('You cannot escape the shadows!', '', 154675, 0, 0, 0, 0, 0, 106587, 0, 0, 0, 0, 0, 0, 0, 28153),
('Extermination!', '', 154674, 0, 0, 0, 0, 0, 106596, 0, 0, 0, 0, 0, 0, 0, 28153),
('Obliteration!', '', 154673, 0, 0, 0, 0, 0, 106595, 0, 0, 0, 0, 0, 0, 0, 28153),
('You cannot resist my call.', '', 154672, 0, 0, 0, 0, 0, 106600, 0, 0, 0, 0, 0, 0, 0, 28153),
('Give yourself to the plague!', '', 154671, 0, 0, 0, 0, 0, 106599, 0, 0, 0, 0, 0, 0, 0, 28153),
('G\'huun will not be stopped...', '', 154670, 0, 0, 0, 0, 0, 106614, 0, 0, 0, 0, 0, 0, 0, 28153),
('The rot consumes all.', '', 154669, 0, 0, 0, 0, 0, 106620, 0, 0, 0, 0, 0, 0, 0, 28153),
