('Cast Shadow Bolt when your other spells are already tormenting your victim.', '', 153795, 0, 0, 0, 0, 0, 104400, 0, 0, 0, 0, 0, 0, 0, 28153),
('', 'After afflicting your target with Agony and Corruption, continue your assault with sinister shadow magic.', 153794, 0, 0, 0, 0, 0, 0, 104399, 0, 0, 0, 0, 0, 0, 28153),
('After afflicting your target with Agony and Corruption, continue your assault with sinister shadow magic.', '', 153793, 0, 0, 0, 0, 0, 104398, 0, 0, 0, 0, 0, 0, 0, 28153),
('Shadows consume you.', '', 153792, 0, 0, 0, 0, 0, 105524, 0, 0, 0, 0, 0, 0, 0, 28153),
('', 'Using Dire Frenzy will also shorten the time before you can use Bestial Wrath again.', 153791, 0, 0, 0, 0, 0, 0, 104379, 0, 0, 0, 0, 0, 0, 28153),
('Using Dire Frenzy will also shorten the time before you can use Bestial Wrath again.', '', 153790, 0, 0, 0, 0, 0, 104378, 0, 0, 0, 0, 0, 0, 0, 28153),
('', 'Your actions will not be tolerated!', 153789, 0, 0, 0, 0, 0, 0, 104516, 0, 0, 0, 0, 0, 0, 28153),
('', 'Use Dire Frenzy while attacking the target dummy.', 153788, 0, 0, 0, 0, 0, 0, 104377, 0, 0, 0, 0, 0, 0, 28153),
('Use Dire Frenzy while attacking the target dummy.', '', 153787, 0, 0, 0, 0, 0, 104376, 0, 0, 0, 0, 0, 0, 0, 28153),
