('', 'No.', 151207, 0, 0, 0, 0, 0, 0, 102415, 0, 0, 0, 0, 0, 0, 28153),
('', 'I say no!', 151206, 0, 0, 0, 0, 0, 0, 102417, 0, 0, 0, 0, 0, 0, 28153),
('', 'Never!', 151205, 0, 0, 0, 0, 0, 0, 102419, 0, 0, 0, 0, 0, 0, 28153),
