(159962, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nHauptmann Samuel Robertson', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nHauptmann Samuel Robertson', 28153),
(159961, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nKorporal Eloise Hesterfeld', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nKorporal Eloise Hesterfeld', 28153),
(159960, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreite Sarah Galgner', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreite Sarah Galgner', 28153),
(159959, 'deDE', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nRüstmeister von Kiefer', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nRüstmeister von Kiefer', 28153),
(159958, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nUnteroffizier J. Müller', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nUnteroffizier J. Müller', 28153),
(159957, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nHauptfeldwebel Murgatroyd Schmidt', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nHauptfeldwebel Murgatroyd Schmidt', 28153),
(159956, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreiter Gottfried Van Houten', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreiter Gottfried Van Houten', 28153),
(159955, 'deDE', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nVersorger Jarrod', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nVersorger Jarrod', 28153),
(159954, 'deDE', 'Habt Ihr Rüstung zu reparieren? Meine Schmiede ist die beste in der ganzen Wüste... Na ja, die einzige in der ganzen Wüste.', 'Habt Ihr Rüstung zu reparieren? Meine Schmiede ist die beste in der ganzen Wüste... Na ja, die einzige in der ganzen Wüste.', 28153),
(159953, 'deDE', 'Die See soll Euch verschlingen!', '', 28153),
(159952, 'deDE', '', 'Was können die Kaldorei für Euch tun?', 28153),
(159951, 'deDE', '', 'Weg von den Archiven! Diese Forschung ist nicht für Euch bestimmt!', 28153),
(159950, 'deDE', '', 'Möge Elune Euren Weg erleuchten.', 28153),
(159949, 'deDE', '', 'Verliert nicht den Glauben.', 28153),
(159948, 'deDE', 'Bei all den Blutelfen, die wir mitgebracht haben, sollte man denken, dass auch ein Juwelenschleifer darunter wäre. Die haben diesen Beruf ja praktisch erfunden. Ich glaube, die Zandalari wollen uns einfach nicht an ihre Reichtümer lassen.\n\nWenn Ihr also mehr erfahren wollt, dann müsst Ihr mit Seshuli reden. Ihr findet sie in der Halle der Schimmer. Um dort hinzukommen, geht Ihr zuerst hinunter zur Handwerkerterrasse im Westen von Dazar\'alor. Dreht Euch dann zur Pyramide und geht in einen der Tunnel. Dort werdet Ihr sie finden.', 'Bei all den Blutelfen, die wir mitgebracht haben, sollte man denken, dass auch ein Juwelenschleifer darunter wäre. Die haben diesen Beruf ja praktisch erfunden. Ich glaube, die Zandalari wollen uns einfach nicht an ihre Reichtümer lassen.\n\nWenn Ihr also mehr erfahren wollt, dann müsst Ihr mit Seshuli reden. Ihr findet sie in der Halle der Schimmer. Um dort hinzukommen, geht Ihr zuerst hinunter zur Handwerkerterrasse im Westen von Dazar\'alor. Dreht Euch dann zur Pyramide und geht in einen der Tunnel. Dort werdet Ihr sie finden.', 28153),
(159947, 'deDE', 'Wenn Ihr nach jemandem sucht, der Euch in die tieferen Geheimnisse der Inschriftenkunde einweihen kann, dann geht zum Großen Siegel.\n\nWenn Ihr dort seid, geht die Treppen im Osten hoch, dann kommt Ihr zur Halle der Chronisten. Haltet Ausschau nach Chronistin Kizani.', 'Wenn Ihr nach jemandem sucht, der Euch in die tieferen Geheimnisse der Inschriftenkunde einweihen kann, dann geht zum Großen Siegel.\n\nWenn Ihr dort seid, geht die Treppen im Osten hoch, dann kommt Ihr zur Halle der Chronisten. Haltet Ausschau nach Chronistin Kizani.', 28153),
(159946, 'deDE', 'Kräuterkunde, hm? Mal sehen. Ja, ich kenne da jemanden. Er heißt Jahden Fla und kümmert sich gerade um seinen Garten auf der Handwerkerterrasse auf der unteren Westseite von Dazar\'alor.', 'Kräuterkunde, hm? Mal sehen. Ja, ich kenne da jemanden. Er heißt Jahden Fla und kümmert sich gerade um seinen Garten auf der Handwerkerterrasse auf der unteren Westseite von Dazar\'alor.', 28153),
(159945, 'deDE', '', 'Wir sind die Kinder von Elune.', 28153),
(159944, 'deDE', '', 'Ishnu-alah.', 28153),
(159943, 'deDE', '', 'Die Göttin gibt mir Kraft.', 28153),
(159942, 'deDE', 'Es gibt eine Zandalari unten an der Spanne im Norden von Dazar\'alor. Ihr Name ist Tali die Schweigsame und man sagt, dass sie alles angeln kann, egal wie groß und wie verborgen es auch sein mag.\n\nSie ist aber nicht sehr gesprächig, wie ihr Name schon sagt. Ihr müsst schon selbst herausfinden, wie gut sie ist.', 'Es gibt eine Zandalari unten an der Spanne im Norden von Dazar\'alor. Ihr Name ist Tali die Schweigsame und man sagt, dass sie alles angeln kann, egal wie groß und wie verborgen es auch sein mag.\n\nSie ist aber nicht sehr gesprächig, wie ihr Name schon sagt. Ihr müsst schon selbst herausfinden, wie gut sie ist.', 28153),
(159941, 'deDE', 'Rührt Euch.', 'Rührt Euch.', 28153),
(159940, 'deDE', 'Nicht schnell genug. Übt weiter!', 'Nicht schnell genug. Übt weiter!', 28153),
(159939, 'deDE', 'Augen auf! Was Ihr nicht seht, könnt Ihr nicht erschießen!', 'Augen auf! Was Ihr nicht seht, könnt Ihr nicht erschießen!', 28153),
(159938, 'deDE', 'Total schlampig! Wir üben das jetzt so lange, bis Ihr das richtig macht!', 'Total schlampig! Wir üben das jetzt so lange, bis Ihr das richtig macht!', 28153),
(159937, 'deDE', 'Ihr habt Eure Munition fallengelassen, Kelada! <seufz> Macht es nächstes Mal richtig!', 'Ihr habt Eure Munition fallengelassen, Kelada! <seufz> Macht es nächstes Mal richtig!', 28153),
(159936, 'deDE', 'Wann habt Ihr zuletzt Eure Waffe gereinigt, Gefreiter? Könnt Ihr es nicht selbst?', 'Wann habt Ihr zuletzt Eure Waffe gereinigt, Gefreiter? Könnt Ihr es nicht selbst?', 28153),
(159935, 'deDE', 'Präsentiert das GEWEHR!', 'Präsentiert das GEWEHR!', 28153),
(159934, 'deDE', 'Das Gewehr... ÜBER!', 'Das Gewehr... ÜBER!', 28153),
(159933, 'deDE', 'Kein Wunder, dass Aschenwinds eigene Leute sich geweigert haben. Der Ort ist das Grauen!', '', 28153),
(159932, 'deDE', 'Ihr da! Habt Ihr mal gesehen, was die können? Die jagen im Rudel. Sie verfolgen ihr Opfer, lenken es ab und setzen dann zum tödlichen Schlag an. Kleine, böse Kreaturen. Aber ich habe hier das Sagen und das wissen sie! Wollt Ihr sehen, wie sich Eure kleinen Tiere gegen meine schlagen?', '', 28153),
(159931, 'deDE', '$n knabbert etwas Popcorn.', '$n knabbert etwas Popcorn.', 28153),
(159930, 'deDE', 'Jepp, Shuga Sprengkapp findet Ihr auf der Handwerkerterrasse. Sie ist sicher bei ihrem Freund Myxle auf der Westseite von Dazar\'alor am Fuß der Pyramide.\n\nWas wollt Ihr denn in die Luft jagen?', 'Jepp, Shuga Sprengkapp findet Ihr auf der Handwerkerterrasse. Sie ist sicher bei ihrem Freund Myxle auf der Westseite von Dazar\'alor am Fuß der Pyramide.\n\nWas wollt Ihr denn in die Luft jagen?', 28153),
(159929, 'deDE', 'Oh... nicht gut. Gar nicht gut... Sie haben sie nach Schicksalsend verschifft.', '', 28153),
(159928, 'deDE', 'Ah, da haben wir\'s ja.', '', 28153),
(159927, 'deDE', 'Genug Beweise, um ihn lebenslang einzulochen. Aber darüber muss er sich wohl keinen Kopf mehr machen.', '', 28153),
(159926, 'deDE', 'Die Blutelfenverzauberin Quinni ist mit uns hergekommen. Hört genau zu. Ihr findet sie an der westlichen Basis von Dazar\'alor bei der Handwerkerterrasse. Dreht Euch, sobald Ihr dort seid, zur Pyramide und sucht einen Weg nach unten. Es gibt dort einen Tunnel, der Euch zur so genannten Halle der Schimmer führt.\n\nWenn Ihr mich fragt, sind wirklich eine Menge Blutelfen mitgekommen. Das macht einen doch misstrauisch...', 'Die Blutelfenverzauberin Quinni ist mit uns hergekommen. Hört genau zu. Ihr findet sie an der westlichen Basis von Dazar\'alor bei der Handwerkerterrasse. Dreht Euch, sobald Ihr dort seid, zur Pyramide und sucht einen Weg nach unten. Es gibt dort einen Tunnel, der Euch zur so genannten Halle der Schimmer führt.\n\nWenn Ihr mich fragt, sind wirklich eine Menge Blutelfen mitgekommen. Das macht einen doch misstrauisch...', 28153),
(159925, 'deDE', 'Gold, Juwelen, Schatzkarten, Lösegeldbriefe... Heiliger Dietrich, Harlan war ein böser, böser Bube.', '', 28153),
(159924, 'deDE', 'Ich muss zugeben, ich bewundere Eure Arbeitseinstellung. Gute Leistung.', '', 28153),
(159923, 'deDE', '', 'Das ist für gewöhnlich ein gutes Zeichen. Was ist drin?', 28153),
(159922, 'deDE', 'Ha, was sagt man dazu... sie ist nicht hochgegangen!', '', 28153),
(159921, 'deDE', 'Diese Bilgewasserbande muss die Ranishu ständig füttern, um ihre Mechs mit Energie zu versorgen. Helft den Goblins. Denn je schneller sie fertig sind, desto eher verschwinden sie.', '', 28153),
(159920, 'deDE', 'Ein Schloss noch. Hoffen wir, dass da keine Sprengfalle dran ist.', '', 28153),
(159919, 'deDE', 'Na dann lasst uns die Kassette mal knacken.', '', 28153),
(159918, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nKapitän Ellis R. Ladimoor\n\nKapitän der Klafterläufer', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nKapitän Ellis R. Ladimoor\n\nKapitän der Klafterläufer', 28153),
(159917, 'deDE', 'Präsentiert... das Gewehr!', 'Präsentiert... das Gewehr!', 28153),
(159916, 'deDE', 'Das Königshaus der Zandalari hat uns seine Köchin ausgeliehen. Sie heißt T\'sarah. Ihr findet sie im Großen Siegel, die Treppe hoch an der Westseite.\n\nIch weiß aber nicht, ob sie wirklich gut kocht. Ich esse nämlich nichts Gekochtes.', 'Das Königshaus der Zandalari hat uns seine Köchin ausgeliehen. Sie heißt T\'sarah. Ihr findet sie im Großen Siegel, die Treppe hoch an der Westseite.\n\nIch weiß aber nicht, ob sie wirklich gut kocht. Ich esse nämlich nichts Gekochtes.', 28153),
(159915, 'deDE', 'Unten auf der unteren Westseite von Dazar\'alor findet Ihr die Handwerkerterrasse. Dort gibt es einen riesigen Terrortroll der Zandalari namens Schmiedemeister Zack-irgendwas, der auf einem Amboss herumhämmert. Glaubt mir, er ist nicht zu übersehen.', 'Unten auf der unteren Westseite von Dazar\'alor findet Ihr die Handwerkerterrasse. Dort gibt es einen riesigen Terrortroll der Zandalari namens Schmiedemeister Zack-irgendwas, der auf einem Amboss herumhämmert. Glaubt mir, er ist nicht zu übersehen.', 28153),
(159914, 'deDE', 'Wir haben Forscherin Alerinda mitgebracht. Sie ist im Großen Siegel in einem Raum an der Westseite.\n\nIch glaube, ihre Leute graben weit im Südwesten gerade einen riesigen Dinosaurier aus. Ihr solltet mal schauen, ob Ihr helfen könnt.', 'Wir haben Forscherin Alerinda mitgebracht. Sie ist im Großen Siegel in einem Raum an der Westseite.\n\nIch glaube, ihre Leute graben weit im Südwesten gerade einen riesigen Dinosaurier aus. Ihr solltet mal schauen, ob Ihr helfen könnt.', 28153),
(159913, 'deDE', 'Scharfschützen! Angetreten!', 'Scharfschützen! Angetreten!', 28153),
(159912, 'deDE', '', 'Wir sind beide froh, dass Ihr wohlbehalten zurück seid.', 28153),
(159911, 'deDE', '', 'Wie bitte? Ich war nicht diejenige, die... <seufz>', 28153),
(159910, 'deDE', 'Ah, da ist ja unser wackerer Champion! Wusste doch, das alles gutgeht. Taelia hat sich Sorgen gemacht.', '', 28153),
(159909, 'deDE', '', 'Immer wenn meine Familie in diese Hügel geht, mache ich mir Sorgen.', 28153),
(159908, 'deDE', 'Hey! Passt auf, wo Ihr die Dinger hinwerft!', '', 28153),
(159907, 'deDE', '', 'Wir haben noch Granaten, $n! Nutzt sie!', 28153),
(159906, 'deDE', 'Ihr sucht Kumali die Kluge. Sie ist auf der Handwerkerterrasse im Westen von Dazar\'alor ganz unten.\n\nAber seid vorsichtig. Sie sieht nach einer der Gestalten aus, die die Dunkelspeere meinen, wenn sie immer vor unheimlichem Voodookram warnen.', 'Ihr sucht Kumali die Kluge. Sie ist auf der Handwerkerterrasse im Westen von Dazar\'alor ganz unten.\n\nAber seid vorsichtig. Sie sieht nach einer der Gestalten aus, die die Dunkelspeere meinen, wenn sie immer vor unheimlichem Voodookram warnen.', 28153),
(159905, 'deDE', 'Sagt\'s mir, wenn sich hier irgendwer verdächtig benimmt. Dann werd ich die Wahrheit aus ihm rausprügeln.', '', 28153),
(159904, 'deDE', 'Dieser Tresor wird von Lok dem Block bewacht. Da klaut keiner was raus!', '', 28153),
(159903, 'deDE', '...Wenn das vorbei ist, müssen wir beide uns mal über unsere gemeinsamen Interessen unterhalten.', '', 28153),
(159902, 'deDE', '', 'Jetzt kommt mein Lieblingsteil!', 28153),
(159901, 'deDE', 'Jetzt kommt mein Lieblingsteil.', '', 28153),
(159900, 'deDE', 'Wir werden unversehrt zurückkehren... und der Gefangene auch.', '', 28153),
(159899, 'deDE', 'Schätze gibt\'s offenbar in allen Formen un\' Größ\'n. Ich bin jedes Mal erstaunt, was die Leute so alles in Tresore pack\'n.', '', 28153),
(159898, 'deDE', '', 'Ich verstehe.', 28153),
(159897, 'deDE', 'Macht Euch keine Sorg\'n um Eure Wertsach\'n, $p.\n\nIch hab schon auf Schätze von König\'n, Warenlager von Händlern, Schmuckstücke von Wahnsinnig\'n un\' das Mittagessen von Kastenlos\'n aufgepasst.\n\nGanz gleich, was es is\', bei mir is\' es sicher.', '', 28153),
(159896, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nStabsfeldwebel Alison Feuerstein', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nStabsfeldwebel Alison Feuerstein', 28153),
(159895, 'deDE', 'Die letzte Bande, die dies\'n Tresor ausrauben wollte, is\' jetzt drauß\'n in Vol\'dun... Genau wie alle andren, die\'s versucht hab\'n.', '', 28153),
(159894, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nKorporal Jonas Kiefer', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nKorporal Jonas Kiefer', 28153),
(159893, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreite Lorelei Schleifstein', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreite Lorelei Schleifstein', 28153),
(159892, 'deDE', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreiter Jakob Simons', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nGefreiter Jakob Simons', 28153),
(159891, 'deDE', 'Das is\' der sicherste Tresor in Zandalar. Ohne meine Erlaubnis geht da nix rein oder raus.\n\nLasst Ihr Eure Sach\'n hier, könnt Ihr beruhigt schlaf\'n. So einfach is\' das.', '', 28153),
(159890, 'deDE', 'Ich nehm meine Arbeit als Tresorwache ernst, $p.\n\nHabt Ihr gute Absicht\'n, hab ich auch gute Absicht\'n.\n\nHabt Ihr schlechte Absicht\'n, stopf ich Euren ganz\'n Körper in \'ne winzige Kiste, verschick Euch nach Vol\'dun und lass Euch an die Geier der Sethrak verfüttern.\n\nAlles klar?', '', 28153),
(159889, 'deDE', 'Ich habe eine Vereinbarung mit den Zandalari. Sie lassen mich bleiben und werden dafür zu meiner Party eingeladen.', '', 28153),
(159888, 'deDE', 'In Zandalar müsst Ihr als jemand von der Allianz gut auf Euch achtgeben.\n\nWerdet Ihr gesehen, werden die Wachen und Götter bestimmt angreifen.', '', 28153),
(159887, 'deDE', 'Wir sind beide weit weg von unserem Zuhause. Lasst uns bleiben und auf dem Großen Basar etwas trinken gehen.', '', 28153),
(159886, 'deDE', '', 'Astarii, schnell! Evakuiert die Stadt... bevor sie niederbrennt...', 28153),
(159885, 'deDE', 'Ja, sicher. Wenn Ihr Hilfe von Experten eines Berufs sucht, werdet Ihr auf der Handwerkerterrasse unten an der unteren Westseite von Dazar\'alor fündig.\n\nWas wollt Ihr denn trainieren?', 'Ja, sicher. Wenn Ihr Hilfe von Experten eines Berufs sucht, werdet Ihr auf der Handwerkerterrasse unten an der unteren Westseite von Dazar\'alor fündig.\n\nWas wollt Ihr denn trainieren?', 28153),
(159884, 'deDE', 'Ein Saurolisk hat den Wagen umgekippt und die Vorräte überall verteilt.', '', 28153),
(159883, 'deDE', '', 'Genn wird vielleicht der \"Alte Wolf\" genannt, aber bei mir schnurrt er wie eine Kätzchen.', 28153),
(159882, 'deDE', '', 'Die Nachtelfen retteten einst mein Volk. Ich werde alles für sie tun, was in meiner Macht steht.', 28153),
(159881, 'deDE', 'Ich bleibe hier und kümmere mich um die Pferde.', '', 28153),
(159880, 'deDE', '', 'Die Kaldorei brauchen unsere Hilfe.', 28153),
(159879, 'deDE', '', 'Die Zeit drängt.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159878, 'deDE', '', 'Ich danke Euch! Ich glaube, ich finde jetzt selbst zurück.', 28153),
(159877, 'deDE', '', 'Lasst sie dafür büßen, Champion.', 28153),
(159876, 'deDE', '', 'So viel unschuldiges Blut...', 28153),
(159875, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(159874, 'deDE', 'Die Hässlichkeit in Person da gehört mir!', 'Die Hässlichkeit in Person da gehört mir!', 28153),
(159873, 'deDE', 'Keine Gefangenen!', 'Keine Gefangenen!', 28153),
(159872, 'deDE', 'Das hier ist Eigentum der Allianz! Weg mit Euch!', 'Das hier ist Eigentum der Allianz! Weg mit Euch!', 28153),
(159871, 'deDE', 'Ihr habt einen Fehler gemacht, Hordenabschaum!', 'Ihr habt einen Fehler gemacht, Hordenabschaum!', 28153),
(159870, 'deDE', '', 'Rettet so viele Ihr könnt!', 28153),
(159869, 'deDE', '', 'Die Schuldigen werden für ihre Verbrechen bezahlen.', 28153),
(159868, 'deDE', 'Wenn hier alles erledigt ist, werden wir dort zu Euch stoßen, um bei der Einsatznachbesprechung zu assistieren.', '', 28153),
(159867, 'deDE', '', 'Für die Allianz.', 28153),
(159866, 'deDE', '', 'Meine Heimat ruft nach mir.', 28153),
(159865, 'deDE', '', 'Danke für Eure Dienste.', 28153),
(159864, 'deDE', '', 'Kann ich Euch behilflich sein?', 28153),
(159863, 'deDE', '', 'Ein Königreich ist kein Ort, sondern ein Volk.', 28153),
(159862, 'deDE', '', 'Gilneas ehrt Euch für Euren Dienst.', 28153),
(159861, 'deDE', '', 'Grüße, Champion.', 28153),
(159860, 'deDE', 'Messer. Gurgel. Das ist doch gar nicht so schwer.', '', 28153),
(159859, 'deDE', 'Töten ist schon Belohnung genug. Aber zu Gold sage ich nicht nein.', '', 28153),
(159858, 'deDE', '$n, gebt Bescheid, wenn Ihr bereit seid. Dann beginnen wir mit den Vorbereitungen, um das Schiff in die Luft zu jagen. Danach meldet Ihr König Wrynn, dass wir erfolgreich waren.', '', 28153),
(159857, 'deDE', 'Lasst uns den Kriegshäuptling beeindrucken... und uns eine nette Belohnung verdienen.', '', 28153),
(159856, 'deDE', 'Lasst uns diesen Wilden eine Lektion erteilen, was sagt Ihr?', '', 28153),
(159855, 'deDE', 'Keeshan, Kelsey, präpariert das Schiff, damit es explodiert, sobald alle weg sind.', '', 28153),
(159854, 'deDE', 'Lasst uns keine Zeit verschwenden.', '', 28153),
(159853, 'deDE', 'Ein Krieg bietet auch immer viele Chancen.', '', 28153),
(159852, 'deDE', 'Umbric, wir brauchen noch einen letzten Leerenriss, um all unsere Truppen abzutransportieren.', '', 28153),
(159851, 'deDE', 'Das Schiff muss zerstört werden. Shandris, helft unseren verbleibenden Truppen, den Aufbruch vorzubereiten.', '', 28153),
(159848, 'deDE', 'Ich liebe meinen Job.', '', 28153),
(159847, 'deDE', 'Sollen wir loslegen?', '', 28153),
(159845, 'deDE', 'Meine Leute werden mich aus Euren Gefängnissen befreien, genau wie sie es mit Prinzessin Talanji und Zul getan haben!', '', 28153),
(159844, 'deDE', 'Sie können es gern versuchen. Aber nun zu anderen Dingen.', '', 28153),
(159843, 'deDE', 'Ihr könnt Euch entweder weiterhin wehren oder Ihr kooperiert mit uns. Es ist Eure Entscheidung.', '', 28153),
(159842, 'deDE', 'Ich kümmere mich darum.', 'Ich kümmere mich darum.', 28153),
(159841, 'deDE', 'Nein. Heute gab es schon genug Tote, Kapitän. Wir nehmen Euch gefangen und bringen Euch zurück nach Sturmwind.', '', 28153),
(159840, 'deDE', 'Miese Allianzhunde! Bringt es endlich hinter Euch und tötet mich!', '', 28153),
(159839, 'deDE', '', 'Kapitän Zalkran hat versucht, nach Zuldazar zu fliehen, aber Falstad und ich haben ihn überwältigt.', 28153),
(159838, 'deDE', 'Shandris, wie lautet der Lagebericht?', 'Shandris, wie lautet der Lagebericht?', 28153),
(159837, 'deDE', 'Könnt Ihr mich in die Gegenwart zurückbringen?', 'Könnt Ihr mich in die Gegenwart zurückbringen?', 28153),
(159836, 'deDE', 'Könnt Ihr mir zeigen, wie Tirisfal vor der Schlacht um Lordaeron aussah?', 'Könnt Ihr mir zeigen, wie Tirisfal vor der Schlacht um Lordaeron aussah?', 28153),
(159835, 'deDE', '', 'Oh... und wenn Ihr meinen Enkel Karl seht, sorgt dafür, dass er nicht irgendwo unter einem Baum kauert.', 28153),
(159834, 'deDE', 'Habt Ihr schon welche von den Tieren eingefangen, die dieses seltsame Land zu bieten hat? Ich hätte nur allzu gern eine dieser Bluttikimasken, aber was wohl die Einheimischen davon halten würden?\n\nWenn Ihr einen Stallmeister sucht, kenne ich da einen Zandalari namens Bestienzähmer Kalatak nahe der nordwestlichen Basis von Dazar\'alor.', 'Habt Ihr schon welche von den Tieren eingefangen, die dieses seltsame Land zu bieten hat? Ich hätte nur allzu gern eine dieser Bluttikimasken, aber was wohl die Einheimischen davon halten würden?\n\nWenn Ihr einen Stallmeister sucht, kenne ich da einen Zandalari namens Bestienzähmer Kalatak nahe der nordwestlichen Basis von Dazar\'alor.', 28153),
(159833, 'deDE', 'Die Crew der Prinzessin Violetta streikt. Sagten sie nicht etwas davon, die letzten elf Jahre nicht bezahlt worden zu sein? Ich hab nicht richtig hingehört.', 'Die Crew der Prinzessin Violetta streikt. Sagten sie nicht etwas davon, die letzten elf Jahre nicht bezahlt worden zu sein? Ich hab nicht richtig hingehört.', 28153),
(159832, 'deDE', 'Wie komme ich zum Schlingendorntal?', 'Wie komme ich zum Schlingendorntal?', 28153),
(159831, 'deDE', '', 'Champion! Es scheint, dass ich erneut Eurer Hilfe bedarf.', 28153),
(159830, 'deDE', '', 'Ich danke Euch noch einmal, Champion, obwohl es so aussieht, als ob wir noch nicht in Sicherheit sind.', 28153),
(159829, 'deDE', '', 'Ja, Mutter. Ich werde bald mit ihnen zurückkehren.', 28153),
(159828, 'deDE', '', 'Taelia! Ruft die Miliz zusammen. Jaina und ich werden die Verteidigung vorbereiten.', 28153),
(159827, 'deDE', '', '$n! Es scheint, als benötige ich noch einmal Eure Hilfe.', 28153),
(159826, 'deDE', '', 'Priscilla ist zurück, um sich meine Stadt zu holen...', 28153),
(159825, 'deDE', '', 'Oder... kamen wir zu spät?', 28153),
(159824, 'deDE', '', 'Was habt Ihr gefunden? Irgendein Zeichen von Jaina?', 28153),
(159823, 'deDE', '', '$n... Ich sehe, Ihr kehrt allein zurück.', 28153),
(159822, 'deDE', '', 'Der Wagen ist ruiniert, und wir hätten dabei getötet werden können. \n\nDie Bestie, die uns angegriffen hat, ist in dieser Höhle. Ich werde nicht gehen, bevor sie tot ist!', 28153),
(159821, 'deDE', '', 'Lordadmiralin! Schiffe am Horizont! Sie segeln unter der Flagge von Aschenwind!', 28153),
(159820, 'deDE', '', 'Mutter... Ich...', 28153),
(159819, 'deDE', '', 'Mal sehen, ob ich es diesmal richtig machen kann... Willkommen daheim, meine Tochter.', 28153),
(159818, 'deDE', '', 'Es tut gut, wieder frische Seeluft zu atmen. Ich danke Euch, $n. Ohne Euch wäre mir das vielleicht nie wieder vergönnt gewesen...', 28153),
(159817, 'deDE', 'Seid gegrüßt, $gInquisitor:Inquisitorin;!\n\nLady Kronsteig hat mich angewiesen, meinen schnellsten Falken für Euch bereitzuhalten, damit er eine Botschaft für Euch überbringt.', '', 28153),
(159816, 'deDE', 'Schickt eine Botschaft zu Katherine Prachtmeer, mich bei Gol Inath zu treffen.', 'Schickt eine Botschaft zu Katherine Prachtmeer, mich bei Gol Inath zu treffen.', 28153),
(159815, 'deDE', 'Ich suche nach einem Weg in die Verseuchten Lande.', 'Ich suche nach einem Weg in die Verseuchten Lande.', 28153),
(159814, 'deDE', '', 'Schützt sie mit Eurem Leben. Kul Tiras hat schon zu viele Prachtmeers verloren.', 28153),
(159813, 'deDE', '', 'Ihr habt es geschafft! Das Bildnis hat funktioniert!', 28153),
(159812, 'deDE', '', 'Das ist es! Die Markierungen an der Wand zeigen die Reihenfolge!', 28153),
(159811, 'deDE', '', 'Vielleicht müssen die Runen in einer bestimmten Reihenfolge aktiviert werden...', 28153),
(159810, 'deDE', '', 'Das sah unangenehm aus...', 28153),
(159809, 'deDE', '', 'Versucht, eine weitere zu aktivieren.', 28153),
(159808, 'deDE', '', 'Es ist verschwunden! Dienen diese Runen vielleicht als eine Art Zauberschutz?', 28153),
(159807, 'deDE', '', 'Also... es muss doch hier drin ein paar Hinweise geben, wie das funktioniert.', 28153),
(159806, 'deDE', '', 'Ah, das hat... etwas bewirkt...', 28153),
(159805, 'deDE', '', 'Das sieht wie eine Art Durchgang aus. Vielleicht sollten wir das Bildnis hier hinstellen.', 28153),
(159804, 'deDE', '', 'Ich muss stark sein. Jaina hat wegen mir weit Schlimmeres erduldet...', 28153),
(159803, 'deDE', '', 'Diese Umgebung lässt meine Seele gefrieren. Als würde man über sein eigenes Grab gehen...', 28153),
(159802, 'deDE', '', 'Es sieht so aus, als wären wir jetzt auf uns gestellt. Nach Euch.', 28153),
(159801, 'deDE', '', 'Diese... Monster im Wald haben meine Wachen angegriffen. Nur dank ihres Opfers habe ich überlebt.', 28153),
(159800, 'deDE', '', '$n! Ihr seid ein willkommener Anblick!', 28153),
(159799, 'deDE', 'Aye! Hannibal hier wird Eure Nachricht in Nullkommanichts zur Burg Prachtmeer bringen.', '', 28153),
(159798, 'deDE', 'Ihr seid jetzt in Sicherheit.', 'Ihr seid jetzt in Sicherheit.', 28153),
(159797, 'deDE', '', 'Ich weiß, dass Katherine vorhat, Euch auf dieser verrückten Suche zu begleiten.', 28153),
(159796, 'deDE', 'Dieser unheimliche Nachtgeborene, Oculeth, hat Portale nach Orgrimmar, Silbermond und Donnerfels für uns geöffnet. Ihr findet sie in der Halle der Uralten Pfade auf der Ostseite im Großen Siegel.\n\nEin Portal nach Unterstadt gibt es leider nicht. Doch schon bald werden wir uns an diesem Allianzabschaum rächen! Genn, Jaina und König Anduin werden für ihre Verbrechen bezahlen!\n\nMöge Sylvanas siegen! Möge sie noch für Jahrtausende als Kriegshäuptling herrschen!', 'Dieser unheimliche Nachtgeborene, Oculeth, hat Portale nach Orgrimmar, Silbermond und Donnerfels für uns geöffnet. Ihr findet sie in der Halle der Uralten Pfade auf der Ostseite im Großen Siegel.\n\nEin Portal nach Unterstadt gibt es leider nicht. Doch schon bald werden wir uns an diesem Allianzabschaum rächen! Genn, Jaina und König Anduin werden für ihre Verbrechen bezahlen!\n\nMöge Sylvanas siegen! Möge sie noch für Jahrtausende als Kriegshäuptling herrschen!', 28153),
(159795, 'deDE', 'Der Weg nach Thros wird gefährlich, doch das ist nur ein Bruchteil dessen, was Euch in den Verseuchten Landen erwartet.\n\nMacht Euch bereit, $C, denn die Diener von Thros werden Eure innersten Ängste und alles, was Ihr bedauert, gegen Euch einsetzen.', '', 28153),
(159794, 'deDE', 'Der Eingang nach Thros befindet sich in dem großen Baum Gol Inath, aber die Schwelle zu übertreten ist kein Leichtes. Man geht nicht einfach so hinein.\n\nUm den Weg zu öffnen, braucht Ihr ein sehr starkes Bildnis. Damit meine ich nicht den Plunder des Zirkels, sondern eins von alter Drustmagie.', '', 28153),
(159793, 'deDE', '', 'Der Wagen ist umgekippt. Es war furchtbar!\n\nIch war auf dem Weg zurück in die Stadt, um Hilfe zu holen, aber dann bekam ich Angst.', 28153),
(159792, 'deDE', 'Ah, es tut gut, noch einen Anhänger des Wegs zu sehen.\n\nWas wollt Ihr von den Dornsprechern?', '', 28153),
(159791, 'deDE', 'Der Besuch vom Festland kehrt also zurück?\n\nIch denke, unsere Schuld ist getilgt. Seid Ihr gekommen, um weitere Gefallen von den Dornsprechern zu erbitten?', '', 28153),
(159790, 'deDE', 'Es ist lange her, seit ein Festländer seinen Fuß in meinen Hain gesetzt hat.\n\nMöchtet Ihr von den Dornsprechern lernen oder seid Ihr gekommen, um Anspruch auf dieses Land zu erheben, wie es Euresgleichen so gerne tut?', '', 28153),
(159789, 'deDE', 'Das... ändert die Dinge.', '', 28153),
(159788, 'deDE', 'Anscheinend habe ich mich geirrt. Thros ist zu uns gekommen.', '', 28153),
(159787, 'deDE', 'Das ist noch lange nicht vorbei, alter Bär.', '', 28153),
(159786, 'deDE', 'Ich werde dafür sorgen, dass sie in Sicherheit sind.', 'Ich werde dafür sorgen, dass sie in Sicherheit sind.', 28153),
(159785, 'deDE', 'Wer seid Ihr, zu urteilen, wer würdig ist? Eure abscheuliche Magie hat unser Volk besudelt, Tul!', '', 28153),
(159784, 'deDE', 'Ulfar, Ihr wollt unsere Gaben mit diesen Schuften teilen? Ihr verdient es, mit ihnen zu brennen!', '', 28153),
(159783, 'deDE', 'Wie komme ich zum Heulenden Fjord?', 'Wie komme ich zum Heulenden Fjord?', 28153),
(159782, 'deDE', 'Dornsprecher, zu den Waffen!', '', 28153),
(159781, 'deDE', 'Wir haben irgendwo über dem Großen Meer den Kontakt zur Wolkenkuss verloren. Sie sollte einen Rekord mit achthundertfünfzehn Flügen ohne Nachtanken aufstellen! Sicher ist alles in Ordnung.', 'Wir haben irgendwo über dem Großen Meer den Kontakt zur Wolkenkuss verloren. Sie sollte einen Rekord mit achthundertfünfzehn Flügen ohne Nachtanken aufstellen! Sicher ist alles in Ordnung.', 28153),
(159780, 'deDE', 'Gorak Tul! Das kann nicht sein!', '', 28153),
(159779, 'deDE', 'Oh, das soll Euch nicht länger sorgen, alter Bär.', '', 28153),
(159778, 'deDE', 'Manche Wege sollten verschlossen bleiben, damit jene auf der anderen Seite sie nicht betreten.', '', 28153),
(159777, 'deDE', 'Ich fürchte, dabei kann ich Euch nicht helfen, $gFestländer:Festländerin;.', '', 28153),
(159776, 'deDE', 'Ihr möchtet Thros betreten? Ich fürchte, da kann ich Euch nicht helfen, Festländer.', '', 28153),
(159775, 'deDE', '', 'Ihr zieht doch nicht ernsthaft in Erwägung, in die Verseuchten Lande zu gehen, oder?', 28153),
(159774, 'deDE', '', '$uInquisitor:Inquisitorin;! Ich habe eine Botschaft von Katherine!', 28153),
(159773, 'deDE', '', 'Ich war diejenige, die dieses Schicksal über sie gebracht hat. Und ich werde dort sein, um es wiedergutzumachen.', 28153),
(159772, 'deDE', '', 'Falls... WENN Ihr Jaina findet, will ich dabei sein. Ich werde mich dafür jeder Gefahr stellen.', 28153),
(159771, 'deDE', '', 'Eine Sache noch, $n...', 28153),
(159770, 'deDE', 'Ein Saurolisk hat die Pferde scheu gemacht, sodass der Wagen gekippt ist und wir unsere Vorräte verloren haben.\n\nMeine beiden Mädchen, Loreen und Mallorie, sind noch immer da draußen. Sie könnten Eure Hilfe gebrauchen.', '', 28153),
(159769, 'deDE', 'Genau da will ich mit ein paar der anderen nach Schichtende auch hin. Wir müssen schließlich fit bleiben.\n\nGeht zur Königlichen Waffenkammer auf der Nordseite von Dazar\'alor am Fuße der Pyramide. Schließt Euch uns doch an.', 'Genau da will ich mit ein paar der anderen nach Schichtende auch hin. Wir müssen schließlich fit bleiben.\n\nGeht zur Königlichen Waffenkammer auf der Nordseite von Dazar\'alor am Fuße der Pyramide. Schließt Euch uns doch an.', 28153),
(159768, 'deDE', '', 'Geht zu Bruder Pike! Er ist noch immer ein loyaler und frommer Gezeitenweiser. Er wird uns helfen.', 28153),
(159767, 'deDE', '', 'Aschenwind handelte schließlich in meinem Namen.', 28153),
(159766, 'deDE', '', 'Nur Gezeitenweise können Schicksalsend sicher anlaufen. Aschenwind konnte sie bestimmt mühelos davon überzeugen, Jaina dorthin zu bringen.', 28153),
(159765, 'deDE', '', 'Sagt mir, dass es nicht zu spät ist.', 28153),
(159764, 'deDE', '', 'Wohin wurde Jaina verschleppt?', 28153),
(159763, 'deDE', 'Ja, ich auch.', '', 28153),
(159762, 'deDE', '', 'Finn, Ihr wisst, was ich meine. Um Lady Katherines Willen bete ich, dass Ihr falsch liegt.', 28153),
(159761, 'deDE', 'Jetzt schließen wir schon Wetten ab? Schämt Euch! Was würde Carsten sagen?', '', 28153),
(159760, 'deDE', 'Ihr habt wohl etwas mit den Dunkelspeeren zu regeln, was? Ihr wisst, dass das Schiff zu den Echoinseln segelt, ja? Oder wollt Ihr nur einen kleinen Ausflug machen, bevor es zurück nach Orgrimmar geht?\n\nGeht einfach im Hafen von Zandalar die Docks Richtung Süden runter.', 'Ihr habt wohl etwas mit den Dunkelspeeren zu regeln, was? Ihr wisst, dass das Schiff zu den Echoinseln segelt, ja? Oder wollt Ihr nur einen kleinen Ausflug machen, bevor es zurück nach Orgrimmar geht?\n\nGeht einfach im Hafen von Zandalar die Docks Richtung Süden runter.', 28153),
(159759, 'deDE', '', 'Also, wenn sie jemand zurückholen kann, dann $n. Wetten?', 28153),
(159758, 'deDE', 'Diese Insel heißt Schicksalsend, Taelia. Nicht Schicksalshoffnung.', '', 28153),
(159757, 'deDE', 'Gute Arbeit. Formieren wir uns neu.', '', 28153),
(159756, 'deDE', 'Ich kann Euch runter zur Klagelied bringen, $p. Aber haltet Euch lieber gut fest!', '', 28153),
(159755, 'deDE', 'Wildhämmer, verteilt Euch und haltet den Himmel frei, aber vermeidet tunlichst, dabei entdeckt zu werden.', '', 28153),
(159750, 'deDE', '', 'Ha... der Käpt\'n... wird... Euch alle töt\'n...', 28153),
(159749, 'deDE', '', 'Ihr seid zu spät! Der Käpt\'n meldet Eure Position bereits Prinzessin Talanji.', 28153),
(159748, 'deDE', 'Ich weiß genau den richtigen Goblin für Euch. Sein Name ist Myxle Schraubenruck. Ihr findet ihn und seinen Schreddermeister Mk1 auf der Handwerkerterrasse unten im Westen von Dazar\'alor.\n\nEr behauptet, dass sein Gerät jeden Eurer Ausrüstungsgegenstände in seine Einzelteile zerlegen kann, damit Ihr sie wiederverwenden oder verkaufen könnt. Das wäre auch mir sehr gelegen gekommen, aber das hier ist Rüstung der Horde.', 'Ich weiß genau den richtigen Goblin für Euch. Sein Name ist Myxle Bauchschlitz. Ihr findet ihn und seine Schrott-o-matik 1000 auf der Handwerkerterrasse unten im Westen von Dazar\'alor.\n\nEr behauptet, dass sein Gerät jeden Eurer Ausrüstungsgegenstände in seine Einzelteile zerlegen kann, damit Ihr sie wiederverwenden oder verkaufen könnt. Das wäre auch mir sehr gelegen gekommen, aber das hier ist Rüstung der Horde.', 28153),
(159747, 'deDE', 'Um hinauf zum Goldenen Thron zu gelangen, müsst Ihr die Aufzüge im Großen Siegel nehmen.\n\nUnd? Wie steht Ihr zum Adel? Was haltet Ihr von diesem Kopfschmuck? Da sind starke Hälse gefragt!', 'Um hinauf zum Goldenen Thron zu gelangen, müsst Ihr die Aufzüge im Großen Siegel nehmen.\n\nUnd? Wie steht Ihr zum Adel? Was haltet Ihr von diesem Kopfschmuck? Da sind starke Hälse gefragt!', 28153),
(159746, 'deDE', 'Riesig ist dieser Ort, das muss man ihnen lassen. Ich kenne da ein paar Adressen, falls Ihr etwas Interessantes sucht.', 'Riesig ist dieser Ort, das muss man ihnen lassen. Ich kenne da ein paar Adressen, falls Ihr etwas Interessantes sucht.', 28153),
(159745, 'deDE', 'Brillin die Liebreizende findet Ihr in der Mitte des Großen Siegels. Ist sie nicht eine göttliche Tänzerin?', 'Brillin die Liebreizende findet Ihr in der Mitte des Großen Siegels. Ist sie nicht eine göttliche Tänzerin?', 28153),
(159744, 'deDE', 'Es gibt da eine Zandalari namens Paku\'ai, die Flüge arrangiert. Wenn Ihr einen Pterrordax braucht, findet Ihr sie auf der Terrasse an der Ostseite des Großen Siegels.', 'Es gibt da eine Zandalari namens Paku\'ai, die Flüge arrangiert. Wenn Ihr einen Pterrordax braucht, findet Ihr sie auf der Terrasse an der Ostseite des Großen Siegels.', 28153),
(159743, 'deDE', 'Das kommt wohl darauf an, welchen Abgesandten Ihr sucht, $n.', 'Das kommt wohl darauf an, welchen Abgesandten Ihr sucht, $n.', 28153),
(159742, 'deDE', 'Ihr wollt Euch gut mit den Zandalari stellen? Das ist klug. Genau so will es der Kriegshäuptling.\n\nIhren Abgesandten Natal\'hakata findet Ihr im Großen Siegel.', 'Ihr wollt Euch gut mit den Zandalari stellen? Das ist klug. Genau so will es der Kriegshäuptling.\n\nIhren Abgesandten Natal\'hakata findet Ihr im Großen Siegel.', 28153),
(159741, 'deDE', 'Den Tortollanern Geheimnisse entlocken? Es heißt, dass sie eine Ewigkeit leben. Nicht ganz so lange wie ich, aber dennoch für eine lange Zeit.\n\nJedenfalls müsst Ihr den ganzen Weg bis zum Schuppenhandelsposten nordöstlich von Dazar\'alor zurücklegen. Sucht dort nach Sammler Kojo.', 'Den Tortollanern Geheimnisse entlocken? Es heißt, dass sie eine Ewigkeit leben. Nicht ganz so lange wie ich, aber dennoch für eine lange Zeit.\n\nJedenfalls müsst Ihr den ganzen Weg bis zum Schuppenhandelsposten nordöstlich von Dazar\'alor zurücklegen. Sucht dort nach Sammler Kojo.', 28153),
(159740, 'deDE', 'Ah, sicher. Ein anderer Stil. Oder vielleicht eine neue Farbe? Dann schaut bei Conner Schnurrschnitt im Großen Basar am Hafen vorbei.', 'Ah, sicher. Ein anderer Stil. Oder vielleicht eine neue Farbe? Dann schaut bei Conner Schnurrschnitt im Großen Basar am Hafen vorbei.', 28153),
(159739, 'deDE', 'Warum darf ich eigentlich auf Greifen nie vorne sitzen?', '', 28153),
(159738, 'deDE', 'Nicht zu tief! Nicht zu tief!', '', 28153),
(159737, 'deDE', '', 'Ich versuche, sie im Tiefflug abzuhängen! Abwärts, Sturmherz!', 28153),
(159736, 'deDE', 'Ist ja nicht so, als könnte ich irgendwas anderes tun!', '', 28153),
(159735, 'deDE', '', 'Sie schießen auf uns! Festhalten!', 28153),
(159734, 'deDE', 'Die Königliche Schatzkammer befindet sich in der Pyramide auf der Westseite des Großen Siegels. Wir wollten sie mit Goblins besetzen, aber die Zandalari weigerten sich.\n\nSie sind ganz schön clever.', 'Die Königliche Schatzkammer befindet sich in der Pyramide auf der Westseite des Großen Siegels. Wir wollten sie mit Goblins besetzen, aber die Zandalari weigerten sich.\n\nSie sind ganz schön clever.', 28153),
(159733, 'deDE', 'Ihr möchtet wohl zu den Echoinseln, was? Aber wieso? Da haus\'n die Dunkelspeere. Sonst gibt\'s da nix. Bleibt lieber in Zandalar. Hier is\' jede Menge los.\n\nNein? Tja, da habt Ihr Glück, denn wir ham denen eins von unsren kleinen Kriegsschiff\'n gelieh\'n. Das liegt am Ende des Docks im Süden im Hafen von Zandalar.', 'Ihr möchtet wohl zu den Echoinseln, was? Aber wieso? Da haus\'n die Dunkelspeere. Sonst gibt\'s da nix. Bleibt lieber in Zandalar. Hier is\' jede Menge los.\n\nNein? Tja, da habt Ihr Glück, denn wir ham denen eins von unsren kleinen Kriegsschiff\'n gelieh\'n. Das liegt am Ende des Docks im Süden im Hafen von Zandalar.', 28153),
(159732, 'deDE', 'Schiff zu den Echoinseln', 'Schiff zu den Echoinseln', 28153),
(159731, 'deDE', 'Vorarbeiter Al\'jibo von den Dunkelspeeren is\' in der Halle der Uralt\'n Pfade auf der Ostseite des Groß\'n Siegels. Ich kann nich\' für ihn bürg\'n, weil er mit der Horde kam. Aber ich bin sicher, dass er Eure Dellen ausbeul\'n un\' Eure Waff\'n schärf\'n kann.\n\nUnd wenn nich\', seid Ihr sowieso bald aufm Weg zu Bwonsamdi.', 'Vorarbeiter Al\'jibo von den Dunkelspeeren is\' in der Halle der Uralt\'n Pfade auf der Ostseite des Groß\'n Siegels. Ich kann nich\' für ihn bürg\'n, weil er mit der Horde kam. Aber ich bin sicher, dass er Eure Dellen ausbeul\'n un\' Eure Waff\'n schärf\'n kann.\n\nUnd wenn nich\', seid Ihr sowieso bald aufm Weg zu Bwonsamdi.', 28153),
(159730, 'deDE', 'Falls Ihr uns noch einmal braucht, dann geht aus dem Boot und setzt ein Signal ab. Ich und Flinkschwinge werden Euch finden.', '', 28153),
(159729, 'deDE', 'Ha! Diesen Teil mag ich am liebsten!', '', 28153),
(159728, 'deDE', 'Also los, Flinkschwinge. Bring uns schön vorsichtig und unentdeckt hinein. Und das, so schnell du kannst.', '', 28153),
(159727, 'deDE', 'Reparaturen', 'Reparaturen', 28153),
(159726, 'deDE', 'Klar habt Ihr Gold zum Ausgeb\'n. Wir sin\' hier schließlich in Zandalar! Nichma\' die Goblins ham mehr Gold als wir.\n\nUn\', was hättet Ihr gern?', 'Klar habt Ihr Gold zum Ausgeb\'n. Wir sin\' hier schließlich in Zandalar! Nichma\' die Goblins ham mehr Gold als wir.\n\nUn\', was hättet Ihr gern?', 28153),
(159725, 'deDE', 'Verkäufer', 'Verkäufer', 28153),
(159724, 'deDE', '', 'Ich werde die Blutschwall auskundschaften und Ihr die Klagelied. Tor ilisar\'thera\'nal!', 28153),
(159723, 'deDE', '', 'Wir sind fast da. Ich kann den üblen Gestank des Untoten riechen.', 28153),
(159722, 'deDE', 'Euer nachtgebor\'ner Elf hat sein Voodoo in der Halle der Uralt\'n Pfade benutzt. Sucht ma\' auf der Ostseite drin im Groß\'n Siegel.\n\nEr hat sich was ausgedacht, um Euch wieder in Eure klein\' Städtchen zurückzubefördern. Wie heiß\'n die nochma\'? Orgrimmar, Silbermond und Donnerfels? Hmpf.', 'Euer nachtgebor\'ner Elf hat sein Voodoo in der Halle der Uralt\'n Pfade benutzt. Sucht ma\' auf der Ostseite drin im Groß\'n Siegel.\n\nEr hat sich was ausgedacht, um Euch wieder in Eure klein\' Städtchen zurückzubefördern. Wie heiß\'n die nochma\'? Orgrimmar, Silbermond und Donnerfels? Hmpf.', 28153),
(159721, 'deDE', 'Portale', 'Portale', 28153),
(159720, 'deDE', 'Wie hat es Euch hierhin verschlagen?', 'Wie hat es Euch hierhin verschlagen?', 28153),
(159719, 'deDE', 'Da haben wir\'s! Die Informationen über Jainas Verbleib sind ganz gewiss hier drin.\n\n<Finn deutet auf die Kassette.>\n\nIhr habt die Schlüssel. Erweist uns die Ehre.', '', 28153),
(159718, 'deDE', '', 'Ihr kommt zu spät!', 28153),
(159717, 'deDE', '', 'Ich hab\'s trotzdem geschafft!', 28153),
(159716, 'deDE', 'Ihr braucht \'n bisschen Übung? Wir hab\'n hier in Dazar\'alor \'ne Menge Trainingsattrappen. Geht einfach rüber in die königliche Waffenkammer.\n\nDie is\' auf der Nordseite von der Pyramide von Dazar\'alor.', 'Ihr braucht \'n bisschen Übung? Wir hab\'n hier in Dazar\'alor \'ne Menge Trainingsattrappen. Geht einfach rüber in die königliche Waffenkammer.\n\nDie is\' auf der Nordseite von der Pyramide von Dazar\'alor.', 28153),
(159715, 'deDE', '<Zenbaro hustet.>', '', 28153),
(159714, 'deDE', 'Trainingsattrappen', 'Trainingsattrappen', 28153),
(159713, 'deDE', '', 'Solltet Ihr wünschen, in das Arathihochland der Gegenwart zurückzukehren, bin ich gern behilflich.', 28153),
(159712, 'deDE', 'Ihr müsst mir den Rücken freihalten, während ich dieses Ritual vollziehe. Es sollte nicht lange dauern.', '', 28153),
(159711, 'deDE', 'Könnt Ihr mich in die Gegenwart zurückbringen?', 'Könnt Ihr mich in die Gegenwart zurückbringen?', 28153),
(159710, 'deDE', '<Gebt Zenbaro die Feldflasche.>', '<Gebt Zenbaro die Feldflasche.>', 28153),
(159709, 'deDE', 'Also gut, $n. Lasst es uns zu Ende bringen!', '', 28153),
(159708, 'deDE', 'Könnt Ihr mir zeigen, wie das Arathihochland aussah, bevor der Krieg ausbrach?', 'Könnt Ihr mir zeigen, wie das Arathihochland aussah, bevor der Krieg ausbrach?', 28153),
(159707, 'deDE', '', 'Ah, Euer Name steht gleich hier! Geht einfach die Treppe hinauf; es ist das Büro ganz am Ende des Korridors. Herr Kampen wird Euch gleich empfangen.', 28153),
(159706, 'deDE', '', 'In diesen Landen tobt der Krieg nach immer wiederkehrendem, uraltem Muster. Die Zeit wird bestimmt durch Zyklen.\n\nTut mir leid. Ich vergesse manchmal, dass Euer Volk so... linear ist.\n\nWie kann ich Euch helfen?', 28153),
(159705, 'deDE', '', 'Bedaure, aber ohne Termin wird niemand vorgelassen. Wachen!', 28153),
(159704, 'deDE', 'Ja, ich habe einen Termin. Sucht nach M. Arbor.', 'Ja, ich habe einen Termin. Sucht nach M. Arbor.', 28153),
(159703, 'deDE', 'Wisst Ihr nicht, wer ich bin? Ich bin $n, Champion der Allianz! Ich möchte Eure Akten einsehen, und zwar sofort!', 'Wisst Ihr nicht, wer ich bin? Ich bin $n, Champion der Allianz! Ich möchte Eure Akten einsehen, und zwar sofort!', 28153),
(159702, 'deDE', 'Ich habe einen Termin bei Eurem Chef. Es ist von äußerster Wichtigkeit, dass ich sofort mit ihm spreche!', 'Ich habe einen Termin bei Eurem Chef. Es ist von äußerster Wichtigkeit, dass ich sofort mit ihm spreche!', 28153),
(159701, 'deDE', '', 'Womit kann ich Euch heute dienen?', 28153),
(159700, 'deDE', '', 'Willkommen in den Amtsstuben der Handelskompanie Aschenwind. Habt Ihr einen Termin?', 28153),
(159699, 'deDE', 'Ah, da seid Ihr ja, $p. Springt auf!', '', 28153),
(159698, 'deDE', 'Aye. Bringen wir es hinter uns.', '', 28153),
(159697, 'deDE', '', 'Dieses Land weist eine bewegte Geschichte auf. Ich muss Euch unbedingt zeigen, wie es war, als das Reich Arathor noch in voller Blüte stand.\n\nHm... Aber das muss wohl vorerst warten.\n\nHabt Ihr Eure Angelegenheiten in der Vergangenheit regeln können, Champion?', 28153),
(159696, 'deDE', 'Das stimmt wohl. Ich mache mir nicht vor, dass dies die beste Lösung ist, aber wir müssen mit dem zurechtkommen, was wir haben.', '', 28153),
(159695, 'deDE', 'Grauenvolle Aufgabe, nicht wahr, Halford? Wenn man bis auf den letzten Zandalari alle an Bord dieses Schiffs töten muss.', '', 28153),
(159694, 'deDE', 'Wenn Ihr bereit seid, mit dem Ritual zu beginnen, legt den Schlüssel des Meeres in die Schlüssel.', '', 28153),
(159693, 'deDE', 'Ich hab mich schon auf Eure Rückkehr gefreut, $n.', '', 28153),
(159692, 'deDE', 'Ich hab mir schon Sorgen gemacht, dass Ihr nich\' wiederkommt.', '', 28153),
(159691, 'deDE', 'Bin ich froh, Euch zu seh\'n, $n. Ich geb zu, ich hätt nich\' gedacht, dass Ihr wiederkommt.', '', 28153),
(159689, 'deDE', 'Also, ich fang ganz von vorn an. \n\nMeine ersten Erinnerung\'n gehör\'n zu den schönst\'n. Damals hab ich mit den Strolch\'n von Zuldazar die Straß\'n unsicher gemacht.\n\nWir ham ganz schön viel ausgefress\'n, aber wir wusst\'n es nich\' besser.\n\nRajin war unser Anführer. Er hat uns \'n Dach überm Kopf gegeb\'n, und wir ham dafür gemacht, was immer er verlangt hat.\n\nUnd das war\'n normalerweise Betrügerei\'n in der Stadt oder Diebstähle aus\'n Schatzkammern vom Loatempel.', '', 28153),
(159688, 'deDE', '', 'Im Eiltempo! Wir befinden uns auf Feindgebiet, nicht in Sturmwind! Wir müssen auf der Stelle das Zeug abladen und die Verwundeten evakuieren!', 28153),
(159687, 'deDE', 'Stell\'n wir uns diese Frage nich\' am Ende alle?\n\n<Zenbaro hustet.>\n\nDie Sande ham mir übel mitgespielt, $n. Mein Ende naht. \n\nMeine Kehle is\' ganz trock\'n von der Wüstenhitze. \n\nIn der Nähe gibt\'s \'ne Quelle. Holt mir \'n bisschen kaltes Wasser, dann erzähl ich Euch meine Geschichte.', '', 28153),
(159686, 'deDE', 'Meint Ihr diesen Goblin un\' sein verrücktes Gerät auf der Handwerkerterrasse? Er sagt, seine Schrott-o-matik 1000 kann alle Ausrüstung in Teile zerleg\'n, um andere Sach\'n draus zu mach\'n.\n\nIhr findet den auf der unt\'ren Westseite von Dazar\'alor.', 'Meint Ihr diesen Goblin un\' sein verrücktes Gerät auf der Handwerkerterrasse? Er sagt, seine Schrott-o-matik 1000 kann alle Ausrüstung in Teile zerleg\'n, um andere Sach\'n draus zu mach\'n.\n\nIhr findet den auf der unt\'ren Westseite von Dazar\'alor.', 28153),
(159685, 'deDE', 'Wer hätt gedacht, dass das mein Schicksal wär? So mutterseelenallein in den Dünen zu verreck\'n?', '', 28153),
(159684, 'deDE', 'Verschrotter', 'Verschrotter', 28153),
(159683, 'deDE', 'Hier ist es. Gehen wir hinunter in den Keller.', '', 28153),
(159682, 'deDE', 'Was habt Ihr mit dem Goldenen Thron zu schaff\'n? Wollt Ihr etwa \'ne Audienz?\n\nUm da hochzukomm\'n, nehmt Ihr den Aufzug drin im Großen Siegel.', 'Was habt Ihr mit dem Goldenen Thron zu schaff\'n? Wollt Ihr etwa \'ne Audienz?\n\nUm da hochzukomm\'n, nehmt Ihr den Aufzug drin im Großen Siegel.', 28153),
(159681, 'deDE', 'Der fragliche Keller sollte ganz in der Nähe sein. Verschwenden wir keine Zeit.', '', 28153),
(159680, 'deDE', 'Der Goldene Thron', 'Der Goldene Thron', 28153),
(159679, 'deDE', 'Seid Ihr bereit zum Aufbruch?', '', 28153),
(159678, 'deDE', 'Das muss schnell gehen. Rein und raus, bevor man uns entdeckt.', '', 28153),
(159677, 'deDE', 'Vorwärts!', '', 28153),
(159676, 'deDE', '', 'Sofort.', 28153),
(159675, 'deDE', 'Shandris, Ihr müsst für mich die Strände absuchen und sicherstellen, dass keine Überlebenden davonkommen. Falstad wird sich Euch anschließen, nachdem er uns abgesetzt hat.', '', 28153),
(159674, 'deDE', '', 'Sie werden uns gar nicht kommen sehen.', 28153),
(159673, 'deDE', 'Geht klar.', '', 28153),
(159672, 'deDE', 'Keeshan, Kelsey, nehmt Umbrics Portal und richtet eine Landezone oben auf dem Schiff ein.', '', 28153),
(159671, 'deDE', 'Zu Befehl.', '', 28153),
(159670, 'deDE', 'Umbric, öffnet ein Leerenportal, um die Dunkeleisenzwerge auf die Grals Ruf zu schleusen.', '', 28153),
(159669, 'deDE', 'Wir müssen sicherstellen, dass niemand auf diesem Schiff nach Zuldazar zurückkehrt. Sonst ist unsere Mission Geschichte, und wir sind alle tot.', '', 28153),
(159668, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(159667, 'deDE', '', 'Alle an der Akademie werden mich hierfür veralbern! Ach, Yuke, du bist so ein Tollpatsch!', 28153),
(159666, 'deDE', '', 'Danke! Ich gehöre wirklich zu den Shado-Pan. Heute ist nur einfach nicht mein Tag, ja? Hier ist etwas Azerit. Erzählt bitte niemandem davon, in Ordnung?', 28153),
(159665, 'deDE', 'Bei den Wellen, das habe ich nicht kommen sehen. Soll ich hier sterben?', '', 28153),
(159664, 'deDE', 'Ich bin Euch zu tiefstem Dank verpflichtet, ich sollte in Zukunft vorsichtiger sein. Ein Geschenk für Eure Freundlichkeit.', '', 28153),
(159663, 'deDE', 'Wie ulkig, ich hab mich selbst in die Ecke kartiert!', '', 28153),
(159662, 'deDE', 'Ha ha! Was wäre Kartografie ohne ein kleines Abenteuer, hm? Ein bisschen Gefahr? Ja, ich sehe an Eurem leeren Blick, dass Ihr mir zustimmt. Hier, etwas für Euch. Und jetzt muss ich Karten zeichnen!', '', 28153),
(159661, 'deDE', 'Es ist wirklich peinlich für einen Drachen, das zu sagen, aber könntet Ihr mir hier helfen?', '', 28153),
(159660, 'deDE', 'Ich danke Euch. Auf diesen Inseln gibt es alle möglichen magischen Gegenstände, die meine Zeit und Aufmerksamkeit verdienen. Es wäre allerdings schön, wenn es hier weniger Fallen gäbe.', '', 28153),
(159659, 'deDE', 'Helft Zwiestrump, bringt viel Glück, wenn Ihr\'s tut!', '', 28153),
(159658, 'deDE', 'Zwiestrump ist frei! Ihr werdet heute maximales Glück haben! Jetzt liegt es an Euch!', '', 28153),
(159657, 'deDE', '', 'Oh Twitti, du steckst mal wieder in der Tinte! Muss einen Ausweg finden...', 28153),
(159656, 'deDE', '', 'Ihr seid $gder:die; Beste! Aber ich werde nicht aufhören, zu erforschen, verdammt, nein! Wenn ich nicht erforsche, bin ich nicht Twitti Leuchtritzel!!', 28153),
(159655, 'deDE', 'Dankbarkeitsmechanismus aktiviert. Gebe Dankbarkeit aus. Dankbarkeitsausgabe ist erfolgt.', '', 28153),
(159654, 'deDE', 'Schaltkreise registrieren Blockade, schalte auf Hilfsmodus. HILFE! HILFE! HILFE! HILFE! HILFE! HILFE! HILFE! HILFE! Wiederhole.', '', 28153),
(159653, 'deDE', '', 'Ay Mann, was macht\'n Ihr hier? Könnt Ihr mir aus der Patsche helf\'n?', 28153),
(159652, 'deDE', '', 'Schon besser. Ihr habt \'n schlaues Köpfchen. Hier \'ne kleine Belohnung für das, was Ihr gemacht habt.', 28153),
(159651, 'deDE', 'Ihr! Könnt Ihr mir helfen? Ich schwöre, ich gehöre NICHT mehr zur Legion. Die ist weg. Ich bin\'s nur, Sylvester, der ehrliche Wichtel.', '', 28153),
(159650, 'deDE', 'Ui, danke, wirklich, ich kann Euch nicht genug danken. So, Wiedersehen, folgt mir nicht.', '', 28153),
(159649, 'deDE', '', 'Hi! Hallo? Oh hi, ja, hallo. Könnt Ihr mir helfen? Ich weiß nicht, was hier zu tun ist. Ich bin ganz durcheinander.', 28153),
(159648, 'deDE', '', 'Danke! Wirklich, vielen Dank. Wisst Ihr, wo wir sind? Ich erinnere mich nicht daran, was ich gemacht habe. Wo ist mein Boot? Hatte ich ein Boot?', 28153),
(159647, 'deDE', 'Ich brauche Hilfe! Hört mich jemand?', '', 28153),
(159646, 'deDE', 'Ah, besten Dank, $gAnglerfreund:Anglerfreundin;. Wie habt Ihr es nur so weit gebracht? Ganz gleich, ich sehe, Ihr müsst Euch auf den Weg machen.', '', 28153),
(159645, 'deDE', 'Die prächtige Stadt Dazar\'alor is\' das Machtzentrum der Welt. Die vielen Viertel sin\' voller Wunder un\' Verlockungen. Seine Einwohner sin\' die stärksten un\' klügsten.\n\nAber nehmt Euch vor dem Voodookram in Acht!', 'Die prächtige Stadt Dazar\'alor is\' das Machtzentrum der Welt. Die vielen Viertel sin\' voller Wunder un\' Verlockungen. Seine Einwohner sin\' die stärksten un\' klügsten.\n\nAber nehmt Euch vor dem Voodookram in Acht!', 28153),
(159644, 'deDE', 'Oh weh, das ist mir wohl ein bisschen über den Kopf gewachsen. Hmm. Denk, denk.', '', 28153),
(159643, 'deDE', 'Oh, ich danke Euch so sehr. Ich kann Euch gar nicht sagen, wie oft mir das schon passiert ist. Eines Tages werde ich daraus lernen! Ha ha, aber scheinbar nicht heute. Hier, ich teile das Wenige, das ich habe, mit Euch.', '', 28153),
(159642, 'deDE', 'Gregg braucht Hilfe! Jemand muss Gregg helfen!', '', 28153),
(159641, 'deDE', 'Ihr Gregg geholfen! Gregg so glücklich. Gregg gibt Euch schöne Steine! Gregg liebt Steine.', '', 28153),
(159640, 'deDE', 'He, Ihr da. Vielleicht helft Ihr dem alten Frankie? Vielleicht gibt er Euch etwas, von dem er weiß, dass Ihr es haben wollt? Was sagt Ihr?', '', 28153),
(159639, 'deDE', 'Uff, schon besser. Ich hätte nie gedacht, dass ich mal von jemandem wie Euch gerettet werden würde, aber das Leben ist voller Überraschungen. Hier ist etwas Azerit für Eure Mühe und erzählt niemandem, dass Ihr den alten Frankie hier gesehen habt.', '', 28153),
(159638, 'deDE', 'Huiii! Ja! Flackerkerz dankt Euch! Ja hier, nehmen Juwelen!', '', 28153),
(159637, 'deDE', 'Ihr! Hilfe! Mir helfen! Hilfe!!', '', 28153),
(159636, 'deDE', 'He Brul, hier müsst\' mal wer mit anpacken!', '', 28153),
(159635, 'deDE', 'Ich habe da wohl ein paar Gewichtssteine mehr aufgelegt, als für mich gut war. Danke, Brul.', '', 28153),
(159634, 'deDE', 'Abgesandter des Zandalariimperiums', 'Abgesandter des Zandalariimperiums', 28153),
(159633, 'deDE', '', 'Alle Achtung, danke! Ihr seid wirklich großartig. Ich werde versuchen, das nicht noch einmal zu tun.', 28153),
(159632, 'deDE', '', 'Schau mal, was du JETZT schon wieder angerichtet hast, Karyn. Oh, wie komme ich aus der Nummer nur wieder raus?', 28153),
(159631, 'deDE', 'Sammler Kojo findet Ihr weit drauß\'n im Schuppenhandelsposten nordöstlich der Stadt.\n\nAber passt mit dem tortollanischen Mojo auf. Das is\' echt seltsames Zeugs.', 'Sammler Kojo findet Ihr weit drauß\'n im Schuppenhandelsposten nordöstlich der Stadt.\n\nAber passt mit dem tortollanischen Mojo auf. Das is\' echt seltsames Zeugs.', 28153),
(159630, 'deDE', 'Abgesandter der tortollanischen Sucher', 'Abgesandter der tortollanischen Sucher', 28153),
(159629, 'deDE', 'Da kenn\' ich mehrere. Welchen wollt Ihr?', 'Da kenn\' ich mehrere. Welchen wollt Ihr?', 28153),
(159628, 'deDE', 'Bedeutende Orte', 'Bedeutende Orte', 28153),
(159627, 'deDE', 'Willkommen in meiner bescheidenen Behausung, $C. Ich hoffe, Ihr könnt... in Frieden ruhen.', '', 28153),
(159626, 'deDE', 'Jetzt nicht mehr. Lasst mich erklären...', '', 28153),
(159625, 'deDE', '', 'Wir haben keine Zeit, dem nachzutrauern, was wir verloren haben. Die Mag\'har werden eine neue Heimat finden. Und zwar hier.', 28153),
(159624, 'deDE', 'Das Portal nach Azeroth wird lange genug offenbleiben, damit Eure Soldaten sich auf ihre Reise vorbereiten und dann hindurchgehen können.', '', 28153),
(159623, 'deDE', 'Aka\'magosh, Geya\'rah. Ich werde Eurer Mutter von Eurer Entscheidung berichten. Gute Reise, Etrigg. Für Euch ebenfalls, $n.', '', 28153),
(159622, 'deDE', '', 'Willkommen, $n! Der Außenposten untersteht Euerm Befehl.', 28153),
(159621, 'deDE', 'Noch einmal die Steine Draenors im Kampf unter meinen Füßen zu spüren... Heute war ein guter Tag.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159620, 'deDE', '', 'Ihr habt schon früher den Weg nach Draenor geöffnet. Ich weiß tief in meinem Herzen, dass wir den Rückweg finden werden.', 28153),
(159619, 'deDE', 'Die Magie, die Euch nach Azeroth bringt, ist unbeständig. Sie wird Euch vielleicht nicht wieder nach Hause bringen können.', '', 28153),
(159618, 'deDE', 'Unser Dank ist Euch gewiss. $n, bereitet Euch darauf vor, nach...', '', 28153),
(159617, 'deDE', 'Ich dachte mir schon, dass Ihr Euch diesen Helden anschließen würdet, nachdem der gemeinsame Kampf Euch miteinander verbunden hat, Geya\'rah. Ihr habt meinen Segen.', '', 28153),
(159616, 'deDE', '', 'Der Kriegshäuptling kann die Draenei und diese Verräter der Lichtgebundenen zurückschlagen. Die Mag\'har werden Euch helfen, Euren Krieg zu gewinnen, und dann wird unsere Schuld beglichen sein.', 28153),
(159615, 'deDE', 'Euch, Oberanführerin? Aber was ist mit dem Kampf Eures Volks hier?', '', 28153),
(159614, 'deDE', '', 'Mich. Mit einer Kompanie Freiwilliger. Mit Eurer Erlaubnis, Kriegshäuptling.', 28153),
(159613, 'deDE', 'Was nun die Schuld angeht, in der wir bei Eurer Horde stehen: Wir senden...', '', 28153),
(159612, 'deDE', '', 'Sie haben mutig gekämpft. Ich muss zugeben... ich bin mit Euch zu hart ins Gericht gegangen, Etrigg. Mit Euch ebenfalls, $n.', 28153),
(159611, 'deDE', 'Wir werden bereit sein. Und was ist mit diesen Helden aus Azeroth? Waren sie hilfreich?', '', 28153),
(159610, 'deDE', '', 'Der Angriff der Draenei wurde niedergeschlagen, Kriegshäuptling. Doch die Hochexarchin wird nicht nachgeben. Das tun Fanatiker nie.', 28153),
(159609, 'deDE', 'Wenn die Piraten von Freihafen aus losgesegelt sind, finden wir dort vielleicht mehr heraus. Ich denke, ich weiß, wer uns helfen könnte.', '', 28153),
(159608, 'deDE', '', 'Ich... vielleicht habt Ihr recht, Genn. Aber trotz alledem sind die Hinweise mehr als dürftig.', 28153),
(159607, 'deDE', 'Womöglich haben sie ihr Ziel noch nicht erreicht, Katherine. Euch könnte noch Zeit bleiben.', '', 28153),
(159606, 'deDE', 'Der Vertrag sieht Jainas Transport vor, keine sofortige Hinrichtung.', '', 28153),
(159605, 'deDE', '', 'Wie kann das keine schlechte Nachricht sein?', 28153),
(159604, 'deDE', '', 'Wir treffun uns beim Lager wieder, $n.', 28153),
(159603, 'deDE', '', 'Sie hat die Hinrichtung meiner Tochter Piraten überlassen, Genn! Dem Abschaum der See!', 28153),
(159602, 'deDE', '', 'Die Zeit wird knapp und unsere einzige Spur ist ein Vertrag zwischen Priscilla und einigen Briganten aus Freihafen!', 28153),
(159601, 'deDE', 'Überlegt einen Moment, Katherine. Vielleicht ist das keine schlechte Nachricht.', '', 28153),
(159600, 'deDE', '', 'Moment... seid Ihr wirklich...?', 28153),
(159599, 'deDE', '', 'Diese Pläne der Allianz sind nur für unsere Augen bestimmt. Zeit, zu sterben; Bluttroll!', 28153),
(159598, 'deDE', 'Ihr könnt kein... Bluttroll... sein...', '', 28153),
(159597, 'deDE', 'Bluttrolle! Ha, Ihr seid zu dumm, um die Geheimnisse der Allianz je zu verstehen.', '', 28153),
(159596, 'deDE', '', 'Ihr seid... kein... Bluttroll...!', 28153),
(159595, 'deDE', '', 'Ein Bluttroll? Ich mache lieber kurzen Prozess, bevor ich diese Pläne zu den Zandalari bringe.', 28153),
(159594, 'deDE', 'Ich rieche auf einmal ganz komisch!', 'Ich will dieses Spiel nicht mehr spielen!', 28153),
(159593, 'deDE', 'So ein grüner Kerl hat sie uns am Ufer verkauft!', 'So ein grüner Kerl hat sie uns am Ufer verkauft!', 28153),
(159592, 'deDE', 'Die Miliz ist immer zur Stelle, um uns zu beschützen! Na ja, außer jetzt gerade. Sie ist bei einem wichtigen Treffen mit den Gezeitenweisen. Die können einem schon Angst einjagen, aber Bruder Pike ist immer nett, wenn er zu Besuch kommt.', 'Die Miliz ist immer zur Stelle, um uns zu beschützen! Na ja, außer jetzt gerade. Sie ist bei einem wichtigen Treffen mit den Gezeitenweisen. Die können einem schon Angst einjagen, aber Bruder Pike ist immer nett, wenn er zu Besuch kommt.', 28153),
(159591, 'deDE', 'Das war alles Gretels Idee!', 'Möchtet Ihr ein Haustier kaufen?', 28153),
(159590, 'deDE', 'Warum heißt es überhaupt Sturmsang? Ich habe hier noch nie einen singen gehört.$b$bErwachsene sind schon komisch, oder?', 'Warum heißt es überhaupt Sturmsang? Ich habe hier noch nie einen singen gehört.$b$bErwachsene sind schon komisch, oder?', 28153),
(159589, 'deDE', 'Habt Ihr schon die gedämpften Miesmuschen probiert? Sie sind eine echte Spezialität aus Sturmsang!', 'Habt Ihr schon die gedämpften Miesmuschen probiert? Sie sind eine echte Spezialität aus Sturmsang!', 28153),
(159588, 'deDE', 'Ich freue mich immer, wenn wir einen Ausflug zur Metbrauerei Mildenhall machen! Meine Eltern sagen, ich bin zu jung für Met, aber dafür ich bekomme immer eine Honigwabe zum Naschen.', 'Ich freue mich immer, wenn wir einen Ausflug zur Metbrauerei Mildenhall machen! Meine Eltern sagen, ich bin zu jung für Met, aber dafür ich bekomme immer eine Honigwabe zum Naschen.', 28153),
(159587, 'deDE', 'Ob ich wohl auch mal so groß werde wie Mama oder Papa? Sie essen immer ihr Gemüse auf. Vielleicht sollte ich das auch...', 'Ob ich wohl auch mal so groß werde wie Mama oder Papa? Sie essen immer ihr Gemüse auf. Vielleicht sollte ich das auch...', 28153),
(159586, 'deDE', 'Mama und Papa arbeiten hart, damit wir alle genug zu essen haben. Essen ist echt lecker!', 'Mama und Papa arbeiten hart, damit wir alle genug zu essen haben. Essen ist echt lecker!', 28153),
(159585, 'deDE', 'Seid gegrüßt, $Gmein Herr:Fräulein;! Seid Ihr neu im Tal?', 'Seid gegrüßt, $Gmein Herr:Fräulein;! Seid Ihr neu im Tal?', 28153),
(159584, 'deDE', 'Ich hoffe, das hat niemand gesehen!', 'Tun wir so, als wäre das nie passiert!', 28153),
(159583, 'deDE', 'Seit Generationen vertrauen wir auf die Weisungen der Gezeitenweisen. Das Meer gewährt ihnen Weisheit, da bin ich mir gewiss.', 'Seit Generationen vertrauen wir auf die Weisungen der Gezeitenweisen. Das Meer gewährt ihnen Weisheit, da bin ich mir gewiss.', 28153),
(159582, 'deDE', 'Ich hab schon bessere Tage gehabt.', 'Das bleibt besser unter uns.', 28153),
(159581, 'deDE', 'Habt Ihr schon von den Schätzen des Tals gekostet? Probiert unser frisches Brot mit Wurst aus Drustvar. Spült alles mit einem leckeren Krug Met hinunter... Allein der Gedanke lässt mir das Wasser im Mund zusammenlaufen.', 'Habt Ihr schon von den Schätzen des Tals gekostet? Probiert unser frisches Brot mit Wurst aus Drustvar. Spült alles mit einem leckeren Krug Met hinunter... Allein der Gedanke lässt mir das Wasser im Mund zusammenlaufen.', 28153),
(159580, 'deDE', 'Wir konnten immer auf den Schutz der Miliz bauen. Ich frage mich, warum sie sich zurückgezogen hat?', 'Wir konnten immer auf den Schutz der Miliz bauen. Ich frage mich, warum sie sich zurückgezogen hat?', 28153),
(159579, 'deDE', 'Wir bestellen die Felder, um die Mägen von Kul Tiras zu füllen. Es ist harte Arbeit, aber sie lohnt sich!', 'Wir bestellen die Felder, um die Mägen von Kul Tiras zu füllen. Es ist harte Arbeit, aber sie lohnt sich!', 28153),
(159578, 'deDE', 'Wir mögen vom Land leben, aber wir sind immer noch Kinder des Meeres.', 'Wir mögen vom Land leben, aber wir sind immer noch Kinder des Meeres.', 28153),
(159577, 'deDE', 'Möge die See Euch den Weg weisen, Fremdling.', 'Möge die See Euch den Weg weisen, Fremdling.', 28153),
(159576, 'deDE', 'Willkommen im Tal!', 'Willkommen im Tal!', 28153),
(159575, 'deDE', 'Ah, $n, da seid Ihr ja. Einige der Prachtmeers sind durchgebrochen. Beseitigt sie.', '', 28153),
(159574, 'deDE', '', 'Ich werde unruhig. Gestattet mir, aus den Schatten heraus zu helfen.', 28153),
(159573, 'deDE', '', 'Mama, wo ist Papa?', 28153),
(159572, 'deDE', 'Seid gegrüßt, $R. Ihr möchtet etwas neu geschmiedet haben?\n\nDie Macht von Azerit ist grenzenlos. Zum Glück für Euch sind meine Preise es nicht.', '', 28153),
(159571, 'deDE', '', 'Kommt, Champions von Azeroth. Wir müssen dem Kriegshäuptling von unserem Sieg berichten...', 28153),
(159570, 'deDE', '', 'Eure Hochexarchin kann Euch nicht retten. Mein Volk wird erst dann aufhören zu kämpfen, wenn Draenor frei ist!', 28153),
(159569, 'deDE', 'Yrel... Ich habe Euch enttäuscht...', '', 28153),
(159568, 'deDE', 'Dieses einst fruchtbare Land ist jetzt lebloser Staub. Das hat Euer Hass angerichtet!', '', 28153),
(159567, 'deDE', '', 'Über unsere Narben bestimmt nicht Ihr!', 28153),
(159566, 'deDE', 'Gebt Euren Hass auf! Das Licht kann die Narben des Kriegs heilen!', '', 28153),
(159565, 'deDE', '', 'Ihr meint Unterwerfung!', 28153),
(159564, 'deDE', 'Die Naaru bieten uns Frieden und Ordnung!', '', 28153),
(159563, 'deDE', 'Für Draenor! Für die Mag\'har!', '', 28153),
(159562, 'deDE', '', 'Ich habe genug von Eurem Geschwafel! Man soll uns auf dem Schlachtfeld beurteilen!', 28153),
(159561, 'deDE', 'Die Hochexarchin befiehlt Euch, aufzugeben... oder Euch dem Urteil zu stellen!', '', 28153),
(159560, 'deDE', '', 'Zieht Euch zurück, solange Ihr noch könnt! Ihr werdet uns nicht Eure Lehren aufzwingen, Draenei!', 28153),
(159559, 'deDE', 'Gebt diesen sinnlosen Widerstand auf, Mag\'har! Ergebt Euch und heißt das Licht willkommen!', '', 28153),
(159558, 'deDE', 'Wir sind bei Euch, Geya\'rah!', '', 28153),
(159557, 'deDE', '', 'Sie greifen Burg Immermorn an! Kommt mit mir, Helden!', 28153),
(159556, 'deDE', 'Die Hochexarchin will das nur das Beste für uns alle!', 'Die Hochexarchin will das nur das Beste für uns alle!', 28153),
(159555, 'deDE', 'Das Licht hat uns gerettet. Es kann Euch ebenfalls retten!', 'Das Licht hat uns gerettet. Es kann Euch ebenfalls retten!', 28153),
(159554, 'deDE', 'Die Zeit von Grommash ist vorbei. Schreitet in eine neue Zukunft!', 'Die Zeit von Grommash ist vorbei. Schreitet in eine neue Zukunft!', 28153),
(159553, 'deDE', 'Schließt Euch uns im Licht an, Brüder und Schwestern!', 'Schließt Euch uns im Licht an, Brüder und Schwestern!', 28153),
(159552, 'deDE', 'Wir können Draenor gemeinsam retten!', 'Wir können Draenor gemeinsam retten!', 28153),
(159551, 'deDE', 'Ihr habt dieses Land zerstört! Es ist noch nicht zu spät, es zu retten!', 'Ihr habt dieses Land zerstört! Es ist noch nicht zu spät, es zu retten!', 28153),
(159550, 'deDE', 'Höret die Visionen der Hochexarchin!', 'Höret die Visionen der Hochexarchin!', 28153),
(159549, 'deDE', 'Wir kommen, um Euch vor Eurer Barbarei zu retten!', 'Wir kommen, um Euch vor Eurer Barbarei zu retten!', 28153),
(159548, 'deDE', 'Ergebt Euch, Mag\'har! Empfangt das Licht mit offenen Armen!', 'Ergebt Euch, Mag\'har! Empfangt das Licht mit offenen Armen!', 28153),
(159547, 'deDE', 'Willkommen.', '', 28153),
(159546, 'deDE', '', 'Macht die Verderbnis des Lichts nieder!', 28153),
(159545, 'deDE', '', 'Zurück, Draenei! Euer Licht ist hier nicht willkommen!', 28153),
(159544, 'deDE', '', 'Verteidigt Eure Stellung! Dieses Land gehört den Mag\'har!', 28153),
(159543, 'deDE', 'Akunda heißt alle willkommen.', '', 28153),
(159542, 'deDE', '', 'Schaltet diese Belagerungsmaschinen aus!', 28153),
(159541, 'deDE', '', 'Dann kämpfen wir gemeinsam für Blut und Ehre. Kommt mit mir, Helden!', 28153),
(159540, 'deDE', 'Ich habe noch nie einem Kampf den Rücken gekehrt. Ich habe nicht vor, heute damit anzufangen.', '', 28153),
(159539, 'deDE', '', 'Das ist nicht Euer Kampf, Fremde. Es steht Euch frei, nach Azeroth zurückzukehren.', 28153),
(159538, 'deDE', 'Wir halten die Stellung, Oberanführerin. Aber der Feind scheint sich für einen größeren Angriff zu sammeln.', '', 28153),
(159537, 'deDE', '', 'Lantresor! Berichtet!', 28153),
(159536, 'deDE', 'Ihr könnt Eure Gegner auch mit einem Stachelpfeil attackieren und ihnen so einen vorübergehenden Blutungsschaden zufügen.', '', 28153),
(159535, 'deDE', 'Wir werden gemeinsam mit Euch kämpfen, Oberanführerin.', '', 28153),
(159534, 'deDE', '', 'Ich werde nicht tatenlos zusehen, wie die Hochexarchin einen Kreuzzug gegen die Freiheit der Mag\'har führt! Die Tyrannei des Lichts muss beendet werden!', 28153),
(159533, 'deDE', '', 'Manche Orcs gingen so weit, sich auf die Seite der Draenei und damit gegen ihre eigene Sippe zu stellen... selbst der Sohn des Kriegshäuptlings! Wir nennen diese Verräter die Lichtgebundenen.', 28153),
(159532, 'deDE', '', 'Ihre Gebieter, die Naaru, drängten sie dazu, ihren Einfluss auf die Orcs auszuweiten. Einige sind freiwillig konvertiert. Anderen wurde das Licht aufgezwungen.', 28153),
(159531, 'deDE', '', 'Doch ohne Dämonen, gegen die sie kämpfen konnten, wurden die Draenei geradezu besessen von ihrem kostbaren Licht.', 28153),
(159530, 'deDE', '', 'Nach Archimondes Untergang haben die Orcs und die Draenei zusammengearbeitet, um die Legion aus Draenor zu vertreiben. Das waren die guten Jahre.', 28153),
(159529, 'deDE', '', 'Das habt Ihr Euch wohl verdient.', 28153),
(159528, 'deDE', 'Es ist Zeit, dass Ihr erläutert, wer diese Lichtgebundenen sind, Oberanführerin.', '', 28153),
(159527, 'deDE', '', 'Gut! Ich kann noch einen weiteren Exarchenkopf auf meinen Mauern brauchen. Kommt, Fremdlinge!', 28153),
(159526, 'deDE', 'Sie werden von einem Exarchen angeführt. Ihre Streitmacht ist... beachtlich.', 'Sie werden von einem Exarchen angeführt. Ihre Streitmacht ist... beachtlich.', 28153),
(159525, 'deDE', '', 'Diese Verräter sollen verflucht sein! Wie groß ist ihre Streitmacht?', 28153),
(159524, 'deDE', 'Oberanführerin Geya\'rah! Die Lichtgebundenen greifen die Wildwacht an!', 'Oberanführerin Geya\'rah! Die Lichtgebundenen greifen die Wildwacht an!', 28153),
(159523, 'deDE', 'So. Ihr seid jetzt... ein Bluttroll. Zumindest vorübergehend.', '', 28153),
(159522, 'deDE', 'Aber wir können nicht riskieren, dass auch nur ein Mitglied der Allianz am Kriegshafen der Rastari gesehen wird.', '', 28153),
(159521, 'deDE', 'Ich entschuldige mich für den Schmerz und die Unangemessenheit dieses Rituals, $n.', '', 28153),
(159520, 'deDE', 'Umbric, ich bin bereit, mich in einen Bluttroll zu verwandeln.', 'Umbric, ich bin bereit, mich in einen Bluttroll zu verwandeln.', 28153),
(159519, 'deDE', 'Man sagt, Pin\'jin is\' einer der geduldigsten Trolle überhaupt. Muss er auch sein, wenn er sich das ganze Geschnatter von den Adligen mit ihren feinen Klamotten anhör\'n kann.\n\nWenn Ihr auch Geduld habt un\' von ihm lern\'n wollt, findet Ihr den auf der Handwerkerterrasse. Das is\' auf der Westseite von Dazar\'alor.', 'Man sagt, Pin\'jin is\' einer der geduldigsten Trolle überhaupt. Muss er auch sein, wenn er sich das ganze Geschnatter von den Adligen mit ihren feinen Klamotten anhör\'n kann.\n\nWenn Ihr auch Geduld habt un\' von ihm lern\'n wollt, findet Ihr den auf der Handwerkerterrasse. Das is\' auf der Westseite von Dazar\'alor.', 28153),
(159517, 'deDE', 'Ihr glaubt, das is\' einfach, \'n Ankylodon zu häut\'n? Überhaupt nich\'! Wenn Ihr sowas lern\'n wollt, müsst Ihr mit Rana sprech\'n.\n\nIch hörte, die is\' grade zurück in der Stadt. Ihr findet sie auf der Handwerkerterrasse auf der Westseite von Dazar\'alor.\n\nAber seid besser nett zu ihr, wenn Euch Eure Haut lieb is\'!', 'Ihr glaubt, das is\' einfach, \'n Ankylodon zu häut\'n? Überhaupt nich\'! Wenn Ihr sowas lern\'n wollt, müsst Ihr mit Rana sprech\'n.\n\nIch hörte, die is\' grade zurück in der Stadt. Ihr findet sie auf der Handwerkerterrasse auf der Westseite von Dazar\'alor.\n\nAber seid besser nett zu ihr, wenn Euch Eure Haut lieb is\'!', 28153),
(159515, 'deDE', 'Was wollt Ihr von diesem Dieb Secott? Wir hab\'n ihn noch nich\' erwischt, aber wir wiss\'n, dass er Gold in Atal\'Dazar klaut! Die Loa werd\'n ihn dafür büß\'n lass\'n. Un\' wenn nich\', dann mach ich das.\n\nIhr findet Euern \"Freund\" drüben auf der Handwerkerterrasse. Wir behalt\'n Euch beide im Auge.', 'Was wollt Ihr von diesem Dieb Secott? Wir hab\'n ihn noch nich\' erwischt, aber wir wiss\'n, dass er Gold in Atal\'Dazar klaut! Die Loa werd\'n ihn dafür büß\'n lass\'n. Un\' wenn nich\', dann mach ich das.\n\nIhr findet Euern \"Freund\" drüben auf der Handwerkerterrasse. Wir behalt\'n Euch beide im Auge.', 28153),
(159513, 'deDE', 'Xanjo macht aus dem Leder, das Rana ihm besorgt, die wundervollsten Rüstung\'n, die Ihr je geseh\'n habt.\n\nIhr findet ihn auf der Handwerkerterrasse auf der Westseite von Dazar\'alor.', 'Xanjo macht aus dem Leder, das Rana ihm besorgt, die wundervollsten Rüstung\'n, die Ihr je geseh\'n habt.\n\nIhr findet ihn auf der Handwerkerterrasse auf der Westseite von Dazar\'alor.', 28153),
(159511, 'deDE', 'Unsere Seshuli stellt den schönsten Schmuck der Südlichen Meere her. Ihr findet sie in der Halle der Schimmer, wenn Ihr was von Ihr lern\'n wollt.\n\nGeht einfach zur Handwerkerterrasse auf der Westseite von Dazar\'alor. Da geht Ihr dann nach Osten un\' den Tunnel runter in die Pyramide. Wenn Ihr das Glitzerzeug seht, wisst Ihr, dass Ihr sie gefund\'n habt.', 'Unsere Seshuli stellt den schönsten Schmuck der Südlichen Meere her. Ihr findet sie in der Halle der Schimmer, wenn Ihr was von Ihr lern\'n wollt.\n\nGeht einfach zur Handwerkerterrasse auf der Westseite von Dazar\'alor. Da geht Ihr dann nach Osten un\' den Tunnel runter in die Pyramide. Wenn Ihr das Glitzerzeug seht, wisst Ihr, dass Ihr sie gefund\'n habt.', 28153),
(159509, 'deDE', '', 'Nehmt meinen Hippogryphen nach Darnassus. Sorgt dafür, dass die Besetzung durch die Horde so... erträglich wie möglich ist.', 28153),
(159506, 'deDE', 'Die Chronisten reis\'n überall rum, um die Wahrheit über die Welt rauszufind\'n. Ihr solltet mit Kizani sprech\'n.\n\nIhr findet sie im oberen Bereich in der Halle der Chronisten im Großen Siegel.', 'Die Chronisten reis\'n überall rum, um die Wahrheit über die Welt rauszufind\'n. Ihr solltet mit Kizani sprech\'n.\n\nIhr findet sie im oberen Bereich in der Halle der Chronisten im Großen Siegel.', 28153),
(159504, 'deDE', 'Jahden Fla auf der Handwerkerterrasse macht immer mit seinen Blumen rum. Das is\' auf der Westseite von Dazar\'alor.\n\nUn\' der macht keine Scherze, wenn er von seinem grünen Daumen redet.', 'Jahden Fla auf der Handwerkerterrasse macht immer mit seinen Blumen rum. Das is\' auf der Westseite von Dazar\'alor.\n\nUn\' der macht keine Scherze, wenn er von seinem grünen Daumen redet.', 28153),
(159503, 'deDE', 'Der Krieg ist eine Prüfung. Er stellt unsere Ehre und unsere Überzeugungen auf die Probe.\n\nIch kam nach Zuldazar, um sicherzustellen, dass die Horde in diesem Konflikt nicht das aus den Augen verliert, was uns ausmacht... was uns stark macht.\n\nIch vertraue darauf, dass Ihr es nicht vergessen werdet, Stimme der Horde.', '', 28153),
(159502, 'deDE', 'Ich muss stärker werden!', '', 28153),
(159500, 'deDE', 'Ich hoffe, es geht Euch gut, $p.', '', 28153),
(159499, 'deDE', 'Euretwegen fange ich jetzt an zu trainieren, damit ich auch ein tapferer Krieger werde. Ich möchte in der Lage sein, unsere Stadt zu verteidigen!', '', 28153),
(159498, 'deDE', 'Oma redet nur noch davon, wie sehr sie wünschte, ich wäre mehr wie Ihr...', '', 28153),
(159497, 'deDE', 'Ich... ich bin nur froh, dass Ihr rechtzeitig hergekommen seid.', '', 28153),
(159496, 'deDE', 'Ihr wollt Angeln lern\'? Dann müsst Ihr mit Tali der Schweigsamen reden. Die fischt immer an der Spanne nördlich von Dazar\'alor.\n\nAber passt auf, dass Ihr kein Lärm macht un\' ihr nich\' die Fische verscheucht.', 'Ihr wollt Angeln lern\'? Dann müsst Ihr mit Tali der Schweigsamen reden. Die fischt immer an der Spanne nördlich von Dazar\'alor.\n\nAber passt auf, dass Ihr kein Lärm macht un\' ihr nich\' die Fische verscheucht.', 28153),
(159495, 'deDE', 'Ich möchte Großmutter zwar nicht enttäuschen, aber ich bin für so was einfach nicht gemacht... Ich will nur, dass alles hier wieder normal wird.', '', 28153),
(159494, 'deDE', 'Passt auf Euren Kopf auf. Es regnet Steine!', '', 28153),
(159492, 'deDE', 'Solche Sachen kann Euch der Goblin Shuga auf der Handwerkerterrasse beibring\'n. Das is\' außerhalb, auf der Westseite von Dazar\'alor.\n\nAber jagt nix Wichtiges in die Luft. Wir mög\'n Zuldazar so wie\'s is\'.', 'Solche Sachen kann Euch der Goblin Shuga auf der Handwerkerterrasse beibring\'n. Das is\' außerhalb, auf der Westseite von Dazar\'alor.\n\nAber jagt nix Wichtiges in die Luft. Wir mög\'n Zuldazar so wie\'s is\'.', 28153),
(159491, 'deDE', 'Die haben meine Kuh getötet!', 'Die haben meine Kuh getötet!', 28153),
(159489, 'deDE', 'Das ist nicht mein erster Kampf!', 'Das ist nicht mein erster Kampf!', 28153),
(159488, 'deDE', 'Ich werde helfen, so gut ich kann!', 'Ich werde helfen, so gut ich kann!', 28153),
(159487, 'deDE', 'Lasst mich schon an sie ran!', 'Lasst mich schon an sie ran!', 28153),
(159486, 'deDE', 'Denen werd ich\'s zeigen!', 'Denen werd ich\'s zeigen!', 28153),
(159485, 'deDE', 'Dafür werden sie zahlen!', 'Dafür werden sie zahlen!', 28153),
(159484, 'deDE', 'Da sprecht Ihr am besten mit der Blutelfenverzauberin Quinni. Ihr findet sie auf der Handwerkerterrasse in der westlichen Basis von Dazar\'alor. Wenn Ihr da in Richtung Pyramide schaut, geht Ihr in die Halle der Schimmer.', 'Da sprecht Ihr am besten mit der Blutelfenverzauberin Quinni. Ihr findet sie auf der Handwerkerterrasse in der westlichen Basis von Dazar\'alor. Wenn Ihr da in Richtung Pyramide schaut, geht Ihr in die Halle der Schimmer.', 28153),
(159482, 'deDE', '', 'Das Erbe Eurer Familie von Prachtmeerversagern stirbt mit Euch!', 28153),
(159481, 'deDE', '', 'Eure Familie war immer zu schwach.', 28153),
(159480, 'deDE', '', 'Und wir haben Beweise!', 28153),
(159479, 'deDE', '', 'Ich werde diese Bürde auf mich nehmen und hoffe, mich als würdige Nachfolgerin zu erweisen.', 28153),
(159478, 'deDE', 'Da wendet Ihr Euch am besten an Küchenchefin T\'sarah. Ihr findet sie am Königlichen Bratrost in Dazar\'alor neben dem Großen Siegel.', 'Da wendet Ihr Euch am besten an Küchenchefin T\'sarah. Ihr findet sie am Königlichen Bratrost in Dazar\'alor neben dem Großen Siegel.', 28153),
(159476, 'deDE', '', 'Meine treue Freundin Priscilla und ich haben uns beraten. Ich denke, es ist das Beste für Kul Tiras, wenn ich als Lordadmiralin abdanke...', 28153),
(159475, 'deDE', '', 'Katherine Prachtmeer hat ihr Leben dem Wohl von Kul Tiras gewidmet!', 28153),
(159473, 'deDE', 'Sterbt, Hordenabschaum!', 'Sterbt, Hordenabschaum!', 28153),
(159472, 'deDE', 'Ich werde Euch in Stücken zu Eurem Kriegshäuptling zurückschicken!', 'Ich werde Euch in Stücken zu Eurem Kriegshäuptling zurückschicken!', 28153),
(159471, 'deDE', 'Ihr werdet uns niemals bezwingen!', 'Ihr werdet uns niemals bezwingen!', 28153),
(159470, 'deDE', 'Boralus wird nicht fallen!', 'Boralus wird nicht fallen!', 28153),
(159469, 'deDE', 'Für Boralus!', 'Für Boralus!', 28153),
(159468, 'deDE', 'Festhalten, $p. Flinkschwinge bringt Euch in null Komma nichts ans Ziel.', '', 28153),
(159467, 'deDE', '', 'Der Nervenkitzel der Jagd... Etwas Besseres gibt es nicht.', 28153),
(159466, 'deDE', '', 'Pa\'ku mustert Kua\'fon und seufzt.', 28153),
(159465, 'deDE', 'Auf geht\'s, Flinkschwinge! Zurück in die Himmel, wo wir hingehören.', '', 28153),
(159464, 'deDE', 'Schließen', 'Schließen', 28153),
(159463, 'deDE', 'Es ist von ALLERGRÖSSTER WICHTIGKEIT, dass wir die Zündbefehle von einer Stellung mit freier Sicht auf alle Explosionsorte aus geben. Leider aber muss ich manuell überprüfen, ob alle Parameter korrekt eingestellt sind, und das kann ich nur von hier aus tun.\n\nKurz gesagt: Schwingt Euch in die Flugmaschine und drückt den großen roten Knopf, wenn ich es Euch sage.', '', 28153),
(159462, 'deDE', '', 'Genug Fragen. Reitet!', 28153),
(159461, 'deDE', 'Die Lichtgebundenen?', '', 28153),
(159460, 'deDE', '', 'Meine Mutter befehligt eine Garnison in Nagrand. Mein Vater ist im Kampf gegen die Lichtgebundenen gefallen.', 28153),
(159459, 'deDE', 'Ihr seid die Tochter von Durotan und Draka. Ich sehe beide in Euch. Sind Eure Eltern...', '', 28153),
(159458, 'deDE', '', 'Ich brauche keine Hilfe von Fremden... aber ich werde tun, was Ihr befehlt. Kommt!', 28153),
(159457, 'deDE', 'Etrigg und $n werden Euch dabei helfen, den Anstifter der Oger zur Strecke zu bringen, Geya\'rah.', '', 28153),
(159456, 'deDE', 'Durotan steht in der Schuld dieser Helden, Geya\'rah, genau wie ich. Ihr entehrt den Geist Eures Vaters mit Eurem Ausbruch. Dennoch... Ihr habt mich da auf einen Gedanken gebracht...', '', 28153),
(159455, 'deDE', '', 'Haltet Ihr uns etwa für Narren?! Kriegshäuptling, wir können unsere Soldaten nicht diesen Fremdlingen zur Verfügung stellen. Nicht, wenn wir uns selbst Feinden gegenübersehen!', 28153),
(159454, 'deDE', 'Helden aus meiner Welt haben einst die Eurige aus den Klauen von Tyrannen befreit. Jetzt sieht Azeroth sich einer ähnlichen Bedrohung gegenüber, also sind wir hergekommen, um Euch um Begleichung dieser Schuld zu bitten.', '', 28153),
(159453, 'deDE', 'Da stehen wir uns nun also als... zwei alte Gespenster gegenüber. Warum seid Ihr nach so langer Zeit nach Draenor zurückgekehrt?', '', 28153),
(159452, 'deDE', 'Und der Grommash Höllschrei, den ich kannte, gab sein Leben, um uns aus den Klauen der Dämonen zu befreien. Ein würdiger Tod.', '', 28153),
(159451, 'deDE', 'Etrigg... Ich kannte einen Etrigg, der Schwarzfaust diente. Er war ein ehrenhafter Orc, der im ruhmreichen Kampf gestorben ist.', '', 28153),
(159450, 'deDE', 'So ist es. Ich bin Etrigg, und dies ist $n, Champion der Horde.', '', 28153),
(159449, 'deDE', 'Es ist schon viele Jahre her, dass mir ein grünhäutiger Orc unter die Augen gekommen ist. Und Eure Begleitung kommt mir... bekannt vor. Ihr kommt aus Azeroth.', '', 28153),
(159448, 'deDE', 'Genug! Ich werde die Gefangenen selbst beurteilen, Geya\'rah.', '', 28153),
(159447, 'deDE', '', 'Eure Worte rühren mein Herz, alter Orc. Wir ehren immer noch die Geschichte unserer einzelnen Klans, obwohl wir als Mag\'har vereint sind. Doch Ihr müsst erst noch beweisen...', 28153),
(159446, 'deDE', 'Durotan war der Häuptling der Frostwölfe. Ich habe nie einen ehrenhafteren Orc gekannt. Er war ein wahrer Anführer, der seine Leute liebte. Ich vermisse seine Weisheit.', '', 28153),
(159445, 'deDE', 'Der Kriegshymnenklan kämpfte seit Generationen gegen die Oger an. Obwohl sie zahlenmäßig weit unterlegen waren, hat Grommash Höllschrei sein Volk zu einem großartigen Sieg über die Hochfelsoger geführt.', '', 28153),
(159444, 'deDE', 'Schwarzfels... mein eigener Klan. Wir waren stolze Orcs... leidenschaftliche Soldaten. Doch wir wurden von Gul\'dans Teufelsmagie getäuscht und haben... furchtbare Dinge getan.', '', 28153),
(159443, 'deDE', '', 'Die drei Banner in diesem Lager wird jeder wahre Orc kennen. Sagt mir etwas darüber, oder die Klinge des Henkers trifft Euch beide!', 28153),
(159442, 'deDE', '', 'Es gibt nur einen Kriegshäuptling... und Ihr seid kein Schwarzfelsorc! Doch lasst uns Eure Worte überprüfen.', 28153),
(159441, 'deDE', 'Ich bin Etrigg vom Schwarzfelsklan. Wir kommen im Namen unseres Kriegshäuptlings aus Azeroth.', '', 28153),
(159440, 'deDE', '', 'Wir werden sehen. Sprecht, Eindringlinge. Wer seid Ihr?', 28153),
(159439, 'deDE', 'Das sind Spione der Lichtgebundenen! Dreckige Verräter!', 'Das sind Spione der Lichtgebundenen! Dreckige Verräter!', 28153),
(159438, 'deDE', '', 'Bringt sie zu mir.', 28153),
(159437, 'deDE', 'Oberanführerin Geya\'rah! Wir haben Gefangene.', '', 28153),
(159436, 'deDE', 'Die Oberanführerin wird wissen, was zu tun ist.', 'Die Oberanführerin wird wissen, was zu tun ist.', 28153),
(159435, 'deDE', 'Seid wachsam. Wir wissen nicht, ob das von den Draenei gesandte Spione sind.', '', 28153),
(159434, 'deDE', 'Grüne Haut... widerlich! Man hat mir von dieser Verderbnis erzählt, aber ich habe sie noch nie gesehen.', 'Grüne Haut... widerlich! Man hat mir von dieser Verderbnis erzählt, aber ich habe sie noch nie gesehen.', 28153),
(159433, 'deDE', 'Schweigt! Die Oberanführerin wird über Euer Schicksal entscheiden. Fesselt sie!', '', 28153),
(159432, 'deDE', 'Lasst ab! Wir kommen in Frieden, um mit Eurem Kriegshäuptling zu sprechen.', '', 28153),
(159431, 'deDE', 'Eindringlinge!', 'Eindringlinge!', 28153),
(159430, 'deDE', 'Warum wollt Ihr denn überhaupt in unsrem Land rumbuddeln? Wenn\'s unbedingt sein muss, findet Ihr Forscherin Alerinda im Großen Siegel.', 'Warum wollt Ihr denn überhaupt in unsrem Land rumbuddeln? Wenn\'s unbedingt sein muss, findet Ihr Forscherin Alerinda im Großen Siegel.', 28153),
(159429, 'deDE', 'Archäologie', 'Archäologie', 28153),
(159428, 'deDE', 'Was hat\'n der Leerenvoodookram hier zu such\'n?', 'Was hat\'n der Leerenvoodookram hier zu such\'n?', 28153),
(159427, 'deDE', 'Was is\' das für \'n Voodoo?', 'Was is\' das für \'n Voodoo?', 28153),
(159426, 'deDE', 'Was is\' das für \'n dunkler Voodookram?', 'Was is\' das für \'n dunkler Voodookram?', 28153),
(159425, 'deDE', 'Geht. Aber achtet darauf, Euch nicht zwischen den Fäden des Schicksals zu verlieren.', '', 28153),
(159424, 'deDE', 'Ich werde den Splitter mit Euch hindurchschicken. Wenn Ihr bereit seid, wird er Euch nach Hause bringen.', '', 28153),
(159423, 'deDE', 'Könnt Ihr den Weg lange genug offenhalten, damit wir die Orcs von Draenor hindurchbringen können?', '', 28153),
(159422, 'deDE', 'Die Ströme der Zeit und der Realität verändern sich ständig. Der Anker in die Welt, die Ihr sucht, wird schwach sein.', '', 28153),
(159421, 'deDE', 'Wie komme ich nach Orgrimmar?', 'Wie komme ich nach Orgrimmar?', 28153),
(159420, 'deDE', 'Unser Kampf hier is\' vorbei, aber der Krieg geht weiter.', '', 28153),
(159419, 'deDE', 'Unser Kriegshäuptling duldet keine Ausreden. Es sieht so, aus als müsste $p nach Tanaris reisen. Meine alten Knochen brauchen Ruhe.', '', 28153),
(159418, 'deDE', 'Wäre das Fragment der Vision der Zeit nicht erschöpft, könnte ich Euch damit schicken, wohin Ihr möchtet. Aber meine Spezialität ist Teleportation, nicht Chronomantie.', '', 28153),
(159417, 'deDE', 'Ihr solltet zur Handwerkerterrasse auf der unt\'ren Westseite von Dazar\'alor geh\'n.\n\nIhr werdet in ganz Azeroth keinen stärk\'ren Schmied als Schmiedemeister Zak\'aal find\'n!', 'Ihr solltet zur Handwerkerterrasse auf der unt\'ren Westseite von Dazar\'alor geh\'n.\n\nIhr werdet in ganz Azeroth keinen stärk\'ren Schmied als Schmiedemeister Zak\'aal find\'n!', 28153),
(159416, 'deDE', '', 'Die Tiere hier sin\' wirklich erstaunlich. Krag\'wa is\' in der Nähe. Ich frag mich, ob die Gegenwart von \'nem Loa sie stärker macht. Wollt Ihr mal Eure Tiere gegen meine antret\'n lass\'n?', 28153),
(159415, 'deDE', '', 'Pa\'ku kichert unheilvoll.', 28153),
(159414, 'deDE', 'Was für eine Erleichterung!', 'Was für eine Erleichterung!', 28153),
(159413, 'deDE', 'Der Schmerz ist verflogen!', 'Der Schmerz ist verflogen!', 28153),
(159412, 'deDE', 'Das fühlt sich schon viel besser an.', 'Das fühlt sich schon viel besser an.', 28153),
(159411, 'deDE', 'Es ist mir eine Ehre, Generalin. $p, sitzt auf Flinkschwinge auf, wann immer Ihr bereit seid.', '', 28153),
(159410, 'deDE', '', 'Falstad, Ihr geht mit $p voraus. Ich reite auf Jai\'alator.', 28153),
(159409, 'deDE', 'Ahh... verstehe. Vielleicht is\' es ihm nich\' bestimmt, durch die Lüfte zu gleit\'n, aber mit Euch an seiner Seite wird trotzdem alles gut werd\'n.', '', 28153),
(159408, 'deDE', 'Wir flieg\'n voraus. Vertraut einander un\' der Rest kommt von allein. Und jetzt schwingt Euch in die Luft!', '', 28153),
(159407, 'deDE', 'Keine Sorge! Euerm geflügelt\'n Freund geht\'s gut. Ich hab \'nen Plan.', '', 28153),
(159405, 'deDE', 'Kumali die Kluge braut alles mögliche Mojo auf der Handwerkerterrasse zusamm\'. Ihr findet sie am Fuß der Westseite von Dazar\'alor.', 'Kumali die Kluge braut alles mögliche Mojo auf der Handwerkerterrasse zusamm\'. Ihr findet sie am Fuß der Westseite von Dazar\'alor.', 28153),
(159404, 'deDE', 'Da die Mitglieder der Horde unsere exklusiven Leistungen schon so lange nutzen, haben wir für verdiente Personen wie Euch Magierportale bereitgestellt. Ich verspreche Euch, dass die Reise größtenteils schmerzlos verläuft.', 'Da die Mitglieder der Horde unsere exklusiven Leistungen schon so lange nutzen, haben wir für verdiente Personen wie Euch Magierportale bereitgestellt. Ich verspreche Euch, dass die Reise größtenteils schmerzlos verläuft.', 28153),
(159403, 'deDE', '', 'Hahahaha!', 28153),
(159402, 'deDE', '', 'Mögen die Winde Euch tragen!', 28153),
(159401, 'deDE', 'Wie komme ich nach Tirisfal?', 'Wie komme ich nach Tirisfal?', 28153),
(159399, 'deDE', 'Die Donnersturm wird gerade instand gesetzt. Sie hat zu oft Feuer gefangen. Eine Schande.', '', 28153),
(159398, 'deDE', 'Ja, Pa\'ku.', 'Ja, Pa\'ku.', 28153),
(159397, 'deDE', 'Wir ham die besten Ausbilder in der ganzen Welt. Die meist\'n von denen findet Ihr auf der unt\'ren Westseite von Dazar\'alor, auf der Handwerkerterrasse.\n\nSucht Ihr wen Bestimmtes?', 'Wir ham die besten Ausbilder in der ganzen Welt. Die meist\'n von denen findet Ihr auf der unt\'ren Westseite von Dazar\'alor, auf der Handwerkerterrasse.\n\nSucht Ihr wen Bestimmtes?', 28153),
(159396, 'deDE', '', 'Ahhh, ich habe gespürt, dass Ihr bald zu mir kommen würdet. Die letzte Lehrstunde Eures Jungen ist eine Weile her.\n\nKommt, sehen wir, was er gelernt hat.', 28153),
(159395, 'deDE', 'Ausbilder', 'Ausbilder', 28153),
(159394, 'deDE', 'Haustiere? Die einzigen Begleiter, die man hab\'n sollte, sin\' die Kinder der Loa.\n\nIhr findet Bestienzähmer Kalatak am nordwestlichen Fuß von Dazar\'alor.', 'Haustiere? Die einzigen Begleiter, die man hab\'n sollte, sin\' die Kinder der Loa.\n\nIhr findet Bestienzähmer Kalatak am nordwestlichen Fuß von Dazar\'alor.', 28153),
(159392, 'deDE', 'Wenn Ihr getan habt, was König Rastakhan wollte, dann hat Natal\'hakata im Großen Siegel vielleicht was Schönes für Euch.', 'Wenn Ihr getan habt, was König Rastakhan wollte, dann hat Natal\'hakata im Großen Siegel vielleicht was Schönes für Euch.', 28153),
(159391, 'deDE', 'Abgesandte', 'Abgesandte', 28153),
(159390, 'deDE', '', 'Tirisfal hat über die Jahre große Mächte aufsteigen sehen... um dann Zeuge ihres Falls zu werden. Aber ich frage mich... wird Eure Art jemals wirklich Lehren aus ihrer Geschichte ziehen?\n\nAber ich schweife ab.\n\nHabt Ihr die Rechnungen der Vergangenheit beglichen, Champion?', 28153),
(159389, 'deDE', '', 'Teldrassil war... ein überwältigender Anblick, nicht wahr? Oft sind die schönsten Dinge auch die vergänglichsten.\n\nInsbesondere dann, wenn Sterbliche meinen, sie mit Feuer bombardieren zu müssen.\n\nHabt Ihr die Rechnungen der Vergangenheit beglichen, Champion?', 28153),
(159388, 'deDE', 'Wenn Ihr glaubt, Ihr könnt Euch trotz dem rumtanzend\'n toten Ding ausruh\'n, findet Ihr sie im Großen Siegel.', 'Wenn Ihr glaubt, Ihr könnt Euch trotz dem rumtanzend\'n toten Ding ausruh\'n, findet Ihr sie im Großen Siegel.', 28153),
(159386, 'deDE', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis beginnt, |cFFFF0000|Hspell:267242|h[Ansteckung]|h|r zu wirken!', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis beginnt, |cFFFF0000|Hspell:267242|h[Ansteckung]|h|r zu wirken!', 28153),
(159385, 'deDE', 'Alle Anträge auf Unterkunft werden einzeln geprüft und priorisiert.', '', 28153),
(159384, 'deDE', '', 'Von dieser Küste aus könnt Ihr Teldrassil sehen. Die einstige Wiege des Lebens ist jetzt nur noch Asche und Feuer.\n\nSogar die Weltenbäume müssen sich dem Kreislauf des Lebens beugen. Alles Geborene wird sterben.\n\nNiemand versteht das besser als der bronzene Drachenschwarm.\n\nMöchtet Ihr den Baum so sehen, wie er einst war?', 28153),
(159383, 'deDE', 'Bedauerlicherweise sind unsere Mittel momentan ziemlich begrenzt.', '', 28153),
(159382, 'deDE', 'Ihr findet Paku\'ai auf der Terrasse außerhalb vom Großen Siegel. Wo wollt Ihr \'n hin?', 'Ihr findet Paku\'ai auf der Terrasse außerhalb vom Großen Siegel. Wo wollt Ihr \'n hin?', 28153),
(159381, 'deDE', 'Habt bitte etwas Geduld. Wir tun alles, was uns unter diesen Umständen möglich ist.', '', 28153),
(159379, 'deDE', '', 'Tirisfal... ein Ort von Schönheit und Dunkelheit gleichermaßen. Ein Land der Reue... und der Gräber.\n\nImmer und immer wieder kämpfte Eure Art, um ihren Anspruch darauf geltend zu machen.\n\nMöchtet Ihr es sehen, wie es vor dem letzten Krieg war?', 28153),
(159378, 'deDE', 'Ich war das Ziegenfleisch langsam leid.', '', 28153),
(159377, 'deDE', 'Wer ist dabei?', '', 28153),
(159376, 'deDE', 'Wir bringen Euch mitsamt einem kleinen Trupp in null Komma nichts dorthin.', '', 28153),
(159375, 'deDE', 'Falstad Wildhammer pfeift, und Greifenreiter setzen zur Landung auf dem Deck ein.', '', 28153),
(159374, 'deDE', 'Euer Schiff ist zu langsam, um rechtzeitig dort zu sein. Aber für die Wildhämmer ist Geschwindigkeit kein Problem.', '', 28153),
(159373, 'deDE', 'Wenn Dreven an Bord dieses Bootes ist, steckt er in der Klemme. Er kann nicht entkommen... solange wir zuschlagen, bevor sie Land erreichen.', '', 28153),
(159372, 'deDE', '', 'Auf meiner Jagd habe ich erfahren, dass Blutprinz Dreven eine Schiffsreise mit einem verräterischen Gezeitenweisen angetreten hat.', 28153),
(159371, 'deDE', '', 'Ich meine sogar, es verdient allerhöchste Priorität. Danke, Mathias.', 28153),
(159370, 'deDE', '', 'Shandris Mondfeder setzt mit ihrem Hippogryphen im Sturzflug zur Landung auf Deck an.', 28153),
(159369, 'deDE', 'Wir sind nicht sicher, aber ich kann ein paar Agenten entsenden, um dem auf den Grund zu gehen. Es muss nicht oberste Priorität haben.', '', 28153),
(159368, 'deDE', 'Was könnte die Horde in alten Schiffswracks suchen...?', '', 28153),
(159367, 'deDE', 'Habt Dank, Mathias.', '', 28153),
(159366, 'deDE', 'Natürlich haben wir dafür gesorgt, dass das Original ohne Anzeichen von Manipulation seinen ursprünglichen Adressaten erreicht, und eine Kopie für Euch angefertigt.', '', 28153),
(159365, 'deDE', 'Hochkommandant, meine Agenten haben Befehle von Sylvanas abgefangen.', '', 28153),
(159364, 'deDE', 'Mein Volk wird im Umgang mit der Leere nicht den gleichen Fehler machen, das verspreche ich.', '', 28153),
(159363, 'deDE', '', 'Wie Ihr schon sagtet, Umbric: Ich habe ein langes Leben hinter mir. Ich habe gesehen, dass Macht auch die edelmütigsten Völker zu korrumpieren vermag... Zurückhaltung wurde nur selten geübt.', 28153),
(159362, 'deDE', 'Ihr klingt überrascht. Glaubt Ihr, mein Volk geht mit Leerenmagie um, als sei sie ein Spielzeug?', '', 28153),
(159361, 'deDE', '', 'Sie zum Schutz einsetzen? Interessant, Umbric.', 28153),
(159360, 'deDE', 'Man kann sich die Leere zum Schutz dienstbar machen, solange man nicht ihrer Macht verfällt.', '', 28153),
(159359, 'deDE', '', 'Und Ihr scheint Euch nicht zu scheuen, Eure Leerenkräfte gegen sie einzusetzen.', 28153),
(159358, 'deDE', 'Wir haben beide ein langes Leben hinter uns, Shandris. Ich kenne viele, die unter der Barbarei der Zandalari leiden mussten.', '', 28153),
(159357, 'deDE', '', 'Hört sich an, als hättet Ihr schon mal mit diesen Zandalari zu tun gehabt.', 28153),
(159356, 'deDE', 'Meine Leute und ich werden nicht zulassen, dass diese monströsen Trolle die Allianz auslöschen. Dafür habt Ihr mein Wort.', '', 28153),
(159355, 'deDE', '', 'Erstaunlich, wie viele Wachen es hier im Hafen gibt. Sie machen sich wohl bereit, die Flotte loszuschicken.', 28153),
(159354, 'deDE', '', 'Wir müssen Halford sofort warnen, sobald wir $n abgesetzt haben.', 28153),
(159353, 'deDE', 'Es ist schlimm, wenn man bedenkt, dass sein Kurs in Sichtweite unseres Außenpostens in Xibala verläuft!', '', 28153),
(159352, 'deDE', '', 'Ein Schiff? Das hört sich nicht allzu schlimm an.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159351, 'deDE', 'Wir haben ein Problem. Es gibt da ein Schiff, das wir übersehen haben. Vielleicht war es eins, das in Pandaria stationiert war?', '', 28153),
(159350, 'deDE', 'Mal sehen. Scheint so, als läge Halford mit seinen Informationen richtig, was die Lage der meisten Schiffe und ihre Routen anbelangt. Allerdings...', '', 28153),
(159349, 'deDE', '', 'Normalerweise spicke ich nicht... aber dieses Mal kann ich wohl eine Ausnahme machen. Mal schauen...', 28153),
(159348, 'deDE', 'Enthalten die von $n beschafften Aufzeichnungen irgendwelche neuen Informationen?', '', 28153),
(159347, 'deDE', '', 'Viel Glück! Am Kriegshafen der Rastari wird es von Zandalari nur so wimmeln. Aber Shandris hat sicher einen Plan.', 28153),
(159346, 'deDE', 'Wenn Ihr Euer Ausseh\'n ma\' verändern wollt, geht Ihr am besten zu den seltsamen Goblins im Großen Basar beim Hafen.', 'Wenn Ihr Euer Ausseh\'n ma\' verändern wollt, geht Ihr am besten zu den seltsamen Goblins im Großen Basar beim Hafen.', 28153),
(159343, 'deDE', 'In dieser Gegend laufen alle möglichen Viecher rum. Es gibt hier ganz normale Kaninchen, Eichhörnchen und Biber, aber auch ganz seltsame Kreaturen, die aussehen wie ein laufendes Bündel Stöcke. Ich habe ein paar Tage gebraucht, eines davon zu fangen und abzurichten, aber jetzt ist es ganz anhänglich. Nicht falsch verstehen: wenn sie einen mit einem ihrer Stöcke pieksen, schreit man trotzdem vor Schmerzen, aber ich finde sie trotzdem großartig. Wollt Ihr mal sehen, wie die loslegen?', '', 28153),
(159342, 'deDE', 'Die königliche Waffenkammer is\' genau in der Mitte von der Pyramide neben dem Großen Siegel.', 'Die königliche Waffenkammer is\' genau in der Mitte von der Pyramide neben dem Großen Siegel.', 28153),
(159340, 'deDE', 'Zeit, ein paar Bomben zu legen... und sie nicht in die Luft zu jagen. Vorerst.', '', 28153),
(159339, 'deDE', '', 'Sagt nicht so etwas, Finn. Wir müssen weiter hoffen, dass Lady Jaina noch am Leben ist!', 28153),
(159338, 'deDE', '$n, bitte richtet Lady Katherine mein aufrichtiges Beileid aus.', '', 28153),
(159337, 'deDE', 'Schicksalsend... nicht MEIN bevorzugtes Ende, das steht fest.', '', 28153),
(159336, 'deDE', 'Lasst uns spielen!', 'Lasst uns spielen!', 28153),
(159335, 'deDE', 'Nehmt Euch ihr Glitzerzeug!', 'Nehmt Euch ihr Glitzerzeug!', 28153),
(159334, 'deDE', 'Oooh, Ihr habt Glitzerzeug!', 'Oooh, Ihr habt Glitzerzeug!', 28153),
(159333, 'deDE', 'Kommt und spielt mit uns!', 'Kommt und spielt mit uns!', 28153),
(159332, 'deDE', 'Ha ha ha!', 'Ha ha ha!', 28153),
(159331, 'deDE', 'Reingefallen!', 'Reingefallen!', 28153),
(159330, 'deDE', 'Hab Euch!', 'Hab Euch!', 28153),
(159329, 'deDE', 'He he he!', 'He he he!', 28153),
(159228, 'deDE', '', 'Seid vorsichtig. Ich warte auf Euer Signal.', 28153),
(159227, 'deDE', 'Wenn Ihr so weit seid, treffen wir uns in Freihafen.', '', 28153),
(159226, 'deDE', 'Besorgt Ihr ein paar Granaten. Ich muss zu einer Dame, die einen Vogel hat.', '', 28153),
(159225, 'deDE', 'Schätze, selbst in diesem schwülstigen Rechtswirrwarr wollten sie nicht riskieren, den Zielort zu verraten. Aber ich bin fast todsicher, wo wir das rausfinden können.', '', 28153),
(159224, 'deDE', 'Vielleicht steht was im Kleingedruckten...', '', 28153),
(159223, 'deDE', 'Lady Katherine will, dass Ihr ihre Tochter findet, was? Na, dann schauen wir mal im Vertrag nach, wohin sie gebracht werden soll.', '', 28153),
(159222, 'deDE', 'Kommt schon! Wohin soll Jaina \"befördert\" werden?', '', 28153),
(159221, 'deDE', 'Noch mehr Klauseln und Erklärungen... rechtlicher Schnickschnack, den nur ein Gauner von Richter anerkennen würde...', '', 28153),
(159220, 'deDE', 'Zehn Seiten mit Sicherheitsauflagen... zwanzig Seiten Haftungsklauseln...', '', 28153),
(159219, 'deDE', 'Beschreibung der Dienstleistungen: Der Transporteur wird dem Kunden bla bla bla...', '', 28153),
(159218, 'deDE', 'Dienstleistungsvertrag... zwischen Handelskompanie Aschenwind und so weiter... Puh, wer schreibt dieses Zeug?', '', 28153),
(159217, 'deDE', '', 'Durch die Barriere! Schnell! Ich halte nicht mehr lange durch!', 28153),
(159216, 'deDE', 'Lady Katherine hat mich gebeten, ihre Tochter zu suchen. Das ist der einzige Hinweis, den ich bisher habe.', 'Lady Katherine hat mich gebeten, ihre Tochter zu suchen. Das ist der einzige Hinweis, den ich bisher habe.', 28153),
(159215, 'deDE', 'He, $n. Schön, Euch zu sehen.', '', 28153),
(159214, 'deDE', '', 'Kehrt zurück, sobald Ihr entdeckt habt, wohin Jaina verschleppt wurde, $n.', 28153),
(159213, 'deDE', '', 'Ich hoffe, Ihr habt Recht, Genn.', 28153),
(159212, 'deDE', '$n ist das Beste, das die Allianz zu bieten hat, Katherine. Jainas Rettung könnte nicht in fähigeren Händen liegen.', '', 28153),
(159211, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Ihr seid mit dem |cFFFF0000|Hspell:265129|h[Omegavektor]|h|r infiziert!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Ihr seid mit dem |cFFFF0000|Hspell:265129|h[Omegavektor]|h|r infiziert!', 28153),
(159210, 'deDE', 'Wartet! Benutzt den Talisman der Kontrolle!', '', 28153),
(159209, 'deDE', 'So, bitte alles aussteigen. Seid vorsichtig und denkt daran: Platziert die Bomben, ohne dass sie Eure Anwesenheit bemerken und das Festland alarmieren!', '', 28153),
(159208, 'deDE', '...Das könnte der Beginn einer wunderbaren Freundschaft sein.', '', 28153),
(159207, 'deDE', '', 'Eine? Aber nein, nein, ich habe MEHRERE Messersammlungen.', 28153),
(159206, 'deDE', 'Ihr habt eine Messersammlung?', '', 28153),
(159205, 'deDE', '', 'Ihr seid ein Kerl nach meinem Geschmack, Keeshan. Wenn das hier vorbei ist, sollten wir mal unsere Messersammlungen vergleichen.', 28153),
(159204, 'deDE', 'Und ich helfe $n, Kelseys Bomben an den kleineren Schiffen zu platzieren... und jeden Zandalari auszuweiden, der mich dabei sieht.', '', 28153),
(159203, 'deDE', '', 'Ich arbeite derweil an einer Vorrichtung, die $n für den nächsten Teil unseres Plans übers Wasser bringt.', 28153),
(159202, 'deDE', 'Ihr müsst bloß dafür sorgen, dass sie nicht merken, wie Ihr Bomben an den Kielen ihrer Schiffe anbringt.', '', 28153),
(159201, 'deDE', 'Das braucht Ihr mir nicht zweimal zu sagen. Ich setze Euch auf der Insel der Klauen ab. Sie liegt weit genug von der Stadt entfernt, dass ihr ungestraft gegen die Zandalari vorgehen könnt.', '', 28153),
(159200, 'deDE', 'Ich wurde schon mal fast gefressen. Empfehlen kann ich es nicht.', '', 28153),
(159199, 'deDE', '', 'Sie würden uns ihren Schoßtierdinos zum Fraß vorwerfen. Und die würden uns zu Hackfleisch zermalmen.', 28153),
(159198, 'deDE', 'Ja. Vereinzelte Einheiten zu finden, wie beispielsweise $n hier, ist eine Sache. Aber wenn sie das ganze verdammte Lager bemerken?', '', 28153),
(159197, 'deDE', '', 'Was glaubt Ihr, warum Halford es so eilig hat? Er weiß genau, dass wir verloren sind, wenn die Zandalari uns auf feindlichem Gebiet erwischen.', 28153),
(159196, 'deDE', 'Dieses Allianzlager ist nicht gerade unauffällig. Wir bereiten uns besser darauf vor, dass die Zandalari uns entdecken.', '', 28153),
(159195, 'deDE', 'So! Das sollte hoch genug sein, um zu vermeiden, dass die Zandalari uns entdecken.', '', 28153),
(159194, 'deDE', 'Gut festhalten! Wir müssen GANZ hoch hinaus, wenn wir nicht wollen, dass man uns bemerkt!', '', 28153),
(159193, 'deDE', '', 'Schaut vorbei, wann immer Ihr möchtet, $p.', 28153),
(159192, 'deDE', '', 'Nie tragt Ihr Euren Mantel, Schätzchen. Ihr holt Euch noch eine Erkältung, wenn Ihr nicht aufpasst!', 28153),
(159191, 'deDE', '', 'Ich hoffe, Ihr kommt auch mal dazu, Euch zu erholen. Monster wird es immer genug zu bekämpfen geben!', 28153),
(159190, 'deDE', 'Besprechen wir unseren Plan, die Zandalariflotte zu schwächen.', 'Besprechen wir unseren Plan, die Zandalariflotte zu schwächen.', 28153),
(159189, 'deDE', 'Wie könnt Ihr... es WAGEN...?', 'Wie könnt Ihr... es WAGEN...?', 28153),
(159188, 'deDE', 'Die zerschmetternde Flut... wird kommen...', 'Die zerschmetternde Flut... wird kommen...', 28153),
(159187, 'deDE', 'Die Dunkelheit... ist nur vorübergehend...', 'Die Dunkelheit... ist nur vorübergehend...', 28153),
(159186, 'deDE', 'Anmaßende... Brut...', 'Anmaßende... Brut...', 28153),
(159185, 'deDE', 'Wir haben Tausende von Konstrukten... Ihr könnt nicht gewinnen...', 'Wir haben Tausende von Konstrukten... Ihr könnt nicht gewinnen...', 28153),
(159184, 'deDE', 'Mein Geist... wird... zurückkehren...', 'Mein Geist... wird... zurückkehren...', 28153),
(159183, 'deDE', 'Mit meinem Tod wird es nicht aufhören...', 'Mit meinem Tod wird es nicht aufhören...', 28153),
(159182, 'deDE', 'Wir werden... wiederkommen...', 'Wir werden... wiederkommen...', 28153),
(159181, 'deDE', 'Der Tod ist nur der Beginn Eurer Bestrafung!', 'Der Tod ist nur der Beginn Eurer Bestrafung!', 28153),
(159180, 'deDE', '', 'Hallöchen! Mögt Ihr mir mit der einen oder anderen Besorgung zur Hand gehen? Natürlich nur, wenn es Euch keine Umstände macht!', 28153),
(159179, 'deDE', 'Euer Schicksal ist besiegelt.', 'Euer Schicksal ist besiegelt.', 28153),
(159178, 'deDE', 'Kniet nieder, Eindringling!', 'Kniet nieder, Eindringling!', 28153),
(159177, 'deDE', 'Euer Tod wird langsam sein, Eindringling!', 'Euer Tod wird langsam sein, Eindringling!', 28153),
(159176, 'deDE', 'Wir waren vor Eurer Art hier. Wir werden hier sein, wenn Ihr vergeht!', 'Wir waren vor Eurer Art hier. Wir werden hier sein, wenn Ihr vergeht!', 28153),
(159175, 'deDE', 'Anmaßende Fleischkreatur!', 'Anmaßende Fleischkreatur!', 28153),
(159174, 'deDE', 'Ihr werdet lernen, Euch unterzuordnen!', 'Ihr werdet lernen, Euch unterzuordnen!', 28153),
(159173, 'deDE', 'Schwache haben in dieser Welt nichts zu suchen!', 'Schwache haben in dieser Welt nichts zu suchen!', 28153),
(159172, 'deDE', 'Was tot ist... kann nicht sterben...', 'Was tot ist... kann niemals sterben...', 28153),
(159171, 'deDE', 'Ich kehre zu ihr zurück, nur für einen Moment...', 'Ich kehre zu ihr zurück, nur für einen Moment...', 28153),
(159170, 'deDE', 'Wir werden nicht in den Tiefen vergessen werden...', 'Wir werden nicht in den Tiefen vergessen werden...', 28153),
(159169, 'deDE', 'Sie wird uns von dieser Qual befreien...', 'Sie wird uns von dieser Qual befreien...', 28153),
(159168, 'deDE', 'Sie wird die goldene Flüssigkeit bekommen... Ihr könnt uns nicht alle aufhalten...', 'Sie wird die goldene Flüssigkeit bekommen... Ihr könnt uns nicht alle aufhalten...', 28153),
(159167, 'deDE', 'Wir sind ewig... Euer Sieg bedeutet nichts...', 'Wir sind ewig... Euer Sieg bedeutet nichts...', 28153),
(159166, 'deDE', 'Sie wird mich zurückbringen...', 'Sie wird mich zurückbringen...', 28153),
(159165, 'deDE', 'Sterbliche können uns... nicht töten...', 'Sterbliche können uns... nicht töten...', 28153),
(159164, 'deDE', 'Ich werde Euch Euren Atem aus den Lungen stehlen!', 'Ich werde Euch Euren Atem aus den Lungen stehlen!', 28153),
(159163, 'deDE', 'Diese Gewässer gehören uns!', 'Diese Gewässer gehören uns!', 28153),
(159162, 'deDE', 'Die Tiefen werden Eure brüchigen Knochen zermalmen!', 'Die Tiefen werden Eure brüchigen Knochen zermalmen!', 28153),
(159161, 'deDE', 'Die Gezeiten werden Euch holen!', 'Die Gezeiten werden Euch holen!', 28153),
(159160, 'deDE', 'Helya ruft Euch!', 'Helya ruft Euch!', 28153),
(159159, 'deDE', 'Eure Seelen werden uns gehören!', 'Eure Seelen werden uns gehören!', 28153),
(159158, 'deDE', 'Ihr werdet uns in den Tod folgen. Ihr werdet Euch ihrer Armee anschließen!', 'Ihr werdet uns in den Tod folgen. Ihr werdet Euch ihrer Armee anschließen!', 28153),
(159157, 'deDE', 'Die Nebel kommen Euch holen!', 'Die Nebel kommen Euch holen!', 28153),
(159156, 'deDE', 'Ihr werdet niemals über die See herrschen...', 'Ihr werdet niemals über die See herrschen...', 28153),
(159155, 'deDE', 'Einer stirbt, aber es gibt noch Tausende...', 'Einer stirbt, aber es gibt noch Tausende...', 28153),
(159154, 'deDE', 'Glaubt nicht, dass Ihr gewonnen habt...', 'Glaubt nicht, dass Ihr gewonnen habt...', 28153),
(159153, 'deDE', 'Ihr habt... keine Zukunft...', 'Ihr habt... keine Zukunft...', 28153),
(159152, 'deDE', 'Der Tod wird Euch holen...', 'Der Tod wird Euch holen...', 28153),
(159151, 'deDE', 'Nur Azshara zählt...', 'Nur Azshara zählt...', 28153),
(159150, 'deDE', 'Meine Azshara... Ich kehre zurück in die Wellen...', 'Meine Azshara... Ich kehre zurück in die Wellen...', 28153),
(159149, 'deDE', 'Meine Königin...', 'Meine Königin...', 28153),
(159148, 'deDE', 'Die sich windende Gottheit der Tiefe wartet auf Euch!', 'Die sich windende Gottheit der Tiefe wartet auf Euch!', 28153),
(159147, 'deDE', 'Die Augen in der Tiefe werden Euch in den Wahnsinn treiben!', 'Die Augen in der Tiefe werden Euch in den Wahnsinn treiben!', 28153),
(159146, 'deDE', 'Fühlt Ihr die Angst? Den unendlichen Schrecken in den Tiefen?', 'Fühlt Ihr die Angst? Den unendlichen Schrecken in den Tiefen?', 28153),
(159145, 'deDE', 'Das schwarze Imperium wird auf dieser Welt wiedergeboren. Und seine Seele wird die Großen nähren!', 'Das schwarze Imperium wird auf dieser Welt wiedergeboren. Und seine Seele wird die Großen nähren!', 28153),
(159144, 'deDE', 'Wir haben lang genug gewartet. Das Zeitalter der Naga ist gekommen!', 'Wir haben lang genug gewartet. Das Zeitalter der Naga ist gekommen!', 28153),
(159143, 'deDE', 'Die Versunkene Stadt wird sich erheben. Euer Untergang naht!', 'Die Versunkene Stadt wird sich erheben. Euer Untergang naht!', 28153),
(159142, 'deDE', 'N\'Zoth ruft nach uns allen. Könnt Ihr es nicht hören?', 'N\'Zoth ruft nach uns allen. Könnt Ihr es nicht hören?', 28153),
(159141, 'deDE', 'Für die große Königin Azshara! Lang möge sie herrschen!', 'Für die große Königin Azshara! Lang möge sie herrschen!', 28153),
(159140, 'deDE', 'Eure Zeit ist abgelaufen!', 'Eure Zeit ist abgelaufen!', 28153),
(159139, 'deDE', 'Wir kommen aus den Tiefen!', 'Wir kommen aus den Tiefen!', 28153),
(159138, 'deDE', 'Tötet sie!', 'Tötet sie!', 28153),
(159137, 'deDE', 'Ihr werdet leidvoll ertrinken!', 'Ihr werdet leidvoll ertrinken!', 28153),
(159136, 'deDE', 'Die sich Windende singt zu uns!', 'Die sich Windende singt zu uns!', 28153),
(159135, 'deDE', 'Die flüsternden Tiefen rufen Euch!', 'Die flüsternden Tiefen rufen Euch!', 28153),
(159134, 'deDE', 'Für Azshara!', 'Für Azshara!', 28153),
(159133, 'deDE', 'Kriecht zurück, wo Ihr hergekommen seid!', 'Kriecht zurück, wo Ihr hergekommen seid!', 28153),
(159132, 'deDE', 'Fluch des Fleisches entdeckt. Starte Säuberungsprotokoll.', 'Fluch des Fleisches entdeckt. Starte Säuberungsprotokoll.', 28153),
(159131, 'deDE', 'Euer Körper ist schwach und formbar. Lasst mich ihn neu gestalten.', 'Euer Körper ist schwach und formbar. Lasst mich ihn neu gestalten.', 28153),
(159130, 'deDE', 'Ihr wolltet der Weltenseele schaden und ihr Blut stehlen. Ihr müsst neu geformt werden.', 'Ihr wolltet der Weltenseele schaden und ihr Blut stehlen. Ihr müsst neu geformt werden.', 28153),
(159129, 'deDE', 'Wir sind die Verteidiger dieser Weltenseele. Ihr dürft nicht fortfahren.', 'Wir sind die Verteidiger dieser Weltenseele. Ihr dürft nicht fortfahren.', 28153),
(159128, 'deDE', 'Ihr hindert uns an der Ausübung der heiligen Pflicht und müsst eliminiert werden.', 'Ihr hindert uns an der Ausübung der heiligen Pflicht und müsst eliminiert werden.', 28153),
(159127, 'deDE', 'Die Verfluchten müssen neu geschaffen werden. So lautet unser Auftrag.', 'Die Verfluchten müssen neu geschaffen werden. So lautet unser Auftrag.', 28153),
(159126, 'deDE', 'Wir wurden geformt, um diese Welt vor den Fleischverfluchten zu beschützen.', 'Wir wurden geformt, um diese Welt vor den Fleischverfluchten zu beschützen.', 28153),
(159125, 'deDE', 'Wir wurden geschaffen, Euch von der Krankheit zu befreien. Bitte haltet still.', 'Wir wurden geschaffen, Euch von der Krankheit zu befreien. Bitte haltet still.', 28153),
(159124, 'deDE', 'Ihr werdet nichts an unseren Weisungen ändern...', 'Ihr werdet nichts an unseren Weisungen ändern...', 28153),
(159123, 'deDE', 'Wir werden alles wiederaufbauen... immer wieder...', 'Wir werden alles wiederaufbauen... immer wieder...', 28153),
(159122, 'deDE', 'Unsere Mission... darf nicht scheitern...', 'Unsere Mission... darf nicht scheitern...', 28153),
(159121, 'deDE', 'Eure Handlungen führen zum Ende Eurer Welt...', 'Eure Handlungen führen zum Ende Eurer Welt...', 28153),
(159120, 'deDE', 'Wir müssen die Weltenseele... beschützen...', 'Wir müssen die Weltenseele... beschützen...', 28153),
(159119, 'deDE', 'Ihr versteht nicht...', 'Ihr versteht nicht...', 28153),
(159118, 'deDE', 'Dies ist... nicht unser Schicksal...', 'Dies ist... nicht unser Schicksal...', 28153),
(159117, 'deDE', 'Die Former... werden zurückkehren...', 'Die Former... werden zurückkehren...', 28153),
(159116, 'deDE', 'Ihr seid verloren. Lasst uns Euch neu ausrichten.', 'Ihr seid verloren. Lasst uns Euch neu ausrichten.', 28153),
(159115, 'deDE', 'Unsere heilige Pflicht darf nicht gestört werden.', 'Unsere heilige Pflicht darf nicht gestört werden.', 28153),
(159114, 'deDE', 'Zur Seite! Die Former haben uns diese Welt anvertraut!', 'Zur Seite! Die Former haben uns diese Welt anvertraut!', 28153),
(159113, 'deDE', 'Der Fluch des Fleisches ist außer Kontrolle!', 'Der Fluch des Fleisches ist außer Kontrolle!', 28153),
(159112, 'deDE', 'Wir werden Euch neu erschaffen. Bitte haltet still.', 'Wir werden Euch neu erschaffen. Bitte haltet still.', 28153),
(159111, 'deDE', 'Ihr müsst von Eurer Krankheit geheilt werden.', 'Ihr müsst von Eurer Krankheit geheilt werden.', 28153),
(159110, 'deDE', 'Euer Fleisch ist verflucht. Wir werden Euch heilen.', 'Euer Fleisch ist verflucht. Wir werden Euch heilen.', 28153),
(159109, 'deDE', 'Wir werden das Blut dieses Planeten kontrollieren.', 'Wir werden das Blut dieses Planeten kontrollieren.', 28153),
(159108, 'deDE', 'Zumindest bin ich reich gestorben...', 'Zumindest bin ich reich gestorben...', 28153),
(159107, 'deDE', 'Sagt meinen Kindern... es gibt kein Geld...', 'Sagt meinen Kindern... es gibt kein Geld...', 28153),
(159106, 'deDE', 'Meine Quartalszahlen... bleiben unvergessen...', 'Meine Quartalszahlen... bleiben unvergessen...', 28153),
(159105, 'deDE', 'Wartet! Ich bezahle Euch, wenn Ihr mich wiederbelebt! Kommt schon!', 'Wartet! Ich bezahle Euch, wenn Ihr mich wiederbelebt! Kommt schon!', 28153),
(159104, 'deDE', 'Argh, bei der Qualitätsprüfung durchgefallen...', 'Argh, bei der Qualitätsprüfung durchgefallen...', 28153),
(159103, 'deDE', 'Bitte lasst mir... die Abfindung...', 'Bitte lasst mir... die Abfindung...', 28153),
(159102, 'deDE', 'Ich sehe rote Zahlen!', 'Ich sehe rote Zahlen!', 28153),
(159101, 'deDE', 'Der Markt... bricht zusammen...', 'Der Markt... bricht zusammen...', 28153),
(159100, 'deDE', 'Jetzt ist Zahltag!', 'Jetzt ist Zahltag!', 28153),
(159099, 'deDE', 'Wenn wir sie nicht töten, müssen wir dafür aus der Kaffeekasse aufkommen!', 'Wenn wir sie nicht töten, müssen wir dafür aus der Kaffeekasse aufkommen!', 28153),
(159098, 'deDE', 'Für Euren Kopf erhalte ich eine schöne Sonderauszahlung!', 'Für Euren Kopf erhalte ich eine schöne Sonderauszahlung!', 28153),
(159097, 'deDE', 'Ich habe mir Platz im Terminkalender freigehalten, nur, um Euch zu töten!', 'Ich habe mir Platz im Terminkalender freigehalten, nur, um Euch zu töten!', 28153),
(159096, 'deDE', 'Unseren Gesellschaftern wird Eure Einmischung nicht gefallen!', 'Unseren Gesellschaftern wird Eure Einmischung nicht gefallen!', 28153),
(159095, 'deDE', 'Das reicht! Jetzt werden die ganz harten Personalführungsmethoden ausgepackt!', 'Das reicht! Jetzt werden die ganz harten Personalführungsmethoden ausgepackt!', 28153),
(159094, 'deDE', 'Mit Euch werde ich meinen Profit mehren!', 'Mit Euch werde ich meinen Profit mehren!', 28153),
(159093, 'deDE', 'Euer Tod ist mein Gewinn!', 'Euer Tod ist mein Gewinn!', 28153),
(159092, 'deDE', 'Ihr seid nichts als Konkursmasse!', 'Ihr seid nichts als Konkursmasse!', 28153),
(159091, 'deDE', 'Das ist eine feindliche Übernahme!', 'Das ist eine feindliche Übernahme!', 28153),
(159090, 'deDE', 'Bereitet das Notfallset vor! Wir haben Gesellschaft!', 'Bereitet das Notfallset vor! Wir haben Gesellschaft!', 28153),
(159089, 'deDE', 'Habt Dank! Das habe ich gern getan.', 'Habt Dank! Das habe ich gern getan.', 28153),
(159088, 'deDE', 'Ihr schadet meiner Geschäftsbilanz!', 'Ihr schadet meiner Geschäftsbilanz!', 28153),
(159087, 'deDE', 'Wir können dafür unsere Operation nicht unterbrechen!', 'Wir können dafür unsere Operation nicht unterbrechen!', 28153),
(159086, 'deDE', 'Was wollt Ihr hier? Das Land hier ist Eigentum der Venture Co.! Hat man Euch nicht informiert?', 'Was wollt Ihr hier? Das Land hier ist Eigentum der Venture Co.! Hat man Euch nicht informiert?', 28153),
(159085, 'deDE', 'Ah! Eindringlinge! Verteidigt mich!', 'Ah! Eindringlinge! Verteidigt mich!', 28153),
(159084, 'deDE', 'Schnappt sie! Aber benutzt nur das billige Zeug!', 'Schnappt sie! Aber benutzt nur das billige Zeug!', 28153),
(159083, 'deDE', 'Denkt daran, unser Hauptziel ist es, ihre Verteidigung zu behindern und unsere Streitkräfte hier im Verborgenen zu halten. Wenn man uns entdeckt, ist alles verloren. Für die Allianz!', '', 28153),
(159082, 'deDE', 'Marie Fürbittshafen 20 Tigules und Forors Erdbeereiscremes geben?', 'Marie Fürbittshafen 20 Tigules und Forors Erdbeereiscremes geben?', 28153),
(159081, 'deDE', '', 'Umbric und ich werden Vorbereitungen für einen Überraschungsschlag am Kriegshafen treffen.', 28153),
(159080, 'deDE', 'Ihr marschiert dem Tod Eurer Welt entgegen... von Arroganz geblendet...', 'Ihr marschiert dem Tod Eurer Welt entgegen... von Arroganz geblendet...', 28153),
(159079, 'deDE', 'Wir wollten nur... was uns gehört...', 'Wir wollten nur... was uns gehört...', 28153),
(159078, 'deDE', 'Ihr zögert... das Unausweichliche... nur hinaus...', 'Ihr zögert... das Unausweichliche... nur hinaus...', 28153),
(159077, 'deDE', 'Mein Nachwuchs wird noch stärker... auch ohne mich...', 'Mein Nachwuchs wird noch stärker... auch ohne mich...', 28153),
(159076, 'deDE', 'Der Himmel verfinstert sich...', 'Der Himmel verfinstert sich...', 28153),
(159075, 'deDE', 'Korrekt. $n, Ihr werdet die Hafenverteidigung der Zandalari sabotieren. Kelsey, Falstad und Keeshan werden Euch beim ersten Ziel helfen.', '', 28153),
(159074, 'deDE', 'Wir haben dieses Schicksal... nicht gewählt...', 'Wir haben dieses Schicksal... nicht gewählt...', 28153),
(159073, 'deDE', 'Wir hatten nie... eine echte Chance...', 'Wir hatten nie... eine echte Chance...', 28153),
(159072, 'deDE', 'Wir fallen... erneut...', 'Wir fallen... erneut...', 28153),
(159071, 'deDE', 'Wir werden uns Euch nicht noch einmal beugen. Jetzt erhebt sich der Zwielichtschwarm!', 'Wir werden uns Euch nicht noch einmal beugen. Jetzt erhebt sich der Zwielichtschwarm!', 28153),
(159070, 'deDE', 'Wir brauchen das glühende Erz. Allein können wir nicht überleben. Versteht Ihr nicht?', 'Wir brauchen das glühende Erz. Allein können wir nicht überleben. Versteht Ihr nicht?', 28153),
(159069, 'deDE', '', 'Ah... und dann warten wir genau auf den Moment, in dem unsere Flotten eintreffen, und lassen sie hochgehen. In der Stadt wird Chaos herrschen, sodass wir ungehindert an Land gehen können!', 28153),
(159068, 'deDE', 'Wir wollen nur das, was uns vor so langer Zeit versprochen wurde!', 'Wir wollen nur das, was uns vor so langer Zeit versprochen wurde!', 28153),
(159067, 'deDE', 'Die goldene Flüssigkeit verkündet die Rückkehr unseres Schwarms und Eure Auslöschung!', 'Die goldene Flüssigkeit verkündet die Rückkehr unseres Schwarms und Eure Auslöschung!', 28153),
(159066, 'deDE', 'Wenn wir unsere Arbeit richtig machen, werden die Zandalari niemals merken, dass wir ihre Verteidigungsanlagen mit Sprengsätzen gespickt haben.', '', 28153),
(159065, 'deDE', 'Wir lassen uns jetzt nicht mehr kontrollieren! Verschwindet!', 'Wir lassen uns jetzt nicht mehr kontrollieren! Verschwindet!', 28153),
(159064, 'deDE', 'In der Tat. Shandris, Falstad und ich haben einen Plan vorgelegt, dem König Wrynn zugestimmt hat. Wenn er aufgeht, haben unsere Streitkräfte wenigstens eine Chance.', '', 28153),
(159063, 'deDE', 'Unser Schwarm gehört jetzt uns. Niemand beherrscht uns, Ihr schon gar nicht!', 'Unser Schwarm gehört jetzt uns. Niemand beherrscht uns, Ihr schon gar nicht!', 28153),
(159062, 'deDE', 'Der Zwielichtschwarm kehrt direkt vor Euren Augen zurück. Wie arrogant Ihr seid!', 'Der Zwielichtschwarm kehrt direkt vor Euren Augen zurück. Wie arrogant Ihr seid!', 28153),
(159061, 'deDE', '', 'Deshalb wolltet Ihr alle diese Bomben!', 28153),
(159060, 'deDE', 'Verdrängt von den sogenannten Herrschern dieser Welt... Die Geschichte wird uns nicht vergessen!', 'Verdrängt von den sogenannten Herrschern dieser Welt... Die Geschichte wird uns nicht vergessen!', 28153),
(159059, 'deDE', '', 'Die Zandalari sind stark, aber nicht unbesiegbar. Wir werden Schlüsselpositionen ihrer Hafenverteidigung mit ferngezündeten Bomben außer Gefecht setzen.', 28153),
(159058, 'deDE', 'Dieses Mal könnt Ihr uns nicht aufhalten!', 'Dieses Mal könnt Ihr uns nicht aufhalten!', 28153),
(159057, 'deDE', 'Ruhm dem Zwielicht!', 'Ruhm dem Zwielicht!', 28153),
(159056, 'deDE', 'Wir sind jetzt unsere eigenen Herrscher!', 'Wir sind jetzt unsere eigenen Herrscher!', 28153),
(159055, 'deDE', 'Reden wir nicht lange um den heißen Brei. Die Allianz braucht unsere Unterstützung, damit sie in Zuldazar einfallen kann.', '', 28153),
(159054, 'deDE', 'Wir werden uns nicht wieder verdrängen lassen!', 'Wir werden uns nicht wieder verdrängen lassen!', 28153),
(159053, 'deDE', 'Der vergessene Schwarm wartet jetzt nicht mehr!', 'Der vergessene Schwarm wartet jetzt nicht mehr!', 28153),
(159052, 'deDE', 'Aus der Dunkelheit kommen wir, um über die Welt zu herrschen!', 'Aus der Dunkelheit kommen wir, um über die Welt zu herrschen!', 28153),
(159051, 'deDE', 'Der Zwielichtschwarm wird herrschen!', 'Der Zwielichtschwarm wird herrschen!', 28153),
(159050, 'deDE', 'Für das Zwielicht!', 'Für das Zwielicht!', 28153),
(159049, 'deDE', 'Wir sind die Erdwächter und Ihr werdet uns nicht das nehmen, was uns gehört, Weichhaut!', 'Wir sind die Erdwächter und Ihr werdet uns nicht das nehmen, was uns gehört, Weichhaut!', 28153),
(159048, 'deDE', 'Ihr wisst nicht, wo unser Gelege ist, also könnt Ihr nicht gewinnen. Gebt jetzt auf!', 'Ihr wisst nicht, wo unser Gelege ist, also könnt Ihr nicht gewinnen. Gebt jetzt auf!', 28153),
(159047, 'deDE', 'Der schwarze Drachenschwarm wird ein für alle Mal Rache nehmen!', 'Der schwarze Drachenschwarm wird ein für alle Mal Rache nehmen!', 28153),
(159046, 'deDE', 'Wir schützen die Steine dieser Welt vor Euresgleichen!', 'Wir schützen die Steine dieser Welt vor Euresgleichen!', 28153),
(159045, 'deDE', 'Jämmerliche Fleischkreaturen, das goldene Weltblut steht unter unserem Schutz!', 'Jämmerliche Fleischkreaturen, das goldene Weltblut steht unter unserem Schutz!', 28153),
(159044, 'deDE', 'Diese Welt wurde den Drachen gegeben. Eure Art ist eine Krankheit!', 'Diese Welt wurde den Drachen gegeben. Eure Art ist eine Krankheit!', 28153),
(159043, 'deDE', 'Wie könnt Ihr es wagen, Euch das anzueignen, was rechtmäßig uns gehört?', 'Wie könnt Ihr es wagen, Euch das anzueignen, was rechtmäßig uns gehört?', 28153),
(159042, 'deDE', 'Das Blut der Welt wurde uns anvertraut! Wir sind seine Wächter!', 'Das Blut der Welt wurde uns anvertraut! Wir sind seine Wächter!', 28153),
(159041, 'deDE', 'Ihr stehlt... was rechtmäßig unser ist...', 'Ihr stehlt... was rechtmäßig unser ist...', 28153),
(159040, 'deDE', 'Wir werden nicht von der Geschichte vergessen werden...', 'Wir werden nicht von der Geschichte vergessen werden...', 28153),
(159039, 'deDE', 'Der schwarze Drachenschwarm wird Euch holen...', 'Der schwarze Drachenschwarm wird Euch holen...', 28153),
(159038, 'deDE', 'Ihr könnt diesen Krieg nicht gewinnen...', 'Ihr könnt diesen Krieg nicht gewinnen...', 28153),
(159037, 'deDE', 'Diese Welt gehört... den Drachen...', 'Diese Welt gehört... den Drachen...', 28153),
(159036, 'deDE', 'Euresgleichen gehört... hier nicht hin...', 'Euresgleichen gehört... hier nicht hin...', 28153),
(159035, 'deDE', 'Der schwarze Drachenschwarm kann nicht besiegt werden...', 'Der schwarze Drachenschwarm kann nicht besiegt werden...', 28153),
(159034, 'deDE', 'Wir werden... zurückkehren...', 'Wir werden... zurückkehren...', 28153),
(159033, 'deDE', 'Der schwarze Drachenschwarm wird wiedergeboren!', 'Der schwarze Drachenschwarm wird wiedergeboren!', 28153),
(159032, 'deDE', 'Eure Art wird geläutert werden!', 'Eure Art wird geläutert werden!', 28153),
(159031, 'deDE', 'Wir bringen Feuer und Tod!', 'Wir bringen Feuer und Tod!', 28153),
(159030, 'deDE', 'Ihr wagt es, Euch einem Drachenschwarm entgegenzustellen?', 'Ihr wagt es, Euch einem Drachenschwarm entgegenzustellen?', 28153),
(159029, 'deDE', 'Der schwarze Drachenschwarm wird sich wieder erheben!', 'Der schwarze Drachenschwarm wird sich wieder erheben!', 28153),
(159028, 'deDE', 'Ruhm dem schwarzen Drachenschwarm!', 'Ruhm dem schwarzen Drachenschwarm!', 28153),
(159027, 'deDE', 'Für die Erdwächter!', 'Für die Erdwächter!', 28153),
(159026, 'deDE', 'Ich werde den Drachenschwarm verteidigen!', 'Ich werde den Drachenschwarm verteidigen!', 28153),
(159025, 'deDE', 'Für Euch... Kaiserin...', 'Für Euch... Kaiserin...', 28153),
(159024, 'deDE', 'Ihr zerquetscht einen... doch es kommen noch viele mehr...', 'Ihr zerquetscht einen... doch es kommen noch viele mehr...', 28153),
(159023, 'deDE', 'Bringt das Erz... der Kaiserin...', 'Bringt das Erz... der Kaiserin...', 28153),
(159022, 'deDE', 'Ihr Ruf... ist Musik...', 'Ihr Ruf... ist Musik...', 28153),
(159021, 'deDE', 'Ich höre sie... sogar im Sterben...', 'Ich höre sie... sogar im Sterben...', 28153),
(159020, 'deDE', 'Das Lied der Kaiserin... verklingt...', 'Das Lied der Kaiserin... verklingt...', 28153),
(159019, 'deDE', 'Wir sind... Tausende... Ihr könnt uns nicht aufhalten...', 'Wir sind... Tausende... Ihr könnt uns nicht aufhalten...', 28153),
(159018, 'deDE', 'Kschh... Ich falle...', 'Kschh... Ich falle...', 28153),
(159017, 'deDE', 'Ich werde Euch töten und Eure Leiche wird den Schwarm ernähren!', 'Ich werde Euch töten und Eure Leiche wird den Schwarm ernähren!', 28153),
(159016, 'deDE', 'Ihr geht so bereitwillig Eurem Tod entgegen?', 'Ihr geht so bereitwillig Eurem Tod entgegen?', 28153),
(159015, 'deDE', 'Das goldene Erz gehört uns! Ein Geschenk für die Kaiserin!', 'Das goldene Erz gehört uns! Ein Geschenk für die Kaiserin!', 28153),
(159014, 'deDE', 'Wir schwärmen für die Kaiserin!', 'Wir schwärmen für die Kaiserin!', 28153),
(159013, 'deDE', 'Der Schwarm kann nicht aufgehalten werden!', 'Der Schwarm kann nicht aufgehalten werden!', 28153),
(159012, 'deDE', 'Der süße Gesang unserer Kaiserin verlangt Euren Tod!', 'Der süße Gesang unserer Kaiserin verlangt Euren Tod!', 28153),
(159011, 'deDE', 'Die Kaiserin befehligt mich!', 'Die Kaiserin befehligt mich!', 28153),
(159010, 'deDE', 'Für die Kaiserin!', 'Für die Kaiserin!', 28153),
(159009, 'deDE', '... die Allianz wird überdauern... und die Schreckensherrschaft der Bansheekönigin wird ein Ende finden.', '', 28153),
(159008, 'deDE', 'Sie glaubt, diese Untat breche unseren Geist... und unsere Einheit. Aber ich schwöre...', '', 28153),
(159007, 'deDE', 'Harr! Ein ehrenwerter Treffer...', 'Harr! Ein ehrenwerter Treffer...', 28153),
(159006, 'deDE', 'Yarr! Das ist der Tod, den ich mir vorstelle!', 'Yarr! Das ist der Tod, den ich mir vorstelle!', 28153),
(159005, 'deDE', 'Doch dieser Traum kann niemals Wirklichkeit werden, solange Sylvanas die Horde anführt.', '', 28153),
(159004, 'deDE', 'Ich segle... dem Sonnenuntergang entgegen...', 'Ich segle... dem Sonnenuntergang entgegen...', 28153),
(159003, 'deDE', 'Mein ganzes Leben habe ich für den Frieden gebetet.', '', 28153),
(159002, 'deDE', 'Ich nehme meinen Platz an der Seite der alten Krieger ein...', 'Ich nehme meinen Platz an der Seite der alten Krieger ein...', 28153),
(159001, 'deDE', 'Ihr habt Mut bewiesen, Champion... an einem der dunkelsten Tage in der Geschichte der Allianz.', '', 28153),
(159000, 'deDE', 'Mögen die Geister meinen Tod segnen...', 'Mögen die Geister meinen Tod segnen...', 28153),
(158999, 'deDE', '', 'Ruht Euch aus! Wappnet Euch für die kommenden Schlachten. Ich brauche Euch.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'deDE', 'Ich sterbe im glorreichen Kampf!', 'Ich sterbe im glorreichen Kampf!', 28153),
(158997, 'deDE', 'Der Klan wird mich rächen...', 'Der Klan wird mich rächen...', 28153),
(158996, 'deDE', '', 'ABER sie bluten. Ihr Zorn wird sich als Schwäche erweisen im aufziehenden Krieg. Nicht als Stärke.', 28153),
(158995, 'deDE', 'Der Tod wird Euch holen...', 'Der Tod wird Euch holen...', 28153),
(158994, 'deDE', 'Noch ein Schwächling, der sterben will!', 'Noch ein Schwächling, der sterben will!', 28153),
(158993, 'deDE', 'Eine weiterer glorreiche Schlacht!', 'Eine weiterer glorreiche Schlacht!', 28153),
(158992, 'deDE', 'Ich werde Euch die Augen herausschneiden!', 'Ich werde Euch die Augen herausschneiden!', 28153),
(158991, 'deDE', '', 'Wir waren nur zum Teil erfolgreich. Die Allianz WIRD sich rächen. Sie werden uns jagen. Mich. Und Euch.', 28153),
(158990, 'deDE', '', 'Unser Angriff sollte den Krieg beenden, bevor er beginnt... dem Feind mit einem Streich sein Zuhause und seine Anführer nehmen. Eine Wunde schlagen, an der die Allianz verblutet.', 28153),
(158989, 'deDE', '', 'Als ich Euch auf diese Mission geschickt habe, habe ich das nicht vorhergesehen.', 28153),
(158988, 'deDE', 'Tausend Schiffe auf dem Weg zu Eurem Untergang!', 'Tausend Schiffe auf dem Weg zu Eurem Untergang!', 28153),
(158987, 'deDE', 'Mein Leben für Jorun!', 'Mein Leben für Jorun!', 28153),
(158986, 'deDE', 'Für die Blutgischt!', 'Für die Blutgischt!', 28153),
(158985, 'deDE', 'Sterbt ehrenvoll!', 'Sterbt ehrenvoll!', 28153),
(158984, 'deDE', 'Ich esse Euer Herz!', 'Ich esse Euer Herz!', 28153),
(158983, 'deDE', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'deDE', 'Mrrg mrgl?', 'Mrrg mrgl?', 28153),
(158981, 'deDE', 'Rgll mgrgl... rgl...', 'Rgll mgrgl... rgl...', 28153),
(158980, 'deDE', 'Grgl...', 'Grgl...', 28153),
(158979, 'deDE', 'Mrg!', 'Mrg!', 28153),
(158978, 'deDE', 'Rgl... mrg...', 'Rgl... mrg...', 28153),
(158977, 'deDE', 'Mrrrmgrl!', 'Mrrrmgrl!', 28153),
(158976, 'deDE', 'Mrglrgl? Mrg! Rgl!', 'Mrglrgl? Mrg! Rgl!', 28153),
(158975, 'deDE', 'Rgrml grml grml!', 'Rgrml grml grml!', 28153),
(158974, 'deDE', '', 'Ach du liebe Güte, das ist ja perfekt! Habt vielen Dank, $p. Ihr seid wirklich ein Schatz. Hier habt Ihr ein paar Kekse.', 28153),
(158973, 'deDE', 'Mrg? Grml?!', 'Mrg? Grml?!', 28153),
(158972, 'deDE', 'Mrgl? Rgl!', 'Mrgl? Rgl!', 28153),
(158971, 'deDE', 'Mrglrglrgl!', 'Mrglrglrgl!', 28153),
(158970, 'deDE', 'Der Tod hat keine Bedeutung für die endlose Leere...', 'Der Tod hat keine Bedeutung für die endlose Leere...', 28153),
(158969, 'deDE', 'Er wird wiederkommen...', 'Er wird wiederkommen...', 28153),
(158968, 'deDE', 'Euer Untergang erhebt sich aus den Tiefen...', 'Euer Untergang erhebt sich aus den Tiefen...', 28153),
(158967, 'deDE', 'Ihr könnt uns nicht vernichten... Wir sind... endlos...', 'Ihr könnt uns nicht vernichten... Wir sind... endlos...', 28153),
(158966, 'deDE', 'Ihr werdet... fallen... verlassen von Euren Freunden...', 'Ihr werdet... fallen... verlassen von Euren Freunden...', 28153),
(158965, 'deDE', 'Hört Ihr den Ruf der Finsternis in der Tiefe?', 'Hört Ihr den Ruf der Finsternis in der Tiefe?', 28153),
(158964, 'deDE', 'Die unbegreiflichen Tiefen lassen sich nicht beherrschen!', 'Die unbegreiflichen Tiefen lassen sich nicht beherrschen!', 28153),
(158963, 'deDE', 'Aus meinem Leichnam werden tausend andere erwachsen.', 'Aus meinem Leichnam werden tausend andere erwachsen.', 28153),
(158962, 'deDE', 'Die letzte Glocke läutet und die zuckende Finsternis verlangt ihren Tribut.', 'Die letzte Glocke läutet und die zuckende Finsternis verlangt ihren Tribut.', 28153),
(158961, 'deDE', 'Den Verschlinger in der Tiefe gelüstet nach Eurer Welt!', 'Den Verschlinger in der Tiefe gelüstet nach Eurer Welt!', 28153),
(158960, 'deDE', 'Ihr könnt nicht besiegen, was Ihr fürchtet!', 'Ihr könnt nicht besiegen, was Ihr fürchtet!', 28153),
(158959, 'deDE', 'Wir werden uns unbehelligt ausbreiten und Eure Welt mit Schrecken und Augen überziehen.', 'Wir werden uns unbehelligt ausbreiten und Eure Welt mit Schrecken und Augen überziehen.', 28153),
(158958, 'deDE', 'Die lichtlosen Abgründe rufen Euch.', 'Die lichtlosen Abgründe rufen Euch.', 28153),
(158957, 'deDE', 'Schreit und lauft in die Tiefen!', 'Schreit und lauft in die Tiefen!', 28153),
(158956, 'deDE', 'Wir werden Euch alle verschlingen!', 'Wir werden Euch alle verschlingen!', 28153),
(158955, 'deDE', 'Euer Körper wird die Finsternis nähren!', 'Euer Körper wird die Finsternis nähren!', 28153),
(158954, 'deDE', 'Schiffbruch...', 'Schiffbruch...', 28153),
(158953, 'deDE', 'Ich dachte immer, ich würde auf hoher See sterben...', 'Ich dachte immer, ich würde auf hoher See sterben...', 28153),
(158952, 'deDE', 'So... will ich nicht sterben...', 'So... will ich nicht sterben...', 28153),
(158951, 'deDE', 'Der Navigator... ist immer schuld...', 'Der Navigator... ist immer schuld...', 28153),
(158950, 'deDE', 'Rettet mich... Ihr Hunde...', 'Rettet mich... Ihr Hunde...', 28153),
(158949, 'deDE', 'Lieber tot... als noch länger hierbleiben...', 'Lieber tot... als noch länger hierbleiben...', 28153),
(158948, 'deDE', 'Hätten nicht... herkommen sollen...', 'Hätten nicht... herkommen sollen...', 28153),
(158947, 'deDE', 'Verdammt... miese... Mannschaft...', 'Verdammt... miese... Mannschaft...', 28153),
(158946, 'deDE', 'Euer Schiff wird uns gehören, Ihr Plattfische!', 'Euer Schiff wird uns gehören, Ihr Plattfische!', 28153),
(158945, 'deDE', 'Schaut, Jungs, der Schatz ist uns direkt in die Arme gelaufen und hat noch einen Weg hier raus mitgebracht!', 'Schaut, Jungs, der Schatz ist uns direkt in die Arme gelaufen und hat noch einen Weg hier raus mitgebracht!', 28153),
(158944, 'deDE', 'Sie haben ein Schiff! Holt sie Euch!', 'Sie haben ein Schiff! Holt sie Euch!', 28153),
(158943, 'deDE', 'Ihr werdet bereuen, hierhergekommen zu sein!', 'Ihr werdet bereuen, hierhergekommen zu sein!', 28153),
(158942, 'deDE', 'Harr, hätte vorher weniger Rum trinken sollen...', 'Harr, hätte vorher weniger Rum trinken sollen...', 28153),
(158941, 'deDE', 'Hoch, ihr Säcke! Wir werden angegriffen!', 'Hoch, ihr Säcke! Wir werden angegriffen!', 28153),
(158940, 'deDE', 'Die sind nicht hier, um uns zu retten! Holt sie Euch!', 'Die sind nicht hier, um uns zu retten! Holt sie Euch!', 28153),
(158939, 'deDE', 'Harrr, wir müssen hier raus, Jungs! Holt sie Euch!', 'Harrr, wir müssen hier raus, Jungs! Holt sie Euch!', 28153),
(158938, 'deDE', 'Zurück in die Tiefe... ein Seemannstod...', 'Zurück in die Tiefe... ein Seemannstod...', 28153),
(158937, 'deDE', 'Arrrgh... Gebt mir noch einen letzten Rum...', 'Arrrgh... Gebt mir noch einen letzten Rum...', 28153),
(158936, 'deDE', 'Wird so dunkel... hier drüben...', 'Wird so dunkel... hier drüben...', 28153),
(158935, 'deDE', 'Arrrgh... Das war nur Glück...', 'Arrrgh... Das war nur Glück...', 28153),
(158934, 'deDE', 'Los... zum Schiff...', 'Los... zum Schiff...', 28153),
(158933, 'deDE', 'Arrrgh! Mitten in den Leib...', 'Arrrgh! Mitten in den Leib...', 28153),
(158932, 'deDE', 'Ihr werdet meinen Schatz... niemals finden...', 'Ihr werdet meinen Schatz... niemals finden...', 28153),
(158931, 'deDE', 'Arrrgh... Mein Schatz...', 'Arrrgh... Mein Schatz...', 28153),
(158930, 'deDE', 'Verteidigt mich, nutzloses Pack!', 'Verteidigt mich, nutzloses Pack!', 28153),
(158929, 'deDE', 'Zu mir, Männer, wir werden geentert!', 'Zu mir, Männer, wir werden geentert!', 28153),
(158928, 'deDE', 'Ihr hättet nicht kommen sollen! Das hier ist Piratenland!', 'Ihr hättet nicht kommen sollen! Das hier ist Piratenland!', 28153),
(158927, 'deDE', 'Arrrgh! Stürzt Euch auf die Eindringlinge, Jungs!', 'Arrrgh! Stürzt Euch auf die Eindringlinge, Jungs!', 28153),
(158926, 'deDE', 'Harrr! Brandschatzen und Plündern!', 'Harrr! Brandschatzen und Plündern!', 28153),
(158925, 'deDE', 'Ich ramm Euch meinen Säbel in die Eingeweide!', 'Ich ramm Euch meinen Säbel in die Eingeweide!', 28153),
(158924, 'deDE', 'Ich schicke Euch über die Planke!', 'Ich schicke Euch über die Planke!', 28153),
(158923, 'deDE', 'Los, Seemänner, schlagt die Eindringlinge zurück!', 'Los, Seemänner, schlagt die Eindringlinge zurück!', 28153),
(158922, 'deDE', 'Niemand wird sich uns bei unserer Jagd nach Onoho in den Weg stellen!', '', 28153),
(158921, 'deDE', 'Das Meer hat Euch uns gegeben, jetzt könnt Ihr nicht fortgehen...', '', 28153),
(158920, 'deDE', 'Wir werden unsere Fähigkeiten verbessern, während wir darauf warten, dass das Meer uns leitet!', '', 28153),
(158919, 'deDE', 'Das Wogen des Wassers hat diese Zusammenkunft vorhergesagt.', '', 28153),
(158918, 'deDE', 'Ihr steht dem großen Jagdklan gegenüber. Wie könnt Ihr hoffen, zu überleben?', '', 28153),
(158917, 'deDE', 'Das Meer bringt uns neues Fleisch und Waffen, wir danken den Wellen dafür!', '', 28153),
(158916, 'deDE', 'Euer Fleisch und Eure Vorräte werden die große Jagd vorantreiben, wir danken Euch!', '', 28153),
(158915, 'deDE', 'Unser Klan jagt Onoho seit vielen Jahren. Ihr werdet uns heute nicht aufhalten!', '', 28153),
(158914, 'deDE', 'Die Untiefen... zeigten mir dieses Schicksal...', '', 28153),
(158913, 'deDE', 'Die Wellen... nehmen mich mit...', '', 28153),
(158912, 'deDE', 'Die Jagd... fordert ein weiteres Opfer...', '', 28153),
(158911, 'deDE', 'Ihr seid... ebenfalls... gut bei der Jagd...', '', 28153),
(158910, 'deDE', 'Hrk... ehrenhaft getroffen...', '', 28153),
(158909, 'deDE', 'Das Meer verschlingt uns am Ende alle...', '', 28153),
(158908, 'deDE', 'Die Jagd wird... ohne mich weitergehen...', '', 28153),
(158907, 'deDE', 'Wir bereuen... nichts...', '', 28153),
(158906, 'deDE', 'Da wurden offenbar ein paar Fremdlinge am Ufer angespült.', '', 28153),
(158905, 'deDE', 'Wir danken Euch für Euer Opfer.', '', 28153),
(158904, 'deDE', 'Entreißt ihnen ihre Vorräte, wir feiern heute Abend!', '', 28153),
(158903, 'deDE', 'Ihr wagt es, Euch unserem Klan entgegenzustellen?', '', 28153),
(158902, 'deDE', 'Euer Blut ist der Treibstoff für die Jagd.', '', 28153),
(158901, 'deDE', 'Euer toter Körper wird uns am Leben halten, wir danken Euch.', '', 28153),
(158900, 'deDE', 'Das Meer hat uns neue Vorräte geschenkt...', '', 28153),
(158899, 'deDE', 'Die Wellen haben Eure Ankunft vorhergesagt.', '', 28153),
(158898, 'deDE', '', 'Ich liebe all diese lustigen, kleinen Kreaturen, die man hier draußen finden kann. Häschen und Vögel und Krabben und was nicht alles. Ich habe ein paar Haustiere ausgebildet, damit sie Champions werden. Seht Ihr den Kadaver da? Das haben meine Schätzchen in nur vier Minuten hinbekommen. Die sind ganz schön hungrig. Wollt Ihr mal sehen, wie die loslegen?', 28153),
(158897, 'deDE', '', 'Behaltet Meerah im Auge, ja? \n\nSie ist blind für die wahren Gefahren der Wüste. Es wäre furchtbar, wenn die Sande sie verschlingen würden...', 28153),
(158896, 'deDE', '', 'Eure Freundin sieht schon viel besser aus. Ich bin froh, dass Kiro und Meerah helfen konnten.', 28153),
(158895, 'deDE', '', 'Willkommen in unserem Zuhause, $n, zumindest vorerst. \n\nDie Karawanen sind sofort zum Aufbruch bereit, für den Fall, dass die Sethrak unser Versteck finden.', 28153),
(158894, 'deDE', 'Seht, ob Ihr Na\'logo durch den ganzen Tang hindurch in Sicherheit bringen könnt.', '', 28153),
(158893, 'deDE', '', 'Ganz bestimmt! Hier, nehmt ein paar dieser Mehlbomben mit. Bitte seid aber vorsichtig damit.', 28153),
(158892, 'deDE', 'Wollt Ihr was gegen Bärenfleisch tauschen?', '', 28153),
(158891, 'deDE', 'Kua\'fon schießt davon!', '', 28153),
(158890, 'deDE', 'Kua\'fon hält den Schädel knapp außerhalb Eurer Reichweite und schlägt schelmisch mit seinem Schwanz.', '', 28153),
(158889, 'deDE', 'So gut... seid Ihr nicht.', '', 28153),
(158888, 'deDE', 'Ach, ich nehme mir einfach, was ich brauche!', '', 28153),
(158887, 'deDE', 'Eure Ausrüstung gefällt mir... Wollt Ihr tauschen?', '', 28153),
(158886, 'deDE', 'Zurück... ins Wasser...', '', 28153),
(158885, 'deDE', 'Der Klan wird nicht sterben... nicht heute...', '', 28153),
(158884, 'deDE', 'Hsss... wie...?', '', 28153),
(158883, 'deDE', 'Ich kehre zurück... in die Wellen...', '', 28153),
(158882, 'deDE', 'Der Schatz ssssollte... mir gehören...', '', 28153),
(158881, 'deDE', 'Hssss... Dafür... werdet Ihr bezahlen...', '', 28153),
(158880, 'deDE', 'Hssss... Diebe...', '', 28153),
(158879, 'deDE', 'Hssss... mein Blut...', '', 28153),
(158878, 'deDE', 'Hsss! Tötet sie! Bewacht den Schatz!', '', 28153),
(158877, 'deDE', 'Die Edelsteine ssstärken unseren Klan! Wir werden uns Euch nicht beugen!', '', 28153),
(158876, 'deDE', 'Ich werde mir Euer Fleisch und Eure Knochen schmecken lassen!', '', 28153),
(158875, 'deDE', 'Ihr wollt Euch dem großen Krieger widersssetzen?', '', 28153),
(158874, 'deDE', 'Ich beschütze den Klan! Ihr werdet sterben!', '', 28153),
(158873, 'deDE', 'Eindringlinge! Massssakriert sie alle!', '', 28153),
(158872, 'deDE', 'Der Schatz gehört meinem Klan. Ihr ssseid nur Diebe!', '', 28153),
(158871, 'deDE', 'Mein Klan ist mächtig. Ihr könnt uns nicht aufhalten!', '', 28153),
(158870, 'deDE', 'Ich werde versuchen, welches für Euch aufzutreiben...', 'Ich werde versuchen, welches für Euch aufzutreiben...', 28153),
(158869, 'deDE', 'Eure Schätze gehören uns!', '', 28153),
(158868, 'deDE', 'Ich habe Eis für Euch!', 'Ich habe Eis für Euch!', 28153),
(158867, 'deDE', 'Ich werde Euch ausnehmen wie einen Fisch!', '', 28153),
(158866, 'deDE', 'Beschützt den Klan!', '', 28153),
(158865, 'deDE', 'Massssakriert sie, bringt mir ihre Sssachen!', '', 28153),
(158864, 'deDE', 'Hsss! Wir werden angegriffen!', '', 28153),
(158863, 'deDE', 'Warmblüter!', '', 28153),
(158862, 'deDE', 'Tötet sie! Nehmt ihre Sssachen!', '', 28153),
(158861, 'deDE', 'Hsss! Ich werde Euch massssakrieren.', '', 28153),
(158860, 'deDE', 'Kinder, hier kommt Eure Nahrung!', 'Kinder, hier kommt Eure Nahrung!', 28153),
(158859, 'deDE', 'Sicher. Was kann ich für Euch tun?', 'Sicher. Was kann ich für Euch tun?', 28153),
(158858, 'deDE', 'K-kchh-k, ein weiteres Opfer in unserem Bau... Eure Reise endet hier...', 'K-kchh-k, ein weiteres Opfer in unserem Bau... Eure Reise endet hier...', 28153),
(158857, 'deDE', 'Wie erfreulich, das köstliche Fleisch läuft direkt in unseren Bau.', 'Wie erfreulich, das köstliche Fleisch läuft direkt in unseren Bau.', 28153),
(158856, 'deDE', 'Die Jungen trinken Euer Blut, die Königin isst Euer Fleisch und ich werde Euer Hirn verzehren!', 'Die Jungen trinken Euer Blut, die Königin isst Euer Fleisch und ich werde Euer Hirn verzehren!', 28153),
(158855, 'deDE', 'Ihr werdet die Eier nicht finden! Unser Schwarm ist unendlich!', 'Ihr werdet die Eier nicht finden! Unser Schwarm ist unendlich!', 28153),
(158854, 'deDE', 'Nicht wehren, Beute, das verlängert nur das Leiden!', 'Nicht wehren, Beute, das verlängert nur das Leiden!', 28153),
(158853, 'deDE', 'Ah, noch ein Opfer für unsere Netzzze!', 'Ah, noch ein Opfer für unsere Netzzze!', 28153),
(158852, 'deDE', 'Wir werden unsere Brut um jeden Preis beschützen!', 'Wir werden unsere Brut um jeden Preis beschützen!', 28153),
(158851, 'deDE', 'Hütet Euch... vor den Eindringlingen...', 'Hütet Euch... vor den Eindringlingen...', 28153),
(158850, 'deDE', 'Die Eier sind vor Euch sicher...', 'Die Eier sind vor Euch sicher...', 28153),
(158849, 'deDE', 'Ihr werdet niemals alle von uns finden...', 'Ihr werdet niemals alle von uns finden...', 28153),
(158848, 'deDE', 'Wir sind so weit gekommen... Es kann nicht sein, dass Ihr uns tötet...', 'Wir sind so weit gekommen... Es kann nicht sein, dass Ihr uns tötet...', 28153),
(158847, 'deDE', 'Mein Körper wird die Brut nähren...', 'Mein Körper wird die Brut nähren...', 28153),
(158846, 'deDE', 'Kzz... dieser Schmerz...', 'Kzz... dieser Schmerz...', 28153),
(158845, 'deDE', 'Beschützt... die Brut...', 'Beschützt... die Brut...', 28153),
(158844, 'deDE', 'Kzzz...', 'Kzzz...', 28153),
(158843, 'deDE', 'Unsere Jungen werden Euer Fleisch verzehren!', 'Unsere Jungen werden Euer Fleisch verzehren!', 28153),
(158842, 'deDE', 'Kch-K-Kommt in mein Netz!', 'Kch-K-Kommt in mein Netz!', 28153),
(158841, 'deDE', 'Eindringlinge!', 'Eindringlinge!', 28153),
(158840, 'deDE', 'Wir werden unsere Brut beschützen!', 'Wir werden unsere Brut beschützen!', 28153),
(158839, 'deDE', 'Kzzz... So frisches Blut...', 'Kzzz... So frisches Blut...', 28153),
(158838, 'deDE', 'Es gibt Beute...', 'Es gibt Beute...', 28153),
(158837, 'deDE', 'Ihr stört unsere Netzzze!', 'Ihr stört unsere Netzzze!', 28153),
(158836, 'deDE', 'Kzzz... Eindringlinge...', 'Kzzz... Eindringlinge...', 28153),
(158835, 'deDE', '', 'In letzter Zeit habe ich richtig Appetit auf Süßigkeiten. Ich hätte riesige Lust auf ein leckeres Erdbeereis! \n\nIch wäre ja so dankbar, wenn Ihr welches für mich besorgen könntet. Wenn es nicht zu viel Mühe macht, bringt mir bitte genug, damit ich etwas für später aufheben kann. Ich hoffe, ich mache Euch keine Umstände!', 28153),
(158834, 'deDE', '', 'Ihr seht ja so mager aus, Schätzchen. Esst Ihr auch genug?', 28153),
(158833, 'deDE', '', 'Oooch! Ihr seid den ganzen Weg gekommen, nur um mich zu besuchen?', 28153),
(158832, 'deDE', '', 'Hallo, mein Schätzchen. Wie schön, Euch zu sehen.', 28153),
(158831, 'deDE', 'Rar! Rargh!', '', 28153),
(158830, 'deDE', 'Ihr... nein...', '', 28153),
(158829, 'deDE', 'Argrrr...', '', 28153),
(158828, 'deDE', 'Grrrr...', '', 28153),
(158827, 'deDE', 'Ihr... riecht übel...', '', 28153),
(158826, 'deDE', 'Muss... weglaufen...', '', 28153),
(158825, 'deDE', 'Hurgh...', '', 28153),
(158824, 'deDE', 'Umpf... grah...', '', 28153),
(158823, 'deDE', 'Neuer Geruch, nicht gut, rarrr!', '', 28153),
(158822, 'deDE', 'Arrr, rieche Fleisch!', '', 28153),
(158821, 'deDE', 'Grar! Ihr nährt uns!', '', 28153),
(158820, 'deDE', 'Beiße Euch, fresse Euer Fleisch!', '', 28153),
(158819, 'deDE', 'Sterbt! Rargh!', '', 28153),
(158818, 'deDE', 'Rrrr... Euch... Ich töten!', '', 28153),
(158817, 'deDE', 'Grrrargh!', '', 28153),
(158816, 'deDE', 'Mmrrr!', '', 28153),
(158815, 'deDE', 'Diese Wildnis gibt es schon viel länger als Euch und sie wird Euch überleben.', 'Diese Wildnis gibt es schon viel länger als Euch und sie wird Euch überleben.', 28153),
(158814, 'deDE', 'Die leuchtenden Edelsteine sind ein Geschenk der Natur an uns und wir werden sie vor Euresgleichen schützen!', 'Die leuchtenden Edelsteine sind ein Geschenk der Natur an uns und wir werden sie vor Euresgleichen schützen!', 28153),
(158813, 'deDE', 'Der Kreislauf wird Euch heute berühren, Eindringling, und wir werden aus Euren Überresten wachsen.', 'Der Kreislauf wird Euch heute berühren, Eindringling, und wir werden aus Euren Überresten wachsen.', 28153),
(158812, 'deDE', 'Ich werde der Bedrohung durch Euch ein Ende setzen, bevor Ihr unser Land noch mehr verderbt.', 'Ich werde der Bedrohung durch Euch ein Ende setzen, bevor Ihr unser Land noch mehr verderbt.', 28153),
(158811, 'deDE', 'Ihr werdet das Erdreich nähren, das Ihr auf Eurem Weg hierher zertrampelt habt.', 'Ihr werdet das Erdreich nähren, das Ihr auf Eurem Weg hierher zertrampelt habt.', 28153),
(158810, 'deDE', 'Eure Art ist aus dem Gleichgewicht geraten. Ihr seid nicht mehr tragbar. Ich muss einschreiten.', 'Eure Art ist aus dem Gleichgewicht geraten. Ihr seid nicht mehr tragbar. Ich muss einschreiten.', 28153),
(158809, 'deDE', 'Ich muss Euch vernichten, um das Gleichgewicht zu bewahren, das ihr gestört habt.', 'Ich muss Euch vernichten, um das Gleichgewicht zu bewahren, das ihr gestört habt.', 28153),
(158808, 'deDE', 'Wir haben den Auftrag, dieses Land und seine Tiere zu hüten. Ihr seid hier nicht willkommen!', 'Wir haben den Auftrag, dieses Land und seine Tiere zu hüten. Ihr seid hier nicht willkommen!', 28153),
(158807, 'deDE', 'Eure Art ist... eine Plage...', 'Eure Art ist... eine Plage...', 28153),
(158806, 'deDE', 'Ihr verschandelt... unser Land...', 'Ihr verschandelt... unser Land...', 28153),
(158805, 'deDE', 'Ihr könnt die Natur... nicht töten...', 'Ihr könnt die Natur... nicht töten...', 28153),
(158804, 'deDE', 'Wir werden... nachwachsen...', 'Wir werden... nachwachsen...', 28153),
(158803, 'deDE', 'Euresgleichen... kann nicht überdauern...', 'Euresgleichen... kann nicht überdauern...', 28153),
(158802, 'deDE', 'Ich nähre... das Land...', 'Ich nähre... das Land...', 28153),
(158801, 'deDE', 'Ihr stört... das Gleichgewicht...', 'Ihr stört... das Gleichgewicht...', 28153),
(158800, 'deDE', 'Ich kehre zurück... zur Natur...', 'Ich kehre zurück... zur Natur...', 28153),
(158799, 'deDE', 'Man hat uns mit dem Schutz dieses Gebiets beauftragt!', 'Man hat uns mit dem Schutz dieses Gebiets beauftragt!', 28153),
(158798, 'deDE', 'Die leuchtenden Edelsteine sind ein Geschenk an die Wildnis!', 'Die leuchtenden Edelsteine sind ein Geschenk an die Wildnis!', 28153),
(158797, 'deDE', 'Wir müssen das Gleichgewicht bewahren!', 'Wir müssen das Gleichgewicht bewahren!', 28153),
(158796, 'deDE', 'Ihr werdet unseren Hain nicht verderben!', 'Ihr werdet unseren Hain nicht verderben!', 28153),
(158795, 'deDE', 'Ich folge dem Ruf der Natur!', 'Ich folge dem Ruf der Natur!', 28153),
(158794, 'deDE', 'Dieses Land wird nicht von Euch verdorben werden, Eindringling!', 'Dieses Land wird nicht von Euch verdorben werden, Eindringling!', 28153),
(158793, 'deDE', 'Natur, lenke meinen Zorn!', 'Natur, lenke meinen Zorn!', 28153),
(158792, 'deDE', 'Ich muss die Wildnis schützen!', 'Ich muss die Wildnis schützen!', 28153),
(158791, 'deDE', 'Ich komm\' jeden Tag her und red\' mit mein\' Großeltern. Ich glaub\', die könn\' mich hör\'n!', '', 28153),
(158790, 'deDE', 'Gruh...', 'Gruh...', 28153),
(158789, 'deDE', 'Wo... bin ich...?', 'Wo... bin ich...?', 28153),
(158788, 'deDE', 'Grah... Blut...', 'Grah... Blut...', 28153),
(158787, 'deDE', '', 'Wenn die Schlacht gewonnen wurde, geht die Arbeit erst richtig los.', 28153),
(158786, 'deDE', 'Mein Zorn... verebbt...', 'Mein Zorn... verebbt...', 28153),
(158785, 'deDE', 'Ihr... warum...', 'Ihr... warum...', 28153),
(158784, 'deDE', 'Muss... fliehen...', 'Muss... fliehen...', 28153),
(158783, 'deDE', 'Ich sehe... jetzt klarer...', 'Ich sehe... jetzt klarer...', 28153),
(158782, 'deDE', 'Argh... Schmerz...', 'Argh... Schmerz...', 28153),
(158781, 'deDE', 'Grarh!', 'Grarh!', 28153),
(158780, 'deDE', 'Ich wüte!', 'Ich wüte!', 28153),
(158779, 'deDE', 'Fremde...', 'Fremde...', 28153),
(158778, 'deDE', 'Rieche Angst...', 'Rieche Angst...', 28153),
(158777, 'deDE', 'Geht... Grrr...', 'Geht... Grrr...', 28153),
(158776, 'deDE', 'Töte... Euch...', 'Töte... Euch...', 28153),
(158775, 'deDE', 'Grrr...', 'Grrr...', 28153),
(158774, 'deDE', 'Rargh!', 'Rargh!', 28153),
(158773, 'deDE', 'Seht ma\', wie groß der geword\'n is\'! Genau wie sein Vater.', '', 28153),
(158772, 'deDE', 'Verflucht seid Ihr...', 'Verflucht seid Ihr...', 28153),
(158771, 'deDE', 'Ich kann... die Vorfahren seh\'n...', 'Ich kann... die Vorfahren seh\'n...', 28153),
(158770, 'deDE', 'Die Geister... werd\'n mich begrüß\'n...', 'Die Geister... werd\'n mich begrüß\'n...', 28153),
(158769, 'deDE', 'Ihr habt... keine Ehre...', 'Ihr habt... keine Ehre...', 28153),
(158768, 'deDE', 'Argh... Habt mich erwischt...', 'Argh... Habt mich erwischt...', 28153),
(158767, 'deDE', 'Ihr könnt uns... nich\' alle töt\'n...', 'Ihr könnt uns... nich\' alle töt\'n...', 28153),
(158766, 'deDE', 'Ich werd mich räch\'n... aus\'m Jenseits...', 'Ich werd mich räch\'n... aus\'m Jenseits...', 28153),
(158765, 'deDE', 'Ich geh zu den Geistern...', 'Ich geh zu den Geistern...', 28153),
(158764, 'deDE', 'Ich mach \'n Verhexdings aus Euren Knochen un\' beleg Eure ganze Familie mit \'nem Fluch!', 'Ich mach \'n Verhexdings aus Euren Knochen un\' beleg Eure ganze Familie mit \'nem Fluch!', 28153),
(158763, 'deDE', 'Dreckige Eindringlinge. Ihr gehört hier nich\' her!', 'Dreckige Eindringlinge. Ihr gehört hier nich\' her!', 28153),
(158762, 'deDE', '', 'Kommt mir wie gestern vor, dass unser Kind \'n Kind bekam. Un\' nu\' seht ihn Euch an!', 28153),
(158761, 'deDE', 'Wer seid\'n Ihr? Ihr seid hier nich\' willkomm\'n.', 'Wer seid\'n Ihr? Ihr seid hier nich\' willkomm\'n.', 28153),
(158760, 'deDE', 'Dann woll\'n wir mal seh\'n, was Ihr könnt...', 'Dann woll\'n wir mal seh\'n, was Ihr könnt...', 28153),
(158759, 'deDE', 'Wir hab\'n jetzt die Edelsteine. Mein Klan is\' jetz\' der stärkste!', 'Wir hab\'n jetzt die Edelsteine. Mein Klan is\' jetz\' der stärkste!', 28153),
(158758, 'deDE', 'So leicht mach ich Euch das nich\', heh.', 'So leicht mach ich Euch das nich\', heh.', 28153),
(158757, 'deDE', 'Das sin\' meine Insel un\' meine Edelsteine un\' für Euch gibt\'s hier nur den Tod.', 'Das sin\' meine Insel un\' meine Edelsteine un\' für Euch gibt\'s hier nur den Tod.', 28153),
(158756, 'deDE', 'Wir ham das hier gefund\'n, un\' Ihr könnt\'s uns nich\' nehm\'n!', 'Wir ham das hier gefund\'n, un\' Ihr könnt\'s uns nich\' nehm\'n!', 28153),
(158755, 'deDE', 'Das is\' unsere Insel!', 'Das is\' unsere Insel!', 28153),
(158754, 'deDE', 'Was wollt\'n Ihr auf dieser Insel?', 'Was wollt\'n Ihr auf dieser Insel?', 28153),
(158753, 'deDE', 'Wir werd\'n angegriff\'n, Mann! Hier rüber!', 'Wir werd\'n angegriff\'n, Mann! Hier rüber!', 28153),
(158752, 'deDE', 'Schlitzt sie schnell auf!', 'Schlitzt sie schnell auf!', 28153),
(158751, 'deDE', 'Ich fress Euch lebend auf un\' Ihr guckt zu!', 'Ich fress Euch lebend auf un\' Ihr guckt zu!', 28153),
(158750, 'deDE', 'Wir werd\'n Euch lebendig häut\'n!', 'Wir werd\'n Euch lebendig häut\'n!', 28153),
(158749, 'deDE', 'Ich mach mir \'ne Halskette aus Euern Knochen!', 'Ich mach mir \'ne Halskette aus Euern Knochen!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'deDE', 'Ich weid Euch aus un\' trink Euer Blut, Mann!', 'Ich weid Euch aus un\' trink Euer Blut, Mann!', 28153),
(158747, 'deDE', 'Argh! Ich sterbe ehrenvoll!', '', 28153),
(158746, 'deDE', 'Ihr seid... die Eindringlinge... Wir haben nichts getan...', '', 28153),
(158745, 'deDE', 'Die Edelsteine... konnten uns nicht retten...', '', 28153),
(158744, 'deDE', 'Wir werden zurückkehren... in noch größerer Zahl...', '', 28153),
(158743, 'deDE', 'Die Sterne... haben gelogen...', '', 28153),
(158742, 'deDE', 'Ich folge dem Ruf der Ahnen...', '', 28153),
(158741, 'deDE', 'Die Geister heißen mich willkommen...', '', 28153),
(158740, 'deDE', 'Ich gehe... zu meinen Ahnen...', '', 28153),
(158739, 'deDE', 'Die Sterne leiten meine Fäuste, Die Zukunft steht in Eurem Blut geschrieben.', '', 28153),
(158738, 'deDE', 'Die Winde haben mir verraten, dass Ihr heute sterben werdet.', '', 28153),
(158737, 'deDE', 'Die Geister verleihen mir die Kraft eines unlöschbaren Feuers!', '', 28153),
(158736, 'deDE', 'Diesen Kampf könnt Ihr nicht gewinnen!', '', 28153),
(158735, 'deDE', 'Die Schätze dieser Insel gehören uns, Narren!', '', 28153),
(158734, 'deDE', 'Die Ahnen verleihen mir Stärke und Weisheit!', '', 28153),
(158733, 'deDE', 'Euer Blut wird an meinen Hörnern kleben, Narren!', '', 28153),
(158732, 'deDE', 'Ich werde meinen Klan verteidigen, Fremdling!', '', 28153),
(158731, 'deDE', 'Krieger, helft mir!', '', 28153),
(158730, 'deDE', 'Sammelt Euch! Wir werden angegriffen!', '', 28153),
(158729, 'deDE', 'Das ist unsere Insel! Ihr habt hier keine Rechte!', '', 28153),
(158728, 'deDE', 'Die leuchtenden Edelsteine gehören uns! Gebt es auf!', '', 28153),
(158727, 'deDE', 'Ihr werdet uns nicht von hier vertreiben, Fremdling!', '', 28153),
(158726, 'deDE', 'Eindringlinge! Schlagt sie zurück!', '', 28153),
(158725, 'deDE', 'Geister, führt meine Waffe!', '', 28153),
(158724, 'deDE', 'Für die Ahnen!', '', 28153),
(158723, 'deDE', 'Tut... weh...', '', 28153),
(158722, 'deDE', 'Was Ihr... hier wollen...?', '', 28153),
(158721, 'deDE', 'Argh! Genau in den Bauch...', '', 28153),
(158720, 'deDE', 'Ihr... uns beklauen...', '', 28153),
(158719, 'deDE', 'Nein! Meine Edelsteine...', '', 28153),
(158718, 'deDE', 'Was... Was das sollen?', '', 28153),
(158717, 'deDE', 'Uff... Nicht gut...', '', 28153),
(158716, 'deDE', 'Warum so dunkel jetzt?', '', 28153),
(158715, 'deDE', '', 'Es gibt welche, die glaub\'n \'n Handel is\' nur \'n Handel. Leere Versprech\'n un\' Getue. Die Belohnungen von heut\' im Austausch für \'ne unbekannte Zukunft.\n\nDenkt aber dran: Bwonsamdi treibt alle Schuld\'n ein. Irgendwann.', 28153),
(158714, 'deDE', 'Los, meine Oger! Zeit zum Zerschmettern!', '', 28153),
(158713, 'deDE', 'Nein! Meine Edelsteine! Nicht Eure! Ich die brauchen!', '', 28153),
(158712, 'deDE', 'Edelsteine machen uns stark, Eindringling. Stärker wie Euch!', '', 28153),
(158711, 'deDE', 'Euer Kopf sein meine Trophäe, wenn wir hier fertig!', '', 28153),
(158710, 'deDE', 'Auf sie! Ihnen das Rückgrat brechen!', '', 28153),
(158709, 'deDE', 'Meine Insel, Winzling! Meine!', '', 28153),
(158708, 'deDE', 'Ich Euch zerschmettern! Euer Blut trinken!', '', 28153),
(158707, 'deDE', 'Ich Euch in Stücke hauen! Arrrgh!', '', 28153),
(158706, 'deDE', 'Meine Edelsteine! Arrrgh!', '', 28153),
(158705, 'deDE', 'Ihr Finger weg von unserem Kram!', '', 28153),
(158704, 'deDE', 'Schnappt sie Euch!', '', 28153),
(158703, 'deDE', 'Ihr Edelsteine nicht kriegen!', '', 28153),
(158702, 'deDE', 'Meine Insel! Ihr verschwinden!', '', 28153),
(158701, 'deDE', 'Eindringlinge! Töten!', '', 28153),
(158700, 'deDE', 'Zerschmettern! Zermalmen! Töten!', '', 28153),
(158699, 'deDE', 'Ich Euch vernichten!', '', 28153),
(158698, 'deDE', 'Vielleicht, wenn ich einfach versprech, mich zu bessern... nich\' so wie letztes Mal!', 'Vielleicht, wenn ich einfach versprech, mich zu bessern... nich\' so wie letztes Mal!', 28153),
(158697, 'deDE', 'Was, glaubt Ihr, würde Bwonsamdi von mir woll\'n?', 'Was, glaubt Ihr, würde Bwonsamdi von mir woll\'n?', 28153),
(158696, 'deDE', 'Was mach ich nur... was mach ich nur... es muss doch \'nen Ausweg geb\'n.', 'Was mach ich nur... was mach ich nur... es muss doch \'nen Ausweg geb\'n.', 28153),
(158695, 'deDE', 'Wenn ich nu\' \'nen Handel mit Bwonsamdi mach\', dann wird alles wieder normal, richtig?', 'Wenn ich nu\' \'nen Handel mit Bwonsamdi mach\', dann wird alles wieder normal, richtig?', 28153),
(158694, 'deDE', 'Ich hass das! Ich hass alles!', 'Ich hass das! Ich hass alles!', 28153),
(158693, 'deDE', 'Das geht so nich\'! Is\' denen nich\' klar, wer ich bin?', 'Das geht so nich\'! Is\' denen nich\' klar, wer ich bin?', 28153),
(158692, 'deDE', 'Ich werd den erwischen, der mir das angetan hat! Und wenn\'s das Letzte is\', was ich tu!', 'Ich werd den erwischen, der mir das angetan hat! Und wenn\'s das Letzte is\', was ich tu!', 28153),
(158691, 'deDE', 'Wie konnte das passier\'n? Das is\' nich\' fair!', 'Wie konnte das passier\'n? Das is\' nich\' fair!', 28153),
(158690, 'deDE', 'Es wird nich\' besser un\' Ihr könnt mir das auch nich\' einred\'n.', 'Es wird nich\' besser un\' Ihr könnt mir das auch nich\' einred\'n.', 28153),
(158689, 'deDE', 'Lief alles so gut für mich un\' jetz\' seht Euch das an... Jetzt bin ich nix.', 'Lief alles so gut für mich un\' jetz\' seht Euch das an... Jetzt bin ich nix.', 28153),
(158688, 'deDE', 'Ich werd nie wieder die Sonne spür\'n.', 'Ich werd nie wieder die Sonne spür\'n.', 28153),
(158687, 'deDE', 'Wenn ich nur \'n paar Tage mehr gehabt hätt... Ich hätt so viel tun könn\'n.', 'Wenn ich nur \'n paar Tage mehr gehabt hätt... Ich hätt so viel tun könn\'n.', 28153),
(158686, 'deDE', 'Tot? Nein, ich ruh mich nur kurz aus.', 'Tot? Nein, ich ruh mich nur kurz aus.', 28153),
(158685, 'deDE', 'Wer seid \'n Ihr? Egal, kann nich\' so wichtig sein...', 'Wer seid \'n Ihr? Egal, kann nich\' so wichtig sein...', 28153),
(158684, 'deDE', 'Wenn ich nich\' hinguck, passiert nix. Is\' so.', 'Wenn ich nich\' hinguck, passiert nix. Is\' so.', 28153),
(158683, 'deDE', 'Einfach weitermach\'n... einfach weitermach\'n... Irgendwann wird\'s richtig...', 'Einfach weitermach\'n... einfach weitermach\'n... Irgendwann wird\'s richtig...', 28153),
(158682, 'deDE', 'Ihr wagt es, einfach so durch MEINEN Frachtraum zu trampeln? Damit ist jetzt Schluss!', '', 28153),
(158681, 'deDE', 'Ihr seid schwach. Stellt Euch mir in einem echten Kampf!', '', 28153),
(158680, 'deDE', 'Glaubt Ihr etwa, Eure erbärmliche Maschine kann es mit mir aufnehmen?!', '', 28153),
(158679, 'deDE', 'Sieh an, ein Herausforderer! Kommt nur her!', '', 28153),
(158678, 'deDE', 'Aber... zum Sterben bin ich viel zu schön...', '', 28153),
(158677, 'deDE', '', 'Ich werde Euch... ausweiden...', 28153),
(158676, 'deDE', '', 'Ich mach Euch zu Geschnetzeltem!', 28153),
(158675, 'deDE', 'Bestattet mich auf See...', '', 28153),
(158674, 'deDE', 'Ich werde Euch kielholen!', '', 28153),
(158673, 'deDE', 'Bah. Dieser Typ. Ich weiß nicht, was schlimmer ist... seine Haargelduschen oder die schiefen Gedichte. Aber täuscht Euch nicht, Reet kämpft wie er liebt – mit Leidenschaft.', '', 28153),
(158672, 'deDE', 'Björn, pfff. Hält sich für unglaublich wichtig.', '', 28153),
(158671, 'deDE', 'Luna hat eine, sagen wir... \"bestechende\" Persönlichkeit.', '', 28153),
(158670, 'deDE', 'Ts... Das Einzige, worauf man sich verlassen kann, sind Steuern und...', '', 28153),
(158669, 'deDE', 'Was haben wir denn hier? Sieht ganz so aus, als gäbe es da noch eine Rechnung zu begleichen!', '', 28153),
(158668, 'deDE', '', 'Ich bete, dass wir nicht zu spät sind. Sputet Euch, $n. Findet meine Tochter.', 28153),
(158666, 'deDE', '', 'Schicksalsend ist eine Insel vor der Küste von Sturmsang. Unsere übelsten Verbrecher und Verräter fristen dort ihre letzten Tage.', 28153),
(158665, 'deDE', '', '$n! Was habt Ihr erfahren?', 28153),
(158661, 'deDE', 'Ich verschwinde hier! Danke für Eure Hilfe, $p!', '', 28153),
(158660, 'deDE', 'Kua\'fon stößt ein durchdringendes Kreischen aus und schlägt aufgeregt mit dem Schwanz.', '', 28153),
(158659, 'deDE', 'Kua\'fon legt den Schädel wieder in Eure Hand.', '', 28153),
(158658, 'deDE', 'Kua\'fon lässt den Schädel vor seine Füße fallen, sieht Euch an und kreischt Euch verspielt an.', '', 28153),
(158657, 'deDE', '', 'Dieser Krieg ist verloren. Teldrassil wird fallen.', 28153),
(158656, 'deDE', 'Die Gezeiten sollen Euch mit Haut und Haaren verschlingen!', '', 28153),
(158655, 'deDE', 'Kommt, Champion. Wir folgen unserem Kriegshäuptling zum... Sieg.', '', 28153),
(158654, 'deDE', '', 'Es funktioniert. Alle aufsitzen!', 28153),
(158653, 'deDE', 'Auch Ihr habt die Wahl. Ihr bringt ihn nach Darnassus und sterbt beide, wenn wir es erobern. Oder flieht, so weit Ihr nur könnt, und Ihr beide überlebt.', '', 28153),
(158652, 'deDE', '', 'Ihr habt Malfurion verschont, also lasse ich Euch die Wahl.', 28153),
(158651, 'deDE', '', 'Bleibt standhaft!', 28153),
(158650, 'deDE', 'Nicht für nichts. Wir vergießen Blut, damit die Horde fortbesteht.', '', 28153),
(158649, 'deDE', '', 'Dieser ganze Krieg ist ehrlos. Wie könnt Ihr es wagen, so viel unschuldiges Blut zu vergießen...? Für nichts!', 28153),
(158648, 'deDE', 'Mein Angriff war ehrlos. Sein Kopf stand mir nicht zu.', '', 28153),
(158647, 'deDE', '', 'Ihr habt ihn nicht getötet, Orc. Warum?', 28153),
(158646, 'deDE', '', 'Malfurion! Nein!', 28153),
(158645, 'deDE', 'Ihr habt die Horde... im Dienste des Todes... geführt. Diesen Tag... bereut Ihr... noch...', '', 28153),
(158642, 'deDE', '', 'Heilt Eure Wunden und ruht die müden Knochen aus. Hier seid Ihr in Sicherheit.', 28153),
(158641, 'deDE', 'Ich bin gestorb\'n, weil ich mich mit dem falsch\'n Vieh angelegt hab. Ihr wisst schon, welches ich mein.', 'Ich bin gestorb\'n, weil ich mich mit dem falsch\'n Vieh angelegt hab. Ihr wisst schon, welches ich mein.', 28153),
(158640, 'deDE', 'Ich bin genauso verwirrt wie Ihr, Mann.', 'Ich bin genauso verwirrt wie Ihr, Mann.', 28153),
(158639, 'deDE', 'Haw\'lis scharfes Chili war zu viel für mich.', 'Haw\'lis scharfes Chili war zu viel für mich.', 28153),
(158638, 'deDE', 'Ich bin gestorb\'n, als ich bei der Torcanata mitgerannt bin. Un\' ich würd\'s nochmal mach\'n, wenn ich könnt!', 'Ich bin gestorb\'n, als ich bei der Torcanata mitgerannt bin. Un\' ich würd\'s nochmal mach\'n, wenn ich könnt!', 28153),
(158637, 'deDE', 'Euern Körper gebt\'er aber an der Tür ab, ja?', 'Euern Körper gebt\'er aber an der Tür ab, ja?', 28153),
(158636, 'deDE', 'Mich hat der Blitz getroff\'n, als ich über\'n Zocalo gelauf\'n bin.', 'Mich hat der Blitz getroff\'n, als ich über\'n Zocalo gelauf\'n bin.', 28153),
(158635, 'deDE', 'Ich bin von der Pyramide gefall\'n un\' gestorb\'n un\' nu\' weiß ich nich\' mehr, wie ich hergekommen bin.', 'Ich bin von der Pyramide gefall\'n un\' gestorb\'n un\' nu\' weiß ich nich\' mehr, wie ich hergekommen bin.', 28153),
(158634, 'deDE', 'Schick gemacht... für nix un\' wieder nix.', 'Schick gemacht... für nix un\' wieder nix.', 28153),
(158633, 'deDE', 'Es war gar nicht einfach, den richtigen Ort für die Platzierung dieses Portals in Boralus zu berechnen, aber es war eine willkommene Herausforderung! Sagt mir Bescheid, wie es läuft, ja?', '', 28153),
(158632, 'deDE', 'Wie Ihr wünscht, Nathanos.', '', 28153),
(158631, 'deDE', 'Zelling, begleitet $n nach Boralus. Oculeth wartet mit einem Portal.', '', 28153),
(158630, 'deDE', 'Hey, großer Champion. Wir müss\'n red\'n.', '', 28153),
(158629, 'deDE', 'Das hier ist der beste Platz... Ihr könnt ihn haben, wenn ich aufstehe.', '', 28153),
(158628, 'deDE', '', '$p? Pfft, nie von Euch gehört.', 28153),
(158627, 'deDE', 'Wenn Ihr bereit seid, Euch zu den Schiffen zu begeben, dann wartet Hobart draußen, um Euch zu helfen.', '', 28153),
(158626, 'deDE', 'Sagt nicht, ich hätte Euch nicht gewarnt!', 'Sagt nicht, ich hätte Euch nicht gewarnt!', 28153),
(158625, 'deDE', 'Bleibt zurück! Es ist zu Eurem Besten.', 'Bleibt zurück! Es ist zu Eurem Besten.', 28153),
(158624, 'deDE', 'Kua\'fon zittert verängstigt.', '', 28153),
(158623, 'deDE', 'Das Blatt hat sich zu unseren Gunsten gewendet, meint Ihr nicht, $n?', '', 28153),
(158622, 'deDE', 'Ich sehe Großes am Horizont... für Euch und auch für mich.', '', 28153),
(158621, 'deDE', 'Ihr könnt mich nich\' einfach hier zurücklass\'n. Meine alt\'n Knoch\'n halt\'n die Arbeit in den Minen hier nich\' mehr aus.', 'Ihr könnt mich nich\' einfach hier zurücklass\'n. Meine alt\'n Knoch\'n halt\'n die Arbeit in den Minen hier nich\' mehr aus.', 28153),
(158620, 'deDE', 'Ich sehe jetzt, was in der Gärphase falsch gelaufen sein könnte.', '', 28153),
(158619, 'deDE', 'Die Präsenz unsichtbarer Schadstoffe könnte demnach Auswirkungen auf den anfänglichen Reduktionsprozess haben.', '', 28153),
(158618, 'deDE', 'Wird gemacht.', '', 28153),
(158617, 'deDE', 'Ich helfe, wo ich kann.', '', 28153),
(158616, 'deDE', 'Ich gehe dann mal an die Arbeit.', '', 28153),
(158615, 'deDE', 'Sicher, ich werde behilflich sein.', '', 28153),
(158614, 'deDE', 'Dann packe ich wohl mal mit an.', '', 28153),
(158612, 'deDE', '', 'Schaut Euch aufmerksam um. Die Bäume haben Augen, Champion. Blendet sie.', 28153),
(158611, 'deDE', 'Wir sollten uns darauf konzentrieren, zuerst die Grundstoffe zu stabilisieren.', '', 28153),
(158610, 'deDE', 'Ohhhh! Das erklärt einiges! \"Das erste Gesetz der Alchemie: Um etwas von Vorteil zu erhalten, muss adäquater Ersatz geleistet werden.\"', '', 28153),
(158609, 'deDE', 'Legen wir los!', 'Legen wir los!', 28153),
(158608, 'deDE', 'Faszinierend... die präzise Zufuhr von Hitze ist entscheidend.', '', 28153),
(158607, 'deDE', 'Ahhh! Ich glaube, jetzt verstehe ich, warum der Katalysator versagt hat.', '', 28153),
(158606, 'deDE', 'Sonderbar... das hätten wir unmöglich vorhersehen können.', '', 28153),
(158605, 'deDE', 'Hmmm... das ist ja interessant.', '', 28153),
(158604, 'deDE', 'Ein paar unserer Kumpels sind da draußen geschnappt worden. Könnt Ihr da helfen?', '', 28153),
(158603, 'deDE', 'Hey! Da hat sich jemand ein paar unserer Waren gegriffen! Die will ich zurück und zwar PRONTO. Vorzugsweise mit Zinsen.', '', 28153),
(158602, 'deDE', 'Ooh, ÜBERALL Verletzte. Wir müssen denen irgendwie helfen!', '', 28153),
(158601, 'deDE', 'Haben wir gute Leisetreter? Ich hätte einen Auftrag für Euch!', '', 28153),
(158600, 'deDE', 'Lauscher auf: Wenn Ihr da draußen gute Kriegstriketeile findet, dann sagt mir Bescheid. Ihr könnt auch \'ne Spritztour machen, wenn sie wieder läuft.', '', 28153),
(158599, 'deDE', 'Ich sehe da was, das ein paar gute alte Tritte im Kezanstil vertragen könnte.', '', 28153),
(158598, 'deDE', 'Ooh, ist das Ding RIESIG. Hey! Will sich das jemand zur Brust nehmen?', '', 28153),
(158597, 'deDE', 'Einige unserer Verbündeten wurden gefangen genommen. Seid Ihr bereit für eine Rettungsoperation?', '', 28153),
(158596, 'deDE', 'Feindliche Truppen sind mit essenziellen Vorräten entkommen. Wollen wir die Diebe etwas Allianzgerechtigkeit schmecken lassen?', '', 28153),
(158595, 'deDE', 'Wir haben verletzte Soldaten im Feld. Sind irgendwelche Sanitäter einsatzbereit?', '', 28153),
(158594, 'deDE', 'So ist es, mein Kind. Elune stand ihnen bei. Sie segnete die Druiden mit Macht über die Winde und vollen Segeln.', '', 28153),
(158593, 'deDE', '', 'Das Verhüllte Meer war dabei kein Hindernis, Shan\'do?', 28153),
(158592, 'deDE', 'Schickt mich zurück zum Hafen.', 'Schickt mich zurück zum Hafen.', 28153),
(158591, 'deDE', 'Schickt mich zu dem kleineren Schiff.', 'Schickt mich zu dem kleineren Schiff.', 28153),
(158590, 'deDE', 'Ich suche Freiwillige für eine gewagte Geheimoperation. Sie erfordert ein gewisses Maß an Tarnung und List.', '', 28153),
(158589, 'deDE', 'Wir versuchen, eine feindliche Kriegsmaschine wieder flott zu machen. Bringt uns jedes Ersatzteil, das Ihr finden könnt.', '', 28153),
(158588, 'deDE', 'Ah, da präsentiert sich uns eine Gelegenheit.', '', 28153),
(158587, 'deDE', 'Recht aggressives Großwild hat sich aufs Schlachtfeld verirrt. Ich würde sagen... Waidmanns Heil!', '', 28153),
(158586, 'deDE', 'Wollt Ihr meinem kleinen Freund hallo sagen?', '', 28153),
(158585, 'deDE', 'Ihr könnt einem ganz schön auf die Bomben gehen.', '', 28153),
(158584, 'deDE', 'Hey, schön gemütlich bleiben.', '', 28153),
(158583, 'deDE', 'Kommt heil wieder zurück, ja?', '', 28153),
(158582, 'deDE', 'Haltet die Augen offen.', '', 28153),
(158581, 'deDE', 'Passt auf Euch auf da draußen.', '', 28153),
(158580, 'deDE', 'Was gibt\'s Neues?', '', 28153),
(158579, 'deDE', 'Wie geht\'s?', '', 28153),
(158578, 'deDE', 'Läuft super.', '', 28153),
(158577, 'deDE', 'Beim Licht, ich könnte noch einen Schluck vertragen.', '', 28153),
(158576, 'deDE', 'Das ist selbst den Lohn eines Offiziers nicht wert.', '', 28153),
(158575, 'deDE', 'Ja, ja...', '', 28153),
(158574, 'deDE', 'Weitermachen.', '', 28153),
(158573, 'deDE', 'Wegtreten.', '', 28153),
(158572, 'deDE', 'Behaltet Eure Feinde immer im Auge.', '', 28153),
(158571, 'deDE', 'Ja?', '', 28153),
(158570, 'deDE', 'Ihr habt meine ungeteilte Aufmerksamkeit.', '', 28153),
(158569, 'deDE', 'Ruhm der Allianz.', '', 28153),
(158568, 'deDE', '', 'Nein... das kann nicht sein.', 28153),
(158565, 'deDE', '', 'Ihr werdet mir helfen, die Grenzen meiner Macht auf die Probe zu stellen!', 28153),
(158564, 'deDE', '', 'Manche sagen, meine Magie sei grausam, aber mein alleiniges Streben ist, die Grenzen des Möglichen auszuloten.', 28153),
(158563, 'deDE', 'Graben', 'Graben', 28153),
(158562, 'deDE', 'Mia... MIA! Öffne die Augen, meine Königin... mein Herz!', '', 28153),
(158561, 'deDE', 'Möge Eure Göttin Euch beschützen.', '', 28153),
(158560, 'deDE', 'Die Banshee hat mir Sohn und Königreich genommen. Sie nimmt mir nicht meine Frau!', '', 28153),
(158559, 'deDE', '', 'Sie... werden sich weigern...', 28153),
(158558, 'deDE', 'Astarii, Ihr habt getan, was Ihr könnt. Befehlt den Priestern, mit uns zu kommen!', '', 28153),
(158557, 'deDE', 'Niemals! Ihr kommt beide mit!', '', 28153),
(158555, 'deDE', '', 'Der Baum... sie verbrennen den Baum! Das Kind... rette es! Lass... mich...', 28153),
(158554, 'deDE', 'Du kannst nicht länger hierbleiben! Wir müssen durch das Portal fliehen!', '', 28153),
(158553, 'deDE', '', 'Astarii, die Zeit drängt. Wir müssen die Stadt evakuieren, bevor alles zu Asche verbrennt!', 28153),
(158551, 'deDE', '', 'Setzt dem ein Ende. Nehmt Euch einen Moment, wenn Ihr müsst... und dann schneidet ihm den Kopf ab. Trefft mich am Weltenbaum!', 28153),
(158550, 'deDE', '', 'Mein Sieg stand nie in Frage. Er hätte nur meine Zeit verschwendet.', 28153),
(158549, 'deDE', 'Ich hätte mich nicht einmischen dürfen.', '', 28153),
(158548, 'deDE', '', 'Grundlos. Das habt Ihr gut gemacht.', 28153),
(158547, 'deDE', 'Ein ehrloser Schlag. Ich... schäme mich.', '', 28153),
(158546, 'deDE', 'ARGH! Saur...fang?!', '', 28153),
(158545, 'deDE', 'Der Kriegshäuptling stellt sich Sturmgrimm allein! Ich muss...', '', 28153),
(158544, 'deDE', 'Norden? Wie sind... Ah... Sie sind über die Berge des Teufelswalds geklettert. Natürlich.', '', 28153),
(158543, 'deDE', 'Champion, Delaryn, fangt sie in Auberdine ab! Ich kümmere mich um den Norden.', '', 28153),
(158542, 'deDE', 'Es ist nur eine Frage der Zeit, bevor die Horde durchbricht. Sie werden uns in die Zange nehmen.', '', 28153),
(158541, 'deDE', 'Die Irrwische... sie sind verwirrt. Die Barriere bricht zusammen!', '', 28153),
(158540, 'deDE', '', 'Was ist das für ein Geräusch? Shan\'do! Die Horde nähert sich von Norden!', 28153),
(158539, 'deDE', '', 'Die Zeit ist gekommen. Der Weltenbaum gehört uns. Sucht Saurfang. Wir setzen dem ein für alle Mal ein Ende.', 28153),
(158537, 'deDE', '', 'Seht Euch um, Champion! Ist es nicht schön? Die Irrwische zerstreuen sich. Die Barriere bricht Stück für Stück zusammen.', 28153),
(158536, 'deDE', '', 'Saurfang! Wird auch Zeit!', 28153),
(158535, 'deDE', 'FÜR DIE HORDE!', '', 28153),
(158534, 'deDE', '', 'Wo seid Ihr hingeflogen, kleines Vögelchen?', 28153),
(158533, 'deDE', '', 'Ah! Meine Augen! Das brennt!', 28153),
(158532, 'deDE', 'Verschwindet, Hexe!', '', 28153),
(158531, 'deDE', '', 'Wer hätte ahnen können, dass Ihr Eure kostbaren Bäume beschützen wollt...', 28153),
(158530, 'deDE', '', 'Malfurion. Wie schön, dass Ihr uns beehrt...', 28153),
(158529, 'deDE', 'Sylvanas! Eure Untaten entweihen diesen heiligen Ort! Andu-falah-dor!', '', 28153),
(158528, 'deDE', '', 'Ruhe ist ein Luxus, den wir ihnen nicht einmal nachts gewähren. Krieg ist Krieg.', 28153),
(158527, 'deDE', '', 'Bis dahin tun wir, was wir können, um die Kaldorei unerlässlich unter Druck zu setzen.', 28153),
(158526, 'deDE', '', 'Ich führe unsere Soldaten weiter durch die Barriere, während wir auf Nachricht von Saurfang warten.', 28153),
(158525, 'deDE', '', 'Wir müssen unserem Kurs vorerst treu bleiben.', 28153),
(158524, 'deDE', '', 'An den Wildschnellen besteht ein Patt und Malfurion weiß das.', 28153),
(158523, 'deDE', '', 'Champions der Horde! Eure Hilfe wird an den Wildschnellen benötigt! Dort wartet unser Schlüssel zum Sieg!', 28153),
(158522, 'deDE', '', '...ich habe eine Krähe zu jagen.', 28153),
(158521, 'deDE', '', 'Macht hier kurzen Prozess. Sobald Ihr so viel Azerit habt, wie Ihr tragen könnt, gebt es unseren Ingenieuren.', 28153),
(158520, 'deDE', '', 'Dieses Schiff muss aus Darnassus kommen... Das bedeutet...', 28153),
(158519, 'deDE', '', 'Seid vorsichtig, Champion. Die Allianz ist uns anscheinend zuvorgekommen.', 28153),
(158518, 'deDE', '', 'Azerit... Damit wird auch der Letzte, der sich der Horde in den Weg stellt, fallen.', 28153),
(158517, 'deDE', '', 'Pioniere! Nehmt Eure Ausrüstung und folgt mir! Bringt alle Schredder mit!', 28153),
(158516, 'deDE', '', 'Macht ihnen ein Ende oder sie tränken diesen Wald im Blut unserer Völker.', 28153),
(158515, 'deDE', '', 'Ich spüre, wie Euch das verunsichert. Diese Urtume sind nun gegen Euch, Druide... entgegen ihrer heiligen Bestimmung.', 28153),
(158514, 'deDE', 'Taelia! Jetzt wär ein Taxi hilfreich!', '', 28153),
(158513, 'deDE', 'Und damit meine ich \"einen rettenden Sprung von der Klippe\". Folgt mir!', '', 28153),
(158512, 'deDE', 'Und einen dramatischen Abgang hinlegen!', '', 28153),
(158511, 'deDE', 'Wir müssen uns nur die Kassette schnappen...', '', 28153),
(158510, 'deDE', 'Ich wusste gar nicht, wie brutal die Sonne auf die letzten Hautfetzen, die einem noch geblieben sind, herunterbrennen kann.', 'Ich wusste gar nicht, wie brutal die Sonne auf die letzten Hautfetzen, die einem noch geblieben sind, herunterbrennen kann.', 28153),
(158509, 'deDE', 'Ich versichere Euch, mein Plan ist brillant.', '', 28153),
(158508, 'deDE', 'Ich nehme an, Ihr habt auch einen Plan, um damit hier rauszukommen?', 'Ich nehme an, Ihr habt auch einen Plan, um damit hier rauszukommen?', 28153),
(158507, 'deDE', 'Harlan hat die Sicherheit erhöht, indem er die Kassette mit einem zusätzlichen Schloss ausgestattet hat.\n\n<Finn kratzt sich am Kinn.>\n\nTja. Da bleibt uns wohl nichts anderes übrig... als die Kassette zu stehlen.', '', 28153),
(158506, 'deDE', 'Hut ab, Harlan. Hut ab.', '', 28153),
(158505, 'deDE', 'Jeder Kadett, den ich erwische, wird zu hundert Runden um die Akademie verdonnert.', '', 28153),
(158504, 'deDE', 'Sie müssen doch irgendwo hier stecken.', '', 28153),
(158503, 'deDE', 'Wir haben niemals darum gebeten, zurückgebracht zu werden... oder das hier durchzustehen.', 'Wir haben niemals darum gebeten, zurückgebracht zu werden... oder das hier durchzustehen.', 28153),
(158502, 'deDE', 'Vier Schlösser? Vier?!', '', 28153),
(158501, 'deDE', 'Die Allianz wagt es, UNS als Monster zu bezeichnen?', 'Die Allianz wagt es, UNS als Monster zu bezeichnen?', 28153),
(158500, 'deDE', 'Wo sind nur diese Kadetten hin...', '', 28153),
(158499, 'deDE', 'Aaah, sieh an... die Schließkassette des Schmierigen.', '', 28153),
(158498, 'deDE', 'Nach allem, was passiert ist, kann ich nicht behaupten, dass ich sie beneide. Aber vielleicht wäre es an der Zeit, die Führung in Kul Tiras jemandem zu übertragen, der besser qualifiziert ist.', 'Nach allem, was passiert ist, kann ich nicht behaupten, dass ich sie beneide. Aber vielleicht wäre es an der Zeit, die Führung in Kul Tiras jemandem zu übertragen, der besser qualifiziert ist.', 28153),
(158497, 'deDE', 'Es wird mit jedem Tag offensichtlicher, dass Katherine sich auf den Lorbeeren ihres verstorbenen Mannes ausruht.', 'Es wird mit jedem Tag offensichtlicher, dass Katherine sich auf den Lorbeeren ihres verstorbenen Mannes ausruht.', 28153),
(158496, 'deDE', 'Eine weitere Woche ist ohne ein Treffen der Häuser vergangen.', 'Eine weitere Woche ist ohne ein Treffen der Häuser vergangen.', 28153),
(158495, 'deDE', 'Ganz recht. Kein Adliger, der in Tiragarde etwas auf sich hält, hätte eine solches Rührstück inszeniert, aus dem das Opfer auch noch Kapital schlagen kann.', 'Ganz recht. Kein Adliger, der in Tiragarde etwas auf sich hält, hätte eine solches Rührstück inszeniert, aus dem das Opfer auch noch Kapital schlagen kann.', 28153),
(158494, 'deDE', 'Am helllichten Tag ermordet, und das an ihrem Hochzeitstag. Was für ein dilettantischer Plan.', 'Am helllichten Tag ermordet, und das an ihrem Hochzeitstag. Was für ein dilettantischer Plan.', 28153),
(158493, 'deDE', 'Das mit ihrem Verlobten? Aber ja doch. Eine Schande.', 'Das mit ihrem Verlobten? Aber ja doch. Eine Schande.', 28153),
(158492, 'deDE', 'Habt Ihr gehört, was mit der Tochter der Familie Kronsteig passiert ist?', 'Habt Ihr gehört, was mit der Tochter der Familie Kronsteig passiert ist?', 28153),
(158491, 'deDE', 'Eine Schande. Ein Sturmsang, der nichts mit dem Meer am Hut hat? Hätte ich dieser Familie etwas zu sagen, hätte ich den Jungen längst verstoßen.', 'Eine Schande. Ein Sturmsang, der nichts mit dem Meer am Hut hat? Hätte ich dieser Familie etwas zu sagen, hätte ich den Jungen längst verstoßen.', 28153),
(158490, 'deDE', 'Also hat sein Onkel das Problem wohl kurzerhand zu uns verschifft?', 'Also hat sein Onkel das Problem wohl kurzerhand zu uns verschifft?', 28153),
(158489, 'deDE', 'Ich habe gehört, Brannon arbeitet wieder hier im Sund.', 'Ich habe gehört, Brannon arbeitet wieder hier im Sund.', 28153),
(158488, 'deDE', 'Ich bin erleichtert, dass Jaina nach ihrer Mutter kommt. Man könnte nicht behaupten, dass Daelin der Schönste war.', 'Ich bin erleichtert, dass Jaina nach ihrer Mutter kommt. Man könnte nicht behaupten, dass Daelin der Schönste war.', 28153),
(158487, 'deDE', '', '<Ein Dolch steckt noch in ihrem Rücken, aber alle Habseligkeiten wurden gestohlen.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'deDE', '', '<Diese Zandalarileiche scheint frisch zu sein.>', 28153),
(158485, 'deDE', '<Untersucht den Leichnam.>', '<Untersucht den Leichnam.>', 28153),
(158484, 'deDE', 'Die Kronsteigs haben sich schon längere Zeit nicht in Boralus blicken lassen. Ich frage mich, ob Margarete endlich gemerkt hat, wie schlecht sie hierher passt.', 'Die Kronsteigs haben sich schon längere Zeit nicht in Boralus blicken lassen. Ich frage mich, ob Margarete endlich gemerkt hat, wie schlecht sie hierher passt.', 28153),
(158483, 'deDE', 'Habt Ihr Lord Sturmsangs Aufzug gesehen, als er das letzte Mal hier war? Tentakelhüte sind völlig aus der Mode, finde ich.', 'Habt Ihr Lord Sturmsangs Aufzug gesehen, als er das letzte Mal hier war? Tentakelhüte sind völlig aus der Mode, finde ich.', 28153),
(158482, 'deDE', '<Simon wirft einen Blick auf Kunga.>\n\nÄhm, ja... Ha! Ha! Ihr seid echt lustig!\n\nHa! Ha! Echt witzig!\n\nIhr solltet lieber gehen, bevor Ihr noch einen findet. Ha! Ha!\n\nGeht und seht Euch die Kämpfe an, während ich... die Vorräte auffülle.', '', 28153),
(158481, 'deDE', 'Ich habe eine Leiche hinter dem Zelt gefunden.', 'Ich habe eine Leiche hinter dem Zelt gefunden.', 28153),
(158480, 'deDE', 'Hallo, ähm, ja.\n\nWillkommen in meinem Laden, Simons... Super... Sachen... Shop.\n\nIch verkaufe...\n\n<Simon wirft hastig einen Blick hinter sich.>\n\nWaffen. Alle möglichen Waffen. Aber alle sind gerade beschäftigt.\n\nKommt doch vielleicht später wieder, wenn ich wieder... neue Ware bekommen habe.', '', 28153),
(158479, 'deDE', 'Ich werde Euch niederstrecken, Hordenabschaum!', '', 28153),
(158478, 'deDE', 'Die Allianz hat kein Recht, uns unsere Heimat zu rauben!', 'Die Allianz hat kein Recht, uns unsere Heimat zu rauben!', 28153),
(158477, 'deDE', 'Alles ist besser als Zwieback.', '', 28153),
(158476, 'deDE', 'Wir konzentrieren unsere gesamten Ressourcen darauf, unseren Leuten Zeit für die Evakuierung zu verschaffen und die Horde in Schach zu halten. Sucht etwas zu essen für unsere Schildwachen.', '', 28153),
(158475, 'deDE', '', 'Ich werde Euch zum Meeresgrund schicken!', 28153),
(158474, 'deDE', 'Das is\' kein Mojo in meiner Tasche.', '', 28153),
(158473, 'deDE', 'Ich lass Euch gleich Eure eig\'ne Medizin kost\'n!', '', 28153),
(158472, 'deDE', 'Passt auf, dass ich Euch nich\' in \'ne Kröte verwandel!', '', 28153),
(158471, 'deDE', 'Ich rat\' Euch: Reizt mich nich\'. Ich bin vielleicht alt, aber dafür kenn\' ich \'n paar ziemlich fiese Verhexung\'n.', '', 28153),
(158470, 'deDE', 'Sachte, Mann. Kein Grund handgreiflich zu werd\'n.', '', 28153),
(158469, 'deDE', 'Ich bild\' seit Generation\' junge Dunkelspeertrolle aus.', '', 28153),
(158468, 'deDE', 'Viel Glück und habt immer n\' gutes Mojo zur Hand.', '', 28153),
(158467, 'deDE', '', 'Alles ist besser als Trockenrationen.', 28153),
(158466, 'deDE', '', 'Auf leeren Magen marschiert es sich schlecht, sagt man mir zumindest. Es muss doch etwas Essbares in diesem Wald geben.', 28153),
(158465, 'deDE', 'Denkt dran, nich\' alles heilt wieder.', '', 28153),
(158464, 'deDE', 'Achtung!', '', 28153),
(158463, 'deDE', 'Ich habe fast genügend Proben! Nur noch ein bisschen...', '', 28153),
(158462, 'deDE', 'Hmm, diese Blätter sind störrischer, als erwartet... aber ich denke, ich mache Fortschritte.', '', 28153),
(158461, 'deDE', 'Das könnte etwas dauern. Die Entfernung der Blätter ist ein heikler Prozess.', '', 28153),
(158460, 'deDE', 'Ich bin zu alt für sowas.', '', 28153),
(158459, 'deDE', 'Mögen die Geister mit Euch sein.', '', 28153),
(158458, 'deDE', 'Eekum bokum.', '', 28153),
(158457, 'deDE', 'Hat jemand \'n Arzt geruf\'n?', '', 28153),
(158456, 'deDE', 'Ihr braucht meine Hilfe?', '', 28153),
(158455, 'deDE', 'Hey, Mann.', '', 28153),
(158454, 'deDE', 'Ich möchte gerne, dass die Geister mich führen.', 'Ich möchte gerne, dass die Geister mich führen.', 28153),
(158453, 'deDE', 'Die Geister könn\' Euch hier hindurchleit\'n.', '', 28153),
(158452, 'deDE', 'Una\'fe, $n. Der Außenposten untersteht Eurem Kommando.', '', 28153),
(158451, 'deDE', '', 'Ihr habt ihnen die Zähne gezogen... für den Moment. Wir müssen wachsam bleiben, solange wir die Quelle des Sprengstoffs nicht zum Versiegen gebracht haben.', 28153),
(158450, 'deDE', '', 'Schlagt Euch ordentlich den Magen voll und dann ruht Euch aus!', 28153),
(158449, 'deDE', 'Das Siegel an dieser Kammer schützt die Weltenseele. Aber durch all das hereinbrechende Azerit hält das Siegel nicht mehr lange stand!', '', 28153),
(158448, 'deDE', 'Wenn Ihr das Azerit mit dem Amulett absorbiert, sollte seine Macht das Siegel der Kammer erneuern!', '', 28153),
(158447, 'deDE', '', 'Es kursieren Gerüchte, dass die Gangs äußerst gefährlichen Azeritsprengstoff in die Hände bekommen haben. Niemand in Boralus ist sicher, solange der Sprengstoff nicht konfisziert wurde.', 28153),
(158446, 'deDE', 'Als mein Schiff sank, sind Hunderte von Männern im Wasser gelandet. Innerhalb einer Stunde tauchten die Haie auf. Kleine Haie, große Haie, wütende Haie. Wir kämpften gegen sie, so gut wir konnten. Aber wenn man einem Hai direkt in diese starren, schwarzen Augen sieht, scheint er nicht einmal lebendig zu sein, bis er dann zubeißt. Dann wird das Meer rot und es wird dunkel und innerhalb weniger Augenblicke wird ein Mann in Stücke gerissen. Wahrscheinlich haben wir die Hälfte der Männer bis zum Ende der ersten Nacht verloren. Da waren Unmengen von Haien, ob zehn oder Tausende, wäre am Ende auch egal gewesen. Schließlich kam die Rettung, vielleicht fünf Tage später, und fast zu spät. Dreihundertundsechzehn Männer gingen rein, sieben kamen heraus, den Rest haben die Haie geholt.\n\nAber genug geredet. Wollt Ihr gegen ein paar Haie kämpfen?', '', 28153),
(158445, 'deDE', 'Danke. Das Risiko nehme ich auf mich. Kann ich mir die Stiefel ausleihen?', 'Danke. Das Risiko nehme ich auf mich. Kann ich mir die Stiefel ausleihen?', 28153),
(158444, 'deDE', '', 'Autsch! Ich wollte bloß ein paar Kisten wegräumen, die... äh... von einer Wagenpritsche gefallen sind.\n\nWenigstens ist Coda nichts passiert. Nichts kann meinem erstaunlichen kleinen Kerl etwas anhaben!\n\nIch habe ein zweites Paar Stiefel, wenn Ihr auf einen Sprung zurück in den Norden müsst. Aber seid gewarnt... Ich habe sie noch nicht getestet.', 28153),
(158443, 'deDE', '', 'Wir kommen zu spät.', 28153),
(158442, 'deDE', '', 'Seht nach, ob diese Leute Hilfe brauchen. Ich werde vorausgehen!', 28153),
(158441, 'deDE', '', 'Zuerst müssen wir das Tor verteidigen!', 28153),
(158440, 'deDE', '', 'Oh nein...', 28153),
(158439, 'deDE', '', 'Das wissen wir. Ruht Euch aus. Er bekommt schon, was er verdient.', 28153),
(158438, 'deDE', 'Harlan... dieser Bastard hat sich an Aschenwind verkauft... er ist... UNGH!', '', 28153),
(158437, 'deDE', 'Ahhh... überall... <hustet>', '', 28153),
(158436, 'deDE', '', 'Finn! Keine Angst, ich hab\' Euch! Geht es Euch gut? Wo tut es weh?', 28153),
(158435, 'deDE', 'Ughh.. ah.. uuuaaAAHH!!', '', 28153),
(158434, 'deDE', '', 'Gut. Komm, Mutter. Es ist Zeit, zu gehen.', 28153),
(158433, 'deDE', '', 'Gut festhalten!', 28153),
(158432, 'deDE', 'Ich bin bereit zum Aufbruch.', 'Ich bin bereit zum Aufbruch.', 28153),
(158431, 'deDE', '', 'Ich kann uns hier herausteleportieren, wenn Ihr so weit seid, $C. \n\nBitte beeilt Euch. Ich will so schnell wie möglich weg von hier.', 28153),
(158430, 'deDE', 'VIDEOSEQUENZ!', 'VIDEOSEQUENZ!', 28153),
(158429, 'deDE', 'Nachtelfen sind gute Nachbarn, aber ihre Irrwische sind etwas gewöhnungsbedürftig.', '', 28153),
(158428, 'deDE', 'Nutzt das Land, bearbeitet das Land. Das war unsere Abmachung.', '', 28153),
(158427, 'deDE', 'Es ist ein Jammer, was mit ihrem Baum passiert ist.', '', 28153),
(158426, 'deDE', 'Glaubt Ihr etwa, dass Ihr uns davon abhalten könnt, Dereks Leichnam zurückzuholen? Da irrt Ihr Euch aber gewaltig!', '', 28153),
(158425, 'deDE', 'Diesmal muss Na\'logo nur sein Ziel erreichen. Aber hütet Euch vor den Gefahren, die im Labyrinth lauern.', '', 28153),
(158424, 'deDE', 'Nun, könnt Ihr Na\'logo zum Schatz führen und dann zum Ziel, ohne dass er seinen zurückgelegten Pfad kreuzt?', '', 28153),
(158423, 'deDE', 'Das war nicht so schwer, oder?', '', 28153),
(158422, 'deDE', 'Zunächst eine einfach Aufgabe: Geleitet Na\'logo zum Ziel.', '', 28153),
(158421, 'deDE', 'Während wir ihnen diese Geschichten erzählen, müssen junge Tortollaner Na\'logo durch ein kleines Labyrinth führen und dabei verschiedene Herausforderungen meistern.', '', 28153),
(158420, 'deDE', 'Seid Ihr bereit für Euer Kampftraining?', 'Seid Ihr bereit für Euer Kampftraining?', 28153),
(158419, 'deDE', 'Gehen wir es mit einem fröhlichen Summen an, $p!', 'Gehen wir es mit einem fröhlichen Summen an, $p!', 28153),
(158418, 'deDE', 'Na\'logos erste Erfolge gaben ihm Selbstvertrauen, sodass er auszog, um noch faszinierendere Orte zu erforschen.', '', 28153),
(158416, 'deDE', 'Könnt Ihr Na\'logo zu allen Schätzen führen und dann zum Ausgang, ohne dass er seinen zurückgelegten Pfad kreuzt?', '', 28153),
(158415, 'deDE', 'Na\'logo begann, die uralten Ruinen zu erforschen, die er entdeckte. Oft fand er wundersame Schätze.', '', 28153),
(158414, 'deDE', '\"Na\'logo der Entdecker\" – Als Na\'logo wuchs, wuchs auch seine Neugier für die Welt.', '', 28153),
(158413, 'deDE', 'Na\'logos Pflichtbewusstsein machte sich bezahlt und die Erde beschenkte ihn mit vielen nahrhaften Lebensmitteln.', '', 28153),
(158412, 'deDE', 'Könnt Ihr Na\'logo helfen, alle Pflanzen im Garten jeweils nur einmal aufzusuchen?', '', 28153),
(158411, 'deDE', 'Jeden Morgen ging er zu allen Pflanzen in seinem Garten, um nach ihnen zu sehen.', '', 28153),
(158410, 'deDE', '', 'Die Drust haben sichtlich kein Interesse daran, das Leben ihrer Gefangenen zu verschonen. Wir dürfen nicht zulassen, dass Jaina so endet.', 28153),
(158409, 'deDE', '\"Na\'logos Ernte.\" Na\'logo liebte es, die Dinge wachsen zu sehen.', '', 28153),
(158408, 'deDE', 'Na\'logo ist nur um Haaresbreite davongekommen, also beschloss er, ein weniger aufregendes Leben zu führen.', '', 28153),
(158407, 'deDE', 'Könnt Ihr Na\'logo dabei helfen, die leuchtenden Kacheln auszuschalten, um die Falle zu neutralisieren?', '', 28153),
(158406, 'deDE', '\"Neugier und der Tortollaner.\" Na\'logos Neugier hätte ihm beinahe übel mitgespielt, als er eine uralte Zandalarifalle ausgelöst hat!', '', 28153),
(158405, 'deDE', '', 'Fleht um Gnade!', 28153),
(158404, 'deDE', 'Das Leben in der großen Stadt lag Na\'logo nicht. Er entschied sich daher für ein einfacheres Leben.', '', 28153),
(158403, 'deDE', 'Er verirrte sich jedoch immer wieder. Könnt Ihr Na\'logo zu allen Läden führen und dann zum Gasthaus, ohne dass er seinen zurückgelegten Pfad kreuzt?', '', 28153),
(158402, 'deDE', '\"Leben in der großen Stadt\" – Eines Tages besuchte Na\'logo eine große Stadt, ähnlich wie Boralus.', '', 28153),
(158401, 'deDE', 'Na\'logo genoss fortan sein ruhiges, friedliches Leben... und seinen vollen Bauch.', '', 28153),
(158399, 'deDE', '', 'Ich konnte ein paar geringe Elementare an diesen Schreinen einfangen, die ziemlich faszinierend sind. Möchtet Ihr sehen, wozu sie fähig sind?', 28153),
(158398, 'deDE', 'Gäste laufen weg... $PR stark...', '', 28153),
(158397, 'deDE', 'Immer noch Hunger...', '', 28153),
(158396, 'deDE', 'Wo ist das Licht hin?', '', 28153),
(158395, 'deDE', 'Lebt wohl, Gallywix...', '', 28153),
(158394, 'deDE', 'Hier wird nicht gekämpft!', '', 28153),
(158393, 'deDE', 'Erster Arbeitstag? Viel Glück!', '', 28153),
(158392, 'deDE', '$gEin:Eine:r; $PR hat hier keinen Zutritt!', '', 28153),
(158391, 'deDE', 'Geschlossene Veranstaltung!', '', 28153),
(158390, 'deDE', 'Und Ihr seid trotzdem nur mein zweitschlechtester Kunde... heute...', 'Und Ihr seid trotzdem nur mein zweitschlechtester Kunde... heute...', 28153),
(158389, 'deDE', 'Ein Goblin... auf Eis...', 'Ein Goblin... auf Eis...', 28153),
(158388, 'deDE', 'Letzte Runde... für Kaja\'Cola...', 'Letzte Runde... für Kaja\'Cola...', 28153),
(158387, 'deDE', 'Vergesst bloß nicht... ein Trinkgeld dazulassen...', 'Vergesst bloß nicht... ein Trinkgeld dazulassen...', 28153),
(158386, 'deDE', 'Ich habe nie gelernt... wie man... Golf spielt...', 'Ich habe nie gelernt... wie man... Golf spielt...', 28153),
(158385, 'deDE', 'Was hier eingelocht gehört... seid Ihr!', 'Was hier eingelocht gehört... seid Ihr!', 28153),
(158384, 'deDE', 'Begrabt mich bloß nicht in dieser Uniform... Die ist lächerlich...', 'Begrabt mich bloß nicht in dieser Uniform... Die ist lächerlich...', 28153),
(158383, 'deDE', 'Ich trag diese Schläger keinen Schritt weiter...', 'Ich trag diese Schläger keinen Schritt weiter...', 28153),
(158382, 'deDE', 'Dafür wird der große G... Euch büßen lassen...', 'Dafür wird der große G... Euch büßen lassen...', 28153),
(158381, 'deDE', 'Moment mal, der Spaß hat... doch noch gar nicht richtig angefangen...', 'Moment mal, der Spaß hat... doch noch gar nicht richtig angefangen...', 28153),
(158380, 'deDE', 'Moment mal... Meine Schicht ist noch nicht zu Ende...', 'Moment mal... Meine Schicht ist noch nicht zu Ende...', 28153),
(158379, 'deDE', 'Sagt Gallywix, er soll... mich weiter bezahlen.', 'Sagt Gallywix, er soll... mich weiter bezahlen.', 28153),
(158378, 'deDE', 'Ich wette, Ihr gebt mickriges Trinkgeld, Geizhals!', 'Ich wette, Ihr gebt mickriges Trinkgeld, Geizhals!', 28153),
(158377, 'deDE', 'Meine Kaja\'Cola bekommt Ihr nicht!', 'Meine Kaja\'Cola bekommt Ihr nicht!', 28153),
(158376, 'deDE', 'Ich werd aus Eurer Milz einen Martini mixen... einen Milztini!', 'Ich werd aus Eurer Milz einen Martini mixen... einen Milztini!', 28153),
(158375, 'deDE', 'Ich höre etwas...', 'Ich höre etwas...', 28153),
(158374, 'deDE', 'Die Getränke kommen aber aus Eurer Tasche, Freundchen!', 'Die Getränke kommen aber aus Eurer Tasche, Freundchen!', 28153),
(158373, 'deDE', 'Eins über Par? Eher ein paar... und zwar auf die Mütze!', 'Eins über Par? Eher ein paar... und zwar auf die Mütze!', 28153),
(158372, 'deDE', '<Der Doktor wendet sich Euch zu und flüstert.>$b$bSie sind schwer verletzt. Wir können sie in ihrem Zustand nicht bewegen. Ich kann bestenfalls versuchen, sie zusammenzuflicken und dann zu fliehen.$b$bEs ist Wahnsinn hier oben...', '~k. A.', 28153),
(158371, 'deDE', 'Alles ist besser, als diesen Idioten den ganzen Tag lang bei ihren Schlagübungen zuzusehen.', 'Alles ist besser, als diesen Idioten den ganzen Tag lang bei ihren Schlagübungen zuzusehen.', 28153),
(158370, 'deDE', 'Für solche Situationen empfehle ich ein 9er-Eisen direkt in die Visage!', 'Für solche Situationen empfehle ich ein 9er-Eisen direkt in die Visage!', 28153),
(158369, 'deDE', 'Endlich darf ich auch mal etwas treffen!', 'Endlich darf ich auch mal etwas treffen!', 28153),
(158368, 'deDE', 'Ha! Reingelegt! Ich arbeite schon die ganze Zeit verdeckt für die Sicherheit!', 'Ha! Reingelegt! Ich arbeite schon die ganze Zeit verdeckt für die Sicherheit!', 28153),
(158367, 'deDE', 'Keine Sorge, ich kümmere mich darum.', 'Keine Sorge, ich kümmere mich darum.', 28153),
(158366, 'deDE', 'Haltet Euch von den Gästen fern!', 'Haltet Euch von den Gästen fern!', 28153),
(158365, 'deDE', 'Dafür werde ich nicht gut genug bezahlt.', 'Dafür werde ich nicht gut genug bezahlt.', 28153),
(158364, 'deDE', 'Ich muss mich... noch ein letztes Mal... grillen...', 'Ich muss mich... noch ein letztes Mal... grillen...', 28153),
(158363, 'deDE', 'Lasst mich in der Sonne... und wendet mich, bevor ich anbrenne...', 'Lasst mich in der Sonne... und wendet mich, bevor ich anbrenne...', 28153),
(158362, 'deDE', 'Ha! Und sie sagten noch... die Sonne würde mich umbringen...', 'Ha! Und sie sagten noch... die Sonne würde mich umbringen...', 28153),
(158361, 'deDE', 'Nein, mein braungebrannter Luxuskörper...', 'Nein, mein braungebrannter Luxuskörper...', 28153),
(158360, 'deDE', 'Gallywix wird davon zu hören bekommen...', 'Gallywix wird davon zu hören bekommen...', 28153),
(158359, 'deDE', 'Ich wollte doch nur feiern...', 'Ich wollte doch nur feiern...', 28153),
(158358, 'deDE', 'Man sollte das hier besser ein Frustschloss nennen...', 'Man sollte das hier besser ein Frustschloss nennen...', 28153),
(158357, 'deDE', 'Aber ich... bin so bedeutend...', 'Aber ich... bin so bedeutend...', 28153),
(158356, 'deDE', 'Caddy, tragt mich... zum Loch.', 'Caddy, tragt mich... zum Loch.', 28153),
(158355, 'deDE', 'Wenigstens bin ich... unter Par gestorben.', 'Wenigstens bin ich... unter Par gestorben.', 28153),
(158354, 'deDE', 'Begrabt mich im Sand des Bunkers.', 'Begrabt mich im Sand des Bunkers.', 28153),
(158353, 'deDE', 'Sagt ihnen... dass ich unter Par war.', 'Sagt ihnen... dass ich unter Par war.', 28153),
(158352, 'deDE', 'Das ist die beste Party... meines Lebens.', 'Das ist die beste Party... meines Lebens.', 28153),
(158351, 'deDE', 'Das ist die mieseste Party... meines Lebens.', 'Das ist die mieseste Party... meines Lebens.', 28153),
(158350, 'deDE', 'Ich will... mein Geld zurück.', 'Ich will... mein Geld zurück.', 28153),
(158349, 'deDE', 'Nur noch... einen winzigen... Schluck...', 'Nur noch... einen winzigen... Schluck...', 28153),
(158348, 'deDE', 'Wir sind voll hier. Geht woanders schwimmen!', 'Wir sind voll hier. Geht woanders schwimmen!', 28153),
(158347, 'deDE', 'Das ist kein Schwimmbecken für Euresgleichen!', 'Das ist kein Schwimmbecken für Euresgleichen!', 28153),
(158346, 'deDE', 'Habt Ihr meinen Sprung vorhin gesehen? Dafür verdiene ich die Bestnote!', 'Habt Ihr meinen Sprung vorhin gesehen? Dafür verdiene ich die Bestnote!', 28153),
(158345, 'deDE', 'He, $PR. Geht mir mit Eurer fetten, hässlichen Visage aus der Sonne!', 'He, $PR. Geht mir mit Eurer fetten, hässlichen Visage aus der Sonne!', 28153),
(158344, 'deDE', 'Ich sag Euch, Gallywix\' Wachen werden jedes Wochenende nutzloser.', 'Ich sag Euch, Gallywix\' Wachen werden jedes Wochenende nutzloser.', 28153),
(158343, 'deDE', 'Ich zahle doch nicht drauf, um von so $geinem hässlichen:einer hässlichen:r; $PR, belästigt zu werden!', 'Ich zahle doch nicht drauf, um von so $geinem hässlichen:einer hässlichen:r; $PR, belästigt zu werden!', 28153),
(158342, 'deDE', 'Hinfort, $p. Belästigt das Gesindel am Becken.', 'Hinfort, $p. Belästigt das Gesindel am Becken.', 28153),
(158341, 'deDE', 'Haltet meine Kaja\'Cola. Ich kümmer mich drum.', 'Haltet meine Kaja\'Cola. Ich kümmer mich drum.', 28153),
(158340, 'deDE', 'Runter vom Grün! Eure Schuhe ruinieren das Gras.', 'Runter vom Grün! Eure Schuhe ruinieren das Gras.', 28153),
(158339, 'deDE', 'Caddy, Holz eins bitte! Der wird weit fliegen.', 'Caddy, Holz eins bitte! Der wird weit fliegen.', 28153),
(158338, 'deDE', 'Das nächste Mal loche ich Euren Augapfel ein!', 'Das nächste Mal loche ich Euren Augapfel ein!', 28153),
(158337, 'deDE', 'Störung auf dem Platz! Ich bekomme einen Mulligan!', 'Störung auf dem Platz! Ich bekomme einen Mulligan!', 28153),
(158336, 'deDE', 'Haut ab, $PR. Wir haben genug damit zu tun, zu trinken, zu essen und wieder zu trinken!', 'Haut ab, $PR. Wir haben genug damit zu tun, zu trinken, zu essen und wieder zu trinken!', 28153),
(158335, 'deDE', 'Ein bisschen mehr Aufregung kann nicht schaden.', 'Ein bisschen mehr Aufregung kann nicht schaden.', 28153),
(158334, 'deDE', 'Wachdienst! Sorgt dafür, dass $gdieser:diese:r; $PR verschwindet!', 'Wachdienst! Sorgt dafür, dass $gdieser:diese:r; $PR verschwindet!', 28153),
(158333, 'deDE', 'Ich habe doch nicht das Allianz-Prügelknabenpaket gekauft!', 'Ich habe doch nicht das Allianz-Prügelknabenpaket gekauft!', 28153),
(158332, 'deDE', 'Autschie...', '', 28153),
(158331, 'deDE', 'Goblins... lauft!', '', 28153),
(158330, 'deDE', 'Wollte nur... glänzendes...', '', 28153),
(158329, 'deDE', 'Hab mein Bestes gegeben...', '', 28153),
(158328, 'deDE', 'Sagt Chef G... es tut mir leid...', '', 28153),
(158327, 'deDE', 'Weiter arbeiten...', '', 28153),
(158326, 'deDE', 'Bin müde...', '', 28153),
(158325, 'deDE', 'Nein, halt... das Gold.', '', 28153),
(158324, 'deDE', 'Nicht anfassen!', '', 28153),
(158323, 'deDE', 'Unser glänzendes Gold!', '', 28153),
(158322, 'deDE', 'Chef G sagt, $PR soll zerschmettert werden.', '', 28153),
(158321, 'deDE', 'Weg von Goblins!', '', 28153),
(158320, 'deDE', 'Gold her!', '', 28153),
(158319, 'deDE', 'Gallawick ist der Beste!', '', 28153),
(158318, 'deDE', 'Weiter arbeiten!', '', 28153),
(158317, 'deDE', 'Kein Trödeln!', '', 28153),
(158316, 'deDE', 'Sie werden vor der Leere erzittern.', 'Sie werden vor der Leere erzittern.', 28153),
(158315, 'deDE', 'Ich habe sie durch den Schleier gesehen. Folgt mir.', 'Ich habe sie durch den Schleier gesehen. Folgt mir.', 28153),
(158314, 'deDE', 'Kommt her, kleine Goblins...', 'Kommt her, kleine Goblins...', 28153),
(158313, 'deDE', '', 'Unsere Streitkräfte sammeln sich bei Ar\'gorok. Ruft Eure Verbündeten und erobert Stromgarde für die Horde!', 28153),
(158312, 'deDE', '<Brecht auf und schließt Euch dem Angriff auf Lordaeron an.>', '<Brecht auf und schließt Euch dem Angriff auf Lordaeron an.>', 28153),
(158311, 'deDE', 'Überraschungen werden fortgesetzt, bis ein Stimmungsanstieg erkannt wurde.', '', 28153),
(158310, 'deDE', 'Diese köstliche Anekdote werdet Ihr Euren Freunden erzählen wollen.', '', 28153),
(158309, 'deDE', 'Kameras bereit machen. In 3... 2... 1...', '', 28153),
(158308, 'deDE', 'Initiiere Amüsement.', '', 28153),
(158307, 'deDE', 'Anfrage auf Überraschung erhalten. Fahre mit hemmungslosem Überschwang fort.', '', 28153),
(158306, 'deDE', 'Maximaler Spaßfaktor muss überschritten werden.', '', 28153),
(158305, 'deDE', 'Langweilige Partygäste werden nicht geduldet.', '', 28153),
(158304, 'deDE', 'Mangel an Spaß verzeichnet. Korrektur eingeleitet.', '', 28153),
(158303, 'deDE', '', '...Ich sage es Euch, wenn der Krieg vorüber ist.', 28153),
(158302, 'deDE', 'Schon gut.', 'Schon gut.', 28153),
(158301, 'deDE', 'Ja.', 'Ja.', 28153),
(158300, 'deDE', '', 'Wir sind nur einen Steinwurf von einem Hauptsammelpunkt der Horde entfernt und Ihr wollt wissen, warum ich eine Flasche habe, mit der man sich unsichtbar machen kann?', 28153),
(158299, 'deDE', 'Warum habt Ihr ein Fläschchen der Unsichtbarkeit?', 'Warum habt Ihr ein Fläschchen der Unsichtbarkeit?', 28153),
(158298, 'deDE', 'Pst, verschwindet! Ihr werdet noch meine Tarnung auffliegen lassen.', '', 28153),
(158297, 'deDE', 'Schickt mich zum Flaggschiff.', 'Schickt mich zum Flaggschiff.', 28153),
(158296, 'deDE', 'Wenn Ihr zu einem der Schiffe wollt, bin ich der rechte Ansprechpartner!', '', 28153),
(158295, 'deDE', 'Der riesige, wandelnde Baum ist ein beeindruckender Anblick.', '', 28153),
(158294, 'deDE', 'Ihr büßt dafür, Vog\'rish nervös zu machen!', '', 28153),
(158293, 'deDE', 'Das ist Vog\'rish noch nie passiert!', '', 28153),
(158292, 'deDE', 'Raaaaagh! Vog\'rish ist blamiert!', '', 28153),
(158291, 'deDE', 'Elfen haben einen grünen Daumen.', '', 28153),
(158290, 'deDE', 'Ich werde Euch Vog\'rishs wahre Macht zeigen!', '', 28153),
(158289, 'deDE', 'Macht Euch auf ein Inferno gefasst, Schwächlinge!', '', 28153),
(158288, 'deDE', 'Kein netter Oger mehr!', '', 28153),
(158287, 'deDE', 'Es ist schön, etwas zusätzliche Hilfe zu haben.', '', 28153),
(158286, 'deDE', '', 'Shandris... Ihr müsst... überleben...', 28153),
(158285, 'deDE', '', 'Für... mein... Volk...', 28153),
(158284, 'deDE', 'Vog\'rish verbrennt Eure Füße!', '', 28153),
(158283, 'deDE', 'Vog\'rishs Magie ist außer Kontrolle!', '', 28153),
(158282, 'deDE', '', 'Folgt mir in den Tod!', 28153),
(158281, 'deDE', 'Seht unglaubliche Macht!', '', 28153),
(158280, 'deDE', 'Ah, genau im rechten Augenblick.', '', 28153),
(158279, 'deDE', '', 'Wie es aussieht, müsst Ihr nicht mehr lange warten, Nathanos.', 28153),
(158278, 'deDE', '', 'Diese hier glitzern so schön! Ich behaupte einfach, die große hier wäre von den Gezeitenweisen gesegnet, und diese schneckenförmige stamme aus der Schatzkiste eines Piraten!', 28153),
(158277, 'deDE', '', 'Weniger Irrwische, die in ihrer Barriere sind und unsere Soldaten stechen. Gut gemacht.', 28153),
(158276, 'deDE', '', 'Dieses Gebiet muss gesäubert werden, damit unsere Truppen sicher hindurchziehen können. Unterschätzt die Irrwische nicht, sie sind in großer Zahl tödlich.', 28153),
(158275, 'deDE', '', 'Ihr glaubt nicht, was man für ein seltsames Zeug fängt, wenn man hier angelt. Ich habe in den letzten Tagen einige exotische Kreaturen an Land gezogen, wollt Ihr Euch mit mir messen?', 28153),
(158274, 'deDE', 'Lilian sagt immer wieder, dass die Horde eine Familie ist.\n\nNun, wo meine echte Familie mich nicht mehr akzeptieren wird... kann ich die Unterstützung wirklich brauchen.\n\nAber im Gegenzug hat Lilian versprochen, dass meine Familie beschützt wird. Und wenn ich das nur erreiche, indem ich der Horde helfe?\n\nNun, dann werde ich es auch tun.', '', 28153),
(158273, 'deDE', '', 'Wir verschwind\'n von hier.', 28153),
(158272, 'deDE', '', 'Kauft meine Muscheln! Die schönsten in ganz Kul Tiras. Ich meine, Azeroth! Die schönsten in ganz Azeroth!', 28153),
(158271, 'deDE', '', 'Meine Sinne kehren langsam zurück, $n.\n\nMit Lilians Hilfe werde ich dieses neue Schicksal vielleicht akzeptieren können.\n\nAber ich gebe zu... je weiter ich mich von Kul Tiras entfernen kann... desto besser.', 28153),
(158270, 'deDE', 'Ich bin dankbar für diese Gelegenheit, den Wert der Ren\'dorei für unsere Sache beweisen zu können.\n\nWir werden alles in unserer Macht Stehende tun, um den Erfolg der Allianz sicherzustellen.', '', 28153),
(158269, 'deDE', '', 'So weit hat mich Hochkommandant Wyrmbann sehr beeindruckt.\n\nEr weiß eine Vielfalt von Taktiken anzuwenden und sich veränderlichen Umständen mithilfe angemessener Strategien anzupassen.\n\nDie Kriegsanstrengungen der Allianz sind in besten Händen. Wie Ihr bin auch ich stolz darauf, meinen eigenen Beitrag dabei zu leisten.', 28153),
(158268, 'deDE', '', 'Die San\'layn müssen ausradiert werden. Der Leichtsinn der Horde bringt uns alle in Gefahr.', 28153),
(158267, 'deDE', 'Ihr werdet bald sehen. Feuer! Ja, großes Feuer!', '', 28153),
(158266, 'deDE', 'Ich werde Euch rufen, wenn Ihr wieder gebraucht werdet. Für die Allianz!', '', 28153),
(158265, 'deDE', 'König Anduin muss sofort informiert werden. Hier ist unser Werk getan, aber unsere Mission hat gerade erst begonnen.', '', 28153),
(158264, 'deDE', 'Heuert die Horde tatsächlich diese vampirischen Elfen an? Wie tief sind sie gesunken...', '', 28153),
(158263, 'deDE', 'Alles Rauch, kein Spiegel!', '', 28153),
(158262, 'deDE', 'Eurer Beschreibung nach scheint es sich um einen der San\'layn zu handeln... einen Blutprinzen.', '', 28153),
(158261, 'deDE', '', 'G-Guzzy ist tot?', 28153),
(158260, 'deDE', 'Kein Rauch ohne Feuer... Glaubt mir!', '', 28153),
(158259, 'deDE', 'Es wird Zeit, dass wir zur nächsten Phase unseres Plans übergehen.', '', 28153),
(158258, 'deDE', 'Wir haben Derek Prachtmeers Leichnam. Wir müssen nicht noch mehr Kul Tiranische Leichen erwecken. Vorläufig.', '', 28153),
(158257, 'deDE', 'Hoffen wir, dass Eure Bemühungen nicht vergebens waren.', '', 28153),
(158256, 'deDE', 'Der Krieg ist an die Dunkelküste gekommen und wir müssen unsere Leute so gut wie möglich schützen. Schickt alle Irrwische, die Ihr findet, an die Front und beseitigt jegliche Bedrohungen.', '', 28153),
(158255, 'deDE', '', 'Ha! Hab \'n Schrei von \'nem feststeckenden Verräter gehört!', 28153),
(158254, 'deDE', '', 'Rast für die Erschöpft\'n, Ess\'n für die Hungrig\'n.', 28153),
(158253, 'deDE', '', 'Ich habe mich nie bereit erklärt, die Flotte von Kul Tiras in meinen Hafen zu locken.\n\nDenkt Euch besser einen passenden Plan aus. Ich weigere mich, meine Freiheit aufzugeben.', 28153),
(158252, 'deDE', 'Beginnt mit dem Ritual.', 'Beginnt mit dem Ritual.', 28153),
(158251, 'deDE', 'Woher kommt Ihr?', 'Woher kommt Ihr?', 28153),
(158250, 'deDE', 'Wie lange seid Ihr schon hier?', 'Wie lange seid Ihr schon hier?', 28153),
(158249, 'deDE', 'Das ist das einzige Zuhause, das ich je kennengelernt habe.\n\nWir gehen dahin, wohin die Sande uns führen.', 'Das ist das einzige Zuhause, das ich je kennengelernt habe.\n\nWir gehen dahin, wohin die Sande uns führen.', 28153),
(158248, 'deDE', 'Noch bevor ich geboren wurde, nannte meine Karawane diese Sande schon ihre Heimat.\n\nJenseits des Meeres gibt es noch andere, aber ich habe sie nie selbst gesehen.', 'Noch bevor ich geboren wurde, nannte meine Karawane diese Sande schon ihre Heimat.\n\nJenseits des Meeres gibt es noch andere, aber ich habe sie nie selbst gesehen.', 28153),
(158247, 'deDE', 'Unsinn. Ihr und Eure Leute haben sich ausgezeichnet geschlagen, Magister. Ihr seid ein Gewinn für die Allianz.', '', 28153),
(158246, 'deDE', 'Im Namen aller Leerenelfen entschuldige ich mich für unser Versagen.', '', 28153),
(158245, 'deDE', '', 'Wir müssen schnell zur Wachkuppe. Los, steigt auf!', 28153),
(158244, 'deDE', 'Kua\'fon zwitschert zufrieden und rollt sich für ein Nickerchen zusammen.', '', 28153),
(158243, 'deDE', 'Der Dorfbewohner stöhnt vor Schmerzen.', 'Die Dorfbewohnerin stöhnt vor Schmerzen.', 28153),
(158242, 'deDE', 'Mok\'rah, $n! Der Außenposten untersteht Eurem Kommando.', '', 28153),
(158241, 'deDE', '', 'Hmpf.', 28153),
(158240, 'deDE', 'Wir werden Euch gut für all Euren Ärger entlohnen.', '', 28153),
(158239, 'deDE', '', 'Nathanos, ich habe Eurer Horde erlaubt, eine Basis in meinem Hafen einzurichten. Aber die Flotte der Prachtmeers herzuführen, habe ich keineswegs erlaubt!', 28153),
(158238, 'deDE', 'Das Szepter ist ein Artefakt, das immense Macht über das Meer besitzt. Wir werden uns damit einen beträchtlichen Vorteil gegenüber der Flotte von Kul Tiras verschaffen können.', '', 28153),
(158237, 'deDE', '', 'Wie wollt Ihr Euch hineinschleichen? Ihr könnt nicht einfach nach Boralus hineinspazieren...', 28153),
(158236, 'deDE', 'Ich habe Valentin nach Boralus geschickt, um Lady Prachtmeer eine Nachricht zu überbringen, koste es, was es wolle: Wir haben ihren Sohn.', '', 28153),
(158235, 'deDE', 'Beruhigt Euch, meine Freunde. Lasst Euch gesagt sein, dass dieser Pirat für seine Verbrechen bezahlen wird. Dennoch müssen wir abwarten, wie das abschließende Urteil des Gerichts lautet.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'deDE', 'Unsere Mission hier besteht darin, das abyssische Szepter zu beschaffen, das sich in den Tiefen der Sturmsangabtei in Boralus befindet.', '', 28153),
(158233, 'deDE', '', 'Kommt rein, $n. Nathanos wird Euch alles erklären.', 28153),
(158232, 'deDE', 'Das Gericht hat Euch des Verbrechens des Wuchers für schuldig befunden. Euer raffgieriges Verleihgeschäft hat viele gute Leute des Hakenkaps ihrer Ersparnisse beraubt. Viele leben durch Eure Missetaten jetzt auf der Straße.', '', 28153),
(158231, 'deDE', 'Das Gericht hat Euch der Verbrechen der Piraterie, des Diebstahls und des Mordes für schuldig befunden. Piraterie ist gemäß den Gesetzen von Kul Tiras eins der abscheulichsten Verbrechen, und jetzt erwartet Euch Eure gerechte Strafe.', '', 28153),
(158230, 'deDE', 'Wucher und organisiertes Verbrechen! Viele der Familien, die heute hier sind, fielen Euren Intrigen zum Opfer. Ihr habt den braven Leuten von Kul Tiras zu hohe Preise abgeknöpft und jetzt werdet Ihr dafür die Zeche zahlen.', '', 28153),
(158229, 'deDE', 'Folgt mir. Wir werden sofort bei Alleria und dem Oberkommandanten vorsprechen.', '', 28153),
(158228, 'deDE', 'Dies ist nicht der große Sieg, den ich mir für die Allianz erhofft hatte, aber ich werde mein Versagen hier nicht noch durch Säumigkeit verschlimmern.', '', 28153),
(158227, 'deDE', 'Die ganze Zeit waren wir hinter einem falschen Gallywix her? Goblins sind echt das Schlimmste.', '', 28153),
(158226, 'deDE', 'Bis später, Ihr Verlierer!', '', 28153),
(158225, 'deDE', 'Aber diese Mechanzüge sind nicht billig, $p. Dafür lass ich Euch eine Rechnung zukommen!', '', 28153),
(158224, 'deDE', 'Ihr seid auf den ältesten Trick der Bilgewässer reingefallen: hochwertige, schlecht bezahlte Arbeiter!', '', 28153),
(158223, 'deDE', 'Ha! Ich wünschte, Ihr könntet jetzt Eure Gesichter sehen.', '', 28153),
(158222, 'deDE', '', 'Der Gedanke, dass ein Geist Bwonsamdi entkomm\'n könnte, ist schon beeindruckend. Ich hoff, dass die Bindung zu seinen Freunden reich\'n wird, um ihn auf der Andren Seite zu erreich\'n.', 28153),
(158221, 'deDE', '$n, auf der Westseite des Lagers gibt es ein Teleskop. Warum haltet Ihr nicht einfach Ausschau nach ihm?', '', 28153),
(158220, 'deDE', 'Hmm... tja, wo ist Guzbert? Er müsste jeden Augenblick um die Ecke kommen.', '', 28153),
(158219, 'deDE', '', 'Bin ich die Erste, die zurück ist? Wo ist Guzzy?', 28153),
(158218, 'deDE', 'Willkommen zurück, Fräulein Stahlfunken.', '', 28153),
(158217, 'deDE', '', 'He, Boss! Habt Ihr den Knall gehört? Da habe ich wohl einen Goblin in den niedrigen Orbit geschleudert.', 28153),
(158216, 'deDE', 'Guzbert und Kelsey müssten jeden Moment hier sein.', '', 28153),
(158215, 'deDE', 'Ach, was hat die Welt schon für mich getan?', '', 28153),
(158214, 'deDE', 'Euer Ego ist so aufgebläht wie Euer Körper. Denkt doch nur, wie viel Gutes Ihr in der Welt hättet ausrichten können!', '', 28153),
(158213, 'deDE', 'Ihr häuft ein Vermögen an und dann baut Ihr damit so etwas, Gallywix? Ein sittenloses Loch?', '', 28153),
(158212, 'deDE', '', 'Setzt \'Beleben\' ein, um Eure Gesundheit komplett aufzufüllen.', 28153),
(158211, 'deDE', 'Setzt \'Beleben\' ein, um Eure Gesundheit komplett aufzufüllen.', '', 28153),
(158210, 'deDE', '', 'Verletzungen gehören zum Kampf dazu, doch Ihr könnt Euch oder Verbündete durch die Nebel heilen. Heilt Eure Wunden mit \'Beleben\'.', 28153),
(158209, 'deDE', 'Verletzungen gehören zum Kampf dazu, doch Ihr könnt Euch oder Verbündete durch die Nebel heilen. Heilt Eure Wunden mit \'Beleben\'.', '', 28153),
(158208, 'deDE', 'Die Allianz wurde besiegt!', '', 28153),
(158207, 'deDE', '|A:Warfront-HordeWave3:25:23:0:0|aEin Angriffstrupp der Horde wurde entsandt!', '|A:Warfront-HordeWave3:25:23:0:0|aEin Angriffstrupp der Horde wurde entsandt!', 28153),
(158206, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Heldenrufpass ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Heldenrufpass ist verloren!', 28153),
(158205, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNeuhof ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNeuhof ist verloren!', 28153),
(158204, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente ist verloren!', 28153),
(158203, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Hochstand ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Hochstand ist verloren!', 28153),
(158202, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz ist verloren!', 28153),
(158201, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aGalsons Mine ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aGalsons Mine ist verloren!', 28153),
(158200, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aDas Hochlandsägewerk ist verloren!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aDas Hochlandsägewerk ist verloren!', 28153),
(158199, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aGalsons Mine wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aGalsons Mine wird angegriffen!', 28153),
(158198, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aDas Hochlandsägewerk wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aDas Hochlandsägewerk wird angegriffen!', 28153),
(158197, 'deDE', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aEuer Kommandant wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aEuer Kommandant wird angegriffen!', 28153),
(158196, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Heldenrufpass wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Heldenrufpass wird angegriffen!', 28153),
(158195, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNeuhof wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNeuhof wird angegriffen!', 28153),
(158194, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente wird angegriffen!', 28153),
(158193, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz wird angegriffen!', 28153),
(158192, 'deDE', 'Den großen roten Knopf drücken, wenn Ihr es sagt. Verstanden.', 'Den großen roten Knopf drücken, wenn Ihr es sagt. Verstanden.', 28153),
(158191, 'deDE', 'Zeigt mir, wohin ich fliegen kann.', 'Zeigt mir, wohin ich fliegen kann.', 28153),
(158190, 'deDE', 'Wollt Ihr irgendwohin fliegen?', '', 28153),
(158189, 'deDE', 'Schon wieder überboten worden! Wieso wollen einige Profit aus dem Elend anderer schlagen?', 'Schon wieder überboten worden! Wieso wollen einige Profit aus dem Elend anderer schlagen?', 28153),
(158188, 'deDE', 'Wir haben nichts Wertvolles mehr zu verkaufen.', 'Wir haben nichts Wertvolles mehr zu verkaufen.', 28153),
(158187, 'deDE', 'Ich hoffe, wir haben genug übrig, um die benötigen Vorräte zu kaufen.', 'Ich hoffe, wir haben genug übrig, um die benötigen Vorräte zu kaufen.', 28153),
(158186, 'deDE', 'Wie viel Gold haben wir noch?', 'Wie viel Gold haben wir noch?', 28153),
(158185, 'deDE', 'Die Rationen reichen nicht...', 'Die Rationen reichen nicht...', 28153),
(158183, 'deDE', 'Passt auf der Straße auf. Etwas Sonderbares lauert in Drustvars Schatten.', 'Passt auf der Straße auf. Etwas Sonderbares lauert in Drustvars Schatten.', 28153),
(158182, 'deDE', 'Hey... was... Der Anzug hat eine Fehlfunktion!', '', 28153),
(158181, 'deDE', 'Die Raben kreisen schon über mir! Das Gelächter will nicht aufhören! Sie kommen, um mich zu holen!', '', 28153),
(158180, 'deDE', '', 'Wegen Euch... hab ich... das gute Zeug verschüttet...', 28153),
(158179, 'deDE', '', 'Ihr glaubt wohl, Ihr könntet mich veräppeln, was?! Euch <hick> werd ich\'s zeigen!', 28153),
(158178, 'deDE', '', 'Gute Arbeit. Wir sehen uns auf der anderen Seite des Lagers.', 28153),
(158177, 'deDE', 'Schaut Euch das an, Gallywix!', 'Schaut Euch das an, Gallywix!', 28153),
(158176, 'deDE', 'Die Allianz? Hier, in Zandalar?', '', 28153),
(158175, 'deDE', 'Wir reisen mit den Sanden.', 'Wir reisen mit den Sanden.', 28153),
(158174, 'deDE', 'Die Dünen stecken voller Schätze, die nur darauf warten, gefunden zu werden.', 'Die Dünen stecken voller Schätze, die nur darauf warten, gefunden zu werden.', 28153),
(158173, 'deDE', 'Zuhause ist, wo der Wagen ist.', 'Zuhause ist, wo der Wagen ist.', 28153),
(158171, 'deDE', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t%s zielt mit der |cFFFF0000|Hspell:271296|h[Blutkeule]|h|r auf Euch!', '', 28153),
(158170, 'deDE', '', 'Arme Seelen... Das sollte niemand erdulden müssen. Wir müssen einen Weg finden, sie zurückzubringen, sobald Jaina sicher ist.', 28153),
(158169, 'deDE', 'Eins steht fest: Ganz Drustvar ist verrückt geworden.', 'Eins steht fest: Ganz Drustvar ist verrückt geworden.', 28153),
(158168, 'deDE', 'Ich hab einen von ihnen von Wild reden gehört, das nach Menschenfleisch lechzt.', 'Ich hab einen von ihnen von Wild reden gehört, das nach Menschenfleisch lechzt.', 28153),
(158167, 'deDE', 'Das mit den Bestienmenschen und Holzdämonen? Ja, das habe ich auch mitbekommen.', 'Das mit den Bestienmenschen und Holzdämonen? Ja, das habe ich auch mitbekommen.', 28153),
(158166, 'deDE', 'Habt Ihr gehört, was sie gesagt haben? Warum diese Flüchtlinge hier sind?', 'Habt Ihr gehört, was sie gesagt haben? Warum diese Flüchtlinge hier sind?', 28153),
(158165, 'deDE', 'Manchmal denke ich, ich könnte mit meinem Mund Summgeräusche machen und mit meinen Bienen kommunizieren, aber das wird wahrscheinlich nicht funktionieren, solange ich mein Ganzkörperbienenkostüm nicht fertig habe. Mal abgesehen davon sind meine Bienen die besten. Wollt Ihr gegen sie kämpfen oder abschwirren?', '', 28153),
(158164, 'deDE', '', 'Möge unser Wille stärker sein als ihre Kriegsmaschinen.', 28153),
(158163, 'deDE', 'Die Kaldorei werden Eure Taten nie vergessen, $n. Eure Hilfe in dieser dunklen Stunde könnte den Unterschied ausmachen.', '', 28153),
(158162, 'deDE', 'Wir stehen vor einer großen Prüfung, aber verzweifelt nicht! Die Göttin gibt uns Kraft, daran müssen wir uns klammern.', '', 28153),
(158161, 'deDE', 'Der Krieg wird nicht von EINER Schlacht entschieden. Unsere Zeit WIRD kommen.', '', 28153),
(158160, 'deDE', 'König Anduin sendet uns Soldaten zu Hilfe. Wir müssen standhalten, bis sie hier sind.', '', 28153),
(158159, 'deDE', 'Unsere Flotte ist aus Silithus zurück. Elune sei Dank! Wir haben sie bitter vermisst.', '', 28153),
(158158, 'deDE', 'Die Barriere aus Irrwischen hält stand. Dennoch stößt die Horde in die Dunkelküste vor.', '', 28153),
(158157, 'deDE', 'Das hat ihrer Moral sicherlich einen Dämpfer verpasst. Unterschätzt niemals die Wirkung psychologischer Kriegsführung.', '', 28153),
(158156, 'deDE', 'Ihr habt mit Nathanos ein paar harte Worte gewechselt.', 'Ihr habt mit Nathanos ein paar harte Worte gewechselt.', 28153),
(158155, 'deDE', 'Die Piraten von Freihafen werden mit jedem Tag frecher. Wir müssen in ihren Rängen Chaos säen. Verwendet eins ihrer Reittiere und verpasst ihnen eine Dusche, die sie so schnell nicht vergessen!', '', 28153),
(158154, 'deDE', '', 'Alle Seefahrer fürcht\'n den Ruf der Sirenen. Aber einige fürcht\'n ihn offenbar nich\' genug.', 28153),
(158153, 'deDE', '', 'Die Sirenen hab\'n \'n weiteres Versorgungsschiff aus Kul Tiras ins Verderben gelockt. Durchsucht das Wrack nach allem, das wir gebrauch\'n könn\'n. Aber seht Euch vor. Nich\' dass Ihr auch noch so endet wie die Crew des Schiffs!', 28153),
(158152, 'deDE', 'Auf Euch wartet ein Schicksal, das viel schlimmer ist als der Tod...', '', 28153),
(158151, 'deDE', 'Ihr glaubt, Ihr habt gewonnen? Mein Fall ist nur der Anfang Eures Niedergangs!', '', 28153),
(158150, 'deDE', 'Sehr gut. Damit haben unsere Feinde nicht mehr die Mittel, um uns herauszufordern.', '', 28153),
(158149, 'deDE', 'Wir dürfen den Kul Tiranern nicht erlauben, noch mehr Azeritmunition herzustellen. Legt die Produktion dieser Gießerei still!', '', 28153),
(158148, 'deDE', '', 'Wenn Fanatiker an Eurer Treue zweifeln, bleibt Ihr nicht lange am Leben.\n\nIch wurde zu diesem Feldzug zwangsverpflichtet. Vielleicht wurdet Ihr das ja auch. Zum Überleben tut man... und sagt man, was man muss.\n\nAber glaubt mir, es gibt nur einen Krieg, der von Bedeutung ist. Und das ist nicht der hier.', 28153),
(158147, 'deDE', 'Ihr werdet... ihr Schicksal teilen...', '', 28153),
(158146, 'deDE', 'Ihr seid... zu spät, um sie zu retten...', '', 28153),
(158145, 'deDE', 'Euch alle erwartet... das Leid!', '', 28153),
(158144, 'deDE', 'Sie ist... bereits verloren...', '', 28153),
(158143, 'deDE', 'Die Rache ist nah!', '', 28153),
(158142, 'deDE', 'Prachtmeer gehört uns!', '', 28153),
(158141, 'deDE', 'Auch Ihr werdet verschlungen!', '', 28153),
(158140, 'deDE', 'Ihr werdet ebenso leiden wie sie!', '', 28153),
(158139, 'deDE', '', 'Ich arbeite jetzt schon so lange in dieser Gegend, dass ich einige interessante Manifestationen dieses Azeritzeugs gefunden habe. Wollt Ihr Euer Glück gegen einige dieser bösartigen Azeritelementare versuchen, die ich tief unten eingesammelt habe?', 28153),
(158138, 'deDE', 'IHR NARREN! Ihr habt nicht den Hauch einer Ahnung, mit welchen Mächten Ihr Euch anlegt!', '', 28153),
(158137, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Hochstand wird angegriffen!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Hochstand wird angegriffen!', 28153),
(158136, 'deDE', '', 'Nicht ganz. Wenn man eine Chance sieht, muss man sie ergreifen.\n\nIch hatte immer Pläne für die Zukunft. Und es wird langsam Zeit, dass ich diese Pläne in die Realität umsetze.', 28153),
(158135, 'deDE', 'Ich dachte, Ihr dient den Ungekrönten. Seid Ihr übergelaufen?', 'Ich dachte, Ihr dient den Ungekrönten. Seid Ihr übergelaufen?', 28153),
(158134, 'deDE', 'Ich bin FREI! Ich danke Euch... und jetzt werden Eure Seelen meinen bodenlosen Hunger stillen!', '', 28153),
(158133, 'deDE', 'Welche Region Ihr als erstes in Angriff nehmt, ist Euch überlassen. Sobald Ihr Euch entschieden habt, legen wir ab.', '', 28153),
(158132, 'deDE', '', 'Gute Arbeit. Die Wachen kümmern sich um den Rest. Wir müssen das Anwesen zukünftig genau im Auge behalten.', 28153),
(158131, 'deDE', '', 'Aus dem Kronsteiganwesen quellen ekelhafte Monstrositäten! Wir müssen sie aufhalten, bevor sie Aroms Wehr erreichen!', 28153),
(158129, 'deDE', 'Wir werden diesen Krieg gewinnen, $n. Für die Allianz!', '', 28153),
(158128, 'deDE', 'Sucht nach Möglichkeiten, die Pläne des Kriegshäuptlings in den Trolllanden zu durchkreuzen.', '', 28153),
(158127, 'deDE', 'Die Stützpunkte, die Ihr uns in Zandalar gesichert habt, waren ein kühner erster Schritt. Von dort aus werden wir den Kampf zur Horde tragen!', '', 28153),
(158126, 'deDE', 'Der Kriegsverlauf verändert sich fortwährend. Es wird Zeit, dass wir unsere Strategie entsprechend anpassen.', '', 28153),
(158125, 'deDE', 'Ich war noch nie zuvor so hungrig...', 'Ich war noch nie zuvor so hungrig...', 28153),
(158124, 'deDE', 'Champion, Euer Einsatz in Kul Tiras hat uns entscheidend weitergeholfen. Nur durch Einheit kann die Allianz stärker werden.', '', 28153),
(158123, 'deDE', 'Für die Allianz!', '', 28153),
(158122, 'deDE', 'Doch bis dahin solltet Ihr wissen, dass Ihr eine Inspiration seid für alle um Euch herum. Und dafür danke ich Euch von Herzen.', '', 28153),
(158121, 'deDE', 'Die Allianz braucht auch weiterhin Eure Hilfe, $n. Wir können dem Kriegshäuptling nur schaden, wenn wir ihre Bande mit den Zandalari durchtrennen. Dieser Tag wird kommen... schon bald.', '', 28153),
(158120, 'deDE', 'Ich wünschte, ich könnte sagen, dass unsere Aufgabe hier erfüllt ist, doch es gibt noch viel zu tun. Uns erwartet große Finsternis, bevor das Licht wieder erstrahlt.', '', 28153),
(158119, 'deDE', 'Champion, Ihr habt in unserem Feldzug gegen einen unerbittlichen Feind an vorderster Front gekämpft. Im Kampf gegen die Horde habt Ihr stets Mut bewiesen... und Ehre.', '', 28153),
(158118, 'deDE', '', 'Für die Horde!', 28153),
(158117, 'deDE', '', 'Ihr verkörpert alle Ideale der Horde, $n. Ihr seid der Funke, der Boralus in Brand setzen wird.', 28153),
(158116, 'deDE', '', 'Kul Tiras ist zu einer Hochburg der Allianz herangewachsen. Durch die stolze Flotte schöpfen sie neuen Mut. Doch schon bald werden diese Wasserratten den Preis für ihren Hohn bezahlen.', 28153),
(158115, 'deDE', '', 'Auch wenn der Sieg noch nicht unser ist, rückt er doch jeden Tag näher. Wir dürfen nicht ruhen, bevor alle Hoffnung im Herzen dieses kleinen Königs zu Asche wird.', 28153),
(158114, 'deDE', '', 'Die Welt ist voller Soldaten, Champion, aber nur wenige sind für den Krieg geschaffen. Ihr hingegen scheint darin regelrecht aufzugehen.', 28153),
(158113, 'deDE', '', 'Wenn sie nicht mehr an ihr Ziel glauben, ist Euch der Sieg sicher, $n. Für die Horde!', 28153),
(158112, 'deDE', '', 'Nutzt die Stützpunkte, die Ihr in Kul Tiras gesichert habt, um die Streitkräfte des kleinen Königs zu lähmen! Raubt ihnen die Hoffnung!', 28153),
(158111, 'deDE', '', 'Doch ein Sieg benötigt mehr als nur die Stärkung der eigenen Reihen. Wir müssen dem Feind so lange zusetzen, bis er vor uns kriecht.', 28153),
(158110, 'deDE', '', 'Ich wusste, Ihr wart die beste Wahl, um die Zandalari für unsere Seite zu gewinnen.', 28153),
(158109, 'deDE', '', 'Champion, als uns Prinzessin Talanji um Hilfe ersuchte, war das DIE Gelegenheit, die Stärke ihres Königreichs mit der unseren zu vereinigen.', 28153),
(158108, 'deDE', 'Hier is\' selbst die Erde tot. Das is\' finster, Mann. Echt finster.', '', 28153),
(158107, 'deDE', '', 'Wärmt Eure Hände und ruht Eure müden Knochen aus, $C.', 28153),
(158106, 'deDE', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s beginnt, |cFFFF0000|Hspell:273361|h[Lache der Dunkelheit]|h|r zu wirken!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s beginnt, |cFFFF0000|Hspell:273361|h[Lache der Dunkelheit]|h|r zu wirken!', 28153),
(158105, 'deDE', 'Willkommen in der Flinkwindstation, $n! Dieser Außenposten steht unter Eurem Kommando.', '', 28153),
(158104, 'deDE', 'Hätte ich doch nur... die optionale Garantieverlängerung... genommen...', '', 28153),
(158103, 'deDE', 'Willkommen in Gallywix\' SCHMERZschloss, Ihr Gesindel!', '', 28153),
(158102, 'deDE', 'Bittet Fozruk, Ar\'gorok anzugreifen.', 'Bittet Fozruk, Ar\'gorok anzugreifen.', 28153),
(158101, 'deDE', 'Die Verderbnis breitet sich schneller aus, als ich dachte...', '', 28153),
(158100, 'deDE', 'Diese Sporen sind unnatürlich. Wir müssen ihren Ursprung herausfinden.', '', 28153),
(158099, 'deDE', 'Wir haben getan, was wir konnten. Mögen sie Frieden im nächsten Leben finden.', '', 28153),
(158098, 'deDE', 'Die Geister sind in Unruhe hier. Wir müssen sie von ihrer Qual befreien.', '', 28153),
(158097, 'deDE', '', 'Gut gemacht. Mög\'n sie Fried\'n find\'n.', 28153),
(158096, 'deDE', '', 'Die Geister sin\' ruhelos. Helft ihnen, Fried\'n zu find\'n.', 28153),
(158095, 'deDE', '', 'Mit den Sporen könn\'n wir den Ursprung der Fäulnis find\'n und sie ausrott\'n.', 28153),
(158094, 'deDE', '', 'Die Fäulnis breitet sich schnell aus. Wir müss\'n \'nen Weg find\'n, sie aufzuhalt\'n. Sammelt die Sporen, vielleicht lern\'n wir so mehr.', 28153),
(158093, 'deDE', 'Brüder und Schwestern! Die Horde dringt tiefer in die Dunkelküste vor. Sammelt Euch an den Wildschnellen!', '', 28153),
(158092, 'deDE', 'Ihr wurdet mit der Macht des Windes erfüllt!', 'Ihr wurdet mit der Macht des Windes erfüllt!', 28153),
(158091, 'deDE', 'Ich will, dass all dieses Gold sofort wieder zurück zum Palast geschafft wird, und dann...', '', 28153),
(158090, 'deDE', 'Keine Verzögerungen! Keine Ausreden! Keine Beförderung!', '', 28153),
(158089, 'deDE', 'Aus dem Weg! Die Allianz ist da!', '', 28153),
(158088, 'deDE', 'Ich werde nicht sterben... nicht durch die Hand eines Goblins.', '', 28153),
(158087, 'deDE', 'Die Allianz baut auf die Leerenelfen. Wir werden sie nicht enttäuschen.', '', 28153),
(158086, 'deDE', 'Gallywiiiiix!', 'Gallywiiiiix!', 28153),
(158085, 'deDE', 'Bloß weg hier! Die Allianz!', 'Bloß weg hier! Die Allianz!', 28153),
(158084, 'deDE', '', 'Die Horde muss die Furbolgs aus ihrer Heimat vertrieben haben.', 28153),
(158083, 'deDE', '', 'Die Horde... es sind so viele...', 28153),
(158082, 'deDE', 'Heiliger Goldsack! Wo kommt denn der Elf her?!', 'Heiliger Goldsack! Wo kommt denn der Elf her?!', 28153),
(158081, 'deDE', '', 'Die Furbolgs sind für gewöhnlich friedliebend. Aus ihrer Heimat vertrieben worden zu sein, muss sie in Raserei versetzt haben.', 28153),
(158078, 'deDE', '', 'Ich wandle durch die Schatten.', 28153),
(158077, 'deDE', '', 'Jawohl!', 28153),
(158076, 'deDE', '', 'Vorsichtig, Champion! Wir müssen leise sein.', 28153),
(158075, 'deDE', '', 'Schnell, erledigt den hier, bevor er die anderen alarmiert!', 28153),
(158074, 'deDE', '', 'Lasst Euch nicht entdecken! Wir dürfen keine Aufmerksamkeit erregen...', 28153),
(158073, 'deDE', 'Ich bin gleich da, Lanfa!', '', 28153),
(158072, 'deDE', '', 'Nach Euch, $n. Wenn Ihr wollt, dass ich einen von ihnen ausschalte, sagt es einfach. Aber... leise.', 28153),
(158071, 'deDE', 'Harli bringt Euch da hin un\' holt mich dann nach. Ich muss wiss\'n, ob mit meiner Frau alles in Ordnung is\'!', '', 28153),
(158070, 'deDE', 'Da habter denen aber \'ne ord\'ntliche Lektion erteilt. Schau\'n wir ma\', ob die was draus lern\'.', '', 28153),
(158069, 'deDE', 'Die Zwerglinge kapier\'n es einfach nich\'. Sie sin\' hier nich\' willkomm\'. Zeigt denen, was die Zandalari von Eindringling\'n halt\'n!', '', 28153),
(158068, 'deDE', 'Falls jemand den Hügel hochkommt... tötet ihn!', '', 28153),
(158067, 'deDE', 'Wenn wir die Flotte zerlegt haben, gehört Zandalar uns!', '', 28153),
(158066, 'deDE', 'Stellt die Säulen auf!', '', 28153),
(158065, 'deDE', '<Wartet einen Moment, während Genn Katherine in einer wirklich großartigen Videosequenz überzeugt.>', '<Wartet einen Moment, während Genn Katherine in einer wirklich großartigen Videosequenz überzeugt.>', 28153),
(158064, 'deDE', 'Die Menschen von Kul Tiras sind vereint, aber ihr führendes Haus ist es nicht und der Allianz fehlt eine ihrer mächtigsten Anführerinnen.\n\nIch hoffe, dass diese Kluft ebenfalls geschlossen werden kann.', '', 28153),
(158063, 'deDE', 'Trefft mich am Familiendenkmal bei Burg Prachtmeer. Mit Glück können wir Lordadmiralin Prachtmeer davon überzeugen, die Hinrichtung ihrer Tochter aufzuschieben.', '', 28153),
(158062, 'deDE', 'Champion, Ihr habt dem Volk von Kul Tiras geholfen, zusammenzufinden und sich der Allianz anzuschließen. Vielleicht könnt Ihr jetzt auch einer Mutter und ihrer Tochter helfen, zusammenzufinden.', '', 28153),
(158061, 'deDE', 'Die Unterbrechung ihres Nachschubs wird die Angriffe der Horde schwächen. Ihr habt uns etwas Zeit verschafft.', '', 28153),
(158060, 'deDE', 'Diese scheußlichen Goblins bohren nach Treibstoff für ihre Kriegsmaschinen! Setzt ihrem Frevel ein Ende.', '', 28153),
(158059, 'deDE', '', 'Die Feuer brennen und wir rücken unaufhaltsam vor.', 28153),
(158058, 'deDE', '', 'Diese Elementare werden uns als Treibstoff für unsere Verwüster dienen. Tötet sie, genauso wie jeden Kaldorei, der Euch dabei im Weg steht.', 28153),
(158057, 'deDE', 'Wir können durch die Leere reisen, um Zeit zu sparen. Folgt mir.', '', 28153),
(158056, 'deDE', 'Gallywix ist ein schlüpfriger Geselle. Er wird nicht lange in der Öffentlichkeit bleiben.', '', 28153),
(158055, 'deDE', 'Ich hätte wissen müssen, dass ein Goblin wie Gallywix der Versuchung nicht widerstehen können würde, eine Stadt aus purem Gold zu plündern.', '', 28153),
(158054, 'deDE', '', 'Wir wurden entdeckt! Sammelt so viel Azerit wie Ihr könnt! Wir können nicht lange hier bleiben.', 28153),
(158053, 'deDE', '', 'Bei der Göttin... Azerit! Es ist überall!', 28153),
(158052, 'deDE', 'Überall tauchen Azeritvorkommen auf.', 'Überall tauchen Azeritvorkommen auf.', 28153),
(158051, 'deDE', '<Legt Eure Hand auf das Azeritvorkommen.>', '<Legt Eure Hand auf das Azeritvorkommen.>', 28153),
(158050, 'deDE', '<Das Azeritvorkommen brummt vor Energie.>', '', 28153),
(158049, 'deDE', '', 'Ihr übernehmt den Schredder! Ich vertreibe die Eindringlinge aus dem Hain.', 28153),
(158048, 'deDE', 'Der Hain der Uralten! Oh, mein...', 'Der Hain der Uralten! Oh, mein...', 28153),
(158047, 'deDE', 'Bin dran!', 'Bin dran!', 28153),
(158046, 'deDE', 'Passt auf die Furbolgs auf. Sie sind plötzlich in Scharen aufgetaucht.', 'Passt auf die Furbolgs auf. Sie sind plötzlich in Scharen aufgetaucht.', 28153),
(158045, 'deDE', 'Bin auf dem Weg!', 'Bin auf dem Weg!', 28153),
(158044, 'deDE', 'Die Furbolgs scheinen ungewöhnlich aggressiv zu sein...', 'Die Furbolgs scheinen ungewöhnlich aggressiv zu sein...', 28153),
(158043, 'deDE', '|TInterface\\Icons\\INV_misc_boilingblood:20|t %s zielt mit einer |cFFFF0000|Hspell:271224|h[Plasmaentladung]|h|r auf Euch!', '', 28153),
(158042, 'deDE', 'Unterschätzt die Wirkung Eurer Taten nicht! Während die sich von solchen Niederlagen erholen, können wir unsere Präsenz in der Region weiter stärken.', '', 28153),
(158041, 'deDE', 'Die Horde will ihre Stellung hier festigen. Versalzt ihnen die Suppe, Champion!', '', 28153),
(158040, 'deDE', '', 'Das Rudel überlebt. Ihr habt gute Arbeit geleistet.', 28153),
(158039, 'deDE', '', '\'ne höchst ungewöhnliche Gruppe Jungtiere brauch Hilfe. Helft denen un\' erlangt so die Gunst von Gonk!', 28153),
(158038, 'deDE', 'Ein Regiment weniger, um das wir uns Sorgen machen müssen. Ausgezeichnete Arbeit.', '', 28153),
(158037, 'deDE', '', 'Zandalar für immer!', 28153),
(158036, 'deDE', '', 'Un\' wär dieser Champion der Horde nich\' gewes\'n, wär\'n unsre Verluste noch viel bitt\'rer.$bDas beweist mehr denn je, dass wir uns anpass\'n müss\'n, wieder ein Teil der Welt werd\'n müss\'n.', 28153),
(158035, 'deDE', '', 'Diese Gleve wird uns dran erinnern: Egal wie tief wir fall\'n, egal wie viel wir verlier\'n, wir sin\' die Zandalari!$bWir lass\'n uns nich\' unterkrieg\'n, wir überleb\'n!', 28153),
(158034, 'deDE', '', 'ER war verantwortlich für den Tod so vieler unsrer Brüder un\' Schwestern.', 28153),
(158033, 'deDE', '', 'Seht das Blut von G\'huun. ER war verantwortlich für den Tod von Shadra, Hir\'eek, Torga un\'... un\' Rezan.', 28153),
(158032, 'deDE', 'Unsere Späher berichten von einem Kriegsschiff der Horde vor der Küste. Seht zu, dass ihre Truppen keinen Fuß auf festen Boden setzen!', '', 28153),
(158031, 'deDE', '', 'Das war nich\' mein Verdienst.', 28153),
(158030, 'deDE', 'In diesem Land ist wirklich nichts selbstverständlich, Champion. Dank Euch können unsere Spione nun weiter ihrer Mission nachgehen.', '', 28153),
(158029, 'deDE', 'Zeigt ihn\' die Klinge. Werdet zu dem Symbol, das die brauch\'n.', '', 28153),
(158028, 'deDE', 'Ihr habt unternomm\', was nötig war, um Euer Volk zu rett\'n.$bJetz\' erst recht verlang\'n sie nach\'m Anführer, der ihre Liebe un\' ihr Vertrau\'n verdient.', '', 28153),
(158027, 'deDE', 'Ihr habt \'nen Champion in das Land hier gebracht, geg\'n den Will\'n von Euerm Vater. Ihr gingt G\'huun nach, als niemand zuhör\'n wollte.', '', 28153),
(158026, 'deDE', 'Mehrere Agenten des SI:7 sind in diesem Gebiet auf Mission, aber wir haben noch keinen einzigen Bericht erhalten. Findet den Grund für diese Verzögerung!', '', 28153),
(158025, 'deDE', 'Anführerin von Zandalar! Zeigt die Klinge denen, die sie am nötigst\'n seh\'n müss\'n! Schenkt ihn\' Fried\'n!', '', 28153),
(158024, 'deDE', '', 'Vol\'jin, hört Ihr uns? Zeigt Euch, Geist!', 28153),
(158023, 'deDE', 'Die Horde wird mit Blut für jeden Zentimenter bezahlen, den sie hier einzunehmen versuchen. Selbst kleine Siege können hier das Blatt zu unseren Gunsten wenden. Gut gemacht.', '', 28153),
(158022, 'deDE', 'Leid... Leid. So viel Leid. So viele brauch\'n Führung. So viele brauch\'n Genugtuung. G\'huun hat ihn\' die Hoffnung geraubt.', '', 28153),
(158021, 'deDE', 'Die Horde glaubt, sie hätte die Vorherrschaft in diesem Gebiet. Beweist ihnen das Gegenteil, Champion!', '', 28153),
(158020, 'deDE', '', 'Psst.', 28153),
(158019, 'deDE', 'Ich hör ihn!', '', 28153),
(158018, 'deDE', 'Leid...', '', 28153),
(158017, 'deDE', '', 'Vol\'jin, Sohn von Sen\'jin, hört die Stimm\' Eurer Familie un\' Freunde. Sie frag\'n sich, wo Ihr seid.', 28153),
(158016, 'deDE', 'Azerit platzieren', 'Azerit platzieren', 28153),
(158015, 'deDE', 'Ihr müsst den Hain der Uralten verteidigen!', 'Ihr müsst den Hain der Uralten verteidigen!', 28153),
(158014, 'deDE', 'Ich bleibe wachsam.', 'Ich bleibe wachsam.', 28153),
(158013, 'deDE', '<Helft ihm auf.>', '<Helft ihm auf.>', 28153),
(158012, 'deDE', 'Ich will ehrlich mit Euch sein... Es war schon mal schlimmer.\n\nAber nicht viel.', '', 28153),
(158011, 'deDE', '', 'Champion! Die Urtume rufen uns! Findet die Druiden der Klaue im Wald und trefft mich dann im Hain der Uralten.', 28153),
(158009, 'deDE', '', 'Das hat uns etwas Zeit erkauft. Schildwachen, haltet die Position!', 28153),
(158008, 'deDE', '', 'Ich habe ihn nicht gesehen. Ich fürchte, Euer Kamerad könnte dem Lockruf der Sirenen erlegen sein.', 28153),
(158007, 'deDE', '<Fragt, ob sie Finn gesehen hat.>', '<Fragt, ob sie Finn gesehen hat.>', 28153),
(158006, 'deDE', 'Weg? Was meint Ihr mit \"weg\"? Ich verlange Entschädigung!', 'Weg? Was meint Ihr mit \"weg\"? Ich verlange Entschädigung!', 28153),
(158005, 'deDE', '', 'Ihr seid nicht der Einzige, der Akten vom SI:7 anfordert.', 28153),
(158004, 'deDE', 'Wie kommt es, dass eine angesehene Elfengeneralin etwas über jemanden wie mich weiß?', '', 28153),
(158003, 'deDE', '', 'Wenn ich an Euren Einsatz in den ersten drei Kriegen bis hin zu Euren Heldentaten im Rotkammgebirge denke, seid Ihr auf Eure Art auch ein Held.', 28153),
(158002, 'deDE', 'Wenn Ihr mich fragt, bin ich kaum würdig, an Eurer Seite zu dienen. Euch Respekt zu zollen und zu schweigen ist das Mindeste, was ich tun kann.', '', 28153),
(158001, 'deDE', 'Herrin, ich habe Eure SI:7-Akte gelesen. Ihr lebt schon mehr als zehntausend Jahre und habt in mehr Kriegen gekämpft, als ich mir je vorstellen könnte.', '', 28153),
(158000, 'deDE', '', 'Keeshan, Ihr dürft ruhig in meiner Gegenwart etwas ungezwungener sein.', 28153),
(157999, 'deDE', 'Sie sagte, dass sie draußen sein sollte, um die Allianz zu töten, statt sich mit irgendwelchem Unsinn herumzuschlagen. Danach wusste ich, dass ich lieber gehen und keine weiteren Handel für Geschichten abschließen sollte.', '', 28153),
(157998, 'deDE', 'Diese Areiel, nach der Ihr sucht, ist mit einem ganzen Haufen der Horde in der Nekropole! Sie wirkte ziemlich besorgt über ein Schreiben, das sie erhielt.', '', 28153),
(157997, 'deDE', 'Das wird ein Spaß! Ich sage Euch, was Ihr wissen müsst, und dann könnt Ihr mir alles über Eure Kriegserfahrungen erzählen.', '', 28153),
(157996, 'deDE', '', 'Ich lebe seit mehr als 10.000 Jahren und habe in jedem Krieg gekämpft. Ich sah den ursprünglichen Brunnen der Ewigkeit mit eigenen Augen.', 28153),
(157995, 'deDE', 'Und ich diente während der ersten drei Kriege, überlebte die Gefangenschaft bei einigen barbarischen Orcs und half, einen schwarzen Großdrachen zu töten.', '', 28153),
(157994, 'deDE', 'Eine gute Geschichte! Ich sollte einige großartige Geschichten von Torga bekommen, aber, na ja, wie Ihr seht, ist er jetzt tot. Habt Ihr noch ein paar gute auf Lager?', '', 28153),
(157993, 'deDE', 'Wir haben gerade Euer Leben gerettet. Was verlangt Ihr denn noch?', '', 28153),
(157992, 'deDE', 'Ich kann Euch alles über die Horde erzählen. Ich verlange nur eine Kleinigkeit als Gegenleistung.', '', 28153),
(157991, 'deDE', 'Ich danke Euch, Herrin.', '', 28153),
(157990, 'deDE', '', '$n, Keeshan, ich danke Euch für Eure Hilfe. Ich muss jetzt gehen und die Jagd auf Dreven fortsetzen. Möge Elune Euren Weg segnen.', 28153),
(157989, 'deDE', 'Geht! Ich pass auf die Flanke auf.', '', 28153),
(157988, 'deDE', '', '$n, Keeshan, kommt, lasst uns zur Siegesfeste zurückkehren... und um ein angemessenes Begräbnis für meine Freunde bitten.', 28153),
(157987, 'deDE', '', 'Elfen oder Menschen, wir sind alle gleich, Keeshan. Keiner von uns ist mehr wert als der andere.', 28153),
(157986, 'deDE', 'Ich werde... im Handumdrehen wie neu sein... Aber es wäre besser gewesen, wenn Eure Freunde überlebt hätten.', '', 28153),
(157985, 'deDE', '', 'Keeshan! Elune sei gepriesen, zumindest einer hat dieses Massaker überlebt.', 28153),
(157984, 'deDE', '<hust> Herrin... noch bin ich nicht... tot. Ohne seine Diener... scheint seine Macht... nicht allzu groß zu sein.', '', 28153),
(157983, 'deDE', '', 'Falia... Lyrias... Aeolyn... Keeshan... Ich schwöre, $n, dafür wird Dreven bezahlen!', 28153),
(157982, 'deDE', 'Ahhh!', '', 28153),
(157981, 'deDE', 'Ich werde mich Euch niemals fügen, Shandris Mondfeder! Seht nur, wie schwächlich Eure Verbündeten sind!', '', 28153),
(157980, 'deDE', 'Wir verschwind\'n besser. Lasst die Geister ihr\'n Weg zu Bwonsamdi allein find\'n!', '', 28153),
(157979, 'deDE', 'Die Bluttrolle komm\' bald wieder, soviel is\' ma\' sicher. Aber jetz\' wiss\'n die, dass die auch Zuhause nich\' sicher sin\'. Den nächst\'n Angriff überleg\'n die sich zweima\'.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'deDE', '', 'Shandris, geht weiter... Lasst mich zurück...', 28153),
(157977, 'deDE', 'Ich schleich schon ma\' voraus un\' sicher uns \'nen Sammelpunkt. Trefft mich vorm Dorf, wenn Ihr fertig seid!', '', 28153),
(157976, 'deDE', 'Lasst Euch mit mir auf den Tod ein, Nachtelf!', '', 28153),
(157975, 'deDE', 'Ich werde Euch zeigen, was dieser alberne Mensch draufhat!', '', 28153),
(157974, 'deDE', '', 'Senkt den Schild! Greift jetzt an! Wir werden Burg Stromgarde einnehmen!', 28153),
(157973, 'deDE', '', 'Alle Kanonen: FEUER!', 28153),
(157972, 'deDE', '', 'Ja?', 28153),
(157971, 'deDE', 'Sie werden uns doch sicherlich zurückgehen lassen, um einige unserer Wertsachen zu bergen. Wenn sich der Rauch erst verzogen hat, meine ich.', 'Sie werden uns doch sicherlich zurückgehen lassen, um einige unserer Wertsachen zu bergen. Wenn sich der Rauch erst verzogen hat, meine ich.', 28153),
(157970, 'deDE', 'Alles, was wir hatten, war im Baum der Ewigen!', 'Alles, was wir hatten, war im Baum der Ewigen!', 28153),
(157969, 'deDE', 'Ihr werdet Euch noch wünschen, in Darnassus verbrannt zu sein!', '', 28153),
(157968, 'deDE', 'Shandris Mondfeder wagt einen Angriff? Wie verwegen!', '', 28153),
(157967, 'deDE', 'Vielleicht sollte ich an diesem albernen Menschen ein Exempel statuieren!', '', 28153),
(157966, 'deDE', '', 'Das Töten endet heute, Dreven.', 28153),
(157965, 'deDE', 'Wie viele von Euch muss ich noch töten, bevor Ihr lernt, uns aus dem Weg zu gehen?', '', 28153),
(157964, 'deDE', 'Die Allianz. Ich wusste doch, dass Ihr zu dumm seid, um aus unserem letzten Aufeinandertreffen etwas zu lernen.', '', 28153),
(157963, 'deDE', 'Sieht so aus, als ob es Zeit für mich ist, die schlechten Kampfspinnen rauszunehmen und ein paar gute Kampfspinnen reinzuschicken.', '', 28153),
(157962, 'deDE', 'Ein Kerl, drei Spinnen, insgesamt 26 Beine... Ihr hattet keine Chance.', '', 28153),
(157961, 'deDE', 'Wenn einer fällt, nimmt ein anderer seinen Platz ein.', '', 28153),
(157960, 'deDE', 'Ganz ruhig. Werdet Ihr uns helfen?', 'Ganz ruhig. Werdet Ihr uns helfen?', 28153),
(157959, 'deDE', '<Flicka mustert Euch vorsichtig.>\n\nFlicka?', '', 28153),
(157958, 'deDE', 'Genauso ist es! Wir sind ganz schlimme Finger! Party!', '', 28153),
(157957, 'deDE', 'Ich bin bereit, Dreven und seine Anhänger zu töten.', 'Ich bin bereit, Dreven und seine Anhänger zu töten.', 28153),
(157956, 'deDE', 'Tag auch, Dietmar Steensen, Befallsbekämpfung. Immer schön, sich mit einem gleichgesinnten Arachnoidenbegeisterten einen Kampf zu liefern.', '', 28153),
(157955, 'deDE', 'Sieht so aus, als ob wir der Köder für eine Gruppe hungriger, blutsaugender Elfen sind. Seid Ihr für was auch immer als Nächstes geschieht bereit?', '', 28153),
(157954, 'deDE', '', 'Ich werde die anderen alarmieren. Keeshan wird sich bei den Tunneln mit Euch treffen.', 28153),
(157953, 'deDE', '', 'Gut gemacht. Von hier an sollten wir damit fertigwerden.', 28153),
(157952, 'deDE', '', 'Hordetruppen haben die Linien durchbrochen! Sie versuchen, eine Basis aufzubauen! Schlagt sie mit Eurem Feendrachen zurück!', 28153),
(157951, 'deDE', 'Ihr mögt durch dieses Dickicht in der Nähe gehen und denken, dass Spinnen die frische Luft und die leichte Brise nicht mögen, aber in dieser Hinsicht sind Spinnen genau wie Ihr und ich. Außerdem sind die Spinnennetze ein todsicheres Zeichen für die Anwesenheit von Arachnoiden.', '', 28153),
(157950, 'deDE', '', 'Ich treffe Euch außerhalb der Ruinen von Zo\'bal. Gebt auf Euch acht.', 28153),
(157949, 'deDE', 'Ah, die Freuden der Jagd. Genießt sie, so wie ich.', '', 28153),
(157948, 'deDE', '', 'Rast für die Erschöpften, Nahrung für die Hungrigen.', 28153),
(157947, 'deDE', 'Immer, Prinzessin.', '', 28153),
(157946, 'deDE', '', 'Ich verstehe. Ich werd nach Zuldazar zurückkehr\'n. Haltet mich über die Operationen der Horde in Nazmir auf dem Laufend\'n. Und seid vorsichtig, Rokhan.', 28153),
(157945, 'deDE', 'Sylvanas will ihnen \'ne Chance geb\'n. Die hab\'n kein Zuhause mehr. Wenn sie mit uns arbeit\'n könn\', dann haben sie \'n Zuhause in der Horde. Wenn nich\', sind sie weg.', '', 28153),
(157944, 'deDE', 'Dieser Schrecken der Lüfte bringt gnadenlos jedes Schiff zur Stecke, dass wir gegen Kul Tiras entsenden. Beendet diese Hetzjagd.', '', 28153),
(157943, 'deDE', '', 'Ich trau diesem Dreven nicht, Rokhan. Es ist nicht klug, ausgerechnet die San\'layn in diesen Konflikt mit hineinzuzieh\'n.', 28153),
(157942, 'deDE', '...Ich werde tun, was Ihr sagt. Vorläufig. Wir werden diesen Tunnel säubern und eine Nachricht schicken, wenn Eure Streitkräfte ausrücken können.', '', 28153),
(157941, 'deDE', 'Weil\'s zur Vereinbarung mit Sylvanas gehört, dass die Hierarchie der Autorität in der Horde respektiert wird, un\', Bruda, ich hab den höheren Rang von uns beid\'n.', '', 28153),
(157940, 'deDE', 'Ihr wollt, dass wir unsere Fähigkeiten einsetzen... um Steine zu bewegen? Und wieso sollte ich Euch folgen, Troll?', '', 28153),
(157939, 'deDE', 'Da is\' \'n eingestürzter Tunnel, der Nazmir un\' Vol\'dun verbindet. Nehmt Eure Anhänger un\' benutzt Eure Kräfte, um das Geröll wegzuräum\'n. Dann greif\'n wir die Hauptstreitmacht der Allianz an.', '', 28153),
(157938, 'deDE', '', 'Südlich von hier gibt\'s \'nen eingestürzten Tunnel, der Nazmir und Vol\'dun verbindet. Säubert ihn und die Horde kann in der Hauptbasis der Allianz in Vol\'dun mit Leichtigkeit zuschlag\'n.', 28153),
(157937, 'deDE', 'Das wird Sylvanas nich\' gefall\'n. Wir müss\'n uns beeil\'n mit unsrem Plan, die Allianz aufzuhalt\'n, Prinz Dreven.', '', 28153),
(157936, 'deDE', 'Nennt es eine meiner besonderen Fähigkeiten. Die Allianz hat die Streitkräfte der Horde in der Nekropole gestört und dabei Areiel getötet.', '', 28153),
(157935, 'deDE', '', 'Prinzessin Talanji für Euch, Prinz Dreven. Und woher wisst Ihr das?', 28153),
(157934, 'deDE', 'Hauptmann Areiel kommt nicht, weil sie getötet wurde, Talanji.', '', 28153),
(157933, 'deDE', '', 'Und doch ist sie nich\' hier. Ist sie zu beschäftigt, um \'nen einfachen Lagebericht abzugeb\'n?', 28153),
(157932, 'deDE', 'Areiel hat Streitkräfte der Allianz un\' der Bluttrolle getötet un\' uns dabei geholfen, \'ne Basis in der Nekropole zu erricht\'n.', '', 28153),
(157931, 'deDE', '', 'Rokhan, verzeiht meine Verspätung. Erzählt mir von Eurer Lage hier, war Hauptmann Areiel nützlich?', 28153),
(157930, 'deDE', 'Prinzessin, ich dank Euch, dass Ihr von Zandalar hergekomm\'n seid. Wir arbeit\'n hart, um die Bluttrolle un\' die Eindringlinge von der Allianz zurückzuhalt\'n.', '', 28153),
(157929, 'deDE', '', 'Willkommen, $n! Dieser Außenposten steht unter Eurem Kommando.', 28153),
(157927, 'deDE', 'Ich stehe zu Diensten.', '', 28153),
(157926, 'deDE', '(Nehmt das Fläschchen der Unsichtbarkeit an Euch.)', '(Nehmt das Fläschchen der Unsichtbarkeit an Euch.)', 28153),
(157925, 'deDE', '', 'Bleibt versteckt. Nur einer von uns sollte hineingehen. Ich bleibe hier und sorge dafür, dass niemand herausfindet, was wir tun.\n\nIch habe ein Fläschchen der Unsichtbarkeit. Das könnt Ihr benutzen, um Euch hineinzuschleichen. Damit solltet Ihr vollkommen unsichtbar sein... für kurze Zeit.\n\nTrinkt vom Fläschchen und schleicht Euch dann in die Ruinen. Findet heraus, was die Horde plant, und dann nichts wie raus.', 28153),
(157924, 'deDE', 'Ich fürchte, dass auch unsere kleinen Siege das Unvermeidliche nur hinauszögern.', '', 28153),
(157923, 'deDE', 'Wir halten die Horde in Schach, aber ihre Aufmerksamkeit wurde auf einen Azeritausbruch an der Küste gelenkt. Wir müssen sie aufhalten.', '', 28153),
(157920, 'deDE', 'Kommt doch näher, Herzchen. Wunja is\' blind, aber nich\' taub! Kehehe! Seid Ihr für \'nen Trank zu Wunja gekommen?', 'Kommt doch näher, Herzchen. Wunja is\' blind, aber nich\' taub! Kehehe! Seid Ihr für \'nen Trank zu Wunja gekommen?', 28153),
(157919, 'deDE', '', 'Dem großen G wird das gar nicht passen...', 28153),
(157918, 'deDE', '', 'Ich lass Euch in die Luft gehen. Kostet den Sprengstoff!', 28153),
(157917, 'deDE', 'Meine Leute sind bereit, $p. Für die Allianz.', '', 28153),
(157916, 'deDE', '', 'Dann arbeiten wir wohl zusammen, $p. Wir treffen uns am Lager der Archäologischen Akademie.', 28153),
(157915, 'deDE', 'Robolöt, los geht\'s.', '', 28153),
(157914, 'deDE', 'Ich habe in allen drei Kriegen gekämpft. Ich dachte, ich hätte schon das Schlimmste gesehen, das Azeroth zu bieten hat.\n\nIch habe mich geirrt.', '', 28153),
(157913, 'deDE', '', 'Ich habe etwas, das hilfreich sein könnte.', 28153),
(157912, 'deDE', '', 'Und nun zu Euch. Erstattet Hauptmann Sommermond Bericht und verstärkt die Grenze!', 28153),
(157911, 'deDE', '', 'Hippogryphenbogenschützen, Ihr kommt mit mir! Wir werden uns in Lor\'danel sammeln und als mobile Eingreiftruppe Wacht halten!', 28153),
(157910, 'deDE', '', 'Schildwachen, erstellt eine Schlachtlinie an den Wildschnellen! Alarmiert unsere Verbündeten am Hain der Uralten!', 28153),
(157909, 'deDE', '', 'Jägerinnen, Ihr müsst die Südgrenze der Dunkelküste verstärken! Nehmt die Glevenschleudern mit!', 28153),
(157908, 'deDE', '', 'Wir müssen eingreifen! Schildwachen, ausrichten!', 28153),
(157907, 'deDE', 'Hauptmann, die Horde hat die Wildschnellen erreicht! Wir können sie nicht mehr lange abwehren!', 'Hauptmann, die Horde hat die Wildschnellen erreicht! Wir können sie nicht mehr lange abwehren!', 28153),
(157906, 'deDE', 'Ein Alpaka! Hurra!', '', 28153),
(157905, 'deDE', 'Seid Ihr sicher?', 'Seid Ihr sicher?', 28153),
(157904, 'deDE', '', 'Wie Ihr befehlt.', 28153),
(157903, 'deDE', '<Greift einfach an.>', '<Greift einfach an.>', 28153),
(157902, 'deDE', 'Wie wäre es mit etwas Gold?', 'Wie wäre es mit etwas Gold?', 28153),
(157900, 'deDE', 'Sylvanas wird es auf mich abgesehen haben und ich gebe ihr, was sie will. Unsere Flotte wurde informiert. So Elune will, kehren sie bald heim.', '', 28153),
(157899, 'deDE', '$n, ich bitte Euch, für die Verteidigung von Darnassus zu sorgen.', '', 28153),
(157898, 'deDE', 'Delaryn, geht zu unseren Außenposten! Bringt jeden Soldaten her, den Ihr finden könnt!', '', 28153),
(157897, 'deDE', '', 'Und Ihr, Shan\'do?', 28153),
(157896, 'deDE', 'Die Bansheekönigin will den Weltenbaum einnehmen.', '', 28153),
(157895, 'deDE', '', 'Malfurion! Hordetruppen sammeln sich am Außenposten von Zoram\'gar.', 28153),
(157894, 'deDE', 'Ihr dürft passieren, $n. Die Irrwische werden Euch nichts tun.', '', 28153),
(157893, 'deDE', '', 'Selbst in Euren letzten Momenten könnt Ihr das wahre Potenzial der Menschen nicht erkennen.', 28153),
(157892, 'deDE', '', 'Und Ihr haltet noch immer an Euren veralteten Ansichten über die Menschen fest. Ich hätte Euch schon vor langer Zeit töten sollen.', 28153),
(157891, 'deDE', '', 'Ich bin dazu bestimmt, ewig zu leben! Ich werde nicht hier sterben!', 28153),
(157890, 'deDE', '', 'Es ist eine Schande, Euch an der Seite eines Menschen kämpfen zu sehen, Shandris! Es sind so kurzlebige, unbedeutende Kreaturen.', 28153),
(157889, 'deDE', '', 'Shandris, wir haben uns bestimmt... zwei- oder dreitausend Jahre nicht gesehen! Und dass wir uns so wiedersehen... und wie Ihr ausgerechnet einem Menschen helft.', 28153),
(157888, 'deDE', '', 'Dunkelheit... Sylvanas... Ist es das, was Ihr saht... Wovor Ihr uns retten wolltet?', 28153),
(157887, 'deDE', '', 'Und ich dachte, das würde eine simple Erkundungsmission. Ich werde das genießen!', 28153),
(157886, 'deDE', '', 'Es ist vorbei. Findet ihre Pläne und kehrt nach Rotfelds Wacht zurück, wenn Ihr hier fertig seid.', 28153),
(157885, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Xibala in Zuldazar!', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Xibala in Zuldazar!', 28153),
(157884, 'deDE', 'Gut gemacht. Ohne diese Kreatur können sich unsere Truppen ungehindert durch das Gebiet bewegen.', '', 28153),
(157883, 'deDE', 'Rum ist für die wahren Eisenfluträuber. Hände weg!', 'Rum ist für die wahren Eisenfluträuber. Hände weg!', 28153),
(157882, 'deDE', 'Es ist auch ohne die Einmischung magischer Bestien schon schwer genug, in einem Sumpf Versorgungslinien aufzubauen. Erlegt das Ding und macht uns den Weg frei!', '', 28153),
(157881, 'deDE', '', 'Gut gemacht. Diese Kreatur wird uns nich\' mehr belästig\'n.', 28153),
(157880, 'deDE', '', 'Dunkles Mojo nährt diese Kreatur. Gebt Bwonsamdi die Seel\'n zurück!', 28153),
(157879, 'deDE', '', 'Ein weiterer Sieg.', 28153),
(157878, 'deDE', 'Ihr werdet schon seh\'n, dass alle, die Bwonsamdi stör\'n, das bereu\'n! Wie wär\'s mit \'nem kleinen Ausflug?', '', 28153),
(157877, 'deDE', '', 'Meine Späher berichten, dass hier an der Dunkelküste plötzlich explosionsartig Azerit aufgetreten ist. Helft unseren Goblinverbündeten, das Azerit sicherzustellen.', 28153),
(157876, 'deDE', 'Kommt Bwonsamdi nicht zu nahe!', 'Kommt Bwonsamdi nicht zu nahe!', 28153),
(157875, 'deDE', 'Was das mit den Ohren soll?$B$BÄh, schon mal was von Mode gehört?', '', 28153),
(157874, 'deDE', 'Diebischer Ho-zen. Wehe, ich finde heraus, dass Rum fehlt.', 'Diebischer Ho-zen. Wehe, ich finde heraus, dass Rum fehlt.', 28153),
(157873, 'deDE', 'Nichtsnutzige Bilgeratten, hört auf, den Rum zu saufen!', 'Nichtsnutzige Bilgeratten, hört auf, den Rum zu saufen!', 28153),
(157872, 'deDE', 'Unsere Hauptaufgabe ist es, die Allianz zwischen der Horde und den Zandalari zunichte zu machen. Dafür müssen wir Stützpunkte im Feindterritorium errichten.', '', 28153),
(157871, 'deDE', 'Zeigen wir der Horde, dass die 7. Legion es ernst meint, $n.', '', 28153),
(157870, 'deDE', '', 'Soldaten... nein! Stürzt Euch nicht in die...', 28153),
(157869, 'deDE', 'Okay, ist das Ding an? Hallo? Gut.', '', 28153),
(157868, 'deDE', 'Ha, Ihr habt sie ganz schön ins Bockshorn gejagt! Sie werden einige Zeit brauchen, um sich wieder zu sammeln. Gute Arbeit.', '', 28153),
(157867, 'deDE', 'Uns ist es gelungen, eine weitere Belagerungsmaschine der Horde einzunehmen. Jetzt drehen wir den Spieß um!', '', 28153),
(157866, 'deDE', 'Nein! Nein! Unmöglich. Das wird dem Boss nich\' gefall\'n. Das letzte Mal hat der alte Bwonsamdi \'nen Geist verlor\'n, da... oh, nich\' gut.', '', 28153),
(157865, 'deDE', 'Ey, Vol\'jin! Kommt ma raus aus der Urne. Wartet... wartet, wartet... nein! Wo is\' der Geist?! Wo is\' Vol\'jin?', '', 28153),
(157864, 'deDE', 'Kusch, Champion. Hier gibt\'s nix mehr zu klären.', '', 28153),
(157863, 'deDE', 'Zum Glück scheint es den Arbeitern nichts auszumachen, dass wir herumschnüffeln. Den Firmenschlägern leider schon.\n\nHabt Ihr, was wir brauchen?', '', 28153),
(157862, 'deDE', 'Heute haben wir hier viel erreicht. Wir können uns draußen neu formieren.', 'Heute haben wir hier viel erreicht. Wir können uns draußen neu formieren.', 28153),
(157861, 'deDE', '', 'Jakra\'zet muss aufgehalt\'n werd\'n.', 28153),
(157860, 'deDE', 'Was tut der König für unsere eigene Heimat?', 'Was tut der König für unsere eigene Heimat?', 28153),
(157859, 'deDE', 'Die Mittel Sturmwinds sind schon übermäßig beansprucht. Sie werden nicht reichen, um uns alle am Leben zu halten.', 'Die Mittel Sturmwinds sind schon übermäßig beansprucht. Sie werden nicht reichen, um uns alle am Leben zu halten.', 28153),
(157858, 'deDE', 'Oh nein, nein, nein, kleiner Champion, das nehmt Ihr schön wieder mit.', '', 28153),
(157857, 'deDE', 'Gut gemacht. Ein hungriges Maul weniger, um das wir uns sorgen müssen.', '', 28153),
(157856, 'deDE', 'Anstatt um Ruinen zu kämpfen, sollte die Allianz unser Heimatland zurückerobern!', 'Anstatt um Ruinen zu kämpfen, sollte die Allianz unser Heimatland zurückerobern!', 28153),
(157855, 'deDE', 'Das ist schon die zweite Heimat, die wir verlieren.', 'Das ist schon die zweite Heimat, die wir verlieren.', 28153),
(157854, 'deDE', 'Wo sollen wir jetzt hin?!', 'Wo sollen wir jetzt hin?!', 28153),
(157853, 'deDE', 'Gut gemacht. Ihr Ableb\'n macht den Weg frei für zukünftige Generation\'.', '', 28153),
(157852, 'deDE', 'Es geht hier um mehr, Generalin. Wir müssen auf diese neuen Informationen reagieren.', '', 28153),
(157851, 'deDE', '', 'Wir dürfen dieses Monster nicht entkommen lassen, Wyrmbann.', 28153),
(157850, 'deDE', 'Keine Dunkelspeere! Dummtrolle sin\' an so \'nem schönen Trollort nich\' erlaubt!', '', 28153),
(157849, 'deDE', 'Hordenabschaum hat hier keinen Platz! Ihr werdet Euch den Sandwütern stell\'n müss\'n!', 'Hordenabschaum hat hier keinen Platz! Ihr werdet Euch den Sandwütern stell\'n müss\'n!', 28153),
(157848, 'deDE', '', 'Ich danke Euch, Alleria. Eure Hilfe ist uns höchst willkommen.', 28153),
(157847, 'deDE', 'Eine weise Strategie. Ich bin einverstanden.', '', 28153),
(157846, 'deDE', '', 'Wir werden ihn jagen und Euch seinen Kopf bringen. Shandris kann sich weiter darauf konzentrieren, diesen Blutprinzen aufzuspüren.', 28153),
(157845, 'deDE', '', 'Meine Leerenelfen können den Kampf um die Eliminierung von Gallywix anführen.', 28153),
(157844, 'deDE', '', 'Alleria öffnet hinter sich ein Leerenportal.', 28153),
(157843, 'deDE', '', 'Wir können es uns nicht leisten, auch nur eines dieser Ziele entwischen zu lassen... und das müssen wir auch nicht.', 28153),
(157842, 'deDE', '', 'Vergebt mir die Unterbrechung, aber ich glaube, Ihr habt beide recht.', 28153),
(157841, 'deDE', '', 'Ich habe gesehen, wozu Dreven fähig ist, Wyrmbann. Was ist, wenn es mehr wie ihn gibt?', 28153),
(157840, 'deDE', 'Taktisch gesehen ist er ihre Schwachstelle. Das ist eine seltene Gelegenheit. Wir müssen sofort zuschlagen.', '', 28153),
(157839, 'deDE', 'Gallywix finanziert die Kriegskampagne der Horde und weiß mehr über Azerit als jeder andere ihrer Anführer.', '', 28153),
(157838, 'deDE', '', 'Diesen gefräßigen Goblin können wir jederzeit erledigen! Wenn Dreven uns entkommt, finden wir ihn vielleicht nie wieder.', 28153),
(157837, 'deDE', 'Wir werden uns noch um Blutprinz Dreven kümmern, Generalin. Aber jetzt haben wir die seltene Gelegenheit, der Streitmacht der Horde einen empfindlichen Schlag zu versetzen. Alles andere muss warten.', '', 28153),
(157836, 'deDE', 'Eine geflügelte Bestie verfüttert meine Männer an ihre Küken. Lasst sie als nächste Mahlzeit etwas Stahl kosten!', '', 28153),
(157835, 'deDE', 'Ihr werdet diesen verräterisch\'n Hordenliebhaber nich\' an diesen heiligen Ort bring\'n!', '', 28153),
(157834, 'deDE', '', 'Unsere Verbündeten erwarten Euren Befehl.', 28153),
(157833, 'deDE', 'Die große Pa\'ku hat entschied\'n, dass Ji\'araks Zeit bei uns abgelauf\'n is\'. Sammelt Eure Streitkräfte un\' erlegt das Tier!', '', 28153),
(157832, 'deDE', 'Willkommen, $n. Es gibt Arbeit für uns.', '', 28153),
(157831, 'deDE', 'Ist das... Blut? Wirklich? Ihr wollt mir sagen, dass dieses Ding buchstäblich von einem Schild aus Blut geschützt wird?\n\nGut... Jetzt hab ich definitiv alles gesehen.', '', 28153),
(157830, 'deDE', '', 'Der Zirkel ist unser! Auf Eure Posten!', 28153),
(157829, 'deDE', 'Der nächste Krieg. Und der nächste danach.', '', 28153),
(157828, 'deDE', 'Das Licht wird uns alle überdauern. Aber wenn dieser Krieg zu Ende ist, was bleibt Euch dann noch, Shaw?', '', 28153),
(157827, 'deDE', 'Euer Glaube an das Licht? Oder an Turalyon?', '', 28153),
(157826, 'deDE', 'Ganz im Gegenteil. Zu sehen, wie das Licht Turalyon getröstet hat, ihn verändert hat, das hat meine Entschlossenheit noch verstärkt. Ich wusste, mein Vertrauen war begründet.', '', 28153),
(157825, 'deDE', 'Und als Ihr rausgefunden habt, dass Turalyon lebt, kamen Euch da Zweifel an Eure Hingabe? An Euren Entscheidungen?', '', 28153),
(157824, 'deDE', 'Als er mit der Allianzexpedition auf der Scherbenwelt verschwand, hat das Licht meine Augen geöffnet. Mir wurde klar, dass ich beides sein kann: Soldat und Paladin. Ich schwor, sein Opfer zu ehren.', '', 28153),
(157823, 'deDE', 'Aber als ich diesen ersten Paladinen zusah, inspirierte mich vor allem einer von ihnen... Turalyon. Sein Glaube stützte ihn, beflügelte seinen Ehrgeiz und machte ihn zu einem großen Anführer.', '', 28153),
(157822, 'deDE', 'Drukan macht ein Nickerchen.', '', 28153),
(157821, 'deDE', 'Ich diente als Ritter, als die Silberne Hand gegründet wurde. Krieger und Priester, das war für mich unvereinbar miteinander, daher konzentrierte ich mich auf meine Kampfausbildung.', '', 28153),
(157820, 'deDE', 'Sagt mir, Wyrmbann, wie kommt ein Paladin dazu, eine Gruppe von Elitesoldaten anzuführen? Solltet Ihr nicht besser Tempel weihen oder etwas in der Art?', '', 28153),
(157819, 'deDE', 'Oh, natürlich.', '', 28153),
(157818, 'deDE', 'Freundliche Worte. Aber wenn es darum geht, meine Ehre zu wahren oder meinen Auftrag zu erfüllen, würde ich immer den Auftrag wählen. Zum Wohle der Allianz natürlich.', '', 28153),
(157817, 'deDE', 'Ich habe lange bezweifelt, dass wir in der Allianz Spione und Assassinen brauchen. Aber dass Ihr unserem König gegenüber Ehre und Loyalität bewiesen habt, steht außer Frage.', '', 28153),
(157816, 'deDE', 'Der SI:7 arbeitet eher im Hintergrund. Ich bleibe lieber in den Schatten, da, wo ich nicht so... sichtbar bin.', '', 28153),
(157815, 'deDE', 'Ich habe aufgehört zu zählen. Ich gehe, wohin die Allianz mich schickt... das Licht mich ruft. Aber Ihr habt ja selbst manche Schlacht erlebt, nicht wahr?', '', 28153),
(157814, 'deDE', 'Der wievielte Feldzug gegen die Horde ist das für Euch, Wyrmbann?', '', 28153),
(157813, 'deDE', 'Passt auf, wohin Ihr das Ding schwingt, $n.', '', 28153),
(157812, 'deDE', 'Dachte mir, Ihr solltet es wissen.', '', 28153),
(157811, 'deDE', 'Die Werkstatt ist hiermit eröffnet! Wenn Ihr etwas braucht, werden wir es mit Schweiß und Schmiere für Euch hinbekommen!', '', 28153),
(157810, 'deDE', 'Der Schaden an der Reißzahnfeste wird zehnfach zurückgezahlt werden.', '', 28153),
(157809, 'deDE', 'Ich fürchte nicht den Tod, der Tod fürchtet mich...', '', 28153),
(157808, 'deDE', 'Der Kriegshäuptling wird das nicht ungesühnt lassen.', '', 28153),
(157807, 'deDE', 'Der Tod ist noch zu gut für Euch!', '', 28153),
(157806, 'deDE', 'Ich werde mich an Eurer Leiche laben!', '', 28153),
(157805, 'deDE', 'Ich haue Euch in Stücke!', '', 28153),
(157804, 'deDE', '', 'Gute Arbeit, aber irgendwas sagt mir, dass das nicht das letzte Mal war.', 28153),
(157803, 'deDE', '', 'Die Wachkuppe wird wieder von Piraten überfallen! Lernen die es nie? Helft den Marinesoldaten, sie abzuwehren!', 28153),
(157802, 'deDE', 'Ich danke Euch! Jetzt muss ich zurück zu meiner Familie.', 'Ich danke Euch! Jetzt muss ich zurück zu meiner Familie.', 28153),
(157801, 'deDE', 'Hahaha! Habt Ihr ihre dummen Gesichter gesehen?! Das war unbezahlbar! Das kriegen die tagelang nicht sauber! Hahaha!', '', 28153),
(157800, 'deDE', 'Die Horde ist barbarisch!', 'Die Horde ist barbarisch!', 28153),
(157799, 'deDE', 'Solch eine schleichende Verderbnis muss einfach ausgemerzt werden... bevor sie die Horde infiziert.', '', 28153),
(157798, 'deDE', 'Hervorragend. Wir können nicht untätig zusehen, wie der Abgrund unser Land verdirbt!', '', 28153),
(157797, 'deDE', 'Wenn wir ein bisschen einen im Tee hatten, haben Venrik und ich \'ne Spritztour auf ein paar Reitpapageien gemacht. Versucht\'s mal und verpasst diesen Rabauken \'ne kalte Dusche!', '', 28153),
(157796, 'deDE', 'Abgeschliffen...', '', 28153),
(157795, 'deDE', 'Ich habe mich ver... kalkuliert.', '', 28153),
(157794, 'deDE', 'Diese Monstrosität ist förmlich die Verkörperung von Wahnsinn und Verderbnis. Vernichtet sie umgehend!', '', 28153),
(157793, 'deDE', 'Ich hoffe nur, dass meine Familie rechtzeitig entkommen ist.', 'Ich hoffe nur, dass meine Familie rechtzeitig entkommen ist.', 28153),
(157792, 'deDE', 'Der Rauch war so dicht. Wir hätten uns darin sicher verirrt, wenn Königin Graumähne nicht gewesen hätte.', 'Der Rauch war so dicht. Wir hätten uns darin sicher verirrt, wenn Königin Graumähne nicht gewesen hätte.', 28153),
(157791, 'deDE', 'Wir müssen diese Kreatur zurück in den Abgrund schicken. Vernichtet sie!', '', 28153),
(157790, 'deDE', 'Wir haben es gerade so rausgeschafft.', 'Wir haben es gerade so rausgeschafft.', 28153),
(157789, 'deDE', 'Warum tun sie so etwas nur?', 'Warum tun sie so etwas nur?', 28153),
(157788, 'deDE', 'Hört Ihr wohl auf, mir Sand ins Getriebe zu streuen!', '', 28153),
(157787, 'deDE', 'Meine Mine!', '', 28153),
(157786, 'deDE', 'Ich werde Euch in Stücke bohren!', '', 28153),
(157785, 'deDE', '', 'Das hätte ein riesiger Verlust für die Prachtmeerwache sein können. Dank Euch war es nur ein kleiner Rückschlag.', 28153),
(157784, 'deDE', '', 'Eins unserer Versorgungsschiffe ist im südlichen Flutkanal auf Grund gelaufen. Der Crew geht es gut, aber sie mussten wertvolle Vorräte zurücklassen.', 28153),
(157783, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Kriegstreiber Yenajz beginnt, |cFFF00000|Hspell:274932|h[Endloser Abgrund]|h|r zu wirken!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Kriegstreiber Yenajz beginnt, |cFFF00000|Hspell:274932|h[Endloser Abgrund]|h|r zu wirken!', 28153),
(157782, 'deDE', 'Fusel?! Ach, Mann! Ich hatte auf Gold gehofft... das ich für Fusel AUSGEBEN kann!', '', 28153),
(157781, 'deDE', 'In Freihafen wird getuschelt, dass einer von den Piraten irgendwo im Wasser vor den Docks \'ne prallgefüllte Schatzkiste versteckt hat. Das schreit nach \'ner Schatzsuche!', '', 28153),
(157780, 'deDE', 'Gute Arbeit. Das sollte den Azeritwaffenschmuggel nach Boralus behindern, bis wir die Aschenwindmeuterei niedergeschlagen haben.', '', 28153),
(157779, 'deDE', 'Die Handelskompanie Aschenwind hat noch nicht wie befohlen ihre Waffenproduktion eingestellt. Zertrümmert diese Gießerei, aber verletzt keine Zivilisten.', '', 28153),
(157778, 'deDE', 'Hey, keine Sorge. Wir finden was Neues für sie. Wichtig ist jetzt nur, dass sie runter von der Straße und raus aus der Schusslinie sind.', '', 28153),
(157777, 'deDE', 'Die Handelskompanie Aschenwind lockt Waisen mit warmen Mahlzeiten an und lässt sie dann bis zur Erschöpfung schuften. Holt die Kleinen da raus!', '', 28153),
(157776, 'deDE', 'Ich hab gehört, Azurethos krallt sich \'nen ganzen Riesenkraken einfach so aus den Wellen. Das war echt \'ne große Nummer. Ihr seid wohl grade zur Legende geworden.', '', 28153),
(157775, 'deDE', 'Es gibt so manche Lieder vom sagenhaften Azurethos. Mit einem Windstoß bringt er \'ne ganze Galeone zum Kentern. Holt ihn vom Himmel und bald singen sie über Euch.', '', 28153),
(157774, 'deDE', '', 'Meldet Euch bei Hochfürst Saurfang! Zeigt ihnen, welchen Preis sie dafür bezahlen! Für die Horde!', 28153),
(157773, 'deDE', 'Immer wenn ich meine Augen schließe... sehe ich die Flammen.', 'Immer wenn ich meine Augen schließe... sehe ich die Flammen.', 28153),
(157772, 'deDE', 'Ich hoffe, unsere Freunde sind in Sicherheit.', 'Ich hoffe, unsere Freunde sind in Sicherheit.', 28153),
(157771, 'deDE', 'Wir dürfen Kalimdor nicht verlieren.', 'Wir dürfen Kalimdor nicht verlieren.', 28153),
(157770, 'deDE', 'Ich kann nicht fassen, dass der Weltenbaum... weg ist...', 'Ich kann nicht fassen, dass der Weltenbaum... weg ist...', 28153),
(157769, 'deDE', 'Diese Hordenbastarde haben unser Zuhause zerstört!', 'Diese Hordenbastarde haben unser Zuhause zerstört!', 28153),
(157768, 'deDE', 'Was wollt Ihr? Oh, Ihr seht aus, als wärt Ihr auch ein Ingenieur...', '', 28153),
(157767, 'deDE', 'Ich möchte etwas anderes fragen.', 'Ich möchte etwas anderes fragen.', 28153),
(157766, 'deDE', 'Dieser verrückte Exzentriker? Ich glaube, er ist ein Cousin zweiten Grades. Traurig, aber alles, woran er denken kann, sind Bomben und noch größere Bomben. Das eigentliche Genie ist damit beschäftigt, die ultimative Energiequelle zu erfinden. Damit könnte man Maschinen zum Zerfetzen, Schreddern, Bohren oder Hochjagen vieler Dinge antreiben. Und das so lange wie möglich.', '', 28153),
(157765, 'deDE', 'Guten Tag, Doktor. Ich würde Euch gerne einen Eurer Reaktoren abkaufen. Es soll sich auch für Euch lohnen.', 'Guten Tag, Doktor. Ich würde Euch gerne einen Eurer Reaktoren abkaufen. Es soll sich auch für Euch lohnen.', 28153),
(157764, 'deDE', 'Seid Ihr das? Dr. Bumm?', 'Seid Ihr das? Dr. Bumm?', 28153),
(157763, 'deDE', 'Ah ja, ich sehe schon. Ihr seid also tatsächlich ein großes Ingenieurstalent! Nicht mal annähernd so talentiert wie ich, aber das sind auch nur wenige.', '', 28153),
(157762, 'deDE', '', 'Keine Ahnung, wer das ist, aber eins ist sicher: Wir müssen sie töten!', 28153),
(157761, 'deDE', 'Doktor, die Ingenieurskunst, die in diesem Stück steckt, ist ganz außergewöhnlich!', 'Doktor, die Ingenieurskunst, die in diesem Stück steckt, ist ganz außergewöhnlich!', 28153),
(157760, 'deDE', '', 'Alle zurück zum Schwarzen Amboss. Wir brauchen einen Schadensbericht!', 28153),
(157759, 'deDE', 'He, ich bin hier am Arbeiten! Kommt wieder, wenn Ihr was vom Ingenieurswesen versteht.', '', 28153),
(157758, 'deDE', '', 'Mit denen habt Ihr kurzen Prozess gemacht! Wir öffnen jetzt die Tür. Passt auf Euch auf, ich höre jede Menge Feinde auf der anderen Seite!', 28153),
(157757, 'deDE', 'Die letzten fünf Jahre habe ich damit verbracht, das fortschrittlichste und tödlichste Roboterteam, das es jemals gab, noch weiter zu verbessern und zu perfektionieren. Wollt Ihr sehen, wie Eure langweiligen, normalen Haustiere sich gegen die Haustiere schlagen, die vom brillantesten, unterschätztesten Reparaturtechniker des Universums hergestellt wurden?', '', 28153),
(157756, 'deDE', 'Fehlfunktion!? Das sollte so eigentlich nicht passieren!', '', 28153),
(157755, 'deDE', 'Mein geniales Gehirn, das noch genialere Maschinen austüftelt, ist einfach unschlagbar.', '', 28153),
(157754, 'deDE', '', 'Gute Arbeit! Das Konstrukt ist nur noch Schutt und Drustvar ist wieder sicher.', 28153),
(157753, 'deDE', '', 'In den nahegelegenen Bergen ist ein riesiges Steinkonstrukt erwacht! Wir müssen es ausschalten, bevor es über die Bewohner von Drustvar herfällt!', 28153),
(157752, 'deDE', 'Unfassbar! Das nächste Mal baue ich größere Roboter.', '', 28153),
(157751, 'deDE', 'Kein Haustier kann es mit meinem Team aufnehmen! Ich bin unaufhaltsam!', '', 28153),
(157750, 'deDE', 'Macht Euch bereit, meinem unschlagbaren Team aus extrem modifizierten und maßangefertigten Robotern gegenüberzutreten!', '', 28153),
(157749, 'deDE', 'Ich bin bereit zum Aufbruch, Krag\'wa.', 'Ich bin bereit zum Aufbruch, Krag\'wa.', 28153),
(157748, 'deDE', 'Sogar jetzt schlachten die Bluttrolle meine Kinder noch ab.$b$bIch werde Euch helfen, an ihren Anführer heranzukommen, aber ich muss schnell zurück in den Sumpf, um meine Kinder zu schützen.', '', 28153),
(157747, 'deDE', 'Krag\'wa, die Anführerin der Bluttrolle ist in das große Gebäude da hinten geflohen. Bitte helft uns.', 'Krag\'wa, die Anführerin der Bluttrolle ist in das große Gebäude da hinten geflohen. Bitte helft uns.', 28153),
(157746, 'deDE', 'Ah... ähem. Nicht jetzt, Venrik. Wir haben was zu erledigen.', '', 28153),
(157745, 'deDE', '', 'Ich bin hier, um zu helfen. Auf in den Kampf!', 28153),
(157744, 'deDE', '', 'Ich kämpfe für mein Volk.', 28153),
(157743, 'deDE', '', 'Ein leichter Gegner, tötet ihn schnell!', 28153),
(157742, 'deDE', 'Ihr wisst schon, die mit dem \"Haar wie Ebenholz\". Hahaha!', '', 28153),
(157741, 'deDE', '', 'Zum Andenken an Darnassus!', 28153),
(157740, 'deDE', '', 'Ich werde diesen Ort mit Freuden weit hinter mir lassen.', 28153),
(157739, 'deDE', '', 'Wir verschwinden besser, bevor noch mehr von diesen... Dingern... kommen.', 28153),
(157738, 'deDE', '', 'Ja... Ich werde es überleben.', 28153),
(157737, 'deDE', 'Sagt mal, Finn, was ist denn aus der Frau geworden, von der Ihr dauernd faselt?', '', 28153),
(157736, 'deDE', '', 'Mutter! Geht es dir gut?', 28153),
(157735, 'deDE', '', 'Werdet Ihr den Hammer zurückholen? Er ist sehr mächtig und könnte unser Untergang sein, wenn die Goblins herausfinden, wie man ihn benutzt.', 28153),
(157734, 'deDE', '', '$n, ich habe eine weitere Aufgabe für Euch. Diese Wilden waren von der Venture Co. Das bedeutet, dass sie jetzt in Kezan sind und wahrscheinlich gerade Eisenfeind in die schmierigen Griffel von Mogul Ratztunk legen.', 28153),
(157733, 'deDE', '', 'Ambossthan, Schwarzamboss, findet heraus, wie der Schwarze Amboss repariert werden kann.', 28153),
(157732, 'deDE', '', 'Verflucht! Sie haben Eisenfeind gestohlen UND den Schwarzen Amboss zerschlagen!', 28153),
(157731, 'deDE', '', 'Und Kul Tiras wird niemals weichen.', 28153),
(157730, 'deDE', 'Die Drust werden niemals... nachgeben...', '', 28153),
(157729, 'deDE', 'Heiliger Bimbam!', '', 28153),
(157728, 'deDE', 'Macht die Augen auf, Ihr beide! Seht Euch den Schwarzen Amboss an!', '', 28153),
(157727, 'deDE', '', 'Da schmelz mir doch einer den Kern! Das muss der große Mech gewesen sein, der mich gerammt hat!', 28153),
(157726, 'deDE', 'Irgendein Schläger hat mir aufgelauert und Eisenfeind gestohlen!', '', 28153),
(157725, 'deDE', '', 'Mir geht es gut. Ihr seht allerdings weniger gut aus...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'deDE', 'Königin-Regentin! Alles in Ordnung, Mädel?!', '', 28153),
(157723, 'deDE', '', 'In Ordnung, Jungs und Mädels, bringen wir es zu Ende!', 28153),
(157722, 'deDE', '', 'Mein Volk hat Euresgleichen schon einmal besiegt, Monster. Und wir werden es wieder tun!', 28153),
(157721, 'deDE', 'Thros wird Euch alle verschlingen! Und die Rache wird mein sein!', '', 28153),
(157720, 'deDE', '', 'Gerade, als es für uns wieder etwas besser aussah.', 28153),
(157719, 'deDE', '', '<Moira murmelt vor sich hin.>', 28153),
(157718, 'deDE', '', 'Thaelin, geht nach oben, durch die Halle des Handwerks! Sie könnten auf dem Weg zum Schwarzen Gewölbe sein.', 28153),
(157717, 'deDE', '', 'Champion, begebt Euch zur Dunkeleisenstraße und sichert sie!', 28153),
(157716, 'deDE', '', 'Ambossthan, sammelt Eure Zauberer für einen Gegenangriff!', 28153),
(157715, 'deDE', '', 'Diese rückgratlosen grünen Dreckskerle glauben, uns in unserem Zuhause angreifen zu können?!', 28153),
(157714, 'deDE', 'Goblins! In den Tunneln!', '', 28153),
(157713, 'deDE', '', 'Zu den Waffen, $n!', 28153),
(157712, 'deDE', '', 'Ihr habt Euch mit der falschen Familie angelegt!', 28153),
(157711, 'deDE', '', 'Mutter!', 28153),
(157710, 'deDE', '', 'Mutter, pass auf!', 28153),
(157709, 'deDE', '', 'Hui, das ist mal ein Riesending!', 28153),
(157708, 'deDE', 'Keiner von Euch wird entkommen!', '', 28153),
(157707, 'deDE', '', 'Komm, Tochter. Wir finden einen Weg hier heraus.', 28153),
(157706, 'deDE', '', 'Hier kommen noch mehr von denen!', 28153),
(157705, 'deDE', '', 'Elementare im Anmarsch!', 28153),
(157704, 'deDE', '', 'Wir haben herausgefunden, dass die Anwendung starker Magie auf Azerit unerwartete Folgen haben kann.', 28153),
(157703, 'deDE', '', 'Jaina? Bist du es wirklich?', 28153),
(157702, 'deDE', 'Was der griesgrämige Bücherwurm damit sagen will, ist, dass Ihr uns Deckung geben sollt, wenn uns die Elemente angreifen.', '', 28153),
(157701, 'deDE', 'Ihr seid... zu spät...', '', 28153),
(157700, 'deDE', '$C, beim Formen des Azerits werden wir bestimmt Zeuge einer spontanen Azergenese. Meint Ihr, Ihr kommt damit zurecht?', '', 28153),
(157699, 'deDE', 'Würdet Ihr mir etwas mehr Azerit auf den Amboss packen, $n?', '', 28153),
(157698, 'deDE', 'Ihr kommt als Nächstes dran!', '', 28153),
(157697, 'deDE', 'Dreiste Narren! Sie ist bereits gebrochen und für Euch unerreichbar!', '', 28153),
(157696, 'deDE', 'Zu Befehl, Königin-Regentin.', '', 28153),
(157695, 'deDE', '', 'Thaelin, Thurgaden, legt Euch ins Zeug.', 28153),
(157694, 'deDE', '', 'Genug! Zeigt uns Eure wahre Gestalt, Monster!', 28153),
(157693, 'deDE', '', 'Sie machen Fortschritte. Anduin fragt fast täglich nach dem Stand der Dinge, also dachte ich, wir zeigen Euch, was wir herausgefunden haben.', 28153),
(157692, 'deDE', '', 'Nach der Entdeckung von Azerit in unseren Tiefen hab ich nur unsere Besten an seiner Veredelung arbeiten lassen.', 28153),
(157691, 'deDE', '', 'Danke, dass Ihr gekommen seid, $n.', 28153),
(157690, 'deDE', '', 'Vater... bitte...', 28153),
(157689, 'deDE', '', 'Wir treffen uns bei der Statue auf dem Hügel.', 28153),
(157688, 'deDE', '', 'Großer Krag\'wa, wir brauch\'n Eure Hilfe.', 28153),
(157687, 'deDE', 'Genau wie im Dritten Krieg.', '', 28153),
(157686, 'deDE', 'Für die Bravo-Kompanie!', '', 28153),
(157685, 'deDE', 'Genau wie in Draenor!', '', 28153),
(157684, 'deDE', 'Das erinnert mich an den Zweiten Krieg.', '', 28153),
(157683, 'deDE', 'Mpf mpf mpf mpf.', 'Mpf mpf mpf mpf.', 28153),
(157682, 'deDE', 'Gehen wir den Plan durch, wie wir Hauptmann Areiel töten.', 'Gehen wir den Plan durch, wie wir Hauptmann Areiel töten.', 28153),
(157681, 'deDE', 'Generalin.', '', 28153),
(157680, 'deDE', '', 'Wir rücken jetzt aus. $n wird die Spitze übernehmen. Der Rest von uns sorgt für Unterstützung und späht die Lage aus. Keeshan, das gilt auch für Euch.', 28153),
(157679, 'deDE', '', 'Wenn wir die Tortollaner retten, sollten wir an Informationen über die Bewegungen der Horde kommen, was uns wiederum zu Hauptmann Areiel führen sollte.', 28153),
(157678, 'deDE', 'Herrin. In Nazmir sind Tortollaner, und unsere Informationen deuten darauf hin, dass sie über die Bewegungen der Horde Bescheid wissen. Einige von ihnen wurden von Bluttrollen gefangen genommen.', '', 28153),
(157677, 'deDE', 'So macht Fischen Spaß!', 'So macht Fischen Spaß!', 28153),
(157676, 'deDE', 'Der ist platt wie \'ne Flunder!', 'Der ist platt wie \'ne Flunder!', 28153),
(157675, 'deDE', '', 'Wir brauchen Informationen und Verbündete in Nazmir, um das zu erreichen. Glücklicherweise bietet sich uns eine Gelegenheit. Keeshan?', 28153),
(157674, 'deDE', '', 'Hauptmann Areiels Tod wird die Operationen der Horde in Nazmir lahmlegen und Sylvanas\' Dunkle Waldläufer schwächen.', 28153),
(157673, 'deDE', 'Diese Trolle haben meinen Kindern schon viel zu lange Leid zugefügt! Jetzt bin ich es, der auf die Jagd geht.', '', 28153),
(157672, 'deDE', 'Ich dachte immer, zur Totenschwemme ginge es in die andere Richtung?', '', 28153),
(157671, 'deDE', '', 'Seit Nante weg ist, ist es hier schön ruhig.', 28153),
(157670, 'deDE', 'Wir dürfen das nicht zulassen. Sammelt Eure Verbündeten, Champion. Stromgarde gehört der Allianz!', '', 28153),
(157669, 'deDE', 'Doch die Horde zieht ihre Kräfte zusammen, um uns die Festung wieder zu entreißen. Wenn ihnen das gelingt, erhalten unsere Feinde eine wichtige strategische Position innerhalb der Östlichen Königreiche.', '', 28153),
(157668, 'deDE', 'Stromgarde war zu Zeiten der Allianz von Lordaeron ein wichtiger Stützpunkt. Und wir wollen, dass es wieder so wird.', '', 28153),
(157667, 'deDE', 'Stellt eine Expedition zusammen und sammelt das Azerit ein... bevor die Horde es tut.', '', 28153),
(157666, 'deDE', 'Shaws Späher haben Azeritvorkommen auf im Meer verstreuten Inseln entdeckt. Die Allianz braucht diese Ressourcen, Champion.', '', 28153),
(157665, 'deDE', 'Die Agenten, die Ihr rekrutiert, sollen die Operationen der Horde stören... und uns den Sieg sichern.', '', 28153),
(157664, 'deDE', 'Stellt mit Mathias Shaw eine Spezialeinheit zusammen. Niemand ist für diese Aufgabe besser geeignet als Sturmwinds Meisterspion.', '', 28153),
(157663, 'deDE', 'Champion, um im Krieg den Sieg zu erringen, bedarf es starker Waffen. Doch manchmal sind... subtilere Methoden angebracht.', '', 28153),
(157662, 'deDE', 'Ich bin bereit, Krag\'wa zu beschwören.', 'Ich bin bereit, Krag\'wa zu beschwören.', 28153),
(157661, 'deDE', '', 'Zelling spricht mit seiner Familie. Bleibt zurück. Wir werden sehen, ob ich eingreifen muss.', 28153),
(157660, 'deDE', '', 'Deckt durch Tarnung und Täuschung Lücken in der feindlichen Verteidigung auf... und nutzt sie aus!', 28153),
(157659, 'deDE', '', 'Arbeitet mit Garona der Halborcin zusammen und stellt eine Einheit aus den gerissensten und verschlagensten Agenten der Horde auf! Diese schickt Ihr dann auf Geheimmissionen in Kul Tiras und Zandalar!', 28153),
(157658, 'deDE', '', 'Um Euren Erfolg zu gewährleisten, sende ich Euch einen Agenten mit... ganz besonderen Fähigkeiten. Das sollte sich auf dieser Mission als hilfreich erweisen.', 28153),
(157657, 'deDE', '', 'Wir müssen uns sputen. Nutzt den Schutz der Dunkelheit, um bei der Suche nicht gesehen zu werden. Dort wimmelt es von Allianzpatrouillen.', 28153),
(157656, 'deDE', '', 'Nathanos, Eure Unterhaltung mit Bruder Zelling trägt bereits Früchte. Er hat uns die Position des gesuchten Schiffswracks offenbart.', 28153),
(157655, 'deDE', '', 'Jetzt schickt der kleine König seine Handlanger, um die Burg zurückzuerobern. Wir dürfen das nicht zulassen.', 28153),
(157654, 'deDE', '', 'Stromgarde war ein Machtzentrum der Allianz im Herzen der Östlichen Königreiche... bevor die Festung aufgegeben wurde.', 28153),
(157653, 'deDE', '', 'Wir müssen dies zum Vorteil nutzen. Erforscht diese Inseln und nehmt sie ein, bevor es die Allianz tut!', 28153),
(157652, 'deDE', '', 'Die mit uns verbündeten Goblins erweisen sich weiterhin als nützlich. Sie haben auf den Inseln in den Ozeanen Azeritablagerungen entdeckt.', 28153),
(157651, 'deDE', '', 'Im Krieg richtet eine wohlplatzierte Klinge manchmal mehr Schaden an als Tausend Schwerter auf dem Schlachtfeld.', 28153),
(157650, 'deDE', '', 'Dieser verdammte Mildenhall dreht völlig durch! Die Metbrauerei ist wohl von seinen Experimenten überrannt worden. Seht nach dem Rechten, bevor das außer Kontrolle gerät.', 28153),
(157649, 'deDE', '', 'Ich danke Euch und Eurer Horde dafür, dass Ihr meine Mannschaft befreit habt.\n\nSolange ich das Kommando habe, werden die Nebelfockfreibeuter als freie Leute über alle Meere segeln!', 28153),
(157648, 'deDE', '', 'Er war das letzte Opfer... Wir ham versagt.', 28153),
(157647, 'deDE', 'Nein... Das kann nicht sein!', '', 28153),
(157646, 'deDE', 'Aber das werdet Ihr...', '', 28153),
(157645, 'deDE', 'Leid? Ihr habt noch überhaupt kein wahres Leid geseh\'n. Noch nich\'...', '', 28153),
(157644, 'deDE', 'Taelia, besucht mich in Sturmwind, wenn Ihr Zeit habt. Ich habe viele Geschichten über Euren Vater zu erzählen.', '', 28153),
(157643, 'deDE', '', 'Die Briefe rissen eines Tages ab. Ich... ich habe so viele Fragen.', 28153),
(157642, 'deDE', '', 'Gewährt ihm \'n schnell\'n Tod. Wir ham heut\' schon genug Leid mitangeseh\'n.', 28153),
(157641, 'deDE', '', '\"Mein Augenstern.\"', 28153),
(157640, 'deDE', 'Ich erinnere mich... er schrieb Euch Briefe. Und er nannte Euch immer...', '', 28153),
(157639, 'deDE', 'Hochlord Bolvar war ein großer Mann. Ein wahrer Held für die Allianz – und für mich.', '', 28153),
(157638, 'deDE', '', 'Kanntet Ihr meinen Vater?', 28153),
(157637, 'deDE', '<Jakra\'zet stöhnt.>', '', 28153),
(157636, 'deDE', 'Taelia... bitte, erhebt Euch. Die Ehre ist meinerseits.', '', 28153),
(157635, 'deDE', '', 'Bolvars Tochter. Nach dem Dritten Krieg zogen wir sie unter unserem Schutz groß.', 28153),
(157634, 'deDE', 'Fordragon?!', '', 28153),
(157633, 'deDE', '', 'Taelia Fordragon.', 28153),
(157632, 'deDE', '', 'Eine Ehre, Eure Bekanntschaft zu machen, König Wrynn. Ich bin Taelia.', 28153),
(157631, 'deDE', '', 'Auch sie trug entscheidend zur Rettung unseres Königreichs bei... und meines Lebens.', 28153),
(157630, 'deDE', '', 'König Wrynn, es gibt jemanden, den Ihr treffen solltet.', 28153),
(157629, 'deDE', 'Es ist mir eine große Ehre, Kul Tiras erneut in der Allianz willkommen zu heißen. Möge das Licht uns zum Sieg führen.', '', 28153),
(157628, 'deDE', '', 'Ich danke Euch... Euch allen. Ich gelobe, Euer Vertrauen nicht zu enttäuschen.', 28153),
(157627, 'deDE', '', 'Die Wahl liegt bei Euch.', 28153),
(157626, 'deDE', '', 'Jetz\' is\' Schluss, General, mit \'n Lüg\'n un\' Intrig\'n un\' Morden.', 28153),
(157625, 'deDE', '', 'Samuel, nein!', 28153),
(157624, 'deDE', 'STURMSANG!', '', 28153),
(157623, 'deDE', 'Ihr habt Euer eigenes Ende hergeführt, Pike. Ich muss die Flotte unserer glorreichen Retterin überreichen... Azshara.', '', 28153),
(157622, 'deDE', 'Ich sehe nur verlorene Seelen, die um Erlösung flehen.', '', 28153),
(157621, 'deDE', 'Es ist vorbei, Sturmsang! Seht Euch um... Ihr seid umstellt!', '', 28153),
(157620, 'deDE', 'Man sieht, Ihr wisst, was Ihr tut. Gut, dass ich immer auf Euch zählen kann, wenn die Situation etwas Verwüstung erfordert.', '', 28153),
(157619, 'deDE', 'Wir haben nicht viel, das man als Waffe verwenden kann, also müssen wir kreativ sein. Findet einen Weg, großen Schaden anzurichten und verschwindet, bevor sie wissen, was sie getroffen hat.', '', 28153),
(157618, 'deDE', '', 'Wer weiß, wie viel Schaden dieses Ding an der Flotte hätte anrichten können. Dank Euch müssen wir es nie herausfinden.', 28153),
(157617, 'deDE', '', 'Ihr seid zu schwach für den Thron, Katherine.', 28153),
(157616, 'deDE', '', 'Und ich hätte fast... Priscilla... Wie konntet Ihr Euer Königreich betrügen? MICH betrügen?', 28153),
(157615, 'deDE', '', 'Dieser Golem könnte ein Schiff spalten! Wir können Lord Sturmsang keine derartig mächtige Waffe überlassen.', 28153),
(157614, 'deDE', '', 'Ihr habt die Piratenflotte angeheuert, bis an die Zähne bewaffnet und auf Eure eigenen Landsleute gehetzt.', 28153),
(157613, 'deDE', '', 'Es wird Azerit genannt... und die Allianz führt mit der Horde bereits einen Krieg darum.', 28153),
(157612, 'deDE', '', 'Euer Unternehmen hat die Waffen ENTWICKELT, die Daelins Tor zerstört haben - hiermit!', 28153),
(157611, 'deDE', '', 'Lady Priscilla Aschenwind, Ihr steht unter Arrest wegen Schwarzhandels, Verschwörung mit Piraten und Hochverrat gegen die Admiralität von Kul Tiras.', 28153),
(157610, 'deDE', 'Die See versorgt uns, doch in ihrer Tiefe lauert nichts als Verderben.', '', 28153),
(157609, 'deDE', '', 'Was wollt Ihr damit sagen, Mädchen?!', 28153),
(157608, 'deDE', '', 'Das war also von Anfang an Euer Plan. Abscheulich.', 28153),
(157607, 'deDE', '', 'Eine Lügnerin!', 28153),
(157606, 'deDE', 'Ein uraltes Unheil aus den Tiefen ist zutage getreten. Verbannt es wieder unter die Fluten.', '', 28153),
(157605, 'deDE', '', 'Lady Aschenwind war mein Fels von jenen finsteren Tagen an, als wir beide unsere Gemahle verloren. Jetzt wird sie dem Königreich ein Fels sein. Von nun an... ist sie–', 28153),
(157603, 'deDE', '', 'Aber es war nicht genug.', 28153),
(157602, 'deDE', '', 'Was für ein Kampf! Dank Euch können wir auch morgen noch auf trockenem Boden kämpfen.', 28153),
(157601, 'deDE', 'So viel Rauch habe ich das letzte Mal gesehen, als die alte Oma Fürbittshafen ihrem dämlichen Enkel Backen beigebracht hat. Ausgezeichnete Arbeit!', '', 28153),
(157600, 'deDE', '', 'Ihr erdreistet Euch?', 28153),
(157599, 'deDE', '', 'Die Naga haben eine lebende Belagerungsmaschine auf den Damm gerichtet! Zu den Waffen!', 28153),
(157598, 'deDE', 'Piraten?! Die Prachtmeers können uns nicht mal mehr vor Piraten beschützen!', '', 28153),
(157597, 'deDE', '', 'Eine Piratenflotte hat das Tor mit überwältigender Feuerkraft durchschlagen...', 28153),
(157596, 'deDE', 'Der Zorn des Sturms ist unberechenbar und gefährlich, aber kein Gegner für jemanden mit Euren Fähigkeiten.', '', 28153),
(157595, 'deDE', 'Offenbar kam hier die Magie der Gezeitenweisen zum Einsatz. Gebietet ihr Einhalt!', '', 28153),
(157594, 'deDE', 'Immer wenn ich denke, wir haben sie geschwächt, sind sie sofort doppelt so stark zurück. Wir müssen ihre Holzvorräte vernichten! Brennt sie nieder!', '', 28153),
(157593, 'deDE', '', 'Die Gerüchte sind wahr. Daelins Tor... ist gefallen.', 28153),
(157592, 'deDE', 'Das waren ein paar wirklich laute Explosionen. Habt Ihr dort noch irgendetwas außer Trümmer zurückgelassen?', '', 28153),
(157591, 'deDE', '', 'Dank Euch ist die Ernte gesichert! Wir werden versuchen, diese kleinen Racker abseits des Ackerlands anzusiedeln.', 28153),
(157590, 'deDE', '', 'Ich wusste doch, dass es den Aufwand wert ist. Wir haben Glück, dass sie da ist!', 28153),
(157589, 'deDE', '', 'Irgendwas frisst die Saat der hiesigen Bauern, bevor sie aufgeht. Lasst uns das Problem im Keim ersticken!', 28153),
(157588, 'deDE', '', 'Frau Fürbittshafen hat um einige Dinge gebeten, um die Kriegsbemühungen zu unterstützen. Mit dieser alten Dame ist nicht zu spaßen. Wir sollten sie besser nicht enttäuschen!', 28153),
(157587, 'deDE', 'Wir werden ihre Verderbnis wieder und wieder fortspülen, bis der Schrein des Sturms gereinigt ist.', '', 28153),
(157586, 'deDE', 'Diese Scheusale versuchen, unsere heiligsten Stätten zu entweihen. Das wird nicht geschehen!', '', 28153),
(157585, 'deDE', '', 'Ich weiß, Schädlingsbekämpfung ist nicht sehr glamourös, aber ich bin sicher, unsere Freunde in Mühlsteinweiler wissen die Hilfe zu schätzen.', 28153),
(157584, 'deDE', '', 'Die Bewohner von Mühlsteinweiler kämpfen mit einer ganzen Reihe von Schicksalsschlägen. Ihre Vorratslager werden von Schädlingen überrannt. Helfen wir ihnen, sie zu beseitigen.', 28153),
(157583, 'deDE', 'Eines Tages werden die beschwingten Klänge von Gezeitenweisen, die ihre ersten Zauber wirken, wieder diesen Ort füllen... aber nicht heute.', '', 28153),
(157582, 'deDE', '', 'Hoffen wir, dass das den Rest dieser garstigen Riesen zurück in die Berge treibt, wo sie hingehören!', 28153),
(157581, 'deDE', 'Die Tentakel meines früheren Meisters reichen noch immer tief ins Land. Löscht jede Spur davon aus.', '', 28153),
(157580, 'deDE', 'Danke. Die Einwohner des Tals werden Euch Eure Taten nie vergessen.', '', 28153),
(157579, 'deDE', '', 'Mühlsteinweiler wird von Ettins terrorisiert und die Bewohner sind ihnen wehrlos ausgesetzt. Wir sind ihre einzige Hoffnung!', 28153),
(157578, 'deDE', 'Wir brauchen Eure Hilfe in Brennadam, Champion. Wir haben immer noch nicht genug Streitkräfte, um ohne Unterstützung einen Gegenangriff zu starten.', '', 28153),
(157577, 'deDE', 'Sprecht mit Kapitänin Angelika, sobald Ihr bereit seid, in See zu stechen.', '', 28153),
(157576, 'deDE', '', 'Entschuldigt, ich hätte Euch nach Allergien fragen sollen, bevor ich Euch dort rausgeschickt habe. Aber Ihr seht gesund aus, also weiß ich, wen ich das nächste Mal fragen kann!', 28153),
(157575, 'deDE', 'Danke, dass Ihr Euch so rasch eingefunden habt, $n. Ihr werdet gemeinsam mit der Dritten Flotte aufbrechen.', '', 28153),
(157574, 'deDE', 'Solch niederträchtigen Frevel dürfen wir in unserer Welt nicht gedeien lassen.', '', 28153),
(157573, 'deDE', '', 'Die Bienen bei der Metbrauerei terrorisieren mal wieder die Anwohner und die Bauern wissen nicht, was sie tun sollen. Was für eine Überraschung!', 28153),
(157572, 'deDE', 'König Anduin schickt mich, Spionagemeister.', 'König Anduin schickt mich, Spionagemeister.', 28153),
(157571, 'deDE', '', 'Etwas auf dieser Farm hat die Wendigos in Raserei versetzt. Bevor diese verrückten Mildenhalls dort hingezogen sind, sind sie immer unter sich geblieben.', 28153),
(157570, 'deDE', '', 'Wir haben gehört, die Metbrauerei Mildenhall hat Probleme mit Wendigos. Könnt Ihr dort mal vorbeischauen und ihnen aushelfen?', 28153),
(157569, 'deDE', 'Die K\'thir praktizieren ungehindert ihre dunkle Magie an Bord der Abgründigen Melodie. Spült diese Infektion von Bord.', '', 28153),
(157568, 'deDE', 'Wir mögen zahlenmäßig unterlegen sein, aber dank Euch bleiben wir unerschrocken.', '', 28153),
(157567, 'deDE', 'Gefallene Gezeitenweisen haben verlorene Matrosen verhext, um das Gezeitenkreuz zu überrennen. Stoppt ihren Vorstoß!', '', 28153),
(157566, 'deDE', '', 'Diese Kreatur war wohl mal ein rechtschaffener Fungianer. Was für ein tragisches Ende für einen so edlen Krieger.', 28153),
(157565, 'deDE', '', 'Uns erreichen Berichte von einer mächtigen Präsenz in einer Höhle im Süden. Seid vorsichtig. Die Erzählungen jagen mir Schauer über den Rücken.', 28153),
(157564, 'deDE', '', 'Gute Arbeit, aber ich bin nicht sicher, dass wir ihm zum letzten Mal die Haut gerettet haben...', 28153),
(157563, 'deDE', 'Wir konnten die Horde noch nicht aus dem Pass verdrängen. Sabotiert ihre Bemühungen – egal, was es kostet. Jagd alles in die Luft, wenn es sein muss!', '', 28153),
(157562, 'deDE', '', 'Waffen aus den Gießereien von Sturmsang sollten das Volk beschützen, nicht unterdrücken.', 28153),
(157561, 'deDE', 'Eine schlichte Aufgabe in Anbetracht Eurer Taten, aber trotzdem etwas, das erledigt werden muss.', '', 28153),
(157560, 'deDE', 'Kenningers Jagdhütte ist mit Bestellungen der Admiralität im Verzug. Es gibt wohl... Komplikationen. Eine helfende Hand sollte für jemanden wie Euch keine Umstände bereiten.', '', 28153),
(157559, 'deDE', '', 'Es wäre eine Schande, wenn diese ganze Munition verkommt. Ihr wisst, was zu tun ist.', 28153),
(157558, 'deDE', 'Jetzt, wo die Miliz nicht mehr da ist, können nur noch wir ihnen Einhalt gebieten.', '', 28153),
(157557, 'deDE', 'Die Stacheleber führen schon wieder etwas im Schilde! Sucht ihren Kral auf und durchkreuzt ihre Pläne, bevor sie ihre Kräfte sammeln können!', '', 28153),
(157556, 'deDE', 'Nura, ich bin hier, um zu helfen.', 'Nura, ich bin hier, um zu helfen.', 28153),
(157555, 'deDE', '', 'Was führt Euch hierher?', 28153),
(157554, 'deDE', 'Wir treffen uns später in der Stadt und teilen das hier auf!', '', 28153),
(157553, 'deDE', 'Könnt Ihr mich zum Höhenpfad im Südlichen Brachland bringen?', 'Könnt Ihr mich zum Höhenpfad im Südlichen Brachland bringen?', 28153),
(157552, 'deDE', 'Ein Schiff ohne Segel ist wie eine Kavallerie ohne Pferde. Eigentlich... völlig nutzlos.', '', 28153),
(157551, 'deDE', 'Ein gewaltiger Sturm bedroht unsere Taklerläden. Besänftigt ihn, bevor es zu spät ist!', '', 28153),
(157550, 'deDE', 'Ihr habt Andersons Vermächtnis heute Ehre gemacht. Vielen Dank.', '', 28153),
(157549, 'deDE', 'Bruder Anderson hätte solche Verderbtheit niemals hingenommen. Erobert die Werft in seinem Namen zurück!', '', 28153),
(157548, 'deDE', '', 'Alles beginnt beim Rohmaterial. Der Rest kommt von harter Arbeit und reinen Herzen.', 28153),
(157547, 'deDE', '', 'Die Schiffsbauer von Sturmsang sind legendär, aber sie brauchen Holz für ihre Arbeit. Stellt die Ordnung wieder her!', 28153),
(157546, 'deDE', '', 'Das soll ihnen eine Lehre sein. Sturmsang steht jedem offen!', 28153),
(157545, 'deDE', '', 'Lord Sturmsangs Truppen haben noch eine Blockade errichtet! Reißt sie ein, damit diese Händler passieren können!', 28153),
(157544, 'deDE', 'Und jetzt, beeilt Euch!', '', 28153),
(157543, 'deDE', 'Sprecht mit Isabella. Sie sorgt dafür, dass Ihr unseren Treffpunkt in Unterstadt heil erreicht.', '', 28153),
(157542, 'deDE', 'Sobald wir genug Verstärkung beisammen haben, erkläre ich Euch alles.', '', 28153),
(157541, 'deDE', 'Danke, dass Ihr so schnell gekommen seid, $n. Wir haben keine Zeit zu verlieren.', '', 28153),
(157540, 'deDE', 'Wir schützen, nähren und leiten. Das ist der wahre Weg der Gezeitenweisen.', '', 28153),
(157539, 'deDE', 'Alle Gezeitenweisen schwören einen heiligen Eid, unser Volk zu beschützen. Helft uns, den Eid zu halten, und steht diesen ermatteten Seelen bei!', '', 28153),
(157538, 'deDE', 'Unsere Feinde sind erbarmungslos, aber dank Euch leben wir, um weiterzukämpfen.', '', 28153),
(157537, 'deDE', 'Es scheint, das Ritual ist gescheitert, bevor Schaden angerichtet wurde. Wir können nicht erlauben, dass die üble Magie der Naga weiter die See verdirbt.', '', 28153),
(157536, 'deDE', 'Nach ihrer kürzlichen Niederlage versuchen sich Azsharas Anhänger an einem neuen Ritual. Schickt sie in die Tiefen, nach denen sie so sehnlichst schmachten.', '', 28153),
(157535, 'deDE', '', 'Die Naga scheinen mit jedem Tag aggressiver zu werden. Ich bin besorgt darüber, was das für uns bedeutet.', 28153),
(157534, 'deDE', '', 'Die Sturmwacht erholt sich immer noch von diesem Nagaangriff. Haltet ihnen den Rücken frei, bis sie wieder Herr der Lage sind!', 28153),
(157533, 'deDE', 'Diese Ressourcen wären unseren Streitkräften von großem Nutzen. Nehmt sie im Dienst unserer Sache ein!', '', 28153),
(157532, 'deDE', 'Mögen die Gezeiten Euch segnen. Dieses Tal wird nicht fallen, solange wir standhaft bleiben!', '', 28153),
(157531, 'deDE', 'Es gibt für alles ein erstes Mal. Und dafür hoffentlich kein zweites.', '', 28153),
(157530, 'deDE', 'Äh, ich bin nicht sicher, was ich davon halten soll, aber in der Stadt geschehen sehr seltsame Dinge. Vielleicht könnt Ihr das ja regeln.', '', 28153),
(157529, 'deDE', '', 'Wenn du deine Gefühle beiseite schiebst, bleibt nichts als leere Dunkelheit.', 28153),
(157528, 'deDE', '', 'Jaina, Liebes... Du kannst nicht alle Entscheidungen allein mit Vernunft treffen.', 28153),
(157527, 'deDE', '', 'Er ist nicht real, Jaina! Nichts von all dem ist real!', 28153),
(157526, 'deDE', '', 'Ich... Ich wusste nicht, dass...', 28153),
(157525, 'deDE', 'Es war dumm von mir zu glauben, Ihr könntet uns anführen!', '', 28153),
(157524, 'deDE', 'Durch Eure Vorurteile wurden die Kirin Tor beschmutzt!', '', 28153),
(157523, 'deDE', '', 'Ich wünschte, dein Vater hätte diese Lektion gelernt.', 28153),
(157522, 'deDE', '', 'Ein Ende des Blutvergießens zu suchen, ist ein nobles Unterfangen, Jaina.', 28153),
(157521, 'deDE', 'Lord Sturmsangs Armeen drohen, dieses Gebiet zurückzuerobern. Stellt sicher, dass es ihnen nicht in die Hände fällt!', '', 28153),
(157520, 'deDE', '', 'Lass sie in Frieden!', 28153),
(157519, 'deDE', 'Hir\'eek is\' der Loa der Nacht. Mehr müsst Ihr nich\' wiss\'n.', 'Hir\'eek is\' der Loa der Nacht. Mehr müsst Ihr nich\' wiss\'n.', 28153),
(157518, 'deDE', '', 'Es war alles meine Schuld...', 28153),
(157517, 'deDE', 'Ihr aber... habt mir Einhalt geboten. Wie viele Soldaten der Allianz starben an jenem Tag? Und in den Schlachten danach?', '', 28153),
(157516, 'deDE', 'Ich hätte sie alle vernichten können! Sylvanas... Thrall... Was wäre unsere Welt für ein schöner Ort ohne die verdorbene Horde.', '', 28153),
(157515, 'deDE', '', 'Nein. Das muss eine weitere dieser Kreaturen sein, die Jaina quälen. Beeilung!', 28153),
(157514, 'deDE', '', 'Diese Stimme... Daelin?!', 28153),
(157513, 'deDE', '', 'Noch eine Illusion? Jaina muss hier in der Nähe sein.', 28153),
(157512, 'deDE', '', 'Wir werden sie finden... und von diesem grausigen Ort wegbringen.', 28153),
(157511, 'deDE', '', 'Meine Tochter ist hier irgendwo. Versteckt sich. Und leidet.', 28153),
(157510, 'deDE', 'Ihr schlagt Euch wacker! Die Wasser werden noch in Jahren von Euren Taten hier erzählen.', '', 28153),
(157509, 'deDE', '', 'Wir müssen weitersuchen.', 28153),
(157508, 'deDE', '', 'Sie ist fort. Das Kind war nur ein Spiegelbild von Jaina... ein Echo ihres Kummers.', 28153),
(157507, 'deDE', '', 'Aber selbst die Stärksten unter uns können nicht alle retten.', 28153),
(157506, 'deDE', '', 'Jaina... du warst... du bist... der ganze Stolz von Kul Tiras: seine Macht und sein Zorn...', 28153),
(157505, 'deDE', '', 'Nein! Hör nicht auf sie, Jaina!', 28153),
(157504, 'deDE', '', 'Ich... war nicht stark genug...', 28153),
(157503, 'deDE', '', 'Ihr hättet ihn aufhalten können! Ihr hättet uns retten können!', 28153),
(157502, 'deDE', 'Melde mich zum Dienst, Hochfürst.', 'Melde mich zum Dienst, Hochfürst.', 28153),
(157501, 'deDE', 'Die Sturmwacht benötigt einmal mehr Eure Hilfe. Mögen Euch die Gezeiten zum Sieg führen.', '', 28153),
(157500, 'deDE', 'Ihr habt uns zum Sterben zurückgelassen!', '', 28153),
(157499, 'deDE', '', 'Geht voran, $p.', 28153),
(157498, 'deDE', '', 'Ich habe sie immer gefunden... und das schaffe ich auch heute.', 28153),
(157497, 'deDE', '', 'Als Kind hat sich Jaina immer versteckt, wenn sie Angst hatte oder durcheinander war.', 28153),
(157496, 'deDE', '', 'Warte!', 28153),
(157495, 'deDE', '', 'Nein! Du kannst mir nicht helfen! Niemand kann das!', 28153),
(157494, 'deDE', '', 'Ist schon gut, Liebes...', 28153),
(157493, 'deDE', '', 'Jaina ist da vorne. Wir müssen uns beeilen!', 28153),
(157492, 'deDE', 'Thros... wird Euch verschlingen...', '', 28153),
(157491, 'deDE', '', 'Nicht, wenn ich noch ein Wörtchen mitzureden habe!', 28153),
(157490, 'deDE', 'Prachtmeers Tochter gehört uns, Eindringling!', '', 28153),
(157489, 'deDE', '', '$n, wir müssen ihr folgen!', 28153),
(157488, 'deDE', '', 'Jaina, warte!', 28153),
(157487, 'deDE', '', 'Nein! Bleib weg!', 28153),
(157486, 'deDE', '', 'Jaina?!', 28153),
(157485, 'deDE', '', 'Es ist... alles meine Schuld...', 28153),
(157484, 'deDE', '', 'Die Verseuchten Lande... dieser Ort wird seinem Namen wirklich gerecht...', 28153),
(157483, 'deDE', 'Mögen die Gezeiten Euch segnen. Unser Tal ist wieder sicher.', '', 28153),
(157482, 'deDE', 'Bei den Tiefen des Abgrunds... Diese Entartung darf unser Volk nicht länger bedrohen!', '', 28153),
(157481, 'deDE', 'Lasst das denjenigen eine Lehre sein, die die Geschenke der Gezeitenmutter einsetzen.', '', 28153),
(157480, 'deDE', 'Solch unverhohlene Geringschätzung für die Macht der See muss bestraft werden.', '', 28153),
(157479, 'deDE', 'Torga ist machtvoll, aber geschwächt. Wir Tortollaner müssen die Erinnerung wachhalten.', '', 28153),
(157478, 'deDE', 'Lasst uns hier einen Moment anhalten, $p.', '', 28153),
(157477, 'deDE', 'Gral is\' \'n weiser Loa. Er schaut weit in die Zukunft. Das tiefe Meer is\' sein Reich und der dunkelste Ozean sein Refugium.', 'Gral is\' \'n weiser Loa. Er schaut weit in die Zukunft. Das tiefe Meer is\' sein Reich und der dunkelste Ozean sein Refugium.', 28153),
(157476, 'deDE', 'Möge die Flut die Verräter verschmähen wie sie ihr Volk.', '', 28153),
(157475, 'deDE', 'Ein paar Eber weniger, die uns stören können. Gute Arbeit.', '', 28153),
(157474, 'deDE', 'Die Stacheleber hecken auf dem Hof außerhalb ihres Krals etwas aus. Schaut doch vorbei und seht, ob Ihr ihrem Ränkeschmieden nicht ein Ende setzen könnt.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'deDE', 'Eine weitere schändliche Seele ist Lord Sturmsangs Ruf gefolgt. Sie dürfen unsere Arbeit nicht ungeschehen machen!', '', 28153),
(157472, 'deDE', 'Ruht nun, verlorene Seele. Euer Leiden ist vorbei.', '', 28153),
(157471, 'deDE', 'Was für Schrecken haben meine Brüder nur heraufbeschworen... Setzt der Qual dieses Wesens ein Ende.', '', 28153),
(157470, 'deDE', 'Ich geh dann ma\'...', 'Ich geh dann ma\'...', 28153),
(157469, 'deDE', 'Ja... mein Lord.', 'Ja... mein Lord.', 28153),
(157468, 'deDE', 'Wasch isch?', 'Wasch isch?', 28153),
(157467, 'deDE', 'Ich geh dann mal!', 'Ich geh dann mal!', 28153),
(157466, 'deDE', 'Mehr Arbeit?', 'Mehr Arbeit?', 28153),
(157465, 'deDE', '', 'Ich kümmere mich darum, Boss!', 28153),
(157464, 'deDE', 'Ich sehe allerdings eine weitere kleine Ausgrabungsstätte westlich von hier. Kelsey?', '', 28153),
(157463, 'deDE', 'Steht zusammen. Wir sind nicht so weit gekommen, um zu scheitern!', '', 28153),
(157462, 'deDE', 'Die größten Ausgrabungsstätten der Archäologischen Akademie liegen weiter im Süden. Wie ich es mir gedacht habe.', '', 28153),
(157461, 'deDE', 'Die Horde hat die Gebäude in Brand gesetzt! Löscht das Feuer, bevor das ganze Tal in Flammen aufgeht!', '', 28153),
(157460, 'deDE', 'Gute Arbeit! Die Flammen sind gelöscht und unsere Häuser stehen noch. Ich danke Euch.', '', 28153),
(157459, 'deDE', 'Ich sorge dafür, dass die Sethrak nicht mal mehr ihre eigene Beute haben, wenn sie hier verschwinden.', 'Ich sorge dafür, dass die Sethrak nicht mal mehr ihre eigene Beute haben, wenn sie hier verschwinden.', 28153),
(157458, 'deDE', 'Ich kann unsere Seeleute nicht zurückholen, aber wenigstens wissen wir, dass sie dort draußen sind. Ihr Schicksal liegt jetzt in den Händen der Prachtmeers.', '', 28153),
(157457, 'deDE', 'Jani is\' der Loa der weggeworf\'nen Dinge und der Leute, die von andren verstoß\'n oder missachtet werd\'n. Er kümmert sich um Waisen wie mich un\' andere, die sich ganz unten wiederfind\'n.', '', 28153),
(157456, 'deDE', 'Hier ist meine Magie am stärksten. Wenn es noch Hoffnung gibt, die Flotte zu finden, dann jetzt.', '', 28153),
(157455, 'deDE', 'Errn... Geht weg... <hick!> Ich bin beschäftigt.', '', 28153),
(157454, 'deDE', 'Wir sin\' Anhänger von Torcali, dem wandernden Berg un\' wandelnden Bollwerk. Wenn der Loa will, kommt niemand an unsern Schild\'n vorbei.', '', 28153),
(157453, 'deDE', '', 'Eine Bedrohung weniger, die das Tal verunsichert. Gut gemacht!', 28153),
(157452, 'deDE', '', 'Wow... ich bin sprachlos. Was für ein unglaublicher Kampf!', 28153),
(157451, 'deDE', 'Wartet hier. Ich glaube, ich sehe da etwas.', '', 28153),
(157450, 'deDE', 'Ich dachte wirklich nicht, dass das klappt, aber das Gold wird sehr vielen Menschen helfen, wieder Fuß zu fassen!', '', 28153),
(157449, 'deDE', 'Ja... Ich kann die Schiffe spüren... unsere Flotte! Die dunklen Nebel um sie verflüchtigen sich!', '', 28153),
(157448, 'deDE', 'Ich bin hier, um Eure Probleme zu lösen, Krog.', 'Ich bin hier, um Eure Probleme zu lösen, Krog.', 28153),
(157447, 'deDE', '', 'Die Sturmwacht berichtet von einer aggressiven Bestie in der Nähe. Eine leichte Übung für Euch, oder?', 28153),
(157446, 'deDE', '', 'In den Hügeln lauert irgendwas gefährliches. Findet es, bevor jemand verletzt wird!', 28153),
(157445, 'deDE', 'Die Schatzjäger bei der Totenschwemme wollen Gold für den Wiederaufbau von Brennadam spenden. Der Haken ist, wir müssen das Gold selbst abholen!', '', 28153),
(157444, 'deDE', 'Arthur...', '', 28153),
(157443, 'deDE', 'Doras, ich brauche einen Windreiterflug hinunter nach Brackenwall.', 'Doras, ich brauche einen Windreiterflug hinunter nach Brackenwall.', 28153),
(157442, 'deDE', '', 'Gute Arbeit, Champion. Ihr habt Ai\'twen beschützt. Damit habt Ihr den Tortollanern geholf\'n... und der Loa is\' vermutlich auch dankbar.', 28153),
(157441, 'deDE', 'Hey, ich habe Steine umgeworfen! Ein paar sehr wütende Steine.', '', 28153),
(157440, 'deDE', 'Ihr hattet den Befehl, Menhire umzuwerfen.', '', 28153),
(157439, 'deDE', 'Ach, nun kommt schon! Alles ist am Ende gut ausgegangen. Der Fremdling und ich haben das große Felsenmonster zur Strecke gebracht und sind noch am Leben! Das ist ein Sieg.', '', 28153),
(157438, 'deDE', 'Arthur! Was habe ich Euch zum Thema \"Hals über Kopf in Dinge hineinstürzen\" gesagt?', '', 28153),
(157437, 'deDE', '', 'Die Tortollaner verehr\'n die große Schildkröte Ai\'twen als mächtige Verbündete. Wir müss\'n sie füttern und beschütz\'n, damit sie uns wieder hilft.', 28153),
(157436, 'deDE', 'Verlasst diesen Ort!', '', 28153),
(157435, 'deDE', 'Mögen Euch die Winde gewogen sein! Ihr seid uns allen ein Vorbild.', '', 28153),
(157434, 'deDE', 'Wir ziehen also weiter Richtung Süden. Wir bleiben in Kontakt, Guzbert.', '', 28153),
(157433, 'deDE', 'Guzzy, Ihr schafft das!', '', 28153),
(157432, 'deDE', '', 'Auf sie, Guzbert.', 28153),
(157431, 'deDE', '... mit einem RIESENHAUFEN BOMBEN!', '', 28153),
(157430, 'deDE', 'Eine kleine Ausgrabungsstätte, wie? Klingt nach einem Job für einen Gnom...', '', 28153),
(157429, 'deDE', 'Etwa einen halben Kilometer östlich von hier gibt es eine kleine Ausgrabungsstätte der Archäologischen Akademie.', '', 28153),
(157428, 'deDE', '$n, hinter Euch! Helft mir, diese Plagegeister aus dem Weg zu räumen.', '', 28153),
(157427, 'deDE', 'Die uralte Schildkröte Ai\'twen ist ein schutzbedürftiges Mysterium des Meeres. Helft den Tortollanern, Ai\'twen zu beschützen und zu füttern.', '', 28153),
(157426, 'deDE', 'Wir werden Lord Sturmsang zur Rechenschaft ziehen... und wenn wir dabei sterben.', '', 28153),
(157425, 'deDE', 'Die Einwohner des Sturmsangtals sollen sich sicher fühlen können. Zeigt denen, die diese Sicherheit bedrohen, keine Gnade.', '', 28153),
(157424, 'deDE', 'Wir müssen jetzt handeln, wenn wir Azshara die Flotte entreißen wollen.', '', 28153),
(157423, 'deDE', 'Hier ist es nicht sicher. Kommt, es gibt einen nahen Wachposten mit Blick auf den Schrein.', '', 28153),
(157422, 'deDE', 'Aber er wird nicht vergessen werden. Nicht, solange wir standhalten.', '', 28153),
(157421, 'deDE', 'Die Stimme ist jetzt ein Echo Eurer eigenen. Ihr fühlt, wie sie die Antwort sucht, weil Ihr sie selbst sucht.\n\n\"Zu welchem Zweck?\"', '', 28153),
(157420, 'deDE', 'Ihr krümmt Euch vor Schmerzen, als die Stimme in Euch schreit.\n\n\"Wo hat es begonnen?\"', '', 28153),
(157419, 'deDE', 'Ihr habt meinen Dank. Die Bauern sollten bald auf ihre Felder zurückkehren können.', '', 28153),
(157418, 'deDE', 'Von den Höfen im Umland erreichen uns beunruhigende Berichte. Bitte helft uns, im Tal die Ordnung wiederherzustellen!', '', 28153),
(157417, 'deDE', 'Die Stimme wird stärker und bestimmter.\n\n\"Mehr! Mehr! Mehr!\"', '', 28153),
(157416, 'deDE', 'Die uralte Stimme ist nunmehr nur ein Echo, das aus den Tiefen Eures Geistes hallt.\n\n\"Was sucht Ihr?\"', '', 28153),
(157415, 'deDE', 'Ihr versteht Eure Sache! Von Euch kann ich noch ein paar Kniffe lernen.', '', 28153),
(157414, 'deDE', 'Gute Arbeit. Wenn Ihr einen Transport aus Boralus braucht, wir haben ein paar Agenten in der Nähe, die bereit stehen.', '', 28153),
(157413, 'deDE', 'Ich werde mich zurückschleichen und es Birkhain erzählen. Wir sehen uns dort!', '', 28153),
(157412, 'deDE', 'HA! Unsere Macht lässt alles zerbröckeln!', '', 28153),
(157411, 'deDE', '', 'Samuel... er... ist tot...', 28153),
(157410, 'deDE', 'Wenn der letzte seiner Untertanen ermordet und als Verlassener auferstanden ist, wird der kleine König vor der Dunklen Fürstin auf die Knie fallen. Und dann wird nur noch eine Königin herrschen.', '', 28153),
(157409, 'deDE', 'Rache, Verachtung, nennt es, wie Ihr wollt.', '', 28153),
(157408, 'deDE', '', 'Ah, die Rache treibt Euch also an. Das kann ich nachfühlen.', 28153),
(157407, 'deDE', 'Als der Lichkönig die Kontrolle über uns verlor, suchte Sylvanas Verbündete. Und anstatt die Gefallenen Lordaerons willkommen zu heißen, wiesen uns die Menschen ab. Sie jagten uns. Also schwor ich, es ihnen gleich zu tun.', '', 28153),
(157406, 'deDE', '', 'Den Rücken gekehrt?', 28153),
(157405, 'deDE', 'Einst kämpfte ich für sie. Doch die unerträgliche Arroganz der Allianz hat sich noch verzehnfacht, seitdem sie uns den Rücken gekehrt haben.', '', 28153),
(157404, 'deDE', '', 'Hinter dem Eifer, mit dem Ihr die Allianz bekämpft, steckt doch mehr als nur der Dienst gegenüber Eurer Königin, Pestrufer.', 28153),
(157403, 'deDE', '', 'Ich habe EINEN König zu Fall gebracht. Vielleicht ist es an der Zeit, das zu wiederholen.', 28153),
(157402, 'deDE', 'Gut. Die Allianz verdient kein Mitgefühl. Keine Gnade. Lasst sie leiden, dann wird die Dunkle Fürstin Euch belohnen.', '', 28153),
(157401, 'deDE', '', 'Stimmt. Und Ihr wisst zweifellos auch, dass ich mit der Allianz gearbeitet habe, als es mir dienlich war. Aber ich schulde ihnen nichts. Die Horde ist mein Zuhause.', 28153),
(157400, 'deDE', 'Ihr seid Narren...', '', 28153),
(157399, 'deDE', 'Im Namen von Kul Tiras! Verlasst diesen Ort!', '', 28153),
(157398, 'deDE', 'Ich kenne die Geschichte. Ich weiß aber auch, dass Ihr bei Llane Wrynns Tod keine Wahl hattet.', '', 28153),
(157397, 'deDE', '', 'Weil der Großvater des jungen Königs und ich einmal befreundet waren? Ich war es, die ihn ermordet hat!', 28153),
(157396, 'deDE', 'Eure Schläge gegen die Allianz waren höchst beeindruckend, Garona. Ich gebe zu, ich habe mich gefragt, ob Ihr vielleicht... zwei Herren dient.', '', 28153),
(157395, 'deDE', 'Hehehe... Frischfleisch!', '', 28153),
(157394, 'deDE', 'Spürt den Zorn der Natur!', '', 28153),
(157393, 'deDE', 'Ich werde Euch zu Geröll verarbeiten!', '', 28153),
(157392, 'deDE', 'Möchtet Ihr wirklich fortfahren?', 'Möchtet Ihr wirklich fortfahren?', 28153),
(157391, 'deDE', 'Gute Arbeit, $p. Das Sturmsangtal steht tief in Eurer Schuld.', '', 28153),
(157390, 'deDE', 'Träumt, träumt von der Versunkenen Stadt.', 'Träumt, träumt von der Versunkenen Stadt.', 28153),
(157389, 'deDE', 'Gefunden im Schatten seines Blickes...', 'Gefunden im Schatten seines Blickes...', 28153),
(157388, 'deDE', 'Verloren in ihrer unerbittlichen Umarmung...', 'Verloren in ihrer unerbittlichen Umarmung...', 28153),
(157387, 'deDE', 'Um die Weisheit der Ertrunkenen zu atmen...', 'Um die Weisheit der Ertrunkenen zu atmen...', 28153),
(157386, 'deDE', 'Die Überlebenden in der Terrorhügelhütte kämpfen seit Tagen ununterbrochen. Vielleicht könnt Ihr ihnen eine Atempause verschaffen.', '', 28153),
(157383, 'deDE', 'Das waren beeindruckend viele Explosionen! Ich bin froh, dass Ihr Euch nicht selbst in die Luft gejagt habt.', '', 28153),
(157382, 'deDE', 'Trinkt, trinkt von der schimmernden Flut...', 'Trinkt, trinkt von der schimmernden Flut...', 28153),
(157381, 'deDE', 'Die Venture Company verheert weiterhin diesen Küstenstrich. Trefft Euch mit Toki, vielleicht könnt Ihr ihm unter die Arme greifen.', '', 28153),
(157380, 'deDE', 'Uh...', 'Uh...', 28153),
(157379, 'deDE', 'Ihr seht einen ominösen Altar. Als Ihr Eure Hand darauflegt, beginnen sich Worte in Eurem Geist zu formen.\n\n\"Womit werdet Ihr anfangen?\"', '', 28153),
(157378, 'deDE', 'Gute Arbeit. Dafür gebe ich eine Runde aus.', '', 28153),
(157377, 'deDE', 'Wartet, bis ich Euch in die Klauen kriege!', '', 28153),
(157376, 'deDE', 'Ich werde Euch in Stücke reißen!', '', 28153),
(157375, 'deDE', 'Ich will, dass die Eisenfluträuber hier verschwinden. Vielleicht vertreiben wir sie, wenn wir ihnen ein bisschen das Leben schwer machen.', '', 28153),
(157374, 'deDE', 'Für Drustvar!', '', 28153),
(157373, 'deDE', 'Na los! Lasst uns das Monster in Schutt verwandeln!', '', 28153),
(157372, 'deDE', '', 'Die Tortollaner danken Euch für Eure Hilfe, und ich auch.', 28153),
(157371, 'deDE', '', 'Diese Schläger von der Venture Company mach\'n den Tortollanern weiterhin Schwierigkeiten! Champion, trefft Euch mit Toki und leistet ihn\' Hilfe.', 28153),
(157370, 'deDE', '', 'Unsre Feinde werd\'n erfahr\'n, dass ein Champion der Horde ihre Machenschaft\'n durchkreuzt hat. Gute Arbeit.', 28153),
(157369, 'deDE', '', 'Unsre Gegner werden jed\'n Tag stärker! Vernichtet ihre Ressourc\'n – und wenn nötig jed\'n Widerstand.', 28153),
(157368, 'deDE', '', 'Wir gewinn\' an Stärke, während unsre Feinde hungern. Manchmal sind\'s die kleinen Siege, die zum groß\'n Triumph führ\'n.', 28153),
(157367, 'deDE', '', 'Mit leer\'m Magen gewinn\' Soldaten kein\' Krieg. Haltet unsre Truppen mit Bärenfleisch bei Kräft\'n – und schenkt unsren Feind\'n nichts.', 28153),
(157362, 'deDE', 'Uralte Dinge, die es eigentlich nicht geben dürfte, beginnen sich zu regen. Seid auf der Hut.', 'Uralte Dinge, die es eigentlich nicht geben dürfte, beginnen sich zu regen. Seid auf der Hut.', 28153),
(157361, 'deDE', 'Wir hatten nicht erwartet, dass die Toten umherwandeln!', 'Wir hatten nicht erwartet, dass sich die Toten erheben und umherwandeln!', 28153),
(157360, 'deDE', 'Solch eine Macht hatten wir nicht erwartet! Seid vorsichtig, $gFestländer:Festländerin;.', 'Solch eine Macht hatten wir nicht erwartet! Seid vorsichtig, $gFestländer:Festländerin;.', 28153),
(157359, 'deDE', 'Die Konstrukte müssen zerstört werden! Bitte helft!', 'Die Konstrukte müssen zerstört werden! Bitte helft!', 28153),
(157358, 'deDE', 'Hilfe zur rechten Zeit, $gFestländer:Festländerin;.', 'Hilfe zur rechten Zeit, $gFestländer:Festländerin;.', 28153),
(157357, 'deDE', '$p, halt. Habt Ihr das gesehen?', '', 28153),
(157356, 'deDE', 'Ihr habt sie zurückgeschlagen, zumindest vorerst, und unsere Stadt steht noch. Wir verdanken Euch unser Leben.', '', 28153),
(157355, 'deDE', 'Die Horde ist zurück und hat Verstärkung dabei. Ihr müsst sie um jeden Preis aufhalten!', '', 28153),
(157354, 'deDE', 'Goldfeld bleibt lieber für sich, aber er merkt, wenn er in der Klemme steckt. Danke, dass Ihr ihm geholfen habt!', '', 28153),
(157353, 'deDE', 'Goldfeld hat um Eure Hilfe gebeten. Sein Hof wird immer noch angegriffen und ihm gehen bald die Vorräte aus. Helft ihm, so gut Ihr könnt.', '', 28153),
(157352, 'deDE', 'Das werden sie so schnell nicht wieder versuchen! Braver Hund.', '', 28153),
(157351, 'deDE', 'Die Stacheleber versuchen, ihr Tunnelnetzwerk auszubauen und bringen das ganze Tal in Gefahr. Unsere Hunde können sie ausfindig machen, wenn sie wissen, wo sie suchen müssen.', '', 28153),
(157350, 'deDE', 'Gehen wir, $p!', '', 28153),
(157349, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|tIhr seid von |cFFFF0000|Hspell:272536|h[Nahender Untergang]|h|r betroffen!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|tIhr seid von |cFFFF0000|Hspell:272536|h[Nahender Untergang]|h|r betroffen!', 28153),
(157348, 'deDE', 'Wisst Ihr, die Kammer hier wär\' ideal, um die königliche Antiquität\'nsammlung auszustell\'n. Vielleicht sollt\'n wir...', '', 28153),
(157347, 'deDE', '', 'Ich werde ganz in Eurer Nähe sein.', 28153),
(157346, 'deDE', 'Shandris, haltet den Kopf unten. Bleibt in den Schatten... wenn Ihr welche finden könnt.', '', 28153),
(157345, 'deDE', '', 'Verstanden, Hochkommandant! Reiten wir!', 28153),
(157344, 'deDE', 'Kelsey, Ihr seid unser Auge am Himmel. Gebt Bescheid, sobald Ihr etwas seht.', '', 28153),
(157343, 'deDE', 'Könntet Ihr den Plan noch einmal darlegen?', 'Könntet Ihr den Plan noch einmal darlegen?', 28153),
(157342, 'deDE', 'Meine Eltern haben immer gesagt, ich habe eine zu blühende Fantasie.', '', 28153),
(157341, 'deDE', 'Manchmal sind wir in einem Wagen einen Hügel ins Tal hinuntergerast! Wir haben getan, als wäre Hobbs ein Tiger!', '', 28153),
(157340, 'deDE', 'Hobbs und ich sind zu allen möglichen Abenteuern losgezogen, als wir klein waren.', '', 28153),
(157339, 'deDE', 'Zeigt es mir.', 'Zeigt es mir.', 28153),
(157338, 'deDE', 'Die Visionen können uns helfen, das Gemetzel zu beobachten, $R.', 'Die Visionen können uns helfen, das Gemetzel zu beobachten, $R.', 28153),
(157337, 'deDE', 'Bald schon wird auch die Flotte sich in ihrem Glanz sonnen und ganz Kul Tiras wird vor dem Licht der Tiefe knien.', '', 28153),
(157336, 'deDE', 'Ihr seid blind. Die Gezeitenmutter hat uns neue Stärke verliehen.', '', 28153),
(157335, 'deDE', 'Seelen der Verderbten, Ihr werdet Eure Schwüre noch erfüllen. Reißt dieses Tor nieder!', '', 28153),
(157334, 'deDE', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t Die Älteste Leaxa beginnt, |cFFF00000|Hspell:264603|h[Blutspiegel]|h|r zu wirken!', 28153),
(157333, 'deDE', '', 'Bei dieser Höhle habe ich ein gutes Gefühl. Ich sehe schon förmlich das Gold, das dort haufenweise herumliegt.', 28153),
(157332, 'deDE', 'Aber jetzt kommt doch die Stelle, wo ich mich mitten in seinen Rachen stürze und ihm von innen den Bauch aufschlitze!', 'Aber jetzt kommt doch die Stelle, wo ich mich mitten in seinen Rachen stürze und ihm von innen den Bauch aufschlitze!', 28153),
(157331, 'deDE', 'Na gut, na gut, Schnur und Senkblei haben geholfen. Aber der Rest ist wahr... jedes Wort!', 'Na gut, na gut, Schnur und Senkblei haben geholfen. Aber der Rest ist wahr... jedes Wort!', 28153),
(157330, 'deDE', 'Mpf mpf mpf mpf, mpf mpf!', 'Mpf mpf mpf mpf, mpf mpf!', 28153),
(157329, 'deDE', 'Klappe zu, Schnur. Wartet, bis Ihr dran seid!', 'Klappe zu, Schnur. Wartet, bis Ihr dran seid!', 28153),
(157328, 'deDE', '', 'Kein Gold, aber Unmengen von Rum!', 28153),
(157327, 'deDE', 'Jep, und zwar mit meinem Angelgeschick!', 'Jep, und zwar mit meinem Angelgeschick!', 28153),
(157326, 'deDE', 'Dank meines messerscharfen Verstands wusste ich genau, wie ich die Bestie kleinkriege.', 'Dank meines messerscharfen Verstands wusste ich genau, wie ich die Bestie kleinkriege.', 28153),
(157325, 'deDE', 'Dann hab ich\'s am Horizont gesehen. Eine Bestie, wie ich noch keine gesehen hab!', 'Dann hab ich\'s am Horizont gesehen. Eine Bestie, wie ich noch keine gesehen hab!', 28153),
(157324, 'deDE', 'Ich war auf Wache, Ausschau nach diesen dreckigen Naga halten.', 'Ich war auf Wache, Ausschau nach diesen dreckigen Naga halten.', 28153),
(157323, 'deDE', 'So, ich erzähl mal, wie ich die zwei Fischköppe hier getroffen hab.', 'So, ich erzähl mal, wie ich die zwei Fischköppe hier getroffen hab.', 28153),
(157322, 'deDE', 'Jap, da muss ich zustim– He, Moment mal!', 'Jap, da muss ich zustim– He, Moment mal!', 28153),
(157321, 'deDE', 'Der Helm ist Euch zu Kopf gestiegen. Eher glaube ich, dass Schnur wirklich mal was gefangen hat!', 'Der Helm ist Euch zu Kopf gestiegen. Eher glaube ich, dass Schnur wirklich mal was gefangen hat!', 28153),
(157320, 'deDE', 'Mpf, mpf mpf mpf mpf. Mpf.', 'Mpf, mpf mpf mpf mpf. Mpf.', 28153),
(157319, 'deDE', 'MPF!!!', 'MPF!!!', 28153),
(157318, 'deDE', 'Mpf mpf... mpf.', 'Mpf mpf... mpf.', 28153),
(157317, 'deDE', 'Gut, dass ich meine besondere Kugel hatte. Hab ich für genau so einen Anlass immer um den Hals getragen.', 'Gut, dass ich meine besondere Kugel hatte. Hab ich für genau so einen Anlass immer um den Hals getragen.', 28153),
(157316, 'deDE', 'Ich werd auf den Rum aufpassen, bis der Käpt\'n zurückkehrt.', '', 28153),
(157315, 'deDE', 'Käpt\'n... Ich hab nichts davon getrunken.', '', 28153),
(157314, 'deDE', '', 'Wo Piraten sind, gibt es normalerweise auch Gold!', 28153),
(157313, 'deDE', '', 'Einige der Arbeiter haben gesagt, sie hätten hier in der Höhle den Geist eines Piraten gesehen.', 28153),
(157312, 'deDE', '', 'Brennadam liegt gleich da vorn. Folgt mir!', 28153),
(157311, 'deDE', '', 'Ohne sie ist Kul Tiras ohne Schutz. Ein feindlicher Angriff ist nur eine Frage der Zeit.', 28153),
(157310, 'deDE', '', 'Wir müssen zu Bruder Pike. Hoffentlich kann er uns helfen, die Flotte heimzuholen.', 28153),
(157309, 'deDE', '', 'Ist das Tal nicht majestätisch? Kein Wunder, dass so viele hier leben wollen.', 28153),
(157308, 'deDE', '', 'Dieser Pass ist der einzige Landweg ins Tal. Haus Sturmsang führt etwas im Schilde.', 28153),
(157307, 'deDE', '', 'Brennadam ist neben Boralus das größte Handelszentrum in Kul Tiras.', 28153),
(157306, 'deDE', 'Strengt Euch mal an, Ihr faulen Säcke!', 'Strengt Euch mal an, Ihr faulen Säcke!', 28153),
(157305, 'deDE', 'Da oben ist er. Zwei Köpfe und riesig!', 'Er macht sich da oben bereit für den Angriff!', 28153),
(157304, 'deDE', 'Kümmert Euch um Euren eigenen Kram. Ich bin hier in offizieller Angelegenheit unterwegs!', 'Kümmert Euch um Euren eigenen Kram. Ich bin hier in offizieller Angelegenheit unterwegs!', 28153),
(157303, 'deDE', 'Was habt Ihr vor? Ihr müsst diesen Ort schleunigst verlassen, wie alle anderen auch!', 'Was habt Ihr vor? Ihr müsst diesen Ort schleunigst verlassen, wie alle anderen auch!', 28153),
(157302, 'deDE', 'Passt auf diese Keule auf!', 'Macht Euch besser aus dem Staub Tom, wir sind in der Überzahl!', 28153),
(157301, 'deDE', 'Wir beide geben Euch die Schuld... hierfür.', 'Wir beide geben Euch die Schuld... hierfür.', 28153),
(157300, 'deDE', 'Kommt und stellt Euch... uns beiden!', 'Kommt und stellt Euch... uns beiden!', 28153),
(157299, 'deDE', 'Ich nehme seinen rechten Kopf.', 'Er ist größer, als ich dachte.', 28153),
(157298, 'deDE', 'Untersuchen', 'Untersuchen', 28153),
(157296, 'deDE', 'Willkommen zurück, meine kleinen Freunde. Hört zu, ich hab ein neues Lied gelernt.', '', 28153),
(157294, 'deDE', 'Ihr werdet sterben und danach werde ich alle Leute im Dorf plattmachen!', 'Ihr werdet sterben und danach werde ich alle Leute im Dorf plattmachen!', 28153),
(157293, 'deDE', 'Die Sturmwacht wird unsere Flotte unter dem Banner der Allianz zum Sieg führen, wie schon zuvor.', '', 28153),
(157292, 'deDE', '', 'Haus Kronsteig steht Euch zur Seite, Lordadmiralin, wie auch der Allianz.', 28153),
(157291, 'deDE', '', 'Wir müssen unser Bündnis mit der Allianz erneuern, deren Helden uns vor unserem Untergang bewahrt haben.', 28153),
(157290, 'deDE', '', 'Daher bitte ich Euch heute, der wahren Lordadmiralin von Kul Tiras zu folgen... meiner Tochter Jaina.', 28153),
(157289, 'deDE', '', 'Die Absichten der Horde sind klar: Diese Wilden wollen uns brennen sehen.', 28153),
(157288, 'deDE', '', 'Seit langem werden wir von Zwietracht und durch Feinde von innen geschwächt.', 28153),
(157287, 'deDE', '', 'Danke für Euer Kommen. Ich werde mich kurz fassen.', 28153),
(157286, 'deDE', 'Ich wette, gemeinsam könnten wir es mit diesen Monstern aufnehmen!', '', 28153),
(157285, 'deDE', 'Als Daelin mich bat, seine Wache zu verlassen und dieses Kind aus den Östlichen Königreichen großzuziehen, verstand ich zuerst nicht, warum.\n\nWieso sollte ausgerechnet ich diese Bürde tragen? Warum wurde mir die Ehre verwehrt, an Daelins Seite zu kämpfen? Ich dachte schon, dass ich irgendetwas getan hatte, um sein Vertrauen zu verlieren.\n\nNach einiger Zeit habe ich aber verstanden, dass genau das Gegenteil der Fall war. Er wollte, dass Taelia richtig aufwächst, mit einer starken Hand und einem edlen Herzen, und diese verantwortungsvolle Aufgabe übertrug er mir. Er vertraute auf meine Fähigkeiten.', '', 28153),
(157284, 'deDE', '', 'Ist es wahr, dass man durch eine Art unterirdischen Tunnel von Sturmwind nach Eisenschmiede gelangen kann?$B$BDas hört sich unglaublich an! Ich würde den Tunnel gerne einmal sehen.', 28153),
(157283, 'deDE', 'Und das war nur eine Prise! Überlegt mal, wie viel Schaden die mit mehr von dem Zeug anrichten können.', '', 28153),
(157282, 'deDE', '', 'Danke. Jetzt können die Anwohner hoffentlich wieder ihre Felder bestellen.', 28153),
(157281, 'deDE', '', 'Die Bauern nicht weit von hier werden von einer Kreatur bedroht. Wir müssen ihnen helfen!', 28153),
(157280, 'deDE', '', 'Fantastisch! Ich wette, diese Vorräte finden sofort Verwendung.', 28153),
(157279, 'deDE', '', 'Hoffentlich kommt der Tag, an dem die Bürger von Kul Tiras der Führung der Gezeitenweisen wieder vertrauen können. Bis dahin müssen wir unseren eigenen Kurs finden.', 28153),
(157278, 'deDE', '', 'Das sollte uns dringend benötigte Zeit zum Durchatmen verschaffen. Ich danke Euch.', 28153),
(157277, 'deDE', '', 'Das Volk von Sturmsang wird Eure Heldentaten nicht vergessen. Gute Arbeit!', 28153),
(157276, 'deDE', '', 'In diesen Hügeln gibt es große Rohstoffvorkommen, die für die Sturmwacht wichtig sind. Könntet Ihr ihnen unter Umständen aushelfen?', 28153),
(157275, 'deDE', '', 'Die Streitkräfte von Lord Sturmsang machen wieder Probleme. Wir können nicht erlauben, dass sie ihre dunklen Rituale fortsetzen.', 28153),
(157274, 'deDE', '', 'Wir haben die Kontrolle über das Gebiet verloren! Geht da raus und drängt den Feind zurück!', 28153),
(157273, 'deDE', '', 'Die Sturmwacht benötigt hier dringend Hilfe. Tut, was Ihr könnt, um dem Tal zumindest wieder ein Gefühl von Frieden zu verleihen!', 28153),
(157272, 'deDE', '', 'Kanoniere! Bereitet das letzte Sperrfeuer vor!', 28153),
(157271, 'deDE', '', 'Haltet den Schild aufrecht! Wir können sie so schon kaum zusammenhalten!', 28153),
(157270, 'deDE', 'Noch jemand von den Verlassenen... Ich hätte nicht gedacht, dass... <hust>... Sagt, meine Dame...', '', 28153),
(157269, 'deDE', '<hust> Die Horde. Ich dachte, ich würde hier... <hust>... in Frieden sterben dürfen.\n\nUnd Ihr gehört zu den Verlassenen? Interessant, aber zu spät.\n\nAlso, worauf wartet Ihr?', '', 28153),
(157268, 'deDE', 'Ich sehe Euch dann beim Wagen wieder, $p!', '', 28153),
(157267, 'deDE', '', 'Juhuu! Zeit zum Plündern!', 28153),
(157266, 'deDE', 'Bitte bringt mich zurück.', 'Bitte bringt mich zurück.', 28153),
(157265, 'deDE', 'Danke für Eure Hilfe am heutigen Tag. Wir sollten zurückkehren.', 'Danke für Eure Hilfe am heutigen Tag. Wir sollten zurückkehren.', 28153),
(157264, 'deDE', 'Beobachtet das Aufeinandertreffen von Zelling und seiner Familie.', 'Beobachtet das Aufeinandertreffen von Zelling und seiner Familie.', 28153),
(157263, 'deDE', 'Gute Arbeit, wie immer. Wenn alle Mitglieder der Allianz wie Ihr reiten, sind sie auf meinem Anwesen jederzeit willkommen!', '', 28153),
(157262, 'deDE', 'Ah, was für ein herrlicher Tag für eine Vorführung! Schwingt Euch aufs Pferd und zeigt im Ring, was Ihr könnt!', '', 28153),
(157261, 'deDE', '', 'Wie Ihr wollt. Kommt schon, $n!', 28153),
(157260, 'deDE', 'Ich kehre zum Lager zurück. Ich weiß, wie das hier enden wird, und ich muss mir das nicht ansehen.', '', 28153),
(157259, 'deDE', 'Zeigt \'n bisschen Respekt un\' verzieht Euch! Verschwendet mir nich\' meine Zeit mit dem Hexfürst\'n.', '', 28153),
(157258, 'deDE', '', 'Klasse! Das sollte den Naga einen Dämpfer verpassen.', 28153),
(157257, 'deDE', '', 'Ihr habt mein Wort. Kommt. $n, kehrt zurück zu Nathanos und informiert ihn darüber, dass wir haben, was wir brauchen.', 28153),
(157256, 'deDE', 'Ich werde Euch beitreten... und Euch helfen, Marschall Valentin zu finden, wenn Ihr mir versprecht, dass meiner Familie nichts passiert.', '', 28153),
(157255, 'deDE', '', 'Die Naga starten einen neuen Vorstoß aufs Tor! Zeigt ihnen, wie Tortollaner das regeln!', 28153),
(157254, 'deDE', '', 'Schließt Euch den Verlassenen an und findet Euren eigenen Weg. Ihr werdet unter Euresgleichen sein, wo man Euch akzeptiert, wie Ihr seid.', 28153),
(157253, 'deDE', 'Und was bleibt mir noch? Bin ich nur noch ein stumpfer Diener der Bansheekönigin?', '', 28153),
(157252, 'deDE', '', 'Das is\' \'ne Ehre, die Auß\'nseitern selt\'n gewährt wird. Kommt, begeht den Pfad mit mir un\' erzählt von den Tat\'n dieses Vol\'jin!', 28153),
(157250, 'deDE', '', 'Ich habe versucht, Euch zu warnen, Zelling. Der Prozess verändert Euch. Die Lebenden werden Euch nicht mehr akzeptieren.', 28153),
(157249, 'deDE', 'Nein... Julia... Matthias... Hannah... Was habe ich nur getan? Was... bin ich?', '', 28153),
(157248, 'deDE', '', 'Mach, dass das Monster verschwindet!', 28153),
(157247, 'deDE', '', 'Lasst uns in Frieden!', 28153),
(157246, 'deDE', 'Mach, dass er weggeht!', '', 28153),
(157245, 'deDE', 'Ruhe!', '', 28153),
(157244, 'deDE', '', 'Ich weiß nicht, wer Ihr seid, aber mein Ehemann hätte NIEMALS versucht, mir oder meinen Kindern wehzutun. Wir gehen jetzt. Folgt uns nicht!', 28153),
(157243, 'deDE', 'Ich... Ich...', '', 28153),
(157242, 'deDE', 'DAS REICHT!', '', 28153),
(157241, 'deDE', 'Mami! Hilf uns!', '', 28153),
(157240, 'deDE', '', 'Halt ihn weg von uns!', 28153),
(157239, 'deDE', 'Vati steht direkt vor euch. Hört auf meine Stimme! Warum versteht ihr das nicht?', '', 28153),
(157238, 'deDE', '', 'Bleibt weg!', 28153),
(157237, 'deDE', 'Mami, ich hab Angst vor dem Ungeheuer!', '', 28153),
(157236, 'deDE', 'Warum willst du es nicht verstehen? Ich bin dein Ehemann... Kinder, ich bin es, euer Vati!', '', 28153),
(157235, 'deDE', '', 'Zum letzten Mal, BLEIBT ZURÜCK! Ihr seid NICHT mein Ehemann!', 28153),
(157234, 'deDE', 'Ich bleibe stark... auch im Tod.', '', 28153),
(157233, 'deDE', 'Ihr seid auf einen Kampf gegen mich nicht vorbereitet!', '', 28153),
(157232, 'deDE', 'Zelling, Ihr müsst Marschall Valentins Leichnam für uns finden.', 'Zelling, Ihr müsst Marschall Valentins Leichnam für uns finden.', 28153),
(157231, 'deDE', 'Meine Familie wird... mich rächen.', '', 28153),
(157230, 'deDE', 'Ihr werdet meine Wut zu spüren bekommen!', '', 28153),
(157229, 'deDE', '', 'Ich denke, wir werden sehen, was nun geschieht.', 28153),
(157228, 'deDE', 'Ich... lebe! Hahaha! Ich muss sofort zu Julia und den Kindern! Sie werden sich ja so freuen!', '', 28153),
(157227, 'deDE', '', 'Nur wenige Geister ham so \'ne... Macht. Meister Gadrin, bringt die Asche von dem Häuptling nach Atal\'Dazar. Wenn er sich würdig erweist, steht ihm \'n Ehrenplatz unter uns\'ren größten Königen zu.', 28153),
(157226, 'deDE', 'Davon wird Zalazane sich nich\' erhol\'n. Vol\'jin wacht selbst aus dem Jenseits über uns.', '', 28153),
(157225, 'deDE', 'Die Toten, sie fall\'n...', '', 28153),
(157224, 'deDE', 'Unsere Verstärkung erwartet Euren Befehl.', '', 28153),
(157223, 'deDE', 'Wenn die Horde Krieg will, werden wir ihr alles geben, was wir haben!', '', 28153),
(157222, 'deDE', 'Ich hoffe, Ihr bringt gute Neuigkeiten.', '', 28153),
(157221, 'deDE', 'Sturmsang trotzt jedem Wetter.', '', 28153),
(157220, 'deDE', 'Haltet die Ohren steif.', '', 28153),
(157219, 'deDE', 'Die Flut leite Euch.', '', 28153),
(157218, 'deDE', 'Ausgezeichnet! Diese Vorräte können wir garantiert gebrauchen. Und für diese Ferkel findet sich sicher auch Verwendung.', '', 28153),
(157217, 'deDE', 'Die Stacheleber haben schon wieder unsere Lager überfallen. Also lasst es uns ihnen mit gleicher Münze heimzahlen. Holt unsere Vorräte zurück und nehmt außerdem alles mit, was irgendwie brauchbar aussieht!', '', 28153),
(157216, 'deDE', 'Ist geritzt.', '', 28153),
(157215, 'deDE', '', 'Aye, Sir!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'deDE', '', 'Gnädige Elune, bitte segne die Gefallenen.', 28153),
(157213, 'deDE', 'Taelia, macht wieder Eure Runde. Sagt der Stadtwache, sie sollen auf Schmuggler achten, die ungewöhnliche Waffen nach Boralus schleusen wollen.', '', 28153),
(157212, 'deDE', '', 'Ich hab entschied\'n, dass Vol\'jin, Sohn von Sen\'jin, dieser heilig\'n Grabstätte würdig is\'. Aber um Atal\'Dazar zu betret\'n, müsst Ihr vielleicht kämpf\'n. Ich schlag vor, der Champion trägt die Asche zu ihrer letzt\'n Ruhestätte.', 28153),
(157211, 'deDE', '', 'Es is\' schwer, das zu tun, wozu die Anführer nich\' bereit sin\'.', 28153),
(157210, 'deDE', 'Als klar wurde, dass Kriegshäuptling Garrosh keine Ehre besaß, führte Vol\'jin \'ne Rebellion, um den Kriegstreiber abzusetz\'n.', '', 28153),
(157209, 'deDE', '', 'Damals war Zuls Vision von \'nem großen Trollimperium verlock\'nd für mein\' Vater. Ich bin erfreut, dass der Kriegshäuptling \'nen Blick fürs große Ganze hatte.', 28153),
(157208, 'deDE', 'Als Zandalar die Trollstämme verein\' wollte, wählte Vol\'jin die Sicherheit von sei\'m Volk, nicht die dunklen Mächte vom Prophet\'n.', '', 28153),
(157207, 'deDE', 'Vo\'jin schloss \'nen Pakt mit Bwonsamdi, um den mächtig\'n Zalazane zu bezwing\'n.', '', 28153),
(157206, 'deDE', '', 'Das sind mehr Irrwische, als ich zählen kann. Die verlorenen Leben...', 28153),
(157205, 'deDE', 'Wir bring\'n die Asche von Vol\'jin, Sohn von Sen\'jin, um an dies\'m heilig\'n Ort geehrt zu werden.', '', 28153),
(157204, 'deDE', 'Finn, ein neuer Auftrag für Euch: Helft unserem neuen Verbündeten hier, die Quelle dieses Pulvers zu finden.', '', 28153),
(157203, 'deDE', 'In diesen Landen regen sich uralte Bedrohungen. Seid vorsichtig.', '', 28153),
(157202, 'deDE', 'Windruferin, ich bin auf Geheiß des Kriegshäuptlings gekommen.', 'Windruferin, ich bin auf Geheiß des Kriegshäuptlings gekommen.', 28153),
(157201, 'deDE', 'Ja, ich muss nach Silithus.', 'Ja, ich muss nach Silithus.', 28153),
(157200, 'deDE', 'Warum bin ich hier, Mensch?', 'Warum bin ich hier, Mensch?', 28153),
(157199, 'deDE', '$uAbgesandter:Abgesandte;! Gebt unseren Skeptikern hier mal eine kleine Demonstration!', '', 28153),
(157198, 'deDE', 'Aber keine wie die hier.', '', 28153),
(157197, 'deDE', 'Heh. Das nennt Ihr eine heiße Spur? Die entwickeln dauernd neue Waffen.', '', 28153),
(157196, 'deDE', '', 'Na gut, Finn. Was ist das für eine \"heiße Spur\"? Irgendwas über ein neues Aschenwindschießpulver?', 28153),
(157195, 'deDE', 'Ich brauche einen Windreiterflug nach Marschalls Zuflucht im Krater von Un\'Goro.', 'Ich brauche einen Windreiterflug nach Marschalls Zuflucht im Krater von Un\'Goro.', 28153),
(157194, 'deDE', 'Wieder da? Gut! Hatt schon befürchtet, ich muss der Prinzessin erklär\'n, dass \'n Zwerg aus Diamant ihr\'n Champion gestohl\'n hat.', '', 28153),
(157193, 'deDE', 'Woow! Das haben wir ja klasse hingekriegt!', '', 28153),
(157192, 'deDE', 'Wir müssen was von der verlorenen Fracht bergen. Und mit \"wir\" meine ich Euch.', '', 28153),
(157191, 'deDE', 'Wo auch immer Ihr hingeht, ich hoff, es geht schnell. Die Prinzessin braucht Eure Hilfe wirklich.', 'Wo auch immer Ihr hingeht, ich hoff, es geht schnell. Die Prinzessin braucht Eure Hilfe wirklich.', 28153),
(157190, 'deDE', 'Außergewöhnlich! Ich sollt das dokumentier\'n.', 'Außergewöhnlich! Ich sollt das dokumentier\'n.', 28153),
(157189, 'deDE', 'Die Sicherung von Nachschublinien ist eine Grundregel der Kriegsführung... genauso wie die Unterbrechung der feindlichen.', '', 28153),
(157188, 'deDE', 'Wracks von Allianzschiffen... stets ein erfreulicher Anblick! Sucht ihre Umgebung nach nützlichen Vorräten für die Horde ab.', '', 28153),
(157187, 'deDE', 'Ein ganz normaler Arbeitstag.', '', 28153),
(157186, 'deDE', 'Dieser Extraktor wird angegriffen. Verteidigt ihn!', '', 28153),
(157185, 'deDE', 'Diese Ressourcen werden der Horde von größtem Nutzen sein. Gute Arbeit.', '', 28153),
(157184, 'deDE', 'Verteidigt unseren Extraktor! Wir brauchen dieses Azerit!', '', 28153),
(157183, 'deDE', 'Wie ist Eure Strategie, Shandris?', 'Wie ist Eure Strategie, Shandris?', 28153),
(157182, 'deDE', '', '<Shandris\' scharfe Augen suchen den Horizont ab. Sie nickt Euch bestätigend zu.>', 28153),
(157181, 'deDE', 'Findet Sonnenwächter und durchlöchert ihn mit Pfeilen.', '', 28153),
(157180, 'deDE', 'Meine Strategie?', '', 28153),
(157179, 'deDE', 'Das Team des Geheimdienstes von Gnomeregan wird ein paar Bomben platzieren, um Sonnenwächter herauszulocken, und dann werden wir in dem folgenden Chaos zuschlagen.', '', 28153),
(157178, 'deDE', '', 'Hey hey!', 28153),
(157177, 'deDE', 'Bestätigt. Zu diesem Zweck habe ich ein hochspezialisiertes Einsatzteam mit dem nötigen technischen Wissen auf den Auftrag angesetzt.', '', 28153),
(157176, 'deDE', '', 'Am besten lasst Ihr mehrere Bomben gleichzeitig hochgehen.', 28153),
(157175, 'deDE', 'Ich möchte einen synchronisierten Brandanschlag auf all ihre Ausgrabungsstätten durchführen.', '', 28153),
(157174, 'deDE', 'Ja. Unsere Späher haben mindestens drei Ausgrabungsstätten gefunden.', '', 28153),
(157173, 'deDE', '', 'Archäologie?', 28153),
(157172, 'deDE', 'Sonnenwächter ist ein Mitglied der Archäologischen Akademie und befindet sich hier auf einer archäologischen Mission.', '', 28153),
(157171, 'deDE', 'Ich... ich erinner mich nich\'. Das is\' aber besser so.', '', 28153),
(157170, 'deDE', '', 'Vergebt mir,... wer sagtet Ihr, seid Ihr? Malfurion hat also von EUCH gesprochen?', 28153),
(157168, 'deDE', 'Ich habe Eure Mitteilung an B\'wizati übergeben.', 'Ich habe Eure Mitteilung an B\'wizati übergeben.', 28153),
(157167, 'deDE', '', 'Und die Zivilisten... nicht einmal sie wurden verschont. Ich hoffe nur, dass einige fliehen konnten, bevor...', 28153),
(157166, 'deDE', '', 'Unsere Außenposten wurden überrascht. Einer nach dem anderen fiel. Die Wachen wurden vergiftet.', 28153),
(157165, 'deDE', '', '%s wischt sich eine Träne weg, als sie aufsteht.', 28153),
(157164, 'deDE', '', 'Wir haben versucht, der Horde eine Falle zu stellen. Ohne Erfolg. Wir konnten sie nicht aufhalten.', 28153),
(157163, 'deDE', 'Schön, dass es Euch gut geht, $n.\n\nMir geht\'s auch gut.\n\nAkunda hat mir \'ne neue Chance gewährt.', '', 28153),
(157162, 'deDE', 'Wie sieht Euer Plan aus, Hochkommandant?', 'Wie sieht Euer Plan aus, Hochkommandant?', 28153),
(157161, 'deDE', 'Die 7. Legion stellt das Beste dar, was Azeroth zu bieten hat.\n\nFür die Allianz!', '', 28153),
(157160, 'deDE', 'Wen? Nee, \'nen Troll mit dem Nam\' kenn ich nich\'.', '', 28153),
(157159, 'deDE', '', 'Leichen überall... so viele Tote...', 28153),
(157158, 'deDE', 'Ich muss $n etwas zeigen. Ein Geschenk, das den Völkern dieses Landes helfen kann.', '', 28153),
(157157, 'deDE', '\'n Zwerg... ganz aus Diamant... im Herz\'n von Zuldazar! Wer...?', '', 28153),
(157156, 'deDE', '', 'Ich habe in diesen Wäldern schon komische Dinge gesehen, aber so etwas ist mir noch nicht untergekommen.', 28153),
(157155, 'deDE', 'Spürt Ihr das? Der Bod\'n bebt...', '', 28153),
(157153, 'deDE', 'Auf Befehl des Krieghäuptlings werde ich Euch unterstützen.', 'Auf Befehl des Krieghäuptlings werde ich Euch unterstützen.', 28153),
(157152, 'deDE', 'Ich muss nach Gadgetzan in Tanaris fliegen.', 'Ich muss nach Gadgetzan in Tanaris fliegen.', 28153),
(157151, 'deDE', 'Ihr... müsst...', '', 28153),
(157150, 'deDE', 'Ich würde... meine Seele... auf ewig... in die Verdammnis schicken... wenn es... das Glück meiner Familie garantiert... Bitte! Ihr müsst...', '', 28153),
(157149, 'deDE', '', 'Das frage ich mich jeden Tag, Zelling.', 28153),
(157148, 'deDE', 'Ziel erfasst.', '', 28153),
(157147, 'deDE', '', 'Wir werden alle ein wenig verrückt, wenn wir zu Verlassenen werden. Einige mehr, andere weniger.', 28153),
(157146, 'deDE', 'Kennt Ihr Akunda?', 'Kennt Ihr Akunda?', 28153),
(157145, 'deDE', 'Lasst Akunda die Sorgen lindern, die schwer auf Euerm Herzen last\'n.', 'Lasst Akunda die Sorgen lindern, die schwer auf Euerm Herzen last\'n.', 28153),
(157144, 'deDE', 'Akunda gibt uns \'ne Chance, neu zu beginn\'n.', 'Akunda gibt uns \'ne Chance, neu zu beginn\'n.', 28153),
(157143, 'deDE', 'Euer Besuch is\' uns hier stets willkomm\'n.', 'Euer Besuch is\' uns hier stets willkomm\'n.', 28153),
(157142, 'deDE', 'Der Loa heißt alle in seinem Tempel willkomm\'n.', 'Der Loa heißt alle in seinem Tempel willkomm\'n.', 28153),
(157141, 'deDE', 'Kennt Ihr Akunda?', 'Kennt Ihr Akunda?', 28153),
(157140, 'deDE', 'Lasst Akunda die Sorgen lindern, die schwer auf Euerm Herzen last\'n.', 'Lasst Akunda die Sorgen lindern, die schwer auf Euerm Herzen last\'n.', 28153),
(157139, 'deDE', 'Akunda gibt uns \'ne Chance, neu zu beginn\'n.', 'Akunda gibt uns \'ne Chance, neu zu beginn\'n.', 28153),
(157138, 'deDE', 'Euer Besuch is\' uns hier stets willkomm\'n.', 'Euer Besuch is\' uns hier stets willkomm\'n.', 28153),
(157137, 'deDE', 'Der Loa heißt alle in seinem Tempel willkomm\'n.', 'Der Loa heißt alle in seinem Tempel willkomm\'n.', 28153),
(157136, 'deDE', 'Ich bin hier, um zu helfen, Nyse.', 'Ich bin hier, um zu helfen, Nyse.', 28153),
(157135, 'deDE', 'Ah, der Alptraum ist vorbei.', 'Ah, der Alptraum ist vorbei.', 28153),
(157134, 'deDE', 'Geladen und entsichert! Ballert diesen Kraken zurück in die Tiefe!', 'Geladen und entsichert! Ballert diesen Kraken zurück in die Tiefe!', 28153),
(157133, 'deDE', 'Feuerbereit!', 'Feuerbereit!', 28153),
(157132, 'deDE', 'Doras, ich benötige einen Flug nach Morastwinkel in den Düstermarschen.', 'Doras, ich benötige einen Flug nach Morastwinkel in den Düstermarschen.', 28153),
(157131, 'deDE', 'Die Kanone ist bereit! Schickt diese Bestie zu den Fischen!', 'Die Kanone ist bereit! Schickt diese Bestie zu den Fischen!', 28153),
(157130, 'deDE', 'Nein... NEIN!', 'Nein... NEIN!', 28153),
(157129, 'deDE', 'Vielen Dank! Ich mache die Kanone jetzt klar, und dann ist Zahltag für dieses Monster!', 'Vielen Dank! Ich mache die Kanone jetzt klar, und dann ist Zahltag für dieses Monster!', 28153),
(157128, 'deDE', 'Zabanji schnarcht.', 'Zabanji schnarcht.', 28153),
(157127, 'deDE', 'Ich schulde Euch was! Jetzt gebt mir einen Moment, um die Kanone klarzumachen!', 'Uff, ich schulde Euch was! Jetzt gebt mir einen Moment, um die Kanone klarzumachen!', 28153),
(157126, 'deDE', 'War alles nur ein Traum?', 'War alles nur ein Traum?', 28153),
(157125, 'deDE', 'Lasst nicht zu, dass diese Bestie mich frisst!', 'Lasst nicht zu, dass diese Bestie mich frisst!', 28153),
(157124, 'deDE', 'Verbrennt sie alle zu Asche!', '', 28153),
(157123, 'deDE', 'Schafft mir dieses Ding vom Hals!', 'Schafft mir dieses Ding vom Hals!', 28153),
(157122, 'deDE', '$p, nehmt Euch eine Fackel und haut nach allem, was sich bewegt. Diese untoten Ausgeburten haben kein Mitleid verdient!', '', 28153),
(157121, 'deDE', 'Sehr richtig, Gefreiter. Und in diesem unheiligen Hafen gibt es unendlich viele Monster, die es zu töten gilt.', '', 28153),
(157120, 'deDE', 'Hilfe!', 'Hilfe!', 28153),
(157119, 'deDE', 'Und niemand macht uns die Gegner streitig, Sir.', '', 28153),
(157118, 'deDE', 'Wer seid Ihr? Wo sind wir?', 'Wer seid Ihr? Wo sind wir?', 28153),
(157117, 'deDE', 'Es gibt keine Verstärkung. Wenn wir das vermasseln, sind wir verloren.', '', 28153),
(157116, 'deDE', 'Zugehört, Soldaten! Das hier ist eine unautorisierte Mission.', '', 28153),
(157115, 'deDE', 'Worauf wartet Ihr, $p?\n\nWir haben Waffen und wir haben einen Feind. Los, in das Boot!', 'Worauf wartet Ihr, $p?\n\nWir haben Waffen und wir haben einen Feind. Los, in das Boot!', 28153),
(157114, 'deDE', 'Akunda der Müdigkeit schnarcht.', 'Akunda der Müdigkeit schnarcht.', 28153),
(157113, 'deDE', 'Wir alle sind... Akunda.', 'Wir alle sind... Akunda.', 28153),
(157112, 'deDE', 'Mehr Arbeit?', '', 28153),
(157111, 'deDE', 'Richtig.', '', 28153),
(157110, 'deDE', 'Na gut.', '', 28153),
(157109, 'deDE', 'Ja, mein Lord.', '', 28153),
(157108, 'deDE', '', 'Jawohl.', 28153),
(157107, 'deDE', 'Nun gut. Dann gehen wir ohne sie weiter. Wenn sie nicht allzu bald kommt... haltet Eure Klingen bereit.', '', 28153),
(157106, 'deDE', '', 'Sie braucht... eine Weile, um sich zu akklimatisieren.', 28153),
(157105, 'deDE', '', 'Hnn... gh....', 28153),
(157104, 'deDE', 'Stein, seid ein Schatz und nennt den Namen des wichtigsten Kriegshelden, der auf diesem Friedhof begraben liegt.', '', 28153),
(157103, 'deDE', 'Jetzt, wo Ihr hier seid, können wir anfangen.', '', 28153),
(157102, 'deDE', 'Kämpft für Eure Brüder und Schwestern!', 'Kämpft für Eure Brüder und Schwestern!', 28153),
(157101, 'deDE', 'Sieg für die Allianz!', 'Sieg für die Allianz!', 28153),
(157100, 'deDE', 'Auf in die Schlacht!', 'Auf in die Schlacht!', 28153),
(157099, 'deDE', 'Das habt Ihr gut gelöst, $p. Heute kommen alle sicher nach Hause.', '', 28153),
(157098, 'deDE', 'Arathi gehört uns!', 'Arathi gehört uns!', 28153),
(157097, 'deDE', 'Tod der Horde!', 'Tod der Horde!', 28153),
(157096, 'deDE', 'Folgt mir!', 'Folgt mir!', 28153),
(157095, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(157094, 'deDE', 'Hier entlang! Wir haben einen Krieg zu gewinnen!', 'Hier entlang! Wir haben einen Krieg zu gewinnen!', 28153),
(157093, 'deDE', 'Die Horde hier hat die Wildtiere ins Tiefland getrieben. Helft den Jägern, mit den Bären fertigzuwerden.', '', 28153),
(157092, 'deDE', 'Ihr... Ihr habt mich dazu gebracht, meinen Freund zu töten! Jetzt werdet Ihr sterben!', '', 28153),
(157091, 'deDE', 'Brüder und Schwestern, seht unsere glorreiche Bestimmung!', '', 28153),
(157090, 'deDE', 'Danke vielmals. Das Tal ist mit Euch.', 'Ich bin so froh, Euch zu sehen, $p. Das werde ich nicht vergessen.', 28153),
(157089, 'deDE', 'Ich komme jetzt wohl alleine klar. Seid vorsichtig.', 'Ihr seid ein willkommener Anblick!', 28153),
(157088, 'deDE', 'Ich glaubte, ganz sicher tot zu sein!', 'Das werde ich Euch nicht vergessen. Vielen Dank!', 28153),
(157087, 'deDE', 'Ha! Vielleicht sind diese Eber gar nicht mal so schlecht. Ich frage mich, ob sie gedämpfte Miesmuscheln mögen...', '', 28153),
(157086, 'deDE', 'Einige unbewachte Eber wurden außerhalb des Krals gesichtet. Wenn Ihr willens seid, Euch auf den Rücken eines dieser Biester zu schwingen, können wir sie gegen die Stacheleber einsetzen!', '', 28153),
(157085, 'deDE', 'Rächt mich... Eikceps...', '', 28153),
(157084, 'deDE', '', 'Endlich... Die Qualen enden...', 28153),
(157083, 'deDE', '', 'Ja... Freiheit...', 28153),
(157082, 'deDE', '', 'Es war... eine Falle...', 28153),
(157081, 'deDE', '', 'Ha... Der Jäger wird zum Gejagten...', 28153),
(157080, 'deDE', '', 'Er kommt uns alle holen...', 28153),
(157079, 'deDE', 'Eure Majestät, einen Moment! Wir haben neue Informationen.', '', 28153),
(157078, 'deDE', '', 'Das hätte... nicht... passieren sollen...', 28153),
(157077, 'deDE', '', 'Es ist so praktisch, wenn die Beute ganz von selbst herkommt!', 28153),
(157076, 'deDE', '', 'Sieh einer an, was mir da in die Falle gegangen ist!', 28153),
(157075, 'deDE', '', 'Ihr seid ein bisschen mickrig, aber ich ziehe Euch trotzdem die Haut ab!', 28153),
(157074, 'deDE', '', 'Sie haben mir die ganze Beute des Waldes versprochen!', 28153),
(157073, 'deDE', '', 'Euer Pelz wird mir ein hübsches Sümmchen einbringen!', 28153),
(157072, 'deDE', '', 'Noch ein Pelz für mich!', 28153),
(157071, 'deDE', 'Ihr werdet... fallen...', '', 28153),
(157070, 'deDE', 'Ich werde wieder eins mit der Erde...', '', 28153),
(157069, 'deDE', 'Das Ende... naht...', '', 28153),
(157068, 'deDE', 'Was wollt Ihr? Buh! Verschwindet!', '', 28153),
(157067, 'deDE', 'Meine Seele... ist verseucht...', '', 28153),
(157066, 'deDE', 'Der Schleier wurde gelüftet...', '', 28153),
(157065, 'deDE', 'Thros wird uns alle verschlingen!', '', 28153),
(157064, 'deDE', 'Er spricht aus dem Jenseits!', '', 28153),
(157063, 'deDE', 'Die Rache wird unser sein... un\' die Schätze auch!', '', 28153),
(157062, 'deDE', 'Aye, nehmt Euch \'ne Fackel und ran an die Arbeit, $p!', 'Aye, nehmt Euch \'ne Fackel und ran an die Arbeit, $p!', 28153),
(157061, 'deDE', 'Aye, wir werd\'n hier die Hölle losbrech\'n lass\'n und sie hinunter in die dunklen Meerestiefen schick\'n!', '', 28153),
(157060, 'deDE', 'Wir brenn\' sie also nieder, aye?', 'Wir brenn\' sie also nieder, aye?', 28153),
(157059, 'deDE', 'Unsre alte verfluchte Mannschaft im Hafen von Zem\'lan hat heute \'nen Haufen Überfallkommandos losgeschickt und wir sin\' eins von den Zielen.', '', 28153),
(157058, 'deDE', 'Willkomm\'n zurück auf der salzigen See, Ihr Leichtmatrosen!', '', 28153),
(157057, 'deDE', 'Alle Mann an die Riemen!', 'Alle Mann an die Riemen!', 28153),
(157056, 'deDE', 'Sobald ich diesen Zauber durchschaut habe, lassen sie mich vielleicht wieder hinein. Wie wäre es mit... Llott si leinad!', '', 28153),
(157055, 'deDE', 'Eikceps, wenn Ihr mich verstehen könnt, dann möchte ich gerne sagen, wie leid es mir tut, dass ich Euch verwandelt habe... permanent ... verwandelt habe.', '', 28153),
(157054, 'deDE', 'Ich frage mich, ob Euer Name funktionieren wird, Eikceps. Versuchen wir\'s mit Enolem enietsi Eikceps!', '', 28153),
(157053, 'deDE', 'Es war gemein von ihnen, mich zu verbannen, Eikceps. Dafür werde ich sie mit meinem stärksten Zauber bestrafen... äh... sobald ich mich daran erinnere, wie er ging.', '', 28153),
(157052, 'deDE', 'Hm, nein... Der scheint es nicht zu sein.', '', 28153),
(157051, 'deDE', 'Ich kann mich einfach nicht an diesen blöden Zauber erinnern. Wie ging das nochmal, Eikceps? Leinad sonstwas... Nos fatsug?', '', 28153),
(157050, 'deDE', 'Mir wurden die Augen geöffnet!', '', 28153),
(157049, 'deDE', 'Euer Blut wird den Wald nähren!', '', 28153),
(157048, 'deDE', 'Rrrraaaaagh!', '', 28153),
(157047, 'deDE', 'Ausgezeichnet. Vielleicht können wir hier eines Tages wieder unsere Gebete sprechen.', '', 28153),
(157046, 'deDE', 'Wenn niemand eingreift, verdirbt die Magie hier die umliegenden Gewässer. Beschäftigt die Gezeitenweisen, so lange Ihr könnt.', '', 28153),
(157045, 'deDE', 'Mögen die Gezeiten ihre fehlgeleiteten Seelen zur letzten Ruhe tragen.', '', 28153),
(157044, 'deDE', 'Der dunkle Einfluss von Haus Sturmsang wird hier von bestimmten Individuen ausgeübt. Beendet ihr Leben, bevor sie noch mehr Schaden anrichten können.', '', 28153),
(157043, 'deDE', 'Gute Arbeit! Ich kann den Rauch von hier aus sehen! Wir schlagen so bald es geht wieder zu.', '', 28153),
(157042, 'deDE', 'Ich hoffe, Ihr mögt Greifen! Sprecht mit Babette Röbken. Sie arbeitet an einem Angriffsplan gegen die Horde bei der Reißzahnfeste.', '', 28153),
(157041, 'deDE', '', 'Was los?', 28153),
(157040, 'deDE', 'Ihr seid schwach ohne den Loa! Gebt ihm den Rest!', '', 28153),
(157039, 'deDE', 'Der versteckt sich hinter Rezans Macht. Ich hol sie mir zurück!', '', 28153),
(157038, 'deDE', 'Vergesst nie, Festländer: Fürchtet, was in der Tiefe lauert. Nichts Gutes lebt in ihren dunkelsten Schatten.', '', 28153),
(157037, 'deDE', 'Einige der Gezeitenweisen hier versuchen, eine Macht herbeizurufen, die Boralus dem Erdboden gleichmachen könnte. Ihr müsst sie aufhalten!', '', 28153),
(157036, 'deDE', '', 'Überlasst ihr die Führung und sie wird Euch in einem Stück hin- und zurückbringen.', 28153),
(157035, 'deDE', '', 'Sie ist abflugbereit!', 28153),
(157034, 'deDE', '', 'Sie ist der schnellste Greif im Tal. Wenn jemand etwas anderes behauptet, lügt er.', 28153),
(157033, 'deDE', 'Ihr seid als Nächstes an der Reihe!', 'Ihr seid als Nächstes an der Reihe!', 28153),
(157032, 'deDE', 'Ihr und der Vogel seid nicht nett.', 'Ihr und der Vogel seid nicht nett.', 28153),
(157031, 'deDE', 'Ich will auch fliegen!', 'Ich will auch fliegen!', 28153),
(157030, 'deDE', 'Ich hasse die Allianz.', 'Ich hasse die Allianz.', 28153),
(157029, 'deDE', 'Schaut! Hübscher Vogel.', 'Schaut! Hübscher Vogel.', 28153),
(157028, 'deDE', '', 'Der Neuerschaffungsantrieb is\' bereit. Jetzt liegt\'s an uns, G\'huuns Seuche ein für alle mal zu beend\'n.', 28153),
(157027, 'deDE', 'Der Neuerschaffungsantrieb ist bereit. Werfen wir ihn an und drücken wir G\'huun aus wie eine eitrige Pustel.', '', 28153),
(157026, 'deDE', 'Jetzt werd ich... zerquetscht?', 'Jetzt werd ich... zerquetscht?', 28153),
(157025, 'deDE', 'Ich werd Euch zerquetsch\'n, kleine Made!', 'Ich werd Euch zerquetsch\'n, kleine Made!', 28153),
(157024, 'deDE', 'Holt mich hier raus!', 'Holt mich hier raus!', 28153),
(157023, 'deDE', 'Das Terrorhornkalb brüllt und läuft zu seiner Mutter!', 'Das Terrorhornkalb brüllt und läuft zu seiner Mutter!', 28153),
(157022, 'deDE', 'Bringt mich hin!', 'Bringt mich hin!', 28153),
(157021, 'deDE', 'Soll ich Euch mitnehmen?', 'Soll ich Euch mitnehmen?', 28153),
(157020, 'deDE', '', 'Elkmar hat Euch gut ausgebildet. Ich weiß, er wäre stolz auf Euch.', 28153),
(157019, 'deDE', '', 'Ich danke Euch, Herrin. Ich werde Euch nicht enttäuschen.', 28153),
(157018, 'deDE', '', 'Ich ernenne Euch hiermit zum Marschall und übergebe Euch das Kommando der Kronsteigwache.', 28153),
(157017, 'deDE', '', 'Aber Drustvar benötigt nun Eure Dienste in höherer Funktion.', 28153),
(157016, 'deDE', '', 'Inquisitorin Morgenlicht, Ihr habt unsere Erwartungen übertroffen – habt Mitgefühl, Mut, Klugheit und Führungsstärke bewiesen.', 28153),
(157015, 'deDE', '', 'Wir alle haben Verluste erlitten, aber das Feuer der Hoffnung brennt hell in uns.', 28153),
(157014, 'deDE', 'Nicht persönlich gemeint.', 'Nicht persönlich gemeint.', 28153),
(157013, 'deDE', 'Unsere Feinde kontrollieren den Zirkel der Elemente... vorerst.', 'Unsere Feinde kontrollieren den Zirkel der Elemente... vorerst.', 28153),
(157012, 'deDE', 'Ich sehe das Banner der Horde am Zirkel der Elemente!', 'Ich sehe das Banner der Horde am Zirkel der Elemente!', 28153),
(157011, 'deDE', 'Die Horde kontrolliert den Zirkel der Elemente!', 'Die Horde kontrolliert den Zirkel der Elemente!', 28153),
(157010, 'deDE', 'Der Zirkel der Elemente zeigt unser Banner!', 'Der Zirkel der Elemente zeigt unser Banner!', 28153),
(157009, 'deDE', 'Unsere Truppen kontrollieren den Zirkel der Elemente.', 'Unsere Truppen kontrollieren den Zirkel der Elemente.', 28153),
(157008, 'deDE', 'Der Zirkel der Elemente verbleibt unter unserer Kontrolle.', 'Der Zirkel der Elemente verbleibt unter unserer Kontrolle.', 28153),
(157007, 'deDE', 'Neuhof zeigt das Banner der Horde... vorerst.', 'Neuhof zeigt das Banner der Horde... vorerst.', 28153),
(157006, 'deDE', 'Diese Monster glauben, Neuhof kontrollieren zu können? Wir werden es ihnen zeigen...', 'Diese Monster glauben, Neuhof kontrollieren zu können? Wir werden es ihnen zeigen...', 28153),
(157005, 'deDE', 'Diese Scheusale können Neuhof nicht ewig halten.', 'Diese Scheusale können Neuhof nicht ewig halten.', 28153),
(157004, 'deDE', 'Unsere Truppen haben die Kontrolle über Neuhof.', 'Unsere Truppen haben die Kontrolle über Neuhof.', 28153),
(157003, 'deDE', 'Wir haben Neuhof unter Kontrolle.', 'Wir haben Neuhof unter Kontrolle.', 28153),
(157002, 'deDE', 'Wir scheinen Neuhof unter Kontrolle zu haben. Und so sollte es auch bleiben.', 'Wir scheinen Neuhof unter Kontrolle zu haben. Und so sollte es auch bleiben.', 28153),
(157001, 'deDE', 'Der Loa der Könige ist gefallen. Wir müssen Umsicht beweisen, wenn wir eine neue Jagd beginnen.\n\nRastakhan ist schwer verwundet und altert schnell. Nur die Macht von Rezan kann Bwonsamdi zurückhalten. Ich würde ihm meine Macht anbieten, aber es steht mir nicht zu, den Loa des Todes herauszufordern.', '', 28153),
(157000, 'deDE', 'Was denn, meine Dame?', '', 28153),
(156999, 'deDE', '', 'Abrichterin L\'kala schaut den Goblin neben ihr misstrauisch an.', 28153),
(156998, 'deDE', '', 'Euer Junges is\' nach so viel\'n Kämpfen wohl müde. Hier is\' es in Sicherheit. Ich werd mich selbst drum kümmern.', 28153),
(156996, 'deDE', 'Das Terrorhornjungtier gähnt und schließt seine Augen.', 'Das Terrorhornjungtier gähnt und schließt seine Augen.', 28153),
(156995, 'deDE', 'Zeit zu gehen!', 'Zeit zu gehen!', 28153),
(156994, 'deDE', 'Ich fühl mich, als hätt mir jemand die Seele aus\'m Leib geriss\'n.', '', 28153),
(156993, 'deDE', 'Das war verdammt knapp! Vielen Dank für die Hilfe!', 'Das war verdammt knapp! Vielen Dank für die Hilfe!', 28153),
(156992, 'deDE', 'Vielen Dank für die Hilfe! Aus irgendeinem Grund haben meine Schleim-weg-Schlappen nicht funktioniert.', 'Vielen Dank für die Hilfe! Aus irgendeinem Grund haben meine Schleim-weg-Schlappen nicht funktioniert.', 28153),
(156991, 'deDE', 'Ich danke Euch! Sobald ich zurück bin, werde ich Beschwerde einlegen. Die logistischen Zumutungen dieser Expedition übertreffen unsere zuvor besprochenen Erwartungen bei Weitem.', 'Ich danke Euch! Sobald ich zurück bin, werde ich Beschwerde einlegen. Die logistischen Zumutungen dieser Expedition übertreffen unsere zuvor besprochenen Erwartungen bei Weitem.', 28153),
(156990, 'deDE', 'Oh, Mann, danach werde ich mich eine Woche lang in den Sanitron legen!', 'Oh, Mann, danach werde ich mich eine Woche lang in den Sanitron legen!', 28153),
(156989, 'deDE', 'Das war eine zähe Angelegenheit. Ihr habt meinen Dank!', 'Das war eine zähe Angelegenheit. Ihr habt meinen Dank!', 28153),
(156988, 'deDE', 'Möge das Meer das Erz segn\'n und nich\' zurückfordern, was schon gesegnet wurde.', 'Möge das Meer das Erz segn\'n und nich\' zurückfordern, was schon gesegnet wurde.', 28153),
(156987, 'deDE', 'Könntet Ihr diese Sturmsilberbarren segnen?', 'Könntet Ihr diese Sturmsilberbarren segnen?', 28153),
(156986, 'deDE', 'Niemand sollte die Verlassenen als eine zweite Chance für irgendetwas ansehen.', '', 28153),
(156985, 'deDE', 'Mir gefällt nicht, was Ihr da andeutet, Zelling.', '', 28153),
(156984, 'deDE', 'Jawohl! Die Kraft der Krustentiere!', '', 28153),
(156983, 'deDE', 'Ihr seht aus, als wärt Ihr auf Schere-reien aus. Kapiert? Scheren wie Krebsscheren! Ich werde gewinnen!', '', 28153),
(156982, 'deDE', 'Das ist nicht das Ende der Geschichte! Ihr werdet noch von Kapitän Hermes und seinem Kampfkrebstrio hören!', '', 28153),
(156981, 'deDE', 'Wie ist das möglich?!', '', 28153),
(156980, 'deDE', 'Endlich jemand, der sich stellt!', '', 28153),
(156979, 'deDE', 'Setzt die Segel, auf ins Sturmsangtal!', 'Setzt die Segel, auf ins Sturmsangtal!', 28153),
(156978, 'deDE', 'Setzt die Segel, auf zum Tiragardesund!', 'Setzt die Segel, auf zum Tiragardesund!', 28153),
(156977, 'deDE', 'Setzt die Segel, auf nach Drustvar!', 'Setzt die Segel, auf nach Drustvar!', 28153),
(156976, 'deDE', '...Was denn?', '', 28153),
(156974, 'deDE', 'Dieser Bursche im roten Hemd da drüben hat mir gesagt, ich bin nicht \"im Kanon\". Ich muss doch sehr bitten! Die Mannschaft schätzt meinen Bariton in unseren mehrstimmigen Shanties!', '', 28153),
(156973, 'deDE', 'Könnt Ihr mich noch mal über Kul Tiras aufklären?', 'Könnt Ihr mich noch mal über Kul Tiras aufklären?', 28153),
(156972, 'deDE', 'Wir werden die Dinge wieder ins Lot bringen.', '', 28153),
(156971, 'deDE', '', 'Hey, wie kann ich helfen?', 28153),
(156970, 'deDE', 'Nicht schlecht! Da habt Ihr ordentlich Kompost draus gemacht.', '', 28153),
(156969, 'deDE', 'Ruft die See Euch ebenso, wie sie mich ruft?', '', 28153),
(156968, 'deDE', 'Ich muss wissen, ob meine Familie in Sicherheit ist! <hust>', '', 28153),
(156967, 'deDE', '', 'Ihr sagte Euch doch, dass Ihr meine Geduld...', 28153),
(156966, 'deDE', 'Mir wurde von einer Art schrecklichem Pflanzenmonster in der Nähe des Krals berichtet. Unsere mechanischen Landarbeiter sollten kurzen Prozess damit machen.', '', 28153),
(156965, 'deDE', 'Möge die See Euch immer nach Hause tragen.', '', 28153),
(156964, 'deDE', 'Was begehrt Ihr von Haus Prachtmeer?', '', 28153),
(156963, 'deDE', 'Setzt die Segel, auf nach Zuldazar!', 'Setzt die Segel, auf nach Zuldazar!', 28153),
(156962, 'deDE', 'Setzt die Segel, auf nach Nazmir!', 'Setzt die Segel, auf nach Nazmir!', 28153),
(156961, 'deDE', 'Gemeinsam sind wir stark.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'deDE', 'Ich werde das Andenken meines Vaters ehren!', '', 28153),
(156959, 'deDE', 'Ich habe Jahre auf See damit verbracht, die tödlichsten Einsiedlerkrebse dieser Welt zu sammeln. Wollt Ihr einen Kampf wagen oder habt Ihr Angst vor einer Pleite?', '', 28153),
(156958, 'deDE', 'Gute Arbeit. Wir werden unsere besten Forscher mit den Studien dieser Schriften beauftragen. Ich danke Euch.', '', 28153),
(156957, 'deDE', 'Unsere Kampfmagier haben bei den Gefallenen Schriftrollen mit tortollanischer Magie entdeckt. Wir müssen sie an uns nehmen, bevor die Horde es tut. Bergt so viele, wie möglich.', '', 28153),
(156956, 'deDE', 'Die Allianz hat Burg Stromgarde zurückerobert!', 'Die Allianz hat Burg Stromgarde zurückerobert!', 28153),
(156955, 'deDE', 'Heda, $n! Hier drüben!', '', 28153),
(156954, 'deDE', 'Ahoi, $p. Ich hab gehört, Ihr seid jetzt ganz dicke mit Kiro un\' den Vulpera.\n\nWir hab\'n keine Zeit für Plauderei\'n, also muss Kiros Wort mir genüg\'n.\n\nWenn Ihr \'ne lütte Kaperfahrt machen wollt, seid Ihr in unser Mannschaft willkomm\'n.\n\nSpringt ins Boot, wenn Ihr bereit seid. Dann könn\'n wir die Segel setz\'n.', '', 28153),
(156953, 'deDE', 'Interessant... Ich lasse die Schriftrolle sofort von unseren Magiern untersuchen. Ich danke Euch!', '', 28153),
(156952, 'deDE', 'Ahoi, $p! Schön, Euch wiederzuseh\'n.\n\nSeid Ihr bereit für \'ne lütte Kaperfahrt? Zem\'lan hat seine Leute auf die Schiffe beordert un\' das macht sie zu leicht\'n Zielen für uns... wenn man richtig ziel\'n kann.\n\nIch weiß, was Ihr draufhabt. Ihr könnt mit diesen üblen Skeletten kurz\'n Prozess mach\'n.\n\nSpringt ins Boot, wenn Ihr bereit seid.', '', 28153),
(156951, 'deDE', 'Ich werde an Bord der \"Die Erlösenden Winde\" zurückkehren. Lasst die Großadmiralin wissen, wenn Ihr bereit seid, nach Boralus zurückzukehren.', '', 28153),
(156950, 'deDE', 'Ich habe Jahre auf See damit verbracht, die wildesten Kampfkrebse zu fangen. Wollt Ihr mal sehen, wie sie kurzen Prozess mit Euren Tierchen machen?', '', 28153),
(156949, 'deDE', '$n! Was kann ich für Euch tun?', '', 28153),
(156948, 'deDE', 'Was\'n das...?', 'Was\'n das...?', 28153),
(156947, 'deDE', '$n! Schön, Euch wiederzusehen. Es ist schon eine Weile her, dass ich unter Euch auf Draenor gedient habe.', '', 28153),
(156946, 'deDE', 'Die Kul Tiraner werden lernen, was Angst bedeutet!', '', 28153),
(156945, 'deDE', 'Was soll\'n das sein...', 'Was soll\'n das sein...', 28153),
(156944, 'deDE', 'Argh! Ist das bitter!', 'Argh! Ist das bitter!', 28153),
(156943, 'deDE', 'Schmeckt nach... Haken...', 'Schmeckt nach... Haken...', 28153),
(156942, 'deDE', 'Was soll das? Bin ich etwa ein... <hick!>... Vrykul?', 'Was soll das? Bin ich etwa ein... <hick!>... Vrykul?', 28153),
(156941, 'deDE', 'Ich... hasse... <hick!> helles Bier...', 'Ich... hasse... <hick!> helles Bier...', 28153),
(156940, 'deDE', 'Öffnet ein Portal, um unsere Truppen herzubringen.', 'Öffnet ein Portal, um unsere Truppen herzubringen.', 28153),
(156939, 'deDE', 'Es ist mir eine Ehre, der Horde als Teil meiner fortlaufenden Telemantiestudien unter Oculeth zu dienen.\n\nUnd es wird mir auch eine Ehre sein, diesen Ort zu verlassen, sobald ich diese Aufgabe abgeschlossen habe.', '', 28153),
(156938, 'deDE', 'Meine Hunde... haben... gebellt... und nicht gebissen...', 'Meine Hunde... haben... gebellt... und nicht gebissen...', 28153),
(156937, 'deDE', 'Perfekt! Unsere Beute ist zu uns gekommen!', 'Perfekt! Unsere Beute ist zu uns gekommen!', 28153),
(156936, 'deDE', 'Erfüllt dieses Amulett mit Macht... das ist womöglich der einzige Weg, sie zu retten!', '', 28153),
(156935, 'deDE', 'Spürt Ihr das? Eine Art... Beben...', '', 28153),
(156934, 'deDE', '', 'Subjekt: Azeroth. Schwere Arrhythmie entdeckt.\n\nVitalzeichen außerhalb akzeptabler Parameter.\n\nVersuche, Ereignisbericht zu aktualisieren...\n\nFEHLER. FEHLER. FEHLER. FEHLER.', 28153),
(156933, 'deDE', 'Oho! Das ist aber starkes Zeug!', '', 28153),
(156932, 'deDE', 'Hmm... erinnert mich an meine Zeit... als Bergarbeiter... Der Trick war, mit der Spitzhacke im richtigen Winkel ins... Erz zu schlagen... damit es...', '', 28153),
(156931, 'deDE', '', 'WARNUNG: Mehrfache Eindämmungsbrüche registriert.\n\nEmpfehle Bereinigung folgender Einrichtungen:\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld... Uld... Uld... Uld...', 28153),
(156930, 'deDE', 'Argh... Das vertrag ich aber nicht gut...', '', 28153),
(156929, 'deDE', 'Meinen Berechnungen zufolge haben wir 2,539, Periode versteht sich, Prozent unserer Erfolgschance verloren. Wir müssen uns mit den Reparaturen beeilen!', 'Meinen Berechnungen zufolge haben wir 2,539, Periode versteht sich, Prozent unserer Erfolgschance verloren. Wir müssen uns mit den Reparaturen beeilen!', 28153),
(156928, 'deDE', 'Los schon! Repariert endlich diese Panzer! Wir fallen im Zeitplan zurück!', 'Los schon! Repariert endlich diese Panzer! Wir fallen im Zeitplan zurück!', 28153),
(156927, 'deDE', 'Beeilt Euch, Leute! Wir haben nur ein kurzes Zeitfenster, um die Belagerungspanzer einzusetzen, bevor die Horde entdeckt, dass wir hier sind.', 'Beeilt Euch, Leute! Wir haben nur ein kurzes Zeitfenster, um die Belagerungspanzer einzusetzen, bevor die Horde entdeckt, dass wir hier sind.', 28153),
(156926, 'deDE', 'Bietet schaumigen Majorskaffee an.', 'Bietet schaumigen Majorskaffee an.', 28153),
(156925, 'deDE', 'Bietet \"Aurora Borealis\" an.', 'Bietet \"Aurora Borealis\" an.', 28153),
(156924, 'deDE', 'Bietet bitteren Finsterwurzelwodka an.', 'Bietet bitteren Finsterwurzelwodka an.', 28153),
(156923, 'deDE', 'Bietet Brennadamer Apfelbranntwein an.', 'Bietet Brennadamer Apfelbranntwein an.', 28153),
(156922, 'deDE', 'Bietet Hakenkapschnaps an.', 'Bietet Hakenkapschnaps an.', 28153),
(156921, 'deDE', 'Bietet Mildenhallmet an.', 'Bietet Mildenhallmet an.', 28153),
(156920, 'deDE', 'Bietet Fahlhain Hell an.', 'Bietet Fahlhain Hell an.', 28153),
(156919, 'deDE', 'Bietet Schwarzzahnblutwein an.', 'Bietet Schwarzzahnblutwein an.', 28153),
(156918, 'deDE', 'Bringt uns nach Boralus zurück.', 'Bringt uns nach Boralus zurück.', 28153),
(156917, 'deDE', '', 'Oh, Mannomann! Ich werde Euch nicht im Stich lassen, $n! Das schwöre ich!', 28153),
(156916, 'deDE', '', 'Hallo? Verzeihung, $gverehrter:verehrte; $n! Hier drüben!', 28153),
(156915, 'deDE', 'Oh, wolltet Ihr etwas von mir?', '', 28153),
(156914, 'deDE', 'Worauf sollten wir uns konzentrieren?', '', 28153),
(156913, 'deDE', 'Bringt uns zurück nach Zuldazar.', 'Bringt uns zurück nach Zuldazar.', 28153),
(156912, 'deDE', '', 'Auf der Suche nach einem Boot? Wollt Ihr eine Nachricht übermitteln?\n\nODER BRAUCHT IHR HILFE, JEMANDEN ABZUSTECHEN?', 28153),
(156911, 'deDE', 'Geht weg, Mann... Seht Ihr nich\', dass ich... <hick!>... beschäftigt bin?', '', 28153),
(156910, 'deDE', '', 'Subjekt: Azeroth.\n\nWARNUNG: Katastrophales Systemversagen.\n\nPlanetenintegrität bei...\n\nwird ermittelt... wird ermittelt... wird ermittelt...', 28153),
(156909, 'deDE', 'Das war nicht Teil meiner Berechnungen...', 'Das war nicht Teil meiner Berechnungen...', 28153),
(156908, 'deDE', 'Meinen Berechnungen zufolge sind Eure Erfolgschancen... gleich null!', 'Meinen Berechnungen zufolge sind Eure Erfolgschancen... gleich null!', 28153),
(156907, 'deDE', '', 'Dieser Stacheleber hatte ganz schön Mojo, aber trotzdem nich\' den Hauch von \'ner Chance gegen Euch.', 28153),
(156906, 'deDE', '', 'Ein Stacheleberschamane lässt die Erde selbst geg\'n uns aufmarschier\'n. Kümmert Euch um diese neue Bedrohung, bevor sie unsre Pläne gefährdet.', 28153),
(156905, 'deDE', 'Heute Nacht werde ich wieder ruhig schlafen können. Gut, dass ein paar weniger Felsbrocken im Sturmsangtal herumlaufen.', '', 28153),
(156904, 'deDE', 'Das wilde Pterrorküken kreischt alarmiert auf!', 'Das wilde Pterrorküken kreischt alarmiert auf!', 28153),
(156903, 'deDE', 'Da ist ein Erdenrufer der Stacheleber, der eine Armee von Elementaren ruft. Dünnt ihre Reihen aus und macht ihn dann selbst einen Kopf kürzer!', '', 28153),
(156902, 'deDE', 'Ich danke Euch. Ich dachte, ich wäre verloren.', 'Ich danke Euch. Ich dachte, ich wäre verloren.', 28153),
(156901, 'deDE', 'Ich bin dankbar, dass es noch gute Leute auf dieser Welt gibt.', 'Ich bin dankbar, dass es noch gute Leute auf dieser Welt gibt.', 28153),
(156900, 'deDE', 'Danke! Von hier aus schaffe ich es alleine.', 'Danke! Von hier aus schaffe ich es alleine.', 28153),
(156899, 'deDE', 'Rächt diejenigen, die nicht gerettet werden konnten.', 'Rächt diejenigen, die nicht gerettet werden konnten.', 28153),
(156898, 'deDE', 'Ihr könnt Euch nicht vorstellen, was sie uns angetan haben...', 'Ihr könnt Euch nicht vorstellen, was sie uns angetan haben...', 28153),
(156897, 'deDE', 'Ihr habt mir das Leben gerettet!', 'Ihr habt mir das Leben gerettet!', 28153),
(156896, 'deDE', 'Habt Dank.', 'Habt Dank.', 28153),
(156895, 'deDE', 'Ich stehe in Eurer Schuld.', 'Ich stehe in Eurer Schuld.', 28153),
(156894, 'deDE', 'Eure Tapferkeit sucht ihresgleichen.', 'Eure Tapferkeit sucht ihresgleichen.', 28153),
(156893, 'deDE', 'Eure Güte werde ich nie vergessen.', 'Eure Güte werde ich nie vergessen.', 28153),
(156892, 'deDE', 'Ihr kommt genau zur rechten Zeit!', 'Ihr kommt genau zur rechten Zeit!', 28153),
(156891, 'deDE', 'Euer Mitgefühl wird nicht in Vergessenheit geraten.', 'Euer Mitgefühl wird nicht in Vergessenheit geraten.', 28153),
(156890, 'deDE', 'Ich schulde Euch mein Leben.', 'Ich schulde Euch mein Leben.', 28153),
(156889, 'deDE', 'Ich kehre besser in den Kampf zurück.', 'Ich kehre besser in den Kampf zurück.', 28153),
(156888, 'deDE', 'Alles rühren, bis es ganz sämig ist!', '', 28153),
(156887, 'deDE', 'Gut vermischen!', '', 28153),
(156886, 'deDE', 'Und jetzt Hitze drauf!', '', 28153),
(156885, 'deDE', 'Und jetzt eine extra Prise Geschmack!', '', 28153),
(156884, 'deDE', 'Eins nach dem anderen!', '', 28153),
(156883, 'deDE', 'Dieses Tal ist es wert, gerettet zu werden.', '', 28153),
(156882, 'deDE', 'Habt Ihr irgendwelche Vorräte übrig?', 'Habt Ihr irgendwelche Vorräte übrig?', 28153),
(156881, 'deDE', 'Rezan... er... er\'s tot. Das... Ding da is\' kein Loa.', '', 28153),
(156880, 'deDE', 'Uff! Diese Kammer ist verloren, $n. Sie hält nicht mehr lange stand!', '', 28153),
(156879, 'deDE', 'Kul Tiras ist in großer Gefahr, Magni. Aber ich vermute, Ihr seid aus... anderen Gründen hier.', '', 28153),
(156878, 'deDE', '', 'Un\' wo is\' jetzt meine Angel? Ich schwör, dass sie grade eben noch da war.', 28153),
(156877, 'deDE', '', 'Hier kann man gut jag\'n un\' fisch\'n, wenn man weiß, wo man hinmuss.', 28153),
(156876, 'deDE', '<Das brüchige Holz ächzt und knirscht, während sanfte Windböen gegen die Wagenseite drücken.\n\nEines der Räder scheint festzustecken.>', '', 28153),
(156875, 'deDE', '<Gebt dem Wagen einen Schubs.>', '<Gebt dem Wagen einen Schubs.>', 28153),
(156874, 'deDE', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tIhr seid nah am Hordenschiff. Passt auf!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tIhr seid nah am Hordenschiff. Passt auf!', 28153),
(156873, 'deDE', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tIhr seid nah am Allianzschiff. Passt auf!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tIhr seid nah am Allianzschiff. Passt auf!', 28153),
(156872, 'deDE', '', 'Die Mauer muss fallen, das Meer wird zurückkehren.', 28153),
(156871, 'deDE', '$n... Macht Euch an anderer Stelle nützlich. Ich lasse Euch rufen, wenn ich Euch wieder brauche.', '', 28153),
(156870, 'deDE', 'Lilian. Stein. Kommt und helft mir, einen dieser... Gezeitenweisen zu finden.', '', 28153),
(156869, 'deDE', 'Ich habe diese ständigen Rückschläge so satt.', '', 28153),
(156868, 'deDE', 'Und, $n? Was habt Ihr gefunden? Gebt mal her.', '', 28153),
(156867, 'deDE', 'Nun denn, Ihr wisst, was zu tun ist. Die Plattform teleportiert Euch zurück zu Euren Verbündeten. Viel Glück... uns allen.', '', 28153),
(156866, 'deDE', 'Ich werde nach Wegen suchen, die Wunden zu heilen, die Azeroth erlitten hat. Wenn ich Eure Hilfe brauche, erreiche ich Euch über diesen Talisman.', '', 28153),
(156865, 'deDE', 'Tragt dieses Amulett nah am Herzen, $n. In dunklen Zeiten wird es Euch den Weg weisen.', '', 28153),
(156864, 'deDE', 'Dann müssen wir also nur etwas finden, das uns zu ihm führt.', '', 28153),
(156863, 'deDE', '', 'Die Festungsmauern sollen unter Euren Schlägen brechen.', 28153),
(156862, 'deDE', '', 'Ihr greift die Mauern auf das Signal hin an, Skoloth.', 28153),
(156861, 'deDE', '', 'Eure Dienste sollen entlohnt werden.', 28153),
(156860, 'deDE', '', 'Amalia, erzählt Nathanos hier von den Gezeitenweisen.', 28153),
(156859, 'deDE', '', 'Kann helfen... Schiffswrack... suchen...', 28153),
(156858, 'deDE', '', 'Gezeitenweisen... Priester... des Meeres...', 28153),
(156857, 'deDE', '', 'Ah, ich glaube, das wird kein Problem.', 28153),
(156856, 'deDE', 'Verschollen auf See?! Wir brauchen seinen Leichnam!', '', 28153),
(156855, 'deDE', '', 'Marschall M. Valentin... Sieger des Zweiten Krieges... verschollen auf See...', 28153),
(156854, 'deDE', 'Ich möchte zum Tiragardesund zurückkehren.', 'Ich möchte zum Tiragardesund zurückkehren.', 28153),
(156853, 'deDE', 'Ich sorge für ordentlich Wind in den Segeln, während Ihr da rausgeht und Eure Angelegenheiten erledigt.', '', 28153),
(156851, 'deDE', 'WO IST DER LEICHNAM?!', '', 28153),
(156850, 'deDE', 'Moment.... Was ist das?', '', 28153),
(156849, 'deDE', 'Valentin. Wir hatten ja schon lange nicht mehr das Vergnügen.', '', 28153),
(156848, 'deDE', 'Wir sollten Valentin nicht warten lassen.', '', 28153),
(156847, 'deDE', 'Säbeltron aktivier... argh!', '', 28153),
(156846, 'deDE', 'Was... wir sind doch noch gar nicht bereit!', '', 28153),
(156845, 'deDE', 'Nichts widersteht Säbeltron!', '', 28153),
(156844, 'deDE', 'Fünf Minikatzen ergeben zusammen eine Superkatze!', '', 28153),
(156843, 'deDE', 'Eure Umarmung wird dieses Schiff nicht länger beschützen.', '', 28153),
(156842, 'deDE', 'Hinfort, elende Dunkelheit.', '', 28153),
(156841, 'deDE', 'Mögen die Gezeiten Euer verderbtes Fleisch verschlingen.', '', 28153),
(156840, 'deDE', '', 'Sie dürfen Dot nichts tun!', 28153),
(156839, 'deDE', '', 'Hiiilfe!', 28153),
(156838, 'deDE', 'Setzt die Segel, auf nach Vol\'dun!', 'Setzt die Segel, auf nach Vol\'dun!', 28153),
(156837, 'deDE', 'Das Ding ist vielleicht tot, aber Alpträume werd ich davon trotzdem kriegen.', '', 28153),
(156836, 'deDE', 'Es ist ein... äääh... Ding! Tötet es! Verbrennt es! Tut was!', '', 28153),
(156835, 'deDE', '|A:Warfront-AllianceWave3:25:23:0:0|aEin Angriffstrupp der Allianz wurde entsandt!', '|A:Warfront-AllianceWave3:25:23:0:0|aEin Angriffstrupp der Allianz wurde entsandt!', 28153),
(156834, 'deDE', 'Die Sethrak haben Meerahs Wagen in den Dünen entdeckt. Sie ist ganz allein und könnte bei ihrer Abwehr ein wenig Hilfe gebrauchen, falls sie angreifen.', '', 28153),
(156833, 'deDE', '', 'Wie Ihr befehlt. Auf Geheiß der Dunklen Fürstin.', 28153),
(156832, 'deDE', '', 'Nehmt den Mann mit. Er hat entschieden, zum Verlassenen zu werden.', 28153),
(156831, 'deDE', 'Lilian. Wir können andere Gezeitenweisen finden. Ihr wisst, dass seine Familie ihn nicht akzeptieren wird.', '', 28153),
(156830, 'deDE', '', 'Lilian Voss. Weshalb habt Ihr mich gerufen?', 28153),
(156829, 'deDE', 'Eine geringfügige Unannehmlichkeit. Sorgt dafür, dass es keinen Einfluss auf unseren Plan nimmt.', '', 28153),
(156828, 'deDE', 'Sehnen trifft es nicht ganz... Ich will es vielmehr erdulden, wenn ich damit meiner Familie helfen kann.', '', 28153),
(156827, 'deDE', '', 'In Schmerzen.', 28153),
(156826, 'deDE', 'Aber ein Teil von Euch hat überlebt, nicht wahr?', '', 28153),
(156825, 'deDE', '', 'Hoffen wir, dass Ihr lange genug lebt, um uns bei der Suche nach Valentin zu helfen.', 28153),
(156824, 'deDE', 'Auf geht\'s!', 'Auf geht\'s!', 28153),
(156823, 'deDE', '', 'Es können sofort zusätzliche Truppen der Horde rekrutiert werden. Ein Wort von Euch genügt.', 28153),
(156822, 'deDE', 'Hmpf. Enttäuscht mich nicht.', '', 28153),
(156821, 'deDE', '', 'Ich werde sie holen, Nathanos. Geht ohne uns weiter.', 28153),
(156820, 'deDE', '', 'Halt!', 28153),
(156819, 'deDE', '', 'AAHHHH!', 28153),
(156818, 'deDE', '', 'Ich... Ich kann nicht...', 28153),
(156817, 'deDE', '', 'Das nenne ich einen guten Anfang. Mal sehen, was Ihr noch für uns tun könnt.', 28153),
(156816, 'deDE', 'Bei Weisenwall halten sich Truppen der Allianz und von Kul Tiras auf. Sie warten auf weitere Verstärkung und sind zurzeit verwundbar gegenüber Angriffen.', '', 28153),
(156815, 'deDE', 'Ist meine Familie in Sicherheit?', '', 28153),
(156814, 'deDE', '', 'Gut. Dann beweist uns, welchen Nutzen Ihr für die Horde habt. Danach entscheiden wir, wie lange Ihr noch dieses Leben leben werdet.', 28153),
(156813, 'deDE', 'Sie sind in Sicherheit. Helft uns, dann werden wir dies weiterhin gewährleisten.', '', 28153),
(156812, 'deDE', '<Hust> Ich... Ich will tun, was ich kann, Fräulein Voss. Ihr wollt doch jemanden oder irgendetwas ausfindig machen, ja? Lasst mich mal sehen, was ich ohne mein Buch erreichen kann...', '', 28153),
(156811, 'deDE', '', 'Strapaziert besser nicht meine Geduld, sonst werdet Ihr Euch wünschen, dass die Krankheit Euch schon dahingerafft hätte. Ich muss herausfinden, wie gut Eure Magie funktioniert, bevor wir weitermachen können.', 28153),
(156810, 'deDE', 'Verehrte Lilian Voss, leidet Ihr, auch nachdem Ihr zurückgebracht wurdet, weiterhin an Krankheiten aus Eurem vorherigen Leben?', '', 28153),
(156809, 'deDE', '', 'Lilian Voss. Und ich bin diejenige, die hier die Fragen stellt. Könnt Ihr Leute aufspüren? Oder Objekte?', 28153),
(156808, 'deDE', 'Jemand von den Verlassenen. Vielleicht ist das ein <hust> Zeichen. Sagt, meine Dame...?', '', 28153),
(156807, 'deDE', '', '$n hat im Grunde recht. Euch geschieht nichts, wenn Ihr uns helft. Am besten noch vor Eurem Tod.', 28153),
(156806, 'deDE', 'Möge die Dunkle Fürstin über Euch wachen.', '', 28153),
(156805, 'deDE', 'Ich benötige Verstärkung.', 'Ich benötige Verstärkung.', 28153),
(156804, 'deDE', 'Ihr seid auf der Suche nach Verstärkung? Gebt den Befehl und ich werde den Transport nach Sturmwind arrangieren.', '', 28153),
(156803, 'deDE', 'Wir haben nicht viel Zeit. Was brauchen wir?', '', 28153),
(156802, 'deDE', 'Ihr seid nicht totzukriegen... im Gegensatz zu Euren Feinden.', '', 28153),
(156801, 'deDE', 'Wir folgen hier keinem bestimmten Plan, also kümmert Euch einfach um diese Bedrohung und lasst Euch nicht umbringen.', '', 28153),
(156799, 'deDE', '%s knabbert am frischen Futter.', '', 28153),
(156798, 'deDE', '%s kaut begeistert auf den grünen Blättern.', '', 28153),
(156797, 'deDE', '%s vergräbt seine Schnauze im Essen.', '', 28153),
(156796, 'deDE', 'Ich werde Euch den Kopf zertrümmern!', 'Ich werde Euch den Kopf zertrümmern!', 28153),
(156795, 'deDE', 'Wer will als Nächstes sterben?!', 'Wer will als Nächstes sterben?!', 28153),
(156794, 'deDE', 'Auf geht\'s!', 'Auf geht\'s!', 28153),
(156793, 'deDE', '[VIDEOSEQUENZ] - Jaina trifft ein! Ihre Truppen haben es geschafft, durch die Mauern von Burg Lordaeron zu brechen! Und das war *so-was-von* cool.', '[VIDEOSEQUENZ] - Jaina trifft ein! Ihre Truppen haben es geschafft, durch die Mauern von Burg Lordaeron zu brechen! Und das war *so-was-von* cool.', 28153),
(156792, 'deDE', '[VIDEOSEQUENZ] - Sylvanas wartet im Thronsaal, als Anduin eintrifft. Anduin bietet ihr die Möglichkeit der Kapitulation. Stattdessen jagt sie aber die ganze Stadt in die Luft. Was hätte man anderes erwarten sollen?', '[VIDEOSEQUENZ] - Sylvanas wartet im Thronsaal, als Anduin eintrifft. Anduin bietet ihr die Möglichkeit der Kapitulation. Stattdessen jagt sie aber die ganze Stadt in die Luft. Was hätte man anderes erwarten sollen?', 28153),
(156791, 'deDE', '', 'Wenn ich Kul Tiras dazu bringen könnte, wieder der Allianz...', 28153),
(156790, 'deDE', '', 'Mein Volk verfügt über die mächtigste Seestreitmacht in ganz Azeroth.', 28153),
(156789, 'deDE', '', 'Ein einfacher Zauber, solange der Betroffene kooperiert.', 28153),
(156788, 'deDE', '', 'Hier, trinkt das.', 28153),
(156787, 'deDE', '', 'Ganz ruhig, Amalia. Nur eine Sekunde...', 28153),
(156786, 'deDE', 'Ich bin hier, um Euch um Hilfe zu bitten, nicht, um Euch zu töten.', 'Ich bin hier, um Euch um Hilfe zu bitten, nicht, um Euch zu töten.', 28153),
(156785, 'deDE', '<hust> Die Horde. Ich dachte, ich würde hier in Frieden sterben dürfen.\n\nAlso, worauf wartet Ihr?', '', 28153),
(156784, 'deDE', '', 'Hey, $n, beim Schredder.', 28153),
(156783, 'deDE', 'Wir müssen uns beeilen, wenn wir die Hilfe dieses Gezeitenweisen nutzen wollen.', '', 28153),
(156782, 'deDE', '', 'Was Ihr tun könnt, kann auch nicht schlimmer sein, als die Krankheit... Er ist Richtung Osten gegangen, um in Ruhe und fern der Kinder zu sterben. Und jetzt lasst uns bitte in Ruhe.', 28153),
(156781, 'deDE', 'Ich will nur wissen, wo Euer Ehemann ist. Euch und Eurer Familie wird nichts geschehen.', '', 28153),
(156780, 'deDE', '', 'Die Horde... Seid Ihr hier, um mir noch mehr zu nehmen? Mein Mann stirbt, ich habe kein Geld... Lasst nur bitte meine Kinder in Ruhe!', 28153),
(156779, 'deDE', 'Das entbehrt jeder Ehre. Wir können einfach nur fragen. Eine weinende Mutter ist nicht unser Feind.', '', 28153),
(156778, 'deDE', 'Ihr solltet jetzt besser in Deckung gehen.', '', 28153),
(156777, 'deDE', 'Dann fahren wir mal schwere Geschütze auf.', '', 28153),
(156776, 'deDE', 'Ich komme mit dem Sandsturm!', '', 28153),
(156775, 'deDE', 'Ihr markiert das Ziel...', '', 28153),
(156774, 'deDE', 'Ich liebe meinen Job.', '', 28153),
(156773, 'deDE', 'Ha! Sieht aus, als hätte der hier den Mund zu voll genommen!', '', 28153),
(156772, 'deDE', 'Der Hund ist von der Leine!', '', 28153),
(156771, 'deDE', 'Das wird \'ne hübsche Überraschung.', '', 28153),
(156770, 'deDE', 'Hat jemand einen Rekonfigulator gerufen?', '', 28153),
(156769, 'deDE', 'Das dürfte Euch gefallen!', '', 28153),
(156768, 'deDE', 'AR-8 im Anmarsch.', '', 28153),
(156767, 'deDE', 'Haltet Euch fest, jetzt geht\'s rund.', '', 28153),
(156766, 'deDE', 'Alles bestens.', '', 28153),
(156765, 'deDE', '', 'Argghhh...', 28153),
(156764, 'deDE', '', 'Je schneller Ihr die Blüten sammeln könnt, desto schneller kann ich Amalia helfen, und dann wird sie uns auch hilfreich sein.', 28153),
(156763, 'deDE', 'Ich hab Geschichten gehört von riesigen Würmern, die sich von Fäulnis ernähren und die Oberfläche verwüsten. Wenn wir einem begegnen, müssen wir ihn töten!', '', 28153),
(156762, 'deDE', 'Danke, dass Ihr die Kinder gerettet habt. Wenn sie nächstes Mal weglaufen, wollen sie bestimmt so werden wie Ihr!', '', 28153),
(156761, 'deDE', 'Ein paar Kinder von der Totenschwemme sind weggelaufen, um Piraten zu werden, und wurden von den Eisenfluträubern gefangen genommen. Befreit sie!', '', 28153),
(156760, 'deDE', '', 'Psst... $n! Hier drüben!', 28153),
(156759, 'deDE', '', 'Ein Scheusal weniger, das mein Volk auf der Oberfläche heimsucht. Die Loa sin\' zufried\'n mit Eurer Arbeit.', 28153),
(156758, 'deDE', '', 'Ich hab\' von Würmern gehört, die sich von Fäulnis ernähr\'n und die Oberfläche verwüst\'n. Wir müssen jeden Wurm töt\'n, den wir finden!', 28153),
(156757, 'deDE', 'Hatten sie nicht Süßigkeiten versprochen?', 'Bin ich jetzt ein Pirat oder nicht?', 28153),
(156756, 'deDE', 'Hört mal, Boss, ich weiß ja, dass Ihr diese Expedition sponsert, aber Gallywix wird sicherstellen wollen, dass die Dunkle Fürstin ihren Anteil kriegt.', '', 28153),
(156755, 'deDE', 'Ich möchte zum Grabhügelfriedhof.', 'Ich möchte zum Grabhügelfriedhof.', 28153),
(156754, 'deDE', '', 'Ich habe die sichersten Raketen in ganz Kul Tiras!$b$bLasst Euch nicht vom Nachnamen täuschen.', 28153),
(156753, 'deDE', 'Rückzug! Wir kämpf\'n \'n anderma\' weiter.', '', 28153),
(156752, 'deDE', 'Zandalari! Rückzug un\' neu gruppiern! Wir knöpf\'n sie uns \'n anderma\' vor.', '', 28153),
(156751, 'deDE', 'Vernichtet die Eindringlinge!', '', 28153),
(156750, 'deDE', 'Ihr seid schwach!', '', 28153),
(156749, 'deDE', 'Euer Tod wartet!', '', 28153),
(156748, 'deDE', 'Ich bin der schreckliche Pirat Bolle! Es wird keine Überlebenden geben!', 'Ich glaub, ich hab meine Katze gesehen!', 28153),
(156747, 'deDE', 'Wagt Euch in den Sturm, damit wir dem ein Ende setzen können.', '', 28153),
(156746, 'deDE', 'Ihr gehört gar nicht zu den Piraten!', 'Sie haben gesagt, ich kriege einen Hut!', 28153),
(156745, 'deDE', 'Argh! Gebt mir etwas Rum!', 'Ich muss zum Poopdeck!', 28153),
(156744, 'deDE', '', 'Gut, Ihr müsst Euch also die Hände nicht schmutzig machen.', 28153),
(156743, 'deDE', 'Ich möchte nach Zuldazar zurückkehren.', 'Ich möchte nach Zuldazar zurückkehren.', 28153),
(156742, 'deDE', 'Ich halt die Segel oben, damit wir schneller wegkomm\'n. Geht jetz\' das Azerit hol\'n!', '', 28153),
(156741, 'deDE', '', '$n, ich kümmere mich um den Leichnam. Kehrt Ihr zu Nathanos zurück und lasst ihn wissen, dass alles nach Plan verläuft.', 28153),
(156740, 'deDE', 'Ich werde nicht mithelfen, diesen Mann zu einem Verlassenen zu machen. Kümmert Ihr Euch darum.', 'Ich werde nicht mithelfen, diesen Mann zu einem Verlassenen zu machen. Kümmert Ihr Euch darum.', 28153),
(156739, 'deDE', '', 'Ihr müsst Euch damit abfinden. Und ich werde Euch dabei helfen.', 28153),
(156738, 'deDE', 'Ich muss gar nicht gerettet werden!', 'Ich bin jetzt ein Pirat. Ich muss nicht auf Euch hören!', 28153),
(156737, 'deDE', '', 'Ihr gehört jetzt zu uns. Sie werden Euch nicht akzeptieren.', 28153),
(156736, 'deDE', 'Tötet Ihr Zelling, Lilian.', 'Tötet Ihr Zelling, Lilian.', 28153),
(156735, 'deDE', '', 'Stein, ich weiß, was Ihr durchmacht. Ihr dürft nicht zulassen, dass diese Veränderung Euch so beherrscht, wie es bei mir der Fall war.', 28153),
(156734, 'deDE', 'Das ist unfair! Ich wollte Pirat werden.', 'Gretel hat mich an die Piraten verkauft!', 28153),
(156733, 'deDE', 'Lilian, macht mit Zelling, was Ihr für richtig haltet.', 'Lilian, macht mit Zelling, was Ihr für richtig haltet.', 28153),
(156732, 'deDE', '', 'Mal schauen. Vielleicht kann es ja anders laufen... dieses eine Mal.', 28153),
(156731, 'deDE', '', 'Furchtbar. Wer nicht gleich vor Euch davonläuft, wird Euch nie wieder so behandeln wie vorher. Ihr schaut in den Spiegel und alles, was Ihr seht, ist ein Monster, das Euch in keiner Weise mehr ähnelt.', 28153),
(156730, 'deDE', 'Bitte... Ich muss mich... um meine... Familie kümmern... Egal, was es kostet.', '', 28153),
(156729, 'deDE', '', 'Wenn Ihr zu einem von uns werdet, wird man Euch scheuen. Wenn Ihr dann in den Spiegel schaut, werdet Ihr nur noch ein Monster sehen.', 28153),
(156728, 'deDE', 'Fräulein Voss, <Hust> bitte... bringt mich wieder zurück... Ich muss meiner Familie helfen... Dafür würde ich alles tun... alles...', '', 28153),
(156727, 'deDE', '', 'Was? Macht Euch nicht lächerlich. Eure Familie wird Euch für ein Monster halten!', 28153),
(156726, 'deDE', '', 'Gut. Es gibt da tatsächlich etwas, das ich wissen muss.', 28153),
(156725, 'deDE', '<Schnauf> Es... tut mir leid. Ich... kann nicht... Ich habe keine... Kraft mehr...', '', 28153),
(156724, 'deDE', '', 'Zelling! Verdammt, wir brauchen Euch lebendig!', 28153),
(156723, 'deDE', 'Ja! Endlich wird mir ewiges Leben gewährt! Ich bin bereit!', '', 28153),
(156722, 'deDE', '', 'Passt auf, Zelling. Seid Ihr wirklich ganz sicher, dass Ihr versteht, was geschehen wird?', 28153),
(156721, 'deDE', 'Gut gemacht. Ihr habt ihnen gezeigt, wie wir das hier im Tal machen.', '', 28153),
(156720, 'deDE', 'Die Späher berichten von einer neuen Bedrohung in dieser Gegend. Kümmert Euch um sie, bevor sie zu einem größeren Problem wird.', '', 28153),
(156719, 'deDE', 'Seid vorsichtig, Jaina. Möge das Licht mit Euch sein.', '', 28153),
(156718, 'deDE', '', 'Ich kehre mit der Flotte zurück... oder gar nicht.', 28153),
(156717, 'deDE', 'Das wird nicht leicht... und sicher gefährlich.', '', 28153),
(156716, 'deDE', 'Das glaube ich auch... und ich glaube an Euch.', '', 28153),
(156715, 'deDE', '', 'Und das zu klären, ist unsere einzige Hoffnung, sie zurückzugewinnen.', 28153),
(156714, 'deDE', 'Jaina, Ihr wart der Grund für ihren Austritt.', '', 28153),
(156713, 'deDE', '', 'Dann müssen wir uns selbst Verbündete suchen.', 28153),
(156710, 'deDE', '', 'Zeigt es uns... zeigt uns, was passiert ist...', 28153),
(156709, 'deDE', 'Wenn die Horde sich mit den Zandalari verbündet, haben wir nicht die Macht, sie zu stoppen.', '', 28153),
(156708, 'deDE', 'Unmöglich! Das ist einer von Sylvanas\' Tricks. Ganz sicher...', '', 28153),
(156707, 'deDE', 'Und von einer riesigen Zandalariflotte.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'deDE', 'Die Überlebenden haben von seltsamer, schrecklicher Magie gesprochen.', '', 28153),
(156705, 'deDE', 'Nur eins ist zurückgekehrt.', '', 28153),
(156704, 'deDE', 'Ich bin im Bilde. Gibt es Nachricht von den acht Verfolgerschiffen?', '', 28153),
(156703, 'deDE', 'Eine Prinzessin. Und einen Propheten.', '', 28153),
(156702, 'deDE', 'Kürzlich ist die Horde ins Verlies eingedrungen und hat zwei Zandalarigefangene befreit.', '', 28153),
(156701, 'deDE', 'Jaina, vielleicht könnt Ihr uns zeigen, was dieser Überlebende gesehen hat?', '', 28153),
(156700, 'deDE', 'In dieser Gegend wurden sehr viele Reisende getötet. Ich möchte, dass Ihr diesem Schrecken ein Ende macht.', '', 28153),
(156699, 'deDE', 'Wir sind vollzählig. Euer Bericht, Spionagemeister?', '', 28153),
(156698, 'deDE', 'Großartige Arbeit! Ich wusste, dass Ihr uns beschützen würdet.', '', 28153),
(156697, 'deDE', 'Als Nächstes will ich \'n Luftschiff. Das werd ich nach meinem Sohn benenn\'!', '', 28153),
(156696, 'deDE', 'Ich hab\'s selbst gestohl\'n und es Malas Gunst getauft... nach meiner Tochter!', '', 28153),
(156695, 'deDE', 'Wenn die sag\'n, wir krieg\'n es mit Piraten zu tun, sag ich, ich brauch \'n Piratenschiff!', '', 28153),
(156694, 'deDE', 'Die Naga haben etwas vor!', '', 28153),
(156693, 'deDE', 'Ja... die Ewigkeit...', '', 28153),
(156692, 'deDE', 'Nehmt das Seil, wenn Ihr bereit seid, zu geh\'n. Ich will Euch mein Schiff zeig\'n!', '', 28153),
(156691, 'deDE', '', 'Der Nächste, der sich beschwert, ist tot!', 28153),
(156690, 'deDE', '', 'Arbeitet gefälligst etwas schneller, Ihr erbärmlichen Bastarde!', 28153),
(156689, 'deDE', '', 'Mehr arbeiten und weniger quatschen! Das Azerit baut sich ja nicht von selbst ab!', 28153),
(156688, 'deDE', '', 'Das nennt Ihr arbeiten? Ihr Hunde könnt froh sein, dass wir Euch nicht dafür bezahlen!', 28153),
(156687, 'deDE', '', 'Zurück an die Arbeit, ihr Hunde! Und strengt Euch etwas mehr an!', 28153),
(156686, 'deDE', 'Bitte tötet mich! Schenkt mir die Ewigkeit als Verlassener!', '', 28153),
(156685, 'deDE', 'Ich weiß, dass Ihr das Unternehmen bestehlt. Ich bin hier, damit das nie wieder passiert...', 'Ich weiß, dass Ihr das Unternehmen bestehlt. Ich bin hier, damit das nie wieder passiert...', 28153),
(156684, 'deDE', 'Wollt Ihr vielleicht Prügel? Kümmert Euch um Euren eigenen Dreck!', 'Wollt Ihr vielleicht Prügel? Kümmert Euch um Euren eigenen Dreck!', 28153),
(156683, 'deDE', 'Geht einfach weiter. Hier gibt es nichts zu sehen...', 'Geht einfach weiter. Hier gibt es nichts zu sehen...', 28153),
(156682, 'deDE', 'Was guckt Ihr so?', 'Was guckt Ihr so?', 28153),
(156681, 'deDE', '<Hustet.> Fräulein Voss, wie kam es, dass Ihr eine Verlassene wurdet?', '', 28153),
(156680, 'deDE', 'Die Langfinger der Horde stibitzen Azerit von Aschenwind & Co. Zerquetscht unsere Feinde und sichert der 7. Legion diese Ressourcen.', '', 28153),
(156679, 'deDE', 'Ich habe nur gestohlen, um mein leeres Herz zu füllen, das niemals Liebe verspürt hat!', 'Ich habe nur gestohlen, um mein leeres Herz zu füllen, das niemals Liebe verspürt hat!', 28153),
(156678, 'deDE', 'Ich kann nichts dafür! Ich hatte eine harte Kindheit!', 'Ich kann nichts dafür! Ich hatte eine harte Kindheit!', 28153),
(156677, 'deDE', 'Ich werde es nicht noch einmal tun! Versprochen!', 'Ich werde es nicht noch einmal tun! Versprochen!', 28153),
(156676, 'deDE', 'Dieser Seebär Harrington hat seine Schläger gerufen!', 'Dieser Seebär Harrington hat seine Schläger gerufen!', 28153),
(156675, 'deDE', 'Ich werde nicht mehr stehlen! Aufhören!', 'Ich werde nicht mehr stehlen! Aufhören!', 28153),
(156674, 'deDE', 'Bitte tötet mich nicht! Ich werde niemals wieder stehlen!', 'Bitte tötet mich nicht! Ich werde niemals wieder stehlen!', 28153),
(156673, 'deDE', 'Unsere Soldaten werden von Verbannten aus Zuldazar als Geiseln gehalten. Wir verhandeln nicht mit Freunden der Horde. Zeigt ihnen die Stärke der Allianz!', '', 28153),
(156672, 'deDE', 'Ihr habt kurzen Prozess mit ihnen gemacht. Nicht schlecht.', '', 28153),
(156671, 'deDE', 'Unsere Spione haben ein kleines Hordelager in den Dünen ausgemacht. Schlagt schnell zu und dezimiert die feindlichen Streitkräfte!', '', 28153),
(156670, 'deDE', 'Es war mir eine Freude, Geschäfte mit Euch zu machen. Wenn Ihr mal einen Job bei den Piraten braucht, seid Ihr jederzeit willkommen!', '', 28153),
(156669, 'deDE', 'Ich halte immer mein Wort, $C. Die Schließkassette des Käpt\'ns soll Euch gehören!', '', 28153),
(156668, 'deDE', 'Wenn Hartford tot ist, treffen wir uns in den Kapitänsquartieren. Und keine Sorge wegen der Schließkassette. Alles, was da drin ist, gehört Euch!', '', 28153),
(156667, 'deDE', '', 'Wir sind noch nicht fertig. Ihr verfügt über gute Informationen, aber wir müssen noch herausfinden, wie mächtig Ihr wirklich seid.', 28153),
(156666, 'deDE', 'Bitte! Das sollte doch reichen. Euer Champion hat für Chaos und Vernichtung in Weisenwall gesorgt. Macht mich zu einem Verlassenen!', '', 28153),
(156665, 'deDE', '', 'War es falsch... die Allianz zu unterstützen?', 28153),
(156664, 'deDE', '', 'Die Horde wird niemals den Willen von Kul Tiras brechen!', 28153),
(156663, 'deDE', 'Man sollte dieses Buch... ins Meer... werfen...', '', 28153),
(156662, 'deDE', 'Ihr dürft dieses Buch nicht nehmen! Es ist zu gefährlich!', '', 28153),
(156661, 'deDE', '', 'Ihr wärt tot, bevor Ihr auch nur noch einmal jämmerlich husten könntet, Zelling. Wollt Ihr es drauf ankommen lassen?', 28153),
(156660, 'deDE', '<Röchelt.> Habt Ihr keine Angst, dass ich Euch angreifen könnte? Wollt Ihr nicht weglaufen?', '', 28153),
(156659, 'deDE', 'Ist Kapitänin Stein verrückt geworden, als sie sich verwandelt hat? Ihre Veränderung ist mir nicht entgangen.', '', 28153),
(156658, 'deDE', '', 'Ein Verlassener zu werden, ist ein unberechenbarer Vorgang. Euer Körper und Euer Geist werden sich verändern, aber in welchem Ausmaß? Das lässt sich unmöglich vorhersagen... und das gilt auch dafür, wie gut Ihr mit dem Vorgang zurechtkommen werdet.', 28153),
(156657, 'deDE', 'Nein, aber könntet Ihr meine Frage beantworten? Wird man von allen Krankheiten befreit, wenn man ein Verlassener wird?', '', 28153),
(156656, 'deDE', 'Mit Euch an meiner Seite komme ich der Flucht aus dieser verdammten Wüste einen Schritt näher.', '', 28153),
(156655, 'deDE', 'Trefft mich im Rotfelshafen, wenn die Aufgabe erledigt ist.', '', 28153),
(156654, 'deDE', 'Also das war... originell.', '', 28153),
(156653, 'deDE', 'Die Horde in diesen Ruinen behindert unsere Verbündeten bei ihrer Mission. Die Dunkeleisenzwerge wollen das auf ihre Art erledigen.', '', 28153),
(156652, 'deDE', 'Die Schlacht um Burg Stromgarde beginnt in 2 Minuten.', '', 28153),
(156651, 'deDE', 'Ich scheine meinen fabelhaften Hut verlegt zu haben.', 'Ich scheine meinen fabelhaften Hut verlegt zu haben.', 28153),
(156650, 'deDE', 'Bringt uns ins Sturmsangtal.', 'Bringt uns ins Sturmsangtal.', 28153),
(156649, 'deDE', 'Gut gemacht. Schauen wir mal, ob da was Nützliches dabei ist.', '', 28153),
(156648, 'deDE', 'Diese Ruinen scheinen zu einem im Meer versunkenen Tempel zu gehören. Die Anwesenheit der Naga ist Grund zur Besorgnis. Viel Glück bei Eurer Aufklärungsmission.', '', 28153),
(156647, 'deDE', 'Ich bin bereit für die Verhandlungen, Ty\'jin.', 'Ich bin bereit für die Verhandlungen, Ty\'jin.', 28153),
(156646, 'deDE', 'Sagt mir Bescheid, wenn Ihr bereit seid loszuleg\'n, Boss.', '', 28153),
(156645, 'deDE', 'Gut gemacht. Lieber früh um ein kleines Übel gekümmert als später um ein großes.', '', 28153),
(156644, 'deDE', 'Unsere Späher haben Murlocs in der Nähe entdeckt. Wir dürfen nicht zulassen, dass sie zu viele werden und unsere Flanken attackieren.', '', 28153),
(156643, 'deDE', '', 'Ihr habt Euch gut geschlag\'n, Champion! Die Loa werd\'n sich drüber freu\'n.', 28153),
(156642, 'deDE', '', 'Die Venture Company zerstört das Land von \'nem wichtig\'n Verbündeten. Den Loa gefällt sowas gar nich\'. Setzt ihr\'m Treiben \'n Ende und helft dabei, den ganz\'n Unrat zu beseitig\'n.', 28153),
(156641, 'deDE', '', 'Sehr gut! Diese Tortollaner werd\'n sich später bestimmt daran erinnern, wer sie vor \'nem schlimm\'n Schicksal bewahrt hat.', 28153),
(156640, 'deDE', '', 'Ich hab\' gehört, dass die Naga in der Gegend Tortollaner versklav\'n und keiner weiß warum. Lasst das nich\' zu, Champion! Tötet die Naga und gebt den Tortollanern die Freiheit zurück.', 28153),
(156639, 'deDE', 'Gezeitenweise geleiten seit jeher verlorene Seelen auf See... aber nicht so.', '', 28153),
(156637, 'deDE', 'Hervorragende Arbeit. Hoffen wir, dass die Tortollaner sich daran erinnern, wenn wir sie später brauchen!', '', 28153),
(156636, 'deDE', 'Ich bin bereit, nach Lordaeron zu segeln.', 'Ich bin bereit, nach Lordaeron zu segeln.', 28153),
(156635, 'deDE', 'Die Venture Company verunstaltet die Küstenlinie hier. Lasst uns die Gunst der Tortollaner erringen, indem wir hier mal etwas aufräumen.', '', 28153),
(156634, 'deDE', '', 'Keine Schule mehr... Nie mehr...', 28153),
(156633, 'deDE', '', 'Ich werde Euch eine Lektion erteilen!', 28153),
(156632, 'deDE', 'Großartig. Ich möchte mir gar nicht ausmalen, was die Naga mit den Tortollanern vorhatten.', '', 28153),
(156631, 'deDE', 'Späher berichten, dass die Naga in der Gegend Tortollaner entführen. Was auch immer sie vorhaben, wir müssen dem ein Ende bereiten.', '', 28153),
(156630, 'deDE', '', 'Ihr kämpft wie ein dummer Bauer!', 28153),
(156629, 'deDE', 'Gute Arbeit, $p! Wir sind dem Sieg einen Schritt näher gekommen!', '', 28153),
(156628, 'deDE', 'Das sollte ihre Zahl einschränken... für eine Weile. Gut gemacht.', '', 28153),
(156627, 'deDE', 'Diese gefiederten Vipern sind bekannt für ihr aggressives Nisten, aber das hier nimmt überhand. Vernichtet umgehend ihre Eier!', '', 28153),
(156626, 'deDE', 'Die kommen uns sehr gelegen. Unsere Verwundeten werden Euch für diesen Dienst danken, Champion.', '', 28153),
(156625, 'deDE', 'Wir müssen nutzen, was die Umgebung hergibt. Sammelt Speicheldrüsen von den wilden Pterrordaxen. Ihre heilende Wirkung wird unseren Verwundeten helfen.', '', 28153),
(156624, 'deDE', 'Kein Wunder, dass die Ravasaurier so gut wie alles fressen können! Das wird uns von großem Nutzen sein. Danke, Champion.', '', 28153),
(156623, 'deDE', 'Wir brauchen etwas Robustes. Die Ravasaurier haben angeblich extrem belastbare Mägen. Besorgt uns ein paar davon, wärt Ihr so gut?', '', 28153),
(156622, 'deDE', 'Arrgh... auf den Grund des Meeres... mit Euch...', '', 28153),
(156621, 'deDE', 'Was soll das werden? Eine Meuterei! Euch werd ich\'s zeigen!', '', 28153),
(156620, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(156619, 'deDE', '', 'Meine Forschungen sind vorerst abgeschlossen. Vielen Dank für Eure Hilfe.', 28153),
(156618, 'deDE', '', 'Das wird der Horde eine Lehre sein! Diese Magie darf niemals in ihre Hände fallen...', 28153),
(156617, 'deDE', '', 'Ich weiß Eure Hilfe zu schätzen. Diese Barriere ist so widerstandsfähig...', 28153),
(156616, 'deDE', 'Ich bin kurz davor, Unsterblichkeit zu erlangen! Ich kann es kaum erwarten, ein Verlassener zu werden. Diese schier unendlichen Möglichkeiten! \n\nWenn Ihr einen Moment Zeit habt, müsst Ihr mir erzählen, wie das ist! Untote Existenz, Ewigkeit, die ganze Welt in Reichweite!', '', 28153),
(156615, 'deDE', 'Ich weigere mich, mein Leben hier wegen einer läppischen... Krankheit enden zu lassen. Ich muss weiterleben, um die Sicherheit meiner Familie zu gewährleisten.', '', 28153),
(156614, 'deDE', 'Stört die Toten nicht, $R.', '', 28153),
(156613, 'deDE', '', 'Ich könnte hier etwas Hilfe brauchen!', 28153),
(156612, 'deDE', 'Wer sich nicht vorwärts bewegt, fällt zurück! Das war und ist immer mein Motto!', '', 28153),
(156611, 'deDE', '', 'Ich muss ein paar Tests durchführen und Daten sammeln. Passt auf, dass mich niemand dabei stört.', 28153),
(156610, 'deDE', '', 'Vielleicht können wir diese Magie nutzen oder sie sogar reproduzieren.', 28153),
(156609, 'deDE', '', 'Die hier verwendete Magie ist faszinierend! So etwas habe ich noch nie gesehen.', 28153),
(156608, 'deDE', '', 'Das hier ist noch nicht vorbei!', 28153),
(156607, 'deDE', 'Aber die Uhr tickt...', '', 28153),
(156606, 'deDE', 'Ich brauche eine neue Verkleidung.', 'Ich brauche eine neue Verkleidung.', 28153),
(156605, 'deDE', 'Die Horde ist hier! Lauft! Gibt es denn nirgendwo Sicherheit?', 'Die Horde ist hier! Lauft! Gibt es denn nirgendwo Sicherheit?', 28153),
(156604, 'deDE', 'Na, großartig. Jetzt ist die Allianz hier und wir haben noch mehr Probleme mit der Horde!', 'Na, großartig. Jetzt ist die Allianz hier und wir haben noch mehr Probleme mit der Horde!', 28153),
(156603, 'deDE', 'Ich riskiere doch nicht mein Leben, wenn die Horde schon hier ist!', 'Ich riskiere doch nicht mein Leben, wenn die Horde schon hier ist!', 28153),
(156602, 'deDE', 'Lauft! Das ist der Dank dafür, dass wir der Allianz geholfen haben!', 'Lauft! Das ist der Dank dafür, dass wir der Allianz geholfen haben!', 28153),
(156601, 'deDE', 'Ich dachte, wir wären vor der Horde sicher!', 'Ich dachte, wir wären vor der Horde sicher!', 28153),
(156600, 'deDE', 'Wie kommt die Horde hierher?!', 'Wie kommt die Horde hierher?!', 28153),
(156599, 'deDE', 'Die Horde! Lauft!', 'Die Horde! Lauft!', 28153),
(156598, 'deDE', 'Dies ist ein Test-Text, mit dem ich Dinge sage.', '', 28153),
(156597, 'deDE', '', 'Lebt wohl, Nathanos.', 28153),
(156596, 'deDE', '', '<Sylvanas setzt zum Gehen an, hält aber inne und blickt über ihre Schulter.>', 28153),
(156595, 'deDE', 'Wir werden Euch nicht enttäuschen. Sichere Reise, meine Fürstin.', '', 28153),
(156594, 'deDE', '', 'Führt meinen Auftrag aus und erstattet mir Bericht über Euren Fortschritt.', 28153),
(156593, 'deDE', 'Wie Ihr befehlt, Kriegshäuptling!', '', 28153),
(156592, 'deDE', '', 'Gut. Ihr werdet zusammen mit $n eine geeignete Stelle für einen Brückenkopf finden.', 28153),
(156591, 'deDE', 'Ja, Herrin. Die Klagelied ist jederzeit bereit zum Auslaufen.', '', 28153),
(156590, 'deDE', '', 'Sind alle Vorkehrungen getroffen?', 28153),
(156589, 'deDE', '<Nathanos verneigt sich.>', '', 28153),
(156588, 'deDE', 'Meine Königin.', '', 28153),
(156587, 'deDE', '$n, Eure Anwesenheit wird auf der Klagelied erwartet. Die Dunkle Fürstin befiehlt uns, unseren Feldzug an der Küste von Kul Tiras zu beginnen.', '', 28153),
(156586, 'deDE', '', 'Folgt mir.', 28153),
(156585, 'deDE', '', '$n.', 28153),
(156584, 'deDE', 'Garona die Halborcin befehligt die Gruppe. Ihr werdet ihr helfen, diese Aufträge durchzuführen.', '', 28153),
(156583, 'deDE', 'Wir haben eine Eliteeinheit zusammengestellt, die Aufträge der Dunklen Fürstin ausführt.', '', 28153),
(156582, 'deDE', 'Gute Arbeit, $p.', '', 28153),
(156581, 'deDE', 'Die Horde ist auf uns aufmerksam geworden und sendet Truppen, um uns anzugreifen. Tut etwas dagegen, damit unsere Feldmesser ihre Mission beenden können!', '', 28153),
(156580, 'deDE', '', 'Nun, ich schätze, das ließe sich arrangieren, Zelling. Aber nur, wenn Ihr Euch der Horde beweist.', 28153),
(156579, 'deDE', 'Mein Name ist Thomas Zelling und ich bin ein Gezeitenweiser, ein ERLEUCHTETER Gezeitenweiser! Ich tue alles, was Ihr sagt. Ich helfe Euch sogar, die Allianz in der Nähe anzugreifen, wenn Ihr mich nur zu einem Verlassenen macht!', '', 28153),
(156578, 'deDE', 'Es scheint, der Wagen hat seinen Weg zurück gefunden. Eure Belohnung erwartet Euch in der Burg.', '', 28153),
(156577, 'deDE', '', 'Wer seid Ihr? Warum glaubt Ihr, ein solches Geschenk verdient zu haben?', 28153),
(156576, 'deDE', 'Endlich, eine Verlassene! Bitte, tötet mich, macht mich zu einem Verlassenen... Schenkt mir die Unsterblichkeit!', '', 28153),
(156575, 'deDE', '', 'Nun, ich könnte die Frau ein bisschen bedrohen. Vielleicht will sie uns ja ein paar Details verraten...', 28153),
(156574, 'deDE', 'Die Leere, die Elemente... <hust>... Kann denn nichts diese verdammte Krankheit aufhalten? Warum musste es so enden?', '', 28153),
(156573, 'deDE', 'Hrm, der Gezeitenweise war vor einiger Zeit hier. Ich habe gesehen, wie er sich um seine Familie gekümmert und sie beschützt hat.', '', 28153),
(156572, 'deDE', 'Irgendeine Idee, wo wir einen Gezeitenweisen finden können?', 'Irgendeine Idee, wo wir einen Gezeitenweisen finden können?', 28153),
(156571, 'deDE', 'Wir haben eine Nachschublinie der Horde auf dem Schlachtfeld ausgemacht. Balinda sucht nach Freiwilligen, um... unsere Vorräte aufzufüllen.', '', 28153),
(156570, 'deDE', 'Wir erhalten Berichte von Hordespähern nahe der Mine. Genny wird Euch bei der Werkstatt die Einzelheiten erklären.', '', 28153),
(156569, 'deDE', 'Genny könnte bei der Werkstatt Hilfe gebrauchen. Unsere Vorräte werden etwas knapp.', '', 28153),
(156568, 'deDE', 'Wir können Geld machen, neue Länder kennenlernen... $B$BEine gute Zeit, in der wir leben!', '', 28153),
(156567, 'deDE', 'Habe ich nicht.', '', 28153),
(156566, 'deDE', 'Misha, bleib hier. Wir anderen werden diesen Gezeitenweisen aufspüren, und dann kann Lilian tun... was auch immer Eure Pläne vorsehen.', '', 28153),
(156565, 'deDE', '', 'Ihr habt wohl kein Interesse an den Details, Rexxar?', 28153),
(156564, 'deDE', 'Ich bin bereit für den Aufbruch nach Unterstadt.', 'Ich bin bereit für den Aufbruch nach Unterstadt.', 28153),
(156563, 'deDE', '', 'Todesend ist Vergangenheit. Ich bringe Euch jetzt zum Magierviertel, damit Ihr den Hochfürsten treffen könnt, wenn Ihr bereit seid.', 28153),
(156562, 'deDE', '', 'Champions, es ist Zeit. Die Allianz wird durch unsere Hand fallen, während sie vergebens versucht, uns Burg Lordaeron zu entreißen.', 28153),
(156560, 'deDE', 'Champions der Allianz, die Zeit ist reif, das zurückzuerobern, was uns rechtmäßig zusteht! Unser finaler Angriff auf Burg Lordaeron beginnt bei Tagesanbruch. Die Horde und ihr Kriegshäuptling müssen für ihre Verbrechen bezahlen!', '', 28153),
(156559, 'deDE', '', 'Ihr findet Euern nachtgebor\'nen Freund in der Halle der Uralt\'n Pfade. Sucht mich auf, wenn Ihr mit\'m Umseh\'n fertig seid.', 28153),
(156558, 'deDE', '', 'Vater bewahrt viele von sein\' Schätz\'n hier in der Schatzkammer auf.', 28153),
(156557, 'deDE', '', 'Es heißt, das Große Siegel is\' eins der wenig\'n Dinge im Land, die älter sin\' als das Imperium der Zandalari.', 28153),
(156556, 'deDE', '', 'Kommt, Champion! Ich führ Euch rum.', 28153),
(156555, 'deDE', 'Da kümmert Ihr Euch besser drum.', '', 28153),
(156554, 'deDE', 'Ich weiß nicht mehr, wie viel Zeit ich in dieser Zelle verbracht habe. Aber es spielt auch keine Rolle.', '', 28153),
(156553, 'deDE', 'Mein Name ist Samuel... Samuel Willem. Freut mich, dass jemand mit einer Waffe zur Abwechslung auf unserer Seite steht.', '', 28153),
(156552, 'deDE', 'Diese Piraten sind skrupellose, widerliche Dinger. Tötet sie, und niemand wird es Euch übelnehmen.', 'Diese Piraten sind skrupellose, widerliche Dinger. Tötet sie, und niemand wird es Euch übelnehmen.', 28153),
(156551, 'deDE', 'Worauf haben wir uns hier eingelassen?', 'Worauf haben wir uns hier eingelassen?', 28153),
(156550, 'deDE', 'Ihr werdet noch von mir hören, Monster!', 'Ihr werdet noch von mir hören, Monster!', 28153),
(156549, 'deDE', 'Ich habe ein Dutzend dieser widerlichen Monster besiegt, bevor sie mich überwältigen konnten!', 'Ich habe ein Dutzend dieser widerlichen Monster besiegt, bevor sie mich überwältigen konnten!', 28153),
(156548, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(156547, 'deDE', 'Niemand wird zurückgelassen!', 'Niemand wird zurückgelassen!', 28153),
(156546, 'deDE', 'Ich wusste, dass Wyrmbann uns hier nicht im Stich lassen würde!', 'Ich wusste, dass Wyrmbann uns hier nicht im Stich lassen würde!', 28153),
(156545, 'deDE', 'Die nächste Runde geht auf mich, wenn wir zurück auf dem Schiff sind.', 'Die nächste Runde geht auf mich, wenn wir zurück auf dem Schiff sind.', 28153),
(156544, 'deDE', 'Ich hätte nie gedacht, dass sie so viel fressen können...', '', 28153),
(156543, 'deDE', 'Ranishu haben einen unstillbaren Hunger, aber einen schlichten Verstand. Sie fressen alles in ihrer Bahn, einschließlich ihresgleichen. Das sollten wir ausnutzen!', '', 28153),
(156542, 'deDE', '', '<Garona lässt ihre Klingen wirbeln, und sie scheinen zu verschwinden.>', 28153),
(156541, 'deDE', 'Diese Kriegsadler werden uns zu unserem Ziel bringen. Seid Ihr bereit? Dann steigt auf!', '', 28153),
(156540, 'deDE', 'Lasst uns aufbrechen.', '', 28153),
(156539, 'deDE', 'Meine Königin hat für alles vorgesorgt. Unser Transportmittel wartet auf der Stadtmauer auf uns.', '', 28153),
(156538, 'deDE', 'Ich wollt nur \'n Teil von ihrem Schatz hab\'n.', 'Ich wollt nur \'n Teil von ihrem Schatz hab\'n.', 28153),
(156537, 'deDE', 'Ich werd zurückkomm\'n, Piraten! Ihr werdet noch von mir hör\'n!', 'Ich werd zurückkomm\'n, Piraten! Ihr werdet noch von mir hör\'n!', 28153),
(156536, 'deDE', 'Tötet die ganze verdammte feige Mannschaft!', 'Tötet die ganze verdammte feige Mannschaft!', 28153),
(156535, 'deDE', 'Ich vermiss Zuldazar... Wie lang muss ich hier drauß\'n noch leid\'n?', 'Ich vermiss Zuldazar... Wie lang muss ich hier drauß\'n noch leid\'n?', 28153),
(156534, 'deDE', 'Ich seh nich\' mal Schätze hier. Alles nur Lügen!', 'Ich seh nich\' mal Schätze hier. Alles nur Lügen!', 28153),
(156533, 'deDE', 'Sie woll\'n mich nich\' inner Mannschaft hab\'n! Das nich\' fair!', 'Sie woll\'n mich nich\' inner Mannschaft hab\'n! Das nich\' fair!', 28153),
(156532, 'deDE', 'So viel Freundlichkeit gibt\'s nich\' oft in der Wüste.', 'So viel Freundlichkeit gibt\'s nich\' oft in der Wüste.', 28153),
(156531, 'deDE', 'Ich hab nich\' gedacht, dass jemand wegen mir kommt. Ich dank Euch.', 'Ich hab nich\' gedacht, dass jemand wegen mir kommt. Ich dank Euch.', 28153),
(156530, 'deDE', 'Irgendetwas hat sich geöffnet.', '', 28153),
(156529, 'deDE', 'Noch nicht fertig...', '', 28153),
(156528, 'deDE', 'Das dürften alle gewesen sein. Gute Arbeit, $p. Ich wusste, ich kann auf Euch zählen.', '', 28153),
(156527, 'deDE', 'In den Höhlen sind noch immer viele Vulpera gefangen. Können wir auf Euch zählen, um sie da rauszuholen?', '', 28153),
(156526, 'deDE', 'Der sorgfältig kalibrierte Feger lässt ein kurzes Summen ertönen, da er keine Fossilien in der Nähe finden kann.', 'Der sorgfältig kalibrierte Feger lässt ein kurzes Summen ertönen, da er keine Fossilien in der Nähe finden kann.', 28153),
(156525, 'deDE', 'Der Ausgrabungselementar bebt verärgert, weil er keine Fossilien in der Nähe finden kann.', 'Der Ausgrabungselementar bebt verärgert, weil er keine Fossilien in der Nähe finden kann.', 28153),
(156524, 'deDE', '', 'Für Gilneas!', 28153),
(156523, 'deDE', '', 'Wachen, rein da! Bringt mir ihre Köpfe!', 28153),
(156522, 'deDE', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t Titanenhüter Hezrel beginnt, |cFFF00000|Hspell:269310|h[Läuterndes Licht]|h|r zu wirken!', '', 28153),
(156521, 'deDE', '', 'Die Horde hat also entschieden, uns hier anzugreifen? Das erspart mir die Mühe, Euch ausfindig zu machen. Gilneer, greift an!', 28153),
(156520, 'deDE', 'Das ist schwerer auszurechnen, als ich dachte. Kommt später wieder, um Euch Euren Anteil vom Schatz abzuholen.', '', 28153),
(156519, 'deDE', '', 'Genau wie bei der Bank von Eisenschmiede. Das ist eine Aufgabe für fünf Leute.', 28153),
(156518, 'deDE', 'Wir werden Helden sein... reiche Helden!', '', 28153),
(156517, 'deDE', 'Macht mich reich, $p, ich will mir ein paar Goldzähne kaufen!', '', 28153),
(156516, 'deDE', '', 'Was macht der Zahn, Ede?', 28153),
(156514, 'deDE', '', 'Ich hatte einen ähnlichen Traum. Aber da war ich in der Bank von Eisenschmiede.', 28153),
(156513, 'deDE', '', 'Wenn wir das Gold kriegen, kauf ich mir ein duftiges Parfüm und nehme ein Bad darin.', 28153),
(156512, 'deDE', 'Vielleicht sehen wir uns wieder. Gehabt Euch wohl!', '', 28153),
(156511, 'deDE', 'Wir sind frei...', '', 28153),
(156510, 'deDE', 'Wir müss\'n... entkomm\'n...', '', 28153),
(156509, 'deDE', '', 'Ich danke Euch für Eure Hilfe, $n. Ich werde jetzt woanders gebraucht.', 28153),
(156508, 'deDE', '', 'Ich gebe nicht vor, Eure Motive zu verstehen, $n, aber ich habe nichts dagegen, wenn Ihr weitere Todesritter niederstreckt.', 28153),
(156507, 'deDE', '', 'Behaltet den Himmel im Auge, $n! Ich spüre, dass sich etwas nähert.', 28153),
(156506, 'deDE', 'Was geht, $p?', 'Wenn Gold dabei rumkommt, bin ich dabei!', 28153),
(156505, 'deDE', 'Ich brauche Eure Hilfe.', 'Ich brauche Eure Hilfe.', 28153),
(156504, 'deDE', 'Ich habe den Lichkönig überstanden, nur um dann von jemandem wie Euch bezwungen zu werden... Argh...', '', 28153),
(156503, 'deDE', 'Was für eine Verschwendung...', '', 28153),
(156502, 'deDE', 'Ich brauche Eure Hilfe.', 'Ich brauche Eure Hilfe.', 28153),
(156501, 'deDE', 'Ihr siegt... Drache...', '', 28153),
(156500, 'deDE', 'Ein letzter... Tod...', '', 28153),
(156499, 'deDE', 'So... ungerecht...', '', 28153),
(156498, 'deDE', 'Dann nehme ich mir, was mir zusteht... mit Gewalt!', '', 28153),
(156497, 'deDE', 'Ich verstehe, $n! Ihr wollt der einzige Todesritter mit so einem schönen Reittier sein!', '', 28153),
(156496, 'deDE', 'Aber ich habe mehr Interesse an der uralten knöchernen Bestie hinter Euch. Wenn es Euch nichts ausmacht, nehme ich mir, was mir gehört.', '', 28153),
(156495, 'deDE', 'Der Drache dort ist ein bisschen klein... Und er lebt noch. Kein sonderlich großes Hindernis.', '', 28153),
(156494, 'deDE', 'Ich werde in Eure Fußstapfen treten. Seid Ihr hier, um mich zu unterstützen? Ich sehe, Ihr habt ein Geschenk mitgebracht!', '', 28153),
(156493, 'deDE', '$gTodesgebieter:Todesgebieterin; $n! Das nenne ich eine Überraschung!', '', 28153),
(156492, 'deDE', 'Pah. Wenn Ihr wollt, können wir das auch auf die harte Tour regeln!', '', 28153),
(156491, 'deDE', '', 'Beschützt mich, $n! Das Ritual muss abgeschlossen werden!', 28153),
(156490, 'deDE', 'Also, geht zur Seite, kleiner Drache. Ich habe etwas mit dem Knochenhaufen zu klären.', '', 28153),
(156489, 'deDE', 'Ich glaube, ich bleibe bei meinem ursprünglichen Plan und mache mit der uralten Bestie weiter.', '', 28153),
(156488, 'deDE', 'Los, verschwinden wir!', 'Los, verschwinden wir!', 28153),
(156487, 'deDE', 'Ein so herausragender Ritter wie ich sollte auch ein herausragendes Reittier haben.', '', 28153),
(156486, 'deDE', 'Zwei Großdrachen! Was für eine Überraschung! Auch wenn der lebendige ein wenig... mickrig ist.', '', 28153),
(156485, 'deDE', '', 'Ihr seid hier nicht willkommen, Todesritter!', 28153),
(156484, 'deDE', 'Sieh einer an... Was haben wir denn da?', '', 28153),
(156483, 'deDE', 'Zuls Anhänger werden Rezan seinem Schicksal nicht so schnell entrinn\'n lass\'n. Wir müss\'n uns den Weg nach draußen freikämpf\'n.\n\nSeid Ihr bereit?', '', 28153),
(156482, 'deDE', 'Warum die Eile? Macht langsam, atmet mal durch... macht ein Nickerchen! Hier bei uns seid Ihr in Sicherheit.', '', 28153),
(156481, 'deDE', 'Mein Vater hat uns das Schmieden gelehrt... Dieser Hammer war der erste, den wir zusammen gefertigt haben.', '', 28153),
(156480, 'deDE', 'Mein Hammer! Ihr habt ihn wiederbeschafft!', '', 28153),
(156479, 'deDE', '', 'Diese Verbannt\'n sin\' sowas wie \'ne Familie für mich.', 28153),
(156478, 'deDE', '', 'Willkommen im Klub, $p.', 28153),
(156477, 'deDE', 'Willkommen im Klub, $p.', '', 28153),
(156476, 'deDE', '', 'Willkommen im Klub, $p.', 28153),
(156475, 'deDE', 'Willkommen im Klub, $p.', '', 28153),
(156474, 'deDE', 'Wie wär\'s mit einem starken Getränk oder etwas zu essen?', 'Wie wär\'s mit einem starken Getränk oder etwas zu essen?', 28153),
(156473, 'deDE', 'Oh, Ihr seid das, $p? Die Sandwüter sin\' Euch doch nich\' etwa gefolgt, oder?', '', 28153),
(156472, 'deDE', 'Noch \'n paar Überfälle auf Karawanen, un\' dann plündern wir die Arena un\' hol\'n uns richtig fette Beute!', '', 28153),
(156471, 'deDE', 'Ich hab Durst! Geht los und klaut mir was von dem Zandalarigesöff!', '', 28153),
(156470, 'deDE', 'Feuerholz is\' bald alle. Findet noch \'ne Vulperakarawane, die wir ausnehm\'n könn\'n!', '', 28153),
(156469, 'deDE', 'Die Wüste gehört den Sandwütern! Alle anderen sind Eindringlinge!', '', 28153),
(156468, 'deDE', 'Bringt mir mehr Sklav\'n. Ich hab noch sehr viel mehr Speere zum Werf\'n.', '', 28153),
(156467, 'deDE', 'Brecht sie! Brecht sie wie Hunde!', '', 28153),
(156466, 'deDE', 'Jetzt isses vorbei mit dem schnöselig\'n Getue, arrogante Zandalari!', '', 28153),
(156465, 'deDE', 'Ha! Hab ein\'! Genau inne Brust, hässlicher Vulpera...', '', 28153),
(156464, 'deDE', 'Ihr wollt Euren Hammer zurück, Ihr dreckige, behaarte Kartoffel? DANN KOMMT UND HOLT IHN EUCH.', '', 28153),
(156463, 'deDE', 'Wir werden unser Land von diesem Abschaum von Kul Tiras reinigen! $n, ruft die Horde und lasst uns all dem ein Ende setzen.', '', 28153),
(156462, 'deDE', 'Passt auf, was Ihr sagt. Yazma is\' die Hohepriesterin von meinem Loa, un\' König Rastakhan schenkt ihr Gehör.$b$bUn\' wenn die Gerüchte stimm\'n, schenkt der große Prophet Zul ihr noch einiges mehr.', 'Passt auf, was Ihr sagt. Yazma is\' die Hohepriesterin von meinem Loa, un\' König Rastakhan schenkt ihr Gehör.$b$bUn\' wenn die Gerüchte stimm\'n, schenkt der große Prophet Zul ihr noch einiges mehr.', 28153),
(156461, 'deDE', 'Shadra is\' beim Rat der Zanchuli \'n besonders beliebter Loa. Anhänger wie ich genieß\'n viele Privilegien. Darunter auch das Recht, Euch nix schuldig zu sein.', 'Shadra is\' beim Rat der Zanchuli \'n besonders beliebter Loa. Anhänger wie ich genieß\'n viele Privilegien. Darunter auch das Recht, Euch nix schuldig zu sein.', 28153),
(156460, 'deDE', 'Seid verflucht...', 'Seid verflucht...', 28153),
(156459, 'deDE', 'Ihr werdet verlieren...', 'Ihr werdet verlieren...', 28153),
(156458, 'deDE', 'Mein König... Es... tut mir leid...', 'Mein König... Es... tut mir leid...', 28153),
(156457, 'deDE', 'Das werdet Ihr... büßen...', 'Das werdet Ihr... büßen...', 28153),
(156456, 'deDE', 'Für... die Allianz...', 'Für... die Allianz...', 28153),
(156455, 'deDE', 'Die Anhänger von Shadra hab\'n Eure Art mit groß\'m Int\'resse beobachtet.$b$BWir seh\'n, wie Eure Horde sich immer tiefer in\'n Riesennetz aus Lüg\'n verstrickt. Die Falle schnappt bald zu, un\' Ihr werdet es erst merk\'n, wenn\'s zu spät ist.', 'Die Anhänger von Shadra hab\'n Eure Art mit groß\'m Int\'resse beobachtet.$b$BWir seh\'n, wie Eure Horde sich immer tiefer in\'n Riesennetz aus Lüg\'n verstrickt. Die Falle schnappt bald zu, un\' Ihr werdet es erst merk\'n, wenn\'s zu spät ist.', 28153),
(156454, 'deDE', 'Sterbt!', 'Sterbt!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'deDE', 'Ich werde Euch in Stücken zurück nach Orgrimmar zurückschicken!', 'Ich werde Euch in Stücken zurück nach Orgrimmar zurückschicken!', 28153),
(156452, 'deDE', 'Ihr werdet für Eure Verbrechen gegen die Allianz bezahlen!', 'Ihr werdet für Eure Verbrechen gegen die Allianz bezahlen!', 28153),
(156451, 'deDE', 'Ich dien\' Shadra, Gebieterin der Spione un\' Loa der Gifte. Un\' wem dient Ihr wirklich?', 'Ich dien\' Shadra, Gebieterin der Spione un\' Loa der Gifte. Un\' wem dient Ihr wirklich?', 28153),
(156450, 'deDE', 'Sterbt, Hordenabschaum!', 'Sterbt, Hordenabschaum!', 28153),
(156449, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(156448, 'deDE', 'Die Gebieterin hat Eure Anwes\'nheit in ihr\'m Reich bemerkt. Seid vorsichtig.', 'Die Gebieterin hat Eure Anwes\'nheit in ihr\'m Reich bemerkt. Seid vorsichtig.', 28153),
(156447, 'deDE', 'Geht mit der Erdenmutter, $n.', 'Geht mit der Erdenmutter, $n.', 28153),
(156446, 'deDE', 'Unsere Jagd in diesen Gefilden hat gerade erst begonnen.', '', 28153),
(156445, 'deDE', 'Rhan\'ka versteckt sich immer noch da draußen in der Oase? Ich muss ihn bald mal besuchen...', '', 28153),
(156444, 'deDE', 'Ich wusste, Ihr würdet zurückkommen und mehr wollen. Ich hab hier eine frische Ladung. Nur für Euch.', '', 28153),
(156443, 'deDE', '[DIE SZENE ZEIGT, WIE GENERAL JAKRA\'ZET UND IMPERATOR KORTHEK PLÄNE SCHMIEDEN.]', '', 28153),
(156442, 'deDE', 'Die Tiefen... haben Euch... im Auge...', 'Die Tiefen... haben Euch... im Auge...', 28153),
(156441, 'deDE', 'Ich werde Euren zerstückelten Kadaver ins Meer werfen!', 'Ich werde Euren zerstückelten Kadaver ins Meer werfen!', 28153),
(156440, 'deDE', '', 'Ich hätte als Goblin geboren werden sollen. Die schätzen meine einzigartigen Fähigkeiten mehr.', 28153),
(156439, 'deDE', 'Wir sollten was mit den Eisenfluträubern machen. Das sind noch größere Dummköpfe.', '', 28153),
(156438, 'deDE', 'Tut, was Ihr tun müsst, während wir nach Zul suchen. Aber haltet Euch in Bereitschaft, denn wir werden Eure Schlagkraft bald genug brauchen.', '', 28153),
(156437, 'deDE', '', 'Wir werden diese Ketzer bis in die letzten Winkel von Azeroth jagen. Ich werde meinen Schwarm versammeln, und wir werden mit unseren Steinen den Tod herabregnen lassen auf die Häupter jener abscheulichen Kreaturen, die es wagten, uns den Rücken zu kehren.\n\nDoch zuerst wird mein Schwarm die Himmel durchstreifen und ergründen, was Zul und seine Verräter im Schilde führen.', 28153),
(156436, 'deDE', 'Der Todesstoß gehörte Euch... zumindest diesmal...', '', 28153),
(156435, 'deDE', '<Reiht meine Gruppe in die Warteschlange für eine PvP-Inselexpedition ein.>', '<Reiht meine Gruppe in die Warteschlange für eine PvP-Inselexpedition ein.>', 28153),
(156434, 'deDE', '<Reiht Euch in die Warteschlange für eine PvP-Inselexpedition ein.>', '<Reiht Euch in die Warteschlange für eine PvP-Inselexpedition ein.>', 28153),
(156433, 'deDE', 'Verwendet Jintikis Fetisch, um Zulajin zu vernichten!', 'Verwendet Jintikis Fetisch, um Zulajin zu vernichten!', 28153),
(156432, 'deDE', 'Ich bete, dass das Versteck meines Schlüssels sicher ist und nur Ihr es finden könnt.', '', 28153),
(156431, 'deDE', 'Kaga, Eure Tapferkeit steht außer Frage, aber Ihr seid nicht in der Lage zu kämpfen. $n, ich werde Kaga begleiten. Stoßt beim Kriegsturm zu uns, wenn Ihr fertig seid.', '', 28153),
(156430, 'deDE', 'Habt Dank. Ich werde den Kriegsturm sichern. Wir werden ihn brauchen, um den Rest der Truppen zu rufen.', 'Habt Dank. Ich werde den Kriegsturm sichern. Wir werden ihn brauchen, um den Rest der Truppen zu rufen.', 28153),
(156429, 'deDE', '', 'Meine Schwestern... werden Euch töten...', 28153),
(156428, 'deDE', 'Die Horde wird scheitern...', 'Die Horde wird scheitern...', 28153),
(156427, 'deDE', 'Ihr folgt einer Wahnsinnigen...', 'Ihr folgt einer Wahnsinnigen...', 28153),
(156426, 'deDE', 'Ihr Monster...', 'Ihr Monster...', 28153),
(156425, 'deDE', 'Ich... werde... Euch... töten...', 'Ich... werde... Euch... töten...', 28153),
(156424, 'deDE', 'Die Horde wird dafür bezahlen...', 'Die Horde wird dafür bezahlen...', 28153),
(156423, 'deDE', 'Für Teldrassil...', 'Für Teldrassil...', 28153),
(156422, 'deDE', 'Schwestern... Ich habe es versucht...', 'Schwestern... Ich habe es versucht...', 28153),
(156421, 'deDE', '', 'Meine Familie ist in Teldrassil gestorben! Ich werde Euch umbringen!', 28153),
(156420, 'deDE', '', 'Wir werden Teldrassil rächen!', 28153),
(156419, 'deDE', 'Wir werden dafür sorgen, dass die Kul Tiraner es sich in Zukunft gut überlegen, sich gegen die Horde zu stellen.', '', 28153),
(156418, 'deDE', 'Für Teldrassil und die Allianz!', 'Für Teldrassil und die Allianz!', 28153),
(156417, 'deDE', 'Ihr sollt qualvoll sterben, Hordenabschaum!', 'Ihr sollt qualvoll sterben, Hordenabschaum!', 28153),
(156416, 'deDE', '', 'Mörder! Ihr wagt es, Eure Gesichter zu zeigen?', 28153),
(156415, 'deDE', 'Lasst uns da lang!', '', 28153),
(156414, 'deDE', 'Das Gehen übernehm\' jetzt ich!', '', 28153),
(156413, 'deDE', 'Ich sage jetzt, wo\'s langgeht!', '', 28153),
(156412, 'deDE', 'Ich zu Beinen befördert!', '', 28153),
(156411, 'deDE', 'Ich fahr jetzt!', '', 28153),
(156410, 'deDE', 'Das heilige Feuer soll Euch läutern!', '', 28153),
(156409, 'deDE', 'Nein... Ich muss... den Ring finden...', '', 28153),
(156408, 'deDE', 'Monster! Ich werde dem Kriegshäuptling Euren Kopf schicken!', 'Monster! Ich werde dem Kriegshäuptling Euren Kopf schicken!', 28153),
(156407, 'deDE', 'Euer Kopf wird ein Geschenk für meine Königin!', '', 28153),
(156406, 'deDE', '', 'Die Horde wird dafür bezahlen, was sie Teldrassil angetan hat!', 28153),
(156405, 'deDE', '', 'Ich werde Euch zeigen, wie Leichen brennen!', 28153),
(156404, 'deDE', '', 'Unsere Arbeit hier scheint getan! Passt auf Euch auf da draußen, $p.', 28153),
(156403, 'deDE', 'Ich werde meine Männer rächen. Das schwöre ich.', 'Ich werde meine Männer rächen. Das schwöre ich.', 28153),
(156402, 'deDE', 'Törichte Sterbliche. Ihr könnt meine Rückkehr nicht verhindern.', '', 28153),
(156401, 'deDE', '', 'Ihr! Horde! Eure Fähigkeiten werden verlangt.', 28153),
(156400, 'deDE', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|tEine neue |cFFFF0404|Hspell:263420|h[Energiematrix]|h|r ist verfügbar.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|tEine neue |cFFFF0404|Hspell:263420|h[Energiematrix]|h|r ist verfügbar.', 28153),
(156399, 'deDE', 'Dieser Troll is\' verrückter als \'n Sack voller Ranishu.', '', 28153),
(156398, 'deDE', 'Rikati rollt mit den Augen.', '', 28153),
(156397, 'deDE', 'Alles klar. Mach ich! Danke!', '', 28153),
(156396, 'deDE', 'Keine Zeit zum red\'n, Rikati! Die Sandwüter lauf\'n Amok! Versteckt den Honig!', '', 28153),
(156395, 'deDE', 'Der Ring der Gezeiten soll uns gehören! Königin Azshara verlangt danach!', 'Der Ring der Gezeiten soll uns gehören! Königin Azshara verlangt danach!', 28153),
(156394, 'deDE', 'Wir geben nicht auf, bis wir den Ring haben!', 'Wir geben nicht auf, bis wir den Ring haben!', 28153),
(156393, 'deDE', 'Was redet Ihr\'n da? Zähl\'n? Ich? So was mach ich nich\'. Das sollt\' Eure Aufgabe sein.\n\nWisst Ihr was, wir fang\'n am Besten nochmal bei Null an.', '', 28153),
(156392, 'deDE', 'Wo ist der Ring der Gezeiten? Versteckt ihn nicht vor uns!', 'Wo ist der Ring der Gezeiten? Versteckt ihn nicht vor uns!', 28153),
(156391, 'deDE', 'Der Ring der Gezeiten ist hier in der Nähe verloren gegangen. Die Königin muss ihn zurückbekommen!', 'Der Ring der Gezeiten ist hier in der Nähe verloren gegangen. Die Königin muss ihn zurückbekommen!', 28153),
(156390, 'deDE', 'Die Sturmwacht wird stärker. Seid Ihr auf unserer Seite?', 'Die Sturmwacht wird stärker. Seid Ihr auf unserer Seite?', 28153),
(156389, 'deDE', 'Habe ich schon eine Million Seelen?', 'Habe ich schon eine Million Seelen?', 28153),
(156388, 'deDE', 'Niemand wird sich der Königin den Weg stellen!', 'Niemand wird sich der Königin den Weg stellen!', 28153),
(156387, 'deDE', 'Der Ring der Gezeiten steht uns zu!', 'Der Ring der Gezeiten steht uns zu!', 28153),
(156386, 'deDE', 'Wir können Lord Sturmsang immer noch aufhalten.', 'Wir können Lord Sturmsang immer noch aufhalten.', 28153),
(156385, 'deDE', 'Der Ring wird uns gehören!', 'Der Ring wird uns gehören!', 28153),
(156384, 'deDE', 'Königin Azshara verlangt nach dem Ring der Gezeiten!', 'Königin Azshara verlangt nach dem Ring der Gezeiten!', 28153),
(156383, 'deDE', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t Die Goldschlange absorbiert animiertes Gold und erhält |cFFFF0000|Hspell:265991|h[Glanz]|h|r!', 'Die Goldschlange absorbiert animiertes Gold und erhält |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t an dieser Stelle optionalen Text und |cFFFF0000|Hspell:265991|h[Glanz]|h|r!', 28153),
(156382, 'deDE', '', 'Oh-oh. Das sieht nicht gut aus! GAR NICHT GUT!', 28153),
(156381, 'deDE', 'Benutzt eines dieser Seile, um in ein Landefahrzeug zu steigen... Es sei denn, Ihr schwimmt lieber.', '', 28153),
(156380, 'deDE', 'Ich werde kein einziges Teil dreckiger Menschenunterwäsche mehr waschen!', '', 28153),
(156379, 'deDE', '', 'Ich bin nass bis auf die Socken! Danke.', 28153),
(156378, 'deDE', '', 'Mir reicht\'s!', 28153),
(156377, 'deDE', 'Ihr habt mich vor einem schrecklichen Schicksal bewahrt.', '', 28153),
(156375, 'deDE', 'Während Ihr auf Abenteuerreise wart, habe ich die Klinge untersucht.', 'Während Ihr auf Abenteuerreise wart, habe ich die Klinge untersucht.', 28153),
(156374, 'deDE', '<Spionagemeister Shaw nickt bestätigend.>', '', 28153),
(156373, 'deDE', 'Wir sind hier, Meisterspion.', '', 28153),
(156372, 'deDE', 'Ich werde mit Spionagemeister Shaw zusammenarbeiten. Er ist vielleicht nicht sonderlich nett, aber er weiß, was er tut.', '', 28153),
(156371, 'deDE', 'Der König hat für diese Mission ein paar recht beeindruckende Helden verpflichtet.', '', 28153),
(156370, 'deDE', 'Flinkschwinge, besorg dir eine schöne Mahlzeit.', '', 28153),
(156369, 'deDE', 'Folgt mir, $umein Junge:meine Liebe;.', '', 28153),
(156368, 'deDE', 'Voll ins Knie getroffen!', 'Oh... Das hat sicher wehgetan!', 28153),
(156367, 'deDE', 'So einfach geben wir nicht auf.', 'Hätten davonlaufen sollen, als sie die Chance dazu hatten.', 28153),
(156366, 'deDE', 'Und wieder einer am Boden!', 'Nicht so zäh, wie sie dachten!', 28153),
(156365, 'deDE', 'Hallo, Kapitänin Stein. Ich freue mich schon darauf, Euch näher kennenzulernen.', '', 28153),
(156364, 'deDE', 'Dann ladet ihn in den Wagen. Ihr erweist Euch nützlicher als erwartet, Fräulein Voss.', '', 28153),
(156363, 'deDE', '', 'Unversehrt genug.', 28153),
(156362, 'deDE', 'Ist er unversehrt?', '', 28153),
(156361, 'deDE', '', 'Hier, Pestrufer. Ich habe den Leichnam geborgen.', 28153),
(156360, 'deDE', 'Gute Arbeit, $p. Aber wo ist Lilian?', '', 28153),
(156359, 'deDE', 'Ihr müsst Euch beeil\'n... Sie werd\'n Rezan nachstell\'n!', '', 28153),
(156358, 'deDE', 'Die... ham mich gezwungen, ihnen zu sag\'n, wie die Drakkari das gemacht ham.', '', 28153),
(156357, 'deDE', 'Ausgezeichnet. Champion, Taelia wird Euch einweisen.', '', 28153),
(156356, 'deDE', '', 'Herr! Der Lagebericht ist bereit!', 28153),
(156355, 'deDE', '', 'Ihr habt aus ihrer Armee Kleinholz gemacht! Wirklich außerordentlich.', 28153),
(156354, 'deDE', '', 'Die Hexen sind dabei, ihre Streitkräfte wieder aufzubauen. Verschafft Euch einen Verwüster und zerschlagt ihre Armee!', 28153),
(156353, 'deDE', '', 'Wir müssen den Kul Tiranern zeigen, was es bedeutet, sich die Horde zum Feind zu machen.', 28153),
(156352, 'deDE', 'Denkt daran: Bronhavn ist eine große und gut geschützte Siedlung. Bleibt am Rande der Stadt... vorerst.', '', 28153),
(156351, 'deDE', 'Wir haben unseren Teil beigetragen, $p. Ich bin stolz auf das, was wir hier erreicht haben.\n\nAber jetzt ist es für mich an der Zeit, mich um meine Leute zu kümmern und für ihre Sicherheit zu sorgen.\n\nIch bin mir sicher, dass wir uns wiedersehen werden. Ich bin stolz darauf, Euch zu meinen Freunden und Verbündeten zählen zu dürfen.', '', 28153),
(156350, 'deDE', 'Die Treulosen sind grausam zu ihren Tieren. Es ist nicht schwer, sie gegen ihre Meister aufzubringen.', '', 28153),
(156349, 'deDE', 'Das muss ich mir nich\' gefall\'n lass\'n. Zul der Prophet hat mir diese Stellung persönlich verlieh\'n.', '', 28153),
(156348, 'deDE', '', 'Also, DAS war eine Schlacht, die einen Heldengesang verdient hat!\n\nEs ist eine Ehre, an Eurer und Vorriks Seite zu kämpfen. Ich hoffe, dass wir bald wieder Gelegenheit dazu haben.\n\nEs gibt schließlich noch einige Treulose mehr, die wir töten können.', 28153),
(156347, 'deDE', 'Lasst uns das zusammen beenden.', '', 28153),
(156346, 'deDE', '', 'Kommt, diesen Sethrak erteilen wir eine Lektion.', 28153),
(156345, 'deDE', '', 'Mit diesen Vorräten können wir unseren Kampf gegen den Zirkel fortführen. Danke.', 28153),
(156344, 'deDE', 'Folgt mir. Die Festung ist nicht weit von hier.', '', 28153),
(156343, 'deDE', 'Gut. Dann wird sie unser Ziel sein.', '', 28153),
(156342, 'deDE', '', 'Bronhavn, die Stadt, die wir gerade passiert haben, scheint die größte Bedrohung in dieser Gegend zu sein.', 28153),
(156341, 'deDE', 'Rexxar! <hust> Viele leisten noch immer Widerstand. I-Ihnen bleibt nicht viel Zeit.', 'Rexxar! <hust> Viele leisten noch immer Widerstand. I-Ihnen bleibt nicht viel Zeit.', 28153),
(156340, 'deDE', 'Diese Bestie macht sich keine Hordensoldaten mehr zur Mahlzeit. Eine würdige Trophäe, Champion.', '', 28153),
(156339, 'deDE', '', 'Uns geht das Silber aus. Für unseren Kampf gegen die Hexen ist es von entscheidender Bedeutung. Geht in die Minen und sammelt so viel wie möglich.', 28153),
(156338, 'deDE', 'Rakjan scheint gewillt zu sein, uns zu helfen. Und es ist auch nicht schwer zu verstehen, warum.\n\nDie Treulosen haben ihn und seine Brut grausam behandelt. Schaut Euch die Narben auf seinem Körper und die leeren Plätze in seinem Hort an.\n\nEr hat genauso viel Recht auf Rache wie wir. Wir werden sie uns zusammen nehmen.', '', 28153),
(156337, 'deDE', 'Ja, Samuel. Bleibt stark.', '', 28153),
(156336, 'deDE', 'Mir ist so kalt. Werden die Stimmen bald aufhören?', '', 28153),
(156335, 'deDE', '$n, rührt meine Mixtur um, sonst brennt sie noch an.', '', 28153),
(156334, 'deDE', 'Gute Arbeit. Dann lasst uns mal dafür sorgen, dass das die letzte Ratsversammlung wird.', '', 28153),
(156333, 'deDE', 'Gut gemacht, Zastamann. Jetz\' könn\' wir in die Ratsversammlung reinplatz\'n.', '', 28153),
(156332, 'deDE', 'Nur ruhig, die Kräuter werden Eure Wunden lindern. Könnt Ihr uns etwas aus dem Inneren der Festung berichten? Gibt es noch andere Überlebende?', '', 28153),
(156331, 'deDE', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t Der Schaden des seelengebundenen Goliaths erhöht sich mit jedem Stapel von |cFFFF0404|Hspell:260512|h[Seelenernte]|h|r!', '', 28153),
(156330, 'deDE', 'Seht! Hier atmet noch einer!', '', 28153),
(156329, 'deDE', 'Viele tapfere Soldaten haben in der Schlacht ihr Leben gelassen. Eure Ankunft war ein wahrer Segen.', '', 28153),
(156328, 'deDE', 'Als wir versuchten, die Besatzungen in Sicherheit zu bringen, griffen die Kul Tiraner an. Wir hatten nicht die Truppenstärke, um beide Stellungen zu halten, also mussten wir uns ans Ufer zurückziehen.', '', 28153),
(156327, 'deDE', 'Der Angriff kam heute am frühen Morgen. Die Magier von Kul Tiras benutzten ein sonderbares Objekt, um diese Schrecken herbeizurufen, die sich um unsere Schiffe wanden.', '', 28153),
(156326, 'deDE', 'Ha! Bestätigt. Mission erfolgreich. Vollendete Perfektion! Ich liebe es, wenn ein Plan funktioniert. Ende.', '', 28153),
(156325, 'deDE', 'Zum Start. Seht Ihr den großen roten Knopf? Genau, verlasst den Einsatzbereich und drückt den großen roten Knopf. Start nach eigenem Ermessen. Ende.', '', 28153),
(156324, 'deDE', 'Authentifizierungscode eins-neun-neun. Instrumentenausrichtung entspricht nicht den Parametern... Berichtigung... ich krieg das hin. Position halten. Ende.', '', 28153),
(156323, 'deDE', 'Bestätige! Ja! Kalibrierung abgeschlossen. Alle Instrumente müssen präzise ausgerichtet werden. Meldet Euch, wenn sie platziert sind. Ende.', '', 28153),
(156322, 'deDE', 'Funktest, 1-2-3. Hier Alpha eins. Rufe Gruppe Alphaschwadron. Hört Ihr mich? Kommen.', '', 28153),
(156321, 'deDE', 'Ein glorreicher Kampf! Und wir haben sogar überlebt, $p!', '', 28153),
(156320, 'deDE', '', 'Die Flamme wird niemals sterben...', 28153),
(156319, 'deDE', '', 'Asche zu Asche...', 28153),
(156318, 'deDE', 'Wir wissen Eure edlen Taten sehr zu schätzen. Vielen Dank, $p.', '', 28153),
(156317, 'deDE', '', 'Eure Knochen werden hervorragenden Zunder abgeben.', 28153),
(156316, 'deDE', '', 'Niemand wird übrig bleiben, um über Eurer Asche zu trauern.', 28153),
(156315, 'deDE', 'In unserer langen Geschichte haben wir nur wenige so großartige Tage erlebt!', '', 28153),
(156314, 'deDE', 'Ich werde Euch zu Ehren eine neue Suppe kreieren!', '', 28153),
(156313, 'deDE', 'Schildkrötensuppe ist nicht halb so lecker wie $gein:eine:r; $R, $gder:die:r; langsam weichgekocht wird.\n\nBeschafft einfach das Schlammwurmfleisch und lasst die kleinen Schildkröten in Ruhe.\n\nKommt mal wieder bei mir vorbei, dann können wir andere Suppen ausprobieren!', '', 28153),
(156312, 'deDE', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t %s beginnt, |cFFFF0000|Hspell:267334|h[Kugel der Verderbnis]|h|r zu wirken!', 'Eine Projektion erscheint in der Ferne...', 28153),
(156311, 'deDE', '', 'Man kommt leicht vom Weg ab.', 28153),
(156310, 'deDE', 'Lasst mich wiss\'n, wenn Ihr meine Hilfe braucht.', '', 28153),
(156309, 'deDE', 'Jetz\', wo all das geregelt is\', mach ich mich auf\'n Rückweg.', '', 28153),
(156308, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf zum Tiragardesund!', '|cFF0000FF(Quest)|r Setzt die Segel, auf zum Tiragardesund!', 28153),
(156307, 'deDE', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s beginnt, |cFFFF0000|Hspell:265360|h[Aufwühlender Betrug]|h|r zu wirken!', 'Eine Projektion erscheint in der Ferne...', 28153),
(156306, 'deDE', '', 'Ich bin dankbar für Euren Beistand, Champion.', 28153),
(156305, 'deDE', '', 'Die Schatten der Vergangenheit umgeben uns.', 28153),
(156304, 'deDE', 'Wollen wir mal den Leidenfrost-Effekt ausprobieren? Wir tauchen unsere Hand erst in Wasser, dann in flüssiges Eisen und wie durch ein Wunder wird uns nichts passieren. Todsicher. Ähm, Ihr fangt an...', '', 28153),
(156303, 'deDE', 'Gleich gibt\'s einen Satz heiße Ohren.', '', 28153),
(156302, 'deDE', 'Ihr spürt gleich meinen Hammer!', '', 28153),
(156301, 'deDE', 'Lasst sie Euer Feuer spüren.', '', 28153),
(156300, 'deDE', 'Haltet Eure Eisen heiß.', '', 28153),
(156299, 'deDE', 'Schönen Tag noch!', '', 28153),
(156298, 'deDE', 'Habt Ihr meinen Schraubenschlüssel gesehen?', '', 28153),
(156297, 'deDE', 'Wie kann ich helfen?', '', 28153),
(156296, 'deDE', 'Wo brennt\'s?', '', 28153),
(156286, 'deDE', '', 'So viel Leid. So viel Verlust.', 28153),
(156285, 'deDE', '', 'Welchen Weg soll ich gehen?', 28153),
(156284, 'deDE', '', 'Ich muss meinen Weg durch den Schmerz finden.', 28153),
(156283, 'deDE', 'Der Sand ist rot.', 'Der Sand ist rot.', 28153),
(156282, 'deDE', 'Wie bin ich denn hier gelandet?', 'Wie bin ich denn hier gelandet?', 28153),
(156281, 'deDE', 'Meine Kameraden werden mich rächen.', 'Meine Kameraden werden mich rächen.', 28153),
(156280, 'deDE', 'Also Turalyon leuchtet, Alleria macht auf düster... Hmm... Ich schätze, jetzt wo ich wieder im Ring bin, brauche ich auch irgendein \"Ding\"!', '', 28153),
(156279, 'deDE', 'Habe ich mich gut geschlagen?', 'Habe ich mich gut geschlagen?', 28153),
(156278, 'deDE', 'Ich werde Euch vernichten!', 'Ich werde Euch vernichten!', 28153),
(156277, 'deDE', 'Das ist Euer Ende!', 'Das ist Euer Ende!', 28153),
(156276, 'deDE', 'Ihr könnt uns nicht aufhalten!', 'Ihr könnt uns nicht aufhalten!', 28153),
(156275, 'deDE', 'Beim Licht, endlich bin ich raus aus der Ehrenfeste. Die Eintönigkeit wurde einfach unerträglich.', '', 28153),
(156274, 'deDE', 'Nicht heute, Ungeheuer!', 'Nicht heute, Ungeheuer!', 28153),
(156273, 'deDE', 'Einmal die Woche treffe ich mich mit Khadgar auf eine Partie Dame. Er schummelt natürlich jedes Mal.', '', 28153),
(156272, 'deDE', 'Wir alle müssen unseren Beitrag leisten.', '', 28153),
(156271, 'deDE', 'Für Stromgarde!', '', 28153),
(156270, 'deDE', 'Ich will Euch nich\' anlüg\'n, Boss.\n\nIch wollt immer mal bei \'ner Meuterei mitmach\'n.', '', 28153),
(156269, 'deDE', 'Für die Allianz!', '', 28153),
(156268, 'deDE', 'Die Allianz wird siegen.', '', 28153),
(156267, 'deDE', 'Kämpft tapfer.', '', 28153),
(156266, 'deDE', 'Azeroth ruft. Und wir müssen folgen.', '', 28153),
(156265, 'deDE', 'Wir kämpfen für das, was unser ist!', '', 28153),
(156264, 'deDE', 'Was immer passiert, wir überstehen es. Gemeinsam.', '', 28153),
(156263, 'deDE', 'Mein Leben für die Allianz.', '', 28153),
(156262, 'deDE', 'Stromgarde wird sich aufs Neue erheben.', '', 28153),
(156261, 'deDE', 'Verdreht die Augen so viel Ihr wollt, ich sag es trotzdem... JETZT WIRD DER HAMMER GESCHWUNGEN!', '', 28153),
(156260, 'deDE', 'Man kann wohl sagen, ich habe das Mittelkindsyndrom. Aber mit einem Diamanten und einem berühmten Entdecker als Bruder, ist es nicht leicht, seine Nische zu finden.', '', 28153),
(156259, 'deDE', 'Was zum...?! Jemand hat mich grade \"Zuckerkönig\" genannt und um einen Lutscher gebeten!', '', 28153),
(156258, 'deDE', 'Wir geben niemals auf!', '', 28153),
(156257, 'deDE', 'Der Bronzebartklan schuldet Euch was, Champion.', '', 28153),
(156256, 'deDE', 'Eisenschmiede rettet den Tag.', '', 28153),
(156255, 'deDE', 'Auf dass Euer Weg zum Ruhm führt.', '', 28153),
(156254, 'deDE', 'Auf dass Euer Hammer nie verfehlt.', '', 28153),
(156253, 'deDE', 'Auf dass die Schmiede Euch stählt.', '', 28153),
(156252, 'deDE', 'Hammer gestählt, Axt geschärft... an die Arbeit!', '', 28153),
(156251, 'deDE', 'Kommt Ihr, um für die Allianz zu kämpfen?', '', 28153),
(156250, 'deDE', 'Die Drei Hämmer stehen Seite an Seite.', '', 28153),
(156249, 'deDE', 'Eisenschmiede leistet seinen Beitrag.', '', 28153),
(156248, 'deDE', 'Wisst Ihr, was mit den ersten sechs Legionen passiert ist? Nein? Wollt Ihr es herausfinden?', '', 28153),
(156247, 'deDE', 'Soll ich Euch in die Brigg werfen, Soldat?', '', 28153),
(156246, 'deDE', 'Ihr stellt meine Geduld auf die Probe.', '', 28153),
(156245, 'deDE', 'Unser Werk hat erst begonnen.', '', 28153),
(156244, 'deDE', 'Auf ein Wiedersehen.', '', 28153),
(156243, 'deDE', 'Möge das Licht mit Euch sein.', '', 28153),
(156242, 'deDE', 'Bei der Macht der Allianz, unsere Feinde werden untergehen.', '', 28153),
(156241, 'deDE', 'Beim Licht, der erste Schlag wird unserer sein.', '', 28153),
(156240, 'deDE', 'Um Euch ranken sich mehr und mehr Legenden.', '', 28153),
(156239, 'deDE', 'Das Schicksal ist uns heute hold.', '', 28153),
(156238, 'deDE', 'Die Horde wird fallen.', '', 28153),
(156237, 'deDE', 'Soldat.', '', 28153),
(156236, 'deDE', 'Wir sind die Söhne und Töchter der Allianz.', '', 28153),
(156235, 'deDE', '', 'Diese Welt muss beschützt werden. Vorwärts, Dunkeleisenzwerge! Wir marschieren in die Schlacht.', 28153),
(156234, 'deDE', '', 'Das gleiche Blut, das unsere Adern durchfließt... fließt auch durch Azeroth.', 28153),
(156233, 'deDE', '', 'Mit Hammer und Amboss wurde unser Königreich geschmiedet, mit feurigen Herzen... und eisernem Willen.', 28153),
(156232, 'deDE', '', 'Der Berg gibt uns Leben, gibt uns Kraft.', 28153),
(156231, 'deDE', '', 'Thurgaden und Thaelin haben Euch in Anerkennung Eurer Taten ein Rüstungsset geschmiedet. Tragt es mit Stolz, $n.', 28153),
(156230, 'deDE', '', 'Jetzt weiß die Allianz, dass wir es ernst meinen. Ich hätte mir keinen besseren Champion wünschen können.', 28153),
(156229, 'deDE', '', 'Kehrt in den Berg zurück. Wir haben was Besonderes für Euch.', 28153),
(156228, 'deDE', '', 'Ihr habt uns wirklich stolz gemacht, $n. Ich habe von Eurer Tapferkeit an der Oberfläche von Azeroth gehört.', 28153),
(156227, 'deDE', '', 'In den Flammen des Berges wurden wir geschmiedet, $n. Zeigt der Welt unser Feuer.', 28153),
(156226, 'deDE', '', 'Azeroth erwartet Euch. Begebt Euch zunächst nach Sturmwind.', 28153),
(156225, 'deDE', '', 'Es ist Zeit, dass die Dunkeleisenzwerge aus den Schatten treten.', 28153),
(156224, 'deDE', '', 'Viele der unseren haben uns davon abgeraten, an die Oberfläche zu reisen. Aber die Mutigen tun es trotzdem.', 28153),
(156223, 'deDE', 'Für die Allianz!', '', 28153),
(156222, 'deDE', '', 'Die Dunkeleisenzwerge nehmen Eure Einladung an. Für die Allianz!', 28153),
(156221, 'deDE', '', 'Ach, kein Problem, Majestät. Reine Formsache.', 28153),
(156220, 'deDE', 'Dennoch haben wir Euren Klan nie offiziell dazu eingeladen, der Allianz beizutreten... Ein Fehler, den Ihr mir hoffentlich erlaubt, zu korrigieren.', '', 28153),
(156219, 'deDE', '', 'Ja.', 28153),
(156218, 'deDE', 'Und obwohl die Dunkeleisenzwerge bekannt sind für ihre... Unabhängigkeit, steht die Hingabe und Loyalität Eures Volkes außer Frage.', '', 28153),
(156217, 'deDE', 'Eure Position im Rat der Drei Hämmer hat geholfen, Ordnung und Stabilität in Eisenschmiede aufrecht zu erhalten.', '', 28153),
(156216, 'deDE', '', 'Ebenfalls, König Wrynn.', 28153),
(156215, 'deDE', 'Königin-Regentin Thaurissan. Es freut mich, Euch wiederzusehen.', '', 28153),
(156214, 'deDE', 'Hey! Ich hier am Arbeiten!', '', 28153),
(156213, 'deDE', '', 'Danke. Wir müssen bewahren, was von Drustvars Höfen noch bleibt.', 28153),
(156212, 'deDE', '', 'Die Schweine eines örtlichen Bauernhofs sind im Dickicht des Waldes verschwunden. Rettet sie, bevor sie den Sporen verfallen!', 28153),
(156211, 'deDE', '', 'Die Hexen sind enttarnt und meine Leute sind wieder sicher. Ich danke Euch.', 28153),
(156210, 'deDE', '', 'Der Zirkel versucht, Aroms Wehr zu unterwandern. Deckt ihre verräterischen Aktivitäten auf und brennt ihre Verderbnis aus, bevor sie jemandem schaden können.', 28153),
(156209, 'deDE', '<Übergebt das Gerinnungspulver: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Übergebt das Gerinnungspulver: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'deDE', '<Übergebt die uralte tortollanische Schriftrolle: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Übergebt die uralte tortollanische Schriftrolle: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'deDE', '<Übergebt die Seeigellauge: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Übergebt die Seeigellauge: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'deDE', '<Übergebt die adstringierenden Gewürze: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Übergebt die adstringierenden Gewürze: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'deDE', 'Bleibt wachsam, $n. Ich werde Euch weitere Anweisungen geben, wenn ich für mehr Zutaten bereit bin.', '', 28153),
(156204, 'deDE', 'Das hier is\' jenseits unser aller Macht. Der Loa des Todes hat ihn uns genomm\'n!', '', 28153),
(156203, 'deDE', 'Tja, bedaure. Dies geht leider ein wenig über meine Fähigkeiten hinaus.', '', 28153),
(156202, 'deDE', 'Jamil Abul\'housin kauert vor Angst nieder!', '', 28153),
(156201, 'deDE', '...Jamil?', '', 28153),
(156200, 'deDE', 'Jede Sekunde.', '', 28153),
(156199, 'deDE', 'So... Jetzt sollte der König erwachen.', '', 28153),
(156198, 'deDE', 'Seine Blutung lässt sich nicht stillen. Schnell, $n, bringt mir sofort das Gerinnungspulver!', '', 28153),
(156196, 'deDE', 'Jamil Abul\'housins Gesänge werden immer lauter und verzweifelter.', '', 28153),
(156195, 'deDE', 'Fertig! Ich werde den Trank nun verabreichen.', '', 28153),
(156194, 'deDE', 'Jamil Abul\'housin intoniert leise ein Gebet.', '', 28153),
(156193, 'deDE', 'Nun gut, DREI Prisen.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'deDE', 'Siebenhundert Jahre sind vergangen, seit ich es zuletzt zubereitet habe. Ihr würdet Euch noch nicht einmal an etwas erinnern, das älter als der Großvater Eures Großvaters ist.', '', 28153),
(156191, 'deDE', 'Ihr habt das Rezept vergess\'n?!', '', 28153),
(156190, 'deDE', 'Waren das ein oder zwei Prisen...? $n, bringt mir meine Schriftrolle.', '', 28153),
(156188, 'deDE', 'Habt Dank. Ich mische es, so schnell ich kann. Nur Geduld.', '', 28153),
(156187, 'deDE', 'Nichts? Jol, beeilt Euch lieber mit dem Heilmittel...', '', 28153),
(156186, 'deDE', 'Jetzt die Lauge. Seht in der Speisekammer nach.', '', 28153),
(156185, 'deDE', 'Lasst die Kroggs nicht entkommen!', 'Lasst die Kroggs nicht entkommen!', 28153),
(156184, 'deDE', 'Ich bin bereit, Jol.', 'Ich bin bereit, Jol.', 28153),
(156183, 'deDE', 'Diese Zutaten sind knifflig. Sie werden meine ganze Aufmerksamkeit brauchen. Ihr müsst mir zur Hand gehen, um dieses Gebräu fertigzustellen. Denkt daran, das Leben des Königs steht auf dem Spiel.\n\nSeid Ihr bereit, anzufangen?', '', 28153),
(156182, 'deDE', '', 'Wenn das wahr is\', was der Verbannte behauptet, dann müsst Ihr das untersuch\'n. Aber Vorsicht, Jakra\'zet könnte noch dort sein.', 28153),
(156181, 'deDE', 'Also, ich hätte nicht gedacht, dass Euch das interessiert! Wo soll ich anfangen?\n\nWir unternehmen diese Pilgerreise nach Nazmir alle paar Jahre. Manchmal liegen fünf und manchmal auch zwanzig Jahre dazwischen. Alles hängt davon ab, wann Torga bereit ist, eine Geschichte zu erzählen.\n\nWenn wir Gerüchte hören, dass Torga bereit sein soll, uns seine Geschichten mitzuteilen, begeben wir uns auf die Reise. Wir kommen hierher, setzen uns und hören uns alle Geschichten an, die Torga zu erzählen hat. Und dann erzählen wir diese Geschichten allen weiter, denen wir begegnen.\n\nIhr könnt Euch glücklich schätzen. Es kommen nicht oft so viele von uns zusammen. Das selbst ist schon eine Geschichte, falls Eure Leute so etwas interessiert.', '', 28153),
(156180, 'deDE', 'Nur über... meine Leiche...', 'Nur über... meine Leiche...', 28153),
(156179, 'deDE', 'Erzählt mir von Eurer Pilgerschaft.', 'Erzählt mir von Eurer Pilgerschaft.', 28153),
(156178, 'deDE', 'Solange ich hier bin, entkommt niemand!', 'Solange ich hier bin, entkommt niemand!', 28153),
(156177, 'deDE', 'Sagen wir, unentschieden.', '', 28153),
(156176, 'deDE', 'Ein neues Schießpulver. So was hab ich noch nie gesehen.', '', 28153),
(156175, 'deDE', 'Boralus gehört mir.', '', 28153),
(156174, 'deDE', 'Was geschieht?', 'Was geschieht?', 28153),
(156173, 'deDE', '', 'Für die Horde!', 28153),
(156172, 'deDE', '', 'Sehr gut! Und jetzt an den Sprengstoffen vorbei und über die Brücke.', 28153),
(156171, 'deDE', '', 'Macht weiter! Ruft alle Wachen der Stadt zusammen... und ihre Anführer!', 28153),
(156170, 'deDE', '', 'Kommt und holt uns doch, Feiglinge!', 28153),
(156169, 'deDE', '', 'Die Horde wird Euch zerfleischen!', 28153),
(156168, 'deDE', '', 'Kul Tiraner! Euer Abkommen mit der Allianz wird Euer Todesurteil sein!', 28153),
(156167, 'deDE', '', 'Begebt Euch in die Stadt und bringt so viele Wachen wie möglich dazu, Euch zu folgen!', 28153),
(156166, 'deDE', '', 'Finn! Hier drüben!', 28153),
(156165, 'deDE', 'Wie konnte ich nur versagen?', 'Wie konnte ich nur versagen?', 28153),
(156164, 'deDE', '', 'Es reicht. Erledigt den Hauptmann, und die Nebelfockfreibeuter behalten ihre Freiheit!', 28153),
(156163, 'deDE', '', 'Soso, Ihr steht also auf düstere Typen, hm? Mädchen... Ihr habt ja keine Ahnung...', 28153),
(156162, 'deDE', '', 'Ist schon witzig... Ich habe nie bemerkt, dass ich meinen Kul Tiraner Akzent verloren hab.', 28153),
(156161, 'deDE', '', 'Natürlich habe ich meinen Verwandlungsstab dabei. Was denkt Ihr, von wem der Begriff \"Wollomant\" kommt?', 28153),
(156160, 'deDE', 'Lasst uns ein paar Waffen stehlen, bevor wir gehen.', 'Lasst uns ein paar Waffen stehlen, bevor wir gehen.', 28153),
(156159, 'deDE', 'Leute zu kaufen und verkaufen... Das ist einfach nicht richtig.', 'Leute zu kaufen und verkaufen... Das ist einfach nicht richtig.', 28153),
(156158, 'deDE', 'Rühren', 'Rühren', 28153),
(156157, 'deDE', 'Wir Vulpera machen das nicht mehr mit!', 'Wir Vulpera machen das nicht mehr mit!', 28153),
(156156, 'deDE', 'Die haben uns nicht zum letzten Mal gesehen!', '', 28153),
(156155, 'deDE', 'Ich will in meinem ganzen Leben keinen Sethrak mehr sehen.', 'Ich will in meinem ganzen Leben keinen Sethrak mehr sehen.', 28153),
(156154, 'deDE', 'Und genau deshalb legt man sich nicht mit Schildkröten an!', '', 28153),
(156153, 'deDE', 'Ich glaube, die wollten mich fressen!', 'Ich glaube, die wollten mich fressen!', 28153),
(156152, 'deDE', 'Bei der Wüstensonne, bin ich froh, dass Ihr hier seid!', 'Bei der Wüstensonne, bin ich froh, dass Ihr hier seid!', 28153),
(156151, 'deDE', '', 'Nach all diesen Jahren denkt Ihr immer noch, Ihr könnt mich knacken? Manche Dinge ändern sich nie...', 28153),
(156150, 'deDE', '', 'Die wahre Schlacht liegt vor uns.', 28153),
(156149, 'deDE', '', 'Ich werde tun, was ich kann.', 28153),
(156148, 'deDE', '', 'Der Weg vor uns wird kein leichter sein.', 28153),
(156147, 'deDE', 'Das schmerzt mehr, als ich erwartet hatte.', 'Das schmerzt mehr, als ich erwartet hatte.', 28153),
(156146, 'deDE', 'Ich hab mir ein paar ihrer Kristalle genommen... Mal sehen, wer hier zuletzt lacht. Ha!', '', 28153),
(156145, 'deDE', 'Dieser Panzer steht nicht zum Verkauf!', '', 28153),
(156144, 'deDE', 'Diese Sethrak können sich mich sowieso nicht leisten.', '', 28153),
(156143, 'deDE', 'Die Treulosen haben keinerlei Respekt vor dem Alter oder vor Weisheit.', '', 28153),
(156142, 'deDE', 'Die Geschichte werde ich allen in Zuldazar erzählen!', '', 28153),
(156141, 'deDE', '', 'Wir dürfen die Welt nicht der Dunkelheit überlassen.', 28153),
(156140, 'deDE', 'Endlich ist das Glück mal auf meiner Seite!', '', 28153),
(156139, 'deDE', 'Der Kriegshäuptling fordert, dass wir die Allianztruppen in dieser Region dezimieren. Macht kurzen Prozess mit ihnen!', '', 28153),
(156138, 'deDE', '', 'Die Zeit für Träume ist vorbei.', 28153),
(156137, 'deDE', 'Diese Allianznarren haben in der Nähe Stellung bezogen. Stattet ihnen einen Besuch ab und zeigt ihnen, wie vergebens ihr Vorhaben ist.', '', 28153),
(156136, 'deDE', 'Truppen der Allianz treiben sich in Eurer Nähe herum. Sorgt dafür, dass es das Letzte ist, was sie tun.', '', 28153),
(156135, 'deDE', '', 'Was begehrt Ihr von der Tochter der See?', 28153),
(156134, 'deDE', 'Die Allianz zerfällt vor unserer Macht! Die Dunkle Fürstin wird erfreut sein.', '', 28153),
(156133, 'deDE', 'Eine beeindruckende Unbarmherzigkeit! Die Allianz hat unseren ganzen Zorn zu spüren bekommen.', '', 28153),
(156132, 'deDE', 'Feuer frei!', '', 28153),
(156131, 'deDE', 'Allianztruppen... einfach jämmerlich. Sie werden es sich gründlich überlegen, uns erneut zu trotzen.', '', 28153),
(156130, 'deDE', '', 'Vor uns liegt ein langer Weg.', 28153),
(156129, 'deDE', 'Haltet die Luft an, $p!', '', 28153),
(156128, 'deDE', '', 'Die Allianz wird bestehen.', 28153),
(156127, 'deDE', '', 'Ich weiß, was getan werden muss.', 28153),
(156126, 'deDE', '', 'Ein Funke kann die ganze Welt in Brand stecken.', 28153),
(156125, 'deDE', '', 'Kontrolliert Eure Macht... oder sie kontrolliert Euch.', 28153),
(156124, 'deDE', 'Für Lordaeron.', 'Für Lordaeron.', 28153),
(156123, 'deDE', '', 'Ich werde niemals vergessen.', 28153),
(156122, 'deDE', '', 'Wir alle haben unsere Dämonen.', 28153),
(156121, 'deDE', 'Endlich ein bisschen Aufregung!', 'Endlich ein bisschen Aufregung!', 28153),
(156120, 'deDE', '', 'Gebt Acht, wem Ihr vertraut.', 28153),
(156119, 'deDE', 'Meine Seele dürstet.', 'Meine Seele dürstet.', 28153),
(156118, 'deDE', 'Zeit, zu bluten!', 'Zeit, zu bluten!', 28153),
(156117, 'deDE', 'Ich weiß effizientes Töten durchaus zu schätzen. Sorgt dafür, dass der Krieg nach Plan verläuft.', '', 28153),
(156116, 'deDE', 'Typisch. Ein weiterer Feind, der sich der Macht der Horde stellt... und verliert.', '', 28153),
(156115, 'deDE', 'Die Dunkle Fürstin wählt ihre Champions weise.', '', 28153),
(156114, 'deDE', 'Eine angemessen gründliche Ausführung... wenn auch etwas grobschlächtig. Ihr dürft wieder Euren regulären Aufgaben nachgehen.', '', 28153),
(156113, 'deDE', 'Ah... wie befriedigend es doch ist, einen Gegner zurechtzustutzen. Die Pflicht soll uns nicht davon abhalten, den Sieg zu genießen!', '', 28153),
(156112, 'deDE', 'Gute Arbeit. Unsere Vorhaben können wie geplant voranschreiten.', '', 28153),
(156111, 'deDE', 'Die Horde wird dieses Gebiet schon bald beanspruchen, doch noch hindert uns ein mächtiger Gegner daran. Macht unseren Truppen den Weg frei.', '', 28153),
(156110, 'deDE', 'In den Plänen des Kriegshäuptlings für dieses Gebiet ist kein Platz für dieses... Monster. Schaltet es aus!', '', 28153),
(156109, 'deDE', '', 'Hört mal, Ihr Naseweis... Habt Ihr je daran gedacht, dass EURE Zeitlinie die \"alternative Geschichte\" ist und nicht MEINE? Ha... da fehlen Euch die Worte, was?', 28153),
(156108, 'deDE', 'Ein beachtlicher Gegner hält sich nahe Eurer Position auf. Beschafft unseren Forschern eine Leiche zum Sezieren, ja?', '', 28153),
(156107, 'deDE', 'Ein Feind in der Nähe hat kurzen Prozess mit unseren jämmerlichen Rekruten gemacht. Ich schätze, ein \"Champion der Horde\" wird sich besser schlagen.', '', 28153),
(156106, 'deDE', '', 'Ihr habt einen Krieg gegen die Legion geführt... aber uns nicht gerufen? Wirklich? Das Schicksal des ganzen Kosmos hing am seidenen Faden, aber Ihr konntet Euch nicht aufraffen... Hmpf, egal!', 28153),
(156105, 'deDE', 'Berichte weisen darauf hin, dass sich ein mächtiger Gegner in Eurer Nähe befindet. Bringt ihn zur Strecke... und ergötzt Euch daran!', '', 28153),
(156104, 'deDE', 'Der Kriegshäuptling fordert, dass Ihr ein Ziel in dieser Gegend ausschaltet. Enttäuscht sie nicht.', '', 28153),
(156103, 'deDE', '', 'Seit ich hier angekommen bin, scheinen die Orcs in Orgrimmar strammer zu stehen.', 28153),
(156102, 'deDE', '', 'Thrallt Euch.', 28153),
(156101, 'deDE', 'Ich hatte schon langsam Hunger...', 'Ich hatte schon langsam Hunger...', 28153),
(156100, 'deDE', '', 'Sprecht rasch. Wir haben Schlachten zu gewinnen!', 28153),
(156099, 'deDE', '', 'Das Herz der Mag\'har ist rein und stark.', 28153),
(156098, 'deDE', '', 'Wir sind hier, diesen Krieg zu gewinnen.', 28153),
(156097, 'deDE', '', 'Ich höre Eure Worte... aber Eure Taten sind es, an denen ich Euch messe.', 28153),
(156096, 'deDE', '', 'Ich will mir nicht vorstellen, was geschehen wäre, wenn wir das Ritual nicht aufgehalten hätten. Danke für Eure Hilfe.', 28153),
(156095, 'deDE', '', 'Sprecht.', 28153),
(156094, 'deDE', '', 'Wir werden Draenors Himmel wiedersehen.', 28153),
(156093, 'deDE', '', 'Krieg ist unser Leben.', 28153),
(156092, 'deDE', '', 'Mögen Eure Feinde vor Euch kriechen.', 28153),
(156091, 'deDE', '', 'Die Hexen in Korlach haben mit der Durchführung eines neuen Rituals begonnen. Haltet sie auf, bevor sie es vollenden!', 28153),
(156090, 'deDE', '', 'Kämpft ehrenhaft. Sterbt glorreich!', 28153),
(156089, 'deDE', '', 'Die Mag\'har werden siegreich sein.', 28153),
(156088, 'deDE', '', 'Sterbt wohl.', 28153),
(156087, 'deDE', '', 'Geht mit Ehre!', 28153),
(156086, 'deDE', '', 'Throm-ka!', 28153),
(156085, 'deDE', '', 'Lok-tar!', 28153),
(156084, 'deDE', 'Die armen Vögel... Mögen ihre Seelen Freiheit finden.', '', 28153),
(156083, 'deDE', 'Die Falken hier stehen unter dem Fluch der Hexen. Ich wünschte, wir könnte sie retten, aber sie sind hoffnungslos verloren. Mit diesen Zwiebeln solltet Ihr ihrer Herr werden!', '', 28153),
(156082, 'deDE', '', 'Gut gemacht. Wann wird die Allianz begreif\'n, dass sich die Zandalari nich\' aufhalt\'n lass\'n?', 28153),
(156081, 'deDE', '', 'Gute Arbeit. Die Allianz wird lern\', die Macht der Zandalari zu fürcht\'n.', 28153),
(156080, 'deDE', '', 'Die Allianz wird bald begreif\'n, dass die Zandalari nich\' bezwungen werd\'n könn\'.', 28153),
(156079, 'deDE', '', 'Ich hab Berichte erhalt\'n, dass die Allianz ihre Truppen in der Nähe sammelt. Ihr müsst ihre Pläne durchkreuz\'n!', 28153),
(156078, 'deDE', '', 'Die Allianz glaubt, sie könnte dem Zandalariimperium trotz\'n. Zeigt ihnen, wie sehr sie sich irr\'n.', 28153),
(156077, 'deDE', '', 'Auf geht\'s, Jungs, jetzt heißt es: Meuterei! Wir Nebelfockfreibeuter weigern uns, unsere Freiheit zu verkaufen!', 28153),
(156076, 'deDE', '', 'Am Anfang war ich genervt von diesem ganzen \"Ja, meine Königin\" hier, \"Sofort, meine Königin\" da, aber... na ja... es sei Euch gestattet!', 28153),
(156075, 'deDE', '', 'Ganz in der Nähe plant die Allianz irgendwas. Schaltet sie aus. Lehrt sie, das Zandalariimperium zu fürcht\'n.', 28153),
(156074, 'deDE', 'Ah. Es ist äußerst beruhigend zu wissen, dass dieses Problem aus der Welt geschafft wurde.', '', 28153),
(156073, 'deDE', 'Die Soldaten, die für die Allianz kämpfen, werden Euch Euer Handeln am heutigen Tage nicht vergessen.', '', 28153),
(156072, 'deDE', 'Gute Arbeit. Ich werde Euch einige Geschichten aus dem Dritten Krieg erzählen müssen. All das erinnert mich an die alten Tage.', '', 28153),
(156071, 'deDE', 'Gute Arbeit. Diese Ressourcen werden uns auf lange Sicht sehr hilfreich sein.', '', 28153),
(156070, 'deDE', 'Dieses Gebiet bereitet unseren Truppen Probleme. Erinnert mich an den Zweiten Krieg. Könntet Ihr uns zur Hand gehen?', '', 28153),
(156069, 'deDE', 'Jemand muss sich um gewisse Probleme in diesem Gebiet kümmern. Bekommt Ihr das hin?', '', 28153),
(156068, 'deDE', '', 'Ihr denkt, EURE Eltern können hart sein? Habt Ihr einen Vater aus verdammtem Diamant?', 28153),
(156067, 'deDE', 'Das Gebiet in Eurer Nähe könnte uns sehr nützlich sein. Wir müssen es räumen und sichern.', '', 28153),
(156066, 'deDE', 'Wir haben Berichte über kritische Ressourcen in der Nähe erhalten. Sie zu sichern könnte den Verlauf des Krieges entscheidend beeinflussen.', '', 28153),
(156065, 'deDE', '', 'Nur zu... reißt einen Zwergenwitz. Wir werden sehen, wie gut Ihr ohne Kniescheiben zurecht kommt!', 28153),
(156064, 'deDE', 'Versaut mir nich\' den königlichen Groove.', '', 28153),
(156063, 'deDE', 'Was macht Ihr hier?', 'Was macht Ihr hier?', 28153),
(156062, 'deDE', '', 'Kiro und ich sind nur auf der Durchreise. Unser nächster Halt ist das Reich der Treulosen. \n\nMein Plan wird aufgehen. \n\nDiese Sethrak werden eine böse Überraschung erleben.', 28153),
(156061, 'deDE', '', 'So sieht man sich wieder.', 28153),
(156060, 'deDE', 'Ihr ehrt die Gefallenen der 7. Legion. Wir werden großen Nutzen aus diesem Gebiet ziehen.', '', 28153),
(156059, 'deDE', 'Ihr habt Euch gut geschlagen. Überlasst den Rest meinen Soldaten.', '', 28153),
(156058, 'deDE', '', 'Mein Volk lebt in einem Vulkan. Schürt weiter das Feuer und ich zeige Euch, wie ein Dunkeleisenzwerg ausbricht!', 28153),
(156057, 'deDE', 'Ausgezeichnet taktiert. Wir werden dieses Gebiet schon bald für uns nutzen können.', '', 28153),
(156056, 'deDE', 'Gute Arbeit. Damit wird bei der 7. Legion eine ganze Weile lang keine Ressourcenknappheit aufkommen.', '', 28153),
(156055, 'deDE', 'Wir brauchen Eure Hilfe dabei, dieses Gebiet zu sichern. Meine Truppen schaffen es nicht allein.', '', 28153),
(156054, 'deDE', 'Viele meiner Soldaten sind beim Versuch gefallen, diese Gegend einzunehmen. Schaltet die dortige Bedrohung aus.', '', 28153),
(156053, 'deDE', 'Späher der 7. Legion haben ermittelt, dass dieser Ort von extremer Bedeutung ist. Sichert ihn für uns.', '', 28153),
(156052, 'deDE', '', 'Die Drei Hämmer stehen Seite an Seite.', 28153),
(156051, 'deDE', 'Die 7. Legion benötigt Ressourcen, die sich in der Nähe finden lassen. Sichert sie um jeden Preis.', '', 28153),
(156050, 'deDE', '', 'Auf dass Euer Hammer nie verfehlt.', 28153),
(156049, 'deDE', '', 'Möge der Schwarze Amboss über Euch wachen.', 28153),
(156048, 'deDE', '', 'Die Dunkeleisenzwerge fordern ihren rechtmäßigen Platz in dieser Welt.', 28153),
(156047, 'deDE', '', 'Geht jetzt. Auf mich wartet Arbeit!', 28153),
(156046, 'deDE', '', 'Ihr dürft Euch entfernen.', 28153),
(156045, 'deDE', '', 'Ihr seid entschuldigt.', 28153),
(156044, 'deDE', 'Bombardiert mein Ziel!', 'Bombardiert mein Ziel!', 28153),
(156043, 'deDE', 'Kanonen! Feuer!', 'Kanonen! Feuer!', 28153),
(156042, 'deDE', 'Ziel für Zerstörung markiert!', 'Ziel für Zerstörung markiert!', 28153),
(156041, 'deDE', 'Artillerie! Auf mein Ziel feuern!', 'Artillerie! Auf mein Ziel feuern!', 28153),
(156040, 'deDE', '', 'Kommen wir zum Geschäft.', 28153),
(156039, 'deDE', '', 'Ja? Ich höre.', 28153),
(156038, 'deDE', '', 'Wählt Eure Worte mit Bedacht in Anwesenheit einer Königin.', 28153),
(156037, 'deDE', 'Wie schön, dass die Sande Euch noch nicht verschlungen haben.', '', 28153),
(156036, 'deDE', '', 'Der Berg verleiht uns seine Stärke.', 28153),
(156035, 'deDE', '', 'Ihr richtet das Wort an die Königin-Regentin des Dunkeleisenklans.', 28153),
(156034, 'deDE', '', 'Der Dunkeleisenklan wird den Respekt erhalten, der ihm zusteht.', 28153),
(156033, 'deDE', '', 'Die Allianz vertraut genauso auf unsere Magie, wie auf unsere Stärke.', 28153),
(156032, 'deDE', 'Ankleiden', 'Ankleiden', 28153),
(156031, 'deDE', 'Entfernen', 'Entfernen', 28153),
(156030, 'deDE', '', 'Ausgezeichnete Arbeit. Die Ressourcen werd\'n den Zandalari sehr nützlich sein.', 28153),
(156029, 'deDE', '', 'Beeindruckend. Schon bald werden alle wiss\'n, dass man sich nich\' mit dem Zandalariimperium anleg\'n sollte.', 28153),
(156028, 'deDE', '', 'Noch \'n Sieg für den Champion der Horde. Ich könnt mich dran gewöhn\', Euch zu mein\' Verbündeten zu zähl\'n.', 28153),
(156027, 'deDE', '', 'Die Zandalari dank\'n Euch für Eure Hilfe.', 28153),
(156026, 'deDE', '', 'Nathanos glaubt nich\', dass wir dieses Gebiet erobern könn\'. Beweist ihm das Gegenteil.', 28153),
(156025, 'deDE', '', 'Das Gebiet in Eurer Nähe muss von Gefahren befreit werd\'n, damit unsre Kampagne voranschreit\'n kann... \'ne Aufgabe wie für Euch gemacht.', 28153),
(156024, 'deDE', '', 'Wir müss\'n dafür sorg\'n, dass dieses Gebiet für unsre Verbündeten sicher is\'. Zeigt denen, die sich Euch widersetz\'n, keine Gnade.', 28153),
(156023, 'deDE', '', 'In der Nähe gibt\'s Ressourcen, die für unsre Kampagne nützlich sein könnt\'n. Ihr müsst sie beschaff\'n.', 28153),
(156022, 'deDE', 'Dot und Dolly werden das im Handumdrehen verschlingen.', '', 28153),
(156021, 'deDE', 'Dot und Dolly sind launische Kreaturen. Mit leerem Magen arbeiten sie nicht. Helft dabei, etwas zu essen für sie zu finden!', '', 28153),
(156020, 'deDE', 'Husch!', 'Husch!', 28153),
(156019, 'deDE', 'Ihr verschwinden!', 'Ihr verschwinden!', 28153),
(156018, 'deDE', 'Ihr nicht anfassen!', 'Ihr nicht anfassen!', 28153),
(156017, 'deDE', 'Ihr näherkommen, ich Euch Stein auf Schädel hauen!', 'Ihr näherkommen, ich Euch Stein auf Schädel hauen!', 28153),
(156016, 'deDE', 'Ihr weggehen, sonst ich Euch totmachen!', 'Ihr weggehen, sonst ich Euch totmachen!', 28153),
(156015, 'deDE', '', 'Geht! Sammelt alles Nötige, um die Schlange zu heil\'n. Ich erzähl Julwaba, was wir wiss\'n.', 28153),
(156014, 'deDE', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNeues Bauwerk verfügbar!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNeues Bauwerk verfügbar!', 28153),
(156013, 'deDE', 'Ich habe vielen Kriegshäuptlingen gedient. Zieht hinaus in die Welt und Ihr werdet sicher den ein oder anderen treffen.', '', 28153),
(156012, 'deDE', 'Warum gebt Ihr keine Ruhe? Gibt es eine neue Schlacht zu schlagen? Was rede ich denn... es gibt IMMER eine neue Schlacht zu schlagen.', '', 28153),
(156011, 'deDE', 'Wenn Ihr wüsstet, welches Meer von Blut meine Axt vergossen hat, wärt Ihr vorsichtiger mit Eurem Finger.', '', 28153),
(156010, 'deDE', 'Ich bin zu alt für diesen Blödsinn.', '', 28153),
(156009, 'deDE', 'Ich diene der Horde.', '', 28153),
(156008, 'deDE', 'Sprecht rasch... und sprecht redlich.', '', 28153),
(156007, 'deDE', 'Das ist nicht die Zeit für Höflichkeiten.', '', 28153),
(156006, 'deDE', 'Was braucht Ihr von mir?', '', 28153),
(156005, 'deDE', 'Throm-ka!', '', 28153),
(156004, 'deDE', 'Lok-tar!', '', 28153),
(156003, 'deDE', 'Ich bin Saurfang. Bruder von Broxigar.', '', 28153),
(156002, 'deDE', 'Die Horde wird bestehen.', '', 28153),
(156001, 'deDE', 'Ich das nicht mehr mögen. Ich jetzt laufen!', 'Ich das nicht mehr mögen. Ich jetzt laufen!', 28153),
(156000, 'deDE', 'In der Schlacht ist Strategie genauso entscheidend wie Stärke.', '', 28153),
(155999, 'deDE', 'Hurra! Ich frei!', 'Hurra! Ich frei!', 28153),
(155998, 'deDE', 'Ich jetzt abhauen!', 'Ich jetzt abhauen!', 28153),
(155997, 'deDE', 'Wir sind die wahre Macht Kalimdors.', '', 28153),
(155996, 'deDE', 'Warum das passieren?', 'Warum das passieren?', 28153),
(155995, 'deDE', 'Ich nicht sterben, Ihr mir Deckung geben!', 'Ich nicht sterben, Ihr mir Deckung geben!', 28153),
(155994, 'deDE', 'Was passieren?!', 'Was passieren?!', 28153),
(155993, 'deDE', 'Vorsichtig sein, verrückte Menschen überall!', 'Vorsichtig sein, verrückte Menschen überall!', 28153),
(155992, 'deDE', 'Werdet nicht alt... wenn Ihr es vermeiden könnt.', '', 28153),
(155991, 'deDE', 'Ohne Ehre sind wir nur Staub und Schatten.', '', 28153),
(155990, 'deDE', 'Ein ehrenhafter Tod auf dem Schlachtfeld ist ein Tod, der eines Orcs würdig ist.', '', 28153),
(155989, 'deDE', 'Mögt Ihr im Kampf gegen einen verhassten Feind sterben.', '', 28153),
(155988, 'deDE', 'Versucht, Na\'logo zum sicheren Seetang zu führen.', '', 28153),
(155987, 'deDE', '\"Na\'logo und das Meer\" – Ein junger Tortollaner muss sich in Sicherheit bringen, direkt nachdem er aus dem Sand gekrochen ist.', '', 28153),
(155986, 'deDE', '', 'Die Streitkräfte der Hexen sind besiegt, und unsere Holzfäller können wieder ihre Arbeit machen. Vielen Dank, dass Ihr sie beschützt habt.', 28153),
(155985, 'deDE', 'Ich mach das hier gleich mal weg...', '', 28153),
(155984, 'deDE', '', 'Die Hexen haben ihre Schergen ausgesandt, um unsere Holzfällerlager einzunehmen. Versammelt die Waldarbeiter. Räuchert die Hexen aus!', 28153),
(155983, 'deDE', '', 'Schnitztal ist wieder frei vom Einfluss des Zirkels. Habt Dank.', 28153),
(155982, 'deDE', '', 'Schnitztal wurde vom Zirkel überrannt! Befreit seine Bewohner und erobert die Stadt zurück!', 28153),
(155981, 'deDE', 'Psssst... Hier drüb\'n, $n!', '', 28153),
(155980, 'deDE', '', 'Wir müssen für das einstehen, was richtig ist.', 28153),
(155979, 'deDE', '', 'Wenn die Zeit kommt, bin ich bereit.', 28153),
(155978, 'deDE', '', 'Ans Werk.', 28153),
(155977, 'deDE', '', 'Wir müssen denen helfen, die sich nicht selbst helfen können.', 28153),
(155976, 'deDE', '', 'Ohne Ehre sind wir nichts.', 28153),
(155975, 'deDE', '', 'Wenn Ihr IRGENDJEMANDEM davon erzählt, verfüttere ich Euch an meinen Greifen, kapiert?!', 28153),
(155974, 'deDE', '', 'Ich kämpfe bis zum bitteren Ende.', 28153),
(155973, 'deDE', '', '<grunz> Oh, nein... D-das habt Ihr nicht gehört.', 28153),
(155972, 'deDE', '', 'Ich bin... eine höchst disziplinierte... Knappin mit einem... eisernen Willen...', 28153),
(155971, 'deDE', '', 'Kommt schon, das kitzelt! Hört auf damit!', 28153),
(155970, 'deDE', '', 'Hey! Lasst das!', 28153),
(155969, 'deDE', '', 'Wir schaffen das.', 28153),
(155968, 'deDE', '', 'Dient ehrenhaft.', 28153),
(155967, 'deDE', '', 'Haltet den Kurs.', 28153),
(155966, 'deDE', '', 'Möge der Wind immer in Eurem Rücken sein, Freunde. Ich aber muss bei den Vulpera kämpfen.', 28153),
(155965, 'deDE', '', 'Erzählt mir alles, wenn Ihr zurück seid!', 28153),
(155964, 'deDE', '', 'Für Kul Tiras!', 28153),
(155963, 'deDE', '', 'Die Pflicht ruft.', 28153),
(155962, 'deDE', '', 'Lebt wohl.', 28153),
(155961, 'deDE', '', 'Wie ist die Lage?', 28153),
(155960, 'deDE', '', 'Endlich passiert mal was!', 28153),
(155959, 'deDE', '', 'Dafür habe ich mein Leben lang trainiert.', 28153),
(155956, 'deDE', '', 'Gemeinsam können wir Kul Tiras vereinen.', 28153),
(155955, 'deDE', '', 'Ich habe immer von Abenteuern geträumt.', 28153),
(155953, 'deDE', 'Zuhause ist, wo das Tal ist.', '', 28153),
(155952, 'deDE', 'Ich halte Euch den Rücken frei und Ihr mir.', '', 28153),
(155950, 'deDE', 'Passt auf Euch auf da draußen.', '', 28153),
(155947, 'deDE', 'Wir sitzen alle im gleichen Boot.', '', 28153),
(155946, 'deDE', '', 'Status: Neuerschaffungsexplosion erreicht Energiemaximum.', 28153),
(155945, 'deDE', '', 'Achtung. Neuerschaffungsexplosion bald bei voller Kapazität.', 28153),
(155944, 'deDE', '', 'Achtung. Volle Kraft fast erreicht.', 28153),
(155943, 'deDE', '', 'Status: Energiepegel erreicht Maximum.', 28153),
(155942, 'deDE', 'Mit einem Tag harter Arbeit kann man alles ins Lot bringen.', '', 28153),
(155941, 'deDE', 'Mein Herz schlägt für das Tal.', '', 28153),
(155939, 'deDE', '', 'Was kann ich tun?', 28153),
(155938, 'deDE', 'Hört Ihr das? Die Tiefen flüstern etwas. Sie... sie flüstern über Euch! Wie war das? Aha. Verstehe. Sie sagen \"Hört auf, Pike zu malträtieren, Ihr Monster!\" Phänomenal!', '', 28153),
(155937, 'deDE', 'Ach, die sind für alles Mögliche nützlich!$b$bNatürlich eignen die sich als spitzes Werkzeug, um Dinge zu durchbohren. Aber die Stacheln haben darüber hinaus noch weitere nützliche Eigenschaften. Wenn man sie zu einem feinen Pulver zermahlt, werden sie zu einem hervorragenden Bindemittel. Ihr könnt sie kochen und die Öle als Reinigungsmittel benutzen, und im Notfall tun sie es auch als Zahnstocher!', '', 28153),
(155936, 'deDE', 'Ich werde Euch wohl zusamm\' mit Euren töricht\'n Freund\'n selbst töten müss\'n!', '', 28153),
(155935, 'deDE', 'Tongo... von \'nem Fremdling getötet? Ich muss ihn wohl überschätzt hab\'n!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'deDE', 'Nein, nicht so... nein... argghh....', '', 28153),
(155933, 'deDE', 'Ich habe einen Eid geschworen, in diesen Landen den Frieden zu wahren, aber für Euch mache ich eine Ausnahme.', '', 28153),
(155932, 'deDE', 'Plagt mich, so viel Ihr wollt. Die Geduld eines Gezeitenweisen ist legendär.', '', 28153),
(155931, 'deDE', '', 'Grüße!', 28153),
(155930, 'deDE', 'Wofür braucht man dieser Stacheln eigentlich?', 'Wofür braucht man dieser Stacheln eigentlich?', 28153),
(155929, 'deDE', 'Opfergabe', 'Opfergabe', 28153),
(155928, 'deDE', 'Wisst Ihr, was die Definition von Wahnsinn ist? Immer wieder dasselbe zu tun und keine Backpfeife dafür zu erwarten!', '', 28153),
(155927, 'deDE', 'Langsam, Kumpel. Ich weiß, ich bin zum Anbeißen, aber wir haben Arbeit.', '', 28153),
(155926, 'deDE', 'Also, es sei denn, Ihr wurdet zum Marinedienst verdonnert... oder von Piraten gefangen genommen... und DANN von der Marine verhaftet...', '', 28153),
(155925, 'deDE', 'Ah, die offene See. Ein Seemannslied auf den Lippen. Der Wind im Brusthaar. DAS nenn ich Freiheit.', '', 28153),
(155924, 'deDE', 'Schaut niemals zurück.', '', 28153),
(155923, 'deDE', 'Augen auf den Horizont.', '', 28153),
(155922, 'deDE', 'Die nächste Runde geht auf mich!', '', 28153),
(155921, 'deDE', 'Holen wir uns unseren Lohn.', '', 28153),
(155920, 'deDE', 'Man sieht sich.', '', 28153),
(155919, 'deDE', '<König Rastakhan atmet schwer und in schnellen Zügen. Der Verband um seine Brust ist von Blut durchtränkt.>', '', 28153),
(155918, 'deDE', 'Haltet da draußen die Augen offen.', '', 28153),
(155917, 'deDE', 'Haltet Euer Pulver trocken.', '', 28153),
(155916, 'deDE', 'Wo drückt der Schuh?', '', 28153),
(155915, 'deDE', 'Ausgezeichnet! Ich beginne sofort mit dem Brauen. Und die ansässigen Fischer sind sicher nicht unglücklich darüber, dass ihre geflügelte Konkurrenz etwas dezimiert wurde.', '', 28153),
(155914, 'deDE', 'Ich bin Jamil Abul\'housin, der königliche Leibarzt. Das wär nich\' das erste Mal, dass ich \'nen König zusamm\'ngeflickt hab, und, so die Loa wollen, auch nicht das letzte Mal.', '', 28153),
(155913, 'deDE', 'Ich benötige Bestandteile der Fische und Krabben in dieser Gegend. Leider sind genau diese Dinge auch sehr begehrt bei den Möwen hier. Beschafft mir, was ich brauche, und dünnt dabei diese Vogelschar etwas aus!', '', 28153),
(155912, 'deDE', 'Wie steht\'s um die Genesung?', 'Wie steht\'s um die Genesung?', 28153),
(155911, 'deDE', 'Ja... ja! Lasst dieses Land vor der Macht der Horde erzittern!', '', 28153),
(155910, 'deDE', 'Wir ham viel zusamm\'n durchgemacht, der alte Rastakhan un\' ich. Aber das...\n\n<Jamil deutet auf die böse zugerichtete Gestalt des Königs.>\n\nDas is\' übel.', '', 28153),
(155909, 'deDE', '<Jol wendet den Blick nicht von seinen Gebräuen ab.>\n\nDie Zeit wird knapp für den König.', '', 28153),
(155908, 'deDE', 'Auftrag ist Auftrag, Kumpel.', '', 28153),
(155907, 'deDE', 'Das sollte reichen. Eine Schande, dass wir diese Bedrohung nicht in eine Waffe gegen unsere Feinde verwandeln konnten.', '', 28153),
(155906, 'deDE', 'Ein mächtiger Gegner hier in der Nähe hat sich für unsere Truppen als... problematisch erwiesen. Ich schätze, Ihr wisst, was zu tun ist.', '', 28153),
(155905, 'deDE', 'Euer Erfolg wird den Kriegshäuptling erfreuen.', '', 28153),
(155904, 'deDE', 'Ein gefährlicher Gegner lauert in der Nähe. Schaltet ihn aus, bevor er unsere Pläne durchkreuzen kann.', '', 28153),
(155903, 'deDE', 'Feindliche Truppen behindern unsere Vorhaben in diesem Gebiet. Der Kriegshäuptling erwartet, dass dieses Problem gelöst wird. Enttäuscht sie nicht.', '', 28153),
(155902, 'deDE', 'Wie konnte Rhenik das zulassen?!', 'Wie konnte Rhenik das zulassen?!', 28153),
(155901, 'deDE', 'Nicht schon wieder!', 'Nicht schon wieder!', 28153),
(155900, 'deDE', 'Dafür wird jemand bezahlen!', 'Dafür wird jemand bezahlen!', 28153),
(155899, 'deDE', 'Warum muss immer der Grog draufgehen?!', 'Warum muss immer der Grog draufgehen?!', 28153),
(155898, 'deDE', 'Nicht den Grog!', 'Nicht den Grog!', 28153),
(155897, 'deDE', 'Ob Blut oder Gold – alles hat seinen Preis.', '', 28153),
(155896, 'deDE', 'So sollte das eigentlich nicht laufen. Wollt Ihr es noch mal versuchen?', '', 28153),
(155895, 'deDE', 'Habt Ihr Durst? Ich hab Durst.', '', 28153),
(155894, 'deDE', 'Bin ganz Ohr.', '', 28153),
(155893, 'deDE', 'Was gibt\'s Neues?', '', 28153),
(155892, 'deDE', 'Ahoi!', '', 28153),
(155891, 'deDE', 'Passt auf Euch auf da draußen.', '', 28153),
(155890, 'deDE', 'Man sieht sich.', '', 28153),
(155889, 'deDE', 'Bis bald!', '', 28153),
(155888, 'deDE', 'Grog? \'nen Humpen? Oder beides?', '', 28153),
(155887, 'deDE', 'Was darf\'s sein?', '', 28153),
(155886, 'deDE', 'Gut gemacht, $n!', '', 28153),
(155885, 'deDE', 'Was kann ich für Euch tun?', '', 28153),
(155884, 'deDE', 'Könnt Ihr Na\'logo zu allen Vorräten auf der Insel führen und dann zu seiner Hütte, ohne dass er seinen zurückgelegten Pfad kreuzt?', '', 28153),
(155883, 'deDE', '\"Das einfache Leben\" – Eines Tages beschloss Na\'logo, ein friedliches Leben auf einer einsamen Insel zu führen.', '', 28153),
(155882, 'deDE', 'Ihr wachst mir ans Herz wie ein Nagel in den Zeh!', '', 28153),
(155881, 'deDE', 'Oft genug waren Na\'logos Reisen voller Gefahren. Ich erzähle Euch eine dieser Geschichten.', '', 28153),
(155880, 'deDE', 'Wir Tortollaner lieben die Geschichte von Na\'logo, einem jungen Tortollaner, der die ganze Welt bereist hat.', '', 28153),
(155879, 'deDE', 'Was wollt Ihr? Soll ich Euch eine Kriegsgeschichte vorlesen?', '', 28153),
(155878, 'deDE', 'Zu MEINER Zeit wussten wir, wann es Zeit ist, die Klappe zu halten.', '', 28153),
(155877, 'deDE', '', 'Der Kreislauf des Lebens kann grausam sein.', 28153),
(155876, 'deDE', '', 'Eine Schildkröte hat es ins Wasser geschafft!', 28153),
(155875, 'deDE', '', 'Danke, $n!', 28153),
(155874, 'deDE', '', 'Tortollaner beginnen ihr Leben inmitten von Gefahren, wie diese Schildkröten am Strand. Verteidigt sie, bis sie im sicheren Meer ankommen!', 28153),
(155873, 'deDE', '', 'Gute Arbeit! Das war zwar nicht der vorgesehene Zweck der Maschine, aber es hat funktioniert.', 28153),
(155872, 'deDE', '', 'Wenn einer keinen Ausweis trägt, tötet ihn!', 28153),
(155871, 'deDE', '', 'Welcher Trottel hat gleich mehrere Kisten mit Bomben verloren?', 28153),
(155870, 'deDE', '', 'Einige der Männer bei Aroms Wehr haben es geschafft, die Bergbaumaschine zum Laufen zu bringen. Lasst sie auf die Horde los!', 28153),
(155869, 'deDE', '', 'Ich kann übermäßige Kosten ausgleichen, indem ich Euch von der Lohnliste streiche!', 28153),
(155868, 'deDE', '', 'Kann sein, dass ich ein paar Einschnitte machen muss, um unsere Kosten wieder in die Reihe zu bringen.', 28153),
(155867, 'deDE', 'Eindringlinge in der Gießerei! Ich wiederhole, EINDR...', 'Eindringlinge in der Gießerei! Ich wiederhole, EINDR...', 28153),
(155866, 'deDE', 'Lasst Euch von der Ehre leiten.', '', 28153),
(155865, 'deDE', 'Für die Lordadmiralin.', '', 28153),
(155864, 'deDE', 'Für Kul Tiras!', '', 28153),
(155863, 'deDE', 'Niemals Schwäche zeigen!', '', 28153),
(155862, 'deDE', 'Bleibt wachsam.', '', 28153),
(155861, 'deDE', 'Mast- und Schotbruch!', '', 28153),
(155860, 'deDE', 'Wegtreten!', '', 28153),
(155859, 'deDE', '', '', 28153),
(155858, 'deDE', '', '', 28153),
(155857, 'deDE', 'Lasst hören!', '', 28153),
(155856, 'deDE', '', '', 28153),
(155855, 'deDE', 'Ich hab genug Krieg für uns beide erlebt.', '', 28153),
(155854, 'deDE', 'Was Neues von der Front?', '', 28153),
(155853, 'deDE', 'Was braucht Ihr?', '', 28153),
(155852, 'deDE', 'Mir steckt immer noch der Kampfgeist in den Knochen.', '', 28153),
(155851, 'deDE', 'Gibt\'s was zu berichten?', '', 28153),
(155850, 'deDE', 'Grüße!', '', 28153),
(155849, 'deDE', '', 'Ich empfange keine Bittsteller.', 28153),
(155848, 'deDE', '', 'Ob Sturm oder Schnee, wir bleiben frei wie die See.', 28153),
(155847, 'deDE', '', 'Kul Tiras hält jedem Sturm stand.', 28153),
(155846, 'deDE', '', 'Ich höre.', 28153),
(155845, 'deDE', '', 'Nennt Euer Anliegen.', 28153),
(155844, 'deDE', 'Wir müssen unseren Weg weitergehen.', '', 28153),
(155843, 'deDE', 'Fürchtet nicht den Fluss der Gezeiten.', '', 28153),
(155842, 'deDE', 'Die Strömung leite Euch.', '', 28153),
(155841, 'deDE', 'Gedenkt der Gefallenen.', '', 28153),
(155840, 'deDE', 'Behaltet immer das Meer im Auge.', '', 28153),
(155839, 'deDE', '', 'Ich habe keine Zeit für Plauschereien.', 28153),
(155838, 'deDE', 'Der Sturm erwacht in jedem von uns.', '', 28153),
(155837, 'deDE', 'Ich bin hier, um mich zu duellieren.', 'Ich bin hier, um mich zu duellieren.', 28153),
(155836, 'deDE', 'Nicht ganz. Versucht es noch mal.', '', 28153),
(155835, 'deDE', 'Oh, ein Pärchen!', '', 28153),
(155834, 'deDE', 'Gut gemacht, $n!', '', 28153),
(155833, 'deDE', 'Ich habe über die Jahre viele Dinge gesammelt. Findet Ihr die identischen?', '', 28153),
(155832, 'deDE', 'Na ja, wenn man gern rumrennt. Wenn Ihr lieber fliegt, besucht Pa\'ku, Loa der Winde. Von ihr\'n Totems gibt\'s zwar weniger, dafür könnt Ihr fliegend Eure Wege durch die Stadt abkürz\'n.', '', 28153),
(155831, 'deDE', '', 'Gonk, Meister der Formen un\' der Herr der Jagd is\' \'n mächtiger Loa. Der kann Euch die Stärke von sein\' viel\'n Totems in der Stadt gewähr\'n, die Eure Geschwindigkeit erhöh\'n, wenn sie nah sin\'.', 28153),
(155830, 'deDE', 'Die Tiefen sprachen von Eurem Kommen.', '', 28153),
(155829, 'deDE', 'Ich höre.', '', 28153),
(155828, 'deDE', 'Benötigt Ihr mich?', '', 28153),
(155827, 'deDE', 'Mögen die Gezeiten Euch segnen.', '', 28153),
(155826, 'deDE', 'Zieht die Laufplanken ein, wir legen sofort ab. Löcher im Schiff kann ich überhaupt nicht brauchen.', '', 28153),
(155825, 'deDE', 'Verstehe, die sind auch hinter dem Azerit her. Clever, clever, aber wir waren schneller. Ziehen wir ab, bevor sie uns bemerken.', '', 28153),
(155824, 'deDE', 'Das wäre alles. Die Insel ist abgeräumt, und keinen Moment zu früh. Da ist ein Zandalarischiff am Horizont.', '', 28153),
(155823, 'deDE', 'Und die haben auch Azerit gesammelt. Na, das ist ja praktisch. Tötet sie einfach und klaut ihr Zeug.', '', 28153),
(155822, 'deDE', 'Ho-zen? Hier? Tja, ich schätze, man weiß nie genau, wer auf diesen Inseln auftaucht.', '', 28153),
(155821, 'deDE', 'Wir haben gerade jede Menge Azerit in der Nähe entdeckt. Das wird der Hammer.', '', 28153),
(155820, 'deDE', 'Schick. Also, eigentlich ist es blutig und ekelhaft. Ach, aber was soll\'s? Azerit ist Azerit.', '', 28153),
(155819, 'deDE', 'Boah, was für ein Riesenmonster! Und es ist voll mit Azeritrückständen. Ihr tötet es und wir extrahieren das Azerit.', '', 28153),
(155818, 'deDE', 'Also, der Detektor zeigt nahe Eurer Position noch eine Azeritquelle an. Werft mal einen Blick drauf.', '', 28153),
(155817, 'deDE', 'Wuhuu! Das ist fette Beute. Gute Arbeit!', '', 28153),
(155816, 'deDE', 'Hui, was für ein Riesenbrocken Azerit. Baut das Ding ab, dann schaffen wir die Splitter sofort aufs Schiff.', '', 28153),
(155815, 'deDE', 'Unser Azeritdetektor zeigt eine... na, eine Azeritquelle an. Warum geht Ihr nicht los, um das zu untersuchen? Ich, äh, bleibe hier.', '', 28153),
(155814, 'deDE', 'Sanft anlegen. Versucht, nirgendwo anzustoßen. Und legt die Laufstege aus. Danke.', '', 28153),
(155813, 'deDE', 'Wisst Ihr, hier könnte es auch, zum Beispiel... Riesenspinnen geben. Ich sag\'s ja nur. Man weiß es nie.', '', 28153),
(155812, 'deDE', 'Ziemlich sicher, dass wir hier richtig sind. Hier soll es jede Menge Azerit geben.', '', 28153),
(155811, 'deDE', '$n! Der Dunklen Fürstin sei Dank, dass Ihr hier seid! Rexxar hat einen Haufen Kul Tiraner in die Gebäude dort vorne gelockt. Er braucht Unterstützung!', '$n! Der Dunklen Fürstin sei Dank, dass Ihr hier seid! Rexxar hat einen Haufen Kul Tiraner in die Gebäude dort vorne gelockt. Er braucht Unterstützung!', 28153),
(155810, 'deDE', 'Schnell, unter Deck und an die Kanonen! Unsere Truppen brauchen uns!', '', 28153),
(155809, 'deDE', 'Da sind die Überreste von Vadekius. Er war ein mächtiger Drache.', 'Da sind die Überreste von Vadekius. Er war ein mächtiger Drache.', 28153),
(155808, 'deDE', 'Kommt nicht auf komische Gedanken.', 'Kommt nicht auf komische Gedanken.', 28153),
(155807, 'deDE', 'Es muss wahrlich etwas Dunkles und Mächtiges gewesen sein, was ihn getötet hat.', 'Es muss wahrlich etwas Dunkles und Mächtiges gewesen sein, was ihn getötet hat.', 28153),
(155806, 'deDE', 'Da sind die Überreste von Vadekius. Er war ein mächtiger Drache.', 'Da sind die Überreste von Vadekius. Er war ein mächtiger Drache.', 28153),
(155805, 'deDE', 'Aber dies ist immerhin ein Anfang.', 'Aber dies ist immerhin ein Anfang.', 28153),
(155804, 'deDE', 'Mein Herz ist nicht so groß wie das meiner Königin.', 'Mein Herz ist nicht so groß wie das meiner Königin.', 28153),
(155803, 'deDE', 'Was Ihr Kyranastrasz angetan habt, werde ich Euch nicht so schnell vergeben können.', 'Was Ihr Kyranastrasz angetan habt, werde ich Euch nicht so schnell vergeben können.', 28153),
(155802, 'deDE', 'Dann muss ich mich wohl bedanken.', 'Dann muss ich mich wohl bedanken.', 28153),
(155801, 'deDE', 'Danke für Eure Hilfe, $n.', 'Danke für Eure Hilfe, $n.', 28153),
(155800, 'deDE', 'Wir wollen nicht, dass sich diese furchtbaren Ereignisse wiederholen.', 'Wir wollen nicht, dass sich diese furchtbaren Ereignisse wiederholen.', 28153),
(155799, 'deDE', 'Um seine letzte Ruhestätte zu finden, ist der Todesgebieter in unser Rubinsanktum eingedrungen.', 'Um seine letzte Ruhestätte zu finden, ist der Todesgebieter in unser Rubinsanktum eingedrungen.', 28153),
(155798, 'deDE', 'Während des letzten Krieges gegen die Legion haben sie einen von uns als untote Kreatur wiederauferstehen lassen.', 'Während des letzten Krieges gegen die Legion haben sie einen von uns als untote Kreatur wiederauferstehen lassen.', 28153),
(155797, 'deDE', 'Dann werden $n und ich uns um diese Aufgabe kümmern. Kommt, $C, ich bringe Euch zur Ritualstätte.', 'Dann werden $n und ich uns um diese Aufgabe kümmern. Kommt, $C, ich bringe Euch zur Ritualstätte.', 28153),
(155796, 'deDE', '', '$n hat die Aufgabe erledigt und ist zurückgekehrt. Vielleicht erhaltet Ihr Hilfe, Zallestrasza.', 28153),
(155795, 'deDE', 'Ihr macht Euch beide zu viele Sorgen. Ich fühle mich schon viel besser.', 'Ihr macht Euch beide zu viele Sorgen. Ich fühle mich schon viel besser.', 28153),
(155794, 'deDE', 'Haltet still, damit ich Euch heilen kann.', 'Haltet still, damit ich Euch heilen kann.', 28153),
(155793, 'deDE', 'Ihr könnt ja kaum aufrecht sitzen, Theo!', 'Ihr könnt ja kaum aufrecht sitzen, Theo!', 28153),
(155792, 'deDE', '', 'Gut gemacht, $n! Gehen wir jetzt in mein neues Büro.', 28153),
(155791, 'deDE', '', 'Das war meiner! Den zähl ich bei mir mit!', 28153),
(155790, 'deDE', 'Für den Kampf gegen Korthek werde ich unglaubliche Kräfte brauchen. Er war immer der bessere Kämpfer von uns beiden.\n\nIch werde so viel aus diesen Kristallen herausholen, wie ich kann, und dann müssen wir beten, dass es reichen wird.', '', 28153),
(155789, 'deDE', '', 'Die Spinnen wurden auf eine gemütlichere Anzahl reduziert. Unsere Leute können sich jetzt wieder im Wald aufhalten, ohne Angst haben zu müssen, in ein Spinnennetz zu geraten.', 28153),
(155788, 'deDE', '', 'Gefährliche Spinnen haben sich hier im Wald eingenistet und gefährden unsere Jäger. Räuchert sie aus!', 28153),
(155787, 'deDE', 'Vertauschen', 'Vertauschen', 28153),
(155786, 'deDE', '', 'Gute Arbeit. Beim Wetter hier werd\'n unsre Truppen froh sein über diese Vorräte.', 28153),
(155785, 'deDE', '', 'Unsre Späher sag\'n, die Menschen hier kenn\' \'nen Weg, Tierfell zu sammeln, ohne dass die Tiere zu Schaden komm\'. Seltsam... aber es funktioniert.', 28153),
(155784, 'deDE', 'Etwas Böses treibt sich im Sägewerk herum. Das ist mir zu nah an Boralus.', '', 28153),
(155783, 'deDE', 'Was für ein Kampf! Als das Monster Kul Tiranischen Boden berührt hat, waren seine Tage gezählt.', '', 28153),
(155782, 'deDE', 'Die Sturmtakler haben etwas großes am Haken. Sie könnten Eure Hilfe brauchen.', '', 28153),
(155781, 'deDE', 'Verbrennen', 'Verbrennen', 28153),
(155780, 'deDE', 'Wir steck\'n da gemeinsam drin. Ich werd nich\' nachgeb\'n!', 'Wir steck\'n da gemeinsam drin. Ich werd nich\' nachgeb\'n!', 28153),
(155779, 'deDE', 'Wenn ich heut sterbe... dann wird das im Kampf gescheh\'n!', 'Wenn ich heut sterbe... dann wird das im Kampf gescheh\'n!', 28153),
(155778, 'deDE', 'Lebend bekommt Mojambo mich nich\'!', 'Lebend bekommt Mojambo mich nich\'!', 28153),
(155777, 'deDE', 'Ich werd mich nich\' Mojambo und seiner Bande unterwerf\'n!', 'Ich werd mich nich\' Mojambo und seiner Bande unterwerf\'n!', 28153),
(155776, 'deDE', 'Ich kämpf bis zum letzten Atemzug!', 'Ich kämpf bis zum letzten Atemzug!', 28153),
(155775, 'deDE', 'Ohne Kampf wird Mojambo uns nich\' bezwing\'n!', 'Ohne Kampf wird Mojambo uns nich\' bezwing\'n!', 28153),
(155774, 'deDE', 'Der Kampf wird bald beginnen. Nehmt dieses Schwert und bleibt wachsam.', 'Der Kampf wird bald beginnen. Nehmt dieses Schwert und bleibt wachsam.', 28153),
(155773, 'deDE', 'Wir sind hier zu Hause. Wir werden nicht kampflos abziehen.', 'Wir sind hier zu Hause. Wir werden nicht kampflos abziehen.', 28153),
(155772, 'deDE', '', 'Gute Arbeit! Ein Problem weniger, um das die Marinesoldaten sich Sorgen machen müssen.', 28153),
(155771, 'deDE', '', 'Was für ein Sieg! Ich glaube, ich könnte viel lernen, indem ich Euch beim Kämpfen zusehe.', 28153),
(155770, 'deDE', '', 'Die Straßen von Kul Tiras sind heute dank Eurer Taten wieder sicher.', 28153),
(155769, 'deDE', '', 'Das Militär hat hier in der Vergangenheit Scherereien mit einer Bestie gehabt. Lösen wir das Problem!', 28153),
(155768, 'deDE', '', 'Eine üble Bestie durchstreift die Gegend. In Kul Tiras\' Interesse können wir diese Bedrohung nicht ignorieren!', 28153),
(155767, 'deDE', '', 'So eine Abscheulichkeit darf nicht weiter über unschuldige Bürger herfallen. Streckt sie nieder!', 28153),
(155766, 'deDE', 'Solltet Ihr nicht gerade woanders sein?', 'Solltet Ihr nicht gerade woanders sein?', 28153),
(155765, 'deDE', 'Hey, da guckt jemand komisch!', 'Hey, da guckt jemand komisch!', 28153),
(155764, 'deDE', 'Ihr seid aber gar nicht von hier!', 'Ihr seid aber gar nicht von hier!', 28153),
(155763, 'deDE', 'Roter Himmel inner Nacht dem Seemann große Freude macht, roter Himmel dann am Morg\'n bringt dem Seemann große Sorg\'n!', '', 28153),
(155762, 'deDE', 'Ich möchte zu G\'huun teleportiert werden.', 'Ich möchte zu G\'huun teleportiert werden.', 28153),
(155761, 'deDE', 'Ich möchte zu Mythrax teleportiert werden.', 'Ich möchte zu Mythrax teleportiert werden.', 28153),
(155760, 'deDE', 'Ich möchte zu Zul teleportiert werden.', 'Ich möchte zu Zul teleportiert werden.', 28153),
(155759, 'deDE', 'Ich möchte zum Blutelementar teleportiert werden.', 'Ich möchte zum Blutelementar teleportiert werden.', 28153),
(155758, 'deDE', 'Ich möchte zu Zek\'voz teleportiert werden.', 'Ich möchte zu Zek\'voz teleportiert werden.', 28153),
(155757, 'deDE', 'Ich möchte zum fauligen Verschlinger teleportiert werden.', 'Ich möchte zum fauligen Verschlinger teleportiert werden.', 28153),
(155756, 'deDE', 'Ich möchte zu MUTTER teleportiert werden.', 'Ich möchte zu MUTTER teleportiert werden.', 28153),
(155755, 'deDE', 'Seid gegrüßt und habt Dank dafür, dass Ihr beim Testen von Uldir helft!\n\nIch kann Euch direkt zu sämtlichen Bossen teleportieren, die aktuell getestet werden können.', 'Seid gegrüßt und habt Dank dafür, dass Ihr beim Testen von Uldir helft!\n\nIch kann Euch direkt zu sämtlichen Bossen teleportieren, die aktuell getestet werden können.', 28153),
(155754, 'deDE', '', 'Meine Katze ist verschwunden.', 28153),
(155753, 'deDE', 'Trotzt dem Sturm, den Ihr nich\' meid\'n könnt! Meidet den Sturm, dem Ihr nich\' trotz\'n könnt!', '', 28153),
(155752, 'deDE', 'Immer dran denk\'n: Die nasse Seite nach unt\'n!', '', 28153),
(155750, 'deDE', 'Soll ich Euch zu Bwonsamdi schick\'n?', '', 28153),
(155749, 'deDE', 'So ein Leb\'n an Land muss echt traurig für Euch sein...', '', 28153),
(155748, 'deDE', 'Wenn Ihr auf die Bucht der Könige blickt un\' die heiligen, blau\'n Flammen seht, dann denkt dran, dass Ihr heut\' das Blatt gewendet habt! Das is\' \'n würdiger Sieg, $n. Die Flotte gehört für immer Zandalar!', '', 28153),
(155747, 'deDE', 'Wenn\'s sein muss, lass ich Euch kielhol\'n.', '', 28153),
(155746, 'deDE', 'Mögt Ihr Wind in Euern Segeln un\' Zielstrebigkeit in Euerm Herz\'n ham!', '', 28153),
(155745, 'deDE', 'Man sieht sich.', '', 28153),
(155744, 'deDE', 'Macht\'s gut! Mich ruft die See.', '', 28153),
(155743, 'deDE', 'Von günstig\'n Wind\'n lernt der Seemann nix.', '', 28153),
(155742, 'deDE', 'Mast- und Schotbruch!', '', 28153),
(155741, 'deDE', 'Mögen sich unsere Strömungen erneut kreuzen!', '', 28153),
(155740, 'deDE', 'Segelt mit Rück\'nwind zu neu\'n Horizont\'n!', '', 28153),
(155739, 'deDE', 'Könnt Ihr das Salz in der Luft schmeck\'n? So fühlt sich \"zuhause\" an.', '', 28153),
(155738, 'deDE', 'Taz\'okun! Willkomm\'!', '', 28153),
(155737, 'deDE', 'Die Arbeit ist vollbracht... aber an dem Blutbad, das Ihr hinterlasst, könnt Ihr noch arbeiten. Geht nächstes Mal etwas enthusiastischer zu Werke.', '', 28153),
(155736, 'deDE', 'Ahoy, Ihr seid es!', '', 28153),
(155735, 'deDE', 'Der Kriegshäuptling befiehlt, dass Ihr dieses Gebiet im Namen der Horde erobert. Jedes Mittel soll dabei recht sein, solang es Euch den Sieg bringt.', '', 28153),
(155734, 'deDE', 'Ein Tag ohne Land is\' \'n guter Tag.', '', 28153),
(155733, 'deDE', 'Seid Ihr bereit für \'ne epische Reise?', '', 28153),
(155732, 'deDE', 'Ich möchte nach Uldir (Schlachtzug).', 'Ich möchte nach Uldir (Schlachtzug).', 28153),
(155731, 'deDE', 'Gut gemacht! Unsere Vögel werden sicherere Nistplätze finden, und wir müssen uns um weniger Feinde Gedanken machen.', '', 28153),
(155730, 'deDE', 'Ich erwarte voller Vorfreude Eure Rückkehr!', '', 28153),
(155729, 'deDE', 'Bitte kehrt zügig zurück!', '', 28153),
(155728, 'deDE', 'Zielen!', 'Zielen!', 28153),
(155727, 'deDE', 'Ich verstehe, schon wieder...', '', 28153),
(155726, 'deDE', 'Ich nehme an, Ihr habt etwas kaputtgemacht...', '', 28153),
(155725, 'deDE', 'Kann ich helfen?', '', 28153),
(155724, 'deDE', 'Was kann ich für Euch tun?', '', 28153),
(155723, 'deDE', 'Geht in Deckung!!!', 'Geht in Deckung!!!', 28153),
(155722, 'deDE', 'Habt Ihr ein Glück, dass ich Euch mag. Diesmal werde ich es reparieren... mal wieder...', '', 28153),
(155721, 'deDE', 'Ehrlich? Das klitzekleine Ding ist nur zerbrochen, weil es ein solches Gewicht nicht ausgehalten hat? Wer hätte das erwartet...', '', 28153),
(155720, 'deDE', 'Ihr seid wohl nicht viel klüger als mein Hammer.', '', 28153),
(155719, 'deDE', 'Bin mir ziemlich sicher, das ist dasselbe Ding, was ich beim letzten Mal repariert habe.', '', 28153),
(155718, 'deDE', 'Ich wünschte, diese Narren würden aufhören, alles kaputtzumachen.', '', 28153),
(155717, 'deDE', 'Ich möchte zum Kronsteiganwesen (Dungeon).', 'Ich möchte zum Kronsteiganwesen (Dungeon).', 28153),
(155716, 'deDE', 'Ich möchte nach Tol Dagor (Dungeon).', 'Ich möchte nach Tol Dagor (Dungeon).', 28153),
(155715, 'deDE', 'Ich möchte zur Belagerung von Boralus (Dungeon).', 'Ich möchte zur Belagerung von Boralus (Dungeon).', 28153),
(155714, 'deDE', 'Ich möchte zum Schrein des Sturms (Dungeon).', 'Ich möchte nach Freihafen (Dungeon).', 28153),
(155713, 'deDE', 'Ich möchte nach Freihafen (Dungeon).', 'Ich möchte nach Freihafen (Dungeon).', 28153),
(155712, 'deDE', 'Bei Hakenschnabels Federn! Habt Ihr mich erschreckt!', '', 28153),
(155711, 'deDE', 'Die von den Hexen beherrschten Falkner haben unsere Vögel gestohlen! Befreit die Falken und vernichtet die Diener der Hexen!', '', 28153),
(155710, 'deDE', 'Benötigt Ihr ein bestimmtes Dingsbums? Ein Gerät? Ein Kinkerlitzchen?', '', 28153),
(155709, 'deDE', 'Ich möchte zum Tiefenpfuhl (Dungeon).', 'Ich möchte zum Tiefenpfuhl (Dungeon).', 28153),
(155708, 'deDE', 'Ich möchte zum RIESENFLÖZ (Dungeon).', 'Ich möchte zum RIESENFLÖZ (Dungeon).', 28153),
(155707, 'deDE', 'Ich möchte zum Tempel von Sethraliss (Dungeon).', 'Ich möchte zum Tempel von Sethraliss (Dungeon).', 28153),
(155706, 'deDE', 'Ich möchte zur Königsruh (Dungeon).', 'Ich möchte zur Königsruh (Dungeon).', 28153),
(155705, 'deDE', 'Die Sturmtakler sind auf alles vorbereitet!', '', 28153),
(155704, 'deDE', 'Unsere gefiederten Freunde sind wieder sicher vor der Magie der Hexen.', '', 28153),
(155703, 'deDE', 'Die Hexen benutzen Talismane, um unsere Schwärme schon beim Schlüpfen zu verhexen! Vernichtet die Talismane und alle behexten Falkner, die Ihr finden könnt, bevor sie ihren Einfluss ausweiten können!', '', 28153),
(155702, 'deDE', '', 'Zieht Leine.', 28153),
(155701, 'deDE', '', 'Ich habe eine Waffe und keine Skrupel, sie zu benutzen.', 28153),
(155700, 'deDE', '', 'Euer Gesicht ödet mich an.', 28153),
(155699, 'deDE', '', 'Zeigt mir eine Bestie. Meine Sturmtakler erledigen das.', 28153),
(155698, 'deDE', '', 'Mutzi, du böses Kätzchen. Komm sofort hierher!', 28153),
(155697, 'deDE', '', 'Hierher, miez, miez...!', 28153),
(155696, 'deDE', 'Ich möchte nach Atal\'Dazar (Dungeon).', 'Ich möchte nach Atal\'Dazar (Dungeon).', 28153),
(155695, 'deDE', '', 'Kommt wieder, wenn Ihr bereit seid, mit den Großen zu spielen.', 28153),
(155694, 'deDE', '', 'Ich habe Monster zu töten.', 28153),
(155693, 'deDE', '', 'Was jetzt?', 28153),
(155692, 'deDE', 'Ich nehme an, die Mission ist abgeschlossen? Gut. Ich werde Euren Erfolg dem Kriegshäuptling melden.', '', 28153),
(155691, 'deDE', 'Seid gegrüßt und vielen Dank, dass Ihr uns beim Testen der Beta von Battle for Azeroth helft!\n\nIch kann Euch direkt zu einigen Schlachtzugs- oder Dungeoninstanzen befördern, die derzeit getestet werden. Hierbei handelt es sich nur um eine Teleportation, nicht um Gruppenzuweisung. Ihr habt hoffentlich schon eine Gruppe, mit der Ihr Euch den Herausforderungen stellen könnt, die Euch dort erwarten. Falls dem nicht so ist, solltet Ihr unseren neuen Dungeonbrowser ausprobieren, um Verbündete zu finden.\n\nÜberprüft noch einmal, ob Ihr den passenden Schwierigkeitsgrad ausgewählt habt, bevor Ihr Euch teleportieren lasst. Möglicherweise wird es nicht leicht, die Zone zu verlassen, um die Schwierigkeit zu ändern!', 'Seid gegrüßt und vielen Dank, dass Ihr uns beim Testen der Beta von Battle for Azeroth helft!\n\nIch kann Euch direkt zu einigen Schlachtzugs- oder Dungeoninstanzen befördern, die derzeit getestet werden. Hierbei handelt es sich nur um eine Teleportation, nicht um Gruppenzuweisung. Ihr habt hoffentlich schon eine Gruppe, mit der Ihr Euch den Herausforderungen stellen könnt, die Euch dort erwarten. Falls dem nicht so ist, solltet Ihr unseren neuen Dungeonbrowser ausprobieren, um Verbündete zu finden.\n\nÜberprüft noch einmal, ob Ihr den passenden Schwierigkeitsgrad ausgewählt habt, bevor Ihr Euch teleportieren lasst. Möglicherweise wird es nicht leicht, die Zone zu verlassen, um die Schwierigkeit zu ändern!', 28153),
(155690, 'deDE', '$n (Horde) ist auf Eurer Karte als |c00FFFF00|Hspell:272296|h[Attentäter]|h|r markiert! Tötet $n, um eine Kopfgeldbelohnung zu erhalten.', '$n (Horde) ist auf Eurer Karte als |c00FFFF00|Hspell:272296|h[Attentäter]|h|r markiert! Tötet $n, um eine Kopfgeldbelohnung zu erhalten.', 28153),
(155689, 'deDE', '$n (Allianz) ist auf Eurer Karte als |c00FFFF00|Hspell:272295|h[Attentäter]|h|r markiert! Tötet $n, um eine Kopfgeldbelohnung zu erhalten.', '$n (Allianz) ist auf Eurer Karte als |c00FFFF00|Hspell:272295|h[Attentäter]|h|r markiert! Tötet $n, um eine Kopfgeldbelohnung zu erhalten.', 28153),
(155688, 'deDE', 'Wir müssen die feindlichen Truppen in diesem Gebiet in Schach halten... und ich vertraue Euch diese Aufgabe an.', '', 28153),
(155687, 'deDE', '', 'Mich hat noch kein Monster überlebt.', 28153),
(155686, 'deDE', 'Das hat etwas länger gedauert, als ich mir gewünscht hätte... aber das Ergebnis ist akzeptabel. Unsere Kampagne schreitet fort.', '', 28153),
(155685, 'deDE', 'Der Kriegshäuptling hat Anspruch auf alle Ressourcen in diesem Gebiet erhoben. Nehmt, was unser ist.', '', 28153),
(155684, 'deDE', 'Ich will von DIR nichts mehr über meine Schwester hören!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'deDE', '', 'Mit diesen Rohstoffen werden wir sicherlich etwas anfangen können! Gute Arbeit!', 28153),
(155682, 'deDE', '', 'Du kämpfst wie deine Schwester.', 28153),
(155681, 'deDE', '', 'Hier gibt es Rohstoffe, die dem Orden von Nutzen sein könnten. Übernehmt die Kontrolle über das Gebiet und sichert seine Rohstoffvorkommen für uns!', 28153),
(155680, 'deDE', 'Wie Ihr wünscht, Mutter...', '', 28153),
(155679, 'deDE', '', 'Miezi, wo bist du?', 28153),
(155678, 'deDE', '', 'Komm, Arthur.', 28153),
(155677, 'deDE', '', 'Und jetzt, Marschall, seid ein Schatz und bringt Luzilla in meine Gemächer, sobald Ihr diese Plagen beseitigt habt...', 28153),
(155676, 'deDE', '', 'Habt Ihr meine Katze gesehen?', 28153),
(155675, 'deDE', '', 'Aber Marschall, so redet man nicht mit einer Dame. Ich sollte Euch Manieren beibringen.', 28153),
(155674, 'deDE', '', 'Denkt Ihr, Ihr könnt mithalten?', 28153),
(155673, 'deDE', 'Bleibt ihr vom Leib, herzloses Hexenweib!', '', 28153),
(155672, 'deDE', '', 'Zeig etwas Dankbarkeit, Mädchen! Dein Vater ist nicht nur wohlauf, sondern bald auch Lord von ganz Kul Tiras! Schließ dich uns an, mein Kind...', 28153),
(155671, 'deDE', '', 'Was... was habt Ihr ihm angetan?', 28153),
(155670, 'deDE', '', 'Ich bin so froh, dass du hier bist, Liebes. Dein Vater hat dich schmerzlich vermisst.', 28153),
(155669, 'deDE', '', 'Mutter? Seid Ihr das?', 28153),
(155668, 'deDE', '', 'Das ist nah genug.', 28153),
(155667, 'deDE', 'Hab gehört, das hat mit den ganzen Kisten zu tun, die wir von Aschenwind bekommen.', 'Hab gehört, das hat mit den ganzen Kisten zu tun, die wir von Aschenwind bekommen.', 28153),
(155666, 'deDE', 'Kapitänin Stein wirkt irgendwie wirklich aufgeregt.', 'Kapitänin Stein wirkt irgendwie wirklich aufgeregt.', 28153),
(155665, 'deDE', 'Bin ich froh, dass wir heute hier draußen eingesetzt werden.', 'Bin ich froh, dass wir heute hier draußen eingesetzt werden.', 28153),
(155664, 'deDE', 'Was? Das ist eine BOMBE? Ich dachte, das wäre eine Avocado.', '', 28153),
(155663, 'deDE', '', 'Vorsichtig, John. Wenn Ihr mit dem Schießpulver nicht aufpasst, verliert Ihr noch eine Hand.', 28153),
(155662, 'deDE', 'Holt die Plank\'n ein! Wir leg\'n ab! Habt Euch da drauß\'n gut geschlag\'n.', '', 28153),
(155661, 'deDE', 'Sieht aus, als sin\' die auch hinter\'m Azerit her. Schleich\'n wir uns weg, bevor die uns seh\'n. Wir müss\'n das meld\'n.', '', 28153),
(155660, 'deDE', 'Das wär\' alles. Die Insel ham wir wohl abgeräumt – und grad noch rechtzeitig. Da is\'n Schiff aus Kul Tiras am Horizont.', '', 28153),
(155659, 'deDE', 'Sieht aus, als ob die auch Azerit samm\'ln. Gut für uns... alles auf einem Hauf\'n, ha! Geht hin und nehmt\'s ihnen ab.', '', 28153),
(155658, 'deDE', 'Ho-zen! Ha! Man weiß echt nie, wer hier so alles auftaucht.', '', 28153),
(155657, 'deDE', 'Direkt um die Ecke ham wir \'ne Riesenmenge Azerit gesichtet. Das müsst Ihr Euch ma\' anseh\'n.', '', 28153),
(155656, 'deDE', 'So läuft das. Wir wer\'n den Laderaum im Handumdreh\'n voll ham.', '', 28153),
(155655, 'deDE', 'Das is\'n Riesenmonster, und es is\' mit Azeritrückständ\'n überzog\'n. Tötet es, dann nehm\'n wir ihm das Azerit ab.', '', 28153),
(155654, 'deDE', 'Sieht aus, als is\' in Eurer Nähe noch \'ne Azeritquelle. Die solltet Ihr Euch wohl als Nächstes anguck\'n.', '', 28153),
(155653, 'deDE', 'Na bitte, das is\' ma\' fette Beute. Gut gemacht.', '', 28153),
(155652, 'deDE', 'Ah, jau, das is \'n großer Brock\'n. Baut den schon ma\' ab. Wir hol\'n das Azerit in null Komma nix an Bord.', '', 28153),
(155651, 'deDE', 'Die Maschine zeigt \'n bisschen Azerit in der Nähe an. Geht da ma\' raus und guckt Euch das an.', '', 28153),
(155650, 'deDE', 'Legt die Laufplank\'n aus. Hier sin\' wir richtig.', '', 28153),
(155649, 'deDE', 'Wir wissen aber nich\', was hier noch so is\'. Ihr müsst da drauß\'n aufpass\'n.', '', 28153),
(155648, 'deDE', 'Fast da. Das is\' die Insel, auf der unsre Späher \'ne Menge Azerit entdeckt ham.', '', 28153),
(155647, 'deDE', 'Schon dabei, Kapitänin.', 'Schon dabei, Kapitänin.', 28153),
(155646, 'deDE', '', 'Na dann, ladet sie auf das Schiff! Diese Sprengstoffe sind eine Gefahrenquelle.', 28153),
(155645, 'deDE', 'J-ja, Kapitänin Stein.', 'J-ja, Kapitänin Stein.', 28153),
(155644, 'deDE', '', 'Sind die Schießpulverlieferungen aus der Aschenwindgießerei da?', 28153),
(155643, 'deDE', 'Blut und Donner, was für eine Zauberei ist das? Unsere Schiffe sind vernichtet und unsere Truppen wurden ans Meer zurückgedrängt!', '', 28153),
(155642, 'deDE', 'Wisst Ihr, in Freihafen könnte man ein Vermögen mit Ohrstöpseln machen.', '', 28153),
(155641, 'deDE', 'Was... hört Ihr das? Wartet! Nicht schon wieder! Tötet sie, tötet sie!', '', 28153),
(155640, 'deDE', 'Nicht schlecht! Vielleicht ist Freihafen jetzt ein bisschen sicherer... Ja, klar. Wem mache ich was vor?', '', 28153),
(155639, 'deDE', 'Ha! So sieht\'s aus, Brackwasserschlürfer!', '', 28153),
(155638, 'deDE', 'Spitze! Ein Gläubiger weniger, der mir die Beine brechen will.', '', 28153),
(155637, 'deDE', 'Was riecht nach Grog und hat einen roten Hut? Ein Pirat. Und keiner von der geselligen Sorte.', '', 28153),
(155636, 'deDE', 'Ein paar Freunde haben in der Nähe einen Gesuchten gesehen. Holen wir uns das Kopfgeld!', '', 28153),
(155635, 'deDE', 'In der Gegend treibt sich ein besonders übler Gauner rum. Das solltet Ihr vermutlich ändern.', '', 28153),
(155634, 'deDE', 'Hey, da sind unsere Freunde von der Venture Company. Sie möchten uns die Bürde des Azerits abnehmen. Nett von ihnen. Vielleicht sagt Ihr ihnen mal hallo.', '', 28153),
(155633, 'deDE', 'Die Venture Company hat an mehreren Stellen auf der ganzen Insel die Arbeit aufgenommen. Ihr solltet ihnen das Geschäft verderben.', '', 28153),
(155632, 'deDE', 'Die Venture Company ist gerade aufgetaucht. Sie wollen wohl diese Azeritquelle ausbeuten, wie es nur ein Goblin kann.', '', 28153),
(155631, 'deDE', 'Wir haben auf der ganzen Insel Schläger der Venture Company gesichtet. Da ist wohl eine feindliche Übernahme im Gange.', '', 28153),
(155630, 'deDE', 'Langboote, wie sie die Vrykul haben, und zwar eine ganze Menge. Ein Klan hat sich offensichtlich auf der Suche nach Azerit aufs Meer gewagt.', '', 28153),
(155629, 'deDE', 'Diese Vrykullangboote haben gerade eine große Gruppe abgesetzt. Sie müssen es auf unsere Beute abgesehen haben. Ihr haltet sie doch zurück, ja?', '', 28153),
(155628, 'deDE', 'Eine Vrykulflotte ist gerade angekommen. Auf der ganzen Insel kampieren jede Menge brutal aussehende Krieger, soweit ich das von meinem Versteck hinter diesem Fass aus erkennen kann.', '', 28153),
(155627, 'deDE', 'Vrykulschiffe sind unterwegs. Sieht wie ein Plündertrupp aus. Die plündern immer irgendetwas. Ist ja schließlich ihr Ding.', '', 28153),
(155626, 'deDE', 'Ein paar unfreundliche Inseltrolle haben beschlossen, uns die Party zu verderben. Sie lagern auf der ganzen Insel.', '', 28153),
(155625, 'deDE', 'Ich kann am Horizont Kanus voller Inseltrolle erkennen und sie werden jede Minute hier sein. Dieses Azerit lockt alles an, was ich nicht ausstehen kann.', '', 28153),
(155624, 'deDE', 'Ein paar der Inseltrolle sind aufgetaucht, vermutlich auch darauf aus, Azerit zu erbeuten. Wenn Ihr sie vom Schiff fernhalten könntet, wären wir sehr dankbar.', '', 28153),
(155623, 'deDE', 'Hey, schaut mal, ein ganzer Haufen Trollschiffe ist gerade eingetroffen. Noch mehr Trolle können wir gut gebrauchen. Warum nicht gleich ein ganzer Schlachtzug von ihnen? Einfach großartig.', '', 28153),
(155622, 'deDE', 'Und da kommt ein RIESIGER Drache aus dem Nichts geflogen, weil mir das natürlich gerade noch gefehlt hat. Diese Woche war einfach toll, wisst Ihr? Also, jedenfalls: Drache.', '', 28153),
(155621, 'deDE', 'Hey, Freunde? Ein großer Drache ist grade zur Party aufgekreuzt und scheint ganz wild auf Euer Azerit. Ich dachte nur, ich sollte das vielleicht erwähnen.', '', 28153),
(155620, 'deDE', 'Drachen. Da sind Drachen. Und die gucken genau in Richtung des Schiffs. Ich glaube, die können mich sehen. Vielleicht könntet Ihr mir ja helfen, ja?', '', 28153),
(155619, 'deDE', 'Es ist da gerade ein ganzer Schwarm Drachen gelandet. Und ich wette, ich weiß, was die wollen. Viel Glück!', '', 28153),
(155618, 'deDE', 'Und was ist jetzt mit dem Himmel los? Warum ist der so dunkel? Und WARUM sind da jetzt überall Leichen auf der Insel? Oh, je...', '', 28153),
(155617, 'deDE', 'Also, das ist wohl der ÜBELSTE Gestank, den ich je gerochen habe. Wer war das? Oh, da kommen Untote. Hey Leute, die Toten sind hier und wollen das Azerit! Klar?', '', 28153),
(155616, 'deDE', 'Um dem Ganzen die Krone aufzusetzen, breiten sich die Untoten jetzt anscheinend auf der ganzen Insel aus. Ich will es gar nicht wissen.', '', 28153),
(155615, 'deDE', 'Die Untoten? Hier? Ich weiß zwar nicht, was jetzt los ist, aber das kann garantiert nichts Gutes bedeuten.', '', 28153),
(155614, 'deDE', 'Achtung, am Horizont sind Schiffe der Tol\'vir aufgetaucht und die sehen nicht so aus, als ob sie friedlich Handel treiben wollen. Also macht mal flott, bitte.', '', 28153),
(155613, 'deDE', 'Oh, das sind die Tol\'vir, oder? Ist schon eine Weile her, dass ich eins ihrer Schiffe gesehen habe. Aber jetzt sind sie hier. Und sie hassen uns.', '', 28153),
(155612, 'deDE', 'Gerade sind Schiffe der Tol\'vir angelandet. Woher wissen bloß alle, wo das Azerit ist? Ich hasse das Zeug. Könntet Ihr Euch drum kümmern?', '', 28153),
(155611, 'deDE', 'Was ist denn das? Ein Zentaur? Ein Mantaurus? Hey, ich glaube, da sind gerade ein paar... Tol\'vir aufgetaucht.', '', 28153),
(155610, 'deDE', 'Piratenschiff am Horizont. Die wollen hier vermutlich auch plündern. Wie Piraten eben so drauf sind.', '', 28153),
(155609, 'deDE', 'Da geht eine Piratenmannschaft an Land. Denn wenn es auf einer Insel Schätze gibt, dann sind Piraten natürlich unerlässlich.', '', 28153),
(155608, 'deDE', 'Und jetzt ist natürlich noch ein DRITTES Schiff aufgetaucht, weil ich ja immer die besten Missionen abkriege. Nur zur Information: Das sind übrigens Piraten.', '', 28153),
(155607, 'deDE', 'Oh, Mann, dieses Kanonenfeuer hätte uns fast getroffen! Da sind eine Menge Piraten, die gerade an Land gehen.', '', 28153),
(155606, 'deDE', 'Da sind gerade Saurok aufgetaucht. Haben wohl das Azerit gewittert... Moment, haben die überhaupt Nasen? Na ja, ich werde sie bestimmt nicht fragen.', '', 28153),
(155605, 'deDE', 'Also, gerade eben ist ein ganzer Trupp Saurok aus dem Ozean gestiegen. Damit wisst Ihr Bescheid.', '', 28153),
(155604, 'deDE', 'Was ist denn das in den Wellen? Oh, wow, okay... da ist gerade ein ganzes Saurokheer aus den Tiefen aufgetaucht. Die gehören ganz Euch.', '', 28153),
(155603, 'deDE', 'Ein paar böse aussehende Echsen haben ein Auge auf unser Schiff und das Azerit geworfen. Könntet Ihr vielleicht dafür sorgen, dass sie leer ausgehen?', '', 28153),
(155602, 'deDE', 'Ein paar Neuankömmlinge. Die habe ich noch nie gesehen. Aber sie sind wohl kaum hier, um uns zu helfen.', '', 28153),
(155601, 'deDE', 'Ich habe ein paar seltsame Neuankömmlinge entdeckt. Sieht aus, als sind sie auf der Suche nach Azerit, wie wir auch, aber irgendwas... stimmt mit ihnen nicht.', '', 28153),
(155600, 'deDE', 'Ah! Und wo kommen die jetzt her? Die sind ja wie aus dem Nichts aufgetaucht. Alles klar, Helden? Wir haben Gesellschaft.', '', 28153),
(155599, 'deDE', 'Wer zur Hölle sind die? Ich kann ihre Gesichter nicht erkennen. Vielleicht wollen sie uns nichts Böses? Ah. Wahrscheinlich aber doch.', '', 28153),
(155598, 'deDE', 'Und jetzt scheinen wir tatsächlich die Aufmerksamkeit eines Alten Gottes und seiner Diener erregt zu haben. Also... Könntet Ihr Euch vielleicht darum kümmern?', '', 28153),
(155597, 'deDE', 'Wir haben jetzt ein paar tentakelgesichtige Monster auf der Insel. Tja, ich bin raus aus der Nummer. Ihr findet mich unter Deck. Bis dann.', '', 28153),
(155596, 'deDE', 'Hört hier sonst noch jemand Geflüster? Entweder werde ich wahnsinnig oder auf der Insel sind ein paar Gesichtslose. Ach ja, und sie sind hinter dem Azerit her.', '', 28153),
(155595, 'deDE', 'Ein Sturm aus schattendurchsetzter Dunkelheit. Grandios! Das werden Alte Götter sein. Nehmt Euch vor Tentakeln in Acht.', '', 28153),
(155594, 'deDE', 'Und da kommen Mogu. Eine Menge von denen. Sind hinter dem Azerit her. Solltet Ihr Euch besser mal ansehen...', '', 28153),
(155593, 'deDE', 'Ich habe auf der Insel eben ein paar Mogu gesehen. Haltet die Augen offen. Wir, äh, sind nicht unbedingt Freunde.', '', 28153),
(155592, 'deDE', 'Ein paar, äh, Mogu sind gerade auf der Insel gelandet. Bin nicht sicher, was die da tun. Seht Ihr Euch das mal an.', '', 28153),
(155591, 'deDE', 'Die Moguschlangen setzen einen Räubertrupp ab. Das Azerit hat sie angelockt. Wie immer.', '', 28153),
(155590, 'deDE', 'So, jetzt sind die Naga also auch da. Die haben uns gerade noch gefehlt. Lasst Euch da draußen bitte nicht umbringen.', '', 28153),
(155589, 'deDE', 'Ich habe mit dem Fernglas ein paar Naga entdeckt, die bald hier sein werden. Bereitet ihnen einen schönen Empfang, ja?', '', 28153),
(155588, 'deDE', 'Ein paar Naga haben gerade auf der Suche nach Azerit die Insel betreten. Die sind sicher im Auftrag unserer Freundin Azshara unterwegs. Was hat die eigentlich für ein Problem?', '', 28153),
(155587, 'deDE', 'Aus den Tiefen schlängeln sich Naga empor, die aussehen, als ob sie unsere Beute plündern wollen. Ich mach schon mal die Kanonen schussbereit.', '', 28153),
(155586, 'deDE', 'Nebel zieht auf. Nein, Moment, ich sehe verrottete Schiffe... Alles klar, das sind die Kvaldir. Na toll.', '', 28153),
(155585, 'deDE', 'Hey, also, wir haben Kvaldirschiffe entdeckt, und die werden bald hier sein. Müssen hinter dem Azerit her sein. Warum hab ich diesen Auftrag nochmal angenommen?', '', 28153),
(155584, 'deDE', 'Hier wird es schrecklich neblig. Das müssen die Kvaldir sein. Haltet die Augen offen... also, na ja, wenn Ihr noch etwas erkennen könnt.', '', 28153),
(155583, 'deDE', 'Mann, was riecht denn hier so nach Seetang? Oh, hey, hier drüben sind ein paar Kvaldir, Leute.', '', 28153),
(155582, 'deDE', 'Die Käfer stehen uns hier bis zum Hals... ein riesiger Mantisschwarm ist im Anflug. Ich bin dann mal unter Deck. Viel Spaß, Leute.', '', 28153),
(155581, 'deDE', 'Ich hab von diesen... Mantis oder so schon gehört, glaube ich. Ähm, Ihr kümmert Euch doch darum, oder? Ich habe eine Allergie.', '', 28153),
(155580, 'deDE', 'Ist das ein Schwarm Bienen? Nein, die sind größer. Ja, das sind die Mantis. Uuuund sie sind fast hier.', '', 28153),
(155579, 'deDE', 'Das wird Euch gefallen. Die Mantis sind gerade aufgetaucht. Natürlich sind sie auch hinter dem Azerit her. Natürlich.', '', 28153),
(155578, 'deDE', 'Boah! Was ist da gerade über uns rübergeflogen? Habt Ihr das gesehen? Da ist ein Drache auf der Insel. Passt auf.', '', 28153),
(155577, 'deDE', 'Hey, also, da ist so ein großer Drache aufgetaucht, zusammen mit einem Haufen kleiner Drachen, und die scheinen alle nicht so erfreut zu sein, dass wir uns das Azerit nehmen.', '', 28153),
(155576, 'deDE', 'Ein schwarzer Drache, ausgerechnet. Ein schwarzer Drache und die Hälfte seines Schwarms! Hier!', '', 28153),
(155575, 'deDE', 'Äh, auf der Insel ist gerade ein großer Drache gelandet. Ihr wisst, dass mein Boot brennbar ist, oder? Haltet das Vieh fern. Aber richtig fern.', '', 28153),
(155574, 'deDE', 'Da misch\'n sich Tol\'vir in die Azeritjagd ein. Schön aufgepasst da drauß\'n.', '', 28153),
(155573, 'deDE', 'He, hier sind \'n paar Tol\'vir. Die such\'n nach Azerit, genau wie wir, ha ha.', '', 28153),
(155572, 'deDE', 'Hätt nich\' gedacht, noch mal \'n Boot der Tol\'vir zu seh\'n. \'n paar von denen geh\'n an Land und seh\'n echt grimmig aus.', '', 28153),
(155571, 'deDE', 'Da komm\'n Boote. Die hab ich bisher nur einmal geseh\'n. Die nenn\'n sich die Tol\'vir. Und die seh\'n nich\' freundlich aus.', '', 28153),
(155570, 'deDE', '', 'Versucht, das Relikt in einem Stück zurückzubringen, $n. Astrandis ist... etwas übereifrig.', 28153),
(155569, 'deDE', '', 'Es is\' in unser aller Interesse, die Gewässer von Pirat\'n freizuhalt\'n. Danke.', 28153),
(155568, 'deDE', 'Ich werde Euch in den Hafen werfen.', '', 28153),
(155567, 'deDE', 'Nicht nur die Gezeiten sind verärgert.', '', 28153),
(155566, 'deDE', 'Ihr wisst nicht, wessen Zorn Ihr weckt.', '', 28153),
(155565, 'deDE', '', 'Wir müss\'n wiss\'n, was die Piraten planen. Fangt ihre Befehle ab... egal, was Ihr dafür mach\'n müsst.', 28153),
(155564, 'deDE', 'Die Flut kehrt immer zurück.', '', 28153),
(155561, 'deDE', 'Möge der Wind Eure Segel füllen.', '', 28153),
(155560, 'deDE', 'Wendet Euch nie von der See ab.', '', 28153),
(155558, 'deDE', 'Ich verabscheue Vögel. Krächzende, schmutzige Tiere. Doch nun zu wichtigeren Angelegenheiten.', '', 28153),
(155557, 'deDE', 'Einer unserer Kontakte in Freihafen erbittet Unterstützung beim... Beruhigen seiner Vögel. Das solltet Ihr bewältigen können.', '', 28153),
(155556, 'deDE', 'Ich diene den Gezeiten.', '', 28153),
(155554, 'deDE', 'Spürt Ihr sie... auch... die Macht des Steins?', '', 28153),
(155553, 'deDE', 'Dieser Stein wird uns REICH machen! Ihr könnt ihn nicht haben!', '', 28153),
(155552, 'deDE', 'Die Flut leite Euch.', '', 28153),
(155551, 'deDE', 'Wenn Ihr den Gezeiten lauscht, könnt Ihr viel über die Welt lernen.', '', 28153),
(155550, 'deDE', 'Ich habe einen Verdacht...', '', 28153),
(155549, 'deDE', 'Bringt mich nicht dazu, die Wachen zu rufen.', '', 28153),
(155548, 'deDE', 'Wenn Ihr etwas zu sagen habt, heraus damit!', '', 28153),
(155547, 'deDE', 'Bitte... verschont meine Katze.', '', 28153),
(155546, 'deDE', 'Bitte, ich bin ein vielbeschäftigter Mann.', '', 28153),
(155545, 'deDE', 'Bitte kommt wieder mit neuen Geschichten von Euren Abenteuern!', '', 28153),
(155543, 'deDE', 'Da sind noch mehr von Nantes Laufburschen! Ich werde sie genau wie die anderen in den Schlamm rammen!', '', 28153),
(155540, 'deDE', 'Prächtig!', '', 28153),
(155539, 'deDE', 'Ich wünsche Euch prächtige Unterhaltung!', '', 28153),
(155538, 'deDE', 'Fühlt Euch wie zu Hause. Mein Anwesen ist Euer Anwesen.', '', 28153),
(155536, 'deDE', 'Esst, trinkt, amüsiert Euch!', '', 28153),
(155535, 'deDE', 'Willkommen zum Reit- und Jagdfest der Norwinsens!', '', 28153),
(155534, 'deDE', '', 'Und fünfhundert Milliarden Norgabyte an Bilddateien abgelegt unter \"Süße Kätzchen\".', 28153),
(155533, 'deDE', 'Ein Champion, wenn man ihn braucht! Wir werden von den Troggs angegriffen!', '', 28153),
(155532, 'deDE', '', 'Sie spiel\'n mit Mächten, mit denen niemand spiel\'n sollte. Wir müss\'n die Meere sicher halt\'n!', 28153),
(155531, 'deDE', 'Krieger der Horde! Zeigt der Allianz, für was wir kämpf\'n! Stürmt die Burg!', '', 28153),
(155530, 'deDE', '', 'Kämpft als Einheit! Zum Angriff! Arathi wird uns gehören!', 28153),
(155529, 'deDE', '', 'Die Menschen ruf\'n ein übles Wesen aus den Tief\'n. Haltet sie auf!', 28153),
(155528, 'deDE', 'Tortollaner?', 'Tortollaner?', 28153),
(155527, 'deDE', '', 'Der Panzer da drüben mit Armen und Beinen!\n\nLasst Euch nicht von ihm hinters Licht führen. Er ist schlau und ziemlich neugierig! Er schnüffelt überall herum und sammelt alte Relikte, Schriftrollen und Plunder.\n\nWir wollen nicht, dass er den Schatz zuerst findet.', 28153),
(155526, 'deDE', 'Davon wird mein Onkel erfahren!', '', 28153),
(155525, 'deDE', 'Bitte tretet ein paar Schritte zurück.', '', 28153),
(155524, 'deDE', 'Entschuldigung, könnt Ihr mich bitte in Frieden lassen?', '', 28153),
(155522, 'deDE', 'Ich schätze, das wär\'s dann.', '', 28153),
(155521, 'deDE', 'Niemand hat mir gesagt, wie... schwierig es ist, ein Anführer zu sein.', '', 28153),
(155520, 'deDE', 'Ich tue, was ich kann.', '', 28153),
(155516, 'deDE', 'Der Angelpunkt untersteht meiner Obhut!', '', 28153),
(155515, 'deDE', 'Ich muss mich meinem Onkel beweisen.', '', 28153),
(155514, 'deDE', 'Die See sei Euch gewogen.', '', 28153),
(155513, 'deDE', 'Gut.', '', 28153),
(155512, 'deDE', 'Wenn Ihr nichts braucht, geht bitte weiter.', '', 28153),
(155511, 'deDE', 'Wieder auf Posten.', '', 28153),
(155510, 'deDE', 'Ich habe eine Pflicht zu erfüllen.', '', 28153),
(155509, 'deDE', 'Hmpf.', '', 28153),
(155508, 'deDE', 'Ausgezeichnet! Damit sollte ich einige... interessante Tränke herstellen können.', '', 28153),
(155507, 'deDE', 'Dieses Gebiet quillt über von natürlichen Ressourcen und faszinierenden alchemistischen Reagenzien! Bringt mir einige dieser wertvollen Materialien.', '', 28153),
(155506, 'deDE', '', 'Unsere Bauern sind Euch sehr dankbar für Eure Hilfe bei der Eindämmung der hiesigen Fauna.', 28153),
(155505, 'deDE', '', 'Wilde Tiere bedrohen unsere Bauernhöfe an der Küste. Helft den Bauern und kümmert Euch um das Problem.', 28153),
(155504, 'deDE', 'Eine weitere Berührung ruft eine schwerwiegende, potenziell tödliche Reaktion hervor.', '', 28153),
(155503, 'deDE', 'Macht das nochmal und ihr werdet sehen, dass wir nicht immer so lustig sind.', '', 28153),
(155502, 'deDE', 'Wenn wir unseren Hut verlieren, werdet Ihr es bereuen.', '', 28153),
(155501, 'deDE', 'Wäre das alles?', '', 28153),
(155500, 'deDE', 'Wachst mit Ehre. Unser Geist ist klar.', '', 28153),
(155499, 'deDE', 'Mögen die Sporen mit Euch sein.', '', 28153),
(155498, 'deDE', 'Wir sehen Euch.', '', 28153),
(155497, 'deDE', 'Wir überbringen Grüße!', '', 28153),
(155496, 'deDE', 'Es muss immer einen... Pilzkönig geben...', '', 28153),
(155495, 'deDE', 'Sporgram hungert!', '', 28153),
(155494, 'deDE', 'Ahhh!', '', 28153),
(155493, 'deDE', 'Auf dass die Sporen uns finden...', '', 28153),
(155492, 'deDE', 'Wir... hören... nichts...', '', 28153),
(155491, 'deDE', 'Sterbt! Töten! Töten!', '', 28153),
(155490, 'deDE', 'Werdet einer von uns!', '', 28153),
(155489, 'deDE', 'Sterbt! Sterbt! Sterbt!', '', 28153),
(155488, 'deDE', '', 'Ha! Ein solcher Erfolg würde selbst die Sturmtakler neidisch machen.', 28153),
(155487, 'deDE', 'Irgendein verfluchtes Monster labt sich an den Eingeweiden unserer Rekruten. Tötet es... bevor ich noch mehr unerfahrene Neulinge rekrutieren muss.', '', 28153),
(155486, 'deDE', '', 'Ein paar Wachen von Kul Tiras haben von einer großen Bestie in der Gegend berichtet. Eine Gefahr für jeden, der diese Gewässer befährt.', 28153),
(155485, 'deDE', 'Es gibt Piratengeschichten von einem Skelettdämon im Sund. Diese Erklärung hört sich viel plausibler an.', '', 28153),
(155484, 'deDE', 'An der Küste hat sich eine große Bestie an Land geschleppt. Bin nicht sicher, woher sie kommt, aber die sieht gefährlich aus.', '', 28153),
(155483, 'deDE', 'Erstklassige Arbeit! Manche haben in Tol Dagor zu Recht eingesessen. Der war einer davon.', '', 28153),
(155482, 'deDE', '', 'Der Irre war gemeingefährlich. Ihr habt heute viele Leb\'n gerettet.', 28153),
(155481, 'deDE', 'Ich werde jetzt gehen...', 'Ich werde jetzt gehen...', 28153),
(155480, 'deDE', 'Ich bin jetzt in Sicherheit.', 'Ich bin jetzt in Sicherheit.', 28153),
(155479, 'deDE', 'Danke.', 'Danke.', 28153),
(155478, 'deDE', 'Ich möchte Ruhe finden...', 'Ich möchte Ruhe finden...', 28153),
(155477, 'deDE', 'Ich war so verloren...', 'Ich war so verloren...', 28153),
(155476, 'deDE', 'Ich hatte so große Angst... Aber jetzt nicht mehr...', 'Ich hatte so große Angst... Aber jetzt nicht mehr...', 28153),
(155475, 'deDE', 'Seid Ihr wohlauf?', '', 28153),
(155474, 'deDE', 'Das Licht ist so warm...', 'Das Licht ist so warm...', 28153),
(155473, 'deDE', '', 'Danke für Eure Hilfe! Wir werden Euch das nie vergessen.', 28153),
(155471, 'deDE', 'Hier entlang.', 'Hier entlang.', 28153),
(155470, 'deDE', 'Nachladen!!!', 'Nachladen!!!', 28153),
(155469, 'deDE', '', 'Ketzer! Ihr werdet Euch nicht einmischen!', 28153),
(155468, 'deDE', 'Feuer!!!', 'Feuer!!!', 28153),
(155467, 'deDE', '', 'Zandalar besteht aus Gold. Es muss doch einen Weg geben, die ganze Stadt zu stehlen!', 28153),
(155466, 'deDE', '', 'Ein Ausbrecher aus\'m Menschengefängnis is\' in der Nähe vom Hordenhafen gelandet. Er is\' \'ne Gefahr für uns alle.', 28153),
(155465, 'deDE', 'Ich glaube, ich kenne den Kerl! Wartet... ja, den kenne ich definitiv. Das ist gar nicht gut.', '', 28153),
(155464, 'deDE', 'Die Tiefen... werden uns... mehr geben!', '', 28153),
(155463, 'deDE', 'Diese Macht ist ein Geschenk aus den Tiefen!', '', 28153),
(155462, 'deDE', 'Ich dachte, diese Kul Tiraner könnten sich als würdige Gegner erweisen... aber sie sind genauso weichlich, wie all die anderen Allianzwürmer.', '', 28153),
(155461, 'deDE', 'Eine Dunkle Waldläuferin hat einen Berater des Großadmirals herausgelockt. Die Falle wartet nur darauf, zuzuschnappen... Ich überlasse Euch die Ehre.', '', 28153),
(155460, 'deDE', '', 'Die Geister der Toten haben wieder Frieden gefunden.', 28153),
(155459, 'deDE', 'Na gut... aber Ihr kommt zurück, oder?', '', 28153),
(155458, 'deDE', 'Na gut. Bis später dann!', '', 28153),
(155457, 'deDE', 'Das lehrt die Horde, sich nicht mit unseren Marinesoldaten anzulegen! Gute Arbeit.', '', 28153),
(155456, 'deDE', 'Einer der Prachtmeeroffiziere hat eine Dunkle Waldläuferin gestellt! Helft ihm!', '', 28153),
(155455, 'deDE', 'Ich bin so stolz auf meinen Papa!', '', 28153),
(155454, 'deDE', 'Das wird ein toller Tag!', '', 28153),
(155453, 'deDE', 'Papa sagt, die Großen fürchten sich manchmal. Fürchtet Ihr Euch manchmal?', '', 28153),
(155452, 'deDE', 'Boah, guckt mal, die hübschen Ponys!', '', 28153),
(155451, 'deDE', 'Zum Lernen ist man nie zu alt!', '', 28153),
(155450, 'deDE', 'Bis zum nächsten Mal!', '', 28153),
(155449, 'deDE', '', 'Hexendiener haben die Geister der Toten in Aufruhr versetzt. Vernichtet die verderblichen Einflüsse und bettet die Verlorenen wieder zur Ruhe.', 28153),
(155448, 'deDE', 'Tja, nun... Wenigstens konnt ich noch \'n letztes Mal \'nen edlen Zanchulitropfen probier\'n... <hicks!> ...bevor ich sterb!', '', 28153),
(155447, 'deDE', 'Ich hab gehört, wie sie gesagt hab\'n, dass Mojambo Verstärkung für den Kampf angeheuert hat. Er bekommt jetz\' Rückendeckung von Tongos Mannschaft...', '', 28153),
(155446, 'deDE', 'Ich hab Mojambos Bande die Arena auskundschaft\'n seh\'n...', '', 28153),
(155445, 'deDE', 'Ihr habt Euren Teil der Abmachung eingehalt\'n, also halt ich auch meinen ein...', '', 28153),
(155444, 'deDE', 'Ahhh! Es is\' schon Jahre her, dass ich \'nen edlen Zanchulitropfen probiert hab...<hicks!>', '', 28153),
(155443, 'deDE', 'Hier ist der Rum. Erzählt mir, was Ihr gehört habt.', 'Hier ist der Rum. Erzählt mir, was Ihr gehört habt.', 28153),
(155442, 'deDE', 'Na dann, auf Wiedersehen! Ihr findet mich... hier.', '', 28153),
(155441, 'deDE', 'Ich bin auf der Suche nach Wissen. Was versucht Ihr zu finden?', '', 28153),
(155440, 'deDE', 'Die Reise war lang und beschwerlich, aber wir sind angekommen!', '', 28153),
(155439, 'deDE', 'Gute Jagd.', '', 28153),
(155438, 'deDE', 'Für die Horde!', '', 28153),
(155437, 'deDE', 'Soll ich was aufspüren?', '', 28153),
(155436, 'deDE', 'Bei Reißzahn und Klaue!', '', 28153),
(155435, 'deDE', 'Das war\'s, ich bringe Euch zur Strecke!', '', 28153),
(155434, 'deDE', 'Ernsthaft, lasst das!', '', 28153),
(155433, 'deDE', 'Ich... ähm... ich jage allein.', '', 28153),
(155432, 'deDE', 'Lasst die Jagd beginnen!', '', 28153),
(155431, 'deDE', 'So soll es sein.', '', 28153),
(155430, 'deDE', 'Auf der Pirsch.', '', 28153),
(155429, 'deDE', 'Die Jagd beginnt.', '', 28153),
(155428, 'deDE', 'Meine Beute naht.', '', 28153),
(155427, 'deDE', 'Ich vernehme den Ruf der Wildnis.', '', 28153),
(155426, 'deDE', 'Seht Ihr diese Pferde? Majestätische Kreaturen!', '', 28153),
(155425, 'deDE', 'Kommt bald zurück!', '', 28153),
(155424, 'deDE', 'Nicht vergessen: Keine Wildtiere füttern!', '', 28153),
(155423, 'deDE', 'Genießt Euren Aufenthalt!', '', 28153),
(155422, 'deDE', '...', '', 28153),
(155421, 'deDE', 'Wieso sind wir hier unten?', 'Wieso sind wir hier unten?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'deDE', 'Was wolltet Ihr mir sagen?', 'Was wolltet Ihr mir sagen?', 28153),
(155419, 'deDE', 'Wir dürfen nicht trödeln. Wir haben nicht viel Zeit.', 'Wir dürfen nicht trödeln. Wir haben nicht viel Zeit.', 28153),
(155418, 'deDE', 'Wie geht\'s, wie steht\'s?', '', 28153),
(155417, 'deDE', 'Hallöchen!', '', 28153),
(155416, 'deDE', 'Willkommen in Zischfeders Resort!', '', 28153),
(155415, 'deDE', '', 'Die Macht des Steins... wird... meinen Schwestern gehören!', 28153),
(155414, 'deDE', '', 'Die Macht dieses Steins wird Mutter gefallen!', 28153),
(155413, 'deDE', 'Ihr entscheidet, auf welches Gebiet wir uns zuerst konzentrieren. Trefft Eure Wahl und wir stechen umgehend in See.', '', 28153),
(155412, 'deDE', 'Also dann, $n. Je früher wir beginnen, desto besser. Einer unserer Agenten ist bereit für eine wichtige Mission.', '', 28153),
(155411, 'deDE', 'Möge das Licht mit Euch sein, mein König.', '', 28153),
(155410, 'deDE', 'Gute Reise, mein König.', '', 28153),
(155409, 'deDE', 'Meine Pflichten rufen mich zurück nach Sturmwind, aber ich freue mich bereits auf Eure Fortschritte. Ich bin überzeugt, dass dieser Feldzug in fähigen Händen liegt. Viel Glück Euch allen.', '', 28153),
(155408, 'deDE', 'Champion.', '', 28153),
(155407, 'deDE', 'Für Situationen, die etwas mehr... Fingerspitzengefühl erfordern, stehen Euch Meister Mathias Shaw und seine Agenten des SI:7 zur Verfügung.', '', 28153),
(155406, 'deDE', 'Es ist eine Ehre, an Eurer Seite zu stehen, $n.', '', 28153),
(155405, 'deDE', 'Zu Eurer Unterstützung habe ich eine Gruppe der besten Krieger aus ganz Azeroth abgestellt – die 7. Legion, angeführt von Hochkommandant Halford Wyrmbann.', '', 28153),
(155404, 'deDE', 'Als einer der größten Helden der Allianz spielt Ihr eine tragende Rolle in unseren Bemühungen, diesen Krieg zu gewinnen. Wir dürfen nicht zulassen, dass die Horde mit den Zandalari eine Front bildet.', '', 28153),
(155403, 'deDE', '$n, es wird Zeit, den Kampf nach Zandalar zu tragen. Ich erwarte Eure Ankunft an Bord der \"Die Erlösenden Winde\".', '', 28153),
(155402, 'deDE', 'Diese Wälder sind verflucht. Raus hier! Lauft weg, solange Ihr noch könnt!', 'Diese Wälder sind verflucht. Raus hier! Lauft weg, solange Ihr noch könnt!', 28153),
(155401, 'deDE', 'So etwas Wahnsinniges habe ich noch nie gesehen!', 'So etwas Wahnsinniges habe ich noch nie gesehen!', 28153),
(155400, 'deDE', 'Sie haben meinen Hund gefressen! Und ich wäre als Nächstes dran gewesen!', 'Sie haben meinen Hund gefressen! Und ich wäre als Nächstes dran gewesen!', 28153),
(155399, 'deDE', 'Was im Namen der Seepocken an meines Opas Schiff geht hier vor?', 'Was im Namen der Seepocken an meines Opas Schiff geht hier vor?', 28153),
(155398, 'deDE', 'Ich wurde von einem Rudel Kaninchen gejagt! Kaninchen!', 'Ich wurde von einem Rudel Kaninchen gejagt! Kaninchen!', 28153),
(155397, 'deDE', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 28153),
(155396, 'deDE', 'Die Tiere sind verrückt geworden!', 'Die Tiere sind verrückt geworden!', 28153),
(155395, 'deDE', 'Ich danke Euch!', 'Ich danke Euch!', 28153),
(155394, 'deDE', 'Da schlängel\'n sich Naga an Land. \'ne ganze Menge von den\' woll\'n die Insel plündern.', '', 28153),
(155393, 'deDE', 'Hier tauch\'n Naga auf. Wittern wohl das Azerit, das Ihr gesammelt habt. Haltet die Aug\'n offen.', '', 28153),
(155392, 'deDE', 'Die Naga sin\' grade aufgetaucht. Dann heißt sie doch willkomm\'n, ha!', '', 28153),
(155391, 'deDE', 'Die Naga komm\'n aus den Tief\'n un\' woll\'n sich die Schätze hol\'n. Genau wie wir. Passt auf.', '', 28153),
(155390, 'deDE', 'Seht Euch vor, in der Ferne wurde \'n großer Drache samt Anhang gesichtet, der genau auf uns zufliegt.', '', 28153),
(155389, 'deDE', 'Da komm\'n grade \'ne Menge Drach\'n angeflog\'n, die anfang\'n, sich das Azerit zu schnapp\'n. Vielleicht wollt Ihr dem ja \'n Ende setz\'n.', '', 28153),
(155388, 'deDE', 'He, wir ham Besuch. Da is\' grad\'n Drachenschwarm aufgetaucht, und die ham \'n Auge auf unser Schiff geworf\'n.', '', 28153),
(155387, 'deDE', 'Da kommt was angeflog\'n... sieht nach Drachen aus. Sind sicher hinterm Azerit her. Seid vorsichtig.', '', 28153),
(155386, 'deDE', 'Schwarzdrach\'n... Hier? Die müss\'n auch hinterm Azerit her sein. Passt auf.', '', 28153),
(155385, 'deDE', 'Drach\'n... Hätt nie gedacht, dass ich mal \'n ausgewachsenen Drach\'n seh. Die woll\'n Azerit. Unser Azerit.', '', 28153),
(155384, 'deDE', 'Jau, da drüben land\'n \'n paar Drach\'n. Die hat wohl das Azerit angelockt.', '', 28153),
(155383, 'deDE', 'Der Himmel wird dunkel... \'n schwarzer Drache! Er hat seine Kinder dabei un\' will wohl die Insel plündern! Hilfe!', '', 28153),
(155382, 'deDE', 'Da sin\' \'ne Menge Leute un\' Ausrüstung der Venture Company angekomm\'n. Die such\'n nach Azerit.', '', 28153),
(155381, 'deDE', 'Die Venture Company will auf der Insel hier \'ne Operationsbasis erricht\'n. Vielleicht solltet Ihr die aufhalt\'n.', '', 28153),
(155380, 'deDE', 'Da sin\' Investor\'n der Venture Company gekomm\'n, um uns unsre Beute wegzunehm\'n. Geht und zeigt denen mal, wie wir geschäftliche Besprechung\'n führ\'n.', '', 28153),
(155379, 'deDE', 'He, Freunde, die Venture Company is\' hier. Die scheinen sich grad einzuricht\'n.', '', 28153),
(155378, 'deDE', 'Ay, seht, da drüben, \'n Haufen Inseltrollschiffe. Die sin\' auch weg\'n dem Azerit hier. Lasst es sie nich\' in die Finger bekomm\'n, ha!', '', 28153),
(155377, 'deDE', '\'n paar Inseltrolle sind grad angekomm\'. Die woll\'n bestimmt die Insel plündern. Augen auf.', '', 28153),
(155376, 'deDE', 'Am Horizont sin\' Kanus von den Inseltrollen aufgetaucht. Die konnt ich noch nie leid\'n. Erledigt \'n paar von denen für mich, ja?', '', 28153),
(155375, 'deDE', 'Da komm\' \'n paar Inseltrolle an Land, und die seh\'n nich\' freundlich aus.', '', 28153),
(155374, 'deDE', 'Wir lieg\'n hier drüb\'n unter Kanonenfeuer. Das Piratenschiff is\' vor Anker gegang\'n, um die Insel zu plündern.', '', 28153),
(155373, 'deDE', 'Ay, jetzt hab\'n wir hier auch noch Pirat\'n. Die geh\'n grade an Land. Geht sie doch willkomm\'n heiß\'n.', '', 28153),
(155372, 'deDE', 'Da geht \'ne Piratenmannschaft an Land und sucht das, was wir auch such\'n. Seid vorsichtig.', '', 28153),
(155371, 'deDE', 'Ich mag... Euch nicht...', 'Ihr solltet... echt abhauen...', 28153),
(155370, 'deDE', 'Noch\'n Schiff am Horizont. Sieht nach Piraten aus. Werdet die besser schnell los, bevor sie uns unsre ganze Beute abnehm\'.', '', 28153),
(155369, 'deDE', 'Das Geschläng\'l kenn ich. Da kommt \'n Saurokangriff auf uns zu. Seht Euch vor.', '', 28153),
(155368, 'deDE', 'In den Wellen bewegt sich irgendwas. Sieht so aus, als sind grad Saurok aufgetaucht. Und zwar \'ne ganze Menge.', '', 28153),
(155367, 'deDE', 'Hier gibt\'s \'n paar fies dreinblick\'nde Echs\'n, die unser Boot schief anguck\'n. Erledigt sie lieber. Beeilung!', '', 28153),
(155366, 'deDE', 'Da kommt\'n Kriegstrupp der Saurok direkt aus\'m Wasser. Die woll\'n sich auch das Azerit hol\'n.', '', 28153),
(155365, 'deDE', 'Nein... nicht ins Gesicht...', 'Ist ja gut jetzt...', 28153),
(155364, 'deDE', 'Ich werd meine... Frist nicht einhalten...', 'Dafür bin ich... nicht versichert...', 28153),
(155363, 'deDE', 'Hört\'er das? Die Mantis woll\'n hier wohl auch Azerit find\'n. Nich\' stech\'n lassen, ha-ha!', '', 28153),
(155362, 'deDE', 'Da kommt\'n riesiger Käferschwarm. Passt da drauß\'n auf Euch auf... die woll\'n das, was wir auch woll\'n.', '', 28153),
(155361, 'deDE', 'Die Viecher sin\' gerade aufgetaucht, das sin\' wohl Mantis. Un\' ich glaub, die woll\'n sich hier auch \'n bisschen Azerit hol\'n.', '', 28153),
(155360, 'deDE', 'Das Gesumme... Das kommt vom Himmel. Ich glaub, da sin\' \'ne Menge Insekten, die auf der Insel land\'n woll\'n.', '', 28153),
(155359, 'deDE', 'Dafür zahlt... meine Versicherung doppelt...', 'Das ist... so peinlich...', 28153),
(155358, 'deDE', 'Geister... holt mich zu Euch...', 'Geister... holt mich zu Euch...', 28153),
(155357, 'deDE', 'Un\' was riecht hier nach Seetang? Da drüben! Da land\'n Kvaldirlangboote an der Küste.', '', 28153),
(155356, 'deDE', 'In diesem Nebel kann ich nix seh\'n. Da draußen sin\' bestimmt Kvaldir. Passt auf Euch auf.', '', 28153),
(155355, 'deDE', 'Da komm\'n morsche Schiffe angesegelt, und die stink\'n nach Kvaldir. Die woll\'n unser Azerit.', '', 28153),
(155354, 'deDE', 'Hier wird\'s neblig, und der Nebel is\' kein normaler. Hier komm\'n bald Kvaldir an.', '', 28153),
(155353, 'deDE', 'So war das... nich\' geplant...', 'So war das... nich\' geplant...', 28153),
(155352, 'deDE', 'Ich wollt schon immer \'n Pirat\'nschiff, $gScheff:Scheffin;. Hab\'s nach meiner Tochter Mala benannt!\n\nWenn ich \'n Luftschiff krieg, nenn ich\'s nach meinem Sohn!', '', 28153),
(155351, 'deDE', 'Wie seid Ihr auf den Namen gekommen?', 'Wie seid Ihr auf den Namen gekommen?', 28153),
(155350, 'deDE', 'Eheheheheheheh...\n\nDas is\' \'ne Geschichte für \'n andres Mal, $gScheff:Scheffin;.', '', 28153),
(155349, 'deDE', 'Wo habt Ihr das Schiff her?', 'Wo habt Ihr das Schiff her?', 28153),
(155348, 'deDE', 'Garona hat mich losgeschickt, \'n Boot such\'n. Also hab ich eins besorgt.', '', 28153),
(155347, 'deDE', 'Wieso habt Ihr ein Piratenschiff?', 'Wieso habt Ihr ein Piratenschiff?', 28153),
(155346, 'deDE', 'Da komm\'n grad \'n paar neue Freunde an, ha ha. Ich glaub, das sin\' Vrykulkrieger.', '', 28153),
(155345, 'deDE', 'He, da is\' grad noch wer aufgetaucht. Sieht nach Vrykulplünderern aus. Aufgepasst.', '', 28153),
(155344, 'deDE', 'Da leg\'n grad Langschiffe der Vrykul an. \'n Plündertrupp. Die woll\'n unsre Beute.', '', 28153),
(155343, 'deDE', 'Heda, $gScheff:Scheffin;. Bereit für \'ne kleine Meuterei?', '', 28153),
(155342, 'deDE', 'Das sin\' Langboote am Horizont. Das müss\'n Vrykul sein, die nach Edelsteinen such\'n.', '', 28153),
(155341, 'deDE', 'Irgendwas hat uns die Tot\'n auf\'n Hals gehetzt. Irgendwas, das nich\' von dieser Welt is\'. Passt auf.', '', 28153),
(155340, 'deDE', 'Die Geister sag\'n mir, dass die Tot\'n hier sin\'. Und dass sie Euer Azerit woll\'n.', '', 28153),
(155339, 'deDE', 'Argh, dieser Gestank! Da müss\'n Untote hinter unserm Azerit her sein. Passt auf.', '', 28153),
(155338, 'deDE', 'Diese Dunkelheit is\' unnatürlich. Irgendwas is\' weg\'n dem Azerit hierher unterwegs. Irgendwas Böses.', '', 28153),
(155337, 'deDE', 'Da komm\'n \'n paar merkwürdige neue Leute Euer Azerit besuch\'n. Die seh\'n wie \'ne Art Kult aus.', '', 28153),
(155336, 'deDE', 'Woah, hab die Typ\'n nich\' mal komm\'n seh\'n. Ihr bekommt Gesellschaft. Seht Euch vor!', '', 28153),
(155335, 'deDE', 'He, wer sind\'n die? Sieht aus, als ob die auch Azerit samm\'ln. Solltet Ihr wohl aufhalt\'n.', '', 28153),
(155334, 'deDE', 'Wir ham neue Freunde. Komm\' mir nich\' bekannt vor. Sind vermutlich hinterm Azerit her.', '', 28153),
(155333, 'deDE', 'Knapp vor der Küste sin\' \'n paar Moguschlangen. Sie werd\'n gleich hier sein.', '', 28153),
(155332, 'deDE', 'Da sin\' gerade Mogu aufgetaucht, die sich an unsrem Kram vergreif\'n woll\'n. Bereitet denen \'n schönen Empfang.', '', 28153),
(155331, 'deDE', 'Einer von den Mogu will unser Azerit. Schön die Aug\'n nach Plündertrupps offen halt\'n.', '', 28153),
(155330, 'deDE', 'Hab geseh\'n, wie in der Ferne \'n paar Wolkenschlang\'n angeflog\'n komm\'n. Die Mogu werd\'n bald hier sein.', '', 28153),
(155329, 'deDE', 'Da is \'n Schattensturm... sind sicher Gesichtslose auf\'m Weg hierher.', '', 28153),
(155328, 'deDE', 'Ay, hört Ihr auch dieses Geflüster? Muss \'n Alter Gott sein, der seine Trupp\'n auf uns hetzt. Passt auf.', '', 28153),
(155327, 'deDE', 'Da woll\'n sich \'n paar tentakelgesichtige Freunde hier Euer Azerit schnapp\'n. Ich werd ma\'... in Deckung geh\'n.', '', 28153),
(155326, 'deDE', 'Das Azerit hat die Gesichtslos\'n angelockt. Hier sind grad \'ne Menge von denen aufgetaucht.', '', 28153),
(155325, 'deDE', 'Böser Vogel! Kein Blut.', 'Böser Vogel! Kein Blut.', 28153),
(155324, 'deDE', 'Husch!', 'Husch!', 28153),
(155323, 'deDE', '', 'Die Wälder von Schluchtbach sind für unsere Jäger wieder sicher.', 28153),
(155322, 'deDE', '', 'Die Tiere sind dem Einfluss der Hexen erlegen und machen Jagd auf unsere Jäger! Rettet sie – rottet diese verfluchten Bestien aus!', 28153),
(155321, 'deDE', '', 'Ihr seid wie ein kleiner Scherzbold an meiner Seite, $p.', 28153),
(155320, 'deDE', '', 'Ihr kommt mir wirklich bekannt vor... Habt Ihr in Tol Dagor gesessen?', 28153),
(155319, 'deDE', '', 'Gut gemacht. Die Tiere in diesen Hügeln stellen keine Bedrohung mehr für die Siedlungen in der Gegend dar.', 28153),
(155318, 'deDE', '', 'Die Wildtiere in diesen Hügeln wurden von dem Fluch der Hexen verzaubert! Setzt dem ein Ende, bevor sie noch die Stadt erreichen.', 28153),
(155317, 'deDE', 'Das Atmen wird schwieriger!', 'Das Atmen wird schwieriger!', 28153),
(155312, 'deDE', 'Es wird dauern, bis sie sich von diesem Angriff erholt haben. Für die Dunkle Fürstin!', '', 28153),
(155311, 'deDE', 'Die Truppen unseres Kriegshäuptlings sind in die Militärakademie vorgedrungen. Unterstützt sie.', '', 28153),
(155310, 'deDE', '', 'Ich habe mit ein paar dieser Männer trainiert! Dafür wird die Horde bluten!', 28153),
(155309, 'deDE', '', 'Eine Elitegruppe der Horde ist in die Prachtmeerakademie eingedrungen. Die Marinesoldaten könnten unsere Hilfe gebrauchen!', 28153),
(155308, 'deDE', '', 'Fallhafen ist wieder sicher, aber wir müssen wachsam bleiben.', 28153),
(155307, 'deDE', '', 'Der Fluch der Hexen lastet erneut auf Fallhafen. Brecht ihn, bevor die Stadt verloren ist!', 28153),
(155306, 'deDE', '', 'Hah!... Die Macht der Steine... muss... Sturmsang gehören!', 28153),
(155305, 'deDE', '', 'Dieser Stein ist eine Gabe aus der Tiefe. Ihr dürft ihn nicht haben!', 28153),
(155304, 'deDE', 'Als er verwelkt is\', wusst ich, dass ich allein war. Also hab ich mir \'ne Arbeit an den Docks gesucht. Die Blume hat mich davor bewahrt, \'n Landstreicher zu werd\'n, wie es so viel\'n andren passiert is\'.', 'Als er verwelkt is\', wusst ich, dass ich allein war. Also hab ich mir \'ne Arbeit an den Docks gesucht. Die Blume hat mich davor bewahrt, \'n Landstreicher zu werd\'n, wie es so viel\'n andren passiert is\'.', 28153),
(155303, 'deDE', 'Ganz gleich, ob es Stacheleber oder Eindringlinge der Horde sind... die Bewohner dieses Tals widersetzen sich erhobenen Hauptes.', '', 28153),
(155302, 'deDE', 'Nicht wegnehmen... Troggsteine...', '', 28153),
(155301, 'deDE', 'Meine Steine...', '', 28153),
(155300, 'deDE', 'Euch... zerschmettern...', '', 28153),
(155299, 'deDE', 'Trogg... zerschlagen...', '', 28153),
(155298, 'deDE', 'Trogg zerbröckeln...', '', 28153),
(155297, 'deDE', 'Trogg... töten...', '', 28153),
(155296, 'deDE', 'Arrraagh!', '', 28153),
(155295, 'deDE', 'Garuuu...', '', 28153),
(155294, 'deDE', 'Hier Troggland! Ihr verschwinden!', '', 28153),
(155293, 'deDE', 'Aaaraauuh! Trogg Euch töten!', '', 28153),
(155292, 'deDE', 'Ich Euch zu Kieselsteinchen zermalmen!', '', 28153),
(155291, 'deDE', '', 'Ich habe in ganz Kul Tiras die Dinge reibungslos am Laufen gehalten. Wie kann ich Euch helfen?', 28153),
(155290, 'deDE', 'Glitzersteine gehören Trogg! Geht weg!', '', 28153),
(155289, 'deDE', 'Graaaraah! Zerstören!', '', 28153),
(155288, 'deDE', 'Trogg Euer Gesicht zermalmen!', '', 28153),
(155287, 'deDE', 'Trogg Euren Schädel aufbrechen!', '', 28153),
(155286, 'deDE', 'Hier Troggland!', '', 28153),
(155285, 'deDE', 'Troggzor!', '', 28153),
(155284, 'deDE', 'Meine Steine! Nicht Eure!', '', 28153),
(155283, 'deDE', 'Mein Schatz! Meiner!', '', 28153),
(155282, 'deDE', 'Rarrragh!', '', 28153),
(155281, 'deDE', 'Aaaraaagh!', '', 28153),
(155280, 'deDE', 'Zermalmen! Zerbrechen! TÖTEN!', '', 28153),
(155279, 'deDE', 'Trogg hauen!', '', 28153),
(155278, 'deDE', 'Trogg nicht blöd!', '', 28153),
(155277, 'deDE', 'Ey! Habt Ihr geseh\'n, was die Prinzessin mit der Allianz gemacht hat? Links von Euch könnt Ihr die Trümmer seh\'n. Das war die wahre Macht von \'nem Loa!', '', 28153),
(155276, 'deDE', 'Die Naga war\'n für \'ne Weile weg. Wir ham vom Neuaufbau gesproch\'n. Aber solange Gral vermisst war oder zu schwach, um zu helf\'n, war es alles nur Geschwätz.', '', 28153),
(155275, 'deDE', 'Alle Anhänger wurd\'n getötet. Gral war so zornig! In der Nacht ham alle am Wasser seinen Schmerz gespürt... als sie nach und nach gefall\'n sin\'.', '', 28153),
(155274, 'deDE', 'Oh ho! Es war, als wäre eine Last von uns genommen worden! Wir wussten, dass diese schlangenhaarige Hexe jetzt tot ist!', '', 28153),
(155273, 'deDE', 'Ich wünsche einen umwerfenden Tag.', '', 28153),
(155272, 'deDE', 'Seid vorsichtig. Das Land ist nicht mehr sicher.', '', 28153),
(155271, 'deDE', 'Sturmsang ist voller Schätze.', '', 28153),
(155270, 'deDE', 'Willkommen im Tal.', '', 28153),
(155269, 'deDE', 'Grüße!', '', 28153),
(155268, 'deDE', 'Brennadam ist mein Zuhause und das werde ich beschützen.', '', 28153),
(155267, 'deDE', '', 'Ich stehe zu meinem Wort. Ihr und die Horde seid in meinem Hafen willkommen.', 28153),
(155266, 'deDE', 'Ja, Käpt\'n-Scheffin. Wir helf\'n bei Eurer Sache. Und hoff\'n, dass auch Ihr unsre unterstützt.', '', 28153),
(155265, 'deDE', '', 'Freiheit... Es scheint, als würdet Ihr zu Eurem Wort stehen.', 28153),
(155264, 'deDE', 'Warum seid Ihr... hierhergekommen...?', '', 28153),
(155263, 'deDE', 'Ihr zerstört nur einen Dorn... doch die Ranke bleibt...', '', 28153),
(155262, 'deDE', 'Grah!', '', 28153),
(155261, 'deDE', 'Nein... die Edelsteine...', '', 28153),
(155260, 'deDE', 'Ihr könnt uns nicht... alle töten...', '', 28153),
(155259, 'deDE', 'Ich welke...', '', 28153),
(155258, 'deDE', 'Abgebrochen...', '', 28153),
(155257, 'deDE', 'Dornen... zerbrochen...', '', 28153),
(155256, 'deDE', 'Die leuchtenden Edelsteine hier gehören uns, Eindringling!', '', 28153),
(155255, 'deDE', 'Die Steine machen unsere Dornen stark!', '', 28153),
(155254, 'deDE', 'Wir beanspruchen dieses Land und seine Macht!', '', 28153),
(155253, 'deDE', 'Euer Fleisch hat unseren Dornenspeeren nichts entgegenzusetzen!', '', 28153),
(155252, 'deDE', 'Ich werde Euer Fleisch an meiner Hütte aufhängen!', '', 28153),
(155251, 'deDE', 'Es war die richtige Entscheidung.', '', 28153),
(155250, 'deDE', 'Unsere Ranken werden diese Insel beanspruchen... und Euer Fleisch!', '', 28153),
(155249, 'deDE', 'Dornenbrecher, Euresgleichen hat hier nichts zu suchen.', '', 28153),
(155248, 'deDE', 'Meine Diener, verteidigt mich!', '', 28153),
(155247, 'deDE', 'Lasst sie ihre eigene Medizin kosten!', '', 28153),
(155246, 'deDE', 'Ihr könnt die wilden Ranken nicht aufhalten!', '', 28153),
(155245, 'deDE', 'Euer Blut wird die Dornen nähren.', '', 28153),
(155244, 'deDE', 'Feuer frei!', '', 28153),
(155243, 'deDE', 'Lasst es krachen!', '', 28153),
(155242, 'deDE', 'Ihr werdet welken, Dornenfeind!', '', 28153),
(155241, 'deDE', 'Dieser Ort gehört uns!', '', 28153),
(155240, 'deDE', 'In einem Käfig hätten wir nicht viel erreicht.', '', 28153),
(155239, 'deDE', 'Durchstecht ihr Fleisch!', '', 28153),
(155238, 'deDE', 'Spießt die Eindringlinge auf!', '', 28153),
(155237, 'deDE', '', 'Die See wird rauer.', 28153),
(155236, 'deDE', 'Eindringlinge!', '', 28153),
(155235, 'deDE', 'Sterbt, Dornenbrecher!', '', 28153),
(155234, 'deDE', '', 'Die Flut leite Euch.', 28153),
(155233, 'deDE', 'Die Relikte sind geschützt. Gral ist noch nicht verloren.', '', 28153),
(155232, 'deDE', 'Blut und Donner.', '', 28153),
(155231, 'deDE', 'Oh und ich hab dieses interessante Schmuckstück entdeckt.', '', 28153),
(155230, 'deDE', 'Wir hätten das Lager wohl nicht so übereilt verlassen sollen.', '', 28153),
(155229, 'deDE', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s markiert Euch mit einer brennenden Lunte. Haltet Euch von den Munitionsfässern fern!', 28153),
(155228, 'deDE', 'Genießt den Tag, Razgaji. Nächstes Mal, wenn wir uns seh\'n... wird\'s Euer letzter sein!', '', 28153),
(155227, 'deDE', 'Die Reise hat uns hergeführt. Und wir machten Entdeckungen, die uns des Rätsels Lösung näher brachten.', '', 28153),
(155226, 'deDE', '', 'Passt auf Euch auf da draußen.', 28153),
(155225, 'deDE', '', 'Wie kann die Bürgermeisterin behilflich sein?', 28153),
(155224, 'deDE', '', 'Ich muss die Bürger von Sturmsang schützen.', 28153),
(155223, 'deDE', '', 'Seid Ihr hier, um mit anzupacken?', 28153),
(155222, 'deDE', 'Für die Horde!', '', 28153),
(155221, 'deDE', 'Schaut nur, wie der im Netz zappelt! Wird Spaß machen, den auszuweiden!', 'Schaut nur, wie der im Netz zappelt! Wird Spaß machen, den auszuweiden!', 28153),
(155220, 'deDE', 'Ha! Noch einen erwischt!', 'Ha! Noch einen erwischt!', 28153),
(155219, 'deDE', 'Ja, Mann. Hab \'nen Haufen Kram zu bericht\'n!', '', 28153),
(155218, 'deDE', '', 'Also, Ty\'jin. Wenn ich mit Euch arbeiten soll, erzählt mir erst mehr von der Horde.', 28153),
(155217, 'deDE', 'All das Azerit... wird... uns... gehören...', '', 28153),
(155216, 'deDE', 'Dieses Azerit ist das Eigentum von Aschenwind & Co.!', '', 28153),
(155215, 'deDE', '', 'Die feindlichen Streitkräfte sind im Anmarsch! Treibt sie zurück!', 28153),
(155214, 'deDE', '', 'Ihr habt unseren Streitkräften eine Atempause verschafft.', 28153),
(155213, 'deDE', '', 'Die Hexen wurden in die Flucht geschlagen! Sehr gut!', 28153),
(155212, 'deDE', '', 'Der Zirkel greift dieses Gebiet an. Kümmert Euch um sie!', 28153),
(155211, 'deDE', '', 'Dank Euch können wir wieder aufatmen. Danke.', 28153),
(155210, 'deDE', '', 'Die Bürger von Drustvar werden vom Zirkel angegriffen! Schlagt die Hexen zurück!', 28153),
(155209, 'deDE', '', 'Ich danke Euch im Namen meines Volkes für Eure Hilfe.', 28153),
(155208, 'deDE', '', 'Mein Volk braucht Eure Unterstützung. Bitte steht uns bei!', 28153),
(155207, 'deDE', 'Nein! Soll er doch seinen Will\'n hab\'n. Wir geh\'n erst ma\'... aber wenn wir wiederkomm\'n, sin\' wir nich\' mehr so großzügig!', '', 28153),
(155206, 'deDE', '$gDer:Die:r; $r ist kein Problem für mich, Scheff! Ich kann mich kümmern!', '$gDer:Die:r; $r ist kein Problem für mich, Scheff! Ich kann mich kümmern!', 28153),
(155205, 'deDE', 'Ich geh nich\' mit Euch zurück. Glaubt Ihr wirklich, Eure gemeinen Schläger werd\'n mit meiner Verstärkung hier fertig? Fangt keinen Streit an, den Ihr nich\' gewinn\' könnt.', '', 28153),
(155204, 'deDE', 'Raus? Ich entscheid hier, wer wo un\' wann rausgeht! Ihr wisst, was mit Deserteur\'n passiert!', '', 28153),
(155203, 'deDE', 'Ich bin raus, Mojambo. Ich hab die Nase voll davon, fürs Überleben zu töt\'n un\' zu stehl\'n. Ich geh jetz\' meinen eig\'nen Weg...', '', 28153),
(155202, 'deDE', 'Hehehe...', 'Hehehe...', 28153),
(155201, 'deDE', 'Ihr habt Euch doch nich\' vor Euren alten Freund\'n versteckt, oder?', '', 28153),
(155200, 'deDE', 'Na, wenn das nich\' Razgaji is\'! Hab Euch doch gesagt, wir find\'n ihn hier...', '', 28153),
(155199, 'deDE', 'Seid auf der Hut. Man kann Mojambo nich\' trau\'n...', '', 28153),
(155198, 'deDE', 'Ich bin bereit. Los geht\'s.', 'Ich bin bereit. Los geht\'s.', 28153),
(155197, 'deDE', 'Möge die See diese Barren segnen und sie niemals zurückfordern.', 'Möge die See diese Barren segnen und sie niemals zurückfordern.', 28153),
(155196, 'deDE', '', 'Durch die Macht unseres Meisters werden wir uns wieder erheben!', 28153),
(155195, 'deDE', 'Könntet Ihr diese Sturmsilberbarren segnen?', 'Könntet Ihr diese Sturmsilberbarren segnen?', 28153),
(155194, 'deDE', 'Allzeit ruhige See, $R.', 'Allzeit ruhige See, $R.', 28153),
(155193, 'deDE', '', 'Alle werden sich Königin Azshara unterwerfen!', 28153),
(155192, 'deDE', '', 'Eure Augen werden brennen, während sein Wille Euch verzehrt!', 28153),
(155191, 'deDE', 'Zieht die Harpune heraus.', 'Zieht die Harpune heraus.', 28153),
(155190, 'deDE', '<Die Kreatur sieht Euch kurz mit schwachem Blick an, bevor sie wieder zu der in ihrer Flanke steckenden Harpune blickt.>', '<Die Kreatur sieht Euch kurz mit schwachem Blick an, bevor sie wieder zu der in ihrer Flanke steckenden Harpune blickt.>', 28153),
(155189, 'deDE', 'Wo wollt Ihr hin?', '', 28153),
(155188, 'deDE', 'Muuga maguuduu! Draufhauen!', '', 28153),
(155187, 'deDE', 'Ugafa! Ich Euch wehtun!', '', 28153),
(155186, 'deDE', 'Oooh, Ihr böse! Geht weg!', '', 28153),
(155185, 'deDE', 'Wer zum Maguda ist das?', '', 28153),
(155184, 'deDE', 'Gwaahr! Diese Steine... meine Steine!', '', 28153),
(155183, 'deDE', 'Waaah! Ihr nicht nehmen den Schatz!', '', 28153),
(155182, 'deDE', 'Gwaaah? Wer dieser Typ?', '', 28153),
(155181, 'deDE', 'Bwagauugh! Ich verfüttere Euch an die Fischis!', '', 28153),
(155180, 'deDE', 'Aguu...?', '', 28153),
(155179, 'deDE', 'Harg!', '', 28153),
(155178, 'deDE', 'Gafu... mogo...', '', 28153),
(155177, 'deDE', 'Uug...', '', 28153),
(155176, 'deDE', 'Muug!?', '', 28153),
(155175, 'deDE', 'Matuufa...', '', 28153),
(155174, 'deDE', 'Gark!', '', 28153),
(155173, 'deDE', 'A-buu-buu-buu-buu!', '', 28153),
(155172, 'deDE', 'Urga maguu?!', '', 28153),
(155171, 'deDE', 'Griep!', '', 28153),
(155170, 'deDE', 'Buuga buuga!', '', 28153),
(155169, 'deDE', 'Ahhh!', '', 28153),
(155168, 'deDE', 'Oka magodo!', '', 28153),
(155167, 'deDE', 'Bokum?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'deDE', 'Buuga mabugu!', '', 28153),
(155165, 'deDE', 'Ah gah mah gahma!', '', 28153),
(155164, 'deDE', 'Sein Herz wird immer schwächer... Ich kann nichts mehr für ihn tun, außer seinen Qualen ein Ende zu setzen.', '', 28153),
(155163, 'deDE', 'Aschenwind hat eine Belohnung auf Euren Kopf ausgesetzt!', 'Aschenwind hat eine Belohnung auf Euren Kopf ausgesetzt!', 28153),
(155162, 'deDE', 'Von Eurem Leichnam werde ich mir eine Trophäe holen!', 'Von Eurem Leichnam werde ich mir eine Trophäe holen!', 28153),
(155161, 'deDE', 'Ihr könnt Aschenwind nicht besiegen!', 'Ihr könnt Aschenwind nicht besiegen!', 28153),
(155160, 'deDE', 'Die Stadt gehört uns!', 'Die Stadt gehört uns!', 28153),
(155159, 'deDE', 'Boralus wird brennen!', 'Boralus wird brennen!', 28153),
(155158, 'deDE', 'Wir treffen uns an einem etwas sichereren Ort wieder!', 'Wir treffen uns an einem etwas sichereren Ort wieder!', 28153),
(155157, 'deDE', 'Ich brauche eine Überfahrt nach Drustvar.', 'Ich brauche eine Überfahrt nach Drustvar.', 28153),
(155156, 'deDE', 'Warum... ihr hierhergekommen...?', '', 28153),
(155155, 'deDE', 'Glitzersteine... meine...', '', 28153),
(155154, 'deDE', 'Meine Kerze!', '', 28153),
(155153, 'deDE', 'Au au au!', '', 28153),
(155152, 'deDE', 'Grah!', '', 28153),
(155151, 'deDE', 'Kerze... ausgehen...', '', 28153),
(155150, 'deDE', 'Aaaaaaaaaaaaaaaaaaah!', '', 28153),
(155149, 'deDE', 'Nein!', '', 28153),
(155148, 'deDE', 'Dich verbrennen wie riesige Kerze!', '', 28153),
(155147, 'deDE', 'Deine Kerze jetzt meine!', '', 28153),
(155146, 'deDE', 'Zerschmettern! Nehmen dein Zeug!', '', 28153),
(155145, 'deDE', 'Ich mach Loch in deinen Schädel!', '', 28153),
(155144, 'deDE', 'Nicht wegnehmen meine Glitzersteine!', '', 28153),
(155143, 'deDE', 'Meine Insel! Ich König!', '', 28153),
(155142, 'deDE', 'Glitzersteine mir gehören! MIR!', '', 28153),
(155141, 'deDE', 'Wir das hier gefunden! Nicht ihr!', '', 28153),
(155140, 'deDE', 'Mein Platz!', '', 28153),
(155139, 'deDE', 'Beißt sie! Nehmt ihre Kerzen!', '', 28153),
(155138, 'deDE', 'Grah! Eindringlinge!', '', 28153),
(155135, 'deDE', 'Nicht nehmen Kerze!', '', 28153),
(155134, 'deDE', 'Bishibosh!', '', 28153),
(155133, 'deDE', 'Glitzersteine gehören uns!', '', 28153),
(155132, 'deDE', 'Glitzersteine machen Kerze hell!', '', 28153),
(155131, 'deDE', 'Viel Glück, Festländer. Wenn Ihr Götter habt, solltet Ihr besser hoffen, dass sie Euch hier beistehen.', 'Viel Glück, Festländer. Wenn Ihr Götter habt, solltet Ihr besser hoffen, dass sie Euch hier beistehen.', 28153),
(155130, 'deDE', 'Endstation. Weiter bring ich Euch nicht.', 'Endstation. Weiter bring ich Euch nicht.', 28153),
(155129, 'deDE', 'Beim letzten Besuch hat mir hier fast ein Wolf das Bein abgerissen...', 'Beim letzten Besuch hat mir hier fast ein Wolf das Bein abgerissen...', 28153),
(155128, 'deDE', 'Wir machen ein bisschen weiter unten fest. Der Schlächterhafen ist kein freundlicher Ort in diesen Tagen.', 'Wir machen ein bisschen weiter unten fest. Der Schlächterhafen ist kein freundlicher Ort in diesen Tagen.', 28153),
(155127, 'deDE', 'Was immer Ihr da wollt... bringt das mal lieber schnell hinter Euch.', 'Was immer Ihr da wollt... bringt das mal lieber schnell hinter Euch.', 28153),
(155126, 'deDE', 'Ich bin nicht so abergläubisch wie die meisten Kul Tiraner, aber Drustvar... da wird mir in letzter Zeit auch mulmig.', 'Ich bin nicht so abergläubisch wie die meisten Kul Tiraner, aber Drustvar... da wird mir in letzter Zeit auch mulmig.', 28153),
(155125, 'deDE', 'Und am nächsten Tag scheinen die Minen verlassen und weit und breit ist kein Fleischer in Sicht.', 'Und am nächsten Tag scheinen die Minen verlassen und weit und breit ist kein Fleischer in Sicht.', 28153),
(155124, 'deDE', 'Am einen Tag rennen mir noch Händler die Fähre ein, um mit den Bauern und Bergleuten drüben zu handeln.', 'Am einen Tag rennen mir noch Händler die Fähre ein, um mit den Bauern und Bergleuten drüben zu handeln.', 28153),
(155123, 'deDE', 'Die meisten Fährleute legen da nicht mehr an. Zu viele finstere Gerüchte machen die Runde.', 'Die meisten Fährleute legen da nicht mehr an. Zu viele finstere Gerüchte machen die Runde.', 28153),
(155122, 'deDE', 'Auf dem Weg nach Drustvar, was? Gut, dass Ihr mich und meinen Kahn habt.', 'Auf dem Weg nach Drustvar, was? Gut, dass Ihr mich und meinen Kahn habt.', 28153),
(155121, 'deDE', 'Ooh! Ahh! Ahhh!', '', 28153),
(155120, 'deDE', 'Umpf...', '', 28153),
(155119, 'deDE', 'Seid... verflotscht...', '', 28153),
(155118, 'deDE', 'Au! Genau in die Spenks!', '', 28153),
(155117, 'deDE', 'Gah!', '', 28153),
(155116, 'deDE', 'Fiese... Nappels...', '', 28153),
(155115, 'deDE', 'Verfiddelter... Knatzel...', '', 28153),
(155114, 'deDE', 'Nein, mein Glitzerzeug!', '', 28153),
(155113, 'deDE', 'Die vielfältige Flora und Fauna von Zandalar muss erforscht und katalogisiert werden.', 'Die vielfältige Flora und Fauna von Zandalar muss erforscht und katalogisiert werden.', 28153),
(155112, 'deDE', 'Wo kommen diese Knatzel her?', '', 28153),
(155111, 'deDE', 'Ich fiddel dich da, wo\'s weh tut!', '', 28153),
(155110, 'deDE', 'Flotscht sie und knatzelt sie!', '', 28153),
(155109, 'deDE', 'Vortreffliche Arbeit! Damit kann ich im Handumdrehen wieder neue mächtige Mittelchen brauen!', '', 28153),
(155108, 'deDE', 'Tut mir leid, ich hab keine Zeit für neue Aufträge. Mein Terminplan ist v... He, Ihr habt Geld? Vergesst, was ich gerade gesagt habe. Wie kann ich Euch helfen?', 'Tut mir leid, ich hab keine Zeit für neue Aufträge. Mein Terminplan ist v... He, Ihr habt Geld? Vergesst, was ich gerade gesagt habe. Wie kann ich Euch helfen?', 28153),
(155107, 'deDE', 'Unsere Streitkräfte brauchen mehr Alchemievorräte! Bitte sammelt in diesem Gebiet die dafür nötigen Reagenzien. Oh, und passt auf die Bären auf.', '', 28153),
(155106, 'deDE', '', 'Falkenforst wird von Truppen der Hexen angegriffen! Beseitigt jede Spur ihrer üblen Magie und stellt in der Stadt wieder Ordnung her!', 28153),
(155105, 'deDE', '', 'Die Hexen sind vertrieben und die Bürger von Falkenforst sind wieder in Sicherheit. Wir alle sind Euch dankbar.', 28153),
(155104, 'deDE', 'Willkommen, alles hier wurde frisch von den Einheimischen gesammelt. Probiert doch heute etwas Neues und Exotisches!', 'Willkommen, alles hier wurde frisch von den Einheimischen gesammelt. Probiert doch heute etwas Neues und Exotisches!', 28153),
(155103, 'deDE', 'Verfiddelt euch, das mein Glitzerzeug!', '', 28153),
(155102, 'deDE', 'Verflotschte Nappel, das meine Insel!', '', 28153),
(155101, 'deDE', 'Ich dich in Boden stampfen, Knatzel!', '', 28153),
(155100, 'deDE', 'Euch zieh ich meinen Zwölferschlüssel drüber!', 'Murkst sie alle ab!', 28153),
(155099, 'deDE', 'Hier gibt\'s gleich \'nen kleinen Arbeitsunfall!', 'Das war\'s mit Sicherheit am Arbeitsplatz!', 28153),
(155098, 'deDE', 'Ich erkenne \'ne Lusche, wenn ich eine sehe!', 'Holt mir \'ne Zange! Dem justier ich die Birne!', 28153),
(155097, 'deDE', 'Wir sterben... durch die Klinge...', '', 28153),
(155096, 'deDE', 'Ein Triumph... aber kein Sieg...', '', 28153),
(155095, 'deDE', 'Auf dass die Sporen... Euch holen...', '', 28153),
(155094, 'deDE', 'Wir überdauern... den Tod...', '', 28153),
(155093, 'deDE', 'Wir verlassen... diesen Körper...', '', 28153),
(155092, 'deDE', 'Zumindest... sterben wir... ehrenhaft...', '', 28153),
(155091, 'deDE', 'Und so... fallen wir...', '', 28153),
(155090, 'deDE', 'Wir wachsen... und kämpfen... erneut...', '', 28153),
(155089, 'deDE', 'Für die Sporen!', '', 28153),
(155088, 'deDE', 'Unser Wille ist eins!', '', 28153),
(155087, 'deDE', 'Hey! Hier gibt\'s Regeln und Ihr brecht eine nach der anderen!', 'Ihr da... Ihr seid gefeuert!', 28153),
(155086, 'deDE', 'Ihr habt gezuckt! Wir gewinnen!', '', 28153),
(155085, 'deDE', 'Spürt unsere bohrenden Klingen!', '', 28153),
(155084, 'deDE', 'Unser Wille schützt uns!', '', 28153),
(155083, 'deDE', 'Diese Schlacht habt Ihr schon verloren!', '', 28153),
(155082, 'deDE', 'Darin braucht Ihr mehr Übung!', '', 28153),
(155081, 'deDE', 'Euch pflücken wir samt Stiel!', '', 28153),
(155080, 'deDE', 'Bitte, rettet Boralus!', 'Bitte, rettet Boralus!', 28153),
(155079, 'deDE', 'Diese Piraten reißen Boralus nieder!', 'Diese Piraten reißen Boralus nieder!', 28153),
(155078, 'deDE', 'Habt Dank!', 'Habt Dank!', 28153),
(155077, 'deDE', 'Zermalmt die Nappel zu Spenks!', '', 28153),
(155076, 'deDE', 'Ich hier König, Nappel!', '', 28153),
(155075, 'deDE', 'Tötet sie! Nehmt ihre Spenks!', '', 28153),
(155074, 'deDE', 'Nappel von weit weg!', '', 28153),
(155073, 'deDE', 'Nappel töten!', '', 28153),
(155072, 'deDE', 'Glitzerzeug macht uns stark!', '', 28153),
(155071, 'deDE', 'Unsere Insel! Nicht eure!', '', 28153),
(155070, 'deDE', 'Verfiddel dich!', '', 28153),
(155069, 'deDE', 'Nicht nehmen unser Glitzerzeug!', '', 28153),
(155068, 'deDE', 'Keine Nappel erlaubt!', '', 28153),
(155067, 'deDE', 'Vor vielen Jahren hab ich Zalazane und Vol\'jin dazu ausgebildet, Meister ihrer Fähigkeiten zu werd\'n. Ich hätt nie gedacht, dass ihr Schicksal mal den Lauf der Welt bestimmen würde.', '', 28153),
(155066, 'deDE', 'Hab nur getan... was man mir gesagt hat!', 'Hab nur getan... was man mir gesagt hat!', 28153),
(155065, 'deDE', 'Hätte für Euch... arbeiten sollen!', 'Hätte für Euch... arbeiten sollen!', 28153),
(155064, 'deDE', '', 'Hmmja? Kann ich Euch irgendwie helfen?', 28153),
(155063, 'deDE', 'Die Gelage... werd ich vermissen...', 'Die Gelage... werd ich vermissen...', 28153),
(155062, 'deDE', 'Ich wusste, das bereue ich noch!', 'Ich wusste, das bereue ich noch!', 28153),
(155061, 'deDE', 'Geister... ich komm\' zu Euch...', 'Geister... ich komm\' zu Euch...', 28153),
(155060, 'deDE', 'Ich hau mich kurz... aufs Ohr...', 'Ich hau mich kurz... aufs Ohr...', 28153),
(155059, 'deDE', 'Das... petz ich...', '', 28153),
(155058, 'deDE', 'Nächstes Mal will ich gewinnen...', '', 28153),
(155057, 'deDE', 'Haha! Ich gewonnen... Oh, wartet...', '', 28153),
(155056, 'deDE', 'Nein... ich nicht verlieren...', '', 28153),
(155055, 'deDE', 'Ihr Problem... Ich schaffen aus Welt.', '', 28153),
(155054, 'deDE', 'Ich Pryo...Pyrofachoger! Ich schlau. Machen Feuer!', '', 28153),
(155053, 'deDE', 'Ihr planschen in Ölpfütze... Ich geben Streichholz!', 'Ihr planschen in Ölpfütze... Ich geben Streichholz!', 28153),
(155052, 'deDE', 'Feuer blöd... Ihr aufhören mit Feuern!', 'Feuer blöd... Ihr aufhören mit Feuern!', 28153),
(155051, 'deDE', 'Euch brat\' ich gut durch.', 'Euch brat\' ich gut durch.', 28153),
(155050, 'deDE', 'Überlegt Euch gut, ob Ihr hier \'n Fass aufmach\'n wollt.', 'Überlegt Euch gut, ob Ihr hier \'n Fass aufmach\'n wollt.', 28153),
(155049, 'deDE', 'Wer mir dumm kommt, verbrennt sich die Finger.', 'Wer mir dumm kommt, verbrennt sich die Finger.', 28153),
(155048, 'deDE', 'Ich riech\' Euch schon brutzeln.', 'Ich riech\' Euch schon brutzeln.', 28153),
(155047, 'deDE', 'Jetzt wird\'s heiß und hässlich!', 'Jetzt wird\'s heiß und hässlich!', 28153),
(155046, 'deDE', 'Jetzt ist sie zurück in dem Abgrund, aus dem sie stammt.', '', 28153),
(155045, 'deDE', 'Die Bestie ist zurück! Schnell, jagt sie fort, bevor sie noch mehr Schaden am Wall anrichtet!', '', 28153),
(155044, 'deDE', 'Was? Vol\'jin... Ihr hättet niemals so stark werd\'n könn\', ohne dass...', '', 28153),
(155043, 'deDE', 'Denkt Ihr, mein\' Körper zu zerstör\'n... hält mich davon ab... Euch in Stücke zu reiß\'n?', '', 28153),
(155042, 'deDE', 'Ihr denkt, Ihr könnt gewinn\'n? Ihr zögert Euer Schicksal nur raus.', '', 28153),
(155041, 'deDE', 'Ich hab viel gelernt, als ich mitanseh\'n musste, wie Bwonsamdi meine Seele foltert. Ich zeig\' Euch ma\' seine Art von Voodoo!', '', 28153),
(155040, 'deDE', 'Ihr könnt Euch nich\' ewig vor mir versteck\'n. Ich werd\' mich an Vol\'jin und sein\'n Dunkelspeer\'n räch\'n!', '', 28153),
(155039, 'deDE', 'Diener! Tötet ihr\'n Champion und bringt mir die Asche von Vol\'jin. LOS!', '', 28153),
(155038, 'deDE', 'Wo is\' er? Wo versteckt Ihr Vol\'jin? Un\' wie versteckt Ihr ihn?', '', 28153),
(155037, 'deDE', 'Wo habt Ihr sie versteckt, Dunkelspeere? Wo is\' mein alter Freund?', '', 28153),
(155036, 'deDE', 'Zerschmettert die Dunkelspeere un\' findet die Asche.', '', 28153),
(155035, 'deDE', 'Sucht, Diener. Findet die Asche von Vol\'jin un\' bringt sie mir.', '', 28153),
(155034, 'deDE', 'Diese dreckigen Käfer fressen einfach alles. Widerlich.', '', 28153),
(155033, 'deDE', 'Die Ranishu machen sich in Schwärmen über uns her! Rottet sie aus, bevor sie zu einem größeren Problem für uns alle werden.', '', 28153),
(155032, 'deDE', 'Das werden wir. Allzeit günstige Winde.', 'Das werden wir. Allzeit günstige Winde.', 28153),
(155031, 'deDE', 'Ihr konntet mir den richtigen Weg weisen. Werdet Ihr klarkommen?', 'Ihr konntet mir den richtigen Weg weisen. Werdet Ihr klarkommen?', 28153),
(155030, 'deDE', 'Tut mir leid, dass wir nicht mehr tun konnten.', 'Tut mir leid, dass mein Bruder und ich nicht mehr tun konnten.', 28153),
(155029, 'deDE', '', 'Gut gemacht. Schön, dass Ihr an unsrer Seite kämpft.', 28153),
(155028, 'deDE', '', 'In der Nähe von der Arena gibt\'s \'n Nest von den Sandwirblerspinn\'. Ihr müsst das für mich ausm Weg räum\'.', 28153),
(155027, 'deDE', 'Diese Waffen stammen wohl von Gnomen. Aber so oder so sollten sie sich in der Schlacht bewähren.', '', 28153),
(155026, 'deDE', 'Unsere Soldaten haben ein paar... interessante Waffen gefunden, die uns von Nutzen sein könnten – wenn wir herausfinden, wie man sie einsetzt. Probiert sie an den hiesigen Tieren aus!', '', 28153),
(155025, 'deDE', '', 'Es wird Woch\'n dauern, bis Aschenwind & Co. wieder so viele Güter beisamm\' hat. Gute Arbeit.', 28153),
(155024, 'deDE', '', 'Aschenwind & Co. sorg\'n für Ärger in der Nähe. Ihr solltet ihn\' ma\' \'n Strich durch die Rechnung mach\'n!', 28153),
(155023, 'deDE', 'Hundert Schwachköpfe werden auf einer Insel voller Waffen abgesetzt! Verkauft Tickets, um alles von oben aus einem Zeppelin zu beobachten!', 'Hundert Schwachköpfe werden auf einer Insel voller Waffen abgesetzt! Verkauft Tickets, um alles von oben aus einem Zeppelin zu beobachten!', 28153),
(155022, 'deDE', 'Wir belegen Roboter mit einer Steuer. Dann stellen wir Robotersteuereintreiber her! Unendliches Geld!', 'Wir belegen Roboter mit einer Steuer. Dann stellen wir Robotersteuereintreiber her! Unendliches Geld!', 28153),
(155021, 'deDE', 'Einen Glühapfel! Statt immer nur Birnen.', 'Einen Glühapfel! Statt immer nur Birnen.', 28153),
(155020, 'deDE', 'Einen kleinen schicken Hut, den man für förmliche Anlässe auf einen lässigen Hut setzen kann!', 'Einen kleinen schicken Hut, den man für förmliche Anlässe auf einen lässigen Hut setzen kann!', 28153),
(155019, 'deDE', 'Bootems: Totems für die Seefahrt!', 'Bootems: Totems für die Seefahrt!', 28153),
(155018, 'deDE', 'Schießschuhe! Wartet, nein... das hatten wir schon. SchießSOCKEN!', 'Schießschuhe! Wartet, nein... das hatten wir schon. SchießSOCKEN!', 28153),
(155017, 'deDE', 'Wiederverwertbare Raketen!', 'Wiederverwertbare Raketen!', 28153),
(155016, 'deDE', 'Ein Bombenschlittenteam mit nur Goblins!', 'Ein Bombenschlittenteam mit nur Goblins!', 28153),
(155015, 'deDE', 'Waffenfähiger Käse.', 'Waffenfähiger Käse.', 28153),
(155014, 'deDE', 'Kettensägenkriegsgleven für beide Hände! Verkauft sie an die Illidari!', 'Kettensägenkriegsgleven für beide Hände! Verkauft sie an die Illidari!', 28153),
(155013, 'deDE', 'Der Peridotgrüne Tagtraum, wenn es nur ein kurzes Nickerchen sein soll!', 'Der Peridotgrüne Tagtraum, wenn es nur ein kurzes Nickerchen sein soll!', 28153),
(155012, 'deDE', 'Eine taktische Grillzange!', 'Eine taktische Grillzange!', 28153),
(155011, 'deDE', 'Eine Liebesgeschichte... über einen Menschen und einen, äh, einen Jinyu!', 'Eine Liebesgeschichte... über einen Menschen und einen, äh, einen Jinyu!', 28153),
(155010, 'deDE', 'Gut gemacht. Schön, dass Ihr an unserer Seite kämpft.', '', 28153),
(155009, 'deDE', 'Eine Säule, die nicht das Dach abstützt, sondern den Boden unten hält!', 'Eine Säule, die nicht das Dach abstützt, sondern den Boden unten hält!', 28153),
(155008, 'deDE', 'Ein Nest der Sandwirblerspinnen versperrt den Zugang zur Schlucht. Ich möchte, dass Ihr den Weg für unsere Truppen frei macht.', '', 28153),
(155007, 'deDE', 'Eine Wahrsagekugel aus Azerit? Azerichtig oder Azefalsch?', 'Eine Wahrsagekugel aus Azerit? Azerichtig oder Azefalsch?', 28153),
(155006, 'deDE', 'Teldrassilholzkohlebriketts! Voller, rauchiger Grillgeschmack!', 'Teldrassilholzkohlebriketts! Voller, rauchiger Grillgeschmack!', 28153),
(155005, 'deDE', 'Wagen, die auf Wasser statt an Land fahren!', 'Wagen, die auf Wasser statt an Land fahren!', 28153),
(155004, 'deDE', 'Barden!', 'Barden!', 28153),
(155003, 'deDE', 'Eine Pfeife, die Flugmeister zu Euch ruft!', 'Eine Pfeife, die Flugmeister zu Euch ruft!', 28153),
(155002, 'deDE', 'Gute Arbeit, Soldat! Das ist eine Monstrosität weniger, um die wir uns in dieser Todesfalle namens Vol\'dun sorgen müssen!', '', 28153),
(155001, 'deDE', 'Eine Art Arkankristall, der Euch rundum verbessert! Ein wenig instabil vielleicht, aber das ist in Ordnung!', 'Eine Art Arkankristall, der Euch rundum verbessert! Ein wenig instabil vielleicht, aber das ist in Ordnung!', 28153),
(155000, 'deDE', 'Ein riesiger Ranishu terrorisiert die Schlucht, aber er ist zu wild, um ihn direkt anzugreifen. Ihr werdet einen anderen Weg finden müssen, ihn aufzuhalten!', '', 28153),
(154999, 'deDE', 'Toilettenpapiergewehre! Denkt an all die Zeit, die Ihr sparen könntet!', 'Toilettenpapiergewehre! Denkt an all die Zeit, die Ihr sparen könntet!', 28153),
(154998, 'deDE', 'Etagenboote! Wir werden so viel Platz auf den Meeren sparen, den wir für andere Dinge nutzen können! Ich krieg einen Platz oben!', 'Etagenboote! Wir werden so viel Platz auf den Meeren sparen, den wir für andere Dinge nutzen können! Ich krieg einen Platz oben!', 28153),
(154997, 'deDE', 'Wiederverwendbares Kaugummi! Teilt es mit Euren Freunden, Euren Haustieren oder sogar Fremden!', 'Wiederverwendbares Kaugummi! Teilt es mit Euren Freunden, Euren Haustieren oder sogar Fremden!', 28153),
(154996, 'deDE', 'Nun, das war ziemliche Drecksarbeit. Aber irgendjemand musste sie machen! Und besser Ihr als ich, Soldat!', '', 28153),
(154995, 'deDE', 'Wenn wir überleben wollen, müssen wir herausfinden, wie man in dieser Wüste Ackerbau betreibt. Dazu werden wir Dünger brauchen... also macht Euch auf die Suche.', '', 28153),
(154994, 'deDE', 'Ich gebe zu, ich war skeptisch, aber das wird sich gegen die Treulosen als extrem nützlich erweisen.', '', 28153),
(154993, 'deDE', 'Tacha hat in einer der Ruinen ein Zandalaritotem ausgegraben. Probiert es aus und seht, was es kann!', '', 28153),
(154992, 'deDE', 'Na, das sah doch spaßig aus! Ich werde es mir für ein paar Orcs aufsparen.', '', 28153),
(154991, 'deDE', 'Es wird Wochen dauern, bis Aschenwind & Co. wieder so viele Güter beisammen hat. Gute Arbeit.', '', 28153),
(154990, 'deDE', 'Unsere Späher haben in einer der Ruinen dieses alte Zandalaritotem ausgegraben. Sehen wir mal, was es kann!', '', 28153),
(154989, 'deDE', 'Aschenwind & Co. betreibt hier in der Nähe illegalen Bergbau. Schiebt da einen Riegel vor!', '', 28153),
(154988, 'deDE', 'Der Sand breitet sich aus, aber das Leben bleibt bestehen. Danke.', '', 28153),
(154987, 'deDE', 'Die Oasen von Vol\'dun sind eine wichtige Ressource. Wir müssen sie sorgsam pflegen.', '', 28153),
(154986, 'deDE', 'Nicht jeder Sieg entspringt einer glorreichen Schlacht. Vorräte werden uns hier draußen am Leben halten.', '', 28153),
(154985, 'deDE', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg', '', 28153),
(154984, 'deDE', 'Diese Oase wird einen wichtigen taktischen Vorteil darstellen, wenn wir weiter in den Kontinent vordringen.', '', 28153),
(154983, 'deDE', 'Mein Sturz ist nur ein Schlag im pulsierenden Herzen des endlosen Abgrunds.', '', 28153),
(154982, 'deDE', 'Ich muss zugeben, das lief viel besser, als ich erwartet hatte.', '', 28153),
(154981, 'deDE', 'Unsere... ungewöhnlichen Verbündeten im Hafen von Zem\'lan haben sich einen neuen Plan ausgedacht. Helft ihnen, falls Ihr ihnen vertraut.', '', 28153),
(154980, 'deDE', 'Ha! Die werden sich so schnell nicht wieder mit der Allianz anlegen!', '', 28153),
(154979, 'deDE', 'Einige unserer Truppen haben ein Boot gestohlen und mit Waffen beladen. Tragt den Kampf zu diesen untoten Monstern!', '', 28153),
(154978, 'deDE', 'Gut gemacht! Diese verfluchten Teufel werden es sich gründlich überlegen, die Allianz erneut anzugreifen.', '', 28153),
(154977, 'deDE', 'Dreckige untote Piraten haben einige unserer Soldaten gefangen genommen. Befreit sie. Lasst niemanden zurück!', '', 28153),
(154976, 'deDE', '', 'Danke. Selbst Verbannte ham ein bess\'res Schicksal verdient als das.', 28153),
(154975, 'deDE', '', 'Die Pirat\'n von Zem\'lan halt\'n verbannte Zandalari gefang\'n. Befreit sie!', 28153),
(154974, 'deDE', 'Die Treulosen sind abgelenkt. Lasst den Tod vom Himmel auf sie herabregnen!', '', 28153),
(154973, 'deDE', 'Sie werden sich zweifelsohne wieder erheben. Doch jetzt können wir erst einmal den Frieden genießen.', '', 28153),
(154972, 'deDE', 'Die Treulosen sind zahllos. Wir müssen sie hier in Schach halten.', '', 28153),
(154971, 'deDE', 'Ruhm für Sethraliss! Mögen sich alle Sethrak eines Tages ihrer erinnern...', '', 28153),
(154970, 'deDE', 'Nehmt einen Teil meiner Macht und läutert dieses Land von den Treulosen.', '', 28153),
(154969, 'deDE', '', 'Meine Stärke... was habt Ihr getan?', 28153),
(154968, 'deDE', '', 'Diese Macht... Kann mich nich\'... beweg\'n...', 28153),
(154967, 'deDE', 'Meine Lebenskraft... schwindet...', '', 28153),
(154966, 'deDE', 'Ich kann mich nicht bewegen... Hilfe...', '', 28153),
(154965, 'deDE', 'Unnggrrh...', '', 28153),
(154964, 'deDE', 'Habt Ihr wirklich geglaubt, Ihr könnt Euch geg\'n \'nen Gott erheb\'n? STERBT!', '', 28153),
(154963, 'deDE', 'Mehr Blut! Der Durst muss gestillt werd\'n.', '', 28153),
(154962, 'deDE', 'Euer Blut verleiht mir Kraft!', '', 28153),
(154961, 'deDE', 'Nie wieder Drecksarbeit! Ich mache eine Ausbildung, ich werde jemand sein!', 'Nie wieder Drecksarbeit! Ich mache eine Ausbildung, ich werde jemand sein!', 28153),
(154960, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk bereitet sich darauf vor, |cFFFF0000|Hspell:258622|h[Resonanter Impuls]|h|r zu wirken!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk bereitet sich darauf vor, |cFFFF0000|Hspell:258622|h[Resonanter Impuls]|h|r zu wirken!', 28153),
(154959, 'deDE', 'Alles, was Ihr Euch von dem Greifen holt, ist \'ne abgebissene Hand.', 'Alles, was Ihr Euch von dem Greifen holt, ist \'ne abgebissene Hand.', 28153),
(154956, 'deDE', 'Schatten werden länger. Auserwählte sammeln sich. Unsere Zeit kommt.', '', 28153),
(154955, 'deDE', 'Ich werde Eurem Fleisch einen Sinn geben.', '', 28153),
(154954, 'deDE', '', 'Meine Macht... mein Fluch... Das kann nicht sein...', 28153),
(154953, 'deDE', 'Falls... Ihr zurückkehrt.', '', 28153),
(154952, 'deDE', 'Wenn ich zurückkehre, sprechen wir über Ehre... und wie sie wiederhergestellt wird.', '', 28153),
(154951, 'deDE', 'Bringt ihn ins Verlies.', '', 28153),
(154950, 'deDE', 'Eure Art ist nichts als Nahrung für mein Wachstum.', '', 28153),
(154949, 'deDE', 'In diesem Moment sehr wohl.', '', 28153),
(154948, 'deDE', 'Das hat nicht der König der Allianz zu bestimmen!', '', 28153),
(154947, 'deDE', 'Seid vernünftig. Das hier ist nicht ehrenhaft.', '', 28153),
(154946, 'deDE', 'Mein Vater hat einmal gesagt, Varok Saurfang verkörpert die Ehre der Horde...', '', 28153),
(154945, 'deDE', 'Nein! Ich verlange einen ehrenhaften Tod!', '', 28153),
(154944, 'deDE', 'Allianz... halt!', '', 28153),
(154940, 'deDE', '', 'Wie beharrlich! Es zeichnet Euch aus, dass Ihr lang genug überleben konntet, um meinen ganzen Stolz kennenzulernen.', 28153),
(154939, 'deDE', 'Alle Einheiten, feuert auf dieses Monstrum! Heute durchbricht kein Naga diesen Wall!', '', 28153),
(154937, 'deDE', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Mythisch\' ein.>', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Mythisch\' ein.>', 28153),
(154936, 'deDE', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Heroisch\' ein.>', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Heroisch\' ein.>', 28153),
(154935, 'deDE', '<Reiht Euch in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Mythisch\' ein.>', '<Reiht Euch in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Mythisch\' ein.>', 28153),
(154934, 'deDE', '<Reiht Euch in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Heroisch\' ein.>', '<Reiht Euch in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Heroisch\' ein.>', 28153),
(154933, 'deDE', 'Geht, Rudelläufer, und erbaut mir bei den Stufen von Dazar\'alor eine Statue. Die anderen sollen von der Stärke des Rudels erfahren, dann ist mein Segen Euer.', '', 28153),
(154932, 'deDE', '', 'Mit Hilfe dieser drei Schriftrollen kann ich Eure Reisen hier erleichtern.', 28153),
(154931, 'deDE', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s wendet sich |cFFFF0000$n|r zu und bereitet einen |cFFFF0000|Hspell:268403|h[Sturmhieb]|h|r vor!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s bereitet einen |cFFFF0000|Hspell:268932|h[Bebensprung]|h|r auf |cFFFF0000$n|r vor!', 28153),
(154930, 'deDE', 'Wenigstens sterbe ich... mit beiden Füßen... auf dem Boden...', '', 28153),
(154929, 'deDE', 'Guter Wurf, Fremdling! Endlich wieder ein spannender Kampf.', '', 28153),
(154928, 'deDE', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s wurde |cFFFF0000|Hspell:267702|h[Bestattet]|h|r! Achtet auf ein Rütteln, um das Grab zu finden!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s wurde |cFFFF0000|Hspell:267702|h[Bestattet]|h|r! Achtet auf ein Rütteln, um das Grab zu finden!', 28153),
(154927, 'deDE', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Ihr seid in einem Grab gefangen! |cFFFF0000|Hspell:267764|h[Rüttelt]|h|r am Ausgang, um Eure Freunde wissen zu lassen, wo Ihr seid!', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Ihr seid in einem Grab gefangen! |cFFFF0000|Hspell:267764|h[Rüttelt]|h|r am Ausgang, um Eure Freunde wissen zu lassen, wo Ihr seid!', 28153),
(154926, 'deDE', 'Wir müssen schnell zurück zum Sanktum der Ergebenen und verhindern, dass General Jakra\'zet Mythrax entfesselt.', '', 28153),
(154925, 'deDE', 'Ihr seid ein Narr! Mythrax lässt sich nicht kontrollieren.', '', 28153),
(154924, 'deDE', 'Er wird Mythrax entfesseln und wir werden ganz Azeroth erobern.', '', 28153),
(154923, 'deDE', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s bereitet sich darauf vor, |cFFFF0000$n|r zu |cFFFF0000|Hspell:267702|h[Bestatten]|h|r!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s bereitet sich darauf vor, |cFFFF0000$n|r zu |cFFFF0000|Hspell:267702|h[Bestatten]|h|r!', 28153),
(154922, 'deDE', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s bereitet einen |cFFFF0000|Hspell:268932|h[Bebensprung]|h|r auf |cFFFF0000$n|r vor!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s bereitet einen |cFFFF0000|Hspell:268932|h[Bebensprung]|h|r auf |cFFFF0000$n|r vor!', 28153),
(154921, 'deDE', 'Uaahhh! Kommt raus und büßt für Eure Verbrechen, Korthek!', '', 28153),
(154920, 'deDE', '', 'Bin hier, um zu beobacht\'n. Wir Zandalari sin\' sehr an den Verlass\'nen interessiert.', 28153),
(154919, 'deDE', '', 'Ich versichere Euch, Pestrufer, die Freude ist ganz meinerseits.', 28153),
(154918, 'deDE', '', 'Ich finde heraus, warum die Straße gesperrt ist. Bringt Ihr die Soldaten dazu, den Weg freizumachen?', 28153),
(154917, 'deDE', 'Packt Eure Siebensachen zusammen, Ihr Trantüten. Es gibt größere Fische als diese hier.', 'Packt Eure Siebensachen zusammen, Ihr Trantüten. Es gibt größere Fische als diese hier.', 28153),
(154916, 'deDE', 'Seht zu, dass Ihr Land gewinnt.', 'Seht zu, dass Ihr Land gewinnt.', 28153),
(154915, 'deDE', 'Ach, lasst mich in Ruhe.', 'Ach, lasst mich in Ruhe.', 28153),
(154914, 'deDE', 'Ich habe es Euch auch leicht gemacht.', 'Ich habe es Euch auch leicht gemacht.', 28153),
(154913, 'deDE', 'Von Euch hatte ich eh genug.', 'Von Euch hatte ich eh genug.', 28153),
(154912, 'deDE', '', 'Ihr konzentriert Euch zu sehr auf die Einzelheiten! Es wird schon gut gehen!', 28153),
(154911, 'deDE', '', 'Alles hat seinen Preis und diese kribbeligen Krabbelviecher werden mir ein Vermögen einbringen! Sobald ich sie nach Kalimdor zurückbringe.', 28153),
(154910, 'deDE', '', 'Die nähr\'n sich von Blut, wie wollt Ihr die füttern?', 28153),
(154909, 'deDE', '', 'Warum sammelt Ihr Ungeziefer in \'ner Kiste?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'deDE', 'Öffnet auf der Stelle diesen Pass.', 'Öffnet auf der Stelle diesen Pass.', 28153),
(154907, 'deDE', 'Ich sehe, dass das Alter Euch nur noch wilder und weiser gemacht hat, Rakjan. Wir werden diese Treulosen büßen lassen für das, was sie Euch angetan haben.', '', 28153),
(154906, 'deDE', 'Der einzige Weg für Euch hier hinein führt durch mich hindurch.', 'Der einzige Weg für Euch hier hinein führt durch mich hindurch.', 28153),
(154905, 'deDE', 'Habt Ihr was an den Ohren, $gKamerad:Fräulein;? Das Tal ist abgeriegelt.', 'Habt Ihr was an den Ohren, $gKamerad:Fräulein;? Das Tal ist abgeriegelt.', 28153),
(154904, 'deDE', 'Gasmaske und Seuchenkanister, bitte. Ich möchte sehen, was dieses Ding kann.', 'Gasmaske und Seuchenkanister, bitte. Ich möchte sehen, was dieses Ding kann.', 28153),
(154903, 'deDE', 'Nur eine Gasmaske für mich, bitte.', 'Nur eine Gasmaske für mich, bitte.', 28153),
(154902, 'deDE', 'Zurück in die Reihe, wenn Ihr keinen Ärger wollt, Bilgeratte.', 'Zurück in die Reihe, wenn Ihr keinen Ärger wollt, Bilgeratte.', 28153),
(154901, 'deDE', 'Keine Papiere, kein Zutritt. So lauten die Vorschriften.', 'Keine Papiere, kein Zutritt. So lauten die Vorschriften.', 28153),
(154899, 'deDE', 'Mit der Kombination aus Ai\'twens kräftigem Rücken, meiner grandiosen Strategie und Eurer Unerschrockenheit gewinnt man Kriege.', '', 28153),
(154898, 'deDE', 'Ich gehe zur Bergspitze und stelle sicher, dass Rakjan mich nach all den Jahren nicht vergessen hat.', '', 28153),
(154897, 'deDE', '', 'Ich werde ruhen, wenn keine weiteren Verwundeten mehr kommen.', 28153),
(154896, 'deDE', '', 'Es geht mir gut. Diese Matrosen benötigen meine Fertigkeiten.', 28153),
(154895, 'deDE', 'Wenn das so weitergeht, werdet Ihr selbst einen Heiler brauchen. Vom Krankenbett aus werdet Ihr niemandem eine große Hilfe sein.', '', 28153),
(154894, 'deDE', 'Ihr seht müde aus, Feorea. Ihr solltet Euch ausruhen.', '', 28153),
(154893, 'deDE', 'Nehmt meinen Stab und ladet ihn an den Unterdrückungsspitzen der Treulosen auf.', '', 28153),
(154892, 'deDE', 'Ai\'twen und ich werden auf Euch am Minenfeld der Venture Company warten.', '', 28153),
(154891, 'deDE', 'Mama! Meerah und $p haben uns gerettet!', 'Mama! Meerah und $p haben uns gerettet!', 28153),
(154890, 'deDE', 'Ich hab doch gesagt, Meerah würde uns nicht vergessen! Sie ist die Beste!', 'Ich hab doch gesagt, Meerah würde uns nicht vergessen! Sie ist die Beste!', 28153),
(154889, 'deDE', '', 'Kiro! Ich bin ja so froh, dass Ihr zurück seid! War es unheimlich? Wo habt Ihr den Krolusk her? Wie heißt er? Darf ich ihm einen Namen geben? Ist er lieb?', 28153),
(154888, 'deDE', 'Später erzähle ich Euch alles. Lasst uns erst einmal unsere Leute in Sicherheit bringen.', '', 28153),
(154887, 'deDE', 'Das hat überraschend viel Spaß gemacht.', '', 28153),
(154886, 'deDE', 'Hüpft auf den Krolusk und lasst uns hier verschwinden, bevor die Treulosen Verstärkung schicken!', '', 28153),
(154885, 'deDE', '', 'Was ist da unten los? Sturmherz, bring uns dorthin!', 28153),
(154884, 'deDE', '', 'Wir beginnen unsere Suche in Brennadam. Hoffentlich machen wir dort zumindest diesen Bruder Pike ausfindig.', 28153),
(154883, 'deDE', '', 'Lord Sturmsang herrscht über das Haus und damit über das Tal. Er scheint der Schlüssel zu all dem zu sein. Nur war er schon lange nicht mehr in Boralus.', 28153),
(154882, 'deDE', '', 'Wir müssen Haus Sturmsang zuerst wieder auf unsere Seite bringen. Sie kontrollieren die Gezeitenweisen und die Gezeitenweisen die Flotte.', 28153),
(154881, 'deDE', '', 'Erzittert unter dem Schatten des Vulperabanners, treuloser Abschaum.', 28153),
(154880, 'deDE', 'Ihr braucht eine Gasmaske, wenn Ihr die Seuche überleben wollt. Wenn Ihr möchtet, könnt Ihr dazu auch einen Seuchenkanister nehmen und helfen.', 'Ihr braucht eine Gasmaske, wenn Ihr die Seuche überleben wollt. Wenn Ihr möchtet, könnt Ihr dazu auch einen Seuchenkanister nehmen und helfen.', 28153),
(154879, 'deDE', '', 'Ich fürchte, Kul Tiras wird der Allianz keine große Hilfe sein, solange die Flotte nicht heimgekehrt ist.', 28153),
(154878, 'deDE', '', 'Und die Gefangenen da unten sollen wissen, dass wir sie nicht im Stich gelassen haben.', 28153),
(154877, 'deDE', '', 'Gut, sie sollen ruhig wissen, wer ihnen den Hals umdreht.', 28153),
(154876, 'deDE', 'Das ist riskant, Nisha. Die Treulosen werden uns hier oben entdecken.', '', 28153),
(154875, 'deDE', 'Gute Arbeit. Der Lich hatte unsere Späher mit seinen Truppen angegriffen. Jetzt sollten wir uns auf die Horde konzentrieren können.', '', 28153),
(154874, 'deDE', 'In Drustvar sind Hexen, und in Nazmir gibt es anscheinend Lichs. Vernichtet die Armee dieses Monsters und was auch immer ihr Macht verleiht.', '', 28153),
(154873, 'deDE', '', 'Nisha wird sich freuen, Euch zu sehen! Sie ist draußen am Krater und tötet Sethrak... wie immer.', 28153),
(154872, 'deDE', 'Beeindruckend, obwohl man mir sagt, dass sich die Gnome weigern, mit Goblintechnologie zu arbeiten. Aber wenigstens wissen wir, wozu sie fähig ist.', '', 28153),
(154871, 'deDE', 'Unsere Truppen haben den Goblins ein experimentelles Gerät abgenommen. Probiert es an der Bluttrollarmee in der Nähe aus, damit wir uns eine Vorstellung von seiner Macht verschaffen können.', '', 28153),
(154870, 'deDE', 'Ich habe das Gefühl, dass die Naga noch mehr als das geplant haben. Haltet die Augen nach ihnen offen.', '', 28153),
(154869, 'deDE', 'Naga! Sie haben diese Welt schon lange genug terrorisiert. Haltet sie auf, egal, was sie vorhaben.', '', 28153),
(154866, 'deDE', 'Seit dem Dritten Krieg habe ich eine solche Wildheit im Kampf gegen die Horde nicht mehr gesehen. Großartige Leistung!', '', 28153),
(154864, 'deDE', 'Ihr habt Euch gegen die Horde tapfer geschlagen. Das Volk von Kul Tiras wird von Eurem Heldenmut erfahren.', '', 28153),
(154863, 'deDE', 'Gute Arbeit. Lasst uns hoffen, dass dieser Konflikt ein besseres Ende nimmt als der Zweite Krieg.', '', 28153),
(154861, 'deDE', '', 'Sie halten die Kinder unten im Krater gefangen. Passt auf!', 28153),
(154859, 'deDE', 'Gut gemacht! Die Horde kann nix aufhalt\'n!', '', 28153),
(154858, 'deDE', 'Einige Späher wurden getötet, als sie Streitkräfte der Horde in der Nähe bekämpft haben. Nun liegt es an Euch, zu beenden, was auch immer sie hier im Schilde führen.', '', 28153),
(154857, 'deDE', 'Gut gemacht! Von Euch könnt\' ich glatt noch was lern\', Mann.', '', 28153),
(154856, 'deDE', 'Noch\'n toter Feind, und bald wird \'n weiterer sein\' Platz einnehm\'n. Aber erstma\' habt\'er Euch \'ne Pause verdient.', '', 28153),
(154855, 'deDE', '', 'Ich rufe Sturmherz herbei. Sie kann uns am Anleger im Osten treffen.', 28153),
(154854, 'deDE', 'Ah, Sieg! So\'n süßer Geschmack, Mann!', '', 28153),
(154853, 'deDE', 'Damals im Dritten Krieg wurde ich mit den Taktiken der Horde vertraut gemacht. Ganz in der Nähe scheinen sie sich einer ziemlich gefährlichen zu bedienen. Macht ihnen den Garaus.', '', 28153),
(154852, 'deDE', 'Ha-ha. Da wusste jemand nich\', mit wem er sich anlegt, was?', '', 28153),
(154851, 'deDE', 'Die Operationen der Horde in der Nähe erinnern mich an ihre Taktiken im Zweiten Krieg. Wir müssen sie aufhalten, bevor sie damit erfolgreich sind.', '', 28153),
(154850, 'deDE', 'Das is\' echt beeindruckend, Mann!', '', 28153),
(154848, 'deDE', 'Da is\' \'ne starke Seele in der Nähe. Schnell, erlegt das Ding!', '', 28153),
(154846, 'deDE', 'Ein Feind versteckt sich in der Nähe. Mach\'n wir ihn kalt.', '', 28153),
(154845, 'deDE', 'Im Namen der 7. Legion danke ich Euch für Eure Unterstützung im Kampf gegen die Horde.', '', 28153),
(154843, 'deDE', 'Die Niederlage der Horde hier wird es der 7. Legion erlauben, vorzurücken. Gut gemacht!', '', 28153),
(154842, 'deDE', 'König Anduin wird von Euren Heldentaten im Kampf gegen die Horde erfahren.', '', 28153),
(154838, 'deDE', 'Meine Späher berichten von Truppenbewegungen der Horde in der Nähe Eurer Position. Und sie sind anfällig für einen Hinterhalt. Schaltet sie aus!', '', 28153),
(154836, 'deDE', 'Uns wurde berichtet, dass sich eine große Menge Truppen der Horde in der Nähe sammelt. Das ist unsere Chance zuzuschlagen!', '', 28153),
(154833, 'deDE', 'Es gibt \'n Ziel in der Nähe. Macht schnell!', '', 28153),
(154832, 'deDE', 'Die 7. Legion hat Hordetruppen in der Nähe ausgemacht. Euer Befehl lautet, sie aufzuhalten und zu vereiteln, was immer sie auch vorhaben.', '', 28153),
(154831, 'deDE', 'Da lauert noch so \'ne Bedrohung in der Nähe. Ihr wisst, was Ihr zu tun habt.', '', 28153),
(154830, 'deDE', 'Die Geister bericht\'n mir von \'nem stark\'n Feind hier im Gebiet. Den sollt\'n wir ma\' erleg\'n... bevor er \'n Problem wird.', '', 28153),
(154829, 'deDE', 'Eine mächtige Bedrohung lauert in der Nähe. Schaltet die ma\' aus!', '', 28153),
(154828, 'deDE', 'Gute Arbeit! Habt Ihr in Betracht gezogen, der 7. Legion permanent beizutreten? Wir könnten jemanden wie Euch gebrauchen!', '', 28153),
(154827, 'deDE', 'Ausgezeichnete Arbeit. Für König Anduin! Für die Allianz!', '', 28153),
(154826, 'deDE', 'Heute habt Ihr der 7. Legion und der Allianz einen großen Dienst erwiesen.', '', 28153),
(154825, 'deDE', 'Ihr habt meinen Dank... und den Dank jedes Soldaten der 7. Legion.', '', 28153),
(154824, 'deDE', 'Ich werde dafür sorgen, dass König Anduin von Eurem Heldenmut erfährt.', '', 28153),
(154823, 'deDE', 'Unsere Späher haben gemeldet, dass ein mächtiger Gegner nahe Eurer Position lauert. Schaltet ihn aus.', '', 28153),
(154822, 'deDE', 'Die 7. Legion hat Befehle erhalten, ein Ziel in Eurer Nähe auszuschalten.', '', 28153),
(154821, 'deDE', 'Sie sollten in Zukunft wirklich vorsichtiger sein. Wir können nicht immer da sein, wenn sie in Schwierigkeiten geraten. Danke, Champion.', '', 28153),
(154820, 'deDE', 'Eine Gruppe Feldmesser ist von den Untoten umzingelt! Helft ihnen, bevor es zu spät ist!', '', 28153),
(154819, 'deDE', 'Wir übernehmen ab hier. Zeit, dass wir G\'huun ein Ende bereiten.', '', 28153),
(154818, 'deDE', 'Bäh, das ist also \'ne reanimierte Leiche? Bringen wir ihn wieder unter die Erde.', '', 28153),
(154817, 'deDE', 'Den Troll erkenn ich wieder, so hässlich wie er ist. Was hat Zul vor?', '', 28153),
(154816, 'deDE', '...', '', 28153),
(154815, 'deDE', '...', '', 28153),
(154814, 'deDE', '...', '', 28153),
(154813, 'deDE', '...', '', 28153),
(154812, 'deDE', '...', '', 28153),
(154811, 'deDE', '...', '', 28153),
(154810, 'deDE', '...', '', 28153),
(154809, 'deDE', '...', '', 28153),
(154808, 'deDE', 'Eine habt Ihr wohl übersehen!', '', 28153),
(154807, 'deDE', '', 'In dieser Anlage wurden verschiedene Lebensformen erforscht, um Lösungen für die Verderbnis der Alten Götter zu finden.', 28153),
(154806, 'deDE', 'Ach! Was zum Kuckuck ist denn das?', '', 28153),
(154805, 'deDE', '...', '', 28153),
(154804, 'deDE', 'Ich hab viel gehört über die Macht von N\'Zoths Dienern. Ich hoffe, das war das erste und letzte Mal, dass ich wirklich einem begegne.', '', 28153),
(154803, 'deDE', 'Das war knapp. Wenn wir es nicht aufgehalten hätten, wer weiß, wie viele es auf der Oberfläche infiziert hätte.', '', 28153),
(154802, 'deDE', 'Klingt nach \'nem Plan. Wenn wir schon dabei sind, schau ich mal, was für Geheimnisse die Titanen sonst noch hinterlassen haben.', '', 28153),
(154801, 'deDE', '...', '', 28153),
(154800, 'deDE', 'Tja, so viel Zeit haben wir nicht. Wir sollten G\'huun vernichten, bevor seine Seuche sich weiter ausbreitet.', '', 28153),
(154799, 'deDE', 'Und, wisst Ihr jetzt mehr?', '', 28153),
(154798, 'deDE', 'Daher die vielen Bluttrolle. Aber warum würden die Titanen einen der Alten Götter am Leben lassen?', '', 28153),
(154797, 'deDE', 'Mann, bin ich froh, Euch zu sehen. So wie ich es verstehe, ist das hier so \'ne Art Forschungsanlage.', '', 28153),
(154796, 'deDE', 'Na also! Diese Technologie ist gar nicht so kompliziert, wenn man ein Händchen dafür hat.', '', 28153),
(154795, 'deDE', 'Zum zwölften Mal!', '', 28153),
(154794, 'deDE', 'Was?! Nein! Die verdammten Türen sind verriegelt! Schlagt alles kaputt, bis sie sich öffnen!', '', 28153),
(154793, 'deDE', 'Eine Sekunde. Ich hab die Tür so gut wie auf.', '', 28153),
(154792, 'deDE', 'Ihr habt\'s geschafft! Sekunde. Ich hab Zugriff auf \'ne Art Hausmeistereinheit, die vermutlich die Anlage steuert.', '', 28153),
(154791, 'deDE', 'Ich habe gerade Legende erreicht.', '', 28153),
(154789, 'deDE', 'Die Schlacht wütet weiter. Führt den Kampf gegen unsere Feinde fort!', '', 28153),
(154788, 'deDE', 'Ein wichtiges Ziel wurde in der Nähe gesichtet. Ihr müsst es umgehend ausschalten.', '', 28153),
(154787, 'deDE', 'Ein mächtiger Feind ist in der Nähe. Eliminiert ihn. Zeigt keine Gnade!', '', 28153),
(154780, 'deDE', 'Bereit für den Kampf.', 'Bereit für den Kampf.', 28153),
(154779, 'deDE', '', 'Torcanata! Ha! Ha! Ha!', 28153),
(154777, 'deDE', '', 'Heut is\' Torcanata! Wenn Ihr mitmach\'n wollt, schnappt Euch \'ne Fackel und macht Euch bereit, loszurenn\'!', 28153),
(154774, 'deDE', '', 'Champion, Ihr genießt offenbar immer mehr Vertrauen bei den Zandalari. Ich muss mich nun anderen Pflichten widmen. Viel Glück.', 28153),
(154772, 'deDE', '', 'Oculeth, seht Euch das bitte näher an. Wir werden Nachschublinien zu den Hauptstädten der Horde brauchen.', 28153),
(154770, 'deDE', 'Trefft mich bei Bwoljins Sturz, sobald Ihr könnt, $p. Wir schleichen uns gemeinsam in Kortheks Festung.', '', 28153),
(154769, 'deDE', '', 'Prinzessin Talanji war so freundlich, uns über ein altes Portalnetzwerk zu informieren, das wir vielleicht benutzen können.', 28153),
(154768, 'deDE', '', 'Sprecht mich an, wenn Ihr bereit seid, Aschenwinds Flotte zu versenken.', 28153),
(154767, 'deDE', '', 'Ihr habt Euch gut geschlagen, Helden. Doch die Gefahr ist noch nicht gebannt.', 28153),
(154766, 'deDE', 'Zurück an Eure Arbeit. Die gehören zu mir.', 'Zurück an Eure Arbeit. Die gehören zu mir.', 28153),
(154765, 'deDE', 'Fremde sind im Archiv nicht zugelassen, Bruder.', 'Fremde sind im Archiv nicht zugelassen, Bruder.', 28153),
(154764, 'deDE', 'Dort stand ich also, am Strand, umgeben von diesen elenden Gilblins... und plötzlich erschien eine heldenhafte Gestalt! Oh! Hallo noch mal, $n!', '', 28153),
(154763, 'deDE', 'Geht und beschafft die Schriftrollen! Ich werde die... schöne Strecke zurück zum Lager nehmen und von Euren Erfahrungen berichten.', '', 28153),
(154762, 'deDE', 'Ganz gleich, was sie aufbieten, die Allianz wird nichts als bitteres Versagen ernten.', '', 28153),
(154761, 'deDE', 'Einige Champions der Allianz sind eingetroffen und versuchen, die Stadt zu retten. Durchkreuzt diese Pläne.', '', 28153),
(154760, 'deDE', 'Mit diesen Geschossen werden wir die Allianz zerschmettern.', '', 28153),
(154759, 'deDE', 'Aschenwinds Streitkräfte feuern mit Azeritartillerie auf die Stadt. Beansprucht diese Waffen für die Horde!', '', 28153),
(154758, 'deDE', 'Ohne ihre Offiziere treiben wir die Kul Tiraner zurück aufs Meer.', '', 28153),
(154757, 'deDE', 'Ein Offizier von Kul Tiras etabliert eine Verteidigungslinie. Entfernt ihn vom Schlachtfeld.', '', 28153),
(154756, 'deDE', '', 'Ausgezeichnet. Ihr habt der Horde gezeigt, dass kein Feind jemals Boralus einnehmen wird.', 28153),
(154755, 'deDE', '', 'Sieht aus, als nutzt die Horde die Gunst der Stunde und überfällt die Stadt! Verhindert die Plünderung von Boralus!', 28153),
(154754, 'deDE', '', 'Gut gemacht. Ihr habt Aschenwind gezeigt, dass bezahlte Schläger gegen Euch nichts ausrichten.', 28153),
(154753, 'deDE', '', 'Einer von Aschenwinds Söldnern stellt die Stadt auf den Kopf. Haltet ihn auf!', 28153),
(154752, 'deDE', '', 'Gut gemacht. Diese Verbrecher sind die Einzigen, die in Ketten gehören.', 28153),
(154751, 'deDE', '', 'Die Piraten nehmen Zivilisten als Sklaven! Macht dem ein Ende!', 28153),
(154750, 'deDE', 'Gorak Tul... kommt...', '', 28153),
(154749, 'deDE', 'Ganz Kul Tiras wird leiden. Ihr seid nur der Anfang!', '', 28153),
(154748, 'deDE', 'Närrische Made! Ihr werdet schreiend sterben!', '', 28153),
(154747, 'deDE', 'Oou ph\'magg an\'qov nuq.', '', 28153),
(154746, 'deDE', 'Ywaq ongg uul\'gwa no AN\'zig!', '', 28153),
(154745, 'deDE', 'Arwi ryiu yrr oou qam!', '', 28153),
(154744, 'deDE', 'AN\'zig wgah qam za zyqtahg...', '', 28153),
(154743, 'deDE', 'AN\'zig wgah zzof!', '', 28153),
(154742, 'deDE', 'Ywaq fhssh wgah qam!', '', 28153),
(154741, 'deDE', 'Uulg\'ma zyqtahg yrr!', '', 28153),
(154740, 'deDE', 'Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz!', '', 28153),
(154739, 'deDE', 'Jetzt verschwindet, solange es noch geht! Die anderen haben Eure Bemühungen mit Sicherheit bemerkt.', 'Jetzt verschwindet, solange es noch geht! Die anderen haben Eure Bemühungen mit Sicherheit bemerkt.', 28153),
(154738, 'deDE', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Ihr wurdet als Ziel von |cFFFF0000|Hspell:260838|h[Schmetterbohrer]|h|r ausgewählt!', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Ihr wurdet als Ziel von |cFFFF0000|Hspell:260838|h[Schmetterbohrer]|h|r ausgewählt!', 28153),
(154737, 'deDE', 'Og qam shfk wgah iiqaah halahs ma!', '', 28153),
(154736, 'deDE', 'Sucht Bruder Pike in Brennadam auf. Gebt ihm diesen Anhänger. Unsere Arbeit steht erst am Anfang und er wird Eure Hilfe brauchen.', 'Sucht Bruder Pike in Brennadam auf. Gebt ihm diesen Anhänger. Unsere Arbeit steht erst am Anfang und er wird Eure Hilfe brauchen.', 28153),
(154735, 'deDE', 'Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma!', '', 28153),
(154734, 'deDE', 'Unser Volk wandelt auf dunklen Pfaden. Doch es gibt einige unter uns, die die Saat des Widerstands gesät haben.', 'Unser Volk wandelt auf dunklen Pfaden. Doch es gibt einige unter uns, die die Saat des Widerstands gesät haben.', 28153),
(154733, 'deDE', 'Zuq ag\'xig ka\'kar za wgah!', '', 28153),
(154732, 'deDE', 'Puul qi\'plahf ni oou bormax!', '', 28153),
(154731, 'deDE', 'Xith wgah!', '', 28153),
(154729, 'deDE', 'Naz raqul!', '', 28153),
(154728, 'deDE', 'I wgah far\'al zuq ni shn!', '', 28153),
(154727, 'deDE', 'Die Flotte wird nicht vermisst. Sie wird in einem unnatürlichen Sturm gefangen gehalten.', 'Die Flotte wird nicht vermisst. Sie wird in einem unnatürlichen Sturm gefangen gehalten.', 28153),
(154726, 'deDE', 'Zuq wgah qam n\'lyeth!', '', 28153),
(154725, 'deDE', 'Zuq ag\'xig gag wgah naggwa\'fssh!', '', 28153),
(154724, 'deDE', 'Zuq ag\'xig bormax oou iiqaath!', '', 28153),
(154723, 'deDE', 'Geht es Euch gut? Ich hätte wissen müssen, dass Watt dem Schatten nicht gewachsen ist, der auf Haus Sturmsang lastet.', 'Geht es Euch gut? Ich hätte wissen müssen, dass Watt dem Schatten nicht gewachsen ist, der auf Haus Sturmsang lastet.', 28153),
(154722, 'deDE', '', 'Was meint Ihr mit \"Gefahr\"?', 28153),
(154721, 'deDE', 'Ja, Bruder.', 'Ja, Bruder.', 28153),
(154720, 'deDE', 'Keine Besucher. Ich habe Gäste.', 'Keine Besucher. Ich habe Gäste.', 28153),
(154719, 'deDE', 'Ihr habt keine Ahnung, in welcher Gefahr Ihr Euch hier befindet.', '', 28153),
(154718, 'deDE', 'Folgt mir. Und senkt Euren Blick.', '', 28153),
(154717, 'deDE', 'Unsere Befestigungen sind noch immer relativ schwach. Haltet die Truppen der Horde auf, bevor sie zu nahe kommen!', '', 28153),
(154716, 'deDE', 'Stromgarde ist noch schwach. Es wird einem direkten Angriff nicht standhalten. Vernichtet die Vorhut der Horde, bevor sie zu nahe kommt!', '', 28153),
(154715, 'deDE', 'Ha! \'ne feine Respektsbekundung für Pa\'ku!', '', 28153),
(154714, 'deDE', 'Schickt unsre Truppen! Wir müss\'n dieses Allianzungeziefer ausrott\'n, bevor es sich ausbreitet!', '', 28153),
(154713, 'deDE', '', 'Es is\' Zeit! Steigt die Stufen von Zanchul hinauf und erweist unserm Loa die Ehre. Mit seinem Segen wird Zandalar besteh\'n! Macht Gonk stolz!', 28153),
(154712, 'deDE', '', 'Setzt unsere Truppen ein! Lasst nicht zu, dass die Allianz sich hier einnistet.', 28153),
(154711, 'deDE', 'Macht Euch kampfbereit. Gleich geht\'s los!', '', 28153),
(154710, 'deDE', 'Schickt unsere Truppen rein! Die Mauern von Stromgarde werden unter dem Ansturm der Horde einstürzen!', '', 28153),
(154709, 'deDE', 'Wir müss\'n die Hochburg schütz\'n. Lasst ihre Trupp\'n nich\' ran!', '', 28153),
(154708, 'deDE', 'Keine Verzögerungen. Lord Sturmsang braucht diese Karten sofort am Schrein des Sturms!', '', 28153),
(154707, 'deDE', 'Schickt unsere Truppen rein! Von ihrer Basis werden nur Trümmer übrigbleiben.', '', 28153),
(154706, 'deDE', '', 'Die Gezeitenweisen verfügen über eine der vollständigsten Bibliotheken auf der ganzen Welt. Ich wette, wir werden unseren Archivar dort finden.', 28153),
(154705, 'deDE', '', 'Die Allianz marschiert auf Ar\'gorok! Wir müssen sie aufhalten, bevor sie die Festung erreichen!', 28153),
(154704, 'deDE', 'Soldaten der Allianz! Streckt sie nieder!', '', 28153),
(154703, 'deDE', 'Soldaten des Bundes von Arathor, greift an!', '', 28153),
(154702, 'deDE', 'Horde, zum Angriff! Vernichtet diese feigen Schlossbewohner, bevor sie unser Tor durchbrechen!', '', 28153),
(154701, 'deDE', '', 'Kaventsmann! Kaventsmann!', 28153),
(154700, 'deDE', 'Oh! Kaventsmann! Kaventsmann!', '', 28153),
(154699, 'deDE', '', 'Das hier gefällt mir gar nicht. Lasst uns von hier verschwinden.', 28153),
(154698, 'deDE', 'Verschwindet ins Archiv zu Alen, diesem Narren. Sonst stabilisiere ich den Riss mit EUCH...', '', 28153),
(154697, 'deDE', 'Strengt Euch an, Ihr Dummköpfe, bevor wir die Kontrolle verlieren!', '', 28153),
(154696, 'deDE', '', 'Wenn Ihr Euch so anstellt, machen wir vielleicht genau das!', 28153),
(154695, 'deDE', '', 'Wieso geht Ihr nicht Alen auf die Nerven, wenn Ihr hier Eure Zeit verschwenden wollt?', 28153),
(154694, 'deDE', '', 'Öffnet Eure Seelen den Gezeiten. Ihr Flüstern birgt Wahrheit!', 28153),
(154693, 'deDE', 'Samen einpflanzen', 'Samen einpflanzen', 28153),
(154692, 'deDE', '', 'Gilneer, ladet die Kanonen! Vorrücken!', 28153),
(154691, 'deDE', 'Ähm, meine Damen und Herren, startet die Motoren! Zum Angriff!', '', 28153),
(154690, 'deDE', 'Schützen, Gewehre laden und vorrücken!', 'Schützen, Gewehre laden und vorrücken!', 28153),
(154689, 'deDE', '', 'Wir garantieren Eurem Schiff sicheres Geleit, wenn der Preis stimmt.', 28153),
(154688, 'deDE', '', 'So viel Elend. Vielleicht sollten wir hier keine Hochzeiten mehr feiern.', 28153),
(154687, 'deDE', '', 'Monster haben dieses freudige Fest ruiniert! Löscht sie aus und rettet die Hochzeitsgäste!', 28153),
(154686, 'deDE', '', 'Also... ist das jetzt ein Nein?', 28153),
(154685, 'deDE', '', 'Ihr seid beinahe so unausstehlich wie Bruder Alen.', 28153),
(154684, 'deDE', '', 'Ihr dort, wer hat hier das Sagen?', 28153),
(154683, 'deDE', 'Hmpf.', 'Hmpf.', 28153),
(154682, 'deDE', 'Schaut auf Eure schwärenden Wunden und singt das Lied der Verzweiflung!', '', 28153),
(154681, 'deDE', 'Wehrt Euch nicht gegen den Wahnsinn! Nehmt ihn in Euch auf!', '', 28153),
(154680, 'deDE', 'Erkennt die Schönheit des Verfalls und gebt Euch ihr hin!', '', 28153),
(154679, 'deDE', 'Ich werde Euch zu Asche verbrennen!', '', 28153),
(154678, 'deDE', 'Xalzaix hungert nach Vernichtung!', '', 28153),
(154677, 'deDE', 'Ihr werdet nicht überleben!', '', 28153),
(154676, 'deDE', 'Ihr könnt der Vernichtung nicht entrinnen!', '', 28153),
(154675, 'deDE', 'Ihr könnt den Schatten nicht entkommen!', '', 28153),
(154674, 'deDE', 'Auslöschen!', '', 28153),
(154673, 'deDE', 'Vernichtung!', '', 28153),
(154672, 'deDE', 'Ihr könnt Euch meinem Ruf nicht entziehen.', '', 28153),
(154671, 'deDE', 'Gebt Euch der Seuche hin!', '', 28153),
(154670, 'deDE', 'G\'huun ist unaufhaltsam...', '', 28153),
(154669, 'deDE', 'Die Fäulnis verschlingt alles.', '', 28153),
(154668, 'deDE', 'Eure Hülle gehört G\'huun.', '', 28153),
(154667, 'deDE', 'Mehr Nahrung für die Seuche!', '', 28153),
(154666, 'deDE', 'G\'huun wird auferstehen!', '', 28153),
(154665, 'deDE', 'Eure Welt wird enden!', '', 28153),
(154664, 'deDE', 'Euer Verfall ist unausweichlich.', '', 28153),
(154663, 'deDE', 'Ich bin das Kratzen in Eurer Kehle. Der flüchtige Gedanke. Ich war schon immer bei Euch.', '', 28153),
(154662, 'deDE', 'Alles Leben vergeht. Akzeptiert Eure Verwandlung.', '', 28153),
(154661, 'deDE', '', 'Neuerschaffungsantrieb wiederhergestellt. Zugang zur Kammer gewährt.', 28153),
(154660, 'deDE', '', 'Konsole aktiviert. Sicherheitssysteme werden hochgefahren.', 28153),
(154659, 'deDE', 'Oh! Eine Sache noch. Na ja, zwei eigentlich.', '', 28153),
(154658, 'deDE', '', 'Erste Konsole aktiviert. Stelle Energiematrix wieder her.', 28153),
(154657, 'deDE', '', 'Testobjekt G\'huun vernichtet. Keine brauchbaren Proben verbleiben.', 28153),
(154656, 'deDE', '', 'Verderbnis erreicht normale Werte. Systemintegrität wiederhergestellt.', 28153),
(154655, 'deDE', 'Und wenn der Planet schließlich aufplatzt wie eine riesige Eiterbeule, wird meine Fäulnis den Kosmos überziehen.', '', 28153),
(154654, 'deDE', 'Ihr werdet meine Seuche verbreiten, bis ein riesiger, schwärender Abszess die Welt bedeckt.', '', 28153),
(154653, 'deDE', 'Solch eifrige Wirte. Ihr werdet die ersten sein, die mein Geschenk erhalten.', '', 28153),
(154652, 'deDE', 'Die Siegel – gebrochen. Die Titanen – ausgelöscht. Die Ära der Fäulnis beginnt.', '', 28153),
(154651, 'deDE', '', 'Das is\' für Dazar\'alor, abscheuliche Kreatur!', 28153),
(154650, 'deDE', '', 'Wir erledig\'n den Rest. Wir werd\'n G\'huuns Seuche \'n Ende bereit\'n.', 28153),
(154649, 'deDE', '', 'Warnung, erhöhte Kontaminationsgefahr ab diesem Punkt. Quarantänevorschriften verbieten es mir, fortzufahren.', 28153),
(154648, 'deDE', 'Perfekt, $p! Wir haben mehr als genug Minen, um gegen die Venture Company loszuschlagen.', '', 28153),
(154647, 'deDE', '', 'Es is\' egal, wie er zurückgekehrt is\'. Mein Messer schickt ihn wieder ins Dunkel!', 28153),
(154646, 'deDE', 'Hier stehen eine ganze Menge Minen zur Auswahl.', '', 28153),
(154645, 'deDE', '', 'Eine Analyse hat höhere Pegel von Verderbnis ergeben. Hypothese: G\'huun hat dieses Exemplar reanimiert und modifiziert. Weitere Tests erforderlich.', 28153),
(154644, 'deDE', '', 'Zul?! Wie is\' das möglich? Ich hab\' geseh\'n, wie mein Vater ihn getötet hat!', 28153),
(154643, 'deDE', 'Diese Minen wurden nicht gebaut, um Schildkröten zu erkennen! Wir können sie gefahrlos aufsammeln.', '', 28153),
(154642, 'deDE', '', 'Ihr scheint eins überseh\'n zu ham.', 28153),
(154641, 'deDE', '', 'Die Tests konzentrierten sich vor allem auf die Fähigkeit von G\'huuns Verderbnis, totes Gewebe zu reanimieren. Die Ergebnisse waren unbefriedigend und die Testobjekte wurden zerstört.', 28153),
(154640, 'deDE', '', 'Das ist korrekt. In dieser Anlage wurden Versuche an Loa durchgeführt, um eine Lösung für die Verderbnis der Alten Götter zu finden.', 28153),
(154639, 'deDE', '', 'Was is\' das für \'ne Kreatur? Sieht aus, als wär\'s mal \'n Loa gewesen.', 28153),
(154638, 'deDE', '', 'Wenn das Ding einer von G\'huuns Dienern war, dann müss\'n wir ihn aufhalt\'n, bevor \'ne ganze Armee von denen nach oben gelangt.', 28153),
(154637, 'deDE', '', 'Fehler. Datenscheibe defekt. Datenübertragung fehlerhaft.', 28153),
(154636, 'deDE', '', 'System wird hochgefahren.', 28153),
(154635, 'deDE', '', 'Bitte begebt Euch auf die medizinische Station zur neuralen Extraktion und Entnahme von Hirngewebe.', 28153),
(154634, 'deDE', '', 'Eine Analyse Eures Cortex hat ergeben, dass alle anwesenden Individuen schon einmal Kontakt mit Exemplaren der Alten Götter hatten.', 28153),
(154633, 'deDE', '', 'Alle Daten aus früheren Erfahrungen sind für die Forschung dieser Anlage hilfreich.', 28153),
(154632, 'deDE', '', 'Eine Analyse Eures Cortex hat ergeben, dass einige der anwesenden Individuen schon einmal Kontakt mit Exemplaren der Alten Götter hatten.', 28153),
(154631, 'deDE', '', 'Und neunhundertfünfzig Milliarden Norgabyte an musikalischen Wiedergabelisten und Selbstporträts.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'deDE', '', 'Fünfundsiebzig Norgabyte Daten über alle bestehenden chemischen Verbindungen.', 28153),
(154629, 'deDE', '', 'Diese Scheiben enthalten derzeit fünfzig Norgabyte an biologischen Daten über bekannte Lebensformen überall im Kosmos.', 28153),
(154628, 'deDE', '', 'Ihr betretet den Datenraum. Hier wurde Wissen der Titanen gesammelt und aufbewahrt.', 28153),
(154627, 'deDE', 'Ihr kämpft gegen das Unausweichliche. Meine Seuche ist nicht aufzuhalten. Sie schwärt bereits in Euch.', '', 28153),
(154626, 'deDE', '', 'Wenn das Ding an uns vorbeigekomm\'n wär, hätt\' es alles Leben auf der Oberfläche infiziert.', 28153),
(154625, 'deDE', 'Ah, willkommen. Besucher kommen heutzutage immer seltener, besonders in das Archiv.\n\nWie kann ich Euch behilflich sein?', 'Ah, willkommen. Besucher kommen heutzutage immer seltener, besonders in das Archiv.\n\nWie kann ich Euch behilflich sein?', 28153),
(154624, 'deDE', '', 'Alarm. Virale Sicherheitsschleusen durchbrochen. Kontaminierte Testobjekte nähern sich. Maximales Infektionsrisiko.', 28153),
(154623, 'deDE', '', 'Dieses Labor enthält tausende der gefährlichsten Virenstämme im bekannten Kosmos, alphabetisch sortiert für erleichterten Zugriff.', 28153),
(154622, 'deDE', '', 'Ihr betretet den Flügel für virale Ökologie.', 28153),
(154621, 'deDE', '', 'Haltet \'Machtwort: Schild\' immer aktiv, um von \'Abbitte\' zu profitieren.', 28153),
(154620, 'deDE', 'Haltet \'Machtwort: Schild\' immer aktiv, um von \'Abbitte\' zu profitieren.', '', 28153),
(154619, 'deDE', '', 'Wirkt \'Machtwort: Schild\' auf Euch selbst und fügt dann der Zielattrappe Schaden zu, um Euch zu heilen.', 28153),
(154618, 'deDE', 'Wirkt \'Machtwort: Schild\' auf Euch selbst und fügt dann der Zielattrappe Schaden zu, um Euch zu heilen.', '', 28153),
(154617, 'deDE', '', 'Wenn Ihr einem Gegner Schaden zufügt, wird jeder Verbündete geheilt, den Ihr mit \'Abbitte\' belegt habt.', 28153),
(154616, 'deDE', 'Wenn Ihr einem Gegner Schaden zufügt, wird jeder Verbündete geheilt, den Ihr mit \'Abbitte\' belegt habt.', '', 28153),
(154615, 'deDE', '', 'Manche Zauber, wie \'Machtwort: Schild\', wirken \'Abbitte\' auf Euer Ziel.', 28153),
(154614, 'deDE', 'Könnt Ihr mir etwas über die verschwundene Flotte erzählen?', 'Könnt Ihr mir etwas über die verschwundene Flotte erzählen?', 28153),
(154613, 'deDE', 'Manche Zauber, wie \'Machtwort: Schild\', wirken \'Abbitte\' auf Euer Ziel.', '', 28153),
(154612, 'deDE', 'Unser Kriegshäuptling wird sich nicht leicht überzeugen lassen. Kommt.', '', 28153),
(154611, 'deDE', 'Vielleicht ist es Zeit, eine alte Schuld einzufordern. Dadurch könnten wir die Horde um treue Soldaten verstärken.', '', 28153),
(154610, 'deDE', '$n, Ihr liebt die Horde genauso sehr wie ich. Ich fürchte, wenn wir nichts tun, wird sie diesen Krieg nicht überstehen.', '', 28153),
(154609, 'deDE', '', 'Wir ham \'nen Plan. Aktiviert die Konsolen und setzt G\'huuns Seuche ein für alle Mal \'n Ende.', 28153),
(154608, 'deDE', '', 'Die Aktivierung aller Konsolen öffnet den Zugang zu G\'huuns Kammer, wo das Testobjekt mithilfe des Neuerschaffungsantriebs gesäubert werden kann.', 28153),
(154607, 'deDE', '', 'Um das Testobjekt zu vernichten, müssen die in diesem Flügel verteilten Konsolen reaktiviert werden.', 28153),
(154606, 'deDE', '', 'So viel Zeit ham wir nich\'! Wir müss\'n G\'huun jetzt aufhalt\'n!', 28153),
(154605, 'deDE', '', 'Negativ. Daten unschlüssig. Alternative Tests sind in Entwicklung und werden planmäßig in 2364 Zyklen durchgeführt.', 28153),
(154604, 'deDE', 'Oha! Das Zeug hat echt Bums!', '', 28153),
(154603, 'deDE', '', 'Und habt Ihr gefund\'n, was Ihr gesucht habt?', 28153),
(154602, 'deDE', 'Jetzt noch ein kleiner Funke... Äh, vielleicht macht Ihr besser einen Schritt zurück.', '', 28153),
(154601, 'deDE', 'Vielleicht können wir das Schloss wegpusten. Streut was von dem Pulver drauf.', '', 28153),
(154600, 'deDE', '', 'Die Sammlung von Daten ist unverzichtbar für die Bekämpfung der Alten Götter. G\'huuns biologisches Potenzial ist der Schlüssel zur Eliminierung dieser Bedrohung.', 28153),
(154599, 'deDE', '', 'Ihr habt dieses Monstrum am Leben gelass\'n!? Warum?', 28153),
(154598, 'deDE', '', 'Bezeichnung: Uldir. Eine Forschungsanlage mit dem Zweck, die Entität namens G\'huun zu verwahren und zu studieren.', 28153),
(154597, 'deDE', '', 'Was is\' das für \'n Ort?', 28153),
(154596, 'deDE', '', 'Anlagensysteme beschädigt. Vorsicht beim Fortfahren.', 28153),
(154595, 'deDE', '', 'Die Türen sin\' zu! Schaltet die Maschine ab, bevor wir zu Asche verbrenn\'n!', 28153),
(154594, 'deDE', '', 'Alarm. Kontaminierte Lebensform entdeckt. Verbrennungsanlage aktiviert.', 28153),
(154593, 'deDE', '', 'Wegen ihr hat sich die Verseuchung noch nich\' auf die ganze Anlage ausgebreitet.', 28153),
(154592, 'deDE', '', 'Ich bin die Matrone unnachgiebiger Tradition in tatkräftiger, endloser Recherche. Kennzeichen: M.U.T.T.E.R.', 28153),
(154591, 'deDE', '', 'Für die Horde!', 28153),
(154590, 'deDE', '', 'Was war das für \'ne Stimme?', 28153),
(154589, 'deDE', '', 'Für die Horde!', 28153),
(154588, 'deDE', 'Lok-tar ogar! Für die Horde!', '', 28153),
(154587, 'deDE', '', 'Virulentes Exemplar vernichtet. Öffne Dekontaminierungskammer.', 28153),
(154586, 'deDE', '', 'Ich akzeptiere Euren Treueschwur, Oberanführerin. Euer Volk ist in den Mauern Orgrimmars willkommen.', 28153),
(154585, 'deDE', '', 'Draenor ist gefallen, aber wir machen Azeroth zu unserer neuen Heimat. Eure Feinde sind jetzt unsere!', 28153),
(154584, 'deDE', 'Pulver verstreuen', 'Pulver verstreuen', 28153),
(154583, 'deDE', '', 'Etrigg und Euer Champion haben ihren Mut bewiesen. Wenn sie das Herz der Horde verkörpern, dann kämpfen wir mehr als gern an ihrer Seite.', 28153),
(154582, 'deDE', '', 'Taloc hat den A.M.O.D.-Beschuss überlebt?! Diese Monstrosität steht zwischen uns und G\'huun, räumt sie aus\'m Weg!', 28153),
(154581, 'deDE', 'Bwonsamdi...', 'So weit weg von Zuhause...', 28153),
(154580, 'deDE', 'Ich weiß ja, wie wütend du bist, Schatz, aber das sind echte Monster. Wir müssen jetzt gehen.', 'Ich weiß ja, wie wütend du bist, Schatz, aber das sind echte Monster. Wir müssen jetzt gehen.', 28153),
(154578, 'deDE', '', 'Ehre bedeutet uns alles. Wir schwören diesen Eid nicht leichtfertig, Kriegshäuptling.', 28153),
(154577, 'deDE', 'Wir können ja eine neue Torte besorgen, aber wir sollten jetzt los.', 'Wir können ja eine neue Torte besorgen, aber wir sollten jetzt los.', 28153),
(154576, 'deDE', 'Ich weiß, dass du wütend bist, aber wir müssen jetzt wirklich los, mein Schatz.', 'Ich weiß, dass du wütend bist, aber wir müssen jetzt wirklich los, mein Schatz.', 28153),
(154575, 'deDE', 'Schatz, wir müssen los.', 'Schatz, wir müssen los.', 28153),
(154574, 'deDE', '', 'Etrigg hat mir von der Stärke Eures Volkes berichtet. Ich vertraue darauf, dass Euch Ehre genauso viel bedeutet wie ihm.', 28153),
(154572, 'deDE', 'Ihr habt mein Kleid ruiniert! Dieses Kleid war perfekt! Es war aus importierter Seide aus Quel\'Thalas! Der Schleier gehörte meiner Mutter! Wie könnt Ihr es wagen!', 'Ihr habt mein Kleid ruiniert! Dieses Kleid war perfekt! Es war aus importierter Seide aus Quel\'Thalas! Der Schleier gehörte meiner Mutter! Wie könnt Ihr es wagen!', 28153),
(154570, 'deDE', 'Unsere Mission war erfolgreich, Kriegshäuptling. Oberanführerin Geya\'rah hat ihre Soldaten der Horde verpflichtet.', '', 28153),
(154569, 'deDE', 'Ihr habt unseren Zuckerbäcker umgebracht! Er hatte noch nicht mal die Appetithappen gereicht!', 'Ihr habt unseren Zuckerbäcker umgebracht! Er hatte noch nicht mal die Appetithappen gereicht!', 28153),
(154568, 'deDE', 'Verlor\'n im Sand.', 'Endlich, \'n guter Tod.', 28153),
(154567, 'deDE', 'Wer oder was auch immer Ihr seid... Ihr werdet dafür büßen, meine Hochzeit ruiniert zu haben!', 'Wer oder was auch immer Ihr seid... Ihr werdet dafür büßen, meine Hochzeit ruiniert zu haben!', 28153),
(154566, 'deDE', 'Wisst Ihr eigentlich, was für eine Mühe es war, alles so perfekt hinzubekommen?', 'Wisst Ihr eigentlich, was für eine Mühe es war, alles so perfekt hinzubekommen?', 28153),
(154565, 'deDE', 'Wie könnt Ihr es wagen, mir meinen schönsten Tag zu vermiesen?!', 'Wie könnt Ihr es wagen, mir meinen schönsten Tag zu vermiesen?!', 28153),
(154564, 'deDE', 'Endlich... hat\'s ein Ende.', 'Das darf nich\' sein... nich\' so.', 28153),
(154563, 'deDE', 'Ich habe vier Monate lang kein Brot gegessen!', 'Ich habe vier Monate lang kein Brot gegessen!', 28153),
(154562, 'deDE', 'Der Sand wird uns alle verschling\'n.', 'Der Tod is\' der einzige Ausweg.', 28153),
(154561, 'deDE', 'Habt Ihr eine Ahnung, was diese Torte gekostet hat?!', 'Habt Ihr eine Ahnung, was diese Torte gekostet hat?!', 28153),
(154560, 'deDE', 'Ich stand zwei Jahre lang auf der Warteliste für diesen Trauungsort!', 'Ich stand zwei Jahre lang auf der Warteliste für diesen Trauungsort! Zwei! Jahre!', 28153),
(154559, 'deDE', 'Der Tod hat mich schon zuvor nicht aufgehalten...', '', 28153),
(154558, 'deDE', 'Ich kann Euch mit nur einem Finger töten!', '', 28153),
(154557, 'deDE', '', 'Eine neue Energiematrix kann eingesammelt werden.', 28153),
(154556, 'deDE', '', 'Eine Energiematrix ist bereit zum Einsammeln.', 28153),
(154555, 'deDE', '', 'Achtung. Eine neue Energiematrix ist verfügbar.', 28153),
(154554, 'deDE', '', 'Achtung! Neuerschaffungsexplosion steht kurz bevor. Bitte Bereich räumen.', 28153),
(154553, 'deDE', '', 'Alarm. Sequenz für Neuerschaffungsexplosion läuft. Bitte Bereich verlassen.', 28153),
(154551, 'deDE', 'Die Horde wurde besiegt!', '', 28153),
(154550, 'deDE', 'Schon bald werdet Ihr Euren vergeblichen Widerstand einstellen!', 'Schon bald werdet Ihr Euren vergeblichen Widerstand einstellen!', 28153),
(154549, 'deDE', 'Kommt raus und ergebt Euch Eurem Schicksal!', 'Kommt raus und ergebt Euch Eurem Schicksal!', 28153),
(154548, 'deDE', 'Der in der Tiefe Lauernde wird Eure Haut als Mantel tragen!', 'Der in der Tiefe Lauernde wird Eure Haut als Mantel tragen!', 28153),
(154547, 'deDE', 'Kämpft nur um Eure jämmerliche Existenz! Die endlose Flut wird Euch am Ende doch verschlingen!', 'Kämpft nur um Eure jämmerliche Existenz! Die endlose Flut wird Euch am Ende doch verschlingen!', 28153),
(154546, 'deDE', '', 'Wirkt \'Sühne\', um Eure Wunden zu heilen.', 28153),
(154545, 'deDE', 'Was für Pulver ist das genau? Hey, helft mir mal. Greift Euch was von dem Zeug.', '', 28153),
(154544, 'deDE', 'Wirkt \'Sühne\', um Eure Wunden zu heilen.', '', 28153),
(154543, 'deDE', '', 'Wenn Ihr \'Sühne\' auf Euch selbst oder einen Verbündeten wirkt, heilt Ihr, statt Schaden zu verursachen.', 28153),
(154542, 'deDE', 'Wenn Ihr \'Sühne\' auf Euch selbst oder einen Verbündeten wirkt, heilt Ihr, statt Schaden zu verursachen.', '', 28153),
(154541, 'deDE', 'Tötet diese Monster!', 'Tötet diese Monster!', 28153),
(154540, 'deDE', 'Das sollte doch so ein schönes Fest werden!', 'Das sollte doch so ein schönes Fest werden!', 28153),
(154539, 'deDE', 'Was ist los? Was geschieht hier? Was sind das für Monster?', 'Was ist los? Was geschieht hier? Was sind das für Monster?', 28153),
(154538, 'deDE', 'Das ist schlimmer als betrunkene Schwiegereltern!', 'Das ist schlimmer als betrunkene Schwiegereltern!', 28153),
(154537, 'deDE', 'Warum passiert das alles?', 'Warum passiert das alles?', 28153),
(154536, 'deDE', 'Wir haben noch nicht mal einen Falkenschreitertanz hinlegen können!', 'Wir haben noch nicht mal einen Falkenschreitertanz hinlegen können!', 28153),
(154535, 'deDE', 'Das sollte doch ein so schöner Tag werden!', 'Das sollte doch ein so schöner Tag werden!', 28153),
(154534, 'deDE', 'Ahhhhhhhhh!', 'Ahhhhhhhhh!', 28153),
(154533, 'deDE', 'Mit Eurer Erlaubnis, Kriegshäuptling. Kommt, $n!', '', 28153),
(154532, 'deDE', '', 'Unsere nachtgeborenen Verbündeten haben eine besondere Affinität für Teleportation. Ich schlage vor, Ihr macht Euch ihr Wissen für Eure Reisen zunutze.', 28153),
(154531, 'deDE', 'Ich bin an ein Fragment des Artefakts gelangt, mit dem Garrosh zu dieser Welt reiste. Ich glaube, es kann den Weg wieder öffnen... doch dazu brauche ich Hilfe.', '', 28153),
(154530, 'deDE', '', 'Ich sehe den Nutzen dieses Plans. Aber ist das Tor zu diesem anderen Draenor nicht verschlossen?', 28153),
(154529, 'deDE', 'Ich werde mit Ottkens sprechen. Ich mag meine Arbeit und will sie auch behalten. Aber nach meinen Bedingungen.', '', 28153),
(154528, 'deDE', 'Bedeutet das etwa... Oh, ich verstehe.', '', 28153),
(154527, 'deDE', 'Hm... Ich glaube nicht, dass der Käpt\'n sich gegen ein Bündnis mit Aschenwind entscheiden würde. Er schien recht entschlossen.', '', 28153),
(154526, 'deDE', '', 'Was sagt Ihr, $n? Seid Ihr bereit, Euch einem neuen Verbündeten zuzuwenden?', 28153),
(154525, 'deDE', '', 'Die Orcs der Mag\'har sind für ihre Kampfkünste berühmt. Derart furchtlose Soldaten werde ich gebrauchen können.', 28153),
(154524, 'deDE', '', 'Ein Heer kriegslüsterner Orcs aus einer anderen Welt? Ausgebildete Soldaten... Waffen, die nur darauf warten, auf die Allianz gerichtet zu werden. Interessant...', 28153),
(154523, 'deDE', 'Dieser Champion hat sich mit der Rettung Draenors vor Garrosh und der Brennenden Legion das Vertrauen der Orcs dort verdient. Sie stehen in der Schuld der Horde und diese Schuld sollten wir einfordern.', '', 28153),
(154522, 'deDE', 'Kriegshäuptling, vor Jahren verfolgte die Horde den Flüchtigen Garrosh Höllschrei in ein Echo des Draenors, das ich kannte.', '', 28153),
(154521, 'deDE', 'Wir lehnen das Angebot von Aschenwind & Co. ab. Hier sind die Befehle des Kapitäns.', 'Wir lehnen das Angebot von Aschenwind & Co. ab. Hier sind die Befehle des Kapitäns.', 28153),
(154520, 'deDE', 'Ihr seid wirklich nett gekleidet. Benötigt Ihr irgendetwas?', '', 28153),
(154519, 'deDE', 'Trinkt aus, Leute. Ihr seht so ausgetrocknet aus... Ha!', 'Trinkt aus, Leute. Ihr seht so ausgetrocknet aus... Ha!', 28153),
(154518, 'deDE', 'Zerbrechen', 'Zerbrechen', 28153),
(154516, 'deDE', 'Ihr gehört nicht zu meinen Schülern. Ihr habt hoffentlich einen guten Grund, warum Ihr meinen Unterricht stört.', 'Ihr gehört nicht zu meinen Schülern. Ihr habt hoffentlich einen guten Grund, warum Ihr meinen Unterricht stört.', 28153),
(154515, 'deDE', '<Drees scheint auf Eure Anwesenheit nicht zu reagieren.>', '<Drees scheint auf Eure Anwesenheit nicht zu reagieren.>', 28153),
(154514, 'deDE', 'Es ist unhöflich, zu stören, Fremdling.', 'Es ist unhöflich, zu stören, Fremdling.', 28153),
(154513, 'deDE', 'Auf den ersten Blick sehe ich nichts, das mir sagt, wo meine Gnomenfreunde hingegangen sind. Lasst mich die Informationen, die Ihr gesammelt habt, ansehen und wenn ich etwas Interessantes finde, setze ich mich wieder mit Euch in Verbindung.', '', 28153),
(154512, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf ins Sturmsangtal!', '|cFF0000FF(Quest)|r Setzt die Segel, auf ins Sturmsangtal!', 28153),
(154511, 'deDE', 'Warnung! Warnung! Eindringling! Alarm! Eindringling! Alarm!', '', 28153),
(154510, 'deDE', '', 'Nehmt dieses Geschenk... die traditionelle Rüstung unseres Volkes. Tragt sie mit Stolz als Erinnerung an unsere Heimat. Dranosh\'ek mag\'har!', 28153),
(154509, 'deDE', '', 'Mit der Verteidigung der Horde gegen ihre Feinde habt Ihr die Mag\'har geehrt.', 28153),
(154508, 'deDE', '', 'Kehrt nach Orgrimmar zurück, damit ich Eure Hingabe würdigen kann.', 28153),
(154507, 'deDE', '', 'Ihr habt zahllose Schlachten in ganz Azeroth geschlagen. Ihr habt sowohl unseren Verbündeten als auch unseren Feinden gezeigt, wer die Mag\'har sind.', 28153),
(154506, 'deDE', '', 'Egal, wohin Euch die Reise führt, vergesst nie, dass das Herz von Draenor in Euch schlägt. Lok-tar ogar!', 28153),
(154505, 'deDE', '', 'Mit jedem Sieg werdet Ihr den Völkern von Azeroth zeigen, dass wir Meister des Krieges sind.', 28153),
(154504, 'deDE', '', 'Jetzt benötigt die Horde unsere Stärke gegen die Allianz. Und wir folgen ihrem Ruf.', 28153),
(154503, 'deDE', '', 'Unser Volk stand vereint unter der Führung von Grommash Höllschrei. EIN Stamm: die Mag\'har.', 28153),
(154502, 'deDE', '', 'Vor vielen Jahren reisten die Helden dieser Welt nach Draenor und kämpften gemeinsam mit uns gegen die Brennende Legion.', 28153),
(154501, 'deDE', '', 'Mein geschätzter Rokhan, die Dunkelspeere hab\'n sich die Hilfe der Zandalari mehr als verdient. Ich komm\' mit und unterstütz\' Euch.', 28153),
(154500, 'deDE', 'Ich muss mir den Champion ma\' kurz ausleih\'n. \'n alter Feind is\' Bwonsamdi irgendwie entkomm\' un\' bedroht jetz\' meine Heimat.', '', 28153),
(154499, 'deDE', 'Ich bin bereit. Beginnt mit dem Ritual.', 'Ich bin bereit. Beginnt mit dem Ritual.', 28153),
(154498, 'deDE', '', 'Irgendjemand hier muss etwas wissen. Eine ganze Flotte geht nicht einfach verloren!', 28153),
(154497, 'deDE', 'Stattdessen sollen wir... unseren Hafen für die Horde freigeben?', '', 28153),
(154496, 'deDE', 'Wir sollen uns nicht in die Hände der Aschenwind begeben...', '', 28153),
(154495, 'deDE', 'Und ich soll Euch glauben, $R? Her damit.', '', 28153),
(154494, 'deDE', 'Hier sind die Befehle des Kapitäns. Er hat sich gegen ein Bündnis mit Aschenwind & Co. entschieden.', 'Hier sind die Befehle des Kapitäns. Er hat sich gegen ein Bündnis mit Aschenwind & Co. entschieden.', 28153),
(154493, 'deDE', 'Wo genau kommt Ihr noch mal her? Ihr seid ganz sicher nicht von hier.', '', 28153),
(154492, 'deDE', '', 'Was? Zeigt mal her.', 28153),
(154491, 'deDE', 'Wir haben ein paar neue Befehle vom Kapitän für Euch, Bootsfrau.', 'Wir haben ein paar neue Befehle vom Kapitän für Euch, Bootsfrau.', 28153),
(154490, 'deDE', '', 'Nicht nur, um die Flotte heimzuholen, sondern um Kul Tiras zu heilen... von der \"Infektion\", wie Carsten sagen würde.', 28153),
(154489, 'deDE', '', 'Wer seid Ihr? Und was genau wollt Ihr?', 28153),
(154488, 'deDE', '', 'Außerdem segnen sie jedes einzelne Schiff von Kul Tiras. Das unterscheidet unsere Schiffe deutlich von denen unserer Besucher.', 28153),
(154487, 'deDE', '', 'Ich habe nie derartige Mengen Azerit an einem Ort gesehen. Das ist so erfreulich wie besorgniserregend.', 28153),
(154486, 'deDE', '', 'Ein Elementar... aus reinem Azerit. Bezwingt ihn, Champion, aber zerstört ihn nicht. Wir brauchen das Azerit.', 28153),
(154485, 'deDE', '', 'Das sollte sie sättigen... zumindest vorerst.', 28153),
(154484, 'deDE', '', 'Orcs sind tapfere Soldaten, aber jeder von ihnen isst so viel wie zehn Goblins! Wir brauchen neue Vorräte. Es stört Euch sicher nicht, etwas Wild zu töten, während Ihr die Kaldorei niederstreckt, oder?', 28153),
(154483, 'deDE', '', 'Kappt den Stiel, bevor der Rose Dornen wachsen, sage ich immer.', 28153),
(154482, 'deDE', '', 'Noch eine Kaldoreikommandantin zur falschen Zeit am falschen Ort. Streckt sie nieder, wir können ihr nicht erlauben, Verstärkung zu sammeln.', 28153),
(154481, 'deDE', '', 'Ihr wart der richtige Pfeil für diesen Schuss, Champion.', 28153),
(154480, 'deDE', '', 'Saurfang hat die Berge zwischen der Dunkelküste und dem Teufelswald überwunden. Trefft Euch mit ihm im Splitterspeertal und sichert seinen Vorstoß.', 28153),
(154479, 'deDE', 'Wir ham\'s geschafft, Leute. Pirat\'nkönig Zem\'lan is\' erstma\' tot un\' der Schatz gehört uns.', '', 28153),
(154478, 'deDE', '', 'Ich habe keine Sekunde an Euch gezweifelt.', 28153),
(154477, 'deDE', '', 'Die Kaldorei scheinen Verstärkung bekommen zu haben. Das könnte eine Herausforderung darstellen. Ich erwarte einen Sieg.', 28153),
(154476, 'deDE', '', 'Ihr kämpft mit List und Eifer. Eure Taten sind ein Ansporn für all meine Soldaten, Champion.', 28153),
(154475, 'deDE', '', 'Die Allianz durchkämmt die Dunkelküste, um unsere Stellungen auszumerzen. Wir dürfen nicht weichen! Verteidigt unseren Boden!', 28153),
(154474, 'deDE', '', 'Im Krieg heißt es töten oder getötet werden. Mehr gibt es dazu nicht zu sagen.', 28153),
(154473, 'deDE', '', 'Zeigt keine Gnade! Von diesen barbarischen Elfen könnt Ihr auch keine erwarten.', 28153),
(154472, 'deDE', '', 'Wir haben ihren Reserven einen erheblichen Schlag versetzt, Champion. Gute Arbeit.', 28153),
(154471, 'deDE', '', 'Wenn es dunkel wird, sind die Kaldorei am tödlichsten. Stürzt Euch auf sie, bevor die Nacht anbricht!', 28153),
(154470, 'deDE', '', 'Mein Vertrauen in Euch macht sich bezahlt. Der Wille der Kaldorei ist bald gebrochen.', 28153),
(154469, 'deDE', '', 'Malfurions Soldaten sind unserer Armee auf den Fersen! Wir müssen weiter in die Dunkelküste vordringen, solange wir im Vorteil sind!', 28153),
(154468, 'deDE', '', 'Armes Ding... sie hat ja kaum ausholen können.', 28153),
(154467, 'deDE', '', 'Diese Nachtelfenkommandantin stellt meine Geduld auf die Probe. Brecht sie.', 28153),
(154466, 'deDE', '', 'Sie schlafen für tausende von Jahren, nur um für ihren Untergang zu erwachen. Erbärmlich!', 28153),
(154465, 'deDE', '', 'Ah, die Urtume kommen also raus zum Spielen, was? Sorgen wir für ein böses Erwachen.', 28153),
(154464, 'deDE', 'Ich denke, das hätte schlimmer enden können. Sorgt dafür, dass seine Überreste nicht in die Hände der Horde fallen.', '', 28153),
(154463, 'deDE', '', 'Ein Elementar aus reinem Azerit! Ich weiß nicht, wie groß diese Bedrohung ist, Champion... aber bitte seid vorsichtig.', 28153),
(154462, 'deDE', 'Die Nachtelfen werden sich widersetzen, wie sie nur können.', 'Die Nachtelfen werden sich widersetzen, wie sie nur können.', 28153),
(154461, 'deDE', '', 'Habt Ihr je eine Azeritbombe benutzt? Nein? Wollt Ihr einmal wahre Macht erleben? Haltet Euch gut fest, Champion. Ich denke, Ihr werdet positiv überrascht sein.', 28153),
(154460, 'deDE', 'Was für ein Prachtexemplar! Für dieses Wesen finden sich mit Sicherheit die verschiedensten alchemistischen Anwendungen.', '', 28153),
(154459, 'deDE', 'Das ist immer ein kleiner Schock für neue Kadetten. Keine Sorge, das bildet den Charakter!', '', 28153),
(154458, 'deDE', '', 'Die Kaldorei werden der Besetzung trotzen... es sei denn, wir brechen ihren Willen.\n\nWir müssen ein Exempel statuieren, damit sie erkennen, was auf dem Spiel steht. Sie müssen etwas... jemanden... verlieren, der ihr vollstes Vertrauen genießt. Ein Symbol der Hoffnung.\n\n<Die Augen der Dunklen Fürstin verengen sich.> \n\nMalfurion Sturmgrimm muss sterben.', 28153),
(154457, 'deDE', 'Angler berichten von einem seltsamen großen Wesen im Wasser. Es wäre von immensem Wert, wenn ich eine Probe davon untersuchen könnte.', '', 28153),
(154456, 'deDE', '', 'Die Allianz bringt Belagerungswaffen gegen uns in Stellung? Goldig. Zeigt ihnen, wozu die Horde fähig ist.', 28153),
(154455, 'deDE', 'Eisen ist gerade knapp. Selbst beim Training können wir keine Munition verschwenden. Unsere Marinesoldaten wissen aber, wie wir sie zurückbekommen.', '', 28153),
(154454, 'deDE', '', 'Diese Ruinen bergen Unmengen natürlicher Ressourcen... wir müssen nur zugreifen! Lasst nicht zu, dass die Kaldorei uns im Weg stehen.', 28153),
(154453, 'deDE', '', 'Unter unseren Truppen sind ein paar Windreiter. Nehmt Euch unseren Sprengstoff und zerschmettert diese Irrwischbarriere. Schicken wir Malfurion eine Botschaft.', 28153),
(154452, 'deDE', '', 'Gut geschossen, Champion! Aber wer immer die Kanonenkugeln einsammeln muss, kann einem leidtun.', 28153),
(154451, 'deDE', 'Eine Schamanin der Venture Company kontrolliert Elementare voller Azerit! Diese kleinen grünen Langfinger verdienen solche Macht nicht! Weg mit ihr!', '', 28153),
(154450, 'deDE', '', 'Das hört sich nach Schießübungen auf dem Trainingsgelände an. Ich wette, Ihr könntet den anderen Kadetten das eine oder andere über den Umgang mit Kanonen beibringen.', 28153),
(154449, 'deDE', '', 'Die Waffen, die Ihr gesichert habt, werden sich in unserem Krieg als nützlich erweisen. Gute Arbeit.', 28153),
(154448, 'deDE', '', 'So oder so brauchen wir die Hilfe der Gezeitenweisen... jetzt mehr als je zuvor.', 28153),
(154447, 'deDE', 'Nicht übel! Ihr habt hier wohl so einige Geldbörsen traurig gemacht. Zum Beispiel meine...', '', 28153),
(154446, 'deDE', '', 'Derzeit scheint keiner zu wissen, warum die Flotte noch nicht zurück ist.', 28153),
(154445, 'deDE', '', 'Man sagt, die Gezeitenweisen hätten ihre Magie verloren, aber ich glaube, das sind nur Ränkespiele, wie bei Aschenwind.', 28153),
(154444, 'deDE', '', 'Diese Fracht gehört der Horde! Lasst nicht zu, dass sie der Allianz in der Hände fällt.', 28153),
(154443, 'deDE', 'Ein paar Schwertwasserkorsaren halten hier manchmal Duellturniere für Piraten ab und bei den Teilnehmern sind sie nicht wählerisch.', '', 28153),
(154442, 'deDE', '', 'Trotz ihres Elitetrainings haben sich diese Dunklen Waldläuferinnen bei ihre Angriffen wohl verkalkuliert. Vielleicht sollte Pestrufer sich ihrer annehmen...', 28153),
(154441, 'deDE', '', 'An Bord unserer größten Schiffe ist immer ein Gezeitenweiser, um durch Sturm und raue See zu navigieren und die Segel zu füllen.', 28153),
(154440, 'deDE', '', 'Meine Dunklen Waldläuferinnen brauchen Eure Unterstützung. Helft so vielen, wie Ihr finden könnt!', 28153),
(154439, 'deDE', '', 'Eure Dienste werden andernorts verlangt, Champion. Ich habe einen Trupp Goblins beauftragt, den Rest zu suchen.', 28153),
(154438, 'deDE', 'So ein Blödsinn... das Lebensblut eines Planeten an \'nen Oger zu verfüttern, damit er schlauer wird. Das kann nicht funktionieren... oder? Räumt ihn vorsichtshalber aus dem Weg.', '', 28153),
(154437, 'deDE', 'Erstaunlich! Diese Fotos sind ein spektakulärer Blickfang!', '', 28153),
(154436, 'deDE', '', 'Azeritpulverfässer sind von unseren Schiffen geschleudert worden! Sammelt sie ein, sie dürfen nicht versinken!', 28153),
(154435, 'deDE', 'Die Schnappschüsse, die Ihr mir gemacht habt, sind mir schon ausgegangen. Falls Ihr ein wenig Zeit habt, könnte ich immer ein paar Fotos gebrauchen.', '', 28153),
(154434, 'deDE', '', 'Unser Lager ist vorerst sicher, aber bleibt wachsam.', 28153),
(154433, 'deDE', 'Der oberste Waffenentwickler der Venture Company ist hier! Endlich haben wir ihn. Verpasst ihm \'ne ordentliche Tracht Prügel von mir!', '', 28153),
(154432, 'deDE', '', 'Ich wünschte, Ihr könntet die Flotte sehen. Ich glaube, selbst jemand, der so viel gesehen hat wie Ihr, wäre erstaunt!', 28153),
(154431, 'deDE', 'Ah, Boralus! Die illustre Stadt der Gassengangs und zankenden Adligen. Solche Probleme hatte Gnomeregan nie.', '', 28153),
(154430, 'deDE', 'Ich habe beschlossen, auch mit ein paar der hiesigen Sehenswürdigkeiten für mein Resort zu werben. Die Stadt ist ein guter Anfang.', '', 28153),
(154429, 'deDE', '', 'Saboteure der Allianz haben unsere Stellung infiltriert! Scheucht sie auf! Lasst sie bluten!', 28153),
(154428, 'deDE', '', 'Wie auch immer. Zeit, Eure Fähre zu erwischen!', 28153),
(154427, 'deDE', 'Mein oberster Waffenentwickler hat sich von der Venture Company abwerben lassen. Ich kann ihm nicht mal böse sein, er hat \'ne Menge Kohle dafür bekommen. Nur zu Schade, dass Ihr ihn jetzt für mich töten werdet.', '', 28153),
(154426, 'deDE', 'Wunderschön! Wisst Ihr, das Beste an Fotos ist, dass man die Pferde nicht riechen kann.', '', 28153),
(154425, 'deDE', 'Lord Norwinsen wünscht, dass sein malerisches Anwesen in der nächsten Zischfederbroschüre einen prominenten Platz einnimmt. Da sage ich natürlich nicht nein.', '', 28153),
(154424, 'deDE', 'Die Venture Company stopft ihre Oger voll mit Azerit, das macht sie angeblich schlauer. So ein Humbug, aber trotzdem... könnt Ihr Euch darum kümmern? Nur zur Sicherheit.', '', 28153),
(154423, 'deDE', '', 'Die Mondbrunnenessenz sollte Euch im Kampf dienlich sein. Erschöpft auch die anderen Brunnen, die die Kaldorei noch weihen.', 28153),
(154422, 'deDE', '', 'Die Kaldorei nutzen Mondbrunnen, um sich in der Schlacht zu stärken. Entzieht diesen Brunnen, so viel Ihr wollt... dann macht sie unbrauchbar. Verstanden?', 28153),
(154421, 'deDE', 'Ihr seid gerade noch rechtzeitig eingeschritten! Noch ein bisschen mehr und mein Ruf in der Hotellerie wäre ruiniert gewesen.', '', 28153),
(154420, 'deDE', 'Seid vorsichtig da draußen, Taelia. Ich traue diesen Kapuzenpredigern kein Stück.', '', 28153),
(154419, 'deDE', 'Man munkelt, dass die Venture Company es hingekriegt hat, Elementare aus purem Azerit zu zähmen. Wir müssen sie aufhalten. Und wenn ich \"wir\" sage, meine ich \"Euch\".', '', 28153),
(154418, 'deDE', '', 'Ich weise unsere Verzauberer an, diese Mondsteine mit Azerit zu verstärken. Ihre Macht dient jetzt der Horde!', 28153),
(154417, 'deDE', '', 'Die Kaldorei schöpfen ihre Macht aus Mondsteinanhängern. Tut, was nötig ist, um ihnen diese Schmuckstücke zu entreißen.', 28153),
(154416, 'deDE', '', 'Sehr gut, Champion. Ich lasse das Azerit zu unserem Bestand bringen.', 28153),
(154415, 'deDE', '', 'In den Ruinen der Dunkelküste dringt Azerit an die Oberfläche. Wir dürfen der Allianz keinen einzigen Splitter davon überlassen!', 28153),
(154414, 'deDE', '', 'Das ist genau die Botschaft, die ich Malfurion schicken will. Ausgezeichnete Arbeit.', 28153),
(154413, 'deDE', '', 'Diese Irrwische sind nur Insekten, die darauf warten, zerquetscht zu werden. Löscht sie aus, Licht um Licht, bis der Himmel in Dunkelheit versinkt.', 28153),
(154412, 'deDE', 'Es ist eine Katastrophe! Die Quellen sind außer Rand und Band! Sie greifen meine Gäste an!', '', 28153),
(154411, 'deDE', '', 'Narr\'n! G\'hunn kann nich\' versag\'n. Eure Macht is\' nutzlos.', 28153),
(154410, 'deDE', '', 'Unsere Köche sollten daraus etwas Gutes zaubern können. Danke sehr.', 28153),
(154409, 'deDE', '', 'Meine Druidenfreunde haben für gewöhnlich einen, nun ja, Bärenhunger. Und irgendwer muss unsere Speisekammer füllen. Habt Ihr das Zeug dazu?', 28153),
(154408, 'deDE', 'Tut mal was für Euer Geld! Feuer frei!', '', 28153),
(154407, 'deDE', 'Ha ha! Lustig.', 'Ha ha! Lustig.', 28153),
(154406, 'deDE', 'Wie unhöflich.', 'Wie unhöflich.', 28153),
(154405, 'deDE', 'Warum macht Ihr sowas?', 'Warum macht Ihr sowas?', 28153),
(154404, 'deDE', 'Im Namen aller Loa, was soll das denn werd\'n?', 'Im Namen aller Loa, was soll das denn werd\'n?', 28153),
(154403, 'deDE', 'Lasst das!', 'Lasst das!', 28153),
(154402, 'deDE', 'Aus dem Weg! Hier kommt die Kavallerie.', '', 28153),
(154401, 'deDE', 'Da is\' das achte Stück. Das gibt \'ne ganze Münze, Zastamann!', '', 28153),
(154400, 'deDE', 'Piraten teil\'n ihre Münzen oft in acht Stücke auf. Soll Glück bring\'n, alle acht einzusammeln! In Freihafen müsst\'n genug Schätze rumlieg\'n.', '', 28153),
(154399, 'deDE', 'Das Vieh hat \'ne masochistische Ader. Also, wer hat Lust auf Wackelpudding? Har har.', '', 28153),
(154398, 'deDE', 'Eine Riesengaleere is\' in den Gewässern von Freihafen zu Hause. Egal, wie viele Harpun\'n das Ding abkriegt, es kommt immer wieder.', '', 28153),
(154397, 'deDE', 'Ihr habt Vandegrimm umgelegt, jetz\' hat seine Seele Ruhe. Denkt an all die Schätze, die Ihr vom Fluch befreit habt!', '', 28153),
(154396, 'deDE', 'Schreckenskapitän Vandegrimm war hier entlang der ganz\'n Küste gefürchtet. Gerücht\'n zufolge treibt ihn seine Gier ausm Grab, um noch immer weiter zu plündern.', '', 28153),
(154395, 'deDE', 'Iggksh ywaq ag\'rr ni ky!', '', 28153),
(154394, 'deDE', 'Ah\'shel ywaq qam yrr woth\'gl!', '', 28153),
(154393, 'deDE', 'Da ist das achte Stück. Das gibt \'ne ganze Münze! Wir sind reich!', '', 28153),
(154392, 'deDE', 'Za ag\'rr wgah thyzz zuq!', '', 28153),
(154391, 'deDE', 'Piraten teilen ihre Münzen oft in acht Stücke auf. Soll Glück bringen, alle acht zu sammeln! In Freihafen müssten genug Schätze rumliegen.', '', 28153),
(154390, 'deDE', 'Das Vieh hat eine masochistische Ader. Also, wer hat Lust auf Wackelpudding?', '', 28153),
(154389, 'deDE', 'Eine riesige Qualle treibt sich in den Gewässern von Freihafen rum. Egal, wie viele Harpunen wir dem Ding verpassen, es kommt immer wieder.', '', 28153),
(154388, 'deDE', 'Ga ag\'rr ez AN\'zig wgha kyth zuq!', '', 28153),
(154387, 'deDE', 'Ihr habt Vandegrimm getötet, jetzt hat seine Seele Ruhe. Denkt an all die Schätze, die Ihr vom Fluch befreit habt!', '', 28153),
(154386, 'deDE', 'Schreckenskapitän Vandegrimm war entlang der gesamten Küste gefürchtet. Es heißt, seine Gier war so groß, dass er selbst nach dem Tode dort weiterplündert.', '', 28153),
(154385, 'deDE', 'Wartet... Das is\' nich\' die Zukunft, die ich geseh\'n hab\'...', '', 28153),
(154384, 'deDE', 'G\'huuns Blut fließt in meinen Venen! Erzittert vor meiner Macht!', '', 28153),
(154383, 'deDE', 'Was ich alles mit ansehen musste...', 'Derartige Freundlichkeit hätte ich nicht erwartet.', 28153),
(154382, 'deDE', 'Meine Macht wird Euch brech\'n!', '', 28153),
(154381, 'deDE', 'Danke! Ich hätte nicht viel länger durchgehalten!', 'Danke. Das werde ich nicht vermissen.', 28153),
(154380, 'deDE', 'Die Macht von G\'huun is\' Euer Untergang!', '', 28153),
(154379, 'deDE', 'Seht Euer Ende und verzweifelt!', '', 28153),
(154378, 'deDE', 'Erhebt Euch, meine Auserwählten! Durch Blut werd\'n wir sieg\'n!', '', 28153),
(154377, 'deDE', 'Erhebt Euch aus meinem Blut und zerschmettert die Schwachen!', '', 28153),
(154376, 'deDE', 'Kommt, Brüder! Labt Euch an den Untreuen.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'deDE', 'Gebt mir Euer Blut!', '', 28153),
(154374, 'deDE', 'G\'huun! Nehmt dieses Blutopfer!', '', 28153),
(154373, 'deDE', 'Ihr hattet nie eine Zukunft.', '', 28153),
(154372, 'deDE', 'Schwach. Genau wie vorhergeseh\'n.', '', 28153),
(154371, 'deDE', 'Alles is\' so, wie ich\'s vorhergeseh\'n hab\'.', '', 28153),
(154370, 'deDE', 'Kommt nur, Ihr Narren! Ich hab Euer Ende vorhergeseh\'n!', '', 28153),
(154369, 'deDE', 'Meine Mutter is\' gestorb\'n, als ich noch sehr jung war, also wurd ich von meinem Vater aufgezog\'n. Der war Matrose und hat mir immer \'n Meeresstängel hinterlass\'n, wenn er zur See gefahr\'n is\'.', 'Meine Mutter is\' gestorb\'n, als ich noch sehr jung war, also wurd ich von meinem Vater aufgezog\'n. Der war Matrose und hat mir immer \'n Meeresstängel hinterlass\'n, wenn er zur See gefahr\'n is\'.', 28153),
(154368, 'deDE', '', 'Alarm. Dunkle Projektion wird geladen.', 28153),
(154367, 'deDE', '', 'Alarm. Sicherheitssysteme für Leerenquarantäne versagen.', 28153),
(154366, 'deDE', '', 'Das war höchst nobel von Euch, Champion.', 28153),
(154365, 'deDE', '', 'Alarm. Unsichere Mengen an Leerenenergie entdeckt.', 28153),
(154363, 'deDE', '', 'Warnung. Zusätzliche Neruber werden repliziert.', 28153),
(154362, 'deDE', 'Das Gleichgewicht ist wiederhergestellt. Anu\'dorini talah!', '', 28153),
(154361, 'deDE', 'Dieser Feind wandelt in den Schatten, aber niemand kann sich Elunes geweihtem Mondlicht entziehen. Kümmert Euch darum.', '', 28153),
(154360, 'deDE', '', 'Warnung. Zusätzliche Silithiden werden repliziert.', 28153),
(154359, 'deDE', 'Pah! Verfluchte Dinger! Für mich sin\' Meeresstängel nur \'n Symbol dafür, dass gute Matrosen nich\' zurückkehr\'n und ihre Fracht aufm Meeresboden gelandet is\'.', 'Pah! Verfluchte Dinger! Für mich sin\' Meeresstängel nur \'n Symbol dafür, dass gute Matrosen nich\' zurückkehr\'n und ihre Fracht aufm Meeresboden gelandet is\'.', 28153),
(154358, 'deDE', '', 'Mythrax hat auf dieser Welt nichts verloren.', 28153),
(154357, 'deDE', '', 'Elune segne Euch, Champion. Ihr leuchtet mit der Kraft eines Sterns.', 28153),
(154356, 'deDE', '', 'Meine Bogenschützen könnten Eure Hilfe gebrauchen, Champion. Helft Ihnen doch, wenn Ihr sie findet.', 28153),
(154355, 'deDE', '', 'Dieser Krieg muss ein Ende finden.', 28153),
(154354, 'deDE', '', 'Ich werde über Euch wachen.', 28153),
(154353, 'deDE', '', 'Ladevorgang abgeschlossen. Datenscheibe wird heruntergefahren.', 28153),
(154352, 'deDE', '', 'Ihr habt die Bedrohung ausgeschaltet UND meine Belagerungswaffe heil zurückgebracht? Dafür bekommt Ihr ein Fleißsternchen.', 28153),
(154351, 'deDE', '', 'Die Ordnung muss wiederhergestellt werden.', 28153),
(154350, 'deDE', '', 'Wir alle haben unseren Platz. Meiner ist hier.', 28153),
(154349, 'deDE', '', 'Ich bin geschwächt, doch ich bin hier.', 28153),
(154348, 'deDE', '', 'Habt Ihr so etwas schon einmal benutzt? Macht Euch auf eine Überraschung gefasst.', 28153),
(154347, 'deDE', '', 'Greife auf Datenscheibe zu. Korrumpierte Daten werden geladen.', 28153),
(154346, 'deDE', 'Ich entsende so viele Soldaten wie möglich dort hin. Hoffentlich können wir ihren Angriff abwehren. Einen Krieg an zwei Fronten können wir nicht überstehen.', '', 28153),
(154345, 'deDE', 'Ich spüre Unruhe im Norden. Ist das möglich? Greift die Horde uns von jenseits der Berge an? Untersucht das schnellstmöglich!', '', 28153),
(154344, 'deDE', '', 'Ihr seht etwas angesengt aus, Champion. Ist nicht alles nach Plan verlaufen?', 28153),
(154343, 'deDE', '', 'Selbst unter Wasser sind diese Azeritpulverfässer noch ziemlich gefährlich. Ich möchte, dass Ihr sie hochjagt, bevor sie an die Oberfläche treiben. Versucht bitte, dabei nicht draufzugehen, ja?', 28153),
(154342, 'deDE', '', 'Überladung der Datenmatrix. Zugriff auf mehrere Scheiben.', 28153),
(154341, 'deDE', 'Meeresstängel, was? \'n paar meiner Matrosenkumpanen lass\'n immer einen bei ihrer bessren Hälfte, wenn wir aufbrech\'n. Kann man ihn\' nich\' verdenk\'n. Sie woll\'n nich\', dass ihre Familien sich mit Gedanken quäl\'n, was ihn\' wohl passiert is\'.', 'Meeresstängel, was? \'n paar meiner Matrosenkumpanen lass\'n immer einen bei ihrer bessren Hälfte, wenn wir aufbrech\'n. Kann man ihn\' nich\' verdenk\'n. Sie woll\'n nich\', dass ihre Familien sich mit Gedanken quäl\'n, was ihn\' wohl passiert is\'.', 28153),
(154340, 'deDE', '', 'Ich habe keine Sekunde an Euch gezweifelt.', 28153),
(154339, 'deDE', '', 'Die Horde ist in großer Zahl angerückt. Unterschätzen sollte man wirklich keinen von ihnen. Dieser eine scheint ganz besonders... standhaft. Nähert ihm Euch vorsichtig, Champion.', 28153),
(154338, 'deDE', '', 'Greife auf Datenscheibe zu. Yogg-Sarons Daten werden geladen.', 28153),
(154337, 'deDE', '', 'Greife auf Datenscheibe zu. C\'thuns Daten werden geladen.', 28153),
(154335, 'deDE', '', 'Saboteure der Horde haben sich in unsere Reihen eingeschlichen. Spürt sie auf und lasst sie bluten!', 28153),
(154334, 'deDE', '', 'Ich muss schon sagen... Ihr erstaunt, Champion. Selbst die Schildwachen können von Euch noch einiges lernen.', 28153),
(154333, 'deDE', '', 'Es wird Zeit, Feuer mit Feuer zu bekämpfen. Wir müssen die Verwüster der Horde loswerden und ihre Krieger zurück ins Brachland drängen, wo sie hingehören.', 28153),
(154332, 'deDE', '', 'Ihr zaubert ein Lächeln auf Elunes Gesicht... und auf das meinige.', 28153),
(154331, 'deDE', '', 'Die Horde versucht, die Essenz unserer Mondbrunnen zu stehlen. Lasst nicht zu, dass ihr Dreck unsere gesegneten Quellen entweiht.', 28153),
(154330, 'deDE', '', 'Überlasst diesen Wilden von der Horde ihr Brachland. Wir werden sie lehren, sich von den Wäldern fernzuhalten.', 28153),
(154329, 'deDE', '', 'Die Horde hat außerhalb des Eschentals Fuß gefasst. Ruft die Druiden zusammen, die über den Wald wachen!', 28153),
(154328, 'deDE', '', 'Gut gekämpft, Champion, und so leidenschaftlich...', 28153),
(154327, 'deDE', '', 'Hordesoldaten stehlen Ressourcen von unserem Land! Haltet sie auf, bevor sie unseren heiligen Wald zerstören.', 28153),
(154326, 'deDE', '', 'Jahrtausende tot und kein bisschen eingerostet. Gut gekämpft gegen so \'n Gegner!', 28153),
(154325, 'deDE', '', 'Das... das is\' die erste Garde von König Dazar! Das wird \'n schwerer Kampf!', 28153),
(154324, 'deDE', 'Ha, sieht so aus, als hättet Ihr diese Untoten un-untot gemacht. Gute Arbeit.', '', 28153),
(154323, 'deDE', 'Diese untoten Trolle sehen zäher aus als der Rest. Passt auf!', '', 28153),
(154322, 'deDE', 'Was könnt Ihr mir über Meeresstängel erzählen?', 'Was könnt Ihr mir über Meeresstängel erzählen?', 28153),
(154321, 'deDE', '', 'Das sollte genügen, Champion. Euer Beitrag am heutigen Tag wird nicht vergessen werden.', 28153),
(154320, 'deDE', '', 'Die Horde verfügt bereits über Azeritwaffen. Schauen wir doch mal, ob wir die nicht beschlagnahmen können.', 28153),
(154319, 'deDE', '... das mit den Hallen des Steins zählt nicht.', '', 28153),
(154318, 'deDE', 'Tsäh, ein Zwergenkonstrukt wäre niemals so durchgedreht.', '', 28153),
(154317, 'deDE', '', 'Ausgezeichnete Arbeit! Meine Alchemisten werden das Azerit irgendwo verwahren, wo die Horde nicht ran kommt.', 28153),
(154316, 'deDE', 'Pah, typisch Troll und Pfuscharbeit. Der Golem ist durchgedreht. Zeigt Ihm, wo es langgeht!', '', 28153),
(154315, 'deDE', '', 'Wir müss\'n Julwaba vor Jakra\'zet finden.', 28153),
(154314, 'deDE', '', 'Zuls dunkle Magie hat diesen Wächter verderbt. Haltet ihn auf, damit wir ihn reparier\'n könn\'.', 28153),
(154313, 'deDE', '', 'Zul... was Ihr aus diesem heilig\'n Ort gemacht habt, is\' unverzeihlich.', 28153),
(154312, 'deDE', '', 'Ruht in Fried\'n, Halu.', 28153),
(154311, 'deDE', '', 'Ahh, Waffenmeister Halu... er hat mein\' Vater ausgebildet und davor bereits sein\' Vater. Sein Dienst is\' vorbei. Gewährt seinem gestört\'n Geist Ruhe.', 28153),
(154310, 'deDE', 'Ha! Scheint, als hätte er seinen Meister gefunden.', '', 28153),
(154309, 'deDE', 'Ein Krieger, der einst das Königshaus ausgebildet hat, spukt in diesem Grab. Lasst ihn seinen Frieden finden!', '', 28153),
(154308, 'deDE', '', 'Meine Bogenschützen sollten jetzt allein damit fertig werden. Eure Anwesenheit hat einen großen Unterschied gemacht, Champion. Habt Dank!', 28153),
(154307, 'deDE', '', 'Feindliche Truppen greifen von Norden aus an. Es wird Zeit, ihnen die Stirn zu bieten, Champion.', 28153),
(154306, 'deDE', 'Lasst sie durch!', '', 28153),
(154305, 'deDE', '', 'Is\' fast geschafft. Ich kann Akundas Stimme in mei\'m Geist hör\'n.', 28153),
(154304, 'deDE', '', 'Ich werd mein Möglichstes tun, um Akundas Geist zu heil\'n, aber Ihr müsst alle Erinnerung\'n in Schach halt\'n, die sich dabei manifestier\'n könnt\'n.', 28153),
(154303, 'deDE', 'Ywaq ongg an\'qov i lal halahs nuq.', '', 28153),
(154302, 'deDE', 'Ywaq mh\'naus wgah zaix zyqtahg.', '', 28153),
(154301, 'deDE', 'Mojambo wird Euch... büß\'n lass\'n...', '', 28153),
(154300, 'deDE', '', 'Wo... wo bin ich? Was mach\' ich denn hier?', 28153),
(154299, 'deDE', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek...', '', 28153),
(154298, 'deDE', '', 'Sie sind etwas geheimnisvoll, aber genießen hohes Ansehen in Kul Tiras. Sie helfen, hier die Fischernetze zu füllen und sorgen für Regen auf den Feldern im Tal.', 28153),
(154297, 'deDE', '', 'Die meisten hier verehren die See wie andere das Licht, aber die Gezeitenweisen verbindet ein weit stärkeres Band mit dem Wasser.', 28153),
(154296, 'deDE', '', 'Ich würde Euch ja auf Sturmherz reiten lassen, aber die Gezeitenweisen gestatten Besuche nur per Boot.', 28153),
(154295, 'deDE', '', 'Keine Sorge, Carsten. Ich kann auf mich aufpassen. Außerdem ist der Allianzabgesandte bei mir!', 28153),
(154294, 'deDE', 'Oou yyqzz ez thyzz phquathi zuq!', '', 28153),
(154293, 'deDE', 'Oou gul\'kafh lal lwhuk!', '', 28153),
(154292, 'deDE', 'Qam oou iilth ez i awtgsshu amun on\'ma!', '', 28153),
(154291, 'deDE', 'Log\'loth w\'oq Ongg!', '', 28153),
(154290, 'deDE', '', 'In den Ruinen der Dunkelküste ist Azerit aufgetaucht. Es darf nicht in die Hände der Horde fallen.', 28153),
(154289, 'deDE', 'W\'oq uhn\'agth ez qam Shandai!', '', 28153),
(154288, 'deDE', 'Awtgssh shn ongg shg\'ullwaq!', '', 28153),
(154287, 'deDE', 'Zuq ag\'xig bormaz ag\'thyzak!', '', 28153),
(154286, 'deDE', 'Habt Dank!', 'Habt Dank!', 28153),
(154285, 'deDE', 'Za qualar ag\'xig za al\'tha!', '', 28153),
(154284, 'deDE', 'Dafür werde ich nicht gut genug bezahlt!', 'Dafür werde ich nicht gut genug bezahlt!', 28153),
(154283, 'deDE', 'AHHHHHHHHHHHHHHHHHHHHHHHH!', 'AHHHHHHHHHHHHHHHHHHHHHHHH!', 28153),
(154282, 'deDE', 'Danke, dass Ihr mich gerettet habt!', 'Danke, dass Ihr mich gerettet habt!', 28153),
(154281, 'deDE', 'Ich dachte, aus mir wird gleich Hackfleisch!', 'Ich dachte, aus mir wird gleich Hackfleisch!', 28153),
(154280, 'deDE', 'Oou vwahuHn ag\'xig shfk zuq!', '', 28153),
(154279, 'deDE', 'Ich danke Euch!', 'Ich danke Euch!', 28153),
(154278, 'deDE', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'deDE', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma.', '', 28153),
(154276, 'deDE', 'Za awtgsshu wgah uulg\'ma ywaq zaix.', '', 28153),
(154275, 'deDE', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr.', '', 28153),
(154274, 'deDE', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor.', '', 28153),
(154273, 'deDE', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma.', '', 28153),
(154272, 'deDE', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh.', '', 28153),
(154271, 'deDE', 'Wenn die Geister Ruhe finden, ist der Wald im Einklang. Ich danke Euch.', '', 28153),
(154270, 'deDE', 'Diese Geister sind bloße Schatten ihrer früheren Pracht. Sie brauchen Euren Beistand. Schenkt ihnen Frieden.', '', 28153),
(154269, 'deDE', 'Man nennt mich nich\' umsonst Hexfürst.', '', 28153),
(154268, 'deDE', 'Nehmt mein\' Verhexstab un\' verwandelt \'n paar von den Priestern in was Unterhaltsameres.', '', 28153),
(154267, 'deDE', 'Wenn Euch das \'n bisschen überzog\'n vorkommt, solltet Ihr ma\' seh\'n, was die andern Loa von ihr\'n Anhängern verlang\'n.', '', 28153),
(154266, 'deDE', 'Wenn wir diese Verderbnis nicht aufhalten können, wer dann?', 'Wenn wir diese Verderbnis nicht aufhalten können, wer dann?', 28153),
(154265, 'deDE', 'Gonks Druiden sin\' viel zu verklemmt. Spielt ihn\' am Altar von ihr\'m Loa \'n paar Streiche, damit die \'n bisschen lock\'rer werd\'n... Ach ja, dafür werd\'n die Euch dann aber wahrscheinlich umbring\'n woll\'n.', '', 28153),
(154264, 'deDE', 'Wenn sich das ausbreitet... ist Azeroth dem Untergang geweiht.', 'Wenn sich das ausbreitet... ist Azeroth dem Untergang geweiht.', 28153),
(154263, 'deDE', 'Die Natur schreit vor Schmerz auf... Wie halten wir diesen Wahnsinn auf?', 'Die Natur schreit vor Schmerz auf... Wie halten wir diesen Wahnsinn auf?', 28153),
(154262, 'deDE', 'Unsere Kräfte haben keine Wirkung... Wie können wir den Planeten heilen?', 'Unsere Kräfte haben keine Wirkung... Wie können wir den Planeten heilen?', 28153),
(154261, 'deDE', '', 'Was für ein Ritt! Ausgezeichnete Arbeit, Ihr beiden.', 28153),
(154260, 'deDE', '', 'Bitte verzeiht, wenn der Ritt etwas holprig wird. Unsere Feendrachen sind nicht an Zaumzeug gewöhnt. Sitzt auf und dirigiert ihren Angriff!', 28153),
(154259, 'deDE', 'Ich labe mich an Eurer Angst!', '', 28153),
(154258, 'deDE', 'Verstärkungstruppen aus Eisenschmiede, greift die feindliche Basis an!', '', 28153),
(154257, 'deDE', 'Zerschmettert Ar\'gorok. Für Arathor! Für Stromgarde! FÜR DIE ALLIANZ!', '', 28153),
(154256, 'deDE', '', 'Ihr kämpft wie die Zandalari aus den Legend\'n. Beeindruckend.', 28153),
(154255, 'deDE', '', 'Ihr beweist Euch immer wieder. Gut gekämpft.', 28153),
(154252, 'deDE', '', 'Dank Euch sin\' unsre beiden Völker wieder sicher.', 28153),
(154251, 'deDE', '', 'Der Gegner is\' aus\'m Weg, jetz\' kann\'s weitergeh\'n.', 28153),
(154246, 'deDE', '', 'Das Versteck sollte da vorne sein. Dort sind wir sicher... zumindest für eine Weile.', 28153),
(154245, 'deDE', '', 'Hoffentlich hör\'n wir von dem Feind nie wieder was.', 28153),
(154244, 'deDE', '', 'Die Loa ham Euern Sieg vorhergesagt. Ich bin froh, dass sie sich nich\' getäuscht ham.', 28153),
(154243, 'deDE', '', 'Eure Horde wird sich freu\'n, wenn sie erfährt, dass Ihr die Bedrohung abgewehrt habt.', 28153),
(154242, 'deDE', '', 'Ich wusste, dieser Widersacher kann Euch nich\' das Wasser reich\'n.', 28153),
(154240, 'deDE', 'Fühlt Ihr den Stich in Eurem Nacken? Fühlt Ihr meine Gegenwart?', '', 28153),
(154239, 'deDE', '', 'Meine Kämpfer bericht\'n, \'n mächtiger Feind in der Nähe will Euch tot seh\'n. Zeigt ihm keine Gnade.', 28153),
(154238, 'deDE', '', 'Hordekrieger bericht\'n von \'ner Bedrohung in Eurer Nähe. Schaltet sie aus, damit wir \'ne Sorge weniger ham.', 28153),
(154237, 'deDE', '', 'Eure Hordespäher ham in der Nähe \'nen schrecklichen Feind entdeckt. Sie schlag\'n vor, ihn umgeh\'nd zu töt\'n, und ich stimm ihnen zu.', 28153),
(154234, 'deDE', 'Nazmir scheint \'nen unerschöpflich\'n Vorrat von diesen Wild\'n zu haben. Danke, dass es dank Euch jetz\' weniger sin\'.', '', 28153),
(154232, 'deDE', 'Ha! Ihr seid ein Naturtalent! Ich hab schon lange niemand mehr so den Hang runterheizen sehen.', '', 28153),
(154230, 'deDE', 'Die Bluttrolle erstürm\' unsre Tore. Überrennt diese Wild\'n mit den Hörnern des Krieges!', '', 28153),
(154228, 'deDE', 'Ich hab heute nix für Euch. Die meisten Raubeine sind Rodeln gegangen, um Dampf abzulassen. Schnappt Euch \'nen Pinguling und ab auf die Piste!', '', 28153),
(154225, 'deDE', '', 'Passt auf. In Eurer Nähe lauert \'n gefährlicher Feind. Wir müss\'n ihn töt\'n, bevor er mehr Probleme macht.', 28153),
(154224, 'deDE', 'Möge Elune Euch für Euren Heldenmut segnen, Champion.', '', 28153),
(154223, 'deDE', '', 'Die Loa flüstern über \'n mächtigen Gegner in der Nähe. Sie verlang\'n, dass er vom Erdbod\'n vertilgt wird.', 28153),
(154222, 'deDE', 'Die Angriffe der Bansheekönigin sind unerbittlich. Durchkämmt die Wälder und läutert sie von ihrer dunklen Präsenz!', '', 28153),
(154221, 'deDE', '', 'Meine Späher ham in der Nähe \'nen üblen Widersacher gesichtet. Tötet ihn, bevor er zu \'ner echt\'n Gefahr wird.', 28153),
(154220, 'deDE', 'Meine Streitkräfte übernehm\' das von hier an. Danke, dass Ihr Ihn\' die Zeit verschafft habt, sich zu sammeln.', '', 28153),
(154219, 'deDE', '', 'Seid auf der Hut, ich spür hier was Unheilvolles. Kümmert Euch besser drum, bevor\'s sich um Euch kümmert!', 28153),
(154218, 'deDE', 'Die Bedrohung ist vorerst vorüber. Die Urtume können wieder zur Ruhe kommen.', '', 28153),
(154217, 'deDE', '', 'In der Nähe ist ein starker Feind. Tötet ihn, bevor unsre Verbündet\'n zu Schaden komm\'.', 28153),
(154216, 'deDE', 'Tötet alles, was kein Zandalari is\'!', '', 28153),
(154215, 'deDE', 'Die Bedrohung durch die Horde hat die Urtume erweckt. Vertreibt diese Schufte von hier, damit unser Wald wieder Ruhe findet.', '', 28153),
(154213, 'deDE', 'Eure heutigen Taten erlauben uns, Kraft zu sammeln und standzuhalten.', '', 28153),
(154212, 'deDE', 'Die Bäume dieses ehrwürdigen Waldes krümmen sich vor Qualen während die Horde weiter in unser Land eindringt. Wir müssen ihnen Einhalt gebieten!', '', 28153),
(154211, 'deDE', 'Passt auf Euch auf da draußen.', 'Passt auf Euch auf da draußen.', 28153),
(154210, 'deDE', 'Der Sand verschlingt die Schwach\'n.', 'Der Sand verschlingt die Schwach\'n.', 28153),
(154209, 'deDE', 'Vertraut niemand\'m!', 'Passt da drauß\'n ma\' auf Euch auf!', 28153),
(154208, 'deDE', 'Niemand verdient dieses Schicksal.', 'Niemand verdient dieses Schicksal.', 28153),
(154207, 'deDE', 'Was darf\'s sein?', 'Hier is\' jeder willkomm\'.', 28153),
(154205, 'deDE', 'Hey, Mann.', 'Hey, Mann.', 28153),
(154204, 'deDE', '', 'Ich kann Euch noch hören... Meister...', 28153),
(154203, 'deDE', 'Mein Flüstern zersetzt Euren Geist.', '', 28153),
(154202, 'deDE', 'Der Hunger verzehrt Euch. Labt Euch an ihrem Blut.', '', 28153),
(154201, 'deDE', 'Geht zu Euren Verbündeten. Teilt mein Geschenk mit ihnen.', '', 28153),
(154200, 'deDE', 'Ein makelloses Exemplar! Und jetzt beseitigt die verbleibenden Treulosen!', '', 28153),
(154199, 'deDE', 'Die Fäulnis fließt durch Eure Venen. Lasst sie sich ausbreiten.', '', 28153),
(154198, 'deDE', 'Entreißt den Zauberern der Treulosen eines ihrer Geräte und ladet es auf. Eure Mühen sollen reich belohnt werden.', '', 28153),
(154197, 'deDE', 'Unsere Zauberer spüren ungewöhnlich starke elektrische Ströme innerhalb des Tempels.', '', 28153),
(154196, 'deDE', 'Lasst das Festmahl der tausend Mäuler beginnen!', '', 28153),
(154195, 'deDE', 'Ausgezeichnet! Jetzt zum Herzen von Sethraliss.', '', 28153),
(154194, 'deDE', 'Bringt mir diese Relikte, und Ihr werdet reich belohnt.', '', 28153),
(154193, 'deDE', 'Kommt, Kinder, fresst!', '', 28153),
(154192, 'deDE', 'Es scheint, dass die Treulosen einige Artefakte unseres Volkes auf dem Basar vor dem Herzen des Tempels versteckt haben.', '', 28153),
(154191, 'deDE', 'Kommt, Diener der Fäulnis. Labt Euch!', '', 28153),
(154190, 'deDE', 'Ein prächtiges Exemplar! Und jetzt säubert den Tempel von diesen unseligen Treulosen!', '', 28153),
(154189, 'deDE', 'Ich habe gehört, dass eine seltene Gattung von Krolusken im Tempel nistet. Bringt mir eins ihrer Jungen und Ihr werdet belohnt.', '', 28153),
(154188, 'deDE', 'Nichts hält meine Seuche auf!', '', 28153),
(154187, 'deDE', 'Meine Verderbnis kann nicht geläutert werden!', '', 28153),
(154186, 'deDE', 'Die Titanen können Euch nicht retten!', '', 28153),
(154185, 'deDE', 'Ihr könnt der Infektion nicht entkommen!', '', 28153),
(154184, 'deDE', 'Die Siegel sind gebrochen. Das Ende ist hier. Kommt nur, Ihr werdet die ersten sein, die mein Geschenk erhalten.', '', 28153),
(154183, 'deDE', 'Die Arbeiter haben noch mal Schwein gehabt, dass Ihr zur Stelle wart! Sie lassen danken.', '', 28153),
(154182, 'deDE', 'Die Seuche... wächst in Euch...', '', 28153),
(154181, 'deDE', 'Hexen sind erneut in den Schlächterhafen eingefallen. Rettet die Arbeiter, bevor sie zu Wurst werden!', '', 28153),
(154180, 'deDE', '', 'Die Geister der Ahnen ruhen wieder und die Drust sind zerschlagen. Gut gemacht.', 28153),
(154179, 'deDE', '', 'Der endlose Kampf gefährdet die Flüchtlinge in Aroms Wehr. Dünnt die Reihen der Feinde aus!', 28153),
(154178, 'deDE', 'Entfesselt den Sturm und stürzt den Usurpator!', '', 28153),
(154177, 'deDE', 'Ihr führt meine Macht gut, $n.', '', 28153),
(154176, 'deDE', 'Mein liebes Kind, endlich könnt Ihr mich hören. In unserem Tempel ist ein Verräter.', '', 28153),
(154175, 'deDE', '', 'Eine wahrlich abscheuliche Kreatur bedroht mein Volk. Tötet sie.', 28153),
(154174, 'deDE', '', 'Die Hexen haben in dieser Gegend eine mächtige Kreatur entfesselt. Vernichtet sie!', 28153),
(154173, 'deDE', '', 'Gut gemacht! Dank Euch kann sich das Volk von Drustvar sicherer fühlen.', 28153),
(154172, 'deDE', '', 'Gut gekämpft, Inquisitor! Sie werden es sich zweimal überlegen, bevor sie nach Drustvar zurückkehren!', 28153),
(154171, 'deDE', 'Endlich frei. Ich danke Euch, $p.', '', 28153),
(154170, 'deDE', '', 'Laut den Spähern lauert ein gefährlicher Feind in der Nähe. Schaltet ihn aus!', 28153),
(154169, 'deDE', '', 'Mein Volk wird von einem mächtigen Feind in diesem Gebiet bedroht. Schaltet diese Bedrohung aus.', 28153),
(154168, 'deDE', 'Wie konnte ich nur verlieren?', '', 28153),
(154167, 'deDE', '', 'Mein Volk ist Euch zutiefst dankbar. Wir alle können heute Nacht etwas ruhiger schlafen.', 28153),
(154166, 'deDE', '', 'Die Bewohner von Drustvar danken Euch für Eure Hilfe.', 28153),
(154165, 'deDE', 'Das war nicht sehr klug.', '', 28153),
(154164, 'deDE', '', 'Uns wurde von einem Feind in diesem Gebiet berichtet. Tötet ihn.', 28153),
(154163, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|tG\'huun wirkt |cFFFF0404|Hspell:272506|h[Explosive Verderbnis]|h|r auf Euch!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|tG\'huun wirkt |cFFFF0404|Hspell:272506|h[Explosive Verderbnis]|h|r auf Euch!', 28153),
(154162, 'deDE', 'Endlich Frieden...', '', 28153),
(154161, 'deDE', '', 'Ein gefährlicher Feind bedroht die Leute von Drustvar. Kümmert Euch darum!', 28153),
(154160, 'deDE', 'Das Meer konnte mich nicht töten, wieso glaubt Ihr, dass Ihr es könnt?', '', 28153),
(154159, 'deDE', 'Ich werde mich ausbreiten und diese Welt verschlingen.', '', 28153),
(154158, 'deDE', 'Wir brauchen eine Fähre zur Sturmsangabtei.', 'Wir brauchen eine Fähre zur Sturmsangabtei.', 28153),
(154157, 'deDE', 'Eure Hülle dient nun einem neuen Meister.', '', 28153),
(154155, 'deDE', 'All die unausgesprochenen Worte...', '', 28153),
(154154, 'deDE', 'Noch kann ich kämpfen!', '', 28153),
(154153, 'deDE', 'Eure Schreie werden ewig widerhallen!', '', 28153),
(154152, 'deDE', 'Der Fluch des Fleisches verzehrt Euch!', '', 28153),
(154151, 'deDE', 'Die Infektion hat begonnen!', '', 28153),
(154150, 'deDE', '', 'Ich muss, Kaja. Die Pflicht steht über allem.', 28153),
(154149, 'deDE', '', 'Jakra\'zet is\' \'n Verräter, aber der König braucht Beweise.', 28153),
(154148, 'deDE', 'Scheint so... als könnte ich endlich ruhen...', 'Scheint so... als könnte ich endlich ruhen...', 28153),
(154147, 'deDE', 'Wir hab\'n versucht, Euch zu warnen!', 'Wir hab\'n versucht, Euch zu warnen!', 28153),
(154146, 'deDE', '', 'Geht und versucht mehr zu erfahr\'n. Ich weich nich\' von Rakeras Seite.', 28153),
(154145, 'deDE', 'Ihr seid bereit, Akundas Worte zu hör\'n, aber Ihr müsst das allein tun. Geht zum Altar und betet, sobald Ihr so weit seid.', '', 28153),
(154144, 'deDE', 'Akunda kann Euren Geist nur betret\'n, wenn er geläutert is\'.', '', 28153),
(154143, 'deDE', 'Ich möchte an diesen Ort zurückkehren.', 'Ich möchte an diesen Ort zurückkehren.', 28153),
(154142, 'deDE', 'Maximalpegel erreicht. Setze Sammlung fort.', '', 28153),
(154141, 'deDE', '<Althair betrachtet Euch freundlich.>', '<Althair betrachtet Euch freundlich.>', 28153),
(154140, 'deDE', '<Althair betrachtet Euch mit festem Blick.>', '<Althair betrachtet Euch mit festem Blick.>', 28153),
(154139, 'deDE', 'Flüssigkeit wird abgeleitet. Wechsle in Ruhemodus.', '', 28153),
(154138, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|tG\'huun beginnt, |cFFFF0404|Hspell:267700|h[G\'huuns Blick]|h|r zu wirken.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|tG\'huun beginnt, |cFFFF0404|Hspell:267700|h[G\'huuns Blick]|h|r zu wirken.', 28153),
(154133, 'deDE', 'Exemplar vorgesehen für Vernichtung.', '', 28153),
(154132, 'deDE', 'Initiiere Blutzersetzung bei Zielwirt.', '', 28153),
(154131, 'deDE', 'Aktiviere Keulenaufnahme.', '', 28153),
(154130, 'deDE', 'Aktiviere Keule.', '', 28153),
(154129, 'deDE', 'Treibstoffreserven erschöpft. Fahre herunter...', '', 28153),
(154128, 'deDE', '', 'Dranosh\'ek mag\'har!', 28153),
(154127, 'deDE', 'Versuchsobjekte bereit für Kontaminierung.', '', 28153),
(154126, 'deDE', '', 'Krieg überzieht dieses Land. <lacht> Gut so. Wir gehen im Gemetzel auf... und holen uns den Sieg!', 28153),
(154125, 'deDE', '', 'Wir sind die letzten Überlebenden eines stolzen Stammes. Die Unverderbten... die Ungebrochenen... die Mag\'har!', 28153),
(154124, 'deDE', '', 'Für andere nur Worte... aber uns bedeuten sie ALLES.', 28153),
(154123, 'deDE', '', 'Kraft und Ehre. Blut und Donner.', 28153),
(154122, 'deDE', 'Zusätzliche Treibstoffreserven.', '', 28153),
(154121, 'deDE', 'Neuer Kandidat für Verderbnis.', '', 28153),
(154120, 'deDE', 'Wirte entdeckt. Infektion beginnt.', '', 28153),
(154119, 'deDE', '', 'Ich versichere Euch, die existieren und sind gefährlich. Nicht einmal die Sethrak wagen sich in die Schlucht.', 28153),
(154118, 'deDE', 'Initiiere Plasmagewinnung.', '', 28153),
(154117, 'deDE', 'Schneller, Ihr Schnecken! Ihr werdet bezahlt, wenn es repariert ist!', '', 28153),
(154116, 'deDE', 'So eine hübsche Insel...', 'So eine hübsche Insel...', 28153),
(154115, 'deDE', 'War es glorreich?', 'War es glorreich?', 28153),
(154114, 'deDE', '', 'Weiter! Rakera wird in dieser Wüste nich\' lang überleb\'n.', 28153),
(154113, 'deDE', 'Das schmerzt nicht so sehr, wie ich...', 'Das schmerzt nicht so sehr, wie ich...', 28153),
(154112, 'deDE', 'Warum habe ich versagt?', 'Warum habe ich versagt?', 28153),
(154111, 'deDE', 'Sterbt, Aasgeier!', 'Sterbt, Aasgeier!', 28153),
(154110, 'deDE', 'Ihr werdet mich nicht bezwingen!', 'Ihr werdet mich nicht bezwingen!', 28153),
(154109, 'deDE', 'Wo ist Eure Bansheekönigin jetzt?', 'Wo ist Eure Bansheekönigin jetzt?', 28153),
(154108, 'deDE', 'Ich habe das Meer nicht überlebt, um durch Abschaum wie Euch zu sterben!', 'Ich habe das Meer nicht überlebt, um durch Abschaum wie Euch zu sterben!', 28153),
(154107, 'deDE', '', 'Oh, so ja nun nicht.', 28153),
(154106, 'deDE', 'Zeit, Nishas Plan in die Tat umzusetzen. Die Sethrak werden gar nicht wissen, wie ihnen geschieht.', '', 28153),
(154105, 'deDE', '', 'Ich hätte mehr in die Sicherheit investieren sollen.', 28153),
(154104, 'deDE', '', 'Ich kann mir keine Ablenkungen leisten!', 28153),
(154103, 'deDE', '', 'Prügelt sie, wenn es nicht anders geht! Ich will, dass der Riffbrecher sofort einsatzbereit ist.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'deDE', 'Sie wird es vielleicht nicht überleben. Sie ist schwer verwundet.', '', 28153),
(154101, 'deDE', '', 'Ich finde immer einen Weg. Ist das noch ein Überlebender?', 28153),
(154100, 'deDE', 'Rettet, was Ihr könnt, bevor alles zerstört wird.', 'Rettet, was Ihr könnt, bevor alles zerstört wird.', 28153),
(154099, 'deDE', 'Es gibt hier viele interessante Gegenstände.', 'Es gibt hier viele interessante Gegenstände.', 28153),
(154098, 'deDE', 'Es wird \'ne Weile dauern, bis wir genug Wach\'n hab\'n, um die Alte Handelsstraße so wie früher zu sichern. Wir wiss\'n Eure Hilfe zu schätz\'n.', '', 28153),
(154097, 'deDE', 'Danke...', 'Danke...', 28153),
(154096, 'deDE', 'Oh nein... nicht schon wieder.', 'Oh nein... nicht schon wieder.', 28153),
(154095, 'deDE', 'Lasst nicht zu, dass sie mich fressen...', 'Lasst nicht zu, dass sie mich fressen...', 28153),
(154094, 'deDE', 'Das wird ganz einfach... haben sie behauptet...', 'Das wird ganz einfach... haben sie behauptet...', 28153),
(154093, 'deDE', 'Euer Kopf wird eine schöne Trophäe abgeben!', 'Euer Kopf wird eine schöne Trophäe abgeben!', 28153),
(154092, 'deDE', 'Unsre Händler hab\'n uns um Wach\'n für ihre Karawan\' gebet\'n. Wärt Ihr für \'ne Eskorte zu ham?', '', 28153),
(154091, 'deDE', 'Die Seuche wird Euch holen!', 'Die Seuche wird Euch holen!', 28153),
(154090, 'deDE', 'Aus dem Meer gerettet, nur, um durch meine Hand zu sterben!', 'Aus dem Meer gerettet, nur, um durch meine Hand zu sterben!', 28153),
(154089, 'deDE', 'Ihr werdet hier sterben!', 'Ihr werdet hier sterben!', 28153),
(154088, 'deDE', 'JETZT ZEIGT IHR ENDLICH EURE WAHRE GESINNUNG, $gTODESGEBIETER:TODESGEBIETERIN;! VERSCHWINDET VON DIESER HEILIGEN STÄTTE!', 'JETZT ZEIGT IHR ENDLICH EURE WAHRE GESINNUNG, $gTODESGEBIETER:TODESGEBIETERIN;! VERSCHWINDET VON DIESER HEILIGEN STÄTTE!', 28153),
(154087, 'deDE', 'Der nächste Schritt ist immer der größte, $n. Schreitet weiter auf diesem Pfad.', 'Der nächste Schritt ist immer der größte, $n. Schreitet weiter auf diesem Pfad.', 28153),
(154086, 'deDE', 'Ihr seid ein Monster nach Arthas\' Vorbild, $n. Ich hoffe, Euer endgültiger Tod wird langsam und mit ebenso großer Qualen verbunden sein wie jene, die Ihr anderen zugefügt habt.\n\nAls die ganze Welt sich um die wirklich wichtigen Angelegenheiten gekümmert hat, habt Ihr auf dem ganzen Planeten die Toten in ihr verfluchtes Untotendasein gezwungen. Ich bin mir sicher, dass Ihr es für das Richtige gehalten habt, aber ich schwöre Euch, dass dies noch Konsequenzen haben wird.\n\n<Zallestrasza schüttelt sich kurz.>\n\nAber für den Augenblick könnt Ihr uns vielleicht dienlich sein.', 'Ihr seid ein Monster nach Arthas\' Vorbild, $n. Ich hoffe, Euer endgültiger Tod wird langsam und mit ebenso großer Qualen verbunden sein wie jene, die Ihr anderen zugefügt habt.\n\nAls die ganze Welt sich um die wirklich wichtigen Angelegenheiten gekümmert hat, habt Ihr auf dem ganzen Planeten die Toten in ihr verfluchtes Untotendasein gezwungen. Ich bin mir sicher, dass Ihr es für das Richtige gehalten habt, aber ich schwöre Euch, dass dies noch Konsequenzen haben wird.\n\n<Zallestrasza schüttelt sich kurz.>\n\nAber für den Augenblick könnt Ihr uns vielleicht dienlich sein.', 28153),
(154085, 'deDE', '<Der Gesichtsausdruck von Zallestrasza wird etwas milder.>\n\nUnd auch das haben wir zur Kenntnis genommen, $n. Wir sind nicht viele und jedes unserer Leben ist wertvoll.\n\nEs entschuldigt nicht die Vergehen gegen meinen Schwarm, aber wir wissen Eure... Zurückhaltung zu schätzen. Für jemanden wie Euch kann das nicht einfach gewesen sein.', '<Der Gesichtsausdruck von Zallestrasza wird etwas milder.>\n\nUnd auch das haben wir zur Kenntnis genommen, $n. Wir sind nicht viele und jedes unserer Leben ist wertvoll.\n\nEs entschuldigt nicht die Vergehen gegen meinen Schwarm, aber wir wissen Eure... Zurückhaltung zu schätzen. Für jemanden wie Euch kann das nicht einfach gewesen sein.', 28153),
(154084, 'deDE', 'Ja, $gTodesgebieter:Todesgebieterin; $n.\n\nWir wissen, dass Ihr unser Sanktum angegriffen habt. \n\nWir wissen auch, dass Ihr Kyranastrasz verdorben und versklavt habt. Dies sind schwerwiegende Verbrechen, für die Ihr eines Tages zur Rechenschaft gezogen werdet.', 'Ja, $gTodesgebieter:Todesgebieterin; $n.\n\nWir wissen, dass Ihr unser Sanktum angegriffen habt. \n\nWir wissen auch, dass Ihr Kyranastrasz verdorben und versklavt habt. Dies sind schwerwiegende Verbrechen, für die Ihr eines Tages zur Rechenschaft gezogen werdet.', 28153),
(154083, 'deDE', 'Wir wissen von Euren Vergehen, Todesritter. Ihr habt zwar geholfen, Azeroth vor der Brennenden Legion zu retten, aber unser Vertrauen ist beschädigt.\n\nNehmt Euch in Acht.', 'Wir wissen von Euren Vergehen, Todesritter. Ihr habt zwar geholfen, Azeroth vor der Brennenden Legion zu retten, aber unser Vertrauen ist beschädigt.\n\nNehmt Euch in Acht.', 28153),
(154082, 'deDE', 'Offensichtlich sind mir ein paar Drachen im Rubinschrein entgangen. <Versucht, sie zu töten.>', 'Offensichtlich sind mir ein paar Drachen im Rubinschrein entgangen. <Versucht, sie zu töten.>', 28153),
(154081, 'deDE', 'Ich hoffe, ich konnte mir mit meinen Taten hier etwas Vertrauen verdienen.', 'Ich hoffe, ich konnte mir mit meinen Taten etwas Vertrauen verdienen.', 28153),
(154080, 'deDE', 'Euer Volk war schwach und dem Tod schon so nahe. Ich habe nur seinem Leiden ein Ende gemacht.', 'Euer Volk war schwach und dem Tod schon so nahe. Ich habe nur seinem Leiden ein Ende gemacht.', 28153),
(154079, 'deDE', 'Ich habe so viele Leben verschont, wie ich konnte.', 'Ich habe so viele Leben verschont, wie ich konnte.', 28153),
(154078, 'deDE', 'Ihr wisst, wer ich bin?', 'Ihr wisst, wer ich bin?', 28153),
(154077, 'deDE', 'Nein! Nein! Neiiiiiiin!', 'Nein! Nein! Neiiiiiiin!', 28153),
(154076, 'deDE', '', 'Für die Allianz.', 28153),
(154075, 'deDE', 'Verschwindet! Rettet Euch!', 'Verschwindet! Rettet Euch!', 28153),
(154074, 'deDE', 'Ich... Ich glaub, ich hab mich eingenässt...', 'Ich... Ich glaub, ich hab mich eingenässt...', 28153),
(154073, 'deDE', 'Holt mich hier raus!', 'Holt mich hier raus!', 28153),
(154072, 'deDE', 'Danke! Fast wäre ich geliefert gewesen.', 'Danke! Fast wäre ich geliefert gewesen.', 28153),
(154071, 'deDE', 'Was sind das für Dinger?! Ich verschwinde hier!', 'Was sind das für Dinger?! Ich verschwinde hier!', 28153),
(154070, 'deDE', 'Gerettet! Fast wäre ich als Monsterfutter geendet!', 'Gerettet! Fast wäre ich als Monsterfutter geendet!', 28153),
(154069, 'deDE', 'Hmpf. Das war keine große Herausforderung.', '', 28153),
(154068, 'deDE', 'Unfassbar... Mit welchen anderen Schrecken hat Lord Sturmsang sich noch eingelassen?', '', 28153),
(154067, 'deDE', 'Ein mächtiges Unheil erwartet uns im Schrein. Zeigen wir ihm die Zähne!', '', 28153),
(154066, 'deDE', 'Seid achtsam! Ich spüre eine Masse großer Verderbnis im Schrein. Sie muss ausgemerzt werden!', '', 28153),
(154065, 'deDE', 'Ihr seht noch so aus wie vorher. Hmpf. Wie dem auch sei, unsere Jagd geht weiter.', '', 28153),
(154064, 'deDE', 'Fühlt Ihr Euch nicht ruhiger? In Eurer Entschlossenheit bestärkt? Lasst uns nun weiter vorstoßen und tun, was nötig ist.', '', 28153),
(154063, 'deDE', 'Es heißt, die Gezeitenweisen stärken sich mit Wasser aus ihren reinigenden Brunnen. Lasst uns sehen, ob daran etwas Wahres ist, bevor wir das Herz des Schreins betreten.', '', 28153),
(154062, 'deDE', 'Hmpf! Mir nach, los!', '', 28153),
(154061, 'deDE', 'Alle müssen geläutert werden, bevor sie in unsere heilige Stätte treten. Ich bitte Euch, den Segen jedes reinigenden Brunnens zu empfangen, bevor Ihr das Herz des Schreins betretet.', '', 28153),
(154060, 'deDE', 'Jedes kleine bisschen hilft, Champion. Für die Horde!', '', 28153),
(154059, 'deDE', 'Es ist eine Erleichterung, zu wissen, dass nicht alles Lord Sturmsangs Einfluss unterlegen ist. Danke.', '', 28153),
(154058, 'deDE', 'Stärke wohnt diesen Teichen inne. Sammelt reine Wasserpartikel, um unsere Macht wachsen zu lassen!', '', 28153),
(154057, 'deDE', 'Ich spüre, dass an diesem heiligen Ort noch Gutes weilt. Sammelt reine Wasserpartikel, sodass dieser Schrein wieder in neuem Glanz erstrahlen kann.', '', 28153),
(154056, 'deDE', 'Sie hätten mich fast erwischt. Ich danke Euch, $C.', 'Sie hätten mich fast erwischt. Ich danke Euch, $C.', 28153),
(154055, 'deDE', '', 'Ansteckung breitet sich aus.', 28153),
(154054, 'deDE', '', 'Virusbedrohung steigt.', 28153),
(154053, 'deDE', '', 'Neue Mutation entdeckt.', 28153),
(154052, 'deDE', '', 'Chirurgischer Strahl aktiviert. Entnehme Proben für weitere Studien.', 28153),
(154051, 'deDE', '', 'Infektionsausmaß kritisch. Säuberung eingeleitet.', 28153),
(154050, 'deDE', '', 'Entlüfte Kontaminierungskammer.', 28153),
(154049, 'deDE', '', 'Teste bakterielle Empfindlichkeit gegen extreme Hitze.', 28153),
(154048, 'deDE', '', 'Sezierungsprotokolle initiiert.', 28153),
(154047, 'deDE', '', 'System wiederhergestellt. Werte wieder im Normalbereich.', 28153),
(154046, 'deDE', 'Leise ist anders, aber Ihr wart ziemlich effektiv.', '', 28153),
(154045, 'deDE', '', 'Sieht aus, als hätt\' sich\'s ausgekrabbelt. Yazma wird uns nich\' mehr nachspionier\'n!', 28153),
(154044, 'deDE', '', 'Yazmas hat überall Späher. Sie kann sogar durch die Augen von Spinnen seh\'n. Zerquetscht die Krabbelviecher.', 28153),
(154043, 'deDE', '', 'Säuberung abgeschlossen.', 28153),
(154042, 'deDE', 'Das ist eine Rettungsmission. Findet unsere gefangenen Soldaten, befreit sie und bringt sie zum Treffpunkt. Ich autorisiere den Einsatz tödlicher Gewalt. Das heißt: Ich empfehle sie ausdrücklich.', '', 28153),
(154041, 'deDE', '', 'Ansteckungsgefahr reduziert.', 28153),
(154040, 'deDE', 'Gut. Jetzt sollte die zweite Gruppe unsere Soldaten problemlos befreien können.', '', 28153),
(154039, 'deDE', '', 'Schattenklinge Razi wird nie wieder jemand von meinem Volk töten. Danke.', 28153),
(154038, 'deDE', '', 'Infektion gesäubert.', 28153),
(154037, 'deDE', 'Diese Mission ist simpel: Stiftet Chaos. Eine weitere Gruppe steht bereit, um unsere gefangenen Krieger zu befreien, aber zuerst müsst Ihr die Wachen ausschalten. Geht, tötet so viele Ihr finden könnt und verschwindet dann wieder.', '', 28153),
(154036, 'deDE', '', 'Eine von Yazmas loyalsten Assassinen wurd\' in dem Gebiet gesichtet. Seid vorsichtig!', 28153),
(154035, 'deDE', '', 'Virulenter Erreger entdeckt. Leite vollständige Auslöschung ein.', 28153),
(154034, 'deDE', '', 'Das wird Yazma und ihresgleichen lehr\'n, mit dunklem Vooodoo zu hantier\'n.', 28153),
(154033, 'deDE', '', 'Säuberungsprotokoll aktiviert.', 28153),
(154032, 'deDE', '', 'Yazmas böser Voodoo hat diese Tikimasken zum Leb\'n erweckt! Zerstört ihre verderbt\'n Konstrukte.', 28153),
(154031, 'deDE', 'Ihr habt es geschafft! Jetzt können die Jungs von der Forscherliga den Tempel ungestört erkunden.', '', 28153),
(154030, 'deDE', 'Jemand hat\'s auf die Zandalaritrolle hier in der Gegend abgesehen. Die Forscherliga kann den Tempel nicht betreten, bevor nicht etwas unternommen wird! Geht da rein und findet raus, wer dahintersteckt!', '', 28153),
(154029, 'deDE', 'Fantastisch! Dann starten wir gleich eine Expedition.', '', 28153),
(154028, 'deDE', 'Ich kann meine Jungs nicht in den Tempel runterschicken, solang diese Tikimasken da ihr Unwesen treiben. Ihre Magie ist zu stark!', '', 28153),
(154027, 'deDE', 'Gute Arbeit! Auch wenn ich immer noch spüre, wie die Viecher in meinem Bart rumkrabbeln...', '', 28153),
(154026, 'deDE', 'Igitt, Spinnen! Warum müssen es immer Spinnen sein? Diese Yazma hat wirklich überall welche. Zetretet bitte ein paar, damit wir in Frieden arbeiten können!', '', 28153),
(154025, 'deDE', 'Lichtgeschmiedete, bringt diese Verwüster zu Fall!', '', 28153),
(154024, 'deDE', 'Greifenreiter, schwingt Euch in die Lüfte!', '', 28153),
(154023, 'deDE', 'Jetzt, Dunkeleisenzwerge! Greift sie von unten an!', '', 28153),
(154022, 'deDE', '', 'Nun, das ist der Beweis. Aber Ihr habt nicht viele von ihnen übrig gelassen, die ihren Plan umsetzen könnten! Wie dem auch sei, gute Arbeit.', 28153),
(154021, 'deDE', 'Ruhm der... Allianz...', '', 28153),
(154020, 'deDE', 'Ich mag heute ja den Nebelfockfreibeutern angehören, aber deshalb einfach anzunehmen, ich würde mich auf die Seite der Horde schlagen und meine Wurzeln bei der Allianz verraten? Wie könnt Ihr es wagen?!', '', 28153),
(154019, 'deDE', '', 'Die Piratenmannschaften in Freihafen führen immer etwas im Schilde. Findet heraus, was es diesmal ist.', 28153),
(154018, 'deDE', 'Die 7. Legion muss sich um eine Bedrohung weniger sorgen... dank Euch.', '', 28153),
(154017, 'deDE', 'Gut gekämpft! Wir werden schon bald das gesamte Gebiet für die Allianz sichern!', '', 28153),
(154016, 'deDE', 'Das war eine echte Herausforderung und Ihr habt sie tapfer bewältigt. Macht weiter so!', '', 28153),
(154015, 'deDE', 'Der Feind wurde zur Strecke gebracht. Eine Schande, dass es so grausam enden musste, aber Ihr habt getan, was getan werden musste.', '', 28153),
(154014, 'deDE', 'Im Dritten Krieg hätte ich jemanden wie Euch an meiner Seite gebrauchen können. Exzellente Arbeit.', '', 28153),
(154013, 'deDE', 'Ihr hättet Euch damals im Zweiten Krieg ordentlich geschlagen. Gut gekämpft!', '', 28153),
(154012, 'deDE', 'Gute Arbeit. Eine Bedrohung weniger, um die wir uns Sorgen machen müssten!', '', 28153),
(154011, 'deDE', 'Danke, dass Ihr Eure Stärke zur Verfügung gestellt habt. Ihr seid ein wahrer Champion der Ergebenen!', '', 28153),
(154010, 'deDE', '', 'Trefft sie, wo es schmerzt... nämlich in der Brieftasche!', 28153),
(154009, 'deDE', '', 'Wenn wir eins der Geschäftsbücher der Bande hätten, könnten wir damit ihre Finanzen stören!', 28153),
(154008, 'deDE', 'Danke. Wir können die Verwundeten noch nicht wegschaffen, aber Ihr habt uns Zeit verschafft.', 'Danke. Wir können die Verwundeten noch nicht wegschaffen, aber Ihr habt uns Zeit verschafft.', 28153),
(154007, 'deDE', 'Hier, das stoppt erst mal die Blutung...', 'Hier, das stoppt erst mal die Blutung...', 28153),
(154006, 'deDE', 'Ich weiß, es tut weh, aber versucht, stillzuhalten...', 'Ich weiß, es tut weh, aber versucht, stillzuhalten...', 28153),
(154005, 'deDE', 'Ruhe! Sonst hören sie uns...', 'Ruhe! Sonst hören sie uns...', 28153),
(154004, 'deDE', 'Geht, holt Hilfe! Ich versuche diese Verderbnis derweil aus Uldir aufzuhalten!', '', 28153),
(154003, 'deDE', '', 'Ottkens\' Handschrift würde ich überall erkennen. Erst bringe ich Euch um, und dann diese Verräterin!', 28153),
(154002, 'deDE', 'Ohh, der Eingang schließt sich! Diese Chance muss ich nutzen!', '', 28153),
(154001, 'deDE', '', 'Noch da, wo ich ihn gelassen habe!', 28153),
(154000, 'deDE', '', 'Käpt\'n! Wir haben eine Meuterei...', 28153),
(153999, 'deDE', 'Hat das Ding gerade \"G\'huun\" gesagt?! Folgt dieser Maschine!', '', 28153),
(153997, 'deDE', 'Vielleicht hat sie etwas mit Uldir zu tun. Los, lasst es uns rausfinden!', '', 28153),
(153996, 'deDE', 'So eine Verderbnis habe ich noch nie gesehen.', '', 28153),
(153995, 'deDE', '', 'Heda, $C. Interessiert, \'n bisschen Alchemie zu lernen?$b$bIch sag Euch, ich bin die beste Ausbilderin im Land.', 28153),
(153994, 'deDE', 'Wer weiß, welche Geheimnisse sie hütet? Vielleicht erfahren wir dort sogar, wie man einen Alten Gott besiegen kann!', '', 28153),
(153993, 'deDE', 'Die Titanen haben diese Anlage nach dem Untergang des schwarzen Imperiums gebaut, um allerhand Experimente durchzuführen.', '', 28153),
(153992, 'deDE', 'Ech! Was ist das denn für ein Viech?!', '', 28153),
(153991, 'deDE', 'Diese Höhlen müssen zum legendären Uldir führen!', '', 28153),
(153990, 'deDE', 'Danke für Eure Hilfe. Dank Eurer Bemühungen ist die Wüste jetzt sicherer.', '', 28153),
(153989, 'deDE', '', '\'ne ganz schöne Herausforderung, aber Ihr habt gut gekämpft. Macht weiter so!', 28153),
(153988, 'deDE', '', 'Ein Problem weniger. Gute Arbeit!', 28153),
(153987, 'deDE', '', 'Gut gemacht! Ihr habt den Feinden \'ne Lektion verpasst, die sie nich\' so schnell vergess\'n werd\'n.', 28153),
(153986, 'deDE', 'Geht voran.', 'Geht voran.', 28153),
(153985, 'deDE', '', 'Dieses Haust steckt voller Geheimnisse. Nachdem die oberen Geschosse gesichert sind, kann ich Euch einen verborgenen Weg in den Keller zeigen.', 28153),
(153984, 'deDE', 'Danke, dass Ihr geholfen habt. Wir brauchen mehr Helden wie Euch in Vol\'dun!', '', 28153),
(153983, 'deDE', 'Gute Arbeit. Die Wüste ist dank Eurer Hilfe jetzt etwas sicherer.', '', 28153),
(153982, 'deDE', 'Eine Gefahr weniger, über die man sich in Vol\'dun Sorgen machen muss. Gut gemacht!', '', 28153),
(153981, 'deDE', 'Aber denkt doch nur... an all das Gold...', '', 28153),
(153980, 'deDE', 'Versteht Ihr, womit Ihr es hier zu tun habt? Aschenwind wird uns mächtiger machen, als wir es uns je erträumt hätten!', '', 28153),
(153979, 'deDE', 'Ihr werdet meinem Volk kein Leid zufügen!', '', 28153),
(153978, 'deDE', 'Die Steine sind... überall... Die Mogu werden... alle bekommen!', '', 28153),
(153977, 'deDE', 'Dort! Angriff!', '', 28153),
(153976, 'deDE', '', 'Ich glaube, wir haben es geschafft. Gute Arbeit da hinten.', 28153),
(153975, 'deDE', 'Mit diesen Steinen werden die Mogu unbesiegbar sein!', '', 28153),
(153974, 'deDE', 'Jetzt zeigt Ihr Euer Gesicht! Hinfort!', '', 28153),
(153973, 'deDE', '', 'Wir bekommen anscheinend Besuch. Heißt sie willkommen, $p!', 28153),
(153972, 'deDE', '', 'Festhalten, das wird holprig.', 28153),
(153971, 'deDE', 'Auch ein alter Wolf kann die Zähne zeigen!', '', 28153),
(153970, 'deDE', 'Ihr gehört mir!', '', 28153),
(153969, 'deDE', 'Habt Ihr doch noch Euren Mut zusammengenommen? Hah!', '', 28153),
(153968, 'deDE', '', 'Das glaube ich nicht.', 28153),
(153967, 'deDE', '', 'Jämmerlich.', 28153),
(153966, 'deDE', '', 'Nicht heute.', 28153),
(153965, 'deDE', 'Meine Späher melden einen gefährlichen Feind in der Nähe. Ihr müsst ihn ausschalten.', '', 28153),
(153962, 'deDE', 'Ich habe einige meiner Soldaten an einen Feind in der Nähe verloren. Rächt ihren Tod!', '', 28153),
(153959, 'deDE', 'Die 7. Legion hat Berichte über einen mächtigen Feind in der Nähe erhalten. Schaltet ihn umgehend aus.', '', 28153),
(153958, 'deDE', 'Kein Schatz... nur Dunkel.', 'Gold so weit das Auge sieht...', 28153),
(153957, 'deDE', 'Lasst mich frei...', 'Bin ich... frei?', 28153),
(153956, 'deDE', 'Verfluchter Schatz... verfluchtes Gold...', 'Verfluchter Dieb...', 28153),
(153955, 'deDE', 'Werft mich auf den Hauf\'n...', 'Goldne Knoch\'n...', 28153),
(153954, 'deDE', 'Ich habe Berichte über einen gefährlichen Gegner in Eurer Nähe erhalten. Schaltet ihn aus, aber macht Euch auf Überraschungen gefasst.', '', 28153),
(153953, 'deDE', 'Einige unserer Späher sind hier einem gefährlichen Gegner zum Opfer gefallen. Ehrt sie, indem Ihr ihn ausschaltet!', '', 28153),
(153952, 'deDE', 'Vorsicht... eine gefährliche Kreatur ist in der Nähe. Bewahrt Ruhe und streckt sie nieder, bevor sie entkommt!', '', 28153),
(153951, 'deDE', 'Das sieht gar nich\' schlecht aus, $gScheff:Scheffin;. Aber wenn\'s Euch nich\' gefällt, könnt Ihr noch weiter grab\'n.', '', 28153),
(153950, 'deDE', 'Ich habe einen Trank für jeden von Euch. Aber trinkt ihn noch nicht gleich.', '', 28153),
(153949, 'deDE', 'Gut. Ihr habt eine schlafende Stadt sehr, sehr wütend gemacht.\n\nVerplempern wir besser keine Zeit mit Schuldzuweisungen, ja?', '', 28153),
(153948, 'deDE', 'Diese Geschichte kenne ich bereits. (Szenario überspringen und zum Hafen von Zuldazar in Zandalar teleportieren.)', 'Diese Geschichte kenne ich bereits. (Szenario überspringen und zum Hafen von Zuldazar in Zandalar teleportieren.)', 28153),
(153947, 'deDE', 'Das soll Eurem Meister eine Botschaft sein. Die Sturmwacht wird niemals wanken!', '', 28153),
(153946, 'deDE', 'Lasst es nicht in Euren Kopf. Bleibt stark!', '', 28153),
(153945, 'deDE', '', 'All dieses Leid ist nur Eure Schuld. MONSTER!', 28153),
(153944, 'deDE', 'Ich werde uns vor seinem Angriff schützen!', '', 28153),
(153943, 'deDE', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far', '', 28153),
(153942, 'deDE', 'Gold. Gold. Gold.', 'Mehr für den Schatzhauf\'n.', 28153),
(153941, 'deDE', 'Kein Licht. Kein Entkommen. Der vergessene König kehrt zurück.', '', 28153),
(153940, 'deDE', 'Keine Crew...', 'Lauft...', 28153),
(153939, 'deDE', 'Alle Schätze gehör\'n Zem\'lan.', 'Nur Zem\'lan darf den Schatz ham.', 28153),
(153938, 'deDE', 'Mir scheint, ich muss Euch einander vorstell\'n. Erster Maat Ottkens, $n. $n, Ottkens. Dann lasst uns jetz\' zum Geschäftlich\'n komm\'n, ja?', '', 28153),
(153937, 'deDE', '', 'Ich habe Kiro gewarnt, dass sich die Sethrak früher oder später auf uns stürzen. Wir hätten uns wappnen können... Vielleicht hört er jetzt endlich zu.', 28153),
(153936, 'deDE', '', 'Wir waren nicht gegen ihren Angriff gefeit. Die Sethrak kennen beim Töten und Versklaven keine Reue.', 28153),
(153935, 'deDE', 'Gold...', 'Glitzer...', 28153),
(153934, 'deDE', 'In der Nähe lauert eine gefährliche Bedrohung. Vernichtet sie, bevor ihr noch mehr Unschuldige zum Opfer fallen.', '', 28153),
(153933, 'deDE', 'Einige unserer Verbündeten wurden hier angegriffen. Ihr müsst diese Bedrohung sofort ausschalten.', '', 28153),
(153930, 'deDE', 'Es treibt sich eine gefährliche Kreatur in der Nähe herum. Tötet sie, bevor weitere Unschuldige Schaden nehmen.', '', 28153),
(153929, 'deDE', '', 'Ich hab Berichte von \'ner Bedrohung in der Nähe erhalt\'n. Schaltet die so schnell wie möglich aus!', 28153),
(153928, 'deDE', '', 'Einige von unsren Verbündeten wurd\'n hier in der Nähe angegriff\'n. Schaltet die Bedrohung aus, damit sowas nich\' nochmal passiert!', 28153),
(153927, 'deDE', '', 'Hier treibt sich was sehr Gefährliches rum. Ihr müsst es töten, bevor\'s Euch tötet.', 28153),
(153926, 'deDE', 'Ich habe Berichte über eine gefährliche Kreatur hier in der Nähe erhalten. Ich will, dass Ihr sie so schnell wie möglich tötet!', '', 28153),
(153925, 'deDE', 'Schnell, zu mir!', '', 28153),
(153924, 'deDE', 'Eine unserer Karawanen wurde in der Nähe angegriffen. Schaltet diese Bedrohung aus, damit so etwas nicht noch einmal geschieht!', '', 28153),
(153923, 'deDE', 'Ich weiß ja, dass sie \'n Mensch is\', aber habt trotzdem Verständnis.', '', 28153),
(153922, 'deDE', 'Unser Ziel is\' simpel. Wir verhelf\'n ihrer Meuterei zum Erfolg, un\' wir könn\' hier \'nen Stützpunkt für unsren Angriff einricht\'n.', '', 28153),
(153921, 'deDE', 'Ottkens will ihre Freiheit nich\' aufgeb\'n, so wie\'s die andren Piraten mach\'n.', '', 28153),
(153920, 'deDE', 'Es befindet sich eine gefährliche Kreatur in der Nähe. Kümmert Euch um sie, bevor es zu spät ist!', '', 28153),
(153919, 'deDE', 'Ich hab was über unsren Kontakt gehört, als ich Tiragarde nach Landeplätz\'n ausgespäht hab.', '', 28153),
(153918, 'deDE', 'Ahoi, $gPirat:Piratin;!', '', 28153),
(153917, 'deDE', 'Das versunkene Reich heißt Eure gähnenden Seelen willkommen.', '', 28153),
(153916, 'deDE', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma', '', 28153),
(153915, 'deDE', 'Er ist verloren! Es bleibt nichts als Dunkelheit.', '', 28153),
(153914, 'deDE', '', 'Samuel, ich weiß, Ihr seid da drin. Ihr müsst es bekämpfen!', 28153),
(153913, 'deDE', 'Euch kann wirklich keine Kreatur lang widerstehen.', '', 28153),
(153912, 'deDE', '', 'Ausgezeichnet! Jetzt ist der Weg frei.', 28153),
(153911, 'deDE', 'Es war nur eine Miniatur. Sprechen wir nicht weiter davon.', '', 28153),
(153910, 'deDE', '', 'Perfekt! Wir nehmen es mit und finden heraus, was sich darin verbirgt!', 28153),
(153909, 'deDE', 'Das reicht vorerst. Der Kriegshäuptling dankt Euch.', '', 28153),
(153908, 'deDE', '', 'Fantastisch! Das wird im Krieg helfen.', 28153),
(153907, 'deDE', 'Also, $gScheff:Scheffin;. Dann treff\'n wir uns jetz\' mit dem ersten Maat. Benehmt Euch auch wie $g\'n Pirat:\'ne Piratin;.', '', 28153),
(153906, 'deDE', 'Ich seh echt gut aus, nich\'? Joho, joho!', '', 28153),
(153905, 'deDE', 'Eine übel gelaunte Bestie versperrt uns den Fluchtweg aus dem Gefängnis. Tötet sie.', '', 28153),
(153904, 'deDE', '', 'Eine mächtige Bestie verhindert, dass wir den Stützpunkt am Strand sichern können. Ihr müsst Euch für mich darum kümmern, damit wir einen Fluchtweg haben.', 28153),
(153903, 'deDE', 'Lasst mich doch auch beim Verkleid\'n mitmach\'n, $gScheff:Scheffin;.', '', 28153),
(153902, 'deDE', 'Unsere Späher berichten, dass die Stolz von Kul Tiras in Tol Dagor vor Anker liegt. Wenn das stimmt, werdet Ihr dieses Schiff für uns stehlen.', '', 28153),
(153901, 'deDE', '', 'Der Aufseher hält ein Erbstück in einem Modellschiff versteckt. Ich hätte gern, dass Ihr es mir bringt.', 28153),
(153900, 'deDE', 'Die Kriegsmaschine der Horde braucht Rüstung und Waffen. Nehmt, was Ihr tragen könnt, wenn Ihr drin seid und meldet Euch bei mir.', '', 28153),
(153899, 'deDE', '', 'Bei all dem Chaos muss es noch zu plündernde Waren geben. Schauen wir mal, ob wir ihnen nicht ein paar Versorgungsgüter wegklauen können.', 28153),
(153898, 'deDE', 'Sie haben deinen Vater ermordet... deinen König verraten... und du hast nichts getan! Überlässt du all deine Verbündeten der Horde?', '', 28153),
(153897, 'deDE', 'Die Horde ist ein Haufen Ungeheuer. Kein Wunder, dass sie sich gegen dich gewandt haben!', '', 28153),
(153896, 'deDE', 'Du hast diesen Monstern mehr vertraut als deinem eigenen Fleisch und Blut!', '', 28153),
(153895, 'deDE', 'Du hast zugesehen, wie diese Bestien mich niedergemetzelt haben. Was war der Lohn für deinen Verrat?', '', 28153),
(153894, 'deDE', 'Eine größere Meute von Bleichborkentrollen nähert sich Stromgarde aus dem Osten. Jagen wir ein paar zurück zu ihren Hütten. Und die restlichen tötet Ihr bitte.', '', 28153),
(153893, 'deDE', 'Das hier nich\' verbrenn\'. Das nehm\' wir, um raus zur Insel zu fahr\'n.', '', 28153),
(153892, 'deDE', 'Einige unserer Greifenreiter wurden vom Himmel geholt. Haltet im Feld nach Überlebenden Ausschau.', '', 28153),
(153891, 'deDE', '', 'Jetz\' seht Ihr\'s. Jetz\' versteht Ihr\'s. G\'huun kommt Euch alle hol\'n.', 28153),
(153890, 'deDE', '', 'Wenn das Monster befreit wird, wär\' das das Ende von Zuldazar!', 28153),
(153889, 'deDE', '', 'Ich wusste, dass die Bluttrolle \'ne Bedrohung sin\', aber das hätt\' ich nich\' erwartet...', 28153),
(153888, 'deDE', 'Wer seid Ihr?', 'Wer seid Ihr?', 28153),
(153886, 'deDE', 'Seid gegrüßt, $n. Die Kunde Eurer Heldentaten als Champion von Azeroth hat auch uns erreicht.', 'Seid gegrüßt, $n. Die Kunde Eurer Heldentaten als Champion von Azeroth hat auch uns erreicht.', 28153),
(153885, 'deDE', 'Verteufelte Scheusale! Zurück in die Tiefe!', '', 28153),
(153884, 'deDE', 'Ich fürchte, dass Kultisten aus dem Haus Sturmsang versuchen könnten, ihren Einfluss in Boralus auszuweiten. Entlarvt sie!', '', 28153),
(153883, 'deDE', '', 'Die Gerüchte stimmten also. Wenigstens sind die Straßen jetzt etwas sicherer.', 28153),
(153882, 'deDE', 'Kommt, Brüder und Schwestern. Lasst uns zusammenstehen!', '', 28153),
(153881, 'deDE', 'Bleibt in Bewegung! Die Dunkelheit nagt an seinem Verstand!', '', 28153),
(153880, 'deDE', '', 'Haltet durch, Samuel! Wir sind gleich da!', 28153),
(153879, 'deDE', 'GEZEITEN DES BLUTES! STEIGT! SCHWELLT AUF!', '', 28153),
(153878, 'deDE', '', 'Es heißt, dass die Wachen von Boralus auf der Gehaltsliste der Bande stehen. Könnt Ihr die Angelegenheit untersuchen?', 28153),
(153877, 'deDE', 'Puh. Das beschäftigt die für... äh... was? Fünf Minuten?', '', 28153),
(153876, 'deDE', 'Boah! Die Vögel hier sind außer Kontrolle! Gebt denen irgendwas Essbares! Schnell!', '', 28153),
(153875, 'deDE', 'Na gut. Keine von den Geldbörsen ist meine, aber... ich verwahre sie mal, bis wir die Besitzer finden.', '', 28153),
(153874, 'deDE', 'Häh? Was zum... Wo ist meine Geldbörse? Hat die Rotznase etwa meine Geldbörse geklaut?! Haltet den Dieb!', '', 28153),
(153873, 'deDE', '', 'Ich hoffe, die anderen sind auch in Sicherheit.', 28153),
(153872, 'deDE', '', 'Die Vulpera sind ein duldsames Volk. Wir ziehen mit Karawanen umher, verwerten, was wir finden, und suchen den Handel.', 28153),
(153871, 'deDE', 'Ihr habt es geschafft, $p. Ai\'twen erwacht!', '', 28153),
(153870, 'deDE', '', 'Seht, was die Sethrak unserer Heimat angetan haben...', 28153),
(153869, 'deDE', '', 'Eine gute Wahl. Damit komm ich klar.', 28153),
(153868, 'deDE', 'Einige Oger der Felsfäuste haben vor, Stromgarde anzugreifen. Zeigt ihnen doch bitte, wie es den letzten Bierbauchbarbaren ergangen ist, die unsere Stadt mit ihrer Anwesenheit besudelt haben.', '', 28153),
(153867, 'deDE', 'Nur Geduld, Taelia. Sie werden kommen.', '', 28153),
(153866, 'deDE', '', 'Wird der Rest der Sturmwacht überhaupt rechtzeitig hier eintreffen?', 28153),
(153865, 'deDE', 'Ihr erhaltet gewiss eine Belohnung, wenn Ihr die Schlingel zu ihrem Dorf am See im Südwesten zurückbringt, aber haltet Euch besser vom Wasser fern... Da werden die Kaulquappen schließlich gemacht.', '', 28153),
(153864, 'deDE', 'Offenbar flitzt in der Gegend eine ganze Schar von Murlockaulquappen herum.', '', 28153),
(153863, 'deDE', 'Unsere Späher berichten von einem gestohlenen Erzwagen bei der Mine im Nordosten. Wie wäre es mit einer feindlichen Wiederübernahme?', '', 28153),
(153862, 'deDE', 'Wir haben einige unbewachte Holzfäller der Horde gesichtet. Vielleicht können wir von ihnen etwas Holz abZWEIGen.', '', 28153),
(153861, 'deDE', 'Denkt daran, auch sprechendes, aggressives Holz ist immer noch... Holz. Ein großer Haufen Holz.', '', 28153),
(153860, 'deDE', 'Zweigfürst Aldrus wurde an der Baumgrenze gesichtet.', '', 28153),
(153859, 'deDE', 'Der Steinriese Fozruk ist auf den Straßen im Südosten unterwegs. Lasst Euch nicht von ihm zertrampeln.', '', 28153),
(153858, 'deDE', 'Lasst uns den zuhauen und auf die Front der Horde hetzen.', '', 28153),
(153857, 'deDE', 'Auf dem Hügel im Osten wurde ein enormer Erdelementar gesichtet.', '', 28153),
(153856, 'deDE', 'Soldaten des Bundes, die Zeit ist gekommen.', '', 28153),
(153855, 'deDE', 'Kreuzfahrer, auf nach Ar\'gorok! Das Licht will es so!', '', 28153),
(153854, 'deDE', 'Die Horde versucht, Galsons Mine einzunehmen. Heißt sie erz-lich willkommen.', '', 28153),
(153853, 'deDE', 'Die Horde belästigt unsere Verbündeten beim Hochlandsägewerk. Da müssen wir wohl ein paar Späne fliegen lassen.', '', 28153),
(153852, 'deDE', 'Streitkräfte der Horde sind in Stromgarde eingedrungen. Schützt Euren Kommandanten und helft dem Feind, den Weg wieder heraus zu finden.', '', 28153),
(153851, 'deDE', 'Der Hochstand wird angegriffen. Ich würde vorschlagen, dass wir die Horde von unserem Hügel vertreiben.', '', 28153),
(153850, 'deDE', '', 'Gebt mir Bescheid, dann können wir anfangen!', 28153),
(153849, 'deDE', '', 'Der Kriegshäuptling erwartet, dass alle Helden der Horde gerüstet sind. Nutzen wir die Zeit für ein paar Kampfübungen.', 28153),
(153848, 'deDE', '', 'Grüße! Willkommen in Silithus! Ihr seid hier, um unsere Azeritoperation vor der Allianz zu schützen.', 28153),
(153847, 'deDE', 'Zucken... Schlängeln... dieses Flüstern...', '', 28153),
(153846, 'deDE', 'Gebt mir Bescheid, wenn Ihr bereit seid, anzufangen.', '', 28153),
(153845, 'deDE', 'Während wir durch Silithus patrouillieren, können wir gleich Eure Kampffertigkeiten aufpolieren.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'deDE', 'Willkommen an Bord! König Wrynn erwartet, dass jeder Held der Allianz in Höchstform ist, wenn wir der Horde gegenübertreten.', '', 28153),
(153843, 'deDE', 'Seid vorsichtig. Der Name dieser Brücke kommt nicht von ungefähr.', '', 28153),
(153842, 'deDE', '', 'Beeindruckend! Als Nächstes werden wir... Wartet, ist das etwa...? Macht Euch kampfbereit! Die Allianz greift an!', 28153),
(153841, 'deDE', 'Die Flut kommt... kein Entrinnen...', '', 28153),
(153840, 'deDE', 'Haltet die Terrasse! Gebt Zul genug Zeit, um diese kläglichen Kreaturen zu zerquetschen.', '', 28153),
(153839, 'deDE', 'Hordentruppen nähern sich dem Zirkel der Elemente. Vielleicht sollten wir ihnen eine Zauberlektion erteilen.', '', 28153),
(153838, 'deDE', '', 'Für meinen Vater!', 28153),
(153837, 'deDE', '', 'Ich werde es Euch nicht leicht machen!', 28153),
(153836, 'deDE', 'Gut gemacht! Als Nächstes werden wir... Wartet, ist das etwa...? Zu den Waffen! Die Horde greift an!', '', 28153),
(153835, 'deDE', '', 'Eure Zeit ist gekommen!', 28153),
(153834, 'deDE', '', 'Für Kul Tiras!', 28153),
(153833, 'deDE', 'Die Horde greift unsere Truppen am Nordhofkreuz an, aber sie werden bald zu Kreuze kriechen.', '', 28153),
(153832, 'deDE', '', '\'Metamorphose\' verwandelt Euch in einen Dämon und verstärkt \'Chaosstoß\' und \'Klingentanz\'.', 28153),
(153831, 'deDE', '', 'Wir stehen Euch bei!', 28153),
(153830, 'deDE', 'Die Horde nähert sich dem Heldenrufpass, direkt vor unserer Tür. Heißt sie gebührend willkommen.', '', 28153),
(153829, 'deDE', '\'Metamorphose\' verwandelt Euch in einen Dämon und verstärkt \'Chaosstoß\' und \'Klingentanz\'.', '', 28153),
(153828, 'deDE', 'Wenn die Horde denkt, sie könne Neuhof einnehmen, hat sie aufs falsche Pferd gesetzt.', '', 28153),
(153827, 'deDE', '', '\'Klingentanz\' ist eine schnelle Abfolge von Attacken, die alle Feinde in der Nähe treffen.', 28153),
(153826, 'deDE', '\'Klingentanz\' ist eine schnelle Abfolge von Attacken, die alle Feinde in der Nähe treffen.', '', 28153),
(153825, 'deDE', '', 'Diese Fähigkeit ist kostspielig, aber ungemein mächtig. Setzt sie möglichst oft ein.', 28153),
(153824, 'deDE', 'Diese Fähigkeit ist kostspielig, aber ungemein mächtig. Setzt sie möglichst oft ein.', '', 28153),
(153823, 'deDE', '', '\'Augenstrahl\' versengt Eure Gegner mit dem dämonischen Chaos, das in Euch brennt.', 28153),
(153822, 'deDE', '\'Augenstrahl\' versengt Eure Gegner mit dem dämonischen Chaos, das in Euch brennt.', '', 28153),
(153821, 'deDE', '', 'Dies ist einer Eurer verheerendsten Angriffe. Setzt ihn häufig ein, damit sich Euer Jähzorn nicht aufstaut.', 28153),
(153820, 'deDE', 'Dies ist einer Eurer verheerendsten Angriffe. Setzt ihn häufig ein, damit sich Euer Jähzorn nicht aufstaut.', '', 28153),
(153819, 'deDE', 'Ich wollte Hilfe suchen und hier seid Ihr schon! Da habt Ihr mir den Weg erspart.', '', 28153),
(153818, 'deDE', 'Soldaten der Horde sind im Anmarsch. Wehrt sie nach besten Kräften ab.', '', 28153),
(153817, 'deDE', '', 'Setzt \'Überwältigen\' gegen die Zielattrappe ein.', 28153),
(153816, 'deDE', 'Setzt \'Überwältigen\' gegen die Zielattrappe ein.', '', 28153),
(153815, 'deDE', 'Da haben wir wohl in ein Wespennest gestochen. Die Horde schickt alles, was sie hat.', '', 28153),
(153814, 'deDE', '', 'Dieser Angriff verstärkt außerdem Euren nächsten \'Tödlichen Stoß\', also setzt ihn früh und häufig ein.', 28153),
(153813, 'deDE', 'Dieser Angriff verstärkt außerdem Euren nächsten \'Tödlichen Stoß\', also setzt ihn früh und häufig ein.', '', 28153),
(153812, 'deDE', '', 'Mit \'Überwältigen\' versetzt Ihr dem Gegner mit Eurer gewaltigen Kraft einen kritischen Treffer.', 28153),
(153811, 'deDE', 'Mit \'Überwältigen\' versetzt Ihr dem Gegner mit Eurer gewaltigen Kraft einen verheerenden Schlag.', '', 28153),
(153810, 'deDE', '', 'Ihr habt Schaden erlitten – für Euch aber kein Problem.', 28153),
(153809, 'deDE', 'Ihr habt Schaden erlitten – für Euch aber kein Problem.', '', 28153),
(153804, 'deDE', 'Verwendet \'Blutsauger\', um Eure Gesundheit wiederherzustellen!', '', 28153),
(153803, 'deDE', '', 'Verwendet \'Blutsauger\', um Eure Gesundheit wiederherzustellen!', 28153),
(153802, 'deDE', '', '\'Blutsauger\' entzieht Eurem Ziel die Lebenskraft und heilt Euch gleichzeitig.', 28153),
(153801, 'deDE', '\'Blutsauger\' entzieht Eurem Ziel die Lebenskraft und heilt Euch gleichzeitig.', '', 28153),
(153798, 'deDE', '', 'Setzt \'Schattenblitz\' gegen die Zielattrappe ein.', 28153),
(153797, 'deDE', 'Setzt \'Schattenblitz\' gegen die Zielattrappe ein.', '', 28153),
(153796, 'deDE', '', 'Wirkt \'Schattenblitz\', wenn Euer Opfer bereits von Euren anderen Zaubern betroffen ist.', 28153),
(153795, 'deDE', 'Wirkt \'Schattenblitz\', wenn Euer Opfer bereits von Euren anderen Zaubern betroffen ist.', '', 28153),
(153794, 'deDE', '', 'Wenn Ihr Euer Ziel mit \'Agonie\' und \'Verderbnis\' geschwächt habt, setzt Euren Angriff mit düsterer Schattenmagie fort.', 28153),
(153793, 'deDE', 'Wenn Ihr Euer Ziel mit \'Agonie\' und \'Verderbnis\' geschwächt habt, setzt Euren Angriff mit düsterer Schattenmagie fort.', '', 28153),
(153792, 'deDE', 'Die Schatt\'n soll\'n Euch verschling\'n.', '', 28153),
(153791, 'deDE', '', '\'Alpharaserei\' verringert außerdem die Zeit, bis \'Zorn des Wildtiers\' wieder eingesetzt werden kann.', 28153),
(153790, 'deDE', '\'Alpharaserei\' verringert außerdem die Zeit, bis \'Zorn des Wildtiers\' wieder eingesetzt werden kann.', '', 28153),
(153789, 'deDE', '', 'Wir werden Euer Handeln nicht tolerieren!', 28153),
(153788, 'deDE', '', 'Setzt \'Alpharaserei\' ein, während Ihr die Zielattrappe angreift.', 28153),
(153787, 'deDE', 'Setzt \'Alpharaserei\' ein, während Ihr die Zielattrappe angreift.', '', 28153),
(153786, 'deDE', '', '\'Alpharaserei\' versetzt Euren Begleiter in Rage, sodass Ihr Euch auf Eure anderen Fähigkeiten konzentrieren könnt.', 28153),
(153785, 'deDE', '\'Alpharaserei\' versetzt Euren Begleiter in Rage, sodass Ihr Euch auf Eure anderen Fähigkeiten konzentrieren könnt.', '', 28153),
(153784, 'deDE', '', 'Ihr könnt auch Eurem Begleiter befehlen, eine Reihe wütender Angriffe durchzuführen.', 28153),
(153783, 'deDE', 'Ihr könnt auch Eurem Begleiter befehlen, eine Reihe wütender Angriffe durchzuführen.', '', 28153),
(153782, 'deDE', '', 'Setzt \'Lauffeuerbombe\' ein, um alle Gegner zu verbrennen.', 28153),
(153781, 'deDE', 'Setzt \'Lauffeuerbombe\' ein, um alle Gegner zu verbrennen.', '', 28153),
(153780, 'deDE', '', 'Sie sind besonders effektiv gegen Gegnergruppen, da das Feuer alle Gegner in einem Kegel hinter Eurem Ziel trifft.', 28153),
(153779, 'deDE', 'Sie sind besonders effektiv gegen Gegnergruppen, da das Feuer alle Gegner in einem Kegel hinter Eurem Ziel trifft.', '', 28153),
(153778, 'deDE', '', 'Lauffeuerbomben sind ein tödliches Werkzeug, das Gegner in Brand setzt und regelmäßigen Feuerschaden verursacht.', 28153),
(153777, 'deDE', 'Lauffeuerbomben sind ein tödliches Werkzeug, das Gegner in Brand setzt und regelmäßigen Feuerschaden verursacht.', '', 28153),
(153776, 'deDE', '', 'Setzt \'Schlangengift\' gegen die Zielattrappe ein.', 28153),
(153775, 'deDE', 'Setzt \'Schlangengift\' gegen die Zielattrappe ein.', '', 28153),
(153774, 'deDE', '', '\'Schlangengift\' feuert einen vergifteten Pfeil, der regelmäßigen Naturschaden verursacht.', 28153),
(153773, 'deDE', '\'Schlangengift\' feuert einen vergifteten Pfeil, der regelmäßigen Naturschaden verursacht.', '', 28153),
(153772, 'deDE', '', 'Eure Überlebensfähigkeiten sind mächtige Werkzeuge, um Gegnern Schaden zuzufügen.', 28153),
(153771, 'deDE', 'Eure Überlebensfähigkeiten sind mächtige Werkzeuge, um Gegnern Schaden zuzufügen.', '', 28153),
(153770, 'deDE', 'Diese Schlange...', '', 28153),
(153769, 'deDE', 'Günstige Winde!', 'Günstige Winde!', 28153),
(153768, 'deDE', 'Kommt den Sirenen nicht zu nah!', 'Kommt den Sirenen nicht zu nah!', 28153),
(153767, 'deDE', 'Mein Loa schreit auf! Zuls Frevel kennt keine Grenzen!', '', 28153),
(153766, 'deDE', 'Immer warmhalten.', 'Immer warmhalten.', 28153),
(153765, 'deDE', 'Holt mein Schiff zurück, $n! Dann kümmern wir uns um die Möchtegernthronräuber.', '', 28153),
(153764, 'deDE', 'Anker lichten!', 'Anker lichten!', 28153),
(153763, 'deDE', 'Tschüss!', 'Tschüss!', 28153),
(153762, 'deDE', 'Fische sind irgendwie komisch.', 'Fische sind irgendwie komisch.', 28153),
(153761, 'deDE', 'Habt Ihr Skorbut?', 'Habt Ihr Skorbut?', 28153),
(153759, 'deDE', 'Ich hab... mein\'n Teil getan...', '', 28153),
(153758, 'deDE', 'Ich mag Tortollaner.', 'Ich mag Tortollaner.', 28153),
(153757, 'deDE', 'Wo ist nochmal steuerbord?', 'Wo ist nochmal steuerbord?', 28153),
(153756, 'deDE', 'Arrrr!! Kling ich wie ein Pirat?', 'Arrrr!! Kling ich wie ein Pirat?', 28153),
(153755, 'deDE', 'Ahoi!', 'Ahoi!', 28153),
(153754, 'deDE', '', 'Setzt \'Tötungsbefehl\' mehrmals gegen die Zielattrappe ein.', 28153),
(153753, 'deDE', 'Setzt \'Tötungsbefehl\' mehrmals gegen die Zielattrappe ein.', '', 28153),
(153752, 'deDE', '', '\'Tötungsbefehl\' lässt Euren Begleiter eine starke Attacke durchführen und erzeugt Fokus für Eure anderen Fähigkeiten.', 28153),
(153751, 'deDE', '\'Tötungsbefehl\' lässt Euren Begleiter eine starke Attacke durchführen und erzeugt Fokus für Eure anderen Fähigkeiten.', '', 28153),
(153750, 'deDE', 'Mama sagt, Papa spinnt zu viel Garn – dabei hab ich ihn noch nie stricken sehen.', 'Mama sagt, Papa spinnt zu viel Garn – dabei hab ich ihn noch nie stricken sehen.', 28153),
(153749, 'deDE', '', 'Ihr habt nah genug zu Eurer Beute aufgeschlossen. Entfesselt Euren Zorn.', 28153),
(153748, 'deDE', 'Ihr habt nah genug zu Eurer Beute aufgeschlossen. Entfesselt Euren Zorn.', '', 28153),
(153747, 'deDE', 'Mir ist... kalt...', 'Mir ist... kalt...', 28153),
(153746, 'deDE', 'Ihr gehört hier nicht her!', 'Ihr gehört hier nicht her!', 28153),
(153745, 'deDE', 'In der Tat. $n, reist nach Kezan. Erbeutet die Azeritraffinierungstechnik... und zeigt Mogul Ratztunk, warum man sein Wort gegenüber der Dunklen Fürstin nicht bricht.', '', 28153),
(153744, 'deDE', 'Diese Abmachung hat uns mehr Probleme gemacht, als sie wert war. Da gibt\'s \'nen viel einfacheren Weg... wir müssen nur den Mittelsmann ausschalten, wenn Ihr versteht.', '', 28153),
(153743, 'deDE', 'Der Kriegshäuptling wird nicht erfreut sein. Wir haben für unseren Krieg gegen die Allianz fest mit Ratztunks Methoden zur Azeritraffinierung gerechnet.', '', 28153),
(153742, 'deDE', 'Oh, VERZEIHT MIR, Bansheeprinz, dass ich ein bisschen aufgekratzt bin, nachdem ich fast GETÖTET wurde... für eine Abmachung, gegen die ich von Anfang an war!', '', 28153),
(153741, 'deDE', 'Reißt Euch zusammen, Handelsprinz. Dieses Geplapper gebührt sich nicht für einen Anführer der Horde.', '', 28153),
(153740, 'deDE', 'Mogul Ratztunk hat uns aufs Kreuz gelegt! Der grüne Bastard hat einfach das Geschäft platzen lassen. Ihr glaubt nicht, was er–', '', 28153),
(153739, 'deDE', 'Hey, Herr Pestrufer. Ich hab schlechte Neuigkeiten...', '', 28153),
(153738, 'deDE', '', 'Bluttrolle... Holt mehr... von dieser Macht!', 28153),
(153737, 'deDE', '', 'Macht! MACHT!', 28153),
(153736, 'deDE', 'Ai\'twen hat geruht und Kraft für den Augenblick gesammelt, in dem er wieder gebraucht wird.', '', 28153),
(153735, 'deDE', 'Teleportiert Euch zu G\'huun.', 'Teleportiert Euch zu G\'huun.', 28153),
(153734, 'deDE', 'Teleportiert Euch zu Mythrax.', 'Teleportiert Euch zu Mythrax.', 28153),
(153733, 'deDE', 'Teleportiert zum Niedergang.', 'Teleportiert zum Niedergang.', 28153),
(153732, 'deDE', 'Teleportiert Euch zum Eingang von Uldir.', 'Teleportiert Euch zum Eingang von Uldir.', 28153),
(153731, 'deDE', 'Der Teleporter scheint aktiv und stabil zu sein.', 'Der Teleporter scheint aktiv und stabil zu sein.', 28153),
(153730, 'deDE', 'Neuer Tag, neuer Sieg!', '', 28153),
(153729, 'deDE', 'Meine Wachen berichten, dass die Troggs sich auf einen neuen Angriff vorbereiten! Haltet sie auf, bevor es zu spät ist!', '', 28153),
(153728, 'deDE', 'Fertig? Gut. Je weniger irre Tiere, die mich fressen wollen und können, desto besser.', '', 28153),
(153727, 'deDE', 'Bezirzte Bären?! Nein! Das geht gar nicht. Bitte... ähm... macht die da weg.', '', 28153),
(153726, 'deDE', '', 'Vielleicht spinne ich ja, aber ich mag keine Bäume, die laufen können.', 28153),
(153725, 'deDE', '', 'Klingt, als ob es wieder Ärger bei Algersons Sägewerk gibt. Helft ihnen!', 28153),
(153724, 'deDE', 'Ganz famos! Ihr und Euer pelziger Gefährte seid ein teuflisches Gespann.', '', 28153),
(153723, 'deDE', 'Nickel scharrt schon danach, da draußen ein paar Falken zu jagen. Nehmt ihn doch mit. Ein bisschen Training wird ihm gut tun.', '', 28153),
(153722, 'deDE', 'Ah, Eure Ausbeute lässt sich wie immer sehen. Mein Respekt.', '', 28153),
(153721, 'deDE', 'Neuer Tag, neue Jagd! Schauen wir, wie viel Ihr diesmal erwischt!', '', 28153),
(153720, 'deDE', 'In letzter Zeit is\' \'ne Menge los in der Stadt. Auf dem Wasser zu sein, is\' besser. Hier draußen isses angenehm.', '', 28153),
(153719, 'deDE', 'Vor einigen Jahren sin\' die Naga gekomm\'. Ihre Kolosse hab\'n den Tempel niedergeriss\'n.', '', 28153),
(153718, 'deDE', 'Is\' \'n Jammer, was in Atal\'Gral passiert is\'.', '', 28153),
(153717, 'deDE', 'Ich seh nachts immer wieder unters Boot. Die Naga schein\' überall zu sein.', '', 28153),
(153716, 'deDE', 'Atal\'Gral', 'Atal\'Gral', 28153),
(153715, 'deDE', 'Hafen von Zuldazar', 'Hafen von Zuldazar', 28153),
(153714, 'deDE', '', 'Gral kam dem Geheimnis zu nahe.', 28153),
(153713, 'deDE', '', 'Geht nach Atal\'Gral. Ich hoffe wirklich, dass der Tempel noch steht.', 28153),
(153712, 'deDE', 'Mit Eurer Hilfe wird der Angelpunkt eines Tages wieder der alte sein.', '', 28153),
(153711, 'deDE', 'Tiefenwacht hält den Angelpunkt noch immer in seinem Klammergriff. Wir müssen mit allen Kräften die Ordnung in der Werft wiederherstellen!', '', 28153),
(153710, 'deDE', 'Die Wasser hauchen einen Seufzer der Erleichterung. Ihr habt ihren Schmerz gelindert. Vielen Dank.', '', 28153),
(153709, 'deDE', 'Die kriechende Verderbnis in der Bucht muss geläutert werden. Säubert die Wasser von den infizierten Kreaturen!', '', 28153),
(153708, 'deDE', 'Habt Dank. Die liefere ich gleich dem Außenposten!', '', 28153),
(153707, 'deDE', 'Rosalinde hat um mehr Stacheln gebeten. Könntet Ihr mir aushelfen?', '', 28153),
(153706, 'deDE', 'Wunderbar! Davon bekommt Majo wieder etwas Mumm in den Knochen.', '', 28153),
(153705, 'deDE', 'Unser hartschaliger Kumpan Majo hat das Reiten geübt, aber er braucht hier und da einen kleinen Mageneinrenker. Könntet Ihr etwas von seinem Lieblingsgetränk beschaffen?', '', 28153),
(153704, 'deDE', '', 'Hoffentlich haben diese Schmuggler ihre Lektion gelernt. Verbrechen zahlt sich nicht aus!', 28153),
(153703, 'deDE', '', 'Diese Schmuggler denken, sie können mit den Waffen unserer Miliz aus Boralus verschwinden. Rückt ihnen den Kopf zurecht!', 28153),
(153702, 'deDE', 'Kinder, bringt euch in Sicherheit! Schnell!', 'Kinder, bringt euch in Sicherheit! Schnell!', 28153),
(153701, 'deDE', 'Keine Angst, ich bin direkt hinter Euch...', 'Keine Angst, ich bin direkt hinter Euch...', 28153),
(153700, 'deDE', 'Schnell, hier rein!', 'Schnell, hier rein!', 28153),
(153699, 'deDE', 'Okay, von hier aus übernehmen wir. Sieh mal einer an, alle haben noch beide Augen! Gute Arbeit!', '', 28153),
(153698, 'deDE', 'Die See von Kul Tiras verschlingt Euch alle!', 'Die See von Kul Tiras verschlingt Euch alle!', 28153),
(153697, 'deDE', 'Nur zu. Meine Familie ist sicher.', 'Nur zu. Meine Familie ist sicher.', 28153),
(153696, 'deDE', 'Dafür bezahlt Ihr!', 'Dafür bezahlt Ihr!', 28153),
(153695, 'deDE', 'Bestien!', 'Bestien!', 28153),
(153694, 'deDE', 'Der Platz ist vor die Vögel gegangen! Ihr müsst die Zivilisten wegbringen, sonst picken die Möwen ihnen die Augen aus. Aber sagt ihnen nicht, dass ich das gesagt habe!', '', 28153),
(153693, 'deDE', 'Hilfe! Helft uns!', 'Hilfe! Helft uns!', 28153),
(153692, 'deDE', 'Nicht so...', 'Nicht so...', 28153),
(153691, 'deDE', 'Ich hab Angst!', 'Ich hab Angst!', 28153),
(153690, 'deDE', 'Aber meine Eltern...', 'Aber meine Eltern...', 28153),
(153689, 'deDE', 'Werden wir sterben?', 'Werden wir sterben?', 28153),
(153688, 'deDE', 'Warum antwortest du nicht? Ich hab Angst!', 'Warum antwortest du nicht? Ich hab Angst!', 28153),
(153687, 'deDE', 'Wach auf! Bitte wach auf...', 'Wach auf! Bitte wach auf...', 28153),
(153686, 'deDE', 'PAPA!', 'PAPA!', 28153),
(153685, 'deDE', 'MAMA!', 'MAMA!', 28153),
(153684, 'deDE', 'Passt auf Euch auf! Allzeit gute Winde, $gReisender:Reisende;!', '', 28153),
(153683, 'deDE', '', 'Eure heutige Ankunft wurde in den Schriftrollen vorhergesagt.', 28153),
(153682, 'deDE', 'Ahhh, $n. Ja. Hat sich als nützlich erwies\'n.', '', 28153),
(153681, 'deDE', 'Ich möchte meine Ausrüstung reparieren lassen.', 'Ich möchte meine Ausrüstung reparieren lassen.', 28153),
(153680, 'deDE', '', 'Denkt daran, Euch auszuruhen. Erschöpft nützt Ihr der Allianz nichts.', 28153),
(153679, 'deDE', 'Die Horde hat die Kontrolle über den Zirkel der Elemente übernommen!', 'Die Horde hat die Kontrolle über den Zirkel der Elemente übernommen!', 28153),
(153678, 'deDE', '$n hat den Zirkel der Elemente eingenommen!', '$n hat den Zirkel der Elemente eingenommen!', 28153),
(153677, 'deDE', 'Die Horde hat die Kontrolle über Galsons Mine übernommen!', 'Die Horde hat die Kontrolle über Galsons Mine übernommen!', 28153),
(153676, 'deDE', '$n hat Galsons Mine eingenommen!', '$n hat Galsons Mine eingenommen!', 28153),
(153675, 'deDE', 'Die Horde hat die Kontrolle über das Nordhofkreuz übernommen!', 'Die Horde hat die Kontrolle über das Nordhofkreuz übernommen!', 28153),
(153674, 'deDE', '$n hat das Nordhofkreuz eingenommen!', '$n hat das Nordhofkreuz eingenommen!', 28153),
(153673, 'deDE', 'Die Horde hat die Kontrolle über den Hochstand übernommen!', 'Die Horde hat die Kontrolle über den Hochstand übernommen!', 28153),
(153672, 'deDE', '$n hat den Hochstand eingenommen!', '$n hat den Hochstand eingenommen!', 28153),
(153671, 'deDE', 'Die Horde hat die Kontrolle über Neuhof übernommen!', 'Die Horde hat die Kontrolle über Neuhof übernommen!', 28153),
(153670, 'deDE', '$n hat Neuhof eingenommen!', '$n hat Neuhof eingenommen!', 28153),
(153669, 'deDE', 'Die Horde hat die Kontrolle über das Hochlandsägewerk übernommen!', 'Die Horde hat die Kontrolle über das Hochlandsägewerk übernommen!', 28153),
(153668, 'deDE', '$n hat das Hochlandsägewerk eingenommen!', '$n hat das Hochlandsägewerk eingenommen!', 28153),
(153667, 'deDE', 'Die Horde hat die Kontrolle über den Heldenrufpass übernommen!', 'Die Horde hat die Kontrolle über den Heldenrufpass übernommen!', 28153),
(153666, 'deDE', '$n hat den Heldenrufpass eingenommen!', '$n hat den Heldenrufpass eingenommen!', 28153),
(153665, 'deDE', 'Unsere Heldentaten werden in die Annalen der Militärgeschichte eingehen.', '', 28153),
(153664, 'deDE', 'Unsere brillante Strategie und die tadellose Ausführung hat den Feind verwirrt.', '', 28153),
(153663, 'deDE', 'Ich glaube, damit haben sie nicht gerechnet.', '', 28153),
(153662, 'deDE', '', 'Victoria! Sie... hat es nicht geschafft...', 28153),
(153661, 'deDE', '', 'Folgt alle Nathanos zum Hof! Ich hindere die Allianz daran, Euch zu folgen!', 28153),
(153660, 'deDE', 'Soldaten, in Formation! Die Allianz naht!', '', 28153),
(153659, 'deDE', '', 'Die Zandalari wissen nichts von dem Grauen, das ihnen bevorsteht. Man muss sie warnen.', 28153),
(153658, 'deDE', '', 'Königin Azshara führt irgendetwas im Schilde, und sie ist nicht allein.', 28153),
(153657, 'deDE', '', 'Meine Güte! Das ist ja furchtbar. Das ist ein Befehl, alle zu töten, die Gral treu ergeben sind!', 28153),
(153656, 'deDE', 'So sind wir ihnen immer zahlenmäßig weit überlegen.', '', 28153),
(153655, 'deDE', 'Steckt mich nich\' wieder in den Golem...', 'Lasst mein\' Geist frei... bitte...', 28153),
(153654, 'deDE', 'Wir komm\' Euch hol\'n, Zak\'rajan...', 'Ihr seid der nächste, Zak\'rajan...', 28153),
(153653, 'deDE', 'Endlich... Fried\'n...?', 'Endlich... Lasst mich in Fried\'n ruh\'n...', 28153),
(153652, 'deDE', 'Bwonsamdi... lässt mich nich\' sterb\'n...', 'Wo is\'n... die Andre Seite?', 28153),
(153651, 'deDE', 'Der Setzling wurde von Wildtieren gefressen!', 'Der Setzling wurde von Wildtieren gefressen!', 28153),
(153650, 'deDE', 'JIPPIEEEEEEEEE!', '', 28153),
(153649, 'deDE', 'Die Horde darf nicht entkommen!', '', 28153),
(153648, 'deDE', 'Wachen! Ein Angriff! Auf Eure Posten! Schließt die Tore. Blockiert die Zugänge!', '', 28153),
(153647, 'deDE', 'Herrlich! Fahren wir los!', '', 28153),
(153646, 'deDE', 'Klar.', 'Klar.', 28153),
(153645, 'deDE', 'Eure Freunde wurden alle von den Hexen gefoltert und getötet.', 'Eure Freunde wurden alle von den Hexen gefoltert und getötet.', 28153),
(153644, 'deDE', 'Och, so ein Mist! Das ist nicht gut.\n\nIch habe gute Neuigkeiten. Ich bin beinahe damit fertig, eine Stellung auf dem Hügel hier zu errichten. Wollt Ihr sie Euch mal ansehen?', '', 28153),
(153643, 'deDE', 'Sieht so aus, als ob Ihr aus dem Wald gekommen seid. Wie geht\'s den Jungs da?', '', 28153),
(153642, 'deDE', 'Und gerade, nachdem ich das Wolftorrad erfunden hatte!', '', 28153),
(153641, 'deDE', 'Boss, da seid Ihr ja! Und Ihr habt das Trike mitgebracht!', '', 28153),
(153640, 'deDE', 'Die Schlacht um Stromgarde beginnt in 1 Minute.', '', 28153),
(153639, 'deDE', 'Gemeinsam sind wir stärker.', '', 28153),
(153638, 'deDE', 'Niemals aufgeben. Immer überleben.', '', 28153),
(153637, 'deDE', 'Seid vorsichtig!', '', 28153),
(153636, 'deDE', 'Was hab ich Euch über \"Dummheit\'n\" gesagt?', '', 28153),
(153635, 'deDE', 'Die Ausgestoßenen heißen Euch willkommen.', '', 28153),
(153634, 'deDE', 'Seid Ihr gekommen, um zu helfen?', '', 28153),
(153633, 'deDE', 'Was führt Euch hierher?', '', 28153),
(153632, 'deDE', 'Möget Ihr stets Rückenwind haben.', '', 28153),
(153631, 'deDE', 'Stärke und Tugend.', '', 28153),
(153630, 'deDE', 'Geht mit Ehre!', '', 28153),
(153629, 'deDE', 'Dieses Land wird sich geg\'n Euch... auflehn\'...', 'Dieses Land wird sich geg\'n Euch... auflehn\'...', 28153),
(153628, 'deDE', 'Nein! Ich wollt mir doch Euren Kopf hol\'n...', 'Nein! Ich wollt mir doch Euren Kopf hol\'n...', 28153),
(153627, 'deDE', 'Mickrige... Allianz...', 'Mickrige... Allianz...', 28153),
(153626, 'deDE', 'Ihr werdet nich\' viel länger durchhalt\'n...', 'Ihr werdet nich\' viel länger durchhalt\'n...', 28153),
(153625, 'deDE', 'Das Imperium... lebt weiter...', 'Das Imperium... lebt weiter...', 28153),
(153624, 'deDE', 'Es werd\'n immer mehr von uns nachkomm\'n...', 'Es werd\'n immer mehr von uns nachkomm\'n...', 28153),
(153623, 'deDE', 'Ich bin ganz Ohr.', '', 28153),
(153622, 'deDE', 'Es is\' noch nich\' vorbei...', 'Es is\' noch nich\' vorbei...', 28153),
(153621, 'deDE', 'Ihr seid hier willkommen.', '', 28153),
(153620, 'deDE', 'Für die... Horde.', 'Für die... Horde.', 28153),
(153619, 'deDE', 'Ich werd \'ne Belohnung für Euren Kopf krieg\'n.', 'Ich werd \'ne Belohnung für Euren Kopf krieg\'n.', 28153),
(153618, 'deDE', 'Ihr glaubt also, Ihr seid schlauer als wir? Ha!', 'Ihr glaubt also, Ihr seid schlauer als wir? Ha!', 28153),
(153617, 'deDE', 'Eure Köpfe werd\'n unsre Trophäen sein!', 'Eure Köpfe werd\'n unsre Trophäen sein!', 28153),
(153616, 'deDE', 'Ihr könnt uns nich\' alle find\'n!', 'Ihr könnt uns nich\' alle find\'n!', 28153),
(153615, 'deDE', 'Wollt Ihr spiel\'n, Allianz?', 'Wollt Ihr spiel\'n, Allianz?', 28153),
(153614, 'deDE', 'Dieses Land gehört den Zandalari!', 'Dieses Land gehört den Zandalari!', 28153),
(153613, 'deDE', 'Es wird Euch noch leidtun, dass Ihr hierhergekomm\'n seid!', 'Es wird Euch noch leidtun, dass Ihr hierhergekomm\'n seid!', 28153),
(153612, 'deDE', 'Ihr gehört nich\' in dieses Land!', 'Ihr gehört nich\' in dieses Land!', 28153),
(153611, 'deDE', 'Nichts da. Wir sind besser als diese Wilden.', 'Nichts da. Wir sind besser als diese Wilden.', 28153),
(153610, 'deDE', 'Nicht ohne Euch!', 'Nicht ohne Euch!', 28153),
(153609, 'deDE', 'Wir schaffen\'s hier raus, verdammt!', 'Wir schaffen\'s hier raus, verdammt!', 28153),
(153608, 'deDE', 'Ich geh nicht ohne Euch!', 'Ich geh nicht ohne Euch!', 28153),
(153607, 'deDE', 'Was macht Ihr? Bringt Euch in Sicherheit!', 'Was macht Ihr? Bringt Euch in Sicherheit!', 28153),
(153606, 'deDE', 'Geht, holt Hilfe! Ich komm klar!', 'Geht, holt Hilfe! Ich komm klar!', 28153),
(153605, 'deDE', 'Verschwindet hier, es ist zu spät...', 'Verschwindet hier, es ist zu spät...', 28153),
(153604, 'deDE', 'Ihr müsst weglaufen...', 'Ihr müsst weglaufen...', 28153),
(153603, 'deDE', 'Mein Blickt ruht auf Euch.', '', 28153),
(153602, 'deDE', 'Vielleicht passen unsere Verbündeten ja in Zukunft besser auf und lassen sich nicht so leicht ergreifen. Sie können sich glücklich schätzen, dass die Horde auf einen fähigen Champion wie Euch zählen kann.', '', 28153),
(153601, 'deDE', 'Unsere Verbündeten benötigen unsere Hilfe... Sie haben sich offenbar gefangen nehmen lassen. Seht zu, dass sie befreit werden.', '', 28153),
(153600, 'deDE', 'Mit diesen Informationen können wir gewiss die Oberhand über die Allianz gewinnen. Ihr werdet für Eure Mühen belohnt werden.', '', 28153),
(153599, 'deDE', 'Unsere Spione haben uns informiert, dass eine wichtige Nachricht jeden Moment durch dieses Gebiet kommen wird. Unternehmt alles Notwendige, um sie abzufangen.', '', 28153),
(153598, 'deDE', 'Die Loa sin\' Euch gewog\'n. Das is\' gut so! Lasst es Euch nur nich\' zu Kopf steig\'n.', '', 28153),
(153597, 'deDE', 'Unsre Feinde mach\'n sich wieder über den Gart\'n der Loa her. Ihr müsst denen ma\' etwas Benehm\' beibring\'n. Mög\'n die Loa mit Euch sein!', '', 28153),
(153596, 'deDE', 'Wir treffen uns am Außenposten. Wir müssen die Antwort finden. Das riecht nach einer folgenschweren Entdeckung.', '', 28153),
(153595, 'deDE', 'Das mag keine diskrete Arbeit sein, aber sie ist notwendig. Wir müssen unsere Feinde im Dunkeln tappen lassen. Gut gemacht.', '', 28153),
(153594, 'deDE', 'Die Allianz hat Spione ausgesandt, um aus den Schatten unsere Geheimnisse aufzudecken. Sie dürfen nichts von unseren Plänen erfahren. Kümmert Euch darum.', '', 28153),
(153593, 'deDE', 'Ohne die Flotte der Zandalari wird der Krieg mit der Allianz unser Untergang sein.', '', 28153),
(153592, 'deDE', 'Die Allianz wird mit ihrem Angriff nicht warten, bis wir eine Flotte gebaut haben. Wir brauchen die Zandalari.', '', 28153),
(153591, 'deDE', 'Bringt die Zandalari dazu, der Horde beizutreten, Champion.', '', 28153),
(153590, 'deDE', 'Wir brauchen die Flotte der Zandalari.', '', 28153),
(153589, 'deDE', 'Der Kriegshäuptling befiehlt es, Abmarsch!', '', 28153),
(153588, 'deDE', 'Mit Euch und Ai\'twen auf unserer Seite kann der Plan eigentlich gar nicht scheitern.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'deDE', 'Die Zandalari scheinen mich nicht besonders zu mögen.', '', 28153),
(153586, 'deDE', 'Hm. Stimme der Horde.', '', 28153),
(153585, 'deDE', 'Die Zandalariflotte MUSS sich der Horde anschließen. Und Ihr werdet das bewerkstelligen.', '', 28153),
(153584, 'deDE', '', 'Dieser Champion hat der Macht von Sturmwind getrotzt, um Zul un\' mich zu rett\'n. Dafür hat er \'ne Audienz verdient.', 28153),
(153583, 'deDE', 'Mein König, die Horde is\' nur hier, um unsre Flotte für ihr\'n untot\'n Kriegshäuptling zu stehl\'n.', '', 28153),
(153582, 'deDE', 'Ich hab hier echt gutes Zeug. Und Fragen werden auch keine gestellt.', 'Ich hab hier echt gutes Zeug. Und Fragen werden auch keine gestellt.', 28153),
(153581, 'deDE', 'Ich bringe Vorräte vom Hochberg.', 'Ich bringe Vorräte vom Hochberg.', 28153),
(153580, 'deDE', '(Seht Euch die Ereignisse an, die zu Azeroths Verwundung geführt haben.)', '(Seht Euch die Ereignisse an, die zu Azeroths Verwundung geführt haben.)', 28153),
(153579, 'deDE', '<Die Titanenschalttafel zeigt eine Reihe von Dateneinträgen an. Ihr könnt einen auswählen, um ihn Euch näher anzusehen.>', '', 28153),
(153578, 'deDE', 'Ich hoffe, Ihr habt feuerfeste Unterwäsche!', 'Ich hoffe, Ihr habt feuerfeste Unterwäsche!', 28153),
(153577, 'deDE', 'Jetzt geht\'s gleich heiß her!', 'Jetzt geht\'s gleich heiß her!', 28153),
(153576, 'deDE', 'Zeit für ein Feuerwerk!', 'Zeit für ein Feuerwerk!', 28153),
(153575, 'deDE', 'Dieser \"Diamantzwerg\" spricht für die Weltenseele. Er würde nicht derart eingreifen, wenn die Lage nicht ernst wäre.', '', 28153),
(153574, 'deDE', '', 'Oh, stellt Euch mal vor! Der Diamantzwerg könnte uns überallhin auf Azeroth bringen!', 28153),
(153573, 'deDE', 'Ich mag den teleportierenden Diamantzwerg mit den mächtigen Geschenken. Können wir den behalten?', '', 28153),
(153572, 'deDE', 'Ich bin sicher, das ist wichtig, Magni, aber zum Wohle der Menschen von Kul Tiras... bitte beeilt Euch.', '', 28153),
(153571, 'deDE', 'Kommt, Champion. Azeroth selbst ruft uns!', '', 28153),
(153570, 'deDE', 'Ah, hab vergessen, dass ich ihn hier gebunden habe.', 'Ah, hab vergessen, dass ich ihn hier gebunden habe. Verflixt.', 28153),
(153569, 'deDE', 'Ich bin zu alt für so etwas. Ich verschwinde von hier!', 'Ich bin zu alt für so etwas. Ich verschwinde von hier!', 28153),
(153568, 'deDE', 'Seht besser zu, dass Ihr wieder in Ordnung kommt, Gefreiter.', 'Seht besser zu, dass Ihr wieder in Ordnung kommt, Gefreiter.', 28153),
(153567, 'deDE', 'Sir, ich... ich werde mich bessern, Sir.', 'Sir, ich... ich werde mich bessern, Sir.', 28153),
(153566, 'deDE', 'Gefreiter James, haben Eure Eltern Euch als Kind nicht genug Aufmerksamkeit geschenkt? Wieso verschwendet Ihr meine Zeit, indem ich Eurem Hintern durch unbekannte Länder hinterherjagen muss?', 'Gefreiter James, haben Eure Eltern Euch als Kind nicht genug Aufmerksamkeit geschenkt? Wieso verschwendet Ihr meine Zeit, indem ich Eurem Hintern durch unbekannte Länder hinterherjagen muss?', 28153),
(153565, 'deDE', 'Besten Dank, dass Ihr gekommen seid, um mich zu holen... Sir.', 'Besten Dank, dass Ihr gekommen seid, um mich zu holen... Sir.', 28153),
(153564, 'deDE', 'Setzen wir uns in Bewegung!', 'Setzen wir uns in Bewegung!', 28153),
(153563, 'deDE', 'Es wird Zeit, dass wir uns auf den Rückweg machen. Wyrmbann wird einen vollständigen Bericht haben wollen.', 'Es wird Zeit, dass wir uns auf den Rückweg machen. Wyrmbann wird einen vollständigen Bericht haben wollen.', 28153),
(153562, 'deDE', '', 'Die Borstenrücken haben mich nicht getötet, und das werden sie noch bereuen!', 28153),
(153561, 'deDE', '', 'Ich glaube, wenn ich zurückkomme, werde ich erst mal alles neu dekorieren. Vielleicht mit ein paar Hauern? Wenn ich bloß wüsste, wo ich welche herbekommen kann...$b$b<Deike grinst verschmitzt.>', 28153),
(153560, 'deDE', '', 'Ich brauche erst mal einen kräftigen Schluck! Danach muss ich mein Zuhause zurückerobern und wieder aufbauen. Danke, dass Ihr sie etwas dezimiert habt!', 28153),
(153559, 'deDE', 'Ich kann hier nicht lange bleiben. Ich muss zu meinem Hof zurück. Der Bürgermeister hat gesagt, ich soll hier herkommen und Euch unbedingt für Eure Hilfe mit den Borstenrücken danken.$b$bGut gemacht, $gJunge:Kleine;.', '', 28153),
(153558, 'deDE', 'Mit den Stachelebern habt Ihr wirklich gute Arbeit geleistet!', '', 28153),
(153557, 'deDE', 'Ich kann nicht lange bleiben. Diese Landarbeiter müssen repariert werden, um den Schaden zu beheben, den sie auf den Feldern angerichtet haben.$b$bEs ist aber natürlich auch wichtig, ab und an eine Pause einzulegen.', '', 28153),
(153556, 'deDE', 'Ich habe den Landarbeiter im Selbstverteidigungsmodus gelassen. Es wird schon nichts passieren.', '', 28153),
(153555, 'deDE', 'Haltet die Augen nach Stacheleberstacheln offen. Sie sind erstaunlich praktisch als Werkzeuge, und die Stacheleber verwenden sie sogar in ihren eigenen Kesseln als Zutaten.', '', 28153),
(153554, 'deDE', 'Die Horde im Norden, die Stacheleber im Westen. Können wir eigentlich noch auf die Miliz vertrauen?', '', 28153),
(153553, 'deDE', 'Hoffentlich haben es Rolf, Mort und Spiff auch geschafft.', '', 28153),
(153552, 'deDE', '', 'Meine Spione sag\'n mir, dass Ihr Euern Krieg geg\'n die Allianz ohne unsre Flotte nich\' gewinn\' könnt.\n\nDas bedeutet, dass ich jede miese, kleine Aufgabe, die ich heute erledig\'n muss, Euch zuweis\'n werd, un\' wehe Ihr erledigt sie nich\'...!', 28153),
(153551, 'deDE', '', 'Ich sag Zolani un\' Talanji immer wieder, dass der Hafen sicher is\'. Aber hör\'n sie auf mich? Nein.$b$bGibt\'s Stör\'nfriede? Prügelei\'n? Klar. Aber nix, um was sich der König sorg\'n müsste.', 28153),
(153550, 'deDE', 'Wenn Ihr mir freundlicherweise folgen wollt.', 'Wenn Ihr mir freundlicherweise folgen wollt.', 28153),
(153549, 'deDE', 'Ich muss $n etwas zeigen. Ein Geschenk, das auch diesem Land helfen kann.', '', 28153),
(153548, 'deDE', 'Keine Sorge, Freunde. Das ist Magni Bronzebart. Er war König von Eisenschmiede, jetzt ist er der Sprecher für Azeroth.', '', 28153),
(153547, 'deDE', 'Also, das ist neu.', '', 28153),
(153546, 'deDE', 'Hexerei!', '', 28153),
(153545, 'deDE', '', 'Ein... Diamantzwerg?!', 28153),
(153544, 'deDE', 'Jetzt entfesselt die Macht des Herzens von Azeroth!', '', 28153),
(153543, 'deDE', 'Das sind schlimme Neuigkeiten. Wir sollten das lieber dem Hochkommandanten melden.', 'Das sind schlimme Neuigkeiten. Wir sollten das lieber dem Hochkommandanten melden.', 28153),
(153542, 'deDE', 'Korthek ist verrückt! Man muss ihn aufhalten!', 'Korthek ist verrückt! Man muss ihn aufhalten!', 28153),
(153541, 'deDE', 'Korthek wurde der Frieden langweilig. Er kehrte dem Opfer von Sethraliss den Rücken und versucht nun törichterweise, die Schlüssel zusammenzubringen, um den C\'Thrax auf seine Feinde loszulassen.', 'Korthek wurde der Frieden langweilig. Er kehrte dem Opfer von Sethraliss den Rücken und versucht nun törichterweise, die Schlüssel zusammenzubringen, um den C\'Thrax auf seine Feinde loszulassen.', 28153),
(153540, 'deDE', 'Der große Weise Sulthis versicherte sich Kortheks und meiner Hilfe, um eine magische Barriere zu errichten, die den gefallenen C\'Thrax fortschließen sollte. Wir schworen, dass wir ein derartiges Grauen niemals wieder zulassen würden.', 'Der große Weise Sulthis versicherte sich Kortheks und meiner Hilfe, um eine magische Barriere zu errichten, die den gefallenen C\'Thrax fortschließen sollte. Wir schworen, dass wir ein derartiges Grauen niemals wieder zulassen würden.', 28153),
(153539, 'deDE', 'Die entfesselte Macht dieser Zerstörung war gewaltig. Unser Land veränderte sich für immer.', 'Die entfesselte Macht dieser Zerstörung war gewaltig. Unser Land veränderte sich für immer.', 28153),
(153538, 'deDE', 'Nur durch das Eingreifen unseres Loas wurden wir verschont. Sethraliss opferte sich, um den C\'Thrax zu bezwingen, aber vorher zerstörte er noch eine uralte Pyramide, die im Zentrum dieses Landes stand.', 'Nur durch das Eingreifen unseres Loas wurden wir verschont. Sethraliss opferte sich, um den C\'Thrax zu bezwingen, aber vorher zerstörte er noch eine uralte Pyramide, die im Zentrum dieses Landes stand.', 28153),
(153537, 'deDE', 'Vor langer Zeit, bevor der Sand sich auszubreiten begann, fiel ein abscheulicher Kriegshetzer der C\'Thraxxi über unser Land her. Er begann, alles in seinem Weg niederzumetzeln, ganz gleich, ob Troll oder Sethrak.', 'Vor langer Zeit, bevor der Sand sich auszubreiten begann, fiel ein abscheulicher Kriegshetzer der C\'Thraxxi über unser Land her. Er begann, alles in seinem Weg niederzumetzeln, ganz gleich, ob Troll oder Sethrak.', 28153),
(153536, 'deDE', '', 'Wir müssen wegen der Horde wachsam sein. Sie greifen diesen Platz immer wieder an.', 28153),
(153535, 'deDE', '', 'Falls Ihr da draußen noch etwas seht, das in meine Stadt einfallen könnte, würde ich mich über eine Warnung sehr freuen.', 28153),
(153534, 'deDE', '', 'Alle verlassen sich darauf, dass ich der Stadt den Weg weise. Ich werde sie nicht enttäuschen!', 28153),
(153533, 'deDE', '', 'Alle sollten in Sicherheit sein... fürs Erste.', 28153),
(153532, 'deDE', 'Das ist nicht irgendein Stein, es ist ein Schlüssel. Er gehört zu einem ganzen Satz, der gebraucht wird, um eine große und schreckliche Macht einzudämmen.', 'Das ist nicht irgendein Stein, es ist ein Schlüssel. Er gehört zu einem ganzen Satz, der gebraucht wird, um eine große und schreckliche Macht einzudämmen.', 28153),
(153531, 'deDE', 'Oh! Da ist irgendein Stein drin.', 'Oh! Da ist irgendein Stein drin.', 28153),
(153530, 'deDE', '\"Traut nicht der Tochter der See!\"', '\"Traut nicht der Tochter der See!\"', 28153),
(153529, 'deDE', 'Als er tief im Wellenschlund versank:', 'Als er tief im Wellenschlund versank:', 28153),
(153528, 'deDE', 'Rief er voll Gram und Weh,', 'Rief er voll Gram und Weh,', 28153),
(153527, 'deDE', '', 'Er hat versproch\'n, ihn besser auszurüst\'n, damit er mein Volk rett\'n kann. Ich bin bereit, das zu riskier\'n.', 28153),
(153526, 'deDE', 'Verraten von dem eignen Kind,', 'Verraten von dem eignen Kind,', 28153),
(153525, 'deDE', 'Doch wandte sie sich ab.', 'Doch wandte sie sich ab.', 28153),
(153524, 'deDE', 'Die Tochter sah die gnadenlose Schlacht,', 'Die Tochter sah die gnadenlose Schlacht,', 28153),
(153523, 'deDE', 'Da stieß der Feind herab!', 'Da stieß der Feind herab!', 28153),
(153522, 'deDE', 'Doch unversehns am fernen Meeresstrand', 'Doch unversehns am fernen Meeresstrand', 28153),
(153521, 'deDE', 'O See, wo ist mein Kind?', 'O See, wo ist mein Kind?', 28153),
(153520, 'deDE', 'Im Herzen schwer trägt er nur ein Begehr:', 'Im Herzen schwer trägt er nur ein Begehr:', 28153),
(153519, 'deDE', 'Ihr wollt den Champion also einfach so mit dem Diamantenkönig verschwinden lassen?', '', 28153),
(153518, 'deDE', 'Der Vater folgt geschwind.', 'Der Vater folgt geschwind.', 28153),
(153517, 'deDE', 'Sie floh gen West übers weite Meer,', 'Sie floh gen West übers weite Meer,', 28153),
(153516, 'deDE', 'Doch dann erlosch dein Licht.', 'Doch dann erlosch dein Licht.', 28153),
(153515, 'deDE', 'Du warst der Nordstern unserer Nation,', 'Du warst der Nordstern unserer Nation,', 28153),
(153514, 'deDE', 'Warum? Hast du vergessen, wer du bist?', 'Warum? Hast du vergessen, wer du bist?', 28153),
(153513, 'deDE', 'Warum, warum, o Tochter der See?', 'Warum, warum, o Tochter der See?', 28153),
(153512, 'deDE', 'Denn sie ließ ihn allein.', 'Denn sie ließ ihn allein.', 28153),
(153511, 'deDE', 'Ihr Vater fiel in Theramore,', 'Ihr Vater fiel in Theramore,', 28153),
(153510, 'deDE', 'Hört Ihr die Männer schrei\'n?', 'Hört Ihr die Männer schrei\'n?', 28153),
(153509, 'deDE', 'Blutrot der Strand von Kalimdor,', 'Blutrot der Strand von Kalimdor,', 28153),
(153508, 'deDE', 'Und versank in dunkler Nacht.', 'Und versank in dunkler Nacht.', 28153),
(153507, 'deDE', 'So rief er aus, als ihn das Meer verschlang,', 'So rief er aus, als ihn das Meer verschlang,', 28153),
(153506, 'deDE', '\"Nehmt euch vor ihr in Acht!\"', '\"Nehmt euch vor ihr in Acht!\"', 28153),
(153505, 'deDE', '\"Vertraut ihr nicht, der Tochter der See.\"', '\"Vertraut ihr nicht, der Tochter der See.\"', 28153),
(153504, 'deDE', 'Guten Tag, $R.', '', 28153),
(153502, 'deDE', 'Ist da irgendetwas in Euren Taschen?', 'Ist da irgendetwas in Euren Taschen?', 28153),
(153501, 'deDE', 'Ich bleibe hier und kümmere mich um die Verteidigung. Noch mal vielen Dank.', 'Ich bleibe hier und kümmere mich um die Verteidigung. Noch mal vielen Dank.', 28153),
(153500, 'deDE', '', '', 28153),
(153499, 'deDE', '', 'Diener! TÖTET DIE!', 28153),
(153498, 'deDE', 'Ohne Euch und den Uffz wäre ich wohl nicht mehr hier. Nochmals meinen Dank.', 'Ohne Euch und den Uffz wäre ich wohl nicht mehr hier. Nochmals meinen Dank.', 28153),
(153497, 'deDE', '', 'Ich informier Zul. Er wird wiss\'n, ob das Rastakhans Zeit wert is\'.', 28153),
(153496, 'deDE', 'Macht sie kalt, bevor sie durchbrech\'n!', '', 28153),
(153495, 'deDE', 'Keine Unterbrechung mehr bis zu den Docks. Sagt, wenn\'s losgeh\'n kann, $n.', '', 28153),
(153494, 'deDE', 'Seid Ihr lebensmüde?', '', 28153),
(153493, 'deDE', 'Lasst uns ja nich\' auffliegen, $n!', '', 28153),
(153492, 'deDE', 'Wegen Euch geh\'n wir noch drauf!', '', 28153),
(153491, 'deDE', 'Grmpf! Hört auf, abzuhau\'n!', '', 28153),
(153490, 'deDE', 'Kommt zurück, Mann!', '', 28153),
(153489, 'deDE', 'Es ist $n. Dem Licht sei Dank! Ich mache mich auf zum Tempel. Hier ist es nicht sicher.', '', 28153),
(153488, 'deDE', 'Und betet, dass Ihr niemals wählen müsst.', '', 28153),
(153487, 'deDE', 'Vergesst niemals den Unterschied zwischen Loyalität und Ehre.', '', 28153),
(153486, 'deDE', 'Was meint Ihr damit?', 'Was meint Ihr damit?', 28153),
(153485, 'deDE', 'Nach allem, was sie getan hat, kehre ich niemals zu ihrer Horde zurück.', '', 28153),
(153484, 'deDE', 'Ihr glaubt, Ihr wärt hier, um mich nach Orgrimmar zu zurückbringen. Zurück zum Kriegshäuptling. Aber da irrt Ihr Euch.', '', 28153),
(153483, 'deDE', 'Es wird Zeit, dass wir der Venture Company einen strategischen Schlag versetzen!', '', 28153),
(153482, 'deDE', 'Gebt das Signal, $n.', '', 28153),
(153477, 'deDE', '', 'Sterben könnt Ihr später. Wir ham noch Sachen zu erledig\'n.', 28153),
(153476, 'deDE', '', 'Fordert Bwonsamdi nicht zum Tanz, $n.', 28153),
(153475, 'deDE', '', 'Beißt die Zähne zusamm\'n.', 28153),
(153474, 'deDE', '', 'Erhebt Euch, $n. Wir sin\' noch nich\' fertig.', 28153),
(153473, 'deDE', '', 'Mein Loa lässt Euch nich\' im Stich, $n!', 28153),
(153472, 'deDE', 'Offenbar waren unsere Informationen falsch, dass alle Sethrak böse sind.', 'Offenbar waren unsere Informationen falsch, dass alle Sethrak böse sind.', 28153),
(153471, 'deDE', 'Dieses Spiel kann ich auch spielen!', 'Dieses Spiel kann ich auch spielen!', 28153),
(153470, 'deDE', '', 'Das neue Trollimperium wird sich erheb\'n. Unser ewiger Stillstand is\' vorbei!', 28153),
(153469, 'deDE', '', 'Zul hat den Tag komm\' seh\'n. Erhebt Euch... Jünger des Blutes. Folgt dieser Welt in \'n neues Zeitalter!', 28153),
(153468, 'deDE', 'Nein! Nein...', 'Nein! Nein...', 28153),
(153467, 'deDE', 'Wie könnt Ihr es wagen, meinen Anteil zu nehmen...', 'Wie könnt Ihr es wagen, meinen Anteil zu nehmen...', 28153),
(153466, 'deDE', 'Auch Ihr kriegt noch... was Ihr verdient...', 'Auch Ihr kriegt noch... was Ihr verdient...', 28153),
(153465, 'deDE', 'Helden, folgt mir!', '', 28153),
(153464, 'deDE', 'Ich... werde... Euch... kriegen...', 'Ich... werde... Euch... kriegen...', 28153),
(153463, 'deDE', 'Ihr seid tot! Ihr seid alle tot!', 'Ihr seid tot! Ihr seid alle tot!', 28153),
(153462, 'deDE', 'Ihr denkt, Ihr könntet Euch einfach meinen Anteil nehmen?', 'Ihr denkt, Ihr könntet Euch einfach meinen Anteil nehmen?', 28153),
(153461, 'deDE', 'Verräter! Ich werde mir Eure Köpfe holen!', 'Verräter! Ich werde mir Eure Köpfe holen!', 28153),
(153460, 'deDE', 'Ihr seid alle Verräter!', 'Ihr seid alle Verräter!', 28153),
(153459, 'deDE', 'Käpt\'n Eudora... führt uns zum Sieg...', '', 28153),
(153458, 'deDE', 'Frischfleisch? Bilgeratten! Es ist Essenszeit!', '', 28153),
(153457, 'deDE', 'Heute, wenn der Lärm der Schlacht erklingt, werd\'n die Loa zuhör\'n! Und die Gefall\'nen werd\'n ihnen folg\'n... ins Jenseits.', '', 28153),
(153456, 'deDE', 'Gewährt ihr einen ehrenhaften Tod...', '', 28153),
(153455, 'deDE', 'Gewährt ihm einen ehrenhaften Tod...', '', 28153),
(153454, 'deDE', 'Ahhhh?!', '', 28153),
(153453, 'deDE', 'Ins Jenseits...', '', 28153),
(153452, 'deDE', 'Ihr hattet heute nich\' den Segen der Loa.', '', 28153),
(153451, 'deDE', 'Für Zandalar!', '', 28153),
(153450, 'deDE', 'Verkauft! Ein chromatisches Schwert für 281 Gold! Mit dieser Klinge bleibt Ihr bestimmt nicht lange unauffällig!', '', 28153),
(153449, 'deDE', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t Ihr seid im Visier einer |cFFFF0000|Hspell:260838|h[Zielsuchrakete]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t Ihr seid im Visier einer |cFFFF0000|Hspell:260838|h[Zielsuchrakete]|h|r!', 28153),
(153448, 'deDE', 'Was für ein Tag für Kul Tiras!', '', 28153),
(153447, 'deDE', 'Heute fliegen im wahrsten Sinne des Wortes die Fetzen!', '', 28153),
(153446, 'deDE', 'Noch ist nichts entschieden, es wird noch spannend!', '', 28153),
(153445, 'deDE', 'Ruhe, Ruhe! Der Kampf ist noch nicht vorbei.', '', 28153),
(153444, 'deDE', 'Ihr bekommt noch genug Blut zu sehen, keine Sorge!', '', 28153),
(153443, 'deDE', 'Verkauft! Ein verfluchtes Andenken für 18 Gold! Ich würde dafür ja nicht mal ein Kupferstück hinlegen, aber es ist ja auch nicht mein Geld!', '', 28153),
(153442, 'deDE', 'Nein, nein, nein. Gut gerettet, gut gerettet.', '', 28153),
(153441, 'deDE', 'Ihr sterbt... aber nicht als wahrer Kul Tiraner.', '', 28153),
(153440, 'deDE', 'Hoppla!', '', 28153),
(153439, 'deDE', 'Was für eine Nacht für Kul Tiras!', '', 28153),
(153438, 'deDE', 'Das wird kein sauberer Kampf, also haltet besser Abstand! Nun gut, sind alle bereit?', '', 28153),
(153437, 'deDE', 'Nur wer am Ende noch steht, hat diesen Titel verdient.', '', 28153),
(153436, 'deDE', 'Freunde! Wir sind hier, um zu herauszufinden, wer von diesen Banditen, diesen Schlägern, diesen Nichtsnutzen ein echter Kul Tiraner ist!', '', 28153),
(153435, 'deDE', 'Verkauft! Eine große Liebesrakete geht für 1.412 Gold an die reizende Dame! Sie wird jetzt bestimmt zum Stadtgespräch!', '', 28153),
(153434, 'deDE', 'Verkauft! Die Schulterstücke des Schreckenspanzers gehen für 756 Gold an den jungen Mann in der vorderen Reihe! Er wird sie vermutlich nicht tragen können, aber was soll\'s!', '', 28153),
(153433, 'deDE', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Azerokk wirkt |cFFFF0000|Hspell:257597|h[Azeritinfusion]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Azerokk wirkt |cFFFF0000|Hspell:257597|h[Azeritinfusion]|h|r!', 28153),
(153432, 'deDE', 'Verrat! Ergreift sie!', '', 28153),
(153431, 'deDE', 'Dieser Schlüssel darf Korthek auf keinen Fall in die Hände geraten. Kommt, unser Tempel liegt gleich voraus.', '', 28153),
(153430, 'deDE', 'Ich habe ihn einem Gefangenen in die Tasche geschmuggelt, den sie gerade gefasst hatten. Ich glaube, er nannte sich James.', '', 28153),
(153429, 'deDE', 'Diese Narren! Bei meiner Gefangennahme durchsuchten sie mich, aber ich hatte ihn bereits an einem Ort versteckt, an dem sie nie danach suchen würden.', '', 28153),
(153428, 'deDE', 'Doch Korthek verriet uns und Sulthis wurde getötet. Nun sind Korthek und seine Anhänger, die Treulosen, auf der Jagd nach mir und meinem Schlüssel.', '', 28153),
(153427, 'deDE', 'Vor langer Zeit führten wir drei – Korthek, Sulthis und ich – unser Volk gemeinsam an. Unser Loa vertraute uns drei Schlüssel an, die eine alte und böse Macht unter dem Sand gefangen halten.', '', 28153),
(153426, 'deDE', 'Unser Tempel ist die letzte Bastion gegen die Treulosen.', '', 28153),
(153425, 'deDE', '', 'Ja, ja. Also vielleicht ham wir hier unt\'n \'n klitzekleines Problem. Nix, womit wir den König belästig\'n müss\'n.', 28153),
(153424, 'deDE', '', 'Die Zeit für Verhandlung\'n mit den Loa is\' vorbei. Die Zeit für Blut is\' gekomm\'.', 28153),
(153423, 'deDE', '', 'Schert Euch nich\' um \'n paar Gaunerei\'n. Wir müss\'n uns um weit wichtigere Sach\'n kümmern.', 28153),
(153421, 'deDE', '', 'Hoffentlich schmecken sie Euch!', 28153),
(153419, 'deDE', '', 'Hier, bitte. Ich konnte Euch ja schließlich nicht hungrig losziehen lassen, oder?', 28153),
(153418, 'deDE', '', 'Ahhh, die sind einfach perfekt!', 28153),
(153417, 'deDE', '', 'Einen Augenblick, $gmein Lieber:meine Liebe;... Ich habe etwas für Euch.', 28153),
(153416, 'deDE', 'Gut gemacht! Das Zandalariimperium wird sich nicht so schnell von Eurem Schlag erholen!', '', 28153),
(153415, 'deDE', 'Ich entscheide mich für Pa\'ku, Herrin der Winde.', 'Ich entscheide mich für Pa\'ku, Herrin der Winde.', 28153),
(153414, 'deDE', 'Ich entscheide mich für Gonk, Anführer des Rudels.', 'Ich entscheide mich für Gonk, Anführer des Rudels.', 28153),
(153413, 'deDE', 'Die Zandalari halten eine abgerichtete Bestie an der Leine und glauben, dass sie sie schützen kann. Beweist ihnen das Gegenteil!', '', 28153),
(153412, 'deDE', 'Endlich gehört Stromgarde wieder seinen rechtmäßigen Besitzern.', '', 28153),
(153411, 'deDE', 'Sterbt, Gesindel!', '', 28153),
(153410, 'deDE', 'Ihr habt es so gewollt.', '', 28153),
(153409, 'deDE', 'Euch wird niemand vermissen.', '', 28153),
(153408, 'deDE', 'Eines Tages wird Stromgarde wieder der Allianz gehören.', '', 28153),
(153407, 'deDE', 'Lasst den Tod auf die Horde niederregnen!', '', 28153),
(153406, 'deDE', 'Dritte Division, Feuer!', '', 28153),
(153405, 'deDE', 'Ich würde gerne den hier repräsentierten Loa aus Zuldazar wechseln.', 'Ich würde gerne den hier repräsentierten Loa aus Zuldazar wechseln.', 28153),
(153404, 'deDE', 'Schützen, lasst Eure Pfeile fliegen!', '', 28153),
(153403, 'deDE', 'Erwacht, Ihr Echos der Vergangenheit!', '', 28153),
(153402, 'deDE', 'Die Geister Arathors werden Euch vernichten!', '', 28153),
(153401, 'deDE', 'Das Böse wird sich nicht verstecken können, selbst hier nicht. Ihr habt Euch gut geschlagen.', '', 28153),
(153400, 'deDE', 'Erhebt Euch, meine Ahnen, und verteidigt Eure Heimat.', '', 28153),
(153399, 'deDE', 'Ich habe tausende Euresgleichen getötet. Ihr seid nicht anders.', '', 28153),
(153398, 'deDE', 'Und noch \'n Sieg für das Zandalariimperium! Gut gemacht, Champion der Horde.', '', 28153),
(153397, 'deDE', 'Etwas Böses schwärt an diesem wilden Ort. Sorgt dafür, dass es verschwindet!', '', 28153),
(153396, 'deDE', 'Dieses Gebiet wird von einer der stärkst\'n Kreatur\'n des Dschungels bedroht. Spürt sie auf un\' erledigt sie!', '', 28153),
(153395, 'deDE', 'Die Gerechten werden immer siegen!', '', 28153),
(153394, 'deDE', 'Geläutert!', '', 28153),
(153393, 'deDE', 'Euer Schicksal ist entschieden.', '', 28153),
(153392, 'deDE', 'Ihr wurdet gerichtet.', '', 28153),
(153391, 'deDE', 'Stromgarde ist verloren, aber die Allianz wird niemals fallen!', '', 28153),
(153390, 'deDE', 'Bei der Macht des Lichts!', '', 28153),
(153389, 'deDE', 'Verkriecht Euch vor dem Licht, Ungeziefer!', '', 28153),
(153388, 'deDE', 'Das Licht wird Euch versengen.', '', 28153),
(153387, 'deDE', 'Eine weitere ausgemerzte Bedrohung... und ein weiterer Sieg für die Allianz!', '', 28153),
(153386, 'deDE', 'Das Licht wird triumphieren!', '', 28153),
(153385, 'deDE', '', 'Ich bin die erste Chronistin. Der König hat mich ausgewählt, um unsre Geschichte in Stein zu meiß\'ln, damit sie für immer erhalt\'n bleibt.', 28153),
(153384, 'deDE', 'Das Licht wird Euch reinigen!', '', 28153),
(153383, 'deDE', 'Mein Volk wird sich an Euern Nam\'n als Champion der Zandalari erinnern. Gut gemacht!', '', 28153),
(153382, 'deDE', 'Möge das Licht Euch läutern!', '', 28153),
(153381, 'deDE', 'Für das Licht!', '', 28153),
(153380, 'deDE', 'Das Böse gedeiht in diesem Land so mühelos wie eine erstickende Ranke. Schneidet sie zurück und schützt unsere Truppen.', '', 28153),
(153379, 'deDE', 'Ich werd nich\' zulass\'n, dass mein Volk durch dies\'n Feind bedroht wird. Vernichtet ihn!', '', 28153),
(153378, 'deDE', 'Jetzt, da der Weg frei ist, können wir uns wieder ganz dem Kampf gegen die Zandalari widmen. Danke, Champion.', '', 28153),
(153377, 'deDE', 'Ein weiterer Feind, der im Nam\'n des Zandalariimperiums unterworf\'n wurde.', '', 28153),
(153376, 'deDE', 'Unsere Truppen werden von dieser widerlichen Kreatur bedroht. Beseitigt sie, für die Allianz!', '', 28153),
(153375, 'deDE', 'Ich werd diese Bedrohung nich\' innerhalb meiner Grenzen tolerier\'n. Sorgt dafür, dass sie ausgelöscht wird!', '', 28153),
(153374, 'deDE', 'Springt auf das Trike, wenn Ihr abfahrbereit seid.', '', 28153),
(153372, 'deDE', '', 'Diese Naga haben Angst. Irgendetwas anderes treibt sie an, nicht nur treue Ergebenheit für Königin Azshara.', 28153),
(153371, 'deDE', '', 'Grüße.', 28153),
(153370, 'deDE', 'War das schon alles? Ha! Gebt mir mal eine richtige Herausforderung!', '', 28153),
(153369, 'deDE', 'Mann, das macht Spaß!', '', 28153),
(153368, 'deDE', 'Das macht Ihr nicht noch mal.', '', 28153),
(153367, 'deDE', 'Grüßt Eure Vorfahren von mir!', '', 28153),
(153366, 'deDE', 'Ihr werdet nicht ungestraft davonkommen!', '', 28153),
(153365, 'deDE', 'Schön mit viel Schwung.', '', 28153),
(153364, 'deDE', 'Ha-ha-ha! So geht das!', '', 28153),
(153363, 'deDE', 'Haut ab!', '', 28153),
(153362, 'deDE', 'Für Khaz Modan!', '', 28153),
(153361, 'deDE', 'Hab was für Euch!', '', 28153),
(153360, 'deDE', 'Der ist für Euch!', '', 28153),
(153359, 'deDE', 'Heda, fangt!', '', 28153),
(153357, 'deDE', 'Euer Kampf ist zu Ende!', '', 28153),
(153351, 'deDE', 'Magni, was will Azeroth mir geben?', 'Magni, was will Azeroth mir geben?', 28153),
(153350, 'deDE', 'Nun, da die Gorillas zurückgeschlagen sind, können wir uns wieder auf die Horde konzentrieren. Gut gemacht.', '', 28153),
(153349, 'deDE', 'Diese Gorillas haben die Essenz des Kaja\'mits absorbiert und dadurch eine bemerkenswerte Intelligenz erlangt. Wir dürfen nicht zulassen, dass sie sich über ihre Schlucht hinaus ausbreiten.', '', 28153),
(153348, 'deDE', 'Abschuss von A.T.O.M.I.K. festgestellt.', 'Abschuss von A.T.O.M.I.K. festgestellt.', 28153),
(153347, 'deDE', 'Die Horde ist wirklich tief gesunken, wenn sie glaubt, dass sie uns zu Gefangenen machen kann. Dank Euch sind unsere Leute frei. Gut gemacht!', '', 28153),
(153346, 'deDE', 'Ich kann nicht ruhen, solange einer meiner Männer noch da draußen ist.', 'Ich kann nicht ruhen, solange einer meiner Männer noch da draußen ist.', 28153),
(153345, 'deDE', 'Sie werden uns niemals kommen hören. Hahaha! Ihr habt meinen Dank, Champion.', '', 28153),
(153344, 'deDE', 'Die Horde glaubt, dass sie unsere Stellung hier in Zuldazar ausspionieren kann, aber da liegt sie falsch! Lasst ihnen die Ohren klingeln und sendet die Nachricht, dass die Allianz niemals ins Wanken gerät.', '', 28153),
(153343, 'deDE', 'Ohne einen Schlüssel setze ich keinen Fuß mehr in so ein Ding!', 'Ohne einen Schlüssel setze ich keinen Fuß mehr in so ein Ding!', 28153),
(153342, 'deDE', 'Noch eine Minute länger in diesem Ding, und es hätte übel ausgehen können!', 'Noch eine Minute länger in diesem Ding, und es hätte übel ausgehen können!', 28153),
(153341, 'deDE', 'Warum hat uns Thurgaden so lange in diesen Blechdosen schmoren lassen? Pah!', 'Warum hat uns Thurgaden so lange in diesen Blechdosen schmoren lassen? Pah!', 28153),
(153340, 'deDE', 'Da drinnen war es heißer als in Ragnaros\' feurigem Hintern!', 'Da drinnen war es heißer als in Ragnaros\' feurigem Hintern!', 28153),
(153339, 'deDE', 'Ich habe einen Burschen losgeschickt, um Wyrmbann darüber zu informieren, dass wir hier alles im Griff haben. Danke für die Hilfe, $n.', '', 28153),
(153338, 'deDE', 'Das war doch ganz normale Arbeit!', '', 28153),
(153337, 'deDE', 'Das war echt fürchterlich!', '', 28153),
(153336, 'deDE', 'Wir ziehen Kraft aus den Feuerlanden, aber diesem Ruf wird nichts Gefährliches Folge leisten.', '', 28153),
(153335, 'deDE', 'Nur die Ruhe, Thaelin. Ich bin nicht so dumm, wie Zaubererthan Thaurissan es war.', '', 28153),
(153334, 'deDE', 'Seid vorsichtig, was Ihr herbeiruft, Ambossthan.', '', 28153),
(153333, 'deDE', 'Eine echt gute Beschwörung, Jungs. Ihr habt jetzt die Kontrolle, $n. Zeigt dieser Hordentruppe, was passiert, wenn man sich mit den Dunkeleisenzwergen anlegt!', '', 28153),
(153332, 'deDE', '$C, legt etwas von der Schlacke auf das instabile Magma dort drüben. Und macht Euch auf etwas gefasst!', '', 28153),
(153331, 'deDE', 'Die Schlacht um Stromgarde hat begonnen!', '', 28153),
(153330, 'deDE', 'Die Schlacht um Stromgarde beginnt in 30 Sekunden.', '', 28153),
(153329, 'deDE', 'Klar, kein Problem.', '', 28153),
(153328, 'deDE', 'Moment, Ihr habt den Schlüssel für Euch behalten?', '', 28153),
(153327, 'deDE', 'Meine Schamanen hocken wohl immer noch in den Maulwurfmaschinen. Ich wusste, ich hab was vergessen.', '', 28153),
(153326, 'deDE', 'Unsere Anfänge hier sind schon vielversprechend. Was fehlt noch?', '', 28153),
(153325, 'deDE', 'Ihr habt keine Ahnung von den Mächten, die hier am Werk sind, Kindchen.', '', 28153),
(153324, 'deDE', '<Streckt Eure Hand hinein und zieht etwas heraus, das sich mehr wie ein Gebäude anfühlt.>', '<Streckt Eure Hand hinein und zieht etwas heraus, das sich mehr wie ein Gebäude anfühlt.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'deDE', '<Streckt Eure Hand hinein und zieht etwas heraus.>', '<Streckt Eure Hand hinein und zieht etwas heraus.>', 28153),
(153322, 'deDE', '<Ein Wurmloch erstreckt sich vor Euren Augen. Ihr solltet es irgendwie nutzen können, um ein Gebäude zu erschaffen.>', '', 28153),
(153321, 'deDE', 'Strapaziert nicht meine Geduld, Abschaum. Sterbt.', '', 28153),
(153320, 'deDE', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t %s beginnt, |cFFFF0000|Hspell:264382|h[Augenstrahl]|h|r zu wirken!', 'Eine Projektion erscheint in der Ferne...', 28153),
(153319, 'deDE', 'Das Meer is\' unsre Heimat. Da draußen is\' was, das uns fernhält. Ich hoffe, Ihr kümmert Euch drum!', '', 28153),
(153318, 'deDE', 'Ihr wollt zu den Suchern, hm? Die sin\' verlässlich, dort solltet Ihr sicher sein.', '', 28153),
(153317, 'deDE', 'Schiffe verschwind\'n. Stürme komm\'n, wo es vorher keine gab. Andere hab\'n Angst, aufs Wasser zu geh\'n.', '', 28153),
(153316, 'deDE', 'Es gab Gerüchte, dass an der Küste merkwürdige Dinge passier\'n.', '', 28153),
(153315, 'deDE', 'Wie Ihr wünscht.', '', 28153),
(153314, 'deDE', 'Und bitte... achtet auf Jaina.', '', 28153),
(153313, 'deDE', 'Errichtet einen Stützpunkt in Kul Tiras. Dieser Plan darf nicht scheitern.', '', 28153),
(153312, 'deDE', 'Dann eskortiert sie mit einem Schiff der 7. Legion.', '', 28153),
(153311, 'deDE', 'Hmpf. Mich kann nichts erschüttern.', '', 28153),
(153310, 'deDE', 'Mögen sich die Tiefen von Euch abwenden, wie Ihr von Eurem Volk.', '', 28153),
(153309, 'deDE', 'Euch treibt nichts als Hass und Schmerz.', '', 28153),
(153308, 'deDE', 'Hört das Erwachen des Sturms und begrüßt Euer Ende.', '', 28153),
(153307, 'deDE', 'Fürchtet nicht, denn Euer Urteil ist nah.', '', 28153),
(153306, 'deDE', 'Genn... wie seefest seid Ihr?', '', 28153),
(153305, 'deDE', 'Hört die Schreie unseres Volkes und wisset, Eure Zeit ist gekommen.', '', 28153),
(153304, 'deDE', 'Für Euch gibt es keine Erlösung.', '', 28153),
(153303, 'deDE', 'Ihr wurdet für unzulänglich befunden.', '', 28153),
(153302, 'deDE', 'Möge Eure Seele sich in Ewigkeit verzehren.', '', 28153),
(153301, 'deDE', '', 'Sobald ich eine Waffe in die Finger bekomme...', 28153),
(153300, 'deDE', '', 'Ihr erster Fehler war, dass sie mich nicht getötet haben.', 28153),
(153299, 'deDE', '', 'Erst verwüsten sie meinen Hof, und dann entführen sie mich auch noch. Aber damit lasse ich sie nicht ungeschoren davonkommen!', 28153),
(153298, 'deDE', 'Ich gehe hier nicht weg, bis wir uns um diese Bedrohung gekümmert haben!', 'Ich gehe hier nicht weg, bis wir uns um diese Bedrohung gekümmert haben!', 28153),
(153297, 'deDE', 'Sie werden für ihre Taten büßen!', 'Sie werden für ihre Taten büßen!', 28153),
(153296, 'deDE', 'Ich schulde diesen Stachelebern eine Tracht Prügel!', 'Ich schulde diesen Stachelebern eine Tracht Prügel!', 28153),
(153295, 'deDE', '', 'Kommt bald wieder und lasst uns feilschen.', 28153),
(153294, 'deDE', '', 'Endlich frei! Diesen dreckigen Schweinen werde ich zeigen, was passiert, wenn man sich mit mir und meinem Hof anlegt!', 28153),
(153293, 'deDE', 'Heyyy, da ist ja jemand aufgewacht.', '', 28153),
(153292, 'deDE', 'Vertraut... ihr nicht... der To-hochter der See... hmm hmm...', '', 28153),
(153291, 'deDE', 'H-Haltet... H-Haltet mir das vom Leib. I-Ich will höchstens... beim Saufen... ertrinken! *Hicks*!', 'H-Haltet... H-Haltet mir das vom Leib. I-Ich will höchstens... beim Saufen... ertrinken! *Hicks*!', 28153),
(153290, 'deDE', 'Der Mann meiner Schwester gab ihr einen Meeresstängel, bevor er eine viermonatige Seereise antrat. Die Blume verwelkte schon am dritten Tag und meine Schwester war außer sich vor Trauer. Aber da sie schon früh Bescheid wusste, konnte sie sich ihr Geld einteilen, um für ihre Kinder zu sorgen.', 'Der Mann meiner Schwester gab ihr einen Meeresstängel, bevor er eine viermonatige Seereise antrat. Die Blume verwelkte schon am dritten Tag und meine Schwester war außer sich vor Trauer. Aber da sie schon früh Bescheid wusste, konnte sie sich ihr Geld einteilen, um für ihre Kinder zu sorgen.', 28153),
(153289, 'deDE', 'Wir haben oben Pritschen aufgebaut und unten ist Platz für Eure Ausrüstung.\n\nEs ist nicht üppig, aber immer noch besser als da draußen bei den Hexen.', 'Wir haben oben Pritschen aufgebaut und unten ist Platz für Eure Ausrüstung. Es ist nicht üppig, aber immer noch besser als da draußen bei den Hexen.', 28153),
(153288, 'deDE', 'Manche Matrosen betrachten sie als Unglücksbringer oder gar eine Herausforderung an das Schicksal. Andere wiederum wollen einfach, dass ihre Liebsten nicht auf schlechte Nachrichten warten müssen. Ich kann beides verstehen.', 'Manche Matrosen betrachten sie als Unglücksbringer oder gar eine Herausforderung an das Schicksal. Andere wiederum wollen einfach, dass ihre Liebsten nicht auf schlechte Nachrichten warten müssen. Ich kann beides verstehen.', 28153),
(153287, 'deDE', 'Denkt daran, dass, solange die Bäume stehen, wir es ihnen gleichtun müssen. Wir können unsere Leben hier nicht wegwerfen.', '', 28153),
(153286, 'deDE', 'Wir wollen versuchen, unsere Leute zu finden. Zusammen können wir vielleicht etwas von dem Leid Drustvars heilen.', '', 28153),
(153285, 'deDE', '', 'Aber...!', 28153),
(153284, 'deDE', 'Wir haben alles, was in diesem Hain wichtig war, Setzling. Hätten die Fungianer nicht angegriffen, hätte uns die Verderbnis aus dem Süden wohl erreicht.', '', 28153),
(153283, 'deDE', '', 'Auf den Weg? Wohin? Der Eschenwaldhain ist unser Zuhause, Morwin. Und er ist mit Sporen übersät! Wir können hier nicht einfach weg!', 28153),
(153282, 'deDE', 'Gut gemacht, Amalie. Und jetzt sollten wir uns wohl auf den Weg machen.', '', 28153),
(153278, 'deDE', 'Was könnt Ihr mir über diesen Meeresstängel sagen?', 'Was könnt Ihr mir über diesen Meeresstängel sagen?', 28153),
(153277, 'deDE', 'Trommeln', 'Trommeln', 28153),
(153276, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Zuldazar!', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Zuldazar!', 28153),
(153275, 'deDE', 'Ah, ich komme wieder zu Kräften!', '', 28153),
(153274, 'deDE', 'Es war ziemlich ruhig hier. Dann gab es einen Sturm. Die anderen Sucher kommen nicht mehr wieder, $C. Was ist da draußen los?', '', 28153),
(153273, 'deDE', 'Ich danke Euch vielmals. Für Eure Mühen überlasse ich Euch gern etwas von meinem persönlichen Besitz. Und nun muss ich scheiden. Adieu!', '', 28153),
(153272, 'deDE', 'Meine Güte, ich stecke in einer verzwickten Situation. Seid doch so freundlich und helft mir.', '', 28153),
(153271, 'deDE', 'Ah, das ist aber wirklich ganz reizend von Euch. Hier ist etwas für Euch. Tschüssi!', 'Ah, das ist aber wirklich ganz reizend von Euch. Hier ist etwas für Euch. Tschüssi!', 28153),
(153270, 'deDE', '', 'Ihr da! Seid so lieb und helft mir hier mal! Ich bin alleine und schon ganz verzweifelt!', 28153),
(153269, 'deDE', 'Also, mein ganzes Azerit kann ich Euch nicht geben, aber hier ist genug, um Euch gebührend zu danken. Und jetzt lasst mich in Ruhe.', '', 28153),
(153268, 'deDE', 'Heda! Könnt Ihr mir mal aus der Klemme helfen?', '', 28153),
(153267, 'deDE', 'Schaut, es ist nur ein Kostüm! Seht Ihr? Fasst es doch an!$b$bKönnt Ihr ihnen jetzt vielleicht sagen, dass sie mich hier rauslassen sollen? Es war doch nur ein Spaß! Hogger hat Sturmwind nicht wirklich terrorisiert!', 'Schaut, es ist nur ein Kostüm! Seht Ihr? Fasst es doch an!$b$bKönnt Ihr ihnen jetzt vielleicht sagen, dass sie mich hier rauslassen sollen? Es war doch nur ein Spaß! Hogger hat Sturmwind nicht wirklich terrorisiert!', 28153),
(153266, 'deDE', '', 'Ich danke Euch! Und jetzt wollt Ihr wohl was von meinem Azerit, oder? Das finde ich aber auch in Ordnung.', 28153),
(153265, 'deDE', '', 'Hey, da! Ob Ihr mir wohl mal hier raushelfen könntet?', 28153),
(153264, 'deDE', '', 'Wahrscheinlich habe ich das verdient.', 28153),
(153263, 'deDE', '', 'Ich bin bereit, die Konsequenzen zu tragen...', 28153),
(153262, 'deDE', 'Sie kommt zurück, um\'s zu Ende zu bringen!', '', 28153),
(153261, 'deDE', 'Mörderin!', 'Mörderin!', 28153),
(153260, 'deDE', 'Verräterin!', 'Verräterin!', 28153),
(153259, 'deDE', 'Es ist die Tochter der See!', '', 28153),
(153258, 'deDE', '', 'Lady Jaina... ist sie das wirklich?', 28153),
(153257, 'deDE', '', 'Komm jetzt, wir gehen heim. Sofort!', 28153),
(153256, 'deDE', 'Mama, wer ist die Frau?', 'Mama, wer ist die Frau?', 28153),
(153255, 'deDE', 'Specki... das war ja eine Sauerei mit diesen Pilzen...', '', 28153),
(153254, 'deDE', 'Mein Kopf... Was ist mit meinen Schweinen geschehen?!', '', 28153),
(153253, 'deDE', 'Ich werde allen die Geschichte von Eurem großen Sieg heute erzählen. Also... äh... sorgt dafür, dass Ihr auch gewinnt!', '', 28153),
(153252, 'deDE', 'Kehrt in den Blutroten Wald zurück!', 'Kehrt in den Blutroten Wald zurück!', 28153),
(153250, 'deDE', 'Schafft die Zivilisten da weg! Sichert den Bereich!', '', 28153),
(153249, 'deDE', '%s flieht.', '%s flieht.', 28153),
(153248, 'deDE', '', 'Und jetzt sehen sie mich als Verbrecherin.', 28153),
(153247, 'deDE', '', 'Ich sehe, die Stadtwache ist diszipliniert wie eh und je. Mein Vater war so stolz auf sie.', 28153),
(153246, 'deDE', 'Hetz mich nicht! Ich versuche gerade, dein Herrchen zu retten!', '', 28153),
(153245, 'deDE', 'Heda, $n! Hier drüben!', 'Heda, $n! Hier drüben!', 28153),
(153244, 'deDE', 'Das hat mir grad noch gefehlt! Ich bin auf\'m Weg nach Dol\'watha un\' mein Tier wird krank. Wie sag\'n noch alle? Wenn die Dinge schiefgeh\'n, dann richtig.', '', 28153),
(153243, 'deDE', 'Ich bin Rally!', 'Ich bin Rally!', 28153),
(153242, 'deDE', 'So viele Hordenköpfe, die man da draußen einschlagen kann. Lasst mir ein paar übrig, ja?', 'So viele Hordenköpfe, die man da draußen einschlagen kann. Lasst mir ein paar übrig, ja?', 28153),
(153241, 'deDE', 'Lassen wir es leiden.', 'Lassen wir es leiden.', 28153),
(153240, 'deDE', 'Unser Befehl lautet, es zu töten.', 'Unser Befehl lautet, es zu töten.', 28153),
(153239, 'deDE', '', 'Bleibt dicht bei mir. Wir dürfen nicht entdeckt werden.', 28153),
(153238, 'deDE', '', 'Bleibt bei der Sache. $n.', 28153),
(153237, 'deDE', '', 'Legt Ihr es darauf an, uns zu verraten?', 28153),
(153236, 'deDE', 'He, Boris... Ich glaub unsere Zeiten als Langfinger sind vorbei...', '', 28153),
(153235, 'deDE', 'Lasst Eure Finger von meinem Greifen!', '', 28153),
(153234, 'deDE', 'So habe ich mir das vorgestellt. Seht Euch all dieses Azerit an!', '', 28153),
(153233, 'deDE', 'Boss! Da seid Ihr ja!', '', 28153),
(153231, 'deDE', 'Aus dem Weg! Wir haben gefährliche Gefangene bei uns!', '', 28153),
(153230, 'deDE', 'Halt! Was sind Eure Absichten?', '', 28153),
(153229, 'deDE', '', 'Das ist nicht der Moment für Ausflüge.', 28153),
(153228, 'deDE', 'Sch-Schnauze!', '', 28153),
(153227, 'deDE', 'Oooh... Das war vielleicht eine HEXE!', '', 28153),
(153226, 'deDE', 'Noch einer von Euren Spähern, Gallywix... und dieser ist tot.', '', 28153),
(153225, 'deDE', 'Wir müssen ins Herz der Stadt vordringen, um die restlichen Einwohner in Sicherheit zu bringen!', '', 28153),
(153224, 'deDE', 'V-Vorsicht...', '', 28153),
(153223, 'deDE', '', 'Wir sind fast da! Beeilt Euch, Helden!', 28153),
(153222, 'deDE', '', 'Nicht stehen bleiben!', 28153),
(153220, 'deDE', 'Champions, zu mir! Der Kriegshäuptling beordert uns in den hinteren Burghof!', '', 28153),
(153217, 'deDE', '', 'Wo ist Saurfang hin?', 28153),
(153216, 'deDE', 'Seid vorsichtig! Die Senkefelder sind immer noch gefährlich! Die Straße zur Rechten sollte etwas sicherer sein und Euch zur Windmühle bringen. Deikes Hof liegt gleich dahinter.', '', 28153),
(153215, 'deDE', '', 'Wenn Ihr kämpfen könnt, würde ich etwas Hilfe durchaus begrüßen.', 28153),
(153214, 'deDE', '', 'Ich hab keine Tränke mehr und zwischen hier und meinem Wagen lauert da ein ganzer Haufen Sethrak.', 28153),
(153213, 'deDE', '', 'Seid Ihr noch am Leben? Wie gut könnt Ihr mit Eurer Waffe umgehen?', 28153),
(153212, 'deDE', '', 'Nicht heute, Ihr Schuppenköpfe!', 28153),
(153211, 'deDE', 'Bitte bringt mich zum Eingang zurück.', 'Bitte bringt mich zum Eingang zurück.', 28153),
(153210, 'deDE', 'Der Avatar von Sethraliss wurde durch die gemeinsamen Anstrengungen von Euch und Euren Verbündeten wieder verjüngt.', 'Der Avatar von Sethraliss wurde durch die gemeinsamen Anstrengungen von Euch und Euren Verbündeten wieder verjüngt.', 28153),
(153209, 'deDE', 'Magni, schickt mich zurück nach Zandalar.', 'Magni, schickt mich zurück nach Zandalar.', 28153),
(153207, 'deDE', 'Ah, das hier wird uns zu unserem Ziel bringen! Kommt mit, Champion.', '', 28153),
(153206, 'deDE', 'Besiegt alle verbleibenden Eindringlinge.', 'Besiegt alle verbleibenden Eindringlinge.', 28153),
(153205, 'deDE', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tDer Avatar schließt sich Euch an und |cFFFF0000|Hspell:269670|h[Ermächtigt]|h|r Euch, den Kampf zu beenden!', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tDer Avatar schließt sich Euch an und |cFFFF0000|Hspell:269670|h[Ermächtigt]|h|r Euch, den Kampf zu beenden!', 28153),
(153204, 'deDE', '<Vor Euch seht Ihr den Avatar von Sethraliss. Sie lebt, ist aber durch die Einmischung der Trolle stark geschwächt. Überall um Euch herum beginnen uralte defensive Zauberschutze flackernd zum Leben zu erwachen...>', '<Vor Euch seht Ihr den Avatar von Sethraliss. Sie lebt, ist aber durch die Einmischung der Trolle stark geschwächt. Überall um Euch herum beginnen uralte defensive Zauberschutze flackernd zum Leben zu erwachen...>', 28153),
(153203, 'deDE', '|cffffff00+$1i Holz|r', '|cffffff00+$1i Holz|r', 28153),
(153202, 'deDE', 'Ihr hört die Prinzessin! Lasst es krachen!', '', 28153),
(153201, 'deDE', '', 'Der Schild! Er nimmt ab!', 28153),
(153199, 'deDE', 'Kein Grund zur Panik! Mein Erscheinen war wohl etwas abrupt... Ich bin Magni Bronzebart – und ich spreche für Azeroth.', '', 28153),
(153198, 'deDE', '', 'Ah, da seid Ihr ja, $n. Kommt, wir haben Dinge zu bered\'n.', 28153),
(153197, 'deDE', 'Ah, da seid Ihr ja, $n. Ich muss Euch sprechen!', '', 28153),
(153196, 'deDE', '[Audienz bei Katherine - Jaina legt ihr Schicksal in Katherines Hände. Von Lady Aschenwind dazu gedrängt, Jaina als Verräterin zu behandeln, lässt Katherine es zu, dass Jaina vor Gericht gebracht wird. \"Für mich ist sie bereits tot.\" Der Spielercharakter wird festgenommen.]', '[Audienz bei Katherine - Jaina legt ihr Schicksal in Katherines Hände. Von Lady Aschenwind dazu gedrängt, Jaina als Verräterin zu behandeln, lässt Katherine es zu, dass Jaina vor Gericht gebracht wird. \"Für mich ist sie bereits tot.\"]', 28153),
(153195, 'deDE', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t Ihr seid Ziel von |cFFFF0000|Hspell:265212|h[Heranwachsen]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t Ihr seid Ziel von |cFFFF0000|Hspell:265212|h[Heranwachsen]|h|r!', 28153),
(153194, 'deDE', 'Wir werden Euch wiederherstellen!', 'Wir werden Euch wiederherstellen!', 28153),
(153193, 'deDE', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Vectis beginnt, |cFFFF0000|Hspell:265217|h[Verflüssigen]|h|r zu wirken!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Vectis beginnt, |cFFFF0000|Hspell:265217|h[Verflüssigen]|h|r zu wirken!', 28153),
(153192, 'deDE', 'Beachtet Gallywix gar nicht. Wir sind unterwegs nach Drustvar, um die Stellungen unserer Feinde auszuspähen. Gewinn ist zweitrangig.', '', 28153),
(153191, 'deDE', 'Der Rest ist... Schweigen.', '', 28153),
(153190, 'deDE', 'O, ich sterbe...', '', 28153),
(153189, 'deDE', 'Geht und sorgt dafür, dass Etrigg und der Kapitän bereit sind. Es gibt Geld zu verdienen!', '', 28153),
(153188, 'deDE', 'Ihr habt mich zu Fall gebracht...', '', 28153),
(153187, 'deDE', 'Von dieser Stund\' an... rede ich kein Wort.', '', 28153),
(153186, 'deDE', 'Halt!', '', 28153),
(153185, 'deDE', 'Schuft, Ihr erschlugt mich!', '', 28153),
(153184, 'deDE', 'Oh, ich bin umgebracht!', '', 28153),
(153183, 'deDE', 'Jetzt nun entflieht mein Geist, ich kann nicht... mehr.', '', 28153),
(153182, 'deDE', '', 'Nein. Ihr werdet meinem Volk kein Leid mehr zufüg\'n. Euer Wahnsinn endet hier!', 28153),
(153180, 'deDE', '', 'Richtig, Prinzessin.', 28153),
(153177, 'deDE', 'Es wurden drei Geräte geschaffen, um die Verderbnis zu versiegeln.', '', 28153),
(153174, 'deDE', '[Großartige Videosequenz.]', '[Großartige Videosequenz.]', 28153),
(153173, 'deDE', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Vectis wirkt |cFFFF0000|Hspell:266948|h[Seuchenbombe]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Vectis wirkt |cFFFF0000|Hspell:266948|h[Seuchenbombe]|h|r!', 28153),
(153172, 'deDE', '', 'Ein Alter Gott?! Deshalb hab\'n die Bluttrolle meine Stadt angegriff\'n...', 28153),
(153171, 'deDE', 'Daten wiederhergestellt. Verderbnis stammt von Altem Gott in Nazmir.', '', 28153),
(153169, 'deDE', '...und eineinzehntel Gallonen Tequila!', '...und eineinzehntel Gallonen Tequila!', 28153),
(153168, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Drustvar!', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Drustvar!', 28153),
(153167, 'deDE', '', 'Die Klagelied ist eins der besten Schiffe der Dunklen Fürstin. Sie mag keine Augenweide sein, aber sie ist ein zäher Haudegen.\n\nIhr Kapitän ist auch nicht übel.', 28153),
(153166, 'deDE', 'Ja, ich bin bereit, nach Drustvar zu reisen.', 'Ja, ich bin bereit, nach Drustvar zu reisen.', 28153),
(153165, 'deDE', 'Lasst Euch nicht von dem Goblin in die Irre führen, $n. Unsere Mission lautet, INFORMATIONEN über die Allianz zu sammeln und nicht, so viel Azerit wie möglich einzusammeln.\n\nSeid Ihr zum Aufbruch bereit?', '', 28153),
(153164, 'deDE', 'Versucht, Euch nicht von dem Handelsprinzen ablenken zu lassen. Unser Hauptaugenmerk liegt auf Erkundung... nicht auf Profit.', '', 28153),
(153163, 'deDE', 'Sie sag\'n, da drauß\'n soll jede Menge Azerit sein, das man sich nur nehm\'n muss. Un\' das is\' dann also Eure Aufgabe.\n\nWenn Ihr krepiert, krieg ich zumindest Euren Hut! Hahaha!', '', 28153),
(153162, 'deDE', 'Setzt die Wiederherstellung des Avatars von Sethraliss fort, während Ihr weitere Eindringlinge beseitigt.', 'Setzt die Wiederherstellung des Avatars von Sethraliss fort, während Ihr weitere Eindringlinge beseitigt.', 28153),
(153161, 'deDE', 'Gut gemacht, $n. Wir müssen aufpassen und die Dschungelnetzspinnen vom Tempelgelände fernhalten.', '', 28153),
(153160, 'deDE', 'Die Dschungelnetzspinnen werden in den Tempelruinen zur Plage. Tut etwas dagegen und rettet meine gefangenen Anhänger aus den Netzen!', '', 28153),
(153159, 'deDE', 'Heilt den Avatar vollständig.', 'Heilt den Avatar vollständig.', 28153),
(153158, 'deDE', 'Hinterhältige Spinnen!', '', 28153),
(153157, 'deDE', 'Danke, $n! Ich verdanke Euch mein Leben.', '', 28153),
(153156, 'deDE', 'Ich kann wieder atmen! Danke!', '', 28153),
(153155, 'deDE', 'Diese Spinnen sind beim Fressen nicht wählerisch!', '', 28153),
(153154, 'deDE', 'Danke! Das war knapp...', '', 28153),
(153153, 'deDE', 'Ich dachte schon, es wäre um mich geschehen!', '', 28153),
(153152, 'deDE', 'Was wollt Ihr von uns?', 'Was wollt Ihr von uns?', 28153),
(153151, 'deDE', 'Nein, bitte...', 'Nein, bitte...', 28153),
(153150, 'deDE', '', 'Dann aufgesattelt! $n, wir reiten voraus und suchen Meister Eschtal. Wir treffen uns im Blutroten Wald!', 28153),
(153149, 'deDE', 'Meine Knochen! Diese Schmerzen!', 'Diese Schmerzen! Meine Knochen!', 28153),
(153148, 'deDE', 'Ach, wie mir das gefehlt hat.', 'Ach, wie mir das gefehlt hat.', 28153),
(153147, 'deDE', 'Ihr langweilt mich. Machen wir Euch doch... interessanter.', 'Ihr langweilt mich. Machen wir Euch doch... interessanter.', 28153),
(153146, 'deDE', 'Sagt, tut es weh?', 'Sagt, tut es weh?', 28153),
(153145, 'deDE', 'Ich schätze schon.', '', 28153),
(153144, 'deDE', '', 'Geht es Euch gut? Könnt Ihr uns begleiten?', 28153),
(153143, 'deDE', 'Die Stadt ist in guten Händen. Würde mir also jemand erklären, was hier vorgeht?', '', 28153),
(153142, 'deDE', 'Aber gewiss! Ich weiß zwar nicht genau, warum Ihr meine Hilfe braucht, aber da Ihr mein Zuhause gerettet habt, sollt Ihr sie haben!\n\nIhr werdet Euch allerdings etwas gedulden müssen. Die Stadt liegt sicher in Trümmern.', '', 28153),
(153141, 'deDE', 'Wir müssen hier weg!', 'Wir müssen hier weg!', 28153),
(153140, 'deDE', 'Nicht die schon wieder!', 'Nicht die schon wieder!', 28153),
(153139, 'deDE', 'Ohne Euch wäre ich nicht mehr am Leben...', 'Ohne Euch wäre ich nicht mehr am Leben...', 28153),
(153138, 'deDE', 'Die Horde! Was macht die denn hier?', 'Die Horde! Was macht die denn hier?', 28153),
(153137, 'deDE', 'Anker gelichtet, Kommandant!', 'Anker gelichtet, Kommandant!', 28153),
(153136, 'deDE', 'Ich kriege Euch schneller da raus, als eine Möwe fliegen kann. Sagt mir einfach Bescheid, wenn Ihr bereit seid.', '', 28153),
(153135, 'deDE', 'Ihr sucht nach Eschtal? Folgt mir. Ich selbst habe ihn zwar nicht gesehen, dafür aber seinen Lehrling.', '', 28153),
(153134, 'deDE', 'Holla, das ist wirklich nichts für schwache Nerven... oder schwache Mägen.', '', 28153),
(153133, 'deDE', 'Ich habe von einem Leckerbissen aus der Wüste hinter dem Meer erfahren. Bringt mir ein paar Bussardflügel und Skorpidstacheln. Ich möchte eine neue Version kreieren... mit etwas mehr Kick.', '', 28153),
(153132, 'deDE', 'Kurs halten, Steuermann!', 'Kurs halten, Steuermann!', 28153),
(153131, 'deDE', 'DAS ANDERE RAUS, Flachpfeife!', 'DAS ANDERE RAUS, Flachpfeife!', 28153),
(153130, 'deDE', 'DIE UNREINEN DÜRFEN DIE HALLEN DER TOTEN NICHT BETRETEN.', '', 28153),
(153129, 'deDE', 'IHR DÜRFT NICHT WEITER.', '', 28153),
(153128, 'deDE', 'NIEMAND HAT HIER ZUTRITT.', '', 28153),
(153127, 'deDE', 'Bis dann.', '', 28153),
(153126, 'deDE', 'He.', '', 28153),
(153125, 'deDE', '', 'Ich habe als Lehrerin versagt.', 28153),
(153124, 'deDE', '', 'Zeit für die Pause.', 28153),
(153123, 'deDE', '', 'Wir sind für heute... fertig.', 28153),
(153122, 'deDE', '', 'Der Unterricht hat begonnen!', 28153),
(153121, 'deDE', '', 'Zeit, dass Ihr die drei Rs kennenlernt: Runen, Rituale und Relikte!', 28153),
(153120, 'deDE', '', 'Ihr werdet eine Lektion erhalten!', 28153),
(153119, 'deDE', 'Wer kümmert sich jetzt um die Vorräte?', '', 28153),
(153118, 'deDE', 'Diese Charge... ist verdorben.', '', 28153),
(153117, 'deDE', 'Ihr dürft den Bestand nicht berühren!', '', 28153),
(153116, 'deDE', 'Die Sammlung ist ausschließlich für Gäste!', '', 28153),
(153115, 'deDE', 'Ausgezeichnet. Das wird uns eine Weile reichen... wenn ich sie nicht sofort alle auf einmal futtere.', '', 28153),
(153114, 'deDE', 'Ihr wärt überrascht, wie sich die Dinge hier zum Überleben anpassen. Die Peitscher haben die robustesten, aber auch die leckersten, Samen. Holt welche, aber hütet Euch vor den Dornen!', '', 28153),
(153113, 'deDE', 'Ich mag Eure Denkweise, Walter.', '', 28153),
(153112, 'deDE', 'Oder... Wir wurden doch schon bezahlt. Wir könnten doch in Haderfurt erzählen, dass wir angegriffen wurden... und den Met selbst trinken.', '', 28153),
(153111, 'deDE', 'So... Ich glaube, jetzt ist es sicher. Bringen wir diese Fässer jetzt nach Haderfurt.', '', 28153),
(153110, 'deDE', 'Ich werde nach Hinweisen auf James suchen, während Ihr das Schiff ruft. Ich werde ihn nicht in den Klauen dieser glitschigen Mistkerle zurücklassen.', 'Ich werde nach Hinweisen auf James suchen, während Ihr das Schiff ruft. Ich werde ihn nicht in den Klauen dieser glitschigen Mistkerle zurücklassen.', 28153),
(153109, 'deDE', 'Das Ding tropft ja nur so vor Honig!', '', 28153),
(153108, 'deDE', 'Los schon, blöde Möwe!', '', 28153),
(153107, 'deDE', 'Also... Ich bin so bereit, wie man es nur sein kann. Soll die Natur mal zeigen, was sie kann!', '', 28153),
(153106, 'deDE', 'Gehen wir es an!', 'Gehen wir es an!', 28153),
(153105, 'deDE', 'Hier werden jede Sekunde weitere Bestien auftauchen, $C. Beschützt den Met, als würde Euer Leben davon abhängen!', '', 28153),
(153103, 'deDE', 'Kopf hoch, Bradford! Von denen lassen wir uns doch nicht unterkriegen!', '', 28153),
(153102, 'deDE', 'So, Walter, das ist wohl unser Ende. Ich weiß nicht, wie viele dieser Bestien wir noch abwehren können!', '', 28153),
(153101, 'deDE', '%s richtet eine vollständig aufgeladene Azeritkanone auf den Belagerungsturm.', '', 28153),
(153100, 'deDE', '$n! Wir brauchen Euch! Und zwar zügig!', '$n! Wir brauchen Euch! Und zwar zügig!', 28153),
(153099, 'deDE', 'Verdammt, Leonhard, ich habe Euch nicht erlaubt, wegzutreten!', 'Verdammt, Leonhard, ich habe Euch nicht erlaubt, wegzutreten!', 28153),
(153098, 'deDE', 'Der Rest folgt mir. Wir werden ihre Flanke umgehen.', 'Der Rest folgt mir. Wir werden ihre Flanke umgehen.', 28153),
(153097, 'deDE', 'Faszinierend. Höchst exquisit. Ich frage mich, welche Geschichte mir diese kleinen Reisenden zu erzählen haben.', '', 28153),
(153096, 'deDE', 'Normalerweise leben Flatterlinge nur ein paar Monate, aber bei diesen hier scheint das anders zu sein. Bringt mir ein paar Exemplare. Seid sorgsam, sie sind sehr empfindlich.', '', 28153),
(153093, 'deDE', '', 'Wer kümmert sich jetzt um das Gelände?', 28153),
(153092, 'deDE', '', 'Ich werde wieder eins mit der Erde.', 28153),
(153091, 'deDE', '', 'Ihr werdet einen hervorragenden Dünger abgeben.', 28153),
(153090, 'deDE', '', 'Ihr werdet ernten, was Ihr gesät habt!', 28153),
(153089, 'deDE', '', 'Eindringlinge in meinem Garten!', 28153),
(153088, 'deDE', '', 'In Stücke gerissen.', 28153),
(153087, 'deDE', '', 'Meine Pläne... zunichtegemacht.', 28153),
(153086, 'deDE', '', 'Ich verwebe die Stränge Eures Verhängnisses!', 28153),
(153085, 'deDE', '', 'Euer Ende bahnt sich an!', 28153),
(153084, 'deDE', '', 'Ich werde Eure Seelen in meinen Wandschmuck weben!', 28153),
(153083, 'deDE', 'Eine überragende Jagd als überragendes Ende.', '', 28153),
(153082, 'deDE', 'Diese Wildheit...', '', 28153),
(153081, 'deDE', 'Ich hätte nie gedacht... dass ich selbst mal die Trophäe werden würde.', '', 28153),
(153080, 'deDE', 'Zeit zum Zuschlagen!', '', 28153),
(153079, 'deDE', 'Ihr ergebt eine feine Trophäe für meine Wand!', '', 28153),
(153078, 'deDE', 'Die Jagd ist eröffnet!', '', 28153),
(153077, 'deDE', 'Frischfleisch für den Grill!', '', 28153),
(153076, 'deDE', 'Es ist angerichtet!', '', 28153),
(153075, 'deDE', 'Der Schrein muss erneut geöffnet werden. Unsere Erlösung ist endlich gekommen!', '', 28153),
(153074, 'deDE', 'Diese Dunkelheit wird uns nicht aufhalten.', '', 28153),
(153073, 'deDE', 'Gut gemacht. Wir werden die tapferen Schluchtkäfer niemals vergessen, die ihr Leben geopfert haben, um uns alle vor König Rakataka zu retten.', '', 28153),
(153072, 'deDE', 'Mein Volk hat schon für weniger getötet.', '', 28153),
(153071, 'deDE', 'Disziplin und Taktgefühl sind bei Euch offenbar Mangelware.', '', 28153),
(153070, 'deDE', 'Alles hat einen Wert. Selbst Ihr.', '', 28153),
(153069, 'deDE', 'Der Sand veschluckt die Verschwenderischen.', '', 28153),
(153068, 'deDE', 'Die Sande weisen uns den Weg.', '', 28153),
(153067, 'deDE', 'Wir gehen dahin, wo die Sande uns führen.', '', 28153),
(153066, 'deDE', 'Die Dünen geben uns alles, was wir brauchen.', '', 28153),
(153065, 'deDE', 'Um in den Sanden zu überleben, muss man den Wert des Vergessenen erkennen.', '', 28153),
(153064, 'deDE', 'Denkt daran, alles hat einen Nutzen.', '', 28153),
(153063, 'deDE', 'Sprecht.', '', 28153),
(153062, 'deDE', 'Hallo.', '', 28153),
(153061, 'deDE', 'Was habt Ihr dabei?', '', 28153),
(153060, 'deDE', 'Wollt Ihr handeln?', '', 28153),
(153059, 'deDE', 'Braucht Ihr etwas?', '', 28153),
(153058, 'deDE', '', 'Zandalar is\' immer da.', 28153),
(153057, 'deDE', '', 'Immer schön vorsichtig.', 28153),
(153056, 'deDE', '', 'Niemand verdient es, in \'n Sand geschickt zu werd\'n.', 28153),
(153055, 'deDE', '', 'Was kann ich ma\' für Euch tun?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'deDE', '', 'Fasst Euch ma\' kurz.', 28153),
(153053, 'deDE', '', 'Ich hör zu.', 28153),
(153052, 'deDE', '', 'Ja?', 28153),
(153051, 'deDE', 'Wir werden niemals aufgeben.', 'Wir werden niemals aufgeben.', 28153),
(153050, 'deDE', 'Das Imperium der Treulosen wird fallen.', 'Das Imperium der Treulosen wird fallen.', 28153),
(153049, 'deDE', 'Möge Sethraliss uns alle retten.', 'Möge Sethraliss uns alle retten.', 28153),
(153048, 'deDE', 'Korthek hat diesen Krieg über uns gebracht.', 'Korthek hat diesen Krieg über uns gebracht.', 28153),
(153047, 'deDE', 'Wir müssen stark bleiben.', 'Wir müssen stark bleiben.', 28153),
(153046, 'deDE', 'Seid Ihr hier, um zu helfen?', 'Seid Ihr hier, um zu helfen?', 28153),
(153045, 'deDE', 'König Rakataka terrorisiert die Knochensplitterschlucht. Er ist zu stark, um ihn frontal anzugreifen, doch er leidet an unstillbarem Hunger. Er wird sich zu Tode fressen, wenn Ihr ihn nur genug füttert.', '', 28153),
(153044, 'deDE', 'Mein Volk hat schon für weniger getötet.', 'Mein Volk hat schon für weniger getötet.', 28153),
(153043, 'deDE', 'Disziplin und Taktgefühl sind bei Euch offenbar Mangelware.', 'Disziplin und Taktgefühl sind bei Euch offenbar Mangelware.', 28153),
(153042, 'deDE', 'Alles hat einen Wert. Selbst Ihr.', 'Alles hat einen Wert. Selbst Ihr.', 28153),
(153041, 'deDE', 'Seid schnell und seid clever.', 'Seid schnell und seid clever.', 28153),
(153040, 'deDE', 'Wer überleben will, muss einfallsreich sein.', 'Wer überleben will, muss einfallsreich sein.', 28153),
(153039, 'deDE', 'Denkt daran, alles hat einen Nutzen.', 'Denkt daran, alles hat einen Nutzen.', 28153),
(153038, 'deDE', 'Die Dünen geben uns alles, was wir brauchen.', 'Die Dünen geben uns alles, was wir brauchen.', 28153),
(153037, 'deDE', 'Passt auf Euch auf. Sonst tut das nämlich niemand.', 'Passt auf Euch auf. Sonst tut das nämlich niemand.', 28153),
(153036, 'deDE', 'Findet da draußen bloß nicht den Tod.', 'Findet da draußen bloß nicht den Tod.', 28153),
(153035, 'deDE', 'Was habt Ihr mir denn mitgebracht?', 'Was habt Ihr mir denn mitgebracht?', 28153),
(153034, 'deDE', 'Benötigt Ihr irgendwas?', 'Benötigt Ihr irgendwas?', 28153),
(153033, 'deDE', 'Seid Ihr auf einen Handel aus?', 'Seid Ihr auf einen Handel aus?', 28153),
(153032, 'deDE', 'Hallo, Ihr da.', 'Hallo, Ihr da.', 28153),
(153031, 'deDE', 'Habt Ihr was für mich?', 'Habt Ihr was für mich?', 28153),
(153030, 'deDE', 'Bringt mir einen Preis von Eurem nächsten Abenteuer!', 'Bringt mir einen Preis von Eurem nächsten Abenteuer!', 28153),
(153029, 'deDE', 'Sind wir jetzt Freunde?', 'Sind wir jetzt Freunde?', 28153),
(153028, 'deDE', 'Danke, dass Ihr mit mir gesprochen habt.', 'Danke, dass Ihr mit mir gesprochen habt.', 28153),
(153027, 'deDE', 'Seid Ihr gerade auf einem großen Abenteuer? Das ist ja so was von toll!', 'Seid Ihr gerade auf einem großen Abenteuer? Das ist ja so was von toll!', 28153),
(153026, 'deDE', 'Habt Ihr schon mal absichtlich Sand gegessen?', 'Habt Ihr schon mal absichtlich Sand gegessen?', 28153),
(153025, 'deDE', 'Kann ich Eure Sachen haben, wenn Ihr sterbt?', 'Kann ich Eure Sachen haben, wenn Ihr sterbt?', 28153),
(153024, 'deDE', 'Wir werden niemals aufgeben.', '', 28153),
(153023, 'deDE', 'Das Imperium der Treulosen wird fallen.', '', 28153),
(153022, 'deDE', 'Möge Sethraliss uns alle retten.', '', 28153),
(153021, 'deDE', 'Korthek hat diesen Krieg über uns gebracht.', '', 28153),
(153020, 'deDE', 'Wir müssen stark bleiben.', '', 28153),
(153019, 'deDE', 'Seid Ihr hier, um zu helfen?', '', 28153),
(153018, 'deDE', 'Wir tun, was getan werden muss.', '', 28153),
(153017, 'deDE', 'Sethraliss wird uns retten.', '', 28153),
(153016, 'deDE', 'Die Treulosen werden unseren Tempel nicht einnehmen.', '', 28153),
(153015, 'deDE', 'Korthek hat diesen Krieg über uns gebracht.', '', 28153),
(153014, 'deDE', 'Wir müssen stark bleiben.', '', 28153),
(153013, 'deDE', 'Seid Ihr hier, um zu helfen?', '', 28153),
(153012, 'deDE', '', 'Wir hätten Euch wirklich nicht retten sollen. Halt! War nicht so gemeint...', 28153),
(153011, 'deDE', '', 'Oh, das habt Ihr doch nicht wirklich noch einmal gemacht...', 28153),
(153010, 'deDE', '', 'Ihr solltet besser damit aufhören.', 28153),
(153009, 'deDE', '', 'Was soll das?', 28153),
(153008, 'deDE', '', 'Ihr kommt doch zurück, oder?', 28153),
(153007, 'deDE', '', 'Hey, sterbt da draußen nicht!', 28153),
(153006, 'deDE', '', 'Es ist nicht sicher, allein zu reisen.', 28153),
(153005, 'deDE', '', 'Dolly mag Euch. Das kann ich sehen.', 28153),
(153004, 'deDE', '', 'Ich kenne diese Dünen besser als jeder andere.', 28153),
(153003, 'deDE', '', 'Hallo!', 28153),
(153002, 'deDE', '', 'Ich kann Euch helfen!', 28153),
(153001, 'deDE', '', 'Die Stadt wird nich\' fall\'n.', 28153),
(153000, 'deDE', '', 'Seid vorsichtig.', 28153),
(152999, 'deDE', '', 'Ich hab geschwor\'n, die Königsfamilie zu verteidig\'n.', 28153),
(152998, 'deDE', '', 'Wir werd\'n besteh\'n.', 28153),
(152997, 'deDE', '', 'Fasst Euch kurz.', 28153),
(152996, 'deDE', '', 'Ja?', 28153),
(152995, 'deDE', '', 'Ich hör zu.', 28153),
(152994, 'deDE', 'Möge der Sand meine Sünd\'n verschluck\'n.', '', 28153),
(152993, 'deDE', 'Der Sand wird niemals sicher sein.', '', 28153),
(152992, 'deDE', 'Manches kann man nich\' ungescheh\'n machen.', '', 28153),
(152991, 'deDE', 'Was darf\'s denn sein?', '', 28153),
(152990, 'deDE', 'Wenn ich helf\'n kann, werd ich\'s tun.', '', 28153),
(152989, 'deDE', 'Ich verdien mein Schicksal.', '', 28153),
(152988, 'deDE', 'Geht, solang Ihr noch könnt.', '', 28153),
(152987, 'deDE', 'Ich behalt\' Euch im Auge.', '', 28153),
(152986, 'deDE', 'Haltet die Aug\'n off\'n.', '', 28153),
(152985, 'deDE', 'Ihr gehört hier nich\' her.', '', 28153),
(152984, 'deDE', 'Ich hab keine Zeit für Euch.', '', 28153),
(152983, 'deDE', 'Was wollt Ihr hier?', '', 28153),
(152982, 'deDE', 'Lasst Euch vom Sturm leiten.', '', 28153),
(152981, 'deDE', 'Fürchtet den Sturm nicht.', '', 28153),
(152980, 'deDE', 'Klarheit folgt auf den Sturm.', '', 28153),
(152979, 'deDE', 'Der Sturm ruft.', '', 28153),
(152978, 'deDE', 'Alle sind hier willkommen.', '', 28153),
(152977, 'deDE', 'Ich bin der Sturm.', '', 28153),
(152976, 'deDE', 'Was führt Euch hierher?', '', 28153),
(152975, 'deDE', 'Das Festmahl ist bereit!', '', 28153),
(152973, 'deDE', '', 'Ich könnte einen neuen Helm gebrauchen...', 28153),
(152972, 'deDE', '', 'Da fällt mir wieder ein, dass mich auch ein Mal ein Sethrak angestupst hat... EIN Mal.', 28153),
(152971, 'deDE', '', '', 28153),
(152970, 'deDE', '', 'Möge der Wind immer in Eurem Rücken und das Schwert immer in Eurer Hand sein.', 28153),
(152969, 'deDE', '', 'Lehrt sie das Fürchten!', 28153),
(152968, 'deDE', '', 'Lasst mir ein paar Sethrak übrig!', 28153),
(152967, 'deDE', '', 'Hört niemals auf zu kämpfen.', 28153),
(152966, 'deDE', '', '', 28153),
(152965, 'deDE', '', 'Heute ist ein guter Tag zum Kämpfen. Wie jeder Tag eigentlich.', 28153),
(152964, 'deDE', '', 'Wir Vulpera sind stärker, als wir aussehen.', 28153),
(152963, 'deDE', '', 'Mein Volk wird frei sein.', 28153),
(152962, 'deDE', '', 'Ich bin bereit zu kämpfen.', 28153),
(152961, 'deDE', 'Mein Leb\'n für\'n König.', '', 28153),
(152960, 'deDE', 'Haltet Eure Waff\'n bereit.', '', 28153),
(152959, 'deDE', 'Mög\'n die Loa mit Euch sein.', '', 28153),
(152958, 'deDE', 'Zandalar is\' stark.', '', 28153),
(152957, 'deDE', 'Ich stell mich der Gefahr.', '', 28153),
(152956, 'deDE', 'Unsre Feinde werden fall\'n.', '', 28153),
(152955, 'deDE', '', 'Oh, davon bin ich überzeugt.', 28153),
(152954, 'deDE', 'Wir enttäuschen Euch nicht, meine Königin.', '', 28153),
(152953, 'deDE', '', 'Seid Ihr der Aufgabe gewachsen?', 28153),
(152952, 'deDE', '', 'Ihr müsst Sturmwind infiltrieren und einen politischen Gefangenen befreien,\nder den Verlauf des Krieges entscheiden könnte... zu unseren Gunsten.', 28153),
(152951, 'deDE', '', 'Der kleine König hat etwas, das ihm nicht gehört. Ich will es zurück.', 28153),
(152950, 'deDE', '', 'Die Horde gewinnt diesen Krieg nur mit Verbündeten.', 28153),
(152949, 'deDE', '', 'Tatsächlich ist Umsicht mein steter Begleiter.', 28153),
(152948, 'deDE', '', 'Gewisse Mitglieder der Horde scheinen meine jüngsten Taten für... unbedacht zu halten.', 28153),
(152947, 'deDE', '', 'Ich brauche jemanden, dem ich uneingeschränkt vertrauen kann.', 28153),
(152946, 'deDE', '', 'Ah, da seid Ihr. Ich bin schon ungeduldig geworden.', 28153),
(152945, 'deDE', '...der Horde gegenüber.', '', 28153),
(152944, 'deDE', 'Ihre Berater sind loyal...', '', 28153),
(152943, 'deDE', 'Wäre sie von deren Loyalität überzeugt, wäre meine Königin womöglich aufgeschlossener.', '', 28153),
(152942, 'deDE', 'Wie können wir dem Kriegshäuptling helfen, wenn sie ihre Berater ausschließt?', '', 28153),
(152941, 'deDE', 'Das geht Euch nichts an.', '', 28153),
(152940, 'deDE', 'Hat der Kriegshäuptling Euch gerufen?', '', 28153),
(152939, 'deDE', 'Welcher Art ist nicht einmal mir bekannt.', '', 28153),
(152938, 'deDE', 'Unser Kriegshäuptling verlangt nach Euch. Eine Mission größter Wichtigkeit... und Geheimhaltung.', '', 28153),
(152937, 'deDE', 'Empfehlt den Goldhauer Euern Freund\'n!', '', 28153),
(152936, 'deDE', 'Vergesst nich\', Euch ins Gästebuch einzutrag\'n!', '', 28153),
(152935, 'deDE', 'Sterbt mir bloß nich\' weg!', '', 28153),
(152934, 'deDE', 'Habt Ihr vielleicht \'n paar Banan\'?', '', 28153),
(152933, 'deDE', 'Goldhauer bleib\'n sich immer treu.', '', 28153),
(152932, 'deDE', 'Willkomm\' im Goldhauer!', '', 28153),
(152931, 'deDE', 'Meutern oder baumeln.', '', 28153),
(152930, 'deDE', 'Passt auf Eure Mannschaft auf.', '', 28153),
(152929, 'deDE', 'Fürchtet die dunklen Tiefen.', '', 28153),
(152928, 'deDE', 'Sie betrauert ihren Ehemann, seit er in Theramore fiel. Aber an diesem Tag hat sie auch ihre Tochter verloren.', '', 28153),
(152927, 'deDE', 'Schluss mit dem Geplapper! Niemand muss davon erfahren.', 'Schluss mit dem Geplapper! Niemand muss davon erfahren.', 28153),
(152926, 'deDE', 'Ruhe! Wir haben hier eine gute Sache am Laufen.', 'Ruhe! Wir haben hier eine gute Sache am Laufen.', 28153),
(152925, 'deDE', 'Still! Wir brauchen hier niemanden, der Fragen stellt.', 'Still! Wir brauchen hier niemanden, der Fragen stellt.', 28153),
(152924, 'deDE', 'Zem\'lan is\' kein Ort für die Lebenden.', '', 28153),
(152923, 'deDE', 'Sucht Ihr \'ne Crew?', '', 28153),
(152921, 'deDE', 'Ahoi!', '', 28153),
(152920, 'deDE', 'Katherine trägt eine immense Bürde. Kein Wunder, dass Jainas Rückkehr so schwer für sie war.', '', 28153),
(152918, 'deDE', '', 'Wir müssen die Häuser unter dem Banner der Prachtmeers vereinen und die Flotte finden, sonst könnte Kul Tiras zerfallen, bevor der Krieg überhaupt beginnt.', 28153),
(152917, 'deDE', 'Mein Klan wurde vom Schattenhammer ausgelöscht. Ich habe nur überlebt, weil mein Bruder, Keeland, mich auf seinem Greifen fortgeschickt hatte. Das hat mir das Leben gerettet.\n\nIch habe fast die ganze Welt bereist, bevor ich mich hier in Kul Tiras niedergelassen habe. Ich hab diese Leute kennengelernt, die für das Fleisch und den Pelz Jagd auf die Greifen gemacht haben. Ich habe ihnen eine andere Möglichkeit aufgezeigt. Jetzt sind sie die nächste Generation von Greifenreitern.\n\nIch glaube nicht, dass ich nach Hause zurückkehren werde. Das hier ist jetzt mein Klan.', '', 28153),
(152916, 'deDE', 'Bringt mich zurück nach Zul\'jan.', 'Bringt mich zurück nach Zul\'jan.', 28153),
(152915, 'deDE', 'Sägen', 'Sägen', 28153),
(152914, 'deDE', 'Was macht ein Zwerg vom Wildhammerklan hier draußen?', 'Was macht ein Zwerg vom Wildhammerklan hier draußen?', 28153),
(152913, 'deDE', 'Nach dieser Nummer werden wir reich sein.', 'Nach dieser Nummer werden wir reich sein.', 28153),
(152912, 'deDE', 'Die Dummköpfe hatten das Zeug praktisch unter den Füßen und wussten überhaupt nicht, wie viel es wert ist.', 'Die Dummköpfe hatten das Zeug praktisch unter den Füßen und wussten überhaupt nicht, wie viel es wert ist.', 28153),
(152911, 'deDE', 'Ich hab einen Käufer in Silbermond, der mir eine Stange Geld für diese Relikte zahlen wird.', 'Ich hab einen Käufer in Silbermond, der mir eine Stange Geld für diese Relikte zahlen wird.', 28153),
(152910, 'deDE', 'Nichts von dem Kram ist auf dem Weg in ein Museum.', '', 28153),
(152907, 'deDE', 'Von all\'m, was in Nazmir nich\' stimmt, stimmt der Ort hier am aller wenigst\'n. Seid schön vorsichtig!', '', 28153),
(152906, 'deDE', 'Hezrel is\' beschäftigt. Was macht\'n der bloß da unten?', '', 28153),
(152905, 'deDE', 'Wir hatt\'n gehofft, dass Hezrel uns im Kampf hilft, aber der is\' losgerannt un\' macht sein eignes Ding. Was hat\'n das Konstrukt vor?', '', 28153),
(152900, 'deDE', 'Finger weg von mei\'m Schatz...', 'Lasst mich... ich kehre bald wieder...', 28153),
(152899, 'deDE', 'Das Land hier is\' verflucht... wie wir alle...', 'Zem\'lan wird uns wiedererweck\'n... das is\' der wahre Fluch...', 28153),
(152898, 'deDE', 'Ich spür nichts...', 'Eure Landratt\'nbeine soll\'n Euch wegfaul\'n...', 28153),
(152897, 'deDE', 'Der Käpt\'n... wird davon erfah\'n...', 'Dafür werdet Ihr Euch... vor Zem\'lan verantwort\'n müss\'n.', 28153),
(152896, 'deDE', 'Lasst uns runterfliegen und uns mit Titanenhüter Hezrel treffen.', 'Lasst uns runterfliegen und uns mit Titanenhüter Hezrel treffen.', 28153),
(152895, 'deDE', '', 'Ich muss mei\'m Vater erzähl\'n, was hier passiert is\'. Wir hab\'n \'nen großen Sieg errung\', aber der Kampf gegen die Bluttrolle is\' nich\' vorbei.', 28153),
(152894, 'deDE', '', 'Ich vergess nich\', was die Horde alles für mein Volk getan hat. Ohne Euch wär das alles nich\' möglich gewes\'n.', 28153),
(152893, 'deDE', '', 'Zu Befehl!', 28153),
(152892, 'deDE', '', 'Die Höhle stürzt ein. Lauft!', 28153),
(152891, 'deDE', 'Ihr findet Euren Tod – ob durch das Geröll oder meine Vasallen. Meinen Sieg werdet Ihr nicht erleben.', '', 28153),
(152890, 'deDE', '', 'Ich werde Euch mitnehmen!', 28153),
(152889, 'deDE', '', 'Nur noch ein Stückchen näher!', 28153),
(152888, 'deDE', '', 'Lassen wir\'s krachen!', 28153),
(152887, 'deDE', '', 'Kommt schon, lasst Euch mal drücken!', 28153),
(152886, 'deDE', 'Folgt mir! Beeilt Euch, und lasst Euch nicht vom Weg abbringen!', 'Folgt mir! Beeilt Euch, und lasst Euch nicht vom Weg abbringen!', 28153),
(152885, 'deDE', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|tEin |cFFFF0000|Hspell:269131|h[Uralter Geistbeuger]|h|r heftet sich an |cFFFF0000$n|r an!', '', 28153),
(152884, 'deDE', 'Helden der Dritten Flotte, stählt Euch! Meldet Euch umgehend bei König Graumähne!', 'Helden der Dritten Flotte, stählt Euch! Meldet Euch umgehend bei König Graumähne!', 28153),
(152883, 'deDE', 'Falscher Alarm. Ist nur Gesöff. Alles im Lot.', '', 28153),
(152882, 'deDE', '', '.', 28153),
(152881, 'deDE', '', 'Unsre Truppen halt\'n die restlich\'n Bluttrolle in Schach, aber das schaff\'n die nich\' ewig. Wir müssen das beend\'n. Und zwar schnell.', 28153),
(152880, 'deDE', '', '.', 28153),
(152879, 'deDE', '', 'Allerdings hat seit Monaten niemand von der Flotte gehört! \nDie Gezeitenweisen bleiben in ihren Klöstern und scheinen sich nicht für unsere vermissten Schiffe zu interessieren.', 28153),
(152878, 'deDE', '', 'Das Haus Kronsteig war Jahrhunderte lang ein loyaler Unterstützer der Prachtmeerdynastie, \naber ihre Abwesenheit bei den jüngsten Ratstreffen hat beunruhigende Gerüchte losgetreten.', 28153),
(152877, 'deDE', 'Komm zurück, Schatz!', '', 28153),
(152876, 'deDE', 'Das konnte ich ja nicht kalt werden lassen.', 'Das konnte ich ja nicht kalt werden lassen.', 28153),
(152875, 'deDE', 'Lasst mich dieses Mal sterb\'n, Bwonsamdi... Bitte...', '', 28153),
(152874, 'deDE', 'Nun spuckt es schon aus.', '', 28153),
(152873, 'deDE', '', 'Wir werden unsere... Was schaut Ihr mich so an? SEID IHR ETWA NICHT EINVERSTANDEN?', 28153),
(152872, 'deDE', 'Sofort, ja. Natürlich. Wird unverzüglich erledigt!', '', 28153),
(152871, 'deDE', 'Pah, hab schon Schlimmeres gesehen. Aber das ist trotzdem eine traurige Geschichte. Wir müssen das Oberkommando informieren.', '', 28153),
(152870, 'deDE', 'Oje. Dann ist es noch schlimmer, als ich befürchtet habe. Ich bitte aufrichtig um Entschuldigung, dass ich Euch so einer Gefahr ausgesetzt habe, Herr Bronzebart.', '', 28153),
(152869, 'deDE', 'GUT?! Das Mädel war verrückter als ein Murloc nach zwei Eimern Mondmet. Sie hat versucht, $n hier einem Blutgott namens G\'huun zu opfern.', '', 28153),
(152868, 'deDE', 'Hauptmann Conrad... geht es hoffentlich gut?', '', 28153),
(152867, 'deDE', 'Zul\'Nazman, glaube ich. Oder Tul\'vor? Ich glaube, das ist das Gleiche. Oder zumindest fast.', '', 28153),
(152866, 'deDE', 'Ob mit oder ohne sein Wissen... Wir müssen der Sache auf den Grund gehen. Wo ist der Hauptmann hin?', '', 28153),
(152865, 'deDE', 'Oh... Oh, meine Güte. Ich bin mir sicher, dass der verehrte Hauptmann Conrad nichts von diesen makabren Umständen wusste.', '', 28153),
(152864, 'deDE', 'Harry wird urplötzlich ganz bleich um die Nase.', '', 28153),
(152863, 'deDE', 'Was ist hier los, Harry?! Diese Opfergaben, die Ihr geschickt habt... Es waren die Soldaten, die geopfert wurden! Sie wurden um ihr Blut angezapft wie ein Fass beim Braufest.', '', 28153),
(152862, 'deDE', 'Schluss damit! Sie kriegen keinen Heller mehr von uns, bevor ich und $n nicht herausgefunden haben, was hier los ist.', '', 28153),
(152861, 'deDE', 'Handelsabkommen mit Trollen! Wir haben sogar Fledermäuse vorbereitet, um sie mit weiteren Handelsangeboten nach Zala\'mar zu schicken.', '', 28153),
(152860, 'deDE', 'Oh, du lieber Himmel. Aber, ja, das ist natürlich korrekt. Hm... Aber Hauptmann Conrad ist eine große Frau. Zweifelsohne ganz beeindruckend.', '', 28153),
(152859, 'deDE', 'Ich hab gehört, sie wären Wilde, die Blutopfer darbringen.', '', 28153),
(152858, 'deDE', 'Nichts, was Euch beunruhigen müsste. Unser ruhmreicher Hauptmann handelt nur gerade ein Handelsabkommen mit den hiesigen Trollen aus.', '', 28153),
(152857, 'deDE', 'Aha. Nichts zu sehen vom Hauptmann. Was ist hier los?', '', 28153),
(152856, 'deDE', 'Ah! Ah ha! Gleich zur Sache, ja, ja. Keine Sorge! Es ist alles in Ordnung. Lasst uns zunächst die Sicherheit hinter unseren Festungsmauern aufsuchen, ja?', '', 28153),
(152855, 'deDE', 'Wo ist der Hauptmann?', '', 28153),
(152854, 'deDE', 'Hauptmann Conrad hat ein paar Anweisungen hinterlegt.', '', 28153),
(152853, 'deDE', 'Wir haben Euch erwartet, verehrte Berater und zukünftige Freunde.', '', 28153),
(152852, 'deDE', 'Willkommen! Willkommen!', '', 28153),
(152851, 'deDE', 'Unser Empfangskomitee scheint hier zu sein. Harry ist ein sonderbarer Bursche. Beachtet ihn gar nicht.', '', 28153),
(152850, 'deDE', 'Und... uääh... die Nase haltet Ihr Euch besser zu. Was ist denn das für ein grässlicher Verwesungsgestank?', '', 28153),
(152849, 'deDE', 'Egal. Passt auf. Haltet die Augen und Ohren offen. Gefährliche Länder kennen nämlich kein Mitleid mit den Sorglosen, $n.', '', 28153),
(152848, 'deDE', 'Aber immerhin kämpft dieses Land hier gegen die Zandalari und ihre Verbündeten von der Horde. Der Feind meines Feindes ist ja... Mann, wie hieß das nochmal?', '', 28153),
(152847, 'deDE', 'Wir haben Hauptmann Conrad vorausgeschickt, um eine Festung zu errichten. Die Bluttrolle hier sollen vielleicht sogar bereit sein, mit uns zu handeln. Aber ich kann mir kaum vorstellen, dass uns das nicht mehr kostet, als wir zu zahlen bereit sind.', '', 28153),
(152846, 'deDE', 'Das gefällt mir! Überall, wo sich einem die Nackenhaare aufstellen, gibt es eine Gelegenheit für Abenteuer und die Aussicht auf mehr Wissen.', '', 28153),
(152845, 'deDE', 'Hier läuft es mir eiskalt den Rücken runter...', '', 28153),
(152844, 'deDE', 'Ihr werdet es jedoch nicht miterleben. Erhebt Euch, Wächter, und tötet die Eindringlinge!', '', 28153),
(152843, 'deDE', 'Die Pest der Kul Tiraner wird geläutert werden. Wir holen uns unser Land zurück.', '', 28153),
(152842, 'deDE', 'Eure Ahnen waren Narren... genau wie Ihr.', '', 28153),
(152841, 'deDE', 'Nehmt eines der Seile runter zum Landefahrzeug, $n. Und viel Glück.', '', 28153),
(152840, 'deDE', '', 'Das sind definitiv weitere Gravuren. Kommt!', 28153),
(152839, 'deDE', '', 'Gorak Tul hat nicht überlebt. Es gab Zeugen seiner Niederlage.', 28153),
(152838, 'deDE', 'Uns wurde die Erlaubnis gewährt, hier Portale zu öffnen.', 'Uns wurde die Erlaubnis gewährt, hier Portale zu öffnen.', 28153),
(152837, 'deDE', 'Dieser Ort trieft förmlich vor Magie. Spürt Ihr es?\n\nIch frage mich, was für Rituale sie hier abgehalten haben.', 'Dieser Ort trieft förmlich vor Magie. Spürt Ihr es?\n\nIch frage mich, was für Rituale sie hier abgehalten haben.', 28153),
(152836, 'deDE', '', 'Noch eine Stele. Diese hier zeigt auch Gorak Tul.', 28153),
(152835, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Vol\'dun!', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Vol\'dun!', 28153),
(152834, 'deDE', '|cFFEF0201+$1i|r |cFFFFFF00Azerit|r', '|cFFEF0201+$1i|r |cFFFFFF00Azerit|r', 28153),
(152833, 'deDE', 'Sie sagten, ich würde mit Blut <hust> arbeiten. Also fragte ich: \"Blutelfen?!\" Und sie antworteten \"Blut... <hust>.\"\n\nBlutTROLLE. Nicht ELFEN. Argh. Die haben überhaupt keine Kultur.', '', 28153),
(152832, 'deDE', '', 'Aye, Sir!', 28153),
(152831, 'deDE', '', 'Wartet... Was geht hier vor?', 28153),
(152830, 'deDE', 'In Einigkeit liegt Stärke.', '', 28153),
(152829, 'deDE', '...Ich habe hier eine Notiz zu den roten Blüten gemacht. Ich habe sie sogar eingekreist. In Rot. Danke für Eure Hilfe. Ohne Euch hätte das womöglich kein gutes Ende genommen.', '', 28153),
(152828, 'deDE', 'Ah, Ihr da. Ich würde gern ein paar Proben dieser seltenen Wüstenblume nehmen. Bitte helft mir dabei.', '', 28153),
(152827, 'deDE', 'Was für eine Irre! Ich treffe Euch in der Siegesfeste. Lasst uns aus diesem dunklen Loch verschwinden, bevor die alle hinter uns her sind.', '', 28153),
(152826, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(152825, 'deDE', 'Ein seltener Anblick in diesem Teil der Welt. Die Blätter des roten Peitschers sollen über mystische Heilkräfte verfügen.$b$bIch würde gern ein paar davon einsammeln, aber dadurch wird der Geruch der Pflanze freigesetzt. Und damit werden bestimmt ein paar Tiere angelockt.$b$bWenn Ihr mich beim Sammeln beschützt, werde ich Euch angemessen entlohnen.', '', 28153),
(152824, 'deDE', 'Alleria, nehmt den Rest unserer Truppen und schlagt den Feind in die Flucht.', '', 28153),
(152823, 'deDE', 'MEIN LEBEN FÜR DIE HORDE!', '', 28153),
(152822, 'deDE', 'Mein Vater hat für die Allianz alles hingegeben. Aber seid Ihr bereit, dasselbe für die Horde zu tun?', '', 28153),
(152821, 'deDE', 'Ich werde mich NIE ergeben. Jeden Moment meines Lebens kämpfe ich für mein Volk. Was habt Ihr für Eures aufgegeben?', '', 28153),
(152820, 'deDE', 'Euer Vater war ein ehrenhafter Mann, Junge. Ihr hingegen wisst nichts von Ehre.', '', 28153),
(152819, 'deDE', 'Tretet beiseite, Saurfang. Dieser Krieg ist nicht allein der Eure. Es wäre nicht ehrenhaft, Euch zu töten.', '', 28153),
(152818, 'deDE', '', 'Ich bin bereit!', 28153),
(152817, 'deDE', 'Ausgezeichnete Arbeit! Lasst uns weiter vorrücken.', '', 28153),
(152816, 'deDE', 'Vier Augen... das Ende... sie erhebt sich!', '', 28153),
(152815, 'deDE', 'Ein endloser Schatten... tausend Arme...', '', 28153),
(152814, 'deDE', 'Euch verdank ich alles, $p. Das werd ich nie vergess\'n.\n\nJetzt helf\'n wir erst mal Norah un\' den andern Vulpera, die gestohlene Beute von Zem\'lan zu plündern. Aber zögert nich\' zu frag\'n, wenn Ihr Hilfe von \'n paar untoten Piraten braucht.\n\nWir hab\'n \'ne gute Meuterei angeführt, aber ich weiß, dass Zem\'lan nich\' alle von uns zwing\'n musste, Monster zu werd\'n. Viele von der Besatzung hab\'n das freiwillig gemacht.\n\nPasst auf Euch auf, wenn Ihr in den Haf\'n zurückkehrt.', '', 28153),
(152813, 'deDE', 'Wir müssen dafür sorgen, dass Wiebkes Opfer nicht umsonst war. Ihr Stab wird uns den Weg zum Schrein ebnen.', '', 28153),
(152812, 'deDE', 'Meuterei, bis wir an der Rah häng\'n, $p. Ich kämpf an Eurer Seite.', '', 28153),
(152811, 'deDE', 'Habt Ihr schon mal so viele Schätze an einem Ort geseh\'n?\n\nDafür muss \'n guter Pirat \'n Leben lang und darüber hinaus arbeit\'n. So wunderschön...', '', 28153),
(152810, 'deDE', '', '<Ahna schnarcht laut, während sie vorgibt, zu schlafen.>', 28153),
(152809, 'deDE', 'Schlagt den Gong, um Pirat\'nkönig Zem\'lan rauszufordern. Ich bin bereit, mich ihm zu stell\'n.', '', 28153),
(152808, 'deDE', 'Ich verstehe. Dann werden wir Katherine Prachtmeer die selbe Wahrheit eröffnen, die ich selbst schmerzlich erfahren musste...', '', 28153),
(152807, 'deDE', 'Gut gemacht. Goldmünzen des alten Trollimperiums sind ein Vermögen wert. Hier ist Euer Anteil.', '', 28153),
(152806, 'deDE', 'Ich habe ein uraltes Totem im Hof von Zak\'rajan gefunden, das Tote erwecken kann. Geht damit zu den Knochengruben und buddelt ein paar Schätze aus.', '', 28153),
(152805, 'deDE', 'Ach, vergesst es. Ich habe keine Zeit für diesen Blödsinn. Auf mich wartet eine Gruppe.', '', 28153),
(152804, 'deDE', 'Die Jugend von heute. Keine Geduld. Ich mache mich doch gerade erst warm.', '', 28153),
(152803, 'deDE', 'Wenn Ihr mich weiter so anstupst, muss ich gleich eine Geschichte erzählen. Eine sehr laaaange und langweilige Geschichte.', '', 28153),
(152802, 'deDE', 'Wir können uns ja beim nächsten Mal mehr unterhalten.', '', 28153),
(152801, 'deDE', 'Geht nur. Ich habe sowieso zu tun.', '', 28153),
(152800, 'deDE', 'Wo wollt Ihr denn so schnell hin?', '', 28153),
(152799, 'deDE', 'Psst, nicht so laut!', '', 28153),
(152798, 'deDE', 'Kennt Ihr eine gute Geschichte?', '', 28153),
(152797, 'deDE', 'Ja, ja... ich höre ja schon zu.', '', 28153),
(152796, 'deDE', 'Die Dschungelpflanzen könn\' schlimmer sein als die Tiere, wenn man nich\' aufpasst.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'deDE', 'Ich setze nie wieder einen Fuß in diese Mine!', 'Ich setze nie wieder einen Fuß in diese Mine!', 28153),
(152794, 'deDE', 'Sie sind aus dem Nichts aufgetaucht!', 'Sie sind aus dem Nichts aufgetaucht!', 28153),
(152793, 'deDE', 'Danke! Ich dachte schon, ich wäre hinüber.', 'Danke! Ich dachte schon, ich wäre hinüber.', 28153),
(152792, 'deDE', 'Holt mich hier raus!', 'Holt mich hier raus!', 28153),
(152791, 'deDE', '', 'Hiermit gelangt Ihr hinunter zur Brücke.', 28153),
(152790, 'deDE', 'Ich glaube, Euer Gesicht und mein Stiefel hatten noch nicht das Vergnügen. Darf ich Euch vorstellen?', '', 28153),
(152789, 'deDE', 'Macht die Flatter, schräger Vogel...', '', 28153),
(152788, 'deDE', 'Wir sehen uns in der Luft.', '', 28153),
(152787, 'deDE', '', 'Im Sturmsangtal, nördlich von hier, bauen und segnen die Gezeitenweisen von Haus Sturmsang die Schiffe unserer legendären Flotte.', 28153),
(152786, 'deDE', 'Alles klar. Weitermachen.', '', 28153),
(152785, 'deDE', 'Zurück an die Arbeit!', '', 28153),
(152784, 'deDE', 'Spuckt\'s aus.', '', 28153),
(152783, 'deDE', 'Was braucht Ihr?', '', 28153),
(152782, 'deDE', 'Was? Ich hab viel um die Ohren!', '', 28153),
(152781, 'deDE', 'Diese Biester waren der Schrecken vieler Karawanen in Vol\'dun. Gute Arbeit.', '', 28153),
(152780, 'deDE', 'Knochenschnabelgeier sind unzähmbar. Sie sind zu einem solchen Ärgernis geworden, dass Ihre Zahl und Nester reduziert werden müssen.', '', 28153),
(152779, 'deDE', 'Seht Euch ruhig um, aber bitte berührt nichts.$b$bDiese Pflanzen sind sehr empfindlich.', '', 28153),
(152778, 'deDE', '', 'Im Westen liegt Drustvar, eine Bergregion, aus der der Hauptteil des Erzbedarfs im Königreich kommt... und so manche unserer zähesten Krieger.', 28153),
(152777, 'deDE', '', 'Außer dem Tiragardesund gibt es noch die Ländereien der Familien Kronsteig und Sturmsang.', 28153),
(152776, 'deDE', 'Für Euch wird\'s nur Schmerzen geb\'n!', 'Für Euch wird\'s nur Schmerzen geb\'n!', 28153),
(152775, 'deDE', 'Ich weiß, wie ich Euch zum Reden bringe!', 'Ich weiß, wie ich Euch zum Reden bringe!', 28153),
(152774, 'deDE', 'Ich werde Euren Willen brechen.', 'Ich werde Euren Willen brechen.', 28153),
(152773, 'deDE', 'Leben verbrennt zu Asche...', '', 28153),
(152772, 'deDE', 'Als er endlich um Hilfe bat, war es schon zu spät.', '', 28153),
(152771, 'deDE', 'Das Land, das ich liebe, zerbricht... deshalb bitte ich um Eure Hilfe. Kul Tiras braucht die Allianz genauso sehr, wie die Allianz uns.', '', 28153),
(152770, 'deDE', 'Aber sie ist fehlgeleitet. Ihre Berater verbergen die Infektion vor ihr, die sich in unserem Königreich verbreitet hat.', '', 28153),
(152769, 'deDE', 'Kul Tiras leckt immer noch seine Wunden vom Dritten Krieg. Und niemand hat so tiefe wie Katherine Prachtmeer.', '', 28153),
(152768, 'deDE', '', 'Versucht, mich nicht wie einen Trottel aussehen zu lassen, ja?', 28153),
(152767, 'deDE', 'Ein paar Tage später wachte er verschwitzt und schreiend auf. Infektionen hatten seine Gedärme zerfressen. Mein Freund erlebte den nächsten Tag nicht.', '', 28153),
(152766, 'deDE', '', 'Wenn hier keine Münzen mehr sind, seht an den anderen Orten nach.', 28153),
(152765, 'deDE', 'Danach sollte er heimgeschickt werden. Aber er war ein alter Dickkopf. Wollte erst gehen, wenn der Krieg gewonnen war. Also hat er sich zusammengeflickt und den Heilern gesagt, ihm fehlt nichts.', '', 28153),
(152763, 'deDE', 'Ein Kampfpott der Orcs hatte unser Schiff getroffen. Rumpfsplitter schossen übers ganze Deck und bohrten sich in meinen Freund.', '', 28153),
(152762, 'deDE', 'Vor vielen Jahren war ich in einer Schlacht. War es im Zweiten Krieg? Schwer, den Überblick zu behalten.', '', 28153),
(152761, 'deDE', 'Hrrm... Bleibt ein Weilchen und lauscht einem alten Ritter.', '', 28153),
(152760, 'deDE', 'Warum würdet Ihr uns helfen?', '', 28153),
(152759, 'deDE', 'Katherine Prachtmeer hat uns abgewiesen und ihre eigene Tochter als Verräterin verbannt.', '', 28153),
(152758, 'deDE', 'Ein fahrender Zandalari hat mir bei einem Handel diesen Trank angeboten. Angeblich soll er alles auf der Stelle kochen können und ich kann keine kostenlose Mahlzeit ablehnen. Probiert ihn bei den Kreaturen hier aus!', '', 28153),
(152757, 'deDE', 'Taelia! Bereitet eine Lagebesprechung für unsere Gäste vor.', '', 28153),
(152756, 'deDE', 'Alles wird schmelzen.', '', 28153),
(152755, 'deDE', 'König Graumähne, es ist mir eine Ehre. Es steht Euch frei, so lange im Hafen zu bleiben, wie nötig.', '', 28153),
(152754, 'deDE', 'Die Ergebnisse sind nicht abzustreiten. Um sicherzugehen, lass ich unsere spitzohrigen Freunde aber vorkosten.', '', 28153),
(152753, 'deDE', '', 'Das Bedürfnis nach Macht. Das Verlangen nach höheren Wahrheiten. Der Wille des Blutes.', 28153),
(152752, 'deDE', '', 'Das Vorgehen der Nazmani erschien mir zunächst... widerwärtig. Aber ich verstehe sie jetzt. Sie sind einfache Leute mit einfachen Bedürfnissen.', 28153),
(152751, 'deDE', '', 'Hier, ich will Euch zeigen, was ich gelernt habe.', 28153),
(152750, 'deDE', '', 'Wir müssen noch so vieles über sie lernen. Ihre Blutmagie... Sie ist mächtiger, als man es sich überhaupt nur vorstellen kann.', 28153),
(152749, 'deDE', '', 'Sie könnten sich als mächtige Werkzeuge gegen die Zandalari und ihre Verbündeten der Horde erweisen.', 28153),
(152748, 'deDE', '', 'Ich habe mehr Vertrauen zu diesen Bluttrollen, den Nazmani, aufbauen können, als ich erwartet habe.', 28153),
(152747, 'deDE', 'Ach, jetzt haltet doch endlich die Schnauze!', '', 28153),
(152746, 'deDE', '', 'Arrrrggrh!', 28153),
(152745, 'deDE', '', 'Ihr müsst verstehen, dass ich nichts gegen Euch persönlich habe. Aber ich kann nicht zulassen, dass Ihr die Fortschritte gefährdet, die ich gemacht habe. Die Dinge, die ich gelernt habe... Und was es noch zu entdecken gibt.', 28153),
(152744, 'deDE', '', 'Dieser Zandalaritroll wird geopfert, um unsere Macht weiter auszubauen.', 28153),
(152743, 'deDE', 'Wir sin\' Euch bis hierher gefolgt. Wir komm\' mit.', 'Wir sin\' Euch bis hierher gefolgt. Wir komm\' mit.', 28153),
(152742, 'deDE', '$p hier weiß, wo in der Nähe eine Gruppe Vulpera is\'. Ich sage, wir schließ\'n uns den\' an, bis die Luft rein is\'.', '', 28153),
(152741, 'deDE', 'Zem\'lans Speichellecker werden aufm Meer nach uns such\'n.', '', 28153),
(152740, 'deDE', 'Aye, aber erst müss\'n wir uns \'ne Weile bedeckt halt\'n.', '', 28153),
(152739, 'deDE', 'Wir behalt\'n unsre Schätze selber.', 'Wir behalt\'n unsre Schätze selber.', 28153),
(152738, 'deDE', 'Wir plündern nach Lust un\' Laune.', 'Wir plündern nach Lust un\' Laune.', 28153),
(152737, 'deDE', 'Wir befahr\'n frei die offene See.', 'Wir befahr\'n frei die offene See.', 28153),
(152736, 'deDE', 'Wir ham\'s geschafft, Matrosen. Wir sin\' Zem\'lan endlich los.', '', 28153),
(152735, 'deDE', 'Alle Mann an die Riemen, un\' mit Höchstgeschwindigkeit zur Küste!', 'Alle Mann an die Riemen, un\' mit Höchstgeschwindigkeit zur Küste!', 28153),
(152734, 'deDE', 'Ich gehe davon aus, dass die Allianz Euch schickt. Ich bin froh, dass Finn und Taelia Euch aus dem verdammten Gefängnis rausholen konnten. \n\nIch bin Sir Carsten Jammerthal. Im Namen der Prachtmeeradmiralität heiße ich Euch in Kul Tiras willkommen.\n\n<Carsten streckt Euch herzlich seine riesige Hand entgegen.>', '', 28153),
(152733, 'deDE', '<Schüttelt seine Hand.>', '<Schüttelt seine Hand.>', 28153),
(152732, 'deDE', 'Ich habe weniger Tage vor als hinter mir.\n\nIch werde sie nicht damit verplempern, zuzusehen, wie Kul Tiras vor die Hunde geht.', '', 28153),
(152731, 'deDE', 'Los, Leute, schnappt Euch den Schatz un\' ab ins Boot!', '', 28153),
(152730, 'deDE', 'Wilhelm fliegt außerhalb Eurer Reichweite. Kehrt nach Korlach zurück!', '', 28153),
(152729, 'deDE', 'Prinzessin, $n, meine Späher bericht\'n, dass Titan\'hüter Hezrel am Fuß von dies\'m Gebäude rumwandert.', '', 28153),
(152728, 'deDE', 'Seit der Sache mit Hakkar gibt\'s \'ne Schwäche in den Köpf\'n der Gurubashi. Ihr Pfad lässt sich allzu leicht verderb\'n und muss ein Ende find\'n.', '', 28153),
(152727, 'deDE', '', 'Ihr könnt nicht... gewinnen...', 28153),
(152726, 'deDE', 'Aye, aye, Käpt\'n!', '', 28153),
(152725, 'deDE', '', 'Korlach gehört dem Zirkel!', 28153),
(152724, 'deDE', 'Ruht Euch aus und genießt den Abend. Morgen planen wir, wie wir uns den Rest von diesem Schatz holen.', 'Ruht Euch aus und genießt den Abend. Morgen planen wir, wie wir uns den Rest von diesem Schatz holen.', 28153),
(152723, 'deDE', 'Willkommen in der Karawane!', 'Willkommen in der Karawane!', 28153),
(152722, 'deDE', 'In dem Fall...', 'In dem Fall...', 28153),
(152721, 'deDE', 'Aye. Vor der Küste is\' \'ne ganze Insel voll davon. Mehr Schätze, als Ihr trag\'n könnt.', '', 28153),
(152720, 'deDE', 'Ein kleiner Fluch hat die Vulpera noch nie von einem Schatz ferngehalten... Habt Ihr noch mehr davon?', 'Ein kleiner Fluch hat die Vulpera noch nie von einem Schatz ferngehalten... Habt Ihr noch mehr davon?', 28153),
(152719, 'deDE', 'Das einzige Problem is\', dass der Schatz verflucht is\'.', 'Das einzige Problem is\', dass der Schatz verflucht is\'.', 28153),
(152718, 'deDE', 'Wir woll\'n wo anners anheuern. Wenn Ihr uns aufnehmt, geb\'n wir Euch was von unserm Schatz ab.', '', 28153),
(152717, 'deDE', 'Pirat\'nkönig Zem\'lan hat Euern Freund getötet. Aber wir ham gemeutert un\' sein\' Schatz gestohl\'n.', '', 28153),
(152716, 'deDE', 'Ich höre...', 'Ich höre...', 28153),
(152715, 'deDE', 'Ruhig Blut! Wir sin\' hier um Frieden auszuhandeln.', '', 28153),
(152714, 'deDE', 'S-s-skelette! N-n-norah, tötet sie!', 'S-s-skelette! N-n-norah, tötet sie!', 28153),
(152713, 'deDE', 'Ausgezeichnete Arbeit. Eine Salve ihrer eigenen Kanonen sollte die Belagerung durch die Treulosen sicher schwächen.', '', 28153),
(152712, 'deDE', 'Ich lebe für einen guten Kampf!', 'Ich lebe für einen guten Kampf!', 28153),
(152711, 'deDE', 'Die Treulosen greifen an. Schnappt Euch eine der gekaperten Kanonen, um bei der Verteidigung des Tempels zu helfen!', '', 28153),
(152710, 'deDE', '', 'Flick, jetzt!', 28153),
(152709, 'deDE', 'Ich bin so weit, wenn Ihr es seid.', 'Ich bin so weit, wenn Ihr es seid.', 28153),
(152708, 'deDE', 'Wollt Ihr Euch vielleicht in Bewegung setzen? Wir sind hier schließlich nicht im Urlaub.', '', 28153),
(152707, 'deDE', 'Aus allen Rohren, Leute!', '', 28153),
(152706, 'deDE', 'Feuert los!', '', 28153),
(152705, 'deDE', 'Zeigt es ihnen, Leute!', '', 28153),
(152704, 'deDE', 'Ziel anvisiert! Feuer!', '', 28153),
(152703, 'deDE', 'Feuer frei!', '', 28153),
(152702, 'deDE', 'Das ist das Ziel! Feuer!', '', 28153),
(152701, 'deDE', 'Ha ha ha...', '', 28153),
(152700, 'deDE', '...Ja. Einen Hauch zu gruselig für unsere Interessenten.', '', 28153),
(152699, 'deDE', 'Zu gruselig?', '', 28153),
(152698, 'deDE', 'Ich habe eine kleine Gewinn- und Verlustrechnung durchgeführt, und ich glaube nicht, dass sich diese Gegend für uns lohnt.', '', 28153),
(152697, 'deDE', 'Und... Was ist mit Eurem Azerit?', '', 28153),
(152696, 'deDE', 'Gut. Springt auf. Wir brennen jetzt ein paar Spuren in den Boden.', '', 28153),
(152695, 'deDE', 'Aber so was von.', '', 28153),
(152694, 'deDE', 'Also... äh... Sollen wir vielleicht hier verschwinden?', '', 28153),
(152693, 'deDE', 'Nein, nein, nein, nein...', '', 28153),
(152692, 'deDE', 'Ihr überwindet besser Eure Furcht vor Hexen, Etrigg. Diese Gegend ist VOLL von Azerit, und... ARGH!', '', 28153),
(152691, 'deDE', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s erhält einen |cFFFF0000|Hspell:263246|h[Blitzschlagschild]|h|r!', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t%s erhält einen |cFFFF0000|Hspell:263246|h[Blitzschlagschild]|h|r!', 28153),
(152690, 'deDE', 'Nicht noch eine!', '', 28153),
(152689, 'deDE', '', 'Euer Blut gehört mir!', 28153),
(152688, 'deDE', 'Wen interessiert das! Habt Ihr das Azeritflöz gefunden?', '', 28153),
(152687, 'deDE', 'Was? Was ist denn?', '', 28153),
(152686, 'deDE', 'Sch-Schnauze!', '', 28153),
(152685, 'deDE', 'Bwaaahahaha! Ein großer, starker Orc, der sich vor Hexen fürchtet.', '', 28153),
(152684, 'deDE', 'NEIN! Ich meine, nein. Ich... mag sie einfach nicht, das ist alles.', '', 28153),
(152683, 'deDE', 'Was habt Ihr gesagt?', '', 28153),
(152682, 'deDE', 'Hütet Euch... vor den... den Hexen...', '', 28153),
(152681, 'deDE', 'Etrigg... Fürchtet Ihr Euch etwa vor Hexen?', '', 28153),
(152680, 'deDE', 'Hat er gerade... H-H-Hexen gesagt?', '', 28153),
(152679, 'deDE', 'Die Versammlungshalle ist nicht sicher! Die Vögel werden uns kriegen!', 'Die Versammlungshalle ist nicht sicher! Die Vögel werden uns kriegen!', 28153),
(152678, 'deDE', 'Nun, dann macht Eure Arbeit und beschützt mich!', '', 28153),
(152677, 'deDE', 'Nein... Aber ich sehe da was anderes. Wir haben Gesellschaft.', '', 28153),
(152676, 'deDE', 'Pah... Das passiert doch ständig. Seht Ihr vielleicht irgendwo Azerit?', '', 28153),
(152675, 'deDE', 'Sie raufen sich überall in Schwärmen zusammen!', 'Sie raufen sich überall in Schwärmen zusammen!', 28153),
(152674, 'deDE', 'Gallywix... Seht Ihr diesen zerfleischten Leichnam hier? Euer Späher ist tot.', '', 28153),
(152673, 'deDE', 'Ja, ja, wenn Ihr das sagt.', '', 28153),
(152672, 'deDE', 'Also schön, wir werden uns das Azerit ansehen. Aber dann MÜSSEN wir uns auf die Allianz konzentrieren!', '', 28153),
(152671, 'deDE', 'Zu... viele... Vögel!', 'Zu... viele... Vögel!', 28153),
(152670, 'deDE', 'Ich werde nie wieder einer Möwe trauen!', 'Ich werde nie wieder einer Möwe trauen!', 28153),
(152669, 'deDE', 'Die alte Martensen hatte recht. Diese Vögel sind bösartig!', 'Die alte Martensen hatte recht. Diese Vögel sind bösartig!', 28153),
(152668, 'deDE', 'Pfft. Einfache Arbeiter.', '', 28153),
(152667, 'deDE', 'Das werden wir uns als Erstes ansehen.', '', 28153),
(152666, 'deDE', 'Das Wichtigste zuerst! Meine Späher berichten mir von einem RIESIGEN Azeritvorkommen hier in Drustvar.', '', 28153),
(152665, 'deDE', 'Dann geht mir aus den Augen oder ich sorge dafür, dass Ihr wirklich etwas Beängstigendes erlebt!', '', 28153),
(152664, 'deDE', 'Wir sollten vorsichtig sein. Seine Worte waren... beunruhigend.', '', 28153),
(152663, 'deDE', 'Ja, aber...', '', 28153),
(152662, 'deDE', '...ein furchtbarer Fluch... Die anderen sind alle...', '', 28153),
(152661, 'deDE', 'Ihr müsst umkehren! Es ist...', '', 28153),
(152660, 'deDE', '', 'Hm. Hatte ich mir größer vorgestellt.', 28153),
(152659, 'deDE', '', 'Nicht genug Spannung. Ich glaube, das braucht mehr Saft.', 28153),
(152658, 'deDE', 'Wir zieh\'n die Wäldchen der Natur den kalten Steinen der Stadt vor. Viele der Zandalari halt\'n uns für Ketzer. Sie behaupt\'n, unsre Matrone sei kein Loa.\n\nWir respektier\'n ihre Meinung. Wir Lun\'alai verfüg\'n schon lange über die Gaben der Natur und könn\' die Gestalten der Wildnis annehm\'n. Wir tracht\'n nach Gleichgewicht, nich\' nach erhandelten Vorteilen.', '', 28153),
(152655, 'deDE', 'Wunderbar. Sind die nicht schön? Oh, an dem Stück hier klebt noch etwas Sand. Ach egal. Gut gemacht.', '', 28153),
(152654, 'deDE', 'In diesem Marschland wird tonnenweise Seeglas angespült, aber das reißen sich die Murlocs unter den Nagel. Besorgt Euch ein paar schöne Brocken. Wie ist egal.', '', 28153),
(152653, 'deDE', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma beginnt, |cFFFF0404|Hspell:249924|h[Seelenzerfetzer]|h|r zu wirken!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma beginnt, |cFFFF0404|Hspell:249924|h[Seelenzerfetzer]|h|r zu wirken!', 28153),
(152652, 'deDE', 'Ihr seid zu spät! Die Invasion hat schon begonn\'!', 'Ihr seid zu spät! Die Invasion hat schon begonn\'!', 28153),
(152651, 'deDE', 'Glaubt Ihr, ich würd allein arbeit\'n? Hier komm\'n meine Partner!', 'Glaubt Ihr, ich würd allein arbeit\'n? Hier komm\'n meine Partner!', 28153),
(152650, 'deDE', '', 'Das ist selbst für diesen schrecklichen Zirkel ein neuer Tiefpunkt. Ich kann Euch nicht genug danken, dass Ihr dieser... dieser Schweinerei ein Ende gesetzt habt.', 28153),
(152649, 'deDE', 'Die Vorlieben des Zirkels grenzen an Frevel. So endet nun eines ihrer wohl schändlichsten Vorhaben.', '', 28153),
(152648, 'deDE', 'Auf geht\'s. Trefft mich hint\'n am Boot. Ich seh zu, dass die Mannschaft es mit Schätz\'n belädt.', '', 28153),
(152647, 'deDE', '', 'Jedes Leben, das wir vor diesem Kult retten können, ist ein Sieg. Gute Arbeit.', 28153),
(152646, 'deDE', 'Die Wege des Todes und der Wiedergeburt sind uns allein vorenthalten. Dank Euch wird das auch so bleiben.', '', 28153),
(152645, 'deDE', '', 'Ihr habt die Bewohner Drustvars vor diesem fliegenden Schrecken bewahrt. Ich danke Euch.', 28153),
(152644, 'deDE', 'Macht keinen Ärger.', 'Macht keinen Ärger.', 28153),
(152643, 'deDE', 'Damit sollten unsere Waldläufer für einige Zeit versorgt sein.', '', 28153),
(152642, 'deDE', 'Na, in alle Ewigkeit plündern un\' brandschatz\'n... ohne Euch!', '', 28153),
(152641, 'deDE', 'Was gibt\'s denn Bess\'res als in alle Ewigkeit zu plündern un\' zu brandschatz\'n?', '', 28153),
(152640, 'deDE', 'Ihr seid \'n grausamer Käpt\'n, Zem\'lan. Die Crew hat Bess\'res verdient!', '', 28153),
(152639, 'deDE', '', 'Ihr müsst, sonst sind wir alle verloren. Geht jetzt!', 28153),
(152638, 'deDE', '', 'Wir lassen Euch nicht zum Sterben zurück!', 28153),
(152637, 'deDE', '', 'Das war knapp! Wir müss\'n nich\' nur die Sande von Vol\'dun, sondern auch das Meer im Auge behalt\'n.', 28153),
(152636, 'deDE', '', 'Das war knapp! Wir scheinen nicht nur die Sandwüste, sondern auch das Meer im Auge behalten zu müssen.', 28153),
(152635, 'deDE', '', 'Ein riesiges Meeresungeheuer wütet an der Küste. Wir müss\'n das Monster aufhalt\'n, bevor es weiter ins Inland vordringt.', 28153),
(152634, 'deDE', '', 'Ein riesiges Meeresungeheuer wütet an der Küste. Wir müssen das Monster aufhalten, bevor es über unser Lager herfällt!', 28153),
(152633, 'deDE', '', 'Xorreth war \'n wichtiger Kommandant der Sethrakarmee. Sein Tod is\' \'n großer Sieg für uns.', 28153),
(152632, 'deDE', '', 'Giftzahnrufer Xorreth war ein hochrangiger Kommandant der Sethrakarmee. Sein Ableben ist ein großer Sieg für uns.', 28153),
(152631, 'deDE', '', 'Die Vulperaspäher bericht\'n von \'nem Sethrakkommandanten in der Nähe. Wir müss\'n das ausnutz\'n und ihn eliminier\'n.', 28153),
(152630, 'deDE', '', 'Unsere Späher haben von einem hochrangigen Sethrakkommandanten in der Nähe berichtet. Wir müssen diese Gelegenheit nutzen, um ihn zu eliminieren, solange es noch geht.', 28153),
(152629, 'deDE', '', 'Gute Arbeit! Ohne \'nen Anführer, der sie zusammenhält, zerstreu\'n sich die Murlocs.', 28153),
(152628, 'deDE', '', 'Gute Arbeit! Ohne einen Anführer, der sie zusammenhält, zerstreut sich der Stamm.', 28153),
(152627, 'deDE', '', 'In der Nähe gibt es einen Stamm Murlocs, der uns Probleme macht. Schaltet ihren Anführer aus, dann zerstreut sich der Stamm.', 28153),
(152626, 'deDE', '', 'In der Nähe gibt\'s \'n Murlocstamm, der uns Scherereien macht. Schaltet ihr\'n Anführer aus, dann zerstreu\'n sie sich.', 28153),
(152625, 'deDE', '', 'Gute Arbeit. Unsere Späher werden erleichtert sein, dass Ihr Mor\'fani ausgeschaltet habt.', 28153),
(152624, 'deDE', '', 'Gute Arbeit. Die Vulpera werd\'n erleichtert sein, dass Ihr Euch um Mor\'fani gekümmert habt.', 28153),
(152623, 'deDE', 'Der Zirkel hat eine große Krähe verzaubert, um sie auf die Bewohner von Drustvar zu hetzen. An ihnen liegt mir zwar nicht viel, aber unsere Dunklen Waldläufer könnten mit den Krähenfedern ausgezeichnete Pfeile bauen.', '', 28153),
(152622, 'deDE', 'Eine ranghohe Hexe des Zirkels opfert Akolythen, um Macht zu gewinnen. Vernichtet sie und zeigt diesen Anfängern, dass nur die Dunkle Fürstin über den Tod gebietet.', '', 28153),
(152621, 'deDE', 'Der Zirkel scheint die Köche des Anwesens ziemlich üble Gerichte zubereiten zu lassen. Wir sollten ihnen so schnell wie möglich das Handwerk legen.', '', 28153),
(152620, 'deDE', '', 'Der Herzbannzirkel hat eine riesige einheimische Krähe verzaubert. Tötet sie, bevor sie noch Zivilisten angreift!', 28153),
(152619, 'deDE', '', 'Der Zirkel opfert seine eigenen Akolythen! Setzt diesem Ritual ein Ende, bevor zu viele ums Leben kommen!', 28153),
(152618, 'deDE', '', 'Ein Verbannter der Zandalari sorgt unter unseren Spähern für Angst und Schrecken. Findet und liquidiert ihn, bevor er noch mehr von ihnen tötet.', 28153),
(152617, 'deDE', '', '\'n vor Kurzem Verbannter sorgt unter den Vulpera für Angst und Schrecken. Beseitigt ihn, bevor er noch mehr von ihnen tötet.', 28153),
(152616, 'deDE', '', 'Die Köche hier setzen den nichts ahnenden Gästen Mahlzeiten aus dubiosen Zutaten vor. Setzt diesem kulinarischen Frevel ein Ende!', 28153),
(152615, 'deDE', 'Aye, aye!', '', 28153),
(152614, 'deDE', 'N-nein, Herr.', '', 28153),
(152613, 'deDE', 'Und jetzt Waffen runter, lasst sie passieren. Wir sprechen in meinem Büro.', '', 28153),
(152612, 'deDE', 'Nein! Ihr dient Kul Tiras! Ihr tragt das Wappen der Prachtmeers! Und Ihr erhaltet Eure Befehle von MIR.', '', 28153),
(152611, 'deDE', 'Ohne Dünger ist es unmöglich, in Vol\'dun Nutzpflanzen anzubauen. Normalerweise holen wir den von den Hyänen, doch da herrscht gerade Ebbe. Füttert ein paar von ihnen, damit es schneller geht.', '', 28153),
(152610, 'deDE', 'Lady Aschenwind? Dient Ihr Lady Aschenwind? Ist das Lady Aschenwinds Wappen auf Eurem Schild?', '', 28153),
(152609, 'deDE', 'Aber Herr... Lady Aschenwind hat befohlen–', '', 28153),
(152608, 'deDE', 'Waffen runter! Wisst Ihr nicht, wer das ist?', '', 28153),
(152607, 'deDE', 'Das ist erstklassiver Dünger. Gute Arbeit. Vergesst aber bloß nicht, Eure Hände zu waschen!', '', 28153),
(152606, 'deDE', 'Wir sollten das stoppen, oder?', '', 28153),
(152605, 'deDE', 'Ist das ein Segel am Horizont? Vielleicht treffen sie ja ein Abkommen mit den Zandalari.', '', 28153),
(152604, 'deDE', 'Treten', 'Treten', 28153),
(152603, 'deDE', 'Die Kiste gibt einen neutralen Ton ab.', '', 28153),
(152602, 'deDE', 'Die Kiste gibt einen fröhlichen Ton ab.', '', 28153),
(152601, 'deDE', 'Die Kiste gibt einen neutralen Ton ab.', '', 28153),
(152600, 'deDE', 'Keine Ahnung. Aber ich geb heute Abend einen aus.', '', 28153),
(152599, 'deDE', '', 'Was ist es denn?', 28153),
(152598, 'deDE', '', 'Ich werde es genießen, Euch auf den Grund des Großen Meeres zu teleportieren. Für die Horde!', 28153),
(152597, 'deDE', 'Was...', '', 28153),
(152596, 'deDE', '', 'Bei Gerüchten über fremde Eindringlinge und Spione können wir nicht vorsichtig genug sein. Leistet Anweisungen Folge und vermeidet peinliche Zwischenfälle.', 28153),
(152595, 'deDE', '', 'Über die Bezahlung sprechen wir später, Dockmeister.', 28153),
(152594, 'deDE', 'So, da ist es ja. Wir werden das versiegeln und zurück nach Sturmwind schicken.', '', 28153),
(152591, 'deDE', '', 'Oculeth... Es tut mir leid...', 28153),
(152590, 'deDE', 'Die Nadel zeigt nach Osten. Wir treffen uns in den Ruinen, $n.', '', 28153),
(152589, 'deDE', '', 'Zu langsam, Zwerg.', 28153),
(152588, 'deDE', 'Bleibt in meiner Nähe. Die Horde lauert irgendwo hier. Ich kann sie riechen.', '', 28153),
(152587, 'deDE', 'Riecht ein wenig blumiger als erwartet. Haben die eine neue Elfensorte entdeckt?', '', 28153),
(152586, 'deDE', 'Es ist nicht hier. Und jetzt scheinen auch noch die Nachtgeborenen hinter uns her zu sein. Na, großartig.', '', 28153),
(152585, 'deDE', 'Wir kommen der Sache näher. Aber haltet mir diese mordlustigen Manasüchtigen vom Leibe, $n.', '', 28153),
(152584, 'deDE', 'Es ist genau unter meinen Füßen... Aber wo...?', '', 28153),
(152583, 'deDE', 'Argh, was für ein fieser Trick!', '', 28153),
(152581, 'deDE', 'Die Kiste summt leise.', '', 28153),
(152580, 'deDE', 'Die Kiste summt leise.', '', 28153),
(152579, 'deDE', 'Die Kiste summt leise.', '', 28153),
(152578, 'deDE', 'Verdammt! Die Götz\'n könn\' nich\' zerstört werden, aber sie ham mir \'ne alte Erinnerung zurückgebracht... die ich vergessen wollte.', '', 28153),
(152577, 'deDE', 'Wollt Ihr mir wirklich weismachen, dass Ihr Zeit habt, mich um Witze anzustupsen, wenn da EIN RIESIGES SCHWERT MITTEN IM HERZEN DES PLANETEN STECKT? Zurück an die Arbeit mit Euch!', '', 28153),
(152576, 'deDE', 'Vergesst Eure Pflicht gegenüber Azeroth nicht.', '', 28153),
(152575, 'deDE', 'Unsere Welt muss geheilt werden.', '', 28153),
(152574, 'deDE', 'Azeroth schreit vor Schmerzen.', '', 28153),
(152573, 'deDE', 'Unsere Welt braucht uns, Champion.', '', 28153),
(152572, 'deDE', '', 'Kaum zu glauben, dass die Trolle auf dem archäologischen Fund des Jahrhunderts gehockt haben!', 28153),
(152571, 'deDE', 'Eure Knochen könnt Ihr behalten. Hier ist eine Quelle der Macht, das kann ich spüren. Wir schnappen sie der Horde vor der Nase weg.', '', 28153),
(152570, 'deDE', '', 'Und jetzt passt auf Eure Hände auf. Ganz ruhig.', 28153),
(152569, 'deDE', '', 'Macht es nicht kaputt. Ja, so...', 28153),
(152568, 'deDE', '', 'Aaaahhh... Seht Euch das an. Wir bringen Euch die Archäologie doch noch bei!', 28153),
(152567, 'deDE', 'Wirklich? Ihr wollt das alles per Hand machen?', '', 28153),
(152566, 'deDE', 'Los, gebt meinem Elementar einen kleinen Schubs. Er wird das für Euch erledigen.', '', 28153),
(152565, 'deDE', '', 'Moment!', 28153),
(152564, 'deDE', 'Gut. Und jetzt zur richtigen Arbeit.', '', 28153),
(152563, 'deDE', '', 'Ihr habt da Kratzer reingemacht! So können wir es nicht ausstellen!', 28153),
(152562, 'deDE', 'Ach, so schlimm ist das gar nicht.', '', 28153),
(152561, 'deDE', 'Meine Knoch\'n sin\' müde. Der Fluch wiegt schwer.', '', 28153),
(152560, 'deDE', 'Pirat\'nkönig Zem\'lan wird dies\'n Tag nie vergess\'n.', '', 28153),
(152559, 'deDE', '', 'Kommt! Das Büro des Hafenmeisters ist gleich dort unten.', 28153),
(152558, 'deDE', 'Puh. Den Mantel muss ich auch waschen.', '', 28153),
(152557, 'deDE', 'Ein guter, robuster Hammer ist ein wertvolles Werkzeug und eine treue Waffe.', '', 28153),
(152556, 'deDE', 'Ohne meinen Hammer bin ich nutzlos. Das ist so, als fehle mir eine Hand.', '', 28153),
(152555, 'deDE', '', 'Ich kann sie nicht lange aufhalten. Nehmt die Rute und verschwindet hier!', 28153),
(152554, 'deDE', 'Untersuchen', 'Untersuchen', 28153),
(152553, 'deDE', 'Diese Höhlen sind voll von Koboldungeziefer.', '', 28153),
(152552, 'deDE', 'Alle Mann ins Boot! Wir seh\'n uns, $p.', '', 28153),
(152551, 'deDE', 'Wir sin\' fast bereit, den Anker zu licht\'n. Zem\'lan wird gar nich\' wiss\'n, wie ihm geschieht.', '', 28153),
(152550, 'deDE', 'Aye.', 'Aye.', 28153),
(152549, 'deDE', 'Aye.', 'Aye.', 28153),
(152548, 'deDE', 'Aye. Zem\'lan is\' kein Käpt\'n, sondern \'n Tyrann. Meuterei is\' der einzige Weg.', 'Aye. Zem\'lan is\' kein Käpt\'n, sondern \'n Tyrann. Meuterei is\' der einzige Weg.', 28153),
(152547, 'deDE', 'Dann sin\' wir uns also einig?', '', 28153),
(152546, 'deDE', 'Aye, un\' wir greif\'n uns unsern Teil der Beute.', '', 28153),
(152545, 'deDE', 'Sieh sich einer all das Gold an...', 'Sieh sich einer all das Gold an...', 28153),
(152544, 'deDE', 'Das is\' ja auch Meuterei, Torfkopp! Wir ramm\' unsre Kling\'n direkt durch Zem\'lans Gerippe.', 'Das is\' ja auch Meuterei, Torfkopp! Wir ramm\' unsre Kling\'n direkt durch Zem\'lans Gerippe.', 28153),
(152543, 'deDE', 'Un\' wir leg\'n\'s echt drauf an.', 'Un\' wir leg\'n\'s echt drauf an.', 28153),
(152542, 'deDE', 'Die sin\' als einzige noch schlimmer dran als wir.', '', 28153),
(152541, 'deDE', 'Da gibt\'s niemand\'n außer Goldsklav\'n, ehemalige Kamerad\'n, gezwung\'n, sich auf ewig um Zem\'lans Schätze zu kümmern.', '', 28153),
(152540, 'deDE', 'Wir schippern zur Gold\'nen Insel, wo Zem\'lan die ganz\'n Schätze hortet, die wir im Laufe der viel\'n Jahre erbeutet ham.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'deDE', 'Alle Mann an die Riemen!', 'Alle Mann an die Riemen!', 28153),
(152538, 'deDE', '~*Hier gibt es als Überleitung etwas Spaß mit Minenwagen.*', '', 28153),
(152537, 'deDE', 'Es is\' so hell hier... Packt meine Knochen zurück in das Loch.', 'Es is\' so hell hier... Packt meine Knochen zurück in das Loch.', 28153),
(152536, 'deDE', '', 'Kul Tiras besteht aus mehreren großen Adelshäusern. \nUnter Daelin Prachtmeer waren sie vereint, aber nach seinem Sturz bei Theramore fing das Bündnis an zu bröckeln.', 28153),
(152535, 'deDE', '', 'Seinen Platz hat Lordadmiralin Katherine Prachtmeer eingenommen. Sie kommandiert das Militär und die Wachen.', 28153),
(152534, 'deDE', '', 'Trotz unserer Mühe, die Ordnung zu wahren, nehmen Verbrechen, Korruption und Piraterie in Kul Tiras zu. \nDas Volk verliert das Vertrauen in die Prachtmeeradmiralität.', 28153),
(152533, 'deDE', '', '.', 28153),
(152532, 'deDE', '', '.', 28153),
(152531, 'deDE', 'Guten Tag. Benötigt Ihr ein Zimmer? Oder eine Erfrischung?', '', 28153),
(152530, 'deDE', 'Es ist mir eine Ehre, Lord und Lady Norwinsen als Wirtschafter dienen zu dürfen. Bitte lasst mich wissen, wenn Ihr einen Raum für die Übernachtung wünscht.', '', 28153),
(152529, 'deDE', 'Ein Anwesen wie dieses macht viel Arbeit. Das Anfertigen von Hufeisen, Reparieren von Rechen und jede Menge anderer Aufgaben, die anfallen. Ein Schmied hat immer etwas zu tun!', '', 28153),
(152528, 'deDE', 'Habt Ihr etwas, das repariert werden soll? Ich kenne mich gut mit Hufeisen aus, aber ich könnte mich auch um Eure Rüstung kümmern.', '', 28153),
(152527, 'deDE', '', 'Lauft. LAUFT!', 28153),
(152526, 'deDE', '', 'Es ist ganz einfach. Lasst Euch nicht verletzen, dann muss ich Euch nicht heilen.', 28153),
(152525, 'deDE', '', 'Ich halte sie so lange auf, wie ich kann.', 28153),
(152524, 'deDE', 'Ihr seid ja ein Naturtalent. Ich wusste, dass Ihr das Zeug habt. Und Ihr habt sogar noch alle Arme und Beine... was will man mehr?', '', 28153),
(152523, 'deDE', 'Sandwürmer sind wilde Raubtiere, die unter den Dünen lauern. Sie sind gefährlich, doch ihre Zähne sind einiges wert. Nehmt meine Angelrute und schaut, was beißt.', '', 28153),
(152522, 'deDE', 'Es könnte immer noch schlimmer kommen. Wir geben unser Bestes mit dem, was wir haben.', '', 28153),
(152521, 'deDE', 'Die Flotte von Kul Tiras ist mir zu Willen. Und bald auch Ihr.', '', 28153),
(152520, 'deDE', '', 'Ich... glaube, ich kann nicht weitergehen.', 28153),
(152519, 'deDE', '', 'Es sind nur noch ein paar Schritte. Wir lassen Euch nicht zurück!', 28153),
(152518, 'deDE', 'Lasst sie die Macht unserer neuen Verbündeten kosten.', '', 28153),
(152517, 'deDE', 'Ich hab nichts mehr zu geb\'n, Zem\'lan... Ihr habt alles bekomm\'n.', 'Ich hab nichts mehr zu geb\'n, Zem\'lan... Ihr habt alles bekomm\'n.', 28153),
(152516, 'deDE', 'Ein weit\'rer Fleischling, den ich beherrsch\'n kann! Das wird \'n besonderer Spaß.', 'Ein weit\'rer Fleischling, den ich beherrsch\'n kann! Das wird \'n besonderer Spaß.', 28153),
(152514, 'deDE', '', 'Kommt schon, wir sind fast da!', 28153),
(152513, 'deDE', '', 'Wir müssen nur den Altar vor uns erreichen.', 28153),
(152512, 'deDE', 'Ihr denkt, Ihr könnt mich aufhalten, doch das Schicksal von Kul Tiras ist längst besiegelt.', '', 28153),
(152507, 'deDE', 'Ich überlasse es Euch, die guten Nachrichten zu überbringen. Ich werde dafür sorgen, dass man sich um diese Kanonen kümmert.', '', 28153),
(152506, 'deDE', 'So! Ich glaube, das waren alle!', '', 28153),
(152505, 'deDE', 'Ha, wieder einer weniger. Fehlt nur noch einer...', '', 28153),
(152504, 'deDE', 'FEUER!', '', 28153),
(152503, 'deDE', 'Damit haben wir sie auf jeden Fall auf uns aufmerksam gemacht. Behaltet die Horde im Auge, während ich nachlade!', '', 28153),
(152502, 'deDE', 'Also gut, los geht\'s. Haltet Euch die Ohren zu!', '', 28153),
(152501, 'deDE', 'Wenn sie doch nur ihre Macht einsetzen würden, um Azeroth zu heilen, anstatt sie zu verletzen. Gute Arbeit, Champion.', '', 28153),
(152500, 'deDE', 'Irgendjemand gewinnt hier in der Umgebung Energie aus Azerit. Ihr müsst die Übeltäter aufhalten!', '', 28153),
(152499, 'deDE', 'Und nun werde ICH Euch in eine glorreiche Zukunft in den Tiefen führen.', '', 28153),
(152498, 'deDE', '', 'Diese Macht... wird... uns... gehören!', 28153),
(152497, 'deDE', '', 'Mit dieser Macht kann niemand gegen die Sethrak bestehen!', 28153),
(152496, 'deDE', 'Findet die Juwelen und setzt sie zurück in ihre Fassungen, damit wir passieren können!', '', 28153),
(152495, 'deDE', 'Die Augen von Sethraliss wurden entfernt!', '', 28153),
(152494, 'deDE', 'Ich habe alles, was ich brauche. Sprecht mich an, wenn Ihr bereit seid, mit dem Ritual zu beginnen.', '', 28153),
(152493, 'deDE', 'Ich hab geseh\'n, wie er in Richtung Stadt gewatsch\'lt is\'. Hofft lieber, dass er sich nich\' zum Narren macht, sonst könnt\'s sein, dass die Leute ihm an den Kragen geh\'n.', '', 28153),
(152492, 'deDE', 'Ich hab die ganze Zeit geseh\'n, wie viel Mühe Ihr Euch mit dem Kleinen gemacht habt. All die Rückschläge und Triumphe. Ihr solltet stolz auf ihn sein. Un\' stolz auf Euch, dass Ihr zu ihm gehalt\'n habt. Das hätt\'n nich\' alle hier getan.\n\nBehandelt Kua\'fon gut. Er wird Euch \'n treuer Gefährte sein... wenn auch vielleicht nich\' der beste Flieger.', '', 28153),
(152491, 'deDE', '', 'G\'huun... will... diese Macht...', 28153),
(152490, 'deDE', '', 'Diese Energie gibt uns Macht. Ihr könnt nix dageg\'n tun!', 28153),
(152489, 'deDE', 'Helfen', 'Helfen', 28153),
(152488, 'deDE', 'Ausweiden', 'Ausweiden', 28153),
(152487, 'deDE', 'Manchmal scheint es, als hätte es der ganze Sumpf auf uns abgesehen. Aber zum Glück seid Ihr der Sache gewachsen!', '', 28153),
(152486, 'deDE', 'Mir ist nicht wohl bei der Sache... Unsere patrouillierenden Späher sollten schon längst zurück sein. Bitte untersucht den Grund für die Verzögerung.', '', 28153),
(152484, 'deDE', '', 'Gehen wir weiter.', 28153),
(152483, 'deDE', '', 'Es war sein Vater, der uns vor vielen Jahren in dieses Tal geführt hat.', 28153),
(152482, 'deDE', '', 'Überhaupt nicht. Er war so nett, bevor die Stimmen ihn verderbt haben.', 28153),
(152481, 'deDE', '', 'War Lord Sturmsang immer so grausam?', 28153),
(152480, 'deDE', '', 'So viel zum Thema unbemerkt.', 28153),
(152479, 'deDE', '', 'Lasst Ihr mich einfach zum Sterben zurück?', 28153),
(152478, 'deDE', 'Dieser Stein pulsiert mit der Macht von Azshara selbst! Bringt ihn zu den Truppen im Fort. Sie wissen, was zu tun ist.', '', 28153),
(152477, 'deDE', 'Danke. Aber wir beiden sollten besser hier verschwinden!', 'Danke. Aber wir beiden sollten besser hier verschwinden!', 28153),
(152476, 'deDE', 'Ich werde nicht als Babynahrung für Pterrordaxe enden!', 'Ich werde nicht als Babynahrung für Pterrordaxe enden!', 28153),
(152475, 'deDE', 'Der Kommandant wird mich dafür büßen lassen, dass ich mich von Wildtieren habe erwischen lassen.', 'Der Kommandant wird mich dafür büßen lassen, dass ich mich von Wildtieren habe erwischen lassen.', 28153),
(152474, 'deDE', 'Danke! Ich dachte, ich wäre vorsichtig genug gewesen, aber dann hat sich noch eine Bestie von der Seite auf mich gestürzt. Kluges Mädchen.', 'Danke! Ich dachte, ich wäre vorsichtig genug gewesen, aber dann hat sich noch eine Bestie von der Seite auf mich gestürzt. Kluges Mädchen.', 28153),
(152473, 'deDE', 'Uff, diese Krallen tun ja mächtig weh!', 'Uff, diese Krallen tun ja mächtig weh!', 28153),
(152472, 'deDE', 'Die verflucht\'n Pterrordaxviecher sin\' \'ne echte Plage. Ich will nich\', dass meine Soldaten in den Bäuchen von denen land\'n!', 'Die verflucht\'n Pterrordaxviecher sin\' \'ne echte Plage. Ich will nich\', dass meine Soldaten in den Bäuchen von denen land\'n!', 28153),
(152471, 'deDE', 'Diese verfluchten Pterrordaxviecher sind eine Plage. Ich will nicht, dass meine Soldaten als Futter für die enden!', 'Diese verfluchten Pterrordaxviecher sind eine Plage. Ich will nicht, dass meine Soldaten als Futter für die enden!', 28153),
(152470, 'deDE', 'Ich hatte gehofft, die Pterrordaxe von dem Aussichtspunkt auf dem Hügel verjagen zu können, aber die schnappen sich einfach unsere Leute einen nach dem anderen... als wäre das ein Kinderspiel!', 'Ich hatte gehofft, die Pterrordaxe von dem Aussichtspunkt auf dem Hügel verjagen zu können, aber die schnappen sich einfach unsere Leute einen nach dem anderen... als wäre das ein Kinderspiel!', 28153),
(152469, 'deDE', 'Die Mogu... werden... noch mehr... Steine... finden...', '', 28153),
(152468, 'deDE', 'Die Macht des Steins wird das Mogureich wiederauferstehen lassen!', '', 28153),
(152467, 'deDE', 'Gute Arbeit! Das waren ein paar mehr, als ich erwartet hatte.', '', 28153),
(152466, 'deDE', 'Die Gurubashi sin\' in \'nen Blutrausch verfall\'n! Wir woll\'n ihnen helf\'n... beim Sterb\'n! Schlagt den Gong un\' wartet, bis sie angelauf\'n komm\'n!', '', 28153),
(152465, 'deDE', 'Es gibt Berichte über rastlose Trolle in der Gegend und wir befürchten, dass ein Angriff bevorsteht. Zeit, ihre Reihen auszudünnen. Schlagt den Gong oben an der Treppe, um sie zu provozieren!', '', 28153),
(152464, 'deDE', 'Jegliche Hilfe, die Ihr uns anbieten könnt, ist uns willkommen.', 'Jegliche Hilfe, die Ihr uns anbieten könnt, ist uns willkommen.', 28153),
(152463, 'deDE', 'Gebt mir eine Axt und ich schlage zu!', '', 28153),
(152462, 'deDE', 'Weidenmänner, Wildtiere... Ich nehme es mit ihnen allen auf!', '', 28153),
(152461, 'deDE', 'In Kul Tiras geben wir uns niemals kampflos geschlagen!', '', 28153),
(152460, 'deDE', 'Danke für die Hilfe.', '', 28153),
(152459, 'deDE', '', 'Wir haben Gesellschaft!', 28153),
(152458, 'deDE', 'LOS! LOS! LOS!', 'LOS! LOS! LOS!', 28153),
(152457, 'deDE', 'Achtung, Marinesoldaten! Am Strand will ich, dass $n die Führung übernimmt. Setzt mit Eurer hübschen kleinen Leuchtpistole alles in Brand, was nicht bei drei auf den Bäumen ist.', 'Achtung, Marinesoldaten! Am Strand will ich, dass $n die Führung übernimmt. Setzt mit Eurer hübschen kleinen Leuchtpistole alles in Brand, was nicht bei drei auf den Bäumen ist.', 28153),
(152456, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(152455, 'deDE', 'Zermalmt diese Eindringlinge oder Eure Gefahrenzulage gehört mir, Welpen!', '', 28153),
(152454, 'deDE', 'Notfallreparaturprotokoll läuft...', '', 28153),
(152453, 'deDE', 'Oh, süßes Azerit!', '', 28153),
(152452, 'deDE', 'Bohr, Baby, bohr!', '', 28153),
(152451, 'deDE', '', 'Gut ist es, wenn Sturmsang nicht bemerkt, dass wir ihn nehmen.', 28153),
(152450, 'deDE', '', 'Es ist direkt.', 28153),
(152449, 'deDE', '', 'Ist das... gut?', 28153),
(152448, 'deDE', '', 'Die Gezeitenweisen begehen diesen zeremoniellen Pfad, um beim Schrein gesegnet zu werden.', 28153),
(152447, 'deDE', '', 'Solange der Fluch auf Euch liegt, kann Euer Fleisch nicht heilen!', 28153),
(152446, 'deDE', '', 'Das kann nicht das Ende sein.', 28153),
(152445, 'deDE', '', 'Wenn Ihr versagt, bin ich verloren!', 28153),
(152444, 'deDE', '', 'Ihr dürft nicht fallen!', 28153),
(152443, 'deDE', 'Warnung! Treibstoffstand kritisch!', '', 28153),
(152442, 'deDE', 'Warnung! Unautorisierten Benutzer erkannt.', '', 28153),
(152441, 'deDE', 'Warnung! Noch null Punkte, dann wird Eure Lizenz eingezogen.', '', 28153),
(152440, 'deDE', 'Da kommt noch einer. Macht Euch bereit.', 'Da kommt noch einer. Bereit machen zum Spucken.', 28153),
(152439, 'deDE', 'Spuckt höher. Dann fliegen sie weiter und Ihr trefft.', 'Spuckt höher. Dann fliegen sie weiter und Ihr trefft.', 28153),
(152438, 'deDE', 'Macht euch bereit!', 'Macht euch bereit!', 28153),
(152437, 'deDE', 'Spuckt genau dann, wenn sie abheben. So werden sie sicher treffen!', 'Spuckt genau dann, wenn sie abheben. So werden sie sicher treffen!', 28153),
(152436, 'deDE', 'Zweeerg im Aaaaaanfluuuug!', '', 28153),
(152435, 'deDE', 'Es ist eine Schande, dass das Azerit die Elemente aus der Balance bringt. Umso mehr Gründe für uns, dem Ganzen ein Ende zu setzen.', '', 28153),
(152434, 'deDE', 'Einige Erdelementare wurden mit Azerit durchströmt und sind verrückt geworden. Erlöst sie und absorbiert ihr Azerit.', '', 28153),
(152433, 'deDE', 'Sie sind hier! Entzündet die Munition!', '', 28153),
(152432, 'deDE', '', 'Die Steine rühren sich... Wir werden sie alle besitzen!', 28153),
(152431, 'deDE', '', 'Die Macht dieses Steins wird unserem Imperium Stärke verleihen!', 28153),
(152430, 'deDE', '<Glibb schaut Euch neugierig an. Brann traut sich nicht, ihm zu sagen, dass er kein Affe ist.>', '<Glibb schaut Euch neugierig an. Brann traut sich nicht, ihm zu sagen, dass er kein Affe ist.>', 28153),
(152429, 'deDE', 'Willkommen im Falkennest. Dank Euch wurden die Monster zurückgedrängt, und wir können uns endlich die Stadt zurückholen. Ihr könnt bei uns bleiben, solange Ihr wollt.', 'Willkommen im Falkennest. Dank Euch wurden die Monster zurückgedrängt, und wir können uns endlich die Stadt zurückholen. Ihr könnt bei uns bleiben, solange Ihr wollt.', 28153),
(152428, 'deDE', 'Diese Waffen stammen wohl von Goblins. Aber so oder so funktionieren sie gut gegen die Sethrak.', '', 28153),
(152427, 'deDE', 'Nisha hat ein paar... interessante Waffen entdeckt, die uns gegen die Sethrak helfen könnten – wenn wir herausfinden, wie man damit umgeht.', '', 28153),
(152426, 'deDE', 'Solche Monster wie diese habe ich noch nie gesehen!', 'Solche Monster wie diese habe ich noch nie gesehen!', 28153),
(152425, 'deDE', 'Kann ich hier raus fliegen?', 'Kann ich hier raus fliegen?', 28153),
(152424, 'deDE', 'Im Moment geht es leider nicht. \n\nAls dieses Chaos begann, da versuchte ich rauszufliegen... nur um vom Boden aus mit Magie beschossen zu werden. Leo wurde an der Flanke getroffen, und wir schafften es nur mit Mühe zurück nach Falkenforst. Wir sind gerade noch mal mit dem Leben davongekommen.\n\nBürgermeister Reinwald hat uns angewiesen, so lange hierzubleiben, bis wir die Stadt zurückerobert haben oder sich die Lage grundlegend gebessert hat.\n\nTut mir leid, aber wir haben im Moment Startverbot.', 'Im Moment geht es leider nicht. \n\nAls dieses Chaos begann, da versuchte ich rauszufliegen... nur um vom Boden aus mit Magie beschossen zu werden. Leo wurde an der Flanke getroffen, und wir schafften es nur mit Mühe zurück nach Falkenforst. Wir sind gerade noch mal mit dem Leben davongekommen.\n\nBürgermeister Reinwald hat uns angewiesen, so lange hierzubleiben, bis wir die Stadt zurückerobert haben oder sich die Lage grundlegend gebessert hat.\n\nTut mir leid, aber wir haben im Moment Startverbot.', 28153),
(152423, 'deDE', 'Tja, das hatte ich nun wirklich nicht erwartet! Unsere Magier werden sich dieses Ding sicherlich genauer ansehen wollen. Ausgezeichnete Arbeit.', '', 28153),
(152422, 'deDE', 'Unsere Späherberichte weisen darauf hin, dass die Horde diesen Sethrak irgendein Artefakt abnehmen will. Kommen wir ihnen doch einfach zuvor.', '', 28153),
(152421, 'deDE', 'Legen wir los, $n.', '', 28153),
(152420, 'deDE', 'Uuuuuuaaaaaaaaaaaaaah!', '', 28153),
(152417, 'deDE', '', 'Gut gemacht, Champion! Diese Dinger sollten unter der Erde bleiben, wo sie hingehören.', 28153),
(152416, 'deDE', '', 'Dreckige Kreaturen... sie opfern die ihren, um Monstrositäten zu erschaffen. Haltet sie auf, bevor wir von fleischfressenden Pflanzen überrannt werden!', 28153),
(152415, 'deDE', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Normal\' ein.>', '<Reiht meine Gruppe in die Warteschlange für eine Inselexpedition auf dem Schwierigkeitsgrad \'Normal\' ein.>', 28153),
(152414, 'deDE', '', 'Wir werd\'n... das Azerit... kontrollier\'n!', 28153),
(152413, 'deDE', '', 'Das Azerit beugt sich meiner Blutmagie!', 28153),
(152412, 'deDE', 'Da putz mir die Knoch\'n! Natürlich meuter ich mit. Ich häng hier doch schon seit Woch\'n!', 'Da putz mir die Knoch\'n! Natürlich meuter ich mit. Ich häng hier doch schon seit Woch\'n!', 28153),
(152411, 'deDE', '', 'Interessant. Vielleicht hilft uns das dabei, das seltsame Phänomen in Nazmir zu verstehen und auch die Herkunft dieser brutalen Bluttrolle.', 28153),
(152410, 'deDE', '', 'Unsere Forscher haben uns gebeten, nach möglichen Artefaktfunden die Augen offen zu halten, besonders, damit sie der Horde nicht in die Hände fallen. Sucht diese Ruine nach etwas Nützlichem ab.', 28153),
(152409, 'deDE', 'Ich hab \'ne Schwäche für Meuterei\'n. Ich bin dabei.', 'Ich hab \'ne Schwäche für Meuterei\'n. Ich bin dabei.', 28153),
(152407, 'deDE', 'Meuterei? Nix lieber als das, Seemann. Zem\'lan wird dafür büß\'n, dass er mich aufs Kreuz gelegt hat.', 'Meuterei? Nix lieber als das, Seemann. Zem\'lan wird dafür büß\'n, dass er mich aufs Kreuz gelegt hat.', 28153),
(152406, 'deDE', 'Wenn Ihr Gold habt, könnt Ihr es hier gerne ausgeben.\n\nSolange Ihr nicht die Geschäfte stört, werden Euch auch meine Leute nicht stören. Klar?', 'Wenn Ihr Gold habt, könnt Ihr es hier gerne ausgeben.\n\nSolange Ihr nicht die Geschäfte stört, werden Euch auch meine Leute nicht stören. Klar?', 28153),
(152405, 'deDE', '', 'Sprecht mit einigen der bekannteren Namen hier: Klaus Schönwind, Kai Karlson, Klonk Schmierbit und Fixi Scharflist.\n\nVertretet mich bei ihnen und seht, ob Ihr ihnen irgendwie helfen könnt. Ich werde nämlich auch ihre Unterstützung brauchen.\n\nUnd wenn es sonst nichts mehr zu bereden gibt, sollte ich jetzt wieder mit den anständigen und besorgten Bürgern hier sprechen.', 28153),
(152404, 'deDE', 'Mit wem sollte ich sprechen?', 'Mit wem sollte ich sprechen?', 28153),
(152403, 'deDE', 'Zu zweit wird das keine Meuterei, $p. Rekrutiert noch \'n paar Leute!', '', 28153),
(152402, 'deDE', 'Wo ist dein Hüter?', '', 28153),
(152401, 'deDE', 'Du bist aber kein sonderlich höfliches Tier.', '', 28153),
(152400, 'deDE', 'Das wollte ich essen.', '', 28153),
(152399, 'deDE', '... Du solltest damit aufhören.', '', 28153),
(152398, 'deDE', 'Dafür müsst Ihr bezahl\'n!', 'Dafür müsst Ihr bezahl\'n!', 28153),
(152397, 'deDE', 'Das gehört Euch nich\'!', 'Das gehört Euch nich\'!', 28153),
(152396, 'deDE', 'Hey! Spuck das aus!', 'Hey! Spuck das aus!', 28153),
(152395, 'deDE', 'Meine Knochen werd\'n sich wieder erheb\'n.', '', 28153),
(152394, 'deDE', 'Aufsteh\'n, meine Herzchen! Vernichtet den Eindringling!', '', 28153),
(152393, 'deDE', 'Kommt zum Festmahl... Ihr Geier...', '', 28153),
(152392, 'deDE', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n hat die Kugel |cFFFF0000|Hspell:267343|h[Fallen lassen]|h|r!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n hat die Kugel |cFFFF0000|Hspell:267343|h[Fallen lassen]|h|r!', 28153),
(152391, 'deDE', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n wird die Kugel |cFFFF0000|Hspell:267633|h[Entrissen]|h|r!', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t$n wird die Kugel |cFFFF0000|Hspell:267633|h[Entrissen]|h|r!', 28153),
(152390, 'deDE', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s hat eine der Kugeln |cFFFF0000|Hspell:265755|h[Zurückgeholt]|h|r!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t%s hat eine der Kugeln |cFFFF0000|Hspell:265755|h[Zurückgeholt]|h|r!', 28153),
(152389, 'deDE', 'Ich hänge Euch bei den Füßen auf und überlasse Euch den Geiern zum Fraß!', '', 28153),
(152388, 'deDE', 'Zuerst ma\' müss\'n wir andre rekrutier\'n un\' Ihr müsst kapier\'n, womit Ihr\'s hier zu tun habt.', '', 28153),
(152387, 'deDE', 'Dann woll\'n wir ma\' meutern.', '', 28153),
(152386, 'deDE', 'Ich möchte etwas anderes fragen.', 'Ich möchte etwas anderes fragen.', 28153),
(152385, 'deDE', 'Hey! Aufhör\'n!', 'Hey! Aufhör\'n!', 28153),
(152384, 'deDE', 'Verschwinde!', 'Verschwinde!', 28153),
(152383, 'deDE', 'Husch! Husch!', 'Husch! Husch!', 28153),
(152382, 'deDE', 'Schluss mit dem Radau!', 'Schluss mit dem Radau!', 28153),
(152381, 'deDE', 'Runter da!', 'Runter da!', 28153),
(152380, 'deDE', 'Ein Papagei? Keine Drachen?', 'Ein Papagei? Keine Drachen?', 28153),
(152379, 'deDE', '<Tan schnaubt verächtlich.>\n\nPapageien sind viel intelligenter und interessanter als ein Drachen.\n\n<Tan öffnet ein Auge und schaut zu seinem Vogel hinüber.>\n\nSelbst wenn sie manchmal nur aus Spaß kreischen.', '<Tan schnaubt verächtlich.>\n\nPapageien sind viel intelligenter und interessanter als ein Drachen.\n\n<Tan öffnet ein Auge und schaut zu seinem Vogel hinüber.>\n\nSelbst wenn sie manchmal nur aus Spaß kreischen.', 28153),
(152378, 'deDE', 'Seit die Eisenfluträuber hier aufgetaucht sind, muss Richard Schotriss alle ein- und ausgehenden Flüge bewilligen.\n\nOffiziell soll die Bucht dadurch \"geheim\" und \"sicher\" gehalten werden, aber wenn Ihr mich fragt, geht es ihm nur darum, alles zu kontrollieren.\n\nIch bräuchte also seine Genehmigung. Hört zu: Meine Haut und die Flügel meines Vogels stehen auf dem Spiel, wenn ich seine Anweisungen ignoriere.\n\n<Tan lehnt sich vor und spricht mit leiser Stimme weiter.>\n\nWenn jemand anderes das Sagen hätte, würde die Sache anders aussehen.', 'Seit die Eisenfluträuber hier aufgetaucht sind, muss Richard Schotriss alle ein- und ausgehenden Flüge bewilligen.\n\nOffiziell soll die Bucht dadurch \"geheim\" und \"sicher\" gehalten werden, aber wenn Ihr mich fragt, geht es ihm nur darum, alles zu kontrollieren.\n\nIch bräuchte also seine Genehmigung. Hört zu: Meine Haut und die Flügel meines Vogels stehen auf dem Spiel, wenn ich seine Anweisungen ignoriere.\n\n<Tan lehnt sich vor und spricht mit leiser Stimme weiter.>\n\nWenn jemand anderes das Sagen hätte, würde die Sache anders aussehen.', 28153),
(152377, 'deDE', 'Könnte ich vielleicht einen Flug hier raus kriegen?', 'Könnte ich vielleicht einen Flug hier raus kriegen?', 28153),
(152376, 'deDE', 'Ihr müsst mir schon runter helf\'n. Nach meiner letz\'n Flucht hamse mich gut festgebund\'n.', '', 28153),
(152375, 'deDE', 'Na großartig! Ich verschwinde von hier!', 'Na großartig! Ich verschwinde von hier!', 28153),
(152374, 'deDE', 'Vielleicht... also, wenn Ihr den Mut dazu habt... erzählt Ihr ihm, dass ich nächstes Mal einen Hut mitbringen werde!', '', 28153),
(152373, 'deDE', 'Jetzt seid Ihr nich\' mehr so groß und stark, was? Geht, mein Diener. Geht und findet diese Ratte Alfin, die Euch befohl\'n hat, meine Art zu töt\'n. Beißt ihn und verdient Euch Eure Gestalt zurück.', '', 28153),
(152372, 'deDE', 'Die Horde ist hier? Wo ist die denn hergekommen?! Und wer soll uns jetzt beschützen?', 'Die Horde ist hier? Wo ist die denn hergekommen?! Und wer soll uns jetzt beschützen?', 28153),
(152371, 'deDE', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tMerektha |cFFFF0000|Hspell:264206|h[Gräbt]|h|r sich durch das Schlachtfeld!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tMerektha |cFFFF0000|Hspell:264206|h[Gräbt]|h|r sich durch das Schlachtfeld!', 28153),
(152370, 'deDE', 'Danke. Ich dachte schon, es wäre um mich geschehen... doch dann seid Ihr gekommen!', 'Danke. Ich dachte schon, es wäre um mich geschehen... doch dann seid Ihr gekommen!', 28153),
(152369, 'deDE', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n ist von einem |cFFFF0000|Hspell:263958|h[Schlangenknäuel]|h|r eingewickelt. Befreit $gihn:sie;!', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n ist von einem |cFFFF0000|Hspell:263958|h[Schlangenknäuel]|h|r eingewickelt. Befreit $gihn:sie;!', 28153),
(152368, 'deDE', 'Der Tag, als der Haf\'n von Zem\'lan verflucht wurde... lang ist\'s her.', '', 28153),
(152367, 'deDE', 'Mein Medaijong zeigt Euch die Vision von meiner Vergang\'nheit, wenn Ihr so weit seid.', '', 28153),
(152366, 'deDE', 'D-d-danke, $p. M-m-meeki ist ein guter Freund.', 'D-d-danke, $p. M-m-meeki ist ein guter Freund.', 28153),
(152365, 'deDE', 'Ich habe versagt... Korthek...', '', 28153),
(152364, 'deDE', 'Ihr wollt also sterben? Diesen Wunsch gewähre ich Euch!', '', 28153),
(152363, 'deDE', 'Niemand kann... uns aufhalten...', '', 28153),
(152362, 'deDE', 'Dreister Narr! Ihr werdet für Eure Unverschämtheit bezahlen!', '', 28153),
(152361, 'deDE', '', 'Euer Kommandant erwartet Euch unten auf dem Schlachtfeld.', 28153),
(152360, 'deDE', 'Das ist nicht... das Ende...', 'Das ist nicht... das Ende...', 28153),
(152359, 'deDE', 'Wir haben eine seltsame Schriftrolle gefunden, die ein Wesen von unglaublicher Macht beschwören soll. An der Küste wimmelt es von Untoten. Finden wir heraus, ob die Schriftrolle wirklich so mächtig ist.', '', 28153),
(152358, 'deDE', 'Das ist nicht... das Ende...', 'Das ist nicht... das Ende...', 28153),
(152357, 'deDE', 'Mein Leben... für das Imperium...', 'Mein Leben... für das Imperium...', 28153),
(152356, 'deDE', 'Das kann nicht sein...', 'Das kann nicht sein...', 28153),
(152355, 'deDE', 'Die Sande... werden sich ausbreiten...', 'Die Sande... werden sich ausbreiten...', 28153),
(152354, 'deDE', 'Mein Tod wird gerächt...', 'Mein Tod wird gerächt...', 28153),
(152353, 'deDE', 'Ich habe Euch enttäuscht... Korthek...', 'Ich habe Euch enttäuscht... Korthek...', 28153),
(152352, 'deDE', 'Ihr habt nicht... gewonnen...', 'Ihr habt nicht... gewonnen...', 28153),
(152351, 'deDE', 'Ihr werdet uns... nicht aufhalten...', 'Ihr werdet uns... nicht aufhalten...', 28153),
(152349, 'deDE', 'Mein Leben... für das Imperium...', 'Mein Leben... für das Imperium...', 28153),
(152348, 'deDE', 'Das kann nicht sein...', 'Das kann nicht sein...', 28153),
(152347, 'deDE', 'Die Sande... werden sich ausbreiten...', 'Die Sande... werden sich ausbreiten...', 28153),
(152346, 'deDE', 'Mein Tod... wird gerächt...', 'Mein Tod... wird gerächt...', 28153),
(152345, 'deDE', 'Ich habe Euch enttäuscht... Korthek...', 'Ich habe Euch enttäuscht... Korthek...', 28153),
(152344, 'deDE', 'Ihr habt nicht... gewonnen...', 'Ihr habt nicht... gewonnen...', 28153),
(152343, 'deDE', 'Ihr werdet uns... nicht aufhalten...', 'Ihr werdet uns... nicht aufhalten...', 28153),
(152342, 'deDE', '', 'Gute Arbeit. Wie immer können wir darauf zählen, dass Ihr es zu Ende bringt.', 28153),
(152341, 'deDE', '', 'Champion, die Bluttrolle haben die Siegesfeste angegriffen. Zeigt ihnen, dass ihre Überfälle nicht ungestraft bleiben werden!', 28153),
(152340, 'deDE', 'Los, Ihr Ratten! Dieses Azerit jagt sich nicht von selbst in die Luft!', '', 28153),
(152339, 'deDE', '', 'Sie haben Brennadam niedergebrannt. Von uns geht keiner nach Hause.', 28153),
(152338, 'deDE', 'Wir müss\'n schneller geh\'n!', '', 28153),
(152337, 'deDE', 'Ihr erinnert mich an einen jungen Ho-zen, den ich mal kannte. Dachte, er wäre eine Art Affenkönig oder so etwas. Der hat mich auch dauernd gepikst.', '', 28153),
(152336, 'deDE', 'Wenn Ihr denkt, dass Ihr mich ärgern könnt, irrt Ihr Euch gewaltig.', '', 28153),
(152335, 'deDE', 'Ich finde, wir sollten unterschiedslos mit allen Völkern Handel treiben... außer den Naga. Schreckliche Kreaturen.', '', 28153),
(152334, 'deDE', 'Wenn Ihr mächtige Artefakte findet, bringt sie zu mir, anstatt zu versuchen, sie selbst zu verwenden.', '', 28153),
(152333, 'deDE', 'Hmph. Artefakte großer Macht gehören in die Hände der Ältesten, nicht in die von leichtsinnigen Abenteurern.', '', 28153),
(152332, 'deDE', 'Unterschätzt nie den Wert von Dingen, die mehr als zwei Jahrhunderte alt sind.', '', 28153),
(152331, 'deDE', 'Blah blah blah. Kommt zum Punkt.', '', 28153),
(152330, 'deDE', 'Wie viel wollt Ihr für Eure Heldentaten? Und wie sieht es aus mit Kosten für Euer Begräbnis?', '', 28153),
(152329, 'deDE', 'Ah gut, ein Abenteurer. Ich brauche Eure Dienste.', '', 28153),
(152328, 'deDE', 'Hier präsentiere ich Euch... die Steinkette!', '', 28153),
(152327, 'deDE', 'Ihr seht hier die Zukunft, Jungs!', '', 28153),
(152326, 'deDE', 'Glückwunsch, Jungs. Wir werden reich sein!', '', 28153),
(152325, 'deDE', '', 'Komm schon rein! Sei nicht so ein Angstsaurier!', 28153),
(152324, 'deDE', 'Nehmt niemals Geschenke des schwarzen Imperiums an.', '', 28153),
(152323, 'deDE', 'Vielleicht begegnen wir uns auf dem Schlachtfeld wieder. Seite an Seite, Rücken an Rücken, von einer Übermacht von Feinden umzingelt. Hee hee.', '', 28153),
(152322, 'deDE', 'Ich bin dran. Komm und hol dir den Fisch!', '', 28153),
(152321, 'deDE', 'Hinsetzen, Schwesta!', '', 28153),
(152320, 'deDE', 'Du bist ja so unreif!', '', 28153),
(152319, 'deDE', 'Ey! Du hast meine Fische verscheucht!', '', 28153),
(152318, 'deDE', '', 'RARRR! Ich bin Pa\'ku! Zisschh!', 28153),
(152317, 'deDE', '', 'Hey, schaut nur, ich bin Gral!', 28153),
(152316, 'deDE', '', 'Taz\'okun!', 28153),
(152315, 'deDE', '', 'Uiiiiiiiii!', 28153),
(152314, 'deDE', 'Viel Glück. Versucht, nicht zu sterben.', '', 28153),
(152313, 'deDE', 'Seid stets auf der Hut – oder schafft Euch einen Panzer an.', '', 28153),
(152312, 'deDE', 'Das werdet Ihr... büßen...', 'Das werdet Ihr... büßen...', 28153),
(152311, 'deDE', 'So... ungerecht...', 'So... ungerecht...', 28153),
(152310, 'deDE', 'Jünger! Eindringlinge nähern sich den heiligen Teichen!', '', 28153),
(152309, 'deDE', 'Nein... Das gehört mir...', 'Nein... Das gehört mir...', 28153),
(152308, 'deDE', 'Wie könnt Ihr... es... wagen...', 'Wie könnt Ihr... es... wagen...', 28153),
(152307, 'deDE', 'Mir scheint, ich werde Euch um das letzte Hemd bringen!', 'Mir scheint, ich werde Euch um das letzte Hemd bringen!', 28153),
(152306, 'deDE', 'Ich mag eine gelegentliche Rauferei. Manchmal auch eine kleine Balgerei oder sogar eine zünftige Keilerei.', '', 28153),
(152305, 'deDE', 'Dafür werde ich Euch das Doppelte berechnen!', 'Dafür werde ich Euch das Doppelte berechnen!', 28153),
(152304, 'deDE', 'Dafür werdet Ihr Euch dumm und dämlich zahlen!', 'Dafür werdet Ihr Euch dumm und dämlich zahlen!', 28153),
(152303, 'deDE', 'He! Das wird nicht billig!', 'He! Das wird nicht billig!', 28153),
(152302, 'deDE', 'Mir sind schon mehr Völker in den Rücken gefallen, als Ihr überhaupt kennt. Also kommt nicht auf dumme Gedanken.', '', 28153),
(152301, 'deDE', 'Der Tod is\' die einzige Gnade, die Zem\'lan gewährt, un\' selbst das bleibt den meist\'n verwehrt.', '', 28153),
(152300, 'deDE', 'Graben', 'Graben', 28153),
(152299, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(152298, 'deDE', '', 'Ich werde nicht ruhen, bis Lord Sturmsangs Kopf von diesen Mauern baumelt.', 28153),
(152297, 'deDE', '', 'Na, das ist die Art Feuerkraft, die wir brauchen!', 28153),
(152296, 'deDE', 'Ha... Na... gut...', 'Ha... Na... gut...', 28153),
(152295, 'deDE', 'Das werdet Ihr... büßen...', 'Das werdet Ihr... büßen...', 28153),
(152294, 'deDE', 'Ich kann nicht... verlieren...', 'Ich kann nicht... verlieren...', 28153),
(152293, 'deDE', 'Aber... Ich bin der Boss...', 'Aber... Ich bin der Boss...', 28153),
(152292, 'deDE', 'Ihr wollt wohl auch Buchtboss werden, was? HA! Euch werde ich genauso schlagen wie den Letzten, der das versucht hat!', 'Ihr wollt wohl auch Buchtboss werden, was? HA! Euch werde ich genauso schlagen wie den Letzten, der das versucht hat!', 28153),
(152291, 'deDE', 'Ich bin hier der Boss! Ihr tanzt besser nicht aus der Reihe!', 'Ich bin hier der Boss! Ihr tanzt besser nicht aus der Reihe!', 28153),
(152290, 'deDE', 'Ruhe jetzt. Meeki geht\'s gut, und ich versuche hier zu schlafen.', 'Ruhe jetzt. Meeki geht\'s gut, und ich versuche hier zu schlafen.', 28153),
(152289, 'deDE', 'Ich werde Euch kielholen lassen!', 'Ich werde Euch kielholen lassen!', 28153),
(152288, 'deDE', 'Niemand segelt gegen die Eisenfluträuber!', 'Niemand segelt gegen die Eisenfluträuber!', 28153),
(152287, 'deDE', 'Wie könnt Ihr es wagen?!', 'Wie könnt Ihr es wagen?!', 28153),
(152286, 'deDE', 'Falls Ihr unterwegs Schätze findet, bringt die auch gleich mit. Wir sorgen dafür, dass es sich für Euch lohnt.', 'Falls Ihr unterwegs Schätze findet, bringt die auch gleich mit. Wir sorgen dafür, dass es sich für Euch lohnt.', 28153),
(152285, 'deDE', 'Dafür bezahlt Ihr...', 'Dafür bezahlt Ihr...', 28153),
(152284, 'deDE', 'Niemand segelt gegen die Eisenfluträuber...', 'Niemand segelt gegen die Eisenfluträuber...', 28153),
(152283, 'deDE', 'Ich... krieg Euch... noch...', 'Ich... krieg Euch... noch...', 28153),
(152282, 'deDE', 'Tut mir... leid, Boss...', 'Tut mir... leid, Boss...', 28153),
(152281, 'deDE', 'Ihr habt hier nichts zu suchen!', 'Ihr habt hier nichts zu suchen!', 28153),
(152280, 'deDE', 'Was schnüffelt Ihr hier herum?!', 'Was schnüffelt Ihr hier herum?!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'deDE', 'Ihr gehört hier nicht hin!', 'Ihr gehört hier nicht hin!', 28153),
(152278, 'deDE', 'Hey!', 'Hey!', 28153),
(152277, 'deDE', '', 'Wusstet Ihr, dass Ihr aus Walhaikiemen eine prima Suppe kochen könnt? Das ist das beste Mittel gegen Schuppenfäule. Ähm, wo waren wir doch gleich?', 28153),
(152276, 'deDE', '', 'Also, mit \"alle\" meinte ich eigentlich nur Leute, die auch etwas Gold ausgeben wollen. Menschen, Goblins, Tauren, Elfen... Das macht für mich keinen Unterschied, solange ihr Gold nur bei mir landet.\n\n<Cesi mustert Euch eingehend.>\n\nOh. Ihr wollt wissen, ob ich auch mit der Horde Geschäfte machen würde?\n\nHört zu: Ich muss mir meinen Unterhalt verdienen, und wenn ich ein paar Anker habe, die von einem Schiff gefallen sind, dann verkaufe ich die an den nächstbesten Kunden. So läuft das. Wenn ich der Boss bin, dann können alle in der Bucht Geschäfte machen.\n\nUnd Ihr wollt Euch ja schließlich nicht mit diesen Eisenfluträubern abgeben müssen, oder?\n\nGlaubt mir, das wird einfach super.', 28153),
(152275, 'deDE', 'Da ham ja meine Kinder bess\'re Manier\'n als Ihr.', '', 28153),
(152274, 'deDE', 'Was meint Ihr damit: den Handel für \"alle\" eröffnen?', 'Was meint Ihr damit: den Handel für \"alle\" eröffnen?', 28153),
(152271, 'deDE', 'Wollt Ihr mir Euern Finger anbiet\'n oder warum tatscht ihr mich an?', '', 28153),
(152270, 'deDE', 'Das Gasthaus hier ist voller Flüchtlinge, aber ich habe ein freies Zimmer zu vermieten, falls Ihr eine Unterkunft braucht.', '', 28153),
(152269, 'deDE', 'Denkt dran: Wenn Ihr Glitzerzeug findet, bringt\'s zu Jani.', '', 28153),
(152268, 'deDE', 'Wenn Ihr geht, kann ich Euer Zeug ham?', '', 28153),
(152266, 'deDE', 'Sucht Freundschaften auch in Kniehöhe. Ha!', '', 28153),
(152265, 'deDE', 'Gut gemacht, Champion! Dank Eurer Bemühungen ist das Land sicherer.', '', 28153),
(152264, 'deDE', 'Unsere Spione haben in diesem Gebiet eine gefährliche Bedrohung ausgemacht. Findet und eliminiert sie!', '', 28153),
(152263, 'deDE', '', 'Baut was daraus und tötet ihr Haustierchen, bevor uns nichts mehr bleibt, um Aschenwinds Flotte aufzuhalten!', 28153),
(152262, 'deDE', '', 'So ein stattlicher Tortollaner, nur ein bisschen zu groß für seinen Panzer, wenn Ihr versteht, was ich meine. Eine Schande, dass er von einem Walhai gefressen wurde.', 28153),
(152261, 'deDE', '', 'Mir wäre beinahe nicht aufgefallen, dass sie geschnarcht hat. Ihre Stimme ist ohnehin so kratzig. Wie bei meinem zweiten Enkel.', 28153),
(152260, 'deDE', '', 'Einige behaupten ehrlich, ich würde leicht abschweifen. Dabei war das bei meiner Schwester noch viel schlimmer. Wusstet Ihr, dass sie einmal mitten im Satz eingeschlafen ist?', 28153),
(152259, 'deDE', '\'n Müllhaufen is\' \'n Ort, wo man sein Zeug aufbewahrt während man loszieht, um mehr ranzuschaff\'n.', '', 28153),
(152258, 'deDE', '', 'Abenteurer sind so höflich heutzutage.', 28153),
(152257, 'deDE', '', 'Ach, wie nett.', 28153),
(152256, 'deDE', '', 'Schaut mal wieder bei Nola vorbei.', 28153),
(152255, 'deDE', '', 'Das erinnert mich an eine Geschichte...', 28153),
(152254, 'deDE', '', 'Ihr seid ja ein richtiger Springinsfeld.', 28153),
(152253, 'deDE', '', 'Schön Euch zu sehen, Ihr kleiner Rumtreiber.', 28153),
(152252, 'deDE', 'Transblahgrifizierer. Macht furchtbare Ideen weniger furchtbar.', 'Transblahgrifizierer. Macht furchtbare Ideen weniger furchtbar.', 28153),
(152251, 'deDE', 'Kaja\'Cola! Jetzt mit echtem Wasser!', 'Kaja\'Cola! Jetzt mit echtem Wasser!', 28153),
(152250, 'deDE', '', 'Ihr seht aus als wüsstet Ihr eine gute Geschichte zu würdigen.', 28153),
(152249, 'deDE', '', 'Trefft mich nördlich dieses Höllenlochs, wenn Ihr die Rute habt. Sucht nach einem Leichenhaufen dieser Bastarde.', 28153),
(152248, 'deDE', 'Was habt Ihr \'n da im Rucksack? Tut das Not, dass das da drin so rumoxidiert?', '', 28153),
(152246, 'deDE', 'Grüße, Zastamann.', '', 28153),
(152243, 'deDE', 'Für die einen isses \'ne Müllhalde, für die andren \'ne Fundgrube!', '', 28153),
(152241, 'deDE', '', 'Nazmir ist das Zuhause zu vieler Gefahren. Wenigstens ist es jetzt eine weniger.', 28153),
(152239, 'deDE', '', 'Was sind das bloß für Viecher? Champion! Unsere Ingenieure haben dafür genau die richtige Lösung. Setzt sie ein und verbrennt sie alle, bevor sie über unsere Lager herfallen!', 28153),
(152232, 'deDE', 'Schön, Euch zum Freund zu haben. Diese Dünen sind dank Euch ein Stückchen sicherer geworden.', '', 28153),
(152231, 'deDE', 'Unsere Karawane hat etwas Gefährliches draußen in den Dünen gesichtet. Ihr kümmert Euch darum, ja?', '', 28153),
(152230, 'deDE', 'Taelia, $p, Ihr müsst diese Bürde tragen. Ich werde mich um Samuel kümmern und Euch beim Schrein treffen, sobald wir können.', '', 28153),
(152229, 'deDE', 'Zwiesprache halten', 'Zwiesprache halten', 28153),
(152228, 'deDE', 'Ich hab doch gewusst, dass Ihr clever seid. Kommt, wir treffen uns dort.', 'Ich hab doch gewusst, dass Ihr clever seid. Kommt, wir treffen uns dort.', 28153),
(152227, 'deDE', 'Viel Glück damit! Mein Spezialgebiet ist das Schmuggeln. Ich bin kein Söldner.', 'Viel Glück damit! Mein Spezialgebiet ist das Schmuggeln. Ich bin keine Söldnerin.', 28153),
(152226, 'deDE', 'Tja, dann werden die Eisenfluträuber wohl verschwinden müssen!', 'Tja, dann werden die Eisenfluträuber wohl verschwinden müssen!', 28153),
(152225, 'deDE', 'Die Eisenfluträuber quetschen das letzte Gold aus mir heraus, Cesi. Ich komme hier kaum über die Runden.', 'Die Eisenfluträuber quetschen das letzte Gold aus mir heraus, Cesi. Ich komme hier kaum über die Runden.', 28153),
(152224, 'deDE', 'Und jetzt... lasst die Jagd beginnen!', '', 28153),
(152223, 'deDE', '', 'Hört mal, wir können hier immer noch Profit machen!', 28153),
(152222, 'deDE', '', 'Diese Leute haben versucht, zu entkommen. Irgendwo müssen Überlebende sein.', 28153),
(152221, 'deDE', 'Dies ist ein Test.', 'Dies ist ein Test.', 28153),
(152220, 'deDE', 'Wir sollten angreifen, bevor Lord Sturmsang davon Wind bekommt.', '', 28153),
(152219, 'deDE', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Nazmir!', '|cFF0000FF(Quest)|r Setzt die Segel, auf nach Nazmir!', 28153),
(152218, 'deDE', '', 'Das Schiff untersteht Eurem Kommando, $n. Ich habe die Besatzung auf alle Eventualitäten vorbereitet.', 28153),
(152217, 'deDE', 'Worauf sollten wir uns konzentrieren?', '', 28153),
(152216, 'deDE', 'Kommt schon mal vor. Wenn Ihr die das nächste Mal seht, denkt einfach nur an eins: Rache.', '', 28153),
(152215, 'deDE', 'Guckt nicht so aus der Wäsche, das ist keine schlechte Ausbeute.', '', 28153),
(152214, 'deDE', 'Alle Mann an Bord! Wir müssen hier verschwinden, bevor wir unser Schiff verlieren.', '', 28153),
(152213, 'deDE', 'Man kann nicht immer gewinnen, was? Nächstes Mal kriegen wir sie.', '', 28153),
(152212, 'deDE', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|tEinige der Verteidigungen beginnen, sich zu |cFFFF0000|Hspell:267931|h[überladen]|h|r!', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|tEinige der Verteidigungen beginnen, sich zu |cFFFF0000|Hspell:267931|h[überladen]|h|r!', 28153),
(152211, 'deDE', 'Ah, wir hab\'n genug von dem Zeug, Lein\'n los!', '', 28153),
(152210, 'deDE', 'Man kann nich\' immer gewinn\'n, so is\' das Leben.', '', 28153),
(152209, 'deDE', 'Grrm! Wir müss\'n jetzt in See stech\'n. Das nächste Mal schafft Ihr\'s.', '', 28153),
(152208, 'deDE', 'Gute Arbeit da draußen. Denen habt Ihr\'s gegeben, ha ha!', '', 28153),
(152207, 'deDE', 'Wir sin\' so weit. Jau, verpass\'n wir dem Allianzschiff noch \'ne Breitseite im Vorbeifahr\'n. Ha ha ha ha!', '', 28153),
(152206, 'deDE', 'Der Laderaum is\' voll. Segel setzen, wir dampf\'n ab!', '', 28153),
(152205, 'deDE', 'Wir haben, was wir brauchen. Zeit zu verduft\'n! Ah ha ha!', '', 28153),
(152204, 'deDE', 'Sammelt alles, was nich\' niet- und nagelfest is\'. Wird Zeit, dass wir in See stech\'n.', '', 28153),
(152203, 'deDE', 'Das andre Schiff wird bald in See stech\'n, wir müss\'n schneller mach\'n.', '', 28153),
(152202, 'deDE', 'Sieht aus, als wär\' das Schiff der Kul Tiraner fast vollgelad\'n. Wir müss\'n bald auslauf\'n.', '', 28153),
(152201, 'deDE', 'Ihr habt\'s fast geschafft, strengt Euch nochmal an.', '', 28153),
(152200, 'deDE', 'Der Laderaum is\' fast voll. Noch \'n bisschen mehr und wir könn\' los.', '', 28153),
(152199, 'deDE', 'Wir sin\' fast fertig, gute Arbeit.', '', 28153),
(152198, 'deDE', 'Gah! Kann mich kaum auf\'n Beinen halt\'n bei dem Beben. Da treibt sich irgendwo \'n gewaltiger Erdelementar rum, der auch nach Azerit sucht.', '', 28153),
(152197, 'deDE', 'Der Orkan sieht aus wie von \'nem Windelementar. Hat wahrscheinlich auch \'ne Menge Azerit, das Ihr einsack\'n könnt.', '', 28153),
(152196, 'deDE', 'He, dieser Eissturm stammt wahrscheinlich von \'nem hohen Wasserelementar. Macht kurz\'n Prozess mit ihm, ich hasse frier\'n.', '', 28153),
(152195, 'deDE', 'Ganz schön heiß, was? Da will sich wohl \'n Feuerelementar unser Azerit unter \'n Nagel reißen. Löscht ihn aus, bevor er uns die Segel abfackelt, ha ha.', '', 28153),
(152194, 'deDE', 'Da muss \'n Elementarlord dahinter stecken. Legt ihn um... und nehmt sein Azerit mit!', '', 28153),
(152193, 'deDE', 'Die Elemente sin\' heute gegen uns. Die woll\'n dasselbe wie wir.', '', 28153),
(152192, 'deDE', 'Jau, \'n paar ziemlich mächtige Elementare haben\'s auf uns abgesehen. Findet ihr\'n Anführer.', '', 28153),
(152191, 'deDE', 'Das is\' kein normales Unwetter, das muss \'n mächtiger Elementar sein, der unser Azerit will.', '', 28153),
(152190, 'deDE', 'Wir sin\' jetzt bei der Hälfte, haltet die Augen off\'n.', '', 28153),
(152189, 'deDE', 'Hey, Ihr leistet gute Arbeit, die Hälfte hab\'n wir schon ma\'.', '', 28153),
(152188, 'deDE', 'Der Laderaum is\' zur Hälfte voll. Weiter so, dann sind wir ruckzuck fertig!', '', 28153),
(152187, 'deDE', 'Oooh, das dürfte spaßig werd\'n.', '', 28153),
(152186, 'deDE', 'Uns\'re Freunde sind auch mit von der Partie, heh heh.', '', 28153),
(152185, 'deDE', 'Haltet die Aug\'n off\'n, wir hab\'n Gesellschaft.', '', 28153),
(152184, 'deDE', 'Hier muss es sein. Das Azerit wartet nur drauf, eingesammelt zu werd\'n.', '', 28153),
(152183, 'deDE', 'Das Schiff hat angelegt. Kommt mir nich\' tot zurück, ja? Heh heh.', '', 28153),
(152182, 'deDE', 'Wir sind da, Freunde. Jetzt bring\'n wir ma\' den Detektor in Stellung.', '', 28153),
(152181, 'deDE', 'Da drüben liegt \'ne Menge Azerit rum. Schaut Euch das an.', '', 28153),
(152180, 'deDE', '\'n dicker Brock\'n Azerit is\' grad aus der Erde gebroch\'n. Los geht\'s, sackt das Zeug ein!', '', 28153),
(152179, 'deDE', 'Uns\'re Instrumente schlag\'n aus wie wild, da muss irgendwo \'n riesiges Lager Azerit sein.', '', 28153),
(152178, 'deDE', 'Wir sin\' so weit. Ich markier die Azeritvorkommen jetz\' auf Eurer Karte.', '', 28153),
(152177, 'deDE', 'Detektor läuft! Werft \'nen Blick auf die Karte für Azeritvorkommen.', '', 28153),
(152176, 'deDE', 'Ich hab nur die Augen ausgeruht! Jetzt geh ich wieder an die Arbeit!', '', 28153),
(152175, 'deDE', 'OK, Boss, ich geh wieder in die Mine.', '', 28153),
(152174, 'deDE', 'Müde... So müde...', '', 28153),
(152173, 'deDE', 'Au! Schon gut, ich geh ja wieder an die Arbeit, $n!', '', 28153),
(152172, 'deDE', 'Tötet die Hoodooverhexer und vernichtet ihre Totems der Erdung.', 'Tötet die Hoodooverhexer und vernichtet ihre Totems der Erdung.', 28153),
(152171, 'deDE', 'Ein neuer Kontinent, und wieder ein Dämon, der gejagt werden muss.', '', 28153),
(152170, 'deDE', 'Ha. Auf Euch kann man sich immer verlassen.', '', 28153),
(152169, 'deDE', 'Uuund geschafft. Gute Arbeit! Dann wollen wir mal.', '', 28153),
(152168, 'deDE', 'Der Frachtraum ist voll. Dann verdünnisieren wir uns mal besser.', '', 28153),
(152167, 'deDE', 'Segel setzen! Nicht übel, das ist \'ne schöne Ausbeute.', '', 28153),
(152166, 'deDE', 'Die Horde hat uns fast abgehängt! Sammelt, was das Zeug hält!', '', 28153),
(152165, 'deDE', 'Ich geh zu... Xibala...', '', 28153),
(152164, 'deDE', 'Die Horde packt wohl zusammen! Wenn wir nicht bald auslaufen, sind wir ein leichtes Ziel.', '', 28153),
(152163, 'deDE', 'Die Horde hat fast alles beisammen! Schnappt Euch einfach noch möglichst viel, ja?', '', 28153),
(152162, 'deDE', 'Ich will Euch nicht beunruhigen, aber das Hordenschiff scheint ziemlich beladen, und wir müssen mit ihnen auslaufen.', '', 28153),
(152161, 'deDE', 'Wir sind fast fertig hier. Haltet die Ohren steif! Ihr macht das schon.', '', 28153),
(152160, 'deDE', 'Im Frachtraum glitzert alles! Noch ein paar Steinchen, dann laufen wir aus.', '', 28153),
(152159, 'deDE', 'Der Frachtraum ist fast voll. Klarmachen zum Auslaufen! Sobald Ihr bereit seid, lichten wir die Anker.', '', 28153),
(152158, 'deDE', 'Hey, fast geschafft! Nur noch ein bisschen, dann stechen wir in See.', '', 28153),
(152157, 'deDE', 'Warum bebt der Boden? Mir ist schon ganz schlecht... Wir haben Erdelementare gesichtet. Dahinter steckt bestimmt ein Elementarlord. Tut was, bevor sich mein Essen über die Reling verabschiedet!', '', 28153),
(152156, 'deDE', 'Diesem Orkan halten unsere Segel nicht lange stand. Ein hoher Windelementar muss seine Diener geschickt haben, Azerit zu sammeln. Solange sie hier sind, können wir keine Segel setzen.', '', 28153),
(152155, 'deDE', 'H-Helden? Ein Wasserlord hat seine Lakaien zum Azeritsammeln hergeschickt und ich erf-f-frier hier gleich. Schaltet sie aus, ich hab meinen Wintermantel nicht eingepackt.', '', 28153),
(152154, 'deDE', 'Hier wird\'s immer heißer. Was zum... ah, das erklärt\'s. Ein Feuerlord hat seine Diener zum Azeritsammeln geschickt. Gut. Super. Großartig.', '', 28153),
(152153, 'deDE', 'Schon halb geschafft! Weiter so, dann können wir hier ratzfatz wieder verschwinden.', '', 28153),
(152152, 'deDE', 'Sie ist schon halb voll mit Azerit. Weiter so, Ihr macht das suu-per.', '', 28153),
(152151, 'deDE', 'Ihr befindet Euch auf heilig\'m Bod\'n!', '', 28153),
(152150, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(152149, 'deDE', 'Die Untersuchung hat uns auf die Ruinen gebracht. Das Lager der Horde ist den Hügel runter im Nordosten, wir sollten also so schnell wie möglich da rein und wieder raus.\n\nIch garantiere, dass wir den Odem von Xibala vor ihnen bekommen.\n\nSagt Bescheid, wenn Ihr bereit seid, die Untersuchung zu beginnen.', '', 28153),
(152148, 'deDE', 'Der Detektor läuft! Die Azeritvorkommen seht Ihr jetzt auf der Karte.', '', 28153),
(152147, 'deDE', 'Detektor in Betrieb! Ich markiere die Azeritstandorte auf Eurer Karte. Nichts zu danken.', '', 28153),
(152146, 'deDE', 'Hab gerade ein riesiges Azeritvorkommen ganz in der Nähe geortet. Deswegen bebt es hier wohl.', '', 28153),
(152145, 'deDE', 'Junge, hier in der Nähe taucht jede Menge Azerit auf! Da sollten wir uns besser vor der Horde drum kümmern.', '', 28153),
(152144, 'deDE', 'Anker liegt, alle aussteigen! Wir fahren den Azeritdetektor hoch, Ihr erledigt die Bösewichte.', '', 28153),
(152143, 'deDE', 'Wir haben angelegt. Viel Spaß bei Eurem Abenteuer! Wir bringen dann mal den Detektor zum Laufen.', '', 28153),
(152142, 'deDE', 'Da wären wir. Dieser Wind ist ja Gift für meine Frisur. Holt das Azerit, dann verduften wir!', '', 28153),
(152141, 'deDE', 'Aaalso, offenbar ist so ein Elementarlord hier und sucht auch nach unserm Azerit. Ich verzieh mich dann mal unter Deck, bis Ihr Euch um dieses... Problemchen gekümmert habt.', '', 28153),
(152140, 'deDE', 'Das Azerit muss noch irgendwelchen Elementarmächten aufgefallen sein. Vielleicht ist ein Lord hinter unserem Azerit her. Aber wer es findet, darf es behalten!', '', 28153),
(152139, 'deDE', 'Die Horde hat diese Insel wohl auch gefunden. Ihr Schiff hat gerade angelegt.', '', 28153),
(152138, 'deDE', 'Oh, da kommt die Horde. Passt auf Euch auf, ja?', '', 28153),
(152137, 'deDE', 'Ich sehe ein Schiff, alles voller Gold... Definitiv Zandalari. Die Horde ist hier, also passt auf.', '', 28153),
(152136, 'deDE', 'Früher war ich auch ein Abenteurer... und dann habe ich etwas aus mir gemacht. Ha Ha.', '', 28153),
(152135, 'deDE', 'Ihr seht aus, als hättet Ihr einige Schlachten mitgemacht. Wir sollten Kriegsgeschichten austauschen.', '', 28153),
(152134, 'deDE', 'Ich erinnere mich an den Großen Krieg zwischen König Raka und seiner Schwester Königin Tola. Na ja, jedenfalls erinnere ich mich an manches. Oder sagen wir so: Ich bin mir sicher, dass es passiert ist. Halbwegs sicher...', '', 28153),
(152133, 'deDE', 'Ihr erinnert mich an einen Burschen, mit dem ich während der dritten Dynastie zusammen die Küste von Krasarang erstürmt habe. Eine Schande, was die Mogu mit ihm gemacht haben.', '', 28153),
(152132, 'deDE', 'Zeit ist für Sturmschnabel noch nicht gekommen! Aaak!', '', 28153),
(152131, 'deDE', 'Genau darum arbeite ich lieber ohne Partner.', '', 28153),
(152130, 'deDE', 'Als Ihr Euch \"Teufelsbann\" genannt habt, da dachte ich eigentlich, Ihr sollt der Bann sein, und nicht in selbigen gezogen werden.', '', 28153),
(152129, 'deDE', 'Zeit, sie umzupusten!', '', 28153),
(152128, 'deDE', '\"Gehen wir in den Dschungel\", habt Ihr gesagt. \"Da gibt es so viel zu sehen\", habt Ihr gesagt. Ich hätte wissen müssen, dass Euer blinder Fleck uns in Schwierigkeiten bringen würde.', '', 28153),
(152127, 'deDE', 'Wenn wir sterben, gebe ich die Schuld dafür Euch.', '', 28153),
(152126, 'deDE', 'Man hat mir gesagt, dass Ihr hier herumschleichen könntet.$b$bDank einer... Indiskretion, die nicht ich verschuldet habe, sondern Marius, sind wir in diesem feuchten Dreckloch gelandet, das auch noch voller Kreaturen ist, die gerne Knochen nagen. Und alles nur, um diesen fiesen Dämon zu finden.$b$bHelft uns, und Ihr könnt Euch von ihrer Leiche alles nehmen, was irgendwelchen Wert besitzt.$b$bUns interessiert nur das völlig uninteressante Stück Papier, das sie bei sich hat.', '', 28153),
(152125, 'deDE', 'Aaak! Gehört ganz Euch!', '', 28153),
(152124, 'deDE', 'Kann Sturmschnabel ein paar Fische haben?', '', 28153),
(152123, 'deDE', 'Hört auf zu schlagen! Mein Mensch!', '', 28153),
(152122, 'deDE', 'Leute wie Ihr lernen es einfach nie.', '', 28153),
(152121, 'deDE', 'Vielleicht hättet Ihr es ihnen nicht so oft sagen sollen. Aaak!', '', 28153),
(152120, 'deDE', 'Die Beute gehört mir!', 'Die Beute gehört mir!', 28153),
(152119, 'deDE', '', 'Ist ja gut, au, da habt Ihr mich erwischt.', 28153),
(152118, 'deDE', '', 'Hierher, Sturmschnabel! Genug gefaulenzt!', 28153),
(152117, 'deDE', '', 'Verschwinde, Vogel. Ich brauche deine Hilfe nicht!', 28153),
(152116, 'deDE', '', 'Das hat ja nicht mal wehgetan. Soll das etwa schon alles sein, Haihappen?!', 28153),
(152115, 'deDE', 'Ha! Ich hab schon nach einer Gelegenheit gesucht, ein bisschen Dampf abzulassen.', 'Ha! Ich hab schon nach einer Gelegenheit gesucht, ein bisschen Dampf abzulassen.', 28153),
(152114, 'deDE', '', 'Ich war absolut nett... bis sie nicht mehr tun wollten, was ich sage...', 28153),
(152113, 'deDE', '', 'Was meinst du mit \"Leute wie Ihr\"?', 28153),
(152112, 'deDE', '', 'Was bilden die sich ein, mich und mein Schiff zu verlassen? Da können sie aber Gift drauf nehmen, dass ich die Großhorn wieder aufbauen und jede einzelne dieser verräterischen Ratten auf dem Bugspriet aufspießen werde!', 28153),
(152111, 'deDE', '', 'Durch und durch nutzlose Miststücke!', 28153),
(152110, 'deDE', 'Sie... wird ewig... herrschen...', 'Sie... wird ewig... herrschen...', 28153),
(152109, 'deDE', 'Besiegt... von Euresgleichen...', 'Besiegt... von Euresgleichen...', 28153),
(152108, 'deDE', 'Die Horde... wird immer... ihr gehören...', 'Die Horde... wird immer... ihr gehören...', 28153),
(152107, 'deDE', 'Nicht... schon wieder...', 'Nicht... schon wieder...', 28153),
(152106, 'deDE', 'Der Tod ist der einzige Weg!', 'Der Tod ist der einzige Weg!', 28153),
(152105, 'deDE', 'Hört Ihr die Schreie?', 'Hört Ihr die Schreie?', 28153),
(152104, 'deDE', 'Keine Überlebenden!', 'Keine Überlebenden!', 28153),
(152103, 'deDE', 'Für die Dunkle Fürstin!', 'Für die Dunkle Fürstin!', 28153),
(152102, 'deDE', 'Lok-tar ogar!', 'Lok-tar ogar!', 28153),
(152101, 'deDE', 'Lok-narash!', 'Lok-narash!', 28153),
(152100, 'deDE', 'Gakarah ma!', 'Gakarah ma!', 28153),
(152099, 'deDE', 'Sieg oder Tod!', 'Sieg oder Tod!', 28153),
(152098, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(152097, 'deDE', 'Tod unseren Feinden!', 'Tod unseren Feinden!', 28153),
(152096, 'deDE', 'Heute werdet Ihr sterben.', 'Heute werdet Ihr sterben.', 28153),
(152095, 'deDE', 'Ein... ehrenhafter... Tod...', 'Ein... ehrenhafter... Tod...', 28153),
(152094, 'deDE', 'Ihr Ahnen... ich komme...', 'Ihr Ahnen... ich komme...', 28153),
(152093, 'deDE', 'Diesen Krieg... werdet Ihr verlieren...', 'Diesen Krieg... werdet Ihr verlieren...', 28153),
(152092, 'deDE', 'Euer Ende... wird kommen...', 'Euer Ende... wird kommen...', 28153),
(152091, 'deDE', 'Ich sterbe... als Krieger...', 'Ich sterbe... als Kriegerin...', 28153),
(152090, 'deDE', 'Mein Kampf... findet ein Ende...', 'Mein Kampf... findet ein Ende...', 28153),
(152089, 'deDE', 'Mein Leben für Draenor...', 'Mein Leben für Draenor...', 28153),
(152088, 'deDE', 'Macht Euch auf den Weg!', 'Macht Euch auf den Weg!', 28153),
(152087, 'deDE', 'Geht endlich!', 'Geht endlich!', 28153),
(152086, 'deDE', 'Enttäuscht die Horde niemals!', 'Enttäuscht die Horde niemals!', 28153),
(152085, 'deDE', 'Sterbt ehrenhaft.', 'Sterbt ehrenhaft.', 28153),
(152084, 'deDE', 'Ich habe Euch nichts mehr zu sagen.', 'Ich habe Euch nichts mehr zu sagen.', 28153),
(152083, 'deDE', 'Geht jetzt!', 'Geht jetzt!', 28153),
(152082, 'deDE', 'Geht mit Ehre!', 'Geht mit Ehre!', 28153),
(152081, 'deDE', 'Möge Eure Klinge niemals stumpf sein.', 'Möge Eure Klinge niemals stumpf sein.', 28153),
(152080, 'deDE', 'Geht! Sichert Euch den Sieg!', 'Geht! Sichert Euch den Sieg!', 28153),
(152079, 'deDE', 'Vergesst Eure Pflicht nicht!', 'Vergesst Eure Pflicht nicht!', 28153),
(152078, 'deDE', 'Raus mit der Sprache!', 'Raus mit der Sprache!', 28153),
(152077, 'deDE', 'Ich habe keine Zeit zu verschwenden.', 'Ich habe keine Zeit zu verschwenden.', 28153),
(152076, 'deDE', 'Raus damit, ich warte...', 'Raus damit, ich warte...', 28153),
(152075, 'deDE', 'Sprecht!', 'Sprecht!', 28153),
(152074, 'deDE', 'Ich grüße Euch.', 'Ich grüße Euch.', 28153),
(152073, 'deDE', 'Lok-tar!', 'Lok-tar!', 28153),
(152072, 'deDE', 'Throm-ka!', 'Throm-ka!', 28153),
(152071, 'deDE', 'Was wollt Ihr?', 'Was wollt Ihr?', 28153),
(152070, 'deDE', 'Zug-zug.', 'Zug-zug.', 28153),
(152069, 'deDE', 'Kraft und Ehre.', 'Kraft und Ehre.', 28153),
(152068, 'deDE', 'Seid Ihr in Azeroth alle so anstrengend?', 'Seid Ihr in Azeroth alle so anstrengend?', 28153),
(152067, 'deDE', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 28153),
(152066, 'deDE', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 28153),
(152065, 'deDE', 'ORC... DRAUFHAUEN!', 'ORC... DRAUFHAUEN!', 28153),
(152064, 'deDE', 'Die Schergen des Zirkels müssen sie außerhalb der Mauern noch beschäftigen.', '', 28153),
(152063, 'deDE', '', 'Aber wo sind die anderen Inquisitoren?', 28153),
(152062, 'deDE', 'Lok-tar ogar!', 'Lok-tar ogar!', 28153),
(152061, 'deDE', 'Mein Zorn wird Euch vernichten!', 'Mein Zorn wird Euch vernichten!', 28153),
(152060, 'deDE', 'Euer Schicksal ist besiegelt!', 'Euer Schicksal ist besiegelt!', 28153),
(152059, 'deDE', 'Die Horde wird Euch vernichten.', 'Die Horde wird Euch vernichten.', 28153),
(152058, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(152057, 'deDE', 'Tod unseren Feinden!', 'Tod unseren Feinden!', 28153),
(152056, 'deDE', 'Heute werdet Ihr sterben.', 'Heute werdet Ihr sterben.', 28153),
(152055, 'deDE', 'Ein... ehrenhafter... Tod...', 'Ein... ehrenhafter... Tod...', 28153),
(152054, 'deDE', 'Ihr Ahnen... ich komme...', 'Ihr Ahnen... ich komme...', 28153),
(152053, 'deDE', 'Diesen Krieg... werdet Ihr verlieren...', 'Diesen Krieg... werdet Ihr verlieren...', 28153),
(152052, 'deDE', 'Euer Ende... wird kommen...', 'Euer Ende... wird kommen...', 28153),
(152051, 'deDE', 'Geister... nehmt mich auf...', 'Geister... nehmt mich auf...', 28153),
(152050, 'deDE', 'Mein Kampf... findet ein Ende...', 'Mein Kampf... findet ein Ende...', 28153),
(152049, 'deDE', 'Mein Geist... kehrt nach Draenor zurück...', 'Mein Geist... kehrt nach Draenor zurück...', 28153),
(152048, 'deDE', 'Kommt wieder... und bringt mehr Gold mit.', 'Kommt wieder... und bringt mehr Gold mit.', 28153),
(152047, 'deDE', 'Mögen diese Waren Euch gute Dienste leisten.', 'Mögen diese Waren Euch gute Dienste leisten.', 28153),
(152046, 'deDE', 'Kommt gern wieder.', 'Kommt gern wieder.', 28153),
(152045, 'deDE', 'Sterbt ehrenhaft.', 'Sterbt ehrenhaft.', 28153),
(152044, 'deDE', 'Viel mehr habe ich nicht zu sagen.', 'Viel mehr habe ich nicht zu sagen.', 28153),
(152043, 'deDE', 'Wir sind hier fertig.', 'Wir sind hier fertig.', 28153),
(152042, 'deDE', 'Geht mit Ehre!', 'Geht mit Ehre!', 28153),
(152041, 'deDE', 'Mögen Euch die Geister Euren Weg zeigen.', 'Mögen Euch die Geister Euren Weg zeigen.', 28153),
(152040, 'deDE', 'Geht! Sichert Euch den Sieg!', 'Geht! Sichert Euch den Sieg!', 28153),
(152039, 'deDE', 'Verbleiben wir so.', 'Verbleiben wir so.', 28153),
(152038, 'deDE', 'Was sucht ihr?', 'Was sucht ihr?', 28153),
(152037, 'deDE', 'Was darf\'s denn sein?', 'Was darf\'s denn sein?', 28153),
(152036, 'deDE', 'Seht Euch nur um!', 'Seht Euch nur um!', 28153),
(152035, 'deDE', 'Sprecht!', 'Sprecht!', 28153),
(152034, 'deDE', 'Seid gegrüßt.', 'Seid gegrüßt.', 28153),
(152033, 'deDE', 'Lok-tar!', 'Lok-tar!', 28153),
(152032, 'deDE', 'Throm-ka!', 'Throm-ka!', 28153),
(152031, 'deDE', 'Was wollt Ihr?', 'Was wollt Ihr?', 28153),
(152030, 'deDE', 'Zug-zug.', 'Zug-zug.', 28153),
(152029, 'deDE', 'Kraft und Ehre.', 'Kraft und Ehre.', 28153),
(152028, 'deDE', 'Seid Ihr in Azeroth alle so anstrengend?', 'Seid Ihr in Azeroth alle so anstrengend?', 28153),
(152027, 'deDE', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 28153),
(152026, 'deDE', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 28153),
(152025, 'deDE', 'ORC... DRAUFHAUEN!', 'ORC... DRAUFHAUEN!', 28153),
(152024, 'deDE', 'Was Bessres, als frisch gefang\'nen Fisch zu kochen, gibt\'s eigentlich gar nich\'.', '', 28153),
(152023, 'deDE', '', 'Wir sin\' unterwegs, um von all dem wegzukomm\'n. Schon witzig, dass wir\'s nich\' sonderlich weit geschafft ham. Aber die Aussicht is\' einfach nich\' zu schlag\'n.', 28153),
(152017, 'deDE', 'Wie hat es nur die Ketten gesprengt?!', 'Wie hat es nur die Ketten gesprengt?!', 28153),
(152016, 'deDE', 'Wir sollten nicht bleiben, um das herauszufinden!', 'Wir sollten nicht bleiben, um das herauszufinden!', 28153),
(152015, 'deDE', 'Blutverseuchung!', '', 28153),
(152014, 'deDE', 'Blume untersuchen', 'Blume untersuchen', 28153),
(152013, 'deDE', 'Der Avatar von Sethraliss ist jetzt nicht mehr verhext! Stellt seine vollständige Gesundheit wieder her, um die Verteidigung zu deaktivieren!', 'Der Avatar von Sethraliss ist jetzt nicht mehr verhext! Stellt seine vollständige Gesundheit wieder her, um die Verteidigung zu deaktivieren!', 28153),
(152012, 'deDE', 'Evolution!', '', 28153),
(152011, 'deDE', 'Infektion!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'deDE', 'Die Pestilenz wuchert!', '', 28153),
(152009, 'deDE', 'Gebärt neues Blut!', '', 28153),
(152008, 'deDE', 'Verschlinge Hüllen!', '', 28153),
(152007, 'deDE', 'Das reicht! Ihr von der Horde wolltet es ja so.', '', 28153),
(152006, 'deDE', 'Tödlicher Stamm. Ansteckung erfolgreich.', '', 28153),
(152005, 'deDE', 'Ich habe meine Verkleidung verloren. Habt Ihr vielleicht noch eine Schriftrolle?', 'Ich habe meine Verkleidung verloren. Habt Ihr vielleicht noch eine Schriftrolle?', 28153),
(152004, 'deDE', 'Der Dschungelhüpfer hopst ins Wasser!', '', 28153),
(152003, 'deDE', 'Fäulnis!', '', 28153),
(152002, 'deDE', 'Reif zur Infektion!', '', 28153),
(152001, 'deDE', 'Ausbruch unausweichlich...', '', 28153),
(152000, 'deDE', '', 'Nett. PAH! An dem ist gar nichts nett.', 28153),
(151999, 'deDE', '', 'Habt Ihr das heimtückische Genie namens Herr Nett schon gefunden?', 28153),
(151998, 'deDE', 'Frische Wirte!', '', 28153),
(151990, 'deDE', 'Also dann... Zeit, uns unsere Trophäe zu nehmen.', '', 28153),
(151989, 'deDE', 'Wir haben die Perle! Mit ihr werden unsere Schiffe zu Raubtieren der Meere.', '', 28153),
(151987, 'deDE', '', 'Genießt Euren Sieg. Es wird Euer letzter sein.', 28153),
(151986, 'deDE', 'Es ist das Gesetz der Wildnis. Die Starken nehmen von den Schwachen.', '', 28153),
(151985, 'deDE', 'Haltet Eure Sinne geschärft. Etwas Unsichtbares lauert auf uns.', '', 28153),
(151983, 'deDE', 'Die Allianz darf diese Trophäe nicht bekommen. Wer uns trotzt, wird fallen!', '', 28153),
(151982, 'deDE', '', 'Ihr habt dafür gesorgt, dass ich wieder im Geschäft bin, also ja. Mit Cesi als Boss würden wir hier wieder richtig Geld verdienen.', 28153),
(151981, 'deDE', 'Werdet Ihr Cesi Zündschnur unterstützen?', 'Werdet Ihr Cesi Zündschnur unterstützen?', 28153),
(151980, 'deDE', '', 'Früher liefen die Geschäfte hier sehr viel besser.', 28153),
(151979, 'deDE', '', 'Verschwinden wir, bevor wir mit dem Rücken zur Wand stehen. Los!', 28153),
(151978, 'deDE', 'Haus Sturmsang wird dieses versunkene Reich beherrschen. Der Zorn der Gezeitenmutter sorgt dafür.', '', 28153),
(151977, 'deDE', 'Die Flotte... wird ihr gehören...', '', 28153),
(151976, 'deDE', 'Ich habe nur mit ihnen gespielt, Herr. Betrachtet es als erledigt!', '', 28153),
(151975, 'deDE', 'Unser Schicksal hat sich bald erfüllt. Sie dürfen den Schrein des Sturms nicht betreten.', '', 28153),
(151974, 'deDE', '', 'Seht, was aus Euch geworden ist. All dieses Blut klebt an Euren Händen!', 28153),
(151973, 'deDE', 'Die Schriftrolle schwebt und summt. Es erscheinen Visionen von anderen Orten, die von Magie verschleiert wurden.', '', 28153),
(151972, 'deDE', 'Überleben der Weltenseele: Unwahrscheinlich...', '', 28153),
(151971, 'deDE', 'Planetare Infektion steht bevor.', '', 28153),
(151970, 'deDE', 'Wir sollten den Eisenfluträubern den Schatz überlassen.', 'Wir sollten den Eisenfluträubern den Schatz überlassen.', 28153),
(151969, 'deDE', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s erschafft einen |cFFFF0000|Hspell:267891|h[Schnelligkeitszauberschutz]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s erschafft einen |cFFFF0000|Hspell:267891|h[Schnelligkeitszauberschutz]|h|r!', 28153),
(151968, 'deDE', '<Stecht einfach auf ihn ein.>', '<Stecht einfach auf ihn ein.>', 28153),
(151967, 'deDE', '...Meint Ihr das ernst?', '...Meint Ihr das ernst?', 28153),
(151966, 'deDE', 'Das ist eine Frechheit! Das werde ich nicht bezahlen!', 'Das ist eine Frechheit! Das werde ich nicht bezahlen!', 28153),
(151965, 'deDE', 'Ein Platz auf dem Boden kostet fünfzig Gold pro Nacht. Sechzig in der Nähe des Feuers. Bringt Eure eigenen Decken mit.\n\nBetten kosten hundert Gold pro Nacht.\n\nDas Binden des Ruhesteins kostet fünfundsiebzig Gold pro Woche.\n\nDas passt Euch nicht? \n\n<Er verschränkt die Arme mit einem spöttischen Grinsen.>\n\nWie schade. Das sind eben die normalen Preise.', '', 28153),
(151964, 'deDE', 'Die Tiefen verkündeten Eure Ankunft... und Euren Untergang!', '', 28153),
(151963, 'deDE', 'Massive Kontaminierung festgestellt.', '', 28153),
(151962, 'deDE', '', 'Wir müss\'n unsre Streitkräfte sammeln un\' das Übel anner Wurzel pack\'n.', 28153),
(151961, 'deDE', '', 'Der Titan hat uns Zeit erkauft, aber G\'huun wird sich nich\' lange aufhalt\'n lassen.', 28153),
(151960, 'deDE', 'Befallenes Exemplar entdeckt. Prioritätsstufe eins.', '', 28153),
(151959, 'deDE', 'Verschlingen! Nähren! Verbreiten!', '', 28153),
(151958, 'deDE', '', 'Das Ding sucht nach seiner Mutta? Hoffen wir, dass es uns zu was führt, das die Verbreitung von der Seuche stopp\'n kann.', 28153),
(151957, 'deDE', 'G\'huuneindämmung versagt. M.U.T.T.E.R. reagiert nicht.', '', 28153),
(151954, 'deDE', '', 'Wenn sie es bis an die Oberfläche schafft, könn\' wir nich\' mehr viel ausricht\'n.', 28153),
(151953, 'deDE', '', 'Derartige Verderbnis hab ich noch nie geseh\'n.', 28153),
(151952, 'deDE', '', 'Sie darf nich\' an die Oberfläche gelang\'n. Vernichtet sie!', 28153),
(151951, 'deDE', '', 'Pfui! Was\'n das für \'ne Kreatur?', 28153),
(151950, 'deDE', '', 'Seid auf der Hut! Wer weiß, was in den Höhl\'n hier lauert.', 28153),
(151949, 'deDE', '', 'Die Bluttrolle sin\' versprengt, aber wir müss\'n die Wurzel von dem Übel find\'n.', 28153),
(151948, 'deDE', 'Wir bring\'n Euch \'n Geschenk, großer Todesloa.', '', 28153),
(151947, 'deDE', 'Wenn das bedeutet, dass wir ein paar neue Gesichter zu sehen bekommen, ja, dann mache ich das.', '', 28153),
(151946, 'deDE', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t $s beginnt, |cFFFF0404|Hspell:260773|h[Übles Ritual]|h|r zu wirken!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s beginnt, |cFFFF0404|Hspell:260773|h[Übles Ritual]|h|r zu wirken!', 28153),
(151945, 'deDE', 'Werdet Ihr Cesi Zündschnur unterstützen?', 'Werdet Ihr Cesi Zündschnur unterstützen?', 28153),
(151944, 'deDE', 'Kauft Ihr oder verkauft Ihr?', '', 28153),
(151943, 'deDE', '', 'Das sieht nicht gut aus...', 28153),
(151942, 'deDE', 'Mit Freuden. Sie werden in Eurem Namen leiden!', '', 28153),
(151941, 'deDE', 'Kontaminierung festgestellt. Wird sterilisiert.', '', 28153),
(151940, 'deDE', 'Pestilenzexplosion!', '', 28153),
(151939, 'deDE', 'Letzte Schutzmaßnahme wird eingeleitet. Virenquelle wird ausgelöscht.', '', 28153),
(151938, 'deDE', 'Unverzüglich, Herr. Erlaubt mir nur, vorher ein paar Plagen zu beseitigen.', 'Unverzüglich, Herr. Erlaubt mir nur, vorher ein paar Plagen zu beseitigen.', 28153),
(151937, 'deDE', 'Gebiet wird gereinigt.', '', 28153),
(151936, 'deDE', 'Läuterungsprotokolle gestartet.', '', 28153),
(151935, 'deDE', 'Übler Ausbruch!', '', 28153),
(151934, 'deDE', 'Nur \'n paar gebroch\'ne Knoch\'n... nix Ernstes.', '', 28153),
(151933, 'deDE', 'Führt uns zu den Vulpera, $p. Wir schlepp\'n den Schatz.', '', 28153),
(151932, 'deDE', 'Blutausstoß!', '', 28153),
(151931, 'deDE', '', 'Legt Eure Waffen nieder! Ihr müsst das nicht tun!', 28153),
(151930, 'deDE', 'Muss... verbreiten...', '', 28153),
(151929, 'deDE', 'Seuche berührt!', '', 28153),
(151928, 'deDE', 'Infiziert!', '', 28153),
(151927, 'deDE', 'Fleisch verderben!', '', 28153),
(151926, 'deDE', 'Verzehren!', '', 28153),
(151925, 'deDE', 'Muss verbreiten!', '', 28153),
(151924, 'deDE', 'Vergesst jetz\' nur nich\' Euern Teil der Abmachung...', '', 28153),
(151923, 'deDE', 'Hahahaha! Seht Ihr, Majestät? Bwonsamdi hält immer Wort.', '', 28153),
(151922, 'deDE', 'Steht auf... steht auf! Fertig gefaulenzt! Nehmt Eure Speere und KÄMPFT!', '', 28153),
(151921, 'deDE', 'Beherrscht Euch, Majestät. Bwonsamdi hilft sein\' Freunden immer...', '', 28153),
(151920, 'deDE', '', 'Ihr müsst mir nich\' von da bei der Arbeit zuseh\'n. Wir beide hab\'n Arbeit zu erledig\'n.', 28153),
(151919, 'deDE', 'Das Schiff kann ableg\'n, wenn wir bereit sind.', '', 28153),
(151918, 'deDE', 'Diese Verräter steh\'n zwischen mir und meinem Königreich. Und wo ist jetzt die Hilfe, die Ihr versproch\'n habt? Beabsichtigt Ihr, Euer Wort zu halt\'n?', '', 28153),
(151916, 'deDE', 'Ihr habt Euch gut geschlagen, Champion. Ich kann fühlen, wie sich Azeroth erholt und an Stärke gewinnt, dank Euch.', '', 28153),
(151915, 'deDE', 'In der Nähe gibt es mehrere offene Azeritwunden. Verwendet das Herz von Azeroth, um sie zu schließen!', '', 28153),
(151913, 'deDE', 'Lauft, solange Ihr noch könnt!', '', 28153),
(151912, 'deDE', 'Also, das is\' ja nich\' gerade \'n respektvoller Tonfall gegenüber Euerm Loa, Majestät. Ich schätz ma\', die Seelen, die ich heut\' sammeln werd, sollt\'n das mehr als wettmach\'n!', '', 28153),
(151911, 'deDE', 'Wir steck\'n da jetzt zusamm drin, $p.\n\nMeuterei oder aufgeknüpft an der Rah.', '', 28153),
(151910, 'deDE', 'Bwonsamdi, zeigt Euch!', '', 28153),
(151909, 'deDE', 'Zu viele hab\'n sich auf Zuls Seite geschlag\'n. Jetzt gibt\'s nur noch einen Weg...', '', 28153),
(151908, 'deDE', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s nimmt |cFFFF0000$n|r ins Visier und macht sich bereit, |cFFFF0000|Hspell:266951|h[Durchzustürmen]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s nimmt |cFFFF0000$n|r ins Visier und macht sich bereit, |cFFFF0000|Hspell:266951|h[Durchzustürmen]|h|r!', 28153),
(151907, 'deDE', 'Die uralten Zauberschutze, die das Herz von Sethraliss beschützen, wurden von einer Gruppe Zandalari deaktiviert...', 'Die uralten Zauberschutze, die das Herz von Sethraliss beschützen, wurden von einer Gruppe Zandalari deaktiviert...', 28153),
(151906, 'deDE', 'Ja, Cesi kann sich auf meine Unterstützung verlassen.', '', 28153),
(151905, 'deDE', 'Also los, Ihr faulen Goblins. Ich will, dass die Instabasis sofort aufgebaut wird!', 'Also los, Ihr faulen Goblins. Ich will, dass die Instabasis sofort aufgebaut wird!', 28153),
(151904, 'deDE', 'Werdet Ihr Cesi Zündschnur unterstützen?', 'Werdet Ihr Cesi Zündschnur unterstützen?', 28153),
(151902, 'deDE', 'Hm... Ja, lasst mich mal sehen.\n\n<Kooda wühlt eine ganze Weile herum, bevor er ein Glas aus den Tiefen des Rucksacks hervorholt.>\n\nDie habe ich vor einigen hundert Jahren gekauft. Ich hatte sie schon vergessen. Ich könnte sie Euch wohl verkaufen.', '', 28153),
(151901, 'deDE', 'Habt Ihr vielleicht schon einmal von einer \"Jahrhundertsauce\" gehört? Habt Ihr sie womöglich?', 'Habt Ihr vielleicht schon einmal von einer \"Jahrhundertsauce\" gehört? Habt Ihr sie womöglich?', 28153),
(151900, 'deDE', 'Hallo, $R. Habt Ihr irgendetwas Interessantes zu verkaufen?', '', 28153),
(151899, 'deDE', 'Bei den Gezeiten... Es kommt!', 'Bei den Gezeiten... Es kommt!', 28153),
(151898, 'deDE', 'Unstillbarer Hunger. Der König nährt sich.', '', 28153),
(151897, 'deDE', 'Die Wunde schwärt. Die Welt verrottet.', '', 28153),
(151896, 'deDE', 'Wir waren immer in Eurem Verstand.', '', 28153),
(151895, 'deDE', 'Die verderbten Schreie künden von seiner Ankunft.', '', 28153),
(151894, 'deDE', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal der Weise beginnt, |cFFFF0000|Hspell:267273|h[Giftnova]|h|r zu wirken!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal der Weise beginnt, |cFFFF0000|Hspell:267273|h[Giftnova]|h|r zu wirken!', 28153),
(151893, 'deDE', '', 'Die Kriechenden sind erwacht!', 28153),
(151892, 'deDE', '', 'Kril lax qutholil!', 28153),
(151890, 'deDE', 'Ihr habt Euch als mein Avatar den Naga gestellt und dem Angriff auf meinen Tempel ein Ende gesetzt.', '', 28153),
(151889, 'deDE', '', 'Oh! Jahrhundertsauce will ich schon seit einer Ewigkeit ausprobieren! Das ist eine Kochpaste, die aus verschiedenen Zutaten zusammengestellt und dann über Jahrhunderte fermentiert wird. Je länger sie fermentiert, desto komplexer wird ihr Geschmack. Man sagt, dass sie fast jedem Gericht eine besondere Note verleihen kann.\n\nGerüchteweise sollen einige tortollanische Händler sie bei sich führen, aber sie ist sehr selten und außerordentlich teuer.\n\n<Xun Xun seufzt sehnsüchtig.>\n\nDas ist die Traumzutat eines jeden Kochs!', 28153),
(151888, 'deDE', 'Ihr verfügt über eine gut ausgestattete Speisekammer. Braucht Ihr noch irgendwelche Gewürze?', 'Ihr verfügt über eine gut ausgestattete Speisekammer. Braucht Ihr noch irgendwelche Gewürze?', 28153),
(151887, 'deDE', '', 'Ein neues Gesicht! Und anscheinend sogar ein freundliches. Wollt Ihr etwas Spezielles probieren? Oder seid Ihr auf der Suche nach seltenen Gewürzen oder Rezepten?', 28153),
(151886, 'deDE', 'Dank Euch ist das Herz von Azeroth jetzt noch stärker. Wir sind der Heilung von Azeroth einen Schritt näher.', '', 28153),
(151885, 'deDE', 'Ich kann Azerit in der Nähe spüren... und auch jene, die danach suchen, um es für ihre Zwecke zu missbrauchen. Ihr müsst sie aufhalten!', '', 28153),
(151884, 'deDE', 'Kommt, kleiner Setzling. Beruhigt Euer Herz und helft mir, diesen Mann zu heilen.', '', 28153),
(151883, 'deDE', '', 'In den Tiefen strömt das Blut.', 28153),
(151882, 'deDE', '', 'In den Tiefen der Flut wartet Eure Wahrheit.', 28153),
(151881, 'deDE', '', 'Lauscht den Klängen der Ertränkten.', 28153),
(151880, 'deDE', '', 'Die Dunkelheit wurzelt. Die Pestilenz wandert. Der Durchgang ist offen.', 28153),
(151879, 'deDE', '', 'Der Abgrund wird Eure Schreie verschlingen!', 28153),
(151878, 'deDE', '', 'Ich lauere in Eurer Lunge!', 28153),
(151877, 'deDE', '', 'Ich erwarte Euch... im Dunkel...', 28153),
(151876, 'deDE', '', 'Ihr gehört mir!', 28153),
(151875, 'deDE', '', 'Eure Verbündeten genossen Euren Tod.', 28153),
(151874, 'deDE', '', 'Wir sind auf ewig eins in der Endlosigkeit der Tiefe.', 28153),
(151873, 'deDE', 'Nicht ein Würdiger unter Euch.', '', 28153),
(151872, 'deDE', 'So zerbrechlich! So unwürdig!', '', 28153),
(151871, 'deDE', 'Ihr wart das schwächste Glied!', '', 28153),
(151870, 'deDE', 'Wie ist das... möglich...', '', 28153),
(151869, 'deDE', 'Ul basha krix.', '', 28153),
(151868, 'deDE', '', 'Bringt den Himmel zum Brennen! Holt sie runter.', 28153),
(151867, 'deDE', 'Niedere Kreaturen müssen dienen... oder sterben!', '', 28153),
(151866, 'deDE', '', 'Für die Horde!', 28153),
(151865, 'deDE', '', 'Lasst keine Gnade walten!', 28153),
(151864, 'deDE', 'Ug\' crish zul Thraxas!', '', 28153),
(151863, 'deDE', '', 'Immer weiter feuern! Unsere Bodentruppen sind auf Euch angewiesen!', 28153),
(151862, 'deDE', '', 'Weiter feuern!', 28153),
(151861, 'deDE', 'Dieses Grab wird auch das Eure werd\'n.', '', 28153),
(151860, 'deDE', 'Ihr könnt Euch den Zandalari nich\' widersetz\'n.', '', 28153),
(151859, 'deDE', 'Der Tempel is\' mit G\'huuns Macht erfüllt.', '', 28153),
(151858, 'deDE', 'Die Zandalari werd\'n herrsch\'n.', '', 28153),
(151857, 'deDE', '', 'Hier entlang! Uns erwartet eine glorreiche Schlacht!', 28153),
(151856, 'deDE', 'G\'huun kann nich\' aufgehalt\'n werden.', '', 28153),
(151855, 'deDE', 'Blutet für den Blutgott!', '', 28153),
(151854, 'deDE', 'Ich schau mich selbst ein bisschen um. Wenn ich was finde, lass ich es Euch sofort wissen.', '', 28153),
(151853, 'deDE', 'Ihr habt ihn gehört! Wir finden besser die Quelle dieser Verderbnis der Alten Götter und schieben ihr einen Riegel vor.', '', 28153),
(151852, 'deDE', 'Ha! Wenn das alles ist, Zul, dann wundert mich der Untergang des Trollimperiums gar nicht.', '', 28153),
(151850, 'deDE', 'Dann hätte ich Euren Kadaver in einen dieser Sarkophage stecken können.', '', 28153),
(151849, 'deDE', 'Ehre und Ruhm! Ich kämpfe für die Sturmwacht!', 'Ehre und Ruhm! Ich kämpfe für die Sturmwacht!', 28153),
(151848, 'deDE', 'Meine Klinge wird Euch unterstützen.', 'Meine Klinge wird Euch unterstützen.', 28153),
(151847, 'deDE', 'Ich bin noch nicht tot!', 'Ich bin noch nicht tot!', 28153),
(151846, 'deDE', 'Zusammen werden wir diese Unholde aufhalten!', 'Zusammen werden wir diese Unholde aufhalten!', 28153),
(151845, 'deDE', 'Solange ich lebe, wird dieses Tal frei bleiben!', 'Solange ich lebe, wird dieses Tal frei bleiben!', 28153),
(151844, 'deDE', 'Wenn die Sturmwacht ruft, muss ich folgen.', 'Wenn die Sturmwacht ruft, muss ich folgen.', 28153),
(151843, 'deDE', 'Leben oder sterben, unsere Zeit ist gekommen.', 'Leben oder sterben, unsere Zeit ist gekommen.', 28153),
(151842, 'deDE', 'Ich stehe Euch zur Seite!', 'Ich stehe Euch zur Seite!', 28153),
(151841, 'deDE', 'Schade, dass Ihr nicht bei der Zerstörung Eures Konstrukts dabei sein könnt, Zul.', '', 28153),
(151840, 'deDE', 'Ha, das werden wir noch sehen, feiger Trollkopp.', '', 28153),
(151839, 'deDE', 'Bald erheb\'n sie sich und G\'huuns Gegner werden alle fall\'n.', '', 28153),
(151838, 'deDE', 'Vielleicht haben wir doch noch eine Chance! Für die Sturmwacht!', 'Vielleicht haben wir doch noch eine Chance! Für die Sturmwacht!', 28153),
(151837, 'deDE', 'Narren! Meine Macht hat die alt\'n Geister bereits an den Will\'n von mei\'m Meister gefesselt.', '', 28153),
(151836, 'deDE', 'Ich höre den Gesang des Sturms. Es gibt noch Hoffnung!', 'Ich höre den Gesang des Sturms. Es gibt noch Hoffnung!', 28153),
(151835, 'deDE', 'Es gibt noch andere. Nicht alle von uns sind verloren!', 'Es gibt noch andere. Nicht alle von uns sind verloren!', 28153),
(151834, 'deDE', 'Ich weiß nicht, welche dunkle Magie sich hier eingenistet hat, aber wir sollten schnell was dagegen tun.', '', 28153),
(151833, 'deDE', 'Das ist nicht unsere Art. Wir können Lord Sturmsang immer noch aufhalten!', 'Das ist nicht unsere Art. Wir können Lord Sturmsang immer noch aufhalten!', 28153),
(151832, 'deDE', 'Meinen Nachforschungen zufolge ist dies die letzte Ruhestätte des ersten Königs von Zandalar.', '', 28153),
(151831, 'deDE', 'Das Tor ist vernichtet. Vorwärts! Erobert Arathi im Namen der Allianz!', '', 28153),
(151830, 'deDE', 'Pike ist noch am Leben? Ich werde ihn sofort aufsuchen.', 'Pike ist noch am Leben? Ich werde ihn sofort aufsuchen.', 28153),
(151829, 'deDE', 'Das Tor ist gefallen. Nun zieht los und entreißt Arathi den Klauen der Horde!', '', 28153),
(151828, 'deDE', 'Jetzt, das Tor ist zerstört! Los, rein da!', '', 28153),
(151827, 'deDE', '', 'Die Tore sind gefallen! Greift an!', 28153),
(151826, 'deDE', 'Das Tor is\' zerstört! Stürmt die Festung!', '', 28153),
(151825, 'deDE', 'Zum Wohle Zandalars... und auch Eures Königreichs... Ihr müsst ihn aufhalt\'n.', '', 28153),
(151824, 'deDE', 'Die Tore sind gefallen! Nehmt die Festung ein!', '', 28153),
(151823, 'deDE', 'Wir müssen sofort den Schrein des Sturms öffnen!', 'Wir müssen sofort den Schrein des Sturms öffnen!', 28153),
(151822, 'deDE', 'Selbst jetzt sammelt sein Meister Macht. Zul wird nicht ruh\'n, bis der Blutgott die Welt in sein\' Klauen hält.', '', 28153),
(151821, 'deDE', 'Es ist geschafft, Arathi ist wieder unser. Für die Allianz!', '', 28153),
(151820, 'deDE', 'Der Sturm erwacht in mir. Ich werde mich den Schatten entgegenstellen!', 'Der Sturm erwacht in mir. Ich werde mich den Schatten entgegenstellen!', 28153),
(151819, 'deDE', '', 'Unser Sieg stand nie in Frage. Für die Horde!', 28153),
(151818, 'deDE', 'Ihr habt mir \'n finsteres Schicksal erspart, aber Zul ist nur \'ne Marionette in \'nem größeren Plan.', '', 28153),
(151817, 'deDE', 'Kriecht zu Eurem Meister und seht, wie er Versag\'n belohnt!', '', 28153),
(151816, 'deDE', 'Ich wusste, dass dieser Tag kommen würde. Ich werde mich den anderen anschließen.', 'Ich wusste, dass dieser Tag kommen würde. Ich werde mich den anderen anschließen.', 28153),
(151815, 'deDE', 'Unmöglich! Niemand widersetzt sich G\'huun.', '', 28153),
(151814, 'deDE', 'Ihr habt Zuls Bann gebroch\'n! Ich diene diesem Aas nich\' länger!', '', 28153),
(151813, 'deDE', 'Beschwert Euch so viel Ihr wollt... Ihr hättet wiss\'n soll\'n, dass niemand G\'huun entkommt.', '', 28153),
(151812, 'deDE', 'Diese Eindringlinge werd\'n sterb\'n... Aber bis dahin will ich mir nich\' Euer G\'schwafel anhör\'n.', '', 28153),
(151811, 'deDE', 'Mein Leb\'n lang hab ich Euerm Meister getrotzt, nur damit Ihr mich im Tod zu seinem Knecht macht.', '', 28153),
(151810, 'deDE', 'Schweigt, Lügenprophet!', '', 28153),
(151809, 'deDE', 'Das ist die Ruhestatt vom ersten König von Zandalar. Dazar war stur... aber jetzt dient auch er.', '', 28153),
(151808, 'deDE', 'Seid Ihr wahnsinnig?', 'Seid Ihr wahnsinnig?', 28153),
(151807, 'deDE', 'Sagt, was Ihr denkt.', 'Sagt, was Ihr denkt.', 28153),
(151806, 'deDE', 'Aber im Tod hab ich ihn\' ein gemeinsames Ziel gegeb\'n: Euern Tod!', '', 28153),
(151805, 'deDE', 'Die Erde nimmt mich auf.', 'Die Erde nimmt mich auf.', 28153),
(151804, 'deDE', 'Die hasst\'n sich zu Lebzeit\'n un\' vernichtet\'n sich am Ende gegenseitig.', '', 28153),
(151803, 'deDE', 'Ihr nähert Euch drei Herrschern, die das Imperium in einer Zeit beherrscht\'n, als kein Troll allein den Thron halt\'n konnte.', '', 28153),
(151802, 'deDE', 'Fremde haben hier keinen Zutritt.', 'Fremde haben hier keinen Zutritt.', 28153),
(151801, 'deDE', 'Wenn sich das Meer zurückzieht, wird die Erde sich erheben!', 'Das Meer zieht sich zurück und die Erde erhebt sich!', 28153),
(151800, 'deDE', 'Bin mir sicher, der wird auch Euch ohne Probleme los.', '', 28153),
(151799, 'deDE', 'Als die Tempel in Toten erstickt\'n, baut\'n sie Golems, um die verseucht\'n Leich\'n loszuwerd\'n.', '', 28153),
(151798, 'deDE', 'Vor tausenden Jahr\'n hätte \'ne Blutseuche die Zandalari fast ausgerottet.', '', 28153),
(151797, 'deDE', 'Bald erheb\'n sie sich und G\'huuns Gegner werden alle fall\'n.', '', 28153),
(151796, 'deDE', 'Meine Macht schlägt bereits Wellen un\' fesselt die alt\'n Geister an den Will\'n von mei\'m Meister.', '', 28153),
(151795, 'deDE', 'Willkomm\' im Grab vom ersten Trollkönig. Wünschte, ich könnt Euch persönlich begrüß\'n.', '', 28153),
(151794, 'deDE', 'Ich sagte Euch doch schon, dass ich bei diesem Wahnsinn nicht mitmache!', 'Ich sagte Euch doch schon, dass ich bei diesem Wahnsinn nicht mitmache!', 28153),
(151793, 'deDE', 'Darauf falle ich nicht noch einmal herein.', 'Darauf falle ich nicht noch einmal herein.', 28153),
(151792, 'deDE', 'Ist es jetzt... sicher?', 'Ist es jetzt... sicher?', 28153),
(151791, 'deDE', 'Wir sind Unternehmer und Umlagerungsspezialisten. Nicht wie diese verdammten Söldner mit den roten Jacken. Wir sind keine Piraten.', '', 28153),
(151790, 'deDE', '', 'Champion, wir müssen zu Katherine zurück.', 28153),
(151789, 'deDE', '', 'Ihr drei, schickt einen Suchtrupp da runter und findet sie!', 28153),
(151788, 'deDE', '', 'Wartet, nein!', 28153),
(151787, 'deDE', '', 'Vorlaute Göre! Das ist noch lange nicht vorbei!', 28153),
(151786, 'deDE', '', 'Es ist vorbei. Ihr sitzt in der Falle.', 28153),
(151785, 'deDE', '', 'Aus dem Weg, Ihr Spatzenhirne!', 28153),
(151784, 'deDE', '', 'Wie schmeckt Euch das?', 28153),
(151783, 'deDE', '', 'Eure kleine Einlage bringt gar nichts. Die Stadt gehört MIR.', 28153),
(151782, 'deDE', 'Ich werde hier warten, falls jemand den Weg zurück nach Hause findet!', '', 28153),
(151781, 'deDE', '', 'Alles wird viel besser, wenn ich der Boss bin.\n\nSobald diese Eisenfluträuber verschwunden sind, können alle zum Kaufen und Verkaufen hierherkommen. Das wird einfach toll!', 28153),
(151780, 'deDE', '', 'Pah! Alles war besser, bevor diese Deppen mit den roten Röcken auftauchten.', 28153),
(151779, 'deDE', 'Also, ich versuche doch auch nur, über die Runden zu kommen.', '', 28153),
(151778, 'deDE', 'Schotriss und seine Bande sind schlecht fürs Geschäft. Wenn es noch schlimmer wird, werde ich einfach meine Vögel nehmen und abhauen.', '', 28153),
(151777, 'deDE', 'Ich wollte doch reich werden...', '', 28153),
(151776, 'deDE', 'Versucht Ihr, uns in die Quere zu kommen? Ich habe schon für Geringeres getötet!', '', 28153),
(151775, 'deDE', '', 'Ihr werdet diesen Hain nicht erobern!', 28153),
(151774, 'deDE', '', 'Ich danke Euch. Ich dachte, ich könnte es allein mit ihnen aufnehmen. Ich kehre jetzt zu Morwin zurück.', 28153),
(151773, 'deDE', 'Ich finden, Ihr habt das schön gestaltet hier.', '', 28153),
(151772, 'deDE', 'Wir Tortollaner treiben hier schon sehr lange Handel. Nach einiger Zeit etablierten sich die Zandalari um uns herum... Aber nun sind schwere Zeiten über sie gekommen. Wir werden diese natürlich überstehen.', '', 28153),
(151771, 'deDE', 'Ich arbeite hier. Kein Grund, auf gefährliche Straße zu gehen.', '', 28153),
(151770, 'deDE', 'Lok-tar ogar!', 'Lok-tar ogar!', 28153),
(151769, 'deDE', 'Lok-narash!', 'Lok-narash!', 28153),
(151768, 'deDE', 'Gakarah ma!', 'Gakarah ma!', 28153),
(151767, 'deDE', 'Die Horde wird Euch vernichten.', 'Die Horde wird Euch vernichten.', 28153),
(151766, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(151765, 'deDE', 'Tod unseren Feinden!', 'Tod unseren Feinden!', 28153),
(151764, 'deDE', 'Heute werdet Ihr sterben.', 'Heute werdet Ihr sterben.', 28153),
(151763, 'deDE', 'Ein... ehrenhafter... Tod...', 'Ein... ehrenhafter... Tod...', 28153),
(151762, 'deDE', 'Hah! Da meldet sich jemand zum Dienst. Schmeißt das in die Truhe und dann zurück an die Arbeit!', '', 28153),
(151761, 'deDE', 'Ihr Ahnen... ich komme...', 'Ihr Ahnen... ich komme...', 28153),
(151760, 'deDE', 'Diesen Krieg... werdet Ihr verlieren...', 'Diesen Krieg... werdet Ihr verlieren...', 28153),
(151759, 'deDE', 'Euer Ende... wird kommen...', 'Euer Ende... wird kommen...', 28153),
(151758, 'deDE', 'Ich sterbe... als Krieger...', 'Ich sterbe... als Kriegerin...', 28153),
(151757, 'deDE', 'Mein Kampf... findet ein Ende...', 'Mein Kampf... findet ein Ende...', 28153),
(151756, 'deDE', 'Mein Geist... kehrt nach Draenor zurück...', 'Mein Geist... kehrt nach Draenor zurück...', 28153),
(151755, 'deDE', 'Sterbt ehrenhaft.', 'Sterbt ehrenhaft.', 28153),
(151754, 'deDE', 'Ich habe Euch nichts mehr zu sagen.', 'Ich habe Euch nichts mehr zu sagen.', 28153),
(151753, 'deDE', 'Geht jetzt!', 'Geht jetzt!', 28153),
(151752, 'deDE', 'Geht mit Ehre!', 'Geht mit Ehre!', 28153),
(151751, 'deDE', 'Möge Eure Klinge niemals stumpf sein.', 'Möge Eure Klinge niemals stumpf sein.', 28153),
(151750, 'deDE', 'Geht! Sichert Euch den Sieg!', 'Geht! Sichert Euch den Sieg!', 28153),
(151749, 'deDE', 'So machen wir das.', 'So machen wir das.', 28153),
(151748, 'deDE', 'Sprecht.', 'Sprecht.', 28153),
(151747, 'deDE', 'Ich grüße Euch.', 'Ich grüße Euch.', 28153),
(151746, 'deDE', 'Lok-tar!', 'Lok-tar!', 28153),
(151745, 'deDE', 'Throm-ka!', 'Throm-ka!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'deDE', 'Was wollt Ihr?', 'Was wollt Ihr?', 28153),
(151743, 'deDE', 'Zug-zug.', 'Zug-zug.', 28153),
(151742, 'deDE', 'Kraft und Ehre.', 'Kraft und Ehre.', 28153),
(151741, 'deDE', 'Kauft beim nächsten Mal etwas mehr!', 'Kauft beim nächsten Mal etwas mehr!', 28153),
(151740, 'deDE', 'Mögen diese Waren Euch gute Dienste leisten.', 'Mögen diese Waren Euch gute Dienste leisten.', 28153),
(151739, 'deDE', 'Es gibt kein Geld zurück.', 'Es gibt kein Geld zurück.', 28153),
(151738, 'deDE', 'Was sucht ihr?', 'Was sucht ihr?', 28153),
(151737, 'deDE', 'Was darf\'s denn sein?', 'Was darf\'s denn sein?', 28153),
(151736, 'deDE', 'Seht Euch nur um!', 'Seht Euch nur um!', 28153),
(151735, 'deDE', 'Seid Ihr in Azeroth alle so anstrengend?', 'Seid Ihr in Azeroth alle so anstrengend?', 28153),
(151734, 'deDE', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 'Am allerliebsten haue ich nervtötende Sachen zu Brei. Seid Ihr sicher, dass Ihr mich weiter anstupsen wollt?', 28153),
(151733, 'deDE', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 'Vorsicht, Ihr macht mich wütend. Ihr würdet mich nicht mögen, wenn ich wütend bin.', 28153),
(151732, 'deDE', 'ORC... DRAUFHAUEN!', 'ORC... DRAUFHAUEN!', 28153),
(151731, 'deDE', 'Komm... komm, mein lieber Reban. Jetzt gibt\'s Fresschen!', '', 28153),
(151730, 'deDE', '<Applause sounds>', '', 28153),
(151729, 'deDE', '<Yawning sound>', '', 28153),
(151728, 'deDE', '<Short cheer--Wooooo!>', '', 28153),
(151727, 'deDE', '<Slightly longer cheer--Woohoo!>', '', 28153),
(151726, 'deDE', '<Chicken sounds>', '', 28153),
(151725, 'deDE', '<Crying sounds>', '', 28153),
(151724, 'deDE', '<Crying sounds, variant>', '', 28153),
(151723, 'deDE', '<Crying sounds, variant.>', '', 28153),
(151722, 'deDE', '<Kiss sound>', '', 28153),
(151721, 'deDE', '<Laughing sounds>', '', 28153),
(151720, 'deDE', '<Laughing>', '', 28153),
(151719, 'deDE', '<Making a raspberry sound--Pfffthblth!>', '', 28153),
(151718, 'deDE', '<Roar of dominance>', '', 28153),
(151717, 'deDE', '<Variant roar>', '', 28153),
(151716, 'deDE', '<Sighing sound>', '', 28153),
(151715, 'deDE', '<Train noises--chugga chugga choo choo!>', '', 28153),
(151714, 'deDE', 'Das... tut mir echt leid.', '', 28153),
(151713, 'deDE', 'Erbärmlich. Die Mag\'har werden Euch in die Knie zwingen.', '', 28153),
(151712, 'deDE', 'Ich schulde Euch was.', '', 28153),
(151711, 'deDE', 'Ich danke Euch.', '', 28153),
(151710, 'deDE', 'Ich stehe in Eurer Schuld.', '', 28153),
(151709, 'deDE', 'Ihr werdet vor mir im Staub liegen.', '', 28153),
(151708, 'deDE', 'Bei den Monden Draenors!', '', 28153),
(151707, 'deDE', 'Ich habe nur meine Pflicht getan.', '', 28153),
(151706, 'deDE', 'Verlangt das nie wieder von mir.', '', 28153),
(151705, 'deDE', 'War mir ein Vergnügen.', '', 28153),
(151704, 'deDE', 'Sprecht.', '', 28153),
(151703, 'deDE', 'Ich grüße Euch.', '', 28153),
(151702, 'deDE', 'Lok-tar!', '', 28153),
(151701, 'deDE', 'Throm-ka!', '', 28153),
(151700, 'deDE', 'Nein.', '', 28153),
(151699, 'deDE', 'Nichts da!', '', 28153),
(151698, 'deDE', 'Niemals!', '', 28153),
(151697, 'deDE', 'So ist es.', '', 28153),
(151696, 'deDE', 'Natürlich.', '', 28153),
(151695, 'deDE', 'In der Tat.', '', 28153),
(151694, 'deDE', 'Peon rufen', 'Peon rufen', 28153),
(151693, 'deDE', 'Ich habe Schande über meinen Klan gebracht.', '', 28153),
(151692, 'deDE', 'Lasst mich mein Mana wiederauffüllen.', '', 28153),
(151691, 'deDE', 'Kein Mana!', '', 28153),
(151690, 'deDE', 'Ich mag meinen Metal wie meinen Fels: schwarz! <Gitarre>', '', 28153),
(151689, 'deDE', 'Immer schön frostig bleiben, meine Wölfe.', '', 28153),
(151688, 'deDE', 'Ah! Der Chiropraktiker in Orgrimmar hat bei meinem Rücken Wunder gewirkt.', '', 28153),
(151687, 'deDE', 'Warum verbringt IHR nicht mal ein paar Jahrzehnte auf einem Planeten mit fanatischen Draenei? Dann könnt Ihr ja sehen, wie EUCH das schmeckt.', '', 28153),
(151686, 'deDE', 'Die Orcs des Lachenden Schädels haben mich im Comedyclub mit Buhrufen von der Bühne gejagt. Bei so einem Namen sollte man doch besseren Humor erwarten können, oder?', '', 28153),
(151685, 'deDE', 'Meine Güte, Azeroth hat ja einen höheren Verschleiß an Kriegshäuptlingen als Draenor an alternativen Zeitlinien.', '', 28153),
(151684, 'deDE', 'Ich hab Gul\'dan selbst nie getroffen, aber ich höre, auf Partys war er ein echter Alptraum. Hat immer versucht, irgendwas in die Bowle zu schütten...', '', 28153),
(151683, 'deDE', 'Der Ritualkreis von Xal\'vor erwacht zum Leben!', 'Der Ritualkreis von Xal\'vor erwacht zum Leben!', 28153),
(151682, 'deDE', 'Bitte, ich flehe Euch an.', '', 28153),
(151681, 'deDE', 'Habt Mitleid mit einem armen Orc!', '', 28153),
(151680, 'deDE', 'Denkt auch mal an Euren Peon.', '', 28153),
(151679, 'deDE', 'Habt Ihr gut gemacht.', '', 28153),
(151678, 'deDE', 'Beeindruckend, doch.', '', 28153),
(151677, 'deDE', '<hmpf> Ich muss Euch gratulieren.', '', 28153),
(151676, 'deDE', 'Ihr müsst ein Frostwolf sein, so wie Ihr mein Herz aufgespürt habt.', '', 28153),
(151675, 'deDE', 'Knochen, Stahl und Schädel bricht, aber eines Mag\'hars Liebe nicht.', '', 28153),
(151674, 'deDE', 'Wenn es zu viel wird, sage ich \"Zug-zug\".', '', 28153),
(151673, 'deDE', 'Ihr seht nicht nur GUT aus, Ihr seht mok\'gor-oßartig aus!', '', 28153),
(151672, 'deDE', 'Möchtet Ihr mal sehen, wie hart mein Schwarzfels ist?', '', 28153),
(151671, 'deDE', 'Wie wär\'s mit einem Spaziergang im Schattenmondlicht?', '', 28153),
(151670, 'deDE', 'Ist Eure Mutter ein Feuerelementar? Ihr seid nämlich brandheiß.', '', 28153),
(151669, 'deDE', 'Sterbt ehrenhaft.', '', 28153),
(151668, 'deDE', 'Ich habe Euch nichts mehr zu sagen.', '', 28153),
(151667, 'deDE', 'Ihr könnt jetzt gehen.', '', 28153),
(151666, 'deDE', 'Geht mit Ehre.', '', 28153),
(151665, 'deDE', '<Breathe as if you are running: Total 3>', '', 28153),
(151664, 'deDE', '<Jumping off ground: Total 3>', '', 28153),
(151663, 'deDE', '<Landing from jump: Total 3>', '', 28153),
(151662, 'deDE', '<Vocalized cheer: Total 3>', '', 28153),
(151661, 'deDE', '<Deep breath before focusing magic: Total 3>', '', 28153),
(151660, 'deDE', '<Release after expending magic: Total 3>', '', 28153),
(151659, 'deDE', '<Distressed cry: Total 3>', '', 28153),
(151658, 'deDE', '<Convey summoning power. Energy buildup: Total 5-7>', '', 28153),
(151657, 'deDE', '<Release spell, throwing energy: Total 3-5>', '', 28153),
(151656, 'deDE', '<Standard attack: Total 10>', '', 28153),
(151655, 'deDE', '<Big attack: Total 5>', '', 28153),
(151654, 'deDE', '<Falling from high terrain. Impending injury or death: Total 1>', '', 28153),
(151653, 'deDE', '<Player takes a wound: Total 10>', '', 28153),
(151652, 'deDE', '<Player takes significant wound: Total 5>', '', 28153),
(151651, 'deDE', '<Long attack with wind up. Jump attacks: Total 5-7>', '', 28153),
(151650, 'deDE', '<Convey releasing power or charging enemy: Total 4-6>', '', 28153),
(151649, 'deDE', '<Charging to attack enemy: Total 5-7>', '', 28153),
(151648, 'deDE', '<Dying sounds: Total 5>', '', 28153),
(151647, 'deDE', 'Dieser Held kann sich der Gruppe nicht anschließen.', '', 28153),
(151646, 'deDE', 'Ich habe keine Munition mehr.', '', 28153),
(151645, 'deDE', 'Nicht genug Energie.', '', 28153),
(151644, 'deDE', 'Ich brauche mehr Energie.', '', 28153),
(151643, 'deDE', 'Ich brauche erst Mana.', '', 28153),
(151642, 'deDE', 'Mein Mana ist fast alle.', '', 28153),
(151641, 'deDE', 'Nicht genug Mana.', '', 28153),
(151640, 'deDE', 'Nicht genug Wut.', '', 28153),
(151639, 'deDE', 'Ich brauche mehr Wut.', '', 28153),
(151638, 'deDE', 'Das ist zu weit weg.', '', 28153),
(151637, 'deDE', 'Ich bin zu weit weg.', '', 28153),
(151636, 'deDE', 'Ich muss näher ran.', '', 28153),
(151635, 'deDE', 'Wir können niemanden mehr einladen.', '', 28153),
(151634, 'deDE', 'Ich kann jetzt nicht mehr trinken.', '', 28153),
(151633, 'deDE', 'Diese Fähigkeit habe ich noch nicht gelernt.', '', 28153),
(151632, 'deDE', 'Das kann ich noch nicht.', '', 28153),
(151631, 'deDE', 'Dieser Zauber ist noch nicht bereit.', '', 28153),
(151630, 'deDE', 'Das kann ich noch nicht wirken.', '', 28153),
(151629, 'deDE', 'Anker lichten.', 'Anker lichten.', 28153),
(151628, 'deDE', 'Das lädt noch auf.', '', 28153),
(151627, 'deDE', 'Haltet Euer Pulver trocken.', 'Haltet Euer Pulver trocken.', 28153),
(151626, 'deDE', 'Allzeit loyal.', 'Allzeit loyal.', 28153),
(151625, 'deDE', 'Allzeit volle Segel.', 'Allzeit volle Segel.', 28153),
(151624, 'deDE', 'Die Flut wartet nicht auf Buckelige.', 'Die Flut wartet nicht auf Buckelige.', 28153),
(151623, 'deDE', 'Da zieht was auf. Ich hab\'s im Urin.', 'Da zieht was auf. Ich hab\'s im Urin.', 28153),
(151622, 'deDE', 'Der Zirkel wird fallen.', 'Der Zirkel wird fallen.', 28153),
(151621, 'deDE', 'Nur tote Hexen sind gute Hexen.', 'Nur tote Hexen sind gute Hexen.', 28153),
(151620, 'deDE', 'Ruhm dem Haus Kronsteig.', 'Ruhm dem Haus Kronsteig.', 28153),
(151619, 'deDE', 'Immer eine Handbreit Wasser unterm Kiel.', 'Immer eine Handbreit Wasser unterm Kiel.', 28153),
(151618, 'deDE', 'Augen immer am Horizont.', 'Augen immer am Horizont.', 28153),
(151617, 'deDE', 'Mast- und Schotbruch!', 'Mast- und Schotbruch!', 28153),
(151616, 'deDE', 'Für Kul Tiras!', 'Für Kul Tiras!', 28153),
(151615, 'deDE', 'Das kann ich jetzt nicht plündern.', '', 28153),
(151614, 'deDE', 'Ich habe kein Ziel.', '', 28153),
(151613, 'deDE', 'Ich muss zuerst was anvisieren.', '', 28153),
(151612, 'deDE', 'Ich brauche ein Ziel.', '', 28153),
(151611, 'deDE', 'Das kann ich nicht.', '', 28153),
(151610, 'deDE', 'Dazu fehlt mir die Erlaubnis.', '', 28153),
(151609, 'deDE', 'Dieses Ziel kann ich nicht angreifen.', '', 28153),
(151608, 'deDE', 'Das kann ich nicht angreifen.', '', 28153),
(151607, 'deDE', 'Mein Inventar ist voll.', '', 28153),
(151606, 'deDE', 'Ich kann nicht noch mehr tragen.', '', 28153),
(151605, 'deDE', 'Das ist verschlossen.', '', 28153),
(151604, 'deDE', 'Mehr kann ich davon nicht tragen.', '', 28153),
(151603, 'deDE', 'Stromgarde ist noch schwach. Es wird einem direkten Angriff der Verwüster nicht standhalten. Vernichtet sie, bevor sie zu nahe kommen!', '', 28153),
(151602, 'deDE', 'Diesen Gegenstand kann ich noch nicht benutzen.', '', 28153),
(151601, 'deDE', 'Das ist noch nicht bereit.', '', 28153),
(151600, 'deDE', 'Dieser Gegenstand lädt noch auf.', '', 28153),
(151599, 'deDE', 'Unsere Befestigungen sind noch immer relativ schwach. Schnell, zerstört diese Verwüster, bevor sie zu nahe kommen!', '', 28153),
(151598, 'deDE', 'Nicht genug Jähzorn.', '', 28153),
(151597, 'deDE', 'Mein Jähzorn reicht nicht.', '', 28153),
(151596, 'deDE', 'Nicht genug Schmerz.', '', 28153),
(151595, 'deDE', 'Mein Schmerz reicht nicht.', '', 28153),
(151594, 'deDE', 'Das ist keine Tasche.', '', 28153),
(151593, 'deDE', 'Wir müssen diese Verwüster aufhalten, bevor sie UNS verwüsten!', '', 28153),
(151592, 'deDE', 'Meine Mittel reichen nicht.', '', 28153),
(151591, 'deDE', 'Das kann ich mir nicht leisten.', '', 28153),
(151590, 'deDE', '', 'Setzt die Verwüster ein, sofort! Lasst nicht zu, dass die Allianz sich hier einnistet.', 28153),
(151589, 'deDE', 'Das ist zu teuer.', '', 28153),
(151588, 'deDE', 'Wollt Ihr \'nen Krakenbauch von innen sehen? Nein? Dann geht mir aus\'m Wind.', 'Wollt Ihr \'nen Krakenbauch von innen sehen? Nein? Dann geht mir aus\'m Wind.', 28153),
(151587, 'deDE', 'Macht ma\' die Verwüster bereit! Wir müss\'n den Allianzabschaum vernicht\'n, bevor er uns vernichtet!', '', 28153),
(151586, 'deDE', 'Ihr habt wohl nicht alle Segel am Mast, was?', 'Ihr habt wohl nicht alle Segel am Mast, was?', 28153),
(151585, 'deDE', 'Schickt die Verwüster rein! Die Mauern von Stromgarde werden unter dem Ansturm der Horde einstürzen!', '', 28153),
(151584, 'deDE', 'He! Mal wieder Bilgewasser gesoffen, was?', 'He! Mal wieder Bilgewasser gesoffen, was?', 28153),
(151583, 'deDE', 'Belagerungsmaschinen! Fegt sie von der Karte!', '', 28153),
(151582, 'deDE', 'Ihr erbärmlichen Maden habt kein Recht, hier zu sein.', '', 28153),
(151581, 'deDE', '', 'Sie fahren Belagerungsmaschinen auf! Wir müssen sie zerstören, bevor sie unserer Basis zu nahe kommen.', 28153),
(151580, 'deDE', 'Ich brauche beide Hände für meine Waffe.', '', 28153),
(151579, 'deDE', 'Diese Fähigkeit ist noch nicht bereit.', '', 28153),
(151578, 'deDE', 'Das kann ich noch nicht tun.', '', 28153),
(151577, 'deDE', 'Noch nicht bereit.', '', 28153),
(151576, 'deDE', 'Das kann ich da nicht ablegen.', '', 28153),
(151575, 'deDE', 'Diese Tasche ist voll.', '', 28153),
(151574, 'deDE', 'Das kann ich hier nicht tun.', '', 28153),
(151573, 'deDE', 'Das kann ich nicht wegwerfen.', '', 28153),
(151572, 'deDE', 'Das ist an mich gebunden.', '', 28153),
(151571, 'deDE', 'Das kann ich nicht anlegen.', '', 28153),
(151570, 'deDE', 'Meine Stufe ist nicht hoch genug, um das zu benutzen.', '', 28153),
(151569, 'deDE', 'Das kann ich noch nicht benutzen.', '', 28153),
(151568, 'deDE', 'Meine Fertigkeitsstufe ist nicht hoch genug, um das anzulegen.', '', 28153),
(151567, 'deDE', 'So etwas kann ich niemals anlegen.', '', 28153),
(151566, 'deDE', 'Das Wichtigste zuerst: Wir benötigen Holz vom Hochlandsägewerk und dazu Eisen. Das können wir von Galsons Mine requirieren.', '', 28153),
(151565, 'deDE', 'Diesen Zauber kann ich nicht erlernen.', '', 28153),
(151564, 'deDE', 'Da liegt Ihr falsch, Lady Liadrin. Schon bald werden erneut Flaggen der Allianz über Arathi wehen.', '', 28153),
(151563, 'deDE', '', 'Gebt auf, Danath. Die Gebietsansprüche des Hauses Trollbann sind seit Jahren erloschen.', 28153),
(151562, 'deDE', 'Das kann ich nicht plündern.', '', 28153),
(151561, 'deDE', 'Das gehört nicht mir.', '', 28153),
(151560, 'deDE', 'Ich muss näher ran.', '', 28153),
(151559, 'deDE', 'Leider kann ich nicht dasselbe sagen, Schattenjäger.', '', 28153),
(151558, 'deDE', 'Das ist zu weit weg.', '', 28153),
(151557, 'deDE', 'Da komme ich nicht ran.', '', 28153),
(151556, 'deDE', 'Danath Trollbann. Freut mich, Euch endlich kennenzulern\'...', '', 28153),
(151555, 'deDE', 'Das kann ich nicht handeln.', '', 28153),
(151554, 'deDE', 'Das kann ich nicht benutzen.', '', 28153),
(151553, 'deDE', 'Das ist nicht angelegt.', '', 28153),
(151552, 'deDE', 'Nein, es gehört mir. Ihr und die Horde werdet für Eure Unverschämtheit bezahlen, Etrigg.', '', 28153),
(151551, 'deDE', 'Das muss ich erst anlegen.', '', 28153),
(151550, 'deDE', 'Trollbann! Ihr macht Euch besser aus dem Staub. Das Arathihochland gehört jetzt der Horde.', '', 28153),
(151549, 'deDE', 'Aber zunächst müssen wir diese Stellung befestigen. Bringt uns Holz und Eisen.', '', 28153),
(151548, 'deDE', 'Zerquetscht diesen Feind!', '', 28153),
(151547, 'deDE', 'In der Tat, Lady Liadrin. Es wird mir ein Vergnügen sein, einen fehlgeleiteten Paladin der Horde seiner Strafe zuzuführen.', '', 28153),
(151546, 'deDE', 'Auf mein Ziel!', '', 28153),
(151545, 'deDE', 'Zwingt meinen Gegner in die Knie!', '', 28153),
(151544, 'deDE', 'Kommt, hier entlang.', '', 28153),
(151543, 'deDE', 'Lasst einen Orc vorangehen.', '', 28153),
(151542, 'deDE', '', 'Turalyon? Das dürfte interessant werden...', 28153),
(151541, 'deDE', 'Folgt mir.', '', 28153),
(151540, 'deDE', 'Für die Horde!', '', 28153),
(151539, 'deDE', 'Ich wurde verwundet!', '', 28153),
(151538, 'deDE', 'Helft mir, Heiler!', '', 28153),
(151537, 'deDE', 'Steht nicht einfach nur rum! Helft mir!', '', 28153),
(151536, 'deDE', 'Helft mir sofort!', '', 28153),
(151535, 'deDE', 'Wartet hier!', '', 28153),
(151534, 'deDE', 'Rührt Euch nicht von der Stelle.', '', 28153),
(151533, 'deDE', 'Das Licht ist mit uns, Rokhan. Wir fürchten die Schatten nicht.', '', 28153),
(151532, 'deDE', 'Passt auf die Schatt\'n auf, Turalyon. Ich und die Horde komm\' Euch hol\'n...', '', 28153),
(151531, 'deDE', 'Sterbt ehrenvoll!', '', 28153),
(151530, 'deDE', 'Zum Angriff!', '', 28153),
(151529, 'deDE', 'Mok-thora ka!', '', 28153),
(151528, 'deDE', 'Zerquetscht unsere Feinde!', '', 28153),
(151527, 'deDE', 'Es ist Zeit, die Hügel von Arathi von Euch und Eurer Hordearmee zu säubern, Etrigg.', '', 28153),
(151526, 'deDE', 'Durchbrecht ihre Reihen!', '', 28153),
(151525, 'deDE', 'Flieht oder sterbt!', '', 28153),
(151524, 'deDE', 'Wir kämpfen an einem anderen Tag weiter.', '', 28153),
(151523, 'deDE', 'Weg! Weg!', '', 28153),
(151522, 'deDE', 'Rieche ich Allianzabschaum auf meinem Schlachtfeld? Dann ist es wohl Zeit für einen Kampf.', '', 28153),
(151521, 'deDE', 'Macht Euch bereit!', '', 28153),
(151520, 'deDE', 'Kommt von Zeit zu Zeit vorbei. Ich hasse es, wenn das Eisen in der Truhe vergeudet wird.', '', 28153),
(151519, 'deDE', 'Verbrennt sie alle!', '', 28153),
(151518, 'deDE', 'Feuer frei!', '', 28153),
(151517, 'deDE', 'Sie werden bald hier aufkreuzen. Wir müssen die Basis aufbauen, und dazu brauchen wir Holz und Eisen.', '', 28153),
(151516, 'deDE', 'Ich werd Euch Hordlern gehörig den Hintern versohlen, macht Euch auf was gefasst! Hah!', '', 28153),
(151515, 'deDE', '', 'Zieht Euch zurück, Muradin. Die Horde hält dieses Gebiet.', 28153),
(151514, 'deDE', 'Nein, ich suche ein paar Hordler, um meine neue Klinge auszuprobieren!', '', 28153),
(151513, 'deDE', 'Was macht Ihr hier, Muradin? Sucht Ihr \'nen Kampf?', '', 28153),
(151512, 'deDE', 'Geht Ihr doch zurück in Eure karge Einöde, verlauster Orc!', '', 28153),
(151511, 'deDE', 'Muradin! Diesmal haben sich Eure Zwerge übernommen. Kriecht zurück in Euren Berg.', '', 28153),
(151510, 'deDE', '', 'Die Allianz steht bald auf unserer Türschwelle. Wir müssen uns beeilen. Sammelt Holz und Eisen, damit wir unsere Stellung ausbauen können.', 28153),
(151509, 'deDE', '', 'Macht Euch keine Illusionen, alter Mann. Wir sind hier, um Stromgarde zurückzuerobern.', 28153),
(151508, 'deDE', 'Lady Liadrin! Willkommen in Arathi. Seid Ihr hier, um Euch zu ergeben?', '', 28153),
(151507, 'deDE', '', 'Ihr wart zu lange weg, Turalyon. Die Welt hat Euch vergessen.', 28153),
(151506, 'deDE', 'Was ist das? Hordeinvasoren, angeführt von einem Paladin? Was ist nur aus dieser Welt geworden!', '', 28153),
(151505, 'deDE', '', 'Versucht es nur, Muradin. Das ist jetzt Hoheitsgebiet der Horde.', 28153),
(151504, 'deDE', 'Lasst das mal schön bleiben, wenn Ihr nicht wollt, dass wir Euch mit Mörsern einheizen.', '', 28153),
(151503, 'deDE', 'Danath Trollbann... mit Euch hab ich noch \'n Hühnchen zu rupf\'n! Wir seh\'n uns auf\'m Schlachtfeld...', '', 28153),
(151502, 'deDE', 'Ihr wagt es, Arathi anzugreifen? Mit einem TROLL als Anführer? Ihr habt einen großen Fehler begangen.', '', 28153),
(151501, 'deDE', 'Grünhaut? Ohoho... jetzt habt Ihr mich wütend gemacht.', '', 28153),
(151500, 'deDE', 'Zurückgewinnen', 'Zurückgewinnen', 28153),
(151499, 'deDE', '<Klaus lacht schnaubend.>\n\nJa, das kann schon sein. Meine Verwandtschaft ist ganz schön weit verteilt.', '', 28153),
(151498, 'deDE', 'Ihr greift Stromgarde an, die rechtmäßige Heimat des Hauses Trollbann? Verschwindet, Grünhaut.', '', 28153),
(151497, 'deDE', 'Heute erobern wir unser rechtmäßiges Territorium. Für die Allianz!', '', 28153),
(151496, 'deDE', 'Zu lange wurde Stromgarde von fremden Eroberern entwürdigt.', '', 28153),
(151495, 'deDE', 'Für die Allianz!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'deDE', 'Soldaten der Allianz! Heute erobern wir die stolze Stadt Stromgarde von der bestialischen Horde zurück.', '', 28153),
(151493, 'deDE', 'Heute erobern wir die Hügel von Arathi zurück... für die Allianz!', '', 28153),
(151492, 'deDE', 'Ladet die Gewehre und zieht die Schwerter.', '', 28153),
(151491, 'deDE', '', 'Arathi wird uns gehören! Für die Horde!', 28153),
(151490, 'deDE', '', 'Konzentriert Euch auf die Aufgabe vor uns. Zuerst nehmen wir Ar\'gorok ein, dann marschieren wir auf Stromgarde!', 28153),
(151489, 'deDE', 'Schönwind? Ich hab schon mal jemanden mit diesem Namen getroffen.', 'Schönwind? Ich hab schon mal jemanden mit diesem Namen getroffen.', 28153),
(151488, 'deDE', 'Packt zusammen, Jungs! Wir bringen die Waffen weg von hier!', '', 28153),
(151487, 'deDE', 'Die Burg von Stromgarde wurde zu einem Schloss ausgebaut.', '', 28153),
(151486, 'deDE', 'Der Bau des Arsenals ist abgeschlossen.', '', 28153),
(151485, 'deDE', 'Die Werkstatt ist jetzt bereit.', '', 28153),
(151484, 'deDE', 'Unser Rathaus wurde zu einer Burg ausgebaut.', '', 28153),
(151483, 'deDE', 'Der Altar der Könige ist fertig.', '', 28153),
(151482, 'deDE', 'Unsere Burg wurde zu einem Schloss umgebaut!', '', 28153),
(151481, 'deDE', 'Arsenal errichtet.', '', 28153),
(151480, 'deDE', 'Die Werkstatt ist bereit für den Bau von Panzern.', '', 28153),
(151479, 'deDE', 'Unser Rathaus wurde zu einer Burg erweitert.', '', 28153),
(151478, 'deDE', 'Der Altar der Könige ist fertig.', '', 28153),
(151477, 'deDE', 'Großartig! Unsere Burg ist jetzt ein Schloss!', '', 28153),
(151476, 'deDE', 'Wir können jetzt im Arsenal unsere Truppen ausrüsten!', '', 28153),
(151475, 'deDE', 'Die Werkstatt ist funktionstüchtig. Zeit, ein paar Panzer zu bauen!', '', 28153),
(151474, 'deDE', 'Das Rathaus wurde zu einer Burg ausgebaut!', '', 28153),
(151473, 'deDE', 'Der Altar der Könige ist bereit!', '', 28153),
(151472, 'deDE', '', 'Unsere Hochburg wurde zu einer Festung ausgebaut. Für die Horde!', 28153),
(151471, 'deDE', '', 'Dieses neue Arsenal erlaubt es uns, unsere Truppen besser zu bewaffnen.', 28153),
(151470, 'deDE', '', 'Die Werkstatt ist fertig.', 28153),
(151469, 'deDE', '', 'Wir haben unsere Basis verstärkt. Das Haupthaus wurde in eine Hochburg umgewandelt.', 28153),
(151468, 'deDE', '', 'Der Altar der Stürme ist jetzt bereit.', 28153),
(151467, 'deDE', 'Unsere Kaserne ist zur Truppenausbildung bereit.', '', 28153),
(151466, 'deDE', 'Die Kaserne wurde fertiggestellt. Wir können mit der Ausbildung von Truppen beginnen.', '', 28153),
(151465, 'deDE', 'Wir haben eine Kaserne! Fangt an, Truppen auszubilden!', '', 28153),
(151464, 'deDE', '', 'In der Kaserne können jetzt Truppen ausgebildet werden.', 28153),
(151463, 'deDE', 'Unsre Hochburg is\' jetzt \'ne Festung!', '', 28153),
(151462, 'deDE', 'Wir ham das Haupthaus zu \'ner Hochburg ausgebaut.', '', 28153),
(151461, 'deDE', 'Der Altar der Stürme is\' bereit.', '', 28153),
(151460, 'deDE', 'Die Kaserne is\' einsatzbereit. Diesen Krieg könn\' wir nur mit der Unterstützung von unsren Grunzern gewinn\'.', '', 28153),
(151459, 'deDE', 'Unsere Hochburg ist jetzt eine Festung!', '', 28153),
(151458, 'deDE', 'Unser Haupthaus ist jetzt eine Hochburg!', '', 28153),
(151457, 'deDE', 'Der Altar der Stürme wurde fertiggestellt.', '', 28153),
(151456, 'deDE', 'Wir haben eine Kaserne, dann bildet mal Grunzer aus!', '', 28153),
(151455, 'deDE', '', 'Ihr habt keine Chance. Blutritter, metzelt sie nieder!', 28153),
(151454, 'deDE', 'Und mich nenn\' sie nich\' umsonst Schattenjäger. Jetzt, Assassinen! Zeigt Euch!', '', 28153),
(151453, 'deDE', 'Eure Allianzgerechtigkeit kenne ich zur Genüge. Windreiter, lasst sie den Zorn der Horde spüren!', '', 28153),
(151452, 'deDE', '', 'Niemals!', 28153),
(151451, 'deDE', 'Dieses Land gehört nich\' Euch, Trollbann. Die Trolle war\'n lang vor Euch hier.', '', 28153),
(151450, 'deDE', 'Hah! Das denkt nur Ihr.', '', 28153),
(151449, 'deDE', '', 'Ich habe genug von Eurem Geprahle. Blutritter, schlagt zu mit dem Zorn des Lichts!', 28153),
(151448, 'deDE', 'Das Licht kann Euch nich\' mehr rett\'n. Schattenjäger, zeigt Euch!', '', 28153),
(151447, 'deDE', 'Windreiter, zum Angriff!', '', 28153),
(151446, 'deDE', '', 'Das wird sich noch zeigen, Turalyon. Erst müsst Ihr an mir vorbei.', 28153),
(151445, 'deDE', 'Ich warte schon.', '', 28153),
(151444, 'deDE', 'Nicht, wenn ich ein Wort mitzureden habe, Turalyon.', '', 28153),
(151443, 'deDE', '', 'All das wird Euch nichts nützen, Zwerg. Zu den Waffen, Blutritter.', 28153),
(151442, 'deDE', 'Ihr seid mir genau in die Falle getappt, Muradin. Schattenjäger, zeigt Euch!', '', 28153),
(151441, 'deDE', 'Jetzt, Windreiter! Zum Angriff!', '', 28153),
(151440, 'deDE', '', 'Niemals.', 28153),
(151439, 'deDE', 'Seht Euch vor, Muradin!', '', 28153),
(151438, 'deDE', 'Aber nicht mehr lange, Zwerg. Für die Horde!', '', 28153),
(151437, 'deDE', 'Ich werde diese Stadt nicht noch einmal verlieren, erst recht nicht an Euresgleichen. Verteidiger, zeigt ihnen die Macht von Stromgarde!', '', 28153),
(151436, 'deDE', 'Ich jetzt in Sicherheit. Zurück an die Arbeit.', '', 28153),
(151435, 'deDE', 'Die Licht ist an meiner Seite. Verteidiger, vorwärts!', '', 28153),
(151434, 'deDE', 'Ich werde Stromgarde bis zu meinem letzten Atemzug halten, Liadrin. Gebt nicht nach, Verteidiger!', '', 28153),
(151433, 'deDE', 'Freut Euch nicht zu früh, Blutelfe. Erst müsst Ihr an mir vorbei.', '', 28153),
(151432, 'deDE', 'Ja... Ich kann es kaum erwarten.', '', 28153),
(151431, 'deDE', 'Pah! Von dem hohen Ross holen wir Euch schon runter!', '', 28153),
(151430, 'deDE', 'Dieser alte Narr hat immer noch ein paar Tricks auf Lager. Verteidiger, zeigt ihnen die Stärke Stromgardes!', '', 28153),
(151429, 'deDE', 'Das Licht wird immer über die Schatten siegen, Rokhan. Verteidiger, vorwärts!', '', 28153),
(151428, 'deDE', 'Ich hab nur auf Euch gewartet, Rokhan. Verteidiger, zeigt ihnen, aus welchem Holz wir geschnitzt sind!', '', 28153),
(151427, 'deDE', 'Schweigt, Troll. Die Allianz wird Eure Armee von schmutzigen Monstern bald genug in die Knie zwingen.', '', 28153),
(151426, 'deDE', 'Und doch scheint das Licht über Stromgarde.', '', 28153),
(151425, 'deDE', 'Ich komm noch früh genug, Jungchen. Dachte, ich lass Euch erst noch etwas weichklopfen.', '', 28153),
(151424, 'deDE', 'Stromgarde steht noch immer, Orc. Und Eure Leiche wird bald in meinem Burggraben schwimmen. Verteidiger, zeigt ihnen die Stärke unserer Stadt!', '', 28153),
(151423, 'deDE', 'Ich habe mehr Schlachten gewonnen und verloren, als Ihr je erlebt habt, Etrigg. Und diese ist noch lange nicht vorbei. Vorwärts, Verteidiger!', '', 28153),
(151422, 'deDE', 'Erst müsst Ihr mich zu fassen kriegen. Verteidiger, drängt sie zurück!', '', 28153),
(151421, 'deDE', 'Hmpf. Ihr und Eure Art seid alle gleich. Ihr werdet bald genug um Euer Leben winseln.', '', 28153),
(151420, 'deDE', 'Habt Geduld, Orc. Sie wird kommen, seid versichert.', '', 28153),
(151419, 'deDE', 'Und ich rieche Euren Atem von hier unten. Zeigt\'s mir doch, Orc!', '', 28153),
(151418, 'deDE', 'Belagerungsmaschinen, feuert auf das Tor. Ich werde den Kopf dieser Blutelfe auf eine Lanze spießen!', '', 28153),
(151417, 'deDE', 'Belagerungsmaschinen, Angriff auf das Tor! Bringt mir Rokhan! Man nennt mich nicht ohne Grund Trollbann...', '', 28153),
(151416, 'deDE', 'Belagerungsmaschinen, vernichtet das Tor! Dieser üble Orc wird die Gerechtigkeit der Allianz zu spüren bekommen!', '', 28153),
(151415, 'deDE', 'Der Hochstand gehört uns. Das ist Eure letzte Chance, Blutelfe. Ergebt Euch und ich lasse Euch vielleicht am Leben.', '', 28153),
(151414, 'deDE', 'Wir haben den Hochstand gesichert. Bald holen wir uns Ar\'gorok und erobern unser Land zurück!', '', 28153),
(151413, 'deDE', 'Der Hochstand ist unser. Wir sind auf gutem Wege, diese Eindringlinge zu vertreiben.', '', 28153),
(151412, 'deDE', 'Mit Galsons Mine haben wir einen unerschöpflichen Vorrat an Eisen. Das können wir gut gebrauchen.', '', 28153),
(151411, 'deDE', 'Perfekt. Das Hochlandsägewerk wird uns mit dem Holz versorgen, das wir für den Wiederaufbau von Stromgarde brauchen.', '', 28153),
(151410, 'deDE', 'Das ist unsere Chance. Greift das Tor an! Nehmt Rache an diesem Hordeabschaum!', '', 28153),
(151409, 'deDE', 'Das ist unsere Chance. Greift das Tor an! Das Urteil des Lichts ereilt Euch, Rokhan!', '', 28153),
(151408, 'deDE', 'Das ist unsere Chance. Greift das Tor an! Euer Ende naht, Etrigg!', '', 28153),
(151407, 'deDE', 'Der Hochstand wurde eingenommen. Das Licht ist mit der Allianz.', '', 28153),
(151406, 'deDE', 'Der Hochstand ist unser und Ar\'gorok wird bald folgen. Wir kommen Euch holen, Rokhan.', '', 28153),
(151405, 'deDE', 'Wir haben den Hochstand eingenommen. Bald werden wir die Streitkräfte der Horde vernichten.', '', 28153),
(151404, 'deDE', 'Gut gemacht. Galsons Mine bietet uns all das Eisen, das wir brauchen.', '', 28153),
(151403, 'deDE', 'Das Holz des Sägewerks ist wichtig für den Bau unserer Basis.', '', 28153),
(151402, 'deDE', 'Bringt die Belagerungsmaschinen in Stellung! Zerstört das Tor! Zeigt der Blutelfe die Macht unserer Zwergenmörser!', '', 28153),
(151401, 'deDE', 'Bringt die Belagerungsmaschinen ran! Reißt das Tor nieder! Brennt diesen Trollschuppen weg!', '', 28153),
(151400, 'deDE', 'Schnell, bringt die Belagerungsmaschinen! Zerstört das Tor! Jagt die Orcs in die Luft!', '', 28153),
(151399, 'deDE', 'Der Hochstand gehört der Allianz! Seid Ihr bereit, die weiße Flagge zu hissen, Mädchen?', '', 28153),
(151398, 'deDE', 'Wir haben den Hochstand erobert! Als Nächstes kommt Ihr dran, Rokhan.', '', 28153),
(151397, 'deDE', 'Hehe... Meine Rechnung in der Schenke ist noch offen...', 'Hehe... Meine Rechnung in der Schenke ist noch offen...', 28153),
(151396, 'deDE', 'Der Hochstand ist unser! Für die Allianz!', '', 28153),
(151395, 'deDE', 'Vielleicht... können wir uns arrangieren...', 'Vielleicht... können wir uns arrangieren...', 28153),
(151394, 'deDE', 'Mit Galsons Mine unter unserer Kontrolle sollten wir mehr als genug Eisen haben.', '', 28153),
(151393, 'deDE', 'Gut, wir haben das Hochlandsägewerk erobert. Das wird uns beim Bau unserer Basis helfen.', '', 28153),
(151392, 'deDE', '', 'Für dies\'n Kampf braucht man Geschick. Un\' davon habter nich\' viel!', 28153),
(151391, 'deDE', '', 'Setzt die Verwüster ein! Zerstört ihr Tor! Macht Stromgarde dem Erdboden gleich!', 28153),
(151390, 'deDE', 'Vorsicht, Freundchen!', 'Vorsicht, Freundchen!', 28153),
(151389, 'deDE', '', 'Setzt die Verwüster ein! Zerstört Ihr Tor! Eure Zeit ist gekommen, Turalyon!', 28153),
(151388, 'deDE', 'Was soll das?', 'Was soll das?', 28153),
(151387, 'deDE', '', 'Schickt die Verwüster in den Kampf! Zerstört ihr Tor! Zwingt den Zwerg heraus ins Freie!', 28153),
(151386, 'deDE', '', 'Der Hochstand ist unser! Wir sind einen Schritt weiter, Arathi für die Horde zu erobern!', 28153),
(151385, 'deDE', '', 'Wir haben den Hochstand eingenommen! Die Horde rückt Euch bald zu Leibe, Turalyon.', 28153),
(151384, 'deDE', '', 'Wir haben den Hochstand eingenommen. Das Blatt wendet sich zu unseren Gunsten.', 28153),
(151383, 'deDE', '', 'Gute Arbeit. Ohne das Eisen aus dieser Mine kommen wir nicht weit.', 28153),
(151382, 'deDE', 'Selbst im Tod kriegter nix geback\'n. Geht beiseite un\' seht ma\' \'nem Meister bei der Arbeit zu.', '', 28153),
(151381, 'deDE', '', 'Wir verwenden das Holz vom Axtkamm für das Fundament unserer Basis. Gute Arbeit.', 28153),
(151380, 'deDE', 'Schickt die Verwüster rein! Macht das Tor kaputt! Un\' bringt mir den Kopf vom alten Narren Trollbann!', '', 28153),
(151379, 'deDE', 'Schickt die Verwüster rein! Kein Licht kann dies\'n Paladin vor der Macht der Horde schütz\'n!', '', 28153),
(151378, 'deDE', 'Schickt die Verwüster rein! Der Zwerg kann sich nich\' für immer hinter sein\'m Tor versteck\'n!', '', 28153),
(151377, 'deDE', 'Der Hochstand is\' in unsren Händen, Trollbann.', '', 28153),
(151376, 'deDE', 'Der Hochstand is\' unser, Turalyon. Die Schatt\'n komm\'n näher...', '', 28153),
(151375, 'deDE', 'Muradin, wir hol\'n uns den Hochstand. Kommt Ihr jetzt endlich raus und kämpft?', '', 28153),
(151374, 'deDE', 'Die Mine der Trockenstoppel gehört der Horde.', '', 28153),
(151373, 'deDE', '', 'Ihr seid tot auch nich\' mehr wert als lebendig. Ich kümmer mich selbst um die.', 28153),
(151372, 'deDE', 'Gut. Wir brauch\'n das Holz vom Axtkamm für unsre Hochburg.', '', 28153),
(151371, 'deDE', 'Bringt die Verwüster! Zerstört das Tor! Zeigen wir diesem törichten Trollbann, was ein paar Grünhäute anrichten können!', '', 28153),
(151370, 'deDE', '', 'Ihr seid zu einer stattlichen jungen Frau herangewachsen, Taelia. Euer Vater wäre stolz auf Euch.', 28153),
(151369, 'deDE', 'Bringt die Verwüster! Bombardiert das Tor! Die Schlacht ist so gut wie gewonnen!', '', 28153),
(151368, 'deDE', 'Bringt die Verwüster! Vernichtet das Tor! Wir werden diesen vermaledeiten Zwerg aufspießen!', '', 28153),
(151367, 'deDE', 'Das wird dem Boss nicht gefallen...', 'Das wird dem Boss nicht gefallen...', 28153),
(151366, 'deDE', 'Der Hochstand gehört der Horde. Oder sollte ich sagen... \"den elenden Grünhäuten\".', '', 28153),
(151365, 'deDE', 'Der Hochstand ist unser. Wo ist Eure Vergeltung, Turalyon? Ich warte...', '', 28153),
(151364, 'deDE', 'Aua...', 'Aua...', 28153),
(151363, 'deDE', 'War doch nicht... so gemeint...', 'War doch nicht... so gemeint...', 28153),
(151362, 'deDE', 'Wir haben den Hochstand erobert. Muradin! Ich sehe Eure Knollennase von hier oben!', '', 28153),
(151361, 'deDE', 'Ich hab nur... meine Arbeit gemacht...', 'Ich hab nur... meine Arbeit gemacht...', 28153),
(151360, 'deDE', '', 'Taelia... Ich erinnere mich. Unser junger Gast von jenseits des Meeres. Ist es schon so lange her?', 28153),
(151359, 'deDE', 'Gut gemacht, mit der Mine der Trockenstoppel unter Kontrolle wird es uns nie an Eisen fehlen.', '', 28153),
(151358, 'deDE', 'Der Axtkamm gehört uns. Das dortige Sägewerk wird beim Aufbau unserer Basis helfen.', '', 28153),
(151357, 'deDE', 'Ist nicht persönlich gemeint, aber es gibt Regeln!', 'Ist nicht persönlich gemeint, aber es gibt Regeln!', 28153),
(151356, 'deDE', 'Der Heldenrufpass ist jetzt unser. Rückt weiter vor!', '', 28153),
(151355, 'deDE', '', 'Taelia, Herrin.', 28153),
(151354, 'deDE', 'Gute Arbeit. Wir haben den Zirkel der Elemente zurückerobert.', '', 28153),
(151353, 'deDE', 'Über Neuhof wehen wieder Allianzbanner.', '', 28153),
(151352, 'deDE', '', 'Selbstverständlich. Wie war gleich Euer Name?', 28153),
(151351, 'deDE', 'Wir haben den Heldenrufpass eingenommen.', '', 28153),
(151350, 'deDE', 'Der Zirkel der Elemente gehört nun der Allianz.', '', 28153),
(151349, 'deDE', 'Gute Arbeit, Soldaten. Neuhof gehört uns.', '', 28153),
(151348, 'deDE', 'Lasst das!', 'Lasst das!', 28153),
(151347, 'deDE', '', 'Lordadmiralin, vielleicht sollten wir Euch zurück zur Burg bringen. Wir können die Beweise gegen Haus Aschenwind dort durchgehen.', 28153),
(151346, 'deDE', 'Gut, wir haben sie vom Heldenrufpass vertrieben. Weiter geht\'s!', '', 28153),
(151345, 'deDE', 'Wir haben den Zirkel der Elemente eingenommen!', '', 28153),
(151344, 'deDE', 'So geht das nicht!', 'So geht das nicht!', 28153),
(151343, 'deDE', 'Wir haben Neuhof in Besitz genommen!', '', 28153),
(151342, 'deDE', '', 'Der Zirkel der Elemente gehört uns.', 28153),
(151341, 'deDE', '', 'Wir haben Neuhof erfolgreich gesichert.', 28153),
(151340, 'deDE', 'Wir wissen mit Unruhestiftern umzugehen!', 'Wir wissen mit Unruhestiftern umzugehen!', 28153),
(151338, 'deDE', '', 'Das verschafft uns etwas Raum zum Atmen.', 28153),
(151337, 'deDE', 'Hey!', 'Hey!', 28153),
(151336, 'deDE', 'Passt auf die Schatten auf, Allianzabschaum. Die Horde kommt Euch hol\'n...', '', 28153),
(151335, 'deDE', 'Gut gekämpft. Nachdem das Nordhofkreuz eingenommen ist, können wir uns auf Größeres konzentrieren.', '', 28153),
(151333, 'deDE', '', 'Ihr da! Auf ein Wort.', 28153),
(151332, 'deDE', 'Unzählige Jahre habe ich auf den Tag meiner Rache gewartet, bis Eure Mutter mir endlich eine Gelegenheit bot.', '', 28153),
(151331, 'deDE', 'Mein Volk haben sie ausgelöscht, aber mich konnten sie nicht vernichten.', '', 28153),
(151330, 'deDE', '', 'Gorak Tul?! Wie ist das möglich? Meine Vorfahren haben Euch vor Urzeiten besiegt!', 28153),
(151329, 'deDE', 'Belagerungsmaschinen, zerstört diese Basis!', '', 28153),
(151328, 'deDE', 'Ich hatte Euch gewarnt, Hordenabschaum. Jetzt macht Euch bereit, vernichtet zu werden.', '', 28153),
(151327, 'deDE', 'Dieses Land gehört der Allianz! Das Licht wird Euresgleichen niemals die Mauern Stromgardes überwinden lassen.', '', 28153),
(151326, 'deDE', 'Seh ich da die Horde auf meinem Schlachtfeld? Ich warte schon lange auf eine richtige Rauferei!', '', 28153),
(151324, 'deDE', 'Ihr müsst sie aufhalten und das Azerit absorbieren, um das Herz mit Energie zu versorgen.', '', 28153),
(151323, 'deDE', 'Überall auf Azeroth reißen weitere Wunden auf und mehr Fraktionen versuchen, Azerit für ihre eigenen Zwecke zu gewinnen.', '', 28153),
(151322, 'deDE', 'Das Herz von Azeroth ist der Schlüssel zur Heilung unserer Welt... aber Ihr müsst mehr Energie sammeln, wenn wir eine Chance haben wollen.', '', 28153),
(151321, 'deDE', 'Magni, Ihr könnt das Herz von Azeroth jetzt stärken.', 'Magni, Ihr könnt das Herz von Azeroth jetzt stärken.', 28153),
(151320, 'deDE', 'Champion, ich muss mit Euch in Silithus sprechen. Es gibt noch mehr zu tun, um unsere Welt zu heilen!', '', 28153),
(151319, 'deDE', '', 'Ich habe einen Besen! Und ich habe keine Skrupel, ihn einzusetzen!', 28153),
(151318, 'deDE', '', 'Weg mit euch, Luftratten!', 28153),
(151317, 'deDE', '', 'Runter von meiner Treppe!', 28153),
(151316, 'deDE', '', 'Verschwindet hier, dreckige Vögel!', 28153),
(151315, 'deDE', 'Jetzt ist Zahltag, Ihr Wichte!', '', 28153),
(151314, 'deDE', 'Alptraumbestien, kommt hervor!', '', 28153),
(151313, 'deDE', 'Ich habe ein gutes Gefühl. Wir werden heute fündig.', 'Ich habe ein gutes Gefühl. Wir werden heute fündig.', 28153),
(151312, 'deDE', 'Diese Stiefel werden mir besser stehen.', 'Diese Stiefel werden mir besser stehen.', 28153),
(151311, 'deDE', 'Ich schlitz Euch auf!', 'Ich schlitz Euch auf!', 28153),
(151310, 'deDE', 'Hier kann Euch niemand mehr retten, Abschaum.', 'Hier kann Euch niemand mehr retten, Abschaum.', 28153),
(151309, 'deDE', 'Passt auf, wohin Ihr tretet.', 'Passt auf, wohin Ihr tretet.', 28153),
(151308, 'deDE', 'Ihr seid ja so zerbrechlich...', 'Ihr seid ja so zerbrechlich...', 28153),
(151307, 'deDE', 'Wartet\'s nur ab...', 'Wartet\'s nur ab...', 28153),
(151306, 'deDE', 'Diese Ressourcen gehören nicht Euch!', 'Diese Ressourcen gehören nicht Euch!', 28153),
(151305, 'deDE', 'Frische Beute!', 'Frische Beute!', 28153),
(151304, 'deDE', 'Türmt Euch auf, meine wogenden Diener!', '', 28153),
(151303, 'deDE', 'Kriechende Schrecken, kommt und labt Euch!', '', 28153),
(151302, 'deDE', 'Kreaturen der Tiefe, hört meinen Ruf!', '', 28153),
(151301, 'deDE', 'Luft ist gut hier. Nicht wie in Mine voller Orcs.', '', 28153),
(151300, 'deDE', 'Die Finsternis verschlingt Euch!', '', 28153),
(151299, 'deDE', 'Ich bin Eurer überdrüssig. Das endet jetzt!', '', 28153),
(151298, 'deDE', 'Azsharas Dienerschar ist endlos. Warum kämpft Ihr?', '', 28153),
(151297, 'deDE', 'Ich habe nicht mehr so viel Angst. Aber Steine machen Arme müde.', '', 28153),
(151295, 'deDE', 'Er kann bereits das Flüstern hören. Wir haben nicht viel Zeit.', '', 28153),
(151294, 'deDE', '', 'Ich bin direkt hinter Euch. Wartet nicht auf mich!', 28153),
(151293, 'deDE', 'Unter den Wogen... wartend... rufend...', '', 28153),
(151292, 'deDE', 'Hier entlang. Ich hol Eisen.', '', 28153),
(151291, 'deDE', 'Sucht in der Nähe nach Waffenständern. Die Treulosen haben hier überall welche aufgestellt.\n\nIch werde mich hier unauffällig verhalten, bis Ihr zurückkommt.', 'Sucht in der Nähe nach Waffenständern. Die Treulosen haben hier überall welche aufgestellt.\n\nIch werde mich hier unauffällig verhalten, bis Ihr zurückkommt.', 28153),
(151290, 'deDE', '', 'Winde, seid mein Schild!', 28153),
(151289, 'deDE', 'Ich komme wieder, sobald ich eine Waffe für Euch gefunden habe.', 'Ich komme wieder, sobald ich eine Waffe für Euch gefunden habe.', 28153),
(151288, 'deDE', '', 'Die Winde stärken uns stets den Rücken!', 28153),
(151287, 'deDE', 'Ihr werdet zersplittern!', '', 28153),
(151286, 'deDE', 'Meine Planken sind undurchdringlich!', '', 28153),
(151285, 'deDE', 'Die Elemente rasen vor Wut!', 'Die Elemente rasen vor Wut!', 28153),
(151284, 'deDE', 'Die sterblichen Weltendiebe werden zugrunde gehen.', 'Die sterblichen Weltendiebe werden zugrunde gehen.', 28153),
(151283, 'deDE', 'Wir werden alles zurückholen, was Ihr Euch genommen habt!', 'Wir werden alles zurückholen, was Ihr Euch genommen habt!', 28153),
(151282, 'deDE', 'Die Elemente werden alles beherrschen!', 'Die Elemente werden alles beherrschen!', 28153),
(151281, 'deDE', 'Das lassen wir uns nicht wegnehmen!', 'Das lassen wir uns nicht wegnehmen!', 28153),
(151280, 'deDE', 'Diese Edelsteine gehören den Herrschern der Elemente!', 'Diese Edelsteine gehören den Herrschern der Elemente!', 28153),
(151279, 'deDE', '<Befreit den Sklaven und gebt ihm eine Waffe.>', '<Befreit den Sklaven und gebt ihm eine Waffe.>', 28153),
(151278, 'deDE', 'Mithilfe dieser Macht werden wir diese Welt zurückerobern!', 'Mithilfe dieser Macht werden wir diese Welt zurückerobern!', 28153),
(151277, 'deDE', '<Befreit den Sklaven und gebt ihm eine Waffe.>', '<Befreit den Sklaven und gebt ihm eine Waffe.>', 28153),
(151276, 'deDE', 'Mein Herrscher wird mich für Eure Vernichtung belohnen.', 'Mein Herrscher wird mich für Eure Vernichtung belohnen.', 28153),
(151275, 'deDE', 'Gebt mir eine Waffe, und ich gebe Euch zehn tote Treulose.', 'Gebt mir eine Waffe, und ich gebe Euch zehn tote Treulose.', 28153),
(151274, 'deDE', 'Packt Eure Sachen zusammen. Ihr kommt mit mir.', 'Packt Eure Sachen zusammen. Ihr kommt mit mir.', 28153),
(151273, 'deDE', 'Brecht diese Ketten auf. Vulpera sind für ein Leben in Freiheit bestimmt.', 'Brecht diese Ketten auf. Vulpera sind für ein Leben in Freiheit bestimmt.', 28153),
(151272, 'deDE', 'Ich will ja arbeiten, aber es ist nicht sicher.', '', 28153),
(151271, 'deDE', 'Befreit mich, $PR, und ich helfe Euch, die Treulosen zu töten.', 'Befreit mich, $PR, und ich helfe Euch, die Treulosen zu töten.', 28153),
(151270, 'deDE', 'Keine Gnade für die Treulosen. Nicht nach allem, was sie getan haben.', 'Keine Gnade für die Treulosen. Nicht nach allem, was sie getan haben.', 28153),
(151269, 'deDE', 'Die Treulosen werden dafür bezahlen, was sie mir angetan haben.', 'Die Treulosen werden dafür bezahlen, was sie mir angetan haben.', 28153),
(151268, 'deDE', 'Hat Nisha Euch geschickt? Was auch immer sie vorhat, ich bin dabei.', 'Hat Nisha Euch geschickt? Was auch immer sie vorhat, ich bin dabei.', 28153),
(151267, 'deDE', 'Beschafft mir einfach eine Waffe, und ich kümmere mich um den Rest.', 'Beschafft mir einfach eine Waffe, und ich kümmere mich um den Rest.', 28153),
(151266, 'deDE', 'Ich brauche nur eine Waffe.', 'Ich brauche nur eine Waffe.', 28153),
(151265, 'deDE', 'Nein... Die Edelsteine gehören mir... Ihr dürft sie... nicht haben...', '', 28153),
(151264, 'deDE', 'Nein! Narren!', '', 28153),
(151263, 'deDE', 'Ihr... habt nicht... gewonnen...', '', 28153),
(151262, 'deDE', 'Ich werde zurückkehren!', '', 28153),
(151261, 'deDE', 'Unsere Zeit wird kommen...', '', 28153),
(151260, 'deDE', 'Ihr zögert... das Unausweichliche... nur hinaus...', '', 28153),
(151259, 'deDE', 'Chaos... lässt sich nicht bändigen...', '', 28153),
(151258, 'deDE', 'Niemand kann die Elemente... aufhalten...', '', 28153),
(151257, 'deDE', 'Eure Meere werden sieden, Euer Himmel wird aufbrechen, Eure Berge sich erheben und wir werden zurückkehren!', '', 28153),
(151256, 'deDE', 'Das Erwachen der Elemente naht!', '', 28153),
(151255, 'deDE', 'Eure Zeit ist abgelaufen, Sterbliche.', '', 28153),
(151254, 'deDE', 'Mithilfe dieser Edelsteine werden wir Euch endlich vernichten.', '', 28153),
(151253, 'deDE', 'Die Elemente werden wieder herrschen!', '', 28153),
(151252, 'deDE', 'Die goldenen Mineralien geben uns Kraft!', '', 28153),
(151251, 'deDE', 'Eure Welt wird wieder uns gehören!', '', 28153),
(151250, 'deDE', 'Wie könnt Ihr es wagen, mich auf meiner eigenen Ebene anzugreifen?', '', 28153),
(151249, 'deDE', 'Ich schaue zu. Habe die Hände voll!', '', 28153),
(151248, 'deDE', 'Schickt mich nach Orgrimmar.', 'Schickt mich nach Orgrimmar.', 28153),
(151247, 'deDE', '', '$n, schön, Euch zu seh\'n. Ich werd erstmal hier bei Krag\'wa bleib\'n.\n\nMeine Eltern hab\'n mir viele Geschichten über den Froschloa erzählt. Es is\' mir \'ne Ehre, ihn vor den Bluttrollen zu beschütz\'n.', 28153),
(151246, 'deDE', 'Das sollte reichen! Ich danke Euch!', 'Das sollte reichen! Ich danke Euch!', 28153),
(151245, 'deDE', 'Champion, bringt mir die Kanonenkugeln, damit ich weiterfeuern kann!', 'Champion, bringt mir die Kanonenkugeln, damit ich weiterfeuern kann!', 28153),
(151244, 'deDE', '', 'Drehnor, Dreynor, Dreinor, Drähnor? Hach... Ich sage einfach, ich komme aus der Scherbenwelt.', 28153),
(151243, 'deDE', '', 'Ihr nennt mich unverderbt, aber ich selbst bezeichne mich lieber als Originalorc.', 28153),
(151242, 'deDE', '', 'Einmal habe ich meine Haare grün gefärbt. Kriegshäuptling Höllschrei hat das überhaupt nicht gefallen.', 28153),
(151241, 'deDE', '', 'Genug von diesem schnibbedi-schnick-wibbelig-wabbeligen... Ach! Lasst mich doch einfach irgendwas kaputt hauen!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'deDE', '', 'Die Orcs der Zerschmetterten Hand sind legendäre Krieger. Fragt sie aber bloß niemals nach einer Rückenmassage. Vertraut mir... <Schmerzenslaute>', 28153),
(151239, 'deDE', '', 'Azeroth hat einfach zu viele Regeln, wen man abstechen darf und wen nicht, wen man hauen darf und wen nicht... Macht Euch doch mal locker!', 28153),
(151238, 'deDE', '', 'Hey, ist das nicht EURE verlassene Garnison im Frostfeuergrat? Eine Frechheit! Erst mit viel Trara hinbauen und dann einfach so verfallen lassen...', 28153),
(151237, 'deDE', '', 'Bleibt, solange Ihr wollt. Aber wenn Ihr etwas kaputt macht, müsst Ihr es auch bezahlen!', 28153),
(151236, 'deDE', '', 'Bevor wir noch weitergehen, muss ich fragen: Wo liegt Eure Schmerzgrenze?', 28153),
(151235, 'deDE', '', 'Nur weil ich Euch gerne um mich habe, heißt das nicht, dass ich Euch nicht auch gerne eine reinhaue.', 28153),
(151234, 'deDE', '', 'So ein Schamane des Blutenden Auges hat gerade mit mir geflirtet. Zumindest glaube ich das. Entweder er hat mir viel sagend zugezwinkert oder er hat eben erst ein Auge geopfert.', 28153),
(151233, 'deDE', '', 'Der letzte, der mich angegraben hat, den hab ich eingegraben.', 28153),
(151232, 'deDE', '', 'So ein grüner Orc wollte mich mit seinen Dämonenblutgriffeln antatschen, da hat er meinen Streitkolben zu spüren bekommen.', 28153),
(151231, 'deDE', '', 'Wisst Ihr vielleicht, ob Saurfang Single ist? Ich hab ein Faible für reife Herren...', 28153),
(151230, 'deDE', '', 'Ihr braucht kein Dunkles Portal. Das Tor zu meinem Herzen steht Euch bereits offen.', 28153),
(151229, 'deDE', '', 'Das... tut mir echt leid.', 28153),
(151228, 'deDE', '', 'Erbärmlich. Die Mag\'har werden Euch in die Knie zwingen.', 28153),
(151227, 'deDE', 'Wenn man will, dass etwas richtig gemacht wird...', 'Wenn man will, dass etwas richtig gemacht wird...', 28153),
(151226, 'deDE', 'Hätte auf die Beförderung... bestehen soll\'n...', 'Ich armes, gebranntes... Kind...', 28153),
(151225, 'deDE', 'Begrabt mich... mit meinem Geld...', 'Keiner hält den Tod auf... oder die Steuern...', 28153),
(151224, 'deDE', 'Das... brennt...', 'Dafür... werdet Ihr zahlen...', 28153),
(151223, 'deDE', 'Das war\'s... nicht wert...', 'Das war\'s... nicht wert...', 28153),
(151222, 'deDE', 'Wo ist meine... Gefahrenzulage...', 'Das war\'s... nicht wert...', 28153),
(151221, 'deDE', '', 'Ich schulde Euch was.', 28153),
(151220, 'deDE', '', 'Ich danke Euch.', 28153),
(151219, 'deDE', 'Der Kriegshäuptling hat Kollateralschäden genehmigt. Feuer frei!', 'Der Kriegshäuptling hat Kollateralschäden genehmigt. Feuer frei!', 28153),
(151218, 'deDE', 'Kollateralschäden genehmigt. Feuer frei!', 'Auf Euch is\' \'ne fette Belohnung ausgesetzt... und die gehört mir!', 28153),
(151217, 'deDE', '', 'Ich stehe in Eurer Schuld.', 28153),
(151216, 'deDE', '', 'Ihr werdet vor mir im Staub liegen.', 28153),
(151215, 'deDE', 'Ihr haltet sie... niemals auf...', 'Ihr haltet sie... niemals auf...', 28153),
(151214, 'deDE', 'Falsche Stadt für Retterkomplexe, Kumpel.', 'Riesenfehler, Kumpel!', 28153),
(151213, 'deDE', '', 'Bei den Monden Draenors!', 28153),
(151212, 'deDE', 'Das werd ich genießen!', 'Oh Baby, ich steh drauf, Zeug abzufackeln!', 28153),
(151211, 'deDE', 'Für die Horde... und für die Kohle!', 'Für die Horde!', 28153),
(151210, 'deDE', '', 'Ich habe nur meine Pflicht getan.', 28153),
(151209, 'deDE', '', 'Verlangt das nie wieder von mir.', 28153),
(151208, 'deDE', '', 'War mir ein Vergnügen.', 28153),
(151207, 'deDE', '', 'Nein.', 28153),
(151206, 'deDE', '', 'Nichts da!', 28153),
(151205, 'deDE', '', 'Niemals!', 28153),
(151204, 'deDE', '', 'So ist es.', 28153),
(151203, 'deDE', '', 'Natürlich.', 28153),
(151202, 'deDE', '', 'In der Tat.', 28153),
(151201, 'deDE', '', 'Ich habe Schande über meinen Klan gebracht.', 28153),
(151200, 'deDE', '', 'Lasst mich mein Mana wiederauffüllen.', 28153),
(151199, 'deDE', '', 'Kein Mana!', 28153),
(151198, 'deDE', '', 'Sterbt ehrenhaft.', 28153),
(151197, 'deDE', '', 'Ich habe Euch nichts mehr zu sagen.', 28153),
(151196, 'deDE', '', 'Ihr könnt jetzt gehen.', 28153),
(151195, 'deDE', '', 'Geht mit Ehre.', 28153),
(151194, 'deDE', '', 'Sprecht.', 28153),
(151193, 'deDE', '', 'Ich grüße Euch.', 28153),
(151192, 'deDE', '', 'Lok-tar!', 28153),
(151191, 'deDE', '', 'Throm-ka!', 28153),
(151190, 'deDE', '', 'Bitte, ich flehe Euch an.', 28153),
(151189, 'deDE', '', 'Habt Mitleid mit einem armen Orc!', 28153),
(151188, 'deDE', '', 'Denkt auch mal an Euren Peon.', 28153),
(151187, 'deDE', '', 'Habt Ihr gut gemacht.', 28153),
(151186, 'deDE', '', 'Beeindruckend, doch.', 28153),
(151185, 'deDE', '', '<hmpf> Ich muss Euch gratulieren.', 28153),
(151184, 'deDE', 'Los, Ihr Geizkragen, diese Verteidigungen bezahlen sich schließlich nicht selbst!', '', 28153),
(151183, 'deDE', '', 'Zerquetscht diesen Feind!', 28153),
(151182, 'deDE', '', 'Auf mein Ziel!', 28153),
(151181, 'deDE', '', 'Zwingt meinen Gegner in die Knie!', 28153),
(151180, 'deDE', '', 'Sterbt ehrenvoll!', 28153),
(151179, 'deDE', '', 'Zum Angriff!', 28153),
(151178, 'deDE', '', 'Mok-thora ka!', 28153),
(151177, 'deDE', 'Warum kämpft Ihr?', 'Warum kämpft Ihr?', 28153),
(151176, 'deDE', 'Die Horde wird überdauern.', 'Die Horde wird überdauern.', 28153),
(151175, 'deDE', '', 'Wir werden angegriffen!', 28153),
(151174, 'deDE', '', 'Zerquetscht unsere Feinde!', 28153),
(151173, 'deDE', '', 'Durchbrecht ihre Reihen!', 28153),
(151172, 'deDE', '', 'Flieht oder sterbt!', 28153),
(151171, 'deDE', '', 'Wir kämpfen an einem anderen Tag weiter.', 28153),
(151170, 'deDE', '', 'Weg! Weg!', 28153),
(151169, 'deDE', '', 'Kommt, hier entlang.', 28153),
(151168, 'deDE', '', 'Lasst einen Orc vorangehen.', 28153),
(151167, 'deDE', 'Kameraden... macht ohne mich weiter...', 'Kameraden... macht ohne mich weiter...', 28153),
(151166, 'deDE', 'Zeit zu ruhen.', 'Zeit zu ruhen.', 28153),
(151165, 'deDE', '', 'Folgt mir.', 28153),
(151164, 'deDE', 'Geister... leitet mich.', 'Geister... leitet mich.', 28153),
(151163, 'deDE', 'Tretet beiseite, wenn Ihr leben wollt.', 'Tretet beiseite, wenn Ihr leben wollt.', 28153),
(151162, 'deDE', 'Ob wir heilen oder verletzen, ist unsere Wahl.', 'Ob wir heilen oder verletzen, ist unsere Wahl.', 28153),
(151161, 'deDE', '', 'Für die Horde!', 28153),
(151160, 'deDE', 'Horde, zu mir! Ich werde Eure Wunden verbinden!', 'Horde, zu mir! Ich werde Eure Wunden verbinden!', 28153),
(151159, 'deDE', '', 'Ich wurde verwundet!', 28153),
(151158, 'deDE', '', 'Helft mir, Heiler!', 28153),
(151157, 'deDE', 'Die Erdenmutter leite mich.', 'Die Erdenmutter leite mich.', 28153),
(151156, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(151155, 'deDE', '', 'Steht nicht einfach nur rum! Helft mir!', 28153),
(151154, 'deDE', '', 'Helft mir sofort!', 28153),
(151153, 'deDE', '', 'Macht Euch bereit!', 28153),
(151152, 'deDE', '', 'Verbrennt sie alle!', 28153),
(151151, 'deDE', '', 'Feuer frei!', 28153),
(151150, 'deDE', '', 'Wartet hier!', 28153),
(151149, 'deDE', '', 'Rührt Euch nicht von der Stelle.', 28153),
(151148, 'deDE', '', '<Applause sounds>', 28153),
(151147, 'deDE', '', '<Yawning sound>', 28153),
(151146, 'deDE', '', '<Short cheer--Wooooo!>', 28153),
(151145, 'deDE', '', '<Slightly longer cheer--Woohoo!>', 28153),
