(151126, 'deDE', '', '<Distressed cry: Total 3>', 28153),
(151125, 'deDE', '', '<Convey summoning power. Energy buildup: Total 5-7>', 28153),
(151124, 'deDE', '', '<Release spell, throwing energy: Total 3-5>', 28153),
(151123, 'deDE', '', '<Standard attack: Total 10>', 28153),
(151122, 'deDE', '', '<Big attack: Total 5>', 28153),
(151121, 'deDE', '', '<Falling from high terrain. Impending injury or death: Total 1>', 28153),
(151120, 'deDE', '', '<Player takes a wound: Total 10>', 28153),
(151118, 'deDE', '', '<Player takes significant wound: Total 5>', 28153),
(151117, 'deDE', '', '<Long attack with wind up. Jump attacks: Total 5-7>', 28153),
(151116, 'deDE', '', '<Convey releasing power or charging enemy: Total 4-6>', 28153),
(151115, 'deDE', '', '<Charging to attack enemy: Total 5-7>', 28153),
(151114, 'deDE', '', '<Dying sounds: Total 5>', 28153),
(151113, 'deDE', 'Meint Ihr diese Plagen, Raik? Beendet es. Sofort.', '', 28153),
(151112, 'deDE', '', 'Ich brauche beide Hände für meine Waffe.', 28153),
(151111, 'deDE', '', 'Diese Fähigkeit ist noch nicht bereit.', 28153),
(151110, 'deDE', '', 'Das kann ich noch nicht tun.', 28153),
(151109, 'deDE', '', 'Noch nicht bereit.', 28153),
(151108, 'deDE', '', 'Das kann ich da nicht ablegen.', 28153),
(151107, 'deDE', '', 'Diese Tasche ist voll.', 28153),
(151106, 'deDE', '', 'Das kann ich hier nicht tun.', 28153),
(151105, 'deDE', '', 'Das kann ich nicht wegwerfen.', 28153),
(151104, 'deDE', '', 'Das ist an mich gebunden.', 28153),
(151103, 'deDE', '', 'Das kann ich nicht anlegen.', 28153),
(151102, 'deDE', '', 'Meine Stufe ist nicht hoch genug, um das zu benutzen.', 28153),
(151101, 'deDE', 'Kehrt zum Schrein zurück. Die Wiedergeburt der Flotte steht bevor.', '', 28153),
(151100, 'deDE', '', 'Das kann ich noch nicht benutzen.', 28153),
(151099, 'deDE', '', 'Meine Fertigkeitsstufe ist nicht hoch genug, um das anzulegen.', 28153),
(151098, 'deDE', '', 'So etwas kann ich niemals anlegen.', 28153),
(151097, 'deDE', '', 'Diesen Zauber kann ich nicht erlernen.', 28153),
(151096, 'deDE', '', 'Das kann ich nicht plündern.', 28153),
(151095, 'deDE', '', 'Das gehört nicht mir.', 28153),
(151094, 'deDE', '', 'Ich muss näher ran.', 28153),
(151093, 'deDE', '', 'Das ist zu weit weg.', 28153),
(151092, 'deDE', '', 'Da komme ich nicht ran.', 28153),
(151091, 'deDE', '', 'Das kann ich nicht handeln.', 28153),
(151090, 'deDE', '', 'Das kann ich nicht benutzen.', 28153),
(151089, 'deDE', '', 'Das ist nicht angelegt.', 28153),
(151088, 'deDE', '', 'Das muss ich erst anlegen.', 28153),
(151087, 'deDE', '', 'Das kann ich jetzt nicht plündern.', 28153),
(151086, 'deDE', '', 'Ich habe kein Ziel.', 28153),
(151085, 'deDE', '', 'Ich muss zuerst was anvisieren.', 28153),
(151084, 'deDE', '', 'Ich brauche ein Ziel.', 28153),
(151083, 'deDE', '', 'Das kann ich nicht.', 28153),
(151082, 'deDE', '', 'Dazu fehlt mir die Erlaubnis.', 28153),
(151081, 'deDE', '', 'Dieses Ziel kann ich nicht angreifen.', 28153),
(151080, 'deDE', '', 'Das kann ich nicht angreifen.', 28153),
(151079, 'deDE', '', 'Mein Inventar ist voll.', 28153),
(151078, 'deDE', '', 'Ich kann nicht noch mehr tragen.', 28153),
(151077, 'deDE', '', 'Das ist verschlossen.', 28153),
(151076, 'deDE', '', 'Mehr kann ich davon nicht tragen.', 28153),
(151075, 'deDE', '', 'Diesen Gegenstand kann ich noch nicht benutzen.', 28153),
(151074, 'deDE', '', 'Das ist noch nicht bereit.', 28153),
(151073, 'deDE', '', 'Dieser Gegenstand lädt noch auf.', 28153),
(151072, 'deDE', '', 'Nicht genug Jähzorn.', 28153),
(151071, 'deDE', '', 'Mein Jähzorn reicht nicht.', 28153),
(151070, 'deDE', '', 'Nicht genug Schmerz.', 28153),
(151069, 'deDE', '', 'Mein Schmerz reicht nicht.', 28153),
(151068, 'deDE', '', 'Das ist keine Tasche.', 28153),
(151067, 'deDE', '', 'Meine Mittel reichen nicht.', 28153),
(151066, 'deDE', '', 'Das kann ich mir nicht leisten.', 28153),
(151065, 'deDE', '', 'Das ist zu teuer.', 28153),
(151064, 'deDE', '', 'Dieser Held kann sich der Gruppe nicht anschließen.', 28153),
(151063, 'deDE', '', 'Ich habe keine Munition mehr.', 28153),
(151062, 'deDE', '', 'Nicht genug Energie.', 28153),
(151061, 'deDE', '', 'Ich brauche mehr Energie.', 28153),
(151060, 'deDE', '', 'Ich brauche erst Mana.', 28153),
(151059, 'deDE', '', 'Mein Mana ist fast alle.', 28153),
(151058, 'deDE', '', 'Nicht genug Mana.', 28153),
(151057, 'deDE', '', 'Nicht genug Wut.', 28153),
(151056, 'deDE', '', 'Ich brauche mehr Wut.', 28153),
(151055, 'deDE', '', 'Das ist zu weit weg.', 28153),
(151054, 'deDE', '', 'Ich bin zu weit weg.', 28153),
(151053, 'deDE', '', 'Ich muss näher ran.', 28153),
(151052, 'deDE', '', 'Wir können niemanden mehr einladen.', 28153),
(151051, 'deDE', '', 'Ich kann jetzt nicht mehr trinken.', 28153),
(151050, 'deDE', '', 'Diese Fähigkeit habe ich noch nicht gelernt.', 28153),
(151049, 'deDE', '', 'Das kann ich noch nicht.', 28153),
(151047, 'deDE', '', 'Dieser Zauber ist noch nicht bereit.', 28153),
(151046, 'deDE', '', 'Das kann ich noch nicht wirken.', 28153),
(151045, 'deDE', '', 'Das lädt noch auf.', 28153),
(151044, 'deDE', 'Ich werd gleich... Lasst mich an ihn ran!', '', 28153),
(151043, 'deDE', 'Das hat in den Visionen... anders ausgeseh\'n...', 'Das war... haarscharf, Mann...', 28153),
(151042, 'deDE', 'Haltet diesen Schnorrer aus meinem Spiel raus, Leute!', '', 28153),
(151041, 'deDE', 'Los, Leute, ich hab das Geld auch garantiert!', '', 28153),
(151040, 'deDE', 'Bevor wir da reinstürmen, sollten wir mehr darüber herausfinden, was diese Trolle im Schilde führen und wie wir sie aufhalten können.', '', 28153),
(151039, 'deDE', 'Wobei mir mein Bauch sagt, dass uns tief im Tempel noch mehr Probleme erwarten.', '', 28153),
(151038, 'deDE', 'Schön habt Ihr das Viech erledigt.', '', 28153),
(151037, 'deDE', 'Natürlich sind wir nicht die Einzigen, die davon angelockt wurden.', '', 28153),
(151036, 'deDE', 'Jawoll, wir sind am richtigen Ort. Ich spüre die Macht dieser Relikte tief in meinen Knochen.', '', 28153),
(151034, 'deDE', '', 'Ihr da! Meine Freunde haben mich zum Sterben zurückgelassen. Könntet Ihr?', 28153),
(151031, 'deDE', '', 'Hm... Faszinierend...', 28153),
(151030, 'deDE', 'Lernt selbst, zu kochen! Einem dürren Koch kann man nicht trauen!', '', 28153),
(151029, 'deDE', 'Die Loa... ruf\'n mich...', 'Glücks...treffer...', 28153),
(151028, 'deDE', 'Die Horde... lebt weiter...', 'Die Horde... wird gewinn\'...', 28153),
(151027, 'deDE', 'Bwonsamdi, ich komm zu Euch...', 'Bwonsamdi, ich komm zu Euch...', 28153),
(151026, 'deDE', 'Narren! Wie könnt Ihr gegen den Loa eines zertrümmerten Tempels ohne Anhänger scheitern?! Tötet ihn!', '', 28153),
(151025, 'deDE', 'Bwonsamdi... ich komme zu Euch...', 'Ich seh... die Andre Seite...', 28153),
(151024, 'deDE', 'Da kommt echt mieses Juju auf Euch zu!', 'Mieses Juju im Anflug!', 28153),
(151023, 'deDE', 'Doch, doch. Der Kriegshäuptling sagt, keine Überleb\'nden.', 'Doch, doch. Der Kriegshäuptling sagt, keine Überleb\'nden.', 28153),
(151022, 'deDE', 'Jetzt nich\' bewegen!', 'Mir weicht Ihr nich\' aus, Mann.', 28153),
(151021, 'deDE', 'Was hammer denn da? Menschlein, schwach un\' auf\'m Weg zur Schlachtbank.', 'Was hammer denn da? Menschlein, schwach un\' auf\'m Weg zur Schlachtbank.', 28153),
(151020, 'deDE', 'Ratztunk sagt, Ihr gehört hier nicht her, Welpe.', '', 28153),
(151019, 'deDE', 'Ratztunk lässt Euch grüßen.', '', 28153),
(151018, 'deDE', 'Pah! Kommt schon, ich bin am Verhungern!', '', 28153),
(151017, 'deDE', 'Meine Brüder und Schwestern haben sich einst aus Verbundenheit mit den Bäumen um dieses Land gekümmert. Aber diese Zeiten sind schon lange vorbei.\n\nNur einige wenige von uns haben diesen Weg noch nicht vergessen.\n\nDer Eschenwaldhain war einer unserer Rückzugsorte. Eine Zuflucht vor der Verderbnis, die langsam den Blutroten Wald erobert.\n\nDer in den Schatten gedeihende Befall scheint auch seiner Zeit ein Ende zu setzen. Ich sehe, wie er vergeht und nur noch in der Erinnerung jener weiterlebt, die ihn einst gepflegt haben.', '', 28153),
(151016, 'deDE', 'Loa, führt meine Klinge!', 'Ich schick Euch zu Bwonsamdi!', 28153),
(151015, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(151014, 'deDE', 'Stimmt etwas nicht mit dem Hain?', 'Stimmt etwas nicht mit dem Hain?', 28153),
(151013, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t G\'huun ruft die |cFFFF0404|Hspell:267509|h[Tausend Mäuler]|h|r um Hilfe an!', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t G\'huun ruft die |cFFFF0404|Hspell:267509|h[Tausend Mäuler]|h|r um Hilfe an!', 28153),
(151011, 'deDE', '', 'Es wird Zeit vergehen, bis meine volle Kraft zurückkehrt, aber der Fluch, der meine Rückkehr verhinderte, ist gebrochen.', 28153),
(151010, 'deDE', '', 'Ich stehe in Eurer Schuld, Helden.', 28153),
(151009, 'deDE', 'Wartet, wer sind diese Eindringlinge?! Sie verderben Sethraliss!', '', 28153),
(151008, 'deDE', 'Schickt mich auf das Schlachtfeld.', 'Schickt mich auf das Schlachtfeld.', 28153),
(151007, 'deDE', 'Ah... Ihr Sanktum sollte nicht mehr weit sein.', '', 28153),
(151006, 'deDE', 'Ohne sie wäre die Welt im Chaos versunken.', '', 28153),
(151005, 'deDE', 'Ich war dabei, als Sethraliss sich geopfert hat, um Mythrax aufzuhalten.', '', 28153),
(151003, 'deDE', 'Selbst von hier kann ich hören, wie die Wurzeln des Blutroten Waldes nach Blut lechzen. Ich hätte niemals gedacht, dass diese Verderbnis so weit reichen würde.', '', 28153),
(151002, 'deDE', 'Müsst Ihr jede Leiche nach Schätzen fleddern? Unser wahres Ziel ist Sethraliss!', '', 28153),
(151001, 'deDE', 'Nun, Ihr habt sichtlich ein Talent für Zerstörung.', '', 28153),
(151000, 'deDE', 'Aber jetzt ist Eile geboten. Ich spüre eine wachsende Dunkelheit im Tempel.', '', 28153),
(150999, 'deDE', 'Ich danke Euch für die Beseitigung dieser Plage.', '', 28153),
(150998, 'deDE', 'Sie hat sich geopfert, um Mythrax zu stoppen... aber mit ihrem Tod verdorrten die Dschungel von Vol\'dun zu Sand.', '', 28153),
(150997, 'deDE', 'Dieser Tempel ist die Ruhestätte von Sethraliss, einem mächtigen Loa, der mein Volk vor langer Zeit vor der Vernichtung bewahrt hat.', '', 28153),
(150996, 'deDE', '', 'Ja! Immer fest drauf!', 28153),
(150995, 'deDE', '', 'Ich hab zehn Gold auf den Großen gesetzt!', 28153),
(150993, 'deDE', 'Die Zeit ihrer Wiedergeburt ist verstrichen und jetzt befürchte ich, dass etwas ihre Rückkehr verhindert.', '', 28153),
(150990, 'deDE', 'Ihr verlasst den vorgesehenen Bereich und werdet aus Eurem Fahrzeug entfernt.', 'Ihr verlasst den vorgesehenen Bereich und werdet aus Eurem Fahrzeug entfernt.', 28153),
(150989, 'deDE', 'Eine kurze Atempause, die uns hoffentlich genug Zeit lässt, uns neu zu formieren und uns zu erholen.', '', 28153),
(150988, 'deDE', 'Schnell! Unsere Matrosen brauchen Hilfe! Sie sind verwundet und verletzt, und die Horde drängt heran!', '', 28153),
(150987, 'deDE', 'Möge die Flut Euch tragen.', '', 28153),
(150986, 'deDE', 'Frische Kohlköpfe!', '', 28153),
(150985, 'deDE', 'Möge der Wind Eure Segel füllen.', '', 28153),
(150984, 'deDE', 'Günstige Winde.', '', 28153),
(150983, 'deDE', 'Oh, hallo.', '', 28153),
(150982, 'deDE', 'Was braucht Ihr?', '', 28153),
(150981, 'deDE', 'Ich grüße Euch.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'deDE', 'Zeit für Prügel!', '', 28153),
(150979, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(150978, 'deDE', 'Niemand kann die Horde aufhalten!', 'Niemand kann die Horde aufhalten!', 28153),
(150977, 'deDE', 'Wir sind die Speerspitze...', 'Wir sind die Speerspitze...', 28153),
(150976, 'deDE', '', 'Ugalazul bwrxil\' qu rax.', 28153),
(150975, 'deDE', 'Besiegt... von Euresgleichen?', 'Besiegt... von Euresgleichen?', 28153),
(150974, 'deDE', 'Die Horde... wird siegen...', 'Dieses Land... wird uns gehören...', 28153),
(150973, 'deDE', 'Wir sind die... Speerspitze...', 'Ich sterbe... ehrenhaft...', 28153),
(150972, 'deDE', 'Niemand kann... uns aufhalten...', 'Wertloser... Abschaum...', 28153),
(150971, 'deDE', '', 'Der Abgrund wird... dieses Land verschlingen!', 28153),
(150970, 'deDE', '', 'Nein... Ich habe versagt!', 28153),
(150969, 'deDE', '', 'Verflucht soll Euer Volk sein!', 28153),
(150968, 'deDE', '', 'Wasser... nehmt mich auf!', 28153),
(150967, 'deDE', '', 'Mein Leben für... unsere Königin!', 28153),
(150966, 'deDE', '', 'Es steigt... aus der Tiefe empor...', 28153),
(150965, 'deDE', '', 'Unsere Königin wird obsiegen...', 28153),
(150964, 'deDE', 'Oh! Ich gehe sofort wieder zurück. Bitte meldet mich nicht!', 'Oh! Ich gehe sofort wieder zurück. Bitte meldet mich nicht!', 28153),
(150963, 'deDE', 'Ihr werdet ein würdiger Gegner sein.', 'Ihr werdet ein würdiger Gegner sein.', 28153),
(150962, 'deDE', 'Steckt Eure Nase nicht in fremder Leute Angelegenheiten!', 'Steckt Eure Nase nicht in fremder Leute Angelegenheiten!', 28153),
(150961, 'deDE', 'Der Abgrund wird... dieses Land verschlingen!', '', 28153),
(150960, 'deDE', 'Nein... Ich habe versagt!', '', 28153),
(150959, 'deDE', 'Verflucht soll Euer Volk sein!', '', 28153),
(150958, 'deDE', 'Wasser... nehmt mich auf!', '', 28153),
(150957, 'deDE', 'Mein Leben für... unsere Königin!', '', 28153),
(150956, 'deDE', 'Ihr werdet... sie niemals aufhalten...', '', 28153),
(150955, 'deDE', 'Es steigt... aus der Tiefe empor...', '', 28153),
(150954, 'deDE', 'Unsere Königin wird obsiegen...', '', 28153),
(150953, 'deDE', '', 'Indem wir verhindern, dass die Fuß fass\'n, schütz\'n wir unsre Heimat. Ich hoff, dass Gonk Euch schnell dafür belohnt, seine Rache auszuüb\'n.', 28153),
(150952, 'deDE', '', 'Wenn die Allianz sich in Zandalar in Stellung bringt, wär das \'ne absolute Katastrophe. Rettet, was noch zu rett\'n is\', aber zeigt ihnen keine Gnade.', 28153),
(150951, 'deDE', 'Wenn man will, dass etwas richtig gemacht wird...', '', 28153),
(150950, 'deDE', 'Euer Tod. Meine Ehre!', 'Das ist Euer Ende!', 28153),
(150949, 'deDE', 'Tötet sie alle!', 'Lok\'tar!', 28153),
(150948, 'deDE', 'Ihr werdet ein würdiger Gegner sein!', 'Keine Gefangenen!', 28153),
(150947, 'deDE', 'Für die... Horde...', 'Für die... Horde...', 28153),
(150946, 'deDE', 'Ah, eine echte Schönheit! Den Anteil habt Ihr Euch wirklich verdient.', '', 28153),
(150945, 'deDE', '', 'IHR mischt Euch in meine Angelegenheiten ein? Denkt Ihr, Ihr könnt meinem Willen trotzen?', 28153),
(150944, 'deDE', 'Macht Euch bereit. Diese Bestie wird keine leichte Beute sein!', '', 28153),
(150943, 'deDE', 'Es hat uns in seine Höhle geführt!', '', 28153),
(150942, 'deDE', 'Hmm... die Fährte führt dort hinunter, in diesen übelriechenden Pfuhl.', '', 28153),
(150941, 'deDE', 'Die Perle ist nicht hier. Vielleicht war Azsharas Lakai schlauer, als er schien.', '', 28153),
(150940, 'deDE', 'Euer Kopf hängt schon bald an meiner Wand!', '', 28153),
(150939, 'deDE', 'Schließt Frieden mit Eurer Königin, denn Euer Leben endet hier.', '', 28153),
(150938, 'deDE', 'Eindringlinge?! Ich versenke Eure Leichen in den schwarzen Tiefen, wo sie auf ewig gemartert werden!', '', 28153),
(150937, 'deDE', 'Der Loa ist zu stark! Zieht Euch ins Wasser zurück! Die Schlacht ist verloren!', '', 28153),
(150936, 'deDE', 'Zerstört den Tempel! Lasst keinen Stein auf dem anderen! Sie werden alle vor unserer Königin knien!', '', 28153),
(150935, 'deDE', 'Wahre Macht oder nicht, Ihr seid unsere nächste Beute!', '', 28153),
(150934, 'deDE', 'Willkommen, Eindringlinge! Gerade rechtzeitig, um Zeugen wahrer Macht zu werden!', '', 28153),
(150933, 'deDE', 'Eine prächtige Trophäe... aber unsere wahre Beute ist in den Schrein geflüchtet.', '', 28153),
(150932, 'deDE', '', 'Die Königin hat Euren Tod befohlen!', 28153),
(150931, 'deDE', '', 'Ruhm der Königin Azshara!', 28153),
(150930, 'deDE', '', 'Unser Schicksal erwartet uns!', 28153),
(150929, 'deDE', '', 'Euer Tod wird meinen Ruhm bedeuten!', 28153),
(150928, 'deDE', '', 'Niemand wird sich Königin Azshara entgegenstellen!', 28153),
(150927, 'deDE', '', 'Der Ring der Gezeiten gehört uns!', 28153),
(150926, 'deDE', '', 'Ihr könnt unsere Macht nicht begreifen!', 28153),
(150925, 'deDE', 'Ruhig! Ihr tragt doch gar keine Schuhe.', '', 28153),
(150924, 'deDE', '', 'Vielleicht nur einen? Ich könnt neue Schuhe gebrauch\'n.', 28153),
(150923, 'deDE', 'Geduld, kleine Schwesta!', '', 28153),
(150922, 'deDE', '', 'Die werd\'n überhaupt nix mitkrieg\'n. Keiner redet davon, ins Lager zu stürm\'... Ein paar von denen auszuschalt\'n tät aber nix schad\'n.', 28153),
(150921, 'deDE', 'Die Königin hat Euren Tod befohlen!', '', 28153),
(150920, 'deDE', 'Ruhm der Königin Azshara!', '', 28153),
(150919, 'deDE', 'Unser Schicksal erwartet uns!', '', 28153),
(150918, 'deDE', 'Euer Tod wird meinen Ruhm bedeuten!', '', 28153),
(150917, 'deDE', 'Niemand wird sich Königin Azshara entgegenstellen!', '', 28153),
(150916, 'deDE', 'Der Ring der Gezeiten gehört uns!', '', 28153),
(150914, 'deDE', 'Wir müss\'n hierbleib\'n. Wenn Ihr losrennt un\' wir deshalb alle draufgeh\'n, dann is\' niemand mehr übrig, der Bericht erstatt\'n kann.', '', 28153),
(150913, 'deDE', 'Ihr könnt unsere Macht nicht begreifen!', '', 28153),
(150912, 'deDE', 'Meine Kohlköpfe!', '', 28153),
(150911, 'deDE', 'Ist mal wieder Zeit für die Greifenjagd. Aufsatteln!', '', 28153),
(150908, 'deDE', 'Raubeinarbeit ist nicht immer glamourös, aber die Kohle stimmt.', '', 28153),
(150907, 'deDE', 'Wir haben einen großen Auftrag für Greifensättel und brauchen mehr Wolle. An die Arbeit!', '', 28153),
(150906, 'deDE', 'Je weniger da oben sind, desto weniger von denen stolpern den Berg runter. Saubere Arbeit!', '', 28153),
(150905, 'deDE', 'Auf dem Gletscher lungern immer mehr Wendigos rum. Schwingt Euren Hintern da hoch und tut was dagegen!', '', 28153),
(150904, 'deDE', 'Mit der Macht der Gezeitenperle ist unsere Flotte unaufhaltbar.', '', 28153),
(150903, 'deDE', '', 'Ich habe doch keinen Goldesel!', 28153),
(150902, 'deDE', 'Tut mir leid, Boss...', '', 28153),
(150901, 'deDE', '', 'Dämlicher Trottel! Die waren teuer!', 28153),
(150900, 'deDE', 'Danke, Helden. Ihr habt dem Volk von Kul Tiras neue Hoffnung gegeben.', '', 28153),
(150899, 'deDE', 'Ich spüre, wie die dunkle Präsenz sich zurückzieht. Der Schrein wird wieder heil sein.', '', 28153),
(150898, 'deDE', 'Hört nicht auf sein Raunen! Dieses Übel will Euch die Seele rauben!', '', 28153),
(150897, 'deDE', 'Bei der Gezeitenmutter!', '', 28153),
(150896, 'deDE', 'Seid auf der Hut, Helden. Im Dunkel lauert noch immer Böses. Wir müssen handeln, um den Schrein von seinem Einfluss zu befreien.', '', 28153),
(150895, 'deDE', 'Etwas stimmt nicht. Die Dunkelheit wuchert hier noch immer.', '', 28153),
(150894, 'deDE', 'Ihr habt Euch gegen die Flut gestellt, Herr. Jetzt reißt ihre Macht Euch in die Tiefe.', '', 28153),
(150893, 'deDE', 'Dann versenke ich Eure Leichen in den schwarzen Tiefen, wo sie auf ewig gemartert werden.', '', 28153),
(150892, 'deDE', 'Niemals.', '', 28153),
(150891, 'deDE', 'Zum letzten Mal: Schließt Euch mir an oder sterbt.', '', 28153),
(150890, 'deDE', 'Narr! Wir müssen aufs Meer zurückkehren und Königin Azshara verleiht uns die Macht dafür!', '', 28153),
(150889, 'deDE', 'Herr! Stoppt diesen Wahnsinn! Die Flotte von Kul Tiras darf nicht der Dunkelheit anheimfallen!', '', 28153),
(150888, 'deDE', '', 'Mir scheint, Ihr habt Gäste, Lord Sturmsang.', 28153),
(150887, 'deDE', '', 'Zollt ihm einfach Respekt un\' lasst ihn red\'n. Dann schmeißt er Euch hoffentlich nich\' von der Pyramide.', 28153),
(150886, 'deDE', 'Die Flotte von Kul Tiras gehört bald Euch, meine Königin.', '', 28153),
(150885, 'deDE', 'Meer zu Meer, Asche zu Asche, Flut zu Flut. Ruht in friedlichen Strömungen.', '', 28153),
(150884, 'deDE', 'Schnell! Haltet sie auf, bevor die Flotte verloren ist!', '', 28153),
(150883, 'deDE', 'Scheiben der Titanen aktiviert: Initiiere Verderbnisprotokoll', 'Scheiben der Titanen aktiviert: Initiiere Verderbnisprotokoll', 28153),
(150882, 'deDE', 'Scheiben der Titanen aktiviert: Initiiere Täuschungsprotokoll', 'Scheiben der Titanen aktiviert: Initiiere Täuschungsprotokoll', 28153),
(150881, 'deDE', '', 'Ist das Ritual erst beendet, gehört die Flotte von Kul Tiras Königin Azshara!', 28153),
(150880, 'deDE', 'Willkommen, Bruder Pike. Ihr kommt gerade recht, um Zeuge unseres Sieges zu werden.', '', 28153),
(150879, 'deDE', 'Sturmsang hat diesen geweihten Ort geschändet. Wir müssen sein übles Treiben ungeschehen machen.', '', 28153),
(150878, 'deDE', 'Stimmen?', 'Stimmen?', 28153),
(150877, 'deDE', 'Seid auf der Hut. Eine dunkle Präsenz beobachtet uns.', '', 28153),
(150876, 'deDE', 'Wir müssen den Schrein läutern von Lord Sturmsangs üblem Einfluss.', '', 28153),
(150875, 'deDE', '', 'Meister! Verlasst mich nich\'! Neeein!', 28153),
(150874, 'deDE', '', 'Ihr glaubt wirklich, Ihr könnt Euch geg\'n die Macht von G\'huun stell\'n? Für so \'ne Arroganz müsst Ihr bezahl\'n!', 28153),
(150873, 'deDE', 'Im Schlamm sind Stimmen!', 'Im Schlamm sind Stimmen!', 28153),
(150872, 'deDE', '', 'Wir sind am Boden.\n\nDas Licht von Rezan hat uns verlass\'n. Nur eine Handvoll jener, die dem großen König der Loa gefolgt sind, besitz\'n noch einen Hauch von Macht, und selbst die sind eher fragwürdig.\n\nUnser Leben war die personifizierte Hingabe. Was soll nun aus uns werd\'n?', 28153),
(150871, 'deDE', 'Zeit für ein paar Verbesserungen!', '', 28153),
(150870, 'deDE', 'So, mit fairem Kämpfen ist jetzt Schluss.', '', 28153),
(150869, 'deDE', 'Großartig! Diese Vorräte werden unseren Soldaten sehr weiterhelfen. Gut gemacht!', '', 28153),
(150868, 'deDE', 'Unsere Späher berichten, dass ganz in der Nähe ein Frachtschiff der Zandalari von Bluttrollräubern gekapert wurde. Tötet sie und nehmt ihnen die Vorräte ab.', '', 28153),
(150867, 'deDE', 'Aufgepasst, Jungs! Da will uns wohl jemand was verkaufen!', '', 28153),
(150866, 'deDE', 'Ja! Sucht Euch jemanden, der Euch in Modefragen berät!', '', 28153),
(150865, 'deDE', '', '$n! Hey, $n! Wir haben eine Aufgabe für Euch!', 28153),
(150864, 'deDE', 'Springen!', 'Springen!', 28153),
(150863, 'deDE', 'Ihr könnt Euch nich\' vor Bwonsamdi versteck\'n, Wicht!', '', 28153),
(150862, 'deDE', 'Irgendwas an Euch is\' seltsam... Ah, der Gestank von Dämonenjägern.', '', 28153),
(150861, 'deDE', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aEuer Kommandant wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aEuer Kommandant wird angegriffen!', 28153),
(150860, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Heldenrufpass wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Heldenrufpass wird angegriffen!', 28153),
(150859, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNeuhof wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNeuhof wird angegriffen!', 28153),
(150858, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente wird angegriffen!', 28153),
(150857, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Hochstand wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDer Hochstand wird angegriffen!', 28153),
(150856, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz wird angegriffen!', 28153),
(150855, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aDie Mine der Trockenstoppel wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aDie Mine der Trockenstoppel wird angegriffen!', 28153),
(150854, 'deDE', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aDer Axtkamm wird angegriffen!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aDer Axtkamm wird angegriffen!', 28153),
(150853, 'deDE', 'Wir müssen unsre Vorhutspäher erreichen. Schaltet dieses fliegende Ungeziefer sofort aus!', 'Wir müssen unsre Vorhutspäher erreichen. Schaltet dieses fliegende Ungeziefer sofort aus!', 28153),
(150852, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Heldenrufpass ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Heldenrufpass ist verloren!', 28153),
(150851, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNeuhof ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aNeuhof ist verloren!', 28153),
(150850, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Zirkel der Elemente ist verloren!', 28153),
(150849, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Hochstand ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDer Hochstand ist verloren!', 28153),
(150848, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aDas Nordhofkreuz ist verloren!', 28153),
(150847, 'deDE', 'Nein, Ihr träumt nich\', Mann.', '', 28153),
(150846, 'deDE', 'Die Geister sin\' bei Euch – oder besser: Ihr seid bei ihnen.', '', 28153),
(150845, 'deDE', 'Ah, ein Todesritter. Ihr solltet mal MEIN Schwarzes Tor seh\'n!', '', 28153),
(150844, 'deDE', 'Euer Land wird als nächstes fallen!', 'Euer Land wird als nächstes fallen!', 28153),
(150843, 'deDE', 'Ihr könnt die Ausbreitung des Sandes nicht verhindern!', 'Ihr könnt die Ausbreitung des Sandes nicht verhindern!', 28153),
(150842, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aDie Mine der Trockenstoppel ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aDie Mine der Trockenstoppel ist verloren!', 28153),
(150841, 'deDE', 'Hah! Die Rolle hat Euch nich\' gerettet, was?', '', 28153),
(150840, 'deDE', 'Wir herrschen über alles!', 'Wir herrschen über alles!', 28153),
(150839, 'deDE', 'Wir zertreten Euch wie ein Insekt!', 'Wir zertreten Euch wie ein Insekt!', 28153),
(150838, 'deDE', 'Totstell\'n geht anders, Mann.', '', 28153),
(150837, 'deDE', 'Für den Imperator!', 'Für den Imperator!', 28153),
(150836, 'deDE', 'Ich glaub, Ihr seid dem falsch\'n Licht gefolgt, Mann.', '', 28153),
(150835, 'deDE', 'Sieht aus, als hättet Ihr Euch verblinzelt, was?', '', 28153),
(150834, 'deDE', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aDer Axtkamm ist verloren!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aDer Axtkamm ist verloren!', 28153),
(150833, 'deDE', 'Ja! Ein Fürchterliches, aber auf jeden Fall anders!', '', 28153),
(150832, 'deDE', '', 'Also, das ist ja mal ein ganz anderes Aussehen.', 28153),
(150831, 'deDE', 'Ich glaube, das ist noch einer von diesen \"Helden\". Riecht, als hätte da jemand im Feuer gestanden!', '', 28153),
(150830, 'deDE', '', 'Was ist das denn für ein Gestank?!', 28153),
(150829, 'deDE', '', 'Waldorf, das ist kein Stacheleber. Das ist nur einer von diesen \"Helden\"!', 28153),
(150828, 'deDE', 'Haha, all die Rüstung hat Euch nix genützt, was?', '', 28153),
(150827, 'deDE', 'Hey, Stattler, gebt mir mein Schwert! Da kommt ein Stacheleber die Straße runter!', '', 28153),
(150826, 'deDE', 'Oooh, habt Ihr Euern kleinen Seelenstein verlor\'n, hm?', '', 28153),
(150825, 'deDE', '', 'Ja, sie taugen, um die Leute zu erschrecken!', 28153),
(150824, 'deDE', 'Schon mal auf die Klamotten von $n geachtet? Die taugen ja sogar was!', '', 28153),
(150823, 'deDE', 'Ah, Ihr wollt \'n bisschen Zeit mit Bwonsamdi verbring\'n?', '', 28153),
(150822, 'deDE', 'Haha! Das war mal \'n unterhaltsamer Abgang!', '', 28153),
(150821, 'deDE', 'Ich würde ja sagen, sieht ganz schön mitgenommen aus... Aber das ist bei solchen Leuten wohl ganz normal!', '', 28153),
(150820, 'deDE', '', 'Nun sieh sich mal einer an, was der Saurolisk angeschleppt hat! $n!', 28153),
(150819, 'deDE', '', 'Ja, wo dieses Set wohl herkommt?! Von einem Trogg?!', 28153),
(150818, 'deDE', 'Hey, Stattler, schaut Euch mal die Ausrüstung von $n an!', '', 28153),
(150817, 'deDE', 'Ich glaube schon! Junge, die stinkt ja noch mehr, als ich erwartet hätte! Haha!', '', 28153),
(150816, 'deDE', '', 'Hey, Waldorf! Ist das nicht diese \"Legende\", die Jaina angeschleppt hat?', 28153),
(150815, 'deDE', '', 'Ja! Ihr stinkt! Hahaha!', 28153),
(150814, 'deDE', 'Hey, Ihr da, $gder:die:r; $r mit dem Gesicht!', '', 28153),
(150813, 'deDE', 'Da hab ich ja schon Pferde mit besseren Transmogrifikationen gesehen!', '', 28153),
(150812, 'deDE', '', 'Hey, $n! Meint Ihr, der Helm passt zu den Stiefeln?', 28153),
(150811, 'deDE', 'Ich würde gerne noch etwas anderes wissen.', 'Ich würde gerne noch etwas anderes wissen.', 28153),
(150810, 'deDE', '', 'Die uralten Drust. Ihr Hass auf die Kul Tiraner überdauerte ihr sterbliches Dasein. Selbst aus dem Jenseits verfluchen sie noch unsere Existenz.\n\nIch habe Mitleid mit dem Narren, der sie heraufbeschworen hat.', 28153),
(150809, 'deDE', 'Die rachsüchtigen Toten?', 'Die rachsüchtigen Toten?', 28153),
(150808, 'deDE', 'Ihr werdet ausgelöscht!', '', 28153),
(150807, 'deDE', '', 'Diese Hexen verwenden uralte und zutiefst verderbte Magie. Sie haben die Wildtiere dazu gebracht, ihnen zu dienen, und damit das Gleichgewicht gestört. Ihre verderbten Kreaturen beherbergen die Geister der rachsüchtigen Toten.', 28153),
(150806, 'deDE', '', 'Die Jagd bereitet Freude un\' die Rache spendet Genugtuung.', 28153),
(150805, 'deDE', '', 'Die Loamörder woll\'n noch immer den Tempel von Rezan besudeln. Der alte K\'zlotec wird ihn\' zeig\'n, was passiert, wenn man dem Loa der Könige ins Gesicht spuckt.', 28153),
(150804, 'deDE', 'Naza bul rexil qalic ul\'.', '', 28153),
(150803, 'deDE', 'Was ist mit dem Wald geschehen?', 'Was ist mit dem Wald geschehen?', 28153),
(150802, 'deDE', 'Ca\' lish!', '', 28153),
(150801, 'deDE', '', 'Ihr findet ihn vielleicht in einer der Höhlen in der Nähe. Viel Glück, $n.', 28153),
(150800, 'deDE', '', 'Grünpirscher wurde geschwächt, aber es ist nur eine Frage der Zeit, bis er die Jagd wieder aufnimmt.', 28153),
(150799, 'deDE', 'Ug\' bwafa qilikx za!', '', 28153),
(150798, 'deDE', 'Ihr werdet in diesen Hallen stets willkommen sein.', '', 28153),
(150797, 'deDE', 'Armes kleines Ding, braucht Ihr Hilfe von Bwonsamdi?', '', 28153),
(150796, 'deDE', 'Die Ranishu haben meine Kinder vergiftet. Sie sind schwach und sterben. Rettet sie mithilfe meiner Macht, wie Ihr auch mich gerettet habt.', '', 28153),
(150795, 'deDE', 'Hul bala miz rilakich...', '', 28153),
(150794, 'deDE', 'Tsss, tsss. Ich hätt\' Euch nich\' so schnell zurückerwartet.', '', 28153),
(150793, 'deDE', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(150792, 'deDE', 'FÜR DIE HORDE!', 'FÜR DIE HORDE!', 28153),
(150791, 'deDE', 'Ich bin die Übermacht!', '', 28153),
(150790, 'deDE', 'Soldaten der Horde, greift zu den Waffen! Heute kämpfen wir gegen die Kaldorei!', '', 28153),
(150789, 'deDE', 'Lasst mich rat\'n... Ihr habt Euch übernomm\'?', '', 28153),
(150788, 'deDE', 'Il qul zerakish!', '', 28153),
(150787, 'deDE', 'Bei Euch sollte alles wieder in Ordnung sein. Reist zu Sylvanas in Orgrimmar, um mit Euren epischen Unternehmungen zu beginnen.', '', 28153),
(150786, 'deDE', 'Ich habe Nazmir gestartet, aber ich kann Zuldazar nicht starten. Bitte helft mir.', 'Ich habe Nazmir gestartet, aber ich kann Zuldazar nicht starten. Bitte helft mir.', 28153),
(150785, 'deDE', 'Was wollt Ihr?', '', 28153),
(150784, 'deDE', 'Es würde uns zum Vorteil gereichen, wenn sich daran nichts änderte.', '', 28153),
(150783, 'deDE', 'Haltet diese Kronsteigloyalisten in Schach und auf Euch wartet eine saftige Belohnung.', '', 28153),
(150781, 'deDE', 'Stellt Eure beste Crew zusammen und segelt zum Schiffskrämerkai. Von dort aus plündert und brandschatzt Ihr Euch durchs Land, stehlt Vorräte und füllt unsere Schatzkammern.', '', 28153),
(150779, 'deDE', 'Käpt\'n Bleifaust, unser Gönner hat mir geflüstert, dass Haus Kronsteig vor die Hunde geht.', '', 28153),
(150778, 'deDE', 'Warum seid Ihr nicht auf Eurem Posten?', 'Warum seid Ihr nicht auf Eurem Posten?', 28153),
(150777, 'deDE', 'Ich hätte gerne Kimbul als meinen Loa.', 'Ich hätte gerne Kimbul als meinen Loa.', 28153),
(150776, 'deDE', 'Das Herz von Azeroth selbst!', '', 28153),
(150775, 'deDE', '<Dieser Schrein wurde zu Ehren von Kimbul errichtet, dem Herrn aller Tiere.>', '<Dieser Schrein wurde zu Ehren von Kimbul errichtet, dem Herrn aller Tiere.>', 28153),
(150773, 'deDE', 'Jo?', 'Jo?', 28153),
(150772, 'deDE', 'Ich mag ihr Sprecher sein, doch Ihr seid ihr Champion. Und sie braucht Eure Hilfe in diesem Kampf.', '', 28153),
(150771, 'deDE', 'Azeroth ruft Euch! Sie bietet Euch ein Geschenk... geformt aus ihrer eigenen Essenz.', '', 28153),
(150770, 'deDE', 'Frei! Wir müss\'n in Sicherheit, in das Innere des Tempels!', 'Frei! Wir müss\'n in Sicherheit, in das Innere des Tempels!', 28153),
(150769, 'deDE', 'Was... Was is\' mit mir gescheh\'n?', 'Was... Was is\' mit mir gescheh\'n?', 28153),
(150768, 'deDE', '', 'G\'huun, gewährt mir Eure Macht!', 28153),
(150767, 'deDE', 'Ich schulde Euch was auf der Andren Seite.', 'Ich schulde Euch was auf der Andren Seite.', 28153),
(150766, 'deDE', '', 'Das Ende is\' nah.', 28153),
(150765, 'deDE', '', 'Fleht um Gnade!', 28153),
(150764, 'deDE', '', 'Alle werd\'n dem Meister dien\'.', 28153),
(150763, 'deDE', 'Endlich bin ich diese verflucht\'n Knochen los!', 'Endlich bin ich diese verflucht\'n Knochen los!', 28153),
(150762, 'deDE', 'Jetz\' isses an der Zeit, Harlan um seine Reichtümer zu erleichtern.', '', 28153),
(150761, 'deDE', 'Scheiben der Titanen aktiviert: Initiiere Chaosprotokoll', 'Scheiben der Titanen aktiviert: Initiiere Chaosprotokoll', 28153),
(150760, 'deDE', 'Ich geb\'s zurück! Ich schwör!', 'Ich geb\'s zurück! Ich schwör!', 28153),
(150759, 'deDE', 'So viel zu Harlan dem Schmierigen. Jetz\' steh\'n uns die Meere off\'n.', '', 28153),
(150758, 'deDE', 'Aaaah!', 'Aaaah!', 28153),
(150757, 'deDE', 'Ich hab das ehrlich geklaut!', 'Ich hab das ehrlich geklaut!', 28153),
(150756, 'deDE', 'Ha! Hab ich doch gewusst, dass Ihr \'ne sich\'re Wette seid!', '', 28153),
(150755, 'deDE', 'Weg hier!', 'Weg hier!', 28153),
(150754, 'deDE', 'Aah! Hilfe, ein Fremdling fasst mich an!', 'Aah! Hilfe, ein Fremdling fasst mich an!', 28153),
(150753, 'deDE', 'Lust, \'n paar Schädel einzuschlag\'n und dafür Gold zu kassier\'n?', '', 28153),
(150752, 'deDE', 'Die Insel is\' abgeriegelt, bis die Feierlichkeiten in der Kampfgrube vorbei sin\'.', '', 28153),
(150750, 'deDE', 'Das war gute Arbeit, aber mit Harlan dürfte das \'n bisschen schwieriger werd\'n.', '', 28153),
(150749, 'deDE', 'Mit \'ner Einladung wird das \'ne Ecke leichter. Wenn Ihr Euch holterdiepolter mit drei gefürchteten Piratenkäpt\'ns anlegt, wird\'s schwierig. Eure Entscheidung.', '', 28153),
(150748, 'deDE', 'Nich\' ma\' Fische trink\'n so viel wie die Bilgeratten. Haltet mit der Bande mit, dann will Euch Käpt\'n Eudora sicher beim Treff\'n seh\'n.', '', 28153),
(150747, 'deDE', 'Die Schwarzzahnvandalen mög\'n nix lieber als \'ne Klopperei. Verteilt \'n paar Zahnlücken, dann will Käpt\'n Raoul Euch sicher beim Treff\'n seh\'n.', '', 28153),
(150746, 'deDE', 'Hab gehört, die Kapitäne treff\'n sich. Wenn wir da reinkomm\', kömmer der Schlange alle Köppe gleichzeitich abschlag\'n.', '', 28153),
(150745, 'deDE', 'Dieser Krieg gewinnt sich nicht von alleine. Wir haben Arbeit zu erledigen!', '', 28153),
(150744, 'deDE', 'Danach kümmern wir uns um Harlan den Schmierigen.', '', 28153),
(150743, 'deDE', 'Hier is\' der Plan: Schwertwasser ablass\'n, Bilgeratten ersäuf\'n, Schwarzzähne ausschlag\'n un\' Eisenflut einschmelz\'n.', '', 28153),
(150742, 'deDE', 'Wenn er das schafft, gräbt seine Flotte uns aufm Meer das Wasser ab.', '', 28153),
(150741, 'deDE', 'Harlan benutzt die Eisenfluträuber, um die andren Piraten für sich zu gewinn\'.', '', 28153),
(150740, 'deDE', 'Danke, dass Ihr mich befreit habt. Im Innern des Tempels spür ich den Ruf von Bwonsamdi, also lasst uns geh\'n.', 'Danke, dass Ihr mich befreit habt. Im Innern des Tempels spür ich den Ruf von Bwonsamdi, also lasst uns geh\'n.', 28153),
(150739, 'deDE', 'Ich dacht, ich würd für immer \'n hässliches Skelett bleib\'n. Ich muss schnell zurück zum Tempel!', 'Ich dacht, ich würd für immer \'n hässliches Skelett bleib\'n. Ich muss schnell zurück zum Tempel!', 28153),
(150738, 'deDE', 'Schnell zurück zum... Tempel von Bwonsamdi...', 'Schnell zurück zum... Tempel von Bwonsamdi...', 28153),
(150737, 'deDE', 'Meine verbleibend\'n Sinne sin\' von dem grässlichen Ritual benomm\'n... Bitte helft mir zu den Tempelstufen.', 'Meine verbleibend\'n Sinne sin\' von dem grässlichen Ritual benomm\'n... Bitte helft mir zu den Tempelstufen.', 28153),
(150736, 'deDE', 'Danke, Mann! Ich werd schnell schwächer, also helft mir bitte zu Bwonsamdis Tempel.', 'Danke, Mann! Ich werd schnell schwächer, also helft mir bitte zu Bwonsamdis Tempel.', 28153),
(150735, 'deDE', 'Was habt Ihr da, Zastamann? \'n glitzerndes Kinkerlitzchen für Jani? Bringt\'s nur her...', '', 28153),
(150734, 'deDE', 'Ich bin der Einzige hier, der rechnen kann! Also behalte ich die Ausgaben im Auge und sorge dafür, dass sich niemand hier etwas einsteckt.', '', 28153),
(150733, 'deDE', 'Die Peons sind das Rückgrat dieses Krieges.', '', 28153),
(150732, 'deDE', 'Kommt heil wieder zurück.', '', 28153),
(150731, 'deDE', 'Hütet Euch vor den Bluttrollen.', '', 28153),
(150730, 'deDE', 'Passt ma\' auf Euch auf! Ich brauch Euch noch.', '', 28153),
(150729, 'deDE', 'Dunkle Zeit\'n in Zandalar.', '', 28153),
(150728, 'deDE', 'Bah, ich HASS Bluttrolle.', '', 28153),
(150727, 'deDE', 'Wie soll\'n wir das nur bewältig\'n?', '', 28153),
(150726, 'deDE', 'Pah! Die Horde hat bekommen, was sie verdient hat. Ich werde dieses Gerät nach Aroms Wehr bringen. Vielleicht hat dort jemand Verwendung dafür. Gute Arbeit.', '', 28153),
(150719, 'deDE', 'Ich bin bereit, Zandalar zu verteidigen.', 'Ich bin bereit, Zandalar zu verteidigen.', 28153),
(150718, 'deDE', 'Hier entlang! Unsere Bodentruppen warten da unten.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'deDE', '', 'Der Wald schreit in seiner Qual. Könnt Ihr es hören?', 28153),
(150716, 'deDE', 'Wir komm\'n nach Hause!', 'Wir komm\'n nach Hause!', 28153),
(150715, 'deDE', 'Habt mich wohl gar nich\' gebraucht! Wir sin\' so schnell wie möglich zurückgekomm\'!', '', 28153),
(150714, 'deDE', 'Derek und ich gehen schon unser Leben lang in diese Hügel. Wir können hier sehr viel länger überleben als die Horde.', '', 28153),
(150713, 'deDE', 'Wollt Ihr nach Zuldazar zurückgehen, um dort getötet zu werden, oder hierbleiben und Euch von einem Raptor töten lassen?', 'Wollt Ihr nach Zuldazar zurückgehen, um dort getötet zu werden, oder hierbleiben und Euch von einem Raptor töten lassen?', 28153),
(150712, 'deDE', 'Ich geh nich\' zurück nach Vol\'dun, klar? Ich will wieder in der Stadt leb\'n!', '', 28153),
(150711, 'deDE', '', 'Frische Schildkröten, Emma! Jetzt musst du mich dafür bezahlen!', 28153),
(150710, 'deDE', 'Was habt Ihr da, Zastamann? \'n glitzerndes Kinkerlitzchen für Jani? Bringt\'s nur her...', '', 28153),
(150709, 'deDE', '', 'Xul krass qi\' UN skush!', 28153),
(150708, 'deDE', '', 'Skitsh qi\'uthik illith!', 28153),
(150707, 'deDE', '', 'Das Blut tropft schon durch die Decke.', 28153),
(150706, 'deDE', '', 'Kommt doch mit mir in den Keller und bestaunt die Schönheit des Todes!', 28153),
(150705, 'deDE', '', 'Oje, Ihr scheint meinen ganzen Haushalt massakriert zu haben.', 28153),
(150704, 'deDE', '<Ihr seht das Bild eines jungen Trolls, der offenbar einen Leichenzug beobachtet. Mit seinen aufgerissenen Augen sieht er unschuldig aus.>', '<Ihr seht das Bild eines jungen Trolls, der offenbar einen Leichenzug beobachtet. Mit seinen aufgerissenen Augen sieht er unschuldig aus.>', 28153),
(150703, 'deDE', 'Bleibt weg vom Tor! Hier oben ist es gefährlich.', 'Bleibt weg vom Tor! Hier oben ist es gefährlich.', 28153),
(150702, 'deDE', 'Kua\'fon knurrt Euch an. Kehrt zu Raal zurück, oder Ihr werdet abgeworfen!', 'Kua\'fon knurrt Euch an. Kehrt zu Raal zurück, oder Ihr werdet abgeworfen!', 28153),
(150701, 'deDE', '', 'Suhlt Euch im Schmerz!', 28153),
(150700, 'deDE', '', 'Ich zerreiße Eure Seelen!', 28153),
(150699, 'deDE', '', 'Als ich das Ding benutzt habe, wurden meine Haare grün!', 28153),
(150698, 'deDE', '', 'Eure Schreie werden in der Ewigkeit hallen!', 28153),
(150697, 'deDE', '', 'Ich gebiete über alles und jeden!', 28153),
(150696, 'deDE', '', 'Kiro, sie leben noch! Wir können sie nicht einfach hier lassen...', 28153),
(150695, 'deDE', 'Schnell, nehmt, was Ihr könnt. Die Schlangen überlassen wir den Geiern.', '', 28153),
(150694, 'deDE', 'Ihr werdet in diesen Dünen sterben...', '', 28153),
(150693, 'deDE', 'Eindringlinge!', '', 28153),
(150692, 'deDE', 'Tut Ihr Euren Teil, General, und ich erledige meinen.', '', 28153),
(150691, 'deDE', 'Wir müss\'n schneller mach\'n. Der König hat neugierige Gäste... das könnt \'n Problem werd\'n.', '', 28153),
(150690, 'deDE', '', 'Es gab in Tol Dagor mal eine Wache, die sah genau wie Ihr aus.', 28153),
(150689, 'deDE', '', 'Könntet Ihr mich wohl in die Bank von Boralus reinschmuggeln?', 28153),
(150688, 'deDE', '', 'Habt Ihr Euch schon mal Sorgen wegen der Strahlung gemacht?', 28153),
(150687, 'deDE', '', 'Habt Ihr irgendwelche nützlichen Fähigkeiten? Könnt Ihr etwas fälschen oder Tresore knacken?', 28153),
(150686, 'deDE', '', 'Der Sturm ist gebrochen und ich bin wieder ich selbst. Ich danke Euch.', 28153),
(150685, 'deDE', '', 'Eure Leben waren bedeutungslos. Und im Tod werdet Ihr vergessen.', 28153),
(150684, 'deDE', '', 'Schänder!', 28153),
(150683, 'deDE', '', 'Helft mir und ich werde sie deaktivieren.', 28153),
(150682, 'deDE', '', 'Der Bann ist gebrochen, aber die Verteidigungssysteme des Tempels wurden aktiviert.', 28153),
(150681, 'deDE', '', 'Eure Qualen werden endlos sein!', 28153),
(150680, 'deDE', 'Ich werde genießen, wie Ihr verkokelt!', '', 28153),
(150679, 'deDE', 'Sterbt, Ungeziefer!', '', 28153),
(150678, 'deDE', 'Bogenschlitzer!', '', 28153),
(150677, 'deDE', 'Schnitt!', '', 28153),
(150676, 'deDE', 'Zu langsam!', '', 28153),
(150675, 'deDE', 'Zerschmettert wie Glas!', '', 28153),
(150674, 'deDE', 'Ich hab keine Angst oder so! Ich hab da nur gerade keine Lust zu!', '', 28153),
(150673, 'deDE', 'Nichts kann gegen unser Reich bestehen!', '', 28153),
(150672, 'deDE', 'Natürlich komme ich da hoch. Ich bin doch kein Weichei!', '', 28153),
(150671, 'deDE', 'Ich muss Euch gar nichts beweisen!', '', 28153),
(150670, 'deDE', 'Los schon, Abraham. Ich hab schon Kinder gesehen, die das geschafft haben.', '', 28153),
(150669, 'deDE', 'Kommt schon, so hoch ist das gar nicht.', '', 28153),
(150668, 'deDE', 'Ich wette, Ihr kommt da nicht hoch.', '', 28153),
(150667, 'deDE', 'Dasch ischt nischt witschig! Helft mir runter!', '', 28153),
(150666, 'deDE', 'Hört auf schu labern und helft mir runter!', '', 28153),
(150665, 'deDE', 'Helft mir einfach runter!', '', 28153),
(150664, 'deDE', 'Verschwindet, solange es noch geht!', 'Verschwindet, solange es noch geht!', 28153),
(150663, 'deDE', 'Die werden mich nicht kriegen!', 'Die werden mich nicht kriegen!', 28153),
(150662, 'deDE', 'Sie können meinen Anteil haben!', 'Sie können meinen Anteil haben!', 28153),
(150661, 'deDE', 'Wir werden alle Eisenfluträuber töten!', 'Wir werden alle Eisenfluträuber töten!', 28153),
(150660, 'deDE', 'Mich kriegen die nicht!', 'Mich kriegen die nicht!', 28153),
(150659, 'deDE', 'Ich arbeite nicht für Piraten!', 'Ich arbeite nicht für Piraten!', 28153),
(150658, 'deDE', '', 'Ich werde Euch den Kopf zermalmen!', 28153),
(150657, 'deDE', 'Schpasch beim Abhängen? Hahaha!', '', 28153),
(150656, 'deDE', 'Was ischt losch? Probleme da oben, Abraham?', '', 28153),
(150655, 'deDE', 'Hey, Idiot! Jetscht hängt Ihr da fescht, oder?!', '', 28153),
(150654, 'deDE', 'Sethraliss hat sich selbst geopfert, um unsere Welt zu retten. Wenn Mythrax zurückkehrt, war ihr Opfer womöglich umsonst...', '', 28153),
(150653, 'deDE', 'Selbst nach seinem Tod ist Mythrax\' Essenz hier noch stark. Es wäre nicht auszudenken, wenn er einmal mehr auferstehen würde...', '', 28153),
(150652, 'deDE', 'Es gibt hier eine dunkle Präsenz. Wir müssen wachsam sein...', '', 28153),
(150651, 'deDE', '', 'Jetzt werd\'n sie eines Tages ihre Bestimmung erfüll\'n könn\'.', 28153),
(150650, 'deDE', '', 'Diese Klein\' müss\'n auf die Probe gestellt werd\'n, damit sie ihr volles Potenzial entfalt\'n könn\'. Ermutigt sie, zur Halle der Kasten zurückzukehr\'n.', 28153),
(150649, 'deDE', 'Gut. Diese Tiere werden uns die Pfeile für unsere Jäger und das Futter für unsere Rüstungen stellen.', '', 28153),
(150648, 'deDE', 'Es ist nicht leicht, im Sumpf Nachschublinien einzurichten, und uns fehlen Materialien für unsere Truppen. Könnt Ihr für uns einige der heimischen Tiere erlegen?', '', 28153),
(150647, 'deDE', 'Ah, das ist perfekt. Jemand wie Ihr hat sich sicher nicht lange mit diesen glitschigen Biestern herumgeplagt, nicht wahr?', '', 28153),
(150646, 'deDE', 'Ein Schwarm Schwarznesseln? Das ist aber lieb, dass die gerade dann auftauchen, wenn mir die Tinte ausgeht. Nehmt diese Rolle und zieht damit die Tinte aus den Dingern.', '', 28153),
(150645, 'deDE', '', 'Diese Technologie scheint eine unglaublich nützliche Ergänzung unserer Streitkräfte zu sein. Gute Arbeit!', 28153),
(150644, 'deDE', '', 'Mekkadrill hat seine D.R.O.H.N.E.-Technologie verbessert und benötigt einen Feldtest, um ihre Fähigkeiten unter Beweis zu stellen. Wir haben gehört, dass sich in der Nähe viele Bluttrolle verstecken. Findet und vernichtet sie damit!', 28153),
(150643, 'deDE', '<Steigt auf!>', '<Steigt auf!>', 28153),
(150642, 'deDE', '<Kua\'fon dreht seinen Kopf, um Euch zu begutachten. Er begrüßt Euch mit einem schrillen Schrei.>\n\nSkriii!', '', 28153),
(150641, 'deDE', '', 'Dreckige kleine Monster.', 28153),
(150640, 'deDE', '', 'Ranishu haben mehrere Mägen, also wühlt weiter, wenn Ihr den ersten gefunden habt.', 28153),
(150639, 'deDE', 'Es wird \'n bisschen dauern, bis er zurück im Horst is\'... Er kann ja schließlich nich\' flieg\'n. Aber ich glaub, das wird schon.$b$bKommt später noch mal vorbei, dann is\' er bestimmt wieder da.', '', 28153),
(150638, 'deDE', 'Tja, ich hab\'s gerichtet. Übrigens gern gescheh\'n...$b$bMir is\' aufgefall\'n, dass er \'n bisschen einsam ausgeseh\'n hat. Vielleicht könnt Ihr ja noch ma\' \'ne Runde mit ihm dreh\'n! Die Bewegung tät ihm bestimmt gut.', '', 28153),
(150637, 'deDE', 'Was hat es mit dem Drachen auf sich?', 'Was hat es mit dem Drachen auf sich?', 28153),
(150636, 'deDE', '', 'Wir müss\'n sie einhol\'n. Los!', 28153),
(150635, 'deDE', '', 'Wir müss\'n Rakera schleunigst find\'n!', 28153),
(150634, 'deDE', 'Ich bin Euch weit voraus, Kenzou.', '', 28153),
(150633, 'deDE', 'Danke, $p. Ohne Euch hätten wir das nicht geschafft. Nehmt Euch Euren Anteil.', '', 28153),
(150632, 'deDE', 'Und jetzt, Tacha und Umi... jetzt schnappen wir uns hier alles, was wertvoll oder nützlich aussieht.', '', 28153),
(150631, 'deDE', 'Genug! Ihr habt Euch die Ehre verdient, durch meine Hand zu sterb\'n!', '', 28153),
(150630, 'deDE', 'Selbst der Tod kann unser Band nich\' brech\'n, meine Tierchen. Un\' jetz\', T\'zala... FRISS!', '', 28153),
(150629, 'deDE', 'Meiner Klinge hält keiner stand!', '', 28153),
(150628, 'deDE', 'Zeit für Blut!', '', 28153),
(150627, 'deDE', 'Ich zerhack Euer Fleisch!', '', 28153),
(150626, 'deDE', 'Kann es sein? Ja... endlich!', '', 28153),
(150625, 'deDE', 'Meine Legende wird Eure überdauern!', '', 28153),
(150624, 'deDE', 'Meine Krone is\' zu schwer für Euch!', '', 28153),
(150623, 'deDE', 'Darum bin ich der König... und Ihr Abschaum.', '', 28153),
(150622, 'deDE', 'Ihr werdet für die Entweihung von meinem Tempel bezahl\'n!', '', 28153),
(150621, 'deDE', 'Die Jagdsaison is\' eröffnet!', '', 28153),
(150620, 'deDE', 'Dafür gibt\'s kein Geg\'ngift!', '', 28153),
(150619, 'deDE', 'Die Elemente erhör\'n mein\' Ruf.', '', 28153),
(150618, 'deDE', 'Ich zeig Euch ma\' \'ne richtige Verhexung!', '', 28153),
(150617, 'deDE', '', 'Jetz\' gibt\'s Haue!', 28153),
(150616, 'deDE', '', 'Jetz\' sterbt Ihr!', 28153),
(150615, 'deDE', '', 'Wie schmeckt Euch die Axt?', 28153),
(150614, 'deDE', '', 'Wenn Ihr wisst, was gut für Euch ist, geht Ihr besser weiter.', 28153),
(150613, 'deDE', '', 'Machenwa jemanden ein\' Kopf kürzer.', 28153),
(150612, 'deDE', 'Bitte... bestattet mich... nich\'... bei diesen Depp\'n...', '', 28153),
(150611, 'deDE', '', 'Mein Kopf... is\' \'ne... hübsche Trophäe...', 28153),
(150610, 'deDE', '', 'Mein Zorn... lebt... weiter...', 28153),
(150609, 'deDE', 'Pst... Ich versuche hier, ein paar Schmetterlinge zu finden!', '', 28153),
(150608, 'deDE', '', 'Oh! Eure Köpfe geb\'n echt herrliche Deko ab.', 28153),
(150607, 'deDE', '', 'Ich hab schon größ\'re Insekt\'n als Euch zequetscht.', 28153),
(150606, 'deDE', 'Ein weit\'res Opfer vom Voodoo.', '', 28153),
(150605, 'deDE', '', 'Keiner überlebt mein\' Zorn.', 28153),
(150603, 'deDE', 'Ich nehme den Schatz!', 'Ich nehme den Schatz!', 28153),
(150602, 'deDE', 'Bringt die Stimmen zum Schweigen!', 'Bringt die Stimmen zum Schweigen!', 28153),
(150601, 'deDE', 'Dieser Schatz gehört mir!', 'Dieser Schatz gehört mir!', 28153),
(150599, 'deDE', '', 'Ha! Da hab ich Euch \'ne Last von den Schultern genomm\'.', 28153),
(150598, 'deDE', 'Ha! Ihr hättet meine Kräfte nich\' weck\'n soll\'n.', '', 28153),
(150597, 'deDE', '', 'Blut un\' Knochen.', 28153),
(150596, 'deDE', '', 'Ihr könnt nich\' entkomm\'.', 28153),
(150595, 'deDE', 'Hier kommt der Onkel Doktor.', '', 28153),
(150594, 'deDE', 'Macht den Leichnam bereit!', '', 28153),
(150593, 'deDE', 'Im Norden beginnen einige Eier aufzubrechen!', 'Im Norden beginnen einige Eier aufzubrechen!', 28153),
(150592, 'deDE', 'Ihr habt die Tot\'n gestört.', '', 28153),
(150591, 'deDE', 'Im Osten beginnen einige staubbedeckte Eier aufzubrechen!', 'Im Osten beginnen einige staubbedeckte Eier aufzubrechen!', 28153),
(150590, 'deDE', 'Im Westen beginnen einige giftbedeckte Eier aufzubrechen!', 'Im Westen beginnen einige giftbedeckte Eier aufzubrechen!', 28153),
(150589, 'deDE', 'Verhindert Infektionen. Entfernt das Gehirn!', '', 28153),
(150588, 'deDE', 'Der Blutfluch muss geläutert werd\'n.', '', 28153),
(150587, 'deDE', 'Die Tot\'n... müss\'n... bewahrt werden...', '', 28153),
(150586, 'deDE', '', 'Kaja und ich müss\'n weiter, um Jakra\'zet aufzuhalt\'n, bevor\'s zu spät is\'.', 28153),
(150585, 'deDE', 'Von der Seuche befreit.', '', 28153),
(150584, 'deDE', 'Werdet zu Staub!', '', 28153),
(150583, 'deDE', 'Ruhet in Fried\'n.', '', 28153),
(150582, 'deDE', 'Euer Blut is\' verflucht.', '', 28153),
(150581, 'deDE', 'Eure Körper sin\' befall\'n.', '', 28153),
(150580, 'deDE', '', 'Ächz... Mein Kopf... Was sin\' das für Dinger?', 28153),
(150574, 'deDE', 'Das werden wir ja sehen, elendes Biest!', '', 28153),
(150573, 'deDE', 'Der Sturm erwacht.', 'Der Sturm erwacht.', 28153),
(150572, 'deDE', 'Haut ab!', 'Haut ab!', 28153),
(150571, 'deDE', 'Klar, zeigt mir, was Ihr habt, Vali.', 'Klar, zeigt mir, was Ihr habt, Vali.', 28153),
(150570, 'deDE', 'Wozu braucht Ihr Münzen?', 'Wozu braucht Ihr Münzen?', 28153),
(150569, 'deDE', 'Die Hauerfratze, die immer hierherkommt, bietet beim Handeln immer Münzen an. $B$BVali glaubt daher, dass sie beim Handel außerhalb von Vol\'dun ziemlich wichtig sein müssen! $B$BWenn Vali Vol\'dun verlassen will, braucht Vali also Münzen.', '', 28153),
(150568, 'deDE', 'Wenn Ihr Münzen habt, hat Vali Waren für Euch!', '', 28153),
(150567, 'deDE', 'Hallöchen! Ja, Ihr da! Mir scheint, Ihr könntet etwas Wasser gebrauchen!', '', 28153),
(150566, 'deDE', '', 'Danke, Knüpp. Wenn das vorbei ist, sollten wir über eine Stelle als meine neue Hofdiplomatin sprechen.', 28153),
(150565, 'deDE', '', 'Ich vertraue Euch. Wenn Euch jemand zu nahe kommt, wird ein kleiner Schädelknacker das Problem lösen.', 28153),
(150564, 'deDE', 'Ich sollte zum Altar zurückkehren. Diese Essenz ist es wert, untersucht zu werden.', 'Ich sollte zum Altar zurückkehren. Diese Essenz ist es wert, untersucht zu werden.', 28153),
(150563, 'deDE', 'Habt Ihr was zu reparier\'n? Die Werkzeuge sin\' alt, aber ich kann trotzdem noch was damit anfang\'n.', 'Habt Ihr was zu reparier\'n? Die Werkzeuge sin\' alt, aber ich kann trotzdem noch was damit anfang\'n.', 28153),
(150562, 'deDE', 'Ich hätte gerne Akunda als meinen Loa.', 'Ich hätte gerne Akunda als meinen Loa.', 28153),
(150561, 'deDE', '<Dieser Schrein wurde zu Ehren von Akunda errichtet, dem Loa der Stürme.>', '<Dieser Schrein wurde zu Ehren von Akunda errichtet, dem Loa der Stürme.>', 28153),
(150560, 'deDE', '', 'Diese Anmaßung! Warte, bis dein Vater davon erfährt. Bis dahin vertraue ich dich der Obhut meiner Diener an.', 28153),
(150559, 'deDE', '', 'Wag es nicht, mich Tochter zu nennen, Hexe!', 28153),
(150558, 'deDE', '', 'Willkommen zu Hause, Tochter. Ich sehe, du bringst Gäste mit.', 28153),
(150557, 'deDE', 'AAAHHHHHH!', 'AAAHHHHHH!', 28153),
(150556, 'deDE', 'Seht Euch die Weberei genauer an.', 'Seht Euch die Weberei genauer an.', 28153),
(150555, 'deDE', 'Dieser Webstuhl und seine Erzeugnisse scheinen von der Magie des Zirkels erfüllt zu sein.', 'Dieser Webstuhl und seine Erzeugnisse scheinen von der Magie des Zirkels erfüllt zu sein.', 28153),
(150554, 'deDE', 'Nehmt die Flasche.', 'Nehmt die Flasche.', 28153),
(150553, 'deDE', 'Der Inhalt der Flasche ist zwar längst gekippt, aber ein erfahrener Koch könnte vielleicht noch etwas damit anfangen.', 'Der Inhalt der Flasche ist zwar längst gekippt, aber ein erfahrener Koch könnte vielleicht noch etwas damit anfangen.', 28153),
(150552, 'deDE', 'Ahhh! Was geht ab?! Hilfe!', '', 28153),
(150551, 'deDE', 'Zerstört die unreife Kapsel.', 'Zerstört die unreife Kapsel.', 28153),
(150550, 'deDE', 'Hier liegt eine inaktive verseuchte Kapsel. Jemand scheint sie für ruchlose Zwecke zu kultivieren.', 'Hier liegt eine inaktive verseuchte Kapsel. Jemand scheint sie für ruchlose Zwecke zu kultivieren.', 28153),
(150549, 'deDE', 'Nehmt die Karte an Euch.', 'Nehmt die Karte an Euch.', 28153),
(150548, 'deDE', 'Hier liegt eine zerschlissene Karte, auf der örtliche Jagdgebiete und die Standorte regionaler Lederhändler eingezeichnet sind.', 'Hier liegt eine zerschlissene Karte, auf der örtliche Jagdgebiete und die Standorte regionaler Lederhändler eingezeichnet sind.', 28153),
(150547, 'deDE', 'Wollt Ihr das auch wirklich tun?', 'Wollt Ihr das auch wirklich tun?', 28153),
(150546, 'deDE', 'Ihr... Ihr seid gerade in den TOPF gesprungen! Was hat Euch nur geritten?! Jetzt müssen wir von vorn anfangen!', '', 28153),
(150545, 'deDE', '', 'Der Weg is\' frei. Zu den Tor\'n, bevor die nächste Welle durchbricht!', 28153),
(150544, 'deDE', '', '$n wird Euch zur Hand gehen, Meister. Ich sehe nach, ob ich Bürgermeister Reinwald helfen kann.', 28153),
(150543, 'deDE', 'Lebendig kriegt Ihr mich nie!', 'Lebendig kriegt Ihr mich nie!', 28153),
(150542, 'deDE', '', 'Das erfreut mich außerordentlich, Meister Eschtal.', 28153),
(150541, 'deDE', 'Inquisitorin, es ist mir ein Privileg, Euch und Fräulein Luzilla in dieser Sache zu unterstützen.', '', 28153),
(150540, 'deDE', 'Faszinierend! Ein bemerkenswerter Ansatz! Höchst entzündlich!', '', 28153),
(150539, 'deDE', 'Fräulein Luzilla hält es für potenziell nützlich, nehme ich an? Nun gut, zeigt her!', '', 28153),
(150538, 'deDE', '', 'Sie hat ein Alchemierezept entdeckt, das sich in der Vergangenheit bewährt hat, und bittet Euch, die Formel zu rekonstruieren.', 28153),
(150537, 'deDE', '', 'Fräulein Luzilla hat den Glutorden neu gegründet. Mittels uralter Texte werden wir diese Hexen bekämpfen, wie wir einst die Drust bekämpft haben.', 28153),
(150536, 'deDE', '', 'Krax il\' oni OGOG!', 28153),
(150535, 'deDE', '', 'Ul tala kraza.', 28153),
(150534, 'deDE', '', 'Bwaxa za\' raga xil.', 28153),
(150533, 'deDE', '', 'Kryl!', 28153),
(150532, 'deDE', 'Offenkundig... aber warum mich?', '', 28153),
(150531, 'deDE', '', 'Bwixki amala zal qulllll...', 28153),
(150530, 'deDE', '', 'Aglathrax hig\' thrixa.', 28153),
(150529, 'deDE', '', 'Meister Eschtal! Fräulein Luzilla Kronsteig hat uns geschickt, Euch aufzusuchen.', 28153),
(150528, 'deDE', '', 'ULL vera skish!!', 28153),
(150527, 'deDE', 'Was für eine Chance hattet Ihr gegen meine Macht?', '', 28153),
(150526, 'deDE', 'Gereinigt!', '', 28153),
(150525, 'deDE', 'Geläutert!', '', 28153),
(150524, 'deDE', 'Die Gezeiten... fließen gegen mich...', '', 28153),
(150523, 'deDE', 'Ich kann es nicht erwarten, Euch persönlich zu ertränken!', '', 28153),
(150522, 'deDE', 'Ich dulde Eure Anmaßung keine Sekunde länger!', '', 28153),
(150521, 'deDE', 'Schwellt an, Ihr Wasser! Erhebt Euch und löscht diese Eindringlinge aus!', '', 28153),
(150520, 'deDE', 'Wagt es nicht, diesen heiligen Ort mit Eurer Anwesenheit zu schänden!', '', 28153),
(150519, 'deDE', 'Erfreut Euch an Eurem nassen Grab!', '', 28153),
(150518, 'deDE', '[DIE SZENE SCHILDERT, WIE JAKRA\'ZET UND SETHRAKIMPERATOR KORTHEK VON SETHRAK UMGEBEN SIND UND PLÄNE SCHMIEDEN, IN DIE PYRAMIDE EINZUBRECHEN. KORTHEK SCHIESST EUCH VOM HIMMEL.]', '', 28153),
(150517, 'deDE', 'Was will Azeroth von mir, Magni?', 'Was will Azeroth von mir, Magni?', 28153),
(150516, 'deDE', 'Ihr hättet an Land bleiben sollen!', '', 28153),
(150515, 'deDE', 'Überlasst mich... der See...', '', 28153),
(150514, 'deDE', 'Dafür versenke ich Euch in den Tiefen!', '', 28153),
(150513, 'deDE', 'NEIN!', '', 28153),
(150512, 'deDE', 'Die Flut wird Euch mit sich reißen!', '', 28153),
(150511, 'deDE', 'Keine Macht kann unser Band zerreißen.', '', 28153),
(150510, 'deDE', '', 'Gemeinsam, Geliebter, sind wir eine Naturgewalt.', 28153),
(150509, 'deDE', '', 'Vom Sturm geläutert!', 28153),
(150508, 'deDE', '', 'Weggeblasen!', 28153),
(150507, 'deDE', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s hat eine |cFFFF0000|Hcurrency:1559|hEssenz der Stürme|h|r erhalten!', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t%s hat eine |cFFFF0000|Hcurrency:1559|hEssenz der Stürme|h|r erhalten!', 28153),
(150506, 'deDE', '', 'Die Wolken... reißen auf...', 28153),
(150505, 'deDE', '', 'Der Wind wird das Fleisch von Euren Knochen reißen!', 28153),
(150504, 'deDE', '', 'Geliebter! Nein!', 28153),
(150503, 'deDE', 'Wenn das jemand überlebt, dann er. Ich sehe nach, was in den Laborgärten vorgeht, Inquisitorin.', '', 28153),
(150502, 'deDE', '', 'Niemand wird dem Sturm standhalten!', 28153),
(150501, 'deDE', '', 'Der Angriff in Falkenforst war heftig. Ich hoffe, Meister Eschtal ist noch am Leben.', 28153),
(150500, 'deDE', '', 'Priscilla reitet uns davon! Schnappt Euch eins der Rösser und verfolgt sie!', 28153),
(150499, 'deDE', 'Meister Eschtal, wir brauchen Eure Hilfe.', 'Meister Eschtal, wir brauchen Eure Hilfe.', 28153),
(150498, 'deDE', 'Recht herzlichen Dank! Ich mach mich jetzt dünne.', 'Recht herzlichen Dank! Ich mach mich jetzt dünne.', 28153),
(150497, 'deDE', 'Das vergesse ich Euch nie! Ich hau ab hier!', 'Das vergesse ich Euch nie! Ich hau ab hier!', 28153),
(150496, 'deDE', 'Ich hatte schon Angst, für immer hier festzusitzen... Hier, nehmt dies als Zeichen meiner Dankbarkeit!', 'Ich hatte schon Angst, für immer hier festzusitzen... Hier, nehmt dies als Zeichen meiner Dankbarkeit!', 28153),
(150495, 'deDE', 'Danke, dass Ihr mich befreit habt. Vielleicht wird dies Euch helfen.', 'Danke, dass Ihr mich befreit habt. Vielleicht wird dies Euch helfen.', 28153),
(150494, 'deDE', 'Ein Glück, dass Ihr mich gerettet habt! Ich werde Euch helfen, so gut ich kann.', 'Ein Glück, dass Ihr mich gerettet habt! Ich werde Euch helfen, so gut ich kann.', 28153),
(150493, 'deDE', 'Lasst mich nicht zurück!', 'Lasst mich nicht zurück!', 28153),
(150492, 'deDE', 'Lasst mich raus!', 'Lasst mich raus!', 28153),
(150491, 'deDE', '', 'Bitte, helft uns! Wenn Gorak Tul nicht gestoppt wird, umschlingt sein Übel ganz Azeroth.', 28153),
(150490, 'deDE', 'Hilfe!', 'Hilfe!', 28153),
(150489, 'deDE', 'Schnell, findet einen Weg, diese Zelle zu öffnen!', 'Schnell, findet einen Weg, diese Zelle zu öffnen!', 28153),
(150488, 'deDE', 'Lasst mich frei!', 'Lasst mich frei!', 28153),
(150487, 'deDE', 'Bitte helft mir!', 'Bitte helft mir!', 28153),
(150486, 'deDE', '\'n Saurid? Was macht der hier?', '', 28153),
(150485, 'deDE', '', 'Es ist nicht wichtig, wer das ist – wir brauchen Hilfe. Gorak Tul darf nicht in unsere Welt übertreten!', 28153),
(150484, 'deDE', '', 'Ganz ruhig, Meister Eschtal! Wir kommen in friedlicher Absicht!', 28153),
(150483, 'deDE', 'Wir sind zu spät! Wartet, wer seid Ihr?!', '', 28153),
(150482, 'deDE', 'Nun, Ihr seht beide recht gefährlich aus. Ähm, ist der Angriff also vorüber?', '', 28153),
(150480, 'deDE', 'Keinen Schritt näher! Ich beherrsche die Alchemie und weiß sie auch zu benutzen!', '', 28153),
(150479, 'deDE', 'Mit der Vernichtung von Lady Kronsteig habt Ihr ein Portal in Eure Welt geöffnet.', '', 28153),
(150478, 'deDE', 'Sterbliche, Euch fehlt Weitsicht. Den Tod hält niemand auf.', '', 28153),
(150477, 'deDE', '', 'Ihr habt meine Gastfreundschaft missbraucht. Nun werdet Ihr für immer hier bleiben!', 28153),
(150476, 'deDE', '', 'Wenn Ihr Euch erneut in meine Angelegenheiten einmischt, wird Euer Tod lang und abscheulich sein.', 28153),
(150475, 'deDE', '', 'Euren leeren Gesichtsausdrücken sehe ich an, dass man in Eurer Heimat wohl schon staunen würde über ein Haus, das nicht aus Dung besteht.', 28153),
(150474, 'deDE', '', 'Ihr müsst mir nicht antworten.', 28153),
(150473, 'deDE', '', 'Gehört es da, wo Ihr herkommt, zum feinen Ton, die Diener seines Gastgebers zu ermorden?', 28153),
(150472, 'deDE', 'Ich bin bereit. Suchen wir nach den anderen.', 'Ich bin bereit. Suchen wir nach den anderen.', 28153),
(150471, 'deDE', 'Wir dürfen keine Zeit verschwenden. Eure Freunde sind schon in Atul\'Aman...', '', 28153),
(150470, 'deDE', 'Kua\'fon kreischt vor Entrüstung und läuft davon.', '', 28153),
(150469, 'deDE', '', 'Kleines! Wenn du zum Nest zurückwillst, lauf jetzt besser.', 28153),
(150468, 'deDE', '', 'Doch zuerst weisen wir es mit einer Praxisübung ein.', 28153),
(150467, 'deDE', '', 'Euer Kleines traut seinen Flügeln noch nicht. Ihr müsst ihm weiter die Freuden der Lüfte zeigen.', 28153),
(150466, 'deDE', '', 'Warum benutzt du noch immer deine Beine?!', 28153),
(150465, 'deDE', '', 'Ihr seid beide noch am Leben. Gut. Wie ich sagte–', 28153),
(150464, 'deDE', '', 'Danke, Helden. Ihr habt den Zirkel zerschlagen und uns von Gorak Tuls Macht befreit. Wir stehen in Eurer Schuld.', 28153),
(150463, 'deDE', '', 'Seht Ihr, ein starker Arm und eine scharfe Klinge können jedes Problem lösen.', 28153),
(150462, 'deDE', 'Wir haben es geschafft! Gorak Tul ist verbannt.', '', 28153),
(150461, 'deDE', 'Angesichts des unausweichlichen Absturzes kreischt Kua\'fon um Hilfe!', 'Angesichts des unausweichlichen Absturzes kreischt Kua\'fon um Hilfe!', 28153),
(150460, 'deDE', 'Kommt, Sterbliche. Der Tod erwartet Euch.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'deDE', '', 'Hartwasser und ich halten sie hier auf. Ihr müsst das zu Ende bringen!', 28153),
(150458, 'deDE', '', 'Jeder Schrecken im Anwesen ist auf dem Weg zu uns!', 28153),
(150457, 'deDE', '', 'Gorak Tul darf unsere Welt nicht betreten!', 28153),
(150456, 'deDE', 'Der Drachen beginnt, heftig zu rucken. Kehrt dorthin zurück, wo ein sanfteres Lüftchen weht!', 'Der Drachen beginnt, heftig zu rucken. Kehrt dorthin zurück, wo ein sanfteres Lüftchen weht!', 28153),
(150455, 'deDE', '|TInterface\\ICONS\\INV_POTION_24:20|t Benutzt |cFFFF0404|Hspell:266198|h[Alchemistisches Feuer]|h|r, um die Leichen von todesberührten Sklaventreibern zu vernichten!', '', 28153),
(150454, 'deDE', 'Jetzt... wird Euer Alptraum erst beginnen.', '', 28153),
(150453, 'deDE', 'Lady Kronsteig war nur ein Gefäß meiner Macht. Mit ihrer Vernichtung habt Ihr ein Portal in Eure Welt geöffnet.', '', 28153),
(150452, 'deDE', 'Absorbieren', 'Absorbieren', 28153),
(150451, 'deDE', 'Naives Kind, Euch fehlt es an Vision. Der Tod ist eine unvermeidliche Kraft, die an jeder Ecke lauert.', '', 28153),
(150450, 'deDE', '', 'Endlich ist der Alptraum vorüber...', 28153),
(150448, 'deDE', 'Geht, mein Diener! Besorgt seine Mütze, dann lernt Euch Jani \'schätz\'n! Aber passt ja auf, dass Euch die hungrig\'n Raubtiere nich\' seh\'n...', '', 28153),
(150446, 'deDE', '', 'Ihr habt recht. Aber wie kann ich das Vertrauen meines Volkes zurückerlangen, wenn sie von den Grauen meiner Familie erfahren?', 28153),
(150445, 'deDE', '', 'Was jetzt zählt, ist, ihrer Grausamkeit ein Ende zu setzen.', 28153),
(150444, 'deDE', '', 'Meine Mutter hatte eine grausame Ader, aber ich hätte nie gedacht, dass sie hierzu fähig ist.', 28153),
(150443, 'deDE', 'Geht und findet Lady Kronsteig. Bringt sie zur Strecke.', '', 28153),
(150442, 'deDE', 'Heh! Kurzer Prozess.', '', 28153),
(150441, 'deDE', 'Sorgt dafür, dass Lady Kronsteig für ihre verderbte Hexerei bezahlt.', '', 28153),
(150440, 'deDE', 'Mit ihrer Befreiung habt Ihr diesen Seelen einen wahren Dienst erwiesen.', '', 28153),
(150439, 'deDE', 'Bleibt Lady Kronsteig auf den Fersen. Ich werde diese Räume sichern.', '', 28153),
(150438, 'deDE', 'Zu wissen, dass diese Kreaturen nicht länger nachts umherstreifen, lässt mich ruhiger schlafen.', '', 28153),
(150437, 'deDE', 'Wir untersuchen das Gelände, während Ihr Euch um die Diener kümmert. Waidmanns Heil.', '', 28153),
(150436, 'deDE', '', 'Helden, wir brauchen Eure Kraft. Wir müssen diesem Übel ein Ende setzen.', 28153),
(150435, 'deDE', 'Weglaufen erscheint mir nicht sehr schlau. Wir haben einen besseren Plan... oder?', '', 28153),
(150434, 'deDE', 'Knüpp!', '', 28153),
(150433, 'deDE', '', 'Kommt zurück und stellt Euch meinem Stahl!', 28153),
(150432, 'deDE', '', 'Wie Ihr wünscht, Herrin.', 28153),
(150431, 'deDE', '', 'Meine Damen, sorgt dafür, dass es unseren Besuchern an nichts fehlt.', 28153),
(150430, 'deDE', '', 'Mir scheint, wir haben ungeladene Gäste. Einerlei, ich bin sicher, wir können uns ihrer annehmen.', 28153),
(150429, 'deDE', 'Ihr steckt voller Überraschungen.', 'Ihr steckt voller Überraschungen.', 28153),
(150428, 'deDE', 'Saubere Arbeit, $R!', 'Saubere Arbeit, $p.', 28153),
(150427, 'deDE', 'Ich bin frei!', 'Ich bin frei!', 28153),
(150426, 'deDE', 'Ich bin Euch was schuldig!', 'Ich bin Euch was schuldig!', 28153),
(150425, 'deDE', 'Vielen Dank!', 'Vielen Dank!', 28153),
(150421, 'deDE', 'Ich gewähre Euch einen Teil meiner Macht, $p. Mein Schutz wird alle Treulosen in Eurem Weg auslöschen.', '', 28153),
(150420, 'deDE', 'Habt Ihr solche Angst, alter Freund, dass Ihr Euch versteckt, während Euer Volk leidet? Setzt dem ein Ende, Korthek!', '', 28153),
(150419, 'deDE', '$p, Ihr solltet Euch mit mir zusammentun. Ich werde ihn finden.', '$p, Ihr solltet Euch mit mir zusammentun. Ich werde ihn finden.', 28153),
(150418, 'deDE', '', 'Eine Lappalie! Wir werden uns neu formieren, dann gehört diese elende Stadt uns!', 28153),
(150417, 'deDE', 'Zuls Verrat hat schlimmere Folgen, als ich gedacht hätte. Mit seiner Rebellion hat er meine Armee praktisch aufgerieb\'n.\n\nJene, die mir noch immer treu ergeben sind, sterb\'n auf dem Schlachtfeld hinter mir durch die Hand der endlosen Schwärme einfallender Bluttrolle.\n\nIch hätte auf Talanji hör\'n soll\'n.', '', 28153),
(150416, 'deDE', 'Ich kenne da jemanden, der weiß, wo er ist.', 'Ich kenne da jemanden, der weiß, wo er ist.', 28153),
(150415, 'deDE', 'Ihr wisst, wo das Gold ist?', 'Ihr wisst, wo das Gold ist?', 28153),
(150414, 'deDE', 'Wenn Ihr den Schatz findet, könnten wir ihn uns teilen.', 'Wenn Ihr den Schatz findet, könnten wir ihn uns teilen.', 28153),
(150413, 'deDE', 'Ich hab gehört, die Eisenfluträuber hätten ihn schon gefunden.', 'Ich hab gehört, die Eisenfluträuber hätten ihn schon gefunden.', 28153),
(150412, 'deDE', 'He, so helft mir doch, den Schatz zu finden!', 'Hey, helft mal einem Mädchen, den Schatz zu finden!', 28153),
(150411, 'deDE', 'Der Kerl hat einen Freund, und der hat gehört, wie ein Eisenfluträuber gesagt hat, er wüsste, wo der Schatz ist.', 'Der Kerl hat einen Freund, und der hat gehört, wie ein Eisenfluträuber gesagt hat, er wüsste, wo der Schatz ist.', 28153),
(150410, 'deDE', 'Vielleicht sind diese Geschichten über Gold alle erstunken und erlogen.', 'Vielleicht sind diese Geschichten über Gold alle erstunken und erlogen.', 28153),
(150409, 'deDE', 'Wir müssen diesen Schatz finden, bevor die Eisenfluträuber hier einfallen.', 'Wir müssen diesen Schatz finden, bevor die Eisenfluträuber hier einfallen.', 28153),
(150408, 'deDE', '', 'Vielleicht hat jemand die Katze gefressen.', 28153),
(150407, 'deDE', '[PH] Fliegt nach Hause, stolzer Rakjani, und erzählt Eurem Vater, wer Euch befreit hat.', '', 28153),
(150406, 'deDE', '', 'Ich werd \'ne Besatzung zusammentrommeln und andere anheuern, um die Boote in der Nähe zu bemann\'. Viel Spaß, $n!', 28153),
(150405, 'deDE', 'Beeilt Euch! Setzt sie in Brand, bevor der Drustkönig sie wiederbelebt!', '', 28153),
(150404, 'deDE', 'Schnell! Verbrennt sie!', '', 28153),
(150403, 'deDE', 'Wir brauchen Unterstützung hier drüben!', '', 28153),
(150402, 'deDE', '$n! Wir werden überwältigt!', '', 28153),
(150401, 'deDE', 'Erliegt der Dunkelheit!', '', 28153),
(150400, 'deDE', 'Erhebt Euch!', '', 28153),
(150399, 'deDE', 'Niemand widersetzt sich mir!', '', 28153),
(150398, 'deDE', 'Ihr wart ein Nichts.', '', 28153),
(150397, 'deDE', 'Alles Leben endet.', '', 28153),
(150396, 'deDE', 'Der Tod... hält mich nicht auf...', '', 28153),
(150395, 'deDE', 'Der Tod macht vor niemandem halt!', '', 28153),
(150394, 'deDE', 'Niemand entkommt meiner Rache!', '', 28153),
(150393, 'deDE', 'Alle Bediensteten in die Küche!', '', 28153),
(150392, 'deDE', 'Weichgeklopft!', '', 28153),
(150391, 'deDE', 'Das wird ein FESTLICHES Mahl heute Abend...', '', 28153),
(150390, 'deDE', 'Welch... köstliche... Qual...', '', 28153),
(150388, 'deDE', '', 'Die Vulpera geben Euch Deckung, $p.\n\nSchickt alle Treulosen, die Euch Probleme machen, zu mir. Ich werde mich sehr gern um sie kümmern.', 28153),
(150387, 'deDE', 'Saftig!', '', 28153),
(150386, 'deDE', 'Frischfleisch!', '', 28153),
(150385, 'deDE', 'Köstlich!', '', 28153),
(150384, 'deDE', 'Bleibt zum Essen!', '', 28153),
(150383, 'deDE', 'Wer den Schatz findet, erhält den dreifachen Anteil!', '', 28153),
(150382, 'deDE', 'Wärt Ihr gern reich? Dann findet diesen Schatz für mich!', '', 28153),
(150381, 'deDE', 'Moxie, treibt diese Faulpelze zur Arbeit an!', '', 28153),
(150380, 'deDE', 'Stinkende Eisenfluträuber! Ihr werdet den Schatz niemals bekommen!', '', 28153),
(150379, 'deDE', 'Tötet den mit dem Piratenhut! Ja, genau den!', '', 28153),
(150378, 'deDE', 'Seht unter den Steinen nach! Seht überall nach!', '', 28153),
(150377, 'deDE', 'Erledigt diese Eisenfluträuber hier!', '', 28153),
(150376, 'deDE', '<Muh-Geräusch>', '', 28153),
(150375, 'deDE', '', '<Muh-Geräusch>', 28153),
(150374, 'deDE', '', 'Verzeiht mir...', 28153),
(150373, 'deDE', '', 'Ich bin die Matrone unnachgiebiger Tradition in tatkräftiger, endloser Recherche. Bezeichnung: M.U.T.T.E.R.', 28153),
(150372, 'deDE', '', 'Was auch immer Ihr hier treibt, ab heute ist damit Schluss!', 28153),
(150371, 'deDE', '', 'Wo ist das Geld?', 28153),
(150370, 'deDE', '', 'Ich weiß, dass Ihr hier etwas verbergt!', 28153),
(150369, 'deDE', '', 'Ihr werdet alle an der Werft zerbrechen.', 28153),
(150368, 'deDE', '', 'Ihr seid längst nicht so zäh, wie ich dachte.', 28153),
(150367, 'deDE', '', 'Ihr werdet diese Ketten bis zur Werft tragen!', 28153),
(150366, 'deDE', 'Grüße, Zastamann. Habt Ihr was Festes un\' Robustes zum Schrein der Aasfresser gebracht?', '', 28153),
(150365, 'deDE', 'Vergesst ihn! Ihr habt sowieso nichts von ihm, wenn Ihr tot seid!', 'Vergesst ihn! Ihr habt sowieso nichts von ihm, wenn Ihr tot seid!', 28153),
(150364, 'deDE', 'Ich lasse den Schatz nicht zurück. Er ist hier!', 'Ich lasse den Schatz nicht zurück. Er ist hier!', 28153),
(150363, 'deDE', 'Die Eisenfluträuber kommen! Wir müssen bald hier weg!', 'Die Eisenfluträuber kommen! Wir müssen bald hier weg!', 28153),
(150362, 'deDE', 'Grüße, Zastamann. Habt Ihr was Poliertes un\' Glattes zum Schrein der Aasfresser gebracht?', '', 28153),
(150361, 'deDE', 'Da wär\'n wir. Blauer Himmel, perfekt für \'nen Erkundungsgang.', '', 28153),
(150360, 'deDE', 'Das is\' kein normales Erdbeben! Irgendwo in der Nähe tritt Azerit aus.', '', 28153),
(150359, 'deDE', 'Das Ding läuft. Jetzt müsst\'n wir gleich alles Azerit seh\'n können.', '', 28153),
(150358, 'deDE', 'Vorsicht, Crew, da geht \'n Schiff von Kul Tiras vor Anka!', '', 28153),
(150357, 'deDE', 'Wie ungerecht, Ihr habt doch schon den letzten bekommen!', 'Wie ungerecht, Ihr habt doch schon den letzten bekommen!', 28153),
(150356, 'deDE', 'Hey, das gehört mir!', 'Hey, das gehört mir!', 28153),
(150355, 'deDE', 'Durchsucht seine Taschen!', 'Durchsucht seine Taschen!', 28153),
(150354, 'deDE', 'Schnappt Euch die Schlüssel!', 'Schnappt Euch die Schlüssel!', 28153),
(150353, 'deDE', 'Narr! Razgaji hat Euch in den Tod geschickt!', '', 28153),
(150352, 'deDE', '', 'Das dachte ich auch. $n, wärt Ihr so freundlich, unsere Theorie einem Feldtest zu unterziehen?', 28153),
(150351, 'deDE', 'Interessant. Die Irrwische erhören Malfurions Ruf. Aber was wäre, wenn noch mehr vom Wald um Hilfe ruft?', '', 28153),
(150350, 'deDE', '', 'Wir können sie nicht töten... jedenfalls nicht genug von ihnen. Aber vielleicht können wir sie verscheuchen.', 28153),
(150349, 'deDE', 'Niemand beklaut Tongo ungestraft!', '', 28153),
(150348, 'deDE', '', 'Die Späher, die ich auf Malfurion angesetzt habe, haben die Irrwische unterschätzt. Sie haben dafür gezahlt.', 28153),
(150347, 'deDE', 'Irrwische? Pah! Davon lassen sich unsere Dunklen Waldläuferinnen und Verwüster nicht aufhalten, Herrin.', '', 28153),
(150346, 'deDE', 'Ich gebe mich... nicht geschlagen...', '', 28153),
(150345, 'deDE', 'Noch ein Pterrordax, der zu schwach für die Treulosen ist!', '', 28153),
(150344, 'deDE', '', 'Schön, Euch zu sehen! Kommt, ruht Eure müden Glieder aus.', 28153),
(150343, 'deDE', '', 'Sagt nur Bescheid, wenn Ihr etwas braucht!', 28153),
(150342, 'deDE', '', 'Willkommen in meinem Gasthaus! Kommt, trinkt etwas.', 28153),
(150341, 'deDE', '', 'Geht es Euch gut, Schätzchen? Kommt rein, macht es Euch gemütlich.', 28153),
(150340, 'deDE', '', 'Ihr scheint eine Pause brauchen zu können. Setzt Euch und esst etwas!', 28153),
(150339, 'deDE', 'Grüße, Zastamann. Habt Ihr was Elektrisier\'ndes un\' Scharfes zum Schrein der Aasfresser gebracht?', '', 28153),
(150338, 'deDE', 'Das ganze Azerit gehört mir!', 'Das ganze Azerit gehört mir!', 28153),
(150337, 'deDE', '', 'Sagt mir, ob das wehtut...', 28153),
(150336, 'deDE', '', 'Boah! Ihr blutet ja echt viel!', 28153),
(150335, 'deDE', '', 'Käpt\'n! Das Dingsbums hat Feinde registriert. Zeit, meine guten Messerchen rauszuholen!', 28153),
(150334, 'deDE', '', 'Mehr Feuer... mehr Explosionen... Tz! Sklaventreiber!', 28153),
(150333, 'deDE', '', 'Es kann funktionieren UND explodieren. Das schließt sich nicht aus, wisst Ihr!', 28153),
(150332, 'deDE', '', 'Das wird... dem Käpt\'n... nicht gefallen...', 28153),
(150331, 'deDE', '', 'Euch stech ich ab!', 28153),
(150330, 'deDE', '', 'Überraschung!', 28153),
(150329, 'deDE', '', 'Zeit zum Abstechen!', 28153),
(150328, 'deDE', 'Das tut ein klein wenig weh!', '', 28153),
(150327, 'deDE', 'Ohhh, Ihr habt\'s ja faustdick hinter den Ohren!', '', 28153),
(150326, 'deDE', 'Aus Euch wird ein guter Köder!', '', 28153),
(150325, 'deDE', 'Was guckt Ihr so?', '', 28153),
(150324, 'deDE', 'Jetzt fütter ich... die Fische...', '', 28153),
(150323, 'deDE', 'Hm, auf dieser Insel ist nicht nur der übliche Pöbel. Vielleicht lohnt sich der Umweg ja doch.', '', 28153),
(150322, 'deDE', 'Kleine zuckende Würmer für meinen Haken!', '', 28153),
(150321, 'deDE', 'Macht Fischfutter aus ihnen!', '', 28153),
(150320, 'deDE', '...wird Sturm ernten!', '', 28153),
(150319, 'deDE', '', 'Schnell! Holt mir \'n Eimer! Hier wird kein Blut verschwendet!', 28153),
(150318, 'deDE', '', '\'ne Insel voll mit Kreaturen und Leuten und Sachen... und Horde. Los, bringt mir Blut!', 28153),
(150317, 'deDE', '', 'Na dann, Bukaniere! Bringt mir Blut... mein süßes, süßes Blut! Und für Euch fällt bestimmt Beute ab.', 28153),
(150316, 'deDE', '', 'Hordenblut... mein Lieblingsblut! Bukaniere, Ihr wisst was zu tun ist!', 28153),
(150315, 'deDE', '', 'Hallo. Sagt mal, braucht Ihr Euer ganzes Blut oder habt Ihr ein bisschen übrig...', 28153),
(150314, 'deDE', '', 'Das ganze Blut... vergeudet...', 28153),
(150313, 'deDE', '', 'Tötet sie schneller! ICH WILL BLUT!', 28153),
(150312, 'deDE', '', 'Jetzt wird geblutet!', 28153),
(150311, 'deDE', '', 'Macht keine Gefangenen!', 28153),
(150310, 'deDE', 'Ahh! Hahaha!', '', 28153),
(150309, 'deDE', 'Hehehehe!', '', 28153),
(150308, 'deDE', 'All...i...anz! Spielen wir \'ne Runde!', '', 28153),
(150307, 'deDE', 'HALLO!', '', 28153),
(150306, 'deDE', 'Heh... heh heh...', '', 28153),
(150305, 'deDE', 'Nicht weglaufen!', '', 28153),
(150304, 'deDE', 'Hier kommt Peter!', '', 28153),
(150303, 'deDE', 'Hier kommt Peter!', '', 28153),
(150302, 'deDE', 'Hier kommt Peter!', '', 28153),
(150301, 'deDE', 'Hört auf, das kitzelt!', '', 28153),
(150300, 'deDE', 'He, das kitzelt!', '', 28153),
(150299, 'deDE', 'Euch pust\' ich um!', '', 28153),
(150298, 'deDE', 'Ha! Erwischt!', '', 28153),
(150297, 'deDE', 'Lest die Runenschrift laut vor.', 'Lest die Runenschrift laut vor.', 28153),
(150295, 'deDE', 'Fliegt mich zum Goldenen Thron.', 'Fliegt mich zum Goldenen Thron.', 28153),
(150294, 'deDE', '', '$n, wir müssen die Kaldorei beschäftigen, während ich an einer Lösung für unser Irrwischproblem arbeite.', 28153),
(150293, 'deDE', '', 'Hmmm, die Irrwische haben sich zerstreut? Hervorragend. Unser Plan geht wohl auf...', 28153),
(150292, 'deDE', '', 'Mein Verwüster wird Euch in Stücke reißen! Ihr zögert das Unausweichliche nur hinaus!', 28153),
(150291, 'deDE', '', 'Akolythin, reißt diese Barrikade ein!', 28153),
(150290, 'deDE', '', 'Lauft, meine Hübschen! Reißt sie in Stücke!', 28153),
(150289, 'deDE', '', 'Champions, kommt mit. Werdet Zeugen des großen Finales.', 28153),
(150288, 'deDE', '', 'Oder vielleicht werdet Ihr Euren Sohn begrüßen können.', 28153),
(150287, 'deDE', '', 'Sterbt doch Euren Kriegertod, Hochfürst Saurfang. Mir ist es einerlei. Vielleicht werde ich Euren geschundenen Körper erwecken, damit Ihr mir erneut dient.', 28153),
(150286, 'deDE', '', 'Euch mag es egal sein, wenn die Euren sterben, solange es ehrenvoll ist. Aber die Horde ist es wert, gerettet zu werden. Wer dem nicht zustimmt, hat nicht verdient, hier zu stehen.', 28153),
(150285, 'deDE', '', 'Ehre bedeutet Leichen nichts, Saurfang. Ihr könnt es Euch erlauben, den Tod zu unterschätzen, aber ich bin mit ihm nur zu gut vertraut.', 28153),
(150284, 'deDE', 'Verlasst Euch auf Sylvanas\' Strategie, Theron.', '', 28153),
(150283, 'deDE', 'Die Leerenelfen... diese Verräter müssen bestraft werden!', '', 28153),
(150282, 'deDE', 'Lordaeron gehört den Verlassenen! Weicht keinen Zentimeter!', '', 28153),
(150281, 'deDE', 'Ihre Stärke wird bald nachlassen. Haltet stand!', '', 28153),
(150280, 'deDE', 'Die Allianz liegt in den letzten Zügen! Mehr als die Hälfte ihrer Soldaten sind am Boden.', '', 28153),
(150279, 'deDE', 'Hahaha! Seht nur, wer sich die Ehre gibt. Gut, jetzt bleibt der Kampf gewiss spannend.', '', 28153),
(150278, 'deDE', 'Das erklärt sie Euch besser selbst. Jetzt geht!', '', 28153),
(150277, 'deDE', 'Wie lange könnt Ihr die Allianz abwehren? Was ist die Strategie des Kriegshäuptlings?', '', 28153),
(150276, 'deDE', 'Nein. Lor\'themar und ich kümmern uns um die Angreifer. Es ist zu riskant, den Kriegshäuptling unbewacht zu lassen. Weicht nicht von ihrer Seite.', '', 28153),
(150275, 'deDE', 'Verstanden. Ich stoße so bald wie möglich zu Euch.', '', 28153),
(150274, 'deDE', 'Wir nutzen den Engpass am Ende des Seitenflügels aus, um sie zusammenzudrängen.', '', 28153),
(150273, 'deDE', 'Wir haben keine Zeit für Fragen! Wir verlieren unseren Geländevorteil in wenigen Minuten!', '', 28153),
(150272, 'deDE', 'Jawohl, Pestrufer. Aber wo ist Saurfang?', '', 28153),
(150271, 'deDE', 'Baine! Schickt die Katapulte und jeden verfügbaren Apotheker sofort zum hinteren Burghof!', '', 28153),
(150270, 'deDE', 'Mit Vergnügen, Pestrufer.', '', 28153),
(150269, 'deDE', 'Lor\'themar, befehligt unsere Waldläufer von der Flanke! Positioniert sie auf den Dächern!', '', 28153),
(150268, 'deDE', 'Die Seuchenkatapulte sind unsere vorderste Linie! Sie werden zwischen uns und dem Feind Seuchenwolken erschaffen!', '', 28153),
(150267, 'deDE', 'Ich gehorche, meine Königin.', '', 28153),
(150266, 'deDE', '', 'Trefft Euch mit Lor\'themar. Schnell! Enttäuscht mich nicht, Nathanos!', 28153),
(150265, 'deDE', 'Gasmasken! Holt Euch Eure Gasmasken! Und wenn Ihr ganz keck seid, könnt Ihr Euch so einen Rucksack greifen und an die Arbeit gehen!', '', 28153),
(150264, 'deDE', 'Verliert Eure Ehre nicht, Helden. Lok-narash!', '', 28153),
(150263, 'deDE', '', 'Tötet sie alle, Champions! Lasst Euch nicht täuschen: König Anduin und seine Armee sind nicht zum Spaß hier – sie sind hier, um uns auszulöschen! Zeigt keine Gnade, denn sie werden Euch keine gewähren!', 28153),
(150262, 'deDE', 'Soldaten der Horde! Eure Brüder und Schwestern liegen blutend auf dem Schlachtfeld! Dieser Sieg ist ehrlos, wenn wir unsere Kameraden zurücklassen!', '', 28153),
(150261, 'deDE', 'Lok\'tar ogar!', '', 28153),
(150260, 'deDE', 'Sie sind viele, aber wir sind stärker. Wir sind die Horde! Wer uns bedroht, wird vernichtet!', '', 28153),
(150259, 'deDE', 'Champions! Folgt dem Befehl Eures Kriegshäuptlings! Wir ziehen gegen die Allianz in den Kampf!', '', 28153),
(150258, 'deDE', '', 'Dann setzen wir dem jetzt endlich ein Ende. Saurfang, sammelt Eure Truppen. Ich bereite die Azeritmaschine vor.', 28153),
(150257, 'deDE', 'Ja, Kriegshäuptling.', '', 28153),
(150256, 'deDE', 'Beeilt Euch! Der Kriegshäuptling wartet!', '', 28153),
(150255, 'deDE', 'Zu mir, schnell! Wir müssen weiter vorrücken, bevor die Horde reagieren kann!', '', 28153),
(150254, 'deDE', 'Seine Winde sind stark, aber gemeinsam sind wir stärker! Haltet durch!', '', 28153),
(150253, 'deDE', 'Nich\' so schnell!', '', 28153),
(150252, 'deDE', '', 'Und zwar schnell! Meine Eisbarrieren halten nicht ewig!', 28153),
(150251, 'deDE', 'Helden! Um den Schamanen kümmern wir uns zum Schluss. Konzentriert Euch auf die restlichen Truppen!', '', 28153),
(150250, 'deDE', 'Der Kriegshäuptling... wird Euch... stopp\'n...', '', 28153),
(150249, 'deDE', 'Der Wind des Adlergeists wird EURE KNOCHEN SCHLEIFEN!', '', 28153),
(150248, 'deDE', '', '', 28153),
(150246, 'deDE', 'SKRII.', '', 28153),
(150245, 'deDE', 'SKRIIIII!', '', 28153),
(150244, 'deDE', 'SKRII!', '', 28153),
(150242, 'deDE', 'Das Buch ist voller verzauberter Runen, die über die Seiten huschen.', 'Das Buch ist voller verzauberter Runen, die über die Seiten huschen.', 28153),
(150241, 'deDE', 'Kann ich sie jetzt abmurksen? Ihr habt gesagt, ich darf sie abmurksen.', '', 28153),
(150240, 'deDE', 'WAS!?', '', 28153),
(150239, 'deDE', 'Sucht Euch selber eine Kiste, $ggieriger:gierige:r; $R!', 'Nein, die Kiste gehört mir!\n\nIch kam hierher, um nach Würmern für eine Suppe zu suchen. Manche Tortollaner behaupten ja, dass Kriecherfleisch das Suppenfleisch schlechthin sei, aber das halte ich für Unsinn. Kriechersuppe ist die Mühe nicht wert, wenn man durch eine Suppe mit einem Fremden Freundschaft schließen möchte.\n\nMit Schlammwurmsuppe kann man hingegen lebenslange Freundschaften aufbauen, und wir Tortollaner leben nun mal sehr lange.\n\nWenn Ihr mir etwas Schlammwurmfleisch findet, gebe ich Euch vielleicht diese Kiste.', 28153),
(150238, 'deDE', 'Das... tut weh...', '', 28153),
(150237, 'deDE', 'Graaaah!', '', 28153),
(150236, 'deDE', 'Bevor Ihr Eure Waffe zieht, hört mich bitte an...', '', 28153),
(150235, 'deDE', '', 'Durchsucht die Leiche nach Beute!', 28153),
(150234, 'deDE', '', 'Auf der Insel gibt\'s noch Schätze! Bringt sie an Bord, Ihr Faulpelze. Bewegt Euch! Und erleichtert auch die Allianz um ihre Beute.', 28153),
(150233, 'deDE', '', 'Hier treiben sich Allianzler rum – und sie atmen noch. Ändert das!', 28153),
(150232, 'deDE', '', 'Diese Insel plündert sich nicht von selbst. An die Arbeit!', 28153),
(150231, 'deDE', '', 'Was los?', 28153),
(150230, 'deDE', '', 'Keine... Gnade...', 28153),
(150229, 'deDE', '', 'Genug! Tötet sie, sofort!', 28153),
(150228, 'deDE', '', 'Tot lasst Ihr Euch besser durchsuchen.', 28153),
(150227, 'deDE', '', 'Ich hab Schlimmes über die Allianz gehört. Kommt denen besser nicht zu nah.', 28153),
(150226, 'deDE', '', 'Das wird helfen.', 28153),
(150225, 'deDE', '', 'Ich übernehme das.', 28153),
(150224, 'deDE', '', 'Grüße.', 28153),
(150223, 'deDE', '', 'Ich... hatte... Recht.', 28153),
(150222, 'deDE', '', 'Oh nein, sie sind hier.', 28153),
(150221, 'deDE', 'Ich sollte mich besser zurückziehen.', '', 28153),
(150220, 'deDE', 'Ich habe genug von Euch.', '', 28153),
(150219, 'deDE', 'Geht uns aus dem Weg, Allianzler, sonst muss ich Euch auslöschen.', '', 28153),
(150218, 'deDE', 'Seid gegrüßt.', '', 28153),
(150217, 'deDE', 'Kua\'fon schlingt sein Futter hinunter und verstreut überall die Reste.', '', 28153),
(150216, 'deDE', 'Das Licht... Ich werde... zurückkehren...', '', 28153),
(150215, 'deDE', 'Entfesselt Euren Zorn!', '', 28153),
(150214, 'deDE', 'Ich habe keine Zeit für so etwas!', '', 28153),
(150213, 'deDE', '', 'Ruhig Blut.', 28153),
(150212, 'deDE', '', 'Immer mit der Ruhe.', 28153),
(150211, 'deDE', '', 'Eure Zeit ist gekommen.', 28153),
(150210, 'deDE', '', 'Asche zu Asche.', 28153),
(150209, 'deDE', '', 'Die Winde haben uns und die Allianz hierher geführt. Manchmal überraschen mich die Elemente noch immer.', 28153),
(150208, 'deDE', '', 'Allianz, seid gewarnt: Lasst uns in Ruhe, dann lassen wir Euch in Ruhe.', 28153),
(150207, 'deDE', '', 'Die Elemente sind aus dem Gleichgewicht. Seht zu, ob wir helfen können, aber passt auf, dass die Allianz uns nicht in die Quere kommt.', 28153),
(150206, 'deDE', '', 'Was führt Euch hierher?', 28153),
(150205, 'deDE', '', 'Mein Geist... wird... zurückkehren...', 28153),
(150204, 'deDE', '', 'Mir geht die Geduld mit Euch aus!', 28153),
(150203, 'deDE', '', 'Elemente, steht uns zur Seite!', 28153),
(150202, 'deDE', '', 'Lasst mich helfen.', 28153),
(150201, 'deDE', '', 'Das Licht scheint auf Euch herab.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'deDE', '', 'Töten bereitet mir keine Freude.', 28153),
(150199, 'deDE', '', 'Vorsicht, unsere Feinde sind hier. Wir sollten sie falls möglich meiden.', 28153),
(150198, 'deDE', '<Bietet |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Dinofutter mit extragroßen Stückchen]|h|r an.>', '<Bietet |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Dinofutter mit extragroßen Stückchen]|h|r an.>', 28153),
(150197, 'deDE', '', 'Das Licht grüßt Euch.', 28153),
(150196, 'deDE', '', 'Ich gehe... ins Licht...', 28153),
(150195, 'deDE', '<Kua\'fon schnappt ungeduldig.>\n\nSKRII.', '', 28153),
(150194, 'deDE', '', 'Ergebt Euch und erspart Euch einen bedeutungslosen Tod!', 28153),
(150193, 'deDE', '<Kua\'fon schnüffelt an Euch.>\n\nSkrii.', '', 28153),
(150192, 'deDE', 'Wollt Ihr das ganz sicher tun? Dies hat keinen Einfluss auf die Handlung, außer dass Ihr damit prahlen könnt.', 'Wollt Ihr das ganz sicher tun? Dies hat keinen Einfluss auf die Handlung, außer dass Ihr damit prahlen könnt.', 28153),
(150191, 'deDE', 'Das ist ein mächtiger Feind!', '', 28153),
(150190, 'deDE', 'Das Licht hat über Euch gerichtet.', '', 28153),
(150189, 'deDE', 'Der Kriegshäuptling will also die Irrwische verscheuchen, was? Tja, dafür habe ich genau das Richtige.\n\nWollt Ihr dieses Ding fliegen? Oder wollt Ihr die Bomben abwerfen?', '', 28153),
(150188, 'deDE', 'Das Licht erstrahlt hell an diesem Ort. Hier ruht viel Azerit.', '', 28153),
(150187, 'deDE', '~Ich versuche immer noch, den Platz dafür zu finden. Womöglich müssen wir ein paar Bäume wegmachen oder ein Baummodell kreieren, das ich zum Leuchten bringen kann. \n\nTut einfach so, als sei es ganz toll gewesen und Irrwische seien aus der Barriere hervorgebrochen, um sichtbare Risse zu schaffen, wo Ihr getroffen habt.', '~Ich versuche immer noch, den Platz dafür zu finden. Womöglich müssen wir ein paar Bäume wegmachen oder ein Baummodell kreieren, das ich zum Leuchten bringen kann. Tut einfach so, als sei es ganz toll gewesen und Irrwische seien überall hervorgebrochen, um Risse in der Barriere zu hinterlassen.', 28153),
(150186, 'deDE', 'Fliegen wir los.', 'Fliegen wir los.', 28153),
(150185, 'deDE', 'Ich kann fliegen. Den Wald anzuzünden sagt mir weniger zu.', 'Ich kann fliegen. Den Wald anzuzünden sagt mir weniger zu.', 28153),
(150184, 'deDE', 'Möge das Licht mit Euch sein.', '', 28153),
(150183, 'deDE', 'Ihr habt... gut gekämpft...', '', 28153),
(150181, 'deDE', 'Licht, besiege meine Feinde!', '', 28153),
(150180, 'deDE', 'Für das Licht!', '', 28153),
(150179, 'deDE', '', 'Nicht so schnell.', 28153),
(150178, 'deDE', '', 'Bleibt zurück!', 28153),
(150177, 'deDE', '', 'Bereiten wir dem ein Ende!', 28153),
(150176, 'deDE', '', 'Wir haben triumphiert!', 28153),
(150175, 'deDE', '', 'Ein wahres Abenteuer! Eine einsame Insel mit unbekannten Gefahren und versteckten Schätzen. Moment, die Horde ist auch hier?', 28153),
(150174, 'deDE', '', 'Schauen wir, welche Abenteuer hier auf uns warten. Wir müssen nur die Horde beseitigen.', 28153),
(150173, 'deDE', '', 'Diener der Dunkelheit, Ihr werdet nicht siegen. Der Lichträcher wird Euch richten!', 28153),
(150172, 'deDE', '', 'Seid gegrüßt.', 28153),
(150171, 'deDE', '', 'Das Licht... wird mich erlösen...', 28153),
(150170, 'deDE', '', 'Ihr seid uns nicht gewachsen!', 28153),
(150169, 'deDE', '<Kua\'fon begrüßt Euch mit einem Krächzen.>\n\nSkrii!', '', 28153),
(150168, 'deDE', '<Kua\'fon bewegt seinen Kopf ruckartig in Eure Richtung.>', '', 28153),
(150166, 'deDE', '<Kua\'fon gluckst Euch verspielt an.>', '', 28153),
(150165, 'deDE', '', 'Verfüttert diese Seele an die Leere!', 28153),
(150164, 'deDE', '<Kua\'fon neigt seinen Kopf zur Seite, als Ihr Euch ihm nähert.>\n\nSkrii?', '', 28153),
(150163, 'deDE', '', 'FÜR DIE LEERE!', 28153),
(150162, 'deDE', '', 'Hier! Wir landen hier, wie die Stimmen es gesagt haben! Ja. Hahaha. Ja, ja, ja.', 28153),
(150161, 'deDE', '', 'Was? Wer hat das gesagt?', 28153),
(150160, 'deDE', '', 'Hehehehe... Die Leere nimmt mich auf...', 28153),
(150159, 'deDE', '', 'Labt Euch, meine Herzchen.', 28153),
(150158, 'deDE', '', 'Exquisite Seelen für die Leere!', 28153),
(150157, 'deDE', 'Spürt die Entropie!', '', 28153),
(150156, 'deDE', 'Erbärmlich.', '', 28153),
(150155, 'deDE', 'Diese Hordenbarbaren sind schon hier. Hmpf, als hätten sie eine Chance gegen die Leere.', '', 28153),
(150154, 'deDE', 'Kobolde und Katakomben!', 'Kobolde und Katakomben!', 28153),
(150153, 'deDE', 'Kobolde und Katakomben!', 'Kobolde und Katakomben!', 28153),
(150152, 'deDE', 'Reich wollt Ihr flieh\'n, doch sie lassen Euch nicht zieh\'n...', 'Reich wollt Ihr flieh\'n, doch sie lassen Euch nicht zieh\'n...', 28153),
(150151, 'deDE', 'schafft Ihr\'s mit heiler Haut hier wieder raus?', 'schafft Ihr\'s mit heiler Haut hier wieder raus?', 28153),
(150150, 'deDE', 'Leere, gib mir Kraft!', '', 28153),
(150149, 'deDE', 'Sie holen schon auf, beeilt Euch und lauft,', 'Sie holen schon auf, beeilt Euch und lauft,', 28153),
(150148, 'deDE', 'Sie werden immer mehr, sind Euch gleich hinterher, erwischt nur nicht den falschen Tunnel dabei!', 'Sie werden immer mehr, sind Euch gleich hinterher, erwischt nur nicht den falschen Tunnel dabei!', 28153),
(150147, 'deDE', 'Gebt Euch der Leere hin!', '', 28153),
(150146, 'deDE', 'Klaut Ihr die Kostbarkeit, verliert nur keine Zeit, Ihr flieht an den Fallen knapp vorbei!', 'Klaut Ihr die Kostbarkeit, verliert nur keine Zeit, Ihr flieht an den Fallen knapp vorbei!', 28153),
(150145, 'deDE', 'DU NICHT NEHMEN KERZE!', 'DU NICHT NEHMEN KERZE!', 28153),
(150144, 'deDE', 'DU NICHT NEHMEN KERZE!', 'DU NICHT NEHMEN KERZE!', 28153),
(150143, 'deDE', 'Reich seid Ihr im Nu, nur eines ist tabu...', 'Reich seid Ihr im Nu, nur eines ist tabu...', 28153),
(150142, 'deDE', 'Passt nur gut auf, dann findet Ihr Gold zuhauf, nehmt Euch all diese sagenhaften Schätze!', 'Passt nur gut auf, dann findet Ihr Gold zuhauf, nehmt Euch all diese sagenhaften Schätze!', 28153),
(150141, 'deDE', 'Viel Gold wartet zwar, doch auch viel Gefahr, und ein wenig baufällig wirkt\'s hier schon.', 'Viel Gold wartet zwar, doch auch viel Gefahr, und ein wenig baufällig wirkt\'s hier schon.', 28153),
(150140, 'deDE', 'Ich grüße Euch.', '', 28153),
(150139, 'deDE', 'Ihr geht auf Schatzexpedition.', 'Ihr geht auf Schatzexpedition.', 28153),
(150138, 'deDE', 'Ah... die Dunkelheit... nimmt mich auf...', '', 28153),
(150137, 'deDE', 'Was für eine erbärmliche Gruppe. Stellt Euch auf Eure Vernichtung ein.', '', 28153),
(150136, 'deDE', 'Versucht doch wenigstens, mitzuhalten.', '', 28153),
(150135, 'deDE', 'Die Reise geht los, die Aufregung groß...', 'Die Reise geht los, die Aufregung groß...', 28153),
(150134, 'deDE', 'Und die unzähligen Schätze, die würdige Abenteurer dort erwarten.', 'Und die unzähligen Schätze, die würdige Abenteurer dort erwarten.', 28153),
(150133, 'deDE', 'Soll ich schon mal meine Siegerpose einnehmen? Was, ich sollte sie zuerst töten? Hm, na gut.', '', 28153),
(150132, 'deDE', 'Legenden ranken sich um eine riesige Untergrundwelt...', 'Legenden ranken sich um eine riesige Untergrundwelt...', 28153),
(150131, 'deDE', 'Jawohl!', 'Jawohl!', 28153),
(150130, 'deDE', 'Ihr müsst so aufgeregt sein, mich zu sehen! Stellt Euch vor, wie Ihr Euch fühlt, wenn Ihr erst tot seid!', '', 28153),
(150129, 'deDE', 'Ein Hordenschiff! Ich kann nicht erwarten, ihre Gesichter zu sehen, wenn sie merken, dass wir hier sind.', '', 28153),
(150128, 'deDE', 'Würdet ihr Kleinen gern ein Lied singen?', 'Würdet ihr Kleinen gern ein Lied singen?', 28153),
(150127, 'deDE', 'Hihi!', 'Hihi!', 28153),
(150126, 'deDE', 'Willkommen!', '', 28153),
(150125, 'deDE', 'Haha!', 'Haha!', 28153),
(150124, 'deDE', 'Hier drüben!', '', 28153),
(150123, 'deDE', 'Was ist? Könnt Ihr nicht mithalten?', '', 28153),
(150122, 'deDE', 'Juhu!', 'Juhu!', 28153),
(150121, 'deDE', 'Packt sie!', 'Packt sie!', 28153),
(150120, 'deDE', 'Arg, das war doch eine Chance von eins zu einer Million...', '', 28153),
(150119, 'deDE', 'Oh weh!', 'Oh weh!', 28153),
(150118, 'deDE', 'Ich bin\'s! Keine Sorge, ich mach\'s kurz und schmerzlos.', '', 28153),
(150117, 'deDE', 'Hallo Horde, ich bin\'s, Kelain! Schön, Euch hier zu treffen.', '', 28153),
(150116, 'deDE', '', 'Verschwindet, Quälgeist!', 28153),
(150115, 'deDE', 'Wenn Ihr auf Grozztok trefft, könnt Ihr ihm gleich \'ne Klinge in sein dunkles Herz ramm\'n.', '', 28153),
(150114, 'deDE', '', 'Niederer Abschaum!', 28153),
(150113, 'deDE', '', 'Wie konntet Ihr mich vollbluten? Passt auf, wo Ihr hinspritzt!', 28153),
(150112, 'deDE', '', 'Oh, wie misslich... für Euch, Allianz. Wir zeigen Euch schon noch Euren Platz.', 28153),
(150111, 'deDE', 'Grozztok hat nix andres verdient. Ich hoff, Ihr habt ihn leid\'n lass\'n.', '', 28153),
(150110, 'deDE', '', 'Gute Güte! Wie schrecklich unschicklich.', 28153),
(150109, 'deDE', 'Ich werd\' in dies\'n Dünen sterb\'n... und ich verdien es auch nich\' anders.', '', 28153),
(150108, 'deDE', '', 'Tz, tz. Lasst mich mal sehen.', 28153),
(150107, 'deDE', '', 'Oh, Ihr seid es. Hallo.', 28153),
(150106, 'deDE', '', 'Wie überaus... unbefriedigend...', 28153),
(150105, 'deDE', '', 'Handschuhe an! Wir wollen uns ja nicht schmutzig machen.', 28153),
(150104, 'deDE', '', 'Hey, holen wir uns den Schwächling da!', 28153),
(150103, 'deDE', '', 'JAWOLL! Habt Ihr das gesehen?', 28153),
(150102, 'deDE', '', 'Kommt schon, runter vom Schiff. Wir verlieren Zeit! Los, los, LOS!', 28153),
(150101, 'deDE', '', 'Warum sitz ich hier fest, wenn ich da draußen kämpfen könnte?', 28153),
(150100, 'deDE', 'Wir haben die Schlüssel des Aufsehers. Jetzt können wir unser Ziel befreien, seine Fähigkeiten werden uns noch von Nutzen sein.', '', 28153),
(150099, 'deDE', '', 'Da müsst Ihr früher aufstehen.', 28153),
(150098, 'deDE', '', 'Zu langsam!', 28153),
(150097, 'deDE', 'Die Dunkle Fürstin wird erfreut sein.', '', 28153),
(150096, 'deDE', '', 'Nicht... fair! Ihr seid echt... fies...', 28153),
(150095, 'deDE', '', 'Alle Mann, Angriff!', 28153),
(150094, 'deDE', '', 'Vor mir gibt\'s kein Entkommen!', 28153),
(150093, 'deDE', 'Schnell, schaltet diesen Schwächling aus!', '', 28153),
(150092, 'deDE', 'Unausweichlich.', '', 28153),
(150091, 'deDE', 'Nehmt ihm die Schlüssel ab, befreit unser Ziel und streckt alles nieder, was Euch im Weg steht.', '', 28153),
(150090, 'deDE', 'Es ist Zeit, Euer Können auf die Probe zu stellen. Zeigt diesen Allianzhunden, was es heißt, Hochgeborener zu sein.', '', 28153),
(150089, 'deDE', 'Kämpft Euch vor bis in die obere Ebene und findet dort den Aufseher.', '', 28153),
(150088, 'deDE', 'Ein würdiger Feind erwartet uns. Und auch ein paar Allianzler.', '', 28153),
(150087, 'deDE', 'Ein Ausbruch hat vor kurzem in den unteren Ebenen des Gefängnisses für Chaos gesorgt. Das können wir nutzen.', '', 28153),
(150086, 'deDE', 'Die Allianz ist hier. Konzentriert Euch. Keine Fehler.', '', 28153),
(150085, 'deDE', 'Unser Ziel wird in Tol Dagor gefangen gehalten.', '', 28153),
(150084, 'deDE', 'Ich grüße Euch.', '', 28153),
(150083, 'deDE', 'Rück...zug...', '', 28153),
(150082, 'deDE', 'Zeigt, was Ihr gelernt habt! Angriff!', '', 28153),
(150081, 'deDE', 'Dem Feind entgegen, mir nach!', '', 28153),
(150080, 'deDE', 'Oh, oh, oh, Ziel priorisieren!', '', 28153),
(150079, 'deDE', 'Ich hab einen! Ich hab einen!', '', 28153),
(150078, 'deDE', 'Die Horde ist hier? Wollt Ihr das wirklich machen? Ich meine, meine Instrumente sind empfindlich und äußerst TEUER.', '', 28153),
(150077, 'deDE', 'Hallo!', '', 28153),
(150076, 'deDE', 'Ich... hatte... Recht, Leute...', '', 28153),
(150075, 'deDE', '$n ist vollständig aufgeladen!', '$n ist vollständig aufgeladen!', 28153),
(150074, 'deDE', '$n ist zum Bersten mit Energie gefüllt!', '$n ist zum Bersten mit Energie gefüllt!', 28153),
(150073, 'deDE', 'Weg mit Euch!', '', 28153),
(150072, 'deDE', 'Das Energieniveau von $n erhöht sich erneut...', 'Das Energieniveau von $n erhöht sich erneut...', 28153),
(150071, 'deDE', 'Oh, das... das sollten wir vielleicht besser lassen.', '', 28153),
(150070, 'deDE', 'Das Energieniveau von $n erhöht sich...', 'Das Energieniveau von $n erhöht sich...', 28153),
(150069, 'deDE', '', 'Sanitäter!', 28153),
(150068, 'deDE', 'Ein Chaosfunke stürmt auf das Schlachtfeld!', 'Ein Chaosfunke stürmt auf das Schlachtfeld!', 28153),
(150067, 'deDE', '', 'Ziel ausgeschaltet.', 28153),
(150066, 'deDE', 'In der Nähe bildet sich ein Energiekern.', 'In der Nähe bildet sich ein Energiekern.', 28153),
(150065, 'deDE', '', 'Durchladen und entsichern, Jungs. Die Horde ist hier. Erst schießen, dann plündern.', 28153),
(150064, 'deDE', '', 'Nehmt, was Ihr kriegen könnt.', 28153),
(150063, 'deDE', '', 'Ich ziehe mich zurück.', 28153),
(150062, 'deDE', 'Ein Wesen reiner Energie nimmt in der Luft vor Euch Gestalt an!', 'Ein Wesen reiner Energie nimmt in der Luft vor Euch Gestalt an!', 28153),
(150061, 'deDE', '', 'Uff... das tut weh...', 28153),
(150060, 'deDE', '', 'Der Feind bewegt sich.', 28153),
(150059, 'deDE', '', 'Zielt auf den Kopf, das ist ihre Schwachstelle!', 28153),
(150058, 'deDE', 'Zeit, ihnen ein Ende zu bereiten.', '', 28153),
(150057, 'deDE', 'Da habt Ihr ein Messer zu einer Mechschießerei mitgebracht.', '', 28153),
(150056, 'deDE', 'Sie haben meinen Roboschreiter zerstört! Rückzug!', '', 28153),
(150055, 'deDE', 'Roboschreiter zerstört! Muss schleunigst hier weg!', '', 28153),
(150054, 'deDE', 'Zerquetscht.', '', 28153),
(150053, 'deDE', 'Nur ein toter Hordler ist ein guter Hordler.', '', 28153),
(150052, 'deDE', 'Mit der Einstellung, dass Gewalt niemals etwas lösen kann, kommt man nicht weit. Reines Wunschdenken.', '', 28153),
(150051, 'deDE', 'Die Horde ist hier! Macht Eure Arbeit, sonst erschieß ich Euch persönlich. In Formation!', '', 28153),
(150050, 'deDE', 'Leistet Euren Beitrag!', '', 28153),
(150049, 'deDE', 'Deckung!', '', 28153),
(150048, 'deDE', 'Lasst mich... jetzt nicht im Stich...', '', 28153),
(150047, 'deDE', 'Aufwachen, wir haben Gesellschaft!', '', 28153),
(150046, 'deDE', 'SIE KOMMEN!', '', 28153),
(150044, 'deDE', 'Zeit für Heilung.', '', 28153),
(150043, 'deDE', 'Grabt schneller! Die Schätze müssen hier irgendwo sein!', 'Grabt schneller! Die Schätze müssen hier irgendwo sein!', 28153),
(150041, 'deDE', 'Zack!', '', 28153),
(150040, 'deDE', 'Hier warten \'n paar Feinde drauf, abgestochen zu werden. Los geht\'s, aber leise!', '', 28153),
(150039, 'deDE', 'Was wollt Ihr?', '', 28153),
(150038, 'deDE', 'Zu langsam!', '', 28153),
(150037, 'deDE', 'Ha... Ihr seid... nichts...', '', 28153),
(150036, 'deDE', 'Ich bin zu schnell für Euch, Allianzler.', '', 28153),
(150035, 'deDE', '', 'Unsere Leute ham Angst vor Veränderung\'n, wie Talanji sie verlangt. Und wenn sie Angst ham, mach\'n Leute dumme Sach\'n.', 28153),
(150034, 'deDE', '', 'Alle Kanonen, Feuer frei!', 28153),
(150033, 'deDE', '', 'Es wird mir zu bunt. Bevor ich Euch gewinnen lasse, verwandle ich Boralus zu Asche.', 28153),
(150032, 'deDE', '', 'Was habt Ihr meinem Tierchen angetan?', 28153),
(150031, 'deDE', '', 'Das ist unser nächstes Ziel.', 28153),
(150030, 'deDE', '', 'Genau nach Plan.', 28153),
(150029, 'deDE', '', 'Ich habe alles genau berechnet. Es ist ein guter Plan: kühn, aber äußerst effektiv. Jetzt führt ihn aus.', 28153),
(150028, 'deDE', '', 'Interessante Rüstung. Aber nicht genug Stacheln.', 28153),
(150027, 'deDE', '', 'Mein Plan ist... unfehlbar...', 28153),
(150026, 'deDE', '', 'Bzzzt!', 28153),
(150025, 'deDE', '', 'Für Kul Tiras!', 28153),
(150024, 'deDE', '', 'Ihr habt das nicht wirklich durchdacht, oder?', 28153),
(150023, 'deDE', 'Ich bin wieder im Geschäft!', '', 28153),
(150022, 'deDE', 'Jetzt wird geschreddert!', '', 28153),
(150021, 'deDE', 'Hey! Das Ding zu reparieren, ist echt teuer!', '', 28153),
(150020, 'deDE', '', 'Das Tor ist gefallen. Erstürmt die Stadt und tötet alle, die sich mir entgegenstellen.', 28153),
(150019, 'deDE', 'Verdammte Schrottmühle.', '', 28153),
(150018, 'deDE', 'Oh ja. Ka-tsching!', '', 28153),
(150017, 'deDE', 'Sieht sehr vielversprechend aus hier! Schattig, viel Beute... die Allianz? Soviel zum Thema \"vielversprechend\".', '', 28153),
(150016, 'deDE', 'Das ist \'ne günstige Gelegenheit, so sieht\'s aus. Die Überreste der Allianz könnt ich als Metallschrott verhökern.', '', 28153),
(150015, 'deDE', '', 'Soll ich es Euch mal demonstrieren?', 28153),
(150014, 'deDE', '', 'Genießt Euren belanglosen Sieg. Ohne die Flotte von Kul Tiras besiegt Ihr mich niemals.', 28153),
(150013, 'deDE', 'Riecht Ihr das? Riecht nach fetter Beute. Bereit machen zum Einsacken!', '', 28153),
(150012, 'deDE', 'Was geeeeht?', '', 28153),
(150011, 'deDE', 'So einfach... werdet Ihr... mich nicht los...', '', 28153),
(150010, 'deDE', '', 'Ihr habt es geschafft! Ohne ihren Riesen können Aschenwinds Streitkräfte die Stadt nicht halten!', 28153),
(150009, 'deDE', 'Dafür ist mein Baby gemacht!', '', 28153),
(150008, 'deDE', 'Bereit zum Metzeln!', '', 28153),
(150007, 'deDE', 'In den Kampf!', '', 28153),
(150006, 'deDE', 'Oh, ich hab mein Spielzeug kaputt gemacht.', '', 28153),
(150005, 'deDE', '<gähnt> Wir sind schon da? Aber das ist doch die beste Zeit für ein Nickerchen.', '', 28153),
(150004, 'deDE', 'Ich müsste das nicht ständig tun, wenn wir aufhören würden, zu kämpfen.', '', 28153),
(150003, 'deDE', 'Zeit, die Wunden zu lecken.', '', 28153),
(150002, 'deDE', 'Grrrrrr-üße.', '', 28153),
(150001, 'deDE', 'Endlich... Zeit für ein Nickerchen...', '', 28153),
(150000, 'deDE', 'Macht mal ein Nickerchen!', '', 28153),
(149999, 'deDE', '<lacht> Lauft doch, kleine Hordler! Wir jagen Euch nicht!', '', 28153),
(149998, 'deDE', '', 'Leichte Beute für die Meute!', 28153),
(149997, 'deDE', '', 'Ich brauche wohl ein neues Jagdziel!', 28153),
(149996, 'deDE', '', 'Aaaah... ein Hauch von Beute liegt in der Luft. Ich liebe eine gute Jagd!', 28153),
(149995, 'deDE', '', 'Ihr riecht komisch.', 28153),
(149994, 'deDE', '', 'Ah... der süße Duft... von Blut...', 28153),
(149993, 'deDE', '', 'Wartet kurz... Ihr seid gleich dran!', 28153),
(149992, 'deDE', '', 'Reißt ihnen die Kehlen raus!', 28153),
(149991, 'deDE', 'Gut gemacht, Champion! Dank Eurer Bemühungen ist das Land sicherer.', '', 28153),
(149990, 'deDE', 'Ich wittere Blut!', '', 28153),
(149989, 'deDE', 'Das wird ihn\' die Macht der Zandalari demonstrier\'n!', '', 28153),
(149988, 'deDE', 'Ich kann Eure Angst riechen.', '', 28153),
(149987, 'deDE', 'Na, DAS war ein Genuss!', '', 28153),
(149986, 'deDE', 'Hordler! Treiben wir sie in die Enge. Die Jagd beginnt! <jault>', '', 28153),
(149985, 'deDE', 'Unsere Spione haben in diesem Gebiet eine gefährliche Bedrohung ausgemacht. Findet und eliminiert sie!', '', 28153),
(149984, 'deDE', '<schnüffelt> Hordler. Ich wünschte, der Wind käme aus der anderen Richtung...', '', 28153),
(149983, 'deDE', '', 'Unwichtig. Meine Kanonen reißen meine Gegner schon bald in Stücke!', 28153),
(149982, 'deDE', 'Bleibt beim Rudel, ich will keine Streuner sehen! Irgendwas riecht hier faul.', '', 28153),
(149981, 'deDE', '<knurrt>', '', 28153),
(149980, 'deDE', 'Ein Alphatier... lässt sich nicht... unterkriegen...', '', 28153),
(149979, 'deDE', 'Diesen Frevel wird er bitter bereu\'n! Di chuka Rezan!', '', 28153),
(149978, 'deDE', 'Reißt sie in Stücke!', '', 28153),
(149977, 'deDE', '<jault> Wolfsrudel, Angriff!', '', 28153),
(149976, 'deDE', '', 'Ja! Sein Kopf gehört mir, hahaha!', 28153),
(149975, 'deDE', '', 'Ooooh, dieses Land is\' genau richtig! Aus\'m Weg, ich mach jetzt Voodoo!', 28153),
(149974, 'deDE', '', 'Ich heil Euch.', 28153),
(149973, 'deDE', '', 'Ihr habt \'n int\'ressantes Gesicht. Krieg ich Euren Kopf, wenn Ihr sterbt?', 28153),
(149972, 'deDE', '', 'Oh, aber die Dunkelspeere... sterb\'n nie...', 28153),
(149971, 'deDE', '', 'Hex hex, ha ha!', 28153),
(149970, 'deDE', '', 'Seid verdammt!', 28153),
(149969, 'deDE', '', 'Ihr da, Euch werd\' ich den Kopf schrumpf\'n!', 28153),
(149968, 'deDE', 'Schnappt Euch den hier.', '', 28153),
(149967, 'deDE', 'Hab ich Euch wohl erwischt.', '', 28153),
(149966, 'deDE', 'Nette Insel, mal seh\'n, was wir hier find\'n.', '', 28153),
(149965, 'deDE', 'Was geht \'n so?', '', 28153),
(149964, 'deDE', 'Ich leg\' mich... \'n Weilchen hin...', '', 28153),
(149963, 'deDE', 'Macht \'n Nickerchen!', '', 28153),
(149962, 'deDE', 'Wo komm\' die her? Was mach\'n die hier?', '', 28153),
(149961, 'deDE', '', 'RHAAAR!', 28153),
(149960, 'deDE', '', 'Mehr Blut!', 28153),
(149959, 'deDE', '', 'Mehr! Bringt mir mehr!', 28153),
(149958, 'deDE', '', 'Langsam vorrück\'n... Pah, tötet sie! Jetzt! Rhaaar!', 28153),
(149957, 'deDE', '', 'Allianzler! Schlachtet sie ab! Und bringt mir ihre Herz\'n...', 28153),
(149956, 'deDE', '', 'Zerfetzt sie, schlitzt sie auf! Ich will Blut seh\'n! Hahahaha!', 28153),
(149955, 'deDE', '', 'Was?', 28153),
(149954, 'deDE', '', 'Ich sterb... den Kriegertod! <spuckt>', 28153),
(149953, 'deDE', '', 'Reißt ihn\'n die Arme ab!', 28153),
(149952, 'deDE', 'Habt Ihr mich vermisst?', '', 28153),
(149951, 'deDE', 'Keine Bewegung!', '', 28153),
(149950, 'deDE', 'Oh, wen haben wir denn da?', '', 28153),
(149949, 'deDE', 'Nicht... schlecht...', '', 28153),
(149948, 'deDE', 'Noch ein Punkt für mich! Ich bin garantiert in Führung.', '', 28153),
(149947, 'deDE', 'Kommen wir zur Sache!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'deDE', 'Ihr werdet Euch erst ein neues Gesicht kaufen müssen.', 'Ihr werdet Euch erst ein neues Gesicht kaufen müssen.', 28153),
(149945, 'deDE', '', 'In Euren Augen erkenne ich Unsicherheit, $n.\n\nIch erlaube Euch, mich nach meinen Plänen zu fragen, wenn Ihr es wünscht.', 28153),
(149944, 'deDE', 'Kriegshäuptling, darf ich fragen, warum wir Teldrassil erobern sollen?', 'Kriegshäuptling, darf ich fragen, warum wir Teldrassil erobern sollen?', 28153),
(149943, 'deDE', 'Gelegenheit?', 'Gelegenheit?', 28153),
(149942, 'deDE', 'Das ist ungewiss, Kriegshäuptling.', 'Das ist ungewiss, Kriegshäuptling.', 28153),
(149940, 'deDE', '', 'Aber eines ist gewiss: Die Allianz wird Darnassus als sicheren Hafen nutzen, um Azerit in die Östlichen Königreiche zu schaffen. Anduin Wrynn wird mächtige neue Waffen bauen und früher oder später wird er sie auf unsere Heimatländer richten. Zuerst wird er Unterstadt und Silbermond angreifen, danach wird er seine Aufmerksamkeit Kalimdor zuwenden.\n\nWenn die Horde eine Zukunft haben soll, müssen wir ihm zuvorkommen.\n\nWenn Darnassus unser ist, kontrollieren wir den Azeritfluss und verhindern, dass das Azerit gegen uns verwendet wird. Die Allianz wird aus Angst vor zivilen Verlusten nicht wagen, ihre eigene Stadt anzugreifen.\n\nSo sichern wir mit einem Streich für Generationen den Frieden.', 28153),
(149939, 'deDE', '', 'Unsere Zeit ist knapp, aber ich respektiere, dass Ihr mehr wissen wollt.\n\n<Sylvanas zeigt auf der Karte auf Silithus.>\n\nDAS hat das Gleichgewicht der Kräfte in Azeroth für immer verändert.\n\nAzeritvorkommen erscheinen auf der ganzen Welt, $n. Wir kennen das volle Potenzial dieser Substanz noch nicht, doch sie birgt ganz klar ungeahnte zerstörerische Kräfte.\n\nWie werden Kriege in zwanzig Jahren geführt werden? In hundert?\n\nWie soll die Horde ihre Grenzen verteidigen, wenn die Allianz den Azeritfluss kontrolliert?', 28153),
(149938, 'deDE', '', 'Ihr wollt mich etwas fragen, $n?', 28153),
(149937, 'deDE', 'Die Treulosen haben ganz in der Nähe wilde Tiere eingepfercht. Das scheint mir die Gelegenheit zu sein.', '', 28153),
(149936, 'deDE', 'Ah, die Horde ist angekommen. Dann wird\'s hier gleich... interessant.', '', 28153),
(149935, 'deDE', 'Ihr könnt mir einfach nicht fernbleiben, was?', '', 28153),
(149934, 'deDE', 'Legt diesen Schwächling auf Eis, Jungs!', '', 28153),
(149933, 'deDE', 'Hallo, Schnuckelchen.', '', 28153),
(149932, 'deDE', 'Bis zum... nächsten Mal...', '', 28153),
(149931, 'deDE', 'Ha! Noch ein Punkt für mich!', '', 28153),
(149930, 'deDE', 'Diese Muckis lügen nicht.', '', 28153),
(149929, 'deDE', 'Allerdings bieten diese Waffen uns einen noch größeren Vorteil.', '', 28153),
(149928, 'deDE', 'Wie findet Ihr meine neuen Flügel? So schnell sind sie, dass kein Glitschi vor mir davonkommt!$b$bUnd kein Nappel.$b$b$b$bDreckige Nappel.', '', 28153),
(149927, 'deDE', 'Die Glitschis aus Zandalar sind seltsam. Verfiddelt salzig, und dann geben sie noch Widerworte.', '', 28153),
(149926, 'deDE', 'Die Horde! Endlich ist mal was los. Dafür zieh ich besser mein Hemd aus.', '', 28153),
(149925, 'deDE', 'Kua\'fon kreischt vor Freude und verschlingt das angebotene Futter.', '', 28153),
(149924, 'deDE', 'Kua\'fon beschnuppert das Futter, bevor er sich gierig darüber hermacht.', '', 28153),
(149923, 'deDE', 'Kua\'fon schnappt das Futter aus der Luft.', '', 28153),
(149922, 'deDE', 'Kua\'fon stürzt sich auf das angebotene Futter und verschlingt es in einem Stück.', '', 28153),
(149921, 'deDE', 'Die Geheimnisse der Welt sind unzählig... und ich behalte die Meinen für mich.', '', 28153),
(149920, 'deDE', 'Skrii?', '', 28153),
(149919, 'deDE', 'SKRIIII!', '', 28153),
(149918, 'deDE', 'Skrii!', '', 28153),
(149917, 'deDE', 'SKRII.', '', 28153),
(149916, 'deDE', 'Fliegende Ho-zen? Wie das?', 'Fliegende Ho-zen? Wie das?', 28153),
(149915, 'deDE', 'Zeit für einen strategischen Rückzug!', '', 28153),
(149914, 'deDE', 'Das hab ich gleich.', '', 28153),
(149913, 'deDE', 'Hallo. Wollt Ihr es mit den Besten aufnehmen?', '', 28153),
(149912, 'deDE', 'Wir haben nich\' sonderlich viele Vorräte, aber das ein oder andere kann ich schon entbehr\'n. Wenn Ihr uns helft, kann ich wohl auch dafür sorg\'n, dass \'n paar gute Sachen dabei sin\'.', 'Wir haben nich\' sonderlich viele Vorräte, aber das ein oder andere kann ich schon entbehr\'n. Wenn Ihr uns helft, kann ich wohl auch dafür sorg\'n, dass \'n paar gute Sachen dabei sin\'.', 28153),
(149911, 'deDE', '<Bietet |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Freilanddinofutter]|h|r an.>', '<Bietet |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Freilanddinofutter]|h|r an.>', 28153),
(149910, 'deDE', 'Wir haben den besten Platz ergattert. Der Schatz ist hier.', 'Wir haben den besten Platz ergattert. Der Schatz ist hier.', 28153),
(149909, 'deDE', 'Das ist... noch nicht... mein Ende...', '', 28153),
(149908, 'deDE', '<Kua\'fon sucht in Euren Händen nach Futter.>\n\nSkrii? SKRII.', '', 28153),
(149907, 'deDE', 'Fügt. Euch.', '', 28153),
(149906, 'deDE', 'Husch! Verschwindet, Ihr Hordeschufte!', '', 28153),
(149905, 'deDE', 'Wir spielen Euch an die Wand!', '', 28153),
(149904, 'deDE', 'Die Horde... ungewaschen, ungehobelt, unbelastet von der Bürde des Intellekts. Wie habt Ihr diese Insel überhaupt gefunden? Muss Zufall gewesen sein.', '', 28153),
(149903, 'deDE', 'Für Euch kann ich langsamer sprechen. Unsere... Insel. Ihr... verschwinden. War das einfach genug?', '', 28153),
(149902, 'deDE', 'Hordevandalen! Wir akzeptieren Eure Kapitulation, wenn Ihr uns sämtliches Azerit aushändigt. Ich hoffe, Euer Intellekt reicht aus, um meine Großzügigkeit zu erkennen.', '', 28153),
(149901, 'deDE', '', 'Ja? Kenne ich Euch?', 28153),
(149900, 'deDE', '', 'Gah! Zieht sich der ganze Allianzpöbel so an? Ihr solltet gehen... bevor Ihr an Scham sterbt!', 28153),
(149899, 'deDE', '', 'Das ist das Schiff der Allianz? Wurde es von Seemonstern angegriffen oder sieht es immer so aus?', 28153),
(149898, 'deDE', 'Ist es heiß hier oder bin ich das? Nur ein Witz... natürlich bin ich das!', '', 28153),
(149897, 'deDE', 'Geröstet!', '', 28153),
(149896, 'deDE', 'Heißer! Heißer!', '', 28153),
(149895, 'deDE', 'Heizen wir die Stimmung etwas auf!', '', 28153),
(149894, 'deDE', 'Ich sabotiere die oberen Kanonen und Ihr steckt die Schlucht in Brand. Trefft mich bei den Gehegen, wenn Ihr fertig seid!', '', 28153),
(149893, 'deDE', '', 'Gah! Kann ich Euch nicht töten, ohne Euch anzusehen?', 28153),
(149892, 'deDE', 'Versenkt Euren Gestank im Meer oder badet in meinen Flammen. Ihr habt die Wahl, Allianz!', '', 28153),
(149891, 'deDE', 'Uff! Was riecht hier so? Oh... die Allianz hat ihre \"Stärksten\" geschickt. Wisst Ihr, warum die so stinken? Weil sie die ganze Zeit Käse essen.', '', 28153),
(149890, 'deDE', 'Möge das Licht Euch segnen.', '', 28153),
(149889, 'deDE', 'Ihr habt gut gekämpft, doch ich war besser.', '', 28153),
(149888, 'deDE', 'Ich ziehe mich zurück.', '', 28153),
(149887, 'deDE', 'Spürt die Heilung des Lichts!', '', 28153),
(149886, 'deDE', 'Ahh, die Allianz. Dabei hat dieser Tag so gut angefangen... Geht besser, bevor Ihr mir die Laune verderbt.', '', 28153),
(149885, 'deDE', 'Diese Insel gehört uns, Allianz. Wenn Ihr sie verlasst, lässt sich Gewalt vermeiden.', '', 28153),
(149884, 'deDE', 'Auf in die Schlacht!', '', 28153),
(149883, 'deDE', '$n beginnt, \'Große Heilung\' zu wirken!', '$n beginnt, \'Große Heilung\' zu wirken!', 28153),
(149882, 'deDE', '', 'Findet einen oder macht einen. Wir haben keine Zeit zu verlieren.', 28153),
(149881, 'deDE', '', 'Das wäre geklärt. Saurfang, Nathanos – brecht sofort auf.', 28153),
(149880, 'deDE', 'Die meisten Schmuggler gehen dem Hochfürsten lieber aus dem Weg, aber ich bin sicher, wir finden jemanden, den wir überreden können.', '', 28153),
(149879, 'deDE', 'Ich bin nicht naiv. Die Ewige Warte bezieht sicher nicht alle Lieferungen auf legalem Weg. Jemand muss eine verborgene Route durch den Teufelswald nutzen.', '', 28153),
(149878, 'deDE', 'Wie bitte?', '', 28153),
(149877, 'deDE', 'Hm... Kennt Ihr viele Schmuggler, Pestrufer?', '', 28153),
(149876, 'deDE', '', 'Wir nehmen Malfurion von beiden Seiten in die Zange.', 28153),
(149875, 'deDE', '', 'Saurfang, führt ein paar Soldaten in den Teufelswald. Findet einen Weg durchs Gebirge zur Dunkelküste, aber überlasst mir die Belagerungswaffen.', 28153),
(149874, 'deDE', '', 'Die Irrwische lassen sich ablenken. Diese Schwäche nutzen wir, um an ihnen vorbeizugelangen.', 28153),
(149873, 'deDE', 'Kriegshäuptling, es gibt keinen sicheren Weg durch den Teufelswald.', '', 28153),
(149872, 'deDE', '', 'Zuldazar: eine der wenigen Städte, die die Zerschlagung überlebt haben und immer noch gedeihen. In seiner Blütezeit regierte das Zandalariimperium über die halbe Welt. In Suramar warnen wir unsere Kinder noch immer vor den Trollen und ihren finsteren Machenschaften.\n\nWir sahen sie als blutrünstige Wilde. Aber wenn man sich das hier anschaut... Nun, man fragt sich, wer hier von wem abhängig ist: die Zandalari von der Horde oder umgekehrt.', 28153),
(149871, 'deDE', '', 'Der Zorn der Vulpera erhebt sich aus den Sanden und fordert Rache. Und ich hole sie mir!', 28153),
(149870, 'deDE', '', 'Der Tod kommt Euch holen, Ihr Treulosen.', 28153),
(149869, 'deDE', '', 'Nach Zoram\'gar, schnell!', 28153),
(149868, 'deDE', 'Die Zeremonie kann beginnen.', 'Die Zeremonie kann beginnen.', 28153),
(149867, 'deDE', 'Nun, das ist mir jetzt etwas peinlich...\n\nIhr müsst wissen, dass ich mir meine Rede in meinem Notizbuch aufgeschrieben habe, das ich nun aber wohl... verlegt haben muss.\n\nEs muss irgendwo in diesem Raum sein. Wenn Ihr mir bei der Suche helfen könntet, wäre ich Euch auf ewig dankbar!', '', 28153),
(149866, 'deDE', 'Oh, hallo. Wir kennen uns leider noch nicht persönlich, aber ich möchte Euch dafür danken, dass Ihr für meine liebe Luzilla da seid.\n\nWie kann ich Euch helfen?', '', 28153),
(149865, 'deDE', 'Keine Sorge, Vaza wird sich in Nazmir um Euch kümmern!', '', 28153),
(149864, 'deDE', 'Luzilla konnte nicht ahnen, dass ich sie jedes Mal besuche, wann immer sie zur Fahlhainkapelle kommt. \n\nVermutlich kann sie meinen Geist nicht sehen, weil ihre Verzweiflung wegen der Geschehnisse, die sich hier ereigneten, einfach zu groß ist. Ich kann nur hoffen, dass ein Teil von ihr weiß, dass ich hier bin.', '', 28153),
(149858, 'deDE', 'Jetzt müsst Ihr Euch ihnen anschließen. Sethraliss vergebe Euch.', '', 28153),
(149857, 'deDE', 'WIR HABEN EINE RAUFEREI!', 'WIR HABEN EINE RAUFEREI!', 28153),
(149856, 'deDE', 'Kua\'fon verschlingt den Fisch.', '', 28153),
(149855, 'deDE', 'Kua\'fon beschnuppert vorsichtig den angebotenen Fisch.', '', 28153),
(149854, 'deDE', '<Bietet ihm etwas Schimmerflossenfleisch an.>', '<Bietet ihm etwas Schimmerflossenfleisch an.>', 28153),
(149853, 'deDE', '<Kua\'fon duckt sich ängstlich und schreckt zurück, als Ihr Euch nähert.>$b$bVielleicht lässt sich das Junge ja überzeugen. Mit einem kleinen Leckerli, vielleicht?', '', 28153),
(149852, 'deDE', 'Immer...', '', 28153),
(149851, 'deDE', 'Ich werde immer hier sein, liebste Luzilla...', '', 28153),
(149850, 'deDE', '', 'Ach, Alexander... Ich wünschte, du könntest jetzt hier sein...', 28153),
(149849, 'deDE', 'Habt Dank.', '', 28153),
(149848, 'deDE', 'Endlich... kann ich nun die Erinnerungen an diesen Ort zurücklassen.', '', 28153),
(149847, 'deDE', 'Nein, alter Freund. Unser Volk ist tot, und es ist Eure Schuld.', '', 28153),
(149846, 'deDE', 'Ich habe niemanden gezwungen, mir zu folgen... Wir sind ein Volk von Eroberern...', '', 28153),
(149845, 'deDE', 'Ihr werdet bereuen... dass Ihr das gesehen habt...', 'Ihr werdet bereuen... was Ihr gesehen habt...', 28153),
(149844, 'deDE', 'Lady Kronsteig ist ein mächtiger Feind...', 'Lady Kronsteig ist ein mächtiger Feind...', 28153),
(149843, 'deDE', '', 'Das will ich auch hoffen!', 28153),
(149842, 'deDE', 'Keine Sorge, ich kümmere mich um diese Ratte.', 'Keine Sorge, ich kümmere mich um diese Ratte.', 28153),
(149841, 'deDE', '', 'Idiot! Keine Zeugen!', 28153),
(149840, 'deDE', 'Wir haben wohl Besuch...', 'Wir haben wohl Besuch...', 28153),
(149839, 'deDE', 'Immer ein Vergnügen, mit Euch Geschäfte zu machen, Mylady.', 'Immer ein Vergnügen, mit Euch Geschäfte zu machen, Mylady.', 28153),
(149838, 'deDE', '', 'Hier ist Euer Geld, elender Gauner. Nehmt es, bevor Euch jemand sieht!', 28153),
(149837, 'deDE', 'Ein Hinterhalt! Luzilla, hinter mich! Wachen, zu den Waffen!', '', 28153),
(149836, 'deDE', '', 'Alexander, nein!', 28153),
(149835, 'deDE', 'Nichts Persönliches, Kleiner.', 'Nichts Persönliches, Kleiner.', 28153),
(149834, 'deDE', 'Alexander, habt Ihr Euer Gelüb– Was war das?!', '', 28153),
(149833, 'deDE', 'Als Herrscher über Drustvar – und Luzillas stolzer Vater – ist es mir eine Ehre, diese beiden Liebenden vor dem Land, dem Himmel und der See zu trauen.', '', 28153),
(149832, 'deDE', 'Werte Freunde, Familie und Gäste. Wir versammeln uns an diesem prächtigen Tag, um Luzillas und Alexanders Vermählung zu feiern.', '', 28153),
(149831, 'deDE', 'Nun gut.', '', 28153),
(149830, 'deDE', '', 'Natürlich, Vater. Bitte.', 28153),
(149829, 'deDE', 'Wollen wir?', '', 28153),
(149828, 'deDE', 'Sie ist bald hier. Sie hat mich gebeten, an ihrer Stelle zu beginnen.', '', 28153),
(149827, 'deDE', '', 'Ist schon in Ordnung, Vater. Wo ist Mutter?', 28153),
(149826, 'deDE', 'Bitte entschuldigt meine Verspätung.', '', 28153),
(149825, 'deDE', 'Aber wo ist Lady Kronsteig?', '', 28153),
(149824, 'deDE', '', 'Da kommt er!', 28153),
(149823, 'deDE', 'Oh, und entschuldigt mich bitte bei den Gästen.', '', 28153),
(149822, 'deDE', 'Bitte gebt dem glücklichen Paar Bescheid, dass ich in Kürze dort bin.', '', 28153),
(149821, 'deDE', 'Oh, Ihr habt es gefunden! Den Gezeiten sei Dank!', '', 28153),
(149820, 'deDE', '', 'Wollt Ihr absichtlich unsere Zeit verschwenden?', 28153),
(149819, 'deDE', '', 'Wir suchen ein Buch. Glaubt Ihr wirklich, wir hätten nicht schon im Bücherregal nachgesehen?', 28153),
(149818, 'deDE', '', 'Warum sollte mein Gatte sein Notizbuch in Luzillas Tasche legen? Seid Ihr nicht bei Trost?', 28153),
(149817, 'deDE', 'Unwahrscheinlich, dass Ihr bei Luzillas Briefen fündig werdet, aber ein kurzer Blick schadet wohl nicht.', '', 28153),
(149816, 'deDE', 'Für Eure Hilfe bin ich zutiefst dankbar, aber ich muss doch sehr bitten, die Unterwäsche meiner Tochter nicht zu durchwühlen...', '', 28153),
(149815, 'deDE', '', 'Aber ihr Herz tut unserem Haus keinen Gefallen...', 28153),
(149814, 'deDE', 'Luzilla folgt nur ihrem Herzen, Margarete. Genau wie ich, als ich dich zur Frau nahm.', '', 28153),
(149813, 'deDE', '', 'Aber Arthur, das kannst du doch nicht zulassen. Soll unsere Tochter wirklich einen gewöhnlichen Händler heiraten?!', 28153),
(149812, 'deDE', '', 'Vielen Dank für Euer Kommen. Wir fühlen uns geehrt, dass Ihr hier seid.', 28153),
(149811, 'deDE', 'Warum seid Ihr hierhergekommen?', '', 28153),
(149810, 'deDE', 'Luzilla? Du bist hier... Moment, Ihr seid nicht Luzilla.', '', 28153),
(149809, 'deDE', 'Ihr auch nich\'. Euerm Vater missfällt, dass Ihr diese Kreatur\'n hierhergebracht habt. Ich soll Euch umgehend zu ihm bring\'n.', '', 28153),
(149807, 'deDE', 'Mir den Sieg gesichert, ganz gleich, was hier geschieht. General Jakra\'zet hat meinen Schlüssel bereits... und mittlerweile bestimmt auch Eure.', '', 28153),
(149806, 'deDE', 'Korthek, was habt Ihr getan?', '', 28153),
(149805, 'deDE', 'Ich frage mich, Vorrik, wenn Ihr hier seid, wer bewacht dann die Schlüssel im Tempel?', '', 28153),
(149804, 'deDE', '', '[PH] Ich lebe, um mein Volk zu verteidigen. Und diese Hände niederer Geburt werden Euch ein Ende setzen!', 28153),
(149803, 'deDE', '[PH] Niedere Vulpera, Ihr lebt nur, um meinem Imperium zu dienen!', '', 28153),
(149802, 'deDE', '', '', 28153),
(149801, 'deDE', 'Ich werde mir neue Zähne machen lassen, und zwar ganz aus Gold!', 'Ich werde mir neue Zähne machen lassen, und zwar ganz aus Gold!', 28153),
(149800, 'deDE', 'Wir werden Mythrax\' Gefängnis versiegelt halten und ich werde unser Volk einen.', '', 28153),
(149799, 'deDE', 'Wir machen die ganze Arbeit, also sollten wir auch das ganze Gold bekommen.', 'Wir machen die ganze Arbeit, also sollten wir auch das ganze Gold bekommen.', 28153),
(149798, 'deDE', 'Nein. Ihr seid unser Versagen. Sethraliss hatte sich für den Frieden geopfert.', '', 28153),
(149797, 'deDE', 'ICH bin die wahre Macht der Sethrak!', '', 28153),
(149796, 'deDE', 'Soll bloß keiner versuchen, mich um meinen Anteil zu bringen.', 'Soll bloß keiner versuchen, mich um meinen Anteil zu bringen.', 28153),
(149795, 'deDE', 'Wenn ich den Schatz finde, brenne ich damit durch!', 'Wenn ich den Schatz finde, brenne ich damit durch!', 28153),
(149794, 'deDE', 'Der Finder kriegt einen zusätzlichen Anteil!', 'Der Finder kriegt einen zusätzlichen Anteil!', 28153),
(149793, 'deDE', 'Drei Millionen in Goldmünzen! Wir werden reich sein!', 'Drei Millionen in Goldmünzen! Wir werden reich sein!', 28153),
(149792, 'deDE', 'Vielleicht graben wir ja an der falschen Stelle?', 'Vielleicht graben wir ja an der falschen Stelle?', 28153),
(149791, 'deDE', 'Ich werde mir ein Schloss samt heißem Bad und Dienern kaufen.', 'Ich werde mir ein Schloss samt heißem Bad und Dienern kaufen.', 28153),
(149790, 'deDE', 'Nante sagt, wir sind ganz nah dran. Es wird nicht mehr lange dauern.', 'Nante sagt, wir sind ganz nah dran. Es wird nicht mehr lange dauern.', 28153),
(149789, 'deDE', 'Ich werde mir ein Schiff kaufen, das größer ist als alle in der Flotte!', 'Ich werde mir ein Schiff kaufen, das größer ist als alle in der Flotte!', 28153),
(149788, 'deDE', 'Wie viel ist der 267. Teil von drei Millionen?', 'Wie viel ist der 267. Teil von drei Millionen?', 28153),
(149787, 'deDE', 'Es ist so viel, dass mich Jaina Prachtmeer heiraten wird, um an mein Geld zu kommen!', 'Es ist so viel, dass mich Jaina Prachtmeer heiraten wird, um an mein Geld zu kommen!', 28153),
(149786, 'deDE', '', '... Tja, das kommt manchmal auch vor.', 28153),
(149785, 'deDE', '', 'Wie schön ist es, zum ersten Mal den Wind unter den Flügeln zu spüren, die Freude am Flie–', 28153),
(149784, 'deDE', '', 'Ah... wieder folgt eines dem Ruf des Himmels!', 28153),
(149783, 'deDE', 'Kehrt bald wieder. Wir müssen Imperator Korthek umgehend angreifen.', '', 28153),
(149782, 'deDE', 'Ich bereite hier unseren Angriff vor, während Ihr unter den Treulosen Chaos sät.', '', 28153),
(149781, 'deDE', '<Stupst das Jungtier aus dem Nest.>', '<Stupst das Jungtier aus dem Nest.>', 28153),
(149779, 'deDE', '[Client-Szene: Taelia tritt vor, um Lady Aschenwind als Drahtzieherin des Angriffs zu beschuldigen. \"Erkennt Ihr es nicht, Katherine? Euch zu ersetzen, war von jeher ihr Plan.\" Katherine wendet sich Priscilla zu. \"Ist das wahr?\" Priscilla hört jäh auf, die Sanftmütige und Verständnisvolle zu spielen. Sie geht hart mit Katherine ins Gericht: \"Schwach! Unfähig zu herrschen! Aschenwind hat diese Stadt AUFGEBAUT!\" Sie zieht ihre Pistole und schießt auf Katherine. Die Wachen reagieren blitzschnell. Priscilla schießt auf die Fässer auf einem Wagen in der Nähe der Menge und erzeugt eine Rauchwand, die sich schnell über den Platz ausbreitet. Chaos bricht aus.]', '[Client-Szene: Taelia tritt vor, um Lady Aschenwind als Drahtzieherin des Angriffs zu beschuldigen. \"Erkennt Ihr es nicht, Katherine? Euch zu ersetzen, war von jeher ihr Plan.\" Katherine wendet sich Priscilla zu. \"Ist das wahr?\" Priscilla hört jäh auf, die Sanftmütige und Verständnisvolle zu spielen. Sie geht hart mit Katherine ins Gericht: \"Schwach! Unfähig zu herrschen! Aschenwind hat diese Stadt AUFGEBAUT!\" Sie zieht ihre Pistole und schießt auf Katherine. Die Wachen reagieren blitzschnell. Priscilla schießt auf die Fässer auf einem Wagen in der Nähe der Menge und erzeugt eine Rauchwand, die sich schnell über den Platz ausbreitet. Chaos bricht aus.]', 28153),
(149778, 'deDE', 'Vorrik, ich bin bereit, Imperator Korthek entgegenzutreten.', 'Vorrik, ich bin bereit, Imperator Korthek entgegenzutreten.', 28153),
(149777, 'deDE', '', 'Meine Beute... Neiiiiin...', 28153),
(149776, 'deDE', 'Zerschmettert dieses unglückselige Schiff und befreit unser Volk!', '', 28153),
(149775, 'deDE', '', 'Schöne Waffe habt Ihr da, die is\' bloß noch mehr Beute für mich!', 28153),
(149774, 'deDE', 'Gewaltige Stürme der See, hört meinen Ruf!', '', 28153),
(149772, 'deDE', '[PH] Beeindruckend, \"alter Freund\". Aber das wird nicht reichen, um mich aufzuhalten!', '', 28153),
(149771, 'deDE', '[PH] Der Schlüssel ist tief in meiner Festung versteckt, Vorrik. Oder dachtet Ihr, ich wäre närrisch genug, ihn bei mir zu tragen?', '', 28153),
(149770, 'deDE', '[PH] In einem habt Ihr jedoch recht. Die Zeit zum Reden ist vorbei!', '', 28153),
(149769, 'deDE', '[PH] Genug Gerede, alter Freund. Übergebt Euren Schlüssel zu Mythrax\' Gefängnis. Ihr werdet unser aller Untergang sein!', '', 28153),
(149768, 'deDE', 'Ihr erblickt der Macht von Korthek, dem Ewigen Imperator!', '', 28153),
(149767, 'deDE', '[PH] Es ist vollbracht. Nun kann ich die Macht dieser Spitze nutzen. Rasch, zum Tor!', '', 28153),
(149766, 'deDE', '', 'Heiliges Sandkorn, bin ich froh, Euch zu sehen! Ich habe mich etwas übernommen...', 28153),
(149765, 'deDE', '', 'Kiro im Auge zu behalten, ist kein Leichtes. Er ist immer in Bewegung, immer dem nächsten großen Plan auf der Spur.\n\nEr ist mit Nisha fortgegangen, aber als ich das letzte Mal von ihm hörte, war er auf dem Weg in die Schlucht, um Vorräte zu stehlen oder die Kanonen zu sabotieren oder so etwas in der Art.', 28153),
(149764, 'deDE', '', 'Nisha ist dabei, im Sklavenlager für Ärger zu sorgen. Geht aus dieser Höhle Richtung Westen und nehmt die erste Rampe nach unten zu Eurer Rechten.\n\nHaltet im Zweifelsfall nach dem Lärm sterbender Sethrak die Ohren offen und geht ihm nach. Sie wird ganz in der Nähe sein.', 28153),
(149763, 'deDE', '', 'Oh, das ist das Beste daran! Ihr habt sie wahrscheinlich auf Eurem Weg herein nicht einmal gesehen, oder?\n\nRaffinierte Vulpera verstecken sich überall entlang der Fluchtroute und halten Ausschau nach den Treulosen!\n\nWenn sie wissen, dass die Straße sicher ist, führe ich einige der Vulpera hinaus und treffe mich mit den Karawanen, die sie in Sicherheit bringen.\n\nDann schleiche ich mich wieder hinein und bereite mich darauf vor, eine weitere Gruppe zu übernehmen. Es ist sehr aufregend und bisher habe ich erst drei Mal vor Angst geweint!\n\nWenn Ihr aufbrechen müsst, geht einfach aus der Höhle heraus und Richtung Westen. Überquert die Brücke zu den Ruinen und Ihr habt es geschafft.', 28153),
(149762, 'deDE', '', 'Das Gleiche wie Ihr, nehme ich an. Seht Euch die Vulpera an... Sie brauchen jemanden, der ihnen hilft.\n\nDie Treulosen haben unzählige meiner Leute versklavt und gezwungen, für sie zu arbeiten und zu kämpfen.\n\nBisher waren wir immer machtlos gegen sie. Nisha und Kiro aber haben uns gezeigt, dass wir Widerstand leisten können.\n\nNachts schleichen sich Kiro und die anderen ins Sklavenlager und retten die schwächsten Vulpera.\n\nSie bringen sie hierher. Dann bringe ich sie sicher durch die Dünen. Dort warten unsere Karawanen auf sie, um sie in Sicherheit zu bringen.\n\nEs ist gefährlich und ich würde viel lieber Ahna im Lager an einem gemütlichen Lagerfeuer singen hören. Aber wie kann ich das, wenn ich weiß, dass meine Freunde Hilfe benötigen?', 28153),
(149761, 'deDE', 'Ich möchte Euch etwas anderes fragen.', 'Ich möchte Euch etwas anderes fragen.', 28153),
(149760, 'deDE', 'Wo ist Nisha?', 'Wo ist Nisha?', 28153),
(149759, 'deDE', 'Wo ist Kiro?', 'Wo ist Kiro?', 28153),
(149758, 'deDE', 'Wie schmuggelt Ihr die Sklaven raus?', 'Wie schmuggelt Ihr die Sklaven raus?', 28153),
(149757, 'deDE', 'Was macht Ihr hier?', 'Was macht Ihr hier?', 28153),
(149756, 'deDE', '', '$p! Ich wusste, dass Ihr kommen würdet! Ich habe allen gesagt: \"$p macht sich etwas aus den Vulpera und wird uns nicht im Stich lassen.\"\n\nIch bin hier, um ebenfalls zu helfen! Kiro und Nisha retten Vulperasklaven und ich organisiere Karawanen, um sie hier wegzubringen.\n\nEs ist irgendwie beängstigend, den Sethrak so nahe zu sein. Aber ich weiß, dass wir hier das Richtige tun. Nisha hat das gesagt.\n\nOh, übrigens, willkommen in unserem kleinen Versteck.', 28153),
(149755, 'deDE', 'Geht voran.', 'Geht voran.', 28153),
(149754, 'deDE', 'Wenn Ihr lügt, werdet Ihr hängen.', 'Wenn Ihr lügt, werdet Ihr hängen.', 28153),
(149753, 'deDE', 'Ich folge Euch.', 'Ich folge Euch.', 28153),
(149752, 'deDE', '', 'Unsre Streitkräfte könn\' diese Vorräte gut gebrauch\'n. Gute Arbeit.', 28153),
(149751, 'deDE', '', 'Wir hab\'n das Bootswrack gefund\'n, das die Bluttrolle aufs Korn genomm\' hatt\'n. Sichert die Fracht, bevor\'s die Bluttrolle tun!', 28153),
(149750, 'deDE', 'An der Sache ist hoffentlich was dran.', 'An der Sache ist hoffentlich was dran.', 28153),
(149749, 'deDE', 'Hmm. Nun gut, gehen wir.', 'Hmm. Nun gut, gehen wir.', 28153),
(149748, 'deDE', 'Was?! Ihr erzählt hoffentlich keinen Unfug...', 'Was?! Ihr erzählt hoffentlich keinen Unfug...', 28153),
(149747, 'deDE', 'Nun denn, mein getreuer Knappe... Wie mir scheint, ist unsere Arbeit hier getan. Entschuldigt mich nun bitte, denn ich habe einen Ettin zu erlegen.', '', 28153),
(149746, 'deDE', 'Ein Bandit! Fürchtet Euch nicht, holde Maid, denn ich werde Euch beschützen!', '', 28153),
(149745, 'deDE', 'Ein Astraldämon? Ich werde nicht dulden, dass Glitzer II derart beleidigt wird! Macht Euch auf eine Kostprobe der Macht von Johnny... Ist das ein Ettin?', '', 28153),
(149744, 'deDE', 'Ihr hattet allem Anschein nach eine Auseinandersetzung mit diesem Astraldämon, aber wie ich sehe, konntet Ihr ihn ganz allein bezwingen! Eine beachtliche Leistung! Er hat Euch doch hoffentlich nicht verletzt?', '', 28153),
(149743, 'deDE', '', 'Das Volk verliert den Glauben an Katherine...', 28153),
(149742, 'deDE', '', 'Großartig... Wir müssen wohl eine Szene machen.', 28153),
(149741, 'deDE', '', 'Erster Schritt: Einen Aufruhr entfachen.', 28153),
(149740, 'deDE', '[PH] Das reicht jetzt. Mythrax wird sich erheben, und Ihr Verräter werdet mit dem Leben bezahlen!', '', 28153),
(149739, 'deDE', '[PH] Die Schlüssel werden unser sein... und Mythrax wird sich erheben!', '', 28153),
(149738, 'deDE', 'Glitzer II... Warum bist du nicht losgeflogen?', '', 28153),
(149737, 'deDE', '[PH] Ich beginne jetzt... und das keinen Moment zu früh. Da sind schon Kortheks Streitkräfte!', '', 28153),
(149736, 'deDE', 'Ich bin bereit, Euch gegen die Sethrak zu verteidigen. Beginnt mit der Abstimmung.', 'Ich bin bereit, Euch gegen die Sethrak zu verteidigen. Beginnt mit der Abstimmung.', 28153),
(149735, 'deDE', '[PH] Seid Ihr bereit? Wir müssen uns beeilen, denn Kortheks Streitkräfte werden versuchen, mich daran zu hindern, mir die Macht dieser Spitze zu eigen zu machen. Ihr müsst mir während meines Zaubers den Rücken decken.', '', 28153),
(149730, 'deDE', 'Wo kommen all diese Irrwische nur her?', '', 28153),
(149729, 'deDE', 'Autsch! Diese verdammten Irrwische!', '', 28153),
(149726, 'deDE', 'Ihr habt Boralus aus großer Not befreit. Aber ich wette mein Gewicht in Grog, dass die Gefahr noch nicht vorbei ist.', '', 28153),
(149725, 'deDE', 'Ohne diesen hinterhältigen Feigling und seine Kapitäne wird seine Piratentruppe das Bramsegel nicht vom Klüver unterscheiden können.', '', 28153),
(149724, 'deDE', 'Harlan hätte wissen müssen, dass sein Verrat an mir so enden würde.', '', 28153),
(149723, 'deDE', 'Aber für Euch doch kein Problem, oder?', '', 28153),
(149722, 'deDE', 'Außer vielleicht seine berüchtigte Leibwache aus kaltblütigen Mördern und Totschlägern.', '', 28153),
(149720, 'deDE', '[PH] Ich werde mich zur Spitze durchschlagen. Trefft mich dort. Kortheks Streitkräfte werden uns mit aller Kraft davon abhalten wollen, die Macht der Spitze zu nutzen.', '', 28153),
(149719, 'deDE', 'Holde Maid, was plagt Euch? Maximillian von Nordhain ist hier, um zu helfen!', '', 28153),
(149717, 'deDE', '', 'Ohne Euch hätt\'n wir Rakera nie gefund\'n, Kleine.', 28153),
(149716, 'deDE', 'Das klang mir ganz nach einer in Not geratenen Maid. Folgt mir, Knappe!', '', 28153),
(149715, 'deDE', 'Ihr müsst verstehen, Knappe, dass meine bisherigen Versuche, diesen Ettin niederzustrecken, nicht von Erfolg gekrönt waren. Zu allem Überfluss stecken meine Lanzen fest in seiner Seite. Eure erste Aufgabe besteht nun darin...', '', 28153),
(149714, 'deDE', '', 'Wir sind doch Freunde, ja?', 28153),
(149713, 'deDE', '', 'Die Ruinen liegen auf dem Weg nach Zem\'lan. Ich nehme Euch gerne mit! Dolly und Dot sind toll, aber manchmal will ich auch mit Freunden reden.', 28153),
(149712, 'deDE', 'Also, diese Blase... Oh! Salzwasser kannst du nicht ab? Wenn das nicht sonderbar ist, Kleiner.', '', 28153),
(149711, 'deDE', 'NEEEEEIIIN!!! DAS KANN NICHT SEIN!!!', '', 28153),
(149710, 'deDE', 'Moment... was machen die Vulpera hier?', '', 28153),
(149709, 'deDE', 'Er ist seit Jahren verlassen, doch von dort aus können wir ideal unseren...', '', 28153),
(149708, 'deDE', 'Mein eigener Unterschlupf lag versteckt in den Hügeln, ein kleiner Sethraliss geweihter Schrein zum Meditieren.', '', 28153),
(149707, 'deDE', 'Damals waren Korthek und ich Anführer aller Sethrak und wir huldigten Sethraliss.', '', 28153),
(149706, 'deDE', 'Der ertrunkene Traum verschlingt mich.', 'Der ertrunkene Traum verschlingt mich.', 28153),
(149705, 'deDE', 'Ich lebte auch vor langer Zeit dort, bevor Korthek unser Volk aus Machtgier und Wahnsinn verraten hat.', '', 28153),
(149704, 'deDE', 'Es ist ein krudes Nest aus Fels und Dreck voller Sethrak, die den Loa abgeschworen haben.', '', 28153),
(149703, 'deDE', 'Ich trinke von der unendlichen Leere.', 'Ich trinke von der unendlichen Leere.', 28153),
(149702, 'deDE', 'Endlich sehe ich klar.', 'Endlich sehe ich klar.', 28153),
(149701, 'deDE', 'Wir reiten in das Herz des Imperiums der Treulosen, $p.', '', 28153),
(149700, 'deDE', 'Der Kreis... ich sehe den Kreis, ja!', 'Der Kreis... ich sehe den Kreis, ja!', 28153),
(149699, 'deDE', 'Der kriechende Schatten kommt mich holen.', 'Der kriechende Schatten kommt mich holen.', 28153),
(149698, 'deDE', 'Ich höre die Stimme! Die tausend Wahrheiten!', 'Ich höre die Stimme! Die tausend Wahrheiten!', 28153),
(149697, 'deDE', 'In der Tiefe werde ich ewig leben!', 'In der Tiefe werde ich ewig leben!', 28153),
(149696, 'deDE', 'Endlich! Der Weg zu Harlan ist frei und nichts kann uns aufhalten.', '', 28153),
(149695, 'deDE', 'Meine Seele für den Uralten!', 'Meine Seele für den Uralten!', 28153),
(149694, 'deDE', '', 'Wir werd\'n Euer Volk wie unser eignes verteidig\'n.', 28153),
(149693, 'deDE', 'Wie wär\'s, wenn wir Euer Diplom in Prügologie richtig einsetzen?', '', 28153),
(149692, 'deDE', 'Die hinterhältige Qualle hat die Insel abriegeln lassen, bis die Feierlichkeiten in den Arenen vorbei sind.', '', 28153),
(149691, 'deDE', 'Hab ich \'ne Friedensblume am Revers, Allianzabschaum?!', 'Hab ich \'ne Friedensblume am Revers, Allianzabschaum?!', 28153),
(149690, 'deDE', 'Ich weiß nix von irgend\'ner Tiefenbahn!', 'Ich weiß nix von irgend\'ner Tiefenbahn!', 28153),
(149689, 'deDE', 'Jetzt bleibt nur eins zu tun: Lasst Harlan Stahl schmecken. Aber das wird nicht einfach.', '', 28153),
(149688, 'deDE', 'Mondkins flieg\'n nich\'! Haut jetz\' ab!', 'Mondkins flieg\'n nich\'! Haut jetz\' ab!', 28153),
(149687, 'deDE', 'Ich bin kein Spion!', 'Ich bin keine Spionin!', 28153),
(149686, 'deDE', '\"Der Murloc macht was wann?\" Ihr habt wohl \'ne Schraube locker!', '\"Der Murloc macht was wann?\" Ihr habt wohl \'ne Schraube locker!', 28153),
(149685, 'deDE', '\"\'ne Flasche Trollschweiß\"? Sowas führ\'n wir hier nich\'!', '\"\'ne Flasche Trollschweiß\"? Sowas führ\'n wir hier nich\'!', 28153),
(149684, 'deDE', 'Klar, Bäume sin\' schön und Feuer is\' übel. Worauf wollt Ihr hinaus?', 'Klar, Bäume sin\' schön und Feuer is\' übel. Worauf wollt Ihr hinaus?', 28153),
(149683, 'deDE', 'Zandalar für immer!', 'Zandalar für immer!', 28153),
(149682, 'deDE', '', 'Etwas stimmt nich\' mit diesem Tempel. Wir müssen \'nen Weg hinein find\'n.', 28153),
(149681, 'deDE', 'Wenn Ihr nicht so ein Heldentyp wärt, würdet Ihr \'nen klasse Piraten abgeben.', '', 28153),
(149680, 'deDE', 'Ich schlafe... nur um zu erwachen...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'deDE', 'Das ist... toll, Maximillian. Ich muss jetzt aber gehen.', 'Das ist... toll, Maximillian. Ich muss jetzt aber gehen.', 28153),
(149678, 'deDE', 'Der endlose Schatten... heißt mich willkommen...', '', 28153),
(149677, 'deDE', 'Eure Hoffnung... schwindet...', '', 28153),
(149676, 'deDE', 'Ähm... Was?', 'Ähm... Was?', 28153),
(149675, 'deDE', 'Die Saat... setzt sich fest...', '', 28153),
(149674, 'deDE', 'Ich bin nur einer... von vielen...', '', 28153),
(149673, 'deDE', 'Der Kreislauf... setzt sich fort...', '', 28153),
(149672, 'deDE', 'Selbst der Tod... vermag zu sterben.', '', 28153),
(149671, 'deDE', 'Letzten Endes... werdet Ihr die Wahrheit erkennen.', '', 28153),
(149670, 'deDE', 'Habt Ihr es schon gehört? Daelins Tor ist gefallen!', 'Habt Ihr es schon gehört? Daelins Tor ist gefallen!', 28153),
(149669, 'deDE', 'Was haltet Ihr von all dem?', 'Was haltet Ihr von all dem?', 28153),
(149668, 'deDE', 'Die Ströme reißen Euch in den Abgrund.', '', 28153),
(149667, 'deDE', 'Ich dagegen möcht\' gleich alte Gewohnheiten annehm\'.', '', 28153),
(149666, 'deDE', 'Die Schwarzzahnvandalen mögen nichts lieber als eine Schlägerei. Verpasst ihnen ein paar Zahnlücken, dann will Käpt\'n Raoul Euch sicher beim Treff\'n sehen.', '', 28153),
(149665, 'deDE', 'Was\'n das für \'n Gekreische aus Euerm Mund?', '', 28153),
(149664, 'deDE', 'Nicht mal Fische trinken so viel wie die Bilgeratten. Haltet mit der Bande mit, dann wird Euch Käpt\'n Eudora sicher zu dem Treffen einladen.', '', 28153),
(149663, 'deDE', 'Was habt Ihr über den Angriff gehört?', 'Was habt Ihr über den Angriff gehört?', 28153),
(149662, 'deDE', 'Keiner kann behaupten, dass ich nicht meinen Beitrag zu den Kriegsanstrengungen geleistet hätte. Hier ist mein Bericht.', 'Keiner kann behaupten, dass ich nicht meinen Beitrag zu den Kriegsanstrengungen geleistet hätte. Hier ist mein Bericht.', 28153),
(149661, 'deDE', '', 'Na gut. Dot und Dolly heißen wir, ziehn durch Wüstensand mit dir!', 28153),
(149660, 'deDE', 'Ich weiß nicht... Mit jedem Tag verschlimmert sich die Lage. Vielleicht sollte Katherine abdanken.', 'Ich weiß nicht... Mit jedem Tag verschlimmert sich die Lage. Vielleicht sollte Katherine abdanken.', 28153),
(149659, 'deDE', 'Ich werde die Allianz nicht enttäuschen. Selbst, wenn ich drei Tage im Schlamm sitzen musste, um das hier zu bekommen. Bitte, nehmt meinen Bericht.', 'Ich werde die Allianz nicht enttäuschen. Selbst, wenn ich drei Tage im Schlamm sitzen musste, um das hier zu bekommen. Bitte, nehmt meinen Bericht.', 28153),
(149658, 'deDE', '', 'Dot und Dolly mögen es, wenn ich singe. Es beruhigt sie.', 28153),
(149657, 'deDE', 'Könnt Ihr glauben, dass manche denken, Trolle und Nachtelfen seien verwandt? Ein traumatisierendes Erlebnis war das. Hier, mein Bericht.', 'Könnt Ihr glauben, dass manche denken, Trolle und Nachtelfen seien verwandt? Ein traumatisierendes Erlebnis war das. Hier, mein Bericht.', 28153),
(149656, 'deDE', 'Besorgt Euch eine Einladung, das macht die Sache einfacher. Ihr könnt natürlich auch reinstürmen und drei der gefürchtetsten Piratenkapitäne auf einmal töten. Eure Entscheidung, Kumpel.', '', 28153),
(149655, 'deDE', '', 'Dot und Dolly heißen wir, ziehn durch Wüstensand mit dir, sind so wuschel-knuffig-süß...', 28153),
(149654, 'deDE', 'Ich habe ja gesagt, dass ich alles tun würde, um Teldrassil zu rächen. Darunter fällt offenbar auch, sich als Troll ausgeben zu müssen. Hier, mein Bericht.', 'Ich habe ja gesagt, dass ich alles tun würde, um Teldrassil zu rächen. Darunter fällt offenbar auch, sich als Troll ausgeben zu müssen. Hier, mein Bericht.', 28153),
(149653, 'deDE', 'Ich weiß aus sicherer Quelle, dass die Kapitäne eine Versammlung haben. Wenn wir\'s da hineinschaffen, können wir der Schlange alle Köpfe auf einmal abschlagen.', '', 28153),
(149652, 'deDE', 'Wo ist mein Pterrordax?', 'Wo ist mein Pterrordax?', 28153),
(149651, 'deDE', 'Was ist mit meinem Jungen nur los?', 'Was ist mit meinem Jungen nur los?', 28153),
(149650, 'deDE', 'Nur ein kleiner Ausflug in den Dschungel, haben sie gesagt. Der reinste Spaziergang, haben sie gesagt. Da, bitte, mein Bericht.', 'Nur ein kleiner Ausflug in den Dschungel, haben sie gesagt. Der reinste Spaziergang, haben sie gesagt. Da, bitte, mein Bericht.', 28153),
(149649, 'deDE', 'Warum macht er solchen Lärm?!', 'Warum macht er solchen Lärm?!', 28153),
(149648, 'deDE', 'Wilde. Ganz und gar unzivilisierte Wilde sind das hier. Bitte, hier habt Ihr meinen Bericht.', 'Wilde. Ganz und gar unzivilisierte Wilde sind das hier. Bitte, hier habt Ihr meinen Bericht.', 28153),
(149647, 'deDE', 'Frag gar nicht erst, wo ich letzte Nacht schlafen musste. Hier ist Euer Bericht.', 'Frag gar nicht erst, wo ich letzte Nacht schlafen musste. Hier ist Euer Bericht.', 28153),
(149646, 'deDE', 'Vielen Dank.', 'Vielen Dank.', 28153),
(149645, 'deDE', 'Ich kümmere mich um das große Ganze, die Details überlasse ich Euch.', '', 28153),
(149644, 'deDE', 'Und dann geben wir Harlan, was er verdient.', '', 28153),
(149643, 'deDE', 'Ertrinkt im Blut der Unendlichkeit.', '', 28153),
(149642, 'deDE', 'Hier ist der Plan: Schwertwasser ablassen, Bilgeratten ersäufen, Schwarzzähne ausschlagen und Eisenflut einschmelzen.', '', 28153),
(149641, 'deDE', 'Wenn er das schafft, wäre seine Flotte eine Bedrohung für die gesamte Region.', '', 28153),
(149640, 'deDE', 'Ich dacht, ich hätt da was kreisch\'n gehört, aber ich kann die Nester nich\' alleinlass\'n, um nachzuseh\'n.$b$bBeeilt Euch lieber, sonst habt Ihr bald keinen Pterrordax mehr, auf den Ihr aufpass\'n könnt. Sie schaffen\'s lang nich\' alle bis zum Erwachsenenalter.', '', 28153),
(149639, 'deDE', 'Harlan benutzt die Eisenfluträuber, um die anderen Piraten für sich zu gewinnen.', '', 28153),
(149638, 'deDE', 'Oh, der is\' weg! Is\' ihm wohl langweilig geword\'n.$b$bFindet ihn lieber wieder, bevor er sich noch wehtut. Er kann schließlich noch nich\' für sich selbst sorg\'n.', '', 28153),
(149637, 'deDE', 'Sieht ganz schön niedergeschlag\'n aus, was?$b$bIch möcht wett\'n, er vermisst seine Mutter. Hey, das seid dann wohl Ihr, was?', '', 28153),
(149636, 'deDE', 'Eure Seele wird nichts als Hunger kennen.', '', 28153),
(149635, 'deDE', 'Die Sterne fürchten unseren Aufstieg.', '', 28153),
(149634, 'deDE', 'Der Lärm is\' \'n sicheres Zeichen, dass er Hunger hat.$b$bFüttert ihn lieber, bevor er Euch \'nen Finger abbeißt.$b$bWenn Ihr kein Futter dabeihabt, könnt Ihr\'s Euch vom Kriegsbestienkral hol\'n.', '', 28153),
(149633, 'deDE', 'Spürt die Umarmung des wahren Nichts.', '', 28153),
(149632, 'deDE', 'Schlaft in Ewigkeit in Ny\'alotha.', '', 28153),
(149631, 'deDE', 'Das Licht ertrinkt in der endlosen Tiefe.', '', 28153),
(149630, 'deDE', 'Ich bin Schwingenhalter Goja. Pa\'ku is\' mein Loa, un\' ich dien der Herrin des Windes, indem ich auf die Jung\'n aufpass.$b$bSie hat mir auch gesagt, dass Ihr Hilfe brauch\'n könntet.$b$b<Schwingenhalter Goja kichert.>$b$bWas kann ich für Euch tun?', '', 28153),
(149629, 'deDE', 'Seht den Schatten Eures Untergangs.', '', 28153),
(149628, 'deDE', 'Ich habe gehört, Piraten stecken dahinter. Könnt Ihr das fassen? Elendige, flohverseuchte PIRATEN! Können diese Prachtmeers uns gar nicht mehr beschützen?', 'Ich habe gehört, Piraten stecken dahinter. Könnt Ihr das fassen? Elendige, flohverseuchte PIRATEN! Können diese Prachtmeers uns gar nicht mehr beschützen?', 28153),
(149627, 'deDE', 'Ah, mein getreuer Knappe! Ihr seid stets zur Stelle, wenn ich Euch brauche.\n\nIch kam in der Hoffnung nach Kul Tiras, dort rettungsbedürftige Bürger anzutreffen. Meine derzeitige Aufgabe ist es, die armen Fischer dieses malerischen Dorfes vor den Ettins zu retten, die sie terrorisieren.\n\nDie Haut dieser Kreaturen ist allerdings unnatürlich dick.', '', 28153),
(149626, 'deDE', 'Klar, Ihr und alle anderen auch. Reiht Euch ein und macht bloß keine Szene. Die Menge fängt so schon an zu toben.', 'Klar, Ihr und alle anderen auch. Reiht Euch ein und macht bloß keine Szene. Die Menge fängt so schon an zu toben.', 28153),
(149625, 'deDE', 'Ich muss umgehend mit Katherine Prachtmeer sprechen.', 'Ich muss umgehend mit Katherine Prachtmeer sprechen.', 28153),
(149624, 'deDE', 'Lordadmiralin Prachtmeer bereitet sich darauf vor, zum Volk zu sprechen. Bitte übt Euch in Geduld.', 'Lordadmiralin Prachtmeer bereitet sich darauf vor, zum Volk zu sprechen. Bitte übt Euch in Geduld.', 28153),
(149623, 'deDE', 'Die Lordadmiralin ist in Gefahr. Kommt mit!', 'Die Lordadmiralin ist in Gefahr. Kommt mit!', 28153),
(149622, 'deDE', 'Bitte bewahrt Ruhe. Alles ist unter Kontrolle.', 'Bitte bewahrt Ruhe. Alles ist unter Kontrolle.', 28153),
(149621, 'deDE', 'Nante Grinser lässt sich nicht ausnutzen. Niemand wird diesen Schatz vor mir finden!', '', 28153),
(149620, 'deDE', 'Ihr werdet mich nicht beim Schlafen erwischen.\n\nWer versucht, mich reinzulegen, den verkaufe ich an die Loyalisten.', '', 28153),
(149619, 'deDE', 'Das Gezeitenblut wurde erst kürzlich verunreinigt. Sicher kann ich es noch läutern.', '', 28153),
(149618, 'deDE', 'Ah! Es ist instabiler, als ich dachte.', '', 28153),
(149617, 'deDE', 'Heda, $gReisender:Reisende;!\n\nHaben die heroischen Geschichten meiner Großtaten in Euch etwa die Hoffnung geweckt, zum Knappen Maximillians von Nordhain auserkoren zu werden?\n\nDann hat sich Eure Hoffnung erfüllt, denn heute ist Euer Glückstag! Ich benötige nämlich einen Knappen, der mir im Kampf gegen gefährliche Widersacher tatkräftig zur Seite steht.', '', 28153),
(149616, 'deDE', '', 'Ich werd sie find\'n oder beim Versuch sterb\'n.', 28153),
(149615, 'deDE', '', 'Zem\'lans Hafen ist im Süden. Da läuft schon seit Jahren kein Schiff mehr ein, aber es ist unsere beste Chance, die Sachen zu finden, die Kiro und Nisha für ihren Angriff auf die Sethrak brauchen.', 28153),
(149614, 'deDE', '', 'Haltet Ausschau nach Eurer Freundin. Ich konzentriere mich auf die Straße.', 28153),
(149613, 'deDE', '', 'Das ist nach der Schlacht, aber... Tul wird nicht tot abgebildet. Verwundet, gebrochen, aber nicht tot!', 28153),
(149612, 'deDE', '', 'Geschichten hiervon schildern, wie Lord Arom Gorak Tul tötet und seine Armee daraufhin fällt. Aber hier sieht man, wie seine Konstrukte zerbersten, als er erstochen und seine Macht gebrochen wird. Als ob sie verbunden sind.', 28153),
(149611, 'deDE', '', 'Das ist Lord Arom Kronsteig, als er damals noch als Oberst den finalen Ansturm anführte. Und hier... hier ersticht Kronsteig Gorak Tul.', 28153),
(149610, 'deDE', '', 'Das ist nicht von den Drust. Die Kul Tiraner haben das hier eingeritzt.', 28153),
(149609, 'deDE', '', 'Interessant. Ich wusste nicht, dass er die Konstrukte erst später aus Verzweiflung erweckte.', 28153),
(149608, 'deDE', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz.', '', 28153),
(149607, 'deDE', 'Fhssh zzof og far\'al awtgsshu.', '', 28153),
(149606, 'deDE', '', 'Gute Arbeit! Jetzt kann Krag\'was Brut erstmal durchatmen. Habt Dank, Champion.', 28153),
(149605, 'deDE', 'Kua\'fon kreischt vor Freude und verschlingt das angebotene Futter.', '', 28153),
(149604, 'deDE', 'Kua\'fon beschnuppert das Futter, bevor er sich gierig darüber hermacht.', '', 28153),
(149603, 'deDE', 'Kua\'fon schnappt das Futter aus der Luft.', '', 28153),
(149602, 'deDE', 'Kua\'fon stürzt sich auf das angebotene Futter und verschlingt es in einem Stück.', '', 28153),
(149601, 'deDE', '', 'Die Bluttrolle jagen Krag\'was Brut aufs Neue. Das Herz vom Herrn der Frösche brennt vor Wut. Geht und helft ihm bei seiner Rache!', 28153),
(149600, 'deDE', 'In Sturmsangs Namen!', 'In Sturmsangs Namen!', 28153),
(149599, 'deDE', 'Das Tal gehört uns, Bilgeratte!', 'Das Tal gehört uns, Bilgeratte!', 28153),
(149598, 'deDE', 'Ohne uns ist Kul Tiras Fischfutter!', 'Ohne uns ist Kul Tiras Fischfutter!', 28153),
(149597, 'deDE', 'Unsere Flotte zerquetscht Euch!', 'Unsere Flotte zerquetscht Euch!', 28153),
(149596, 'deDE', 'Wer uns im Weg steht, geht unter!', 'Wer uns im Weg steht, geht unter!', 28153),
(149595, 'deDE', 'Wir sind gnadenlos wie die kalte See!', 'Wir sind gnadenlos wie die kalte See!', 28153),
(149594, 'deDE', 'Ihr wagt es, Haus Sturmsang zu trotzen?', 'Ihr wagt es, Haus Sturmsang zu trotzen?', 28153),
(149593, 'deDE', 'Kul Tiras gehört der See!', 'Kul Tiras gehört der See!', 28153),
(149592, 'deDE', 'Mein Leben... für die See...', 'Mein Leben... für die See...', 28153),
(149591, 'deDE', 'Gezeitenweise... bewahrt mich...', 'Gezeitenweise... bewahrt mich...', 28153),
(149590, 'deDE', 'Ich hab nur... Befehle befolgt...', 'Ich hab nur... Befehle befolgt...', 28153),
(149589, 'deDE', 'Wir haben... schon gewonnen...', 'Wir haben... schon gewonnen...', 28153),
(149588, 'deDE', 'Mein Tod... hält gar nichts auf...', 'Mein Tod... hält gar nichts auf...', 28153),
(149587, 'deDE', 'Wir machen... niemals halt...', 'Wir machen... niemals halt...', 28153),
(149586, 'deDE', 'Ich blute... Salzwasser...', 'Ich blute... Salzwasser...', 28153),
(149585, 'deDE', 'In der Tiefe... hab ich Wahrheit gesehen.', 'In der Tiefe... hab ich Wahrheit gesehen.', 28153),
(149584, 'deDE', 'Ihr habt keine Vorstellung, wie demütigend dies ist. Hier ist Euer Bericht.', 'Ihr habt keine Vorstellung, wie demütigend dies ist. Hier ist Euer Bericht.', 28153),
(149583, 'deDE', '', 'Narren... Immerhin wissen wir jetzt, wie gefährlich die Irrwische sind.', 28153),
(149582, 'deDE', '', 'Beim nächsten Mal gibt es kein Entkommen, Malfurion!', 28153),
(149581, 'deDE', 'Bis hierher und nicht weiter, Bansheekönigin!', '', 28153),
(149580, 'deDE', '<Kua\'fon ruht mit dem Kopf unter der Schwinge und klagt leise vor sich hin.>', '', 28153),
(149579, 'deDE', '', 'Zeit zum Abstechen!', 28153),
(149577, 'deDE', '[PH] Lasst sie zahlen, $p.', '', 28153),
(149575, 'deDE', '', 'Was habt Ihr erwartet? Es ist gerade geschlüpft und muss fressen. Bittet den Kral um etwas Fleisch.', 28153),
(149574, 'deDE', 'Wer Wind sät...', '', 28153),
(149573, 'deDE', '', 'Ich kann es hören. Das Kleine ist gut bei Stimme.\n\nWarum seht Ihr so verängstigt drein?', 28153),
(149571, 'deDE', '<Starrt Euch ausdruckslos an.>', '<Starrt Euch ausdruckslos an.>', 28153),
(149570, 'deDE', 'Ich sag gar nix.', 'Ich sag gar nix.', 28153),
(149569, 'deDE', 'Habt Ihr ma\' \'n bisschen Kleingeld?', 'Habt Ihr ma\' \'n bisschen Kleingeld?', 28153),
(149568, 'deDE', 'Ihr seid mir ja \'n komischer Troll.', 'Ihr seid mir ja \'n komischer Troll.', 28153),
(149567, 'deDE', '...Was?', '...Was?', 28153),
(149566, 'deDE', 'Ihr versperrt mir die Sicht, Mann.', 'Ihr versperrt mir die Sicht, Mann.', 28153),
(149565, 'deDE', '<Rülpst.>', '<Rülpst.>', 28153),
(149564, 'deDE', '<Nennt die Passphrase.>', '<Nennt die Passphrase.>', 28153),
(149563, 'deDE', 'Was wollt Ihr?', 'Was wollt Ihr?', 28153),
(149562, 'deDE', 'Schildkrötensuppe ist nicht halb so lecker wie $gein:eine:r; $R, $gder:die:r; langsam weichgekocht wird.\n\nBeschafft einfach das Schlammwurmfleisch und lasst die kleinen Schildkröten in Ruhe.\n\nKommt mal wieder bei mir vorbei, dann können wir andere Suppen ausprobieren!', '', 28153),
(149561, 'deDE', 'Schildkrötensuppe?', 'Schildkrötensuppe?', 28153),
(149560, 'deDE', 'FÜR SETHRALISS!', '', 28153),
(149559, 'deDE', 'Die Treulosen versperren den Weg zu Imperator Korthek. Wir müssen diese Barriere zerstören!', '', 28153),
(149558, 'deDE', 'Okay, hört zu! Margie braucht wohl Hilfe in der Werkstatt... Irgendwas mit Teilen für ein... ach, weiß der Henker. Das ist nicht mein Fachbereich, okay?', '', 28153),
(149557, 'deDE', 'Ausgezeichnet. Diese Informationen werden entscheidend für unsere Kriegsanstrengungen sein. Und nein, ich weiß auch nicht, wer sich diese Parole ausgedacht hat.', '', 28153),
(149556, 'deDE', 'Unsere Spione haben die Hauptstadt der Zandalari infiltriert, aber Ihr müsst uns ihre Berichte überbringen. Sprecht mit den Landstreichern. Unser Spion wird auf die geheime Parole reagieren.', '', 28153),
(149555, 'deDE', 'Südlich von hier sind Oger, die, äh, übel gelaunt zu sein scheinen. Macht Euch bereit, Leute! Zu den Waffen!', '', 28153),
(149554, 'deDE', 'Hier findet Ihr nur Akunda. Nur die, die sein\' Namen teil\'n , dürf\'n seine Hall\'n betret\'n.', '', 28153),
(149553, 'deDE', 'Sucht Ihr Erlösung? Akunda heißt alle willkomm\'.', '', 28153),
(149552, 'deDE', '', 'Wir such\'n \'ne Verbannte, die Rakera heißt. Wir denk\'n, sie könnt\' hier im Tempel sein.', 28153),
(149551, 'deDE', '', 'Ich gehe vor, für den Fall, dass dort Gold zu finden ist.', 28153),
(149550, 'deDE', '', 'Als wir hier landeten, wollten wir Frieden, aber die Drust zogen sofort ins Feld. Nur wenige duldeten neue Nachbarn.', 28153),
(149549, 'deDE', '', 'Wartet, das hier zeigt eine der frühen Siedlungen der Kul Tiraner. Eine der verlorenen Siedlungen.', 28153),
(149548, 'deDE', 'Ich werde mit Maokka reden.', 'Ich werde mit Maokka reden.', 28153),
(149547, 'deDE', 'Gut, alle sind hier.', '', 28153),
(149545, 'deDE', 'He, Mann.', '', 28153),
(149544, 'deDE', '', 'So treffen wir uns wieder, Champion.', 28153),
(149543, 'deDE', '', 'Diese Welt kann der Zerstörung, die Mythrax bringt, nicht standhalten.', 28153),
(149542, 'deDE', 'Lasst ihn gehen, Taelia!', '', 28153),
(149541, 'deDE', '', 'Samuel, nein!', 28153),
(149540, 'deDE', 'Für Anderson! Für das Sturmsangtal!', '', 28153),
(149539, 'deDE', 'Diese Bastarde werden für das bezahlen, was sie getan haben!', '', 28153),
(149538, 'deDE', '', 'Jakra\'zet verdient sein Schicksal.', 28153),
(149537, 'deDE', 'Wir stehen Euch bei. Für die Sturmwacht!', '', 28153),
(149535, 'deDE', '', 'Ich habe schon einen Trupp für Euch zusammengestellt. Holt mir meine Beute.', 28153),
(149533, 'deDE', 'Mehr, die meinen Orden verlassen haben. Gut, vielleicht ist noch nicht alles verloren.', '', 28153),
(149532, 'deDE', 'Wenn sie unter uns wandeln, ist die Flotte in größter Gefahr.', '', 28153),
(149531, 'deDE', 'Viele halten sie nur für Legenden. Geschichten, die davor warnen, mit unserer Magie in zu große Tiefen zu spähen.', '', 28153),
(149530, 'deDE', 'Diese... Dinger... sind K\'thir. Sie kommen aus den dunkelsten Tiefen des Meeres.', '', 28153),
(149529, 'deDE', '', '', 28153),
(149528, 'deDE', 'Was wünscht Ihr von mir, Kriegshäuptling?', 'Was wünscht Ihr von mir, Kriegshäuptling?', 28153),
(149527, 'deDE', '', 'Baine, ruft sie zurück!', 28153),
(149526, 'deDE', '', 'Steuert Wach-Es Bewegungen mit der Fernsteuerung. Schickt ihn zu den aufgewühlten Stellen im Boden, und er wird die Würmer herauslocken!', 28153),
(149525, 'deDE', 'Wir haben versucht, uns dagegen zu wehren, ihm zu widerstehen, aber ich fürchte, wir haben versagt.', '', 28153),
(149523, 'deDE', 'Mit der Zeit wurde das Raunen... lauter. Gebieterisch, drohend bisweilen.', '', 28153),
(149522, 'deDE', 'Lange hat mein Orden der See gelauscht, um unsere Schiffe und unser Volk zu führen. Es war ein sanftes Raunen, das nur wenige vernahmen.', '', 28153),
(149521, 'deDE', 'In der Nähe gibt es eine Brücke, von der man freie Sicht auf den Schrein des Sturms hat. Das Omen kommt von dort.', '', 28153),
(149520, 'deDE', 'Es wird mir \'n Vergnügen sein, Euch zu brech\'n.', '', 28153),
(149519, 'deDE', '', 'Seid bloß vorsichtig mit dem Ding... es sei denn, Ihr wollt gegen ein paar dieser Nichtsnutze da draußen kämpfen. In dem Fall: Lasst es krachen!', 28153),
(149518, 'deDE', 'Ihr töricht. Ihr tot.', '', 28153),
(149517, 'deDE', 'Diese Gefangenen gehör\'n den Zandalari!', '', 28153),
(149516, 'deDE', 'Ha ha ha!', '', 28153),
(149515, 'deDE', 'Ihr seid tot!', '', 28153),
(149514, 'deDE', 'Mickrige Allianz.', '', 28153),
(149513, 'deDE', 'Ich werd Euch vernicht\'n!', '', 28153),
(149512, 'deDE', 'Wollt Ihr den Verhörmeister kennenlern\'?', '', 28153),
(149511, 'deDE', 'Frischfleisch!', '', 28153),
(149510, 'deDE', 'Ob das Ding... sicher ist? Egal, das riskiere ich!', 'Ob das Ding... sicher ist? Egal, das riskiere ich!', 28153),
(149509, 'deDE', 'Bringt mich in Sicherheit!', 'Bringt mich in Sicherheit!', 28153),
(149508, 'deDE', 'Gezeitenmutter... was ist aus uns geworden?', '', 28153),
(149507, 'deDE', 'Gerade zur rechten Zeit!', 'Gerade zur rechten Zeit!', 28153),
(149506, 'deDE', 'Ist das... eine Maulwurfmaschine?', 'Ist das... eine Maulwurfmaschine?', 28153),
(149505, 'deDE', 'Ich habe Angst, unter die Erde zu gehen... aber noch mehr Angst habe ich vor diesen Trollen!', 'Ich habe Angst, unter die Erde zu gehen... aber noch mehr Angst habe ich vor diesen Trollen!', 28153),
(149504, 'deDE', 'Habt Dank, habt Dank!', 'Habt Dank, habt Dank!', 28153),
(149503, 'deDE', 'Ich seid gerade noch rechtzeitig gekommen!', 'Ich seid gerade noch rechtzeitig gekommen!', 28153),
(149502, 'deDE', 'Ich dachte schon, die fressen mich noch!', 'Ich dachte schon, die fressen mich noch!', 28153),
(149501, 'deDE', 'Kommandant, der Kriegshäuptling wünscht, dass Ihr Euren Außenposten für eine anrückende Armee vorbereitet.', 'Kommandant, der Kriegshäuptling wünscht, dass Ihr Euren Außenposten für eine anrückende Armee vorbereitet.', 28153),
(149500, 'deDE', 'Wir müssen Platz für die Flotte des Kriegshäuptlings schaffen. Könnt Ihr die Docks räumen?', 'Wir müssen Platz für die Flotte des Kriegshäuptlings schaffen. Könnt Ihr die Docks räumen?', 28153),
(149499, 'deDE', 'Der Kriegshäuptling benötigt Verpflegung und Unterkunft für eine anrückende Armee.', 'Der Kriegshäuptling benötigt Verpflegung und Unterkunft für eine anrückende Armee.', 28153),
(149498, 'deDE', 'Der Kriegshäuptling hat zweihundert Soldaten bei sich? Ich werde den Außenposten auf ihre Ankunft vorbereiten.', '', 28153),
(149497, 'deDE', 'Für den Kriegshäuptling würde ich alles tun. Ich werde den Wachen befehlen, sofort die Docks zu räumen. Lok\'tar.', '', 28153),
(149496, 'deDE', '', 'Die Armee des Kriegshäuptlings benötigt Unterkunft und Verpflegung? Das sollten unsere Reserven verkraften können. Wir hatten einen milden Winter und einen üppigen Frühling.', 28153),
(149495, 'deDE', 'Sie tötet ihre eigenen Truppen...', '', 28153),
(149494, 'deDE', 'Lasst mich helfen. Ich weiß, was ihm fehlt.', '', 28153),
(149493, 'deDE', 'Schickt mich zurück nach Sturmwind. (Zurückkehren/Szenario neu starten)', 'Schickt mich zurück nach Sturmwind. (Zurückkehren/Szenario neu starten)', 28153),
(149492, 'deDE', 'Schickt mich nach Zuldazar. (Introszenario überspringen)', 'Schickt mich nach Zuldazar. (Introszenario überspringen)', 28153),
(149491, 'deDE', '', 'Zu viele Schiffe unserer Flotte wurden entweder von der Legion oder der Allianz zerstört. Unsere Dockmeister arbeiten rund um die Uhr, aber das reicht nicht.', 28153),
(149490, 'deDE', 'Haltet ein.', '', 28153),
(149489, 'deDE', 'Ich spreche... für G\'huun. Er... befiehlt. Ihr... dient... oder sterbt.', '', 28153),
(149488, 'deDE', 'Kommt.', '', 28153),
(149487, 'deDE', 'Die Hülle dieses Loas... nährt mich. Nährt... G\'huun.', '', 28153),
(149486, 'deDE', 'Ihr versucht... G\'huun aufzuhalten. Ihr werdet... scheitern... und leiden.', '', 28153),
(149485, 'deDE', 'Ja... kämpft dagegen an... wehrt Euch... G\'huun hungert... nach Eurem... Leiden.', '', 28153),
(149484, 'deDE', 'Eure Bemühungen... zwecklos. Ich bin... unbesiegbar.', '', 28153),
(149483, 'deDE', 'Eure Bemühungen... zwecklos... Ich bin... unbesieg- was? Nein. NEIN!', '', 28153),
(149482, 'deDE', 'Das... beweist... GAR nichts! Er wird... ein neues Gefäß... suchen. Siegel... werden brechen... G\'huun... wird frei sein!', '', 28153),
(149481, 'deDE', 'Moment mal... Ist das aus dem Keller?', '', 28153),
(149480, 'deDE', '', '[PH] Viel Glück.', 28153),
(149479, 'deDE', '', '[PH] Ihre Patrouille ist gerade vorbeigekommen. Ihr solltet jetzt freie Bahn haben.', 28153),
(149478, 'deDE', '', '', 28153),
(149477, 'deDE', '', '[PH] Die Treulosen werden gar nicht wissen, wie ihnen geschieht!', 28153),
(149476, 'deDE', '', '', 28153),
(149475, 'deDE', 'Das kleine Kind rennt kichernd weg, als Ihr ihm nachlauft.', 'Das kleine Kind rennt kichernd weg, als Ihr ihm nachlauft.', 28153),
(149474, 'deDE', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t%s zielt mit |cFFFF0000|Hspell:257617|h[Emporstoßen]|h|r auf |cFFFF0000$n|r! Verteilt Euch!', '', 28153),
(149473, 'deDE', 'Ich dachte, wir könnt\'n die Pterrordaxe von dem Aussichtspunkt aufm Hügel wegjag\'n, aber die schnapp\'n sich einfach unsre Leute einen nach\'m andern... als wär das nix.', 'Ich dachte, wir könnt\'n die Pterrordaxe von dem Aussichtspunkt aufm Hügel wegjag\'n, aber die schnapp\'n sich einfach unsre Leute einen nach\'m andern... als wär das nix.', 28153),
(149472, 'deDE', 'Schon in Ordnung, gnädige Frau.', '', 28153),
(149471, 'deDE', '', 'Ich halte nicht viel von Reden, also werde ich mich kurzfassen. Danke. Ihr werdet im Sturmsangtal immer Verbündete haben.', 28153),
(149470, 'deDE', '', 'Ist nicht persönlich gemeint, Calvin.', 28153),
(149469, 'deDE', '', 'Ihr habt die Stacheleber über die Höfe bis hin zum Kral gejagt. Ihr habt Bürger und Bauern gerettet. Ihr habt mehr für uns getan, als es die Miliz jemals gekonnt... oder gewollt hätte.', 28153),
(149468, 'deDE', '', 'Ich erspare Euch die blumigen Worte. Diese Kunst habe ich ohnehin nie gut beherrscht.', 28153),
(149466, 'deDE', 'Die Zandalari transportieren ihre Kriegsgefangenen per Schiff ab. Das dürfen wir nicht zulassen! Verwendet die Maulwurfmaschine der Dunkeleisenzwerge, um sie vor Folter und Tod zu bewahren.', '', 28153),
(149465, 'deDE', '', 'Wir müssen dafür sorgen, dass Kiro die Angriffspläne bekommt. Wir haben keine Zeit zu verschwenden. Los!', 28153),
(149464, 'deDE', '', 'Sie hat recht, Arom Kronsteig wurde nach seinem Sieg hier zum Lord erhoben.', 28153),
(149463, 'deDE', '', 'Hm, wenn wir den Befehlen folgen, schafft es keins dieser Monster bis zu Aroms Wehr. Lasst uns helfen.', 28153),
(149462, 'deDE', '', 'Sie denkt, wir sind Teil ihrer Miliz...', 28153),
(149461, 'deDE', '', 'Die Blutopfer müssen aufhör\'n! Dann sin\' wir ein\' Schritt näher dran, den Blutgott aufzuhalt\'n.', 28153),
(149460, 'deDE', '', 'Die dunklen Rituale von Zul\'Nazman hab\'n ihre Verderbnis im Land verbreitet und die Toten zurückgeholt! Läutert ihre Überreste und schenkt den andren Fried\'n!', 28153),
(149459, 'deDE', 'Blut... gott... Ngh!', 'Blut... gott... Ngh!', 28153),
(149458, 'deDE', 'Trefft mich in Atul\'Aman. Die anderen warten drinnen auf uns!', '', 28153),
(149457, 'deDE', 'Wir hör\'n ihn ruf\'n...', 'Wir hör\'n ihn ruf\'n...', 28153),
(149456, 'deDE', 'Ein paar unserer Windreiter stecken in der Klemme. Sucht auf dem Schlachtfeld nach Überlebenden!', '', 28153),
(149455, 'deDE', 'Lasst mich in Ruhe!', 'Lasst mich in Ruhe!', 28153),
(149454, 'deDE', 'Nein, nein, nein, nein!', 'Nein, nein, nein, nein!', 28153),
(149453, 'deDE', 'Geht mir ausm Kopf!', 'Geht mir ausm Kopf!', 28153),
(149452, 'deDE', 'Argh!', 'Argh!', 28153),
(149451, 'deDE', 'Genug!', 'Genug!', 28153),
(149450, 'deDE', 'Ich wünschte, die Treulosen hätten den Frieden mehr zu würdigen gewusst. Wir haben das immer getan.\n\nAber ihre unablässigen Aggressionen haben uns gezwungen zu handeln.\n\nWir werden Imperator Korthek ausschalten... Und wir werden uns alles nehmen, was uns nützlich erscheint.', '', 28153),
(149449, 'deDE', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|tBewegt die Munitionsfässer schnell aus dem Feuer, um zu verhindern, dass %s sie in die Luft jagt!', 28153),
(149448, 'deDE', 'Vorhut! Haltet Euch bereit, Oberst Kronsteig zu unterstützen!', 'Vorhut! Haltet Euch bereit, Oberst Arom zu unterstützen!', 28153),
(149447, 'deDE', 'Für Drustvar und Kul Tiras!', 'Für Drustvar und Kul Tiras!', 28153),
(149446, 'deDE', 'Sie haben uns unsere Söhne und Töchter genommen! Lasst sie dafür büßen!', 'Sie haben uns unsere Söhne und Töchter genommen! Lasst sie dafür büßen!', 28153),
(149445, 'deDE', 'Jetzt ist die Zeit, Eure Vorfahren stolz zu machen!', 'Jetzt ist die Zeit, Eure Vorfahren stolz zu machen!', 28153),
(149444, 'deDE', 'Wir haben sie zurückgedrängt! Nicht nachlassen!', 'Wir haben sie zurückgedrängt! Nicht nachlassen!', 28153),
(149443, 'deDE', 'Bleibt standhaft!', 'Bleibt standhaft!', 28153),
(149442, 'deDE', 'Wir haben den Feind zurückgedrängt!\n\nJetzt steht doch nicht einfach so da. Los jetzt, kämpft!', 'Wir haben den Feind zurückgedrängt!\n\nJetzt steht doch nicht einfach so da. Los jetzt, kämpft!', 28153),
(149441, 'deDE', 'Die ominöse Wolke beginnt zu brodeln, als %s sie berührt!', 'Die ominöse Wolke beginnt zu brodeln, als %s sie berührt!', 28153),
(149440, 'deDE', 'Danke...', 'Danke...', 28153),
(149439, 'deDE', 'Endlich... kann ich ruhen...', 'Endlich... kann ich ruhen...', 28153),
(149438, 'deDE', 'Meine Wacht endet nun...', 'Meine Wacht endet nun...', 28153),
(149437, 'deDE', 'Ich werde... wieder ruhen...', 'Ich werde... wieder ruhen...', 28153),
(149436, 'deDE', 'Meine Pflicht ist getan...', 'Meine Pflicht ist getan...', 28153),
(149435, 'deDE', 'Ich besorge das Fleisch.', 'Ich besorge das Fleisch.', 28153),
(149434, 'deDE', 'Die Kiste gehört mir, $gneugieriger:neugierige:r; $R!\n\nIch brauche die Schlammwürmer für meine Schlammwurmsuppe, aber diese Würmer verstecken sich! Ich habe Geduld und kann hier ein paar Tage warten. Und vielleicht finde ich ja noch ein paar Kisten?\n\nWenn Ihr mir Schlammwurmfleisch bringt, bekommt Ihr diese Kiste.', 'Nein, die Kiste gehört mir!\n\nIch kam hierher, um nach Würmern für eine Suppe zu suchen. Manche Tortollaner behaupten ja, dass Kriecherfleisch das Suppenfleisch schlechthin sei, aber das halte ich für Unsinn. Kriechersuppe ist die Mühe nicht wert, wenn man durch eine Suppe mit einem Fremden Freundschaft schließen möchte.\n\nMit Schlammwurmsuppe kann man hingegen lebenslange Freundschaften aufbauen, und wir Tortollaner leben nun mal sehr lange.\n\nWenn Ihr mir etwas Schlammwurmfleisch findet, gebe ich Euch vielleicht diese Kiste.', 28153),
(149433, 'deDE', 'Diese Kiste?', 'Diese Kiste?', 28153),
(149432, 'deDE', 'Ich habe lange hier gestanden. Dann habe ich diese interessante Kiste im Schlamm gefunden.', 'Ich habe lange hier gestanden. Dann habe ich diese interessante Kiste im Schlamm gefunden.', 28153),
(149431, 'deDE', 'Gut gemacht, Mann. Ich... Ich hätt fast den Verstand verlor\'n. Mein Geist is\' langsam verdorrt, so langsam wie \'ne tortollanische Karawane.', 'Gut gemacht, Mann. Ich... Ich hätt fast den Verstand verlor\'n. Mein Geist is\' langsam verdorrt, so langsam wie \'ne tortollanische Karawane.', 28153),
(149430, 'deDE', 'Ich dank Euch, Fremdling.', 'Ich dank Euch, Fremdling.', 28153),
(149429, 'deDE', 'Endlich Frieden. Danke.', 'Endlich Frieden. Danke.', 28153),
(149428, 'deDE', 'Jetz\' kann ich endlich wieder ruh\'n. Danke, Fremdling.', 'Jetz\' kann ich endlich wieder ruh\'n. Danke, Fremdling.', 28153),
(149427, 'deDE', 'Es is\' vorbei...', 'Es is\' vorbei...', 28153),
(149426, 'deDE', 'Wie lautet der Plan?', 'Wie lautet der Plan?', 28153),
(149425, 'deDE', '', 'Ich dachte schon an elektrische Schocks oder Feuer, aber vielleicht jagen wir ihn ja auch einfach in die Luft!\n\nAber es soll Unglück bringen, einen Tortollaner zu töten, und ich kann wirklich kein Pech mehr brauchen.\n\nZeigt mir, was Ihr mit diesem Tortollaner machen würdet, ja?', 28153),
(149424, 'deDE', '', 'Wir haben da ein Problem, $p. Der Tortollaner hat eine Kiste gefunden, die wir haben wollen!', 28153),
(149423, 'deDE', 'Verfluchter Sumpf! Wegen der hohen Luftfeuchtigkeit fällt hier alles auseinander.\n\nNun, womit kann ich dienen? Na los, raus mit der Sprache! Ich muss schließlich meine Reparaturen fortsetzen.', 'Verfluchter Sumpf! Wegen der hohen Luftfeuchtigkeit fällt hier alles auseinander.\n\nNun, womit kann ich dienen? Na los, raus mit der Sprache! Ich muss schließlich meine Reparaturen fortsetzen.', 28153),
(149422, 'deDE', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'deDE', 'Nur die arrogantesten Narren würden die Amani innerhalb ihrer Mauern dulden. Gute Arbeit, Champion.', '', 28153),
(149420, 'deDE', 'Nur ein toter Amani ist ein guter Amani. Und doch haben ihnen die Zandalari in der Stadt Zuflucht gewährt. Bezwingt ihre Jünger! Für die Allianz!', '', 28153),
(149419, 'deDE', 'Die Bestie ist erledigt! Aschenwind, sichert die oberen Stockwerke ab! Ich kümmere mich um diesen Dieb...', 'Die Bestie ist erledigt! Aschenwind, sichert die oberen Stockwerke ab! Ich kümmere mich um diesen Dieb...', 28153),
(149418, 'deDE', 'Solange ich lebe, werde ich nicht zulassen, dass diese Bastion fällt!', '', 28153),
(149417, 'deDE', 'Damit sollten wir sie wieder in ihre Schranken verwiesen haben.', '', 28153),
(149416, 'deDE', '<Zeigt Kellmann den Liedstein.>', '<Zeigt Kellmann den Liedstein.>', 28153),
(149415, 'deDE', 'Der Amanistamm täte gut daran, die Stärke der Horde in Zuldazar nicht zu vergessen. Helft doch ihrer Erinnerung auf die Sprünge. Schlagt den Gong und besiegt ihre Jünger.', '', 28153),
(149414, 'deDE', 'Ich gehe voraus, um nach den Bauern zu suchen. Lasst Euch bloß nicht gefangennehmen!', '', 28153),
(149413, 'deDE', '', 'Taz\'dingo!', 28153),
(149411, 'deDE', 'In diesem Schlamm sind jede Menge Schätze. Ihr werdet mit Moxie zusammenarbeiten, um nach ihnen zu suchen!', '', 28153),
(149410, 'deDE', 'Nein! Die Kroggs... dürfen nicht befreit werden...', '', 28153),
(149409, 'deDE', 'Auf in die Schlacht!', 'Auf in die Schlacht!', 28153),
(149408, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(149407, 'deDE', 'Wir kämpfen gemeinsam.', 'Wir kämpfen gemeinsam.', 28153),
(149406, 'deDE', 'Ich kämpfe an Eurer Seite.', 'Ich kämpfe an Eurer Seite.', 28153),
(149405, 'deDE', 'Ich stehe in Eurer Schuld, $n.', 'Ich stehe in Eurer Schuld, $n.', 28153),
(149404, 'deDE', 'Das Ritual ist noch nicht beendet. Die Kroggs müssen gebändigt werden!', '', 28153),
(149403, 'deDE', 'Führt den Angriff weiter. Ich komme schon zurecht.', '', 28153),
(149402, 'deDE', '', 'Meine Stärke... was... passiert?', 28153),
(149401, 'deDE', '', 'Mein Körper... Ich kann nich\'... Argghh!', 28153),
(149400, 'deDE', 'Nun gut.', 'Nun gut.', 28153),
(149399, 'deDE', '', 'Die Arbeiter sagen, sie hören Stimmen im Schlamm. Einige von ihnen hat es wahnsinnig gemacht!\n\nIch hör da gar nicht hin!', 28153),
(149398, 'deDE', '', 'Gewisse Leute aus Kul Tiras bringen mich aus irgendeinem Grund mit bestimmten Raubüberfällen in Verbindung, über die ich wirklich rein gar nichts weiß.', 28153),
(149397, 'deDE', '', 'Ich segle... in unbekannte Gewässer...', 28153),
(149396, 'deDE', '', 'Der hier benimmt sich, als hätte er noch nie zuvor einen Gnom gesehen!', 28153),
(149395, 'deDE', '', 'Jetzt reicht\'s!', 28153),
(149394, 'deDE', '', 'Dezimierergeschosse... FEUER!', 28153),
(149393, 'deDE', '', 'Fresst Blei, Ihr Maden!', 28153),
(149392, 'deDE', '', 'Ich schneid Euch in kleine Scheibchen!', 28153),
(149391, 'deDE', '', 'Alle Mann von Deck!', 28153),
(149390, 'deDE', 'Zandalari... nix als leere Versprechungen.', 'Zandalari... nix als leere Versprechungen.', 28153),
(149389, 'deDE', 'Ihr werdet von meinem Loa hör\'n...', 'Ihr werdet von meinem Loa hör\'n...', 28153),
(149388, 'deDE', 'Wir sin\' nirgendwo mehr sicher.', 'Wir sin\' nirgendwo mehr sicher.', 28153),
(149387, 'deDE', 'In ihrer eig\'nen Stadt... lass\'n sie uns verreck\'n.', 'In ihrer eig\'nen Stadt... lass\'n sie uns verreck\'n.', 28153),
(149386, 'deDE', 'Was soll jetz\' aus uns werd\'n?', 'Was soll jetz\' aus uns werd\'n?', 28153),
(149385, 'deDE', 'Das Imperium... is\' nun endgültig gefall\'n.', 'Das Imperium... is\' nun endgültig gefall\'n.', 28153),
(149384, 'deDE', 'Wie konnt\'n sie... das zulass\'n?', 'Wie konnt\'n sie... das zulass\'n?', 28153),
(149383, 'deDE', 'Die Zandalari... ham uns versproch\'n, dass wir in Sicherheit sin\'...', 'Die Zandalari... ham uns versproch\'n, dass wir in Sicherheit sin\'...', 28153),
(149382, 'deDE', 'Endlich! Jemand hat meine Opfergabe an Bwonsamdi gefund\'n. Nutzt sie weise!', 'Endlich! Jemand hat meine Opfergabe an Bwonsamdi gefund\'n. Nutzt sie weise!', 28153),
(149381, 'deDE', '', 'Bringt mir ihre Daumen und macht mit dem Rest, was Ihr wollt.', 28153),
(149380, 'deDE', '', 'Ich bekomme Euren Anteil, wenn Ihr sterbt!', 28153),
(149379, 'deDE', '', 'Euer Kopf wird sich großartig in meiner Sammlung mach\'n.', 28153),
(149378, 'deDE', '', 'Wir beide sind doch jetzt richtig gute Freunde. Kann ich mir etwas Gold leihen?', 28153),
(149377, 'deDE', '', 'In Tol Dagor habe ich mal jemanden gesehen, der genauso aussah wie Ihr.', 28153),
(149376, 'deDE', 'Ihr macht da \'nen groß\'n Fehler!', 'Ihr macht da \'nen groß\'n Fehler!', 28153),
(149375, 'deDE', 'Hilfe! Die Terrasse wird angegriff\'n!', 'Hilfe! Die Terrasse wird angegriff\'n!', 28153),
(149374, 'deDE', 'Schnappt sie Euch!', 'Schnappt sie Euch!', 28153),
(149373, 'deDE', 'Ihr habt hier nix zu such\'n, Mann!', 'Ihr habt hier nix zu such\'n, Mann!', 28153),
(149372, 'deDE', 'Weg hier! Zandalar gehört den Troll\'n!', 'Weg hier! Zandalar gehört den Troll\'n!', 28153),
(149371, 'deDE', 'Hab ich\'s doch geroch\'n, dass hier was faul is\'...', 'Hab ich\'s doch geroch\'n, dass hier was faul is\'...', 28153),
(149370, 'deDE', 'Zu Hilfe! Ich werd angegriff\'n!', 'Zu Hilfe! Ich werd angegriff\'n!', 28153),
(149369, 'deDE', 'Dreckiger Bastard!', 'Dreckiger Bastard!', 28153),
(149368, 'deDE', 'Coda plappert und schaut in die Schlucht hinab.', '', 28153),
(149367, 'deDE', '', 'Ich mache mir auch Sorgen, Coda.', 28153),
(149366, 'deDE', 'Ich möchte zum Osthafen.', 'Ich möchte zum Osthafen.', 28153),
(149365, 'deDE', '', 'Wo wollt Ihr hin?', 28153),
(149364, 'deDE', '', 'Habt Dank! Und bitte drückt Poda ganz fest von mir!', 28153),
(149363, 'deDE', '', 'Alle Kanonen... FEUER!', 28153),
(149362, 'deDE', 'Die Werft wird Euer neues Zuhause sein.', '', 28153),
(149361, 'deDE', 'Ihr alle werdet Lord Sturmsang in der Werft dienen.', '', 28153),
(149360, 'deDE', 'Alle Mann in die Wagen.', '', 28153),
(149359, 'deDE', 'Die Bluttrolle bedrohen wieder einmal meine Kinder!$B$BKommt, kleine Kreatur. Erinnern wir sie gemeinsam daran, was passiert, wenn man Krag\'wa verärgert!', '', 28153),
(149358, 'deDE', '', 'Die Stadt gehört uns!', 28153),
(149357, 'deDE', '', 'Ich häng mir Eure Gedärme an den Mast.', 28153),
(149356, 'deDE', '', 'Einer mehr auf meinem Kerbholz!', 28153),
(149355, 'deDE', '', 'Alle Mann... ANGRIFF!', 28153),
(149354, 'deDE', '', 'Macht keine Gefangenen!', 28153),
(149353, 'deDE', 'Ihr Warten hat beinahe ein Ende.', '', 28153),
(149352, 'deDE', 'Wie viel Zeit bleibt noch?', 'Wie viel Zeit bleibt noch?', 28153),
(149351, 'deDE', 'Die Eisenfluträuber greifen uns jeden Tag an. Und auch eine Armee der Horde ist auf dem Weg hierher. Nicht mehr lange, dann muss unser ganzes Dorf fliehen.', '', 28153),
(149348, 'deDE', 'Ich werd das Ritual vollend\'n... mit Euerm Blut!', '', 28153),
(149347, 'deDE', 'Okay.', 'Okay.', 28153),
(149346, 'deDE', 'Gescheitert? Nein...', '', 28153),
(149345, 'deDE', 'Auf dem morastigen Grund des Sees befindet sich ein riesiger Goldschatz. Ein versunkenes Schiff voller Gold aus dem Zweiten Krieg!\n\nDas ganze Dorf arbeitet zusammen, um den Schatz zuerst zu finden. Die Zeit ist allerdings knapp, wir müssen uns beeilen!', '', 28153),
(149344, 'deDE', 'Lith qul\'shoth wshh... yzsh uovssh qvask.', '', 28153),
(149343, 'deDE', '', 'Es is\' vorbei, Jakra\'zet. Euer Plan is\' gescheitert!', 28153),
(149341, 'deDE', 'Ihr kämpft an der Oberfläche... doch er wartet in der Tiefe.', '', 28153),
(149340, 'deDE', '', 'Gerade noch rechtzeitig, um Euch aufzuhalt\'n!', 28153),
(149339, 'deDE', 'Ihr kommt gerade zur recht\'n Zeit...', '', 28153),
(149338, 'deDE', '', 'Juhu! Sie sind alle nach Hause gelaufen!', 28153),
(149337, 'deDE', 'Das Ritual des Blutes is\' fast vollendet!', '', 28153),
(149336, 'deDE', '', 'Bitte beeilt Euch und findet sie! Coda wird am Boden zerstört sein, wenn er seine Familie verliert.', 28153),
(149335, 'deDE', 'Schatz?', 'Schatz?', 28153),
(149334, 'deDE', 'Die Eisenfluträuber nehmen alle gefangen. Sie versuchen zu verhindern, dass wir den Schatz zuerst finden!', '', 28153),
(149333, 'deDE', '', 'Kommt zurück, meine Kleinen! Wir können euch helfen!', 28153),
(149332, 'deDE', '', 'Wenn wir da reingehen, werden sie uns auch mit ihren Stacheln erwischen!', 28153),
(149331, 'deDE', '', 'Ich kann sie nicht sehen, Coda!', 28153),
(149330, 'deDE', 'Zaix lal sk\'woth\'gl Zaix lal uulwi.', '', 28153),
(149329, 'deDE', 'Die Eisenfluträuber nehmen Gefangene. Wir könnten Eure Hilfe brauchen!', '', 28153),
(149328, 'deDE', 'Sie sind die Erlösung. Sie sind die Wahrheit.', '', 28153),
(149327, 'deDE', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg.', '', 28153),
(149326, 'deDE', 'Ihr werdet alle im lichtlosen Abgrund ertrinken.', '', 28153),
(149325, 'deDE', '', 'Wenn es nicht explodiert, probiert es noch mal.', 28153),
(149323, 'deDE', 'Nein. Ich habe Befehle, Euch zum Kriegshäuptling zurückzugeleiten.', '', 28153),
(149322, 'deDE', '', 'Tja, das is\' mein Schiff, also werdet Ihr Eure Pläne wohl ändern müss\'n.', 28153),
(149321, 'deDE', 'Das könn\' wir unterwegs diskutier\'n, Eure Hoheit.', '', 28153),
(149320, 'deDE', '', 'Kommt. Wir segeln nach Zuldazar.', 28153),
(149319, 'deDE', 'Ich glaub, das Wort, das Ihr sucht, is\' \"Danke\".', '', 28153),
(149318, 'deDE', 'Mir scheint, die Hilfe von \'nem Magier mit Euern... Fähigkeit\'n... käme grade sehr geleg\'n.', '', 28153),
(149317, 'deDE', '', 'Nein... Das kann nicht sein.', 28153),
(149315, 'deDE', 'Ihr könnt uns überwältig\'n un\' vermutlich auch töt\'n.', '', 28153),
(149314, 'deDE', 'Ich weiß, Ihr seht die Flamm\', die Eure Stadt verschlingen.', '', 28153),
(149313, 'deDE', 'Nur nich\' so voreilig.', '', 28153),
(149312, 'deDE', '', 'Dann sterbt.', 28153),
(149311, 'deDE', 'Bei allem Respekt, wir verpassen unser Schiff.', '', 28153),
(149310, 'deDE', '', 'Ergebt Euch, und ich bringe Euch ins Verlies zurück, wo Ihr hingehört. Dort wartet Ihr auf das Urteil des Königs.', 28153),
(149309, 'deDE', 'Wartet hier.', '', 28153),
(149307, 'deDE', 'Dafür wurde gesorgt. Seht selbst.', '', 28153),
(149306, 'deDE', 'Hört auf zu gaffen und durchbrecht das Eis!', '', 28153),
(149305, 'deDE', 'Ich kenn zwar kein\' Rezan, aber ich schulde ihm mein\' Dank.', '', 28153),
(149303, 'deDE', '', 'Sterbt, Hordenabschaum!', 28153),
(149302, 'deDE', '', 'Sie blockiert unseren Fluchtweg!', 28153),
(149300, 'deDE', '', 'Ich brauch zwanzig dieser Vögel.', 28153),
(149299, 'deDE', 'Aha! Lasan, der schlaue Elchmacka!', '', 28153),
(149298, 'deDE', 'Nein... Aber ich glaube, ich weiß, warum. Seht.', '', 28153),
(149297, 'deDE', 'Wer Euch ärgert, dem soll\'n die Loa beisteh\'n, Zul.', '', 28153),
(149296, 'deDE', '', 'Ihr habt viele Unschuldige getötet. Aber hier endet Euer kleiner Ausbruch.', 28153),
(149295, 'deDE', '', 'Sie folgen uns nicht?', 28153),
(149294, 'deDE', 'Hahahaha!', '', 28153),
(149292, 'deDE', '', 'Ihre Streitkräfte müssen aus Lordaeron zurück sein. Wie überwinden wir so viele?', 28153),
(149291, 'deDE', 'Gehen wir!', '', 28153),
(149290, 'deDE', '', 'Mein Loa erhört uns. Mächtiger Rezan, leiht mir Eure Kraft!', 28153),
(149289, 'deDE', '', 'Ihr werdet in dieser Stadt keinem mehr Leid zufügen!', 28153),
(149288, 'deDE', '', 'Bis hierher und nicht weiter!', 28153),
(149287, 'deDE', 'Achtung. Die Vorzeigediplomatin der Allianz scheint diesmal keine Gefangenen zu machen.', '', 28153),
(149286, 'deDE', 'Huaa!', '', 28153),
(149285, 'deDE', '', 'Ihr habt Mama gefunden! Vielen Dank, dass Ihr sie vor den gruseligen Monstern gerettet habt!', 28153),
(149284, 'deDE', '', 'Danke, dass Ihr mir mein Spielzeug gebracht habt. Wenn Ihr meine Mama seht, könnt Ihr sie vielleicht bitten, dass sie wieder nach Hause kommt?\n\nIch hab sie nämlich lange nicht gesehen.', 28153),
(149283, 'deDE', 'Und jetzt. Zerbrecht das letzte Siegel.', '', 28153),
(149282, 'deDE', '', 'Talanji, Ihr un\' Euer Champion verfolgt Zul. Ich werd alle zusammentromm\'ln, die ich find\'n kann, un\' versuch\'n, den Auflöser aufzuhalt\'n. Wir werd\'n \'ne ganze Armee brauch\'n, um den zu erledig\'n.', 28153),
(149281, 'deDE', 'Er befehligt Mythrax. Wir müssen den Diener des schwarzen Imperiums aufhalten.', '', 28153),
(149280, 'deDE', '', 'Champion, die Loa un\' ich werden Mythrax so lang wie möglich aufhalten. Findet mein\' Vater un\' macht Zul den Garaus!', 28153),
(149279, 'deDE', 'Kommt, Mythrax! Kommt, Auflöser! Das letzte Siegel muss gebroch\'n werden.', '', 28153),
(149278, 'deDE', 'Der Weg ist frei, kleine Wesen. Und jetzt los. Mythrax kommt.', '', 28153),
(149277, 'deDE', '', 'Brüder un\' Schwestern von Zandalar, hol\'n wir uns unsre Stadt zurück! Vorwärts!', 28153),
(149276, 'deDE', '', 'Champion, sucht alle Bewohner, die noch aufm Zocalo sin\', un\' schickt sie zu uns. Wir folg\'n Euch möglichst bald.', 28153),
(149275, 'deDE', '', 'Gar nich\' gut. Die Loa tun, was sie könn\', aber wir müss\'n jedem fähig\'n Troll \'nen Speer in die Hand drück\'n.', 28153),
(149274, 'deDE', '', 'Dunkle Zeiten erfordern große Tat\'n. Wie sieht\'s denn aus?', 28153),
(149273, 'deDE', '', 'Talanji, ich seh, Ihr reitet auf\'m Loa in die Schlacht.', 28153),
(149272, 'deDE', '', 'Rakera, ich seh, Ihr übernehmt den Befehl über unsre Trupp\'n.', 28153),
(149271, 'deDE', '', 'Formation einnehm\'! Kriegsbögen in Anschlag.', 28153),
(149270, 'deDE', '', 'Das... kommt ungelegen.', 28153),
(149269, 'deDE', '', 'Der Champion berichtet, dass Mythrax der Auflöser erwacht is\'.', 28153),
(149268, 'deDE', '', 'Etwas treibt die Sethrak zum Angriff. Sie schwärmen aus wie noch nie zuvor.', 28153),
(149267, 'deDE', '', 'Sei vorsichtig, Vater! Diese Pläne hat ein unberech\'nbarer Feind sehr lang geschmiedet.', 28153),
(149266, 'deDE', 'Talanji, nimm den Hordechampion un\' sammel unsre Streitkräfte. Ich arbeite mit Krag\'wa dran, die Spanne zu sichern.', '', 28153),
(149265, 'deDE', '', 'Rastakhan! Die Schlangen Vol\'duns attackieren Eure Westgrenze. Unternehmt etwas.', 28153),
(149264, 'deDE', 'Es komm\' zu viele an uns vorbei. Zur Brücke nach Dazar\'alor! Wir zwing\'n die in \'ne Engstelle.', '', 28153),
(149263, 'deDE', 'Ein Geschenk für den gut\'n Bwonsamdi.', '', 28153),
(149262, 'deDE', 'Sterbt, Eindringlinge!', '', 28153),
(149261, 'deDE', 'Es sin\' so viele.', '', 28153),
(149260, 'deDE', 'Das Bluttor wurde überrannt. Schnell, wir müss\'n so viele von den Angreifern töt\'n wie möglich, bevor die die Stadt erreich\'n.', '', 28153),
(149259, 'deDE', '', 'Ihr könnt den Sturm... nicht aufhalten...', 28153),
(149258, 'deDE', '', 'Ihr könnt das Imperium der Treulosen nicht aufhalten.', 28153),
(149257, 'deDE', 'Ich finde schon raus. Seid vorsichtig!', '', 28153),
(149256, 'deDE', 'Danke... Ich dachte, ich bin erledigt.', '', 28153),
(149255, 'deDE', 'Das sollte genügen. Wie fühlt es sich an, im Alleingang eine ganze Stadt einzunehmen, $n?', '', 28153),
(149254, 'deDE', 'Lauft... LAUFT!!!', '', 28153),
(149253, 'deDE', 'Es ist noch zu früh. Er ist noch nicht im Ruhm des Meisters ertrunken!', '', 28153),
(149252, 'deDE', 'Nein, nein, nein! Die Stadt ist im Aufruhr! Ich bringe uns hier raus.', '', 28153),
(149250, 'deDE', 'Probiert es mal mit dem Dolch, den ich Euch zugesteckt habe. Ich glaube, er wird Euch gefallen.', '', 28153),
(149249, 'deDE', 'Nach Euch, $n. Ihr markiert die sicheren Ziele, ich schalte sie aus.', '', 28153),
(149248, 'deDE', 'Sobald Vertrauen einmal gebrochen wurde, lässt es sich kaum mehr wiederherstellen. Das wird der Hoheit der Zandalari schaden. Gut gemacht, Champion.', '', 28153),
(149247, 'deDE', 'Abgesandte der kleineren Trollstämme versammeln sich unter dem Schutz der Zandalari, aber sie sind verwundbar. Tötet die Sprecher und sät Zweitracht unter unseren Feinden.', '', 28153),
(149246, 'deDE', 'Steckt Ihre Wagen in Brand und brecht ihnen alle Knochen!', 'Steckt Ihre Wagen in Brand und brecht ihnen alle Knochen!', 28153),
(149245, 'deDE', 'Wenn dieses Ungeziefer den Schlüssel versteckt hält, werden wir ihn finden!', 'Wenn dieses Ungeziefer den Schlüssel versteckt hält, werden wir ihn finden!', 28153),
(149244, 'deDE', 'Verschont die Starken. Sie werden sich auf dem Markt gut verkaufen.', 'Verschont die Starken. Sie werden sich auf dem Markt gut verkaufen.', 28153),
(149243, 'deDE', 'Ist es bald vorbei? Bitte sagt mir, es ist bald vorbei!', '', 28153),
(149242, 'deDE', 'Kommt zurück!', 'Kommt zurück!', 28153),
(149241, 'deDE', '', 'Wir sollten uns zum Grat in nordwestlicher Richtung bewegen. Von dort sollte Aroms Wehr unser Signal gut erkennen.', 28153),
(149240, 'deDE', '', 'Aber bevor wir gehen, sollten wir die Gunst der Stunde nutzen und ihre Armee etwas aufreiben.', 28153),
(149239, 'deDE', '', 'Vom Grat im Nordwesten können wir Signal setzen, um abgeholt zu werden.', 28153),
(149238, 'deDE', 'Das ist Wahnsinn! Nicht so schnell!', '', 28153),
(149237, 'deDE', 'Das erdbebenartige Stampfen ist ganz köstlich!', '', 28153),
(149236, 'deDE', '', 'Die Waffe des Zirkels gegen sie zu richten, birgt eine gewisse Befriedigung.', 28153),
(149235, 'deDE', 'Das Feuer brennt und violetter Rauch steigt auf. Sie sollten ihn schon bald über den Baumkronen sehen können.', '', 28153),
(149234, 'deDE', 'Lasst mich den anderen zuerst das Angriffssignal geben.', '', 28153),
(149233, 'deDE', 'Nein. Mit der Zeit komm\' sie schon zu uns.', '', 28153),
(149232, 'deDE', '', 'Soll\'n wir sie verfolg\'n?', 28153),
(149231, 'deDE', 'Keine Verträge mehr mit Fremd\'n. Keine Geschäfte mehr mit Loa. Das Blut is\' jetz\' unser Weg... der Weg von G\'HUUN!', '', 28153),
(149230, 'deDE', 'Ich hab grad kein\' Hunger. Kommt später wieder...', '', 28153),
(149229, 'deDE', 'Würdet Ihr mir glauben, wenn ich sage, alles verläuft nach Plan? ... Hab ich auch nicht erwartet.', '', 28153),
(149228, 'deDE', 'Gute Nachrichten! Ich hab den Feind gefunden. Er hat uns umzingelt.', '', 28153),
(149227, 'deDE', 'Können... können wir das Rosen bitte verschweigen?', '', 28153),
(149226, 'deDE', 'Da hab ich mich ja richtig mit Ruhm bekleckert.', '', 28153),
(149225, 'deDE', 'Lauscht meiner Prophezeiung: Das Trollimperium wird die Welt beherrsch\'n, am Ende wie zu Beginn. Und auf\'m Thron soll ER als König sitz\'n, am Ende wie zu Beginn. Doch weder Ihr noch ich werd\'n es in diesem Leben bezeug\'n. Das is\' die Vision MEINES Gottes...', '', 28153),
(149224, 'deDE', 'Ihr seid träg geword\'n. Ihr habt unser Königreich verrott\'n un\' verfall\'n lass\'n. Ich hab vorhergeseh\'n, wie sich das Trollimperium wieder erhebt.', '', 28153),
(149223, 'deDE', 'Ihr hättet auf Talanji hör\'n soll\'n.', '', 28153),
(149221, 'deDE', 'Nein! Habutu!', '', 28153),
(149220, 'deDE', 'Haha! Ein kühnes Manöver.', '', 28153),
(149219, 'deDE', 'Die Stunde des Blutes is\' bald gekomm\'.', '', 28153),
(149218, 'deDE', 'Die Zeit der Loa... is\' um.', '', 28153),
(149217, 'deDE', 'Ich bin Euch nich\' untertan.', '', 28153),
(149216, 'deDE', 'Rezan, Rezan...', '', 28153),
(149215, 'deDE', 'Hütet Eure Zunge, Verräter.', '', 28153),
(149214, 'deDE', 'Ah, er ist hier – der Loa des... hmm...', '', 28153),
(149212, 'deDE', '', 'Wehe Eure Vision\' sin\' nich\' wahr.', 28153),
(149211, 'deDE', 'Ketzer!', '', 28153),
(149210, 'deDE', '', 'Erahnt den nächsten Zug Eures Partners!', 28153),
(149209, 'deDE', '', 'Schlagt blitzschnell zu! Und pariert!', 28153),
(149208, 'deDE', '', 'Ihr dürft Euch erst ausruhen, wenn Ihr Eure Übungen abgeschlossen habt!', 28153),
(149207, 'deDE', '', 'Konzentriert Euch auf Euren Partner! Schlagt hart und gezielt zu!', 28153),
(149206, 'deDE', 'Kommandantin! Sie ist einfach... zusammengebrochen?!', 'Kommandantin! Sie ist einfach... zusammengebrochen?!', 28153),
(149205, 'deDE', 'Ist alles in Ordnung, Schwester?! Ich wollte nicht so hart zuschlagen!', 'Ist alles in Ordnung, Schwester?! Ich wollte nicht so hart zuschlagen!', 28153),
(149204, 'deDE', 'Meine Güte! Habe ich da etwa... Ist alles in Ordnung?!', 'Meine Güte! Habe ich da etwa... Ist alles in Ordnung?!', 28153),
(149200, 'deDE', 'Es gibt doch nichts befriedigenderes, als einen Kommandanten der Allianz auszuschalten. Vor allem, wenn es so einfach geht...', '', 28153),
(149199, 'deDE', '', 'Günstige Winde, $n.', 28153),
(149198, 'deDE', '', 'Der Glutorden trotzt ein weiteres Mal Gorak Tul. Und mit Verbündeten werden wir auch weiterhin standhalten.', 28153),
(149197, 'deDE', '', 'Habt Dank für Eure Unterstützung, $n. Ich werde Fräulein Luzilla von unserem Erfolg berichten.', 28153),
(149196, 'deDE', 'Mir schaudert vor dem Schicksal, das mich erwartet hätte, wärt Ihr und die Inquisitorin nicht gewesen.', '', 28153),
(149195, 'deDE', 'Nicht tot zu sein sagt mir sehr zu.', '', 28153),
(149194, 'deDE', '', 'Der Wald kann jetzt gefahrlos überflogen werden. Ich hoffe nur, sie beeilen sich.', 28153),
(149193, 'deDE', '', 'Unsere Greifenreiter warten nur auf dieses Signal.', 28153),
(149192, 'deDE', 'Das war an Schlampigkeit nicht zu überbieten. Seid nächstes Mal leiser!', '', 28153),
(149191, 'deDE', 'Verdammt! Das sollte ein schneller und lautloser Angriff sein! Konzentriert Euch!', '', 28153),
(149190, 'deDE', 'Schnell, erledigt den hier, bevor er die anderen alarmiert!', '', 28153),
(149189, 'deDE', 'Lasst Euch nicht entdecken! Wir dürfen nicht zu viel Aufmerksamkeit erregen...', '', 28153),
(149187, 'deDE', 'Ahhh, nein. Der gehört mir.', '', 28153),
(149186, 'deDE', 'Da drücke ich mal beide Augen zu. Ich kann nicht behaupten, schon mal jemanden im Schlaf getötet zu haben.', '', 28153),
(149185, 'deDE', 'Hey, seid vorsichtig bei Zivilisten, sonst macht Ihr noch die Wachen auf uns aufmerksam.', '', 28153),
(149184, 'deDE', 'Das war zwar keine Wache, aber ich werde uns bestimmt nicht daran hindern, Allianzmitglieder umzubringen.', '', 28153),
(149183, 'deDE', 'Genau genommen müssen wir die Zivilisten nicht töten, aber Euer Stil gefällt mir.', '', 28153),
(149182, 'deDE', 'Ihr seid eiskalt... Das gefällt mir.', '', 28153),
(149181, 'deDE', 'Einer unserer Ingenieure hat Allianzler in der Nähe unserer Mine gesehen. Besucht Margie in der Werkstatt, um mehr zu erfahren und Euch... äh, zu rüsten.', '', 28153),
(149180, 'deDE', 'Meine Brust ist... Ich kann nicht atmen!', 'Meine Brust ist... Ich kann nicht atmen!', 28153),
(149179, 'deDE', 'Mein Hals... schnürt sich zusammen!', 'Mein Hals... schnürt sich zusammen!', 28153),
(149178, 'deDE', 'Ich glaube, ich muss mich übergeben...', 'Ich glaube, ich muss mich übergeben...', 28153),
(149177, 'deDE', 'Muss nur... ausruhen...', 'Muss nur... ausruhen...', 28153),
(149176, 'deDE', 'Es ist so... dunkel...', 'Es ist so... dunkel...', 28153),
(149175, 'deDE', 'Mir ist... anders.', 'Mir ist... anders.', 28153),
(149174, 'deDE', 'Nein! Neeeein!!', '', 28153),
(149173, 'deDE', 'W– was?!', '', 28153),
(149172, 'deDE', 'Ihr da! Stehenbleiben!', '', 28153),
(149171, 'deDE', '', 'Is\' ja, als freu\'n die sich auf\'n Tod... Kann nur hoff\'n, dass Ihr Blut G\'huun nich\' irgendwie stärkt.', 28153),
(149170, 'deDE', '', 'Sie trotz\'n Bwonsamdi noch immer, das wird kein gutes Ende für sie nehm\'. Champion, unser Pakt mit Bwonsamdi gilt noch. Schickt ihm diese verirrten Seel\'n!', 28153),
(149169, 'deDE', 'Nein, wartet. War nur mein andres Bein. Alles in Butter.', '', 28153),
(149168, 'deDE', 'Irgendwas hat mich am Bein berührt!', '', 28153),
(149167, 'deDE', 'Die Großfuhre ist wohlbehalten angekommen. Holt Euch Euren Anteil!', '', 28153),
(149166, 'deDE', 'Unsere Minenarbeiter sind auf eine Ader gestoßen. Bringt die Ausbeute wohlbehalten in unsere Basis – davon profitieren wir alle.', '', 28153),
(149165, 'deDE', '', 'Gehen wir! Ich werde Euch gut im Auge behalten.', 28153),
(149164, 'deDE', '', 'Man kann nie zu viel Sprengstoff verwenden!', 28153),
(149163, 'deDE', '', 'Kennt Ihr irgendwelche Adligen von Kul Tiras mit viel Gold und schlechten Sicherheitsvorkehrungen?', 28153),
(149162, 'deDE', '', 'Ich suche nach schlauen Leuten wie Euch, $p, um viel Gold in ein neues Geschäft zu investieren, das ich aufziehen will.', 28153),
(149161, 'deDE', '', 'Als Gnom muss man bei diesen Kul Tiranern gut auf sich aufpassen!', 28153),
(149160, 'deDE', '', 'Im Zweifelsfall einfach in die Luft jagen!', 28153),
(149159, 'deDE', '', 'Tol Barad, Tol Dagor, das Verlies von Sturmwind... Hab ich alles gesehen!', 28153),
(149158, 'deDE', 'Gebt das Signal. Verschwinden wir von hier!', 'Gebt das Signal. Verschwinden wir von hier!', 28153),
(149157, 'deDE', '', 'Bitte, Rakera! Geht nich\'! Sie werd\'n Euch umbringen!', 28153),
(149156, 'deDE', '', 'Den Sanden sei Dank, Euch geht\'s gut!', 28153),
(149155, 'deDE', '', 'Hier is\' Schluss. Von Euch wird keiner die Meisterin stör\'n.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'deDE', 'Diese kleinen Kerle dürften wohl kaum eine Bedrohung darstellen, $R.', '', 28153),
(149151, 'deDE', '', 'Ihr lebt noch, $p! Dann seid Ihr genauso ein Glückspilz wie ich.', 28153),
(149150, 'deDE', 'Wir seh\'n uns später.', '', 28153),
(149149, 'deDE', 'Das war\'s?', '', 28153),
(149148, 'deDE', 'Entspannt bleib\'n, Mann.', '', 28153),
(149147, 'deDE', 'Kein Problem, Freundchen.', '', 28153),
(149146, 'deDE', 'Braucht Ihr \'n bisschen Voodoo?', '', 28153),
(149145, 'deDE', 'Was wollt Ihr?', '', 28153),
(149144, 'deDE', '', 'Die Bluttrolle leg\'n uns nie wieder rein. Nich\' solang ich noch leb.', 28153),
(149143, 'deDE', '', 'Die Bluttrolle versuch\'n, sich an uns anzuschleich\'n. Ich hab was, womit Ihr sie seh\'n könnt. Nutzt das un\' tötet sie.', 28153),
(149142, 'deDE', 'Holt erst einmal Luft. Wir werden nicht anhalten, bis wir das Schiff erreicht haben.', '', 28153),
(149141, 'deDE', 'Weg hier! Ich will bloß noch weg hier!', 'Weg hier! Ich will bloß noch weg hier!', 28153),
(149140, 'deDE', 'Zul bringt uns noch alle ums Leb\'n.', 'Zul bringt uns noch alle ums Leb\'n.', 28153),
(149139, 'deDE', 'Das is\' das Ende!', 'Das is\' das Ende!', 28153),
(149138, 'deDE', 'Das is\' gar nich\' gut fürs Geschäft.', 'Das is\' gar nich\' gut fürs Geschäft.', 28153),
(149137, 'deDE', 'Ich verschwind von hier!', 'Ich verschwind von hier!', 28153),
(149136, 'deDE', 'Hey! Was geht da drin vor?!', '', 28153),
(149135, 'deDE', 'WACHE! WACHE, HILFE!! OOOH!!', '', 28153),
(149134, 'deDE', 'AU! AH, MIESER SCHLÄGER!', '', 28153),
(149133, 'deDE', 'Nicht so schüchtern! Voll auf die Zwölf!', '', 28153),
(149132, 'deDE', 'Na los, schlagt mich!', '', 28153),
(149131, 'deDE', 'Schlagt mich.', '', 28153),
(149130, 'deDE', 'Na gut, das ist der Plan:', '', 28153),
(149129, 'deDE', 'Dritter Eintrag: Ich habe es fast geschafft! Die Bienen wachsen, ihre Produktivität nimmt exponentiell zu. Die Königin werde ich aber beobachten müssen.', '', 28153),
(149128, 'deDE', 'Zweiter Eintrag: Der belebte Met zeigt Anzeichen von Aggression. Vielleicht ist mir bei meinen Berechnungen ein kleiner Fehler unterlaufen.', '', 28153),
(149127, 'deDE', 'Erster Eintrag: Der Honig ist zum Leben erwacht, und die Replikationsrate übertrifft meine kühnsten Träume. Ich muss weitere Tests durchführen!', '', 28153),
(149126, 'deDE', 'Löscht die Flammen! Haltet sie auf!', '', 28153),
(149125, 'deDE', 'Seht, wie sie den Schwanz einziehen und fliehen!', '', 28153),
(149124, 'deDE', 'Lauft, Ihr dreckigen Ratten!', '', 28153),
(149123, 'deDE', '', 'Das ist Irrsinn. Ihr werdet hier sterben, und ein namenloses Grab wird alles sein, was von Euch bleibt.', 28153),
(149122, 'deDE', '', 'Ich wusste, die Horde kann grausam sein. Rücksichtslos in ihrem Streben nach dem Sieg. Aber das...?', 28153),
(149121, 'deDE', 'Ich habe sie gefunden, mein König! Ich bringe Euch ihre Häute als Trophäen!', '', 28153),
(149120, 'deDE', 'Tut nich\' so, als würdet Ihr Euch nich\' freu\'n, uns zu seh\'n.', '', 28153),
(149119, 'deDE', 'Ich bin verzückt. Wirklich. Gehen wir. Auf Euer Zeichen.', '', 28153),
(149118, 'deDE', '', 'Ihr seid echt \'n grausamer Feind, Zul.', 28153),
(149117, 'deDE', '', 'Ein Kampf wäre ausweglos. Lauft!', 28153),
(149116, 'deDE', '', 'Was denn nun schon wieder?', 28153),
(149115, 'deDE', 'Also das ist ein vollendetes Desaster.', '', 28153),
(149114, 'deDE', '', 'Der Hafen! Wir müssen weiter!', 28153),
(149113, 'deDE', 'Man sollte mein\', \'ne Stadt aus Stein is\' weniger... entzündlich.', '', 28153),
(149112, 'deDE', 'Die woll\'n uns einkesseln. Das dürf\'n wir nich\' zulass\'n!', '', 28153),
(149111, 'deDE', 'Hier wollt Ihr nich\' weiter.', '', 28153),
(149110, 'deDE', 'Wir müss\'n zurück zu den Kanälen. Mir nach!', '', 28153),
(149109, 'deDE', 'Sieh an. Das kann ich brauch\'n.', '', 28153),
(149108, 'deDE', '', 'Wir müssen Deckung suchen!', 28153),
(149107, 'deDE', '', 'Vorsicht!', 28153),
(149106, 'deDE', 'Der alte Wolf hat uns gewittert. Wir müss\'n hier weg!', '', 28153),
(149105, 'deDE', '', 'Es sind zu viele... die Barriere wird nicht halten!', 28153),
(149104, 'deDE', 'Da! Haltet sie auf, bevor sie die Tore erreichen!', 'Da! Haltet sie auf, bevor sie die Tore erreichen!', 28153),
(149103, 'deDE', 'Ihr dachtet, Ihr wärt ungeschoren davongekommen? Da habt Ihr Euch aber geirrt!', 'Ihr dachtet, Ihr wärt ungeschoren davongekommen? Da habt Ihr Euch aber geirrt!', 28153),
(149102, 'deDE', 'Da unten! Holt Euch diese Ressourcen!', 'Da unten! Holt Euch diese Ressourcen!', 28153),
(149101, 'deDE', '', 'Die Bluttrolle sin\' kranke, widerliche Kreatur\'n. Gibt keine Hoffnung, dass die sich jemals ändern.', 28153),
(149100, 'deDE', '', 'Die Bluttrolle verschling\'n mein Volk. Ihr müsst die aufhalt\'n.', 28153),
(149099, 'deDE', 'Mordschnabel wird durch den Aufruhr angelockt!', 'Mordschnabel wird durch den Aufruhr angelockt!', 28153),
(149098, 'deDE', 'Axtschnäbel werden vom Geruch der Köder im Wasser angelockt!', 'Axtschnäbel werden vom Geruch der Köder im Wasser angelockt!', 28153),
(149097, 'deDE', 'Habt Dank! Ich fürchtete schon, als Fleischspieß zu enden.', '', 28153),
(149096, 'deDE', 'Da seid Ihr ja! Ich könnte hier etwas Hilfe brauchen.', '', 28153),
(149095, 'deDE', 'Wir wissen Eure Eile zu schätzen, $C. Wir werden uns zu Fräulein Kronsteig durchkämpfen.', '', 28153),
(149094, 'deDE', '', 'Könnten hier Eure Hilfe gebrauchen!', 28153),
(149093, 'deDE', 'Danke für Eure Hilfe.', '', 28153),
(149092, 'deDE', 'Verfluchte Hexen mit ihren Barrieren!', '', 28153),
(149091, 'deDE', '', 'Den Jungtier\'n geht\'s wunderbar. Sie werd\'n zu prächtigen Kriegsbestien ranwachs\'n.', 28153),
(149090, 'deDE', '', 'Junge Kriegsbestien brauch\'n ständige Aufmerksamkeit und Zuneigung. Sie müss\'n lernen, mit uns zu interagier\'n, so wie wir lern\' müss\'n, sie zu versteh\'n.', 28153),
(149089, 'deDE', 'Ich höre den Ruf!', '', 28153),
(149088, 'deDE', 'Ich hab all meine Waff\'n verlor\'n, aber wenigstens hab ich mein Leb\'n noch.', '', 28153),
(149087, 'deDE', 'Die hab\'n mich beim Späh\'n überrascht. Soll nich\' wieder vorkomm\'n.', '', 28153),
(149086, 'deDE', 'Ich komm wieder, und dann werd\'n diese Bluttrolle zahl\'n!', '', 28153),
(149085, 'deDE', 'Danke. Ich geh zurück nach Zul\'jan.', '', 28153),
(149084, 'deDE', '', 'Danke. Die Goblins sollt\'n sich besser drauf konzentrier\'n, meine Stadt zu retten, statt an Profit zu denk\'n.', 28153),
(149083, 'deDE', '', 'So \'ne Gruppe Goblins wurd von den Untoten gefang\'n. Wir müss\'n die da raus hol\'n.', 28153),
(149082, 'deDE', 'Habt Ihr eine Ahnung, wofür dieser Teer benutzt wird? Ich auch nicht, aber damit soll sich so RICHTIG Geld machen lassen!', '', 28153),
(149081, 'deDE', 'Von wegen Teergruben, Drecksgruben sind das! Ich hau ab hier.', '', 28153),
(149080, 'deDE', 'Na ja, ich wollte sowieso gerade raus. Dieser Teer wird uns ganz schön was einbringen!', '', 28153),
(149079, 'deDE', 'Ganz schön knapp! He, könnt Ihr wohl ein bisschen Teer für mich holen? Daheim können wir damit fett Kohle machen.', '', 28153),
(149078, 'deDE', 'Danke. Wer hätte gedacht, dass es so gefährlich sein würde, Teer aus einem verbotenen Sumpf zu holen?', '', 28153),
(149076, 'deDE', 'Korthek ist zu weit gegangen. Ich muss mich persönlich darum kümmern. Beschützt die Schlüssel, solange ich weg bin.', '', 28153),
(149075, 'deDE', '', 'Das sollte den Bluttrollen zeig\'n, dass ihre Tage gezählt sin\'.', 28153),
(149074, 'deDE', '', 'Der Goblintrupp hat \'nen Plan, wie wir mit den Bluttrollen fertig werden. Kuckt, was Ihr tun könnt, damit die das überleb\'n.', 28153),
(149073, 'deDE', 'Lasst uns an Bord des A.F.M.O.D. gehen und diese Bluttrollarmee aufhalten.', 'Lasst uns an Bord des A.F.M.O.D. gehen und diese Bluttrollarmee aufhalten.', 28153),
(149072, 'deDE', 'He! Da sind ein paar fiese Bluttrolle auf dem Weg nach Zuldazar. Aber zum Glück haben wir jetzt eine verbesserte Version des A.M.O.D.!\n\nSeht Euch doch nur mal dieses Prachtstück an! Der A.F.M.O.D. kann sogar FLIEGEN! Tod von oben!\n\nLeider mussten wir dafür auf den Schild verzichten, sonst hätte das Ding unmöglich fliegen können.\n\nWollt Ihr vielleicht mal eine Runde damit drehen? Wir können diese Armee damit in Stücke schießen!', '', 28153),
(149071, 'deDE', 'Ihr seid wertlos... genau wie die anderen...', '', 28153),
(149070, 'deDE', 'Noch ein Verbannter zum Abschlachten? Heute ist ein schöner Tag.', '', 28153),
(149066, 'deDE', 'Geht, kleiner König. Ich werde alle verschlingen, die Euch zu folgen suchen.', '', 28153),
(149065, 'deDE', 'Nun, nix is\' es nich\'.', '', 28153),
(149064, 'deDE', '', 'Zul is\' relativ ruhig. Vielleicht is\' es nix.', 28153),
(149063, 'deDE', 'Sie können nicht weit sein. Eure Wachsamkeit ist unser Schutz.', '', 28153),
(149062, 'deDE', 'Infiltratoren der Horde sind ins Verlies vorgedrungen! Zivilisten sollten in ihren Häusern bleiben, bis die Gefahr gebannt ist!', '', 28153),
(149061, 'deDE', 'Auf Befehl des Königs!', '', 28153),
(149060, 'deDE', 'Ich kann uns versteckt halt\'n, solange keiner Dummheit\'n macht.', '', 28153),
(149059, 'deDE', 'Ha ha! Sei unbesorgt, mein lieber Anselm, das hier ist nichts als ein kleiner Rückschlag! Der Betrieb wird in null Komma nichts wieder wie am Schnürchen laufen!', 'Ha ha! Sei unbesorgt, mein lieber Anselm, das hier ist nichts als ein kleiner Rückschlag! Der Betrieb wird in null Komma nichts wieder wie am Schnürchen laufen!', 28153),
(149058, 'deDE', 'W-Was redest du da? Du wärst fast umgekommen und hast dabei ganz nebenbei auch noch den ganzen Hof in Schutt und Asche gelegt!', '', 28153),
(149057, 'deDE', 'Es liegt an uns, die Kunst der Imkerei voranzutreiben, koste es, was es wolle!', 'Es liegt an uns, die Kunst der Imkerei voranzutreiben, koste es, was es wolle!', 28153),
(149056, 'deDE', 'Die war offensichtlich nich\' nötig.', '', 28153),
(149055, 'deDE', 'SOFORT.', '', 28153),
(149054, 'deDE', 'Häh?', '', 28153),
(149053, 'deDE', '', 'Keine Sorge. Wir krieg\'n schon mit, wenn sein Leben in Gefahr is\'.', 28153),
(149052, 'deDE', 'Weiter.', '', 28153),
(149051, 'deDE', '', 'Moment... Wo sind die Wachen?', 28153),
(149050, 'deDE', 'Los geht\'s. Bleibt zusamm\'.', '', 28153),
(149049, 'deDE', '\'ne kleine Vorwarnung hätte nich\' geschadet.', '', 28153),
(149048, 'deDE', 'Bleibt wachsam. Laut dem SI:7 ist der Feind in der Nähe der Burg gesehen worden.', '', 28153),
(149047, 'deDE', 'Rein in den Kanal. Sofort.', '', 28153),
(149046, 'deDE', 'Geh\'n wir über die Brücke. Außer, Euer Prophet hat \'n Problem damit.', '', 28153),
(149045, 'deDE', 'Schnell! Runter vom Weg.', '', 28153),
(149044, 'deDE', 'Wartet kurz.', '', 28153),
(149043, 'deDE', 'Hergehört, Bürger von Sturmwind!', '', 28153),
(149042, 'deDE', 'Dann los. Bleibt zusamm\', wie \'n Team.', '', 28153),
(149041, 'deDE', '', 'Überall Wachen. Wir können hier nicht lange bleiben.', 28153),
(149040, 'deDE', 'Ich bin bereit, die Segel zu setzen!', 'Ich bin bereit, die Segel zu setzen!', 28153),
(149039, 'deDE', '', 'Seid Ihr bereit für die Reise nach Kul Tiras?', 28153),
(149038, 'deDE', '', 'Dank Euch ham wir \'n bisschen Zeit zum Manövrier\'n un\' Krag\'wa kann seine Verteidigung verstärk\'n. Habt Dank.', 28153),
(149037, 'deDE', 'Ich hole zurück, was mein ist! Ihr könnt mich nicht aufhalten!', '', 28153),
(149036, 'deDE', '', 'Die Bluttrolle greif\'n Krag\'wa noch immer an. Schneidet ihnen die Nachschubwege ab un\' lasst sie teuer dafür bezahl\'n!', 28153),
(149035, 'deDE', 'Sethraliss... Ich habe Eure Stimme vergessen...', '', 28153),
(149034, 'deDE', 'Wir sind nicht an die Loa gebunden. Wir sind allein stark.', '', 28153),
(149033, 'deDE', 'Eindringlinge! Das hier geht weit über Euren Verstand hinaus.', '', 28153),
(149031, 'deDE', 'PLATZHALTERSZENE - Talanji fragt, ob es wirklich vorbei ist. Rokhan antwortet, das Böse habe die Angewohnheit zu überleben und er bezweifle, dass dies das Letzte sei, was sie von diesem Ort gesehen haben.\nAufnahme: Nahaufnahmen von Talanji und Rokhan, dann ein ominöses Panorama der nun freigelegten Grube.', 'PLATZHALTERSZENE - Talanji fragt, ob es wirklich vorbei ist. Rokhan antwortet, das Böse habe die Angewohnheit zu überleben und er bezweifle, dass dies das Letzte sei, was sie von diesem Ort gesehen haben.\nAufnahme: Nahaufnahmen von Talanji und Rokhan, dann ein ominöses Panorama der nun freigelegten Grube.', 28153),
(149030, 'deDE', '', 'Meister... ich... habe versagt...', 28153),
(149029, 'deDE', '', 'Gorak Tul... kommt...', 28153),
(149028, 'deDE', '', 'Gorak Tul... hat Macht versprochen...', 28153),
(149027, 'deDE', '', 'Ich bin keine große Hilfe im Kampf, aber ich werde nicht ruhen, ehe meine Mutter zur Rechenschaft gezogen wurde.', 28153),
(149026, 'deDE', '', 'Für meinen Vater und für Drustvar!', 28153),
(149025, 'deDE', '', 'Wir sehen uns drinnen, Inquisitorin.', 28153),
(149024, 'deDE', '', 'Inquisitoren, mir nach! Ruhm dem Haus Kronsteig!', 28153),
(149023, 'deDE', '', 'Jawohl, Herrin! Wir werden den Zirkel zerschlagen.', 28153),
(149022, 'deDE', '', 'Inquisitoren, dies ist die letzte Schlacht. Mögen die Winde Euch den Rücken stärken.', 28153),
(149021, 'deDE', '', 'Mutter... Was habt Ihr getan?', 28153),
(149020, 'deDE', '', 'Marschall, nein...', 28153),
(149019, 'deDE', 'Es... tut mir leid...', '', 28153),
(149018, 'deDE', 'Liebste Luzilla... Ich... habe versagt...', '', 28153),
(149017, 'deDE', '', 'Kämpft dagegen an, Marschall!', 28153),
(149016, 'deDE', 'Nein... das darf... nicht sein!', '', 28153),
(149015, 'deDE', 'Ich... gehorche...', '', 28153),
(149014, 'deDE', 'Wir decken die Flanken. $n, bleibt bei Luzilla und dem Marschall!', '', 28153),
(149013, 'deDE', '', 'Ihr habt Euch die Falsche zum Ankreischen ausgesucht, Hexe!', 28153),
(149012, 'deDE', 'Los, weiter. Wir schaffen es! Auf die Augen, Wilhelm!', '', 28153),
(149011, 'deDE', 'Ich bin gleich hinter Euch.', 'Ich bin gleich hinter Euch.', 28153),
(149010, 'deDE', 'Für Haus Kronsteig!', '', 28153),
(149009, 'deDE', 'Bleibt zusammen und stoßt weiter vor, bis wir die Tore des Anwesens durchbrochen haben!', '', 28153),
(149008, 'deDE', 'Bei dem Tempo halt\'n wir nich\' lang durch. Wir müss\'n schnell zu den Docks.\n\nSagt Bescheid, dann renn\' wir los.', '', 28153),
(149007, 'deDE', 'Inquisitoren! Dies ist unsere Chance, Lord und Lady Kronsteig zu retten... und diesem fürchterlichen Zirkel ein Ende zu bereiten!', '', 28153),
(149005, 'deDE', '', 'Ihr schlottert ja. Hat die Allianz etwa Angst?', 28153),
(149004, 'deDE', '', 'Schwindelig?', 28153),
(149003, 'deDE', '', 'Ihr dachtet wirklich, Ihr könntet gewinnen?', 28153),
(149002, 'deDE', '', 'Ausgelöscht... von niederem Abschaum...', 28153),
(149001, 'deDE', 'Eure Erfolgschancen sind ziemlich mager!', '', 28153),
(149000, 'deDE', 'Ihr steht nicht richtig!', '', 28153),
(148999, 'deDE', 'Grillt diese Made!', '', 28153),
(148998, 'deDE', 'Ihr habt... betrogen...', '', 28153),
(148997, 'deDE', 'Ich bin bei Euch!', '', 28153),
(148996, 'deDE', 'Verteidigungspositionen!', '', 28153),
(148995, 'deDE', 'Möge das Licht... Euch segnen.', '', 28153),
(148994, 'deDE', '', 'Reißt ihn\'n das Herz raus!', 28153),
(148993, 'deDE', '', 'Ich schicke Eure Seele zu Gorak Tul!', 28153),
(148991, 'deDE', 'Macht Euch bereit! Sie kommen!', 'Macht Euch bereit! Sie kommen!', 28153),
(148990, 'deDE', 'Schützt die Ressourcen!', 'Schützt die Ressourcen!', 28153),
(148989, 'deDE', 'Dieser Wald gehört uns!', 'Dieser Wald gehört uns!', 28153),
(148988, 'deDE', 'Kommt ja nicht näher!', 'Kommt ja nicht näher!', 28153),
(148987, 'deDE', 'Zurück!', 'Zurück!', 28153),
(148986, 'deDE', 'Die Hüter waren die Stärksten unter uns und wurden damit beauftragt, Mythrax\' Leichnam in der großen Pyramide zu versiegeln.\n\nSulthis war der Gründer, aber er konnte das Grab nicht allein versiegeln.\n\nEr bat Vorrik und Korthek um Hilfe und zusammen erschufen sie eine Barriere, die den Leichnam von Mythrax darin bannt.', 'Die Hüter waren die Stärksten unter uns und wurden damit beauftragt, Mythrax\' Leichnam in der großen Pyramide zu versiegeln.\n\nSulthis war der Gründer, aber er konnte das Grab nicht allein versiegeln.\n\nEr bat Vorrik und Korthek um Hilfe und zusammen erschufen sie eine Barriere, die den Leichnam von Mythrax darin bannt.', 28153),
(148985, 'deDE', 'Er nennt sich Imperator Korthek, aber vor langer Zeit war er einer der Hüter, der zum Schutz des Grabes berufen wurde.\n\nSeine Kriegslust ist das Gegenteil von allem, wofür unser Loa steht. Er verspottet und verhöhnt sie und hat eine eigene Armee aufgestellt, mit der er ganz Zuldazar unterwerfen will.', 'Er nennt sich Imperator Korthek, aber vor langer Zeit war er einer der Hüter, der zum Schutz des Grabes berufen wurde.\n\nSeine Kriegslust ist das Gegenteil von allem, wofür unser Loa steht. Er verspottet und verhöhnt sie und hat eine eigene Armee aufgestellt, mit der er ganz Zuldazar unterwerfen will.', 28153),
(148984, 'deDE', 'Die Treulosen sind eine Streitmacht militanter Sethrak, die von Imperator Korthek angeführt wird.\n\nVor langer Zeit haben wir alle zusammengelebt, so wie es Sethraliss immer wollte.\n\nAber seit Kortheks Verrat haben die Treulosen den Krieg über unser Land gebracht.\n\nSie werden nicht aufhören, bis sie die gesamte Welt unterworfen haben.', 'Die Treulosen sind eine Streitmacht militanter Sethrak, die von Imperator Korthek angeführt wird.\n\nVor langer Zeit haben wir alle zusammengelebt, so wie es Sethraliss immer wollte.\n\nAber seit Kortheks Verrat haben die Treulosen den Krieg über unser Land gebracht.\n\nSie werden nicht aufhören, bis sie die gesamte Welt unterworfen haben.', 28153),
(148983, 'deDE', 'Sethraliss ist unser geliebter Loa.\n\nAls Mythrax unser Land verwüstete und uns beinahe ausgerottet hätte, war sie es, die ihn gestoppt hat. Sie opferte ihr Leben für uns.\n\nIm Gegensatz zu den Treulosen spüren wir ihre Präsenz noch immer. Wir glauben, dass sie eines Tages zu uns zurückkehrt.', 'Sethraliss ist unser geliebter Loa.\n\nAls Mythrax unser Land verwüstete und uns beinahe ausgerottet hätte, war sie es, die ihn gestoppt hat. Sie opferte ihr Leben für uns.\n\nIm Gegensatz zu den Treulosen spüren wir ihre Präsenz noch immer. Wir glauben, dass sie eines Tages zu uns zurückkehrt.', 28153),
(148982, 'deDE', 'Die Hüter waren die Stärksten unter uns und wurden damit beauftragt, Mythrax\' Leichnam in der großen Pyramide zu versiegeln.\n\nSulthis war der Gründer, aber er konnte das Grab nicht allein versiegeln.\n\nEr bat Vorrik und Korthek um Hilfe und zusammen erschufen sie eine Barriere, die den Leichnam von Mythrax darin bannt.', '', 28153),
(148981, 'deDE', 'Er nennt sich Imperator Korthek, aber vor langer Zeit war er einer der Hüter, der zum Schutz des Grabes berufen wurde.\n\nSeine Kriegslust ist das Gegenteil von allem, wofür unser Loa steht. Er verspottet und verhöhnt sie und hat eine eigene Armee aufgestellt, mit der er ganz Zuldazar unterwerfen will.', '', 28153),
(148980, 'deDE', 'Sethraliss ist unser geliebter Loa.\n\nAls Mythrax unser Land verwüstete und uns beinahe ausgerottet hätte, war sie es, die ihn gestoppt hat. Sie opferte ihr Leben für uns.\n\nIm Gegensatz zu den Treulosen spüren wir ihre Präsenz noch immer. Wir glauben, dass sie eines Tages zu uns zurückkehrt.', '', 28153),
(148979, 'deDE', '', 'Ich benötige Euch sofort in Orgrimmar für eine Mission von äußerster Dringlichkeit. Lasst mich nicht warten!', 28153),
(148978, 'deDE', '', 'Unser Erfolg in diesem Konflikt könnte von Euren Fähigkeiten abhängen.', 28153),
(148977, 'deDE', 'Die Treulosen sind eine Streitmacht militanter Sethrak, die von Imperator Korthek angeführt wird.\n\nVor langer Zeit haben wir alle zusammengelebt, so wie es Sethraliss immer wollte.\n\nAber seit Kortheks Verrat haben die Treulosen den Krieg über unser Land gebracht.\n\nSie werden nicht aufhören, bis sie die gesamte Welt unterworfen haben.', '', 28153),
(148976, 'deDE', '', 'Champion, die Horde befindet sich jetzt im offenen Krieg mit der Allianz.', 28153),
(148975, 'deDE', 'Diese Insel strotzt geradezu vor Azerit. In der Nähe sollte es eine große Ansammlung geben.', '', 28153),
(148974, 'deDE', 'Detektor läuft. Jetzt sollten wir Azerit auf der ganzen Insel orten können.', '', 28153),
(148973, 'deDE', 'Sethraliss ist unser geliebter Loa.\n\nAls Mythrax unser Land verwüstete und uns beinahe ausgerottet hätte, war sie es, die ihn gestoppt hat. Sie opferte ihr Leben für uns.\n\nIm Gegensatz zu den Treulosen spüren wir ihre Präsenz noch immer. Wir glauben, dass sie eines Tages zu uns zurückkehrt.', '', 28153),
(148972, 'deDE', 'Er nennt sich Imperator Korthek, aber vor langer Zeit war er einer der Hüter, der zum Schutz des Grabes berufen wurde.\n\nSeine Kriegslust ist das Gegenteil von allem, wofür unser Loa steht. Er verspottet und verhöhnt sie und hat eine eigene Armee aufgestellt, mit der er ganz Zuldazar unterwerfen will.', '', 28153),
(148971, 'deDE', 'Wir werden niemals vergessen, was der Loa für uns getan hat.', 'Wir werden niemals vergessen, was der Loa für uns getan hat.', 28153),
(148970, 'deDE', '', 'Danke, Champion. Meine Gelehrt\'n arbeit\'n bereits an den Text\'n. Hoffentlich find\'n die was, das wir gegen den Blutgott einsetz\'n könn\'.', 28153),
(148969, 'deDE', '', 'Diese Einrichtung birgt vielleicht noch Information\' mit den\' wir G\'huun vernicht\'n oder wegsperr\'n könn\'. Sucht nach nützlich\'n Relikt\'n un\' Text\'n.', 28153),
(148968, 'deDE', 'Unser Glaube macht uns stark.', 'Unser Glaube macht uns stark.', 28153),
(148966, 'deDE', 'Wir verteidigen den Tempel um jeden Preis.', 'Wir verteidigen den Tempel um jeden Preis.', 28153),
(148965, 'deDE', 'Wir werden den Tempel nicht aufgeben.', 'Wir werden den Tempel nicht aufgeben.', 28153),
(148962, 'deDE', 'Ein Schiff fährt in den Dungeon ein. Pike verleiht seiner Sorge darüber Ausdruck, dass ein Schiff mit Dorfbewohnern im Heiligtum seines Ordens auftaucht.', 'Ein Schiff fährt in den Dungeon ein. Pike verleiht seiner Sorge darüber Ausdruck, dass ein Schiff mit Dorfbewohnern im Heiligtum seines Ordens auftaucht.', 28153),
(148959, 'deDE', 'Was ist es denn?', 'Was ist es denn?', 28153),
(148958, 'deDE', 'Ich kann es hier ganz deutlich spüren. Etwas Dunkles erwacht.', '', 28153),
(148955, 'deDE', 'Ich frage mich, woran Vater hier unten gearbeitet hat...', '', 28153),
(148954, 'deDE', 'Wir müss\'n hier raus. Ich kann uns an den Wach\'n vorbeischmuggeln.\n\nSagt Bescheid, wenn Ihr bereit seid.', '', 28153),
(148953, 'deDE', 'Platz da!', '', 28153),
(148952, 'deDE', 'Haltet Euch rechts! Ich glaube, ich habe einen Weg raus gesehen!', '', 28153),
(148946, 'deDE', 'Gut! Diese Materialien werd\'n sich bestens als Befiederung für unsre Pfeile und Futter für unsre Rüstungen mach\'n.', '', 28153),
(148945, 'deDE', 'Nazmir is\' echt tödlich. Aber es gibt auch massig Ressourcen, wenn man nur weiß wo. Von den Lebewes\'n an der Küste bekomm\' wir, was die Trupp\'n brauch\'n.', '', 28153),
(148944, 'deDE', 'Was sollen wir nur tun, $p?!', '', 28153),
(148943, 'deDE', '', '...Zumindest wollen wir das hoffen.', 28153),
(148942, 'deDE', '', 'Ihr solltet Euch bei Theock melden. Er wird sich freuen, dass die Mine wieder unter Kontrolle ist.', 28153),
(148941, 'deDE', '', 'Wir haben es geschafft!', 28153),
(148940, 'deDE', '', 'Ich sterbe... so weit... von... G\'huun...?', 28153),
(148939, 'deDE', '', 'BLUT FÜR G\'HUUN!', 28153),
(148938, 'deDE', 'Wir seh\'n uns im Labor!', 'Wir seh\'n uns im Labor!', 28153),
(148936, 'deDE', 'Der Tempel ist da vorn.', '', 28153),
(148935, 'deDE', 'Wir werden ihn aufhalten, koste es, was es wolle.', '', 28153),
(148934, 'deDE', 'Korthek führt sie an auf ihrer Suche nach den übrigen Schlüsseln. Er will die Barriere um Atul\'Aman brechen und mit dem darin Verborgenen ganz Zuldazar erobern.', '', 28153),
(148933, 'deDE', 'Seit Kortheks Verrat haben die Treulosen in unserem Land Krieg entfacht.', '', 28153),
(148932, 'deDE', 'Vor Langem lebten wir in Einheit, wie unser Loa es gewollt hätte.', '', 28153),
(148931, 'deDE', 'Unser Tempel ist die letzte Bastion gegen die Treulosen.', '', 28153),
(148930, 'deDE', 'Krieger der Horde! Folgt dem Ruf der Schlacht! Beschert unseren Feinden einen schnellen Tod.', '', 28153),
(148929, 'deDE', 'Ihr seht so aus, als wolltet Ihr einen Tortollaner, richtig?', 'Ihr seht so aus, als wolltet Ihr einen Tortollaner, richtig?', 28153),
(148928, 'deDE', 'Holt Euch Euren eigenen Tortollaner! Lasst ihn am Leben oder nutzt seinen Panzer als Staufach.', 'Holt Euch Euren eigenen Tortollaner! Lasst ihn am Leben oder nutzt seinen Panzer als Staufach.', 28153),
(148927, 'deDE', 'Wer bietet mehr? Tortollaner, frisch gefangen auf ihrer Pilgerreise durch Nazmir!', 'Weitere Gebote? Tortollaner, frisch gefangen auf ihrer Pilgerreise durch Nazmir!', 28153),
(148925, 'deDE', 'Schlagt jetzt zu! Solche Vulpera wie diese bekommt Ihr nie wieder!', 'Schlagt jetzt zu! Solche Vulpera wie diese bekommt Ihr nie wieder!', 28153),
(148924, 'deDE', 'Holt Euch hier Eure eignen Vulpera! Mit extra viel Energie!', 'Holt Euch hier Eure eignen Vulpera! Mit extra viel Energie!', 28153),
(148923, 'deDE', 'Bietet jemand mehr für die Vulpera? Sie werden Euch gute Dienste erweisen!', 'Bietet jemand mehr für die Vulpera? Sie werden Euch gute Dienste erweisen!', 28153),
(148922, 'deDE', 'Die Treulosen müssen aufgehalten werden!', 'Die Treulosen müssen aufgehalten werden!', 28153),
(148921, 'deDE', 'Ich sollte mich jetzt in Sicherheit bringen können.', 'Ich sollte mich jetzt in Sicherheit bringen können.', 28153),
(148920, 'deDE', 'Danke! Von hier aus schaffe ich es.', 'Danke! Von hier aus schaffe ich es.', 28153),
(148919, 'deDE', 'Rächt diejenigen, die nicht gerettet werden konnten.', 'Rächt diejenigen, die nicht gerettet werden konnten.', 28153),
(148918, 'deDE', 'Ihr habt keine Ahnung, was sie uns angetan haben...', 'Ihr habt keine Ahnung, was sie uns angetan haben...', 28153),
(148917, 'deDE', 'Seid vorsichtig, $p. Ihr lauft geradewegs in ihr Nest.', '', 28153),
(148916, 'deDE', 'Trefft uns dort, sobald Ihr den Stein von Korthek habt.', '', 28153),
(148910, 'deDE', 'Wie könnt Ihr es wag\'n, Fuß in diese Jagdgründe zu setz\'n?!', 'Wie könnt Ihr es wag\'n, Fuß in diese Jagdgründe zu setz\'n?!', 28153),
(148909, 'deDE', 'Dafür werdet Ihr büß\'n!', 'Dafür werdet Ihr büß\'n!', 28153),
(148908, 'deDE', 'Die Allianz hat hier nix zu such\'n!', 'Die Allianz hat hier nix zu such\'n!', 28153),
(148907, 'deDE', 'Dieses Reservat gehört den Zandalari!', 'Dieses Reservat gehört den Zandalari!', 28153),
(148906, 'deDE', 'Bitte! Vergeudet noch mehr Zeit mit Diskutier\'n.', '', 28153),
(148905, 'deDE', '', 'Dem Troll zufolge nach draußen.', 28153),
(148904, 'deDE', 'Wo führt der hin?', '', 28153),
(148903, 'deDE', '', 'Hier riecht\'s... nich\' angenehm.', 28153),
(148902, 'deDE', '', 'Die Bluttrolle werd\'n lern\', dass wir uns nich\' mehr vor ihnen versteck\'n. Gute Arbeit.', 28153),
(148901, 'deDE', '', 'Jemand... muss sie aufhalten...', 28153),
(148900, 'deDE', '', 'Niemand überrumpelt die 7. Legion. Sterbt, Hordenabschaum!', 28153),
(148899, 'deDE', '', 'Meine Späher bericht\'n, dass sich die Bluttrolle in der Nähe sammeln. Zeigt ihn\', warum man sich nich\' mit\'n Zandalari anlegt!', 28153),
(148898, 'deDE', '', 'Ihr werdet keinen Schritt weitergehen!', 28153),
(148897, 'deDE', '', 'Ein Nullifikationsfeld. Ich kann nicht zaubern!', 28153),
(148896, 'deDE', 'Das is\' echt fieser Voodoo. Thalyssra?', '', 28153),
(148895, 'deDE', '', 'Lasst mich kurz verschnaufen. Ich habe stundenlang versucht, mich aus diesem Käfig zu befreien.', 28153),
(148894, 'deDE', '', 'Mein Fluch kann nicht gebrochen werden!', 28153),
(148893, 'deDE', 'Jedes Einzelne dieser Tiere wird eines Tages für die Horde kämpfen. Das dürfen wir nicht zulassen.', '', 28153),
(148892, 'deDE', 'Die Wildtiere werden bald wieder ihre normale Anzahl erreicht haben, aber die Horde wird ewig brauchen, bis sie neue Bestienhüter ausgebildet hat. Gute Arbeit!', '', 28153),
(148891, 'deDE', 'Das Zandalarireservat ist voller Tiere, die man für den Kampf abrichten könnte, aber alles steht und fällt mit ihrer Ausbildung. Vergiftet sie, um ihre Bestienhüter herauszulocken. Sie sind die wahren Ziele.', '', 28153),
(148890, 'deDE', '', 'Wehe, das stimmt nich\'.', 28153),
(148889, 'deDE', 'Das wär ein Fehler. Wir müss\'n in die andre Richtung.', '', 28153),
(148888, 'deDE', 'Hier lang!', '', 28153),
(148887, 'deDE', '', 'Wie komm\'n wir raus?', 28153),
(148886, 'deDE', '', 'Dank Euch sin\' wir einen Schritt näher dran, die Bluttrolle endgültig aufzuhalt\'n.', 28153),
(148885, 'deDE', '', 'Ich spür dunkles Mojo in der Nähe. Bestimmt Bluttrolle. Ihr müsst \'nen Strich durch ihre Pläne mach\'n.', 28153),
(148884, 'deDE', '', 'Wir müssen hier weg!', 28153),
(148883, 'deDE', '', 'Riegelt alles ab!', 28153),
(148879, 'deDE', 'Die Wolken brechen auf... Der Sturm legt sich...', '', 28153),
(148878, 'deDE', 'Ich bin der Vorbote des Sturms!', '', 28153),
(148877, 'deDE', 'Vorstellungen mach\'n wir später.', '', 28153),
(148876, 'deDE', '', 'Wir sind hier auf Geheiß der Horde. Ich bin Thalyssra und das ist Rokhan.', 28153),
(148875, 'deDE', '', 'Hmm... Danke. Mein Prophet sagt mir, Ihr seid auf unsrer Seite.', 28153),
(148874, 'deDE', 'Hahahaha, Euch kenn ich doch. Ihr seid die Schlange, die–', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'deDE', 'Ah, da kommt unsre Eskorte. Wie ich versproch\'n hab, Prinzessin.', '', 28153),
(148871, 'deDE', 'Kommt, $n. Hier lang.', '', 28153),
(148870, 'deDE', 'Ich muss mich nur einen Moment ausruhen.', '', 28153),
(148868, 'deDE', 'Korthek glaubt, er kann sich hinter einer Mauer vor uns verstecken? So ein Narr.', '', 28153),
(148867, 'deDE', 'Haltet Ihr Euch an den Plan. Ich komme nach.', '', 28153),
(148858, 'deDE', '', 'Ich verstehe... Ihr seid Euch sicher, Hochfürst?', 28153),
(148857, 'deDE', 'Bin ich. Lok\'tar.', '', 28153),
(148856, 'deDE', 'Ihr kommt nich\' mit uns.', '', 28153),
(148855, 'deDE', 'Wir wissen beide, Ihr seid nicht wegen mir hier. Die, die Ihr sucht, findet Ihr am Ende des Gangs.', '', 28153),
(148854, 'deDE', 'Auf Basis der Informationen würde ich sagen, dass der Imperator am ehesten angreifbar ist, wenn er zum Markt geht. Das ist gleich um die Ecke.', '', 28153),
(148853, 'deDE', 'Ich glaub, das hier solltet Ihr übernehm\'n.', '', 28153),
(148852, 'deDE', '', 'Wir werden sie ablenken. Seid vorsichtig.', 28153),
(148851, 'deDE', 'Ich geh vor und spür die Gefang\'nen auf. Gebt mir Deckung.', '', 28153),
(148850, 'deDE', 'Die 7. Legion is\' hier. Wen immer wir raushol\'n, die Menschen lassen\'s echt nich\' drauf ankomm\'.', '', 28153),
(148849, 'deDE', 'Ich werde Euch finden. Viel Glück.', '', 28153),
(148848, 'deDE', 'Wenn Ihr die Gefangenen befreit habt, bringt sie zu diesem Schiff dort unten.', '', 28153),
(148847, 'deDE', 'Sollte die Situation ausweglos sein, nehmt, was ich Euch gegeben habe. Es ermöglicht einen schnellen Tod.', '', 28153),
(148846, 'deDE', 'Geratet Ihr in Gefangenschaft, leugnen der Kriegshäuptling und die Horde jede Kenntnis von dieser Mission.', '', 28153),
(148845, 'deDE', 'Unsere Späher haben einen geheimen Eingang entdeckt. Ich decke mit den Tauren Euren Rückzug.', '', 28153),
(148844, 'deDE', 'Ihr dringt mit Thalyssra und Rokhan ins Verlies ein und befreit die Gefangenen.', '', 28153),
(148843, 'deDE', 'Hört gut zu. In Sturmwind sind wir voneinander abgeschnitten.', '', 28153),
(148842, 'deDE', '', 'Wir werden dafür sorgen, dass die Stacheleber nie wieder einen solchen Krieg führen können.', 28153),
(148841, 'deDE', 'Eure Verdammnis... steigt empor...', 'Eure Verdammnis... steigt empor...', 28153),
(148840, 'deDE', 'Wie kann... das sein...', 'Wie kann... das sein...', 28153),
(148839, 'deDE', 'Das Auge... des Sturms... findet Euch...', 'Das Auge... des Sturms... findet Euch...', 28153),
(148838, 'deDE', 'Ihr... werdet... fallen...', 'Ihr... werdet... fallen...', 28153),
(148837, 'deDE', 'Meine Seele... verfließt... im Ozean...', 'Meine Seele... verfließt... im Ozean...', 28153),
(148836, 'deDE', 'Ich breche auf... in die endlose... Tiefe...', 'Ich breche auf... in die endlose... Tiefe...', 28153),
(148835, 'deDE', 'Ich kehre zurück... in die Tiefe...', 'Ich kehre zurück... in die Tiefe...', 28153),
(148834, 'deDE', 'Selbst die Flut... weicht zurück...', 'Selbst die Flut... weicht zurück...', 28153),
(148833, 'deDE', 'Ihre Macht strömt durch meine Adern!', 'Ihre Macht strömt durch meine Adern!', 28153),
(148832, 'deDE', 'Fügt Euch Eurem Ende!', 'Fügt Euch Eurem Ende!', 28153),
(148831, 'deDE', 'Die Flut des Schicksals wird über Euch brechen!', 'Die Flut des Schicksals wird über Euch brechen!', 28153),
(148830, 'deDE', 'Die Flut höhlt Euch aus wie einen Stein!', 'Die Flut höhlt Euch aus wie einen Stein!', 28153),
(148829, 'deDE', 'Ertrinkt in den lichtlosen Tiefen!', 'Ertrinkt in den lichtlosen Tiefen!', 28153),
(148828, 'deDE', 'Niemand stoppt die endlose Flut!', 'Niemand stoppt die endlose Flut!', 28153),
(148827, 'deDE', 'Hört den Ruf der Tiefe!', 'Hört den Ruf der Tiefe!', 28153),
(148826, 'deDE', 'Die See wird Euch fortspülen!', 'Die See wird Euch fortspülen!', 28153),
(148825, 'deDE', 'Es ist so... dunkel...', 'Es ist so... dunkel...', 28153),
(148824, 'deDE', 'Ich geh... mit der Flut...', 'Ich geh... mit der Flut...', 28153),
(148823, 'deDE', 'Zumindest sterb ich... als Kul Tiraner...', 'Zumindest sterb ich... als Kul Tiraner...', 28153),
(148822, 'deDE', 'Wie... habt Ihr...', 'Wie... habt Ihr...', 28153),
(148821, 'deDE', 'Nicht... so...', 'Nicht... so...', 28153),
(148820, 'deDE', 'Für Euch hol ich mir ein sattes Kopfgeld!', 'Für Euch hol ich mir ein sattes Kopfgeld!', 28153),
(148819, 'deDE', 'Ich schrubb das Deck mit Eurem Gesicht!', 'Ich schrubb das Deck mit Eurem Gesicht!', 28153),
(148818, 'deDE', 'Dann lasst mal sehen!', 'Dann lasst mal sehen!', 28153),
(148817, 'deDE', 'Das gibt eine tolle Kneipengeschichte!', 'Das gibt \'ne tolle Kneipengeschichte!', 28153),
(148816, 'deDE', 'Das wird Euch leid tun!', 'Das wird Euch leid tun!', 28153),
(148815, 'deDE', 'Die See... ruft mich...', 'Die See... ruft mich...', 28153),
(148814, 'deDE', 'Ich geh... mit der Flut...', 'Ich geh... mit der Flut...', 28153),
(148813, 'deDE', 'Zumindest sterb ich... als Kul Tiraner...', 'Zumindest sterb ich... als Kul Tiraner...', 28153),
(148812, 'deDE', 'Am Ende... gehören wir alle... der See...', 'Am Ende... gehören wir alle... der See...', 28153),
(148811, 'deDE', 'Fünf Faden tief... liegt mein Gebein...', 'Fünf Faden tief... liegt mein Gebein...', 28153),
(148810, 'deDE', 'Noch eine Trophäe für die Wand!', 'Noch eine Trophäe für die Wand!', 28153),
(148809, 'deDE', '', 'Hier können wir frei sprechen. Anders als ins Orgrimmar.', 28153),
(148808, 'deDE', 'Ich fütter die Fische mit Euch!', 'Ich fütter die Fische mit Euch!', 28153),
(148807, 'deDE', 'Dann lasst mal sehen!', 'Dann lasst mal sehen!', 28153),
(148806, 'deDE', '', 'Verzeiht das Theater. Mathias Shaw hat seine Spione überall.', 28153),
(148805, 'deDE', 'Ich stoß mit den Jungs auf Euren Kopf an!', 'Ich stoß mit den Jungs auf Euren Kopf an!', 28153),
(148804, 'deDE', 'Das wird Euch leid tun.', 'Das wird Euch leid tun.', 28153),
(148803, 'deDE', '', 'He! Holt mich hier raus!', 28153),
(148802, 'deDE', 'Zurück an die Arbeit, Wurm!', 'Zurück an die Arbeit, Wurm!', 28153),
(148801, 'deDE', 'Ihr kriegt noch... was Ihr verdient...', 'Ihr kriegt noch... was Ihr verdient...', 28153),
(148800, 'deDE', 'Das is... Befehls...verweigerung...', 'Das is... Befehls...verweigerung...', 28153),
(148799, 'deDE', 'Weg... treten...', 'Weg... treten...', 28153),
(148798, 'deDE', 'Früher... gab\'s noch... echte Arbeiter...', 'Früher... gab\'s noch... echte Arbeiter...', 28153),
(148797, 'deDE', 'Dafür gibt\'s eine schriftliche Verwarnung!', 'Dafür... gibt\'s... eine schriftliche... Verwarnung!', 28153),
(148796, 'deDE', 'Aaaaaah... verflucht...', 'Aaaaaah... verflucht...', 28153),
(148795, 'deDE', 'Mehr... habt Ihr... nicht drauf?', 'Mehr... habt Ihr... nicht drauf?', 28153),
(148794, 'deDE', 'Wertlose... Made...', 'Wertlose... Made...', 28153),
(148793, 'deDE', 'Hab ich \"aufhören\" gesagt?!', 'Hab ich \"aufhören\" gesagt?!', 28153),
(148792, 'deDE', 'An Euch statuiere ich ein Exempel!', 'An Euch statuiere ich ein Exempel!', 28153),
(148791, 'deDE', 'Die Pause ist vorbei, Made!', 'Die Pause ist vorbei, Made!', 28153),
(148790, 'deDE', 'Mich hintergeht Ihr nur einmal!', 'Mich hintergeht Ihr nur einmal!', 28153),
(148789, 'deDE', 'Hier wird nicht aus der Reihe getanzt!', 'Hier wird nicht aus der Reihe getanzt!', 28153),
(148788, 'deDE', 'Euch lass ich bluten, aufmüpfige Made!', 'Euch lass ich bluten, aufmüpfige Made!', 28153),
(148787, 'deDE', 'In die Reihe!', 'In die Reihe!', 28153),
(148786, 'deDE', 'Los, verschwinden wir!', '', 28153),
(148785, 'deDE', '', 'Serrik, ich bin so froh, dass Ihr zurück seid! Die Treulosen haben Vorrik!', 28153),
(148783, 'deDE', '', 'Lasst uns allein.', 28153),
(148782, 'deDE', '', 'Ahhh, $n. Vielen Dank, dass Ihr so schnell gekommen seid.', 28153),
(148781, 'deDE', '', 'Algerson holzt die Wälder ab! Wir können nicht einfach zusehen, wie er die Natur schändet!', 28153),
(148780, 'deDE', 'Ihr müsst mit dem Loa Zwiesprache halten. Seid Ihr bereit?', '', 28153),
(148779, 'deDE', 'Die Statue befindet sich irgendwo in den Tempelruinen...', '', 28153),
(148778, 'deDE', 'Wir müssen die Spinnen aus dem Weg räumen, bevor unser Stamm hier Zuflucht suchen kann.', '', 28153),
(148775, 'deDE', 'Wir müssen dem Stamm mitteilen, was wir gefunden haben!', '', 28153),
(148774, 'deDE', 'Ich fürchte, ohne Nahrung wird unser Stamm bald aussterben...', '', 28153),
(148773, 'deDE', 'Wir müssen herausfinden, wonach die Naga suchen...', '', 28153),
(148772, 'deDE', 'Aber meine Berechnungen... Ich verstehe das nicht.', 'Aber meine Berechnungen... Ich verstehe das nicht.', 28153),
(148771, 'deDE', '<Seufz> Ich werde hier nie rauskommen.', '<Seufz> Ich werde hier nie rauskommen.', 28153),
(148770, 'deDE', 'Hätte ich nur die nötigen Zutaten...', 'Hätte ich nur die nötigen Zutaten...', 28153),
(148769, 'deDE', 'Heureka! Ich bin frei!!', 'Heureka! Ich bin frei!!', 28153),
(148767, 'deDE', 'Eins bleibt aber noch zu tun. Sprecht mit mir, wenn Ihr bereit seid, Euch den Sturmschlangen zu stellen.', '', 28153),
(148766, 'deDE', 'Ich kann die Tortaka jetzt als Anhänger akzeptieren. In diesem Tempel wird ihr Stamm immer einen sicheren Zufluchtsort haben.', '', 28153),
(148765, 'deDE', 'Ihr habt den Fluch von Mepjila gebrochen und den Seelen meiner uralten Anhänger Frieden geschenkt.', '', 28153),
(148764, 'deDE', 'Sondern auch noch des Seefahrers Mast! ...Und, ähm, das tat dem Seefahrer weh, denn um sein Boot war\'s... äh... gescheh\'n. Ja, genau.', '', 28153),
(148763, 'deDE', 'Drum sah sie dann rot und brach nicht nur Schot...', '', 28153),
(148762, 'deDE', 'Ihr Mann hat ihr Hörner verpasst...', '', 28153),
(148761, 'deDE', 'Es war mal \'ne Maid im Morast...', '', 28153),
