(148759, 'deDE', 'Immer schön das Ruder grade halten.', '', 28153),
(148758, 'deDE', 'Weiter so.', '', 28153),
(148757, 'deDE', 'Was kann ein alter Seebär für Euch tun?', '', 28153),
