(148707, 'deDE', 'Ihr seid mir nicht gewachsen!', 'Ihr seid mir nicht gewachsen!', 28153),
(148706, 'deDE', 'Verteidigt Euch, Halunke!', 'Verteidigt Euch, Halunke!', 28153),
