(148704, 'deDE', 'Euch zeige ich, wo Euer Platz ist!', 'Euch zeige ich, wo Euer Platz ist!', 28153),
(148703, 'deDE', 'Kommt nur her!', 'Kommt nur her!', 28153),
(148701, 'deDE', 'Davon stand nichts in meinem Vertrag!', 'Davon stand nichts in meinem Vertrag!', 28153),
(148700, 'deDE', 'Dafür zahlen sie mir nicht genug!', 'Dafür zahlen sie mir nicht genug!', 28153),
(148699, 'deDE', '', 'Sicherheit geht vor!', 28153),
(148698, 'deDE', '', 'Ich liebe den Geruch von Treibstoff am Morgen!', 28153),
(148697, 'deDE', 'Das ist \'ne lange Geschichte, die kann wart\'n. Er trifft bald Bwonsamdi, wenn wir uns nich\' beeilen.', 'Das ist \'ne lange Geschichte, die kann wart\'n. Er trifft bald Bwonsamdi, wenn wir uns nich\' beeilen.', 28153),
(148696, 'deDE', '', 'Ihr habt Euch mit \'nem Sethrak verbündet?', 28153),
(148695, 'deDE', 'Mir geht\'s gut, aber mein Freund macht\'s nich\' mehr lang.', 'Mir geht\'s gut, aber mein Freund macht\'s nich\' mehr lang.', 28153),
(148694, 'deDE', 'Die Allianz denkt, sie könnte Nachschub transportieren, ohne uns was abzugeben? Drom\'kal hat einen Plan und dafür braucht er Freiwillige in der Rüstkammer... und zwar dalli!', '', 28153),
(148693, 'deDE', 'Hey! Es wurden ein paar Holzfäller der Allianz gesichtet! Bringt sie um die Ecke und schnappt Euch Ihr Holz.', '', 28153),
(148692, 'deDE', 'Oh-oh, das verheißt nichts Gutes! Bleichborken von Osten!', '', 28153),
(148691, 'deDE', 'Wir machen das Tal wieder flott.', 'Wir machen das Tal wieder flott.', 28153),
(148690, 'deDE', 'Behaltet da draußen einen klaren Kopf.', 'Behaltet da draußen einen klaren Kopf.', 28153),
(148689, 'deDE', 'Lasst Euch vom Sturmgesang lotsen.', 'Lasst Euch vom Sturmgesang lotsen.', 28153),
(148688, 'deDE', 'Wir streichen nicht die Segel.', 'Wir streichen nicht die Segel.', 28153),
(148687, 'deDE', 'Sturmsang trotzt jedem Wetter.', 'Sturmsang trotzt jedem Wetter.', 28153),
(148686, 'deDE', 'Ihr seid weit weg von zu Hause.', 'Ihr seid weit weg von zu Hause.', 28153),
(148685, 'deDE', 'Hütet Euch vor unbekannten Gesichtern.', 'Hütet Euch vor unbekannten Gesichtern.', 28153),
(148684, 'deDE', 'Lasst Euch nicht mit Hexen ein.', 'Lasst Euch nicht mit Hexen ein.', 28153),
(148683, 'deDE', 'Ruhm dem Haus Kronsteig.', 'Ruhm dem Haus Kronsteig.', 28153),
(148682, 'deDE', 'Kommt jederzeit wieder.', 'Kommt jederzeit wieder.', 28153),
(148681, 'deDE', 'Ein wahres Vergnügen.', 'Ein wahres Vergnügen.', 28153),
(148680, 'deDE', 'Auf bald.', 'Auf bald.', 28153),
(148679, 'deDE', 'Möge der Wind Eure Segel füllen.', 'Möge der Wind Eure Segel füllen.', 28153),
