(148665, 'deDE', 'Wünscht Ihr Parley?', 'Wünscht Ihr Parley?', 28153),
(148664, 'deDE', 'Seht Euch in Ruhe um.', 'Seht Euch in Ruhe um.', 28153),
(148663, 'deDE', 'Die See sei Euch gewogen.', 'Die See sei Euch gewogen.', 28153),
(148662, 'deDE', 'Ich diene allen Getreuen der See.', 'Ich diene allen Getreuen der See.', 28153),
(148661, 'deDE', 'Ich werde dem Sturm trotzen.', 'Ich werde dem Sturm trotzen.', 28153),
(148660, 'deDE', 'Oh! Mir scheint, das Wasser steht uns bis zum Hals.', 'Mir scheint, das Wasser steht uns bis zum Hals.', 28153),
(148659, 'deDE', 'Gibt es Neues vom Festland?', 'Gibt es Neues vom Festland?', 28153),
(148658, 'deDE', 'Ich fürchte, Frieden ist uns einfach nicht vergönnt.', 'Ich fürchte, Frieden ist uns einfach nicht vergönnt.', 28153),
(148657, 'deDE', 'Sehr erfreut, Eure Bekanntschaft zu machen.', 'Sehr erfreut, Eure Bekanntschaft zu machen.', 28153),
(148656, 'deDE', 'Bringt der Wind Neuigkeiten?', 'Bringt der Wind Neuigkeiten?', 28153),
(148655, 'deDE', 'Was verschafft mir die Ehre?', 'Was verschafft mir die Ehre?', 28153),
(148654, 'deDE', 'Sehr erfreut, doch, doch.', 'Sehr erfreut, doch, doch.', 28153),
(148653, 'deDE', 'Große Güte... so spät ist es schon? Ihr wolltet sicherlich gerade gehen, nicht wahr?', 'Große Güte... so spät ist es schon? Ihr wolltet sicherlich gerade gehen, nicht wahr?', 28153),
(148652, 'deDE', 'Hört Ihr das? Jemand scheint Euch zu rufen und es klingt überaus wichtig!', 'Hört Ihr das? Jemand scheint Euch zu rufen und es klingt überaus wichtig!', 28153),
(148651, 'deDE', 'Wie unhöflich von mir, Euch so lange aufzuhalten. Irgendwo muss es doch jemanden geben, der tatsächlich das Bedürfnis hat, mit Euch zu reden.', 'Wie unhöflich von mir, Euch so lange aufzuhalten. Irgendwo muss es doch jemanden geben, der tatsächlich das Bedürfnis hat, mit Euch zu reden.', 28153),
(148650, 'deDE', 'Was kann ich für Euch tun?', 'Was kann ich für Euch tun?', 28153),
(148649, 'deDE', 'Gunst der Lordadmiralin!', 'Gunst der Lordadmiralin!', 28153),
(148648, 'deDE', 'Moin Moin!', 'Moin Moin!', 28153),
(148647, 'deDE', 'Ahoi!', 'Ahoi!', 28153),
(148646, 'deDE', 'Hilfe! Hilfe! Ich werde unterdrückt!', 'Hilfe! Hilfe! Ich werde unterdrückt!', 28153),
(148645, 'deDE', 'Nicht alles im Lot auf Eurem Boot, was?', 'Nicht alles im Lot auf Euerm Boot, was?', 28153),
(148644, 'deDE', 'Euch sitzt der Finger locker, was?', 'Euch sitzt der Finger locker, was?', 28153),
(148643, 'deDE', 'Auf dass die See Euren Bauch füllt.', 'Auf dass die See Euren Bauch füllt.', 28153),
(148642, 'deDE', 'Auf jedem Weg sind ein paar Pfützen.', 'Auf jedem Weg sind ein paar Pfützen.', 28153),
(148641, 'deDE', 'Wir holen uns zurück, was uns gehört.', 'Wir holen uns zurück, was uns gehört.', 28153),
(148640, 'deDE', 'Die Zeiten waren auch mal einfacher.', 'Die Zeiten waren auch mal einfacher.', 28153),
