INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'deDE', 'Hier gibt\'s das Beste vom Besten aus ganz Kul Tiras.', 'Hier gibt\'s das Beste vom Besten aus ganz Kul Tiras.', 28153),
