(148561, 'deDE', 'Allzeit günstigen Wind.', 'Allzeit günstigen Wind.', 28153),
(148560, 'deDE', 'Gute Fahrt.', 'Gute Fahrt.', 28153),
(148559, 'deDE', 'Abwarten und Tee trinken.', 'Abwarten und Tee trinken.', 28153),
(148553, 'deDE', 'Lasst uns hier alles niederbrennen!', 'Tötet sie, wie Nisha es tun würde!', 28153),
(148552, 'deDE', 'Viel Glück!', 'Viel Glück!', 28153),
(148551, 'deDE', 'Der nächste Treulose gehört mir!', 'Mit diesem Schwert werde ich einiges ausrichten!', 28153),
(148550, 'deDE', 'Ein gutes Gefühl, wieder eine Waffe in den Händen zu halten.', 'Sie werden die Vulpera fürchten!', 28153),
(148549, 'deDE', 'Sehr erfreut, doch, doch.', 'Sehr erfreut, doch, doch.', 28153),
(148548, 'deDE', 'Was verschafft mir die Ehre?', 'Was verschafft mir die Ehre?', 28153),
(148547, 'deDE', '', 'Ah, die sin\' perfekt! Un\' macht Euch ma\' keine Sorg\'n um Raals Gefühle. Der kommt schon klar.', 28153),
(148546, 'deDE', '', 'Mein Mann will kein\' Pterrordaxspeichel für unsre Trankbrauer sammeln. Er wird langsam weichlich. Geht und sammelt mir so viele Speicheldrüs\'n, wie Ihr könnt.', 28153),
(148545, 'deDE', 'Gute Arbeit, Mann. Da werden unsre Weisen \'ne Weile dran rumstudier\'n.', '', 28153),
(148544, 'deDE', 'Bringt der Wind Neuigkeiten?', 'Bringt der Wind Neuigkeiten?', 28153),
(148543, 'deDE', 'Sehr erfreut, Eure Bekanntschaft zu machen.', 'Sehr erfreut, Eure Bekanntschaft zu machen.', 28153),
(148542, 'deDE', 'Viele Tortollaner sin\' von diesen Bluttrollbarbaren abgeschlachtet word\'n, aber wir könn\' wenigstens ihr Wissen bewahr\'n. Rettet so viele von ihren Schriftroll\'n, wie Ihr könnt!', '', 28153),
(148541, 'deDE', 'Hilfe! Hilfe! Ich werde unterdrückt!', 'Hilfe! Hilfe! Ich werde unterdrückt!', 28153),
(148540, 'deDE', '', 'Das... kann nicht sein...', 28153),
(148539, 'deDE', 'Nu macht mal Butter bei die Fische.', 'Nu macht mal Butter bei die Fische.', 28153),
(148538, 'deDE', '', 'Meine Magie... hat versagt?', 28153),
(148537, 'deDE', '', 'Mir wurde... Macht versprochen...', 28153),
(148536, 'deDE', 'Solange ihre Seelen leiden, kann ich keine neuen Anhänger annehmen. Die Ehre verbietet es mir.', '', 28153),
(148535, 'deDE', 'Denkt Ihr, ein bisschen Säbelrasseln bringt mich zum Zittern?', 'Denkt Ihr, ein bisschen Säbelrasseln bringt mich zum Zittern?', 28153),
(148534, 'deDE', '', 'Die Macht... sie schwindet...', 28153),
(148533, 'deDE', '', 'Meine Schwestern werden Euch vernichten...', 28153),
(148532, 'deDE', '', 'Euer Blut wird meinen Ritualen Macht verleihen!', 28153),
(148531, 'deDE', '', 'Ihr gebt ein würdiges Opfer ab!', 28153),
(148530, 'deDE', '', 'Alle werden dem Herzbann dienen!', 28153),
(148529, 'deDE', '', 'Mutter, schenkt mir Macht!', 28153),
(148528, 'deDE', 'Aber als meine Fangzähne das Herz ihrer Anführerin durchbohrten, verdammte sie die Seelen meiner Anhänger zu unendlichen Qualen.', '', 28153),
(148527, 'deDE', '', 'Mein Leben für den Zirkel!', 28153),
(148526, 'deDE', 'Es ist mir gleich, dass sie tot ist. Eine Person weniger, die mir in die Quere kommt.', '', 28153),
(148525, 'deDE', 'Dass sie sich der Hexerei zuwendet, um sich an mir zu rächen...', '', 28153),
(148524, 'deDE', 'Ich jagte die übrigen Naga bis auf den letzten. Keiner entkam meinem Zorn...', '', 28153),
(148523, 'deDE', 'Meine Arbeit ist mein Leben! Vergesst Petula, vergesst Benjamin... Das hier ist mein Vermächtnis.', '', 28153),
(148522, 'deDE', 'Ich habe ganz klein angefangen! Ich habe dieses Geschäft aufgebaut, um meine Frau und unsere Familie zu ernähren.', '', 28153),
(148521, 'deDE', 'Ruhm dem Haus Kronsteig.', 'Ruhm dem Haus Kronsteig.', 28153),
(148520, 'deDE', 'Ich war nicht immer der Präsident eines erfolgreichen Holzunternehmens, wisst Ihr?', '', 28153),
(148519, 'deDE', 'Lasst Euch nicht mit Hexen ein.', 'Lasst Euch nicht mit Hexen ein.', 28153),
(148518, 'deDE', 'Hütet Euch vor unbekannten Gesichtern.', 'Hütet Euch vor unbekannten Gesichtern.', 28153),
(148517, 'deDE', 'Abstand halten, Festländer.', 'Abstand halten, Festländer.', 28153),
(148516, 'deDE', 'Freund oder Feind?', 'Freund oder Feind?', 28153),
(148515, 'deDE', 'In welcher Angelegenheit kommt Ihr zu mir?', 'In welcher Angelegenheit kommt Ihr zu mir?', 28153),
(148514, 'deDE', 'Vor Jahrhunderten wurde dieser Tempel von den Naga angegriffen. Ich kam zu spät, um meine Anhänger zu retten.', '', 28153),
(148513, 'deDE', 'Ich habe Mitgefühl mit den Tortaka und ihrer Not gegen die Naga. Aber ich kann sie nicht beschützen.', '', 28153),
(148512, 'deDE', 'Ruhige See und guten Wind.', 'Ruhige See und guten Wind.', 28153),
(148511, 'deDE', 'Auf jedem Weg sind ein paar Pfützen.', 'Auf jedem Weg sind \'n paar Pfützen.', 28153),
(148510, 'deDE', 'Wir holen uns zurück, was uns gehört.', 'Wir holen uns zurück, was uns gehört.', 28153),
(148509, 'deDE', 'Früher war alles einfacher.', 'Früher war alles einfacher.', 28153),
(148508, 'deDE', 'Helfende Hände sind immer willkommen.', 'Helfende Hände sind immer willkommen.', 28153),
(148507, 'deDE', 'Ihr seid nicht von hier, oder?', 'Ihr seid nicht von hier, oder?', 28153),
(148506, 'deDE', 'Sturmsang wird wieder rein sein.', 'Sturmsang wird wieder rein sein.', 28153),
(148505, 'deDE', 'Fürchtet, was in der Tiefe lauert.', 'Fürchtet, was in der Tiefe lauert.', 28153),
(148504, 'deDE', 'Möge der Wind Eure Segel füllen.', 'Möge der Wind Eure Segel füllen.', 28153),
(148503, 'deDE', 'Wir werden diesem Sturm trotzen.', 'Wir werden diesem Sturm trotzen.', 28153),
(148502, 'deDE', 'Wer die See achtet, ist mir willkommen.', 'Wer die See achtet, ist mir willkommen.', 28153),
(148501, 'deDE', 'Die See sei Euch gewogen.', 'Die See sei Euch gewogen.', 28153),
(148500, 'deDE', 'Wir machen das Tal wieder flott.', 'Wir machen das Tal wieder flott.', 28153),
(148499, 'deDE', 'Behaltet da draußen einen klaren Kopf.', 'Behaltet da draußen einen klaren Kopf.', 28153),
(148498, 'deDE', 'Lasst Euch vom Sturmgesang lotsen.', 'Lasst Euch vom Sturmgesang lotsen.', 28153),
(148497, 'deDE', 'Wir streichen nicht die Segel.', 'Wir streichen nicht die Segel.', 28153),
(148496, 'deDE', 'Sturmsang trotzt jedem Wetter.', 'Sturmsang trotzt jedem Wetter.', 28153),
(148495, 'deDE', 'Ihr seid weit weg von zu Hause.', 'Ihr seid weit weg von zu Hause.', 28153),
(148493, 'deDE', 'Gleichfalls. Un\', $n, Ihr habt echtes Mojo. Schaut vorbei, wenn Ihr ma\' in Vol\'dun seid, ja?', '', 28153),
(148492, 'deDE', 'Lebt wohl, Jin\'Tiki. Überlebt.', '', 28153),
(148491, 'deDE', 'Ich kümmere mich drum.', '', 28153),
(148490, 'deDE', 'Macht es wie geplant. Und jetzt los.', '', 28153),
(148489, 'deDE', 'Ha! Das is\' das Bekloppteste, was ich je gemacht hab!', '', 28153),
(148488, 'deDE', 'Zulajin is\' tot! Verschwind\'n wir hier.', '', 28153),
(148487, 'deDE', 'Gute Arbeit! Weiter so!', '', 28153),
(148486, 'deDE', 'Aah!', 'Aah!', 28153),
(148485, 'deDE', 'Fresst mich nicht!', 'Fresst mich nicht!', 28153),
(148484, 'deDE', 'Ack!', 'Ack!', 28153),
(148483, 'deDE', 'Woran hat Papa gearbeitet, um so etwas zu verursachen...?', '', 28153),
(148482, 'deDE', 'Wie bewegt sich der Honig nur so ganz von alleine?', '', 28153),
(148481, 'deDE', '<Keuch> Ähhhm, $p... ist der H-Honig etwa l-l-lebendig?', '', 28153),
(148480, 'deDE', 'Danke, Fremdling.', 'Danke, Fremdling.', 28153),
(148479, 'deDE', 'Ich sorge dafür, dass die Sethrak nicht mal mehr ihre eigene Beute haben, wenn sie hier verschwinden.', 'Ich sorge dafür, dass die Sethrak nicht mal mehr ihre eigene Beute haben, wenn sie hier verschwinden.', 28153),
(148478, 'deDE', 'Lasst uns ein kleines Spiel spielen. Ich nenne es \"Schlangen und Füchse\"...', 'Lasst uns ein kleines Spiel spielen. Ich nenne es \"Schlangen und Füchse\"...', 28153),
(148477, 'deDE', 'Wuhu! Ich bin frei. Ihr habt mich nicht gefressen.', 'Wuhu! Ich bin frei. Ihr habt mich nicht gefressen.', 28153),
(148476, 'deDE', 'Das reicht jetzt. Jetzt nehme ich das Doppelte.', 'Das reicht jetzt. Jetzt nehme ich das Doppelte.', 28153),
(148475, 'deDE', '', 'Wie schön, dass die Sande Euch noch nicht verschlungen haben, $n!', 28153),
(148473, 'deDE', 'Großer Loa, dieses Opfer bringt der Stamm der Tortaka dar.', 'Großer Loa, dieses Opfer bringt der Stamm der Tortaka dar.', 28153),
(148472, 'deDE', 'Fallen lassen!', '', 28153),
(148471, 'deDE', 'Nicht so schnell!', '', 28153),
(148470, 'deDE', 'Das werdet Ihr bereuen.', '', 28153),
(148469, 'deDE', 'Das würde ich an Eurer Stelle nicht tun.', '', 28153),
(148468, 'deDE', 'Gebt das zurück!', '', 28153),
(148467, 'deDE', 'Ha! So nicht! Das gehört mir.', '', 28153),
(148466, 'deDE', 'Lasst bloß die Finger davon, Freundchen.', '', 28153),
(148463, 'deDE', 'Schlechte Entscheidung.', '', 28153),
(148462, 'deDE', 'Zu einem guten Kampf sage ich nie nein.', '', 28153),
(148461, 'deDE', 'Ihr werdet für Eure Taten zahlen!', '', 28153),
(148460, 'deDE', 'Ihr da!', '', 28153),
(148459, 'deDE', 'Das werdet Ihr bereuen!', '', 28153),
(148458, 'deDE', 'Nicht heute!', '', 28153),
(148456, 'deDE', 'Passt auf, wohin Ihr tretet.', '', 28153),
(148455, 'deDE', 'Mein Fernrohr ist am unteren Vorsprung mit dem Krater im Norden im Blick.', '', 28153),
(148454, 'deDE', '', 'Terrorhorndinomantie! Wie erfrischend. Also, die verstauen wir erstmal, wo Kojo sie nicht finden kann.', 28153),
(148453, 'deDE', '', 'Ich habe einen Haufen alter Schriftrollen ausgegraben, weiß aber überhaupt nicht, was sie machen. Probiert sie doch bitte für mich aus. Das könnte Spaß machen.', 28153),
(148452, 'deDE', 'Benutzt den Fetisch! Jagt das Ding in die Luft!', '', 28153),
(148451, 'deDE', 'LAUFT!', '', 28153),
(148450, 'deDE', 'AAHHH!', '', 28153),
(148449, 'deDE', 'Äh... Irgendwas stimmt da nich\'. Ich spür \'ne ganz fiese Blutmagie von da drüb\'n...', '', 28153),
(148448, 'deDE', 'Ihr habt\'s geschafft! Das is\' das Ende für Zulajin.', '', 28153),
(148447, 'deDE', 'Haha! Das muss ich Pa\'ku erzähl\'n!', '', 28153),
(148446, 'deDE', 'Die Nachtgebor\'nen woll\'n die Eindringlinge in Xibala auf ihre Art zum Geh\'n auffordern. Das sollte \'nen Blick wert sein.', '', 28153),
(148420, 'deDE', '', 'Gut gemacht. Vielleicht werden diese Gewässer eines Tages wieder sicher.', 28153),
(148419, 'deDE', '', 'Ihr beiden habt jetzt genug gesungen!', 28153),
(148418, 'deDE', '', 'Gut. Alle sin\' hier. Lasst uns keine Zeit verlier\'n.', 28153),
(148416, 'deDE', 'Danke, Mann. Diese Bluttrolle ham jed\'n Schlag verdient, den sie eingesteckt ham!', '', 28153),
(148415, 'deDE', 'Zu seh\'n, wie diese Schwachköpfe die Leiche eines Loas entweih\'n... Dafür bezahl\'n sie! Metzelt sie nieder!', '', 28153),
(148414, 'deDE', '', 'Na, wer is\' hier \'n braver Zandalarifratzenbeißer? Du!', 28153),
(148413, 'deDE', '', 'Unsre mächtigen Verbündeten müss\'n lern\', wie man gegen unsre Feinde kämpft. Bringt diesem Jungchen bei, wie\'s auf dem Schlachtfeld zugeht.', 28153),
(148412, 'deDE', 'Und so ward es gehört:\n\nEinst wandte der große Loa sich einer Versammlung seiner Anhänger zu und sprach:\n\n\"So wie der Jaguar tagelang seine Beute verfolgt, so handelt auch der Weise mit Geduld in all seinen Belangen. Jene aber, die sich im Leben von Verlangen und Gefühlen leiten lassen, werden im Dschungel nicht lange überleben.\n\nSo wie der Dschungel uns das Geschenk des Lebens spendet, so spendet er auch die Berührung des Todes. Jene, die Erleuchtung erfahren, sehen, dass die Natur nicht ihnen gehört, sondern sie ihr. Sie respektieren die natürliche Ordnung und nehmen nur das, was sie zum Leben benötigen.\"\n\nAls die Anhänger Eraka no Kimbuls seine Worte vernahmen, erfüllten diese sie mit Geduld und Respekt.', '', 28153),
(148411, 'deDE', 'Und so ward es gehört:\n\nEinst wandte der große Loa sich einer Versammlung seiner Anhänger zu und sprach:\n\n\"So wie ein König seinen größten Schatz nicht für eine bloße Handvoll Unrat preisgibt, so bietet auch der Ehrenhafte seine Integrität nicht für Reichtum oder Ruhm feil. Lebt Euer Leben in Ehre, und es wird ein erfülltes Leben sein.\n\nSo wie Schluchten durch den stetigen Fluss des Wassers geformt werden, so sind auch alle großen Taten aus Beharrlichkeit geboren. Lebt mit unbeugsamer Entschlossenheit, und kein Versagen wird Euch jemals in die Knie zwingen.\"\n\nAls die Anhänger Eraka no Kimbuls Worte vernahmen, erfüllten diese sie mit Tugend und Hingabe.', '', 28153),
(148410, 'deDE', 'Und so ward es gehört:\n\nEinst wandte der große Loa sich einer Versammlung seiner Anhänger zu und sprach:\n\n\"So wie der Tiger bei der Jagd über Fels und Kluft springt, so verschwendet auch der Mutige keine Zeit damit, in Angst zu kauern. Handelt mutig in allen Belangen, und Eure Beute wird Euch nicht entrinnen.\n\nSo wie Fäulnis an den Blüten des Dschungels zehrt, so zehrt auch das Alter an der Stärke der Jugend. Der Ursprung der Macht liegt nicht in der Stärke, sondern in jenem unbezähmbaren Willen, den auch das Alter nicht zu brechen vermag.\"\n\nAls die Anhänger Eraka no Kimbuls Worte vernahmen, erfüllten diese sie mit Mut und Überzeugung.', '', 28153),
(148408, 'deDE', 'Eraka no Kimbul, Loa der Tiger, Herr aller Tiere, König aller Katzen und Untergang seiner Beute.', '', 28153),
(148400, 'deDE', 'Ich hab Narben, die sind älter als Eure Sprache.', '', 28153),
(148399, 'deDE', 'Ich brauche jemand Junges, mit einem gesunden Rücken, der bereit ist, sich mit den Kräften des Bösen anzulegen... gegen Bezahlung, versteht sich.', '', 28153),
(148398, 'deDE', '', 'Seid Ihr hier, um mit der alten Nola zu sprechen?', 28153),
(148397, 'deDE', 'Bin hier bei der Arbeit, Schuppi!', 'Bin hier bei der Arbeit, Schuppi!', 28153),
(148396, 'deDE', 'Euch wird das Lachen schon noch vergehen, wenn wir frei sind...', 'Euch wird das Lachen schon noch vergehen, wenn wir frei sind...', 28153),
(148395, 'deDE', 'Schon gut! Schon gut!', 'Schon gut! Schon gut!', 28153),
(148394, 'deDE', 'Aua! Weg da!', 'Aua! Weg da!', 28153),
(148393, 'deDE', '<An der Statue scheinen sich Zeichen zu befinden. Ihre Bedeutung ist aber schon seit langer Zeit verloren gegangen.>', '', 28153),
(148392, 'deDE', '<An der Statue scheinen sich Zeichen zu befinden. Ihre Bedeutung ist aber schon seit langer Zeit verloren gegangen.>', '<An der Statue scheinen sich Zeichen zu befinden. Ihre Bedeutung ist aber schon seit langer Zeit verloren gegangen.>', 28153),
(148391, 'deDE', '<An der Statue scheinen sich Zeichen zu befinden. Ihre Bedeutung ist aber schon seit langer Zeit verloren gegangen.>', '', 28153),
(148389, 'deDE', 'Sie ermordeten Sulthis, aber er konnte vorher seinen Schlüssel noch schützen. Diejenigen von uns, die Sethraliss treu blieben, mussten fliehen. Seither kämpfen wir gegen die Treulosen.', '', 28153),
(148388, 'deDE', 'Korthek stellte eine Armee aus Gleichgesinnten auf, und sie begannen zu töten, wer sich ihnen widersetzte.', '', 28153),
(148387, 'deDE', '', 'Wir müss\'n die Prinzessin warn\'.', 28153),
(148386, 'deDE', '', '\'ne Waffe... Das is\' es, was Jakra\'zet sucht! Ein C\'Thrax...', 28153),
(148385, 'deDE', 'Er plante im Geheimen, den C\'Thrax auszugraben und mit dieser Waffe den ganzen Kontinent zu erobern.', '', 28153),
(148384, 'deDE', 'Über die Jahre wurde Korthek unserer Lebensweise überdrüssig. Wir lebten seit jeher in Frieden mit den Trollen im angrenzenden Gebiet, aber Korthek wollte Krieg.', '', 28153),
(148383, 'deDE', 'Jahrelang lebten wir in Frieden, wie Sethraliss es gewollt hätte. Unser Land war zerstört, unser Loa nicht mehr da, aber wir passten uns an. Wir zweifelten nicht daran, dass Sethraliss eines Tages zurückkehren würde.', '', 28153),
(148382, 'deDE', 'Um die Barriere zu sichern, erschuf jeder von uns einen Schlüssel. Die Magie, mit der wir die Barriere formten, kann nur mit allen drei Schlüsseln gebannt werden. So wurden die Hüter geboren.', '', 28153),
(148381, 'deDE', 'Wir verbliebenen Anhänger von Sethraliss wurden aus unserer Heimat\nin den Untergrund gezwungen. Seitdem bekämpfen wir die Treulosen.', '', 28153),
(148380, 'deDE', 'Korthek rekrutierte eine Armee gleichgesinnter Sethrak und metzelte alle nieder, die sich widersetzten...\nSulthis war der Erste, der fiel, aber zuvor konnte er noch seinen Schlüssel schützen.', '', 28153),
(148379, 'deDE', 'Als der Sand sich weiter ausbreitete, dürstete es Korthek nach Krieg.\nEr plante insgeheim, den C\'Thrax zu befreien und mit ihm als Waffe den Kontinent zu erobern.', '', 28153),
(148378, 'deDE', 'Trotz seiner immensen Macht konnte Sulthis die Barriere nicht allein beschwören.\nKorthek und ich standen ihm bei und gemeinsam versiegelten wir Mythrax in der großen Pyramide.', '', 28153),
(148377, 'deDE', 'Nachdem wir Zeugen seiner Zerstörung wurden, mussten wir sicherstellen, dass niemand Mythrax je wieder erwecken konnte.', '', 28153),
(148376, 'deDE', 'Unser Loa opferte sich, um uns vor dieser Monstrosität zu schützen. Sie hat den C\'Thrax erschlagen,\naber erst, nachdem er bereits die Scheibe im Herzen von Atul\'Aman zerstört hatte.', '', 28153),
(148375, 'deDE', 'Vor langer Zeit fiel Mythrax der Auflöser über unser Land her. Er tötete alles in seinem Weg, egal ob Troll oder Sethrak.', '', 28153),
(148374, 'deDE', 'Dieser Schlüssel gehörte dem ersten Hüter. Er hieß Sulthis und er starb durch die Hand von Korthek.', '', 28153),
(148365, 'deDE', '', 'Mainhardt schickt also Schläger, um seine Probleme zu lösen, wie immer. Dann mal los, $gFreundchen:meine Liebe;. Ich werde Euch zerquetschen wie die anderen vor Euch!', 28153),
(148364, 'deDE', 'Eine Hexe... Warum hat eine Hexe unseren Betrieb im Visier?! Ich muss weg hier. Ich werde meinem Vater Bescheid sagen!', '', 28153),
(148361, 'deDE', 'François bemerkt Euren gefüllten Geldbeutel und hält es für angebracht, Euch etwas Zeit zu widmen.', '', 28153),
(148360, 'deDE', 'Ihr klingelt ein wenig mit Eurem Geldbeutel.', 'Ihr klingelt ein wenig mit Eurem Geldbeutel.', 28153),
(148359, 'deDE', 'Wenn Ihr diese Spinne ausschaltet... würdet Ihr einer Menge Leuten helfen.', '', 28153),
(148358, 'deDE', 'Gut... Ihr scheint einen Weg freigemacht zu haben. Ich glaube, ich schaffe es jetzt alleine hier raus.', '', 28153),
(148357, 'deDE', 'François pickt hochnäsig nach Euren Füßen.', '', 28153),
(148356, 'deDE', 'Der Imperator wird sich um Euch kümmern.', '', 28153),
(148355, 'deDE', 'Ihr habt mich beim Essen gestört, $PR. Ich habe Leute schon aus harmloseren Gründen umgebracht.', '', 28153),
(148354, 'deDE', '<Gebt Vorrik Sulthis\' Stein.>', '<Gebt Vorrik Sulthis\' Stein.>', 28153),
(148353, 'deDE', 'Das wär erledigt. Wer hätt\' gedacht, dass Froschmojo so stark sein kann?', '', 28153),
(148352, 'deDE', 'Die Naga entzieh\'n dem Froschloa die Macht! Haltet sie auf un\' zerstört ihr Lager.', '', 28153),
(148351, 'deDE', 'Seid gesegnet, Fremdling. Meine geflügelt\'n Kumpels sin\' bereit, Euch hinzuflieg\'n, wo immer Ihr hinwollt.', 'Seid gesegnet, Fremdling. Meine geflügelt\'n Kumpels sin\' bereit, Euch hinzuflieg\'n, wo immer Ihr hinwollt.', 28153),
(148350, 'deDE', 'Ich bin wieder am Leben! Habt Dank. Ich stehe Euch zu Diensten, wann immer Ihr mich braucht.', 'Ich bin wieder am Leben! Habt Dank. Ich stehe Euch zu Diensten, wann immer Ihr mich braucht.', 28153),
(148349, 'deDE', 'Bwonsamdi segne Euch!', 'Bwonsamdi segne Euch!', 28153),
(148348, 'deDE', 'Mein schicker Stein! Nur für mich!', '', 28153),
(148347, 'deDE', '', 'Wir müss\'n mit Vorrik red\'n.', 28153),
(148345, 'deDE', 'Haltet Euch zurück. Wenn sie nach Vorrik suchen, können sie uns vielleicht helfen...', '', 28153),
(148344, 'deDE', 'Ich bin wie neugeboren! Habt Dank, Fremdling.', 'Ich bin wie neugeboren! Habt Dank, Fremdling.', 28153),
(148342, 'deDE', '', 'Ah, Ihr habt Verstärkung mitgebracht.', 28153),
(148340, 'deDE', '', 'Ganz ruhig. Mein Freund ist einer von den Guten.', 28153),
(148339, 'deDE', 'Ja! Darum geht\'s eigentlich, Nimmy, um Muscheln. Man muss die Muscheln mögen...', '', 28153),
(148338, 'deDE', 'Eine Minute lang hat es alles aufgehört. Mir war kalt. Mir war heiß... ich wollte sagen...', '', 28153),
(148337, 'deDE', 'Und Korl... Korl nahm die Klinge... Seine Augen sind einfach... einfach erloschen...', '', 28153),
(148336, 'deDE', 'Flossen und Klingen und Gelächter und Dunkelheit... da war Blut...', '', 28153),
(148335, 'deDE', 'Eigentlich war es der langweiligste Posten auf dem Meer... bis er es nicht mehr war... als sie gekommen sind...', '', 28153),
(148334, 'deDE', 'Egal, es war überragend! Es war entsetzlich!', '', 28153),
(148333, 'deDE', 'Moment mal, du bist doch kein Niemand, oder? Ich hab mich da ja schon mal geirrt...', '', 28153),
(148332, 'deDE', 'Ich wette eine Nagawarze, dass du davon gehört hast... Es gibt doch niemanden, der die Geschichten von der Schlacht am Scarvingraben nicht kennt.', '', 28153),
(148331, 'deDE', 'WAS?! Noch nie was von der Schlacht am Scarvingraben gehört?', '', 28153),
(148330, 'deDE', 'Ihr kennt doch die Schlacht am Scarvingraben, oder? Ganz da unten...', '', 28153),
(148329, 'deDE', 'Also, wie auch immer, Korl und ich haben über die Schlacht gesprochen.', '', 28153),
(148328, 'deDE', 'Ich liebe dich, mein kleiner schuppiger Freund.', '', 28153),
(148327, 'deDE', 'Ich hab das mal gesehen. Es war uuuuuuuunglaublich!', '', 28153),
(148326, 'deDE', 'Wusstest du, dass hier mal Feuer unter dem Wasser war?', '', 28153),
(148325, 'deDE', 'Aber das ist ja nicht mal das Thema jetzt... Das Thema ist eigentlich, dass...', '', 28153),
(148324, 'deDE', 'Er war\'s zumindest nicht. Er hat mich nur angeglotzt und dann eine Krabbe zermatscht...', '', 28153),
(148323, 'deDE', 'Du wärst beeindruckt gewesen, oder? Oder du hättest zumindest so getan?', '', 28153),
(148322, 'deDE', 'Da war ich traurig.', '', 28153),
(148321, 'deDE', 'Ich hab mal eine Muschel gefunden. War eine richtig schöne. Ich hab\'s Korl erzählt, aber ihm war\'s egal.', '', 28153),
(148320, 'deDE', 'Niemals nicht mag ich Seepocken. Korl sagt, dass Leute, die Seepocken mögen, böse sind.', '', 28153),
(148318, 'deDE', 'So viel hat sich verändert, seit Korthek und ich hier gemeinsam die Weisheit von Sethraliss lehrten...\n\nDie heiligen Stätten liegen heute in Trümmern, und Sethraliss ist bestenfalls in Vergessenheit geraten... Viel häufiger wird sie jedoch geschmäht.\n\nKorthek, mein alter Freund... Was habt Ihr unserem Volk nur angetan?', '', 28153),
(148317, 'deDE', 'Schlimm, diese Seepocken. Nimmy, was ist mit dir? Magst du Seepocken?', '', 28153),
(148316, 'deDE', 'Mit Seepocken jucken meine Füße immer wie die Hölle. Ich hasse das. Korl mag die fiesen Dinger auch nicht.', '', 28153),
(148315, 'deDE', 'Seepocken sind schlimm.', '', 28153),
(148314, 'deDE', 'Also, mein Kumpel Korl, kennst du den eigentlich? Also, mein Kumpel Korl zumindest, der meint, wenn man mit einer Balliste zwischen den Zehen rumstochert, kriegt die Seepocken gut weg.', '', 28153),
(148313, 'deDE', 'Ihr gehört hier nicht her!', 'Ihr gehört hier nicht her!', 28153),
(148312, 'deDE', 'Einen Dunkeleisenzwerg fordert Ihr nur einmal raus!', 'Einen Dunkeleisenzwerg fordert Ihr nur einmal raus!', 28153),
(148311, 'deDE', 'Spürt die Macht des Berges!', 'Spürt die Macht des Berges!', 28153),
(148310, 'deDE', 'Euch werd ich zusammenstutzen!', 'Euch werd ich zusammenstutzen!', 28153),
(148309, 'deDE', 'Zeigt, was Ihr drauf habt!', 'Zeigt, was Ihr drauf habt!', 28153),
(148308, 'deDE', 'Genießt Euren letzten Atemzug!', 'Genießt Euren letzten Atemzug!', 28153),
(148307, 'deDE', 'Brennt im Feuer meiner Wut!', 'Brennt im Feuer meiner Wut!', 28153),
(148306, 'deDE', 'Ihr könnt... mein Feuer... nicht löschen...', 'Ihr könnt... mein Feuer... nicht löschen...', 28153),
(148305, 'deDE', 'Mein Volk... wird mich... rächen...', 'Mein Volk... wird mich... rächen...', 28153),
(148304, 'deDE', 'Meine Seele... ruht im... Amboss...', 'Meine Seele... ruht im... Amboss...', 28153),
(148303, 'deDE', 'Ich... könnte ein... Kühles vertragen...', 'Ich... könnte ein... Kühles vertragen...', 28153),
(148302, 'deDE', 'Seid... verflucht...', 'Seid... verflucht...', 28153),
(148301, 'deDE', 'Ich geb mein Leben... für die Königin...', 'Ich geb mein Leben... für die Königin...', 28153),
(148300, 'deDE', 'Im Feuer... werde ich... wiedergeboren...', 'Im Feuer... werde ich... wiedergeboren...', 28153);
