(145835, 'deDE', '<Big attack: Total 5>', '', 28153),
(145834, 'deDE', '<Convey releasing power or charging enemy: Total 4-6>', '', 28153),
(145833, 'deDE', '<Release spell, throwing energy: Total 3-5>', '', 28153),
