(145823, 'deDE', '<Long attack with wind up. Jump attacks: Total 5-7>', '', 28153),
(145822, 'deDE', '<Breathe as if you are running: Total 3>', '', 28153),
(145821, 'deDE', '<Vocalized cheer: Total 3>', '', 28153),
(145820, 'deDE', '<Player takes a wound: Total 10>', '', 28153),
(145819, 'deDE', '<Player takes significant wound: Total 5>', '', 28153),
(145818, 'deDE', 'Das Ziel kann ich nich\' angreifen.', '', 28153),
(145817, 'deDE', 'Das kann ich nich\' angreifen.', '', 28153),
(145816, 'deDE', 'Meine Taschen sin\' voll.', '', 28153),
(145815, 'deDE', 'Ich kann nich\' noch mehr tragen.', '', 28153),
(145814, 'deDE', 'Das is\' verschlossen.', '', 28153),
(145813, 'deDE', 'Mehr kann ich davon nich\' tragen.', '', 28153),
(145812, 'deDE', 'Den Gegenstand kann ich noch nich\' benutzen.', '', 28153),
(145811, 'deDE', 'Das\'s noch nich\' bereit.', '', 28153),
(145810, 'deDE', 'Wer sich weigert zu dienen, wird ausgelöscht!', 'Wer sich weigert zu dienen, wird ausgelöscht!', 28153),
(145809, 'deDE', 'Der Gegenstand lädt noch\'n bisschen auf.', '', 28153),
(145808, 'deDE', 'Nich\' genug Jähzorn.', '', 28153),
(145807, 'deDE', 'Zu wenig Jähzorn.', '', 28153),
(145806, 'deDE', 'Nich\' genug Schmerz.', '', 28153),
(145805, 'deDE', 'Zu wenig Schmerz.', '', 28153),
(145804, 'deDE', 'Das is\' keine Tasche.', '', 28153),
(145803, 'deDE', 'Mein Geld reicht nich\' dafür.', '', 28153),
(145802, 'deDE', 'Das kann ich mir nich\' leisten.', '', 28153),
(145801, 'deDE', 'Das is\' zu teuer.', '', 28153),
(145800, 'deDE', 'Der Held kann sich der Gruppe nich\' anschließen.', '', 28153),
(145799, 'deDE', 'Ich hab keine Munition mehr.', '', 28153),
(145798, 'deDE', 'Nich\' genug Energie.', '', 28153),
(145797, 'deDE', 'Ich brauch mehr Energie.', '', 28153),
(145796, 'deDE', 'Ich brauch erstma\' Mana.', '', 28153),
(145795, 'deDE', 'Mein Mana is\' alle.', '', 28153),
(145794, 'deDE', 'Nich\' genug Mana.', '', 28153),
(145793, 'deDE', 'Nich\' genug Wut.', '', 28153),
(145792, 'deDE', 'Ich brauch mehr Wut.', '', 28153),
(145791, 'deDE', 'Zu weit weg.', '', 28153),
(145790, 'deDE', 'Ich bin zu weit weg.', '', 28153),
(145789, 'deDE', 'Ich muss erstma\' näher ran.', '', 28153),
(145788, 'deDE', 'Wir könn\' kein\' mehr einladen.', '', 28153),
(145787, 'deDE', 'Ich kann jetz\' nich\' mehr trinken.', '', 28153),
(145786, 'deDE', 'Die Fähigkeit hab ich noch nich\' gelernt.', '', 28153),
(145785, 'deDE', 'Das kann ich noch nich\' tragen.', '', 28153),
(145784, 'deDE', 'Der Zauber is\' noch nich\' bereit.', '', 28153),
(145783, 'deDE', 'Das kann ich noch nich\' wirken.', '', 28153),
(145782, 'deDE', 'Das lädt noch auf.', '', 28153),
(145781, 'deDE', 'Ich brauch beide Hände für meine Waffe.', '', 28153),
(145780, 'deDE', 'Die Fähigkeit ist noch nich\' bereit.', '', 28153),
(145779, 'deDE', 'Das geht noch nich\'.', '', 28153),
(145778, 'deDE', 'Is\' noch nich\' bereit.', '', 28153),
(145777, 'deDE', 'Das kann ich da nich\' ableg\'n.', '', 28153),
(145776, 'deDE', 'Die Tasche is\' voll.', '', 28153),
(145775, 'deDE', 'Das kann ich hier nich\' mach\'n.', '', 28153),
(145774, 'deDE', 'Das kann ich nich\' wegwerfen.', '', 28153),
(145773, 'deDE', 'Das is\' an mich gebunden.', '', 28153),
(145772, 'deDE', 'Das kann ich nich\' anleg\'n.', '', 28153),
(145771, 'deDE', 'Meine Stufe is\' nich\' hoch genug, um das zu benutzen.', '', 28153),
(145770, 'deDE', 'Das kann ich noch nich\' benutzen.', '', 28153),
(145769, 'deDE', 'Meine Fertigkeitsstufe is\' nich\' hoch genug, um das anzuleg\'n.', '', 28153),
(145768, 'deDE', 'Sowas kann ich nich\' anleg\'n.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145767, 'deDE', 'So\'n Zauber kann ich nich\' lern\'.', '', 28153),
(145766, 'deDE', 'Das kann ich nich\' plündern.', '', 28153),
(145765, 'deDE', 'Das is\' nich\' meins.', '', 28153),
(145764, 'deDE', 'Ich muss näher ran.', '', 28153),
(145763, 'deDE', 'Das is\' zu weit weg.', '', 28153),
(145762, 'deDE', 'Da komm ich nich\' ran.', '', 28153),
(145761, 'deDE', 'Das kann ich nich\' handeln.', '', 28153),
(145760, 'deDE', 'Das kann ich nich\' benutzen.', '', 28153),
(145759, 'deDE', 'Das is\' nich\' angelegt.', '', 28153),
(145758, 'deDE', 'Das muss ich erstma\' anleg\'n.', '', 28153),
(145757, 'deDE', 'Das kann ich jetz\' nich\' plündern.', '', 28153),
(145756, 'deDE', 'Ich hab kein Ziel.', '', 28153),
(145755, 'deDE', 'Ich muss erstma\' was anvisieren.', '', 28153),
(145754, 'deDE', 'Ich brauch ein Ziel.', '', 28153),
(145753, 'deDE', 'Das kann ich nich\' tun.', '', 28153),
(145752, 'deDE', 'Dazu fehlt mir die Erlaubnis.', '', 28153),
(145751, 'deDE', 'Greift mein\' Feind an!', '', 28153),
(145750, 'deDE', 'Macht mein Ziel kalt!', '', 28153),
(145749, 'deDE', 'Angriffe konzentrieren!', '', 28153),
(145748, 'deDE', 'Attacke!', '', 28153),
(145747, 'deDE', 'Alle zusamm\'!', '', 28153),
(145746, 'deDE', 'Für Zandalar!', '', 28153),
(145745, 'deDE', 'Alle Mann vorrücken!', '', 28153),
(145744, 'deDE', 'Schlagt die zurück!', '', 28153),
(145743, 'deDE', 'Rückzug!', '', 28153),
(145742, 'deDE', 'Wir müssen uns zurückzieh\'n!', '', 28153),
(145741, 'deDE', 'Weg! Weg!', '', 28153),
(145740, 'deDE', 'Hier lang.', '', 28153),
(145739, 'deDE', 'Ich geh vor.', '', 28153),
(145738, 'deDE', 'Folgt mir ma\'!', '', 28153),
(145737, 'deDE', 'Für die Horde!', '', 28153),
(145736, 'deDE', 'Meine Wund\'n tun echt weh.', '', 28153),
(145735, 'deDE', 'Ich brauch Heilung!', '', 28153),
(145734, 'deDE', 'Ich brauch ma\' Hilfe!', '', 28153),
(145733, 'deDE', 'Helf ma\' einer!', '', 28153),
(145732, 'deDE', 'Gefahr im Anmarsch!', '', 28153),
(145731, 'deDE', 'Feuert aus all\'n Rohr\'n!', '', 28153),
(145730, 'deDE', 'Feuer! Feuer!', '', 28153),
(145729, 'deDE', 'Bleibt ma\' hier!', '', 28153),
(145728, 'deDE', 'Lauft nich\' weg!', '', 28153),
(145727, 'deDE', 'Da meine Brüder nun befreit sind, werde ich die Zandalari im Dorf aufsuchen. Für uns bleibt hier nichts mehr zu tun.', '', 28153),
(145726, 'deDE', 'Ich bin kein Kämpfer. Ich werde Euch tiefer in der Schlucht wiedertreffen, wenn Ihr meine Brüder befreit habt.', '', 28153),
(145725, 'deDE', 'Kein Trinkgeld?', 'Kein Trinkgeld?', 28153),
(145724, 'deDE', 'Ich fühle den Ruf von Raiks Macht wie ein Leuchtfeuer. Schnell!', '', 28153),
(145723, 'deDE', 'Ihr hattet wohl genug. Ihr geht besser!', '', 28153),
(145722, 'deDE', 'Platzieren', 'Platzieren', 28153),
(145721, 'deDE', '', 'Die evolutionäre Biologie der Silithidenspezies ist außerordentlich faszinierend!', 28153),
(145720, 'deDE', 'Ihr scheint Katzen wirklich sehr zu mögen.', 'Ihr scheint Katzen wirklich sehr zu mögen.', 28153),
(145719, 'deDE', 'Frau Flauschibausch?', 'Frau Flauschibausch?', 28153),
(145718, 'deDE', 'Es scheint ihnen schon gut zu gehen.', 'Es scheint ihnen schon gut zu gehen.', 28153),
(145717, 'deDE', '<Ihr versucht, etwas zu sagen, werdet aber unterbrochen.>', '<Ihr versucht, etwas zu sagen, werdet aber unterbrochen.>', 28153),
(145716, 'deDE', '', '<Sie fängt an zu weinen.>\n\nTut mir leid, dass ich so emotional werde, aber... ich liebe Katzen einfach. Alle Katzen. Bombay-Katzen, Schildpattkatzen, Siamkatzen, Tabby-Katzen, teufelsberührte Katzen, nicht teufelsberührte Katzen, Dämmersäbler, Teufelssäbler, Flammensäbler, Frostsäbler, Manasäbler, Nebelsäbler, Mondsäbler, Nachtsäbler, Runensäbler, Sturmsäbler, Löwen, Luchse, Panther, Panthara mit ihrer tollen Farbgebung, besonders in Indigo, auch wenn die Leute diese Tiere für launisch halten, aber die verstehen sie eben nicht so wie ich, Tiger, Spektraltiger... Nach Suramar habe ich mir als Erstes alle möglichen Katzen angeschaut und wollte sie unbedingt alle umarmen. Aber das geht ja gar nicht!\n\n<Sie weint wieder.>', 28153),
(145715, 'deDE', '', '<Sie zeigt auf ein drittes Manakätzchen.>\n\nDa sitzt sie, immer so geduldig... Sie hat wirklich eine ganz eigene Vorstellung von Essen. Man sollte ja denken, sie wäre glücklich mit dem edlen Fisch, den wir hier servieren, aber nein, Frau Flauschibausch hat ihre Vorlieben. Ihre Lieblingsspeise ist nämlich, und ich kann das eigentlich selbst nicht glauben... Manatorte! \n\nAber das kommt wahrscheinlich daher, dass meine Eltern ihr, als ich ein kleines Mädchen war, welche als Leck... also L-E-C-K-E-R-L-I gegeben haben. Einzelkätzchen und Einzelkind... Wir beide haben wohl gut zusammengepasst.', 28153),
(145714, 'deDE', '', 'Diese Kätzchen verdienen nur das Beste, denn sie sind die Besten, und ich wünschte, ich könnte sie mit aller Welt teilen, aber das geht nicht... Und, glaubt mir, ich habe es wirklich versucht. Ich finde es so schön, dass Ihr hier seid und sie sogar streicheln könnt. Es war gut, bereits zwei andere Kätzchen hierzuhaben, während ich mich bemüht habe, Mauntz\' Vertrauen zu gewinnen. Alles andere wäre ja eine reine Qual gewesen! Ein Zuhause ohne Katzen ist ja schließlich gar kein Zuhause, sondern lediglich ein Platz, an dem man lebt. Und kann man eigentlich ein Leben ohne Katzen ein Leben nennen? Oh, da ist ja eines der beiden erwähnten Kätzchen... Frau Flauschibausch!', 28153),
(145713, 'deDE', '', 'Am Anfang war er ganz schön misstrauisch und ließ sich nicht mal von mir streicheln. Aber im Laufe einiger Jahre konnte ich mich ihm mit Ausdauer, Entschlossenheit und vor allem L-E-C-K-E-R-L-I-S annähern. Die sind dabei ganz, ganz wichtig. Und mittlerweile sind wir wie BESTE FREUNDE und ich verstehe mich mit ihm genauso gut wie mit meinen anderen Kätzchen!\n\nIch muss das eine Wort buchstabieren, sonst kommt er und bettelt, und wie könnte ich diesen bezaubernden Augen je widerstehen? Seht sie Euch an, seht sie Euch nur an! Sie sind so voller Liebe und Wärme, dass ich mich selbst auch ganz glücklich und geborgen fühle! Ich versuche, sie in Maßen zu geben, um ihn nicht zu verwöhnen. Aber ich mache mir eigentlich etwas vor, denn am Ende bekommt er immer, so viel er will!', 28153),
(145712, 'deDE', '', 'Ihr könnte den Arkwein gleich da drüben... Oh, Ihr seid wohl... neu hier! Ich möchte Euch meine Schätzchen vorstellen! \n\n<Sie zeigt auf eines der Manakätzchen.>\n\nDas ist Schatten. Er verliert ständig seine Spielzeuge, wenn er sie auf seine Abenteuer mitschleppt. Wo willst du denn hin, Kleiner? In die Menagerie, zu den exotischen Kreaturen dieser Welt? Durch die duftenden Zwielichtrebgärten? Vielleicht kannst du mir von deiner nächsten Reise ja ein schmuckes Andenken mitbringen! Obwohl... Er hat mir ja schon einmal etwas mitgebracht... Meinen lieben Mauntz! Einmal habe ich ihn nämlich hereingelassen, und er hatte zu meiner freudigen Überraschung einen kleinen Freund dabei! Und alle Freunde von Schatten sind natürlich auch meine Freunde.', 28153),
(145706, 'deDE', '', 'Was war das? Ihr drei! Seht nach den Maschinen!', 28153),
(145703, 'deDE', 'Ihr habt Euer eigenes Todesurteil unterschrieben. Das ist ein Versprechen...', '', 28153),
(145702, 'deDE', 'Ihr habt meinen Grog verschüttet! Dafür werdet Ihr zahlen!', '', 28153),
(145701, 'deDE', 'Ich werde das Deck mit Euch schrubben!', '', 28153),
(145700, 'deDE', 'Mit ein paar Grunzern kommt Ihr vielleicht klar! Aber wollen wir doch einmal sehen, wie Ihr Euch gegen einen Seebärenveteranen schlagt!', '', 28153),
(145699, 'deDE', 'Los Jungs, zeigen wir diesem Wurm, was passiert, wenn man sich mit der Horde anlegt!', '', 28153),
(145698, 'deDE', 'Wenn Ihr glaubt, Ihr könnt die Mannschaft eines Seebären aufhalten, habt Ihr Euch geschnitten!', '', 28153),
(145697, 'deDE', 'Ihr wagt es also, uns Eure hässliche Allianzfratze zu zeigen?', '', 28153),
(145686, 'deDE', '', 'Heute schlaft Ihr bei den Sichelfischen, $n.', 28153),
(145685, 'deDE', '', 'Ich werde für Euch beten!', 28153),
(145684, 'deDE', '', 'Verschwendet kein Geld für meinen Sarg.', 28153),
(145683, 'deDE', '', 'Ihr wagt es, mir die Zähne zu zeigen, $n?!', 28153),
(145682, 'deDE', '', 'Ich fleh Euch an.', 28153),
(145681, 'deDE', '', 'Mögt Ihr Explosionen, $n?', 28153),
(145680, 'deDE', '', 'Habt doch\'n Herz!', 28153),
(145679, 'deDE', '', 'Ich hab eine Mordslaune.', 28153),
(145678, 'deDE', '', 'Geister, habt Gnade.', 28153),
(145677, 'deDE', '', 'Echt verdient.', 28153),
(145676, 'deDE', '', 'Die Loa ham Euch gesegnet.', 28153),
(145675, 'deDE', '', 'Bin beeindruckt.', 28153),
(145674, 'deDE', '', 'Euer Mitleid widert mich an!', 28153),
(145673, 'deDE', '', 'Ich rieche angesengte Augenbrauen.', 28153),
(145672, 'deDE', '', 'Lasst Euch nich\' mit den Geistern ein.', 28153),
(145671, 'deDE', '', 'Zwingt mich nicht, Euch zu schocken.', 28153),
(145670, 'deDE', '', 'Möge Bwonsamdi Euch fern bleiben.', 28153),
(145669, 'deDE', 'Wird auch Zeit.', 'Wird auch Zeit.', 28153),
(145668, 'deDE', '', 'Mög\'n die Loa über Euch wach\'n.', 28153),
(145667, 'deDE', '', 'Lebt wohl.', 28153),
(145666, 'deDE', '', 'Die Geister heiß\'n Euch willkomm\'.', 28153),
(145665, 'deDE', '', 'Hallo.', 28153),
(145664, 'deDE', '', 'Die Loa sin\' überall mit uns.', 28153),
(145663, 'deDE', '', 'Ich habe hier Euer Mietgeld!', 28153),
(145662, 'deDE', '', 'Seid gegrüßt.', 28153),
(145661, 'deDE', '', 'Nein.', 28153),
(145660, 'deDE', '', 'Nix da.', 28153),
(145659, 'deDE', '', 'Sicher nich\'.', 28153),
(145658, 'deDE', '', 'Verstehe.', 28153),
(145657, 'deDE', '', 'Einverstanden.', 28153),
(145656, 'deDE', '', 'Jawoll.', 28153),
(145655, 'deDE', '', 'Ich brauch Mana.', 28153),
(145654, 'deDE', '', 'Wartet ma\', muss erstma\' Mana sammeln.', 28153),
(145653, 'deDE', 'Ihr spürt, dass ein fremder Blick auf Euch liegt... Er wirkt etwas... arrogant?', 'Ihr hört das Geräusch dröhnender Maschinen in der Ferne.', 28153),
(145652, 'deDE', '', 'Wärmst\'n Dank.', 28153),
(145651, 'deDE', '', 'Habt Dank.', 28153),
(145650, 'deDE', '', 'Ich schuld Euch was.', 28153),
(145649, 'deDE', 'Korrekt! Ihr habt alle meine Rätsel gelöst!', '', 28153),
(145648, 'deDE', '', 'Den Loa sei Dank.', 28153),
(145647, 'deDE', '', 'Haben wir Euch! Der Goblintrupp ist in der Überzahl und hat Euch umzingelt! Sprecht Eure Gebete!', 28153),
(145646, 'deDE', '', 'Ihr stinkt wie\'n Bluttroll.', 28153),
(145645, 'deDE', '', 'Eure Knochen werden mein\' Altar verzieren.', 28153),
(145644, 'deDE', '', 'Gern gescheh\'n.', 28153),
(145643, 'deDE', '', 'Nich\' der Rede wert.', 28153),
(145642, 'deDE', '', 'War mir\'n Vergnügen.', 28153),
(145641, 'deDE', 'Die Höchstgeschwindigkeit eines unbeladenen Axtschnabels.', 'Die Höchstgeschwindigkeit eines unbeladenen Axtschnabels.', 28153),
(145640, 'deDE', 'Ein Plünderang.', 'Ein Plünderang.', 28153),
(145639, 'deDE', 'Ich kann nicht... sterben. Ich bin... Gaston...', '', 28153),
(145638, 'deDE', 'Ich bin nicht so weit gekommen, um jetzt aufzugeben.', 'Ich bin nicht so weit gekommen, um jetzt aufzugeben.', 28153),
(145637, 'deDE', 'Falsch!\n\nWollt Ihr nochmal rat\'n?', '', 28153),
(145636, 'deDE', 'Ein gebrochenes Herz.', 'Ein gebrochenes Herz.', 28153),
(145635, 'deDE', 'Zeit.', 'Zeit.', 28153),
(145634, 'deDE', 'Beantwortet mir folg\'nde Frage:\n\nWas kann immer gemess\'n, aber nie geseh\'n werd\'n?', '', 28153),
(145633, 'deDE', 'Besonders gut kann ich ausweiiiiiiiden!', '', 28153),
(145632, 'deDE', 'Hat lebensechte Lockvögel dazu, der Gaston!', '', 28153),
(145631, 'deDE', 'Schlägt Euch im Nu wie Gaston!', '', 28153),
(145630, 'deDE', 'Bereit!', 'Bereit!', 28153),
(145629, 'deDE', 'Niemand haut zu wie Gaston!', '', 28153),
(145628, 'deDE', 'Die Vergangenheit.', 'Die Vergangenheit.', 28153),
(145626, 'deDE', '', 'Greift mein\' Feind an!', 28153),
(145625, 'deDE', '', 'Macht mein Ziel kalt!', 28153),
(145624, 'deDE', '', 'Angriffe konzentrieren!', 28153),
(145623, 'deDE', '', 'Attacke!', 28153),
(145622, 'deDE', '', 'Alle zusamm\'!', 28153),
(145621, 'deDE', '', 'Für Zandalar!', 28153),
(145620, 'deDE', '', 'Alle Mann vorrücken!', 28153),
(145619, 'deDE', '', 'Schlagt die zurück!', 28153),
(145618, 'deDE', '', 'Rückzug!', 28153),
(145617, 'deDE', 'Die Sonne.', 'Die Sonne.', 28153),
(145616, 'deDE', '', 'Wir müssen uns zurückzieh\'n!', 28153),
(145615, 'deDE', '', 'Weg! Weg!', 28153),
(145614, 'deDE', '', 'Hier lang.', 28153),
(145613, 'deDE', '', 'Ich geh vor.', 28153),
(145612, 'deDE', '', 'Folgt mir ma\'!', 28153),
(145611, 'deDE', '', 'Für die Horde!', 28153),
(145610, 'deDE', '', 'Meine Wund\'n tun echt weh.', 28153),
(145609, 'deDE', 'Das is\' richtig! Nur noch eine Frage.\n\nBereit?', '', 28153),
(145608, 'deDE', 'Mein Schatten.', 'Mein Schatten.', 28153),
(145607, 'deDE', '', 'Ich brauch Heilung!', 28153),
(145606, 'deDE', '', 'Ich brauch ma\' Hilfe!', 28153),
(145605, 'deDE', 'Lasst es mich noch einmal versuchen.', 'Lasst es mich noch einmal versuchen.', 28153),
(145604, 'deDE', 'Falsch!\n\nHabt Ihr \'ne andere Antwort?', '', 28153),
(145603, 'deDE', '', 'Helf ma\' einer!', 28153),
(145602, 'deDE', 'Ein Schurke.', 'Ein Schurke.', 28153),
(145601, 'deDE', 'Beantwortet mir folg\'nde Frage:\n\nManchmal geh ich vor Euch. Manchmal geh ich hinter Euch. Nur im Dunklen verlass ich Euch. Wer bin ich?', '', 28153),
(145600, 'deDE', '', 'Gefahr im Anmarsch!', 28153),
(145599, 'deDE', 'Eine Schatztruhe.', 'Eine Schatztruhe.', 28153),
(145598, 'deDE', '', 'Feuert aus all\'n Rohr\'n!', 28153),
(145597, 'deDE', '', 'Feuer! Feuer!', 28153),
(145595, 'deDE', '', 'Bleibt ma\' hier!', 28153),
(145594, 'deDE', '', 'Lauft nich\' weg!', 28153),
(145593, 'deDE', 'Bitte sagt mir, dass wir gleich durch sind.', 'Bitte sagt mir, dass wir gleich durch sind.', 28153),
(145592, 'deDE', 'Bereit!', 'Bereit!', 28153),
(145591, 'deDE', 'Korrekt!\n\nSeid Ihr noch dabei?', '', 28153),
