(145389, 'deDE', '<Player takes a wound: Total 10>', '', 28153),
(145388, 'deDE', '<Player takes significant wound: Total 5>', '', 28153),
(145387, 'deDE', 'Meine Waffe erfordert beide Hände.', '', 28153),
(145386, 'deDE', 'Diese Fähigkeit ist noch nicht bereit.', '', 28153),
(145385, 'deDE', 'Das kann ich noch nicht tun.', '', 28153),
(145384, 'deDE', 'Noch nicht bereit.', '', 28153),
(145383, 'deDE', 'Das kann ich dort nicht ablegen.', '', 28153),
(145382, 'deDE', 'Diese Tasche ist voll.', '', 28153),
(145381, 'deDE', 'Das kann ich hier nicht tun.', '', 28153),
(145380, 'deDE', 'Das kann ich nicht wegwerfen.', '', 28153),
(145379, 'deDE', 'Das ist an mich gebunden.', '', 28153),
(145378, 'deDE', 'Das kann ich nicht anlegen.', '', 28153),
(145377, 'deDE', 'Dafür ist meine Stufe nicht hoch genug.', '', 28153),
(145376, 'deDE', 'Das kann ich noch nicht benutzen.', '', 28153),
(145375, 'deDE', 'Dafür ist meine Fertigkeitsstufe nicht hoch genug.', '', 28153),
(145374, 'deDE', 'So etwas kann ich nicht anlegen.', '', 28153),
(145373, 'deDE', 'Diesen Zauber kann ich nicht erlernen.', '', 28153),
(145372, 'deDE', 'Das kann ich nicht plündern.', '', 28153),
(145371, 'deDE', 'Das steht mir nicht zu.', '', 28153),
(145370, 'deDE', 'Ich muss näher heran.', '', 28153),
(145369, 'deDE', 'Das ist zu weit weg.', '', 28153),
(145368, 'deDE', 'Da komme ich nicht ran.', '', 28153),
(145367, 'deDE', 'Das kann ich nicht handeln.', '', 28153),
(145366, 'deDE', 'Das kann ich nicht benutzen.', '', 28153),
(145365, 'deDE', 'Das ist nicht angelegt.', '', 28153),
(145364, 'deDE', 'Das muss ich erst anlegen.', '', 28153),
(145363, 'deDE', 'Na schön, ich versuche es noch einmal.', 'Na schön, ich versuche es noch einmal.', 28153),
(145362, 'deDE', 'Ha! Falsch.\n\nNoch \'n Versuch?', '', 28153),
(145361, 'deDE', 'Das kann ich gerade nicht plündern.', '', 28153),
(145360, 'deDE', 'Ich habe kein Ziel.', '', 28153),
(145359, 'deDE', 'Ich muss zuerst etwas anvisieren.', '', 28153),
(145358, 'deDE', 'Ich brauche ein Ziel.', '', 28153),
(145357, 'deDE', 'Das kann ich nicht tun.', '', 28153),
(145356, 'deDE', 'Dafür fehlt mir die Erlaubnis.', '', 28153),
(145355, 'deDE', 'Dieses Ziel kann ich nicht angreifen.', '', 28153),
(145354, 'deDE', 'Köstlicher Schokoladenkuchen.', 'Köstlicher Schokoladenkuchen.', 28153),
(145353, 'deDE', 'Das kann ich nicht angreifen.', '', 28153),
(145352, 'deDE', 'Mein Inventar ist voll.', '', 28153),
(145351, 'deDE', 'Mehr kann ich nicht tragen.', '', 28153),
(145350, 'deDE', 'Das ist verschlossen.', '', 28153),
(145349, 'deDE', 'Mehr kann ich davon nicht tragen.', '', 28153),
(145348, 'deDE', 'Diesen Gegenstand kann ich noch nicht benutzen.', '', 28153),
(145347, 'deDE', 'Das ist noch nicht bereit.', '', 28153),
(145346, 'deDE', 'Dieser Gegenstand lädt noch auf.', '', 28153),
(145345, 'deDE', 'Nicht genug Jähzorn.', '', 28153),
(145344, 'deDE', 'Mein Jähzorn reicht nicht aus.', '', 28153),
(145343, 'deDE', 'Nicht genug Schmerz.', '', 28153),
(145342, 'deDE', 'Mein Schmerz reicht nicht aus.', '', 28153),
(145341, 'deDE', 'Das ist keine Tasche.', '', 28153),
(145340, 'deDE', 'Meine Mittel reichen nicht aus.', '', 28153),
(145339, 'deDE', 'Das kann ich mir nicht leisten.', '', 28153),
(145338, 'deDE', 'Das ist zu teuer.', '', 28153),
(145337, 'deDE', 'Dieser Held kann sich der Gruppe nicht anschließen.', '', 28153),
(145336, 'deDE', 'Ich habe keine Munition mehr.', '', 28153),
(145335, 'deDE', 'Nicht genug Energie.', '', 28153),
(145334, 'deDE', 'Ich brauche mehr Energie.', '', 28153),
(145333, 'deDE', 'Ich benötige erst Mana.', '', 28153),
(145332, 'deDE', 'Mein Mana ist knapp.', '', 28153),
(145331, 'deDE', 'Nicht genug Mana.', '', 28153),
(145330, 'deDE', 'Nicht genug Wut.', '', 28153),
(145329, 'deDE', 'Ich brauche mehr Wut.', '', 28153),
(145328, 'deDE', 'Zu weit entfernt.', '', 28153),
(145327, 'deDE', 'Ich bin außer Reichweite.', '', 28153),
(145326, 'deDE', 'Ich muss näher heran.', '', 28153),
(145325, 'deDE', 'Wir können niemanden mehr einladen.', '', 28153),
(145324, 'deDE', 'Ich kann gerade nicht mehr trinken.', '', 28153),
(145323, 'deDE', 'Diese Fähigkeit habe ich noch nicht erlernt.', '', 28153),
(145322, 'deDE', 'Das kann ich noch nicht.', '', 28153),
(145321, 'deDE', 'Dieser Zauber ist noch nicht bereit.', '', 28153),
(145320, 'deDE', 'Das kann ich noch nicht wirken.', '', 28153),
(145319, 'deDE', 'Das lädt noch auf.', '', 28153),
(145318, 'deDE', 'Beantwortet mir folg\'nde Frage:\n\nWenn ich es hab, teil ich es nich\'. Wenn ich es teil, hab ich es nich\'. Was is\' es?', '', 28153),
(145317, 'deDE', 'Bringt diesen Gegner zur Strecke!', '', 28153),
(145316, 'deDE', 'Schaltet dieses Ziel aus!', '', 28153),
(145315, 'deDE', 'Konzentriert Euch auf den Feind!', '', 28153),
(145314, 'deDE', 'Zu den Waffen!', '', 28153),
(145313, 'deDE', 'Für die Königin!', '', 28153),
(145312, 'deDE', 'Bei der Macht des Berges!', '', 28153),
(145311, 'deDE', 'Macht sie nieder!', '', 28153),
(145310, 'deDE', 'Schlagt sie zurück!', '', 28153),
(145309, 'deDE', 'Zieht Euch zurück!', '', 28153),
(145308, 'deDE', 'Ihr spürt, dass ein fremder Blick auf Euch liegt... Er wirkt etwas... arrogant?', 'Ihr spürt, dass ein fremder Blick auf Euch liegt... Er wirkt etwas... arrogant?', 28153),
(145307, 'deDE', 'Rückzug!', '', 28153),
(145306, 'deDE', 'Macht, dass Ihr wegkommt!', '', 28153),
(145305, 'deDE', 'Hier lang.', '', 28153),
(145304, 'deDE', 'Ich gehe voraus.', '', 28153),
(145303, 'deDE', 'Folgt mir.', '', 28153),
(145302, 'deDE', 'Wirklich, noch eins?', 'Wirklich, noch eins?', 28153),
(145301, 'deDE', 'Bereit!', 'Bereit!', 28153),
(145300, 'deDE', 'Die sich am meisten zieren, sind immer die schönste Beute. Ihr gehört jetzt mir!', '', 28153),
(145299, 'deDE', 'Ihr habt\'s!\n\nBereit für noch \'n Rätsel?', '', 28153),
(145298, 'deDE', 'Für die Allianz!', '', 28153),
(145297, 'deDE', 'Ich bin schwer verwundet!', '', 28153),
(145296, 'deDE', 'Ich brauche dringend Heilung!', '', 28153),
(145295, 'deDE', 'Ich brauche Hilfe!', '', 28153),
(145294, 'deDE', 'Kommt mir zu Hilfe!', '', 28153),
(145293, 'deDE', 'Es droht Gefahr!', '', 28153),
(145292, 'deDE', 'Auf sie mit Gebrüll!', '', 28153),
(145291, 'deDE', 'Heizt ihnen ein!', '', 28153),
(145290, 'deDE', 'Wartet hier.', '', 28153),
(145289, 'deDE', 'Rührt Euch nicht vom Fleck!', '', 28153),
(145288, 'deDE', 'Eine fleischfressende Topfpflanze.', 'Eine fleischfressende Topfpflanze.', 28153),
(145287, 'deDE', '', 'Aber zuerst brauche ich mehr Mana.', 28153),
(145286, 'deDE', '', 'Ich muss mein Mana auffrischen.', 28153),
(145285, 'deDE', 'Ein Fisch.', 'Ein Fisch.', 28153),
(145283, 'deDE', 'Noch ein Versuch.', 'Noch ein Versuch.', 28153),
(145282, 'deDE', 'Nö!\n\nNoch \'n Versuch?', '', 28153),
(145281, 'deDE', 'Ein Pandaren.', 'Ein Pandaren.', 28153),
(145280, 'deDE', 'Ein Feuer.', 'Ein Feuer.', 28153),
(145279, 'deDE', 'Beantwortet mir folg\'nde Frage:\n\nWenn ich trinke, sterbe ich. Wenn ich esse, lebe ich. Was bin ich?', '', 28153),
(145278, 'deDE', 'Bereit!', 'Bereit!', 28153),
(145277, 'deDE', 'Richtig!\n\nBereit für noch \'n Rätsel?', '', 28153),
(145276, 'deDE', 'Uuna wird von Finsternis verschlungen.', 'Uuna wird von Finsternis verschlungen.', 28153),
(145275, 'deDE', '', 'Aaaaah! Nein! Hilfe!', 28153),
(145273, 'deDE', '', 'Eine donnernde Stimme lässt Euch erschaudern.', 28153),
(145272, 'deDE', '', 'Ich bitte Euch inständig!', 28153),
(145271, 'deDE', '', 'Kommt schon, habt Erbarmen!', 28153),
(145270, 'deDE', '', 'Ich bitte um Gnade!', 28153),
(145269, 'deDE', '', 'Gar nicht mal schlecht.', 28153),
(145268, 'deDE', '', 'Beeindruckend.', 28153),
(145267, 'deDE', '', 'Sehr schön.', 28153),
(145266, 'deDE', '', 'Aber jetzt noch nicht.', 28153),
(145265, 'deDE', '', 'Ich weiß, irgendwann muss ich wieder zu meiner Mama und meinem Papa zurück.', 28153),
(145264, 'deDE', '', 'Möge die Schmiede Euch den Weg erhellen.', 28153),
(145263, 'deDE', '', 'Ihr habt mir so viele tolle Sachen gezeigt. Ihr seid wirklich $gder beste Freund, den:die beste Freundin, die; man sich vorstellen kann!', 28153),
(145262, 'deDE', '', 'Fort mit Euch.', 28153),
(145261, 'deDE', '', 'Ihr werdet ZAHL\'N für das, was Ihr gemacht habt!', 28153),
(145260, 'deDE', '', 'Hinfort mit Euch!', 28153),
(145259, 'deDE', '', 'Lebt wohl.', 28153),
(145258, 'deDE', '', 'Vielen, vielen Dank, dass Ihr mir das gezeigt habt!', 28153),
(145257, 'deDE', '', 'Es sind nicht alle auf Argus gestorben?', 28153),
(145256, 'deDE', '', 'Mein Volk ist hier! Sie leben noch!', 28153),
(145255, 'deDE', '', 'Es ist so... wunderschön...', 28153),
(145254, 'deDE', '', 'Das ist irgendwie seltsam.', 28153),
(145253, 'deDE', '', 'Aber es bewegt sich wie Wasser... ist es ein leuchtender See?', 28153),
(145252, 'deDE', '', 'Raus mit der Sprache.', 28153),
(145251, 'deDE', 'Ich versuche es noch einmal.', 'Ich versuche es noch einmal.', 28153),
(145250, 'deDE', 'Falsch!\n\nWollt Ihr\'s nochmal versuch\'n?', '', 28153),
(145249, 'deDE', 'Ein Loa.', 'Ein Loa.', 28153),
(145248, 'deDE', 'Eine Kerze.', 'Eine Kerze.', 28153),
(145247, 'deDE', '', 'Seht Euch das an. Wie es leuchtet!', 28153),
(145246, 'deDE', '', 'Wo sind wir? Warum ist alles voller Rauch?', 28153),
(145245, 'deDE', '', 'Also seid vorsichtig, ja?', 28153),
(145244, 'deDE', 'Ein Baum.', 'Ein Baum.', 28153),
(145243, 'deDE', '', 'Oh, passt auf, dass Ihr nicht runterfallt! Mir passiert nichts, wenn ich falle, aber Ihr, bei Euch macht es PLATSCH!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'deDE', '', 'Grüße.', 28153),
(145241, 'deDE', '', 'Ich wusste gar nicht, dass es so hohe Berge gibt!', 28153),
(145240, 'deDE', '', 'Von hier aus kann ich alles sehen!', 28153),
(145239, 'deDE', '', 'Gut, Euch zu sehen.', 28153),
(145238, 'deDE', '', 'Ich grüße Euch.', 28153),
(145237, 'deDE', '', 'Krah krah krah krah krah!', 28153),
(145236, 'deDE', '', 'Nein.', 28153),
(145235, 'deDE', '', 'Nein.', 28153),
(145234, 'deDE', '', 'Niemals!', 28153),
(145233, 'deDE', '', 'Ganz richtig.', 28153),
(145232, 'deDE', '', 'Mmm-hmm.', 28153),
(145231, 'deDE', '', 'Jau.', 28153),
(145230, 'deDE', '', 'Ich bedanke mich.', 28153),
(145229, 'deDE', '', 'Ich danke Euch.', 28153),
(145228, 'deDE', 'Ein Gnom.', 'Ein Gnom.', 28153),
(145227, 'deDE', '', 'Dafür schulde ich Euch was.', 28153),
(145226, 'deDE', '', 'Beim Schwarzen Amboss!', 28153),
(145225, 'deDE', '', 'Mindestens... ZEHN!', 28153),
(145224, 'deDE', '', 'Ist das alles, was Ihr könnt?', 28153),
(145222, 'deDE', '', 'Ich mach Euch Feuer unterm Hintern!', 28153),
(145221, 'deDE', '', 'Wie viele Vögel wohl in diesem Baum leben? Bestimmt ganz viele!', 28153),
(145220, 'deDE', 'Beantwortet mir folg\'nde Frage:\n\nIch bin groß, wenn ich jung bin, und klein, wenn ich alt bin. Was bin ich?', '', 28153),
(145219, 'deDE', '', 'War mir ein Vergnügen.', 28153),
(145218, 'deDE', '', 'Schaut nur! Wir stehen unter einem riesigen Baum!', 28153),
(145217, 'deDE', '', 'Immer wieder gern.', 28153),
(145216, 'deDE', '', 'Stets zu Diensten.', 28153),
(145215, 'deDE', 'Lasst uns spielen.', 'Lasst uns spielen.', 28153),
(145214, 'deDE', 'Seid Ihr bereit, Euern Geist auf die Probe zu stell\'n?', '', 28153),
(145213, 'deDE', '', 'Kann ich einen als Haustier haben?', 28153),
(145212, 'deDE', '', 'Nur für Echsenvögel!', 28153),
(145211, 'deDE', '', 'Das ist aber ein großer Turm. Sieht aus wie... ein riesiges Vogelhaus!', 28153),
(145210, 'deDE', '', 'Hey, was sind das für fliegende Dinger? Die sind ja schön!', 28153),
(145209, 'deDE', '', 'Das heißt... Wohnt Ihr eigentlich überhaupt irgendwo?', 28153),
(145208, 'deDE', '', 'Wohnt Ihr hier?', 28153),
(145207, 'deDE', '', 'Wie macht sie das?', 28153),
(145206, 'deDE', '', 'Whoa... eine fliegende Stadt! Ist das Euer Ernst?!', 28153),
(145205, 'deDE', '', 'Spielt Ihr Prinzessin mit mir?', 28153),
(145204, 'deDE', '', 'Wisst Ihr, wer da drin wohnt? Bestimmt eine Prinzessin.', 28153),
(145203, 'deDE', '', 'Wow! Das ist das schönste Haus, das ich jemals gesehen habe!', 28153),
(145202, 'deDE', '', 'Iiiiiiehhhh!', 28153),
(145201, 'deDE', '', 'Krabbelviecher vielleicht? Ja, ich wette deswegen. Pfui Spinne! Ich hasse Krabbelviecher.', 28153),
(145200, 'deDE', '', 'Was wollten sie wohl damit fernhalten?', 28153),
(145199, 'deDE', '', 'Wow! Das ist die größte Mauer, die ich jemals gesehen habe!', 28153),
(145197, 'deDE', '', 'Uuna umarmt Euch.', 28153),
(145196, 'deDE', 'Du nicht nehmen Stiefel!', '', 28153),
(145195, 'deDE', '', 'Okay, lasst uns gehen! Es gibt so viel, was ich noch sehen möchte!', 28153),
(145194, 'deDE', '', 'Richte Mama und Papa aus, dass ich sie vermisse und... dass ich sie bald wiedersehen werde!', 28153),
(145193, 'deDE', '', 'Das Licht sagt, ich kann bleiben! Juhuu!', 28153),
(145192, 'deDE', '', 'Wäre es schlimm, wenn ich noch ein bisschen bei meinem Freund hier bleibe? Nur ein klein wenig länger?', 28153),
(145191, 'deDE', '', 'Es gibt so viel, was ich noch tun wollte. So viele Orte, die ich noch sehen wollte...', 28153),
(145190, 'deDE', '', 'Moment mal...', 28153),
(145189, 'deDE', '', 'Mama! Papa! Sie warten auf mich!', 28153),
(145188, 'deDE', '', 'Das Licht... es will, dass ich ihm folge...', 28153),
(145187, 'deDE', '', 'Was... was ist denn los?', 28153),
(145186, 'deDE', '', 'Wir haben es geschafft! Wir haben sie geschlagen!', 28153),
(145185, 'deDE', '', 'Die Finsternis ist weg! Ich kann wieder sehen!', 28153),
(145184, 'deDE', '', 'Ihr werdet zahl\'n für das, was Ihr gemacht habt!', 28153),
(145183, 'deDE', 'Verflucht sollt Ihr sein! Ich war noch nicht fertig...', '', 28153),
(145182, 'deDE', 'Euer Tod wird die Bansheekönigin sehr erfreuen!', '', 28153),
(145181, 'deDE', 'Allianzabschaum! Ich werde der Dunklen Fürstin Euren Kopf bringen!', '', 28153),
(145180, 'deDE', '', 'Ich werd\' Euch die Kehle aufschlitz\'n, $n!', 28153),
(145179, 'deDE', 'In der Ferne sind schnelle Hufschläge zu hören. Jemand ist da im Anmarsch.', 'In der Ferne sind schnelle Hufschläge zu hören. Jemand ist da im Anmarsch.', 28153),
(145178, 'deDE', '', 'Ihr wagt\'s, mich zu unterbrech\'n. Jetzt werdet Ihr sterb\'n, $n!', 28153),
(145177, 'deDE', '', 'Ich hab Euch ma\' beobachtet, $n.', 28153),
(145176, 'deDE', 'Ich werd\' Euch grill\'n wie Euren Köter von \'nem König! Für die Horde!', '', 28153),
(145175, 'deDE', 'Es riecht nach Ozon und die Luft beginnt zu knistern.', 'Es riecht nach Ozon und die Luft beginnt zu knistern.', 28153),
(145173, 'deDE', '', 'Dreist, aber ich hab mehr drauf wie meine Magie.', 28153),
(145172, 'deDE', 'Ich bin bereit. Beginnen wir mit dem Ritual.', 'Ich bin bereit. Beginnen wir mit dem Ritual.', 28153),
(145171, 'deDE', 'Ich höre die Schreie der Welt unter meinen Füßen. Azeroth windet sich in Schmerzen! Wir müssen einen Weg finden, ihr Leiden zu lindern...', '', 28153),
(145170, 'deDE', '', 'So einfach sterb\' ich nich\', $n. Ihr kriegt meinen Zorn zu spür\'n!', 28153),
(145169, 'deDE', '', 'Endlich hab ich Euch gefund\'n, $n.', 28153),
(145168, 'deDE', 'Ich werde Euch den Kopf einschlagen!', '', 28153),
(145167, 'deDE', 'Ich werde Euch das Fleisch von den Knochen ziehen!', '', 28153),
(145166, 'deDE', 'Ich werde bis in alle Ewigkeit auf Eurem Grab stehen.', '', 28153),
(145165, 'deDE', 'Mir wurde alle Hoffnung genommen.', '', 28153),
(145164, 'deDE', 'Verflucht. Nicht schon wieder.', '', 28153),
(145163, 'deDE', 'Ihr werdet leiden, für das, was Ihr mir angetan habt.', '', 28153),
(145162, 'deDE', 'Ich werde Euch die Lebenskraft entziehen.', '', 28153),
(145161, 'deDE', 'Ich genieße den Klang von aufeinanderschmetterndem Metall und den Geruch von Angst.', '', 28153),
(145160, 'deDE', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Der |cFFF00000|Hspell:260953|h[Eiserne Blick]|h|r ist auf Euch gerichtet!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Ihr seid |cFFF00000|Hspell:257459|h[Am Haken]|h|r!', 28153),
(145159, 'deDE', '', 'ICH WERDE NIE WIEDER ANGST HABEN!', 28153),
(145158, 'deDE', '', 'Mein Licht ist superstark!', 28153),
(145157, 'deDE', 'Ich will jetzt heimgeh\'n.', '', 28153),
(145156, 'deDE', '', 'Und solange mein Licht bei mir ist, wird die Finsternis niemals gewinnen!', 28153),
(145155, 'deDE', '', 'Meine Mama hat immer gesagt, das Licht würde mich finden. Ihr seid mein Licht!', 28153),
(145154, 'deDE', '', 'H-Held, Ihr seid hier! Ihr habt mich nicht zurückgelassen!', 28153),
(145153, 'deDE', 'Nein... nein...', 'Nein... nein...', 28153),
(145152, 'deDE', 'Dunkle Fürstin... Ich habe versagt...', 'Dunkle Fürstin... Ich habe versagt...', 28153),
(145151, 'deDE', 'Ich bin der ganz unt\'n am Totempfahl, Mann.', '', 28153),
(145150, 'deDE', 'Endlich...', 'Endlich...', 28153),
(145149, 'deDE', 'Oh... nicht schon wieder...', 'Oh... nicht schon wieder...', 28153),
(145148, 'deDE', 'Für die Dunkle Fürstin!', 'Für die Dunkle Fürstin!', 28153),
(145147, 'deDE', 'Gebt Eure Hoffnung auf!', 'Gebt Eure Hoffnung auf!', 28153),
(145146, 'deDE', 'Folgt uns in den Tod!', 'Folgt uns in den Tod!', 28153),
(145145, 'deDE', 'Ich werde mich an Euren Knochen laben!', 'Ich werde mich an Euren Knochen laben!', 28153),
(145144, 'deDE', 'Tod den Lebenden!', 'Tod den Lebenden!', 28153),
(145143, 'deDE', 'Für Sylvanas!', 'Für Sylvanas!', 28153),
(145142, 'deDE', '', 'Uuna schlingt die Arme um ihren Leib und beginnt zu weinen.', 28153),
(145141, 'deDE', '', 'Ich... ich schaff es nicht! Ich will einfach nur nach Hause.', 28153),
(145140, 'deDE', '', 'Held? Seid Ihr noch hier? Ich habe solche Angst!', 28153),
(145139, 'deDE', 'Das finst\'re Juju wird Euch krieg\'n!', '', 28153),
(145137, 'deDE', 'Könnt Ihr Eure Vorfahren schon ruf\'n hör\'n?', '', 28153),
(145136, 'deDE', 'Ich verfluch Euch, Ihr werdet so mies ausseh\'n wie mein Bruder.', '', 28153),
(145135, 'deDE', 'Was kennt\'n Ihr für Voodoo, Mann?', '', 28153),
(145133, 'deDE', 'Soll\'n die Knochen fall\'n, wie\'s das Schicksal will.', '', 28153),
(145130, 'deDE', 'Die Dornen wollen Eure Seele!', '', 28153),
(145129, 'deDE', 'Dann wandte er sich ab und verschwand wieder im Wald. Seitdem genießen die Tapferen und Rechtschaffenen den Schutz des weißen Hirsches dieses Waldes.', 'Dann wandte er sich ab und verschwand wieder im Wald. Seitdem genießen die Tapferen und Rechtschaffenen den Schutz des weißen Hirsches dieses Waldes.', 28153),
(145128, 'deDE', '\"Ich bin Athair, das Herz dieses Waldes. Solange ich lebe, werde ich Euch und Eure Leute beschützen, wenn sie zu mir kommen\", sagte der Hirsch.', '\"Ich bin Athair, das Herz dieses Waldes. Solange ich lebe, werde ich Euch und Eure Leute beschützen, wenn sie zu mir kommen\", sagte der Hirsch.', 28153),
(145127, 'deDE', '\"Beim Licht! Ihr könnt ja reden!\", rief Arom.', '\"Beim Licht! Ihr könnt ja reden!\", rief Arom.', 28153),
(145126, 'deDE', '', '<Applause sounds>', 28153),
(145125, 'deDE', '', '<Yawning sound>', 28153),
(145124, 'deDE', '', '<Short cheer--Wooooo!>', 28153),
(145123, 'deDE', '', '<Slightly longer cheer--Woohoo!>', 28153),
(145122, 'deDE', 'Feuer wird ihn vernichten!', '', 28153),
(145121, 'deDE', '', '<Chicken sounds>', 28153),
(145120, 'deDE', '', '<Crying sounds>', 28153),
(145119, 'deDE', '\"Gern geschehen. Ich habe mich nur für Eure freundliche Hilfe revanchiert.\"', '\"Gern geschehen. Ich habe mich nur für Eure freundliche Hilfe revanchiert.\"', 28153),
(145118, 'deDE', '', '<Crying sounds, variant>', 28153),
(145117, 'deDE', '', '<Crying sounds, variant.>', 28153),
(145116, 'deDE', '', '<Kiss sound>', 28153),
(145115, 'deDE', '\"Danke, mein Freund\", sagte Arom zum Hirsch.', '\"Danke, mein Freund\", sagte Arom zum Hirsch.', 28153),
(145114, 'deDE', '', '<Laughing sounds>', 28153),
(145113, 'deDE', '', '<Laughing>', 28153),
(145112, 'deDE', '', '<Making a raspberry sound--Pfffthblth!>', 28153),
(145111, 'deDE', 'Arom und der weiße Hirsch kämpften gemeinsam gegen die Krieger und besiegten sie schließlich.', 'Arom und der weiße Hirsch kämpften gemeinsam gegen die Krieger und besiegten sie schließlich.', 28153),
(145110, 'deDE', '', '<Roar of dominance>', 28153),
(145109, 'deDE', '', '<Variant roar>', 28153),
(145108, 'deDE', '', '<Sighing sound>', 28153),
(145107, 'deDE', '', '<Train noises--chugga chugga choo choo!>', 28153),
(145106, 'deDE', 'Der weiße Hirsch kehrte zurück und trampelte einige der Drust zu Tode!', 'Der weiße Hirsch kehrte zurück und trampelte einige der Drust zu Tode!', 28153),
(145105, 'deDE', 'Da vernahm er ein mächtiges Röhren aus dem Wald!', 'Da vernahm er ein mächtiges Röhren aus dem Wald!', 28153),
(145104, 'deDE', 'Dennoch war er fest entschlossen, nicht aufzugeben und so viele von ihnen mit in den Tod zu nehmen, wie er konnte.', 'Dennoch war er fest entschlossen, nicht aufzugeben und so viele von ihnen mit in den Tod zu nehmen, wie er konnte.', 28153),
(145103, 'deDE', 'Lord Arom kämpfte tapfer und geschickt gegen gleich zehn ihrer Krieger! Doch sie waren in der Übermacht und hatten ihn umzingelt!', 'Lord Arom kämpfte tapfer und geschickt gegen gleich zehn ihrer Krieger! Doch sie waren in der Übermacht und hatten ihn umzingelt!', 28153),
(145102, 'deDE', 'Interessant.', 'Interessant.', 28153),
(145101, 'deDE', 'In der Nacht griffen die Drust an!', 'In der Nacht griffen die Drust an!', 28153),
(145100, 'deDE', 'Der Hirsch sprang zurück in den Wald und Arom schlug sein Lager auf.', 'Der Hirsch sprang zurück in den Wald und Arom schlug sein Lager auf.', 28153),
(145099, 'deDE', '\"Wer so viele Drust bezwingen kann, hat einen Platz in meinem Wald verdient\", dachte Lord Arom und heilte stattdessen die Wunden des Hirsches.', '\"Wer so viele Drust bezwingen kann, hat einen Platz in meinem Wald verdient\", dachte Lord Arom und heilte stattdessen die Wunden des Hirsches.', 28153),
(145098, 'deDE', 'Hütet Euch vor den Dornen!', '', 28153),
(145097, 'deDE', 'Die Leute von Lord Arom benötigten Nahrung und der Hirsch hätte viele von ihnen satt gemacht, aber er entschied sich, nicht zuzustoßen.', 'Die Leute von Lord Arom benötigten Nahrung und der Hirsch hätte viele von ihnen satt gemacht, aber er entschied sich, nicht zuzustoßen.', 28153),
(145096, 'deDE', 'Der Hirsch war von den Drust angegriffen worden. Er hatte zwar viele von ihnen getötet, war aber auch selbst verletzt worden.', 'Der Hirsch war von den Drust angegriffen worden. Er hatte zwar viele von ihnen getötet, war aber auch selbst verletzt worden.', 28153),
(145095, 'deDE', 'Als Lord Arom eines Tages im Wald auf der Jagd war, begegnete er einem riesigen weißen Hirsch.', 'Als Lord Arom eines Tages im Wald auf der Jagd war, begegnete er einem riesigen weißen Hirsch.', 28153),
(145094, 'deDE', 'Ja! Lasst uns frei!', '', 28153),
(145093, 'deDE', 'Ihr habt... uns befreit...', '', 28153),
(145092, 'deDE', 'Endlich... frei...', '', 28153),
(145091, 'deDE', 'Habt... Dank...', '', 28153),
(145090, 'deDE', 'Jetzt gehört Ihr zu uns.', '', 28153),
(145089, 'deDE', 'Es gibt kein Entkommen.', '', 28153),
(145088, 'deDE', '', 'Bringt diesen Gegner zur Strecke!', 28153),
(145087, 'deDE', '', 'Schaltet dieses Ziel aus!', 28153),
(145086, 'deDE', '', 'Konzentriert Euch auf den Feind!', 28153),
(145085, 'deDE', 'Flieht! Es gibt keine Hoffnung mehr!', '', 28153),
(145084, 'deDE', 'Für immer vereint.', '', 28153),
(145083, 'deDE', '', 'Zu den Waffen!', 28153),
(145082, 'deDE', '', 'Für die Königin!', 28153),
(145081, 'deDE', '', 'Bei der Macht des Berges!', 28153),
(145080, 'deDE', 'Teilt nicht unser Los!', '', 28153),
(145079, 'deDE', '', 'Macht sie nieder!', 28153),
(145078, 'deDE', '', 'Schlagt sie zurück!', 28153),
(145077, 'deDE', '', 'Zieht Euch zurück!', 28153),
(145076, 'deDE', '', 'Rückzug!', 28153),
(145075, 'deDE', '', 'Macht, dass Ihr wegkommt!', 28153),
(145074, 'deDE', '', 'Hier lang.', 28153),
(145073, 'deDE', '', 'Ich gehe voraus.', 28153),
(145072, 'deDE', '', 'Folgt mir.', 28153),
(145071, 'deDE', '', 'Für die Allianz!', 28153),
(145070, 'deDE', '', 'Ich brauche Hilfe!', 28153),
(145069, 'deDE', '', 'Kommt mir zu Hilfe!', 28153),
(145068, 'deDE', '', 'Es droht Gefahr!', 28153),
(145067, 'deDE', '', 'Auf sie mit Gebrüll!', 28153),
(145066, 'deDE', '', 'Heizt ihnen ein!', 28153),
(145065, 'deDE', '', 'Wartet hier.', 28153),
(145064, 'deDE', '', 'Rührt Euch nicht vom Fleck!', 28153),
(145063, 'deDE', '', 'Ich bin schwer verwundet!', 28153),
(145062, 'deDE', '', 'Ich brauche dringend Heilung!', 28153),
(145061, 'deDE', '', '<Standard attack: Total 10>', 28153),
(145060, 'deDE', '', '<Big attack: Total 5>', 28153),
(145059, 'deDE', '', '<Convey releasing power or charging enemy: Total 4-6>', 28153),
(145058, 'deDE', '', '<Release spell, throwing energy: Total 3-5>', 28153),
(145057, 'deDE', '', '<Convey summoning power. Energy buildup: Total 5-7>', 28153),
(145056, 'deDE', '', '<Charging to attack enemy: Total 5-7>', 28153),
(145055, 'deDE', '', '<Dying sounds: Total 5>', 28153),
(145054, 'deDE', '', '<Distressed cry: Total 3>', 28153),
(145053, 'deDE', '', '<Release after expending magic: Total 3>', 28153),
(145052, 'deDE', '', '<Falling from high terrain. Impending injury or death: Total 1>', 28153),
(145051, 'deDE', '', '<Deep breath before focusing magic: Total 3>', 28153),
(145050, 'deDE', '', '<Jumping off ground: Total 3>', 28153),
(145049, 'deDE', '', '<Landing from jump: Total 3>', 28153),
(145048, 'deDE', '', '<Long attack with wind up. Jump attacks: Total 5-7>', 28153),
(145047, 'deDE', '', '<Breathe as if you are running: Total 3>', 28153),
(145046, 'deDE', '', '<Vocalized cheer: Total 3>', 28153),
(145045, 'deDE', '', '<Player takes a wound: Total 10>', 28153),
(145044, 'deDE', '', '<Player takes significant wound: Total 5>', 28153),
(145043, 'deDE', '', 'Behaltet stets Euer Ziel im Blick.', 28153),
(145042, 'deDE', '', 'Wir tun, was wir tun müssen für jene, die wir lieben!', 28153),
(145041, 'deDE', '', 'Mögen Eure Pfeile immer treffen.', 28153),
(145040, 'deDE', '', 'Lebt wohl.', 28153),
(145039, 'deDE', '', 'Die Schatten können mächtige Verbündete sein... wenn man weiß, wie man sie kontrolliert.', 28153),
(145038, 'deDE', '', 'Grüße.', 28153),
(145037, 'deDE', '', 'Wir können niemanden mehr einladen.', 28153),
(145036, 'deDE', '', 'Wir alle beschreiten einen Pfad. Wählt den Eurigen.', 28153),
(145035, 'deDE', '', 'Ich kann gerade nicht mehr trinken.', 28153),
(145034, 'deDE', '', 'Diese Fähigkeit habe ich noch nicht erlernt.', 28153),
(145033, 'deDE', '', 'Das kann ich noch nicht.', 28153),
(145032, 'deDE', '', 'Dieser Zauber ist noch nicht bereit.', 28153),
(145031, 'deDE', '', 'Gibt es Neuigkeiten?', 28153),
(145030, 'deDE', '', 'Das kann ich noch nicht wirken.', 28153),
(145029, 'deDE', '', 'Das lädt noch auf.', 28153),
(145028, 'deDE', '', 'Nutzt jede Waffe, die Euch zur Verfügung steht.', 28153),
(145027, 'deDE', '', 'Es ist ein guter Tag für eine Jagd.', 28153),
(145026, 'deDE', '', 'Ich galt jahrelang als verschollen und Euch fällt nichts anderes ein, als mich mit solchem Unfug zu reizen?', 28153),
(145025, 'deDE', '', 'Das kann ich nicht tun.', 28153),
(145024, 'deDE', '', 'Dafür fehlt mir die Erlaubnis.', 28153),
(145023, 'deDE', '', 'Dieses Ziel kann ich nicht angreifen.', 28153),
(145022, 'deDE', '', 'Meine Leere wird Euch verschlingen... wenn Ihr lieb fragt.', 28153),
(145021, 'deDE', '', 'Das kann ich nicht angreifen.', 28153),
(145020, 'deDE', '', 'Mein Inventar ist voll.', 28153),
(145019, 'deDE', '', 'Mehr kann ich nicht tragen.', 28153),
(145018, 'deDE', '', 'Es ist nicht immer leicht unter Schwestern. Besonders, wenn eine von ihnen untot ist.', 28153),
(145017, 'deDE', '', 'Das ist verschlossen.', 28153),
(145016, 'deDE', '', 'Mehr kann ich davon nicht tragen.', 28153),
(145015, 'deDE', '', 'Diesen Gegenstand kann ich noch nicht benutzen.', 28153),
(145014, 'deDE', '', 'Das ist noch nicht bereit.', 28153),
(145013, 'deDE', '', 'Dieser Gegenstand lädt noch auf.', 28153),
(145012, 'deDE', '', 'Nicht genug Jähzorn.', 28153),
(145011, 'deDE', '', 'Mein Jähzorn reicht nicht aus.', 28153),
(145010, 'deDE', '', 'Nicht genug Schmerz.', 28153),
(145009, 'deDE', '', 'Mein Schmerz reicht nicht aus.', 28153),
(145008, 'deDE', '', 'Das ist keine Tasche.', 28153),
(145007, 'deDE', '', 'Meine Mittel reichen nicht aus.', 28153),
(145006, 'deDE', '', 'Das kann ich mir nicht leisten.', 28153),
(145005, 'deDE', '', 'Das ist zu teuer.', 28153),
(145004, 'deDE', '', 'Dieser Held kann sich der Gruppe nicht anschließen.', 28153),
(145003, 'deDE', '', 'Ich habe keine Munition mehr.', 28153),
(145002, 'deDE', '', 'Nicht genug Energie.', 28153),
(145001, 'deDE', '', 'Ich brauche mehr Energie.', 28153),
(145000, 'deDE', '', 'Ich benötige erst Mana.', 28153),
(144999, 'deDE', '', 'Mein Mana ist knapp.', 28153),
(144998, 'deDE', '', 'Nicht genug Mana.', 28153),
(144997, 'deDE', '', 'Nicht genug Wut.', 28153),
(144996, 'deDE', '', 'Ich brauche mehr Wut.', 28153),
(144995, 'deDE', '', 'Zu weit entfernt.', 28153),
(144994, 'deDE', '', 'Natürlich liebe ich ihn immer noch. Aber ich weiß nicht, was Euch das angeht!', 28153),
(144993, 'deDE', '', 'Ich bin außer Reichweite.', 28153),
(144992, 'deDE', '', 'Ich muss näher heran.', 28153),
(144991, 'deDE', '', 'Meine Waffe erfordert beide Hände.', 28153),
(144990, 'deDE', '', 'Diese Fähigkeit ist noch nicht bereit.', 28153),
(144989, 'deDE', '', 'Das kann ich noch nicht tun.', 28153),
(144988, 'deDE', '', 'Noch nicht bereit.', 28153),
(144987, 'deDE', '', 'Das kann ich dort nicht ablegen.', 28153),
(144986, 'deDE', '', 'Diese Tasche ist voll.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'deDE', '', 'Das kann ich hier nicht tun.', 28153),
(144984, 'deDE', '', 'Das kann ich nicht wegwerfen.', 28153),
(144983, 'deDE', '', 'Das ist an mich gebunden.', 28153),
(144982, 'deDE', '', 'Das kann ich nicht anlegen.', 28153),
(144981, 'deDE', '', 'Dafür ist meine Stufe nicht hoch genug.', 28153),
(144980, 'deDE', '', 'Das kann ich noch nicht benutzen.', 28153),
(144979, 'deDE', '', 'Dafür ist meine Fertigkeitsstufe nicht hoch genug.', 28153),
(144978, 'deDE', '', 'So etwas kann ich nicht anlegen.', 28153),
(144977, 'deDE', '', 'Diesen Zauber kann ich nicht erlernen.', 28153),
(144976, 'deDE', '', 'Das kann ich nicht plündern.', 28153),
(144975, 'deDE', '', 'Das steht mir nicht zu.', 28153),
(144974, 'deDE', '', 'Ich muss näher heran.', 28153),
(144973, 'deDE', '', 'Das ist zu weit weg.', 28153),
(144972, 'deDE', '', 'Da komme ich nicht ran.', 28153),
(144971, 'deDE', '', 'Das kann ich nicht handeln.', 28153),
(144970, 'deDE', '', 'Das kann ich nicht benutzen.', 28153),
(144969, 'deDE', '', 'Das ist nicht angelegt.', 28153),
(144968, 'deDE', '', 'Das muss ich erst anlegen.', 28153),
(144967, 'deDE', '', 'Das kann ich gerade nicht plündern.', 28153),
(144966, 'deDE', '', 'Ich habe kein Ziel.', 28153),
(144965, 'deDE', '', 'Ich muss zuerst etwas anvisieren.', 28153),
(144964, 'deDE', '', 'Ich brauche ein Ziel.', 28153),
(144963, 'deDE', '', 'Niedere Geister, erhabene Mächte, lasst wachsen die Dornen zum großen Geflechte!', 28153),
(144962, 'deDE', '', 'Gib mir die Iris, Schwester!', 28153),
(144961, 'deDE', '', 'Meine Dornen werden Euch in Stücke reißen!', 28153),
(144960, 'deDE', '', 'Je mehr Ihr Euch widersetzt, desto mehr werdet Ihr bluten!', 28153),
(144959, 'deDE', '', 'Ihr tragt das schwarze Mal!', 28153),
(144958, 'deDE', '', 'Ich werde mein Heim mit Euren Schädeln schmücken.', 28153),
(144956, 'deDE', '', 'Meine Wurzeln leben noch...', 28153),
(144955, 'deDE', '', 'Ich liebe das Geräusch brechender Knochen.', 28153),
(144954, 'deDE', 'Ich werd heut gut essen. Vielen Dank un\' Segen für Euch.', 'Ich werd heut gut essen. Vielen Dank un\' Segen für Euch.', 28153),
(144953, 'deDE', 'Ich seid echt gut zu mir. Danke, Mann!', 'Ich seid echt gut zu mir. Danke, Mann!', 28153),
(144952, 'deDE', 'Danke vielmals.', 'Danke vielmals.', 28153),
(144951, 'deDE', '', 'Solch grazile Knochen!', 28153),
(144950, 'deDE', '<Gebt zehn Goldmünzen.>', '<Gebt zehn Goldmünzen.>', 28153),
(144949, 'deDE', '<Gebt eine Goldmünze.>', '<Gebt eine Goldmünze.>', 28153),
(144948, 'deDE', '<Gebt fünf Kupfermünzen.>', '<Gebt fünf Kupfermünzen.>', 28153),
(144947, 'deDE', 'Habt Ihr \'n paar Kupfer, Kumpel?', 'Habt Ihr \'n paar Kupfer, Kumpel?', 28153),
(144946, 'deDE', '', 'Verwestes Fleisch und Marterschreie, Übel, wachse und gedeihe!', 28153),
(144945, 'deDE', '', 'Euer Ende steht bevor!', 28153),
(144944, 'deDE', '', 'Du warst schon dran!', 28153),
(144943, 'deDE', '', '... und Rezan stieß über den Leichen der Bluttrollarmee \'n lautes Brüllen aus. Triumphier\'nd!', 28153),
(144942, 'deDE', '', 'Eure Qualen sind längst nicht zu Ende.', 28153),
(144941, 'deDE', '', 'Welch köstliche Pein!', 28153),
(144940, 'deDE', '', 'Mein Körper ist zerbrochen... doch mein Fluch... bleibt...', 28153),
(144939, 'deDE', '', 'Eure Schmerzensschreie wird man weithin hören!', 28153),
(144938, 'deDE', '', 'Schwarze Seele dunkler Nacht, lass sie spüren deine Macht!', 28153),
(144937, 'deDE', '', 'Jetzt seid Ihr mein!', 28153),
(144936, 'deDE', '', 'Tanzt, kleines Püppchen, tanzt!', 28153),
(144935, 'deDE', '', 'Gib mir die Iris, Dummkopf! Nur ich kann ihre Macht fokussieren!', 28153),
(144934, 'deDE', '', 'Eure Seelen gehören mir... für immer.', 28153),
(144933, 'deDE', '', 'Der Tod ist nicht mein Ende...', 28153),
(144932, 'deDE', '', 'Solch eine zarte Seele.', 28153),
(144931, 'deDE', '', 'Ihr habt hier keine Macht!', 28153),
(144930, 'deDE', '', '$n, folgt mir. Ihr andren zu Rokhan an der nördlich\'n Front!', 28153),
(144929, 'deDE', 'Schaut Euch all diese Allianztruppen an! Sie schicken alles, was sie haben!', '', 28153),
(144928, 'deDE', 'Sie entsenden Heerscharen von Soldaten! Sie dürfen auf keinen Fall durchkommen!', '', 28153),
(144926, 'deDE', '', 'Grüße, $C.', 28153),
(144925, 'deDE', '', 'Tragt immer in Eurem Herzen, was es bedeutet, lichtgeschmiedet zu sein.', 28153),
(144924, 'deDE', '', '<Fareeya empfängt Euch mit einem warmen Lächeln.>$B$BIhr habt Euch bei den Prüfungen gut geschlagen, $C. Aber ich habe das Gefühl, das ist erst der Anfang Eures Weges.', 28153),
(144923, 'deDE', 'Wenn Ihr Maela sucht, sie hilft an der Front aus.$B$BIn Sturmwind gibt es viele fähige Schneider, die Euch noch das eine oder andere beibringen können.', '', 28153),
(144921, 'deDE', '', 'Möge das Licht diese Werkbank holen! Ich werde diese Werkstatt nie wieder benutzen können.$B$BDie Verunreinigung durch diese Tierfelle von Argus lässt sich nicht auswaschen, egal wie sehr ich schrubbe.', 28153),
(144908, 'deDE', 'Die Vindikaar erwartet ihre nächste Reise.\n\nEbenso wie ich.', '', 28153),
(144907, 'deDE', 'Danke für Eure Hilfe, $GKumpel:Mädchen;! Ihr habt was gut bei mir!', '', 28153),
(144906, 'deDE', 'Wenn Ihr mich entschuldigt: Ich bin dann mal in der Taverne.', '', 28153),
(144905, 'deDE', 'Ahh, schon besser. Das ist genau die richtige Rüstung für einen mächtigen Krieger! Ein Krieger, dessen Taten Azeroth bis in die Grundfesten erschüttern!', '', 28153),
(144904, 'deDE', 'Darauf könnt Ihr Gift nehmen! Ich habe diese Rüstung ehrlich erworben, auch wenn ich sie noch nicht abbezahlt habe.', '', 28153),
(144903, 'deDE', '', 'Heute scheint das Glück Euch hold zu sein, Herr Steinbraue. Ihr könnt die Ware wieder mitnehmen.', 28153),
(144902, 'deDE', 'Lasst Eure Pfoten von mir, Fellknäuel!', '', 28153),
(144901, 'deDE', '', 'Ja, Madame.', 28153),
(144900, 'deDE', '', 'Verschwindet! Wir haben keine Angst vor Euch!', 28153),
(144899, 'deDE', '%s nickt.', '', 28153),
(144898, 'deDE', '', 'Herr Chu, bitte begleitet diesen Zwerg nach draußen. Fräulein Xiulan, setzt die Rüstung wieder auf unsere Inventarliste.', 28153),
(144897, 'deDE', 'Ich hab die Zahlung heute Morgen abgeschickt, ich schwöre es! Bitte, Ihr könnt mich doch nicht hängen lassen!', '', 28153),
(144896, 'deDE', '', 'Ihr habt einmal zu oft Eure Rechnung nicht beglichen, Herr Steinbraue. Ich konfisziere die Ware, wie festgelegt in unserem Vertrag.', 28153),
(144895, 'deDE', '', 'Sie sind hier...', 28153),
(144894, 'deDE', '', 'Wir finden ihn, nur die Ruhe.', 28153),
(144893, 'deDE', 'Sie kamen aus dem Wald. Wir haben gekämpft. Meister Eschtal hat mich weggestoßen, da haben sie ihn geschnappt. Wir müssen ihn retten!', '', 28153),
(144892, 'deDE', '', 'Ich glaube Euch, Martin. Erzählt uns, was passiert ist.', 28153),
(144891, 'deDE', 'Ich habe alles versucht, um sie abzuwehren!', '', 28153),
(144889, 'deDE', '', 'Also... Wieso habt Ihr diesen Zwerg mitgebracht? Eine Demonstration der Stärke? Abschreckung?', 28153),
(144888, 'deDE', 'Das hat ja genauso funktioniert, wie ich es mir gedacht hatte.', '', 28153),
(144887, 'deDE', '...Richtig... Ja. Natürlich!', '', 28153),
(144886, 'deDE', 'Vergesst nicht unsere Aufgabe hier. Wir müssen das Auge finden, bevor es der Allianz in die Hände fällt.', '', 28153),
(144885, 'deDE', '', 'Kaum zu glauben, dass die Trolle auf dem archäologischen Fund des Jahrtausends gesessen haben könnten!', 28153),
(144884, 'deDE', '', 'Die Schlacht hat begonn\'. Führt uns zum Sieg!', 28153),
(144883, 'deDE', 'Als Ihr gingt, sagtet Ihr Eurem Vater, Ihr werdet die Welt entdeck\'n, nich\' dass Ihr mit den Hund\'n der Horde verhandelt.', '', 28153),
(144882, 'deDE', 'Prinzessin.', '', 28153),
(144881, 'deDE', 'Euer Vater wartet schon auf uns.', '', 28153),
(144880, 'deDE', '', 'Prinzessin... Erlaubt mir, Euch als Erste...', 28153),
(144879, 'deDE', '', 'Ich sollt Euch warn\', mein Vater is\' zwar engstirnig, aber er is\' echt aufmerksam. Wette, er weiß schon, dass Ihr mich aus Sturmwind befreit habt.', 28153),
(144878, 'deDE', '', 'Ihr habt nich\' über das Schicksal zu entscheid\'n, General.', 28153),
(144877, 'deDE', 'Um das Königreich zu schütz\'n, wär\'s das Beste, wenn ich dieses... Ding da... nach Vol\'dun verbann. Die Horde hat in Zandalar nix zu such\'n.', '', 28153),
(144876, 'deDE', '', 'Ihr sollt dieses Königreich beschütz\'n. Wenn Ihr Eure Pflicht nich\' erfüllt, muss ich wen anders find\'n.', 28153),
(144875, 'deDE', '<Berührt die Träne.>', '<Berührt die Träne.>', 28153),
(144874, 'deDE', '', 'General.', 28153),
(144873, 'deDE', '<Die Träne eines grünen Drachen, in Schatten gehüllt durch unbekannte Kräfte.>', '', 28153),
(144872, 'deDE', '', 'Aber der Rat der Zanchuli, mit sein\' Intriganten un\' alten Knackern, redet die Bedrohung klein. Die hab\'n mein\' Vater überzeugt, nix zu tun.', 28153),
(144871, 'deDE', '', 'Bluttrolle fallen von Norden ein und verschlepp\'n unsere Leute in die Sümpfe von Nazmir – keiner ist zurückgekehrt.', 28153),
(144870, 'deDE', '', 'Zandalar is\' umgeb\'n von Feind\'n, von inn\'n und auß\'n. Deswegen hab ich versucht, die Horde zu finden. Deshalb brauch ich Euch, ihren größt\'n Champion.', 28153),
(144869, 'deDE', '', 'Wir werd\'n nich\' lang allein sein, $n. Es gibt was über mein Königreich, das Ihr wiss\'n solltet.', 28153),
(144868, 'deDE', '', 'Kommt, Champion der Horde. Wir statt\'n mei\'m Vater \'nen Besuch ab. Zul... bis später.', 28153),
(144867, 'deDE', '', 'Tze\'na! Hallo meine Kleine, hast du mich vermisst?', 28153),
(144866, 'deDE', '', 'Ich kenne das Kind, von dem Ihr sprecht. Ich habe sein verzweifeltes Rufen vernommen.\n\nIch werde Euch Zutritt in diese Welt verschaffen, so dass Ihr dort nach ihr suchen könnt.\n\nSie befindet sich an einem Ort, wo die Barriere zwischen der Welt des Lebens und der des Todes so dünn ist, dass sie in Eure Welt durchbrechen.\n\nDoch Vorsicht! Ihr habt dort keine Macht. Seine Bewohner können nicht von Sterblichen verletzt werden.\n\nVersucht Euer Bestes, doch wahrscheinlich könnt Ihr Eurer Freundin nicht helfen.', 28153),
(144864, 'deDE', 'Möge das Licht mit Euch sein.', 'Möge das Licht mit Euch sein.', 28153),
(144863, 'deDE', 'Ich suche ein kleines Mädchen namens Uuna. Habt Ihr sie gesehen?', 'Ich suche ein kleines Mädchen namens Uuna. Habt Ihr sie gesehen?', 28153),
(144862, 'deDE', '', 'T\'paartos hat uns gezeigt, wie man Klinge, Fels, Pergament spielt, aber ich habe vergessen, wie es geht.', 28153),
(144860, 'deDE', 'Das Allianztor wurde zerstört!', '', 28153),
(144859, 'deDE', '', 'Greifen! Angriff!', 28153),
(144853, 'deDE', 'Unsere tapfersten Krieger kämpfen meist an vorderster Front. Das Mindeste, was ich tun kann, ist für ihre Familien zu sorgen, bis sie zurückkehren.', 'Unsere tapfersten Krieger kämpfen meist an vorderster Front. Das Mindeste, was ich tun kann, ist für ihre Familien zu sorgen, bis sie zurückkehren.', 28153),
(144852, 'deDE', 'Ihr wagt Euch in meine Tunnel? Wie töricht!', '', 28153),
(144851, 'deDE', '', 'Der Schwanz ist so flauschig!', 28153),
(144850, 'deDE', '', 'Darf ich es behalten?', 28153),
(144849, 'deDE', '', 'Nein! Bleibt doch und erzählt uns ein paar Abenteuergeschichten, T\'paartos!', 28153),
(144848, 'deDE', '', 'Er ist zurück!', 28153),
(144847, 'deDE', '', 'Es ist T\'paartos!', 28153),
(144846, 'deDE', 'Keine Sorge! T\'paartos wird bald zurückkehren, mit mehr Geschichten... und vielleicht einem anderen Freund.', '', 28153),
(144845, 'deDE', 'T\'paartos muss dieses Wesen jetzt zurückbringen. Sagt auf Wiedersehen, Kinder.', '', 28153),
(144842, 'deDE', '', 'Ooh!', 28153),
(144841, 'deDE', 'Erzählt mir, was bei dem Festmahl passiert ist.', 'Erzählt mir, was bei dem Festmahl passiert ist.', 28153),
(144840, 'deDE', 'Die Dunkle Fürstin hat einen Auftrag für Euch, $C. Ich hoffe, Ihr seid bereit...', '', 28153),
(144839, 'deDE', '', 'T\'paartos!', 28153),
(144838, 'deDE', '', 'Bitte versprecht mir, dass Ihr mich nicht zurücklasst. Selbst, wenn es dunkel wird...', 28153),
(144837, 'deDE', '', 'Aber jetzt seid Ihr ja hier. Gemeinsam können wir gegen sie kämpfen! Oder?', 28153),
(144836, 'deDE', '', 'Ich laufe weg so schnell ich kann, aber sie finden mich jedes Mal.', 28153),
(144835, 'deDE', '', 'Sie werden bald hier sein.', 28153),
(144834, 'deDE', '', 'Ah, da seid Ihr! Das ist schon viel besser.', 28153),
(144833, 'deDE', 'Haha! T\'paartos ist froh, dass es Euch gut geht! T\'paartos hat auch ein Geschenk gebracht, das er in Val\'shara gefunden hat.', '', 28153),
(144832, 'deDE', 'Soll das ein SCHERZ sein?!', '', 28153),
(144831, 'deDE', 'Diese Kugeln scheinen Macht zu enthalten. Vielleicht könnte ich das Äußere entfernen...', '', 28153),
(144830, 'deDE', 'Gah!', '', 28153),
(144829, 'deDE', 'Diese Augen sind schön saftig. Da quetsche ich einfach ein paar Tropfen heraus und...', '', 28153),
(144828, 'deDE', '', 'Mir ist so kalt und es ist so dunkel hier. Ich weiß nicht, was ich tun soll!', 28153),
(144827, 'deDE', '', 'Ich werde nicht aufgeben! Versprochen!', 28153),
(144826, 'deDE', '', 'Held? Seid Ihr das?', 28153),
(144825, 'deDE', 'Unsere Agenten haben sich unter die Minenarbeiter gemischt, um Informationen zu sammeln. Wir werden bald wissen, was sie da unten vorhaben...', '', 28153),
(144824, 'deDE', 'Hätte... tiefer... graben... sollen...', 'Hätte... tiefer... graben... sollen...', 28153),
(144823, 'deDE', 'Ein Elf... der gräbt... Hah!', 'Ein Elf... der gräbt... Hah!', 28153),
(144822, 'deDE', 'Ihr kommt zu spät. Wir haben es gefunden...', 'Ihr kommt zu spät. Wir haben es gefunden...', 28153),
(144821, 'deDE', 'Wer\'s findet, darf\'s behalten...', 'Wer\'s findet, darf\'s behalten...', 28153),
(144820, 'deDE', 'Ihr werdet es niemals finden...', 'Ihr werdet es niemals finden...', 28153),
(144819, 'deDE', 'Eure Suche endet hier. Sterbt!', 'Eure Suche endet hier. Sterbt!', 28153),
(144818, 'deDE', 'Ich werde es genießen, Euch unter die Erde zu bringen.', 'Ich werde es genießen, Euch unter die Erde zu bringen.', 28153),
(144817, 'deDE', 'Wir werden Euch den Boden unter den Füßen weggraben!', 'Wir werden Euch den Boden unter den Füßen weggraben!', 28153),
(144816, 'deDE', 'Ihr wollt Euch mit den Dunkeleisenzwergen anlegen? Ganz schlechte Idee!', 'Ihr wollt Euch mit den Dunkeleisenzwergen anlegen? Ganz schlechte Idee!', 28153),
(144815, 'deDE', 'Aufdringlicher Elfenabschaum! Diese Ruinen gehören den Dunkeleisenzwergen!', 'Aufdringlicher Elfenabschaum! Diese Ruinen gehören den Dunkeleisenzwergen!', 28153),
(144812, 'deDE', '', 'Der Feind bekommt Verstärkung!', 28153),
(144811, 'deDE', 'Die Messwerte sind eindeutig! Wir reisen gen Westen!', '', 28153),
(144810, 'deDE', '', 'Die Schlucht gehört uns! Alle formier\'n! Plan\' wir den nächst\'n Angriff.', 28153),
(144809, 'deDE', '', 'Ihr wollt \'n rechteckiges Totem in \'nen runden Totemhalter steck\'n. Der Voodoo kann Stimmungen fühl\'n, Goblin.', 28153),
(144808, 'deDE', 'Sie kamen aus den Schatten und sie sind überall!', 'Sie kamen aus den Schatten und sie sind überall!', 28153),
(144807, 'deDE', '', 'Eine bewundernswerte Eigenschaft. Das gefällt mir an ihm.', 28153),
(144806, 'deDE', '', 'Oh ja, genau wie gestern, vorgestern... und den Tag davor.', 28153),
(144805, 'deDE', 'Die Tunnel sind gesichert. Öffnet das Tor!', '', 28153),
(144804, 'deDE', 'Er ist heute guter Laune, nicht wahr?', '', 28153),
(144803, 'deDE', '', 'Der Feind rückt näher. Bwonsalaka!', 28153),
(144802, 'deDE', 'Ich kehre zu den anderen zurück. Wir müssen diesem Wahnsinn Einhalt gebieten.', '', 28153),
(144801, 'deDE', 'Ich danke Euch, $p. Ich fürchte, die Lage ist schlimmer, als wir dachten.', '', 28153),
(144800, 'deDE', 'Was ist an der Löwenruh geschehen?', 'Was ist an der Löwenruh geschehen?', 28153),
(144799, 'deDE', 'Meine Agenten haben den Bereich gesichert, aber wir sollten trotzdem leise reden.', '', 28153),
(144798, 'deDE', 'Bwon\'chaga di choka!', 'Bwon\'chaga di choka!', 28153),
(144796, 'deDE', '', 'Voodoo kann in alle Herzen blick\'n, Kala, ob man nun dran glaubt oder nich\'.', 28153),
(144795, 'deDE', '', 'Durch Voodoo kann man die Gedanken von Dinosauriern lesen? Wirklich?!', 28153),
(144794, 'deDE', '', 'Das is\' \'ne Herzenssache, Kala. Das Herz, selbst Eures, erkennt Voodoo besser als der Kopf.', 28153),
(144792, 'deDE', 'Euer Wille is\' jetzt mein!', 'Euer Wille is\' jetzt mein!', 28153),
(144791, 'deDE', 'Der Rauch lässt Euch klarseh\'n!', 'Der Rauch lässt Euch klarseh\'n!', 28153),
(144790, 'deDE', 'Tief einatmen!', 'Tief einatmen!', 28153),
(144789, 'deDE', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[Erweckt]|h|r alle verbleibenden Knochenhaufen!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[Erweckt]|h|r alle verbleibenden Knochenhaufen!', 28153),
(144788, 'deDE', '', 'G\'huun...', 28153),
(144787, 'deDE', '', 'Nein... nicht so...', 28153),
(144786, 'deDE', '', 'Meine Schwestan werd\'n.... mich... räch\'n...', 28153),
(144785, 'deDE', '', 'Gachaga!', 28153),
(144784, 'deDE', '', 'Zuldazar... wird... fall\'n...', 28153),
(144783, 'deDE', '', 'Herrin... rächt mich...', 28153),
(144782, 'deDE', '', 'Ich dachte, ich bin am stärksten...', 28153),
(144781, 'deDE', '', 'Pohkiza...', 28153),
(144780, 'deDE', 'Na toll.', '', 28153),
(144779, 'deDE', 'Ausgezeichnete Arbeit mit den Tränken, $n. Jetzt muss ich nur von jedem ein paar Topfen hinzufügen und...', '', 28153),
(144778, 'deDE', '', 'Das wird einfach!', 28153),
(144777, 'deDE', '', 'Ich mach kurz\'n Prozess!', 28153),
(144776, 'deDE', '', 'Hah! Ihr seid keine Herausforderung!', 28153),
(144775, 'deDE', '', 'Noch \'n Schädel für meine Sammlung!', 28153),
(144774, 'deDE', '', 'Das is\' unser Land!', 28153),
(144773, 'deDE', 'Hurtig! Hier drüben! Wir haben viel zu tun!', '', 28153),
(144772, 'deDE', 'Es tut gut, sich einmal ein wenig auszuruhen.$B$BBesonders nach einem so erfolgreichen Geschäftsabschluss!', '', 28153),
(144771, 'deDE', 'Ihr löscht das Feuer und ich bereite im Labor alles vor. Oh, das wird ein prächtiger Spaß!', '', 28153),
(144770, 'deDE', 'Mir sind gerade die Materialen ausgegangen. Tut mir wirklich Leid.', '', 28153),
(144769, 'deDE', 'Ich habe mehrere Kugeln für Euch, Elrick.', 'Ich habe mehrere Kugeln für Euch, Elrick.', 28153),
(144768, 'deDE', 'Ich habe die Kräuter für Euch.', 'Ich habe die Kräuter für Euch.', 28153),
(144767, 'deDE', 'Hier sind die Augen, die Ihr wolltet.', 'Hier sind die Augen, die Ihr wolltet.', 28153),
(144766, 'deDE', 'Hier sind die Tränke, die Ihr benötigt.', 'Hier sind die Tränke, die Ihr benötigt.', 28153),
(144765, 'deDE', 'Ah, $gein Alchemistengenosse:eine Alchemistengenossin;! Kann ich vielleicht Euer Interesse an meinen neuesten Rezepten wecken?$b$bTränke sind meine Spezialität, doch von Zeit zu Zeit beschäftige ich mich auch mit Transmutationen.', '', 28153),
(144764, 'deDE', 'Willkommen in meinem Laden, $C! Darf ich Euch einen erfrischenden Trank anbieten oder hat etwas anderes Eure Aufmerksamkeit erweckt?$b$bTränke sind meine Spezialität, doch von Zeit zu Zeit beschäftige ich mich auch mit Transmutationen.', '', 28153),
(144763, 'deDE', '', 'Frischfleisch!', 28153),
(144762, 'deDE', '', 'Eure Ohr\'n komm\'n an meine Kette!', 28153),
(144761, 'deDE', '', 'Blut für G\'huun!', 28153),
(144760, 'deDE', 'Pssst, nicht bewegen! Er kann uns nur sehen, wenn wir uns bewegen.', 'Pssst, nicht bewegen! Er kann uns nur sehen, wenn wir uns bewegen.', 28153),
(144759, 'deDE', 'Das Licht stehe mir bei... er ist zurück!', 'Das Licht stehe mir bei... er ist zurück!', 28153),
(144758, 'deDE', 'Der Lichtgeschmiedete Verteidiger stöhnt.', 'Die Lichtgeschmiedete Verteidigerin stöhnt.', 28153),
(144757, 'deDE', 'Ich dachte, mein Verstand ist verloren.', 'Ich dachte, mein Verstand ist verloren.', 28153),
(144756, 'deDE', 'Die Erdenmutter segne Euch!', 'Die Erdenmutter segne Euch!', 28153),
(144755, 'deDE', 'Es war schrecklich, $R.', 'Es war schrecklich, $R.', 28153),
(144754, 'deDE', 'Ich muss... Mein Verstand... Ich muss fort von hier!', 'Ich muss... Mein Verstand... Ich muss fort von hier!', 28153),
(144753, 'deDE', 'Die Stimmen... sie haben mich in den Wahnsinn getrieben!', 'Die Stimmen... sie haben mich in den Wahnsinn getrieben!', 28153),
(144752, 'deDE', 'Vielen Dank, Champion.', 'Vielen Dank, Champion.', 28153),
(144751, 'deDE', '', 'Selbst die schärfste Waffe wird stumpf, wenn man sie zu oft benutzt. Nehmt Euch Zeit, um vollständig zu genesen, T\'paartos.', 28153),
(144750, 'deDE', 'T\'paartos dankt Lysara. T\'paartos fühlt sich wieder bereit zu kämpfen!', '', 28153),
(144749, 'deDE', 'Nicht genug, um T\'paartos aufzuhalten!', '', 28153),
(144748, 'deDE', 'Nehmt mein Abbildamulett dafür. Vertraut mir, is\' das Beste, was ich hab.', '', 28153),
(144747, 'deDE', 'Das is\' mal \'ne hübsche Fälschung! Von wem habt Ihr die? Ne, nich\' den Namen sag\'n! Einfach zu mir schick\'n...', '', 28153),
(144746, 'deDE', 'Und kein Wort darüber, wo Ihr das herhabt, sonst zeig ich Euch, wie ich meinen Namen bekomm\'n hab.', '', 28153),
(144745, 'deDE', '', 'Schon wieder, T\'paartos? Zum wie vielten Mal...', 28153),
(144744, 'deDE', 'Das ist nicht nur irgendein Nachtelfenkopf... Vor Tausenden von Jahren gehörte sie zum Adel!', '', 28153),
(144743, 'deDE', 'Wir werd\'n seh\'n. Passt auf diese Jahrhundertblüte auf, $p. Sie blüht nur einma\' alle hundert Jahre.', '', 28153),
(144742, 'deDE', '', 'Goldsamen! Die müss\'n wir sofort für den König anpflanz\'n! Was wohl daraus wachs\'n wird, Jahden?', 28153),
(144741, 'deDE', 'Die Schot\'n sin\' perfekt für meinen nächsten Topf extrascharfes Chili... und die gold\'nen Samen da schmeck\'n wie Dreck!', '', 28153),
(144740, 'deDE', '', 'Den gab es wirklich. Gibt es wirklich. Fräulein Luzilla ist entschlossen, unser Land und unsere Leute zu retten.', 28153),
(144739, 'deDE', 'In diesem Fall hat sie meine volle Unterstützung.', '', 28153),
(144738, 'deDE', 'Wirklich? Ich dachte, der wäre nur eine Legende!', '', 28153),
(144737, 'deDE', '', 'Ich bin jetzt Inquisitorin, Bürgermeister. Fräulein Luzilla hat den Glutorden für den Kampf gegen diese Hexen neu aufgestellt.', 28153),
(144736, 'deDE', 'Wir sind Euch zu tiefstem Dank dafür verpflichtet, dass Ihr uns zu Hilfe geeilt seid, Hauptmann.', '', 28153),
(144735, 'deDE', '', 'Danke, $p! Wir hatt\'n schon fast keine Ruhesteine mehr, Mann. Hier is\' \'ne Schote aufs Haus.', 28153),
(144734, 'deDE', 'Wollt Ihr was arbeit\'n, $p? Findet wen, der die Ruhesteine hier will. Tauscht sie geg\'n was echt Wertvolles un\' ich geb Euch \'ne gute Belohnung.', '', 28153),
(144733, 'deDE', 'Ihr wisst, was das heißt... jede Menge Bauholz!', '', 28153),
(144732, 'deDE', 'Äh, Boss...? Ich höre Berichte, dass sich eine Art riesiges Baummonster in den Wäldern herumtreibt.', '', 28153),
(144731, 'deDE', 'Krächz! Eure Mutter war ein Trogg! Krächz!', '', 28153),
(144730, 'deDE', 'Feige Landratten! KRÄCHZ!', '', 28153),
(144729, 'deDE', 'KRÄCHZ!', '', 28153),
(144728, 'deDE', 'Psst, $p. Wolltet Ihr schon immer mal jemand\'n ins Gesicht schlag\'n, aber wusstet, dass Ihr\'s nich\' tun könnt? Ich hab hier genau die Lösung!', '', 28153),
(144727, 'deDE', 'Aufregende Amulette! Kunstvolle Kuriosität\'n! Spezialangebote nur für schlaue Händler!', '', 28153),
(144726, 'deDE', 'Lauscht dem Flüstern. Wie wunderschön es ist.', 'Lauscht dem Flüstern. Wie wunderschön es ist.', 28153),
(144725, 'deDE', 'Die Schatten werden Euch verschlingen.', 'Die Schatten werden Euch verschlingen.', 28153),
(144724, 'deDE', 'Segen un\' Schreie sin\' total außer Mode! Nur Azerit kann Euch die Stärke geb\'n, die Ihr für diese gefährliche un\' beschwerliche Welt braucht. Trinkt heut\' noch Eure Dosis flüssiges Azerit!', '', 28153),
(144723, 'deDE', 'Euer Tod ist unvermeidlich.', 'Euer Tod ist unvermeidlich.', 28153),
(144722, 'deDE', 'MACHT, DASS ES AUFHÖRT!', 'MACHT, DASS ES AUFHÖRT!', 28153),
(144721, 'deDE', 'Die Finsternis naht...', 'Die Finsternis naht...', 28153),
(144720, 'deDE', 'Hätt Vol\'jin an der Verheert\'n Küste nur sein Totem der Unverwundbarkeit dabeigehabt, wär er jetz\' noch hier. Macht nich\' den gleich\'n Fehler!', '', 28153),
(144719, 'deDE', 'Spioniert Eure Feinde aus, haltet \'nen Blick auf Eure Freunde, lugt in die königlich\'n Gemächer... alles mit dem unglaublich\'n Totem der flüsternd\'n Irrwische!', '', 28153),
(144718, 'deDE', 'Die Flamme des Totems hier hat nie aufgehört zu brenn\', seit König Rastakhan zum erst\'n Mal auf seinem Thron gesess\'n hat. Holt Euch heut\' noch \'n Stück Zandalarigeschichte!', '', 28153),
(144717, 'deDE', 'Gaunahs Garantie: Wer nich\' fragt, kriegt satte Rabatte!', '', 28153),
(144716, 'deDE', 'T\'paartos ist hier!', '', 28153),
(144715, 'deDE', '', 'Ich fühle mich schon viel besser.', 28153),
(144714, 'deDE', 'T\'PAARTOS!', '', 28153),
(144713, 'deDE', '', 'Ihr könnt die Finsternis nicht ohne Krone besiegen. So sind die Regeln.', 28153),
(144712, 'deDE', '', 'Er schießt Sterne! Bösewichte vertragen das überhaupt nicht.', 28153),
(144711, 'deDE', 'Wir sind Hüter und Sammler des Wissens.\n\nEs ist meine Aufgabe, dafür zu sorgen, dass Entdeckungen ordnungsgemäß archiviert werden.', '', 28153),
(144706, 'deDE', 'Ich habe viel vorzubereiten. Kümmert Euch um sie.', 'Ich habe viel vorzubereiten. Kümmert Euch um sie.', 28153),
(144705, 'deDE', 'Ich habe genug von diesem Gewäsch.', 'Ich habe genug von diesem Gewäsch.', 28153),
(144704, 'deDE', 'Diese Stimme bietet nichts als Lügen!', '', 28153),
(144703, 'deDE', 'Spürt Ihr nicht die Großmächtige in der Tiefe? Ihr Wille wird unser Volk erneut einen!', 'Spürt Ihr nicht die Großmächtige in der Tiefe? Ihr Wille wird unser Volk erneut einen!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'deDE', 'Wir haben geschworen, Brennadam und unser Volk zu beschützen! Habt Ihr unseren Eid vergessen?', '', 28153),
(144701, 'deDE', 'Mit Eurer närrischen Fürsorge für Brennadam wart Ihr nie würdig, an Lord Sturmsangs Seite zu dienen.', 'Mit Eurer närrischen Fürsorge für Brennadam wart Ihr nie würdig, an Lord Sturmsangs Seite zu dienen.', 28153),
(144700, 'deDE', 'Ihr seid es, der verloren ist!', '', 28153),
(144699, 'deDE', 'Die See... möge Euch... verschlingen...', '', 28153),
(144698, 'deDE', 'Mein Leben... für... Azshara...', '', 28153),
(144697, 'deDE', 'Der Abgrund soll Euch mitreißen...', '', 28153),
(144696, 'deDE', 'Meine Königin... Ich habe versagt...', '', 28153),
(144695, 'deDE', 'Die Flut... geht zurück...', '', 28153),
(144694, 'deDE', '', 'Die Flut... geht zurück...', 28153),
(144693, 'deDE', '', 'Meine Königin... Ich habe versagt...', 28153),
(144692, 'deDE', '', 'Der Abgrund soll Euch mitreißen...', 28153),
(144691, 'deDE', '', 'Mein Leben für Azshara!', 28153),
(144690, 'deDE', '', 'Die See... möge Euch... verschlingen...', 28153),
(144689, 'deDE', 'Ich habe noch eine andere Frage...', 'Ich habe noch eine andere Frage...', 28153),
(144688, 'deDE', 'Sieht aus, als könntet Ihr einen Freund brauchen.', 'Sieht aus, als könntet Ihr einen Freund brauchen.', 28153),
(144687, 'deDE', 'Was macht Ihr?', 'Was macht Ihr?', 28153),
(144686, 'deDE', 'Ich möchte helfen, Kugro!', 'Ich möchte helfen, Kugro!', 28153),
(144685, 'deDE', 'Könntet Ihr vielleicht einen Blick auf diese Schriftrolle werfen?', 'Könntet Ihr vielleicht einen Blick auf diese Schriftrolle werfen?', 28153),
(144684, 'deDE', 'Spart Euch die Mühe, Kind.\n\nWas immer Ihr auch wollt, ich habe keine Zeit dafür.', '', 28153),
(144683, 'deDE', 'Freunde brauche ich nicht, aber Assistenten könnte ich schon brauchen, ja.', '', 28153),
(144682, 'deDE', 'Ich kann Euch sagen, was ich nicht mache: und zwar zulassen, dass $gein:eine:r; $R meine Zeit mit Schwätzchen vergeudet, wenn ich zu arbeiten habe.', '', 28153),
(144681, 'deDE', 'Dann hoffe ich, dass Ihr gut darin seid, mehrere Dinge gleichzeitig zu erledigen.', '', 28153),
(144680, 'deDE', 'Ich nehme derzeit keine Nebenprojekte an. Ich bin ohnehin schon im Rückstand. Diese Schriftrollen schreiben sich nicht von selbst, wisst Ihr?', '', 28153),
(144679, 'deDE', 'Es scheint, ich bin bankrott.', '', 28153),
(144678, 'deDE', '', '<Arluelle wirkt abwesend, als schaue sie in die Ferne.>$B$BWenn nur mein Bruder die Stadt jetzt sehen könnte...', 28153),
(144677, 'deDE', '', 'Etwas sagt mir, unsere Stadt wird bald benötigt. Ich werde bereit sein, wenn es so weit ist.', 28153),
(144676, 'deDE', 'Es ist schade, dass wir die Lichtgeschmiedeten nicht überzeugen konnten, sich uns anzuschließen. Sie beherrschen das Kriegshandwerk wie kaum ein anderes Volk.', '', 28153),
(144675, 'deDE', 'Verflucht, bei welcher Zahl war ich gerade? Argh!', '', 28153),
(144674, 'deDE', 'Es wird der Dämmerwache gut tun, Victoire wieder in ihren Reihen zu haben.', '', 28153),
(144673, 'deDE', '', 'Los geht\'s, Champion.', 28153),
(144672, 'deDE', 'Ich bin froh, dass Arluelle ihre Ausbildung fortsetzt, sie hat bereits Fortschritte gemacht.$B$BVielleicht sollte ich ihre Entwicklung genauer verfolgen.', '', 28153),
(144671, 'deDE', 'Die Gezeiten haben sich geändert, Bruder. Steht zu uns, oder Ihr seid verloren!', 'Die Gezeiten haben sich geändert, Bruder. Steht zu uns, oder Ihr seid verloren!', 28153),
(144670, 'deDE', 'Eins für Euch. Eins für mich.', '', 28153),
(144669, 'deDE', 'Nur frisierte Geschäftsbücher sehen richtig gut aus!', '', 28153),
(144668, 'deDE', 'Raik! Die Flotte muss umgehend nach Kul Tiras zurückkehren!', '', 28153),
(144667, 'deDE', 'Habe ich diesen Haufen schon gezählt?', '', 28153),
(144666, 'deDE', 'Ein... Zwei... Sieben... Rot... Zwei...', '', 28153),
(144665, 'deDE', '', 'Falls Ihr\'s noch nicht gemerkt habt: Ich bin ziemlich gut darin, Sachen in die Luft zu sprengen... und dreimal dürft ihr raten, wer gerade immer weiter hochrückt auf der Abschussliste!', 28153),
(144664, 'deDE', '', 'Macht so weiter, dann habt Ihr vielleicht einen klitzekleinen \"Unfall\".', 28153),
(144663, 'deDE', '', 'He! Das wird Euch teuer zu stehen kommen.', 28153),
(144662, 'deDE', '', 'Bis später, Keule.', 28153),
(144661, 'deDE', '', 'Wie? Das war\'s schon?', 28153),
(144660, 'deDE', '', 'Wir sehen uns.', 28153),
(144659, 'deDE', '', 'Was braucht Ihr, Kollege?', 28153),
(144658, 'deDE', '', 'Kann\'s losgehen?', 28153),
(144657, 'deDE', '', 'Was geht ab, Kumpel?', 28153),
(144656, 'deDE', 'Dass ich mir so was gefallen lassen muss...', '', 28153),
(144655, 'deDE', 'Jetzt im Ernst? Habt Ihr sie eigentlich noch alle? Immer wieder dieses piks piks piks piks piks?!', '', 28153),
(144654, 'deDE', 'Habt Ihr nix Besseres zu tun? Geht doch... \'n Murloc küssen oder so.', '', 28153),
(144653, 'deDE', 'He, ich verdiene mehr Respekt als das!', '', 28153),
(144652, 'deDE', 'Ja, ja... passt schon.', '', 28153),
(144651, 'deDE', 'Ah, endlich wieder Ruhe.', '', 28153),
(144650, 'deDE', 'Bis später.', '', 28153),
(144649, 'deDE', 'Ich bin kampfbreit.', '', 28153),
(144648, 'deDE', 'Ab die Post!', '', 28153),
(144647, 'deDE', 'Wenn Ihr mich weiter so anstupst, verliert Ihr den Finger.', '', 28153),
(144646, 'deDE', '<seufzt> ... und ich hatte grad so \'nen schönen Tag.', '', 28153),
(144645, 'deDE', 'Hallo, mein Name ist Flick, aber Ihr dürft mich gerne \"Sir\" nennen.', '', 28153),
(144644, 'deDE', 'Lieber viel zu viel als nicht genug.', '', 28153),
(144643, 'deDE', 'Ich liebe es, wenn ein Plan funktioniert.', '', 28153),
(144642, 'deDE', 'Bis später.', '', 28153),
(144641, 'deDE', 'Wie lautet der Plan?', '', 28153),
(144640, 'deDE', 'Was gibt\'s Neues?', '', 28153),
(144639, 'deDE', 'Was geht?', '', 28153),
(144638, 'deDE', 'Macht Ihr das gern? Heutzutage macht echt ma\' jeder, was er will.', '', 28153),
(144637, 'deDE', 'Wollt Ihr wissen, wo ich die ganz\'n Schädel her hab?', '', 28153),
(144636, 'deDE', 'Leider war der Name \"Pinkspeerstamm\" schon vergeb\'n.', '', 28153),
(144635, 'deDE', 'Ich hab mein\' Kopf verlor\'n. War etwa sooo groß. Ich hatt ihn auf mei\'m Speer. Sagt Bescheid, wenn Ihr ihn findet.', '', 28153),
(144634, 'deDE', 'Kommt wieder, wenn Ihr meine Hilfe braucht.', '', 28153),
(144633, 'deDE', 'Finger weg vom Voodoo, Mann.', '', 28153),
(144632, 'deDE', 'Bleibt immer wachsam.', '', 28153),
(144631, 'deDE', 'Was kann ich für Euch tun, Boss?', '', 28153),
(144630, 'deDE', 'Für die Dunkelspeere!', '', 28153),
(144629, 'deDE', 'Ich hör Euch, Mann.', '', 28153),
(144628, 'deDE', 'Nun gut... Ihr habt es so gewollt. Empfehle Neuerschaffung des gesamten Kosmos.', '', 28153),
(144627, 'deDE', 'Kontinuierliches Anstupsen beschleunigt die Systemleistung nicht.', '', 28153),
(144626, 'deDE', 'Markiere neues potenzielles Ziel für Eindämmung.', '', 28153),
(144625, 'deDE', 'Fehler. Bitte versucht es später NICHT noch einmal.', '', 28153),
(144624, 'deDE', 'Interaktion abgeschlossen.', '', 28153),
(144623, 'deDE', 'Setzte Eindämmungsprotokoll fort.', '', 28153),
(144622, 'deDE', 'Wiederhole Scans.', '', 28153),
(144621, 'deDE', '', 'Grüße, $p! Neue Länder und neue Verbündete erwarten uns überall in Azeroth.$B$BOculeth hat unten Portale vorbereitet, die Ihr benutzen könnt, sobald Ihr bereit seid.', 28153),
(144620, 'deDE', 'Verdernis entdeckt. Eindämmung um jeden Preis erforderlich.', '', 28153),
(144619, 'deDE', 'Prozess mit oberster Priorität: Eindämmung der Verderbnis.', '', 28153),
(144618, 'deDE', 'Einheit Hezrel aktiv. Aufgabe: Eindämmung der Verderbnis.', '', 28153),
(144617, 'deDE', '', 'Zeigt mal etwas Respekt vor dem Alter!', 28153),
(144616, 'deDE', '', 'Habt Ihr schon mal von der Tortollanerin gehört, die von einer Nervensäge so sehr auf die Palme getrieben wurde, dass sie ihr eine geklebt hat?', 28153),
(144614, 'deDE', '', 'Bald werd ich brummig.', 28153),
(144613, 'deDE', '', 'War\'s das?', 28153),
(144612, 'deDE', '', 'Stört nächstes Mal wen anders.', 28153),
(144611, 'deDE', '', 'Hat ja lange genug gedauert.', 28153),
(144610, 'deDE', '', 'Ürg. Was denn?', 28153),
(144609, 'deDE', '', 'Müsst Ihr unbedingt mit mir reden?', 28153),
(144608, 'deDE', '', 'Was wollt Ihr jetzt?', 28153),
(144605, 'deDE', 'Lasst mich ma\' in Ruh\'... bevor ich meine Schuld mit Eurer Seele begleich\'!', '', 28153),
(144604, 'deDE', 'Ich hab \'nen Rat für Euch: Geht nie \'nen Handel mit \'nem Todesloa ein!', '', 28153),
(144603, 'deDE', 'Verliert Eure Seele nich\'.', '', 28153),
(144602, 'deDE', 'Gebt auf Euch Acht.', '', 28153),
(144601, 'deDE', 'Passt auf Euch auf.', '', 28153),
(144600, 'deDE', 'Grüßt Euch, Fremdling.', '', 28153),
(144599, 'deDE', 'Was wollt Ihr von Hanzabu?', '', 28153),
(144598, 'deDE', 'Ich hab viel zu tun.', '', 28153),
(144597, 'deDE', 'Spart Euch Eure Unkenrufe!', '', 28153),
(144596, 'deDE', 'Müsst Ihr mir immer dazwischen quaken?', '', 28153),
(144595, 'deDE', 'Ich hüpf gleich im Dreieck!', '', 28153),
(144594, 'deDE', 'Hey, Küssen verboten, ist das klar?', '', 28153),
(144593, 'deDE', 'Bis zum nächsten Mal.', '', 28153),
(144592, 'deDE', 'Gebt Acht, bevor Ihr springt.', '', 28153),
(144591, 'deDE', 'Mögt Ihr stets fette Fliegen fangen.', '', 28153),
(144590, 'deDE', 'Sprecht.', '', 28153),
(144589, 'deDE', 'Ihr sprecht mit Krag\'wa?', '', 28153),
(144588, 'deDE', 'Ja, kleines Wesen?', '', 28153),
(144587, 'deDE', 'Wir seh\'n uns bald wieder. Sehr bald.', '', 28153),
(144586, 'deDE', 'Kusch! Verschwindet!', '', 28153),
(144585, 'deDE', 'Früher oder später... komm\' alle zu Bwonsamdi.', '', 28153),
(144584, 'deDE', 'Ihr seht \'n bisschen durstig aus. Wollt Ihr \'nen Drink? Wie wär\'s mit \'nem \"Zombie\"? Hahaha!', '', 28153),
(144583, 'deDE', 'Ich seh\' tote Leute. Is\' so \'n Hobby von mir.', '', 28153),
(144582, 'deDE', 'Da spielt aber jemand gern mit\'m Feuer...', '', 28153),
(144581, 'deDE', 'Sachte, Fremdling. Vergesst nich\', mit wem Ihr\'s zu tun habt.', '', 28153),
(144580, 'deDE', 'Hallo, hallo. Wollt Ihr \'nen Handel eingeh\'n?', '', 28153),
(144579, 'deDE', 'Was wollt Ihr vom Tod?', '', 28153),
(144578, 'deDE', 'Nun... was führt Euch zum alten, einsam\' Bwonsamdi?', '', 28153),
(144577, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(144576, 'deDE', 'Wir müssen diesem Wahnsinn ein Ende setzen, bevor es zu spät ist.', '', 28153),
(144575, 'deDE', '', 'Ich halte ihn fest, damit er nicht wieder verlorengeht.', 28153),
(144574, 'deDE', 'Direkt vor unserer Nase gestohlen! Die haben Nerven!', '', 28153),
(144573, 'deDE', 'Nein... das kann nicht sein! Laut meinen Kalkulationen sollte es...!', '', 28153),
(144572, 'deDE', 'Diese Ergebnisse sind verwirrend. Wenn diese kleinen... wie nennt Ihr sie? Bartlinge... nur nicht meine Konzentration stören würden!', '', 28153),
(144571, 'deDE', 'Ich muss es noch einmal versuchen. Gute Arbeit! Obwohl ich erwartet hätte, dass unsere Gegner etwas größer sind!', '', 28153),
(144570, 'deDE', 'Ich vertraue darauf, dass Ihr mögliche Unterbrechungen handhabt, ja?', '', 28153),
(144569, 'deDE', 'Hier entlang! Sobald ich mit dem Hellsehen beginne, muss ich meine ganze Aufmerksamkeit darauf konzentrieren.', '', 28153),
(144567, 'deDE', '', 'Nuu ist hier, um uns zu helfen! Ich wusste, du würdest uns finden, Nuu.', 28153),
(144566, 'deDE', 'Die Aquädukte sind schwer beschädigt und immer noch voll instabiler Energien. Das Tor bleibt daher vorläufig geschlossen.', 'Die Aquädukte sind schwer beschädigt und immer noch voll instabiler Energien. Das Tor bleibt daher vorläufig geschlossen.', 28153),
(144565, 'deDE', 'Ich passe auf ihn auf. Er scheint gern in den Gärten umherzustreifen.', 'Ich passe auf ihn auf. Er scheint gern in den Gärten umherzustreifen.', 28153),
(144564, 'deDE', '', 'Sehr gut! Ich bin beeindruckt!', 28153),
(144563, 'deDE', '', 'Chienergie auf ein Ziel zu lenken, kann anfangs schwierig sein. \n\nIhr da vorn, versucht, die Trainingsattrappe da drüben zu treffen.', 28153),
(144562, 'deDE', 'Psst, $PR... Wollt Ihr was kauf\'n?', '', 28153),
(144561, 'deDE', 'Was habt Ihr denn da, $p? Ist das eine Jahrhundertblüte?', '', 28153),
(144560, 'deDE', '', 'Wir müss\'n uns auf die nächste Pflanzzeit vorbereit\'n, Jahden.', 28153),
(144559, 'deDE', 'Hm... Dem Chili fehlt was... Das braucht \'n bisschen Hitze.', '', 28153),
(144558, 'deDE', '', 'Zancha! Habt Ihr schon wieder vergess\'n, die Ruhesteine aufzufüll\'n?', 28153),
(144557, 'deDE', 'Tschüüüüüüüss!', '', 28153),
(144556, 'deDE', 'Einfach schwimmen.', '', 28153),
(144555, 'deDE', 'Wasser ist toll. Ich mag Wasser. Mögt Ihr Wasser? Was mögt Ihr am liebsten am Wasser? Ich mag, wie nass es ist. Wasser ist wirklich toll, findet Ihr nicht auch?', '', 28153),
(144554, 'deDE', 'Meine Mama sagt, wir sind amfibrich... amphlibich... AMPHIBISCH! Endlich hab ich\'s!', '', 28153),
(144553, 'deDE', 'Hey, jetzt komm\' die Tortollaner,\nsuperstarke Tortollaner,\njeder kennt die Tortollaner.\nImmer auf der Lauer.', '', 28153),
(144552, 'deDE', 'Wenn ich groß bin, les ich ALLES, was es gibt!', '', 28153),
(144551, 'deDE', 'Wie tragt Ihr Sachen ohne Panzer mit Euch rum?', '', 28153),
(144550, 'deDE', 'Ich lieg gern auf dem Rücken.', '', 28153),
(144549, 'deDE', 'Bald bin ich genauso alt wie Ihr!', '', 28153),
(144548, 'deDE', 'Na schön, geht schon. Ich war sowieso fertig.', '', 28153),
(144547, 'deDE', 'Nicht alles im Ozean hat mein umwerfendes Aussehen oder meine guten Manieren.', '', 28153),
(144546, 'deDE', 'Wenn Ihr etwas Exotisches findet, bringt es mir.', '', 28153),
(144545, 'deDE', 'Kommt wieder mit besseren Geschichten.', '', 28153),
(144544, 'deDE', 'Ich habe Sachen gesehen, da würde Euch der Panzer wegfliegen.', '', 28153),
(144543, 'deDE', 'Tretet näher, und bloß nicht nuscheln.', '', 28153),
(144542, 'deDE', 'Guten Tag, werter Herr oder werte Dame.', '', 28153),
(144541, 'deDE', 'Habt Ihr was Antikes zum Tauschen? Aber es muss mindestens zweihundert Jahre alt sein.', '', 28153),
(144540, 'deDE', '', 'Hallo, hier spielt die Musik!', 28153),
(144539, 'deDE', '', 'Tschüss.', 28153),
(144538, 'deDE', '', 'Un\' einmal, im Feldlager, da hab ich \'n Alpaka gemopst und zum Tempel gebracht, aber Mutta hat\'s mich nich\' behalt\'n lass\'n.', 28153),
(144537, 'deDE', '', 'Un\' einmal, im Feldlager, da hab ich \'nen Abenteurer vermöbelt und ihm den Schädel abgenomm\'n. Der war stärker als Ihr...', 28153),
(144536, 'deDE', '', 'Un\' einmal, im Feldlager, hab ich \'n Brutosaurus am Schwanz geschnappt. Hat mich dreiunddreißig\'nhalb Meter geschleppt.', 28153),
(144535, 'deDE', 'Ein boshafter Albatros fliegt im Sturzflug auf das schlüpfende Ei zu.', '', 28153),
(144534, 'deDE', '', 'Un\' einmal, im Feldlager, da hab ich \'nen Saurid gefang\'. Der war echt voll riesengroß. Die ham gesagt, is\' \'n Ravasaurus, aber die Erwachs\'nen ham bestimmt geflunkert.', 28153),
(144533, 'deDE', '', 'Un\' einmal, im Feldlager, da hab ich sooo \'nen groß\'n Fisch gefang\'. War aber doch nur \'ne verhexte Wache.', 28153),
(144532, 'deDE', '', 'Taz\'okun!', 28153),
(144531, 'deDE', '', 'Taz\'dingo!', 28153),
(144530, 'deDE', '', 'Mein Loa haut Euern Loa in die Pfanne!', 28153),
(144529, 'deDE', '', 'Irgendwann werd\' ich ein Loa sein!', 28153),
(144528, 'deDE', 'Winke, winke.', '', 28153),
(144527, 'deDE', 'Wohin geht\'s?', '', 28153),
(144526, 'deDE', 'Loas sin\' sooo toll. Die ganz dicken machen Happs un\' weg seid Ihr!', '', 28153),
(144525, 'deDE', 'Wenn ich groß bin, werd\' ich\'n Brutosaurusdruide. Grrr!', '', 28153),
(144524, 'deDE', 'Ich hab zehn Zeh\'n... aber nur vier sind meine.', '', 28153),
(144523, 'deDE', 'So ein Doofie hat meine Schrumpfkopfkiste geklaut. Wart Ihr das?', '', 28153),
(144522, 'deDE', 'Huhu.', '', 28153),
(144521, 'deDE', 'Taz\'okun!', '', 28153),
(144520, 'deDE', 'Taz\'dingo!', '', 28153),
(144519, 'deDE', 'Grrr!', '', 28153),
(144518, 'deDE', 'Die Loa sin\' stark hier.', 'Die Loa sin\' stark hier.', 28153),
(144517, 'deDE', 'Geht mit den Geistern.', 'Geht mit den Geistern.', 28153),
(144516, 'deDE', 'Die Loa seh\'n alles.', 'Die Loa seh\'n alles.', 28153),
(144515, 'deDE', 'Pah! Hier, schluckt zwei von denen und kommt morgen wieder.', 'Pah! Hier, schluckt zwei von denen und kommt morgen wieder.', 28153),
(144513, 'deDE', 'Ihr fordert echt Euer Glück raus, Mann.', 'Ihr fordert echt Euer Glück raus, Mann.', 28153),
(144512, 'deDE', 'Hier gibt\'s nur das beste Juju, Mann.', 'Hier gibt\'s nur das beste Juju, Mann.', 28153),
(144511, 'deDE', 'Die Geister flüstern von Euch.', 'Die Geister flüstern von Euch.', 28153),
(144510, 'deDE', 'Wer ist denn Euer Loa?', 'Wer ist denn Euer Loa?', 28153),
(144509, 'deDE', '', 'Rückt aus! Für die Zukunft von Zandalar!', 28153),
(144508, 'deDE', 'Das sind jetzt keine idealen Umstände, um sich kennenzulernen... Ich sollte schnell zurückkehren, sonst wird Kugro gar nicht begeistert sein.', '', 28153),
(144498, 'deDE', 'Zandalar is\' immer da.', 'Zandalar is\' immer da.', 28153),
(144497, 'deDE', 'Beugt Euch nie den Schwachen.', '', 28153),
(144496, 'deDE', 'Fügt Euren Feinden tiefe Wunden zu.', '', 28153),
(144495, 'deDE', 'Mögt Ihr das Fleisch Eurer Feinde kosten.', '', 28153),
(144494, 'deDE', 'Was wollt Ihr, Kind der Horde?', '', 28153),
(144493, 'deDE', 'Ihr streift durch mein Land.', '', 28153),
(144492, 'deDE', 'Seid Ihr ein Raubtier... oder Beute?', '', 28153),
(144491, 'deDE', 'Kommt Ihr, um zu verhandeln?', '', 28153),
(144490, 'deDE', 'Erzählt den anderen von mir!', '', 28153),
(144489, 'deDE', 'Mögen Euch Eure Feinde niemals wittern.', '', 28153),
(144488, 'deDE', 'Bringt Eurem Rudel Stärke.', '', 28153),
(144486, 'deDE', 'Wenn Ihr weglaufen wollt, denkt immer daran... ich weiß, wie man Türen öffnet.', '', 28153),
(144484, 'deDE', 'Weiter so, dann werdet Ihr mein nächstes Beutetier.', '', 28153),
(144481, 'deDE', 'Ich bin der Meister der Formen, der Rudelläufer und der Herr der Jagd.', '', 28153),
(144480, 'deDE', 'Was führt EUCH zum Herrn der Jagd?', '', 28153),
(144479, 'deDE', 'Kommt Ihr, um zu verhandeln?', '', 28153),
(144478, 'deDE', '', 'Auf günstige Winde... und dass sie Euch weit wegtragen.', 28153),
(144477, 'deDE', '', 'Denkt daran, der Himmel gehört mir.', 28153),
(144476, 'deDE', '', 'Möget Ihr den Tod herabregnen lassen.', 28153),
(144475, 'deDE', '', 'Der Wind ist mein Wille.', 28153),
(144474, 'deDE', '', 'Ich steige mit Euch hoch... und lasse Euch auf einen Felsen stürzen!', 28153),
(144473, 'deDE', '', 'Wollt Ihr meinen Zorn herausfordern?', 28153),
(144472, 'deDE', '', 'Ihr strapaziert meine Nerven, Jüngling.', 28153),
(144471, 'deDE', '', 'Warum muss ich Eure Luft atmen?', 28153),
(144470, 'deDE', '', 'Was braucht Ihr, Kind?', 28153),
(144469, 'deDE', '', 'Kommt Ihr, um zu verhandeln?', 28153),
(144468, 'deDE', '', 'Psst, $PR... Habt Ihr genug davon, hier wie \'n Saurid rumzulauf\'n? Mein Mojo lässt Euch wie \'n Teufelssaurier ausseh\'n!', 28153),
(144462, 'deDE', '', 'Wählt Euern Loa mit Bedacht.', 28153),
(144461, 'deDE', '', 'Auf dass Ihr immer Eure Feinde erschnüff\'ln könnt.', 28153),
(144460, 'deDE', '', 'Für das Rudel.', 28153),
(144459, 'deDE', '', 'Lasst Euch nich\' zähmen.', 28153),
(144458, 'deDE', '', 'Lasst das Tier raus, Mann.', 28153),
(144457, 'deDE', '', 'Bleibt in der Nähe. Vielleicht nehm\' ich Eure Dienste später nochmal in Anspruch.', 28153),
(144456, 'deDE', '', 'Aaaaaaaaah, das hab ich gebraucht.', 28153),
(144455, 'deDE', '', 'Also, immer weiter so.', 28153),
(144454, 'deDE', '', 'Wenn Ihr so weitermacht, wird mein Mann noch ganz eifersüchtig.', 28153),
(144453, 'deDE', '', 'Schon ma\' das Tier rausgelassen?', 28153),
(144452, 'deDE', 'Zeit, die Sache selbst in die Hand zu nehmen. Ihr werdet mir die Operation nicht vermasseln!', '', 28153),
(144451, 'deDE', 'Vielen Dank, $n. Kugro war offenbar fleißig. Was... mache ich denn jetzt mit diesen ganzen Schriftrollen?', '', 28153),
(144450, 'deDE', '', 'Die Macht der Loa is\' stark hier.', 28153),
(144449, 'deDE', '', 'In dieser Form traut Ihr Euch unter Leute?', 28153),
(144448, 'deDE', 'Ihr seid nicht meine Kontaktperson! Rein hier, Männer, es gibt Frischfleisch!', '', 28153),
(144447, 'deDE', '', 'Ich diene Gonk, dem Meister der Formen.', 28153),
(144446, 'deDE', '<Gebt Itokka die Schriftrollen.>', '<Gebt Itokka die Schriftrollen.>', 28153),
(144445, 'deDE', '', 'Ich wünschte, Nuu wäre hier. Er wüsste, was zu tun ist.', 28153),
(144444, 'deDE', '', 'Oh, hallo! Wer seid Ihr? Ich bin Uuna. Wollt Ihr mein Freund sein? Vielleicht finden wir gemeinsam hier raus.', 28153),
(144443, 'deDE', 'Hey! Ich hab genau das Richtige für Euch. Zuls höchsteigensten Sauridenzauberschutz! Hält Euch die diebisch\'n Viecher vom Leib!', '', 28153),
(144442, 'deDE', '', 'Es ist zu hell! Zu hell! Aua!', 28153),
(144441, 'deDE', 'Seid gesegnet, $gReisender:Reisende;.\n\nLegt Eure Waffe ab und ruht Euch ein wenig aus.\n\nDer Krieg läuft Euch nicht weg.', '', 28153),
(144440, 'deDE', 'Ich grüß Euch, Pakura\'ai!', '', 28153),
(144439, 'deDE', 'Wählt Euern Loa mit Bedacht.', '', 28153),
(144438, 'deDE', 'Mit den weisen Wort\'n meines Loas: Geht endlich weg!', '', 28153),
(144437, 'deDE', 'Möge Pa\'ku Eure Feinde find\'n, bevor die Euch find\'n.', '', 28153),
(144436, 'deDE', 'Mög\'n die Kriegswinde immer günstig für Euch steh\'n.', '', 28153),
(144435, 'deDE', 'Perfekt! Genau das hab ich gebraucht.', '', 28153),
(144434, 'deDE', 'Oh ja, genau so... nur\'n kleines Stückchen mehr rechts...', '', 28153),
(144433, 'deDE', 'Wenn mir meine Frau doch auch nur so viel Aufmerksamkeit schenken würde wie Ihr...', '', 28153),
(144432, 'deDE', 'Mit den weisen Wort\'n meines Loas: Finger weg!', '', 28153),
(144431, 'deDE', 'Mit den weisen Wort\'n meines Loas: Ducken! Hahahaha!', '', 28153),
(144430, 'deDE', 'Macht die Saurier ma\' nie sauer.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144429, 'deDE', 'Die Himmel sin\' meine Aug\'n.', '', 28153),
(144428, 'deDE', 'Ich dien Pa\'ku, einem von den ältesten Loa.', '', 28153),
(144427, 'deDE', '', 'Ich kämpf\' für die, die sich nicht selbst schütz\'n können.', 28153),
(144425, 'deDE', 'Wir haben alle unsre Roll\'n zu spiel\'n – sogar Ihr.', '', 28153),
(144424, 'deDE', 'Ich hab viele große Ereignisse unsrer Zeit geseh\'n. Und immer wart Ihr dabei. Interessant.', '', 28153),
(144423, 'deDE', 'Finst\'re Zeiten brech\'n an!', '', 28153),
(144422, 'deDE', 'Das is\' finster, Mann. Echt finster.', '', 28153),
(144421, 'deDE', 'Das Trollimperium wird sich wieder erheben. Ich hab\'s geseh\'n.', '', 28153),
(144420, 'deDE', 'Die Trolle war\'n die ersten, die über die Welt geherrscht ham, und sie werd\'n auch die letzten sein.', '', 28153),
(144419, 'deDE', 'Das Schicksal meint\'s echt nich\' gut mit Euch.', '', 28153),
(144418, 'deDE', 'Ich hab vorhergeseh\'n, was Ihr sagen werdet, also macht schon hin.', '', 28153),
(144417, 'deDE', 'Ich hab geseh\'n, wie diese Welt endet, und es wird Euch nich\' gefall\'n.', '', 28153),
(144416, 'deDE', '', 'Zandalar is\' immer da.', 28153),
(144415, 'deDE', '', 'Rache für die Gefall\'nen.', 28153),
(144414, 'deDE', '', 'Auf dass die Schädel Eurer Feinde Eure Kleider schmück\'n.', 28153),
(144413, 'deDE', '', 'Zeiten ändern sich, die Zandalari müss\'n sich mitändern.', 28153),
(144412, 'deDE', '', 'Viel zu tun. Macht\'s kurz.', 28153),
(144411, 'deDE', 'Mög\'n Eure Feinde vor Euch zittern.', '', 28153),
(144410, 'deDE', 'Zandalar für immer!', '', 28153),
(144409, 'deDE', 'Rezan verleih\' Euch Stärke.', '', 28153),
(144408, 'deDE', 'Es is\' gut, der König zu sein.', '', 28153),
(144407, 'deDE', 'Ihr steht vor König Rastakhan.', '', 28153),
(144406, 'deDE', 'Willkommen in Zuldazar.', '', 28153),
(144405, 'deDE', 'Seid Ihr \'n Raubtier... oder Beute?', '', 28153),
(144404, 'deDE', '', 'Ich wünschte, ich könnte besser sehen, es ist so finster hier!', 28153),
(144403, 'deDE', '', 'Aber Ihr seid mein Freund und ich weiß, alles wird wieder gut.', 28153),
(144402, 'deDE', '', 'Aber zumindest haben wir uns, stimmt\'s? Wir... wissen nur nicht, wo wir sind.', 28153),
(144401, 'deDE', '', 'Hilfe! HILFE!', 28153),
(144400, 'deDE', '', 'Wer seid Ihr? Könnt Ihr mir helfen?', 28153),
(144399, 'deDE', '', 'Es ist so dunkel! Ich kann nichts sehen!', 28153),
(144397, 'deDE', '', 'Die Angelegenheit mit Elisande ist vorbei, aber es gibt noch viel zu tun für die Stadt.', 28153),
(144396, 'deDE', '', 'Die Nachtgeborenen sind wirklich frei. Wir brauchen den Nachtbrunnen und seine Macht nicht mehr.$b$bWir sind unseres eigenen Glückes Schmied.', 28153),
(144395, 'deDE', 'Ich habe Proben mitgebracht, um die grundlosen Gerüchte zu zerstreuen, dass unser Wein zu sehr nach Füßen... äh, zu süß schmeckt.', '', 28153),
(144394, 'deDE', 'Einige unserer Winzer haben den Weinanbau aufgegeben und geben sich nun anderen Formen der Botanik hin.', '', 28153),
(144393, 'deDE', 'Jo, die Bluttrolle ham sich mit den Wachen gehau\'n, als wir ankam\'. Ham nich\' erwartet, dass wir ihnen in den Rück\'n fall\'n.', '', 28153),
(144392, 'deDE', 'Hoppla, der ist groß. Ich werde Eure Hilfe brauchen, um ihn zu erledigen!', '', 28153),
(144391, 'deDE', 'Wenn Ihr eine Gruppe von ihnen seht, dann werft eine dieser Stachelbomben hinein und lasst sie mal spüren, wie schön das ist!', '', 28153),
(144390, 'deDE', 'Das hat bestimmt ordentlich wehgetan! Verschwindet von meinem Land!', '', 28153),
(144389, 'deDE', 'Ha, genau zwischen die Augen!', '', 28153),
(144388, 'deDE', 'Ihr könnt gehen und Rosen sagen, dass es mir gut geht, ich aber meinen Hof nie verlassen werde. Ich werde sie nicht zurücklassen.', '', 28153),
(144387, 'deDE', 'Ja, das sollte gehen. Dieses Plätzchen haben sie immer gemocht...', '', 28153),
(144386, 'deDE', 'Ihr könnt das Portal von Orgrimmar benutzen, um Euch mit unseren Verbündeten der Horde in ihrer Hauptstadt auf Kalimdor zu treffen.', '', 28153),
(144385, 'deDE', '', 'Rokhan! Geht\'s Euch gut? Sieht aus, als hätt hier \'n Kampf stattgefund\'n.', 28153),
(144384, 'deDE', 'Ich habe gehört, dass Dalaran eine ganze Etage nur für magische Transportationen unterhält. $B$BStellt Euch nur vor, welche Möglichkeiten das bietet!', '', 28153),
(144383, 'deDE', 'Es ist unglaublich lästig, diese Portale aufrecht zu erhalten und was wichtiger ist: Sie halten mich ab von meiner wertvollen Forschung!$B$BIch bin mir sicher, dass Telemantie eine stabilere Lösung bietet.', '', 28153),
(144382, 'deDE', 'Wer behauptet, Goblins hätten keine Kultur?', '', 28153),
(144381, 'deDE', 'Sie haben sogar eine von unseren Trommeln!', '', 28153),
(144380, 'deDE', '... und sucht Euch \'ne freie Trommel!', '', 28153),
(144379, 'deDE', 'Willkommen im Betrunkenen Trommler, $PR! Nehmt Euch was zu trink\'n...', '', 28153),
(144378, 'deDE', 'Argh! Un\' ich dachte, mein Plan sei idiotensicher, Mann!', '', 28153),
(144377, 'deDE', 'Narr! Ihr werdet dafür zahl\'n, dass Ihr Euch unter meine Brücke wagt!', '', 28153),
(144376, 'deDE', 'He, Mann! Ihr überquert da meine Brücke, Mann. Zahlt dem Troll den Zoll, Mann, oder Ihr werdet in Blut zahl\'n, Mann!', '', 28153),
(144375, 'deDE', 'Ich bin bereit, mit der Prüfung zu beginnen.', 'Ich bin bereit, mit der Prüfung zu beginnen.', 28153),
(144374, 'deDE', '', 'Warum binden wir ihnen nicht ein bisschen Sprengstoff um? Das wäre doch urkomisch... Explodierende Dinosaurier!', 28153),
(144373, 'deDE', '', 'Ich weiß Euren Enthusiasmus zu schätzen, Shuga, aber ich bin mir sicher, dass die Zandalari ihre Waffen lieber mit mächtiger Magie verzaubert und nicht mit Schmiere verschandelt haben wollen.', 28153),
(144372, 'deDE', 'Was... Was ist aus uns geworden?', '', 28153),
(144371, 'deDE', '', 'Nein! Lasst mich los! Hilfe! Held! Bitte helft mir!', 28153),
(144370, 'deDE', '', 'Es ist wieder dunkel! Wo seid Ihr? Bitte, lasst mich nicht zurück!', 28153),
(144369, 'deDE', '', 'Ich hatte auch einmal so einen Zauberstab! Aber ich habe ihn vor langer Zeit verloren.', 28153),
(144368, 'deDE', '', 'Eine Krone! Oh, wie hübsch!', 28153),
(144367, 'deDE', '', 'Nuu-Nuu! Ich hatte Angst, ich würde dich nie wiedersehen! Wie bist du hierhergekommen?', 28153),
(144366, 'deDE', '', 'Es wird heller! Ich kann sehen... einigermaßen.', 28153),
(144365, 'deDE', '', 'Was ist das? Ein Licht in der Finsternis! Es ist so hell...', 28153),
(144364, 'deDE', 'Sie... hat es versprochen...', '', 28153),
(144363, 'deDE', 'Mir wurde gesagt, so könnten wir zusammen sein!', '', 28153),
(144362, 'deDE', '', 'Mit den Loa an unsrer Seite un\' Mut in unsern Herzen werden wir siegreich sein!', 28153),
(144361, 'deDE', '', 'Wir werden den Bluttrollen den Garaus mach\'n. Wir werden sicherstell\'n, dass ihr Monster niemals geg\'n uns eingesetzt wird!', 28153),
(144360, 'deDE', '', 'Unsre Feinde woll\'n alles, was uns lieb un\' teuer is\', vernicht\'n. Wir dürf\'n das nich\' zulassen. Zandalars Zukunft hängt von unsren Taten am heutigen Tag ab.', 28153),
(144359, 'deDE', '', 'Soldat\'n, Freunde, wir hab\'n viel durchgemacht, aber ein Ende von unserm Kampf is\' in Sicht.', 28153),
(144358, 'deDE', 'Wohin kann ich mit der Fähre fahren?', 'Wohin kann ich mit der Fähre fahren?', 28153),
(144357, 'deDE', 'Sucht Ihr nach einer Fähre?', 'Sucht Ihr nach einer Fähre?', 28153),
(144356, 'deDE', '', 'Gut, dass ich meine Stiefel trage!', 28153),
(144355, 'deDE', 'Ich nehm ein paar Tortollaner und geh zu Fuß nach Zul\'jan. Viel Glück Euch beid\'n.', '', 28153),
(144354, 'deDE', 'Ich lebe... und sterbe... für die Horde!', 'Ich lebe... und sterbe... für die Horde!', 28153),
(144353, 'deDE', 'Blut und Donner!', 'Blut und Donner!', 28153),
(144352, 'deDE', 'Arathi gehört der Horde!', 'Arathi gehört der Horde!', 28153),
(144351, 'deDE', 'Folgt mir!', 'Folgt mir!', 28153),
(144350, 'deDE', 'Tod der Allianz!', 'Tod der Allianz!', 28153),
(144349, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(144348, 'deDE', 'Da entlang! In den Kampf!', 'Da entlang! In den Kampf!', 28153),
(144347, 'deDE', 'Los schon, Grunzer! Wir müssen diesen Krieg gewinnen!', 'Los schon, Grunzer! Wir müssen diesen Krieg gewinnen!', 28153),
(144346, 'deDE', 'Ich bin Gral!', '', 28153),
(144345, 'deDE', 'Im Süden werdet Ihr die Überreste meines Tempels finden. Dort werde ich Euch treffen und wir werden diesen Naga den Zorn eines Hailoas zeigen!', '', 28153),
(144344, 'deDE', 'Oh... Ihr wart köstlich.', '', 28153),
(144343, 'deDE', 'Keine Tiefen sind dunkel genug für Euch!', '', 28153),
(144342, 'deDE', 'Naga sind in Atal\'Gral nicht willkommen!', '', 28153),
(144341, 'deDE', 'Der köstlich scharfe Geruch von mit Wut erfülltem Nagablut... die süßen, zarten Happen... Da werde ich beiwohnen.', '', 28153),
(144340, 'deDE', '', 'Mutter, Benjamin hat mir alles erzählt.\n\nDu konntest mich vorher nicht hören. Aber vielleicht jetzt? Ich wollte doch nur eine Erklärung.', 28153),
(144339, 'deDE', '', 'Mutter, ich weiß, dass du nicht hier bist. Aber wenn du mich hören kannst...', 28153),
(144338, 'deDE', 'Ich bin vielleicht nicht der beste Verwalter, aber Mutter war unglaublich. Sie so tief fallen zu sehen...$b$bWir kommen schon klar, $n. Danke für Eure Hilfe.', '', 28153),
(144337, 'deDE', '', 'Wo geht Ihr hin?', 28153),
(144336, 'deDE', '', 'Bitte, lasst mich nicht alleine.', 28153),
(144335, 'deDE', 'Unsere Herrin unter dem Meer wird uns zum Sieg führen.', 'Unsere Herrin unter dem Meer wird uns zum Sieg führen.', 28153),
(144334, 'deDE', 'Schön, dass Ihr es alle heil zurück geschafft habt. Alles dank... hey, da ist ja unsere Frau der Stunde.', '', 28153),
(144333, 'deDE', 'Bleibt Ihr oder geht Ihr?', '', 28153),
(144332, 'deDE', 'Bitte entschuldigt mich. Ich muss meine Schwester finden.', '', 28153),
(144331, 'deDE', 'Als unser Vater starb, ist unsere Mutter verschwunden. Aber ich hätte nie gedacht...', '', 28153),
(144330, 'deDE', 'Sie und mein Vater haben ihr ganzes Leben lang gearbeitet, um dieses Geschäft aufzubauen und für mich und meine Schwester zu sorgen.', '', 28153),
(144329, 'deDE', 'Diese Hexe... Das war meine Mutter.', '', 28153),
(144328, 'deDE', 'Ihr seht aus, als würdet Ihr Euch mit Tieren auskennen. Was braucht Ihr denn?', '', 28153),
(144327, 'deDE', 'Was ist denn nun? Habt Ihr etwas verloren?', '', 28153),
(144326, 'deDE', 'Hervorragend! Noch einmal von vorn.', '', 28153),
(144325, 'deDE', 'Zuviel Energie auf einmal einzusetzen, ist gefährlich. Mäßigt Euch, Schüler.', '', 28153),
(144324, 'deDE', 'Konzentriertes Chi ist sehr mächtig. Meister Tau Li wird Euch leiten, wenn Ihr bereit dafür seid.', '', 28153),
(144323, 'deDE', 'Beim Heilen müsst Ihr Eure innere Stärke sammeln und sie an jemand anderen weitergeben.', '', 28153),
(144322, 'deDE', 'Ich bin froh, dass ich nicht MEINE SEELE geben musste.', 'Ich bin froh, dass ich nicht MEINE SEELE geben musste.', 28153),
(144321, 'deDE', 'Unsere verderbten Brüder und Schwestern irren noch immer in der Wildnis umher.', 'Unsere verderbten Brüder und Schwestern irren noch immer in der Wildnis umher.', 28153),
(144320, 'deDE', '', 'Mein Leben... für die Horde.', 28153),
(144319, 'deDE', '', 'Auf bald.', 28153),
(144318, 'deDE', '', 'Blut und Donner!', 28153),
(144317, 'deDE', '', 'Ich werde Euch niedermähen.', 28153),
(144316, 'deDE', '', 'Meine Klinge sehnt sich nach Eurem Fleisch.', 28153),
(144315, 'deDE', '', 'Ihr habt einer Orcfrau nichts entgegenzusetzen!', 28153),
(144314, 'deDE', '', 'Eure Knochen sind meiner Klinge nicht gewachsen!', 28153),
(144313, 'deDE', '', 'Haltet die Linie! Es darf keiner durchkommen!', 28153),
(144312, 'deDE', 'Habt Dank.', '', 28153),
(144311, 'deDE', 'Falls ich Euch bei unserem nächsten Treffen nicht wiedererkennen sollte, tut es mir leid.', '', 28153),
(144310, 'deDE', 'Ich danke Euch für Eure Hilfe mit Torok. Er weigerte sich, zu erkennen wie gefährlich die Macht war, die er suchte.', 'Ich danke Euch für Eure Hilfe mit Torok. Er weigerte sich, zu erkennen wie gefährlich die Macht war, die er suchte.', 28153),
(144309, 'deDE', '<Der schlafende Tauren schnarcht vernehmlich und dreht sich zur Seite.>', '<Der schlafende Tauren schnarcht vernehmlich und dreht sich zur Seite.>', 28153),
(144308, 'deDE', 'ZZZzzz...', 'ZZZzzz...', 28153),
(144307, 'deDE', 'Ich mach mit, Prinzessin. Bis zum bitt\'ren Ende.', '', 28153),
(144306, 'deDE', '', 'Das is\' der einzige Weg, um mein Volk zu rett\'n, Rokhan. Ich würd alles aufgeb\'n für ihre Sicherheit. Helft Ihr mir?', 28153),
(144305, 'deDE', 'Ich kann immer noch nicht fassen, dass meine Brüder und Schwestern der Teufelsmacht erlegen sind.', 'Ich kann immer noch nicht fassen, dass meine Brüder und Schwestern der Teufelsmacht erlegen sind.', 28153),
(144304, 'deDE', '', 'So geh\'n wir mit Gästen um, Töchter!', 28153),
(144303, 'deDE', '', 'Das Blut... wird mich... räch\'n...', 28153),
(144302, 'deDE', '', 'Für die Kriegsmatronen!', 28153),
(144301, 'deDE', 'Nun konzentriert Euch. Schleudert das Chi fort von Euch.', '', 28153),
(144300, 'deDE', '', 'Eure Essenz wird von außen dien\'!', 28153),
(144299, 'deDE', '', 'Das Aussaugen wird mir Spaß mach\'n.', 28153),
(144298, 'deDE', '', 'Euer Blut is\' unsere Kraft!', 28153),
(144297, 'deDE', '', 'Ich nehm\' Euer Blut. Der Rest kann verrotten!', 28153),
(144296, 'deDE', '', 'Ich tauch meine Klinge in Euer Blut.', 28153),
(144295, 'deDE', 'Wenn Ihr einen Transport benötigt, wisst Ihr ja, wo Ihr mich findet!', '', 28153),
(144294, 'deDE', '', 'Blut für die Sängerinnen!', 28153),
(144293, 'deDE', '', 'Eure Haut wird gutes Zaumzeug abgeb\'n.', 28153),
(144292, 'deDE', '', 'Der Himmel... ruft.', 28153),
(144291, 'deDE', '', 'Ein wundervoller Tag für eine Schlacht.', 28153),
(144290, 'deDE', '', 'Die Kroggs werd\'n sich satt fress\'n heut Abend!', 28153),
(144289, 'deDE', 'Bleibt stark! Ich schau nach Satao.', '', 28153),
(144288, 'deDE', 'EINTRAG - Das Schleimexperiment\n\nDas Beleben der Schleime war erfolgreich. Anstatt organisches Material wie Fleisch oder Pflanzen aufzulösen, können sie sich ausschließlich von Honig ernähren. Die hohe Menge an Ausscheidungen kann in Fässern vergoren werden, um besonders starken und köstlichen Met herzustellen.\n\nWenn man die Schleime jedoch nicht entsprechend kontrolliert, suchen sie sich früher oder später ganze Bienenstöcke und verschlingen sie. Dabei werden sie tendenziell aggressiver und sind nicht mehr zu beherrschen.\n\nAls Reaktion darauf sind die Bienen natürlich wehrhafter geworden, was die Arbeit mit ihnen erschwert. Dafür muss ich offenbar eine Lösung finden, da die Bienen nicht leicht zu ersetzen sind.', '', 28153),
(144287, 'deDE', '', 'Pohkiza...', 28153),
(144286, 'deDE', '', 'Der Blutgott... nimmt alles...', 28153),
(144285, 'deDE', '', 'Hahaha!', 28153),
(144284, 'deDE', '', 'Zuldazar... wird... fall\'n...', 28153),
(144283, 'deDE', '', 'Gachaga!', 28153),
(144282, 'deDE', '', 'Meine Schwestan werd\'n.... mich... räch\'n...', 28153),
(144281, 'deDE', '', 'Mein Blut... für... G\'huun!', 28153),
(144280, 'deDE', '', 'G\'huun!', 28153),
(144279, 'deDE', '<Tsunga grunzt Euch herzlich zu.>', '', 28153),
(144278, 'deDE', 'Ich bin aus den Nebeln gekommen, um das Volk von Zandalar zu warnen. Das Azerit hat den Gorillas hohe Intelligenz geschenkt. Diese Intelligenz bringt Krieg mit sich.', '', 28153),
(144277, 'deDE', 'Pohkiza...', '', 28153),
(144276, 'deDE', 'Der Blutgott... nimmt alles...', '', 28153),
(144275, 'deDE', 'Ihr habt... schon... verlor\'n...', '', 28153),
(144274, 'deDE', 'Zuldazar... wird... fall\'n...', '', 28153),
(144273, 'deDE', 'Gachaga!', '', 28153),
(144272, 'deDE', 'Mein Leben für die Mütta!', '', 28153),
(144271, 'deDE', 'Mein Blut... für... G\'huun!', '', 28153),
(144270, 'deDE', 'G\'huun!', '', 28153),
(144269, 'deDE', 'Gut. Gut. Noch einmal!', '', 28153),
(144268, 'deDE', 'Nich\' so zappeln.', '', 28153),
(144266, 'deDE', '', 'Ich greife den Dorfverteidigern unter die Arme. Wir treffen uns dann da!', 28153),
(144265, 'deDE', '', 'Wir haben sie zurückgeschlagen. Kommt! Wir sollten mit Bürgermeister Reinwald sprechen.', 28153),
(144264, 'deDE', '', 'Alleria seufzt mit gerunzelten Augenbrauen.', 28153),
(144263, 'deDE', '<Bleibt ein Weilchen und hört zu.>', '<Bleibt ein Weilchen und hört zu.>', 28153),
(144262, 'deDE', '', '<Allerias Augen wandern vom kalten steinernen Antlitz der Statue herunter zur Tafel mit der Inschrift.>', 28153),
(144261, 'deDE', 'Bleibt standhaft! Wir halten die Stellung!', 'Bleibt standhaft! Wir halten die Stellung!', 28153),
(144260, 'deDE', 'Neben Rohn\'kors letzten Atemzügen hört Ihr ein leises Winseln.', '', 28153),
(144259, 'deDE', '', 'Ich werd mir aus Eurem Bauch \'n neuen Hut mach\'n!', 28153),
(144258, 'deDE', '', 'Nein! Mein Baby!', 28153),
(144257, 'deDE', '', 'Hört auf, dem kleinen Schatz wehzutun! Ihr werdet diese Grube nich\' verlass\'n!', 28153),
(144256, 'deDE', '', 'Die woll\'n uns tot! Friss sie auf, mein Schatz!', 28153),
(144255, 'deDE', 'Bwonsamdi... seid gnädig!', 'Bwonsamdi... seid gnädig!', 28153),
(144254, 'deDE', 'Zandalar... für immer...', 'Zandalar... für immer...', 28153),
(144253, 'deDE', 'Wir werd\'n Euch die letzte Ruhe verschaff\'n, Urok. Tut mir leid, dass es so gelauf\'n is\'.', '', 28153),
(144252, 'deDE', 'Was zur... Was mach\'n diese Dinger in Urok?', '', 28153),
(144251, 'deDE', 'Wir sin\' so nah dran! Ich muss nur eben mein Zeug anzieh\'n...', '', 28153),
(144250, 'deDE', 'Nich\' so...', 'Nich\' so...', 28153),
(144249, 'deDE', 'Bwonsamdi... kommt... mich hol\'n...', 'Bwonsamdi... kommt... mich hol\'n...', 28153),
(144248, 'deDE', 'Haltet die Stellung, mehr Feinde im Anmarsch!', 'Haltet die Stellung, mehr Feinde im Anmarsch!', 28153),
(144247, 'deDE', 'Mein... Leben... für Zandalar...', 'Mein... Leben... für Zandalar...', 28153),
(144245, 'deDE', 'Di chuka Zandalar!', 'Di chuka Zandalar!', 28153),
(144243, 'deDE', 'Zermetzelt sie alle!', 'Zermetzelt sie alle!', 28153),
(144242, 'deDE', 'Für das einzig wahre Zandalar!', 'Für das einzig wahre Zandalar!', 28153),
(144240, 'deDE', 'Ich fütter\' die Würmer mit Euerm Blut!', 'Ich fütter\' die Würmer mit Euerm Blut!', 28153),
(144239, 'deDE', 'Wir werd\'n Euch verscharr\'n!', 'Wir werd\'n Euch verscharr\'n!', 28153),
(144238, 'deDE', 'Ihr werdet hier drauß\'n krepier\'n!', 'Ihr werdet hier drauß\'n krepier\'n!', 28153),
(144237, 'deDE', 'Zandalar für immer!', 'Zandalar für immer!', 28153),
(144236, 'deDE', 'Die Prinzessin hat gesagt, wir soll\'n die Monster find\'n. Aber das sin\' ja alles Monster!', '', 28153),
(144235, 'deDE', 'Wo is\' die Sonne? In diesem Sumpfloch seh\' ich gar nix!', '', 28153),
(144234, 'deDE', 'Das is\' Schwachsinn! Ich seh hier \'n großes Loch. Auf dieser Karte is\' aber kein Loch eingezeichnet!', '', 28153),
(144233, 'deDE', 'Oh! Das is\'... is\'... nichts... Das is\' enttäuschend.', '', 28153),
(144232, 'deDE', 'Taz\'okun! Das is\' vielleicht Azerit!', '', 28153),
(144231, 'deDE', 'Was is\'n das für \'n Nadelding? Igitt. Warum is\' das so klebrig?', '', 28153),
(144230, 'deDE', 'Oh, wie entzückend. Talanji würd sowas bestimmt gefall\'n.', '', 28153),
(144229, 'deDE', 'Ein behexter Armbrustschütze hat Euch ins Visier genommen. Weicht aus!', '', 28153),
(144228, 'deDE', 'Hier besteht sonst keine große Nachfrage nach Schwertern, aber ich schmiede sie sehr gerne. Dass wir jetzt so viele brauchen, gefällt mir trotzdem nicht!', '', 28153),
(144227, 'deDE', 'Jetzt versteh ich, warum die Leute sich vor diesem Sumpf fürcht\'n.', '', 28153),
(144226, 'deDE', 'Wie seltsam.', '', 28153),
(144225, 'deDE', 'Ich werd diesen Dreck wohl nie mehr von meinen Händen bekomm\'n. Meine schönen Schriftrollen.', '', 28153),
(144224, 'deDE', 'Was für \'n merkwürdiger Felsen... Oh! Er hat sich bewegt!', '', 28153),
(144223, 'deDE', 'Wirklich faszinierend.', '', 28153),
(144222, 'deDE', 'Gonk ebne Euern Pfad.', 'Gonk ebne Euern Pfad.', 28153),
(144221, 'deDE', 'Pa\'ku schütze Euch.', 'Pa\'ku schütze Euch.', 28153),
(144220, 'deDE', 'Rezans Kraft sei mit Euch.', 'Rezans Kraft sei mit Euch.', 28153),
(144219, 'deDE', 'Lasst Euch nicht kalt erwischen.', 'Lasst Euch nicht kalt erwischen.', 28153),
(144218, 'deDE', 'Benehmt Euch in unsrer Stadt.', 'Benehmt Euch in unsrer Stadt.', 28153),
(144217, 'deDE', 'Zandalar für immer!', 'Zandalar für immer!', 28153),
(144216, 'deDE', 'Braucht Ihr Schutz?', 'Braucht Ihr Schutz?', 28153),
(144215, 'deDE', '\'nen besseren Handel kriegt Ihr nirgendwo.', '\'nen besseren Handel kriegt Ihr nicht.', 28153),
(144214, 'deDE', 'Was hat Euer Aufenthalt für\'n Zweck?', 'Was hat Euer Aufenthalt für\'n Zweck?', 28153),
(144213, 'deDE', 'Grüße.', 'Grüße.', 28153),
(144209, 'deDE', 'Ich hab geschwor\'n, die Königsfamilie zu verteidig\'n.', 'Ich hab geschwor\'n, die Königsfamilie zu verteidig\'n.', 28153),
(144208, 'deDE', 'Unser Königreich erobert keiner.', 'Unser Königreich erobert keiner.', 28153),
(144201, 'deDE', 'Lasst uns die Sache angehen.', 'Lasst uns die Sache angehen.', 28153),
(144200, 'deDE', 'Wir sind jetzt sehr nah dran, $n.$b$bSagt einfach Bescheid, dann werde ich mit dem Hellsehen beginnen.$b$bOh, ich habe vergessen zu erwähnen: Unsere Rivalen haben in der Nähe ein Lager aufgeschlagen, am Strand. Beobachtet die Umgebung, damit wir nicht in einen Hinterhalt geraten.$b$bIch vertraue darauf, dass Ihr mich verteidigt, falls wir überfallen werden!', '', 28153),
(144199, 'deDE', 'Durchhalten, Leute! Wir halten diese Widerlinge auf!', '', 28153),
(144198, 'deDE', 'Die Nacht bricht an! Haltet die Wachfeuer am Brennen! Sagt, wenn Ihr mehr Brennstoff braucht.', '', 28153),
(144197, 'deDE', 'Lasst keins von diesen Monstern durch! Wir haben ihr Ungetüm zwar getötet, aber zu viele Boote verloren.', '', 28153),
(144196, 'deDE', 'Löst jemanden an der Barrikade ab, sobald Ihr Euch ausgeruht habt. Wir müssen diesen Angriff überstehen!', '', 28153),
(144195, 'deDE', 'Ich brauche Freiwillige, die zu Eschtal aufbrechen! Vielleicht kann er ein paar Leuchtfeuer basteln.', '', 28153),
(144194, 'deDE', 'Versorgt erst die Kinder und dann die Verletzten mit Nahrung!', '', 28153),
(144193, 'deDE', 'Heiler müssen sich abwechseln und Pausen einlegen! Das gilt auch für Euch, Kirstin!', '', 28153),
(144192, 'deDE', 'Verstärkt die Barrikade! Verwendet alles, was nicht festgenagelt ist. Und wenn das nicht reicht, dann zieht eben die Nägel raus!', '', 28153),
(144191, 'deDE', 'Der Kroggling gibt ein paar seltsam quäkende Geräusche von sich und scharrt mit den Füßen auf dem Seerosenblatt.', '', 28153),
(144190, 'deDE', 'Die Matrosen sollten lieber die Horde im Auge behalten und nicht uns.', 'Die Matrosen sollten lieber die Horde im Auge behalten und nicht uns.', 28153),
(144189, 'deDE', 'Je schneller wir finden, was wir suchen, und davonsegeln, desto besser.', 'Je schneller wir finden, was wir suchen, und davonsegeln, desto besser.', 28153),
(144188, 'deDE', 'Die Horde ist ganz in der Nähe, seid vorsichtig!', 'Die Horde ist ganz in der Nähe, seid vorsichtig!', 28153),
(144187, 'deDE', 'Ich wünschte, die Forscherliga hätte mehr ihrer Leute für diese Expedition abgestellt.', 'Ich wünschte, die Forscherliga hätte mehr ihrer Leute für diese Expedition abgestellt.', 28153),
(144186, 'deDE', 'Wer weiß, was die Dunkeleisenzwerge tun würden, wenn wir nicht hier wären, um sie im Auge zu behalten...', 'Wer weiß, was die Dunkeleisenzwerge tun würden, wenn wir nicht hier wären, um sie im Auge zu behalten...', 28153),
(144185, 'deDE', '', 'Und ihre Jungen erst! Ich kann eine Fotokabine aufbauen und Plüschdinos beschaffen. Ihr würdet natürlich etwas abbekommen, Jangalar. 70 zu 30 oder so. Die 70 natürlich für mich, ich habe schließlich die Ideen.', 28153),
(144184, 'deDE', 'Da vorn braucht noch einer Hilfe, wenn Ihr bereit dazu seid.', '', 28153),
(144183, 'deDE', '', 'NEU VERWENDEN: Es ist Zeit, den Injektor anzuwenden, um Ben\'jin in Wut zu versetzen und dann gemeinsam mit ihm die invasive Spezies zu vernichten.', 28153),
(144182, 'deDE', 'Bis wir hier mit Graben fertig sind, befindet sich die Horde schon auf halbem Weg nach Eisenschmiede!', 'Bis wir hier mit Graben fertig sind, befindet sich die Horde schon auf halbem Weg nach Eisenschmiede!', 28153),
(144181, 'deDE', 'Die Hitze macht den Dunkeleisenzwergen nichts aus, aber diese Feuchtigkeit...', 'Die Hitze macht den Dunkeleisenzwergen nichts aus, aber diese Feuchtigkeit...', 28153),
(144180, 'deDE', 'Der Forscherliga verbringt aber wirklich eine Menge Zeit mit Graben, besonderns, wenn es einen Krieg zu gewinnen gilt.', 'Der Forscherliga verbringt aber wirklich eine Menge Zeit mit Graben, besonderns, wenn es einen Krieg zu gewinnen gilt.', 28153),
(144179, 'deDE', 'Dafür haben wir unseren Berg verlassen?', 'Dafür haben wir unseren Berg verlassen?', 28153),
(144178, 'deDE', 'Kein Grund, gleich so dramatisch zu werden.', '', 28153),
(144177, 'deDE', '', 'Die Kratzspuren... der ungleichmäßig entfernte Schmutz... Wie sollen wir das denn jetzt ausstellen?!', 28153),
(144176, 'deDE', 'War das jetzt wirklich so schlimm?', '', 28153),
(144175, 'deDE', '', 'Wartet!', 28153),
(144174, 'deDE', 'Champion, Ihr dürft die Dinge gern beschleunigen. Dieses Gerät wird von Nutzen sein.', '', 28153),
(144173, 'deDE', 'Fantastisch? Madame, in diesem Tempo sind wir nächstes Jahr noch hier.', '', 28153),
(144172, 'deDE', '', 'Aaaahhhh, wunderbar. Ist das nicht ganz fantastisch?', 28153),
(144171, 'deDE', '', 'Versucht, das Fossil nicht zu beschädigen... Exzellent.', 28153),
(144170, 'deDE', '', 'Sehr gut. Und jetzt mit ganz ruhiger Hand.', 28153),
(144169, 'deDE', '', 'Passt auf, wo Ihr hintretet! Das ist eine einzige Todesfalle!', 28153),
(144168, 'deDE', 'Sehr gut! Das sollten wir gegen diese monströsen Holzkreaturen einsetzen können. Ah... Aber achtet darauf, nichts zu verschütten.', '', 28153),
(144167, 'deDE', 'Danke, dass Ihr sie mir zurückgebracht habt.', '', 28153),
(144166, 'deDE', '', 'NEU VERWENDEN: Hier ist die Box für die Injektorvorrichtung. Bitte installiert sie.', 28153),
(144165, 'deDE', '', 'Hallo Papa!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144164, 'deDE', 'Petra! Oh, mein Liebes!', '', 28153),
(144163, 'deDE', 'Eure Erfolge beim Sägewerk sind nicht von Dauer! Es wird bald wieder uns gehören!', '', 28153),
(144162, 'deDE', 'Dann suchen wir mal deinen Papa.', 'Dann suchen wir mal deinen Papa.', 28153),
(144161, 'deDE', '', 'Hallo! Wie heißt Ihr?', 28153),
(144160, 'deDE', 'Seht Ihr nicht, in welcher Gefahr Ihr schwebt?', 'Seht Ihr nicht, in welcher Gefahr Ihr schwebt?', 28153),
(144159, 'deDE', 'Ihr könnt uns nicht alle aufhalten!', 'Ihr könnt uns nicht alle aufhalten!', 28153),
(144158, 'deDE', 'Ihr werdet uns niemals alle finden!', 'Ihr werdet uns niemals alle finden!', 28153),
(144157, 'deDE', 'Mein Standort wurde entdeckt!', 'Mein Standort wurde entdeckt!', 28153),
(144156, 'deDE', 'Schaut! Sie haben sogar eine von unseren Trommeln.\n\nWer behauptet, Goblins hätten keine Kultur?', '', 28153),
(144153, 'deDE', 'Bitte gebt ein paar Tropfen flüchtigen Harzes dazu. Achtet darauf, das Gefäß ruhig zu halten!', '', 28153),
(144152, 'deDE', 'Etwas Schwefel bitte. Aber meidet die Dämpfe!', '', 28153),
(144151, 'deDE', 'Gebt ganz vorsichtig etwas Herdblume dazu.', '', 28153),
(144150, 'deDE', 'Wir brauchen ein wenig Salpeter, damit es auch ordentlich wirkt!', '', 28153),
(144148, 'deDE', 'Krag\'wa nickt Eurem Gefährten zu.', '', 28153),
(144147, 'deDE', 'Krag\'wa und der junge Kroggling scheinen zu kommunizieren.', '', 28153),
(144146, 'deDE', 'Nein! Ich geh nicht zurück in den Bau! NIEMALS!', '', 28153),
(144145, 'deDE', '', 'Haltet den Schrein! Wir dürfen nicht die Kontrolle verlieren!', 28153),
(144144, 'deDE', 'Ausgezeichnet! Ich werde Euch sagen, was Ihr in den Kessel geben müsst. Folgt bitte genau meinen Anweisungen, weil die Konsequenzen sonst... sehr explosiv sein könnten.', '', 28153),
(144142, 'deDE', 'Tschüss, Petra!', '', 28153),
(144141, 'deDE', '', 'Jap! Bis später, Jens!', 28153),
(144140, 'deDE', '', 'Hallo Jens!', 28153),
(144139, 'deDE', 'Oh, hallo Petra. Bist du auf dem Weg zu deinem Papa?', '', 28153),
(144138, 'deDE', 'Was ist denn mit allen los?!', '', 28153),
(144137, 'deDE', '', 'Ich brauche Heilung!', 28153),
(144136, 'deDE', '', 'Ergebt Euch den Elementen!', 28153),
(144135, 'deDE', '$n, es gibt nichts, was ich tun könnte, um ihn zurückzuverwandeln. Bei Euch wird er ein besseres Leben haben. Behaltet ihn und beschützt ihn.', '', 28153),
(144134, 'deDE', 'Ich verstehe.', '', 28153),
(144133, 'deDE', 'Kommt doch näher, junges Wesen.', '', 28153),
(144132, 'deDE', 'Alptraum...', '', 28153),
(144131, 'deDE', 'Der Mond... geht auf...', '', 28153),
(144130, 'deDE', 'Ferne Küsten...', '', 28153),
(144129, 'deDE', 'Nich\'... im Topf rühren...', '', 28153),
(144128, 'deDE', 'Noch zwei Becher... un\' Eure größte Chilischote...', '', 28153),
(144127, 'deDE', 'Der mittlere Berg... stürzt...', '', 28153),
(144126, 'deDE', 'Noch zehn Minuten...', '', 28153),
(144125, 'deDE', 'Noch nich\'...', '', 28153),
(144124, 'deDE', 'Flinkie knurrt beschützend.', '', 28153),
(144123, 'deDE', 'Stellt Euch Eurem Ende!', 'Stellt Euch Eurem Ende!', 28153),
(144122, 'deDE', 'Erblickt die Wahrheit... Eures Verderbens...', '', 28153),
(144121, 'deDE', 'Dieser Sieg... wird... nur Euren Tod bringen...', '', 28153),
(144120, 'deDE', 'Bedeutungslos... im Angesicht... der Leere...', '', 28153),
(144119, 'deDE', 'Ihr habt... nichts... gewonnen...', '', 28153),
(144118, 'deDE', 'Die Meister... rufen...', '', 28153),
(144117, 'deDE', 'Die Leere... holt alle...', '', 28153),
(144116, 'deDE', 'Sinnlos... alles wird... Dunkelheit...', '', 28153),
(144115, 'deDE', 'Sie werden Eure Leiche aus dem Hafenwasser ziehen!', 'Sie werden Eure Leiche aus dem Hafenwasser ziehen!', 28153),
(144114, 'deDE', 'Kul Tiras braucht die Allianz nicht!', 'Kul Tiras braucht die Allianz nicht!', 28153),
(144113, 'deDE', 'Euch befördere ich unter die Wellen!', 'Euch befördere ich unter die Wellen!', 28153),
(144112, 'deDE', '<Reiht Euch in die Warteschlange für die Schlacht um Stromgarde ein.>', '<Reiht Euch in die Warteschlange für die Schlacht um Stromgarde ein.>', 28153),
(144111, 'deDE', 'Von hier aus könnt Ihr Euch in die Warteschlange für den Kampf an einer Kriegsfront einreihen.', '', 28153),
(144110, 'deDE', 'Katherine will uns alle ertrinken lassen!', 'Katherine will uns alle ertrinken lassen!', 28153),
(144109, 'deDE', 'Azeroth ist unser.', '', 28153),
(144108, 'deDE', 'Das Imperium wird wiederauferstehen!', '', 28153),
(144107, 'deDE', 'Findet sie!', '', 28153),
(144106, 'deDE', 'Alles wird vergehen.', '', 28153),
(144105, 'deDE', 'Alles wird vernichtet werden.', '', 28153),
(144104, 'deDE', 'Keine Hoffnung... kein Leben.', '', 28153),
(144103, 'deDE', 'Alles wird verschlungen.', '', 28153),
(144102, 'deDE', 'Alles wird zu Schatten.', '', 28153),
(144101, 'deDE', 'Die Leere verschlingt alles.', '', 28153),
(144100, 'deDE', '', 'Druiden der Klaue, ANGRIFF!', 28153),
(144099, 'deDE', '<Pfeift>', '', 28153),
(144097, 'deDE', '', 'Dann eben Plan B.', 28153),
(144096, 'deDE', 'Wir haben die Infos. Jetzt müssen wir\'s nur hier rausschaffen!', '', 28153),
(144095, 'deDE', '', 'Wir wurden entdeckt!', 28153),
(144094, 'deDE', 'Bl-bl-bl-bl... <Statik> Blut von Azeroth geortet. Anfrage: Anbringung des fehlenden Dat-dat-dat-dat... <Statik> ...kerns.', '', 28153),
(144093, 'deDE', 'Argh. Das is\' fürchterlich!', '', 28153),
(144092, 'deDE', 'Jabari, Ihr habt das Erinnerungsvermögen eines Elekk un\' den Verstand von Gonk.', '', 28153),
(144091, 'deDE', 'Klar, un\' wenn man \"scharf\" mit tödlich giftigen Injektionen gleichsetzt, passt der Vergleich auch...', '', 28153),
(144090, 'deDE', 'Ich brauch Eure Pflege nich\', Jabari! Ich hab Haw\'lis scharfes Chili überlebt!', '', 28153),
(144089, 'deDE', 'Kriegt Euch ein. Ihr benehmt euch wie\'n Bruto mit Halsschmerzen.', '', 28153),
(144088, 'deDE', 'Ruhig, mein Bruder... Nehmt das.', '', 28153),
(144087, 'deDE', 'Hört auf mit dem Rumdoktern!', '', 28153),
(144086, 'deDE', 'Ganz genau! Hm, was brauchen wir jetzt...?', '', 28153),
(144085, 'deDE', 'Ihr habt bereits Erfahrung in der Alchemie! Das sehe ich sofort!', '', 28153),
(144084, 'deDE', 'Gut gemacht! Und als Nächstes...', '', 28153),
(144082, 'deDE', 'Der erste Schuss ist bereit. Sobald ich ihn abgefeuert habe, werden sie wissen, dass wir hier sind.$b$bSeid Ihr so weit?', '', 28153),
(144081, 'deDE', 'Es ist nur eine Frage der Zeit, bis sie hier oben nachsehen...', '', 28153),
(144080, 'deDE', '', 'In Ordnung! Los!', 28153),
(144079, 'deDE', '', 'Wartet! Ihr müsst mich an die Hand nehmen!', 28153),
(144078, 'deDE', 'Familie Prachtmeer wird fallen!', 'Familie Prachtmeer wird fallen!', 28153),
(144077, 'deDE', 'Mein Tod wird den Wechsel von Ebbe und Flut nicht aufhalten.', 'Mein Tod wird den Wechsel von Ebbe und Flut nicht aufhalten.', 28153),
(144076, 'deDE', 'Das werdet Ihr bereuen!', 'Das werdet Ihr bereuen!', 28153),
(144075, 'deDE', 'Ihr gehört hier nicht her, $gFremder:Fremde;!', 'Ihr gehört hier nicht her, $gFremder:Fremde;!', 28153),
(144074, 'deDE', 'Boralus gehört uns!', 'Boralus gehört uns!', 28153),
(144073, 'deDE', '', 'Zwischen hier und Atal\'Dazar sind viele Streitkräfte von Zul. Wir müss\'n sie ausm Weg räumen.', 28153),
(144072, 'deDE', 'Elfen...', 'Elfen...', 28153),
(144071, 'deDE', 'Vollstrecker der Rastari spuckt auf den Boden.', 'Vollstreckerin der Rastari seufzt.', 28153),
(144070, 'deDE', 'Natürlich! Er ist so herrlich primitiv. Okay, in 3... 2... 1...', '', 28153),
(144069, 'deDE', '', 'Der große, hässliche Tempel im Hintergrund muss auf jeden Fall mit drauf.', 28153),
(144068, 'deDE', '', 'Alle unsere Freunde in Silbermond werden so neidisch sein, wenn sie dieses Bild sehen.', 28153),
(144067, 'deDE', 'Nachdem ich meine Prüfung nun abgeschlossen hatte, vollendete ich meine Geschichte und kehrte zurück in die reale Welt.', 'Nachdem ich meine Prüfung nun abgeschlossen hatte, vollendete ich meine Geschichte und kehrte zurück in die reale Welt.', 28153),
(144066, 'deDE', 'Sie sah mir direkt in die Augen, blickte tief in meine Seele und vermittelte mir das Wissen darum, wie ich sie heraufbeschwören konnte.', 'Sie sah mir direkt in die Augen, blickte tief in meine Seele und vermittelte mir das Wissen darum, wie ich sie heraufbeschwören konnte.', 28153),
(144065, 'deDE', 'Sie nahm ihre endgültige körperliche Gestalt an und bekundete ihr neu gewonnenes Leben mit einem Schrei.', 'Sie nahm ihre endgültige körperliche Gestalt an und bekundete ihr neu gewonnenes Leben mit einem Schrei.', 28153),
(144064, 'deDE', 'Als das Ritual abgeschlossen war, begann vor meinen Augen eine Kreatur zusammenzufließen.', 'Als das Ritual abgeschlossen war, begann vor meinen Augen eine Kreatur zusammenzufließen.', 28153),
(144063, 'deDE', 'Als ich den Raum betrat, bemerkte ich die vier auf dem Boden verteilten Runen. Dafür war vermutlich die Tinte vorgesehen.', 'Als ich den Raum betrat, bemerkte ich die vier auf dem Boden verteilten Runen. Dafür war vermutlich die Tinte vorgesehen.', 28153),
(144062, 'deDE', 'Als ich genug Tinte gesammelt hatte, fühlte ich mich auf seltsame Weise zu einem Ende der Halle hingezogen.', 'Als ich genug Tinte gesammelt hatte, fühlte ich mich auf seltsame Weise zu einem Ende der Halle hingezogen.', 28153),
(144061, 'deDE', 'Ein Skelett auf dem Boden erinnerte mich an meine eigene Sterblichkeit. Ich fragte mich, ob andere bereits an dieser Prüfung gescheitert waren.', 'Ein Skelett auf dem Boden erinnerte mich an meine eigene Sterblichkeit. Ich fragte mich, ob andere bereits an dieser Prüfung gescheitert waren.', 28153),
(144060, 'deDE', 'Diese zähflüssigen Wesen begannen, ziemlich lästig zu werden.', 'Diese zähflüssigen Wesen begannen, ziemlich lästig zu werden.', 28153),
(144059, 'deDE', 'Die Schlicke waren der Schlüssel zu diesem Rätsel. Und bis jetzt fand ich, was ich brauchte.', 'Die Schlicke waren der Schlüssel zu diesem Rätsel. Und bis jetzt fand ich, was ich brauchte.', 28153),
(144058, 'deDE', 'Irgendwie wusste ich, was zu tun war, und entschied mich, fortzufahren.', 'Irgendwie wusste ich, was zu tun war, und entschied mich, fortzufahren.', 28153),
(144057, 'deDE', 'Meidet die Schwärze und sammelt die Röte, auf dass der blutgebundene Schlächter für euch töte.\"', 'Meidet die Schwärze und sammelt die Röte, auf dass der blutgebundene Schlächter für euch töte.\"', 28153),
(144056, 'deDE', '\"Was durch Stift und Adern fließt, sich gemeinsam hier ergießt.', '\"Was durch Stift und Adern fließt, sich gemeinsam hier ergießt.', 28153),
(144055, 'deDE', 'Ich erwachte in einer Kammer. Eine fremde Stimme in meinem Kopf zitierte ein Gedicht.', 'Ich erwachte in einer Kammer. Eine fremde Stimme in meinem Kopf zitierte ein Gedicht.', 28153),
(144054, 'deDE', 'Ihr beginnt, in das Buch zu schreiben: \"Als mein Stift die Seite berührte, spürte ich, wie ich hineingezogen wurde.\"', 'Ihr beginnt, in das Buch zu schreiben: \"Als mein Stift die Seite berührte, spürte ich, wie ich hineingezogen wurde.\"', 28153),
(144053, 'deDE', 'Ihr blättert das ganz Buch durch und findet nur leere Seiten. Frustriert seht Ihr zu Kronah und fragt Euch, ob sie den Kniff bei dieser Prüfung kennt.', '', 28153),
(144052, 'deDE', 'Ich freue mich schon darauf, über Eure Begegnungen zu lesen.', '', 28153),
(144051, 'deDE', 'Nehmt einfach einen Eurer Stifte und beginnt zu schreiben. Keine Sorge, den Rest macht das Buch selbst.', '', 28153),
(144050, 'deDE', 'Also, das ist ganz einfach. Ihr müsst Eure eigene Geschichte in das Buch schreiben.', '', 28153),
(144049, 'deDE', 'Oh nein, ich glaub\', ich muss...', '', 28153),
(144048, 'deDE', 'Ich möchte ein paar meiner Stacheln eintauschen.', 'Ich möchte ein paar meiner Stacheln eintauschen.', 28153),
(144047, 'deDE', 'Oh, das hat leider überhaupt nicht funktioniert. Also noch einmal!', '', 28153),
(144046, 'deDE', 'Die Alchemie ist eine präzise Wissenschaft! Bitte seid etwas aufmerksamer.', '', 28153),
(144045, 'deDE', 'Also, das war nicht richtig. Wir müssen noch mal von vorne anfangen!', '', 28153),
(144044, 'deDE', 'Die Mixtur hat sich entzündet! Wir müssen von vorn anfangen!', 'Die Mixtur hat sich entzündet! Wir müssen von vorn anfangen!', 28153),
(144043, 'deDE', 'Zul hat diesen Tag vorhergesehen. Indem Ihr gegen das Schicksal ankämpft, beweist Ihr nur seine Unausweichlichkeit!', '', 28153),
(144042, 'deDE', 'Zul... hat nie gesagt... ich würde verlieren...', '', 28153),
(144041, 'deDE', 'Ihr werdet ihn niemals rechtzeitig erreichen!', '', 28153),
(144040, 'deDE', 'Ich bin bereit anzufangen!', 'Ich bin bereit anzufangen!', 28153),
(144039, 'deDE', 'Wartet! Jetzt geht es mir wieder besser! Argh...', 'Wartet! Jetzt geht es mir wieder besser! Argh...', 28153),
(144038, 'deDE', 'Ich war ein Narr!', 'Ich war eine Närrin!', 28153),
(144037, 'deDE', 'Ich kann ihr Lied nicht mehr vernehmen...', 'Ich kann ihr Lied nicht mehr vernehmen...', 28153),
(144036, 'deDE', 'Sie wird Euch nie lieben!', 'Sie wird Euch nie lieben!', 28153),
(144035, 'deDE', 'Nein, meine Liebste!', 'Nein, meine Liebste!', 28153),
(144034, 'deDE', 'Liebe kann auch wehtun.', 'Liebe kann auch wehtun.', 28153),
(144033, 'deDE', 'Das war es wert!', 'Das war es wert!', 28153),
(144032, 'deDE', 'So süß ist Trennungsweh.', 'So süß ist Trennungsweh.', 28153),
(144031, 'deDE', 'Hey Süße, schaut her, wie ich diesen Kerl verprügle.', 'Hey Süße, schaut her, wie ich diesen Kerl verprügle.', 28153),
(144030, 'deDE', 'Guckt Ihr etwa mein Mädel an?!', 'Guckt Ihr etwa mein Mädel an?!', 28153),
(144029, 'deDE', 'Die Liebe überwindet alles!', 'Die Liebe überwindet alles!', 28153),
(144028, 'deDE', 'Sie gehört mir! MIR!', 'Sie gehört mir! MIR!', 28153),
(144027, 'deDE', 'Wir danken Euch, Champion. Ihr habt dieses Dorf gerettet und in mir neuen Mut entfacht. Albers und Therold, sorgt dafür, dass der Angelpunkt sich erholt. Ihr hört bald von mir.', '', 28153),
(144026, 'deDE', 'Fasst sie nicht an!', 'Fasst sie nicht an!', 28153),
(144025, 'deDE', 'Zul will Dazar erwecken?! Ich werde hier nicht untätig herumsitzen, während dieser \"Prophet\" die Gebeine unseres ersten Königs entweiht. Kommt, Champion, trefft uns am Südtor dieses Ortes.', '', 28153),
(144024, 'deDE', 'Jetzt muss ich heimkehren. Mein Onkel und seine Gezeitenweisen im Sturmsangtal wissen vielleicht mehr über diese dunkle Magie.', '', 28153),
(144023, 'deDE', 'Tiefenwacht... Intelligent war er immer, aber mit solcher Magie hat er sich meines Wissens nie beschäftigt. Eine Kraft zu bändigen, die den Ozean in solche Panik versetzt...', '', 28153),
(144022, 'deDE', 'Verschwindet, sie ist schon vergeben!', 'Verschwindet, sie ist schon vergeben!', 28153),
(144021, 'deDE', '', 'Ja! Da ist eine Lücke bei ihren Himmelstötern. Fliegt, meine Kinder! Tötet diese Ketzer!', 28153),
(144020, 'deDE', 'Der Angelpunkt ist sicher, aber meine Furcht bleibt. Tiefenwacht war ein kluger Mann, aber er hat bisher keine solche Macht besessen.', '', 28153),
(144019, 'deDE', 'Ich werde Euch beschützen, meine Liebste!', 'Ich werde Euch beschützen, meine Liebste!', 28153),
(144018, 'deDE', 'Ich liebe sie so sehr!', 'Ich liebe sie so sehr!', 28153),
(144017, 'deDE', 'DIE HAND DES SCHICKSALS IST ZUFRIEDENGESTELLT. ICH WERDE EUCH IN SICHERHEIT BRINGEN. DAS SCHICKSAL NEIGT MANCHMAL ZUR GÜTE.', '', 28153),
(144016, 'deDE', 'Weg aus unsrer Stadt, $p! Ihr verdammt uns alle!', '', 28153),
(144015, 'deDE', 'Macht Platz für $p, von den Loa gesegnet!', '', 28153),
(144013, 'deDE', '', 'Die Omen sin\' zwiegespalten... Euch erwart\'n unmögliche Herausforderungen, aber Ihr werdet sie übersteh\'n. Die Loa verlass\'n Euch nich\'.', 28153),
(144012, 'deDE', '', 'Ich fürcht, das sin\' alles schlechte Omen... Eure Zukunft hält \'ne Menge Ärger parat. Tut mir leid.', 28153),
(144011, 'deDE', '', 'Meidet heut das Wasser. Es is\' nich\' sicher.', 28153),
(144010, 'deDE', '', 'Leer? Nein... Ihr müsst dass ändern.', 28153),
(144009, 'deDE', '', 'Ihr werdet große Not un\' Verrat erfahr\'n. Wählt Eure Begleiter heut\' mit Bedacht.', 28153),
(144008, 'deDE', '', 'Ich hab dieses Omen für \'ne sehr, sehr lange Zeit nich\' gehört... Ihr müsst Euer Schicksal ändern.', 28153),
(144007, 'deDE', '', 'Wenn Ihr heute Eure Ziele verfolgt, nehmt nich\' den leichten Weg. Kompromisse oder Achtlosigkeit werd\'n zu \'nem schlimmen Ende führ\'n.', 28153),
(144006, 'deDE', '', '\'ne Warnung von der Andren Seite. Seid vorsichtig.', 28153),
(144005, 'deDE', '', 'Hütet Euch vor der Gold\'nen Stadt. Sie is\' das Risiko nich\' wert.', 28153),
(144004, 'deDE', '', 'Ihr müsst blind in die Zukunft geh\'n, fürcht ich.', 28153),
(144003, 'deDE', '', 'Gral wird von \'ner unsichtbaren Hand in die Tiefe gezog\'n.', 28153),
(144002, 'deDE', '', 'Shadras Nest is\' leer.', 28153),
(144001, 'deDE', '', 'Torcali schläft.', 28153),
(144000, 'deDE', '', 'Rezan stürzt zu Boden... tot.', 28153),
(143999, 'deDE', '', 'Bwonsamdi bietet grinsend \'nen Handel an.', 28153),
(143998, 'deDE', '', 'Krag\'wa verschlingt \'ne Herde blauer Terrorhörner.', 28153),
(143997, 'deDE', '', 'Gonk is\' allein und durchschwimmt \'nen Fluss aus Gold.', 28153),
(143996, 'deDE', '', 'Pa\'ku schließt ihre Augen in der Dunkelheit.', 28153),
(143995, 'deDE', '', 'Es gibt nur wenige Omen, die schlechter sin\' als das. Seid vorsichtig.', 28153),
(143994, 'deDE', '', '\'n dunkles Omen für uns alle. Was habt Ihr an unsre Küste gebracht?', 28153),
(143993, 'deDE', '', 'Ihr verschwendet Euer Potenzial. Werdet den Möglichkeit\'n gerecht, die sich Euch biet\'n, oder Ihr werdet zu \'nem namenlos\'n Toten.', 28153),
(143992, 'deDE', '', 'Die Spaltung zwisch\'n Euch un\' Euern Verbündeten bedroht uns alle. Ihr müsst Zandalar verein\'n.', 28153),
(143991, 'deDE', '', '\'n unwillkomm\'nes Omen, doch eins, das mit Stärke un\' Entschlusskraft überwund\'n werd\'n kann.', 28153),
(143990, 'deDE', '', 'Streitende Anführer sin\' gar keine Anführer. Ihr müsst mit Euern Rivalen arbeit\'n oder die Konsequenzen trag\'n.', 28153),
(143989, 'deDE', '', 'Eine Dunkelheit erhebt sich, die selbst die Stärkst\'n von uns verschlingt. Auch Euch.', 28153),
(143988, 'deDE', '', 'Ein dunkles Omen für uns alle...', 28153),
(143987, 'deDE', '', 'Der Tod eines neuen Freunds.', 28153),
(143986, 'deDE', '', 'Die untergeh\'nde Sonne in den dunklen Sümpf\'n von Nazmir.', 28153),
(143985, 'deDE', '', '\'ne zerbroch\'ne Amphore, aus der Wein rinnt.', 28153),
(143984, 'deDE', '', 'Zwei Priester, die sich gegenseitig töt\'n.', 28153),
(143983, 'deDE', '', 'Ein Menschenschiff an unsrer Küste...', 28153),
(143982, 'deDE', '', 'Ein zerbroch\'ner Thron aus Feuer un\' Eis...', 28153),
(143981, 'deDE', '', 'Ein Brutosaurus, der in Blut ertrinkt...', 28153),
(143980, 'deDE', '', 'Ein Fluss aus Blut, worin Leich\'n stromaufwärts schwimm\'n...', 28153),
(143979, 'deDE', 'Komm, Kratzi, gehen wir!', 'Komm, Kratzi, gehen wir!', 28153),
(143978, 'deDE', 'Hurra! Vielen Dank!', 'Hurra! Vielen Dank!', 28153),
(143977, 'deDE', 'Puh. Das ist schon besser!', '', 28153),
(143976, 'deDE', 'Ich hab den andern gesagt, dass sie geh\'n soll\'n, aber sie wollt\'n es nochmal seh\'n... Ich bin nur knapp entkomm\'n. Ohne Euch hätt ich es nich\' geschafft.', '', 28153),
(143975, 'deDE', '', 'Sprecht durch Euer Gefäß Zetoa!', 28153),
(143974, 'deDE', '', 'Sprecht durch Euer Gefäß Iluna!', 28153),
(143973, 'deDE', '', 'Wir sin\' bereit. Füllt meine Gefäße un\' zeigt uns die Zukunft.', 28153),
(143972, 'deDE', '', 'Geister der Toten, Geister der Loa, Geister der Vergessenen un\' Verlorenen, hört mich an!', 28153),
(143971, 'deDE', 'Ich gehe zurück zur Verteidigungslinie!', 'Ich gehe zurück zur Verteidigungslinie!', 28153),
(143970, 'deDE', 'Ich konnte mich nicht bewegen!', 'Ich konnte mich nicht bewegen!', 28153),
(143969, 'deDE', 'Ich dachte, sie wollten mich auch in den Wald zerren!', 'Ich dachte, sie wollten mich auch in den Wald zerren!', 28153),
(143968, 'deDE', 'Sie haben schon Leute in den Wald verschleppt!', 'Sie haben schon Leute in den Wald verschleppt!', 28153),
(143967, 'deDE', 'Ich gehe zurück zur Barrikade!', 'Ich gehe zurück zur Barrikade!', 28153),
(143966, 'deDE', '', 'Das sin\' alles gute Omen... Geht heut\' alles mit Zuversicht an!', 28153),
(143965, 'deDE', 'Ich dachte schon, es wäre um mich geschehen!', 'Ich dachte schon, es wäre um mich geschehen!', 28153),
(143964, 'deDE', 'Habt Dank!', 'Habt Dank!', 28153),
(143963, 'deDE', '', '\'ne Stampede...', 28153),
(143962, 'deDE', '', '\'n unbeschwertes Omen... Lasst Euch nich\' von Sorgen überwältig\'n. Glück un\' Humor werden Euch Erfolg bring\'n.', 28153),
(143961, 'deDE', 'Die Fäulnis wächst!', '', 28153),
(143960, 'deDE', 'Alles is\'... vergänglich...', '', 28153),
(143959, 'deDE', '', 'Der häufigste Segen von Shadra, mit \'nem unerwartet\'n Zusatz. Noch immer gut, aber ich kann ihn nich\' ganz entschlüss\'ln.', 28153),
(143958, 'deDE', '', 'Der Segen des Verteidigers... Ihr werdet viele Leben rett\'n, aber vielleicht Eures geb\'n.', 28153),
(143957, 'deDE', '', 'Der Loa des Königs is\' ein seltenes Omen. Kraftvoll un\' mächtig. Ihr werdet die Feinde des Königs vernicht\'n.', 28153),
(143956, 'deDE', '', '\'n gutes Omen für langes Leben und \'nen leichten Tod.', 28153),
(143955, 'deDE', 'Nähren!', '', 28153),
(143954, 'deDE', 'Verdorrt!', '', 28153),
(143953, 'deDE', 'Die Verderbnis sprießt!', '', 28153),
(143952, 'deDE', '', 'Sofern diese Insel nich\' Eure Heimat is\', is\' das ein gutes Omen.', 28153),
(143951, 'deDE', 'Wachst!', '', 28153),
(143950, 'deDE', '', 'Ihr werdet immer an der Seite von Verbündeten kämpf\'n. Gonk wird Euch in Eurer Stunde der Not nich\' verlass\'n.', 28153),
(143949, 'deDE', '', 'Pa\'ku wird Euch auf Eurer Reise leit\'n und Eure Feinde fernhalt\'n...', 28153),
(143948, 'deDE', 'So fruchtbarer Nährboden!', '', 28153),
(143947, 'deDE', '', 'Gral springt über die Flotte des Königs...', 28153),
(143946, 'deDE', '', 'Shadras Eier schlüpf\'n. Zahllose Augen husch\'n vorwärts...', 28153),
(143945, 'deDE', '', 'Torcali steht hoch aufgerichtet auf \'ner Bergspitze, allein...', 28153),
(143944, 'deDE', '', 'Rezan stampft auf un\' die Bluttrolle zerstreu\'n sich...', 28153),
(143943, 'deDE', '', 'Bwonsamdi wendet sich ab...', 28153),
(143942, 'deDE', '', 'Krag\'wa verschlingt \'ne Insel...', 28153),
(143941, 'deDE', 'Wuchert!', '', 28153),
(143940, 'deDE', '', 'Gonk rennt mit seinem Rudel...', 28153),
(143939, 'deDE', 'Erntezeit!', '', 28153),
(143938, 'deDE', 'Der Verfall is\' unaufhaltsam!', '', 28153),
(143937, 'deDE', '', 'Fast immer \'n gutes Omen, aber es wird von Euerm Freund abhäng\'n...', 28153),
(143936, 'deDE', '', '\'n gutes Omen für uns alle. Wir sollt\'n Eure Anwesenheit in Zandalar schätz\'n.', 28153),
(143935, 'deDE', '', 'Entgeg\'n dem Glauben vieler habt Ihr Euer volles Potenzial noch nich\' erreicht. Eure Macht wird wachs\'n un\' Ihr werdet mächtiger werd\'n, als man es je von Euch geglaubt hat.', 28153),
(143934, 'deDE', '', '\'n... überraschendes Omen für \'nen Fremdling. Was mag das bedeut\'n?', 28153),
(143933, 'deDE', '', '\'n machtvolles Omen! Das verheißt Euch Gutes...', 28153),
(143932, 'deDE', '', '\'n gutes Omen für die Ausbreitung un\' das Wachsen unseres Volks. Int\'ressant, dass Ihr dieses Omen erhaltet...', 28153),
(143931, 'deDE', '', '\'n gutes Omen für Wohlstand un\' Vermächtnis.', 28153),
(143930, 'deDE', '', '\'n gutes Omen der Stärke, der Macht un\' des Erfolgs.', 28153),
(143929, 'deDE', '', 'Die Wiederauferstehung eines früheren Freunds...', 28153),
(143928, 'deDE', '', '\'ne aufgehende Sonne über goldenem Wasser...', 28153),
(143927, 'deDE', '', '\'n großes Ei, in dem sich wild was bewegt, doch es bricht nich\' auf...', 28153),
(143926, 'deDE', '', 'Alle Trollstämme vereint unter dem Banner der Zandalari...', 28153),
(143925, 'deDE', '', '\'n abgetrennter Elfenkopf...', 28153),
(143924, 'deDE', '', 'Uralte Wasser, seit Generationen unberührt...', 28153),
(143923, 'deDE', '', 'Masken aus Gold...', 28153),
(143922, 'deDE', '', 'Pa\'kus Schatten fällt über \'nen steinigen Pfad...', 28153),
(143921, 'deDE', '', 'Gut. Lasst uns seh\'n, was die Geister Euch zu sag\'n hab\'n...', 28153),
(143920, 'deDE', '', 'Seid Ihr sicher, dass Ihr\'s wissen wollt, $p?\n\nNich\' alle Wahrsagungen handeln von groß\'n Taten un\' glücklich\'n Ausgängen...', 28153),
(143919, 'deDE', 'Ich habe keine Furcht. Sagt mir, was Ihr in meiner Zukunft seht.', 'Ich habe keine Furcht. Sagt mir, was Ihr in meiner Zukunft seht.', 28153),
(143918, 'deDE', 'Was seht Ihr in meiner Zukunft?', 'Was seht Ihr in meiner Zukunft?', 28153),
(143917, 'deDE', '', 'Hört mich, Geister, alt un\' verlor\'n. Füllt die Gefäße un\' enthüllt uns die Zukunft.', 28153),
(143916, 'deDE', 'Es ist egal. Wir sind überall... unter Euren Füßen.', '', 28153),
(143915, 'deDE', 'Ihr seid schwach... Unser Stamm... wird stark.', 'Ihr seid schwach... Unser Stamm... wird stark.', 28153),
(143914, 'deDE', '', 'Willkomm\'n im Salon der verlor\'nen Geister, $p.\n\nIhr seid spät dran. Ich war nich\' sicher, ob Ihr\'s noch schaff\'n würdet.\n\nAlso sagt mir, was kann Madam Konawla für Euch tun?', 28153),
(143913, 'deDE', 'Ich sterb gut...', 'Ich sterb gut...', 28153),
(143912, 'deDE', 'Unsere Dornen überwuchern das Land!', 'Unsere Dornen überwuchern das Land!', 28153),
(143911, 'deDE', 'Die Borstenrücken... werden trotzdem groß und stark...', 'Die Borstenrücken... werden trotzdem groß und stark...', 28153),
(143910, 'deDE', 'Mein Weg... endet.', 'Mein Weg... endet.', 28153),
(143909, 'deDE', 'Euer Tod. Mein Ruhm.', 'Euer Tod. Mein Ruhm.', 28153),
(143908, 'deDE', 'Euer Blut macht die Dornen groß und stark.', 'Euer Blut macht die Dornen groß und stark.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143907, 'deDE', 'Rückzug? Kapitulation? Niemals!', 'Rückzug? Kapitulation? Niemals!', 28153),
(143906, 'deDE', 'Warum ist das Kompendium des Blutvergießens leer?', 'Warum ist das Kompendium des Blutvergießens leer?', 28153),
(143905, 'deDE', 'Unsre Eber fressen sich satt an Euch.', 'Unsre Eber fressen sich satt an Euch.', 28153),
(143904, 'deDE', 'Ihr könnt uns nicht aufhalten!', 'Ihr könnt uns nicht aufhalten!', 28153),
(143903, 'deDE', 'Wir nehmen uns das Land hier!', 'Wir nehmen uns das Land hier!', 28153),
(143902, 'deDE', 'Beginnt, in das Buch zu schreiben.', 'Beginnt, in das Buch zu schreiben.', 28153),
(143901, 'deDE', 'Blättert das ganze Buch durch.', 'Blättert das ganze Buch durch.', 28153),
(143900, 'deDE', 'Kraaaatzi! Bist du noch da oben?! Miaue zweimal, wenn du mich hören kannst!!', 'Kraaaatzi! Bist du noch da oben?! Miaue zweimal, wenn du mich hören kannst!!', 28153),
(143899, 'deDE', 'Auch die nächsten Seiten scheinen leer zu sein.', '', 28153),
(143898, 'deDE', 'Wir holen dich da runter, Kratzi! Bleib ruhig!', 'Wir holen dich da runter, Kratzi! Bleib ruhig!', 28153),
(143897, 'deDE', 'Alles wird gut, Kratzi! Warte ein bisschen!', 'Alles wird gut, Kratzi! Warte ein bisschen!', 28153),
(143896, 'deDE', 'Blättert noch ein paar Seiten um.', 'Blättert noch ein paar Seiten um.', 28153),
(143895, 'deDE', 'Die Seiten des Buches scheinen leer zu sein.', '', 28153),
(143894, 'deDE', 'MiiiAAUUU.', '', 28153),
(143893, 'deDE', 'Halte durch, Kratzi! Hilfe ist auf dem Weg!', 'Halte durch, Kratzi! Hilfe ist auf dem Weg!', 28153),
(143892, 'deDE', 'Komm da runter, Kratzi! Spring! Da oben ist es gefährlich!', 'Komm da runter, Kratzi! Spring! Da oben ist es gefährlich!', 28153),
(143891, 'deDE', 'Spring runter, Kratzi! Ich fang dich auf!', 'Spring runter, Kratzi! Ich fang dich auf!', 28153),
(143890, 'deDE', 'Kraaatzi!! Spring runter!!!', 'Kraaatzi!! Spring runter!!!', 28153),
(143889, 'deDE', '', 'Ich verfütter Euch an meine Tiere, $R!', 28153),
(143888, 'deDE', 'Hier drüben, Champion.', '', 28153),
(143887, 'deDE', 'Hier drüben!', '', 28153),
(143886, 'deDE', 'Achtung!', '', 28153),
(143885, 'deDE', 'Hier entlang.', '', 28153),
(143884, 'deDE', 'Hier lang.', '', 28153),
(143883, 'deDE', 'Vorsicht!', '', 28153),
(143882, 'deDE', 'Hier drüben!', '', 28153),
(143881, 'deDE', 'Hey, Ihr da.', '', 28153),
(143879, 'deDE', 'Läutern!', '', 28153),
(143876, 'deDE', 'Es ist getan.', '', 28153),
(143875, 'deDE', 'Blut! Blut! Blut!', '', 28153),
(143874, 'deDE', 'Zuldazar wird fall\'n!', '', 28153),
(143873, 'deDE', 'Frischfleisch!', '', 28153),
(143872, 'deDE', 'Ich will Euer Blut!', '', 28153),
(143871, 'deDE', 'Eure Knoch\'n werd\'n uns gut dienen!', '', 28153),
(143870, 'deDE', 'Euer Blut für G\'huun!', '', 28153),
(143869, 'deDE', 'Niemand entkommt dem Blutgott!', '', 28153),
(143868, 'deDE', 'Guzincha!', '', 28153),
(143867, 'deDE', 'Kachago!', '', 28153),
(143865, 'deDE', 'Das Kleingedruckte nicht gelesen?\n\nKeine Rückerstattungen. Keine Ausnahmen. Kein Rumjammern.\n\nAber wisst Ihr, was Euch garantiert wieder aufmuntert? Federfuß\' fabulöses Fallen!', '', 28153),
(143864, 'deDE', 'Einmal Federfuß\' fabulöses Fallen, bitte!', 'Einmal Federfuß\' fabulöses Fallen, bitte!', 28153),
(143863, 'deDE', 'Ich will eine Rückerstattung.', 'Ich will eine Rückerstattung.', 28153),
(143862, 'deDE', 'Willkommen zurück, $p!\n\nIhr habt zweifelsohne Eure Zeit bei den fröhlichen Freunden von Federfuß\' fabulösem Fallen genossen.\n\nAls Vollmitglied erhaltet Ihr Zugang zu unbeschränktem langsamen Fall von der Spitze dieser tollen Ziggurat. Lasst es mich wissen, sobald Ihr einen weiteren benötigt.\n\nEs gibt definitiv keine Rückerstattungen.', '', 28153),
(143861, 'deDE', 'Tretet noch heute den Freunden von Federfuß\' fabulösem Fallen bei!\n\nFür eine geringe, einmalige Gebühr erhaltet Ihr Zugang zu unbeschränktem langsamen Fall von der Spitze dieser Ziggurat. Gewährt mit Sicherheit Euer Überleben!\n\nKeine Rückerstattungen.', '', 28153),
(143860, 'deDE', 'Die Winde hier sind noch stärker als am Hochberg. Unsere Entscheidung, der Horde beizutreten, zahlt sich bereits aus.', '', 28153),
(143859, 'deDE', 'Kehrt in den Sturm zurück und findet Frieden. Strömt durch den Schrein und teilt Eure Stärke mit uns!', '', 28153),
(143858, 'deDE', '', 'Was für eine wundervolle Stadt. Es ist so eine Freude, die Welt zu erkunden.', 28153),
(143857, 'deDE', 'Hört unseren Ruf, Gefallene. Eure Untaten seien Euch mit dem heutigen Tag vergeben.', '', 28153),
(143856, 'deDE', 'Wenn Ihr bereit seid, entfesselt die Seelen in der Glocke.', '', 28153),
(143855, 'deDE', 'Es tut mir leid, Rosalinde, aber Ihr müsst warten. Heute haben wir mit Dringenderem als der Jagd zu tun.', '', 28153),
(143854, 'deDE', '', 'He, Therold! Lasst die Faxen. Wir brauchen Euren Segen für die Jagd!', 28153),
(143853, 'deDE', 'Kommt bald wieder, $p!', '', 28153),
(143852, 'deDE', 'Für jeden Bluttroll, den Ihr bespuckt, gibt es zehn Punkte!', '', 28153),
(143851, 'deDE', 'Erzählt auch Euren Freunden von Federfuß\' fabulösem Fallen!', '', 28153),
(143850, 'deDE', 'Schön, Euch wiederzusehen, $p. Fröhliches Fallen!', '', 28153),
(143849, 'deDE', 'Versucht, auf dem Brutosaurus zu landen!', '', 28153),
(143848, 'deDE', 'Versucht, in einem Wasserfall zu landen!', '', 28153),
(143847, 'deDE', 'Passt auf die Pterrordaxe auf!', '', 28153),
(143846, 'deDE', 'Gute Reise, $p.', '', 28153),
(143845, 'deDE', 'Aaaaaaaaaugh!', '', 28153),
(143844, 'deDE', 'Für die Allianz.', '', 28153),
(143843, 'deDE', 'Für die Horde!', '', 28153),
(143842, 'deDE', 'Stromgarde is\' gefallen. Gebt auf, Rogers, un\' rettet Eure Haut.', '', 28153),
(143841, 'deDE', 'Jawohl, sapperlot! Da ist... mein Hammer!', '', 28153),
(143840, 'deDE', 'Klopf, klopf, kleiner Bronzebart. Is\' jemand da?', '', 28153),
(143839, 'deDE', 'Das Licht steht mir weiterhin bei. So leicht werde ich nicht fallen!', '', 28153),
(143838, 'deDE', 'Admiralin Rogers! Wir haben Eure Festung gestürmt! Wo also ist jetzt Eure Vergeltung, Paladin?', '', 28153),
(143837, 'deDE', 'Die glaub\'n, dass uns \'n paar Soldaten auf Pferden aufhalt\'n? Ha! Denen woll\'n wir ma\' zeig\'n, was die Horde draufhat!', '', 28153),
(143836, 'deDE', 'Wir müss\'n die Hochburg schütz\'n. Zerstört die Panzer, bevor sie zu nah ran komm\'!', '', 28153),
(143835, 'deDE', 'Unsere Verteidigung ist immer noch schwach. Hordentruppen, kehrt zur Basis zurück und verteidigt die Stellung!', '', 28153),
(143834, 'deDE', 'Nun gut. Wenn Ihr Krieg wollt, dann sollt Ihr Euren Krieg bekommen. Schickt ein berittenes Bataillon, um sie auszuschalten!', '', 28153),
(143833, 'deDE', 'Der Zirkel der Elemente is\' jetzt unter der Kontrolle von der Horde.', '', 28153),
(143832, 'deDE', 'Neuhof is\' unser und damit auch die Wolfsreiter.', '', 28153),
(143831, 'deDE', 'Das Arsenal is\' bereit, Mann.', '', 28153),
(143830, 'deDE', 'Die Werkstatt is\' fertig. Unsre Verwüster werd\'n mit den Mauern der Allianz kurz\'n Prozess mach\'n!', '', 28153),
(143829, 'deDE', 'Belagerungsmaschinen! Zerstört sie!', '', 28153),
(143828, 'deDE', 'Ich hatte Euch gewarnt, Hordenabschaum. Jetzt macht Euch bereit, vernichtet zu werden.', '', 28153),
(143827, 'deDE', 'Das ganze Land hat den Troll\'n gehört, bevor die Allianz überhaupt wusste, dass es da is\', Turalyon.', '', 28153),
(143826, 'deDE', 'Hmpf. Damit solltet Ihr ins Bild passen.', '', 28153),
(143825, 'deDE', 'Diese Kleidung muss vorerst genügen.', '', 28153),
(143824, 'deDE', 'So, das Wichtigste sin\' Holz und Eisen, damit wir hier \'ne Basis bau\'n können. In der Nähe sollt\'s genug von beidem geb\'n.', '', 28153),
(143823, 'deDE', 'Ich auch, Muradin.', '', 28153),
(143822, 'deDE', 'Vielleicht verbessert diese Kleidung ja Eure Sammelfähigkeiten.', '', 28153),
(143821, 'deDE', 'Pah! Eure Vergeltung könnt Ihr selbst fressen, Turalyon!', '', 28153),
(143820, 'deDE', 'Dieses Land gehört der Allianz! Diese Hordeinvasoren wird schnelle Vergeltung ereilen!', '', 28153),
(143819, 'deDE', 'Heut wird\'s der Horde gehör\'n!', '', 28153),
(143818, 'deDE', 'Lang vor unsrer Zeit war das hier alles Trollland.', '', 28153),
(143817, 'deDE', 'Ah... Es wird mir eine Freude sein. Ihr habt Euch mit dem falschen Zwerg angelegt.', '', 28153),
(143816, 'deDE', 'Muradin! Zeigt Euch, Feigling!', '', 28153),
(143815, 'deDE', 'Unsere Verteidigung ist immer noch schwach. Haltet diese Panzer von unserer Basis fern!', '', 28153),
(143814, 'deDE', 'Nicht halb so hässlich wie Eures, Bronzebart!', '', 28153),
(143813, 'deDE', 'Vergebt mir, Prüferin.', '', 28153),
(143812, 'deDE', 'Es ist mir eine Ehre zu dienen, Prüferin.', '', 28153),
(143811, 'deDE', '', 'Der Kampf is\' vorbei... un\' wir leb\'n noch. Ateena wird für dies\'n Wahnsinn bezahl\'n.', 28153),
(143810, 'deDE', '', 'Seht den Zerstörer von Zuldazar! Versucht nur, uns aufzuhalt\'n... Ihr werdet richtig schön leid\'n!', 28153),
(143809, 'deDE', '', 'Ihr seid weit gekomm\', aber mein Meister wird Euch vernicht\'n!', 28153),
(143808, 'deDE', 'Die Arbeit für die Archäologische Akademie ist strapaziös...', '', 28153),
(143807, 'deDE', 'Ha, zu einfach! Versucht es mal draußen im Feld. Mehr Holz können wir immer brauchen.', '', 28153),
(143806, 'deDE', 'Wie Ihr wünscht, Prüferin.', '', 28153),
(143805, 'deDE', 'Wie auch immer ich zu Diensten sein kann, Prüferin.', '', 28153),
(143804, 'deDE', 'Ich helfe gern, Prüferin.', '', 28153),
(143803, 'deDE', '', 'Euer Körper wird \'n gutes Gefäß für mein\' Meister!', 28153),
(143802, 'deDE', '', 'Die Horde is\' als nächstes dran. Ihr habt Hir\'eek getötet, dafür werdet Ihr zahl\'n! Ihr könnt\' Euch nich\' versteck\'n.', 28153),
(143801, 'deDE', '', 'Zuldazar wird fall\'n... und mein Meister wird endlich frei sein! Eure mickrig\'n Loa werd\'n ihn nich\' aufhalt\'n!', 28153),
(143800, 'deDE', 'Selbstverständlich, Prüferin.', '', 28153),
(143799, 'deDE', 'Bin schon auf dem Weg, Prüferin.', '', 28153),
(143798, 'deDE', '', 'Interessant... Baeloth, kommt her und sagt mir, was Ihr seht.', 28153),
(143797, 'deDE', '', 'Wo wollt Ihr denn hin, Baeloth?! Ich habe noch mehr Erkenntnisse, die Ihr niederschreiben müsst.', 28153),
(143796, 'deDE', '', 'Mein lieber Baeloth, schaut Euch das mal an.', 28153),
(143795, 'deDE', '', 'In der Archäologischen Akademie gibt es keine Verschnaufpausen, Baeloth.', 28153),
(143794, 'deDE', '', 'Baeloth, nicht die Artefakte berühren!', 28153),
(143793, 'deDE', '', 'Das ist fantastisch... Baeloth, kommt rüber und seht Euch an, wie fantastisch das ist!', 28153),
(143792, 'deDE', '', 'Hezrels Schild is\' aktiv. Rein da!', 28153),
(143791, 'deDE', '', 'Baeloth, träumt Ihr schon wieder? Ich könnte Eure Hilfe hier brauchen.', 28153),
(143790, 'deDE', '', 'Baeloth, seid so lieb und schreibt alles nieder, was ich sage.', 28153),
(143789, 'deDE', 'Die Sturmtakler sind auf viele verschiedene Vorräte angewiesen, damit sie Höchstleistungen bringen können! Meine Aufgabe ist es, die Lagerbestände im Auge zu behalten und aufzustocken und zudem defekte Geräte und Dingsbumse zu reparieren!$b$b...$b$bUnd bei ihnen gehen jeden Tag jede Menge Geräte und Dingsbumse zu Bruch.$b$bIhre Feinmotorik lässt ein wenig zu wünschen übrig.', '', 28153),
(143788, 'deDE', '', '$n, kann ich kurz mit Euch reden? Ich könnte Eure Hilfe gebrauchen.', 28153),
(143787, 'deDE', '~<< An event plays out where me and the laborers walk towards the causeway with cannons. >>', '', 28153),
(143786, 'deDE', 'Hodor! Äh... T\'paartos!', '', 28153),
(143785, 'deDE', 'Es scheint, als seien sie auf meine Maskerade hereingefallen! Es ist außerordentlich bemerkenswert, dass sie glauben, ich könne so minderbemittelt sein, um... Was sagt Ihr, sie können mich hören? Ich,... äh... T\'paartos!', '', 28153),
(143784, 'deDE', 'Dinge, die T\'paartos nicht mag: Schlangen, böse Kinder, Schlangen, dunkle Höhlen, Schlangen... und mickrige Wesen, die T\'paartos ärgern.', '', 28153),
(143783, 'deDE', 'Sicher, T\'paartos hat Bücher gelesen. Bücher mit wenig Wörtern und viel Bildern... aber die gelten trotzdem.', '', 28153),
(143782, 'deDE', 'Versucht Ihr, T\'paartos\' Gutmütigkeit auszunutzen, mickriges Wesen?', '', 28153),
(143781, 'deDE', 'T\'paartos hat immer noch ein wenig Angst vor Schlangen.', '', 28153),
(143780, 'deDE', 'T\'paartos ist stolz ein Lichtgeschmiedeter zu sein!', '', 28153),
(143779, 'deDE', 'Schaut wieder bei T\'paartos vorbei.', '', 28153),
(143778, 'deDE', 'T\'paartos muss jetzt wieder an die Arbeit.', '', 28153),
(143777, 'deDE', 'T\'paartos hat viel zu tun.', '', 28153),
(143776, 'deDE', 'T\'paartos wird Euch bald wiedersehen.', '', 28153),
(143775, 'deDE', 'T\'paartos.', '', 28153),
(143774, 'deDE', 'Beeilt Euch, $n. Es stehen Leben auf dem Spiel.', '', 28153),
(143773, 'deDE', 'T\'paartos ist bereit!', '', 28153),
(143772, 'deDE', 'Möge das Licht mit Euch sein.', '', 28153),
(143771, 'deDE', 'Gefahr? T\'paartos fürchtet keine Gefahr!', '', 28153),
(143770, 'deDE', 'Braucht Ihr etwas von T\'paartos, mickriges Wesen?', '', 28153),
(143769, 'deDE', 'T\'paartos grüßt Euch, mickriges Wesen.', '', 28153),
(143768, 'deDE', 'T\'paartos?', '', 28153),
(143767, 'deDE', 'T\'paartos!', '', 28153),
(143766, 'deDE', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s beginnt, |cFFFF0000|Hspell:259610|h[Blutige Apokalypse]|h|r zu wirken! In Deckung!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s beginnt, |cFFFF0000|Hspell:259610|h[Blutige Apokalypse]|h|r zu wirken! In Deckung!', 28153),
(143765, 'deDE', '', 'Kämpft! Wehrt Euch! Euer Leiden nährt meinen Meister!', 28153),
(143764, 'deDE', 'Jaina? Wohl eher... äh... ach, Ihr könnt nicht erwarten, dass ich jedes Mal einen Volltreffer lande.', '', 28153),
(143763, 'deDE', 'Bitte lasst mich mit Khadgar in Ruhe. Seine Witze sind eine einzige Khadgarstrophe.', '', 28153),
(143762, 'deDE', 'Kirin Tor? Wohl eher Klimbim Tor. Stimmt doch, oder?', '', 28153),
(143761, 'deDE', 'Wenn Ihr einfach das tätet, was ich Euch sage, anstatt zu versuchen, für Euch selbst zu denken, wäre Azeroth sehr viel besser dran.', '', 28153),
(143760, 'deDE', 'Uns in den Weg zu kommen wäre nicht weise.', '', 28153),
(143759, 'deDE', 'Für Quel\'Thalas.', '', 28153),
(143758, 'deDE', 'Wir haben so manches bewältigt.', '', 28153),
(143757, 'deDE', 'Tradition ist der Grundstein für unsere Zukunft.', '', 28153),
(143756, 'deDE', 'Zurück an die Arbeit mit Euch.', '', 28153),
(143755, 'deDE', 'Wir brauchen keine Hilfe von Fremden.', '', 28153),
(143754, 'deDE', 'Achtet unsere Bräuche.', '', 28153),
(143753, 'deDE', 'Die ewige Sonne leitet uns weiterhin.', '', 28153),
(143752, 'deDE', 'Was wollt Ihr von mir?', '', 28153),
(143751, 'deDE', 'Ich diene Silbermond.', '', 28153),
(143750, 'deDE', 'Ich bin beschäftigt.', '', 28153),
(143749, 'deDE', 'Verschwendet keine Ressourcen.', '', 28153),
(143748, 'deDE', 'Was verlangt Ihr?', '', 28153),
(143747, 'deDE', 'Der Sonnenbrunnen muss beschützt werden.', '', 28153),
(143746, 'deDE', 'Nehmt dies als Zeichen meines Dankes.', '', 28153),
(143745, 'deDE', '', 'Pläne? Ich unschuldiges kleines Ding? Was für Pläne könnte ich schon verfolgen?', 28153),
(143744, 'deDE', '', 'Denkt Ihr, ich bekomme nicht mit, wie Ihr meine Dunklen Waldläuferinnen anstarrt? Ich schlage vor, Ihr haltet Eure Augen – und Gedanken – in Zaum.', 28153),
(143743, 'deDE', '', 'Ich habe Eure Entwicklung verfolgt. Es scheint, als müsste ich Euch für Nachhilfeeinheiten zu Nathanos schicken.', 28153),
(143742, 'deDE', '', 'Ich bin doch sicherlich Eure Lieblingswindläuferschwester... oder? Oder!?', 28153),
(143741, 'deDE', '', 'Das Lebensblut von Azeroth gehört der Horde!', 28153),
(143740, 'deDE', 'Ich habe schon kaum noch an die Existenz eines solchen Wesens geglaubt!', '', 28153),
(143739, 'deDE', '', 'Wir werden uns nehmen, was uns gehört.', 28153),
(143738, 'deDE', '', 'Alle werden irgendwann der Horde dienen.', 28153),
(143737, 'deDE', '', 'Ich werde die Reihen der Verlassenen stärken. Egal mit welchen Mitteln.', 28153),
(143736, 'deDE', '', 'Wir werden die Allianz in die Knie zwingen.', 28153),
(143735, 'deDE', '', 'Dient der Horde. Dient mir.', 28153),
(143734, 'deDE', 'Es ist wunderschön!', '', 28153),
(143733, 'deDE', '', 'Geht. Ich habe viel zu tun.', 28153),
(143732, 'deDE', '', 'Dient mir gut und Ihr sollt belohnt werden.', 28153),
(143731, 'deDE', '', 'Die Horde erwartet eine neue Zukunft!', 28153),
(143730, 'deDE', '', 'Die wahre Arbeit fängt gerade erst an.', 28153),
(143729, 'deDE', '', 'Grüße, Champion.', 28153),
(143728, 'deDE', '', 'Tretet vor.', 28153),
(143727, 'deDE', '', 'Ich hoffe, Ihr verschwendet nicht meine Zeit.', 28153),
(143726, 'deDE', '', 'Tragt Eurem Kriegshäuptling Euer Anliegen vor.', 28153),
(143725, 'deDE', '', 'Die Elementare Zandalars haben viel durchgemacht. Wir müssen die dunklen Schamanen aufhalten, die ihre Macht zu selbstsüchtigen Zwecken missbrauchen.', 28153),
(143724, 'deDE', 'Ich heiße Berthold, Berthold Brauner, und ich bin ein wenig in Pferde vernarrt.\n\nMan munkelt, dass sich auf einem Berg westlich dieses Resorts ein majestätisches Pferdewesen herumtreibt. Ich habe angefangen, hier zu arbeiten, damit ich vielleicht einmal in meiner Pause dieses Wesen erblicken kann.\n\nIch würde so viel dafür geben, so etwas mit eigenen Augen zu sehen...', '', 28153),
(143721, 'deDE', 'Bestätige. Titanenhüter Hezrel nicht mehr an Position gebunden. Auf dem Weg in Gebiet genannt Zul\'Nazman.', '', 28153),
(143720, 'deDE', '', 'Hezrel, die Bluttrolle sammeln sich in Zul\'Nazman. Wenn Ihr uns helf\'n wollt, solltet Ihr dort hingeh\'n.', 28153),
(143719, 'deDE', 'Kauft mir \'nen Drink, $PR.\n\nMein Volk hat die Welt gerettet, während Ihr weggerannt seid und Euch im Nebel versteckt habt.\n\nIhr schuldet mir \'nen Drink.', '', 28153),
(143718, 'deDE', 'Titanenhüter Hezrels Systeme auf 50%. Muss verbleibende Energie sparen für Auslöschung der Bluttrolle.', '', 28153),
(143717, 'deDE', 'Das war mal meine Mischerei. Die königliche Familie hat hier Gäste aus der ganzen Welt unterhalt\'n und ich hab sie mit meinen Getränk\'n erfreut.\n\nJetzt ist sie \'ne dreckige Kaschemme für dreckige Fremdlinge und ihre hässlichen Freunde. Was \'ne Schande.', '', 28153),
(143716, 'deDE', 'Ich respektier einige der Goblinkartelle. Neutral und stark; willens, alles Notwendige zu tun. Wie die Zandalari... nur schlechter, natürlich.\n\nAber Ihr Bilgewässer seid \'ne Schande. Habt Euch mit den Elfen un\' der Horde eingelass\'n. Nix als Verräter.', '', 28153),
(143715, 'deDE', 'Fühlt meine Macht!', '', 28153),
(143714, 'deDE', 'Ich mag die Art, wie Eure Horde vorgeht, $p. Starke Anführer. Vereint in ihr\'m Ziel. Stabile Versorgungslinien.\n\nRekrutiert ihr?', '', 28153),
(143713, 'deDE', 'Ich bin bereit, einen weiteren Verbündeten um Unterstützung zu ersuchen.', 'Ich bin bereit, einen weiteren Verbündeten um Unterstützung zu ersuchen.', 28153),
(143712, 'deDE', '', 'Endlich ist das endlose Taktieren von Horde und Allianz vorbei.$b$bDie Zeit ist reif für Krieg.', 28153),
(143711, 'deDE', 'War immer \'ne Überraschung für mich, dass Ihr Dunkelspeere der Horde beigetret\'n seid. Wart immer zu schwach, auf eignen Beinen zu steh\'n, schätze ich.\n\nWie geht\'s Vol\'jin?', '', 28153),
(143710, 'deDE', 'Hey, Elf. Die Bar gehört mir nich\' mehr, also muss ich auch nich\' so tun, als würd ich Euch mögen.\n\nGeht mir ausm Sichtfeld, dreckiger Elf.', '', 28153),
(143709, 'deDE', 'Ihr seht durstig aus. Trinkt was. Bleibt und unterhaltet Euch für \'ne Weile.\n\nZuldazar gibt\'s schon seit Urzeiten. Es wird nich\' über Nacht verschwind\'n.', '', 28153),
(143708, 'deDE', 'Ich hör, einige von Euch geh\'n Richtung Nazmir. Drückt Euch vor der Aufgabe, wenn Ihr könnt. Ausm Sumpf is\' schon seit Generationen nix Gutes gekomm\'n.', '', 28153),
(143707, 'deDE', 'Wie ich hör, rumort\'s in den Sand\'n von Vol\'dun noch mehr als sonst. Vorsicht, wenn Ihr in die Richtung wollt.', '', 28153),
(143706, 'deDE', 'Mein Volk hat zu Anbeginn der Zeit die Zivilisation begründet und den Rest von Euch Schmarotzern die ganze Zeit mitgezog\'n.\n\nSagt mal, $PR, was hat Euer Volk je gemacht, das es wert wäre, sich dran zu erinnern?\n\nMir fällt da nix ein.', '', 28153),
(143705, 'deDE', '(Springt auf Hezrels Schulter, um zum Trübsumpf zurückzukehren.)', '(Springt auf Hezrels Schulter, um zum Trübsumpf zurückzukehren.)', 28153),
(143704, 'deDE', 'Reparatur der Eindämmung von G\'huun fehlgeschlagen. Muss Bluttrolle aufhalten, die Zuldazar zerstören wollen, um vollständige Befreiung von G\'huun zu verhindern.\n\nGebäude von Bluttrollen umzingelt. Titanenhüter Hezrel wird Sicherheit von $n und Prinzessin Talanji sicherstellen.\n\nSpringt auf meine Schultern. Köpfe einziehen.', '', 28153),
(143703, 'deDE', 'Widerlich. Ekelhaft. Ihr stinkt schlimmer als \'n Bluttroll.\n\nWürd mir die Bar noch gehör\'n, würd ich Euch mit dem Müll rauskehr\'n.', '', 28153),
(143702, 'deDE', 'Habt Ihr was darüber gehört, was außerhalb der Stadt los is\'?', '', 28153),
(143700, 'deDE', 'Gallywix ist in Silithus aktiv. Begebt Euch sofort dorthin. Und falls Ihr auf die Allianz trefft, macht kurzen Prozess mit ihnen.', '', 28153),
(143699, 'deDE', 'Wir haben eine provisorische Basis in Silithus errichtet. Meldet Euch bei unseren Kräften vor Ort – und behaltet die Horde im Auge.', '', 28153),
(143698, 'deDE', 'Ihr Orcs könnt trink\'n. Das respektier ich.\n\nAber sagt Euern Fatzkenfreunden von den Elfen, sie soll\'n draußen bleib\'n, klar?', '', 28153),
(143697, 'deDE', 'Alleria und Turalyon? Das wird niemals gutgehen. Nicht, dass ich irgendetwas gegen sie hätte, aber... Ach, warum beteilige ich mich überhaupt an solchem Promiklatsch?', '', 28153),
(143696, 'deDE', 'Ich verstehe manchmal, warum Elfen nicht sonderlich beliebt sind. Schließlich ist die eine Hälfte von uns der anderen ebenfalls in herzlicher Abneigung verbunden.', '', 28153),
(143695, 'deDE', 'Ich gebe zu, Lila war nie meine Farbe, aber in letzter Zeit ist sie mir ans Herz gewachsen. Im wahrsten Sinne des Wortes.', '', 28153),
(143694, 'deDE', 'Ein Hochelf? Ich bitte Euch. Warum würde man ein Hochelf sein wollen? Melancholisch und missmutig ist doch viel angesagter!', '', 28153),
(143693, 'deDE', 'Verliert nie die Konzentration. Behaltet stets die Kontrolle.', '', 28153),
(143692, 'deDE', 'Gebt nicht dem Flüstern nach.', '', 28153),
(143691, 'deDE', 'Seid offen für alle Möglichkeiten.', '', 28153),
(143690, 'deDE', 'Mögen die Schatten über Euch wachen.', '', 28153),
(143689, 'deDE', 'Wir dienen der Allianz.', '', 28153),
(143688, 'deDE', 'Das Licht ist nicht der einzige Weg.', '', 28153),
(143687, 'deDE', 'Die Ren\'dorei werden beweisen, dass sie würdig sind.', '', 28153),
(143686, 'deDE', 'Ihr könnt so viel von mir lernen.', '', 28153),
(143685, 'deDE', 'Öffnet Euren Geist.', '', 28153),
(143684, 'deDE', 'Alle Wege stehen uns offen.', '', 28153),
(143683, 'deDE', 'Wir nutzen die Macht. Wir fürchten sie nicht.', '', 28153),
(143682, 'deDE', 'Die Schatten dienen uns.', '', 28153),
(143681, 'deDE', 'Bal\'a dash, malanore.', '', 28153),
(143680, 'deDE', 'Ich grüße Euch.', '', 28153),
(143679, 'deDE', 'Meine Augenklappe hat niemals die Stelle gewechselt! Ich meine... so etwas würde einem doch auffallen, oder?', '', 28153),
(143678, 'deDE', 'Für Sylvanas zu arbeiten, ist manchmal nicht einfach. Sie war ja schon immer etwas herrisch, aber seit ihrem Untod... Na ja... Äh, bitte erzählt ihr das nicht, ja?', '', 28153),
(143677, 'deDE', 'Sylvanas\' Champion hin oder her: Im Umgang mit dem Bogen hat Nathanos keine Chance gegen mich.', '', 28153),
(143676, 'deDE', 'Solches Haar bekommt man nicht von selbst. Es erfordert ständige Pflege.', '', 28153),
(143675, 'deDE', 'Niemals wieder soll ein König in Silbermond herrschen.', '', 28153),
(143674, 'deDE', 'Unsere Nation wird sich erheben.', '', 28153),
(143673, 'deDE', 'Al diel shala.', '', 28153),
(143672, 'deDE', 'Die Horde gibt uns Stärke.', '', 28153),
(143671, 'deDE', 'Was ich tue, tue ich für Quel\'Thalas.', '', 28153),
(143670, 'deDE', 'Möge das Licht des Sonnenbrunnens mit Euch sein.', '', 28153),
(143669, 'deDE', 'Silbermond wird wieder erblühen.', '', 28153),
(143668, 'deDE', 'Die Pracht des Immersangwalds wird überdauern.', '', 28153),
(143667, 'deDE', 'Die ewige Sonne leitet uns weiterhin.', '', 28153),
(143666, 'deDE', 'Der Wiederaufbau schreitet voran.', '', 28153),
(143665, 'deDE', 'Wir haben viele Opfer gebracht.', '', 28153),
(143664, 'deDE', 'Es ist mir eine Ehre als Lordregent zu dienen.', '', 28153),
(143663, 'deDE', 'Bal\'a dash, malanore.', '', 28153),
(143662, 'deDE', 'Ich grüße Euch im Namen Silbermonds.', '', 28153),
(143651, 'deDE', 'Oh, ich glaube, ich habe einen großen erwischt!', '', 28153),
(143650, 'deDE', 'PLATZHALTERSZENE - Hezrel offenbart, dass G\'huun ein Alter Gott ist, mit dem Experimente durchgeführt wurden. Er sagt, dass die Bluttrolle Zuldazar zerstören wollen, um G\'huun zu befreien. Aktuelle Eindämmung kann nicht repariert werden. Zuldazar muss beschützt werden. Ateena, eine Matriarchin der Bluttrolle, erscheint, beschädigt Hezrel stark und macht sich zum Angriff bereit.', 'PLATZHALTERSZENE - Hezrel spricht darüber, dass G\'huun ein Alter Gott ist, mit dem Experimente durchgeführt wurden. Er sagt, dass die Bluttrolle Zuldazar zerstören wollen, um G\'huun zu befreien. Aktuelle Eindämmung kann nicht repariert werden. Zuldazar muss beschützt werden. Ateena, eine Matriarchin der Bluttrolle, erscheint, verwundet Hezrel stark und macht sich zum finalen Schlag bereit.', 28153),
(143649, 'deDE', '', 'Zurück, $R! Seine Stimme gehört mir!', 28153),
(143648, 'deDE', '', 'Solch eine... Macht... hier...', 28153),
(143647, 'deDE', '', 'Vorsicht, Umbric. Antworten auf solche Fragen haben oft ihren Preis.', 28153),
(143646, 'deDE', 'Dieser Würfel zum Beispiel. Ein uralter Mechanismus, vielleicht sogar älter als das Leben auf Azeroth selbst. Er scheint verschlossen und bisher konnten wir ihn noch nicht öffnen.', '', 28153),
(143645, 'deDE', 'In der Tat! Wie auch Ihr glauben wir, dass die Leere zum Schutz des Lebens eingesetzt werden kann, nicht nur, um es zu verschlingen. Wir haben große Fortschritte gemacht, Lady Windläufer, doch viele Fragen bleiben noch offen.', '', 28153),
(143644, 'deDE', '', 'Ein andermal vielleicht. Der Champion und ich haben nach Euch gesucht. Wir wissen, dass Ihr aus Silbermond verbannt wurdet. Ich denke, wir haben einiges gemeinsam.', 28153),
(143643, 'deDE', 'Mein Volk und ich haben Geschichten davon gehört, was sich auf Argus zugetragen hat. Wie Ihr Euch vorstellen könnt, interessieren wir uns sehr für Eure Begegnung mit dem dunklen Naaru.', '', 28153),
(143642, 'deDE', 'Alleria Windläufer!? Wie habt Ihr... Was für eine unerwartete Ehre!', '', 28153),
(143641, 'deDE', '', 'Magister Umbric! Ich bin Alleria Windläufer.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143640, 'deDE', '', 'Da vorn. Das muss Umbric sein.', 28153),
(143639, 'deDE', '', 'Mit Hilfe dieser Notizen kann ich den Weg in diese Welt erneut öffnen. Lasst mich sehen...', 28153),
(143638, 'deDE', '', '<Landing from jump: Total 3>', 28153),
(143637, 'deDE', 'Drathir vermutete, dass dieser Riss ein uraltes Objekt von unaussprechlicher Macht birgt. Vielleicht ist das der Schlüssel, um Kontrolle über die Schatten zu erlangen.', '', 28153),
(143636, 'deDE', 'Laut seinen Aufzeichnungen existierte es in einem Riss im Gewebe der Realität. Er hat den Ort nie gefunden... aber ich war erfolgreich, wo er versagte. Der Weg wird uns bald offen stehen!', '', 28153),
(143635, 'deDE', 'In seinem Streben nach Macht suchte Drathir nach den Fragmenten einer uralten Welt, ein Reich am Rande der Leere selbst.', '', 28153),
(143634, 'deDE', '<Landing from jump: Total 3>', '', 28153),
(143633, 'deDE', '', 'Kommt. Wir müssen uns auf den Weg machen zum Morgensternturm.', 28153),
(143632, 'deDE', 'Dennoch glaube ich, dass dieses Wissen zum Guten genutzt werden kann. Drathir führte seine Experimente meist im Morgensternturm durch. Lasst uns dorthin aufbrechen.', '', 28153),
(143631, 'deDE', 'Durch Drathirs Verrat gelang es Arthas, den Sonnenbrunnen zu verderben... und unser Königreich in Ruinen zu verwandeln. Zum ersten Mal verstehe ich, warum Rommath sich gegen unsere Forschung stellt.', '', 28153),
(143630, 'deDE', 'Anscheinend sind wir nicht die Ersten unseres Volkes, die versuchen, die Leere nutzbar zu machen. Ich habe Notizbücher gefunden von jemandem, dessen bloßer Name als Fluch gilt... Dar\'Khan Drathir.', '', 28153),
(143629, 'deDE', '<Landing from jump: Total 3>', '', 28153),
(143628, 'deDE', '', 'Wie es scheint, haben wir einige Notizen gefunden.', 28153),
(143627, 'deDE', '', '<Landing from jump: Total 3>', 28153),
(143626, 'deDE', 'Leider kommt unsere Forschung derzeit nicht voran. Ich glaube aber, in Andiliens Grund liegt Wissen verborgen, das uns weiterhelfen wird.', '', 28153),
(143625, 'deDE', 'Der Großmagister muss verstehen, dass diese Kraft für die Verteidigung Silbermonds unerlässlich ist. Nie wieder werden die Sin\'dorei ihren Feinden ausgeliefert sein!', '', 28153),
(143624, 'deDE', 'Unsere Leerenexperimente schreiten gut voran. Ich bin sicher, dass wir kurz vor dem Durchbruch stehen... trotz der engstirnigen Bedenken von Rommath.', '', 28153),
(143623, 'deDE', '<Landing from jump: Total 3>', '', 28153),
(143622, 'deDE', '', '<Landing from jump: Total 3>', 28153),
(143621, 'deDE', '<Distressed cry: Total 3>', '', 28153),
(143620, 'deDE', '<Landing from jump: Total 3>', '', 28153),
(143619, 'deDE', 'Hezrel, startet Eure Scans, um eine Lösung für diese Verderbnis der Alten Götter in Nazmir zu finden.', 'Hezrel, startet Eure Scans, um eine Lösung für diese Verderbnis der Alten Götter in Nazmir zu finden.', 28153),
(143618, 'deDE', 'Mal sehen, ob diese Fische anbeißen wollen!', '', 28153),
(143617, 'deDE', '', '<Landing from jump: Total 3>', 28153),
(143616, 'deDE', '', 'In diesen Wäldern waren meine Schwestern und ich so glücklich. Sie so zu sehen... füllt mein Herz mit Kummer.', 28153),
(143615, 'deDE', 'Gemeinsam werden wir sie eines Besseren belehren.', '', 28153),
(143614, 'deDE', 'Es wird einige Zeit dauern, bis wir uns an unsere neue Gestalt gewöhnt haben. Wir freuen uns auf Eure Rückkehr, Lady Windläufer. Und Euch, $p, gilt unser tiefster Dank.', '', 28153),
(143613, 'deDE', '', 'Im Gegenzug verspreche ich, Euch auf Eurem Weg zur Seite zu stehen. $p und ich werden Hochkönig Wrynn hiervon berichten. Danach kehre ich zurück, um Euch auszubilden.', 28153),
(143612, 'deDE', 'Silbermond hat uns vor langer Zeit den Rücken gekehrt. Heute wurden wir wiedergeboren... und es ist passend, einen neuen Pfad einzuschlagen. Fortan gilt unsere Treue der Allianz.', '', 28153),
(143611, 'deDE', '', 'Ich spüre die beachtlichen Kräfte, über die Ihr gebietet. Ihr wärt ein wertvoller Verbündeter für die Allianz.', 28153),
(143610, 'deDE', 'Mein Hochmut wäre beinah unser Untergang gewesen. Ich ließ mich mit Kräften ein, die ich nicht beherrschte. Bitte, Alleria, lehrt uns den Weg und wir werden Euch folgen.', '', 28153),
(143609, 'deDE', '', 'Ich habe den Bau einer Botschaft in Orgrimmar genehmigt. Von dort aus werden wir andere für unsere Sache gewinnen. Trefft mich dort unverzüglich.', 28153),
(143608, 'deDE', '', 'Durch die selbstlose Aufopferung der Horde gegen die Legion sind unsere Reihen geschwächt. Unsere Feinde lecken sich die Finger nach unserem Eigentum. Wir werden sie nicht gewähren lassen.', 28153),
(143607, 'deDE', '', 'Ihr habt unsere Aktivitäten in Silithus gesehen, $p. Die Allianz versucht mit aller Macht, unseren Fortschritt zu untergraben.', 28153),
(143606, 'deDE', 'Es wird Zeit, dass die Allianz neue Verbündete gewinnt. Wir haben eine Botschaft in Sturmwind eingerichtet, um das zu erreichen. Trefft mich dort.', '', 28153),
(143605, 'deDE', 'Die Horde macht vor nichts halt, das Lebensblut von Azeroth für sich zu beanspruchen. Ich fürchte, wir sind nach dem Krieg gegen die Legion zu geschwächt, um sie aufzuhalten.', '', 28153),
(143604, 'deDE', 'Ihr habt die Verheerung in Silithus mit eigenen Augen gesehen. Ihr wisst, was auf dem Spiel steht.', '', 28153),
(143603, 'deDE', 'Trefft mich außerhalb der Feste Grommash. Aber verliert kein Wort darüber... sonst könnte das unangenehme Konsequenzen haben.', '', 28153),
(143602, 'deDE', 'Wir haben wichtige Informationen erhalten. Für die Interessen der Horde ist es unabdingbar, der Allianz einen Schritt vorauszubleiben.', '', 28153),
(143601, 'deDE', '$p! Die Dunkle Fürstin befiehlt Euch, mich in Orgrimmar zu treffen.', '', 28153),
(143600, 'deDE', 'Trefft mich bei der Löwenruh. Ich muss wohl nicht erwähnen, dass unsere Unterhaltung geheim ist.', '', 28153),
(143599, 'deDE', 'Wir haben... vertrauliche Informationen entdeckt, die er Euch zeigen möchte.', '', 28153),
(143598, 'deDE', '$p, Hochkönig Wrynn wünscht, dass Ihr mich in Sturmwind trefft.', '', 28153),
(143597, 'deDE', 'Ich hab noch so\'n Fremdling hier mitgebracht. Er will mit Euch sprech\'n, mächtiger Loa.', '', 28153),
(143596, 'deDE', '', 'Die Nachtgeborenen sind ein weises und mächtiges Volk. Das uralte Wissen in Eurem Besitz könnte unserer Sache von großem Nutzen sein.', 28153),
(143595, 'deDE', '', 'Genug der schönen Worte. Ihr habt einiges zu beweisen. Wo immer Euer Pfad Euch auch hinführt, vergesst nicht: Ihr kämpft für die Horde!', 28153),
(143594, 'deDE', '', 'Seid versichert, ich werde Euren Fortschritt verfolgen. Als Kriegshäuptling erwarte ich viel von Euch... aber ich belohne auch jene, die mir gut dienen.', 28153),
(143593, 'deDE', '', 'Die Horde hat viele Rivalen in dieser Welt. Manche sehen uns als ihre Feinde... andere nennen uns Ausgestoßene. Doch wir schöpfen Stärke aus Einheit... und wir stellen uns allen entgegen, die uns unsere Freiheit nehmen wollen.', 28153),
(143592, 'deDE', '', 'Die Hochbergtauren sind berühmt für ihren Mut und ihre Stärke. Wir werden solche Qualitäten brauchen.', 28153),
(143591, 'deDE', '', 'Ah, unser junger Champion $p. Man hat mir erzählt, dass Ihr großes Potenzial zeigt. Hoffen wir, dass diese Berichte wahr sind.', 28153),
(143590, 'deDE', 'Glück auf Euren Wegen, $p. Möge stets das Licht mit Euch sein.', '', 28153),
(143589, 'deDE', 'Die Leerenelfen sind unserem Bündnis zwar erst vor Kurzem beigetreten, aber Alleria Windläufer ist eine unserer größten Helden. Unter ihrer Anleitung werden Eure Kräfte unserer Sache gut dienen.', '', 28153),
(143588, 'deDE', 'Wir werden dieses Land von Euch befreien!', '', 28153),
(143587, 'deDE', 'Glück auf Euren Wegen, $p. Auch wenn Ihr in den Schatten wandelt, Ihr seid ein Leuchtfeuer der Hoffnung für uns.', '', 28153),
(143586, 'deDE', 'Ich freue mich darauf, von Euren Fortschritten zu hören. Etwas sagt mir, dass wir bald wieder miteinander sprechen werden.', '', 28153),
(143585, 'deDE', 'Es ziehen schwere Zeiten auf für Azeroth. In den kommenden Tagen werdet Ihr viele Prüfungen bestehen... viele Feinde bekämpfen müssen. Doch vergesst nicht: Ihr seid nicht allein im Kampf gegen die Finsternis. Die Allianz steht an Eurer Seite.', '', 28153),
(143584, 'deDE', 'Die Lichtgeschmiedeten sind zwar erst seit Kurzem Mitglied der Allianz, aber ich kenne die Draenei gut. Ich bin sicher, dass Ihr die Hingabe und den Mut der Armee des Lichts verkörpern werdet.', '', 28153),
(143583, 'deDE', 'Willkommen, $p. Ich bin König Anduin Wrynn. Als neues Mitglied der Allianz wollte ich Euch persönlich begrüßen.', '', 28153),
(143582, 'deDE', 'Ich brauche Heilung!', '', 28153),
(143581, 'deDE', 'Besorgt Euch Euer eigenes Werk!', '', 28153),
(143580, 'deDE', 'In was für eine interessante und obskure kleine Ecke der Welt uns die Horde hier gebracht hat.\n\nIch hoffe doch, dass die anderen Einrichtungen unserer Fraktion eleganter und sauberer als diese hier sein werden?', '', 28153),
(143579, 'deDE', 'Vergebt mir, $p.\n\nIch würde mich gern mit Euch unterhalten, aber ich glaube, mir wird gerade schlecht.\n\nHaltet Euch von diesem Wein fern.', '', 28153),
(143578, 'deDE', '<Weinhändler Thesnala starrt den Schankwirt finster an, während er das Weinglas langsam auf den Boden auskippt.>', '', 28153),
(143577, 'deDE', 'Habt Ihr schon den Wein hier gekostet?\n\nDas müsst Ihr einfach tun. Der Geschmack ist unglaublich abstoßend.\n\nBarden könnten Lieder über seine legendär grauenhafte Textur schreiben.\n\nWahrlich ein Höhenflug der Weinkunst, die es sich zum Ziel gemacht hat, die Geschmacksknospen absterben zu lassen.', '', 28153),
(143576, 'deDE', 'Bisher traue ich den Zandalari zu, große, unansehnliche Gebäude zu errichten.\n\nIch traue es ihnen NICHT zu, Wein herzustellen.', '', 28153),
(143575, 'deDE', 'Wenn man keinen guten Wein herstellen kann, sollte man am besten gar keinen herstellen.', '', 28153),
(143574, 'deDE', 'Kauft mir doch ein zweites Glas davon, damit ich diese dreckige Brühe erneut auf den Boden spucken kann.', '', 28153),
(143573, 'deDE', 'Dieses Gesöff schimpft sich hier Wein? Kein Wunder, dass die Trolle die Stadt verlassen.', '', 28153),
(143572, 'deDE', 'Wir sind endlich frei! Schnell, nichts wie raus hier!', 'Wir sind endlich frei! Schnell, nichts wie raus hier!', 28153),
(143571, 'deDE', 'Diese hölzernen Monstrositäten sind wie aus einem Alptraum!', '', 28153),
(143569, 'deDE', 'Dafür gibt\'s... besser eine... saftige Gefahrenzulage...', 'Dafür gibt\'s... besser eine... saftige Gefahrenzulage...', 28153),
(143568, 'deDE', '', 'Selbst so verwüstet kommt mir das hier irgendwie bekannt vor...', 28153),
(143567, 'deDE', 'Strengt Euch mal an, Ihr faulen Säcke!', 'Strengt Euch mal an, Ihr faulen Säcke!', 28153),
(143566, 'deDE', 'Bauwerkinneres sicher. Entität genannt \"Prinzessin Talanji\" anwesend.', '', 28153),
(143565, 'deDE', 'Es ist so weit. Auf nach Korlach!', '', 28153),
(143562, 'deDE', 'Zu spät. G\'huun lässt sich nicht bändigen. Alle werden fallen. Alle werden sterben.', '', 28153),
(143561, 'deDE', 'Euer Ende naht. G\'huun wird frei sein. Azeroth gehört uns.', '', 28153),
(143560, 'deDE', 'Packt Eure Wertsach\'n in den Tresor un\' geht wieder, $p.\n\nIch behalt Euch im Auge...', '', 28153),
(143559, 'deDE', 'Das sind finstere Zeiten für Drustvar, aber wir werden uns unser Land zurückholen!', '', 28153),
(143558, 'deDE', 'Für Zandalar!', '', 28153),
(143557, 'deDE', 'Rezan, geh\'n wir auf die Jagd.', '', 28153),
(143556, 'deDE', 'Ja. Wir warten nur auf das Kommando des Festländers.', '', 28153),
(143555, 'deDE', 'Pa\'ku, Loa der Winde, steigt in die Lüfte und spürt die Ketzer auf. Findet raus, was sie vorhab\'n und trefft uns am Tempel.', '', 28153),
(143554, 'deDE', 'Gonk, Loa der Jagd, führt Eure Anhänger zum Tempel des Propheten und macht alle Feinde nieder. Jagt uns\'re Widersacher aus ihrem Versteck.', '', 28153),
(143553, 'deDE', 'Brüder und Schwestern von Zandalar, es is\' Zeit, alle Verräter, die Zul folg\'n, \'nen Kopf kürzer zu mach\'n.', '', 28153),
(143552, 'deDE', '', 'Wir anderen müssen uns auf den Ritt nach Korlach vorbereiten. Marschall, wie ich höre, habt Ihr einen Angriffsplan?', 28153),
(143551, 'deDE', '', 'Jawohl, Fräulein!', 28153),
(143550, 'deDE', '', 'Bringt Meister Eschtal in Falkenforst die Formel für alchemistisches Feuer. Er sollte sich damit auskennen.', 28153),
(143549, 'deDE', '', 'Glücklicherweise kenne ich einen fachkundigen Alchemisten in Falkenforst südlich von hier. Die Wälder sind gefährlich, also werdet Ihr über die alten Bergpfade dorthin reisen müssen.', 28153),
(143548, 'deDE', '', 'Im Folianten ist eine Formel für alchemistisches Feuer, aber wir haben hier niemanden, der es herstellen könnte.', 28153),
(143547, 'deDE', '', 'Wenn wir den Zirkel endgültig bezwingen wollen, brauchen wir mehr als Silber. Wir brauchen Feuer.', 28153),
(143546, 'deDE', '', 'Danke, Marschall! Was kann ich für Euch tun, Herrin?', 28153),
(143545, 'deDE', 'Hauptmann Morgenlicht – Verzeihung, Inquisitorin Morgenlicht ist höchst zuverlässig. Ich bin sicher, sie kann jede Aufgabe zu Eurer Zufriedenheit meistern.', '', 28153),
(143544, 'deDE', '', 'Wen schlagt Ihr vor, Marschall?', 28153),
(143543, 'deDE', '', 'So, bevor wir gehen, brauche ich jemanden, der für den Orden eine besondere Aufgabe übernimmt.', 28153),
(143542, 'deDE', 'Ist es zu glauben, dass die Horde nie ein offizielles Amt für Telemantie eingerichtet hat? Ich meine, es ist mir unbegreiflich, wie die Bevölkerung ohne jegliche Sicherheitsvorkehrungen reisen konnte. Allein der Gedanke an all diese willkürlichen Portale, die ohne entsprechende Verankerung Löcher in die Realität reißen...\n\nWie dem auch sei, es ist mir eine Freude, der Horde ein stabilisiertes Teleportationsnetzwerk zu bieten. Bitte, nur weiter.', '', 28153),
(143540, 'deDE', 'Die Leute aus meiner Stadt sind hart im Nehmen, aber das ist eine echte Prüfung.', '', 28153),
(143539, 'deDE', '', 'Ertränkt diese Insekten, meine Kinder. Verdient Euch meinen Stolz.', 28153),
(143537, 'deDE', 'Brgl! Brglrgl!', '', 28153),
(143536, 'deDE', 'Mrgl, mrglrglrgl! Mrrrg! Mrrrg!!', '', 28153),
(143531, 'deDE', 'Stemmen', 'Stemmen', 28153),
(143530, 'deDE', 'Jetzt kommt\'s auf Euch an! Springt rein!', '', 28153),
(143529, 'deDE', 'Irgendwas stimmt nich\' auf der Rezans Klaue. Wir haben einen Spähflieger in der Nähe des Lagers.', '', 28153),
(143523, 'deDE', 'Gebt mir Euer Gold! Ich muss in in fünf Minuten über meine Gewinne Bericht erstatten!', '', 28153),
(143520, 'deDE', 'Ich bin bereit, die synthetische Essenz von G\'huun von Euch zu empfangen.', 'Ich bin bereit, die synthetische Essenz von G\'huun von Euch zu empfangen.', 28153),
(143519, 'deDE', 'König Da\'ka! Er is\' hier! Hilfe!', '', 28153),
(143518, 'deDE', 'Ihr habt... verloren? Gegen diese Schwächlinge? Erbärmlich! Meldet Euch in Unterstadt für Nachhilfeeinheiten. Anscheinend muss ich ganz von vorne bei Euch anfangen...', '', 28153),
(143517, 'deDE', 'Das war nicht gerade das, was ich einen \"glänzenden Sieg\" nenne, aber immerhin habt Ihr diese Allianzfeiglinge in die Schranken verwiesen. Für die Horde!', '', 28153),
(143516, 'deDE', 'Rieche ich da etwa... Worgen? Die Allianz stinkt so sehr nach Arroganz, dass man andere Gerüche kaum wahrnimmt.', '', 28153),
(143515, 'deDE', 'Löscht sie aus! Ihr wollt Euren Kriegshäuptling nicht enttäuschen!', '', 28153),
(143514, 'deDE', 'Das nennt sich bei der Allianz \"Soldaten\"? Erbärmlich! Der da kann kaum mit einem Schwert umgehen!', '', 28153),
(143513, 'deDE', 'Feuer! Lasst keinen von diesen Bastarden am Leben!', '', 28153),
(143512, 'deDE', 'Schau einer an! Sieht aus, als gäbe es noch mehr Azerit hier. Folgt Eurer Karte und sichert diese Vorkommen.', '', 28153),
(143511, 'deDE', 'Überall auf der Insel ist es zu weiteren Azeriteruptionen gekommen! Werft einen Blick auf die Karte, um sie zu finden.', '', 28153),
(143510, 'deDE', 'Wir haben es gleich! Lasst jetzt nicht nach. Mehr Azerit!', '', 28153),
(143509, 'deDE', 'Ha! Direkt der Allianz abgenommen! Gut gemacht!', '', 28153),
(143508, 'deDE', 'Nicht übel für den ersten Versuch, aber wir brauchen mehr von diesem Azerit!', '', 28153),
(143507, 'deDE', 'Schnappt Euch, was Ihr braucht. Aber vergesst nicht den Auftrag der Bansheekönigin!', '', 28153),
(143506, 'deDE', 'Nachschub ist auf dem Weg. Seht besser zu, dass die Allianz sie nicht in die Finger kriegt!', '', 28153),
(143505, 'deDE', 'Da unten... Azerit! Sammelt es ein, für unseren Kriegshäuptling. Und wenn Euch die Allianz in die Quere kommt, übersät den Strand mit ihren Leichen. Bewegung!', '', 28153),
(143504, 'deDE', 'Lasst mich Euch anschauen. Ugh... jämmerlich! Für Dunkle Waldläufer hat es wohl nicht gereicht? Na gut, Ihr müsst genügen.', '', 28153),
(143503, 'deDE', 'Allianzschiffe nähern sich! Diese Hunde sind uns auf den Fersen. Alle auf Gefechtsstation!', '', 28153),
(143502, 'deDE', 'Euer Auftrag hier ist einfach. Sammelt so viel Azerit ein, wie Ihr könnt, und lasst nichts für die Allianz zurück. Ich hoffe, das ist nicht allzu schwer zu verstehen.', '', 28153),
(143501, 'deDE', 'Champions der Horde! Wir sind auf einer schäbigen kleinen Insel vor der Küste von Feralas auf Azeritvorkommen gestoßen. Sichert sie im Namen der Dunklen Fürstin!', '', 28153),
(143500, 'deDE', 'Drängt sie zurück! Diese Insel gehört uns!', '', 28153),
(143499, 'deDE', 'In den Kampf für den König und die Allianz!', '', 28153),
(143498, 'deDE', 'Die Horde hält sich für schlau. Erteilt ihnen eine Lektion!', '', 28153),
(143497, 'deDE', 'Feuer! Erledigt diese Heiler!', '', 28153),
(143496, 'deDE', 'Ihr seht alle ganz robust aus. Hmm... noch ein oder zwei Schurken könnten nicht schaden... aber Ihr müsst reichen!', '', 28153),
(143495, 'deDE', 'Verdammt! Dieses Mal hat die Horde die Oberhand behalten. Doch ich schwöre bei der Löwenruh: Wir werden den Sieg erringen!', '', 28153),
(143494, 'deDE', 'Gute Arbeit, Champions! König Wrynn wird zufrieden sein, wenn er von unserem Sieg hört. Für die Allianz!', '', 28153),
(143493, 'deDE', 'Vorräte unterwegs! Sammelt sie auf, Champions!', '', 28153),
(143492, 'deDE', 'Noch mehr Azeriteruptionen! Schaut Euch die Markierungen auf der Karte an und sichert diese Stellen!', '', 28153),
(143491, 'deDE', 'Ihr helft uns wirklich weiter. Uns fehlt nur noch ein bisschen Azerit, dann haben wir es geschafft!', '', 28153),
(143490, 'deDE', 'Ihr habt dieses Azerit der Horde abspenstig gemacht. Hervorragende Arbeit!', '', 28153),
(143489, 'deDE', 'Gute Arbeit, Helden. Wir brauchen aber noch mehr Azerit!', '', 28153),
(143488, 'deDE', 'Helden! Wir werfen Euch Vorräte ab. Passt auf, dass sie nicht der Horde in die Hände fallen.', '', 28153),
(143487, 'deDE', 'Überall auf der Insel hat es neue Azeriteruptionen gegeben! Die Stellen sind auf der Karte markiert.', '', 28153),
(143486, 'deDE', 'Unter uns befinden sich reiche Azeritvorkommen. Geht da runter und sammelt, was Ihr könnt. Wenn Euch Hordegesindel in die Quere kommt... macht kurzen Prozess!', '', 28153),
(143485, 'deDE', 'Hordeschiffe gesichtet! Dieser Abschaum muss uns hierher gefolgt sein! Auf die Kampfstationen!', '', 28153),
(143484, 'deDE', 'Wir haben mit dem Schiff die Mitte der Insel erreicht. Sammelt so viel Azerit, wie Ihr könnt. Es ist der Schlüssel zum Sieg!', '', 28153),
(143483, 'deDE', 'Champions, auf einer Insel abseits der Küste von Feralas wurden Azeritvorkommen entdeckt. Wir müssen sie sichern, bevor die Horde uns zuvorkommt.', '', 28153),
(143482, 'deDE', '', 'Es wäre mir eine Ehre, Lady Liadrin. Oculeth hat die Koordianten zu Eurer Hauptstadt. Ich suche Silgryn und Valtrois und treffe Euch in Silbermond.', 28153),
(143481, 'deDE', '', 'Ich bin sicher, der Lordregent wird hocherfreut sein, von Eurem Wunsch zu hören. Seid Ihr bereit?', 28153),
(143480, 'deDE', '', 'Daher bin ich Euch dankbar für Eure Einladung nach Silbermond. Ich möchte wissen, ob die Nachtgeborenen Aufnahme in die Horde finden.', 28153),
(143479, 'deDE', '', 'Die Allianz schottet sich ab... zu stark ist ihr Misstrauen. Mein Volk soll niemals wieder so verblendet sein.', 28153),
(143478, 'deDE', '', 'Tyrande und ihr hochmütiges Volk blicken auch auf die Sin\'dorei herab. Dabei waren sie es, die viele Jahre in Höhlen schliefen oder sich in Bäumen verbargen, während mein Volk für das Wohl der Welt kämpfte.', 28153),
(143477, 'deDE', '', 'Wie es scheint hat \"Elunes Weisheit\" sie dazu geleitet, den Bund, der uns einte, zu brechen. So sei es denn.', 28153),
(143476, 'deDE', '', 'Die Kaldorei werden kämpfen, um die Legion zu bezwingen und den Nachtbrunnen zu zerstören. Dann... sehen wir, wohin Elunes Weisheit uns leitet.', 28153),
(143475, 'deDE', '', 'Wir werden keine Sklaven des Nachtbrunnens sein. Wir wollen die Legion aus Suramar vertreiben und Elisandes Gewalt ein Ende setzen.', 28153),
(143474, 'deDE', '', 'Arkanistin Thalyssra. Ich weiß, auf welcher Seite Euer Orden im Krieg der Ahnen stand. Was, wenn Ihr uns verratet und die nächste Elisande... oder Azshara werdet?', 28153),
(143473, 'deDE', '', 'Ich dachte, unsere Verwandten aus Kalimdor wären die naheliegendsten Verbündeten. Doch ihre Arroganz und ihr Misstrauen bewiesen schnell das Gegenteil.', 28153),
(143472, 'deDE', '', 'Ich muss zugeben, dass ich skeptisch war, als ich das erste Mal von der Horde hörte. Ich fürchtete, dass uns nur wenig verbindet.', 28153),
(143471, 'deDE', '', 'Die Horde ist stolz darauf, an Eurer Seite gegen die Brennende Legion gekämpft zu haben.', 28153),
(143470, 'deDE', '', 'Dafür stehen wir tief in Eurer Schuld. Ihr habt unserer Sache einen gewaltigen Dienst erwiesen.', 28153),
(143469, 'deDE', '', 'Es ist schön, Eure Stadt befreit zu sehen.', 28153),
(143468, 'deDE', '', 'Lady Liadrin, $p, ich grüße Euch. Willkommen zurück in Suramar. Ich bin froh, Euch unter angenehmeren Umständen zu empfangen.', 28153),
(143467, 'deDE', '', 'Enttäuschend, aber nich\' überraschend... Die Loa haben Euch nich\' gesegnet, Kind. Ihr werdet uns nich\' auf die Terrasse der Auserwählten begleit\'n.', 28153),
(143466, 'deDE', 'Ihr seid wirklich weit gereist, um mich zu besuchen, Kind.$b$bIch besitze mehrere Bücher über die Geschichte der Krabben, falls Euch die reizt?', '', 28153),
(143465, 'deDE', '', 'Widerstandsfähig und stolz werdet Ihr Eure Gegner und jeden Sturm überdauern. Eure Stärke wird vonnöten sein, um unsre Stadt zu verteidig\'n.', 28153),
(143464, 'deDE', '', 'Das is\'... sehr ungewöhnlich. Eure Stärke wird in den kommenden Zeiten benötigt werd\'n.', 28153),
(143463, 'deDE', '', 'Selbstsüchtig und ehrlos... Ihr würdet gut dran tun, einen andren Weg zu such\'n, Kind.', 28153),
(143462, 'deDE', '', 'Int\'ressant... Verstohl\'n und klug schlagt Ihr aus den Schatten zu. Die Überraschung wird Eure stärkste Waffe sein.', 28153),
(143461, 'deDE', '', 'Verstehe. Ihr seid schnell und wachsam, Eure Schläge sin\' umsichtig. Eure Geduld wird belohnt werd\'n.', 28153),
(143460, 'deDE', '', 'Seht tief in Euch rein, Kind. Zeigt mir, wie Ihr Eure Beute jag\'n werdet. Mit Weisheit, Stärke oder was völlig andrem?', 28153),
(143459, 'deDE', '', 'Das Rudel ruft laut nach Euch. Fügt Euch den Blutsbanden un\' jagt mit Euern Brüdern und Schwestern.', 28153),
(143458, 'deDE', 'Riecht Ihr das auch? Es riecht nach Kohl.$b$b<Kronah beugt sich zu Euch und schnüffelt.>$b$bIhr seid das nicht. Aber irgendetwas anderes hier. $b$bWie steht es eigentlich um Eure Schreibkünste? Braucht Ihr Nachhilfe? Ich bin nämlich eine Inschriftenmeisterin, müsst Ihr wissen.', '', 28153),
(143457, 'deDE', 'Wir werden angegriffen!', 'Wir werden angegriffen!', 28153),
(143456, 'deDE', 'Greift zu Eurem Stahl, Brüder und Schwestern!', 'Greift zu Eurem Stahl, Brüder und Schwestern!', 28153),
(143455, 'deDE', 'Der Feind ist hier!', 'Der Feind ist hier!', 28153),
(143454, 'deDE', 'Eindringlinge! Zu den Waffen!', 'Eindringlinge! Zu den Waffen!', 28153),
(143452, 'deDE', 'Kein Problem.', '', 28153),
(143451, 'deDE', 'Bewegung!', '', 28153),
(143450, 'deDE', 'Wir haben Bestellungen zu erfüllen!', '', 28153),
(143449, 'deDE', '', 'Bitte lenkt das Kind nich\' ab.\n\nIch prüf diese Kinder nach Zeichen auf \'ne Verbindung mit den Loa. Jene, die von den Loa gesegnet sin\', werd\'n \'ne vollständige Priesterausbildung sowie alle Ehren und Privilegien erhalt\'n, die damit einhergeh\'n.\n\nDen nich\' Gesegneten wird die Möglichkeit gegeb\'n, zu beweis\'n, dass sie eines Tages zu starken Kriegern heranwachs\'n werd\'n.\n\nJene, die beide Prüfungen nich\' besteh\'n, sin\' für uns nutzlos. Sie end\'n vermutlich als Hafendiebe oder Bettler im Zocalo.', 28153),
(143448, 'deDE', 'Das kann ich.', '', 28153),
(143447, 'deDE', 'Alles klar.', '', 28153),
(143446, 'deDE', 'Arbeit, Arbeit.', '', 28153),
(143445, 'deDE', 'Wir brauchen mehr Holz!', '', 28153),
(143444, 'deDE', 'Ausruhen könnt Ihr Euch, wenn Ihr tot seid. Bis dahin haben wir zu tun!', '', 28153),
(143443, 'deDE', 'Ich werde so schnell ich kann ins Dorf zurückkehren, bevor alles weg ist. Vielleicht haben sie mich noch nicht vergessen.', '', 28153),
(143442, 'deDE', 'Ich glaube nicht, dass ich wieder so leben kann wie früher... als stumpfsinniger Affe. Nicht nach dem, was ich gesehen und gefühlt habe. Wenn auch nur kurz.', '', 28153),
(143441, 'deDE', 'Da\'ka hatte recht. Ich spüre bereits, wie mein Geist in seinen primitiven Zustand zurückgleitet.', '', 28153),
(143440, 'deDE', 'Seid gegrüßt, $gReisender:Reisende;.$b$bInteresse an ein paar Schriftrollen? Oder vielleicht an exotischen Tinten aus den seltensten Kräutern?', '', 28153),
(143439, 'deDE', 'Aber Goblins haben ja auch so winzig kleine Gehirne. Da müsst Ihr vielleicht noch mal hundert einschlagen, bis sie es lernen.', '', 28153),
(143438, 'deDE', 'Wacker gekämpft. Diesen Goblins habt Ihr gezeigt, was passiert, wenn man sich mit den Dunkeleisenzwergen anlegt!', '', 28153),
(143437, 'deDE', 'Sabotiert ihre Maschinen! Zerstört ihre Werkzeuge! Zerquetscht jeden kleinen grünen Goblin, der Euch übern Weg läuft!', '', 28153),
(143436, 'deDE', 'Diese Goblins verderben Azerit in rauen Mengen! Wir dürfen nicht tatenlos zusehen!', '', 28153),
(143435, 'deDE', 'Eisenfeind ist endlich zum Greifen nah. Hämmert diesen Goblins ein, was passiert, wenn man von den Dunkeleisenzwergen stiehlt!', '', 28153),
(143434, 'deDE', 'Wer hier? Wer Dämpfe ausgemacht? König Da\'ka Euch töten!', '', 28153),
(143433, 'deDE', 'Für die Horde!', 'Für die Horde!', 28153),
(143432, 'deDE', 'Klein Tika blickt die Schweine hungrig an.', '', 28153),
(143431, 'deDE', 'Klein Tika wackelt verspielt.', '', 28153),
(143430, 'deDE', '', 'Bist du \'n braves kleines blutrünstiges Raptorbaby? Joah, das bist du, das bist du!', 28153),
(143429, 'deDE', '', 'Oh, es is\' so schön, dich kleinen Racker zu sehen! $n... Ich danke Euch.', 28153),
(143428, 'deDE', '', 'Is\' das Tika?!', 28153),
(143427, 'deDE', 'Klein Tika trällert fröhlich.', '', 28153),
(143426, 'deDE', '', 'Andere... werden kommen...', 28153),
(143425, 'deDE', '', 'Die Sonne senkt sich über dem Imperium der Zandalari. Die Treulosen werden sich auf die Reste stürzen.', 28153),
(143424, 'deDE', 'Dafür werde ich Euch vierteilen lassen!', 'Dafür werde ich Euch vierteilen lassen!', 28153),
(143423, 'deDE', 'Klein Tika hebt ihr Schnäuzchen in den Wind und gibt einen scharfen Schrei von sich.', '', 28153),
(143422, 'deDE', 'Kniet nieder vor Eurer Königin, Bauerntrampel!', 'Kniet nieder vor Eurer Königin, Bauerntrampel!', 28153),
(143421, 'deDE', 'Euch... wird sie auch holen...', 'Euch... wird sie auch holen...', 28153),
(143420, 'deDE', 'Haus Sturmsang wird dieses Land regieren!', 'Haus Sturmsang wird dieses Land regieren!', 28153),
(143419, 'deDE', '', 'Danke Euch beiden für die Hilfe! $n, macht Euch bereit, Euch in die Höhle von Düsterschweif zu begeben und Ben\'jin zu helfen, wenn das hier funktioniert.', 28153),
(143418, 'deDE', '', 'Ich hätte ein Gerät bauen können, mit dem man Hirnscans von Brutosauriern machen und Analysen durchführen kann. Ich mein ja nur.', 28153),
(143417, 'deDE', '', 'Wissenschaft ist die einzige Lösung, Jangalar. Ich will Eure Kräfte nicht geringschätzen, aber Hokuspokus ist kein Ersatz für aggressive, logische Alchemie.', 28153),
(143416, 'deDE', 'Wir werden den schwächlichen Menschen die Stärke der Horde zeigen!', '', 28153),
(143415, 'deDE', 'Diese Menschen sollen uns schon fürchten, bevor sie unsere Klingen zu spüren bekommen!', '', 28153),
(143414, 'deDE', 'Für die Horde!', '', 28153),
(143413, 'deDE', 'Ich werd nach Zuldazar zurückkehr\'n... Macht Euch keine Sorg\'n, ich werd das schon allein schaff\'n. Kommt vorbei, wenn Ihr\'s nächste Mal da seid!', '', 28153),
(143412, 'deDE', 'Wartet, Jin\'Tiki. Nehmt den Raptor. Euch... scheint er schließlich mehr zu mög\'n als mich.', '', 28153),
(143411, 'deDE', 'Passt gut auf! Ich will nicht, dass diese Menschen hier in unserem Werk herumschnüffeln!', '', 28153),
(143410, 'deDE', 'Los, schneller!', '', 28153),
(143409, 'deDE', 'Hier sin\' wir wohl fertig. Dann muss ich jetz\' zurück nach Vol\'dun und für meine Verbrechen bezahl\'n.', '', 28153),
(143408, 'deDE', 'Wenn jemand bei der Arbeit einschläft, verfüttere ich ihn persönlich an die Wölfe!', '', 28153),
(143407, 'deDE', 'Schafft mehr Ressourcen ran!', '', 28153),
(143404, 'deDE', 'Eure Verdammnis... steigt empor...', 'Eure Verdammnis... steigt empor...', 28153),
(143403, 'deDE', 'Wie kann... das sein...', 'Wie kann... das sein...', 28153),
(143402, 'deDE', '', 'Schnappt Euch die Tiere un\' reist in die Stadt. Ich bring Euch \'nen Korb Schlangenköpfe, wenn wir fertig sin\'!', 28153),
(143401, 'deDE', 'Das Auge... des Sturms... findet Euch...', 'Das Auge... des Sturms... findet Euch...', 28153),
(143400, 'deDE', 'Ihr... werdet... fallen...', 'Ihr... werdet... fallen...', 28153),
(143399, 'deDE', 'Da. Dort komm\'n die Dämpfe von tief unten nach oben.', '', 28153),
(143398, 'deDE', 'Meine Seele... verfließt... im Ozean...', 'Meine Seele... verfließt... im Ozean...', 28153),
(143397, 'deDE', 'Ich breche auf... in die endlose... Tiefe...', 'Ich breche auf... in die endlose... Tiefe...', 28153),
(143396, 'deDE', 'Die hab\'n unsren Häuptling umgebracht! Das ganze Dorf is\' weg!', '', 28153),
(143395, 'deDE', 'Der große Schlot is\' da drinnen. Kommt schnell!', '', 28153),
(143394, 'deDE', 'Ich kehre zurück... in die Tiefe...', 'Ich kehre zurück... in die Tiefe...', 28153),
(143391, 'deDE', 'Selbst die Flut... weicht zurück...', 'Selbst die Flut... weicht zurück...', 28153),
(143390, 'deDE', 'Ihre Macht strömt durch meine Adern!', 'Ihre Macht strömt durch meine Adern!', 28153),
(143389, 'deDE', 'Fügt Euch Eurem Ende!', 'Fügt Euch Eurem Ende!', 28153),
(143388, 'deDE', 'Die Flut des Schicksals wird über Euch brechen!', 'Die Flut des Schicksals wird über Euch brechen!', 28153),
(143387, 'deDE', 'Die Flut höhlt Euch aus wie einen Stein!', 'Die Flut höhlt Euch aus wie einen Stein!', 28153),
(143386, 'deDE', 'Ertrinkt in den lichtlosen Tiefen!', 'Ertrinkt in den lichtlosen Tiefen!', 28153),
(143385, 'deDE', 'Niemand stoppt die endlose Flut!', 'Niemand stoppt die endlose Flut!', 28153),
(143384, 'deDE', 'Hört den Ruf der Tiefe!', 'Hört den Ruf der Tiefe!', 28153),
(143383, 'deDE', 'Die See wird Euch fortspülen!', 'Die See wird Euch fortspülen!', 28153),
(143382, 'deDE', 'So falle... König Da\'ka.', '', 28153),
(143381, 'deDE', '', 'Aber... mir wurde Macht versprochen...', 28153),
(143380, 'deDE', 'Schuft! Ihr seid wie ein Licht, das beste Teil heruntergebrannt.', '', 28153),
(143379, 'deDE', '', 'Ihr seid stark, aber Ihr werdet Euch dem Zirkel beugen wie alle vor Euch!', 28153),
(143378, 'deDE', '', 'Aber Eure Entdeckung wird mit Euch sterben. Greift an, meine Liebchen!', 28153),
(143377, 'deDE', '', 'Ihr habt uns also gefunden. Ihr müsst Euch ja so schlau fühlen.', 28153),
(143376, 'deDE', 'Ha! Wozu ist Intelligenz gut, wenn nicht zum Ausüben von Macht? Ich werde der König von Zandalar sein. Akzeptiert das oder findet Euren Tod!', '', 28153),
(143375, 'deDE', 'Ihr müsst aufgehalten werden, Da\'ka. Unsere Intelligenz war nie für uns bestimmt... und erst recht nicht, um Krieg zu führen!', '', 28153),
(143374, 'deDE', 'Tsunga... Ihr habt eine unwürdige Kreatur zu den heiligen Dämpfen gebracht. Warum bist du gekommen?', '', 28153),
(143373, 'deDE', 'Was ist hier los?', 'Was ist hier los?', 28153),
(143372, 'deDE', 'In der Tiefe... hab ich Wahrheit gesehen...', 'In der Tiefe... hab ich Wahrheit gesehen...', 28153),
(143371, 'deDE', 'Ich blute... Salzwasser...', 'Ich blute... Salzwasser...', 28153),
(143370, 'deDE', 'Geht! Die Quelle der Nebel is\' in dieser Höhle. Keine Ahnung, wo König Da\'ka is\'. Beeilt Euch!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143369, 'deDE', 'Die Blutmagie an diesem Ort is\' sehr stark. Man muss kein Hexendoktor sein, um das zu spür\'n. Sie is\' überall.', '', 28153),
(143368, 'deDE', '', 'Oh... Was macht Ihr denn hier, $gFestländer:Festländerin;?\n\nKann ich Euch irgendwie behilflich sein?', 28153),
(143367, 'deDE', 'Wen soll ich töt\'n?', '', 28153),
(143366, 'deDE', 'Taz\'dingo!', '', 28153),
(143365, 'deDE', 'Für die Horde!', '', 28153),
(143364, 'deDE', 'Zeit zu töten!', '', 28153),
(143363, 'deDE', 'Töten is\' einfach.', '', 28153),
(143362, 'deDE', 'Kein Erbarmen!', '', 28153),
(143361, 'deDE', 'Köpfe werden rollen!', '', 28153),
(143360, 'deDE', 'Ruhm der Horde!', '', 28153),
(143359, 'deDE', '', 'Ruhm der Horde!', 28153),
(143358, 'deDE', '', 'Köpfe werden rollen!', 28153),
(143357, 'deDE', '', 'Kein Erbarmen!', 28153),
(143356, 'deDE', 'Wir machen... niemals halt...', 'Wir machen... niemals halt...', 28153),
(143355, 'deDE', 'Mein Tod... hält gar nichts auf...', 'Mein Tod... hält gar nichts auf...', 28153),
(143354, 'deDE', 'Wir haben... schon gewonnen...', 'Wir haben... schon gewonnen...', 28153),
(143353, 'deDE', '', 'Töten is\' einfach.', 28153),
(143352, 'deDE', 'Ich habe nur... Befehle befolgt...', 'Ich hab nur... Befehle befolgt...', 28153),
(143351, 'deDE', 'Gezeitenweise... bewahrt mich...', 'Gezeitenweise... bewahrt mich...', 28153),
(143350, 'deDE', 'Mein Leben... für die See...', 'Mein Leben... für die See...', 28153),
(143349, 'deDE', 'Kul Tiras gehört der See!', 'Kul Tiras gehört der See!', 28153),
(143348, 'deDE', 'Ihr wagt es, Haus Sturmsang zu trotzen?', 'Ihr wagt es, Haus Sturmsang zu trotzen?', 28153),
(143347, 'deDE', 'Wir sind gnadenlos wie die kalte See!', 'Wir sind gnadenlos wie die kalte See!', 28153),
(143346, 'deDE', 'Wer uns im Weg steht, geht unter!', 'Wer uns im Weg steht, geht unter!', 28153),
(143345, 'deDE', 'Unsere Flotte zerquetscht Euch!', 'Unsere Flotte zerquetscht Euch!', 28153),
(143344, 'deDE', '', 'Zeit zu töten!', 28153),
(143343, 'deDE', '', 'Kommt nur her, Schwesta!', 28153),
(143342, 'deDE', 'Ohne uns ist Kul Tiras Fischfutter!', 'Ohne uns ist Kul Tiras Fischfutter!', 28153),
(143341, 'deDE', '', 'Kommt nur her, Bruda!', 28153),
(143340, 'deDE', 'Das Tal gehört uns, Bilgeratte!', 'Das Tal gehört uns, Bilgeratte!', 28153),
(143339, 'deDE', 'In Sturmsangs Namen!', 'In Sturmsangs Namen!', 28153),
(143338, 'deDE', '', 'So viele tote Saurier... Ich hab sie alle von Ei an aufgezog\'n. Es is\', als wär\'n meine eigenen Kinder gestorb\'n.$b$bDiese Schlangenmänner müss\'n dafür zahl\'n.', 28153),
(143337, 'deDE', 'Große Verderbnis umgibt das nahe Gebäude. Sofortiges Handeln erforderlich.', '', 28153),
(143336, 'deDE', 'Teilweiser Wiederherstellungsprozess erfolgreich. Muss weiter, um Eindämmung der Verderbnis zu reparieren.', '', 28153),
(143335, 'deDE', 'Verbessere Nebensysteme. Bitte warten...', '', 28153),
(143334, 'deDE', 'Könnt Ihr Ausrüstungsgegenstände reparieren?', 'Könnt Ihr Ausrüstungsgegenstände reparieren?', 28153),
(143333, 'deDE', 'Das Dorf is\' vielleicht weg, aber die Schmiede verlass ich nur mit den Füß\'n zuerst.', '', 28153),
(143332, 'deDE', '', 'Für die Horde!', 28153),
(143331, 'deDE', '', 'Taz\'dingo!', 28153),
(143330, 'deDE', '', 'Wen soll ich töt\'n?', 28153),
(143329, 'deDE', 'Ich bin froh, dass die Zivilisten in Sicherheit sind, aber es gibt noch viel zu tun.', '', 28153),
(143328, 'deDE', '', 'Sturmwind kenne ich bisher nur aus Erzählungen. Ich freue mich darauf, die Wunder zu erkunden, die seine verwinkelten Gassen bereithalten. Mögen die Schatten Euch leiten, $n.', 28153),
(143327, 'deDE', 'Das Licht sei mit Euch, $n. Ich werde die Legion in Azeroth aufspüren und unseren ewigen Kampf fortsetzen.', '', 28153),
(143326, 'deDE', 'Mach ich natürlich nicht... aber ich hab drüber nachgedacht – fast \'ne ganze Sekunde.', '', 28153),
(143325, 'deDE', 'Ich muss ja sagen, so hart wie Ihr gearbeitet habt, hab ich echt überlegt, Euch auch was abzugeben.', '', 28153),
(143324, 'deDE', 'Gut gemacht! Und jetzt zu den wirklichen Heldentaten: alle Dokumente unterschreiben, damit alles rechtmäßig mir gehört. So richtig schön offiziell.', '', 28153),
(143323, 'deDE', 'Aber jetzt mal ehrlich, vernichtet sie lieber, bevor sie mir noch die Tour vermasseln.', '', 28153),
(143322, 'deDE', 'Ziel erreicht. Beziehe vordere Position. Abschluss an neuer Position.', '', 28153),
(143321, 'deDE', 'Ha! Guckt Euch diese Pfeifen an! Diese Elementare wissen wirklich, wie man austeilt.', '', 28153),
(143320, 'deDE', 'Klein Tika knurrt bedrohlich leise.', '', 28153),
(143319, 'deDE', 'Klein Tika fiept verzweifelt!', '', 28153),
(143318, 'deDE', 'Die Welt blutet und Ihr zehrt an ihren Wunden? Sterbt!', '', 28153),
(143317, 'deDE', 'Ich will Explosionen sehen, Chaos, sinnlose Gewalt. Ihr wisst schon... das, was Ihr am besten könnt.', '', 28153),
(143316, 'deDE', 'Zeigt diesen Amateuren von der Venture Company, dass es nichts gibt, was ich nicht haben kann.', '', 28153),
(143315, 'deDE', 'Da gibt\'s nur ein Problem... Das ganze gehört nicht mir. Und deshalb brauch ich Euch.', '', 28153),
(143314, 'deDE', 'Sieh an, DA kommt also das ganze Schwarzmarktazerit her. Kein schlechtes Geschäft.', '', 28153),
(143313, 'deDE', '', 'Ich weiß nicht, was \"Worgenbann\" ist, aber... Hm, was steht hier?', 28153),
(143312, 'deDE', 'Ihr wart zu gut für diese Welt, Bruder. Ich sorge dafür, dass Ihr anständig bestattet werdet.', '', 28153),
(143311, 'deDE', 'Ich lieb den Geruch von Mojo am Morg\'n!', '', 28153),
(143310, 'deDE', '', 'Rokhan hat gesagt, Ihr habt Erfahrung mit solch\'n Sach\'n. Tut, was Ihr könnt. Ich bleib hier un\' wart auf den Goblintrupp.', 28153),
(143308, 'deDE', '', '$n, wir benötig\'n jed\'n Verbündeten, den wir krieg\'n könn\'. Helft dem Hüter – so schnell wie möglich.', 28153),
(143307, 'deDE', 'Unterstützung erforderlich. Hezrel reparieren. Nahegelegene Struktur erreichen. Verderbnis innerhalb Nazmirs eindämmen.', '', 28153),
(143306, 'deDE', 'Weitreichende Verderbnis in Nazmir verzeichnet. Muss Eindämmung veranlassen.', '', 28153),
(143305, 'deDE', 'Ich hab viele Schlachten geschlag\'n... aber sowas wie dieses Monster... hab ich noch nie geseh\'n...', '', 28153),
(143304, 'deDE', 'Lebend bekommt Ihr mich nich\'!', '', 28153),
(143303, 'deDE', 'Na gut, in Vol\'dun ist\'s bestimmt sich\'rer als hier!', '', 28153),
(143302, 'deDE', 'Nein! Nicht die Raptor\'n... Die werd\'n mich fress\'n!', '', 28153),
(143301, 'deDE', '...Danke, Zaluto. Wer weiß, in \'nem andren Leb\'n hätt\'n wir vielleicht Brüda sein könn\'n.', '', 28153),
(143300, 'deDE', 'Verwendet den Blutfetisch gegen Zulajin, um seine Macht zu absorbier\'n und ihn zurück in sein Grab zu schick\'n!', '', 28153),
(143299, 'deDE', 'Keine Sorge, Mann! Ich kümmer mich um den Anführer hier, während Ihr in den Ruinen aufräumt!', '', 28153),
(143298, 'deDE', 'So! Jetzt legt die Verkleidung an und geht den Schlüssel hol\'n!', '', 28153),
(143297, 'deDE', 'Ihr braucht \'ne Verkleidung, um an Zulajin vorbeizukomm\'n. Kommt schnell wieder, wenn Ihr die Sachen habt!', '', 28153),
(143296, 'deDE', 'Ich bin \'n Verbrecher, aber ich bin nich\' böse. Ich werd Euch hier nich\' zum Sterben liegen lass\'n!', '', 28153),
(143295, 'deDE', 'Falls ich sterb\'n muss... sterb ich mit Ehre... Dank Euch...', '', 28153),
(143294, 'deDE', 'Prost! Ein Hoch auf den mutigen <hicks> Champion, der uns alle retten wird!', '', 28153),
(143293, 'deDE', '', 'Reist nach Orgrimmar. Trefft unsere neuen Verbündeten und schmiedet mit ihnen eine neue gemeinsame Zukunft.', 28153),
(143292, 'deDE', '', 'Erzählt allen, die Ihr auf Euren Reisen durch Azeroth trefft, die stolze Geschichte der Nachtgeborenen... und lasst sie wissen, dass wir nicht länger in Isolation leben.', 28153),
(143291, 'deDE', 'Was wissen wir über die Nachtgeborenen?', 'Was wissen wir über die Nachtgeborenen?', 28153),
(143290, 'deDE', '', '$n, ich bin froh, dass Ihr hier seid. Wir müssen den Kriegshäuptling davon überzeugen, ein Bündnis mit den Nachtgeborenen einzugehen.', 28153),
(143289, 'deDE', 'Was wissen wir über die Hochbergtauren?', 'Was wissen wir über die Hochbergtauren?', 28153),
(143288, 'deDE', '', 'Nun liegt es an uns, zu beweisen, dass wir den Ruhm und die Stärke der Horde mehren.', 28153),
(143287, 'deDE', 'Wir haben viel gemeinsam mit den Hochbergtauren. Ich bin überzeugt, dass sie in naher Zukunft ideale Verbündete sein könnten.', '', 28153),
(143286, 'deDE', '', 'Keine Sorge wegen Tsunga. Wir kümmern uns um ihn. Auch wenn er sich nich\' mal mehr an seinen eignen Namen erinnern kann.', 28153),
(143285, 'deDE', '', 'Junge, Junge, der war ganz schön groß, was? Gute Arbeit!', 28153),
(143284, 'deDE', '', 'Mögen die Sterne Euch leiten, $p. Ich höre ungewöhnliche Berichte über das Vorgebirge des Hügellands. Ich werde dorthin aufbrechen.', 28153),
(143283, 'deDE', '', 'Seid Ihr sicher, Tsunga? Ihr wisst, was Ihr verliert, wenn der Champion die Dämpfe versieg\'n lässt!', 28153),
(143282, 'deDE', 'Ich werde das Ritual vorbereiten, um diese Seelen zu befreien. Trefft mich am Ufer nördlich von hier.', '', 28153),
(143281, 'deDE', 'Ich bin mir der Konsequenzen vollauf bewusst. Trotzdem. Manches mag schwer aufzugeben sein, dennoch ist es richtig, es herzugeben.', '', 28153),
(143280, 'deDE', 'Ich werde einen anderen Pfad in die Schlucht nehmen und Euch dort treffen.', '', 28153),
(143279, 'deDE', 'Bleibt in Formation! Verstärkung ist unterwegs. Wir dürfen nicht zulassen, dass die Naga den Damm zerstören!', '', 28153),
(143278, 'deDE', 'Befreit Euer Herz gänzlich von Hass.', '', 28153),
(143277, 'deDE', '', 'Doch die Sin\'dorei, die Blutelfen, brachten uns Respekt und Verständnis entgegen. Ihre Freundschaft bewies, dass es in Azeroth noch andere Völker gibt, die unsere Werte teilen.', 28153),
(143276, 'deDE', '', 'Als unsere Stadt vor dem Untergang stand, kämpften die Helden von Azeroth an unserer Seite, um die Legion zu besiegen. Nicht alle von ihnen handelten aus Überzeugung.', 28153),
(143275, 'deDE', '', 'Ich überreiche Euch die traditionelle Tracht von Suramar. Tragt sie als Erinnerung an unsere Vergangenheit... und die neue Zukunft, die wir an der Seite unserer Verbündeten schmieden werden.', 28153),
(143274, 'deDE', 'Das müsst Ihr mir nicht zweimal sagen!', '', 28153),
(143273, 'deDE', '', 'Ihr habt der Horde, und allen Völkern von Azeroth, gezeigt, dass die Nachtgeborenen den Willen und den Mut besitzen, unsere Welt zu verteidigen.', 28153),
(143272, 'deDE', 'Begebt Euch zum Ufer auf der anderen Seite der Werft. Findet eine junge Prachtmeerkadettin – Taelia. Los!', '', 28153),
(143271, 'deDE', '', 'Begebt Euch nach Suramar. Ihr habt unserem Volk geholfen, seinen Platz in dieser Welt zu finden. Dafür möchten wir Euch danken.', 28153),
(143270, 'deDE', '', 'Ihr gehört zu den ersten Shal\'dorei, die sich heraus in die weite Welt gewagt und die Wildnis von Azeroth erkundet haben. Doch nun ist es Zeit, heimzukehren.', 28153),
(143269, 'deDE', 'Diese Arbeiter... sie stehen unter dem Einfluss der Gezeitenweisen! Wir müssen ihnen helfen.', '', 28153),
(143268, 'deDE', 'Den Gezeiten sei Dank. Es sind nicht alle verrückt geworden. Das halbe Haus hat den Verstand verloren.', '', 28153),
(143267, 'deDE', 'Mir wäre etwas weniger Flanell recht.', 'Mir wäre etwas weniger Flanell recht.', 28153),
(143266, 'deDE', '', 'Ich reite voraus. Wir treffen uns am Ufer!', 28153),
(143265, 'deDE', 'Gut seht Ihr aus, $n.', '', 28153),
(143264, 'deDE', 'Wir haben Arbeit zu erledigen.', '', 28153),
(143263, 'deDE', 'Mir wäre etwas mehr Flanell recht.', 'Mir wäre etwas mehr Flanell recht.', 28153),
(143262, 'deDE', '', 'Zu den Waffen!', 28153),
(143261, 'deDE', '', 'Für den König!', 28153),
(143260, 'deDE', '', 'Kommt nur her!', 28153),
(143259, 'deDE', '', 'Bis zum Tode!', 28153),
(143258, 'deDE', '', 'Für Sturmwind!', 28153),
(143257, 'deDE', '', 'Für die Allianz!', 28153),
(143256, 'deDE', '', 'Kein Rückzug!', 28153),
(143255, 'deDE', '', 'Lasst mich ran!', 28153),
(143254, 'deDE', '', 'Von welcher Verderbnis redet Ihr? $n, vielleicht betrachtet das Ding die Bluttrolle als \"Verderbnis\".', 28153),
(143253, 'deDE', '', 'Wisst Ihr, was das für\'n Ding is\', $n? Glaubt Ihr, es würd uns helf\'n?', 28153),
(143252, 'deDE', '', 'Was\'n das für\'n Voodoo? Vielleicht kann uns das helf\'n, die Bluttrolle un\' G\'huun aufzuhalt\'n.', 28153),
(143251, 'deDE', 'Lasst mich ran!', '', 28153),
(143250, 'deDE', 'Kein Rückzug!', '', 28153),
(143249, 'deDE', 'Für die Allianz!', '', 28153),
(143248, 'deDE', 'Für Sturmwind!', '', 28153),
(143247, 'deDE', 'Bis zum Tode!', '', 28153),
(143246, 'deDE', 'Kommt nur her!', '', 28153),
(143245, 'deDE', 'Für den König!', '', 28153),
(143244, 'deDE', 'Zu den Waffen!', '', 28153),
(143243, 'deDE', 'Wahnsinn, der Detektor flippt total aus! Irgendwo muss die Insel grade massenweise Azerit ausspucken.', '', 28153),
(143242, 'deDE', 'Wir müssen die Quelle dieser Entweihung entdecken.', '', 28153),
(143241, 'deDE', '', 'Möge diese Rüstung Euch daran erinnern, was Ihr erreicht habt, $p. Nehmt sie mit meinem Dank entgegen.', 28153),
(143240, 'deDE', 'Absolut.', '', 28153),
(143239, 'deDE', 'Ähm, eeh... denkt... denkt Ihr, die Meereswesen sind auch davon betroffen?', '', 28153),
(143238, 'deDE', 'Und noch ein \"böses Omen\": In der Bucht sind Berge von Sturmtaklerbeute.', '', 28153),
(143237, 'deDE', 'Tsunga schaut besorgt in den Höhleneingang.', '', 28153),
(143236, 'deDE', '', 'Viele hatten Zweifel, dass die Ren\'dorei die Macht der Leere nutzen können, ohne ihrem Einfluss zu erliegen. Ihr habt es ihnen bewiesen.', 28153),
(143235, 'deDE', 'Die Schreie der Flut werden lauter, während wir in die Bucht dringen. Ich spüre die Qualen der Gezeiten. Das ist ein wirklich dunkles Omen.', '', 28153),
(143234, 'deDE', '', 'Ihr seid zu einer beeindruckenden Waffe der Allianz geworden, $p. Kehrt zurück zum Leerenspalt. Wir werden dort Euren Erfolg ehren.', 28153),
(143233, 'deDE', 'Lasst uns diese Aufgabe hinter uns bringen.', '', 28153),
(143230, 'deDE', 'Ich fange gleich mit der Ausbildung an. Sucht Tagart, der hat noch mehr für Euch.', '', 28153),
(143229, 'deDE', 'Neustart von Titanenhüter Hezrel. Direktive: Ausgebrochene Verderbnis innerhalb Nazmirs eindämmen. Aufgabe unmöglich. Systeme beschädigt.', '', 28153),
(143228, 'deDE', '', 'Während Eurer Reisen durch Azeroth habt Ihr gelernt, Kräfte zu beherrschen, die ständig versuchen, Besitz von Euch zu ergreifen.', 28153),
(143227, 'deDE', 'Guter Fang, mein Freund. Mal schauen, wie der fliegt. Hi-ah!', '', 28153),
(143226, 'deDE', 'Ho, ho! Schau mal einer an, was die Hauskatze angeschleppt hat! Unglaublich!', '', 28153),
(143224, 'deDE', 'Ich sag König Rastakhan Bescheid, dass die Signale auf den Türm\'n brenn\', wenn die Schiffe zurückerobert sin\'. So weiß auch meine Crew, sie kann nach Hause komm\'.', '', 28153),
(143223, 'deDE', 'Das gewünschte Motiv ist in diesem Bild nicht klar zu sehen. Wulferd wird das nicht gefallen.', 'Das gewünschte Motiv ist in diesem Bild nicht klar zu sehen. Wulferd wird das nicht gefallen.', 28153),
(143222, 'deDE', 'Gewährt mir Eure Hilfe!', '', 28153),
(143221, 'deDE', 'Meine Arbeiter... es ist alles meine Schuld.', '', 28153),
(143220, 'deDE', '', 'Hilfe! Der Kommandant wurde getroffen!', 28153),
(143219, 'deDE', 'Hilfe! Ich werde angegriffen!', '', 28153),
(143218, 'deDE', 'Dafür werdet Ihr bezahlen!', '', 28153),
(143217, 'deDE', 'Bei dem Typ stellen sich mir echt die Federn!', '', 28153),
(143216, 'deDE', 'Nein! Jetzt leidet mein Versicherungsbeitrag!', '', 28153),
(143215, 'deDE', 'Wofür bezahl ich Euch Trottel eigentlich? Raus da und repariert das!', '', 28153),
(143214, 'deDE', 'Lust auf ein Großkalibergemetzel?', '', 28153),
(143213, 'deDE', 'Zieht Euch das rein! 300 Schuss pro Minute!', '', 28153),
(143212, 'deDE', 'Genau da gehört Ihr hin... in den Dreck!', '', 28153),
(143211, 'deDE', 'Fresst Staub!', '', 28153),
(143210, 'deDE', '', 'Ich erkunde die Gegend etwas und treffe Euch weiter vorne.', 28153),
(143209, 'deDE', 'Lebend kriegt Ihr mich nie.', '', 28153),
(143208, 'deDE', 'Hätt ich... mir doch bloß... den Schleudersitz geleistet...', '', 28153),
(143207, 'deDE', 'Die verbrauchte Munition stell ich Euren nächsten Angehörigen in Rechnung.', '', 28153),
(143206, 'deDE', '', 'Nutzt, was ich Euch gelehrt habe, um die Kontrolle zu behalten. Werdet zu einer Waffe für die Allianz... auch wenn Ihr dafür am Rande der Finsternis wandelt.', 28153),
(143205, 'deDE', 'Es wird die geben, die Euch in Frage stellen, an Eurer Entschlossenheit zweifeln – an Eurem Vermögen, Mächte zu bändigen, die schwächeren Geistern zum Verhängnis wurden.', '', 28153),
(143204, 'deDE', '', 'Aber wir sehen Alternativen. Viele Pfade – viele Möglichkeiten – die uns offen stehen.', 28153),
(143203, 'deDE', '', 'Manche werden Euch sagen, das Licht ist der einzige Weg. Die eine Waffe, die die Feinde von Azeroth stoppen kann.', 28153),
(143202, 'deDE', 'Wisst Ihr Trampel eigentlich, wie viel Sachschaden Ihr hier angerichtet habt?', '', 28153),
(143201, 'deDE', 'Willkommen bei den Raubeinen!', '', 28153),
(143200, 'deDE', 'Es is\' genau so, wie die alte Schlange gesagt hat. Klettert an Bord. Der König wartet.', '', 28153),
(143199, 'deDE', 'Zerquetschen!', '', 28153),
(143198, 'deDE', 'Einstampfen!', '', 28153),
(143197, 'deDE', 'Plattmachen!', '', 28153),
(143196, 'deDE', 'Eine wahre Schande, dass ich ihm das Allerwichtigste nich\' mehr beibring\'n konnte.', '', 28153),
(143195, 'deDE', 'Sagt dem alten Rastakhan, ich kehre später zurück. Ah, un\' danke für Eure Hilfe.', '', 28153),
(143193, 'deDE', 'Wenn ich Yazma und Zul in meine Klauen bekomme, werde ich sie auf einen Felsen stürzen lassen!', '', 28153),
(143192, 'deDE', 'Unsere Beute ist nahe. Das Blut von Zul, Yazma und ihren Ketzern wird schon bald fließen. Es wird eine großartige Jagd.', '', 28153),
(143191, 'deDE', 'Ruhm für Pa\'ku!', 'Ruhm für Pa\'ku!', 28153),
(143190, 'deDE', 'Wir hol\'n uns das Schiff zurück!', 'Wir hol\'n uns das Schiff zurück!', 28153),
(143189, 'deDE', 'Taz\'okun!', 'Taz\'okun!', 28153),
(143188, 'deDE', 'Das ist nur eine Fleischwunde. Ich werde es wohl schaffen...', '', 28153),
(143185, 'deDE', '', 'Gleich wird\'s Euch zu heiß.', 28153),
(143184, 'deDE', '', 'Brennt! Jahaha! Brennt!', 28153),
(143183, 'deDE', '', 'Ihr sucht Azerit? Hier habt Ihr welches!', 28153),
(143182, 'deDE', '', 'Und dabei ist hier schon seit Tagen keiner mehr einen grausigen Flammentod gestorben...', 28153),
(143181, 'deDE', 'Nichts ist das hier wert!', '', 28153),
(143180, 'deDE', '', 'Mangelnde Erfahrung ist Todesursache Nummer 1.', 28153),
(143179, 'deDE', 'Für die Allianz!', '', 28153),
(143178, 'deDE', '', 'Es ist mir eine Ehre erneut zu dienen, Hochkönig. Für die Allianz!', 28153),
(143177, 'deDE', '', 'Wieder ein unbrauchbares Testobjekt.', 28153),
(143176, 'deDE', 'Lady Windläufer, $p, Ihr habt uns heute einen großen Dienst erwiesen. Ich danke Euch.', '', 28153),
(143175, 'deDE', 'Es wird einige Zeit dauern, bis diese Leerenelfen das Vertrauen aller in unseren Rängen gewonnen haben. Doch so lange sie Euren Lehren folgen, sind sie in der Allianz willkommen.', '', 28153),
(143174, 'deDE', '', 'Ich brauche... eine... Gefahrenzulage...', 28153),
(143173, 'deDE', '', 'Ich werde sie führen, ihnen beibringen, das Flüstern der Schatten zu kontrollieren. Im Gegenzug werden sie gemeinsam mit der Allianz gegen all ihre Feinde kämpfen.', 28153),
(143172, 'deDE', '', 'Hochkönig Wrynn, $p und ich haben die verstoßenen Sin\'dorei aufgespürt. Ähnlich wie mich hat die Leere auch sie verändert – doch ihr Herz und Verstand gehören immer noch ihnen selbst.', 28153),
(143171, 'deDE', '', 'Wenn man will, dass etwas richtig gemacht wird... muss man mehr Sprengstoff verwenden.', 28153),
(143170, 'deDE', '', 'Ihr seid der Grund, dass meine Gehilfen geflohen sind?', 28153),
(143169, 'deDE', '', 'Hey! Wo wollt Ihr denn so schnell hin?', 28153),
(143168, 'deDE', 'Eindringlinge? Lauft!', 'Eindringlinge? Lauft!', 28153),
(143167, 'deDE', 'Ich weiß nicht, welche Dunkelheit Euren Geist benebelt hat, Schwester, aber sie wird unser Volk nicht länger quälen.', '', 28153),
(143166, 'deDE', 'Ihr schafft das!', '', 28153),
(143165, 'deDE', 'Schiff außer Kontrolle!', '', 28153),
(143164, 'deDE', '', 'Ich will keine Beschwerden mehr hören über unsichere Arbeitsbedingungen!', 28153),
(143163, 'deDE', 'Hier ist es nicht sicher. Verschwindet so schnell Ihr könnt.', '', 28153),
(143162, 'deDE', 'Ist sowieso keine schöne Insel!', '', 28153),
(143161, 'deDE', 'Wir sind verdammt!', '', 28153),
(143160, 'deDE', 'Fort mit Euch! Eure Arbeit hier ist getan.', '', 28153),
(143159, 'deDE', 'Es hat sich losgerissen! Zurück!', '', 28153),
(143158, 'deDE', 'Ihr seid frei, Brüder und Schwestern.', '', 28153),
(143157, 'deDE', '', 'Wer meckert, der hält nicht den Atem an und ist somit selbst Schuld, wenn er giftige Dämpfe einatmet.', 28153),
(143156, 'deDE', 'Lauft zu Euren Familien. Wir kümmern uns um den Rest.', '', 28153),
(143155, 'deDE', 'Flieht, Ihr Narren!', '', 28153),
(143154, 'deDE', 'Befreit Eure Seele aus ihrer sterblichen Hülle und lasst sie sinken.', '', 28153),
(143153, 'deDE', 'Hört den Gesang des Sturms und findet Frieden.', '', 28153),
(143152, 'deDE', 'Fragt nicht, für wen der Leuchtturm strahlt. Er strahlt für Euch.', '', 28153),
(143151, 'deDE', '', 'Für die Horde!', 28153),
(143150, 'deDE', '', 'Für die Horde!', 28153),
(143149, 'deDE', '', 'Suramar kämpft an der Seite der Horde!', 28153),
(143148, 'deDE', '', 'Jahrtausendelang stand Suramar allein. Mit dem heutigen Tag wird Euer Volk Teil von etwas Größerem werden. Ich nehme Euren Treueschwur an, Thalyssra.', 28153),
(143147, 'deDE', '', 'Es ist Zeit, dass die Nachtgeborenen Verbündete unter den Königreichen von Azeroth finden. Wir wären geehrt, uns Eurer Sache anschließen zu dürfen.', 28153),
(143146, 'deDE', '', 'Die Horde steht für Stärke. Entschlossenheit. Individualität. Eigenschaften, die auch uns Shal\'dorei wichtig sind.', 28153),
(143145, 'deDE', '', 'Dem stimme ich zu, Erste Arkanistin.', 28153),
(143144, 'deDE', '', 'Es ist mir eine Ehre, Kriegshäuptling. Ich habe an der Seite von Lady Liadrin und dem Lordregenten gekämpft. Ihr Mut ehrt Eure Horde.', 28153),
(143143, 'deDE', 'Fürchtet Euch nicht, Bruder. Die Wellen werden Euch gnädig sein.', '', 28153),
(143142, 'deDE', 'Ebbe und Flut, vernehmt die Klagen dieses Geistes.', '', 28153),
(143141, 'deDE', 'Möge Euer kühner Geist ewig ruhen.', '', 28153),
(143140, 'deDE', 'Möge die Tiefe Eure müde Seele aufnehmen.', '', 28153),
(143139, 'deDE', 'Möge die Gezeitenmutter Euer verderbtes Fleisch läutern.', '', 28153),
(143138, 'deDE', 'Die Strömung wird Euch tragen, Gefallene.', '', 28153),
(143137, 'deDE', 'Die Erde wird Euch verschlingen!', '', 28153),
(143136, 'deDE', 'See zu See, Asche zu Asche, Flut zu Flut.', '', 28153),
(143135, 'deDE', 'Erzittert!', '', 28153),
(143134, 'deDE', 'Das Blut von Azeroth durchfließt Euch.', '', 28153),
(143133, 'deDE', 'Wir dürfen diese verlorenen Seelen nicht länger umherirren lassen. Ich muss mit Euch sprechen, $p.', '', 28153),
(143132, 'deDE', 'Entfesselt Eure Macht!', '', 28153),
(143131, 'deDE', 'Tropfnass, aber noch lesbar. Diese Zaubersprüche werden uns gute Dienste leisten.', '', 28153),
(143130, 'deDE', 'Die Nebel des Ozeans verdecken viel, aber dieses Leuchtfeuer wird uns den Weg weisen.', '', 28153),
(143129, 'deDE', 'Erhebt Euch!', '', 28153),
(143128, 'deDE', '', 'Willkomm\'n, Kind. Das Augenlicht mag mich verlassen hab\'n, aber Pa\'ku hat das nich\'.\n\nSetzt Euch zu mir und stellt Eure Fragen an den großen Loa. Ich werd sie so gut es geht beantwort\'n.', 28153),
(143127, 'deDE', 'Gut, die Klinge ist noch scharf. Eine scharfe Klinge ist eine sichere Klinge.', '', 28153),
(143126, 'deDE', 'Ihr richtet keinen Schaden mehr an.', '', 28153),
(143125, 'deDE', 'Was ist Euer Blut schon wert?', '', 28153),
(143124, 'deDE', '', 'Kriegshäuptling Sylvanas Windläufer, ich stelle vor: Erste Arkanistin Thalyssra von Suramar.', 28153),
(143123, 'deDE', '', 'Ich stoße zu den anderen und warte auf Euer Kommando, Festländer.', 28153),
(143122, 'deDE', '', 'Das bezweifle ich... aber Befehl ist Befehl.', 28153),
(143121, 'deDE', '', 'Marschall Lesner glaubt also, Ihr seid der Schlüssel zum Sieg gegen den Zirkel?', 28153),
(143120, 'deDE', 'Jetzt zeigt mal, was Ihr drauf habt!', '', 28153),
(143119, 'deDE', 'Heh, wurde auch langsam Zeit.', '', 28153),
(143118, 'deDE', 'Hängt Euch ordentlich rein!', '', 28153),
(143117, 'deDE', 'Zieht!', '', 28153),
(143116, 'deDE', 'Komm, Wilhelm. Wir müssen uns um ein paar Hexen kümmern.', '', 28153),
(143115, 'deDE', 'Noch ein paar tiefe Schnitte und dann haben wir es.', '', 28153),
(143114, 'deDE', 'Fast geschafft! Nur noch ein bisschen.', '', 28153),
(143113, 'deDE', 'Gibt es neue Befehle?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143112, 'deDE', 'Ich danke Euch für die Nachricht. Ich melde mich umgehend bei Fräulein Kronsteig zum Dienst.', '', 28153),
(143111, 'deDE', 'Ich dachte immer, die Geschichten wären nur Hirngespinste eines Historikers.', '', 28153),
(143110, 'deDE', 'Ihr wart nie mehr als Parasiten.', '', 28153),
(143109, 'deDE', 'Die Gerüchte sind also wahr? Der Glutorden wurde wieder zum Leben erweckt?', '', 28153),
(143108, 'deDE', 'Die Wunden... müssen geheilt werden...', '', 28153),
(143107, 'deDE', '', 'Ihr habt meine Klinge, Fremdling.', 28153),
(143106, 'deDE', 'Ihr seid in meinem Reich nicht erwünscht.', '', 28153),
(143105, 'deDE', '', 'Ich glaube nicht an den ganzen Hokuspokus, aber alles ist besser, als nur darauf zu warten, dass der Zirkel uns alle umbringt.', 28153),
(143104, 'deDE', '', 'Ihr steckt also hinter diesem Glutorden, von dem ich gehört habe.', 28153),
(143103, 'deDE', '<Überreicht Marschall Lesners Befehle.>', '<Überreicht Marschall Lesners Befehle.>', 28153),
(143102, 'deDE', '', 'Hier ziehen die Steinkonstrukte ins Feld. Lebendige Krieger wurden rar, also schuf er eine neue Armee. Aber was verlieh den Steinen Macht?', 28153),
(143101, 'deDE', '', 'Was kann ich für Euch tun, $C?', 28153),
(143100, 'deDE', '', 'Das ist Gorak Tul, ihr größter Anführer. Ah! Er versucht, in einem Ritual die Steinkonstrukte zu erschaffen!', 28153),
(143099, 'deDE', '<Leutnant Hartwasser nickt Euch zu, als Ihr Euch nähert.>', '', 28153),
(143098, 'deDE', 'Ein schönes Tier, nicht wahr? Das Haus Kronsteig hat eine lange Tradition in der Falknerei.\n\nLeider sind die meisten unserer besten Vögel dem Fluch des Zirkels zum Opfer gefallen. Wilhelm hier ist einer der wenigen Falken des Hauses Kronsteig, der nicht von diesem Zauber betroffen ist.\n\nDas sind wirklich traurige Zeiten.', '', 28153),
(143097, 'deDE', '', 'Aber das... dieses Gemeltzel wird verherrlicht! Die Kul Tiraner haben nicht einmal Waffen!', 28153),
(143096, 'deDE', 'Im Wald treibt sich etwas Böses herum, $gFestländer:Festländerin;. Bei Nacht leuchtet das uralte Drustmonument in seiner Mitte vor unheiliger Macht.\n\nAn Eurer Stelle würde ich einen großen Bogen darum machen.', '', 28153),
(143095, 'deDE', '', 'Was gibt es denn, $gFestländer:Festländerin;?\n\nIch bin ziemlich beschäftigt, falls Ihr das übersehen habt.', 28153),
(143094, 'deDE', 'EINDRINGLINGE ELIMINIEREN, VER-VERNICHTEN. VERNICHTEN.', '', 28153),
(143093, 'deDE', 'FREISETZUNG DER VERDERBNIS BEVORSTEHEND. AKT-AKTIVIERE SI-SI-SICHERHEITSPROTOKOLLE. EINDR-EINDRINGLINGE ERKANNT.', '', 28153),
(143092, 'deDE', 'FEHLER... EINDRINGEN... ERM-ERMITTELT... SCANNEN NACH... VERDERBNIS...', '', 28153),
(143091, 'deDE', 'Giftgaseinsatz autorisiert.', '', 28153),
(143090, 'deDE', 'Stromspannung erhöht.', '', 28153),
(143089, 'deDE', 'Systeme aktiv. Beginne Verprügelung.', '', 28153),
(143088, 'deDE', '', 'Die Kul Tiraner in diesem Relief wirken fast wie... Zivilisten? Seefahrer und Bauern?', 28153),
(143087, 'deDE', '', 'Selbst ihr Anführer zieht sich aus der Schlacht zurück.', 28153),
(143086, 'deDE', '', 'HA! Und hier schlagen wir zurück!', 28153),
(143085, 'deDE', '', 'Es ist kurios, dass wir keines ihrer Konstrukte ins Feld ziehen sehen.', 28153),
(143084, 'deDE', 'Die Venture Company dankt Euch für Euer Vertrauen und wünscht Euch viel Spaß mit Eurem neuen Premiumprügelpaket.', '', 28153),
(143083, 'deDE', '', 'Ein Sieg über eine weitere Siedlung der Kul Tiraner. Die große Figur im Zentrum ist ihr legendärer Anführer, denke ich.', 28153),
(143082, 'deDE', 'Die Venture Company dankt Euch für Euer Vertrauen und wünscht Euch viel Vergnügen mit Eurem neuen Basisprügelpaket.', '', 28153),
(143081, 'deDE', 'Gebt mir ein paar Monate und ich polier\' die Pfütze hier zum Luxusresort auf!', '', 28153),
(143080, 'deDE', 'Dämlack! Die Garantieverlängerung sollte man NIE kaufen!', 'Dämlack! Die Garantieverlängerung sollte man NIE kaufen!', 28153),
(143079, 'deDE', 'Okay, okay. Moment... Soll ich \'ne Garantieverlängerung kaufen?', 'Okay, okay. Moment... Soll ich \'ne Garantieverlängerung kaufen?', 28153),
(143078, 'deDE', 'Kommt, $p.', '', 28153),
(143077, 'deDE', 'Wir werden alle sterben!', 'Wir werden alle sterben!', 28153),
(143076, 'deDE', 'Hetzt mich nicht! Ich les\' die Lizenzvereinbarung.', 'Hetzt mich nicht! Ich les\' die Lizenzvereinbarung.', 28153),
(143075, 'deDE', 'Schnell! Sie kommen!', 'Schnell! Sie kommen!', 28153),
(143074, 'deDE', 'Ich brauchte nur eine kleine Pause.', '', 28153),
(143073, 'deDE', 'Ganz ruhig. Gutes Mädchen. Ruhig.', '', 28153),
(143072, 'deDE', 'Systeme... versagen. Münzausgabe... blockiert...', '', 28153),
(143071, 'deDE', 'Wer möchte eine Runde fliegen? Wollt Ihr eine Runde fliegen? Lasst uns fliegen!', '', 28153),
(143070, 'deDE', 'Nicht beißen!', '', 28153),
(143069, 'deDE', 'Schadensbegrenzungsprotokoll aktiviert.', '', 28153),
(143068, 'deDE', 'Beschädigungen dieser Maschine verstoßen gegen die Nutzungsbedingungen.', '', 28153),
(143067, 'deDE', 'Bomben los!', 'Bomben los!', 28153),
(143066, 'deDE', 'Aufgepasst da unten, Ihr Drecksäcke!', 'Aufgepasst da unten, Ihr Drecksäcke!', 28153),
(143065, 'deDE', 'Heda! Zurück an die Arbeit!', 'Heda! Zurück an die Arbeit!', 28153),
(143064, 'deDE', 'Tötungsprotokolle autorisiert.', '', 28153),
(143063, 'deDE', 'Versammlungsgröße überschreitet zulässiges Maximum. Breche Meute auf.', '', 28153),
(143062, 'deDE', 'Fragt nach unseren günstigen Bestattungsleistungen.', '', 28153),
(143061, 'deDE', 'Ein weiterer Kunde wurde zufriedengestellt.', '', 28153),
(143060, 'deDE', 'Die Venture Company übernimmt keine Haftung für verlorene Gliedmaßen.', '', 28153),
(143059, 'deDE', 'Die Horde hat einen Angriff abgewehrt!', 'Die Horde hat einen Angriff abgewehrt!', 28153),
(143058, 'deDE', 'Ausschwärmen! Diese Allianzhunde werden uns bald mit Verstärkung auf den Leib rücken.', '', 28153),
(143057, 'deDE', '', 'Sobald das Schiff hier den Hafen erobert hat, werd ich Käpt\'n! Merkt Euch das und übt schon mal, Euch zu verbeug\'n!', 28153),
(143056, 'deDE', '', 'Die Gefangenen wiss\'n gar nich\', was für \'n Glück sie ham! Sie werd\'n schon bald Zul treff\'n!', 28153),
(143055, 'deDE', '', 'Wenn wir dies\'n Hafen erobern woll\'n, müsst Ihr schon mehr biet\'n als das!', 28153),
(143054, 'deDE', 'Ich kann nicht... Hilfe... AAAAAAAUUURGH!', '', 28153),
(143050, 'deDE', 'Nein! Ich werd hier nich\' sterb\'n! Nich\' jetz\'!', '', 28153),
(143049, 'deDE', 'Wie konnte er... das wiss\'n...', '', 28153),
(143048, 'deDE', 'Das... das passiert nich\' wirklich!', '', 28153),
(143047, 'deDE', 'Ihr seid stark... aber meine Sicht is\' stärker!', '', 28153),
(143046, 'deDE', 'Weg von mir! Das is\'n Befehl!', '', 28153),
(143045, 'deDE', 'Meine Erwählt\'n! Euer Meister braucht Euch!', '', 28153),
(143044, 'deDE', 'IHR werdet hier sterb\'n!', '', 28153),
(143043, 'deDE', 'Nich\' mit mir, alter Mann!', '', 28153),
(143042, 'deDE', 'Nich\' ich werd Euch töten. Aber mein Freund.', '', 28153),
(143041, 'deDE', 'Ihr wisst, dass nich\' Ihr mich töt\'n werdet. Ihr könnt mich nich\' aufhalt\'n.', '', 28153),
(143040, 'deDE', 'Gut so. Ist fast Zeit für ein Leckerli!', '', 28153),
(143039, 'deDE', 'Genug der Spielchen. Ihr habt Eure Nachricht überbracht, jetz\' stellt Euch Eurem Schicksal.', '', 28153),
(143038, 'deDE', 'Zul schüttet den Trank in einem großen Schluck hinunter. Der Geschmack lässt ihn schaudern.', '', 28153),
(143037, 'deDE', 'Den ersten, den Ihr seht. Nich\' denken, einfach mach\'n.', '', 28153),
(143036, 'deDE', 'Seine Diener werd\'n versuch\'n, Euch aufzuhalten. Passt auf.', '', 28153),
(143035, 'deDE', 'Hm.', '', 28153),
(143034, 'deDE', 'Kommt her. Es is\' Zeit.', '', 28153),
(143033, 'deDE', 'Gut. Jetzt vertauscht ein\' von Vol\'jambas Tränken, mit dem, den Ihr von mir habt.', '', 28153),
(143032, 'deDE', 'Wobei... bewegt sie \'n bisschen nach links.', '', 28153),
(143031, 'deDE', 'Und jetzt platziert die Urne beim Durchgang.', '', 28153),
(143030, 'deDE', 'Haltet Eure Waffen außerhalb der Botschaft bereit, $p. Den Zandalari fehlt die notwendige Stärke und der Wille, die Kontrolle zu bewahren. Sie brauchen einen starken Kriegshäuptling wie unseren.\n\nNun, was kann ich für Euch tun?', 'Haltet Eure Waffen außerhalb der Botschaft bereit, $p. Den Zandalari fehlt die notwendige Stärke und der Wille, die Kontrolle zu bewahren. Sie brauchen einen starken Kriegshäuptling wie unseren.\n\nNun, was kann ich für Euch tun?', 28153),
(143029, 'deDE', 'Wenn Ihr Allianzler herumschleichen seht, lasst es mich wissen. Ich kümmere mich darum.\n\nSucht Ihr ansonsten nach irgendetwas?', 'Wenn Ihr Allianzler herumschleichen seht, lasst es mich wissen. Ich kümmere mich darum.\n\nSucht Ihr ansonsten nach irgendetwas?', 28153),
(143028, 'deDE', 'Also eins kann ich über die Zandalari mit Sicherheit sagen: Sie wissen, wie man Botschaften baut. Und die Stadt ist riesig!\n\nHabt Ihr Euch verlaufen?', 'Also eins kann ich über die Zandalari mit Sicherheit sagen: Sie wissen, wie man Botschaften baut. Und die Stadt ist riesig!\n\nHabt Ihr Euch verlaufen?', 28153),
(143027, 'deDE', 'Ich bin beschäftigt. Fasst Euch kurz.', 'Ich bin beschäftigt. Fasst Euch kurz.', 28153),
(143026, 'deDE', 'Was braucht Ihr, $PR?', 'Was braucht Ihr, $PR?', 28153),
(143025, 'deDE', 'Ruhm dem Kriegshäuptling! Sucht Ihr etwas?', 'Ruhm dem Kriegshäuptling! Sucht Ihr etwas?', 28153),
(143024, 'deDE', 'Dieses gewaltige Botschaftsgebäude beweist, dass die Zandalari die Stärke unseres Kriegshäuptlings respektieren. Sie sollten sie ebenso fürchten.\n\nAlso, was wollt Ihr?', 'Dieses gewaltige Botschaftsgebäude beweist, dass die Zandalari die Stärke unseres Kriegshäuptlings respektieren. Sie sollten sie ebenso fürchten.\n\nAlso, was wollt Ihr?', 28153),
(143023, 'deDE', 'Bei dieser Luftfeuchtigkeit schwitzen sogar meine Knochen. Was kann ich für Euch tun?', 'Bei dieser Luftfeuchtigkeit schwitzen sogar meine Knochen. Was kann ich für Euch tun?', 28153),
(143022, 'deDE', 'Wir sind auf dem Weg nach oben, mein Großer. Eines Tages wird all das uns gehören.', '', 28153),
(143021, 'deDE', 'Wofür bezahlen wir Euch eigentlich? Fürs Ausruhen?', '', 28153),
(143020, 'deDE', '', 'Vielleicht ist Tod das wahre Vermächtnis der Windläufer.', 28153),
(143019, 'deDE', '', 'Allerdings. Manchmal kommt es mir vor, als wäre ich schon zweimal gestorben. Einmal auf Draenor, verloren geglaubt, und dann in den Fängen des gefallenen Naaru.', 28153),
(143018, 'deDE', 'Es ist verstörend, diese Mahnmale unseres Ablebens zu sehen.', '', 28153),
(143017, 'deDE', '', 'Es ist Zeit, Turalyon. Ich muss meine Heimat mit eigenen Augen wiedersehen... und von Sylvanas selbst hören, wie sie zum Kriegshäuptling werden konnte.', 28153),
(143016, 'deDE', 'Jede von euch hat ihren eigenen Pfad. Wenn es der Wille des Lichts ist, dass sie sich kreuzen, werden sie es. Du solltest euer Schicksal nicht erzwingen.', '', 28153),
(143015, 'deDE', 'Du musst nicht gehen. Du musst sie nicht treffen.', '', 28153),
(143014, 'deDE', '', 'Wie niemand sonst, mein Liebster.', 28153),
(143013, 'deDE', 'Du bist besorgt. Du verbirgst es gut... aber ich kenne dich.', '', 28153),
(143012, 'deDE', 'Ich weiß, vor uns liegen harte Zeiten. Aber was auch kommt... vergesst nie unsere Pflicht gegenüber Azeroth!', '', 28153),
(143011, 'deDE', 'Die Energie, die durch Eure Waffe tost... so etwas habe ich noch nie gesehen! Denkt immer daran – jede Macht hat ihren Preis.', '', 28153),
(143010, 'deDE', 'Ihr habt es geschafft! Sargeras\' Schwert ruht. Azeroth ist noch nicht geheilt... aber Ihr habt uns wertvolle Zeit erkauft.', '', 28153),
(143009, 'deDE', 'Gemeinsam, Champions! Für Azeroth!', '', 28153),
(143008, 'deDE', 'Erhebt sie, vereint... treibt die Verderbnis aus der Klinge des Dunklen Titanen!', '', 28153),
(143007, 'deDE', 'Die einzigen Gefäße, die dieser Gewalt standhalten können... sind die mächtigen Waffen, die Ihr führt.', '', 28153),
(143006, 'deDE', 'Das Schwert von Sargeras vergiftet das Lebensblut der Welt selbst.', '', 28153),
(143005, 'deDE', 'Kommt nach Silithus... solange es noch eine Welt gibt, für die wir kämpfen können!', '', 28153),
(143004, 'deDE', 'Ich weiß, die Spannungen steigen... aber ich bitte Euch, noch einmal Schulter an Schulter zu stehen.', '', 28153),
(143003, 'deDE', 'Champions, Ihr habt die Orden um Euch gesammelt und zusammen die Legion von Azeroth verjagt.', '', 28153),
(143002, 'deDE', 'Ein Sturm braut sich zusammen, $p. Wenn wir Azeroth nicht heilen können... ist alles andere bedeutungslos.', '', 28153),
(143001, 'deDE', 'Ich weiß nicht, wie ich helfen kann. Oder irgendwer sonst. Aber wir müssen es weiter versuchen.', '', 28153),
(143000, 'deDE', 'Seit wir von Argus zurück sind, sind die Schreie von Azeroth... überwältigend. Solche Schmerzen...', '', 28153),
(142999, 'deDE', 'Champion... in so dunklen Zeiten tut es gut, ein vertrautes Gesicht zu sehen.', '', 28153),
(142998, 'deDE', 'Wir warten immer noch auf die, Prinzessin. Aber wir ham \'ne Spur zum Loa Krag\'wa.', '', 28153),
(142997, 'deDE', '', '... un\' das is\' Torgas Schicksal. Was gibt\'s Neues von der Verstärkung der Horde?', 28153),
(142996, 'deDE', 'Wir haben\'s beinahe geschafft, $n. Nur noch \'n kleines bisschen.', '', 28153),
(142995, 'deDE', 'Ich kann nicht glauben, dass diese Monster Torga abgeschlachtet haben...', '', 28153),
(142994, 'deDE', 'Mist, jetzt ist Torga tot und es gibt nichts, was ich den anderen erzählen könnte.', '', 28153),
(142993, 'deDE', 'Wo ist Kisha? Ich dachte, sie wäre hier, um uns den Weg zu zeigen...', '', 28153),
(142992, 'deDE', 'Also gut, dann gehe ich eben zum Trübsumpf. Mal sehen, wie verrückt es noch wird.', '', 28153),
(142991, 'deDE', 'Hm... Gegen eine Horde Bluttrolle zu kämpfen, wäre wohl auch eine interessante Geschichte. Na schön, dann gehe ich also zum Trübsumpf.', '', 28153),
(142990, 'deDE', 'Ihr habt... WAS?! Ich werde mir das nicht entgehen lassen. Ich gehe jetzt zum Trübsumpf.', '', 28153),
(142989, 'deDE', 'Okay, Kisha, gehen wir zurück zum Trübsumpf und sammeln wir Tortollaner ein, die wir auf dem Weg treffen. Unser Helferchen hier wird alle mitnehmen, die wir vergessen haben.', '', 28153),
(142988, 'deDE', '', 'Ich schlag mich zum Trübsumpf durch und Ihr kümmert Euch um die Tortollaner auf\'m Weg.', 28153),
(142987, 'deDE', '$n, bemannt diese Kanonen!', '', 28153),
(142986, 'deDE', 'Viel Glück, $p. Ich werde meine Fähigkeiten im Eschental unter Beweis stellen. Für die Horde!', '', 28153),
(142985, 'deDE', 'Die Atem von Pa\'ku un\' die Rezans Klaue ham die ganze Welt umfahr\'n. Helft ihnen, nach Hause zu komm\'n.', '', 28153),
(142984, 'deDE', 'Als die Schiffe zurückkam\'n, hing \'ne Dunkelheit über ihnen. Ich hatte \'n schlimmes Gefühl in der Magengrube.', '', 28153),
(142983, 'deDE', 'Die Atem von Pa\'ku war mein Zuhause... viele Jahre lang, Mann. Der Hafen un\' mein Herz... beide war\'n leer, als sie ausgelauf\'n is\'.', '', 28153),
(142982, 'deDE', 'Das Brüllen von Donnerbringer Anji erfüllt Euch mit Lebenskraft.', '', 28153),
(142981, 'deDE', 'Oi! Ab ins Boot! Der Käpt\'n sagt, die Atem von Pa\'ku is\' in Schwierigkeiten!', '', 28153),
(142980, 'deDE', '', 'Kommandant, wir sind hier, um zu helfen. Heute wird der Damm nicht brechen!', 28153),
(142979, 'deDE', '', 'Lasst uns zum Damm gehen. Kommandant Kellmann wartet nicht gerne!', 28153),
(142977, 'deDE', 'Ihr seid dieser Gesellschaft nicht würdig!', '', 28153),
(142976, 'deDE', 'Ihr seid ein Narr und ein Feigling darüber hinaus!', '', 28153),
(142975, 'deDE', 'Ja, kommt mir, lausiger Eindringling!', '', 28153),
(142974, 'deDE', 'Hebt Euch hinweg, Ihr Spitzbube!', '', 28153),
(142973, 'deDE', 'Ich werde Euch mit der Faust bedienen!', '', 28153),
(142972, 'deDE', 'Ich werde Euch in Greinen und Winseln hineinprügeln!', '', 28153),
(142971, 'deDE', 'Bei dieser Hand! Ich schlag\' Euch die Zähne ein.', '', 28153),
(142970, 'deDE', 'Achtung!', '', 28153),
(142969, 'deDE', '', 'Im Namen des Hauses Kronsteig ernenne ich Euch zu Inquisitoren des Glutordens!', 28153),
(142968, 'deDE', '', 'Heute werdet Ihr zu unserer größten Hoffnung gegen den ewigen Feind.', 28153),
(142967, 'deDE', '', 'Heute werdet Ihr zur glänzenden Klinge, die das Böse richtet.', 28153),
(142966, 'deDE', '', 'Brüder und Schwestern, heute werdet Ihr zum lodernden Feuer, das die Dunkelheit verzehrt.', 28153),
(142965, 'deDE', '', 'Ah, hier.', 28153),
(142964, 'deDE', '', 'Da war ein Initiierungsspruch im Folianten. Lasst mich nachsehen...', 28153),
(142963, 'deDE', '', 'Danke, dass Ihr uns Eure Männer abtretet, Marschall. Langsam wird das ein richtiger Orden!', 28153),
(142962, 'deDE', 'Ich wart jetz\' schon seit Tagen drauf, den König zu seh\'n. Man würd ja denk\'n, dass es ihn mehr interessier\'n würd, was die Goblins hierzulande mach\'n.', '', 28153),
(142961, 'deDE', 'Wir haben hier viele fähige Soldaten, Herrin. Tüchtige Rekruten für Euren Glutorden.', '', 28153),
(142960, 'deDE', '', 'Marschall, wir haben vielleicht ein Mittel gegen den Zirkel gefunden. Wir brauchen kräftige Soldaten, die es einsetzen können.', 28153),
(142959, 'deDE', 'Ich würd nie \'nen Loa oder die Stadt verrat\'n!', '', 28153),
(142958, 'deDE', 'Ich verehre Pa\'ku. Blutmagie is\' verboten!', '', 28153),
(142957, 'deDE', 'Ich sag die Wahrheit. Ich weiß überhaupt nix über Blutrelikte!', '', 28153),
(142956, 'deDE', 'Ich bin echt unschuldig! Bitte, habt Gnade.', '', 28153),
(142955, 'deDE', 'Ich würd nie Blutrelikte schmugg\'ln. Blutmagie is\' böse!', '', 28153),
(142954, 'deDE', 'Ich hab noch nie irgendwelche Blutrelikte geseh\'n!', '', 28153),
(142953, 'deDE', 'Ich weiß nich\', wovon Ihr redet!', '', 28153),
(142952, 'deDE', 'Ich hab nix Falsches gemacht!', '', 28153),
(142951, 'deDE', 'Wollt Ihr, dass ich nochma\' zusteche...?', '', 28153),
(142950, 'deDE', 'Wem habt Ihr die Blutrelikte verkauft?', '', 28153),
(142949, 'deDE', 'Ihr ekelt mich an, Verräter.', '', 28153),
(142948, 'deDE', 'Ich werd Euch leid\'n lass\'n, Pro\'ditor. Wir statuier\'n \'n Exempel an Euch.', '', 28153),
(142947, 'deDE', 'Wenn Ihr gesteht, versprech ich, Euch schnell zu töt\'n.', '', 28153),
(142946, 'deDE', 'Ihr seid echt der schlimmste Abschaum, Pro\'ditor. Blutmagie tötet unser Volk!', '', 28153),
(142945, 'deDE', 'Wir wiss\'n, dass Ihr Blutrelikte in die Stadt geschmuggelt habt.', '', 28153),
(142944, 'deDE', 'Sagt uns, woher Ihr die Blutrelikte habt, Pro\'ditor!', '', 28153),
(142943, 'deDE', 'Dieser Abschaum hat Blutrelikte in unsre Stadt geschmuggelt.\n\nEr wird gesteh\'n und dann statuier\'n wir an ihm \'n Exempel.', '', 28153),
(142942, 'deDE', 'Ich hab nix Falsches getan! Sagt\'s ihnen!', '', 28153),
(142941, 'deDE', '(Gehen)', '(Gehen)', 28153),
(142940, 'deDE', '<Die blutigen und zerfetzten Überreste des geflohenen Sträflings Teshyambi sind kaum noch zu erkennen. Es sieht so aus, als wären die Raptoren in der Nähe dafür verantwortlich.>', '<Die blutigen und zerfetzten Überreste des geflohenen Sträflings Teshyambi sind kaum noch zu erkennen. Es sieht so aus, als wären die Raptoren in der Nähe dafür verantwortlich.>', 28153),
(142939, 'deDE', 'Ich weiß, wer Ihr seid, Mojoba. Geht weiter nach Vol\'dun und lebt dort in Frieden im Exil.', 'Ich weiß, wer Ihr seid, Mojoba. Geht weiter nach Vol\'dun und lebt dort in Frieden im Exil.', 28153),
(142938, 'deDE', 'Wer seid Ihr? Was wollt Ihr hier?', '', 28153),
(142937, 'deDE', 'Es tut mir leid, aber Ihr wurdet als Strafe für Eure Taten nach Vol\'dun verbannt.', 'Es tut mir leid, aber Ihr wurdet als Strafe für Eure Taten nach Vol\'dun verbannt.', 28153),
(142936, 'deDE', 'Pscht! Ich versteck mich hier vor den Raptor\'n un\' Zulajin. Ich muss es zurück nach Zuldazar schaff\'n.', '', 28153),
(142935, 'deDE', '', 'Gute Arbeit... für einen entflohenen Sträfling.', 28153),
(142934, 'deDE', '', 'Jetzt, wo das Gefängnis unter unserer Kontrolle ist und wir die Schlüssel haben, können wir das Azerit bergen und die Geiseln freilassen.', 28153),
(142933, 'deDE', '', 'Lady Aschenwind wird sich wohl doch einen neuen Wärter suchen müssen.', 28153),
(142932, 'deDE', 'Haltet Euch mit dem Feuer zurück! Und damit meine ich Euch, Flammenwirkerin. Wenn nur eine Azeritmunition explodiert, sind wir alle Geschichte!', '', 28153),
(142931, 'deDE', 'Bereit machen, Männer! Sie kommen!', '', 28153),
(142930, 'deDE', '', 'Wir können den Rest der unteren Stockwerke sichern. Geht Ihr schon mal vor zum Wärter.', 28153),
(142929, 'deDE', '', 'Gut gemacht. Sieht aus, als hättet Ihr alles unter Kontrolle.', 28153),
(142928, 'deDE', 'Wenn wir erst die Geiseln vom Wärter in den Klauen haben, schwimmen wir im Lösegeld!', '', 28153),
(142927, 'deDE', 'Los, Jungs! Tretet die Türen ein!', '', 28153),
(142926, 'deDE', '', 'Das hoffe ich für Euch. Sonst suche ich einen neuen Wärter, der Euch mitsamt diesem Abschaum ertränkt.', 28153),
(142925, 'deDE', 'Verzeiht mir, Lady Aschenwind. Meine Männer haben die Ordnung in Kürze wiederhergestellt.', '', 28153),
(142924, 'deDE', '', 'Korgus! Warum habt Ihr die unteren Stockwerke noch nicht überschwemmt und diese zankenden Ratten ertränkt!?', 28153),
(142923, 'deDE', '', 'Igitt! Wo seid Ihr denn durchgekrochen? Kommt mir lieber nicht zu nahe.', 28153),
(142922, 'deDE', '', 'Diese Kreatur war bestimmt der Grund, warum der Wärter auf dieser Seite der Insel nicht viele Patrouillen hat. Gute Arbeit.', 28153),
(142921, 'deDE', '', 'Wir kümmern uns um die Wachen, Ihr könnt schon vor zum Kanalgitter. Durch den Kanal solltet Ihr immer noch ins Gefängnis eindringen können.', 28153),
(142920, 'deDE', '', 'Laut unseren Informanten verwahrt der Wärter die Schlüssel zum Azeritlager und zum Geiseltrakt... um seinen Hals.', 28153),
(142919, 'deDE', '', 'Bleibt unauffällig! Noch haben sie uns nicht gesehen!', 28153),
(142918, 'deDE', 'Muss das sein?', '', 28153),
(142917, 'deDE', 'Was Ihr wollen?', '', 28153),
(142916, 'deDE', 'Bereit zur Arbeit.', '', 28153),
(142915, 'deDE', 'Unsere Kaserne wurde zerstört!', '', 28153),
(142914, 'deDE', 'Wir brauchen Verstärkung, wenn wir diesen Krieg gewinnen wollen.', '', 28153),
(142913, 'deDE', 'Zurück an Arbeit!', '', 28153),
(142912, 'deDE', 'Dieses Gebäude baut sich nicht von selbst!', '', 28153),
(142911, 'deDE', 'Schwingt den Hammer!', '', 28153),
(142910, 'deDE', '', 'Alleria spannt sich kampfbereit an.', 28153),
(142909, 'deDE', 'Ihr habt mir das Leben gerettet!', 'Ihr habt mir das Leben gerettet!', 28153),
(142908, 'deDE', 'Ich sollte mich jetzt in Sicherheit bringen können. Danke.', 'Ich sollte mich jetzt in Sicherheit bringen können. Danke.', 28153),
(142907, 'deDE', 'Ihre Angriffe waren unerbittlich. Danke für Eure Hilfe.', 'Ihre Angriffe waren unerbittlich. Danke für Eure Hilfe.', 28153),
(142906, 'deDE', 'Ich werde Euren Mut nicht vergessen.', 'Ich werde Euren Mut nicht vergessen.', 28153),
(142905, 'deDE', 'Ich dachte, ich sterbe hier draußen!', 'Ich dachte, ich sterbe hier draußen!', 28153),
(142904, 'deDE', 'Unser Dorf könnte mehr Helden wie Euch brauchen!', 'Unser Dorf könnte mehr Helden wie Euch brauchen!', 28153),
(142903, 'deDE', 'Rächt diejenigen, die nicht gerettet werden konnten.', 'Rächt diejenigen, die nicht gerettet werden konnten.', 28153),
(142902, 'deDE', 'Diese Naga sind Monster!', 'Diese Naga sind Monster!', 28153),
(142901, 'deDE', 'Damit treff ich Euch mitten ins Herz!', '', 28153),
(142900, 'deDE', 'Eindringlinge kommen durch die Kanalisation!', '', 28153),
(142898, 'deDE', 'Dieser Stein singt ein stilles und mächtiges Lied. Es gibt nur eine, die seine Melodie hört – hoffen wir, dass sie niemals den Weg zu diesen Gestaden findet.', '', 28153),
(142897, 'deDE', 'Ich habe gesehen, was ich sehen musste. Dieser Stein bringt großes Unheil. Wir müssen ihn zerstören.', '', 28153),
(142894, 'deDE', 'Ich bezweifle, dass sie die freiwillig rausrückt, also werdet Ihr sie ihren toten Händen entreißen müssen.', '', 28153),
(142893, 'deDE', 'Ich habe unser nächstes Ziel im Süden ausgemacht. Ihr beeilt Euch besser.', '', 28153),
(142892, 'deDE', 'Ah, nur schade, dass sich die Kul Tiraner dank Eurem Sieg neu formieren können werden.', '', 28153),
(142891, 'deDE', 'Die Dunkle Fürstin weiß Euren Dienst sicherlich zu schätzen.', '', 28153),
(142890, 'deDE', '', 'Es wird mir eine Ehre sein, Lordregent. Ich treffe Euch in Silbermond, Champion.', 28153),
(142889, 'deDE', 'Ausgezeichnet! Lady Liadrin, bitte kehrt nach Orgrimmar zurück und überbringt dem Kriegshäuptling die guten Nachrichten.', '', 28153),
(142888, 'deDE', '', 'Im Namen der Nachtgeborenen nehme ich Euer Angebot an. Von diesem Tage an wird Suramar für die Horde kämpfen.', 28153),
(142887, 'deDE', 'Die Horde bietet Euch das, Erste Arkanistin. Schließt Euch uns an. Die Tore Silbermonds stehen Euch offen.', '', 28153),
(142886, 'deDE', '', 'Suramar wird immer unsere Heimat sein. Doch einige aus meinem Volk möchten mehr Kontakt mit der Außenwelt. Sie wollen, dass wir erneut unseren Platz in Azeroth einnehmen. Dafür brauchen wir Verbündete.', 28153),
(142885, 'deDE', '', 'Wir schöpfen Kraft aus diesem Bündnis... aber wir haben nicht vergessen, wer wir sind.', 28153),
(142884, 'deDE', '', 'Ganz im Gegenteil. Dieser Konflikt hat bewiesen, mit welcher Hingabe Ihr für Euer Volk sorgt. Ich kann sehen, dass die Horde Euch erlaubt, Eure Traditionen aufrecht zu erhalten – das ist etwas, das uns sehr wichtig ist.', 28153),
(142883, 'deDE', 'Es tut mir leid, dass Ihr das mit ansehen musstet, Thalyssra. So sollte Euer Besuch nicht verlaufen.', '', 28153),
(142882, 'deDE', '', 'Wie Ihr befehlt, Lordregent. Fürs Erste.', 28153),
(142881, 'deDE', 'Genug! Verlasst uns auf der Stelle, Alleria. Unfall oder nicht, Eure Anwesenheit ist eine Gefahr für Quel\'Thalas. Kehrt zurück nach Sturmwind. Silbermond ist nicht mehr Eure Heimat.', '', 28153),
(142880, 'deDE', '', 'Ich lasse mich in meinem Heimatland nicht zu einer Gefangenen machen.', 28153),
(142879, 'deDE', 'Wachen! Nehmt diesen Saboteur fest!', '', 28153),
(142878, 'deDE', 'Der Sonnenbrunnen ist sicher. Wir danken Euch für Eure Hilfe, Thalyssra. Und Euch ebenfalls, Champion.', '', 28153),
(142877, 'deDE', 'Ihr zögert das Unausweichliche nur heraus. Ich werde haben, wonach ich suche.', '', 28153),
(142876, 'deDE', '', 'Jetzt! Vereint Eure Kräfte mit mir!', 28153),
(142875, 'deDE', 'Das Tor öffnet sich. Ja... das sollte unseren Zwecken genügen.', '', 28153),
(142874, 'deDE', '', 'Sagt uns, was wir tun müssen, und wir werden Euch mit aller Macht unterstützen.', 28153),
(142873, 'deDE', '', 'Ich kann den Spalt schließen, aber ich brauche Hilfe dabei.', 28153),
(142872, 'deDE', 'Etwas versucht, einen Riss in die Kammer zu öffnen. Wenn es durchkommt, verlieren wir den Sonnenbrunnen.', '', 28153),
(142871, 'deDE', 'Beginnt den Zauber zu wirken, Rikal.', 'Beginnt den Zauber zu wirken, Rikal.', 28153),
(142870, 'deDE', 'Früher oder später ändern sich die Gezeiten. Das tun sie immer.', '', 28153),
(142869, 'deDE', 'Euer Griff versagt!', '', 28153),
(142868, 'deDE', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s bereitet sich darauf vor, |cFFFF0000|Hspell:257785|h[Blitzende Dolche]|h|r zu werfen! Versteckt Euch!', '', 28153),
(142867, 'deDE', 'Bal\'a dash, malanore.', '', 28153),
(142866, 'deDE', 'Jeder von uns muss seinen eigenen Weg finden.', '', 28153),
(142865, 'deDE', 'Unser Volk ist das Antlitz einer neuen Zukunft.', '', 28153),
(142864, 'deDE', 'Seht keine Wahrheit als selbstverständlich.', '', 28153),
(142863, 'deDE', 'Der Kosmos ist voller Mysterien.', '', 28153),
(142862, 'deDE', 'Neue Möglichkeiten liegen vor uns.', '', 28153),
(142861, 'deDE', 'Die Vergangenheit ist geschrieben. Die Zukunft nicht.', '', 28153),
(142860, 'deDE', 'Shorel\'aran.', '', 28153),
(142859, 'deDE', 'Unser Volk fürchtet die Schatten nicht.', '', 28153),
(142858, 'deDE', 'Es gibt keinen einzig richtigen Weg.', '', 28153),
(142857, 'deDE', 'Die Stimmen haben keine Macht über uns.', '', 28153),
(142856, 'deDE', 'Jeder Impuls muss beherrscht werden.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142855, 'deDE', 'Fürchtet die Macht nicht. Kontrolliert sie.', '', 28153),
(142854, 'deDE', 'Zieht alle Möglichkeiten in Betracht.', '', 28153),
(142853, 'deDE', 'Euer infantiles Verhalten bringt mich nicht aus der Fassung.', '', 28153),
(142852, 'deDE', '\"Für den Sonnenbrunnen\"? Ach kommt, das habe ich längst abgehakt.', '', 28153),
(142851, 'deDE', 'Würde sich urplötzlich zu Euren Füßen ein Portal ins endlose Nichts öffnen und Euch in meiner unmittelbaren Gegenwart verschlingen – seid versichert, es gäbe keinerlei Zusammenhang. Unfälle geschehen schließlich.', '', 28153),
(142850, 'deDE', 'Oh natürlich, kaum wird die physische Gestalt von einer kosmischen Macht transformiert, die bekanntlich Wahnsinn hervorruft, und schon ist man \"verdächtig\". Ich rieche Vorurteile...', '', 28153),
(142849, 'deDE', 'Wonach sucht Ihr?', '', 28153),
(142848, 'deDE', 'Ich biete seltene Waren aus fernen Landen.', '', 28153),
(142847, 'deDE', 'Alles hat seinen Preis... wenn Ihr gewillt sein, ihn zu zahlen.', '', 28153),
(142846, 'deDE', 'Ich hoffe, die Einkäufe entsprechen Euren Erwartungen.', '', 28153),
(142845, 'deDE', 'Danke für Euren Besuch.', '', 28153),
(142844, 'deDE', 'Kommt jederzeit wieder.', '', 28153),
(142843, 'deDE', '', 'Kommt jederzeit wieder.', 28153),
(142842, 'deDE', '', 'Danke für Euren Besuch.', 28153),
