(142422, 'deDE', '', 'Ash\'thoras denil.', 28153),
(142421, 'deDE', '', 'Geht im Licht der Sterne.', 28153),
(142420, 'deDE', '', 'Die Sterne leiten Euch.', 28153),
(142419, 'deDE', '', 'Unsere Ära ist gekommen.', 28153),
