(142416, 'deDE', '', 'Lebt wohl.', 28153),
(142407, 'deDE', 'Die Loa? Die sin\' uralte, mächtige Geschöpfe, Prinzessin. Woher wollt Ihr wissen, ob die überhaupt hier sin\'?', '', 28153),
(142404, 'deDE', 'Ich hatte Euch davor gewarnt, in der Nähe der Urne zu sterb\'n.', '', 28153),
(142403, 'deDE', 'Wir bleib\'n hier un\' wart\'n drauf, dass Prinzessin Talanji zurückkommt. Ich werd mein\' Posten nich\' verlass\'n. Un\' Ihr solltet das auch nich\' tun.', 'Wir bleib\'n hier un\' wart\'n drauf, dass Prinzessin Talanji zurückkommt. Ich werd mein\' Posten nich\' verlass\'n. Un\' Ihr solltet das auch nich\' tun.', 28153),
(142402, 'deDE', 'Ich sag, wir sollt\'n hier abhau\'n un\' uns der Flotte anschließ\'n. Wir sin\' hier draußen doch nur Kanon\'nfutter für die Bluttrolle!', 'Ich sag, wir sollt\'n hier abhau\'n un\' uns der Flotte anschließ\'n. Wir sin\' hier draußen doch nur Kanon\'nfutter für die Bluttrolle!', 28153),
(142401, 'deDE', 'Un\'? Sie is\' mit den andern Irren unterwegs nach Nazmir. Prinzessin Talanji kommt nich\' zurück!', 'Un\'? Sie is\' mit den andern Irren unterwegs nach Nazmir. Prinzessin Talanji kommt nich\' zurück!', 28153),
(142400, 'deDE', 'Seid Ihr irre? Wir könn\' unsere Posten nich\' verlassen. Wir ham grad die Prinzessin geseh\'n!', 'Seid Ihr irre? Wir könn\' unsere Posten nich\' verlassen. Wir ham grad die Prinzessin geseh\'n!', 28153),
