(142110, 'deDE', 'Kommt bald wieder.', '', 28153),
(142109, 'deDE', 'Wie immer ein Vergnügen.', '', 28153),
(142108, 'deDE', 'Auf bald.', '', 28153),
(142107, 'deDE', 'Wir bekommen täglich neue Waren.', '', 28153),
(142106, 'deDE', '', 'Der Hochberg wird nicht fallen!', 28153),
(142105, 'deDE', '', 'Grüße.', 28153),
(142104, 'deDE', '', 'Der Fluss nährt uns.', 28153),
(142103, 'deDE', '', 'Was trägt der Wind da zu uns?', 28153),
(142102, 'deDE', '', 'Wir fürchten die Finsternis nicht.', 28153),
(142101, 'deDE', '', 'Wahrt Frieden und Geduld.', 28153),
(142100, 'deDE', '', 'Wir verteidigen diese Welt gemeinsam.', 28153),
(142099, 'deDE', '', 'Hütet Euch vor den Tiefen dieser Erde.', 28153),
(142098, 'deDE', '', 'Gemeinsam stehen wir für den Hochberg.', 28153),
(142097, 'deDE', '', 'Möge An\'she Euch leiten.', 28153),
(142096, 'deDE', '', 'Mögen Eure Flüsse immer üppig sein.', 28153),
(142095, 'deDE', '', 'Reitet die Winde.', 28153),
(142094, 'deDE', '', 'Mögen Sonne und Mond Euren Pfad erleuchten.', 28153),
(142093, 'deDE', '', 'Denkt immer an die Lehren der Erdenmutter.', 28153),
(142092, 'deDE', '', 'Nervensägen wie Euch nehme ich aufs Gehörn.', 28153),
(142091, 'deDE', '', 'Ein wütender Hochberg kommt vor dem Fall.', 28153),
(142090, 'deDE', '', 'Macht so weiter und Ihr fangt Euch einen donnernden Huftritt ein.', 28153),
(142089, 'deDE', '', 'Sucht Euch ein Plätzchen in den Tiefen der Erde und verkriecht Euch.', 28153),
(142088, 'deDE', '', 'Seid Ihr hier, um zu handeln?', 28153),
(142087, 'deDE', '', 'Ich habe genau das Richtige für Euch.', 28153),
(142086, 'deDE', '', 'Seht Euch ruhig um.', 28153),
(142085, 'deDE', '', 'Ich habe die besten Hochbergwaren.', 28153),
(142084, 'deDE', '', 'Kommt bald wieder.', 28153),
(142083, 'deDE', '', 'Wie immer ein Vergnügen.', 28153),
(142082, 'deDE', '', 'Die Andre Seite steht uns off\'n. Danke, Mann. Danke...', 28153),
(142081, 'deDE', '', 'Entfesselt den Dämon in Euch, um für kurze Zeit schreckliche Macht zu erlangen, die Ihr gegen Eure Feinde einsetzt.', 28153),
(142080, 'deDE', '', 'Setzt \'Metamorphose\' ein, während Ihr die Zielattrappe angreift.', 28153),
(142079, 'deDE', '', 'Auf bald.', 28153),
(142078, 'deDE', '', 'Wir bekommen täglich neue Waren.', 28153),
(142077, 'deDE', 'Setzt \'Metamorphose\' ein, während Ihr die Zielattrappe angreift.', '', 28153),
(142076, 'deDE', 'Entfesselt den Dämon in Euch, um für kurze Zeit schreckliche Macht zu erlangen, die Ihr gegen Eure Feinde einsetzt.', '', 28153),
(142075, 'deDE', 'Wir bekommen täglich neue Waren.', '', 28153),
(142074, 'deDE', 'Auf bald.', '', 28153),
(142073, 'deDE', 'Wie immer ein Vergnügen.', '', 28153),
(142072, 'deDE', 'Kommt bald wieder.', '', 28153),
(142071, 'deDE', 'Ich habe die besten Hochbergwaren.', '', 28153),
(142070, 'deDE', 'Seht Euch ruhig um.', '', 28153),
(142069, 'deDE', 'Ich habe genau das Richtige für Euch.', '', 28153),
(142068, 'deDE', 'Seid Ihr hier, um zu handeln?', '', 28153),
(142067, 'deDE', 'Sucht Euch ein Plätzchen in den Tiefen der Erde und verkriecht Euch.', '', 28153),
(142066, 'deDE', 'Macht so weiter und Ihr fangt Euch einen donnernden Huftritt ein.', '', 28153),
(142065, 'deDE', 'Ein wütender Hochberg kommt vor dem Fall.', '', 28153),
(142064, 'deDE', 'Nervensägen wie Euch nehme ich aufs Gehörn.', '', 28153),
(142063, 'deDE', 'Denkt immer an die Lehren der Erdenmutter.', '', 28153),
(142062, 'deDE', 'Mögen Sonne und Mond Euren Pfad erleuchten.', '', 28153),
(142061, 'deDE', 'Reitet die Winde.', '', 28153),
(142060, 'deDE', 'Mögen Eure Flüsse immer üppig sein.', '', 28153),
(142059, 'deDE', 'Möge An\'she Euch leiten.', '', 28153),
(142058, 'deDE', 'Gemeinsam stehen wir für den Hochberg.', '', 28153),
(142057, 'deDE', 'Hütet Euch vor den Tiefen dieser Erde.', '', 28153),
(142056, 'deDE', 'Wir verteidigen diese Welt gemeinsam.', '', 28153),
(142055, 'deDE', 'Wahrt Frieden und Geduld.', '', 28153),
(142054, 'deDE', 'Wir fürchten die Finsternis nicht.', '', 28153),
(142053, 'deDE', '', 'Setzt \'Chaosstoß\' gegen die Zielattrappe ein.', 28153),
(142052, 'deDE', '', 'Mit \'Chaosstoß\' kanalisiert Ihr Euren Jähzorn in Eure Klingen zu einem brutalen Angriff.', 28153),
(142051, 'deDE', 'Versucht Euer Möglichstes, $p. Ich werde meinem Bruder die letzte Ehre erweisen.', '', 28153),
(142050, 'deDE', 'Setzt \'Chaosstoß\' gegen die Zielattrappe ein.', '', 28153),
(142049, 'deDE', 'Mit \'Chaosstoß\' kanalisiert Ihr Euren Jähzorn in Eure Klingen zu einem brutalen Angriff.', '', 28153),
(142048, 'deDE', '', 'Ihr seid in Reichweite. Rückt dem Gegner mit gewaltigen Schlägen zu Leibe.', 28153),
(142042, 'deDE', '', 'Setzt \'Dämonenbiss\' gegen die Zielattrappe ein.', 28153),
(142041, 'deDE', '', '\'Dämonenbiss\' ist ein mächtiger Angriff, der Jähzorn erzeugt.', 28153),
(142040, 'deDE', 'Setzt \'Dämonenbiss\' gegen die Zielattrappe ein.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142039, 'deDE', '\'Dämonenbiss\' ist ein mächtiger Angriff, der Jähzorn erzeugt.', '', 28153),
(142038, 'deDE', 'Ihr seid in Reichweite. Rückt dem Gegner mit gewaltigen Schlägen zu Leibe.', '', 28153),
(142036, 'deDE', '', 'Setzt \'Teufelsrausch\' ein, um auf die Zielattrappe loszustürmen.', 28153),
(142035, 'deDE', 'Was trägt der Wind da zu uns?', '', 28153),
(142034, 'deDE', 'Der Fluss nährt uns.', '', 28153),
(142033, 'deDE', 'Grüße.', '', 28153),
(142032, 'deDE', '', 'Dank Eurer Mobilität bestimmt Ihr, wann und wo Ihr Feinde bekämpft.', 28153),
(142031, 'deDE', '', 'Verwüstungsdämonenjäger haben viel geopfert, um die Macht der Dämonen zu beherrschen.', 28153),
(142030, 'deDE', '', 'Verwüstungsdämonenjäger haben viel geopfert, um die Macht der Dämonen zu beherrschen.', 28153),
(142029, 'deDE', 'Der Hochberg wird nicht fallen!', '', 28153),
(142028, 'deDE', 'Verwüstungsdämonenjäger haben viel geopfert, um die Macht der Dämonen zu beherrschen.', '', 28153),
(142027, 'deDE', 'Setzt \'Teufelsrausch\' ein, um auf die Zielattrappe loszustürmen.', '', 28153),
(142026, 'deDE', 'Dank Eurer Mobilität bestimmt Ihr, wann und wo Ihr Feinde bekämpft.', '', 28153),
(142025, 'deDE', 'Verwüstungsdämonenjäger haben viel geopfert, um die Macht der Dämonen zu beherrschen.', '', 28153),
(142022, 'deDE', 'Das klingt ja, als habt Ihr schon \'nen Plan, Prinzessin.', '', 28153),
(142021, 'deDE', '', 'Ich glaub, dieser G\'huun gibt ihn\' Macht... mehr als wir bewältig\'n könn\'. Wir brauch\'n \'ne neue Strategie.', 28153),
(142020, 'deDE', 'Die ham WAS?! Ihr habt gesagt, das is\' nur \'n Häufchen Sumpfbewohner!', '', 28153),
(142019, 'deDE', 'Hört her! Hört her! Lord Sturmsang hat seine Botschaft an die Getreuen überbracht!', 'Hört her! Hört her! Lord Sturmsang hat seine Botschaft an die Getreuen überbracht!', 28153),
(142018, 'deDE', 'Vorarbeiter Zettel hat den Verstand verloren. Sie alle!', 'Vorarbeiter Zettel hat den Verstand verloren. Sie alle!', 28153),
(142017, 'deDE', 'Ich war kurz davor zusammenzubrechen!', 'Ich war kurz davor zusammenzubrechen!', 28153),
(142016, 'deDE', 'Sie lassen uns nicht gehen!', 'Sie lassen uns nicht gehen!', 28153),
(142015, 'deDE', 'Mögen die Gezeiten Euch segnen.', 'Mögen die Gezeiten Euch segnen.', 28153),
(142014, 'deDE', 'Tausend Dank, Fremdling!', 'Tausend Dank, Fremdling!', 28153),
(142013, 'deDE', 'Die Ernter haben sich gegen uns gewandt!', 'Die Ernter haben sich gegen uns gewandt!', 28153),
(142012, 'deDE', 'Die Gezeiten bewahren mich!', 'Die Gezeiten bewahren mich!', 28153),
(142011, 'deDE', 'Ich wusste, dass die See uns nicht verlassen hat!', 'Ich wusste, dass die See uns nicht verlassen hat!', 28153),
(142007, 'deDE', 'Ihr kriegt noch... was Ihr verdient...', 'Ihr kriegt noch... was Ihr verdient...', 28153),
(142006, 'deDE', 'Das is... Befehls...verweigerung...', 'Das is... Befehls...verweigerung...', 28153),
(142004, 'deDE', 'Weg... treten...', 'Weg... treten...', 28153),
(142003, 'deDE', 'Meine Tierchen hungern.', '', 28153),
(142002, 'deDE', 'Wellen, dient meinem Willen!', '', 28153),
(142001, 'deDE', 'Übergebt... meinen Leichnam... der See...', '', 28153),
(142000, 'deDE', 'Früher... gab\'s noch... echte Arbeiter...', 'Früher... gab\'s noch... echte Arbeiter...', 28153),
(141999, 'deDE', 'Dafür gibt\'s eine schriftliche Verwarnung!', 'Dafür gibt\'s eine schriftliche Verwarnung!', 28153),
(141998, 'deDE', 'Aaaaaah... verflucht...', 'Aaaaaah... verflucht...', 28153),
(141997, 'deDE', 'Nichts entkommt der Tiefe.', '', 28153),
(141996, 'deDE', 'Mehr... habt Ihr... nicht drauf?', 'Mehr... habt Ihr... nicht drauf?', 28153),
(141995, 'deDE', 'Wertlose... Made...', 'Wertlose... Made...', 28153),
(141994, 'deDE', 'Hab ich \"aufhören\" gesagt?!', 'Hab ich \"aufhören\" gesagt?!', 28153),
(141993, 'deDE', 'In die Tiefe mit Euch!', '', 28153),
(141992, 'deDE', 'An Euch statuiere ich ein Exempel!', 'An Euch statuiere ich ein Exempel!', 28153),
(141991, 'deDE', 'Die Pause ist vorbei, Made!', 'Die Pause ist vorbei, Made!', 28153),
(141990, 'deDE', 'Mich hintergeht Ihr nur einmal!', 'Mich hintergeht Ihr nur einmal!', 28153),
(141989, 'deDE', 'Hier wird nicht aus der Reihe getanzt!', 'Hier wird nicht aus der Reihe getanzt!', 28153),
(141988, 'deDE', 'Euch lass ich bluten, aufmüpfige Made!', 'Euch lass ich bluten, aufmüpfige Made!', 28153),
(141987, 'deDE', 'Raub der Wellen...', '', 28153),
(141986, 'deDE', 'In die Reihe!', 'In die Reihe!', 28153),
(141985, 'deDE', 'Zurück an die Arbeit, Wurm!', 'Zurück an die Arbeit, Wurm!', 28153),
(141984, 'deDE', 'Energiepegel im roten Bereich.', '', 28153),
(141983, 'deDE', 'Systemneustart erforderlich.', '', 28153),
(141982, 'deDE', 'Die Tiefe wird Euer Grab sein!', '', 28153),
(141981, 'deDE', 'Fremdeinheit in Luke A registriert.', '', 28153),
(141980, 'deDE', 'Einheit deaktiviert.', '', 28153),
(141979, 'deDE', 'Ernteprotokoll fehlgeschlagen.', '', 28153),
(141978, 'deDE', 'Die Fluten werden Euch verschlingen!', '', 28153),
(141977, 'deDE', 'Strukturelle Integrität: 0%%.', '', 28153),
(141976, 'deDE', 'Registriere Leck.', '', 28153),
(141975, 'deDE', 'System deaktiviert.', '', 28153),
(141974, 'deDE', 'Feindeinheit erfasst.', '', 28153),
(141973, 'deDE', 'Aktiviere Gegenmaßnahmen.', '', 28153),
(141972, 'deDE', 'Initialisiere Ernteservos.', '', 28153),
(141971, 'deDE', 'Eindringlingsalarm!', '', 28153),
(141970, 'deDE', 'Zugang verweigert.', '', 28153),
(141969, 'deDE', 'Angriffssequenz initiiert.', '', 28153),
(141968, 'deDE', 'Angriff eingeleitet.', '', 28153),
(141967, 'deDE', 'Bedrohung entdeckt.', '', 28153),
(141966, 'deDE', 'Artillerie! Pustet diesen Abschaum von meinem Schlachtfeld!', '', 28153),
(141965, 'deDE', 'Kanonen! Feuert auf meine Position!', '', 28153),
(141964, 'deDE', 'Niemand widersteht der Flut!', '', 28153),
(141963, 'deDE', 'Seht Eurem Tod ins Auge!', '', 28153),
(141962, 'deDE', 'Sagt der Welt Lebwohl!', '', 28153),
(141961, 'deDE', 'Kostet Stahl!', '', 28153),
(141960, 'deDE', 'Wie zu erwarten von Hordeabschaum.', '', 28153),
(141959, 'deDE', 'Undiszipliniert!', '', 28153),
(141958, 'deDE', 'Die See wird Euren Leichnam mit sich reißen!', '', 28153),
(141957, 'deDE', 'Ihr... verdient nicht... den Sieg...', '', 28153),
(141956, 'deDE', 'Euer Ende naht, Hordeabschaum!', '', 28153),
(141955, 'deDE', 'Für Boralus!', '', 28153),
(141954, 'deDE', 'Der Feind hat uns umzingelt!', '', 28153),
(141953, 'deDE', 'Achtung!', '', 28153),
(141952, 'deDE', 'Hier drüben!', '', 28153),
(141951, 'deDE', 'Hier entlang!', '', 28153),
(141950, 'deDE', '', 'Tragt diese Gewänder mit Stolz, $p. Die Armee des Lichts wird sich für alle Zeit geehrt fühlen, Euch in ihren Rängen zu wissen.', 28153),
(141949, 'deDE', '', 'Auf all Euren Reisen wart Ihr ein Licht in der Dunkelheit. Ihr habt der Allianz gezeigt, was lichtgeschmiedet zu sein wahrhaft bedeutet.', 28153),
(141948, 'deDE', '', 'Kommt, trefft mich auf der Vindikaar. Es wird Zeit, dass wir Euer Pflichtbewusstsein belohnen.', 28153),
(141947, 'deDE', '', 'Eure Dienste für die Allianz waren höchst beeindruckend, $p. Ich selbst hätte nicht mehr erreichen können. Nun ja, vielleicht ein wenig.', 28153),
(141946, 'deDE', 'Feuer frei!', '', 28153),
(141945, 'deDE', 'Brennt!', '', 28153),
(141944, 'deDE', '', 'Es ist mir Ehre und Privileg, Euch die Rüstung unseres Volkes zu überreichen. Sie wird Euch an Eure Wurzeln erinnern, wohin auch immer Euch Eure Reisen führen mögen.', 28153),
(141943, 'deDE', '', 'In den finstersten Stunden hieltet Ihr stand – stark, tapfer, unbeugsam. Dank Euch, $p, sieht die Horde, was es bedeutet, ein Hochbergtauren zu sein.', 28153),
(141942, 'deDE', 'Hiergeblieben!', '', 28153),
(141941, 'deDE', '', 'Nun ruft Donnertotem Euch heim. Was bleibt ist unser Dank für all die Dienste, die Ihr uns erwiesen habt.', 28153),
(141940, 'deDE', '', 'Eure Reise durch Azeroth war lang, $p. Und auf Eurem Pfad habt Ihr dem Hochberg Ehre gebracht.', 28153),
(141939, 'deDE', 'Kommt her!', '', 28153),
(141938, 'deDE', 'Ihr seid als Nächstes dran!', '', 28153),
(141937, 'deDE', 'Ihr entkommt mir nicht!', '', 28153),
(141936, 'deDE', 'Ich werde mich an Eurem Blut laben!', '', 28153),
(141935, 'deDE', 'Argusfilter für S.E.L.F.I.E.-Kamera erhalten!', 'Argusfilter für S.E.L.F.I.E.-Kamera erhalten!', 28153),
(141934, 'deDE', 'Frostgramfilter für S.E.L.F.I.E.-Kamera erhalten!', 'Frostgramfilter für S.E.L.F.I.E.-Kamera erhalten!', 28153),
(141933, 'deDE', 'Shafilter für S.E.L.F.I.E.-Kamera erhalten!', 'Shafilter für S.E.L.F.I.E.-Kamera erhalten!', 28153),
(141932, 'deDE', 'Feuerlandefilter für S.E.L.F.I.E.-Kamera erhalten!', 'Feuerlandefilter für S.E.L.F.I.E.-Kamera erhalten!', 28153),
(141931, 'deDE', 'Zwielichtfilter für S.E.L.F.I.E.-Kamera erhalten!', 'Zwielichtfilter für S.E.L.F.I.E.-Kamera erhalten!', 28153),
(141930, 'deDE', 'Der Schlächter wird zum Geschlachteten...', '', 28153),
(141929, 'deDE', 'Saftige Häppchen.', '', 28153),
(141928, 'deDE', 'Ihr seid Fischfutter!', '', 28153),
(141926, 'deDE', 'Das nenn\' ich Schlachtfest!', '', 28153),
(141925, 'deDE', 'Ich mach Hackfleisch aus Euch.', '', 28153),
(141924, 'deDE', '<Der Fischer starrt wie besessen auf das Wasser und murmelt etwas vor sich hin. Seine Lippen sind aufgesprungen, seine Hände bluten und sein ganzer Körper ist mit Schnitten und Kratzspuren überzogen, vermutlich von den gefräßigen Vögeln an der Küste.\n\nEr scheint sich seit Tagen nicht von der Stelle gerührt zu haben. \n\nEr steht ganz offensichtlich unter dem Einfluss des Zirkels, aber im Gegensatz zu allen anderen, die Ihr gesehen habt, kann er sich bewegen und sprechen. Allerdings reagiert er nicht auf Euch, als Ihr Euch ihm nähert.>', '', 28153),
(141923, 'deDE', 'Lämmer zur Schlachtbank.', '', 28153),
(141922, 'deDE', '', 'Bleibt Eurer Heimat treu. Und solltet Ihr sie je vermissen, dann denkt daran, dass der Hochberg für Euch da ist – und es immer sein wird.', 28153),
(141921, 'deDE', '', 'Reist nach Orgrimmar. Trefft unsere neuen Verbündeten und findet heraus, was ihnen teuer ist... wofür sie kämpfen.', 28153),
(141920, 'deDE', '', 'Heute tretet Ihr eine neue Reise an, $p. Ihr werdet unsere Stimme sein in den Landen jenseits der Berge.', 28153),
(141919, 'deDE', '', 'Es ist an der Zeit, das zu ändern.', 28153),
(141918, 'deDE', '', 'Jahrhundertelang nannte unser Volk die Verheerten Inseln sein Zuhause. Wir wissen wenig über das Azeroth jenseits unserer Küsten.', 28153),
(141917, 'deDE', 'Ich habe gehört, dass Spione unterwegs sind! Was soll ich machen?', 'Ich habe gehört, dass Spione unterwegs sind! Was soll ich machen?', 28153),
(141916, 'deDE', '', 'Und wandelt stets im Licht, $p.', 28153),
(141915, 'deDE', '', 'Euer Dienst beginnt in Sturmwind. Erkundet die Welt von Azeroth. Macht Euch mit den Einwohnern und Orten vertraut, die wir zu verteidigen geschworen haben.', 28153),
(141914, 'deDE', '', 'Aber wir dürfen uns nicht von Trägheit schwächen lassen. Ein Krieg endet, ein anderer beginnt. Das ist das Leben eines Soldaten.', 28153),
(141913, 'deDE', '', 'Nach so langer Zeit wandeln wir zum ersten Mal unter einem Himmel, unbesudelt vom Wahn der Legion... und fühlen die Erde unter unseren Hufen.', 28153),
(141912, 'deDE', '', 'Über Jahrtausende bekämpften die Lichtgeschmiedeten die Dämonen im Wirbelnden Nether. Die Xenedar war das einzige Zuhause, das wir kannten.', 28153),
(141911, 'deDE', 'Ah, das trifft sich hervorragend, Champion. Ihr könnt aus erster Hand erleben, was es für einen Soldaten bedeutet, lichtgeschmiedet zu werden. Fahrt fort, Fareeya.', '', 28153),
(141910, 'deDE', '', 'Ihr wisst, wie gern ich Euren Reden lausche, aber hat das noch Zeit? Wir waren gerade dabei, diese Initianden in ihre Prüfung zu schicken.', 28153),
(141909, 'deDE', 'In der Tat. Er ist hocherfreut, die Armee des Lichts im Kampf an der Seite der Allianz zu wissen. Versammelt unsere Truppen, Hauptmann Fareeya. Ich werde es verkünden.', '', 28153),
(141908, 'deDE', '', 'So früh habe ich Euch nicht zurückerwartet, Hochexarch. Ich nehme an, Euer Treffen mit dem König ist gut verlaufen?', 28153),
(141905, 'deDE', 'Anderson! Bei den Tiefen...', '', 28153),
(141902, 'deDE', 'Zurück in die Leere, aus der Ihr gekrochen seid!', '', 28153),
(141901, 'deDE', 'Donnerfels wird frei von Euch sein!', '', 28153),
(141900, 'deDE', 'Hahahaha! Es fühlt sich gut an, wieder meinen Kolben zu schwingen!', '', 28153),
(141899, 'deDE', 'Ich werde Eure Schatten aus Mulgore verbannen!', '', 28153),
(141898, 'deDE', 'Für die Allianz!', '', 28153),
(141897, 'deDE', 'Für die Allianz!', '', 28153),
(141896, 'deDE', 'Manchmal frage ich mich, ob er Recht hat.', '', 28153),
(141895, 'deDE', 'Beides Eigenschaften, die noch bitter nötig sein werden. Danke, dass Ihr geholfen habt, sie unserer Sache zuzuführen, $p.', '', 28153),
(141894, 'deDE', 'Ich habe eintausend Jahre lang im Wirbelnden Nether an der Seite dieser Draenei gekämpft. Ihr werdet niemals geschicktere oder treuere Soldaten finden.', '', 28153),
(141893, 'deDE', 'Die Stärke der Lichtgeschmiedeten ist mehr als Willkommen in unseren Reihen, Hochexarch.', '', 28153),
(141892, 'deDE', 'Hochkönig Wrynn. Die Armee des Lichts schwört der Allianz die Treue.', '', 28153),
(141891, 'deDE', 'Lord Sturmsang untersagt solche Rituale nun. Er konzentriert sich auf den Bau neuer Schiffe.', '', 28153),
(141890, 'deDE', 'Wenn ich die Weiten des Meeres ergründe, verschleiert ein dunkler Sturm meinen Blick.', '', 28153),
(141889, 'deDE', '', 'Wisst Ihr, wo die Flotte ist?', 28153),
(141888, 'deDE', 'Haus Sturmsang hat sich verändert, nachdem die Flotte nicht zurückkehrte.', '', 28153),
(141887, 'deDE', 'Einen meiner Brüder... und Antworten, hoffe ich.', '', 28153),
(141886, 'deDE', '', 'Und was werden wir dort finden?', 28153),
(141885, 'deDE', 'Die Seemannsrinne ist nicht weit von hier. Kommt.', '', 28153),
(141884, 'deDE', 'Und bleib tot!', '', 28153),
(141883, 'deDE', '', 'Niemand von Euch wird aus Nazmir zurückkehr\'n. Unser armer König! Seine Tochter in diesem sinnlos\'n Kreuzzug zu verlier\'n...', 28153),
(141882, 'deDE', 'Ich mach mich auf nach Nazmir, $n. Vorsicht, außer Bluttrollen un\' dunklem Voodoo gibt\'s da nich\' mehr viel.', '', 28153),
(141881, 'deDE', '', 'Ich lass meine Tiere doch nich\' zu Bluttrollfutter werd\'n. Aus Nazmir kehrt KEINER zurück, Mann.', 28153),
(141880, 'deDE', 'Bevor Ihr aufbrecht, möchte ich Euch noch etwas über die nächsten drei Schreine erzählen.', '', 28153),
(141879, 'deDE', 'Das Land heißt Zandalar. Ihr müsst vielleicht ein Boot mieten. Es ist mehr oder weniger auf der anderen Seite der Welt.', '', 28153),
(141878, 'deDE', 'Ich glaube, ich habe noch ein paar ausfindig gemacht. Allerdings auf gefährlichem Gebiet.', '', 28153),
(141877, 'deDE', 'Als Ihr unterwegs wart, habe ich in dem Tagebuch weiter nach Orten von Schreinen gesucht.', '', 28153),
(141876, 'deDE', '', 'Mit Freuden, Hochexarch.', 28153),
(141875, 'deDE', 'Champion, es ist Zeit für uns, nach Sturmwind zurückzukehren. Fareeya, lasst alle wissen: Die Lichtgeschmiedeten kämpfen jetzt unter dem Banner der Allianz.', '', 28153),
(141874, 'deDE', 'T\'paartos ist etwas... unkonventionell. Doch er wird unserer Sache redlich dienen.', '', 28153),
(141873, 'deDE', 'T\'paartos!', '', 28153),
(141872, 'deDE', '', 'Pheta thones gamera. Das Licht leite uns!', 28153),
(141871, 'deDE', 'Von diesem Tag an seid Ihr lichtgeschmiedet.', '', 28153),
(141870, 'deDE', 'T\'paartos bittet um Verzeihung.', '', 28153),
(141869, 'deDE', 'schnüffelt an Wees\'kis Atem. Puh!', '', 28153),
(141868, 'deDE', 'Wir hatt\'n so ziemlich die beste Nacht unsres Lebens. Schade, dass ich mich an nichts mehr davon erinn\'re.\n\nAber immerhin hab\'n wir Dinoeier fürs Frühstück!', '', 28153),
(141867, 'deDE', 'Meine Schattenjäger und ich späh\'n die Gegend aus. Ich lass\' die Prinzessin in Eurer Obhut, $n.', '', 28153),
(141866, 'deDE', 'Könnt Ihr Euch erinnern, was letzte Nacht war?\n\nIch auch nich\'.', '', 28153),
(141865, 'deDE', 'Prinzessin, die Horde schickt uns bald Verstärkung. Wir sollt\'n hier ma\' nix überstürz\'n.', '', 28153),
(141864, 'deDE', 'Uff... ich muss echt ma\' anfang\'n... etwas gesünder zu leb\'n...', '', 28153),
(141863, 'deDE', 'Geht Ihr weiter. Ich werd schon wieder, ich brauch... ARG! Ich... ich brauch nur Zeit.', '', 28153),
(141862, 'deDE', 'Dafür is\' keine Zeit!\n\nDie Horde wird uns bald Verstärkung schick\'n und wir brauch\'n \'nen Hafen, wo die ankommen kann.', '', 28153),
(141861, 'deDE', '', 'Dieses Mal sind es zu viele! Feuer!', 28153),
(141860, 'deDE', 'Wenn ich das nur wüsste.', '', 28153),
(141859, 'deDE', '', 'Was geht hier vor, Bruder?', 28153),
(141858, 'deDE', '', 'Versammlung auflösen, Bürger, sofort!', 28153),
(141857, 'deDE', 'Ihr werdet den Schatz meines Meisters niemals finden! Macht Euch für Eure Auslöschung bereit, Eindringling!', '', 28153),
(141856, 'deDE', 'WER WAGT ES, DIE KAMMER ZU BETRETEN?!', '', 28153),
(141855, 'deDE', '', 'Sobald Ihr sie auf Euch aufmerksam gemacht habt, schicke ich sie weg.', 28153),
(141852, 'deDE', 'Die Angst... sie ist T\'paartos überallhin gefolgt!', '', 28153),
(141851, 'deDE', 'T\'paartos bereut, dass er $p mickrig genannt hat.', '', 28153),
(141850, 'deDE', 'T\'paartos kennt keine Furcht!', '', 28153),
(141849, 'deDE', 'Hier, Champion!', '', 28153),
(141848, 'deDE', 'Achtung!', '', 28153),
(141847, 'deDE', 'Hier drüben!', '', 28153),
(141846, 'deDE', 'Hier entlang!', '', 28153),
(141845, 'deDE', 'Wir haben das Azeritlager gesichert und die restlichen Aschenwindwachen unter unsere Kontrolle gebracht. Das Gefängnis ist unser.', 'Wir haben das Azeritlager gesichert und die restlichen Aschenwindwachen unter unsere Kontrolle gebracht. Das Gefängnis ist unser.', 28153),
(141844, 'deDE', 'Ich hoffe, Ihr habt Korgus für seine Grausamkeit büßen lassen.', 'Ich hoffe, Ihr habt Korgus für seine Grausamkeit büßen lassen.', 28153),
(141843, 'deDE', 'Ich danke Euch!', 'Ich danke Euch!', 28153),
(141842, 'deDE', 'Die Gefangenen sind sicher und wir haben die unteren Stockwerke unter Kontrolle.', 'Die Gefangenen sind sicher und wir haben die unteren Stockwerke unter Kontrolle.', 28153),
(141841, 'deDE', '', 'Sofort, Hochexarch.', 28153),
(141840, 'deDE', 'Fareeya, Ich benötige ein Signal zur Vindikaar.', '', 28153),
(141839, 'deDE', 'Hier entlang, Champion.', '', 28153),
(141838, 'deDE', 'Wie Ihr wünscht, Hochkönig.', '', 28153),
(141837, 'deDE', 'Ich freue mich darauf, die Lichtgeschmiedeten in die Allianz aufzunehmen. Turalyon, nehmt Euren Champion mit zur Vindikaar und tretet gemeinsam vor Eure Truppen.', '', 28153),
(141836, 'deDE', '', 'Ihr gefallt mir. Nicht leicht zufrieden zu stellen. Immer auf der Suche nach Perfektion, genau wie ich.$B$BEhrlich gesagt: Ich bin mir nicht sicher. Das Ding enthält das Beste an Goblintechnologie, alles in einen winzigen Kasten. Das hat jede Menge Potenzial, wenn Ihr mich fragt.$B$BFindet eine gewaltige Energiequelle und... schaut einfach, was passiert. Aber hey: Ich übernehme keine Garantie.', 28153),
(141835, 'deDE', '', 'Niko, mehr Licht! Oh, hallo, $gHübscher:Hübsche;! Hab Euch gar nicht gesehen. Was kann ich für Euch tun?', 28153),
(141834, 'deDE', '', 'Ich bin mir nicht ganz sicher! Diese Kamera steckt voller mächtiger Technologie... wahrscheinlich hat sie auch die eine oder andere Zusatzfunktion.$B$BAm Besten probiert Ihr sie in der Nähe einer gewaltigen Energiequelle aus. Das sollte helfen!', 28153),
(141833, 'deDE', 'Kann diese Kamera noch mehr?', 'Kann diese Kamera noch mehr?', 28153),
(141832, 'deDE', 'Ich habe meine Kamera verloren. Könnt Ihr mir eine neue bauen?', 'Ich habe meine Kamera verloren. Könnt Ihr mir eine neue bauen?', 28153),
(141831, 'deDE', '', 'Selbsteinstellender Lichtbildfestindexerzeuger.', 28153),
(141830, 'deDE', 'Was bedeutet S.E.L.F.I.E.?', 'Was bedeutet S.E.L.F.I.E.?', 28153),
(141829, 'deDE', '', 'Oh, hi! Wollt Ihr ein S.E.L.F.I.E. mit mir machen?', 28153),
(141828, 'deDE', 'Wir verlangen Antworten, Pike!', 'Wir verlangen Antworten, Pike!', 28153),
(141827, 'deDE', 'Ihr denkt nur daran, wie Ihr unsere Ernte stehlen könnt! \"Für die Soldaten\"...', 'Ihr denkt nur daran, wie Ihr unsere Ernte stehlen könnt! \"Für die Soldaten\"...', 28153),
(141826, 'deDE', 'Die Miliz war seit Tagen nicht mehr auf Patrouille!', 'Die Miliz war seit Tagen nicht mehr auf Patrouille!', 28153),
(141825, 'deDE', 'Unterstadt wird angegriffen! Lauft zum Magierportal!', 'Unterstadt wird angegriffen! Lauft zum Magierportal!', 28153),
(141824, 'deDE', 'Sollen wir einfach alles stehen und liegen lassen und nach Orgrimmar flüchten?', 'Sollen wir einfach alles stehen und liegen lassen und nach Orgrimmar flüchten?', 28153),
(141823, 'deDE', 'Sie haben plötzlich angefangen, die Tore dichtzumachen. Was ist los?', 'Sie haben plötzlich angefangen, die Tore dichtzumachen. Was ist los?', 28153),
(141822, 'deDE', 'Sicherheit hin oder her, ich will nicht meine ganzen Waren in diesem Krieg verlieren!', 'Sicherheit hin oder her, ich will nicht meine ganzen Waren in diesem Krieg verlieren!', 28153),
(141821, 'deDE', 'Ich muss meine Freunde finden!', 'Ich muss meine Freunde finden!', 28153),
(141820, 'deDE', 'Mama hat gesagt, die Soldaten beschützen uns vor den Bösen. Wo sind die Soldaten hin?', 'Mama hat gesagt, die Soldaten beschützen uns vor den Bösen. Wo sind die Soldaten hin?', 28153),
(141819, 'deDE', 'Ich hatte solche Angst! Danke!', 'Ich hatte solche Angst! Danke!', 28153),
(141818, 'deDE', 'Ich will meinen Papa!', 'Ich will meinen Papa!', 28153),
(141817, 'deDE', 'Wo ist die Miliz?', 'Wo ist die Miliz?', 28153),
(141816, 'deDE', 'Ihr habt mich gerettet. Danke Euch!', 'Ihr habt mich gerettet. Danke Euch!', 28153),
(141815, 'deDE', 'So gnadenlos haben sie uns noch nie angegriffen!', 'So gnadenlos haben sie uns noch nie angegriffen!', 28153),
(141814, 'deDE', 'Von hier aus schaffe ich es. Ich bete, dass es den anderen gut geht!', 'Von hier aus schaffe ich es. Ich bete, dass es den anderen gut geht!', 28153),
(141813, 'deDE', 'Ich... bin nicht sicher. Mayla, wir beide müssen vorangehen. Baine, Ihr und Euer Champion versammelt die anderen und stoßt am Gipfel zu uns.', '', 28153),
(141812, 'deDE', 'Kind der... Was hat das zu bedeuten?', '', 28153),
(141811, 'deDE', 'Ja... kommt! Eure Stärke wird die unsere sein, Kind der Finsternis!', '', 28153),
(141810, 'deDE', 'Der letzte Zauberschutz wurde auf dem Hochberggipfel platziert. Dort müssen wir hin. Und genau wie Huln müssen wir mit unseren Verbündeten Schulter an Schulter stehen.', '', 28153),
(141809, 'deDE', 'In der Tat. Und als ich den Berg verließ, um nach Mulgore zu reisen, ließen die Zauberschutze gerade genug nach, dass die Finsternis hindurchsickern konnte.', '', 28153),
(141808, 'deDE', '', 'Seit jenen Tagen lauern die Nekrodunklen in den Schatten darauf, ihren Meister erneut heraufzubeschwören.', 28153),
(141807, 'deDE', 'Und so erdachte Huln einen anderen Plan. Es wurden Zauberschutze errichtet, um den Einfluss der Alten Götter einzuschließen. Der General überlebte, doch Uul\'gyneths Essenz war gefangen.', '', 28153),
(141806, 'deDE', 'Huln vereinte Helden aus allen Stämmen. Sie bekämpften Uul\'gyneths Diener, die Nekrodunklen... doch die Mächte der Schatten waren zu gewaltig, um ihnen standzuhalten.', '', 28153),
(141805, 'deDE', 'Vor langer Zeit trachteten die Alten Götter nach dem Hochberg. Ihr Vormarsch wurde von einer entsetzlichen Alptraumkreatur angeführt... Uul\'gyneth die Finsternis.', '', 28153),
(141804, 'deDE', '', 'Doch unsere Arbeit ist nicht getan. Ebenhorn, wir müssen erfahren, wonach sich diese Finsternis verzehrt.', 28153),
(141803, 'deDE', 'Champion! Grauhimmel hat mir von Eurem Heldenmut berichtet.', '', 28153),
(141802, 'deDE', 'Meine Gedanken sind wieder die meinen. Champion, kehrt nach Donnertotem zurück. Rüsten wir uns für das, was vor uns liegt.', '', 28153),
(141801, 'deDE', '', 'Beeilung! Ich hör die andren in der Nähe.', 28153),
(141800, 'deDE', '', 'Ich werde hier bleiben, während Grauhimmel Euch unterstützt. Betet, dass die Erneuerung der Zauberschutze Ebenhorns Geist heilt.', 28153),
(141799, 'deDE', '', 'Die Wasser haben Ebenhorns Leid gelindert, doch ich fürchte, er entgleitet uns.', 28153),
(141798, 'deDE', 'Reist zum Hochberg und unterstützt Mayla, Champion. Ich werde Euch in Kürze folgen.', '', 28153),
(141797, 'deDE', 'Ich muss Gewissheit haben, dass die Diener der Alten Götter aus Mulgore vertrieben wurden.', '', 28153),
(141796, 'deDE', 'Eure Meister werden meine Stadt nicht erobern, Monster!', '', 28153),
(141795, 'deDE', 'Vernichtet sie! Sie dürfen meine Rückkehr nicht vereiteln!', '', 28153),
(141794, 'deDE', '', 'Wenn die das Monster entfessel\'n, werden die Bluttrolle unaufhaltbar. Selbst Ihr un\' die Horde reich\'n dann nich\' mehr aus. Wir brauch\'n \'nen neuen Plan.', 28153),
(141793, 'deDE', '', 'Sie verfolg\'n uns nich\' mehr. Sieht aus, als hab\'n wir\'s geschafft.', 28153),
(141792, 'deDE', 'Also dann. Fegen wir diesen Abschaum der Alten Götter aus Donnerfels.', '', 28153),
(141791, 'deDE', '', 'Ich verstehe, mein Freund. Baine, ich muss Ebenhorn zurück zum Hochberg bringen.', 28153),
(141790, 'deDE', 'Mayla... die Teiche...', '', 28153),
(141789, 'deDE', '', 'Ich hab keine Angst vor Euch oder Euern Monstern. Ihr werdet alle durch meine Hand sterb\'n.', 28153),
(141788, 'deDE', '', 'Lauft, kleine Prinzessin! Nix wird Euch vor mei\'m Meister rett\'n! G\'huun wird Euch fress\'n!', 28153),
(141787, 'deDE', '', 'Wir müss\'n hier weg! Haltet Euch fest!', 28153),
(141786, 'deDE', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tDie Sandkönigin |cFFFF0000|Hspell:257609|hwird [wütend]|h|r!', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tDie Sandkönigin |cFFFF0000|Hspell:257609|hwird [wütend]|h|r!', 28153),
(141784, 'deDE', 'Die Zauberschutze sind geschwächt! Er wird unser sein!', '', 28153),
(141783, 'deDE', 'Gemeinsam werden wir in die Fluten zurückkehren. Gemeinsam werden wir wieder mächtig sein!', '', 28153),
(141782, 'deDE', 'Mit der Macht des Meeres werden uns die Gezeitenweisen zum Sieg führen!', '', 28153),
(141781, 'deDE', 'Wir müssen unsere Kräfte vereinen. Kul Tiras wird für immer dem Volk gehören.', '', 28153),
(141780, 'deDE', 'Haus Sturmsang muss die Kontrolle über dieses gespaltene Land übernehmen und ihm zu altem Ruhm verhelfen.', '', 28153),
(141779, 'deDE', 'Nie wieder werden wir unsere Felder bestellen und Schiffe bauen für die Elite von Boralus, die uns nicht einmal dankt.', '', 28153),
(141778, 'deDE', 'Kinder der See, heute erleben wir den Anbruch einer neuen Ära für uns alle.', '', 28153),
(141777, 'deDE', 'Wenn Ihr geseh\'n hättet, was ich geseh\'n hab, würdet Ihr dasselbe tun. Kommt, ich zeig\'s Euch!', '', 28153),
(141774, 'deDE', 'Systemenergieversorgung auf kritischem Wert.', '', 28153),
(141773, 'deDE', 'Primäre Zielsuche f-f-fällt aus...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141772, 'deDE', 'Zustand wird schlechter. Benötige Unterstützung.', '', 28153),
(141771, 'deDE', 'Fehlfunktion!', '', 28153),
(141770, 'deDE', '', 'Das goldene Refugium? Das ist vermutlich Atal\'Dazar. Es ist eine Stadt. Aus Gold. Eine goldene Stadt.$b$bAber Refugium? Vielleicht für Gold. Oder Dinosaurier. Oder Dinosaurier mit Goldbeschlag!$b$bIch würde es dort versuchen.', 28153),
(141769, 'deDE', 'Sie wurden wohl da lang geschleppt. Den Gletscher im Nordwesten hoch.', '', 28153),
(141768, 'deDE', 'Habt Ihr je etwas von einem \"goldenen Refugium\" gehört?', 'Habt Ihr je etwas von einem \"goldenen Refugium\" gehört?', 28153),
(141767, 'deDE', 'Eure Mission ist es, diese Maden zu finden, sie auszurotten und unsere Zivilisten sicher nach Orgrimmar zu bringen.', '', 28153),
(141766, 'deDE', 'Wir haben diese Feiglinge im Magierviertel isoliert und die restlichen Viertel gesichert.', '', 28153),
(141765, 'deDE', 'Unsere Feinde greifen Unterstadt an und wollen Lordaeron für sich beanspruchen.', '', 28153),
(141764, 'deDE', 'Unterstadt ist für Zivilisten nicht mehr sicher. Über der Erde tobt die Schlacht und Dutzende von Spionen haben die Stadt infiltriert.', '', 28153),
(141762, 'deDE', 'Soldaten der Horde, die Zeit ist gekommen!', '', 28153),
(141761, 'deDE', '', 'Sammelt Euch im Tal der Ehre, sobald Ihr in Orgrimmar seid! Ihr seid nicht sicher hier!', 28153),
(141760, 'deDE', '', 'Mein Portal ist offen! Wir müssen flüchten!', 28153),
(141759, 'deDE', '', 'Flieht nach Orgrimmar! Hier seid Ihr nicht sicher!', 28153),
(141758, 'deDE', 'Guter... Schuss...', '', 28153),
(141757, 'deDE', 'Rennt, wie Ihr wollt! Ich verfehle nie mein Ziel.', '', 28153),
(141756, 'deDE', 'Ihr steht im Kreuzfeuer!', '', 28153),
(141755, 'deDE', 'Diese Munition wollte ich schon lange an lebenden Zielen ausprobieren.', '', 28153),
(141754, 'deDE', 'Zurück zur Tagesordnung.', '', 28153),
(141753, 'deDE', 'Hat Euch Euer Henkersmahl gemundet? Oder war es zu bleihaltig?', '', 28153),
(141752, 'deDE', 'Todesurteil vollstreckt!', '', 28153),
(141751, 'deDE', 'Wie freundlich von Euch, für Eure Hinrichtung zurückzukehren.', '', 28153),
(141750, 'deDE', 'Weitere Bomben sind unterwegs!', '', 28153),
(141749, 'deDE', 'Jawohl, Herrin!', '', 28153),
(141748, 'deDE', '', 'Ich will diese Feuer heißer brennen sehen!', 28153),
(141747, 'deDE', '', 'Mehr Brennstoff für das Feuer! Sofort!', 28153),
(141746, 'deDE', '', 'Von Euch wird nur Asche übrig bleiben!', 28153),
(141745, 'deDE', '', 'Brennt auf dem Scheiterhaufen!', 28153),
(141744, 'deDE', '', 'Euch werde ich einheizen!', 28153),
(141743, 'deDE', 'Ihr habt meinem Freund wehgetan!', '', 28153),
(141742, 'deDE', '', 'Die hellsten Sterne... brennen am schnellsten aus...', 28153),
(141741, 'deDE', 'Ihr werdet zahlen, für das, was Ihr getan habt!', '', 28153),
(141740, 'deDE', 'Beschäftigt sie, mein Großer! Ich werde sie schon kleinkriegen.', '', 28153),
(141739, 'deDE', '', 'Wir müss\'n die Waffe find\'n, bevor Jakra\'zet sie in die Finger kriegt.', 28153),
(141738, 'deDE', '', 'Keine Ahnung, was das für \'ne Waffe is\' oder wo sie is\', aber gut kann das nich\' sein, wenn Jakra\'zet sie vorm König verheimlicht.', 28153),
(141737, 'deDE', '', 'Die durchsuch\'n die Wüste nach \'ner Waffe, die die Stadt zerstör\'n kann, un\' töt\'n jed\'n in ihr\'m Weg.', 28153),
(141736, 'deDE', '', 'Wie ich mir dachte. General Jakra\'zet hat Trupp\'n in der Wüste un\' der König weiß nix davon.', 28153),
(141735, 'deDE', 'Sondieren', 'Sondieren', 28153),
(141734, 'deDE', 'Aber klar! Kommt her, ich hab was für Euch zu tun.', '', 28153),
(141733, 'deDE', 'Hey, Rulf! Ich hab hier jemand Vielversprechendes! Habt Ihr Arbeit zu erledigen?', '', 28153),
(141732, 'deDE', '', 'Ich mag Blasen. Ich fühle mich sicher in Blasen.', 28153),
(141731, 'deDE', 'Stellt Euch vor, dort draußen gibt es Städte ohne eine magische Schutzblase. Ich meine, wie halten die Leute dort den Staub fern? Diese Wilden.', '', 28153),
(141730, 'deDE', '', 'Ich dacht\', ich sehe sie nie wieder...', 28153),
(141729, 'deDE', 'Die Erinnerungen komm\'n zurück, un\' damit auch der Schmerz...', '', 28153),
(141728, 'deDE', '', 'Ist es Euch etwa zu heiß geworden?', 28153),
(141727, 'deDE', '', 'Oh... Ich liebe es, Fleisch brutzeln zu hören!', 28153),
(141726, 'deDE', '', 'Mit Euren Leichen werden die Feuer noch höher lodern!', 28153),
(141725, 'deDE', '', 'Ich kann es kaum erwarten, Euch brutzeln zu sehen.', 28153),
(141724, 'deDE', '', '$p, kommt schnell! Rakera erinnert sich!', 28153),
(141723, 'deDE', 'Ich dachte... Euer Blut wird fließen...', '', 28153),
(141722, 'deDE', '', 'Mein Kopf... Kaja, seid Ihr das?', 28153),
(141721, 'deDE', 'Die Jagd ist eröffnet!', '', 28153),
(141720, 'deDE', 'Ihr habt meinen kleinen Bruder getötet. Dafür reiß ich Euch in Stücke.', '', 28153),
(141719, 'deDE', 'Brüderchen!', '', 28153),
(141718, 'deDE', 'Hoch mit dir, Brüderchen! Hier schreien Leute danach, getötet zu werden.', '', 28153),
(141717, 'deDE', 'Kommt, Jungs! Zeigen wir ihnen, wer hier im Block das Sagen hat!', '', 28153),
(141716, 'deDE', 'Diese Klingen hab ich extra für Euch geschärft!', '', 28153),
(141715, 'deDE', 'Aber... ich war doch schon fast draußen...', '', 28153),
(141714, 'deDE', 'Ihr wärt besser in Eurer Zelle geblieben.', '', 28153),
(141713, 'deDE', 'Schickt mich nach Ulduar. (Zeitwanderungsschlachtzug)', 'Schickt mich nach Ulduar. (Zeitwanderungsschlachtzug)', 28153),
(141712, 'deDE', '', 'Grüße, $n. Ihr erinnert Euch sicher nicht an mich. Wir haben uns nächste Woche getroffen.$b$bMöchtet Ihr erneut Ulduar besuchen?', 28153),
(141711, 'deDE', 'Ich bin der Alphawolf!', '', 28153),
(141710, 'deDE', 'Kurzer Prozess.', '', 28153),
(141709, 'deDE', 'Frischfleisch!', '', 28153),
(141708, 'deDE', 'Schwächt den Greifen, aber Ihr solltet Euch dabei trotzdem gut|TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Festhalten]|h|r!', '', 28153),
(141707, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(141706, 'deDE', '', 'An die Arbeit.', 28153),
(141705, 'deDE', '', 'Ich glaub, wir haben\'s geschafft. Wir müss\'n uns beeil\'n, wenn wir an den Ruinen von Zul\'jan ankomm\'.', 28153),
(141704, 'deDE', '', 'Die Bluttrolle sin\' unnachgiebig un\' zahllos un\' zehr\'n von der Macht von \'nem Alten Gott.', 28153),
(141703, 'deDE', '', 'Schön, dass Euch das auffällt, Flick. Da seid Ihr mei\'m Vater ein\' Schritt voraus.', 28153),
(141701, 'deDE', '', 'Untote! Die marschier\'n auf Zuldazar. Wir müss\'n sie vernicht\'n.', 28153),
(141696, 'deDE', 'Der Talisman scheint nicht zu wirken. Probiert ihn erst einmal an einigen fluchgeformten Knechten aus.', '', 28153),
(141695, 'deDE', 'Der Typ ist nicht die hellste Kerze im Leuchter, was?', '', 28153),
(141694, 'deDE', 'Glückschweif läuft zum Wasserfall!', '', 28153),
(141693, 'deDE', '', '', 28153),
(141692, 'deDE', '|cffffff00+$1i Rüstungsfetzen|r', '|cffffff00+$1i Rüstungsfetzen|r', 28153),
(141691, 'deDE', 'Glückschweif flieht und begibt sich in Sicherheit!', '', 28153),
(141690, 'deDE', '', 'Was hab\'n diese Kultisten Rakera angetan... Sie erinnert sich nich\' mal an ihren eigenen Namen.', 28153),
(141689, 'deDE', 'Ihr da! Ja, Ihr. Kommt her, aber leise, Mann. Bleibt unauffällig.', '', 28153),
(141688, 'deDE', '', 'Was ham sie mit Euch gemacht...', 28153),
(141687, 'deDE', '', 'Wir alle sind Akunda.', 28153),
(141686, 'deDE', '', 'Rakera?', 28153),
(141685, 'deDE', '', 'Sie ist hier. Sie lebt! Rakera!', 28153),
(141684, 'deDE', '', 'Rakera!', 28153),
(141683, 'deDE', '', 'Irgendwer in diesem seltsamen Tempel muss was wiss\'n.', 28153),
(141682, 'deDE', 'Es is\' mir egal, was ihr glaubt, vom König und seiner Tochter erkauf\'n zu können. Wisst, dass Ihr in Zuldazar nich\' willkomm\'n seid.$b$bDie Prinzessin mag \'ne große Autorität hab\'n, aber sie is\' noch nich\' Königin.$b$bBis dahin liegt die wahre Macht von Zuldazar bei mir und dem Rat der Zanchuli.', '', 28153),
(141681, 'deDE', '', 'Das ist eine förmliche Zeremonie. Keine Unterbrechungen!', 28153),
(141680, 'deDE', 'T\'paartos erkennt das jetzt.', '', 28153),
(141679, 'deDE', 'Dunkelheit lebt in uns allen. Es ist nicht leicht, sich ihr zu stellen.', '', 28153),
(141678, 'deDE', '', 'T\'paartos... Ihr habt Euch Eurer Furcht... und Euren Fehlern gestellt... und wurdet wiedergeboren.', 28153),
(141677, 'deDE', '', 'Willkommen zurück, T\'paartos.', 28153),
(141676, 'deDE', '', 'Wenn Rakera hier im Tempel is\', werd\'n wir sie find\'n.', 28153),
(141675, 'deDE', 'Ihr stinkt! Kraaaah!', '', 28153),
(141674, 'deDE', 'Tut Haihappen leid, dass Ihr nach Papageienmist riecht.', '', 28153),
(141673, 'deDE', 'Krah! Kragg ist tot! Tut Haihappen leid...', '', 28153),
(141672, 'deDE', '', 'Ah, \'n Mitglied der Horde. Wie sonderbar...', 28153),
(141671, 'deDE', '$n hat die Allianztruppen beim Sägewerk angegriffen!', '$n hat die Allianztruppen beim Sägewerk angegriffen!', 28153),
(141669, 'deDE', '', 'Selbst der Wind hier is\' von der Macht der Loa erfüllt. Pa\'ku gleitet hier irgendwo durch die Luft. Ich kann ihre Gegenwart spür\'n.$b$bIch war noch nie in Zandalar, aber mein alter Großvater hat mir immer Geschicht\'n über dies\'n Ort erzählt.', 28153),
(141668, 'deDE', '', 'Die Loa hier sin\' mächtig. Ich spür die Gegenwart meines eignen Loas, Gonk, wie er hinter jedem Baum un\' Busch lauert.$b$bGonk is\' in der Nähe. Es wird großartig sein, ihn endlich mit eignen Augen zu seh\'n.', 28153),
(141667, 'deDE', 'So leicht werden wir nicht fallen. Soldaten! Erobert unser Sägewerk zurück!', '', 28153),
(141666, 'deDE', 'Grüße, kleines Wesen.$b$bIch bin Hexfürst Raal, Mitglied des Rats der Zanchuli und Oberster von jenen, die mit Pa\'ku feilsch\'n, dem Loa der Winde.$b$bIch bin sehr wichtig und sehr beschäftigt. Was wollt Ihr?', '', 28153),
(141665, 'deDE', '', 'Unsre Zeit mit dem Hexfürst is\' knapp bemess\'n. Unterbrecht uns nich\'. Es gibt viel zu besprech\'n.', 28153),
(141664, 'deDE', 'Mein Freund!', '', 28153),
(141663, 'deDE', '', 'Jetzt wissen die Sethrak, wen sie fürchten müssen: die Vulpera!', 28153),
(141662, 'deDE', 'General Jakra\'zet, der Emporkömmling von Sandwütertroll, der das Militär von Zuldazar leitet, hat sich offenbar entschied\'n, seine Wachen vom Hafen zurückzuzieh\'n.\n\nEs scheint, dass nicht alle Trolle glücklich mit Prinzessin Talanjis Entscheidung sind, andere als Trolle in den Hafen zu lass\'n.\n\nSie wird hierfür die Hilfe von mindestens einem Mitglied des Rats der Zanchuli benötig\'n. Glücklicherweise weiß ich, wo sich zwei befind\'n.', '', 28153),
(141660, 'deDE', '', 'Die Vulpera sind überhaupt nicht schwach. Sie werden uns fürchten!', 28153),
(141658, 'deDE', 'Absorbieren', 'Absorbieren', 28153),
(141657, 'deDE', '', 'Diese Sethrak werden für das bezahlen, was sie unserer Heimat angetan haben.', 28153),
(141655, 'deDE', 'Nein, kümmert Euch nicht um mich, $gmein Herr:Frollein;. Hick. Isch mache misch gleisch auf den Weg... uh... Wo zur Hölle bin isch?$b$bAlscho gut, isch leg misch hier einfach hin und nüschtere aus, bisch Ihr wieder hier scheid. Hick. Dasch geht ruck schuck. Isch schwör!', '', 28153),
(141654, 'deDE', 'Haha, dasch isch der witzige Teil davon. Der hat sisch doch tatssäschlisch schnappen laschn. Hick. Der Schtrolch wollte wen umbringen.$b$bJetzt sitzsst er im Gefängnisch mit den andern Gesellen. Hick. Wenn er esch immer noch dabeihat, wette ich darauf, dass Ihr esch aus seinen toten Klauen herausreißen müsst.$b$bAber misch wollt Ihr nicht töten, oder? Hick. Isch habe Eusch nichts getan.$b$bHört tschu, isch gehe einfach meiner Wege und werd wieder nüchtern. Scheemansehrenwort, haha.', '', 28153),
(141653, 'deDE', 'Wo ist die Person, die das Juwel genommen hat?', 'Wo ist die Person, die das Juwel genommen hat?', 28153),
(141652, 'deDE', 'Diescher Hund ischt mit unscherem Juwel abgehauen. Hick. Wir haben ewig gebraucht, esch aussugraben und wasch macht er? Hick.$b$bEr macht sisch mitten in der Nacht ausm Staub. Wir werden dieschen Klunker verkaufen und stinkreich werden! Hick.$b$b<Johann nimmt einen weiteren Schluck aus seinem Krug.>$b$bHabt Ihr vieleisch ein bischen Kleingeld für misch, $gmein Herr:Frollein;?', '', 28153),
(141651, 'deDE', '', 'Ich bin bereit. Blasen wir zur Sethrakjagd.', 28153),
(141649, 'deDE', 'Prinzessin Talanji sagt, sie braucht Eure Hilfe mit Jakra\'zet.', 'Prinzessin Talanji sagt, sie braucht Eure Hilfe mit Jakra\'zet.', 28153),
(141648, 'deDE', '', 'Ihr steht vor Kriegsdruidin Loti, Ergebene von Gonk, Champion der Jagd un\' Meisterin des Spurenlesens. Was wollt Ihr, $C?', 28153),
(141647, 'deDE', 'Lasst die Sägeblätter kreischen! Wir brauchen mehr Holz!', '', 28153),
(141646, 'deDE', 'Oh, damit gibt\'s ein Problem. Jakra\'zet weigert sich, die Befehle der Prinzessin auszuführ\'n.$b$bIch brauch die Hilfe eines weiteren Mitglieds im Rat der Zanchuli, aber die zwei hier anwesenden sind damit beschäftigt, \'nen Stammesstreit zu schlicht\'n.$b$bGeht nach Tal\'aman oder Tal\'farrak und versucht, einen dieser Zanchuli zu überred\'n, uns zu helf\'n.$b$bWenn ich für eine solche Aufgabe nich\' viel zu wichtig wär, würd ich selbst geh\'n.', '', 28153),
(141645, 'deDE', 'Prinzessin Talanji verlangt zu wissen, wo die Wachen sind.', 'Prinzessin Talanji verlangt zu wissen, wo die Wachen sind.', 28153),
(141644, 'deDE', 'In dem Moment, als ich Euer Gesicht in Sturmwind geseh\'n hab, wusste ich, dass die Zeit der Prophezeiung gekomm\'n ist.$b$bDie Geister zeig\'n mir viele Dinge, und in diesen Visionen hab ich Euer Gesicht in Verbindung mit vielen großen Ereignissen geseh\'n, die da kommen werd\'n.$b$bDie Dinge sind in Bewegung, $C. Bald werd\'n Ihr und ich die Welt erzittern lass\'n.', '', 28153),
(141643, 'deDE', 'Und Euch würde ich dasselbe raten. Viel Glück.', 'Und Euch würde ich dasselbe raten. Viel Glück.', 28153),
(141642, 'deDE', 'Ja... fügt Euch, T\'paartos. Empfangt wahre Macht!', '', 28153),
(141641, 'deDE', 'Entledigt Euch der Ketten, die das Licht Euch aufgebürdet hat.', '', 28153),
(141640, 'deDE', 'Das Licht ist nicht der Pfad zu wahrer Stärke.', '', 28153),
(141639, 'deDE', 'Solche Macht erwartet uns, T\'paartos.', '', 28153),
(141638, 'deDE', 'Das Licht war immer an T\'paartos\' Seite! Er wird sich niemals vom Licht abwenden!', '', 28153),
(141637, 'deDE', 'GENUG!!!', '', 28153),
(141636, 'deDE', 'Nein...', '', 28153),
(141635, 'deDE', 'Nein... das ist nicht real. Das kann nicht der wahre T\'paartos sein!', '', 28153),
(141634, 'deDE', 'Ugh! Könnt Ihr die Schlangen fortjagen?', '', 28153),
(141633, 'deDE', 'Das ist... etwas peinlich für T\'paartos.', '', 28153),
(141632, 'deDE', 'T\'paartos kann Berge versetzen!', '', 28153),
(141631, 'deDE', 'In der Armee des Lichts hat sich T\'paartos vielen solcher Feinde gestellt.', '', 28153),
(141630, 'deDE', 'Aaah, Ika. T\'paartos zog diesen Elekk auf, als seine Mutter getötet wurde.', '', 28153),
(141629, 'deDE', 'Nein! Die Dunkelheit wird T\'paartos nicht verschlingen!', '', 28153),
(141628, 'deDE', 'War T\'paartos für diesen Pfad bestimmt? Ist T\'paartos würdig, ein Lichtgeschmiedeter zu werden?', '', 28153),
(141623, 'deDE', 'Und wieder habt Ihr mich gerettet! Ich gehe zum Lager zurück, bevor ich mich noch erkälte.', '', 28153),
(141620, 'deDE', '', 'Tötet sie nicht ohne mich.', 28153),
(141619, 'deDE', '', 'Die Vulpera sind bereit. Die Treulosen werden uns fürchten.', 28153),
(141618, 'deDE', 'Mmmm... erwische... mmmm.', '', 28153),
(141617, 'deDE', 'Von dem Gold wollte isch meine Hochzeit finanzieren <Schluchz>.', '', 28153),
(141616, 'deDE', 'Schobald ich ein Boot auftreiben kann, scheid ihr dran!', '', 28153),
(141615, 'deDE', 'Ihr habt unscher verdammtes Juwel geschtolen. Hick. Elender Schtrolch!', '', 28153),
(141614, 'deDE', 'Ihr habt unscher... Hick.', '', 28153),
(141613, 'deDE', 'Ich muss aufhören, Nisha die Planung zu überlassen...', '', 28153),
(141612, 'deDE', '', 'Wohl gar nicht. Die meisten Eurer Art können das nicht. Na ja, nicht mehr.', 28153),
(141611, 'deDE', 'Seid vorsichtig, Meerah. Die alten Trollstraßen sind gefährlich für unsere Wagen.', '', 28153),
(141610, 'deDE', '', 'Die Sethrak werden bereuen, jemals unsere Karawane angegriffen zu haben.', 28153),
(141609, 'deDE', 'Haltet die Taue straff! Nicht nachlassen!', '', 28153),
(141608, 'deDE', '', 'Hier habt Ihr sie, $n. Die fertige Übersetzung des Tagebuchs. Ganz schön spannend, wenn Ihr mich fragt.', 28153),
(141607, 'deDE', '', 'Ja? Ja! Das ist es! Wo sind meine leeren Bücher? Ah, hier ist eins.', 28153),
(141606, 'deDE', '', 'Oh! DAZU braucht man die Rune also. Sehr interessant...', 28153),
(141605, 'deDE', '', 'Ihr habt sie alle?! Gute Arbeit, $n. Dann machen wir uns jetzt daran, das Tagebuch zu übersetzen.', 28153),
(141604, 'deDE', '<Der Soldat murmelt etwas Unverständliches vor sich hin.>', '<Die Soldatin murmelt etwas Unverständliches vor sich hin.>', 28153),
(141603, 'deDE', 'Hier sind die Bücher, die Ihr wolltet.', 'Hier sind die Bücher, die Ihr wolltet.', 28153),
(141602, 'deDE', 'Steigt die Flut, oder fallen wir?\n\nTiefer und tiefer...', 'Steigt die Flut, oder fallen wir?\n\nTiefer und tiefer...', 28153),
(141601, 'deDE', 'Perfekt, perfekt, es hat gesagt, alles muss perfekt sein...\n\nWas hat das gesagt?', 'Perfekt, perfekt, es hat gesagt, alles muss perfekt sein...\n\nWas hat das gesagt?', 28153),
(141600, 'deDE', 'Wir werd\'n eine schöne Überraschung für die Zandalari bereithalt\'n!', 'Wir werd\'n eine schöne Überraschung für die Zandalari bereithalt\'n!', 28153),
(141599, 'deDE', 'Die Kroggs wachs\'n wirklich gut. Sie sin\' bald bereit für ihren ersten Ausritt.', 'Die Kroggs wachs\'n wirklich gut. Sie sin\' bald bereit für ihren ersten Ausritt.', 28153),
(141598, 'deDE', 'Verzeiht, Mutta. Ich mach\' sofort den Weg für Euch frei.', 'Verzeiht, Mutta. Ich mach\' sofort den Weg für Euch frei.', 28153),
(141597, 'deDE', 'Ich rat Euch, Eure Waffen messerscharf zu wetz\'n. Bald werd\'n wir den Zandalari gegenübertret\'n.', 'Ich rat Euch, Eure Waffen messerscharf zu wetz\'n. Bald werd\'n wir den Zandalari gegenübertret\'n.', 28153),
(141596, 'deDE', 'Kriegshäuptling Sylvanas Windläufer, ich stelle vor – Häuptling Mayla Hochberg.', '', 28153),
(141595, 'deDE', 'Einer unserer Rucksäcke. Hier sind wir wohl richtig.', '', 28153),
(141594, 'deDE', 'Ah. Eine unserer Äxte. Wir sind auf dem richtigen Weg.', '', 28153),
(141593, 'deDE', 'Der arme Kerl ist schon ewig tot. Suchen wir im Osten nach dem Vorratskarren.', '', 28153),
(141592, 'deDE', 'Ich hab Euch noch nie geseh\'n. Beeilt Euch besser und geht rein. Angeblich wurde Najimas Arbeitergruppe tot aufgefund\'n.', 'Ich hab Euch noch nie geseh\'n. Beeilt Euch besser und geht rein. Angeblich wurde Najimas Arbeitergruppe tot aufgefund\'n.', 28153),
(141591, 'deDE', 'Der letzte Zauberschutz wurde auf dem Hochberggipfel platziert. Dort müssen wir hin. Und genau wie Huln müssen wir mit unseren Verbündeten Schulter an Schulter stehen.', '', 28153),
(141590, 'deDE', 'In der Tat. Und als ich den Berg verließ, um nach Mulgore zu reisen, ließen die Zauberschutze gerade genug nach, dass die Finsternis Fuß fassen konnte.', '', 28153),
(141589, 'deDE', '', 'Die Nekrodunklen lauerten also in den Schatten darauf, ihren Meister erneut heraufzubeschwören.', 28153),
(141588, 'deDE', 'Und so erdachte Huln einen anderen Plan. Es wurden Zauberschutze errichtet, um den Einfluss der Alten Götter einzuschließen. Der General überlebte, doch Uul\'gyneths Essenz war gefangen.', '', 28153),
(141587, 'deDE', 'Huln vereinte Helden aus allen Stämmen für die Schlacht. Sie bekämpften Uul\'gyneths Diener, die Nekrodunklen... doch die Mächte der Schatten waren zu gewaltig, um ihnen standzuhalten.', '', 28153),
(141586, 'deDE', 'Vor langer Zeit trachteten die Alten Götter nach dem Hochberg. Ihr Vormarsch wurde von einem grausamen General angeführt... Uul\'gyneth die Finsternis.', '', 28153),
(141585, 'deDE', 'Folgt mir, Champion.', '', 28153),
(141584, 'deDE', '<Der Bürgermeister reagiert nicht.>', '', 28153),
(141583, 'deDE', '<Sucht nach der Quelle des Zaubers.>', '<Sucht nach der Quelle des Zaubers.>', 28153),
(141582, 'deDE', '<Das Bildnis im Zentrum des Ortes pulsiert vor dunkler Energie, die jener ähnelt, welche die Ortsbewohner gefangen hält. Vielleicht fungiert es als Fokus, um den Zauber aufrechtzuerhalten.\n\nVielleicht würde es den Zauber aufheben, wenn man es zerstört.>', '', 28153),
(141581, 'deDE', '<Der Mann entspricht der Beschreibung von Cyril Weiß, dem Bürgermeister von Fallhafen. Leider ist er gerade nicht in der Lage, Euch weiterzuhelfen.\n\nDer Bürgermeister und die anderen Bewohner von Fallhafen scheinen unter dem Einfluss einer unbekannten Magie zu stehen. Er atmet zwar noch, aber er kann sich nicht bewegen und reagiert auch nicht auf Euch.\n\nIhr müsst einen Weg finden, diesen Fluch aufzuheben, wenn er Euch dabei helfen soll, das Haus Kronsteig zu kontaktieren.>', '', 28153),
(141580, 'deDE', 'Ihr habt mich gerettet! Wohin mich die Raubeine wohl als Nächstes schicken...', '', 28153),
(141579, 'deDE', 'Die Zauberschutze sind geschwächt! Er wird unser sein!', '', 28153),
(141578, 'deDE', 'Ihr habt versagt! Die Finsternis erhebt sich... und der Hochberg wird fallen!', '', 28153),
(141577, 'deDE', 'Die Legion war nichts im Vergleich zu unserer Macht! Beugt Euch!', '', 28153),
(141576, 'deDE', 'Die Himmelshörner werden meinen Meistern dienen! Ihr werdet die Schatten sein, die den Himmel verdunkeln!', '', 28153),
(141575, 'deDE', 'Dient Euren wahren Meistern, Drogbar! Fügt Euch oder sterbt!', '', 28153),
(141573, 'deDE', '', 'Hallo! Interessiert Ihr Euch für die Geschichte von Kul Tiras? Ich habe viele Bände über die Gründung und die Politik unserer großen Nation. Ein wahrlich faszinierendes Thema, wirklich.$b$bDie Transkription ist ein weiteres meiner Talente und ich kann Euch zudem beibringen, wie man mit Feder und Tinte umgeht!', 28153),
(141572, 'deDE', 'Ein Fehler un\' wir werd\'n Euch hier begrab\'n.', '', 28153),
(141571, 'deDE', 'Meerah, holt den Wagen und stellt Euch darauf ein, ein paar Sachen am Hafen abzuholen. Unsere neuen Verbündeten können mitfahren und ihre Suche fortsetzen.', '', 28153),
(141570, 'deDE', 'Die Luftfeuchtigkeit hier is\' fast so hässlich wie Euer Gesicht.', 'Die Luftfeuchtigkeit hier is\' fast so hässlich wie Euer Gesicht.', 28153),
(141569, 'deDE', 'Was glotzt Ihr so?', 'Was glotzt Ihr so?', 28153),
(141568, 'deDE', 'Ihr habt das königliche Ohr, also werd\'n wir Euch für den Moment nich\' töten.', 'Ihr habt das königliche Ohr, also werd\'n wir Euch für den Moment nich\' töten.', 28153),
(141567, 'deDE', 'Thronräuber. Eure Horde wird dafür bezahl\'n, was sie unserm Volk in Tanaris angetan hat.', 'Thronräuber. Eure Horde wird dafür bezahl\'n, was sie unserm Volk in Tanaris angetan hat.', 28153),
(141566, 'deDE', 'Einen guten Tag wünsche ich Euch. Interessiert Ihr Euch für Edelsteinschneiderei?$b$bOder wie man es auch nennt: Juwelierskunst?', '', 28153),
(141565, 'deDE', 'Lächelt, solang Ihr noch könnt, $C. \'n falscher Schritt hier und wir töten Euch mit eig\'nen Händ\'n.', 'Lächelt, solang Ihr noch könnt, $C. \'n falscher Schritt hier und wir töten Euch mit eig\'nen Händ\'n.', 28153),
(141564, 'deDE', 'Die Horde hat ihre kostbar\'n Blutelfen uns vorgezog\'n. Und dann hab\'n sie Zul\'jin umgebracht, unsern größten Anführer.$b$bBlut. Ihr schuldet uns \'ne Menge Blut, Mann.', '', 28153),
(141563, 'deDE', 'Passt gut auf, Mann. Sobald die Prinzessin mit Euch fertig is\', werdet Ihr un\' mein Messer \'ne Unterhaltung darüber führ\'n, was die Horde mit Zul\'jin gemacht hat.', '', 28153),
(141562, 'deDE', 'Ihr tragt das Zeichen der Prinzessin Talanji. Das heißt zwar, wir können Euch nich\' töt\'n, aber wir müss\'n Euch deswegen nich\' mög\'n.', '', 28153),
(141561, 'deDE', 'Was guckt Ihr so?', '', 28153),
(141559, 'deDE', 'Der Tempel is\' eine Ruine! Es is\' noch schlimmer, als ich befürchtet hab...', '', 28153),
(141558, 'deDE', 'Ich muss schnell zum Tempel zurück. Ich fürcht mich davor, was in meiner Abwesenheit draus geword\'n ist...', '', 28153),
(141557, 'deDE', '', 'Nun gehören sie mir!', 28153),
(141556, 'deDE', 'Ich bin frei von dem Alten Gott. Vielen Dank, meine Freunde.', '', 28153),
(141555, 'deDE', 'Mayla! Wir müssen vereint kämpfen!', '', 28153),
(141554, 'deDE', '', 'Ich werde nicht zulassen, dass die Finsternis vom Körper meines Vaters Besitz ergreift!', 28153),
(141552, 'deDE', 'Ich wollte... seh\'n...', 'Ich wollte... seh\'n...', 28153),
(141549, 'deDE', 'Zum Kessel mit Euch!', 'Zum Kessel mit Euch!', 28153),
(141547, 'deDE', 'Ah, danke, dass Ihr mich befreit habt! Ich hätt es besser wissen müss\'n, als diesen hinterhältigen Tortaka zu trau\'n!', '', 28153),
(141546, 'deDE', 'Vol\'jamba hat versproch\'n...', 'Vol\'jamba hat versproch\'n...', 28153),
(141544, 'deDE', 'Lag er... falsch?', 'Lag er... falsch?', 28153),
(141538, 'deDE', 'Nur Vol\'jamba kann uns rett\'n!', 'Nur Vol\'jamba kann uns rett\'n!', 28153),
(141536, 'deDE', 'Kommt... hängt mal Eure Nase rein. Dann seh\'n wir, wer \'nen stärk\'ren Willen hat!', '', 28153),
(141535, 'deDE', 'Ich werd\' mich nie... unterwerf\'n...', 'Ich werd\' mich nie... unterwerf\'n...', 28153),
(141528, 'deDE', 'Er hat... gesagt... wir überleb\'n...', 'Er hat... gesagt... wir überleb\'n...', 28153),
(141527, 'deDE', 'Warum hört keiner zu?! Das Ende is\' nah!', 'Warum hört keiner zu?! Das Ende is\' nah!', 28153),
(141524, 'deDE', 'Alles klar, Boss.', '', 28153),
(141523, 'deDE', 'Bodo!', '', 28153),
(141522, 'deDE', 'Holzdiebe! Schnappt sie Euch, Bodo!', '', 28153),
(141519, 'deDE', '', '$n, seid Ihr das? Wo sind wir?', 28153),
(141518, 'deDE', 'Dieser T\'paartos hat sich dem Licht verschworen, und doch... wandelt er mit der Finsternis? Das kann nicht T\'paartos\' Schicksal sein!', '', 28153),
(141517, 'deDE', 'Alles is\' so, wie mein Prophet gesagt hat. Vielleicht versteht Ihr jetzt, warum ich ihn gern an meiner Seite hab.', '', 28153),
(141512, 'deDE', 'Stanzt das Siegel, das ich Euch gegeb\'n hab, auf den Gong.', '', 28153),
(141510, 'deDE', 'Mann!', '', 28153),
(141509, 'deDE', 'Verschwindet! Berührt sie nich\'!', '', 28153),
(141508, 'deDE', 'Also, die Vision is\': Gold\'ne Segel läut\'n die letzte Landung ein. Der Manipulator sucht, das Siegel zu brech\'n.', '', 28153),
(141507, 'deDE', 'Ich bin gut drauf, drum werd ich Euch zuhör\'n. Aber der Champion hier...', '', 28153),
(141506, 'deDE', 'Ich hab \'ne Nachricht für mein\' alten Schüler. Ihr werdet mich find\'n, wenn Ihr die Narren erledigt habt, die ihm hörig sin\'.', '', 28153),
(141505, 'deDE', 'Versteckt Euch nich\' länger hinter Eurer Maske. Ihr erkauft Euch nur \'n bisschen Zeit, aber nich\' viel.', '', 28153),
(141504, 'deDE', 'Dann nehmt unsren neuen Sprecher mit, Problem gelöst.', '', 28153),
(141503, 'deDE', 'Euer Wunsch is\' mir Befehl. Aber... ich hab vorhergeseh\'n, dass Vol\'jamba nich\' durch meine Hand stirbt.', '', 28153),
(141502, 'deDE', 'Das ist Eure Schuld, Prophet. Also kümmert Euch drum.', '', 28153),
(141500, 'deDE', 'Nils! Da bist du ja!', '', 28153),
(141499, 'deDE', '', 'Aber ist die Forschung ohne ein wenig Gefahr nicht langweilig? Bin noch komplett unversehrt.', 28153),
(141498, 'deDE', '', 'Und mehr konnte ich da allein nicht rausholen.', 28153),
(141497, 'deDE', 'Ich bin nur froh, dass Ihr Euch da rausgewunden habt.', '', 28153),
(141496, 'deDE', 'Führt der Pfad zu wahrer Größe? Ruhm? Oder Vernichtung?', '', 28153),
(141495, 'deDE', 'Eine Seele birgt viele Wahrheiten. Einige edel, andere...', '', 28153),
(141494, 'deDE', 'Ein Angebot war zurückgewiesen... und doch bleibt die Furcht.', '', 28153),
(141493, 'deDE', 'Vielleicht muss man die Furcht vor der Dunkelheit akzeptieren, um sie zu überwinden.', '', 28153),
(141492, 'deDE', 'Furcht ist erbarmungslos. Unnachgiebig. Ein Feind, der bezwungen werden muss.', '', 28153),
(141491, 'deDE', 'Sicher. Geborgen. Weit weg von jedem. Von allem.', '', 28153),
(141490, 'deDE', 'Ist Einsamkeit die Antwort? Niemand kann Euch verletzen, wenn Ihr allein seid.', '', 28153),
(141489, 'deDE', 'Gegner lauern in jedem Schatten. Kann diese Finsternis gestoppt werden?', '', 28153),
(141488, 'deDE', 'Unfair! Ungerecht! Nichts ist je, wie es scheint!', '', 28153),
(141487, 'deDE', 'Ablenkung ermöglicht Flucht.', '', 28153),
(141486, 'deDE', 'Tiefer... Sicherheit finden... Geborgenheit finden...', '', 28153),
(141485, 'deDE', 'Gibt es keinen Trost? Keine Linderung?', '', 28153),
(141484, 'deDE', 'Selbst in der dunkelsten Stunde ist noch Hoffnung.', '', 28153),
(141483, 'deDE', 'Qual und Kummer... die Suche nach Trost.', '', 28153),
(141482, 'deDE', 'Hier gibt es keine Güte.', '', 28153),
(141481, 'deDE', 'Schmerz ist der Architekt der Erinnerungen.', '', 28153),
(141480, 'deDE', 'Es geht nur vorwärts.', '', 28153),
(141479, 'deDE', 'Ich erinnere mich an die Zeiten, als nur Trolle auf Zandalar erlaubt waren. Also, Trolle und Tortollaner natürlich.\n\nSie haben selbstverständlich versucht, uns loszuwerden. Ich glaube, es war Rastakhans Urgroßvater, König Tezlekhan der Hitzige. Ein ganz schöner Wichtigtuer. Wir haben dann dafür gesorgt, dass er schneller seine Meinung geändert hat als ein Elementar auf einer Schamanenversammlung.\n\nEs ist erstaunlich, wie viele kleine, dreckige Details man über eine königliche Familie sammeln kann, wenn man länger lebt als sie.', 'Ich erinnere mich an die Zeiten, als nur Trolle auf Zandalar erlaubt waren. Also, Trolle und Tortollaner natürlich.\n\nSie haben selbstverständlich versucht, uns loszuwerden. Ich glaube, es war Rastakhans Urgroßvater, König Tezlekhan der Hitzige. Ein ganz schöner Wichtigtuer. Wir haben dann dafür gesorgt, dass er schneller seine Meinung geändert hat als ein Elementar auf einer Schamanenversammlung.\n\nEs ist erstaunlich, wie viele kleine, dreckige Details man über eine königliche Familie sammeln kann, wenn man länger lebt als sie.', 28153),
(141478, 'deDE', 'Die Zandalari lassen uns unbehelligt ihr Land durchqueren, weil wir ihnen wichtige Informationen liefern.\n\nIch frage mich, was Euer Volk ihnen versprochen hat...', 'Die Zandalari lassen uns unbehelligt ihr Land durchqueren, weil wir ihnen wichtige Informationen liefern.\n\nIch frage mich, was Euer Volk ihnen versprochen hat...', 28153),
(141477, 'deDE', 'Ah, $gein:eine:c; $C. Und von welchem Kontinent stammt Ihr?', 'Ah, $gein:eine:c; $C. Und von welchem Kontinent stammt Ihr?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141476, 'deDE', '', 'Hoff\'n wir, Rokhan un\' die andren schaff\'n es heil zurück nach Zul\'jan... andernfalls wird das \'n kurzer Ausflug.', 28153),
(141475, 'deDE', 'Ah, jemand auf der Suche nach Abenteuern. Kann man Euch mieten? Ich meine, ich könnte Eure Hilfe brauchen, und zwar bei der etwas... gefährlichen... Wiederbeschaffung eines wertvollen Gegenstands.', 'Ah, jemand auf der Suche nach Abenteuern. Kann man Euch mieten? Ich meine, ich könnte Eure Hilfe brauchen, und zwar bei der etwas... gefährlichen... Wiederbeschaffung eines wertvollen Gegenstands.', 28153),
(141474, 'deDE', 'Haben wir uns schon einmal getroffen? Meine Erinnerung ist nicht mehr so gut wie vor hundert Jahren.', 'Haben wir uns schon einmal getroffen? Meine Erinnerung ist nicht mehr so gut wie vor hundert Jahren.', 28153),
(141473, 'deDE', 'Oh, sie haben die Horde nach Zuldazar hineingelassen? Wie fortschrittlich von ihnen.', 'Oh, sie haben die Horde nach Zuldazar hineingelassen? Wie fortschrittlich von ihnen.', 28153),
(141472, 'deDE', '', '', 28153),
(141471, 'deDE', '', 'Tötet diese Bluttrolle! Sie dürf\'n unsern Kahn nich\' versenken.', 28153),
(141470, 'deDE', '', 'Guckt! Bluttrolle. Sie bereit\'n sich wohl auf\'n Angriff auf meine Stadt vor.', 28153),
(141463, 'deDE', 'Was ist das für ein Geräusch?', '', 28153),
(141462, 'deDE', 'Hallo? Ist da wer?', '', 28153),
(141461, 'deDE', 'NUBB NUBB, KOMMT HIER HOCH UND WISCHT DEN KNATZELN EINE!', '', 28153),
(141460, 'deDE', 'Los jetz\', nichtsnutzige, glotzende Echse.', 'Los jetz\', nichtsnutzige, glotzende Echse.', 28153),
(141459, 'deDE', '', 'Ihr verhandelt wie \'n Wurm. Seid ehrlich, was wollt Ihr?', 28153),
(141458, 'deDE', '', 'Raal, Eure Frau wollt mich heut\' Morgen umbring\'n. Was glaubt sie, das Ihr hier drüb\'n vorhabt?', 28153),
(141457, 'deDE', '', 'Raal, wir müssen diese Sache beileg\'n. Diese Forderungen von den Amani müss\'n aufhör\'n.', 28153),
(141456, 'deDE', 'Ein Yeti! Na, war ja fast richtig. Die Form eines Mannes und haarig wie ein Bär.', '', 28153),
(141455, 'deDE', '', 'Uff... Mir wird schon beim Gedanken an Seetang schlecht... umm <Rülps> Oh-oh...', 28153),
(141454, 'deDE', '', 'Hat was über Seetang drübermachen oder so gefaselt?', 28153),
(141453, 'deDE', '', '<Rülps> Oh ja, ich erinnere mich noch an so einen Tölpel, der mit einem Schatz geprahlt hat.', 28153),
(141452, 'deDE', 'Warum müss\'n wir hier Wache schieb\'n, Mann? Das is\' so öde.', 'Warum müss\'n wir hier Wache schieb\'n, Mann? Das is\' so öde.', 28153),
(141451, 'deDE', '', 'Woooooaaaah! <Hicks>$B$BÄh? Wasch losch?', 28153),
(141450, 'deDE', '<Seufz> Nubb Nubb hilft es jedenfalls nicht.', '', 28153),
(141449, 'deDE', 'Hat aber nur gesagt, dass er an einem \"sandigen Ort\" vergraben ist. Was soll das weiterhelfen?!', '', 28153),
(141448, 'deDE', 'Nubb Nubb hat von einem Schatz gehört. Das ganze Gasthaus hat es gehört!', '', 28153),
(141447, 'deDE', 'Was muss gewischt werden?', '', 28153),
(141446, 'deDE', 'VERGRABENER. SCHATZ.', 'VERGRABENER. SCHATZ.', 28153),
(141445, 'deDE', 'KLEEFARBENER LATZ?!', '', 28153),
(141444, 'deDE', 'Nein, nein. Ein vergrabener Schatz.', 'Nein, nein. Ein vergrabener Schatz.', 28153),
(141443, 'deDE', 'ERHABENER SPATZ?', '', 28153),
(141442, 'deDE', 'LETZTENS WAR ABER EIN KERL IM GASTHAUS, DER MIT SEINEM VERSAGENDEN MATZ GEPROTZT HAT. WER WILL SCHON SO WAS HÖREN?', '', 28153),
(141441, 'deDE', 'NEE, VON EINEM SCHATZ WEISS ICH NICHTS.', '', 28153),
(141440, 'deDE', 'OHHHH. EIN VERGRABENER SCHATZ.', '', 28153),
(141439, 'deDE', '<Zeigt das Plakat.> Was wisst Ihr über diesen vergrabenen Schatz?', '<Zeigt das Plakat.> Was wisst Ihr über diesen vergrabenen Schatz?', 28153),
(141438, 'deDE', 'WAAAAS? IHR MÜSST EIN WENIG LAUTER SPRECHEN. ICH HÖR NICHT MEHR SO GUT, SEIT...$B$BDEM VORFALL.', '', 28153),
(141435, 'deDE', 'Hier kommt Peter!', '', 28153),
(141434, 'deDE', '', 'Immer schön lächeln! Man weiß nie, wann die Gäste einen beobachten. Vor allem die hinterlistigen Typen!', 28153),
(141433, 'deDE', '', 'Merkt Euch, wenn ein Gast eine Frage stellt und Ihr die Antwort nicht kennt, erfindet einfach etwas! Setzt gnomische Rafinesse ein!', 28153),
(141432, 'deDE', '', 'Na zeigt schon Eure Grübchen, Rekruten! Zeigt den Leuten, wie unheimlich niedlich wir Gnome sein können!', 28153),
(141431, 'deDE', 'Was?! Das ist unfair! DAS IST UNFAIR!', '', 28153),
(141430, 'deDE', '', 'Finn! Ich komme!', 28153),
(141429, 'deDE', 'Zehntausend Goldstücke für den, der mir ihre Köpfe bringt!', '', 28153),
(141428, 'deDE', 'Die Prachtmeers sind Geschichte! Und wenn Lady Aschenwind auf dem Thron sitzt, kommandier ich ihre Flotte!', '', 28153),
(141427, 'deDE', 'Das reicht! Ihr seid sowieso zu spät! Unser Angriff auf Daelins Tor ist in vollem Gang!', '', 28153),
(141426, 'deDE', 'Hrm! Die Würfel sind verflucht! Egal, greift sie euch!', '', 28153),
(141425, 'deDE', 'Harlan schüttet einen ganzen Beutel Würfel aus und erhält größtenteils Schätze.', 'Harlan schüttet einen ganzen Beutel Würfel aus und erhält größtenteils Schätze.', 28153),
(141424, 'deDE', 'Harlan würfelt neu und erhält eine Kanone und zwei Schädel.', 'Harlan würfelt neu und erhält eine Kanone und zwei Schädel.', 28153),
(141423, 'deDE', 'Harlan würfelt zwei Schätze und einen Kompass.', 'Harlan würfelt zwei Schätze und einen Kompass.', 28153),
(141422, 'deDE', 'Harlan würfelt drei Schwerter.', 'Harlan würfelt drei Schwerter.', 28153),
(141421, 'deDE', 'Schon besser! Hab ich erwähnt, dass ich nicht fair spiele? Haha!', '', 28153),
(141420, 'deDE', 'Was?! Nein, nein, nein, nein. So läuft das nicht.', '', 28153),
(141419, 'deDE', 'Mja! Bitte! Neue Runde, neues Glück!', '', 28153),
(141418, 'deDE', 'Ah, seht an, ein neues Gesicht! Hoffentlich seid Ihr etwas interessanter als der Rest.', '', 28153),
(141417, 'deDE', 'Ooooh! Vielleicht beim nächsten Mal, haha! Vierteilt sie!', '', 28153),
(141416, 'deDE', 'Hmm... was tun wir mit einem Haufen meuternder Ratten... Lassen wir doch die Würfel entscheiden!', '', 28153),
(141415, 'deDE', 'Hohoho! Unser neuster \"Rekrut\" ist da! Das wird ein Spaß!', '', 28153),
(141414, 'deDE', '', 'Mein Mann wird niemals aufhören, seine Arbeiter auszubeuten...', 28153),
(141413, 'deDE', 'Der Wind hat gedreht, Finn. Ich bin jetzt der Käpt\'n. Und sobald die Prachtmeers aus dem Weg sind, plündern wir Kul Tiras bis auf\'s letzte Goldstück!', '', 28153),
(141412, 'deDE', 'Nghh... lauft...', '', 28153),
(141411, 'deDE', 'Genau, Jungs! Dreht Ihn richtig durch die Mangel.', '', 28153),
(141410, 'deDE', '', 'Es ist Zeit, dass Ihr Euch aufmacht, über unsere ehrwürdigen Gipfel hinaus.', 28153),
(141409, 'deDE', '', 'Bisweilen waren wir gespalten. Bisweilen kamen wir von unserem Pfad ab. Doch die Geister unserer Ahnen erinnerten uns, dass Erde, Fluss und Himmel uns verbinden. Dass wir eine Familie sind und dafür lohnt es sich zu kämpfen.', 28153),
(141408, 'deDE', '', 'Diese Worte sprechen von mehr als Erde und Stein. Sie erzählen die Geschichte unseres Volkes, das Entbehrung und Konflikt trotzte, um sich gegen gemeinsame Feinde zu vereinen.', 28153),
(141407, 'deDE', '', 'Der Hochberg bleibt stark.', 28153),
(141406, 'deDE', '', 'Ihr seid $gein Narr:eine Närrin;, Euch mir in den Weg zu stellen!', 28153),
(141405, 'deDE', '', 'Silgryn! Valtrois! Eilt dem Lordregenten zu Hilfe!', 28153),
(141404, 'deDE', 'Genug! Wir müssen diese Verderbnis läutern, bevor der Brunnen verloren ist!', '', 28153),
(141403, 'deDE', '', 'Ich wollte mit meiner Anwesenheit nicht...', 28153),
(141402, 'deDE', 'Genau deshalb ließ ich Umbric und seine Fanatiker verbannen. Jeder, der sich mit den Mächten der Leere einlässt, ist eine Gefahr für den Sonnenbrunnen!', '', 28153),
(141401, 'deDE', 'Was geht hier vor?', '', 28153),
(141400, 'deDE', 'Zurück!', '', 28153),
(141399, 'deDE', '', 'Der Sonnenbrunnen ist nicht mehr derselbe... aber noch genauso schön. Es ist so lange her.', 28153),
(141398, 'deDE', '', 'Der Sonnenbrunnen wurde von unseren Feinden verderbt, aber das Opfer eines Naaru läuterte seine Wasser. Jetzt nährt uns die Essenz des Lichts.', 28153),
(141397, 'deDE', '', 'Die Macht ist förmlich in der Luft zu spüren. So stark wie der Nachtbrunnen, aber auf andere Weise.', 28153),
(141396, 'deDE', 'Bitte folgt mir.', '', 28153),
(141395, 'deDE', 'Rommath, bitte öffnet uns den Weg.', '', 28153),
(141394, 'deDE', '', 'Es wäre mir eine Ehre, den Sonnenbrunnen zu sehen, Lor\'themar. Meine Freunde nennen mich übrigens Thalyssra.', 28153),
(141393, 'deDE', 'Alleria ist eine Tochter von Quel\'Thalas. Ich werde ihr die Pilgerschaft zu unserer heiligsten Stätte nicht verweigern. Erste Arkanistin, ich lade Euch und Eure Gefolgschaft herzlich ein, uns zu begleiten.', '', 28153),
(141392, 'deDE', 'Ich rate davon ab. Wir können nicht sicher sein, was sie im Schilde...', '', 28153),
(141391, 'deDE', '', 'Es ist tausend Jahre her, seit ich den Sonnenbrunnen gesehen habe. Erlaubt Ihr mir, ihn erneut zu besuchen?', 28153),
(141389, 'deDE', '', 'Es scheint, als hättet Ihr mein Angebot erwartet... und verschmäht. Nun gut. Doch bevor ich gehe, habe ich eine Bitte.', 28153),
(141388, 'deDE', 'Ihr zweifelt an meinen Worten, doch wie können wir den Euren trauen? Streitet Ihr ab, dass die Fürsten der Leere Euch zuraunen? Habt Ihr Euch etwa nicht auf Argus den Schatten ergeben?', '', 28153),
(141387, 'deDE', '', 'Scharfe Worte, Lor\'themar. Sind es die Eurigen oder ist der aufrechte Waldläufer, den ich einst kannte, jetzt das Sprachrohr Eures Kriegshäuptlings?', 28153),
(141384, 'deDE', 'Ich hatte gehofft, Euer Besuch wäre aus Liebe zu Silbermond geschehen. Stattdessen kommt Ihr im Namen des Kindkönigs der Allianz. Wie enttäuschend.', '', 28153),
(141383, 'deDE', '', 'Wie Ihr wünscht. Ich komme mit einem Angebot von Hochkönig Anduin Wr–', 28153),
(141382, 'deDE', 'Unsinn. Was immer Ihr zu sagen habt, könnt Ihr ruhig vor unseren Gästen sagen.', '', 28153),
(141381, 'deDE', '', 'Es war nicht meine Absicht, Euren Besuch zu stören, Erste Arkanistin. Vielleicht sollte ich ein andermal wiederkommen.', 28153),
(141380, 'deDE', '', 'Eine unerwartete Ehre, Lady Windläufer. Silgryn berichtete mir von Euren Heldentaten während des Feldzugs auf Argus.', 28153),
(141379, 'deDE', 'Bitte, nennt mich Lor\'themar. Erlaubt mir, Euch einen weiteren Gast vorzustellen: Lady Alleria Windläufer, eine Heldin aus Silbermonds Vergangenheit.', '', 28153),
(141376, 'deDE', '', 'Ich freue mich, endlich Eure prächtige Stadt zu sehen. Ich danke Euch für Eure Einladung, Lordregent.', 28153),
(141375, 'deDE', '', 'Erste Arkanistin Thalyssra und verehrte Gäste. Willkommen in Silbermond.', 28153),
(141374, 'deDE', 'Ich sehe keinen Grund für Geheimnisse vor unseren Verbündeten, Alleria. Tatsächlich treffen gerade unsere neuesten Freunde ein.', '', 28153),
(141373, 'deDE', '', 'Schön Euch wiederzusehen, Liadrin. Champion. Lor\'themar, ich komme in einer Angelegenheit, die wir besser unter vier Augen besprechen.', 28153),
(141372, 'deDE', 'Lady Liadrin... Champion. Ihr seid höchst willkommen. Wie Ihr seht, haben wir einen unerwarteten Besucher.', '', 28153),
(141371, 'deDE', '', 'Wie Ihr befehlt, Kriegshäuptling. Ich werde Euch in Lady Thalyssras Anwesen in Suramar treffen, $p.', 28153),
(141370, 'deDE', '', 'Ich verlasse mich auf Euch beide. Kehrt nicht zurück, bis sich Suramar der Horde verschworen hat.', 28153),
(141369, 'deDE', '', 'Der Lordregent hat die Nachtgeborenen nach Silbermond eingeladen. Ich breche auf nach Suramar und eskortiere Lady Thalyssra zu dem Treffen.', 28153),
(141366, 'deDE', '', 'Um die Zukunft unseres Volkes zu gewährleisten, müsst Ihr helfen, unseren Platz in Azeroth zu sichern.', 28153),
(141365, 'deDE', '', 'Unsere Anführer verrieten uns, schlossen einen Handel mit den Dämonen. Doch wir erhoben uns gegen die Tyrannei... und verjagten die Teufel. Suramar gehört einmal mehr uns... und wir werden es niemals wieder der Finsternis aushändigen.', 28153),
(141364, 'deDE', '', 'Mit den Jahrhunderten veränderte sich Azeroth um uns... und fiel in die Klauen der Legion.', 28153),
(141363, 'deDE', '', 'Zehntausend Jahre lang war Suramar die einzige Welt, die wir kannten.', 28153),
(141362, 'deDE', '', 'Ihr seid lichtgeschmiedet. Ihr müsst die Fackel der Hoffnung im Angesicht der Dunkelheit sein.', 28153),
(141361, 'deDE', '', 'Nach all dieser Zeit ist unser Feind gefallen. Die Legion ist nicht mehr. Doch unser Krieg ist lange nicht vorbei. Neue Bedrohungen lauern in den Schatten und warten nur auf den richtigen Moment.', 28153),
(141360, 'deDE', '', 'Über Jahrtausende des Kampfes hat das Licht uns auf den wahren Pfad geführt...', 28153),
(141359, 'deDE', '', 'Wir sind Soldaten.', 28153),
(141358, 'deDE', '', 'Die Leere hat uns geformt... uns verändert. Doch Ihr werdet sie meistern.', 28153),
(141357, 'deDE', '', 'Doch wir haben verstanden, was sie nicht begreifen.', 28153),
(141356, 'deDE', '', 'Weise und Gelehrte fürchten die Leere.', 28153),
(141355, 'deDE', '', 'Die Leere. Eine Kraft von unendlichem Hunger.', 28153),
(141354, 'deDE', '', 'Ich geh zum Boot. Trefft mich dort.', 28153),
(141353, 'deDE', 'Möge Bwonsamdi Euch segn\'n.', '', 28153),
(141352, 'deDE', '', 'Die Goblins hab\'n mir versichert, dass dieser Plan funktionier\'n wird... Und Ihr seid hier, um sicherzustell\'n, dass er das auch tut.$B$BSeid Ihr bereit für \'ne Spritztour auf dem Fluss?', 28153),
(141351, 'deDE', 'Unser Champion, der bei den Fischen schläft... im wahrsten Sinne des Wortes! Der Vollstrecker von Freihafen... der Virtuose der fliegenden Fäuste... Trothak der Haidrescher!', '', 28153),
(141350, 'deDE', 'Unglaublich! Diese Süßwassermatrosen haben es geschafft, Gryff und Stevin zu besiegen! Jetzt bleibt nur noch ein Gegner, und der braucht keine Ankündigung.', '', 28153),
(141349, 'deDE', 'Das Federvieh und sein Flusspferd... zwei Himmelhunde auf dem Weg zur Hölle... das zerstörerischste Zweiergespann seit Millificent und Millhaus... Ring frei für: Gryff und Stevin!', '', 28153),
(141348, 'deDE', 'Und jetzt Applaus für das dynamische Duo von jenseits des Meeres. Zwei, wie es sie kein zweites Mal gibt, und ein Wirklichkeit gewordener Albtraum selbst für hartgesottene Kämpfer.', '', 28153),
(141347, 'deDE', 'Leiden sollt Ihr!', '', 28153),
(141345, 'deDE', 'Hier kommt Ihr niemals wieder fort!', '', 28153),
(141344, 'deDE', 'Ludwig geht zu Boden! Was für ein Kampf! Diese dahergelaufenen Seeräuber sind nicht unterzukriegen, aber wird ihnen das etwas nutzen? Denn ihr nächster Gegner ist der Inbegriff roher Gewalt.', '', 28153),
(141343, 'deDE', 'Rettet... Euch...', '', 28153),
(141342, 'deDE', '', 'Verfluchtes Kind! Bwonsamdi hat mir im Austausch gegen deine Seele ewiges Leben versproch\'n! Du machst alles kaputt!', 28153),
(141341, 'deDE', 'Aus der Kanalisation von Freihafen kommt ein Tortollaner, an dem sich so mancher Gegner schon die Zähne ausgebissen hat. Der gepanzerte Gladiator... der schildbewehrte Schläger... der zäheste Brocken diesseits von Kalimdor: Ludwig!', '', 28153),
(141340, 'deDE', 'Schau einer an, sie haben ein Schwein gefangen. Vielleicht kommt jetzt mal eine echte Herausforderung.', '', 28153),
(141334, 'deDE', '', 'Ihr habt noch nie vom Schattenzahnklan gehört? Kein Wunder, der Stamm wurde ja auch vom Schattenhammer ausgelöscht.\n\nDie Zandalari behalt\'n eine Repräsentantin hier, als Erinnerung an die Vergangenheit. Nun bin ich nichts weiter als \'ne Kuriosität.\n\nEs is\' gar nich\' so übel. Ich musste noch keines meiner Getränke selbst bezahl\'n.', 28153),
(141332, 'deDE', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 28153),
(141331, 'deDE', 'Die Zandalari ham früher über alle Trolle geherrscht. Jetzt könn\' sie nich\' mal ihre Grenzen sichern.', 'Die Zandalari ham früher über alle Trolle geherrscht. Jetzt könn\' sie nich\' mal ihre Grenzen sichern.', 28153),
(141330, 'deDE', 'Die Zandalari ham Blutmagie über ihre Grenzen gelass\'n. Is\' nur \'ne Frage der Zeit, bis sie vernichtet werd\'n.', 'Die Zandalari ham Blutmagie über ihre Grenzen gelass\'n. Is\' nur \'ne Frage der Zeit, bis sie vernichtet werd\'n.', 28153),
(141329, 'deDE', 'Die Zandalari schick\'n alle, die Ärger mach\'n, in die Wüste. Von da kommt niemand zurück.', 'Die Zandalari schick\'n alle, die Ärger mach\'n, in die Wüste. Von da kommt niemand zurück.', 28153),
(141328, 'deDE', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 28153),
(141327, 'deDE', 'Ihr seht lecka aus.', 'Ihr seht lecka aus.', 28153),
(141326, 'deDE', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 28153),
(141325, 'deDE', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 28153),
(141324, 'deDE', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 28153),
(141323, 'deDE', 'Die Zandalari ham früher über alle Trolle geherrscht. Jetzt könn\' sie nich\' mal ihre Grenzen sichern.', 'Die Zandalari ham früher über alle Trolle geherrscht. Jetzt könn\' sie nich\' mal ihre Grenzen sichern.', 28153),
(141322, 'deDE', 'Wir sollt\'n die Horde einfach töt\'n und gut is\'.', 'Wir sollt\'n die Horde einfach töt\'n und gut is\'.', 28153),
(141321, 'deDE', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', '', 28153),
(141320, 'deDE', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', '', 28153),
(141319, 'deDE', 'Mit König Rastakhan muss es bergab geh\'n, wenn er die Horde nach Zandalar reinlässt, ohne sich ihre Köpfe zu hol\'n.', '', 28153),
(141318, 'deDE', 'Die Horde hat \'nen neuen Kriegshäuptling. Soll so ein kleiner schwächlicher Elfling sein.', '', 28153),
(141316, 'deDE', 'Dies is\' der einzige Ort, an dem sich so viele Stämme treff\'n könn\', ohne dass Köpfe roll\'n. Sobald die Wächter weg sin\', sieht das aber ganz anders aus.', '', 28153),
(141313, 'deDE', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 28153),
(141312, 'deDE', 'Die Dunkelspeere ham ihr eignes Volk verrat\'n. Sie hätt\'n sich niemals der Horde anschließ\'n soll\'n.', 'Die Dunkelspeere ham ihr eignes Volk verrat\'n. Sie hätt\'n sich niemals der Horde anschließ\'n soll\'n.', 28153),
(141311, 'deDE', 'Die Horde hat \'nen neuen Kriegshäuptling. Soll so ein kleiner schwächlicher Elfling sein.', 'Die Horde hat \'nen neuen Kriegshäuptling. Soll so ein kleiner schwächlicher Elfling sein.', 28153),
(141310, 'deDE', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 28153),
(141309, 'deDE', 'Das is\' nix im Vergleich zu unsren Dschungeln zu Hause. Wir ham viel größ\'re Dinos.', 'Das is\' nix im Vergleich zu unsren Dschungeln zu Hause. Wir ham viel größ\'re Dinos.', 28153),
(141308, 'deDE', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 28153),
(141307, 'deDE', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 28153),
(141306, 'deDE', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 28153),
(141304, 'deDE', 'Die Zandalari ham Blutmagie über ihre Grenzen gelass\'n. Is\' nur \'ne Frage der Zeit, bis sie vernichtet werd\'n.', 'Die Zandalari ham Blutmagie über ihre Grenzen gelass\'n. Is\' nur \'ne Frage der Zeit, bis sie vernichtet werd\'n.', 28153),
(141303, 'deDE', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 28153),
(141302, 'deDE', 'Hab gehört, der König weiß noch nich\' mal, was in seiner eignen Stadt passiert. Wie soll er da so \'ne Situation unter Kontrolle krieg\'n?', 'Hab gehört, der König weiß noch nich\' mal, was in seiner eignen Stadt passiert. Wie soll er da so \'ne Situation unter Kontrolle krieg\'n?', 28153),
(141301, 'deDE', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 28153),
(141300, 'deDE', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 28153),
(141299, 'deDE', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 28153),
(141298, 'deDE', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 28153),
(141297, 'deDE', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 28153),
(141296, 'deDE', 'Mit König Rastakhan muss es bergab geh\'n, wenn er die Horde nach Zandalar reinlässt, ohne sich ihre Köpfe zu hol\'n.', 'Mit König Rastakhan muss es bergab geh\'n, wenn er die Horde nach Zandalar reinlässt, ohne sich ihre Köpfe zu hol\'n.', 28153),
(141295, 'deDE', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 28153),
(141294, 'deDE', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 28153),
(141293, 'deDE', 'Die Horde? Pah! Die is\' nich\' mal so viel Wert wie \'n Haufen Terrorhorndung.', 'Die Horde? Pah! Die is\' nich\' mal so viel Wert wie \'n Haufen Terrorhorndung.', 28153),
(141292, 'deDE', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 28153),
(141291, 'deDE', 'Die Zandalari sag\'n immer, wie sehr sie die Untoten hass\'n, aber sie katzbuckeln trotzdem ganz schön vor dem neuen Kriegshäuptling.', 'Die Zandalari sag\'n immer, wie sehr sie die Untoten hass\'n, aber sie katzbuckeln trotzdem ganz schön vor dem neuen Kriegshäuptling.', 28153),
(141290, 'deDE', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 28153),
(141289, 'deDE', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 28153),
(141288, 'deDE', 'Die Zandalari glaub\'n, sie wär\'n besser als die andren Stämme. Sie hab\'n nich\' mehr viel Zeit, dies\'n Irrtum einzuseh\'n.', 'Die Zandalari glaub\'n, sie wär\'n besser als die andren Stämme. Sie hab\'n nich\' mehr viel Zeit, dies\'n Irrtum einzuseh\'n.', 28153),
(141287, 'deDE', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 'Die Zandalari war\'n früher der stolzeste Stamm. Jetzt is\' Stolz das Einzige, was diesen Ort zusammenhält.', 28153),
(141286, 'deDE', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 'Ich hass die Elf\'n. Und ich hass die Untot\'n. Und in der Horde sind beide.', 28153),
(141285, 'deDE', 'Dies is\' der einzige Ort, an dem sich so viele Stämme treff\'n könn\', ohne dass Köpfe roll\'n. Sobald die Wächter weg sin\', sieht das aber ganz anders aus.', 'Dies is\' der einzige Ort, an dem sich so viele Stämme treff\'n könn\', ohne dass Köpfe roll\'n. Sobald die Wächter weg sin\', sieht das aber ganz anders aus.', 28153),
(141284, 'deDE', 'Die Tage der Horde sin\' gezählt. Das könnt Ihr mir glaub\'n.', 'Die Tage der Horde sin\' gezählt. Das könnt Ihr mir glaub\'n.', 28153),
(141283, 'deDE', 'Die Zandalari sag\'n immer, wie sehr sie die Untoten hass\'n, aber sie katzbuckeln trotzdem ganz schön vor dem neuen Kriegshäuptling.', 'Die Zandalari sag\'n immer, wie sehr sie die Untoten hass\'n, aber sie katzbuckeln trotzdem ganz schön vor dem neuen Kriegshäuptling.', 28153),
(141282, 'deDE', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 'Zu viele red\'n. Zu viele hör\'n nich\' zu.', 28153),
(141281, 'deDE', 'Was soll\'n all diese Stufen in dieser Stadt?', 'Was soll\'n all diese Stufen in dieser Stadt?', 28153),
(141280, 'deDE', 'Die Zandalari schick\'n alle, die Ärger mach\'n, in die Wüste. Von da kommt niemand zurück.', 'Die Zandalari schick\'n alle, die Ärger mach\'n, in die Wüste. Von da kommt niemand zurück.', 28153),
(141279, 'deDE', 'Die Bruchhauer erinnern sich an die Hilfe der Horde. Wir sin\' bereit, die Schuld zu begleich\'n.', 'Die Bruchhauer erinnern sich an die Hilfe der Horde. Wir sin\' bereit, die Schuld zu begleich\'n.', 28153),
(141278, 'deDE', 'Wir sin\' weit weg vom Hinterland, aber Ihr sollt wiss\'n, dass die Bruchhauer schon immer Freunde der Horde war\'n.', 'Wir sin\' weit weg vom Hinterland, aber Ihr sollt wiss\'n, dass die Bruchhauer schon immer Freunde der Horde war\'n.', 28153),
(141277, 'deDE', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 'Die Zandalari könn\' sich nich\' mehr vor der Welt versteck\'n. Ihre Zeit geht zu Ende.', 28153),
(141276, 'deDE', 'Ein eingefettetes Schwein? Ich bekomme den Eindruck, hier sind Amateure am Werk. Also gut... schnappt Euch das Schweinchen und Ihr habt gewonnen.', '', 28153),
(141275, 'deDE', 'Und in der anderen Ecke: der überragende... der unglaubliche... der unübertroffene... äh, Moment, was? Ist das Euer Ernst?', '', 28153),
(141274, 'deDE', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 'Seid auf der Hut. Hier habter schneller \'n Messer im Rücken, als Euch lieb is\'.', 28153),
(141273, 'deDE', 'Die Horde hat \'nen neuen Kriegshäuptling. Soll so ein kleiner schwächlicher Elfling sein.', 'Die Horde hat \'nen neuen Kriegshäuptling. Soll so ein kleiner schwächlicher Elfling sein.', 28153),
(141272, 'deDE', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 'Die gold\'ne Flotte is\' die eigentliche Macht der Zandalari. Wer diese Flotte kontrolliert, hat auch die Macht.', 28153),
(141271, 'deDE', 'Mit König Rastakhan muss es bergab geh\'n, wenn er die Horde nach Zandalar reinlässt, ohne sich ihre Köpfe zu hol\'n.', 'Mit König Rastakhan muss es bergab geh\'n, wenn er die Horde nach Zandalar reinlässt, ohne sich ihre Köpfe zu hol\'n.', 28153),
(141266, 'deDE', 'Autsch! Okay, okay! Heute in der Arena: Ein Kampf, der seinesgleichen sucht! In der einen Ecke: Geheimnisvoll... gemeingefährlich... und etwas heruntergekommen: eine Bande dahergelaufener Seeräuber!', '', 28153),
(141265, 'deDE', 'Na los, macht schon! Macht Euer Ding!', '', 28153),
(141263, 'deDE', 'Aua! Was soll das Piksen? Oh, oh! Aufwachen, Wodin! Wir sind dran!', '', 28153),
(141262, 'deDE', 'Ihr seid dran, Landratten!', '', 28153),
(141261, 'deDE', 'Schließt Eure Wetten ab! Wir haben Frischflei.... äh, neue Herausforderer! Und nun Applaus für: Gurgthock und Wodin!', '', 28153),
(141260, 'deDE', 'Ein Kampf? Immer gern!', 'Ein Kampf? Immer gern!', 28153),
(141259, 'deDE', 'Willkommen im Ring der Beute, Ihr Leichtmatrosen. Habt Ihr den Mut, es mit diesen kampfgestählten Raufbolden aufzunehmen?', '', 28153),
(141250, 'deDE', 'Die Horde? Pah! Die is\' nich\' mal so viel Wert wie \'n Haufen Terrorhorndung.', 'Die Horde? Pah! Die is\' nich\' mal so viel Wert wie \'n Haufen Terrorhorndung.', 28153),
(141249, 'deDE', '', 'Ich lasse mich von keinem Zirkel maßregeln!', 28153),
(141248, 'deDE', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 'Die Zandalari glaub\'n, dass sie besser sin\' als andere. Dabei sin\' sie nur aussterbende Relikte.', 28153),
(141247, 'deDE', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 'Könnt Ihr glaub\'n, dass die Horde \'ner kleinen toten Elfe als Kriegshäuptling folgt? Echt schwach.', 28153),
(141246, 'deDE', 'Die Dunkelspeere ham die Trolle verrat\'n. Sie hätt\'n sich niemals der Horde anschließ\'n soll\'n.', 'Die Dunkelspeere ham die Trolle verrat\'n. Sie hätt\'n sich niemals der Horde anschließ\'n soll\'n.', 28153),
(141245, 'deDE', '', 'Ihr habt alles... zunichtegemacht...', 28153),
(141244, 'deDE', '', 'Ungebührlich! Schwach! Ich?!', 28153),
(141243, 'deDE', '', 'Sie werden sich winden und schreien, wenn ich sie aufreiße und ihre Eingeweide verschlinge!', 28153),
(141238, 'deDE', '', 'Verstanden. Wir werden Euch nicht alleine gehen lassen.', 28153),
(141235, 'deDE', 'Ihr hört ein kratzendes Geräusch am Stein.', 'Ihr hört ein kratzendes Geräusch am Stein.', 28153),
(141233, 'deDE', 'Die verfluchte Verseuchung blockiert den Weg. Unsere Truppen können ihr nicht folgen.', '', 28153),
(141232, 'deDE', 'Salbe herstellen', 'Salbe herstellen', 28153),
(141221, 'deDE', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 'Hab gehört, dass es König Rastakhan nich\' so gut geht. Is\' wohl nur \'ne Frage der Zeit, bis ganz Zandalar fällt. Und was wird dann aus uns?', 28153),
(141213, 'deDE', 'Die Wildtiere von Vol\'dun müssen frei bleiben.', '', 28153),
(141212, 'deDE', '', 'Lasst mich Euer Herz verspeisen!', 28153),
(141211, 'deDE', 'Was ist los?', 'Was ist los?', 28153),
(141210, 'deDE', 'Könnte ich etwas tun, um zu helfen?', 'Könnte ich etwas tun, um zu helfen?', 28153),
(141209, 'deDE', 'Was ist geschehen?', 'Was ist geschehen?', 28153),
(141208, 'deDE', 'Warum weint Ihr?', 'Warum weint Ihr?', 28153),
(141207, 'deDE', 'Aye aye! Brief ist im Handumdrehen da! Volle Kraft voraus, Schätzchen!', '', 28153),
(141206, 'deDE', 'Könnt Ihr diesen Brief Taelia in Boralus zustellen?', 'Könnt Ihr diesen Brief Taelia in Boralus zustellen?', 28153),
(141205, 'deDE', 'Die Geschichte geht weiter...\n\nDanke für Eure Teilnahme an der BlizzCon!', '', 28153),
(141204, 'deDE', 'Kommt Ihr, um zu spott\'n? Kommt Ihr, um Euch über den Sprecher eines untergegangenen Reichs lustig zu mach\'n?$b$bJeder Troll von Zul\'Drak, der nich\' der Geißel anheimfiel, wurde von ihr gebroch\'n. Den Tod vor Augen tötet\'n die Verbleibenden meines Volks unsere Loa und stahl\'n die Macht dieser Götter, um sie gegen die Geißel einzusetz\'n. Aber dann starb\'n auch sie.$b$bUnd hier steh ich nun, kaum mehr als ein Schoßhund für die Zandalari. Eine Kuriosität, die sie hervorhol\'n, um ihren Kindern was Exotisches zu zeig\'n.$b$bLasst mich in Ruhe.', '', 28153),
(141202, 'deDE', '', 'Die Zurückweisung des Zirkels hat mir die Seele herausgerissen. Jetzt nehme ich mir Eure!', 28153),
(141201, 'deDE', '', 'Es... gibt eine Sache, die helfen könnte...', 28153),
(141200, 'deDE', '', 'Wir... hätten so eine wundervolle Zukunft zusammen haben können, aber sie wurde uns genommen.', 28153),
(141199, 'deDE', '', 'Ich hätte es mir denken können, als sie an die Tür klopften. Sie kommen nie vorbei, um gute Nachrichten zu bringen.\n\nDa wusste ich schon, dass der Traum vorbei war.', 28153),
(141198, 'deDE', '', 'So ein... Verlust... \n\nIch hätte nicht gedacht, dass es so wehtun könnte...', 28153),
(141197, 'deDE', 'Ihr da! Hier drüben!', '', 28153),
(141196, 'deDE', '<Die Frau weint. Ihr reicht ihr zum Trost Eure Hand.>', '<Die Frau weint. Ihr reicht ihr zum Trost Eure Hand.>', 28153),
(141194, 'deDE', 'Möchtet Ihr Euch wirklich zum Dungeon Atal\'Dazar teleportieren?', 'Möchtet Ihr Euch wirklich zum Dungeon Atal\'Dazar teleportieren?', 28153),
(141193, 'deDE', 'Möchtet Ihr Euch wirklich zum Dungeon Freihafen teleportieren?', 'Möchtet Ihr Euch wirklich zum Dungeon Freihafen teleportieren?', 28153),
(141192, 'deDE', 'Zum Dungeon Atal\'Dazar teleportieren', 'Nach Atal\'Dazar teleportieren', 28153),
(141191, 'deDE', 'Zum Dungeon Freihafen teleportieren', 'Nach Freihafen teleportieren', 28153),
(141190, 'deDE', 'Willkommen zur BlizzCon 2017! Bitte klickt unten, wenn Ihr Euch zum Dungeon für Eure Fraktion teleportieren möchtet.', 'Willkommen zur BlizzCon 2017! Bitte klickt unten, wenn Ihr Euch zum Dungeon für Eure Fraktion teleportieren möchtet.', 28153),
(141189, 'deDE', '', 'Aus mein\'n Augen! Und kehrt nich\' zurück, bevor Ihr Euch nicht als würdig erwies\'n habt!', 28153),
(141188, 'deDE', 'Tut mir leid! Ich wollte ihm helfen, aber ich bin kein Kämpfer!', '', 28153),
(141187, 'deDE', '', 'Ihr könnt nich\' aufhalt\'n, was kommt. Keine Hoffnung für Zuldazar. Keine Hoffnung für Euch. G\'huun kommt. G\'huun erwacht.', 28153),
(141186, 'deDE', '', 'Ihr habt UNSERN Loa getötet... wir werd\'n Euch jagen... Euch foltern... Euer Blut is\' unser!', 28153),
(141185, 'deDE', '', 'Hir\'eek war ein Diener von G\'huun! Dafür werdet Ihr bezahl\'n. Zuerst wird Zuldazar fallen... und dann die Horde!', 28153),
(141184, 'deDE', '<Rakjan senkt respektvoll den Kopf.>', '', 28153),
(141183, 'deDE', 'Reiten wir.', 'Reiten wir.', 28153),
(141182, 'deDE', '<Rakjan senkt respektvoll den Kopf.>', '', 28153),
(141180, 'deDE', 'Lebt wohl, Narr!', '', 28153),
(141178, 'deDE', 'Ich schätze, ich sollte für eine Weile untertauchen...', '', 28153),
(141177, 'deDE', 'Eine Schande, dass die Schildkröte nicht selbst gekommen ist. Sein Panzer wäre einiges wert gewesen.', '', 28153),
(141176, 'deDE', 'Ich rekrutiere gerade Tauren für eine Illidari-Gruppe. Wir nennen uns die Dä-muh-nenjäger.', '', 28153),
(141175, 'deDE', 'Die Vindikaar ist ein schnelles Schiff. Man könnte sagen, sie erreicht Lichtgeschwindigkeit.', '', 28153),
(141174, 'deDE', '', 'Wir stehen für den Hochberg... Und manchmal stehen wir auf dem Hochberg, unter dem Hochberg, neben dem Hochberg und ab und zu sogar mal im Hochberg.', 28153),
(141173, 'deDE', '', 'Habt Ihr Velens neuen Tanz gesehen? Er nennt ihn den Mac\'Areena.', 28153),
(141172, 'deDE', '', 'Hmpf. Hat wohl <hicks!> die Kurve gekratzt.', 28153),
(141171, 'deDE', '', 'Wo ist dieser feige Abschaum, der da <hicks> die Eisenfluträuber beleidigt?!', 28153),
(141170, 'deDE', '', 'Was?! <Hicks!> Ich werd\' sie lehren, MEINE Besatzung schlecht zu machen!', 28153),
(141169, 'deDE', 'Yarr! So ein lachsgehackter Scharlatan zieht den guten Namen der Eisenfluträuber in den Dreck! Gleich da drüben, hinter dem Gebäude!', 'Yarr! So ein lachsgehackter Scharlatan zieht den guten Namen der Eisenfluträuber in den Dreck! Gleich da drüben, hinter dem Gebäude!', 28153),
(141168, 'deDE', 'Was? Die Alte sollte längst tot sein und ihre Seele ausgehaucht hab\'n! Na los, los! Tötet sie noch mal, und diesmal \'n bisschen gründlicher. Ich nehm\' mir, was mir gehört.', '', 28153),
(141167, 'deDE', '', '<Hicks>$B$BJa? Was willze?', 28153),
(141166, 'deDE', 'Ihr habt WAS gemacht?! Ihr könnt doch nich\'... Ihr DÜRFT keine Loa umbring\'n!', '', 28153),
(141165, 'deDE', 'Jo\'chunga lebt, aber der Loa Hir\'eek...', 'Jo\'chunga lebt, aber der Loa Hir\'eek...', 28153),
(141164, 'deDE', 'Da seid Ihr ja! Ich hab mir schon langsam Sorgen gemacht. Was is\' passiert?', '', 28153),
(141163, 'deDE', 'Draenei bei Tag... aber Eredar bei Nacht, Baby.', '', 28153),
(141162, 'deDE', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t Achtung, |cFFF00000|Hspell:257585|h[Kanonensperrfeuer]|h|r!', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t Achtung, |cFFF00000|Hspell:257585|h[Kanonensperrfeuer]|h|r!', 28153),
(141159, 'deDE', 'Vorsicht, es wird hell... und ganz schön heiß.', '', 28153),
(141158, 'deDE', 'Geistwandler?!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141157, 'deDE', 'Gesichtstentakel?! Natürlich haben wir KEINE Gesichtstentakel! Hätten wir welche, wären die Draenei geheime Boten der Leere, die sich Euer Vertrauen erschleichen und Eure Gesellschaft infiltrieren, um Euch ein Ende zu bereiten. Sicher war es nicht DAS, was Ihr andeuten wolltet, oder?', '', 28153),
(141156, 'deDE', 'Hm, meine Tättowierungen leuchten recht schwach. Vielleicht sollte ich mal die Batterien wechseln.', '', 28153),
(141155, 'deDE', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan setzt seine |cFFFF0000|Hspell:255371|h[Furchterregende Fratze]|h|r ein. Versteckt Euch!', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan setzt seine |cFFFF0000|Hspell:255371|h[Furchterregende Fratze]|h|r ein. Versteckt Euch!', 28153),
(141154, 'deDE', '', 'Meister... gewährt mir Eure Gabe...', 28153),
(141153, 'deDE', '', 'Ihr kriegt einen Stein von mir ab! Wartet nur!', 28153),
(141152, 'deDE', '', 'Bleibt weg von mir, stinkende Troggs!', 28153),
(141149, 'deDE', '', 'Haltet die Jungen von Rakjan fern!', 28153),
(141147, 'deDE', '', 'Entschuldigt bitte! Könntet Ihr mir vielleicht mal helfen?', 28153),
(141144, 'deDE', '', 'Lasst die Jungen nicht entwischen!', 28153),
(141143, 'deDE', 'He! Hier drüben! Heda! Heeeee!', '', 28153),
(141142, 'deDE', 'Ein verletzter Pterrordax hält inne, um sich von seinen Verletzungen zu erholen.', '', 28153),
(141140, 'deDE', '', 'Schaut! Es ist vollbracht! Oh, wie wundervoll! Und wie tödlich!', 28153),
(141139, 'deDE', '', 'All diese... MACHT! HAHAHAHAHA!', 28153),
(141138, 'deDE', 'Interessant... Sie nutzen diese Spitzen als Transportmittel. Heute habe ich schon viel gelernt.', '', 28153),
(141137, 'deDE', 'Öh, Boss? $n? Ich glaube, wir haben ein neues Schlangenproblem.', '', 28153),
(141136, 'deDE', '<Rakjan erhebt voller Stolz sein Haupt.>', '', 28153),
(141135, 'deDE', '', 'Dass ich im Licht geschmiedet bin, heißt nicht, dass ich im Dunkeln keinen Spaß haben kann.', 28153),
(141134, 'deDE', '', 'Es ist wirklich hilfreich, wenn man im Dunkeln leuchtet. Wenn jemand den Weg nach Süden nicht findet... *räusper*', 28153),
(141133, 'deDE', '', 'Soll ich Euch mal zeigen, warum man es Almauftrieb nennt?', 28153),
(141132, 'deDE', '', 'Ein Leben in den Bergen wirkt Wunder, was die Ausdauer betrifft. Darf ich Euch das mal demonstrieren?', 28153),
(141131, 'deDE', '', 'Ich kenne Ethel. Eigentlich ist sie ziemlich flink, aber sie findet es lustig, Touristen zu veräppeln.', 28153),
(141130, 'deDE', 'Die ruhelosen Knochen erheben sich als reanimierter Raptor!', 'Die ruhelosen Knochen erheben sich als reanimierter Raptor!', 28153),
(141129, 'deDE', 'In einem nahen Knochenhaufen rührt sich etwas.', 'In einem nahen Knochenhaufen rührt sich etwas.', 28153),
(141127, 'deDE', 'Die Prinzessin is\' die Zukunft von Zandalar. Sie muss beschützt werd\'n.', 'Die Prinzessin is\' die Zukunft von Zandalar. Sie muss beschützt werd\'n.', 28153),
(141125, 'deDE', 'Wir dien\' der Prinzessin!', 'Wir dien\' der Prinzessin!', 28153),
(141124, 'deDE', 'Was wollt Ihr von mir?', 'Was wollt Ihr von mir?', 28153),
(141123, 'deDE', 'Die Bäume sind zum Leben erwacht! Ergreift Eure Äxte!', '', 28153),
(141122, 'deDE', 'T\'paartos!', '', 28153),
(141121, 'deDE', '', 'Lasst die Prüfung beginnen. Das Licht sei mit Euch.', 28153),
(141120, 'deDE', '', 'Eine unorthodoxe Wahl, aber... nicht regelwidrig. Ich habe nie erlebt, dass $p vor einer Herausforderung zurückschreckt.', 28153),
(141119, 'deDE', 'Wie Ihr wünscht! T\'paartos wählt... den Mickrigen dort!', '', 28153),
(141118, 'deDE', '', 'Der letzte Initiand, der die Prüfung allein beschritt, kam in Stücken zurück. Wählt einen Zweiten oder kehrt zur Kaserne zurück.', 28153),
(141117, 'deDE', 'T\'paartos braucht niemandes Hilfe!', '', 28153),
(141116, 'deDE', '', 'T\'paartos... wir hatten darüber gesprochen. Jeder Initiand muss von einem Zweiten begleitet werden. Wo ist Euer Partner?', 28153),
(141115, 'deDE', '', 'Doch solltet Ihr wahrhaft bereit sein, dann schreitet voran und begrüßt Euer Schicksal.', 28153),
(141114, 'deDE', '', 'Wenn Ihr nur den Hauch eines Zweifels verspürt, macht kehrt. Damit zeigt Ihr Weisheit, nicht Feigheit.', 28153),
(141113, 'deDE', '', 'Viele Draenei haben sich dieser Prüfung unterzogen... und waren seither gebrochen... oder Schlimmeres.', 28153),
(141112, 'deDE', '', 'Sie wird Euch zwingen, bis in den Kern Eures Wesens einzudringen. Dessen, was Ihr glaubt zu sein.', 28153),
(141111, 'deDE', '', 'Eine letzte Prüfung steht noch bevor – und diese wird Euch alles abverlangen.', 28153),
(141110, 'deDE', '', 'Meine Mitstreiter, die Prüfungen, die Ihr bestritten habt, sind Beweis für das Licht, das hell in Euren Herzen strahlt.', 28153),
(141109, 'deDE', '<Die Troggs scheinen ihn ausgeleert zu haben.>', '', 28153),
(141108, 'deDE', '<Sucht weiter nach den Kindern.>', '<Sucht weiter nach den Kindern.>', 28153),
(141107, 'deDE', 'Ich glaube, dass $n ein wenig mehr Erfahrung mit diesen Dingen hat als Ihr, Ingrid.', '', 28153),
(141106, 'deDE', '', 'Das ist nicht gerecht! Ich wollte das machen!', 28153),
(141100, 'deDE', '', 'Schaut! Es ist vollbracht! Oh, wie wundervoll! Und wie tödlich!', 28153),
(141096, 'deDE', 'Sehr gute Arbeit, Ingrid. Und gar nicht befremdlich.', '', 28153),
(141095, 'deDE', 'Ich kümmer mich drum.', '', 28153),
(141094, 'deDE', '', 'Äh... Ich glaube, wir brauchen einen Schild, um uns vor diesen Blitzschlägen zu schützen.', 28153),
(141093, 'deDE', '', 'Oh, darauf habe ich schon eine ganze Weile gewartet. Bleibt zurück!', 28153),
(141092, 'deDE', 'Wenn mich noch einer von Euch Eingeborenen \"Kandelaber\" nennt, schwöre ich...', '', 28153),
(141091, 'deDE', '', 'Also eigentlich stehe ich nicht auf Drogbar, aber wenn sie ihre Fitnessübungen machen, dann... na ja... wird es in MEINEN Tiefen ganz warm.', 28153),
(141090, 'deDE', 'Ingrid, ich werde den Himmelsruferedelstein mit meiner eigenen Magie ermächtigen. Tretet zurück.', 'Ingrid, ich werde den Himmelsruferedelstein mit meiner eigenen Magie ermächtigen. Tretet zurück.', 28153),
(141089, 'deDE', 'Ihr müsst den Himmelsruferedelstein für mich ermächtigen.', 'Ihr müsst den Himmelsruferedelstein für mich ermächtigen.', 28153),
(141088, 'deDE', 'Nicht zu glauben... $n! Hier drüben!', '', 28153),
(141087, 'deDE', '', 'Haha... Ich WUSSTE, dass wir gerettet würden! Also zumindest hatte ich es schwer gehofft. Hier drüben!', 28153),
(141086, 'deDE', '', 'Hey, Ihr da! $n! Ich hab schon viel von Euch gehört! Und jetzt holt mich hier raus!', 28153),
(141085, 'deDE', 'Ist das zu glauben, dass $n hier ist, um mich persönlich zu retten?', '', 28153),
(141084, 'deDE', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Ihr seid |cFFF00000|Hspell:257459|h[Am Haken]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Ihr seid |cFFF00000|Hspell:257459|h[Am Haken]|h|r!', 28153),
(141083, 'deDE', 'Ihr Sieg ist näher, als Ihr glaubt.', '', 28153),
(141082, 'deDE', 'Ihr Flüstern hallt am lautesten nach.', '', 28153),
(141081, 'deDE', 'Die Brennenden hielten das Gleichgewicht. Jetzt ist es verloren...', '', 28153),
(141080, 'deDE', 'Euer Stolz hat all dies bewirkt.', '', 28153),
(141079, 'deDE', 'Die Nacht bricht an. Ihr Lied endet.', '', 28153),
(141078, 'deDE', 'Fügt Euch Eurem Schicksal. Alle werden ertrinken.', '', 28153),
(141077, 'deDE', 'Die Risse weiten sich aus.', '', 28153),
(141075, 'deDE', '$n erweckt einen Knochenhaufen!', '$n erweckt einen Knochenhaufen!', 28153),
(141074, 'deDE', 'He, Ihr! Wenn Ihr Eure Gefährten verlor\'n habt, kann ich Euch helf\'n, sie wiederzufind\'n.', '', 28153),
(141073, 'deDE', 'Ich hab mich zu Lebzeit\'n um die Tiere gekümmert. Wenn Ihr wollt, kann ich damit noch immer helf\'n.', '', 28153),
(141072, 'deDE', 'Wir sind gekomm\'n, so früh es ging.', '', 28153),
(141071, 'deDE', '', 'Bereitet die Seuche vor! Lasst sie auf ihre Armeen niederregnen!', 28153),
(141068, 'deDE', '', 'Doch Euer Schicksal liegt in Eurer eigenen Hand, Umbric. Ich kann Euch lehren, das Flüstern verstummen zu lassen, sodass die Schatten Euch dienen und nicht Ihr ihnen.', 28153),
(141067, 'deDE', '', 'Durzaan hat versucht, Euch Eure Sterblichkeit zu entreißen, Euch ihm gleich zu machen – Sklaven seines Hungers.', 28153),
(141066, 'deDE', 'Alleria... $p... Mein Volk ist frei, doch wir... haben uns verändert. Und die Stimmen...', '', 28153),
(141065, 'deDE', '', 'Nein. Ihr könnt sie nicht versklaven. Sie sind nicht verloren.', 28153),
(141064, 'deDE', 'Neeeeeeeeeeeein...', '', 28153),
(141063, 'deDE', '', 'Ich durchschaue Eure Lügen, Durzaan. Und die anderen werden das auch.', 28153),
(141062, 'deDE', 'Warum widersetzt Ihr Euch? Ihr steht an der Schwelle zu einem glorreichen Schicksal.', '', 28153),
(141061, 'deDE', '', 'Dieser Leerensturm ist eine Verbindung... ein Tor, das geschlossen werden muss.', 28153),
(141060, 'deDE', '', 'Eure Meister werden mich nicht versklaven, Astraler... weder mich noch meine Brüder und Schwestern!', 28153),
(141059, 'deDE', 'Wir sind auf derselben Seite, Windläufer... was auch immer Euch dieser Verräter gelehrt hat.', '', 28153),
(141058, 'deDE', '', 'Ah-ah, beim ersten Date wird nicht am Geweih gefummelt.', 28153),
(141057, 'deDE', 'Namen sind von geringer Bedeutung. Die interessantere Frage ist... Zu was werdet Ihr werden?', '', 28153),
(141056, 'deDE', '', 'Kommt, $p. Wir müssen diese Transformation stoppen, bevor mein Volk verloren ist!', 28153),
(141055, 'deDE', 'Rrrrurgaaghh! Ich spüre, wie die Macht... mich ruft... mich verändert...', '', 28153),
(141054, 'deDE', '', 'Widersetzt Euch den Stimmen, Umbric! Dieses \"Geschenk\" ist nichts mehr als Sklaverei.', 28153),
(141053, 'deDE', '', 'Zeigt Euch! Wer seid Ihr?', 28153),
(141052, 'deDE', 'Endlich... die Zukunft, die ich sah, wird Realität. Danke, dass Ihr den Pfad geebnet habt.', '', 28153),
(141051, 'deDE', '', 'Und dann sagte er zu mir, Donnertotem sei ein Kuhdorf. Damit hatte er es sich endgültig mit mir verscherzt.', 28153),
(141050, 'deDE', 'Warum sich mit Hörnern zufrieden geben, wenn man auch ein dickes Geweih haben kann.', '', 28153),
(141049, 'deDE', 'Haha! Erlebt meine Kraft un\' denkt daran, dass Ihr \'nen Teil davon hab\'n könnt...', '', 28153),
(141048, 'deDE', 'Das Gebiet dort vorn ist gefährlich. Kehrt um!', 'Das Gebiet dort vorn ist gefährlich. Kehrt um!', 28153),
(141047, 'deDE', '', 'Ihr habt zugelass\'n, dass Zul sich durch unsere Truppen wie durch Seid\'npapier schneidet. Jetzt marschiert er ohne Widerstand auf Atal\'Dazar zu. Habt Ihr \'nen Plan dafür, oh König?', 28153),
(141046, 'deDE', '', 'Rastakhan, Ihr habt Euch echt Zeit gelass\'n, Euch um die Sache hier zu kümmern.', 28153),
(141045, 'deDE', 'Es is\' schwer zu sagen, ob Zul gut planen kann oder einfach nur ein guter Prophet is\'. Auf jeden Fall is\' er uns immer einen Schritt voraus.$b$bEr plant, mich durch die Knochen unseres ersten Königs, Dazar, zu ersetz\'n.$b$bIch wünsche mir zwar, dass wieder Trolle die Welt beherrsch\'n, aber ich bin nich\' bereit, den Preis für die dunklen Ketzereien zu bezahl\'n, denen sich Zul zugewandt hat.', '', 28153),
(141044, 'deDE', '', 'Sogar der alte Bwonsamdi wird erbleich\'n, wenn er sieht, was ich mit Euch anstell\'n werd.', 28153),
(141043, 'deDE', '', 'Ich werd Eurer Seele schreckliche Dinge zufüg\'n.', 28153),
(141042, 'deDE', '', 'Euer Leid\'n endet nich\' mit dem Tod.', 28153),
(141041, 'deDE', '', 'Erst töt ich Euch un\' dann knöpf ich mir Euch richtig vor.', 28153),
(141040, 'deDE', '', 'Ihr wagt es, in meinen Tempel einzudring\'n? Oh, dafür sterbt Ihr.', 28153),
(141039, 'deDE', '', 'Rastakhan is\' hier? Gut. Bringt mich zu dem Zuspätkommer.', 28153),
(141038, 'deDE', 'Ich wollte nur helfen.', '', 28153),
(141037, 'deDE', 'Die Schönheit, die da kommt, wird die Welt brennen lassen.', '', 28153),
(141036, 'deDE', 'Schaut Euch an! Der mächtige Held... ha!', '', 28153),
(141035, 'deDE', '', 'Wollt Ihr wissen, wie man eine Frau erobert? Hufmassagen. Da könnt Ihr mir vertrauen, Schätzchen.', 28153),
(141034, 'deDE', '', 'Vielleicht sollte ich Lieder schreiben. Wir Tauren sind einfach die besten Muuuhsiker.', 28153),
(141033, 'deDE', '', 'Brrrrr, irgendwie kalt hier. Jemand Lust auf Milcheis?', 28153),
(141032, 'deDE', '', 'Warum sind die Flussmähnen immer so negativ? Bei ihnen geht alles den Bach runter.', 28153),
(141031, 'deDE', '', 'Meine Mama hat immer gesagt, wenn man zu viel Schokolade isst, wird man davon ganz lila.', 28153),
(141030, 'deDE', 'Habt Ihr gerade versucht, Euren Hut an mein Geweih zu hängen? Sehe ich etwas aus wie eine Garderobe?', '', 28153),
(141029, 'deDE', 'Was riecht schlimmer als ein Drogbar? Zwei Drogbar! Was riecht schlimmer als zwei Drogbar? Das konnte noch keiner herausfinden, der Gestank bringt einen vorher um.', '', 28153),
(141028, 'deDE', 'Ein Tauren, ein Yaungol und ein Taunka kommen in eine Bar. Nein, das ist kein Witz, das ist mein Familientreffen.', '', 28153),
(141027, 'deDE', 'Ha! Ein Kumpel von mir hat einmal so einen episch gekleideten Abenteurer überredet, Fische in den Fluss zu treten. Hahaha! Oh ähm... das wart doch nicht etwa Ihr?', '', 28153),
(141026, 'deDE', 'Ich bin vielleicht nur ein einfacher Tauren aus den Bergen, aber wenigstens suche ich nicht in Tierdung nach Beute.', '', 28153),
(141025, 'deDE', 'Lust auf ein Spiel? Immer wenn eine Harpyie was von Erde oder Steinen kreischt, heben wir einen.', '', 28153),
(141024, 'deDE', 'Warum tragen manche Draenei ihre Euter eigentlich im Gesicht?', '', 28153),
(141023, 'deDE', '', 'Nicht die Größe des Geweihs entscheidet, sondern wie gut man sein Totem schwingt.', 28153),
(141022, 'deDE', '', 'Starrt Ihr auf mein Geweih?', 28153),
(141020, 'deDE', '', 'Darf ich mal Euren Brunftschrei hören?', 28153),
(141018, 'deDE', 'Ihr dürft gerne mal meinen Hochberg besteigen.', '', 28153),
(141017, 'deDE', 'Bei mir dürft Ihr Euch ruhig austoben, ich halte einiges aus.', '', 28153),
(141016, 'deDE', 'Hütet Euch vor den Tiefen... meines Herzens.', '', 28153),
(141015, 'deDE', 'Mein Totem donnert... die ganze Nacht.', '', 28153),
(141014, 'deDE', 'Vertraut mir, ich kenne mich in den \"Tiefen\" aus.', '', 28153),
(141013, 'deDE', 'Kennt Ihr die Kojen auf der Vindikaar schon? Ich kann eine Privatführung arrangieren.', '', 28153),
(141012, 'deDE', '', 'Ihr müsst wirklich zu einer unserer Partys im Hof der Sterne kommen. Keiner hat eine Maske nötiger als Ihr.', 28153),
(141011, 'deDE', '', 'Nachtelf? Ihr denkt, ich bin ein Nachtelf? Lebe ich in Bäumen? Schlafe ich in Höhlen? Wächst mir ein Hutständer aus dem Kopf?', 28153),
(141010, 'deDE', '', 'Ich habe also diese Kaldorei getroffen und die sagt mir, mein Kleid ist der letzte Schrei... jedenfalls vor 10.000 Jahren. Autsch! Diese Nachtelfen wissen wirklich, wie man einem den Tag verdüstert.', 28153),
(141009, 'deDE', '', 'Tyrande sieht wirklich gut aus, selbst nach all den Jahren. Wisst Ihr, ob sie mit jemandem ausgeht?', 28153),
(141008, 'deDE', '', 'Möchtet Ihr ein Glas Arkwein? Auf den Beeren bin ich selbst herumgesprungen.', 28153),
(141007, 'deDE', '', 'Rosen sind rot... und unscheinbar. Da schreit schon die Wache: WER IST DA?', 28153),
(141006, 'deDE', '', 'Eine Anspielung! Was impliziert Ihr?', 28153),
(141005, 'deDE', 'Seien wir ehrlich – einen riesigen, wütenden Dinosaurier in einem Zoo einzusperren, musste ja schiefgehen.', '', 28153),
(141004, 'deDE', 'Tenu\'blabla. Halt... das klang falsch.', '', 28153),
(141003, 'deDE', 'Früher war alles besser. Da gab es nur eine Art von Elf. EINE.', '', 28153),
(141002, 'deDE', 'Das sind meine Eigenarten, ich trinke Arkwein und ich weiß Dinge.', '', 28153),
(141001, 'deDE', 'Hallo... mein Name ist Roy und ich bin magiesüchtig.', '', 28153),
(141000, 'deDE', 'Warum soll ich eigentlich immer wieder diesen Spruch sagen? Ughhhh. Na schön. Eine Täuschung! Was verbergt Ihr?', '', 28153),
(140999, 'deDE', 'Um ganz ehrlich zu sein, eigentlich hat fast immer alles gestimmt.', '', 28153),
(140998, 'deDE', '', 'Denkt Ihr, Ihr habt die nötige Ausrüstung, um mich zu tanken?', 28153),
(140997, 'deDE', '', 'Ich war 10.000 Jahre lang mit den gleichen Kerlen in einer Blase eingesperrt. Man könnte sagen, ich bin bereit für etwas... Abwechslung.', 28153),
(140996, 'deDE', '', 'Ich zeige Euch meine Leylinien, wenn Ihr mir Eure zeigt.', 28153),
(140995, 'deDE', '', 'Animation? Detonation? Wieso gehen wir nicht gleich zur Replikation über?', 28153),
(140994, 'deDE', '', 'Ob wir uns gerne mal gehen lassen? <kichert> Sagen wir, der Nachtbrunnen ist nicht nur wegen seiner Magie beliebt.', 28153),
(140992, 'deDE', '', 'Mhm. Keine Illusionen. Das bin alles ich...', 28153),
(140991, 'deDE', '', 'Ist das eine Illusion in Eurer Tasche, oder freut Ihr Euch nur mich zu sehen?', 28153),
(140990, 'deDE', 'Ihr seid ja ein reifes Früchtchen. Haben sie Euch gerade vom Arcan\'dor gepflückt?', '', 28153),
(140989, 'deDE', 'Die Sterne haben Euch gerichtet und zum Essen mit mir verurteilt.', '', 28153),
(140988, 'deDE', 'Ich habe das Gefühl, wir sind für einander nachtgeboren.', '', 28153),
(140987, 'deDE', 'Seid nachsichtig, Ihr macht mich noch nachtsüchtig.', '', 28153),
(140986, 'deDE', 'Mmmh, also diese Leylinie würde ich gerne mal anzapfen.', '', 28153),
(140985, 'deDE', 'Wollt Ihr einen Ar-kuss?', '', 28153),
(140984, 'deDE', 'Ihr scheint etwas von Illusionen zu verstehen, denn Ich kann niemanden mehr sehen, außer Euch.', '', 28153),
(140983, 'deDE', 'Euer Körper muss ein Quell der Magie sein, denn ich fühle mich magisch davon angezogen.', '', 28153),
(140982, 'deDE', '', 'Turalyon war der einzige Mensch, den ich in tausend Jahren gesehen habe. Ich dachte, sie wären alle grau und vernarbt.', 28153),
(140981, 'deDE', '', 'Lichtgeschmiedet zu sein, ist manchmal hart. Meine S.E.L.F.I.E.S. sind immer überbelichtet.', 28153),
(140980, 'deDE', '', 'Wir haben die Vindikaar noch nicht zu Bruch geflogen... aber bei unserer Fliegerei kann es nicht mehr lange dauern.', 28153),
(140979, 'deDE', '', 'Auf der Vindikaar solltet Ihr nie barfuß sein. Wir finden andauernd kleine Kristallsplitter, die beim Durchfegen übersehen wurden.', 28153),
(140978, 'deDE', '', 'Zehen sind überbewertet. Mit Hufen geht die Pediküre soooo viel schneller.', 28153),
(140977, 'deDE', '', 'Kennt Ihr meinen Hund? Ich mag eigentlich keine Hunde, aber der Verkäufer meinte, er killt jeden. Das hatte ich falsch verstanden.', 28153),
(140976, 'deDE', '', 'Nein, ich habe keine leuchtende Tätowierung über meinem Schwanz.', 28153),
(140975, 'deDE', 'Mein Leben für Aiur... <cough> Argus. Mein Leben für ARGUS!', '', 28153),
(140974, 'deDE', 'Nachdem ich so lange auf einem Schiff gelebt habe, tut es gut, echten Boden unter den Füßen zu haben. Die harten Oberflächen waren Gift für meine Hufe!', '', 28153),
(140973, 'deDE', 'Eure Welt ist sonderlich. Sprechende Bären, die Kung-Fu praktizieren? Auf Argus nennt man das Zirkus.', '', 28153),
(140972, 'deDE', 'Ich dachte meine Tättowierung bedeutet \"Verteidiger des Lichts\" auf Naaru, aber tatsächlich steht da \"Leuchtziege\".', '', 28153),
(140971, 'deDE', '', 'Im Zweifelsfall... einfach etwas anfassen, das leuchtet.', 28153),
(140970, 'deDE', 'Brennt das Licht heller in mir? Oder machst du mich nur so heiß?', '', 28153),
(140969, 'deDE', 'Ihr Blut macht ihn stärker. Und Eures wird das auch tun.', '', 28153),
(140967, 'deDE', 'Wir müss\'n weiter, hier sollten wir nich\' bleib\'n.', 'Wir müss\'n weiter, hier sollten wir nich\' bleib\'n.', 28153),
(140966, 'deDE', '', 'Verflucht seien die Feiglinge von Zuldazar, dass sie diese Bedrohung nich\' schon früher bekämpft hab\'n! Mein Vater war ein Narr, zu glaub\'n, dass sich das schon irgendwie von alleine lös\'n würde.\n\nEs wird nich\' reich\'n, nur Ateena zu töt\'n... Das Problem is\' größer, als ich es je erwartet hätte.', 28153),
(140965, 'deDE', 'Meine Wacht... endet jetzt...', '', 28153),
(140964, 'deDE', 'Vergebt mir, meine Königin.', '', 28153),
(140963, 'deDE', 'Meine Königin... Ich hab Euch enttäuscht!', '', 28153),
(140962, 'deDE', 'Niemand darf sich der Königin nähern!', '', 28153),
(140961, 'deDE', 'Die Ruhe der Königin darf nich\' gestört werd\'n!', '', 28153),
(140960, 'deDE', 'Ich bin der ewige Beschützer der Königin! Verschwindet!', '', 28153),
(140959, 'deDE', '', 'Beim Loa... Nein! Das is\' also die wahre Macht von den Bluttrollen... Oh, Vater... warum hast du sie nur so lang ignoriert?', 28153),
(140958, 'deDE', '', 'Macht Euch bereit, $n. Wir wiss\'n nich\', was vor uns is\'.', 28153),
(140957, 'deDE', '<Im Allgemeinen sollte man schlafende Hunde nicht wecken.>', '', 28153),
(140954, 'deDE', 'Ich lasse dabei gern das Licht an. Nicht, dass ich wirklich eine Wahl habe.', '', 28153),
(140953, 'deDE', '', 'Mein Schiff ist nicht weit von hier. Sollen wir ein bisschen den Nether wirbeln?', 28153),
(140952, 'deDE', '', 'Du musst mit den Titanen verwandt sein... bei diesem Himmelskörper.', 28153),
(140950, 'deDE', '', 'Sie muss in der Nähe sein. Ich geb nich\' auf, schon gar nich\', wenn wir so kurz davor sin\', die Anführerin der Monster zu töt\'n.', 28153),
(140949, 'deDE', '', 'Ihr entkommt mir nich\', Ateena. Ganz egal, was Ihr für\'n dunkles Voodoo benutzt.', 28153),
(140939, 'deDE', '', 'Ihr steht der Macht von G\'huun gegenüber! Ihr könnt uns nich\' aufhalt\'n. Ich zeig\'s Euch...', 28153),
(140938, 'deDE', '', 'Arme Talanji! Wir sind die Kinder von \'nem mächtigen Loa. So werdet Ihr uns nie besieg\'n, Kind!', 28153),
(140937, 'deDE', '', 'Ihr könnt mich nich\' einschüchtern, Ateena. Ich werd\' Euch töt\'n, genau wie Euern Meister!', 28153),
(140936, 'deDE', '', 'Ich halt mich lieber bedeckt, bis die Zeit reif is\'. Un\' dann bereit\'n wir Ateena gemeinsam \'n Ende.', 28153),
(140930, 'deDE', 'Ich bin entkomm\'!', 'Für immer hier gefang\'n.', 28153),
(140929, 'deDE', 'Ihr werdet leid\'n!', 'Zak\'rajan hat uns alle verrat\'n.', 28153),
(140928, 'deDE', 'Zak\'rajan muss sterb\'n!', 'Niemand entkommt Zak\'rajan.', 28153),
(140927, 'deDE', 'Mutta! Ich glaub, ich hab da drüben im Nordwesten \'ne Bewegung geseh\'n.', '', 28153),
(140926, 'deDE', 'Ich grüß Euch, Mutta. Hier is\' alles ruhig.', '', 28153),
(140925, 'deDE', 'Hey, Mutta. Es gibt schlechte Neuigkeiten. Wir ham die Spur von den Eindringlingen verlor\'n, die Najimas Arbeitstrupp abgemurkst ham.', '', 28153),
(140924, 'deDE', '', 'Lasst die Bluttrolle für diese Schandtat leid\'n, $n! Sucht mich auf, wenn Ihr die Gefall\'nen gerächt habt.', 28153),
(140923, 'deDE', '', 'Ich kann die Tot\'n von meinem Volk nich\' so zurücklass\'n... damit sie diese Monster entweih\'n.', 28153),
(140922, 'deDE', 'Meine Axt ist zum Fällen von Bäumen gemacht, aber diese Dinger sind ähnlich genug!', '', 28153),
(140921, 'deDE', 'Diese Axt ist zum Hacken gemacht, und das wird sie jetzt zeigen!', '', 28153),
(140920, 'deDE', 'Spinnen... Bestien aus Holz... Ich mäh\' sie alle nieder!', '', 28153),
(140916, 'deDE', 'Mich kerkert Ihr nich\' noch ma\' ein.', 'Ich werde Eure Seele verschling\'n.', 28153),
(140915, 'deDE', '|cffffff00Forschung abgeschlossen|r', '|cffffff00Forschung abgeschlossen|r', 28153),
(140914, 'deDE', '', 'Nur noch eine Handvoll Totems... In Ordnung, ich bin bereit!', 28153),
(140912, 'deDE', 'Spinnen sind eine Sache, aber Baummenschen? Damit will ich nichts zu tun haben!', '', 28153),
(140911, 'deDE', 'Ich bin\'s ja gewöhnt, Holz zu hacken, aber normalerweise wehrt es sich nicht!', '', 28153),
(140910, 'deDE', 'Die Bäume sind zum Leben erwacht! Los, jeder für sich!', '', 28153),
(140909, 'deDE', '', 'Folgt mir. Ich halte uns während unserer Flucht versteckt.', 28153),
(140907, 'deDE', '', 'Beeilt Euch. Wir wissen nicht, ob dieses Ding tot bleibt.', 28153),
(140906, 'deDE', '', 'Sehr Euch nur all diese Artefakte an! Ich brauche eine größere Tasche!', 28153),
(140905, 'deDE', 'Gute Arbeit, Leute! Schnappt Euch, was Ihr könnt, solange Ihr es könnt.', '', 28153),
(140904, 'deDE', '', 'Und vielleicht ein paar kleine Kinkerlitzchen... für meine Mühen.', 28153),
(140903, 'deDE', '', 'Oh, und das seelenerfüllte Golemauge nicht zu vergessen! Daraus kann Tacha lustige kleine Bomben machen.', 28153),
(140902, 'deDE', '', 'Verfluchte Götzen! Tacha liebt sie... Und seht Euch all diese Reagenzien an.', 28153),
(140901, 'deDE', '', 'Also dann. Mal sehen, was von diesem magischen Zeug es wert ist, herumgeschleppt zu werden.', 28153),
(140900, 'deDE', '', 'Das ist eine gute Ausbeute, $p. Ich nehme mir das Beste davon, natürlich für die Gruppe.', 28153),
(140899, 'deDE', '', 'Hauptsächlich standardmäßige Zandalariwaffen hier... Oh, die hier sehen verzaubert aus!', 28153),
(140898, 'deDE', '', 'Gut gekämpft. Jetzt wollen wir mal sehen, was sie hier alles eingelagert haben.', 28153),
(140897, 'deDE', 'Beschützt die Priesterin! Lasst kein\' durch!', 'Beschützt die Priesterin! Lasst niemand\'n durch!', 28153),
(140896, 'deDE', 'Wir erricht\'n \'ne Basis in den Ruin\' in der Nähe. Ihr zwei, seid vorsichtig. Hab kein gutes Gefühl bei der Sache.', '', 28153),
(140895, 'deDE', 'Loti hat Euch Waren schlepp\'n lass\'n? Ich hätt das Viech einfach verhext und gut wär\'s gewes\'n, aber die Händler beschwer\'n sich immer, wenn ich sowas mach.', '', 28153),
(140894, 'deDE', '', 'Etwas hat einen von den Brutosauriern erschreckt und ihn in Panik versetzt. Dieses Chaos is\' das Letzte, was wir hier in der Stadt brauch\'n. Helft den Händlern und rettet die Ladung, bevor er Euch in \'n Boden stampft!', 28153),
(140893, 'deDE', '', 'Habt Dank. Die Jugend von heute respektiert weder das Alter noch das Eigentum. Das hätte es zu meiner Zeit nicht gegeben...', 28153),
(140892, 'deDE', '', 'Hilfe! Die Kleinen haben unsere Schriftrollen gestohlen und sich in wilde Tiere verwandelt. Wir haben Schriftrollen der Bannung, aber um sie einzusetzen, müsst Ihr nah genug ran. Seid vorsichtig!', 28153),
(140891, 'deDE', 'Bevor Ihr sterbt, sollt Ihr wissen, dass der Rest Eurer Art in Ketten gelegt und uns dienen wird!', '', 28153),
(140890, 'deDE', 'Eure erbärmliche Art werden wir uns gefügig machen.', '', 28153),
(140889, 'deDE', 'Euresgleichen wird durch unsere Klingen sterben.', '', 28153),
(140888, 'deDE', 'Horde und Allianz werden untergehen!', '', 28153),
(140887, 'deDE', 'Rache für den Kaiser!', '', 28153),
(140886, 'deDE', 'Rache für Lei Shen!', '', 28153),
(140885, 'deDE', 'Zul hat uns versprochen, dass wir Rache an Euresgleichen nehmen können.', '', 28153),
(140880, 'deDE', 'Dinomantin Kish\'o ruft um Hilfe!', 'Dinomantin Kish\'o ruft um Hilfe!', 28153),
(140869, 'deDE', 'Stellt diese Kaserne fertig.', '', 28153),
(140860, 'deDE', 'Ähm, Verzeihung! Hier drüben! Könnten wir Euch behelligen und um Hilfe bitten?', '', 28153),
(140859, 'deDE', '', 'Danke für die Unterstützung, $p. Wenn Ihr bereit seid, ein paar Sethrak zu töten, sucht uns drinnen.', 28153),
(140858, 'deDE', '', 'Ich stimme zu. Das ist nicht unser Kampf. Es ist Zeit zu gehen.', 28153),
(140857, 'deDE', 'Das eskaliert zu schnell. Wir haben bereits die Vorräte, die wir zum Angriff auf die Sethrak benötigen.', '', 28153),
(140856, 'deDE', 'Schickt mich zur Mine der Trockenstoppel.', 'Schickt mich zur Mine der Trockenstoppel.', 28153),
(140855, 'deDE', 'Rekrutiert einen Goblinbomber.', 'Rekrutiert einen Goblinbomber.', 28153),
(140854, 'deDE', 'Ich werde mich vorschleichen und das Gebiet auskundschaften. Ihr räumt diese Gespenster aus dem Weg, und ich schnappe mir die Vorräte.', 'Ich werde mich vorschleichen und das Gebiet auskundschaften. Ihr räumt diese Gespenster aus dem Weg, und ich schnappe mir die Vorräte.', 28153),
(140853, 'deDE', '', 'Zuerst müsst Ihr die Golems töten. Benutzt dann das Totem, um den Leichnamen ihre Seelen zu entziehen.', 28153),
(140852, 'deDE', 'Beeilt Euch, sobald Ihr im Inneren seid. Der nächste Treffpunkt befindet sich im hinteren Teil der Ruinen nahe der unterirdischen Kammer.', '', 28153),
(140851, 'deDE', 'Es gibt keine Hoffnung! Die Versprech\'n des Betrügers sin\' Lügen!', '', 28153),
(140850, 'deDE', 'Lügen! Alles nur Lügen!', '', 28153),
(140849, 'deDE', 'Warum habt Ihr mich das erblick\'n lass\'n?! WARUM?!', '', 28153),
(140848, 'deDE', 'Ihr seid nur \'ne Marionette... un\' auch der Tod bringt Euch keine Erlösung!', '', 28153),
(140847, 'deDE', 'Unterwerft Euch G\'huun!', '', 28153),
(140846, 'deDE', '', 'Der Tod hält mich nicht auf...', 28153),
(140845, 'deDE', '', 'Die Mutter... wird Euch holen...', 28153),
(140844, 'deDE', 'So! Hab Euch den Geist von \'nem Bluttroll verpasst. Die Magie wird Euch verwandeln, wenn Ihr näher an ihr Dorf rangeht.', '', 28153),
(140843, 'deDE', '', 'Das ist nicht... das Ende...', 28153),
(140842, 'deDE', '', 'Der Zirkel ist... überall...', 28153),
(140841, 'deDE', '', 'Drustvar gehört uns, Fremdling!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140840, 'deDE', '', 'Widerstand ist zwecklos!', 28153),
(140839, 'deDE', '', 'Kniet nieder vor der Mutter!', 28153),
(140838, 'deDE', '', 'Euer jämmerliches Dorf gehört bald dem Zirkel!', 28153),
(140837, 'deDE', '', 'Da kommt Umi mit dem Späherbericht.', 28153),
(140836, 'deDE', '', 'Schlechte Neuigkeiten, Team. Ich habe Gespenster da drin gefunden. Ich erhöhe unsere Bedrohungsstufe auf \"Orange\".', 28153),
(140834, 'deDE', '', 'Während Ihr Euch darum kümmert, spähe ich die Ruinen aus. Stoßt am Treffpunkt zu mir, wenn Ihr bereit seid.', 28153),
(140833, 'deDE', '', 'Verschwendet Eure Zeit nicht mit leblosen Golems. Findet einen, der noch funktioniert.', 28153),
(140832, 'deDE', 'Schickt mich zum Axtkamm.', 'Schickt mich zum Axtkamm.', 28153),
(140831, 'deDE', 'Wir sehen uns am Treffpunkt auf der zerbrochenen Brücke, bevor wir die Ruinen direkt angreifen.', '', 28153),
(140830, 'deDE', 'Nun denn, jeder hat seine Aufgabe. Gute Jagd.', '', 28153),
(140829, 'deDE', 'Folgt mir. König Rastakhan ist in der Nähe.', 'Folgt mir. König Rastakhan ist in der Nähe.', 28153),
(140828, 'deDE', '', 'Zückt die Waffen. Da kommt jemand...', 28153),
(140827, 'deDE', '', 'Als Zul verlangte, dass wir ihm die Überreste von Dazar, unsrem ersten König geb\'n, dacht\'n wir, er macht \'n Witz.$b$bWir hab\'n ihn weggeschickt.$b$bDa wussten wir noch nich\', dass er \'ne Armee hat, um den Tempel zu stürm\'n.', 28153),
(140826, 'deDE', 'Diese Ruine ist voller Schätze. Lassen wir uns also Zeit und erledigen das gründlich.', '', 28153),
(140825, 'deDE', '', 'Mutta! Wo bist du?', 28153),
(140824, 'deDE', '<Winstone öffnet eine Packung Karten. Woher hat er nur das ganze Gold?>', '', 28153),
(140823, 'deDE', '<Winstone starrt wie wild auf die Karten in seiner Hand.>', '', 28153),
(140822, 'deDE', '<Winstone kauert über seiner Kartensammlung und spielt mit einer Idee für ein neues Deck herum.$b$bBei näherer Betrachtung scheint er sich ganz schön viele Wildtiere ausgesucht zu haben...>', '', 28153),
(140821, 'deDE', 'Schickt mich nach Ar\'gorok.', 'Schickt mich nach Ar\'gorok.', 28153),
(140820, 'deDE', 'Um Xal\'zaix zu finden, müssen wir zuerst Sethraliss finden.', '', 28153),
(140818, 'deDE', 'Zak\'rajan benutzt uns\'re Seelen als Waff\'n. Ihr seid dem Untergang geweiht.', '', 28153),
(140817, 'deDE', 'Eure Waffen sind wertlos. Uns\'re Geister schützen ihn.', '', 28153),
(140816, 'deDE', 'Noch \'n Körper, der Zak\'rajan geopfert werd\'n kann!', '', 28153),
(140815, 'deDE', 'Eure Seele wird mit den and\'ren in diesem Golem vereint sein!', '', 28153),
(140814, 'deDE', 'Befreit uns...', '', 28153),
(140813, 'deDE', 'Zak\'rajan herrscht...', '', 28153),
(140812, 'deDE', 'Fremdlinge werd\'n ausgemerzt.', '', 28153),
(140811, 'deDE', 'Keine Könige. Nur Zak\'rajan.', '', 28153),
(140810, 'deDE', 'Geht, geht. Findet die abhand\'ne Mutta un\' bringt sie zusamm\'.', '', 28153),
(140809, 'deDE', 'Hehe... die Kleine hat Recht. Ihre Mutta is\' nich\' auf der Andren Seite.', '', 28153),
(140808, 'deDE', 'Keine Loa. Nur Zak\'rajan.', '', 28153),
(140807, 'deDE', 'Verteidigt den Hof mit all\'n Mitteln.', '', 28153),
(140806, 'deDE', 'Helft uns...', '', 28153),
(140805, 'deDE', 'Opfer... für Zak\'rajan...', '', 28153),
(140804, 'deDE', 'Oho, \'n Priester. Wenn Ihr jemals den Glauben wechseln wollt, meldet Euch beim alten Bwonsamdi.', '', 28153),
(140803, 'deDE', 'Die Blutfliegen stechen in letzter Zeit ganz schön zu, was?', 'Die Blutfliegen stechen in letzter Zeit ganz schön zu, was?', 28153),
(140802, 'deDE', 'Aua!', 'Aua!', 28153),
(140801, 'deDE', 'Döskopp.', 'Döskopp.', 28153),
(140800, 'deDE', 'He! Habt Ihr mich gerade gestochen!?', 'He! Habt Ihr mich gerade gestochen!?', 28153),
(140799, 'deDE', 'Vermaleidete Festländer...', 'Vermaleidete Festländer...', 28153),
(140798, 'deDE', 'Autsch! Was zum Henker macht Ihr da?!', 'Autsch! Was zum Henker macht Ihr da?!', 28153),
(140796, 'deDE', 'Dreckige Plünderer! Ich herrsche hier!', '', 28153),
(140794, 'deDE', 'Die Elemente hören den Ruf der Horde, wie es sich gehört.', '', 28153),
(140793, 'deDE', '', 'Das Geisterhaus steht für Euch bereit. Was braucht Ihr?', 28153),
(140792, 'deDE', 'Selbst die Loa haben uns verlass\'n.', 'Selbst die Loa haben uns verlass\'n.', 28153),
(140791, 'deDE', 'Schon seit unzähligen Äonen versklavt Zak\'rajan uns. Befreit uns...', 'Schon seit unzähligen Äonen versklavt Zak\'rajan uns. Befreit uns...', 28153),
(140790, 'deDE', 'Geister sin\' machtvolle Waffen... wenn man sie kontrollier\'n kann.', 'Geister sin\' machtvolle Waffen... wenn man sie kontrollier\'n kann.', 28153),
(140789, 'deDE', 'Er macht sich unsere Seelen zunutze, um sich selbst zu schütz\'n. Seinen Schild kann man nich\' mit Waffen durchdring\'n.', 'Er macht sich unsere Seelen zunutze, um sich selbst zu schütz\'n. Seinen Schild kann man nich\' mit Waffen durchdring\'n.', 28153),
(140788, 'deDE', 'Man hat uns unermessliche Reichtümer versproch\'n. Stattdessen versklavte man uns.', 'Man hat uns unermessliche Reichtümer versproch\'n. Stattdessen versklavte man uns.', 28153),
(140787, 'deDE', 'Zak\'rajan hat uns verboten, zu den Loa zu bet\'n, weil er allein verehrt werd\'n wollte.', 'Zak\'rajan hat uns verboten, zu den Loa zu bet\'n, weil er allein verehrt werd\'n wollte.', 28153),
(140786, 'deDE', 'Warum weigert sich Bwonsamdi, uns auf die Andre Seite zu lass\'n?', 'Warum weigert sich Bwonsamdi, uns auf die Andre Seite zu lass\'n?', 28153),
(140785, 'deDE', 'Zak\'rajan hat unsre Geister in diese Golems eingesperrt. Er zwingt uns, ihm zu dien\'n.', 'Zak\'rajan hat unsre Geister in diese Golems eingesperrt. Er zwingt uns, ihm zu dien\'n.', 28153),
(140784, 'deDE', 'Ich hoffe, die Hunde haben Hunger. Die Banner der Horde wehen über Neuhof und wir können Wolfsreiter ausbilden.', '', 28153),
(140783, 'deDE', 'Das Arsenal ist fertig. Bringt die Schmieden zum Laufen!', '', 28153),
(140781, 'deDE', 'Bau des Arsenals abgeschlossen. Wie lauten Eure Befehle?', '', 28153),
(140780, 'deDE', 'Zak\'rajan muss für unsere Gefangenschaft büß\'n!', 'Zak\'rajan muss für unsere Gefangenschaft büß\'n!', 28153),
(140779, 'deDE', 'Sethraliss wird über uns wachen.', 'Sethraliss wird über uns wachen.', 28153),
(140778, 'deDE', '', 'Ruhet in Frieden, süße Kaja. Ihr werdet nie in Vergessenheit gerat\'n.', 28153),
(140777, 'deDE', 'Sulthis war der erste Hüter. Er brauchte mich und Korthek, um den Leichnam von Mythrax in der großen Pyramide zu versiegeln.\n\nWir haben zusammen eine Barriere erschaffen, die den Leichnam von Mythrax darin bannt.\n\nJeder von uns erschuf einen Schlüssel, der mit unserer Kraft verstärkt wurde, um das Grab für alle Zeiten zu verschließen.', '', 28153),
(140776, 'deDE', 'Aber, aber. Niemand hier hat einen Grund zu kämpfen. Lasst uns Platz nehmen, etwas trinken und Rätsel erzählen, in Ordnung?', '', 28153),
(140775, 'deDE', 'Wenn Ihr denkt, Ihr hättet mit Winstone da drüben leichtes Spiel, dann passt bloß auf. Er wird den Spieß umdrehen und dann werdet IHR es vermasseln!', '', 28153),
(140774, 'deDE', 'Ich kenne Rastakhan, den mächtigen und ewigen König. Er sollte sich vorsehen, wen er unter seine Fittiche nimmt.', '', 28153),
(140773, 'deDE', '\"Oh, ich werde mein Abenteuer fortsetzen\", denkt Ihr vielleicht. Warum nicht bleiben, sich entspannen und etwas trinken?', '', 28153),
(140772, 'deDE', 'Willkommen in der Tikibar \"Der Flotschthron\". Hier gibt\'s die besten Getränke in ganz Zandalar!', '', 28153),
(140771, 'deDE', 'Wir können die Verbindung zwischen dem Herzen und Sethraliss benutzen, um sie zu finden.', '', 28153),
(140770, 'deDE', 'Das Herz ist an die Lebenskraft unseres Loas gebunden. Das rote Leuchten, das Ihr beschreibt, lässt darauf schließen, dass sie in Not ist... und noch viel wichtiger: dass sie lebt!', '', 28153),
(140769, 'deDE', 'Wenn es stimmt, was Ihr sagt, dann müssen wir schnell handeln!', '', 28153),
(140768, 'deDE', 'Interessant...', '', 28153),
(140767, 'deDE', 'Nee, nee, nee, tot bringt Ihr mir nix. Ich könnt Euch ins Leben zurückhol\'n... aber das kost\' was.', '', 28153),
(140766, 'deDE', 'Was macht Ihr hier, Mann? Eure Zeit is\' noch nich\' gekomm\'.', '', 28153),
(140764, 'deDE', '', 'Sie konnte nich\' wiss\'n, dass aus dem Dschungel \'ne Wüste wird...', 28153),
(140762, 'deDE', 'Raaaaaaagh!', '', 28153),
(140761, 'deDE', 'Die Treulosen werden diesen Tempel niemals erobern.', '', 28153),
(140759, 'deDE', 'Un\' Ihr da... mischt Euch nich\' wieder in meine Geschäfte ein. Wer \'n Handel mit mir bricht, der zahlt.', '', 28153),
(140758, 'deDE', 'Jetzt geht in Euer Gefängnis zurück un\' leidet.', '', 28153),
(140757, 'deDE', 'Ich mach keine Geschäfte mit Betrügern.', '', 28153),
(140756, 'deDE', 'Bitte, Bwonsamdi, nur noch einen Handel! Ich schlag jeden Tag Eure Trommeln! Meine Leute werden Euch immer verehr\'n!', '', 28153),
(140755, 'deDE', 'Ich hab Rakera gesucht, genau wie Ihr. Diese Schlangen behaupten, Ihr habt sie gefund\'n.\n\nSchön, dass wir alle wieder vereint sein können, zumindest, wenn sie mich mal aus diesem Käfig rauslass\'n.', '', 28153),
(140754, 'deDE', 'Ihr geht nie auf die Andre Seite. Ihr seht nie Eure Vorfahr\'n. Ihr seid hier gefang\'n auf alle Ewigkeit.', '', 28153),
(140753, 'deDE', 'Ich tu\'s. Bwonsamdi vergisst nichts.', '', 28153),
(140752, 'deDE', 'Aber Ihr seid arrogant geword\'n. Habt jede Verehrung außer Eurer eignen verbot\'n. Erinnert Ihr Euch?', '', 28153),
(140751, 'deDE', 'ändert mich', 'ändert mich', 28153),
(140750, 'deDE', 'Wir hatten \'ne Abmachung. Ihr kriegt Macht, Eure Leute verehr\'n mich.', '', 28153),
(140749, 'deDE', 'Wenn Ihr das glaubt, seid Ihr so dumm wie Ihr verlog\'n seid, Zak\'rajan.', '', 28153),
(140748, 'deDE', 'Zandalar birgt viele Geheimnisse. Vielleicht sind wir über eines gestolpert, das wir nicht hätten aufdecken sollen.', '', 28153),
(140747, 'deDE', '', 'Wir werd\'n Jakra\'zet als den Verräter entlarv\'n, der er ist.', 28153),
(140746, 'deDE', 'Bwonsamdi, alter Bastard, endlich hab ich Euch besiegt!', '', 28153),
(140745, 'deDE', 'Ja! Ich werd mich endlich zu meinen Vorfahren in den Schattenlanden gesell\'n!', '', 28153),
(140743, 'deDE', 'Wer sind die Hüter?', 'Wer sind die Hüter?', 28153),
(140742, 'deDE', 'Was is\' das? Is\' meine Seele endlich aus diesem Gefängnis befreit?', '', 28153),
(140740, 'deDE', 'Wer ist Sethraliss?', 'Wer ist Sethraliss?', 28153),
(140739, 'deDE', 'Die Treulosen sind eine Streitmacht militanter Sethrak, die von Imperator Korthek angeführt wird.\n\nVor langer Zeit haben wir alle zusammengelebt, so wie es Sethraliss immer wollte.\n\nAber seit Kortheks Verrat haben die Treulosen den Krieg über unser Land gebracht.\n\nSie werden nicht aufhören, bis sie die gesamte Welt unterworfen haben.', '', 28153),
(140738, 'deDE', 'Wer ist Korthek?', 'Wer ist Korthek?', 28153),
(140737, 'deDE', 'Die Treulosen werden diesen Tempel niemals erobern.', '', 28153),
(140729, 'deDE', '', 'Nicht schlecht, Herr Specht. Ihr könnt jederzeit wieder mit uns jagen! Nehmt jetzt einen Greifen zum Angelpunkt. Wir räumen hier auf.', 28153),
(140727, 'deDE', '', 'Könn\' wir Serrik vertrau\'n? Glaubt Ihr, der Sethrak kann uns helf\'n, Xal\'zaix zu find\'n?', 28153),
(140725, 'deDE', '', 'Is\' das Jakra\'zets Werk? Hat der sich Xal\'zaix schon geschnappt?', 28153),
(140724, 'deDE', 'Ruhm! Ruhm dem Meer!', '', 28153),
(140723, 'deDE', 'Ihr könnt die Gezeiten nicht aufhalten...', '', 28153),
(140722, 'deDE', 'Ifis yahf an\'zig...', '', 28153),
(140721, 'deDE', 'Erzittert unter dem Blick unseres Meisters!', '', 28153),
(140720, 'deDE', 'Uothk w\'shh!', '', 28153),
(140719, 'deDE', 'Das Meer ruft Euch, $R.', '', 28153),
(140718, 'deDE', 'Zurück in Eure Golems, Geister! Ihr gehört mir!', '', 28153),
(140717, 'deDE', 'Untersuchen', 'Untersuchen', 28153),
(140716, 'deDE', '', 'Sein Schild ist unten. Schlagt jetzt zu!', 28153),
(140715, 'deDE', '', 'Wenn Ihr schlau seid, könnt Ihr die Geister dazu benutzen, all die schwere Arbeit für Euch zu machen.', 28153),
(140714, 'deDE', '', 'Genau darum bewahre ich alte Totems voller zorniger Geister auf, $p...', 28153),
(140713, 'deDE', '', 'Da ist er! Ich kümmere mich um diesen ärgerlichen Geisterschild.', 28153),
(140707, 'deDE', 'Wir haben die verfiddelste Brapsche diesseits des flotzeligen Meeres. Haut sie Euch in die Gotsche!', '', 28153),
(140706, 'deDE', 'Was trinken, Nappel?', '', 28153),
(140705, 'deDE', '', 'Keine Ahnung, ob dieser Schlangenmensch die Wahrheit sagt, aber viele Möglichkeiten hab\'n wir nicht.', 28153),
(140704, 'deDE', 'Wen muss ich hier flotschen, um hier \'ne verfiddelte Brapsche zu bekommen?', 'Wen muss ich hier flotschen, um hier \'ne verfiddelte Brapsche zu bekommen?', 28153),
(140703, 'deDE', 'Verkauft Ihr... irgendwas?', 'Verkauft Ihr... irgendwas?', 28153),
(140702, 'deDE', '', 'Wir müss\'n die Waffe find\'n, bevor Jakra\'zet sie in die Finger kriegt.', 28153),
(140701, 'deDE', '', '<Der Stacheleber macht eine Reihe von Grunzlauten, die von gelegentlichem Quieken unterbrochen werden.>', 28153),
(140700, 'deDE', 'Die Sturmtakler sind so tapfer! Ich könnte nie ausziehen und diese Monster stellen! Ich bin ganz zufrieden damit, dass ich mich um die Fracht kümmern muss.', 'Die Sturmtakler sind so tapfer! Ich könnte nie ausziehen und diese Monster stellen! Ich bin ganz zufrieden damit, dass ich mich um die Fracht kümmern muss.', 28153),
(140699, 'deDE', '', 'Gehen wir, Okri. Die Sturmtakler warten.', 28153),
(140698, 'deDE', '', 'Wir warten nicht mehr auf Euren Segen, Therold. Wir haben Monster zu töten.', 28153),
(140697, 'deDE', 'Sobald Zak\'rajan erledigt ist, wird nach Herzenslust geplündert. Jeder behält das, was er sich schnappen kann.', '', 28153),
(140696, 'deDE', 'WARUM?!', 'WARUM?!', 28153),
(140695, 'deDE', 'AAAAAAHHHHHH!', 'AAAAAAHHHHHH!', 28153),
(140694, 'deDE', 'HEISS HEISS HEISS!', 'HEISS HEISS HEISS!', 28153),
(140693, 'deDE', '', 'Ich habe alles, was wir brauchen, um Zak\'rajans Barriere zu zerstören. Zeigt mir einfach, wo er ist.', 28153),
(140692, 'deDE', 'Nein, nicht so!!!', 'Nein, nicht so!!!', 28153),
(140691, 'deDE', 'Nein, nein, nein, NEIN!!!', 'Nein, nein, nein, NEIN!!!', 28153),
(140690, 'deDE', 'Wartet, wartet, WARTET!!!', 'Wartet, wartet, WARTET!!!', 28153),
(140689, 'deDE', '', 'Ich übernehme die Führung. Bleibt in der Nähe.', 28153),
(140688, 'deDE', '', 'Sie hab\'n sich ja echt Mühe gegeb\'n, aber dank Euch hab ich Bwonsamdi noch nich\' getroff\'n, $n.', 28153),
(140687, 'deDE', '', 'Plündert bloß nichts ohne mich.', 28153),
(140686, 'deDE', '', 'Wie schön, dass die Sande Euch noch nich\' verschlung\'n hab\'n, Rakera.', 28153),
(140685, 'deDE', '', 'Meine Späher und ich treffen Euch dort.', 28153),
(140684, 'deDE', '', 'Vielen Dank für Eure Hilfe. Ich weiß nicht, wohin unsere Entdeckung führen wird, aber ich bin froh, dass wir einige der Leute hier retten können.', 28153),
(140683, 'deDE', '', 'Lord Brannon und die anderen sind zum Sturmsangtal aufgebrochen, um vor der Verderbnis der Priester zu warnen. Ich überbringe die Warnung Boralus.', 28153),
(140682, 'deDE', 'Wir werden Euch dort treffen, $n. Das Spirituelle ist eine delikate Angelegenheit.', '', 28153),
(140681, 'deDE', '', 'Ich habe genau das Richtige zur Heilung...', 28153),
(140680, 'deDE', '', 'Wir sind über etwas gestolpert, das größer ist als wir selbst.', 28153),
(140678, 'deDE', '', 'Wir wart\'n hier. Wir sollt\'n lieber nich\' die Aufmerksamkeit von Jakra\'zets Assassinen weck\'n.', 28153),
(140677, 'deDE', 'Wartet einen Moment...', '', 28153),
(140675, 'deDE', '', 'Der hat genug! Was für ein Kampf, Sturmtakler.', 28153),
(140673, 'deDE', '', 'Da ist er! Zeigt ihm die Stärke der Sturmtakler!', 28153),
(140672, 'deDE', 'Der Assassine der Sandwüter zieht sich in die Schatten zurück.', 'Der Assassine der Sandwüter zieht sich in die Schatten zurück.', 28153),
(140671, 'deDE', '', 'Haltet nichts zurück, Sturmtakler! Gebt ihm alles, was Ihr habt!', 28153),
(140670, 'deDE', '', 'Zerstört die Tentakel! Zwingt die Bestie an die Oberfläche!', 28153),
(140669, 'deDE', '', 'Haltet Ausschau nach Assassinen. Jakra\'zet hat \'ne gepfefferte Summe auf mein\' Kopf ausgesetzt.', 28153),
(140667, 'deDE', 'Diese Welt wird uns gehör\'n. Zul hat es vorausgeseh\'n!', 'Diese Welt wird uns gehör\'n. Zul hat es vorausgeseh\'n!', 28153),
(140666, 'deDE', 'Was kommt, könnt Ihr nich\' aufhalt\'n. Zul hat es vorhergeseh\'n.', 'Was kommt, könnt Ihr nich\' aufhalt\'n. Zul hat es vorhergeseh\'n.', 28153),
(140665, 'deDE', 'Ihr bringt unsern gescheitert\'n König mit? Er wird sterb\'n, und Ihr könnt es nich\' verhindern.', 'Ihr bringt unsern gescheitert\'n König mit? Er wird sterb\'n, und Ihr könnt es nich\' verhindern.', 28153),
(140664, 'deDE', 'Ihr seid zu spät. Zul is\' aufm Weg zum Gipfel.', 'Ihr seid zu spät. Zul is\' aufm Weg zum Gipfel.', 28153),
(140663, 'deDE', 'Die Horde wird fall\'n. Die Allianz wird fall\'n. Un\' Zandalar wird aufersteh\'n!', 'Die Horde wird fall\'n. Die Allianz wird fall\'n. Un\' Zandalar wird aufersteh\'n!', 28153),
(140662, 'deDE', 'Zandalar wird diese Welt beherrsch\'n!', 'Zandalar wird diese Welt beherrsch\'n!', 28153),
(140661, 'deDE', 'Wir kämpf\'n für ein echtes Trollimperium!', 'Wir kämpf\'n für ein echtes Trollimperium!', 28153),
(140660, 'deDE', 'Mein Leben für Zul!', 'Mein Leben für Zul!', 28153),
(140659, 'deDE', 'Der Schrecken der Meere – verleitet von Tiefenwachts dunklem Meister! Vielleicht ein zu großes Monster, selbst für die Sturmtakler.', '', 28153),
(140656, 'deDE', 'Ich hatte schon Gegner, die größer waren als Ihr. Haben alle den Kürzeren gezogen!', '', 28153),
(140655, 'deDE', 'Wehe, jemand rührt... meine Beute an...', '', 28153),
(140654, 'deDE', 'Einfach unmöglich...', '', 28153),
(140653, 'deDE', 'Los, Männer! Macht dieses Pack mit unseren Kanonen bekannt.', '', 28153),
(140652, 'deDE', 'Feuer frei! Zerfetzt diese elenden Hunde!', '', 28153),
(140651, 'deDE', 'Brecht die Goldzähne raus, Jungs. Der Rest ist für die Haie.', '', 28153),
(140650, 'deDE', 'Ich liebe das Todesröcheln meiner Feinde am Morgen.', '', 28153),
(140649, 'deDE', '', 'G\'huun wird frei sein un\' Hir\'eeks Anhänger krieg\'n ihre Belohnung!', 28153),
(140648, 'deDE', 'Alles klar, Jungs, sackt ihre Wertsachen ein. Wenn ich meinen Anteil ausgesucht habe, könnt Ihr Euch um die Reste streiten.', '', 28153),
(140647, 'deDE', 'Ihr habt die wichtigste Piratenregel vergessen: Kommt niemals zwischen Harlan und seine Beute!', '', 28153),
(140646, 'deDE', 'Stürzt Euch auf sie!', '', 28153),
(140645, 'deDE', 'Alle Mann an Deck!', '', 28153),
(140643, 'deDE', '', 'Beeindruckend. Ihr seid weiter gekomm\', als ich gedacht hab... aber ich werd trotzdem Euer Blut trink\'n.', 28153),
(140642, 'deDE', '', 'Rezan war\'n mächtiger Loa. Vielleicht gebt Ihr \'n würdiges Opfer für Zul ab.', 28153),
(140641, 'deDE', '', 'Ich muss Euch dank\'n, dass Ihr die Priest\'rin umgebracht habt. Damit habt Ihr mein\' Einfluss auf\'n Tempel nur gestärkt.', 28153),
(140640, 'deDE', 'Das gefällt mir! Bringt mehr in meine Höhle... Ich muss mit dem Meister Zwiesprache halten.', '', 28153),
(140639, 'deDE', '', 'Die Bedrohung durch die Gesichtslosen ist erst mal gebannt, aber ich werd weiterhin Atul\'Aman im Auge behalt\'n, um sicherzustell\'n, dass es auch so bleibt.', 28153),
(140638, 'deDE', '', 'Ihr habt Vol\'kaal in Einzelteile zerlegt? Macht nichts... ich bau ihn neu. Aber wenn IHR sterbt, kommt Ihr nich\' mehr zurück!', 28153),
(140637, 'deDE', 'Lasst uns eine Runde fliegen!', 'Lasst uns eine Runde fliegen!', 28153),
(140636, 'deDE', 'Wir werden belagert! Kommt mit mir, um den Ansturm dieses Monsters aufzuhalten!', '', 28153),
(140635, 'deDE', 'Informiert mich, wenn Ihr zum Aufbruch bereit seid! Die Zeit läuft uns davon, und das Monster wird nicht zögern!', '', 28153),
(140634, 'deDE', '', 'Zul wird bald Dazar erweck\'n un\' dann wird das Trollreich aufersteh\'n!', 28153),
(140633, 'deDE', '', 'Ihr kommt zu spät, Fremdlinge! Der Tempel is\' in der Gewalt von mei\'m Meister!', 28153),
(140632, 'deDE', 'HA! Es klappt! Nich\' aufhör\'n, weiterstech\'n!', '', 28153),
(140631, 'deDE', 'Die Sethrak sind uns zahlenmäßig überlegen, also müssen wir sie überlisten.', '', 28153),
(140630, 'deDE', '', 'Nehmt Euch, was Ihr könnt, wann immer Ihr könnt und von wem auch immer Ihr könnt.', 28153),
(140629, 'deDE', '', 'Man kann eine Verwendung für alles finden, wenn man es nur lang genug behält.', 28153),
(140628, 'deDE', '|TInterface\\Icons\\ABILITY_MOUNT_EPICBATMOUNT.BLP:20|t%s beginnt, |cFFFF0000|Hspell:256497|h[Blutschrecken]|h|r zu wirken! In Deckung!', '', 28153),
(140627, 'deDE', 'Gut... der denkt, wir sin\' Matsch... wir brauch\'n... \'nen neu\'n Plan.', '', 28153),
(140626, 'deDE', 'Nach all Euren \"Heldentaten\"... endet Ihr tot in meiner Höhle. Ich labe mich an Euch... wenn ich wieder bei Kräften bin.', '', 28153),
(140625, 'deDE', '', 'Die Winde werden Euch jetzt nach Atul\'Aman führen... Macht Euch bereit!', 28153),
(140624, 'deDE', '', 'Jetzt liegt es an uns, die Quelle der Störung zu finden und ihr ein Ende zu bereiten.', 28153),
(140623, 'deDE', '', 'Seit Jahrhunderten schon gedeiht im Inneren von Atul\'Aman eine finstere Macht. Ich spüre, dass die Elemente unruhig geworden sind...', 28153),
(140622, 'deDE', 'Mörsertrupps! Sprengt ihre Festung in Grund und Boden. In Grund und Boden!', '', 28153),
(140621, 'deDE', '', 'Die Echos jener Explosion hallen noch immer durch die Elemente. Welche Macht vermochte es, solche Verheerung zu stiften?', 28153),
(140620, 'deDE', '', 'Vor Tausenden von Jahren wurde das einst prächtige Bauwerk von Atul\'Aman in einer katastrophalen Explosion zerstört.', 28153),
(140619, 'deDE', 'Runter! Da kommt Hir\'eek.', '', 28153),
(140618, 'deDE', '', 'Legt Eure Hände auf den Schamanenstein und ich werd einen Zyklon beschwör\'n, der Euch nach Atul\'Aman bringt.', 28153),
(140617, 'deDE', '', 'Wir müss\'n erst mit den Glasschwanzskorpiden fertigwerd\'n, aber ich fürchte, dass uns noch eine gefährlichere Bedrohung erwartet.', 28153),
(140616, 'deDE', 'Aaaaah!!', '', 28153),
(140615, 'deDE', 'Ihr seid stark... aber keiner hält der Macht eines Loas stand!', '', 28153),
(140614, 'deDE', 'GENUG! Ich werde mich an Eurem gebrochenen Leib laben!', '', 28153),
(140613, 'deDE', 'Die Macht meines Meisters durchströmt mich... sie wird mich von Eurem Toxin läutern!', '', 28153),
(140612, 'deDE', 'Ich werde... Aaaargh! Was ist... das für ein Gift? Was habt Ihr mir angetan?', '', 28153),
(140611, 'deDE', 'Ha! Denkt Ihr wirklich, Ihr könnt mich bezwingen? Ich beherrsche die Lüfte!', '', 28153),
(140610, 'deDE', '', 'Was ham wir denn sonst für \'ne Wahl?', 28153),
(140609, 'deDE', '', 'Rakera! Ihr wollt ihm doch nich\' glaub\'n, was er da sagt?', 28153),
(140608, 'deDE', '', 'Dann is\' Euch unsere Hilfe gewiss, Serrik.', 28153),
(140607, 'deDE', 'Sammelt die Reagenzien für das Ritual und wir helfen Euch bei der Suche nach Eurem verschollenen Artefakt.', '', 28153),
(140606, 'deDE', 'Diese Vision war aufschlussreicher, als wir uns je erhofft hätt\'n. Xal\'zaix is\' zum Greifen nah.', '', 28153),
(140605, 'deDE', 'Was genau wird uns dieses Ritual offenbar\'n? Sind wir schon nah dran, Xal\'zaix zu find\'n?', '', 28153),
(140604, 'deDE', 'Vertraut Ihr diesen Schlangen wirklich? Ich glaub\', sie wiss\'n mehr, als sie preisgeb\'n...', '', 28153),
(140603, 'deDE', 'Meine Leute können Euch helfen, diesen Xal... wie heißt er doch gleich? Xal\'zaix... zu finden.', '', 28153),
(140602, 'deDE', 'Wollt Ihr zulassen, dass sie mich weiter so eingesperrt halt\'n?', '', 28153),
(140601, 'deDE', 'Nach Rakera zu suchen, is\' vergebene Mühe. Ihr Schicksal war besiegelt, als man sie in die Sande schickte.', '', 28153),
(140600, 'deDE', '', 'Die Kammer war versiegelt! Wie kann sie dann leer sein? Das macht kein\' Sinn...', 28153),
(140599, 'deDE', '', 'Was hat Jakra\'zet nur getan...', 28153),
(140596, 'deDE', 'Niemand hält... die Sande auf...', '', 28153),
(140595, 'deDE', 'Der Tempel muss fallen! Schlachtet alle ab, die sich uns in den Weg stellen.', '', 28153),
(140594, 'deDE', 'War mir ein Vergnügen, Geschäfte mit Euch zu machen. Wenn Ihr nichts dagegen habt, mache ich mich jetzt davon, bevor mich noch jemand vermisst.', '', 28153),
(140593, 'deDE', 'Und hier das offizielle Ornat der Schwertwasserkorsaren, wie versprochen. Jetzt seht Ihr aus wie anständige Kriminelle.', '', 28153),
(140592, 'deDE', 'Ihr werdet brechen wie Glas!', 'Ihr werdet brechen wie Glas!', 28153),
(140591, 'deDE', 'Für den Imperator!', 'Für den Imperator!', 28153),
(140590, 'deDE', 'Ihr habt\'s geschafft! Ich wusste, dieser Kläffer würde uns helfen. Der beste Freund des Menschen.', '', 28153),
(140589, 'deDE', 'Wir zertreten Euch wie ein Insekt!', 'Wir zertreten Euch wie ein Insekt!', 28153),
(140588, 'deDE', 'Wie Sand sollt Ihr verweht und vergessen werden!', 'Wie Sand sollt Ihr verweht und vergessen werden!', 28153),
(140587, 'deDE', 'Die Sande werden Euch verschlingen!', 'Die Sande werden Euch verschlingen!', 28153),
(140586, 'deDE', 'Wir herrschen über alles!', 'Wir herrschen über alles!', 28153),
(140585, 'deDE', 'Der Sand wandert! Ihr könnt ihn nicht aufhalten!', 'Der Sand wandert! Ihr könnt ihn nicht aufhalten!', 28153),
(140584, 'deDE', 'Euer Land wird als nächstes fallen!', 'Euer Land wird als nächstes fallen!', 28153),
(140583, 'deDE', 'Also... wie sieht\'s aus? Ihr wisst schon: Eine Hand wäscht die andere.', '', 28153),
(140582, 'deDE', 'Aber zuerst müsst Ihr mir einen Gefallen tun. Dieses Schloss will sich einfach nicht knacken lassen. Dieser Köter hat den Schlüssel, aber er entwischt mir immer wieder.', '', 28153),
(140581, 'deDE', 'Das werd ich genieß\'n!', 'Das werd ich genieß\'n!', 28153),
(140580, 'deDE', 'Jakra\'zet will Euch tot seh\'n.', 'Jakra\'zet will Euch tot seh\'n.', 28153),
(140579, 'deDE', 'Auf Euern Kopf is\' \'n Preis ausgesetzt!', 'Auf Euern Kopf is\' \'n Preis ausgesetzt!', 28153),
(140578, 'deDE', 'Wenn Ihr die Weltmeere unsicher machen wollt, solltet Ihr den Kapitänsrat treffen. Dabei kann ich helfen.', '', 28153),
(140576, 'deDE', 'Ich mach Euch \'nen Kopf kürzer!', 'Ich mach Euch \'nen Kopf kürzer!', 28153),
(140575, 'deDE', 'Jakra\'zet lässt Euch grüßen.', 'Jakra\'zet lässt Euch grüßen.', 28153),
(140574, 'deDE', 'Ahoi! Ihr seht wie echte Piraten aus. Anders als der Abschaum, der sich hier sonst rumtreibt.', '', 28153),
(140573, 'deDE', 'Wogender Stahl!', '', 28153),
(140572, 'deDE', 'En garde!', '', 28153),
(140571, 'deDE', '', 'Ich treff immer ins Ziel.', 28153),
(140570, 'deDE', '', 'Zappelt nur, ich treff\' Euch doch!', 28153),
(140569, 'deDE', 'Die Sache kommt ins Rollen!', '', 28153),
(140568, 'deDE', 'Jetzt geht\'s rund!', '', 28153),
(140567, 'deDE', 'Sucht Krag\'wa auf. Der Kleine wird Euch dort treff\'n.', '', 28153),
(140566, 'deDE', 'Ihr denkt, Ihr könnt es mit mir aufnehmen, Kanaille? Gestattet mir, Euch das Gegenteil zu beweisen.', '', 28153),
(140565, 'deDE', '', 'Dass \'n Sethrak um Gnade fleht, hab ich mein Lebtag nich\' geseh\'n. Vielleicht sagt er ja die Wahrheit.', 28153),
(140564, 'deDE', '', 'Wir hab\'n keine Zeit, Gefangene zu nehmen. Bringt\'s hinter Euch und richtet ihn hin.', 28153),
(140563, 'deDE', '', 'Alles Lügen! Die Sethrak mord\'n und plündern alles, was ihnen in die Quere kommt!', 28153),
(140562, 'deDE', 'Spürt den Zorn der See!', '', 28153),
(140561, 'deDE', 'Passt auf, wo Ihr hintretet.', '', 28153),
(140560, 'deDE', 'Ich bin Euch nicht feindlich gesinnt! Ihr müsst mir glauben!', '', 28153),
(140559, 'deDE', 'Begrabt mich... mit meiner Klinge...', '', 28153),
(140558, 'deDE', 'Ich tue Euch nichts zuleide! Bitte... tötet mich nicht!', '', 28153),
(140557, 'deDE', 'Ihr gehört mir!', 'Ihr gehört mir!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140556, 'deDE', 'Ihr werdet bereu\'n, hierher gekomm\' zu sein!', 'Ihr werdet bereu\'n, hierher gekomm\' zu sein!', 28153),
(140555, 'deDE', 'Wir ham Befehle, Euch zu töt\'n.', 'Wir ham Befehle, Euch zu töt\'n.', 28153),
(140554, 'deDE', 'Was auch immer Ihr da habt, das gehört bald mir!', 'Was auch immer Ihr da habt, das gehört bald mir!', 28153),
(140553, 'deDE', 'Werde ich je auf einen ebenbürtigen Gegner treffen?', '', 28153),
(140552, 'deDE', 'Das\'s nich\' Euer Kampf!', 'Das\'s nich\' Euer Kampf!', 28153),
(140551, 'deDE', 'Ihr habt zu viel geseh\'n, um Euch am Leb\'n zu lass\'n!', 'Ihr habt zu viel geseh\'n, um Euch am Leb\'n zu lass\'n!', 28153),
(140550, 'deDE', 'Ihr gehört hier nich\' her!', 'Ihr gehört hier nich\' her!', 28153),
(140549, 'deDE', 'Erstes Blut!', '', 28153),
(140548, 'deDE', 'Gegen mich macht Ihr keinen Stich.', '', 28153),
(140546, 'deDE', 'Lassen wir den Stahl sprechen!', '', 28153),
(140545, 'deDE', '', 'Fresst Schrot, Abschaum!', 28153),
(140544, 'deDE', '', 'Ich werde Euch wegpusten!', 28153),
(140542, 'deDE', '', 'Lauft nur, ich krieg Euch trotzdem!', 28153),
(140541, 'deDE', '', 'Ich hab Euch im Visier!', 28153),
(140540, 'deDE', '', 'Guter... Schuss...', 28153),
(140539, 'deDE', '', 'Oooh, ich hatte doch noch Kugeln geladen.', 28153),
(140538, 'deDE', '', 'Soll\'n sie sich doch um die Sethrak kümmern. Wir beide müss\'n diese Kammer aufmach\'n und Xal\'zaix find\'n.', 28153),
(140537, 'deDE', '', 'Genau zwischen die Augen.', 28153),
(140536, 'deDE', '', 'Pulverisiert...', 28153),
(140535, 'deDE', '', 'Eure Schädel geben ideale Zielscheiben ab.', 28153),
(140534, 'deDE', 'Macht sie nieder!', '', 28153),
(140533, 'deDE', 'Die Runde geht auf mich!', '', 28153),
(140532, 'deDE', 'Trinkt aus, Ihr faulen Hunde!', '', 28153),
(140531, 'deDE', 'Das wird nich\' funktionier\'n. Wir sin\' Rastakhan treu, nich\' diesem falschen Propheten.', '', 28153),
(140530, 'deDE', 'Hau ruck!', '', 28153),
(140529, 'deDE', 'Zapfenstreich!', '', 28153),
(140528, 'deDE', 'Wenn\'s nach mir geht, wird er höchstens \'ne Reise zu Bwonsamdi bekomm\'n.', '', 28153),
(140527, 'deDE', '', 'Ihr geht und stimmt die Sphäre ab. Der Rest von uns macht sich zu den Ruinen von Atul\'Aman auf, um die Kammer von Xal\'zaix zu such\'n.', 28153),
(140526, 'deDE', '', 'Schlimm genug, dass er die Flotte nach Pandaria geführt hat. Jetz\' will er ganz Zuldazar für sich allein hab\'n!', 28153),
(140525, 'deDE', '', 'Ich hab diesem teuflisch\'n Schwätzer Zul nie vertraut!', 28153),
(140524, 'deDE', 'Ich komm zurück, wenn ich fertig bin, Mutta.', '', 28153),
(140523, 'deDE', 'Das war... meine letzte Runde...', '', 28153),
(140522, 'deDE', 'Ich brech sofort auf, Mutta! Für Euch tu\' ich alles.', '', 28153),
(140521, 'deDE', 'Na dann, Prost!', '', 28153),
(140520, 'deDE', 'Vertragt wohl nix, was?', '', 28153),
(140519, 'deDE', 'Euer Wunsch is\' mir Befehl, Mutta!', '', 28153),
(140518, 'deDE', 'Wir brauch\'n mehr Stein im Lager. Geht und sammelt nur die reinsten Felsen in Nazmir. Un\' zwar sechzig davon.', 'Wir brauch\'n mehr Stein im Lager. Geht und sammelt nur die reinsten Felsen in Nazmir. Un\' zwar sechzig davon.', 28153),
(140517, 'deDE', 'Darauf trink ich erstmal einen.', '', 28153),
(140516, 'deDE', 'Wir brauch\'n mehr Holz im Lager. Geht und holt dreißig Scheite, aber ich will nur die makellosen!', 'Wir brauch\'n mehr Holz im Lager. Geht und holt dreißig Scheite, aber ich will nur die makellosen!', 28153),
(140515, 'deDE', 'Oh, Mutta! Ich wart hier, wie mir gesagt wurde.', '', 28153),
(140514, 'deDE', 'Wir brauch\'n fünfzig makellose Krokiliskenhäute. Holt sie ran un\' kommt nich\' zurück, bevor Ihr sie nich\' alle zusammen habt.', 'Wir brauch\'n fünfzig makellose Krokiliskenhäute. Holt sie ran un\' kommt nich\' zurück, bevor Ihr sie nich\' alle zusammen habt.', 28153),
(140513, 'deDE', 'Mutta! Was kann ich für Euch tun?', '', 28153),
(140512, 'deDE', 'Gefallen Euch meine hübschen Vögelchen?', '', 28153),
(140511, 'deDE', 'Wohin kann ich fliegen?', 'Wohin kann ich fliegen?', 28153),
(140510, 'deDE', '', 'Eure Seele gehört mir!', 28153),
(140509, 'deDE', '', 'Jetz\' untersteht Ihr meiner Macht!', 28153),
(140508, 'deDE', '', 'Eure Seele wird brech\'n!', 28153),
(140507, 'deDE', '', 'Ich werd Eure Seele zerreiß\'n!', 28153),
(140506, 'deDE', '', 'Für die Horde!', 28153),
(140505, 'deDE', 'Für die Horde!', '', 28153),
(140504, 'deDE', '', 'Für die Horde!', 28153),
(140503, 'deDE', '', 'Von diesem Tage an steht der Hochberg an Eurer Seite. Eure Feinde sind unsere Feinde.', 28153),
(140502, 'deDE', '', 'Ich akzeptiere Euren Treueeid. Die Horde bietet Euch Schutz... und erwartet Gehorsam von Euch.', 28153),
(140501, 'deDE', '', 'Kriegshäuptling, die Stärke und der Mut der Horde wurden sowohl von Baine Bluthuf als auch Eurem Champion eindrucksvoll unter Beweis gestellt.', 28153),
(140500, 'deDE', '', 'Nun, was habt Ihr zu sagen, Häuptling?', 28153),
(140499, 'deDE', 'Es ist der Horde eine Ehre, Euch willkommen zu heißen! Reisen wir gemeinsam nach Orgrimmar und informieren wir den Kriegshäuptling.', '', 28153),
(140498, 'deDE', '', 'Euren Segen vorausgesetzt, würde es die Tauren des Hochbergs mit Stolz erfüllen, sich der Horde anzuschließen.', 28153),
(140497, 'deDE', '', 'Baine Bluthuf, Ihr habt Tapferkeit, Ehre und Treue bewiesen. Es ist an der Zeit, die Blutbande zwischen unseren Völkern zu erneuern.', 28153),
(140496, 'deDE', 'Daran denke ich mit Schrecken, Mayla. Ohne das rasche Eingreifen von Baine und seinem Champion wäre alles verloren.', '', 28153),
(140495, 'deDE', '', 'Wäre Uul\'gyneths Plan erfolgreich gewesen, wären wir jetzt alle Sklaven der Alten Götter... selbst Ebenhorn.', 28153),
(140494, 'deDE', '', 'Der heutige Tag wäre beinahe ein düsterer für Azeroth geworden.', 28153),
(140493, 'deDE', '', 'Narren... Zul wird Eure Geister auslösch\'n.', 28153),
(140492, 'deDE', 'Das Flüstern... es ist verschwunden. Ich danke Euch, Champion, Grauhimmel.', '', 28153),
(140491, 'deDE', '', 'Ebenhorn leidet. Wir müssen einen Weg finden, ihn vor dem Abgrund zu bewahren. Sprecht mit Geistwandler Grauhimmel. Ich bin sicher, er kann helfen.', 28153),
(140490, 'deDE', 'Bis wir aufdecken, was hinter diesem Angriff steckt, ist Mulgore niemals in Sicherheit. Ich begleite Euch, Mayla. Stellen wir uns der Finsternis gemeinsam.', '', 28153),
(140489, 'deDE', '', 'Ich muss Ebenhorn schnellstmöglich zurück zum Hochberg bringen!', 28153),
(140488, 'deDE', 'Diese Macht ist mir nur zu vertraut. Champion! Wir brauchen Eure Hilfe!', '', 28153),
(140487, 'deDE', '', 'Ebenhorn! Welch finstere Macht hat Euch in ihren Fängen?', 28153),
(140486, 'deDE', 'Ich hätte den Berg... niemals... verlassen dürfen.', '', 28153),
(140485, 'deDE', 'Es sind diese Blutbande, über die ich sprechen möchte. Ich hoffe, da–', '', 28153),
(140484, 'deDE', '', 'Eure Einladung war überaus freundlich, Baine. Es ist Zeit, die Blutbande zwischen unseren Völkern zu erneuern.', 28153),
(140483, 'deDE', 'Ich danke Euch für Euer Kommen, Mayla. Es ehrt mich, Euch in Mulgore willkommen zu heißen.', '', 28153),
(140482, 'deDE', '', 'Euer Blut is\' meins.', 28153),
(140481, 'deDE', '', 'Euer Blut wird uns gute Dienste leist\'n... Ihr braucht\'s ja sowieso nich\' mehr.', 28153),
(140480, 'deDE', '', 'Dazar erwacht bald, aber das erlebt Ihr nich\' mehr!', 28153),
(140479, 'deDE', 'Unsere Truppen wurden jetzt mit Stahlrüstung ausgestattet!', 'Unsere Truppen wurden jetzt mit Stahlrüstung ausgestattet!', 28153),
(140478, 'deDE', '$gEin Meuterer:Eine Meuterin;, was? Holt $gihn:sie; Euch!', '$gEin Meuterer:Eine Meuterin;, was? Holt $gihn:sie; Euch!', 28153),
(140477, 'deDE', 'Los, Finger weg da!', 'Los, Finger weg da!', 28153),
(140476, 'deDE', 'Was macht Ihr\'n da?!', 'Was macht Ihr\'n da?!', 28153),
(140471, 'deDE', 'Unsere Truppen wurden jetzt mit Stahlwaffen ausgestattet!', 'Unsere Truppen wurden jetzt mit Stahlwaffen ausgestattet!', 28153),
(140470, 'deDE', 'Kann\'s aushalten, Mutta! Bin bereit für\'n Kampf!', '', 28153),
(140469, 'deDE', 'Ich bin nich\' schwach, ich fühl kein\'n Schmerz! Ich bin bereit zu töt\'n!', '', 28153),
(140468, 'deDE', 'Ich kann noch mehr Schmerz ertrag\'n! Ich werd alles töt\'n, was mir inne Quere kommt!', '', 28153),
(140467, 'deDE', 'Ich bin stark! Ich kann noch mehr einsteck\'n, Mutta!', '', 28153),
(140464, 'deDE', '$n, sagt dieser Kreatur, dass Ihr mich kennt. Er kann mich nich\' länger so einsperr\'n!', '', 28153),
(140463, 'deDE', 'Abreißen', 'Abreißen', 28153),
(140462, 'deDE', 'Aaah. Das schmiert die Kehle.', '', 28153),
(140461, 'deDE', 'Da, für Euch. Trinken wir auf bessere Zeiten!', '', 28153),
(140460, 'deDE', 'Ja?', '', 28153),
(140459, 'deDE', '', 'Ihr gebt \'n gutes Opfer ab!', 28153),
(140458, 'deDE', '', 'Springt auf! Wir sin\' vielleicht schon zu spät!', 28153),
(140457, 'deDE', 'Meister wird mich neu mach\'n...', '', 28153),
(140456, 'deDE', 'Meister nimmt Stücke von Euch. Macht mich stärker!', '', 28153),
(140455, 'deDE', 'Fleisch für den Meister!', '', 28153),
(140454, 'deDE', 'Ich reiß Euch in Stücke.', '', 28153),
(140453, 'deDE', 'Ihr sterbt mit mir!', '', 28153),
(140452, 'deDE', 'Nich\' kaputt mach\'n!', '', 28153),
(140451, 'deDE', 'Werde schwächer!', '', 28153),
(140450, 'deDE', 'Nich\' Totem zerstör\'n!', '', 28153),
(140449, 'deDE', 'Neeiiin!', '', 28153),
(140448, 'deDE', 'Zerschmettern!', '', 28153),
(140447, 'deDE', 'Vernicht\'n!', '', 28153),
(140446, 'deDE', 'Ihr?! Ich werd\' Euch zerstückeln!', '', 28153),
(140445, 'deDE', '', 'Endlich seid Ihr hier. Die Elemente haben von Eurer Ankunft geflüstert...', 28153),
(140444, 'deDE', 'Zissiah und ich eilen voraus und kündigen Vorrik Eure Ankunft an.', '', 28153),
(140441, 'deDE', 'Was könnt Ihr mir sonst noch erzählen?', 'Was könnt Ihr mir sonst noch erzählen?', 28153),
(140439, 'deDE', 'Wer sind die Treulosen?', 'Wer sind die Treulosen?', 28153),
(140438, 'deDE', 'Die Treulosen werden ihre Belagerung niemals aufgeben, aber Eure Bemühungen haben uns etwas Zeit verschafft. Wir werden unseren Loa finden und diesem Kampf ein Ende bereiten.', '', 28153),
(140437, 'deDE', 'Die Treulosen belagern unser Zuhause. Wir müssen sie zurückdrängen! Sie dürfen den Tempel nicht erobern.', '', 28153),
(140436, 'deDE', 'Ach, Ihr seid $g\'n Spielverderber:\'ne Spielverderberin;!', 'Ach, Ihr seid $g\'n Spielverderber:\'ne Spielverderberin;!', 28153),
(140435, 'deDE', 'Hach, is\' auch egal. Dann geh ich eben nach Hause!', 'Hach, is\' auch egal. Dann geh ich eben nach Hause!', 28153),
(140434, 'deDE', 'Grrr! Grrr grrr gr... Oh!', 'Grrr! Grrr grrr gr... Oh!', 28153),
(140433, 'deDE', 'Mann, Ihr seid \'n echter Miesepeter.', 'Mann, Ihr seid \'n echter Miesepeter.', 28153),
(140432, 'deDE', 'Ja! Größer zu sein, is\' viel lustiger!', 'Ja! Größer zu sein, is\' viel lustiger!', 28153),
(140431, 'deDE', 'Juhu! Das macht Spaß... Ähm, ich mein... \"Grrr\"!', 'Juhu! Das macht Spaß... Ähm, ich mein... \"Grrr\"!', 28153),
(140430, 'deDE', 'Aufpass\'n da! Ich kann nich\' seh\'n, wo ich hinstapfe!', 'Aufpass\'n da! Ich kann nich\' seh\'n, wo ich hinstapfe!', 28153),
(140429, 'deDE', 'Ich bin \'n mächtiger Raptor, genau wie Gonk! Hahaha!', 'Ich bin \'n mächtiger Raptor, genau wie Gonk! Hahaha!', 28153),
(140428, 'deDE', '', 'Ach, Ihr seid $g\'n Spielverderber:\'ne Spielverderberin;!', 28153),
(140427, 'deDE', '', 'Hach, is\' auch egal. Dann geh ich eb\'n nach Haus!', 28153),
(140426, 'deDE', '', 'Grrr! Grrr grrr gr... Oh!', 28153),
(140425, 'deDE', '', 'Mann, was für \'n Miesepeter.', 28153),
(140424, 'deDE', 'Macht sie kalt. Unsre Arbeit hier is\' fast erledigt!', '', 28153),
(140423, 'deDE', '', 'Ja! Größer zu sein, is\' viel lustiger!', 28153),
(140422, 'deDE', '', 'Juchhu! Das macht so\'n Spaß... Ähm, ich mein... \"Grrr\"!', 28153),
(140421, 'deDE', '', 'Aufpass\'n da! Ich kann nich\' seh\'n, wo ich hinstapfe!', 28153),
(140420, 'deDE', '', 'Ich bin \'n mächtiger Raptor, genau wie Gonk! Hahaha!', 28153),
(140419, 'deDE', 'Mann, was für \'n Miesepeter.', '', 28153),
(140418, 'deDE', 'Grrr! Grrr grrr gr... Oh!', '', 28153),
(140417, 'deDE', 'Hach, is\' auch egal. Dann geh ich eben nach Hause!', '', 28153),
(140416, 'deDE', 'Ach, Ihr seid $g\'n Spielverderber:\'ne Spielverderberin;!', '', 28153),
(140415, 'deDE', 'Ich bin \'n mächtiger Ravasaurus, genau wie Gonk! Hahaha!', '', 28153),
(140414, 'deDE', 'Aufpass\'n da! Ich kann nich\' seh\'n, wo ich hinstapfe!', '', 28153),
(140413, 'deDE', 'Juchhu! Das macht so\'n Spaß... Ähm, ich mein... \"Grrr\"!', '', 28153),
(140412, 'deDE', 'Ja! Größer zu sein, is\' viel lustiger!', '', 28153),
(140411, 'deDE', 'Meister will Eure Knochen!', '', 28153),
(140410, 'deDE', 'Krah! Elende Landratten! Krah!', '', 28153),
(140409, 'deDE', 'Krah! Breitseite! Krah!', '', 28153),
(140408, 'deDE', 'Krah! Seebestattung! Krah!', '', 28153),
(140407, 'deDE', 'Krah! Ruf der Natur! Krah!', '', 28153),
(140406, 'deDE', 'Krah! Landliebendes Pack! Krah!', '', 28153),
(140405, 'deDE', 'Haha! Macht Euch nicht ins Hemd!', '', 28153),
(140404, 'deDE', 'Zeit für eine... Seebestattung...', '', 28153),
(140403, 'deDE', 'Ihr seid Fraß für die Haie!', '', 28153),
(140402, 'deDE', 'Der Meeresgrund wartet!', '', 28153),
(140401, 'deDE', 'Wohl bekomm\'s!', '', 28153),
(140400, 'deDE', 'Ahaha! Alles Gute kommt von oben!', '', 28153),
(140399, 'deDE', 'Volle Breitseite!', '', 28153),
(140398, 'deDE', 'Euch heiz\' ich ein!', '', 28153),
(140397, 'deDE', 'Ihr steht auf meiner Abschussliste!', '', 28153),
(140396, 'deDE', 'Mein Gesöff! Das war Euer letzter Fehler...', '', 28153),
(140395, 'deDE', 'Oh, was für eine Verschwendung!', '', 28153),
(140394, 'deDE', 'Ah! Jetzt hab ich alles verschüttet wegen Euch!', '', 28153),
(140393, 'deDE', 'Keine Gnade!', '', 28153),
(140392, 'deDE', 'Rammgeschwindigkeit!', '', 28153),
(140391, 'deDE', 'Zandalari sterb\'n nie!', '', 28153),
(140390, 'deDE', 'Zeit für ein bisschen Blutvergießen.', '', 28153),
(140389, 'deDE', 'Geht mit den Geistern.', '', 28153),
(140388, 'deDE', 'Ich höre den Ruf!', '', 28153),
(140387, 'deDE', 'Na gut... Jetz\', $n!', '', 28153),
(140386, 'deDE', 'Gnade? Dummes Insekt! Wir werden Euch und ganz Zuldazar auslöschen!', '', 28153),
(140385, 'deDE', 'Großer Hir\'eek! Wir fleh\'n um Gnade, oh Mächtiger... Verschont uns!', '', 28153),
(140384, 'deDE', 'Aaaangriff!', '', 28153),
(140383, 'deDE', 'Jo\'chunga, ich bin bereit. Lasst uns unseren Plan in die Tat umsetzen und Hir\'eek aufhalten.', 'Jo\'chunga, ich bin bereit. Lasst uns unseren Plan in die Tat umsetzen und Hir\'eek aufhalten.', 28153),
(140382, 'deDE', 'Oh, das is\' Wahnsinn... Als das alles angefang\'n hat, hab ich nich\' gewusst, dass ich mich freiwillig melde, um \'nen LOA zu töten.', '', 28153),
(140381, 'deDE', 'Aaargh! Haihappen, verpass ihnen eine Breitseite!', '', 28153),
(140380, 'deDE', 'Meine Diener... lasst ab. Ihr Frevler, tretet vor und seht Eurem Ende ins Auge... Euer Blut wird G\'huun speisen!', '', 28153),
(140379, 'deDE', 'Nehmt Euch in Acht da unten, landliebendes Pack!', '', 28153),
(140378, 'deDE', 'Der letzte Schlag!', '', 28153),
(140377, 'deDE', 'Ich werde Eurer überdrüssig!', '', 28153),
(140376, 'deDE', 'Sterbt jetzt, und seid still!', '', 28153),
(140375, 'deDE', 'Hier gibt es viele Trolle, aber die wollen nicht kämpfen.$b$bSo werden sie nie in die Hallen der Tapferkeit gelangen. Man muss nach Ruhm auf dem Schlachtfeld streben!$b$bWo ist ihr König? Der würde das verstehen. Der kann vielleicht sogar halbwegs anständig kämpfen!', '', 28153),
(140374, 'deDE', 'Seid Ihr zum Kämpfen hier? Ich könnte ein gutes Duell vertragen.', '', 28153),
(140373, 'deDE', '', 'Wir wollen uns durch den Kampf verbessern und den Ruhm erlangen, der uns in die Hallen der Tapferkeit bringt.$b$bDer König hier ist stark und herrscht schon seit Hunderten von Jahren. Er wäre ein würdiger Gegner. Wir müssen uns einfach nur mit dem König treffen und ihn zu einem glorreichen Kampf herausfordern!', 28153),
(140372, 'deDE', '', 'Göttlicher Ansturm!', 28153),
(140371, 'deDE', '', 'Mein Sieg soll sich in Eure Seele einbrennen!', 28153),
(140370, 'deDE', '', 'Kommt, $gKrieger:Kriegerin;! Die Schlacht erwartet uns!', 28153),
(140369, 'deDE', 'Bomben los!', '', 28153),
(140368, 'deDE', '', 'Ich suche edle Krieger, die sich mir im Kampf anschließen möchten.', 28153),
(140367, 'deDE', 'Nehmt es Haihappen nicht übel. Er folgt einfach dem Ruf der Natur!', '', 28153),
(140366, 'deDE', 'Euer Untergang naht!', '', 28153),
(140364, 'deDE', 'Haihappen, Anker lichten und Leinen los! Wir müssen uns um diese Landratten kümmern!', '', 28153),
(140363, 'deDE', 'Eindringlinge!', '', 28153),
(140362, 'deDE', 'Ich hoffe, Ihr habt Euer Testatment gemacht!', '', 28153),
(140361, 'deDE', 'Hiergeblieben, Ihr elenden Landratten!', '', 28153),
(140360, 'deDE', 'Wen soll ich töt\'n?', '', 28153),
(140359, 'deDE', '', 'Wir halten die Insel und sagen Bescheid, wenn es was Neues gibt!', 28153),
(140358, 'deDE', 'Lang lebe der König!', '', 28153),
(140357, 'deDE', 'Bwonsamdi gibt mir noch \'ne Chance!', '', 28153),
(140356, 'deDE', 'Taz\'dingo!', '', 28153),
(140355, 'deDE', '', 'Das Gold gehorcht meiner Macht!', 28153),
(140354, 'deDE', '', 'Ihr gehört nich\' hierher!', 28153),
(140353, 'deDE', '', 'Meine Klauen wer\'n Euer Herz finden.', 28153),
(140352, 'deDE', '', 'Verlieren wir keine Zeit. Wir warten oben bei der Höhle auf Euch!', 28153),
(140335, 'deDE', 'Jetz\' wird\'s ernst. Wenn das nich\' klappt, sin\' wir mausetot.', '', 28153),
(140334, 'deDE', 'Oh nein... Hir\'eek!', '', 28153),
(140333, 'deDE', 'Prinzessin Talanji will unbedingt wiss\'n, was hier in den Sümpfen passiert.', '', 28153),
(140332, 'deDE', '', 'Das Gold folgt mei\'m Ruf.', 28153),
(140331, 'deDE', '', 'Die Verderbnis werde geläutert!', 28153),
(140330, 'deDE', '', 'Atal\'Dazars Macht fließt durch mich!', 28153),
(140329, 'deDE', '', 'Jetzt seid Ihr geläutert!', 28153),
(140328, 'deDE', '', 'Der Tod is\' Euer richtiges Schicksal.', 28153),
(140327, 'deDE', '', 'Die Becken... müss\'n... geläutert werd\'n.', 28153),
(140326, 'deDE', '', 'Nur wer würdig is\', wird hier bestattet. Mit EUREN Überbleibseln fütter ich die Raptor\'n.', 28153),
(140325, 'deDE', '', 'Ihr hättet niemals herkomm\' dürf\'n.', 28153),
(140324, 'deDE', '', 'Ihr kommt wegen dem Gold, aber Ihr lasst Eure Knochen zurück!', 28153),
(140323, 'deDE', '', 'Diener von Yazma sin\' hier nicht willkommen!', 28153),
(140322, 'deDE', 'Tretet vor! Ich werde mich allein Eurer annehmen.', '', 28153),
(140321, 'deDE', 'Talanji hat uns hierhergeschickt, damit wir die Gerüchte über Monster im Sumpf untersuch\'n. Aber was wir gefund\'n ham, is\' noch viel schlimmer: Die erschaff\'n die Monster...', '', 28153),
(140320, 'deDE', 'Dachte, Ihr habt den Löffel abgegeben! Sagt nicht, Ihr arbeitet für diese Stiefellecker!', '', 28153),
(140319, 'deDE', 'Ist... eine lange Geschichte. Habt Ihr ein Kühles?', '', 28153),
(140318, 'deDE', 'Ich hab Euch Eisenflutknallköppen doch gesagt... Was zum... Finn?!', '', 28153),
(140317, 'deDE', 'Ahem... FLOSSEN HOCH, schleimige Meerwarze! Rückt die Beute raus!', '', 28153),
(140316, 'deDE', '', 'Wasss? Nein! Wasss... ist diessse... Macht...', 28153),
(140315, 'deDE', 'Willkommen bei der Goldhauerbande, $p. Ihr seid jetzt Familie!', '', 28153),
(140314, 'deDE', '', 'Habt Ihr jemals einem Sethrak \'nen so hart\'n Hieb verpasst, dass sein Schwanz abgefall\'n ist?', 28153),
(140313, 'deDE', 'Ihr habt die Muckis und ich hab das Hirn.\n\nWir sin\' das perfekte Team.', '', 28153),
(140312, 'deDE', '', 'Keine Sorge. Ich reparier\' die Trommel in null Komma nix.', 28153),
(140311, 'deDE', '', 'Das sagten die Vögel vorher!', 28153),
(140310, 'deDE', '', 'Nur meine Spielsachen...', 28153),
(140309, 'deDE', '', 'Kein Tanzen und Lachen...', 28153),
(140308, 'deDE', '', 'Man hört keine Leute mehr.', 28153),
(140307, 'deDE', 'Einsammeln', 'Einsammeln', 28153),
(140306, 'deDE', '', 'Azshara... Ich habe Euch enttäuscht...', 28153),
(140305, 'deDE', '', 'Meine Königin wird von Eurem Tod entzückt sssein. Nazjatar wird sssich erheben!', 28153),
(140303, 'deDE', 'Trinkt was mit mir und Finn! Geht auf\'s Haus!$b$bWas darf\'s sein?', '', 28153),
(140302, 'deDE', 'Milch... in einem Schädelbecher.', 'Milch... in einem Schädelbecher.', 28153),
(140301, 'deDE', 'Milch.', 'Milch.', 28153),
(140300, 'deDE', 'Bier.', 'Bier.', 28153),
(140299, 'deDE', '|TInterface\\Icons\\INV_AMMO_BULLET_03:20|t%s setzt |cFFFF0000|Hspell:256044|h[Zielwasser]|h|r gegen Euch ein und feuert ein Geschoss auf Euch!', '', 28153),
(140298, 'deDE', 'Vorsicht da draußen. Da braut sich was zusammen.', '', 28153),
(140297, 'deDE', 'Ihr seid hier immer willkommen, $p. Ihr seid jetzt \'n Ehrenmitglied vonner Goldhauerbande.', '', 28153),
(140296, 'deDE', 'Der Goldhauer is\' hiermit offiziell eröffnet!', '', 28153),
(140295, 'deDE', 'Danke, dass Ihr mich gerettet habt...', '', 28153),
(140294, 'deDE', 'Ich schätze, ich bleib\' \'ne Weile hier und helfe, wo ich kann.', '', 28153),
(140293, 'deDE', 'Unglaublich, dass ich Euch wiedergefund\'n hab, $p. Ich bin erschöpft...', '', 28153),
(140292, 'deDE', 'Ich würd\' Euch ja für verrückt halt\'n, aber Ihr habt mich grad gerettet. Danke.', '', 28153),
(140291, 'deDE', 'Ihr habt diesen Verbannten geholf\'n, ein Gasthaus hier mitten im Nichts aufzumach\'n?', '', 28153),
(140290, 'deDE', 'Die Treulos\'n ham mich durch die Wüste gejagt, durch wilde Bestien und Monster. Fast hätt\' ich\'s nich\' überlebt.', '', 28153),
(140289, 'deDE', 'Diese verrückten Bluttrolle benutz\'n unsere Leute als Fledermausfutter!', 'Diese verrückten Bluttrolle benutz\'n unsere Leute als Fledermausfutter!', 28153),
(140288, 'deDE', 'Diese Dinger wollt\'n mein Blut für diese Fledermäuse!', 'Diese Dinger wollt\'n mein Blut für diese Fledermäuse!', 28153),
(140287, 'deDE', 'Danke, die wollt\'n mich dies\'n Fledermäusen opfern!', 'Danke, die wollt\'n mich dies\'n Fledermäusen opfern!', 28153),
(140286, 'deDE', 'Die wollt\'n mich an die Fledermäuse verfüttern!', 'Die wollt\'n mich an die Fledermäuse verfüttern!', 28153),
(140285, 'deDE', 'Königin Azshara wirkt ziemlich verzweifelt. Zumindest werden wir ihr einen dicken Strich durch die Rechnung machen.$B$BIch finde das sehr amüsant.', '', 28153),
(140283, 'deDE', 'Eure Tarnung is\' weg! Warum is\' meine noch da? Hmm... Schätze, das ändert die Sache.', '', 28153),
(140282, 'deDE', '$n! Was macht Ihr da?', '', 28153),
(140281, 'deDE', 'Uh, mir is\' schwindelig... Bwonsamdi hatte mich schon geruf\'n.', '', 28153),
(140280, 'deDE', '', 'Ich weiß, was Ihr denkt: \"Haben die Zandalaritrolle nicht die Goblins versklavt und zur Minenarbeit gezwungen?\"$b$bAber wenn wir nicht mit unseren Feinden handeln, handeln sie einfach nur untereinander. Und das ist schlecht fürs Geschäft.', 28153),
(140279, 'deDE', '', 'Dank ist nicht erforderlich.', 28153),
(140278, 'deDE', 'Dank ist nicht erforderlich.', '', 28153),
(140277, 'deDE', 'Gern geschehen.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140276, 'deDE', '', 'Gern geschehen.', 28153),
(140275, 'deDE', 'Es ist mir eine Ehre zu dienen.', '', 28153),
(140274, 'deDE', '', 'Es ist mir eine Ehre zu dienen.', 28153),
(140273, 'deDE', '', 'Nicht der Rede wert.', 28153),
(140272, 'deDE', 'Nicht der Rede wert.', '', 28153),
(140271, 'deDE', '', 'Das Vergnügen war ganz meinerseits.', 28153),
(140270, 'deDE', 'Das Vergnügen war ganz meinerseits.', '', 28153),
(140269, 'deDE', 'Es war mir ein Vergnügen.', '', 28153),
(140268, 'deDE', '', 'War mir ein Vergnügen.', 28153),
(140267, 'deDE', '', 'Ohne Zweifel.', 28153),
(140266, 'deDE', 'Ohne Zweifel.', '', 28153),
(140265, 'deDE', 'Das ist korrekt.', '', 28153),
(140264, 'deDE', 'Mein erstes Getränk in Vol\'dun. Ich bin seit dem Angriff in den Dünen rumgeirrt!', '', 28153),
(140263, 'deDE', '', 'Das ist korrekt.', 28153),
(140262, 'deDE', 'Was macht Ihr denn hier draußen, $p? Ich dachte, Ihr seid tot!', '', 28153),
(140261, 'deDE', 'Jawohl.', '', 28153),
(140260, 'deDE', '', 'Jawohl.', 28153),
(140259, 'deDE', '', 'Ohne Frage.', 28153),
(140258, 'deDE', 'Ohne Frage.', '', 28153),
(140257, 'deDE', 'Wartet hier.', '', 28153),
