(140160, 'deDE', '~DO NOT TRANSLATE', '', 28153),
(140159, 'deDE', 'Grozztok, kümmert Euch um die Eindringlinge. Enttäuscht mich nich\' nomma.', '', 28153),
(140158, 'deDE', 'Ruhe! Wir sin\' nich\' allein...', '', 28153),
(140157, 'deDE', 'Wir komm\' nich\' rein. Das Tor is\' mit Magie versiegelt, die wir noch nie geseh\'n ham.', '', 28153),
(140156, 'deDE', 'Es war \'n großer Fehler, in die Sande zu komm\'. Die Prinzessin kann Euch jetz\' nich\' mehr rett\'n.', '', 28153),
