(140110, 'deDE', 'Folgt mir.', '', 28153),
(140109, 'deDE', 'Das hier bleibt unter uns, ja, $p? Goldhauergeheimnis.', '', 28153),
(140108, 'deDE', 'Hmm, diese Frucht sieht lecker aus! Wir brauch\'n sie auf dem Buffet.', '', 28153),
(140107, 'deDE', 'Während Ihr uns was Obst besorgt, mach ich Skorpiden-Frühstücksspieße!', '', 28153),
(140106, 'deDE', 'Die Schuppen von $n sind von statischer Elektrizität erfüllt!', 'Die Schuppen von $n sind von statischer Elektrizität erfüllt!', 28153),
(140105, 'deDE', '', 'Der erste Flug gehört Euch, wenn Ihr wollt, $p. Sagt einfach Bescheid, wenn Ihr irgendwo hinflieg\'n wollt.', 28153),
(140104, 'deDE', '', 'Passt auf Saurolisken auf, die auf Felsvorsprüngen über Euch lauern... Die spring\'n gern mal runter.', 28153),
