(140092, 'deDE', '', 'Rückzug!', 28153),
(140091, 'deDE', 'Mög\'n die Loa Euch schnell leit\'n. Ihr müsst den König warnen, bevor\'s zu spät is\'!', '', 28153),
(140090, 'deDE', 'Wir treff\'n Euch bei Kaos Kriegsschiff, sobald der Weg frei is\'. Geht mit den Geistern.', '', 28153),
(140089, 'deDE', 'Ja.', '', 28153),
(140088, 'deDE', '', 'Ja.', 28153),
(140087, 'deDE', 'Ja.', '', 28153),
(140086, 'deDE', '', 'Ja.', 28153),
(140085, 'deDE', 'Ihr findet unsre Krieger auf der ob\'ren Terrasse. Für Zuldazar!', '', 28153),
