INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140020, 'deDE', '<Sighing sound>', '', 28153),
(140019, 'deDE', 'Ist doch selbstverständlich.', '', 28153),
(140018, 'deDE', 'Hocherfreut.', '', 28153),
(140017, 'deDE', 'Keine Ursache.', '', 28153),
(140016, 'deDE', 'Tausend Dank.', '', 28153),
(140015, 'deDE', 'Ich kann Euch nicht genug danken.', '', 28153),
(140014, 'deDE', 'Ich stehe in Eurer Schuld.', '', 28153),
(140013, 'deDE', '<Train noises--chugga chugga choo choo!>', '', 28153),
(140012, 'deDE', 'Bleibt hier.', '', 28153),
(140011, 'deDE', 'Geht nicht fort.', '', 28153),
(140010, 'deDE', 'So ist es.', '', 28153),
(140009, 'deDE', 'Richtig.', '', 28153),
(140008, 'deDE', 'Ja.', '', 28153),
(140004, 'deDE', 'Ich beneide Euch... Ihr seht die Geburt eines neu\'n Trollimperiums mit eig\'nen Augen. Schade, dass Rastakhan nich\' mit dabei sein kann.', '', 28153),
(140003, 'deDE', 'Die Mogu ham ihren Teil getan: die Leibwächter von ihrem König wegzulock\'n.', '', 28153),
(140002, 'deDE', 'Die Prophezeiung erfüllt sich. Das hier is\' nur \'ne Ablenkung, während Zul seine Pläne umsetzt.', '', 28153),
(140001, 'deDE', 'Vilnak\'dor! Kao lügt hoffentlich, sonst kommt Ihr als Nächstes dran!', '', 28153),
(140000, 'deDE', '', 'Der König?', 28153),
(139999, 'deDE', 'Einerlei... Das Ende Eures Königs... ist nah...', '', 28153),
(139998, 'deDE', 'Ich wusst\', dass wir diesem Schuft nicht vertrau\'n könn\'! Dafür wird er büß\'n!', '', 28153),
(139997, 'deDE', 'Zul hat uns ein neues Imperium versprochen und wir werden es bekommen!', '', 28153),
(139996, 'deDE', 'Schaut Euch um, Kao. Ihr habt schon verlor\'n! Legt Eure Waffen nieder!', '', 28153),
(139995, 'deDE', 'Ich bin die Macht des Donners. Der Schrecken der Steppen. Ihr könnt mich nicht besiegen!', '', 28153),
(139994, 'deDE', '', 'Wir sin\' Zandalari! Wir geb\'n niemals auf!', 28153),
(139993, 'deDE', 'Zuldazar ist unser Geburtsrecht. Unterwerft Euch und wir gewähren Euch einen gnädigen Tod.', '', 28153),
(139992, 'deDE', 'Hmpf. Ich hatte eine größere Herausforderung erwartet.', '', 28153),
(139991, 'deDE', 'Taz\'dingo! Für König Rastakhan!', '', 28153),
(139990, 'deDE', '', 'Habutu, Ihr müsst König Rastakhan von Zuls Verrat bericht\'n. $p un\' ich kümmern uns um diesen Grobian.', 28153),
(139989, 'deDE', 'Ankunft der Zandalariflotte', 'Ankunft der Zandalariflotte', 28153),
(139988, 'deDE', 'Lasst mich mal Eure Hüte sehen.', 'Lasst mich mal Eure Hüte sehen.', 28153),
(139987, 'deDE', 'Ihr seid zurück?\n\nIch mein... Hey, Ihr habt\'s geschafft!\n\nBevor mich Eure Schritte erschreckt hab\'n, hab ich mit Zulsan das Gasthaus sauber gemacht. Wie versproch\'n. Sieht man doch, oder?', '', 28153),
(139986, 'deDE', 'Dann lasst mal Eure Steine sehen!', 'Dann lasst mal Eure Steine sehen!', 28153),
(139985, 'deDE', 'Ich hab gute Idee: Ihr kauft zwei Hüte, tragt einen und gebt anderen an Freund, Familie, Kumpel. Mir total egal.', '', 28153),
(139984, 'deDE', 'Natürlich verkauf ich zwei Hüte auf einmal. Ich hab zwei Köpfe!$b$bIch sehe, Ihr habt nur einen Kopf. Tut mir leid für Euch. Aber Ersatzhut ist auch gut!', '', 28153),
(139983, 'deDE', 'Ihr wollt Hüte kaufen? Ich hab Hüte! Zwei kaufen, zwei bezahlen!', '', 28153),
(139982, 'deDE', 'Ihr wollt groß und stark sein als wie Velz\'brok? Ihr kaufen meine Steine, Ihr heben meine Steine, Ihr schmeißen meine Steine. Dann Ihr werden vielleicht groß und stark.$b$bAber vielleicht nicht so groß und stark wie ich.', '', 28153),
(139981, 'deDE', 'Kauft Steine von Velz\'brok! Ich hab besteste Steine, Ihr kaufen für guten Preis!', '', 28153),
(139980, 'deDE', 'Hey, Ihr! Wollt Ihr \'nen Stein kaufen? Ich hab die besten Steine.', '', 28153),
(139979, 'deDE', 'Das Herz von Sethraliss leuchtet rot. Was hat das zu bedeuten?', 'Das Herz von Sethraliss leuchtet rot. Was hat das zu bedeuten?', 28153),
(139978, 'deDE', 'Wir müssen stark bleiben.', 'Wir müssen stark bleiben.', 28153),
(139977, 'deDE', 'Der Totmannpass is\' einfach zu find\'n, er is\' bei den bedrohlich\'n dunklen Felsen im Nordwesten. Das wird \'n Riesenspaß!', '', 28153),
(139976, 'deDE', 'In der Nähe von ihrem Lager werdet Ihr in eine von denen verwandelt. Aber passt auf! Die Tarnung is\' nich\' perfekt.', '', 28153),
(139975, 'deDE', 'Die Bluttrollfrauen befehl\'n die Kriegsmeuten, also müsst Ihr wie eine aussehen. Lasst mich mal mach\'n, das krieg ich hin.', '', 28153),
(139974, 'deDE', 'Ich warn\' Euch ma\': Wird \'n bisschen wehtun... Naja, vielleicht \'n bisschen mehr!', '', 28153),
(139727, 'deDE', 'Ich bin bereit, mit dem Ritual zu beginnen, um mich als Bluttroll auszugeben.', 'Ich bin bereit, mit dem Ritual zu beginnen, um mich als Bluttroll auszugeben.', 28153),
(139726, 'deDE', 'Hier gibt\'s echt schlimmes Voodoo in der Gegend.', '', 28153),
(139592, 'deDE', 'Wenn Ihr mich braucht, dann könnt Ihr so weit von Izarn weg wie möglich nach mir such\'n.', '', 28153),
(139567, 'deDE', 'Wie ich seh, habt Ihr während meiner Abwesenheit neue Freunde gefund\'n.', '', 28153),
(139482, 'deDE', '', 'Haltet diese Kreuzung! Wir müss\'n den Vormarsch der Mogu aufhalt\'n.', 28153),
(139443, 'deDE', 'Euer Freund darf gehen, ich würde jedoch ein Auge auf ihn halten.', '', 28153),
(139410, 'deDE', 'Sofort.', '', 28153),
(139408, 'deDE', 'Die Stadt is\' in Aufruhr. Wir müssen für Eure Sicherheit sorg\'n!', '', 28153),
(139406, 'deDE', 'Mein König, wir können nich\' von Eurer Seite weich\'n.', '', 28153),
(139401, 'deDE', 'Ihr hattet Eure Chance. Solang ich herrsche, werd\'n die Zandalari nie mehr in Angst vor Euren Viechern leb\'n.', '', 28153),
(139397, 'deDE', 'Meine Soldaten werd\'n die Stadt nach weiteren durchkämm\'n.', '', 28153),
(139391, 'deDE', 'Ich schulde Euch mein Leben, $p. Trefft mich im Tempel. Hier ist es nicht sicher.', '', 28153),
(139390, 'deDE', '', 'He! Weniger quatschen, mehr helfen. Verlagern wir die Jagd auf\'s Wasser!', 28153),
(139389, 'deDE', 'Bruder Therold! Lord Sturmsang! Was für ein Glück, dass Ihr hier seid! Wir benötigen Eure Hilfe!', '', 28153),
(139388, 'deDE', 'Trefft mich bei den andren, wenn Ihr mein Zeug habt. Wir müss\'n uns vorbereit\'n.', '', 28153),
(139387, 'deDE', 'Ihr da! Kommt her, bevor mir diese Schläger den Rest geb\'n.', '', 28153),
(139386, 'deDE', 'Sie könn\' uns unser Land nehm\', aber niemals unsre unsterblich\'n Seel\'n.', '', 28153),
(139385, 'deDE', 'Ich danke Euch. Ich werde alleine hinausfinden.', 'Ich danke Euch. Ich werde alleine hinausfinden.', 28153),
(139384, 'deDE', 'Hier drüben! Wir beschütz\'n Kaza\'jins Schmuck mit unsrem Leben.', 'Hier drüben! Wir beschütz\'n Kaza\'jins Schmuck mit unsrem Leben.', 28153),
(139383, 'deDE', '', 'Bereitmachen, Sturmtakler! Diese Kreaturen sind anders als alles, was wir kennen!', 28153),
(139375, 'deDE', 'Passt auf, wo Ihr hintretet. Die Ranishu fressen alles... und das meine ich wortwörtlich.', '', 28153),
(139374, 'deDE', '', 'Taji sollte sich auf dem Hügel im Süden befinden, falls Ihr auch nach ihm sucht.', 28153),
(139372, 'deDE', 'Trefft mich beim Wagen, sobald Ihr hier fertig seid. Ich werde mit den Reparaturen beginnen.', '', 28153),
(139371, 'deDE', 'Glückwunsch, $p. Ihr habt eine weitere Begegnung mit den Ranishu überlebt. Nur wenige haben so viel Glück.', '', 28153),
(139370, 'deDE', 'Stark und robust... Dieses Holz ist die perfekte Wahl für Reparaturen an unserer Karawane.', '', 28153),
(139369, 'deDE', 'Die Reparaturen am Wagen kommen dank des hochwertigen Holzes, das Ihr uns beschafft habt, gut voran.', '', 28153),
(139368, 'deDE', '', 'Na gut... Hier ist sie! Schriftrolle der Unsichtbarkeit... Das muss sie sein.', 28153),
(139367, 'deDE', '', 'Hallo! Jetz\' is\' keine Zeit für Geschicht\'n.', 28153),
(139366, 'deDE', 'Habe ich die Geschichte nie erzählt? Was für ein Abenteuer! Wo soll ich nur anfangen...', '', 28153),
(139365, 'deDE', '', 'Meine Güte... das hier sieht aus, als wäre es in der Sprache der Alten Götter verfasst. Wo habt Ihr nur so etwas her?', 28153),
(139364, 'deDE', 'Nein! Habt Ihr überhaupt mal einen Blick rein geworfen? Aber, äh, legt sie beiseite. Wir brauchen sie, wenn wir hier fertig sind.', '', 28153),
(139363, 'deDE', '', 'Schauen wir mal... Schriftrolle der ewigen Rückkehr, ist es das?', 28153),
(139362, 'deDE', 'Könnt Ihr mich zurück zu Albers begleiten? Sicher ist er krank vor Sorge.', '', 28153),
(139361, 'deDE', 'Sobald Ihr die anderen gerettet habt, trefft mich auf der östlichen Erhebung, um der Gezeitenherrin entgegenzutreten!', '', 28153),
(139360, 'deDE', '', 'Pah, das könnte den ganzen Tag dauern! Prinzessin, Ihr könnt Euch nicht vorstellen, wie viele Rollen dieser alte Kauz hat.', 28153),
(139358, 'deDE', 'Wir müss\'n zu den andern!', 'Wir müss\'n zu den andern!', 28153),
(139357, 'deDE', 'Beschützt die Flotte!', 'Beschützt die Flotte!', 28153),
(139356, 'deDE', 'Der Kriegshaf\'n darf nich\' fall\'n!', 'Der Kriegshaf\'n darf nich\' fall\'n!', 28153),
(139355, 'deDE', 'Für König Rastakhan!', 'Für König Rastakhan!', 28153),
(139354, 'deDE', 'Ha! Wusste ich doch, dass ich sie irgendwo hatte. Damit sind wir gut genug vor den Bluttrollen verborgen. Bleibt in meiner Nähe.', '', 28153),
(139353, 'deDE', 'In früheren Zeiten hätte ich es mit einem ganzen Schwarm dieser kriechenden Würmer aufgenommen. Sie sind in der Dunkelheit auf mich losgegangen. Ich wurde überrannt! Ihre Befehle schienen zusammengefasst zu lauten: \"Beeilt euch! Azshara will ihre Beute!\"', '', 28153),
(139351, 'deDE', 'Was immer Ihr uns sagen könnt, mein Lord. Wir brauchen so viele Informationen wie nur möglich.', '', 28153),
(139350, 'deDE', 'Die Naga suchen hier nach etwas. Es wird für Azshara sein. Wir müssen sie aufhalten oder von ihrem Ziel abbringen.', '', 28153),
(139348, 'deDE', 'Äh, eehm... wegen meiner... ääh, eeh... Unzulänglichkeit hat ein... ein Kult die Stadt im Griff.', '', 28153),
(139347, 'deDE', 'Hört Ihr das? Das is\' Bwonsamdi! Die Ewigkeit kommt näher!', 'Hört Ihr das? Das is\' Bwonsamdi! Die Ewigkeit kommt näher!', 28153),
(139346, 'deDE', 'Mein Lord! Seid Ihr in Sicherheit? Was wisst Ihr?', '', 28153),
(139345, 'deDE', 'Brannon!', '', 28153),
(139344, 'deDE', 'Diese Stimme... Er ruft uns... Wir müss\'n gehorch\'n!', 'Diese Stimme... Er ruft uns... Wir müss\'n gehorch\'n!', 28153),
(139343, 'deDE', 'Was is\' gescheh\'n? Ich lag krank im Bett... un\' wo bin ich jetzt?', 'Was is\' gescheh\'n? Ich lag krank im Bett... un\' wo bin ich jetzt?', 28153),
(139341, 'deDE', 'Mein Leben... für den Kaiser...', '', 28153),
(139339, 'deDE', 'Ich habe meine Untergebenen enttäuscht. Wegen meiner mangelnden Führung wandten sie sich Anderen zu.', '', 28153),
(139338, 'deDE', 'Mein Onkel dachte, in diesem Dorf könnte ich erste Erfahrung als Anführer sammeln. Aber ein Kult? Wie kommt man einem Kult bei?!', '', 28153),
(139336, 'deDE', 'Tausend Schlachten... tausend Siege...', '', 28153),
(139335, 'deDE', 'Der Donner... wird niemals... schweigen...', '', 28153),
(139334, 'deDE', 'Habt Dank für meine Rettung, Fremdling. Klausen und seine Männer stürzten das Dorf so schnell... Ich hab es nicht kommen sehen.', '', 28153),
(139333, 'deDE', 'Der Sturm... legt sich...', '', 28153),
(139329, 'deDE', 'Unser ist der Wille... der Götter...', '', 28153),
(139328, 'deDE', 'Selbst Stein... bricht...', '', 28153),
(139327, 'deDE', 'Fleisch ist... schwach...', '', 28153),
(139326, 'deDE', 'Das Reich... wird niemals... untergehen...', '', 28153),
(139317, 'deDE', 'Ihr werdet mir als Sklave dienen!', '', 28153),
(139316, 'deDE', 'Spürt den Zorn des Sturms!', '', 28153),
(139315, 'deDE', 'Verbeugt Euch vor mir!', '', 28153),
(139314, 'deDE', 'Ich bin die Verkörperung der Macht!', '', 28153),
(139312, 'deDE', 'Die Zandalari werden ihren Pakt ehren... oder sterben!', '', 28153),
(139311, 'deDE', 'Ich werde Euren Schädel in meinen Händen zermalmen!', '', 28153),
(139309, 'deDE', 'Unser Reich wird mit Euren Knochen wiederaufgebaut!', '', 28153),
(139308, 'deDE', 'Ihr werdet dienen!', '', 28153),
(139307, 'deDE', 'Brannon, Ihr seid nichts als ein törichter Junge. Ich habe eine Abmachung getroffen und werde dieses Dorf ohne Euch zum Erfolg führen!', 'Brannon, Ihr seid nichts als ein törichter Junge. Ich habe eine Abmachung getroffen und werde dieses Dorf ohne Euch zum Erfolg führen!', 28153),
(139306, 'deDE', 'Wir benötigen Ressourcen, um sie aufzuhalten. Zieht los und bringt mir Eisen und Holz!', '', 28153),
(139305, 'deDE', '', 'Wasss wissst Ihr über die Geheimnisssse der Insel? Sssagt es mir!', 28153),
(139304, 'deDE', 'Dasss Meer issst unser Reich!', '', 28153),
(139303, 'deDE', 'Wir ertränken Euch unter den Wellen!', '', 28153),
(139298, 'deDE', '', 'Schön, ich mache mich auf zum Wagen. Bis bald, $p!', 28153),
(139295, 'deDE', 'Ja. Danke für Eure Hilfe heute, Kona und $p. Ich stehe in Eurer Schuld.', '', 28153),
(139294, 'deDE', '', 'Wir hätten bis zum Schluss mit Euch gekämpft, Sumber.', 28153),
(139293, 'deDE', 'Ich bin auch froh zu hören, dass Thun\'ka der Verdorrer seiner Bindung entflohen ist. Ein so mächtiger Elementar wäre... problematisch für uns.', '', 28153),
(139292, 'deDE', 'Es war also ein Schamane, der dieses Chaos verursacht hat? Danke, dass Ihr ihn getötet habt.', '', 28153),
(139291, 'deDE', 'Hahaha! Nehmt das, widerlicher Hordenabschaum!', '', 28153),
(139290, 'deDE', 'Mein Ritual is\' fast vollständig! Ich werd Euch bind\'n, Thun\'ka der Verdorrer!', '', 28153),
(139288, 'deDE', '', 'Macht, was Ihr wollt, mir doch egal! Hmpf... der führt sich auf, als hätte er das hier gebaut.', 28153),
(139287, 'deDE', 'Ach, was wisst Ihr denn schon? Dann bleibt doch hier. Wir gehen jetzt los. Ich kenne das hier wie meine Westentasche.', '', 28153),
(139286, 'deDE', 'Die machen kurzen Prozess mit Euch! Die sind von einer anderen Sorte als die Bluttrolle, denen wir auf unserer letzten Pilgerschaft begegnet sind.', '', 28153),
(139285, 'deDE', 'Pah, Ihr habt hier gar nichts zu befehlen. Wir müssen diesen Monstern eine Lektion erteilen.', '', 28153),
(139284, 'deDE', '', 'Bleibt hier und denkt Euch einen Plan mit uns aus. Die Bluttrolle schafft Ihr nicht allein.', 28153),
(139283, 'deDE', 'Kisha, Lashk. Wir kümmern uns jetzt um die Störenfriede, die Torga zerhacken.', '', 28153),
(139282, 'deDE', '', 'Wurde auch Zeit! Ich dachte, wir sind die Einzigen, denen Torgas Tod nicht egal ist.', 28153),
(139281, 'deDE', 'Schau an. Die anderen trauen sich endlich auch aus ihren Panzern.', '', 28153),
(139250, 'deDE', '|cffffff00+$1i Eisen|r', '|cffffff00+$1i Eisen|r', 28153),
(139241, 'deDE', 'Kämpft weiter!', '', 28153),
(139240, 'deDE', '', 'Sind wir nicht ein tolles Team?', 28153),
(139204, 'deDE', '', 'Ich habe noch einen getötet, Sumber! Damit wären es schon siebenundzwanzig!', 28153),
(139198, 'deDE', '|cffffff00+$1i Holz|r', '|cffffff00+$1i Holz|r', 28153),
(139168, 'deDE', 'Ja... kämpft dagegen an... wehrt Euch... G\'huun hungert... nach Eurem... Leiden.', '', 28153),
(139167, 'deDE', 'Ihr versucht... G\'huun aufzuhalten. Ihr werdet... scheitern... und leiden.', '', 28153),
(139165, 'deDE', 'Kommt.', '', 28153),
(139164, 'deDE', 'Haltet ein.', '', 28153),
(139163, 'deDE', 'Werkstatt ist einsatzbereit!', '', 28153),
(139162, 'deDE', 'Die Werkstatt ist bereit. Baut Verwüster und zeigt der Allianz, wie leicht ihre Mauern einstürzen!', '', 28153),
(139097, 'deDE', '$n tränkt die Krallen in Gift!', '$n tränkt die Krallen in Gift!', 28153),
(139080, 'deDE', 'Ihr versteht nicht... was in der Tiefe lauert...', '', 28153),
(139079, 'deDE', 'Unsere Macht wird Euch brechen!', '', 28153),
(139078, 'deDE', 'Kniet nieder vor Euren neuen Meistern!', '', 28153),
(139077, 'deDE', 'Unsere Herrschaft... ist der einzige... Weg...', '', 28153),
(139073, 'deDE', 'Die Stürme selbst gehorchen meinem Ruf!', '', 28153),
(139072, 'deDE', 'Das werdet Ihr bereuen!', '', 28153),
(139071, 'deDE', 'Ich habe mehr Macht, als Ihr je haben werdet!', '', 28153),
(139070, 'deDE', 'Ich hab Euch gewarnt!', '', 28153),
(139065, 'deDE', 'Unsere Worte strotzen vor Macht! Dieses Land wird uns gehören!', '', 28153),
(138870, 'deDE', '', 'Die Leute von Schnitztal schulden Euch etwas, $C. \n\nKümmert Ihr Euch jetzt um Fräulein Kronsteig. Wir beseitigen hier die Überreste des Zirkels.', 28153),
(138865, 'deDE', '', 'Ihr seid zurück! Bitte sagt mir, dass Ihr diese Matrone erledigt habt.', 28153),
(138864, 'deDE', '', 'Seitdem diese Energie dort herausströmt, können wir nicht mehr in die Mine hinein.\n\nDieses Weidenkonstrukt, das Ihr kontrolliert, könnte unsere einzige Hoffnung sein.', 28153),
(138859, 'deDE', '', 'Wir wissen Eure Hilfe zu würdigen, $C. Die Lage war ziemlich düster, bevor Ihr eingetroffen seid.', 28153),
(138853, 'deDE', 'Ich werde mich weiter im Stadtinneren umsehen. Hoffentlich sind die Leute dort sicher!', '', 28153),
(138852, 'deDE', 'Erfolg! Ihr habt die Kontrolle über den fluchgeformten Knecht übernommen!', '', 28153),
(138849, 'deDE', 'Hinfort!', '', 28153),
(138848, 'deDE', '', 'Seid Ihr jetzt zufrieden? Laufe ich genug für Euren Geschmack?', 28153),
(138847, 'deDE', '', 'Ich stehe nur herum? Na gut... Und jetzt? Ist Euch das Pilgern genug?', 28153),
(138841, 'deDE', 'Kommt näher, $gkleiner:kleine:r; $PR. Ich will mit Euch sprechen.', '', 28153),
(138837, 'deDE', '', 'Ich frage selbst ein bisschen herum. Wir treffen uns in der Stadt!', 28153),
(138836, 'deDE', '', 'Ihr seid große Klasse, $p. Ich hoffe, unsere Pfade kreuzen sich bald wieder.', 28153),
(138833, 'deDE', 'Wir müssen stark bleiben.', '', 28153),
(138832, 'deDE', 'Geht voran, $n! Beschützt die Leute von Drustvar!', '', 28153),
(138831, 'deDE', 'Bleibt ruhig, Kinder des Meeres. Wir müssen fest an das Wasser glauben, um eine Heilung zu finden.', '', 28153),
(138830, 'deDE', '', 'Wenn Ihr noch weiteren verderbten Hexen begegnet, dann versetzt ihnen in meinem Namen einen gerechten Schlag ins Gesicht, Champion!', 28153),
(138829, 'deDE', '', 'Wir sind sehr froh, dass es immer noch Champions wie Euch gibt, $n.', 28153),
(138824, 'deDE', '', 'Taji und Kona hätten mittlerweile zurück sein sollen. Sie müssen in Schwierigkeiten geraten sein.', 28153),
(138823, 'deDE', 'Unsere höchste Priorität sollte es sein, unsere Vorräte zurückzuholen. Wir müssen essen.', '', 28153),
(138822, 'deDE', 'Oh Meer, lindere das Leiden der Kranken und Unterdrückten der Angelpunktwerft. Mögen wir die Quelle des Übels entdecken, das uns quält!', '', 28153),
(138821, 'deDE', 'Ihr könnt von Glück sagen, dass $n in der Nähe war und euch gerettet hat.', '', 28153),
(138820, 'deDE', 'Noch ein Wort und es werden drei Monate!', '', 28153),
(138819, 'deDE', 'Aber wir sind doch Entdecker!', '', 28153),
(138818, 'deDE', '', 'Och nö!', 28153),
(138817, 'deDE', 'Ach, komm schon, Opi!', '', 28153),
(138816, 'deDE', 'Ihr kriegt alle zwei Monate Hausarrest!', '', 28153),
(138815, 'deDE', '', 'Jawohl.', 28153),
(138814, 'deDE', 'Ja, Opi.', '', 28153),
(138813, 'deDE', 'Ja, Opi.', '', 28153),
(138812, 'deDE', 'Ihr Kinder solltet doch nicht weglaufen!', '', 28153),
(138811, 'deDE', 'Dieses Matrosenlied will ich nie wieder hören!', 'Dieses Matrosenlied will ich nie wieder hören!', 28153),
(138810, 'deDE', 'Endlich! Frei!', 'Endlich! Frei!', 28153),
(138809, 'deDE', 'Argh. Dieses Lied werde ich den ganzen Tag nicht aus dem Kopf bekommen.', 'Argh. Dieses Lied werde ich den ganzen Tag nicht aus dem Kopf bekommen.', 28153),
(138808, 'deDE', 'Ich danke Euch!', 'Ich danke Euch!', 28153),
(138807, 'deDE', 'Tod... endlich... Jetzt müsst Ihr... G\'huun aufhalten...', '', 28153),
(138804, 'deDE', 'Ihr glaubt, Ihr seid stark genug, um G\'huun aufzuhalten? Das werden wir in meiner Arena herausfinden!', '', 28153),
(138803, 'deDE', 'Nazesh war ziemlich unverschämt. Eure Lektion in Manieren muss ziemlich streng ausfallen... und dauerhaft, fürchte ich. Benutzt jetzt die Schriftrolle, das wird helfen!', '', 28153),
(138802, 'deDE', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tDas Blut von $n ist jetzt |cFFFF0000|Hspell:255582|h[Unrein]|h|r!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tDas Blut von $n ist jetzt |cFFFF0000|Hspell:255582|h[Unrein]|h|r!', 28153),
(138801, 'deDE', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t$n wirkt |cFFFF0000|Hspell:255577|h[Transfusion]|h|r!', 28153),
(138800, 'deDE', '', '$n überzieht ihre Hände mit Gold.', 28153),
(138799, 'deDE', 'Hier waren nur ein paar Murlocs, dann gab es einen Sturm, dann strömten die Naga auf den Strand. Sie haben mich als Ersten erwischt und das ist mir ziemlich peinlich.', '', 28153),
(138798, 'deDE', 'Befreit meinen Geist, bitte!', '', 28153),
(138797, 'deDE', 'Ich will das nich\'! Macht den Schmerz weg!', '', 28153),
(138796, 'deDE', 'Lasst mich zu Bwonsamdi geh\'n, bitte!', '', 28153),
(138795, 'deDE', 'Tut so weh! Macht, dass es vorbei is\'!', '', 28153),
(138794, 'deDE', 'Bitte lasst meine Schmerzen aufhör\'n!', '', 28153),
(138793, 'deDE', 'Ich hab mich nich\' unter Kontrolle!', '', 28153),
(138792, 'deDE', 'Bitte, macht, dass mein Leiden vorbei is\'!', '', 28153),
(138791, 'deDE', '', 'Befreit meinen Geist, bitte!', 28153),
(138790, 'deDE', '', 'Ich will das nich\'! Macht den Schmerz weg!', 28153),
(138789, 'deDE', '', 'Lasst mich zu Bwonsamdi geh\'n, bitte!', 28153),
(138788, 'deDE', '', 'Tut so weh! Macht, dass es vorbei is\'!', 28153),
(138787, 'deDE', '', 'Bitte lasst meine Schmerzen aufhör\'n!', 28153),
(138786, 'deDE', '', 'Ich hab mich nich\' unter Kontrolle!', 28153),
(138785, 'deDE', '', 'Bitte, macht, dass mein Leiden vorbei is\'!', 28153),
(138784, 'deDE', '', 'Ich hör den Ruf der Elemente und geh, wohin der Wind mich ruft.', 28153),
(138783, 'deDE', 'Wie sind diese Dinger überhaupt in meinen Magen gekommen?!', 'Wie sind diese Dinger überhaupt in meinen Magen gekommen?!', 28153),
(138782, 'deDE', 'Mir... Mir geht\'s nicht so gut...', 'Mir... Mir geht\'s nicht so gut...', 28153),
(138781, 'deDE', 'So gut hat mein Magen sich schon seit Tagen nicht mehr angefühlt!', 'So gut hat mein Magen sich schon seit Tagen nicht mehr angefühlt!', 28153),
(138779, 'deDE', 'W-Waren die in mir drin?', 'W-Waren die in mir drin?', 28153),
(138776, 'deDE', '', 'Wenn Ihr nicht zum Helfen hier seid, dann steht nicht im Weg.', 28153),
(138775, 'deDE', '', 'Willkommen in Schnitztal, $C. Das Chaos tut mir leid, wir haben hier grade ein kleines Hexenproblem.', 28153),
(138774, 'deDE', 'Ich dachte, die Geister würden mich töten! Ich danke Euch!', 'Ich dachte, die Geister würden mich töten! Ich danke Euch!', 28153),
(138773, 'deDE', 'Ich danke Euch. Sobald ich meinen Begleiter gefunden habe, verlasse ich diese verfluchte Gegend!', 'Ich danke Euch. Sobald ich meinen Begleiter gefunden habe, verlasse ich diese verfluchte Gegend!', 28153),
(138772, 'deDE', 'Habt Dank!', 'Habt Dank!', 28153),
(138771, 'deDE', 'Solche Geister habe ich noch nie gesehen. Ich verschwinde hier!', 'Solche Geister habe ich noch nie gesehen. Ich verschwinde hier!', 28153),
(138770, 'deDE', 'Danke, dass Ihr mich gerettet habt.', 'Danke, dass Ihr mich gerettet habt.', 28153),
(138769, 'deDE', 'Ich danke Euch. Ich dachte schon, es wäre um mich geschehen.', 'Ich danke Euch. Ich dachte schon, es wäre um mich geschehen.', 28153),
(138768, 'deDE', 'Hey, ich stör\' ja nur ungern, Mann, aber ich hab \'ne dringende Bitte an $n.', '', 28153),
(138767, 'deDE', 'Wer seid\'n Ihr, Fremdling? Kein Bluttroll... sonst hätt\'n die Geister kurzen Prozess mit Euch gemacht.', '', 28153),
(138766, 'deDE', 'Wartet... da kommt was auf uns zu.', '', 28153),
(138765, 'deDE', 'Die Ruine hier is\' Bwonsamdi geweiht. Die Bluttrolle werd\'n uns nich\' hierher folg\'n.', '', 28153),
(138762, 'deDE', 'Ich habe nicht viele, aber sie gehören ganz Euch, Hochkönig.', '', 28153),
(138760, 'deDE', '', 'Die Horde zieht sich wieder zurück? Welche Strategie verfolgt sie damit?', 28153),
(138759, 'deDE', 'Sylvanas darf nicht entkommen. Wir gewinnen den Krieg nur, wenn wir sie gefangen nehmen.', '', 28153),
(138758, 'deDE', 'Ihr seid nichts...', '', 28153),
(138757, 'deDE', 'Diese Bucht gehört Gezeitenherrin Nazesh! Wir werden aufdecken, was bisher in Zuldazar verborgen war!', '', 28153),
(138756, 'deDE', 'Heh. Frischfleisch.', 'Heh. Frischfleisch.', 28153),
(138755, 'deDE', 'Keine Angst, wir haben andere Pläne. Ich kenn\' ein Schlupfloch, wo wir ungestört Informationen sammeln können.', '', 28153),
(138754, 'deDE', 'Was der meint, ist \"Frischlinge weichklopfen\".', '', 28153),
(138753, 'deDE', 'Na gut, kommt rein. Meldet Euch für die... \"Einweisung\". Hehe.', '', 28153),
(138752, 'deDE', 'Hmm... Na, Ihr HABT immerhin eigene Hüte...', '', 28153),
(138751, 'deDE', 'Wir wollen den Eisenfluträubern beitreten. Wir haben unsere eigenen Hüte mitgebracht.', 'Wir wollen den Eisenfluträubern beitreten. Wir haben unsere eigenen Hüte mitgebracht.', 28153),
(138749, 'deDE', 'Das is \'n heiliger Ort. Un\' es is\' meine Mission, ihn bis in alle Ewigkeit zu beschütz\'n.', '', 28153),
(138748, 'deDE', 'Viele Pilger auf dem Weg zur Nekropole hab\'n hier Halt gemacht.\n\nDieser Tage is\' alles ruhig... Das is\' nich\' gut. Gar nich\' gut.', '', 28153),
(138747, 'deDE', 'Ich bewach dieses Refugium, seit es gebaut wurde. Un\' ich werd das so lange mach\'n, bis es zu Staub zerfällt.', '', 28153),
(138746, 'deDE', 'Wir heiß\'n alle hier willkomm\'n, die unterwegs zur Nekropole sin\'!', '', 28153),
(138745, 'deDE', 'In Bwonsamdis Namen biet ich Reisenden Rast, die zu seinem Tempel reis\'n.', '', 28153),
(138744, 'deDE', 'Schneidig! Jetzt melden wir uns als Freiwillige beim Rekrutierer.', '', 28153),
(138743, 'deDE', 'Setzt den Hut auf. Ohne Hut geht hier keiner als rauer Seebär durch!', '', 28153),
(138742, 'deDE', 'Nur noch ein paar Minuten, Rosalinde. Mithilfe der verstärkten Harpunen werdet Ihr über Eure Beute triumphieren!', '', 28153),
(138741, 'deDE', '', 'Okri, was machen unsere Vorräte? Ich will so schnell wie möglich in See stechen. Uns läuft die Zeit davon!', 28153),
(138740, 'deDE', 'Aye? Was wollt Ihr?', 'Aye? Was wollt Ihr?', 28153),
(138739, 'deDE', 'Nun werde ich wohl erst einmal mit leeren Händen nach Boralus zurückkehren. Findet mich dort, wenn Ihr die Schriftrolle habt, dann reden wir über Eure Bezahlung.', '', 28153),
(138738, 'deDE', 'Passt auf, das ist wichtig: Die Schriftrolle, die Ihr eintauschen möchtet, wurde mit grünem Wachs versiegelt. Es MUSS grün sein!', '', 28153),
(138737, 'deDE', 'Der Mann, nach dem Ihr sucht, heißt Karl-Jan. Sein Laden ist im Obergeschoss des Hauses am südlichen Ende der Stadt.', '', 28153),
(138734, 'deDE', 'Wozu beißte mich denn? Ich hab kein Fleisch auf\'n Knoch\'n.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138733, 'deDE', 'Friss die Bestie, du verrückte Schlange!', '', 28153),
(138732, 'deDE', 'Euer Kampfgeist gefällt mir. Spart\'n Euch für die Sethrak auf!', '', 28153),
(138731, 'deDE', 'Ha! Fast hätt\'s mich erwischt!', '', 28153),
(138730, 'deDE', 'Rezan schickt sich an, $n zu |TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[Verschlingen]|h|r!', '', 28153),
(138729, 'deDE', 'Käpt\'n Gulnaku wird für seine Tat\'n zahl\'n.', '', 28153),
(138728, 'deDE', 'Danke, dass Ihr mich freigelass\'n habt... Dafür lass\' ich Euch am Leb\'n.', '', 28153),
(138725, 'deDE', 'Passt auf, wo Ihr da rumwühlt! Ich penn da unt\'n!', 'Passt auf, wo Ihr da rumwühlt! Ich penn da unt\'n!', 28153),
(138724, 'deDE', 'Die Geister in dieser Gegend werden bestimmt nicht tatenlos zusehen, wie Ihr ihr Land zerstört...', '', 28153),
(138723, 'deDE', 'Ich halte es für keine gute Idee, Bomben auf diese Knochen zu werfen!', '', 28153),
(138722, 'deDE', 'Ich habe viele Trolle nach Xibala befragt und unabhängig von meinen Verhörmethoden viele verschiedene Geschichten über ihn gehört.\n\nEinige sagen, dass er dafür verantwortlich war, dass die Körper von Leuten vor eitrigen Entzündungen aufgedunsen waren.\n\nOder dass alle, die ihn angesehen haben, zu lebenden Skeletten geworden sind.\n\nOder dass er in den Schatten gelauert hat und Leute verschlang, während sie geschlafen haben.\n\nOder dass er in der Nähe von Straßen gewartet hat und Leute Blut husten ließ.\n\nKein Wunder, dass die Einheimischen sich fernhalten!', '', 28153),
(138721, 'deDE', 'Es ist schon eine Ewigkeit her, seit ich diesen Ort das letzte Mal gesehen habe. Und schon damals fürchteten und mieden ihn sogar die Einheimischen...\n\nDort treiben sich böse Geister rum, $n. Ihr solltet sie nicht stören.', '', 28153),
(138717, 'deDE', 'Ihr solltet Euch nich\' in Zem\'lans Gassen herumtreiben, Ratte. Schnappt sie Euch, Giff!', 'Ihr solltet Euch nich\' in Zem\'lans Gassen herumtreiben, Ratte. Schnappt sie Euch, Giff!', 28153),
(138716, 'deDE', 'Die Horde... wird mich räch\'n...', '', 28153),
(138715, 'deDE', 'Diese Stätte gehört der Archäologischen Akademie. Die Allianz ist hier nicht willkommen!', '', 28153),
(138709, 'deDE', '', 'Es könnte Kollateralschaden entstehen, aber die Teile können wir bestimmt am Ende wieder zusammenfügen. Vielleicht würden wir dazu einige weitere Forschungsassistenten benötigen...', 28153),
(138707, 'deDE', 'He, Zalnon\'mak, Euer Hut is\' wirklich bequem. Ich glaub\', den behalt\' ich!', '', 28153),
(138706, 'deDE', 'Wer will mit mir trink\'n?', '', 28153),
(138705, 'deDE', 'Warum arbeitet Ihr alle so hart? Ihr wisst aber, dass wir ewig leb\'n, oder?', '', 28153),
(138704, 'deDE', 'He Senjilak! Xunanji klaut Euer Zeug, sobald Ihr ihnen den Rück\'n zukehrt!', '', 28153),
(138703, 'deDE', 'He, Segazea, Euer Diener verbreitet seinen Gestank im ganzen Laden. Schafft ihn raus hier!', '', 28153),
(138702, 'deDE', 'Xulai, Ihr seid der lahmste Träger, der mir je unter die Augen gekommen is\'!', '', 28153),
(138701, 'deDE', 'Langsam durstig? Schade!', '', 28153),
(138700, 'deDE', 'Macht hinne, Ihr Faulenzer. Ich brauch\' mehr Grog!', '', 28153),
(138699, 'deDE', '$n hat die Mine der Trockenstoppel eingenommen!', '$n hat die Mine der Trockenstoppel eingenommen!', 28153),
(138698, 'deDE', '', 'Haut bloß nicht noch mal einfach so ab. Verstanden? Und jetzt los. Es gibt viel zu tun.', 28153),
(138691, 'deDE', 'Ich... Bitte beruhigt Euch, beruhigt Euch allesamt! Wir tun, was wir können. Wir finden ein Heilmittel und ebenso die Ursache!', '', 28153),
(138690, 'deDE', '', 'Ihr müsst uns helfen, Therold! Wir brauchen Antworten! Wir brauchen ein Heilmittel!', 28153),
(138689, 'deDE', 'Was verursacht diese Krankheit?!', '', 28153),
(138688, 'deDE', '', 'Unsere Kinder werden krank!', 28153),
(138687, 'deDE', 'Kommt zur Revanche wieder vorbei...', 'Kommt zur Revanche wieder vorbei...', 28153),
(138686, 'deDE', 'Hierfür hab ich schon\'n ganz\'n Tag getrunk\'n...', 'Hierfür hab ich schon\'n ganz\'n Tag getrunk\'n...', 28153),
(138679, 'deDE', 'Das wird Gulnaku gar nich\' gefall\'n.', 'Das wird Gulnaku gar nich\' gefall\'n.', 28153),
(138678, 'deDE', 'Pfoten weg von meiner Schatzkarte!', 'Pfoten weg von meiner Schatzkarte!', 28153),
(138676, 'deDE', 'Bringt mir \'nen Vulperakopf und erhaltet Rabatt auf Euren ersten Einkauf!', '', 28153),
(138675, 'deDE', 'Ein Grog in Ehr\'n wird auch Flog abwehr\'n!', '', 28153),
(138674, 'deDE', 'Augenklappen kann man nie genug hab\'n!', '', 28153),
(138673, 'deDE', 'Mit den neuen Kopfbedeckungen von Flicker könnt auch Ihr wie Zem\'lan selbst ausseh\'n!', '', 28153),
(138672, 'deDE', 'Yoksa kennt sich mit Mojo aus wie kein Zweiter! Holt Euch noch heute seine neuesten Tränke!', '', 28153),
(138671, 'deDE', 'Jetzt auf Lager: neue Entermesser! Extra scharf!', '', 28153),
(138670, 'deDE', 'Kämpft heute an der Seite eines furchterregenden Tigers!', '', 28153),
(138669, 'deDE', 'Holt Euch Eure Vulperasteaks, frisch vom Grill!', '', 28153),
(138668, 'deDE', 'Nur heute: Alles von Oggo zum halb\'n Preis...', 'Nur heute: Alles von Oggo zum halb\'n Preis...', 28153),
(138666, 'deDE', '', 'Ich finde schon allein hinaus. Seid vorsichtig.', 28153),
(138664, 'deDE', 'Räumt das Chaos hier auf... bevor Ihr geht.', 'Räumt das Chaos hier auf... bevor Ihr geht.', 28153),
(138663, 'deDE', 'Hier soll Euer neues Zuhause sein... un\' zwar für immer!', 'Hier soll Euer neues Zuhause sein... un\' zwar für immer!', 28153),
(138662, 'deDE', 'Hallöchen, $C. Wir brauchen Eure Hilfe bei einem kleinen Problemchen.', '', 28153),
(138661, 'deDE', 'Wir sin\' für immer an Zem\'lans Willen gebund\'n.', 'Wir sin\' für immer an Zem\'lans Willen gebund\'n.', 28153),
(138660, 'deDE', 'Ich hab immer alles für meine Besatzung gegeb\'n. Für Euch is\' hier Schluss!', 'Ich hab immer alles für meine Besatzung gegeb\'n. Für Euch is\' hier Schluss!', 28153),
(138659, 'deDE', 'Wir komm\'n zurück ausm Grab un\' sin\' bereit zu kämpf\'n.', 'Wir komm\'n zurück ausm Grab un\' sin\' bereit zu kämpf\'n.', 28153),
(138658, 'deDE', 'Hab ich Euch nich\' schon getötet? Oder hattet Ihr mich getötet?', 'Hab ich Euch nich\' schon getötet? Oder hattet Ihr mich getötet?', 28153),
(138655, 'deDE', 'Ich labe mich an Eurem Fleisch und reiche Eure Seele meinem Meister dar!', '', 28153),
(138652, 'deDE', 'Ich ziehe Euch das Fleisch von den Knochen!', '', 28153),
(138651, 'deDE', 'Für eine elende Landratte kämpft Ihr gut, aber jetzt kommt Euer Ende!', '', 28153),
(138650, 'deDE', 'Lauft, so schnell Ihr könnt, Ratte. Ich hab \'ne ganze Ewigkeit, Euch zu jag\'n.', 'Lauft, so schnell Ihr könnt, Ratte. Ich hab \'ne ganze Ewigkeit, Euch zu jag\'n.', 28153),
(138649, 'deDE', 'Keiner nimmt mir den Schatz weg! Ihr nich\', Zem\'lan nich\', niemand nich\'!', 'Keiner nimmt mir den Schatz weg! Ihr nich\', Zem\'lan nich\', niemand nich\'!', 28153),
(138644, 'deDE', 'Der Aufstieg unseres Imperiums ist Euer Untergang!', 'Der Aufstieg unseres Imperiums ist Euer Untergang!', 28153),
(138641, 'deDE', 'Euer Tod soll den anderen eine Lehre sein!', 'Euer Tod soll den anderen eine Lehre sein!', 28153),
(138634, 'deDE', 'Keine Sorge, $PR. Ich werd nich\' gegen Euch kämpf\'n.\n\nZem\'lan hat mir das angetan. Er hat das mit all\'n so gemacht, ob wir\'s wollt\'n oder nich\'.\n\nSchaut mich an...\n\n<Der sanftmütige Guntha gibt einen tiefen Seufzer von sich.>\n\nWollt Ihr was trink\'n?', '', 28153),
(138633, 'deDE', 'Wenn Ihr in Vol\'dun überleb\'n wollt, müsst Ihr dem Tod immer in die Augen seh\'n... ohne jemals zu blinz\'ln.', '', 28153),
(138631, 'deDE', 'Keine Beute, kein Zaster.', 'Euer Schatz... er gehört jetz\' mir.', 28153),
(138628, 'deDE', 'Der Fluch macht uns stark.', 'Ich hab alles für Zem\'lan geopfert.', 28153),
(138627, 'deDE', 'Zem\'lan duldet keine Leb\'nd\'n mehr.', 'Wenn Ihr nich\' zur Crew gehört, sterbt Ihr.', 28153),
(138625, 'deDE', 'Ich hab den Haf\'n hier unzählige Jahre verteidigt.', 'Das is\' unser Hafen!', 28153),
(138624, 'deDE', 'Passt auf Euch auf da drauß\'n! Diese Sethrak sollt man nich\' unterschätz\'n...', '', 28153),
(138623, 'deDE', '', 'Und fertig! Danke für die Unterstützung.', 28153),
(138622, 'deDE', '', 'Fast fertig...', 28153),
(138621, 'deDE', '', 'So, nach all dem Krimskrams habe ich nun endlich die echten Relikte erreicht. Sollte nicht mehr lange dauern.', 28153),
(138620, 'deDE', '', 'Und wenn man sich die Bissspuren ansieht, wird diese Knochensammlung wohl von Birch stammen.', 28153),
(138619, 'deDE', '', 'Ein \"original Krummelunte-Prototyp\". Schade um das Metall, aber für Müll haben wir keinen Platz.', 28153),
(138618, 'deDE', '', 'Einige unserer wertvollsten Funde wurden in dieser Kiste zurückgelassen. Passt auf mich auf, $C. Ich versuche, so viel wie möglich zu retten.', 28153),
(138615, 'deDE', 'Wir werden den Tempel nicht aufgeben.', '', 28153),
(138589, 'deDE', 'Solange dieser Tempel noch steht, seid Ihr eingeladen, in seinen Mauern Zuflucht zu suchen.', '', 28153),
(138568, 'deDE', '', 'Boah! Sobald ich wieder Luft kriege, trete ich Euch dafür ordentlich gegen das Schienbein!', 28153),
(138567, 'deDE', 'Moment! Ich bin kein Hund! Und ich wusste gar nicht, dass Ihr mit diesen Stummelbeinchen rennen könnt. Ich dachte, Ihr würdet einfach Abhänge hinunterrollen.', '', 28153),
(138566, 'deDE', '', 'Eine Öffnung! Wer zuerst draußen ist, Birch! Ich wette, Ihr kriegt mich nicht, obwohl Ihr ein halber Hund seid!', 28153),
(138556, 'deDE', 'Die Allianz hat die Kontrolle über den Hof von Burg Stromgarde übernommen!', 'Die Allianz hat die Kontrolle über den Hof von Burg Stromgarde übernommen!', 28153),
(138555, 'deDE', '$n hat den Hof der Burg Stromgarde eingenommen!', '$n hat den Hof der Burg Stromgarde eingenommen!', 28153),
(138553, 'deDE', '', 'Ein Überfall! Beschützt die Dorfbewohner!', 28153),
(138552, 'deDE', '', 'Kommt, $n. Auf zum Hochwegpass!', 28153),
(138551, 'deDE', 'Ich hoffe, Ihr habt recht, Herrin. Männer, wir reiten los!', '', 28153),
(138550, 'deDE', '', 'Marschall, $gder:die:c; $C begleitet mich und stellt sicher, dass mir nichts geschieht.', 28153),
(138549, 'deDE', 'Aber Herrin, es wäre doch sicherer, wenn...', '', 28153),
(138548, 'deDE', '', 'Marschall, Ihr reitet mit Euren Truppen zu Aroms Wehr. Ich stoße nach einem kurzen Abstecher zu Euch.', 28153),
(138547, 'deDE', 'Die Allianz hat die Kontrolle über den Heldenrufpass übernommen!', 'Die Allianz hat die Kontrolle über den Heldenrufpass übernommen!', 28153),
(138546, 'deDE', '$n hat den Heldenrufpass eingenommen!', '$n hat den Heldenrufpass eingenommen!', 28153),
(138545, 'deDE', 'Wer is\' der Nächste?', '', 28153),
(138544, 'deDE', 'Willkomm\' bei der zeitlos\'n Crew der Verdammt\'n, Erster Maat.', '', 28153),
(138543, 'deDE', 'Uaaagh!', '', 28153),
(138542, 'deDE', 'Jamboya, werdet wiedergebor\'n!', '', 28153),
(138540, 'deDE', 'Tretet vor! Mein Geschenk macht Euch für IMMER Teil meiner Crew.', '', 28153),
(138539, 'deDE', 'Das is\' unser Zuhause. Wir werden alles tun, um den Haf\'n zu halt\'n... auf ewig!', '', 28153),
(138538, 'deDE', 'NEIN!', 'NEIN!', 28153),
(138537, 'deDE', 'Die Sethrak glaub\'n, sie könn\' uns abschlacht\'n. Was sagt Ihr dazu?', '', 28153),
(138535, 'deDE', 'Ich bleib nich\' lang tot... Wir seh\'n uns, Jamboya...', '', 28153),
(138534, 'deDE', 'Mein eigener Erster Maat?! Euch werd ich kielhol\'n!', '', 28153),
(138533, 'deDE', 'Ahoi! Welche räudige Ratte will mich rausfordern?', '', 28153),
(138532, 'deDE', '', 'Die Mutter... wird Euch holen...', 28153),
(138531, 'deDE', '', 'Euer Widerstand ist töricht. Ganz Kul Tiras wird dem Zirkel gehören!', 28153),
(138530, 'deDE', 'Wir beschützen das Fräulein, Festländer. Beseitigt Ihr die Anführerin!', '', 28153),
(138529, 'deDE', '', 'Die Mutter wird Euch holen, Luzilla Kronsteig!', 28153),
(138528, 'deDE', 'Was in aller Welt ist das?', '', 28153),
(138527, 'deDE', 'Die Fallen halten sie nicht mehr auf! Es kommen immer mehr!', '', 28153),
(138526, 'deDE', 'Beruhigt Euch, Kal\'dran. Wir können Zardrax immer noch besiegen.', 'Beruhigt Euch, Kal\'dran. Wir können Zardrax immer noch besiegen.', 28153),
(138521, 'deDE', '', 'Danke, Wachtmeister. Sollen wir, $C?', 28153),
(138520, 'deDE', 'Fräulein Kronsteig, Ihr könnt gehen... Ich bitte um Verzeihung...', '', 28153),
(138519, 'deDE', 'Hört, Ihr Leute! Es ist zutage getreten, dass in Wahrheit eine andere Hexe für den Fluch in Schnitztal verantwortlich war.', '', 28153),
(138518, 'deDE', '', 'So ist es besser. Nun, dann...', 28153),
(138517, 'deDE', 'Ich hol mir einfach \'nen anderen Bluttroll. Es gibt endlos viele un\' Ihr seid verlor\'n!', '', 28153),
(138516, 'deDE', 'Nein! Nana\'kwug! Jetzt muss ich...', '', 28153),
(138515, 'deDE', 'Haha... Eure Mühe is\' vergebens. Ihr könnt meine Macht nich\' aufhalt\'n!', '', 28153),
(138514, 'deDE', 'Glaubt Ihr wirklich, das macht \'n Unterschied? Die Kraft des Blutgotts fließt in mir! Ihr könnt sie nicht aufhalt\'n!', '', 28153),
(138513, 'deDE', 'Meine Kraft... schwindet! Haha... Ihr müsst verzweifelt sein, zu glaub\'n, dass das funktioniert!', '', 28153),
(138509, 'deDE', 'Achtung! Feinde, aus dem Wald!', '', 28153),
(138502, 'deDE', 'So! Das is\' alles, was ich Euch geb\'n kann, ohne mir selbst zu sehr wehzutun. Jetz\' geht un\' verbrennt diese Skeletthaufen.', '', 28153),
(138501, 'deDE', 'Ihr bleibt wachsam, während ich Euch \'nen Teil meines Feuermojos überlasse...', '', 28153),
(138500, 'deDE', 'Ich bin bereit, Euer Feuermojo zu nehm\'n, um die Grabhügel zu zerstör\'n.', 'Ich bin bereit, Euer Feuermojo zu nehm\'n, um die Grabhügel zu zerstör\'n.', 28153),
(138499, 'deDE', '', 'Dann sieht es aus, als müssten wir den Kampf zum Zirkel tragen. Und ich weiß auch schon, wie.', 28153),
(138498, 'deDE', 'Sie... sie haben ihn, Herrin. Wir wollten seine Befreiung in Angriff nehmen, als wir von diesem... Prozess gehört haben.', '', 28153),
(138497, 'deDE', '', 'Und mein Vater? Was unternimmt er dagegen?', 28153),
(138496, 'deDE', 'Sie sind in das Gebiet jenseits der Berge eingefallen. Wir halten Aroms Wehr mit nur einer Handvoll Soldaten.', '', 28153),
(138495, 'deDE', 'Es ist schlimmer, als Ihr denkt, Herrin. Dieser Zirkel hat sich in Drustvar wie ein Lauffeuer ausgebreitet.', '', 28153),
(138494, 'deDE', '', 'Marschall! Was wisst Ihr über diesen Zirkel? Sagt mir, was mit unserem Land geschehen ist!', 28153),
(138449, 'deDE', '', 'Whoa! Seht Euch nur an, wie der alte Zem\'lan aussah!', 28153),
(138448, 'deDE', '', 'Dieser Zem\'lan war schon ein ziemlicher Mistkerl, was?', 28153),
(138439, 'deDE', 'Holt die Götz\'n un\' trommelt die Besatzung zusamm\'.', '', 28153),
(138438, 'deDE', 'Die Sethrak nehm\' uns nich\' unser Zuhause. Nich\' heute. Nich\' gar nich\'!', '', 28153),
(138437, 'deDE', 'Ich... ich... Es muss \'nen andren Weg geben, Käpt\'n. Die Crew...', '', 28153),
(138436, 'deDE', 'Ist das ein Trick? Ja, oder?', 'Ihr seid ein Lebensretter. Ich wäre hier noch umgekommen.', 28153),
(138435, 'deDE', 'Vorstellen können wir uns ein andermal. Ich bleibe keine Minute mehr in dieser Mine.', 'Vorstellen können wir uns ein andermal. Ich bleibe keine Minute mehr in dieser Mine.', 28153),
(138434, 'deDE', 'Stellt mich nich\' infrage! Holt alle zum Altar. Sofort!', '', 28153),
(138433, 'deDE', 'Welche Freude, Euch zu sehen!', 'Welche Freude, Euch zu sehen!', 28153),
(138432, 'deDE', 'Ich hab keine Ahnung, wer Ihr seid oder was Ihr wollt, aber trotzdem danke.', 'Ich hab keine Ahnung, wer Ihr seid oder was Ihr wollt, aber trotzdem danke.', 28153),
(138431, 'deDE', 'Ihr seid wirklich die Rettung. Ich wäre hier glatt gestorben!', 'Ihr seid wirklich die Rettung. Ich wäre hier glatt gestorben!', 28153),
(138430, 'deDE', 'Meine Arme mögen müde sein, aber meine Beine sind bereit, sofort hier abzuhauen!', 'Ich hab keine Ahnung, wer Ihr seid oder was Ihr wollt, aber trotzdem danke.', 28153),
(138429, 'deDE', 'Verflucht sei der Sand un\' diese Schlang\'n! Der Hafen von Zem\'lan gehört MIR!', '', 28153),
(138428, 'deDE', 'Ich schulde Euch was, Fremdling.', 'Ich schulde Euch was, Fremdling.', 28153),
(138427, 'deDE', 'Es sin\' zu viele, Käpt\'n! Wir müss\'n uns zurückzieh\'n sonst geh\'n wir alle drauf.', '', 28153),
(138426, 'deDE', 'Mäht diese Schlang\'n nieder! Keine Gnade!', '', 28153),
(138373, 'deDE', 'Hoffen wir, dass ich schneller bin als diese Gesetzlosen!', '', 28153),
(138316, 'deDE', 'Ich danke Euch, $C. Lasst uns ein wenig reden, wenn wir einen Ort erreicht haben, der etwas sicherer ist.', '', 28153),
(138288, 'deDE', 'Es wird nich\' zurückgewich\'n. Stellt Euch den Sethrak oder stellt Euch mir!', '', 28153),
(138282, 'deDE', 'Ruft die Matros\'n zusamm\'. Ich will jeden besoff\'nen Freibeuter am Haupttor seh\'n.', '', 28153),
(138281, 'deDE', 'Den nimmt mir niemand. Niemals!', '', 28153),
(138280, 'deDE', 'Dann sin\' die so dämlich wie der Rest. Das hier is\' der Hafen von Zem\'lan! MEIN Hafen!', '', 28153),
(138279, 'deDE', 'Käpt\'n Zem\'lan, die Armee von den Sethrak nähert sich. Es sin\' so viele.', '', 28153),
(138264, 'deDE', 'Fluggenieur Krazzel zu Diensten!', '', 28153),
(138247, 'deDE', 'Also verschwindet aus mei\'m Haf\'n un\' sterbt im Sand, wo ihr hingehört.', '', 28153),
(138242, 'deDE', 'Und da keiner von Euch mehr hat als seine dreckig\'n Lumpen, seid Ihr für mich eh schon gestorb\'n.', '', 28153),
(138240, 'deDE', 'Niemand setzt \'n Fuß auf meine Boote, der mich nich\' mit Gold bezahlt hat.', '', 28153),
(138238, 'deDE', 'Dann sterbt doch, nutzloses Gesindel.', '', 28153),
(138235, 'deDE', 'Wenn ihr uns nich\' auf die Boote lasst, sterb\'n wir alle!', 'Wenn ihr uns nich\' auf die Boote lasst, sterb\'n wir alle!', 28153),
(138234, 'deDE', 'Anne Seite, Flüchtlinge! Pirat\'n kommt zuerst an Bord!', '', 28153),
(138233, 'deDE', 'Bitte, Zem\'lan. Lasst uns auf die Boote! Die Sethrak bring\'n uns sonst um.', 'Bitte, Zem\'lan. Lasst uns auf die Boote! Die Sethrak bring\'n uns sonst um.', 28153),
(138232, 'deDE', 'Wir nehm\' dann noch so viele mit, wie wir Platz ham.', '', 28153),
(138224, 'deDE', '', 'Ihr kommt zu einer merkwürdigen Zeit, $gFestländer:Festländerin;.\n\nWas wollt Ihr hier?', 28153),
(138214, 'deDE', 'Schön, dann geht es also nur mir so.', '', 28153),
(138213, 'deDE', '', 'Kein bisschen.', 28153),
(138212, 'deDE', 'Nein.', '', 28153),
(138211, 'deDE', '', 'Nein.', 28153),
(138210, 'deDE', 'Kommt es noch jemandem etwas übertrieben vor, dass wir ganze Heerscharen Sethrak ausgelöscht haben, während sie nur ein paar von uns getötet haben?', '', 28153),
(138209, 'deDE', 'Das ist natürlich großartig. Aber trotzdem irgendwie... ein wenig zu viel des Guten.', '', 28153),
(138208, 'deDE', '', 'Hahaha! Das war ja unglaublich! Und Ihr lebt noch!', 28153),
(138203, 'deDE', 'Zeppelin kommt!', '', 28153),
(138202, 'deDE', 'Ihr habt es wieder mal geschafft! Gute Arbeit!', '', 28153),
(138200, 'deDE', 'Die Troggs sind mir hierher gefolgt. Das ist alles meine Schuld! Helft mir bitte, $n!', '', 28153),
(138123, 'deDE', 'Ich wusste nicht, wie frei sich ein Tortollaner fühlen kann!', '', 28153),
(138122, 'deDE', 'Ich spür den Wind zwischen meinen Schuppen!', '', 28153),
(138121, 'deDE', 'Ich bin frei wie ein Vogel!', '', 28153),
(138120, 'deDE', 'Du hältst dich super, Papa!!', '', 28153),
(138118, 'deDE', 'NICHT LOSLASSEN NICHT LOSLASSEN NICHT LOSLASSEN!', '', 28153),
(138075, 'deDE', 'Mein Freund, würdet Ihr mir bei der Beurteilung dieser Pferde behilflich sein? Es muss das perfekte Pferd sein!', '', 28153),
(138074, 'deDE', 'Imma wieder werd\'n sie von faulenzenden Arbeitern gestohl\'n. Wenn Ihr keinen Grog findet, durchsucht die Arbeiter.', '', 28153),
(138073, 'deDE', 'Ich lagere meine zusätzlich\'n Vorräte unter Wasser. Hält sie schön kühl.', '', 28153),
(138072, 'deDE', 'Ihr seid in Ordnung, Fleischling. Sagt Bescheid, wenn Ihr was zu trink\'n braucht.', '', 28153),
(138071, 'deDE', '', 'HA!', 28153),
(138070, 'deDE', '', 'Habt Ihr ein Glück, dass ich nicht höher treten kann! Gebt es zu! Ihr habt die Falle ausgelöst!', 28153),
(138069, 'deDE', 'Au! Das war mein Schienbein!', '', 28153),
(138068, 'deDE', 'Mein Chaos? MEIN CHAOS? Ihr habt es doch ausgelöst, Ihr unausstehliche...', '', 28153),
(138067, 'deDE', '', '...um Euer Chaos zu korrigieren!', 28153),
(138066, 'deDE', '', 'Dann ab mit uns. Finden wir einen Händler. Ich verhungere.', 28153),
(138065, 'deDE', '', 'Und hey... Ich habe genug Edelsteine und Schmuckstücke mitgehen lassen, dass unsere Kosten für einen Monat gedeckt sind.', 28153),
(138064, 'deDE', '', 'Ja ja. Ich hab Euch auch alle lieb.', 28153),
(138061, 'deDE', '', 'Hier gibt es nichts mehr für uns, Leute. Packen wir zusammen und machen wir uns auf den Weg.', 28153),
(138060, 'deDE', '', 'Ich bin nicht wirklich überrascht. Den Fluch zu bannen, war ein Schuss ins Blaue.', 28153),
(138059, 'deDE', 'Wollt Ihr sehen, wie Wurst gemacht wird?', '', 28153),
(138058, 'deDE', 'Wer will Euch an den Schinken? Ich! Hehehe!', '', 28153),
(138057, 'deDE', 'Ihr ergebt einen schönen Schinken!', '', 28153),
(138056, 'deDE', 'Ich werde... Euch zerhäckseln...', '', 28153),
(138055, 'deDE', 'Ihr seid... verloren...', '', 28153),
(138054, 'deDE', '', 'Mögen die Winde Euch tragen, $p... und werdet ja nicht einer von ihnen, verstanden?', 28153),
(138053, 'deDE', '', 'Ich schleiche mich zurück zur Karawane und sorge dafür, dass alle bereit sind, hier zu plündern, sobald Ihr den Fluch gebannt habt.', 28153),
(138052, 'deDE', '', 'Hier sind die Notizen, die ich gefunden habe. Es fehlen Euch nur noch ein paar Dinge, um das Ritual durchzuführen.', 28153),
(138051, 'deDE', 'Danke, dass Ihr uns gerettet habt, $C. Diese ganze Fluchbekämpfung muss Euch hungrig gemacht haben.\n\nMöchtet Ihr vielleicht eine Wurst?', '', 28153),
(138050, 'deDE', 'Bitte, genießt das Fest. Reitet! Esst! Trinkt! Ihr seid mein Ehrengast.', '', 28153),
(138049, 'deDE', 'Ihr! Ihr habt nicht nur meinen Sohn gerettet, sondern mein ganzes Fest! Davon wird man noch in Jahren sprechen!', '', 28153),
(138048, 'deDE', '', 'Sucht Ihr etwas zu essen... oder etwas anderes?', 28153),
(138047, 'deDE', 'Revitalisieren', 'Revitalisieren', 28153),
(138046, 'deDE', '', 'Ich werde hierbleiben, während Ihr die anderen Götzen sucht. Bringt sie hierher, sobald Ihr alle gefunden habt.', 28153),
(138045, 'deDE', '', 'Und auch einer der Götzen. Wärt Ihr so gut, ihn mir zu holen?', 28153),
(138044, 'deDE', '', 'Ich glaube, das war Zem\'lans Thronsaal. Überall liegen Schätze!', 28153),
(138042, 'deDE', 'Zurück auf Position! Haltet die Formation!', '', 28153),
(138040, 'deDE', '', 'Wahrscheinlich ist Meeki schon tot. Bloß raus aus Zem\'lan, solange Ihr noch könnt.', 28153),
(138039, 'deDE', '', 'Ihr seid ein richtig großer, fetter Engel! $gMein Held:meine Heldin;!', 28153),
(138038, 'deDE', 'Sie haben Ahna nach Süden verschleppt, aber ich komme hier raus!', '', 28153),
(138037, 'deDE', 'Ich muss zu meinem Tempel zurückkehren, um dort vollends zu Kräften zu kommen. Ich warte dort auf Euch.', '', 28153),
(138036, 'deDE', 'Endlich bin ich frei.', '', 28153),
(138035, 'deDE', 'Kommt bald zurück zu mir, Norah.', '', 28153),
(138034, 'deDE', '', 'Wenn wir jetzt aufbrechen, werden wir in den Dünen verhungern.', 28153),
(138033, 'deDE', '', 'Das können wir nicht. Und Ihr wisst es.', 28153),
(138032, 'deDE', 'Ihr müsst das nicht tun, Norah. Wir können einfach alles zusammenpacken und Zem\'lan hinter uns lassen!', '', 28153),
(138031, 'deDE', '', 'Passt auf die Karawane auf, solange ich weg bin, Viggy.', 28153),
(138029, 'deDE', 'Ich war lange weg. Hoffen wir mal, ich hab da drin noch ein paar Freunde.', '', 28153),
(138028, 'deDE', 'Sobald Ihr Beweise habt, dass Aschenwind & Co. diesen Dreckskerlen Waffen verkauft, kommt zu mir auf den Hügel beim Haupttor.', '', 28153),
(138026, 'deDE', 'Okay, ich habe Eure... Beine. Was jetzt?', 'Okay, ich habe Eure... Beine. Was jetzt?', 28153),
(138025, 'deDE', 'Das wird das aufregendste Fest seit Jahren! Schwingt Euch auf Böttcher und gebt den Troggs Saures. Ihr werdet sehen, wie hilfreich er im Kampf ist!', '', 28153),
(138024, 'deDE', 'Fallhafen schuldet Euch etwas, $C. \n\nIch hoffe nur, dass wir diese Schuld beizeiten begleichen können.', '', 28153),
(138023, 'deDE', 'Ihr und Böttcher gebt ein tolles Team ab! Wenn Ihr wollt, könnt Ihr ihn jederzeit auf dem Anwesen reiten.', '', 28153),
(138021, 'deDE', 'Die meisten werd\'n nie wiss\'n, was Ihr für sie getan habt, aber ich werd das nie vergess\'n.', '', 28153),
(138020, 'deDE', '', 'Törichter Fremdling! Ihr wagt es, mich in meinem Reich herauszufordern?!', 28153),
(138019, 'deDE', '', 'Niemand wird Eure Schreie hören!', 28153),
(138018, 'deDE', 'Ein herzliches Willkommen unserem geschätzten Gast, $gLord:Lady; $n!', '', 28153),
(138017, 'deDE', 'Erlaubt mir, die Ankunft von $gLord:Lady; $n zu verkünden!', '', 28153),
(138016, 'deDE', 'Es ist mir ein Vergnügen, $gLord:Lady; $n auf dem Anwesen der Norwinsens zu begrüßen!', '', 28153),
(138015, 'deDE', '', 'Ich bin Jette. Bevor die Sirenen uns hergelockt haben, war ich Söldnerin auf einem Handelsschiff.$B$BDie Leute hier zogen mich aus dem Priel, gaben mir meinen Spitznamen und seitdem sind wir eine Familie.$B$BAuch wenn sie etwas komisch wirken, sind es gute und ehrliche Leute. Für einige war es ein willkommener Wandel, nach ihrem bisherigen Leben hier zu stranden. Die Chance auf einen Neuanfang. Andere versuchen einfach nur zu überleben, bis sie wieder nach Hause kommen.', 28153),
(138014, 'deDE', 'Xenxuju hat mich vom Kelch des Donners trink\'n lass\'n. Dank Xenxuju werd\'n wir alle bald eins mit Akunda sein!', '', 28153),
(138013, 'deDE', '', 'Kel\'vax hat... so viele Opfer... um Euch zu töt\'n...', 28153),
(138012, 'deDE', '', 'Ich glaub\', ich füg\' Euch den Leich\'nopfern für Kel\'vax hinzu!', 28153),
(138009, 'deDE', 'V-v-verschreckt unseren Gast nicht, Norah. W-w-wir können die Hilfe gebrauchen.', 'V-v-verschreckt unseren Gast nicht, Norah. W-w-wir können die Hilfe gebrauchen.', 28153),
(138008, 'deDE', 'Sagt, Fremdling, kennt Ihr die Legende von Zem\'lan?', 'Sagt, Fremdling, kennt Ihr die Legende von Zem\'lan?', 28153),
(137999, 'deDE', 'Ich glaube, ich gehe lieber nach da hinten. Da ist... das Licht besser zum Lesen. Viel Glück!', '', 28153),
(137997, 'deDE', '<Untersucht den Rucksack.>', '<Untersucht den Rucksack.>', 28153),
(137993, 'deDE', '<Das ist ein Kinderrucksack. Auf der Rückseite befindet sich ein Anstecker mit dem Wort \"Nachwuchsentdecker\".>', '', 28153),
(137988, 'deDE', 'Ich werde mir nur ein klein bisschen vom Schatz nehmen, bevor ich gehe...', 'Ich werde mir nur ein klein bisschen vom Schatz nehmen, bevor ich gehe...', 28153),
(137987, 'deDE', 'Danke. Das werde ich nicht vermissen.', 'Danke. Das werde ich nicht vermissen.', 28153),
(137986, 'deDE', 'Ich habe einen gewaltigen Fehler gemacht.', 'Ich habe einen gewaltigen Fehler gemacht.', 28153),
(137985, 'deDE', 'Habt Ihr ihre monströsen Haustiere gesehen? Dieser Ort ist ein Alptraum.', 'Habt Ihr ihre monströsen Haustiere gesehen? Dieser Ort ist ein Alptraum.', 28153),
(137984, 'deDE', 'Danke, $PR! Ich hätte nicht viel länger durchgehalten!', 'Danke, $PR! Ich hätte nicht viel länger durchgehalten!', 28153),
(137983, 'deDE', 'Ich stehe in Eurer Schuld.', 'Ich stehe in Eurer Schuld.', 28153),
(137982, 'deDE', 'Ich bin der letzte Überlebende meiner Karawane.', 'Ich bin die letzte Überlebende meiner Karawane.', 28153),
(137981, 'deDE', 'Was ich alles mit ansehen musste...', 'Was ich alles mit ansehen musste...', 28153),
(137926, 'deDE', 'Euer Freund is\' tot, $PR. Das is\' kein Ort für Sterbliche.', '', 28153),
(137925, 'deDE', '', 'Es gab also einen Troll namens Zem\'lan, der über diesen Hafen geherrscht hat? Dann muss das hier sein Thronsaal sein.', 28153),
(137924, 'deDE', 'Hmm. Eigentlich ist das Pilgerreise für Tortollaner. Wir ziehen zu Torga, um seinen Geschichten zu lauschen. Aber, hm, gut, Ihr dürft mitkommen.', '', 28153),
(137913, 'deDE', 'Ich hab das perfekte Geg\'nmittel geg\'n Schnüffler wie Euch.', '', 28153),
(137912, 'deDE', 'Den kleinen Kerl mochte ich sehr. Den Roboter mein ich.', '', 28153),
(137911, 'deDE', 'Ich hatte einen Spielzeugroboter. Einen kleinen zum Aufziehen, den ich bei einem Gnom in Boralus gekauft habe.', '', 28153),
(137909, 'deDE', 'Die Reagenzien zu sammeln, die für Eure Weihe nötig sin\', is\' der erste Schritt zur Erlösung.', '', 28153),
(137908, 'deDE', 'Lasst Xenxuju nich\' wart\'n. Aber seid vorsichtig. Mit ihm legt man sich besser nich\' an.', '', 28153),
(137907, 'deDE', '%s redet mehrere Minuten lang darüber, dass man die Verantwortung für seine eigenen Handlungen akzeptieren muss.', '', 28153),
(137906, 'deDE', 'Hm... vermutlich meinen Kompass. Der hat mich nie in die Irre geführt! Nun ja, bis wir hier gelandet sind. Aber das ist nicht die Schuld meines Kompasses. Das ist ja nur ein Gegenstand, auf den kann man nicht wirklich die Schuld schieben...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137905, 'deDE', 'Nun gut, Ihr dürft mitkommen... aber macht nicht zu viel Lärm! Das ist eine Pilgerreise, kein Karnevalsumzug.', '', 28153),
(137903, 'deDE', '', 'Beeindruck\'nd... aber wir hab\'n Arbeit. Es bleib\'n nur noch zwei Loa. Wir müss\'n uns den Tortollanern anschließ\'n auf ihrem Weg zu Torga, dem Schildkröt\'nloa.', 28153),
(137902, 'deDE', '', 'Ihr wollt mir also sag\'n, Bwonsamdi hilft Euch... un\' Ihr habt Hir\'eek getötet?', 28153),
(137901, 'deDE', 'Oh, das ist einfach! Meine gute alte Vesperdose. In der hat mich immer ein leckeres Mahl erwartet. Ich vermisse sie sehr.', '', 28153),
(137900, 'deDE', '', 'Endlich frei!', 28153),
(137899, 'deDE', 'Die Meisterin wird Eure Seele als Nächstes binden!', '', 28153),
(137898, 'deDE', '(Erzählt Talanji von Bwonsamdis Hilfe und Hir\'eeks Tod.)', '(Erzählt Talanji von Bwonsamdis Hilfe und Hir\'eeks Tod.)', 28153),
(137897, 'deDE', 'Die Meisterin wird Eure Seele als Nächstes nehmen!', '', 28153),
(137896, 'deDE', 'Sterbt für ihren Ruhm!', '', 28153),
(137895, 'deDE', 'Ich töte Euch für die Meisterin!', '', 28153),
(137894, 'deDE', '', 'Ihr müsst jetz\' los... Ich werd mich bald verwandeln, und ich will nich\', dass Ihr seht, was aus mir wird...', 28153),
(137893, 'deDE', 'Ich bin Kalle. Wenn was repariert werden muss, bin ich dabei.', '', 28153),
(137892, 'deDE', '', 'Es is\' zu spät für mich... aber für andre gibt\'s noch Hoffnung.', 28153),
(137891, 'deDE', 'Seid gegrüßt, $gReisender:Reisende;! Seid Ihr wie der Rest von uns im Priel angeschwemmt worden?$B$BIch weiß, es ist nicht viel, aber Ihr dürft in unserem Lager bleiben, so lange Ihr wollt.', '', 28153),
(137890, 'deDE', 'Durchsucht die Wüste nach den vermisst\'n Initianden. Ich werd hier auf Euch wart\'n.', '', 28153),
(137889, 'deDE', 'Was habt Ihr beim Schiffbruch verloren, das Euch viel bedeutet?', 'Was habt Ihr beim Schiffbruch verloren, das Euch viel bedeutet?', 28153),
(137888, 'deDE', 'Habt Ihr etwas zu essen?', '', 28153),
(137887, 'deDE', '', 'Das ist nicht gut. Gar nicht gut. Alle raus aus dem Wagen! Schnell!', 28153),
(137886, 'deDE', '', 'Das sin\' Jakra\'zets Truppen!', 28153),
(137885, 'deDE', '', 'Ich glaube nicht, dass die Trolle da vorne Eure Freunde sind.', 28153),
(137869, 'deDE', 'Narr! Ihr hättet flieh\'n soll\'n, als Ihr noch konntet! Akundas Macht wird mir gehör\'n!', '', 28153),
(137860, 'deDE', '', 'Dolly! Dot! Wartet! Da ist es nicht sicher!', 28153),
(137857, 'deDE', 'Wen ham wir denn da? Ihr seid noch am Leben, $n!', '', 28153),
(137851, 'deDE', 'Ruhm dem Sethrakimperium!', 'Ruhm dem Sethrakimperium!', 28153),
(137810, 'deDE', 'Auuu! Ich glaub, mein Bein is\' gebroch\'n.', '', 28153),
(137807, 'deDE', 'Dann mal los.', 'Dann mal los.', 28153),
(137806, 'deDE', 'Das Ritual is\' schon in vollem Gange. Hir\'eek wird jeden Moment auftauch\'n. Seid Ihr bereit?', '', 28153),
(137805, 'deDE', 'Trefft mich am Ritualkreis.', '', 28153),
(137789, 'deDE', 'Passt auf Euch auf, $C.', 'Passt auf Euch auf, $C.', 28153),
(137788, 'deDE', '<Der Körper des Loas wurde durch magische Bindungen außer Gefecht gesetzt.>', '', 28153),
(137787, 'deDE', 'Willkommen in meinem Tempel, $n. Dank Eurer mutigen Taten werdet Ihr hier stets mit Gastfreundschaft empfangen werden.', '', 28153),
(137785, 'deDE', '', 'Danke, Ihr beid\'n. Eure Treue bedeutet mir viel... mir und all\'n Zandalari.', 28153),
(137784, 'deDE', '', 'Ich kann bestimmt die Tortollaner in Nazmir überzeugen, uns zu helfen. Vielleicht kommen Shoak und Kajosh auch!', 28153),
(137783, 'deDE', 'Na gut, na gut. Wir kämpfen mit Euch gegen diesen Blutgott, Prinzessin. Wenn Ihr mich dann damit in Ruhe lasst!', '', 28153),
(137782, 'deDE', '', 'Passt gut auf den Loa auf, Lashk. Ich un\' $n müss\'n mehr Verbündete such\'n.', 28153),
(137781, 'deDE', 'Ha! Die schlaue alte Schildkröte... Er wollte noch nicht ruhen, er wollte wiedergeboren werden!', '', 28153),
(137780, 'deDE', '', 'Was um alles...', 28153),
(137779, 'deDE', '', 'Ich werd nich\' ruh\'n, bis G\'huun und die ganz\'n Bluttrolle ausradiert sin\'. Das schwör ich, Torga.', 28153),
(137778, 'deDE', '', 'Und ich werde unserem ganzen Volk erzählen, wie mutig Ihr gegen G\'huun gekämpft habt.', 28153),
(137777, 'deDE', 'Auf Wiedersehen, Torga. Ich werde Eure Geschichten nie vergessen... und sie weitergeben.', '', 28153),
(137776, 'deDE', '', 'Ihr seid stark. Aber meinen Kräften habt Ihr nichts entgegenzusetz\'n!', 28153),
(137764, 'deDE', '', 'Ja... Kehr\'n wir zum Schrein zurück.', 28153),
(137763, 'deDE', 'Uff! Eine Pause käme mir jetzt recht.', '', 28153),
(137762, 'deDE', '', 'Wow... unglaublich. Wir haben es wirklich geschafft!', 28153),
(137758, 'deDE', '', 'Der Hordechampion un\' ich komm\' Euch hol\'n... Und dann reiß\'n wir Euch in Stücke!', 28153),
(137757, 'deDE', '', 'Das hört jetz\' auf! Mein Volk wird nich\' weiter in Angst vor Euch un\' Euern Bluttrollen leb\'n.', 28153),
(137755, 'deDE', 'Das... beweist... GAR nichts! Er wird... ein neues Gefäß... suchen. Siegel... werden brechen... G\'huun... wird frei sein!', '', 28153),
(137754, 'deDE', 'Schnell! Tötet es, bevor es die größere Bedrohung in mir erkennt!', '', 28153),
(137753, 'deDE', 'Spürt meine treue Armbrust, garstiger Teufel!', '', 28153),
(137752, 'deDE', 'Haltet es still! Bei diesem Rumgeeier kann ja kein Mensch zielen!', '', 28153),
(137751, 'deDE', '', 'Was macht Ihrn da?! Wachen! Zu mir!', 28153),
(137750, 'deDE', 'WRAAHH! Ihr seid NICHTS gegenüber G\'huun! Leidet und STERBT!', '', 28153),
(137749, 'deDE', '', 'FÜR TORGA!', 28153),
(137748, 'deDE', '', 'Alle zusamm\'! JETZT!', 28153),
(137747, 'deDE', 'Eure Bemühungen... zwecklos... Ich bin... unbesieg- was? Nein. NEIN!', '', 28153),
(137746, 'deDE', '', 'Ihr seid zu selbstsicher. Das wird Euer Ende sein. Eure Macht kann Euch nich\' schütz\'n.', 28153),
(137745, 'deDE', 'Eure Bemühungen... zwecklos. Ich bin... unbesiegbar.', '', 28153),
(137744, 'deDE', '', 'Wartet nur, bis die anderen hören, dass wir G\'huuns Vorboten getötet haben!', 28153),
(137743, 'deDE', 'Es ist lange her, dass mein Herz so voller Feuer war. Für Torga!', '', 28153),
(137742, 'deDE', '', 'Schreit\'n wir zur Tat, für Zandalar... un\' für Torga.', 28153),
(137736, 'deDE', '', 'Großer Hir\'eek! Wir hab\'n ein Opfer aus Fleisch und Blut für Euch!', 28153),
(137734, 'deDE', 'Ja, ja. Wir kommen!', '', 28153),
(137733, 'deDE', '', 'Kommt! Wir müss\'n uns vorbereit\'n, um den Vorbot\'n des Blutgotts zu vernicht\'n.', 28153),
(137732, 'deDE', 'Vorsicht vor Spinnen, mein kleiner Saurid. Ich bin vielleicht der Gott der Geheimnisse, aber Yazma is\' die Herrin der Spione. Sie liebt\'s, ihre huschenden Späher in mein Reich zu schick\'n, immer auf der Jagd nach meinen Kindern.', '', 28153),
(137731, 'deDE', 'Ich bin bereit hineinzugehen.', 'Ich bin bereit hineinzugehen.', 28153),
(137730, 'deDE', '', 'Ich hätte nie gedacht, diese Ruinen einmal zu betreten. Das ist unglaublich!', 28153),
(137728, 'deDE', 'Jetzt seid Ihr nich\' mehr so groß und stark, was? Geht, mein Diener. Geht und findet diese Ratte Nokano, die Euch befohl\'n hat, meine Art zu töt\'n. Beißt ihn und verdient Euch Eure Gestalt zurück.', '', 28153),
(137721, 'deDE', '', 'Das könnte die beste Geschichte werden, die je ein Tortollaner erlebt hat. Rache für einen Loa und der Kampf gegen den Avatar eines Ungeheuers!', 28153),
(137720, 'deDE', 'Wisst Ihr, vielleicht gelingt es uns ja doch, den Vorboten von G\'huun zu töten.', '', 28153),
(137719, 'deDE', '', 'Wir beeil\'n uns lieber un\' schau\'n, was die Bluttrolle da vorne noch so treib\'n.', 28153),
(137718, 'deDE', '', 'Wir sind hier fertig, $n. Ich warte bei Aroms Wehr auf Euch.', 28153),
(137716, 'deDE', '', 'Die Hexe war mir überlegen und ich wurde gefangen.', 28153),
(137715, 'deDE', '', 'Vielen Dank, dass Ihr mich aus diesem üblen Konstrukt gerettet habt.', 28153),
(137710, 'deDE', '', 'Gut, los geht\'s. Und seid bloß leise. Es fehlt uns grad noch, dass Ihr zwei gefang\'n werdet.', 28153),
(137709, 'deDE', 'Natürlich. Ich besitze Schriftrollen, die älter sind als Ihr! Kisha, schaut in meinen Sachen nach.', '', 28153),
(137708, 'deDE', '', 'Wir müss\'n rausfind\'n, was die Bluttrolle vorhab\'n. Lashk, Kisha, habt Ihr irgendwas, was uns dabei irgendwie verberg\'n kann?', 28153),
(137707, 'deDE', '', 'Schließlich hat sich das Blatt dank unseren Gelehrten gewendet...', 28153),
(137706, 'deDE', 'Ich bin langsam zu alt für so etwas.', '', 28153),
(137705, 'deDE', 'Blutmagie! Warum sollte sich irgendwer damit abgeben?', '', 28153),
(137704, 'deDE', 'Davon werde ich den anderen erzählen.', '', 28153),
(137703, 'deDE', 'Erst bringen sie Torga um und jetzt uns! Was ist nur los mit diesen Trollen?', '', 28153),
(137702, 'deDE', 'Sie haben mir auch alle meine Schriftrollen gestohlen! Holt sie für mich zurück.', '', 28153),
(137701, 'deDE', 'Endlich ist das Glück mal auf meiner Seite!', '', 28153),
(137700, 'deDE', '', 'Ihr verhindert nich\', dass wir unsre Tortollaner ess\'n!', 28153),
(137699, 'deDE', '', 'Loa ess\'n wir nich\'... aber Tortollaner!', 28153),
(137697, 'deDE', '', 'Kachago!', 28153),
(137696, 'deDE', 'Glaubt bloß nicht die Lügen dieses Hausierers über seine faulen Produkte.\n\nEr hat mir mehrere Manuskripte verkauft, die sich alle als absurder Schwindel herausgestellt haben.\n\nWenn er glaubt, dass ich ohne eine Rückerstattung weggehe, irrt er sich aber gewaltig. \"So\" lange leben Trolle nun auch wieder nicht.', '', 28153),
(137695, 'deDE', 'Ich werde erst gehen, wenn ich eine Rückerstattung erhalten habe.', '', 28153),
(137694, 'deDE', 'Eure Schilderungen sind verwirrend und schlecht ausformuliert.', '', 28153),
(137693, 'deDE', 'Eure Bücher erzählen von Orten, die es einfach nicht gibt.', '', 28153),
(137692, 'deDE', 'Möge das Glück Euch hold sein, Sterbliche. Und... danke.', '', 28153),
(137691, 'deDE', 'Ihr verkauft Lügen, Erzählah.', '', 28153),
(137690, 'deDE', 'Vernichtet die Lager bei meiner Leiche, um Jungo zu schwächen.', '', 28153),
(137689, 'deDE', 'Prinzessin Talanji, die Bluttrolle ermächtigen Jungo mit meinen Überresten.', '', 28153),
(137678, 'deDE', '', 'Leiht uns Eure Weisheit, großer Torga. Sagt uns, wie wir die Bluttrolle aufhalt\'n könn\'!', 28153),
(137677, 'deDE', 'Ich bin hier. Sagt mir, was Ihr wünscht.', '', 28153),
(137676, 'deDE', 'Torga! Euer Geist wird verlangt. Streckt ma\' Euern Kopf raus.', '', 28153),
(137675, 'deDE', '', 'Guzincha!', 28153),
(137674, 'deDE', 'Argggh...', '', 28153),
(137673, 'deDE', 'Graaaagh!', '', 28153),
(137672, 'deDE', '', 'Niemand entkommt dem Blutgott!', 28153),
(137671, 'deDE', '\"Blöde Ziege. Lass uns gehen, bevor du von Monstern aufgefressen wirst.\"', '\"Blöde Ziege. Lass uns gehen, bevor du von Monstern aufgefressen wirst.\"', 28153),
(137670, 'deDE', '', 'Euer Blut für G\'huun!', 28153),
(137669, 'deDE', '\"He, Marzipan. Du scheinst dich verlaufen zu haben. Komm mit. Ich bringe dich nach Hause, ja?\"', '\"He, Marzipan. Du scheinst dich verlaufen zu haben. Komm mit. Ich bringe dich nach Hause, ja?\"', 28153),
(137668, 'deDE', '', 'Eure Knoch\'n werd\'n uns gut dienen!', 28153),
(137667, 'deDE', '', 'Ich will Euer Blut!', 28153),
(137666, 'deDE', '', 'Frischfleisch!', 28153),
(137665, 'deDE', '', 'Zuldazar wird fall\'n!', 28153),
(137664, 'deDE', 'Ich bin nich\' hier, um die Händler oder Euch zu beschütz\'n. Meine Aufgabe isses, die Alpträume ausm Norden zu bekämpf\'n. Bluttrolle, Schlang\'nmacka, Allianz und solche Sach\'n.\n\nIch muss auch gegen Langeweile kämpf\'n, aber vor allem gegen das andre Zeugs. Warum seid Ihr hier?', 'Ich bin nich\' hier, um die Händler oder Euch zu beschütz\'n. Meine Aufgabe isses, die Alpträume ausm Norden zu bekämpf\'n. Bluttrolle, Schlang\'nmacka, Allianz und solche Sach\'n.\n\nIch muss auch gegen Langeweile kämpf\'n, aber vor allem gegen das andre Zeugs. Warum seid Ihr hier?', 28153),
(137663, 'deDE', '<Die kleine Ziege scheint von einem Hof entlaufen zu sein.\n\nDer Name auf dem Halsband lautet \"Marzipan\".>', '', 28153),
(137662, 'deDE', '', 'Blut! Blut! Blut!', 28153),
(137661, 'deDE', 'Hab gehört, Ihr habt Prinzessin Talanji zurückgebracht. Da habt Ihr mein\' Dank für.\n\nAber man sagt auch, Ihr habt Zul zurückgebracht. Da habt Ihr mein\' Zorn für.\n\nWas wollt Ihr?', 'Hab gehört, Ihr habt Prinzessin Talanji zurückgebracht. Da habt Ihr mein\' Dank für.\n\nAber man sagt auch, Ihr habt Zul zurückgebracht. Da habt Ihr mein\' Zorn für.\n\nWas wollt Ihr?', 28153),
(137660, 'deDE', 'Haltet Ihr mich für \'n Händler? Ich bin \'n Krieger! Das is\' \'ne höhere Kaste, Mann.\n\nUn\' was braucht Ihr?', 'Haltet Ihr mich für \'n Händler? Ich bin \'n Krieger! Das is\' \'ne höhere Kaste, Mann.\n\nUn\' was braucht Ihr?', 28153),
(137659, 'deDE', 'Braucht Ihr irgendwas? Wenn nich\', geht weiter.', 'Braucht Ihr irgendwas? Wenn nich\', geht weiter.', 28153),
(137658, 'deDE', 'Ihr habt aber nich\' irgendwelchen Voodookrams von den Bluttroll\'n dabei, oder? Nein? Gut.\n\nWozu seid Ihr also hier?', 'Ihr habt aber nich\' irgendwelchen Voodookrams von den Bluttroll\'n dabei, oder? Nein? Gut.\n\nWozu seid Ihr also hier?', 28153),
(137657, 'deDE', 'Es heißt, dass die Bluttrolle neue Wege in unsre Gesellschaft gefund\'n hab\'n. Wenn sie uns nich\' erobern könn\', versuch\'n sie eben, uns zu bekehr\'n.\n\nWohl eher beides, aber egal. Was braucht Ihr?', 'Es heißt, dass die Bluttrolle neue Wege in unsre Gesellschaft gefund\'n hab\'n. Wenn sie uns nich\' erobern könn\', versuch\'n sie eben, uns zu bekehr\'n.\n\nWohl eher beides, aber egal. Was braucht Ihr?', 28153),
(137656, 'deDE', 'Mein Cousin is\' da unten am Bluttor und darf richtig kämpfen. Und ich? Ich darf Sauridendienst schieb\'n. Pah!\n\nUn\' was wollt Ihr?', 'Mein Cousin is\' da unten am Bluttor und darf richtig kämpfen. Und ich? Ich darf Sauridendienst schieb\'n. Pah!\n\nUn\' was wollt Ihr?', 28153),
(137655, 'deDE', 'Bwonsamdi, wir sind bereit für Eure Beschwörung von Torgas Geist.', 'Bwonsamdi, wir sind bereit für Eure Beschwörung von Torgas Geist.', 28153),
(137654, 'deDE', '\"Geht nach Nazmir und hört Euch die Geschichten von Torga an\", haben sie gesagt. \"Das wird lustig\", haben sie gesagt.', '', 28153),
(137652, 'deDE', 'Die Hülle dieses Loas... nährt mich. Nährt... G\'huun.', '', 28153),
(137651, 'deDE', 'Ich spreche... für G\'huun. Er... befiehlt. Ihr... dient... oder sterbt.', '', 28153),
(137643, 'deDE', 'Ich würd\' zu gern\' ihre Schreie hör\'n, aber wir müss\'n leise sein. Wir woll\'n nicht auch noch erwischt werd\'n.', '', 28153),
(137642, 'deDE', 'Ah! Freiheit!', '', 28153),
(137641, 'deDE', 'Oh, und wenn Ihr jemals \'nem Troll namens Sur\'jan begegnet, durchbohrt sein Herz mit meiner Klaue! Das hatter verdient!', '', 28153),
(137640, 'deDE', 'Ich dank\' Euch für alles, Mann!', '', 28153),
(137639, 'deDE', '', 'Mit der Brut von Hir\'eek, die uns flieg\'n lässt, un\' der Kraft des Blutgottes werd\'n wir die Zandalari vernicht\'n!', 28153),
(137638, 'deDE', 'Danke für die Beinarbeit, $p. Wenn Ihr schon auf dem Weg nach draußen seid, sagt Grusli doch, dass sie mir etwas Wasser schicken soll, okay?', '', 28153),
(137637, 'deDE', 'Seid vorsichtig! Die Treants drehen durch und töten jeden, der ihnen zu nahe kommt.', '', 28153),
(137620, 'deDE', 'Eure Größe tut nichts zur Sache. Euer Geist ist größer als alle, die ich in diesen Hügeln angetroffen habe.', '', 28153),
(137619, 'deDE', '', 'Danke, Sumber! Ich möchte alles lernen, was Ihr eine kleine Vulpera wie mich lehren könnt.', 28153),
(137618, 'deDE', 'Ich habe einen Teil meiner Macht in dieses Totem geleitet. Nutzt es weise.', '', 28153),
(137616, 'deDE', '', 'Sehr gern, Sumber. Wir beide sind froh, Euch auf jede nur mögliche Art zu helfen.', 28153),
(137615, 'deDE', 'Ich bin beeindruckt! Es war weise von Euch, mir diese Essenz zu bringen.', '', 28153),
(137614, 'deDE', '', 'Gah! Dieses Wasser bewegt sich so schnell. Ich kann es nicht kontrollieren!', 28153),
(137610, 'deDE', '', 'Haltet Ausschau nach großen Wasserpfützen. Es gibt nicht viele in Vol\'dun. Sie sollten leicht zu erkennen sein.', 28153),
(137609, 'deDE', '', 'Legt Euch ins Zeug, wenn ich bitten darf. Wir wollen so richtig Eindruck bei Sumber schinden.', 28153),
(137608, 'deDE', '', 'Was auch immer dort unten vorgeht, holt Euch einfach das Wasser und verschwindet wieder. Lasst Euch in nichts reinziehen.', 28153),
(137607, 'deDE', 'Dort unten lauern mächtige Wesen, $p. Lasst Euch in all Euren Schritten und Entscheidungen von Weisheit leiten.', '', 28153),
(137606, 'deDE', 'Ruhm und Ehre, $p.', '', 28153),
(137605, 'deDE', '', 'Wer Ihr auch seid, die Arbeit eines Tages bleibt einen Tageslohn wert.', 28153),
(137604, 'deDE', 'Ein mächtiger Bezwinger des Bösen wie $p bekämpft Monster nicht für Euer Geld, Maiya. Wir tun es für den Ruhm!', '', 28153),
(137603, 'deDE', '', 'Alles kann repariert werden, wenn man nur hart genug arbeitet, Heiro.', 28153),
(137602, 'deDE', 'Seid Ihr sicher, dass wir den Wagen überhaupt reparieren können? Die Ranishu haben eine Menge davon gefressen.', '', 28153),
(137601, 'deDE', 'Und jetzt zum schönsten Teil: Leute abmurks\'n und mehr Seelen für mich samm\'ln.', '', 28153),
(137597, 'deDE', 'Es brennt ein Feuer in Euch, Talanji. Aber meine Hilfe wird Euch was kost\'n.', '', 28153),
(137594, 'deDE', '', 'Spart Euch die Spielchen. Ihr wollt die Seele von \'nem Loa? Hir\'eek wurde schon von $n getötet. Holt Euch doch SEINE Seele.', 28153),
(137590, 'deDE', 'Hah... Wie wär\'s mit \'nem Handel? Bringt mir die Seele von \'nem andern Loa, dann hol ich Euch Torgas Geist.', '', 28153),
(137588, 'deDE', 'Lasst mich raten... Hmm... Ihr wollt mit der Seele vom arm\' Torga red\'n.', '', 28153),
(137587, 'deDE', 'Ich bin bereit für den Versuch, Bwonsamdi zu beschwören.', 'Ich bin bereit für den Versuch, Bwonsamdi zu beschwören.', 28153),
(137586, 'deDE', 'Und reden hilft nicht. Wir müssen einen anderen Weg finden, um sie aufzuhalten. Oder ihnen zu entkommen, wie es Euch gelungen ist.', '', 28153),
(137585, 'deDE', 'Ich benachrichtige Grusli und die anderen. $gEin:Eine:r; $PR ist für die Ranishu ein gefundenes Fressen... wie alles andere auch.', '', 28153),
(137584, 'deDE', 'Haha, seht nur, wie $gdieser:diese:r; $PR rennen kann! Fallt nicht hin!', '', 28153),
(137583, 'deDE', 'Mampf-Mampf groß! Essen Maske! Alle $PR essen!', '', 28153),
(137582, 'deDE', '', 'Die Bluttrolle werden sich wünsch\'n, dass sie sich nie mit uns angelegt hätt\'n.', 28153),
(137581, 'deDE', '<Zieht an der Fackel.>', '<Zieht an der Fackel.>', 28153),
(137580, 'deDE', '<Bei näherer Betrachtung scheint die Fackel mit einer Art Mechanismus in der Mauer verbunden zu sein.>', '', 28153),
(137579, 'deDE', '<Das ist ein Paar alter Stiefel.\n\nWas habt Ihr denn erwartet?>', '', 28153),
(137578, 'deDE', '<Ihr findet keinen verborgenen Eingang unter dem Teppich.\n\nEr macht das Zimmer aber auch überhaupt erst gemütlich.>', '', 28153),
(137577, 'deDE', '<Überraschenderweise ist das hervorstehende Buch kein geheimer Hebel für einen verborgenen Eingang.>', '', 28153),
(137576, 'deDE', '<Der Anker ist fest an der Wand angebracht.>', '', 28153),
(137575, 'deDE', '', 'Das kann ich Euch sag\'n: die Bluttrolle. Folgt mir... Die werd\'n bezahl\'n!', 28153),
(137574, 'deDE', '', 'Wer konnte Torga so etwas antun? Er wollte doch nur seine Geschichten erzählen!', 28153),
(137573, 'deDE', 'Torga. NEIN!', '', 28153),
(137572, 'deDE', 'Torga wurde niedergestreckt wie irgendein dahergelaufenes Tier!', '', 28153),
(137571, 'deDE', 'All die Geschichten von Torga sind... für immer verloren!', '', 28153),
(137570, 'deDE', 'Ein Loa ist... tot?', '', 28153),
(137569, 'deDE', 'Wie konnte das passieren?', '', 28153),
(137568, 'deDE', '', 'Dieses Wissen wurde hier verborgen und sicher verwahrt.', 28153),
(137563, 'deDE', 'Ich suche Arbeit.', 'Ich suche Arbeit.', 28153),
(137561, 'deDE', '', 'Pah! Sehe ich aus wie eine Reiseführerin? Ich bin nur hier, um Torgas Geschichten zuzuhören.', 28153),
(137560, 'deDE', '', 'Ich mache mich besser vom Acker, bevor mich noch jemand nach dem Weg fragt.', 28153),
(137559, 'deDE', '', 'Also, folgt einfach weiter der Straße, dann findet Ihr Torga. Er ist eine riesige Schildkröte... Kann man nicht übersehen.', 28153),
(137558, 'deDE', '', 'Pah! Was geht Euch das überhaupt an? Ich entscheide, wie ich pilgere.', 28153),
(137557, 'deDE', 'Eine \"Pilgerschaft\"? Ihr steht doch nur nutzlos herum! Lashk meinte, Ihr wüsstet, wo Torga sich aufhält.', 'Eine \"Pilgerschaft\"? Ihr steht doch nur nutzlos herum! Lashk meinte, Ihr wüsstet, wo Torga sich aufhält.', 28153),
(137556, 'deDE', 'Lashk erzählte mir, Ihr wüsstet, wo ich Torga finden kann.', 'Lashk erzählte mir, Ihr wüsstet, wo ich Torga finden kann.', 28153),
(137555, 'deDE', 'Was wollt Ihr? Könnt Ihr nicht sehen, dass ich gerade mit Pilgern beschäftigt bin?', '', 28153),
(137554, 'deDE', 'Ich glaube, wir werden uns gut verstehen, Prinzessin.', '', 28153),
(137553, 'deDE', '', 'Das is\' nich\' das erste Mal, dass ich mit Euch Tortollanern zu tun hab\' un\' Euern endlos\'n Geschicht\'n. Konzentriert Euch un\' lauft weiter!', 28153),
(137552, 'deDE', 'Gut, dann auf zu Torga! Aber denkt daran: nicht zu viel Lärm machen. Ich will keine einzige Geschichte verpassen!', '', 28153),
(137551, 'deDE', 'Nun denn. Wir haben nicht vor, uns irgendeiner Sache anzuschließen, aber kommt mit uns, wenn Ihr wollt.', '', 28153),
(137550, 'deDE', 'Was wollt Ihr?', '', 28153),
(137549, 'deDE', 'Es wär klug, Eure Antwort zu überdenk\'n.', '', 28153),
(137548, 'deDE', 'Ich kenn nur Akunda.', '', 28153),
(137547, 'deDE', 'Ich frag nach Euerm Namen, doch Ihr erzählt Geschicht\'n?', '', 28153),
(137546, 'deDE', 'Todesschwinge? Was für \'ne kümmerliche Kreatur trägt so \'nen Namen?', '', 28153),
(137545, 'deDE', '~Ihr werdet Zugang zum Stärkungszauber dieses Loas erhalten. Dieses System ist noch in Bearbeitung.', '~Ihr werdet Zugang zum Stärkungszauber dieses Loas erhalten. Dieses System ist noch in Bearbeitung.', 28153),
(137544, 'deDE', 'Ich kümmere mich sofort darum.', 'Ich kümmere mich sofort darum.', 28153),
(137543, 'deDE', '', 'Die Pflanzenwelt dieser Schlucht kämpft ums Überleben, genau wie auch der Rest von uns.', 28153),
(137542, 'deDE', 'Ich kann Euch nicht genug danken. Ich gehe jetzt so weit weg von hier wie irgend möglich.', 'Ich kann Euch nicht genug danken. Ich gehe jetzt so weit weg von hier wie irgend möglich.', 28153),
(137541, 'deDE', '', 'Hallo! Mögt Ihr Feuer? Oder Raketen? Oder Raketen mit viel Feuer? Ich habe Euch so viele tolle Dinge zu zeigen, dass ich es kaum abwarten kann!', 28153),
(137540, 'deDE', 'Himmel! Was war das denn für ein... Ding?', 'Himmel! Was war das denn für ein... Ding?', 28153),
(137537, 'deDE', '', 'Nein, ist es nicht. Aber durch die Schlucht wollt Ihr nicht, die ist voller Alpträume.', 28153),
(137536, 'deDE', '', 'Haltet Euch fest. Gleich wird\'s ganz schön holprig!', 28153),
(137535, 'deDE', 'Das kann doch nich\' die einzige Straße sein...', '', 28153),
(137534, 'deDE', '', 'Also nach Süden. Aber Ihr solltet wissen, dass die Berge dort verflucht sind. Diejenigen, die sich dort hinwagen, kommen nie mehr zurück.', 28153),
(137533, 'deDE', 'Es muss hier sein. Ich seh da vorne \'n Bauwerk.', '', 28153),
(137531, 'deDE', 'Wir sollt\'n nach Süden. Der Tempel is\' irgendwo in diesen Hügeln.', '', 28153),
(137530, 'deDE', 'Ich kann Euch versichern, dass meine Unterkünfte rustikal, aber sehr komfortabel sind.', '', 28153),
(137529, 'deDE', 'Akunda hat uns die Chance gegeb\'n, die Vergangenheit ruh\'n zu lassen und einen neuen Anfang zu mach\'n.', '', 28153),
(137528, 'deDE', '', 'Die Horde muss ausgelöscht werden. Zuldazar muss sich der Allianz beugen!', 28153),
(137526, 'deDE', 'Hm. So schlimm ist es hier nicht. Wir sind auf Pilgerschaft. Und irgendwas sagt mir, dass Ihr alles nur noch komplizierter machen werdet.', '', 28153),
(137525, 'deDE', '', 'Tortollaner! Was führt\'n Euch an dies\'n verflucht\'n Ort?', 28153),
(137523, 'deDE', 'Die Antwort wird Euch vielleicht nich\' gefall\'n, $n. Ich verdien meine Strafe in den Sanden, da gibt\'s keine Zweifel.', '', 28153),
(137517, 'deDE', 'Was habt Ihr getan, um hier zu enden?', 'Was habt Ihr getan, um hier zu enden?', 28153),
(137516, 'deDE', 'Klingt nich\' übel: \'ne Chance, meine Vergangenheit hinter mir zu lass\'n un\' noch mal von vorn zu beginn\'n. Diese Trolle sin\' vielleicht am Ende doch gar nich\' so irre.', '', 28153),
(137515, 'deDE', 'Ich verdank Rakera mein Leben. Keiner von uns Verbannten hätt die Sande ohne ihre Führung überlebt.', '', 28153),
(137509, 'deDE', 'Da! Nehmt\'s doch! Aber lasst mich geh\'n!', '', 28153),
(137508, 'deDE', 'Rupert, tanz!', '', 28153),
(137505, 'deDE', 'Ich hab die Frau geseh\'n, nach der Ihr gefragt habt. Sie hat die Prüfungen mit Leichtigkeit bestand\'n, hatte aber wohl kein Interesse daran, lange hierzubleib\'n.\n\nSie hat was gesucht. Hat Frag\'n gestellt, genau wie Ihr, aber is\' so schnell verschwund\'n, wie sie gekomm\'n war. Nach Süden wollte sie, un\' da solltet Ihr auch hin.\n\nDieser Tempel is\' nich\' sicher.', '', 28153),
(137504, 'deDE', '', 'Wir alle sin\' Akunda.', 28153),
(137502, 'deDE', 'Rupert, hierher!', '', 28153),
(137501, 'deDE', 'Habt Ihr Kriegswache Rakera gesehen?', 'Habt Ihr Kriegswache Rakera gesehen?', 28153),
(137500, 'deDE', 'Akunda verleiht uns Stärke.', 'Akunda verleiht uns Stärke.', 28153),
(137499, 'deDE', 'Ohne Akunda sin\' wir nichts.', 'Ohne Akunda sin\' wir nichts.', 28153),
(137498, 'deDE', 'Akunda gewährt uns seine Macht.', 'Akunda gewährt uns seine Macht.', 28153),
(137497, 'deDE', 'Wir alle sin\' Akunda.', 'Wir alle sin\' Akunda.', 28153),
(137496, 'deDE', 'Sie ist nich\' Akunda.', '', 28153),
(137495, 'deDE', '', 'Wenn sie nich\' Akunda ist, hat sie keinen Zutritt.', 28153),
(137494, 'deDE', 'Nur Akunda wandelt in diesem Tempel.', '', 28153),
(137493, 'deDE', 'Mit dem Namen gibt\'s niemand hier.', '', 28153),
(137492, 'deDE', '', 'Ich seh\' nur diejenigen, die Akundas Macht würdig sind.', 28153),
(137491, 'deDE', 'Warum gebt Ihr Euch mit den\' ab, die nich\' Akunda sin\'?', '', 28153),
(137490, 'deDE', '', 'Rakera? \'n seltsamer Name.', 28153),
(137489, 'deDE', 'Innen saftig! Mampf! Mampf!', '', 28153),
(137488, 'deDE', 'Still! Wir woll\'n doch nich\', dass diese verrückt\'n Kultist\'n wiss\'n, dass wir so red\'n.', '', 28153),
(137487, 'deDE', 'Wollt Ihr eins mit Akunda werd\'n, mein Kind? Dient mir fleißig, und ich werd\' Euren Wunsch erfüllen...', '', 28153),
(137486, 'deDE', 'Ihr da! Trinkt nich\' aus dem Kelch da.', '', 28153),
(137485, 'deDE', 'Mampf! Mampf! Mampf!', '', 28153),
(137484, 'deDE', 'Habt Ihr mich etwa nich\' gehört? Trinkt aus dem Kelch, und Ihr werdet\'s bereu\'n.', '', 28153),
(137483, 'deDE', 'Salja schläft immer drüben im Nordturm. Ein Tropfen von mei\'m Gift un\' die wacht nie wieder auf. Bringt auf jeden Fall den Schlüssel mit!', '', 28153),
(137482, 'deDE', '', 'Kenn\' wir uns? Ihr kommt mir bekannt vor...', 28153),
(137480, 'deDE', 'Wenn ich rauskomm, werdet Ihr dafür büß\'n!', '', 28153),
(137479, 'deDE', 'Lasst mich raus oder Ihr werdet das schwer bereu\'n!', '', 28153),
(137478, 'deDE', 'Holt mich aus diesem Käfig raus oder ich zeige Euch \'ne neue Bedeutung von Alptraum.', '', 28153),
(137477, 'deDE', 'Nie zuvor habe ich so etwas gesehen... Das Fleisch hat die Ranishu nur noch hungriger gemacht. Der alte Unterholz hatte keine Chance!', '', 28153),
(137476, 'deDE', 'Ha! Das kitzelt... Autsch! Das tut weh! Aufhören!', '', 28153),
(137475, 'deDE', 'Ich gebe Euch NICHT die Erlaubnis, mich zu verschlingen, ihr widerlichen Kreaturen!', '', 28153),
(137472, 'deDE', '<Die Augen des alten Unterholz sind kalt und leblos.>', '', 28153),
(137466, 'deDE', 'Haltet im Norden nach Fresser Ni-Ni Ausschau. Großer Käfer mit Unmengen an toten Dingen um sich rum. Ihr müsst ihn nur zerquetschen, um an seine Maske zu kommen!', '', 28153),
(137465, 'deDE', '', 'Torgas Blut gibt uns Kraft!', 28153),
(137464, 'deDE', '', 'Torgas Blut gehört jetzt uns!', 28153),
(137463, 'deDE', 'Ah, endlich hat das Jucken ein Ende. Süße Einsamkeit ist immer noch am genüsslichsten.', '', 28153),
(137462, 'deDE', 'Hör nicht auf den ignoranten Jäger, Rupert. Du wirst den perfekten Gefährten abgeben.', '', 28153),
(137461, 'deDE', 'Das ist ein Bär. Ach, seht einfach zu, dass Ihr ihn verschwinden lasst, bevor einer der Holstens ihn sieht.', 'Das ist ein Bär. Ach, seht einfach zu, dass Ihr ihn verschwinden lasst, bevor einer der Holstens ihn sieht.', 28153),
(137460, 'deDE', 'So ein Quatsch. Ich habe dieses arme kleine Hündchen mitgenommen, als ich jagen war. Und dann habe ich mich entschlossen, ihm Kunststückchen beizubringen.', '', 28153),
(137459, 'deDE', 'I-Ist das ein Bär?!', 'I-Ist das ein Bär?!', 28153),
(137458, 'deDE', 'Rupert, schau was $gder gütige:die gütige:c; $C uns gebracht hat. Zeig $gihm:ihr; deine Dankbarkeit! Tanze ein wenig!', '', 28153),
(137457, 'deDE', 'Willkommen, Akunda der Tapferkeit.', '', 28153),
(137456, 'deDE', 'Willkommen, Akunda des Gleichmuts.', '', 28153),
(137455, 'deDE', 'Willkommen, Akunda der Flinkheit.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137454, 'deDE', 'Ich habe Todesschwinge getötet. Sicher habt Ihr von mir gehört?', 'Ich habe Todesschwinge getötet. Sicher habt Ihr von mir gehört?', 28153),
(137453, 'deDE', 'Die Kunde meines Triumphes über den Lichkönig ist nicht bis an Eure Küsten gedrungen?', 'Die Kunde meines Triumphes über den Lichkönig ist nicht bis an Eure Küsten gedrungen?', 28153),
(137452, 'deDE', 'Ich habe die Brennende Legion bezwungen. Im Ernst? Ihr wisst nicht, wer ich bin?', 'Ich habe die Brennende Legion bezwungen. Im Ernst? Ihr wisst nicht, wer ich bin?', 28153),
(137451, 'deDE', 'Weg von mir, Ihr feigen Plagegeister! Verschlingt Euer begehrtes Fleisch und lasst die Bäume in Ruhe!', '', 28153),
(137450, 'deDE', 'Mein Name ist Akunda der Flinkheit.', 'Mein Name ist Akunda der Flinkheit.', 28153),
(137449, 'deDE', 'Mein Name ist Akunda des Gleichmuts.', 'Mein Name ist Akunda des Gleichmuts.', 28153),
(137448, 'deDE', 'Mein Name ist Akunda der Tapferkeit.', 'Mein Name ist Akunda der Tapferkeit.', 28153),
(137447, 'deDE', 'Mein Name bleibt unverändert.', 'Mein Name bleibt unverändert.', 28153),
(137446, 'deDE', 'Bis jetzt habt Ihr ein Leb\'n ohne Bedeutung gelebt.\n\nWas Ihr getan habt und wer Ihr mal wart, is\' jetzt Geschichte.\n\nSprecht Euren wahr\'n Namen, damit ihn alle hör\'n!', '', 28153),
(137444, 'deDE', 'Viele suchen Schutz in uns\'rem Tempel, aber nur wer sich als würdig erweist, wird eingelass\'n.', '', 28153),
(137438, 'deDE', 'Ha! Zusammen werden wir diese Bestie töten!', '', 28153),
(137437, 'deDE', 'Langzahn hat jetzt Verbündete und greift mit neu gewonnener Kraft an!', '', 28153),
(137436, 'deDE', 'Langzahn heult als Dank an Euch triumphierend auf und legt sich nieder, um endlich zu ruhen.', '', 28153),
(137435, 'deDE', 'Ich danke Euch. Jetzt kann ich ruhen.', '', 28153),
(137434, 'deDE', 'Willkommen in meinem Hain, $p... oder in dem, was davon übrig ist.', '', 28153),
(137432, 'deDE', 'Ich halte das nich\' mehr aus, Mann! Das is\' zu viel!', '', 28153),
(137431, 'deDE', 'Vergesst\'s, Mann! Vielleicht verleiht MIR Hir\'eek seine Macht, wenn ich EUCH opfere!', '', 28153),
(137430, 'deDE', 'Keine Opfer mehr von uns! Erhebt Euch, Brüda!', '', 28153),
(137429, 'deDE', 'Ihr und die Hohepriesterin sollt in der Hölle verrott\'n!', '', 28153),
(137428, 'deDE', 'Ich werd\' nicht wie ein Tier leb\'n!', '', 28153),
(137427, 'deDE', 'Die Hohepriesterin fordert von Euch ein Zeichen Eurer Unterwerfung.\n[Befreit den Akkordarbeiter.]', 'Die Hohepriesterin fordert von Euch ein Zeichen Eurer Unterwerfung.\n[Befreit den Akkordarbeiter.]', 28153),
(137426, 'deDE', 'Bringt Essen oder werdet gefressen!', '', 28153),
(137425, 'deDE', 'In Vol\'dun ist nichts so einfach, wie es sein sollte.\n\nIch brauche einfach nur etwas Holz, um meinen Wagen zu reparieren.', '', 28153),
(137424, 'deDE', '', 'Haha... zu spät... Der Blutgott... is\' hier!', 28153),
(137423, 'deDE', '', 'Der Herold is\' komplett. Ihr könnt das hier nich\' aufhalt\'n!', 28153),
(137422, 'deDE', 'Euresgleichen mag das lustig erscheinen, aber die Ranishu sind eine ernstzunehmende Plage.\n\nAllerdings kitzeln sie auch ein wenig.', '', 28153),
(137421, 'deDE', 'Niemand kann uns nich\' aufhalten! Die Männer werd\'n sich erheben!', '', 28153),
(137420, 'deDE', 'Passt besser auf, was ihr macht, Mann. Ihr Frauen werdet nich\' mehr lang\' an der Macht sein!', '', 28153),
(137419, 'deDE', 'Ihr werdet schon seh\'n, Mann. Meine Brüder und ich werd\'n von hier entkomm\'n und dann übernehm\'n WIR die Herrschaft!', '', 28153),
(137418, 'deDE', 'Wollt Ihr mich etwa wieder rumschubs\'n? Ich hab keine Angst vor Euch!', '', 28153),
(137417, 'deDE', 'Torgas Blut gibt uns Kraft!', '', 28153),
(137416, 'deDE', 'Torgas Blut gehört jetzt uns!', '', 28153),
(137414, 'deDE', 'Wir bring\'n das Loafleisch zu den andern. Un\' Ihr haltet uns nich\' auf!', '', 28153),
(137413, 'deDE', 'Das Fleisch vom Loa gehört uns. Und das von Euch auch!', '', 28153),
(137412, 'deDE', '', 'Nun gut, dann hätten wir jetzt ein paar Hexen zu töten.', 28153),
(137411, 'deDE', '', 'So erhebt sich der Glutorden von Neuem.', 28153),
(137410, 'deDE', '', 'Mit seinem Wissen wird es Euch und unseren Truppen gelingen, den dunklen Zirkel zu vernichten, der unser Land plagt.', 28153),
(137409, 'deDE', '', 'Nehmt das Buch, wenn Ihr bereit seid, dem Pfad des Ordens zu folgen.', 28153),
(137408, 'deDE', '', 'Hier ist er... der letzte Unterschlupf des Glutordens. Seid Ihr bereit, die Vergangenheit zum Leben zu erwecken?', 28153),
(137407, 'deDE', '', 'Kommt mit, das Buch müsste hier sein!', 28153),
(137406, 'deDE', '', 'Ach... natürlich geht es Euch gut. Um Euch in die Knie zu zwingen, braucht es mehr als ein paar Steinchen!', 28153),
(137405, 'deDE', '', 'So ein großes Konstrukt habe ich noch nie gesehen! Geht es Euch gut?', 28153),
(137404, 'deDE', '', 'Hir\'eek wird... mich räch\'n...', 28153),
(137403, 'deDE', '', 'Meine Seele für G\'huun!', 28153),
(137402, 'deDE', '<Helft Henri Wellenbruch und beendet die Pattsituation.>', '<Helft Henri Wellenbruch und beendet die Pattsituation.>', 28153),
(137401, 'deDE', '', 'Das Loafleisch gehört uns!', 28153),
(137400, 'deDE', '', 'Hinter Euch!', 28153),
(137399, 'deDE', '', 'Ehre sei... Hir\'eek...', 28153),
(137398, 'deDE', '', 'Wir nehmen uns Loafleisch, wir ESSEN Loafleisch!', 28153),
(137397, 'deDE', '', 'Moment... Hier stimmt etwas nicht.', 28153),
(137396, 'deDE', '', 'Hmm... Diese Trümmer versperren uns den Weg. Könntet Ihr sie beiseiteschaffen?', 28153),
(137395, 'deDE', '', 'Mit diesem neuen Wissen gelang es unseren Männern, die Drust in ihre Bergfesten zurückzudrängen.', 28153),
(137394, 'deDE', '', 'Sie sammelten ihre Erkenntnisse in einer Abhandlung über Waffen und Taktiken. Sie sollte uns helfen, die Barbaren zu besiegen.', 28153),
(137393, 'deDE', '', 'Wie ich sagte... Das Blatt hat sich gewendet, als unsere Gelehrten Schwächen der Drustmagie entdeckten.', 28153),
(137392, 'deDE', '', 'Danke. Ich dachte schon, es wäre um mich geschehen.', 28153),
(137391, 'deDE', '', 'Wartet... passt auf!', 28153),
(137390, 'deDE', '', 'Die Kronsteigs sind seit jeher zäh, aber die Magie der Drust war stark. Wir waren ihnen unterlegen...', 28153),
(137389, 'deDE', '', 'Im Krieg gegen die Drust kämpften meine Urahnen gegen ähnliche Steinkonstrukte.', 28153),
(137388, 'deDE', '', 'Es tut mir leid. Die Magie des Zirkels versetzt offenbar die Geister der alten Drust in Unruhe. Wir müssen vorsichtig sein.', 28153),
(137387, 'deDE', '', 'Achtung!', 28153),
(137386, 'deDE', '', 'Moment... was war das?', 28153),
(137385, 'deDE', '', 'So ging es unzählige Jahre lang, bis die Urahnen von Haus Kronsteig beschlossen, dass etwas getan werden musste.', 28153),
(137384, 'deDE', '', 'Drustvar war seit Urzeiten ihr Zuhause. Von hier aus griffen sie immer und immer wieder unsere kleinen Siedlungen an.', 28153),
(137383, 'deDE', '', 'Vor langer Zeit, als die ersten Siedler nach Kul Tiras kamen, traf mein Haus auf kriegerische Barbaren. Sie nannten sich die Drust.', 28153),
(137382, 'deDE', '', 'Da ist er! Der Weg ist frei!', 28153),
(137381, 'deDE', '', 'Wir müssen nur den Zugang finden!', 28153),
(137380, 'deDE', '', 'Er birgt ein altes Geheimnis meines Hauses, aus der Zeit, als wir uns in diesem Land niedergelassen haben.', 28153),
(137379, 'deDE', '', 'Ich kann kaum glauben, dass wir hier sind! Mein Vater hat mir früher Geschichten erzählt von diesem Ort.', 28153),
(137378, 'deDE', '', 'Hü! Auf zu Aroms Wehr, Bella!', 28153),
(137377, 'deDE', '', 'Bella, folg dem Champion und trag die Vorräte, die er findet, ja?', 28153),
(137376, 'deDE', '<Helft Langzahn und beendet die Pattsituation.>', '<Helft Langzahn und beendet die Pattsituation.>', 28153),
(137375, 'deDE', '<Der Geist des Jägers Henri Wellenbruch ist zu sehr auf seinen endlosen Kampf konzentriert, um Euch zu bemerken.\n\nEr ist im Kampf gegen den Geist der Wölfin Langzahn gefangen. Keiner der beiden ist bereit nachzugeben, und so sind die beiden sogar im Tode noch in einer nie endenden Pattsituation gefangen.>', '', 28153),
(137374, 'deDE', '<Der Geist der mächtigen Wölfin Langzahn kämpft auch im Tod noch weiter.\n\nSie ist für immer gefangen im Kampf gegen Henri Wellenbruch.>', '', 28153),
(137296, 'deDE', '', 'Mehr Blut für Hir\'eek!', 28153),
(137295, 'deDE', '', 'Zeit \'n paar Köpfe zu sammeln!', 28153),
(137294, 'deDE', '', 'Ihr krepiert hier!', 28153),
(137292, 'deDE', '', 'Hir\'eek wird Euer Blut trinken!', 28153),
(137290, 'deDE', '', 'Ihr werdet \'n Festmahl für meine Fledermaus abgeb\'n!', 28153),
(137289, 'deDE', '', 'Ich werd Euch gleich an Hir\'eek verfüttern!', 28153),
(137287, 'deDE', '', 'Der Blutgott hat mich vor Euch gewarnt!', 28153),
(137284, 'deDE', 'Ihr versucht, eine Festung zu bauen? Hah! Das ist ein köstlicher Witz! Hahaha!', '', 28153),
(137282, 'deDE', 'Fahrt die schweren Geschütze auf! Von ihrer Basis werden nur Trümmer übrigbleiben.', '', 28153),
(137281, 'deDE', 'Sieh mal einer an! Die Horde ist endlich bereit, ihre hässlichen Fratzen zu zeigen!', '', 28153),
(137280, 'deDE', 'Ich werde von Minute zu Minute schwächer. Helft mir, bevor es zu spät ist.', '', 28153),
(137279, 'deDE', 'Ihr seid ein Naturtalent!', '', 28153),
(137278, 'deDE', 'Und natürlich meine Lieblingsdisziplin: Springen! Zeigt, ob Ihr Eurer Reittier über Hindernisse führen könnt. Je mehr Ihr springt, desto höher fällt am Ende Eure Gesamtwertung aus!', '', 28153),
(137277, 'deDE', 'Die Raubeine haben Euch schon ihr Lieblingswerkzeug gezeigt – die Bolas! Trainiert das Werfen beim Reiten, indem Ihr die Zeppeline abschießt. Sie sind eher selten, aber geben viele Punkte!', '', 28153),
(137276, 'deDE', 'Kampfgeschick ist eine wichtige Voraussetzung für Reiter von Kul Tiras. Zeigt mir an den Gnollzielen, wie Ihr mit der Harpune umgeht!', '', 28153),
(137275, 'deDE', 'Oder vielleicht ein Mischwesen? Ein Mannbär... oder... Bärenmann?', '', 28153),
(137274, 'deDE', 'Mehr Bärenwunden. Vielleicht ein Gesetzloser mit seinem Bären?', '', 28153),
(137271, 'deDE', 'Vielleicht doch kein Bär. Vielleicht hat sie sich mit einem Gesetzlosen verzettelt oder so.', '', 28153),
(137270, 'deDE', 'Was für seltsame Wunden. Erinnert fast an einen Bären. Sieht das für Euch nach Bärenwunden aus?', '', 28153),
(137269, 'deDE', 'Alles wird zur... Wüste... sogar Nazmir...!', '', 28153),
(137268, 'deDE', 'Nazmir wurde im Namen des Imperiums der Sethrak eingenommen!', '', 28153),
(137267, 'deDE', 'Ich hab die Bluttrolle überlebt und mehr kriege ich nicht? Bah!', 'Ich hab die Bluttrolle überlebt und mehr kriege ich nicht? Bah!', 28153),
(137266, 'deDE', 'Pah! Torga ist tot. Keine Geschichten für mich.', 'Pah! Torga ist tot. Keine Geschichten für mich.', 28153),
(137265, 'deDE', 'Was...?! Ich hasse es hier... Hier bleibe ich nicht!', 'Was...?! Ich hasse es hier... Hier bleibe ich nicht!', 28153),
(137264, 'deDE', 'Torga ist... tot?! Was ist denn nur geschehen?', 'Torga ist... tot?! Was ist denn nur geschehen?', 28153),
(137263, 'deDE', '', 'Was für \'n Verrat is\' das? Ich werd mir Euern Kopf hol\'n!', 28153),
(137262, 'deDE', '', 'Und schon ist er fort. Ich werde diese Woche wohl besser den Lohn des Wildhüters verdoppeln.', 28153),
(137261, 'deDE', 'Ausgezeichnet! Die Elchjagd ist so viel zivilisierter als Bärenfallen auszulegen!', '', 28153),
(137260, 'deDE', '', 'Westlich von hier gibt es ein kleines Lager, das etwas Hilfe brauchen...', 28153),
(137259, 'deDE', 'Haha! Netter Trick! Weiter so!', '', 28153),
(137258, 'deDE', 'Los!', '', 28153),
(137257, 'deDE', 'Junji muss auch immer aus der Reihe tanz\'n. Es wär ganz schön übel für ihn, wenn die Echs\'n ihn vor Euch find\'n!', '', 28153),
(137256, 'deDE', 'Auf die Plätze... Fertig...', '', 28153),
(137255, 'deDE', 'Das mög\'n nich\' die appetitlichst\'n Zutaten sein, aber sie mach\'n uns satt.', '', 28153),
(137254, 'deDE', 'Fletschzahn is\' tot un\' unsere Alpakas sin\' zurück. Jetzt is\' da nur noch das Problem, dass Mojambo uns alle abmurks\'n will...', '', 28153),
(137253, 'deDE', 'Die Alpakas werd\'n in der Wüste nich\' allein überleb\'n. Wir müss\'n sie zurückbring\'n!', '', 28153),
(137252, 'deDE', 'Unsre Herde Alpakas is\' verschwund\'n. Wir müss\'n sie finden, bevor\'s zu spät is\'!', '', 28153),
(137251, 'deDE', 'Die Wüste is\' \'n trostloser Ort, aber man kann was zu ess\'n find\'n, wenn man nur weiß, wo man such\'n muss!', '', 28153),
(137250, 'deDE', 'Ohne Essen un\' Vorräte werd\'n wir nich\' lange überleb\'n.', '', 28153),
(137249, 'deDE', 'Solang\' die Sethrak das Land verwüst\'n, gibt\'s keinen Fried\'n.', '', 28153),
(137248, 'deDE', 'Wir mach\'n weiter, wenn Ihr bereit seid.', '', 28153),
(137247, 'deDE', '$n hat Neuhof eingenommen!', '$n hat Neuhof eingenommen!', 28153),
(137246, 'deDE', 'Die Allianz hat die Kontrolle über Neuhof übernommen!', 'Die Allianz hat die Kontrolle über Neuhof übernommen!', 28153),
(137245, 'deDE', 'Die Allianz hat die Kontrolle über den Axtkamm übernommen!', 'Die Allianz hat die Kontrolle über den Axtkamm übernommen!', 28153),
(137244, 'deDE', '', 'Bitte... Ich hab... nich\' mehr... viel Zeit.', 28153),
(137243, 'deDE', '<Die Trollfrau hat eine klaffende Schnittwunde in der Seite, umrandet von grünem Schaum.>', '', 28153),
(137242, 'deDE', '', 'Ich mache mir solche Sorgen um meine Nichte.', 28153),
(137241, 'deDE', '', 'Ich bin froh, dass Ihr unversehrt seid, $p! Dolly und Dot geht es auch gut.', 28153),
(137240, 'deDE', '', 'Dolly und Dot haben ganz schön Hunger. Eine Wagenladung Trolle zu ziehen, ist keine leichte Arbeit!', 28153),
(137239, 'deDE', '', 'Dolly und Dot sind stark und zuverlässig. Sie bringen uns sicher ans Ziel.', 28153),
(137235, 'deDE', 'Ich akzeptiere diesen Handel.', 'Ich akzeptiere diesen Handel.', 28153),
(137234, 'deDE', 'Nickel packt den Falken in seine Tasche.', '', 28153),
(137233, 'deDE', 'Ah, $gein:eine:c; $C. Sagt mir, $gkleiner:kleine:r; $R, seid Ihr wegen eines Handels zu mir gekommen?\n\nVor langer Zeit habe ich mich entschieden, es meinen Anhängern zu überlassen, welchem anderen Loa sie noch folgen wollen. Doch für meinen Segen verlange ich, dass Ihr für die Bewohner Zuldazars ein Zeichen meiner Macht seid.\n\nWenn Ihr meinen Segen wünscht, kehrt zu den Stufen von Dazar\'alor zurück und errichtet einen Schrein für mich, der eines Gottes würdig ist.\n\nTut dies und ich werde Euch als Teil meines Rudels betrachten. Akzeptiert Ihr diesen Handel?', '', 28153),
(137226, 'deDE', 'Lasst mich frei.', 'Lasst mich frei.', 28153),
(137223, 'deDE', 'Grüße, Zastamann. Und was bringt Euch zum Schrein der Aasfresser?', '', 28153),
(137212, 'deDE', 'Tag 1: Bis Mittag werden wir die Troggs der Nördlichen Höhlen erreichen. Ich wusste, dass wir etwas vor dem Abendessen finden! Auf ins Abenteuer!', '', 28153),
(137175, 'deDE', '$n hat das Nordhofkreuz eingenommen!', '$n hat das Nordhofkreuz eingenommen!', 28153),
(137174, 'deDE', 'Die Allianz hat die Kontrolle über das Nordhofkreuz übernommen!', 'Die Allianz hat die Kontrolle über das Nordhofkreuz übernommen!', 28153),
(137162, 'deDE', 'Ah, noch \'ne Seele, die G\'huun brech\'n kann!', '', 28153),
(137161, 'deDE', 'Blöder Saurid, seid Ihr wieder tot?', '', 28153),
(137157, 'deDE', 'Hek hek hek hek!', '', 28153),
(137156, 'deDE', '$n hat den Hochstand eingenommen!', '$n hat den Hochstand eingenommen!', 28153),
(137155, 'deDE', 'Die Allianz hat die Kontrolle über den Hochstand übernommen!', 'Die Allianz hat die Kontrolle über den Hochstand übernommen!', 28153),
(137154, 'deDE', 'Das... das fühlt sich befreiend an!', '', 28153),
(137153, 'deDE', 'Warte... Joma! Joma, es klappt!', '', 28153),
(137152, 'deDE', 'Die Allianz hat die Kontrolle über den Zirkel der Elemente übernommen!', 'Die Allianz hat die Kontrolle über den Zirkel der Elemente übernommen!', 28153),
(137151, 'deDE', '$n hat den Zirkel der Elemente eingenommen!', '$n hat den Zirkel der Elemente eingenommen!', 28153),
(137148, 'deDE', 'Vorwärts, Papa!', '', 28153),
(137144, 'deDE', 'NEIN! GEHT NICHT! ZU SCHNELL!', '', 28153),
(137143, 'deDE', 'Na gut, ich denke... das geht...', '', 28153),
(137142, 'deDE', 'Aaaaraaargh!', '', 28153),
(137141, 'deDE', 'Rarrrargh! Zerfetzen! Töten!', '', 28153),
(137140, 'deDE', 'Töten! Töten! Töten!', '', 28153),
(137139, 'deDE', 'Grrr... Zerquetschen!', '', 28153),
(137138, 'deDE', 'Zermalmen!', '', 28153),
(137137, 'deDE', 'Guuuurarrrrgh!', '', 28153),
(137135, 'deDE', 'Ich... töte... Euch...', '', 28153),
(137134, 'deDE', 'Es zerfällt...', '', 28153),
(137133, 'deDE', 'Bin... gebrochen...', '', 28153),
(137132, 'deDE', 'Ihr jetzt auch Mahlzeit!', '', 28153),
(137131, 'deDE', 'Nicht Frischfleisch wegnehmen!', '', 28153),
(137130, 'deDE', 'Erde bricht Euch!', '', 28153),
(137129, 'deDE', 'Ich fresse Euch!', '', 28153),
(137128, 'deDE', 'Na gut, Joma. Bring mich zum Trainingsgelände. Ich denke, dort werde ich am schnellsten... sattelfest, wie man so sagt.', '', 28153),
(137127, 'deDE', 'Gut so, Papa! Halt dich fest!', '', 28153),
(137122, 'deDE', 'Mir... alles mir...', '', 28153),
(137121, 'deDE', 'Ich... Euch... töten...', '', 28153),
(137120, 'deDE', 'Ich... Euch zerbrechen...', '', 28153),
(137119, 'deDE', 'Ich Euch zerbrechen!', '', 28153),
(137118, 'deDE', 'Ich Euch essen!', '', 28153),
(137117, 'deDE', 'Euch töten!', '', 28153),
(137116, 'deDE', 'Das mein Schatz!', '', 28153),
(137113, 'deDE', 'Harrison Jones ist mein Held! Aber Brann Bronzebart ist auch in Ordnung.', '', 28153),
(137110, 'deDE', 'Ihr habt was gefangen!', '', 28153),
(137109, 'deDE', 'Hoppla! Ihr habt da eine wütende Krabbe erwischt!', '', 28153),
(137108, 'deDE', 'Die Schnur ist gerissen!', '', 28153),
(137107, 'deDE', 'Poz\'ga!', '', 28153),
(137106, 'deDE', 'Poz\'ga frisst Euch jetz\'!', '', 28153),
(137105, 'deDE', 'Poz\'ga kommt! Lauft!', '', 28153),
(137104, 'deDE', '', 'Ich werd Euch selbst an Hir\'eek verfütter\'n!', 28153),
(137101, 'deDE', 'Meint Ihr, hier oben ist Titanenzeug? Ich glaube, hier oben ist Titanenzeug. Deswegen die Troggs. Ich werde das Zeug finden, das die Titanen hiergelassen haben.', '', 28153),
(137100, 'deDE', 'Diese Kinder werden lebenslang Hausarrest bekommen!', '', 28153),
(137099, 'deDE', 'Mein Enkel stellt zwar ständig Unfug an, aber das ist die Krönung!', '', 28153),
(137098, 'deDE', 'Ausnehmen', 'Ausnehmen', 28153),
(137097, 'deDE', 'Na... na gut. Ich denke, es wird Zeit. Mein Freund, könnt Ihr mir helfen?', '', 28153),
(137096, 'deDE', 'Los! Verschwinden wir hier!', '', 28153),
(137095, 'deDE', 'Na gut, Papa. Schluss mit den Ausreden! Das Pferd hier musst du jetzt nehmen!', '', 28153),
(137094, 'deDE', 'Das Pferd ist nichts für mich, mein Sohn. Sieh, wie seine Augen blitzen, wenn es mich ansieht. Es will mich verschlingen!', '', 28153),
(137093, 'deDE', 'Das da mag ich. Das find ich am schönsten! Papa?', '', 28153),
(137092, 'deDE', 'Nein, nein, Kind. Das kann ich nicht reiten. Es... ist zu sprunghaft! Sieh, wie es läuft. Meine alten Knochen halten das Gehopse nicht aus!', '', 28153),
(137091, 'deDE', 'Das da sieht süß aus!', '', 28153),
(137090, 'deDE', 'Nein, nein, Joma. Nicht das da. Es ist zu... unruhig. Ja! Unruhig! Es würde vermutlich bei jeder schnellen Bewegung erschrecken.', '', 28153),
(137089, 'deDE', 'Was ist mit dem hier, Papa?', '', 28153),
(137088, 'deDE', 'Na gut, genug gebummelt. Es wird Zeit, das perfekte Pferd zu bestimmen!', '', 28153),
(137087, 'deDE', 'Ich muss mich herrichten, bevor es losgeht. Einen Moment...', '', 28153),
(137086, 'deDE', 'Wir schlitz\'n Euch auf, dann hab\'n wir mehr zu fress\'n!', '', 28153),
(137085, 'deDE', 'Ihr seht wie gutes Futter für die Meister aus!', '', 28153),
(137084, 'deDE', 'Mein Vater erzählt ständig von Pferden! Er möchte gerne eins reiten, aber ich glaube, er hat Angst vor ihnen.$b$bIch weiß schon genau, wie wir ihm helfen können!', '', 28153),
(137083, 'deDE', 'Danach müss\'n die Sethrak gesucht hab\'n!', '', 28153),
(137082, 'deDE', 'Die auf den Runensteinen eingraviert\'n Geschicht\'n war\'n also wahr... die Sphäre gibt\'s tatsächlich!', '', 28153),
(137080, 'deDE', '', 'Euer Gezaubere kann mich nich\' täusch\'n!', 28153),
(137079, 'deDE', '', 'Die Tränke sin\' noch nich\' bereit. Weg mit Euch!', 28153),
(137078, 'deDE', '', 'Sprecht. Warum stört Ihr meine Meditation?', 28153),
(137077, 'deDE', 'Thun\'ka... der Verdorrer...', '', 28153),
(137076, 'deDE', 'Thun\'ka... der Verdorrer...', '', 28153),
(137075, 'deDE', '', 'Danke für die Hilfe, Fremdling. Seht zu, dass Euch kein Salz inne Kniehos\'n kommt.', 28153),
(137074, 'deDE', 'Macht Euch bereit. Diese Party wird gerade um einiges spannender!', '', 28153),
(137073, 'deDE', 'Dieb! Dafür werdet Ihr bezahlen!', 'Dieb! Dafür werdet Ihr bezahlen!', 28153),
(137071, 'deDE', 'Ihr habt unserem Imperium nichts entgegenzusetzen!', 'Ihr habt unserem Imperium nichts entgegenzusetzen!', 28153),
(137068, 'deDE', 'Die Macht in diesen Ruinen gehört uns!', 'Die Macht in diesen Ruinen gehört uns!', 28153),
(137067, 'deDE', 'Ihr könnt nicht die Macht haben! Sie wird uns gehören!', 'Ihr könnt nicht die Macht haben! Sie wird uns gehören!', 28153),
(137066, 'deDE', '', 'Es passiert nicht alle Tage, dass man sich die Gunst eines Wasserelementars verdienen kann.', 28153),
(137065, 'deDE', '', 'Ich bewundere Eure Inbrunst. Geht hin und errichtet mir am Fuße von Dazar\'alor eine Statue, damit die Trolle dieses Landes wissen, wem Ihr huldigt.', 28153),
(137063, 'deDE', '', 'Haha! Das war nicht wörtlich gemeint.', 28153),
(137062, 'deDE', '<Aktiviert den Koloss.>', '<Aktiviert den Koloss.>', 28153),
(137061, 'deDE', 'Dieses uralte Konstrukt beginnt zu leuchten, als Ihr Euch nähert.', 'Dieses uralte Konstrukt beginnt zu leuchten, als Ihr Euch nähert.', 28153),
(137056, 'deDE', 'Versucht nicht, mich ein zweites Mal zu binden, Schamane. Ich werde Euch desintegrieren!', '', 28153),
(137055, 'deDE', 'He da! Ihr seht ja gar nicht nach hochnäsigem Adel aus. Kommt her und trinkt mit uns! Lord Norwinsen hat uns aus den Bergen herbeigerufen, um die Feier in Schwung zu bringen, und das werden wir auch tun!', '', 28153),
(137054, 'deDE', 'Ihr seid hier nich\' willkomm\'n... Das is\' die Trollbrücke!', '', 28153),
(137053, 'deDE', 'Seht Euch diese majestätischen Rösser an. Wir sind quer über den Kontinent gereist, um an diesem Fest teilzunehmen. Ich bin fest entschlossen, mehr über diese herrlichen Tiere zu erfahren.$b$bEdel, mächtig... Sie erfüllen mein altes Herz mit Furcht und Faszination.', '', 28153),
(137052, 'deDE', 'Der Verdorrer wird dieses Tal verschlingen!', '', 28153),
(137051, 'deDE', 'Die Horde hat Ar\'gorok zurückerobert!', 'Die Horde hat Ar\'gorok zurückerobert!', 28153),
(137050, 'deDE', '', 'Es gibt eine neue Macht in meinem Haus. Tretet vor, $p von der Horde, damit ich Euer wahres Ich erkennen kann.$b$b$gEin:Eine:r; $R, $gein:eine:c; $C und ein Champion noch dazu.$b$BMein Hexfürst sagt mir, Ihr wünscht meinen Segen. Doch ich benötige zuerst etwas von Euch, wie von allen, die einen Handel mit mir eingehen.$b$bIch verlange... einen Sprung ins Ungewisse. Beweist mir Euer Vertrauen.', 28153),
(137049, 'deDE', 'Wir müssen diesem Kult ein Ende setzen!', '', 28153),
(137048, 'deDE', 'I-Is\' das Euer Ernst? Ich glaub, wir sollt\'n sein Angebot annehm\'n!', '', 28153),
(137047, 'deDE', 'Pah! Ich hab schon ganz anderes überlebt. Ich weiß, dass Ihr nich\' gewinn\' könnt.', '', 28153),
(137046, 'deDE', 'Eure Leute sin\' verlor\'n! Schließt Euch mir an... un\' Ihr werdet gerettet.', '', 28153),
(137045, 'deDE', 'Einverstanden.', 'Einverstanden.', 28153),
(137041, 'deDE', 'Ah, unsere gefeierte Heldenlegende! Willkommen, willkommen. Bedient Euch bei Speis und Trank. Und lasst es mich nur wissen, wenn Ihr sonst etwas braucht. Ich bin Euch gerne behilflich.', '', 28153),
(137040, 'deDE', 'Hier kümmern wir uns um unsere Pferde. Sowohl Reiter als auch Stallknechte pflegen sie und achten auf ihr Wohlergehen!', '', 28153),
(137039, 'deDE', '', 'Worum möchtet Ihr den Loa des Himmels bitten?', 28153),
(137038, 'deDE', '', 'Ich werde mich zusammen mit Markus verstecken!', 28153),
(137037, 'deDE', '', 'Danke! Mir wären hier bald die Steine ausgegangen!', 28153),
(137036, 'deDE', 'Sterbt, Eindringling!', '', 28153),
(137035, 'deDE', '', 'Zardrax\' Macht wird mich durchdring\'n!', 28153),
(137034, 'deDE', '', 'Zardrax\' Macht wird Euch zerstör\'n!', 28153),
(137033, 'deDE', 'Ich kehr zurück nach Zul\'jan. Mal seh\'n, ob noch jemand so irre is\', wegzulauf\'n un\' sich den Bluttrollen anschließ\'n zu woll\'n.', '', 28153),
(137032, 'deDE', 'Schade, dass Kal\'dran schwach war un\' nich\' seh\'n konnte, dass wir gewinnen werd\'n, hm?', '', 28153),
(137031, 'deDE', 'Viel Glück, $n. Tötet Zardrax, bevor er noch mehr verdirbt un\' auf seine Seite holt.', '', 28153),
(137030, 'deDE', 'Überlasst die Sache einfach $n. $GEr:Sie; wird diese Verhexerin töt\'n, von dem Ihr da redet.', '', 28153),
(137029, 'deDE', 'Ich weiß ja nich\', Da\'jul... $n kann das nich\' aufhalt\'n! Wir werd\'n alle sterb\'n!', '', 28153),
(137028, 'deDE', '', 'Ich gehe Markus suchen. Bis dann!', 28153),
(137027, 'deDE', '', 'Oh, danke Euch! Es war ganz schön unbehaglich hier.', 28153),
(137026, 'deDE', '', 'Das ist alles einfach zu viel für mich. Ich bin weg!', 28153),
(137025, 'deDE', 'Die Allianz hat die Mine angegriffen!', '', 28153),
(137024, 'deDE', '$n hat die Mine angegriffen!', '', 28153),
(137023, 'deDE', 'Ich werde sofort beginnen, den See wiederaufzufüllen.', '', 28153),
(137022, 'deDE', 'Solch mächtige Essenz. Das muss Sumbers Werk sein.', '', 28153),
(137021, 'deDE', 'Ich werde Markus suchen und bei ihm warten. Bis dann!', '', 28153),
(137020, 'deDE', 'He, danke! Wer hätte gedacht, dass die Troggs Magie beherrschen?', '', 28153),
(137019, 'deDE', 'Ich kehre zu Sumber zurück.', '', 28153),
(137018, 'deDE', 'Ich bin wiedergeboren.', '', 28153),
(137017, 'deDE', 'Ich bin mit Geschichten über die wild\'n Bluttrolle aufgewachs\'n, aber das hier is\' schlimmer als in den Geschichten.', '', 28153),
(137016, 'deDE', 'Kal\'dran! $n, Ihr müsst ihn aufhalt\'n... Selbst, wenn das bedeutet, dass Ihr ihn töt\'n müsst.', '', 28153),
(137015, 'deDE', 'Wir sin\' alle VERLOR\'N! Zardrax wird uns rett\'n... un\' Ihr seid tot, wenn Ihr versucht, mich aufzuhalt\'n!', '', 28153),
(137013, 'deDE', 'Kann nicht... halten...', '', 28153),
(137012, 'deDE', 'Willkommen zu Norwinsens Reitfest! Wir bauen noch auf, aber Ihr müsst einfach am Fest teilnehmen. Ein Nein werde ich nicht akzeptieren!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137011, 'deDE', 'Geht! Hier gibt es nichts mehr für Euch!', '', 28153),
(137010, 'deDE', 'Jetzt, $C!', '', 28153),
(137009, 'deDE', 'Glaubt seinen leeren Lügen nicht. Sie sind Euer Untergang!', '', 28153),
(137008, 'deDE', 'Lord Herbsttal ist tot! Seine Machtgier wurde ihm zum Verhängnis!', '', 28153),
(137007, 'deDE', 'Ich hab... das Gesicht von G\'huun geseh\'n... keine Hoffnung... keine Hoffnung...', '', 28153),
(137006, 'deDE', 'Es gibt keine Hoffnung! Warum schließt Ihr Euch nich\' Zardrax an?', '', 28153),
(137005, 'deDE', 'Ich danke Euch abermals, $C. Ihr seid gerade rechtzeitig gekommen!', '', 28153),
(137003, 'deDE', 'Ihr habt dieses Land... dem Untergang geweiht...', '', 28153),
(137002, 'deDE', 'Ihr solltet uns besser nicht stören, sonst werdet Ihr auch noch zu einer lebendigen Opfergabe!', '', 28153),
(137001, 'deDE', 'Diese Leute sind verrückt! Helft mir, $C!', '', 28153),
(137000, 'deDE', 'Der Weidenmann muss besänftigt werden! Sonst wird das Pech uns immer wieder heimsuchen!', '', 28153),
(136999, 'deDE', 'Seid Ihr wohl still!?! Euer Tod dient einem größeren Ziel!', '', 28153),
(136998, 'deDE', 'Das könnt Ihr nicht tun! Das ist Mord! Mord!', '', 28153),
(136997, 'deDE', 'Sieht so aus, als hättet Ihr sie ein wenig dezimiert. Ich glaube, von hier aus komme ich allein zurück.', '', 28153),
(136996, 'deDE', 'Danke, $gFremder:Fremde;! Ich dachte schon, diese Bienen besiegeln mein Schicksal.', '', 28153),
(136995, 'deDE', 'Meine Augen! Sie sind in meinen Augen!', '', 28153),
(136994, 'deDE', 'Nicht die Bienen! Neeiiiinnnn!', '', 28153),
(136993, 'deDE', '$C! Es tut gut, ein freundliches... Halt, was ist das?', '', 28153),
(136992, 'deDE', 'Hoch lebe der Weidenmann!', 'Hoch lebe der Weidenmann!', 28153),
(136991, 'deDE', 'Seht, $n! Das ist mein neues Pferd Magoo. Ist er nicht wundervoll?$b$bNatürlich vermisse ich Heißsporn. Er war prächtig, aber manchmal so aufgeregt! Mit Magoo werde ich mich extra viel beschäftigen, damit ich gleich erkenne, wenn er nervös wird.$b$bIch will ein wirklich guter Reiter werden, also werde ich mit Marina üben, damit Magoo und ich ein tolles Team werden. Die Besten der Besten!', '', 28153),
(136990, 'deDE', 'Initianden, versammelt Euch vor dem Weidenmann. Er wird uns vor den Flüchen schützen, die unser Land befallen.', '', 28153),
(136989, 'deDE', '', 'Ich kann Euch nicht genug danken, dass Ihr Emil gerettet habt! Er ist ein guter Junge und wird auch einen guten Reiter abgeben.$b$bDoch vorerst denke ich, wir werden ihn auf dem Anwesen reiten lassen.', 28153),
(136988, 'deDE', 'Zu... schwach...', '', 28153),
(136987, 'deDE', 'Ihr seid der Boss, Mutta! Ich mach mich los.', '', 28153),
(136986, 'deDE', 'Kejabu schickt mich.', 'Kejabu schickt mich.', 28153),
(136985, 'deDE', 'Aber wenn Ihr Euch mir anschließt, kriegt Ihr mehr Kraft als Ihr je zu träum\'n gewagt habt!', '', 28153),
(136984, 'deDE', 'Wenn Ihr kämpf\'n wollt, werd\'n unsre Truppen Euch zerquetsch\'n.', '', 28153),
(136983, 'deDE', 'Ihr habt keine Wahl. Zuldazar is\' verlor\'n un\' G\'huun wird frei sein!', '', 28153),
(136982, 'deDE', 'Ihr werdet verschont, wenn Ihr mir dient. G\'huun verspricht das.', '', 28153),
(136981, 'deDE', 'G\'huun wird alles verschling\'n! Es gibt keine Hoffnung.', '', 28153),
(136980, 'deDE', 'Haha... Ihr seid stark! Aber es werd\'n sich alle G\'huun beug\'n müss\'n. Mein Angebot gilt noch, wenn Ihr wollt...', '', 28153),
(136979, 'deDE', 'M-Moment... Vielleicht sollt\'n wir mit Zardrax zusammenarbeit\'n. Wie könn\' wir all das aufhalt\'n?', '', 28153),
(136978, 'deDE', '$n wird sich Euch niemals anschließ\'n! Zeigt dem Lich, was Ihr von diesem \"Angebot\" haltet!', '', 28153),
(136977, 'deDE', 'Dient mir un\' rettet Euch... Dann erhaltet Ihr \'nen Teil von G\'huuns Kraft.', '', 28153),
(136976, 'deDE', 'Zuldazar wird an die Bluttrolle un\' G\'huun fall\'n. Aber Ihr müsst dieses Schicksal nich\' teil\'n.', '', 28153),
(136975, 'deDE', 'Nun gut, Lich. Nennt Euer Angebot.', 'Nun gut, Lich. Nennt Euer Angebot.', 28153),
(136974, 'deDE', 'Schließt Euch mir an, dann werdet Ihr die Zerstörung von Zuldazar überleb\'n!', '', 28153),
(136973, 'deDE', 'Das is\' unser Ende! Wie soll\'n wir sowas je aufhalt\'n?', '', 28153),
(136972, 'deDE', 'Wie viele Kraftquellen hab\'n diese Bluttrolle denn noch?', '', 28153),
(136969, 'deDE', '', 'Klasse! Gute Wahl. Und jetzt reitet mit mir und lernt Euern Beschützer kennen.', 28153),
(136968, 'deDE', 'Ha! Ich wusste, dass Ihr die richtige Entscheidung trefft. Kommt her und ich flieg Euch raus, damit Ihr Pa\'ku ma\' persönlich treff\'n könnt.', '', 28153),
(136967, 'deDE', 'Ich möchte einen anderen Loa wählen.', 'Ich möchte einen anderen Loa wählen.', 28153),
(136966, 'deDE', 'Neeein! Elender Hordenwurm! Ich werd Euch das Leben aus dem Leib reiß\'n.', '', 28153),
(136965, 'deDE', 'Nich\' aufhör\'n! Es darf nich\' aufhör\'n!', '', 28153),
(136964, 'deDE', 'Gebt mir mehr! Gebt mir alles!', '', 28153),
(136963, 'deDE', 'Mehr! Gebt mir mehr!', '', 28153),
(136962, 'deDE', 'Ja... Ja... JAAAA!!!', '', 28153),
(136961, 'deDE', '', 'Ihr seid spät dran! Wenn desweg\'n meine Fledermaus stirbt, schmück\' ich meine Hütte mit Eurem Kopf!', 28153),
(136960, 'deDE', 'Ihr entpuppt Euch als unerwartete Hilfe in diesem Kampf.', '', 28153),
(136959, 'deDE', 'D-Das... Das klingt vernünftig.', '', 28153),
(136958, 'deDE', '', 'Nun gut, Emil. Ich glaube, die Reitstunden werden vorerst auf dem Anwesen fortgeführt werden.', 28153),
(136957, 'deDE', '', 'Wir haben keine Zeit für Skrupel, Hochfürst!', 28153),
(136956, 'deDE', 'Es muss einen anderen Weg geben!', '', 28153),
(136954, 'deDE', '', 'Raal, du aufgeblas\'ner Idiot! Wegen dir sin\' wir komplett ungeschützt. Da is\'n Ritual von Blutkultisten direkt auf unsrer Spitze.', 28153),
(136953, 'deDE', 'Die letzte Barriere wird fall\'n... und G\'huun... wird frei sein!', '', 28153),
(136952, 'deDE', 'Nein... Meine Verbindung zu G\'huun... schwindet?', '', 28153),
(136951, 'deDE', 'Ich verbreite G\'huuns Macht! Ihr haltet mich nich\' auf!', '', 28153),
(136950, 'deDE', 'Narr! G\'huuns Macht is\' in mir! Ich werd nich\' fallen!', '', 28153),
(136949, 'deDE', '$gFrecher kleiner:Freche kleine:r; $PR. Tretet näher. Ich will mit Euch sprechen.', '', 28153),
(136948, 'deDE', '', 'Hah... Niemand kann Zardrax aufhalt\'n... Mit seiner Kraft werd\'n wir... Zuldazar vernicht\'n...', 28153),
(136947, 'deDE', '', 'Mit der Kraft von Zardrax un\' G\'huun sin\' wir nicht aufzuhalten!', 28153),
(136945, 'deDE', 'Gut gemacht, $C. Ihr habt mein Vertrauen verdient und ich werde Euch bei Euren Aufgaben helfen.', '', 28153),
(136944, 'deDE', '', 'Auf jeden Fall wirkt er viel präsenter als vorher.', 28153),
(136943, 'deDE', 'Ich glaube, er hat sich bewegt! Nein... halt... war das der Wind?', '', 28153),
(136942, 'deDE', 'Es ist vollbracht. Seht unsere Gaben, Weidenmann, und segnet uns mit Eurer Gnade!', '', 28153),
(136941, 'deDE', 'Ihr habt die Knochen dabei? Perfekt. Dieses Ding mag doch offensichtlich Knochen.', '', 28153),
(136940, 'deDE', 'Ah ja, die Innereien! Damit können wir sicher... irgendetwas anfangen.', '', 28153),
(136939, 'deDE', 'Ihr habt Euch also für die Weiden entschieden. Fast zu naheliegend, aber dennoch korrekt.', '', 28153),
(136938, 'deDE', '', 'Nein, nein, nein! Das sind Küchenkräuter, keine Ritualkräuter! Seht Ihr das nicht?', 28153),
(136937, 'deDE', '', 'Was macht Ihr da mit dem Getreide? Wir basteln hier keine Vogelscheuche!', 28153),
(136936, 'deDE', 'Oh, Ihr habt die Schriftrollen dabei... Es könnte wohl sein, dass man mit ihnen den Weidenmann erwecken kann... Leider kann sie niemand hier lesen.', '', 28153),
(136935, 'deDE', 'Früchte?! Ist das Euer Ernst? $gEr:Sie; meint das wirklich ernst!', '', 28153),
(136934, 'deDE', 'Wir haben es geschafft. Sylvanas wird endlich für ihre Verbrechen büßen. Champions, kommt mit mir...', '', 28153),
(136929, 'deDE', '<Heiro schlägt das Tamburin lässig auf seine Hüfte und zwinkert Euch zu.>', '', 28153),
(136927, 'deDE', 'Ich bezweifle, dass wir uns wiedersehen, $n. Habt Dank.', '', 28153),
(136925, 'deDE', '', 'Vol\'dun hat uns schon viel Schlimmeres abverlangt. Wir werden es überleben.', 28153),
(136919, 'deDE', 'Ich glaube, wenn Ihr den Weg freikämpfen würdet, würde ich es bis zu Marina schaffen. Danke vielmals, dass Ihr mich gerettet habt!', '', 28153),
(136918, 'deDE', 'Ist... Ist es sicher, herauszukommen? Troggs sind wirklich gruselig!', '', 28153),
(136917, 'deDE', '$n hat den Axtkamm eingenommen!', '$n hat den Axtkamm eingenommen!', 28153),
(136916, 'deDE', 'Ich setz\' Euch ma\' bei Loti ab. Sagt ihr, die Quelle der ganzen Probleme is\' vielleicht direkt in Zanchul.', '', 28153),
(136915, 'deDE', 'Hm, irgendwas fühlt sich... komisch an. Ich spür \'ne große Macht im Innern von Zanchul.', '', 28153),
(136914, 'deDE', 'Es vergeht keine Woche, ohne dass sich nich\' irgendwelche Zandalari der Blutmagie zuwend\'n, die sie von den Frevlern in Nazmir gelernt ham.', '', 28153),
(136913, 'deDE', 'Unsre Verteidigung wird schwächer. Prinzessin Talanji fragt schon länger nach mehr Trupp\'n, aber ihr Vater reagiert nur langsam, also wendet sie sich an die Horde.', '', 28153),
(136912, 'deDE', 'Da hammer das erste Ma\' richtige Blutmagie zu spür\'n bekomm\'. Nich\' den Kinderkram der schwächeren Stämme.', '', 28153),
(136911, 'deDE', 'Vor so\'n paar Jahren wurde dieses ganze Land vom Kataklymus erschüttert. Unsere nördlichen Tore stürzt\'n ein und Horden von wilden Bluttrollen stürmten da durch.', '', 28153),
(136910, 'deDE', 'Ich zeig Euch die besten Eck\'n und Ihr habt dann die Ehre, ma\' so\'n Totem des Scharfsehers runterzuschmeißen.', '', 28153),
(136909, 'deDE', 'Ein kleiner Beutel Pferdeleckerli ist auf dem Boden verteilt. Bei näherer Betrachtung erkennt Ihr Emils Namen, der in den Stoff eingenäht ist.$b$bEr muss hier vorbeigekommen sein, wenn auch nicht freiwillig. Ihr bemerkt ein paar Leckerli, die den Hügel hinauf führen.', 'Ein kleiner Beutel Pferdeleckerli ist auf dem Boden verteilt. Bei näherer Betrachtung erkennt Ihr Emils Namen, der in den Stoff eingenäht ist.$b$bEr muss hier vorbeigekommen sein, wenn auch nicht freiwillig. Ihr bemerkt ein paar Leckerli, die den Hügel hinauf führen.', 28153),
(136908, 'deDE', 'Ich weiß nich\', wie viel länger wir uns geg\'n die Sethrak noch behaupt\'n könn\'...', '', 28153),
(136907, 'deDE', 'Ihr seid offenbar nich\' aus Zuldazar, sonst würdet Ihr genau wiss\'n, wer ich bin. Ich war General Jakra\'zets persönlicher Koch!$b$bIch wurde verbannt, nachdem der General von einem meiner Gerichte krank geword\'n war... aber das war nich\' meine Schuld!$b$bDie andren Köche war\'n neidisch auf meine Stellung. Einer von denen muss das Essen vergiftet hab\'n, als ich grad nich\' hingeseh\'n hab!$b$bEines Tages werd ich meine Unschuld beweis\'n, aber bis dahin muss ich wohl Mistkäfer koch\'n, um zu überleb\'n.', '', 28153),
(136906, 'deDE', 'ALLIANZ, HALTET STAND!', '', 28153),
(136905, 'deDE', 'Wie hat es Euch nach Vol\'dun verschlagen?', 'Wie hat es Euch nach Vol\'dun verschlagen?', 28153),
(136904, 'deDE', 'Ihr stellt gefährliche Fragen, $C.\n\nIch leugne meine Vergangenheit nich\', doch andere hier könnten\'s damit anders halten...\n\nIch wurd mit meiner Familie verbannt, als ich noch \'n kleiner Junge war. Mein Vater hatte hohe Schulden, damals musst\'n Kinder mit ihren Eltern ins Exil.\n\nIch war allein un\' fast verdurstet, als Razgaji mich gefund\'n hat. Er hat mich wieder gesund gepflegt und mich wie \'n eigenes Kind großgezog\'n. Seither bin an seiner Seite geblieb\'n...', '', 28153),
(136903, 'deDE', 'Was führt Euch nach Vol\'dun?', 'Was führt Euch nach Vol\'dun?', 28153),
(136902, 'deDE', '', 'Ihr da, ich kenn\' Euer Gesicht nich\'. Kommt, sprecht mit mir.', 28153),
(136901, 'deDE', '', 'Hir\'eek is besänftigt... aber wir brauch\'n mehr Blut! Bringt noch \'n Opfer!', 28153),
(136900, 'deDE', '', 'Großer Hir\'eek, Loa der Fledermäuse, Diener von G\'huun. Akzeptiert unser Opfer!', 28153),
(136899, 'deDE', '', 'Hexfürst Raal könnt Ihr am andern Ende vonner Terrasse find\'n. Richtet ihm von mir was Beleidigendes aus.', 28153),
(136895, 'deDE', 'Eure Zeit ist abgelaufen, König Anduin!', '', 28153),
(136894, 'deDE', 'Wenn wir jetzt flüchten, werden wir zur Beute. Nein. Wir kämpfen – und sterben, wenn es sein muss – für unsere Überzeugungen!', '', 28153),
(136889, 'deDE', '', 'Sprecht! Oder ich werde Eure Zunge für das nächste Ritual rausreiß\'n lass\'n.', 28153),
(136888, 'deDE', '', 'Hir\'eek gibt uns seine Kinder und der Blutgott verleiht uns Macht! Zusamm\'n sind wir unschlagbar!', 28153),
(136887, 'deDE', '', 'Was wollt Ihr? Sprecht schnell oder Ihr werdet die nächste Opfergabe sein!', 28153),
(136882, 'deDE', 'Seil nehmen', 'Seil nehmen', 28153),
(136878, 'deDE', '', 'Krieg erfordert nun mal direktere Methoden.', 28153),
(136876, 'deDE', '', 'Achtung! Schlangen!', 28153),
(136874, 'deDE', 'Habt Ihr mit Gonk gesproch\'n? Er is\' der Herr des Rudels. Er hat zu \'n paar von den Dunkelspeeren gesprochen un\' ihnen erklärt, wie sie Druiden werd\'n.$b$bAber für uns is\' er mehr als \'ne Stimme. Für uns is\' er real. Nich\' nur \'n Fragment oder Stück von ihm.', 'Habt Ihr mit Gonk gesproch\'n? Er is\' der Herr des Rudels. Er hat zu \'n paar von den Dunkelspeeren gesprochen un\' ihnen erklärt, wie sie Druiden werd\'n.$b$bAber für uns is\' er mehr als \'ne Stimme. Für uns is\' er real. Nich\' nur \'n Fragment oder Stück von ihm.', 28153),
(136872, 'deDE', 'Gonk is\' der Loa, der allen Trollen beigebracht hat, wie sie ihren Einfluss auf andere Loa ausdehn\' un\' Druiden werd\'n. Un\' wir sin\' auf ewig dankbar.', 'Gonk is\' der Loa, der allen Trollen beigebracht hat, wie sie ihren Einfluss auf andere Loa ausdehn\' un\' Druiden werd\'n. Un\' wir sin\' auf ewig dankbar.', 28153),
(136871, 'deDE', 'Die Ergebenen von Pa\'ku sin\' noch immer verbittert drüber, wie Kriegsdruidin Loti ihren Hexfürst Raal verlass\'n hat. Sehr traurig. Sehr unprofessionell.', 'Die Ergebenen von Pa\'ku sin\' noch immer verbittert drüber, wie Kriegsdruidin Loti ihren Hexfürst Raal verlass\'n hat. Sehr traurig. Sehr unprofessionell.', 28153),
(136870, 'deDE', 'Die Anhänger von Gonk sin\' noch immer verbittert drüber, wie Hexfürst Raal unsre Kriegsdruidin Loti verlass\'n hat. Sehr traurig. Sehr unprofessionell.', 'Die Anhänger von Gonk sin\' noch immer verbittert drüber, wie Hexfürst Raal unsre Kriegsdruidin Loti verlass\'n hat. Sehr traurig. Sehr unprofessionell.', 28153),
(136869, 'deDE', 'Egal was Ihr tut, hört nich\' auf diese Lügen von den Anhängern von Gonk. Sie sin\' nur neidisch drauf, wie großartig unser Loa Pa\'ku is\'.', 'Egal was Ihr tut, hört nich\' auf diese Lügen von den Anhängern von Gonk. Sie sin\' nur neidisch drauf, wie großartig unser Loa Pa\'ku is\'.', 28153),
(136868, 'deDE', 'Ich diene Pa\'ku, dem Loa der Winde und Meisterin unserer Flotte. Sie is\' \'n Loa wie kein andrer. Ihr solltet \'nen Handel mit ihr eingeh\'n, nicht mit den andren. Die sin\' nicht vertrauenswürdig.', 'Ich diene Pa\'ku, dem Loa der Winde und Meisterin unserer Flotte. Sie is\' \'n Loa wie kein andrer. Ihr solltet \'nen Handel mit ihr eingeh\'n, nicht mit den andren. Die sin\' nicht vertrauenswürdig.', 28153),
(136867, 'deDE', 'Hmm, $p. Die Loa flüstern Euern Namen. Eure Ankunft in Zuldazar wird interessant werd\'n.', 'Hmm, $p. Die Loa flüstern Euern Namen. Eure Ankunft in Zuldazar wird interessant werd\'n.', 28153),
(136866, 'deDE', 'Pa\'ku is\' der Loa der Winde und Meister der Späher und der Flotte. Sie is\' von der impulsiven Sorte und liebt ihre Freiheit. Sprecht mit ihrem Champion, Hexfürst Raal, wenn Ihr mehr wiss\'n wollt.', 'Pa\'ku is\' der Loa der Winde und Meister der Späher und der Flotte. Sie is\' von der impulsiven Sorte und liebt ihre Freiheit. Sprecht mit ihrem Champion, Hexfürst Raal, wenn Ihr mehr wiss\'n wollt.', 28153),
(136865, 'deDE', 'Ah! Der Champion der Horde. Hexfürst Raal wird beeindruckt von Euch sein. Is\' er Euch wohlgesonnen, gilt dasselbe für Pa\'ku un\' mich.', 'Ah! Der Champion der Horde. Hexfürst Raal wird beeindruckt von Euch sein. Is\' er Euch wohlgesonnen, gilt dasselbe für Pa\'ku un\' mich.', 28153),
(136864, 'deDE', 'Ihr seid hier nich\' willkommen.', 'Ihr seid hier nich\' willkommen.', 28153),
(136863, 'deDE', 'Ich hab Euch nichts zu sag\'n.', 'Ich hab Euch nichts zu sag\'n.', 28153),
(136862, 'deDE', 'Habt Ihr Euch verlauf\'n? Solltet eigentlich wissen, dass Ihr hier nix zu such\'n habt.', 'Habt Ihr Euch verlauf\'n? Solltet eigentlich wissen, dass Ihr hier nix zu such\'n habt.', 28153),
(136861, 'deDE', 'Kastenloser Abschaum. Bah!', 'Kastenloser Abschaum. Bah!', 28153),
(136860, 'deDE', 'Sprecht mich nich\' an, Jämmerling.', 'Sprecht mich nich\' an, Jämmerling.', 28153),
(136859, 'deDE', '', 'Wie erwartet ist meine Arbeit perfekt. Etwas muss den Brunnen verstopfen. Würdet Ihr einen Blick darauf werfen?', 28153),
(136858, 'deDE', '', 'Sehen wir uns den Brunnen von Nahem an.', 28153),
(136857, 'deDE', 'Ich werd mein nächstes Ritual mit Euerm Blut zeichn\'n.', 'Ich werd mein nächstes Ritual mit Euerm Blut zeichn\'n.', 28153),
(136856, 'deDE', 'Elender Hordendreck!', 'Elender Hordendreck!', 28153),
(136855, 'deDE', 'Ihr könnt uns nich\' alle aufhalt\'n!', 'Ihr könnt uns nich\' alle aufhalt\'n!', 28153),
(136854, 'deDE', 'Ihr glaubt, ich allein wirk hier Blutmagie? Auf Euch wartet \'ne böse Überraschung.', 'Ihr glaubt, ich allein wirk hier Blutmagie? Auf Euch wartet \'ne böse Überraschung.', 28153),
(136853, 'deDE', 'Bah! Von einfach\'m Hordenabschaum lass ich mich nich\' besieg\'n!', 'Bah! Von einfach\'m Hordenabschaum lass ich mich nich\' besieg\'n!', 28153),
(136852, 'deDE', 'Ich dachte, Ihr geflügelten Trottel solltet nach diesen Bluttrollen Ausschau halt\'n. Warum mach\'n also wir die Arbeit für Euch?', 'Ich dachte, Ihr geflügelten Trottel solltet nach diesen Bluttrollen Ausschau halt\'n. Warum mach\'n also wir die Arbeit für Euch?', 28153),
(136851, 'deDE', 'Ihr werdet nich\' unsern Ritualtag stör\'n. Dafür wird Loti schon sorg\'n.', 'Ihr werdet nich\' unsern Ritualtag stör\'n. Dafür wird Loti schon sorg\'n.', 28153),
(136850, 'deDE', 'Ihr flieg\'nden Fanatiker werdet der Untergang von Zandalar sein.', 'Ihr flieg\'nden Fanatiker werdet der Untergang von Zandalar sein.', 28153),
(136849, 'deDE', 'Wenn Raal weiter so Ärger macht, werd\'n wir Euch alle an den Loa des Königs verfüttern.', 'Wenn Raal weiter so Ärger macht, werd\'n wir Euch alle an den Loa des Königs verfüttern.', 28153),
(136848, 'deDE', '', 'Diese Armee ist riesig... Gebt nur den Befehl, dann bringe ich uns in Sicherheit.', 28153),
(136846, 'deDE', 'Ihr folgt immer noch Loti? Ha! Ihr seid dümmer als Brutosaurierdung.', 'Ihr folgt immer noch Loti? Ha! Ihr seid dümmer als Brutosaurierdung.', 28153),
(136845, 'deDE', 'Jetzt seid Ihr in der Unterzahl.', '', 28153),
(136844, 'deDE', 'Raal übernimmt den Lad\'n hier irgendwann und verfrachtet Euch Raptorfanatiker in die Wildnis, wo Ihr hingehört.', 'Raal übernimmt den Lad\'n hier irgendwann und verfrachtet Euch Raptorfanatiker in die Wildnis, wo Ihr hingehört.', 28153),
(136843, 'deDE', 'Der Name von Euerm Loa is\' Gonk. Dafür solltet Ihr Euch schäm\'n.', 'Der Name von Euerm Loa is\' Gonk. Dafür solltet Ihr Euch schäm\'n.', 28153),
(136842, 'deDE', 'Ihr dreckigen Druiden pfeift ausm letzt\'n Loch. Keiner is\' besser als die Gurubashi.', 'Ihr dreckigen Druiden pfeift ausm letzt\'n Loch. Keiner is\' besser als die Gurubashi.', 28153),
(136841, 'deDE', 'Ihr seid nich\' besser als ich. Mein Blut... klebt an Euern Händen.', '', 28153),
(136840, 'deDE', 'Jeder kämpft für sich allein. Töten oder getötet werden!', '', 28153),
(136838, 'deDE', '<Ihr findet den noch immer warmen Kadaver von Emils Pony Heißsporn.>$b$b<Krümel führen den Hügel hinauf. Anscheinend hat Emil eine Spur hinterlassen.>', 'Ihr findet den noch immer warmen Kadaver von Emils Pony Heißsporn.$b$bIhr hofft, dass es nicht auch für Emil zu spät ist.', 28153),
(136837, 'deDE', 'Junge wird leckerer Snack!', '', 28153),
(136836, 'deDE', 'Ich bin hier drüben! Er hat den Schlüssel! Bitte helft mir!', '', 28153),
(136835, 'deDE', '', 'Brechen wir auf, $n. Lord Norwinsen wird meinen Kopf fordern, wenn seinem Sohn etwas zustößt!', 28153),
(136832, 'deDE', 'Wir sind ein Stamm von Ausgestoßenen. Wir wurd\'n aus Zuldazar verbannt und zum Sterb\'n in die Wüste geschickt.\n\nEinige von uns wurd\'n zu Unrecht der Verbrechen beschuldigt, wegen der sie nun hier sin\'. Aber der Rest von uns hat sein Schicksal verdient.\n\nFür uns zählt jetz\' nur noch das eigne Überleb\'n.\n\nWer den Gesetzen des Stammes folgt, hat \'nen Platz bei uns. Aber wer unsre Gesetze missachtet, der wird Gerechtigkeit noch rascher vollstreckt seh\'n als bei König Rastakhan.', '', 28153),
(136831, 'deDE', 'Was braucht Ihr, Mutta?', '', 28153),
(136830, 'deDE', 'Was is\' denn? Ihr... Ihr seid doch nich\' etwa das nächste Opfer?', '', 28153),
(136829, 'deDE', 'Die Priesterinnen... Die werd\'n uns alle abmurks\'n!', '', 28153),
(136828, 'deDE', 'Ohne Eure Tarnung wird die Sache \'ne ganze Ecke gewalttätiger.', '', 28153),
(136827, 'deDE', 'Erzählt mir von Eurem Stamm.', 'Erzählt mir von Eurem Stamm.', 28153),
(136825, 'deDE', '', 'Das is\' Rakeras Schild... Wo is\' sie? Was habt Ihr mit ihr gemacht?', 28153),
(136824, 'deDE', 'Das is\' Jakra\'zets Schuld, nich\' meine. Rakera is\' der Grund, warum ich noch lebe.', '', 28153),
(136823, 'deDE', '', 'Meerah, stoppt die Karawane! Da vorne is\' was.', 28153),
(136822, 'deDE', '', 'Wie kann Rakera an so \'nem Ort überlebt ham?', 28153),
(136820, 'deDE', '', 'Könnt Ihr glauben, dass diese Ödnis einmal das Juwel des Trollimperiums war? Ein Dschungel voller Leben... Was davon noch übrig ist, liegt jetzt unter dem Sand begraben.', 28153),
(136819, 'deDE', '', 'Kiro muss sich keine Sorgen machen, ich hab das total drauf! Aber haltet Euch besser fest, nur zur Sicherheit.', 28153),
(136818, 'deDE', '', 'Bin ich doch immer!', 28153),
(136816, 'deDE', 'Aber dafür brauch ich Hilfe un\' $gdieser:diese:c; $C hat jede Menge Mojo. Das kann ich riech\'n.', '', 28153),
(136815, 'deDE', 'Ihr seid auch nich\' besser als die andren Irren, die nach Naz... Was?', 'Ihr seid auch nich\' besser als die andren Irren, die nach Naz... Was?', 28153),
(136814, 'deDE', 'Bah! Passt auf, ich geh da runter un\' zeig Euch, dass der Kerl verrückt is\'.', 'Bah! Passt auf, ich geh da runter un\' zeig Euch, dass der Kerl verrückt is\'.', 28153),
(136813, 'deDE', 'Ich werd alle im Lager wiss\'n lass\'n, dass Ihr mich gerettet habt!', '', 28153),
(136812, 'deDE', 'Ich bin frei! Ich kann\'s kaum fass\'n!', '', 28153),
(136811, 'deDE', 'Wenn ich meine Stärke zurückbekomm, könnt ich ihn besieg\'n...', '', 28153),
(136810, 'deDE', 'Un\' das is\' Urok, eine untote Monstrosität, die Euch alle töt\'n wird.', '', 28153),
(136809, 'deDE', 'Idiot! Ihr werdet nur Futter für Urok sein!', '', 28153),
(136808, 'deDE', 'Pssst. Urok is\' nah. Ich kann seine ZÄHNE RIECH\'N.', '', 28153),
(136807, 'deDE', 'Zeigt mir Urok, den Schrecken des Sumpflands.', 'Zeigt mir Urok, den Schrecken des Sumpflands.', 28153),
(136806, 'deDE', '', 'Emil!!!', 28153),
(136805, 'deDE', 'Betet mit uns Pa\'ku an, sie is\' Euer Loa, Mann!', 'Betet mit uns Pa\'ku an, sie is\' Euer Loa, Mann!', 28153),
(136804, 'deDE', 'Am Himmel isses schön, das werdet ihr seh\'n. Schließt Euch unserm Pa\'ku an, sie is\' Euer Loa, Mann!', 'Am Himmel isses schön, das werdet ihr seh\'n. Schließt Euch unserm Pa\'ku an, sie is\' Euer Loa, Mann!', 28153),
(136803, 'deDE', 'Nich\' zögern, Leute – folgt Pa\'ku noch heute!', 'Nich\' zögern, Leute – folgt Pa\'ku noch heute!', 28153),
(136800, 'deDE', 'Alles okay, alles okay! Kein Grund zu... AH!', '', 28153),
(136799, 'deDE', '', 'Passt auf, Emil, beruhigt Heißsporn.', 28153),
(136798, 'deDE', '', 'Erbärmlicher Zwerg! Hir\'eek wird Euch nich\' mal als Opfer akzeptier\'n!', 28153),
(136797, 'deDE', '', 'Kommt jetzt mit. Eure Zeit is\' gekommen.', 28153),
(136789, 'deDE', 'Macht\'s gut, $n. Wir seh\'n uns bald.', '', 28153),
(136788, 'deDE', 'Ich muss dann ma\' zurück nach Zo\'bal. Muss noch jede Menge Seelen sammeln, bevor ich meine Schuld abbezahl\'n kann.', '', 28153),
(136780, 'deDE', 'Der gebundene Nachtjäger stößt ein gurgelndes Winseln aus.', '', 28153),
(136779, 'deDE', 'Der gebundene Nachtjäger hört etwas in der Nähe!', '', 28153),
(136778, 'deDE', 'Der gebundene Nachtjäger schnuppert in der Luft.', '', 28153),
(136769, 'deDE', '', 'Meeki hat ein besseres Schicksal verdient, aber das ist nicht Eure Schuld.\n\nDanke, dass Ihr ihn für uns gefunden habt. Es ist besser, mit Schmerz als mit Bedauern zu leben.\n\nWir reisen durch diese Dünen als Familie und Ihr seid jetzt ein Teil davon. Ihr seid in unserer Karawane immer willkommen.', 28153),
(136768, 'deDE', 'Ihr müsst \'n klaren Kopf behalt\'n. Eure Feinde spür\'n die Schwäche in Euern Gedanken.', '', 28153),
(136767, 'deDE', 'Hört auf damit!', '', 28153),
(136766, 'deDE', 'I-I-Ich kann es kaum erwarten, Ahnas Ode über Eure Abenteurer zu hören.\n\nA-A-Ahna macht sehr gute Musik. Ihr m-m-müsst ihr unbedingt Eure Geschichte erzählen!\n\nW-W-Wir werden dafür sorgen, dass allen, die unseren Weg kreuzen, die Legende von $p zu Ohren kommt.', '', 28153),
(136764, 'deDE', '', 'Tragödie, untote Piraten, verfluchte Schätze, Meuterei... Dieses Abenteuer birgt den Stoff für Legenden.\n\nIch habe bereits ein paar gute Ideen für die erste Strophe meiner Ode, der Ballade der Tapferkeit von $p.\n\nIhr werdet von dieser Karawane noch nach Generationen als Legende gefeiert werden.\n\nGleich nach diesem Nickerchen.', 28153),
(136763, 'deDE', 'Kämpft mit Hingabe! Alles steht aufm Spiel!', '', 28153),
(136762, 'deDE', 'Wir kämpf\'n nich\' nur, um die Leute zu beschütz\'n, sondern auch für die Zukunft der Zandalari. Nehmt das nich\' auf die leichte Schulter.', '', 28153),
(136761, 'deDE', 'Greift schnell an, aber vergesst niemals die Soldat\'n um Euch herum.', '', 28153),
(136760, 'deDE', 'Ihr müsst das Ziel mit Wucht treff\'n... aber dabei Eure Haltung nich\' verlier\'n.', '', 28153),
(136759, 'deDE', 'Ich bin schon viel im Ring geritten. Dort draußen kann es nicht so anders sein!', '', 28153),
(136758, 'deDE', '', 'Haltet die Zügel gut fest, Emil.', 28153),
(136757, 'deDE', '', 'Lord Norwinsen hat mir die Reitausbildung seines Sohnes anvertraut. Im Ring kommt er ja gut zurecht, doch der Gedanke, ihn ins Freie mitzunehmen, bereitet mir Sorgen. Ich bin mir nicht sicher, ob er sein Pony nach einem Schreck zum Halt bewegen könnte.$b$bAber hoffentlich wird es nie dazu kommen!', 28153),
(136756, 'deDE', 'Heißsporn würde nie erschrecken. Er ist ganz tapfer!', '', 28153),
(136755, 'deDE', 'Ich glaube, er hört zu. Seht Euch seine Ohren an!', '', 28153),
(136754, 'deDE', 'Tu ich doch, tu ich doch!', '', 28153),
(136753, 'deDE', '', 'Schön langsam und ruhig. Dort draußen könnte er sich vor vielem erschrecken.', 28153),
(136752, 'deDE', '', 'Sorgt dafür, dass er sich auf Euch konzentriert, hier ist eine Menge los!', 28153),
(136751, 'deDE', '', 'Emil, dreht ihn mit Eurem Bein, nicht mit Eurer Hand.', 28153),
(136750, 'deDE', 'Hm... Eine Wüste im Sumpf... Was haben die Sethrak vor?', '', 28153),
(136747, 'deDE', 'Danke, dass Ihr mich vor den widerwärtigen Saurolisken gerettet habt. Allein gehe ich nicht mehr zum Flussbett... zumindest nicht, bis ich etwas älter bin!', '', 28153),
(136746, 'deDE', 'Hallo? Is\' da draußen wer?', '', 28153),
(136745, 'deDE', 'Die Allianz ist uns nicht gewachsen. Für die Horde!', '', 28153),
(136744, 'deDE', 'Der Hafen von Zem\'lan is\' mein!', '', 28153),
(136741, 'deDE', 'Sur\'jan, sei nich\' irre! Nach der Sache hier bleib\'n wir schön in Nazmir. Ich geh nie mehr zurück nach Zuldazar.', '', 28153),
(136740, 'deDE', 'Mit Eurer Hilfe werd ich stark genug sein. Dann können wir Urok noch einmal besieg\'n. Ich wart hier, um das nächste Ritual vorzubereit\'n.', '', 28153),
(136738, 'deDE', 'Diese Monster wollten mich fressen!', '', 28153),
(136732, 'deDE', 'Was denn, Sur\'jan?... Hmpf, gut, hast ja recht.', '', 28153),
(136731, 'deDE', 'Sur\'jan, eigentlich sollte ich das erledig\'n. Ich sitz nich\' gern rum und seh andern beim Arbeiten zu.', '', 28153),
(136730, 'deDE', 'Ich geh voraus. Macht Ihr ma\' alles bereit für unsren Kampf gegen Urok.', '', 28153),
(136729, 'deDE', 'Papa meint, dieses Jahr kann ich bei der Feier mitmachen. Sie bringen mir endlich das Reiten bei!', '', 28153),
(136728, 'deDE', 'Ich kümmer mich um das Gleichgewicht der Natur.\n\nRuhig, Sur\'jan, natürlich is\' mir das Gleichgewicht der Natur wichtig... irgendwie. $gEr:Sie; muss ja nichts davon wiss\'n.', '', 28153),
(136727, 'deDE', 'Der Sumpf is voll von Schrecken. Wenn Ihr da überleb\'n wollt, müsst Ihr selbst einer werd\'n.', '', 28153),
(136726, 'deDE', 'Der Fluch... is\' vorbei? Bin ich endlich frei?', '', 28153),
(136725, 'deDE', 'Ihr seid hier auf verfluchtem Boden... hier kommt niemand raus!', '', 28153),
(136724, 'deDE', '', 'Monster lauern in den Schatten von Zem\'lan.\n\nPasst auf, dass Ihr nicht selber eines werdet.', 28153),
(136723, 'deDE', 'Eine F-F-Familie hält zusammen, was auch immer geschieht.', '', 28153),
(136722, 'deDE', 'Un\' ich mach keine Scherze. Ich will, dass dieser Troll getötet wird. Genau wie Urok hier. Viel Glück bei der Jagd.', '', 28153),
(136721, 'deDE', 'Sei nich\' albern, Sur\'jan. $gEr:Sie; wird nich\' denken, dass ich Scherze mach... Also gut... Ich werd mich klarer ausdrück\'n.', '', 28153),
(136720, 'deDE', 'War schön, mit Euch zu arbeit\'n. Wenn Ihr \'nen Troll namens \"Krugah\" findet, bringt ihn einfach um. Hah!', '', 28153),
(136719, 'deDE', 'Wir dürf\'n keine Zeit mehr verlier\'n. Urok muss sterb\'n!', '', 28153),
(136718, 'deDE', 'Jawoll! Es is\' so weit... wir werd\'n Urok zur Strecke bring\'n!', '', 28153),
(136717, 'deDE', 'Ich kann es fühl\'n... Meine Kraft kehrt zurück!', '', 28153),
(136713, 'deDE', 'Ha HA! Es is\' fast so weit... un\' wir sin\' fast bereit, Urok zu töt\'n!', '', 28153),
(136712, 'deDE', 'Gut... Ich fühl schon, wie die Kraft zu mir zurückkehrt!', '', 28153),
(136711, 'deDE', 'Ah... MEHR! Wir brauch\'n mehr Kraft, wenn wir Urok töt\'n woll\'n!', '', 28153),
(136710, 'deDE', 'Das is\' alles, was ich brauch... Jetzt is\' es Zeit für mehr Kraft!', '', 28153),
(136698, 'deDE', 'Wir sind es, die Glück haben. Nicht Ihr. Noch nicht.', '', 28153),
(136697, 'deDE', 'Sie sucht das, was durch ein Opfer verdient werden muss.', '', 28153),
(136696, 'deDE', '', 'Jenseits dieses kleinen Sternenmeeres gibt es nur endlose Dunkelheit.', 28153),
(136695, 'deDE', '', 'Sagt meinem Papa, dass ich ihm vergebe.', 28153),
(136694, 'deDE', '', 'Hat sie Euch schon verraten? Denn das wird sie...', 28153),
(136693, 'deDE', '', 'Ihr werdet allein sterben.', 28153),
(136692, 'deDE', '', 'Der Meister wartet darauf, dass Ihr Euch ihm anschließt...', 28153),
(136691, 'deDE', '', 'Er ist jetzt wach. Und er hat Euch bemerkt.', 28153),
(136690, 'deDE', '', 'Ihr werdet Euch uns bald anschließen.', 28153),
(136689, 'deDE', '', 'Ich weiß, was Ihr getan habt.', 28153),
(136688, 'deDE', '', 'Ihr hört leises Gelächter.', 28153),
(136687, 'deDE', '', 'Ihr spürt, wie Ihr beobachtet werdet.', 28153),
(136686, 'deDE', '', 'Ihr werdet beobachtet.', 28153),
(136685, 'deDE', '', 'Der verfolgende Geist lacht und läuft davon.', 28153),
(136684, 'deDE', 'Unser nächstes Treff\'n wird unser letztes sein...', '', 28153),
(136683, 'deDE', 'Eure Seele gehört mir, Eindringling!', '', 28153),
(136681, 'deDE', 'Eure Anwesenheit is\' \'ne Entweihung! Fürchtet den Zorn Xibalas!', 'Eure Anwesenheit is\' \'ne Entweihung! Fürchtet den Zorn Xibalas!', 28153),
(136680, 'deDE', '', 'Wenn Ihr feinstes Mojo un\' Schätze aus\'m Süden wollt, solltet Ihr mit Wunja sprech\'n!', 28153),
(136679, 'deDE', 'Törichtes sterbliches Wesen! Xibala wird Euch zerstör\'n!', 'Törichtes sterbliches Wesen! Xibala wird Euch zerstör\'n!', 28153),
(136678, 'deDE', 'Wir fliegen mit Schwingenfürst Ata rum. Sitzt ma\' auf und haltet die Aug\'n off\'n.', '', 28153),
(136677, 'deDE', 'Mit den weisen Wort\'n meines Loas: Wenn Ihr die Ursache von dem Problem nich\' seh\'n könnt, müsst Ihr höher rauf.', '', 28153),
(136676, 'deDE', 'Lotis Ansatz is\' mir zu bodenständig. Ich mach das lieber aus der Pterrordaxperspektive.', '', 28153),
(136674, 'deDE', 'Bereit zur Patrouille.', 'Bereit zur Patrouille.', 28153),
(136673, 'deDE', '', 'Ich bin Kriegsdruidin Loti. Ich spreche für Gonk, den Loa der Wandlung un\' Meister der Jagd.$b$bIch bin auch \'n Mitglied im Rat der Zanchuli, aber das habt Ihr sicher schon gewusst.', 28153),
(136672, 'deDE', 'Der Träger nickt der Wache der Zandalari zu.', '', 28153),
(136671, 'deDE', 'Die Wache mustert Euch eingehend.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136670, 'deDE', 'Die Wache nimmt Eure Anwesenheit zur Kenntnis.', '', 28153),
(136669, 'deDE', 'Ich hoff, Ihr habt Eure Lektion gelernt!', 'Ich hoff, Ihr habt Eure Lektion gelernt!', 28153),
(136668, 'deDE', 'Die Wache grüßt Euch, als Ihr vorbeigeht.', '', 28153),
(136667, 'deDE', 'Die Wache nickt zu Euch herüber.', '', 28153),
(136662, 'deDE', 'Ihr steht vor Hexfürst Raal, Mitglied des Rats der Zanchuli un\' Hohepriester des großen Loas Pa\'ku, Meisterin der Winde un\' unsrer Flotte.\n\nAlso, was wollt Ihr?', '', 28153),
(136657, 'deDE', 'Arbeit, Arbeit.', '', 28153),
(136655, 'deDE', '', 'Möge das Licht Euch Frieden schenken, $C.', 28153),
(136654, 'deDE', 'Blöder Sur\'jan! Warum musst du vor allen das Maul aufreiß\'n? Die denk\'n doch, dass du verrückt bis\'!', '', 28153),
(136653, 'deDE', 'Ich geh un\' bereite alles fürs Ritual vor. Wir können Urok töt\'n, sobald ich meine Kraft wiederhab.', '', 28153),
(136652, 'deDE', 'Ich weiß, ich leb in Nazmir un\' Ihr denkt, ich wär irre, aber Ihr müsst mir zuhör\'n! Ihr seid alle tot, wenn Ihr mir nich\' helft!', '', 28153),
(136651, 'deDE', 'Ich weiß, Ihr haltet mich für irre, aber Ihr müsst mir helf\'n!', '', 28153),
(136650, 'deDE', 'Schickt mich nich\' ständig weg! Ich brauch Eure Hilfe!', '', 28153),
(136649, 'deDE', 'So, sein Schutz is\' weg! Mach\'n wir ihn fertig!', '', 28153),
(136648, 'deDE', '', 'Bei G\'huun, ich wurd\' wiedergebor\'n.', 28153),
(136647, 'deDE', 'Ich überlass Euch die komplizierten Dinge. Ich wart draußen vor Uroks Höhle.', '', 28153),
(136646, 'deDE', 'HAH! Wir haben\'s geschafft! Hab ich dir doch gesagt, Sur\'jan, dass wir ihn schlag\'n könn\'!', '', 28153),
(136645, 'deDE', 'Champion, schnappt Euch die Hexe! Ihre tanz\'nden Knoch\'ngerippe werd\'n vor dem wahren Herrn des Todes fall\'n.', '', 28153),
(136644, 'deDE', 'Urok is\' von den Totems geschützt! Nehmt meine Fackel, um sie niederzubrenn\'!', '', 28153),
(136643, 'deDE', '<Der Rucksack ist halb von Sand bedeckt, doch sein Inhalt scheint in brauchbarem Zustand zu sein.>', '', 28153),
(136642, 'deDE', '', 'Hab ich Euch nicht gewarnt, da reinzugehen? Das hat Euch fast den Kopf gekostet!', 28153),
(136641, 'deDE', 'Der Tod kommt Euch holen!', 'Der Tod kommt Euch holen!', 28153),
(136640, 'deDE', 'Störenfried!', 'Störenfried!', 28153),
(136639, 'deDE', 'Kommt zu uns!', 'Kommt zu uns!', 28153),
(136638, 'deDE', '', 'Ihr werdet meine Arbeit nicht stören! Vernichtet dieses Insekt!', 28153),
(136637, 'deDE', 'Los! Los! Los!', 'Los! Los! Los!', 28153),
(136632, 'deDE', 'Haha, den werd ich niedermach\'n!', '', 28153),
(136615, 'deDE', '', 'Erhebt Euch, Diener! Und vernichtet den töricht\'n Loa!', 28153),
(136614, 'deDE', 'Ich brauch Eure Hilfe... Es kommt was Böses un\' ich kann es nich\' allein töt\'n!', '', 28153),
(136613, 'deDE', '', 'Große Worte. Aber auf Euch wartet dasselbe Schicksal, wie auf alle, die sich G\'huun verweigern.', 28153),
(136611, 'deDE', 'Keiner darf Bwonsamdi rumkommandier\'n. Ihr glaubt also, Ihr könnt Euch mir entgegenstell\'n, Wicht?', '', 28153),
(136610, 'deDE', 'Hmm... Ihr seht wie \'n schlaues Mädchen aus, und trotzdem unterbrecht Ihr mich in mei\'m eignen Tempel.', '', 28153),
(136609, 'deDE', '', 'Ich geb Euch eine Chance, Euch dem Blutgott zu unterwerf\'n. Gebt auf... oder sterbt!', 28153),
(136608, 'deDE', '', 'Bwonsamdi! Endlich traut Ihr Euch aus dem Schutz der Ruine.', 28153),
(136607, 'deDE', 'Was steht Ihr hier so faul rum? Fangen wir an!', '', 28153),
(136605, 'deDE', 'Lasst uns die Sache angehen.', 'Lasst uns die Sache angehen.', 28153),
(136604, 'deDE', 'Der Ritus der Bindung is\' altes, altes Mojo. Alt wie die Welt selbst. Wenn Ihr mit dies\'m Mojo was tötet, bekommt Bwonsamdi die Seele ab. Wenn Ihr den Ritus annehmt, sin\' wir im Geschäft.$b$bSeid Ihr bereit? Ich schon.', '', 28153),
(136603, 'deDE', '', 'Was gibt es denn, $gFestländer:Festländerin;?', 28153),
(136602, 'deDE', '', 'Meine Rekruten sind bereit, die Dorfbewohner zu verteidigen. Sollen wir mit der Evakuierung beginnen?', 28153),
(136601, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(136600, 'deDE', 'Das war \'n mieser Trick, Pinkie. Böser Teufelssaurier! Böse!', 'Das war \'n mieser Trick, Pinkie. Böser Teufelssaurier! Böse!', 28153),
(136599, 'deDE', 'Kommt zum Hof der Seelen. Es is\' an der Zeit, dass wir unsren Pakt... abschließen.', '', 28153),
(136591, 'deDE', 'Genug gelabert, Schwester. Wir haben Befehle von der Prinzessin.', '', 28153),
(136590, 'deDE', '', 'Dann hat sie mir befohl\'n, drauf zu acht\'n, dass $n und, Zitat, \"der Niedliche\" so schnell wie möglich nach Nazmir gelang\'n.', 28153),
(136589, 'deDE', 'Der Schlurfer hat sich gegen seine Meister gewandt!', '', 28153),
(136588, 'deDE', 'Der Knecht scheint vorübergehend handlungsunfähig zu sein.', '', 28153),
(136587, 'deDE', 'Der Knecht wird in die Raserei getrieben!', '', 28153),
(136581, 'deDE', 'Kümmert Euch um diesen Eindringling, Meereswächter. Gehorcht meinem Willen.', '', 28153),
(136578, 'deDE', 'Respekt erweisen', '', 28153),
(136577, 'deDE', 'Ich wette, an den Docks finden wir mehr Aschenwindwaffen. Wir müssen rausfinden, wer sie kauft.', '', 28153),
(136576, 'deDE', '', 'Meine Schwestern sind zahlreich... Kul Tiras wird fallen...', 28153),
(136575, 'deDE', '', 'Ihr könnt nicht gewinnen! Der Zirkel wird nicht haltmachen, bis sie alle dienen!', 28153),
(136574, 'deDE', '', 'Spürt meinen Zorn!', 28153),
(136573, 'deDE', '', 'Beeindruckend... aber so leicht besiegt Ihr eine Matrone des Herzbannzirkels nicht!', 28153),
(136572, 'deDE', '', 'Das ändert nichts. Seht, was mit Feinden des Zirkels geschieht! Akolythen, vernichtet die aufsässige Made!', 28153),
(136571, 'deDE', '', 'Ein dahergelaufener Tölpel setzt also eine unserer Schöpfungen gegen uns ein, hm? Ihr müsst Euch für so gerissen halten.', 28153),
(136570, 'deDE', 'Ich hab sie noch nie so brechend voll gesehen. Da braut sich was zusammen.', '', 28153),
(136569, 'deDE', 'Freibeuter, Söldner... sogar Piraten sind willkommen. Ist also eine recht, äh... lebhafte Stadt.', '', 28153),
(136568, 'deDE', 'Freihafen steht jedem offen. Im Gegensatz zu Boralus gibt\'s hier keine Gesetze, welche Schiffe anlegen dürfen und welche nicht.', '', 28153),
(136567, 'deDE', '', 'Es tut mir leid, $C. Wir haben absolut keinen Seetang mehr. Wir sind alle zu krank, um ins Wasser zu gehen und neuen zu sammeln. Sagt Therold, dass es mir leidtut.', 28153),
(136566, 'deDE', '', 'Meine Schwestern werden mich rächen...', 28153),
(136565, 'deDE', '', 'Ihr hättet Euch nicht einmischen sollen!', 28153),
(136564, 'deDE', 'Habt Ihr Seetang? Therold braucht ihn für ein Gegengift.', 'Habt Ihr Seetang? Therold braucht ihn für ein Gegengift.', 28153),
(136563, 'deDE', '', 'Die Matrone wird Euch vernichten...', 28153),
(136562, 'deDE', '', 'Diese Stadt gehört dem Zirkel, Eindringling!', 28153),
(136561, 'deDE', '', 'So viel zu tun, so wenig Zeit!$b$bIch muss die Fischer und ihre Ausrüstung segnen, die Gezeiten beobachten, um Omen zu erkennen, für die Rückkehr unserer Seeleute beten...', 28153),
(136560, 'deDE', '', 'Ihr werdet dem Zirkel dienen...', 28153),
(136559, 'deDE', '', 'Der Zirkel wird alles verschlingen!', 28153),
(136558, 'deDE', 'Die Sirenen sind heute alle unterwegs. Verlasst den Boden nicht. Haltet Euch von Inseln fern, dann wird es Euch gutgehen.', 'Die Sirenen sind heute alle unterwegs. Verlasst den Boden nicht. Haltet Euch von Inseln fern, dann wird es Euch gutgehen.', 28153),
(136557, 'deDE', 'Die Gezeiten sind im Osten stark ausgeprägt. Hier im Westen bleibt das Meer ruhiger.', 'Die Gezeiten sind im Osten stark ausgeprägt. Hier im Westen bleibt das Meer ruhiger.', 28153),
(136556, 'deDE', 'Mein Segen wird Euch auch im Wasser schützen.', 'Mein Segen wird Euch auch im Wasser schützen.', 28153),
(136555, 'deDE', 'Schickt die Fischer zum Dock am Markt. Dort tummeln sich heute viele Fische.', 'Schickt die Fischer zum Dock am Markt. Dort tummeln sich heute viele Fische.', 28153),
(136554, 'deDE', 'Unter Eurer Führung werden wir sicher sein.', 'Unter Eurer Führung werden wir sicher sein.', 28153),
(136553, 'deDE', 'Wir müssen in tiefere Gewässer vorstoßen. Was ist der beste Kurs?', 'Wir müssen in tiefere Gewässer vorstoßen. Was ist der beste Kurs?', 28153),
(136552, 'deDE', 'Dann müssen wir uns keine Sorgen machen. Danke!', 'Dann müssen wir uns keine Sorgen machen. Danke!', 28153),
(136551, 'deDE', 'Wir dringen in tiefe Gewässer vor. Wie sieht es mit den Gezeiten aus?', 'Wir dringen in tiefe Gewässer vor. Wie sieht es mit den Gezeiten aus?', 28153),
(136550, 'deDE', 'Ich spüre, wie Euer Segen mich durchströmt. Herzlichen Dank.', 'Ich spüre, wie Euer Segen mich durchströmt. Herzlichen Dank.', 28153),
(136549, 'deDE', 'Ich mache mich auf den Weg ins Monstergebiet. Bitte schenkt mir Euren Segen!', 'Ich mache mich auf den Weg ins Monstergebiet. Bitte schenkt mir Euren Segen!', 28153),
(136548, 'deDE', 'Ich werde den Fischern Bescheid sagen.', 'Ich werde den Fischern Bescheid sagen.', 28153),
(136547, 'deDE', 'Wo gibt es heute die meisten Fische?', 'Wo gibt es heute die meisten Fische?', 28153),
(136546, 'deDE', 'Hey! Ihr seid \'n angesagtes Thema im Kral, Fremdling. Die erzähl\'n, Ihr seid besonders mutig!', '', 28153),
(136545, 'deDE', '', 'Ihr seid unter denen, die mit den Loa wand\'ln. Seid vorsichtig, nich\' alle Loa können einander leid\'n.', 28153),
(136538, 'deDE', 'Krieger der Horde! Heute erheben wir uns und tränken unsere Äxte im Blut unserer Feinde!', '', 28153),
(136533, 'deDE', 'Mekkadrill, können Eure Flugmaschinen uns über diese Verseuchung bringen?', '', 28153),
(136532, 'deDE', '', 'Ihr brauchtet Unterstützung, König Wrynn?', 28153),
(136528, 'deDE', 'Jaina! Blockiert die Ausgänge! Lasst nicht zu, dass sie Verstärkung rufen!', '', 28153),
(136527, 'deDE', 'Dieser Tempel wird fall\'n! Die Priesterin hat\'s vorhergeseh\'n!', '', 28153),
(136526, 'deDE', 'Beschützt die Priesterin!', '', 28153),
(136525, 'deDE', 'Die Priesterin braucht Blut fürs Ritual. Wir nehm\'n einfach Eures.', '', 28153),
(136524, 'deDE', 'Für die Priesterin! Für G\'huun!', '', 28153),
(136523, 'deDE', 'Bwonsamdi hat keine Macht über uns! Für den Blutgott!', '', 28153),
(136522, 'deDE', 'Auf Befehl der Kriegsfürstin!', '', 28153),
(136521, 'deDE', 'Ich zerquetsche alle Eindringlinge!', '', 28153),
(136520, 'deDE', 'Für Kriegsfürstin Malaka! Für den Blutgott!', '', 28153),
(136519, 'deDE', 'Ihr werdet \'nen gut\'n Sklaven für die Kriegsfürstin abgeb\'n!', '', 28153),
(136518, 'deDE', '', 'Ihr wagt\'s, mein Ritual zu unterbrech\'n?', 28153),
(136517, 'deDE', '', 'Das reicht! Ich hab gesagt, ich denk\' drüber nach!', 28153),
(136516, 'deDE', 'Aber Ihr könntet Eure Produktion mindestens verdreifachen! Meine Elixiere enthalten zu einhundert Prozent natürliche Zutaten und...', '', 28153),
(136515, 'deDE', '', 'Ich weiß nich\'... Wir komm\'n eigentlich ganz gut zurecht un\'...', 28153),
(136514, 'deDE', 'Ich sage Euch, Ihr verpasst eine riiiiiesige Gelegenheit! Das solltet Ihr Euch nicht entgehen lassen!', '', 28153),
(136513, 'deDE', '', 'Das werdet Ihr bereu\'n!', 28153),
(136512, 'deDE', '', 'Beginnt mit dem Ritual. Ich werd diese klägliche Hülle hinter mir lass\'n.', 28153),
(136511, 'deDE', 'Hier gibt\'s nichts zu sehen, fort mit Euch!', '', 28153),
(136510, 'deDE', 'Bringt mich nicht dazu, Euch wehzutun.', '', 28153),
(136509, 'deDE', 'He! Was macht Ihr hier?', '', 28153),
(136508, 'deDE', '', 'Alle werd\'n... sich dem Willen des Blutgottes unterwerf\'n...', 28153),
(136507, 'deDE', '', 'Mehr Blut für den Blutgott!', 28153),
(136498, 'deDE', 'Alle scheinen den Verstand zu verlieren! Ich verschwinde, solange es noch möglich ist!', '', 28153),
(136497, 'deDE', '', 'Es ist vorbei.\n\nEs war... notwendig. Die Verderbnis war zu weit vorangeschritten.\n\n<Rebecca schnieft.>\n\nEntschuldigt bitte. Ich brauche etwas Zeit für mich.', 28153),
(136495, 'deDE', '', 'Zuerst fand ich es noch ganz unterhaltsam, was meine Schwester so trieb, aber das ist Irrsinn!\n\nIn ihrem Zauberfolianten spricht sie davon, dass sie eine Armee dieser uralten Konstrukte ausheben will! Sie wird ganz Drustvar versklaven, wenn man sie nicht aufhält!', 28153),
(136494, 'deDE', 'Hinfort!', 'Hinfort!', 28153),
(136493, 'deDE', '', 'Ich hoff, Mutta un\' ich seh\'n Euch mal wieder.', 28153),
(136492, 'deDE', '', 'Ja, Mutta hat \'n Fehler gemacht. Aber ich vergeb ihr. Jetzt könn\' wir den Rest der Ewigkeit zusamm\' auf der Andern Seite verbring\'n.', 28153),
(136491, 'deDE', '', 'Jetzt sin\' Mutta un\' ich zusamm\'... für immer!', 28153),
(136490, 'deDE', '', 'Neiiiiin... Ich sollte für immer... leb\'n...', 28153),
(136489, 'deDE', 'Passt auf. Hier krabbeln ein paar fiese Viecher rum.', '', 28153),
(136488, 'deDE', '', 'Was is\' das? Nein! Wie könnt Ihr\'s wag\'n, dieses DING hierherzubring\'n!', 28153),
(136487, 'deDE', '', 'Hab dich gefunden, Mutta!', 28153),
(136486, 'deDE', '', 'Wer wagt\'s, meine Ruhe zu stör\'n?', 28153),
(136485, 'deDE', '<Versucht, den Sarkophag zu öffnen.>', '<Versucht, den Sarkophag zu öffnen.>', 28153),
(136484, 'deDE', '<Der Sarkophag ist fest verschlossen, aber mit einiger Anstrengung solltet Ihr ihn öffnen können.>', '', 28153),
(136483, 'deDE', '', 'Ich glaub, wir sin\' fast da! Mutta! Wo bis\' du?', 28153),
(136482, 'deDE', '', 'Es is\' dunkel da drin. Geht vor, ich bin gleich hinter Euch.', 28153),
(136481, 'deDE', '', 'Nein, das is\' die Gruft der großen Königin. Mutta würd\' Ärger bekomm\'n, wenn sie da reingeht.', 28153),
(136480, 'deDE', '', 'Ihhh, die Priester da drin stink\'n nach alten Würmern! Nee, da is\' Mutta bestimmt nich\'.', 28153),
(136479, 'deDE', '', 'Ich und Mutta ham Priester hier gefund\'n. Ham mir \'n Kleidchen gegeb\'n. Richtig nett!', 28153),
(136478, 'deDE', 'Ich wusste, Ihr seid mir nicht gewachsen!', 'Ich wusste, Ihr seid mir nicht gewachsen!', 28153),
(136477, 'deDE', '', 'Nee, hier is\' sie nich\'. In den Haupttempel kommt niemand rein.', 28153),
(136476, 'deDE', 'Ich muss härter trainieren...', 'Ich muss härter trainieren...', 28153),
(136475, 'deDE', 'Arggh... Ihr seid stärker, als ich erwartet hatte.', 'Arggh... Ihr seid stärker, als ich erwartet hatte.', 28153),
(136474, 'deDE', 'Genug! Ich gebe auf!', 'Genug! Ich gebe auf!', 28153),
(136473, 'deDE', 'Ihr habt gewonnen. Dieses Mal...', 'Ihr habt gewonnen. Dieses Mal...', 28153),
(136472, 'deDE', 'Es reicht! Ich gebe auf!', 'Es reicht! Ich gebe auf!', 28153),
(136471, 'deDE', 'Versucht, mich nicht vollzubluten!', 'Versucht, mich nicht vollzubluten!', 28153),
(136470, 'deDE', 'Es war töricht von Euch, mich herauszufordern!', 'Es war töricht von Euch, mich herauszufordern!', 28153),
(136469, 'deDE', 'Ich hoffe, Euer Schwert ist so scharf wie Eure Zunge!', 'Ich hoffe, Euer Schwert ist so scharf wie Eure Zunge!', 28153),
(136468, 'deDE', 'Ihr wagt es, mich herauszufordern? Macht Euch darauf gefasst, Euer eigenes Blut zu vergießen!', 'Ihr wagt es, mich herauszufordern? Macht Euch darauf gefasst, Euer eigenes Blut zu vergießen!', 28153),
(136467, 'deDE', 'Gegen mich zu kämpfen, wird Euer letzter Fehltritt sein!', 'Gegen mich zu kämpfen, wird Euer letzter Fehltritt sein!', 28153),
(136466, 'deDE', 'Wenn Ihr eine Abreibung wollt... könnt Ihr eine Abreibung haben!', 'Wenn Ihr eine Abreibung wollt... könnt Ihr eine Abreibung haben!', 28153),
(136465, 'deDE', '', 'Sie sagte, sie geht irgendwo hin, wo\'s dunkel und gruselig is\'. Wo könnt\' das sein? Oh... Ich hasse dunkle Orte.', 28153),
(136464, 'deDE', '', 'Ah! Okay, Mutta hat was gesagt über \'ne Abmachung mit Bwonsamdi. Sie is\' sicher noch irgendwo in dem Tempel.', 28153),
(136463, 'deDE', 'Razgaji riet mir, Euch zu einem Duell herauszufordern.', 'Razgaji riet mir, Euch zu einem Duell herauszufordern.', 28153),
(136462, 'deDE', 'Passt lieber auf... Ich habe nichts für Fremde übrig.', 'Passt lieber auf... Ich habe nichts für Fremde übrig.', 28153),
(136461, 'deDE', 'Fragt mich, wie ich in Vol\'dun gelandet bin, und ich gebe Euch eine Liste von Friedhöfen, die Ihr besuchen solltet...', 'Fragt mich, wie ich in Vol\'dun gelandet bin, und ich gebe Euch eine Liste von Friedhöfen, die Ihr besuchen solltet...', 28153),
(136460, 'deDE', 'Ich zähle bis drei. Bis dahin habt Ihr Zeit, kehrtzumachen... Drei!', 'Ich zähle bis drei. Bis dahin habt Ihr Zeit, kehrtzumachen... Drei!', 28153),
(136459, 'deDE', 'Seht Ihr nicht, dass ich trainiere? Haut ab!', 'Seht Ihr nicht, dass ich trainiere? Haut ab!', 28153),
(136458, 'deDE', 'Rokhan, ich bin hier, um Euch und Prinzessin Talanji zu helfen, Nazmir zu erkunden.', 'Rokhan, ich bin hier, um Euch und Prinzessin Talanji zu helfen, Nazmir zu erkunden.', 28153),
(136457, 'deDE', 'Prinzessin Talanji schickt uns nach Nazmir. Wir brauch\'n Eure Pterrordaxe, um da hinzukomm\'.', '', 28153),
(136453, 'deDE', '', 'Sichert die Stadt um jeden Preis. Ich werde in Kürze eintreffen und die Ruinen persönlich untersuchen.', 28153),
(136451, 'deDE', '', 'Die Gruft darin birgt womöglich Relikte, die sich für die Rituale des Zirkels als nützlich erweisen könnten.', 28153),
(136450, 'deDE', '', 'Die Minenarbeiter aus Schnitztal sind tief in der Ursteinmine auf eine unberührte, verborgene Ruine gestoßen.', 28153),
(136449, 'deDE', '', 'Schwestern des Zirkels!', 28153),
(136448, 'deDE', '', 'Ich hab da drin schon zwei Männer verloren. Macht nicht denselben Fehler.', 28153),
(136447, 'deDE', '', 'Ich weiß nicht, was die aushecken, aber die Magie dort scheint einem richtig das Leben auszusaugen.', 28153),
(136446, 'deDE', '', 'Ein guter Rat, $C: Meidet auf jeden Fall die Minen.', 28153),
(136445, 'deDE', '', 'Das waren alle Dorfbewohner. Mit ein bisschen Glück schaffen sie\'s unversehrt nach Fallhafen.', 28153),
(136444, 'deDE', '', 'Jetzt fahren sie wohl die großen Geschütze auf! Festhalten, Leute!', 28153),
(136443, 'deDE', '', 'Mehr Angreifer aus der Stadt! Haltet die Stellung!', 28153),
(136442, 'deDE', '', 'Die nehmen uns aufs Korn. Beschützt die Zivilisten!', 28153),
(136441, 'deDE', '', 'Bezieht mit ihnen Stellung und wehrt Angriffe aus der Stadt ab!', 28153),
(136440, 'deDE', '', 'Okay, Jungs, sichern wir die Straße hier, damit wir die Anwohner in Sicherheit bringen können.', 28153),
(136439, 'deDE', '', 'Dann hoffe ich mal, Ihr habt eine Armee im Gepäck.', 28153),
(136438, 'deDE', '', 'Hört ihr das, Leute? Der Festländer räumt unsre Stadt mit uns auf!', 28153),
(136437, 'deDE', '', 'Also, diese unheimlichen Weidenleute meinen es jedenfalls ernst.\n\nEs begann alles vor ein paar Wochen, als einige der Minenarbeiter verschwanden. Und dann tauchten plötzlich diese Kreaturen auf und begannen, uns aus der Stadt zu vertreiben. Es ging los, als diese junge Kronsteig sich hier herumtrieb. Und nachdem sie wieder weg war, wurde das Problem sogar noch schlimmer.\n\nJetzt haben diese Dinger den ganzen Ort übernommen und die meisten Bewohner gefangen. Ich konnte diese Stellung mit ein paar Freiwilligen halten, aber ich habe keine Ahnung, wie ich meine Stadt zurückerobern kann.\n\nAlso, wenn Ihr uns nicht helfen wollt, solltet Ihr vielleicht besser gleich weiterziehen.', 28153),
(136436, 'deDE', 'Ich bin hier, um zu helfen.', 'Ich bin hier, um zu helfen.', 28153),
(136435, 'deDE', 'Was geht hier vor?', 'Was geht hier vor?', 28153),
(136434, 'deDE', '', 'Seitdem diese Alptraumkreaturen aus den Minen herausströmen, geht unser Dorf den Bach runter.\n\nIch hoffe, Ihr habt mehr Glück bei der Suche nach der Ursache für dieses Chaos als wir.', 28153),
(136432, 'deDE', 'Ich werde Euch helfen, Eure Mutter zu finden.', 'Ich werde Euch helfen, Eure Mutter zu finden.', 28153),
(136431, 'deDE', 'Ihr wart sehr geduldig.', 'Ihr wart sehr geduldig.', 28153),
(136430, 'deDE', '', 'Hier is\' es soooo einsam ohne Mutta.$b$bKönnt Ihr mir helf\'n, sie zu find\'n? Bitte! Ich bin auch ganz brav. Ich versprech\'s!', 28153),
(136429, 'deDE', '', 'Mutta hat mir gesagt, ich soll hierbleib\'n. Ich wart hier aber schon seit \'ner halben Ewigkeit und Mutta taucht nich\' wieder auf!$b$bIch will nich\' mehr wart\'n! Ich will meine Mutta!', 28153),
(136428, 'deDE', 'Was macht Ihr hier?', 'Was macht Ihr hier?', 28153),
(136427, 'deDE', '', 'Wo is\' Mutta? Ich will nach Hause!', 28153),
(136426, 'deDE', '', 'Wo is\' Mutta bloß hin? Sie is\' schon so lang weg!', 28153),
(136425, 'deDE', '', 'Es is\' so kalt... Wo is\' Mutta bloß?', 28153),
(136422, 'deDE', 'Noch jemand, der nach Nazmir will? Glaubt mir, Ihr kommt nich\' zurück.', '', 28153),
(136421, 'deDE', '', 'Hmpf. Sagt nichts mehr. Ich mach mich auf den Weg nach Nazmir. Hoffentlich können wir die Prinzessin einhol\'n.', 28153),
(136420, 'deDE', 'Talanji is\' schon in Nazmir? Dann mach ich mich mal los, wir seh\'n uns dort.', '', 28153),
(136419, 'deDE', '', 'Es gibt keine Zeit zu verlieren! Wir haben seit Tagen nichts von Falkenforst gehört.', 28153),
(136418, 'deDE', '', 'Ich g-glaube, ich kann mich in die Höhle sch-schleichen, in der meine Schwester ist. Wir treffen uns dort.', 28153),
(136417, 'deDE', '', 'Ich mach mich auf den Weg nach Nazmir. Wir seh\'n uns dort.', 28153),
(136415, 'deDE', 'Hochwertige Zutaten sind in Vol\'dun nicht leicht zu find\'n, aber wenn Ihr schnell esst und die Augen dabei schließt, schmeckt\'s gar nich\' so schlecht, wie man erwart\'n würde!', '', 28153),
(136414, 'deDE', 'Wenn Ihr mehr über Alpakas wiss\'n wollt, seid Ihr bei mir an der richtig\'n Adresse! Ich weiß alles, was man nur wiss\'n kann, un\' mehr.', '', 28153),
(136413, 'deDE', 'Vol\'dun mag \'ne tückische Ödnis sein, aber \'ne andre Heimat hab ich nich\'.', '', 28153),
(136407, 'deDE', 'Wir geh\'n an \'nen Ort, an den sonst niemand in Zuldazar geh\'n will. Seid vorbereitet.', '', 28153),
(136406, 'deDE', 'ZERSCHMETTERN!', '', 28153),
(136405, 'deDE', 'Ich hab noch so\'n Fremdling hier mitgebracht. Er will mit Euch sprech\'n, mächtiger Loa.', '', 28153),
(136404, 'deDE', 'Kommt. Hier geht\'s lang.', '', 28153),
(136403, 'deDE', 'Ah, die Stimme kenn\' ich doch. Und Geschenke, sehr schön. Kommt rein, kommt rein.', '', 28153),
(136402, 'deDE', 'Großfuhre kommt raus! Holt Verstärkung!', '', 28153),
(136398, 'deDE', 'Meine Haut! Das brennt!', '', 28153),
(136397, 'deDE', 'Ahhhhh!', '', 28153),
(136396, 'deDE', 'Großer Bwonsamdi, diese Opfer erwart\'n Euch!', '', 28153),
(136395, 'deDE', 'Doba quzhu ta tawbo!', '', 28153),
(136394, 'deDE', 'Sehr gut. Jetzt schlagt die Trommel!', '', 28153),
(136393, 'deDE', 'Lasst die Vision Eure Schritte lenk\'n, bis sie den magischen Kreis bilden. Vorsichtig! Bwonsamdi wird verärgert sein, wenn das Ritual schlampig durchgeführt wird.', '', 28153),
(136388, 'deDE', 'War\'s das dann mit den Nebengeschäften? Einmal mit <hick> Profis arbeiten...', '', 28153),
(136387, 'deDE', 'Giftstacheln? Bin sicher, die dienen einem absolut seriösen Zweck.', '', 28153),
(136386, 'deDE', 'He, hier ist es gefährlich! <hick> Ihr solltet Euch echt an mich halten!', '', 28153),
(136385, 'deDE', 'Dann, äh... wart ich wohl mal.', '', 28153),
(136384, 'deDE', '<hick> Hier drüben!', '', 28153),
(136383, 'deDE', 'He, worauf wartet Ihr?!', '', 28153),
(136382, 'deDE', '<hick> Kuckuck, Eidechse.', '', 28153),
(136380, 'deDE', 'Klingen bereithalten! Lok\'tar ogar!', '', 28153),
(136379, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Tunnel graben', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Tunnel graben', 28153),
(136378, 'deDE', 'He, $gKumpel:Herzchen;! Wisst Ihr, was der neueste Technologietrend an der Kriegsfront ist?\n\nTunnel.\n\nGanz genau. Für nur EINEN großen Haufen Gold graben mein Partner und ich Euch und Euren Kriegsgefährten einen Tunnel zur Front. Was meint Ihr?', '', 28153),
(136377, 'deDE', 'Das ist ein raues Pflaster. Lasst <hick> besser mich reden.', '', 28153),
(136376, 'deDE', 'Da sind wir. Freihafen!', '', 28153),
(136375, 'deDE', 'Hmmm. Letztes Mal war\'s rechts... dann MUSS es ja links sein! Schätze, mein Kopf ist langsam wieder im Lot.', '', 28153),
(136374, 'deDE', '', 'Wir müss\'n die Sphäre zurück ins Lager schaff\'n, bevor die Sethrak merk\'n, dass sie weg ist! Beeilt Euch!', 28153),
(136373, 'deDE', 'Ah. Wir sind fast da. Ich kann\'s spüren.', '', 28153),
(136372, 'deDE', 'Puh, was für ein Marathon. Ich muss die Glieder ölen...', '', 28153),
(136371, 'deDE', 'W... Was? Wer seid Ihr? Was ist das?', 'W... Was? Wer seid Ihr? Was ist das?', 28153),
(136370, 'deDE', 'Dieses Ding hat mein Gehirn kontrolliert?!', 'Dieses Ding hat mein Gehirn kontrolliert?!', 28153),
(136369, 'deDE', 'Ah-ha! Das hab ich schon mal gesehen. Muss der <hick> richtige Weg sein.', '', 28153),
(136368, 'deDE', 'Wa... Was ist geschehen?', 'Wa... Was ist geschehen?', 28153),
(136367, 'deDE', 'Uq naggwa... Unser Meister wird Euch holen...', 'Uq naggwa... Unser Meister wird Euch holen...', 28153),
(136366, 'deDE', 'Ihr seid zu spät! Ihr könnt die bevorstehende Flut nicht mehr aufhalten!', 'Ihr seid zu spät! Ihr könnt die bevorstehende Flut nicht mehr aufhalten!', 28153),
(136365, 'deDE', 'Ah, japp, schon besser. Los geht\'s.', '', 28153),
(136364, 'deDE', 'Uff, bin noch ein bisschen tüddelig. Ich spül mal den Kopf durch.', '', 28153),
(136363, 'deDE', 'Nee, nee. DEFINITIV rechts.', '', 28153),
(136362, 'deDE', '<hick> Also, wo wollten wir hin... links?', '', 28153),
(136361, 'deDE', 'Das Geflüster... Es überwältigt meine Gedanken...', 'Das Geflüster... Es überwältigt meine Gedanken...', 28153),
(136360, 'deDE', 'Meine Seele für das Meer...', 'Meine Seele für das Meer...', 28153),
(136359, 'deDE', 'Y\'za qam yyqzz...', 'Y\'za qam yyqzz...', 28153),
(136358, 'deDE', 'O Eindringling. Ihr stolpert in Orte, in denen Ihr nichts zu suchen habt!', 'O Eindringling. Ihr stolpert in Orte, in denen Ihr nichts zu suchen habt!', 28153),
(136357, 'deDE', 'Euer Herz wird eine würdige Opfergabe bieten!', 'Euer Herz wird eine würdige Opfergabe bieten!', 28153),
(136356, 'deDE', 'Ich gebe mich voll und ganz dieser Macht hin!', 'Ich gebe mich voll und ganz dieser Macht hin!', 28153),
(136350, 'deDE', '%s folgt Euch.', '', 28153),
(136349, 'deDE', '%s ist es leid, Euch zu folgen, und läuft davon.', '', 28153),
(136348, 'deDE', '', 'Jetzt, wo die See unter Kontrolle ist, sollten wir uns auf die Höhlen konzentrieren.', 28153),
(136347, 'deDE', 'Kerz\'n am Platz un\' die Opfer sin\' bereit. Jetz\' noch den Zirkel mal\'n...', '', 28153),
(136346, 'deDE', 'Der Himmelsruferedelstein wird überladen! Wer weiß, was geschehen würde, wenn Ihr ihn jetzt nutzt?', 'Der Himmelsruferedelstein wird überladen! Wer weiß, was geschehen würde, wenn Ihr ihn jetzt nutzt?', 28153),
(136345, 'deDE', 'Für die Horde!', '', 28153),
(136341, 'deDE', 'Lasst uns anfangen.', 'Lasst uns anfangen.', 28153),
(136340, 'deDE', 'Wir werden die Ebenen mit dem Blut unserer Feinde tränken und erblühen lassen.', '', 28153),
(136327, 'deDE', '', 'Achtung!', 28153),
(136326, 'deDE', '', 'Achtung!', 28153),
(136325, 'deDE', 'Na dann... weiter geht\'s. Das können wir noch hinbiegen.', '', 28153),
(136324, 'deDE', 'Bittet Fozruk darum, den Hochstand anzugreifen.', 'Bittet Fozruk darum, den Hochstand anzugreifen.', 28153),
(136323, 'deDE', 'Bittet Fozruk darum, den Heldenrufpass anzugreifen.', 'Bittet Fozruk darum, den Heldenrufpass anzugreifen.', 28153),
(136322, 'deDE', 'Bittet Fozruk darum, Stromgarde anzugreifen.', 'Bittet Fozruk darum, Stromgarde anzugreifen.', 28153),
(136321, 'deDE', '<Fozruk blickt auf Euch herab.>', '', 28153),
(136320, 'deDE', 'Mit Vergnügen.', '', 28153),
(136319, 'deDE', 'Ich werde Euch zerfetzen!', '', 28153),
(136318, 'deDE', 'Vergeblich... Die anderen werden kommen... und den Edelstein zurückholen...', '', 28153),
(136317, 'deDE', 'Ihr werdet uns nicht davon abhalten können, die wahre Macht des Himmelsruferedelsteins zu finden!', '', 28153),
(136316, 'deDE', 'Die Wüste wird sich ausbreiten!', '', 28153),
(136315, 'deDE', 'Wir holen uns Nazmir für die Sethrak!', '', 28153),
(136314, 'deDE', 'Dieses Land wird zu Sand werden!', '', 28153),
(136313, 'deDE', 'Euer Land holen wir uns als nächstes!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136312, 'deDE', 'Ihr könnt unsere Vorherrschaft nicht aufhalten!', '', 28153),
(136311, 'deDE', 'Die Sümpfe werden verwandelt!', '', 28153),
(136310, 'deDE', 'Wir herrschen über alles und alle!', '', 28153),
(136309, 'deDE', 'Die Wüste wird dieses Land übernehmen!', '', 28153),
(136297, 'deDE', 'WIE KONNTET IHR?!', '', 28153),
(136296, 'deDE', 'Ihr... Ihr habt die Liebe meines Lebens getötet!', '', 28153),
(136295, 'deDE', 'Argh... Verdammt! Von den Sethrak zweigeteilt... So kann man doch nicht abtreten.', '', 28153),
(136292, 'deDE', 'Möge der Segen des Meers Euch überfluten! Auf dass Ihr seine zarte Umarmung spürt und als Euren Verbündeten erkennt.', '', 28153),
(136291, 'deDE', 'Xibala... wird Euch leid\'n lass\'n...', '', 28153),
(136290, 'deDE', 'Das is\' Xibalas heiliger Schrein. Er wird \'ne neue Seele in seiner Sammlung willkommen heiß\'n!', '', 28153),
(136278, 'deDE', 'Die Welt wird untergehen... ak yar qi\'lwhuk h\'iwn...', 'Die Welt wird untergehen... ak yar qi\'lwhuk h\'iwn...', 28153),
(136277, 'deDE', 'Es ist zu spät! Ihr könnt unseren Fortschritt nicht aufhalten!', 'Es ist zu spät! Ihr könnt unseren Fortschritt nicht aufhalten!', 28153),
(136276, 'deDE', 'Ifis shuul qi\'nuq yyqzz...', '', 28153),
(136275, 'deDE', 'Brannon Sturmsang ist ein Schwächling. Die wahre Macht gehört dem Meer!', '', 28153),
(136274, 'deDE', 'Albers? Was ist los? Wo ist Lord Sturmsang?', '', 28153),
(136273, 'deDE', 'Ihr würdet es mir nicht glauben, Therold. Es ist ein Desaster.', '', 28153),
(136272, 'deDE', 'Schweigt! Fürstin Sylvanas wird nicht erfreut sein, wenn unsere Mission scheitert.', '', 28153),
(136271, 'deDE', 'Tucker! Ich hätte es wissen sollen. Immerhin hat er den Preis für seine Inkompetenz bezahlt.', '', 28153),
(136270, 'deDE', 'Das war Tucker. Die Sethrak haben ihn zuerst getötet.', '', 28153),
(136269, 'deDE', 'Wir hätten den Angriff kommen sehen müssen. Wer war als Wachposten eingeteilt?', '', 28153),
(136268, 'deDE', '', 'Ich glaube nicht, dass es unsere Schuld war, Boss. Wir wurden schließlich von einer Gruppe angegriffen, die nicht hätte dort sein dürfen.', 28153),
(136267, 'deDE', 'Sie wird es sein, wenn wir unsere Aufgabe erfüllen, Ingrid.', '', 28153),
(136266, 'deDE', '', 'Ist sie eigentlich jemals zufrieden, Boss?', 28153),
(136265, 'deDE', 'Also los, ausrücken! Wir haben noch viel zu erkunden und dürfen nicht noch einmal in einen Hinterhalt geraten.', '', 28153),
(136264, 'deDE', '<Aus dem Augenwinkel scheint es Euch, als würde der dunkle Fetisch sich bewegen. Wenn Ihr ihn anseht, tut sich jedoch nichts. Vielleicht hängt es mit dem Lichteinfall zusammen. Vielleicht auch nicht.>', '', 28153),
(136263, 'deDE', '', 'Ach, kommt schon!', 28153),
(136262, 'deDE', '...Diese Information ist geheim.', '', 28153),
(136261, 'deDE', '', 'Und WANN wurdet Ihr das erste Mal zweigeteilt?', 28153),
(136260, 'deDE', 'Es ist nicht das erste Mal, dass ich entzweigeteilt wurde. Aber hoffentlich das letzte Mal.', '', 28153),
(136259, 'deDE', 'Manchmal.', '', 28153),
(136258, 'deDE', '', 'Ach, Klodwig, wir sind Untote. Natürlich überleben wir es, zweigeteilt zu werden.', 28153),
(136257, 'deDE', 'Boss... Wie habt Ihr überlebt? Ich habe gesehen, wie Ihr entzweigeteilt wurdet.', '', 28153),
(136256, 'deDE', '', 'Viel Spaß mit dem Edelstein! Ich glaube, bei dem Ritual ist er... weitgehend intakt geblieben.', 28153),
(136255, 'deDE', 'Würmer, die Gesichter fressen? Also, ich bin hier raus!', 'Würmer, die Gesichter fressen? Also, ich bin hier raus!', 28153),
(136254, 'deDE', 'Wie konnte die Führungsebene das nur zulassen? Es reicht, wir müssen eine Gewerkschaft gründen.', 'Wie konnte die Führungsebene das nur zulassen? Es reicht, wir müssen eine Gewerkschaft gründen.', 28153),
(136253, 'deDE', 'Es ist sowieso Zeit für meine Pause. Ich bin dann mal weg.', 'Es ist sowieso Zeit für meine Pause. Ich bin dann mal weg.', 28153),
(136252, 'deDE', 'Ich werde weiter hinaufgehen. Sagt dem Trupp, dass er sich dort mit mir treffen soll.', '', 28153),
(136251, 'deDE', 'Also, an Monsterteile als Fracht bin ich ja gewohnt, aber lebende Monster? Ohne mich.', 'Also, an Monsterteile als Fracht bin ich ja gewohnt, aber lebende Monster? Ohne mich.', 28153),
(136250, 'deDE', 'Einfach das Teil reindrücken...', '', 28153),
(136249, 'deDE', '', 'Wir treffen uns auf der anderen Seite des Ladebereichs. Ich sehe mir mal an, was in der Stadt so vor sich geht.', 28153),
(136248, 'deDE', '', 'Was geht hier vor? Was... was IST das?', 28153),
(136243, 'deDE', '', '\"Nicht mit Schattenmagie experimentieren\", sagten sie.$B$B\"Ganz Azeroth ist in Gefahr, wenn Ihr so weitermacht\", haben sie mich gewarnt.$B$B\"Gebt mir meinen Arm zurück, Ihr könnt ihn nicht als Ersatzteil verwenden\", schrie er, als ich ihm den Arm herausdrehte.$B$BOh, tut mir leid. Ich schwelge gerade in Erinnerungen!', 28153),
(136242, 'deDE', 'Die Mehrheit ist dafür. Dann werden wir uns also ein schönes Feuerwerk ansehen.', '', 28153),
(136241, 'deDE', 'Dagegen.', '', 28153),
(136240, 'deDE', 'Dagegen.', '', 28153),
(136239, 'deDE', '...und wer ist dagegen?', '', 28153),
(136238, 'deDE', 'Dafür.', '', 28153),
(136237, 'deDE', 'Ich komm besser mit und sorg dafür, dass alles richtig läuft.', '', 28153),
(136236, 'deDE', '', 'Dafür.', 28153),
(136235, 'deDE', '', 'Dafür.', 28153),
(136234, 'deDE', 'Wir werden darüber abstimmen. Also, wer ist dafür, in einem gefährlichen Sumpf zu bleiben und jemanden dabei zuzusehen, wie er ein paar Schlangenleute mit einem Edelstein umbringt?', '', 28153),
(136233, 'deDE', '', 'Macht schon, Chadwick! Mit dem Himmelsruferedelstein, den $n für uns besorgt, können wir sie GRILLEN!', 28153),
(136232, 'deDE', 'Meine Magier und ich treffen Euch dann dort.', '', 28153),
(136231, 'deDE', 'Hätte nicht geglaubt, hier mal ein freundliches Gesicht zu sehen. Danke für die Rettung. Habt Ihr schon von Ingrids Plan gehört?', '', 28153),
(136230, 'deDE', 'Wir hätten es besser wissen müssen, dermaßen unvorbereitet an einen solch gefährlichen Ort zu kommen...', '', 28153),
(136229, 'deDE', '', 'Ich verschwinde, während Ihr die Sache hier erledigt... Und dann werden wir sehen, was dieser Edelstein ausrichten kann!', 28153),
(136228, 'deDE', 'Danke für die Rettung. Die Sethrak suchen nach einer Art Schattenmagie in Nazmir. Aber wozu nur?', '', 28153),
(136227, 'deDE', '', 'Das ist besser. Diese Sethrak suchen nach einer Art Magie, um die Macht eines ihrer Artefakte zu entfesseln.', 28153),
(136226, 'deDE', 'Habt Ihr Eure Lieferungen erhalten?', 'Habt Ihr Eure Lieferungen erhalten?', 28153),
(136225, 'deDE', 'AAH! HALTET MIR DIESES DING VOM LEIB!', '', 28153),
(136224, 'deDE', 'Bastard!', 'Bastard!', 28153),
(136223, 'deDE', 'Oh mein Gott! Er hat Ken\'nai umgebracht!', 'Oh mein Gott! Er hat Ken\'nai umgebracht!', 28153),
(136222, 'deDE', 'Das könnte ein Problem werden. Seid wachsam!', '', 28153),
(136221, 'deDE', 'Ich habe gerade eben eine Lieferung erhalten! Wollt Ihr mal schauen?', '', 28153),
(136220, 'deDE', '', 'Wisst Ihr, ich habe diesen Sturmsangjüngling schon seit Tagen nicht mehr gesehen. Ich wünschte, sie würden einer fähigeren Person die Leitung überlassen, aber das geht mich wohl nichts an.', 28153),
(136219, 'deDE', 'Habt Ihr etwas Ungewöhnliches bemerkt?', 'Habt Ihr etwas Ungewöhnliches bemerkt?', 28153),
(136218, 'deDE', 'Ich habe schon seit Tagen keine frischen Zutaten mehr erhalten! Wie soll ich ohne frische Dreschadonflossen meinen berühmten frittierten Dreschadon machen?', '', 28153),
(136215, 'deDE', 'Ich glaube, es ist an der Zeit, diesen Sethrak zu zeigen, was wahre Schmerzen sind.', '', 28153),
(136212, 'deDE', 'Passt! Gar nicht übel. Habt Ihr das vorher schon mal gemacht?', '', 28153),
(136211, 'deDE', 'AU! Nein, macht einfach weiter. Das tut immer weh. Nur ein bisschen drehen...', '', 28153),
(136210, 'deDE', 'Vorsicht mit meinen Beinen. Sie neigen zum Zappeln, wenn man sie entfernt.', '', 28153),
(136207, 'deDE', 'Hey! Gebt das zurück!', '', 28153),
(136206, 'deDE', '', 'Diese Sauriden müss\'n hier raus! Sofort!', 28153),
(136205, 'deDE', '', 'Was? Was wollt Ihr?', 28153),
(136200, 'deDE', 'Natürlich. Ich decke die hintere Flanke ab.', '', 28153),
(136199, 'deDE', 'Genn, Ihr müsst uns den Rücken freihalten. Es ist zu riskant, alle gleichzeitig durch den Seitenflügel zu schleusen. Sie hat dort sicher Fallen gelegt.', '', 28153),
(136198, 'deDE', '', 'Gehen wir.', 28153),
(136197, 'deDE', 'Geht alle auf Eure Position. Wir greifen auf mein Kommando an!', '', 28153),
(136196, 'deDE', 'Gute Idee. Sylvanas hatte kaum Zeit, sich auf diesen Angriff vorzubereiten, aber wir dürfen sie nicht unterschätzen.', '', 28153),
(136194, 'deDE', 'Ist Euch irgendetwas Merkwürdiges aufgefallen?', 'Ist Euch irgendetwas Merkwürdiges aufgefallen?', 28153),
(136193, 'deDE', 'Benötigt Ihr etwas?', '', 28153),
(136192, 'deDE', '', 'Ja, kann ich Euch helfen?', 28153),
(136191, 'deDE', 'Willkommen, willkommen! Darf ich Euch etwas zu Essen anbieten?', '', 28153),
(136187, 'deDE', 'Könntet Ihr mir zur Hand gehen? Oder vielmehr... zu meinem Bein? Mit meinen Händen ist ja alles in Ordnung.', '', 28153),
(136179, 'deDE', 'Es wird Zeit, dass wir dem Allianzabschaum die wahre Macht der Horde demonstrieren!', '', 28153),
(136178, 'deDE', 'Schon als Welpen werden unsere Wölfe trainiert und auf den Kampf vorbereitet.', '', 28153),
(136177, 'deDE', 'Keine Zeit für Plaudereien. Wir haben Arbeit zu erledigen.', '', 28153),
(136176, 'deDE', '', 'Ja? Was kann ich denn für Euch tun, Schätzchen?', 28153),
(136170, 'deDE', 'Jaina, dem Licht sei Dank, dass Ihr hier seid! Wir brauchen Euch in diesem Kampf.', '', 28153),
(136169, 'deDE', '', 'Im Leben war Kel\'vax unser Sohn. Aber jetzt is\' er nur ein weiteres Monster. Vernichtet ihn, damit wir seine Seele zu Bwonsamdi schick\'n könn\'n.', 28153),
(136167, 'deDE', '', 'Kel\'vax will alles beschmutz\'n, was mit Bwonsamdi zu tun hat. Findet die Phylakterien, damit wir diese Schande beend\'n könn\'.', 28153),
(136166, 'deDE', '', 'Helft, die alte heilige Stätte von Bwonsamdi zu befrei\'n. Un\' dabei war die mal so prächtig...', 28153),
(136165, 'deDE', '', 'Wart mal... da is jemand, da drüben... und das is\' kein Bluttroll! He, hier drüben!', 28153),
(136164, 'deDE', '', 'Meine Geschöpfe... können nicht besiegt werden...', 28153),
(136163, 'deDE', '', 'Diese Seelen gehören mir!', 28153),
(136162, 'deDE', 'Wenn wir so weitermach\'n, wird das hier nie fertig für Bwonsamdi!', '', 28153),
(136161, 'deDE', '', 'Ah, da seid Ihr ja. Ich hab grad Mutumbas Bericht gehört. Scheint, als hättet Ihr zwei einiges erlebt.', 28153),
(136160, 'deDE', '', 'Als ich noch lebte, kümmerte ich mich um das Wohl dieses Waldes. Ich lasse mich von diesen Hexen nicht benutzen!', 28153),
(136159, 'deDE', 'So... wunderschön...', '', 28153),
(136156, 'deDE', '', 'Vorsichtig. Ihr habt tiefe Wund\'n.', 28153),
(136153, 'deDE', 'Wir sind bereit zum Aufbruch.', 'Wir sind bereit zum Aufbruch.', 28153),
(136152, 'deDE', '', 'Es ist nie sicher, allein durch diese Dünen zu reisen.', 28153),
(136151, 'deDE', 'Zu Lebzeiten schützte ich dieses Land.\n\nAls Toter gelobe ich, dasselbe zu tun.', '', 28153),
(136150, 'deDE', '', 'Wir seh\'n uns auf der Andren Seite.', 28153),
(136149, 'deDE', 'Bwonsamdis Wille soll gescheh\'n. Es wird Zeit, dass wir alle Ruhe find\'n.', '', 28153),
(136148, 'deDE', 'Nein! Ich kann Bwonsamdi nich\' sehen! Ich will nich\'... Bitte, hört auf!', '', 28153),
(136147, 'deDE', '', 'Dein Schicksal liegt jetzt in Bwonsamdis Händen. Hoff ma\' besser, er gewährt dir mehr Gnade als wir.', 28153),
(136146, 'deDE', 'Nein! Mutter, tu etwas!', '', 28153),
(136145, 'deDE', 'Jetzt is\' es zu spät, mein Sohn. Du hast dich entschloss\'n, Bwonsamdi zu verrat\'n. Jetzt wirst du dafür bezahl\'n.', '', 28153),
(136144, 'deDE', 'Mutter... Vater... Es tut mir leid. Bitte vergebt mir un\' legt bei Bwonsamdi ein gutes Wort für mich ein!', '', 28153),
(136141, 'deDE', 'Ich kümmere mich um die Toten.$b$b<Allen zuckt mit den Schultern.>$b$bDavon kann man auch leben.', '', 28153),
(136140, 'deDE', '', 'Törichter Loa! Hier is\' nur der Tod zu find\'n!', 28153),
(136116, 'deDE', 'Kommt, lasst uns zum Bau zurückkehren.', '', 28153),
(136115, 'deDE', 'Haha! Wir haben unsere Feinde in die Flucht geschlagen.', '', 28153),
(136114, 'deDE', 'Bwonsamdi! Nein... G\'huun hat versproch\'n, dass ich niemals besiegt werd\'n kann!', '', 28153),
(136113, 'deDE', 'Seid nicht so pessimistisch! Meiner Erfahrung nach sind sagenumrankte Kreaturen von Nahem nie so fürchterlich, wie die Geschichten es glauben machen wollen.', '', 28153),
(136112, 'deDE', 'Ich hab \'n schlechtes Gefühl dabei... Seid vorsichtig, $n!', '', 28153),
(136111, 'deDE', 'Gut! Ihr Anführer ist tot und diese Diener werden ihm bald folgen. Laben wir uns an ihnen.', '', 28153),
(136110, 'deDE', 'PAH! Fluch über Euch und Fluch über Bwonsamdi! Meine Seele KRIEGT ER NICH\'!', '', 28153),
(136109, 'deDE', 'Eure Geister sin\' nur Futter für den Blutgott!', '', 28153),
(136108, 'deDE', 'Kel\'vax is wieder verwundbar... jetz\' liegt\'s an Euch!', '', 28153),
(136107, 'deDE', 'Was macht... nich\' möglich! Keiner legt mir Kett\'n an! Nich\' ihr, nich\' Bwonsamdi!', '', 28153),
(136106, 'deDE', 'Zeit für Bwonsamdis Urteil! Wir haben die Phylakterien und $n hat mir die Knoch\'n besorgt, um dein\' Voodoo zu bind\'n!', '', 28153),
(136105, 'deDE', 'Mutter, Vater...', '', 28153),
(136104, 'deDE', '', 'Kel\'vax, genug jetzt!', 28153),
(136103, 'deDE', 'Ihr werdet gemeinsam mit diesen Dienern Bwonsamdis bis in alle Ewigkeit Qualen erleid\'n!', '', 28153),
(136102, 'deDE', 'ES REICHT! Der Blutgott fordert Eure Vernichtung... und ich werd\' sie vollstreck\'n. Bwonsamdi sei verdammt!', '', 28153),
(136101, 'deDE', 'Es is\' jetzt egal. Ich hab Aufstieg un\' Fall dieser Zivilisation geseh\'n... Ihr werdet mich nich\' aufhalt\'n!', '', 28153),
(136100, 'deDE', 'Was? Wo sin\' meine Zombies... mein Skelette? Was passiert hier?', '', 28153),
(136099, 'deDE', 'Törichte Sterbliche... Meine Armeen werd\'n Euch zerstör\'n. Ihr werdet alle meine Sklaven sein!', '', 28153),
(136096, 'deDE', 'He! Ich kenne Euch nicht. Seid Ihr hier, um zu helfen, oder nicht?', '', 28153),
(136095, 'deDE', 'Genug von diesem Mummenschanz!', 'Genug von diesem Mummenschanz!', 28153),
(136094, 'deDE', '', 'Steckt Euren Riechkolben besser nicht in Aschenwindgeschäfte. Denen sitzt der Säbel locker.', 28153),
(136093, 'deDE', 'Nicht schlecht für \'nen räudigen blinden Passagier. Hätt ich Euch gefunden, bevor wir aufgelaufen sind, wären das jetzt wohl EURE Gedärme an meinem Stiefel.', 'Nicht schlecht für \'nen räudigen blinden Passagier. Hätt ich Euch gefunden, bevor wir aufgelaufen sind, wären das jetzt wohl EURE Gedärme an meinem Stiefel.', 28153),
(136092, 'deDE', 'Kommt her, ihr runzligen Hexen! Ich mach mir \'ne Flagge aus Eurer Pelle!', 'Kommt her, ihr runzligen Hexen! Ich mach mir \'ne Flagge aus Eurer Pelle!', 28153),
(136086, 'deDE', '', 'Mein Vater hat einst mit eiserner Hand regiert und niemand hat sich getraut, die Gesetze zu brech\'n. Aber er war auch gütig und großherzig und hat den Leuten in Not geholf\'n. Dafür hat das Volk ihn geliebt.$b$bUnd jetzt ist seine eiserne Hand vergess\'n. Jene, denen er traut, vergift\'n ihn mit ihren Lügen, während sie ihre Ränke schmied\'n.$b$bIch weiß nich\', was sie planen, aber ich weiß, dass unser Volk es sich nich\' leist\'n kann, einfach abzuwart\'n und zuzuschau\'n.', 28153),
(136085, 'deDE', '', 'Meine Kinder, tötet diese Kreatur!', 28153),
(136072, 'deDE', 'Die Blutwelle wird ausm Norden über Euch hinwegroll\'n un\' Euch in die Knie zwing\'n.', 'Die Blutwelle wird ausm Norden über Euch hinwegroll\'n un\' Euch in die Knie zwing\'n.', 28153),
(136071, 'deDE', 'Bald werd\'n sie aus Nazmir komm\'n. Dann seht Ihr alles, was wir geseh\'n ham.', 'Bald werd\'n sie aus Nazmir komm\'n. Dann seht Ihr alles, was wir geseh\'n ham.', 28153),
(136070, 'deDE', 'Nein! Nein! Ihr könnt uns nich\' aufhalt\'n. Er hat versprochen, dass Ihr uns nich\' aufhalt\'n könnt.', 'Nein! Nein! Ihr könnt uns nich\' aufhalt\'n. Er hat versprochen, dass Ihr uns nich\' aufhalt\'n könnt.', 28153),
(136069, 'deDE', 'Heldenblut bringt \'nen guten Preis.', 'Heldenblut bringt \'nen guten Preis.', 28153),
(136068, 'deDE', 'Ihr könnt mich nich\' bei den Wachen verpetz\'n, wenn Ihr tot seid.', 'Ihr könnt mich nich\' bei den Wachen verpetz\'n, wenn Ihr tot seid.', 28153),
(136067, 'deDE', 'Ihr wagt es, uns aufhalt\'n zu woll\'n?', 'Ihr wagt es, uns aufhalt\'n zu woll\'n?', 28153),
(136039, 'deDE', 'Was ist das? Unsere Gegner sind hinter uns! Wenn Ihr mir nicht beisteht, werde ich ihnen allein gegenübertreten.', '', 28153),
(136015, 'deDE', 'Die Fracht im Fass scheint aus unbedenklichen Allerweltsmonsterteilen zu bestehen.', '', 28153),
(136003, 'deDE', 'Es wird Zeit, dem ein Ende zu setzen. Trefft mich am Flussufer.', '', 28153),
(135928, 'deDE', '', 'Diese Untoten sin\' \'ne Beleidigung für Bwonsamdi. Wir können nich\' ruh\'n, bevor wir das nich\' in Ordnung gebracht hab\'n.', 28153),
(135927, 'deDE', 'Der Wille von Bwonsamdi muss gescheh\'n. Wir können nich\' ruh\'n, bis das nich\' erfüllt is\'.', '', 28153),
(135904, 'deDE', 'Kommt zu meinem Bau. Es gibt viel, das getan werden muss.', '', 28153),
(135903, 'deDE', '', 'Nein! Vergebt mir, Krag\'wa.', 28153),
(135901, 'deDE', 'Seid Ihr so stolz, dass Ihr in Frage stellt, wem ich meine Gunst erweise?', '', 28153),
(135900, 'deDE', '', 'Krag\'wa! Es is\' eine Ehre, die... ich nich\' verdiene. Ich konnt die Naga nich\' aufhalt\'n.', 28153),
(135898, 'deDE', 'Narez. Ihr habt Euch als würdig erwiesen, mein Anhänger zu werden.', '', 28153),
(135875, 'deDE', '', 'Ich bleib hier, um die Naga zu beobacht\'n un\' um Krag\'wa zu zeig\'n, dass ich würdig bin. Bis dann.', 28153),
(135874, 'deDE', 'Oh nein, das werdet Ihr nich\', Fremdling! Ihr werdet mir meine Geschäfte nich\' kaputt mach\'n!', '', 28153),
(135869, 'deDE', 'Ich komm mit.', 'Ich komm mit.', 28153),
(135868, 'deDE', 'Neu hier? Wer bist du?$b$bHerrn Nett wird\'s nich\' gefall\'n, dass du nich\' zuerst zu ihm gegang\'n bist. Du kommst besser mit mir.', '', 28153),
(135865, 'deDE', '', 'Und sie haben mich einen Dummkopf genannt, weil ich eine so \"überspezialisierte\" Schriftrolle behalten habe. Pah!', 28153),
(135861, 'deDE', '%s erliegt seinen Verletzungen.', '%s erliegt seinen Verletzungen.', 28153),
(135843, 'deDE', '', 'Die Rachenscheusale... Wollt\' nur noch eins... noch eins mach\'n...', 28153),
(135842, 'deDE', '', 'Ihr werdet den Totems viel Kraft geb\'n!', 28153),
(135795, 'deDE', '<Der riesige Frosch liegt tot im Schlamm.>', '', 28153),
(135777, 'deDE', 'Weg hier!', '', 28153),
(135776, 'deDE', 'Aaaah!', '', 28153),
(135774, 'deDE', 'Nichts wie weg!', '', 28153),
(135772, 'deDE', 'Iep!', '', 28153),
(135771, 'deDE', 'Das sag ich Herrn Nett!', '', 28153),
(135770, 'deDE', 'Das hab ich gebraucht!', '', 28153),
(135769, 'deDE', 'Aah! Fremden trau ich nich\'!', '', 28153),
(135768, 'deDE', 'Das wird Herrn Nett nich\' gefall\'n!', '', 28153),
(135741, 'deDE', 'Was?', 'Was?', 28153),
(135740, 'deDE', 'Was hat $gder:die:r; $r zum Hexendoktor gesagt?', '', 28153),
(135733, 'deDE', 'Er lag falsch. Klar, es hat \'n paar Schäden gegeb\'n, aber Zul is\' mit unsrer Flotte gefloh\'n un\' hat \'n paar Kriege angezettelt. Diejenigen von uns, die hiergeblieb\'n sin\', ham durchgehalt\'n. Wir ham alles wiederaufgebaut. Denn DAS bedeutet es, \'n wahrer Zandalari zu sein.', '', 28153),
(135732, 'deDE', 'Zuls Visionen, pah! Hatter Euch erzählt, wie er mal vorhergesagt hat, dass Zandalar in die Wellen sink\'n würde?', '', 28153),
(135726, 'deDE', 'Ich beaufsichtige jeden Monat Hunderte Schiffe, die hier anland\'n und wieder auslauf\'n, und ich stell sicher, dass jedes von ihnen pünktlich ist.$b$bFür Trödelei hab ich keine Zeit, also macht schnell.', '', 28153),
(135719, 'deDE', '', 'Fahrt fort.', 28153),
(135701, 'deDE', 'Es gibt viele Geschichten über Xibala, aber ich weiß nich\', welche davon wahr sin\'. Die Ahnen hab\'n ihn gefürchtet, so viel is\' sicher.\n\nEs heißt, dass er dafür verantwortlich war, dass die Körper von Leuten vor eitrig\'n Entzündungen aufgedunsen war\'n.\n\nOder dass alle, die ihn angeseh\'n hab\'n, zu lebenden Skeletten geword\'n sind.\n\nOder dass er in den Schatten gelauert hat und Leute verschlang, während sie geschlaf\'n hab\'n.\n\nOder dass er in der Nähe von Straßen gewartet hat und Leute Blut hust\'n ließ.\n\nSogar die mutigsten Krieger wiss\'n, dass es besser is\', diesen Ort zu meid\'n.', '', 28153),
(135699, 'deDE', 'Wer war Xibala?', 'Wer war Xibala?', 28153),
(135694, 'deDE', '', 'Ich g-glaube, ich kann mich in die Höhle sch-schleichen, in der meine Schwester ist. Wir treffen uns dort.', 28153),
(135683, 'deDE', 'Was führt Euch her, $C?', '', 28153),
(135680, 'deDE', 'Wir sind bereit, die Prüfungen zu beginnen.', 'Wir sind bereit, die Prüfungen zu beginnen.', 28153),
(135679, 'deDE', 'Eure Hinhaltetaktik wird Euch nichts nützen. Wir werden das Geheimnis um Fräulein Kronsteig schon bald lüften!', '', 28153),
(135674, 'deDE', 'Unsere Windreiter wurden vielleicht abgeschossen, doch die wahre Macht liegt im festen Griff um eine Axt!', '', 28153),
(135673, 'deDE', 'Egal ob mit oder ohne Artillerie, unsere Kampfkraft ist unübertroffen!', '', 28153),
(135670, 'deDE', 'Meine Klingen werden Euer Fleisch durchdringen!', '', 28153),
(135638, 'deDE', 'Diese Monster haben meinen letzten Jünger getötet. Ich werde den Zorn von Zehntausend Jahren über sie bringen!', '', 28153),
(135610, 'deDE', '', 'Damit kommt Ihr zu den unteren Gemächern. Prinzessin Talanji wartet da. Passt auf, dass Ihr nich\' fallt.', 28153),
(135604, 'deDE', '', 'Folgt mir. Ich kenn \'nen einfachen Weg nach unten.', 28153),
(135586, 'deDE', '', 'Kommt mich besuchen, wenn sich die Gelegenheit ergibt. Ich kann es kaum erwarten, all das, was ich aus diesen Inschriften gelernt habe, mit Euch zu teilen!', 28153),
(135579, 'deDE', '', 'Macht Euch um mich keine Sorgen... Ich schaffe es allein zurück zur Arena.', 28153),
(135578, 'deDE', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma beginnt, |cFFFF0404|Hspell:249924|h[Seelenzerfetzer]|h|r auf |cFFFF0000$n|r zu wirken!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma beginnt, |cFFFF0404|Hspell:249924|h[Seelenzerfetzer]|h|r auf $n zu wirken!', 28153),
(135577, 'deDE', 'Ich spüre, wie meine Kraft zurückkehrt... Das Gegengift scheint zu wirken.', '', 28153),
(135576, 'deDE', 'Ich bin nich\' sicher, wie viel Zeit Julwaba noch bleibt... das Gegengift is\' ihre einzige Hoffnung.', '', 28153),
(135574, 'deDE', 'Julwaba und Taz\'jin werden seit Tagen vermisst. Langsam beginn\' ich, mir Sorg\'n zu machen...', '', 28153),
(135565, 'deDE', 'Geht, schnell! Die Naga müssen sterb\'n, um Krag\'was Anhänger zu rett\'n.', '', 28153),
(135555, 'deDE', '', 'Möge Krag\'wa Euch segn\'n. Zeigt Zaldraxia, dass sie sich mit\'m falschen Loa angelegt hat.', 28153),
(135539, 'deDE', 'Die Naga müssen aufgehalten werden. Kümmert Euch nicht um mich.', '', 28153),
(135511, 'deDE', 'Bringt mich zu König Rastakhan.', 'Bringt mich zu König Rastakhan.', 28153),
(135496, 'deDE', 'Unsere Stadt wird angegriffen!', 'Unsere Stadt wird angegriffen!', 28153),
(135492, 'deDE', 'Ich schicke ein paar Arbeiter, die für Euch das Flöz abbauen.', '', 28153),
(135486, 'deDE', 'Die Mine wird angegriffen!', 'Die Mine wird angegriffen!', 28153),
(135469, 'deDE', '', 'Was gibt es, $C?', 28153),
(135466, 'deDE', 'Diese nutzlose Schriftrolle... Kannst du nicht einfach funktionieren und SHOAK FINDEN?', '', 28153),
(135465, 'deDE', 'Los jetzt! Du sollst Shoak finden und NICHT MIT DIESEM TOTEM HERUMALBERN!', '', 28153),
(135464, 'deDE', 'Warum FUNKTIONIERT das nicht?! Finde doch einfach Shoak!', '', 28153),
(135457, 'deDE', '', 'Es könnte Kollateralschaden entstehen, aber die Teile können wir bestimmt am Ende wieder zusammenfügen. Vielleicht würden wir dazu einige weitere Forschungsassistenten benötigen...', 28153),
(135456, 'deDE', 'Die Geister werd\'n darüber sicher nich\' erfreut sein. Sagt später nich\', ich hätt Euch nich\' gewarnt!', '', 28153),
(135455, 'deDE', 'He! Werft besser keine Bomb\'n auf die Knoch\'n!', '', 28153),
(135446, 'deDE', '', 'Sterbt, Eindringling!', 28153),
(135445, 'deDE', '', 'Ihr werdet uns dienen!', 28153),
(135444, 'deDE', '', 'Nein... Ich darf nicht scheitern!', 28153),
(135443, 'deDE', '', 'Nein... mir wurde Macht... versprochen...', 28153),
(135442, 'deDE', '', 'Ihr werdet um Euren Tod betteln, bevor ich mit Euch fertig bin!', 28153),
(135441, 'deDE', '', 'Auch Ihr werdet dienen!', 28153),
(135440, 'deDE', '', 'Ihr könnt mich nicht aufhalten!', 28153),
(135439, 'deDE', 'Ich werde der Meisterin Euer Herz bringen!', '', 28153),
(135432, 'deDE', 'Die Allianz hat ein Azeritflöz eingenommen!', '', 28153),
(135431, 'deDE', '$n hat ein Azeritflöz verteidigt!', '', 28153),
(135430, 'deDE', 'Die Horde hat ein Azeritflöz eingenommen!', '', 28153),
(135429, 'deDE', '$n hat ein Azeritflöz angegriffen!', '', 28153),
(135405, 'deDE', 'Nun gut. Ich werd den König aber um den Kopf dieser Kreatur bitt\'n.', '', 28153),
(135400, 'deDE', 'Genug, General! Ihr werdet jetzt beiseitetret\'n. Dieser Lakai der Horde hat die Herausforderungen von zwei Stämmen bestand\'n. Unser Gesetz fordert freies Geleit.', '', 28153),
(135399, 'deDE', '', '', 28153),
(135388, 'deDE', 'Hab gehört, dass der König den Thron seit dem Tod seiner Frau nich\' mehr verlass\'n hab\'n soll.', 'Hab gehört, dass der König den Thron seit dem Tod seiner Frau nich\' mehr verlass\'n hab\'n soll.', 28153),
(135387, 'deDE', 'Die Horde? Hier in Zuldazar? Das is\' schlimm, das is\' echt schlimm.', 'Die Horde? Hier in Zuldazar? Das is\' schlimm, das is\' echt schlimm.', 28153),
(135386, 'deDE', 'Als Zul ging, hat er so viele von uns mitgenomm\'n. Und jetzt heißt es, die Bluttrolle greif\'n die nördliche Grenze an.', 'Als Zul ging, hat er so viele von uns mitgenomm\'n. Und jetzt heißt es, die Bluttrolle greif\'n die nördliche Grenze an.', 28153),
(135385, 'deDE', '', 'Argh... Es tut mir leid, Festländer, aber ich muss Euch um einen weiteren Gefallen bitten.', 28153),
(135384, 'deDE', 'Dann müssen wir wohl warten.', '', 28153),
(135383, 'deDE', '', 'Das könnte eine Ewigkeit dauern!', 28153),
(135382, 'deDE', 'Ihr werdet erst freigesprochen, wenn wir die Wahrheit erfahren haben über das, was unserem Dorf geschehen ist!', '', 28153),
(135381, 'deDE', '', 'Was?! Nach allem, was ich durchgemacht habe?!', 28153),
(135380, 'deDE', 'Ihr habt mich nicht überzeugt. Das erklärt die Vorkommnisse in Schnitztal nicht.', '', 28153),
(135379, 'deDE', 'Ruhe! Ich allein fälle hier das Urteil!', '', 28153),
(135378, 'deDE', 'Vielleicht ist sie doch keine Hexe? Aber was ist dann mit unserem Dorf los?', 'Vielleicht ist sie doch keine Hexe? Aber was ist dann mit unserem Dorf los?', 28153),
(135377, 'deDE', 'Ihr ist schlecht geworden! Wie kann das sein!', '', 28153),
(135376, 'deDE', '', 'Ohhh... Mir geht\'s nicht so...', 28153),
(135375, 'deDE', '', 'Das bin ich. Das Gift, Festländer.', 28153),
(135374, 'deDE', 'Seid Ihr bereit, uns das Gegenteil zu beweisen, Fräulein Kronsteig?', '', 28153),
(135373, 'deDE', 'Wie man weiß, beziehen Hexen ihre Kraft nicht aus Speis und Trank, sondern aus den Seelen, die sie ihren Opfern aussaugen. Ihre Organe sind völlig leer.', '', 28153),
(135372, 'deDE', 'Interessant, aber nicht stichhaltig. Kommen wir zur letzten Prüfung... der Organprobe.', '', 28153),
(135371, 'deDE', 'Die Fliegen meiden sie gar nicht. Sie beißen sogar noch mehr zu als sonst!', 'Die Fliegen meiden sie gar nicht. Sie beißen sogar noch mehr zu als sonst!', 28153),
(135370, 'deDE', '', 'Aua! Uuh! Oh, das tut weh!', 28153),
(135369, 'deDE', '', 'Keine Sorge, ein paar Mückenstiche halte ich schon aus.', 28153),
(135368, 'deDE', 'Lasst die Fliegen frei und seht, wie sie vor ihrem verhexten Fleisch fliehen!', '', 28153),
(135367, 'deDE', 'Die zweite Prüfung ist die Stichprobe. Es ist allseits bekannt, dass auch die hungrigste Blutfliege das üble Blut der Hexen meidet.', '', 28153),
(135366, 'deDE', 'Ruhe, Ruhe. Es könnte sich immer noch um eine Täuschung handeln. Wir fahren mit dem Prozess fort.', '', 28153),
(135365, 'deDE', 'Sie weint! Aber Hexen können doch gar nicht weinen!', 'Sie weint! Aber Hexen können doch gar nicht weinen!', 28153),
(135364, 'deDE', '', 'Nun, Festländer. Zeigt es ihnen.', 28153),
(135363, 'deDE', 'Kann die Angeklagte überhaupt weinen? Zeigt es uns, auf dass wir unser Urteil fällen.', '', 28153),
(135362, 'deDE', 'Die erste Prüfung ist die Tränenprobe. Fräulein Kronsteig hat während des gesamten Prozesses nicht eine Träne vergossen.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135361, 'deDE', 'Sie will, dass dieser Festländer die Prüfungen durchführt. Eine ungewöhnliche Wahl... die ich als Zeichen unserer lauteren Absichten aber erlaube.', '', 28153),
(135360, 'deDE', 'Wie es Brauch ist, hat Fräulein Kronsteig die Prüfungen bestimmt, durch die sie von der Anklage der Hexerei freigesprochen zu werden hofft.', '', 28153),
(135359, 'deDE', 'Endlich! Der Prozess kann beginnen!', '', 28153),
(135358, 'deDE', 'Seid Ihr so weit? Mir reißt bald der Geduldsfaden!', '', 28153),
(135357, 'deDE', 'Vor einiger Zeit habe ich eine Geschichte von einer Hexe gehört, die in den Sümpfen lebte. Den Bürgern fiel auf, dass die Hexe nicht von den Blutfliegen belästigt wurde, und so wurde sie entlarvt.\n\nAlle wurden von den Fliegen gebissen, nur die Hexe nicht!\n\nMan sagt, dass das Blut einer Hexe so faulig ist, dass nicht einmal Blutfliegen es haben wollen!', '', 28153),
(135356, 'deDE', 'Ich habe zuvor noch nie eine echte Hexe gesehen. Ist das nicht aufregend?!', '', 28153),
(135355, 'deDE', 'Früher haben wir sie einfach mit Gewichten beschwert und im Fluss versenkt! Wenn sie wieder aufgetaucht sind, dann wussten wir, dass sie einen Pakt mit dem Bösen eingegangen waren. Danach haben sie Bekanntschaft mit unserem Galgen gemacht.\n\nDas ist der einzige Weg, wie eine Hexe ihre Unschuld beweisen kann, wenn Ihr mich fragt!', '', 28153),
(135354, 'deDE', 'Der Fluch der Hexe hat mir meinen Sohn genommen! Heute wird sie dafür bezahlen!', '', 28153),
(135353, 'deDE', '', 'Ich... bin mir nicht sicher.\n\nMan sagt, dass sich Hexen niemals übergeben können, weil ihre Mägen fortwährend von den bösen Geistern, die darin wohnen, geleert werden.\n\nAllerdings bin ich mir nicht sicher, wie wir das beweisen können...', 28153),
(135352, 'deDE', '', 'Der Fluch über unserem Dorf muss endlich gebrochen werden.\n\nIch bin mir sicher, dass wir nur die Hexe töten müssen, die uns verflucht hat, und alles ist vorbei!', 28153),
(135351, 'deDE', 'Ich habe gehört, dass die Haut von Hexen nicht verbrennen kann, deswegen werden sie bei uns auch gehängt, wenn sie für schuldig befunden werden!\n\nWenn Ihr mich überzeugen wollt, dann zündet sie doch an!', '', 28153),
(135350, 'deDE', 'Diese Frau hat das Böse in unser Dorf gebracht. Dafür muss sie bezahlen!', '', 28153),
(135349, 'deDE', '', 'Meine Mama hat mir immer gesagt, dass Hexen niemals weinen können, egal wie traurig sie sind.\n\nFräulein Kronsteig hat keine einzige Träne vergossen, als sie gehört hat, dass sie vor Gericht kommen soll. Sie muss eine Hexe sein!', 28153),
(135348, 'deDE', 'Wie kann man beweisen, dass jemand keine Hexe ist?', 'Wie kann man beweisen, dass jemand keine Hexe ist?', 28153),
(135347, 'deDE', '', 'Dieser Prozess ist schrecklich, aber die Gerechtigkeit muss in Schnitztal obsiegen!', 28153),
(135346, 'deDE', 'Hat Fräulein Kronsteig entschieden, wie sie geprüft werden möchte?', '', 28153),
(135345, 'deDE', 'Endlich! Lasst uns fortfahren.', '', 28153),
(135344, 'deDE', 'Wachtmeister! Fahrt fort mit diesem... Prozess.', '', 28153),
(135343, 'deDE', 'Ihr habt uns etwas Zeit verschafft, Festländer. Ich will nur hoffen, dass diese Dörfler Fräulein Kronsteig wirklich nichts Böses wollen.', '', 28153),
(135342, 'deDE', '', 'Retten? Und wollt Ihr auch die Dorfbewohner töten, um mich zu retten?\n\nWenn Ihr mich wirklich unterstützen wollt, dann helft mir mit dem Marschall.\n\nIhre Anschuldigungen sind zwar falsch, aber es sind immer noch meine Leute. Ich dulde nicht, dass ihnen Schaden zugefügt wird, nur um mir Unannehmlichkeiten zu ersparen. Sie sollen ihren Prozess haben, dann beweise ich ihnen meine Unschuld.\n\nIch befürchte allerdings, dass der Marschall selbst nachhelfen will, und ich sitze hier leider fest. Versucht, ihn zu überzeugen, den Prozess seinen Gang nehmen zu lassen.', 28153),
(135341, 'deDE', 'Ich bin hier, um Euch zu retten.', 'Ich bin hier, um Euch zu retten.', 28153),
(135340, 'deDE', '', 'Es tut mir leid, dass Ihr zwischen die Fronten geraten seid. Das sind wirklich gute Menschen hier, aber die Zeiten sind grausam.', 28153),
(135339, 'deDE', '', 'Nichts dergleichen werdet Ihr tun, Marschall! Legt die Waffen nieder!', 28153),
(135338, 'deDE', 'Wir haben keine Zeit für Diskussionen. Tretet zurück oder wir befreien sie mit Gewalt!', '', 28153),
(135337, 'deDE', 'Fräulein Kronsteig ist der Hexerei angeklagt! Ohne Freisprache von dieser Straftat werden wir sie nicht entlassen!', '', 28153),
(135336, 'deDE', 'Wachtmeister Leumder! Ich befehle Euch, mir Fräulein Kronsteig auszuhändigen!', '', 28153),
(135335, 'deDE', 'Noch mehr Unterbrechungen!? Was ist es diesmal?', '', 28153),
(135334, 'deDE', 'Da! Reiter, aus dem Wald!', 'Da! Reiter, aus dem Wald!', 28153),
(135333, 'deDE', 'Wie ich es hasse, unterbrochen zu werden! Was wollt Ihr hier, Festländer?', '', 28153),
(135332, 'deDE', 'Wachtmeister! Da kommt jemand!', 'Wachtmeister! Da kommt jemand!', 28153),
(135331, 'deDE', 'Ihr steht vor Gericht...', '', 28153),
(135330, 'deDE', 'Luzilla Kronsteig! Ihr werdet beschuldigt, Hexerei praktiziert und das Dorf Schnitztal mit einem Fluch belegt zu haben.', '', 28153),
(135301, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Kriegstrike herbeirufen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Kriegstrike herbeirufen', 28153),
(135286, 'deDE', '', 'Es war dumm von mir, allein uralte Relikte such\'n zu geh\'n...', 28153),
(135281, 'deDE', 'Was... <hicks!> Was glotzt Ihr\'n so, Mann?', '', 28153),
(135272, 'deDE', 'Besprechen wir, was wir tun können, um die Bluttrolle zu bekämpfen.', 'Besprechen wir, was wir tun können, um die Bluttrolle zu bekämpfen.', 28153),
(135265, 'deDE', '', 'Da ist noch einer... hier!', 28153),
(135263, 'deDE', '', 'Da! Torga, der Schildkröt\'nloa. Er is\' gutherzig un\' weise. Ich weiß, er wird uns helf\'n. Seh\'n wir, wer noch da is\'...', 28153),
(135261, 'deDE', '', 'Nazmir is\'n verfluchter Ort... doch halt\'n sich dort Loa auf. Zurück... Ich find raus, wer von den\' hier is\'.', 28153),
(135226, 'deDE', 'Danke! Ich war in einem Alptraum gefangen!', '', 28153),
(135225, 'deDE', 'Ihr müsst sie aufhalten!', '', 28153),
(135224, 'deDE', 'Was geschieht hier?', '', 28153),
(135221, 'deDE', 'Ich werde Euch töten!', '', 28153),
(135220, 'deDE', 'Wie könnt Ihr es wagen, die Arbeit der Meisterin zu stören?!', '', 28153),
(135209, 'deDE', '', 'Mal seh\'n, was noch da draußen ist...', 28153),
(135190, 'deDE', 'Hier, Pinkie! Ich hab \'nen feinen Leckerbissen für dich!', 'Hier, Pinkie! Ich hab \'nen feinen Leckerbissen für dich!', 28153),
(135189, 'deDE', 'Die Allianz hat die Mine erobert.', 'Die Allianz hat die Mine erobert.', 28153),
(135188, 'deDE', 'Na ja, das lief \'n bisschen verrückt ab. Aber Ende gut, alles gut, oder nich\'? Ha ha ha!', '', 28153),
(135187, 'deDE', 'Wer diesssen Mast hält... befehligt meine Besssatzung...', '', 28153),
(135185, 'deDE', 'Einige freu\'n sich auf die Rückkehr der Flotte. Aber ich kann mich gut an die Trolle erinnern, die mit Zul gesegelt sin\'. \'n verdammt wütender Haufen.', 'Einige freu\'n sich auf die Rückkehr der Flotte. Aber ich kann mich gut an die Trolle erinnern, die mit Zul gesegelt sin\'. \'n verdammt wütender Haufen.', 28153),
(135184, 'deDE', 'Is\' es wahr, dass Zul zurück nach Zandalar geschleift wird? Ich bin sicher, das passt ihm überhaupt nich\'.', 'Is\' es wahr, dass Zul zurück nach Zandalar geschleift wird? Ich bin sicher, das passt ihm überhaupt nich\'.', 28153),
(135179, 'deDE', 'Ich bin kein Freund der Horde, aber Ihr habt \'ne Menge von diesem Allianzdreck getötet. Kann also nich\' so schlecht sein.', 'Ich bin keine Freundin der Horde, aber Ihr habt \'ne Menge von diesem Allianzdreck getötet. Kann also nich\' so schlecht sein.', 28153),
(135178, 'deDE', 'Habt Ihr wirklich an der Seite von Prinzessin Talanji gekämpft? Hat sie Gesichter geschmolz\'n? Hat sie Seelen zerriss\'n? Wie war\'n ihre Verhexungen?', 'Habt Ihr wirklich an der Seite von Prinzessin Talanji gekämpft? Hat sie Gesichter geschmolz\'n? Hat sie Seelen zerriss\'n? Wie war\'n ihre Verhexungen?', 28153),
(135177, 'deDE', 'Es heißt, Ihr folgt \'ner untoten Anführerin. Dem alten Bwonsamdi wird das nich\' gefall\'n.', 'Es heißt, Ihr folgt \'ner untoten Anführerin. Dem alten Bwonsamdi wird das nich\' gefall\'n.', 28153),
(135176, 'deDE', 'Ihr seid von der Horde? Is\' es wahr, dass Vol\'jin tot is\'?', 'Ihr seid von der Horde? Is\' es wahr, dass Vol\'jin tot is\'?', 28153),
(135175, 'deDE', 'Den Loa sei Dank für die Rückkehr von Prinzessin Talanji. Sie war nich\' lang fort, doch ihre Gegner braucht\'n nich\' viel Zeit.', 'Den Loa sei Dank für die Rückkehr von Prinzessin Talanji. Sie war nich\' lang fort, doch ihre Gegner braucht\'n nich\' viel Zeit.', 28153),
(135174, 'deDE', 'Zuerst Nicht-Trolle, un\' jetzt die Horde? Wen will Talanji noch in unsre Stadt reinlass\'n?', 'Zuerst Nicht-Trolle, un\' jetzt die Horde? Wen will Talanji noch in unsre Stadt reinlass\'n?', 28153),
(135173, 'deDE', 'Die Horde is\' hier? Das sin\' finstere Zeiten.', 'Die Horde is\' hier? Das sin\' finstere Zeiten.', 28153),
(135147, 'deDE', 'Ich... Was ist geschehen? Ich muss hier weg!', '', 28153),
(135140, 'deDE', 'Vater, hilf mir. Ich brauche deinen Rat. Ich brauche...', '', 28153),
(135138, 'deDE', 'Mein König, die Belagerungstürme sind verloren! Unsere Truppen schwinden...', '', 28153),
(135002, 'deDE', 'Ich kann das Ding nicht einfach hierlassen. So schnappt es Euch doch, sonst nehme ich es zurück!', '', 28153),
(135001, 'deDE', 'Wenn keiner demnächst die Truhe aufmacht, muss ich den Rückrufmechanismus aktivieren!', '', 28153),
(134991, 'deDE', 'Man kann nicht immer gewinnen. Hinfort, hinfort!', '', 28153),
(134989, 'deDE', 'Wirklich? Keiner will? Wie Ihr meint!', '', 28153),
(134976, 'deDE', 'Ich hab\'s zuerst gesehen!', 'Ich hab\'s zuerst gesehen!', 28153),
(134975, 'deDE', 'Kann ich Bedarf würfeln?', 'Kann ich Bedarf würfeln?', 28153),
(134877, 'deDE', 'So, dann wollen wir mal! Alles gehört demjenigen, der sie zuerst öffnet!', '', 28153),
(134876, 'deDE', 'Nur noch fünfzehn Sekunden. Jetzt geht\'s hier gleich rund!', '', 28153),
(134875, 'deDE', 'Entsperrung läuft! Gebt mir dreißig Sekunden, ja?', '', 28153),
(134869, 'deDE', 'Ladung auf dem Weg! Köpfe einziehen!', '', 28153),
(134867, 'deDE', 'Passt auf, wir haben eine Menge Vorräte auf dem Weg ins Tiefland!', '', 28153),
(134811, 'deDE', 'Entsperrung abgeschlossen! Dem Sieger die Beute!', '', 28153),
(134810, 'deDE', 'Fünfzehn Sekunden, bis die Entsperrung abgeschlossen ist!', '', 28153),
(134809, 'deDE', 'Entsperrungssequenz aktiviert! T minus dreißig Sekunden.', '', 28153),
(134790, 'deDE', 'Ladung abgeworfen! Vorsicht da unten!', '', 28153),
(134789, 'deDE', 'Vorratsladung auf dem Weg ins Tiefland!', '', 28153),
(134699, 'deDE', '', 'Geht voraus, Champion. Ich hab\' noch \'n Wörtchen zu reden, mit dieser Sandschlange.', 28153),
(134678, 'deDE', 'Die Frösche werden wir nicht töten, aber Euch werden wir niedermetzeln!', '', 28153),
(134676, 'deDE', 'Wir werden Eure lieben kleinen Frösche in Käfige sperren und ihnen das Leben entziehen!', '', 28153),
(134675, 'deDE', 'Ich muss ihre neue Manaquelle beschützen!', '', 28153),
(134674, 'deDE', '$gDreckiger:Dreckige:r; $R! Wir werden unsere neue Manaquelle bekommen!', '', 28153),
(134673, 'deDE', 'Sobald wir Euch getötet haben, holen wir uns noch mehr Frösche!', '', 28153),
(134672, 'deDE', 'Wir haben Befehle, die Frösche nicht zu töten. Euch können wir aber sehr wohl töten!', '', 28153),
(134671, 'deDE', 'Ihr werdet uns nicht aufhalten. Die Frösche werden uns jahrelang nähren!', '', 28153),
(134670, 'deDE', '', 'Die Frösche gehören den Naga!', 28153),
(134669, 'deDE', '', 'Ihr werdet uns unsere Frösche nicht wegnehmen!', 28153),
(134668, 'deDE', '', 'Tod den Manadieben!', 28153),
(134667, 'deDE', '', 'Diese Frösche gehören jetzt uns!', 28153),
(134666, 'deDE', '', 'Die Frösche gehören uns!', 28153),
(134665, 'deDE', '', 'Diese Frösche werden uns viele Jahre nähren!', 28153),
(134664, 'deDE', '', 'Mit diesen Fröschen werden wir unser Volk retten!', 28153),
(134663, 'deDE', '', 'Diese Frösche werden uns nähren!', 28153),
(134661, 'deDE', 'Der feige Angriff der Horde auf Teldrassil hat uns in den Krieg gestürzt... und zeigt uns, was wirklich auf dem Spiel steht.', '', 28153),
(134656, 'deDE', 'Krag\'wa wird Eure Ergebenheit belohnen. Kommt.', '', 28153),
(134652, 'deDE', '', 'Unser Ältester hat von Krag\'wa erzählt. Niemand wollt\' ihm glaub\'n... außer mir. Ich wollt\', dass es wahr is\'.', 28153),
(134651, 'deDE', 'Ich weiß, was Euer Herz bewegt, Narez. Ihr wart die ganze Zeit über Krag\'wa treu ergeben.', '', 28153),
(134650, 'deDE', '', 'Wartet! Bevor Ihr geht...', 28153),
(134649, 'deDE', 'Es wird Zeit, dass ich zurückkehre. Danke nochmal für all Eure Hilfe.', '', 28153),
(134648, 'deDE', 'Es wird sogar erzählt, dass Euer Vater schwach geword\'n is\' und seine einzige Tochter vorgeschickt hat, Zul anzubetteln, mit seiner Flotte zurückzukehr\'n. Is\' das so, Hoheit?', '', 28153),
(134647, 'deDE', '', 'Wie könnt Ihr es wag\'n, so mit mir zu...', 28153),
(134646, 'deDE', 'Wir werden die Naga zurückschlagen können, wenn Zaldraxia tot ist. Viel Glück.', '', 28153),
(134639, 'deDE', 'Ein feindlicher Verwüster ist am südlichen Gebäude der Horde erschienen!', 'Ein feindlicher Verwüster ist am südlichen Gebäude der Horde erschienen!', 28153),
(134638, 'deDE', '', 'In all den Jahren in diesen Hügeln habe ich noch nie solche Monster gesehen!', 28153),
(134637, 'deDE', '<Zeigt ihr das Wort des Zul.>', '<Zeigt ihr das Wort des Zul.>', 28153),
(134630, 'deDE', '', 'Ich w-weiß nicht, was meine Schwester und ihre Freunde vorhaben, aber es wird nichts Gutes sein. Für gute Sachen braucht man keine B-Blutopfer!', 28153),
(134629, 'deDE', '', 'S-So viele Beine! So viele Augen! Sie suchen nach mir!', 28153),
(134620, 'deDE', '', 'Wir brauch\'n \'nen echten Anführer! Keinen schwachen König.', 28153),
(134618, 'deDE', '', 'Unsere Grenzen sin\' schwach. Unser Volk is\' schwach. Wir brauch\'n die Stärke, die nur Zul uns biet\'n kann.', 28153),
(134617, 'deDE', '', 'Erinnert Euch an die Worte von Zul, unserm Propheten. Erinnert Euch an die Verdammnis, die er für unser Volk vorausgeseh\'n hat.', 28153),
(134616, 'deDE', '', 'König Rastakhan verrottet auf seinem Thron, zu schwach und zu ängstlich, um unter sein Volk zu geh\'n. Wir brauch\'n \'nen starken Anführer!', 28153),
(134615, 'deDE', '', 'Zul sah den Kataklysmus voraus und wir taten nichts. Wir sah\'n zu, als unser König ihn verbannte. Wir sah\'n zu, als Zul unsre Brüder und Schwestern mit sich ins Exil nahm. Und wir sah\'n die Zerstörung, die der Kataklysmus mit sich brachte.', 28153),
(134613, 'deDE', '', 'Zul wird zurückkehr\'n und unser Imperium aus der Asche erheb\'n.', 28153),
(134610, 'deDE', '', 'Die Zeit is\' gekomm\'n! Ich muss es den andern sag\'n. Wer ihm immer noch treu ergeben is\', muss es erfahr\'n.', 28153),
(134599, 'deDE', '', 'Ich werde Euch nicht enttäuschen, Königin Azshara! Die Frösche werden uns gehören, dafür werde ich sorgen!', 28153),
(134598, 'deDE', '', 'Alle Eure kostbaren Frösche kommen in Käfige. Sie werden dafür leben, unsere Bedürfnisse zu stillen!', 28153),
(134597, 'deDE', '', 'Unverschämter ABSCHAUM! Die Magie unseres Volks wird endlich gestillt werden. Kein Durst mehr! Kein Verlangen!', 28153),
(134596, 'deDE', '', 'Warum...? Fast hätten wir... nie wieder nach Magie dürsten müssen...', 28153),
(134595, 'deDE', '', 'Ihr! Ihr habt alles zunichte gemacht... Die Frösche sollten noch jahrelang unsere Magie nähren!', 28153),
(134594, 'deDE', 'Die Naga werden für ihre Vergehen bezahlen.', '', 28153),
(134593, 'deDE', 'Zaldraxia soll für alles zahlen, was sie uns angetan hat.', '', 28153),
(134592, 'deDE', 'Ha! Meine Kraft fließt... dank Euch. Krag\'wa wird von Eurer Hilfe erfahren.', '', 28153),
(134591, 'deDE', 'Ah... endlich habe ich wieder Kraft! Ihr habt gute Dienste geleistet. Krag\'wa wird davon erfahren.', '', 28153),
(134590, 'deDE', 'Ich fühle mich... voller Kraft! Ich danke Euch, aber ich muss jetzt zu Krag\'wa zurückkehren.', '', 28153),
(134589, 'deDE', '', 'Vor Jahren, als er mit unsrer Flotte aus dem Exil zurückgekehrt is\'.$b$bEr beschrieb seine Vision von dem Tag, an dem die Welt blut\'n würde, und er hat Euch in allen Einzelheiten beschrieb\'n.', 28153),
(134588, 'deDE', 'Wann habt Ihr zuletzt mit Zul gesprochen?', 'Wann habt Ihr zuletzt mit Zul gesprochen?', 28153),
(134587, 'deDE', '', 'Ihr! Ihr seid es!$b$bZul hat mir Euch einmal beschrieb\'n. Sehr detailliert. Ihr habt sogar dieses... Ding... in Euerm Gesicht. Ganz, wie er beschrieb\'n hat.$b$bSagt mir, is\' es wahr? Habt Ihr eine Botschaft von ihm für mich?', 28153),
(134584, 'deDE', 'Es is\' also endlich so weit. Ich hab diese Botenbestie hierbehalt\'n, seit der Donnerkönig aufgestieg\'n is\'. Es scheint, ihre Stunde is\' nun gekomm\'n.', '', 28153),
(134583, 'deDE', 'Die Magie des Frosches nährt unser Volk. Wir werden nie wieder Durst leiden!', '', 28153),
(134581, 'deDE', '<Zeigt ihm das Wort des Zul.>', '<Zeigt ihm das Wort des Zul.>', 28153),
(134580, 'deDE', 'Was gibt\'s, Fremdling?', '', 28153),
(134492, 'deDE', '', 'Endlich kommt mir wer helf\'n! Die Naga ham \'nen Glückstreffer bei mir gelandet. Wir müss\'n die Frösche rett\'n.', 28153),
(134471, 'deDE', '', 'Ahh, was haben wir denn da? Der Löwe von Sturmwind zeigt sich endlich. Ihr habt nicht die leiseste Ahnung, womit Ihr es zu tun habt, kleiner König. Das ist erst der Anfang!', 28153),
(134465, 'deDE', '', 'Mpf... Ich wart hier und versteck mich, zwei Sachen, die ich nich\' aussteh\'n kann. Findet raus, warum die Naga die Frösche woll\'n!', 28153),
(134464, 'deDE', 'War das schon alles, Windläufer?!', '', 28153),
(134463, 'deDE', 'Alle Einheiten zu den Toren! Sieg für die Allianz!', '', 28153),
(134460, 'deDE', '', 'Diese Naga werd\'n nich\' damit durchkomm\'n, diese Frösche zu entweih\'n.', 28153),
(134453, 'deDE', 'Die Prinzessin is\' nich\' hier, um Euch zu rett\'n.', 'Die Prinzessin is\' nich\' hier, um Euch zu rett\'n.', 28153),
(134451, 'deDE', 'Haha. Hier rettet Euch keiner außer mir.', 'Haha. Hier rettet Euch keiner außer mir.', 28153),
(134450, 'deDE', 'Die Wach\'n hier scher\'n sich \'nen Dreck um wertlose Fremdlinge wie Euch.', 'Die Wach\'n hier scher\'n sich \'nen Dreck um wertlose Fremdlinge wie Euch.', 28153),
(134449, 'deDE', 'Mein Messer sagt, Ihr gebt mir \'nen ordentlich\'n Rabatt.', 'Mein Messer sagt, Ihr gebt mir \'nen ordentlich\'n Rabatt.', 28153),
(134448, 'deDE', 'Ihr seid schon wieder zu spät mit\'m Schutzgeld dran.', 'Ihr seid schon wieder zu spät mit\'m Schutzgeld dran.', 28153),
(134447, 'deDE', 'Eure Hoheit, könnt Ihr die Angst nich\' riechen, die diese Stadt umklammert?', '', 28153),
(134442, 'deDE', 'Hehe... Die Lieferungen sind schon raus...', '', 28153),
(134439, 'deDE', 'Ah! Mehr Fleisch, das ich verwursten kann!', '', 28153),
(134438, 'deDE', 'Hah! In Euch steckt noch Kampfgeist. Gestattet mir, Euch einen Vorgeschmack darauf zu gewähren, was die Horde zu bieten hat.', '', 28153),
(134330, 'deDE', 'Rette sich, wer kann!', 'Rette sich, wer kann!', 28153),
(134329, 'deDE', 'Das ist reines Chaos! Ich muss mich in Sicherheit begeben.', 'Das ist reines Chaos! Ich muss mich in Sicherheit begeben.', 28153),
(134328, 'deDE', 'Diese Troggs sind aus dem Nichts aufgetaucht!', 'Diese Troggs sind aus dem Nichts aufgetaucht!', 28153),
(134310, 'deDE', 'Der Tempel is\' \'ne Ruine! Es is\' noch schlimmer, als ich befürchtet hab...', '', 28153),
(134309, 'deDE', 'Bevor ich ermordet wurde, war ich der Verwalter von diesem Tempel. Mir graut davor, was aus ihm in den Jahrzehnt\'n nach meinem Tod geword\'n is\'...', '', 28153),
(134300, 'deDE', 'Aua! Böser Dino! Böse!', 'Aua! Böser Dino! Böse!', 28153),
(134299, 'deDE', 'Ihr seid gut!', 'Ihr seid gut!', 28153),
(134298, 'deDE', 'Argh! Nich\' meine Finger!', 'Argh! Nich\' meine Finger!', 28153),
(134297, 'deDE', 'Wer mich veräpp\'ln will, kriegt was auf\'n Schädel!', 'Wer mich veräpp\'ln will, kriegt was auf\'n Schädel!', 28153),
(134296, 'deDE', 'Aua! Nich\' beiß\'n!', 'Aua! Nich\' beiß\'n!', 28153),
(134295, 'deDE', 'Sachte... sachte!', 'Sachte... sachte!', 28153),
(134292, 'deDE', '%s zittert und wimmert.', '', 28153),
(134291, 'deDE', '%s quiekt vor Schreck.', '', 28153),
(134290, 'deDE', '%s quiekst ängstlich.', '', 28153),
(134289, 'deDE', 'Ich werde Euch durch die Tempelruinen begleiten.', 'Ich werde Euch durch die Tempelruinen begleiten.', 28153),
(134288, 'deDE', 'Nickel bellt ein Wiesel an.', '', 28153),
(134279, 'deDE', 'Sie nähren sich von meiner Magie!', '', 28153),
(134278, 'deDE', 'Sie rauben uns die Magie!', '', 28153),
(134277, 'deDE', 'Argh... Meine Magie lässt nach...', '', 28153),
(134276, 'deDE', 'Ich fühle mich so... ausgelaugt... Sie haben mir meine Kraft genommen!', '', 28153),
(134275, 'deDE', 'Diese Widerlinge haben meine Freunde entführt!', '', 28153),
(134274, 'deDE', 'Dieses Pack hat mir meine Magie geraubt!', '', 28153),
(134272, 'deDE', 'Diesmal nicht...', '', 28153),
(134271, 'deDE', 'Die Allianz lässt keinen Soldaten zurück!', '', 28153),
(134270, 'deDE', 'Sie belebt ihre Leichen! Wir müssen die Verwundeten wegschaffen!', '', 28153),
(134266, 'deDE', 'SIEG DEN VERLASSENEN!', '', 28153),
(134263, 'deDE', 'Mein König, die Seuche ist zu gefährlich! Wir können nicht riskieren–', '', 28153),
(134252, 'deDE', 'Das Licht segne Euch. Bringt mir Eure Verletzten!', '', 28153),
(134233, 'deDE', '', 'Ich danke Euch. Jetzt komme ich wieder alleine zurecht.', 28153),
(134230, 'deDE', 'Verfluchte... Wilde!', 'Verfluchte... Wilde!', 28153),
(134229, 'deDE', 'Ich sterbe... für meinen König... für Lordaer...', 'Ich sterbe... für meinen König... für Lordaer...', 28153),
(134227, 'deDE', 'Es hört nicht auf... da kommen immer mehr! Helden, helft mir, sie abzuwehren!', 'Es hört nicht auf... da kommen immer mehr! Helden, helft mir, sie abzuwehren!', 28153),
(134226, 'deDE', '', 'Ääähm... kann mal jemand helfen?', 28153),
(134224, 'deDE', '', 'Bogenschützen, anlegen und vorrücken!', 28153),
(134223, 'deDE', 'Helden! Wir werden überrannt! Ich kann sie... nicht viel länger am Leben halten...', '', 28153),
(134211, 'deDE', 'Soooo schöööön...', '', 28153),
(134209, 'deDE', 'Wartet, hört Ihr das?', '', 28153),
(134208, 'deDE', 'Steuermann, bringt uns raus!', 'Steuermann, bringt uns raus!', 28153),
(134186, 'deDE', 'Genau! Höchste Zeit, dass $p in die Bande eingeschwor\'n wird. Bereitet das Ritual vor!', '', 28153),
(134164, 'deDE', '', 'Kommt, Drekal. Such\'n wir weiter.', 28153),
(134163, 'deDE', '', 'Ich seh hier nix Interessantes.', 28153),
(134162, 'deDE', '', 'Warum habt Ihr uns geruf\'n?', 28153),
(134161, 'deDE', '', 'Wisst Ihr, was $gder:die:r; letzte $r aushalten musste, $gder:die:r; falsch\'n Alarm geschlag\'n hat?', 28153),
(134159, 'deDE', '', 'Ist das \'n Spiel für Euch?', 28153),
(134158, 'deDE', 'Oh nein... ich glaub, da ist Pipi in meinem Fass.', '', 28153),
(134157, 'deDE', 'Den Käufern juckt\'s in den Fingern! Klar zum Ablegen!', 'Den Käufern juckt\'s in den Fingern! Klar zum Ablegen!', 28153),
(134156, 'deDE', '', 'Neuer Plan, Jungs! Pullen weg und ran an den Speck!', 28153),
(134155, 'deDE', '', 'Was soll die Zeitverschwendung?', 28153),
(134151, 'deDE', '', 'Das Signalleuchtfeuer is\' kein Spielzeug.', 28153),
(134150, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Südliches Gebäude der Allianz verteidigen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Südliches Gebäude der Allianz verteidigen', 28153),
(134149, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Nördliches Gebäude der Allianz verteidigen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Nördliches Gebäude der Allianz verteidigen', 28153),
(134125, 'deDE', '', 'Schon gut. Auf den könn\' wir nich\' wart\'n. Ich hab jemand\'n gefund\'n, der anscheinend weiß, wo Rakera is\'. Kommt, hier lang!', 28153),
(134123, 'deDE', '', 'Bleib\'n wir hier nich\' länger als unbedingt nötig. Falls Ihr was Interessantes findet, gebt mit dem Leuchtfeuer Signal.', 28153),
(134116, 'deDE', 'Dieses Land gehört uns, ihr Hunde! Ihr werdet mit Euren Leben bezahlen!', '', 28153),
(134115, 'deDE', 'Soldaten! In Formation!', '', 28153),
(134111, 'deDE', 'Ich kann nicht behaupten, dass ich diesen Ort vermissen werde.', '', 28153),
(134109, 'deDE', '', 'Ihr verlangt ganz schön viel für jemand\'n, der so dicht neb\'n meinem Schwert steht.', 28153),
(134101, 'deDE', 'Ihr gehört hier nicht her!', 'Ihr gehört hier nicht her!', 28153),
(134100, 'deDE', 'Oooh, das leere Fass ist meins! Ihr könnt das andere haben.', '', 28153),
(134099, 'deDE', 'Schnell, versteckt Euch!', '', 28153),
(134096, 'deDE', 'Aschenwinds dreckiges Geheimnis.', '', 28153),
(134095, 'deDE', 'Was war DAS?!', '', 28153),
(134094, 'deDE', 'Seid Ihr sicher, dass Ihr für 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold einen Spähturm bauen möchtet?', 'Seid Ihr sicher, dass Ihr für 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold einen Spähturm bauen möchtet?', 28153),
(134093, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Spähturm bauen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Spähturm bauen', 28153),
(134092, 'deDE', 'Ja, ja, Man\'zul. Wir hätt\'n auf Euch hör\'n soll\'n. Ihr habt das nich\' verdient. Wir hätt\'n Eurem Plan folg\'n soll\'n. Ihr seid so clever. Jetzt psst, oder ich zwick\' Euch nochmal die Nase!', '', 28153),
(134091, 'deDE', 'Man\'zul! Das is\'n familienfreundliches Gasthaus! Die Zeiten sin\' hinter uns.', '', 28153),
(134090, 'deDE', 'Ha! Euer Stil gefällt mir, $p, aber da war ich schneller. Von ihm is\' nur noch die Augenklappe und \'n charmantes Lächeln übrig.', '', 28153),
(134089, 'deDE', 'Volni, hört auf, die Gäste zum Duell rauszufordern! Die letzt\'n beiden ham nicht mal die Rechnung bezahlt.', '', 28153),
(134088, 'deDE', 'Sprecht lauter! Ich kann nicht lausch\'n, wenn Ihr da drüben so nuschelt!', '', 28153),
(134087, 'deDE', 'Ihr macht keinem was vor, Volni. Ihr liebt den Hut, den ich Euch geschenkt hab\', und ich nehm\' ihn nich\' weg, bis Ihr\'s zugebt!', '', 28153),
(134086, 'deDE', 'Wartet, bei dem Trommelgedröhn kann sie Euch nicht hör\'n. Macht mal \'n Päuschen, Grenja! $p will Euch begrüß\'n. Grenja is\' unsere Bardin, aber manchmal vergisst sie, dass wir hier auch red\'n woll\'n.', '', 28153),
(134085, 'deDE', 'Alles klar mit Euch, $p? Ihr macht Grenja nervös... Habt Ihr \'nen Hitzschlag?', '', 28153),
(134084, 'deDE', 'Gut erkannt, $p! In Zuldazar hat Grenja uns aus so manch brenzliger Lage rausgehau\'n. Viele Türen hat sie uns geöffnet und eingeschlag\'n... und andere Leute hat sie auch eingeschlag\'n.', '', 28153),
(134079, 'deDE', 'Okay, an die Arbeit.', '', 28153),
(134078, 'deDE', 'Andererseits... Ihr habt meiner Stadt sehr geholfen, und ich bin Euch dankbar. Ich sehe mal, was ich ausrichten kann...', '', 28153),
(134077, 'deDE', 'Ich bezweifle, dass sie mit Festländern verhandeln wollen.', '', 28153),
(134076, 'deDE', 'Auf diesem Land lastet ein Fluch, und als er sich zeigte, zogen die Kronsteigs den Schwanz ein und rannten davon. Sie verstecken sich auf ihrem Anwesen, während ihre Untertanen unsichtbaren Übeln zum Opfer fallen.', '', 28153),
(134075, 'deDE', 'Ihr wollt Euch mit den Feiglingen von Kronsteig treffen? Ich glaube nicht, dass Euch das weiterhelfen wird.', '', 28153),
(134074, 'deDE', 'Ich möchte den Lord des Hauses Kronsteig sprechen.', 'Ich möchte den Lord des Hauses Kronsteig sprechen.', 28153),
(134073, 'deDE', 'Ich kann Euch gar nicht genug dafür danken, was Ihr für unsere Stadt getan habt, $gFestländer:Festländerin;.\n\nFallhafen steht in Eurer Schuld.', '', 28153),
(134072, 'deDE', 'Wie kann ich behilflich sein, $C?', '', 28153),
(134070, 'deDE', '', 'Ah, da seid Ihr wieder. Ihr wart länger fort als erwartet. Gab\'s Schwierigkeiten?', 28153),
(134069, 'deDE', '', 'Ihr könnt meine Rakete nehmen, um zu Eurer Basis zurückzukehren. Das geht nur in eine Richtung, also zündet sie erst, wenn Ihr wirklich bereit seid.', 28153),
(134068, 'deDE', '', 'Hey, äh... Ihr wart ja \'ne große Hilfe, aber den Rest schaffen wir allein.', 28153),
(134067, 'deDE', 'Lasst uns von hier verschwinden.', 'Lasst uns von hier verschwinden.', 28153),
(134066, 'deDE', 'Molch sagt, dass diese Rakete ein sicheres Einwegfahrzeug ist. Die instabile Bauweise spricht aber eine andere Sprache.', '', 28153),
(134065, 'deDE', 'Zsserstört allesss, wasss sssich unsss entgegenssstellt. Für den Ruhm der Königin!', '', 28153),
(134064, 'deDE', 'Zsserstört alles, wasss ausss dem Tempel kommt!', '', 28153),
(134063, 'deDE', 'Sssichert die Relikte für die Königin!', '', 28153),
(134062, 'deDE', 'Die Königin will diessse Relikte! Holt sssie, ssschnell!', '', 28153),
(134061, 'deDE', 'Schön, dass Ihr es alle heil zurück geschafft habt. Alles dank... hey, da ist ja unser Mann der Stunde.', '', 28153),
(134060, 'deDE', 'Meine.... Schätze...', '', 28153),
(134059, 'deDE', 'Ihr wagt\'s, meine Schätze zu berühr\'n?!', '', 28153),
(134018, 'deDE', '<Versucht, die Truhe zu öffnen.>', '<Versucht, die Truhe zu öffnen.>', 28153),
(134017, 'deDE', 'Die Truhe ist fest verschlossen, aber mit dem richtigen Einsatz solltet Ihr sie öffnen können.', '', 28153),
(134016, 'deDE', '', 'Scheint, als hätte schon ein weiteres Allianzschiff angelegt. Hoffentlich wurden sie wärmer empfangen als Jaina...', 28153),
(134015, 'deDE', 'Ihr habt mir das Leben gerettet!', '', 28153),
(134014, 'deDE', 'Das werde ich Euch nicht vergessen. Vielen Dank!', '', 28153),
(134013, 'deDE', 'Ich schulde Euch ein Bier!', '', 28153),
(134012, 'deDE', 'Danke, viel länger hätte ich nicht durchgehalten.', '', 28153),
(134011, 'deDE', 'Die Naga haben die anderen in Ketten gelegt und verschleppt. Bitte befreit sie auch!', '', 28153),
(134010, 'deDE', 'Blut und Donner! Wenn wir uns das nächste Mal sehen, gebe ich einen aus!', '', 28153),
(134009, 'deDE', '', 'Ich weiß nicht, was gerade mit Euch geschehen ist, aber es hat anscheinend funktioniert! Geht es Euch... gut?', 28153),
(134007, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134003, 'deDE', 'Kämpft gemeinsam! FÜR DIE ALLIANZ!', '', 28153),
(134001, 'deDE', 'Um unsere Zukunft zu sichern, muss die Bansheekönigin gerichtet werden. Ihre dunkle Herrschaft endet heute!', '', 28153),
(134000, 'deDE', 'Ihr Kriegshäuptling wollte nicht einfach eine Stadt einnehmen, sie wollte unsere Lebensweise zerstören... und jegliche Hoffnung für kommende Generationen.', '', 28153),
(133999, 'deDE', 'Gemeinsam treiben wir ihren verderbten Kadaver aus diesem Land... und lassen unsere Banner aufs Neue über Lordaeron wehen!', '', 28153),
(133998, 'deDE', 'Brüder und Schwestern der Allianz, hört meine Worte!', '', 28153),
(133996, 'deDE', 'König Anduin führt den Angriff! Gebt alles, was Ihr habt, um das Schlachtfeld zu sichern!', '', 28153),
(133990, 'deDE', 'Belagerungsmaschine bereit zum Einsatz!', '', 28153),
(133989, 'deDE', 'Eine Belagerungsmaschine für $geinen tollen Burschen:ein tolles Mädel;!', '', 28153),
(133988, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Belagerungsmaschine bauen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Belagerungsmaschine bauen', 28153),
(133986, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Mörserspezialisten ausbilden - Norden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Mörserspezialisten ausbilden - Norden angreifen', 28153),
(133985, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Ritter ausbilden - Norden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Ritter ausbilden - Norden angreifen', 28153),
(133984, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Scharfschützen ausbilden - Norden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Scharfschützen ausbilden - Norden angreifen', 28153),
(133983, 'deDE', 'Ich brauch noch ein bisschen mehr von Euch, um die Bestellungen zu machen.', '', 28153),
(133982, 'deDE', 'Willkommen in meinem Laden!', '', 28153),
(133981, 'deDE', '', 'Stallmeisterin Lucia Fahrental, zu Euren Diensten!', 28153),
(133980, 'deDE', '', 'Unsere Reiter auszubilden, ist ziemlich teuer, $n.', 28153),
(133979, 'deDE', '', 'Schön Euch wiederzusehen, $n. Wie kann ich Euch helfen?', 28153),
(133974, 'deDE', '', 'Ich kann nicht zum Nulltarif ausbilden!$B$BSammelt mehr Gold und kommt dann zurück!', 28153),
(133971, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Ritter ausbilden - Süden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Ritter ausbilden - Süden angreifen', 28153),
(133970, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Mörserspezialisten ausbilden - Süden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Mörserspezialisten ausbilden - Süden angreifen', 28153),
(133969, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Scharfschützen ausbilden - Süden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Scharfschützen ausbilden - Süden angreifen', 28153),
(133968, 'deDE', '', 'Wieso habt Ihr so lange gebraucht? Zeit, an die Arbeit zu gehen!', 28153),
(133960, 'deDE', '<Stellt Euch höflich vor.>', '<Stellt Euch höflich vor.>', 28153),
(133959, 'deDE', '<Stellt Euch höflich vor.>', '<Stellt Euch höflich vor.>', 28153),
(133958, 'deDE', '', 'Ist sie in Sicherheit? Ich habe Kaja gesagt, sie soll nich\' nach mir such\'n.', 28153),
(133953, 'deDE', 'Diese versunkene Stadt war einst ein schöner Tempel, der Gral gewidmet war, dem Loa des Meeres.$b$bAllerdings kamen die Naga und zerstörten den Tempel. All seine Anhänger wurden getötet.$B$BWenn Gral noch lebt, wird er geschwächt sein.', '', 28153),
(133952, 'deDE', 'Was is\' los, Mann? Werd\'n wir angegriff\'n?', '', 28153),
(133951, 'deDE', 'Irgendwas is\' vom Himmel gefall\'n! Es is\' hier drüben!', '', 28153),
(133950, 'deDE', 'Meine Brüder lassen es zu, dass ihr Hass auf die Naga ihr Urteilsvermögen beeinträchtigt. Es ist nicht das erste Mal, dass Herrin Ssin und ihre Schreckenswindernaga uns zu einem solchen Fund verfolgt haben.$b$bOffenbar wissen sie etwas, das wir nicht wissen.', '', 28153),
(133947, 'deDE', '', 'Ihr werdet um Gnade flehen!', 28153),
(133946, 'deDE', 'Ich möchte zum Trübsumpf.', 'Ich möchte zum Trübsumpf.', 28153),
(133945, 'deDE', 'Ihr werdet durch meine Klinge sterben!', 'Ihr werdet durch meine Klinge sterben!', 28153),
(133944, 'deDE', 'Wollt Ihr wo hin?', '', 28153),
(133943, 'deDE', 'Ich mache keine Gefangenen!', 'Ich mache keine Gefangenen!', 28153),
(133942, 'deDE', '', 'Für diese Unterbrechung bezahlt Ihr mit dem Leben!', 28153),
(133941, 'deDE', '', 'Zerlegt dieses Lager in seine Einzelteile. Ich will alles haben, an dem Goji und seinesgleichen gearbeitet haben.', 28153),
(133939, 'deDE', 'Die Piratenkönigin wird meinen Tod rächen!', '', 28153),
(133938, 'deDE', 'Wer hat diesen Schwachkopf auf mein Schiff gelassen?', '', 28153),
(133936, 'deDE', 'Sterbt, Made!', 'Sterbt, Made!', 28153),
(133935, 'deDE', 'Na Ihr traut Euch aber etwas...', 'Na, Ihr traut Euch aber was...', 28153),
(133934, 'deDE', 'Was immer Ihr habt, es gehört jetzt mir!', 'Was immer Ihr habt, es gehört jetzt mir!', 28153),
(133933, 'deDE', 'Dieses Land gehört Aschenwind & Co.!', 'Dieses Land gehört Aschenwind & Co.!', 28153),
(133929, 'deDE', 'Ihr seid hier nicht willkommen!', 'Ihr seid hier nicht willkommen!', 28153),
(133928, 'deDE', 'Ihr kommt hier nicht lebend raus!', 'Ihr kommt hier nicht lebend raus!', 28153),
(133926, 'deDE', 'Ich werd diese Barmherzigkeit nie vergess\'n...', 'Ich werd diese Barmherzigkeit nie vergess\'n...', 28153),
(133925, 'deDE', 'Endlich hat das Leiden ein Ende...', 'Endlich hat das Leiden ein Ende...', 28153),
(133924, 'deDE', 'Ihr habt meinen Dank, $gFremder:Fremde;...', 'Ihr habt meinen Dank, $gFremder:Fremde;...', 28153),
(133923, 'deDE', 'Ich wusste, Eraka no Kimbul würde uns Hilfe send\'n...', 'Ich wusste, Eraka no Kimbul würde uns Hilfe send\'n...', 28153),
(133919, 'deDE', 'Endlich kann ich in Frieden ruh\'n...', 'Endlich kann ich in Frieden ruh\'n...', 28153),
(133918, 'deDE', 'Ich wusste, der Loa würde uns nich\' vergess\'n...', 'Ich wusste, der Loa würde uns nich\' vergess\'n...', 28153),
(133917, 'deDE', 'Springt über das ausgewählte Hindernis. Der Schiedsrichter könnte den Sprung nicht werten, wenn Ihr nicht über die Mitte springt!', 'Springt über das ausgewählte Hindernis. Der Schiedsrichter könnte den Sprung nicht werten, wenn Ihr nicht über die Mitte springt!', 28153),
(133916, 'deDE', 'Wenn Ihr zu spät oder zu früh springt, könnte Eurer Pferd Euch abwerfen.', 'Wenn Ihr zu spät oder zu früh springt, könnte Eurer Pferd Euch abwerfen.', 28153),
(133915, 'deDE', 'Keine Sorge, ich gehe nicht verloren. Und wenn, würdet Ihr ja sowieso nach mir suchen.', '', 28153),
(133913, 'deDE', 'Wenn Ihr \'Leichter Galopp\' verwendet, benutzt \'Galoppieren\', um Euch noch schneller fortzubewegen!', 'Wenn Ihr \'Leichter Galopp\' verwendet, werdet Ihr durch \'Galoppieren\' noch schneller!', 28153),
(133912, 'deDE', 'Setzt \'Leichter Galopp\' ein, um Euch schneller fortzubewegen. Dies ist die beste Geschwindigkeit für Sprünge!', 'Setzt \'Leichter Galopp\' ein, um Euch schneller fortzubewegen. Dies ist die beste Geschwindigkeit für Sprünge!', 28153),
(133911, 'deDE', 'Verwendet \'Schritt\', um Euch nach vorne zu bewegen und \'Stoppen\', um jederzeit anzuhalten.', 'Verwendet \'Schritt\', um Euch nach vorne zu bewegen und \'Stoppen\', um jederzeit anzuhalten.', 28153),
(133904, 'deDE', 'Gilgoblins sind furchtbare Kreaturen. Diese kleinen Schleimer des Meeres sind ihren Nagameistern nur zu gern zu Willen, egal, wie herablassend sie sind.', '', 28153),
(133899, 'deDE', 'Hm, vielleicht begreift Shoak, dass dies kein Ort zum Erkunden sondern zum Verlassen ist!', '', 28153),
(133893, 'deDE', 'Argh... Geht schon in Ordnung, Dummkopf. Aber nicht wieder weglaufen!', '', 28153),
(133883, 'deDE', 'Ein feindlicher Verwüster ist am nördlichen Gebäude der Horde erschienen!', 'Ein feindlicher Verwüster ist am nördlichen Gebäude der Horde erschienen!', 28153),
(133835, 'deDE', 'Es ist leider nicht billig, eine Armee aufzustellen, $n. Wir müssen sie ernähren, ausbilden und jedes Rüstungsteil von Hand herstellen.\n\nKommt wieder, wenn Eure Taschen voller sind.', '', 28153),
(133834, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Fußsoldaten ausbilden - Süden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Fußsoldaten ausbilden - Süden angreifen', 28153),
(133833, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Fußsoldaten ausbilden - Norden angreifen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Fußsoldaten ausbilden - Norden angreifen', 28153),
(133832, 'deDE', '', 'Wie viele Gegner habt Ihr gegess\'n, um so stark zu werd\'n?', 28153),
(133831, 'deDE', '', 'Wir hab\'n Stimmen gehört, die von Euch flüsterten... Ich freu mich schon drauf, Euch zu fress\'n!', 28153),
(133830, 'deDE', '', 'Wehe, Ihr... esst mich... für Kraft...', 28153),
(133829, 'deDE', '', 'Ich glaub, ich fress Euern Arm, bevor ich mit Euch das Totem stärke!', 28153),
(133828, 'deDE', '', 'Die Stimmen hab\'n mir gesagt... Fleisch... gibt uns Kraft...', 28153),
(133827, 'deDE', '', 'Die Stimmen hab\'n mir gesagt, Euer Fleisch gibt uns Kraft!', 28153),
(133820, 'deDE', 'Ihr habt nicht genug Kriegsfrontgold, um ein Gebäude zu bauen.', 'Ihr habt nicht genug Kriegsfrontgold, um ein Gebäude zu bauen.', 28153),
(133819, 'deDE', 'Wir können nichts bauen, während bereits ein Gebäude in Arbeit ist.', 'Wir können nichts bauen, während bereits ein Gebäude in Arbeit ist.', 28153),
(133806, 'deDE', 'Wenn Ihr zu diesem Tempel zurückkehrt, so werden wir Euch zu unseren Freunden und geschätzten Gästen zählen.', '', 28153),
(133805, 'deDE', 'Als Anerkennung Eures Mutes biete ich Euch einen Segen der Macht. Möge er Euch in zukünftigen Schlachten dienlich sein.', '', 28153),
(133804, 'deDE', 'Und darüber hinaus habt Ihr die Geister meiner Anhänger vor der Vernichtung bewahrt und diesem Tempel geholfen.', '', 28153),
(133803, 'deDE', 'Endlich ist Kuppaka tot, und die mächtigen gestohlenen Artefakte wurden den Fängen der Tortaka entrissen.', '', 28153),
(133801, 'deDE', 'Für die Tortaka gibt es keine Rettung mehr. Kuppaka und sein Stamm müssen ausgelöscht werden, wie auch die Quellen ihrer dunklen Macht.', '', 28153),
(133799, 'deDE', 'Ich hätt nie gedacht, dass ihre Machtgier sie zu solch\'n Gräueltaten treib\'n würde... Was könn\' wir dagegen tun?', '', 28153),
(133798, 'deDE', 'Der Stamm der Tortaka wird nicht aufgeben, bis er jedem Geist im Tempel die Energie entzogen hat.', '', 28153),
(133794, 'deDE', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold eine Schmiede bauen möchtet?', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold eine Schmiede bauen möchtet?', 28153),
(133793, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Schmiede bauen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Schmiede bauen', 28153),
(133790, 'deDE', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold eine Werkstatt bauen möchtet?', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold eine Werkstatt bauen möchtet?', 28153),
(133788, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Werkstatt bauen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Werkstatt bauen', 28153),
(133786, 'deDE', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold Ställe bauen möchtet?', 'Seid Ihr sicher, dass Ihr für 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t Kriegsfrontgold Ställe bauen möchtet?', 28153),
(133785, 'deDE', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Ställe bauen', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Ställe bauen', 28153),
(133784, 'deDE', 'Wählt, welches Gebäude Ihr an dieser Position bauen möchtet:', 'Wählt, welches Gebäude Ihr an dieser Position bauen möchtet:', 28153),
(133775, 'deDE', 'Shoak hat sich reingeritten... schon wieder! Unfassbar, dass der Idiot sich von den Bluttrollen hat fangen lassen.', '', 28153),
(133769, 'deDE', 'SHOAK! Wo seid Ihr? SHOAK!', '', 28153),
(133768, 'deDE', 'Ich kenne einen guten Platz, zu dem wir alle bringen können. Folgt mir!', '', 28153),
(133765, 'deDE', 'Eure Seele ist verloren!', '', 28153),
(133764, 'deDE', 'Euer Loa hat hier keine Macht!', '', 28153),
(133763, 'deDE', 'Eure Seele wird uns gehören!', '', 28153),
(133760, 'deDE', 'Die Tortaka dulden keine Fremden!', '', 28153),
(133759, 'deDE', 'Ihr seid hier nicht willkommen!', '', 28153),
(133758, 'deDE', 'Eraka no Kimbul hat hier keine Macht!', '', 28153),
(133757, 'deDE', 'Die Macht dieses Reiches gehört uns!', '', 28153),
(133756, 'deDE', 'Selbst der Loa kann uns nicht aufhalten!', '', 28153),
(133755, 'deDE', 'Ich werde Euch meine wahre Macht zeigen!', '', 28153),
(133754, 'deDE', 'Die Macht wird uns gehören!', '', 28153),
(133752, 'deDE', 'Wir werden uns an Eurer Seele laben!', '', 28153),
(133745, 'deDE', '', 'Was wissst Ihr von unseren Plänen? Sssagt esss mir!', 28153),
(133742, 'deDE', '', 'Sssprecht! Welche Geheimnisssse wissst Ihr vom Tempel?', 28153),
(133741, 'deDE', '', 'Ihr werdet ssssprechen oder ertrinken!', 28153),
(133732, 'deDE', 'Ihr rettet Shoak und ich bringe mich in Sicherheit. Dann müsst Ihr zumindest nicht uns beide retten.', '', 28153),
(133731, 'deDE', '[Nach einer kurzen Fahrt mit der Fähre...]', '[Nach einer kurzen Fahrt mit der Fähre...]', 28153),
(133730, 'deDE', 'Danke fürs Mitnehmen, Tae. Ich meld mich dann mal beim Alten.', '', 28153),
(133729, 'deDE', 'Dieser Idiot... Warum musste er sich auch von den Bluttrollen fangen lassen?', '', 28153),
(133728, 'deDE', '...Die Trolle von Natha\'vor haben Shoak.', '', 28153),
(133727, 'deDE', 'Nein... nein, nein!', '', 28153),
(133726, 'deDE', 'Oh nein...', '', 28153),
(133725, 'deDE', '...Hör auf, mich zu umkreisen, und finde Shoak!', '', 28153),
(133724, 'deDE', 'Was war\'n das für\'n Krach? Ich beschütz die Prinzessin, Ihr geht ma\' guck\'n.', '', 28153),
(133723, 'deDE', 'Fallhafen steht in Eurer Schuld, Fremdling. Sagt, wie können wir Euch entlohnen?', '', 28153),
(133722, 'deDE', 'Ich muss Euch wohl danken... Ich dachte, ich erwache nie aus diesem alptraumhaften Fluch...', '', 28153),
(133721, 'deDE', 'Was... was geht hier vor?', '', 28153),
(133720, 'deDE', '', 'Ihr seid zurück! Und die Bürger scheinen auch wieder zu sich zu kommen!', 28153),
(133719, 'deDE', '', 'Ihr könnt meinen Fluch... nicht aufhalten...', 28153),
(133718, 'deDE', '', 'Unsere Macht ist uralt. Ihr seid verloren!', 28153),
(133717, 'deDE', '', 'Werdet Zeuge der Macht des Zirkels!', 28153),
(133716, 'deDE', '', 'Wendet Euch ab, sonst wird das Schicksal des Dorfes auch Eures sein.', 28153),
(133715, 'deDE', '', 'Geistloser Fremdling! Dieses Dorf ist mein. So will es die Mutter!', 28153),
(133714, 'deDE', 'Sie ist gefährlich... aber nicht halb so gefährlich wie ich, wenn ich herausfinde, dass du etwas im Schilde führst!', 'Sie ist gefährlich... aber nicht halb so gefährlich wie ich, wenn ich herausfinde, dass du etwas im Schilde führst!', 28153),
(133713, 'deDE', 'Was immer du auch treibst, wehe, es hat etwas mit dieser verrückten Schrulle im Wald zu tun.', 'Was immer du auch treibst, wehe, es hat etwas mit dieser verrückten Schrulle im Wald zu tun.', 28153),
(133712, 'deDE', 'Mein allerwertester Mann! Ich weiß nicht, wen du zum Narren halten willst, aber ich weiß sehr wohl, dass du dich ins Vorgebirge schleichst, wenn du denkst, ich schlafe.', 'Mein allerwertester Mann! Ich weiß nicht, wen du zum Narren halten willst, aber ich weiß sehr wohl, dass du dich ins Vorgebirge schleichst, wenn du denkst, ich schlafe.', 28153),
(133711, 'deDE', 'Ich werde Ende dieser Woche noch einmal versuchen, sie zu liefern.', 'Ich werde Ende dieser Woche noch einmal versuchen, sie zu liefern.', 28153),
(133710, 'deDE', 'Meine Schweine verhalten sich seither ungewöhnlich aggressiv. Ich hatte Schwierigkeiten, sie für den Transport zusammenzutreiben.', 'Meine Schweine verhalten sich seither ungewöhnlich aggressiv. Ich hatte Schwierigkeiten, sie für den Transport zusammenzutreiben.', 28153),
(133709, 'deDE', 'Eine alte Dame an der Straße hat mir etwas Grünzeug für meine Schweine gegeben, aber ich befürchte, damit stimmte etwas nicht.', 'Eine alte Dame an der Straße hat mir etwas Grünzeug für meine Schweine gegeben, aber ich befürchte, damit stimmte etwas nicht.', 28153),
(133708, 'deDE', 'Geehrter Metzger Zwirbler, bitte entschuldigt die Verspätung der letzten Schweinelieferung.', 'Geehrter Metzger Zwirbler, bitte entschuldigt die Verspätung der letzten Schweinelieferung.', 28153),
(133707, 'deDE', 'Bürgermeister Weiß bittet um sofortige Meldung verdächtiger Personen oder Vorfälle.', '', 28153),
(133706, 'deDE', 'Des Weiteren erhalten wir Berichte von gefährlichen Kreaturen im Vorgebirge. Wir rufen jeden, der sich außerhalb der Stadt bewegt, zur Vorsicht auf.', '', 28153),
(133705, 'deDE', 'Zu ihrer Sicherheit haben alle Bewohner vor Sonnenuntergang ihre Häuser aufzusuchen.', '', 28153),
(133704, 'deDE', 'Aufgrund jüngster Vermisstenmeldungen tritt in Fallhafen eine strikte nächtliche Ausgangssperre in Kraft.', '', 28153),
(133703, 'deDE', 'Ich verwette meine letzte Fackel, dass diese alte Schachtel was damit zu tun hat!', 'Ich verwette meine letzte Fackel, dass diese alte Schachtel was damit zu tun hat!', 28153),
(133702, 'deDE', 'Wenn das so weitergeht, haben wir in einem Monat kein Schweinefutter mehr. Was ist das für ein Fluch?!', 'Wenn das so weitergeht, haben wir in einem Monat kein Schweinefutter mehr. Was ist das für ein Fluch?!', 28153),
(133701, 'deDE', 'Keine Ahnung, wo diese verdammten Fliegen herkommen, aber die schwirren seit zwei Wochen jeden Morgen hier herum.', 'Keine Ahnung, wo diese verdammten Fliegen herkommen, aber die schwirren seit zwei Wochen jeden Morgen hier herum.', 28153),
(133700, 'deDE', '', 'Seht Euch die letzten Einträge der Bürger an. Vielleicht finden wir so heraus, wer das getan hat.', 28153),
(133699, 'deDE', '', 'Mal sehen, ob ich etwas im Geschäftsbuch der Stadt finde. Wenn die Bürger etwas Verdächtiges gesehen haben, ist es vielleicht irgendwo vermerkt.', 28153),
(133698, 'deDE', '', 'Oh nein! Nicht auch noch hier!', 28153),
(133693, 'deDE', '', 'Ihr versteht nicht. Es gibt keinen sich\'ren Ort, wenn Jakra\'zet erfolgreich ist.', 28153),
(133692, 'deDE', '', 'Ich konnt\' Euch nich\' einfach dem Tod überlass\'n! Wir können vor all dem flieh\'n... an \'nem sicheren Ort \'n neues Leben beginnen.', 28153),
(133691, 'deDE', '', 'Ihr hättet mich nicht such\'n kommen soll\'n, Kaja.', 28153),
(133690, 'deDE', '', 'Ich dacht\', ich seh\' Euch nie wieder...', 28153),
(133689, 'deDE', 'Einige kaputte Totems sind besser als keine. Mal sehen, ob wir diesen Trottel finden können...', '', 28153),
(133688, 'deDE', 'SHOAK! Das ist nicht mehr witzig! Ich bin zu nah am Außenposten der Bluttrolle!', '', 28153),
(133686, 'deDE', '', 'Rakera! Ihr lebt!', 28153),
(133685, 'deDE', 'Zolani, meine Klinge! Wir müssen den Tempel verteidigen. Los!', '', 28153),
(133672, 'deDE', 'Meine Herrin kriegt ihr\'n Will\'n.', '', 28153),
(133670, 'deDE', 'Zeit zum Dreschen!', '', 28153),
(133669, 'deDE', 'Kommt, kleiner König. Lasst uns diese Ketzer zerstampfen!', '', 28153),
(133668, 'deDE', 'Aber ich schwör\' Euch und auch unserem Gast der Horde hier: Ich werd\' nich\' ruh\'n, bis ich Zuls Kopf hab!', '', 28153),
(133667, 'deDE', 'Ich bin weich geword\'n. Viele hab\'n versucht, mich zu warn\'... wie meine Tochter. Aber ich hab nich\' zugehört.', '', 28153),
(133666, 'deDE', 'Ihr müsst Euch also fragen: Seid Ihr König oder Beute?', '', 28153),
(133665, 'deDE', 'Man hat Euer Blut geleckt.', '', 28153),
(133664, 'deDE', 'Euer Rat fordert Euch heraus. Eure Freunde haben versucht, Euch umzubringen.', '', 28153),
(133663, 'deDE', 'Rastakhan, Eure Feinde attackieren Eure Grenzen.', '', 28153),
(133648, 'deDE', 'Großer Loa, seid Ihr noch am Leben? Ich befrei\' Euch aus den Kett\'n hier.', '', 28153),
(133646, 'deDE', 'Zul hat Euer Kommen vorhergesagt. Alles passiert so, wie er\'s prophezeit hat.', '', 28153),
(133645, 'deDE', '', 'Narr! Hätt ich die Zeit, würd ich Euch zerschmettern un\' Vol\'kaal räch\'n.', 28153),
(133644, 'deDE', '', 'Sterbt, Shadra, un\' kehrt nie wieder! Nach alt\'m Recht beanspruch ich Eure Macht!', 28153),
(133643, 'deDE', 'Ich gehe voraus, während Ihr diese Totems zerstört. Hoffentlich finden wir den Trottel, wenn diese Totems vernichtet sind.', '', 28153),
(133638, 'deDE', '', 'Vol\'kaal, werdet die Eindringlinge los, ich kümmer mich um Shadra.', 28153),
(133633, 'deDE', '', 'Shadra, Ihr habt mich lang geleitet. Aber von jetz\' an dien\' ich \'nem neu\'n Meister!', 28153),
(133632, 'deDE', '', 'Ihr kommt zu spät. Das Blut vom Loa wurd vergoss\'n!', 28153),
(133610, 'deDE', 'Gonk wütend! Gonk zerschmettert Yazma!', '', 28153),
(133606, 'deDE', 'Ich weiß Eure Taten zu würdigen. Ihr habt meinen Segen.', '', 28153),
(133605, 'deDE', 'Vielen Dank, $n. Ihr habt Euch meinen Segen verdient.', '', 28153),
(133591, 'deDE', '<Auf der Seite der Rakete ist eine kurze Nachricht eingeritzt.>$b$bACHTUNG: Offizielle Nachricht.$B$BWenn Ihr keinen Kommandantenrang innerhalb der Horde habt, NICHT WEITERLESEN!$b$bVon: Flick, Goblintrupp.$b$bMein Trupp wurde ausgesandt, um Feuerkraft zu stellen, damit unser Plan in Nazmir weiter voranschreitet. Wir liefern eine Kanone, die mit allem, was sich uns in den Weg stellt, kurzen Prozess macht.$B$BWir sind auf der \"Goldkelch\" und suchen an der östlichen Küste nach einem Ankerplatz. Schickt uns einen Lotsen, der uns zu einem Einsatzort bringt.', '', 28153),
(133582, 'deDE', '*Knurr* Ich werde vorerst hier verweilen, wenn auch nur, um den Geistern meiner fähigen Anhänger beizustehen, die ob Eurer Torheit ermordet wurden.', '', 28153),
(133581, 'deDE', 'Es war nur \'n einfacher Fehler... Aber seht Euch doch um! Werd\'n hier nich\' schöne Erinnerungen wach? Bleibt und lasst uns dies\'n Tempel Euch zu Ehren wieder aufbau\'n!', '', 28153),
(133580, 'deDE', 'Die Tortollaner hab\'n seltsame Bräuche, mein Gebieter. Wie sollte ich wiss\'n, dass die Ablehnung von \'nem Heiratsantrag als Kriegshandlung ausgelegt werd\'n würd?', '', 28153),
(133579, 'deDE', 'Eure Aufgabe war denkbar einfach: Schließt Frieden mit den Tortaka und haltet meinen Tempel instand, während ich fort bin. Und jetzt schaut ihn Euch an!', '', 28153),
(133578, 'deDE', '*Ähem* Ich bin\'s, großer Loa, Euer getreuer und verlässlicher Diener, Vunanju.', '', 28153),
(133576, 'deDE', '', 'Hier in Kul Tiras gibt es ein Sprichwort.$B$BWenn etwas schiefgeht, nehmen die Seeleute es einfach so hin und sagen: \"Den Wind kann man nicht ändern.\"$B$BWie ich diesen Spruch hasse.', 28153),
(133575, 'deDE', '', 'Carsten hat mich aufgezogen. Er hat mir beigebracht zu kämpfen, zu reiten und zu segeln.$B$BAls ich der Wache beitrat, war ich besser ausgebildet als einige meiner Ausbilder.$B$BDas gefiel ihnen nicht besonders gut.', 28153),
(133574, 'deDE', '', 'Als Daelin Prachtmeer besiegt wurde, änderte sich bei uns alles.$B$BAber Jaina hatte sicher gute Gründe... oder?', 28153),
(133573, 'deDE', '', 'In meiner Kindheit hörte ich Geschichten über das große Königreich Lordaeron.$B$BUnd auch über seinen Untergang.$B$BDie Geißel hat mir meine Mutter, meinen Vater und mein Heimatland genommen, bevor ich überhaupt alt genug war, um zu verstehen, was das bedeutete.', 28153),
(133572, 'deDE', 'Ich bin bereit, eine Entscheidung zu treffen.', 'Ich bin bereit, eine Entscheidung zu treffen.', 28153),
(133571, 'deDE', 'DAS TIER IST VÖLLIG WAHNSINNIG!', '', 28153),
(133570, 'deDE', '', 'Habt Ihr schon entschieden, was Ihr als Nächstes angeht?', 28153),
(133569, 'deDE', '', 'Ihr habt meinen Dank, $n.', 28153),
(133568, 'deDE', 'Wenn Ihr noch einmal verloren geht, bevor wir zurück sind, werde ich NICHT wieder nach Euch suchen!', '', 28153),
(133567, 'deDE', 'Kehren wir zu den anderen zurück. Es gibt so viel zu erzählen!', '', 28153),
(133566, 'deDE', 'Passt gut auf, diese Trolle sind nicht ganz richtig im Kopf. Warum fressen die ihre eigenen Leute auf?', '', 28153),
(133565, 'deDE', 'Oh... Das ist lecker! Davon hätte ich gern etwas mehr. Vielleicht beim nächsten Mal.', '', 28153),
(133564, 'deDE', 'Bin ich hungrig... Raptorfleisch klingt gerade richtig gut.', '', 28153),
(133563, 'deDE', 'Macht Euch bereit, denn der Herr aller Tiere is\' endlich zu uns zurückgekehrt!', '', 28153),
(133562, 'deDE', 'Klingenwache Kaja schickt mich.', 'Klingenwache Kaja schickt mich.', 28153),
(133561, 'deDE', '', 'Ich bin froh zu seh\'n, dass Julwaba am Leb\'n ist.', 28153),
(133560, 'deDE', '', 'Ich steh\' tief in Eurer Schuld, $n.', 28153),
(133559, 'deDE', '', 'Ich denk\', es is\' am besten, wenn Ihr den Anzug tragt und ins Lager geht. Ich kann nich\' garantieren, meine Klinge nich\' gegen die zu erheb\'n, die Rakera was angetan hab\'n.', 28153),
(133558, 'deDE', 'Unsere... Schätze...', '', 28153),
(133557, 'deDE', 'Diese Ssschätze gehören den Faulschuppen!', '', 28153),
(133556, 'deDE', 'Wir sind nur einfache Wursthersteller! Warum sollte uns jemand etwas tun wollen?', '', 28153),
(133555, 'deDE', '', 'Ich behalt den Menschen im Auge. Wenn er versucht zu flieh\'n, wird meine Klinge ihn aufzuhalt\'n wissen.', 28153),
(133554, 'deDE', 'Ich werde mich zum Strand aufmachen. Trefft mich dort, wenn Ihr habt, worum ich gebeten habe.', '', 28153),
(133553, 'deDE', 'Jetzt, da die Opfergaben bereit sind, hab\'n wir alles, was wir brauch\'n, um den Loa zu beschwör\'n.', '', 28153),
(133551, 'deDE', 'Die Zandalari können im Kampf gegen dieses Böse jede Hilfe brauchen. Glücklicherweise ist die Horde hier, um sie zu retten.', '', 28153),
(133548, 'deDE', '', 'Ich werd den hier im Auge behalt\'n un\' dafür sorg\'n, dass er sich nich\' ausm Staub macht.', 28153),
(133547, 'deDE', '', 'Es nähert sich eine blutige Flut. Sind wir verloren, $n?', 28153),
(133540, 'deDE', 'Geht, $n, seid ein Bote meines Zorns. Ich muss zu mei\'m Loa, bevor \'s zu spät is\'.', '', 28153),
(133539, 'deDE', '', 'Wie... Das Fleisch sollte mir... Kraft geb\'n...', 28153),
(133538, 'deDE', '', 'Das darf nich\' sein... Ihr dürft mich nich\' fressen! Ihr dürft nich\' meine Kraft krieg\'n!', 28153),
(133537, 'deDE', '', 'Was? Ich soll doch Kraft von Euerm Fleisch krieg\'n. Warum sterbt Ihr nich\'?!', 28153),
(133536, 'deDE', '', 'Ihr riecht nach Stärke... un\' ich werd stark, wenn ich Euch fresse!', 28153),
(133534, 'deDE', '', 'Ihr werdet dieses Artefakt nich\' krieg\'n!', 28153),
(133532, 'deDE', 'Ah, natürlich, wie dumm von mir... Ich hab die Opfergab\'n vergess\'n! Wir könn\' den Loa doch nich\' mit leeren Händen herbeiruf\'n!', '', 28153),
(133527, 'deDE', 'Hmm... Irgendwas muss da falsch lauf\'n. Der Götze is\' am richtig\'n Platz auf dem Altar. Warum also sollte der Loa nich\' zurückkehr\'n?', '', 28153),
(133526, 'deDE', '', 'Das is\' Rakeras Medaillon. Es wird allen Kriegswachen als Anerkennung für ihre Dienste für den König verlieh\'n. Zumindest hat sie\'s nich\' kampflos verlor\'n.', 28153),
(133516, 'deDE', 'Zul und alle, die ihm folg\'n, werd\'n schon sehr bald erfahr\'n, dass man \'nen Preis zahl\'t, wenn man \'nem Loa trotzt.\n\nUnd der Preis erhöht sich mit jedem Augenblick, der verstreicht.', '', 28153),
(133515, 'deDE', '', 'Wir sin\' hier! Was habt Ihr gefund\'n?', 28153),
(133514, 'deDE', '', 'Los, weiter. Wir müsst\'n bald da sein.', 28153),
(133505, 'deDE', '', 'Ich kämpfe an Eurer Seite, mein König. Die Horde wird für ihre Verbrechen zahlen. Ich blockiere den Eingang, damit wir uns formieren können.', 28153),
(133503, 'deDE', 'Das waren mindestens zwei. Und sie waren mächtig groß! Oh, und danke, dass Ihr mich geheilt habt.', '', 28153),
(133502, 'deDE', 'Ihr wurdet fast gefressen und... wie viele Speere waren in Eurem Bauch?', '', 28153),
(133501, 'deDE', 'Ah, Kajosh. Das hättet Ihr sehen müssen. Überall dunkle Magie, Trolle, die seltsame Sachen machen, und ich hatte sogar Speere in meinem Bauch!', '', 28153),
(133500, 'deDE', 'Idiot! Wisst Ihr eigentlich, welche Sorgen ich mir gemacht habe?!', '', 28153),
(133499, 'deDE', 'Das war verdammt knapp! Mir wird es bald wieder besser gehen, dieser alte Panzer hat schon ganz andere Sachen überstanden.', '', 28153),
(133498, 'deDE', 'Ich bin ja schon wach! War das wirklich nötig?', '', 28153),
(133497, 'deDE', '', 'Gut, Ihr habt mein Leuchtfeuer geseh\'n! Wo is\' Drekal?', 28153),
(133496, 'deDE', 'Argh... Es geht mir gut, ich kann mich bewegen. Ich werde zu Kajosh gehen... Ich wette, er ist... argh... ziemlich wütend!', '', 28153),
(133495, 'deDE', '', 'Hah... Jal\'aya hat... immer noch... Euer Artefakt...', 28153),
(133494, 'deDE', '', 'Ich glaub, wir ess\'n erst den Tortollaner un\' dann Euch!', 28153),
(133492, 'deDE', '', 'Der Markt beherbergt Reisende aus ganz Azeroth. Hier gibt es viele Tavernen, aber die hier mag ich am liebsten!', 28153),
(133490, 'deDE', '', 'Was ich in meinen Visionen geseh\'n hab... Zul und Yazma müss\'n aufgehalt\'n werd\'n, $n!', 28153),
(133489, 'deDE', 'Kajosh hat mich geschickt. Ich kümmere mich um die Rachenscheusale.', 'Kajosh hat mich geschickt. Ich kümmere mich um die Rachenscheusale.', 28153),
(133488, 'deDE', 'Argh... Wenn Ihr nicht hier seid, um mich zu fressen... dann verschwindet und rettet Euch selbst! \n\nDie Rachenscheusale werden jeden Moment zurück sein, um sich ihre \"Nahrung\" zu holen.', '', 28153),
(133487, 'deDE', 'Argh... Da kommen sie. Aufpassen!', '', 28153),
(133481, 'deDE', 'Das is\' nich\' Shadras Art. Was is\' mit ihr passiert?', 'Das is\' nich\' Shadras Art. Was is\' mit ihr passiert?', 28153),
(133480, 'deDE', 'Zul un\' Yazma steck\'n hinter dies\'m Verrat. Sie müss\'n aufgehalt\'n werd\'n!', 'Zul un\' Yazma steck\'n hinter dies\'m Verrat. Sie müss\'n aufgehalt\'n werd\'n!', 28153),
(133479, 'deDE', 'So wollte ich nich\' sterb\'n. Danke, dass Ihr mich gerettet habt!', 'So wollte ich nich\' sterb\'n. Danke, dass Ihr mich gerettet habt!', 28153),
(133478, 'deDE', 'Da werd ich mit dem Loa drüber sprech\'n müss\'n!', 'Da werd ich mit dem Loa drüber sprech\'n müss\'n!', 28153),
(133477, 'deDE', 'Heute ist ein so guter Tag für eine Schlacht wie jeder andere.', '', 28153),
(133476, 'deDE', 'Blutmagie is\' verbot\'n! Die Verräter müss\'n aufgehalten werd\'n!', '', 28153),
(133475, 'deDE', 'Ich bin... wieder der alte. Jetzt wird es Zeit für meine Rache.', '', 28153),
(133474, 'deDE', 'Shadra und ihre Schergen sind diesmal zu weit gegang\'n!', '', 28153),
(133473, 'deDE', 'Guuut! Meine Macht wächst. Entfesselt die Magie des letzten Totems.', '', 28153),
(133472, 'deDE', 'Findet Shoak. Ich werde hier warten.', '', 28153),
(133471, 'deDE', '...Er ist im Tempel hinter uns. Also, das war jetzt wirklich leicht.', '', 28153),
(133470, 'deDE', 'Aha! Er ist...', '', 28153),
(133469, 'deDE', 'Dafür wird Zul zahlen müss\'n!', '', 28153),
(133468, 'deDE', 'Ah, meine Stärke kehrt zurück. Schnell, entfesselt die Magie eines weiteren Totems.', '', 28153),
(133467, 'deDE', 'Möge der Loa Euch segnen!', '', 28153),
(133466, 'deDE', 'Tja, Shoak könnte irgendwo in Nazmir sein...', '', 28153),
(133465, 'deDE', 'Ich bin bereit. Wirkt den Zauber, damit wir Shoak finden.', 'Ich bin bereit. Wirkt den Zauber, damit wir Shoak finden.', 28153),
(133463, 'deDE', '', 'Glaub mir, das kenn ich. Wir fliegen schon bald, ja?', 28153),
(133461, 'deDE', '(Zurück)', '(Zurück)', 28153),
(133460, 'deDE', 'Ich könnte mein altes Essen aufessen, aber ich habe noch nie Raptorfleisch probiert. Da sollte ich doch besser die Chance nutzen und etwas Neues probieren?', '', 28153),
(133459, 'deDE', 'Einige der Totems sind zerstört. Wird Euer Zauber jetzt funktionieren?', 'Einige der Totems sind zerstört. Wird Euer Zauber jetzt funktionieren?', 28153),
(133455, 'deDE', '', 'Ah, da ist ja mein Mädchen. Du bist bestimmt ganz unruhig, ständig hier eingepfercht...', 28153),
(133450, 'deDE', 'Ihr werdet jetz\' sterb\'n.', 'Ihr werdet jetz\' sterb\'n.', 28153),
(133449, 'deDE', 'Zul hat dem Macht versproch\'n, der ihm Euern Kopf bringt.', 'Zul hat dem Macht versproch\'n, der ihm Euern Kopf bringt.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133448, 'deDE', 'Ich werd Zul Euern Kopf bring\'n.', 'Ich werd Zul Euern Kopf bring\'n.', 28153),
(133447, 'deDE', 'Ich werd Euern Geist auseinanderreiß\'n.', 'Ich werd Euern Geist auseinanderreiß\'n.', 28153),
(133446, 'deDE', 'Wir lass\'n Euch bluten, Mann.', 'Wir lass\'n Euch bluten, Mann.', 28153),
(133445, 'deDE', 'Wo is\' der König?', 'Wo is\' der König?', 28153),
(133444, 'deDE', 'Wir werd\'n Euern Kopf auf \'ne Pike pflanzen.', 'Wir werd\'n Euern Kopf auf \'ne Pike pflanzen.', 28153),
(133443, 'deDE', 'Mein Leben für Zul!', 'Mein Leben für Zul!', 28153),
(133438, 'deDE', '<Die Oberfläche des Altars weist eine Vertiefung auf und an den Ecken sind deutliche Einkerbungen zu sehen.$b$bAuf diesem Altar muss einst ein schweres, großes Objekt seinen Platz gehabt haben.$b$bAber was immer es war, es ist nicht mehr da.>', '', 28153),
(133432, 'deDE', 'Untersucht den Altar.', 'Untersucht den Altar.', 28153),
(133430, 'deDE', '<Der Raum scheint leer zu sein.$b$bDen Altar vor Euch zieren Gravuren uralter Zandalariglyphen und Bilder des Loas Eraka no Kimbul.$b$bEinst schien auf dem Altar etwas gestanden zu haben. Eine Statue vielleicht?>', '', 28153),
(133428, 'deDE', '', 'Das Zählhaus wird Tag und Nacht schwer bewacht. Hier könnt Ihr Eure Wertsachen gefahrlos aufbewahren.', 28153),
(133412, 'deDE', 'Die Zanchuli seh\'n alles!', 'Die Zanchuli seh\'n alles!', 28153),
(133411, 'deDE', 'Ihr könnt Euch nich\' vor mir versteck\'n!', 'Ihr könnt Euch nich\' vor mir versteck\'n!', 28153),
(133410, 'deDE', 'Zul wird Eure Geheimnisse erfahr\'n!', 'Zul wird Eure Geheimnisse erfahr\'n!', 28153),
(133409, 'deDE', 'Euer Leben is\' verwirkt!', 'Euer Leben is\' verwirkt!', 28153),
(133407, 'deDE', 'Ihr werdet mir nich\' in die Quere kommen, Eindringling!', 'Ihr werdet mir nich\' in die Quere kommen, Eindringling!', 28153),
(133406, 'deDE', 'Zandalar gehört jetz\' den Zanchuli!', 'Zandalar gehört jetz\' den Zanchuli!', 28153),
(133405, 'deDE', 'Für Zul! Für die Zanchuli!', 'Für Zul! Für die Zanchuli!', 28153),
(133404, 'deDE', 'Wir Zanchuli nehm\'n uns, was wir woll\'n!', 'Wir Zanchuli nehm\'n uns, was wir woll\'n!', 28153),
(133403, 'deDE', 'Eure Macht wird mir gehör\'n!', 'Eure Macht wird mir gehör\'n!', 28153),
(133402, 'deDE', 'Euer Tod wird mich stärker mach\'n!', 'Euer Tod wird mich stärker mach\'n!', 28153),
(133401, 'deDE', 'Mehr Blut für Zul!', 'Mehr Blut für Zul!', 28153),
(133392, 'deDE', '', 'Diese Fähre verbindet mehrere Anlegestellen an der inneren Küste des Sunds.', 28153),
(133389, 'deDE', '', 'Ihr benötigt einen Fährenpass von der Hafenmeisterei. Das sollte aber kein Problem sein.', 28153),
(133387, 'deDE', '', 'Keine Sorge wegen dem Ausbruch. Auf dem Markt seid Ihr nur ein Reisender in der Menge. Also dann führe ich Euch mal rum!', 28153),
(133380, 'deDE', '', 'Ich spar mir Euren Kopf für später auf!', 28153),
(133379, 'deDE', '', 'Ihr werdet mich lange satt mach\'n!', 28153),
(133374, 'deDE', '', 'Ich werd Eure Knochen kau\'n!', 28153),
(133372, 'deDE', '', 'Macht die Stacheln klar, es kommt Futter!', 28153),
(133371, 'deDE', '', 'Ah, neues Futter für mich!', 28153),
(133370, 'deDE', '', 'Eure Schenkel werd\'n \'ne gute Mahlzeit abgeb\'n!', 28153),
(133369, 'deDE', '', 'Jetzt hab\'n wir Essen!', 28153),
(133368, 'deDE', '', 'Ihr seht aber lecker aus!', 28153),
(133359, 'deDE', 'Das ist nicht das erste Mal, dass Shoak verloren gegangen ist. Bei all dem Ärger, den wir haben, hoffe ich, dass er wirklich in Schwierigkeiten steckt.', '', 28153),
(133357, 'deDE', 'Auf die Beine! Dieses Azerit baut sich nicht von selbst ab.', 'Auf die Beine! Dieses Azerit baut sich nicht von selbst ab.', 28153),
(133356, 'deDE', 'Ich bin bereit, Euch zum Tempel zu begleiten.', 'Ich bin bereit, Euch zum Tempel zu begleiten.', 28153),
(133355, 'deDE', 'Ich hätt\' es besser wissen und diesen hinterhältig\'n Tortaka nie vertrau\'n sollen! Ich kann nicht fass\'n, dass sie mich getötet und für hundert Jahre in diesem Glas eingeschloss\'n haben... oder waren es gar zweihundert? Ich weiß es schon gar nicht mehr!', '', 28153),
(133354, 'deDE', '<Ein schrecklicher Schmerzensschrei hallt durch Zeb\'ahari.>', '<Ein schrecklicher Schmerzensschrei hallt durch Zeb\'ahari.>', 28153),
(133351, 'deDE', 'Ich mach mich auf die Suche nach dem Loa. Trefft mich im Tempel, wenn Ihr hier fertig seid.', '', 28153),
(133350, 'deDE', 'Endlich frei... Habt Dank dafür, dass Ihr mich aus diesem verflucht\'n Gefäß befreit habt! War ganz schön eng da drin... sogar für \'nen Geist!', '', 28153),
(133349, 'deDE', '', 'Diese Mauern werden nicht lange halten. Wir sollten hier nicht bleiben.', 28153),
(133348, 'deDE', '', 'Fabelhafte Arbeit, Mann! Sprecht mich einfach an, wenn Ihr bereit seid. Wir müss\'n zurück in diesen Krieg.', 28153),
(133346, 'deDE', '', 'Ich komm zu Euch... Blutgott. Das is\' nich\' das Ende.', 28153),
(133345, 'deDE', '', 'Der Blutgott kriegt seinen Tribut früher oder später. Ihr könnt uns nich\' aufhalt\'n!', 28153),
(133344, 'deDE', '', 'Die Prinzessin will sofort unsern Bericht hör\'n. Wir lass\'n sie ma\' besser nich\' wart\'n.', 28153),
(133343, 'deDE', 'Beißt die Zähne zusamm\'n.', '', 28153),
(133342, 'deDE', 'Jetzt wird nich\' gestorb\'n. Wir hab\'n noch zu tun.', '', 28153),
(133341, 'deDE', 'Erhebt Euch. Wir sind noch nich\' fertig mit Euch.', '', 28153),
(133340, 'deDE', 'Erhebt Euch! Wir brauch\'n Euch.', '', 28153),
(133339, 'deDE', 'Erhebt Euch!', '', 28153),
(133338, 'deDE', 'Erhebt Euch! Euer König braucht Euch.', '', 28153),
(133337, 'deDE', 'Ich bin bereit für den Kampf gegen die Bluttrolle.', 'Ich bin bereit für den Kampf gegen die Bluttrolle.', 28153),
(133336, 'deDE', 'Die Bluttrolle formieren sich für einen neuen Angriff auf mich und meine Kinder.$b$bDieses Mal werden es aber sie selbst sein, die sterben!$b$bSeid Ihr bereit?', '', 28153),
(133325, 'deDE', 'Angreifer von der Horde sind auf dem Weg zur Kaserne!', 'Angreifer von der Horde sind auf dem Weg zur Kaserne!', 28153),
(133305, 'deDE', '', 'Ihr fühlt Euch bald wie zu Hause. Und jetzt schauen wir mal bei Carsten vorbei!', 28153),
(133304, 'deDE', '', 'Ist sie nicht hübsch? Carsten schenkte sie mir, als sie noch ein Küken war.', 28153),
(133303, 'deDE', 'Ich schließe mich Eurem Kreuzzug gegen die Bluttrolle an. Doch zunächst muss ich wieder zu Kräften kommen. Helft Ihr mir?', '', 28153),
(133302, 'deDE', 'Zentimo hat mir gut gedient. Sein Geist wird unter meinen Kindern weiterleben.', '', 28153),
(133300, 'deDE', 'Randall Rotmond spuckt in den Sand.', '', 28153),
(133298, 'deDE', 'Hilfe! Haltet mir diese Dinger vom Leib!', '', 28153),
(133297, 'deDE', '', 'Seine Verletzungen war\'n zu schwer... Es tut mir leid.', 28153),
(133295, 'deDE', 'Vunanju? *Knurr* Ich hätte es wissen sollen...', '', 28153),
(133294, 'deDE', 'Wer wagt es, mich in diesem heruntergekommenen Tempel zu beschwören?', '', 28153),
(133274, 'deDE', 'Ich geh vor, das Ritual vorbereit\'n. Trefft mich dort, wenn Ihr fertig seid.', '', 28153),
(133265, 'deDE', 'Seht die Pracht von Eraka no Kimbul, Loa der Tiger, Herr aller Tiere, König aller Katz\'n und Untergang seiner Beute!', '', 28153),
(133264, 'deDE', 'Ihr habt den Götz\'n gefund\'n! Jetz\', wo er an Ort und Stelle steht, könn\' wir den Loa herbeiruf\'n...', '', 28153),
(133263, 'deDE', '', 'Ich bring ihn zurück zu seinem Loa und töte alle, die an Euch vorbeikomm\'n.', 28153),
(133261, 'deDE', 'Die Kaserne wurde zerstört! Baut sie wieder auf!', 'Die Kaserne wurde zerstört! Baut sie wieder auf!', 28153),
(133260, 'deDE', 'Die Schmiede wurde zerstört! Baut sie wieder auf!', 'Die Schmiede wurde zerstört! Baut sie wieder auf!', 28153),
(133259, 'deDE', 'Die Ställe wurden zerstört! Baut sie wieder auf!', 'Die Ställe wurden zerstört! Baut sie wieder auf!', 28153),
(133258, 'deDE', 'Die Werkstatt wurde zerstört. Baut sie wieder auf!', 'Die Werkstatt wurde zerstört. Baut sie wieder auf!', 28153),
(133254, 'deDE', 'Ich habe nicht einmal eine Waffe!', '', 28153),
(133253, 'deDE', 'Ich will nicht sterben!', '', 28153),
(133252, 'deDE', 'So kann ich nicht arbeiten!', '', 28153),
(133251, 'deDE', 'Es funktioniert! Seid bereit!', '', 28153),
(133250, 'deDE', 'Wir werden einen Fossilisationsumkehrzauber einsetzen. Bleibt zurück!', '', 28153),
(133249, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(133248, 'deDE', 'Wenn das funktionieren sollte, erwartet nicht, dass Xibala sich zahm verhält.\n\nIch hoffe, Ihr seid vorbereitet, alles Notwendige zu tun, um ihn zu überwältigen.', '', 28153),
(133247, 'deDE', '', 'Hier drüb\'n. Hier is\' einer verletzt.', 28153),
(133240, 'deDE', '', 'Ich biete in diesem feindseligen Land so viel Schutz, wie ich nur kann.', 28153),
(133239, 'deDE', 'Das war mein Zuhause, bevor die Zandalari beschlossen haben, ein Haus um mich herum zu bauen.', '', 28153),
(133224, 'deDE', 'Der Götze muss in den Tempel von Kimbul zurückgebracht werd\'n. Ihr haltet den Schlüssel zur Rückkehr des Loas in den Händ\'n!', '', 28153),
(133223, 'deDE', 'Mein Geist is\' schwach und mir bleibt nich\' viel Zeit, $gReisender:Reisende;. Hört genau auf meine Worte...', '', 28153),
(133214, 'deDE', 'Und jetz\' lasst uns verschwind\'n. Weiter vorne is\'n Schrein, Zo\'bal genannt. Trefft mich da.', '', 28153),
(133213, 'deDE', 'Der Kommandant der Horde wurde besiegt! Ihr wart siegreich!', 'Der Kommandant der Horde wurde besiegt! Ihr wart siegreich!', 28153),
(133212, 'deDE', 'Großartig! Der Orcabschaum hat offenbar einige starke Sprengsätze zurückgelassen. Was wohl passieren würde, wenn wir die in der Nähe ihrer hässlichen Gebäude da drüben abwerfen?', '', 28153),
(133207, 'deDE', 'Das Areal wurde schon vor langer Zeit von den Geistern der Vergangenheit verlass\'n, und das aus gutem Grund.\n\nDie Horde kann hier gern versuch\'n, was herauszufind\'n, wenn sie sich traut...', '', 28153),
(133204, 'deDE', 'Selbst im Tod blieb\'n die Geister meines Volks dem großen Loa Eraka no Kimbul treu. Die Bande unseres Glaubens sind zeitlos und stärker als der kalte Griff des Todes selbst.', '', 28153),
(133201, 'deDE', 'Wir brauchen die Mine, aber diese verdammten Orcs sind uns im Weg. Also lasst uns da runtergehen und sie ausmerzen, damit die Arbeiter mit unserem Kasernenbau beginnen können.', '', 28153),
(133200, 'deDE', 'Jetzt ist diese hässliche Fratze endlich weg. Schafft jetzt dieses Banner fort, dann können wir uns an die Arbeit machen.', '', 28153),
(133199, 'deDE', 'Na gut, Leute. Wir müssen hier eine Basis errichten, wenn wir diesen orcischen Befehlshaber aus dem Weg räumen und seine Basis ein für alle Mal vernichten wollen.', '', 28153),
(133198, 'deDE', '', 'Das ändert... gar nichts! Bald... werdet Ihr alle... sterb\'n...', 28153),
(133197, 'deDE', 'Ihr seid $gder:die; erste Sterbliche, $gder:die; meinen Tempel seit vielen Jahren betritt. Es erfreut mich, wieder Anhänger unter den Lebenden zu haben.', '', 28153),
(133158, 'deDE', '', 'Wir haben\'s geschafft. Stellt Euch nur mal vor, was passier\'n wird, wenn das große Konstrukt durch die Mauern von Zuldazar bricht und die alle reinlässt. Mehr Loa auf unsrer Seite sind da \'ne große Hilfe.', 28153),
(133157, 'deDE', '', 'Schaut Euch die alle an! Alle aufm Weg nach Zuldazar... Passt auf! Kopf runter!', 28153),
(133156, 'deDE', '', 'Die Insel is\' südlich von hier. Ich wart dort auf Euch.', 28153),
(133155, 'deDE', '', 'Hier drüb\'n. Das Boot is\' bereit, wenn Ihr\'s seid. Hoffentlich sin\' da keine Ungeheuer im Fluss, was?', 28153),
(133154, 'deDE', 'LOS GEHTS!', '', 28153),
(133153, 'deDE', 'ABER LASST ES NICHT EXPLODIEREN!', '', 28153),
(133152, 'deDE', 'HAUT WEITER DRAUF!', '', 28153),
(133151, 'deDE', 'Was kann ich für Euch tun, $gBürschchen:Mädel;?', '', 28153),
(133150, 'deDE', 'Ich sage Euch was. Alles was Ihr da drin findet, gehört Euch. Das ist meine Art, danke zu sagen.', '', 28153),
(133149, 'deDE', 'AAAAAa....aahhhh....', '', 28153),
(133143, 'deDE', 'Eure Anwesenheit hier gleicht \'ner Entweihung! Fürchtet Xibala!', '', 28153),
(133141, 'deDE', 'In der Werkstatt können jetzt Zwergengrenadiere rekrutiert werden.', 'In der Werkstatt können jetzt Zwergengrenadiere rekrutiert werden.', 28153),
(133140, 'deDE', 'In der Schmiede können jetzt Scharfschützen rekrutiert werden.', 'In der Schmiede können jetzt Scharfschützen rekrutiert werden.', 28153),
(133139, 'deDE', 'In den Ställen können jetzt Ritter rekrutiert werden.', 'In den Ställen können jetzt Ritter rekrutiert werden.', 28153),
(133138, 'deDE', 'In der Kaserne können jetzt Fußsoldaten rekrutiert werden.', 'In der Kaserne können jetzt Fußsoldaten rekrutiert werden.', 28153),
(133136, 'deDE', '', 'Nicht mehr weit. Die erste Präsenz, die ich gespürt hab, war irgendwo neb\'m Wasser.', 28153),
(133133, 'deDE', '', 'Hm... die Opfergaben sin\' frisch. Bwonsamdi hat anscheinend \'nen Anhänger hier im Sumpf.', 28153),
(133131, 'deDE', 'Zu viele Bluttrolle. Ich kämpfe nich\' mehr.', '', 28153),
(133126, 'deDE', 'Die Horde hat ein Gebäude verloren. Die Schmiede kann jetzt gebaut werden.', 'Die Horde hat ein Gebäude verloren. Die Schmiede kann jetzt gebaut werden.', 28153),
(133125, 'deDE', 'Die Horde hat ein Gebäude verloren. Die Werkstatt kann jetzt gebaut werden.', 'Die Horde hat ein Gebäude verloren. Die Werkstatt kann jetzt gebaut werden.', 28153),
(133124, 'deDE', 'Die Horde hat ein Gebäude verloren. Die Ställe können jetzt gebaut werden.', 'Die Horde hat ein Gebäude verloren. Die Ställe können jetzt gebaut werden.', 28153),
(133123, 'deDE', '', 'Da... Folgt dem Phantom. Find\'n wir raus, wo der Anhänger Bwonsamdis hin is\'.', 28153),
(133122, 'deDE', '', '\'ne Bluttrollfrau? Sieht aus, als ob sie geopfert wurde. Seht, der Mörder hat \'nen Dolch dagelassen! \'n kleiner Zauber und...', 28153),
(133114, 'deDE', 'HOLT MICH HIER RAUS!', '', 28153),
(133113, 'deDE', 'Die Bombe wurde fallen gelassen!', 'Die Bombe wurde fallen gelassen!', 28153),
(133112, 'deDE', 'Die Bombe wurde aufgehoben!', 'Die Bombe wurde aufgehoben!', 28153),
(133111, 'deDE', 'Gleich explodiert hier eine Bombe! Verschwindet!', 'Gleich explodiert hier eine Bombe! Verschwindet!', 28153),
(133108, 'deDE', 'Fußsoldat [25 Kriegsfrontgold] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 'Fußsoldat [25 Kriegsfrontgold] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'deDE', 'Lasst uns anfangen.', 'Lasst uns anfangen.', 28153),
(133103, 'deDE', 'NEU VERWENDEN', 'NEU VERWENDEN', 28153),
(133102, 'deDE', 'Unsere Arbeit geht dank der Störungen durch die Allianz nur sehr langsam voran!', 'Unsere Arbeit geht dank der Störungen durch die Allianz nur sehr langsam voran!', 28153),
(133101, 'deDE', 'Ich könnte wesentlich mehr schaffen, wenn ich nicht ständig nach Allianzsaboteuren Ausschau halten müsste...', 'Ich könnte wesentlich mehr schaffen, wenn ich nicht ständig nach Allianzsaboteuren Ausschau halten müsste...', 28153),
(133100, 'deDE', 'Die Allianz hat keinen Anspruch auf dieses Land! Zuldazar ist Territorium der Horde!', 'Die Allianz hat keinen Anspruch auf dieses Land! Zuldazar ist Territorium der Horde!', 28153),
(133099, 'deDE', 'Wir kommen hier nicht entscheidend weiter, solange wir die verdammten Zwerge nicht aus dem Land vertrieben haben!', '', 28153),
(133085, 'deDE', '', 'Die Allianz... wird siegen...', 28153),
(133084, 'deDE', '', 'Das ist eine offizielle Ausgrabungsstätte der Forscherliga. Ihr habt sie unbefugt betreten!', 28153),
(133069, 'deDE', 'Für die Allianz!', 'Für die Allianz!', 28153),
(133066, 'deDE', 'Fort mit Euch, Eindringling!', 'Fort mit Euch, Eindringling!', 28153),
(133065, 'deDE', 'Diese Artefakte werden uns gehören!', 'Diese Artefakte werden uns gehören!', 28153),
(133064, 'deDE', 'Nieder mit der Archäologischen Akademie!', 'Nieder mit der Archäologischen Akademie!', 28153),
(133055, 'deDE', '', 'Hallo, Ihr da! Schon mal mit verbundenen Augen eine Rakete abgefeuert, die auf Eurem Rücken festgeschnallt ist? Ich schon!', 28153),
(133054, 'deDE', 'Die Allianz muss ausgelöscht werden. Zuldazar gehört der Horde!', '', 28153),
(133053, 'deDE', 'Das war unglaublich. Was für ein Fund!', '', 28153),
(133048, 'deDE', '', 'Ich habe zahllose Reisende nach ihren Geschichten gelöchert, ganz besonders, wenn sie aus den Östlichen Königreichen kamen.', 28153),
(133047, 'deDE', '', 'Da sind wir – der Hafen von Boralus. Nach Burg Prachtmeer ist das der am schwersten bewachte Teil der Stadt und der einzige, den die meisten Besucher je betreten werden.', 28153),
(133045, 'deDE', '', 'Ihr habt Glück, dass er überhaupt bezahlt. Und jetzt rudert!', 28153),
(133044, 'deDE', 'Ein Abgesandter der Allianz? Das hat Carsten nicht erwähnt... Ich hätte das Doppelte verlangt.', '', 28153),
(133043, 'deDE', '', 'Ihr seid mit Jaina Prachtmeer hier! Ihr müsst der Abgesandte der Allianz sein!', 28153),
(133042, 'deDE', '', 'Wartet... ich kenne Euch...', 28153),
(133041, 'deDE', 'Ach, und das Ziel gerettet hab ich natürlich auch. Gaunerkumpel, Taelia. Taelia, Gaunerkumpel.', '', 28153),
(133040, 'deDE', '', 'Was geht da drin vor? Klingt, als hättet Ihr einen Aufstand angezettelt!', 28153),
(133039, 'deDE', 'Keine Ahnung, wovon Ihr redet... aber ich glaube, wir haben endlich was gegen Aschenwind in der Hand.', '', 28153),
(133038, 'deDE', 'Da ist sie ja! Alle einsteigen!', '', 28153),
(133037, 'deDE', 'Jetzt müssen wir in den tieferen Ebenen \'nen Weg nach draußen suchen.', '', 28153),
(133036, 'deDE', 'Ah, schon besser. Ohne die hab ich mich nackt gefühlt! Gut, weiter geht\'s.', '', 28153),
(133013, 'deDE', '', 'Ob Ihr einen neuen Teppich oder einen Mantel braucht, wir haben die passenden Felle für Euch!', 28153),
(133012, 'deDE', '', 'Felle zum Wärmen, Funktionsfelle, kuschelige Felle!', 28153),
(133011, 'deDE', '', 'Hochwertige Felle aus ganz Kul Tiras!', 28153),
(133009, 'deDE', '', 'Die verlässlichsten Erfindungen in ganz Tiragarde! Das ist Fakt!', 28153),
(133008, 'deDE', '', 'Vertraut niemals den gnomischen Erfindungen anderer Anbieter! Meine Konkurrenten sind alle Betrüger!', 28153),
(133007, 'deDE', '', 'Bei mir findet Ihr die besten Spielereien und Gerätschaften!', 28153),
(133001, 'deDE', 'Was...? Wird der... noch größer? Aaaah!', 'Was...? Wird der... noch größer? Aaaah!', 28153),
(132999, 'deDE', 'Anheben', 'Anheben', 28153),
(132994, 'deDE', 'Magier, lasst uns zum Lager zurückkehren. Wir haben viel zu untersuchen!', '', 28153),
(132993, 'deDE', 'Mist! Das hat ganz schön gerumst! Also die Schlüssel sind hin.', '', 28153),
(132992, 'deDE', 'Nehmt Euer Zeug und dann ab zum Wärter. Wir brauchen seine Schlüssel.', '', 28153),
(132991, 'deDE', 'Schätze, da geht\'s nicht raus. Gehen wir zur anderen Seite.', '', 28153),
(132990, 'deDE', 'Kaserne verfügbar', 'Kaserne verfügbar', 28153),
(132989, 'deDE', 'Aufstand, Jungs! Macht sie platt!', '', 28153),
(132988, 'deDE', '[Zellentüren schwingen auf. Die Insassen stürmen hinaus und rennen den Gang hinab.]', '[Zellentüren schwingen auf. Die Insassen stürmen hinaus und rennen den Gang hinab.]', 28153),
(132987, 'deDE', 'Angreifer von der Horde sind auf dem Weg zur Werkstatt!', 'Angreifer von der Horde sind auf dem Weg zur Werkstatt!', 28153),
(132986, 'deDE', 'Fußsoldaten herbeirufen', 'Fußsoldaten herbeirufen', 28153),
(132985, 'deDE', 'Die Kaserne wurde erobert und wird wiederaufgebaut.', 'Die Kaserne wurde erobert und wird wiederaufgebaut.', 28153),
(132981, 'deDE', 'Angreifer von der Horde sind auf dem Weg zu den Ställen!', 'Angreifer von der Horde sind auf dem Weg zu den Ställen!', 28153),
(132980, 'deDE', 'Angreifer von der Horde sind auf dem Weg zur Schmiede!', 'Angreifer von der Horde sind auf dem Weg zur Schmiede!', 28153),
(132969, 'deDE', '', 'Mama, alle meine Freunde spielen ohne mich! Kann ich bitte, bitte gehen?', 28153),
(132968, 'deDE', '', 'Mir ist langweilig! Kann ich spielen gehen?', 28153),
(132967, 'deDE', '', 'Sind wir mit den Erledigungen endlich fertig?', 28153),
(132966, 'deDE', 'Damit sollte er zumindest wieder auf die Beine kommen.', '', 28153),
(132957, 'deDE', '', 'Dieses alte Ding?$B$B<Sie lacht herzlich.>$B$BSeht Euch um. Wo, glaubt Ihr, habe ich das her?', 28153),
(132955, 'deDE', 'Ein ziemlich interessanter Schild. Woher habt Ihr ihn?', 'Ein ziemlich interessanter Schild. Woher habt Ihr ihn?', 28153),
(132954, 'deDE', '', 'Ich bin vielleicht etwas kurz geraten, aber ich habe einen kräftigeren Hammerschwung als der meiste Hordendreck, der sich hier ansammelt.', 28153),
(132945, 'deDE', 'Was treibt Ihr hier draußen?', 'Was treibt Ihr hier draußen?', 28153),
(132944, 'deDE', 'Ich hab genau das Richtige dafür. Zeigen wir\'s ihm.', '', 28153),
(132943, 'deDE', 'Da kommt ein Riese. Hey, ist das nicht der Typ, der unser Boot kaputt gemacht hat? Rache ist Blutwurst!', '', 28153),
(132941, 'deDE', 'Hört mal her, $gBursche:Mädel;... Ich, äh, hab vergessen, was ich sagen wollte. Wie dem auch sei, fasst hier besser nichts an.$B$BIch will keine Blutflecken auf meinen Gerätschaften.', '', 28153),
(132940, 'deDE', 'Durch meine Größe brauchen meine Gefühle länger, um ihr volles Potenzial zu entfalten.$B$BHabt Geduld.', '', 28153),
(132939, 'deDE', 'Zuerst mal müssen wir die Präzision der Kanone prüfen, und wenn wir schon dabei sind, warum nicht gleichzeitig diese Naga loswerden?', '', 28153),
(132938, 'deDE', 'Vorsicht! Sie feuern auf unsere Position. Schaltet sie mit Splitterschüssen aus!', '', 28153),
(132935, 'deDE', 'Unter uns! Passt auf!', '', 28153),
(132932, 'deDE', '', 'Tatsächlich... Flieg\'n wir nach Westen. Ich will keine unnötigen Konflikte.', 28153),
(132931, 'deDE', 'Ihre Zahl scheint gewachsen zu sein.', '', 28153),
(132928, 'deDE', 'Sucht Ihr Schutz oder wollt Ihr handeln?', 'Sucht Ihr Schutz oder wollt Ihr handeln?', 28153),
(132926, 'deDE', 'Alles fertig, kann losgehen. Einfach aufsitzen.', '', 28153),
(132924, 'deDE', 'Schnell! Der Hebel!', '', 28153),
(132923, 'deDE', 'Kommt, unsere Fahrgelegenheit sollte schon am Strand warten.', '', 28153),
(132922, 'deDE', '', 'Weg da! Auf dem Gold steht MEIN Name.', 28153),
(132920, 'deDE', 'Fünfzigtausend Goldstücke für denjenigen, der als erstes am Einsatzort ankommt.', '', 28153),
(132918, 'deDE', 'Aber ich hab hier doch gerade erst alles mit Minen gesichert!', '', 28153),
(132917, 'deDE', 'Jetzt reicht\'s mir endgültig mit diesem Knast.', '', 28153),
(132916, 'deDE', 'Uff... stinkt ja wie \'ne Piratenunterhose.', '', 28153),
(132915, 'deDE', 'Okay, Team, los geht\'s.', '', 28153),
(132912, 'deDE', 'Wer nicht wagt, der nicht gewinnt. Junge, Junge, Ihr müsst echt mal mehr wetten.', '', 28153),
(132911, 'deDE', '', 'Ach, 80 Prozent ist \'ne Menge. Warum übertreiben und den Deal aufs Spiel setzen?', 28153),
(132910, 'deDE', 'Nur 80 Prozent? Ihr könnt noch viel höher gehen. Wo ist denn Eure Gier?', '', 28153),
(132909, 'deDE', 'Willkommen zurück im Goldhauer, Schwesta. Hier seid Ihr immer unter Euresgleich\'n.\n\nEntspannt Euch un\' ruht Euch erstmal aus, dann trink\'n wir ein\'n!', '', 28153),
(132908, 'deDE', 'Willkommen zurück im Goldhauer, Bruda. Hier seid Ihr immer unter Euresgleich\'n.\n\nEntspannt Euch un\' ruht Euch erstmal aus, dann trink\'n wir ein\'n!', '', 28153),
(132907, 'deDE', 'Was tut Ihr da? Das ist meine Ausrüstung!', 'Was tut Ihr da? Das ist meine Ausrüstung!', 28153),
(132906, 'deDE', 'Hilfe! Hier sabotiert einer!', 'Hilfe! Hier sabotiert einer!', 28153),
(132905, 'deDE', 'Das ist empfindliche Ausrüstung!', 'Das ist empfindliche Ausrüstung!', 28153),
(132904, 'deDE', 'He! Weg von meiner Ausrüstung!', 'He! Weg von meiner Ausrüstung!', 28153),
(132897, 'deDE', 'Lasst mich ausm Käfig raus! Ich schwör, ich bin unschuldig!', 'Lasst mich ausm Käfig raus! Ich schwör, ich bin unschuldig!', 28153),
(132893, 'deDE', 'Seh ich auch so, Grenja. $p wär genau richtig, wenn Zulsan nich\' zurückkommt.', '', 28153),
(132891, 'deDE', 'Wer hatte eigentlich die Idee, so nahe an diese verfluchte Grotte heranzusegeln?', 'Wer hatte eigentlich die Idee, so nahe an diese verfluchte Grotte heranzusegeln?', 28153),
(132890, 'deDE', 'Endlich hat der Gesang aufgehört!', 'Endlich hat der Gesang aufgehört!', 28153),
(132889, 'deDE', 'Ist das... Bier?', 'Ist das... Bier?', 28153),
(132880, 'deDE', 'Ha, das zieht immer wieder...', '', 28153),
(132879, 'deDE', 'Ich hab das Blut und die Stacheln aufkoch\'n lass\'n und in unsren zeremoniellen Goldhauerkelch gefüllt... Das is\' \'ne Ananas. Esst die bloß nich\'. Wir haben nur die eine.', '', 28153),
(132877, 'deDE', 'Danke, dass Ihr mich gerettet habt!', '', 28153),
(132876, 'deDE', 'Danke! Wir sehen uns dann am Treffpunkt!', '', 28153),
(132849, 'deDE', 'Jetzt erkenne ich, dass ich fast in eine böse Falle getappt wäre... Danke!', 'Jetzt erkenne ich, dass ich fast in eine böse Falle getappt wäre... Danke!', 28153),
(132848, 'deDE', 'Ich weiß nicht, was in mich gefahren ist...', 'Ich weiß nicht, was in mich gefahren ist...', 28153),
(132847, 'deDE', 'Bitte rettet die anderen... Ich gehe unverzüglich zu Kimbul.', 'Bitte rettet die anderen... Ich gehe unverzüglich zu Kimbul.', 28153),
(132846, 'deDE', 'Beinahe hätten sie mich ausgelöscht... Ihr habt meinen Dank, Fremdling.', 'Beinahe hätten sie mich ausgelöscht... Ihr habt meinen Dank, Fremdling.', 28153),
(132845, 'deDE', 'Diese Täuschung hätte mich fast meine Seele gekostet...', 'Diese Täuschung hätte mich fast meine Seele gekostet...', 28153),
(132844, 'deDE', 'Jetzt sehe ich, dass es nur eine Verzauberung war. Ich werde zu Kimbul gehen...', 'Jetzt sehe ich, dass es nur eine Verzauberung war. Ich werde zu Kimbul gehen...', 28153),
(132843, 'deDE', 'Das verzehrende Licht hat mich verführt. Danke, dass Ihr mich gerettet habt...', 'Das verzehrende Licht hat mich verführt. Danke, dass Ihr mich gerettet habt...', 28153),
(132841, 'deDE', '', 'Ohne Nahrung oder Wasser überleb ich nich\' mehr lang. Nachdem ich den Großteil des Tages im Kreis gelaufen war, blieb mir nichts andres übrig, als dem Rat von \'nem Verrückten zu folg\'n un\' mich Richtung Süd\'n aufzumach\'n, um dort Zuflucht zu such\'n.', 28153),
(132840, 'deDE', '', 'Von Jakra\'zet gesandte Attentäter ham unser Lager mitten in der Nacht angegriff\'n. Unbewaffnet un\' im Halbschlaf konnt\'n wir uns nicht wehr\'n. Ich hab den Verräter abgewehrt, aber es war zu spät: Die Überleb\'nd\'n hatt\'n sich in alle Winde zerstreut un\' sin\' jetz\' auf sich allein gestellt.', 28153),
(132839, 'deDE', '', 'Die Sonne is\' hinter den Dün\' untergegang\'n. Da lässt die Hitze endlich nach, die so viele wahnsinnig macht. Einer von uns hat \'nen Hitzschlag bekomm\' un\' etwas von ei\'m Tempel im Süden gefaselt, der Verbannte aufnimmt. Der wird die Nacht wohl nich\' übersteh\'n.', 28153),
(132838, 'deDE', '', 'Ich schreib das hier in \'nem Käfig mit \'nem Dutzend andrer Verbannter, auf\'m Weg in die Sande, wo wir den Rest unsrer Tage verbring\'n werden – was nich\' mehr viele sein dürft\'n. An der drück\'nd\'n Hitze merk ich, dass wir fast da sin\'.', 28153),
(132830, 'deDE', '', 'Ihr zu spät... die Loa... wer\'n alle Futter... für den Blutgott.', 28153),
(132827, 'deDE', 'Dafür werden diese Naga bezahlen!', '', 28153),
(132826, 'deDE', 'Ich weiß nicht, wie ich Euch danken soll!', '', 28153),
(132825, 'deDE', 'Ich schulde Euch was!', '', 28153),
(132824, 'deDE', 'Freiheit!', '', 28153),
(132823, 'deDE', 'Euch verdanke ich mein Leben. Diese Schlangen werden dafür bezahlen, was sie unserer Heimat angetan haben.', 'Euch verdanke ich mein Leben. Diese Schlangen werden dafür bezahlen, was sie unserer Heimat angetan haben.', 28153),
(132821, 'deDE', '<Nehmt den Brief.>', '<Nehmt den Brief.>', 28153),
(132752, 'deDE', 'Nisha, den Sanden sei Dank. Ihr seid in Sicherheit.', '', 28153),
(132737, 'deDE', '', 'Er ist wirklich der gütigste Mann, den ich je gekannt habe.', 28153),
(132736, 'deDE', '%s macht eine Geste in Eure Richtung, als wollte er Euch aufhalten. Dann zieht er sich zurück und starrt wieder in die Ferne.', '', 28153),
(132735, 'deDE', 'Ha, der erste Becher vom Skorpidblut geht immer schwer runter. Lasst es raus. Beim nächsten Mal geht\'s leichter.', '', 28153),
(132734, 'deDE', 'Zuldazar hat uns verrat\'n, uns verbannt. Aber wir ham unsereins nie verrat\'n. Wir Goldhauer bleib\'n uns treu.', '', 28153),
(132733, 'deDE', 'Ah, der süße Geschmack vom Blut... Trinkt un\' seht, was ich seh., $p.', '', 28153),
(132714, 'deDE', 'Professionelle Waffen für Jäger, vom Anfänger bis zum Meister!', '', 28153),
(132713, 'deDE', 'Begebt Ihr Euch auf die Jagd? Nirgendwo gibt es bessere Vorräte als hier!', '', 28153),
(132712, 'deDE', 'Feuerwaffen, Munition und Sprengstoff... für jeden Jäger das Richtige!', '', 28153),
(132711, 'deDE', 'Das junge Terrorhorn gähnt müde.', '', 28153),
(132710, 'deDE', 'Oh, das? Das war nur eine Kleinigkeit, mit der ich meine Leibwächter füttere. Ich habe jede Menge davon, wenn Ihr mir ein Angebot machen wollt!', '', 28153),
(132696, 'deDE', 'Is\' es jetzt sicher zum Rauskomm\'n?', '', 28153),
(132692, 'deDE', 'Ha! Klar, $p kann Euch gar nicht seh\'n. Denkt sicher, ich bin verrückt. Ha!', '', 28153),
(132691, 'deDE', 'Keine Sorge, $p kann Euch gar nich\' seh\'n. Denkt sicher, ich bin verrückt. Ha!', '', 28153),
(132690, 'deDE', '$p hat Euch gerettet, Zulsan! Ich freu mich so!', '', 28153),
(132688, 'deDE', 'Hallo, $n! Der Handelsprinz sagt, wir sollten mal ein bisschen Profit machen. Lasst mich wissen, wenn Ihr von einem guten Geschäft hört, ja?', '', 28153),
(132684, 'deDE', '', 'Hier kommt die Braut, hier kommt die Braut!', 28153),
(132683, 'deDE', 'Da lang!', 'Da lang!', 28153),
(132682, 'deDE', 'Aaaaangriff! Ihr schafft das!', 'Aaaaangriff! Ihr schafft das!', 28153),
(132681, 'deDE', '<Flüstert, dass Ihr seine Augenklappe albern findet.>', '<Flüstert, dass Ihr seine Augenklappe albern findet.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132680, 'deDE', 'Kann ich Eure Sachen haben?', 'Kann ich Eure Sachen haben?', 28153),
(132679, 'deDE', 'Eure Augenklappe ist wirklich furchterregend.', 'Eure Augenklappe ist wirklich furchterregend.', 28153),
(132678, 'deDE', '<Man\'zuls Augenklappe zuckt vor Magie.>', '', 28153),
(132677, 'deDE', '<Versucht, Grenja in einem Wettstarren zu besiegen.>', '<Versucht, Grenja in einem Wettstarren zu besiegen.>', 28153),
(132676, 'deDE', 'Ich wette, Ihr würdet einen famosen Türstopper abgeben.', 'Ich wette, Ihr würdet einen famosen Türstopper abgeben.', 28153),
(132675, 'deDE', 'Grüße!', 'Grüße!', 28153),
(132674, 'deDE', '<Grenja sieht für einen Schädel überraschend fröhlich aus.>', '', 28153),
(132673, 'deDE', 'Ruhe bitte! Wir ham \'nen Gast.', '', 28153),
(132672, 'deDE', '<Stellt Euch höflich vor.>', '<Stellt Euch höflich vor.>', 28153),
(132671, 'deDE', '<Murmelt vor Euch hin, wie verrückt es doch hier zugeht.>', '<Murmelt vor Euch hin, wie verrückt es doch hier zugeht.>', 28153),
(132670, 'deDE', 'Eure Kopfbedeckung gefällt mir.', 'Eure Kopfbedeckung gefällt mir.', 28153),
(132669, 'deDE', 'Ähm... Hallo?', 'Ähm... Hallo?', 28153),
(132668, 'deDE', 'Hui! Was war das denn? Ich fühle mich hervorragend.', '', 28153),
(132667, 'deDE', '', '<Volni sieht aus, als sei sie in einem nicht enden wollenden Schrei erstarrt.>', 28153),
(132663, 'deDE', '', 'Die Farbe und der Geschmack, die alle Gerichte durch unsere Gewürze erhalten, werden Euch begeistern!', 28153),
(132662, 'deDE', '', 'Hochwertige Gewürze aus ganz Azeroth!', 28153),
(132661, 'deDE', '', 'Esst nie wieder ein fades Gericht! Seht Euch nur unsere Gewürze an!', 28153),
(132657, 'deDE', 'Aaaah! Lenkt ihn mit \'nem Spielzeug ab!', 'Aaaah! Lenkt ihn mit \'nem Spielzeug ab!', 28153),
(132656, 'deDE', 'Aale, Aale, Aale! \"Aale\" Mann an die Fische! Richtig \"scholle\" Fische!', 'Aale, Aale, Aale! \"Aale\" Mann an die Fische! Richtig \"scholle\" Fische!', 28153),
(132655, 'deDE', 'Gibt nichts Besseres als einen frisch gefangenen Fisch zum Abendbrot!', 'Gibt nichts Besseres als einen frisch gefangenen Fisch zum Abendbrot!', 28153),
(132654, 'deDE', 'Fische! Frisch von Tuskarrbooten!', 'Fische! Frisch von Tuskarrbooten!', 28153),
(132653, 'deDE', 'Sir! In den südwestlichen Lagern der Horde scheinen sich Truppen zu sammeln. Sie machen sich wohl marschbereit, Sir.', '', 28153),
(132651, 'deDE', 'Behaltet sie im Auge! Ihr wisst, was Ihr zu tun habt, sobald sie Anstalten machen, auszurücken.', '', 28153),
(132650, 'deDE', 'Zündholz! Gibt es Neuigkeiten?', '', 28153),
(132648, 'deDE', 'Retten', 'Retten', 28153),
(132646, 'deDE', 'Feuer!', 'Feuer!', 28153),
(132645, 'deDE', 'Ihr müsst zu dieser Horde gehör\'n, von der ich schon so viel gehört hab. Un\' Ihr habt \'n Terrorhornjungtier? Das dürft die Abrichterin interessier\'n. Geht durch.', 'Ihr müsst zu dieser Horde gehör\'n, von der ich schon so viel gehört hab. Un\' Ihr habt \'n Terrorhornjungtier? Das dürft die Abrichterin interessier\'n. Geht durch.', 28153),
(132636, 'deDE', '', 'Sehr interessant...', 28153),
(132635, 'deDE', '', 'Mal sehen, was wir hier haben.', 28153),
(132634, 'deDE', '', 'Seid da draußen vorsichtig.', 28153),
(132629, 'deDE', 'Setzt \'Sprinten\' ein, um schneller zu rennen!', 'Setzt \'Sprinten\' ein, um schneller zu rennen!', 28153),
(132628, 'deDE', '', 'Wir töten die Jäger un\' hol\'n die verlor\'nen Totems zurück.', 28153),
(132626, 'deDE', '', 'Wenn die Zandalari Euch an ihrer Seite kämpf\'n seh\'n, werdet Ihr wieder Anhänger hab\'n.', 28153),
(132624, 'deDE', '', 'Ihr seid \'n mächtiger Loa. Mit solcher Stärke an unsrer Seite, könnwer unsren Feind zerquetsch\'n.', 28153),
(132622, 'deDE', '', 'Großer Krah\'gwa, wir brauch\'n Eure Hilfe geg\'n die Bluttrolle.', 28153),
(132620, 'deDE', 'Hab dich! Jetzt bist DU dran!', '', 28153),
(132619, 'deDE', 'Hab dich! Du bist dran!', '', 28153),
(132613, 'deDE', 'Ich segne Euch mit einem kleinen Teil meiner Macht. Nutzt sie, um Zentimo zu helfen, sich meinen Kindern anzuschließen.', '', 28153),
(132611, 'deDE', '', '', 28153),
(132609, 'deDE', 'Der Angriff kam so plötzlich... Wir... hätten sie nicht aufhalten können.', 'Der Angriff kam so plötzlich... Wir... hätten sie nicht aufhalten können.', 28153),
(132608, 'deDE', 'Der Riese hat uns... vernichtet...', 'Der Riese hat uns... vernichtet...', 28153),
(132607, 'deDE', 'Die Waffe... zerstört...', 'Die Waffe... zerstört...', 28153),
(132606, 'deDE', 'N... Naga... überall!', 'N... Naga... überall!', 28153),
(132605, 'deDE', 'D... d... danke!', 'D... d... danke!', 28153),
(132604, 'deDE', 'Jetzt ist es also so weit.', 'Jetzt ist es also so weit.', 28153),
(132603, 'deDE', 'Feigling!', 'Feigling!', 28153),
(132602, 'deDE', 'Mich kriegt Ihr nie lebendig!', 'Mich kriegt Ihr nie lebendig!', 28153),
(132601, 'deDE', 'Ehrloser Wicht!', 'Ehrloser Wicht!', 28153),
(132600, 'deDE', 'Elender Abschaum!', 'Elender Abschaum!', 28153),
(132599, 'deDE', 'Es is\' mutig von Euch, mit auf die große Jagd zu geh\'n. Das wird bestimmt \'n spannender Tag, was?', '', 28153),
(132581, 'deDE', 'Genug mit diesen Insekten. Wo ist Ihr Anführer?', '', 28153),
(132580, 'deDE', 'Ich lasse mir diese Angriffe nicht länger bieten. Vernichtet sie! Ich bin Krag\'wa, ich werde niemandes Festmahl.', '', 28153),
(132579, 'deDE', 'Gut gemacht, $n. Ihr habt Eure Stärke und Euren Mut mehr als bewiesen. Kehrt zum Tempel zurück und nehmt Eure Belohnung in Empfang.', '', 28153),
(132573, 'deDE', 'Vier Karawanen wurden vom letzten Ranishuschwarm verschlungen. Danke, dass sich das Euretwegen nicht wiederholt.', '', 28153),
(132572, 'deDE', 'Ein Rudel Brutosaurier ist in Vol\'dun eingewandert und die Ranishu sind dem Fresswahn verfallen. Dünnt sie aus, bevor sie sich in einen tödlichen Schwarm verwandeln.', '', 28153),
(132571, 'deDE', 'Beweist Euch, indem Ihr wohlbehalten mit den Opfergaben zurückkehrt. Dann wird der Loa Euch eine Audienz gewähren.', '', 28153),
(132566, 'deDE', 'Ihr habt diesem Tempel gedient und Euch als würdig erwiesen, $n. Im Gegenzug gebe ich Euch meinen Segen, wenn Ihr bereit seid, ihn zu empfangen.', '', 28153),
(132565, 'deDE', 'Jetzt gilt es für Euch, den Unterschlupf des Giftzahnrufers zu finden und die Kreatur umgehend zu töten. Die Sicherheit des Tempels steht auf dem Spiel.', '', 28153),
(132564, 'deDE', 'Wenn die Sethrak nicht bald aus der Schlucht vertrieben werden, ist das Fortbestehen dieses Tempels bedroht.', '', 28153),
(132563, 'deDE', 'Ich nehme Eure Opfergabe an, Fremdling. Bitte tretet näher, diese alten Augen sind nicht mehr, was sie einst waren.', '', 28153),
(132562, 'deDE', 'Anscheinend haben wir Besuch, Jal\'Nanji. Bitte begrüßt unseren Neuzugang.', '', 28153),
(132560, 'deDE', 'Willkomm\'n zur richtig\'n Jagd.', '', 28153),
(132550, 'deDE', 'Die große Donnerechse hat uns gestattet, hier im Tempel Zuflucht zu such\'n. Ihr seid hier so lange willkomm\'n, wie es der Loa erlaubt.', '', 28153),
(132549, 'deDE', 'NEEEEIN! Der haut mit unserem A.M.O.D. ab! Wenn wir den nicht zurückkriegen, ziehen sie uns das für den Rest unseres Lebens vom Gehalt ab.', '', 28153),
(132547, 'deDE', 'Habt Ihr bekommen, was wir brauchen?', '', 28153),
(132545, 'deDE', '<Ihr seht Hunderte von Lunten, die in kleinen Phiolen voll schimmernden Pulvers befestigt sind.>', '', 28153),
(132544, 'deDE', '<Die Klingen der Entersäbel in dieser Kiste erstrahlen in einem vertrauten Glanz.>', '', 28153),
(132541, 'deDE', '<Tausende Kugeln von Musketenschrot sind sorgfältig in dieser Kiste untergebracht.>', '', 28153),
(132537, 'deDE', '<Der unverkennbare Geruch von Schießpulver steigt aus dieser Kiste empor.>', '', 28153),
(132536, 'deDE', '<Als Ihr die Plane anhebt, seht Ihr in der Kiste Metall aufblitzen.>', '', 28153),
(132534, 'deDE', 'Hätte nie erwartet, dass ich noch mal meinen Kopf für Carsten riskieren würde.$B$BNatürlich hätte ich auch nie erwartet, dass wir beide so lange überleben!', '', 28153),
(132533, 'deDE', 'Wir treffen uns dort, sobald Ihr ein paar Informationen über diese Lieferungen habt.', '', 28153),
(132532, 'deDE', 'Schickt die Kinder hier auf die Westseite der Gießerei. Ich warte hier und passe auf, dass sie keiner anrührt.', '', 28153),
(132531, 'deDE', 'Cassens hat dieses Mädchen von seiner Fähre aus aus dem Wasser gefischt. Sie wollte anscheinend aus der Schmiede fliehen.$B$BÜberrascht mich kein bisschen, dass Aschenwind & Co. Kinder für sich arbeiten lässt. Ich war kaum älter als sie, als die Straßenbanden in Boralus mich zwangen, Leute zu bestehlen und Wachen abzulenken.$B$BSo ist der Lauf der Welt: Je schwächer man ist, desto mehr nutzen einen andere aus.', '', 28153),
(132495, 'deDE', '', 'G\'huun... das\'s nich\'... was Ihr mir versproch\'n habt...', 28153),
(132494, 'deDE', '', 'Narr! Eure Seele gehört jetz\' G\'huun.', 28153),
(132493, 'deDE', '', 'Nein! Ich bin nich\'... bereit dafür...', 28153),
(132492, 'deDE', '', 'Ihr wagt\'s, meine Trauer zu unterbrech\'n? Das werdet Ihr bereu\'n!', 28153),
(132453, 'deDE', '', 'Um ein Haar wäre ich da drin ertrunken. Danke, Kumpel.', 28153),
(132450, 'deDE', '', 'Molch schnappt nach Luft.', 28153),
(132444, 'deDE', 'Da lang!', 'Da lang!', 28153),
(132416, 'deDE', 'Bleibt bei mir!', '', 28153),
(132415, 'deDE', 'Wir müss\'n zum Garten der Loa, bevor\'s zu spät is\'! Beeilt Euch!', '', 28153),
(132408, 'deDE', '', 'Danke, dass Ihr diese Sauerei aufgeräumt habt. Zem\'lan ist noch gefährlicher, als die Legenden vermuten lassen.', 28153),
(132406, 'deDE', 'So unbequem war\'s schon lang nich\' mehr. Danke, $n!', '', 28153),
(132404, 'deDE', '', 'Wenn ich Yazma und ihr\'n Spinnenkult in die Klauen bekomm\'... Oh, dann wird Blut fließ\'n.', 28153),
(132403, 'deDE', 'Vielen Dank, $ct. Für die Horde!', 'Vielen Dank, $ct. Für die Horde!', 28153),
(132398, 'deDE', 'Ich hab nur wenig Zeit für Plapperei.', '', 28153),
(132396, 'deDE', 'Warum fragt Ihr sowas? Wollt Ihr raus in\'n Sand geschickt werd\'n?', '', 28153),
(132376, 'deDE', '', 'Dafür werdet Ihr bezahlen!', 28153),
(132374, 'deDE', 'Aaaaaaagh!', 'Aaaaaaagh!', 28153),
(132365, 'deDE', 'Der Loa ist in den Tempel zurückgekehrt.', 'Der Loa ist in den Tempel zurückgekehrt.', 28153),
(132364, 'deDE', 'Hier ist es nicht sicher für Euch. Geht lieber, bevor es zu spät ist.', 'Hier ist es nicht sicher für Euch. Geht lieber, bevor es zu spät ist.', 28153),
(132343, 'deDE', 'Auf der anderen Seite dieser Ruinen ist ein verstecktes Fleckchen. Das würde das perfekte Basislager abgeben. Sagt dem Team, wir treffen uns dort.', '', 28153),
(132342, 'deDE', 'Krag\'wa blickt kurz auf die Glühwürmchen und ist von ihrem Licht erfreut.', '', 28153),
(132340, 'deDE', 'Krag\'wa verschlingt das Fleisch in einem Happen!', '', 28153),
(132325, 'deDE', 'Ihr beleidigt mich? Hinfort mit Euch!', '', 28153),
(132324, 'deDE', 'Krag\'wa wird wütend! Ihr wart zu langsam!', '', 28153),
(132323, 'deDE', 'Ich nehme Euren Tribut an. Und nun zeigt mir, was Ihr zu bieten habt.', '', 28153),
(132322, 'deDE', 'Krag\'wa sieht sich verärgert um. Er scheint sich allmählich zu langweilen. Lenkt ihn ab!', '', 28153),
(132321, 'deDE', 'Krag\'wa leckt sich die Lippen und beäugt Euch mit hungrigem Blick. Füttert ihn!', '', 28153),
(132320, 'deDE', 'Ihr bringt Geschenke. Das freut mich. Ihr sollt noch einen Moment länger leben.', '', 28153),
(132310, 'deDE', 'Geistermaske benutzen', 'Geistermaske benutzen', 28153),
(132308, 'deDE', 'Mächtiger Krag\'wa, ich biete Euch ein Opfer aus Fleisch und Fliegen.', 'Mächtiger Krag\'wa, ich biete Euch ein Opfer aus Fleisch und Fliegen.', 28153),
(132307, 'deDE', 'Ihr seid ein Freund der Frösche. Ich werde Euch... nicht verschlingen.', '', 28153),
(132306, 'deDE', 'Eindringling! Ihr wollt meine Kinder stehlen? Ich werde Euch verschlingen!', '', 28153),
(132297, 'deDE', 'Es sieht aus, als in diese Richtung ein Pfad verlaufen.', '', 28153),
(132296, 'deDE', 'Was wollt Ihr, Nottlich?', '', 28153),
(132294, 'deDE', 'Ich habe diese Steine gesammelt, bitte, nehmt sie. Meine alten Knochen können Schätze nicht mehr so wie früher tragen. Ho ho ho!', '', 28153),
(132293, 'deDE', 'Oh, hallo, glaubt Ihr, Ihr könntet einem alten Mann helfen? Ich stecke wohl ganz schön in der Klemme.', '', 28153),
(132289, 'deDE', 'Ich bin schon dabei, einen Plan auszuklügeln, der alle unsere Probleme löst. Keine Sorge.', '', 28153),
(132288, 'deDE', 'Schmuddelbart dankt Euch! Hier, nehmen Glitzerzeug. Bringen Unglück.', '', 28153),
(132287, 'deDE', '', 'Ihr da, ich könnte Eure Hilfe brauchen!', 28153),
(132279, 'deDE', '', 'Wir müss\'n unsere Position stärk\'n. Wir sin\' alles, was noch zwischen meiner Heimat und dem sicheren Untergang steht.', 28153),
(132275, 'deDE', '', 'Wie könnt Ihr es wagen, unsere Ruhestätte zu entweihen!', 28153),
(132274, 'deDE', '', 'Verschwindet! Überlasst uns unseren Qualen!', 28153),
(132267, 'deDE', 'Tja, das war peinlich. Wenigstens habt Ihr mein Gewehr gefunden.', '', 28153),
(132266, 'deDE', 'Ihr seid \'ne nette Abwechslung zu den Bluttrollen, die ich sonst immer jag.', '', 28153),
(132265, 'deDE', 'Haltet still. Ich muss Euern Kopf sauber abtrenn\'.', '', 28153),
(132264, 'deDE', 'Sagt Bwonsamdi hallo von mir.', '', 28153),
(132263, 'deDE', 'Tretet vor. Nich\' so schüchtern.', '', 28153),
(132262, 'deDE', 'Passt auf, wo Ihr hintretet...', '', 28153),
(132261, 'deDE', 'Ich werd mir Euern Kopf hol\'n!', '', 28153),
(132260, 'deDE', 'Kommt raus zum Spielen, $gkleiner:kleine:r; $R.', '', 28153),
(132254, 'deDE', '', 'Hinterhalt!', 28153),
(132243, 'deDE', '', 'Ich habe beschlossen, nach Osthafen weiterzuziehen. Ich bete, dass die Leute dort nicht dasselbe Schicksal erlitten haben wie die in Schluchtbach.', 28153),
(132240, 'deDE', '', 'Ich spür hier Zorn un\' Kummer. Was auch immer hier gescheh\'n is\', es hat kein gutes Ende genomm\'.', 28153),
(132237, 'deDE', '<Die Zähne einer brutalen Falle haben sich in das Bein dieses toten Jägers gegraben.$B$BPfeile scheinen seine Rüstung durchbohrt zu haben.$B$BSein Gesicht ist mit einem überraschten Ausdruck erstarrt. Er hat den Tod nicht kommen sehen.>', '', 28153),
(132236, 'deDE', '', 'Sei nett zu unserem Gast, Spätzchen! Wir wollen ja nicht, dass uns jemand verlässt... nicht lebend!', 28153),
(132221, 'deDE', '~SCHIESSBUDE HIER EINFÜGEN', '', 28153),
(132205, 'deDE', 'Jainas Wärter sind erst vor ein paar Tagen hier angekommen, um ihr Exil zu vollstrecken. Wenn wir uns beeilen, finden wir sie vielleicht, bevor es zu spät ist.', '', 28153),
(132201, 'deDE', '', 'Eindringling! Ihr werdet für den Tod meiner Schwestern bezahl\'n!', 28153),
(132190, 'deDE', 'Die Abrichterin sagt, dass Ihr jetz\' zu uns gehört und hierbleib\'n dürft. Aber glaubt ja nich\', dass wir Euch aus den Augen lass\'n.', '', 28153),
(132189, 'deDE', '', '\'n Pterrordax zu reiten is\' spannend, um es milde auszudrück\'n! Haltet Euch lieber gut fest!', 28153),
(132188, 'deDE', 'Nun gut. Hier beginnt es also.', '', 28153),
(132187, 'deDE', 'Sie ist wahrscheinlich der Straße gefolgt, um Schutz zu suchen.', '', 28153),
(132186, 'deDE', 'Knüpp, wir finden einen Weg, sobald wir Jaina haben. Irgendwelche Vorschläge, Yorrick?', '', 28153),
(132185, 'deDE', '', 'Ich habe das Gefühl, dass sie uns das Tor nicht öffnen werden, wenn wir zurückkehren...', 28153),
(132180, 'deDE', '', 'Da, das is\' der Weg!', 28153),
(132179, 'deDE', 'Worum wollt Ihr den alt\'n Bwonsamdi bitt\'n?', '', 28153),
(132178, 'deDE', 'Nich\' übel, gar nich\' übel! Am Ende steckt in Euch was von \'nem Seelenernter!', '', 28153),
(132177, 'deDE', 'Ihr wagt es, meinen Körper zu entweih\'n?', '', 28153),
(132169, 'deDE', 'Die Allianz stellt eine hohe Belohnung für die Rückkehr von Jaina in Aussicht.', 'Die Allianz stellt eine hohe Belohnung für die Rückkehr von Jaina in Aussicht.', 28153),
(132168, 'deDE', 'Ihr meint in Drustvar?! Das kann nicht Euer Ernst sein!\n\nNein, Sir, mein Platz ist hier an der Mauer. Ich versorge diese tapferen Soldaten mit Vorräten! Nur ein Narr würde sich auf die andere Seite der Tore zu wagen!', '', 28153),
(132152, 'deDE', '', 'Wahrlich, Ihr könnt wirklich kämpfen, das muss ich Euch lassen. Ich werde dem Marschall mit meinem Schwert zur Seite stehen.', 28153),
(132149, 'deDE', '', 'Jetzt ist es zu spät für eine Umkehr, Yorrick. Wehrheim wird keinem Soldaten verzeihen, der seine eigenen Leute angegriffen hat, auch nicht, wenn er auf Befehl gehandelt hat.', 28153),
(132148, 'deDE', 'Jaina?! Sie ist der Grund für diese Expedition? Das ist Hochverrat!', '', 28153),
(132146, 'deDE', 'Dieses Risiko muss ich eingehen, Hauptmann. Folgt mir, Soldaten!', '', 28153),
(132145, 'deDE', 'Ihr könnt durch, Lesner, aber die Königin wird davon erfahren! Ihr werdet Boralus nie wieder betreten können!', '', 28153),
(132144, 'deDE', 'Genug. Ich gebe auf!', '', 28153),
(132143, 'deDE', 'Dafür ist jetzt keine Zeit! Soldaten, haltet stand!', '', 28153),
(132142, 'deDE', 'Auf Befehl der Königin darf niemand dieses Tor passieren. Auch Ihr nicht.', '', 28153),
(132141, 'deDE', 'Hauptmann Wehrheim, ich habe diese Männer für eine Sondermission rekrutiert. Ich befehle Euch, zur Seite zu treten und uns durchzulassen!', '', 28153),
(132140, 'deDE', 'Halt! Wo wollt Ihr eigentlich mit meinen Männern hin, Marschall?', '', 28153),
(132139, 'deDE', 'Das sollte genügen! Berichtet Marschall Lesner, dass Rüstmeister Nottlich bereit zum Dienst ist!', '', 28153),
(132138, 'deDE', 'Ich... leihe mir nur ein paar Dinge aus, die wir brauchen.', '', 28153),
(132137, 'deDE', 'Belohnung, sagt Ihr? Das ändert natürlich die Lage...', '', 28153),
(132136, 'deDE', 'Feuer einstellen. Anscheinend haben wir sie in die Flucht geschlagen.', '', 28153),
(132135, 'deDE', 'Nehmt Euch eine Armbrust und helft mir, $gFestländer:Festländerin;!', '', 28153),
(132134, 'deDE', 'Wenn er mich braucht, werde ich seine Befehle befolgen. Allerdings würden wir unsere Pflicht vernachlässigen, wenn wir hier verschwinden, ohne die Reihen dieser Bestien etwas auszudünnen.', '', 28153),
(132133, 'deDE', 'Ich habe mir schon gedacht, dass der Marschall aus diesem Grund hier ist. Aber sagt diesen Namen hier lieber nicht zu laut...', '', 28153),
(132132, 'deDE', '', 'Passt auf. Wenn Ihr mir Euren Mut beweist, werde ich bei Lesners kleinem Abenteuer mitmachen. En garde!!', 28153),
(132131, 'deDE', '', 'Ich bin bereit, den Gefahren im Grabwald gegenüberzutreten. Ich mache aber nicht den Babysitter für $geinen Festländer, der:eine Festländerin, die; kaum ein Schwert halten kann.', 28153),
(132130, 'deDE', '', 'Willkommen zur groß\'n Jagd, $R. An diesem Ort zählt alles als Beute, was sich bewegt.$b$bHier ehr\'n wir die, die mit den schönsten Trophäen von ihrer Jagd zurückkehr\'n.', 28153),
(132129, 'deDE', 'Vorsichtig! Das Mojo von der Hexe is\' ziemlich mächtig!', '', 28153),
(132128, 'deDE', 'Die Tafel ist uralt und verwittert. Sie steht in starkem Kontrast zu den frischen Opfergaben, die vor ihr platziert wurden.', 'Die Tafel ist uralt und verwittert. Sie steht in starkem Kontrast zu den frischen Opfergaben, die vor ihr platziert wurden.', 28153),
(132117, 'deDE', '', 'Eure Knochen gehör\'n der Meisterin!', 28153),
(132114, 'deDE', 'Dreckiger Abschaum, diese Horde!', '', 28153),
(132113, 'deDE', 'Geht dieser Krieg denn nie zu Ende?', '', 28153),
(132112, 'deDE', 'Ich kehre in die Schatten zurück.', '', 28153),
(132111, 'deDE', 'Passt auf Euch auf, Soldat.', '', 28153),
(132107, 'deDE', 'Sie is\' im Norden. Folgt einfach dem Fluss und überquert ihn, wo er flach is\'.', '', 28153),
(132106, 'deDE', '', 'Ich werd sie begleit\'n, damit sie auch wirklich sicher sin\'.', 28153),
(132105, 'deDE', 'Willkommen! Entschuldigt bitte die Unordnung. Wir hab\'n nur selten lebenden Besuch.', '', 28153),
(132096, 'deDE', 'Hmm, ich glaub\' die Geschichte... vorerst. Lasst uns red\'n.', '', 28153),
(132095, 'deDE', '', 'Ich schwör\'s!', 28153),
(132094, 'deDE', 'Wartet, Jhasan! $GEr:Sie; hat was. Vielleicht sagt die Kleine ja die Wahrheit.', '', 28153),
(132093, 'deDE', 'Ah, Ihr beschäftigt uns mit Red\'n, bis Eure Freunde hier sin\'?', '', 28153),
(132092, 'deDE', '', 'Moment, das sin\' Freunde... $n, Vorsicht!', 28153),
(132081, 'deDE', 'Nur zu schade, dass Zulsan nicht hier is\', um Euch kennenzulernen. Eure Haare würd\'n ihm gefallen.', '', 28153),
(132068, 'deDE', 'Ja, ich habs gehört, Man\'zul. Ich find\' trotzdem, Eure Augenklappe is\' hässlicher als \'n Sauroliskenhintern.', '', 28153),
(132067, 'deDE', 'Ha! Volni, seid doch nicht so. Vielleicht war beim Anzieh\'n ja das Licht aus... Aber Ihr habt schon recht!', '', 28153),
(132066, 'deDE', 'Grenja is\' unsre Hausbardin. Sie spielt jedes Lied, das Ihr wollt... wenn\'s \'n Rhythmus hat. Sie haut gern Sachen kaputt. Hoffentlich nich\' Euer Gesicht, ha! Das wird sie schon nicht... oder?', '', 28153),
(132057, 'deDE', 'Nein, Grenja, ich kauf\' keine goldene Trommel! Und jetzt Ruhe, sonst nehm\' ich Euch den schick\'n neuen Hut!', '', 28153),
(132055, 'deDE', 'Wir dürf\'n hier bloß nich\' den Kopf verlier\'n. Der Sumpf is\' die Quelle von mächtigem Voodoo.', '', 28153),
(132054, 'deDE', 'Ihr duftet frisch. Der Sumpfgestank hat sich also noch nich\' an Euch festgesetzt. Kommt zur Sache.', '', 28153),
(132053, 'deDE', '', 'Die Dunklen riefen Annie, doch dem Bösen sie entsagte. Es wundert daher wenig, dass die Folge sie nun plagte.', 28153),
(132049, 'deDE', '', 'Der gute Bauer Samuel, für sein Vieh tat er das seine. Doch nun hat ihn der Wald geholt – wer nährt jetzt nur die Schweine?', 28153),
(132048, 'deDE', '', 'Herr Hayens Seele, sagt man, war gütig und auch zart. Wie tragisch, dass sein Herz der Hexe Opfer ward!', 28153),
(132047, 'deDE', '', 'Frau Maria wandt sich ab, was sie begehrt\' war üble Macht. Bracht\' den Tod in unser Dorf und stürzt\' den Wald in finstre Nacht.', 28153),
(132046, 'deDE', 'Hier entlang, Fremdling. Zum König geht es durch diese Tür und drinn\'n mit dem Aufzug hinauf.', '', 28153),
(132045, 'deDE', '', 'Seid gewarnt, Fremdling. Ich hab Euch im Auge. Ihr steht hier vor einem der ältest\'n lebend\'n Trolle. Un\' er is\' am Leben, weil mein Bruder un\' ich ihn am Leben halt\'n. Also kommt nich\' auf komische Gedank\'n.', 28153),
(132044, 'deDE', 'Rache für Zul\'jin!', '', 28153),
(132043, 'deDE', 'Ich hoffe, sie haben was zu essen an Bord!', 'Ich hoffe, sie haben was zu essen an Bord!', 28153),
(132042, 'deDE', 'Ein warmes Feuer wäre jetzt toll!', 'Ein warmes Feuer wäre jetzt toll!', 28153),
(132041, 'deDE', 'Bitte helft auch den Erwachsenen!', 'Bitte helft auch den Erwachsenen!', 28153),
(132040, 'deDE', 'Danke!', 'Danke!', 28153),
(132039, 'deDE', 'Ich gehe wieder die Schulbank drücken...', 'Ich gehe wieder die Schulbank drücken...', 28153),
(132038, 'deDE', 'Mich kriegen die nicht! Ich bin zu schnell!', 'Mich kriegen die nicht! Ich bin zu schnell!', 28153),
(132037, 'deDE', 'Ich bin dann mal weg!', 'Ich bin dann mal weg!', 28153),
(132020, 'deDE', '', 'Beruhigt Euch, Drekal. Diese Kreaturen hab\'n uns Schutz gebot\'n. Wir sollt\'n ihr Vertrauen gewinn\'.', 28153),
(132019, 'deDE', 'Oho, das\'s ma\' \'ne mächtige Seele. Der alte Bwonsamdi fühlt sich richtig beflügelt. Haha, ja, meine Macht wächst.', '', 28153),
(132017, 'deDE', '', 'Ihr verwirkt Eure Chance auf Macht...', 28153),
(132016, 'deDE', 'Gut gemacht, das sollte sie in die Schranken weisen.', '', 28153),
(132015, 'deDE', 'Die Sethrak breiten ihr Imperium aus und übernehmen die Ebenen, auf denen unser Volk einst lebte. Wir müssen ihrem Eroberungszug einen Riegel vorschieben.', '', 28153),
(132010, 'deDE', 'Geh zum Wasser hinunter. Ein Boot wartet dort, um dich in Sicherheit zu bringen.', 'Geh zum Wasser hinunter. Ein Boot wartet dort, um dich in Sicherheit zu bringen.', 28153),
(132009, 'deDE', '', 'Narr... Ihr wisst nicht, worauf Ihr Euch einlasst...', 28153),
(132004, 'deDE', 'Ich habe ein paar böse Männer gesehen. Sie haben alle angeschrien... sogar die anderen Erwachsenen!', 'Ich habe ein paar böse Männer gesehen. Sie haben alle angeschrien... sogar die anderen Erwachsenen!', 28153),
(132003, 'deDE', 'Seid Ihr gemein?$B$BIhr seht nicht gemein aus.', 'Seid Ihr gemein?$B$BIhr seht nicht gemein aus.', 28153),
(132002, 'deDE', 'Meine Nase friert mir ab, meine Ohren frieren mir ab und meine Zehen auch...', 'Meine Nase friert mir ab, meine Ohren frieren mir ab und meine Zehen auch...', 28153),
(131999, 'deDE', 'Sie sagten, wir kriegen was zu essen, aber seit ich hier bin, habe ich nicht mal eine alte Brotkruste zu sehen bekommen!', 'Sie sagten, wir kriegen was zu essen, aber seit ich hier bin, habe ich nicht mal eine alte Brotkruste zu sehen bekommen!', 28153),
(131998, 'deDE', '', 'Drekal und ich werden zu Euch stoß\'n, nachdem wir uns umgeseh\'n haben.', 28153),
(131997, 'deDE', '', 'Ihr solltet los zum Tempel da vorne. Wenn dieser Loa wirklich so mächtig is\', wie die sag\'n, dann kann er uns vielleicht helf\'n, Rakera zu find\'n.', 28153),
(131996, 'deDE', '<Hust> <hust>$B$BIch will nach Hause.', '<Hust> <hust>$B$BIch will nach Hause.', 28153),
(131995, 'deDE', 'Bitte schreit mich nicht an!', 'Bitte schreit mich nicht an!', 28153),
(131994, 'deDE', 'Ich bin müde.', 'Ich bin müde.', 28153),
(131939, 'deDE', '', 'Willkommen, $gSoldat:Soldatin;. Seid Ihr bereit, für die Allianz zu kämpfen?', 28153),
(131931, 'deDE', 'Ihr glaubt, Ihr hättet ein schweres Los? Ihr habt ja keine Ahnung, wie schwer es ist, den Überblick zu behalten, welcher Krieg wann läuft.', '', 28153),
(131897, 'deDE', '', 'Fliegt weiter und hofft, dass wir\'s nicht rausfind\'n.', 28153),
(131894, 'deDE', '', 'Wir müss\'n durch \'n Sumpf. Solange wir in der Luft bleib\'n und keiner uns sieht, sollt\'n wir nicht zu viele Probleme ham.', 28153),
(131893, 'deDE', '', 'Kaja, was sin\' das für Dinger da unter uns?', 28153),
(131888, 'deDE', 'Was Mutta will, kriegt Mutta auch.', '', 28153),
(131887, 'deDE', 'Mein Leb\'n für die Großmutter!', '', 28153),
(131886, 'deDE', 'Fleisch für die Kriegsmatronen!', '', 28153),
(131885, 'deDE', 'Frisches Blut!', '', 28153),
(131884, 'deDE', 'Mutta hat gesagt, töt\'n... nein... gefangen nehm\'n. Ja! Gefangene.', '', 28153),
(131883, 'deDE', 'Sehnen! Die muss ich zerschneid\'n. Mutta hat gesagt, wir soll\'n sie zerschneid\'n.', '', 28153),
(131882, 'deDE', 'Sterbt! Sterbt! Sterbt!', '', 28153),
(131881, 'deDE', '<Als Ihr seine Taschen durchsucht, findet Ihr einen Brief.>\n\nMeine liebste Maria,\n\nbitte komm zurück nach Hause. Robin fragt immer wieder, wo du bist. Was soll ich ihm sagen? Dass seine Mutter in den Wald rannte, um wer weiß was zu tun? Wir vermissen dich, meine Liebe. Unser Haus ist nicht mehr, was es einst war. Ich bitte dich, komm zurück zu uns.\n\nIn Liebe,\nJonathan', '', 28153),
(131880, 'deDE', '*Hicks* Passt auf, wo Ihr lang lauft...', '*Hicks* Passt auf, wo Ihr lang lauft...', 28153),
(131878, 'deDE', '<Untersucht den Leichnam nach Hinweisen auf seine Identität.>', '<Untersucht den Leichnam nach Hinweisen auf seine Identität.>', 28153),
(131875, 'deDE', 'Was wird heute verschickt?', 'Was wird heute verschickt?', 28153),
(131874, 'deDE', 'Ja?', 'Ja?', 28153),
(131869, 'deDE', 'Witwergrog! Drei Fässer!', 'Witwergrog! Drei Fässer!', 28153),
(131868, 'deDE', 'Gewürzwein! Fünf Fässer! Abyssalbier! Sieben Fässer! Uuuund...', 'Gewürzwein! Fünf Fässer! Abyssalbier! Sieben Fässer! Uuuund...', 28153),
(131867, 'deDE', 'Alle mal herhören! Die Bestellung des Tages ist da!', 'Alle mal herhören! Die Bestellung des Tages ist da!', 28153),
(131855, 'deDE', 'Noch einmal danke für Eure Hilfe. Ich werde diese Opfergabe sogleich zum Tempel bringen.', 'Noch einmal danke für Eure Hilfe. Ich werde diese Opfergabe sogleich zum Tempel bringen.', 28153),
(131851, 'deDE', 'Ruhe allerseits! $p wird zu jedem von Euch komm\'n und Hallo sag\'n.', '', 28153),
(131845, 'deDE', 'Das is\' jetz\' genug. Sucht auf der groß\'n Treppe nach Talanji. Ich werd weiter patrouillier\'n un\' nach der Allianz Ausschau halt\'n.', '', 28153),
(131844, 'deDE', 'Teil\'n wir uns auf und spüren die Allianz auf. Ich werd mein Bestes geb\'n, Euch zu unterstütz\'n.', '', 28153),
(131843, 'deDE', 'Eine Dreistigkeit! Ein Angriff auf MEIN\' Tempel? Auf MICH? Das wird ihnen noch leid tun. M-hm. Sowas von leid.', '', 28153),
(131842, 'deDE', '', 'Ich wander schon viel zu lang über diese Welt. Endlich hab ich Fried\'n!', 28153),
(131841, 'deDE', 'Geht schon, Mann. Bwonsamdi wacht über Euch.', '', 28153),
(131840, 'deDE', 'Gut, gut. Sylvanas wird erfreut sein. Kommt, \"Stimme\", besprechen wir unseren nächsten Schritt.', '', 28153),
(131839, 'deDE', 'Moment, wir ALLE müssen dieses Ding bekämpfen? Ich dachte, wir könnten... einfach... unseren Champion reinschicken... oder so.', '', 28153),
(131838, 'deDE', 'Für die Trommel braucht Ihr Mambus Hammer und Gee\'daes Hammer. Die könnt Ihr beide in meinen Tempelhöfen find\'n.', '', 28153),
(131832, 'deDE', 'Danke vielmals.', '', 28153),
(131831, 'deDE', 'Ich möchte nach Zul\'jan.', 'Ich möchte nach Zul\'jan.', 28153),
(131830, 'deDE', '', 'Ich bin zwar tot, aber die Kreaturen hör\'n immer noch auf mein\'n Ruf.\n\nSoll ich Euch mitnehm\'n?', 28153),
(131829, 'deDE', 'Ich muss \'n Wort mit Euch red\'n. Es gibt da \'ne Situation, um die Ihr Euch kümmern müsst.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131828, 'deDE', 'Hallo, $gmein Freund:meine Liebe;! Ich hab Euch überall gesucht!', '', 28153),
(131818, 'deDE', 'Vergesst unsre Abmachung bloß nich\'. Schickt Bwonsamdi weiter Seelen... wenn Ihr weiter in meiner Gunst steh\'n wollt.', '', 28153),
(131816, 'deDE', 'Langsam Prinzessin, wir dürf\'n nix überstürz\'n. Wir müss\'n die Gegend erkund\'n un\' \'nen Plan schmied\'n.', '', 28153),
(131803, 'deDE', '', 'Ihr seid $gder Held:die Heldin; von dem sie sprach, nehm\' ich an. Helft unsrer Prinzessin und ich erzähl Euch alles, was Ihr wiss\'n wollt. Ich pflege unsre Verwundeten schon eine ganze Weile, aber es wird einfach nur schlimmer.\n\nSie geht nach Nazmir. Sie hat nur \'ne kleine Wachtruppe mitgenommen, aber Rokhan ist auch dabei. Wir haben ihnen all unsre Vorräte gegeb\'n, die wir entbehren konnt\'n.\n\nSie sind durchs Nordwesttor gegangen. Da wurden schon lange keine Bluttrolle mehr gesichtet, seit sie das Haupttor belagern.\n\nMein Loa ist da blind. Bitte seid vorsichtig.', 28153),
(131777, 'deDE', 'Ich werde diese Schuld begleichen. Versprochen.', 'Ich werde diese Schuld begleichen. Versprochen.', 28153),
(131776, 'deDE', 'Ich bin frei? Ganz ohne Gegenleistung? Ihr hebt Euch von der Masse ab.', '', 28153),
(131774, 'deDE', '', 'Was für ein Chaos da unten. Ich wünschte, die Prinzessin wär\' nie aufgebrochen. Die Bluttrolle steh\'n direkt vor unsren Toren und der König unternimmt nix!', 28153),
(131771, 'deDE', 'Sie war noch keinen Tag hier und ist schon wieder aufgebroch\'n!\n\nTalanji geht auf Reisen und ihr Vater weiß nichts davon. Sie hat nur \'ne Handvoll Leibwach\'n dabei, um den Schein zu wahr\'n.\n\nIch hab das Gefühl, sie will Richtung Nazmir. Das gibt sie aber nicht zu. Das ist ein übler Ort und ich kann nicht geh\'n, aber wenn Ihr an meiner Stelle aufbrecht, würde mich das beruhig\'n.\n\nSie wird Unterstützung brauch\'n. Wahrscheinlich wird sie sich an die Priesterschaft wend\'n und sie an einem ihrer Lieblingsplätze zusammenruf\'n. Zeigt mir Eure Karte.', '', 28153),
(131766, 'deDE', 'Wo ist Talanji?', 'Wo ist Talanji?', 28153),
(131765, 'deDE', 'Ich werd\' Euch auf ewig dankbar sein, wenn Ihr die Prinzessin rettet. Ich hab selbst erlebt, dass es \'ne harte Nuss sein kann, sie zu beschütz\'n. Sie glaubt, sie muss die Zandalari im Alleingang rett\'n.', '', 28153),
(131764, 'deDE', 'Derartige Freundlichkeit hätte ich nicht erwartet.', 'Derartige Freundlichkeit hätte ich nicht erwartet.', 28153),
(131763, 'deDE', 'Keine Zeit für nette Schwätzchen. Wir sind hier am Gefechtsstand, mitten im Geschehen. Camp Taurajo da drüben hetzt eine Welle verfluchter Tauren nach der anderen auf uns.\n\nWenn wir diese Position aufgeben, weiß ich nicht, wie wir das Tor einnehmen sollen.', '', 28153),
(131761, 'deDE', 'Ihr könnt Euch nich\' vorm Mojo versteck\'n!', '', 28153),
(131752, 'deDE', 'Valjabu, Ihr müsst nich\' auf die Andre Seite geh\'n. Unterwerft Euch G\'huun und Ihr könnt ewig leb\'n!', '', 28153),
(131750, 'deDE', 'Noch so ein erbärmlicher Verbannter, der zum Sterben in die Sande kommt?', '', 28153),
(131745, 'deDE', '', 'Begebt Euch mit Rokhan nach Nazmir. Ich treff Euch dort. Wir müss\'n den Bluttroll\'n \'n Ende bereit\'n.', 28153),
(131742, 'deDE', '', 'Odyns Segen für Euch und hier noch eine angemessene Belohnung.', 28153),
(131741, 'deDE', 'So, Jungs, dann legen wir hier mal los und machen klar Schiff. Ich will Wachen an den Eingängen, falls die versuchen, uns rauszuschmeißen, und ich will sofort einen kompletten Barservice. Geh mir außerdem einer noch einen Teleportstein besorgen, nur für alle Fälle.', '', 28153),
(131709, 'deDE', 'Was geht hier vor? Warum sin\' wir wie Tiere eingesperrt?', '', 28153),
(131706, 'deDE', '', 'Yorrick, bringt Eure Ambulanztasche hier rüber. Wir haben hier einen Überlebenden!', 28153),
(131705, 'deDE', 'Uh... oh! Zu Befehl!', '', 28153),
(131703, 'deDE', '', 'Auf die Beine, Fähnrich! Wir müssen uns einen Weg hier raus suchen!', 28153),
(131690, 'deDE', 'Klingenwache Hozzul reagiert nicht.', '', 28153),
(131689, 'deDE', '', 'Klingenwache Jorana reagiert nicht.', 28153),
(131674, 'deDE', 'Willkomm\' im Goldhauer!', '', 28153),
(131672, 'deDE', 'Dieser Verbannte ist zwar noch am Leben, atmet aber kaum noch.\n\nEr hat schwere Verwundungen erlitten, doch seine kränkliche Erscheinung lässt darauf schließen, dass womöglich noch etwas anderes im Argen liegt.', '', 28153),
(131671, 'deDE', 'Auf der anderen Seite des Geröllhaufens, der diesen Gang versperrt, ist Licht zu sehen.\n\nWenn man das Geröll beseitigen könnte, wäre dies vielleicht ein Weg aus den Ruinen heraus.', '', 28153),
(131670, 'deDE', 'Diese Tiere wurden mithilfe von Frostmagie getötet. Ein sicheres Zeichen, dass Jaina hier gewesen ist.\n\nWo sie jetzt allerdings ist, bleibt ein Rätsel.', '', 28153),
(131668, 'deDE', 'Dies scheinen die Spuren von einem der Tiere zu sein, die Eure Gruppe im Wald angegriffen haben. Es hat etwas hinter sich hergeschleift.\n\nSeltsamerweise enden die Spuren plötzlich an einer Stelle, als hätte sich die Bestie in Luft aufgelöst.', '', 28153),
(131667, 'deDE', 'Vorsicht. Ich hab so Hunger, dass ich langsam wütend werde!', '', 28153),
(131666, 'deDE', '', 'Was WAR das?!', 28153),
(131665, 'deDE', 'Das Terrorhornjungtier kreischt überrascht.', '', 28153),
(131664, 'deDE', 'Das junge Terrorhorn springt Euch leidenschaftlich an.', '', 28153),
(131663, 'deDE', 'Das junge Terrorhorn verpasst Euch versehentlich einen Liebesbiss.', '', 28153),
(131662, 'deDE', 'Das aufgeregte junge Terrorhorn stößt Euch um.', '', 28153),
(131661, 'deDE', 'Ich bin so hungrig, ich könnte einen ganzen Brutasaurus fressen!', '', 28153),
(131659, 'deDE', 'Mama, kann ich bitte mehr Fleisch haben?', '', 28153),
(131658, 'deDE', 'Peitscher sind lecker, aber ich will FLEISCH!', '', 28153),
(131657, 'deDE', '%s knurrt verspielt.', '', 28153),
(131656, 'deDE', '%s betrachtet Euch spitzbübisch.', '', 28153),
(131655, 'deDE', '%s tänzelt freudig herum.', '', 28153),
(131654, 'deDE', '%s wimmert aufgeregt.', '', 28153),
(131653, 'deDE', 'Hört mal, Ihr habt zwar Mumm, aber Verhandlungen sind nicht Eure Spezialität. Zumindest könnt Ihr es nicht so wie ich.$b$bVerschafft mir einfach eine Audienz bei diesem König, dann beschwatze ich ihn, seine Flotte, seinen Thron, das ganze dekorative Gold und vielleicht noch ein paar Tikimasken als Andenken rauszurücken.', '', 28153),
(131652, 'deDE', 'Hey, sieh\' ma\' einer an. Womöglich seid Ihr meine Zeit ja doch wert. Lasst uns im Tempel red\'n. Der alte Bwonsamdi hat da vielleicht \'n Angebot für Euch.', '', 28153),
(131651, 'deDE', 'Ah, Salazae... die weilt schon viel zu lange unter den Lebend\'n. Tut, was Ihr tun müsst, um ihre Seele zu diesem mehr als geduldig\'n Gott zu bring\'n, ja?', '', 28153),
(131650, 'deDE', '', 'Lasst mich in Ruhe, wenn Ihr mir nich\' meinen Liebsten zurückbring\'n könnt.', 28153),
(131649, 'deDE', 'Wir sind bereit, Euren Segen zu empfangen.', 'Wir sind bereit, Euren Segen zu empfangen, großer Loa.', 28153),
(131648, 'deDE', 'Seit dem Bau dieses Tempels sind viele Jahre vergangen. Obwohl die Wände noch immer dieselben sind, haben sich die Gesichter meiner Gefolgsleute geändert.', '', 28153),
(131637, 'deDE', 'Seid gegrüßt, Ihr Kleinen. Ich bin zurückgekehrt. Tretet vor und empfangt meinen Segen.', '', 28153),
(131633, 'deDE', 'Nur Zandalari dürf\'n diese heiligen Hall\'n betret\'n! Das Gesetz is\' eindeut–', '', 28153),
(131632, 'deDE', 'Verbreitet die Kunde... Hiermit ernenn\' ich Euch zur Stimme der Horde.', '', 28153),
(131631, 'deDE', 'Solang ich hier König bin, sag ich, was Gesetz is\'.', '', 28153),
(131630, 'deDE', 'Das ganze Königreich schaut auf Euch, Champion. Mit dem heutig\'n Tag ernenn ich Euch zur Stimme der Horde.', '', 28153),
(131629, 'deDE', 'Lasst uns seh\'n, ob die Horde sich bewährt. Bringt sie im Groß\'n Siegel unter. Sie sin\' meine Gäste... vorerst.', '', 28153),
(131628, 'deDE', 'Talanji fürchtet, ich seh nich\', wer wirklich unser Feind is, aber ich bin nich\' so blind, wie sie denkt.', '', 28153),
(131627, 'deDE', 'Aber meine Tochter hat auch recht. Ihre Rettung hat echt Mut erfordert... so was bewunder ich.', '', 28153),
(131626, 'deDE', 'Jakra\'zet hat recht... Ihr braucht die Stärke unsrer Flotte geg\'n die Allianz.', '', 28153),
(131625, 'deDE', '', 'Wunderbar! Setzt Euch und wir können beginnen. Mit Eurer und Schmuserchens Hilfe kann ich den letzten Gast rufen!', 28153),
(131624, 'deDE', '', 'Hier oben! Das wird die beste Teeparty aller Zeiten!', 28153),
(131623, 'deDE', '', 'Los, los, kommt schon! Zeit für die Teeparty!', 28153),
(131620, 'deDE', '', 'Euer Opfer und das meines Mannes werden das Ritual zur Vollendung bringen!', 28153),
(131619, 'deDE', '', 'Kommt mit uns, Schwester, und uns wird große Macht zuteilwerden.', 28153),
(131618, 'deDE', '<In der Brust des Mannes klafft eine große offene Wunde. Ihr schaut sie genauer an und seht, dass ihm das Herz herausgerissen wurde.>', '', 28153),
(131617, 'deDE', 'Ins Holz sind die Worte \"S. Hagendorn\" eingeritzt.', '', 28153),
(131616, 'deDE', '', 'Herr Hagendorn hat immer die Hündchen von seinen Tieren weggejagt. Aber jetzt kriegen die Hunde endlich Fresschen!', 28153),
(131615, 'deDE', '', 'Unser Dorf ist tot und leer.', 28153),
(131609, 'deDE', '', 'Wir müss\'n wachsam sein. Aus Nazmir kommt niemand lebend zurück.', 28153),
(131608, 'deDE', '', 'Bluttrolle sin\' erbärmliche Wilde. Sie sin\' schon lang keine Bedrohung mehr.', 28153),
(131607, 'deDE', 'Genug. Ich entscheide, was mit dem Fremdling passiert.', '', 28153),
(131606, 'deDE', '', 'Wir brauch\'n Verbündete geg\'n die Bluttrolle. Ich hab\' getan, was getan werd\'n musste.', 28153),
(131605, 'deDE', 'Talanji hat dieses Hordegesindel mitgebracht. Das is\' Verrat, Hoheit.', '', 28153),
(131604, 'deDE', '', 'Eure Seele für mein\' Meister. Eure Seele für G\'huun.', 28153),
(131603, 'deDE', 'Das is\'... noch nich\'... das Ende...', 'Das is\'... noch nich\'... das Ende...', 28153),
(131602, 'deDE', '', 'G\'huun is\' der Meister von dies\'m Land. Schon bald wird ihm auch der törichte Bwonsamdi dien\'.', 28153),
(131544, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(131543, 'deDE', '', '<Annie sieht Euch mit leerem Blick an. Ihre Kleidung ist blutverschmiert, aber sie selbst scheint größtenteils unversehrt zu sein. Sie stottert ein paar unverständliche Worte.>', 28153),
(131542, 'deDE', 'Knüpp, Nottlich und Yorrick melden, dass sie für den Aufbruch bereit sind.', 'Knüpp, Nottlich und Yorrick melden, dass sie für den Aufbruch bereit sind.', 28153),
(131541, 'deDE', 'Stammt Ihr aus Schluchtbach?', 'Stammt Ihr aus Schluchtbach?', 28153),
(131540, 'deDE', '', '<Annie zittert merklich. Ihr Blick starrt ins Leere.>', 28153),
(131539, 'deDE', 'Die Zeit ist gekommen. Trefft mich am Tor und wir überfallen Drustvar!', '', 28153),
(131505, 'deDE', 'Ich kann ihn nicht einfach so zurücklassen. Geht und sagt den anderen, was sie mit ihm gemacht haben. Wir treffen uns beim Tempel wieder.', '', 28153),
(131504, 'deDE', '*Schnief* Bitte wacht auf...', '', 28153),
(131503, 'deDE', 'Hakasi, Ihr seid jetzt in Sicherheit... Hakasi? He, wacht auf...', '', 28153),
(131497, 'deDE', 'Böser Teufelssaurier! Böse!', 'Böser Teufelssaurier! Böse!', 28153),
(131496, 'deDE', 'Ich danke Euch für Eure Hilfe und das Weiterleiten meiner Befehle. Ich werde Marschall Lesner Bericht erstatten.', '', 28153),
(131494, 'deDE', 'Die Zeit ist oft der Feind der Weisheit.', '', 28153),
(131493, 'deDE', 'Es wäre weise, zu warten, bis der Sturm vorüber ist, bevor wir in derart unwirtliches Gebiet vorstoßen.', '', 28153),
(131492, 'deDE', 'Also gut, ich bereite die Vorräte für eine Eilsendung vor.', '', 28153),
(131491, 'deDE', 'Berichtet Marschall Lesner, dass Rüstmeister Nottlich zum Dienst bereit ist!', '', 28153),
(131490, 'deDE', '', 'Ich treffe Euch am Tor, $gFestländer:Festländerin;. Ich hoffe, Ihr seid bereit für das, was uns dahinter erwartet.', 28153),
(131489, 'deDE', '', 'Hah! Lesner will also in die Wälder von Drustvar stürmen? Wurde auch langsam Zeit, dass hier mal was Interessantes passiert.', 28153),
(131487, 'deDE', '', 'Warum stört Ihr mich, $gFestländer:Festländerin;?\n\nSeht Ihr nicht, dass ich beschäftigt bin?', 28153),
(131486, 'deDE', 'Über dem Grabwald braut sich ein Sturm zusammen. Wir brauchen Glück, um unseren Feind überhaupt auszumachen, bevor er schon direkt vor unsrer Tür steht.\n\nAls ob Drustvar nicht ohne dieses Dreckswetter schon gefährlich genug wäre...', '', 28153),
(131485, 'deDE', 'Marschall Lesner befiehlt, dass wir uns seiner Expedition zur Suche nach Jaina anschließen.', 'Marschall Lesner befiehlt, dass wir uns seiner Expedition zur Suche nach Jaina anschließen.', 28153),
(131484, 'deDE', 'Wir bekommen hier an der Mauer nicht viele Festländer zu sehen.\n\nSeid Ihr auf der Suche nach Vorräten?', '', 28153),
(131479, 'deDE', 'Ich muss zugeben, dass mich Euer Mut überrascht, $gFestländer:Festländerin;.\n\nObwohl Ihr nicht von hier seid, begebt Ihr Euch in große Gefahr, um eine von uns zu retten. Ich hoffe, Euer Schwert ist genauso stark wie Euer Herz.\n\nWir warten auf Euren Aufbruchsbefehl.', '', 28153),
(131478, 'deDE', 'Haltet durch, Hakasi... Wir werden Euch retten, versprochen!', '', 28153),
(131477, 'deDE', 'Damit... werdet Ihr niemals durchkommen, Ihr Monster!', '', 28153),
(131476, 'deDE', 'Was? Festländer hier an der Mauer? Ihr wollt bestimmt einen Blick in das verfluchte Land Drustvar werfen, ohne den Gefahren, die dort lauern, entgegenzutreten.\n\nGeht nach Hause, $gJunge:Mädchen;. Reisende haben hier nichts zu suchen.', '', 28153),
(131475, 'deDE', 'Wie?\n\nEntschuldigt bitte. Ich habe... mich versprochen.\n\nIhr seid also mit dem Hause Prachtmeer verbündet? Dann gehe ich davon aus, dass Ihr nach Jaina fragen werdet, sonst wärt Ihr niemals so weit in den Norden gereist.\n\nIhr seid vielleicht gerade rechtzeitig gekommen.', '', 28153),
(131472, 'deDE', '<Gebt Lesner die Notiz von Taelia.>', '<Gebt Lesner die Notiz von Taelia.>', 28153),
(131471, 'deDE', 'Sieh an, hallo, Hanzabu! Wollt Ihr Eure Schulden begleich\'n?', '', 28153),
(131470, 'deDE', 'Welche Neuigkeiten bringt Ihr uns?', '', 28153),
(131469, 'deDE', 'Wir müssen ihn retten!', '', 28153),
(131468, 'deDE', 'Ich habe gerade Hakasis Stimme aus dieser Höhle kommen hören! Es klang so, als sei er in Schwierigkeiten...', '', 28153),
(131467, 'deDE', '$n! Hier drüben!', '', 28153),
(131466, 'deDE', 'Wachen! Verbündete! Streitkräfte der Horde nähern sich aus dem Südwesten! Macht Euch am Tor bereit!', '', 28153),
(131465, 'deDE', 'Ihr kümmert Euch um die Serpentine, ich gehe vor und suche Hakasi...', '', 28153),
(131461, 'deDE', 'MUA HA HA! Hanzabu, haltet Ihr mich für \'nen Narren? Die zwei werd\'n nicht durch Eure Hand sterb\'n.', '', 28153),
(131460, 'deDE', 'Zwei sin\' besonders mächtig. Die sollt\'n doch reich\'n für unsere Abmachung?', '', 28153),
(131459, 'deDE', 'Großer Bwonsamdi, ich bringe Euch mehr Seelen... wie vereinbart.', '', 28153),
(131458, 'deDE', '', 'Moment... Horcht, ich glaub\', ich kann was hör\'n.', 28153),
(131457, 'deDE', '', 'Die Barriere is\' weg! Lasst uns hier verschwind\'n!', 28153),
(131456, 'deDE', 'Sie is\' nutzlos gewes\'n. Bluttrolle überfall\'n das Land von Norden her, die Allianz drängt im Süden über unsre Grenze, un\' jetzt lasst Ihr auch noch dieses Hordengesindel in unsre eigene Stadt.', '', 28153),
(131455, 'deDE', '', 'Was Ihr auch gemacht habt, Ihr habt \'nen Teil vom Mojofluss zur Barriere aufgehalt\'n. Such\'n wir weiter nach solch\'n Dingern.', 28153),
(131454, 'deDE', '', 'Rakera hat zu den best\'n Anführern im Königreich geh...', 28153),
(131453, 'deDE', 'Ich habe Neuigkeiten über Hakasi.', 'Ich habe Neuigkeiten über Hakasi.', 28153),
(131452, 'deDE', '', 'Feinde im Anmarsch!', 28153),
(131451, 'deDE', '', 'Der Weg is\' versperrt! Schau\'n wir uns um, die Barriere muss man doch irgendwie wegmach\'n können.', 28153),
(131450, 'deDE', '', 'Kein Erbarmen!', 28153),
(131449, 'deDE', '', 'Nichts und Niemand hält uns auf!', 28153),
(131448, 'deDE', '', 'Und tot!', 28153),
(131447, 'deDE', '', 'Tayhuwaniwanga!', 28153),
(131446, 'deDE', '<Ein Monster brüllt in der Ferne.>', '', 28153),
(131445, 'deDE', 'Wir müssen ihn finden, bevor es zu spät ist! Trefft mich an der Schlucht, sobald Ihr bereit seid!', '', 28153),
(131444, 'deDE', 'Hakasi wollte etwas in der Schlucht untersuchen und ist noch immer nicht zurückgekehrt... Das ist kein gutes Zeichen.', '', 28153),
(131443, 'deDE', '', 'Vorsicht, die Geister hier sin\' wütend. Sin\' wohl schon lang hier gefang\'n.', 28153),
(131442, 'deDE', '', 'Unser Gast ist wach.', 28153),
(131440, 'deDE', '', 'Schmuserchen liebt den Wald. Ich seh nach, dass die Hunde ihn auch nicht geholt haben!', 28153),
(131439, 'deDE', 'Mich kriegt Ihr nicht zu fang\'n, Hexe!', '', 28153),
(131435, 'deDE', 'Helft den Zähmern, den Teufelssaurier zu bändigen!', 'Helft den Zähmern, den Teufelssaurier zu bändigen!', 28153),
(131434, 'deDE', 'Greift den roten Tod an!', 'Greift den roten Tod an!', 28153),
(131431, 'deDE', 'Werft ein Spielzeug, um den Teufelssaurier abzulenken!', 'Werft ein Spielzeug, um den Teufelssaurier abzulenken!', 28153),
(131430, 'deDE', 'Stürmt die Barriere, um sie zu durchbrechen!', 'Stürmt die Barriere, um sie zu durchbrechen!', 28153),
(131429, 'deDE', 'Flieht durch das Nordtor! Lasst Euch nicht vom Teufelssaurier erwischen!', 'Flieht durch das Nordtor! Lasst Euch nicht vom Teufelssaurier erwischen!', 28153),
(131428, 'deDE', 'Viel Glück, Lehrling!', '', 28153),
(131427, 'deDE', 'Willkomm\'n aufm Ausbildungsgelände! Das da vorn is\' Pinkie, unser munterer junger Teufelssaurier.', '', 28153),
(131426, 'deDE', 'Die Lieferung gehört uns, Allianzabschaum!', 'Die Lieferung gehört uns, Allianzabschaum!', 28153),
(131425, 'deDE', 'Untersucht den Leichnam genauer.', 'Untersucht den Leichnam genauer.', 28153),
(131424, 'deDE', '<Die Wunden sind tief. Die Schnitte wurden mit sorgfältiger Präzision gesetzt.$B$BReste einer Flüssigkeit glitzern auf den verletzten Bereichen im Licht.>', '', 28153),
(131419, 'deDE', '', 'Wir mach\'n uns auf, wenn Ihr bereit seid, aber verschwendet keine Zeit. Rakera wird in\'n Sanden nich\' lang überleb\'n.', 28153),
(131418, 'deDE', '', 'Ich werd nich\' ruh\'n, bis Rakera gefund\'n wurde.', 28153),
(131416, 'deDE', 'Habt Ihr schon mal mit \'nem Teufelssaurier gekämpft? Er beißt gar nich\' so fest zu. Meistens jedenfalls!', 'Habt Ihr schon mal mit \'nem Teufelssaurier gekämpft? Er beißt gar nich\' so fest zu. Meistens jedenfalls!', 28153),
(131415, 'deDE', '', 'Ihr habt Recht! Dann mal los!', 28153),
(131414, 'deDE', '', 'Ja, das sin\' weise Worte. Lasst uns den Weg aus dieser Krypta find\'n.', 28153),
(131413, 'deDE', '', 'Eure Worte sin\' wahr, Mann. Schau\'n wir uns um, es muss \'nen Weg raus geb\'n.', 28153),
(131408, 'deDE', 'Soldaten geben nicht auf, Bwu\'ja. Beherrscht Euch jetzt, dann suchen wir einen Weg hier raus. Für die Horde!', 'Soldaten geben nicht auf, Bwu\'ja. Beherrscht Euch jetzt, dann suchen wir einen Weg hier raus. Für die Horde!', 28153),
(131407, 'deDE', 'Wir haben eine Aufgabe, Bwu\'ja. Die müssen wir erfüllen, komme, was da wolle!', 'Wir haben eine Aufgabe, Bwu\'ja. Die müssen wir erfüllen, komme, was da wolle!', 28153),
(131406, 'deDE', 'Würdet Ihr diese Gesinnung auch dem Kriegshäuptling zeigen? Man verlässt sich auf uns!', 'Würdet Ihr diese Gesinnung auch dem Kriegshäuptling zeigen? Man verlässt sich auf uns!', 28153),
(131405, 'deDE', '', 'Kämpf\'n hat keinen Zweck, wir sin\' erledigt!', 28153),
(131404, 'deDE', 'Ihr seid eine Schattenjägerin, Bwu\'ja. Zeigt ihnen, dass das nicht nur ein bedeutungsloser Titel ist.', 'Ihr seid eine Schattenjägerin, Bwu\'ja. Zeigt ihnen, dass das nicht nur ein bedeutungsloser Titel ist.', 28153),
(131403, 'deDE', 'Wollt Ihr die Hoffnungen und Träume Eurer Ahnen kampflos hier zugrunde gehen lassen?', 'Wollt Ihr die Hoffnungen und Träume Eurer Ahnen kampflos hier zugrunde gehen lassen?', 28153),
(131399, 'deDE', 'Dann kämpft weiter! Glaubt an Euch und macht sie stolz!', 'Dann kämpft weiter! Glaubt an Euch und macht sie stolz!', 28153),
(131396, 'deDE', '', 'Wie? Natürlich nicht!', 28153),
(131392, 'deDE', 'Reißt Euch zusammen. Ihr seid eine Schattenjägerin, Ihr seid zu mehr fähig!', 'Reißt Euch zusammen. Ihr seid eine Schattenjägerin, Ihr seid zu mehr fähig!', 28153),
(131391, 'deDE', 'Prinzessin Talanji wartet wohl nich\' gern. Sie is\' schon mit Zul zum Dock losgezog\'n. Beeilt Euch lieber, wenn Ihr sie einhol\'n wollt.', '', 28153),
(131389, 'deDE', '', '', 28153),
(131388, 'deDE', 'Wenn Ihr Verzweiflung verspürt, ist Euer Geist noch lebendig und Ihr könnt Eure Lage verändern!', 'Wenn Ihr Verzweiflung verspürt, ist Euer Geist noch lebendig und Ihr könnt Eure Lage verändern!', 28153),
(131387, 'deDE', 'Er kommt frei! Lauft!', 'Er kommt frei! Lauft!', 28153),
(131386, 'deDE', 'Wir haben noch Hoffnung! Wenn wir zusammenarbeiten, finden wir einen Weg, diesen Fluch zu besiegen.', 'Wir haben noch Hoffnung! Wenn wir zusammenarbeiten, finden wir einen Weg, diesen Fluch zu besiegen.', 28153),
(131385, 'deDE', 'Für den Moment überlasse ich die Entscheidung, wie wir am besten vorgehen, Rokhan und Euch. Er kennt dieses Volk besser als ich.$b$bAußerdem hegen diese Trolle Vorurteile gegenüber denen, die sich wie ich weigern, tot zu bleiben. Ich will nicht, dass ihre engstirnige Sicht der Dinge unserer Akquisition ihrer Flotte im Weg steht.$b$bWir dürfen nicht scheitern. Sylvanas muss ihre Flotte bekommen.', '', 28153),
(131384, 'deDE', '', 'Ach? Und wie kommt Ihr darauf?', 28153),
(131383, 'deDE', 'Reißt Euch zusammen, wir sind noch nicht am Ende!', 'Reißt Euch zusammen, wir sind noch nicht am Ende!', 28153),
(131382, 'deDE', 'Wollt Ihr den Geistern Eurer Ahnen wirklich sagen, dass Ihr aufgegeben habt, wenn Ihr sie wiederseht?', 'Wollt Ihr den Geistern Eurer Ahnen wirklich sagen, dass Ihr aufgegeben habt, wenn Ihr sie wiederseht?', 28153),
(131377, 'deDE', 'Gebt der Verzweiflung nicht nach! Wir werden einen Ausweg finden.', 'Gebt der Verzweiflung nicht nach! Wir werden einen Ausweg finden.', 28153),
(131372, 'deDE', 'Legen wir los.', 'Legen wir los.', 28153),
(131371, 'deDE', 'Nicht zu glauben, dass Hakasi uns mit all der Arbeit alleinlässt. Dafür wird er bezahlen, wenn er zurückkehrt!', '', 28153),
(131370, 'deDE', '', 'Ha ha! Durch damit!', 28153),
(131369, 'deDE', '', 'Das is\' hoffnungslos. Wie soll\'n wir hier rauskomm\'n?', 28153),
(131333, 'deDE', 'Er hat etwas über eine Störung in der Schlucht erwähnt. Und ich sagte ihm, dass es bestimmt keinen Grund zur Sorge gibt.', '', 28153),
(131332, 'deDE', 'Hmmm... lasst mich mal überlegen. Oh ja! Ich sah ihn vor nicht allzu langer Zeit Richtung Schlucht marschieren. Ich frage mich nur, was er dort wollte?', '', 28153),
(131331, 'deDE', 'Hakasi? Ja, erst heute habe ich ihn gesehen. Nicht weit von hier war er dabei, die Opfergaben für das Ritual zu sammeln.', '', 28153),
(131329, 'deDE', '', 'Rückzug, bringt Euch in Sicherheit! So weit weg von diesen Schlang\'n wie nur möglich!', 28153),
(131327, 'deDE', 'Kaja, wir sollt\'n den Kurs anpass\'n. Wir sind bald im Gebiet von den Sethrak.', '', 28153),
(131325, 'deDE', '', 'Die Schlangenmenschen? Ich dachte, die versteck\'n sich untern Dünen...', 28153),
(131322, 'deDE', '', 'Da vorn, der Pass! Fliegt tief und haltet die Augen off\'n nach \'nem Lebenszeichen von Rakera.', 28153),
(131306, 'deDE', 'Ihr habt noch nie den großen Akunda gesehen? Dann kommt Ihr genau zur rechten Zeit!', '', 28153),
(131305, 'deDE', 'Ich habe vor Akundas Ankunft noch so viel zu erledigen! Dafür ist keine Zeit... gar keine Zeit!', '', 28153),
(131304, 'deDE', 'Habt Ihr Hakasi gesehen?', 'Habt Ihr Hakasi gesehen?', 28153),
(131303, 'deDE', 'Viele Jahre sind vergangen, seit unser Volk Akunda beschworen hat. Ich kann es kaum erwarten, wieder in seiner Gegenwart zu sein!', '', 28153),
(131302, 'deDE', '%s verschlingt aufgeregt jeden Happen und rülpst danach Flammen!', '', 28153),
(131300, 'deDE', '%s verschlingt geräuschvoll die Pflanze.', '', 28153),
(131299, 'deDE', 'Endlich eine richtige Schlacht!\n\nDiese Narren von der Horde glauben, sie gelangen dort durch die Schlucht und würden zum Gefechtsstand durchkommen. Was ich dazu sage?\n\nPAH!\n\nKommt, lasst uns gemeinsam Abschaum niedermetzeln gehen.', '', 28153),
(131298, 'deDE', '', 'Ich bin froh, dass Ihr hier seid, $gSoldat:Soldatin;. Wir halten kaum noch durch!\n\nDie Triumphfeste ist ein entscheidender Engpass für den Angriff auf das Tor. Die Schlucht im Norden wird ständig von Verstärkung aus Orgrimmar angegriffen. Wenn wir also diese Position nicht halten können, sind alle unsere Konvois aus Theramore gefährdet.', 28153),
(131297, 'deDE', 'Wie Ihr wünscht, Meister Higashi...', '', 28153),
(131296, 'deDE', 'Das Essen zu verkosten ist nicht dasselbe wie \"das Festmahl vorzubereiten\". Ich bitte Euch nicht noch einmal, Rifu.', '', 28153),
(131295, 'deDE', 'Aber ich bin bereits damit beschäftigt, das Festmahl vorzubereiten!', '', 28153),
(131294, 'deDE', 'Hakasi muss noch die letzten Opfergaben bringen. Bitte nehmt unseren Gast mit, um sie zu sammeln.', '', 28153),
(131293, 'deDE', 'Sehr wohl, Meister Higashi!', '', 28153),
(131292, 'deDE', 'Rifu! Wir haben einen Gast, denn Ihr kennenlernen müsst.', '', 28153),
(131291, 'deDE', 'Ohne sie können wir den Loa nicht beschwören. Vielleicht könnt Ihr uns helfen...', '', 28153),
(131290, 'deDE', 'Der Beginn des Rituals steht kurz bevor, aber viele der benötigten Opfergaben fehlen noch.', '', 28153),
(131289, 'deDE', 'Sucht die uralten Schrifttafeln in den Hallen des Tempels. Sie werden Euch die Legende von Akunda offenbaren.', '', 28153),
(131255, 'deDE', 'Mög\'n wir immer dieser großen Donnerechse Tribut zoll\'n un\' möge er immer über diesen Dschungel wach\'n.', '', 28153),
(131254, 'deDE', '', 'Gut. Jetzt is\' es an der Zeit für Euch, ein Ei auszuwähl\'n. Ihr wisst, dass das Junge Euch akzeptiert, wenn Ihr seine Stimme in Euerm Kopf hört.', 28153),
(131250, 'deDE', '', '<Matriarchin Jaz\'lith begutachtet Euch aufmerksam.>', 28153),
(131249, 'deDE', '', 'Da is\' sie. Is\' sie nich\' die perfekte Mischung aus Wildheit un\' Anmut? Fordert sie raus, wenn Ihr Euch traut.', 28153),
(131248, 'deDE', '', 'Das Monument da sieht genauso aus wie Bwonsamdis Schreine in Zuldazar, is\' aber viel älter.', 28153),
(131247, 'deDE', 'Mein Terrorhorn und ich kennen uns schon seit dem Tag, an dem es geschlüpft ist. Wir kämpf\'n als Einheit.', 'Mein Terrorhorn und ich kennen uns schon seit dem Tag, an dem es geschlüpft ist. Wir kämpf\'n als Einheit.', 28153),
(131246, 'deDE', '\'n Bestienrufer braucht Talent, sicher, aber auch unendlich viel Geduld. Junge Terrorhörner könn\'n nämlich ziemlich ungestüm sein!', '\'n Bestienrufer braucht Talent, sicher, aber auch unendlich viel Geduld. Junge Terrorhörner könn\'n nämlich ziemlich ungestüm sein!', 28153),
(131245, 'deDE', 'Un\' so hab\'n wir an diesem Ort den Tempel zu Ehren von Akunda errichtet, auf dass wir nie wieder diesen groß\'n Loa vergess\'n.', '', 28153),
(131244, 'deDE', 'Als der Staub sich gelegt hatte, sin\' wir auf den Gipfel des Bergs gestieg\'n. Vor uns lag der leblose Leichnam von Zul\'khan, aber Akunda war nirgendwo zu seh\'n.', '', 28153),
(131243, 'deDE', 'Es hat ausgeseh\'n, als wollte der Kampf niemals end\'n, aber schließlich hat sich der Staub verzog\'n un\' Stille is\' eingekehrt...', '', 28153),
(131242, 'deDE', 'Akunda war endlich zurückgekehrt un\' im nächsten Moment sin\' die beid\'n Bestien aufeinander losgegang\'n. Mit jedem Schlag hat die Erde gebebt!', '', 28153),
(131241, 'deDE', 'Als alle Hoffnung schon verlor\'n schien, hab\'n wir \'n donnerndes Brüllen in der Schlucht gehört. Eine Gestalt is\' über den Klippen aufgeragt un\' hat das Mondlicht verdeckt.', '', 28153),
(131240, 'deDE', 'Wir ham Zul\'khan mit all unsrer Kraft bekämpft, aber er war zu stark für uns! Er hat sich befreit... Wir war\'n verlor\'n.', '', 28153),
(131239, 'deDE', 'Wir hab\'n Zul\'khan tief in die Schlucht reingelockt un\' ihn angegriff\'n. Von oben hab\'n wir \'n großes Netz auf ihn geworf\'n...', '', 28153),
(131238, 'deDE', 'Die Ältesten meines Stammes hab\'n sich im Herzen von Vol\'Aman getroff\'n. Würd\'n wir zusammen kämpf\'n oder unser Hab und Gut zusammenpack\'n un\' aus dem Dschungel flieh\'n? Wir entschloss\'n uns zu kämpf\'n!', '', 28153),
(131237, 'deDE', 'Jetzt konnte niemand mehr Zul\'khan und seinen Terror aufhalt\'n. Er hat gnadenlos Jagd auf meine Leute gemacht un\' sie nach Belieben getötet. Es war\'n finstre Zeiten...', '', 28153),
(131236, 'deDE', 'Wir hab\'n der Donnerechse keinen Tribut mehr gezollt, un\' schließlich is\' Akunda aus dem Dschungel verschwund\'n...', '', 28153),
(131235, 'deDE', 'Akunda hat uns vor Zul\'khans Terror geschützt, aber im Laufe der Jahre is\' mein Volk selbstgefällig geword\'n.', '', 28153),
(131234, 'deDE', 'Zul\'khan, der Teufelssaurier, war neidisch auf die Macht des Loas. Er hat im dunklen Dschungel gelauert, aus Gier gejagt un\' zum Vergnügen getötet.', '', 28153),
(131233, 'deDE', 'Alle Kreaturen des Dschungels verehrt\'n seine erhabene Macht. Alle außer einem, dem tyrannischen Zul\'khan...', '', 28153),
(131232, 'deDE', 'Vor langer Zeit hab\'n meine Leute voller Ehrfurcht mit angeseh\'n, wie die große Donnerechse durch den Dschungel gezog\'n is\'.', '', 28153),
(131231, 'deDE', 'Ich, Zen\'gaji, Anführer meines Stammes un\' Architekt dieses Tempels, widme ihn hiermit dem mächtig\'n Akunda.', '', 28153),
(131230, 'deDE', 'Ich hab seit meiner Geburt trainiert, \'n Bestienrufer zu werd\'n. Was habt Ihr getan?', 'Ich hab seit meiner Geburt trainiert, \'ne Bestienruferin zu werd\'n. Was habt Ihr getan?', 28153),
(131229, 'deDE', 'Lasst uns kämpfen!', 'Lasst uns kämpfen!', 28153),
(131228, 'deDE', '', 'Zandalar für immer!', 28153),
(131227, 'deDE', '', 'Die Loa steh\'n mir bei.', 28153),
(131226, 'deDE', '', 'Für Zuldazar!', 28153),
(131224, 'deDE', '', 'Kriegswache Rakera war meine Kommandantin. Die beste, die diese Stadt je hatte.', 28153),
(131223, 'deDE', 'Ich stell keine Frag\'n. Ich befolg Befehle. Ihr solltet besser dasselbe tun.', '', 28153),
(131222, 'deDE', 'Raus damit, $n. Ich werd nich\' fürs Reden bezahlt.', '', 28153),
(131221, 'deDE', '', 'Seid Ihr lebensmüde? General Jakra\'zet hat überall Aug\'n und Ohr\'n.', 28153),
(131220, 'deDE', '', 'Wenn Ihr was wollt, dann macht\'s kurz.', 28153),
(131218, 'deDE', '', 'Wie Ihr seh\'n könnt, sin\' auch in unsern Reih\'n noch \'n paar, die das gleiche glaub\'n.', 28153),
(131215, 'deDE', '', 'He, Ihr da. Seid Ihr der Fremdling, der überall nach\'m General fragt?', 28153),
(131214, 'deDE', '', 'Die Dünen sind \'n Todesurteil. Ich werd\' nich\' rumsteh\'n un\' zuseh\'n, wie Rakera vom Sand verschlung\' wird!', 28153),
(131213, 'deDE', '', 'Was sie dort rausgefund\'n hat, hat ihr \'ne Reise in die Wüste eingebrockt.', 28153),
(131212, 'deDE', '', 'Sie hat mir gesagt, sie kann beinah beweis\'n, dass General Jakra\'zet \'n Hochverräter is\'. Seitdem hab ich nix mehr von ihr gehört.', 28153),
(131211, 'deDE', '', 'Geh\'n wir \'n Stück, aber bleib\'n wir unauffällig.', 28153),
(131210, 'deDE', 'Was könnt Ihr mir über General Jakra\'zet erzählen?', 'Was könnt Ihr mir über General Jakra\'zet erzählen?', 28153),
(131209, 'deDE', '', 'Was kann ich für Euch tun?', 28153),
(131208, 'deDE', 'Tut mir leid, dass Ihr beide da reingezog\'n wurdet. Aber jetzt könnt Ihr wenigstens Bwonsamdi seh\'n, wie Ihr wolltet! Höhöhö!', '', 28153),
(131207, 'deDE', 'Gute Arbeit. Die Seele von der hier wird \'n würdiges Opfer für Bwonsamdi abgeb\'n.', '', 28153),
(131206, 'deDE', 'Verflucht, sie hab\'n mich gefund\'n! Helft mir, dann können wir über den Gefallen red\'n, den Ihr wollt.', '', 28153),
(131205, 'deDE', 'Zu den Waffen!', '', 28153),
(131204, 'deDE', '', 'Marschall! Nein!', 28153),
(131203, 'deDE', 'Lasst $Gihn:sie; los, Ihr...', '', 28153),
(131202, 'deDE', '', 'Vorsicht $gFestländer:Festländerin;!', 28153),
(131201, 'deDE', 'Knüpp, Yorrick! Schwärmt aus und durchsucht die Umgebung nach...', '', 28153),
(131200, 'deDE', '', 'Meint Ihr, sie ist... da runter?', 28153),
(131199, 'deDE', 'Ich verstehe das nicht. Der Pfad verläuft doch in dieser Richtung.', '', 28153),
(131198, 'deDE', 'Eine Sackgasse...', '', 28153),
(131197, 'deDE', '', 'Wo... sind wir hier nur?!', 28153),
(131196, 'deDE', 'In der Entfernung lässt sich ein Gebäude ausmachen. Jaina ist sicher dorthin aufgebrochen!', '', 28153),
(131195, 'deDE', 'Die Bestien blockieren den Weg. Bahnt Euch einen Weg hindurch!', '', 28153),
(131194, 'deDE', 'Wir müssen weiter in den Wald hinein. Formation einnehmen!', '', 28153),
(131193, 'deDE', 'Das sieht nach Eismagie aus... Jaina muss hier gewesen sein!', '', 28153),
(131192, 'deDE', 'Verdammt! Wir müssen wohl ohne ihn weitermachen... halt, was ist das?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131191, 'deDE', 'Sir, es gibt keine Spur von Nottlich. In diesem Sturm können wir ihm unmöglich folgen!', '', 28153),
(131190, 'deDE', 'Das... Das sieht nicht gut aus.', '', 28153),
(131189, 'deDE', '', 'Was zum...', 28153),
(131188, 'deDE', 'Schnell, sie sind dort entlang!', '', 28153),
(131187, 'deDE', '', 'Ein Hinterhalt!', 28153),
(131186, 'deDE', 'Aaaaiieeeee!', '', 28153),
(131185, 'deDE', 'Nottlich! Nein!', '', 28153),
(131184, 'deDE', 'Wartet... Ich glaube, ich sehe etwas...', '', 28153),
(131183, 'deDE', 'Weiter. Wir müssen in Bewegung bleiben.', '', 28153),
(131182, 'deDE', 'Ich wünschte, es wäre so. Ich befürchte aber, dass hier noch viel dunklere Mächte am Werk sind.', '', 28153),
(131181, 'deDE', '', 'Sieht aus, als gäbe es hier nicht nur Wildtiere im Wald. Meint Ihr, das war ein Verbannter?', 28153),
(131180, 'deDE', 'Halt! Was ist das?', '', 28153),
(131179, 'deDE', 'Das verheißt nichts Gutes...', '', 28153),
(131178, 'deDE', 'Diese Bestien werden immer dreister. Jetzt greifen sie schon hier im offenen Gelände an.', '', 28153),
(131177, 'deDE', 'Was war das? Seid auf der Hut, Männer!', '', 28153),
(131176, 'deDE', 'Auf meinen Befehl!', '', 28153),
(131175, 'deDE', 'Macht Eure Waffen bereit und seid stark, denn heute Nacht reiten wir in die Dunkelheit!', '', 28153),
(131174, 'deDE', 'Die wilden Tiere in diesem Wald reagieren äußerst gereizt auf... nun ja, eigentlich so gut wie alles.', '', 28153),
(131173, 'deDE', 'In diesem Sturm sieht man kaum etwas. Bleibt alle zusammen und verlasst den Pfad nicht.', '', 28153),
(131172, 'deDE', 'Ich bin bereit zur Ausbildung.', 'Ich bin bereit zur Ausbildung.', 28153),
(131171, 'deDE', 'Wir trainier\'n Wildtiere jeder Gestalt un\' Größe. Auch, wenn sie eigentlich Lasttiere werd\'n soll\'n, müssen sie für\'n Kampf trainiert werd\'n!', '', 28153),
(131170, 'deDE', 'Wir werden dem Pfad bis Schicksalsend folgen. Dorthin wollte die Karawane ins Exil aufbrechen.', '', 28153),
(131169, 'deDE', '', 'Die Geister... verlass\'n... mich...', 28153),
(131168, 'deDE', '', 'Aughhh!', 28153),
(131167, 'deDE', '', 'Ich kann... nich\' mehr...', 28153),
(131166, 'deDE', '', 'Ihr werdet uns nie besieg\'n! Ich verfluch\' Euch mit meinem letzten Atemzug! Wir seh\'n uns auf der Andren Seite!', 28153),
(131165, 'deDE', '', 'Die Verbindung zwischen Tier un\' Reiter wird durch \'nen Fetisch ermöglicht. Berührt unsern Saurierstein, wenn Ihr bereit seid.', 28153),
(131158, 'deDE', 'Im Namen von Akunda, dem großen Loa, heiße ich Euch in diesem Tempel willkommen.', '', 28153),
(131148, 'deDE', '', 'Ihr kämpft gut. Mein Nachwuchs ist bei Euch sicher.', 28153),
(131142, 'deDE', '', 'Für meinen Nachwuchs nur das Beste!', 28153),
(131115, 'deDE', 'Schnappen wir sie uns, Jungs!', '', 28153),
(131114, 'deDE', 'Feiglinge! Schickt Euren besten Champion, dann sehen wir mal, was er kann!', '', 28153),
(131113, 'deDE', 'Dann wollen wir doch einmal sehen, was die Horde so auf Lager hat, was?', '', 28153),
(131112, 'deDE', '', 'Euer Blut wird fließ\'n!', 28153),
(131111, 'deDE', '', 'Dieses Mal hab ich Euch erwischt, Hanzabu! Ihr werdet für den Tod meiner Schwestern bezahl\'n!', 28153),
(131109, 'deDE', 'Wir such\'n den Loa Bwonsamdi.', 'Wir such\'n den Loa Bwonsamdi.', 28153),
(131108, 'deDE', 'Das Schlimmste haben wir wohl überstanden. Machen wir hier kurz Pause, bevor wir weiter vorstoßen.', '', 28153),
(131107, 'deDE', 'Gute Arbeit. Diese Truppen werden für den Krieg unschätzbar wertvoll sein.', '', 28153),
(131106, 'deDE', 'Macht kurz Pause, Leute. Wir warten einen Moment hier, dann ziehen wir los.', '', 28153),
(131105, 'deDE', 'Soldaten der Allianz! Verteidigt diesen tapferen Konvoi auf dem Weg zum Gefechtsstand!', '', 28153),
(131098, 'deDE', 'Diese Klauen und Zähne... Davon werd ich noch lange schlecht träum\'n.', 'Diese Klauen und Zähne... Davon werd ich noch lange schlecht träum\'n.', 28153),
(131097, 'deDE', 'Grade rechtzeitig!', 'Grade rechtzeitig!', 28153),
(131096, 'deDE', 'Hätt nich\' gedacht, dass ich es schaff. Danke!', 'Hätt nich\' gedacht, dass ich es schaff. Danke!', 28153),
(131094, 'deDE', 'Eure Kleider sin\' nich\' dreckig un\' Ihr stinkt nich\'.$b$bWas habt Ihr im Sumpf zu such\'n?', '', 28153),
(131093, 'deDE', 'Wer seid Ihr, Fremdling? Ihr riecht nich\' wie \'n Bluttroll...', '', 28153),
(131088, 'deDE', '', 'Juhu! Das wird die beste Teeparty aller Zeiten! Suchen wir die anderen Gäste.', 28153),
(131087, 'deDE', 'Was wollt\'n Ihr von Hanzabu?', '', 28153),
(131086, 'deDE', '', 'Rüsselchen! Du weißt doch, dass Tante Maria dich nicht im Haus will! Du machst alles schmutzig!', 28153),
(131085, 'deDE', '', 'Oh, Herr Leckermaul! Du warst aber hungrig, hm? Na gut, gehen wir. Es ist Zeit für den Tee.', 28153),
(131081, 'deDE', '', 'Böser Bürgermeister Stricks! Läuft immer vor seiner Verantwortung für die Dorfbewohner weg. Ha, jetzt läufst du nicht mehr!', 28153),
(131080, 'deDE', '', 'Ich vertrau ihm nich\'. Wir sollt...', 28153),
(131079, 'deDE', 'Ruhe! Ich will kein Gewimmer mehr hör\'n!', '', 28153),
(131078, 'deDE', '', 'Auggh!', 28153),
(131077, 'deDE', 'Oh, das is\' ma\' \'n guter Fang!', '', 28153),
(131057, 'deDE', '$n hat das Sägewerk verteidigt!', '', 28153),
(131056, 'deDE', 'Die Allianz hat das Schiffswrack eingenommen!', '', 28153),
(131055, 'deDE', 'Die Horde hat die Schiffswrack eingenommen!', '', 28153),
(131054, 'deDE', '$n hat das Schiffswrack angegriffen!', '', 28153),
(131049, 'deDE', 'Die Horde hat einen Panzer auf die Straße zur Feste Nordwacht geschickt! Er muss zerstört werden!', 'Die Horde hat einen Panzer auf die Straße zur Feste Nordwacht geschickt! Er muss zerstört werden!', 28153),
(131048, 'deDE', 'Szenario abgeschlossen.', 'Szenario abgeschlossen.', 28153),
(131033, 'deDE', '', 'Räumt der 7. Flotte den Weg frei! Wir werden unseren Anstieg beginnen, wenn die Verstärkung eintrifft.', 28153),
(131032, 'deDE', 'Test', '', 28153),
(131030, 'deDE', '', 'Schaut, Mann! Die Mojospur führt nach Norden. Folg\'n wir ihr.', 28153),
(131025, 'deDE', '', 'Welche Neuigkeiten gibt es aus dem Norden?', 28153),
(131010, 'deDE', '', 'Mhm... Ein Opfer, und es is\' noch frisch. Die Mojoreste vom Ritual hier hab\'n \'ne Spur hinterlass\'n. Seh\'n wir nach, wo sie hinführt.', 28153),
(131009, 'deDE', 'Im Rücken dieses Leichnams steckt ein kleiner Dolch.', 'Im Rücken dieses Leichnams steckt ein kleiner Dolch.', 28153),
(131008, 'deDE', '', 'Ich spüre \'ne stärkere Präsenz im Norden. Geh\'n wir und schau\'n es uns an.', 28153),
(131007, 'deDE', '', 'Dieses Opfer war nich\' da, als ich hergekommen bin. Bwonsamdi hat hier wohl noch \'nen Anhänger.', 28153),
(131000, 'deDE', 'Das raue Klima Nazmirs hat die Schrift auf der Tafel größtenteils verblassen lassen. Ihr könnt nur die Wörter \"preisen\", \"Geist\" und \"Grab\" ausmachen.', 'Das raue Klima Nazmirs hat die Schrift auf der Tafel größtenteils verblassen lassen. Ihr könnt nur die Wörter \"preisen\", \"Geist\" und \"Grab\" ausmachen.', 28153),
(130979, 'deDE', 'Unsere Späher haben gemeldet, dass Truppen der Horde im Schutz der Dunkelheit auf die Nordwacht zumarschiert sind. Wir benötigen sofort Eure Hilfe!', '', 28153),
(130978, 'deDE', '', 'Soldaten der Allianz! Unsere Zeit ist gekommen! Unser Angriff auf die Großen Tore von Mulgore beginnt hier und jetzt. Kämpft als Einheit, und kämpft tapfer.', 28153),
(130977, 'deDE', '', 'Alle zu den Docks!', 28153),
(130969, 'deDE', '', 'Ah, $p, da seid Ihr ja. Wie G\'huun es uns zugeflüstert hat. Das wird \'n Spaß werd\'n!', 28153),
(130967, 'deDE', '', 'Soldaten der 7. Flotte, es ist Zeit für unseren Angriff. Sammelt Eure Sachen ein und macht Euch bereit zum Ausrücken.', 28153),
(130947, 'deDE', 'Ich verhungere hier, siehst du das nicht?', '', 28153),
(130946, 'deDE', 'Mama, füttere mich!!!', '', 28153),
(130945, 'deDE', '%s gibt Euch einen freundlichen Kopfstoß.', '', 28153),
(130944, 'deDE', '', 'Mein Tod is\' nich\' mein Ende.', 28153),
(130943, 'deDE', 'Willst du ein Spiel spielen? Du rennst und ich versuche, dich zu fangen und aufzufressen!', '', 28153),
(130940, 'deDE', '%s starrt Euch klagend an.', '', 28153),
(130939, 'deDE', '%s winselt vor Hunger.', '', 28153),
(130938, 'deDE', '%s winselt und stupst Euch kräftig an.', '', 28153),
(130937, 'deDE', 'Der Magen von %s grummelt laut.', '', 28153),
(130936, 'deDE', '%s beschnüffelt Euch herzlich.', '', 28153),
(130935, 'deDE', '', 'Ihr könnt uns nich\' alle besieg\'n. Dazar\'alor wird fall\'n!', 28153),
(130934, 'deDE', 'Ich werd meine Verwundeten rausbring\'n. Trefft uns in Raz\'lotec, wenn Ihr so weit seid, dann setz\'n wir dieser Belagerung ein Ende.', '', 28153),
(130932, 'deDE', 'Schlüpft...', 'Schlüpft...', 28153),
(130931, 'deDE', '', 'Ich weid Euch aus!', 28153),
(130930, 'deDE', '', 'Wir werd\'n Euch häut\'n!', 28153),
(130929, 'deDE', '', 'Mehr Blut! Mehr Blut!', 28153),
(130928, 'deDE', '', 'Die Mutta braucht Euer Blut.', 28153),
(130927, 'deDE', '', 'Schöne Knochen.', 28153),
(130926, 'deDE', '', 'Frisches Fleisch, fließ\'ndes Blut.', 28153),
(130925, 'deDE', 'Puh, ich werd \'ne Woche brauch\'n, um mich von den ganzen Schnitten zu erhol\'n.', 'Puh, ich werd \'ne Woche brauch\'n, um mich von den ganzen Schnitten zu erhol\'n.', 28153),
(130924, 'deDE', 'Barbarische Bluttrolle!', 'Barbarische Bluttrolle!', 28153),
(130923, 'deDE', 'Ha! Mein Blut werdet Ihr heute nich\' krieg\'n.', 'Ha! Mein Blut werdet Ihr heute nich\' krieg\'n.', 28153),
(130922, 'deDE', 'Sie hab\'n gesagt, sie würd\'n mein Blut benutz\'n.', 'Sie hab\'n gesagt, sie würd\'n mein Blut benutz\'n.', 28153),
(130921, 'deDE', 'Ha! Ihr werdet mich heute nich\' krieg\'n, Ihr Barbaren.', 'Ha! Ihr werdet mich heute nich\' krieg\'n, Ihr Barbaren.', 28153),
(130920, 'deDE', 'Sie hab\'n ein Ritual angefang\'n. Ich hab gespürt, wie meine Knochen sich unter meiner Haut beweg\'n.', 'Sie hab\'n ein Ritual angefang\'n. Ich hab gespürt, wie meine Knochen sich unter meiner Haut beweg\'n.', 28153),
(130919, 'deDE', 'Sie hab\'n mir Symbole in den Arm geritzt. Die Barbaren.', 'Sie hab\'n mir Symbole in den Arm geritzt. Die Barbaren.', 28153),
(130918, 'deDE', 'Ha! Diesen Troll erwisch\'n sie heute nich\'!', 'Ha! Diesen Troll erwisch\'n sie heute nich\'!', 28153),
(130917, 'deDE', 'Dank Euch! Habt viel\'n Dank.', 'Dank Euch! Habt viel\'n Dank.', 28153),
(130915, 'deDE', 'Stellt das Feuer ein. Hier is\' unsere Verstärkung!', '', 28153),
(130914, 'deDE', '', 'Geh\'n wir, Mann, jetzt jag\'n wir!', 28153),
(130913, 'deDE', '', 'Kommt! Das Ausschlüpf\'n fängt bald an.', 28153),
(130907, 'deDE', 'Ich bin bereit.', 'Ich bin bereit.', 28153),
(130906, 'deDE', '', 'Willkommen im Kriegsbestienkral, $n.\n\nIch hab schon von der Horde gehört un\' ich weiß, dass Ihr Rastakhan ein Abkommen vorschlag\'n wollt.\n\nMal seh\'n, ob Ihr uns nützlich sein könnt. Vielleicht leg\'n wir dann ein gutes Wort für Euch bei den Stufen von Dazar ein...', 28153),
(130905, 'deDE', 'Wenn ich den find, der das mit Euch gemacht hat, alter Junge...', '', 28153),
(130904, 'deDE', 'Die Bluttrolle kämpfen nich\' fair.', '', 28153),
(130903, 'deDE', 'Dunkle Magie. Das is\' nich\' natürlich.', '', 28153),
(130902, 'deDE', 'Mit was hab\'n sie Euch verflucht, alter Junge?', '', 28153),
(130901, 'deDE', 'Kommt schon, alter Junge. Ihr schafft das.', '', 28153),
(130900, 'deDE', 'Haltet die Aufstellung! Holt die Toten und Verwundeten, aber die Aufstellung muss erhalt\'n bleib\'n.', '', 28153),
(130899, 'deDE', 'Achtet auf den Himmel! Da komm\'n noch mehr Blutbäuche.', '', 28153),
(130898, 'deDE', 'Ihr seid Zandalari, also kämpft auch so!', '', 28153),
(130897, 'deDE', 'Holt die Verwundeten auf die Beine! Diese Barbaren werd\'n sich keinen von uns hol\'n.', '', 28153),
(130896, 'deDE', 'Haltet stand, Brüder und Schwestern! Heute zwing\'n uns diese Barbaren nich\' in die Knie!', '', 28153),
(130842, 'deDE', 'Wirkt einen Stärkungszauber auf alle.', 'Wirkt einen Stärkungszauber auf alle.', 28153),
(130841, 'deDE', '', 'Vielleicht seid Ihr stärker, als Ihr ausseht. Mein Champion wird keine Gnade mit Euch hab\'n. Fordert ihn raus, wenn Ihr bereit seid.', 28153),
(130840, 'deDE', '', 'Ich hab auch nich\' erwartet, dass ein Novize für Euch \'ne große Herausforderung darstell\'n würde. Mal seh\'n, wie Ihr gegen \'nen stärkeren Gegner abschneidet.', 28153),
(130839, 'deDE', 'Ich kann Euch mit Stärkungszaubern und Vorteilen versorgen, die Euch an der Kriegsfront helfen.', '', 28153),
(130838, 'deDE', '', 'Seid Ihr wirklich bereit, so \'ne Verantwortung zu übernehm\'n? Es is\' noch nich\' zu spät, es sich anders zu überleg\'n.', 28153),
(130822, 'deDE', 'Weitere Kämpfer werden zu Generälen befördert!', 'Weitere Kämpfer werden zu Generälen befördert!', 28153),
(130797, 'deDE', '', 'Ihr seid zumindest sehr entschloss\'n. Es is\' jetz\' Zeit, Matriarchin Jaz\'lith zu treff\'n. Kommt.', 28153),
(130796, 'deDE', '', 'Seid Ihr bereit, die Bedürfnisse Eures Jungen über Eure eignen zu stell\'n? Wisst Ihr eigentlich, wie viel die fress\'n?', 28153),
(130795, 'deDE', 'Die Verbindung mit unseren Tieren entsteht beim Schlüpfen und dauert \'n Leben lang. Die sind Familie.', 'Die Verbindung mit unseren Tieren entsteht beim Schlüpfen und dauert \'n Leben lang. Die sind Familie.', 28153),
(130794, 'deDE', '', 'Terrorhörner sin\' Pflanzenfresser, also gebt ihnen bloß kein Fleisch!', 28153),
(130793, 'deDE', 'Jungtiere sind ziemlich wählerisch bei der Wahl der Person, mit der sie \'ne Bindung eingehen. Warum es \'nen Fremdling wie Euch ausgewählt hat, ist mir echt \'n Rätsel!', 'Jungtiere sind ziemlich wählerisch bei der Wahl der Person, mit der sie \'ne Bindung eingehen. Warum es \'nen Fremdling wie Euch ausgewählt hat, ist mir echt \'n Rätsel!', 28153),
(130732, 'deDE', '', 'Ah, Hir\'eek, der Fledermausloa... er muss irgendwo in Nazmir sein. Er is\' schlau un\' weiß bestimmt, wie wir die aufhalt\'n.', 28153),
(130731, 'deDE', '', 'Ich spür seine Macht... er\'s in der Nähe. Näher als die andren Loa.', 28153),
(130730, 'deDE', '', 'Bwonsamdi... der Loa des Todes. \'n mächtiger Loa, aber auch geriss\'n un\' gefährlich... für ihn is\' alles \'n Geschäft.', 28153),
(130710, 'deDE', '', 'Der Froschloa, Krag\'wa... er is\' in Nazmir! Er is\'n starker Loa, der sich das mit den Bluttrollen sicher nich\' gefall\'n lässt.', 28153),
(130707, 'deDE', 'Wir lass\'n uns also mit\'m Todesloa ein, mit\'m Schildkröt\'nloa, mit\'m Fledermausloa und mit\'m Froschloa... damit wir die Bluttrolle aufhalt\'n.', '', 28153),
(130705, 'deDE', '', 'Wir sin\' nich\' mächtig genug, um die Bluttrolle aufzuhalt\'n. Uns bleibt nur eine Option: die Loa in Nazmir.', 28153),
(130692, 'deDE', '', '<Sie starrt Euch... suggestiv an.>', 28153),
(130625, 'deDE', '', 'Talanji redet darüber, begrenzte Unterstützung von Kontakten in Zuldazar zu erhalten, während der Spieler vergessene Loa um Hilfe bittet.', 28153),
(130566, 'deDE', '', 'COOLE ZWISCHENSZENE/FLYOVER. Ihr seht das verderbte Konstrukt der Titanen. Die Blutmatriarchin bemerkt Euch und spricht einen Fangspruch auf Talanji!', 28153),
(130494, 'deDE', '', 'Frei! Wir müss\'n los! Springt auf!', 28153),
(130490, 'deDE', '', 'Noch mehr von mein\' Soldat\'n, aber der Pfad geht weiter. Also müss\'n wir es auch.', 28153),
(130485, 'deDE', '', 'Mein Volk... abgeschlachtet. Seht Ihr jetz\', was für\'n Übel wir bekämpf\'n, $n? Die Bluttrolle sin\' Monster!', 28153),
(130383, 'deDE', '', 'Euer Rat is\' weise, Rokhan, doch die Zeit für Tat\'n is\' gekomm\'. Die Bluttrolle müss\'n aufgehalt\'n werden.', 28153),
(130372, 'deDE', '', 'Seid schnell und tödlich. Zul und ich wart\'n auf den Stufen der Pyramide auf Euch. Es ist nich\' zu verfehl\'n.', 28153),
(130361, 'deDE', '', 'Wenn Ihr überlebt, trefft uns am Eingang zur Fassgasse. Dann hab ich möglicherweise \'ne Aufgabe für Euch.', 28153),
(130353, 'deDE', 'Ich war noch nie in Zandalar. Zuldazar is\' größer, als ich\'s mir hätte vorstell\'n können.$b$bNehmt Euch bloß in Acht, Mann. Die Zandalari mög\'n geschniegelt und gestriegelt wirk\'n, aber es sin\' immer noch Trolle. Jenen gegenüber, die Schwäche zeig\'n, sind sie unbarmherzig.', '', 28153),
(130352, 'deDE', 'Prinzessin Talanji erwartet Euch am Ende der Docks. Bummelt nich\' und betretet nich\' die Stadt, bevor die Rituale durchgeführt wurd\'n, sonst droht Euch die Todesstrafe.\n\nIhr werdet die sprechende Leiche hier lass\'n, bis der König was andres sagt.', '', 28153),
(130121, 'deDE', '', 'Wie Ihr wünscht.', 28153),
(130120, 'deDE', 'Ihr werdet Euch für Eure Verbrechen gegen Kul Tiras verantworten.', '', 28153),
(130119, 'deDE', 'Keine Sorge. Wir bringen Euch schon zu ihr.', '', 28153),
(130099, 'deDE', '<Kurzer Unterhaltungsmoment, in dem ich über Zul lache und ihn erniedrige. Ich sage meiner Tochter, dass sie ihren Posten verlassen hat>', '', 28153),
(130096, 'deDE', 'Ihr solltet wiss\'n, dass unser König einhundertdreiundzwanzig Mordversuche überlebt hat.$b$bDie Köpfe jener, die es versucht\'n, dekorier\'n jetzt den Thronsaal.', '', 28153),
(130081, 'deDE', '', 'Ihr wollt den König seh\'n? Schön, schlagt den Gong und wir kümmern uns um \'ne angemessene Herausforderung für Euch.', 28153),
(130079, 'deDE', '', 'Nehmt Euern Segen und geht. Wenn Ihr zurückkehrt, is\' Euer Leben verwirkt.', 28153),
(130075, 'deDE', '', 'Wie geht\'s dem alten Vol\'jin so? Tot, wie ich hör. Ah, echt \'ne Schande. Gibt einige von uns, die ihn selbst töten wollt\'n.', 28153),
(130032, 'deDE', 'Spuckt\'s aus und schert Euch fort, $R. Die Amani hab\'n nich\' vergess\'n, dass Eure Horde unseren geliebt\'n Zul\'jin verstümmelt und ermordet hat.\n\nAus Respekt vor den Zandalari geb ich Euch \'ne Warnung. Ihr seid in dieser Botschaft auf\'m Boden der Amani. Bleibt hier und wir werd\'n Euch hier begrab\'n.', '', 28153),
(130031, 'deDE', 'Nehmt Euren Segen un\' schert Euch weg. Die Amani woll\'n nichts mit der Horde zu tun hab\'n.', '', 28153),
(130030, 'deDE', 'Mutig, Mann. Ich glaub nich\', dass Ihr wisst, worauf Ihr Euch eingelass\'n habt. Besiegt jed\'n der Jünger hinter mir, dann werdet Ihr unsern Segen erhalt\'n.', '', 28153),
(130003, 'deDE', '', '.', 28153),
(129998, 'deDE', '', 'Ich bin Jaina Prachtmeer. Ich ersuche eine Audienz bei Lordadmiralin Katherine Prachtmeer... meiner Mutter.', 28153),
(129993, 'deDE', '', 'Ich hoffe, das funktioniert.', 28153),
(129983, 'deDE', 'Ach! Nein! Gahz\'ragon! Herzloser Hordenabschaum! Hier, nehmt Euern Segen un\' schert Euch weg.', '', 28153),
(129980, 'deDE', 'In Eurer Abwesenheit hat sich einiges verändert, Hoheit. Rakera is\' zu schwach für ihren Posten gewes\'n, also hab ich sie nach Vol\'dun ins Exil geschickt.', '', 28153),
(129979, 'deDE', '', 'Jakra\'zet. Wo is\' Kriegswache Rakera?', 28153),
(129978, 'deDE', 'Das ist weit genug, Hordegesindel.', '', 28153),
(129969, 'deDE', '[Ladebildschirm -> - Schiff auf offenem Wasser, Jainas Alptraum, Ankunft am Tor von Boralus.]', '[Ladebildschirm -> - Schiff auf offenem Wasser, Jainas Alptraum, Ankunft am Tor von Boralus.]', 28153),
(129968, 'deDE', 'Ihr wollt\'s mit unserer Herausforderung aufnehm\'n? Dann verdient\'s Euch. Schlagt auf den Gong da drüben, dann gibt\'s mehr von unsrer Herausforderung, als Euch lieb is\'.', '', 28153),
(129967, 'deDE', '<Sprecht die Herausforderung aus.>', '<Sprecht die Herausforderung aus.>', 28153),
(129966, 'deDE', 'Sieh an, $R. Euer Volk hat mir und meinem Volk viel Schmerz beschert. Was wollt Ihr?', '', 28153),
(129965, 'deDE', 'Die Allianz wird sowas nich\' dulden!', 'Die Allianz wird sowas nich\' dulden!', 28153),
(129964, 'deDE', 'Unser König wird davon hör\'n!', 'Unser König wird davon hör\'n!', 28153),
(129963, 'deDE', 'Diese Runde geht an Euch.', 'Diese Runde geht an Euch.', 28153),
(129962, 'deDE', 'Ihr werdet hier nich\' die Oberhand behalt\'n.', 'Ihr werdet hier nich\' die Oberhand behalt\'n.', 28153),
(129961, 'deDE', 'Wir werd\'n zurückkommen!', 'Wir werd\'n zurückkommen!', 28153),
(129960, 'deDE', 'Das wird \'n Nachspiel haben, $p!', 'Das wird \'n Nachspiel haben, $p!', 28153),
(129959, 'deDE', '$gDreckiger:Dreckige:c; $C!', '$gDreckiger:Dreckige:c; $C!', 28153),
(129958, 'deDE', 'Sterbt!', 'Sterbt!', 28153),
(129957, 'deDE', 'Ich hab schon von Euch gehört, $p! Wenn ich Euch töte, bin ich \'n Held.', 'Ich hab schon von Euch gehört, $p! Wenn ich Euch töte, bin ich \'ne Heldin.', 28153),
(129956, 'deDE', 'Solang Ihr noch atmet, geh ich hier nich\' weg.', 'Solang Ihr noch atmet, geh ich hier nich\' weg.', 28153),
(129955, 'deDE', 'Die Zandalari könn\' sich nich\' mit Euch verbünd\'n, wenn Ihr tot seid.', 'Die Zandalari könn\' sich nich\' mit Euch verbünd\'n, wenn Ihr tot seid.', 28153),
(129954, 'deDE', 'Mich werdet Ihr so schnell nich\' los!', 'Mich werdet Ihr so schnell nich\' los!', 28153),
(129953, 'deDE', 'Hordenabschaum!', 'Hordenabschaum!', 28153),
(129952, 'deDE', 'Der Hordenabschaum wird sich nich\' mit den Zandalari zusamm\'ntun.', 'Der Hordenabschaum wird sich nich\' mit den Zandalari zusamm\'ntun.', 28153),
(129951, 'deDE', 'Auf Befehl der Prinzessin seid Ihr verbannt. Geht oder sterbt.', 'Auf Befehl der Prinzessin seid Ihr verbannt. Geht oder sterbt.', 28153),
(129950, 'deDE', 'Nich\' anfassen, Hordendreck.', 'Nich\' anfassen, Hordendreck.', 28153),
(129949, 'deDE', 'Ach was, \'n Mitglied der Horde hier in Zuldazar. Is\' ja interessant.', 'Ach was, \'n Mitglied der Horde hier in Zuldazar. Is\' ja interessant.', 28153),
(129948, 'deDE', 'Wollt Ihr das Ding auch? Ich hab\'s nämlich zuerst geseh\'n un\' ich kauf das, also weg mit Euch!', 'Wollt Ihr das Ding auch? Ich hab\'s nämlich zuerst geseh\'n un\' ich kauf das, also weg mit Euch!', 28153),
(129947, 'deDE', 'Was wollt Ihr? Bin beschäftigt.', 'Was wollt Ihr? Bin beschäftigt.', 28153),
(129946, 'deDE', 'Was is\', Hordendreck?', 'Was is\', Hordendreck?', 28153),
(129944, 'deDE', '', 'Ich muss mein Schiff klarmachen. Champion, wir treffen uns am Hafen, wenn Ihr bereit zum Aufbruch seid.', 28153),
(129940, 'deDE', 'Hört zu, Fremdling, ich hab eine Regel: Wer kämpf\'n will, der geht nach drauß\'n.\n\nWenn Ihr Euch dran haltet, könnt Ihr hier schlaf\'n.\n\nOh, und wenn Euch irgendwas komisch vorkommt, dann lasst mich ausm Spiel, klar?', '', 28153),
(129883, 'deDE', 'Kein Fremdling betritt die Stadt, bevor ich nicht von seinem Fleisch gekostet habe!', '', 28153),
(129881, 'deDE', 'Geht, sterbliches Wesen. Sagt der Tochter von Rastakhan, dass Ihr meine Erlaubnis habt, die Stadt zu betreten.', '', 28153),
(129880, 'deDE', 'Ich möchte die Stadt betreten.', 'Ich möchte die Stadt betreten.', 28153),
(129879, 'deDE', 'Ihr riecht nach etwas Neuem und Kriegsgeprüftem. Eine verlockende Beute. Warum steht Ihr vor mir?', '', 28153),
(129660, 'deDE', 'Champion! Es wurde ein dringender Kriegsrat einberufen. Eure Anwesenheit in Burg Sturmwind ist erwünscht.', '', 28153),
(128197, 'deDE', 'Ich kehre zurück aus den Tiefen!', '', 28153),
(128196, 'deDE', 'Da wären wir. Wir fahren schon mal den Detektor hoch und Ihr seht Euch auf der Insel um.', '', 28153),
(128195, 'deDE', 'Hier gehen wir an Land, Peons! Moment, ich rieche den Gestank von MENSCHEN. Hört ihr mich, Menschen?! Diese Insel gehört Burgthok!', '', 28153),
(127581, 'deDE', 'Woah, da stimmt was nicht mit dem Wetter. Das ganze Azerit muss einen Elementarlord angelockt haben. Seid auf der Hut. Oder tötet ihn! Oder beides!', '', 28153),
(127580, 'deDE', '', 'Arbeiter zum Abbau des Azeritflözes sind jetzt unterwegs.', 28153),
(127579, 'deDE', '$n, unsere Späher haben mehrere Inseln mit reichen Azeritvorkommen entdeckt. Wir brauchen sofort Euer Schiff.', '', 28153),
(127578, 'deDE', 'Allianz! Das Licht hat uns diese Insel geschenkt. Verschwindet, bevor Blut fließt. Das ist Eure letzte Warnung.', '', 28153),
(127577, 'deDE', '', 'Hier wartet Beute! Dorp, schießt auf alles, was sich bewegt. Peter, macht kurzen Prozess mit dem Allianzabschaum. Und holt mir das Azerit!', 28153),
(127576, 'deDE', 'Hey, ich hab hier echt gutes Zeug.', '', 28153),
(127575, 'deDE', '', 'Eure Verbündeten der Lichtgeschmiedeten sind hier, um zu helfen!', 28153),
(127574, 'deDE', 'Da sind ein paar... Hordenschiffe. Ihr solltet vielleicht mal einen Zahn zulegen.', '', 28153),
(127573, 'deDE', 'Ja? Wir haben unsere Befehle und das Azerit wartet. Schaut einfach auf die Tafel und sagt mir, wann Ihr aufbrechen könnt.\n\nIch weiß ja, dass ich anderer Leute Blicke auf mich ziehe, und das nicht selten... aber wir müssen uns hier konzentrieren.', '', 28153),
(127569, 'deDE', 'Startet die aktuelle Insel neu.', 'Startet die aktuelle Insel neu.', 28153),
(127568, 'deDE', 'Die Hälfte ist geschafft. Lasst mich jetz\' nicht hängen, Leute!', '', 28153),
(127501, 'deDE', 'Ihr! Helft Schmuddelbart! Ich geben viel Glitzerzeug!', '', 28153),
(126508, 'deDE', '|cFF0EA6DC+$1i|r |cFFFFFF00Azerit|r', '|cFF0EA6DC+$1i|r |cFFFFFF00Azerit|r', 28153),
(124726, 'deDE', 'Die Regeln entziffern', 'Die Regeln entziffern', 28153),
(124724, 'deDE', 'Das Spiel zurücksetzen', 'Das Spiel zurücksetzen', 28153),
(124723, 'deDE', 'Das Spiel beginnen', 'Das Spiel beginnen', 28153),
(124717, 'deDE', '------------------------------$bHÖCHSTE SCHWIERIGKEIT$b------------------------------$b\nDie Konsole summt und pfeift, als Ihr eure Hand darauflegt. Auf der mittleren Anzeige leuchten endlose Symbole auf, wobei die meisten von Schädeln oder Gesichtern mit \"X\" statt Augen begleitet werden. Ihr könnt in dieser Stufe Bonuszeit erhalten, doch eine der Bonuszeitanzeigen ist eine Falle.$b$bDie Konsole spielt fröhliche Musik ab. Wünscht sie Euch Glück bei der schwierigsten Herausforderung? Oder verabschiedet sie sich?', '', 28153),
(124716, 'deDE', '---------------$b   STUFE 4$b---------------$b\nDie Konsole reagiert auf Eure vertraute Berührung, lässt Sechseckmuster aufleuchten und spielt fröhliche Musik ab.$b$bDie uralten Symbole auf der mittleren Anzeige sind nur schwer zu entziffern, doch Ihr entnehmt ihnen, dass die nächste Schwierigkeitsstufe die meisten Spieler gnadenlos tötet.$b$bImmerhin könnt Ihr nun aus einem der Sechsecke Bonuszeit gewinnen.', '', 28153),
(124715, 'deDE', '---------------$b   STUFE 3$b---------------$b\nDie Konsole begrüßt Euch freundlich, obwohl sie mehrfach versucht hat, Euch zu töten.$b$bDie Symbole zur nächsten Stufe der Herausforderung deuten darauf hin, dass Ihr weniger Hinweise, weniger Zeit und mehr Minen zu erwarten habt.', '', 28153),
(124714, 'deDE', '---------------$b   STUFE 2$b---------------$b\nDie Konsole piept und tönt und erkennt Euch an Eurer Berührung. Die Regeln haben sich offenbar geändert. Die Bildsymbole zeigen an, dass jetzt eine Zeitbeschränkung gilt.$b$bDie Strafe dafür, das Rätsel nicht innerhalb der Zeit zu lösen, scheinen Schmerzen zu sein und nicht der Tod. Das ist immerhin nett.', '', 28153),
(124713, 'deDE', 'Ihr bemüht Euch, die Symbole zu interpretieren und die ständigen Warnungen vor dem sofortigen Tod zu ignorieren.$b$bDie WizSweeper-Konsole wird ein Raster aus Sechsecken erzeugen, die Euer Betreten wahrnehmen. Einige sind mit einer \"Mine\" versehen und werden den Spieler vernichten. Wenn Ihr hingegen auf ein \"sicheres\" Feld tretet, wird angezeigt, wie viele der benachbarten Felder vermint sind.$b$bDas Ziel liegt darin, das Spielfeld \"aufzudecken\", indem Ihr alle sicheren Felder aufdeckt und alle gefährlichen mit den kleinen weißen Flaggen markiert.$b$bEuch erschließt sich nicht, warum das Spiel es für nötig hält, seine Spieler bei Betreten eines falschen Feldes umzubringen.', '', 28153),
(124711, 'deDE', '---------------$b   STUFE 1$b---------------$b\nDiese geheimnisvolle, arkane Konsole leuchtet, als Ihr sie berührt. Auf dem mittleren Feld wird eine seitenlange Anleitung angezeigt. Die Sprache ist nicht verständlich, aber die Symbole sind unmissverständlich:$bHaufenweise Schädel.$b$bDies ist WizSweeper, ein höchst gefährliches Spiel, bei dem man sich durch ein Arkanminenfeld bewegen und die gefährlichen Bereiche identifizieren muss. Der kleinste Fehltritt wird mit dem sofortigen Tod bestraft.$b$bIhr fragt Euch, warum man das zum Spaß tun sollte.', '', 28153),
(124677, 'deDE', 'STUFE 5', '', 28153),
(124676, 'deDE', 'STUFE 4', '', 28153),
(124675, 'deDE', 'STUFE 3', '', 28153),
(124674, 'deDE', 'STUFE 2', '', 28153),
(124673, 'deDE', 'STUFE 1', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(167308, 'esES', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'esES', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'esES', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
