(167297, 'esES', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'esES', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'esES', 'Ciudad Forjatiniebla', 'Ciudad Forjatiniebla', 28153),
(162170, 'esES', 'No puedes dejar de lado tu deber, ¡regresa a Darnassus!', 'No puedes dejar de lado tu deber, ¡regresa a Darnassus!', 28153),
(162169, 'esES', '', '¿Acabamos con esto de una vez por todas, $n?', 28153),
(162168, 'esES', '<Vuela a Dalaran>.', '<Vuela a Dalaran>.', 28153),
(162167, 'esES', '¿Puedes guiar a Loh hasta todas las tiendas y después hasta la posada, sin pasar dos veces por el mismo punto?', '', 28153),
(162166, 'esES', '', '¿Podrás defender a las tortuguitas hasta que lleguen al mar?', 28153),
(162165, 'esES', 'Cuando quieras.', 'Cuando quieras.', 28153),
(162164, 'esES', 'Te doy la bienvenida, $n. ¿Crees que tienes la astucia necesaria para jugar a mi juego de emparejar?', '', 28153),
(162161, 'esES', '¿Seguro que quieres saltarte la presentación de Costa Oscura?', '¿Seguro que quieres saltarte la presentación de Costa Oscura?', 28153),
(162160, 'esES', '¿Sí, $n? Parece que te preocupa algo...', '', 28153),
(162159, 'esES', '<El marinero perdido te juzga con la mirada. No deberías estar aquí>.', '<El marinero perdido te juzga con la mirada. No deberías estar aquí>.', 28153),
(162158, 'esES', 'Ya he oído esta historia... <Saltarse las misiones preliminares e iniciar el viaje por Costa Oscura>. ', 'Ya he oído esta historia... <Saltarse la gesta e iniciar la siguiente misión>.', 28153),
(162157, 'esES', 'Te pondré a salvo, $n. ¡Agárrate!', '', 28153),
(162156, 'esES', '¡La ira de la naturaleza te aplastará!', '', 28153),
(162155, 'esES', 'Agárrate a mis ramas, $c.', '', 28153),
(162152, 'esES', '¡Nos aseguraremos de que esta azerita no caiga en manos de la Alianza!', '¡Nos aseguraremos de que esta azerita no caiga en manos de la Alianza!', 28153),
(162151, 'esES', '|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t¡|cFFF00000|Hspell:260551|h[Espinas de alma]|h|r ha atrapado a $n!', '', 28153),
(162150, 'esES', 'Me gustaría ayudar al almirantazgo con su campaña en Kul Tiras. <Establecer reputación Amistoso con el Almirantazgo de la Casa Valiente>.', 'Me gustaría ayudar al almirantazgo con su campaña en Kul Tiras. <Establecer reputación Amistoso con el Almirantazgo de la Casa Valiente>.', 28153),
(162149, 'esES', '¡Eres lo más, $n!', '¡Eres lo más, $n!', 28153),
(162148, 'esES', '$n está a tope ahora mismo.', '$n está a tope ahora mismo.', 28153),
(162147, 'esES', '¡Dalo todo!', '¡Dalo todo!', 28153),
(162146, 'esES', '¡Yuju!', '¡Yuju!', 28153),
(162145, 'esES', '¡$n! ¡$n! ¡$n!', '¡$n! ¡$n! ¡$n!', 28153),
(162144, 'esES', '¡Es $n! ¡$n está en el escenario!', '¡Es $n! ¡$n está en el escenario!', 28153),
(162143, 'esES', '¡Bien, $n! ¡Guau!', '¡Bien, $n! ¡Guau!', 28153),
(162142, 'esES', '¡Vamos, $n!', '¡Vamos, $n!', 28153),
(162141, 'esES', 'Mi forja siempre está lista, $n.', 'Mi forja siempre está lista, $n.', 28153),
(162140, 'esES', 'Prepararé la comida y las camas que tenemos disponibles. ¡Lok\'tar ogar!', 'Somos una avanzada modesta, pero reuniré todo lo que tenemos. La Jefa de Guerra y su ejército tendrán lo que necesiten. ¡Lo juro! ¡Lok\'tar ogar!', 28153),
(162139, 'esES', '¡Zoram\'gar estará a la altura! ¡Por la Horda!', '¡Zoram\'gar estará a la altura! ¡Por la Horda!', 28153),
(162138, 'esES', 'La jefa de guerra Sylvanas Brisaveloz requiere tu ayuda para reparar las armas de sus soldados.', 'La jefa de guerra Sylvanas Brisaveloz requiere tu ayuda para reparar las armas de sus soldados.', 28153),
(162137, 'esES', '', 'Por aquí cerca hay un camino oculto que podemos usar para volver al recibidor de la mansión.', 28153),
(162135, 'esES', '¡Vuelve a la Vega Crepuscular!', '', 28153),
(162134, 'esES', '', '¡Prended la llama! ¡Dadnos una lección, enanos Hierro Negro!', 28153),
(162133, 'esES', '', '¡El ambiente se caldea! ¡Un aplauso para los enanos Hierro Negro!', 28153),
(162132, 'esES', '', 'Sus pasos de baile no son de este mundo. ¡Un aplauso para los Mag\'har!', 28153),
(162131, 'esES', '', '¡Que salgan los Mag\'har al escenario!', 28153),
(162130, 'esES', 'Muéstrame nuestras opciones de investigación.', 'Muéstrame nuestras opciones de investigación.', 28153),
(162129, 'esES', '¡Vuelve al Río Culebra!', '', 28153),
(162128, 'esES', '¡Vuelve a La Espada del Maestro!', '', 28153),
(162127, 'esES', '', 'Si quieres un trabajo bien hecho... ¡usa explosivos más grandes!', 28153),
(162123, 'esES', '¡$n prepara un festín generoso de capitán!', '¡$n prepara un festín generoso de capitán!', 28153),
(162122, 'esES', '¡$n prepara un banquete de galera!', '¡$n prepara un banquete de galera!', 28153),
(162121, 'esES', '¿Seguro que quieres saltarte la Batalla por Lordaeron?', '¿Seguro que quieres saltarte la Batalla por Lordaeron?', 28153),
(162120, 'esES', 'Ya he oído esta historia... <Saltarse la gesta e iniciar la siguiente misión>.', 'Ya he oído esta historia... <Saltarse la gesta e iniciar la siguiente misión>.', 28153),
(162119, 'esES', '', '¡Hermanas, venid conmigo! ¡Debemos proteger nuestras tierras de la Horda!', 28153),
(162118, 'esES', '', '¡Están atacando Costa Oscura! ¡Avisad a la Suma Sacerdotisa de inmediato!', 28153),
(162117, 'esES', '¡Reunid a nuestros aliados del bosque! ¡Debemos salvar el Árbol del Mundo!', '', 28153),
(162116, 'esES', '¡Están atacando Costa Oscura! ¡Debemos actuar con rapidez para proteger nuestro bosque!', '', 28153),
(162110, 'esES', 'Debemos ocuparnos del general Grebo.', 'Debemos ocuparnos del general Grebo.', 28153),
(162109, 'esES', 'Saludos.', '', 28153),
(162108, 'esES', '¡La Horda se ha detenido en el Río Culebra! ¡Debemos hacerlos retroceder de inmediato!', '¡La Horda se ha detenido en el Río Culebra! ¡Debemos hacerlos retroceder de inmediato!', 28153),
(162107, 'esES', 'Oigo el eco de los tambores de guerra en el bosque. ¡Los druidas de la Zarpa están listos para proteger esta tierra de quienes quieren destruirla!', '', 28153),
(162106, 'esES', '¡Menudo poder!', '', 28153),
(162105, 'esES', 'Sí, esto es perfecto. Justo lo que necesitaba. Debería llevarme solo un momento.', '', 28153),
(162104, 'esES', 'Lo siento. ¡El fragmento vibra con poder! Es... bello y a la vez aterrador.', '', 28153),
(162103, 'esES', '', 'Ya era hora de que los enanos Hierro Negro saliéramos de las montañas y reclamásemos nuestro lugar en la Alianza.', 28153),
(162102, 'esES', '¿Crees que me permitirían conducir mi tanque por las calles de Ventormenta?', '', 28153),
(162101, 'esES', '¡Será mejor que los demás miembros de la Alianza se acostumbren a su nuevo y fogoso aliado!', '', 28153),
(162100, 'esES', 'No me gustan las miradas que me echan el resto de enanos de Ventormenta.', 'No me gustan las miradas que me echan el resto de enanos de Ventormenta.', 28153),
(162099, 'esES', 'No me gusta que haya tanta luz en la superficie.', 'No me gusta que haya tanta luz en la superficie.', 28153),
(162098, 'esES', 'Una casa no es un hogar si no está bendecida con una fina capa de hollín.', 'Una casa no es un hogar si no está bendecida con una fina capa de hollín.', 28153),
(162097, 'esES', '¡Los fuegos de Roca Negra arden por la Alianza!', '¡Los fuegos de Roca Negra arden por la Alianza!', 28153),
(162096, 'esES', 'Casi todo se puede arreglar con una llave inglesa y un brazo enérgico.', 'Casi todo se puede arreglar con una llave inglesa y un brazo enérgico.', 28153),
(162095, 'esES', 'Los Hierro Negro somos los únicos enanos auténticos. ¡Los otros clanes son demasiado blandos!', 'Los Hierro Negro somos los únicos enanos auténticos. ¡Los otros clanes son demasiado blandos!', 28153),
(162094, 'esES', 'Somos el verdadero poder de la montaña.', 'Somos el verdadero poder de la montaña.', 28153),
(162093, 'esES', '¿Por qué te acercas a mí? ¡Cuidado, tengo poca paciencia!', '¿Por qué te acercas a mí? ¡Cuidado, tengo poca paciencia!', 28153),
(162089, 'esES', '¡Abandona este lugar!', '', 28153),
(162088, 'esES', '¡Fuera! ¡No eres $gbienvenido:bienvenida; en nuestro cubil!', '', 28153),
(162087, 'esES', '¡No nos arrebatarás nuestro hogar!', '', 28153),
(162086, 'esES', '¡Basta! ¡Piedad! Tú ganas...', '', 28153),
(162085, 'esES', 'Vale... Reuniré a mi gente y abandonaremos el lugar.', '', 28153),
(162084, 'esES', '¡Basta! ¡Por favor! Me rindo...', '', 28153),
(162082, 'esES', '', 'La Alianza acoge a los draenei y a los forjados por la Luz.\n\nEso es motivo suficiente para reducir sus ciudades a cenizas.', 28153),
(162081, 'esES', '', '¿En este mundo hay draenei?\n\n<Geya\'rah frunce el ceño>.\n\nNo por mucho tiempo.', 28153),
(162080, 'esES', '', '¡Nuestras armas juran lealtad a la Horda!', 28153),
(162079, 'esES', '', 'Los Mag\'har encontrarán un nuevo hogar aquí, en Azeroth.', 28153),
(162078, 'esES', '', 'Puede que hayamos perdido Draenor, pero mi corazón me dice que volveremos a ver su cielo.\n\n¡Ancestros, concededme este deseo!', 28153),
(162077, 'esES', '¿Azotar? Eso es una práctica de antaño, más propia de bárbaros. Por supuesto, yo no tendría ni idea de qué hacer en un ritual así.\n\n<El orco se inclina y susurra>.\n\nSé exactamente qué hacer. ¿Has venido a pedir una demostración?', '¿Azotar? Eso es una práctica de antaño, más propia de bárbaros. Por supuesto, yo no tendría ni idea de qué hacer en un ritual así.\n\n<La orco se inclina y susurra>.\n\nSé exactamente qué hacer. ¿Has venido a pedir una demostración?', 28153),
(162076, 'esES', 'A veces, miro a los draenei y me pregunto si tienen huesos en esos tentáculos carnosos de la cara. Porque, si los tuviesen, coleccionaría cientos y los usaría para hacer guirnaldas decorativas que colgaría de las paredes de nuestra fortaleza para que los visitantes las admirasen y dijesen: \"Eh, mira esos huesos de tentáculos faciales. Seguro que los ha traído un orco muy sabio y con mucho talento\". Y yo respondería: \"Sí, eso es lo que siempre me decía mi madre\".\n\nPerdona, ¿querías preguntarme algo?', 'A veces, miro a los draenei y me pregunto si tienen huesos en esos tentáculos carnosos de la cara. Porque, si los tuviesen, coleccionaría cientos y los usaría para hacer guirnaldas decorativas que colgaría de las paredes de nuestra fortaleza para que los visitantes las admirasen y dijesen: \"Eh, mira esos huesos de tentáculos faciales. Seguro que los ha traído un orco muy sabio y con mucho talento\". Y yo respondería: \"Sí, eso es lo que siempre me decía mi madre\".\n\nPerdona, ¿querías preguntarme algo?', 28153),
(162075, 'esES', '¿Es hora de comer? ¡Espero que lo sea!\n\nCambiando de tema... Si tuvieras que elegir una extremidad de la que podrías prescindir para vivir, ¿cuál sería?', '¿Es hora de comer? ¡Espero que lo sea!\n\nCambiando de tema... Si tuvieras que elegir una extremidad de la que podrías prescindir para vivir, ¿cuál sería?', 28153),
(162074, 'esES', '', '<Lasha te mira fijamente a la cabeza>.\n\n¿Cómo es tu calavera? ¿Encaja?\n\n¿Tienes la mente libre... vacía... o dividida?', 28153),
(162073, 'esES', '', 'Echo de menos a los botani.\n\nCuando los tostabas lo justo, estaban DELICIOSOS.\n\n<Lasha se limpia un chorrito de baba de los labios>.', 28153),
(162072, 'esES', '', '¿Ha llegado la hora de prender fuego a los vinculados a la Luz?', 28153),
(162071, 'esES', 'Te doy la bienvenida a mi posada, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?', 'Te doy la bienvenida a mi posada, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?', 28153),
(162070, 'esES', 'Fija tu hogar en esta taberna.', 'Fija tu hogar en esta taberna.', 28153),
(162069, 'esES', '¡Quienes desafíen al jefe de guerra Grito Infernal pagarán con sus vidas!', '¡Quienes desafíen al jefe de guerra Grito Infernal pagarán con sus vidas!', 28153),
(162068, 'esES', 'Estás en NUESTRO mundo, $gforastero:forastera;.\n\nSi osas traer corrupción aquí, dirás adiós a la vida.', 'Estás en NUESTRO mundo, $gforastero:forastera;.\n\nSi osas traer corrupción aquí, dirás adiós a la vida.', 28153),
(162067, 'esES', '¡Si atrapas a alguno de esos traidores vinculados a la Luz, les rebanaré la garganta!', '¡Si atrapas a alguno de esos traidores vinculados a la Luz, les rebanaré la garganta!', 28153),
(162066, 'esES', 'Hemos superado a los primigenios. Podemos acabar con cualquier enemigo.', 'Hemos superado a los primigenios. Podemos acabar con cualquier enemigo.', 28153),
(162065, 'esES', '¡Draenor será libre!', '¡Draenor será libre!', 28153),
(162064, 'esES', 'Si te ganas la confianza de la señora suprema, te ganarás la mía.', 'Si te ganas la confianza de la señora suprema, te ganarás la mía.', 28153),
(162063, 'esES', 'La señora suprema Geya\'rah es la mano derecha del Jefe de Guerra. No hay orco más valiente en todo Draenor.\n\n¡Ni en tu mundo, $gforastero:forastera;!', 'La señora suprema Geya\'rah es la mano derecha del Jefe de Guerra. No hay orco más valiente en todo Draenor.\n\n¡Ni en tu mundo, $gforastero:forastera;!', 28153),
(162062, 'esES', '', 'Cuando era niña, los eruditos draenei me enseñaron a leer y a escribir. Me gustaban. Los respetaba.\n\nEntonces llegaron los naaru y se extendió el fanatismo.\n\nLos draenei renacieron... No, ellos usan otra palabra... Los reforjó su preciada Luz.\n\nSu fe los ciega y los somete a maestros que buscan controlar el universo, exactamente igual que la Legión.\n\nDraenei... eredar... siempre tan dispuestos a dejarse dominar. Siempre tan propensos a la corrupción.', 28153),
(162061, 'esES', '', 'Grommash Grito Infernal es un gran líder. Lo respeto tanto como respetaba a mi padre.\n\nPero como vuelva a ver al traidor de su hijo...\n\n<Geya\'rah escupe en el suelo>.\n\nAcabaré con él.', 28153),
(162060, 'esES', '', 'Draenor debe ser libre del control de fanáticos y tiranos.', 28153),
(162059, 'esES', 'Una vez, los héroes de tu mundo me liberaron de un demonio en la Ciudadela del Fuego Infernal. ¿Estabas con ellos?\n\n<Grommash te mira>.\n\nSi es así, estoy en deuda contigo. Puede que los espíritus me muestren una forma de pagártela.', '', 28153),
(162058, 'esES', 'Los Mag\'har no se inclinarán ante nadie. Ni siquiera ante aquellos a los que una vez llamamos amigos.', '', 28153),
(162057, 'esES', 'Has viajado una gran distancia, $c. Puede que nuestro mundo te parezca aún más salvaje que la última vez que lo vieron los tuyos.', '', 28153),
(162047, 'esES', '', '¿Qué recuerdos deseas que te muestre?', 28153),
(162046, 'esES', '¿Como puede ayudarte el viejo T\'omkuh?', '', 28153),
(162045, 'esES', 'Háblame de la batalla por Lordaeron.', 'Háblame de la batalla por Lordaeron.', 28153),
(162044, 'esES', 'Háblame del enfrentamiento en el salón del trono.', 'Háblame del enfrentamiento en el salón del trono.', 28153),
(162043, 'esES', 'Háblame de la traición de Valiente.', 'Háblame de la traición de Valiente.', 28153),
(162042, 'esES', 'Háblame de las pruebas de Jaina.', 'Háblame de las pruebas de Jaina.', 28153),
(162041, 'esES', 'Háblame de la pesadilla de Jaina.', 'Háblame de la pesadilla de Jaina.', 28153),
(162040, 'esES', 'Háblame del regreso de Jaina a Theramore.', 'Háblame del regreso de Jaina a Theramore.', 28153),
(162039, 'esES', 'Háblame de la batalla en la pirámide.', 'Háblame de la batalla en la pirámide.', 28153),
(162038, 'esES', 'Háblame de la decisión de Rastakhan.', 'Háblame de la decisión de Rastakhan.', 28153),
(162037, 'esES', 'Háblame del regreso de Talanji a Zuldazar.', 'Háblame del regreso de Talanji a Zuldazar.', 28153),
(162035, 'esES', 'Esta no es forma de morir.', 'Esta no es forma de morir.', 28153),
(162034, 'esES', 'Sentía que el frío me dominaba...', 'Sentía que el frío me dominaba...', 28153),
(162033, 'esES', 'Te doy las gracias.', 'Te doy las gracias.', 28153),
(162032, 'esES', 'Espero que esto no sea una trampa, aún necesitamos la ayuda de $n.', '', 28153),
(162031, 'esES', 'Estoy $glisto:lista; para ir a Fin del Destino.', 'Estoy $glisto:lista; para ir a Fin del Destino.', 28153),
(162030, 'esES', 'Estoy $glisto:lista; para ir a Fin del Destino.', 'Estoy $glisto:lista; para ir a Fin del Destino.', 28153),
(162029, 'esES', '¿Pero qué...? ¿Qué necesita Magni Barbabronce?', '', 28153),
(162025, 'esES', '¿No te has enterado? La Horda tiene el cuerpo de Derek Valiente en Puerto Saqueo. Lady Valiente ha enviado prácticamente a toda la flota a recuperarlo.', '¿No te has enterado? La Horda tiene el cuerpo de Derek Valiente en Puerto Saqueo. Lady Valiente ha enviado prácticamente a toda la flota a recuperarlo.', 28153),
(162024, 'esES', 'Esto está muy tranquilo. ¿Dónde está todo el mundo?', 'Esto está muy tranquilo. ¿Dónde está todo el mundo?', 28153),
(162023, 'esES', '', 'Parece que Stone se está recuperando bien.\n\nCon el tiempo, estoy segura de que demostrará ser una aliada leal.', 28153),
(162021, 'esES', '', 'Ha sido muy reconfortante ver cómo recibía su merecido oda esa gente.\n\n¿Esto es lo que se siente al ser libre? ¿Al establecer tus propias reglas?\n\nQuizás pueda acostumbrarme a esto.', 28153),
(162020, 'esES', '', 'Parece que Amalia lo está llevando relativamente bien.\n\nEl cambio es muy duro, pero ella es más fuerte de lo que lo era yo cuando pasé por lo mismo. Yo mataba a cualquiera que me hacía enfadar. Amalia, sin embargo, ha decidido aislarse.\n\nEntrará en razón con el tiempo. Confía en mí.', 28153),
(162019, 'esES', '¡Se están acercando! ¡Que sepan lo que es el dolor!', '', 28153),
(162018, 'esES', '¡Vamos! ¡No les deis respiro!', '', 28153),
(162017, 'esES', 'Flaquearás... Ya viene... Ya viene...', '', 28153),
(162016, 'esES', '', 'Déjame, no quiero hablar contigo.', 28153),
(162015, 'esES', 'El maestro está hambriento... el Corazón alimentará su sueño lúcido...', '', 28153),
(162014, 'esES', 'Loh Zandalari llevan adorando al viejo Bwonsamdi mucho tiempo, igual que loh Lanza Negra.\n\nMira ehte ídolo de Bwonsamdi que he comprado en el puerto. ¡Eh maravilloso! Mucho mejor que loh que hay en casa.\n\nLoh Lanza Negra y loh Zandalari somoh muy dihtintoh, eh cierto, pero noh unene máh cosah de lah que noh separan.\n\nSi loh Zandalari no fueran tan ehtiradoh, ¡creo que podríamoh ser colegah! ', '¿Cuándo cazaremos de nuevo, $p?\n\nEn todos los años que llevo en Azeroth, nunca han faltado monstruos que matar.', 28153),
(162013, 'esES', '', '¡No! Nuestro hogar...', 28153),
(162012, 'esES', '', '¡No te acercarás ni un paso más a nuestro hogar, $r! ¡Tor ilisar\'thera\'nal!', 28153),
(162011, 'esES', 'Demasiado tarde... Estúpidos...', '', 28153),
(162010, 'esES', 'Arrasaremos lo que quede de esta aldea, ¡y acabaremos con vosotros de una vez por todas!', '', 28153),
(162009, 'esES', 'He oído que los Zandalari veneran a un loa pterrordáctilo.\n\nUn dios reptil... ¡que vuela!\n\n<A Lasan parecen brillarle los ojos>.\n\nAviash está deseando vencer a sus mejores jinetes en una carrera. O mejor, ¡en una pelea!\n\nA nosotros nos da igual, ¡los ganaremos en ambos casos!\n\n¡Ja, ja, ja, ja, ja, ja!', '¿Cuándo cazaremos de nuevo, $p?\n\nEn todos los años que llevo en Azeroth, nunca han faltado monstruos que matar.', 28153),
(162008, 'esES', 'Cuéntame tu plan, Nathanos.', 'Cuéntame tu plan, Nathanos.', 28153),
(162007, 'esES', 'Muy bien. $n, informa a Velapastrosa de que estamos listos para partir.', '', 28153),
(162006, 'esES', 'Y la Horda va a robarlo.', '', 28153),
(162005, 'esES', 'El artefacto está guardado bajo llave en el corazón de Boralus, la capital de Kul Tiras.', '', 28153),
(162004, 'esES', 'Blandir el cetro abisal supone blandir el poder del mar y las tormentas.', '', 28153),
(162003, 'esES', 'El cetro abisal.', '', 28153),
(162002, 'esES', 'Mis antiguos hermanos, los Sabiomar de la casa Canto Tormenta, poseen un artefacto de gran poder.', '', 28153),
(162001, 'esES', 'Por supuesto, Clamañublo.', '', 28153),
(162000, 'esES', 'Zelling, ¿haces los honores?', '', 28153),
(161999, 'esES', '¡Mira el tamaño de esos dinosaurios!\n\n<Ji suspira con anhelo>.\n\nEstoy deseando darles un puñetazo...', '¿Cuándo cazaremos de nuevo, $p?\n\nEn todos los años que llevo en Azeroth, nunca han faltado monstruos que matar.', 28153),
(161998, 'esES', 'Costa Abrupta', 'Costa Abrupta', 28153),
(161997, 'esES', 'Cámara de Neltharion', 'Cámara de Neltharion', 28153),
(161996, 'esES', 'Meseta Elemental', 'Meseta Elemental', 28153),
(161995, 'esES', 'Mirador de la Fundición Roca Negra', 'Mirador de la Fundición Roca Negra', 28153),
(161994, 'esES', 'Cervecería del Trueno', 'Cervecería del Trueno', 28153),
(161993, 'esES', 'Barrilia', 'Barrilia', 28153),
(161992, 'esES', 'He luchado en muchas guerras. He visto desangrarse en el campo de batalla tanto a héroes como a cobardes.\n\nPero esta guerra es... diferente.\n\nPone a prueba algo más que el temple y la pericia. Pone a prueba nuestros corazones. La fe que depositamos los unos en los otros.\n\nPase lo que pase, la Horda prevalecerá.\n\nDebe hacerlo.', '¿Cuándo cazaremos de nuevo, $p?\n\nEn todos los años que llevo en Azeroth, nunca han faltado monstruos que matar.', 28153),
(161991, 'esES', 'Santuario de Dragones Rubí', 'Santuario de Dragones Rubí', 28153),
(161990, 'esES', 'Campos del Torneo Argenta', 'Campos del Torneo Argenta', 28153),
(161989, 'esES', 'Skald', 'Skald', 28153),
(161988, 'esES', 'Fosas Viles', 'Fosas Viles', 28153),
(161987, 'esES', 'Bastión del Honor', 'Bastión del Honor', 28153),
(161986, 'esES', 'La Gran División', 'La Gran División', 28153),
(161985, 'esES', 'Trono de la Llama', 'Trono de la Llama', 28153),
(161984, 'esES', 'Cresta Pluma de Fuego', 'Cresta Pluma de Fuego', 28153),
(161983, 'esES', 'El Masón', 'El Masón', 28153),
(161982, 'esES', 'Pico Nidal', 'Pico Nidal', 28153),
(161981, 'esES', 'Castillo de Nethergarde', 'Castillo de Nethergarde', 28153),
(161980, 'esES', 'Ventormenta', 'Ventormenta', 28153),
(161979, 'esES', 'Forjaz', 'Forjaz', 28153),
(161978, 'esES', 'Zandalar', 'Zandalar', 28153),
(161977, 'esES', 'Kul Tiras', 'Kul Tiras', 28153),
(161976, 'esES', 'Islas Abruptas', 'Islas Abruptas', 28153),
(161975, 'esES', 'Rasganorte', 'Rasganorte', 28153),
(161974, 'esES', 'Pandaria', 'Pandaria', 28153),
(161973, 'esES', 'Draenor', 'Draenor', 28153),
(161972, 'esES', 'Terrallende', 'Terrallende', 28153),
(161971, 'esES', 'Kalimdor', 'Kalimdor', 28153),
(161970, 'esES', 'Reinos del Este', 'Reinos del Este', 28153),
(161969, 'esES', 'Todo lo que merece la pena cabe en una caja.\n\n¡Excepto la gente, claro! No puedes meter a $p en una caja, ¿verdad?\n\n<Hobart se queda pensativo un instante>.\n\nEn cualquier caso, solo estoy ajustando un par de cosas. Tendré el traje preparado en nada. ¡Y con algunas mejoras explosivas!', '¿Cuándo cazaremos de nuevo, $p?\n\nEn todos los años que llevo en Azeroth, nunca han faltado monstruos que matar.', 28153),
(161968, 'esES', 'No moriré en esta colina, George.', '', 28153),
(161967, 'esES', 'Si luchas con Jeph, ¡prepárate para caer!', '', 28153),
(161966, 'esES', 'Se han llevado a tu hija a Fin del Destino.', 'Se han llevado a tu hija a Fin del Destino.', 28153),
(161965, 'esES', '¡Bien! ¡A ver si así aprende!', '', 28153),
(161964, 'esES', 'A un... ¿desierto? Qué pintoresco...', '', 28153),
(161963, 'esES', 'He venido, tal como solicitaste, Aterravermis.', '', 28153),
(161962, 'esES', 'Allá va...', '', 28153),
(161961, 'esES', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡Ve hasta el  |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r para volver a lanzarlo por los aires!', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡Ve hasta el  |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r para volver a lanzarlo por los aires!', 28153),
(161960, 'esES', '¡Fuego!', '¡Fuego!', 28153),
(161959, 'esES', '¡Vale! ¡Cuando quieras!', '', 28153),
(161958, 'esES', '¡Retén a esa cosa mientras yo preparo el cañón!', '', 28153),
(161957, 'esES', '|cFF0000FF(Misión)|r Estoy listo para ir a Draenor.', '|cFF0000FF(Misión)|r Estoy lista para ir a Draenor.', 28153),
(161956, 'esES', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t ¡%s te marca como objetivo de |cFFFF0000|Hspell:259720|h[Agitación]|h|r!', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t ¡%s te marca como objetivo de |cFFFF0000|Hspell:259720|h[Agitación]|h|r!', 28153),
(161955, 'esES', '¡Aquí está! ¡Tengo la última llave!', '¡Aquí está! ¡Tengo la última llave!', 28153),
(161954, 'esES', 'Estoy listo para buscar el eco de Garrosh.', 'Estoy lista para buscar el eco de Garrosh.', 28153),
(161953, 'esES', 'No te ayudaría con esto si no creyera que es importante.', '', 28153),
(161952, 'esES', '¡Deja de cotorrear! Tampoco hay que contárselo a todo el mundo.', 'Deberíamos habernos ido ayer.', 28153),
(161950, 'esES', '¡Así no es como esperaba que fuera el día!', '', 28153),
(161949, 'esES', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t ¡El repartetundas de pago lanza |cFFFF0000|Hspell:256214|h[Lanzador de bombalones]|h|r!', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t ¡El repartetundas de pago lanza |cFFFF0000|Hspell:256214|h[Lanzador de bombalones]|h|r!', 28153),
(161948, 'esES', 'El poder de tu fragmento crece, $p.', '', 28153),
(161947, 'esES', 'El hedor de los míos aún permanece. Ocúpate rápido de este.', '', 28153),
(161946, 'esES', 'Nuestra tarea ha terminado, $p. El telemántico jefe Oculeth espera tu llegada en Zuldazar.', '', 28153),
(161945, 'esES', '', 'Sí, mientras cumplas tu parte del trato, sabandija.', 28153),
(161944, 'esES', '¡De acuerdo, cincuenta me parece justo! Sin rencores, ¿verdad?', '', 28153),
(161943, 'esES', '', 'Que sea un cincuenta. A no ser que prefieras que me lleve un cincuenta por ciento de tus dientes.', 28153),
(161942, 'esES', 'Mira, ¿qué te parece si te doy una parte de los beneficios de la plata y tú bajas ese pico? ¿Qué tal suena un veinte por ciento?', '', 28153),
(161941, 'esES', '¿De verdad? Yo creo que lo recordaría...', '', 28153),
(161940, 'esES', '', '¡Porque te estábamos gritando mientras te ibas con nuestros únicos guardias!', 28153),
(161939, 'esES', '¡Calma, calma! ¿Cómo iba a saber yo que había supervivientes?', '', 28153),
(161938, 'esES', '', '¡Cobarde! ¡Nos abandonaste a nuestra suerte!', 28153),
(161937, 'esES', '¡Puntúa mi siguiente vuelta!', '¡Puntúa mi siguiente vuelta!', 28153),
(161936, 'esES', '¡Espero que estés $glisto:lista; para cabalgar!', '', 28153),
(161935, 'esES', '', 'Si no te importa, voy a ir a buscar a Cierrelúgubre para enseñarle la punta de mi pico...', 28153),
(161934, 'esES', '', 'Gracias de nuevo por tu ayuda, $gforastero:forastera;.', 28153),
(161933, 'esES', 'Misiones del mundo desbloqueadas', '', 28153),
(161932, 'esES', '¡Intentaron vendernos esas cosas como comida!', '¡Sella esos cajones, tenemos que arreglar este estropicio!', 28153),
(161931, 'esES', 'La batalla por Stromgarde desbloqueada', '', 28153),
(161930, 'esES', '¡Odio a esos niños!', '¡Deshazte de esas cosas!', 28153),
(161929, 'esES', '¡Esos niños horribles han traído esas cosas a la ciudad!', '¡Esta es otra de las malas ideas de esos chavales!', 28153),
(161928, 'esES', '|TInterface\\ICONS\\INV_Misc_Bell_Green:20|t ¡Raal el Glotón comienza a lanzar |cFFFF0404|Hspell:264931|h[Llamar a sirviente]|h|r!', '', 28153),
(161927, 'esES', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t ¡Lady Crestavía comienza a lanzar |cFFFF0404|Hspell:268306|h[Cadencia discordante]|h|r!', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t ¡Lady Crestavía comienza a lanzar |cFFFF0404|Hspell:268306|h[Cadencia discordante]|h|r!', 28153),
(161926, 'esES', '¡Lo has logrado! Azeroth se hace más fuerte... ¡y tú también, adalid!', '', 28153),
(161925, 'esES', '¡Un esbirro de los dioses antiguos! ¡El Corazón de Azeroth es lo bastante fuerte para expulsarlo! ¡Úsalo, $n!', '', 28153),
(161924, 'esES', 'Islas desbloqueadas', '', 28153),
(161923, 'esES', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Festín sangriento]|h|r para limpiar tus acumulaciones de |cFFFF0404|Hspell:263227|h[Sangre pútrida]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Festín sangriento]|h|r para limpiar tus acumulaciones de |cFFFF0404|Hspell:263227|h[Sangre pútrida]|h|r.', 28153),
(161922, 'esES', 'Vuela sobre la tormenta. Deja que los demás se mojen.', '', 28153),
(161921, 'esES', '', '¡Lo conseguimos! Volvamos a Ventormenta para informar al Rey.', 28153),
(161920, 'esES', '', 'Hemos decidido hacer unas cuantas mejoras mientras reparamos el Yunquenegro.', 28153),
(161919, 'esES', '', 'Seguiré dando caza al enemigo hasta haber ganado esta guerra, $n.\n\nEs mi juramento por todos aquellos que perdimos en Teldrassil.\n\n<Shandris inclina la cabeza para orar>.', 28153),
(161918, 'esES', '', 'Cabalga las corrientes. ¡Afronta la tormenta!', 28153),
(161917, 'esES', 'Vuelve a la Puerta de Sangre.', 'Vuelve a la Puerta de Sangre.', 28153),
(161916, 'esES', 'No puedo decir que en general me gusten los barcos, pero sí lo que guardáis aquí abajo.\n\nSi encuentras más reliquias antiguas a las que merezca la pena echar un vistazo, me encantaría hacerlo.\n\nAh, y puertas. Puertas misteriosas. ¡Las puertas titánicas misteriosas son mi especialidad!', '', 28153),
(161915, 'esES', '', 'Halford tiene notas muy interesantes por aquí. Informes de guerra, desplazamientos de tropas...\n\n<Kelsey mira a la puerta y se acerca para hablarte entre susurros>.\n\n¡Creo que hasta podría haber encontrado su diario personal!\n\n<Kelsey te guiña un ojo con complicidad>.', 28153),
(161914, 'esES', '', 'No querrás irte sin tus amigos, ¿verdad?', 28153),
(161913, 'esES', 'Sienta bien volver a luchar junto a soldados de la Alianza recios y honestos. Me recuerda a los tiempos de la Compañía Bravo.\n\n<Los ojos de Keeshan parecen observar algo en la distancia>.\n\n$n, ten siempre tu arma preparada. Y pon otra a buen recaudo por si te capturan en algún lugar. Llévala a un sitio donde no la vayan a buscar.', '', 28153),
(161912, 'esES', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t ¡Rixxa Flujollama está lanzando |cFFFF0000|Hspell:259940|h[Descarga motriz]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t ¡Rixxa Flujollama está lanzando |cFFFF0000|Hspell:259940|h[Descarga motriz]|h|r!', 28153),
(161911, 'esES', 'Mi pueblo ha estado entrenando para dominar nuestras habilidades.\n\n<Umbric frunce el ceño>.\n\nLos susurros hablan de muchas posibilidades diferentes. Estaremos listos para lo que se avecine.', '', 28153),
(161910, 'esES', 'Sí. Todo este asunto me provocaba dudas, pero parece que la cosa se ha resuelto para mejor.', '', 28153),
(161909, 'esES', '¡Es un buen día para ser Hierro Negro!', '', 28153),
(161908, 'esES', '', 'El último golpe es tuyo, $p.', 28153),
(161907, 'esES', '', '$n, qué bien sienta estar en guerra de nuevo. Pero debo admitir... que curar a los heridos se hace pesado. Mi talento se podría aprovechar mucho mejor.\n\nMuchas de las técnicas que los forjados por la Luz empleamos contra la Legión nos vendrían bien contra la Horda.\n\nInforma al Alto Comandante de que sería un placer encargarme de asegurar que los prisioneros que capturemos se... \"purifiquen\" correctamente.', 28153),
(161906, 'esES', '', 'No me sorprende que Jaina Valiente haya decidido regresar a casa.\n\nUna herida que no se trata nunca se cura, y su herida es muy grave.', 28153),
(161905, 'esES', '¡El guardián de corazón se dispone a atacarte!', '¡El guardián de corazón se dispone a atacarte!', 28153),
(161904, 'esES', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t¡Merektha está a punto de golpearte con |cFFFF0000|Hspell:263914|h[Arena cegadora]|h|r, mira a otro lado!', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t¡Merektha está a punto de golpearte con |cFFFF0000|Hspell:263914|h[Arena cegadora]|h|r, mira a otro lado!', 28153),
(161903, 'esES', '', 'Cuando tú digas, $n. Habla conmigo cuando quieras ir a las Profundidades de Roca Negra.', 28153),
(161902, 'esES', '', 'Sabes lo que tenemos que hacer, $n. Hora de pasar a la acción.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161901, 'esES', '|cFF0000FF(Misión)|r Estoy listo para ir a las Tierras de Fuego.', '|cFF0000FF(Misión)|r Estoy lista para ir a las Tierras de Fuego.', 28153),
(161900, 'esES', '', 'Vamos, $n. Debemos atacar.', 28153),
(161899, 'esES', 'No esperarán encontrarnos en Vol\'dun, pero no tardarán en preguntarse quién está matando a sus operativos.', '', 28153),
(161898, 'esES', 'Debemos darnos prisa, $n. La Horda aún no sabe que hemos llegado.', '', 28153),
(161897, 'esES', 'Colocará las bombas y volverá en un santiamén.', '', 28153),
(161896, 'esES', 'Aunque no lo parezca, sabe apañárselas en una pelea. Y su pericia para las demoliciones no tiene igual.', '', 28153),
(161895, 'esES', 'No hay por qué preocuparse, ya he trabajado con Guzbert antes. Es muy profesional.', '', 28153),
(161894, 'esES', 'Si la Luz lo quiere, pondremos fin a esto.', '', 28153),
(161893, 'esES', 'Lo que no les sirve, lo venden, y con eso financian la campaña de la Horda.', '', 28153),
(161892, 'esES', 'Pero sería un error. Esos sinvergüenzas siempre están desenterrando artefactos poderosos y utilizándolos contra sus enemigos.', '', 28153),
(161891, 'esES', 'Resulta tentador ignorar al Vigía del Sol y al Relicario. Al fin y al cabo, no son más que arqueólogos...', '', 28153),
(161890, 'esES', '|cFF0000FF(Misión)|r Estoy listo para ir a las Profundidades de Roca Negra.', '|cFF0000FF(Misión)|r Estoy lista para ir a las Profundidades de Roca Negra.', 28153),
(161889, 'esES', '', 'Ahora mismo es demasiado peligroso viajar por Arathi.$B$BSe podrá volver a acceder al portal cuando recuperemos el control de Stromgarde.', 28153),
(161888, 'esES', '¿Qué sabemos sobre los orcos Mag\'har?', '¿Qué sabemos sobre los orcos Mag\'har?', 28153),
(161887, 'esES', '¿Qué puedes decirme sobre los enanos Hierro Negro?', '¿Qué puedes decirme sobre los enanos Hierro Negro?', 28153),
(161886, 'esES', 'Cuando crezca, seré como Nisha. ¡Es la mejor del mundo!\n\n¡O como Kiro!, que es requetelisto...\n\n¡O como Meerah!, que es tan simpática...\n\n¡O como Jena!, que tiene montones de cosas...\n\nO...\n\n<Rudo sigue con una lista de nombres de otros vulperas del campamento>.', '', 28153),
(161885, 'esES', '', 'Ahora mismo es demasiado peligroso viajar por Arathi.$B$BSe podrá volver a acceder al portal cuando recuperemos el control de Ar\'gorok.', 28153),
(161884, 'esES', '', '¿Una bebida refrescante? Tengo las mejores.', 28153),
(161883, 'esES', '¡Mis productos traen suerte! ¡No se puede ganar sin ellos!', '', 28153),
(161882, 'esES', 'Eh, hola, tengo buen material por aquí.', 'Oh, ¡a todo el mundo le gustan mis inventos!', 28153),
(161881, 'esES', '¡Tengo armas y armaduras recién forjadas!', '', 28153),
(161880, 'esES', '', '¡Tengo suministros comerciales de Ventormenta!', 28153),
(161879, 'esES', 'Tengo instrumentos de oscuridad.', '', 28153),
(161878, 'esES', 'Tengo artefactos mágicos de lo más interesantes.', 'Tengo buen material. Pero nada de preguntas.', 28153),
(161877, 'esES', '¡Brebajes a la venta!', 'Tengo buen material. Pero nada de preguntas.', 28153),
(161876, 'esES', 'Los Mag\'har están contigo. ¡Sangre y truenos!', 'Tengo buen material. Pero nada de preguntas.', 28153),
(161875, 'esES', 'Eh, ¿alguien quiere explosivos? Los tengo justo aquí.', 'Tengo buen material. Pero nada de preguntas.', 28153),
(161874, 'esES', '¡Lok\'tar! Traigo suministros comerciales de Orgrimmar.', 'Tengo buen material. Pero nada de preguntas.', 28153),
(161873, 'esES', '¡Tengo objetos a la venta! Y traen buena suerte.', '¡Tengo objetos a la venta! Y traen buena suerte.', 28153),
(161872, 'esES', 'Se dice que Elisande dominaba conjuros que solo los dragones Bronce conocían. Tal vez estén dispuestos a ayudarte.', '', 28153),
(161871, 'esES', 'La magia temporal era la especialidad de nuestra antigua líder, la gran magistrix Elisande. Muchos de sus conocimientos murieron con ella.', '', 28153),
(161870, 'esES', 'Necesito infiltrarme en la Academia Valiente.', 'Necesito infiltrarme en la Academia Valiente.', 28153),
(161869, 'esES', 'Necesito infiltrarme en el Cuartel de los Valiente.', 'Necesito infiltrarme en el Cuartel de los Valiente.', 28153),
(161868, 'esES', '', '¡Por la Alianza!', 28153),
(161867, 'esES', 'Nosotros defenderemos el frente. Tú adelántate. ¡Por la Alianza!', '', 28153),
(161866, 'esES', 'Estamos entre la pared y un océano lleno de barcos enemigos que nos están rodeando.', '', 28153),
(161865, 'esES', 'Me temo que estoy de acuerdo con la gnoma, $p.', '', 28153),
(161864, 'esES', '', '¡Eh!', 28153),
(161863, 'esES', '%s vuelve corriendo hacia Fangorrana.', '%s vuelve corriendo hacia Fangorrana.', 28153),
(161862, 'esES', 'Este hablará. Al menos aún tiene lengua, a diferencia de esos malditos Renegados.', '', 28153),
(161861, 'esES', '', '¡Hay que ponerse en marcha, $p! ¡Ve a hablar con el capitán del barco para zarpar!', 28153),
(161860, 'esES', '', 'A veces me gustaría A MÍ ser una máquina...', 28153),
(161859, 'esES', '', 'Máquinas...', 28153),
(161858, 'esES', 'Ya tienes tus órdenes. ¡Retírate!', '', 28153),
(161857, 'esES', 'Investiga los campamentos e informa de lo que descubras.', '', 28153),
(161856, 'esES', '', '¡Oh! ¡Enanos Hierro Negro! ¡Me encantan los enanos Hierro Negro! ¡Tienen MÁQUINAS!', 28153),
(161855, 'esES', 'Te reunirás con el maestro del yunque Thurgaden en la costa suroriental de Zuldazar.', '', 28153),
(161854, 'esES', '', '¡Sí, señor!', 28153),
(161853, 'esES', '¡Kelsey!', '', 28153),
(161852, 'esES', 'Su tripulación se encontró con algún que otro problema en el mar, pero se las arreglaron para montar un campamento en la costa oriental.', '', 28153),
(161851, 'esES', 'Reúnete con el brigadier Thom, uno de nuestros oficiales de la Séptima Legión.', '', 28153),
(161850, 'esES', '¡$p!', '', 28153),
(161849, 'esES', '', 'Hay un buen montón de comida fresca dentro.', 28153),
(161848, 'esES', 'Tenemos tropas en posición, no en uno, sino en dos puntos de Zuldazar.', '', 28153),
(161847, 'esES', 'Escuchad todos, este es el plan.', '', 28153),
(161846, 'esES', 'Acabarás... en la prisión de los Valiente...', '', 28153),
(161845, 'esES', '', 'Escoria... de la Horda...', 28153),
(161844, 'esES', 'Recuperaremos el cuerpo de Derek, sea como sea.', '', 28153),
(161843, 'esES', '', 'Nunca conseguirás dominar el poder que otorgan nuestras enseñanzas...', 28153),
(161842, 'esES', 'La marea te engullirá...', '', 28153),
(161841, 'esES', 'Vete. Vuelve con Oculeth. Ahora que el fragmento está restaurado, te podrá enviar al lugar que buscas.', '', 28153),
(161840, 'esES', 'Si hubiera la más mínima duda..., no me arriesgaría a que el fragmento cayera en las manos equivocadas. Otra vez, no.', '', 28153),
(161839, 'esES', 'Siento que los hilos del destino se entrelazan a tu alrededor. Eres más que $gdigno:digna; de lo que está por venir.', '', 28153),
(161838, 'esES', 'Incluso como eco del pasado, Garrosh ha sido un enemigo formidable.', '', 28153),
(161837, 'esES', 'Lo que has visto aquí es una de sus peores versiones. Una lástima.', '', 28153),
(161836, 'esES', 'En muchas otras posibles líneas temporales, fue un gran héroe para su gente. Algunos lo consideraban el mejor Jefe de Guerra de la Horda.', '', 28153),
(161835, 'esES', 'Garrosh Grito Infernal... Una pena cómo acabaron las cosas.', '', 28153),
(161834, 'esES', '¿Creéih que oh tengo miedo?', '', 28153),
(161833, 'esES', 'Cuéntanoslo todo, Zandalari.', 'Cuéntanoslo todo, Zandalari.', 28153),
(161832, 'esES', '¿Queréih saber lo que me pasó?\n\nEhtaba en el buque insignia. Lo vi todo.\n\nDe acuerdo, oh lo contaré. Eh mejor que lo sepáih. Eh mejor que sintáih el miedo.', '', 28153),
(161831, 'esES', 'Ven, debemos viajar hasta el Templo del Tigre Blanco.', '', 28153),
(161830, 'esES', 'Nadie echará de menos a Gul\'dan. Ni en esta dimensión ni en ninguna otra.', '', 28153),
(161829, 'esES', 'Aunque este enemigo de Azeroth es tan solo un eco de lo que un día fue, morir a manos de este ente supondría una muerte real.', '', 28153),
(161828, 'esES', 'Fue aquí donde Gul\'dan viajó entre mundos con la ayuda de la visión en el tiempo.', '', 28153),
(161827, 'esES', 'Los ecos de la magia de este lugar resuenan en los portales del tiempo.', '', 28153),
(161826, 'esES', 'Incluso ahora, puedo... Espera, ¿qué es eso?', '', 28153),
(161825, 'esES', '¡En el interior de esta cámara, el Corazón de Azeroth que llevas puede hacerse aún más poderoso!', '', 28153),
(161824, 'esES', 'La Cámara del Corazón tiene mejor aspecto que la última vez que estuviste aquí, ¿eh?', '', 28153),
(161823, 'esES', 'Pero no podemos caer en la desesperación. ¡Sé que acabaremos con esta marea de oscuridad!', '', 28153),
(161822, 'esES', 'Me temo que aún nos queda mucho camino por andar, adalid. Parece que las cosas no hacen más que empeorar.', '', 28153),
(161821, 'esES', '¿Lo sientes? ¡El poder del Corazón despierta!', '', 28153),
(161820, 'esES', '¡Maldita sea! Escúchame bien... Llegará el día en que el Señor del Fuego reclamará lo que es suyo. Nos veremos las caras entonces... viejo amigo.', '', 28153),
(161819, 'esES', 'Ah, qué gustazo... El olor del fuego por la mañana... y al medio día y por la noche. Tenemos que adentrarnos en la antigua guarida del Señor del Fuego para cargar el Núcleo de Magma.', '', 28153),
(161818, 'esES', 'Enviaré a mis mejores exploradores en busca de Pedrasiniestra. ¡Tenemos que detener a ese bastardo antes de que le lave el cerebro a más seguidores!', '', 28153),
(161817, 'esES', '¿Seguro que quieres saltarte las misiones de presentación de Kul Tiras?', '¿Seguro que quieres saltarte las misiones de presentación de Kul Tiras?', 28153),
(161816, 'esES', 'Esta historia ya la he oído... <Saltarse las misiones de presentación de Kul Tiras y empezar la aventura en Boralus>.', 'Esta historia ya la he oído... <Saltarse las misiones de presentación de Kul Tiras y empezar la aventura en Boralus>.', 28153),
(161815, 'esES', 'Usa su poder con sabiduría, $n. Y cuidado... Hay quienes desean que fracases en tu tarea de salvar el mundo.', '', 28153),
(161814, 'esES', 'Y a medida que se recupera, también se fortalece el Corazón de Azeroth que llevas al cuello.', '', 28153),
(161813, 'esES', 'Azeroth aún sufre, pero, gracias a ti, poco a poco, se va recuperando.', '', 28153),
(161812, 'esES', 'Vale, vamos a abrir ese puente. Creo que conozco el hechizo perfecto...', '', 28153),
(161811, 'esES', '¡Eso debería bastar! Salgamos de aquí.', '', 28153),
(161810, 'esES', 'Pero lo primero es lo primero. Tenemos que cargar ese Núcleo de Magma para arreglar el Yunquenegro.', '', 28153),
(161809, 'esES', 'Tengo terribles noticias, %p. Pedrasiniestra y sus fanáticos pretenden hacer volver a Ragnaros... Creía que habrían aprendido la lección.', '', 28153),
(161808, 'esES', 'Muéstrame los acontecimientos que hicieron que la Alianza llegara a Silithus.', 'Muéstrame los acontecimientos que hicieron que la Alianza llegara a Silithus.', 28153),
(161807, 'esES', 'Muéstrame los acontecimientos que hicieron que la Horda llegara a Silithus.', 'Muéstrame los acontecimientos que hicieron que la Horda llegara a Silithus.', 28153),
(161806, 'esES', '¡Que el ritmo no pare!', '', 28153),
(161805, 'esES', '¡Todavía tengo sed!', '', 28153),
(161804, 'esES', '¡Otra más!', '', 28153),
(161803, 'esES', '¡Otra!', '', 28153),
(161802, 'esES', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t ¡Hadal crea una |cFFFF0000|Hspell:276068|h[Fuerza del oleaje]|h|r!', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t ¡Hadal crea una |cFFFF0000|Hspell:276068|h[Fuerza del oleaje]|h|r!', 28153),
(161801, 'esES', 'Muy bien. Acabemos pues con las formalidades.', '', 28153),
(161800, 'esES', '¡Puedes contar con ello!', '', 28153),
(161799, 'esES', 'Cuando el auténtico Señor del Fuego vuelva a alzarse, todos los Hierro Negro fieles acudiremos a su llamada. ¿Piensas oponerte a nosotros?', '', 28153),
(161798, 'esES', '¿Crees que esa panda de cultores que has reunido lo va a impresionar? Ya hemos despachado a la mayoría mientras veníamos hacia aquí.', '', 28153),
(161797, 'esES', 'Thaurissan no iba por mal camino, pero su error fue intentar controlar al Señor del Fuego. Lo que debemos hacer es servirle.', '', 28153),
(161796, 'esES', '¿Ragnaros? ¿Pretendes que vuelva ese tirano? Cuando el señor feudal hechicero lo intentó...', '', 28153),
(161795, 'esES', '¿Legítima líder? Moira no tiene fuego en las venas. Nuestro legítimo líder es el Señor del Fuego, no una cría Barbabronce... una mera aspirante al trono.', '', 28153),
(161794, 'esES', 'De acuerdo. Cuidado con lo que dices, heraldo. Blasfemas contra nuestra legítima líder.', '', 28153),
(161793, 'esES', '¡Muestra algo de respeto! Te dirigirás a mí por mi título.', '', 28153),
(161792, 'esES', 'Cuidado con lo que dices, Harrold. Estás jugando con fuego.', '', 28153),
(161791, 'esES', 'Todo a su debido tiempo, maestro del yunque. Sabes tan bien como yo que la Reina regente es compasiva. Débil.', '', 28153),
(161790, 'esES', 'Pedrasiniestra... ¿Qué demonios está pasando aquí? ¿Dónde está Arderon?', '', 28153),
(161789, 'esES', '¡A tus órdenes!', '', 28153),
(161788, 'esES', '¡EL MAESTRO DEL YUNQUE THURGADEN ESTÁ AQUÍ! ¡AVISAD AL ALTO JUSTICIERO PEDRASINIESTRA!', '¡EL MAESTRO DEL YUNQUE THURGADEN ESTÁ AQUÍ! ¡AVISAD AL ALTO JUSTICIERO PEDRASINIESTRA!', 28153),
(161786, 'esES', 'Ya vale de balbuceos. ¡Dilo de una vez!', '', 28153),
(161785, 'esES', 'Eh... Bueno, verás...', 'Eh... Bueno, verás...', 28153),
(161784, 'esES', '¿Quién ha ordenado que se cierre el puente? ¿Quién está al mando?', '', 28153),
(161783, 'esES', '¿Maestro del yunque?', '¿Maestro del yunque?', 28153),
(161782, 'esES', '¿Qué significa esto?', '', 28153),
(161781, 'esES', '¡Saluda a mi amigo!', '', 28153),
(161780, 'esES', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 28153),
(161779, 'esES', '<No queda claro cómo murió este mercader, pero parece claro que es pasto de los cuervos desde hace bastante tiempo>.', '', 28153),
(161774, 'esES', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t ¡El kraken invoca un |cFFFF0000|Hspell:279897|h[Terror de las profundidades]|h|r!', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t ¡El kraken invoca un |cFFFF0000|Hspell:279897|h[Terror de las profundidades]|h|r!', 28153),
(161773, 'esES', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t ¡Los tiburones huelen la |cFFFF0000|Hspell:279893|h[Sangre en el agua]|h|r!', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t ¡Los tiburones huelen la |cFFFF0000|Hspell:279893|h[Sangre en el agua]|h|r!', 28153),
(161772, 'esES', 'Te admiraba por ello, igual que yo.', '', 28153),
(161771, 'esES', 'No han perdonado a Jaina... Era de esperar. Me preocupa su destino incierto, pero debemos centrarnos en la misión que nos ocupa.\n\nHay que conseguir que Kul Tiras se una a la Alianza. Si Katherine Valiente no quiere escucharnos, estos simpatizantes son nuestra mejor opción.', '', 28153),
(161770, 'esES', 'Agh...', '', 28153),
(161769, 'esES', '¿La Alianza? ¿Aquí?', '', 28153),
(161768, 'esES', '', 'Mi vida por la arqueología...', 28153),
(161767, 'esES', '', '¡Que no se acerquen a la excavación!', 28153),
(161766, 'esES', 'El Relicario me vengará...', '', 28153),
(161765, 'esES', '', 'Tengo que avisar... al Vigía del Sol.', 28153),
(161764, 'esES', '', '¡Eh! ¡Esto es territorio de la Horda! ¡No puedes estar aquí!', 28153),
(161763, 'esES', '¡Enséñales lo que vale un peine! Yo... te espero aquí.', '', 28153),
(161762, 'esES', '¡Alcanzaremos la victoria para la Horda!', '¡Alcanzaremos la victoria para la Horda!', 28153),
(161761, 'esES', 'Nos vemos en el frente.', 'Nos vemos en el frente.', 28153),
(161760, 'esES', '¿A punto para zarpar?', '¿A punto para zarpar?', 28153),
(161759, 'esES', '¡Nuestros enemigos sentirán pavor ante nosotros!', '¡Nuestros enemigos sentirán pavor ante nosotros!', 28153),
(161758, 'esES', '¡La batalla nos espera!', '¡La batalla nos espera!', 28153),
(161757, 'esES', '¡No podemos permitir que esta guerra eche raíces!', '¡No podemos permitir que esta guerra eche raíces!', 28153),
(161756, 'esES', '¿Me acogerás en tus ramas, ser venerable?', '¿Me acogerás en tus ramas, ser venerable?', 28153),
(161755, 'esES', 'Hoja-lá la Horda nos dejara tranquilos...', 'Hoja-lá la Horda nos dejara tranquilos...', 28153),
(161754, 'esES', '¡Ciudadanos de Boralus! ¡Posad la mirada en las mareas y observad!', '', 28153),
(161753, 'esES', 'Mis Martillo Salvaje harán que la Horda se centre en ese barco mientras nosotros nos ocupamos de Dreven en el otro.', '', 28153),
(161752, 'esES', 'Estoy listo para volver a Boralus.', 'Estoy lista para volver a Boralus.', 28153),
(161751, 'esES', '', 'La caza ha terminado. El mundo ahora es un poco más seguro.\n\nHoy ha sido un buen día.', 28153),
(161750, 'esES', '¡A la batalla!', '¡A la batalla!', 28153),
(161749, 'esES', 'Te sigo.', 'Te sigo.', 28153),
(161748, 'esES', '¡Gracias! Ahora, manos a la obra.', '¡Gracias! Ahora, manos a la obra.', 28153),
(161747, 'esES', 'Lucharé a tu lado.', 'Lucharé a tu lado.', 28153),
(161746, 'esES', 'Estoy en deuda contigo, $n.', 'Estoy en deuda contigo, $n.', 28153),
(161745, 'esES', '¡Oh, vaya! ¡Muchas gracias, $p!', '', 28153),
(161744, 'esES', '¿Entregar la carta de Rosaline a Ancel Mildenhall?', '¿Entregar la carta de Rosaline a Ancel Mildenhall?', 28153),
(161743, 'esES', '¡Tenemos un ataque de troggs entre manos! Monta en Cooper y da una lección a esos troggs.', '', 28153),
(161742, 'esES', '¡Hasta otra!', '¡Hasta otra!', 28153),
(161741, 'esES', '', 'Cierto. Los echo mucho de menos y espero volver a casa pronto. Seguro que Raimond hace lo que puede, pero tiene un talento especial para dejarlo todo patas arriba.', 28153),
(161740, 'esES', 'Con eso no pasarás frío.', '', 28153),
(161739, 'esES', 'Esa vestimenta servirá.', '', 28153),
(161738, 'esES', 'Tal vez estas prendas te ayuden a mejorar tu habilidad de recolección.', '', 28153),
(161737, 'esES', 'Te sienta bien, $n.', '', 28153),
(161736, 'esES', '¡Mi Descarga de Escarcha te dejaría $ghelado:helada;!', '¡Mi Descarga de Escarcha te dejaría $ghelado:helada;!', 28153),
(161735, 'esES', 'Gracias, te prometo que lo entregaré a tiempo.', 'Gracias, te prometo que lo entregaré a tiempo.', 28153),
(161734, 'esES', '¡No derrames tu bebida en mi hoja de personaje!', '¡No derrames tu bebida en mi hoja de personaje!', 28153),
(161733, 'esES', 'La vela para mí.', 'La vela para mí.', 28153),
(161732, 'esES', '¿Mmm?', '', 28153),
(161731, 'esES', 'Lo mismo sería más fácil sanarte si no te quedases en el fuego todo el tiempo.', 'Lo mismo es más fácil sanarte si no te quedas en el fuego todo el tiempo.', 28153),
(161730, 'esES', 'Esto... No sé dónde la he puesto. ¿Podrías darme una copia, por favor?', 'Esto... No sé dónde la he puesto. ¿Podrías darme una copia, por favor?', 28153),
(161729, 'esES', '¿Me verá el guardia si despojo este cadáver?', '¿Me verá el guardia si despojo este cadáver?', 28153),
(161728, 'esES', '¡No enfades a quien te da las misiones!', '¡No enfades a quien te da las misiones!', 28153),
(161727, 'esES', 'No, el árbol no es vulnerable a los ataques de fuego.', 'No, el árbol no es vulnerable a los ataques de fuego.', 28153),
(161726, 'esES', 'Ya te lo he dicho, ¡los bardos no son una clase!', 'Ya te lo he dicho, ¡los bardos no son una clase!', 28153),
(161725, 'esES', '', 'Saludos, $p. No esperaba volver a verte tan pronto. ¿Cómo ha reaccionado Ancel a mi carta?', 28153),
(161724, 'esES', '', 'Cielo santo, $p, espero sinceramente que no tengas por costumbre perder las cosas. Un momento, te daré una copia.', 28153),
(161723, 'esES', '¿Entregar el amuleto de miel endurecida a Rosaline?', '¿Entregar el amuleto de miel endurecida a Rosaline?', 28153),
(161722, 'esES', '', 'Ah... Nuevo día, nuevo asesinato.', 28153),
(161721, 'esES', '', 'Espera... ¡¿Dices que has estado con Ancel y Raimond?!', 28153),
(161720, 'esES', 'Bueno, es una larga historia, pero estaba dentro de un monstruo hecho de miel. Lo encontré mientras ayudaba a Ancel y a Raimond a limpiar la granja.', 'Bueno, es una larga historia, pero estaba dentro de un monstruo hecho de miel. Lo encontré mientras ayudaba a Ancel y a Raimond a limpiar la granja.', 28153),
(161719, 'esES', 'Me he encontrado este amuleto, ¿es tuyo?', 'Me he encontrado este amuleto, ¿es tuyo?', 28153),
(161718, 'esES', '', '¿Cómo puedo ayudarte? ¿Tienes artilugios Arcanos que identificar?', 28153),
(161717, 'esES', 'Ya casi tenemos todo lo que necesitamos para reparar el Yunquenegro. Solo nos falta cargar el núcleo con la esencia de Ragnaros.', '', 28153),
(161716, 'esES', '|cFF0000FF(Misión)|r Todo listo para ir al Núcleo de Magma.', '|cFF0000FF(Misión)|r Todo listo para ir al Núcleo de Magma.', 28153),
(161715, 'esES', 'Es una belleza, ¿a que sí? Salgamos de aquí. La máquina topo nos llevará a Ventormenta sanos y salvos.', '', 28153),
(161714, 'esES', 'Lo mismo te digo, hermano fúngico.', '', 28153),
(161713, 'esES', '¡Nunca fuiste nuestro igual!', '', 28153),
(161712, 'esES', 'Es difícil saber con quién estaría más decepcionado.', '', 28153),
(161711, 'esES', '¿Qué pensaría nuestro padre fúngico de esto en lo que nos hemos convertido?', '', 28153),
(161710, 'esES', 'El destino lo dirá, hermano fúngico.', '', 28153),
(161709, 'esES', 'Nunca llegarás a nada.', '', 28153),
(161708, 'esES', 'Parece que nos va a tocar andar el resto del camino.', '', 28153),
(161707, 'esES', 'Bueno, qué le vamos a hacer. Menos mal que tengo repuestos.', '', 28153),
(161706, 'esES', '¡IZQUIERDA! ¡DERECHA! ¡EL SUELO ES LAVA!', '', 28153),
(161705, 'esES', '¡Puaj! Voy a tener arena en la ropa una buena temporada.', '', 28153),
(161704, 'esES', '¡Eh! ¡Ten cuidado!', '', 28153),
(161703, 'esES', 'Un poco más y tendremos la bodega llena con el cargamento, así podremos irnos de esta costa devastada y dejar atrás este olor.', '', 28153),
(161702, 'esES', 'Pero bueno, gracias a mi tanque, todo debería ser más sencillo. Intenta no hacerle ningún rasguño mientras lo preparo todo.', '', 28153),
(161701, 'esES', 'Sin mencionar que probablemente tengamos que lidiar con el viejo Gezzrok antes de poder hacernos con un fragmento del Núcleo.', '', 28153),
(161700, 'esES', 'Igual podrían acelerar un poco el ritmo.', '', 28153),
(161699, 'esES', 'El problema es que unas bestias ígneas se interponen en nuestro camino hacia la vieja Guarida de Ragnaros.', '', 28153),
(161698, 'esES', 'Muy bien, $n, seguro que piensas que esto va a ser coser y cantar. Y no te equivocas del todo.', '', 28153),
(161697, 'esES', 'Me impresionaría bastante que tus trabajadores fueran capaces de alcanzar un nivel ligeramente superior a la pura mediocridad.', '', 28153),
(161696, 'esES', 'Te recomiendo que te centres en la tarea que tienes entre manos.', '', 28153),
(161695, 'esES', 'Francamente, la filiación política de tu... líder... no me importa lo más mínimo; ni a mí ni a quienes represento.', '', 28153),
(161694, 'esES', 'Sí, sí... Entendido.', '', 28153),
(161693, 'esES', '¡Y no es algo que nos apetezca ver!', '', 28153),
(161692, 'esES', '¡Eh, ricachones! Si seguimos perdiendo trabajadores y nuestras máquinas se siguen rompiendo, vais a tener que transportar la azerita vosotros mismos con esas piernecitas de elfo vuestras.', '', 28153),
(161691, 'esES', 'Ya. No te importa.', '', 28153),
(161690, 'esES', 'Vale, vale. Lo siento, $n.', '', 28153),
(161689, 'esES', '', 'Y tú y yo sabemos que tienes una reserva casi infinita de menas en la Cámara Negra.', 28153),
(161688, 'esES', '', 'No seas tacaño, Thaelin. $n lo necesitará para los desafíos que se avecinan.', 28153),
(161687, 'esES', 'El Yunquenegro está forjado con el hierro negro más puro, fundido y refinado mediante un proceso secreto que solo conocen los mineros y herreros de máxima confianza.', '', 28153),
(161686, 'esES', '¡Vamos a necesitar un buen montón de hierro negro para reparar este trasto!', '', 28153),
(161685, 'esES', '', 'Puedes estar $gseguro:segura; de que Volrath es el responsable de que la Horda merodee por Kul Tiras.\n\nPrimero Ashran, luego esa isla devastada en Feralas y ahora aquí... Es como un mal resfriado que no acaba de curarse.', 28153),
(161684, 'esES', 'Supongo que batirse en duelo no viene mal pa perfeccionar lah habilidadeh de combate.\n\nSin embargo, yo prefiero usar a la Alianza como muñecoh-diana.', 'Supongo que batirse en duelo no viene mal pa perfeccionar lah habilidadeh de combate.\n\nSin embargo, yo prefiero usar a la Alianza como muñecoh-diana.', 28153),
(161683, 'esES', 'Reúnete conmigo a bordo del Llanto del Alma en Pena, que está en el Puerto de Zandalar.', '', 28153),
(161682, 'esES', '¡Soldado! ¡Vuelve a tu posición!', '¡Soldado! ¡Vuelve a tu posición!', 28153),
(161681, 'esES', 'Nuestro siguiente escuadrón de refuerzos está preparándose para zarpar.', 'Nuestro siguiente escuadrón de refuerzos está preparándose para zarpar.', 28153),
(161680, 'esES', 'La batalla nos llama, ¡y responderemos!', 'La batalla nos llama, ¡y responderemos!', 28153),
(161679, 'esES', 'Nos hemos entrenado para este momento.', 'Nos hemos entrenado para este momento.', 28153),
(161678, 'esES', 'La batalla nos espera.', 'La batalla nos espera.', 28153),
(161677, 'esES', 'Vale, $n. Coge un fragmento del núcleo y volvamos a las cavernas superiores. Yo iré a buscar una máquina topo.', '', 28153),
(161676, 'esES', '$gUn:Una; $c como tú encajará bien en nuestras filas.', '$gUn:Una; $c como tú encajará bien en nuestras filas.', 28153),
(161675, 'esES', 'Prepárate para la batalla.', 'Prepárate para la batalla.', 28153),
(161674, 'esES', '¡De acuerdo!', '', 28153),
(161673, 'esES', 'Claro que lo necesitáis. Si me vences, puede que te entregue el fragmento que buscas.', '', 28153),
(161672, 'esES', 'Necesitamos un fragmento del Núcleo de Magma para reparar el Yunquenegro.', '', 28153),
(161671, 'esES', '¿Y qué es lo que buscas, hijo del fuego?', '', 28153),
(161670, 'esES', 'Thaelin Yunquenegro, del clan Hierro Negro.', '', 28153),
(161669, 'esES', '¿Quién se acerca?', '', 28153),
(161668, 'esES', 'Muy bien. Te has ganado un fragmento del Núcleo de Magma. No lo desperdicies.', '', 28153),
(161667, 'esES', 'Tremblade y su banda de catetoh de la Alianza se creen máh lihtoh que nosotroh.\n\nSu arrogancia será su perdición.', '', 28153),
(161666, 'esES', '', 'No se lo digas a los demás, pero me alegra que últimamente haya menos halcones rondando por aquí.\n\nNo es que tenga nada en contra de los pájaros, pero les he cogido cariño a estos bichitos peludos.\n\nSin halcones en la zona, mis conejos podrán disfrutar de una vida más... bueno, más larga.', 28153),
(161665, 'esES', '¡Por la Alianza!', 'Y por los caídos... Elune-adore.', 28153),
(161664, 'esES', '¡Ah, Falstad! Aquí estás.', '', 28153),
(161663, 'esES', '¡Abandona este lugar!', '¡Abandona este lugar!', 28153),
(161662, 'esES', '¡No destruiréis estas tierras!', '¡No destruiréis estas tierras!', 28153),
(161661, 'esES', 'Loh ehpírituh... me acogen...', 'Loh ehpírituh... me acogen...', 28153),
(161660, 'esES', 'No podráh matarnoh... a todoh...', 'No podráh matarnoh... a todoh...', 28153),
(161659, 'esES', 'Voy con loh ehpírituh...', 'Voy con loh ehpírituh...', 28153),
(161658, 'esES', 'Ehto no lo vi... en mih visioneh...', 'Ehto no lo vi... en mih visioneh...', 28153),
(161657, 'esES', 'La Horda... pervive...', 'La Horda... pervive...', 28153),
(161656, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(161655, 'esES', '¡No te muevah!', '¡No te muevah!', 28153),
(161654, 'esES', 'Ahí te va algo de mal juju.', 'Ahí te va algo de mal juju.', 28153),
(161653, 'esES', 'Somos imparables...', 'Somos imparables...', 28153),
(161652, 'esES', '', 'Te espero en mis aposentos, en Entrañas. Allí hablaremos de nuestro siguiente paso... sin que nadie nos oiga.', 28153),
(161651, 'esES', '¿Whisky? Nunca lo bebo.\n\nNo, yo solo estoy aquí por los pretzels.', '', 28153),
(161650, 'esES', 'Gracias, Magister. Tu conocimiento será muy valioso.', '', 28153),
(161649, 'esES', 'Estaré encantado de compartir cualquier detalle que recuerde que pueda ayudarlos.', '', 28153),
(161648, 'esES', 'Solo hay un Gallywix de verdad y lo encontraremos. Avisaré a Shaw de los señuelos.', '', 28153),
(161647, 'esES', '', 'Un Gallywix ya era más de lo que necesitaba Azeroth, y ahora tenemos... ¿cuántos dirías tú, Halford, docenas de ellos?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161645, 'esES', '¡Que alguien se encargue de $gese:esa; $pr! ¡Y que alguien me traiga manteca de cacao al balcón!', '', 28153),
(161644, 'esES', '¡Cuando quieras!', '¡Cuando quieras!', 28153),
(161643, 'esES', '¡Me alegra que hayas podido venir, $n! Avísame cuando quieras partir, puedo llevarte hasta Ulfar.', '', 28153),
(161642, 'esES', 'No entiendo para nada las fiestas de los goblins.', '', 28153),
(161641, 'esES', 'No hablemos de este sitio nunca más.', '', 28153),
(161640, 'esES', 'Qué gula y qué derroche de recursos mientras otros goblins se mueren de hambre.', '', 28153),
(161639, 'esES', 'Puaj, ¿qué es ese olor tan fuerte?', '', 28153),
(161638, 'esES', 'Nunca me ha hecho falta una ducha más que ahora.', '', 28153),
(161637, 'esES', 'No metería ni un dedo del pie en ese charco inmundo. Quién sabe lo que habrán estado haciendo dentro.', '', 28153),
(161636, 'esES', 'Por supuesto, tiran su basura al agua, sin más ni más. Qué vulgar.', '', 28153),
(161635, 'esES', 'Un agradable pedazo de naturaleza... estropeado por ese espantoso césped artificial.', '', 28153),
(161634, 'esES', 'Tu cuerpo se vuelve pesado mientras se te llenan los pulmones de humo...', 'Tu cuerpo se vuelve pesado mientras se te llenan los pulmones de humo...', 28153),
(161633, 'esES', '', 'Me alegro... de haberte encontrado...', 28153),
(161632, 'esES', '', 'Adalid... ¿Adalid? ¿Puedes oírme?', 28153),
(161631, 'esES', '¡Ya no hay llamas! ¡Id al Templo de la Luna!', '¡Ya no hay llamas! ¡Id al Templo de la Luna!', 28153),
(161630, 'esES', '¡Ishala! ¡Ishala! ¿Estás ahí? Por favor, Ishala... ¡Escucha mi voz!', '¡Ishala! ¡Ishala! ¿Estás ahí? Por favor, Ishala... ¡Escucha mi voz!', 28153),
(161629, 'esES', '¡No puedo irme sin mi hija! ¡Por favor, que alguien me ayude!', '¡No puedo irme sin mi hija! ¡Por favor, que alguien me ayude!', 28153),
(161628, 'esES', '¡Ayuda, por favor! ¡Encontrad a mi familia!', '¡Ayuda, por favor! ¡Encontrad a mi familia!', 28153),
(161627, 'esES', '¡Ayúdame, por favor! ¡No encuentro a mi hija!', '¡Ayúdame, por favor! ¡No encuentro a mi hija!', 28153),
(161626, 'esES', 'Aprovéchala. Tráela a casa.', '', 28153),
(161625, 'esES', 'Tú ahora tienes una nueva oportunidad.', '', 28153),
(161624, 'esES', 'Yo daría lo que fuera por volver a abrazar a mi hijo.', '', 28153),
(161623, 'esES', 'Si puedes oírla, aún no es demasiado tarde.', '', 28153),
(161622, 'esES', '', 'Es demasiado tarde.', 28153),
(161621, 'esES', 'Katherine, te está llamando... Debes ir con ella.', '', 28153),
(161620, 'esES', '', 'Genn... Se está quemando.', 28153),
(161619, 'esES', '', 'La veo... en mis sueños...', 28153),
(161618, 'esES', 'Y ahora sufre incluso más, ¿no es así?', '', 28153),
(161617, 'esES', 'Lo único que hizo Jaina fue seguir su corazón. Y ha sufrido por ello.', '', 28153),
(161616, 'esES', '', 'Jaina traicionó a este reino.', 28153),
(161615, 'esES', 'Tienes a Jaina.', '', 28153),
(161614, 'esES', '', 'No tengo nada... ni a nadie...', 28153),
(161613, 'esES', '', 'Priscilla, mi amiga del alma... me ha apuñalado por la espalda.', 28153),
(161612, 'esES', '', 'No sé qué hacer, Daelin. No sé en qué creer... ni en quién confiar.', 28153),
(161611, 'esES', 'Contra ella, contra Kul Tiras y contra toda la Alianza si hace falta.\n\nAmo a la Horda. Le prometí a Thrall que la defendería.\n\nDa igual quién iniciara esta guerra, yo lucharé hasta que acabe... o hasta que acabe conmigo.', '', 28153),
(161610, 'esES', 'Darnassus no puede caer... ¡No puede acabar así!', 'Darnassus no puede caer... ¡No puede acabar así!', 28153),
(161609, 'esES', 'Maldita sea la Horda. ¡Malditos sean todos!', 'Maldita sea la Horda. ¡Malditos sean todos!', 28153),
(161608, 'esES', 'No... entiendo...', 'No... entiendo...', 28153),
(161607, 'esES', '¡Gracias! Espero que los otros estén a salvo...', '¡Gracias! Espero que los otros estén a salvo...', 28153),
(161606, 'esES', '¿Lucharás contra Jaina Valiente?', '¿Lucharás contra Jaina Valiente?', 28153),
(161605, 'esES', 'Jaina Valiente.\n\nUna vez eligió salvarnos de la tiranía de su padre. Yo respeté esa decisión y lo difícil que fue.\n\nPero ella no pudo perdonar lo que Grito Infernal le hizo a Theramore. Volvió su odio contra toda la Horda.\n\nFue demasiado lejos. Mató a demasiados. Hay que poner fin a su misión de venganza.', '', 28153),
(161604, 'esES', 'Gracias... Pensaba que ya no lo contaba.', 'Gracias... Pensaba que ya no lo contaba.', 28153),
(161603, 'esES', 'Está ardiendo todo... todo...', 'Está ardiendo todo... todo...', 28153),
(161602, 'esES', 'Que Elune te bendiga...', 'Que Elune te bendiga...', 28153),
(161601, 'esES', 'Doy gracias a Elune por ti, $n.', 'Doy gracias a Elune por ti, $n.', 28153),
(161600, 'esES', '¡Envíame a Boralus!', '¡Envíame a Boralus!', 28153),
(161599, 'esES', '', 'Saludos, $c. ¿Quieres volver a Boralus?', 28153),
(161598, 'esES', '', 'Saludos, $c. ¿Te diriges al frente?', 28153),
(161597, 'esES', '¿Ella? ¿A quién te refieres?', '¿Ella? ¿A quién te refieres?', 28153),
(161596, 'esES', 'No puedo... respirar...', 'No puedo... respirar...', 28153),
(161595, 'esES', 'Había encontrado un lugar junto a otros cazadores en la Senda Oculta. Luchábamos para defender una tierra rota.\n\nPero ahora el cuerno de la guerra ha sonado una vez más.\n\nCuando oí que ella había vuelto... tuve que acudir a la llamada.', '', 28153),
(161594, 'esES', '¿Qué te trae a este conflicto, Rexxar?', '¿Qué te trae a este conflicto, Rexxar?', 28153),
(161593, 'esES', '¡Ayuda! ¡Por favor!', '¡Ayuda! ¡Por favor!', 28153),
(161592, 'esES', '¡Que alguien lo apague! ¡Quien sea!', '¡Que alguien lo apague! ¡Quien sea!', 28153),
(161591, 'esES', 'Parece que tenemos otra guerra que librar.\n\nHay poco tiempo para la charla.', '', 28153),
(161590, 'esES', 'Hace tanto... calor...', 'Hace tanto... calor...', 28153),
(161589, 'esES', '¿Por qué está pasando esto?', '¿Por qué está pasando esto?', 28153),
(161588, 'esES', '¡AAAAAH!', '¡AAAAAH!', 28153),
(161587, 'esES', '¡Agua! ¡Por favor!', '¡Agua! ¡Por favor!', 28153),
(161586, 'esES', '¡Que Elune nos guarde!', '¡Que Elune nos guarde!', 28153),
(161585, 'esES', 'Sí, me centro. En mi trabajo. Complacer a Clamañublo. Mantenerlos a salvo.\n\nDebo volver al trabajo, $n.', '', 28153),
(161584, 'esES', '¡Céntrate, hermano Zelling!', '¡Céntrate, hermano Zelling!', 28153),
(161583, 'esES', '¡Lo son TODO para mí!\n\nSoy... soy consciente de que ya no me quieren en sus vidas. ¡Pero eso podría cambiar!\n\nCuando se den cuenta de que soy yo, de que aún los quiero, sé que... que...\n\nYo... yo...', '', 28153),
(161582, 'esES', 'Sigues pensando en ellos.', 'Sigues pensando en ellos.', 28153),
(161581, 'esES', 'No estoy seguro... Todavía no he...\n\nEsto no es fácil, $n.\n\nLa señorita Voss me ha aconsejado que me centre en mi trabajo. Dice que demostrar mi valía ante Clamañublo es la mejor forma de mantener a salvo a mi familia.\n\nMi familia...', '', 28153),
(161580, 'esES', '¿Qué tal ha ido tu transición, Zelling?', '¿Qué tal ha ido tu transición, Zelling?', 28153),
(161579, 'esES', 'Haré todo lo que pueda para ayudar a la causa de los Renegados.', '', 28153),
(161578, 'esES', '¡Envíame a Zuldazar!', '¡Envíame a Zuldazar!', 28153),
(161577, 'esES', '', 'Throm-ka, $c. ¿Quieres volver a Zuldazar?', 28153),
(161576, 'esES', '', 'Cuando vivía, me enseñaron a odiar a los no-muertos. Me entrenaron para destruirlos.\n\nCuando me convertí en Renegada, me odiaba a mí misma con todas mis fuerzas.\n\nPero ahora veo que es la Alianza la que fomenta este odio. Los reinos humanos rechazan a sus antiguos hermanos y hermanas porque les recordamos lo que se oculta bajo la fachada de la carne.\n\nEs hora de poner fin a su ciclo de odio. La Alianza merece caer.', 28153),
(161575, 'esES', '', '¡La oscuridad no podrá con la Luz!', 28153),
(161574, 'esES', 'Qué vudú tan terrible.', '', 28153),
(161573, 'esES', 'No pasa nada.', 'No pasa nada.', 28153),
(161572, 'esES', '¡Nada detiene a la Horda!', '', 28153),
(161571, 'esES', '¿Y qué hay de la Alianza?', '¿Y qué hay de la Alianza?', 28153),
(161570, 'esES', '', 'No hace falta ser profeta para ver que Sylvanas usará esta guerra para traer más Renegados al mundo.\n\nMi propia conversión fue... difícil. Tuve que superar muchas cosas. Muchos asuntos pendientes.\n\nNo he abandonado todo eso. Pero también siento la obligación de ayudar a los nuevos Renegados a adaptarse a su situación. Quizás pueda ahorrarles el tipo de dolor que yo soporté.', 28153),
(161569, 'esES', 'Será un placer.', 'Será un placer.', 28153),
(161568, 'esES', 'Lo tenemos todo bajo control. Relájate y disfruta de tu cerveza.', 'Lo tenemos todo bajo control. Relájate y disfruta de tu cerveza.', 28153),
(161567, 'esES', 'Gracias, camarada, pero nos movemos más deprisa solos.', 'Gracias, camarada, pero nos movemos más deprisa solos.', 28153),
(161566, 'esES', '¿Necesitáis los elfos ayuda con vuestra misión? ¡Los Hierro Negro pueden ocuparse de ella!', '¿Necesitáis los elfos ayuda con vuestra misión? ¡Los Hierro Negro pueden ocuparse de ella!', 28153),
(161565, 'esES', '¿Qué clase de oportunidad?', '¿Qué clase de oportunidad?', 28153),
(161564, 'esES', '', 'Parece que mis habilidades llamaron la atención de las altas esferas. Solicitaron mis servicios.\n\n¿Has captado el significado oculto de la palabra? Perdona. A pesar de mi profesión, la sutileza no es mi fuerte.\n\nAun así, sé reconocer una oportunidad cuando la veo.', 28153),
(161563, 'esES', 'Parece que has abrazado la Horda.', 'Parece que has abrazado la Horda.', 28153),
(161562, 'esES', 'Halford, pongamos en marcha el proceso de volar el barco por los aires.', 'Halford, pongamos en marcha el proceso de volar el barco por los aires.', 28153),
(161561, 'esES', '¿Te llevo?', '', 28153),
(161560, 'esES', '¿Te llevo?', '', 28153),
(161559, 'esES', 'El capitán Brewston ha dicho que podrías hacerme de guía por la zona.', 'El capitán Brewston ha dicho que podrías hacerme de guía por la zona.', 28153),
(161558, 'esES', 'Gracias.', 'Gracias.', 28153),
(161557, 'esES', 'Wistel ha dicho que podrías hacerme de guía por la zona.', 'Wistel ha dicho que podrías hacerme de guía por la zona.', 28153),
(161556, 'esES', 'Gracias.', 'Gracias.', 28153),
(161555, 'esES', 'Vale, suficiente. Vamos a bajar.', '', 28153),
(161554, 'esES', 'Justo delante tienes Nido Alto. ¿Ves más allá? Eso es Ar\'gorok, $gmuchacho:muchacha;. El enemigo. El sitio que tenemos que conquistar.', '', 28153),
(161553, 'esES', '¿Eso de allí? Es Finca Nueva. Tierras de cultivo y pastos. De lo más normal.', '', 28153),
(161552, 'esES', 'Allí, hacia el este, está el Círculo de los Elementos. Tienen grandes tótems de piedra, elementales de fuego gigantescos y enormes círculos en la tierra. A los chamanes les encanta.', '', 28153),
(161551, 'esES', 'No te preocupes, no iremos lejos. Solo quiero señalar algunos de los lugares donde hemos sufrido ataques de la Horda. Por si necesitamos que... bueno, los mates.', '', 28153),
(161550, 'esES', 'Te doy la bienvenida al Aserradero de las Tierras Altas, la fuente de toda la madera de Stromgarde. Bueno, al menos es donde SOLÍAMOS conseguir nuestra madera. Desde el último ataque de la Horda, nos han echado y parece que la naturaleza ha invadido nuestra serrería.\n\nNo te preocupes. En cuanto mandemos a unos cuantos lacayos allí, volveremos a poner la vieja serrería en marcha.', '', 28153),
(161549, 'esES', 'Te doy la bienvenida al Aserradero de las Tierras Altas, la fuente de toda la madera de Stromgarde.\n\nLos bosques han estado muy tranquilos hoy. Uno de los campesinos tuvo un encontronazo con un oso, pero eso no es nada nuevo. Ya sabes cómo son los campesinos.', '', 28153),
(161548, 'esES', '', '$n, ¿no? Tully.\n\n<La supervisora Tully te tiende una mano encallecida>.\n\nEsta es la Mina de Galson. Normalmente, mis trabajadores estarían en ella extrayendo metal para la guerra, pero nos echaron con el último ataque de la Horda.\n\nDile a Brewston que nos vendría bien algo de apoyo militar. Estamos listos para trabajar, pero no vamos a poder entrar en esa mina sin pelear.', 28153),
(161547, 'esES', '', '$n, ¿no? Tully.\n\n<La supervisora Tully te tiende una mano encallecida>.\n\nNada de lo que informar. La Horda sigue siendo una espina clavada en nuestro costado y los kóbolds siguen... molestando, pero no es nada que no podamos manejar.', 28153),
(161546, 'esES', 'Vale, suficiente. Vamos a bajar.', '', 28153),
(161545, 'esES', 'Justo delante tienes Nido Alto. ¿Ves más allá? Eso es Stromgarde, $gmuchacho:muchacha;. El enemigo. El sitio que tenemos que conquistar.', '', 28153),
(161544, 'esES', '¿Eso de allí? Es Finca Nueva. Tierras de cultivo y pastos. De lo más normal.', '', 28153),
(161543, 'esES', 'Allí, hacia el este, está el Círculo de los Elementos. Tienen grandes tótems de piedra, elementales de fuego gigantescos y enormes círculos en la tierra. A los chamanes les encanta.', '', 28153),
(161542, 'esES', 'No te preocupes, no iremos lejos. Solo quiero señalar algunos de los lugares donde hemos sufrido ataques de la Alianza. Por si necesitamos que... bueno, los mates.', '', 28153),
(161541, 'esES', 'Te doy la bienvenida a Cumbre Destral, la fuente de toda la madera de Ar\'gorok. Bueno, o al menos lo era. Desde el último ataque de la Alianza, nos han echado y parece que la naturaleza ha invadido nuestro aserradero.\n\nNo te preocupes. En cuanto vengan unos cuantos brutos, volveremos a poner el viejo aserradero en marcha.', '', 28153),
(161540, 'esES', 'Te doy la bienvenida a Cumbre Destral, la fuente de toda la madera de Ar\'gorok. Bueno, o al menos lo era. Desde el último ataque de la Alianza, nos han echado y parece que la naturaleza ha invadido nuestro aserradero.\n\nNo te preocupes. En cuanto vengan unos cuantos brutos, volveremos a poner el viejo aserradero en marcha.', '', 28153),
(161539, 'esES', '$n, ¿no? Drogg.\n\n<Drogg te tiende una mano encallecida>.\n\nEsta es la Mina Mostacho Seco. Normalmente, mis peones estarían en ella extrayendo metal para la guerra, pero nos echaron con el último ataque de la Alianza.\n\nDile a Wistel que nos vendría bien algo de apoyo militar. Estamos listos para trabajar, pero no vamos a poder entrar en esa mina sin pelear.', '', 28153),
(161538, 'esES', '', '$n, ¿no? Drogg.\n\n<Drogg te tiende una mano encallecida>.\n\nNada de lo que informar. La Alianza sigue siendo una espina clavada en nuestro costado y los kóbolds siguen... molestando, pero no es nada que no podamos manejar.', 28153),
(161537, 'esES', 'Mientras Lunargenta esté con la Horda, habrá quien no se fíe de nosotros.\n\nPero el lugar de nuestro pueblo está con la Alianza. Ahora estoy más seguro de eso que nunca.\n\nSigue así, $n. Muéstrales a nuestros compañeros de la Alianza que luchamos por la misma causa.\n\nAlgún día nuestras tierras dejarán de estar bajo el control de la Horda y los hijos de Quel\'Thalas volverán a estar unidos.\n\nLo sé.', '', 28153),
(161536, 'esES', '¿Crees que nos hemos ganado la confianza de la Alianza?', '¿Crees que nos hemos ganado la confianza de la Alianza?', 28153),
(161535, 'esES', 'Lucho por controlar los susurros, igual que tú. Por suerte, Alleria Brisaveloz sigue ofreciéndonos su guía.\n\nSin su intervención... bueno, me temo que habríamos estado perdidos todos.\n\nY aunque al principio era reacio a tratar con él, he aprendido mucho del Peregrino. Pero recuerda que todo lo que ofrece acaba por servir de alguna forma a sus planes.', '', 28153),
(161534, 'esES', '¿Cómo estás, magister Umbric?', '¿Cómo estás, magister Umbric?', 28153),
(161533, 'esES', 'No estamos con la Alianza por conveniencia. Ni tampoco es un simple gesto de agradecimiento a Alleria.\n\nNuestra experiencia nos ha enseñado la importancia de que los grandes poderes estén en las manos adecuadas. No podíamos permitir que la Horda supiera lo que sabemos o que nos utilizara como arma para sus planes.\n\nLuchamos por la Alianza porque creemos en sus valores. Y un día espero que logremos traer de vuelta a toda Lunargenta.', '', 28153),
(161532, 'esES', 'Ahora luchas por la Alianza.', 'Ahora luchas por la Alianza.', 28153),
(161531, 'esES', 'Nos llevé directos a la trampa de los etéreos. De no haber sido por la intervención de Alleria Brisaveloz, habríamos estado perdidos.\n\nAl final, las energías sombrías nos transformaron... y abrieron nuestras mentes a los susurros del Vacío. Sin la orientación de Alleria, habríamos sucumbido a la locura.\n\nNos ha enseñado a acallar nuestras mentes. A atenuar los susurros. Es una lucha constante.', '', 28153),
(161530, 'esES', '¿El Vacío casi se te ha llevado?', '¿El Vacío casi se te ha llevado?', 28153),
(161529, 'esES', 'Mis seguidores y yo no éramos en absoluto leales a la Horda. Cuando el gran magister Rommath prohibió nuestra investigación del Vacío, no dudamos en marcharnos y seguir nuestro propio camino.\n\nPero me dejé llevar por la arrogancia. Estaba seguro de que podría dominar cualquier fuerza que encontráramos.\n\nQué equivocado estaba...', '', 28153),
(161528, 'esES', '¿Ansiabais el poder de las Sombras?', '¿Ansiabais el poder de las Sombras?', 28153),
(161527, 'esES', 'Como magister, siempre he tenido un deber para con Lunargenta y su gente. Cuando Arthas el loco devastó nuestras tierras, supe que debíamos usar todos los poderes a nuestra disposición para asegurar nuestra supervivencia.\n\nEl príncipe Kael\'thas propuso una manera. Yo busqué otra.', '', 28153),
(161526, 'esES', '¿Cuál es tu papel en esta campaña, Magister?', '¿Cuál es tu papel en esta campaña, Magister?', 28153),
(161525, 'esES', '', '¿Nos vamos, adalid?', 28153),
(161524, 'esES', '¿De vuelta tan pronto?', '', 28153),
(161523, 'esES', 'No sé dónde he puesto la flauta.', 'No sé dónde he puesto la flauta.', 28153),
(161521, 'esES', 'Impresionante. Gracias, Magister.', '', 28153),
(161520, 'esES', 'Viajaré contigo en esta nave para planear nuestra estrategia durante el trayecto.', '', 28153),
(161519, 'esES', 'Estarán esperando en la orilla cuando lleguemos, con un informe completo de su exploración de la zona.', '', 28153),
(161518, 'esES', 'Gracias, magister Umbric. ¿Cuánto tardaremos en verlos allí?', '', 28153),
(161517, 'esES', 'Alto comandante, he dispuesto que un regimiento de mis mejores exploradores y asesinos se reúna con nosotros en Xibala.', '', 28153),
(161516, 'esES', '', 'Vaya, tengo público... Perfecto. No te muevas, insecto de la Alianza. ¡Observa cómo acabo con uno de tus mayores héroes!', 28153),
(161515, 'esES', '¡Mándame a las Tierras Altas de Arathi!', '¡Mándame a las Tierras Altas de Arathi!', 28153),
(161514, 'esES', '', 'Throm-ka, $c. ¿Te diriges al frente?', 28153),
(161513, 'esES', '', '¡Hola! Este lugar es increíble, ¿verdad? Soy incapaz de decidir qué antro es mi favorito, pero este está claramente entre los diez primeros. Por lo menos.', 28153),
(161512, 'esES', 'Ningún barco puede igualar al nuestro. Ninguno.', 'Ningún barco puede igualar al nuestro. Ninguno.', 28153),
(161511, 'esES', 'Alabada sea la madre de las mareas.', 'Alabada sea la madre de las mareas.', 28153),
(161510, 'esES', 'Escucha a las profundidades. Solo ellas nos mostrarán la verdad.', 'Escucha a las profundidades. Solo ellas nos mostrarán la verdad.', 28153),
(161509, 'esES', '', 'Anda, mira, otro artefacto Drust. Debería llevárselo a Jane.', 28153),
(161508, 'esES', 'Que las corrientes te guíen.', 'Que las corrientes te guíen.', 28153),
(161507, 'esES', '', 'Mmmm. Tengo el pico de minero un poco suelto. Debería llevarlo a que lo vea Grix.', 28153),
(161506, 'esES', '', 'Me está entrando hambre. Debería coger a Alan e ir donde Byron.', 28153),
(161505, 'esES', '', 'Por mucho que odie admitirlo, mover materiales era mucho más fácil cuando Franklin estaba aquí.', 28153),
(161504, 'esES', '', 'Te doy la bienvenida a nuestra humilde posada. ¿En qué puedo ayudarte?', 28153),
(161503, 'esES', '', '¿Necesitas ayuda para regresar a Boralus?', 28153),
(161502, 'esES', 'Has demostrado que eres $gun aliado:una aliada; de verdad, $p.\n\nSiempre habrá un lugar para ti en nuestra caravana, ya sea aquí o donde nos lleven las arenas.', '', 28153),
(161501, 'esES', '', 'La vida en Vol\'dun es dura, pero será un poco más fácil tras nuestra victoria contra los infieles.\n\nGracias, $p.\n\nDescansa y disfruta de la hospitalidad de mi gente. Habla con los pequeñines que has ayudado a rescatar. Bebe algo.\n\nLuchamos por estos instantes de paz; debemos acordarnos de disfrutar de ellos.', 28153),
(161500, 'esES', '', 'Ha sido toda una aventura, $p. Una que no olvidaré fácilmente.\n\nAh, oye, asegúrate de saludar a Dolly. ¡Te echa de menos!', 28153),
(161499, 'esES', 'El incidente en el Almacén de Maderas Algerson se ha resuelto. Todos los clientes que esperan madera pronto verán satisfechos sus pedidos.', '', 28153),
(161498, 'esES', '', 'Uf, el pelo de estas pieles de jabalí no deja de embotarme la cuchilla. Debería pedirle a Grix que me haga algo mejor.', 28153),
(161497, 'esES', 'La guardia de los Crestavía nos ha informado de que vuelve a ser seguro viajar a Drustvar. Sin embargo, aconsejan a los viajeros curiosos que no abandonen los caminos.', '', 28153),
(161496, 'esES', '¿Quién acompaña a Talanji? ¿Eh de... la Horda?', '', 28153),
(161495, 'esES', '¿Tiene algún cráneo nuevo? ¡Dejadme ver!', '', 28153),
(161494, 'esES', '¡La Princesa ha vuelto!', '', 28153),
(161493, 'esES', '¡Talanji! ¡Talanji!', '¡Talanji! ¡Talanji!', 28153),
(161492, 'esES', 'Llévame de vuelta a Zuldazar.', 'Llévame de vuelta a Zuldazar.', 28153),
(161491, 'esES', 'Lord Norwington invita a todo jinete y cazador hábil a participar en el 15.º Festival ecuestre y de caza de Norwington en su hacienda.', '', 28153),
(161490, 'esES', '', 'La civilización es tan aburrida... Debería estar por ahí, cazando...', 28153),
(161489, 'esES', 'Dejo... mi trabajo... para siempre...', 'Dejo... mi trabajo... para siempre...', 28153),
(161488, 'esES', '¡Te aplastaré a golpes!', '¡Te aplastaré a golpes!', 28153),
(161487, 'esES', 'La guardia de los Valiente desaconseja viajar a Drustvar hasta nuevo aviso. Están esperando la respuesta de la guardia de los Crestavía. En este momento no hay más información disponible.', '', 28153),
(161486, 'esES', 'No te preocupes, ¡seguro que lo hará! Toma, me ha pedido que te entregue esta carta.', 'No te preocupes, ¡seguro que lo hará! Toma, me ha pedido que te entregue esta carta.', 28153),
(161485, 'esES', '', 'Oye, Cass. No encuentro mi cuchillo de desuello favorito. ¿Lo has vis...? ¡Ah, descuida! Lo he encontrado.', 28153),
(161484, 'esES', 'Para quienes estén inquietos por los extraños rumores que rodean al Almacén de Maderas Algerson, Maynard quiere que se sepa que todas esas historias se han exagerado con fines efectistas y que el almacén simplemente está lidiando con las habituales cuestiones de negocios.', '', 28153),
(161483, 'esES', 'Priscilla... te arrancará la cabeza por esto...', 'Priscilla... te arrancará la cabeza por esto...', 28153),
(161482, 'esES', '¡Fisgar por ahí no es bueno para la salud!', '¡Fisgar por ahí no es bueno para la salud!', 28153),
(161481, 'esES', 'Por orden del Gran Almirante, recuerdo a todos los ciudadanos que planeen visitar Canto Tormenta que deben presentarse en el puesto de control del valle para someterse a una inspección de los guardias de lord Canto Tormenta.', '', 28153),
(161480, 'esES', '¡Ah, mamá! La echo mucho de menos. Espero que vuelva pronto a casa.', '', 28153),
(161479, 'esES', 'Loh vientoh siempre ehtán cambiando. A veceh son buenoh. Otrah son maloh. Pa\'ku noh enseña a ir donde loh vientoh noh mandan, pueh eh donde se noh necesita.\n\nTú y la Horda habéih prehtado un gran servicio a mi Rey y a mi pueblo. Nunca lo olvidaremoh.\n\nComo si Loti fuera a dejar que lo olvidáramoh. Tal vez debería perdonarla. O pedir yo perdón. Ya no me acuerdo. Ehte podría ser el fin, dehpuéh de todo.', '', 28153),
(161478, 'esES', '', '¡Saludos!$b$b¿Te interesa la ingeniería?', 28153),
(161477, 'esES', '¡Papá ha estado trabajando sin descanso para arreglar la granja!', '', 28153),
(161476, 'esES', 'Echo de menos a mi madre... Lleva muchísimo tiempo fuera de casa.', '', 28153),
(161475, 'esES', '¿Sabes? Creo que a mí también me gustaría ser aventurero algún día.', '', 28153),
(161474, 'esES', '¡No me puedo creer que lucharas contra los wendigos y ganaras!', '', 28153),
(161473, 'esES', '¡Oh, dime que tienes nuevas historias chulas que contar!', '', 28153),
(161472, 'esES', '¡Hola, $p!', '', 28153),
(161471, 'esES', 'De no ser por ti habría muerto. Gracias.', 'De no ser por ti habría muerto. Gracias.', 28153),
(161470, 'esES', '¡Por loh loa, ehto va a ehtrellarse pero bien!', '¡Por loh loa, ehto va a ehtrellarse pero bien!', 28153),
(161469, 'esES', '¡Maldita sea la Horda! ¡Lor\'danel no ha hecho nada para merecerse esto!', '¡Maldita sea la Horda! ¡Lor\'danel no ha hecho nada para merecerse esto!', 28153),
(161468, 'esES', '¡Hola, primor! Tienes una pinta... horrorosa.$b$bNo te preocupes, pastelito. ¡Danny tiene justo lo que necesitas!', '', 28153),
(161467, 'esES', 'Que loh loa oh acompañen a loh doh.', '', 28153),
(161466, 'esES', 'Eh una época ohcura pa Zandalar. Trolh de sangre, loah que mueren y traidoreh. Nuehtroh cieloh ehtán cubiertoh de tinieblah y loh vientoh susurran que se avecinan todavía máh problemah.\n\nHahta Loti ehtá siendo amable conmigo. No eh natural. No me guhta.\n\nMe alegro de que ehtéh aquí, $n. Y tu Horda también.', '', 28153),
(161465, 'esES', '¡Que Elune nos asista!', '¡Que Elune nos asista!', 28153),
(161464, 'esES', 'Ehpera, ¿que quiereh hacer QUÉ?', 'Ehpera, ¿que quiereh hacer QUÉ?', 28153),
(161463, 'esES', '¿A quién le pareció ehto una buena idea?', '¿A quién le pareció ehto una buena idea?', 28153),
(161462, 'esES', '¡La granja es un desastre! ¡No sé qué ha pasado!', '', 28153),
(161461, 'esES', 'Ha ocurrido todo tan rápido...', 'Ha ocurrido todo tan rápido...', 28153),
(161460, 'esES', '¡Alabada sea Elune!', '¡Alabada sea Elune!', 28153),
(161459, 'esES', '¿Vas a alguna parte?', '¿Vas a alguna parte?', 28153),
(161458, 'esES', 'Creí que era el fin. ¡Gracias!', 'Creí que era el fin. ¡Gracias!', 28153),
(161457, 'esES', 'No puedeh hacer tantoh intentoh aquí.', 'No puedeh hacer tantoh intentoh aquí.', 28153),
(161456, 'esES', 'Demasiadoh intentoh aquí.', 'Demasiadoh intentoh aquí.', 28153),
(161455, 'esES', 'Lor\'danel no pudo hacer nada...', 'Lor\'danel no pudo hacer nada...', 28153),
(161454, 'esES', 'El cliente sufrirá por ehto.', 'El cliente sufrirá por ehto.', 28153),
(161453, 'esES', 'He conocido a tu madre. ¡Te manda saludos!', 'He conocido a tu madre. ¡Te manda saludos!', 28153),
(161452, 'esES', 'Me dehconcierta el rendimiento actual de ehtoh cuernoatroceh.', 'Me dehconcierta el rendimiento actual de ehtoh cuernoatroceh.', 28153),
(161451, 'esES', '¡Ay! ¡Tengo alergia al dolor!', '¡Ay! ¡Tengo alergia al dolor!', 28153),
(161450, 'esES', '¿Qué pasa si me rindo y me quedo aquí?', '¿Qué pasa si me rindo y me quedo aquí?', 28153),
(161449, 'esES', '¡Gonk, no me falleh ahora!', '¡Gonk, no me falleh ahora!', 28153),
(161448, 'esES', '¡A correr!', '¡A correr!', 28153),
(161447, 'esES', '¡¿Por qué nos atacan?!', '¡¿Por qué nos atacan?!', 28153),
(161446, 'esES', '¡No! ¡Nanay! ¡Ni hablar!', '¡No! ¡Nanay! ¡Ni hablar!', 28153),
(161445, 'esES', '¡Correráh rápido, pero nunca me atraparáh!', '¡Correráh rápido, pero nunca me atraparáh!', 28153),
(161444, 'esES', '¡Corre!', '¡Corre!', 28153),
(161443, 'esES', '<El diario está abierto por una página que relata el ataque de la Horda a la Plaza de Brennadam>.', '<El diario está abierto por una página que relata el ataque de la Horda a la Plaza de Brennadam>.', 28153),
(161442, 'esES', '', '¡Yo ni siquiera sabía pa qué servía ese sello!\n\nAhora, máh que nunca, debemoh trabajar juntoh pa superar loh peligroh que amenazan a Zandalar. Cuida de tuh compañeroh de manada y ayúdaloh con suh cargah.\n\nEl traidor Zul ha muerto. Podría recordarle a Raal que yo tenía razón, pero vihto que somoh tan pocoh, ¿debería hacer lah paceh? Bah.', 28153),
(161441, 'esES', '', '¡Te doy la bienvenida a Pieles y cueros de Kul Tiras!$b$bUf... Necesitamos un nombre mejor.$b$bMe llamo Cass e imparto clases de peletería. Mi compañera, Cami, es un poco brusca, pero no encontrarás mejor desolladora.$b$bDicho eso, ¿qué es lo que deseas?', 28153),
(161440, 'esES', '', 'La pérdida de tantoh loa... Que Gonk proteja a loh que ahora han quedado huérfanoh. Mi corazón sufre por mi Rey y la Princesa. La pérdida de Rezan eh una herida en suh corazoneh.\n\nBAH. Puede que incluso tenga que ser educada con Raal, pero solo durante unoh díah.\n\nGraciah, $n. Tú y tu Horda soih fuerteh. Hacéih máh fuerte a nuehtra manada. Oh necesitaremoh.', 28153),
(161439, 'esES', '', 'Hah demohtrado una y otra vez tu valor pa el Imperio Zandalari. La derrota de loh trolh de sangre, la de la amenaza sethrak y ahora incluso la del traicionero profeta.\n\nEh un honor ehtar a tu lado, $n.', 28153),
(161438, 'esES', '¿Supongo que buscas una nueva mascota?\n\n<Ulfar resopla con desprecio>.\n\nLa magia de este lugar es profunda y poderosa. Ha pasado a habitar en algunos de los animales de la región. Son poderosas manifestaciones de la naturaleza que hay que respetar.', '', 28153),
(161437, 'esES', 'Qué $gobservador:observadora;.\n\n<Ulfar se ríe>.\n\nEn efecto, sí, pero no todo mi pueblo estuvo de acuerdo con el conflicto. ¿Nunca has visto divisiones entre los tuyos?\nLos Hablaespinas nos unimos a la sociedad de Kul Tiras. Algunos de vuestros descendientes oyeron la llamada de la naturaleza y deseaban aprender las antiguas tradiciones, así que se las hemos enseñado. ¿Acaso oyes tú la llamada? ¿No?', '', 28153),
(161436, 'esES', 'Zul ha muerto, pero ¿a qué precio?\n\nEl Gran Sello ehtá roto. Mythrah el Desintegrador vuelve a pisar ehte mundo. El mayor mal al que se hayan enfrentado loh Zandalari se avecina en el horizonte y se llama G\'huun.\n\nEhta carga eh mía, $n. Si hubiera hecho caso a Talanji, si me hubiera ocupado de Zul en cualquiera de lah muchah ocasioneh que se cuehtionó su comportamiento, quizáh ehto podría haberse evitado. Quizáh mi loa aún viviría y yo no me habría aliado con el loa de la muerte.\n\nEhta eh mi vergüenza.\n\nPero tú, $n, hah ehtado a mi lado. Tu Horda ha luchado junto a nosotroh contra nuehtroh enemigoh máh antiguoh. Loh Zandalari no lo olvidarán.\n\nMe aseguraré de ello.', '', 28153),
(161435, 'esES', 'En efecto. No todo mi pueblo estuvo de acuerdo con el conflicto. ¿Nunca has visto divisiones entre los tuyos?\n\nLos Hablaespinas nos unimos a la sociedad de Kul Tiras. Algunos de sus descendientes oyeron la llamada de la naturaleza y deseaban aprender las antiguas tradiciones, así que se las hemos enseñado.', '', 28153),
(161434, 'esES', 'Soy Ulfar, el último de los Hablaespinas Drust y el maestro de estos alumnos. Un día mi tarea habrá terminado, volveré a la tierra y un nuevo Alto Hablaespinas asumirá el mando, como debe ser.\n\nPero ese día aún no ha llegado.', '', 28153),
(161433, 'esES', '¡Ah! ¡Me has asustado!$b$b¿Vienes... para aprender a pescar? La verdad es que no sé nada más.', '', 28153),
(161432, 'esES', 'He visto algunos animales que parecen tener parte de planta. ¿Puedes hablarme de ellos?', 'He visto algunos animales que parecen tener parte de planta. ¿Puedes hablarme de ellos?', 28153),
(161431, 'esES', '¡Eres un Drust! ¡Libramos una guerra contra vosotros!', '¡Eres un Drust! ¡Libramos una guerra contra vosotros!', 28153),
(161430, 'esES', '¿Eres un Drust? ¿No hubo una guerra contra ellos?', '¿Eres un Drust? ¿No hubo una guerra contra ellos?', 28153),
(161429, 'esES', '¿Puedes contar tu historia otra vez?', '¿Puedes contar tu historia otra vez?', 28153),
(161428, 'esES', '¿Quién eres?', '¿Quién eres?', 28153),
(161427, 'esES', '', 'Hay que acordarse de cuidar de uno mismo, $p. No podemos ayudar a nuestros seres queridos si apenas podemos sobrevivir nosotros mismos.', 28153),
(161426, 'esES', '¿Tú también eres druida?', '¿Tú también eres druida?', 28153),
(161425, 'esES', '¿Sois druidas?', '¿Sois druidas?', 28153),
(161424, 'esES', '', '¡Espero que te haya ido bien en tus aventuras, $p!', 28153),
(161423, 'esES', 'Lo somos, $n. Somos guardianes del equilibrio en la naturaleza, los protectores del ciclo. La vida es una parte de la naturaleza, igual que la muerte.', '', 28153),
(161422, 'esES', 'Lo somos y no somos tan distintos de ti, $n. Somos guardianes del equilibrio en la naturaleza, los protectores del ciclo. La vida es una parte de la naturaleza, igual que la muerte. Pero tú, como druida, ya lo sabes.\n\n$gBienvenido:Bienvenida; a nuestra arboleda.', '', 28153),
(161421, 'esES', '', 'Echo mucho de menos a Ancel y a su padre. Espero poder volver pronto a casa.', 28153),
(161420, 'esES', '', 'Me alegro de volver a verte, $p. Espero que las cosas te hayan ido bien.', 28153),
(161419, 'esES', '<Leer la entrada del diario>.', '<Leer la entrada del diario>.', 28153),
(161418, 'esES', '¡De acuerdo!', '¡De acuerdo!', 28153),
(161417, 'esES', 'Lee sobre la primera vez que Talanji y tú visteis el Corazón de la Oscuridad.', 'Lee sobre la primera vez que Talanji y tú visteis el Corazón de la Oscuridad.', 28153),
(161416, 'esES', '', 'Cierto. Los echo mucho de menos y espero volver a casa pronto. Seguro que Raimond hace lo que puede, pero tiene un talento especial para dejarlo todo patas arriba.\n\nSi vuelves a verlos, dale esta carta a mi querido Ancel.', 28153),
(161414, 'esES', 'Vaza el Loco ha tomado nota de todos los sucesos que han tenido lugar en Nazmir. A pesar de su apodo, lleva unas notas muy bien escritas y organizadas.', '', 28153),
(161413, 'esES', '', 'Zul ha provocado tanta devahtación...\n\nOh agradezco a ti y a la Horda que sigáih aquí, $n. Me alegro de no haberme equivocado al tener fe en vosotroh. Pensar que loh Zandalari podrían haber tenido que enfrentarse a ehtah cosah soloh eh... máh aterrador de lo que puedo decir con palabrah.\n\nSi seguimoh vivoh cuando ehto acabe, ehpero que podamoh devolver el favor. Loh Zandalari ehtarán siempre en deuda contigo.', 28153),
(161412, 'esES', '\"Hermano mío\", dijo Koralynn. \"Eres un pésimo marinero, pero creo que vas a ser un Sabiomar de primera\".', '\"Hermano mío\", dijo Koralynn. \"Eres un pésimo marinero, pero creo que vas a ser un Sabiomar de primera\".', 28153),
(161411, 'esES', '', 'Iré contigo, Eitrigg, y hablaré con tu Jefe de Guerra. ¿Sigue siendo el trol del que hablaba mi madre?', 28153),
(161410, 'esES', '', 'Rezan... mi loa... ha muerto.\n\nMi corazón sufre. Nunca he vihto a mi padre soportar tanto peso sobre suh hombroh. La traición de Zul noh hizo máh daño de lo que podíamoh pensar... incluso a quieneh sohpecharon de él dehde el principio.\n\nUna herejía así no puede quedar sin cahtigo, $n. ¡Debemoh convocar a nuehtro pueblo, nuehtroh loa, nuehtroh aliadoh! Solo entonceh tendremoh una oportunidad de detener loh vileh planeh de Zul.', 28153),
(161409, 'esES', '', 'Muy bien, entonces. Hasta la próxima.', 28153),
(161408, 'esES', '¡Buenas, $gmuchacho:muchacha;!$b$b¡$gBienvenido:Bienvenida; a la Barbacoa Boralana Byron y Hnos.! ¡Las mejores carnes ahumadas a este lado de Forjaz!$b$b¿Qué te pongo?', '', 28153),
(161407, 'esES', 'Háblame del trato de Rastakhan con Bwonsamdi.', 'Háblame del trato de Rastakhan con Bwonsamdi.', 28153),
(161406, 'esES', 'Ante nosotros se alzan los muros de Orgrimmar, capital de la Horda.', '', 28153),
(161405, 'esES', 'Hace mucho, yo sentí lo mismo. Puede resultar... desconcertante. Haré cuanto pueda para ayudarte a ti y a tu gente.', '', 28153),
(161404, 'esES', 'Vaya... Menuda historia.', 'Vaya... Menuda historia.', 28153),
(161403, 'esES', '', '¡Mythrah el Desintegrador vuelve a ehtar suelto por el mundo! Creíamoh que era parte de una leyenda, una antigua tradición pa advertirnoh de no sucumbir al deterioro del tiempo y la autocomplacencia. Pero graciah a esa serpiente de Jakra\'zet y suh aliadoh infieleh ehte terror vive de nuevo.\n\nNo todo ehtá perdido. Jakra\'zet recibió su merecido y tenemoh nuevoh aliadoh, loh vulperah y loh adoradoreh de la loa Sethralih. Sin embargo... temo que incluso contando con su fuerza no podamoh vencer a un enemigo así.\n\nSon tiempoh ohcuroh... y ehpero que no sean loh últimoh de Zandalar.', 28153),
(161402, 'esES', '', 'Hace tan solo unos segundos, luchábamos por nuestra supervivencia en Draenor. Jamás me hubiera imaginado que mis ojos verían otro mundo.', 28153),
(161401, 'esES', 'Háblame de Reproche de Talanji.', 'Háblame de Reproche de Talanji.', 28153),
(161400, 'esES', 'Háblame del ataque de Mythrax.', 'Háblame del ataque de Mythrax.', 28153),
(161399, 'esES', 'Lo hemos conseguido. Señora suprema, bienvenida a... Azeroth.', '', 28153),
(161398, 'esES', 'Háblame de la traición de Zul.', 'Háblame de la traición de Zul.', 28153),
(161397, 'esES', '', 'Durante generacioneh, loh Zandalari han luchado contra loh Nazmani. Nuehtrah fronterah han ehtado bajo asedio dehde mucho anteh de que yo naciera, y mi padre solo ha conocido la guerra contra loh trolh de sangre. Mi padre loh consideraba una plaga y hemoh permitido que reúnan suh fuerzah. Ahora sabemoh cuál eh su fuente.\n\nObedecen al Dioh de la Sangre, G\'huun.\n\nNo debemoh fracasar. Si Zuldazar cae, el rehto del mundo caerá con ella. No se detendrán hahta que el Dioh de la Sangre lo domine todo.', 28153),
(161396, 'esES', '', '$gBienvenido:Bienvenida; a mi tienda.$b$bPuedes echar un vistazo. Si tienes alguna pregunta, seguro que puedo ayudarte.', 28153),
(161395, 'esES', '', '¡Mip! ¡Mip!', 28153),
(161394, 'esES', '¡Estos especímenes Zandalari requieren una taxonomía completamente nueva!', '¡Estos especímenes Zandalari requieren una taxonomía completamente nueva!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161393, 'esES', '', '¡Estás en Encantamientos finos de Buentiempo!\n\n¡Si tienes alguna pregunta sobre alguna cuestión mística, adelante!', 28153),
(161391, 'esES', '', 'Vaya, he roto otra pluma...', 28153),
(161390, 'esES', 'La llave... vuelve a girar.', '', 28153),
(161389, 'esES', '¡Carne errante! ¡Cuando despierte, conoceréis la eternidad y os estremeceréis!', '', 28153),
(161388, 'esES', '', '¡Ah! ¡Un calambre en la mano!', 28153),
(161387, 'esES', 'Hay una verdad grande y terrible en el comienzo de todas las cosas. Yo soy su heraldo. Escucha mi sermón y asume tu infinita insignificancia.', '', 28153),
(161386, 'esES', '¡No me dejé llevar por el pánico, me puse a nadar y a beber!', '', 28153),
(161385, 'esES', '¡Allí estaba yo, atrapado en una cuba enorme de cerveza del Trueno!', '', 28153),
(161384, 'esES', 'Habéis visto el más allá. Ahora percibiréis las cosas como son en realidad.', '', 28153),
(161383, 'esES', '', 'Espera, ¿esto era una mancha o un glifo?', 28153),
(161382, 'esES', 'Sylvanas quiere enfrentarse a mí, y no se lo voy a negar.', '', 28153),
(161381, 'esES', 'Un par de cervecerías enanas mejorarían mucho Claro de la Luna.', '', 28153),
(161380, 'esES', '', '¡Vámonos! Ya debería estar listo tu submarino.', 28153),
(161379, 'esES', '¡Otra ronda para mis amigos!', '', 28153),
(161378, 'esES', '¡Un envío especial para ti!', '', 28153),
(161377, 'esES', 'Vale, no ha tenido gracia. ¡En cualquier caso, aquí estamos!', '', 28153),
(161376, 'esES', '¡Estoy demasiado enraizado! ¿Lo pillas?', '', 28153),
(161375, 'esES', 'Mis padres querían que me uniera a la marina. ¿Te lo imaginas? No podría.', '', 28153),
(161374, 'esES', 'Él y los demás me llevan guiando desde que oí la llamada cuando era pequeño.', '', 28153),
(161373, 'esES', 'Ulfar puede ser un maestro estricto, pero es justo.', '', 28153),
(161372, 'esES', '¡Espera!', '', 28153),
(161371, 'esES', '¡Eh, $n! ¡Aquí!', '', 28153),
(161370, 'esES', 'El camino a la arboleda de Ulfar puede ser un poco precario. Arthur, reúnete con nuestros amigos al principio del camino.', '', 28153),
(161369, 'esES', '¡Claro! ¡Nos vemos allí, $n!', '', 28153),
(161368, 'esES', 'Tus hazañas son la comidilla de la Falla de Telogrus, $p.\n\nMe alegra tenerte a mi lado en esta misión. Juntos, no habrá nada que pueda pararnos.', '', 28153),
(161367, 'esES', 'Estoy haciendo lo posible para que esta zona sea segura.', 'Estoy haciendo lo posible para que esta zona sea segura.', 28153),
(161366, 'esES', 'Con esos dispositivos desactivados, esta zona debería ser un poco más segura. Al menos por ahora.', 'Con esos dispositivos desactivados, esta zona debería ser un poco más segura. Al menos por ahora.', 28153),
(161365, 'esES', 'Mira por dónde pisas.', 'Mira por dónde pisas.', 28153),
(161364, 'esES', 'He desmantelado todos los dispositivos que he encontrado, pero aun así, deberías tener cuidado ahí fuera.', 'He desmantelado todos los dispositivos que he encontrado, pero aun así, deberías tener cuidado ahí fuera.', 28153),
(161363, 'esES', '', '¡Sí, claro que está arreglado! ¡Oye! ¿Por qué no revisamos los registros que encontró $n?', 28153),
(161362, 'esES', 'Ya veo, qué bien que lo hayas arreglado.', '', 28153),
(161361, 'esES', 'Qué flor tan bonita.', '', 28153),
(161360, 'esES', '', '¡Oh! Ja, ja... Bueno, el campo de contención miniaturizado no funcionaba muy bien hace diez minutos.', 28153),
(161359, 'esES', 'Kelsey, ¿por qué no hemos usado este submarino para ir a la Isla Diente Marfil?', '', 28153),
(161358, 'esES', '', '¡Tú relájate, que yo nos llevaré al puerto de guerra en un periquete!', 28153),
(161357, 'esES', 'Tu saltamareas se está asustando. ¡Da la vuelta ya!', 'Tu saltamareas se está asustando. ¡Da la vuelta ya!', 28153),
(161356, 'esES', 'Mmm... pulgones... Me encargaré de VOSOTROS más tarde.', '', 28153),
(161355, 'esES', 'Venga, bonito. Brota.', '', 28153),
(161354, 'esES', 'Ah, nada como la delicada fragancia del aethril.', '', 28153),
(161353, 'esES', 'Isla Yojamba fue una ehpedición hace muchoh añoh a la Vega de Tuercehpina. Yo formaba parte de lah fuerzah que rechazaron el regreso de Hakkar a ehte mundo. Proporcionamoh armamento glorioso a loh héroeh que lucharon contra esa inmunda abominación loa.\n\nCuando volvimoh victoriosoh a Zandalar, cometí el error de jactarme de mi victoria ante el profeta Zul. Puede que dijera algunah cosah en público que no sentaron muy bien.\n\nAhora sirvo ehquisiteceh.', '', 28153),
(161352, 'esES', 'Empiezas a dejar de prestar atención a la historia. ¡Da media vuelta ya!', 'Empiezas a dejar de prestar atención a la historia. ¡Da media vuelta ya!', 28153),
(161351, 'esES', '', 'Me alegra verte de nuevo, $p. Admiro lo rápido que has ascendido en las filas de la Alianza.\n\nPero me alegra incluso más que sigas resistiendo los susurros.\n\nLa guerra es caótica y salvaje. Da igual lo que veas y por lo que pases, nunca debes perder el control. No dejes que las sombras dominen tu voluntad.\n\nLa Alianza cuenta contigo.\n\nYo cuento contigo.', 28153),
(161350, 'esES', '¿Qué es o era Yojamba?', '¿Qué es o era Yojamba?', 28153),
(161349, 'esES', '¡La Alianza noh ataca, debemoh advertir al Rey!', '¡La Alianza noh ataca, debemoh advertir al Rey!', 28153),
(161348, 'esES', '¡La Alianza ehtá aquí, avisad al continente!', '¡La Alianza ehtá aquí, avisad al continente!', 28153),
(161347, 'esES', '¡Noh ataca la Alianza, debo advertir al continente!', '¡Noh ataca la Alianza, debo advertir al continente!', 28153),
(161346, 'esES', '¡La Alianza noh ataca, debemoh advertir a loh demáh!', '¡La Alianza noh ataca, debemoh advertir a loh demáh!', 28153),
(161345, 'esES', '', 'No bajes la guardia, Umbric. Es un plan ambicioso. Si una sola cosa sale mal, se perderán muchas vidas.', 28153),
(161344, 'esES', 'Supongo que no es una misión tan suicida como pensaba.', '', 28153),
(161343, 'esES', 'Sin ánimo de ofender, Halford, lo que propones es una misión suicida. Los Zandalari aniquilaron la última flota que se acercó a sus costas.', '', 28153),
(161342, 'esES', 'Sí, tal y como están las cosas, sufriríamos pérdidas catastróficas si intentáramos hacer cualquier desembarco.', '', 28153),
(161341, 'esES', 'Sus defensas navales destruyeron la última flota que se acercó a la isla y lo único que hacían era perseguir a una princesa en un barco.', '', 28153),
(161340, 'esES', '¿Bienes enterrados?', '¿Bienes enterrados?', 28153),
(161339, 'esES', 'Gracias, supongo...', 'Gracias, supongo...', 28153),
(161338, 'esES', '¿Hay algo de lo que quieras hablar?', '¿Hay algo de lo que quieras hablar?', 28153),
(161337, 'esES', 'Hace calor aquí.', 'Hace calor aquí.', 28153),
(161336, 'esES', '<Señalar con gestos la zona>.', '<Señalar con gestos la zona>.', 28153),
(161335, 'esES', '¿Qué decías?', '¿Qué decías?', 28153),
(161334, 'esES', '¿Esto es lo que tenías en mente?', '¿Esto es lo que tenías en mente?', 28153),
(161333, 'esES', 'Hola, no temah.', '', 28153),
(161332, 'esES', '¡Ahí tieneh, debería haber hahta pa una propina!', '', 28153),
(161331, 'esES', 'Sí, algo que ehcondí anteh de que me enterraran. Solo tieneh que encontrar la torre junto a Sendarraíz, cerca del río de Nazmir. Ehtará al pie de la torre.', '', 28153),
(161330, 'esES', 'Me da la sensación de que te debo un depósito de hace mucho tiempo. Te diré dónde ehtán mih bieneh enterradoh.', '', 28153),
(161329, 'esES', 'Tengo que admitir que ereh el mejor guía que un cráneo podría desear.', '', 28153),
(161328, 'esES', 'Me siento bien. Parece un lugar cómodo.', '', 28153),
(161327, 'esES', '¿Te he contado que oí decir a uno de esoh taponeh tiznadoh que vivía en un volcán?', '', 28153),
(161326, 'esES', 'Bueno, sí, puede ser... Te ehtáh poniendo azul... ni se te ocurra dejarme aquí.', '', 28153),
(161325, 'esES', 'Casi monté un negocio de carrerah en Vol\'dun. A mi socio le preocupaba que otro cataclihmo noh hundiera y se rajó. Ademáh, no teníamoh dinero, noh lo quitaron cuando noh exiliaron.', '', 28153),
(161324, 'esES', 'No eh un verdadero reptil... No le digah que he dicho eso.', '', 28153),
(161323, 'esES', 'En Zandalar tenemoh reptileh grandeh, loh máh grandeh que hay.', '', 28153),
(161322, 'esES', 'Creo que tengo máh frío, ¿eso eh posible?', '', 28153),
(161321, 'esES', '¿Hah vihto alguna vez un sable en la nieve? Menuda fantasía. Hablo de la nieve, claro.', '', 28153),
(161320, 'esES', 'Ehte parece un buen sitio. Podría rondar ehte lugar.', '', 28153),
(161319, 'esES', '¿Cuándo vamoh a ir a ver un sitio bonito?', '', 28153),
(161318, 'esES', '', 'Nos mudamos a esa granja con la esperanza de cambiar nuestras vidas. Las cosas no nos iban bien en la ciudad y Ancel lo pasaba mal en la escuela. Su padre y yo pensamos que sería mejor huir del ajetreo y buscar un ritmo más sosegado en el campo.\n\nYo tuve que renunciar a mis estudios Arcanos y dedicar mis esfuerzos a conseguir que la granja diera fuera productiva. No fue fácil, era un trabajo duro y vivimos tiempos de escasez. Cada vez que Raimond pensaba que iba a conseguir algo bueno, de forma inevitable, otra cosa salía terriblemente mal.\n\nEntonces decidimos que lo mejor sería que reanudara mis estudios Arcanos. He estado viajando y mejorando mis habilidades para ayudar a mi familia, ofreciendo mis talentos a quien pudiera pagarme.', 28153),
(161317, 'esES', 'Aquí hace un poco de frío, ¿no? ¿O eh cosa mía?', '', 28153),
(161316, 'esES', 'Ehte sitio parece interesante.', '', 28153),
(161315, 'esES', 'Uh, ¿dónde ehtamoh hoy?', '', 28153),
(161314, 'esES', '¿Gracias...?', '¿Gracias...?', 28153),
(161313, 'esES', 'Tendremos que reservarlo para otro momento.', 'Tendremos que reservarlo para otro momento.', 28153),
(161312, 'esES', '¿Quizás? Pero yo no soy druida.', '¿Quizás? Pero yo no soy druida.', 28153),
(161311, 'esES', 'Desde luego.', 'Desde luego.', 28153),
(161310, 'esES', 'Eso tiene que ser frustrante.', 'Eso tiene que ser frustrante.', 28153),
(161309, 'esES', 'Y que lo digas.', 'Y que lo digas.', 28153),
(161308, 'esES', 'Pero ¿esas formas más épicas no te permiten volar más rápido?', 'Pero ¿esas formas más épicas no te permiten volar más rápido?', 28153),
(161307, 'esES', 'La verdad es que he cambiado de opinión. No quiero saberlo.', 'La verdad es que he cambiado de opinión. No quiero saberlo.', 28153),
(161306, 'esES', '¿Qué te produce tanta inquietud?', '¿Qué te produce tanta inquietud?', 28153),
(161305, 'esES', 'Tienes pinta de tener una historia increíble.', 'Tienes pinta de tener una historia increíble.', 28153),
(161304, 'esES', '', 'Bueno... es una larga historia, pero me encantará contarla si te interesa. ¿Tienes un momento?', 28153),
(161303, 'esES', 'No te lo echaré en cara. De hecho, te lo escribiré, bien grande, para que sea fácil de leer.', '', 28153),
(161302, 'esES', 'Me pregunto si... tal vez, si te enseñara cómo se puede tener un aspecto respetable sin renunciar a su adorado \"vuelo más rápido\", harían caso.', '', 28153),
(161301, 'esES', 'Tú lo sabes. Pero a mí nadie me hará caso. Solo agitan su enmarañada melena, su pelaje, sus hojas, su cuello... Bah, qué más da.', '', 28153),
(161300, 'esES', 'Sí... pero, si no es indiscreción, ¿por qué no estás con ellos? ¡Han dejado la granja hecha un desastre!', 'Sí... pero, si no es indiscreción, ¿por qué no estás con ellos? ¡Han dejado la granja hecha un desastre!', 28153),
(161299, 'esES', 'Qué ignorancia tan común. ¿Quién dice que un viejo pájaro no pueda competir con esas nuevas formas tan vistosas? La formas originales y humildes nos han servido bien durante milenios.', '', 28153),
(161298, 'esES', 'Pues estos druidas jóvenes de hoy en día... No nos respetan a los tradicionalistas. A mí no me verás volar por ahí con borlas o una armadura vistosa.', '', 28153),
(161297, 'esES', '', '¿Dónde has encontrado esto? ¡Pensaba que lo había perdido para siempre!', 28153),
(161296, 'esES', 'Ah, ¿eres escriba? ¿Podría convencerte de que me hicieras un hechizo?', '', 28153),
(161295, 'esES', 'Todos tienen que llamar tanto la atención...', '', 28153),
(161294, 'esES', 'En mis tiempos, la gente respetaba lo que hacían los mayores.', '', 28153),
(161293, 'esES', 'Vine a Kul Tiras para alejarme de la guerra, así es mi vida.', '', 28153),
(161292, 'esES', 'Estos jóvenes druidas de hoy...', '', 28153),
(161291, 'esES', '¿No ves que estoy tomando el sol?', '', 28153),
(161290, 'esES', 'Márchate.', '', 28153),
(161289, 'esES', 'He despejado un camino... ¡Escapad ahora!', 'He despejado un camino... ¡Escapad ahora!', 28153),
(161288, 'esES', 'Déjame en paz.', '', 28153),
(161287, 'esES', '', '¿Qué clase de gran aventura te ha traído hasta este rincón del mundo?', 28153),
(161286, 'esES', '', 'Hacer sacrificios siempre es difícil, incluso si son por un bien mayor...', 28153),
(161285, 'esES', '', 'Espero volver a casa algún día con el poder para remediar nuestras frecuentes desgracias.', 28153),
(161284, 'esES', '', 'El estudio del conocimiento Arcano me consume por completo. A veces siento que el viaje me sobrepasa...', 28153),
(161283, 'esES', '', '¿Tienes hijos? Me pregunto cómo estará mi pequeño Ancel... Debería enviarle una carta.', 28153),
(161282, 'esES', '', '¿Por casualidad no venderás instrumentos mágicos difíciles de encontrar?', 28153),
(161281, 'esES', '', 'Hola, es un placer conocerte.', 28153),
(161280, 'esES', '¡Argh! ¡Tenía la boca abierta!', '¡Argh! ¡Tenía la boca abierta!', 28153),
(161279, 'esES', '¡El parche! ¡No sirve de nada!', '¡El parche! ¡No sirve de nada!', 28153),
(161278, 'esES', '¡Puaj! ¡Te arrancaré las alas, rata voladora!', '¡Puaj! ¡Te arrancaré las alas, rata voladora!', 28153),
(161277, 'esES', '¡Argh! ¡Ese es mi ojo bueno!', '¡Argh! ¡Ese es mi ojo bueno!', 28153),
(161276, 'esES', '¡Maldito seas, diablo con plumas!', '¡Maldito seas, diablo con plumas!', 28153),
(161275, 'esES', 'Ufff...', 'Ufff...', 28153),
(161274, 'esES', '¡Otra vez no!', '¡Otra vez no!', 28153),
(161273, 'esES', '¡Argh! ¡Asqueroso!', '¡Argh! ¡Asqueroso!', 28153),
(161272, 'esES', 'No vais a perder, ¿verdad? He apostado dinero por vosotros... y a mi padre no le gusta que pierda dinero.', '', 28153),
(161271, 'esES', 'No te preocupeh, oro de mih amoreh. ¡Pronto volveré a por ti!', 'No te preocupeh, oro de mih amoreh. ¡Pronto volveré a por ti!', 28153),
(161270, 'esES', '¡Vista al frente, soldado! ¡Estamos en una zona de guerra!', '', 28153),
(161269, 'esES', 'Mira todo ese oro, Sargento... ¡Cómo brilla!', '', 28153),
(161268, 'esES', '¡Hola! Me ocupo de entretener a los niños. ¿Qué sugieres que escuchemos?', '¡Hola! Me ocupo de entretener a los niños. ¿Qué sugieres que escuchemos?', 28153),
(161267, 'esES', '', '¡Oye, tú! ¿Te gustaría resolver rompecabezas en los que un error podría acabar matándote o convirtiéndote en pollo? ¡Si es así, tal vez deberías plantearte aprender ingeniería!', 28153),
(161266, 'esES', '', 'La verdad... es que todavía tengo que acabar el gólem aéreo en el que estaba trabajando.', 28153),
(161265, 'esES', 'Me gustaría oír una canción seria.', 'Me gustaría oír una canción seria.', 28153),
(161264, 'esES', 'Me gustaría oír una historia sobre los Sabiomar.', 'Me gustaría oír una historia sobre los Sabiomar.', 28153),
(161263, 'esES', 'Me gustaría oír una canción tonta.', 'Me gustaría oír una canción tonta.', 28153),
(161262, 'esES', 'Háblame de Athair.', 'Háblame de Athair.', 28153),
(161261, 'esES', '¡Cuberterías de plata! ¡Teteras! ¡Vajillas de primera! ¡Todo con el sello de calidad de los Gobernalle!', '¡Cuberterías de plata! ¡Teteras! ¡Vajillas de primera! ¡Todo con el sello de calidad de los Gobernalle!', 28153),
(161260, 'esES', '', 'Si aumento la fuerza de la carga inicial, también podría aumentar la potencia de la carga explosiva... ¿y qué probabilidad hay de que salga mal?', 28153),
(161259, 'esES', '¡Tengo algo para todo el mundo, señoras y señores!', '¡Tengo algo para todo el mundo, señoras y señores!', 28153),
(161258, 'esES', '¡Relojes de bolsillo para marineros! ¡Algunos ya ni se fabrican!', '¡Relojes de bolsillo para marineros! ¡Algunos ya ni se fabrican!', 28153),
(161257, 'esES', '¡Por doce monedas de plata menos de lo que cuestan en Vientos Alisios!', '¡Por doce monedas de plata menos de lo que cuestan en Vientos Alisios!', 28153),
(161256, 'esES', '¡Brújulas chapadas en oro! ¡Del mismo proveedor del almirantazgo!', '¡Brújulas chapadas en oro! ¡Del mismo proveedor del almirantazgo!', 28153),
(161255, 'esES', '', '¿Dónde habré puesto esa llave?', 28153),
(161254, 'esES', 'Mira cómo corretean por ahí como ratah de Pantoque. ¡Lánzaleh lah cargah de profundidad, $p!', 'Mira cómo corretean por ahí como ratah de Pantoque. ¡Lánzaleh lah cargah de profundidad, $p!', 28153),
(161253, 'esES', '¡Mira abajo, $p! Tienen almacenes enteros bajo el agua. ¡Lánzales las cargas de profundidad!', '', 28153),
(161252, 'esES', '', '¡Encantamientos! ¡Son muy lucrativos!', 28153),
(161251, 'esES', '', '¿Dónde ha ido a parar ese anillo? Lo llevaba cuando estaba... Oh, no... otra vez no.', 28153),
(161250, 'esES', '', 'El guerrero más fuerte no es nada sin su armadura y sus armas mágicas. ¡Aprende a encantar!', 28153),
(161249, 'esES', '', '¿Te interesan las artes Arcanas? ¡Aprende a encantar objetos con propiedades mágicas!', 28153),
(161248, 'esES', '¡Y en los cañones de los muros!', '', 28153),
(161247, 'esES', '¡Concentrad el fuego de las antorchas en las canoas con banderas rojas!', '', 28153),
(161246, 'esES', '¡Y en loh cañoneh del muro! No me apetece hundirme hoy en lah profundidadeh.', '', 28153),
(161245, 'esES', '¡Concentrad vuehtrah antorchah en lah canoah con la bandera roja!', '', 28153),
(161244, 'esES', '¡Aprende a dominar las especias y la llama!', '', 28153),
(161243, 'esES', '¿Tienes hambre? ¿Quieres quitarte el gusanillo? ¡Prepárate algo de comer!', '', 28153),
(161242, 'esES', '¡Carnes ahumadas que hacen la boca agua! ¡No están a la venta, pero puedes aprender a hacerlas tú $gmismo:misma;!', '', 28153),
(161241, 'esES', '', 'Si descubro quién es el gracioso que deja que estas reliquias se destruyan en el trayecto, le partiré todos los huesos del cuerpo.', 28153),
(161240, 'esES', '', 'Hah demohtrado tener un gran valor y honor. He comunicado al rey Rahtakhan que podríah ser alguien de fiar pa tareah máh importanteh.\n\nÁndate con ojo, porque sin duda te observan miradah hohtileh.', 28153),
(161239, 'esES', '', 'Algún coleccionista pagará bastante por esto.', 28153),
(161238, 'esES', '¡Y por eso nuestros barcos son los mejores!', '¡Y por eso nuestros barcos son los mejores!', 28153),
(161237, 'esES', 'Y Domenic, ojiplático y tembloroso, se dio cuenta de que el mar había respondido a su llamada.', 'Y Domenic, ojiplático y tembloroso, se dio cuenta de que el mar había respondido a su llamada.', 28153),
(161236, 'esES', 'En ese momento las aguas bajaron y la bestia quedó empalada en las rocas.', 'En ese momento las aguas bajaron y la bestia quedó empalada en las rocas.', 28153),
(161234, 'esES', '¡Levantó los barcos en su huida sobre las rocas! ¡El kraken perseguidor fue tras su presa!', '¡Levantó los barcos en su huida sobre las rocas! ¡El kraken perseguidor fue tras su presa!', 28153),
(161233, 'esES', '', 'Tengo que calibrar sin falta mi equipo de análisis antes de la siguiente salida.', 28153),
(161231, 'esES', '¡Entonces tomó forma de entre las aguas otro kraken tres veces más grande que el que los perseguía!', '¡Entonces tomó forma de entre las aguas otro kraken tres veces más grande que el que los perseguía!', 28153),
(161229, 'esES', '\"¡Estamos muertos!\", gritó la tripulación.', '\"¡Estamos muertos!\", gritó la tripulación.', 28153),
(161228, 'esES', 'De repente avistaron ante ellos unas rocas gigantescas, que se alzaban sobre el agua.', 'De repente avistaron ante ellos unas rocas gigantescas, que se alzaban sobre el agua.', 28153),
(161227, 'esES', 'Las indicaciones de Domenic los guiaban a salvo entre las rocas, ¡pero el kraken ganaba terreno!', 'Las indicaciones de Domenic los guiaban a salvo entre las rocas, ¡pero el kraken ganaba terreno!', 28153),
(161226, 'esES', '\"¡A babor!\", gritó Domenic, presa del pánico, pues algo tiraba de él como las mareas en esa dirección. El barco viró. \"¡Ahora a estribor!\". Una vez más, su hermana hizo lo que decía.', '\"¡A babor!\", gritó Domenic, presa del pánico, pues algo tiraba de él como las mareas en esa dirección. El barco viró. \"¡Ahora a estribor!\". Una vez más, su hermana hizo lo que decía.', 28153),
(161225, 'esES', '¡Un enorme kraken, más grande que el mayor de sus barcos, emergió de las profundidades!', '¡Un enorme kraken, más grande que el mayor de sus barcos, emergió de las profundidades!', 28153),
(161224, 'esES', 'Pero cuando llegaron, los barcos descubrieron que ellos eran la presa.', 'Pero cuando llegaron, los barcos descubrieron que ellos eran la presa.', 28153),
(161223, 'esES', '\"Creo que los mares estarán en calma y los vientos soplarán sin cesar\", dijo Domenic. La pequeña flota de caza se asombró de la velocidad de su travesía, pues su predicción se cumplió.', '\"Creo que los mares estarán en calma y los vientos soplarán sin cesar\", dijo Domenic. La pequeña flota de caza se asombró de la velocidad de su travesía, pues su predicción se cumplió.', 28153),
(161222, 'esES', '\"¡Son peligrosos!\", gritó la tripulación. \"¡Harán pedazos el barco!\".', '\"¡Son peligrosos!\", gritó la tripulación. \"¡Harán pedazos el barco!\".', 28153),
(161221, 'esES', 'El hermano pensó en ello detenidamente, como si escuchara una canción que nadie más podía oír. Entonces señaló una dirección. \"El instinto me dice que en los bajíos cerca de Kalimdor\".', 'El hermano pensó en ello detenidamente, como si escuchara una canción que nadie más podía oír. Entonces señaló una dirección. \"El instinto me dice que en los bajíos cerca de Kalimdor\".', 28153),
(161220, 'esES', '\"Hermano, ¿dónde crees que deberíamos cazar?\", le preguntó ella, pues nunca le había fallado la intuición.', '\"Hermano, ¿dónde crees que deberíamos cazar?\", le preguntó ella, pues nunca le había fallado la intuición.', 28153),
(161219, 'esES', 'Koralynn decidió que tenían que cazar en otro sitio.', 'Koralynn decidió que tenían que cazar en otro sitio.', 28153),
(161218, 'esES', 'Un día zarparon en busca de kraken con los que alimentar a la flota, pero no había ninguno en los caladeros habituales. ¡Durante semanas fueron incapaces de encontrar comida y la situación iba de mal en peor!', 'Un día zarparon en busca de kraken con los que alimentar a la flota, pero no había ninguno en los caladeros habituales. ¡Durante semanas fueron incapaces de encontrar comida y la situación iba de mal en peor!', 28153),
(161217, 'esES', 'Un día zarparon en busca de kraken con los que alimentar a la flota, pero no había ninguno en los caladeros habituales.', 'Un día zarparon en busca de kraken con los que alimentar a la flota, pero no había ninguno en los caladeros habituales.', 28153),
(161215, 'esES', 'Parecía conocer el mar como nadie. Sabía cuándo llegaban las tormentas, cuándo cambiaban las mareas y dónde ir a pescar.', 'Parecía conocer el mar como nadie. Sabía cuándo llegaban las tormentas, cuándo cambiaban las mareas y dónde ir a pescar.', 28153),
(161214, 'esES', 'Koralynn había estado observando y aprendiendo, sí, pero también había observado a su hermano.', 'Koralynn había estado observando y aprendiendo, sí, pero también había observado a su hermano.', 28153),
(161213, 'esES', '¡Qué curioso! Nunca he visto que haga ESO...', '', 28153),
(161212, 'esES', 'Nota mental: se te está acabando el extracto de musgo estelar. Consigue más cuando puedas.', '', 28153),
(161211, 'esES', 'Por eso todos se sorprendieron cuando Koralynn lo escogió para la tripulación de su primer barco, ¡incluido el mismo Domenic!', 'Por eso todos se sorprendieron cuando Koralynn lo escogió para la tripulación de su primer barco, ¡incluido el mismo Domenic!', 28153),
(161210, 'esES', '¡Y no hablemos de sus intentos de capitanear una galera!', '¡Y no hablemos de sus intentos de capitanear una galera!', 28153),
(161209, 'esES', 'Ah, se ha condensado muy bien.', '', 28153),
(161208, 'esES', 'Perdía el equilibrio sobre las jarcias y nunca aprendió a hacer los nudos ni a ajustar las velas como es debido.', 'Perdía el equilibrio sobre las jarcias y nunca aprendió a hacer los nudos ni a ajustar las velas como es debido.', 28153),
(161207, 'esES', 'Domenic era extraño. Vagaba por la cubierta ensimismado, a menudo tarareando.', 'Domenic era extraño. Vagaba por la cubierta ensimismado, a menudo tarareando.', 28153),
(161206, 'esES', 'Solo necesito quitarle un poco de calor a esto...', '', 28153),
(161205, 'esES', 'Koralynn era todo lo que debía ser una hija de Kul Tiras. Pero su hermano no.', 'Koralynn era todo lo que debía ser una hija de Kul Tiras. Pero su hermano no.', 28153),
(161203, 'esES', 'Estudiaba los mapas del firmamento, las corrientes y las zonas de caza. Observaba a los marineros y aprendía.', 'Estudiaba los mapas del firmamento, las corrientes y las zonas de caza. Observaba a los marineros y aprendía.', 28153),
(161202, 'esES', 'Mmmm... Puede que tenga que encargarle un poco más de fjarnskaggl a Enges.', '', 28153),
(161201, 'esES', 'Koralynn era fuerte e inteligente.', 'Koralynn era fuerte e inteligente.', 28153),
(161200, 'esES', 'Hace mucho tiempo, había dos niños, Koralynn y Domenic.', 'Hace mucho tiempo, había dos niños, Koralynn y Domenic.', 28153),
(161199, 'esES', '', 'Gracias, Comandante. ¡Habríamos muerto si no nos hubieras salvado! ¡Volveremos inmediatamente a nuestros puestos!', 28153),
(161198, 'esES', 'Miimii decide empezar a seguirte.', 'Miimii decide empezar a seguirte.', 28153),
(161197, 'esES', 'Se oye un sonido que proviene de un sarcófago cercano...', 'Se oye un sonido que proviene de un sarcófago cercano...', 28153),
(161196, 'esES', 'Miimii la Momia te mira con expectación.', 'Miimii la Momia te mira con expectación.', 28153),
(161195, 'esES', '¿No hay peces? Al final me moriré...', '', 28153),
(161194, 'esES', 'Llevo una eternidad sin comer.', '', 28153),
(161193, 'esES', '¿No pican? ¿TODAVÍA NO?', '', 28153),
(161192, 'esES', 'He sido testigo de muchos sucesos importantes. He visto cómo se hace la historia, cómo los conflictos se resuelven y se reanudan, traiciones y grandes victorias.\n\nEsto es una derrota segura como pocas. Zul nos ha vencido en todos los frentes y ha conseguido su objetivo final. No podemos permitir que esto sea el fin.\n\nEl conflicto inminente con este antiguo enemigo, un enemigo al que esta gente se ha enfrentado desde los albores de su raza, determinará el destino tanto de la Horda como de los Zandalari. Acudiremos a su llamada. Arreglaremos lo que Zul ha estropeado.\n\nPrepárate, mantente alerta y no vaciles, $n.', '', 28153),
(161191, 'esES', '', 'Me preocupaba no poder llevar estos suministros a tu ejército. Gracias. Por favor, llévate estos recursos como recompensa.', 28153),
(161190, 'esES', 'No sé qué estará pensando el rey Zandalari en este momento, pero sé que no podemos dejar que estos sucesos nos distraigan de nuestra meta. Los Zandalari deben resistir este conflicto. La Horda ha prometido defender a esta gente con sus espadas y puede que estemos solos si sus dioses no los salvan.\n\nAhora, más que nunca, te mirarán a ti. Represéntanos bien, portavoz de la Horda.', '', 28153),
(161189, 'esES', '', 'Vaya, estaba segura de que iba a morir. ¡Pero entonces llegaste tú! Solo por eso, le mejoraré la armadura a tu ejército. ¡Gracias!', 28153),
(161188, 'esES', '¿Buscas magia y tierras lejanas? ¿O es que la guerra te va a alejar de nosotros durante un tiempo?\n\nSi buscas los portales para ir a la Ciudad de Ventormenta, Forjaz y El Exodar, los encontrarás en el lado sur del nivel inferior del Mercado Vientos Alisios. Busca la cámara que está justo al lado de ese extraño transfigurador etéreo.', '¿Buscas magia y tierras lejanas? ¿O es que la guerra te va a alejar de nosotros durante un tiempo?\n\nSi buscas los portales para ir a la Ciudad de Ventormenta, Forjaz y El Exodar, los encontrarás en el lado sur del nivel inferior del Mercado Vientos Alisios. Busca la cámara que está justo al lado de ese extraño transfigurador etéreo.', 28153),
(161187, 'esES', '', 'Debo conservar la esperanza. Jaina podría seguir viva.', 28153),
(161186, 'esES', 'Puedo ver la oscuridad en tus ojos. Tu siguiente esfuerzo te destrozará la mente y te convertirá en otro de los fantasmas que me acechan.$b$bNo estás $gpreparado:preparada;. Vuelve cuando lo estés, la siguiente tarea te estará esperando. La corrupción ha tenido una eternidad para crecer. En el fondo, unos pocos días no tienen mucha importancia.', '', 28153),
(161185, 'esES', 'Encontré esta pista en las oficinas de Gobernalle.', 'Encontré esta pista en las oficinas de Gobernalle.', 28153),
(161184, 'esES', 'Así que por fin has venido a salvarme, ¿eh? Bueno, supongo que te debo una. Tal vez pueda devolverte el favor mejorándole las armas a tu ejército.', '', 28153),
(161183, 'esES', '', 'Me niego a creer que Jaina esté muerta.', 28153),
(161181, 'esES', '¡Pues me encanta esta clara Vientos Alisios! ¡Entra como si fuera agua!\n\n¡Me la voy a tomar de un trago para pedir otra!', '', 28153),
(161180, 'esES', 'Me encanta la cerveza de aquí. ¡Es de mis favoritas!\n\n¡Salud!', '', 28153),
(161179, 'esES', '¡$gBienvenido:Bienvenida; a nuestra cervecería!\n\nEspero que te gusten las cervezas que tenemos. Si quieres comprar barriles para alguna celebración, dímelo.\n\nMientras tanto, ¿por qué te tomas un trago?', '', 28153),
(161178, 'esES', '¡Ahí estás! Las fuerzas de Zul han intentado echarnos, pero la Horda ha hecho una demostración de fuerza. La lucha ha terminado por ahora.\n\nTeníamos motivos para sospechar que Zul conspiraba contra nosotros. No pensé que actuaría tan pronto o de forma tan decisiva. Supongo que sus facultades como profeta no eran ninguna exageración.\n\nDebemos actuar para conservar a nuestros nuevos aliados. Ve y haz lo que puedas para devolver al rey Rastakhan al poder. La Horda mantendrá el orden aquí.', '', 28153),
(161177, 'esES', 'El poder que ocupó por primera vez ehte trono gobernó a todoh loh sereh civilizadoh de ehte mundo.\n\nMíranoh ahora, con nuehtro poder reducido a una única ihla. Incluso loh trolh inferioreh desafían nuehtro poder.\n\nEhto no va a ser siempre así.', '', 28153),
(161176, 'esES', '¿Has venido en ese nuevo navío? ¡Háblame de su estructura mientras nos tomamos una cerveza!', '', 28153),
(161175, 'esES', '¡Día nuevo, cerveza nueva!\n\n¿Cuál es tu tipo de cerveza favorito?', '', 28153),
(161174, 'esES', '¿Hay que arreglar algo?', '', 28153),
(161173, 'esES', '¡Bebed!', '', 28153),
(161172, 'esES', 'Mi hija piensa que lah amenazah de Nazmir son tan grandeh que debemoh enviar todo nuehtro ejército a nuehtra frontera norte.\n\nEh joven e impaciente. No entiende que loh trolh de sangre han acosado a nuehtro pueblo durante generacioneh.\n\nSi cree que la Horda la ayudará, entonceh ehtoy impaciente por ver lo que tú podráh conseguir. Le vendría bien algo de ehperiencia tratando con potenciah ehtranjerah.\n\nDebeh saber que si ella sufre algún daño, reduciré tu Horda a cenizah y de ese lamentable hatajo de barcuchoh que llamáih flota no dejaré máh que loh dehpojoh.\n\nBuena suerte.', '', 28153),
(161171, 'esES', '¡Salud a todo el mundo!', '', 28153),
(161170, 'esES', 'En cuanto termine esta bebida, iré para allá y los ayudaré con eso.', '', 28153),
(161169, 'esES', '¡Malfurion ha avisado de que la Legión Ardiente está atacando Costa Abrupta!', '', 28153),
(161168, 'esES', 'Tyrande y yo éramos pareja antes de que conociera a Mildred.', '', 28153),
(161167, 'esES', '¡Me puse manos a la obra y salvé hasta el último barril de ron!', '', 28153),
(161166, 'esES', 'El barco se hundió y había gente ahogándose por todas partes. Treinta barriles de ron de Tiragarde, directos al fondo.', '', 28153),
(161165, 'esES', 'Ni una sola cerveza negra decente en la Arboleda de los Sueños. Por eso nunca voy allí.', '', 28153),
(161164, 'esES', '¡Todoh a bordo, zarpamoh hacia Zuldazar!', '', 28153),
(161163, 'esES', '¡Todoh a bordo, zarpamoh hacia lah Ihlah del Eco!', '', 28153),
(161162, 'esES', 'No temas las mareas de guerra que se acercan, $p. Nuestra faceta más fuerte solo se muestra cuando nos ponen a prueba de verdad.', '', 28153),
(161161, 'esES', '¡Tienes que convencer al Rey de que me destine a un clima más templado!', '', 28153),
(161160, 'esES', 'El conflicto apenas está empezando, $p. Espero que te hayas preparado para los rigores de la guerra.', '', 28153),
(161159, 'esES', 'Me parece que necesito un aumento por trabajar aquí. ¡Un plus de peligrosidad, $r! ¡Un plus de peligrosidad!', '', 28153),
(161158, 'esES', 'Puede que acabe prendiéndome fuego si me pican más bichos en los bajos. ¡Odio este lugar!', '', 28153),
(161157, 'esES', 'Que la Horda mande a sus soldados más fuertes contra nosotros. Nada me gustaría más que poner a prueba mi hoja contra un enemigo digno.', '', 28153),
(161156, 'esES', '¡Ah! ¡Qué calor! ¿Ves el sudor que me cae por la barba?', '', 28153),
(161155, 'esES', 'Si ves la oportunidad de echar una mano, hazlo, por favor. No hace falta pedir permiso en estos tiempos peligrosos.', '', 28153),
(161154, 'esES', 'No te preocupeh, ehte eh uno de loh barcoh máh rápidoh de Zandalar. Te llevaremoh a tu dehtino.', '', 28153),
(161153, 'esES', 'Si tenemos que eliminar a la Horda, debemos actuar con astucia y precisión. No hay margen para el error.', '', 28153),
(161152, 'esES', '¡Ehtamoh llegando a lah Ihlah del Eco!', '', 28153),
(161151, 'esES', '¡Ehtamoh llegando a Zuldazar!', '', 28153),
(161150, 'esES', 'Acabo de reordenar los barriles de más clara a más oscura.\n\nPero ¿debería hacerlo por orden alfabético? ¿Por fecha? ¿Por malta, quizás?', '', 28153),
(161149, 'esES', '', 'Hola, encanto. ¿Buscas un compañero de fiar? ¿Una criatura con la que acurrucarte los días de tormenta? ¿Un mejor amigo con el que compartir las alegrías y las penas de la vida?', 28153),
(161148, 'esES', 'Mmmm... ehto me trae recuerdoh... de cuando aprendía minería... Secott siempre me decía... que el truco ehtaba en golpear con el pico en ángulo... Mantiene la... mena...', '¡Puaj! Demasiada fruta solar...', 28153),
(161147, 'esES', 'Gracias, Comandante. ¡Habríamos muerto si no nos hubieras salvado! ¡Volveremos inmediatamente a nuestros puestos!', '', 28153),
(161146, 'esES', 'A maní precisamente no sabe.', 'A maní precisamente no sabe.', 28153),
(161145, 'esES', 'Puedo ver nuestra victoria.', 'Puedo ver nuestra victoria.', 28153),
(161144, 'esES', 'Siempre he odiado este bosque.', 'Siempre he odiado este bosque.', 28153),
(161143, 'esES', '¿Ehto qué eh, un cubo de agua de fregar sucia?', '¿Ehto qué eh, un cubo de agua de fregar sucia?', 28153),
(161142, 'esES', 'Nos haremos con el árbol.', 'Nos haremos con el árbol.', 28153),
(161141, 'esES', '¡Puaj! ¡Uf, odio la ginebra, colega!', '¡Puaj! ¡Uf, odio la ginebra, colega!', 28153),
(161140, 'esES', '', 'Ahora mihmo el barco ya debería haber dejado Zandalar y ehtar de camino hacia.', 28153),
(161139, 'esES', 'Al menos he muerto luchando.', 'Al menos he muerto luchando.', 28153),
(161138, 'esES', '', 'Ehtá al otro lado del océano, en Zandalar. Volverá pronto, no te preocupeh.', 28153),
(161137, 'esES', 'Solo eres una molestia.', 'Solo eres una molestia.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161136, 'esES', 'Esto sabe a muerto, colega.', 'Esto sabe a muerto, colega.', 28153),
(161135, 'esES', '', 'El barco acaba de partir hacia Zandalar. Volverá muy pronto.', 28153),
(161134, 'esES', '', 'La tieneh juhto delante. ¡Sube!', 28153),
(161133, 'esES', 'Uf, ¿qué eh ehto? ¿Vino tortoliano?', 'Uf, ¿qué eh ehto? ¿Vino tortoliano?', 28153),
(161132, 'esES', 'Recomiendo acompañar nuestra cerveza tostada Puntagarfio con unas deliciosas semillas de azotador tostadas.\n\nQue no te engañen las semillas. Los matices tostados de las semillas de azotador destacan particularmente cuando se mezclan con la intensidad de la malta de la cerveza. Puede parecer una combinación extraña, pero que me lleven las mareas si no es una de mis favoritas.', '', 28153),
(161131, 'esES', '¡Puaj! Demasiada fruta solar...', '¡Puaj! Demasiada fruta solar...', 28153),
(161130, 'esES', 'Recomiendo acompañar nuestra cerveza rubia de pátina con mi plato favorito, el pollo picante del coronel Tenders.\n\nLa suave miel de la cerveza contrasta de forma exquisita con el picante del pollo. ¡Es una forma excelente de limpiar el paladar cuando el picante empieza a ser excesivo!', '', 28153),
(161129, 'esES', '¡Hola! ¿Has venido a ver mi colección?', '', 28153),
(161128, 'esES', 'Oh imploro que sigáih su ejemplo. Sed flexibleh, pa que nada oh doblegue. ¡Y dejad a vuehtroh enemigoh sobre una roca cuando hayáih acabado con elloh!', 'Oh imploro que sigáih su ejemplo. Sed flexibleh, pa que nada oh doblegue. ¡Y dejad a vuehtroh enemigoh sobre una roca cuando hayáih acabado con elloh!', 28153),
(161127, 'esES', '', 'No eh seguro, pero se ehtá formando una tormenta máh allá del horizonte.', 28153),
(161126, 'esES', 'Loh vientoh traen máh que tormentah y comercio. Traen el cambio. Un cambio que Pa\'ku noh ha enseñado a afrontar.', 'Loh vientoh traen máh que tormentah y comercio. Traen el cambio. Un cambio que Pa\'ku noh ha enseñado a afrontar.', 28153),
(161125, 'esES', 'Y yo ehtaba *¡hip!* pensando en beber un trago...', 'Y yo ehtaba *¡hip!* pensando en beber un trago...', 28153),
(161124, 'esES', '¡Ya has perdido!', '¡Ya has perdido!', 28153),
(161123, 'esES', '¡Tomaremos lo que es nuestro!', '¡Tomaremos lo que es nuestro!', 28153),
(161122, 'esES', 'Mirad máh allá de lah palabrah rencorosah de quieneh se dejaron doblegar por la tormenta. Mirad en cambio a quieneh supieron adaptarse.', 'Mirad máh allá de lah palabrah rencorosah de quieneh se dejaron doblegar por la tormenta. Mirad en cambio a quieneh supieron adaptarse.', 28153),
(161121, 'esES', '¿Qué tieneh?', '¿Qué tieneh?', 28153),
(161120, 'esES', 'Se dice que eh caprichosa y que se enfurece con rapidez. Pero yo oh desafío a ver máh allá de eso.', 'Se dice que eh caprichosa y que se enfurece con rapidez. Pero yo oh desafío a ver máh allá de eso.', 28153),
(161119, 'esES', 'Tienes el honor de morir a mis manos.', 'Tienes el honor de morir a mis manos.', 28153),
(161118, 'esES', '¿Bebidah gratih?', '¿Bebidah gratih?', 28153),
(161117, 'esES', 'Ehpero que ehto merezca la pena...', 'Ehpero que ehto merezca la pena...', 28153),
(161116, 'esES', 'Suh vientoh traen la lluvia, llenan nuehtrah velah e impulsan nuehtroh barcoh por loh mareh. ¡Su poder eh todo lo que somoh!', 'Suh vientoh traen la lluvia, llenan nuehtrah velah e impulsan nuehtroh barcoh por loh mareh. ¡Su poder eh todo lo que somoh!', 28153),
(161115, 'esES', 'Recomiendo acompañar nuestra rubia Pontón con el ácido bacalao de canal salado.\n\nEl sabor amargo de la cerveza crea un contraste muy agradable con el dulzor del bacalao, mientras que el lúpulo añade una nota picante al intenso sabor salado del bacalao.', '', 28153),
(161114, 'esES', '', '¿Vah a Zandalar? Allí eh donde va el barco que atraca aquí, colega.', 28153),
(161113, 'esES', 'Ya voy, mi amor...', 'Ya voy, mi amor...', 28153),
(161112, 'esES', 'Ofrecer cóctel Amani', 'Ofrecer cóctel Amani', 28153),
(161111, 'esES', 'Ofrecer zumo de Jani', 'Ofrecer zumo de Jani', 28153),
(161110, 'esES', 'Ofrecer mojo\'ito', 'Ofrecer mojo\'ito', 28153),
(161109, 'esES', 'Ofrecer ginebra de Zul', 'Ofrecer ginebra de Zul', 28153),
(161108, 'esES', 'Ofrecer Bwonzombi', 'Ofrecer Bwonzombi', 28153),
(161107, 'esES', 'Ofrecer ponche de gruta', 'Ofrecer ponche de gruta', 28153),
(161106, 'esES', 'Recomiendo acompañar nuestra cerveza negra Levaanclas con un buen queso marrón de Vaderia.\n\nMe encantan las buenas combinaciones de cerveza y queso y el maridaje de estos dos es perfecto. Ambos tienen una suave capa de caramelo y, al juntarlos, sale a relucir lo mejor de los dos.', '', 28153),
(161105, 'esES', 'Ofrecer latigazo de trol', 'Ofrecer latigazo de trol', 28153),
(161104, 'esES', 'Que la muerte te lleve...', 'Que la muerte te lleve...', 28153),
(161103, 'esES', '', 'Mis mascotas solo se hacen más fuertes cuando un aliado cae en combate.', 28153),
(161102, 'esES', '¿Por qué están tan callados los pájaros?', '¿Por qué están tan callados los pájaros?', 28153),
(161101, 'esES', 'Lady Tyrande os detendrá.', 'Lady Tyrande os detendrá.', 28153),
(161100, 'esES', '', 'Las especies de Zandalar tienen un poder sin igual, tus otras mascotas no tienen ninguna posibilidad.', 28153),
(161099, 'esES', 'Nunca acorrales a un sable de la noche herido...', 'Nunca acorrales a un sable de la noche herido...', 28153),
(161098, 'esES', '¡Esta tierra es nuestra!', '¡Esta tierra es nuestra!', 28153),
(161097, 'esES', '', 'Esto no me lo esperaba. Ganaré la próxima vez que nos veamos.', 28153),
(161096, 'esES', '', 'Parece que en mi terreno tengo ventaja.', 28153),
(161095, 'esES', 'Adiós al honor.', 'Adiós al honor.', 28153),
(161094, 'esES', '', '¿Vienes a enfrentarte a mí en mi propia casa? Buena suerte.', 28153),
(161093, 'esES', 'No quiero matarte, pero lo haré.', 'No quiero matarte, pero lo haré.', 28153),
(161092, 'esES', '', 'Puede que no sea la especie nueva más fuerte que haya, debería seguir buscando cosas mejores que capturar.', 28153),
(161091, 'esES', '¡Recomiendo acompañar nuestra birra de nievebayas nada menos que con unas natillas de nievebayas!\n\nCon esta combinación sentirás los dos lados del perfil de sabor de las nievebayas: la acidez de la cerveza y el delicado dulzor de las natillas. La cremosidad de las natillas compensa la textura de la cerveza y crea una extravagante aventura en el paladar.', '', 28153),
(161090, 'esES', '', 'Eso seguro que deja marca.', 28153),
(161089, 'esES', '', 'Necesito más tiempo para entrenar con estas especies nuevas, estaré más fuerte en nuestro próximo combate.', 28153),
(161088, 'esES', '', 'Como he dicho, las alimañas de esta tierra son feroces. Buena pelea, igualmente.', 28153),
(161087, 'esES', '', 'Las alimañas de esta tierra son feroces, espero que estés $glisto:lista;.', 28153),
(161086, 'esES', '', 'No te preocupes, pequeño, me ocuparé de ti.', 28153),
(161085, 'esES', 'Todo debe morir.', 'Todo debe morir.', 28153),
(161084, 'esES', '', 'No estés triste por perderlo, tus otras mascotas parecen bastante fuertes.', 28153),
(161083, 'esES', 'Yo solo quería proteger mi hogar.', 'Yo solo quería proteger mi hogar.', 28153),
(161082, 'esES', '', 'Supongo que he perdido algo de práctica.', 28153),
(161081, 'esES', 'Espero soñar...', 'Espero soñar...', 28153),
(161080, 'esES', '', 'Madre mía, parece que mi equipo es más fuerte de lo que creía.', 28153),
(161079, 'esES', 'Las hojas caen...', 'Las hojas caen...', 28153),
(161078, 'esES', 'Ojalá tuviera tiempo para matarte lentamente.', 'Ojalá tuviera tiempo para matarte lentamente.', 28153),
(161077, 'esES', '', 'Llevo mucho sin combatir, espero seguir siendo un buen desafío para ti.', 28153),
(161076, 'esES', '¡Garras fuera!', '¡Garras fuera!', 28153),
(161075, 'esES', '¡Las espinas te atravesarán!', '¡Las espinas te atravesarán!', 28153),
(161074, 'esES', '', '¡No estaba lista, esto no cuenta!', 28153),
(161073, 'esES', '¡Vengaré al bosque!', '¡Vengaré al bosque!', 28153),
(161072, 'esES', '', 'Parece que mi racha de victorias sigue creciendo.', 28153),
(161071, 'esES', 'Recomiendo acompañar nuestra clara Vientos Alisios con mi rebanada de centeno con alcaravea casera.\n\nEl sabor a pan de la cerveza combina muy bien con el sabor a tierra del pan. Además, limpia el paladar con su efervescencia.', '', 28153),
(161070, 'esES', '', 'Esto no cuenta realmente como una derrota, mantengo mi racha de victorias.', 28153),
(161069, 'esES', '', '¡Hurra! ¡Y sigo con la racha de victorias!', 28153),
(161068, 'esES', '', 'Menuda racha de victorias llevo, no tenéis nada que hacer contra mí y mi equipo.', 28153),
(161067, 'esES', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t¡El avatar ya no está |cFFFF0000|Hspell:274148|h[corrupto]|h|r, ahora tus sanaciones tienen todo su efecto!', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t¡El avatar ya no está |cFFFF0000|Hspell:274148|h[corrupto]|h|r, ahora tus sanaciones tienen todo su efecto!', 28153),
(161066, 'esES', 'No te amilanes ante la derrota, demuestra estar a la altura del desafío si puedes.', '', 28153),
(161065, 'esES', 'Me gustaría comprar algo de comer.', 'Me gustaría comprar algo de comer.', 28153),
(161064, 'esES', 'Tengo la victoria a mi alcance, casi puedo sentirla.', '', 28153),
(161063, 'esES', 'Dad graciah a Gonk, corred con su manada y sabed que loh demáh caminoh siguen abiertoh pa vosotroh. Ehte eh su regalo a loh Zandalari.', 'Dad graciah a Gonk, corred con su manada y sabed que loh demáh caminoh siguen abiertoh pa vosotroh. Ehte eh su regalo a loh Zandalari.', 28153),
(161062, 'esES', 'Pero Gonk eh sabio y sabe que somoh máh fuerteh unidoh que separadoh. No exige que el suyo sea el único ídolo en vuehtro altar.', 'Pero Gonk eh sabio y sabe que somoh máh fuerteh unidoh que separadoh. No exige que el suyo sea el único ídolo en vuehtro altar.', 28153),
(161061, 'esES', '¿Qué recomiendas para acompañar la cerveza tostada Puntagarfio?', '¿Qué recomiendas para acompañar la cerveza tostada Puntagarfio?', 28153),
(161060, 'esES', 'Asombroso, llevo años sin perder una pelea. ¡Buen combate!', '', 28153),
(161059, 'esES', 'Con algo más de práctica serías un buen desafío hasta para mí, sigue así.', '', 28153),
(161058, 'esES', '¿Qué recomiendas para acompañar la cerveza rubia de pátina?', '¿Qué recomiendas para acompañar la cerveza rubia de pátina?', 28153),
(161057, 'esES', '¿Qué recomiendas para acompañar la rubia Pontón?', '¿Qué recomiendas para acompañar la rubia Pontón?', 28153),
(161056, 'esES', '¿Qué recomiendas para acompañar la cerveza negra Levaanclas?', '¿Qué recomiendas para acompañar la cerveza negra Levaanclas?', 28153),
(161055, 'esES', '¿Qué recomiendas para acompañar la birra de nievebayas?', '¿Qué recomiendas para acompañar la birra de nievebayas?', 28153),
(161054, 'esES', '¿Qué recomiendas para acompañar la clara Vientos Alisios?', '¿Qué recomiendas para acompañar la clara Vientos Alisios?', 28153),
(161053, 'esES', 'Loh otroh loa, al principio, se enfurecieron. Le ehcupieron y lo llamaron caprichoso y débil por aceptar menoh de lo que era suyo por derecho.', 'Loh otroh loa, al principio, se enfurecieron. Le ehcupieron y lo llamaron caprichoso y débil por aceptar menoh de lo que era suyo por derecho.', 28153),
(161052, 'esES', 'Dijo a suh seguidoreh: \"Podéih elegir el camino que máh se ajuhte a vosohtroh. A mih ojoh, todoh somoh una manada\".', 'Dijo a suh seguidoreh: \"Podéih elegir el camino que máh se ajuhte a vosohtroh. A mih ojoh, todoh somoh una manada\".', 28153),
(161051, 'esES', '¿Buscas algún majar delicioso que combine bien con tu cerveza?\n\nTengo lo que necesitas.', '', 28153),
(161050, 'esES', 'El loa de lah formah miró a su pueblo y vio que tenía muchah necesidadeh, necesidadeh que él no podía satihfacer.', 'El loa de lah formah miró a su pueblo y vio que tenía muchah necesidadeh, necesidadeh que él no podía satihfacer.', 28153),
(161049, 'esES', 'Pensadlo, hermanoh y hermanah. Elegid bien.', 'Pensadlo, hermanoh y hermanah. Elegid bien.', 28153),
(161048, 'esES', '¿U oh encontraréih sufriendo tormentoh hahta que el sol se vuelva negro en el cielo?', '¿U oh encontraréih sufriendo tormentoh hahta que el sol se vuelva negro en el cielo?', 28153),
(161047, 'esES', '¿Reiréih con él? ¿Bailaréih con loh demáh muertoh agradecidoh?', '¿Reiréih con él? ¿Bailaréih con loh demáh muertoh agradecidoh?', 28153),
(161046, 'esES', 'Cuando llegue vuehtra hora y vuehtro ehpíritu cruce al otro lado, ¿será Bwonsamdi vuehtro amigo?', 'Cuando llegue vuehtra hora y vuehtro ehpíritu cruce al otro lado, ¿será Bwonsamdi vuehtro amigo?', 28153),
(161045, 'esES', 'Pero yo ehtoy aquí pa recordaroh ehto. Bwonsamdi también ve el mundo de loh vivoh. Noh observa. Noh juzga.', 'Pero yo ehtoy aquí pa recordaroh ehto. Bwonsamdi también ve el mundo de loh vivoh. Noh observa. Noh juzga.', 28153),
(161044, 'esES', '\"Pero yo ehtoy vivo\", pensaréih. \"Un loa como él no tiene cabida en mi altar. Aún no\".', '\"Pero yo ehtoy vivo\", pensaréih. \"Un loa como él no tiene cabida en mi altar. Aún no\".', 28153),
(161043, 'esES', 'Krag\'wa ha vuelto y ehtah son lah leccioneh que trae a loh Zandalari.', 'Krag\'wa ha vuelto y ehtah son lah leccioneh que trae a loh Zandalari.', 28153),
(161042, 'esES', 'A loh que deseáih coraje, el poder pa proteger a otroh o la voluntad de seguir adelante, oh digo: no buhquéih máh.', 'A loh que deseáih coraje, el poder pa proteger a otroh o la voluntad de seguir adelante, oh digo: no buhquéih máh.', 28153),
(161041, 'esES', 'Seguid su ejemplo, hermanoh y hermanah. La convicción pa proteger lo que eh vuehtro eh una poderosa bendición.', 'Seguid su ejemplo, hermanoh y hermanah. La convicción pa proteger lo que eh vuehtro eh una poderosa bendición.', 28153),
(161040, 'esES', 'Ha demohtrado que, incluso ante la amenaza de la nada, aún puede defender a loh suyoh.', 'Ha demohtrado que, incluso ante la amenaza de la nada, aún puede defender a loh suyoh.', 28153),
(161039, 'esES', 'Ahora ehtoy aquí ante vosotroh pa deciroh que el gran guardián ha vuelto a nosotroh con toda su fuerza.', 'Ahora ehtoy aquí ante vosotroh pa deciroh que el gran guardián ha vuelto a nosotroh con toda su fuerza.', 28153),
(161038, 'esES', 'Siempre disfruto de una buena batalla con un contrincante nuevo.', '', 28153),
(161037, 'esES', 'Es hora de recolectar más vendas para mascotas.', '', 28153),
(161036, 'esES', '¡Buena pelea, pequeñín! ¡Ya mejorarás!', '', 28153),
(161035, 'esES', 'Porras, odio perder. Buena pelea.', '', 28153),
(161034, 'esES', 'Así, cuando lleguen nuevah tormentah, sabréih que eh una oportunidad de empezar de nuevo. No temeréih lah nubeh en el horizonte.', 'Así, cuando lleguen nuevah tormentah, sabréih que eh una oportunidad de empezar de nuevo. No temeréih lah nubeh en el horizonte.', 28153),
(161033, 'esES', '¿He ganado? ¡Estupendo, se lo diré a todos mis amigos!', '', 28153),
(161032, 'esES', '¡Es hora de una gran aventura!', '', 28153),
(161031, 'esES', 'Superar ehtah pruebah demuehtra nuehtra fuerza y nuehtra determinación. Quieneh siguen en pie cuando se van lah nubeh son máh fuerteh que anteh.', 'Superar ehtah pruebah demuehtra nuehtra fuerza y nuehtra determinación. Quieneh siguen en pie cuando se van lah nubeh son máh fuerteh que anteh.', 28153),
(161030, 'esES', 'Esa mascota era un poco siniestra de todas formas, así que no se pierde mucho.', '', 28153),
(161029, 'esES', 'Sí, hay furia en su relámpago, hay ira en el trueno. Pero el cambio no eh un proceso fácil.', 'Sí, hay furia en su relámpago, hay ira en el trueno. Pero el cambio no eh un proceso fácil.', 28153),
(161028, 'esES', 'Loh vientoh limpiarán la tierra y darán lugar a un nuevo crecimiento.', 'Loh vientoh limpiarán la tierra y darán lugar a un nuevo crecimiento.', 28153),
(161027, 'esES', 'Será mejor que te ocupes de eso antes de que lo usen para algún ritual de sangre.', '', 28153),
(161026, 'esES', 'Noh enseña a no temer la tormenta en el horizonte, pueh suh lluviah limpiarán loh pesareh del pasado.', 'Noh enseña a no temer la tormenta en el horizonte, pueh suh lluviah limpiarán loh pesareh del pasado.', 28153),
(161025, 'esES', 'Este sitio está maldito, yo nunca pierdo de esa manera.', '', 28153),
(161024, 'esES', 'Ha sido una buena pelea, pero no eres rival para mí.', '', 28153),
(161023, 'esES', 'Este sitio pone los pelos de punta, que sea una batalla rápida.', '', 28153),
(161022, 'esES', '¡Monstruo! Esa era mi mascota favorita.', '', 28153),
(161021, 'esES', 'Otro que muerde el polvo.', '', 28153),
(161020, 'esES', '¡Llámame si quieres bebercio!\n\nPero si lo que quieres es un vuelo, haz el favor de pedírselo a otro. Por mi salud mental.', '', 28153),
(161019, 'esES', '', '¡Claro! Ahí tienes.', 28153),
(161018, 'esES', '¡Odio perder! La próxima vez seré más fuerte, cuenta con ello.', '', 28153),
(161017, 'esES', '¿Tienes otro balde de leche a mano?', '¿Tienes otro balde de leche a mano?', 28153),
(161016, 'esES', '¡Otra victoria para el mejor equipo, el mío!', '', 28153),
(161015, 'esES', '¡Es hora de comenzar a luchar! ¡Adelante!', '', 28153),
(161014, 'esES', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t¡Comienza una |cFFFF0000|Hspell:269688|h[Lluvia]|h|r de ranas!', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t¡Comienza una |cFFFF0000|Hspell:269688|h[Lluvia]|h|r de ranas!', 28153),
(161013, 'esES', '', 'Pues eres $gguapo:guapa;, ¿sabes?', 28153),
(161012, 'esES', '', '¡Si alguna vez necesitas algo de mí, no dudes en pedírmelo!', 28153),
(161011, 'esES', '', 'Cuando uno cae en combate, loh demáh obtienen fuerza pa luchar con máh empeño aún.', 28153),
(161010, 'esES', '', 'Nunca podré agradecerte lo suficiente que rescataras a Millie por mí.', 28153),
(161009, 'esES', '', 'Saludos, $p. Siempre es un placer verte.', 28153),
(161008, 'esES', '', '¡Ja! ¡Uno menoh!', 28153),
(161007, 'esES', '', 'Entrenaré y ehtaré preparada la próxima vez que noh encontremoh.', 28153),
(161006, 'esES', '', 'No te entrihtezcah por la derrota, aprende de tuh erroreh y demuehtra que ehtáh a la altura del desafío.', 28153),
(161005, 'esES', '', '¡Ya era hora de que llegara algo de fuerza bruta para ayudar!', 28153),
(161004, 'esES', '', 'Luchemoh con honor, $gforahtero:forahtera;.', 28153),
(161003, 'esES', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t¡Se está formando cerca un fragmento de energía, úsalo para |cFFFF0000|Hspell:274149|h[energizar]|h|r al avatar!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t¡Se está formando cerca un fragmento de energía, úsalo para |cFFFF0000|Hspell:274149|h[energizar]|h|r al avatar!', 28153),
(161002, 'esES', '<Darle a Genn un momento para hablar con Katherine>.', '<Darle a Genn un momento para hablar con Katherine>.', 28153),
(161001, 'esES', '¡Esta es nuestra oportunidad!', '¡Esta es nuestra oportunidad!', 28153),
(161000, 'esES', '¡Coge tus cosas, rápido!', '¡Coge tus cosas, rápido!', 28153),
(160999, 'esES', '¡Vamos!', '¡Vamos!', 28153),
(160998, 'esES', '¡Venga, vámonos de aquí!', '¡Venga, vámonos de aquí!', 28153),
(160997, 'esES', 'Un guardián se forma en las cercanías para proteger el corazón de Sethraliss.', 'Un guardián se forma en las cercanías para proteger el corazón de Sethraliss.', 28153),
(160996, 'esES', 'Los seguidores de Jakra\'zet arremeten contra el corazón de Sethraliss.', 'Los seguidores de Jakra\'zet arremeten contra el corazón de Sethraliss.', 28153),
(160995, 'esES', '¡En la naturaleza hay osos, lobos y cabras que muerden!', '', 28153),
(160994, 'esES', 'Creo que eres bastante alucinante, pero respeto tu espacio.', '', 28153),
(160993, 'esES', 'No quiero hacer daño al animal, pero sí avisarlo.', '', 28153),
(160992, 'esES', 'Pero también hay que tener cuidado, por eso siempre voy armado.', '', 28153),
(160991, 'esES', 'Para que lo sepas, salir a la naturaleza es una de las cosas más alucinantes que se pueden hacer.', '', 28153),
(160990, 'esES', 'Esto de aquí es un pino. ¡Se sabe que es un pino por el aspecto que tiene!', '', 28153),
(160989, 'esES', 'También se puede llamar caída de agua, porque el agua cae por la cascada.', '', 28153),
(160988, 'esES', 'Las cascadas son majestuosas... y tienen majestuosidad.', '', 28153),
(160987, 'esES', 'Esto de aquí es una cascada.', '', 28153),
(160986, 'esES', '¿A que es alucinante?', '', 28153),
(160985, 'esES', '¡Hala, menuda belleza!', '', 28153),
(160984, 'esES', 'Y así, el Señor de lah Behtiah enseñó a suh seguidoreh lah virtudeh del valor y la convicción.', 'Y así, el Señor de lah Behtiah enseñó a suh seguidoreh lah virtudeh del valor y la convicción.', 28153),
(160983, 'esES', 'La fuente del poder no eh la fuerza, sino una voluntad inquebrantable que la edad no puede dehtruir.', 'La fuente del poder no eh la fuerza, sino una voluntad inquebrantable que la edad no puede dehtruir.', 28153),
(160982, 'esES', 'Igual que la dehcomposición devora lah floreh de la jungla, la edad devora la fuerza de la juventud.', 'Igual que la dehcomposición devora lah floreh de la jungla, la edad devora la fuerza de la juventud.', 28153),
(160981, 'esES', 'Actuad con coraje en todo lo que hagáih y no perderéih de vihta vuehtra presa.', 'Actuad con coraje en todo lo que hagáih y no perderéih de vihta vuehtra presa.', 28153),
(160980, 'esES', 'Igual que un tigre salta sobre rocah y abihmoh mientrah caza, el valiente no pierde el tiempo dejándose llevar por el miedo.', 'Igual que un tigre salta sobre rocah y abihmoh mientrah caza, el valiente no pierde el tiempo dejándose llevar por el miedo.', 28153),
(160979, 'esES', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 28153),
(160978, 'esES', 'Y así, el Rey de loh Felinoh enseñó a suh seguidoreh la virtud de la dedicación.', 'Y así, el Rey de loh Felinoh enseñó a suh seguidoreh la virtud de la dedicación.', 28153),
(160977, 'esES', 'Vivid con una determinación inquebrantable y el fracaso jamáh oh vencerá.', 'Vivid con una determinación inquebrantable y el fracaso jamáh oh vencerá.', 28153),
(160976, 'esES', 'Igual que el conhtante fluir del agua talla loh cañoneh, nacen también de la perseverancia todah lah grandeh accioneh.', 'Igual que el conhtante fluir del agua talla loh cañoneh, nacen también de la perseverancia todah lah grandeh accioneh.', 28153),
(160975, 'esES', 'Vivid una vida de honor y será una vida bien vivida.', 'Vivid una vida de honor y será una vida bien vivida.', 28153),
(160974, 'esES', 'Igual que un rey no intercambia su mayor tesoro por un mero puñado de tierra, no cambia el honorable su integridad por fama o fortuna.', 'Igual que un rey no intercambia su mayor tesoro por un mero puñado de tierra, no cambia el honorable su integridad por fama o fortuna.', 28153),
(160973, 'esES', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 28153),
(160972, 'esES', 'Y así, la Condena de la Presa enseñó a suh seguidoreh lah virtudeh de la paciencia y el rehpeto.', 'Y así, la Condena de la Presa enseñó a suh seguidoreh lah virtudeh de la paciencia y el rehpeto.', 28153),
(160971, 'esES', 'Son quieneh rehpetan el orden natural y solo toman lo necesario pa vivir.', 'Son quieneh rehpetan el orden natural y solo toman lo necesario pa vivir.', 28153),
(160970, 'esES', 'Quieneh tienen visión ven que la naturaleza no leh pertenece, sino que elloh le pertenecen a ella.', 'Quieneh tienen visión ven que la naturaleza no leh pertenece, sino que elloh le pertenecen a ella.', 28153),
(160969, 'esES', 'Igual que la jungla otorga el don de la vida, también da el toque de la muerte.', 'Igual que la jungla otorga el don de la vida, también da el toque de la muerte.', 28153),
(160968, 'esES', 'Loh necioh se dejan llevar por lah ansiah y lah emocioneh en su vida, pero no sobreviven mucho en la jungla.', 'Loh necioh se dejan llevar por lah ansiah y lah emocioneh en su vida, pero no sobreviven mucho en la jungla.', 28153),
(160967, 'esES', 'Igual que el jaguar acecha a su presa durante díah, loh sabioh obran con paciencia en todo momento.', 'Igual que el jaguar acecha a su presa durante díah, loh sabioh obran con paciencia en todo momento.', 28153),
(160966, 'esES', '¡No solo sobrevivir, sino prohperar! Yo oh digo: ¡adelante! Vivid en la miseria y hacedlo con la cabeza bien alta. Pueh ese eh el dominio de Jani.', '¡No solo sobrevivir, sino prohperar! Yo oh digo: ¡adelante! Vivid en la miseria y hacedlo con la cabeza bien alta. Pueh ese eh el dominio de Jani.', 28153),
(160965, 'esES', 'Jani no necesita bonitah palabrah ni grandeh sacrificioh. Alabar a Jani eh sobrevivir delante de lah nariceh de aquelloh que oprimen a loh rechazadoh.', 'Jani no necesita bonitah palabrah ni grandeh sacrificioh. Alabar a Jani eh sobrevivir delante de lah nariceh de aquelloh que oprimen a loh rechazadoh.', 28153),
(160964, 'esES', '¡Lo que otroh quitan, Jani lo da! Se lo da a todoh loh que se valen por sí mihmoh. Todoh loh que loh grandeh, loh alhajah, dejan de lado.', '¡Lo que otroh quitan, Jani lo da! Se lo da a todoh loh que se valen por sí mihmoh. Todoh loh que loh grandeh, loh alhajah, dejan de lado.', 28153),
(160963, 'esES', '¡Pero Jani eh máh poderoso que todoh loh demás y oh diré por qué!', '¡Pero Jani eh máh poderoso que todoh loh demás y oh diré por qué!', 28153),
(160962, 'esES', 'Ehtienden suh manoh anhelando lah alabanzah de la gente.', 'Ehtienden suh manoh anhelando lah alabanzah de la gente.', 28153),
(160961, 'esES', 'Thros... devora...', '', 28153),
(160960, 'esES', 'Nadie escapará...', '', 28153),
(160959, 'esES', 'No queda esperanza...', '', 28153),
(160958, 'esES', '¡Os arrancaré la piel!', '', 28153),
(160957, 'esES', '¡Os retorceréis de dolor!', '', 28153),
(160956, 'esES', '¡Ehcupo sobre tu loa de alhajah!', '¡Ehcupo sobre tu loa de alhajah!', 28153),
(160955, 'esES', '¡Sufrid!', '', 28153),
(160954, 'esES', '¡Dihpersaoh!', '¡Dihpersaoh!', 28153),
(160953, 'esES', '¡Jani eh el loa que me va! ¡Ja, ja, ja!', '¡Jani eh el loa que me va! ¡Ja, ja, ja!', 28153),
(160952, 'esES', '¡Jani noh hace ricoh!', '¡Jani noh hace ricoh!', 28153),
(160951, 'esES', '¡Bahta de tonteríah! ¡Fuera!', '¡Bahta de tonteríah! ¡Fuera!', 28153),
(160950, 'esES', '¡Te burlah de nosotroh con ehte ehpectáculo! ¡Vete!', '¡Te burlah de nosotroh con ehte ehpectáculo! ¡Vete!', 28153),
(160949, 'esES', '¡Ehtáh faltando al rehpeto a loh loa de verdad! ¡Saca ehta basura de aquí!', '¡Ehtáh faltando al rehpeto a loh loa de verdad! ¡Saca ehta basura de aquí!', 28153),
(160948, 'esES', '¡El inútil de Jani siempre arma un ehtropicio! ¡Fuera, fuera!', '¡El inútil de Jani siempre arma un ehtropicio! ¡Fuera, fuera!', 28153),
(160947, 'esES', 'Así no. ¡Recibe la bendición de mi loa!', 'Así no. ¡Recibe la bendición de mi loa!', 28153),
(160946, 'esES', 'Puede que haya llegado tarde...', 'Puede que haya llegado tarde...', 28153),
(160945, 'esES', 'Tal devoción hace que se me salten lah lágrimah. ¿Hah presenciado la generosidad de loh loa?', 'Tal devoción hace que se me salten lah lágrimah. ¿Hah presenciado la generosidad de loh loa?', 28153),
(160944, 'esES', 'El ritual comenzará pronto, $n.\n\nNuehtra gente, gente de toda condición, viene de todoh loh rinconeh de Zandalar pa oír la sabiduría de su loa. Muchoh vienen con la ehperanza de que loh loa leh otorguen una bendición. ¡Quizáh te den una bendición a ti también!\n\nQuédate y alaba a loh loa con el pueblo Zandalari.', 'El ritual comenzará pronto, $n.\n\nLoh nuehtroh, gente de toda condición, viene de todoh loh rinconeh de Zandalar pa oír la sabiduría de su loa. Muchoh vienen con la ehperanza de que loh loa leh otorguen una bendición. ¡Quizáh te den una bendición a ti también!\n\nQuédate y alaba a loh loa con el pueblo Zandalari.', 28153),
(160943, 'esES', 'Desearéis... morir...', '', 28153),
(160942, 'esES', '¡Vuestros gritos no tendrán fin!', '', 28153),
(160941, 'esES', 'Nadie nos negará... nuestra venganza...', '', 28153),
(160940, 'esES', '¡Pertenece a Gorak Tul!', '', 28153),
(160939, 'esES', '¡No nos arrebataréis nuestro trofeo!', '', 28153),
(160938, 'esES', 'Estabas a mi lado en Entrañas. ¡Los teníamos rodeados! ¡Era el momento de hacer justicia!', '', 28153),
(160937, 'esES', 'Hola, $ghermano:hermana;, tienes pinta de necesitar un trago. ¿Quieres una cerveza?', '', 28153),
(160936, 'esES', 'Acabo de empezar a hacer una nueva cerveza con miel Canto Tormenta de primerísima calidad.\n\n¡Nos salió muy cara, pero estoy convencido de que valdrá la pena!', '', 28153),
(160935, 'esES', '', '¿Quieres una birra? También he preparado café, por si necesitas espabilarte.', 28153),
(160934, 'esES', '¡Voy a ser un alhaja! ¡Yuju!', '¡Voy a ser una alhaja! ¡Yuju!', 28153),
(160933, 'esES', '¡Tu loa no eh bienvenido aquí! ¡Largo!', '¡Tu loa no eh bienvenido aquí! ¡Largo!', 28153),
(160932, 'esES', '¡El Dioh de la Basura te da su bendición! ¡Ja, ja, ja!', '¡El Dioh de la Basura te da su bendición! ¡Ja, ja, ja!', 28153),
(160931, 'esES', 'Loh demáh oh dirán que suh loa son loh máh generosoh, o loh máh fuerteh, o loh máh temperamentaleh.', 'Loh demáh oh dirán que suh loa son loh máh generosoh, o loh máh fuerteh, o loh máh temperamentaleh.', 28153),
(160930, 'esES', '¡Ja, ja, ja! ¡Eh hora de alabar al loa de todoh! ¡Venid a loh ehcaloneh de Dazar\'alor pa alabar a Jani!', '¡Ja, ja, ja! ¡Eh hora de alabar al loa de todoh! ¡Venid a loh ehcaloneh de Dazar\'alor pa alabar a Jani!', 28153),
(160929, 'esES', 'Si sigue el horario previhto, el barco ha zarpado ya de lah Ihlah del Eco y no tardará en llegar.', '', 28153),
(160928, 'esES', '¡Pueblo de Zandalar! ¡Eh momento de alabar a la Señora de loh Vientoh, la Reina de loh Cieloh, la Matrona del Mar! ¡Venid a loh ehcaloneh y alabad a Pa\'ku!', '¡Pueblo de Zandalar! ¡Eh momento de alabar a la Señora de loh Vientoh, la Reina de loh Cieloh, la Matrona del Mar! ¡Venid a loh ehcaloneh y alabad a Pa\'ku!', 28153),
(160927, 'esES', 'Todoh loh que ehtáih ante mí habéih sentido la bendición de Pa\'ku, mi loa.', 'Todoh loh que ehtáih ante mí habéih sentido la bendición de Pa\'ku, mi loa.', 28153),
(160926, 'esES', '¡Alabada sea Pa\'ku! ¡Que suh vientoh llenen vuehtrah velah!', '¡Alabada sea Pa\'ku! ¡Que suh vientoh llenen vuehtrah velah!', 28153),
(160925, 'esES', '¡Gonk noh otorga su bendición! ¡Que la manada siempre ehté con vosotroh!', '¡Gonk noh otorga su bendición! ¡Que la manada siempre ehté con vosotroh!', 28153),
(160924, 'esES', 'Sed bienvenidoh, hermanoh y hermanah, y sabed que hoy el ehpíritu de Gonk ehtá con nosotroh.', 'Sed bienvenidoh, hermanoh y hermanah, y sabed que hoy el ehpíritu de Gonk ehtá con nosotroh.', 28153),
(160923, 'esES', '¡Pueblo de Zandalar! El loa de lah formah buhca lah alabanzah de su gente. ¡Venid y alzaremoh nuehtrah voceh por el Señor de la Manada, el máh generoso de loh loa! ¡Alabado sea Gonk!', '¡Pueblo de Zandalar! El loa de lah formah buhca lah alabanzah de su gente. ¡Venid y alzaremoh nuehtrah voceh por el Señor de la Manada, el máh generoso de loh loa! ¡Alabado sea Gonk!', 28153),
(160922, 'esES', '¡Compañeroh Zandalari! ¡El poderoso Krag\'wa ha regresado! ¡Venid a loh ehcaloneh de Dazar\'alor pa rendir tributo al gran guardián!', '¡Compañeroh Zandalari! ¡El poderoso Krag\'wa ha regresado! ¡Venid a loh ehcaloneh de Dazar\'alor pa rendir tributo al gran guardián!', 28153),
(160921, 'esES', 'Muchoh me han dicho: \"¿Krag\'wa? ¿El gran sapo? ¡Ese loa eh un mito! ¡Una ficción!\".', 'Muchoh me han dicho: \"¿Krag\'wa? ¿El gran sapo? ¡Ese loa eh un mito! ¡Una ficción!\".', 28153),
(160920, 'esES', '¡El gran guardián ofrece su protección! ¡Alabado sea Krag\'wa!', '¡El gran guardián ofrece su protección! ¡Alabado sea Krag\'wa!', 28153),
(160919, 'esES', 'Bwonsamdi noh observa a todoh. ¡Sed dignoh de su bendición, hermanoh y hermanah!', 'Bwonsamdi noh observa a todoh. ¡Sed dignoh de su bendición, hermanoh y hermanah!', 28153),
(160918, 'esES', 'Seguro que lo sabéih todo de Bwonsamdi. Pensáih: \"Sí, eh el loa de la muerte\".', 'Seguro que lo sabéih todo de Bwonsamdi. Pensáih: \"Sí, eh el loa de la muerte\".', 28153),
(160917, 'esES', '¡Loh ehpírituh ehtán con nosotroh! Venid a loh ehcaloneh de Dazar\'alor pa alabar a quien guarda a nuehtroh muertoh. ¡Dad graciah a Bwonsamdi!', '¡Loh ehpírituh ehtán con nosotroh! Venid a loh ehcaloneh de Dazar\'alor pa alabar a quien guarda a nuehtroh muertoh. ¡Dad graciah a Bwonsamdi!', 28153),
(160916, 'esES', 'El barco ehtá en lah Ihlah del Eco. Seguro que vuelve pronto con nosotroh.', '', 28153),
(160915, 'esES', '', 'No le hagas caso a la pizarra. No está acabada.', 28153),
(160914, 'esES', 'El barco acaba de irse. Va de camino a lah Ihlah del Eco. Volverá pronto.', '', 28153),
(160913, 'esES', '¡Compañeroh Zandalari! Venid a loh ehcaloneh de Dazar\'alor pa oír la sabiduría del Rey de loh Felinoh, Condena de la Presa, Señor de lah Behtiah. ¡Alabado sea Kimbul!', '¡Compañeroh Zandalari! Venid a loh ehcaloneh de Dazar\'alor pa oír la sabiduría del Rey de loh Felinoh, Condena de la Presa, Señor de lah Behtiah. ¡Alabado sea Kimbul!', 28153),
(160912, 'esES', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 'Oh doy lah palabrah de mi loa. Así habló a suh seguidoreh:', 28153),
(160911, 'esES', '¡La Condena de la Presa bendice vuehtrah caceríah! ¡Marchad!', '¡La Condena de la Presa bendice vuehtrah caceríah! ¡Marchad!', 28153),
(160910, 'esES', '¡Deleitaoh con la bendición de Akunda!', '¡Deleitaoh con la bendición de Akunda!', 28153),
(160909, 'esES', 'Compartiré con vosotroh la sabiduría de Akunda. Eh el loa de lah tormentah, de loh nuevoh comienzoh.', 'Compartiré con vosotroh la sabiduría de Akunda. Eh el loa de lah tormentah, de loh nuevoh comienzoh.', 28153),
(160908, 'esES', '¡Se acerca una tormenta! Dejad que la lluvia limpie vuehtrah penah, hermanoh y hermanah. ¡Venid a loh ehcaloneh de Dazar\'alor pa alabar a Akunda!', '¡Se acerca una tormenta! Dejad que la lluvia limpie vuehtrah penah, hermanoh y hermanah. ¡Venid a loh ehcaloneh de Dazar\'alor pa alabar a Akunda!', 28153),
(160907, 'esES', 'Pero si ehtá aquí, colega. Sube a bordo anteh de que zarpe.', '', 28153),
(160906, 'esES', '¡$gUn verdadero:Una verdadera; fan! ¡Qué bien! Conocerme tiene que ser impactante para ti. No tengas vergüenza, soy solo un aventurero cualquiera, como tú. Menos en lo de que soy un escritor galardonado e increíblemente rico con fans que cruzan océanos solo por tener la oportunidad de conocerme.\n\nAquí está tu libro. Seguro que será un tesoro para ti.', '', 28153),
(160905, 'esES', '¡Día nuevo, cerveza nueva! ¿Ya has probado algo excepcionalmente delicioso?', '', 28153),
(160904, 'esES', '¿Eres caballero de la Muerte? ¡Siempre he querido conocer a uno!\n\n¿Cómo es la no-muerte? ¿Querías ser caballero de la Muerte? Yo sí. ¿Dónde me apunto?', '', 28153),
(160903, 'esES', '¿Me harías el favor de firmarme el libro?', '¿Me harías el favor de firmarme el libro?', 28153),
(160902, 'esES', 'Mi última obra es verdaderamente magistral. Una joya literaria, sacada de las profundidades de los mares para deslumbrar y seducir al lector. ¿Has venido a alabarme?', '', 28153),
(160901, 'esES', 'La verdad eh que ahora mihmo no ehtoy seguro. Ehperemoh que la Alianza no lo haya atacado.', '', 28153),
(160900, 'esES', 'No podremos contener a Mythrax mucho tiempo. Mata a Zul mientras aún quede tiempo.', '', 28153),
(160899, 'esES', '¡Me has salvado! ¡Muchas gracias! Tengo una recompensa para ti en alguna parte de esta bolsa.', '', 28153),
(160898, 'esES', 'Cuida de tu ciudad, $ghéroe:heroína;. Yo defenderé el camino norte de estos viles sethrak.', '', 28153),
(160897, 'esES', '', 'Nunca pensé que vería lah calleh de Zuldazar invadidah por ningún enemigo...', 28153),
(160896, 'esES', '', '¿Dónde ehtán lah defensah? ¿Ha dejado la traición de Zul tan débil a Zuldazar que no puede defenderse?\n\nLe metí prisah a Meerah pa llegar a tiempo de avisar a loh guardiah realeh, pero quedan muy pocoh. Tendremoh que defender nosotroh lo que queda.', 28153),
(160895, 'esES', '', 'No te creerías la ruta que tuvimos que tomar para llegar aquí antes que los sethrak. Si tus amigos no contaran con mi ayuda, nunca habrían conseguido atravesar esas montañas a tiempo.\n\nAh, y hemos traído a Akunda y Kimbul. Akunda nos está cubriendo las espaldas y no sé dónde ha ido Kimbul, pero dijo algo de desgarrar al enemigo o algo así.\n\nSolo sé que vimos un MONTÓN de sethrak viniendo hacia aquí. ¡UN MONTÓN!', 28153),
(160894, 'esES', '¿Qué puedes contarnos acerca los movimientos de la Horda en la zona?', '¿Qué puedes contarnos acerca los movimientos de la Horda en la zona?', 28153),
(160893, 'esES', 'Creí que iba a morir. Te lo agradezco, $r. Siguen llamando $r a tu raza, ¿no?', 'Creí que iba a morir. Te lo agradezco, $r. Siguen llamando $r a tu raza, ¿no?', 28153),
(160892, 'esES', '', '¡Con lo grande que eres tienes que beber un montón!', 28153),
(160891, 'esES', 'Déjame ver tu carta de cervezas.', 'Déjame ver tu carta de cervezas.', 28153),
(160890, 'esES', '', '¿Te apetece una cerveza? ¡Tenemos opciones para todos los gustos!', 28153),
(160889, 'esES', 'Vaya, sí que te han durado poco. Si quieres, yo podría proporcionar a tus tropas nuevas armaduras. ¡Totalmente gratis!', '', 28153),
(160888, 'esES', '', 'Usar Disparo con púas también reducirá el tiempo necesario para lanzar Cólera de las bestias de nuevo.', 28153),
(160887, 'esES', '¡Lo preparo lo más rápido que puedo!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160886, 'esES', '', '¡Corta más rápido, Colton! ¡Tenemos clientes hambrientos!', 28153),
(160885, 'esES', 'Usar Disparo con púas también reducirá el tiempo necesario para lanzar Cólera de las bestias de nuevo.', '', 28153),
(160884, 'esES', '¡Vamoh, chica!', '', 28153),
(160883, 'esES', '¿$GLihto:Lihta;?', '', 28153),
(160882, 'esES', '¿Eh hora de jugar, Luna?', '', 28153),
(160881, 'esES', 'Qué suerte tengo de haber encontrado una esposa tan inteligente.', '', 28153),
(160880, 'esES', '', '¡Tengo una sorpresa para ti!', 28153),
(160879, 'esES', '', 'Esto es fascinante, ¿lo has visto?', 28153),
(160878, 'esES', 'Ah, no sé, tal vez busque una buena pareja y siente la cabeza en una pequeña granja en algún sitio...\n\nPero ¿qué te CREES tú que voy a hacer, colega?\n\nVoy a ir a que Cyrus me dé mi dinero, le pagaré una ronda a todo el mundo en Muelle Acogedor y buscaré la siguiente aventura.\n\nEs la única forma de vivir que vale la pena.', '', 28153),
(160877, 'esES', '¿Qué vas a hacer ahora?', '¿Qué vas a hacer ahora?', 28153),
(160876, 'esES', 'Invasiones, golpes de estado, el alzamiento de los viejos dioses... ¡Bah! No voy a dejar este Zócalo hasta que el Viejo Tella me pague lo que me debe.', '', 28153),
(160875, 'esES', 'Ehto no eh nada. Durante la Tercera Guerra presencié la gran danza de loh huesoh de Sendarraíz. Eh lo máh asuhtacionante que he vihto en mi vida.', '', 28153),
(160874, 'esES', 'Si sobrevivo a ehto, prometo no timar a mih clienteh durante al menoh doh... puede que treh semanah.', '', 28153),
(160873, 'esES', '¿Dónde está el barco ahora?', '¿Dónde está el barco ahora?', 28153),
(160872, 'esES', '', 'Mandaré tanta ayuda como pueda, $n.', 28153),
(160871, 'esES', '', 'Vi el rahtro de la Plaga cuando recorrió Zul\'Drak, pero ehte ataque a mi tierra por parte de gente en la que confiábamoh como amigoh...\n\nNormalmente no soy una trol violenta, pero creo que tal vez necesite matar a alguien por ehto.', 28153),
(160870, 'esES', '¡Archidruida, Malfurion necesita tu ayuda en Costa Oscura!', '¡Archidruida, Malfurion necesita tu ayuda en Costa Oscura!', 28153),
(160869, 'esES', '¡Sacerdotisa, necesitamos tu ayuda para detener a la Horda en Río Culebra!', '¡Sacerdotisa, necesitamos tu ayuda para detener a la Horda en Río Culebra!', 28153),
(160868, 'esES', 'Ayudah a la Princesa. Eso eh bueno, sigue así. Dehtruye la amenaza de loh trolh de sangre anteh de que noh consuma a todoh.\n\nLa persona con la que tieneh que hablar ehtá en lah Ruinah de Zul\'jan. Eh la proveedora Lija. Te ayudará con lo que necesiteh.', 'Ayudah a la Princesa. Eso eh bueno, sigue así. Dehtruye la amenaza de loh trolh de sangre anteh de que noh consuma a todoh.\n\nLa persona con la que tieneh que hablar ehtá en lah Ruinah de Zul\'jan. Eh la proveedora Lija. Te ayudará con lo que necesiteh.', 28153),
(160867, 'esES', 'Lo mejor para los intereses de la Jefa de Guerra es que hagas todo lo posible para garantizar que los Zandalari y su flota se unan a la Horda. Para conseguirlo, sigue apoyando a Talanji. Si eso supone destruir hasta el último de los trols de sangre, que así sea.\n\nEncontrarás a su emisaria en Nazmir, en las Ruinas de Zul\'jan. Busca a la proveedora Lija y que la Dama Oscura vele por ti.', 'Lo mejor para los intereses de la Jefa de Guerra es que hagas todo lo posible para garantizar que los Zandalari y su flota se unan a la Horda. Para conseguirlo, sigue apoyando a Talanji. Si eso supone destruir hasta el último de los trols de sangre, que así sea.\n\nEncontrarás a su emisaria en Nazmir, en las Ruinas de Zul\'jan. Busca a la proveedora Lija y que la Dama Oscura vele por ti.', 28153),
(160866, 'esES', 'Emisaria de la Expedición de Talanji', 'Emisaria de la Expedición de Talanji', 28153),
(160865, 'esES', '¡En Kul Tiras tienen una cerveza interesante!\n\nEs mucho más sabrosa que las que he encontrado en el continente. ¡Es impresionante lo dedicados que están aquí a su cerveza!', '', 28153),
(160864, 'esES', 'Ve hacia la princesa Talanji y la guardia bélica Rakera.', 'Ve hacia la princesa Talanji y la guardia bélica Rakera.', 28153),
(160863, 'esES', '', '¿Cultoreh de sangre, sethrak, mogu y hahta nuehtro Zul? Echo de menoh loh tiempoh sencilloh en loh que solo intentábamoh dominar el mundo.', 28153),
(160862, 'esES', '', 'Nuestra larga lucha contra la Legión ha terminado, pero la Horda no puede permitirse ningún respiro.', 28153),
(160861, 'esES', 'La Legión ha caído, pero nos enfrentamos a una nueva amenaza. Hemos recibido mensajes preocupantes de nuestros operativos en Orgrimmar. Debemos tratar este asunto. Reúnete conmigo en el Castillo de Ventormenta.', '', 28153),
(160860, 'esES', '¡Estás en El Perrete Grumete! ¿Quieres comprarle algo a tu pequeñín o pequeñina?', '', 28153),
(160859, 'esES', '', 'Todo empezó con tres gatos. ¡Tres gatos! ¡Un número razonable!\n\nPero entonces una amiga se mudó y tuvo que buscarle un hogar al suyo. Luego encontré otro en la calle que parecía triste. Murió un vecino. Una tuvo gatitos. Otros dos... ¡aparecieron sin más!\n\nLos quiero a todos y cada uno de ellos. No cambiaría a ninguno por nada en el mundo.', 28153),
(160858, 'esES', '¡Bien! ¡Otra vez!', '', 28153),
(160857, 'esES', 'Ninguno de estos cachorros es mío. Perdí a mi querido Willoughby hace muchos años. Por eso vengo aquí cada día, para encontrar a los que están más solos. Los acaricio y les digo lo buenos perros que son.', '', 28153),
(160856, 'esES', 'Haría lo que fuera por mi perro.', '', 28153),
(160855, 'esES', 'Este es mi perro, Cubo. ¡Es muy bueno escarbando!\n\nLo he colocado aquí arriba para acariciarlo mejor. Creo que simplemente está contento de estar aquí.', '', 28153),
(160854, 'esES', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Asegúrate de que haya al menos un jugador en cada una de las áreas que sean objetivos de |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Asegúrate de que haya al menos un jugador en cada una de las áreas que sean objetivos de |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', 28153),
(160853, 'esES', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t ¡Tienes más de 50 acumulaciones de |cFFFF0000|Hspell:272146|h[Aniquilación]|h|r! ¡Busca fragmentos de esencia para recuperar tu máximo de salud!', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t ¡Tienes más de 50 acumulaciones de |cFFFF0000|Hspell:272146|h[Aniquilación]|h|r! ¡Busca fragmentos de esencia para recuperar tu máximo de salud!', 28153),
(160852, 'esES', 'He oído que necesitabas ayuda con los ettins.', 'He oído que necesitabas ayuda con los ettins.', 28153),
(160851, 'esES', '¡Por la Alianza!', '', 28153),
(160850, 'esES', 'Me aseguraré de que el rey Anduin sepa de tus actos de heroísmo en el día de hoy. Todos habéis hecho un trabajo excelente.', '', 28153),
(160849, 'esES', 'Y un reconocimiento especial para el señor feudal Falstad y para todo el clan Martillo Salvaje.', '', 28153),
(160848, 'esES', 'Ehtáh lejoh de tu hogar, $r.$b$bPediré a loh ehpírituh que velen por ti mientrah ehtéh en Vol\'dun, pero te aviso de que ya no me hacen caso.', 'Ehtáh lejoh de tu hogar, $r.$b$bPediré a loh ehpírituh que velen por ti mientrah ehtéh en Vol\'dun, pero te aviso de que ya no me hacen caso.', 28153),
(160847, 'esES', 'No hay manera de ehcapar de ehte calor.', 'No hay manera de ehcapar de ehte calor.', 28153),
(160846, 'esES', '¡Alimaña descerebrada! ¡Te cortaré la cabeza!', '¡Alimaña descerebrada! ¡Te cortaré la cabeza!', 28153),
(160845, 'esES', '¿Tú otra vez? Tuve piedad la última vez. ¡Es un error que no pienso repetir!', '¿Tú otra vez? Tuve piedad la última vez. ¡Es un error que no pienso repetir!', 28153),
(160844, 'esES', 'Gracias por rescatarme. Mira, como recompensa proveeré a todo tu ejército de las mejores armas de Industrias Tarque. ¡Por la paz! Salud.', '', 28153),
(160843, 'esES', 'Y a mí... que me daban miedo... los tiburones...', 'Y a mí... que me daban miedo... los tiburones...', 28153),
(160842, 'esES', 'Quiero la revancha... en tierra...', 'Quiero la revancha... en tierra...', 28153),
(160841, 'esES', 'Por... la Horda...', 'Por... la Horda...', 28153),
(160840, 'esES', '¿Dónde... vas a huir...?', '¿Dónde... vas a huir...?', 28153),
(160839, 'esES', 'Así no...', 'Así no...', 28153),
(160838, 'esES', 'Arrástrame... al barco...', 'Arrástrame... al barco...', 28153),
(160837, 'esES', 'Deja que... me hunda...', 'Deja que... me hunda...', 28153),
(160836, 'esES', 'Morir por... restos...', 'Morir por... restos...', 28153),
(160835, 'esES', '¡Ni siquiera necesito pantalones para vencerte!', '¡Ni siquiera necesito pantalones para vencerte!', 28153),
(160834, 'esES', '¡Como atrapar un pez con un arpón!', '¡Como atrapar un pez con un arpón!', 28153),
(160833, 'esES', '¡Este buceo por fin se está poniendo interesante!', '¡Este buceo por fin se está poniendo interesante!', 28153),
(160832, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(160831, 'esES', '¡No vale! ¡Mi equipo está en el barco!', '¡No vale! ¡Mi equipo está en el barco!', 28153),
(160830, 'esES', '¿Qué ha pasado mientras estaba abajo? ¡La Alianza está aquí!', '¿Qué ha pasado mientras estaba abajo? ¡La Alianza está aquí!', 28153),
(160829, 'esES', '¿La Alianza está aquí también?', '¿La Alianza está aquí también?', 28153),
(160828, 'esES', 'Espera, ¿qué haces aquí?', 'Espera, ¿qué haces aquí?', 28153),
(160827, 'esES', '¡No se toca!', '¡No se toca!', 28153),
(160826, 'esES', '¡Fregaré la cubierta con tu sangre!', '¡Fregaré la cubierta con tu sangre!', 28153),
(160825, 'esES', '¡Voy a detener a $geste:esta; $pr!', '¡Voy a detener a $geste:esta; $pr!', 28153),
(160824, 'esES', '¡Deja de hacer lo que sea que estás haciendo!', '¡Deja de hacer lo que sea que estás haciendo!', 28153),
(160823, 'esES', '¿Qué me han traído hoy loh loa?', '¿Qué me han traído hoy loh loa?', 28153),
(160822, 'esES', '¡Aparta las manos de los suministros!', '¡Aparta las manos de los suministros!', 28153),
(160821, 'esES', '¡No dejéis que se acerquen a los cañones!', '¡No dejéis que se acerquen a los cañones!', 28153),
(160820, 'esES', '¡No toques eso!', '¡No toques eso!', 28153),
(160819, 'esES', '¡Aléjate de ahí!', '¡Aléjate de ahí!', 28153),
(160818, 'esES', 'Tírame... por la borda...', 'Tírame... por la borda...', 28153),
(160817, 'esES', 'Malditos seáis... tú y tu rey...', 'Malditos seáis... tú y tu rey...', 28153),
(160816, 'esES', 'Estás $gatrapado:atrapada; aquí... con nosotros...', 'Estás $gatrapado:atrapada; aquí... con nosotros...', 28153),
(160815, 'esES', 'Por... mi Jefa de Guerra...', 'Por... mi Jefa de Guerra...', 28153),
(160814, 'esES', 'Perro de la Alianza...', 'Perro de la Alianza...', 28153),
(160813, 'esES', 'Esto tenía... que ser... fácil...', 'Esto tenía... que ser... fácil...', 28153),
(160812, 'esES', 'Nathanos... acabará... con vosotros...', 'Nathanos... acabará... con vosotros...', 28153),
(160811, 'esES', 'Por... la Reina... alma en pena...', 'Por... la Reina... alma en pena...', 28153),
(160810, 'esES', 'Sabía que había olido $gun asqueroso:una asquerosa; $pr.', 'Sabía que había olido $gun asqueroso:una asquerosa; $pr.', 28153),
(160809, 'esES', '¡Te rajaré las entrañas!', '¡Te rajaré las entrañas!', 28153),
(160808, 'esES', '¡Que alguien avise a Nathanos!', '¡Que alguien avise a Nathanos!', 28153),
(160807, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(160806, 'esES', '¡Por la Dama Oscura!', '¡Por la Dama Oscura!', 28153),
(160805, 'esES', '¡A por ellos!', '¡A por ellos!', 28153),
(160804, 'esES', '¡Sal de nuestro barco!', '¡Sal de nuestro barco!', 28153),
(160803, 'esES', '¡La Alianza está aquí!', '¡La Alianza está aquí!', 28153),
(160802, 'esES', 'Dreven acabará... contigo...', 'Dreven acabará... contigo...', 28153),
(160801, 'esES', 'Solo un poco... más... de poder...', 'Solo un poco... más... de poder...', 28153),
(160800, 'esES', 'Soy... invencible...', 'Soy... invencible...', 28153),
(160799, 'esES', 'Te maldigo...', 'Te maldigo...', 28153),
(160798, 'esES', 'El Príncipe de Sangre... te... dejará $gseco:seca;...', 'El Príncipe de Sangre... te... dejará $gseco:seca;...', 28153),
(160797, 'esES', '¡No!', '¡No!', 28153),
(160796, 'esES', '¡Sigue así! Solo un poco más...', '', 28153),
(160795, 'esES', 'Una... última... gota...', 'Una... última... gota...', 28153),
(160794, 'esES', 'Solo... una... más...', 'Solo... una... más...', 28153),
(160793, 'esES', 'Llorarás antes de que haya acabado contigo.', 'Llorarás antes de que haya acabado contigo.', 28153),
(160792, 'esES', '¡Solo eres sustento para los San\'layn!', '¡Solo eres sustento para los San\'layn!', 28153),
(160791, 'esES', '¡Eso es! ¡Creo que está funcionando!', '', 28153),
(160790, 'esES', '$gUn:Una; $pr... Qué curioso.', '$gUn:Una; $pr... Qué curioso.', 28153),
(160789, 'esES', '¡Te arrancaré la carne de los huesos!', '¡Te arrancaré la carne de los huesos!', 28153),
(160788, 'esES', 'Mira lo que ha venido a parar a nuestro barco.', 'Mira lo que ha venido a parar a nuestro barco.', 28153),
(160787, 'esES', 'Sentirás un dolor exquisito.', 'Sentirás un dolor exquisito.', 28153),
(160786, 'esES', 'Quiero oírte gritar.', 'Quiero oírte gritar.', 28153),
(160785, 'esES', 'Acércate, $pr...', 'Acércate, $pr...', 28153),
(160784, 'esES', '$gUn:Una; $c, ¿eh? ¿Qué te trae por aquí?\n\nAh, será la batalla inminente, supongo. Bueno, esta charla me ha dejado la garganta seca.\n\nSi me disculpas, debo continuar con mis preparativos.', '', 28153),
(160783, 'esES', 'La batalla nos espera. $gUn:Una; $c como tú nos vendría bien en nuestras filas.', '', 28153),
(160782, 'esES', 'Ven con nosotros a un lugar seguro. No te haremos daño.', 'Ven con nosotros a un lugar seguro. No te haremos daño.', 28153),
(160781, 'esES', '¡Por favor, no me lleves!', '¡Por favor, no me lleves!', 28153),
(160780, 'esES', 'La Horda... ¿aquí?', 'La Horda... ¿aquí?', 28153),
(160779, 'esES', '¡Vete! Es demasiado tarde...', '¡Vete! Es demasiado tarde...', 28153),
(160778, 'esES', '¡Este debería ser un tiempo de celebración! Sin embargo, este mundo cambiante a menudo nos lo pone difícil. Puedo ayudarte, si quieres unirte a las festividades.', '', 28153),
(160777, 'esES', '<Darle un puñetazo>.', '<Darle un puñetazo>.', 28153),
(160776, 'esES', 'Roko te manda recuerdos.', 'Roko te manda recuerdos.', 28153),
(160775, 'esES', '¿Te acuerdas de mí?', '¿Te acuerdas de mí?', 28153),
(160774, 'esES', '¿Qué asuntoh tieneh con loh exiliadoh y loh dehpojoh de lah arenah? Vol\'dun eh donde mandamoh a morir a loh alborotadoreh.\n\nAun así, ereh de fiar. Bien, ehcucha con atención. Tieneh que buhcar a una vulpera, la acaparadora Jena. Puede que la encuentreh en un lugar conocido como el Ehcondrijo Vulpera.', '¿Qué asuntoh tieneh con loh exiliadoh y loh dehpojoh de lah arenah? Vol\'dun eh donde mandamoh a morir a loh alborotadoreh.\n\nAun así, ereh de fiar. Bien, ehcucha con atención. Tieneh que buhcar a una vulpera, la acaparadora Jena. Puede que la encuentreh en un lugar conocido como el Ehcondrijo Vulpera.', 28153),
(160773, 'esES', '¿Has venido a mendigar como el resto de la chusma apestosa de fuera?$b$bNo pierdas el tiempo. Estoy aquí para hacer negocios.', '¿Has venido a mendigar como el resto de la chusma apestosa de fuera?$b$bNo pierdas el tiempo. Estoy aquí para hacer negocios.', 28153),
(160772, 'esES', '¿Por qué te interesan? Son una panda de carroñeros y exiliados. ¿Es que la Dama Oscura te ha pedido que hagas que se unan a nosotros?\n\nEn cualquier caso, prueba en el Escondrijo Vulpera, en Vol\'dun. Allí hay una raposa a la que llaman acaparadora Jena. Quizás ella pueda ayudarte.', '¿Por qué te interesan? Son una panda de carroñeros y exiliados. ¿Es que la Dama Oscura te ha pedido que hagas que se unan a nosotros?\n\nEn cualquier caso, prueba en el Escondrijo Vulpera, en Vol\'dun. Allí hay una raposa a la que llaman acaparadora Jena. Quizás ella pueda ayudarte.', 28153),
(160771, 'esES', 'Emisaria Voldunai', 'Emisaria Voldunai', 28153),
(160770, 'esES', 'En mi opinión, los del Despertar de la Tormenta son buena gente. Si quieres hablar con uno de sus líderes, deberías ir a Brennadam, que está en el Valle Canto Tormenta.\n\nBusca allí a la hermana Lilyana. Ella puede ayudarte con cualquier asunto relacionado con el Despertar.', 'En mi opinión, los del Despertar de la Tormenta son buena gente. Si quieres hablar con uno de sus líderes, deberías ir a Brennadam, que está en el Valle Canto Tormenta.\n\nBusca allí a la hermana Lilyana. Ella puede ayudarte con cualquier asunto relacionado con el Despertar.', 28153),
(160769, 'esES', 'Emisaria del Despertar de la Tormenta', 'Emisaria del Despertar de la Tormenta', 28153),
(160768, 'esES', '<Quédate un rato y escucha>.', '<Quédate un rato y escucha>.', 28153),
(160767, 'esES', 'Je, parece que hasta hemos asustado a la tormenta.', '', 28153),
(160766, 'esES', 'Esta guerra ha durado demasiado.\n\nLa Alianza dice guiarse por la justicia y la piedad. ¡Sandeces! Rechazan y condenan a todo el que no encaja en su reducida visión del mundo.', '', 28153),
(160765, 'esES', '<Quédate un rato y escucha>.', '<Quédate un rato y escucha>.', 28153),
(160764, 'esES', '', 'Parece que me han vuelto a reclutar para llevar a cabo los planes de otro señor.\n\nHaré lo que haga falta y diré lo que haga falta para vivir un día más.\n\nPero tarde o temprano esta guerra acabará. Debemos estar preparados para lo que pase después.', 28153),
(160763, 'esES', '<Quédate un rato y escucha>.', '<Quédate un rato y escucha>.', 28153),
(160762, 'esES', 'La sutileza y la astucia son nuestras mejores armas en esta guerra, $n.', '', 28153),
(160761, 'esES', '<Quédate un rato y escucha>.', '<Quédate un rato y escucha>.', 28153),
(160759, 'esES', '¡Si tienes a los Martillo Salvaje de tu lado, no tienes más que mirar al cielo cuando estés en apuros!', '', 28153),
(160758, 'esES', 'La campaña progresa rápidamente, $n. Desde luego, has cumplido con tu papel.', '', 28153),
(160757, 'esES', 'Cómo se reirá la Dama Oscura... ¡cuando le diga que has muerto en una trampa como la alimaña que eres!', '', 28153),
(160756, 'esES', 'Llevo tiempo queriendo poner fin a tu molesta existencia.', '', 28153),
(160755, 'esES', 'Acabemos con esto.', '', 28153),
(160754, 'esES', '¿Orden de Ascuas? ¿Qué es eso? Suena de lo más misterioso.\n\nResulta que oí hablar acerca de alguien que hay allá en Puesto de Arom, Drustvar, hacia el oeste. Es el intendente Alcorn. Si me preguntas sobre esto es que debes de saber cómo llegar allí. Mira, dame tu mapa y te señalaré la ubicación.', '¿Orden de Ascuas? ¿Qué es eso? Suena de lo más misterioso.\n\nResulta que oí hablar acerca de alguien que hay allá en Puesto de Arom, Drustvar, hacia el oeste. Es el intendente Alcorn. Si me preguntas sobre esto es que debes de saber cómo llegar allí. Mira, dame tu mapa y te señalaré la ubicación.', 28153),
(160753, 'esES', 'Las hermanas Hondopantano me pidieron ayuda. El mundo ha asistido a muchos cambios. ¿Por qué íbamos a dejar de divertirnos por eso?', '', 28153),
(160752, 'esES', '¿Qué hace aquí un miembro del Vuelo Bronce?', '¿Qué hace aquí un miembro del Vuelo Bronce?', 28153),
(160751, 'esES', '¿Estás disfrutando de los festejos?', '', 28153),
(160750, 'esES', 'Emisario de la Orden de Ascuas', 'Emisario de la Orden de Ascuas', 28153),
(160749, 'esES', 'Sí. Martillo Salvaje, guardad vuestros martillos de tormenta y mantened un compás de espera hasta que dé la orden.', '', 28153),
(160748, 'esES', '', 'No tan cerca todavía. Quiero observar y formular un plan antes de que sepan que estamos aquí.', 28153),
(160747, 'esES', 'Ahí están, General. Dos buques de guerra justo enfrente. Renegados.', '', 28153),
(160746, 'esES', 'Ximo dice que no debo hablar con loh clienteh.', '', 28153),
(160745, 'esES', '', 'Muere con honor, Grommash Grito Infernal.', 28153),
(160744, 'esES', '¡Que su sacrificio no sea en vano! ¡Vamos! ¡YA!', '', 28153),
(160743, 'esES', '', '¡No! ¡Permaneceré junto a mi Jefe de Guerra!', 28153),
(160742, 'esES', '¡Agrupaos enseguida! ¡Solo tenemos una oportunidad!', '', 28153),
(160741, 'esES', '¡Por los Mag\'har! ¡Por Draenor! ¡Lok\'tar ogar!', '', 28153),
(160740, 'esES', '', 'Conseguí hacerme con unas cuantas cajas de provisiones antes de irme. Puedes quedarte algunas. ¡Necesitarás toda tu fuerza!', 28153),
(160739, 'esES', '', 'Mis hermanos y hermanas han ido demasiado lejos. Nuestro deber es arreglar esto.', 28153),
(160738, 'esES', '', 'Tenemos catres, por si quieres descansar. No son gran cosa, pero es lo que hay.', 28153),
(160737, 'esES', 'Geya\'rah, saca a todo el mundo de aquí. Ya. Sin preguntas.', '', 28153),
(160736, 'esES', '<Grommash baja la voz para que solo los Mag\'har lo oigan>.', '', 28153),
(160735, 'esES', '', 'Me apena perder a un viejo amigo, Grommash, pero... como quieras. Lo haremos a tu manera.', 28153),
(160734, 'esES', '¿Cómo puedes estar tan ciega, Yrel? Es la Luz la que ha condenado este mundo.', '', 28153),
(160733, 'esES', '', 'Tu gente le está arrancando la vida a este mundo... y está convirtiendo la tierra en un páramo.', 28153),
(160732, 'esES', '', 'He venido a ofrecerte una última oportunidad de abrazar la Luz.', 28153),
(160731, 'esES', 'Alta Exarca. Un honor poco común.', '', 28153),
(160730, 'esES', '', 'Grommash Grito Infernal. Cuánto tiempo.', 28153),
(160729, 'esES', '', '¡Debemos hacerlo! Nuestro destino NO es sucumbir a esta corrupción.', 28153),
(160728, 'esES', '¡El barco hacia Kul Tiras acaba de llegar! ¡Todos a bordo para ir a Boralus!', '¡El barco hacia Kul Tiras acaba de llegar! ¡Todos a bordo para ir a Boralus!', 28153),
(160727, 'esES', '¡Son demasiados! ¡No podremos defender este frente eternamente!', '', 28153),
(160726, 'esES', '¡$n, sube a la torre y acribilla a los vinculados a la Luz!', '', 28153),
(160725, 'esES', '¡Señora Suprema, Eitrigg, defended aquí el frente conmigo!', '', 28153),
(160724, 'esES', '¡Lantresor, ve lo más rápido que puedas! ¡Reúne a todos los orcos que encuentres y tráelos aquí!', '', 28153),
(160723, 'esES', '...', '', 28153),
(160722, 'esES', '¿Todos?', '', 28153),
(160721, 'esES', 'A todos ellos.', '', 28153),
(160720, 'esES', '¿A cuántos nos enfrentamos, Lantresor?', '', 28153),
(160719, 'esES', '¡Jefe de guerra Grito Infernal! ¡Se acerca un ejército!', '', 28153),
(160718, 'esES', '<Vuela a Ventormenta>', '<Vuela a Ventormenta>', 28153),
(160717, 'esES', '', '¡El Incansable acaba de atracar! ¡Todos a bordo para ir a Ventormenta!', 28153),
(160716, 'esES', '¡Señor Supremo! Quebrantarrocas no querer líos con los orcos. Kor\'gall estar en su cueva.', '', 28153),
(160715, 'esES', '¿Ya vuelves a casa? Por suerte para ti, uno de los pocos barcos de la Alianza que nos quedan realiza a menudo el trayecto de aquí a Ventormenta. Solo tienes que ir al pequeño muelle de madera en el extremo sur del Mercado Vientos Alisios.\n\nNos vemos.', '¿Ya vuelves a casa? Por suerte para ti, uno de los pocos barcos de la Alianza que nos quedan realiza a menudo el trayecto de aquí a Ventormenta. Solo tienes que ir al pequeño muelle de madera en el extremo sur del Mercado Vientos Alisios.\n\nNos vemos.', 28153),
(160714, 'esES', 'Barco a Ventormenta', 'Barco a Ventormenta', 28153),
(160713, 'esES', 'Te sorprendería la de reparaciones que he tenido que hacer por aquí. Con toda la magia que usan los Sabiomar, sería lógico que emplearan materiales impermeables.', '', 28153),
(160712, 'esES', '<Vuela a Orgrimmar>', '<Vuela a Orgrimmar>', 28153),
(160711, 'esES', 'Si te soy del todo sincero, jamás me fie realmente de ellos. A ver, ¿tú has visto sus estandartes?', '', 28153),
(160710, 'esES', '¡Los Sabiomar se han vuelto locos!', '', 28153),
(160709, 'esES', '¿Hah ehtado ya en alguno de nuehtroh antroh? ¡Vale la pena visitarloh!', '', 28153),
(160708, 'esES', 'Cuando la embarcación ehtá vacía, me relajo con loh dedoh de loh pieh en el agua.', '', 28153),
(160707, 'esES', 'Nada como el olor del aire marino.', '', 28153),
(160706, 'esES', 'Vivimoh en una ihla pa que no noh acose el rehto del mundo. ¿Eh que no pueden irse todoh a su casa? No me refiero a ti, claro.', '', 28153),
(160705, 'esES', 'El sonido del remo en el agua eh la mar de relajante.', '', 28153),
(160704, 'esES', 'Siempre tuve predilección por Zeb\'ahari, tan tranquilo y relajante. Lejoh del ajetreo de Dazar\'alor, uno valora realmente la belleza de Zuldazar.', '', 28153),
(160703, 'esES', 'Recuerdo que cuando era un trol chiquitín me encantaban loh viajeh a la cohta.', '', 28153),
(160702, 'esES', '¡Cuanto anteh limpien nuehtrah playah, máh contento ehtaré!', '', 28153),
(160701, 'esES', 'Envíame a la Mina de Galson.', 'Envíame a la Mina de Galson.', 28153),
(160700, 'esES', 'Envíame al Aserradero de las Tierras Altas.', 'Envíame al Aserradero de las Tierras Altas.', 28153),
(160699, 'esES', 'Envíame al Castillo de Stromgarde.', 'Envíame al Castillo de Stromgarde.', 28153),
(160698, 'esES', '¿Te llevo?', '', 28153),
(160697, 'esES', '¡Trabajando todos juntos lo tendremos todo limpio y ordenado!', '', 28153),
(160696, 'esES', '¡El cuerpo de ingenieros de seguridad encontrará los problemas!', '', 28153),
(160695, 'esES', '¿Tienes alguna abolladura? ¡Déjamelo a mí!', '', 28153),
(160694, 'esES', '<Toma las notas>.', '<Toma las notas>.', 28153),
(160693, 'esES', '', '\"Tras descubrir finalmente una base adecuada, hemos producido con éxito un compuesto estable.$B$BEn este estado se puede almacenar, transportar o introducir en el proceso de mezcla para obtener una pólvora negra potentísima.$B$BTan segura estoy de su estabilidad que ya se han enviado muestras a Boralus suspendidas dentro de un collar.$B$BDel mismo modo en que las calderas están día y noche mezclando pólvora, continúa también el trabajo en los prototipos de nuevas aplicaciones. El más prometedor por ahora es una pistola que esperamos constituya un regalo apropiado para nuestra estimada presidenta\".$B$B<Las desorganizadas notas detallan varios proyectos y aspiraciones>.', 28153),
(160692, 'esES', 'Potenciando', 'Potenciando', 28153),
(160691, 'esES', '', 'Cuando Zandalar yazca en ruinah, ¡el imperio de los dioseh antiguoh resurgirá!', 28153),
(160690, 'esES', '', 'Luchah en vano... ¡G\'huun será liberado!', 28153),
(160689, 'esES', '', 'Si dehtruyen el último sello, ¡ese monhtruo quedará libre por Azeroth!', 28153),
(160688, 'esES', 'Los de Nazmir y Vol\'dun no están operativos. Último sello en funcionamiento: Zuldazar.', '', 28153),
(160687, 'esES', 'Denominación: G\'huun.', '', 28153),
(160686, 'esES', '', 'Se acabó.', 28153),
(160685, 'esES', '', 'No puedeh seguir huyendo de tuh crímeneh.', 28153),
(160684, 'esES', 'Y tú no pintah nada entre loh reyeh.', '', 28153),
(160683, 'esES', '¿Acaso no lo entiendeh?', '', 28153),
(160682, 'esES', '¿Cómo tenemoh que llamarte?', '', 28153),
(160681, 'esES', 'Esto es terreno sagrado.', '', 28153),
(160680, 'esES', 'Aquí estoy para ayudarte.', 'Aquí estoy para ayudarte.', 28153),
(160679, 'esES', '', 'Aunque estos días han estado marcados por la pérdida, seguimos adelante.', 28153),
(160678, 'esES', '¡No olvideh que el lado mojado va abajo!', '', 28153),
(160677, 'esES', 'Cielo rojo al anochecer, nada que temer. ¡Cielo rojo en la alborada, cuidado que el tiempo se enfada!', '', 28153),
(160676, 'esES', 'El barco ehtá seguro en el puerto..., pero ¿qué tiene eso de divertido?', '', 28153),
(160675, 'esES', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t ¡Mythrax empieza a lanzar |cFFFF0000|Hspell:274113|h[Haz de desintegración]|h|r!', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t ¡Mythrax empieza a lanzar |cFFFF0000|Hspell:274113|h[Haz de desintegración]|h|r!', 28153),
(160674, 'esES', 'Bien hecho, $p. Bien hecho, Shandris.', '', 28153),
(160673, 'esES', 'Xibala', 'Xibala', 28153),
(160672, 'esES', 'Si quieres saber cómo fabricarte tu equipo de un modo más eficaz, no busques más. Tengo lo que necesitas.', '', 28153),
(160671, 'esES', 'Los Martillo Salvaje hablarán de esta misión durante años... Pero de momento me apetece una pinta.', '', 28153),
(160670, 'esES', '', 'Mantendremos vigilados a esos sethrak de ahí abajo. ¡Cuenta con nosotros!', 28153),
(160669, 'esES', '¡Eres lo más!', '¡Eres lo más!', 28153),
(160668, 'esES', '¡Vuélalos otra vez!', '¡Vuélalos otra vez!', 28153),
(160667, 'esES', '¡Cuando crezca seré como tú!', '¡Cuando crezca seré como tú!', 28153),
(160666, 'esES', '¡Eres un héroe!', '¡Eres un héroe!', 28153),
(160665, 'esES', 'Si quieres saber cómo fabricarte tu equipo de un modo más eficaz, no busques más. Tengo lo que necesitas.', '', 28153),
(160664, 'esES', '|TInterface\\Icons\\70_inscription_vantus_rune_light:20|t¡%s crea un |cFFFF0000|Hspell:267905|h[Resguardo de refuerzo]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', 28153),
(160663, 'esES', '', '¡Maldita sea esta horrible Luz!', 28153),
(160662, 'esES', '', 'No... Un naaru... ¡Otra vez no!', 28153),
(160661, 'esES', '', 'Y del destino de mis hermanos y hermanas en el Fuerte Sol Eterno. Me temo que ya poco podemos hacer para salvarlos.', 28153),
(160660, 'esES', '¡Hora de irse, héroes! ¡No me pagan para esperar!', '¡Hora de irse, héroes! ¡No me pagan para esperar!', 28153),
(160659, 'esES', 'Magni Barbabronce te espera en Silithus. ¡Deprisa! ¡La misma tierra se alza contra nosotros!', '', 28153),
(160658, 'esES', 'Magni Barbabronce necesita tu ayuda, adalid. Vamos a hablar.', '', 28153),
(160657, 'esES', '¡Tengo que hablar contigo, adalid!', '', 28153),
(160656, 'esES', 'Vamos, adalid, tenemos que hablar. ¡Magni Barbabronce necesita tu ayuda!', '', 28153),
(160655, 'esES', '¡Adalid! Traigo un mensaje urgente de Magni Barbabronce, Portavoz de Azeroth.', '', 28153),
(160654, 'esES', 'Estoy a punto para partir.', 'Estoy a punto para partir.', 28153),
(160653, 'esES', '¿Todo listo para partir?', '¿Todo listo para partir?', 28153),
(160652, 'esES', '', 'Tras abrir una brecha, el dolor se vuelve... soportable. Solo necesito... un momento.', 28153),
(160650, 'esES', '', 'Preparaos...', 28153),
(160649, 'esES', '', '¡Atravesaremos el muro a mi señal!', 28153),
(160648, 'esES', '¡Se ha activado la autodestrucción!', '¡Se ha activado la autodestrucción!', 28153),
(160647, 'esES', 'No, creo que no es así. ¿Lo volvemos a intentar?', '', 28153),
(160646, 'esES', '', 'Mi gente sobrevivirá.', 28153),
(160645, 'esES', 'Estoy a punto para partir.', 'Estoy a punto para partir.', 28153),
(160644, 'esES', '', '¡La Horda pagará por este ataque!', 28153),
(160643, 'esES', '', 'Elune... Sálvanos.', 28153),
(160642, 'esES', '', 'Sirvo a los kaldorei.', 28153),
(160641, 'esES', '', 'Me alegro de que estés con nosotros.', 28153),
(160640, 'esES', '', 'Queda mucho por hacer.', 28153),
(160639, 'esES', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Fuerza vital]|h|r del avatar se refuerza. ¡Sánala!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Fuerza vital]|h|r del avatar se refuerza. ¡Sánala!', 28153),
(160638, 'esES', 'Jinetes de grifos, retiraos y volved a la formación. ¡Aquí ya hemos acabado!', '', 28153),
(160637, 'esES', 'Ya has oído al General, Alapresta. ¡Llévanos de vuelta a Boralus!', '', 28153),
(160636, 'esES', '', 'Listos para partir, Falstad.', 28153),
(160635, 'esES', '¡¿La Horda está aquí?! ¡Antes prefiero vérmelas con los tiburones!', '¡¿La Horda está aquí?! ¡Antes prefiero vérmelas con los tiburones!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160634, 'esES', 'Prefiero que se vayan anteh que preparar el plato con prisah. Lah sandíah requieren un movimiento de corte delicado a la par que violento.', '', 28153),
(160633, 'esES', 'Tal vez deba cortarlah con esa lengua tan afilada que tieneh, Grozzak.', '', 28153),
(160632, 'esES', '¡Corto lo máh deprisa que puedo!', '', 28153),
(160631, 'esES', 'Cortar sandíah lleva su tiempo. No molehteh al chef.', '', 28153),
(160630, 'esES', 'Necesito la sandía o se me marcharán loh clienteh.', '', 28153),
(160629, 'esES', 'A lo mejor la cuchilla ehtá roma, amigo mío.', '', 28153),
(160628, 'esES', 'Parece mucho tiempo pa cortar una sandía, Ka\'ro.', '', 28153),
(160627, 'esES', 'Loh clienteh ehperan. ¿Falta mucho?', '', 28153),
(160626, 'esES', 'Mis Martillo Salvaje no podrán entretener a Nathanos y al resto de la Horda mucho más tiempo. ¿$gListo:Lista; para marcharte?', '', 28153),
(160625, 'esES', 'Azeroth será un sitio mejor sin ese Príncipe de Sangre. Has hecho bien, $p.', '', 28153),
(160624, 'esES', 'Pon fin a la pelea.', 'Pon fin a la pelea.', 28153),
(160623, 'esES', 'Hoy habéis hecho mucho por Boralus, héroes. Ahora me toca a mí.', 'Hoy habéis hecho mucho por Boralus, héroes. Ahora me toca a mí.', 28153),
(160622, 'esES', 'Prepárate para saltar, $p. Te llevaré justo sobre el Borrasca Carmesí.', '', 28153),
(160621, 'esES', '', '¿Para qué loa quieres que cree la estatua?', 28153),
(160620, 'esES', 'Puedo llevarte al Borrasca Carmesí, $p. Shandris te espera allí.', '', 28153),
(160619, 'esES', 'Nunca escapará... de las Tierras Contagiadas...', '', 28153),
(160618, 'esES', '¡Thros lo consume todo! ¡Es nuestra!', '', 28153),
(160617, 'esES', 'Me gustaría cambiar al loa representado aquí desde Vol\'dun.', 'Me gustaría cambiar al loa representado aquí desde Vol\'dun.', 28153),
(160616, 'esES', 'Me gustaría cambiar al loa representado aquí desde Nazmir.', 'Me gustaría cambiar al loa representado aquí desde Nazmir.', 28153),
(160615, 'esES', '', 'Iré hacia las afueras y avisaré a los ciudadanos. Tú dirígete al puerto. ¡Nos vemos allí!', 28153),
(160614, 'esES', '', 'Entendido..., Lady Almirante.', 28153),
(160613, 'esES', '', 'Parece que tu bienvenida tendrá que esperar.', 28153),
(160612, 'esES', '¡Adalid! ¡Has vuelto! ¿Qué ha pasado?', '', 28153),
(160611, 'esES', '¡Adalid! Estás desapareciendo de...', '', 28153),
(160609, 'esES', 'Buena suerte.', '', 28153),
(160608, 'esES', 'Yo me quedaré con nuestros guías y seré el faro que te ayude a encontrar el camino de vuelta a la costa.', '', 28153),
(160607, 'esES', 'Espero que encontremos a los que buscamos. Pero ten cuidado, la isla apesta a maldad.', '', 28153),
(160606, 'esES', 'No sé lo que encontraremos en Fin del Destino, adalid.', '', 28153),
(160605, 'esES', '¿Cómo, te habías preocupado? ¡Ja, ja!\n\n<tose>\n\nAh... Aún me duele un poco. Pero me pondré bien.\n\nAdemás, yo ya he hecho mi trabajo, colega.\n\nTú vete con Taelia de vuelta a Boralus a hacer cosas de héroes.', '', 28153),
(160604, 'esES', '', 'Vamos, Amalia. Sigamos con tus lecciones sobre lo que significa ser una Renegada.', 28153),
(160603, 'esES', 'Muéstrame lo que tienes en venta.', 'Muéstrame lo que tienes en venta.', 28153),
(160602, 'esES', 'Estaba buscando provisiones cuando tuve problemas con el motor. Hice un aterrizaje de emergencia en este mismo punto y esperé ayuda durante días.$b$b¿Nunca has sobrevivido en un pantano a base de musgo y ramitas? ¡Yo sí!', '', 28153),
(160601, 'esES', '', 'Alerta a Falstad y únete a mí en el cielo. Volveremos $gjuntos:juntas; a Boralus.', 28153),
(160600, 'esES', '', 'El príncipe de sangre Dreven ha muerto. Debemos actuar antes de que Nathanos y los demás se sobrepongan a la distracción de los Martillo Salvaje.', 28153),
(160599, 'esES', '', 'Anu\'dorini talah... monstruo.', 28153),
(160598, 'esES', 'Viene... Gorak Tul...', '', 28153),
(160597, 'esES', '¡Pagarás por esto!', '', 28153),
(160596, 'esES', '¿Quién se atreve a profanar estos huesos?', '', 28153),
(160595, 'esES', 'Ah, justo igual que mi madre cuando acababa de preparar su famosa tarta.\n\nMuy bien, te mostraré... ¡el trabajo de mi vida!\n\nEstá en un arcón ahí detrás, en el exterior, y es todo tuyo.\n\n¡Espero que haya merecido la pena!', 'Ah, justo igual que mi madre cuando acababa de preparar su famosa tarta.\n\nMuy bien, te mostraré... ¡el trabajo de mi vida!\n\nEstá en un arcón ahí detrás, en el exterior, y es todo tuyo.\n\n¡Espero que haya merecido la pena!', 28153),
(160594, 'esES', '¿Qué tal huelo?', '¿Qué tal huelo?', 28153),
(160593, 'esES', 'Ah, excelente. Pero aun así, yo... eh... esto...', 'Ah, excelente. Pero aun así, yo... eh... esto...', 28153),
(160592, 'esES', 'Les he mandado un mensaje a tus enemigos. En cuanto a esos secretos...', 'Les he mandado un mensaje a tus enemigos. En cuanto a esos secretos...', 28153),
(160591, 'esES', 'Soy yo, tu amigo. ¿Tienes secretos que contarme?', 'Soy yo, tu amiga. ¿Tienes secretos que contarme?', 28153),
(160590, 'esES', '¡No sé de qué me hablas!', '¡No sé de qué me hablas!', 28153),
(160589, 'esES', '¡Hola! Perdona el desorden, no suelo recibir muchas visitas.', '¡Hola! Perdona el desorden, no suelo recibir muchas visitas.', 28153),
(160588, 'esES', '', '¡Dame fuerzas, diosa!', 28153),
(160587, 'esES', '', '¡No! No más artimañas. No más huidas. No pienso seguir esperando para tener justicia.', 28153),
(160586, 'esES', '¡El príncipe de sangre Dreven empieza a lanzar un hechizo para escapar!', '', 28153),
(160585, 'esES', 'Me he cansado de tu pobre concepto de la lucha. No daré más pie a intentos tan patéticos.', '', 28153),
(160584, 'esES', 'Ponte $gcómodo:cómoda;, como si estuvieras en tu casa.', 'Ponte $gcómodo:cómoda;, como si estuvieras en tu casa.', 28153),
(160583, 'esES', 'Podríamos brindar y sonreír juntos, pero mírame: no tengo ni bebida ni piel.', 'Podríamos brindar y sonreír juntos, pero mírame: no tengo ni bebida ni piel.', 28153),
(160582, 'esES', '¡Ay, cielos! No esperaba visitas... ¡No tengo nada que ponerme!', '¡Ay, cielos! No esperaba visitas... ¡No tengo nada que ponerme!', 28153),
(160581, 'esES', '', 'La Alianza nos atacó. Te has perdido toda la diversión, $p.', 28153),
(160580, 'esES', '¡Hola de nuevo! Hemos estado un poco, mmm, ocupados mientras tú estabas ahí abajo.', '', 28153),
(160579, 'esES', 'Fue mejor todavía.', '', 28153),
(160578, 'esES', 'Niñata estúpida. Supe sus nombres al extraer la vida de sus cascarones.', '', 28153),
(160577, 'esES', '¡Alapresta y yo te cubrimos, $p! ¡Estaremos lanzando martillos sin parar a través de los puertos!', '', 28153),
(160576, 'esES', '', 'Me temo que ya es tarde para eso, Amalia. Tenemos visita.', 28153),
(160575, 'esES', '', 'Las fuerzas de lady Valiente son implacables, Nathanos. Deberíamos irnos de aquí lo antes posible.', 28153),
(160574, 'esES', 'Ah, estupendo. Esto no solo beneficiará a la armada Zandalari..., además, perjudicará a la de Kul Tiras.', '', 28153),
(160573, 'esES', 'Hemos logrado recuperar el cetro abisal, Nathanos.', '', 28153),
(160572, 'esES', '¡Lo has conseguido! ¡La cámara está a salvo!', '', 28153),
(160571, 'esES', '¡No! ¡El sello se está rompiendo! Aguanta... Vamos, ¡aguanta!', '', 28153),
(160570, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t No olvides desviar la mirada mientras G\'huun lanza |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t No olvides desviar la mirada mientras G\'huun lanza |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', 28153),
(160569, 'esES', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t ¡Consigue la |cFFFF0404|Hspell:263420|h[matriz de poder]|h|r para activar una |cFFFF0404|Hspell:263482|h[Explosión de recreación]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t ¡Consigue la |cFFFF0404|Hspell:263420|h[matriz de poder]|h|r para activar una |cFFFF0404|Hspell:263482|h[Explosión de recreación]|h|r!', 28153),
(160568, 'esES', 'Zeb\'ahari', 'Zeb\'ahari', 28153),
(160567, 'esES', 'Avísame cuando estés $glisto:lista; para ir al lugar del ritual, $n.', '', 28153),
(160566, 'esES', '', 'Esto no puede ser bueno.', 28153),
(160565, 'esES', '', 'Un momento, ¿qué pasa allí abajo?', 28153),
(160564, 'esES', '', '¿Quería probar sus nuevas armas... o quería algo más?', 28153),
(160563, 'esES', '', 'No lo entiendo... ¿Por qué contrataría lady Gobernalle a unos piratas para atacar la Puerta de Daelin?', 28153),
(160562, 'esES', 'Ve con honor. Por la Horda.', '', 28153),
(160561, 'esES', 'La próxima vez que venga a visitarte, será hora de atacar Boralus, la capital de Kul Tiras.', '', 28153),
(160560, 'esES', 'Hemos reunido todas las piezas que necesitamos.', '', 28153),
(160558, 'esES', 'Partamos, pues. Dile a Velapastrosa que aquí ya hemos acabado.', '', 28153),
(160557, 'esES', 'Será mejor que nos movamos antes de que vuelvan. No podemos arriesgarnos a que descubran nuestras últimas adquisiciones.', '', 28153),
(160556, 'esES', 'La Alianza atacó mientras tú estabas bajo el agua, $p. Pudimos rechazarlos, pero nos destruyeron el otro barco.', '', 28153),
(160555, 'esES', '', 'Sí, incluso a mí.', 28153),
(160554, 'esES', '', '¿Incluso a ti?', 28153),
(160553, 'esES', '', 'Date tiempo, Stone. A todos nos cuesta acostumbrarnos a la vida tras la muerte.', 28153),
(160552, 'esES', '', 'Sé que jamás me aceptarían... así, pero no puedo volverme contra mi gente.', 28153),
(160551, 'esES', '', 'No puedo hacerlo, Lilian.', 28153),
(160550, 'esES', 'Como desees.', '', 28153),
(160549, 'esES', 'Excelente. $p y tú id a hablar con Hobart. Le proporcionará a $p los conocimientos y el equipo necesarios para descender al lecho marino.', '', 28153),
(160548, 'esES', 'Seguro que sí. Las mareas no mienten, Valentine está ahí abajo.', '', 28153),
(160547, 'esES', '¿Es aquí?', '', 28153),
(160546, 'esES', 'Sí, mi señor.', '', 28153),
(160545, 'esES', 'Dale las coordenadas a Velapastrosa. Debemos partir de inmediato.', '', 28153),
(160544, 'esES', 'Ese es un tabú del que ya no tienes que preocuparte.', '', 28153),
(160543, 'esES', 'Eso creo, sí. Aunque debo decir que usar el poder de un Sabiomar para recuperar un cadáver perdido en el mar... es...', '', 28153),
(160542, 'esES', 'Zelling. ¿Seguro que conseguirás encontrar el cuerpo del mariscal Valentine?', '', 28153),
(160541, 'esES', '¿Quieres practicar un poco? Bien por ti. La práctica es crucial para la supervivencia. Vale, lo que debes hacer es subir a lo alto del muro que da al Puerto de Boralus.\n\nLa mejor forma de llegar allí es buscar a Joan Weber, la maestra de vuelo del Mercado Vientos Alisios, y bajar las escaleras que verás a su izquierda. Sigue las escaleras y ve al sur, a través del puesto de control. Allí hay un pequeño claro donde entrenan los guardias.', '¿Quieres practicar un poco? Bien por ti. La práctica es crucial para la supervivencia. Vale, lo que debes hacer es subir a lo alto del muro que da al Puerto de Boralus.\n\nLa mejor forma de llegar allí es buscar a Joan Weber, la maestra de vuelo del Mercado Vientos Alisios, y bajar las escaleras que verás a su izquierda. Sigue las escaleras y ve al sur, a través del puesto de control. Allí hay un pequeño claro donde entrenan los guardias.', 28153),
(160540, 'esES', '', 'Tenemos que llegar a Boralus. ¡Hay que avisar a la Lady Almirante!', 28153),
(160539, 'esES', '', 'Iré a informar al teniente. Reúnete conmigo en Alto del Vigía cuando hayas terminado.', 28153),
(160538, 'esES', '', 'Aunque podrían volver... Y si deciden traer esas armas para atacar Boralus...', 28153),
(160537, 'esES', '', '¡Démonos prisa!', 28153),
(160536, 'esES', '', 'Mensaje urgente de Nathanos. Los Valiente han desembarcado en Puerto Saqueo.', 28153),
(160535, 'esES', '', 'Usa Disparo con púas para atacar al muñeco-diana.', 28153),
(160534, 'esES', 'Usa Disparo con púas para atacar al muñeco-diana.', '', 28153),
(160533, 'esES', '', 'El olor de la sangre pone a tu mascota como loca y te otorga enfoque para tus otras facultades.', 28153),
(160532, 'esES', 'El olor de la sangre pone a tu mascota como loca y te otorga enfoque para tus otras facultades.', '', 28153),
(160531, 'esES', '', 'También puedes atacar a tus enemigos con un Disparo con púas y provocar daño de sangrado en el tiempo.', 28153),
(160530, 'esES', '¡Tu linterna ha atraído a un tiburón ballena!', '¡Tu linterna ha atraído a un tiburón ballena!', 28153),
(160529, 'esES', '', '¿Has visto eso? ¡Lo hemos conseguido!', 28153),
(160528, 'esES', '¿Seguro que quieres volver a invocar a una gárgola en vez de a una Val\'kyr?', '¿Seguro que quieres volver a invocar a una gárgola en vez de a una Val\'kyr?', 28153),
(160527, 'esES', '¿Seguro que quieres aprender a invocar a una Val\'kyr en vez de a una gárgola?', '¿Seguro que quieres aprender a invocar a una Val\'kyr en vez de a una gárgola?', 28153),
(160526, 'esES', 'Parece que se ha ido.', 'Parece que se ha ido.', 28153),
(160525, 'esES', 'Da igual, simplemente le diré a Sylvanas que los mataste... ¡antes de que yo te matara a ti!', '', 28153),
(160524, 'esES', 'El problema de los no-muertos siempre ha sido que no tienen carne en los huesos. Tuve que drenar a tres para juntar al poder de un elfo de la noche.', '', 28153),
(160523, 'esES', 'Notas que algo voluminoso acecha ahí cerca en el agua...', 'Notas que algo voluminoso acecha ahí cerca en el agua...', 28153),
(160522, 'esES', '', 'Esta vez no podrás huir, abominación. Hace mucho que deberías haber muerto.', 28153),
(160521, 'esES', '', 'Antes de morir sabrás el nombre de mis hermanas, monstruo.', 28153),
(160520, 'esES', '', 'Centinela Falia. Centinela Aeolyn. Centinela Lyrias.', 28153),
(160519, 'esES', 'Abre bien los ojos, $n. Este no es un sótano cualquiera. Nos hemos adentrado bastante en Boralus.', '', 28153),
(160518, 'esES', '', 'Recuerda que te vas a adentrar mucho en Boralus. Ve con cuidado.', 28153),
(160517, 'esES', 'Regresemos a Zuldazar.', 'Regresemos a Zuldazar.', 28153),
(160516, 'esES', '¡Lo hemos perdido todo!', '¡Lo hemos perdido todo!', 28153),
(160515, 'esES', '¡Mira! El héroe que nos ayudó a escapar.', '¡Mira! El héroe que nos ayudó a escapar.', 28153),
(160514, 'esES', 'No creo que piensen tenernos aquí de forma indefinida.', 'No creo que piensen tenernos aquí de forma indefinida.', 28153),
(160513, 'esES', '¡Uf! ¡Aquí fuera hay DEMASIADA luz!', '¡Uf! ¡Aquí fuera hay DEMASIADA luz!', 28153),
(160512, 'esES', 'La entrada a la cámara está por aquí. ¡Vamos!', '', 28153),
(160511, 'esES', '¡Lordaeron pertenece a los Renegados!', '¡Lordaeron pertenece a los Renegados!', 28153),
(160510, 'esES', '', 'Suerte que vinimos aquí cuando lo hicimos. Thorgen no habría sobrevivido aquí mucho tiempo sin refuerzos..., pese a que el enano pueda decir lo contrario.', 28153),
(160509, 'esES', 'Has vuelto. ¿A punto para volver a descender?', '', 28153),
(160508, 'esES', 'Quiero volver a invocar a una gárgola, en vez de a una Val\'kyr, con mi hechizo Invocar gárgola.', 'Quiero volver a invocar a una gárgola, en vez de a una Val\'kyr, con mi hechizo Invocar gárgola.', 28153),
(160507, 'esES', 'Quiero aprender a invocar a una Val\'kyr en vez de a una gárgola con mi hechizo Invocar gárgola.', 'Quiero aprender a invocar a una Val\'kyr en vez de a una gárgola con mi hechizo Invocar gárgola.', 28153),
(160506, 'esES', '¿La Horda? ¡Llévate lo que quieras, pero perdóname la vida!', '', 28153),
(160505, 'esES', '¡Oye, devuelve eso!', '', 28153),
(160504, 'esES', '<Recoge el cuerpo de Derek Valiente>', '<Recoge el cuerpo de Derek Valiente>', 28153),
(160503, 'esES', '<Recoge el cuerpo del mariscal Valentine>.', '<Recoge el cuerpo del mariscal Valentine>.', 28153),
(160502, 'esES', 'Mil Almas sE alimenTan eN la Sombra, grItan, Claman y Braman eN la osCuridad, prOnto te Unirás a ellas, ¡y Con ellas sufrIrás pOr tOda la eternidad!', 'Mil Almas sE alimenTan eN la Sombra, grItan, Claman y Braman eN la osCuridad, prOnto te Unirás a ellas, ¡y Con ellas sufrIrás pOr tOda la eternidad!', 28153),
(160501, 'esES', '', '¡Las tropas de la Horda avanzan hacia Lor\'danel! Adalid, ¡a mí!', 28153),
(160500, 'esES', '', '¡A por él! ¡Atácalo con una mascota de duelo!', 28153),
(160499, 'esES', '', '¡Toma estrellas, chivo malo!', 28153),
(160498, 'esES', '', 'Ah, ¡sé muy bien qué hacer contigo!', 28153),
(160497, 'esES', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Valiente\n\nPríncipe heredero de Kul Tiras', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Valiente\n\nPríncipe heredero de Kul Tiras', 28153),
(160496, 'esES', '', '¡Tu infecta magia de sangre no te protegerá, Dreven!', 28153),
(160495, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMariscal M. Valentine\n\nCapitán del Orgullo de Tiragarde\nMariscal de la Tercera Flota de Kul Tiras', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMariscal M. Valentine\n\nCapitán del Orgullo de Tiragarde\nMariscal de la Tercera Flota de Kul Tiras', 28153),
(160494, 'esES', 'No hace falta que subraye la importancia de esta misión, $n. La Dama Oscura depende de nosotros para que se cumpla su voluntad.', '', 28153),
(160493, 'esES', '', 'Atacaremos $gjuntos:juntas; al príncipe de sangre Dreven. No habrá piedad ni escapatoria.', 28153),
(160492, 'esES', 'Habla conmigo cuando quieras empezar.', '', 28153),
(160491, 'esES', '¡Sí! Es el buque insig... Ah, no, espera... Es solo una mancha en el catalejo.', '¡Sí! Es el buque insig... Ah, no, espera... Es solo una mancha en el catalejo.', 28153),
(160490, 'esES', '¿Has visto ya a los de Kul Tiras?', '¿Has visto ya a los de Kul Tiras?', 28153),
(160489, 'esES', '¡La caja de puzles reacciona a la proyección de Yogg-Saron!', '¡La caja de puzles reacciona a la proyección de Yogg-Saron!', 28153),
(160488, 'esES', 'Los Mag\'har están condenados, Geya\'rah, pero yo me he asegurado de que mi clan perdure mientras el tuyo se convierte en polvo.', '', 28153),
(160487, 'esES', '', '|TInterface\\Icons\\Ability_Mage_RayofFrost:20|t¡%s activa los |cFFFF0000|Hspell:268253|h[Haces defensivos de Uldir]|h|r!', 28153),
(160486, 'esES', '', '¡Silencio! ¡Si no te arrodillas, yo misma te obligaré.', 28153),
(160485, 'esES', '¡Eh, échame una mano con estas cuerdas!', '¡Eh, échame una mano con estas cuerdas!', 28153),
(160484, 'esES', '¡No dejes que me coman!', '¡No dejes que me coman!', 28153),
(160483, 'esES', '¡Socorro!', '¡Socorro!', 28153),
(160482, 'esES', 'No eres capaz ni de proteger a los tuyos, hija de lobos. ¿Por qué deberíamos seguirte?', '', 28153),
(160481, 'esES', '', '¿Qué significa esta insurrección, Kor\'gall? Sabes que ahora más que nunca debemos estar unidos.', 28153),
(160480, 'esES', 'Me gustaría elegir a Akunda, el loa de las tormentas.', 'Me gustaría elegir a Akunda, el loa de las tormentas.', 28153),
(160479, 'esES', 'Me gustaría elegir a Kimbul, el señor de las bestias.', 'Me gustaría elegir a Kimbul, el señor de las bestias.', 28153),
(160478, 'esES', 'Me gustaría elegir a Bwonsamdi, loa de la muerte.', 'Me gustaría elegir a Bwonsamdi, loa de la muerte.', 28153),
(160477, 'esES', 'Me gustaría elegir a Krag\'wa el Enorme.', 'Me gustaría elegir a Krag\'wa el Enorme.', 28153),
(160476, 'esES', '', 'Por lo visto el mariscal Valentine entregó nuestro mensaje. La flota de los Valiente ha picado el anzuelo.', 28153),
(160475, 'esES', '', 'Esta avanzada está peligrosamente cerca de la ciudad, pero está bien oculta y nos da una visión perfecta del Trono Dorado.\n\nDesde aquí nuestros espías podrán seguir de cerca los movimientos del rey Rastakhan y de la Horda.', 28153),
(160474, 'esES', 'Ya puedo empezar.', 'Ya puedo empezar.', 28153),
(160473, 'esES', 'Para el ritual de salvoconducto tendremos que colaborar.\n\n¿Estás a punto?', '', 28153),
(160472, 'esES', 'Un tanto... siniestro, ¿no? Supongo que si lo que pretendíamos era captar la atención de lady Valiente...', '', 28153),
(160471, 'esES', '¡Fuego!', '¡Fuego!', 28153),
(160470, 'esES', '¡Llamad a los bomberos!', '¡Llamad a los bomberos!', 28153),
(160469, 'esES', '¡Fuego! ¡Fuego!', '¡Fuego! ¡Fuego!', 28153),
(160468, 'esES', 'No habrá sido fácil. Mantén los ojos abiertos.', 'No habrá sido fácil. Mantén los ojos abiertos.', 28153),
(160467, 'esES', '¿Cómo crees que han accedido a Las Mazmorras?', '¿Cómo crees que han accedido a Las Mazmorras?', 28153),
(160466, 'esES', '¿Hay algo de lo que esa bellaca de Brisaveloz no sea capaz a estas alturas?', '¿Hay algo de lo que esa bellaca de Brisaveloz no sea capaz a estas alturas?', 28153),
(160465, 'esES', 'He oído que intentan asesinar al Rey.', 'He oído que intentan asesinar al Rey.', 28153),
(160464, 'esES', 'No pretenderán en serio atacar la ciudad con tan pocos hombres.', 'No pretenderán en serio atacar la ciudad con tan pocos hombres.', 28153),
(160463, 'esES', 'No puedo dejar pasar a nadie. Órdenes del Rey.', 'No puedo dejar pasar a nadie. Órdenes del Rey.', 28153),
(160462, 'esES', 'Nada malo te pasará a ti ni a tu familia. Vuelve a tu casa de inmediato.', 'Nada malo te pasará a ti ni a tu familia. Vuelve a tu casa de inmediato.', 28153),
(160461, 'esES', 'Ya os he dicho todo lo que sé. Volved a vuestras casas.', 'Ya os he dicho todo lo que sé. Volved a vuestras casas.', 28153),
(160460, 'esES', 'Por favor, mi hija vive en el Distrito de Mercaderes. ¡Tengo que llegar hasta ella!', 'Por favor, mi hija vive en el Distrito de Mercaderes. ¡Tengo que llegar hasta ella!', 28153),
(160459, 'esES', '¡Déjame pasar ahora mismo! Exijo hablar con tu superior.', '¡Déjame pasar ahora mismo! Exijo hablar con tu superior.', 28153),
(160458, 'esES', '¿Qué es este escándalo? ¿Sabes la hora que es?', '¿Qué es este escándalo? ¿Sabes la hora que es?', 28153),
(160457, 'esES', '¿Cuántos son? ¿Nos atacan?', '¿Cuántos son? ¿Nos atacan?', 28153),
(160456, 'esES', '¿Crees que el Rey está en peligro?', '¿Crees que el Rey está en peligro?', 28153),
(160455, 'esES', 'Ahora silencio. Entra y escóndete como te enseñé.', 'Ahora silencio. Entra y escóndete como te enseñé.', 28153),
(160454, 'esES', 'Tengo miedo...', 'Tengo miedo...', 28153),
(160453, 'esES', '¿Qué ocurre? ¿Por qué está cerrada la puerta?', '¿Qué ocurre? ¿Por qué está cerrada la puerta?', 28153),
(160452, 'esES', 'No quiero problemas, $r.', 'No quiero problemas, $r.', 28153),
(160451, 'esES', 'Mm. ¿Es normal que estén aquí...?', 'Mm. ¿Es normal que estén aquí...?', 28153),
(160450, 'esES', '¿Es así como cae Ventormenta? Ja. ¡Y yo con asiento en primera fila!', '¿Es así como cae Ventormenta? Ja. ¡Y yo con asiento en primera fila!', 28153),
(160449, 'esES', '¡Guardias! ¡¿Guardias?!', '¡Guardias! ¡¿Guardias?!', 28153),
(160448, 'esES', 'Atrás. No pienso morir aquí.', 'Atrás. No pienso morir aquí.', 28153),
(160447, 'esES', '¡Sí! ¡Eres mi billete para salir de aquí, $r!', '¡Sí! ¡Eres mi billete para salir de aquí, $r!', 28153),
(160446, 'esES', '¡Eh! ¡Ven aquí y déjame salir!', '¡Eh! ¡Ven aquí y déjame salir!', 28153),
(160445, 'esES', '¿Qué ocurre? ¡¿Qué hace aquí la Horda?!', '¿Qué ocurre? ¡¿Qué hace aquí la Horda?!', 28153),
(160444, 'esES', 'Una vez que hayamos hecho salir al guardia más fuerte, nuestro amigo Oculeth abrirá un portal para que $n y Zelling lo crucen y se hagan con el cetro.', '', 28153),
(160443, 'esES', 'En cualquier momento, las fuerzas de élite de los Valiente llegarán aquí e intentarán recuperar el cuerpo de Derek.', '', 28153),
(160442, 'esES', 'Aquí Hannibal es el halcón mensajero más veloz de todo Kul Tiras.', '', 28153),
(160441, 'esES', '¡Se abre una unidad de eliminación de residuos que forma una masa mutada!', '¡Se abre una unidad de eliminación de residuos que forma una masa mutada!', 28153),
(160440, 'esES', '¡Adalid! ¡Azeroth te necesita! Ven a Silithus. Hay algo que tienes que ver.', '', 28153),
(160439, 'esES', 'Esto no tendría que ir así. ¡Yo debería ir ganando!', '', 28153),
(160438, 'esES', 'Centro de entrenamiento de mascotas de duelo de Fortachón. Me gusta cómo suena, ¡y ya estoy un poco más cerca de ganarte!', '', 28153),
(160437, 'esES', 'Debería diversificar mi plantel de mascotas, ahora que lo pienso. Tres mascotas iguales, ¿en qué estaría yo pensando?', '', 28153),
(160436, 'esES', 'Con ese montón de cosas puntiagudas y ese aire chungo que tienen, ¿pensabas que ibas a ganar?', '', 28153),
(160435, 'esES', 'Estos pequeñines son bastante raros, pero no veas cómo arrean. ¿Seguro que quieres esta pelea?', '', 28153),
(160434, 'esES', '', 'No me lo esperaba.', 28153),
(160433, 'esES', '', '¡Aniquilado!', 28153),
(160432, 'esES', '', 'Vaya, esto no me lo esperaba. Pero estaré preparada para ganar la próxima vez que nos veamos.', 28153),
(160431, 'esES', '', 'Como dije ya de entrada, mi equipo es claramente superior.', 28153),
(160430, 'esES', '', 'Antes de empezar, solo quiero recordarte que no te lo tomes muy a pecho cuando mi equipo aniquile al tuyo.', 28153),
(160429, 'esES', 'El olor de la sangre en el agua atraerá a más tiburones.', '', 28153),
(160428, 'esES', '¡Hora de comer, chicos!', '', 28153),
(160427, 'esES', 'Me has ganado, ¿y qué? Seguiré atrapado aquí abajo para toda la eternidad. Por lo menos hoy he podido charlar.', '', 28153),
(160426, 'esES', 'Una persona contra un tiburón, podría estar igualado. ¿Una persona contra tres? De locos.', '', 28153),
(160425, 'esES', 'Si quieres vencer a otros como yo, necesitarás un barco más grande para llevarte esto de aquí.', '', 28153),
(160424, 'esES', '', 'Tu determinación es admirable, pero el resultado de esto ya está decidido.', 28153),
(160423, 'esES', '', '¡Vuelve por donde viniste!', 28153),
(160422, 'esES', '', 'Esto no tenía que pasar, no era lo que decía la profecía.', 28153),
(160421, 'esES', '', 'Necesitas mucho más entrenamiento antes de vértelas con una maestra como yo.', 28153),
(160420, 'esES', '', 'Las extrañas criaturas de esta isla darán para una extraña batalla, supongo.', 28153),
(160419, 'esES', '', 'Vales más como carnaza en un pesquero que luchando para mi equipo.', 28153),
(160418, 'esES', '', '¡Parece que ese ya duerme con los peces!', 28153),
(160417, 'esES', '', 'Siempre hay más peces en el mar, ¿eh? Aunque ahora que lo pienso, tal vez el dicho no vaya sobre eso.', 28153),
(160416, 'esES', '', 'Jamás lo he dudado.', 28153),
(160415, 'esES', '', 'Las criaturas marinas más duras de la zona luchan para mí, no tienes ninguna posibilidad.', 28153),
(160414, 'esES', 'Cada vez que entreno a abejas nuevas pasa lo mismo: se vuelven grandes, fuertes y aparentemente inestables, le pican a algo y mueren.', '', 28153),
(160413, 'esES', '¡Uno a cero a favor de las abejas!', '', 28153),
(160412, 'esES', '¡No! ¡Mis abejas no!', '', 28153),
(160411, 'esES', 'Está claro que las abejas son superiores. Esto lo demuestra.', '', 28153),
(160410, 'esES', 'Pero cuando empecemos esta batalla recuerda que tú te lo has buscado.', '', 28153),
(160409, 'esES', '', 'Ese era el que menos me gustaba del grupo, ¡hora de jugar con los auténticos pesos pesados, prepárate!', 28153),
(160408, 'esES', '', '¡Uno a cero a favor del equipo Fizzie!', 28153),
(160407, 'esES', '', '¡Pero mis mascotas están imbuidas de azerita! ¡Es lo que las mascotas ansían!', 28153),
(160406, 'esES', '', 'No es que me sorprenda: mi equipo es claramente el mejor.', 28153),
(160405, 'esES', '', '¿Crees que tus mascotas tienen alguna posibilidad frente a mi equipo imbuido de azerita? ¡Qué más quisieras!', 28153),
(160404, 'esES', '', 'En Zuldazar hay muchas criaturas, algunas pequeñas y otras enormes. Me he propuesto capturar y entrenar a las criaturas más pequeñas como recordatorio de que las grandes cosas pueden tener un inicio humilde.', 28153),
(160403, 'esES', '', 'Reúnete conmigo en la bodega cuando hayas acabado. Encontraré una forma de destruir la barrera que protege al príncipe de sangre Dreven.', 28153),
(160402, 'esES', '¡El devorador fétido |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t ha usado |cFFFF0000|Hspell:262370|h[Consumir corrupción]|h|rcon éxito! ¡Procura matar a los corpúsculos de corrupción cuando aparezcan!', '¡El devorador fétido |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t ha usado |cFFFF0000|Hspell:262370|h[Consumir corrupción]|h|rcon éxito! ¡Procura matar a los corpúsculos de corrupción cuando aparezcan!', 28153),
(160401, 'esES', 'Shandris te estará esperando a bordo. Buena suerte.', '', 28153),
(160400, 'esES', '¡Buen lanzamiento! Ahora te llevaré al Borrasca Carmesí.', '', 28153),
(160399, 'esES', '', '¡Aaarg!', 28153),
(160398, 'esES', '', '¡SSSSSSSSSÍ! ¡Por nuestras venas fluye la sangre de G\'huun!', 28153),
(160397, 'esES', '', 'La sangre de nuestro maestro..., nuestra carne, ¡nuestras vidas por G\'huun!', 28153),
(160396, 'esES', 'Te pillé, Alapresta. Ningún cañón de la Horda acabará hoy con nosotros.', '', 28153),
(160395, 'esES', '¡Caray! ¡Es genial! ¡Gracias, $gseñor:señora;!', '¡Caray! ¡Es genial! ¡Gracias, $gseñor:señora;!', 28153),
(160394, 'esES', 'Nos... ¿Nos has traído caramelos nuevos? ¿Y mejores?', 'Nos... ¿Nos has traído caramelos nuevos? ¿Y mejores?', 28153),
(160393, 'esES', '¡Eh! ¡Tú eres $gel:la; $r que se había llevado nuestros caramelos!', '¡Eh! ¡Tú eres $gel:la; $r que se había llevado nuestros caramelos!', 28153),
(160392, 'esES', '<Solo quedan unos cuantos envoltorios de caramelos de tu asalto a este cofre... Envoltorios y tu propia vergüenza>.', '<Solo quedan unos cuantos envoltorios de caramelos de tu asalto a este cofre... Envoltorios y tu propia vergüenza>.', 28153),
(160391, 'esES', '<Pon mejores caramelos en el cofre>.', '<Pon mejores caramelos en el cofre>.', 28153),
(160390, 'esES', 'Qué ganas de ahondar en los secretos de Xibala. ¡Este lugar plantea tantas preguntas!\n\n¿Quién es Xibala? ¿Qué es Xibala? ¿Por qué abandonaron los Zandalari este lugar? ¿Qué hace el ojo de Xibala?\n\n¡Bajo la supervisión de la examinadora Tae\'shara, seguro que lo averiguamos!', 'Qué ganas de ahondar en los secretos de Xibala. ¡Este lugar plantea tantas preguntas!\n\n¿Quién es Xibala? ¿Qué es Xibala? ¿Por qué abandonaron los Zandalari este lugar? ¿Qué hace el ojo de Xibala?\n\n¡Bajo la supervisión de la examinadora Tae\'shara, seguro que lo averiguamos!', 28153),
(160389, 'esES', '¿Crees que Astrandis podría presentarme al telemántico jefe Oculeth...?\n\nHe oído tantas cosas sobre él... ¿Crees que me firmará el tabardo?', '¿Crees que Astrandis podría presentarme al telemántico jefe Oculeth...?\n\nHe oído tantas cosas sobre él... ¿Crees que me firmará el tabardo?', 28153),
(160388, 'esES', 'Debo reconocérselo. Tras pasar una pequeña eternidad enclaustrados en un mundo perfecto de vino y sofás de felpa, estos Nocheterna se están adaptando muy bien a los rigores del mundo exterior.\n\n¡Si hasta le he podido enseñar a uno cómo sujetar una pala!', 'Debo reconocérselo. Tras pasar una pequeña eternidad enclaustrados en un mundo perfecto de vino y sofás de felpa, estos Nocheterna se están adaptando muy bien a los rigores del mundo exterior.\n\n¡Si hasta le he podido enseñar a uno cómo sujetar una pala!', 28153),
(160387, 'esES', 'La examinadora Tae\'shara es una mujer de notable paciencia. Digna sucesora de su padre, si este desistiera de su cargo.\n\nPero me pregunto si el Astrandis este no estará poniendo a prueba su prodigiosa tolerancia.', 'La examinadora Tae\'shara es una mujer de notable paciencia. Digna sucesora de su padre, si este desistiera de su cargo.\n\nPero me pregunto si el Astrandis este no estará poniendo a prueba su prodigiosa tolerancia.', 28153),
(160386, 'esES', 'El Relicario no dejó escapar la oportunidad de excavar un yacimiento así. Tenemos suerte de que los trols que viven aquí no se opusieran.', 'El Relicario no dejó escapar la oportunidad de excavar un yacimiento así. Tenemos suerte de que los trols que viven aquí no se opusieran.', 28153),
(160385, 'esES', 'Le ofrecí un pico a un Nocheterna y me miró con incredulidad total.\n\n\"¿Para qué es esto?\", preguntó, como si apenas pudiera hacerse una idea.\n\nSu destreza mágica dice mucho de su capacidad como raza, pero tienen mucho que aprender sobre el mundo. Por suerte los sin\'dorei estamos bien equipados para enseñarles.', 'Le ofrecí un pico a un Nocheterna y me miró con incredulidad total.\n\n\"¿Para qué es esto?\", preguntó, como si apenas pudiera hacerse una idea.\n\nSu destreza mágica dice mucho de su capacidad como raza, pero tienen mucho que aprender sobre el mundo. Por suerte los sin\'dorei estamos bien equipados para enseñarles.', 28153),
(160384, 'esES', 'Los Nocheterna han sido de lo más útiles en esta expedición, pero no como yo esperaba.\n\nEs verdad que aportan cierto nivel de confort a un viaje, lo cual se agradece frente a la habitual dureza del campamento.\n\n<Da un sorbo a un vaso de vino>.', 'Los Nocheterna han sido de lo más útiles en esta expedición, pero no como yo esperaba.\n\nEs verdad que aportan cierto nivel de confort a un viaje, lo cual se agradece frente a la habitual dureza del campamento.\n\n<Da un sorbo a un vaso de vino>.', 28153),
(160383, 'esES', 'No mires, pero creo que ese shal\'dorei tiene cogida su herramienta de peritaje al revés.', 'No mires, pero creo que ese shal\'dorei tiene cogida su herramienta de peritaje al revés.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160382, 'esES', 'Confieso que no sabía en qué me metía cuando accedí a visitar esta tierra extraña.\n\nHace más calor de lo que esperaba. Mucho más. Pero es una valiosa oportunidad para hacer avanzar la causa de la Primera Arcanista y congraciarnos con nuestros nuevos aliados.\n\nSupongo que es una razón tan buena como cualquier otra para aguantarse, vamos.\n\n<Esboza una sonrisa muy forzada>.', 'Confieso que no sabía en qué me metía cuando accedí a visitar esta tierra extraña.\n\nHace más calor de lo que esperaba. Mucho más. Pero es una valiosa oportunidad para hacer avanzar la causa de la Primera Arcanista y congraciarnos con nuestros nuevos aliados.\n\nSupongo que es una razón tan buena como cualquier otra para aguantarse, vamos.\n\n<Esboza una sonrisa muy forzada>.', 28153),
(160381, 'esES', 'Espero que estemos causando una buena impresión a los Zandalari. Fueron muy amables al darnos la oportunidad de estudiar este sitio pese a sus reticencias.', 'Espero que estemos causando una buena impresión a los Zandalari. Fueron muy amables al darnos la oportunidad de estudiar este sitio pese a sus reticencias.', 28153),
(160380, 'esES', '¿Crees que nuestros aliados del Relicario me dejarán usar unos de esos cepillos pequeñitos...?', '¿Crees que nuestros aliados del Relicario me dejarán usar unos de esos cepillos pequeñitos...?', 28153),
(160379, 'esES', 'Nuestros aliados sin\'dorei me han estado deleitando con historias de sus anteriores expediciones. Percibo un tema recurrente en sus repetidos encuentros con enanos.', 'Nuestros aliados sin\'dorei me han estado deleitando con historias de sus anteriores expediciones. Percibo un tema recurrente en sus repetidos encuentros con enanos.', 28153),
(160378, 'esES', '¿Crees que los trols nos permitirán llevarnos una de esas criaturas de cuello largo a Suramar...? ¡A Su\'esh le encantaría un compañero!\n\n¡Tal vez deberías preguntárselo a ellos!', '¿Crees que los trols nos permitirán llevarnos una de esas criaturas de cuello largo a Suramar...? \n\n¡Tal vez deberías preguntárselo a ellos!', 28153),
(160377, 'esES', '<Intenta matar un mosquito que pasa por ahí>.\n\n¡Lo que hay que aguantar para demostrarle a la Horda lo que valemos! ¡Estas condiciones de trabajo son terribles!', '<Intenta matar un mosquito que pasa por ahí>.\n\n¡Lo que hay que aguantar para demostrarle a la Horda lo que valemos! ¡Estas condiciones de trabajo son terribles!', 28153),
(160376, 'esES', '<Se abanica enérgicamente con una mano>.\n\nHasta ahora no había sabido apreciar como es debido el clima de Suramar. Será un alivio volver a casa en cuanto acabe toda esta excavación.', '<Se abanica enérgicamente con una mano>.\n\nHasta ahora no había sabido apreciar como es debido el clima de Suramar. Será un alivio volver a casa en cuanto acabe toda esta excavación.', 28153),
(160375, 'esES', 'He leído acerca de las selvas en nuestra biblioteca, ¡pero ahí no decían nada de este calor sofocante!\n\nSe me pega la ropa. Y hay insectos. ¡Insectos!\n\n¿Por qué querría nadie vivir en un sitio así por voluntad propia?', 'He leído acerca de las selvas en nuestra biblioteca, ¡pero ahí no decían nada de este calor sofocante!\n\nSe me pega la ropa. Y hay insectos. ¡Insectos!\n\n¿Por qué querría nadie vivir en un sitio así por voluntad propia?', 28153),
(160374, 'esES', 'Oh, esoh doh. Ehtán todo el día dihcutiendo en el Gran Sello, en el balcón del ehte.\n\nHacen que se te quiten lah ganah de ir allí. Eso sí, debo decir que coincido con la tauren. En general.', 'Oh, esoh doh. Ehtán todo el día dihcutiendo en el Gran Sello, en el balcón del ehte.\n\nHacen que se te quiten lah ganah de ir allí. Eso sí, debo decir que coincido con la tauren. En general.', 28153),
(160373, 'esES', 'Tú buscas a Cringely y Ulla. Están teniendo una acalorada discusión sobre las políticas de la Jefa de Guerra. Y Cringely tiene razón, claro, pero Ulla es muy tozuda, la pobre.\n\nEs imposible no encontrarlos en el Gran Sello. Están en el balcón oriental que da a la galería.', 'Tú buscas a Cringely y Ulla. Están teniendo una acalorada discusión sobre las políticas de la Jefa de Guerra. Y Cringely tiene razón, claro, pero Ulla es muy tozuda, la pobre.\n\nEs imposible no encontrarlos en el Gran Sello. Están en el balcón oriental que da a la galería.', 28153),
(160372, 'esES', '¡Tengo bacalao! ¡Preparado y listo para comer!', '', 28153),
(160371, 'esES', '¡La pesca del día! ¡Tiburón fresquito, arponeado esta mañana!', '', 28153),
(160370, 'esES', 'Protegednos de la tormenta.', '', 28153),
(160369, 'esES', 'Guiadnos por esas aguas traicioneras que ahora os pertenecen.', '', 28153),
(160368, 'esES', 'Atravesad el velo y pisad tierra firme.', '', 28153),
(160367, 'esES', 'Almas arrastradas por el mar, volved a nosotros.', '', 28153),
(160366, 'esES', 'Somos los faros que os guían al hogar.', '', 28153),
(160365, 'esES', 'Alzamos nuestros faroles sobre las aguas oscuras.', '', 28153),
(160364, 'esES', 'Su sonido os convoca de regreso a casa.', '', 28153),
(160363, 'esES', 'Escuchad las campanas que tañen sobre el canto de la tormenta.', '', 28153),
(160362, 'esES', 'Sobre aguas tranquilas y corrientes raudas, navegad hasta casa.', '', 28153),
(160361, 'esES', 'Con sangre apaciguamos los mares salvajes que os reclamaron.', '', 28153),
(160360, 'esES', 'Dejad el abrazo del abismo y ayudad a vuestros hermanos una vez más.', '', 28153),
(160359, 'esES', 'Almas perdidas en las profundidades, os invocamos.', '', 28153),
(160358, 'esES', 'Que el viento y la marea lleven nuestra plegaria.', '', 28153),
(160357, 'esES', '', '¡Con el mejor jamón de los Reinos del Este! ¡Directamente desde Albergue del Ocaso!', 28153),
(160356, 'esES', '', '¡Salchichas! ¡Recién empaquetadas en Drustvar y Ventormenta!', 28153),
(160355, 'esES', '', '¡Nada mejor que ir dando sorbos a una cerveza exótica mientras paseas por la Fila del Mercado! ¡Y si no te va la cerveza, también he traído té!', 28153),
(160354, 'esES', '', '¡Vendo cerveza! ¡Toneles venidos de Pandaria!', 28153),
(160353, 'esES', '¡Eh! ¡Eh, tú! ¡Sí, tú! Puede que tenga algo de interés para alguien de tu... vocación.', '', 28153),
(160352, 'esES', 'Ahora, más que nunca, la Jefa de Guerra nos necesita atentos y organizados. ¿Qué sacrificará tu hermandad para hacer avanzar la causa de la Horda?', '', 28153),
(160351, 'esES', '', '¡Repollos frescos, de cultivo local!', 28153),
(160350, 'esES', '', '¡Verduras llegadas directamente de las granjas de Canto Tormenta! ¡El mejor maíz que hayas probado!', 28153),
(160349, 'esES', 'No sé dónde está ahora el barco.', 'No sé dónde está ahora el barco.', 28153),
(160348, 'esES', 'El Incansable debería haber salido del muelle de Ventormenta.', 'El Incansable debería haber salido del muelle de Ventormenta.', 28153),
(160347, 'esES', 'El Incansable debería haberse ido de Boralus.', 'El Incansable debería haberse ido de Boralus.', 28153),
(160346, 'esES', 'Si alguna vez necesitas la respuesta a cualquier problema que tenga que ver con zapatos, aquí estoy siempre. ¡Disfruta de tu flamante lustre!', '', 28153),
(160345, 'esES', '¡Marchando un lustrado de zapatos!', '', 28153),
(160344, 'esES', 'Así que ereh $gun:una; profesional. Vale, nunca vienen mal. Si buhcah herramientas de trabajo, ve a ver a un tauren llamado Hanul Ventolera. Lo encontraráh en la Cámara de Sendah Ancehtraleh, una sala que está en la zona ehte del Gran Sello.', 'Así que ereh $gun:una; profesional. Vale, nunca vienen mal. Si buhcah herramientas de trabajo, ve a ver a un tauren llamado Hanul Ventolera. Lo encontraráh en la Cámara de Sendah Ancehtraleh, una sala que está en la zona ehte del Gran Sello.', 28153),
(160343, 'esES', 'Si buscas suministros, no te lo pienses y ve al Gran Sello. Una vez dentro, ve por el este a la Cámara de Sendas Ancestrales. Busca a un tauren llamado Hanul Ventolera. Debería tener todo lo que necesitas.', 'Si buscas suministros, no te lo pienses y ve al Gran Sello. Una vez dentro, ve por el este a la Cámara de Sendas Ancestrales. Busca a un tauren llamado Hanul Ventolera. Debería tener todo lo que necesitas.', 28153),
(160342, 'esES', '¿Pertrechoh? La Horda se trajo loh suyoh propioh. Ve a hablar con la orco Araka, en la Cámara de Sendah Ancehtraleh. Eh una sala que hay en la parte ehte del Gran Sello. Tiene todoh loh pertrechoh que necesitah.', '¿Pertrechoh? La Horda se trajo loh suyoh propioh. Ve a hablar con la orco Araka, en la Cámara de Sendah Ancehtraleh. Eh una sala que hay en la parte ehte del Gran Sello. Tiene todoh loh pertrechoh que necesitah.', 28153),
(160341, 'esES', 'Araka puede ayudarte. Está en la Cámara de Sendas Ancestrales, justo frente al lado este del Gran Sello.', 'Araka puede ayudarte. Está en la Cámara de Sendas Ancestrales, justo frente al lado este del Gran Sello.', 28153),
(160340, 'esES', '¿Quieres crear una nueva hermandad? Te conviene buscar al guardia de muelle Finnson y a Perry Charlton. Son un tanto turbios, pero te enseñarán los rudimentos.\n\nLos encontrarás en el edificio que hay en la entrada de la ciudad más cercana al puerto.', '¿Quieres crear una nueva hermandad? Te conviene buscar al guardia de muelle Finnson y a Perry Charlton. Son un tanto turbios, pero te enseñarán los rudimentos.\n\nLos encontrarás en el edificio que hay en la entrada de la ciudad más cercana al puerto.', 28153),
(160339, 'esES', 'Leila Stafford es la mejor. Me ha ayudado varias veces cuando mi pequeñina se ha puesto mala.\n\nLa encontrarás en el nivel superior del Mercado Vientos Alisios, en el lado oeste.', 'Leila Stafford es la mejor. Me ha ayudado varias veces cuando mi pequeñina se ha puesto mala.\n\nLa encontrarás en el nivel superior del Mercado Vientos Alisios, en el lado oeste.', 28153),
(160338, 'esES', 'Teníamos un barbero, pero desapareció no hace mucho y nadie sabe qué le pasó. Aquel día no se hablaba de otra cosa.\n\nAhora hay un gnomo que se ha mudado adonde el otro vivía. Mira, yo no quiero decir nada, pero si quieres un corte o un cambio de color, puedes buscar a Teri Rizos en Puntagarfio. Vigila tu espalda, eso sí.', 'Teníamos un barbero, pero desapareció no hace mucho y nadie sabe qué le pasó. Aquel día no se hablaba de otra cosa.\n\nAhora hay un gnomo que se ha mudado adonde el otro vivía. Mira, yo no quiero decir nada, pero si quieres un corte o un cambio de color, puedes buscar a Teri Rizos en Puntagarfio. Vigila tu espalda, eso sí.', 28153),
(160337, 'esES', '', 'La fjarnskaggl gusta mucho a los nobles del lugar. Enseguida me quedo sin existencias.\n\nVuelve la semana que viene, que volveré a tener.', 28153),
(160336, 'esES', 'Ya tienes tus sellos de la semana. No me hagas perder más el tiempo.\n\nCreo que tendré más la semana que viene.', '', 28153),
(160335, 'esES', 'Henrick Wyther vende todo tipo de productos para apoyar a profesionales como tú. Lo encontrarás en el nivel superior del Mercado Vientos Alisios.\n\nSu puesto no tiene pérdida. Es un poco conspiranoico. No te rías de sus mapas y notas, que él eso se lo toma muy en serio, pero es buen tipo.', 'Henrick Wyther vende todo tipo de productos para apoyar a profesionales como tú. Lo encontrarás en el nivel superior del Mercado Vientos Alisios.\n\nSu puesto no tiene pérdida. Es un poco conspiranoico. No te rías de sus mapas y notas, que él eso se lo toma muy en serio, pero es buen tipo.', 28153),
(160334, 'esES', 'Objetos comerciales', 'Objetos comerciales', 28153),
(160333, 'esES', 'No me hagas hablar del oro que llevo gastado en reparaciones. Por suerte el almirantazgo tiene un herrero propio que se ocupa de nuestro equipo. Pero para tus cosas personales te recomiendo ir a ver a Patrick Markson. Sí, ya sé que vende armas de fuego. Pero también es muy bueno arreglando de todo.\n\nBusca su puesto junto a la fuente, en el nivel inferior del Mercado Vientos Alisios, según bajas de la posada por las escaleras.', 'No me hagas hablar del oro que llevo gastado en reparaciones. Por suerte el almirantazgo tiene un herrero propio que se ocupa de nuestro equipo. Pero para tus cosas personales te recomiendo ir a ver a Patrick Markson. Sí, ya sé que vende armas de fuego. Pero también es muy bueno arreglando de todo.\n\nBusca su puesto junto a la fuente, en el nivel inferior del Mercado Vientos Alisios, según bajas de la posada por las escaleras.', 28153),
(160332, 'esES', '¿Nunca has querido cambiar tu destino? ¿Tal vez por una pieza de armadura especial, un arma o un abalorio de gran poder?\n\nPor un módico precio, te proporcionaré un sello que altera el destino y otorga un resultado adicional para una oportunidad pasada.\n\nCuando el sello esté en tu poder, se activará tras derrotar a enemigos poderosos en mazmorras y bandas complicadas.\n\nPronto podré proporcionar sellos de destino destrozado por la guerra a cambio de oro, recursos de la guerra o marcas de honor.\n\nAhora mismo no tengo ninguno disponible.', '', 28153),
(160331, 'esES', 'Ofrezco varias formas de adquirir un sello de destino destrozado por la guerra.\n\n¿A qué prefieres renunciar por la oportunidad de alterar el destino?', '', 28153),
(160330, 'esES', '¡No puedes tener más sellos en tu poder!\n\nUsa los que tienes antes de pedirme más.', '', 28153),
(160329, 'esES', 'Pertrechos. Entendido. A quien buscas es a Ninette Shoames. Cada día deposita sus mercancías en la fuente que hay en la parte inferior del Mercado Vientos Alisios.', 'Pertrechos. Entendido. A quien buscas es a Ninette Shoames. Cada día deposita sus mercancías en la fuente que hay en la parte inferior del Mercado Vientos Alisios.', 28153),
(160328, 'esES', 'El Incansable usa ahora este muelle como punto de desembarco.\n\nLo fletó la Alianza como principal transporte para los diplomáticos entre Ventormenta y Kul Tiras. El barco te llevará directamente al Puerto de Boralus.', 'El Incansable usa ahora este muelle como punto de desembarco.\n\nLo fletó la Alianza como principal transporte para los diplomáticos entre Ventormenta y Kul Tiras. El barco te llevará directamente al Puerto de Boralus.', 28153),
(160327, 'esES', 'Pertrechos', 'Pertrechos', 28153),
(160326, 'esES', 'El Incansable suele atracar aquí para llevar a la gente de vuelta al continente. Si quieres ir a Ventormenta, ese es tu barco. Atracará en el puerto de la ciudad.', 'El Incansable suele atracar aquí para llevar a la gente de vuelta al continente. Si quieres ir a Ventormenta, ese es tu barco. Atracará en el puerto de la ciudad.', 28153),
(160325, 'esES', 'Vendedores. Ya. ¿Qué tipo de mercader buscas?', 'Vendedores. Ya. ¿Qué tipo de mercader buscas?', 28153),
(160324, 'esES', 'Quieres cambiar de aspecto. Entendido. Aunque parezca extraño, tienes que ir a ver al tejedor de distorsión Ezil. Lo sé, es raro porque el tipo parece un vendaje andante. Pero créeme, contigo puede hacer maravillas. Si es que consigues una cita.\n\nSu tienda está en el edificio contiguo a la Posada Muelle Acogedor.', 'Quieres cambiar de aspecto. Entendido. Aunque parezca extraño, tienes que ir a ver al tejedor de distorsión Ezil. Lo sé, es raro porque el tipo parece un vendaje andante. Pero créeme, contigo puede hacer maravillas. Si es que consigues una cita.\n\nSu tienda está en el edificio contiguo a la Posada Muelle Acogedor.', 28153),
(160323, 'esES', 'Si quieras aprender un nuevo estilo de bordado, o cómo contener una herida sangrante, o, incluso, cómo hacer una bolsa nueva..., te conviene entrenar con Daniel Tejesalmuera. Búscalo en el extremo norte del Mercado Vientos Alisios, en el nivel superior.\n\nDaniel es un buen tipo, aunque un pelín muermo. Me ha vendado más veces de las que querría admitir. Transmitir sus conocimientos suele alegrarle el día.', 'Si quieras aprender un nuevo estilo de bordado, o cómo contener una herida sangrante, o, incluso, cómo hacer una bolsa nueva..., te conviene entrenar con Daniel Tejesalmuera. Búscalo en el extremo norte del Mercado Vientos Alisios, en el nivel superior.\n\nDaniel es un buen tipo, aunque un pelín muermo. Me ha vendado más veces de las que querría admitir. Transmitir sus conocimientos suele alegrarle el día.', 28153),
(160322, 'esES', '¿Eres $gun:una; gran $gcazadora:cazadora;? Pues que sepas algo, $gamigo:amiga;: aquí las cosas tienen un pellejo más duro que nada que hayas visto. En Kul Tiras los criamos para que sean duros y letales.\n\nSi quieres aprender, hazlo con los mejores. Y esa es Camila Oscurecielo. Está en el nivel superior del lado norte del Mercado Vientos Alisios.', '¿Eres $gun:una; gran $gcazadora:cazadora;? Pues que sepas algo, $gamigo:amiga;: aquí las cosas tienen un pellejo más duro que nada que hayas visto. En Kul Tiras los criamos para que sean duros y letales.\n\nSi quieres aprender, hazlo con los mejores. Y esa es Camila Oscurecielo. Está en el nivel superior del lado norte del Mercado Vientos Alisios.', 28153),
(160321, 'esES', '¿A salvo? ¿Tú has visto todo lo que corretea por este sitio?\n\nGracias, pero yo de esta no me separo por si las moscas.', '', 28153),
(160320, 'esES', 'Aquí no necesitas blandir tu arma. No hay peligro.', 'Aquí no necesitas blandir tu arma. No hay peligro.', 28153),
(160319, 'esES', 'Prepárate para cualquier cosa.', '', 28153),
(160318, 'esES', 'La batalla es inminente. Nos vendría bien $un:una; $r como tú en nuestras filas.', '', 28153),
(160317, 'esES', 'Te lo veo en los ojos. En la mente, erosionada por la locura que te corroe. Pero puedes tener un respiro.$b$bAquí los sabios prosperaron en su día, intentando combatir la oscuridad. Construyeron capillas, baluartes de fe y entereza. Erigieron una taberna para ahogar los susurros en un mar de hidromiel. Y ahora son polvo y escombros...$b$bDirígete al noroeste. Allí está lo que queda de su presencia, un gran ídolo abisal. Encuentra la efigie y tal vez aún puedas acabar con los horrores de este lugar. Pero ten cuidado, pues tendrás que beber mucho y el mar siempre pasa factura.', '', 28153),
(160316, 'esES', 'Algo me preocupa. ¿Puedes ayudarme?', 'Algo me preocupa. ¿Puedes ayudarme?', 28153),
(160315, 'esES', '¿Lo notas? Los muros... se desmoronan. Van llegando de forma terrible susurro a susurro.', '', 28153),
(160314, 'esES', 'Estas ruinas fueron una vez la envidia del valle.', '', 28153),
(160313, 'esES', 'Confieso que no recuerdo cuándo se envió esa carta...', '', 28153),
(160312, 'esES', 'Recuerda, el exceso de confianza destruye de forma lenta e insidiosa.', '', 28153),
(160311, 'esES', '¿Buscas oro? ¿Platino? ¡¿Plata de tormenta?! Si buscas lo último en técnicas de minería, buscas a Myra Cabot. Tiene una habilidad sobrenatural para descubrir una veta.\n\nSe encuentra en el lado norte del Mercado Vientos Alisios, en el nivel superior. Ya me dirás si haces fortuna, $gamigo:amiga;.', '¿Buscas oro? ¿Platino? ¡¿Plata de tormenta?! Si buscas lo último en técnicas de minería, buscas a Myra Cabot. Tiene una habilidad sobrenatural para descubrir una veta.\n\nSe encuentra en el lado norte del Mercado Vientos Alisios, en el nivel superior. Ya me dirás si haces fortuna, $gamigo:amiga;.', 28153),
(160310, 'esES', 'Muy bien, ya volveremos para acabar con ellos.', '', 28153),
(160309, 'esES', 'A mí eso no me va, pero si quieres mejorar tus habilidades para la peletería, conozco a alguien en Kul Tiras ideal para ti. Se llama Cassandra Brennor y es una zahorí con punzón y sacabocados.\n\nNormalmente la verás trabajando con Camila Oscurecielo. Comparten un espacio en el nivel superior del extremo norte del Mercado Vientos Alisios.', 'A mí eso no me va, pero si quieres mejorar tus habilidades para la peletería, conozco a alguien en Kul Tiras ideal para ti. Se llama Cassandra Brennor y es una zahorí con punzón y sacabocados.\n\nNormalmente la verás trabajando con Camila Oscurecielo. Comparten un espacio en el nivel superior del extremo norte del Mercado Vientos Alisios.', 28153),
(160308, 'esES', 'Avísame cuando quieras empezar el bombardeo.', '', 28153),
(160307, 'esES', 'Samuel D. Colton tercero es a quien buscas. Es un milagro que no se añada un doctorado y un trato de don. Pero hay que reconocerlo: su trabajo es exquisito. Si buscas entrenamiento, no hay opción mejor.\n\nLo encontrarás bien ufano tras su expositor, en medio del nivel superior del lado norte del Mercado Vientos Alisios.', 'Samuel D. Colton tercero es a quien buscas. Es un milagro que no se añada un doctorado y un trato de don. Pero hay que reconocerlo: su trabajo es exquisito. Si buscas entrenamiento, no hay opción mejor.\n\nLo encontrarás bien ufano tras su expositor, en medio del nivel superior del lado norte del Mercado Vientos Alisios.', 28153),
(160306, 'esES', 'Busca a Zooey Tintapiñón. Hace poco alquiló un sitio en el extremo norte del Mercado Vientos Alisios, en el nivel superior.\n\nCuesta creer que quepa tanto conocimiento y poder en alguien tan diminuto.', 'Busca a Zooey Tintapiñón. Hace poco alquiló un sitio en el extremo norte del Mercado Vientos Alisios, en el nivel superior.\n\nCuesta creer que quepa tanto conocimiento y poder en alguien tan diminuto.', 28153),
(160305, 'esES', 'Si queremos tener alguna esperanza de atraer a los Zandalari a la Horda, debemos mantenernos fuertes.', '', 28153),
(160304, 'esES', '¿Te gustan las flores? A mí también. Huelen tan bien. Bueno, no todas.\n\nSi buscas el secreto para saber manejar bien la flora de esta parte del mundo, habla con Declan Senal. Lo encontrarás cuidando su jardín en el nivel superior del lado norte del Mercado Vientos Alisios.', '¿Te gustan las flores? A mí también. Huelen tan bien. Bueno, no todas.\n\nSi buscas el secreto para saber manejar bien la flora de esta parte del mundo, habla con Declan Senal. Lo encontrarás cuidando su jardín en el nivel superior del lado norte del Mercado Vientos Alisios.', 28153),
(160303, 'esES', '¡Alguien está protegiendo el Llanto del Alma en Pena con la magia sofisticada de los Sabiomar!', '', 28153),
(160302, 'esES', 'Alan Goyle tiene su cabaña de pesca por encima del Mercado Vientos Alisios. Está siempre ahí arriba, pescando en su estanque. No me preguntes cómo es que siempre hay peces. Para mí que caen por las cataratas.\n\nSubir ahí arriba tiene truco. Tienes que dar con las escaleras que hay entre los instructores de joyería y sastrería.', 'Alan Goyle tiene su cabaña de pesca por encima del Mercado Vientos Alisios. Está siempre ahí arriba, pescando en su estanque. No me preguntes cómo es que siempre hay peces. Para mí que caen por las cataratas.\n\nSubir ahí arriba tiene truco. Tienes que dar con las escaleras que hay entre los instructores de joyería y sastrería.', 28153),
(160301, 'esES', '¡Coge mis martillos, $p, y lánzalos con todas tus fuerzas!', '', 28153),
(160300, 'esES', 'Martillo Salvaje, ¡centraos en el Llanto del Alma en Pena! ¡No les deis tregua!', '', 28153),
(160299, 'esES', '¿Eres $gun granadero, un tirador certero o uno de esos inventores chiflados:una granadera, una tiradora certera o una de esas inventoras chifladas;? ¿Tal vez las tres cosas?\n\nSea como fuere, tú buscas a Layla Quillaplana. La encontrarás trasteando con sus máquinas en el nivel superior del extremo norte del Mercado Vientos Alisios.', '¿Eres $gun granadero, un tirador certero o uno de esos inventores chiflados:una granadera, una tiradora certera o una de esas inventoras chifladas;? ¿Tal vez las tres cosas?\n\nSea como fuere, tú buscas a Layla Quillaplana. La encontrarás trasteando con sus máquinas en el nivel superior del extremo norte del Mercado Vientos Alisios.', 28153),
(160298, 'esES', '', 'Los Mag\'har... prevalecerán...', 28153),
(160297, 'esES', '', '¡Tu fin es inminente!', 28153),
(160296, 'esES', 'Esta victoria vacía... no significa nada...', '', 28153),
(160295, 'esES', '', '¡Caerás!', 28153),
(160294, 'esES', '', '¡Mira! ¡Se retiran!', 28153),
(160293, 'esES', '', '¡Ja, ja! ¡Chupaos esa, ratas de Pantoque!', 28153),
(160292, 'esES', '', '¡Lok\'tar ogar!', 28153),
(160291, 'esES', '', '¡Dranosh\'ek Mag\'har!', 28153),
(160290, 'esES', 'Os espero... en las Tierras Contagiadas...', '', 28153),
(160289, 'esES', '', '¡Nunca nos rendiremos!', 28153),
(160288, 'esES', 'Nuestra batalla... no ha acabado...', '', 28153),
(160287, 'esES', '', '¡Por los Mag\'har!', 28153),
(160286, 'esES', 'Regresaré...', '', 28153),
(160285, 'esES', 'Idiotas... Solo habéis... derrotado... a un receptáculo...', '', 28153),
(160284, 'esES', '¿Crees que has ganado? Mira a tu alrededor... Lo que buscas no está aquí.', '', 28153),
(160283, 'esES', 'La niña perdida se encuentra en mi poder. Y cómo llora... ¡Su sufrimiento no tendrá fin!', '', 28153),
(160282, 'esES', '', 'Si la azerita es capaz de provocar un destrozo así, me temo que ni la gran puerta de Boralus hubiera resistido.', 28153),
(160281, 'esES', '', 'Cuánta destrucción... Era imposible que la Puerta de Daelin aguantara...', 28153),
(160280, 'esES', '', '¡Apunta a las barricas de pólvora!', 28153),
(160279, 'esES', 'A ti te interesa Emily Buentiempo. La encontrarás en la parte más alta del Mercado Vientos Alisios, en la cara norte.\n\nDe hecho una vez me hizo aparecer unos brazales como por arte de magia. Te la recomiendo de todas todas.', 'A ti te interesa Emily Buentiempo. La encontrarás en la parte más alta del Mercado Vientos Alisios, en la cara norte.\n\nDe hecho una vez me hizo aparecer unos brazales como por arte de magia. Te la recomiendo de todas todas.', 28153),
(160278, 'esES', '', 'Aquí las criaturas pueden ser muy desagradables, pero estoy curada de espanto y decidida a capturarlas a todas. Mi colección no es muy extensa aún, pero las que he capturado son de armas tomar. ¿Buscas pelea?', 28153),
(160277, 'esES', '¿Tengo visita? Qué curioso...', '', 28153),
(160276, 'esES', 'Cuando el último fuego ehté encendido, ¡la ciudad sabrá que somoh libreh! ¡Y mi tripulación volverá!', '', 28153),
(160275, 'esES', 'Es vulnerable en su propio reino, así que hará lo que haga falta para que no entres en él.', '', 28153),
(160274, 'esES', 'Te deseo suerte en tu camino, continental. Ve con cuidado; Gorak Tul te vigila.', '', 28153),
(160273, 'esES', 'Cuenca Verdeante es un buen lugar para una avanzada oculta. ¡Con azerita en abundancia cerca y ni un solo trol a la vista! ¡Lo tiene todo!', '', 28153),
(160272, 'esES', '', 'Nos hemos acostumbrado a los diversos insectos que vuelan por estas tierras, algunos muy dóciles y otros muy peligrosos. Me he hecho con bastantes especies a lo largo de muchos, muchos años, y nos encanta entretener a otros duelistas de mascotas con una escaramuza. ¿Te interesa?', 28153),
(160271, 'esES', '', 'Deberíamos atacar el siguiente desde el aire. ¿Vamos?', 28153),
(160270, 'esES', '', '¡Ah! Estábamos demasiado cerca...', 28153),
(160269, 'esES', 'Desenterrando', 'Desenterrando', 28153),
(160268, 'esES', 'Ah, tú buscas al \"capitán\". Busca su restaurante al aire libre situado entre el corral y el foso del herrero, en el nivel superior del Mercado Vientos Alisios. Está en el lado norte.\n \n¡Tienes que probar el pescado de ciénaga con patatas fritas! Solo con pensar en ir allí se me hace la boca agua.', 'Ah, tú buscas al \"capitán\". Busca su restaurante al aire libre situado entre el corral y el foso del herrero, en el nivel superior del Mercado Vientos Alisios. Está en el lado norte.\n \n¡Tienes que probar el pescado de ciénaga con patatas fritas! Solo con pensar en ir allí se me hace la boca agua.', 28153),
(160267, 'esES', '¿Que si sé dónde está el instructor de herrería? Pues claro que sí. Soy un guardia, ¿no?\n\nDirígete al nivel superior del Mercado Vientos Alisios. En la parte del norte verás un foso, y en él uno de los herreros más dotados que conozco, Grix \"Puños Férreos\" Barlow. No tiene pérdida.', '¿Que si sé dónde está el instructor de herrería? Pues claro que sí. Soy una guardia, ¿no?\n\nDirígete al nivel superior del Mercado Vientos Alisios. En la parte del norte verás un foso, y en él uno de los herreros más dotados que conozco, Grix \"Puños Férreos\" Barlow. No tiene pérdida.', 28153),
(160266, 'esES', 'Empezaré con los preparativos. Reúnete conmigo cuando lo tengas todo.', '', 28153),
(160265, 'esES', 'Por los pelos. ¡Gracias por tan oportuno rescate!', 'Por los pelos. ¡Gracias por tan oportuno rescate!', 28153),
(160263, 'esES', 'Superviso todas las tasas de registro para las hermandades y compañías comerciales en el puerto. ¿En qué puedo ayudarte?', '', 28153),
(160262, 'esES', '¿Escarbando en el suelo en busca de tesoros perdidos? Así es la vida. ¿Tienes uno de esos artilugios de topografía tan chulos?\n\nPues busca a Jane Hudson en el nivel superior del Mercado Vientos Alisios. Una vez arriba, suele estar en su negocio del lado oeste del bancal, cerca del corral.', '¿Escarbando en el suelo en busca de tesoros perdidos? Así es la vida. ¿Tienes uno de esos artilugios de topografía tan chulos?\n\nPues busca a Jane Hudson en el nivel superior del Mercado Vientos Alisios. Una vez arriba, suele estar en su negocio del lado oeste del bancal, cerca del corral.', 28153),
(160261, 'esES', '', 'Prepárate... ¡Y lanza!', 28153),
(160260, 'esES', 'Un maestro de pociones. Ajá. Sí, busca a Elric Whalgrene. Lo encontrarás en el extremo norte mismo del Mercado Vientos Alisios, en el nivel superior que da al foso del herrero.\n\nQue no te engañe eso de que no lleve chistera y bastón, ese tipo es un zahorí. Poderoso y extraño. O sea, ¿beber una poción para convertirse en nube? Raro. Pero admito que de vez en cuando me encanta tomar una dosis de su brebaje de pies ligeros. Es como andar con muelles.', 'Un maestro de pociones. Ajá. Sí, busca a Elric Whalgrene. Lo encontrarás en el extremo norte mismo del Mercado Vientos Alisios, en el nivel superior que da al foso del herrero.\n\nQue no te engañe eso de que no lleve chistera y bastón, ese tipo es un zahorí. Poderoso y extraño. O sea, ¿beber una poción para convertirse en nube? Raro. Pero admito que de vez en cuando me encanta tomar una dosis de su brebaje de pies ligeros. Es como andar con muelles.', 28153),
(160259, 'esES', 'Para que nuestra tierra sane, necesitamos la esperanza de la redención. Para todos nosotros.', '', 28153),
(160258, 'esES', '¡Cuánto debe haber sufrido por esas muertes! ¡Y cuánto ansiará, como yo, encontrar el perdón!', '', 28153),
(160257, 'esES', 'Lady Jaina no hizo nada mientras su padre y sus compatriotas morían.', '', 28153),
(160256, 'esES', 'Aún me pregunto si podría haber hecho más. Ese pensamiento me atormenta.', '', 28153),
(160255, 'esES', 'Habían perdido la cordura, pero aún siento remordimientos por sus muertes.', '', 28153),
(160254, 'esES', 'He tenido que luchar, e incluso matar, a mi propia gente. Fue una decisión dura, pero necesaria.', '', 28153),
(160253, 'esES', 'Muchos de mis compatriotas creen que Jaina Valiente es una traidora. Hay quienes cuestionarían mi decisión de perdonarle la vida.', '', 28153),
(160252, 'esES', '¿Eres $gun:una; profesional? Buscas que te instruyan, ¿verdad? No hay problema. Esto es Boralus, ¿sabes? No hay nada mejor.', '¿Eres $gun:una; profesional? Buscas que te instruyan, ¿verdad? No hay problema. Esto es Boralus, ¿sabes? No hay nada mejor.', 28153),
(160251, 'esES', '¡Derriba $gal:a la; $pr!', '', 28153),
(160250, 'esES', '', 'Deambulando por estas dunas encontré algunas de las especies de mascotas más espectaculares que haya visto jamás. Sobreviven de lo que pueden, como nosotros. Su voluntad de salir adelante es fuerte y eso las hace resistentes. ¿Quieres ver lo que encontré?', 28153),
(160249, 'esES', '¡No me comas, Morrobarro! ¡Somos amigos!', '', 28153),
(160248, 'esES', '¡Trágate solo a los malos!', '', 28153),
(160247, 'esES', '¡Intentaron ahuyentar a Morrobarro, pero se enfadó mucho!', '', 28153),
(160246, 'esES', '¡Se ha tragado al señor Anderson!', '', 28153),
(160245, 'esES', '¡Espabila!', '¡Espabila!', 28153),
(160244, 'esES', 'Debes reunir lo que necesito. Date prisa, hay una vida en juego.', '', 28153),
(160242, 'esES', 'Pero aún nos falta mucho para limpiar toda la corrupción de nuestra tierra.', '', 28153),
(160241, 'esES', 'Algunos hermanos leales se han unido a mí para cambiar el curso de esta marea... Literalmente, en algunos casos.', '', 28153),
(160240, 'esES', 'Lord Canto Tormenta ya no existe, pero la oscuridad que se apoderó de él permanece.', '', 28153),
(160239, 'esES', 'Poner un pie en esa isla es una sentencia de muerte.', '', 28153),
(160238, 'esES', 'Los Sabiomar somos los únicos que podemos acercarnos sin problemas, pero siempre nos quedamos en el agua.', '', 28153),
(160237, 'esES', 'Nunca he tenido que hacer frente a la terrible tarea de acompañar a un alma hasta Fin del Destino.', '', 28153),
(160236, 'esES', 'Lo siento, peque... No puedo dejarte pasar. Toma aquello a por lo que viniste y vete.', '', 28153),
(160235, 'esES', 'Si han enviado a lady Jaina a esa isla maldita, puede que no nos quede mucho tiempo. Sígueme.', '', 28153),
(160234, 'esES', '¿Condenó a su hija a Fin del Destino? ¡Por las mareas misericordiosas!', '', 28153),
(160233, 'esES', 'Lady Katherine ha recapacitado sobre su orden de ejecutar a su hija. Sabemos que se llevaron a Jaina a Fin del Destino. Busco la forma de llegar allí.', 'Lady Katherine ha recapacitado sobre su orden de ejecutar a su hija. Sabemos que se llevaron a Jaina a Fin del Destino. Busco la forma de llegar allí.', 28153),
(160232, 'esES', 'Casi no nos queda tiempo, debemos darnos prisa si queremos salvar a Jaina.', '', 28153),
(160230, 'esES', '¡Tienes una cabeza perfecta para mi siguiente creación!', '', 28153),
(160229, 'esES', 'De lo mejor que he hecho. Las piezas encajan a la perfección.', '', 28153),
(160228, 'esES', 'Ah, adalid. Me alegro de volver a verte. ¿Qué te trae de nuevo por Canto Tormenta?', '', 28153),
(160227, 'esES', 'A lady Katherine le interesará saber lo que has descubierto.', '', 28153),
(160226, 'esES', '', 'Es muy antiguo... y más terrible de lo que imaginas...', 28153),
(160225, 'esES', '', 'Me pertenecerás. Para siempre.', 28153),
(160224, 'esES', '', 'Hola, cielo. ¿Quieres oír mi canción?', 28153),
(160223, 'esES', 'Eres $gun necio:una necia;... por confiar..., como nosotros.', '', 28153),
(160222, 'esES', '¡No tendrás estos artefactos!', '', 28153),
(160221, 'esES', 'Los envíos no se pueden retrasar.', '', 28153),
(160220, 'esES', '¿Para qué querrías ver a ese gnomo loco? Toda su zona está hecha un asco, la verdad.\n\nPero ya veo que no te haré desistir. El individuo al que buscas es Crenzo Rompechispas. Se halla en el nivel superior del Mercado Vientos Alisios, en el lado este. Lo encontrarás trasteando sobre su siempre creciente pila de chatarra. Buena suerte, $gamigo:amiga;.', '¿Para qué querrías ver a ese gnomo loco? Toda su zona está hecha un asco, la verdad.\n\nPero ya veo que no te haré desistir. El individuo al que buscas es Crenzo Rompechispas. Se halla en el nivel superior del Mercado Vientos Alisios, en el lado este. Lo encontrarás trasteando sobre su siempre creciente pila de chatarra. Buena suerte, $gamigo:amiga;.', 28153),
(160219, 'esES', 'Debes saber que el sistema de ferris urbano es una de las verdaderas maravillas del mundo. No solo puede llevarte de un punto a otro por los prodigiosos canales de Boralus, sino que, además, los maestros de ferris también circulan por el extrarradio hacia el resto del Estrecho de Tiragarde.\n\nSi quieres un agradable viaje en barco, tu hombre es Will Melborne. Los encontrarás a él y a su hija Sally al nivel del agua, en la parte sur del Mercado Vientos Alisios.', 'Debes saber que el sistema de ferris urbano es una de las verdaderas maravillas del mundo. No solo puede llevarte de un punto a otro por los prodigiosos canales de Boralus, sino que, además, los maestros de ferris también circulan por el extrarradio hacia el resto del Estrecho de Tiragarde.\n\nSi quieres un agradable viaje en barco, tu hombre es Will Melborne. Los encontrarás a él y a su hija Sally al nivel del agua, en la parte sur del Mercado Vientos Alisios.', 28153),
(160218, 'esES', 'Maestro de ferris', 'Maestro de ferris', 28153),
(160217, 'esES', 'Hay todo tipo de sitios interesantes repartidos por Boralus. ¿Qué puedo ofrecerte, $gamigo:amiga;?', 'Hay todo tipo de sitios interesantes repartidos por Boralus. ¿Qué puedo ofrecerte, $gamigo:amiga;?', 28153),
(160216, 'esES', 'Si buscas un sitio en el que echar una cabezadita, te sugiero la posada Muelle Acogedor. La encontrarás en el nivel superior que da a la fuente.\n\nWesley Rockhold es tu hombre. Te proporcionará una cama bien cómoda. Nada de colchones de paja. Y si tiene una olla de su legendario estofado, píllate un plato bien grande.', 'Si buscas un sitio en el que echar una cabezadita, te sugiero la posada Muelle Acogedor. La encontrarás en el nivel superior que da a la fuente.\n\nWesley Rockhold es tu hombre. Te proporcionará una cama bien cómoda. Nada de colchones de paja. Y si tiene una olla de su legendario estofado, píllate un plato bien grande.', 28153),
(160215, 'esES', 'Wgullll naq xizzuoog', '', 28153),
(160214, 'esES', 'Wgul naq zzigla ouug anagih', '', 28153),
(160213, 'esES', '¡No tendrás que repetírmelo!', '', 28153),
(160212, 'esES', 'Quieres hacer un viaje, ¿eh? Sí, ya lo sé. La euforia de planear entre las nubes hacia tierras lejanas y exóticas. La emoción del peligro desconocido al otro lado. La promesa de ese fabuloso tesoro una vez vencido el villano.\n\n¿No? Ah, bueno... Que solo quieres un vuelo. ¿Y por qué no lo has dicho? Pues ve al nivel superior del lado oeste del Mercado Vientos Alisios. Encontrarás a Joan Weber cerca de la percha de grifo.', 'Quieres hacer un viaje, ¿eh? Sí, ya lo sé. La euforia de planear entre las nubes hacia tierras lejanas y exóticas. La emoción del peligro desconocido al otro lado. La promesa de ese fabuloso tesoro una vez vencido el villano.\n\n¿No? Ah, bueno... Que solo quieres un vuelo. ¿Y por qué no lo has dicho? Pues ve al nivel superior del lado oeste del Mercado Vientos Alisios. Encontrarás a Joan Weber cerca de la percha de grifo.', 28153),
(160211, 'esES', '', 'Sigue tu camino.', 28153),
(160210, 'esES', '', 'Y tú, portavoz de la Horda... Ya pensaré qué hacer contigo a su debido momento.', 28153),
(160209, 'esES', '', 'Tú, pequeño verde, ya no ereh bienvenido en el Redil Behtia de Guerra. ¡Largo!', 28153),
(160208, 'esES', '', 'Bien. Se acabó el vudú antinatural ehte.', 28153),
(160207, 'esES', '', 'Esto no estaba en mi... contrato...', 28153),
(160206, 'esES', '', '¡Estás en propiedad de la compañía Gobernalle!', 28153),
(160205, 'esES', 'El cuernoatroz joven gime y se desploma.', '', 28153),
(160204, 'esES', 'El cuernoatroz joven rehuye por el sabor.', '', 28153),
(160203, 'esES', '', 'Nos hará falta un bote para llegar al siguiente barco.', 28153),
(160202, 'esES', 'No me preguntes cómo lo sé, pero lo sé. Si quieres estar a buenas con esa misteriosa gente tortuga, debes hablar con su emisario, el recolector Kajo.\n\nAhora bien, ¿que dónde está? Eso es lo malo. Está en lo alto del Valle Canto Tormenta, en un lugar que llaman Vista de los Buscadores. Tendrás que subir ahí por tu cuenta, $gamigo:amiga;, pero a juzgar por tu aspecto seguro que ya sabes cómo.', 'No me preguntes cómo lo sé, pero lo sé. Si quieres estar a buenas con esa misteriosa gente tortuga, debes hablar con su emisario, el recolector Kajo.\n\nAhora bien, ¿que dónde está? Eso es lo malo. Está en lo alto del Valle Canto Tormenta, en un lugar que llaman Vista de los Buscadores. Tendrás que subir ahí por tu cuenta, $gamigo:amiga;, pero a juzgar por tu aspecto seguro que ya sabes cómo.', 28153),
(160201, 'esES', '¡Que vuelen los martillos!', '', 28153),
(160200, 'esES', '¡Los martillos son imbatibles y los grifos imparables!', '', 28153),
(160199, 'esES', '', '¡Ahora! ¡Al ataque!', 28153),
(160198, 'esES', 'Haciendo puntos con el almirantazgo, ¿eh? Bien por ti.\n\nSí, sé dónde está. Busca a la proveedora Fray en el Despacho del Capitán de Puerto. Está ahí metida con todos los peces gordos.', 'Haciendo puntos con el almirantazgo, ¿eh? Bien por ti.\n\nSí, sé dónde está. Busca a la proveedora Fray en el Despacho del Capitán de Puerto. Está ahí metida con todos los peces gordos.', 28153),
(160197, 'esES', 'Emisaria del Almirantazgo de la Casa Valiente', 'Emisaria del Almirantazgo de la Casa Valiente', 28153),
(160196, 'esES', 'Emisarios, ¿eh? ¿A cuál buscas?', 'Emisarios, ¿eh? ¿A cuál buscas?', 28153),
(160195, 'esES', 'El banco. Sí. Encontrarás a los banqueros en el extremo noroeste de la ciudad, en el distrito del Mercado Vientos Alisios. Están en la zona este del nivel inferior.\n\nLo que me recuerda que tengo que ir a revisar mi cuenta cuando acabe el turno. No tengo protección contra descubiertos.', 'El banco. Sí. Encontrarás a los banqueros en el extremo noroeste de la ciudad, en el distrito del Mercado Vientos Alisios. Están en la zona este del nivel inferior.\n\nLo que me recuerda que tengo que ir a revisar mi cuenta cuando acabe el turno. No tengo protección contra descubiertos.', 28153),
(160194, 'esES', 'Ah, hola, $c. ¿Qué se cuece?', '', 28153),
(160193, 'esES', '¡A bucear!', '¡A bucear!', 28153),
(160192, 'esES', 'Perfecto. Veamos...\n\n<Hobart hojea un manual empapado>.\n\nLas normas de seguridad tres a diecisiete son aburridas y no tienen importancia. ¿$gListo:Lista;?', '', 28153),
(160191, 'esES', 'No dejar la linterna encendida mucho tiempo. Vale.', 'No dejar la linterna encendida mucho tiempo. Vale.', 28153),
(160190, 'esES', 'Estupendo. Segunda norma: NO TE DEJES LA LINTERNA ENCENDIDA.\n\nEn serio. Más vale que no la tengas encendida más de, no sé, veinte segundos o así. A menos que quieras que se te coma un tiburón. Si ves uno, apaga la luz. ¿Entendido?', '', 28153),
(160189, 'esES', 'No quitarme el casco. Vale.', 'No quitarme el casco. Vale.', 28153),
(160188, 'esES', '¡Genial! Primera norma: no te quites nunca el casco.\n\nMe dan igual esas pamplinas mágicas para respirar en el agua. La presión de ahí abajo puede aplastarle el cráneo a $gun:una; $r. Además, usaré un auricular a prueba de estática para comunicarme contigo durante la misión. ¿Entendido?', '', 28153),
(160187, 'esES', 'Sí, te escucho.', 'Sí, te escucho.', 28153),
(160186, 'esES', '¡Ajá! ¡Aquí $gnuestro buceador:nuestra buceadora;!\n\nLlegas en el momento justo. Acabo de terminar de parchear el último agujero de la manguera de aire.\n\nAntes de ponernos a ello, hay unas normas de seguridad para el buceo. ¿Me escuchas?', '', 28153),
(160185, 'esES', '', 'Yo que tú cerraría el pico.', 28153),
(160184, 'esES', '¿No podemos hablarlo? Es decir, esto apenas tiene efectos secundarios...', '', 28153),
(160183, 'esES', 'Anda... Si eres TÚ. ¡Vaya, vaya, mira qué bien!', '', 28153),
(160182, 'esES', '', '¿Cómo han podido hacer esto esos monstruos?', 28153),
(160181, 'esES', '¡Epa! ¡Eh, eh! ¡¿Te importaría apartar esas cosas puntiagudas?!', '', 28153),
(160180, 'esES', '', 'Debemos encontrar la forma de sobrevivir.', 28153),
(160179, 'esES', '', 'Ehplícate.', 28153),
(160178, 'esES', '', 'Esperaré en las sombras, $n. Si me necesitas, solo tienes que llamarme.', 28153),
(160177, 'esES', '', 'Un consejo: aléjate de los pozos de energía mágica. Crean dependencia y convierten a la gente en una especie de... elfos derivados.', 28153),
(160176, 'esES', '', 'No, no me gustan las vendas en los ojos. Bueno... puede que un poco.', 28153),
(160175, 'esES', '', 'Me gustas... ¿No tendrás un hermano gemelo por casualidad?', 28153),
(160174, 'esES', '', 'Puedes intentar impedir que me lo lleve y morir, o quedarte arrodillado en el fango y vivir.', 28153),
(160173, 'esES', '', 'El rey Anduin me dio una piedra de hogar para volver a Ventormenta. Allí curaré las heridas de mi amado... y ayudaré a mi gente a recuperarse de esta locura.', 28153),
(160172, 'esES', 'Salgamos de aquí.', 'Salgamos de aquí.', 28153),
(160171, 'esES', 'La guardia de honor arreglará el resto de este desastre. ¿Estás a punto?', '', 28153),
(160170, 'esES', '', 'No bajes la guardia.', 28153),
(160169, 'esES', '', '¡Adalid!', 28153),
(160168, 'esES', '', '¡Cuidado!', 28153),
(160167, 'esES', '|cFF0000FF(Misión)|r Llévanos al barco naufragado del mariscal Valentine, en medio del Mare Magnum.', '|cFF0000FF(Misión)|r Llévanos al barco naufragado del mariscal Valentine, en medio del Mare Magnum.', 28153),
(160166, 'esES', '', 'Por aquí.', 28153),
(160165, 'esES', 'Saludos, $gviajero:viajera;. ¿En qué puedo ayudarte?', 'Saludos, $gviajero:viajera;. ¿En qué puedo ayudarte?', 28153),
(160164, 'esES', '', '¡Aquí!', 28153),
(160163, 'esES', '', 'Su luz revela todas las verdades.', 28153),
(160162, 'esES', 'La azerita... Ehto no... lo que Zul prometió...', '', 28153),
(160161, 'esES', '¡Tuh ehfuerzoh son inútileh! ¡Loh podereh de la azerita fluyen a travéh de mí!', '', 28153),
(160160, 'esES', '¡Retirada! ¡Los pillaremos al otro lado!', '¡Retirada! ¡Los pillaremos al otro lado!', 28153),
(160159, 'esES', '¡Te tenemos, $p!', '', 28153),
(160158, 'esES', 'Me gustaría comerciar.', 'Me gustaría comerciar.', 28153),
(160157, 'esES', 'Volvamos al portal.', '', 28153),
(160156, 'esES', '', 'Es un honor servir a Elune.', 28153),
(160155, 'esES', '', 'Hablo en nombre de mi pueblo.', 28153),
(160154, 'esES', '', 'Nuestros enemigos conocerán nuestra furia.', 28153),
(160153, 'esES', 'Tienes tanto corazón como tu madre.', '', 28153),
(160152, 'esES', 'No creo que nadie deba perder su hogar. No si hace que se sientan así.', '', 28153),
(160151, 'esES', 'Madre hablaba de ello a veces. Creo... que la hacía llorar.', '', 28153),
(160150, 'esES', '', 'Los kaldorei sobrevivirán.', 28153),
(160149, 'esES', 'No éramos... nosotros. Es difícil de explicar, chico.', '', 28153),
(160148, 'esES', '¿No se quedaron todos muy tristes?', '', 28153),
(160147, 'esES', 'Eso fue hace mucho tiempo.', '', 28153),
(160146, 'esES', 'Me dijiste que los orcos perdimos una vez nuestro hogar.', '', 28153),
(160145, 'esES', '', 'A veces debemos ser pacientes... otras veces debemos luchar.', 28153),
(160144, 'esES', '¿Por qué?', '', 28153),
(160143, 'esES', 'Me sabe mal que los elfos perdieran su árbol.', '', 28153),
(160142, 'esES', '¡A los poderes inferiores tu bendición devolveré!', '', 28153),
(160141, 'esES', 'Acabaré con nuestros enemigos si me concedes tu poder...', '', 28153),
(160140, 'esES', 'Y castíganos si lo usamos contra tu voluntad.', '', 28153),
(160139, 'esES', '', 'Lucharemos para proteger nuestro futuro.', 28153),
(160138, 'esES', 'Pero permítenos tu poder aprovechar, usar...', '', 28153),
(160137, 'esES', '', 'Escucha la voz de Elune.', 28153),
(160136, 'esES', 'Ya veremos, chico. Ya veremos.', '', 28153),
(160135, 'esES', '¿Crees que esta guerra va a cambiar a la Horda?', '', 28153),
(160134, 'esES', 'Los océanos permanecerán, no así la humanidad.', '', 28153),
(160133, 'esES', 'Las guerras nunca cambian. Solo los guerreros.', '', 28153),
(160132, 'esES', '¿Esta guerra es mala? Es decir... ¿Peor que las demás?', '', 28153),
(160131, 'esES', 'Remolinos de mareas, lazos de unidad...', '', 28153),
(160130, 'esES', '¿Qué pasa, chico?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160129, 'esES', '¿Padre?', '', 28153),
(160128, 'esES', '', 'El Monte Mugamba es un lugar salvaje e implacable. Custodiado por una tribu de gorilas gigantes y rodeado de traicioneros acantilados, es poco probable que la Horda venga a buscarnos aquí.', 28153),
(160127, 'esES', '', 'Cuando desees volver a la Costa Oscura del presente, solo tienes que pedirlo.', 28153),
(160126, 'esES', 'Lo haré, padre.', '', 28153),
(160125, 'esES', 'Recuérdalo, chico.', '', 28153),
(160124, 'esES', 'La guerra es una prueba de honor. En cuanto se pierde, no es fácil de recuperar.', '', 28153),
(160123, 'esES', 'La guerra saca lo peor de todo del mundo.', '', 28153),
(160122, 'esES', 'Oí a otros niños hablar de la guerra. ¿Ha...? ¿Ha hecho la Horda algo malo?', '', 28153),
(160121, 'esES', 'Estás muy callado. Más de lo habitual.', '', 28153),
(160120, 'esES', '¿Sí, padre?', '', 28153),
(160119, 'esES', 'Chico.', '', 28153),
(160118, 'esES', 'Esta tierra está llena de maravillosas e interesantes criaturas. Al igual que los defensores de nuestro templo se enorgullecen de ser tenaces y competentes en combate, yo me enorgullezco de adiestrar a mis mascotas para que sean lo más competentes posible, y ellas están entregadas a entrenarse para la lucha. ¿Están las tuyas a la altura?', '', 28153),
(160117, 'esES', '¿Puedes mostrarme cómo era el mundo antes de la quema de Teldrassil?', '¿Puedes mostrarme cómo era el mundo antes de la quema de Teldrassil?', 28153),
(160116, 'esES', 'Un momento... ¿te estabas metiendo con mi peso? Llevaba un arcón enorme encima, ¡y lo sabes!', '', 28153),
(160115, 'esES', 'Hecho. ¡Agarra el cetro y salgamos de aquí!', '', 28153),
(160114, 'esES', '¡Aléjate de ahí!', '', 28153),
(160113, 'esES', '', 'Bueno, podrías haberte quitado ese abrigo harapiento, Flynn.', 28153),
(160112, 'esES', '¡Blasfemia!', '', 28153),
(160111, 'esES', 'Vale, vale. Pillaremos unos cuantos peces para tu superpájaro y dejaremos que descanse un poco antes de volver.', '', 28153),
(160110, 'esES', '', 'No quiero que mi pequeña viaje si está agotada. Hoy ha llevado una carga muy pesada.', 28153),
(160109, 'esES', '', 'Volveremos a la ciudad, pero antes Alatifón necesita descansar un poco.', 28153),
(160108, 'esES', 'Déjame un hueco, Taelia. ¡Esta vez pienso volar bien sentado!', '', 28153),
(160107, 'esES', 'Vale. Adalid, tú echa un vistazo por Tol Dagor. Nosotros llevaremos el arcón a Boralus.', '', 28153),
(160106, 'esES', 'Ehte mundo no te merece, $n. ¿Por dónde iba? Ah, sí. Nuehtra fatídica huida.', '', 28153),
(160105, 'esES', 'Mucho mejor. Déjame continuar...', '', 28153),
(160104, 'esES', 'Ah, eso ehtá mucho mejor.', '', 28153),
(160103, 'esES', '¡Nooo! Otra vez... no...', '', 28153),
(160102, 'esES', '¡Siento cómo vuelve la vida a mi forma! ¡Necesito máh poder!', '', 28153),
(160101, 'esES', 'Por desgracia, el barco está actualmente en reparación. Puede que su hoja de servicios haya quedado empañada, pero aquí estoy yo para proporcionarte otros medios y que llegues a tu destino.\n\nQuizás un simple portal no sea tan emocionante como sentir que el viento te mesa los cabellos en alta mar, pero podrás seguir a lo tuyo sin trabas.\n\nPor favor, usa este portal cuando tengas la necesidad. Estoy a tu servicio.', 'Por desgracia, el barco está actualmente en reparación. Puede que su hoja de servicios haya quedado empañada, pero aquí estoy yo para proporcionarte otros medios y que llegues a tu destino.\n\nQuizás un simple portal no sea tan emocionante como sentir que el viento te mesa los cabellos en alta mar, pero podrás seguir a lo tuyo sin trabas.\n\nPor favor, usa este portal cuando tengas la necesidad. Estoy a tu servicio.', 28153),
(160100, 'esES', '¡Ah!', '¡Ah!', 28153),
(160099, 'esES', '¡Voy a dehtripar a quien haya dejado ehto aquí!', '¡Voy a dehtripar a quien haya dejado ehto aquí!', 28153),
(160098, 'esES', '¡Otra vez no!', '¡Otra vez no!', 28153),
(160097, 'esES', '¡¿Quién ha puehto ehto aquí?!', '¡¿Quién ha puehto ehto aquí?!', 28153),
(160096, 'esES', '', '¡Puertopuente está ahí delante! ¡Aterrizaremos allí!', 28153),
(160095, 'esES', '¡Thros despierta!', '', 28153),
(160094, 'esES', 'Sabes que no puedes derrotarme, Ulfar. Pero si buscas pelea, ¡la tendrás!', '', 28153),
(160093, 'esES', 'Mi... poder...', 'Mi... poder...', 28153),
(160092, 'esES', 'Poder... ¡Mayor del que jamáh he tenido! ¡Necesito máh!', 'Poder... ¡Mayor del que jamáh he tenido! ¡Necesito máh!', 28153),
(160091, 'esES', 'Aquí encontraráh el barco que va del Puerto de Zandalar a lah Ihlah del Eco.\n\n¿Eh allí a donde te dirigeh?', '', 28153),
(160090, 'esES', '', 'Estas servirán. Salgamos del barco, ¡vamos a probar las bombas!', 28153),
(160089, 'esES', 'Encárgate de este incordio, $n.', '', 28153),
(160088, 'esES', '¡Si tú ehcupeh a mi loa yo te arranco loh labioh!', '¡Si tú ehcupeh a mi loa yo te arranco loh labioh!', 28153),
(160087, 'esES', '¡Ya te enseñaré yo a faltar al rehpeto a mi loa!', '¡Ya te enseñaré yo a faltar al rehpeto a mi loa!', 28153),
(160086, 'esES', '¡Pagaráh por ehte insulto!', '¡Pagaráh por ehte insulto!', 28153),
(160085, 'esES', '¿Por qué haceh eso?', '¿Por qué haceh eso?', 28153),
(160084, 'esES', 'En nombre de todoh loh loa, ¿qué creeh que ehtáh haciendo?', 'En nombre de todoh loh loa, ¿qué creeh que ehtáh haciendo?', 28153),
(160083, 'esES', '¡Vale ya!', '¡Vale ya!', 28153),
(160082, 'esES', 'Vamos.', 'Vamos.', 28153),
(160081, 'esES', 'Parece que tenemos visita. ¿Te apuntas a saludar?', '', 28153),
(160080, 'esES', 'Katherine no se detendrá ante nada para recuperar el cadáver de su hijo.\n\nSacaremos partido a sus emociones para cobrar ventaja frente a su flota.', '', 28153),
(160079, 'esES', 'Otra ridícula estrategia de la Alianza frustrada. Supongo que debería felicitarte...', '', 28153),
(160078, 'esES', 'La Alianza ha creado su propia máquina de guerra potenciada con azerita. Si es la mitad de potente que la nuestra, debemos destruirla de inmediato.', '', 28153),
(160077, 'esES', '\"Aullido de Fatalidad\", un nombre adecuado. ¡Bien hecho!', '', 28153),
(160076, 'esES', 'La Horda ha construido otra máquina de guerra que funciona con azerita. ¡Acaba con ella antes de que destruya Stromgarde!', '', 28153),
(160075, 'esES', '', 'Es hora de pagarles con la misma moneda. Busquemos bombas de azerita en uno de sus barcos.', 28153),
(160074, 'esES', '', 'Se hará justicia... Primero vamos a por los piratas; luego, a por la Compañía Gobernalle.', 28153),
(160073, 'esES', '', 'Aguanta, Flynn. No te mueras...', 28153),
(160072, 'esES', 'Nuestra ubicación con vistas a la Ruta Dorada es un excelente punto estratégico desde el que controlar el tráfico que entra y sale de la capital de Zandalar.', '', 28153),
(160071, 'esES', 'Colocar cebo', 'Colocar cebo', 28153),
(160070, 'esES', 'Que así sea. Recuperaré el cadáver de Derek pasando por encima del tuyo.', '', 28153),
(160069, 'esES', 'Pero, francamente, puedes hacer lo que quieras con Valentine. No significa nada para nosotros.', '', 28153),
(160068, 'esES', 'Ah, mi buen amigo. Esa táctica podría funcionar con otro que no fuera yo...', '', 28153),
(160067, 'esES', 'Devolvednos a Derek Valiente y vosotros recuperaréis a vuestro hombre.', '', 28153),
(160066, 'esES', 'Invirtiendo', 'Invirtiendo', 28153),
(160065, 'esES', 'Cuando oí a los trols hablar de sombras, supuse que se referían a sombras de verdad. ¿Quién habría dicho que les gustaran tanto las metáforas?', 'Cuando oí a los trols hablar de sombras, supuse que se referían a sombras de verdad. ¿Quién habría dicho que les gustaran tanto las metáforas?', 28153),
(160064, 'esES', '¿Sabes qué necesita este sitio? Un buen lodo verde.', '¿Sabes qué necesita este sitio? Un buen lodo verde.', 28153),
(160063, 'esES', '¡Intolerable! Aquí el agua es demasiado azul para mi gusto.', '¡Intolerable! Aquí el agua es demasiado azul para mi gusto.', 28153),
(160062, 'esES', '¿Sabes? Creo que yo también necesito un nuevo estilismo. Te conviene buscar al tejedor de distorsión Hayri cerca de los muelles.\n\nPara llegar allí, ve al Gran Bazar, que está a un bancal del puerto. Hayri administra un lugar del lado este llamado Mercado de La Vorágine.', '¿Sabes? Creo que yo también necesito un nuevo estilismo. Te conviene buscar al tejedor de distorsión Hayri cerca de los muelles.\n\nPara llegar allí, ve al Gran Bazar, que está a un bancal del puerto. Hayri administra un lugar del lado este llamado Mercado de La Vorágine.', 28153),
(160061, 'esES', 'No creo que nadie note que se han llevado unos cuantos miembros del campo de batalla.', 'No creo que nadie note que se han llevado unos cuantos miembros del campo de batalla.', 28153),
(160060, 'esES', '¿Quiereh retocar tu ahpecto? En la zona del muelle hay un etéreo al que llaman tejedor de dihtorsión Hayri.\n\nPa dar con él, ve primero al Gran Bazar, que ehtá en un bancal sobre el puerto. Lo encontraráh en un sitio llamado Mercado de La Vorágine, en la zona ehte.', '¿Quiereh retocar tu ahpecto? En la zona del muelle hay un etéreo al que llaman tejedor de dihtorsión Hayri.\n\nPa dar con él, ve primero al Gran Bazar, que ehtá en un bancal sobre el puerto. Lo encontraráh en un sitio llamado Mercado de La Vorágine, en la zona ehte.', 28153),
(160059, 'esES', 'Este sitio no es El Apothecarium, pero qué se le va a hacer.', 'Este sitio no es El Apothecarium, pero qué se le va a hacer.', 28153),
(160058, 'esES', 'Oye, tú pareces tener experiencia en los duelos de mascotas. No nos andemos con rodeos: ¿quieres luchar?', '', 28153),
(160057, 'esES', 'Esta ciudad es demasiado abierta para mi gusto. Necesito sitios sombríos como este para realizar mi trabajo.', 'Esta ciudad es demasiado abierta para mi gusto. Necesito sitios sombríos como este para realizar mi trabajo.', 28153),
(160056, 'esES', '¡Excelente! Siento que Azeroth empieza a recuperar su poder.', '', 28153),
(160055, 'esES', 'Transfigurador', 'Transfigurador', 28153),
(160054, 'esES', 'Siento que hay azerita cerca de aquí... ¡y algo que está obteniendo un gran poder de ella! ¡Hay que detenerlo!', '', 28153),
(160053, 'esES', 'No fue hahta muchoh díah dehpuéh cuando comprendí la terrible verdad...\n\nKaiani había muerto, asesinada por su padre, pero me iban a culpar a mí.\n\n<Zenbaro tose con violencia>.\n\nNo creo que me quede mucho ya.\n\n¿Podríah traerle a ehte moribundo un último trago del manantial?', '', 28153),
(160052, 'esES', 'En cuehtión de un año tenía suficiente pa que Kaiani y yo noh fugáramoh.\n\nPlaneamoh irnoh aquella noche. Le dije que al atardecer se reuniera conmigo cerca del Viejo Camino Mercantil.\n\nEn cuanto el sol se puso trah lah montañah, corrí hacia mi futuro.\n\nEn el Camino Mercantil me ehperaban guardiah armadoh.\n\nSe me llevaron sin decir una palabra.', '', 28153),
(160051, 'esES', 'Qué vergüenza, dar más importancia a la propia codicia que a la salud de Azeroth. Gracias, adalid.', '', 28153),
(160050, 'esES', 'Durante el tiempo que trabajé para su padre, intimamoh.\n\nElla me suplicó que dejara a loh malandrineh y noh fuéramoh de la ciudad, pero yo sabía que no había ehcapatoria.\n\nYo ehtaba pelado. Todo lo que robaba iba directo a Rajin. Pero ¿por qué tenía que ser así?\n\nA partir de aquel día, de cada doh monedah que robaba me ehcondía una pa mí.\n\n<Zenbaro tose con violencia>.\n\nNecesito agua, $n. Por favor...', '', 28153),
(160049, 'esES', 'Me había ganado la confianza y el rehpeto de Rajin, todo al que alguien podía ahpirar.\n\nPa un malandrín, ese eh el sueño, pero yo tenía otrah cosah en mente...\n\nRajin tenía una hija, Kaiani. Era todo lo que yo no era: honehta, amable..., hermosa.', '', 28153),
(160048, 'esES', 'El jefe no tardó en fijarse en mih habilidadeh.\n\nAl cabo de poco ya le hacía recadoh al mihmísimo Rajin.\n\nSi había que leerle la cartilla a alguien, yo era el tipo indicado.\n\nPero créeme, la cosa no iba de leer.\n\n<Zenbaro tose>.\n\nMe vendría bien máh agua, $n.', '', 28153),
(160047, 'esES', 'Alguien está extrayendo azerita en esta cueva, de las heridas abiertas del mundo. ¡Impídelo!', '', 28153),
(160046, 'esES', 'Cuéntame más.', 'Cuéntame más.', 28153),
(160045, 'esES', 'Es arriesgado provocar a un oso.', '', 28153),
(160044, 'esES', 'La muerte es parte del ciclo de la vida. ¿Quieres que te lo demuestre?', '', 28153),
(160043, 'esES', 'Puede que sea viejo, pero no estoy senil. Para.', '', 28153),
(160042, 'esES', 'Sé fuerte.', '', 28153),
(160041, 'esES', 'Que la fuerza del bosque te acompañe.', '', 28153),
(160040, 'esES', 'Golpea rápido y en el blanco.', '', 28153),
(160039, 'esES', 'Cuidado con el bosque.', '', 28153),
(160038, 'esES', 'Mantén el equilibrio.', '', 28153),
(160037, 'esES', 'Saludos, continental.', '', 28153),
(160036, 'esES', 'Nuestras raíces son profundas en esta tierra.', '', 28153),
(160035, 'esES', 'Combatimos la oscuridad.', '', 28153),
(160034, 'esES', 'La vida tiene ritmo. ¿Lo sientes?', '', 28153),
(160033, 'esES', '¿Has venido a aprender?', '', 28153),
(160032, 'esES', '', '¡Así se te atragante este repollo!', 28153),
(160031, 'esES', 'Mi sabiduría no es para los débiles.', '', 28153),
(160030, 'esES', '¿Qué quieres de los Hablaespinas?', '', 28153),
(160029, 'esES', '¿Cómo podemos pujar por lo que necesitamos si no tenemos dinero?', '¿Cómo podemos pujar por lo que necesitamos si no tenemos dinero?', 28153),
(160028, 'esES', 'No nos quedan muchos objetos de valor que vender.', 'No nos quedan muchos objetos de valor que vender.', 28153),
(160027, 'esES', 'Con esto debería bastar para permitirnos suministros... Espero.', 'Con esto debería bastar para permitirnos suministros... Espero.', 28153),
(160026, 'esES', '¿Cuánto oro nos queda?', '¿Cuánto oro nos queda?', 28153),
(160025, 'esES', '¿Nos queda algo de valor que vender?', '¿Nos queda algo de valor que vender?', 28153),
(160024, 'esES', 'No tengo muy claro que los banqueros goblins sean mucho mejores que esos agarrados de los Montesco.', 'No tengo muy claro que los banqueros goblins sean mucho mejores que esos agarrados de los Montesco.', 28153),
(160023, 'esES', 'Inténtalo con más fuerza... ¡pero no demasiada!', '', 28153),
(160022, 'esES', '', '¡No puedo deshacerme del último!', 28153),
(160021, 'esES', '¡Huimos de forma tan precipitada que tuve que dejarlo todo!', '¡Huimos de forma tan precipitada que tuve que dejarlo todo!', 28153),
(160020, 'esES', '', '¡Largo de aquí, $r!', 28153),
(160019, 'esES', '', '¡Irán a por ti, $r!', 28153),
(160018, 'esES', '', '¡Vete de Ventormenta, $r!', 28153),
(160017, 'esES', 'Veamos a quién ha enviado ahora Valiente.', '', 28153),
(160016, 'esES', '¡Alto!', '¡Alto!', 28153),
(160015, 'esES', 'Creías que no te veríamos, ¿eh?', 'Creías que no te veríamos, ¿eh?', 28153),
(160014, 'esES', '¡Ja! Te he pillado husmeando.', '¡Ja! Te he pillado husmeando.', 28153),
(160013, 'esES', '¡Largo de aquí, escoria de la Horda!', '¡Largo de aquí, escoria de la Horda!', 28153),
(160012, 'esES', '', 'TRIPULACIÓN DE VINTA, ¡ABRID FUEGO!', 28153),
(160011, 'esES', 'Poder restaurado. Continuar directiva principal. ¡Exterminar!', 'Poder restaurado. Continuar directiva principal. ¡Exterminar!', 28153),
(160010, 'esES', '¡Te mataré para arrebatarte ese martillo!', '¡Te mataré para arrebatarte ese martillo!', 28153),
(160009, 'esES', '', '¡Aquí tenemos para todos los gustos!', 28153),
(160008, 'esES', '', '¡Veo a $gun:una; $r $gal:a la; que le vendrían bien vitaminas!', 28153),
(160007, 'esES', '', '¡Tienes pinta de necesitar un nabo maduro!', 28153),
(160006, 'esES', '', '¡Aquí se vende de todo!', 28153),
(160005, 'esES', '¡Largo de ahí!', '', 28153),
(160004, 'esES', '¡Alto!', '', 28153),
(160003, 'esES', '¡¿Qué estás haciendo aquí?!', '', 28153),
(160002, 'esES', '¡No des un paso más!', '', 28153),
(160001, 'esES', '¡Dad la cara, gusanos de la Horda! Tenemos a uno de los vuestros.', '', 28153),
(160000, 'esES', 'Yo me largo de aquí en cuanto esto se despeje. Nos vemos en casa de la abuela, ¡buena suerte!', '', 28153),
(159999, 'esES', '¿Qué hacemos ahora, Jefa de Guerra?', '¿Qué hacemos ahora, Jefa de Guerra?', 28153),
(159998, 'esES', '¡Hacer un bonito pastel está chupado!', '', 28153),
(159997, 'esES', 'Uno de los Lanza Negra, el supervisor Al\'jibo, se ocupa de eso para la mayoría de nuestras fuerzas. Lo encontrarás en la Cámara de Sendas Ancestrales, en el Gran Sello del lado este.', 'Uno de los Lanza Negra, el supervisor Al\'jibo, se ocupa de eso para la mayoría de nuestras fuerzas. Lo encontrarás en la Cámara de Sendas Ancestrales, en el Gran Sello del lado este.', 28153),
(159996, 'esES', '¿Quieres deshacerte de algunas de esas ganancias obtenidas con malas artes? Te escucho. ¿De qué sirve ir de campaña si no hay botín? ¿Sí o no? ¿O tal vez tienes algo que reparar?\n\n¿Qué clase de mercader buscas?', '¿Quieres deshacerte de algunas de esas ganancias obtenidas con malas artes? Te escucho. ¿De qué sirve ir de campaña si no hay botín? ¿Sí o no? ¿O tal vez tienes algo que reparar?\n\n¿Qué clase de mercader buscas?', 28153),
(159995, 'esES', 'Pin\'jin el Paciente es a quien buscas para aprender más sobre sastrería. Tiene mano firme con la aguja para bordar togas y, además, sutura que es un portento. A mí el otro día me cosió el brazo.\n\nBúscalo detrás de los cotorreantes nobles del Bancal de Artesanos, en el lado oeste de Dazar\'alor.', 'Pin\'jin el Paciente es a quien buscas para aprender más sobre sastrería. Tiene mano firme con la aguja para bordar togas y, además, sutura que es un portento. A mí el otro día me cosió el brazo.\n\nBúscalo detrás de los cotorreantes nobles del Bancal de Artesanos, en el lado oeste de Dazar\'alor.', 28153),
(159994, 'esES', '¡Prueba cuando quieras y lo comprobarás con tus propios ojos!\n', '', 28153),
(159993, 'esES', 'Voy a decir una obviedad: Rina la Desolladora es sin duda una de las mejores del mundo. ¿Has visto la fauna que hay por aquí?\n\nBúscala en el Bancal de Artesanos, en la base de la pirámide del lado oeste de Dazar\'alor.', 'Voy a decir una obviedad: Rina la Desolladora es sin duda una de las mejores del mundo. ¿Has visto la fauna que hay por aquí?\n\nBúscala en el Bancal de Artesanos, en la base de la pirámide del lado oeste de Dazar\'alor.', 28153),
(159992, 'esES', '¿Minería? Qué maravilla. Si yo fuera minero, me pondría a hacerlo en su legendaria \"ciudad de oro\", Atal\'Dazar. Pero que no te pillen, $n.\n\nSi quieres entrenar más, habla con Secott el Forjaoro. Para encontrarlo, dirígete al Bancal de Artesanos, en el lado occidental inferior de Dazar\'alor.', '¿Minería? Qué maravilla. Si yo fuera minera, me pondría a hacerlo en su legendaria \"ciudad de oro\", Atal\'Dazar. Pero que no te pillen, $n.\n\nSi quieres entrenar más, habla con Secott el Forjaoro. Para encontrarlo, dirígete al Bancal de Artesanos, en el lado occidental inferior de Dazar\'alor.', 28153),
(159991, 'esES', '', 'Cuando desees volver a los Claros de Tirisfal del presente, solo tienes que pedirlo.', 28153),
(159990, 'esES', '¡Esto es la bomba! No, en serio, podría volar la cúpula del Palacete de Gallywix...', '', 28153),
(159989, 'esES', 'Cualquier goblin estaría orgulloso...', '', 28153),
(159987, 'esES', 'Una pizca de mi ingrediente secreto... ¡y tachán! ¡Las modificaciones están listas!', '', 28153),
(159986, 'esES', 'Un poco de pólvora... Unas mechas y trocitos de cobre...', '', 28153),
(159985, 'esES', 'Añado un poco de esto... Y lo aplasto muuy bien.', '', 28153),
(159984, 'esES', 'Deja que... Dame un momento, ¿vale?', '', 28153),
(159983, 'esES', 'Uuuh, ¿me has traído azerita? Esto sí que es material del bueno...', '', 28153),
(159982, 'esES', '¿Quieres explosiones? ¡Pues las tendrás! Súbete a una de estas bellezas y date una vuelta con ella.', '', 28153),
(159981, 'esES', '¡Mi poción no se toca!', '¡Mi poción no se toca!', 28153),
(159980, 'esES', 'Don Amable no quiere que hable con adultoh.', '', 28153),
(159979, 'esES', 'De este cosechador averiado cuelgan engranajes y cables rotos.', 'De este cosechador averiado cuelgan engranajes y cables rotos.', 28153),
(159978, 'esES', 'Hay un martillo desgastado en la mesa.', 'Hay un martillo desgastado en la mesa.', 28153),
(159977, 'esES', 'Repara el cosechador.', 'Repara el cosechador.', 28153),
(159976, 'esES', '¿Has visto las armaduras de cuero que llevan los Zandalari? Si deseas aprender sus secretos, vete al Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\nUna vez allí, busca a Xanjo. Es el experto local en peletería.', '¿Has visto las armaduras de cuero que llevan los Zandalari? Si deseas aprender sus secretos, vete al Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\nUna vez allí, busca a Xanjo. Es el experto local en peletería.', 28153),
(159975, 'esES', 'Recupera el martillo.', 'Recupera el martillo.', 28153),
(159974, 'esES', 'Examina las propiedades de la poción.', 'Examina las propiedades de la poción.', 28153),
(159973, 'esES', 'Recuperaremos a Derek... de un modo u otro.', '', 28153),
(159972, 'esES', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', 28153),
(159971, 'esES', 'La botella está llena de un extraño líquido turbulento.', 'La botella está llena de un extraño líquido turbulento.', 28153),
(159970, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCampeón caballero Dirk Espigado\n\nCapitán del Drustvaria', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCampeón caballero Dirk Espigado\n\nCapitán del Drustvaria', 28153),
(159969, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitana del Vendaval Condonador', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitana del Vendaval Condonador', 28153),
(159968, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTeniente coronel Andrew Avrinn\n\nCapitán del Calandria Cantora', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTeniente coronel Andrew Avrinn\n\nCapitán del Calandria Cantora', 28153),
(159967, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Aloysius Millsworth', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Aloysius Millsworth', 28153),
(159966, 'esES', 'Te subes a un barco y acabas en un sitio nuevo y persigues bichitos y animales y terminas en medio de un sitio escalofriante como este. Al menos eso es lo que me pasó a mí. Pero capturé a unos chiquitines interesantes, criaturas que nunca había visto antes aquí. ¿Quieres ver de qué son capaces?', '', 28153),
(159965, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Ava MacArthur', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Ava MacArthur', 28153),
(159964, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Chris Lee', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Chris Lee', 28153),
(159963, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Evan Morris', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Evan Morris', 28153),
(159962, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nTeniente caballero Samuel Robertson', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nTeniente caballero Samuel Robertson', 28153),
(159961, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Eloise Hesterfield', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Eloise Hesterfield', 28153),
(159960, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Sarah Gallows', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Sarah Gallows', 28153),
(159959, 'esES', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendente O\'Keefe', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendente O\'Keefe', 28153),
(159958, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento J. Mills', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento J. Mills', 28153),
(159957, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSargento primero Murgatroyd Smith', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSargento primero Murgatroyd Smith', 28153),
(159956, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Geoffrey Van Houten', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Geoffrey Van Houten', 28153),
(159955, 'esES', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nProveedor Jarrod', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nProveedor Jarrod', 28153),
(159954, 'esES', '¿Tienes una armadura que reparar? Tengo la mejor forja del desierto... Bueno... La única forja del desierto.', '¿Tienes una armadura que reparar? Tengo la mejor forja del desierto... Bueno... La única forja del desierto.', 28153),
(159953, 'esES', '¡El mar se te tragará por completo!', '', 28153),
(159952, 'esES', '', '¿Qué necesitas de los kaldorei?', 28153),
(159951, 'esES', '', '¡Apártate de nuestros archivos! ¡Esta investigación no es para ti!', 28153),
(159950, 'esES', '', 'Que Elune ilumine tu camino.', 28153),
(159949, 'esES', '', 'No pierdas la fe.', 28153),
(159948, 'esES', 'Con todos los elfos de sangre que hemos traído, lo normal sería que entre ellos hubiera habido un joyero, dado que prácticamente son quienes inventaron la profesión. Supongo que los Zandalari no quieren confiarnos sus riquezas.\n\nAsí que si quieres aprender más, tienes que hablar con Seshuli. La encontrarás en la Cámara de los Destellos. Para llegar allí, dirígete al Bancal de Artesanos, en el lado oeste de Dazar\'alor. Luego gírate para encarar la pirámide y enfila uno de los túneles. Allí estará ella.', 'Con todos los elfos de sangre que hemos traído, lo normal sería que entre ellos hubiera habido un joyero, dado que prácticamente son quienes inventaron la profesión. Supongo que los Zandalari no quieren confiarnos sus riquezas.\n\nAsí que si quieres aprender más, tienes que hablar con Seshuli. La encontrarás en la Cámara de los Destellos. Para llegar allí, dirígete al Bancal de Artesanos, en el lado oeste de Dazar\'alor. Luego gírate para encarar la pirámide y enfila uno de los túneles. Allí estará ella.', 28153),
(159947, 'esES', 'Si buscas a alguien que te enseñe algo más sobre los misterios de la inscripción, dirígete al Gran Sello.\n\nUna vez allí, sube al lado este y verás la Sala de Cronistas. Pregunta por la cronista Kizani.', 'Si buscas a alguien que te enseñe algo más sobre los misterios de la inscripción, dirígete al Gran Sello.\n\nUna vez allí, sube al lado este y verás la Sala de Cronistas. Pregunta por la cronista Kizani.', 28153),
(159946, 'esES', 'Herboristería, ¿eh? Vale, conozco a un tipo. Se llama Jahden Fla. Lo encontrarás cuidando su jardín en el Bancal de Artesanos, en el lado occidental inferior de Dazar\'alor.', 'Herboristería, ¿eh? Vale, conozco a un tipo. Se llama Jahden Fla. Lo encontrarás cuidando su jardín en el Bancal de Artesanos, en el lado occidental inferior de Dazar\'alor.', 28153),
(159945, 'esES', '', 'Somos los hijos de Elune.', 28153),
(159944, 'esES', '', 'Ishnu-alah.', 28153),
(159943, 'esES', '', 'La diosa me da fuerzas.', 28153),
(159942, 'esES', 'Hay una Zandalari allá en las orillas de La Plata, al norte de Dazar\'alor. Se llama Tali la Sigilosa y dicen que puede pescar lo que sea desde donde sea.\n\nClaro que, fiel a su nombre, no se jacta de ello, así que deberás decidir tú si realmente es tan buena.', 'Hay una Zandalari allá en las orillas de La Plata, al norte de Dazar\'alor. Se llama Tali la Sigilosa y dicen que puede pescar lo que sea desde donde sea.\n\nClaro que, fiel a su nombre, no se jacta de ello, así que deberás decidir tú si realmente es tan buena.', 28153),
(159941, 'esES', 'Descansad.', 'Descansad.', 28153),
(159940, 'esES', 'No es lo bastante rápido. ¡Sigue practicando!', 'No es lo bastante rápido. ¡Sigue practicando!', 28153),
(159939, 'esES', '¡Abre los ojos! ¡¿Cómo vas a darle a lo que no ves?!', '¡Abre los ojos! ¡¿Cómo vas a darle a lo que no ves?!', 28153),
(159938, 'esES', '¡Qué chapuza! ¡No pararemos hasta que te salga bien!', '¡Qué chapuza! ¡No pararemos hasta que te salga bien!', 28153),
(159937, 'esES', '¡Se te ha caído la munición, Kelada! <suspira> ¡Hazlo bien la próxima vez!', '¡Se te ha caído la munición, Kelada! <suspira> ¡Hazlo bien la próxima vez!', 28153),
(159936, 'esES', '¿Cuándo fue la última vez que limpiaste el rifle, soldado? ¿Es que no sabes hacerlo?', '¿Cuándo fue la última vez que limpiaste el rifle, soldado? ¿Es que no sabes hacerlo?', 28153),
(159935, 'esES', '¡PRESENTAD!', '¡PRESENTAD!', 28153),
(159934, 'esES', '¡ARMAAAAS... al hombro!', '¡ARMAAAAS... al hombro!', 28153),
(159933, 'esES', 'Con razón Gobernalle no logró que la llevaran los suyos. ¡Es un lugar terrorífico!', '', 28153),
(159932, 'esES', 'Eh, tú, ¿alguna vez has visto de qué son capaces estos? Son cazadores de la manada. Acechan a su presa, la distraen y asestan el golpe de gracia. Unas criaturillas feroces. ¡Pero aquí mando yo, y lo saben! ¿Quieres comparar a tus bestias con las mías?', '', 28153),
(159931, 'esES', '$n mastica palomitas.', '$n mastica palomitas.', 28153),
(159930, 'esES', 'Sí, tú a quien buscas es a Shuga Revientatapas en el Bancal de Artesanos. La encontrarás junto a su colega Myxle en el lado oeste de Dazar\'alor, en la base de la pirámide.\n\n¿Qué quieres hacer saltar por los aires?', 'Sí, tú a quien buscas es a Shuga Revientatapas en el Bancal de Artesanos. La encontrarás junto a su colega Myxle en el lado oeste de Dazar\'alor, en la base de la pirámide.\n\n¿Qué quieres hacer saltar por los aires?', 28153),
(159929, 'esES', 'Oh, oh... Esto es malo. Muy malo... ¡Se la han llevado a Fin del Destino!', '', 28153),
(159928, 'esES', 'Ah. ¡Bingo!', '', 28153),
(159927, 'esES', 'Hay pruebas suficientes para encerrarlo de por vida. Pero como está muerto, supongo que no tiene de qué preocuparse.', '', 28153),
(159926, 'esES', 'La encantadora Quinni, elfa de sangre, vino con nosotros. Escucha atentamente. Para dar con ella, tienes que dirigirte a la base del oeste de Dazar\'alor, al Bancal de Artesanos. Una vez allí, gírate para encarar la pirámide y busca una forma de bajar. Hay un túnel que te llevará a un lugar que se llama la Cámara de los Destellos.\n\nLa verdad es que nos hemos traído a un montón de elfos de sangre. Levanta ciertas suspicacias...', 'La encantadora Quinni, elfa de sangre, vino con nosotros. Escucha atentamente. Para dar con ella, tienes que dirigirte a la base del oeste de Dazar\'alor, al Bancal de Artesanos. Una vez allí, gírate para encarar la pirámide y busca una forma de bajar. Hay un túnel que te llevará a un lugar que se llama la Cámara de los Destellos.\n\nLa verdad es que nos hemos traído a un montón de elfos de sangre. Levanta ciertas suspicacias...', 28153),
(159925, 'esES', 'Oro, gemas, mapas del tesoro, notas de rescate... Vaya, vaya, Harlan era todo un pillín.', '', 28153),
(159924, 'esES', 'Admiro tu ética laboral. Buen trabajo.', '', 28153),
(159923, 'esES', '', 'Eso suele ser buena señal. ¿Qué hay dentro?', 28153),
(159922, 'esES', '¡Eh! Fíjate tú... ¡no ha explotado!', '', 28153),
(159921, 'esES', 'Esos tipos de Pantoque tienen que mantener a los ranishus bien alimentados para que sus robots funcionen. Ayuda a los goblins. Cuanto antes acaben, antes se largarán.', '', 28153),
(159920, 'esES', 'Solo un cerrojo más. Espero que no explote...', '', 28153),
(159919, 'esES', 'Vale, vamos a abrir este arcón.', '', 28153),
(159918, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCapitán caballero Ellis R. Ladimore\n\nCapitán del Remolino de las Honduras', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCapitán caballero Ellis R. Ladimore\n\nCapitán del Remolino de las Honduras', 28153),
(159917, 'esES', '¡Revisad... armas!', '¡Revisad... armas!', 28153),
(159916, 'esES', 'Los miembros de la familia real Zandalari nos han prestado a su propia chef. Se llama T\'sarah. La encontrarás en el Gran Sello, arriba, en el lado oeste.\n\nPersonalmente, ni idea de si es buena. No como nada cocinado.', 'Los miembros de la familia real Zandalari nos han prestado a su propia chef. Se llama T\'sarah. La encontrarás en el Gran Sello, arriba, en el lado oeste.\n\nPersonalmente, ni idea de si es buena. No como nada cocinado.', 28153),
(159915, 'esES', 'Allá en el lado occidental inferior de Dazar\'alor encontrarás el Bancal de Artesanos. Allí hay un enorme trol temible Zandalari llamado maestro de forja Zac no sé qué, que estará martilleando un yunque. No tiene pérdida, créeme.', 'Allá en el lado occidental inferior de Dazar\'alor encontrarás el Bancal de Artesanos. Allí hay un enorme trol temible Zandalari llamado maestro de forja Zac no sé qué, que estará martilleando un yunque. No tiene pérdida, créeme.', 28153),
(159914, 'esES', 'Nos hemos traído a la examinadora Alerinda. Está en el Gran Sello, en una sala del lado oeste.\n\nCreo que su gente está desenterrando algún dinosaurio gigante allá al suroeste. Deberías ir a ver si puedes ayudar.', 'Nos hemos traído a la examinadora Alerinda. Está en el Gran Sello, en una sala del lado oeste.\n\nCreo que su gente está desenterrando algún dinosaurio gigante allá al suroeste. Deberías ir a ver si puedes ayudar.', 28153),
(159913, 'esES', '¡Fusileros! ¡A formar!', '¡Fusileros! ¡A formar!', 28153),
(159912, 'esES', '', 'Nos alegramos de que estés a salvo, adalid.', 28153),
(159911, 'esES', '', '¿Qué? Pero si yo no... Es igual.', 28153),
(159910, 'esES', 'Ah, ¡aquí llega nuestra salvación! ¿Ves? Te dije que no le pasaría nada, Taelia. Le gusta tanto preocuparse...', '', 28153),
(159909, 'esES', '', 'Siempre que mi familia va a esas colinas me preocupo.', 28153),
(159908, 'esES', '¡Eh! ¡A ver si afinas un poco esa puntería!', '', 28153),
(159907, 'esES', '', 'Quedan unas pocas granadas, adalid. ¡Lánzaselas!', 28153),
(159906, 'esES', 'Tú buscas a Kumali la Lista. Está en el Bancal de Artesanos, en el lado oeste de Dazar\'alor, cerca del suelo.\n\nTen cuidado. Tiene pinta de ser de esas de cuyo vudú chungo siempre nos alertan los Lanza Negra.', 'Tú buscas a Kumali la Lista. Está en el Bancal de Artesanos, en el lado oeste de Dazar\'alor, cerca del suelo.\n\nTen cuidado. Tiene pinta de ser de esas de cuyo vudú chungo siempre nos alertan los Lanza Negra.', 28153),
(159905, 'esES', 'Si veh a alguien sohpechoso por aquí, me lo diceh. Le sacaré la verdad a golpeh.', '', 28153),
(159904, 'esES', 'Ehta cámara ehtá protegida por Lok la Roca. ¡Nadie la dehvalijará!', '', 28153),
(159903, 'esES', '... Cuando esto acabe, tú yo tenemos que hablar de nuestros intereses comunes.', '', 28153),
(159902, 'esES', '', '¡Ahora toca mi parte favorita!', 28153),
(159901, 'esES', 'Ahora toca mi parte favorita.', '', 28153),
(159900, 'esES', 'Volveremos sanos y salvos..., y también el prisionero.', '', 28153),
(159899, 'esES', 'Por lo vihto hay tesoroh de muy diversoh tipoh. No deja de sorprenderme lo que la gente guarda en ehtah cámarah.', '', 28153),
(159898, 'esES', '', 'Entendido.', 28153),
(159897, 'esES', 'No dejaré que leh pase nada a tuh objetoh de valor, $p.\n\nHe cuhtodiado tesoroh de reyeh, almaceneh de mercadereh, abalorioh de dementeh y lah comidah de dehposeídoh.\n\nSea lo que sea, yo garantizo su seguridad.', '', 28153),
(159896, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nAlférez Alison Flint', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nAlférez Alison Flint', 28153),
(159895, 'esES', 'La última banda que intentó robar ehta cámara ehtá ahora en Vol\'dun..., como todoh loh que lo han intentado.', '', 28153),
(159894, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Jameson Keefe', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Jameson Keefe', 28153),
(159893, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Lorelai Whetstone', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Lorelai Whetstone', 28153),
(159892, 'esES', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado James Simmons', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado James Simmons', 28153),
(159891, 'esES', 'Ehta eh la cámara máh segura de Zandalar. Nada entra ni sale sin mi consentimiento.\n\nSi dejah aquí tuh cosah, dormiráh tranquilamente. Así de sencillo.', '', 28153),
(159890, 'esES', 'Me tomo muy en serio mi trabajo como vigilante de la cámara, $p.\n\nSi tuh intencioneh son buenah, lah míah también.\n\nSi lah tuyah son malah, te ehtrujo en un cajón, te mando pa Vol\'dun y dejo que loh sethrak te den de comer a loh buitreh.\n\n¿Ehtamoh?', '', 28153),
(159889, 'esES', 'A los Zandalari les gustó mi propuesta. Me dejan kedarme y los invito a mi fiesta.', '', 28153),
(159888, 'esES', 'Ve con kuidado si eres de la Alianza y estás en Zandalar.\n\nSi te ven, dioses y guardias te van a atakar.', '', 28153),
(159887, 'esES', 'Muy lejos estamos ambos del hogar. ¿Por qué no te kedas y echas un trago en el Gran Bazar?', '', 28153),
(159886, 'esES', '', 'Astarii... Deprisa. Evacúa la ciudad... antes de que arda...', 28153),
(159885, 'esES', 'Por supuesto. Si buscas ayuda profesional, a la mayoría los encontrarás en el Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\n¿Qué es lo quieres practicar?', 'Por supuesto. Si buscas ayuda profesional, a la mayoría los encontrarás en el Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\n¿Qué es lo quieres practicar?', 28153),
(159884, 'esES', 'Un saurolisco volcó el carro y los suministros salieron despedidos por doquier.', '', 28153),
(159883, 'esES', '', 'Llaman \"viejo lobo\" a Genn, pero yo puedo hacerlo ronronear como un gatito.', 28153),
(159882, 'esES', '', 'Los elfos de la noche salvaron a mi pueblo. Haré todo lo que pueda por ellos.', 28153),
(159881, 'esES', 'Yo me quedaré aquí a acomodar a los caballos.', '', 28153),
(159880, 'esES', '', 'Los kaldorei necesitan nuestra ayuda.', 28153),
(159879, 'esES', '', 'Se acaba el tiempo.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159878, 'esES', '', '¡Gracias! Creo que ya podré volver sola.', 28153),
(159877, 'esES', '', 'Hazlos pagar por esto, adalid.', 28153),
(159876, 'esES', '', 'Tanta sangre inocente...', 28153),
(159875, 'esES', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(159874, 'esES', '¡El feo es mío!', '¡El feo es mío!', 28153),
(159873, 'esES', '¡No hagáis prisioneros!', '¡No hagáis prisioneros!', 28153),
(159872, 'esES', '¡Esto es propiedad de la Alianza! ¡Largo de aquí!', '¡Esto es propiedad de la Alianza! ¡Largo de aquí!', 28153),
(159871, 'esES', '¡Has cometido un error, escoria de la Horda!', '¡Has cometido un error, escoria de la Horda!', 28153),
(159870, 'esES', '', '¡Salva a los que puedas!', 28153),
(159869, 'esES', '', 'Los culpables pagarán por sus crímenes.', 28153),
(159868, 'esES', 'Los demás llegaremos cuando todo esto haya acabado para ayudar con cualquier informe que haga falta.', '', 28153),
(159867, 'esES', '', 'Por la Alianza.', 28153),
(159866, 'esES', '', 'Mi hogar me llama.', 28153),
(159865, 'esES', '', 'Gracias por tu ayuda.', 28153),
(159864, 'esES', '', '¿Puedo ayudarte?', 28153),
(159863, 'esES', '', 'Un reino no es un territorio, sino su gente.', 28153),
(159862, 'esES', '', 'Gilneas agradece tu ayuda.', 28153),
(159861, 'esES', '', 'Saludos, adalid.', 28153),
(159860, 'esES', 'Cuchillo. Garganta. No es tan complicado.', '', 28153),
(159859, 'esES', 'Matar ya es de por sí una buena recompensa. Pero el oro también me vale.', '', 28153),
(159858, 'esES', '$n, avisa cuando quieras que empecemos con los preparativos para volar el barco. Después, quiero que informes al rey Wrynn de nuestro éxito.', '', 28153),
(159857, 'esES', 'Impresionemos a la Jefa de Guerra... y, de paso, hagámonos con una buena recompensa.', '', 28153),
(159856, 'esES', 'Demos a esos salvajes una lección, ¿te parece?', '', 28153),
(159855, 'esES', 'Keeshan, Kelsey, preparad el barco para que explote cuando hayan salido todos.', '', 28153),
(159854, 'esES', 'No perdamos el tiempo.', '', 28153),
(159853, 'esES', 'En la guerra abundan las oportunidades.', '', 28153),
(159852, 'esES', 'Umbric, necesitamos una última falla de Vacío para sacar a todas nuestras tropas de aquí.', '', 28153),
(159851, 'esES', 'Hay que destruir este barco. Shandris, ayuda a las tropas que nos quedan a preparar la retirada.', '', 28153),
(159848, 'esES', 'Me encanta mi trabajo.', '', 28153),
(159847, 'esES', '¿Nos ponemos manos a la obra?', '', 28153),
(159845, 'esES', '¡Mi gente me liberará de vuestras jaulas, como hicieron con la princesa Talanji y Zul!', '', 28153),
(159844, 'esES', 'Me encantaría ver cómo lo intentan. Ahora, pasemos a otros asuntos.', '', 28153),
(159843, 'esES', 'Puedes resistirte a nosotros o cooperar, la decisión es tuya.', '', 28153),
(159842, 'esES', 'Yo me encargo.', 'Yo me encargo.', 28153),
(159841, 'esES', 'No. Ya se ha derramado suficiente sangre por hoy, capitán. Vamos a devolverte a Ventormenta como prisionero.', '', 28153),
(159840, 'esES', '¡Perros de la Alianza! ¡Matadme y acabad con esto de una vez!', '', 28153),
(159839, 'esES', '', 'El capitán Zalkran intentaba huir a Zuldazar, pero Falstad y yo lo redujimos.', 28153),
(159838, 'esES', 'Shandris, ¿puedes informarme de la situación?', 'Shandris, ¿puedes informarme de la situación?', 28153),
(159837, 'esES', '¿Puedes devolverme al presente?', '¿Puedes devolverme al presente?', 28153),
(159836, 'esES', '¿Puedes mostrarme cómo eran los Claros de Tirisfal antes de la Batalla por Lordaeron?', '¿Puedes mostrarme cómo eran los Claros de Tirisfal antes de la Batalla por Lordaeron?', 28153),
(159835, 'esES', '', 'Ah... Y si ves a mi nieto, Charles, asegúrate de que no está muerto de miedo debajo de algún árbol.', 28153),
(159834, 'esES', '¿Has empezado a capturar a las mascotas que ofrece esta extraña tierra? Personalmente, ando detrás de una de esas máscaras tiki de sangre, aunque no sé cómo se lo tomará la gente del lugar.\n\nSi buscas un maestro de establos, hay un Zandalari que se hace llamar cuidabestias Kalatak cerca de la base noroeste de Dazar\'alor.', '¿Has empezado a capturar a las mascotas que ofrece esta extraña tierra? Personalmente, ando detrás de una de esas máscaras tiki de sangre, aunque no sé cómo se lo tomará la gente del lugar.\n\nSi buscas un maestro de establos, hay un Zandalari que se hace llamar cuidabestias Kalatak cerca de la base noroeste de Dazar\'alor.', 28153),
(159833, 'esES', 'La tripulación del Princesa Púrpura se ha declarado en huelga. ¿Algo acerca de que llevan once años sin cobrar? No estaba prestando atención.', 'La tripulación del Princesa Púrpura se ha declarado en huelga. ¿Algo acerca de que llevan once años sin cobrar? No estaba prestando atención.', 28153),
(159832, 'esES', '¿Cómo puedo ir a la Vega de Tuercespina?', '¿Cómo puedo ir a la Vega de Tuercespina?', 28153),
(159831, 'esES', '', 'Adalid, parece que vuelvo a necesitar tu ayuda.', 28153),
(159830, 'esES', '', 'Gracias de nuevo, $gcampeón:campeona;, aunque puede que el peligro aún no haya pasado.', 28153),
(159829, 'esES', '', 'Sí, madre. Volveré con ellos en breve.', 28153),
(159828, 'esES', '', 'Taelia, adalid, ¡reunid a la milicia! Jaina y yo prepararemos las defensas.', 28153),
(159827, 'esES', '', 'Adalid, parece que vuelvo a necesitar tu ayuda.', 28153),
(159826, 'esES', '', 'Priscilla ha vuelto a por mi ciudad...', 28153),
(159825, 'esES', '', 'O... ¿hemos llegado demasiado tarde?', 28153),
(159824, 'esES', '', 'Dime lo que has encontrado. ¿Había alguna pista de Jaina?', 28153),
(159823, 'esES', '', '¡Adalid! Veo que nadie te acompaña...', 28153),
(159822, 'esES', '', 'El carro está destrozado y podíamos habernos matado.\n\nLa bestia que nos atacó está en esa cueva. ¡No pienso irme hasta verla muerta!', 28153),
(159821, 'esES', '', '¡Lady Almirante! ¡Barcos a la vista! ¡Y llevan los colores de los Gobernalle!', 28153),
(159820, 'esES', '', 'Madre... yo...', 28153),
(159819, 'esES', '', 'A ver si esta vez consigo hacerlo bien... Bienvenida a casa, hija mía.', 28153),
(159818, 'esES', '', 'Adoro la brisa marina... Gracias, adalid. Sin tu intervención, tal vez jamás la hubiera sentido de nuevo.', 28153),
(159817, 'esES', '¡Saludos, $gInquisidor:Inquisidora;!\n\nLady Crestavía me ha ordenado preparar mi halcón más veloz para que envíes un mensaje.', '', 28153),
(159816, 'esES', 'Avisa a Katherine Valiente para que se reúna conmigo en Gol Inath.', 'Avisa a Katherine Valiente para que se reúna conmigo en Gol Inath.', 28153),
(159815, 'esES', 'Quiero saber cómo entrar en las Tierras Contagiadas.', 'Quiero saber cómo entrar en las Tierras Contagiadas.', 28153),
(159814, 'esES', '', 'Protégela con tu vida. Kul Tiras ya ha perdido a demasiados Valiente.', 28153),
(159813, 'esES', '', '¡Lo has conseguido! ¡La efigie ha funcionado!', 28153),
(159812, 'esES', '', '¡Eso es! ¡Las marcas de la pared muestran la secuencia!', 28153),
(159811, 'esES', '', 'Quizás haya que activar las runas siguiendo un patrón determinado...', 28153),
(159810, 'esES', '', 'Eso no ha parecido muy agradable...', 28153),
(159809, 'esES', '', 'Intenta activar otra.', 28153),
(159808, 'esES', '', '¡Se ha esfumado! Tal vez estas runas funcionen como resguardos.', 28153),
(159807, 'esES', '', 'Bueno... Por aquí debe de haber alguna pista sobre cómo funciona esto.', 28153),
(159806, 'esES', '', 'Bueno... Algo ha hecho...', 28153),
(159805, 'esES', '', 'Esto parece una especie de puerta. ¿Y si colocamos aquí la efigie?', 28153),
(159804, 'esES', '', 'Debo armarme de valor. Jaina ha afrontado cosas peores por mi culpa...', 28153),
(159803, 'esES', '', 'Este lugar me da escalofríos. Es como caminar sobre mi propia tumba...', 28153),
(159802, 'esES', '', 'Parece que solo quedamos tú y yo. Te sigo.', 28153),
(159801, 'esES', '', 'Esos... monstruos del bosque le tendieron una emboscada a mi guardia de honor. Sobreviví gracias a su sacrificio.', 28153),
(159800, 'esES', '', '¡Adalid! ¡Cuánto me alegro de verte!', 28153),
(159799, 'esES', '¡A tus órdenes! ¡Hannibal llevará tu mensaje al Fuerte Valiente de inmediato!', '', 28153),
(159798, 'esES', 'Ya estás a salvo.', 'Ya estás a salvo.', 28153),
(159797, 'esES', '', 'Sé que Katherine pretende acompañarte en esta búsqueda disparatada.', 28153),
(159796, 'esES', 'Ese Nocheterna escalofriante, Oculeth, nos hizo portales a Orgrimmar, Ciudad de Lunargenta y Cima del Trueno. Los encontrarás en la Cámara de Sendas Ancestrales, dentro del Gran Sello del lado este.\n\nPor desgracia no hay portal a Entrañas. ¡Pronto nos vengaremos de la escoria de la Alianza! ¡Genn, Jaina y el rey Anduin pagarán por sus crímenes!\n\n¡Victoria para Sylvanas! ¡Que su reinado como Jefa de Guerra dure mil años!', 'Ese Nocheterna escalofriante, Oculeth, nos hizo portales a Orgrimmar, Ciudad de Lunargenta y Cima del Trueno. Los encontrarás en la Cámara de Sendas Ancestrales, dentro del Gran Sello del lado este.\n\nPor desgracia no hay portal a Entrañas. ¡Pronto nos vengaremos de la escoria de la Alianza! ¡Genn, Jaina y el rey Anduin pagarán por sus crímenes!\n\n¡Victoria para Sylvanas! ¡Que su reinado como Jefa de Guerra dure mil años!', 28153),
(159795, 'esES', 'El camino hacia Thros será traicionero y, sin embargo, no será más que una fracción de lo que te espera en las Tierras Contagiadas.\n\nPrepárate, $c, pues los esbirros de Thros emplearán tus mayores miedos y pesares contra ti.', '', 28153),
(159794, 'esES', 'La entrada a Thros se halla en el gran árbol, Gol Inath, pero cruzar el umbral no será tan sencillo como pasar caminando sin más.\n\nPara abrir el camino necesitarás una efigie de gran fuerza. No uno de los abalorios del aquelarre, ojo, sino uno de antigua magia Drust.', '', 28153),
(159793, 'esES', '', 'El carro volcó. ¡Fue horrible!\n\nVolví hacia la ciudad a por ayuda, pero tenía mucho miedo.', 28153),
(159792, 'esES', 'Ah, me alegra ver a $gotro seguidor:otra seguidora; del camino.\n\n¿Qué quieres de los Hablaespinas?', '', 28153),
(159791, 'esES', '¿Así que ha vuelto $gel:la; continental?\n\nCreo que nuestra deuda está saldada. ¿Vienes en busca de nuevos favores por parte de los Hablaespinas?', '', 28153),
(159790, 'esES', 'Hacía mucho que un continental no hollaba mi arboleda.\n\n¿Quieres aprender de los Hablaespinas, o has venido a reclamar esta tierra, como tanto les gusta hacer a los tuyos?', '', 28153),
(159789, 'esES', 'Esto... cambia las cosas.', '', 28153),
(159788, 'esES', 'Por lo visto me equivocaba. Thros ha venido a nosotros.', '', 28153),
(159787, 'esES', 'Esto no ha acabado, viejo oso.', '', 28153),
(159786, 'esES', 'Me aseguraré de que estén a salvo.', 'Me aseguraré de que estén a salvo.', 28153),
(159785, 'esES', '¿Quién eres tú para juzgar quién es digno? ¡Tus malas artes deshonraron a los nuestros, Tul!', '', 28153),
(159784, 'esES', '¿Estás dispuesto a compartir nuestros dones con estos miserables, Ulfar? ¡Mereces arder con ellos!', '', 28153),
(159783, 'esES', '¿Cómo puedo ir al Fiordo Aquilonal?', '¿Cómo puedo ir al Fiordo Aquilonal?', 28153),
(159782, 'esES', 'Hablaespinas, ¡a las armas!', '', 28153),
(159781, 'esES', 'Perdimos el contacto con el Besanubes en algún punto del Mare Magnum. Íbamos a por un récord, ¡ochocientos quince vuelos sin repostar! Seguro que están bien.', 'Perdimos el contacto con el Besanubes en algún punto del Mare Magnum. Íbamos a por un récord, ¡ochocientos quince vuelos sin repostar! Seguro que están bien.', 28153),
(159780, 'esES', '¡Gorak Tul! ¡No puede ser!', '', 28153),
(159779, 'esES', 'Creo que es un poco tarde para eso, viejo oso.', '', 28153),
(159778, 'esES', 'Es preferible que algunos senderos permanezcan cerrados, así se evita que los recorran quienes están al otro lado.', '', 28153),
(159777, 'esES', 'Me temo que en eso no puedo ayudarte, continental.', '', 28153),
(159776, 'esES', '¿Deseas entrar en Thros? Me temo que no puedo ayudarte.', '', 28153),
(159775, 'esES', '', 'No estarás pensando de verdad en ir a las Tierras Contagiadas, ¿no?', 28153),
(159774, 'esES', '', '¡He recibido noticias de Katherine!', 28153),
(159773, 'esES', '', 'Fui yo quien la llevó hasta este destino. Y allí estaré para enmendarlo.', 28153),
(159772, 'esES', '', 'Si encuentras... Cuando encuentres a Jaina, quiero estar allí. Haré frente a cualquier peligro.', 28153),
(159771, 'esES', '', 'Una cosa más, adalid.', 28153),
(159770, 'esES', 'Un saurolisco asustó a los caballos, el carro volcó y perdimos los suministros.\n\nMis dos chicas, Lorraine y Mallory, siguen allí. Les vendría bien tu ayuda.', '', 28153),
(159769, 'esES', 'Allí es adonde iré con algunos de los demás cuando acabe nuestro turno. Hay que estar alerta.\n\nEstá en la Armería Real, en la parte norte de Dazar\'alor, cerca de la base de la pirámide. ¿Por qué no te vienes?', 'Allí es adonde iré con algunos de los demás cuando acabe nuestro turno. Hay que estar alerta.\n\nEstá en la Armería Real, en la parte norte de Dazar\'alor, cerca de la base de la pirámide. ¿Por qué no te vienes?', 28153),
(159768, 'esES', '', '¡Busca al hermano Pike! Es un Sabiomar leal y devoto. Estoy segura de que nos ayudará.', 28153),
(159767, 'esES', '', 'Al fin y al cabo, actuaba bajo mis órdenes.', 28153),
(159766, 'esES', '', 'Solo los Sabiomar pueden acercarse a ella sin problemas. Seguro que a lady Gobernalle no le costó convencerlos de que llevaran a Jaina hasta allí.', 28153),
(159765, 'esES', '', 'Dime que no es demasiado tarde...', 28153),
(159764, 'esES', '', '¿Dónde se han llevado a Jaina?', 28153),
(159763, 'esES', 'Sí. Yo también.', '', 28153),
(159762, 'esES', '', 'Flynn, ya sabes a lo que me refiero. Por el bien de lady Katherine, espero que te equivoques.', 28153),
(159761, 'esES', '¿Ahora te ha dado por apostar? ¡Qué vergüenza! ¿Qué diría Cyrus?', '', 28153),
(159760, 'esES', 'Supongo que tienes asuntos pendientes con los Lanza Negra, ¿no? Sabes que el barco va a las Islas del Eco, ¿verdad? ¿O es que quieres irte de excursión antes de regresar a Orgrimmar?\n\n¿No? Vale, por suerte para ti les prestamos uno de nuestros pequeños buques de guerra. Lo verás al final del muelle, al sur del Puerto de Zandalar.', 'Supongo que tienes asuntos pendientes con los Lanza Negra, ¿no? Sabes que el barco va a las Islas del Eco, ¿verdad? ¿O es que quieres irte de excursión antes de regresar a Orgrimmar?\n\n¿No? Vale, por suerte para ti les prestamos uno de nuestros pequeños buques de guerra. Lo verás al final del muelle, al sur del Puerto de Zandalar.', 28153),
(159759, 'esES', '', 'Si hay alguien capaz de salvarla de ese horrible lugar, me juego lo que sea a que eres tú, adalid.', 28153),
(159758, 'esES', 'La isla se llama Fin del Destino, Taelia. No Esperanza del Destino.', '', 28153),
(159757, 'esES', 'Buen trabajo. Reagrupémonos.', '', 28153),
(159756, 'esES', 'Puedo llevarte al Llanto del Alma en Pena, $p. ¡Pero tendrás que agarrarte bien!', '', 28153),
(159755, 'esES', 'Martillo Salvaje, dispersaos y despejad el cielo, pero evitad que os vean por ahora.', '', 28153),
(159750, 'esES', '', 'Ja... El capitán... oh... matará a todoh...', 28153),
(159749, 'esES', '', '¡Llegáih tarde! El capitán ya ehtá informando de vuehtra ubicación a la princesa Talanji.', 28153),
(159748, 'esES', 'Precisamente conozco al goblin adecuado. Se llama Myxle Sacatripas. Lo encontrarás junto a su Supertrituradora Mk1 en el Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\nSegún él, su aparato puede descomponer cualquier equipo en piezas para reutilizarlas o venderlas. Yo iba a aceptar su oferta, pero esta armadura es de la Horda.', 'Precisamente conozco al goblin adecuado. Se llama Myxle Sacatripas. Lo encontrarás junto a su Desguazachatarra 1000 en el Bancal de Artesanos, en la parte occidental inferior de Dazar\'alor.\n\nSegún él, su aparato puede descomponer cualquier equipo en piezas para reutilizarlas o venderlas. Yo iba a aceptar su oferta, pero esta armadura es de la Horda.', 28153),
(159747, 'esES', 'Para llegar al Trono Dorado, tienes que subir en los ascensores que hay dentro del Gran Sello.\n\n¿Te llevas bien con los miembros de la familia real? ¿Qué te parecen esos tocados? ¡Hay que tener un cuello robusto!', 'Para llegar al Trono Dorado, tienes que subir en los ascensores que hay dentro del Gran Sello.\n\n¿Te llevas bien con los miembros de la familia real? ¿Qué te parecen esos tocados? ¡Hay que tener un cuello robusto!', 28153),
(159746, 'esES', 'Este lugar es enorme, eso hay que reconocerlo. Sé de unos cuantos sitios si buscas algo interesante.', 'Este lugar es enorme, eso hay que reconocerlo. Sé de unos cuantos sitios si buscas algo interesante.', 28153),
(159745, 'esES', 'Brillin la Bella está en el centro del Gran Sello. ¿Verdad que baila de maravilla?', 'Brillin la Bella está en el centro del Gran Sello. ¿Verdad que baila de maravilla?', 28153),
(159744, 'esES', 'Hay una Zandalari llamada Paku\'ai que ofrece vuelos. Si quieres un pterrordáctilo, la encontrarás en el saliente frente al Gran Sello, en la parte oriental.', 'Hay una Zandalari llamada Paku\'ai que ofrece vuelos. Si quieres un pterrordáctilo, la encontrarás en el saliente frente al Gran Sello, en la parte oriental.', 28153),
(159743, 'esES', 'Supongo que eso depende de a qué emisario busques, $n.', 'Supongo que eso depende de a qué emisario busques, $n.', 28153),
(159742, 'esES', '¿Te llevas bien con los Zandalari? Muy hábil. Es justo lo que quiere la Jefa de Guerra.\n\nEncontrarás a su emisario Natal\'hakata dentro del Gran Sello.', '¿Te llevas bien con los Zandalari? Muy hábil. Es justo lo que quiere la Jefa de Guerra.\n\nEncontrarás a su emisario Natal\'hakata dentro del Gran Sello.', 28153),
(159741, 'esES', '¿Buscas averiguar secretos de los tortolianos? Dicen que viven una eternidad. No tanto como lo haré yo, pero no deja de ser mucho tiempo.\n\nEn cualquier caso, debes dirigirte al Puesto Proveescamas, al noreste de Dazar\'alor. Busca al recolector Kajo.', '¿Buscas averiguar secretos de los tortolianos? Dicen que viven una eternidad. No tanto como lo haré yo, pero no deja de ser mucho tiempo.\n\nEn cualquier caso, debes dirigirte al Puesto Proveescamas, al noreste de Dazar\'alor. Busca al recolector Kajo.', 28153),
(159740, 'esES', 'Por supuesto. Un estilo distinto. ¿O tal vez otro color? Tú a quien buscas es a Conner Zumbacorte, en el Gran Bazar del puerto.', 'Por supuesto. Un estilo distinto. ¿O tal vez otro color? Tú a quien buscas es a Conner Zumbacorte, en el Gran Bazar del puerto.', 28153),
(159739, 'esES', '¿Por qué nunca me toca a mí montar en el grifo?', '', 28153),
(159738, 'esES', '¡No tan bajo! ¡No tan bajo!', '', 28153),
(159737, 'esES', '', 'Bajaré un poco para intentar perderlos. Alatifón, ¡abajo!', 28153),
(159736, 'esES', '¡Aguantar es todo lo que puedo hacer de momento!', '', 28153),
(159735, 'esES', '', '¡Aguantad! ¡Nos disparan!', 28153),
(159734, 'esES', 'La Tesorería Real se encuentra en la pirámide de la parte oeste del Gran Sello. Íbamos a dotarla de goblins, pero los Zandalari se negaron.\n\nSon muy listos.', 'La Tesorería Real se encuentra en la pirámide de la parte oeste del Gran Sello. Íbamos a dotarla de goblins, pero los Zandalari se negaron.\n\nSon muy listos.', 28153),
(159733, 'esES', '¿Quiereh ir a lah Ihlah del Eco? ¿Por qué? Allí eh donde viven loh Lanza Negra. Un sitio diminuto. Quédate en Zandalar. Eh grande.\n\n¿No? Vale, por suerte pa ti leh prehtamoh uno de nuehtroh pequeñoh buqueh de guerra. Lo veráh al final del muelle, al sur del Puerto de Zandalar.', '¿Quiereh ir a lah Ihlah del Eco? ¿Por qué? Allí eh donde viven loh Lanza Negra. Un sitio diminuto. Quédate en Zandalar. Eh grande.\n\n¿No? Vale, por suerte pa ti leh prehtamoh uno de nuehtroh pequeñoh buqueh de guerra. Lo veráh al final del muelle, al sur del Puerto de Zandalar.', 28153),
(159732, 'esES', 'Barco a las Islas del Eco', 'Barco a las Islas del Eco', 28153),
(159731, 'esES', 'El supervisor Al\'jibo de loh Lanza Negra se halla en la Cámara de Sendah Ancehtraleh, en la parte oriental del Gran Sello. No puedo rehponder por él, porque vino con la Horda, pero seguro que puede repararte lah abolladurah y afilarte lah armah.\n\nY si no, no tardaráh en ver a Bwonsamdi.', 'El supervisor Al\'jibo de loh Lanza Negra se halla en la Cámara de Sendah Ancehtraleh, en la parte oriental del Gran Sello. No puedo rehponder por él, porque vino con la Horda, pero seguro que puede repararte lah abolladurah y afilarte lah armah.\n\nY si no, no tardaráh en ver a Bwonsamdi.', 28153),
(159730, 'esES', 'Si nos necesitas otra vez, aléjate de la embarcación y envía una señal. Alapresta y yo te encontraremos.', '', 28153),
(159729, 'esES', '¡Ja! ¡Esta parte me encanta!', '', 28153),
(159728, 'esES', 'Allá vamos, Alapresta. Llévanos volando bajo para que no nos descubran. Y lo más rápido que puedas.', '', 28153),
(159727, 'esES', 'Reparaciones', 'Reparaciones', 28153),
(159726, 'esES', 'Claro que tieneh oro pa gahtar. ¡Ehto eh Zandalar! Ni loh goblinh tienen tanto oro como nosotroh.\n\nBueno, ¿qué buhcah?', 'Claro que tieneh oro pa gahtar. ¡Ehto eh Zandalar! Ni loh goblinh tienen tanto oro como nosotroh.\n\nBueno, ¿qué buhcah?', 28153),
(159725, 'esES', 'Vendedores', 'Vendedores', 28153),
(159724, 'esES', '', 'Yo exploraré el Borrasca Carmesí mientras tú exploras el Llanto del Alma en Pena. ¡Tor ilisar\'thera\'nal!', 28153),
(159723, 'esES', '', 'Estamos cerca. Huelo el hedor de la no-muerte.', 28153),
(159722, 'esES', 'Vuehtro elfo Nocheterna ha ehtado usando su vudú en la Cámara de Sendah Ancehtraleh, que se encuentra en la parte ehte del interior del Gran Sello.\n\nHa dado con un conjuro para que podáih volver a vuehtrah diminutah ciudadeh. ¿Cómo se llamaban? ¿Orgrimmar, Ciudad de Lunargenta y Cima del Trueno? Hum.', 'Vuehtro elfo Nocheterna ha ehtado usando su vudú en la Cámara de Sendah Ancehtraleh, que se encuentra en la parte ehte del interior del Gran Sello.\n\nHa dado con un conjuro para que podáih volver a vuehtrah diminutah ciudadeh. ¿Cómo se llamaban? ¿Orgrimmar, Ciudad de Lunargenta y Cima del Trueno? Hum.', 28153),
(159721, 'esES', 'Portales', 'Portales', 28153),
(159720, 'esES', '¿Cómo has acabado aquí?', '¿Cómo has acabado aquí?', 28153),
(159719, 'esES', '¡Vamos allá! Seguro que aquí dentro está la información sobre el paradero de Jaina.\n\n<Flynn señala el arcón>.\n\nTú tienes las llaves: haz los honores.', '', 28153),
(159718, 'esES', '', '¡Llegas tarde!', 28153),
(159717, 'esES', '', 'Aun así... lo he conseguido.', 28153),
(159716, 'esES', '¿Así que quiereh practicar? Aquí en Dazar\'alor tenemoh muchoh muñecoh de entrenamiento. Solo tieneh que ir a la Armería Real.\n\nEhtá en la cara norte de la pirámide de Dazar\'alor.', '¿Así que quiereh practicar? Aquí en Dazar\'alor tenemoh muchoh muñecoh de entrenamiento. Solo tieneh que ir a la Armería Real.\n\nEhtá en la cara norte de la pirámide de Dazar\'alor.', 28153),
(159715, 'esES', '<Zenbaro tose>.', '', 28153),
(159714, 'esES', 'Muñecos de entrenamiento', 'Muñecos de entrenamiento', 28153),
(159713, 'esES', '', 'Cuando desees volver a las Tierras Altas de Arathi del presente, solo tienes que pedirlo.', 28153),
(159712, 'esES', 'Necesitaré que me cubras mientras realizo este ritual. No tardaré mucho.', '', 28153),
(159711, 'esES', '¿Puedes devolverme al presente?', '¿Puedes devolverme al presente?', 28153),
(159710, 'esES', '<Darle la cantimplora a Zenbaro>.', '<Darle la cantimplora a Zenbaro>.', 28153),
(159709, 'esES', 'De acuerdo, $n. Acabemos con esto.', '', 28153),
(159708, 'esES', '¿Puedes mostrarme cómo eran las Tierras Altas de Arathi antes de que estallara la guerra?', '¿Puedes mostrarme cómo eran las Tierras Altas de Arathi antes de que estallara la guerra?', 28153),
(159707, 'esES', '', '¡Aquí está tu nombre! Ve arriba, al despacho al final del pasillo. El señor Camden te verá allí.', 28153),
(159706, 'esES', '', 'La guerra arrasa estas tierras; la historia se repite una vez más. Los caminos del tiempo siempre son cíclicos.\n\nLo siento, a veces olvido que tú los tuyos sois muy... lineares.\n\n¿En qué puedo ayudarte?', 28153),
(159705, 'esES', '', 'Lo siento, pero aquí no entra nadie sin cita. ¡Guardias!', 28153),
(159704, 'esES', 'Sí, tengo una cita. A nombre de M. Arbor.', 'Sí, tengo una cita. A nombre de M. Arbor.', 28153),
(159703, 'esES', '¿No sabes quién soy? ¡Soy $n, campeón de la Alianza! ¡Necesito ver tus archivos, ya!', '¿No sabes quién soy? ¡Soy $n, campeona de la Alianza! ¡Necesito ver tus archivos, ya!', 28153),
(159702, 'esES', 'Tengo una cita con tu jefe. ¡Es muy importante que hable con él de inmediato!', 'Tengo una cita con tu jefe. ¡Es muy importante que hable con él de inmediato!', 28153),
(159701, 'esES', '', '¿En qué puedo ayudarte?', 28153),
(159700, 'esES', '', '$gBienvenido:Bienvenida; a las oficinas de la Compañía Comercial Gobernalle. ¿Tienes cita?', 28153),
(159699, 'esES', 'Ah, aquí estás, $p. ¡Sube!', '', 28153),
(159698, 'esES', 'Sí. Acabemos ya con esto.', '', 28153),
(159697, 'esES', '', 'Esta tierra rezuma historia. Tengo que enseñarte cómo era durante la época de máximo esplendor del Imperio de Arathor.\n\nMmm... Pero supongo que eso tendrá que esperar.\n\n¿Has puesto en orden tus asuntos pasados, adalid?', 28153),
(159696, 'esES', 'Así es. No voy a decir que sea la mejor solución, pero es lo que hay.', '', 28153),
(159695, 'esES', 'Mal asunto, ¿eh, Halford? Tener que matar a todos los Zandalari del barco.', '', 28153),
(159694, 'esES', 'Cuando estés $glisto:lista; para empezar el ritual, coloca la llave del mar en el cuenco.', '', 28153),
(159693, 'esES', 'Ehperaba tu regreso con impaciencia, $n.', '', 28153),
(159692, 'esES', 'Empezaba a preocuparme que no volvierah.', '', 28153),
(159691, 'esES', 'Me alegra verte, $n. Reconozco que no creía que volvierah.', '', 28153),
(159689, 'esES', 'Deja que empiece por el principio.\n\nMih primeroh recuerdoh son de loh mejoreh, yendo por ahí con loh malandrineh de Zuldazar.\n\nNo hacíamoh máh que meternoh en líoh, pero no dábamoh pa máh.\n\nRajin era nuehtro líder. Noh acogió y, a cambio, hacíamoh lo que él pedía.\n\nQue solía ser ehtafar a gente en la ciudad o robar de lah arcah del templo de loh loa.', '', 28153),
(159688, 'esES', '', '¡Paso ligero! ¡Estamos en territorio hostil, no en Ventormenta! ¡Vamos a descargar esto y a evacuar a los heridos!', 28153),
(159687, 'esES', '¿No eh eso lo que todoh noh acabamoh preguntando?\n\n<Zenbaro tose>.\n\nLah arenah no me han tratado bien, $n. Mi final ehtá cerca.\n\nTengo la garganta hinchada por el calor del desierto.\n\nTráeme agua frehca del manantial que hay cerca y te contaré mi hihtoria.', '', 28153),
(159686, 'esES', '¿Te refiereh a ese goblin con un dihparatado artilugio del Bancal de Artesanoh? Dice que su Dehguazachatarra 1000 puede dehcomponer lah parteh de cualquier equipo pa hacer otrah cosah.\n\nSolo tieneh que ir a la parte occidental inferior de Dazar\'alor.', '¿Te refiereh a ese goblin con un dihparatado artilugio del Bancal de Artesanoh? Dice que su Dehguazachatarra 1000 puede dehcomponer lah parteh de cualquier equipo pa hacer otrah cosah.\n\nSolo tieneh que ir a la parte occidental inferior de Dazar\'alor.', 28153),
(159685, 'esES', 'Jamáh imaginé que ehte sería mi dehtino. Solo y moribundo en lah dunah.', '', 28153),
(159684, 'esES', 'Desguazador', 'Desguazador', 28153),
(159683, 'esES', 'Aquí es. Bajemos al sótano.', '', 28153),
(159682, 'esES', '¿Qué asuntoh te traen al Trono Dorado? ¿Buhcah una audiencia?\n\nPa subir ahí, usa loh ahcensoreh que hay dentro del Gran Sello.', '¿Qué asuntoh te traen al Trono Dorado? ¿Buhcah una audiencia?\n\nPa subir ahí, usa loh ahcensoreh que hay dentro del Gran Sello.', 28153),
(159681, 'esES', 'El sótano en cuestión debería estar cerca. No perdamos tiempo.', '', 28153),
(159680, 'esES', 'El Trono Dorado', 'El Trono Dorado', 28153),
(159679, 'esES', '¿Todo listo?', '', 28153),
(159678, 'esES', 'Venga, date prisa. Dentro y fuera, antes de que nos descubran.', '', 28153),
(159677, 'esES', '¡En marcha!', '', 28153),
(159676, 'esES', '', 'Ahora mismo.', 28153),
(159675, 'esES', 'Shandris, tienes que patrullar las playas y asegurarte de que no escape ningún superviviente. Falstad se reunirá contigo en cuanto nos haya dejado.', '', 28153),
(159674, 'esES', '', 'Ni nos verán venir.', 28153),
(159673, 'esES', 'Entendido.', '', 28153),
(159672, 'esES', 'Keeshan, Kelsey, usad el portal de Umbric y estableced una zona de desembarco en lo alto del barco.', '', 28153),
(159671, 'esES', 'Como ordenes.', '', 28153),
(159670, 'esES', 'Umbric, abre un portal del Vacío para traer a los enanos Hierro Negro al Llamada de Gral.', '', 28153),
(159669, 'esES', 'Hay que asegurarse de que nadie de ese barco vuelva a Zuldazar, o será el fin de nuestra misión y de todos nosotros.', '', 28153),
(159668, 'esES', 'Estoy listo.', 'Estoy lista.', 28153),
(159667, 'esES', '', '¡Todos los de la academia se burlarán de mí por esto! ¡Ay, Yuke, qué torpe eres!', 28153),
(159666, 'esES', '', '¡Gracias! Soy miembro del Shadopan, en serio. Pero tengo el día libre, ¿vale? Toma un poco de azerita y no le cuentes esto a nadie, por favor.', 28153),
(159665, 'esES', 'Por las olas, esto no lo vi venir. ¿Pereceré aquí?', '', 28153),
(159664, 'esES', 'Te lo agradezco enormemente, debería tener más cuidado en adelante. Un regalo por tu amabilidad.', '', 28153),
(159663, 'esES', '¡Anda, me he acabado arrinconando!', '', 28153),
(159662, 'esES', '¡Ja, ja! ¿Qué es la cartografía sin un poco de aventura, eh? ¿Sin algo de peligro? Sí, ya veo por tu mirada ausente que estás de acuerdo. Ten, esto es para ti. ¡Y ahora debo hacer mapas!', '', 28153),
(159661, 'esES', 'Como dragón me da mucha vergüenza decir esto, pero ¿podrías echarme una mano?', '', 28153),
(159660, 'esES', 'Gracias, $gamigo:amiga;. Estas islas albergan todo tipo de objetos mágicos, dignos de mi tiempo y mi atención. Las trampas me sobran, eso sí.', '', 28153),
(159659, 'esES', 'Ayuda a Dos Calzas, ¡mucha suerte si lo haces!', '', 28153),
(159658, 'esES', '¡Dos Calzas está libre! ¡Hoy tendrás máximo de suerte, $gamigo:amiga;! ¡Es tu destino ahora!', '', 28153),
(159657, 'esES', '', '¡Ay, Pía, otra vez en apuros! Hay que buscar una salida...', 28153),
(159656, 'esES', '', '¡Eres lo más! ¡Pero no pienso dejar de explorar, ni hablar! ¡Yo si no exploro no soy Pía Trabaluz!', 28153),
(159655, 'esES', 'Mecanismos de gratitud activados. Dispensando gratitud. Gratitud dispensada.', '', 28153),
(159654, 'esES', 'Circuitos registrando obstrucción, iniciando modo de ayuda. AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA. Repitiendo.', '', 28153),
(159653, 'esES', '', 'Anda, colega, ¿qué haceh aquí? ¿Me ayudah a salir de ehte fregao?', 28153),
(159652, 'esES', '', 'Eso ehtá mejor. Tieneh la cabeza bien amueblada. Aquí tieneh algo por lo que hah hecho.', 28153),
(159651, 'esES', '¡Tú! ¿Quieres echar una mano? Te prometo que ya NO soy de la Legión. Esos tipos ya no están. Ahora estoy yo solo, Sylvester, el diablillo honrado.', '', 28153),
(159650, 'esES', 'Vaya, gracias de verdad, no sé cómo agradecértelo. Vale, chao, no me sigas.', '', 28153),
(159649, 'esES', '', '¡Hola! ¿Hola? Oh, ah, sí, hola. ¿Puedes ayudarme? No sé qué hacer. Ando muy perdida.', 28153),
(159648, 'esES', '', '¡Gracias! Muchas gracias, de verdad. ¿Sabes dónde estamos? No recuerdo qué hacía. ¿Dónde está mi embarcación? ¿Tenía una?', 28153),
(159647, 'esES', '¡Necesito ayuda! ¿Me oye alguien?', '', 28153),
(159646, 'esES', 'Ah, te lo agradezco, $gamigo pescador:amiga pescadora;. ¿Cómo has llegado tan lejos? Da igual, veo que tienes que irte.', '', 28153),
(159645, 'esES', 'La gran ciudad de Dazar\'alor eh la máh poderosa del mundo. Suh muchoh dihtritoh ehtán llenoh de prodigioh y seducción. Su gente eh la máh fuerte y sabia.\n\n¡Pero ojo con el vudú!', 'La gran ciudad de Dazar\'alor eh la máh poderosa del mundo. Suh muchoh dihtritoh ehtán llenoh de prodigioh y seducción. Su gente eh la máh fuerte y sabia.\n\n¡Pero ojo con el vudú!', 28153),
(159644, 'esES', 'Uf, vaya, parece que esto me supera. Mmmm. Piensa, piensa.', '', 28153),
(159643, 'esES', '¡Ay, gracias, $gamigo:amiga;. No sabría decirte las veces que me ha pasado. ¡Algún día aprenderé! Ja, ja. Pero hoy no, por lo visto. Ten, lo poco que tengo lo compartiré.', '', 28153),
(159642, 'esES', '¡Gregg necesita ayuda! ¡Ayuda para Gregg!', '', 28153),
(159641, 'esES', '¡Tú ayudar Gregg! Gregg muy feliz. ¡Gregg darte rocas! Gregg adorar rocas.', '', 28153),
(159640, 'esES', 'Eh, tú. ¿Ayudas al viejo Frankie? Tal vez él te dé algo que sabe que quieres. ¿Qué me dices?', '', 28153),
(159639, 'esES', 'Uf, eso está mejor. Jamás pensé que me salvaría uno de vosotros, pero la vida tiene esas cosas. Toma un poco de azerita por la molestia y no le digas a nadie que has visto aquí al viejo Frankie.', '', 28153),
(159638, 'esES', '¡Ayyyy! ¡Sí! ¡Mechaluz agradecer! ¡Sí, tomar gemas!', '', 28153),
(159637, 'esES', '¡Tú! ¡Socorro! ¡Ayúdame! ¡Ayuda!', '', 28153),
(159636, 'esES', '¡Ay, brul, una ayudita por aquí!', '', 28153),
(159635, 'esES', 'Me he pasado un poco con los pesos. Gracias, brul.', '', 28153),
(159634, 'esES', 'Emisario del Imperio Zandalari', 'Emisario del Imperio Zandalari', 28153),
(159633, 'esES', '', '¡Oh, vaya, gracias! Eres $gel:la; mejor. Intentaré que no se repita.', 28153),
(159632, 'esES', '', 'Mira en qué te has metido ESTA vez, Karyn. Ay, ¿cómo voy a salir de esta?', 28153),
(159631, 'esES', 'Encontraráh al recolector Kajo allá en el Puehto Proveehcamah, al norehte de la ciudad.\n\nTen cuidado con ese mojo tortoliano. Eh algo fuera de lo común, dehde luego.', 'Encontraráh al recolector Kajo allá en el Puehto Proveehcamah, al norehte de la ciudad.\n\nTen cuidado con ese mojo tortoliano. Eh algo fuera de lo común, dehde luego.', 28153),
(159630, 'esES', 'Emisario de los Buscadores Tortolianos', 'Emisario de los Buscadores Tortolianos', 28153),
(159629, 'esES', 'Sé de máh de uno. ¿A cuál buhcah?', 'Sé de máh de uno. ¿A cuál buhcah?', 28153),
(159628, 'esES', 'Puntos de interés', 'Puntos de interés', 28153),
(159627, 'esES', '$gBienvenido:Bienvenida; a mi humilde morada, $c. Espero que descanses... en paz.', '', 28153),
(159626, 'esES', 'Ya no. Ya te contaré...', '', 28153),
(159625, 'esES', '', 'No hay tiempo para lamentar lo perdido. Los Mag\'har establecerán un nuevo hogar. Aquí.', 28153),
(159624, 'esES', 'El portal a Azeroth permanecerá abierto el tiempo suficiente para que tus soldados se preparen para el viaje y crucen.', '', 28153),
(159623, 'esES', 'Aka\'magosh, Geya\'rah. Informaré a tu madre de tu decisión. Buen viaje, Eitrigg. Y lo mismo te digo, $n.', '', 28153),
(159622, 'esES', '', '¡$gBienvenido:Bienvenida;, $n! Tieneh la avanzada a tuh órdeneh.', 28153),
(159621, 'esES', 'Volve a sentir las piedras de Draenor bajo mis pies en combate... Este ha sido un buen día.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159620, 'esES', '', 'No es la primera vez que abres el camino hacia Draenor. Tengo la convicción de que conseguiremos regresar.', 28153),
(159619, 'esES', 'La magia que te transporta a Azeroth es volátil. Tal vez no pueda llevarte de regreso a casa.', '', 28153),
(159618, 'esES', 'Estamos agradecidos. $n, haz los preparativos para volver a...', '', 28153),
(159617, 'esES', 'Sospechaba que en cuanto establecieras vínculos con ellos en combate, querrías unirte a estos héroes, Geya\'rah. Tienes mi bendición.', '', 28153),
(159616, 'esES', '', 'El Jefe de Guerra puede contener a los draenei y a esos traidores vinculados a la Luz. Los Mag\'har os ayudarán a ganar vuestra guerra y nuestra deuda quedará saldada.', 28153),
(159615, 'esES', '¿Tú, Señora Suprema? Pero ¿qué hay de la lucha de tu gente aquí?', '', 28153),
(159614, 'esES', '', 'A una compañía de voluntarios. Y a mí misma. Con tu permiso, Jefe de Guerra.', 28153),
(159613, 'esES', 'Y en cuanto al asunto de nuestra deuda con vuestra Horda, enviaremos...', '', 28153),
(159612, 'esES', '', 'Han luchado con valor. Reconozco... que fui severa al juzgarte, Eitrigg. Y a ti también, $n.', 28153),
(159611, 'esES', 'Estaremos preparados. ¿Y qué hay de estos héroes de Azeroth? ¿Te han sido de ayuda?', '', 28153),
(159610, 'esES', '', 'Hemos sofocado el ataque draenei, Jefe de Guerra. Pero la Alta Exarca no cederá. Como buena fanática.', 28153),
(159609, 'esES', 'Si los piratas partieron de Fuerte Libre, puede que encontremos más pistas allí. Y creo que sé de alguien que puede ayudarnos.', '', 28153),
(159608, 'esES', '', 'Tal vez tengas razón, Genn... Pero aunque eso sea cierto, no tenemos casi ninguna pista.', 28153),
(159607, 'esES', 'A lo mejor aún no han llegado a su destino, Katherine. Puede que no sea tarde.', '', 28153),
(159606, 'esES', 'Según el contrato, tenían que trasladar a Jaina a otro lugar, no matarla directamente.', '', 28153),
(159605, 'esES', '', '¿Cómo puedes decir algo así?', 28153),
(159604, 'esES', '', 'Volveremos a vernos en el campamento, $n.', 28153),
(159603, 'esES', '', 'Contrató a unos piratas para ejecutar a mi hija, Genn. ¡A unos piratas! ¡La escoria del mar!', 28153),
(159602, 'esES', '', 'Se nos acaba el tiempo y lo único que tenemos es un contrato que firmó Priscilla con unos bandidos de Fuerte Libre.', 28153),
(159601, 'esES', 'Piénsalo bien, Katherine. Puede que sean buenas noticias.', '', 28153),
(159600, 'esES', '', 'Espera... ¿De verdad... eres...?', 28153),
(159599, 'esES', '', 'Estos planes de batalla de la Alianza son solo para nosotros. ¡Hora de morir, trol de sangre!', 28153),
(159598, 'esES', 'Es imposible que... seas un trol... de sangre...', '', 28153),
(159597, 'esES', '¡Trols de sangre! Ja, sois demasiado bobos para entender los secretos de la Alianza.', '', 28153),
(159596, 'esES', '', '¡Tú no... eres... un trol de sangre...!', 28153),
(159595, 'esES', '', '¿Un trol de sangre? Acabaré con esto rápidamente y les llevaré estos planes a los Zandalari.', 28153),
(159594, 'esES', '¡Ahora huelo raro!', '¡No quiero seguir con este juego!', 28153),
(159593, 'esES', '¡Nos los vendió un tipo verde en la orilla!', '¡Nos los vendió un tipo verde en la orilla!', 28153),
(159592, 'esES', '¡La milicia está siempre aquí para protegernos! Bueno, menos ahora. Fueron a una importante reunión con los Sabiomar. A veces dan un poco de miedo, pero el hermano Pike siempre es amable cuando nos visita.', '¡La milicia está siempre aquí para protegernos! Bueno, menos ahora. Fueron a una importante reunión con los Sabiomar. A veces dan un poco de miedo, pero el hermano Pike siempre es amable cuando nos visita.', 28153),
(159591, 'esES', '¡Todo ha sido idea de Grettle!', '¿Quieres uno de mascota?', 28153),
(159590, 'esES', '¿Por qué lo llamaron Canto Tormenta? No los oigo cantar nunca.$b$bMira que son raros los mayores.', '¿Por qué lo llamaron Canto Tormenta? No los oigo cantar nunca.$b$bMira que son raros los mayores.', 28153),
(159589, 'esES', '¿Has probado ya las almejas al vapor? ¡Son una especialidad de Canto Tormenta!', '¿Has probado ya las almejas al vapor? ¡Son una especialidad de Canto Tormenta!', 28153),
(159588, 'esES', '¡Me encanta visitar la Granja de Hidromiel Mildenhall! Mis padres dicen que soy demasiado joven para el hidromiel, pero siempre me regalan un panal.', '¡Me encanta visitar la Granja de Hidromiel Mildenhall! Mis padres dicen que soy demasiado joven para el hidromiel, pero siempre me regalan un panal.', 28153),
(159587, 'esES', 'Me pregunto si me haré grande como mamá o papá. Comen mucha verdura, tal vez yo también debería...', 'Me pregunto si me haré grande como mamá o papá. Comen mucha verdura, tal vez yo también debería...', 28153),
(159586, 'esES', 'Mi mamá y mi papá trabajan duro para que todo el mundo tenga algo de comer. ¡Y la comida está buenísima!', 'Mi mamá y mi papá trabajan duro para que todo el mundo tenga algo de comer. ¡Y la comida está buenísima!', 28153),
(159585, 'esES', '¡Hola, $gseñor:señora;! ¿Eres $gnuevo:nueva; en el valle?', '¡Hola, $gseñor:señora;! ¿Eres $gnuevo:nueva; en el valle?', 28153),
(159584, 'esES', 'Espero que no lo haya visto nadie.', '¡Tú haz como si no hubiera pasado!', 28153),
(159583, 'esES', 'Durante generaciones hemos confiado en la orientación de los Sabiomar. Sin duda el mar les otorga sabiduría.', 'Durante generaciones hemos confiado en la orientación de los Sabiomar. Sin duda el mar les otorga sabiduría.', 28153),
(159582, 'esES', 'He tenido días mejores.', 'Que esto no salga de aquí.', 28153),
(159581, 'esES', '¿Has catado los productos del valle? Prueba nuestro pan recién hecho con salchichas de Drustvar. Riégalo todo con una buena jarra de hidromiel... Se me hace la boca agua solo de pensarlo.', '¿Has catado los productos del valle? Prueba nuestro pan recién hecho con salchichas de Drustvar. Riégalo todo con una buena jarra de hidromiel... Se me hace la boca agua solo de pensarlo.', 28153),
(159580, 'esES', 'Solíamos tener a la milicia para protegernos. ¿Qué habrá hecho que se retire?', 'Solíamos tener a la milicia para protegernos. ¿Qué habrá hecho que se retire?', 28153),
(159579, 'esES', 'Trabajamos en los campos para llenar los estómagos de Kul Tiras. ¡Es un trabajo duro, pero gratificante!', 'Trabajamos en los campos para llenar los estómagos de Kul Tiras. ¡Es un trabajo duro, pero gratificante!', 28153),
(159578, 'esES', 'Tal vez vivamos de la tierra, pero seguimos siendo hijos del mar.', 'Tal vez vivamos de la tierra, pero seguimos siendo hijos del mar.', 28153),
(159577, 'esES', 'Que los mares te guíen, $gforastero:forastera;.', 'Que los mares te guíen, $gforastero:forastera;.', 28153),
(159576, 'esES', '¡$gBienvenido:Bienvenida; al valle!', '¡$gBienvenido:Bienvenida; al valle!', 28153),
(159575, 'esES', 'Ah, $n, ahí estás. Algunos de los Valiente han conseguido pasar. Elimínalos.', '', 28153),
(159574, 'esES', '', 'Me estoy impacientando. Permíteme que ayude desde las sombras.', 28153),
(159573, 'esES', '', 'Mamá, ¿dónde está papá?', 28153),
(159572, 'esES', 'Saludos, $r. ¿Quieres reforjar algo?\n\nEl poder de la azerita es enorme. Por suerte para ti, mis precios no.', '', 28153),
(159571, 'esES', '', 'Vamos, campeones de Azeroth. Debemos informar al Jefe de Guerra de nuestra victoria.', 28153),
(159570, 'esES', '', 'Vuestra Alta Exarca no puede salvaros. ¡Mi gente no dejará de luchar hasta que Draenor sea libre!', 28153),
(159569, 'esES', 'Yrel... Te he fallado...', '', 28153),
(159568, 'esES', 'Esta tierra antaño fértil es ahora polvo sin vida. ¡Eso es lo que vuestro odio ha conseguido!', '', 28153),
(159567, 'esES', '', '¡Nuestras cicatrices no son vuestras!', 28153),
(159566, 'esES', '¡Renuncia a tu odio! ¡La Luz puede sanar las cicatrices de la guerra!', '', 28153),
(159565, 'esES', '', '¡Querrás decir subyugación!', 28153),
(159564, 'esES', '¡Los naaru nos ofrecen paz y orden!', '', 28153),
(159563, 'esES', '¡Por Draenor! ¡Por los Mag\'har!', '', 28153),
(159562, 'esES', '', '¡Basta de cháchara! ¡No hay sentencia como la del campo de batalla!', 28153),
(159561, 'esES', 'La Alta Exarca os ordena que os rindáis... ¡o que os sometáis a su sentencia!', '', 28153),
(159560, 'esES', '', '¡Retiraos mientras aún podáis! ¡No nos impondréis vuestras doctrinas, draenei!', 28153),
(159559, 'esES', '¡Abandonad este absurdo desafío, Mag\'har! ¡Rendíos y abrazad la Luz!', '', 28153),
(159558, 'esES', '¡Estamos contigo, Geya\'rah!', '', 28153),
(159557, 'esES', '', '¡Atacan el Fuerte Sol Eterno! ¡Seguidme, héroes!', 28153),
(159556, 'esES', '¡La Alta Exarca solo desea lo mejor para todos!', '¡La Alta Exarca solo desea lo mejor para todos!', 28153),
(159555, 'esES', 'La Luz nos ha salvado. ¡Como puede salvaros a vosotros!', 'La Luz nos ha salvado. ¡Como puede salvaros a vosotros!', 28153),
(159554, 'esES', 'El tiempo de Grommash ha pasado. ¡Abrazad un nuevo futuro!', 'El tiempo de Grommash ha pasado. ¡Abrazad un nuevo futuro!', 28153),
(159553, 'esES', '¡Acompañadnos en la Luz, hermanos y hermanas!', '¡Acompañadnos en la Luz, hermanos y hermanas!', 28153),
(159552, 'esES', '¡Juntos podemos salvar Draenor!', '¡Juntos podemos salvar Draenor!', 28153),
(159551, 'esES', '¡Habéis arruinado esta tierra! ¡Aún no es tarde para salvarla!', '¡Habéis arruinado esta tierra! ¡Aún no es tarde para salvarla!', 28153),
(159550, 'esES', '¡Haced caso de las visiones de la Alta Exarca!', '¡Haced caso de las visiones de la Alta Exarca!', 28153),
(159549, 'esES', '¡Venimos a salvaros de vuestro salvajismo!', '¡Venimos a salvaros de vuestro salvajismo!', 28153),
(159548, 'esES', '¡Rendíos, Mag\'har! ¡Abrazad la Luz!', '¡Rendíos, Mag\'har! ¡Abrazad la Luz!', 28153),
(159547, 'esES', 'Te doy la bienvenida.', '', 28153),
(159546, 'esES', '', '¡Acabad con la corrupción de la Luz!', 28153),
(159545, 'esES', '', '¡Atrás, draenei! ¡Vuestra Luz no es bienvenida aquí!', 28153),
(159544, 'esES', '', '¡Mantened la posición! ¡Esta tierra pertenece a los Mag\'har!', 28153),
(159543, 'esES', 'Akunda acoge a todo el mundo.', '', 28153),
(159542, 'esES', '', '¡Eliminad esas máquinas de asedio!', 28153),
(159541, 'esES', '', '¡Entonces lucharemos juntos por la sangre y el honor! ¡Seguidme, héroes!', 28153),
(159540, 'esES', 'Nunca he rehuido una batalla. No pienso empezar hoy.', '', 28153),
(159539, 'esES', '', 'Esta no es vuestra lucha, forasteros. Sois libres de regresar a Azeroth.', 28153),
(159538, 'esES', 'Estamos manteniendo la posición, Señora Suprema. Pero el enemigo parece concentrarse para un ataque mayor.', '', 28153),
(159537, 'esES', '', '¡Lantresor! ¡Informa!', 28153),
(159536, 'esES', 'También puedes atacar a tus enemigos con un Disparo con púas y provocar daño de sangrado durante un tiempo.', '', 28153),
(159535, 'esES', '¡Lucharemos a tu lado, Señora Suprema!', '', 28153),
(159534, 'esES', '', '¡No me quedaré de brazos cruzados mientras la Alta Exarca lanza una cruzada contra la libertad de los Mag\'har! ¡Debemos acabar con la tiranía de la Luz!', 28153),
(159533, 'esES', '', 'Algunos orcos incluso se alinearon con los draenei contra los suyos... ¡Hasta perdimos al hijo del Jefe de Guerra! A estos traidores los llamamos vinculados a la Luz.', 28153),
(159532, 'esES', '', 'Sus amos naaru los obligaron a extender su influencia entre los orcos. Unos pocos se convirtieron por voluntad propia. A otros se les impuso la Luz.', 28153),
(159531, 'esES', '', 'Pero sin demonios a los que combatir, los draenei se obsesionaron con su queridísima Luz.', 28153),
(159530, 'esES', '', 'Tras la caída de Archimonde, orcos y draenei colaboraron para expulsar a la Legión de Draenor. Fueron buenos tiempos.', 28153),
(159529, 'esES', '', 'Supongo que os lo habéis ganado.', 28153),
(159528, 'esES', 'Es hora de que expliques quiénes son esos vinculados a la Luz, Señora Suprema.', '', 28153),
(159527, 'esES', '', '¡Bien! Justo quería otra cabeza de exarca para mis muros. ¡Vamos, forasteros!', 28153),
(159526, 'esES', 'Los dirige un exarca. Son... bastante numerosos.', 'Los dirige un exarca. Son... bastante numerosos.', 28153),
(159525, 'esES', '', '¡Malditos traidores! ¿Son numerosas sus fuerzas?', 28153),
(159524, 'esES', '¡Señora suprema Geya\'rah! ¡Los vinculados a la Luz atacan la Avanzada de las Bestias!', '¡Señora suprema Geya\'rah! ¡Los vinculados a la Luz atacan la Avanzada de las Bestias!', 28153),
(159523, 'esES', 'Eso es. Ahora eres... un trol de sangre. Temporalmente al menos.', '', 28153),
(159522, 'esES', 'Pero no podemos arriesgarnos a que vean a un solo miembro de la Alianza en el Puerto de Guerra Rastari.', '', 28153),
(159521, 'esES', 'Te pido disculpas por lo doloroso e indecoroso de este ritual, $n.', '', 28153),
(159520, 'esES', 'Umbric, estoy listo para convertirme en trol de sangre.', 'Umbric, estoy lista para convertirme en trol de sangre.', 28153),
(159519, 'esES', 'Dicen que Pin\'jin eh uno de loh trolh máh pacienteh que hayan exihtido. Como pa no serlo, con tantoh nobleh dándole la vara todo el rato acerca de suh atuendoh.\n\nSi tú tieneh paciencia pa aprender de él, dirígete al Bancal de Artesanoh. Ehtá en la parte oehte de Dazar\'alor.', 'Dicen que Pin\'jin eh uno de loh trolh máh pacienteh que hayan exihtido. Como pa no serlo, con tantoh nobleh dándole la vara todo el rato acerca de suh atuendoh.\n\nSi tú tieneh paciencia pa aprender de él, dirígete al Bancal de Artesanoh. Ehtá en la parte oehte de Dazar\'alor.', 28153),
(159517, 'esES', '¿Creeh que eh fácil dehpellejar un anklyodón? ¡Te equivocah! Si quiereh aprender, debeh entrenar con Rina.\n\nLo último que sé de ella eh que ha vuelto a la ciudad. La encontraráh en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.\n\n¡Pero sé amable o te dehpellejará a ti también!', '¿Creeh que eh fácil dehpellejar un anklyodón? ¡Te equivocah! Si quiereh aprender, debeh entrenar con Rina.\n\nLo último que sé de ella eh que ha vuelto a la ciudad. La encontraráh en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.\n\n¡Pero sé amable o te dehpellejará a ti también!', 28153),
(159515, 'esES', '¿Pa qué buhcah a ese ladrón de Secott? Aún no lo hemoh pillado, ¡pero sabemoh que roba oro de Atal\'Dazar! Loh loa se lo harán pagar. Y si no lo hacen elloh, lo haré yo.\n\nVe a por tu \"amigo\" allá en el Bancal de Artesanoh. Oh ehtaremoh vigilando a amboh.', '¿Pa qué buhcah a ese ladrón de Secott? Aún no lo hemoh pillado, ¡pero sabemoh que roba oro de Atal\'Dazar! Loh loa se lo harán pagar. Y si no lo hacen elloh, lo haré yo.\n\nVe a por tu \"amigo\" allá en el Bancal de Artesanoh. Oh ehtaremoh vigilando a amboh.', 28153),
(159513, 'esES', 'Xanjo toma loh pellejoh que le da Rina y hace algunah de lah mejoreh armadurah que hayah vihto.\n\nPuedeh encontrarlo en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.', 'Xanjo toma loh pellejoh que le da Rina y hace algunah de lah mejoreh armadurah que hayah vihto.\n\nPuedeh encontrarlo en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.', 28153),
(159511, 'esES', 'Nuehtra Seshuli fabrica lah mejoreh joyah de loh Mareh del Sur. Si quiereh que te enseñe, búhcala en la Cámara de loh Dehtelloh.\n\nPa llegar allí, ve al Bancal de Artesanoh, en la parte oehte de Dazar\'alor. Luego tuerce al ehte y enfila el túnel que se adentra en la pirámide. No tiene pérdida, con todah lah cosah brillanteh que hay allí.', 'Nuehtra Seshuli fabrica lah mejoreh joyah de loh Mareh del Sur. Si quiereh que te enseñe, búhcala en la Cámara de loh Dehtelloh.\n\nPa llegar allí, ve al Bancal de Artesanoh, en la parte oehte de Dazar\'alor. Luego tuerce al ehte y enfila el túnel que se adentra en la pirámide. No tiene pérdida, con todah lah cosah brillanteh que hay allí.', 28153),
(159509, 'esES', '', 'Ve a Darnassus en mi hipogrifo. Asegúrate de que la ocupación de la Horda sea... lo más tolerable posible.', 28153),
(159506, 'esES', 'Loh cronihtah viajan mucho pa conocer la verdad del mundo. A ti te interesa hablar con Kizani.\n\nPara encontrarla tieneh que subir lah ehcalerah hahta el Gran Sello. La veráh en la Cámara de loh Cronihtah.', 'Loh cronihtah viajan mucho pa conocer la verdad del mundo. A ti te interesa hablar con Kizani.\n\nPara encontrarla tieneh que subir lah ehcalerah hahta el Gran Sello. La veráh en la Cámara de loh Cronihtah.', 28153),
(159504, 'esES', 'Jahden Fla ehtá siempre cuidando suh floreh en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.\n\nNo bromea cuando dice tener mano pa la plantah.', 'Jahden Fla ehtá siempre cuidando suh floreh en el Bancal de Artesanoh, en la parte oehte de Dazar\'alor.\n\nNo bromea cuando dice tener mano pa la plantah.', 28153),
(159503, 'esES', 'La guerra nos pone a prueba. Nos obliga a examinar nuestro honor, nuestras convicciones.\n\nHe venido a Zuldazar para asegurarnos de que, en mitad de este conflicto, la Horda no pierda de vista lo que nos define, lo que nos hace fuertes.\n\nTengo fe en que tú no lo olvidarás, portavoz de la Horda.', '', 28153),
(159502, 'esES', '¡Necesito hacerme más fuerte!', '', 28153),
(159500, 'esES', 'Espero que te vaya bien, $p.', '', 28153),
(159499, 'esES', 'Gracias a ti, empezaré a entrenar para ser un valiente guerrero. ¡Quiero poder defender nuestra ciudad!', '', 28153),
(159498, 'esES', 'La abuela no deja de decir lo mucho que le gustaría que me pareciera a ti...', '', 28153),
(159497, 'esES', 'Me... alegra que vinieras cuando lo hiciste.', '', 28153),
(159496, 'esES', '¿Quiereh aprender a pehcar? Entonceh tieneh que ver a Tali la Sigilosa, que ehtá pehcando en el Rehquicio Frondoso, al norte de Dazar\'alor.\n\nPero procura no hacer ruido pa no ahuyentarle a loh peceh.', '¿Quiereh aprender a pehcar? Entonceh tieneh que ver a Tali la Sigilosa, que ehtá pehcando en el Rehquicio Frondoso, al norte de Dazar\'alor.\n\nPero procura no hacer ruido pa no ahuyentarle a loh peceh.', 28153),
(159495, 'esES', 'No quiero decepcionar a la abuela, pero esto no es lo mío... Solo quiero que las cosas vuelvan a la normalidad.', '', 28153),
(159494, 'esES', '¡Ojo con la cabeza, que caen piedras del cielo!', '', 28153),
(159492, 'esES', 'En el Bancal de Artesanoh hay una goblin llamada Shuga que enseña esah cosah. Queda por el lado occidental de Dazar\'alor.\n\nMáh vale que no tengah intención de volar nada importante. Noh guhta Zuldazar tal como ehtá.', 'En el Bancal de Artesanoh hay una goblin llamada Shuga que enseña esah cosah. Queda por el lado occidental de Dazar\'alor.\n\nMáh vale que no tengah intención de volar nada importante. Noh guhta Zuldazar tal como ehtá.', 28153),
(159491, 'esES', '¡Me mataron a la vaca!', '¡Me mataron a la vaca!', 28153),
(159489, 'esES', '¡No es mi primera batalla!', '¡No es mi primera batalla!', 28153),
(159488, 'esES', '¡Ayudaré en lo que pueda!', '¡Ayudaré en lo que pueda!', 28153),
(159487, 'esES', '¡Que voy!', '¡Que voy!', 28153),
(159486, 'esES', '¡Les daré su merecido!', '¡Les daré su merecido!', 28153),
(159485, 'esES', '¡Sí! ¡Pagarán por esto!', '¡Sí! ¡Pagarán por esto!', 28153),
(159484, 'esES', 'Buhcah a una encantadora llamada Quinni, una elfa de sangre. La encontraráh en la base occidental de Dazar\'alor, en el Bancal de Artesanoh. Una vez allí, sitúate frente a la pirámide y baja a la Cámara de loh Dehtelloh.', 'Buhcah a una encantadora llamada Quinni, una elfa de sangre. La encontraráh en la base occidental de Dazar\'alor, en el Bancal de Artesanoh. Una vez allí, sitúate frente a la pirámide y baja a la Cámara de loh Dehtelloh.', 28153),
(159482, 'esES', '', '¡El legado de fracasos de los Valiente morirá contigo!', 28153),
(159481, 'esES', '', 'Tu familia siempre lo ha sido.', 28153),
(159480, 'esES', '', '¡Tenemos pruebas!', 28153),
(159479, 'esES', '', 'Yo me encargaré de esta pesada carga. Solo espero ser una sucesora digna.', 28153),
(159478, 'esES', 'Tú buhcah a la chef real, T\'sarah. La encontraráh en Dazar\'alor, en el Ehpositor de Carne Real, junto al Gran Sello.', 'Tú buhcah a la chef real, T\'sarah. La encontraráh en Dazar\'alor, en el Ehpositor de Carne Real, junto al Gran Sello.', 28153),
(159476, 'esES', '', 'He estado hablando con mi querida amiga Priscilla y creo que lo mejor para Kul Tiras es que deje mi cargo de Lady Almirante...', 28153),
(159475, 'esES', '', '¡Katherine Valiente lleva toda su vida haciendo lo mejor para Kul Tiras!', 28153),
(159473, 'esES', '¡Morid, escoria de la Horda!', '¡Morid, escoria de la Horda!', 28153),
(159472, 'esES', '¡Os mandaré de vuelta con vuestra Jefa de Guerra en pedacitos!', '¡Os mandaré de vuelta con vuestra Jefa de Guerra en pedacitos!', 28153),
(159471, 'esES', '¡Jamás nos derrotaréis!', '¡Jamás nos derrotaréis!', 28153),
(159470, 'esES', '¡Boralus no caerá!', '¡Boralus no caerá!', 28153),
(159469, 'esES', '¡Por Boralus!', '¡Por Boralus!', 28153),
(159468, 'esES', 'Agárrate bien, $p. Alapresta nos llevará allí en un periquete.', '', 28153),
(159467, 'esES', '', 'La emoción de la caza... No hay nada igual.', 28153),
(159466, 'esES', '', 'Pa\'ku mira a Kua\'fon y suspira.', 28153),
(159465, 'esES', '¡Vamos allá, Alapresta! De vuelta al cielo, que es lo nuestro.', '', 28153),
(159464, 'esES', 'Cerrando.', 'Cerrando.', 28153),
(159463, 'esES', 'Es IMPRESCINDIBLE que enviemos las órdenes de ignición desde una posición con visibilidad directa de todos los puntos de explosión. Por desgracia, tengo que verificar a mano que todos los parámetros sean correctos, y eso solo lo puedo hacer desde aquí.\n\nEn resumen: necesitamos que te subas a la máquina voladora y que pulses el gran botón rojo cuando yo te lo diga.', '', 28153),
(159462, 'esES', '', 'Basta de preguntas. ¡Andando!', 28153),
(159461, 'esES', '¿Vinculados a la Luz?', '', 28153),
(159460, 'esES', '', 'Mi madre dirige una ciudadela en Nagrand. Mi padre cayó en combate frente a los vinculados a la Luz.', 28153),
(159459, 'esES', 'Eres la hija de Durotan y Draka. Veo a ambos en ti. ¿Tus padres están...?', '', 28153),
(159458, 'esES', '', 'No necesito la ayuda de forasteros... Pero cumpliré tus órdenes. ¡Venid!', 28153),
(159457, 'esES', 'Eitrigg y $n te ayudarán a acabar con el ogro instigador, Geya\'rah.', '', 28153),
(159456, 'esES', 'Durotan estaba en deuda con estos héroes, Geya\'rah, igual que yo. Deshonras al espíritu de tu padre al perder así los estribos. Pero... me has dado una idea...', '', 28153),
(159455, 'esES', '', '¿Nos tomas por tontos? Jefe de Guerra, no podemos ceder nuestros soldados a estos extranjeros. ¡No cuando tenemos nuestros propios enemigos!', 28153),
(159454, 'esES', 'Unos héroes de mi mundo liberaron una vez al tuyo del yugo de unos tiranos. Ahora Azeroth se enfrenta a una amenaza similar, así que hemos venido a que se salde esa deuda.', '', 28153),
(159453, 'esES', 'Pues aquí estamos... Dos viejos fantasmas. ¿Por qué habéis vuelto a Draenor después de tanto tiempo?', '', 28153),
(159452, 'esES', 'Y el Grommash Grito Infernal al que conocí dio la vida por liberarnos de los demonios. Una muerte digna.', '', 28153),
(159451, 'esES', 'Eitrigg... Conocí a un Eitrigg que servía a Puño Negro. Era un orco honorable que murió en una batalla gloriosa.', '', 28153),
(159450, 'esES', 'Así es. Soy Eitrigg y $geste:esta; es $n, $gcampeón:campeona; de la Horda.', '', 28153),
(159449, 'esES', 'Hacía muchos años que no veía a un orco de piel verde. Y $gel:la; que está a tu lado... me resulta familiar. Venís de Azeroth.', '', 28153),
(159448, 'esES', '¡Basta! Ya juzgaré yo a los prisioneros, Geya\'rah.', '', 28153),
(159447, 'esES', '', 'Tus palabras me conmueven, anciano. Seguimos honrando la historia de nuestros clanes, aunque nos hayamos unido como Mag\'har. Pero aún tenéis que demostrar...', 28153),
(159446, 'esES', 'Durotan era el jefe de los Lobo Gélido. Jamás he conocido orco más honorable. Era un auténtico líder que amaba a su pueblo. Echo de menos su sabiduría.', '', 28153),
(159445, 'esES', 'El clan Grito de Guerra luchó durante generaciones contra los ogros. Pese a su gran inferioridad numérica, Grommash Grito Infernal condujo a su gente a una gran victoria sobre Ogrópolis.', '', 28153),
(159444, 'esES', 'Los Roca Negra... Mi propio clan. Éramos orcos orgullosos... Fieros soldados. Pero la magia vil de Gul\'dan nos engañó e hicimos... cosas terribles.', '', 28153),
(159443, 'esES', '', 'Cualquier orco de verdad reconocería los tres estandartes de este campamento. ¡Habladme de ellos o conoceréis la hoja del verdugo!', 28153),
(159442, 'esES', '', 'Solo hay un Jefe de Guerra... ¡y tú no eres Roca Negra! Pero pongamos a prueba tus palabras.', 28153),
(159441, 'esES', 'Soy Eitrigg, del clan Roca Negra. Venimos de Azeroth en nombre de nuestra Jefa de Guerra.', '', 28153),
(159440, 'esES', '', 'Ya veremos. Hablad, intrusos. ¿Quiénes sois?', 28153),
(159439, 'esES', '¡Son espías vinculados a la Luz! ¡Sucios traidores!', '¡Son espías vinculados a la Luz! ¡Sucios traidores!', 28153),
(159438, 'esES', '', 'Tráemelos.', 28153),
(159437, 'esES', '¡Señora suprema Geya\'rah! Tenemos prisioneros.', '', 28153),
(159436, 'esES', 'La Señora Suprema sabrá qué hacer.', 'La Señora Suprema sabrá qué hacer.', 28153),
(159435, 'esES', 'Ten cuidado. Lo mismo son espías enviados por los draenei.', '', 28153),
(159434, 'esES', 'Piel verde... ¡Qué asco! Había oído historias de esta corrupción, pero no la había visto nunca.', 'Piel verde... ¡Qué asco! Había oído historias de esta corrupción, pero no la había visto nunca.', 28153),
(159433, 'esES', '¡Silencio! La Señora Suprema decidirá vuestro destino. ¡Encadenadlos!', '', 28153),
(159432, 'esES', '¡Detente! Venimos en son paz a hablar con tu Jefe de Guerra.', '', 28153),
(159431, 'esES', '¡Intrusos!', '¡Intrusos!', 28153),
(159430, 'esES', '¿Por qué querríah ehcarbar en nuehtra tierra? Si eh necesario, encontraráh a la examinadora Alerinda en el Gran Sello.', '¿Por qué querríah ehcarbar en nuehtra tierra? Si eh necesario, encontraráh a la examinadora Alerinda en el Gran Sello.', 28153),
(159429, 'esES', 'Arqueología', 'Arqueología', 28153),
(159428, 'esES', '¿Qué hace aquí ehte vudú del Vacío?', '¿Qué hace aquí ehte vudú del Vacío?', 28153),
(159427, 'esES', '¿Qué eh ehte vudú?', '¿Qué eh ehte vudú?', 28153),
(159426, 'esES', '¿Qué vudú ohcuro eh ehte?', '¿Qué vudú ohcuro eh ehte?', 28153),
(159425, 'esES', 'Ve. Pero procura no perderte entre los hilos del destino.', '', 28153),
(159424, 'esES', 'Os enviaré el fragmento al otro lado. Cuando estéis listos, os traeré de vuelta.', '', 28153),
(159423, 'esES', '¿Puedes mantener abierta la vía el tiempo suficiente para que hagamos pasar a los orcos de Draenor?', '', 28153),
(159422, 'esES', 'Las corrientes del tiempo y la realidad varían constantemente. El anclaje al mundo que buscas será endeble.', '', 28153),
(159421, 'esES', '¿Cómo puedo ir a Orgrimmar?', '¿Cómo puedo ir a Orgrimmar?', 28153),
(159420, 'esES', 'Nuehtra batalla aquí ha acabado, pero la guerra continúa.', '', 28153),
(159419, 'esES', 'Nuestra Jefa de Guerra no tolerará excusas. Parece que $p debe viajar a Tanaris. Mis viejos huesos necesitan un descanso.', '', 28153),
(159418, 'esES', 'Si el fragmento no estuviera agotado, podría mandarte a tu destino, pero mi especialidad es el teletransporte, no la cronomancia.', '', 28153),
(159417, 'esES', 'Te conviene ir al Bancal de Artesanoh, en la parte occidental inferior de Dazar\'alor.\n\n¡No encontraráh en todo Azeroth a un herrero máh fuerte que el maehtro de forja Zak\'aal!', 'Te conviene ir al Bancal de Artesanoh, en la parte occidental inferior de Dazar\'alor.\n\n¡No encontraráh en todo Azeroth a un herrero máh fuerte que el maehtro de forja Zak\'aal!', 28153),
(159416, 'esES', '', 'Aquí la fauna eh asombrosa. Krag\'wa anda cerca, me pregunto si la presencia de un loa la hace máh fuerte. ¿Quiereh poner a prueba tuh mahcotah contra lah míah?', 28153),
(159415, 'esES', '', 'Pa\'ku se ríe de forma ominosa.', 28153),
(159414, 'esES', '¡Qué alivio!', '¡Qué alivio!', 28153),
(159413, 'esES', '¡El dolor ha desaparecido!', '¡El dolor ha desaparecido!', 28153),
(159412, 'esES', 'Esto ya es otra cosa.', 'Esto ya es otra cosa.', 28153),
(159411, 'esES', 'Será un honor, General. $p, súbete a Alapresta cuando estés $glisto:lista;.', '', 28153),
(159410, 'esES', '', 'Falstad, ve tú delante con $p. Yo iré en Jai\'alator.', 28153),
(159409, 'esES', '¡Ah! Ya entiendo. Puede que no ehté hecho pa surcar loh cieloh. Pero contigo a su lado, vivirá una buena vida.', '', 28153),
(159408, 'esES', 'Iremoh delante. La clave ehtá en la confianza mutua. Y ahora, ¡a volar!', '', 28153),
(159407, 'esES', '¡No te preocupeh! A tu amigo alado no le pasará nada. Tengo un plan.', '', 28153),
(159405, 'esES', 'Kumali la Lihta prepara todo tipo de mojoh en el Bancal de Artesanoh. La encontraráh en la parte occidental inferior de Dazar\'alor.', 'Kumali la Lihta prepara todo tipo de mojoh en el Bancal de Artesanoh. La encontraráh en la parte occidental inferior de Dazar\'alor.', 28153),
(159404, 'esES', 'Como los miembros de la Horda han usado nuestros ejemplares servicios durante tanto tiempo, hemos proporcionado portales de mago a individuos destacados, como tú. Te prometo que el viaje será prácticamente indoloro.', 'Como los miembros de la Horda han usado nuestros ejemplares servicios durante tanto tiempo, hemos proporcionado portales de mago a individuos destacados, como tú. Te prometo que el viaje será prácticamente indoloro.', 28153),
(159403, 'esES', '', '¡Ja, ja, ja, ja!', 28153),
(159402, 'esES', '', '¡Que tengas el viento a favor!', 28153),
(159401, 'esES', '¿Cómo puedo ir a los Claros de Tirisfal?', '¿Cómo puedo ir a los Claros de Tirisfal?', 28153),
(159399, 'esES', 'El Invocador del Trueno está en mantenimiento, se ha incendiado demasiadas veces. Una pena.', '', 28153),
(159398, 'esES', 'Sí, Pa\'ku.', 'Sí, Pa\'ku.', 28153),
(159397, 'esES', 'Tenemoh a loh mejoreh inhtructoreh del mundo. La mayoría se encuentran en la parte occidental inferior de Dazar\'alor, en el Bancal de Artesanoh.\n\n¿Buhcah a alguien en particular?', 'Tenemoh a loh mejoreh inhtructoreh del mundo. La mayoría se encuentran en la parte occidental inferior de Dazar\'alor, en el Bancal de Artesanoh.\n\n¿Buhcah a alguien en particular?', 28153),
(159396, 'esES', '', 'Aaah, sentía que pronto vendrías a mí. Ya ha pasado algún tiempo desde la última lección de tu jovenzuelo.\n\nVen, veamos qué ha aprendido.', 28153),
(159395, 'esES', 'Instructores', 'Instructores', 28153),
(159394, 'esES', 'Mahcotah, ¿eh? Loh únicoh compañeroh que merecen la pena son loh hijoh de loh loa.\n\nTe conviene buhcar al cuidabehtiah Kalatak cerca de la base noroehte de Dazar\'alor.', 'Mahcotah, ¿eh? Loh únicoh compañeroh que merecen la pena son loh hijoh de loh loa.\n\nTe conviene buhcar al cuidabehtiah Kalatak cerca de la base noroehte de Dazar\'alor.', 28153),
(159392, 'esES', 'Si hah ehtado cumpliendo la voluntad del rey Rahtakhan, puede que Natal\'hakata tenga algo interesante pa ti en el Gran Sello.', 'Si hah ehtado cumpliendo la voluntad del rey Rahtakhan, puede que Natal\'hakata tenga algo interesante pa ti en el Gran Sello.', 28153),
(159391, 'esES', 'Emisarios', 'Emisarios', 28153),
(159390, 'esES', '', 'Tirisfal ha presenciado el auge y la caída de grandes poderes. ¿Aprenderán los tuyos de toda su historia?\n\nPero estoy divagando.\n\n¿Has resuelto tus asuntos pendientes, adalid?', 28153),
(159389, 'esES', '', 'Teldrassil... Una vista magnífica, ¿eh? A menudo las cosas más bellas son las más fugaces.\n\nSobre todo cuando los mortales se empeñan en rociarlas con fuego.\n\n¿Has resuelto tus asuntos pendientes, adalid?', 28153),
(159388, 'esES', 'Si creeh que podráh dehcansar con esa cosa muerta danzando por ahí, puedeh encontrarla en el Gran Sello.', 'Si creeh que podráh dehcansar con esa cosa muerta danzando por ahí, puedeh encontrarla en el Gran Sello.', 28153),
(159386, 'esES', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t ¡Vectis empieza a lanzar |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t ¡Vectis empieza a lanzar |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', 28153),
(159385, 'esES', 'Todas las solicitudes de refugio se estudiarán caso por caso.', '', 28153),
(159384, 'esES', '', 'Desde estas costas puedes contemplar Teldrassil. Lo que una vez fue cuna de vida es ahora una ruina de fuego y cenizas.\n\nNi siquiera los Árboles del Mundo escapan al ciclo de la vida. Todo lo que nace, muere.\n\nNadie lo entiende mejor que el Vuelo Bronce.\n\n¿Quieres ver el árbol tal y como era en tiempos?', 28153),
(159383, 'esES', 'Por desgracia, tenemos recursos limitados en estos momentos.', '', 28153),
(159382, 'esES', 'Encontraráh a Paku\'ai en el saliente frente al Gran Sello. ¿Adónde vah?', 'Encontraráh a Paku\'ai en el saliente frente al Gran Sello. ¿Adónde vah?', 28153),
(159381, 'esES', 'Paciencia, por favor. Hacemos todo lo que podemos dadas las circunstancias.', '', 28153),
(159379, 'esES', '', 'Tirisfal... Un lugar de belleza y oscuridad. Una tierra llena de remordimientos... y tumbas.\n\nLos tuyos han luchado sin cesar por recuperarla.\n\n¿Te gustaría ver cómo era antes de la última guerra?', 28153),
(159378, 'esES', 'Ya me estaba cansando de la carne de cabra.', '', 28153),
(159377, 'esES', '¿Quién viene?', '', 28153),
(159376, 'esES', 'En un santiamén podemos llevaros allí a ti y a un pequeño escuadrón.', '', 28153),
(159375, 'esES', 'Falstad Martillo Salvaje silba y bajan a cubierta jinetes de grifos.', '', 28153),
(159374, 'esES', 'Tu barco es demasiado lento para llegar allí a tiempo. Pero la velocidad no es problema para los Martillo Salvaje.', '', 28153),
(159373, 'esES', 'Si Dreven se encuentra bordo de ese barco, estará acorralado. No tiene adonde huir... si atacamos antes de que desembarquen.', '', 28153),
(159372, 'esES', '', 'Durante mi persecución, me enteré de que el príncipe de sangre Dreven viaja en barco con un Sabiomar traidor.', 28153),
(159371, 'esES', '', 'En realidad creo que es una de las mayores prioridades. Gracias, Mathias.', 28153),
(159370, 'esES', '', 'Shandris Plumaluna desciende a cubierta montada en su hipogrifo.', 28153),
(159369, 'esES', 'No estamos seguros, pero puedo enviar agentes a investigar. Puede ser algo de baja prioridad.', '', 28153),
(159368, 'esES', '¿Qué podría estar buscando la Horda en restos de naufragios antiguos...?', '', 28153),
(159367, 'esES', 'Gracias, Mathias.', '', 28153),
(159366, 'esES', 'Obviamente permitimos que el original llegara a su destino sin señales de manipulación, pero creamos un duplicado para ti.', '', 28153),
(159365, 'esES', 'Alto comandante, mis agentes han interceptado órdenes de Sylvanas.', '', 28153),
(159364, 'esES', 'Mi gente no cometerá el mismo error al usar el Vacío, lo prometo.', '', 28153),
(159363, 'esES', '', 'Como bien dices, Umbric, he vivido una larga vida. He visto cómo el poder corrompía a las razas más nobles... La contención ha sido algo inusual.', 28153),
(159362, 'esES', 'Pareces sorprendida. ¿Creías que mi gente usaba la magia del Vacío como un mero juguete?', '', 28153),
(159361, 'esES', '', '¿Usarse para proteger? Interesante, Umbric.', 28153),
(159360, 'esES', 'El Vacío puede usarse para proteger, siempre y cuando no sucumbas a su poder.', '', 28153),
(159359, 'esES', '', 'Y tú no pareces dudar a la hora de usar tus poderes del Vacío contra ellos.', 28153),
(159358, 'esES', 'Tanto tú como yo hemos vivido mucho, Shandris. Conozco a cantidad de afectados por la barbarie de los Zandalari.', '', 28153),
(159357, 'esES', '', 'Se diría que ya has tenido experiencia con los Zandalari.', 28153),
(159356, 'esES', 'Mi gente y yo no permitiremos que estos monstruosos trols destruyan a la Alianza. Tienes mi palabra.', '', 28153),
(159355, 'esES', '', 'La cantidad de guardias que hay en este puerto es impresionante. Deben de estar preparándose para sacar la flota.', 28153),
(159354, 'esES', '', 'En cuanto dejemos a $n, tenemos que avisar a Halford sin demora.', 28153),
(159353, 'esES', 'Es malo si te fijas en que su ruta lo lleva a una posición desde donde podría ver nuestra avanzada de Xibala.', '', 28153),
(159352, 'esES', '', '¿Un barco? Tan malo no parece.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159351, 'esES', 'Tenemos un problema. Hay un barco que no teníamos presente. Podría ser uno de los destinados en Pandaria.', '', 28153),
(159350, 'esES', 'A ver... Parece que la información de Halford sobre la ubicación de la mayoría de barcos y sus rutas de navegación era correcta. Aunque...', '', 28153),
(159349, 'esES', '', 'No suelo husmear... pero en este caso haré una excepción. Veamos...', 28153),
(159348, 'esES', '¿Hay información nueva sobre los registros que recuperó $n?', '', 28153),
(159347, 'esES', '', '¡Buena suerte! El Puerto de Guerra Rastari estará plagado de Zandalari. Seguro que Shandris tiene un plan.', 28153),
(159346, 'esES', 'Si quiereh cambiar de ahpecto, ve a ver a esoh goblinh tan raroh del Gran Bazar, cerca del puerto.', 'Si quiereh cambiar de ahpecto, ve a ver a esoh goblinh tan raroh del Gran Bazar, cerca del puerto.', 28153),
(159343, 'esES', 'Por aquí corretean extrañas criaturas de todo tipo. Los típicos conejos, castores y ardillas, pero también esos otros más raros que parecen un fajo de palos ambulante. Tras varios días, al fin cacé uno y lo entrené. Resulta que son bastante leales. A ver, que si te dan con una de su partes puntiagudas gritas igual, pero molan bastante. ¿Quieres verlos en acción?', '', 28153),
(159342, 'esES', 'Encontraráh la Tesorería Real en medio de la pirámide junto al Gran Sello.', 'Encontraráh la Tesorería Real en medio de la pirámide junto al Gran Sello.', 28153),
(159340, 'esES', 'Hora de colocar bombas... sin hacerlas explotar. Por ahora.', '', 28153),
(159339, 'esES', '', 'No digas eso, Flynn. Puede que lady Jaina siga con vida. ¡Debemos tener esperanza!', 28153),
(159338, 'esES', 'Adalid, dale mi pésame a lady Katherine.', '', 28153),
(159337, 'esES', 'Fin del Destino... No es la muerte que elegiría para mí, desde luego.', '', 28153),
(159336, 'esES', '¡Vamos a jugar!', '¡Vamos a jugar!', 28153),
(159335, 'esES', '¡Coged sus cosas brillantes!', '¡Coged sus cosas brillantes!', 28153),
(159334, 'esES', '¡Oooh, tenéis cosas brillantes!', '¡Oooh, tenéis cosas brillantes!', 28153),
(159333, 'esES', '¡Venid a jugar con nosotros!', '¡Venid a jugar con nosotros!', 28153),
(159332, 'esES', '¡Ja, ja, ja!', '¡Ja, ja, ja!', 28153),
(159331, 'esES', '¡Ha picado!', '¡Ha picado!', 28153),
(159330, 'esES', '¡Te pillé!', '¡Te pillé!', 28153),
(159329, 'esES', '¡Je, je, je!', '¡Je, je, je!', 28153),
(159228, 'esES', '', 'Tened cuidado. ¡Estaré esperando vuestra señal!', 28153),
(159227, 'esES', 'Cuando acabes, reúnete conmigo en Fuerte Libre.', '', 28153),
(159226, 'esES', 'Pilla unas cuantas granadas. Yo tengo que hablar con alguien.', '', 28153),
(159225, 'esES', 'Parece que no se atrevieron a desvelar su destino, ni siquiera en este tocho de pamplinas legales... Pero creo que sé dónde tienen esa información.', '', 28153),
(159224, 'esES', 'Puede que haya algo en la letra pequeña...', '', 28153),
(159223, 'esES', 'Así que lady Katherine te ha enviado a buscar a su hija, ¿eh? Veamos qué dice este contrato sobre su destino.', '', 28153),
(159222, 'esES', 'Oh, vamoooos... ¿Adónde estáis llevando a Jaina?', '', 28153),
(159221, 'esES', 'Más definiciones, más condiciones de servicio... Rollos legales que no servirían de nada en un juicio a menos que hubieran comprado al juez...', '', 28153),
(159220, 'esES', 'Diez páginas de medidas de seguridad... Veinte de descargos de responsabilidad...', '', 28153),
(159219, 'esES', 'Descripción de los servicios: el transportista otorgará al cliente... Bla, bla, bla...', '', 28153),
(159218, 'esES', 'El presente contrato de servicios entre Gobernalle y bla, bla, bla... Ah, ¿quién escribe estas cosas?', '', 28153),
(159217, 'esES', '', '¡Atravesad el muro! ¡Rápido! No aguantaré mucho más.', 28153),
(159216, 'esES', 'Lady Katherine me ha pedido que busque a su hija. Esta es la única pista que tengo por ahora.', 'Lady Katherine me ha pedido que busque a su hija. Esta es la única pista que tengo por ahora.', 28153),
(159215, 'esES', 'Hola, $n. Me alegro de volver a verte.', '', 28153),
(159214, 'esES', '', 'Vuelve en cuanto descubras dónde está Jaina, adalid.', 28153),
(159213, 'esES', '', 'Espero que tengas razón, Genn.', 28153),
(159212, 'esES', 'Existen pocos campeones en la Alianza que se puedan igualar a quien tienes ante ti, Katherine. Es tu mejor opción para salvar a Jaina.', '', 28153),
(159211, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t ¡Te han infectado con |cFFFF0000|Hspell:265129|h[Vector omega]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t ¡Te han infectado con |cFFFF0000|Hspell:265129|h[Vector omega]|h|r!', 28153),
(159210, 'esES', '¡Usa el talismán de control!', '', 28153),
(159209, 'esES', 'Aquí es donde te bajas tú. Ten cuidado y recuerda: ¡coloca las bombas y no dejes que alerten al continente de tu presencia!', '', 28153),
(159208, 'esES', '... Presiento que este es el comienzo de una hermosa amistad.', '', 28153),
(159207, 'esES', '', '¿Una? No, no, no: tengo VARIAS colecciones de cuchillos.', 28153),
(159206, 'esES', '¿Tienes una colección de cuchillos?', '', 28153),
(159205, 'esES', '', 'Eres como yo, Keeshan. Cuando esto acabe tenemos que comparar nuestras colecciones de cuchillos.', 28153),
(159204, 'esES', 'Y yo ayudaré a $n colocando las bombas de Kelsey en los barcos más pequeños... y destripando a cualquier Zandalari que me vea.', '', 28153),
(159203, 'esES', '', 'Estaré trabajando en un dispositivo para ayudar a $n a cruzar al otro lado para la siguiente parte del plan.', 28153),
(159202, 'esES', 'Procura que no te vean colocar esas bombas en la base de sus barcos.', '', 28153),
(159201, 'esES', 'Me lo creo. Os dejaré a todos en la Isla Diente Marfil. Está lo bastante lejos de la ciudad como para que podáis actuar con cierta impunidad contra esos Zandalari.', '', 28153),
(159200, 'esES', 'A mí casi me comen una vez. No lo recomiendo.', '', 28153),
(159199, 'esES', '', 'Nos darían de comer a sus dinosaurios. Nos harían trizas con las mandíbulas.', 28153),
(159198, 'esES', 'Ya. Una cosa es encontrar un número reducido, como aquí $n. Pero ¿y si ven todo el maldito campamento?', '', 28153),
(159197, 'esES', '', '¿Por qué crees que Halford avanza tan deprisa? Sabe que estamos perdidos si los Zandalari nos cazan en su territorio.', 28153),
(159196, 'esES', 'Ese campamento de la Alianza salta a la vista cosa mala. Tenemos que prepararnos para cuando los Zandalari nos descubran.', '', 28153),
(159195, 'esES', '¡Listo! Con esta altura debería bastar para que los Zandalari no nos vean.', '', 28153),
(159194, 'esES', '¡Agárrate bien, tenemos que elevarnos MUCHO para que no nos descubran!', '', 28153),
(159193, 'esES', '', 'Puedes pasarte por aquí siempre que quieras, $p.', 28153),
(159192, 'esES', '', 'Nunca te veo con el abrigo puesto, cielo. ¡Vas a pillar un resfriado!', 28153),
(159191, 'esES', '', 'Espero que descanses como es debido. ¡Monstruos con los que luchar nunca faltarán!', 28153),
(159190, 'esES', 'Hablemos de nuestro plan para debilitar la flota Zandalari.', 'Hablemos de nuestro plan para debilitar la flota Zandalari.', 28153),
(159189, 'esES', '¿Cómo... OSAS...?', '¿Cómo... OSAS...?', 28153),
(159188, 'esES', 'La ola aplastante... ya viene...', 'La ola aplastante... ya viene...', 28153),
(159187, 'esES', 'La oscuridad... es solo temporal...', 'La oscuridad... es solo temporal...', 28153),
(159186, 'esES', '$gMocoso:Mocosa;... insolente...', '$gMocoso:Mocosa;... insolente...', 28153),
(159185, 'esES', 'Tenemos miles de ensamblajes... No podéis ganar...', 'Tenemos miles de ensamblajes... No podéis ganar...', 28153),
(159184, 'esES', 'Mi espíritu... volverá...', 'Mi espíritu... volverá...', 28153),
(159183, 'esES', 'Esto no terminará con mi muerte...', 'Esto no terminará con mi muerte...', 28153),
(159182, 'esES', 'Reconstruiremos...', 'Reconstruiremos...', 28153),
(159181, 'esES', '¡La muerte es solo el comienzo de vuestro castigo!', '¡La muerte es solo el comienzo de vuestro castigo!', 28153),
(159180, 'esES', '', 'Vaya, vaya. Hola, $gquerido:querida;. Quizás puedas ayudarme con algún recadillo. ¡Siempre que no sea una molestia, por supuesto!', 28153),
(159179, 'esES', 'Tu destino está sellado, $ginsensato:insensata;.', 'Tu destino está sellado, $ginsensato:insensata;.', 28153),
(159178, 'esES', '¡Inclínate, $gintruso:intrusa;!', '¡Inclínate, $gintruso:intrusa;!', 28153),
(159177, 'esES', '¡Morirás lentamente, $gintruso:intrusa;!', '¡Morirás lentamente, $gintruso:intrusa;!', 28153),
(159176, 'esES', '¡Estábamos aquí antes que los vuestros, y aquí estaremos cuando perezcáis!', '¡Estábamos aquí antes que los vuestros, y aquí estaremos cuando perezcáis!', 28153),
(159175, 'esES', '¡Insolente criatura de carne!', '¡Insolente criatura de carne!', 28153),
(159174, 'esES', '¡Aprenderéis a respetar a vuestros superiores!', '¡Aprenderéis a respetar a vuestros superiores!', 28153),
(159173, 'esES', '¡No hay lugar en este mundo para los débiles!', '¡No hay lugar en este mundo para los débiles!', 28153),
(159172, 'esES', 'Lo que está muerto... no puede morir...', 'Lo que está muerto... no puede morir...', 28153),
(159171, 'esES', 'Vuelvo con ella, durante un instante...', 'Vuelvo con ella, durante un instante...', 28153),
(159170, 'esES', 'No seremos olvidados en las profundidades...', 'No seremos olvidados en las profundidades...', 28153),
(159169, 'esES', 'Ella nos liberará de este tormento...', 'Ella nos liberará de este tormento...', 28153),
(159168, 'esES', 'Ella tendrá el líquido dorado... No podéis detenernos a todos...', 'Ella tendrá el líquido dorado... No podéis detenernos a todos...', 28153),
(159167, 'esES', 'Somos eternos... Vuestra victoria no significa nada...', 'Somos eternos... Vuestra victoria no significa nada...', 28153),
(159166, 'esES', 'Ella me traerá de vuelta...', 'Ella me traerá de vuelta...', 28153),
(159165, 'esES', 'No pueden matarnos... unos mortales...', 'No pueden matarnos... unos mortales...', 28153),
(159164, 'esES', '¡Te robaré el aliento de los pulmones!', '¡Te robaré el aliento de los pulmones!', 28153),
(159163, 'esES', '¡Estas aguas nos pertenecen!', '¡Estas aguas nos pertenecen!', 28153),
(159162, 'esES', '¡Las profundidades aplastarán tus frágiles huesos!', '¡Las profundidades aplastarán tus frágiles huesos!', 28153),
(159161, 'esES', '¡Las mareas se te llevarán!', '¡Las mareas se te llevarán!', 28153),
(159160, 'esES', '¡Helya os reclama!', '¡Helya os reclama!', 28153),
(159159, 'esES', '¡Vuestras almas serán nuestras!', '¡Vuestras almas serán nuestras!', 28153),
(159158, 'esES', '¡Nos acompañaréis en la muerte, os uniréis a su ejército!', '¡Nos acompañaréis en la muerte, os uniréis a su ejército!', 28153),
(159157, 'esES', '¡Las brumas vienen a por ti!', '¡Las brumas vienen a por ti!', 28153),
(159156, 'esES', 'Jamásss dominaréisss losss maresss...', 'Jamásss dominaréisss losss maresss...', 28153),
(159155, 'esES', 'Muere uno, pero quedan milesss...', 'Muere uno, pero quedan milesss...', 28153),
(159154, 'esES', 'No creáisss que habéisss ganado...', 'No creáisss que habéisss ganado...', 28153),
(159153, 'esES', 'Vuessstro futuro... essstá condenado...', 'Vuessstro futuro... essstá condenado...', 28153),
(159152, 'esES', 'La muerte viene a por vosotrosss...', 'La muerte viene a por vosotrosss...', 28153),
(159151, 'esES', 'Azssshara... lo es todo...', 'Azssshara... lo es todo...', 28153),
(159150, 'esES', 'Mi Azssshara... Regressso a las olasss...', 'Mi Azssshara... Regressso a las olasss...', 28153),
(159149, 'esES', 'Mi Reina...', 'Mi Reina...', 28153),
(159148, 'esES', '¡El diosss de lasss profundidadesss osss essspera impaciente!', '¡El diosss de lasss profundidadesss osss essspera impaciente!', 28153),
(159147, 'esES', '¡Losss ojosss del abisssmo osss volverán locosss!', '¡Losss ojosss del abisssmo osss volverán locosss!', 28153),
(159146, 'esES', '¿Sssentísss el miedo? ¿El terror inacabable de las profundidadesss?', '¿Sssentísss el miedo? ¿El terror inacabable de las profundidadesss?', 28153),
(159145, 'esES', '¡El Imperio Negro renacerá en essste mundo y sssu alma alimentará a losss magnosss!', '¡El Imperio Negro renacerá en essste mundo y sssu alma alimentará a losss magnosss!', 28153),
(159144, 'esES', 'Hemosss esssperado demasssiado, ¡esss la era de los nagasss!', 'Hemosss esssperado demasssiado, ¡esss la era de los nagasss!', 28153),
(159143, 'esES', '¡La Ciudad sssumergida sssurgirá como heraldo de vuessstra perdición!', '¡La Ciudad sssumergida sssurgirá como heraldo de vuessstra perdición!', 28153),
(159142, 'esES', 'N\'Zoth nosss llama a todosss, ¿no lo oísss?', 'N\'Zoth nosss llama a todosss, ¿no lo oísss?', 28153),
(159141, 'esES', '¡Por la gran reina Azssshara, largo sssea sssu reinado!', '¡Por la gran reina Azssshara, largo sssea sssu reinado!', 28153),
(159140, 'esES', '¡Se acabó el tiempo!', '¡Se acabó el tiempo!', 28153),
(159139, 'esES', '¡Venimosss desssde lasss profundidadesss!', '¡Venimosss desssde lasss profundidadesss!', 28153),
(159138, 'esES', '¡Matadlosss!', '¡Matadlosss!', 28153),
(159137, 'esES', '¡Os ahogaréisss en la pena!', '¡Os ahogaréisss en la pena!', 28153),
(159136, 'esES', '¡La aviesssa nosss canta!', '¡La aviesssa nosss canta!', 28153),
(159135, 'esES', '¡Las profundidadesss sssusssurrantesss osss llaman!', '¡Las profundidadesss sssusssurrantesss osss llaman!', 28153),
(159134, 'esES', '¡Por Azssshara!', '¡Por Azssshara!', 28153),
(159133, 'esES', '¡Volved allá de donde vinisssteisss!', '¡Volved allá de donde vinisssteisss!', 28153),
(159132, 'esES', 'Maldición de la carne detectada, iniciando protocolo de higienización.', 'Maldición de la carne detectada, iniciando protocolo de higienización.', 28153),
(159131, 'esES', 'Vuestro cuerpo es débil y maleable. Permitid que os dé forma.', 'Vuestro cuerpo es débil y maleable. Permitid que os dé forma.', 28153),
(159130, 'esES', 'Queréis hacer daño al alma-mundo y robarle la sangre. Hay que reformaros.', 'Queréis hacer daño al alma-mundo y robarle la sangre. Hay que reformaros.', 28153),
(159129, 'esES', 'Somos los defensores de esta alma-mundo, no podéis continuar.', 'Somos los defensores de esta alma-mundo, no podéis continuar.', 28153),
(159128, 'esES', 'Estáis impidiendo nuestro deber sagrado. Hay que purificaros.', 'Estáis impidiendo nuestro deber sagrado. Hay que purificaros.', 28153),
(159127, 'esES', 'Hay que volver a crear a los malditos. Es nuestro cometido.', 'Hay que volver a crear a los malditos. Es nuestro cometido.', 28153),
(159126, 'esES', '¡Se nos formó para proteger este mundo de aquellos con la maldición de la carne!', '¡Se nos formó para proteger este mundo de aquellos con la maldición de la carne!', 28153),
(159125, 'esES', 'Fuimos creados para purificar vuestra enfermedad. No os mováis.', 'Fuimos creados para purificar vuestra enfermedad. No os mováis.', 28153),
(159124, 'esES', 'Nuestra misión no cambiará por vosotros...', 'Nuestra misión no cambiará por vosotros...', 28153),
(159123, 'esES', 'Reconstruiremos... una y otra vez...', 'Reconstruiremos... una y otra vez...', 28153),
(159122, 'esES', 'Nuestra misión... no debe fracasar...', 'Nuestra misión... no debe fracasar...', 28153),
(159121, 'esES', 'Vuestras acciones provocan el fin de vuestro mundo...', 'Vuestras acciones provocan el fin de vuestro mundo...', 28153),
(159120, 'esES', 'Debemos proteger... el alma del mundo...', 'Debemos proteger... el alma del mundo...', 28153),
(159119, 'esES', 'No lo... entendéis...', 'No lo... entendéis...', 28153),
(159118, 'esES', 'Este no es... nuestro destino...', 'Este no es... nuestro destino...', 28153),
(159117, 'esES', 'Los modeladores... regresarán...', 'Los modeladores... regresarán...', 28153),
(159116, 'esES', 'Estáis perdido, dejadnos reorientaros.', 'Estáis perdido, dejadnos reorientaros.', 28153),
(159115, 'esES', 'Nuestro deber sagrado no puede ser interrumpido.', 'Nuestro deber sagrado no puede ser interrumpido.', 28153),
(159114, 'esES', 'Los modeladores nos dejaron a cargo de este mundo, ¡aparta!', 'Los modeladores nos dejaron a cargo de este mundo, ¡aparta!', 28153),
(159113, 'esES', '¡La maldición de la carne está descontrolada!', '¡La maldición de la carne está descontrolada!', 28153),
(159112, 'esES', 'Os crearemos de nuevo, no os mováis.', 'Os crearemos de nuevo, no os mováis.', 28153),
(159111, 'esES', 'Hay que curaros de vuestra enfermedad.', 'Hay que curaros de vuestra enfermedad.', 28153),
(159110, 'esES', 'Sufrís la maldición de la carne y os curaremos.', 'Sufrís la maldición de la carne y os curaremos.', 28153),
(159109, 'esES', 'Debemos supervisar la sangre del planeta.', 'Debemos supervisar la sangre del planeta.', 28153),
(159108, 'esES', 'Al menos he muerto rico...', 'Al menos he muerto rica...', 28153),
(159107, 'esES', 'Decid a mis hijos... que ni olerán el dinero...', 'Decid a mis hijos... que ni olerán el dinero...', 28153),
(159106, 'esES', 'Recordadme... por mis ganancias trimestrales...', 'Recordadme... por mis ganancias trimestrales...', 28153),
(159105, 'esES', '¡Un momento! ¡Pagaré para que me resucitéis! ¡Venga!', '¡Un momento! ¡Pagaré para que me resucitéis! ¡Venga!', 28153),
(159104, 'esES', '¡Uf! Auditoría...', '¡Uf! Auditoría...', 28153),
(159103, 'esES', 'Espero que esto... no afecte... a mi pensión...', 'Espero que esto... no afecte... a mi pensión...', 28153),
(159102, 'esES', '¡Números rojos!', '¡Números rojos!', 28153),
(159101, 'esES', 'Crac... bursátil...', 'Crac... bursátil...', 28153),
(159100, 'esES', '¡Preparaos para pasar por caja!', '¡Preparaos para pasar por caja!', 28153),
(159099, 'esES', 'Si no los matamos, ¡los gastos se deducirán del presupuesto para café!', 'Si no los matamos, ¡los gastos se deducirán del presupuesto para café!', 28153),
(159098, 'esES', '¡Me llevaré una buena bonificación por entregar tu cabeza!', '¡Me llevaré una buena bonificación por entregar tu cabeza!', 28153),
(159097, 'esES', '¡He hecho un hueco en la agenda solo para matarte!', '¡He hecho un hueco en la agenda solo para matarte!', 28153),
(159096, 'esES', '¡A los accionistas no les hará gracia que os entrometáis en nuestros asuntos!', '¡A los accionistas no les hará gracia que os entrometáis en nuestros asuntos!', 28153),
(159095, 'esES', '¡Se acabó, voy a tirar de técnicas de gestión!', '¡Se acabó, voy a tirar de técnicas de gestión!', 28153),
(159094, 'esES', 'Voy a convertiros en un magnífico beneficio.', 'Voy a convertiros en un magnífico beneficio.', 28153),
(159093, 'esES', '¡El beneficio ha sido mejor de lo esperado!', '¡El beneficio ha sido mejor de lo esperado!', 28153),
(159092, 'esES', '¡Consideraos adquiridos!', '¡Consideraos adquiridos!', 28153),
(159091, 'esES', '¡Esto es una opa hostil!', '¡Esto es una opa hostil!', 28153),
(159090, 'esES', '¡Que alguien saque el kit de emergencia, tenemos compañía!', '¡Que alguien saque el kit de emergencia, tenemos compañía!', 28153),
(159089, 'esES', '¡Gracias! Muy amable.', '¡Gracias! Muy amable.', 28153),
(159088, 'esES', '¡Me estáis reduciendo los márgenes de beneficio!', '¡Me estáis reduciendo los márgenes de beneficio!', 28153),
(159087, 'esES', '¡No podemos parar las operaciones por esto!', '¡No podemos parar las operaciones por esto!', 28153),
(159086, 'esES', '¿Qué hacéis aquí? Esto es territorio Ventura, ¿no os llegó la circular?', '¿Qué hacéis aquí? Esto es territorio Ventura, ¿no os llegó la circular?', 28153),
(159085, 'esES', '¡Agh! ¡Intrusos! ¡Que alguien me defienda!', '¡Agh! ¡Intrusos! ¡Que alguien me defienda!', 28153),
(159084, 'esES', '¡A por ellos! ¡Pero con el material más barato!', '¡A por ellos! ¡Pero con el material más barato!', 28153),
(159083, 'esES', 'Recuerda que nuestro objetivo principal es mermar sus defensas para que nuestras tropas sigan ocultas en esta zona. Si nos descubren, se acabó todo. ¡Por la Alianza!', '', 28153),
(159082, 'esES', '¿Darle 20 helados de fresa de Tigule y Foror a Marie Davenport?', '¿Darle 20 helados de fresa de Tigule y Foror a Marie Davenport?', 28153),
(159081, 'esES', '', 'Umbric y yo nos adelantaremos y realizaremos los preparativos para un ataque sigiloso al puerto de guerra.', 28153),
(159080, 'esES', 'Marcháis hacia la muerte de vuestro mundo... cegados por la arrogancia...', 'Marcháis hacia la muerte de vuestro mundo... cegados por la arrogancia...', 28153),
(159079, 'esES', 'Solo queríamos... lo que es nuestro...', 'Solo queríamos... lo que es nuestro...', 28153),
(159078, 'esES', 'Solo estáis retrasando... lo inevitable...', 'Solo estáis retrasando... lo inevitable...', 28153),
(159077, 'esES', 'La nidada se hará más fuerte... sin mí...', 'La nidada se hará más fuerte... sin mí...', 28153),
(159076, 'esES', 'El cielo se oscurece...', 'El cielo se oscurece...', 28153),
(159075, 'esES', 'Correcto. $n, tú te encargarás de debilitar las defensas portuarias Zandalari. Kelsey, Falstad y Keeshan te ayudarán con el primer objetivo.', '', 28153),
(159074, 'esES', 'Nosotros no... elegimos nuestro destino...', 'Nosotros no... elegimos nuestro destino...', 28153),
(159073, 'esES', 'Nunca nos dieron... una oportunidad...', 'Nunca nos dieron... una oportunidad...', 28153),
(159072, 'esES', 'Caemos... una vez más...', 'Caemos... una vez más...', 28153),
(159071, 'esES', '¡Ya sucumbimos una vez ante los vuestros y no volverá a ocurrir! ¡Es el amanecer del Crepúsculo!', '¡Ya sucumbimos una vez ante los vuestros y no volverá a ocurrir! ¡Es el amanecer del Crepúsculo!', 28153),
(159070, 'esES', 'Necesitamos la mena brillante, sin ella no podemos sobrevivir, ¿no lo ves?', 'Necesitamos la mena brillante, sin ella no podemos sobrevivir, ¿no lo ves?', 28153),
(159069, 'esES', '', 'Ah... Entonces esperamos para detonarlas hasta el momento en que lleguen nuestras flotas. ¡En la ciudad reinaría el caos y podríamos desembarcar!', 28153),
(159068, 'esES', '¡Solo queremos lo que se nos prometió hace mucho tiempo!', '¡Solo queremos lo que se nos prometió hace mucho tiempo!', 28153),
(159067, 'esES', 'El líquido dorado anuncia el retorno de nuestro Vuelo ¡y vuestra desaparición!', 'El líquido dorado anuncia el retorno de nuestro Vuelo ¡y vuestra desaparición!', 28153),
(159066, 'esES', 'Si hacemos bien nuestro trabajo, los Zandalari no sabrán que les hemos saboteado las defensas para que exploten.', '', 28153),
(159065, 'esES', 'Ahora tomamos nuestras propias decisiones, ¡dejadnos estar!', 'Ahora tomamos nuestras propias decisiones, ¡dejadnos estar!', 28153),
(159064, 'esES', 'Estoy de acuerdo. Shandris. Falstad y yo trazamos un plan que aprobó el rey Wrynn. Si logramos llevarlo a cabo, puede que nuestras fuerzas tengan una oportunidad.', '', 28153),
(159063, 'esES', '¡Nuestro Vuelo es independiente, no estamos en deuda con nadie, y menos con vosotros!', '¡Nuestro Vuelo es independiente, no estamos en deuda con nadie, y menos con vosotros!', 28153),
(159062, 'esES', '¡El Vuelo Crepuscular regresa ante vuestras narices, so arrogantes!', '¡El Vuelo Crepuscular regresa ante vuestras narices, so arrogantes!', 28153),
(159061, 'esES', '', '¡Para eso queríais esas bombas!', 28153),
(159060, 'esES', 'Apartados por los autodenominados gobernantes de este mundo, ¡no desapareceremos en la historia!', 'Apartados por los autodenominados gobernantes de este mundo, ¡no desapareceremos en la historia!', 28153),
(159059, 'esES', '', 'Los Zandalari son poderosos, pero no invencibles. Vamos a sabotear emplazamientos clave de sus defensas portuarias con bombas de detonación remota.', 28153),
(159058, 'esES', '¡Esta vez no podréis detenernos!', '¡Esta vez no podréis detenernos!', 28153),
(159057, 'esES', '¡Gloria al Crepúsculo!', '¡Gloria al Crepúsculo!', 28153),
(159056, 'esES', '¡Ahora nos gobernamos solos!', '¡Ahora nos gobernamos solos!', 28153),
(159055, 'esES', 'Despejemos el camino. La Alianza necesitará nuestra ayuda para preparar el asalto a Zuldazar.', '', 28153),
(159054, 'esES', '¡No volverán a dejarnos de lado!', '¡No volverán a dejarnos de lado!', 28153),
(159053, 'esES', '¡El Vuelo olvidado no esperará más!', '¡El Vuelo olvidado no esperará más!', 28153),
(159052, 'esES', 'Venimos de las tinieblas a gobernar este mundo.', 'Venimos de las tinieblas a gobernar este mundo.', 28153),
(159051, 'esES', '¡El Vuelo Crepuscular reinará para siempre!', '¡El Vuelo Crepuscular reinará para siempre!', 28153),
(159050, 'esES', '¡Por el Crepúsculo!', '¡Por el Crepúsculo!', 28153),
(159049, 'esES', '¡Somos los guardianes de la tierra, y queréis lo que no es vuestro, pieles suaves!', '¡Somos los guardianes de la tierra, y queréis lo que no es vuestro, pieles suaves!', 28153),
(159048, 'esES', 'No podéis ganar porque no sabéis dónde está nuestra nidada. ¡Rendíos ya!', 'No podéis ganar porque no sabéis dónde está nuestra nidada. ¡Rendíos ya!', 28153),
(159047, 'esES', '¡El Vuelo Negro se vengará de una vez por todas!', '¡El Vuelo Negro se vengará de una vez por todas!', 28153),
(159046, 'esES', '¡Protegemos las piedras de este mundo de la gente como vosotros!', '¡Protegemos las piedras de este mundo de la gente como vosotros!', 28153),
(159045, 'esES', '¡Patéticas criaturas de carne, la dorada sangre del mundo está a nuestro cargo!', '¡Patéticas criaturas de carne, la dorada sangre del mundo está a nuestro cargo!', 28153),
(159044, 'esES', '¡Este mundo era para los dragones, vuestra especie es una enfermedad!', '¡Este mundo era para los dragones, vuestra especie es una enfermedad!', 28153),
(159043, 'esES', '¿Cómo osáis tomar lo que es legítimamente nuestro?', '¿Cómo osáis tomar lo que es legítimamente nuestro?', 28153),
(159042, 'esES', '¡La sangre del mundo está a nuestro cargo! ¡Somos los guardianes!', '¡La sangre del mundo está a nuestro cargo! ¡Somos los guardianes!', 28153),
(159041, 'esES', 'Robáis... lo que nos pertenece por derecho...', 'Robáis... lo que nos pertenece por derecho...', 28153),
(159040, 'esES', 'La historia no nos olvidará...', 'La historia no nos olvidará...', 28153),
(159039, 'esES', 'El Vuelo Negro viene a por vosotros...', 'El Vuelo Negro viene a por vosotros...', 28153),
(159038, 'esES', 'No podéis ganar esta guerra...', 'No podéis ganar esta guerra...', 28153),
(159037, 'esES', 'Este mundo pertenece... a los dragones...', 'Este mundo pertenece... a los dragones...', 28153),
(159036, 'esES', 'Vuestra especie... no pinta nada aquí...', 'Vuestra especie... no pinta nada aquí...', 28153),
(159035, 'esES', 'Es imposible vencer al Vuelo Negro...', 'Es imposible vencer al Vuelo Negro...', 28153),
(159034, 'esES', 'Volveremos...', 'Volveremos...', 28153),
(159033, 'esES', '¡El Vuelo Negro renacerá!', '¡El Vuelo Negro renacerá!', 28153),
(159032, 'esES', '¡Vuestra especie será erradicada!', '¡Vuestra especie será erradicada!', 28153),
(159031, 'esES', '¡Traemos el fuego y la muerte!', '¡Traemos el fuego y la muerte!', 28153),
(159030, 'esES', '¿Osáis enfrentaros a un Vuelo?', '¿Osáis enfrentaros a un Vuelo?', 28153),
(159029, 'esES', '¡El Vuelo Negro resurgirá!', '¡El Vuelo Negro resurgirá!', 28153),
(159028, 'esES', '¡Gloria al Vuelo Negro!', '¡Gloria al Vuelo Negro!', 28153),
(159027, 'esES', '¡Por los guardianes de la tierra!', '¡Por los guardianes de la tierra!', 28153),
(159026, 'esES', '¡Defenderé al Vuelo!', '¡Defenderé al Vuelo!', 28153),
(159025, 'esES', 'Por ti... emperatriz...', 'Por ti... emperatriz...', 28153),
(159024, 'esES', 'Habéis aplastado a uno... pero vienen muchos más...', 'Habéis aplastado a uno... pero vienen muchos más...', 28153),
(159023, 'esES', 'Llevad la mena... a la emperatriz...', 'Llevad la mena... a la emperatriz...', 28153),
(159022, 'esES', 'Su llamada... es música...', 'Su llamada... es música...', 28153),
(159021, 'esES', 'Puedo oírla... incluso mientras muero...', 'Puedo oírla... incluso mientras muero...', 28153),
(159020, 'esES', 'La canción de la emperatriz... se desvanece...', 'La canción de la emperatriz... se desvanece...', 28153),
(159019, 'esES', 'Somos... miles... No podéis pararnos...', 'Somos... miles... No podéis pararnos...', 28153),
(159018, 'esES', 'Kssh... Caigo...', 'Kssh... Caigo...', 28153),
(159017, 'esES', '¡Te mataré y tu cadáver será para el enjambre!', '¡Te mataré y tu cadáver será para el enjambre!', 28153),
(159016, 'esES', '¿De verdad deseáis lanzaros hacia vuestra propia muerte?', '¿De verdad deseáis lanzaros hacia vuestra propia muerte?', 28153),
(159015, 'esES', '¡La mena de oro es nuestra! ¡Un regalo para la Emperatriz!', '¡La mena de oro es nuestra! ¡Un regalo para la Emperatriz!', 28153),
(159014, 'esES', '¡Este enjambre es por la Emperatriz!', '¡Este enjambre es por la Emperatriz!', 28153),
(159013, 'esES', '¡Es imposible detener al enjambre!', '¡Es imposible detener al enjambre!', 28153),
(159012, 'esES', '¡La dulce canción de nuestra Emperatriz exige vuestra muerte!', '¡La dulce canción de nuestra Emperatriz exige vuestra muerte!', 28153),
(159011, 'esES', '¡Sirvo a la Emperatriz!', '¡Sirvo a la Emperatriz!', 28153),
(159010, 'esES', '¡Por la Emperatriz!', '¡Por la Emperatriz!', 28153),
(159009, 'esES', 'La Alianza resistirá... Y el pérfido reinado de la Reina alma en pena llegará a su fin.', '', 28153),
(159008, 'esES', 'Sylvanas espera que esta atrocidad nos desmoralice y nos divida. Pero juro que...', '', 28153),
(159007, 'esES', '¡Raar! Abatido con honor...', '¡Raar! Abatida con honor...', 28153),
(159006, 'esES', '¡Argh! ¡Esta es la muerte que ansío!', '¡Argh! ¡Esta es la muerte que ansío!', 28153),
(159005, 'esES', 'Pero ese sueño jamás se cumplirá mientras Sylvanas Brisaveloz lidere a la Horda.', '', 28153),
(159004, 'esES', 'Parto... hacia el atardecer...', 'Parto... hacia el atardecer...', 28153),
(159003, 'esES', 'Toda mi vida he rezado para que la paz reinara en este mundo.', '', 28153),
(159002, 'esES', 'Ocuparé mi lugar junto a los guerreros de antaño...', 'Ocuparé mi lugar junto a los guerreros de antaño...', 28153),
(159001, 'esES', 'Has mostrado valor y bondad en este día oscuro, uno de los peores para la Alianza.', '', 28153),
(159000, 'esES', 'Los espíritus bendicen mi defunción...', 'Los espíritus bendicen mi defunción...', 28153),
(158999, 'esES', '', 'Descansa mientras puedas y prepárate para las batallas que están por llegar. Me harás falta.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'esES', '¡Muero en glorioso combate!', '¡Muero en glorioso combate!', 28153),
(158997, 'esES', 'El clan me vengará...', 'El clan me vengará...', 28153),
(158996, 'esES', '', 'Pero están sangrando. En la guerra que se avecina, su rabia será su debilidad, no su fortaleza.', 28153),
(158995, 'esES', 'La muerte viene a por vosotros...', 'La muerte viene a por vosotros...', 28153),
(158994, 'esES', '¡$gOtro:Otra; enclenque $gal:a la; que conquistar!', '¡$gOtro:Otra; enclenque $gal:a la; que conquistar!', 28153),
(158993, 'esES', '¡Otra gloriosa batalla!', '¡Otra gloriosa batalla!', 28153),
(158992, 'esES', '¡Os arrancaré los ojos!', '¡Os arrancaré los ojos!', 28153),
(158991, 'esES', '', 'Esta es solo una victoria parcial. La Alianza se vengará. Vendrán a por nosotros. A por mí. A por ti.', 28153),
(158990, 'esES', '', 'Nuestro objetivo era acabar con la guerra antes de que empezara; conquistar el hogar del enemigo y aniquilar a sus líderes de un solo golpe. Infligir una herida que desangrara a la Alianza.', 28153),
(158989, 'esES', '', 'Cuando te encomendé esta misión, no predije este resultado.', 28153),
(158988, 'esES', '¡Los mil barcos navegan hacia vuestra perdición!', '¡Los mil barcos navegan hacia vuestra perdición!', 28153),
(158987, 'esES', '¡Mi vida por Jorun!', '¡Mi vida por Jorun!', 28153),
(158986, 'esES', '¡Por los Rastrosangre!', '¡Por los Rastrosangre!', 28153),
(158985, 'esES', '¡Muere con honor!', '¡Muere con honor!', 28153),
(158984, 'esES', '¡Me comeré tu corazón!', '¡Me comeré tu corazón!', 28153),
(158983, 'esES', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'esES', '¿Mrrg mrgl?', '¿Mrrg mrgl?', 28153),
(158981, 'esES', 'Rgll mgrgl... rgl...', 'Rgll mgrgl... rgl...', 28153),
(158980, 'esES', 'Grgl...', 'Grgl...', 28153),
(158979, 'esES', '¡Mrg!', '¡Mrg!', 28153),
(158978, 'esES', 'Rgl... mrg...', 'Rgl... mrg...', 28153),
(158977, 'esES', '¡Mrrrmgrl!', '¡Mrrrmgrl!', 28153),
(158976, 'esES', '¿Mrglrgl? ¡Mrg! ¡Rgl!', '¿Mrglrgl? ¡Mrg! ¡Rgl!', 28153),
(158975, 'esES', '¡Rgrml grml grml!', '¡Rgrml grml grml!', 28153),
(158974, 'esES', '', '¡Ay, cielos, es perfecto! Muchas gracias, $p, eres un encanto. Ten, llévate unas galletas.', 28153),
(158973, 'esES', '¿Mrg? ¡¿Grml?!', '¿Mrg? ¡¿Grml?!', 28153),
(158972, 'esES', '¿Mrgl? ¡Rgl!', '¿Mrgl? ¡Rgl!', 28153),
(158971, 'esES', '¡Mrglrglrgl!', '¡Mrglrglrgl!', 28153),
(158970, 'esES', 'La muerte no significa nada para el Vacío infinito...', 'La muerte no significa nada para el Vacío infinito...', 28153),
(158969, 'esES', 'Contemplad este segundo advenimiento...', 'Contemplad este segundo advenimiento...', 28153),
(158968, 'esES', 'Vuestra perdición surge de las profundidades...', 'Vuestra perdición surge de las profundidades...', 28153),
(158967, 'esES', 'No podéis destruirnos... Somos infinitos...', 'No podéis destruirnos... Somos infinitos...', 28153),
(158966, 'esES', 'Caeréis... Vuestros amigos os abandonarán...', 'Caeréis... Vuestros amigos os abandonarán...', 28153),
(158965, 'esES', '¿Oís la llamada de la oscuridad ahí abajo?', '¿Oís la llamada de la oscuridad ahí abajo?', 28153),
(158964, 'esES', '¡Es imposible contener las enloquecedoras profundidades!', '¡Es imposible contener las enloquecedoras profundidades!', 28153),
(158963, 'esES', 'De mi cadáver surgirán miles más.', 'De mi cadáver surgirán miles más.', 28153),
(158962, 'esES', 'La aviesa oscuridad reclama el tañido de la última campana.', 'La aviesa oscuridad reclama el tañido de la última campana.', 28153),
(158961, 'esES', '¡El devorador de las profundidades ansía vuestro mundo!', '¡El devorador de las profundidades ansía vuestro mundo!', 28153),
(158960, 'esES', '¡No podéis combatir aquello que teméis!', '¡No podéis combatir aquello que teméis!', 28153),
(158959, 'esES', 'Nos propagaremos imparables hasta que vuestro mundo quede sumido en el terror.', 'Nos propagaremos imparables hasta que vuestro mundo quede sumido en el terror.', 28153),
(158958, 'esES', 'Las profundidades sin luz os llaman.', 'Las profundidades sin luz os llaman.', 28153),
(158957, 'esES', '¡Adéntraos entre gritos en el abismo!', '¡Adéntraos entre gritos en el abismo!', 28153),
(158956, 'esES', '¡Os consumiremos a todos!', '¡Os consumiremos a todos!', 28153),
(158955, 'esES', '¡Tu cadáver será entregado a las tinieblas!', '¡Tu cadáver será entregado a las tinieblas!', 28153),
(158954, 'esES', 'Naufragado...', 'Naufragada...', 28153),
(158953, 'esES', 'Siempre pensé que moriría... en el mar...', 'Siempre pensé que moriría... en el mar...', 28153),
(158952, 'esES', 'No pienso morir... así...', 'No pienso morir... así...', 28153),
(158951, 'esES', 'La culpa es... del navegante...', 'La culpa es... del navegante...', 28153),
(158950, 'esES', 'Salvadme... mastuerzos...', 'Salvadme... mastuerzos...', 28153),
(158949, 'esES', 'Prefiero morir... a seguir aquí más tiempo...', 'Prefiero morir... a seguir aquí más tiempo...', 28153),
(158948, 'esES', 'Jamás debimos... venir aquí...', 'Jamás debimos... venir aquí...', 28153),
(158947, 'esES', 'La peor... tripulación... del mundo...', 'La peor... tripulación... del mundo...', 28153),
(158946, 'esES', '¡Vuestro barco será nuestro, bribones!', '¡Vuestro barco será nuestro, bribones!', 28153),
(158945, 'esES', 'Mirad, chicos, el tesoro ha venido a nosotros, ¡y se ha traído un modo de salir de aquí!', 'Mirad, chicos, el tesoro ha venido a nosotros, ¡y se ha traído un modo de salir de aquí!', 28153),
(158944, 'esES', '¡Tienen un barco! ¡A por ellos!', '¡Tienen un barco! ¡A por ellos!', 28153),
(158943, 'esES', '¡Lamentaréis haber venido!', '¡Lamentaréis haber venido!', 28153),
(158942, 'esES', 'Ar, me he pasado un poquito con el ron...', 'Ar, me he pasado un poquito con el ron...', 28153),
(158941, 'esES', '¡Nos atacan, mostrencos! ¡En pie todos!', '¡Nos atacan, mostrencos! ¡En pie todos!', 28153),
(158940, 'esES', '¡No han venido a salvarnos, a por ellos!', '¡No han venido a salvarnos, a por ellos!', 28153),
(158939, 'esES', '¡Yar, ahora saldremos de aquí, muchachos! ¡A por ellos!', '¡Yar, ahora saldremos de aquí, muchachos! ¡A por ellos!', 28153),
(158938, 'esES', 'Al abismo regreso... Una muerte de marinero...', 'Al abismo regreso... Una muerte de marinera...', 28153),
(158937, 'esES', 'Uf... Dadme un trago de ron antes de zarpar...', 'Uf... Dadme un trago de ron antes de zarpar...', 28153),
(158936, 'esES', 'Todo se oscurece... a mi alrededor...', 'Todo se oscurece... a mi alrededor...', 28153),
(158935, 'esES', 'Oh... Ha sido un golpe bajo...', 'Oh... Ha sido un golpe bajo...', 28153),
(158934, 'esES', 'Debo ir... al barco...', 'Debo ir... al barco...', 28153),
(158933, 'esES', '¡Argh! Justo en las tripas...', '¡Argh! Justo en las tripas...', 28153),
(158932, 'esES', 'Jamás encontraréis... mi botín...', 'Jamás encontraréis... mi botín...', 28153),
(158931, 'esES', 'Yar... Mi tesoro...', 'Yar... Mi tesoro...', 28153),
(158930, 'esES', '¡Defendedme, patanes inútiles!', '¡Defendedme, patanes inútiles!', 28153),
(158929, 'esES', '¡A mí, perros sarnosos, que nos abordan!', '¡A mí, perros sarnosos, que nos abordan!', 28153),
(158928, 'esES', '¡No deberíais haber venido aquí, esto es tierra pirata!', '¡No deberíais haber venido aquí, esto es tierra pirata!', 28153),
(158927, 'esES', '¡Arr, tenemos intrusos, muchachos!', '¡Arr, tenemos intrusos, muchachos!', 28153),
(158926, 'esES', '¡Saqueo y pillaje, yar!', '¡Saqueo y pillaje, yar!', 28153),
(158925, 'esES', '¡Os estáis buscando un alfanje en las tripas!', '¡Os estáis buscando un alfanje en las tripas!', 28153),
(158924, 'esES', '¡Os pasaremos por la quilla!', '¡Os pasaremos por la quilla!', 28153),
(158923, 'esES', '¡Atentos, marineruchos, rechazad a los invasores!', '¡Atentos, marineruchos, rechazad a los invasores!', 28153),
(158922, 'esES', '¡Nada nos impedirá cazar a Onoho!', '', 28153),
(158921, 'esES', 'El mar os ha traído hasta nosotros, ya no podéis iros...', '', 28153),
(158920, 'esES', '¡Puliremos nuestras habilidades mientras esperamos que el mar nos oriente!', '', 28153),
(158919, 'esES', 'El flujo y reflujo del agua predijo este encuentro.', '', 28153),
(158918, 'esES', 'Os enfrentáis al gran clan cazador, ¿cómo esperáis sobrevivir?', '', 28153),
(158917, 'esES', 'El mar nos trae más carne y armas, ¡gracias a las olas!', '', 28153),
(158916, 'esES', '¡Vuestra carne y suministros impulsarán la gran caza, gracias!', '', 28153),
(158915, 'esES', 'Nuestro clan ha cazado al magno durante años, ¡hoy no nos detendréis!', '', 28153),
(158914, 'esES', 'El aguazal... me mostró mi destino...', '', 28153),
(158913, 'esES', 'Las olas... me llevan...', '', 28153),
(158912, 'esES', 'La caza... se lleva a otro...', '', 28153),
(158911, 'esES', 'También... sois... excelentes cazadores...', '', 28153),
(158910, 'esES', 'Hrk... Abatido justamente...', '', 28153),
(158909, 'esES', 'El mar nos traga a todos al final...', '', 28153),
(158908, 'esES', 'La caza seguirá... sin mí...', '', 28153),
(158907, 'esES', 'No nos arrepentimos... de nada...', '', 28153),
(158906, 'esES', 'Parece que las olas han arrastrado forasteros hasta aquí.', '', 28153),
(158905, 'esES', 'Os damos las gracias por vuestro sacrificio.', '', 28153),
(158904, 'esES', '¡Quitadles los suministros, esta noche tendremos festín!', '', 28153),
(158903, 'esES', '¿Osáis enfrentaros a nuestro clan?', '', 28153),
(158902, 'esES', 'Vuestra sangre impulsa la caza.', '', 28153),
(158901, 'esES', 'Vuestros cadáveres nos sustentará y os lo agradecemos.', '', 28153),
(158900, 'esES', 'El mar nos ha dado nuevos suministros...', '', 28153),
(158899, 'esES', 'Las olas predijeron vuestra llegada.', '', 28153),
(158898, 'esES', '', 'Me encantan todos los bichitos que se pueden encontrar por aquí. Conejillos, pájaros, cangrejos, todo lo que se te ocurra. Tengo unas cuantas mascotas a las que he adiestrado para ser campeones. ¿Ves estos restos de aquí? Lo hicieron mis mascotas en apenas cuatro minutos. Son voraces, los bichejos. ¿Quieres verlos en acción?', 28153),
(158897, 'esES', '', 'No pierdas de vista a Meerah, ¿quieres?\n\nNo es consciente de los auténticos peligros del desierto. No querría que se la tragaran las arenas...', 28153),
(158896, 'esES', '', 'Tu amigo tiene mucho mejor aspecto. Me alegra que Kiro y Meerah hayan podido ayudar.', 28153),
(158895, 'esES', '', '$gBienvenido:Bienvenida; a nuestro hogar, $n, al menos por ahora.\n\nLas caravanas están listas para partir en un momento, si es que los sethrak dan con nuestro escondrijo.', 28153),
(158894, 'esES', 'Intenta guiar a Loh hasta un lugar seguro a través de esas algas del camino.', '', 28153),
(158893, 'esES', '', '¡Sí, eso es! Ten, llévate unas cuantas bombas de harina. Pero ten cuidado con ellas.', 28153),
(158892, 'esES', '¿Te interesa algo de carne de oso?', '', 28153),
(158891, 'esES', '¡Kua\'fon sale a escape!', '', 28153),
(158890, 'esES', 'Kua\'fon sostiene la calavera fuera de tu alcance y mueve la cola con ánimo juguetón.', '', 28153),
(158889, 'esES', 'No eres tan... fuerte.', '', 28153),
(158888, 'esES', '¡Cogeré lo que quiero sin más!', '', 28153),
(158887, 'esES', 'Me gusta tu equipo... ¿Me lo cambias?', '', 28153),
(158886, 'esES', 'Me retiro... al agua...', '', 28153),
(158885, 'esES', 'El clan no morirá... hoy...', '', 28153),
(158884, 'esES', 'Gurrr... ¿Cómo...?', '', 28153),
(158883, 'esES', 'Regreso... a las olas...', '', 28153),
(158882, 'esES', 'El tesoro... era mío...', '', 28153),
(158881, 'esES', 'Sss...Pagaréis...', '', 28153),
(158880, 'esES', 'Hsss... Ladrones...', '', 28153),
(158879, 'esES', 'Gaah... Mi sangre...', '', 28153),
(158878, 'esES', '¡Hssss! ¡Matadlos! ¡Proteged el tesoro!', '', 28153),
(158877, 'esES', '¡Las gemas hacen fuerte a nuestro clan, no nos arrodillaremos ante vosotros!', '', 28153),
(158876, 'esES', '¡Devoraré vuestra carne y roeré vuestros huesos!', '', 28153),
(158875, 'esES', '¿Osáis enfrentaros a un gran guerrero?', '', 28153),
(158874, 'esES', '¡Yo defiendo al clan! ¡Moriréis!', '', 28153),
(158873, 'esES', '¡Intrusos! ¡Matadlos, esbirros!', '', 28153),
(158872, 'esES', '¡Este tesoro es de mi clan, ladrones!', '', 28153),
(158871, 'esES', '¡Mi clan es poderoso, no nos podéis detener!', '', 28153),
(158870, 'esES', 'A ver si puedo encontrarte un poco.', 'A ver si puedo encontrarte un poco.', 28153),
(158869, 'esES', '¡Vuestro tesoro será nuestro!', '', 28153),
(158868, 'esES', '¡Tengo helado para ti!', '¡Tengo helado para ti!', 28153),
(158867, 'esES', '¡Os destriparé como a un pez!', '', 28153),
(158866, 'esES', '¡Defended al clan!', '', 28153),
(158865, 'esES', '¡Rebanadlos, traedme su tesoro!', '', 28153),
(158864, 'esES', '¡Sss! ¡Nos atacan!', '', 28153),
(158863, 'esES', '¡Sangres calientes!', '', 28153),
(158862, 'esES', '¡Matadlos! ¡Coged sus cosas!', '', 28153),
(158861, 'esES', '¡Hssss! ¡Os asesinaremos!', '', 28153),
(158860, 'esES', '¡Ha llegado más comida, hijos míos!', '¡Ha llegado más comida, hijos míos!', 28153),
(158859, 'esES', 'Claro. ¿Qué puedo hacer por ti?', 'Claro. ¿Qué puedo hacer por ti?', 28153),
(158858, 'esES', 'Kkkk-k-k, $gotro:otra; que cae en nuestro hoyo, tu viaje toca a su fin...', 'Kkkk-k-k, $gotro:otra; que cae en nuestro hoyo, tu viaje toca a su fin...', 28153),
(158857, 'esES', 'Carne suculenta venida a nuestra guarida, qué delicia.', 'Carne suculenta venida a nuestra guarida, qué delicia.', 28153),
(158856, 'esES', 'Vuestra sangre alimentará a los jóvenes, vuestra carne nutrirá a las reinas, ¡y yo consumiré vuestro cerebro!', 'Vuestra sangre alimentará a los jóvenes, vuestra carne nutrirá a las reinas, ¡y yo consumiré vuestro cerebro!', 28153),
(158855, 'esES', '¡Jamás encontraréis los huevos, nuestro enjambre es eterno!', '¡Jamás encontraréis los huevos, nuestro enjambre es eterno!', 28153),
(158854, 'esES', '¡No forcejees, presa, eso solo prolongará tu agonía!', '¡No forcejees, presa, eso solo prolongará tu agonía!', 28153),
(158853, 'esES', '¡Ah, otra víctima en nuestras redes, ksssh!', '¡Ah, otra víctima en nuestras redes, ksssh!', 28153),
(158852, 'esES', '¡Defenderemos a la prole hasta el final!', '¡Defenderemos a la prole hasta el final!', 28153),
(158851, 'esES', 'Cuidado con... los invasores...', 'Cuidado con... los invasores...', 28153),
(158850, 'esES', 'Los huevos... están a salvo... de vosotros...', 'Los huevos... están a salvo... de vosotros...', 28153),
(158849, 'esES', 'No nos encontraréis... a todos...', 'No nos encontraréis... a todos...', 28153),
(158848, 'esES', 'No llegamos tan lejos... para que nos matarais vosotros...', 'No llegamos tan lejos... para que nos matarais vosotros...', 28153),
(158847, 'esES', 'Mi cuerpo alimentará a las crías...', 'Mi cuerpo alimentará a las crías...', 28153),
(158846, 'esES', 'Asssh... Dolor...', 'Asssh... Dolor...', 28153),
(158845, 'esES', 'Defended... a la prole...', 'Defended... a la prole...', 28153),
(158844, 'esES', 'Kasssh...', 'Kasssh...', 28153),
(158843, 'esES', '¡Los jóvenes devorarán vuestra carne!', '¡Los jóvenes devorarán vuestra carne!', 28153),
(158842, 'esES', '¡Hkkk-k-k! ¡Venid a mi red!', '¡Hkkk-k-k! ¡Venid a mi red!', 28153),
(158841, 'esES', '¡Intrusos!', '¡Intrusos!', 28153),
(158840, 'esES', '¡Protegeremos a la prole!', '¡Protegeremos a la prole!', 28153),
(158839, 'esES', 'Hsssh... Sangre fresca...', 'Hsssh... Sangre fresca...', 28153),
(158838, 'esES', 'He aquí la presa...', 'He aquí la presa...', 28153),
(158837, 'esES', '¡Perturbáis nuestras telarañasss!', '¡Perturbáis nuestras telarañasss!', 28153),
(158836, 'esES', 'Ksssh... Invasoresss...', 'Ksssh... Invasoresss...', 28153),
(158835, 'esES', '', 'Últimamente estoy muy golosa. ¡Me encantaría un buen helado de fresa!\n\nTe lo agradecería muchísimo si pudieras encontrarme uno. Si no es mucha molestia, trae suficiente para que sobre para luego. ¡Espero no ser muy pesada!', 28153),
(158834, 'esES', '', 'Estás un poco $gdelgado:delgada;, cielo. ¿Comes bien?', 28153),
(158833, 'esES', '', 'Oooh. ¿Has venido hasta aquí para verme a mí?', 28153),
(158832, 'esES', '', 'Hola, cariño. Me alegra verte.', 28153),
(158831, 'esES', '¡Raar! ¡Rargh!', '', 28153),
(158830, 'esES', 'Vosotros... no...', '', 28153),
(158829, 'esES', 'Argrrr...', '', 28153),
(158828, 'esES', 'Grrrr...', '', 28153),
(158827, 'esES', 'Olor... malo...', '', 28153),
(158826, 'esES', 'Hay que... correr...', '', 28153),
(158825, 'esES', 'Argh...', '', 28153),
(158824, 'esES', 'Argh... grah...', '', 28153),
(158823, 'esES', '¡Olor nuevo, no bueno, rarrr!', '', 28153),
(158822, 'esES', '¡Arrr, oler carne!', '', 28153),
(158821, 'esES', '¡Grar! ¡Vosotros alimentarnos!', '', 28153),
(158820, 'esES', '¡Morder, comerme vuestra carne!', '', 28153),
(158819, 'esES', '¡Morir! ¡Rargh!', '', 28153),
(158818, 'esES', 'Rrrr... vosotros... ¡Yo matar!', '', 28153),
(158817, 'esES', '¡Grrrargh!', '', 28153),
(158816, 'esES', '¡Mmrrr!', '', 28153),
(158815, 'esES', 'Estas espesuras han vivido mucho más tiempo que vosotros, y os sobrevivirán.', 'Estas espesuras han vivido mucho más tiempo que vosotros, y os sobrevivirán.', 28153),
(158814, 'esES', '¡Las gemas resplandecientes son un regalo que nos hizo la naturaleza y las protegeremos de los vuestros!', '¡Las gemas resplandecientes son un regalo que nos hizo la naturaleza y las protegeremos de los vuestros!', 28153),
(158813, 'esES', 'El ciclo os alcanzará hoy, invasores, y creceremos a partir de vuestros restos.', 'El ciclo os alcanzará hoy, invasores, y creceremos a partir de vuestros restos.', 28153),
(158812, 'esES', 'Acabaré con vuestra amenaza antes de que sigáis corrompiendo nuestras tierras.', 'Acabaré con vuestra amenaza antes de que sigáis corrompiendo nuestras tierras.', 28153),
(158811, 'esES', 'Nutriréis el suelo que habéis hollado en vuestro camino hasta aquí.', 'Nutriréis el suelo que habéis hollado en vuestro camino hasta aquí.', 28153),
(158810, 'esES', 'Vuestra especie está desequilibrada, no se os puede sustentar. Debo intervenir.', 'Vuestra especie está desequilibrada, no se os puede sustentar. Debo intervenir.', 28153),
(158809, 'esES', 'Debo destruiros para preservar el equilibrio que habéis roto.', 'Debo destruiros para preservar el equilibrio que habéis roto.', 28153),
(158808, 'esES', 'Nuestra misión es cuidar esta tierra y a sus bestias, ¡y aquí no sois bienvenidos!', 'Nuestra misión es cuidar esta tierra y a sus bestias, ¡y aquí no sois bienvenidos!', 28153),
(158807, 'esES', 'Vuestra especie es... una plaga...', 'Vuestra especie es... una plaga...', 28153),
(158806, 'esES', 'Mancilláis... nuestras tierras...', 'Mancilláis... nuestras tierras...', 28153),
(158805, 'esES', 'No podéis matar... a la naturaleza...', 'No podéis matar... a la naturaleza...', 28153),
(158804, 'esES', 'Resurgiremos...', 'Resurgiremos...', 28153),
(158803, 'esES', 'Vuestra especie... no durará...', 'Vuestra especie... no durará...', 28153),
(158802, 'esES', 'Alimento... a la tierra...', 'Alimento... a la tierra...', 28153),
(158801, 'esES', 'Habéis roto... el equilibrio...', 'Habéis roto... el equilibrio...', 28153),
(158800, 'esES', 'Vuelvo... a la naturaleza...', 'Vuelvo... a la naturaleza...', 28153),
(158799, 'esES', '¡Se nos encomendó proteger este lugar!', '¡Se nos encomendó proteger este lugar!', 28153),
(158798, 'esES', '¡Las gemas resplandecientes son un regalo para la espesura!', '¡Las gemas resplandecientes son un regalo para la espesura!', 28153),
(158797, 'esES', '¡Debemos preservar el equilibrio!', '¡Debemos preservar el equilibrio!', 28153),
(158796, 'esES', '¡No corromperéis nuestro claro!', '¡No corromperéis nuestro claro!', 28153),
(158795, 'esES', '¡Respondo a la llamada de la naturaleza!', '¡Respondo a la llamada de la naturaleza!', 28153),
(158794, 'esES', '¡No arruinaréis esta tierra, invasores!', '¡No arruinaréis esta tierra, invasores!', 28153),
(158793, 'esES', '¡Que la naturaleza guíe mi cólera!', '¡Que la naturaleza guíe mi cólera!', 28153),
(158792, 'esES', '¡Debo proteger la espesura!', '¡Debo proteger la espesura!', 28153),
(158791, 'esES', 'Vengo aquí cada día a hablar con mih abueloh. ¡Creo que pueden oírme!', '', 28153),
(158790, 'esES', 'Gruh...', 'Gruh...', 28153),
(158789, 'esES', '¿Dónde... estoy...?', '¿Dónde... estoy...?', 28153),
(158788, 'esES', 'Grah... Sangre...', 'Grah... Sangre...', 28153),
(158787, 'esES', '', 'Tras ganar la batalla empieza el trabajo de verdad.', 28153),
(158786, 'esES', 'Mi ira... disminuye...', 'Mi ira... disminuye...', 28153),
(158785, 'esES', 'Vosotros... Por qué...', 'Vosotros... Por qué...', 28153),
(158784, 'esES', 'Debo... huir...', 'Debo... huir...', 28153),
(158783, 'esES', 'Ahora veo... con más claridad...', 'Ahora veo... con más claridad...', 28153),
(158782, 'esES', 'Argh... Dolor...', 'Argh... Dolor...', 28153),
(158781, 'esES', '¡Grarh!', '¡Grarh!', 28153),
(158780, 'esES', '¡Rabia!', '¡Rabia!', 28153),
(158779, 'esES', 'Desconocido...', 'Desconocido...', 28153),
(158778, 'esES', 'Oler miedo...', 'Oler miedo...', 28153),
(158777, 'esES', 'Marchar... rrr...', 'Marchar... rrr...', 28153),
(158776, 'esES', 'Mataros...', 'Mataros...', 28153),
(158775, 'esES', 'Grrr...', 'Grrr...', 28153),
(158774, 'esES', '¡Rargh!', '¡Rargh!', 28153),
(158773, 'esES', '¡Mira qué grande se ehtá haciendo! Sale a su padre.', '', 28153),
(158772, 'esES', 'Maldita sea...', 'Maldita sea...', 28153),
(158771, 'esES', 'Veo... a loh ancehtroh...', 'Veo... a loh ancehtroh...', 28153),
(158770, 'esES', 'Loh ehpírituh... me acogen...', 'Loh ehpírituh... me acogen...', 28153),
(158769, 'esES', 'No tenéih... honor...', 'No tenéih... honor...', 28153),
(158768, 'esES', 'Uf... Me han matado...', 'Uf... Me han matado...', 28153),
(158767, 'esES', 'No podréih matarnoh... a todoh...', 'No podréih matarnoh... a todoh...', 28153),
(158766, 'esES', 'Me vengaré de vosotroh... dehde el otro lado...', 'Me vengaré de vosotroh... dehde el otro lado...', 28153),
(158765, 'esES', 'Voy con loh ehpírituh...', 'Voy con loh ehpírituh...', 28153),
(158764, 'esES', '¡Haré un maleficio con tuh huesoh y le echaré una maldición a toda tu familia!', '¡Haré un maleficio con tuh huesoh y le echaré una maldición a toda tu familia!', 28153),
(158763, 'esES', '¡No ereh máh que $gun sucio forahtero:una sucia forahtera; y ehte no eh tu sitio!', '¡No ereh máh que $gun sucio forahtero:una sucia forahtera; y ehte no eh tu sitio!', 28153),
(158762, 'esES', '', 'Parece que fue ayer cuando nuehtro peque tuvo a ehte peque. ¡Y míralo ahora!', 28153),
(158761, 'esES', 'Eh, ¿quieneh soih? Aquí no soih bienvenidoh, ¿vale?', 'Eh, ¿quieneh soih? Aquí no soih bienvenidoh, ¿vale?', 28153),
(158760, 'esES', 'Bueno, a ver qué sabeh hacer...', 'Bueno, a ver qué sabeh hacer...', 28153),
(158759, 'esES', 'Ya tenemoh lah gemah, ¡mi clan eh el máh fuerte!', 'Ya tenemoh lah gemah, ¡mi clan eh el máh fuerte!', 28153),
(158758, 'esES', 'No os será tan fácil encontrarme, je.', 'No os será tan fácil encontrarme, je.', 28153),
(158757, 'esES', 'Eh mi ihla, son mih gemah, no habéih encontrado máh que la muerte.', 'Eh mi ihla, son mih gemah, no habéih encontrado máh que la muerte.', 28153),
(158756, 'esES', 'Ehte sitio lo encontramoh nosotroh, $ginvasor:invasora;, ¡y no noh lo quitaráh!', 'Ehte sitio lo encontramoh nosotroh, $ginvasor:invasora;, ¡y no noh lo quitaráh!', 28153),
(158755, 'esES', '¡Ehta eh nuehtra ihla!', '¡Ehta eh nuehtra ihla!', 28153),
(158754, 'esES', 'Eh, ¿qué hacéih en ehta ihla?', 'Eh, ¿qué hacéih en ehta ihla?', 28153),
(158753, 'esES', '¡Noh atacan! ¡Venid aquí!', '¡Noh atacan! ¡Venid aquí!', 28153),
(158752, 'esES', '¡Rebanadloh enseguida!', '¡Rebanadloh enseguida!', 28153),
(158751, 'esES', '¡Váih a ver cómo oh devoro!', '¡Váih a ver cómo oh devoro!', 28153),
(158750, 'esES', '¡Oh dehpellejaremoh vivoh!', '¡Oh dehpellejaremoh vivoh!', 28153),
(158749, 'esES', '¡Me haré un collar con vuehtroh huesoh!', '¡Me haré un collar con vuehtroh huesoh!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'esES', '¡Voy a dehtriparte y a beberme tu sangre, colega!', '¡Voy a dehtriparte y a beberme tu sangre, colega!', 28153),
(158747, 'esES', '¡Argh! ¡Caigo con honor!', '', 28153),
(158746, 'esES', 'Vosotros sois... los invasores... Nosotros no hemos hecho nada...', '', 28153),
(158745, 'esES', 'Las gemas... no han podido salvarnos...', '', 28153),
(158744, 'esES', 'Volveremos... y seremos más...', '', 28153),
(158743, 'esES', 'Las estrellas... mintieron...', '', 28153),
(158742, 'esES', 'Oigo la llamada... de los ancestros...', '', 28153),
(158741, 'esES', 'Los espíritus me acogen...', '', 28153),
(158740, 'esES', 'Me uno... a mis ancestros...', '', 28153),
(158739, 'esES', '¡Las estrellas guían mis puños, el futuro está escrito con vuestra sangre!', '', 28153),
(158738, 'esES', 'Los vientos me han dicho que hoy fracasaréis.', '', 28153),
(158737, 'esES', '¡Espíritus, dadme la fuerza de una llamarada insaciable!', '', 28153),
(158736, 'esES', '¡Empiezas una pelea que no puedes ganar, enclenque!', '', 28153),
(158735, 'esES', 'Las riquezas de estas islas son nuestras, idiotas.', '', 28153),
(158734, 'esES', '¡Los ancestros me dan fuerza y sabiduría!', '', 28153),
(158733, 'esES', '¡Me ungiré los cuernos con vuestra sangre, necios!', '', 28153),
(158732, 'esES', '¡Defenderé a mi clan, $gforastero:forastera;!', '', 28153),
(158731, 'esES', '¡Ayudadme, guerreros!', '', 28153),
(158730, 'esES', '¡Preparaos, nos atacan!', '', 28153),
(158729, 'esES', '¡Esta isla es nuestra, no tenéis ningún derecho!', '', 28153),
(158728, 'esES', '¡Las gemas brillantes son nuestras, no tienes ninguna posibilidad!', '', 28153),
(158727, 'esES', '¡No nos arrebatarás este sitio, $gforastero:forastera;!', '', 28153),
(158726, 'esES', '¡Invasores! ¡Rechazadlos!', '', 28153),
(158725, 'esES', '¡Que los espíritus guíen mi hoja!', '', 28153),
(158724, 'esES', '¡Por los ancestros!', '', 28153),
(158723, 'esES', 'Eso... doler...', '', 28153),
(158722, 'esES', '¿Por qué... haber venido...?', '', 28153),
(158721, 'esES', '¡Argh! En toda barriga...', '', 28153),
(158720, 'esES', 'Tú... $gladrón:ladrona;...', '', 28153),
(158719, 'esES', '¡No! Mis gemas...', '', 28153),
(158718, 'esES', '¿Por qué... hacer eso?', '', 28153),
(158717, 'esES', 'Uf... Eso no bueno...', '', 28153),
(158716, 'esES', '¿Por qué oscuro ahora?', '', 28153),
(158715, 'esES', '', 'Ehtán loh que creen que un trato eh solo un trato. Promesah vacíah y pohtureo. Lah recompensah de hoy a cambio de un futuro inehcrutable.\n\nPero recuerda ehto: Bwonsamdi se cobra todah su deudah. Máh tarde o máh temprano.', 28153),
(158714, 'esES', '¡Ogros todos, hora de aplastar!', '', 28153),
(158713, 'esES', '¡No! ¡Gemas mías! ¡No vuestras! ¡Yo necesitar!', '', 28153),
(158712, 'esES', 'Las gemas hacernos fuertes, $ginvasor:invasora;. ¡Más que tú!', '', 28153),
(158711, 'esES', '¡Yo tomar cabeza de trofeo al acabar!', '', 28153),
(158710, 'esES', '¡A por ellos! ¡Romper sus columnas!', '', 28153),
(158709, 'esES', 'Esta isla mía, $gcanijo:canija;. ¡Mía!', '', 28153),
(158708, 'esES', '¡Yo aplastar, beber sangre!', '', 28153),
(158707, 'esES', '¡Yo aplastar mucho! ¡Raargh!', '', 28153),
(158706, 'esES', '¡Gemas mías! ¡Aaargh!', '', 28153),
(158705, 'esES', '¡No coger nuestras cosas!', '', 28153),
(158704, 'esES', '¡A por ellos!', '', 28153),
(158703, 'esES', '¡No llevar gemas!', '', 28153),
(158702, 'esES', '¡Isla mía! ¡Iros ya!', '', 28153),
(158701, 'esES', '¡Matar a los intrusos!', '', 28153),
(158700, 'esES', '¡Chafar, aplastar, matar!', '', 28153),
(158699, 'esES', '¡Yo aplastar!', '', 28153),
(158698, 'esES', 'Puede que si prometo ser mejor persona ehta vez... ¡No como la anterior!', 'Puede que si prometo ser mejor persona ehta vez... ¡No como la anterior!', 28153),
(158697, 'esES', '¿Qué creeh que Bwonsamdi puede querer de mí?', '¿Qué creeh que Bwonsamdi puede querer de mí?', 28153),
(158696, 'esES', 'Qué hacer... Qué hacer... ¡Tiene que haber algún modo de salir de ehta!', 'Qué hacer... Qué hacer... ¡Tiene que haber algún modo de salir de ehta!', 28153),
(158695, 'esES', 'Si hago un trato con Bwonsamdi, todo volverá a la normalidad, ¿no?', 'Si hago un trato con Bwonsamdi, todo volverá a la normalidad, ¿no?', 28153),
(158694, 'esES', '¡Odio ehto! ¡Lo odio todo!', '¡Odio ehto! ¡Lo odio todo!', 28153),
(158693, 'esES', '¡Eh inaceptable! ¿No saben quién soy?', '¡Eh inaceptable! ¿No saben quién soy?', 28153),
(158692, 'esES', '¡Iré a por quien me haya hecho ehto! ¡Aunque sea lo último que haga!', '¡Iré a por quien me haya hecho ehto! ¡Aunque sea lo último que haga!', 28153),
(158691, 'esES', '¿Cómo ha podido pasar? ¡No eh juhto!', '¿Cómo ha podido pasar? ¡No eh juhto!', 28153),
(158690, 'esES', 'Ehto no va a ir a mejor y nada me convencerá de lo contrario.', 'Ehto no va a ir a mejor y nada me convencerá de lo contrario.', 28153),
(158689, 'esES', 'Con lo bien que me iba y mírame ahora... Ya no soy nada.', 'Con lo bien que me iba y mírame ahora... Ya no soy nada.', 28153),
(158688, 'esES', 'Ya no volveré a sentir el sol.', 'Ya no volveré a sentir el sol.', 28153),
(158687, 'esES', 'Si tuviera solo unoh díah máh... Podría haber hecho tantah cosah.', 'Si tuviera solo unoh díah máh... Podría haber hecho tantah cosah.', 28153),
(158686, 'esES', '¿Muerto? Qué va, solo ehtaba dehcansando.', '¿Muerta? Qué va, solo ehtaba dehcansando.', 28153),
(158685, 'esES', '¿Quién ereh? Da igual, muy importante no será...', '¿Quién ereh? Da igual, muy importante no será...', 28153),
(158684, 'esES', 'Lo que yo no veo, no pasa. Así de sencillo.', 'Lo que yo no veo, no pasa. Así de sencillo.', 28153),
(158683, 'esES', 'Sigue así... Sigue así... Al final saldrá bien...', 'Sigue así... Sigue así... Al final saldrá bien...', 28153),
(158682, 'esES', '¿Cómo osas pisotear MI fuerte? ¡Ya basta!', '', 28153),
(158681, 'esES', 'Eres débil. ¡Enfréntate a mí en auténtico combate!', '', 28153),
(158680, 'esES', '¡¿Crees que tu patética máquina puede conmigo?!', '', 28153),
(158679, 'esES', '¡Vaya, $gun:una; contendiente! ¡Toma esto!', '', 28153),
(158678, 'esES', 'Pero si... soy demasiado guapo para morir...', '', 28153),
(158677, 'esES', '', 'Te... destriparé...', 28153),
(158676, 'esES', '', '¡Te cortaré a tiras!', 28153),
(158675, 'esES', 'Enterradme en el mar...', '', 28153),
(158674, 'esES', '¡Te pasaré por la quilla!', '', 28153),
(158673, 'esES', 'Ah, este tipo... No sé qué es peor, la cantidad de gomina que utiliza o su poesía de aficionado. Pero que no te engañe: aunque Reed sea un donjuán, es un gran luchador.', '', 28153),
(158672, 'esES', 'Beckett está convencido de que es toda una leyenda.', '', 28153),
(158671, 'esES', 'Luna es un poco... cortante, por así decirlo.', '', 28153),
(158670, 'esES', 'Je... Lo único seguro en esta vida: los impuestos y...', '', 28153),
(158669, 'esES', '¿Qué tenemos aquí? ¡Parece una cuenta pendiente de saldar!', '', 28153),
(158668, 'esES', '', 'Espero que no sea demasiado tarde... Parte de inmediato. Encuentra a mi hija.', 28153),
(158666, 'esES', '', 'Fin del Destino es una isla cercana a la costa de Canto Tormenta. Allí se destierra a los peores criminales y traidores para que no regresen nunca.', 28153),
(158665, 'esES', '', '¡Adalid! ¿Qué has descubierto?', 28153),
(158661, 'esES', '¡Me largo de aquí! ¡Gracias por tu ayuda, $p!', '', 28153),
(158660, 'esES', 'Kua\'fon suelta un chirrido agudo y agita la cola con entusiasmo.', '', 28153),
(158659, 'esES', 'Kua\'fon te vuelve a colocar la calavera en la mano.', '', 28153),
(158658, 'esES', 'Kua\'fon deja caer el cráneo a sus pies y te chilla alegremente.', '', 28153),
(158657, 'esES', '', 'Esta guerra está perdida. Teldrassil no tardará en caer.', 28153),
(158656, 'esES', '¡Las mareas te tragarán por completo!', '', 28153),
(158655, 'esES', 'Vamos, adalid. Sigamos a nuestra Jefa de Guerra hasta la... victoria.', '', 28153),
(158654, 'esES', '', 'No está mal. ¡Todos arriba!', 28153),
(158653, 'esES', 'Tú también debes elegir entre llevártelo a Darnassus y morir junto a él cuando lo conquistemos, o huir lejos de aquí y sobrevivir. ', '', 28153),
(158652, 'esES', '', 'Le has perdonado la vida a Malfurion, así que dejaré que elijas.', 28153),
(158651, 'esES', '', '¡Firmes!', 28153),
(158650, 'esES', 'Hay un motivo. Derramamos sangre para que la Horda perdure.', '', 28153),
(158649, 'esES', '', 'Toda esta guerra es deshonrosa. ¿¡Cómo os atrevéis a derramar la sangre de tantos inocentes... sin motivo!?', 28153),
(158648, 'esES', 'Mi ataque fue deshonroso. No merecía acabar con su vida.', '', 28153),
(158647, 'esES', '', 'Orco... ¿Por qué no lo has matado?', 28153),
(158646, 'esES', '', '¡Malfurion! ¡No!', 28153),
(158645, 'esES', 'Has puesto a... tu Horda... al servicio... de la muerte. Algún día... lo lamentarás.', '', 28153),
(158642, 'esES', '', 'Cúrate las heridas y da descanso a tus huesos. Aquí estás a salvo.', 28153),
(158641, 'esES', 'Morí por meterme con la behtia equivocada. Ya sabeh cuál.', 'Morí por meterme con la behtia equivocada. Ya sabeh cuál.', 28153),
(158640, 'esES', 'Ehtoy tan confundido como tú, colega.', 'Ehtoy tan confundida como tú, colega.', 28153),
(158639, 'esES', 'El chili de Haw\'li fue demasiado picante pa mí.', 'El chili de Haw\'li fue demasiado picante pa mí.', 28153),
(158638, 'esES', 'Morí corriendo en la Torcanata. ¡Y volvería a hacerlo si pudiera!', 'Morí corriendo en la Torcanata. ¡Y volvería a hacerlo si pudiera!', 28153),
(158637, 'esES', 'Deja tu cuerpo en la entrada, ¿quiereh?', 'Deja tu cuerpo en la entrada, ¿quiereh?', 28153),
(158636, 'esES', 'Me cayó un rayo mientrah andaba por El Zócalo.', 'Me cayó un rayo mientrah andaba por El Zócalo.', 28153),
(158635, 'esES', 'Morí al caerme de la pirámide y no recuerdo cómo llegué aquí.', 'Morí al caerme de la pirámide y no recuerdo cómo llegué aquí.', 28153),
(158634, 'esES', 'De punta en blanco y sin tener adonde ir.', 'De punta en blanco y sin tener adonde ir.', 28153),
(158633, 'esES', 'Calcular el sitio correcto en el que colocar este portal en Boralus no era fácil, ¡pero como desafío ha estado bien! Ya me dirás cómo va, ¿eh?', '', 28153),
(158632, 'esES', 'Como desees, Nathanos.', '', 28153),
(158631, 'esES', 'Zelling, acompaña a $n a Boralus. Oculeth está esperando con un portal.', '', 28153),
(158630, 'esES', 'Hola, adalid. Tenemoh que hablar.', '', 28153),
(158629, 'esES', 'Este es el mejor asiento del local... Cuando me levante es tuyo.', '', 28153),
(158628, 'esES', '', '¿$p? Pff, no sé ni quién eres.', 28153),
(158627, 'esES', 'Cuando estés $glisto:lista; para ir a los barcos, Hobart te espera fuera para ayudarte.', '', 28153),
(158626, 'esES', 'No digas que no te avisamos.', 'No digas que no te avisamos.', 28153),
(158625, 'esES', '¡Atrás! Es por tu propio bien.', '¡Atrás! Es por tu propio bien.', 28153),
(158624, 'esES', 'Kua\'fon se estremece de terror.', '', 28153),
(158623, 'esES', 'Cómo han cambiado las tornas a nuestro favor, ¿no crees, $n?', '', 28153),
(158622, 'esES', 'Veo grandes cosas en el horizonte para ambos.', '', 28153),
(158621, 'esES', 'No puedeh dejarme aquí sin máh. Tengo loh huesoh demasiado viejoh pa trabajar en ehtah minah.', 'No puedeh dejarme aquí sin máh. Tengo loh huesoh demasiado viejoh pa trabajar en ehtah minah.', 28153),
(158620, 'esES', 'Ya veo en qué podemos habernos equivocado en la etapa de fermentación.', '', 28153),
(158619, 'esES', 'Así que la introducción de contaminantes ocultos puede afectar al proceso de reducción inicial.', '', 28153),
(158618, 'esES', 'Hecho.', '', 28153),
(158617, 'esES', 'Encantado de ayudar.', '', 28153),
(158616, 'esES', 'A trabajar, pues.', '', 28153),
(158615, 'esES', 'Claro, lo que haga falta.', '', 28153),
(158614, 'esES', 'Supongo que puedo echar una mano.', '', 28153),
(158612, 'esES', '', 'Mira a tu alrededor: los árboles tienen ojos, adalid. Ciégalos.', 28153),
(158611, 'esES', 'Primero deberíamos centrarnos en estabilizar los compuestos claves.', '', 28153),
(158610, 'esES', '¡Aaah! ¡Eso explica muchas cosas! \"La primera ley de la alquimia: para obtener algo de beneficio, debe ofrecerse una sustitución recíproca\".', '', 28153),
(158609, 'esES', '¡Vamos!', '¡Vamos!', 28153),
(158608, 'esES', 'Interesante... Es crucial una aplicación de calor precisa.', '', 28153),
(158607, 'esES', '¡Aaah! Creo que ya sé en qué ha fallado el catalizador.', '', 28153),
(158606, 'esES', 'Qué raro... ¿Cómo íbamos a predecir algo así?', '', 28153),
(158605, 'esES', 'Mmm... Muy interesante.', '', 28153),
(158604, 'esES', 'Parece que se han llevado a algunos de los nuestros. ¿Les echamos una mano?', '', 28153),
(158603, 'esES', '¡Eh! ¡Alguien ha mangado parte de nuestras mercancías! ¡Tenemos que recuperarlas, pero ya! Y con intereses.', '', 28153),
(158602, 'esES', 'Oh... ¡Heridos por todos lados! ¡Tenemos que ayudarlos!', '', 28153),
(158601, 'esES', '¿Algún ladrón taimado por aquí? ¡Tengo un trabajito para alguien así!', '', 28153),
(158600, 'esES', 'Escuchad, si encontráis alguna pieza para mi triciclo de guerra, decídmelo. Cuando lo repare, igual os dejo que os deis un voltio.', '', 28153),
(158599, 'esES', 'He descubierto algo que está pidiendo a gritos que lo aplasten al estilo de Kezan.', '', 28153),
(158598, 'esES', '¡Vaya! ¡Menudo tamaño el de ese bicho! ¿Alguien quiere matarlo?', '', 28153),
(158597, 'esES', 'Han capturado a varios miembros de la Alianza. ¿Os veis con fuerzas para una misión de rescate?', '', 28153),
(158596, 'esES', 'Las fuerzas enemigas se han fugado con suministros valiosos. Que esos ladrones sepan cómo imparte justicia la Alianza.', '', 28153),
(158595, 'esES', 'En el campo de batalla hay soldados heridos. Nos vendría bien un médico.', '', 28153),
(158594, 'esES', 'Sí, pequeña. Elune los guiaba. Bendijo a nuestros druidas con la fuerza necesaria para conjurar un viento que hinchara sus velas.', '', 28153),
(158593, 'esES', '', '¿Ha sido benigno el Mar de la Bruma con ellos, Shan\'do?', 28153),
(158592, 'esES', 'Envíame de vuelta al puerto.', 'Envíame de vuelta al puerto.', 28153),
(158591, 'esES', 'Envíame al barco más pequeño.', 'Envíame al barco más pequeño.', 28153),
(158590, 'esES', 'Necesitamos voluntarios osados para una operación encubierta. El sigilo y el ingenio son imprescindibles.', '', 28153),
(158589, 'esES', 'Estamos intentando hacernos con los restos de una máquina de guerra enemiga. Recojamos todos los componentes que encontremos.', '', 28153),
(158588, 'esES', '¡Ah! Tenemos una oportunidad única en el punto de mira.', '', 28153),
(158587, 'esES', 'Unos animales salvajes enormes deambulan por el campo de batalla. ¡Que comience la cacería!', '', 28153),
(158586, 'esES', '¿Quieres decirle hola a mi amiguito?', '', 28153),
(158585, 'esES', 'Eres como una patada en... las bombas, colega.', '', 28153),
(158584, 'esES', 'Eh, para.', '', 28153),
(158583, 'esES', 'Vuelve de una pieza, ¿vale?', '', 28153),
(158582, 'esES', 'Mantén los ojos bien abiertos.', '', 28153),
(158581, 'esES', 'Ándate con cuidado.', '', 28153),
(158580, 'esES', '¿Qué hay de nuevo?', '', 28153),
(158579, 'esES', '¿Qué tal va todo?', '', 28153),
(158578, 'esES', 'Tienes buen aspecto.', '', 28153),
(158577, 'esES', 'Por la Luz, qué bien me vendría otro trago.', '', 28153),
(158576, 'esES', 'No hay oro que pague esto.', '', 28153),
(158575, 'esES', 'Sí, sí...', '', 28153),
(158574, 'esES', 'Sigue tu camino.', '', 28153),
(158573, 'esES', 'Puedes marcharte.', '', 28153),
(158572, 'esES', 'No pierdas de vista al enemigo.', '', 28153),
(158571, 'esES', '¿Sí?', '', 28153),
(158570, 'esES', 'Tienes toda mi atención.', '', 28153),
(158569, 'esES', 'Gloria a la Alianza.', '', 28153),
(158568, 'esES', '', 'No... No puede ser.', 28153),
(158565, 'esES', '', '¡Me ayudarás a probar los límites de mi poder!', 28153),
(158564, 'esES', '', 'Hay quien dice que mi magia es cruel, pero solo quiero explorar los límites de lo posible.', 28153),
(158563, 'esES', 'Hozando.', 'Hozando.', 28153),
(158562, 'esES', 'Mia... ¡MIA! Abre los ojos, mi Reina... ¡Amor mío!', '', 28153),
(158561, 'esES', 'Que vuestra diosa os proteja.', '', 28153),
(158560, 'esES', 'La Reina alma en pena asesinó a mi hijo y me robó el reino. ¡No me arrebatará a mi amada!', '', 28153),
(158559, 'esES', '', 'No... irán...', 28153),
(158558, 'esES', 'Astarii, ¡has hecho todo lo que estaba en tu mano! Ordena a los sacerdotes que nos sigan.', '', 28153),
(158557, 'esES', '¡Nunca! ¡Os salvaré a las dos!', '', 28153),
(158555, 'esES', '', 'El árbol... ¡Están quemando el árbol! La niña... Sálvala. Abandóname a mí...', 28153),
(158554, 'esES', 'No puedes quedarte aquí. ¡Debemos huir a través del portal!', '', 28153),
(158553, 'esES', '', 'Astarii, no hay tiempo que perder. ¡Hay que evacuar la ciudad antes de que arda hasta los cimientos!', 28153),
(158551, 'esES', '', 'Acaba con él. Tómate tu tiempo, si quieres, pero tráeme su cabeza. Te estaré esperando en el Árbol del Mundo.', 28153),
(158550, 'esES', '', 'Mi victoria era inevitable, tan solo me hacía perder el tiempo.', 28153),
(158549, 'esES', 'No. No debí interferir.', '', 28153),
(158548, 'esES', '', 'Nada de lamentos. Has hecho bien.', 28153),
(158547, 'esES', 'Un golpe sin honor. Lo... lamento.', '', 28153),
(158546, 'esES', '¡Aah! ¿Colmillosauro?', '', 28153),
(158545, 'esES', '¡La Jefa de Guerra se enfrenta sola a Tempestira! Tengo que...', '', 28153),
(158544, 'esES', '¿Desde el norte? ¿Pero cómo...? Han escalado las montañas de Frondavil. ¡Claro!', '', 28153),
(158543, 'esES', 'Adalid, Delaryn, interceptadlos en Auberdine. Yo me ocuparé de la zona norte.', '', 28153),
(158542, 'esES', 'La Horda va a atravesar el muro, solo es cuestión de tiempo. Nos atacarán desde ambos flancos.', '', 28153),
(158541, 'esES', 'Los fuegos fatuos... ¡están desorientados! ¡El muro va a caer!', '', 28153),
(158540, 'esES', '', 'Ese sonido... ¿Es posible...? ¡Shan\'do! ¡La Horda se acerca desde el norte!', 28153),
(158539, 'esES', '', 'Es la hora: ¡el Árbol del Mundo es nuestro! Encuentra a Colmillosauro. Acabaremos con esto de una vez por todas.', 28153),
(158537, 'esES', '', '¡Mira a tu alrededor, adalid! Qué espectáculo tan hermoso... Los fuegos fatuos se dispersan. Poco a poco, el muro se derrumba.', 28153),
(158536, 'esES', '', '¡Colmillosauro! Ya era hora.', 28153),
(158535, 'esES', '¡POR LA HORDA!', '', 28153),
(158534, 'esES', '', '¿Dónde has volado, pajarito?', 28153),
(158533, 'esES', '', '¡Ah! ¡Mis ojos! ¡Quema!', 28153),
(158532, 'esES', '¡Fuera de aquí, bruja!', '', 28153),
(158531, 'esES', '', '¿Quién hubiera imaginado que vendrías a proteger tus preciados árboles?', 28153),
(158530, 'esES', '', 'Malfurion... Qué privilegio tenerte entre nosotros...', 28153),
(158529, 'esES', '¡Sylvanas! ¡Tus infames actos profanan este lugar sagrado! ¡Andu-falah-dor!', '', 28153),
(158528, 'esES', '', 'No les concederemos el lujo de descansar durante la noche. Esto es la guerra.', 28153),
(158527, 'esES', '', 'Mientras tanto, haremos todo lo posible para seguir presionando a los kaldorei.', 28153),
(158526, 'esES', '', 'Seguiré guiando a nuestros soldados a través del muro mientras esperamos noticias de Colmillosauro.', 28153),
(158525, 'esES', '', 'No podemos relajarnos ahora.', 28153),
(158524, 'esES', '', 'El Río Culebra está en un punto muerto, y Malfurion lo sabe.', 28153),
(158523, 'esES', '', 'Campeones de la Horda, ¡os necesitamos en el Río Culebra! ¡Es nuestra oportunidad de obtener la victoria!', 28153),
(158522, 'esES', '', '... que tengo un cuervo que cazar.', 28153),
(158521, 'esES', '', 'Date prisa. Cuando hayas conseguido toda la azerita que puedas, dásela a nuestros ingenieros.', 28153),
(158520, 'esES', '', 'Seguro que ese barco viene de Darnassus. Lo que significa...', 28153),
(158519, 'esES', '', 'Ten cuidado, adalid. Parece que la Alianza se nos ha adelantado.', 28153),
(158518, 'esES', '', 'Azerita... Con esto en nuestro poder, ¡todo aquel que se oponga a la Horda morirá!', 28153),
(158517, 'esES', '', '¡Zapadores! ¡Equipaos y seguidme! Traed todas vuestras trituradoras.', 28153),
(158516, 'esES', '', 'Acaba con ellos o cubrirán el bosque con la sangre de nuestra gente.', 28153),
(158515, 'esES', '', 'Veo que esto te preocupa. Esos ancestros se han vuelto contra ti, druida... contra su obligación sagrada.', 28153),
(158514, 'esES', '¡Taelia! ¿Nos recoges, por favor?', '', 28153),
(158513, 'esES', 'Y con eso, lo que quiero decir es \"saltar desde el acantilado\". ¡Vamos!', '', 28153),
(158512, 'esES', '¡Y emprender una huida dramática!', '', 28153),
(158511, 'esES', 'Solo tenemos que coger el arcón...', '', 28153),
(158510, 'esES', 'Nunca me di cuenta de lo perjudicial que puede ser el sol para la piel que nos queda.', 'Nunca me di cuenta de lo perjudicial que puede ser el sol para la piel que nos queda.', 28153),
(158509, 'esES', 'Te aseguro que mi plan es brillante.', '', 28153),
(158508, 'esES', 'Tendrás un plan para salir de aquí con eso, ¿no?', 'Tendrás un plan para salir de aquí con eso, ¿no?', 28153),
(158507, 'esES', 'Harlan aumentó su seguridad añadiendo otro cerrojo al arcón.\n\n<Flynn se frota la barbilla>.\n\nSí. No hay otra opción... más que robar el arcón.', '', 28153),
(158506, 'esES', 'Bien jugado, Harlan. Bien jugado.', '', 28153),
(158505, 'esES', 'Estoy pensando en cien vueltas a la academia por cada cadete al que encuentre.', '', 28153),
(158504, 'esES', 'En algún lugar tienen que estar.', '', 28153),
(158503, 'esES', 'Nunca pedimos que nos trajeran de vuelta... ni tener que soportar esto.', 'Nunca pedimos que nos trajeran de vuelta... ni tener que soportar esto.', 28153),
(158502, 'esES', '¿Cuatro cerrojos? ¡¿Cuatro?!', '', 28153),
(158501, 'esES', '¿La Alianza se atreve a considerarnos monstruos a NOSOTROS?', '¿La Alianza se atreve a considerarnos monstruos a NOSOTROS?', 28153),
(158500, 'esES', '¿Dónde se han metido esos cadetes...?', '', 28153),
(158499, 'esES', 'Ah, aquí está: el arcón de Harlan Sweete.', '', 28153),
(158498, 'esES', 'Con todo lo que ha pasado, no es que la envidie. Pero tal vez sea hora de que entregue Kul Tiras a alguien más capacitado para gobernar.', 'Con todo lo que ha pasado, no es que la envidie. Pero tal vez sea hora de que entregue Kul Tiras a alguien más capacitado para gobernar.', 28153),
(158497, 'esES', 'Cada día que pasa parece más evidente que Katherine vive solo de lo que hizo su difunto marido.', 'Cada día que pasa parece más evidente que Katherine vive solo de lo que hizo su difunto marido.', 28153),
(158496, 'esES', 'Ha pasado otra semana y seguimos sin una reunión entre las casas.', 'Ha pasado otra semana y seguimos sin una reunión entre las casas.', 28153),
(158495, 'esES', 'Pues sí. Cualquier noble de Tiragarde que se precie habría tenido el buen juicio de no montar una historia tan triste que la víctima pudiera aprovechar.', 'Pues sí. Cualquier noble de Tiragarde que se precie habría tenido el buen juicio de no montar una historia tan triste que la víctima pudiera aprovechar.', 28153),
(158494, 'esES', 'Asesinado a plena luz del día, el día de su boda. Muy de aficionados.', 'Asesinado a plena luz del día, el día de su boda. Muy de aficionados.', 28153),
(158493, 'esES', '¿Lo de su prometido? Ya lo creo, qué pena.', '¿Lo de su prometido? Ya lo creo, qué pena.', 28153),
(158492, 'esES', '¿Has oído lo que le pasó a la hija de los Crestavía?', '¿Has oído lo que le pasó a la hija de los Crestavía?', 28153),
(158491, 'esES', 'Qué vergüenza. ¿Qué clase de Canto Tormenta no puede invocar el mar? Si yo fuera de esa familia, ya haría mucho que habría desheredado al chaval.', 'Qué vergüenza. ¿Qué clase de Canto Tormenta no puede invocar el mar? Si yo fuera de esa familia, ya haría mucho que habría desheredado al chaval.', 28153),
(158490, 'esES', '¿Así que su tío lo despachó para endilgárnoslo a nosotros?', '¿Así que su tío lo despachó para endilgárnoslo a nosotros?', 28153),
(158489, 'esES', 'Dicen que Brannon vuelve a trabajar aquí en el Estrecho.', 'Dicen que Brannon vuelve a trabajar aquí en el Estrecho.', 28153),
(158488, 'esES', 'Me alivia ver que Jaina se parece a su madre. No es que Daelin fuera lo que se dice atractivo.', 'Me alivia ver que Jaina se parece a su madre. No es que Daelin fuera lo que se dice atractivo.', 28153),
(158487, 'esES', '', '<En la espalda sigue alojada una daga, pero todas sus pertenencias han volado>.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'esES', '', '<Este cadáver Zandalari parece reciente>.', 28153),
(158485, 'esES', '<Examinar el cuerpo>.', '<Examinar el cuerpo>.', 28153),
(158484, 'esES', 'Hace tiempo que los Crestavía no visitan Boralus. Me pregunto si Meredith se ha dado cuenta al fin de lo poco que encaja aquí.', 'Hace tiempo que los Crestavía no visitan Boralus. Me pregunto si Meredith se ha dado cuenta al fin de lo poco que encaja aquí.', 28153),
(158483, 'esES', '¿Viste el atuendo de lord Canto Tormenta la última vez que estuvo aquí? Un gorro con tentáculos es un poco demodé, la verdad.', '¿Viste el atuendo de lord Canto Tormenta la última vez que estuvo aquí? Un gorro con tentáculos es un poco demodé, la verdad.', 28153),
(158482, 'esES', '<Simon mira a Kunga>.\n\nMmm, sí... ¡Ja! ¡Ja! ¡Mira que eres bromista!\n\n¡Ja! ¡Ja! ¡Qué gracioso!\n\nDeberías irte ya, antes de que encuentres otro. ¡Ja! ¡Ja!\n\nVe a ver la lucha mientras yo... repongo existencias.', '', 28153),
(158481, 'esES', 'He visto un cadáver detrás de la tienda.', 'He visto un cadáver detrás de la tienda.', 28153),
(158480, 'esES', 'Hola, mmm, sí.\n\n$gBienvenido:Bienvenida; a mi local, la tienda de... vender... cosas... de Simon.\n\nVendo...\n\n<Simon mira atrás un momento>.\n\nArmas. De todo tipo. Pero ahora no hay ninguna disponible.\n\n¿Qué tal si vuelves luego, cuando... tenga existencias?', '', 28153),
(158479, 'esES', '¡Acabaré contigo, escoria de la Horda!', '', 28153),
(158478, 'esES', '¡La Alianza no tiene derecho a reclamar nuestras tierras!', '¡La Alianza no tiene derecho a reclamar nuestras tierras!', 28153),
(158477, 'esES', 'Cualquier cosa es mejor que el pan de marcha.', '', 28153),
(158476, 'esES', 'Todos nuestros recursos están destinados a dar tiempo a nuestra gente a evacuar y mantener a la Horda a raya. Busca algo de comer para nuestros centinelas.', '', 28153),
(158475, 'esES', '', '¡Te enviaré al fondo del mar!', 28153),
(158474, 'esES', 'No eh precisamente mojo lo que tengo en el bolsillo...', '', 28153),
(158473, 'esES', '¡Ahora vah a probar tu propia medicina!', '', 28153),
(158472, 'esES', '¡No me obligueh a convertirte en sapo!', '', 28153),
(158471, 'esES', 'Lah manoh quietah. Ehtoy mayor, pero eso solo significa que conozco máh maleficioh.', '', 28153),
(158470, 'esES', 'Ya ehtá bien, ¿no? No me guhta que me soben.', '', 28153),
(158469, 'esES', 'Llevo generacioneh entrenando a loh trolh Lanza Negra.', '', 28153),
(158468, 'esES', 'Buena suerte, y que no te falte buen mojo.', '', 28153),
(158467, 'esES', '', 'Cualquier cosa es mejor que las raciones de marcha.', 28153),
(158466, 'esES', '', 'Un ejército no funciona con el estómago vacío, o eso tengo entendido. Debe de haber algo que se pueda comer en este bosque.', 28153),
(158465, 'esES', 'Recuerda: no todo se regenera.', '', 28153),
(158464, 'esES', '¡Cuidado!', '', 28153),
(158463, 'esES', '¡Casi tengo la muestra que necesito! Solo un poco más...', '', 28153),
(158462, 'esES', 'Vaya, estas hojas son más obstinadas de lo que esperaba. Pero creo que estoy avanzando.', '', 28153),
(158461, 'esES', 'Esto va a llevar tiempo. Arrancar las hojas es un proceso delicado.', '', 28153),
(158460, 'esES', 'Ehtoy viejo pa ehto.', '', 28153),
(158459, 'esES', 'Que loh ehpírituh te guíen.', '', 28153),
(158458, 'esES', 'Eekum bokum.', '', 28153),
(158457, 'esES', '¿Alguien ha llamado a un médico?', '', 28153),
(158456, 'esES', '¿Necesitah que te ayude?', '', 28153),
(158455, 'esES', 'Hola.', '', 28153),
(158454, 'esES', 'Ojalá los espíritus me guiaran.', 'Ojalá los espíritus me guiaran.', 28153),
(158453, 'esES', 'Los espíritus pueden guiarte aquí.', '', 28153),
(158452, 'esES', 'Una\'fe, $n. La avanzada está a tus órdenes.', '', 28153),
(158451, 'esES', '', 'Los has desarmado... de momento. Pero debemos mantenernos alerta hasta que cortemos sus suministros.', 28153),
(158450, 'esES', '', '¡Llénate a tope el estómago y descansa un poco!', 28153),
(158449, 'esES', 'El sello de esta cámara protege el alma del mundo, pero con toda esta azerita, el sello está a punto de romperse.', '', 28153),
(158448, 'esES', 'Utiliza tu amuleto para absorber la azerita. ¡Su poder debería reparar el sello de la cámara!', '', 28153),
(158447, 'esES', '', 'Se rumorea que las bandas se han hecho con explosivos de azerita. Nadie estará a salvo en Boralus hasta que recuperemos esas armas.', 28153),
(158446, 'esES', 'Mi barco se hundió y cientos de hombres cayeron al agua. En menos de una hora aquello estaba lleno de tiburones. Pequeños, grandes, furiosos. Los combatimos como pudimos. Cuando te mira de cerca un tiburón y ves esos ojos negros y sin vida, piensas que parecen muertos hasta que te muerden. Entonces el océano se tiñe de rojo, todo se oscurece y en cuestión de instantes un hombre queda hecho pedazos. Perdí como a la mitad de la tripulación tras la primera noche. Habría unos mil tiburones. Cuando al fin llegó el rescate, unos cinco días después, era tarde. Trescientos dieciséis hombres cayeron al mar y siete salieron de él. El resto fue pasto de los tiburones.\n\nPero basta de charla. ¿Quieres vértelas con los escualos?', '', 28153),
(158445, 'esES', 'Gracias. Me arriesgaré. Déjame las botas esas.', 'Gracias. Me arriesgaré. Déjame las botas esas.', 28153),
(158444, 'esES', '', '¡Ay! Estaba intentando mover unas cajas que... esto... se cayeron de un carro.\n\nAl menos Coda está bien. ¡Nada puede hacerle daño a mi increíble hombrecito!\n\nTengo otro par de botas por si tienes que saltar de vuelta al norte. Pero te aviso: aún no las he probado.', 28153),
(158443, 'esES', '', 'Es demasiado tarde.', 28153),
(158442, 'esES', '', 'Mira a ver si esa gente necesita ayuda. ¡Yo me adelanto!', 28153),
(158441, 'esES', '', '¡Pero primero hay que proteger esa puerta!', 28153),
(158440, 'esES', '', 'Oh, no...', 28153),
(158439, 'esES', '', 'Lo sabemos. Tú descansa. Tendrá su merecido.', 28153),
(158438, 'esES', 'Harlan... Ese canalla se ha vendido a los Gobernalle... ¡Aah! ¡Uh!', '', 28153),
(158437, 'esES', 'Ooh... Todo...', '', 28153),
(158436, 'esES', '', '¡Flynn! Tranquilo, ¡estás a salvo! ¿Te encuentras bien? ¿Qué te duele?', 28153),
(158435, 'esES', 'Ah... Ah... Oh, oh, oh, ¡oooooh!', '', 28153),
(158434, 'esES', '', 'Muy bien. Vamos, madre. Es hora de volver a casa.', 28153),
(158433, 'esES', '', '¡Agárrate bien!', 28153),
(158432, 'esES', 'Estoy listo para partir.', 'Estoy lista para partir.', 28153),
(158431, 'esES', '', 'Puedo teletransportarnos fuera de aquí cuando tú digas, $c.\n\nDate prisa, estoy deseando dejar este lugar.', 28153),
(158430, 'esES', '¡ESCENA INTERMEDIA!', '¡ESCENA INTERMEDIA!', 28153),
(158429, 'esES', 'Aunque los elfos de la noche son buenos vecinos, lleva un tiempo acostumbrarse a sus fuegos fatuos.', '', 28153),
(158428, 'esES', 'Utilizar la tierra y trabajarla. Ese era nuestro trato.', '', 28153),
(158427, 'esES', 'Es una pena lo que le ha pasado a su árbol.', '', 28153),
(158426, 'esES', '¡Si crees que puedes evitar que recuperemos el cuerpo de Derek, te equivocas!', '', 28153),
(158425, 'esES', 'Esta vez Loh solo tiene que llegar a la meta, pero cuidado con los peligros que acechan en el laberinto.', '', 28153),
(158424, 'esES', '¿Puedes guiar a Loh hasta los tesoros y luego hasta la meta, sin pasar dos veces por el mismo punto?', '', 28153),
(158423, 'esES', 'Fácil, ¿verdad?', '', 28153),
(158422, 'esES', 'Para empezar, algo fácil: guía a Loh hasta la meta.', '', 28153),
(158421, 'esES', 'Al contar estas historias, les decimos a los pequeños tortolianos que guíen a Loh a lo largo de una serie de laberintos y pruebas.', '', 28153),
(158420, 'esES', '¿Quieres empezar tu entrenamiento de combate?', '¿Quieres empezar tu entrenamiento de combate?', 28153),
(158419, 'esES', '¡Saboreemos las mieles del triunfo, $p!', '¡Saboreemos las mieles del triunfo, $p!', 28153),
(158418, 'esES', 'El éxito de Loh hizo que se confiara y buscara zonas cada vez más extraordinarias que explorar.', '', 28153),
(158416, 'esES', '¿Puedes guiar a Loh hasta todos los tesoros y después hasta la salida, sin pasar dos veces por el mismo punto?', '', 28153),
(158415, 'esES', 'Loh comenzó a explorar las ruinas antiguas que se encontraba y descubría en ellas tesoros fabulosos.', '', 28153),
(158414, 'esES', '\"Loh el Explorador\". A medida que Loh crecía, también aumentaba su curiosidad por el mundo.', '', 28153),
(158413, 'esES', 'El buen hacer de Loh dio sus frutos y la tierra le aportó muchas cosas nutritivas que comer.', '', 28153),
(158412, 'esES', '¿Puedes ayudar a Loh a visitar todas las plantas del jardín una sola vez?', '', 28153),
(158411, 'esES', 'Cada mañana miraba cómo estaban todas las plantas de su jardín.', '', 28153),
(158410, 'esES', '', 'Está claro que a los Drust no les interesa mantener con vida a sus prisioneros. ¡Debemos impedir que Jaina corra esa suerte!', 28153),
(158409, 'esES', '\"La cosecha de Loh\". A Loh le encantaba ver crecer las cosas.', '', 28153),
(158408, 'esES', 'Loh logró escapar a duras penas. Por eso decidió llevar una vida menos emocionante.', '', 28153),
(158407, 'esES', '¿Puedes ayudar a Loh a apagar todas las baldosas brillantes para desactivar la trampa?', '', 28153),
(158406, 'esES', '\"La curiosidad y el tortoliano\". ¡La curiosidad de Loh casi le jugó una mala pasada una vez que activó una antigua trampa Zandalari!', '', 28153),
(158405, 'esES', '', '¡Pide clemencia!', 28153),
(158404, 'esES', 'Loh no estaba hecho para la vida en la gran ciudad, así que se fue a vivir una vida más sencilla.', '', 28153),
(158403, 'esES', 'Se perdía todo el rato. ¿Puedes guiar a Loh hasta todas las tiendas y luego hasta la posada, sin pasar dos veces por el mismo punto?', '', 28153),
(158402, 'esES', '\"La vida en la gran ciudad\". Loh visitó una vez una gran ciudad, muy parecida a Boralus.', '', 28153),
(158401, 'esES', 'Loh se retiró para disfrutar de una vida tranquila... y de un estómago lleno.', '', 28153),
(158399, 'esES', '', 'He conseguido capturar a algunos elementales inferiores alrededor de estos altares, son fascinantes. ¿Quieres ver de lo que son capaces?', 28153),
(158398, 'esES', 'Los invitados se van... $pr fuerte...', '', 28153),
(158397, 'esES', 'Aún hambre...', '', 28153),
(158396, 'esES', '¿Dónde ir luz?', '', 28153),
(158395, 'esES', 'Adiós, Gallywix...', '', 28153),
(158394, 'esES', '¡No peleas!', '', 28153),
(158393, 'esES', '¡Primer día de trabajo! ¡Buena suerte!', '', 28153),
(158392, 'esES', '¡$pr no puede estar aquí!', '', 28153),
(158391, 'esES', '¡Fiesta privada!', '', 28153),
(158390, 'esES', 'Y aun así eres solo el segundo peor cliente... que he tenido hoy...', 'Y aun así eres solo el segundo peor cliente... que he tenido hoy...', 28153),
(158389, 'esES', 'Un goblin... con hielo...', 'Un goblin... con hielo...', 28153),
(158388, 'esES', 'Última llamada... para una Kaja\'Cola...', 'Última llamada... para una Kaja\'Cola...', 28153),
(158387, 'esES', 'Más te vale... dejar una buena propina...', 'Más te vale... dejar una buena propina...', 28153),
(158386, 'esES', 'Nunca aprendí... a jugar... al golf...', 'Nunca aprendí... a jugar... al golf...', 28153),
(158385, 'esES', 'No eres más que... un doble bogey...', 'No eres más que... un doble bogey...', 28153),
(158384, 'esES', 'No me enterréis con este uniforme... Es ridículo...', 'No me enterréis con este uniforme... Es ridículo...', 28153),
(158383, 'esES', 'No pienso cargar más con estos palos...', 'No pienso cargar más con estos palos...', 28153),
(158382, 'esES', 'El Gran G... te hará pagar por esto...', 'El Gran G... te hará pagar por esto...', 28153),
(158381, 'esES', 'Espera, nunca llegué... a la parte del placer...', 'Espera, nunca llegué... a la parte del placer...', 28153),
(158380, 'esES', 'Espera... aún no he acabado...', 'Espera... aún no he acabado...', 28153),
(158379, 'esES', 'Dile a Gallywix que siga... pagándome.', 'Dile a Gallywix que siga... pagándome.', 28153),
(158378, 'esES', 'Seguro que das unas propinas pésimas, so roñica.', 'Seguro que das unas propinas pésimas, so roñica.', 28153),
(158377, 'esES', '¡No te llevarás mi Kaja\'Cola!', '¡No te llevarás mi Kaja\'Cola!', 28153),
(158376, 'esES', 'Me voy a hacer un martini con tu bazo... ¡Un bazini!', 'Me voy a hacer un martini con tu bazo... ¡Un bazini!', 28153),
(158375, 'esES', 'Oigo ruidos...', 'Oigo ruidos...', 28153),
(158374, 'esES', '¡Esas bebidas las vas a pagar tú de tu bolsillo!', '¡Esas bebidas las vas a pagar tú de tu bolsillo!', 28153),
(158373, 'esES', '¿Qué tal un hoyo en uno... de tus huesos?', '¿Qué tal un hoyo en uno... de tus huesos?', 28153),
(158372, 'esES', '<El doctor se dirige a ti entre susurros>.$b$bEstán muy graves. En su estado, no podemos moverlos. Lo máximo que puedo hacer es curarlos un poco e intentar llegar a un lugar seguro.$b$bAhí arriba la cosa es de locos.', 'n/a', 28153),
(158371, 'esES', 'Cualquier cosa es mejor que mirar todo el día cómo estos cretinos fallan los golpes.', 'Cualquier cosa es mejor que mirar todo el día cómo estos cretinos fallan los golpes.', 28153),
(158370, 'esES', '¡En esta situación, recomiendo un hierro nueve en toda la cara!', '¡En esta situación, recomiendo un hierro nueve en toda la cara!', 28153),
(158369, 'esES', '¡Por fin me toca golpear algo!', '¡Por fin me toca golpear algo!', 28153),
(158368, 'esES', '¡Ja! ¡Te he engañado! ¡Desde el principio he sido un agente de seguridad encubierto!', '¡Ja! ¡Te he engañado! ¡Desde el principio he sido una agente de seguridad encubierta!', 28153),
(158367, 'esES', 'No te preocupes. Yo me encargo.', 'No te preocupes. Yo me encargo.', 28153),
(158366, 'esES', '¡Aléjate de los invitados!', '¡Aléjate de los invitados!', 28153),
(158365, 'esES', 'No cobro lo suficiente por esto.', 'No cobro lo suficiente por esto.', 28153),
(158364, 'esES', 'Necesito hacer... una última... barbacoa...', 'Necesito hacer... una última... barbacoa...', 28153),
(158363, 'esES', 'Dejadme en el sol... y dadme la vuelta antes de que me queme...', 'Dejadme en el sol... y dadme la vuelta antes de que me queme...', 28153),
(158362, 'esES', '¡Ja! Y dijeron... que me mataría el sol...', '¡Ja! Y dijeron... que me mataría el sol...', 28153),
(158361, 'esES', 'No, mi precioso cuerpo bronceado...', 'No, mi precioso cuerpo bronceado...', 28153),
(158360, 'esES', 'Tengo unas palabritas que decirle a... Gallywix sobre esto...', 'Tengo unas palabritas que decirle a... Gallywix sobre esto...', 28153),
(158359, 'esES', 'Yo solo quería salir de fiesta...', 'Yo solo quería salir de fiesta...', 28153),
(158358, 'esES', 'Esto no es un palacio... ni es de placer...', 'Esto no es un palacio... ni es de placer...', 28153),
(158357, 'esES', 'Pero si soy... muy importante...', 'Pero si soy... muy importante...', 28153),
(158356, 'esES', 'Caddie, llévame... al hoyo.', 'Caddie, llévame... al hoyo.', 28153),
(158355, 'esES', 'Al menos he muerto... bajo par.', 'Al menos he muerto... bajo par.', 28153),
(158354, 'esES', 'Enterradme... en la arena.', 'Enterradme... en la arena.', 28153),
(158353, 'esES', 'Diles... que estaba bajo par.', 'Diles... que estaba bajo par.', 28153),
(158352, 'esES', 'La mejor fiesta... de mi vida.', 'La mejor fiesta... de mi vida.', 28153),
(158351, 'esES', 'La peor fiesta... de mi vida.', 'La peor fiesta... de mi vida.', 28153),
(158350, 'esES', 'Quiero... un reembolso.', 'Quiero... un reembolso.', 28153),
(158349, 'esES', 'Solo... un trago... más...', 'Solo... un trago... más...', 28153),
(158348, 'esES', 'Estamos hasta arriba. ¡Ve a nadar a otro sitio!', 'Estamos hasta arriba. ¡Ve a nadar a otro sitio!', 28153),
(158347, 'esES', '¡En esta piscina no puede entrar ningún $pr!', '¡En esta piscina no puede entrar ningún $pr!', 28153),
(158346, 'esES', '¿Has visto mi zambullida de antes? ¡10 de 10, sí señor!', '¿Has visto mi zambullida de antes? ¡10 de 10, sí señor!', 28153),
(158345, 'esES', 'Oye, $pr. ¡Me tapas el sol con esa jeta tan grande!', 'Oye, $pr. ¡Me tapas el sol con esa jeta tan grande!', 28153),
(158344, 'esES', 'Hay que ver, cada fin de semana la seguridad de Gallywix es peor.', 'Hay que ver, cada fin de semana la seguridad de Gallywix es peor.', 28153),
(158343, 'esES', '¡No he pagado el extra para que me ataque $gun:una; $pr tan $gfeo:fea;!', '¡No he pagado el extra para que me ataque $gun:una; $pr tan $gfeo:fea;!', 28153),
(158342, 'esES', 'Largo, $p. Ve a molestar a la chusma que hay junto a la piscina.', 'Largo, $p. Ve a molestar a la chusma que hay junto a la piscina.', 28153),
(158341, 'esES', 'Sujétame la Kaja\'Cola. Yo me ocupo.', 'Sujétame la Kaja\'Cola. Yo me ocupo.', 28153),
(158340, 'esES', '¡No pises el green! Vas a estropear la hierba con los zapatos.', '¡No pises el green! Vas a estropear la hierba con los zapatos.', 28153),
(158339, 'esES', '¡Caddie, llama a mi chófer! Esta llegará lejos.', '¡Caddie, llama a mi chófer! Esta llegará lejos.', 28153),
(158338, 'esES', '¡Voy a hacer el siguiente hoyo en uno con tu ojo!', '¡Voy a hacer el siguiente hoyo en uno con tu ojo!', 28153),
(158337, 'esES', '¡Hay una distracción en el campo! ¡Tengo que repetirlo!', '¡Hay una distracción en el campo! ¡Tengo que repetirlo!', 28153),
(158336, 'esES', 'Largo, $pr. ¡Estamos ocupados bebiendo y comiendo y bebiendo otra vez!', 'Largo, $pr. ¡Estamos ocupados bebiendo y comiendo y bebiendo otra vez!', 28153),
(158335, 'esES', 'No me importaría un poco de emoción extra.', 'No me importaría un poco de emoción extra.', 28153),
(158334, 'esES', '¡Seguridad! ¡Llevaos a $geste:esta; $pr!', '¡Seguridad! ¡Llevaos a $geste:esta; $pr!', 28153),
(158333, 'esES', '¡No compré el paquete de peleles de la Alianza!', '¡No compré el paquete de peleles de la Alianza!', 28153),
(158332, 'esES', 'Ay...', '', 28153),
(158331, 'esES', 'Goblins... ¡correr!', '', 28153),
(158330, 'esES', 'Solo quería... brillante...', '', 28153),
(158329, 'esES', 'Hice lo que pude...', '', 28153),
(158328, 'esES', 'Di Gran G... que yo sentir...', '', 28153),
(158327, 'esES', 'Seguir trabajo...', '', 28153),
(158326, 'esES', 'Yo sueño...', '', 28153),
(158325, 'esES', 'No parar... el oro.', '', 28153),
(158324, 'esES', '¡No tocar!', '', 28153),
(158323, 'esES', '¡Nuestro oro brillante!', '', 28153),
(158322, 'esES', 'Gran G dice que aplastar a $pr.', '', 28153),
(158321, 'esES', '¡No acercarte a goblins!', '', 28153),
(158320, 'esES', '¡Dar oro!', '', 28153),
(158319, 'esES', '¡Gallawick el mejor!', '', 28153),
(158318, 'esES', '¡No parar de trabajar!', '', 28153),
(158317, 'esES', '¡Sin retrasos!', '', 28153),
(158316, 'esES', 'Temblarán ante el Vacío.', 'Temblarán ante el Vacío.', 28153),
(158315, 'esES', 'Puedo verlos a través del velo. Sígueme.', 'Puedo verlos a través del velo. Sígueme.', 28153),
(158314, 'esES', 'Venid, pequeños goblins...', 'Venid, pequeños goblins...', 28153),
(158313, 'esES', '', 'Nuestras tropas están en Ar\'gorok. Reúne a tus aliados y conquistad Stromgarde. ¡Por la Horda!', 28153),
(158312, 'esES', '<Salir y participar en el asalto de Lordaeron>', '<Salir y participar en el asalto de Lordaeron>', 28153),
(158311, 'esES', 'Las sorpresas proseguirán hasta que mejore el ánimo.', '', 28153),
(158310, 'esES', 'Esta será una historia desternillante que contarle a tus amigos.', '', 28153),
(158309, 'esES', 'Preparad vuestras cámaras. En 3... 2... 1...', '', 28153),
(158308, 'esES', 'Iniciando diversión.', '', 28153),
(158307, 'esES', 'Solicitud de sorpresa recibida. Procediendo sin contemplaciones.', '', 28153),
(158306, 'esES', 'Los niveles máximos de diversión deben superarse.', '', 28153),
(158305, 'esES', 'No se tolerará a los invitados aburridos.', '', 28153),
(158304, 'esES', 'Falta de diversión detectada. Corrigiendo.', '', 28153),
(158303, 'esES', '', '... Te lo diré cuando acabe la guerra.', 28153),
(158302, 'esES', 'Déjalo.', 'Déjalo.', 28153),
(158301, 'esES', 'Sí.', 'Sí.', 28153),
(158300, 'esES', '', '¿Estamos a tiro de piedra de un importante punto de reunión de la Horda y quieres saber por qué llevo una botella que puede volverte invisible?', 28153),
(158299, 'esES', '¿Por qué tienes un frasco de invisibilidad?', '¿Por qué tienes un frasco de invisibilidad?', 28153),
(158298, 'esES', 'Ssssh, vete de aquí. ¡Vas a hacer que me descubran!', '', 28153),
(158297, 'esES', 'Llévame al buque insignia.', 'Llévame al buque insignia.', 28153),
(158296, 'esES', '¡Si necesitas que te lleven a esos barcos, yo soy tu hombre!', '', 28153),
(158295, 'esES', '¡Ese gran árbol andante es algo digno de ver!', '', 28153),
(158294, 'esES', '¡Pagar por poner nervioso a Vog\'rish!', '', 28153),
(158293, 'esES', '¡Eso nunca pasar antes a Vog\'rish!', '', 28153),
(158292, 'esES', '¡Aaaaah! ¡Vog\'rish avergonzado!', '', 28153),
(158291, 'esES', 'Los elfos son muy buenos cultivando.', '', 28153),
(158290, 'esES', '¡Yo enseñarte verdadero poder de Vog\'rish!', '', 28153),
(158289, 'esES', '¡Preparar para infierno, debiluchos!', '', 28153),
(158288, 'esES', '¡Ya no más ogro bueno!', '', 28153),
(158287, 'esES', 'Está bien conseguir algo más de ayuda.', '', 28153),
(158286, 'esES', '', 'Shandris... tienes... que sobrevivir...', 28153),
(158285, 'esES', '', 'Por... mi... pueblo...', 28153),
(158284, 'esES', '¡Vog\'rish quemarte los pies!', '', 28153),
(158283, 'esES', '¡La magia de Vog\'rish estar fuera de control!', '', 28153),
(158282, 'esES', '', '¡Únete a mí en la muerte!', 28153),
(158281, 'esES', '¡Contemplar increíble poder!', '', 28153),
(158280, 'esES', 'Ah, justo a tiempo.', '', 28153),
(158279, 'esES', '', 'Parece que no tendremos que esperar mucho más, Nathanos.', 28153),
(158278, 'esES', '', '¡Cómo brillan! ¡Diré que esta grande la han bendecido los Sabiomar y que esta con una espiral viene del tesoro de un pirata!', 28153),
(158277, 'esES', '', 'Menos fuegos fatuos en su muro para atacar a nuestros soldados. Bien hecho.', 28153),
(158276, 'esES', '', 'Hay que despejar esta zona para que nuestras tropas puedan pasar sin peligro. No subestimes a los fuegos fatuos, en bandada son letales.', 28153),
(158275, 'esES', '', 'No te creerías las cosas raras que puedes atrapar pescando aquí abajo. He atrapado algunas criaturas exóticas estos últimos días, ¿quieres un combate?', 28153),
(158274, 'esES', 'Lilian no deja de decirme que la Horda es mi familia.\n\nAhora que la verdadera no me acepta... La verdad es que me vendría bien el apoyo.\n\nPero, a cambio, Lilian ha prometido que mantendrán a salvo a mi familia. ¿Y si es algo que puedo conseguir ayudando a la Horda?\n\nPues entonces es lo que haré.', '', 28153),
(158273, 'esES', '', '¡Salgamoh de aquí!', 28153),
(158272, 'esES', '', '¡Se venden conchas! Las más bonitas de todo Kul Tiras. ¡Ah, no, de Azeroth! ¡Las más bonitas de todo Azeroth!', 28153),
(158271, 'esES', '', 'Ahora tengo algo más de lucidez, $n.\n\nCon la ayuda de Lilian, quizás pueda llegar a aceptar este nuevo destino.\n\nAunque debo decir... que cuanto más lejos esté de Kul Tiras... mejor.', 28153),
(158270, 'esES', 'Agradezco esta oportunidad de demostrar la valía de los ren\'dorei para nuestra causa.\n\n¡Haremos lo que haga falta para garantizar el éxito de la Alianza!', '', 28153),
(158269, 'esES', '', 'Hasta ahora, el alto comandante Aterravermis me ha impresionado mucho.\n\nEmplea una gran variedad de tácticas y se adapta sin demora a los cambios en las circunstancias con estrategias apropiadas y necesarias.\n\nLas campañas de la Alianza están en buenas manos. Como tú, cumplo mi papel en ellas con orgullo.', 28153),
(158268, 'esES', '', 'Hay que erradicar a los San\'layn. La temeridad de la Horda nos pone en peligro a todos.', 28153),
(158267, 'esES', 'Tú ver pronto. ¡Fuego! ¡Sí, fuego grande!', '', 28153),
(158266, 'esES', 'Te volveré a llamar cuando te necesite. Por la Alianza.', '', 28153),
(158265, 'esES', 'Hay que informar enseguida al rey Anduin. Hemos cumplido nuestro cometido aquí, pero nuestra misión solo acaba de empezar.', '', 28153),
(158264, 'esES', '¿En serio está la Horda empleando a estos elfos vampiros? Qué bajo han caído.', '', 28153),
(158263, 'esES', '¡Mucho humo y muchas nueces!', '', 28153),
(158262, 'esES', 'Lo que describes parece uno de los San\'layn... un príncipe de sangre.', '', 28153),
(158261, 'esES', '', '¿G... Guzzy está muerto?', 28153),
(158260, 'esES', 'Donde haber humo, haber fuego... ¡Fiar de mí!', '', 28153),
(158259, 'esES', 'Es hora de pasar a la siguiente fase de nuestro plan.', '', 28153),
(158258, 'esES', 'Tenemos el cuerpo de Derek Valiente. No necesitamos resucitar más cadáveres de Kul Tiras. Por ahora.', '', 28153),
(158257, 'esES', 'Esperemos que tus esfuerzos no fueran en vano.', '', 28153),
(158256, 'esES', 'La guerra ha llegado a Costa Oscura y debemos proteger a nuestra gente lo mejor que podamos. Dirige a los fuegos fatuos que encuentres hacia el frente y elimina cualquier amenaza.', '', 28153),
(158255, 'esES', '', '¡Ja! ¡He oído el grito de un traidor atrapado!', 28153),
(158254, 'esES', '', 'Un rehpiro pa loh fatigadoh y comida pa loh hambrientoh.', 28153),
(158253, 'esES', '', 'No accedí a atraer la flota de Kul Tiras a mi puerto.\n\nMás te vale tener un plan adecuado. Me niego a perder mi libertad.', 28153),
(158252, 'esES', 'Comienza el ritual.', 'Comienza el ritual.', 28153),
(158251, 'esES', '¿De dónde vienes?', '¿De dónde vienes?', 28153),
(158250, 'esES', '¿Cuánto tiempo llevas aquí?', '¿Cuánto tiempo llevas aquí?', 28153),
(158249, 'esES', 'Este es el único hogar que he conocido.\n\nLas arenas guían nuestros pasos.', 'Este es el único hogar que he conocido.\n\nLas arenas guían nuestros pasos.', 28153),
(158248, 'esES', 'Estas arenas han sido el hogar de mi caravana desde antes de que yo naciera.\n\nHay otras al otro lado del mar, pero nunca las he visto con mis propios ojos.', 'Estas arenas han sido el hogar de mi caravana desde antes de que yo naciera.\n\nHay otras al otro lado del mar, pero nunca las he visto con mis propios ojos.', 28153),
(158247, 'esES', 'Tonterías. Tu gente y tú habéis cumplido vuestro papel de forma admirable, Magister. Honráis a la Alianza.', '', 28153),
(158246, 'esES', 'En nombre de todos los elfos del Vacío, me disculpo por nuestro fracaso.', '', 28153),
(158245, 'esES', '', 'Debemos llegar a Alto del Vigía. Rápido, ¡sube!', 28153),
(158244, 'esES', 'Kua\'fon gorjea con satisfacción y se enrosca para dormir.', '', 28153),
(158243, 'esES', 'El lugareño gruñe de dolor.', 'La lugareña gruñe de dolor.', 28153),
(158242, 'esES', '¡Mok\'rah, $n! La avanzada está a tus órdenes.', '', 28153),
(158241, 'esES', '', 'Mmm.', 28153),
(158240, 'esES', 'Te pagaremos generosamente por las molestias.', '', 28153),
(158239, 'esES', '', 'Nathanos, te dije que tu Horda podía utilizar mi puerto como base. ¡Pero no te di permiso para llevar a la flota de los Valiente hasta mis mismas puertas!', 28153),
(158238, 'esES', 'El cetro es un artefacto con un inmenso poder sobre el mar. Podremos usarlo para obtener ventaja frente a la flota de Kul Tiras.', '', 28153),
(158237, 'esES', '', '¿Cómo vas a colarte? Uno no entra así como así en Boralus...', 28153),
(158236, 'esES', 'Envié a Valentine a Boralus para hacerle llegar un mensaje a lady Valiente, costara lo que costara. Tenemos a su hijo.', '', 28153),
(158235, 'esES', 'Tranquilidad, amigos míos. Os aseguro que este pirata pagará por sus crímenes. No obstante, debemos esperar a que los tribunales dicten su sentencia final.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'esES', 'Nuestra misión aquí es hacernos con el cetro abisal, que está en el corazón del Monasterio Canto Tormenta, en Boralus.', '', 28153),
(158233, 'esES', '', 'Entra, $n. Nathanos te pondrá al día.', 28153),
(158232, 'esES', 'Los tribunales te declaran culpable de un delito de usura. Tus préstamos abusivos han arrebatado sus ahorros a muchas buenas personas de Puntagarfio. Muchas ahora viven en la calle por tus fechorías.', '', 28153),
(158231, 'esES', 'Los tribunales te declaran culpable de los delitos de piratería, robo y asesinato. La piratería es el peor de los crímenes según la ley de Kul Tiras y deberás someterte a la justicia.', '', 28153),
(158230, 'esES', '¡Extorsión y fraude! Muchas de las familias que hay hoy aquí han sido víctimas de tus engaños. Has cobrado un precio demasiado alto al pueblo de Kul Tiras y ahora serás tú quien pagará.', '', 28153),
(158229, 'esES', 'Sígueme. Nos llevaré directamente hasta Alleria y el Alto comandante.', '', 28153),
(158228, 'esES', 'No es la victoria total que esperaba conseguir para la Alianza, pero la tardanza no será otro de mis fallos aquí.', '', 28153),
(158227, 'esES', '¿Hemos estado persiguiendo a un señuelo todo el tiempo? Los goblins son lo peor.', '', 28153),
(158226, 'esES', '¡Hasta luego, desgraciados!', '', 28153),
(158225, 'esES', 'Los trajes mecánicos no son baratos, $p. ¡Voy a mandarte la factura de ese!', '', 28153),
(158224, 'esES', '¡Os ha engañado el truco más viejo de Pantoque: trabajadores cualificados y mal pagados!', '', 28153),
(158223, 'esES', '¡Ja! Ojalá pudierais veros las caras ahora mismo.', '', 28153),
(158222, 'esES', '', 'La idea de que cualquier ehpíritu pudiera eludir a Bwonsamdi eh impresionante. Mi ehperanza eh que loh vínculoh de suh amigoh bahten pa darnoh una conexión con él en el otro lado.', 28153),
(158221, 'esES', '$n, hay un telescopio en el lado oeste del campamento. ¿Por qué no vas y echas un vistazo, por si lo ves?', '', 28153),
(158220, 'esES', 'Mmm... Sí, ¿dónde está Guzbert? Debería aparecer por esa esquina de un momento a otro.', '', 28153),
(158219, 'esES', '', '¿Soy la primera en volver? ¿Dónde está Guzzy?', 28153),
(158218, 'esES', 'Bienvenida de nuevo, señorita Chispacero.', '', 28153),
(158217, 'esES', '', '¡Oye, jefe! ¿Has oído ese estruendo? Creo que puedo haber puesto en órbita a algún goblin.', 28153),
(158216, 'esES', 'Guzbert y Kelsey deberían llegar en cualquier momento.', '', 28153),
(158215, 'esES', 'Je. ¿Qué ha hecho el mundo por mí?', '', 28153),
(158214, 'esES', 'Tienes el ego tan inflado como el cuerpo. ¡Piensa en todo el bien que podrías haber hecho por este mundo!', '', 28153),
(158213, 'esES', 'Con toda la riqueza que has acumulado, ¿esto es lo que construyes, Gallywix? ¡Un antro de depravación!', '', 28153),
(158212, 'esES', '', 'Usa Vivificar para recuperar toda tu salud.', 28153),
(158211, 'esES', 'Usa Vivificar para recuperar toda tu salud.', '', 28153),
(158210, 'esES', '', 'Recibir daño es inevitable, pero puedes usar brumas espirituales para sanarte o sanar a un aliado. Usa Vivificar.', 28153),
(158209, 'esES', 'Recibir daño es inevitable, pero puedes usar brumas espirituales para sanarte o sanar a un aliado. Usa Vivificar.', '', 28153),
(158208, 'esES', '¡La Alianza ha sido derrotada!', '', 28153),
(158207, 'esES', '|A:Warfront-HordeWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Horda!', '|A:Warfront-HordeWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Horda!', 28153),
(158206, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido la Senda del Valor!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido la Senda del Valor!', 28153),
(158205, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Finca Nueva!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Finca Nueva!', 28153),
(158204, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de los Elementos!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de los Elementos!', 28153),
(158203, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Nido Alto!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Nido Alto!', 28153),
(158202, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Cruce Redilnorte!', 28153),
(158201, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Hemos perdido la Mina de Galson!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Hemos perdido la Mina de Galson!', 28153),
(158200, 'esES', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido el Aserradero de las Tierras Altas!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido el Aserradero de las Tierras Altas!', 28153),
(158199, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Están atacando la Mina de Galson!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Están atacando la Mina de Galson!', 28153),
(158198, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Están atacando el Aserradero de las Tierras Altas!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Están atacando el Aserradero de las Tierras Altas!', 28153),
(158197, 'esES', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', 28153),
(158196, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando la Senda del Valor!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando la Senda del Valor!', 28153),
(158195, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Finca Nueva!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Finca Nueva!', 28153),
(158194, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de los Elementos!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de los Elementos!', 28153),
(158193, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Cruce Redilnorte!', 28153),
(158192, 'esES', 'Que pulse el gran botón rojo cuando me lo digas. Vale.', 'Que pulse el gran botón rojo cuando me lo digas. Vale.', 28153),
(158191, 'esES', 'Muéstrame adónde puedo ir volando.', 'Muéstrame adónde puedo ir volando.', 28153),
(158190, 'esES', '¿Quieres volar a algún sitio?', '', 28153),
(158189, 'esES', '¡De nuevo superan mi puja! ¿Por qué hay gente que busca hacerse rica a costa del sufrimiento ajeno?', '¡De nuevo superan mi puja! ¿Por qué hay gente que busca hacerse rica a costa del sufrimiento ajeno?', 28153),
(158188, 'esES', 'No nos queda nada de valor que vender.', 'No nos queda nada de valor que vender.', 28153),
(158187, 'esES', 'Espero que nos quede lo bastante para comprar los suministros que necesitamos.', 'Espero que nos quede lo bastante para comprar los suministros que necesitamos.', 28153),
(158186, 'esES', '¿Cuánto oro nos queda?', '¿Cuánto oro nos queda?', 28153),
(158185, 'esES', 'No hay bastantes raciones...', 'No hay bastantes raciones...', 28153),
(158183, 'esES', 'Cuidado en el camino, $gviajero:viajera;. Algo extraño acecha en las sombras de Drustvar.', 'Cuidado en el camino, $gviajero:viajera;. Algo extraño acecha en las sombras de Drustvar.', 28153),
(158182, 'esES', 'Oye... ¡Oye! ¡El traje está fallando!', '', 28153),
(158181, 'esES', '¡Los cuervos vigilan! ¡La risa no para! ¡Vendrán a por mí!', '', 28153),
(158180, 'esES', '', 'Has hecho... que se me caiga... la bebida...', 28153),
(158179, 'esES', '', '¿Te crees que a MÍ me vas a engañar, eh? ¡Te <hip> voy a atravesar!', 28153),
(158178, 'esES', '', 'Buen trabajo. Nos vemos en el otro lado del campamento.', 28153),
(158177, 'esES', '¡Mira esto, Gallywix!', '¡Mira esto, Gallywix!', 28153),
(158176, 'esES', '¿La Alianza? ¿Aquí, en Zandalar?', '', 28153),
(158175, 'esES', 'Nos movemos con las arenas.', 'Nos movemos con las arenas.', 28153),
(158174, 'esES', 'Las dunas están llenas de tesoros que esperan a ser encontrados.', 'Las dunas están llenas de tesoros que esperan a ser encontrados.', 28153),
(158173, 'esES', 'El carro es nuestro hogar.', 'El carro es nuestro hogar.', 28153),
(158171, 'esES', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t ¡%s te escoge como objetivo de la |cFFFF0000|Hspell:271296|h[Maza de sangre]|h|r!', '', 28153),
(158170, 'esES', '', 'Pobres almas... Nadie debería sufrir así. Cuando salvemos a Jaina, tenemos que encontrar el modo de volver a por ellas.', 28153),
(158169, 'esES', 'Algo es seguro, Drustvar ha enloquecido.', 'Algo es seguro, Drustvar ha enloquecido.', 28153),
(158168, 'esES', 'He oído a uno de ellos decir algo de ciervos que comen carne humana.', 'He oído a uno de ellos decir algo de ciervos que comen carne humana.', 28153),
(158167, 'esES', '¿Lo de los hombres bestia y los demonios de madera? Sí, los he oído hablar de eso.', '¿Lo de los hombres bestia y los demonios de madera? Sí, los he oído hablar de eso.', 28153),
(158166, 'esES', '¿Has oído lo que decían? ¿Por qué están aquí esos refugiados?', '¿Has oído lo que decían? ¿Por qué están aquí esos refugiados?', 28153),
(158165, 'esES', 'Hay días que pienso que puedo comunicarme con mis abejas a base de zumbar con la boca, pero probablemente no funcionará hasta que acabe mi disfraz de abeja de tamaño natural. Pero eso da igual, lo que importa es que mis abejas son las mejores de la zona. ¿Quieres luchar contra ellas o vas a irte con el aguijón entre las piernas?', '', 28153),
(158164, 'esES', '', 'Que nuestra voluntad sea más fuerte que sus máquinas de guerra.', 28153),
(158163, 'esES', 'Los kaldorei no olvidarán tus hazañas, adalid. La ayuda que nos prestas en estos tiempos oscuros podría ser la clave de la victoria.', '', 28153),
(158162, 'esES', 'Nos enfrentamos a una dura prueba, pero no desesperaremos. La diosa nos otorga fuerza, y debemos aferrarnos a ella.', '', 28153),
(158161, 'esES', 'Una guerra no se decide en una sola batalla. Nuestro momento llegará.', '', 28153),
(158160, 'esES', 'El rey Anduin enviará a sus soldados para ayudarnos. Debemos resistir hasta entonces.', '', 28153),
(158159, 'esES', 'Nuestra flota ha regresado de Silithus, ¡bendita sea Elune! Necesitamos su poderío.', '', 28153),
(158158, 'esES', 'A pesar de que el muro de fuegos fatuos aún resiste, la Horda se está abriendo camino hasta la Costa Oscura.', '', 28153),
(158157, 'esES', 'Eso los habrá desmoralizado. Nunca subestimes el poder de la guerra psicológica.', '', 28153),
(158156, 'esES', 'Son palabras duras las que le has dicho a Nathanos.', 'Son palabras duras las que le has dicho a Nathanos.', 28153),
(158155, 'esES', 'Los piratas de Fuerte Libre son cada vez más osados. Debemos sembrar el caos entre ellos. Usa una de sus propias monturas para que les llueva porquería encima.', '', 28153),
(158154, 'esES', '', 'Todoh loh marineroh temen la llamada de lah sirenah, pero algunoh no lo suficiente.', 28153),
(158153, 'esES', '', 'Lah sirenah han atrapado a otro barco de suminihtroh de Kul Tirah. Buhca cosah útileh entre loh ehcombroh... ¡pero intenta no acabar como su tripulación!', 28153),
(158152, 'esES', 'Os espera un destino mucho peor que la muerte...', '', 28153),
(158151, 'esES', '¿Creéis que habéis ganado? ¡Mi caída no es más que el comienzo de vuestro final!', '', 28153),
(158150, 'esES', 'Bien hecho. Has dejado al enemigo sin buenas armas con las que atacarnos.', '', 28153),
(158149, 'esES', 'No podemos dejar que la gente de Kul Tiras siga produciendo munición de azerita. ¡Detén el trabajo en esa fundición!', '', 28153),
(158148, 'esES', '', 'Cuando un fanático duda de tu lealtad, tienes los días contados.\n\nA mí me reclutaron para esta campaña y quizás a ti también. Hemos de hacer y decir lo que haga falta para sobrevivir a ella.\n\nPero debes saber que solo hay una guerra que importa. Y no es esta.', 28153),
(158147, 'esES', 'Compartiréis... su destino.', '', 28153),
(158146, 'esES', 'Es... demasiado tarde... para salvarla...', '', 28153),
(158145, 'esES', 'Nadie se salvará del tormento...', '', 28153),
(158144, 'esES', 'Ya está... condenada...', '', 28153),
(158143, 'esES', '¡La venganza está cerca!', '', 28153),
(158142, 'esES', '¡Valiente es nuestra!', '', 28153),
(158141, 'esES', '¡Lo consumiremos todo!', '', 28153),
(158140, 'esES', '¡Os uniréis a su sufrimiento!', '', 28153),
(158139, 'esES', '', 'Llevo trabajando en esta zona lo bastante como para encontrar algunas manifestaciones interesantes de esta azerita. ¿Quieres probar suerte contra unos elementales de azerita salvajes que he reunido en secreto?', 28153),
(158138, 'esES', '¡INSENSATOS! ¡No podéis comprender los poderes a los que os enfrentáis!', '', 28153),
(158137, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Nido Alto!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Nido Alto!', 28153),
(158136, 'esES', '', 'No exactamente. Cuando veo una oportunidad, la aprovecho.\n\nSiempre he tenido planes de futuro. Ya va siendo hora de que me ponga manos a la obra para hacerlos realidad.', 28153),
(158135, 'esES', 'Pensaba que servías a los Descoronados. ¿Has cambiado de bando?', 'Pensaba que servías a los Descoronados. ¿Has cambiado de bando?', 28153),
(158134, 'esES', '¡Soy LIBRE! Os lo agradezco... ¡y ahora vuestras almas saciarán mi hambre insondable!', '', 28153),
(158133, 'esES', 'Tú eliges por qué región comenzar. Partiremos en cuanto tomes la decisión.', '', 28153),
(158132, 'esES', '', 'Buen trabajo. Los guardias se encargarán de los que quedan. A partir de ahora debemos vigilar mejor la mansión.', 28153),
(158131, 'esES', '', '¡Unos monstruos están saliendo de la Mansión Crestavía y se dirigen a Puesto de Arom! ¡Hay que detenerlos!', 28153),
(158129, 'esES', 'Ganaremos esta guerra. ¡Por la Alianza!', '', 28153),
(158128, 'esES', 'Busca objetivos en las tierras de los trols e interfiere cuanto puedas en los planes de la Jefa de Guerra.', '', 28153),
(158127, 'esES', 'Las posiciones que aseguraste en Zandalar fueron un primer paso audaz. ¡Ahora las usaremos para llevar la batalla a la Horda!', '', 28153),
(158126, 'esES', 'Pero las mareas de la guerra cambian sin cesar. Y es hora de que modifiquemos también nuestra campaña.', '', 28153),
(158125, 'esES', 'Nunca he tenido tanta hambre...', 'Nunca he tenido tanta hambre...', 28153),
(158124, 'esES', 'Tu actuación en Kul Tiras ha sido de vital importancia para nuestra causa. Tan solo la unidad fortalece a la Alianza.', '', 28153),
(158123, 'esES', '¡Por la Alianza!', '', 28153),
(158122, 'esES', 'Pero, por ahora, ten claro que sirves de inspiración a aquellos que te rodean. Te doy las gracias por ello, adalid.', '', 28153),
(158121, 'esES', 'La Alianza te sigue necesitando. Está claro que no podremos acabar con el reinado de la Jefa de Guerra hasta que rompamos sus lazos con los Zandalari. Y ese día... llegará pronto.', '', 28153),
(158120, 'esES', 'Ojalá pudiera decir que nuestro trabajo ha acabado, pero queda mucho por hacer. Los días serán cada vez más oscuros... antes de que vuelva a brillar la luz.', '', 28153),
(158119, 'esES', 'Adalid, has encabezado una larga campaña contra un enemigo implacable. Además, te has enfrentado a la Horda con coraje... y con honor.', '', 28153),
(158118, 'esES', '', '¡Por la Horda!', 28153),
(158117, 'esES', '', 'Representas lo mejor de la Horda, adalid. Sé que te convertirás en la chispa que prenderá fuego a Boralus.', 28153),
(158116, 'esES', '', 'Kul Tiras es un punto clave para las tropas de la Alianza. El regreso de su famosa flota los ha envalentonado, pero pronto esos perros de agua salada pagarán por habernos desafiado.', 28153),
(158115, 'esES', '', 'Aunque la victoria nos rehuye, está cada vez más cerca. No descansaré hasta que el último ápice de esperanza del niño rey quede reducido a cenizas.', 28153),
(158114, 'esES', '', 'El mundo está repleto de soldados, adalid, pero muy pocos están preparados para la guerra. Tú, en cambio, pareces disfrutarla.', 28153),
(158113, 'esES', '', 'Arrebátales la esperanza y la victoria será nuestra. ¡Por la Horda!', 28153),
(158112, 'esES', '', 'Aprovecha las posiciones que has establecido en Kul Tiras para diezmar las tropas del niño rey. Haz que pierdan la fe en su causa inútil.', 28153),
(158111, 'esES', '', 'Pero para alcanzar la victoria no basta con aumentar nuestra fuerza. Tenemos que aplastar al enemigo hasta que se arrodille a nuestros pies.', 28153),
(158110, 'esES', '', 'Sabía que no había nadie mejor que tú para atraer a los Zandalari a nuestra causa.', 28153),
(158109, 'esES', '', 'Adalid, cuando la princesa Talanji recurrió a nosotros en busca de ayuda, vi una oportunidad de sumar la fuerza de su reino a nuestra causa.', 28153),
(158108, 'esES', 'La mihma tierra ehtá muerta aquí. Ehto eh el horror, colega. Verdadero horror.', '', 28153),
(158107, 'esES', '', 'Caliéntate las manos y reposa los huesos, $c.', 28153),
(158106, 'esES', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t ¡%s comienza a lanzar |cFFFF0000|Hspell:273361|h[Charco de oscuridad]|h|r!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t ¡%s comienza a lanzar |cFFFF0000|Hspell:273361|h[Charco de oscuridad]|h|r!', 28153),
(158105, 'esES', 'Te doy la bienvenida a Puesto Vientoveloz, $n. La avanzada está bajo tu mando.', '', 28153),
(158104, 'esES', 'Debí... contratar... la garantía...', '', 28153),
(158103, 'esES', '¡$gBienvenido:Bienvenida; al palacio del DOLOR de Gallywix, $gasqueroso ladrón:asquerosa ladrona;!', '', 28153),
(158102, 'esES', 'Pedirle a Fozruk que ataque Ar\'gorok.', 'Pedirle a Fozruk que ataque Ar\'gorok.', 28153),
(158101, 'esES', 'La corrupción se extiende más rápido de lo que había imaginado...', '', 28153),
(158100, 'esES', 'Estas esporas no son normales. Hay que averiguar su origen.', '', 28153),
(158099, 'esES', 'Hemos hecho lo que hemos podido. Que en la próxima vida encuentren la paz.', '', 28153),
(158098, 'esES', 'Estos espíritus están muy alterados. Acabemos con su tormento.', '', 28153),
(158097, 'esES', '', 'Bien hecho. Ojalá dehcansen en paz.', 28153),
(158096, 'esES', '', 'Loh ehpírituh ehtán alteradoh. Otorgadleh la paz que ansían.', 28153),
(158095, 'esES', '', 'Con ehtah ehporah, podemoh encontrar el origen de la corrupción y dehtruirla.', 28153),
(158094, 'esES', '', 'La corrupción se propaga con rapidez. Tenemoh que detenerla. Necesitamoh ehporah pa ehtudiarlah.', 28153),
(158093, 'esES', '¡Hermanos y hermanas! ¡La Horda intensifica su ataque contra la Costa Oscura! ¡Acudid al Río Culebra!', '', 28153),
(158092, 'esES', '¡Te ha imbuido el poder del viento!', '¡Te ha imbuido el poder del viento!', 28153),
(158091, 'esES', 'Quiero todo este oro de vuelta en el palacio lo antes posible y entonces...', '', 28153),
(158090, 'esES', '¡Nada de retrasos! ¡Ni excusas! ¡Ni ascensos!', '', 28153),
(158089, 'esES', '¡Fuera de mi camino! ¡La Alianza está aquí!', '', 28153),
(158088, 'esES', 'No moriré... a manos de un goblin.', '', 28153),
(158087, 'esES', 'La Alianza cuenta con los elfos del Vacío. No la defraudaremos.', '', 28153),
(158086, 'esES', '¡Gallywiiiiix!', '¡Gallywiiiiix!', 28153),
(158085, 'esES', '¡Dispersaos! ¡Es la Alianza!', '¡Dispersaos! ¡Es la Alianza!', 28153),
(158084, 'esES', '', 'La Horda ha debido de expulsar a los fúrbolgs de su hogar.', 28153),
(158083, 'esES', '', 'La Horda... Hay demasiados...', 28153),
(158082, 'esES', '¡Oro bendito! ¿De dónde ha salido $gel elfo:la elfa;?', '¡Oro bendito! ¿De dónde ha salido $gel elfo:la elfa;?', 28153),
(158081, 'esES', '', 'Normalmente los fúrbolgs son una tribu pacífica, pero al ser expulsados de su hogar deben de haberse vuelto locos.', 28153),
(158078, 'esES', '', 'Camino en las sombras.', 28153),
(158077, 'esES', '', '¡Enseguida!', 28153),
(158076, 'esES', '', '¡Cuidado, adalid! ¡Que no nos descubran!', 28153),
(158075, 'esES', '', 'Rápido, ¡asegúrate de que no alerta a los demás!', 28153),
(158074, 'esES', '', '¡Intenta que no te detecten! No podemos llamar demasiado la atención...', 28153),
(158073, 'esES', '¡Ahora bajo, Lanfa!', '', 28153),
(158072, 'esES', '', 'Después de ti. Si quieres que incapacite a alguien, dímelo. Bajito, eso sí.', 28153),
(158071, 'esES', 'Harli te llevará allí y volverá a por mí. ¡Debo comprobar que mi compañera ehtá bien!', '', 28153),
(158070, 'esES', 'Una lección bien impartida. A ver si aprenden algo de ella.', '', 28153),
(158069, 'esES', 'Esoh enanoh no son bienvenidoh aquí, pero parece que no se dan por aludidoh. Que aprendan cómo tratan loh Zandalari a loh intrusoh.', '', 28153),
(158068, 'esES', 'Si alguien intenta subir a esta colina... ¡matadlo!', '', 28153),
(158067, 'esES', '¡Cuando desmantelemos la flota, Zandalar será nuestra!', '', 28153),
(158066, 'esES', '¡Levantad esos pilares!', '', 28153),
(158065, 'esES', '<Esperar un momento mientras Genn convence a Katherine en una escena intermedia absolutamente genial>.', '<Esperar un momento mientras Genn convence a Katherine en una escena intermedia absolutamente genial>.', 28153),
(158064, 'esES', 'El pueblo de Kul Tiras está unido, pero su casa gobernante no, y la Alianza está desprovista de una de nuestras líderes más poderosas.\n\nEspero poder reparar también esta desavenencia.', '', 28153),
(158063, 'esES', 'Reúnete conmigo en el monumento familiar junto al Fuerte Valiente. Con algo de suerte, podremos convencer a la lady almirante Valiente de que anule la sentencia contra su hija.', '', 28153),
(158062, 'esES', 'Adalid, has ayudado a unir a la gente de Kul Tiras y has conseguido su apoyo para la Alianza. Tal vez ahora puedas ayudar con la reconciliación de una madre con su hija.', '', 28153),
(158061, 'esES', 'Al privar a la Horda de sus suministros, ralentizamos su ataque. Hemos ganado tiempo.', '', 28153),
(158060, 'esES', '¡Esos horrendos goblins están extrayendo combustible para sus máquinas de guerra! ¡Acaba con esta profanación!', '', 28153),
(158059, 'esES', '', 'Avanzamos mientras los fuegos arden.', 28153),
(158058, 'esES', '', 'Estos elementales potenciarán nuestros demoledores. Mátalos, y si algún kaldorei se interpone en tu camino, acaba con él.', 28153),
(158057, 'esES', 'Podemos viajar por el Vacío para ahorrar tiempo. Sígueme.', '', 28153),
(158056, 'esES', 'Gallywix es escurridizo. No se quedará mucho tiempo en campo abierto.', '', 28153),
(158055, 'esES', 'Debería haber sabido que un goblin como Gallywix sería incapaz de resistirse a saquear una ciudad literalmente hecha de oro.', '', 28153),
(158054, 'esES', '', '¡Nos han descubierto! Recoge toda la azerita que puedas. ¡Tenemos que salir de aquí lo antes posible!', 28153),
(158053, 'esES', '', 'Por la diosa... ¡Azerita! ¡Por todas partes!', 28153),
(158052, 'esES', 'Salen nodos de azerita por todas partes.', 'Salen nodos de azerita por todas partes.', 28153),
(158051, 'esES', '<Apoyar la mano en el nodo de azerita>.', '<Apoyar la mano en el nodo de azerita>.', 28153),
(158050, 'esES', '<El nodo de azerita emite un zumbido de poder>.', '', 28153),
(158049, 'esES', '', 'Encárgate de la trituradora, yo expulsaré a los invasores de la arboleda.', 28153),
(158048, 'esES', '¡El Páramo de los Ancianos! Madre mía...', '¡El Páramo de los Ancianos! Madre mía...', 28153),
(158047, 'esES', '¡Allá voy!', '¡Allá voy!', 28153),
(158046, 'esES', 'Cuidado con los fúrbolgs. De repente han aparecido montones.', 'Cuidado con los fúrbolgs. De repente han aparecido montones.', 28153),
(158045, 'esES', '¡Voy de camino!', '¡Voy de camino!', 28153),
(158044, 'esES', 'Los fúrbolgs parecen más agresivos de lo normal...', 'Los fúrbolgs parecen más agresivos de lo normal...', 28153),
(158043, 'esES', '|TInterface\\Icons\\INV_misc_boilingblood:20|t ¡%s te escoge como objetivo de |cFFFF0000|Hspell:271224|h[Descarga de plasma]|h|r!', '', 28153),
(158042, 'esES', 'No subestimes la importancia de tus actos. Podremos aprovechar estas victorias para fortalecer nuestra posición en la zona.', '', 28153),
(158041, 'esES', 'La Horda quiere asegurar aquí su posición. Adalid, ¡no lo permitas!', '', 28153),
(158040, 'esES', '', 'Lah críah sobrevivirán. Bien hecho.', 28153),
(158039, 'esES', '', 'Unah críah un tanto ehtrañah necesitan auxilio. Ayúdalah y gánate el favor de Gonk.', 28153),
(158038, 'esES', 'Una partida de guerra menos de la que preocuparse. Bien hecho.', '', 28153),
(158037, 'esES', '', '¡Zandalar eterno!', 28153),
(158036, 'esES', '', 'Si no fuera por ti, adalid de la Horda, nuehtrah pérdidah habrían sido mucho mayoreh.$bEhto prueba, ahora máh que nunca, que eh hora de adaptarse. Debemoh volver a formar parte del mundo.', 28153),
(158035, 'esES', '', 'Que ehta guja sirva como recordatorio de que no importa cuánto caigamoh, ni cuánto perdamoh, ¡somoh Zandalari! $b¡Noh adaptamoh! ¡Y sobrevivimoh!', 28153),
(158034, 'esES', '', 'Culpable de lah muerteh de tantoh hermanoh y hermanah...', 28153),
(158033, 'esES', '', 'Contemplad la sangre de G\'huun, culpable de lah muerteh de Shadra, Hir\'eek, Torga y... y Rezan.', 28153),
(158032, 'esES', 'Nuestros exploradores informan de la presencia de un buque de guerra de la Horda en la costa. Evita que sus tropas desembarquen.', '', 28153),
(158031, 'esES', '', 'El mérito no eh mío.', 28153),
(158030, 'esES', 'En estas tierras no podemos dar nada por sentado. Gracias a ti, nuestros exploradores podrán ver un nuevo amanecer.', '', 28153),
(158029, 'esES', 'Muéhtraleh la hoja. Conviértete en el símbolo que necesitan.', '', 28153),
(158028, 'esES', 'Hicihte lo necesario pa salvar a tu gente. Ahora, máh que nunca, necesitan un líder a quien amar, un líder que leh guíe.', '', 28153),
(158027, 'esES', 'Fuihte tú quien trajo ayuda a ehtah tierrah contra la voluntad de tu padre. Dehcubrihte loh secretoh de G\'huun cuando nadie máh pudo.', '', 28153),
(158026, 'esES', 'Tenemos varios operativos del IV:7 desplegados en esta región, pero aún no hemos recibido ningún informe suyo. Averigua cuál es el problema.', '', 28153),
(158025, 'esES', 'Adelante, líder de Zandalar. Muehtra la hoja a aquelloh que máh necesitan verla. Otórgaleh paz.', '', 28153),
(158024, 'esES', '', 'Vol\'jin, ¿puedeh oírnoh? Muéhtraté, ehpíritu.', 28153),
(158023, 'esES', 'La Horda pagará con sangre cada centímetro que trate de conquistar. Incluso la victoria más nimia puede decidir una guerra. Buen trabajo.', '', 28153),
(158022, 'esES', 'Perdido... Tanto perdido. ¡Tantoh sin nadie que loh guíe! Tantoh sin conocer la justicia. G\'huun ha engullido toda ehperanza.', '', 28153),
(158021, 'esES', 'La Horda cree que puede operar sin oposición aquí. Demuéstrales lo equivocados que están.', '', 28153),
(158020, 'esES', '', 'Silencio.', 28153),
(158019, 'esES', '¡Lo oigo!', '', 28153),
(158018, 'esES', 'Perdido...', '', 28153),
(158017, 'esES', '', 'Vol\'jin, hijo de Sen\'jin, ehcucha lah voceh de tu familia y amigoh. Se preguntan dónde ehtáh.', 28153),
(158016, 'esES', 'Colocando azerita', 'Colocando azerita', 28153),
(158015, 'esES', '¡Hay que defender el Páramo de los Ancianos!', '¡Hay que defender el Páramo de los Ancianos!', 28153),
(158014, 'esES', 'No bajo la guardia.', 'No bajo la guardia.', 28153),
(158013, 'esES', '<Ayudarlo a levantarse>.', '<Ayudarlo a levantarse>.', 28153),
(158012, 'esES', 'Te diré la verdad: he estado peor.\n\nPero poco más.', '', 28153),
(158011, 'esES', '', 'Adalid, ¡los ancestros nos reclaman! ¡Busca a los druidas de la Zarpa en el bosque y reúnete conmigo en el Páramo de los Ancianos!', 28153),
(158009, 'esES', '', 'Esto nos dará un pequeño respiro. Centinelas, ¡mantened la posición!', 28153),
(158008, 'esES', '', 'Nunca he visto a nadie así. Me temo que podemos haber perdido a tu amigo por la llamada de las sirenas.', 28153),
(158007, 'esES', '<Preguntarle si ha visto a Flynn>.', '<Preguntarle si ha visto a Flynn>.', 28153),
(158006, 'esES', '¿Que ya no está? ¿Cómo que ya no está? ¡Exijo un reembolso!', '¿Que ya no está? ¿Cómo que ya no está? ¡Exijo un reembolso!', 28153),
(158005, 'esES', '', 'No eres el único que le pide archivos al IV:7.', 28153),
(158004, 'esES', '¿Cómo es que una general elfa condecorada conoce a alguien como yo?', '', 28153),
(158003, 'esES', '', 'Tú mismo eres un héroe por méritos propios, Keeshan, desde tu servicio en las tres primeras guerras hasta tus actos de heroísmo en Crestagrana.', 28153),
(158002, 'esES', 'Por lo que a mí respecta, apenas soy digno de servir a tu lado. Lo menos que puedo hacer es callarme y mostrarte respeto.', '', 28153),
(158001, 'esES', 'Señora, he leído tu archivo del IV:7. Llevas viva más de diez mil años y has luchado en más guerras de las que yo pueda imaginar.', '', 28153),
(158000, 'esES', '', 'Keeshan, tienes permiso para descansar cuando estés conmigo.', 28153),
(157999, 'esES', 'Dijo que debería estar matando a la Alianza en vez de ocuparse de alguna tontería. Después de eso supe que debía marcharme antes de hacer ningún otro trato a cambio de historias.', '', 28153),
(157998, 'esES', '¡La Areiel que buscáis está en la Necrópolis, junto con toda una hueste de la Horda! Parecía muy molesta por una misiva que había recibido.', '', 28153),
(157997, 'esES', '¡Esto va a ser divertido! Te diré lo que necesitas saber y tú luego puedes contarme tus experiencias de guerra.', '', 28153),
(157996, 'esES', '', 'Yo he vivido más de 10 000 años y he combatido en todas las guerras. Vi el Pozo de la Eternidad original con mis propios ojos.', 28153),
(157995, 'esES', 'Y yo serví en las tres primeras guerras, fui prisionero de unos orcos bárbaros, sobreviví y ayudé a matar a un dragón Negro.', '', 28153),
(157994, 'esES', '¡Una buena historia! Torga me iba a contar unas muy buenas también, pero ahora está muerto. ¿Tenéis alguna buena historia?', '', 28153),
(157993, 'esES', 'Acabamos de salvarte la vida. ¿Qué más necesitas?', '', 28153),
(157992, 'esES', 'Puedo contártelo todo de la Horda. Solo necesito algo a cambio.', '', 28153),
(157991, 'esES', 'Gracias, señora.', '', 28153),
(157990, 'esES', '', '$n, Keeshan, gracias por toda vuestra ayuda. Yo debo irme ahora para continuar la caza de Dreven. Que Elune bendiga vuestro camino.', 28153),
(157989, 'esES', '¡Adelante! ¡Yo me ocupo del flanco!', '', 28153),
(157988, 'esES', '', '$n, Keeshan, venid. Volvamos al Fuerte Victoria... y pidamos un funeral digno para mis amigos.', 28153),
(157987, 'esES', '', 'Elfos, humanos... Todos somos iguales, Keeshan. Ninguno de nosotros vale más que otro.', 28153),
(157986, 'esES', 'Estaré... como nuevo enseguida... pero no debería haber vivido yo. Deberían haber sobrevivido tus amigos.', '', 28153),
(157985, 'esES', '', '¡Keeshan! Gracias a Elune, al menos alguien ha sobrevivido a esta carnicería.', 28153),
(157984, 'esES', '<tose> Señora... aún no estoy... muerto del todo. Parece que su poder... no es tan grande... sin esos esbirros.', '', 28153),
(157983, 'esES', '', 'Falia... Lyrias... Aeolyn... Keeshan... ¡$n, te juro que Dreven lo pagará!', 28153),
(157982, 'esES', '¡Ah!', '', 28153),
(157981, 'esES', 'Nunca me rendiré, Shandris Plumaluna. ¡Contempla la fragilidad de tus aliados!', '', 28153),
(157980, 'esES', 'Será mejor que noh vayamoh. Dejemoh que loh ehpírituh encuentren a Bwonsamdi por sí mihmoh.', '', 28153),
(157979, 'esES', 'Seguro que loh trolh de sangre volverán, pero ahora saben que podemoh hacerleh daño aquí, en su hogar. Se lo pensarán doh veceh anteh de atacarnoh de nuevo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'esES', '', 'Shandris, sigue... sin mí...', 28153),
(157977, 'esES', 'Me adelantaré pa encontrar una zona segura. Reúnete conmigo en lah afuerah de la aldea cuando puedah.', '', 28153),
(157976, 'esES', '¡Abraza la muerte conmigo, elfo de la noche!', '', 28153),
(157975, 'esES', '¡Es hora de que veas lo que puede hacer este patético humano!', '', 28153),
(157974, 'esES', '', '¡Desactivad el escudo! ¡Aprovechad la oportunidad! ¡Stromgarde será nuestra!', 28153),
(157973, 'esES', '', '¡Todos los cañones! ¡FUEGO!', 28153),
(157972, 'esES', '', '¿Sí?', 28153),
(157971, 'esES', 'Seguro que nos dejarán volver para recuperar algunos de nuestros bienes. Cuando se despeje el humo, claro.', 'Seguro que nos dejarán volver para recuperar algunos de nuestros bienes. Cuando se despeje el humo, claro.', 28153),
(157970, 'esES', '¡Todo lo que teníamos estaba en la Rama de los Eternos!', '¡Todo lo que teníamos estaba en la Rama de los Eternos!', 28153),
(157969, 'esES', '¡Vas a desear haber ardido con Darnassus!', '', 28153),
(157968, 'esES', '¿Shandris Plumaluna intentando una emboscada? Qué audacia.', '', 28153),
(157967, 'esES', 'Quizás este patético humano sirva de ejemplo para los demás.', '', 28153),
(157966, 'esES', '', 'La matanza acaba hoy, Dreven.', 28153),
(157965, 'esES', '¿A cuántos más de tu misma calaña debo matar para que dejéis de interponeros en nuestro camino?', '', 28153),
(157964, 'esES', 'La Alianza. Sabía que seríais demasiado idiotas para aprender la lección de nuestro último encuentro.', '', 28153),
(157963, 'esES', 'Parece que es el momento de quitar de en medio las arañas de combate malas y poner en juego algunas buenas.', '', 28153),
(157962, 'esES', 'Un tío y tres arañas hacen un total de 26 patas, no tenías ninguna posibilidad.', '', 28153),
(157961, 'esES', '¡Cuando cae una, otra ocupa su lugar!', '', 28153),
(157960, 'esES', 'Tranquilo, pequeño. ¿Nos ayudarás?', 'Tranquilo, pequeño. ¿Nos ayudarás?', 28153),
(157959, 'esES', '<Flicka te mira con cautela>\n\n¿Flicka?', '', 28153),
(157958, 'esES', 'Venga, eso es. ¡Somos chicos malos! ¡A rocanrolear!', '', 28153),
(157957, 'esES', 'Estoy listo para matar a Dreven y sus seguidores.', 'Estoy lista para matar a Dreven y sus seguidores.', 28153),
(157956, 'esES', 'Hola, me llamo Dilbert McClint y lo mío es la gestión de infestaciones. Siempre es un placer combatir contra otro amante de los arácnidos.', '', 28153),
(157955, 'esES', 'Parece que somos el cebo para un hatajo de elfos chupasangres hambrientos. ¿Estás a punto para lo que pueda pasar a continuación?', '', 28153),
(157954, 'esES', '', 'Avisaré a los demás, Keeshan se reunirá contigo en los túneles.', 28153),
(157953, 'esES', '', 'Bien hecho. Nosotros podemos encargarnos del resto.', 28153),
(157952, 'esES', '', '¡La Horda se ha abierto paso y está intentando establecer una base! Expúlsalos con la ayuda de tu dragón hada.', 28153),
(157951, 'esES', 'Al caminar por esta espesura cercana uno podría pensar que a las arañas no les gustan el aire libre y la brisa, pero en ese aspecto son como tú y como yo. Eso, y que las telarañas delatan claramente una presencia arácnida.', '', 28153),
(157950, 'esES', '', 'Nos veremos en las Ruinas de Zo\'bal. Ten cuidado.', 28153),
(157949, 'esES', 'Ah, la emoción de la caza. Saboréala, como hago yo.', '', 28153),
(157948, 'esES', '', 'Un respiro para los fatigados y comida para los hambrientos.', 28153),
(157947, 'esES', 'Siempre, Princesa.', '', 28153),
(157946, 'esES', '', 'Ya veo. Volveré a Zuldazar. Mantenme al corriente de lah operacioneh de la Horda en Nazmir. Y ten cuidado, Rokhan.', 28153),
(157945, 'esES', 'Sylvanah quiere darleh una oportunidad. No tienen hogar al que volver. Si son capaceh de trabajar con nosotroh, tendrán un hogar con la Horda. Si no, se marcharán.', '', 28153),
(157944, 'esES', 'Esta amenaza aviaria domina los mares y ataca a todos los barcos que enviamos contra Kul Tiras. Acaba con ella.', '', 28153),
(157943, 'esES', '', 'No me fío de ehte Dreven, Rokhan. No eh prudente involucrar a nada menoh que los San\'layn en ehte conflicto.', 28153),
(157942, 'esES', 'Haré lo que pides, por el momento. Despejaremos ese túnel y avisaremos cuando vuestras fuerzas puedan movilizarse.', '', 28153),
(157941, 'esES', 'Porque parte de vuehtro acuerdo con Sylvanah era rehpetar la jerarquía de mando de la Horda y soy tu superior, hermano.', '', 28153),
(157940, 'esES', 'Quieres que usemos nuestras facultades... para mover rocas. ¿Y por qué debería seguirte, trol?', '', 28153),
(157939, 'esES', 'Hay un túnel derrumbado que une Nazmir y Vol\'dun. Llévate a tuh seguidoreh, utilizad vuehtroh podereh pa retirar loh ehcombroh y atacaremoh al grueso de lah fuerzah de la Alianza.', '', 28153),
(157938, 'esES', '', 'Hay un túnel derrumbado al sur de aquí que conecta Nazmir y Vol\'dun. Dehpéjalo y la Horda podrá atacar fácilmente la base principal de la Alianza en Vol\'dun.', 28153),
(157937, 'esES', 'Eso a Sylvanah no le va a guhtar. Tenemoh que llevar a cabo rápido nuehtro plan pa detener a la Alianza, príncipe Dreven.', '', 28153),
(157936, 'esES', 'Llámalo uno de mis talentos especiales. La Alianza ha saboteado a las fuerzas de la Horda en la Necrópolis y ha matado a Areiel.', '', 28153),
(157935, 'esES', '', 'Pa ti soy la princesa Talanji, Dreven. ¿Y cómo sabeh eso?', 28153),
(157934, 'esES', 'La capitana Areiel no vendrá porque ha sido asesinada, Talanji.', '', 28153),
(157933, 'esES', '', 'Y sin embargo no ehtá aquí. ¿Ehtá demasiado ocupada pa dar un simple informe?', 28153),
(157932, 'esES', 'Areiel mató tanto a lah fuerzah de la Alianza como a lah de loh trolh de sangre y noh ayudó a ehtablecer una base en la Necrópolih.', '', 28153),
(157931, 'esES', '', 'Dihculpa el retraso, Rokhan. Cuéntame cómo van lah cosah aquí. ¿Ha sido de ayuda la capitana Areiel?', 28153),
(157930, 'esES', 'Princesa, graciah por venir dehde Zandalar. Ehtamoh dándolo todo pa rechazar a loh trolh de sangre y a loh invasoreh de la Alianza.', '', 28153),
(157929, 'esES', '', 'Te doy la bienvenida, $n. La avanzada está bajo tu mando.', 28153),
(157927, 'esES', 'Estoy a tu servicio.', '', 28153),
(157926, 'esES', '(Tomar el frasco de invisibilidad).', '(Tomar el frasco de invisibilidad).', 28153),
(157925, 'esES', '', 'Que no te descubran. Es mejor que solo entre $guno:una;. Yo me quedaré aquí para asegurarme de que nadie se entere de lo que estamos haciendo.\n\nTengo un frasco de invisibilidad que puedes usar para entrar con sigilo. Debería volverte completamente invisible... durante un corto período de tiempo.\n\nBebe del frasco y cuélate en las ruinas. Averigua qué planea la Horda y luego sal.', 28153),
(157924, 'esES', 'Temo que incluso las pequeñas victorias estén solo retrasando lo inevitable.', '', 28153),
(157923, 'esES', 'Estamos manteniendo a la Horda a raya, pero ahora se han fijado en una erupción de azerita en la costa. Debemos detenerlos.', '', 28153),
(157920, 'esES', 'Acércate, corazón. ¡Wunja ehtará ciega, pero no sorda! ¡Je, je, je! ¿Vieneh a la vieja Wunja por una poción?', 'Acércate, corazón. ¡Wunja ehtará ciega, pero no sorda! ¡Je, je, je! ¿Vieneh a la vieja Wunja por una poción?', 28153),
(157919, 'esES', '', 'Al Gran G no le va a gustar esto...', 28153),
(157918, 'esES', '', '¡Te voy a reventar pero bien, justo en la boca!', 28153),
(157917, 'esES', 'Mi gente está lista, $p. Por la Alianza.', '', 28153),
(157916, 'esES', '', 'Supongo que entonces vendrás conmigo, $p. Te veré en el Campo del Relicario.', 28153),
(157915, 'esES', 'Vamos, Mecafusible.', '', 28153),
(157914, 'esES', 'He luchado en las tres guerras. Pensaba que había visto lo peor que Azeroth podía ofrecer.\n\nMe equivocaba.', '', 28153),
(157913, 'esES', '', 'Tengo algo que puede ser de ayuda.', 28153),
(157912, 'esES', '', 'Solo quedas tú. ¡Preséntate ante la capitana Luna de Verano y refuerza esa frontera!', 28153),
(157911, 'esES', '', 'Arqueros de hipogrifo, conmigo. ¡Nos reagruparemos en Lor\'danel y permaneceremos alerta como una unidad de respuesta móvil!', 28153),
(157910, 'esES', '', '¡Centinelas, cread un frente de batalla en el Río Culebra! ¡Arengad a nuestros aliados en el Páramo de los Ancianos!', 28153),
(157909, 'esES', '', '¡Cazadoras, tenéis que reforzar la frontera sur de Costa Oscura! ¡Traed los lanzagujas!', 28153),
(157908, 'esES', '', '¡Debemos entrar en acción! ¡Centinelas, vista al frente!', 28153),
(157907, 'esES', '¡Capitana, la Horda ha llegado hasta Río Culebra! ¡No podremos retenerlos mucho tiempo!', '¡Capitana, la Horda ha llegado hasta Río Culebra! ¡No podremos retenerlos mucho tiempo!', 28153),
(157906, 'esES', '¡Una alpaca! ¡Bien!', '', 28153),
(157905, 'esES', '¿Seguro?', '¿Seguro?', 28153),
(157904, 'esES', '', '¡A tus órdenes!', 28153),
(157903, 'esES', '<Atacar sin más>.', '<Atacar sin más>.', 28153),
(157902, 'esES', '¿Qué tal algo de oro?', '¿Qué tal algo de oro?', 28153),
(157900, 'esES', 'Sylvanas quiere enfrentarse a mí, y no se lo voy a negar. Hemos informado a nuestra flota; si Elune lo permite, volverá pronto.', '', 28153),
(157899, 'esES', 'Adalid, debes ayudarnos a defender Darnassus.', '', 28153),
(157898, 'esES', 'Delaryn, ve a nuestras avanzadas. Reúne a todos soldados que encuentres y tráelos aquí.', '', 28153),
(157897, 'esES', '', '¿Y tú, Shan\'do?', 28153),
(157896, 'esES', 'La Reina alma en pena pretende hacerse con el Árbol del Mundo.', '', 28153),
(157895, 'esES', '', '¡Malfurion! Las fuerzas de la Horda se reúnen en Avanzada de Zoram\'gar.', 28153),
(157894, 'esES', 'Puedes atravesar el muro, adalid. Los fuegos fatuos no te harán daño.', '', 28153),
(157893, 'esES', '', 'Incluso en tus últimos momentos sigues sin ver el verdadero potencial de los humanos.', 28153),
(157892, 'esES', '', 'Y sigues aferrándote a tus opiniones anticuadas sobre los humanos. Debería haberte matado hace mucho tiempo.', 28153),
(157891, 'esES', '', '¡Mi destino es vivir eternamente, no voy a morir aquí!', 28153),
(157890, 'esES', '', '¡Es una pena que estés luchando codo con codo con esta escoria humana, Shandris! Qué vidas tan cortas e insignificantes.', 28153),
(157889, 'esES', '', 'Shandris, han pasado... ¿dos, tres mil años? Quién iba a pensar que nos volveríamos a encontrar así, contigo ayudando a un humano, nada menos.', 28153),
(157888, 'esES', '', 'Oscuridad... Sylvanas... ¿esto es lo que viste? ¿De lo que nos querías salvar?', 28153),
(157887, 'esES', '', 'Y yo pensaba que sería una simple misión de reconocimiento. ¡Cómo voy a disfrutar!', 28153),
(157886, 'esES', '', 'Se acabó. Encuentra sus planos y vuelve a la Avanzada de Fincagrana cuando hayas terminado aquí.', 28153),
(157885, 'esES', '|cFF0000FF(Misión)|r Viaja en barco a Xibala, que está en Zuldazar.', '|cFF0000FF(Misión)|r Viaja en barco a Xibala, que está en Zuldazar.', 28153),
(157884, 'esES', '¡Bien hecho! Con esa criatura muerta, nuestras tropas podrán avanzar sin obstáculos.', '', 28153),
(157883, 'esES', 'El ron es para los verdaderos Marea de Hierro. ¡Fuera esas manos!', 'El ron es para los verdaderos Marea de Hierro. ¡Fuera esas manos!', 28153),
(157882, 'esES', 'Ya es bastante difícil establecer líneas de suministros a través de un pantano sin bestias mágicas de por medio. Acaba con esta y despeja el camino.', '', 28153),
(157881, 'esES', '', '¡Bien hecho! Esa criatura ya no noh dará máh problemah.', 28153),
(157880, 'esES', '', '¡Un mojo ohcuro alimenta a ehta criatura! Devuelve lah almah a Bwonsamdi.', 28153),
(157879, 'esES', '', 'Otra victoria.', 28153),
(157878, 'esES', '¡Tieneh que aprender que interrumpir a Bwonsamdi tiene un precio! ¿Por qué no haceh un viajecito?', '', 28153),
(157877, 'esES', '', 'Según mis exploradores, se ha producido una erupción repentina de azerita aquí en Costa Oscura. Ayuda a nuestros aliados goblins a conseguirla.', 28153),
(157876, 'esES', '¡No te arrimes demasiado a Bwonsamdi!', '¡No te arrimes demasiado a Bwonsamdi!', 28153),
(157875, 'esES', '¿Que qué pasa con las orejas?$b$bPues es cuestión de moda, OBVIAMENTE.', '', 28153),
(157874, 'esES', 'Hozen ladrones. Más vale que no falte nada de ron.', 'Hozen ladrones. Más vale que no falte nada de ron.', 28153),
(157873, 'esES', '¡Dejad de beberos el ron, miserables ratas de Pantoque!', '¡Dejad de beberos el ron, miserables ratas de Pantoque!', 28153),
(157872, 'esES', 'Nuestro objetivo principal es romper la alianza de la Horda con los Zandalari. Para ello, debemos establecer posiciones en territorio enemigo.', '', 28153),
(157871, 'esES', 'Ha llegado el momento de demostrarle a la Horda que la Séptima Legión va en serio.', '', 28153),
(157870, 'esES', '', 'Soldados... ¡No! ¡Esperad!', 28153),
(157869, 'esES', 'Mm, ¿esto está encendido? ¿Hola? Vale.', '', 28153),
(157868, 'esES', 'Ja, ¡les has dado lo suyo! Les llevará tiempo volver a movilizar a sus tropas. Buen trabajo.', '', 28153),
(157867, 'esES', 'Nos hemos hecho con otra de las armas de asedio de la Horda. ¡Es hora de darles un poco de su propia medicina!', '', 28153),
(157866, 'esES', '¡No! ¡No! ¡Imposible! Al jefe no le va a guhtar ehto. Se supone que no puedo perder ehpírituh en... Ehto no eh bueno.', '', 28153),
(157865, 'esES', 'Venga, Vol\'jin. Sal de esa urna. Ehpera... Ehpera... ¡No! ¿Dónde ehtá su ehpíritu? ¿Dónde ehtá Vol\'jin?', '', 28153),
(157864, 'esES', 'Vete, adalid. Aquí ya no hay nada pa ti.', '', 28153),
(157863, 'esES', 'Por suerte, parece que a los trabajadores no les importa que fisguemos, solo les importa a los matones de la compañía.\n\n¿Has conseguido lo que necesitamos?', '', 28153),
(157862, 'esES', 'Se ha conseguido mucho hoy aquí. Podemos reagruparnos fuera.', 'Se ha conseguido mucho hoy aquí. Podemos reagruparnos fuera.', 28153),
(157861, 'esES', '', 'Hay que detener a Jakra\'zet.', 28153),
(157860, 'esES', '¿Qué está haciendo el Rey por nuestra tierra?', '¿Qué está haciendo el Rey por nuestra tierra?', 28153),
(157859, 'esES', 'Los recursos de Ventormenta están al límite. No habrá bastante para mantenernos vivos a todos.', 'Los recursos de Ventormenta están al límite. No habrá bastante para mantenernos vivos a todos.', 28153),
(157858, 'esES', 'No, no, no, coleguita. Eso no se va a quedar aquí.', '', 28153),
(157857, 'esES', '¡Bien hecho! Unos dientes menos de los que preocuparse.', '', 28153),
(157856, 'esES', '¡En vez de luchar por ruinas, la Alianza debería recuperar nuestra patria!', '¡En vez de luchar por ruinas, la Alianza debería recuperar nuestra patria!', 28153),
(157855, 'esES', 'Ya hemos perdido dos hogares.', 'Ya hemos perdido dos hogares.', 28153),
(157854, 'esES', '¿Adónde se supone que debemos ir ahora?', '¿Adónde se supone que debemos ir ahora?', 28153),
(157853, 'esES', 'Bien hecho. Lah nuevah generacioneh podrán prohperar graciah a su muerte. ', '', 28153),
(157852, 'esES', 'Hay cosas más importantes en juego, General. Debemos adaptarnos a esta nueva información.', '', 28153),
(157851, 'esES', '', 'No podemos dejar que ese monstruo escape, Aterravermis.', 28153),
(157850, 'esES', '¡Lanza Negra no! ¡Nada de trolh tontoh en sitio trol guay!', '', 28153),
(157849, 'esES', 'Ninguna ehcoria de la Horda va a ser digna de ehte lugar. ¡Nosotroh, loh Furiarena, te desafiamoh!', 'Ninguna ehcoria de la Horda va a ser digna de ehte lugar. ¡Nosotroh, loh Furiarena, te desafiamoh!', 28153),
(157848, 'esES', '', 'Gracias, Alleria. Tu ayuda es más que bienvenida.', 28153),
(157847, 'esES', 'Una sabia estrategia. La apruebo.', '', 28153),
(157846, 'esES', '', 'Le daremos caza y te traeremos su cabeza. Shandris puede centrarse en rastrear al Príncipe de Sangre.', 28153),
(157845, 'esES', '', 'Mis elfos del Vacío pueden liderar el plan para eliminar a Gallywix.', 28153),
(157844, 'esES', '', 'Alleria abre un portal del Vacío detrás de ella.', 28153),
(157843, 'esES', '', 'No podemos dejar que se nos escape ninguno de estos objetivos. Y no tiene por qué ocurrir.', 28153),
(157842, 'esES', '', 'Perdonad que os interrumpa, pero creo que los dos tenéis razón.', 28153),
(157841, 'esES', '', 'He visto de lo que era capaz Dreven, Aterravermis. ¿Y si hay más como él?', 28153),
(157840, 'esES', 'Él es su punto débil táctico y no suele estar expuesto. Debemos atacar ahora.', '', 28153),
(157839, 'esES', 'Gallywix financia la campaña bélica de la Horda y comprende la azerita mejor que cualquiera de sus demás líderes.', '', 28153),
(157838, 'esES', '', '¡Podemos matar a ese goblin glotón cuando queramos! Si Dreven escapa, puede que nunca volvamos a encontrarlo.', 28153),
(157837, 'esES', 'Pronto nos ocuparemos del príncipe de sangre Dreven, General. Sin embargo, esta es una oportunidad insólita para neutralizar el ejército de la Horda. Todo lo demás debe esperar.', '', 28153),
(157836, 'esES', '¡Una bestia alada está alimentando a sus crías con mis hombres! Que coman acero de postre.', '', 28153),
(157835, 'esES', '¡No vah a traer a ese traidor amante de la Horda a ehte lugar sagrado!', '', 28153),
(157834, 'esES', '', 'Nuestros aliados esperan tus órdenes.', 28153),
(157833, 'esES', 'Pa\'ku, en su inmenso poder, ha decidido que la hora de Ji\'arak ha llegado. Reúne a tuh tropah y acaba con esa criatura.', '', 28153),
(157832, 'esES', 'Saludos, adalid. Tenemos mucho trabajo.', '', 28153),
(157831, 'esES', '¿Eso es... sangre? ¿En serio? ¿Me estás diciendo que esa cosa está protegida literalmente con un escudo de sangre?\n\nAhora sí que lo he visto todo.', '', 28153),
(157830, 'esES', '', '¡El Círculo es nuestro! ¡Todos a sus puestos!', 28153),
(157829, 'esES', 'La próxima guerra. Y la siguiente.', '', 28153),
(157828, 'esES', 'La Luz seguirá brillando cuando nosotros ya no existamos. Pero cuando esta guerra acabe, ¿qué te quedará a ti, Shaw?', '', 28153),
(157827, 'esES', '¿En la Luz? ¿O en Turalyon?', '', 28153),
(157826, 'esES', 'Al contrario. Presenciar el regreso de Turalyon y descubrir que la Luz lo había mantenido con vida, que lo había transformado, reforzó mi determinación. Comprendí que había depositado mi fe donde debía.', '', 28153),
(157825, 'esES', 'Y cuando descubriste que Turalyon estaba vivo, ¿te cuestionaste tu devoción o tus decisiones?', '', 28153),
(157824, 'esES', 'Cuando se fue a Terrallende con la expedición de la Alianza y se le dio por perdido, la Luz me abrió los ojos. Me di cuenta de que podía ser soldado y paladín al mismo tiempo. Y juré honrar su sacrificio.', '', 28153),
(157823, 'esES', 'Pero uno de esos primeros paladines me inspiró... Turalyon. Su fe le daba fuerzas, alimentaba su devoción y lo convertía en un gran líder.', '', 28153),
(157822, 'esES', 'Drukan se ha echado a descansar.', '', 28153),
(157821, 'esES', 'Yo era caballero cuando se fundó la Mano de Plata. Tenía mis dudas sobre esa mezcla entre devoción y artes bélicas, así que me centré en mi instrucción de combate.', '', 28153),
(157820, 'esES', 'Dime, Aterravermis, ¿cómo acaba un paladín liderando a un ejército de soldados de élite? ¿No deberías estar por ahí consagrando templos o algo así?', '', 28153),
(157819, 'esES', 'Ah, por supuesto.', '', 28153),
(157818, 'esES', 'Muy amable por tu parte, pero si tengo que elegir entre actuar con honor y hacer lo que tiene que hacerse, elijo lo segundo sin dudarlo. Por la Alianza, por supuesto.', '', 28153),
(157817, 'esES', 'Admito que, como paladín, tenía dudas acerca de la presencia de espías y asesinos en las filas de la Alianza. Pero el honor y la lealtad que le has demostrado a nuestro Rey son incuestionables.', '', 28153),
(157816, 'esES', 'El IV:7 se creó para trabajar en las sombras. Y yo lo prefiero así, de ese modo no estoy tan... expuesto.', '', 28153),
(157815, 'esES', 'He dejado de contarlas. Voy donde la Alianza me ordena que vaya... y donde la Luz me llama. Pero esta tampoco es tu primera batalla.', '', 28153),
(157814, 'esES', '¿Cuántas campañas llevas ya contra la Horda, Aterravermis?', '', 28153),
(157813, 'esES', 'Cuidado con dónde usas eso, $n.', '', 28153),
(157812, 'esES', 'Me pareció que debías saberlo.', '', 28153),
(157811, 'esES', '¡El taller ya está abierto! ¡Si necesitas algo, tenemos el sudor y la grasa necesarios para hacerlo!', '', 28153),
(157810, 'esES', '¡Devolveremos diez veces el daño que sufrió Guerracolmillo!', '', 28153),
(157809, 'esES', 'Ya no temo a la muerte, la muerte me teme a mí...', '', 28153),
(157808, 'esES', 'La Jefa de Guerra no dejará que esto quede impune.', '', 28153),
(157807, 'esES', 'La muerte es demasiado buena para ti.', '', 28153),
(157806, 'esES', '¡Devoraré tu cadáver!', '', 28153),
(157805, 'esES', '¡Te partiré en dos!', '', 28153),
(157804, 'esES', '', 'Buen trabajo, pero algo me dice que seguirán intentándolo.', 28153),
(157803, 'esES', '', '¡Los piratas vuelven a atacar Alto del Vigía! ¡¿Es que nunca aprenderán?! Ayuda a los marinos a repelerlos.', 28153),
(157802, 'esES', '¡Gracias! Tengo que volver con mi familia.', '¡Gracias! Tengo que volver con mi familia.', 28153),
(157801, 'esES', '¡¿Has visto sus caras?! Ah, ¡que me troncho! ¡Se van a pasar días limpiando!', '', 28153),
(157800, 'esES', '¡La Horda es un hatajo de bárbaros!', '¡La Horda es un hatajo de bárbaros!', 28153),
(157799, 'esES', 'Es mejor purgar toda esa corrupción insidiosa antes de que contamine a la Horda.', '', 28153),
(157798, 'esES', 'Bien hecho. ¡No podemos quedarnos de brazos cruzados mientras el abismo corrompe nuestra tierra!', '', 28153),
(157797, 'esES', 'A Venrik y a mí nos gustaba desmelenarnos de vez en cuando y dar una vuelta montados en loros. Pruébalo y haz que llueva justicia sobre esos bandidos.', '', 28153),
(157796, 'esES', 'Desgastado...', '', 28153),
(157795, 'esES', 'He cometido un... error de cálculo.', '', 28153),
(157794, 'esES', 'Esta abominación es pura locura y corrupción. ¡Destrúyela de inmediato!', '', 28153),
(157793, 'esES', 'Solo espero que mi familia escapara a tiempo.', 'Solo espero que mi familia escapara a tiempo.', 28153),
(157792, 'esES', 'El humo era muy denso. Nos habríamos perdido en él de no ser por la reina Cringrís.', 'El humo era muy denso. Nos habríamos perdido en él de no ser por la reina Cringrís.', 28153),
(157791, 'esES', 'Hay que devolver a esta criatura al abismo. ¡Acaba con ella!', '', 28153),
(157790, 'esES', 'Apenas logramos salir con vida.', 'Apenas logramos salir con vida.', 28153),
(157789, 'esES', '¿Por qué harían algo así?', '¿Por qué harían algo así?', 28153),
(157788, 'esES', '¡Vas a conseguir que pierda un tornillo!', '', 28153),
(157787, 'esES', '¡Todo esto es míooooo!', '', 28153),
(157786, 'esES', '¡Te taladraré hasta la muerte!', '', 28153),
(157785, 'esES', '', 'Gracias a ti, lo que podría haber sido una enorme pérdida para la Guardia de los Valiente se ha quedado en un simple contratiempo.', 28153),
(157784, 'esES', '', 'Uno de nuestros barcos de suministros ha encallado en el canal del sur. La tripulación ha escapado, pero ha dejado muchos bienes valiosos allí.', 28153),
(157783, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t ¡El belisario Yenajz comienza a lanzar |cFFF00000|Hspell:274932|h[Abismo infinito]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t ¡El belisario Yenajz comienza a lanzar |cFFF00000|Hspell:274932|h[Abismo infinito]|h|r!', 28153),
(157782, 'esES', '¡¿Bebida?! Repámpanos, esperaba que fueran riquezas... ¡para gastarlas en bebida!', '', 28153),
(157781, 'esES', 'Por Fuerte Libre se dice que uno de esos piratas tiene un jugoso botín oculto en las aguas que bañan el muelle. ¡A ver si lo encuentras!', '', 28153),
(157780, 'esES', 'Buen trabajo. Eso debería reducir la cantidad de armas de azerita que llegan a Boralus mientras nos ocupamos del motín de los Gobernalle.', '', 28153),
(157779, 'esES', 'A pesar de las órdenes, la Compañía Comercial Gobernalle sigue produciendo armas. Destruye esa fundición, pero intenta que no haya heridos.', '', 28153),
(157778, 'esES', 'No te preocupes, les encontraremos un nuevo hogar. Lo más importante es que ya no están en la calle y que no corren ningún peligro.', '', 28153),
(157777, 'esES', 'La Compañía Comercial Gobernalle atrae a huérfanos prometiéndoles comida y luego los explota. ¡Saca a esos niños de ahí!', '', 28153),
(157776, 'esES', 'Dicen que Azurethos podía sacar a un kraken de las olas con sus garras. Era muy peligroso... Te has convertido en una leyenda al derrotarlo.', '', 28153),
(157775, 'esES', 'Los marineros cantan canciones sobre el legendario Azurethos, capaz de volcar un galeón con una racha de viento. Acaba con él y las canciones hablarán de ti.', '', 28153),
(157774, 'esES', '', 'Presentaos ante el alto señor Colmillosauro. Haced que paguen cara esta locura. ¡Por la Horda!', 28153),
(157773, 'esES', 'Cada vez que cierro los ojos... veo las llamas.', 'Cada vez que cierro los ojos... veo las llamas.', 28153),
(157772, 'esES', 'Espero que nuestros amigos estén a salvo.', 'Espero que nuestros amigos estén a salvo.', 28153),
(157771, 'esES', 'No podemos perder Kalimdor.', 'No podemos perder Kalimdor.', 28153),
(157770, 'esES', 'No puedo creer que el Árbol del Mundo.... ya no esté...', 'No puedo creer que el Árbol del Mundo.... ya no esté...', 28153),
(157769, 'esES', '¡Esos perros de la Horda destruyeron nuestro hogar!', '¡Esos perros de la Horda destruyeron nuestro hogar!', 28153),
(157768, 'esES', '¿Qué quieres? Ah, tienes pinta de ser $gingeniero:ingeniera; también...', '', 28153),
(157767, 'esES', 'Me gustaría hacer otra pregunta.', 'Me gustaría hacer otra pregunta.', 28153),
(157766, 'esES', '¿Ese cocinero loco? Creo que es un primo segundo. Es triste, solo se le ocurren bombas y bombas mayores. El verdadero genio está en inventar la fuente de energía definitiva. Una que pueda alimentar durante el mayor tiempo posible máquinas capaces de romper, desgarrar, taladrar o volar por los aires montones de cosas.', '', 28153),
(157765, 'esES', 'Buenos días, doctor, me gustaría comprar uno de tus reactores. Puedo compensártelo en su justa medida.', 'Buenos días, doctor, me gustaría comprar uno de tus reactores. Puedo compensártelo en su justa medida.', 28153),
(157764, 'esES', '¡Lo eres! ¿El doctor Bum?', '¡Lo eres! ¿El doctor Bum?', 28153),
(157763, 'esES', 'Ah, eso crees. ¡Veo que SÍ que eres $gun hábil ingeniero:una hábil ingeniera;! Ni mucho menos tienes un nivel cercano al mío, pero pocos lo tienen.', '', 28153),
(157762, 'esES', '', 'No sé quién es esa, ¡pero lo que sí sé es que hay que matarla!', 28153),
(157761, 'esES', '¡Doctor, esa pieza es una extraordinaria obra de ingeniería!', '¡Doctor, esa pieza es una extraordinaria obra de ingeniería!', 28153),
(157760, 'esES', '', '¡Todo el mundo de vuelta al Yunquenegro! ¡Hay que hacer control de daños!', 28153),
(157759, 'esES', 'Eh, ¡estoy trabajando! Vuelve cuando tengas el título de ingeniería y algo útil que ofrecer.', '', 28153),
(157758, 'esES', '', '¡Qué rapidez! Muy bien. Vamos a abrir la puerta. Hay muchos enemigos al otro lado, ¡así que cuidado!', 28153),
(157757, 'esES', 'He pasado los últimos cinco años arreglando, mejorando y afinando el equipo más avanzado y letal de robots que se pueda imaginar. ¿Quieres ver cómo se las arreglan tus mascotas normales y aburridas contra mascotas creadas por el técnico reparador de bajo nivel más brillante del universo?', '', 28153),
(157756, 'esES', '¿Una avería? ¡Eso no debería ocurrir!', '', 28153),
(157755, 'esES', 'Mi mente brillante y las máquinas aún más brillantes que crea son una combinación invencible.', '', 28153),
(157754, 'esES', '', '¡Buen trabajo! El ensamblaje ya es historia. Drustvar está a salvo.', 28153),
(157753, 'esES', '', 'Un ensamblaje de piedra ha despertado en las montañas cerca de aquí. ¡Hay que acabar con él antes de que ataque a la gente de Drustvar!', 28153),
(157752, 'esES', '¡Inconcebible! La próxima vez haré robots más grandes.', '', 28153),
(157751, 'esES', '¡Ninguna mascota puede competir con mi equipo, soy imparable!', '', 28153),
(157750, 'esES', '¡Prepárate para enfrentarte a mi equipo invencible de robots modificados y personalizados!', '', 28153),
(157749, 'esES', 'Estoy listo, Krag\'wa.', 'Estoy lista, Krag\'wa.', 28153),
(157748, 'esES', 'Incluso ahora los trols de sangre siguen masacrando a mis hijos.$b$bOs ayudaré a llegar hasta su líder, pero debo volver rápido a la ciénaga para proteger a mis hijos.', '', 28153),
(157747, 'esES', 'Krag\'wa, el líder de los trols de sangre ha huido a la gran estructura que se ve a lo lejos. Por favor, préstanos tu ayuda.', 'Krag\'wa, el líder de los trols de sangre ha huido a la gran estructura que se ve a lo lejos. Por favor, préstanos tu ayuda.', 28153),
(157746, 'esES', 'Ah... Ejem. Ahora no, Venrik. Estamos aquí para hablar de cosas serias.', '', 28153),
(157745, 'esES', '', '¡He venido a ayudar, a luchar!', 28153),
(157744, 'esES', '', 'Lucho por mi pueblo.', 28153),
(157743, 'esES', '', '¡Es un enemigo fácil, despáchalo rápidamente!', 28153),
(157742, 'esES', 'La que tenía \"el cabello negro como un cuervo\". ¡Ja, ja, ja!', '', 28153),
(157741, 'esES', '', '¡En recuerdo de Darnassus!', 28153),
(157740, 'esES', '', 'Será un alivio abandonar este lugar.', 28153),
(157739, 'esES', '', 'Salgamos de aquí antes de que lleguen más de esas... cosas.', 28153),
(157738, 'esES', '', 'Sí... Lo estaré.', 28153),
(157737, 'esES', 'Eh, Flynn, ¿qué fue de aquella mujer de la que siempre estabas hablando?', '', 28153),
(157736, 'esES', '', '¡Madre! ¿Estás bien?', 28153),
(157735, 'esES', '', '¿Irás a recuperar el martillo? Es un poder en sí mismo y podría ser nuestra perdición si los goblins averiguan cómo usarlo.', 28153),
(157734, 'esES', '', '$n, tengo otra tarea para ti. Esos salvajes eran de Ventura y Cía. Eso significa que estarán en Kezan, probablemente entregándole Ferromazo al grasiento Mogul Razdunk en este preciso momento.', 28153),
(157733, 'esES', '', 'Maestro del yunque, Thaelin, pensad en cómo reparar el Yunquenegro.', 28153),
(157732, 'esES', '', '¡Ay! ¡Han robado Ferromazo y han partido el Yunquenegro en dos!', 28153),
(157731, 'esES', '', 'Y Kul Tiras jamás se rendirá.', 28153),
(157730, 'esES', 'Los Drust... nunca... nos rendiremos...', '', 28153),
(157729, 'esES', '¡Madre mía!', '', 28153),
(157728, 'esES', '¡Vosotros dos, abrid los ojos! ¡Mirad el Yunquenegro!', '', 28153),
(157727, 'esES', '', '¡Núcleo bendito! ¡Debe de ser ese meca grande que me golpeó!', 28153),
(157726, 'esES', '¡Una especie de moledor me ha atacado por sorpresa y me ha robado a Ferromazo!', '', 28153),
(157725, 'esES', '', 'Estoy bien. Tú tampoco tienes muy buena pinta.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'esES', '¡Reina regente! ¡¿Estás bien, muchacha?!', '', 28153),
(157723, 'esES', '', '¡Bien, chicos y chicas, vamos acabando!', 28153),
(157722, 'esES', '', 'Mi gente ya derrotó a los tuyos una vez, monstruo. ¡Volveremos a hacerlo!', 28153),
(157721, 'esES', '¡Thros os consumirá a todos! ¡Por fin me vengaré!', '', 28153),
(157720, 'esES', '', 'Justo cuando empezaban a irnos bien las cosas.', 28153),
(157719, 'esES', '', '<Moira murmura para sus adentros>.', 28153),
(157718, 'esES', '', '¡Thaelin, ve por la Sala de los Oficios! Puede que estén de camino a la Cámara Negra.', 28153),
(157717, 'esES', '', '¡$gCampeón:Campeona;, ve por la Ruta Hierro Negro y encárgate de asegurarla!', 28153),
(157716, 'esES', '', '¡Maestro del yunque, ve a reunir a tus hechiceros para un contraataque!', 28153),
(157715, 'esES', '', '¡¿Esos rastreros verdes sin agallas creen que pueden atacarnos en nuestro hogar?!', 28153),
(157714, 'esES', '¡Goblins! ¡En los túneles!', '', 28153),
(157713, 'esES', '', '¡A las armas, adalid!', 28153),
(157712, 'esES', '', '¡Te has enfrentado a la familia equivocada, demonio!', 28153),
(157711, 'esES', '', '¡Madre!', 28153),
(157710, 'esES', '', 'Madre, ¡cuidado!', 28153),
(157709, 'esES', '', 'Oh, ¡es de los grandes!', 28153),
(157708, 'esES', '¡No escaparéis!', '', 28153),
(157707, 'esES', '', 'Vamos, hija mía. Encontraremos la forma de salir de aquí.', 28153),
(157706, 'esES', '', '¡Aquí vienen más!', 28153),
(157705, 'esES', '', '¡Vienen elementales!', 28153),
(157704, 'esES', '', 'Hemos descubierto que aplicar magia poderosa a la azerita puede tener resultados inesperados.', 28153),
(157703, 'esES', '', '¿Jaina? ¿Eres tú de verdad?', 28153),
(157702, 'esES', 'Lo que quiere decir el ratón de biblioteca cascarrabias es que nos protejas cuando nos ataquen los elementos.', '', 28153),
(157701, 'esES', 'Es... demasiado tarde...', '', 28153),
(157700, 'esES', '$C, seguramente se producirán incidentes de azerigénesis espontánea mientras moldeamos la azerita. ¿Podrás apañártelas?', '', 28153),
(157699, 'esES', '¿Te importa ponerme algo más de azerita en el yunque, $n?', '', 28153),
(157698, 'esES', '¡Ahora te toca a ti!', '', 28153),
(157697, 'esES', '¡Idiotas insolentes! ¡No podéis hacer nada para salvarla!', '', 28153),
(157696, 'esES', 'Sí, Reina regente.', '', 28153),
(157695, 'esES', '', 'Thaelin, Thurgaden, poneos a ello.', 28153),
(157694, 'esES', '', '¡Basta! ¡Muestra tu verdadero ser, monstruo!', 28153),
(157693, 'esES', '', 'Están avanzando. Anduin sigue pidiendo información prácticamente todos los días, así que he pensado que podríamos enseñarte lo que hemos averiguado.', 28153),
(157692, 'esES', '', 'He tenido a los mejores refinando azerita desde que apareció por primera vez en nuestras profundidades.', 28153),
(157691, 'esES', '', 'Gracias por venir, $n.', 28153),
(157690, 'esES', '', 'Papá... por favor...', 28153),
(157689, 'esES', '', 'Nos vemos en la estatua de la colina.', 28153),
(157688, 'esES', '', '¡Gran Krag\'wa, necesitamoh tu ayuda!', 28153),
(157687, 'esES', 'Igual que en la Tercera Guerra.', '', 28153),
(157686, 'esES', '¡Por la Compañía Bravo!', '', 28153),
(157685, 'esES', '¡Igual que en Draenor!', '', 28153),
(157684, 'esES', 'Me recuerda a la Segunda Guerra.', '', 28153),
(157683, 'esES', 'Mm, mm, mm, mm.', 'Mm mm mm mm.', 28153),
(157682, 'esES', 'Repasemos el plan para matar a la capitana Areiel.', 'Repasemos el plan para matar a la capitana Areiel.', 28153),
(157681, 'esES', 'General.', '', 28153),
(157680, 'esES', '', 'Partimos ya. $n irá delante. El resto daremos apoyo y reconoceremos el terreno. Keeshan, eso te incluye a ti.', 28153),
(157679, 'esES', '', 'Si rescatamos a los tortolianos, podríamos obtener información sobre los movimientos de la Horda, lo que debería llevarnos hasta la capitana Areiel.', 28153),
(157678, 'esES', 'Señora. Hay tortolianos en Nazmir y, según nuestros informes, conocen los movimientos de la Horda. Los trols de sangre han capturado a varios de ellos.', '', 28153),
(157677, 'esES', '¡Pan comido!', '¡El pez grande se come al chico!', 28153),
(157676, 'esES', '¡En el blanco! Bueno, ¡en el pez!', '¡En el blanco! Bueno, ¡en el pez!', 28153),
(157675, 'esES', '', 'Necesitamos información y aliados en Nazmir para conseguirlo. Por suerte, tenemos una oportunidad. ¿Keeshan?', 28153),
(157674, 'esES', '', 'La muerte de la capitana Areiel paralizará las operaciones de la Horda en Nazmir y debilitará a las forestales oscuras de Sylvanas.', 28153),
(157673, 'esES', '¡Esos trols llevan demasiado tiempo haciendo daño a mis hijos! Ahora soy yo quien les da caza.', '', 28153),
(157672, 'esES', '¿Ribera Inerte no estaba en la otra dirección?', '', 28153),
(157671, 'esES', '', 'Esto ha estado muy tranquilo desde que Nedly desapareció.', 28153),
(157670, 'esES', 'No podemos permitirlo. Reúne a tus aliados, adalid. ¡Stromgarde pertenece a la Alianza!', '', 28153),
(157669, 'esES', 'Pero la Horda está reuniendo a sus tropas para hacerse con su control. Si tienen éxito, obtendrán una posición estratégica muy importante en los Reinos del Este. ', '', 28153),
(157668, 'esES', 'Stromgarde era una sede de poder fundamental para la Alianza en los días de Lordaeron. Y queremos que vuelva a serlo.', '', 28153),
(157667, 'esES', 'Organiza una expedición para conseguir esa azerita antes de que la consiga la Horda.', '', 28153),
(157666, 'esES', 'Los exploradores de Shaw han descubierto depósitos de azerita en varias islas. La Alianza necesita ese recurso, adalid.', '', 28153),
(157665, 'esES', 'Los agentes que reclutéis se encargarán de interferir en los planes de la Horda... y se asegurarán de que obtengamos la victoria.', '', 28153),
(157664, 'esES', 'Ayuda a Mathias Shaw a reunir a un equipo de operativos especiales. No se me ocurre mejor espía para esta misión.', '', 28153),
(157663, 'esES', 'Para ganar esta guerra hace falta fuerza, pero a veces es necesario optar por una estrategia más... sutil.', '', 28153),
(157662, 'esES', 'Estoy listo para invocar a Krag\'wa.', 'Estoy lista para invocar a Krag\'wa.', 28153),
(157661, 'esES', '', 'Zelling habla con su familia. Quédate atrás, ya veremos si me hace falta intervenir.', 28153),
(157660, 'esES', '', 'Aprovecha su sigilo y su astucia para descubrir los puntos débiles de las defensas enemigas... y explótalos.', 28153),
(157659, 'esES', '', 'Ayuda a Garona Semiorco a crear un grupo con los operativos más astutos y taimados de la Horda. Esta unidad se encargará de realizar misiones encubiertas en Kul Tiras y Zandalar.', 28153),
(157658, 'esES', '', 'Para asegurarme de que tenéis éxito, enviaré a alguien con ciertas... habilidades especiales para que os ayude. Creo que os resultará bastante útil.', 28153),
(157657, 'esES', '', 'Debéis actuar con presteza. Ocultaos en la oscuridad de la noche mientras buscáis los restos. Esas aguas están llenas de patrullas de la Alianza.', 28153),
(157656, 'esES', '', 'Nathanos, la conversión del hermano Zelling ya está dando resultados. Ha revelado la ubicación del barco naufragado que buscamos.', 28153),
(157655, 'esES', '', 'El niño rey ha enviado a sus subordinados para recuperarla, pero no podemos permitirlo.', 28153),
(157654, 'esES', '', 'Stromgarde era una sede de poder clave para la Alianza en los Reinos del Este... hasta que se convirtió en ruinas.', 28153),
(157653, 'esES', '', 'Debemos aprovechar esta ventaja. Explora las islas y conquístalas... antes de que lo haga la Alianza.', 28153),
(157652, 'esES', '', 'Nuestros aliados goblins han vuelto a demostrar su utilidad. Han encontrado depósitos de azerita en varias islas repartidas por el ancho mar.', 28153),
(157651, 'esES', '', 'En la guerra, hay momentos en los que un simple filo en la espalda correcta inflige más daño que mil espadas en el campo de batalla.', 28153),
(157650, 'esES', '', '¡Ese maldito Mildenhall está loco! Por lo visto sus experimentos han infestado la granja de hidromiel. Ve allí antes de que reine el caos.', 28153),
(157649, 'esES', '', 'Os doy las gracias a ti y a tu Horda por ayudar a liberar a mi tripulación.\n\n¡Mientras yo esté al mando, los Velaniebla serán libres de surcar los mares!', 28153),
(157648, 'esES', '', 'Él era el último sacrificio. Hemoh fracasado.', 28153),
(157647, 'esES', 'No... ¡Imposible!', '', 28153),
(157646, 'esES', '¡Pero lo haréih!', '', 28153),
(157645, 'esES', '¿Sufrimiento? No conocéih el auténtico sufrimiento. Aún no...', '', 28153),
(157644, 'esES', 'Taelia, cuando tengas tiempo, te invito a venir a Ventormenta. Puedo contarte muchas historias sobre tu padre.', '', 28153),
(157643, 'esES', '', 'Las cartas dejaron de llegar. Tengo... tantas preguntas...', 28153),
(157642, 'esES', '', 'Dale una muerte rápida. Ya hemoh vihto suficiente sufrimiento por hoy.', 28153),
(157641, 'esES', '', '\"Mi brillante estrella\".', 28153),
(157640, 'esES', 'Ahora me acuerdo... Solía escribirte cartas. Tenía un nombre especial para ti...', '', 28153),
(157639, 'esES', 'El alto señor Bolvar era un gran hombre. Un auténtico héroe para la Alianza... y para mí.', '', 28153),
(157638, 'esES', '', '¿Conocías a mi padre?', 28153),
(157637, 'esES', '<Jakra\'zet gime>.', '', 28153),
(157636, 'esES', 'Taelia... Levántate, por favor. El honor es mío.', '', 28153),
(157635, 'esES', '', 'La hija de Bolvar. Ha estado bajo nuestra protección desde la Tercera Guerra.', 28153),
(157634, 'esES', '¡¿Fordragón?!', '', 28153),
(157633, 'esES', '', 'Taelia Fordragón.', 28153),
(157632, 'esES', '', 'Es un honor conocerte, rey Wrynn. Soy Taelia.', 28153),
(157631, 'esES', '', 'Junto a tu adalid, ha jugado un papel fundamental en la salvación de tu reino... y de mi vida.', 28153),
(157630, 'esES', '', 'Rey Wrynn, hay alguien a quien deberías conocer.', 28153),
(157629, 'esES', 'Es un honor para mí volver a recibir a Kul Tiras en la Alianza. Que la Luz nos guíe hasta la victoria.', '', 28153),
(157628, 'esES', '', 'Gracias a todos... Haré todo lo posible para no defraudaros.', 28153),
(157627, 'esES', '', '¿Qué me decís?', 28153),
(157626, 'esES', '', 'Se acabó, General. Se acabaron lah mentirah, lah conhpiracioneh y loh asesinatoh.', 28153),
(157625, 'esES', '', '¡Sam, no!', 28153),
(157624, 'esES', '¡CANTO TORMENTA!', '', 28153),
(157623, 'esES', 'Tú mismo has propiciado tu fin, Pike. Debo entregar la flota a nuestra gloriosa salvadora: Azshara.', '', 28153),
(157622, 'esES', 'No veo más que almas perdidas que ansían ser liberadas.', '', 28153),
(157621, 'esES', '¡Se acabó, Canto Tormenta! Mira a tu alrededor... ¡Estás rodeado!', '', 28153),
(157620, 'esES', 'Está claro que sabes lo que haces. ¡Siempre puedo contar contigo para desatar el caos!', '', 28153),
(157619, 'esES', 'No tenemos muchas armas, así que habrá que ingeniárselas. Encuentra el modo de darles donde más duele y salir antes de que puedan reaccionar.', '', 28153),
(157618, 'esES', '', '¿Quién sabe el daño que podría haber causado a la flota esa cosa? Gracias a ti, nunca lo descubriremos.', 28153),
(157617, 'esES', '', 'Eres demasiado débil para gobernar, Katherine.', 28153),
(157616, 'esES', '', 'Y yo casi... Priscilla... ¿Cómo has podido traicionar al reino? ¿Traicionarme a mí?', 28153),
(157615, 'esES', '', '¡Ese gólem podría partir una nave por la mitad! No podemos permitir que lord Canto Tormenta tenga un arma de esa magnitud.', 28153),
(157614, 'esES', '', 'Contrataste a la flota pirata, los armaste hasta los dientes y los lanzaste contra tus propios compatriotas.', 28153),
(157613, 'esES', '', 'Se llama azerita... Y la Alianza y la Horda están en guerra por este material.', 28153),
(157612, 'esES', '', '¡Tu compañía fabricó las armas que destruyeron la Puerta de Daelin usando esto!', 28153),
(157611, 'esES', '', 'Lady Priscilla Gobernalle, quedas detenida por traficar y conspirar con piratas, y por traición contra el Almirantazgo de Kul Tiras.', 28153),
(157610, 'esES', 'El océano nos da mucho, pero bajo su superficie no hay más que desesperación.', '', 28153),
(157609, 'esES', '', '¡¿Qué significa esto, chica?!', 28153),
(157608, 'esES', '', 'Así que este era tu plan desde el principio. Infame.', 28153),
(157607, 'esES', '', '¡Miente!', 28153),
(157606, 'esES', 'Se ha manifestado un antiguo horror de las profundidades. Hazlo volver bajo las olas.', '', 28153),
(157605, 'esES', '', 'Lady Gobernalle ha sido un gran apoyo para mí desde los días oscuros en que ambas perdimos a nuestros maridos. Ahora será un apoyo para todo el reino. Ahora... ella...', 28153),
(157603, 'esES', '', 'Pero no ha sido suficiente.', 28153),
(157602, 'esES', '', '¡Buen golpe! Nuestras tropas lucharán en tierra firme un día más.', 28153),
(157601, 'esES', 'La última vez que vi tanto humo, la vieja abuela Davenport le estaba enseñando a cocinar al espeso de su nieto. ¡Buen trabajo!', '', 28153),
(157600, 'esES', '', '¡Qué osadía!', 28153),
(157599, 'esES', '', '¡Los nagas han traído una máquina de asedio viva para destruir el dique! ¡A las armas!', 28153),
(157598, 'esES', '¡¿Piratas?! ¡Los Valiente ya no pueden ni protegernos de los piratas!', '', 28153),
(157597, 'esES', '', 'Una flota pirata atacó la puerta con una fuerza abrumadora...', 28153),
(157596, 'esES', 'La furia de la tormenta es impredecible y peligrosa, pero no es rival para tus talentos.', '', 28153),
(157595, 'esES', 'Esto lleva el sello de la magia Sabiomar. ¡Haz lo que debas para contenerla!', '', 28153),
(157594, 'esES', 'Parece que estamos diezmando sus efectivos, pero reconstruyen más rápido de lo que destruimos. ¡Tenemos que reducir sus suministros de madera! ¡Quémala toda!', '', 28153),
(157593, 'esES', '', 'Los rumores son ciertos. La Puerta de Daelin... ha caído.', 28153),
(157592, 'esES', '¡Menudas explosiones! ¿Has dejado algo, aparte de un montón de escombros?', '', 28153),
(157591, 'esES', '', '¡La cosecha está a salvo gracias a ti! ¡A ver si podemos llevar a esos malandrines lejos de los cultivos!', 28153),
(157590, 'esES', '', 'Sabía que el esfuerzo merecería la pena. ¡Es una suerte contar con ella!', 28153),
(157589, 'esES', '', 'Algo se está comiendo las semillas de los granjeros locales antes de que germinen. ¡A ver si averiguas qué es!', 28153),
(157588, 'esES', '', 'La señorita Davenport solicita que le entreguemos algunos objetos para ayudarnos en la batalla. Esa vieja dama es dura de pelar. ¡Sería una locura no ayudarla!', 28153),
(157587, 'esES', 'Acabaremos con su corrupción tantas veces como haga falta, hasta que el Altar de la Tormenta quede purificado.', '', 28153),
(157586, 'esES', 'Esos demonios pretenden profanar nuestro suelo sagrado. ¡Es intolerable!', '', 28153),
(157585, 'esES', '', 'Sé que la exterminación de plagas no es la más glamurosa de las tareas, pero seguro que la gente de Muelerroca lo agradece.', 28153),
(157584, 'esES', '', 'Los residentes de Muelerroca han sufrido todo tipo de infortunios. Sus reservas de comida están infestadas de alimañas. Venga, vamos a purgarlas.', 28153),
(157583, 'esES', 'Algún día, aquí volverá a reinar el alegre sonido de los hechizos de los aprendices Sabiomar, aunque no será hoy...', '', 28153),
(157582, 'esES', '', 'Esperemos que eso haga volver al resto de esos malditos gigantes a las montañas, ¡de donde no debieron salir!', 28153),
(157581, 'esES', 'Los tentáculos de mi antiguo maestro aún llegan lejos. No dejes rastro de ellos.', '', 28153),
(157580, 'esES', 'Gracias. La gente del valle nunca olvidará tus hazañas.', '', 28153),
(157579, 'esES', '', 'Los ettins han estado aterrorizando a los civiles en la Aldea Muelerroca. No pueden defenderse solos. ¡Somos su única esperanza!', 28153),
(157578, 'esES', 'Te necesitamos en Brennadam. Aún no tenemos suficientes tropas para lanzar un contraataque solos.', '', 28153),
(157577, 'esES', 'Habla con la capitana Angelica cuando quieras embarcar.', '', 28153),
(157576, 'esES', '', 'Perdón, debí preguntarte si tenías alergia a las abejas antes de mandarte ahí. Pero parece que estás bien, ¡así que ya sé a quién llamar la próxima vez!', 28153),
(157575, 'esES', 'Gracias por la rapidez de tu informe, adalid. Embarcarás con la Tercera Flota.', '', 28153),
(157574, 'esES', 'No podemos permitir que semejante maldad prospere en nuestro mundo.', '', 28153),
(157573, 'esES', '', 'Las abejas de la granja de hidromiel están aterrorizando a los lugareños. La situación se les ha ido de las manos a los granjeros. ¡Qué sorpresa!', 28153),
(157572, 'esES', 'Me envía el rey Anduin, maestro de espías.', 'Me envía el rey Anduin, maestro de espías.', 28153),
(157571, 'esES', '', 'En esa granja ha pasado algo que ha sublevado a los wendigos. Antes de que esos chalados de los Mildenhall se instalaran allí, nunca dieron problemas.', 28153),
(157570, 'esES', '', 'Nos informan de que la Granja de Hidromiel Mildenhall tiene problemas con los wendigos. ¿Podrías ir a echar una mano?', 28153),
(157569, 'esES', 'Los K\'thir practican su magia oscura sin trabas en el Melodía Abisal. Purifica la corrupción de su cubierta.', '', 28153),
(157568, 'esES', 'Puede que nos superen en número, pero gracias a ti, no flaqueamos.', '', 28153),
(157567, 'esES', 'Los Sabiomar corruptos han esclavizado a marineros perdidos y amenazan con invadir Cruce de la Marea. ¡Detenlos!', '', 28153),
(157566, 'esES', '', 'Esa criatura debió ser un noble fungárico antaño. Qué destino tan aciago para un guerrero tan noble.', 28153),
(157565, 'esES', '', 'Nos llegan informes de una poderosa presencia en una cueva al sur. Ten cuidado. Lo que cuentan de esa criatura me pone los pelos de punta...', 28153),
(157564, 'esES', '', 'Buen trabajo, pero no creo que sea la última vez que tengamos que salvarle el pellejo.', 28153),
(157563, 'esES', 'Aún no hemos logrado expulsar a la Horda del paso. Paraliza su producción cueste lo que cueste. ¡Vuélalos por los aires si hace falta!', '', 28153),
(157562, 'esES', '', 'Las armas producidas en las fundiciones Canto Tormenta deberían servir para proteger a la gente, no para oprimirla.', 28153),
(157561, 'esES', 'Puede que sea una tarea sencilla, dado tu historial, pero es algo que debe hacerse.', '', 28153),
(157560, 'esES', 'La Residencia Kennings lleva retraso en las órdenes del almirantazgo debido a ciertas... complicaciones. No debería resultarte muy difícil ayudar.', '', 28153),
(157559, 'esES', '', 'Sería una lástima desperdiciar toda esa munición. Ya sabes qué hacer.', 28153),
(157558, 'esES', 'Nos corresponde a nosotros tenerlos controlados ahora que se ha ido la milicia.', '', 28153),
(157557, 'esES', 'Los jabaespines traman algo en su horado. ¡Frustra sus planes antes de que se hagan más fuertes!', '', 28153),
(157556, 'esES', 'Nura, he venido a ayudar.', 'Nura, he venido a ayudar.', 28153),
(157555, 'esES', '', '¿Qué te trae hasta aquí?', 28153),
(157554, 'esES', '¡Nos veremos luego en la ciudad y nos repartiremos esto!', '', 28153),
(157553, 'esES', '¿Puedes acercarme a La Carretera en Los Baldíos del Sur?', '¿Puedes acercarme a La Carretera en Los Baldíos del Sur?', 28153),
(157552, 'esES', 'Un barco sin velas es como una caballería sin caballos. Vamos... que no sirve para nada.', '', 28153),
(157551, 'esES', 'Una tormenta temible amenaza nuestras provisiones de jarcias. ¡Aplácala lo antes posible!', '', 28153),
(157550, 'esES', 'Hoy has honrado el legado de Addington. Gracias.', '', 28153),
(157549, 'esES', 'El hermano Addington jamás habría tolerado semejante depravación. ¡Reclama el terreno en su nombre!', '', 28153),
(157548, 'esES', '', 'Todo empieza con la materia prima. El resto se consigue con trabajo duro y corazones leales.', 28153),
(157547, 'esES', '', 'Los armadores de Canto Tormenta son legendarios, pero necesitan madera para trabajar. ¡Restaura el orden!', 28153),
(157546, 'esES', '', 'Así aprenderán. ¡Canto Tormenta siempre estará abierto a todos!', 28153),
(157545, 'esES', '', '¡Las tropas de lord Canto Tormenta han levantado otra barricada! ¡Derríbala para que estos comerciantes puedan pasar!', 28153),
(157544, 'esES', '¡Vamos, démonos prisa!', '', 28153),
(157543, 'esES', 'Habla con Isabella; se asegurará de que llegues bien al punto de encuentro de Entrañas.', '', 28153),
(157542, 'esES', 'Cuando tengamos refuerzos suficientes, te diré lo que tienes que hacer.', '', 28153),
(157541, 'esES', 'Gracias por tu pronta respuesta, adalid. No hay tiempo que perder.', '', 28153),
(157540, 'esES', 'Proteger, amparar y guiar. Esa es la verdadera senda de los Sabiomar.', '', 28153),
(157539, 'esES', 'Los Sabiomar hacen votos sagrados para proteger a nuestra gente. ¡Hónralos y ayuda a estas almas pesarosas!', '', 28153),
(157538, 'esES', 'Nuestros enemigos son implacables. Pero, gracias a ti, vivimos para luchar otro día.', '', 28153),
(157537, 'esES', 'Parece que el ritual se ha frustrado sin incidentes. No podemos permitir que la magia vil de los nagas siga corrompiendo el mar.', '', 28153),
(157536, 'esES', 'Los seguidores de Azshara intentan llevar a cabo un nuevo ritual tras su reciente derrota. Mándalos a las profundidades que tanto veneran.', '', 28153),
(157535, 'esES', '', 'Parece que los nagas se vuelven más agresivos cada día que pasa. Me preocupa que pueda afectarnos.', 28153),
(157534, 'esES', '', 'El Despertar de la Tormenta aún se está recuperando del ataque naga. ¡Ayúdalos a defenderse mientras retoman el control!', 28153),
(157533, 'esES', 'A nuestras tropas les vendrían muy bien esos suministros. ¡Consíguelos para nuestra causa!', '', 28153),
(157532, 'esES', 'Que la marea te bendiga. ¡No tomarán este valle mientras resistamos!', '', 28153),
(157531, 'esES', 'Hay una primera vez para todo. Esperemos que no haya una segunda, al menos para esto.', '', 28153),
(157530, 'esES', 'No sé muy bien qué significa esto, pero está ocurriendo algo muy extraño en la ciudad. A ver si puedes encargarte.', '', 28153),
(157529, 'esES', '', 'Si te aíslas de tus sentimientos, solo te queda la oscuridad.', 28153),
(157528, 'esES', '', 'Mi querida Jaina... No puedes basar todas tus decisiones solo en la lógica.', 28153),
(157527, 'esES', '', '¡No es real, Jaina! ¡Nada de esto lo es!', 28153),
(157526, 'esES', '', 'Pero... me mintieron...', 28153),
(157525, 'esES', '¡Fui un estúpido al pensar que podrías ser nuestra líder!', '', 28153),
(157524, 'esES', '¡Permitiste que tus prejuicios corrompieran el Kirin Tor!', '', 28153),
(157523, 'esES', '', 'Ojalá tu padre hubiera aprendido esa lección.', 28153),
(157522, 'esES', '', 'Intentar poner fin a una matanza es un propósito noble, Jaina.', 28153),
(157521, 'esES', 'El ejército de lord Canto Tormenta amenaza con conquistar esta zona. ¡Asegúrate de que no caiga en sus manos!', '', 28153),
(157520, 'esES', '', '¡Aléjate de ella!', 28153),
(157519, 'esES', 'Hir\'eek eh el loa de la noche. No necesitah saber nada máh.', 'Hir\'eek eh el loa de la noche. No necesitah saber nada máh.', 28153),
(157518, 'esES', '', 'Todo por mi culpa...', 28153),
(157517, 'esES', 'Pero tú... Tú detuviste mi hoja. ¿Cuántos soldados de la Alianza murieron aquel día? ¿Y en las batallas que siguieron?', '', 28153),
(157516, 'esES', '¡Podría haber acabado con ellos! Sylvanas... Thrall... ¡Piensa en lo que podría haber sido de nuestro mundo sin ellos y sin su retorcida Horda!', '', 28153),
(157515, 'esES', '', 'No. Debe ser otra de esas criaturas que están atormentando a Jaina. ¡Rápido!', 28153),
(157514, 'esES', '', 'Esa voz... ¡¿Daelin?!', 28153),
(157513, 'esES', '', '¿Otra ilusión? Jaina debe seguir atrapada cerca de aquí.', 28153),
(157512, 'esES', '', 'La encontraremos... Y la sacaremos de este lugar maldito.', 28153),
(157511, 'esES', '', 'Mi hija está por aquí, oculta en algún lugar. Sufriendo.', 28153),
(157510, 'esES', '¡Bien hecho! La marea llevará el cantar de tus hazañas durante años.', '', 28153),
(157509, 'esES', '', 'Debemos seguir buscando.', 28153),
(157508, 'esES', '', 'Ha desaparecido. Tan solo era un reflejo... un eco del sufrimiento de Jaina.', 28153),
(157507, 'esES', '', '... pero ni los más fuertes consiguen salvar a todo el mundo.', 28153),
(157506, 'esES', '', 'Jaina... eras... eres el orgullo de Kul Tiras: su poder y su furia...', 28153),
(157505, 'esES', '', '¡No! ¡No les hagas caso, Jaina!', 28153),
(157504, 'esES', '', 'Les fallé... a todos...', 28153),
(157503, 'esES', '', '¡Podrías haberlo detenido! ¡Podrías habernos salvado!', 28153),
(157502, 'esES', 'A tu servicio, Alto Señor Supremo.', 'A tu servicio, Alto Señor Supremo.', 28153),
(157501, 'esES', 'El Despertar de la Tormenta necesita tu ayuda una vez más. Que las mareas te guíen hacia la victoria.', '', 28153),
(157500, 'esES', '¡Nos abandonaste!', '', 28153),
(157499, 'esES', '', 'Te sigo, adalid.', 28153),
(157498, 'esES', '', 'Y yo siempre conseguía encontrarla... No voy a fallarle ahora.', 28153),
(157497, 'esES', '', 'Cuando Jaina era pequeña, se escondía siempre que estaba asustada o disgustada.', 28153),
(157496, 'esES', '', '¡Espera!', 28153),
(157495, 'esES', '', '¡No! ¡No puedes ayudarme! ¡Nadie puede ayudarme!', 28153),
(157494, 'esES', '', 'No pasa nada, cariño...', 28153),
(157493, 'esES', '', 'Jaina está ahí delante. ¡Vamos, rápido!', 28153),
(157492, 'esES', 'Thros... os consumirá...', '', 28153),
(157491, 'esES', '', '¡No si yo tengo algo que decir al respecto!', 28153),
(157490, 'esES', '¡La hija de Valiente es nuestra!', '', 28153),
(157489, 'esES', '', 'Adalid, ¡debemos seguirla!', 28153),
(157488, 'esES', '', 'Jaina, ¡espera!', 28153),
(157487, 'esES', '', '¡No! ¡Vete!', 28153),
(157486, 'esES', '', '¡¿Jaina?!', 28153),
(157485, 'esES', '', 'Todo es... culpa mía...', 28153),
(157484, 'esES', '', 'Las Tierras Contagiadas... Este lugar hace honor a su nombre...', 28153),
(157483, 'esES', 'Que las mareas te bendigan. Nuestro valle vuelve a estar a salvo.', '', 28153),
(157482, 'esES', 'Por las profundidades abisales... ¡No podemos permitir que esta aberración siga amenazando a nuestra gente!', '', 28153),
(157481, 'esES', 'Que esto sirva de lección para todo el que ose blandir los dones de la madre de las mareas.', '', 28153),
(157480, 'esES', 'Hay que poner fin a semejante ultraje al poder del mar.', '', 28153),
(157479, 'esES', 'Torga es un ser poderoso que ha perdido mucha de su fuerza, pero los tortolianos mantenemos vivo su recuerdo.', '', 28153),
(157478, 'esES', 'Paremos aquí un momento, $p.', '', 28153),
(157477, 'esES', 'Gral eh un loa sabio, ve lah cosah con perhpectiva. El mar profundo eh su reino y el océano máh ohcuro, su dominio.', 'Gral eh un loa sabio, ve lah cosah con perhpectiva. El mar profundo eh su reino y el océano máh ohcuro, su dominio.', 28153),
(157476, 'esES', 'Que las mareas renieguen de ellos, como ellos renegaron de su gente.', '', 28153),
(157475, 'esES', '¡Nos has quitado unas cuantas espinas que teníamos clavadas! Buen trabajo.', '', 28153),
(157474, 'esES', 'Los jabaespines traman algo en la granja que hay junto a su horado. ¿Por qué no vas a echar un ojo a ver si puedes frustrar sus planes?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'esES', 'Otra alma perversa ha respondido a la llamada de lord Canto Tormenta. ¡Que no arruinen nuestros logros!', '', 28153),
(157472, 'esES', 'Descansa, alma desdichada. Ya no sufrirás más.', '', 28153),
(157471, 'esES', 'Qué horrores han creado mis hermanos... Acaba con su sufrimiento.', '', 28153),
(157470, 'esES', 'Allá voy...', 'Allá voy...', 28153),
(157469, 'esES', 'Sí... mi sheñor.', 'Sí... mi sheñor.', 28153),
(157468, 'esES', '¡¿Qué pasha?!', '¡¿Qué pasha?!', 28153),
(157467, 'esES', '¡Entonces allá voy!', '¡Puesh allá voy!', 28153),
(157466, 'esES', '¿Másh trabajo?', '¿Másh trabajo?', 28153),
(157465, 'esES', '', '¡Estoy en ello, jefe!', 28153),
(157464, 'esES', 'SÍ que veo otra pequeña excavación al oeste de aquí. ¿Kelsey?', '', 28153),
(157463, 'esES', 'Resistid. ¡No hemos llegado hasta aquí para fracasar ahora!', '', 28153),
(157462, 'esES', 'Las mayores excavaciones del Relicario están más hacia el sur. Como sospechaba.', '', 28153),
(157461, 'esES', '¡La Horda ha prendido fuego a los edificios! ¡Apaga las llamas antes de que devoren todo el valle!', '', 28153),
(157460, 'esES', '¡Buen trabajo! Las llamas menguan y nuestros hogares están a salvo. Gracias.', '', 28153),
(157459, 'esES', 'Me aseguraré de que los sethrak no tengan ni su propio botín cuando se vayan de aquí.', 'Me aseguraré de que los sethrak no tengan ni su propio botín cuando se vayan de aquí.', 28153),
(157458, 'esES', 'Aunque no puedo hacer que los marinos regresen, al menos sabemos que nuestros barcos están ahí fuera... en algún lugar. Ahora el destino de nuestra flota depende de los Valiente.', '', 28153),
(157457, 'esES', 'Jani eh el loa de lah cosah abandonadah y de la gente que otroh abandonan o ignoran. Él cuida de huérfanoh como yo o de cualquiera que ehté pasando por un mal momento.', '', 28153),
(157456, 'esES', 'Aquí mi magia es más fuerte. Si hay alguna esperanza de encontrar a la flota, este es el momento de intentarlo.', '', 28153),
(157455, 'esES', 'Eeh... Vete... <¡hip!> Estoy ocupado.', '', 28153),
(157454, 'esES', 'Somoh seguidoreh de Torcali, la Montaña que Anda, el Baluarte Errante. Si nuehtro loa lo quiere, nada atravesará nuehtroh ehcudoh.', '', 28153),
(157453, 'esES', '', '¡Una amenaza menos en el valle! ¡Buen trabajo!', 28153),
(157452, 'esES', '', 'Hala... No sé qué decir. ¡Qué batalla tan espectacular!', 28153),
(157451, 'esES', 'Espera aquí. Creo que veo algo.', '', 28153),
(157450, 'esES', 'La verdad es que no confiaba nada en el plan, ¡pero ese oro ayudará a mucha gente a rehacer sus vidas!', '', 28153),
(157449, 'esES', 'Sí... percibo los barcos... ¡nuestra flota! ¡La niebla oscura que la rodea se está disipando!', '', 28153),
(157448, 'esES', 'He venido para resolver tus problemas, Krog.', 'He venido para resolver tus problemas, Krog.', 28153),
(157447, 'esES', '', 'El Despertar de la Tormenta nos ha informado de la presencia de una bestia peligrosa. ¡Encárgate!', 28153),
(157446, 'esES', '', 'Algo peligroso acecha en las colinas. ¡Encuéntralo antes de que alguien salga herido!', 28153),
(157445, 'esES', 'Los cazatesoros de Ribera Inerte van a donar oro para ayudar a reconstruir Brennadam. ¡El problema es que tenemos que recogerlo nosotros!', '', 28153),
(157444, 'esES', 'Arthur...', '', 28153),
(157443, 'esES', 'Doras, necesito un jinete del viento para ir al Poblado Murohelecho.', 'Doras, necesito un jinete del viento para ir al Poblado Murohelecho.', 28153),
(157442, 'esES', '', 'Bien hecho. Al salvar a Ai\'twen, hah ayudado a loh tortolianoh... y complacido a loh loa, en mi opinión.', 28153),
(157441, 'esES', '¡Oye, que he derribado piedras! Unas muy enfadadas.', '', 28153),
(157440, 'esES', 'Tenías órdenes de derribar hitos.', '', 28153),
(157439, 'esES', '¡Ah, venga ya! Todo ha salido bien al final. ¡$gEl:La; continental y yo hemos acabado con el gran monstruo de roca y hemos sobrevivido! Eso es una victoria.', '', 28153),
(157438, 'esES', '¡Arthur! ¿Qué te tengo dicho de meterte en problemas sin pensar?', '', 28153),
(157437, 'esES', '', 'Loh tortolianoh veneran a la gran tortuga Ai\'twen, un aliado poderoso de su pasado. Mantenlo a salvo y bien alimentado pa que pueda ayudarnoh.', 28153),
(157436, 'esES', '¡Abandona este lugar!', '', 28153),
(157435, 'esES', '¡Que las corrientes favorables te guíen! Tus actos son un ejemplo para todos.', '', 28153),
(157434, 'esES', 'Seguiremos hacia el sur, entonces. Estaremos en contacto, Guzbert.', '', 28153),
(157433, 'esES', '¡Tú puedes, Guzzy!', '', 28153),
(157432, 'esES', '', '¡A por ellos, Guzbert!', 28153),
(157431, 'esES', '... ¡con un MONTÓN DE BOMBAS!', '', 28153),
(157430, 'esES', 'Una pequeña excavación, ¿eh? Parece un trabajo para un gnomo...', '', 28153),
(157429, 'esES', 'Hay una pequeña excavación del Relicario a medio kilómetro al este de aquí.', '', 28153),
(157428, 'esES', '¡$n, detrás de ti! ¡Ayúdame a quitar de en medio estas molestias!', '', 28153),
(157427, 'esES', 'La tortuga ancestral Ai\'twen es un misterio marino que hay que proteger. Ayuda a los tortolianos a mantenerla a salvo y bien alimentada.', '', 28153),
(157426, 'esES', 'Haremos que lord Canto Tormenta pague por sus transgresiones... o moriremos en el intento.', '', 28153),
(157425, 'esES', 'La gente de Canto Tormenta merece sentirse a salvo. No tengas piedad con los que amenazan su seguridad.', '', 28153),
(157424, 'esES', 'Debemos actuar ahora si queremos salvar a nuestra flota de las garras de Azshara.', '', 28153),
(157423, 'esES', 'Este lugar no es seguro. Ven, hay un viejo puesto de vigilancia sobre el santuario cercano.', '', 28153),
(157422, 'esES', 'Pero no lo olvidaremos... Mientras vivamos.', '', 28153),
(157421, 'esES', 'La voz ahora es un eco de la tuya. Sientes que busca una respuesta, porque tú también la buscas.\n\n\"¿Con qué fin?\".', '', 28153),
(157420, 'esES', 'Te encoges de dolor cuando la voz grita en tu interior.\n\n\"¿Dónde comenzó?\".', '', 28153),
(157419, 'esES', 'Te doy las gracias. Los granjeros deberían poder volver pronto a sus campos.', '', 28153),
(157418, 'esES', 'Me han informado de que las granjas periféricas están en peligro. ¡Ayúdalos a restaurar el orden en el valle!', '', 28153),
(157417, 'esES', 'La voz se vuelve más fuerte y más ansiosa.\n\n\"¡Más! ¡Más! ¡Más!\".', '', 28153),
(157416, 'esES', 'Esa voz ancestral es solo un eco que te habla desde las profundidades de tu mente.\n\n\"¿Qué es lo que buscas?\".', '', 28153),
(157415, 'esES', '¡Eres una caja de sorpresas! Deberías enseñarme algunos trucos un día de estos.', '', 28153),
(157414, 'esES', 'Buen trabajo. Si necesitas que te saquen de Boralus, tenemos agentes cerca de ti.', '', 28153),
(157413, 'esES', 'Voy a volver para contárselo a Sotoabedul. ¡Nos vemos allí!', '', 28153),
(157412, 'esES', '¡JA! ¡Se derrumbó ante nuestro poder!', '', 28153),
(157411, 'esES', '', 'Sam... lo... lo hemos perdido...', 28153),
(157410, 'esES', 'Cuando el último de sus súbditos haya muerto y se haya alzado como Renegado, el niño rey se arrodillará ante la Dama Oscura. Y por fin tendremos una reina para gobernarlos a todos.', '', 28153),
(157409, 'esES', 'Venganza. Desdén. Llámalo como quieras.', '', 28153),
(157408, 'esES', '', 'Tu motivación es la venganza. Lo comprendo bien.', 28153),
(157407, 'esES', 'Cuando nos liberamos del control del Rey Exánime, Sylvanas buscó aliados. En vez de aceptar a sus hermanos caídos de Lordaeron, los humanos nos rechazaron. Nos persiguieron. Así que juré darles caza.', '', 28153),
(157406, 'esES', '', '¿A qué te refieres?', 28153),
(157405, 'esES', 'En otro tiempo luché por su causa, pero la arrogancia insufrible de la Alianza se ha multiplicado desde que nos dieron la espalda.', '', 28153),
(157404, 'esES', '', 'Parece que la pasión con la que atacas a la Alianza responde a algo más que a la mera obediencia a tu Reina, Clamañublo.', 28153),
(157403, 'esES', '', 'Yo provoqué la caída de un rey. Puede que sea el momento de acabar con el reino de otro.', 28153),
(157402, 'esES', 'Bien. La Alianza no merece compasión ni tregua. Hazlos sufrir y la Dama Oscura te recompensará.', '', 28153),
(157401, 'esES', '', 'No. Y sin duda sabrás que he colaborado con la Alianza cuando me ha convenido. Pero no les debo nada. La Horda es mi hogar.', 28153),
(157400, 'esES', 'Qué insensatos sois...', '', 28153),
(157399, 'esES', '¡En nombre de Kul Tiras, debes abandonar este lugar!', '', 28153),
(157398, 'esES', 'Conozco la historia, pero también sé que no fue decisión tuya matar a Llane Wrynn.', '', 28153),
(157397, 'esES', '', '¿Solo porque fui amiga del abuelo del joven Rey? Lo maté, por si no te acuerdas.', 28153),
(157396, 'esES', 'Tus ataques contra objetivos de la Alianza han sido impresionantes, Garona. Admito que pensaba que tu lealtad podía estar... dividida.', '', 28153),
(157395, 'esES', 'Je, je, je... ¡Carne fresca!', '', 28153),
(157394, 'esES', '¡Siente la cólera de la naturaleza!', '', 28153),
(157393, 'esES', '¡Te voy a convertir en escombros!', '', 28153),
(157392, 'esES', '¿Seguro que quieres continuar?', '¿Seguro que quieres continuar?', 28153),
(157391, 'esES', 'Buen trabajo. El Valle Canto Tormenta estará eternamente en deuda contigo.', '', 28153),
(157390, 'esES', 'Sueña, sueña con la Ciudad Sumergida.', 'Sueña, sueña con la Ciudad Sumergida.', 28153),
(157389, 'esES', 'Encontrándote en la sombra de la mirada de Él...', 'Encontrándote en la sombra de la mirada de Él...', 28153),
(157388, 'esES', 'Perdiéndote en el implacable abrazo de Ella...', 'Perdiéndote en el implacable abrazo de Ella...', 28153),
(157387, 'esES', 'Para respirar la sabiduría de los ahogados...', 'Para respirar la sabiduría de los ahogados...', 28153),
(157386, 'esES', 'Los supervivientes de la Cabaña de las Colinas Aciagas llevan días luchando. A ver si puedes ayudarles y darles la oportunidad de descansar.', '', 28153),
(157383, 'esES', '¡Cuántas explosiones! Me alegra que ninguna os volara por los aires ni a ti ni a Toki.', '', 28153),
(157382, 'esES', 'Bebe la marea centelleante...', 'Bebe la marea centelleante...', 28153),
(157381, 'esES', 'Ventura y Cía. sigue destruyendo la costa de esta zona. Habla con Toki a ver si le puedes echar una mano.', '', 28153),
(157380, 'esES', 'Eh...', 'Eh...', 28153),
(157379, 'esES', 'Encuentras un altar agorero. Al poner tu mano sobre él, se te empieza a inundar la cabeza de palabras.\n\n\"¿Cómo comenzarás?\".', '', 28153),
(157378, 'esES', 'Buen trabajo. Te debo un trago por esto.', '', 28153),
(157377, 'esES', '¡Espera a que te ponga las garras encima!', '', 28153),
(157376, 'esES', '¡Te haré pedazos!', '', 28153),
(157375, 'esES', 'Quiero a los Marea de Hierro fuera de esta zona. A ver si tienen ganas de quedarse después de que hagamos sus vidas un poco más desagradables.', '', 28153),
(157374, 'esES', '¡Por Drustvar!', '', 28153),
(157373, 'esES', '¡Venga! ¡Convirtamos a ese monstruo en escombros!', '', 28153),
(157372, 'esES', '', 'Loh tortolianoh agradecen tu ayuda. Y yo también.', 28153),
(157371, 'esES', '', 'Esoh brutoh de Ventura y Cía. siguen hohtigando a loh tortolianoh. Reúnete con Toki y préhtale tu ayuda.', 28153),
(157370, 'esES', '', 'Nuehtroh enemigoh sabrán que ha sido la Horda quien ha fruhtrado suh planeh. Buen trabajo, adalid.', 28153),
(157369, 'esES', '', '¡Loh enemigoh cada vez son máh osadoh! Acaba con suh recursoh... y con suh vidah, si eh necesario.', 28153),
(157368, 'esES', '', 'Cada vez somoh máh fuerteh... y el enemigo se debilita. A veceh lah pequeñah victoriah conducen a un gran triunfo.', 28153),
(157367, 'esES', '', 'Loh soldadoh no pueden ganar una guerra con el ehtómago vacío; necesitan carne de oso. No dejeh que el enemigo interfiera.', 28153),
(157362, 'esES', 'Están despertando cosas antiguas que no deberían existir. No bajes la guardia.', 'Están despertando cosas antiguas que no deberían existir. No bajes la guardia.', 28153),
(157361, 'esES', '¡No nos esperábamos ver a los muertos vagando por ahí!', '¡No nos esperábamos que los muertos se levantaran y caminaran por ahí!', 28153),
(157360, 'esES', '¡No nos esperábamos un poder así! Ten cuidado, continental.', '¡No nos esperábamos un poder así! Ten cuidado, continental.', 28153),
(157359, 'esES', 'Los ensamblajes deben ser destruidos. ¡Ayúdanos, por favor!', 'Los ensamblajes deben ser destruidos. ¡Ayúdanos, por favor!', 28153),
(157358, 'esES', 'Una ayuda muy oportuna, continental.', 'Una ayuda muy oportuna, continental.', 28153),
(157357, 'esES', '$p, para. ¿Has visto eso?', '', 28153),
(157356, 'esES', 'Se han retirado, al menos de momento, y la ciudad sigue en pie. Te debemos la vida.', '', 28153),
(157355, 'esES', 'La Horda ha regresado con refuerzos para terminar el trabajo. ¡Haz lo que sea necesario para detenerlos!', '', 28153),
(157354, 'esES', 'Le gusta vivir apartado, pero sabe pedir ayuda cuando está en un aprieto. ¡Gracias por tu apoyo!', '', 28153),
(157353, 'esES', 'Campodorado dice que le vendría bien tu asistencia. Los asaltos a su granja no han cesado, y se está quedando sin suministros. Ayúdalo.', '', 28153),
(157352, 'esES', '¡La próxima vez se lo pensarán dos veces! Ráscale la tripa a ese perro de mi parte.', '', 28153),
(157351, 'esES', 'Los jabaespines están intentando expandir su red de túneles y están poniendo el valle en peligro. Nuestros canes podrían hacerlos salir, si supieran dónde buscar.', '', 28153),
(157350, 'esES', '$p, vamos.', '', 28153),
(157349, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t ¡Estás bajo los efectos de |cFFFF0000|Hspell:272536|h[Ruina inminente]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t ¡Estás bajo los efectos de |cFFFF0000|Hspell:272536|h[Ruina inminente]|h|r!', 28153),
(157348, 'esES', 'Ehta sería la sala ideal pa ehponer la colección real de antigüedadeh. Tal vez deberíamoh...', '', 28153),
(157347, 'esES', '', 'No estaré lejos.', 28153),
(157346, 'esES', 'Sé discreta, Shandris. Quédate en las sombras... si las encuentras.', '', 28153),
(157345, 'esES', '', '¡Entendido, Alto comandante! ¡Adelante!', 28153),
(157344, 'esES', 'Kelsey, serás nuestros ojos en el cielo. Avisa si ves algo.', '', 28153),
(157343, 'esES', '¿Puedes repetir el plan?', '¿Puedes repetir el plan?', 28153),
(157342, 'esES', 'Mis padres siempre decían que yo tenía mucha imaginación.', '', 28153),
(157341, 'esES', '¡A veces nos tirábamos colina abajo montados en una carreta! ¡Solíamos fingir que Hobbs era un tigre!', '', 28153),
(157340, 'esES', 'Hobbs y yo emprendíamos todo tipo de aventuras cuando éramos niños.', '', 28153),
(157339, 'esES', 'Muéstramelo.', 'Muéstramelo.', 28153),
(157338, 'esES', 'Las visiones pueden ayudarnos a observar la matanza, $r.', 'Las visiones pueden ayudarnos a observar la matanza, $r.', 28153),
(157337, 'esES', 'Pronto también la flota gozará de su fulgor, y todo Kul Tiras se inclinará ante la luz que surge bajo las mareas.', '', 28153),
(157336, 'esES', 'Estáis ciegos. Los dones de la madre de las mareas nos han hecho fuertes una vez más.', '', 28153),
(157335, 'esES', 'Almas de mis hermanos corruptos, vais a poder cumplir vuestros votos. ¡Derribad esta puerta!', '', 28153),
(157334, 'esES', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t ¡La anciana Leaxa comienza a lanzar |cFFF00000|Hspell:264603|h[Espejo de sangre]|h|r!', 28153),
(157333, 'esES', '', 'Esta cueva me da buenas sensaciones. Estoy imaginándome un montón de oro dentro.', 28153),
(157332, 'esES', '¡Pero si justo estaba llegando a la parte en que me lanzo de cabeza por su gaznate y lo rajo desde dentro!', '¡A ver, estaba llegando a la parte en la que me cuelo por su gaznate y la rajo desde dentro!', 28153),
(157331, 'esES', 'Vale, vale, Sedal y Escafandro me ayudaron. Pero el resto es verdad, ¡hasta la última palabra!', 'Vale, vale, Sedal y Escafandro me ayudaron. Pero el resto es verdad, ¡hasta la última palabra!', 28153),
(157330, 'esES', '¡Mm, mm, mm, mm, mm, mm!', 'Mm mm mm mm, ¡mm mm!', 28153),
(157329, 'esES', 'Cierra el pico, Sedal. ¡Espera tu turno!', '¡Cierra el pico, Sedal, y espera tu turno!', 28153),
(157328, 'esES', '', '¡No hay nada de oro, pero sí mucho ron!', 28153),
(157327, 'esES', 'Sí, ¡gracias a mis habilidades de pesca!', 'Sí, ¡gracias a mis habilidades de pesca!', 28153),
(157326, 'esES', 'Gracias a mi agudo ingenio, supe exactamente cómo acabar con la bestia.', 'Gracias a mi agudo genio, supe exactamente cómo acabar con ella.', 28153),
(157325, 'esES', 'Entonces la vi, acercándose desde el horizonte. ¡Nunca había visto una bestia igual!', 'Fue entonces cuando la vi acercarse por el horizonte: ¡una bestia como ninguna!', 28153),
(157324, 'esES', 'Me tocó la primera guardia, así que estuve vigilando por si aparecían más de esos malditos nagas.', 'Yo tenía el primer turno de guardia para vigilar a esos malditos nagas.', 28153),
(157323, 'esES', 'Ahora deja que te cuente cómo conocí a estos pobres marineros.', 'Deja que te cuente cómo conocí a estos dos pobres marineros.', 28153),
(157322, 'esES', 'Sí, yo también dudaría de... Eh, ¡un momento!', 'Sí, yo también dudaría de... Eh, ¡un momento!', 28153),
(157321, 'esES', 'Ese yelmo te está cortando el riego. ¡Antes me creería que Sedal hubiera pescado algo!', 'Ese yelmo te está cortando el riego. ¡Antes me creería que Sedal hubiera pescado algo!', 28153),
(157320, 'esES', 'Mm, mm, mm, mm, mm. Mm.', 'Mm, mm mm mm mm. Mm.', 28153),
(157319, 'esES', '¡MMM!', '¡MM!', 28153),
(157318, 'esES', 'Mm, mm... mm.', 'Mm, mm... mm.', 28153),
(157317, 'esES', 'Por suerte, llevaba la bala especial que me cuelgo al cuello para ocasiones como esta.', 'Por suerte, llevaba la bala especial que me cuelgo al cuello para ocasiones como esta.', 28153),
(157316, 'esES', 'Yo vigilo el ron hasta que vuelva el capitán.', '', 28153),
(157315, 'esES', 'Capitán... no he bebido nada.', '', 28153),
(157314, 'esES', '', '¡Donde hay piratas suele haber oro!', 28153),
(157313, 'esES', '', 'Algunos de los trabajadores dicen que han visto el fantasma de un pirata en las inmediaciones de esta cueva.', 28153),
(157312, 'esES', '', 'Brennadam está ahí delante. ¡Vamos!', 28153),
(157311, 'esES', '', 'Kul Tiras está expuesto sin ella. Solo es cuestión de tiempo que nos ataquen.', 28153),
(157310, 'esES', '', 'Tenemos que encontrar al hermano Pike de inmediato. Con suerte, podrá ayudarnos a traer a la flota de regreso a casa.', 28153),
(157309, 'esES', '', 'El valle es espléndido... No me extraña que tanta gente decida asentarse aquí.', 28153),
(157308, 'esES', '', 'Este es el único camino que lleva al valle. La casa Canto Tormenta trama algo.', 28153),
(157307, 'esES', '', 'Brennadam es el núcleo comercial más importante de Kul Tiras después de Boralus.', 28153),
(157306, 'esES', '¡Esforzaos más, pedazo de holgazanes!', '¡Esforzaos más, pedazo de holgazanes!', 28153),
(157305, 'esES', 'Está ahí arriba. ¡Es grande y tiene dos cabezas!', '¡Está ahí arriba preparándose para atacar!', 28153),
(157304, 'esES', 'Métete en tus asuntos. ¡He venido en misión oficial!', 'Métete en tus asuntos. ¡He venido en misión oficial!', 28153),
(157303, 'esES', '¿Qué te propones? ¡Tienes que irte con los demás!', '¿Qué te propones? ¡Tienes que irte con los demás!', 28153),
(157302, 'esES', '¡Cuidado con ese garrote!', '¡Más te vale correr, Tom, te superamos en número!', 28153),
(157301, 'esES', 'Los dos os culpamos... de esto.', 'Los dos os culpamos... de esto.', 28153),
(157300, 'esES', 'Enfrentaos a mí... ¡a los dos!', 'Enfrentaos a mí... ¡a los dos!', 28153),
(157299, 'esES', 'Yo me ocupo de la cabeza de la derecha.', 'Es más grande de lo que pensaba.', 28153),
(157298, 'esES', 'Inspeccionando', 'Inspeccionando', 28153),
(157296, 'esES', '¡Bienvenidos, amiguitos! Escuchad, he aprendido una canción nueva.', '', 28153),
(157294, 'esES', '¡Primero mueres tú y luego aplasto a toda la gente de la ciudad!', '¡Primero mueres tú y luego aplasto a toda la gente de la ciudad!', 28153),
(157293, 'esES', 'Como en el pasado, el Despertar de la Tormenta dirigirá la flota hasta la victoria. Por la Alianza.', '', 28153),
(157292, 'esES', '', 'La casa Crestavía está contigo, Lady Almirante. Y con la Alianza.', 28153),
(157291, 'esES', '', 'Y que renovemos nuestro vínculo con la Alianza, cuyos héroes nos han salvado de nuestra propia destrucción.', 28153),
(157290, 'esES', '', 'Os pido que depositéis vuestra fe en mi hija, Jaina, la auténtica Lady Almirante de Kul Tiras.', 28153),
(157289, 'esES', '', 'Y la Horda ha dejado claras sus intenciones. Esos salvajes quieren vernos arder.', 28153),
(157288, 'esES', '', 'La falta de unidad nos hace vulnerables. Tenemos al enemigo entre nuestras filas.', 28153),
(157287, 'esES', '', 'Gracias a todos por venir. Seré breve.', 28153),
(157286, 'esES', '¡Seguro que entre los dos podríamos acabar con estos monstruos!', '', 28153),
(157285, 'esES', 'Cuando Daelin me pidió que dejase su guardia y criara a esta hija de los Reinos del Este, me costó entender por qué.\n\n¿Por qué me daba a mí esa carga? ¿Por qué me negaba el honor de luchar a su lado? Pensé que tal vez había hecho algo para perder su confianza.\n\nCon el paso de los años, me he dado cuenta de que era justo lo contrario. Quería que Taelia creciera fuerte de cuerpo y noble de corazón, y confiaba en mí para que así fuera.', '', 28153),
(157284, 'esES', '', '¿Es cierto que se puede viajar de Ventormenta a Forjaz por una especie de túnel subterráneo?$b$b¡Parece increíble! Me encantaría verlo algún día.', 28153),
(157283, 'esES', 'Y eso solo ha sido con un pellizco. Imaginad el daño que podría causar en cantidades mayores.', '', 28153),
(157282, 'esES', '', 'Gracias. Ahora los granjeros podrán volver a trabajar sus campos.', 28153),
(157281, 'esES', '', 'Hay una criatura en las inmediaciones que amenaza a los granjeros locales. ¡Debemos ayudarlos!', 28153),
(157280, 'esES', '', '¡Excelente! Seguro que les dan buen uso a estos suministros.', 28153),
(157279, 'esES', '', 'Espero que llegue el día en el que los ciudadanos de Kul Tiras puedan volver a confiar en los consejos de los Sabiomar. Hasta entonces, debemos seguir nuestro propio camino.', 28153),
(157278, 'esES', '', 'Esto debería proporcionarnos el respiro que necesitamos. Gracias.', 28153),
(157277, 'esES', '', 'La gente de Canto Tormenta no olvidará tu ayuda. ¡Buen trabajo!', 28153),
(157276, 'esES', '', 'En estas colinas abundan recursos muy importantes para el Despertar de la Tormenta. ¿Podrías echar una mano con ellos?', 28153),
(157275, 'esES', '', 'Las fuerzas de Lord Canto Tormenta están causando problemas de nuevo. ¡Hay que detener sus rituales oscuros!', 28153),
(157274, 'esES', '', '¡Hemos perdido el control de la zona! ¡Sal ahí y repele al enemigo!', 28153),
(157273, 'esES', '', 'El Despertar de la Tormenta necesita ayuda. Por favor, ¡restaura la paz en el valle!', 28153),
(157272, 'esES', '', '¡Cañoneros! ¡Preparad el último bombardeo!', 28153),
(157271, 'esES', '', '¡Mantened el escudo! ¡Bastante nos está costando aguantar ya!', 28153),
(157270, 'esES', 'También eres de los Renegados. No pensé... <tose>. ¿Sí, señorita...?', '', 28153),
(157269, 'esES', '<tos> La Horda. Pensé que aquí moriría en paz.\n\n¿Y eres de los Renegados? Interesante, pero es demasiado tarde.\n\n¿Y bien? ¿A qué estás esperando?', '', 28153),
(157268, 'esES', '¡Nos vemos en el carro, $p!', '', 28153),
(157267, 'esES', '', '¡Bien! ¡Es hora de saquear!', 28153),
(157266, 'esES', 'Por favor, llévame de vuelta.', 'Por favor, llévame de vuelta.', 28153),
(157265, 'esES', 'Gracias por tu ayuda hoy. Deberíamos volver.', 'Gracias por tu ayuda hoy. Deberíamos volver.', 28153),
(157264, 'esES', 'Observa el encuentro entre Zelling y su familia.', 'Observa el encuentro entre Zelling y su familia.', 28153),
(157263, 'esES', '¡Un trabajo excelente! Como siempre. Si todos los miembros de la Alianza montaran como tú, ¡serían más que bienvenidos en mi hacienda!', '', 28153),
(157262, 'esES', '¡Hace un día perfecto para un buen espectáculo! Monta, camarada, ¡y demuestra tu valía como jinete!', '', 28153),
(157261, 'esES', '', 'Allá tú. Vamos, $n.', 28153),
(157260, 'esES', 'Me vuelvo a la base. Sé cómo acaba esto, no necesito verlo.', '', 28153),
(157259, 'esES', 'Sé conhciente de que ehtáh entre tuh superioreh. No ehtorbeh mientrah ehtoy con el señor de loh maleficioh.', '', 28153),
(157258, 'esES', '', '¡Bien hecho! Eso debería retrasar a los nagas.', 28153),
(157257, 'esES', '', 'Tienes mi palabra. Ven. $n, vuelve con Nathanos e infórmalo de que tenemos lo que necesitamos.', 28153),
(157256, 'esES', 'Me uniré a ti... y te ayudaré a encontrar al mariscal Valentine. Siempre y cuando me prometas que mi familia no sufrirá ningún daño.', '', 28153),
(157255, 'esES', '', '¡Los nagas vuelven a atacar el fuerte! ¡Acaba con ellos al estilo tortoliano!', 28153),
(157254, 'esES', '', 'Únete a los Renegados y sigue tu propio camino. Estarás entre los que te aceptan como aquello en lo que te has convertido.', 28153),
(157253, 'esES', '¿Y eso en qué me convierte? ¿En un esbirro de la Reina alma en pena sin voluntad?', '', 28153),
(157252, 'esES', '', 'Eh un honor que, normalmente, solo correhponde a loh Zandalari. Caminad conmigo y relatadme la hihtoria de Vol\'jin.', 28153),
(157250, 'esES', '', 'Intenté advertirte, Zelling. El proceso te cambia. Los vivos ya no te aceptarán.', 28153),
(157249, 'esES', 'No... Julia... Matthew... Hannah... ¿Qué es lo que he hecho? ¿Qué... soy?', '', 28153),
(157248, 'esES', '', '¡Haz que se vaya el monstruo!', 28153),
(157247, 'esES', '', '¡Déjanos en paz!', 28153),
(157246, 'esES', '¡Que se vaya!', '', 28153),
(157245, 'esES', '¡Silencio!', '', 28153),
(157244, 'esES', '', 'No sé quién eres, pero mi marido NUNCA intentó hacerme daño a mí ni a nuestros hijos. Nos vamos... ¡No nos sigas!', 28153),
(157243, 'esES', 'Yo... Yo...', '', 28153),
(157242, 'esES', '¡YA BASTA!', '', 28153),
(157241, 'esES', '¡Mamá, socorro!', '', 28153),
(157240, 'esES', '', '¡No dejes que se acerque!', 28153),
(157239, 'esES', 'Papá está aquí. ¡Escuchad mi voz! ¡¿Por qué no lo entendéis?!', '', 28153),
(157238, 'esES', '', '¡No te acerques!', 28153),
(157237, 'esES', '¡Mamá, el monstruo me da miedo!', '', 28153),
(157236, 'esES', '¡¿Por qué no lo entendéis?! Soy yo, tu marido... ¡Hijos, soy vuestro papá!', '', 28153),
(157235, 'esES', '', '¡Por última vez, NO TE ACERQUES! ¡Tú NO eres mi marido!', 28153),
(157234, 'esES', 'Sigo siendo fuerte... hasta en la muerte.', '', 28153),
(157233, 'esES', '¡Has venido mal $gpreparado:preparada; para enfrentarte a mí en combate!', '', 28153),
(157232, 'esES', 'Zelling, necesitamos que encuentres el cadáver del mariscal Valentine.', 'Zelling, necesitamos que encuentres el cadáver del mariscal Valentine.', 28153),
(157231, 'esES', 'Mi familia me... vengará.', '', 28153),
(157230, 'esES', '¡Serás el objetivo de mi ira!', '', 28153),
(157229, 'esES', '', 'Supongo que habrá que ver qué pasa ahora.', 28153),
(157228, 'esES', '¡Es... Estoy vivo! ¡Ja, ja! Tengo que ir a ver a Julia y los niños, ¡estarán encantados!', '', 28153),
(157227, 'esES', '', 'Pocoh ehpírituh han demohtrado un poder semejante... Maehtro Gadrin, por favor, lleva lah cenizah de ehte jefe a Atal\'Dazar. Si su ehpíritu eh digno, obtendrá un lugar de honor entre nuehtroh gloriosoh reyeh.', 28153),
(157226, 'esES', 'Zalazane no volverá dehpuéh de eso. Incluso muerto, Vol\'jin cuida de nosotroh.', '', 28153),
(157225, 'esES', 'Loh muertoh... caen...', '', 28153),
(157224, 'esES', 'Nuestros refuerzos esperan tus órdenes.', '', 28153),
(157223, 'esES', '¡Si la Horda quiere guerra, se la daremos con todas nuestras fuerzas!', '', 28153),
(157222, 'esES', 'Espero que traigas buenas nuevas.', '', 28153),
(157221, 'esES', 'Canto Tormenta prevalecerá.', '', 28153),
(157220, 'esES', 'Buen viaje.', '', 28153),
(157219, 'esES', 'Que las mareas te guíen.', '', 28153),
(157218, 'esES', '¡Excelente! Daremos buen uso tanto a los suministros como a esas crías.', '', 28153),
(157217, 'esES', 'Los jabaespines no paran de saquearnos. Ahora nos toca a nosotros. ¡Hazte con nuestros suministros y con todo lo que te parezca útil!', '', 28153),
(157216, 'esES', 'Ahora mismo.', '', 28153),
(157215, 'esES', '', '¡Señor, sí, señor!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'esES', '', 'Misericordiosa Elune, bendice a los caídos.', 28153),
(157213, 'esES', 'Taelia, reanuda las patrullas. Que la guardia de la ciudad preste especial atención a cualquier posible contrabando de armas extrañas a Boralus.', '', 28153),
(157212, 'esES', '', 'Declaro a Vol\'jin, hijo de Sen\'jin, digno de nuehtrah tumbah sagradah. Pero la entrada a Atal\'Dazar no ehtá exenta de peligroh. Sugiero que tú, adalid, porteh ehtah cenizah a su lugar de dehcanso eterno.', 28153),
(157211, 'esES', '', 'Hacer lo que tuh lídereh no ehtán dihpuehtoh a hacer eh difícil.', 28153),
(157210, 'esES', 'Cuando fue evidente que Garrosh, nuehtro Jefe de Guerra, no iba a liderarnoh con honor, Vol\'jin se rebeló e intentó acabar con su sed de sangre.', '', 28153),
(157209, 'esES', '', 'En aquel momento, a mi padre le atrajo la visión de Zul de un gran imperio trol, pero admito que tu jefe acertó al mantener una visión máh amplia.', 28153),
(157208, 'esES', 'Cuando Zandalar intentó unir a lah tribuh trol, Vol\'jin eligió la seguridad de su pueblo anteh que loh podereh ohcuroh del profeta.', '', 28153),
(157207, 'esES', 'Vol\'jin hizo un pacto con Bwonsamdi pa derrotar al poderoso Zalazane.', '', 28153),
(157206, 'esES', '', 'Hay más fuegos fatuos de los que puedo contar. Las vidas perdidas...', 28153),
(157205, 'esES', 'Venimoh a depositar lah cenizah de Vol\'jin, hijo de Sen\'jin, pa que se le honre en ehte lugar sagrado.', '', 28153),
(157204, 'esES', 'Flynn, tengo otro trabajo para ti: ayuda a tu adalid a rastrear el origen de esta pólvora.', '', 28153),
(157203, 'esES', 'Están despertando antiguas amenazas por estos lares. Cuidado.', '', 28153),
(157202, 'esES', 'Clamavientos, he venido por orden de la Jefa de Guerra.', 'Clamavientos, he venido por orden de la Jefa de Guerra.', 28153),
(157201, 'esES', 'Sí, necesito ir a Silithus.', 'Sí, necesito ir a Silithus.', 28153),
(157200, 'esES', '¿Por qué estoy aquí, humano?', '¿Por qué estoy aquí, humano?', 28153),
(157199, 'esES', '¡Adalid! ¿Podrías hacerles una demostración a nuestros incrédulos compañeros?', '', 28153),
(157198, 'esES', 'No, esta vez es diferente.', '', 28153),
(157197, 'esES', 'Menuda novedad. Fabrican armas nuevas constantemente.', '', 28153),
(157196, 'esES', '', 'Vale, Flynn, cuéntanos lo que has descubierto. Que Gobernalle tenía un nuevo tipo de pólvora o algo así, ¿no?', 28153),
(157195, 'esES', 'Necesito un jinete del viento para ir al Refugio de Marshal en el Cráter de Un\'Goro.', 'Necesito un jinete del viento para ir al Refugio de Marshal en el Cráter de Un\'Goro.', 28153),
(157194, 'esES', 'Ya de vuelta... ¡Bien! Temía decirle a la Princesa que un enano de diamante noh había robado a su adalid.', '', 28153),
(157193, 'esES', '¡Oh, vaya! ¡Qué buen trabajo hemos hecho!', '', 28153),
(157192, 'esES', 'Tenemos que recuperar el cargamento perdido. Y con \"tenemos\" quiero decir \"tienes\".', '', 28153),
(157191, 'esES', 'Dondequiera que vayah, ehpero que el viaje sea breve. ¡Sé que la Princesa te necesita!', 'Dondequiera que vayah, ehpero que el viaje sea breve. ¡Sé que la Princesa te necesita!', 28153),
(157190, 'esES', '¡Ehtraordinario! Debería tomar apunteh...', '¡Ehtraordinario! Debería tomar apunteh...', 28153),
(157189, 'esES', 'En la guerra, es fundamental proteger la línea de suministros. Como también lo es acabar con la del enemigo.', '', 28153),
(157188, 'esES', '¿Restos de naufragio de la Alianza? ¡Maravilloso! Busca cualquier suministro que pueda ser útil para la Horda.', '', 28153),
(157187, 'esES', 'Un día productivo. Muy bien.', '', 28153),
(157186, 'esES', '¡Están atacando el extractor! ¡Protégelo!', '', 28153),
(157185, 'esES', 'Estos recursos son vitales para la Horda. Buen trabajo.', '', 28153),
(157184, 'esES', '¡Protege el extractor! ¡Necesitamos esa azerita!', '', 28153),
(157183, 'esES', '¿Cuál es tu estrategia, Shandris?', '¿Cuál es tu estrategia, Shandris?', 28153),
(157182, 'esES', '', '<La aguda mirada de Shandris recorre el horizonte. Te hace un gesto de reconocimiento>.', 28153),
(157181, 'esES', 'Encontrar al Vigía del Sol y luego llenarlo de flechas.', '', 28153),
(157180, 'esES', '¿Mi estrategia?', '', 28153),
(157179, 'esES', 'El equipo de operaciones especiales de Gnomeregan colocará bombas para atraer al Vigía del Sol, y entonces lo atacaremos en plena confusión.', '', 28153),
(157178, 'esES', '', '¡Muy buenas!', 28153),
(157177, 'esES', '¡Afirmativo! Por lo tanto, he reunido un equipo especializado de comandos con el conocimiento técnico necesario.', '', 28153),
(157176, 'esES', '', 'Quieres... detonar unas cuantas bombas a la vez.', 28153),
(157175, 'esES', 'Me gustaría realizar un ataque incendiario sincronizado contra todas sus excavaciones.', '', 28153),
(157174, 'esES', 'Sí. Nuestra información indica que hay al menos tres excavaciones.', '', 28153),
(157173, 'esES', '', '¿Arqueología?', 28153),
(157172, 'esES', 'El Vigía del Sol, como miembro del Relicario, está aquí por una misión arqueológica.', '', 28153),
(157171, 'esES', 'No... No recuerdo. Pero eh mejor así.', '', 28153),
(157170, 'esES', '', 'Perdóname... ¿Quién has dicho que eras? ¿Es de ti de quien hablaba Malfurion?', 28153),
(157168, 'esES', 'Le he entregado tu nota a B\'wizati.', 'Le he entregado tu nota a B\'wizati.', 28153),
(157167, 'esES', '', 'Y los civiles... Tampoco a ellos les perdonaron la vida. Espero que algunos pudieran escapar antes de...', 28153),
(157166, 'esES', '', 'Atacaron a nuestra avanzada por sorpresa. No quedó ni uno. Envenenaron a los guardias...', 28153),
(157165, 'esES', '', '%s se enjuga una lágrima mientras se levanta.', 28153),
(157164, 'esES', '', 'Intentamos tenderle una trampa a la Horda, pero fallamos. No conseguimos detenerlos.', 28153),
(157163, 'esES', 'Me alegra ver que ehtáh bien. Yo también lo ehtoy. Akunda me ha otorgado la posibilidad de un nuevo comienzo.', '', 28153),
(157162, 'esES', '¿Cuál es tu plan, Alto comandante?', '¿Cuál es tu plan, Alto comandante?', 28153),
(157161, 'esES', 'La Séptima Legión representa lo mejor que Azeroth puede ofrecer.\n\n¡Por la Alianza!', '', 28153),
(157160, 'esES', '¿Quién? No conozco a ningún trol que se llame así, ¿no?', '', 28153),
(157159, 'esES', '', 'Cadáveres... Tantos cadáveres...', 28153),
(157158, 'esES', 'Tengo algo que mostrarte, adalid. Un regalo que puede ayudar a la gente de esta tierra.', '', 28153),
(157157, 'esES', 'Un enano... de diamante... ¡en el corazón de Zuldazar! ¿Quién...?', '', 28153),
(157156, 'esES', '', 'He visto cosas extrañas en estos bosques, pero nada como esto.', 28153),
(157155, 'esES', '¿Qué eh eso? La tierra tiembla...', '', 28153),
(157153, 'esES', 'La Jefa de Guerra ordenó que te ayudara.', 'La Jefa de Guerra ordenó que te ayudara.', 28153),
(157152, 'esES', 'Debo volar a Gadgetzan en Tanaris.', 'Debo volar a Gadgetzan en Tanaris.', 28153),
(157151, 'esES', 'Tienes... que...', '', 28153),
(157150, 'esES', 'Yo... condenaría mi alma... por toda la eternidad... con tal de que mi familia fuera feliz... ¡Por favor! Tienes que...', '', 28153),
(157149, 'esES', '', 'Yo me pregunto eso a diario, Zelling.', 28153),
(157148, 'esES', 'Objetivo fijado.', '', 28153),
(157147, 'esES', '', 'Todos nos volvemos un poco locos cuando nos convertimos en Renegados. Algunos más que otros.', 28153),
(157146, 'esES', '¿Conoceh a Akunda?', '¿Conoceh a Akunda?', 28153),
(157145, 'esES', 'Deja que Akunda te quite la carga que pesa sobre tu corazón.', 'Deja que Akunda te quite la carga que pesa sobre tu corazón.', 28153),
(157144, 'esES', 'Akunda noh da a todoh una oportunidad de empezar de nuevo.', 'Akunda noh da a todoh una oportunidad de empezar de nuevo.', 28153),
(157143, 'esES', 'Siempre seráh bien $grecibido:recibida; aquí.', 'Siempre seráh bien $grecibido:recibida; aquí.', 28153),
(157142, 'esES', 'El loa da la bienvenida a todoh a su templo.', 'El loa da la bienvenida a todoh a su templo.', 28153),
(157141, 'esES', '¿Conoceh a Akunda?', '¿Conoceh a Akunda?', 28153),
(157140, 'esES', 'Deja que Akunda te quite la carga que pesa sobre tu corazón.', 'Deja que Akunda te quite la carga que pesa sobre tu corazón.', 28153),
(157139, 'esES', 'Akunda noh da a todoh una oportunidad de empezar de nuevo.', 'Akunda noh da a todoh una oportunidad de empezar de nuevo.', 28153),
(157138, 'esES', 'Siempre seráh bien $grecibido:recibida; aquí.', 'Siempre seráh bien $grecibido:recibida; aquí.', 28153),
(157137, 'esES', 'El loa da la bienvenida a todoh a su templo.', 'El loa da la bienvenida a todoh a su templo.', 28153),
(157136, 'esES', 'He venido a ayudar, Nyse.', 'He venido a ayudar, Nyse.', 28153),
(157135, 'esES', 'Ah, la pesadilla ha terminado.', 'Ah, la pesadilla ha terminado.', 28153),
(157134, 'esES', '¡Listo! ¡Enviad a ese kraken de nuevo a las profundidades!', '¡Listo! ¡Enviad a ese kraken de nuevo a las profundidades!', 28153),
(157133, 'esES', '¡Artillería a punto!', '¡Artillería a punto!', 28153),
(157132, 'esES', 'Doras, necesito volar a Piñón de Barro en el Marjal Revolcafango.', 'Doras, necesito volar a Piñón de Barro en el Marjal Revolcafango.', 28153),
(157131, 'esES', '¡La artillería está lista! ¡Convertid a esa bestia en carnaza!', '¡La artillería está lista! ¡Convertid a esa bestia en carnaza!', 28153),
(157130, 'esES', 'No... ¡NO!', 'No... ¡NO!', 28153),
(157129, 'esES', '¡Gracias! ¡Ahora prepararé este cañón para devolvérsela!', '¡Gracias! ¡Ahora prepararé este cañón para devolvérsela!', 28153),
(157128, 'esES', 'Zabanji ronca.', 'Zabanji ronca.', 28153),
(157127, 'esES', '¡Os debo una! ¡Ahora dadme un momento para preparar este cañón!', '¡Os debo una! ¡Ahora dadme un momento para preparar este cañón!', 28153),
(157126, 'esES', '¿Todo ha sido un sueño?', '¿Todo ha sido un sueño?', 28153),
(157125, 'esES', '¡No dejéis que esta bestia me coma!', '¡No dejéis que esta bestia me coma!', 28153),
(157124, 'esES', '¡Reducidlos a cenizas!', '', 28153),
(157123, 'esES', '¡Quitadme esta cosa de encima!', '¡Quitadme esta cosa de encima!', 28153),
(157122, 'esES', '$p, coge una antorcha y dale a todo lo que se mueva. ¡Estas abominaciones no-muertas no merecen que te lo pienses dos veces!', '', 28153),
(157121, 'esES', 'Eso es, soldado. Y este puerto impío está plagado de monstruos que matar.', '', 28153),
(157120, 'esES', '¡Socorro!', '¡Socorro!', 28153),
(157119, 'esES', 'Ni habrá nadie que nos robe las muertes, señor.', '', 28153),
(157118, 'esES', '¿Quién ereh? ¿Dónde ehtamoh?', '¿Quién ereh? ¿Dónde ehtamoh?', 28153),
(157117, 'esES', 'No hay refuerzos. No nos rescatarán si fallamos.', '', 28153),
(157116, 'esES', 'Escuchad, soldados. Esta es una misión no autorizada.', '', 28153),
(157115, 'esES', '¿A qué estás esperando, $p?\n\nTenemos armas y tenemos un enemigo. ¡Sube al barco!', '¿A qué estás esperando, $p?\n\nTenemos armas y tenemos un enemigo. ¡Sube al barco!', 28153),
(157114, 'esES', 'Akunda de la Fatiga ronca.', 'Akunda de la Fatiga ronca.', 28153),
(157113, 'esES', 'Todoh somoh Akunda...', 'Todoh somoh Akunda...', 28153),
(157112, 'esES', '¿Más trabajo?', '', 28153),
(157111, 'esES', 'Bien.', '', 28153),
(157110, 'esES', 'De acuerdo.', '', 28153),
(157109, 'esES', 'Sí, mi señor.', '', 28153),
(157108, 'esES', '', 'Sí, señor.', 28153),
(157107, 'esES', 'De acuerdo. Seguiremos adelante sin ella. Si no vuelve pronto en sí... preparad vuestras hojas.', '', 28153),
(157106, 'esES', '', 'Le está costando... un tiempo acostumbrarse.', 28153),
(157105, 'esES', '', 'Arg...', 28153),
(157104, 'esES', 'Stone, haz el favor de decirnos quién es el héroe de guerra más importante que hay en este cementerio.', '', 28153),
(157103, 'esES', 'Ahora que has venido, podemos empezar.', '', 28153),
(157102, 'esES', '¡Luchad por vuestros hermanos y hermanas!', '¡Luchad por vuestros hermanos y hermanas!', 28153),
(157101, 'esES', '¡Victoria para la Alianza!', '¡Victoria para la Alianza!', 28153),
(157100, 'esES', '¡A la batalla!', '¡A la batalla!', 28153),
(157099, 'esES', 'Gracias por ocuparte del entuerto. Todos podrán volver a casa a salvo esta noche.', '', 28153),
(157098, 'esES', '¡Arathi es nuestra!', '¡Arathi es nuestra!', 28153),
(157097, 'esES', '¡Muerte a la Horda!', '¡Muerte a la Horda!', 28153),
(157096, 'esES', '¡Seguidme!', '¡Seguidme!', 28153),
(157095, 'esES', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(157094, 'esES', '¡Por aquí! ¡Tenemos una guerra que ganar!', '¡Por aquí! ¡Tenemos una guerra que ganar!', 28153),
(157093, 'esES', 'La presencia de la Horda ha hecho que la fauna huya a las tierras bajas. Ayuda a los cazadores a ocuparse de los osos.', '', 28153),
(157092, 'esES', 'Tú... ¡has hecho que mate a mi amigo! ¡Ahora vas a morir!', '', 28153),
(157091, 'esES', 'Hermanos y hermanas, ¡sed testigos de nuestro glorioso destino!', '', 28153),
(157090, 'esES', 'Gracias, $gamigo:amiga;. El valle está contigo.', 'Cuánto me alegro de verte, $p. Recordaré esto.', 28153),
(157089, 'esES', 'Ahora puedo seguir yo. Ten cuidado.', '¡Me alegro tanto de verte...!', 28153),
(157088, 'esES', '¡Creía que iba a morir!', 'Gracias, no lo olvidaré.', 28153),
(157087, 'esES', '¡Ja! Esos jabalíes no son tan horribles después de todo. Me pregunto si les gustan las almejas al vapor...', '', 28153),
(157086, 'esES', 'Hemos avistado algunos jabalíes de batalla salvajes cerca del horado. Si te atreves a montar uno, ¡podríamos usarlo contra los jabaespines!', '', 28153),
(157085, 'esES', 'Véngame... Taptaf...', '', 28153),
(157084, 'esES', '', 'Por fin... acaba el tormento...', 28153),
(157083, 'esES', '', 'Sí... Se acabó...', 28153),
(157082, 'esES', '', 'Era... una trampa...', 28153),
(157081, 'esES', '', 'Je... El cazador, cazado...', 28153),
(157080, 'esES', '', 'Él viene a por todos nosotros...', 28153),
(157079, 'esES', '¡Un momento, Majestad! Traigo noticias.', '', 28153),
(157078, 'esES', '', 'Esto... no tenía que... pasar...', 28153),
(157077, 'esES', '', '¡Qué conveniente es que la presa venga por sí sola!', 28153),
(157076, 'esES', '', '¡Mira lo que me he encontrado entre mis trampas!', 28153),
(157075, 'esES', '', '¡No eres muy grande, pero te despellejaré de todos modos!', 28153),
(157074, 'esES', '', '¡Me prometieron todas las recompensas del bosque!', 28153),
(157073, 'esES', '', '¡Me pagarán bien por tu piel!', 28153),
(157072, 'esES', '', '¡Otra piel para mí!', 28153),
(157071, 'esES', 'Caerás...', '', 28153),
(157070, 'esES', 'Vuelvo a la tierra...', '', 28153),
(157069, 'esES', 'Llega... el fin...', '', 28153),
(157068, 'esES', '¡¿Qué quieres?! ¡Bu! ¡Largo!', '', 28153),
(157067, 'esES', 'Mi alma... está contagiada...', '', 28153),
(157066, 'esES', 'El velo ha caído...', '', 28153),
(157065, 'esES', '¡Thros nos consumirá a todos!', '', 28153),
(157064, 'esES', '¡Habla desde el más allá!', '', 28153),
(157063, 'esES', '¡Tomad vuehtra venganza y tomad vuehtro tesoro!', '', 28153),
(157062, 'esES', '¡Sí, coge una antorcha y ponte a trabajar, $p!', '¡Sí, coge una antorcha y ponte a trabajar, $p!', 28153),
(157061, 'esES', '¡Sí, vamoh a atacarloh y mandarloh a todoh a lah ohcurah profundidadeh!', '', 28153),
(157060, 'esES', 'Vamoh a quemarloh, ¿no?', 'Vamoh a quemarloh, ¿no?', 28153),
(157059, 'esES', 'Nuehtra vieja tripulación maldita en el Puerto de Zem\'lan ehtá enviando grandeh grupoh de asalto hoy, y somoh uno de loh objetivoh.', '', 28153),
(157058, 'esES', '¡Bienvenidoh de nuevo a la mar salada, camaradah!', '', 28153),
(157057, 'esES', '¡Todoh a bordo!', '¡Todoh a bordo!', 28153),
(157056, 'esES', 'Cuando logre conjurar el hechizo, tal vez vuelvan a dejarme entrar. Puede que sea... ¡Lai negse leinad!', '', 28153),
(157055, 'esES', 'Taptaf, si puedes entenderme, quiero decirte que siento haberte transformado. Ya sabes, para siempre.', '', 28153),
(157054, 'esES', 'Me pregunto si tu nombre servirá, Taptaf. Vamos a probar. ¡Nolem nuse Taptaf!', '', 28153),
(157053, 'esES', 'No fue justo que me expulsaran, Taptaf. Les enseñaré el mayor de mis poderes... eh... cuando recuerde cómo era.', '', 28153),
(157052, 'esES', 'Mmm... No, no parece que sea eso.', '', 28153),
(157051, 'esES', 'No consigo recordar ese maldito hechizo. ¿Cómo era, Taptaf? Leinad algo... ¿Nos fatsug?', '', 28153),
(157050, 'esES', '¡Me han abierto los ojos!', '', 28153),
(157049, 'esES', '¡Tu sangre alimentará al bosque!', '', 28153),
(157048, 'esES', '¡Raaaaaaagh!', '', 28153),
(157047, 'esES', 'Excelente trabajo. Ojalá algún día este vuelva a ser un lugar de oración.', '', 28153),
(157046, 'esES', 'La magia que infecta este lugar corromperá las aguas si no hacemos algo. Retrasa a los Sabiomar como puedas.', '', 28153),
(157045, 'esES', 'Que las mareas se lleven sus almas corruptas y puedan, por fin, descansar en paz.', '', 28153),
(157044, 'esES', 'Ciertos partidarios de la casa Canto Tormenta corrompieron este lugar con su poder oscuro. Acaba con ellos antes de que causen más daño.', '', 28153),
(157043, 'esES', '¡Bien hecho! ¡Puedo ver el humo desde aquí! Volveremos a atacar en cuanto podamos.', '', 28153),
(157042, 'esES', '¡Espero que te lleves bien con los grifos! Habla con Bernadette Robels. Ha ideado un plan para atacar a la Horda en el Fuerte Guerracolmillo.', '', 28153),
(157041, 'esES', '', '¿Yarr?', 28153),
(157040, 'esES', 'Sin el poder del loa, ereh débil. ¡Adalid, acaba con él!', '', 28153),
(157039, 'esES', 'El enemigo se ehconde trah el poder de Rezan. ¡Yo me ocupo de ehto!', '', 28153),
(157038, 'esES', 'Recuerda, continental: teme todo aquello que mora en las profundidades. En las sombras, solo encontrarás fatalidad.', '', 28153),
(157037, 'esES', 'Algunos Sabiomar están intentando invocar un poder que podría destruir Boralus. ¡Hay que detenerlos!', '', 28153),
(157036, 'esES', '', 'Deja que te guíe, te llevará y te traerá de vuelta de una pieza.', 28153),
(157035, 'esES', '', '¡Está lista para partir!', 28153),
(157034, 'esES', '', 'Es el grifo más veloz del valle. Si alguien dice lo contrario, miente.', 28153),
(157033, 'esES', '¡Luego te toca a ti!', '¡Luego te toca a ti!', 28153),
(157032, 'esES', 'El pájaro y tú sois malos.', 'El pájaro y tú sois malos.', 28153),
(157031, 'esES', '¡Quiero volar también!', '¡Quiero volar también!', 28153),
(157030, 'esES', 'Odio a la Alianza.', 'Odio a la Alianza.', 28153),
(157029, 'esES', '¡Mira! Pajarito bonito.', '¡Mira! Pajarito bonito.', 28153),
(157028, 'esES', '', 'El impulso de recreación ehtá lihto. De nosotroh depende acabar con G\'huun de una vez por todah.', 28153),
(157027, 'esES', 'El impulso de recreación está listo. Encendámoslo y reventemos a G\'huun como el grano de pus que es.', '', 28153),
(157026, 'esES', '¿Me aplastan... a mí?', '¿Me aplastan... a mí?', 28153),
(157025, 'esES', '¡Renacuajo insignificante! ¡Yo aplastarte como a bicho!', '¡Renacuajo insignificante! ¡Yo aplastarte como a bicho!', 28153),
(157024, 'esES', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(157023, 'esES', '¡La cría de cuernoatroz brama y corre hacia su madre!', '¡La cría de cuernoatroz brama y corre hacia su madre!', 28153),
(157022, 'esES', '¡Llévame dentro!', '¡Llévame dentro!', 28153),
(157021, 'esES', '¿Te llevo?', '¿Te llevo?', 28153),
(157020, 'esES', '', 'Everit te ha entrenado bien. Estaría orgulloso de ti.', 28153),
(157019, 'esES', '', 'Gracias, mi señora. No te decepcionaré.', 28153),
(157018, 'esES', '', 'Por lo que te nombro mariscal Albaclara, líder de la guardia de los Crestavía.', 28153),
(157017, 'esES', '', 'Pero Drustvar va a seguir necesitando tus servicios, y a un nivel aún mayor.', 28153),
(157016, 'esES', '', 'Inquisidora Albaclara, con tu demostración de compasión, valentía, liderazgo y astucia, has superado todas nuestras expectativas.', 28153),
(157015, 'esES', '', 'Hemos conocido el dolor de la pérdida, pero el fuego de la esperanza arde con fuerza.', 28153),
(157014, 'esES', 'No es nada personal.', 'No es nada personal.', 28153),
(157013, 'esES', 'El enemigo controla el Círculo de los Elementos... por ahora.', 'El enemigo controla el Círculo de los Elementos... por ahora.', 28153),
(157012, 'esES', '¡Veo estandartes de la Horda en el Círculo de los Elementos!', '¡Veo estandartes de la Horda en el Círculo de los Elementos!', 28153),
(157011, 'esES', '¡La Horda controla el Círculo de los Elementos!', '¡La Horda controla el Círculo de los Elementos!', 28153),
(157010, 'esES', '¡Nuestros estandartes ondean en el Círculo de los Elementos!', '¡Nuestros estandartes ondean en el Círculo de los Elementos!', 28153),
(157009, 'esES', 'Nuestras fuerzas controlan el Círculo de los Elementos.', 'Nuestras fuerzas controlan el Círculo de los Elementos.', 28153),
(157008, 'esES', 'El Círculo de los Elementos permanece bajo nuestro control.', 'El Círculo de los Elementos permanece bajo nuestro control.', 28153),
(157007, 'esES', 'Los estandartes de la Horda ondean en Finca Nueva... por ahora.', 'Los estandartes de la Horda ondean en Finca Nueva... por ahora.', 28153),
(157006, 'esES', '¿Esos monstruos se creen que controlan Finca Nueva? Ya verán...', '¿Esos monstruos se creen que controlan Finca Nueva? Ya verán...', 28153),
(157005, 'esES', 'Esos villanos no podrán controlar Finca Nueva eternamente.', 'Esos villanos no podrán controlar Finca Nueva eternamente.', 28153),
(157004, 'esES', 'Nuestras fuerzas han tomado el control de Finca Nueva.', 'Nuestras fuerzas han tomado el control de Finca Nueva.', 28153),
(157003, 'esES', 'Tenemos el control de Finca Nueva.', 'Tenemos el control de Finca Nueva.', 28153),
(157002, 'esES', 'Parece que hemos tomado el control de Finca Nueva. Será mejor que siga en nuestras manos.', 'Parece que hemos tomado el control de Finca Nueva. Será mejor que siga en nuestras manos.', 28153),
(157001, 'esES', 'El loa de los reyes ha caído. Debemos ser precavidos si vamos a iniciar otra cacería.\n\nRastakhan está gravemente herido y envejece rápidamente. Solo el poder de Rezan podría mantener a Bwonsamdi a raya. Le ofrecería mi poder, pero no me corresponde a mí retar al loa de la muerte.', '', 28153),
(157000, 'esES', '¿Qué, señora?', '', 28153),
(156999, 'esES', '', 'La señora de las bestias L\'kala mira con desconfianza al goblin que está a su lado.', 28153),
(156998, 'esES', '', 'Parece que tu pequeño ehtá cansado de tanto luchar. Aquí ehtará a salvo. Lo cuidaré yo mihma.', 28153),
(156996, 'esES', 'La prole de cuernoatroz bosteza y cierra los ojos.', 'La prole de cuernoatroz bosteza y cierra los ojos.', 28153),
(156995, 'esES', '¡Hora de irse!', '¡Hora de irse!', 28153),
(156994, 'esES', 'Siento como si alguien me hubiera arrancado el alma del cuerpo.', '', 28153),
(156993, 'esES', '¡Ha estado cerca! ¡Gracias por la ayuda!', '¡Ha estado cerca! ¡Gracias por la ayuda!', 28153),
(156992, 'esES', '¡Gracias por la ayuda! Por alguna razón, mis zapatillas antipringue dejaron de funcionar.', '¡Gracias por la ayuda! Por alguna razón, mis zapatillas antipringue dejaron de funcionar.', 28153),
(156991, 'esES', '¡Muchas gracias! En cuanto vuelva voy a poner una queja. Los problemas logísticos a los que se está enfrentando esta expedición son muchos más de los que detallaba nuestro informe.', '¡Muchas gracias! En cuanto vuelva voy a poner una queja. Los problemas logísticos a los que se está enfrentando esta expedición son muchos más de los que detallaba nuestro informe.', 28153),
(156990, 'esES', '¡Oh, vaya! ¡Después de esto voy a tener que pasarme una semana en el Sanitrón!', '¡Oh, vaya! ¡Después de esto voy a tener que pasarme una semana en el Sanitrón!', 28153),
(156989, 'esES', '¡No conseguía despegarme de la situación! ¡Tienes mi gratitud!', '¡No conseguía despegarme de la situación! ¡Tienes mi gratitud!', 28153),
(156988, 'esES', 'Que loh mareh bendigan ehta mena y que nunca reclamen lo que han bendecido.', 'Que loh mareh bendigan ehta mena y que nunca reclamen lo que han bendecido.', 28153),
(156987, 'esES', '¿Podrías bendecir estos lingotes de plata de tormenta?', '¿Podrías bendecir estos lingotes de plata de tormenta?', 28153),
(156986, 'esES', 'Nadie debería pensar en los Renegados como una segunda oportunidad para nada.', '', 28153),
(156985, 'esES', 'No me gusta lo que estás insinuando, Zelling.', '', 28153),
(156984, 'esES', '¡Sí! ¡Poder crustáceo!', '', 28153),
(156983, 'esES', 'Vas a necesitar un caparazón en el que esconderte. ¡Ja! ¡Un caparazón de cangrejo! ¿Lo pillas? ¡La victoria es mía!', '', 28153),
(156982, 'esES', '¡Esto no quedará así! ¡El capitán Hermes y su trío de cangrejos despiadados aún no están acabados!', '', 28153),
(156981, 'esES', '¿Cómo es posible?', '', 28153),
(156980, 'esES', '¡Por fin aparece un contendiente!', '', 28153),
(156979, 'esES', 'Pon rumbo al Valle Canto Tormenta.', 'Pon rumbo al Valle Canto Tormenta.', 28153),
(156978, 'esES', 'Pon rumbo al Estrecho de Tiragarde.', 'Pon rumbo al Estrecho de Tiragarde.', 28153),
(156977, 'esES', 'Pon rumbo a Drustvar.', 'Pon rumbo a Drustvar.', 28153),
(156976, 'esES', '¿Qué?', '', 28153),
(156974, 'esES', 'El tipo de la camiseta roja dijo que yo no era oficial. ¡Pues claro que no lo soy! Soy Almirante.', '', 28153),
(156973, 'esES', '¿Podrías volver a informarme sobre Kul Tiras?', '¿Podrías volver a informarme sobre Kul Tiras?', 28153),
(156972, 'esES', 'Enderezaremos las cosas.', '', 28153),
(156971, 'esES', '', 'Hola, ¿en qué puedo ayudarte?', 28153),
(156970, 'esES', '¡Buen trabajo! Has cortado sus planes de raíz.', '', 28153),
(156969, 'esES', '¿Los mares te susurran como me susurran a mí?', '', 28153),
(156968, 'esES', '¡Tengo que saber si mi familia está a salvo! <tos>', '', 28153),
(156967, 'esES', '', 'He dicho que no pongas a prueba mi...', 28153),
(156966, 'esES', 'Me han informado de que hay una horrible planta monstruosa cerca del horado. Nuestros mozos de labranza mecánicos deberían poder encargarse de ella rápidamente.', '', 28153),
(156965, 'esES', 'Que los mares te guíen a tu hogar.', '', 28153),
(156964, 'esES', '¿En qué puede ayudarte la casa Valiente?', '', 28153),
(156963, 'esES', 'Pon rumbo a Zuldazar.', 'Pon rumbo a Zuldazar.', 28153),
(156962, 'esES', 'Pon rumbo a Nazmir.', 'Pon rumbo a Nazmir.', 28153),
(156961, 'esES', 'Juntos somos fuertes.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'esES', 'Honraré el legado de mi padre.', '', 28153),
(156959, 'esES', 'Durante años he surcado los mares en busca de la más mortífera colección de cangrejos ermitaños que ha conocido este mundo. ¿Te atreves a combatir o temes que te dé un repaso?', '', 28153),
(156958, 'esES', 'Buen trabajo. Pondremos a nuestros mejores investigadores a estudiar estos textos. Gracias.', '', 28153),
(156957, 'esES', 'Nuestros magos de batalla han descubierto pergaminos tortolianos entre los caídos. Debemos hacernos con ellos antes de que la Horda los descubra. Recupera cuantos puedas.', '', 28153),
(156956, 'esES', '¡La Alianza ha capturado Stromgarde!', '¡La Alianza ha capturado Stromgarde!', 28153),
(156955, 'esES', '¡Eh, $n! ¡Aquí!', '', 28153),
(156954, 'esES', 'Saludoh, $p. He oído que ereh $gamigo:amiga; de Kiro y loh vulperah.\n\nNo tenemoh mucho tiempo pa negociacioneh, así que me conformaré con la palabra de Kiro.\n\nSi te apetece un poco de saqueo en mar abierto, ereh libre de unirte a mi tripulación.\n\nSalta al bote cuando quierah zarpar.', '', 28153),
(156953, 'esES', 'Muy... interesante. Haré que nuestros magos estudien el pergamino de inmediato. ¡Gracias!', '', 28153),
(156952, 'esES', '¡Saludoh, $p! Me alegra verte de nuevo.\n\n¿Ehtáh $gpreparado:preparada; pa un poco de saqueo marítimo? Zem\'lan ehtá ordenando a suh tripulacioneh que se vayan a loh barcoh y eso loh convierte en un objetivo fácil... si tieneh buena puntería.\n\nDe todah formah, ya te he vihto en acción, así que sé que acabaráh rápidamente con esoh ehqueletoh ahquerosoh.\n\nSalta al bote cuando ehtéh $glihto:lihta; pa salir.', '', 28153),
(156951, 'esES', 'Regresaré al Redención del Viento. Avisa a la gran almirante cuando estés $gpreparado:preparada; para volver a Boralus.', '', 28153),
(156950, 'esES', 'He surcado los mares durante años buscando los cangrejos más despiadados jamás vistos. ¿Quieres descubrir lo rápido que destrozo a tus mascotas?', '', 28153),
(156949, 'esES', '¡$n! ¿Qué puedo hacer por ti?', '', 28153),
(156948, 'esES', '¿Qué esh eshto?', '¿Qué esh eshto?', 28153),
(156947, 'esES', '¡$n! Me alegro de volver a verte. Ha pasado algún tiempo desde que serví bajo tu mando en Draenor.', '', 28153),
(156946, 'esES', '¡Los hijos de Kul Tiras sabrán lo que es el miedo!', '', 28153),
(156945, 'esES', 'Pero... ¿qué...?', 'Pero... ¿qué...?', 28153),
(156944, 'esES', '¡Puaj! ¡Qué amargo!', '¡Puaj! ¡Qué amargo!', 28153),
(156943, 'esES', 'Sabe a... garfios...', 'Sabe a... garfios...', 28153),
(156942, 'esES', '¿Qué soy...? ¿Un vrykul...? <¡hip!>', '¿Qué soy...? ¿Una vrykul...? <¡hip!>', 28153),
(156941, 'esES', 'Odio la... <¡hip!> cerveza rubia...', 'Odio la... <¡hip!> cerveza rubia...', 28153),
(156940, 'esES', 'Abre un portal para traer a las tropas.', 'Abre un portal para traer a las tropas.', 28153),
(156939, 'esES', 'Es un honor servir a la Horda como parte de mis estudios de telemancia con Oculeth.\n\nTambién será un honor abandonar este lugar en cuanto acabe con mi tarea.', '', 28153),
(156938, 'esES', 'Mis canes... eran... muy ladradores... y poco mordedores...', 'Mis canes... eran... muy ladradores... y poco mordedores...', 28153),
(156937, 'esES', '¡Perfecto, la presa ha venido a nosotros!', '¡Perfecto, la presa ha venido a nosotros!', 28153),
(156936, 'esES', 'Imbuye de poder este amuleto... ¡Puede que sea la única forma de salvar a Azeroth!', '', 28153),
(156935, 'esES', '¿Qué es eso? Siento una especie... de temblor.', '', 28153),
(156934, 'esES', '', 'Sujeto: Azeroth. Detectada arritmia severa.\n\nLas constantes superan los parámetros estándar.\n\nIntentando actualizar los informes de incidencias...\n\nERROR. ERROR. ERROR. ERROR.', 28153),
(156933, 'esES', '¡Uh! ¡Qué fuerte!', '', 28153),
(156932, 'esES', 'Mmmm... Me recuerda... a mis tiempos de minero... El truco estaba en golpear con el pico en ángulo... Mantiene la... mena...', '', 28153),
(156931, 'esES', '', 'ATENCIÓN: Detectadas múltiples brechas de contención.\n\nSe recomienda expurgar las siguientes instalaciones:\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld... Uld... Uld... Uld...', 28153),
(156930, 'esES', 'Uff... No me está sentando muy bien...', '', 28153),
(156929, 'esES', 'Según mis cálculos, hemos perdido un 2,539, repitiéndose por supuesto, de nuestro porcentaje de éxito. ¡Tenemos que acelerar las reparaciones!', 'Según mis cálculos, hemos perdido un 2,539, repitiéndose por supuesto, de nuestro porcentaje de éxito. ¡Tenemos que acelerar las reparaciones!', 28153),
(156928, 'esES', '¡Venga! ¡Reparad esos tanques, que vamos con retraso!', '¡Venga! ¡Reparad esos tanques, que vamos con retraso!', 28153),
(156927, 'esES', '¡Deprisa, chicos! Tenemos poco tiempo para desplegar estos tanques de asedio antes de que la Horda descubra que estamos aquí.', '¡Deprisa, chicos! Tenemos poco tiempo para desplegar estos tanques de asedio antes de que la Horda descubra que estamos aquí.', 28153),
(156926, 'esES', 'Ofrecer café espumoso del alcalde', 'Ofrecer café espumoso del alcalde', 28153),
(156925, 'esES', 'Ofrecer \"Aurora Borealis\"', 'Ofrecer \"Aurora Borealis\"', 28153),
(156924, 'esES', 'Ofrecer vodka amargo de Raíz Oscura', 'Ofrecer vodka amargo de Raíz Oscura', 28153),
(156923, 'esES', 'Ofrecer brandy de manzana de Brennadam', 'Ofrecer brandy de manzana de Brennadam', 28153),
(156922, 'esES', 'Ofrecer schnapps de Puntagarfio', 'Ofrecer schnapps de Puntagarfio', 28153),
(156921, 'esES', 'Ofrecer hidromiel de Mildenhall', 'Ofrecer hidromiel de Mildenhall', 28153),
(156920, 'esES', 'Ofrecer cerveza rubia de la Arboleda Blanca', 'Ofrecer cerveza rubia de la Arboleda Blanca', 28153),
(156919, 'esES', 'Ofrecer vinosangre Dientenegro', 'Ofrecer vinosangre Dientenegro', 28153),
(156918, 'esES', 'Llévanos de vuelta a Boralus.', 'Llévanos de vuelta a Boralus.', 28153),
(156917, 'esES', '', '¡Oh, no! ¡No te defraudaré, $n, lo juro!', 28153),
(156916, 'esES', '', 'Eh, ¿disculpa? ¿$gSeñor:Señora; $n? ¡Por aquí!', 28153),
(156915, 'esES', 'Ah, ¿querías algo?', '', 28153),
(156914, 'esES', '¿Én qué lugar deberíamos centrarnos?', '', 28153),
(156913, 'esES', 'Llévanos de vuelta a Zuldazar.', 'Llévanos de vuelta a Zuldazar.', 28153),
(156912, 'esES', '', '¿Necesitas un barco? ¿O mandar un mensaje?\n\n¿TAL VEZ UN POCO DE AYUDA PARA APUÑALAR A ALGUIEN?', 28153),
(156911, 'esES', 'Déjame en paz, colega... ¿No vesh que eshtoy... <¡hip!> ocupado?', '', 28153),
(156910, 'esES', '', 'Sujeto: Azeroth.\n\nATENCIÓN: Fallo catastrófico del sistema en curso.\n\nIntegridad planetaria al...\n\ncalculando... calculando... calculando...', 28153),
(156909, 'esES', 'Esto no estaba en mis cálculos...', 'Esto no estaba en mis cálculos...', 28153),
(156908, 'esES', 'Según mis cálculos, tus probabilidades de éxito son iguales a... ¡cero!', 'Según mis cálculos, tus probabilidades de éxito son iguales a... ¡cero!', 28153),
(156907, 'esES', '', 'Ese jabaehpín tenía un mojo muy poderoso, pero no era rival pa ti.', 28153),
(156906, 'esES', '', 'La tierra se alza bajo lah órdeneh de un chamán jabaehpín. Acaba con ehta amenaza anteh de que fruhtre nuehtroh planeh.', 28153),
(156905, 'esES', 'Descansaré mejor esta noche sabiendo que Canto Tormenta cuenta con algunas rocas merodeadoras menos.', '', 28153),
(156904, 'esES', '¡La cría de pterrordáctilo salvaje chilla alarmada!', '¡La cría de pterrordáctilo salvaje chilla alarmada!', 28153),
(156903, 'esES', 'Aquí hay un clamatierras jabaespín que está reuniendo su propio ejército de elementales. ¡Merma sus filas y acaba con él!', '', 28153),
(156902, 'esES', 'Gracias. Creía que estaba acabado.', 'Gracias. Creía que estaba acabada.', 28153),
(156901, 'esES', 'Doy gracias por que aún quede gente buena en este mundo.', 'Doy gracias por que aún quede gente buena en este mundo.', 28153),
(156900, 'esES', '¡Gracias! Desde aquí puedo seguir solo.', '¡Gracias! Desde aquí puedo seguir sola.', 28153),
(156899, 'esES', 'Venga a quienes no nos pudimos salvar.', 'Venga a quienes no nos pudimos salvar.', 28153),
(156898, 'esES', 'No tienes ni idea de lo que nos han hecho pasar...', 'No tienes ni idea de lo que nos han hecho pasar...', 28153),
(156897, 'esES', '¡Me has salvado la vida!', '¡Me has salvado la vida!', 28153),
(156896, 'esES', 'Te doy las gracias.', 'Te doy las gracias.', 28153),
(156895, 'esES', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 28153),
(156894, 'esES', 'Tu valentía no tiene igual.', 'Tu valentía no tiene igual.', 28153),
(156893, 'esES', 'No olvidaré tu amabilidad.', 'No olvidaré tu amabilidad.', 28153),
(156892, 'esES', '¡Llegas justo a tiempo!', '¡Llegas justo a tiempo!', 28153),
(156891, 'esES', 'Tu compasión no caerá en el olvido.', 'Tu compasión no caerá en el olvido.', 28153),
(156890, 'esES', 'Te debo la vida.', 'Te debo la vida.', 28153),
(156889, 'esES', 'Será mejor que vuelva al combate.', 'Será mejor que vuelva al combate.', 28153),
(156888, 'esES', '¡Hay que removerlo hasta que no queden grumos!', '', 28153),
(156887, 'esES', '¡Mézclalo bien!', '', 28153),
(156886, 'esES', '¡Y por fin, un poco de calor!', '', 28153),
(156885, 'esES', '¡Un toquecito de sabor!', '', 28153),
(156884, 'esES', '¡Uno por uno!', '', 28153),
(156883, 'esES', 'Vale la pena salvar este valle.', '', 28153),
(156882, 'esES', '¿Tienes suministros de más?', '¿Tienes suministros de más?', 28153),
(156881, 'esES', 'Rezan ha... ha muerto. Ese... engendro no eh un loa.', '', 28153),
(156880, 'esES', '¡Ah! Esta cámara está en ruinas. ¡No aguantará mucho más!', '', 28153),
(156879, 'esES', 'Kul Tiras se enfrenta a un grave peligro, Magni. Pero supongo que has venido por... otras razones.', '', 28153),
(156878, 'esES', '', '¿Dónde habré puehto mi caña de pehcar? Juraría que ehtaba aquí...', 28153),
(156877, 'esES', '', 'Hay buena pehca y caza por aquí, si sabeh dónde mirar.', 28153),
(156876, 'esES', '<La madera deteriorada cruje y chirría mientras el suave viento roza el costado del carruaje.\n\nParece que una de las ruedas está atascada>.', '', 28153),
(156875, 'esES', '<Dar un empujoncito al carro>.', '<Dar un empujoncito al carro>.', 28153),
(156874, 'esES', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca del barco de la Horda. ¡Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca del barco de la Horda. ¡Cuidado!', 28153),
(156873, 'esES', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca del barco de la Alianza. ¡Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca del barco de la Alianza. ¡Cuidado!', 28153),
(156872, 'esES', '', 'El muro debe desmoronarse, el mar volverá.', 28153),
(156871, 'esES', '$n... Ve a ayudar a otro sitio. Te avisaré cuando vuelva a necesitarte.', '', 28153),
(156870, 'esES', 'Lilian. Stone. Venid conmigo, ayudadme a localizar a uno de esos... Sabiomar.', '', 28153),
(156869, 'esES', 'Estoy harto de tanto obstáculo repetitivo.', '', 28153),
(156868, 'esES', '¿Y bien, $n? ¿Qué has encontrado? Dámelo.', '', 28153),
(156867, 'esES', 'Ahora tienes trabajo que hacer. La plataforma de teletransporte te llevará de nuevo con tus aliados. Buena suerte... a todos.', '', 28153),
(156866, 'esES', 'Seguiré buscando la manera de sanar el daño que ha sufrido Azeroth. Cuando te necesite, me pondré en contacto contigo a través de ese talismán.', '', 28153),
(156865, 'esES', 'Mantén ese amuleto cerca del corazón. Te ayudará a superar la oscuridad que se avecina.', '', 28153),
(156864, 'esES', 'Así que lo único que necesitamos es algo que nos conduzca hasta él.', '', 28153),
(156863, 'esES', '', 'Los muros de la fortaleza se desmoronarán ante tus ataques.', 28153),
(156862, 'esES', '', 'Ataca los muros a la señal, Skoloth.', 28153),
(156861, 'esES', '', 'Recibirás una recompensa por tus servicios.', 28153),
(156860, 'esES', '', 'Amalia, cuéntale a Nathanos lo de los Sabiomar.', 28153),
(156859, 'esES', '', 'Con ayuda.. podremos localizar... los restos del naufragio...', 28153),
(156858, 'esES', '', 'Los Sabiomar... sacerdotes... del mar...', 28153),
(156857, 'esES', '', 'Ah, creo que eso lo tenemos cubierto.', 28153),
(156856, 'esES', '¡¿Perdido en el mar?! ¡Pero necesitamos su cuerpo!', '', 28153),
(156855, 'esES', '', 'Mariscal M. Valentine... vencedor de la Segunda Guerra... perdido en el mar...', 28153),
(156854, 'esES', 'Quiero regresar al Estrecho de Tiragarde.', 'Quiero regresar al Estrecho de Tiragarde.', 28153),
(156853, 'esES', 'Mantendré las velas izadas mientras vas ahí fuera y haces tu parte.', '', 28153),
(156851, 'esES', '¡¿DÓNDE ESTÁ EL CUERPO?!', '', 28153),
(156850, 'esES', 'Un momento... ¿Qué es esto?', '', 28153),
(156849, 'esES', 'Valentine... Nos has evitado durante bastante tiempo.', '', 28153),
(156848, 'esES', 'No haremos esperar a Valentine.', '', 28153),
(156847, 'esES', 'Sabletrón activado... ¡Ah!', '', 28153),
(156846, 'esES', '¿Pero qué...? ¡Aún no estamos listos!', '', 28153),
(156845, 'esES', '¡Nada resiste ante un sabletrón!', '', 28153),
(156844, 'esES', '¡Cinco minigatos se unen para formar un supergato!', '', 28153),
(156843, 'esES', 'Tu influencia ya no podrá proteger este navío.', '', 28153),
(156842, 'esES', 'Desaparece, maldita oscuridad.', '', 28153),
(156841, 'esES', 'Las mareas devoran tu carne maldita.', '', 28153),
(156840, 'esES', '', '¡No dejes que hagan daño a Dot!', 28153),
(156839, 'esES', '', '¡Ayudaaaa!', 28153),
(156838, 'esES', 'Pon rumbo a Vol\'dun.', 'Pon rumbo a Vol\'dun.', 28153),
(156837, 'esES', 'Aunque esté muerta, aún la veré en mis pesadillas.', '', 28153),
(156836, 'esES', '¡Mira! Es una... eh... ¡cosa! ¡Mátala! ¡Mátala hasta que se muera!', '', 28153),
(156835, 'esES', '|A:Warfront-AllianceWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Alianza!', '|A:Warfront-AllianceWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Alianza!', 28153),
(156834, 'esES', 'Los sethrak han descubierto el carro de Meerah en las dunas. Está sola y probablemente necesite ayuda si deciden atacarla.', '', 28153),
(156833, 'esES', '', 'Como ordenes, por la voluntad de la Dama Oscura.', 28153),
(156832, 'esES', '', 'Trae de vuelta a este hombre. Ha sido elegido para convertirse en Renegado.', 28153),
(156831, 'esES', 'Lilian. Podemos encontrar otros Sabiomar. Sabes que su familia no lo aceptará.', '', 28153),
(156830, 'esES', '', 'Lilian Voss. ¿Por qué recurres a mí?', 28153),
(156829, 'esES', 'Un pequeño inconveniente. Demuestra que no cambia nuestro plan en absoluto.', '', 28153),
(156828, 'esES', 'Querer es una palabra muy fuerte. Es algo que... estoy dispuesto a soportar para ayudar a mi familia.', '', 28153),
(156827, 'esES', '', 'Con dolor.', 28153),
(156826, 'esES', 'Pero parte de ti sobrevivió, ¿cierto?', '', 28153),
(156825, 'esES', '', 'Esperemos que vivas lo suficiente para ayudarnos a encontrar a Valentine.', 28153),
(156824, 'esES', '¡Vamos!', '¡Vamos!', 28153),
(156823, 'esES', '', 'Puedes solicitar más fuerzas de la Horda en cualquier momento. Solo tienes que dar la orden.', 28153),
(156822, 'esES', 'Mmm. Asegúrate de hacerlo.', '', 28153),
(156821, 'esES', '', 'Yo la traeré, Nathanos. Continúa sin nosotras.', 28153),
(156820, 'esES', '', '¡Alto!', 28153),
(156819, 'esES', '', '¡AAAAAH!', 28153),
(156818, 'esES', '', 'No... No puedo...', 28153),
(156817, 'esES', '', 'Me parece un buen comienzo. Veamos qué más sabes hacer.', 28153),
(156816, 'esES', 'Hay fuerzas de la Alianza y Kul Tiras en Fuerte Sabio. Están esperando refuerzos y en este momento son vulnerables.', '', 28153),
(156815, 'esES', '¿Mi familia está a salvo?', '', 28153),
(156814, 'esES', '', 'Bien. Demuestra que puedes ser útil a la Horda y ya veremos cuánto tiempo te permitimos vivir esta vida.', 28153),
(156813, 'esES', 'Están a salvo. Ayúdanos y seguiremos ocupándonos de que lo estén.', '', 28153),
(156812, 'esES', '<tose> Haré... todo lo que pueda, señorita Voss. Quieres localizar algo o a alguien, ¿cierto? Déjame ver qué puedo hacer sin mi libro...', '', 28153),
(156811, 'esES', '', 'No pongas a prueba mi paciencia o haré que lamentes no haber muerto a causa de tu enfermedad. Necesito comprobar la calidad de tu magia antes de continuar.', 28153),
(156810, 'esES', 'Señorita Voss. ¿Cuando regresaste conservabas alguna enfermedad, alguna dolencia que tuvieras en vida?', '', 28153),
(156809, 'esES', '', 'Lilian Voss. Yo soy la que hace las preguntas. ¿Sabes rastrear personas? ¿Objetos?', 28153),
(156808, 'esES', 'Una Renegada. Tal vez sea una <tose> señal. ¿Sí, señorita...?', '', 28153),
(156807, 'esES', '', '$n tiene razón, en cierto modo. No sufrirás si nos ayudas, preferiblemente antes de morir.', 28153),
(156806, 'esES', 'Que la Dama Oscura cuide de ti.', '', 28153),
(156805, 'esES', 'Necesito refuerzos.', 'Necesito refuerzos.', 28153),
(156804, 'esES', '¿Buscando refuerzos? No tienes más que pedirlo y organizaré el transporte desde Ventormenta.', '', 28153),
(156803, 'esES', 'Tenemos poco tiempo. ¿Qué hay que hacer?', '', 28153),
(156802, 'esES', 'Es muy difícil matarte... mucho más que a ese enemigo.', '', 28153),
(156801, 'esES', 'Ahora estamos trabajando sin un plan concreto, así que necesito que te ocupes de la amenaza. Y que no mueras.', '', 28153),
(156799, 'esES', '%s mastica la comida fresca de forma ruidosa.', '', 28153),
(156798, 'esES', '%s mastica las verduras con entusiasmo.', '', 28153),
(156797, 'esES', '%s entierra el hocico en la comida.', '', 28153),
(156796, 'esES', '¡Te aplastaré la cabeza!', '¡Te aplastaré la cabeza!', 28153),
(156795, 'esES', '¿Quién quiere ser el siguiente en morir?', '¿Quién quiere ser el siguiente en morir?', 28153),
(156794, 'esES', '¡Vamos!', '¡Vamos!', 28153),
(156793, 'esES', '[SECUENCIA CINEMÁTICA] - ¡Aparece Jaina! ¡Sus fuerzas consiguen atravesar los muros de la fortaleza de Lordaeron! Y por cierto, es una auténtica pasada.', '[SECUENCIA CINEMÁTICA] - ¡Aparece Jaina! ¡Sus fuerzas consiguen atravesar los muros de la fortaleza de Lordaeron! Y por cierto, es una auténtica pasada.', 28153),
(156792, 'esES', '[SECUENCIA CINEMÁTICA] - Sylvanas está esperando en el salón del trono cuando llega Anduin. Anduin le ofrece la posibilidad de rendirse. En lugar de eso, vuela toda la ciudad. Bueno, ¿qué te esperabas?', '[SECUENCIA CINEMÁTICA] - Sylvanas está esperando en el salón del trono cuando llega Anduin. Anduin le ofrece la posibilidad de rendirse. En lugar de eso, vuela toda la ciudad. Bueno, ¿qué te esperabas?', 28153),
(156791, 'esES', '', 'Si pudiera hacer que Kul Tiras regresara a la Alianza...', 28153),
(156790, 'esES', '', 'Mi gente posee la flota más poderosa de todo Azeroth.', 28153),
(156789, 'esES', '', 'Es un hechizo sencillo, si el sujeto está dispuesto.', 28153),
(156788, 'esES', '', 'Toma. Bébete esto.', 28153),
(156787, 'esES', '', 'De acuerdo, Amalia. Dame un segundo...', 28153),
(156786, 'esES', 'He venido a pedirte ayuda, no a matarte.', 'He venido a pedirte ayuda, no a matarte.', 28153),
(156785, 'esES', '<tose> La Horda. Pensé que aquí moriría en paz.\n\n¿Y bien? ¿A qué estás esperando?', '', 28153),
(156784, 'esES', '', 'Eh... $n, junto a la trituradora.', 28153),
(156783, 'esES', 'Si queremos la ayuda de ese Sabiomar, debemos darnos prisa.', '', 28153),
(156782, 'esES', '', 'No puedes hacer nada que sea peor que la enfermedad... Se fue al este para morir tranquilo, lejos de los niños. Por favor, déjanos en paz.', 28153),
(156781, 'esES', 'Solo quiero saber dónde está tu esposo. Ni tu familia ni tú sufriréis ningún daño.', '', 28153),
(156780, 'esES', '', 'La Horda... ¿Venís a robarme algo más? Mi esposo se está muriendo, no tengo una triste moneda... Dejad a mis hijos en paz, por favor.', 28153),
(156779, 'esES', 'Eso no es nada honorable. Podemos preguntar sin más. No tenemos reparos con que una madre llore.', '', 28153),
(156778, 'esES', 'Guardad las distancias.', '', 28153),
(156777, 'esES', 'Hora de la artillería pesada.', '', 28153),
(156776, 'esES', '¡Y yo traigo la tormenta de arena!', '', 28153),
(156775, 'esES', 'Tú pintas la diana...', '', 28153),
(156774, 'esES', 'Me encanta mi trabajo.', '', 28153),
(156773, 'esES', '¡Ha! ¡Parece que ese bicho ha acabado atragantándose!', '', 28153),
(156772, 'esES', 'El gran perro anda suelto.', '', 28153),
(156771, 'esES', 'Nunca sabrán lo que les alcanzó.', '', 28153),
(156770, 'esES', '¿Ha llamado alguien a un reconfigurador?', '', 28153),
(156769, 'esES', '¡Creo que te gustará!', '', 28153),
(156768, 'esES', 'RA-8 en camino..', '', 28153),
(156767, 'esES', 'Tenemos turbulencias, vamos a bailar un poco.', '', 28153),
(156766, 'esES', 'Estamos en la cima; salvo problemas...', '', 28153),
(156765, 'esES', '', 'Hnngh...', 28153),
(156764, 'esES', '', 'Cuanto antes reúnas esas flores, antes podré ayudar a Amalia a estar en condiciones.', 28153),
(156763, 'esES', 'He oído rumores de gusanos gigantes que se alimentan de podredumbre y siembran el caos en la superficie. ¡Tenemos que detenerlos!', '', 28153),
(156762, 'esES', 'Buen trabajo, los has salvado. ¡Seguro que ahora todos quieren escapar y ser como tú!', '', 28153),
(156761, 'esES', '¡Unos críos de Ribera Inerte se escaparon para hacerse piratas y ahora son prisioneros de los Marea de Hierro! ¡Salva a esos niños!', '', 28153),
(156760, 'esES', '', 'Psst... ¡$n, por aquí!', 28153),
(156759, 'esES', '', 'Esa behtia ya no sembrará el terror entre mi gente. Vuehtroh actoh complacerán a loh loa.', 28153),
(156758, 'esES', '', 'Esoh gusanoh ehtán atiborrándose de podredumbre y sembrando el caoh en la superficie. ¡Acabemoh con elloh!', 28153),
(156757, 'esES', 'Dijeron que habría caramelos.', '¿Ahora soy pirata?', 28153),
(156756, 'esES', 'Mira, jefe, sé que eres tú quien pone la pasta para esta expedición, pero Gallywix querrá que la Dama Oscura se lleve su parte.', '', 28153),
(156755, 'esES', 'Necesito un transporte al Cementerio Lomatúmulo.', 'Necesito un transporte al Cementerio Lomatúmulo.', 28153),
(156754, 'esES', '', '¡Tengo los cohetes más seguros de todo Kul Tiras!$b$bQue no te engañe mi apellido.', 28153),
(156753, 'esES', 'Retirada. Vivid pa luchar otro día.', '', 28153),
(156752, 'esES', 'Zandalari, retiraoh y reagrupaoh. Loh dejaremoh vivir un día máh.', '', 28153),
(156751, 'esES', '¡Dehtruid a loh invasoreh!', '', 28153),
(156750, 'esES', 'Soih débileh.', '', 28153),
(156749, 'esES', 'Vuehtra muerte se acerca.', '', 28153),
(156748, 'esES', '¡Soy el temible pirata Beuford! ¡No habrá supervivientes!', '¡Creo que veo a mi gato!', 28153),
(156747, 'esES', 'Adéntrate en la tormenta y acabemos con esto.', '', 28153),
(156746, 'esES', '¡No eres pirata!', '¡Me dijeron que me darían un sombrero!', 28153),
(156745, 'esES', '¡Aagh! ¡Dame un poco de ron!', '¡Tengo que ir a la cubierta de popa!', 28153),
(156744, 'esES', '', 'Bien, no te ensucies las manos.', 28153),
(156743, 'esES', 'Quiero regresar a Zuldazar.', 'Quiero regresar a Zuldazar.', 28153),
(156742, 'esES', 'Mantendré lah velah dehplegadah pa que podamoh ehcapar rápidamente. ¡Ve a por la azerita!', '', 28153),
(156741, 'esES', '', '$n, yo me ocuparé del cuerpo. Vuelve con Nathanos y dile que todo va según lo planeado.', 28153),
(156740, 'esES', 'No participaré en la conversión de este hombre en Renegado. Encárgate tú.', 'No participaré en la conversión de este hombre en Renegado. Encárgate tú.', 28153),
(156739, 'esES', '', 'Aprenderás a lidiar con ello. Y yo te ayudaré.', 28153),
(156738, 'esES', '¡No necesito que me salven!', 'Ahora soy pirata. No tengo que escucharte.', 28153),
(156737, 'esES', '', 'Ahora eres de los nuestros; no te aceptarán.', 28153),
(156736, 'esES', 'Lilian, tú mata a Zelling.', 'Lilian, tú mata a Zelling.', 28153),
(156735, 'esES', '', 'Stone, entiendo por lo que estás pasando. Pero no puedes dejar que el cambio controle tu mente como me paso a mí.', 28153),
(156734, 'esES', '¡No es justo! Iba a ser pirata.', '¡Grettly me vendió a los piratas!', 28153),
(156733, 'esES', 'Lilian, haz lo que debas con Zelling.', 'Lilian, haz lo que debas con Zelling.', 28153),
(156732, 'esES', '', 'Ya veremos. Puede que esta vez sea diferente.', 28153),
(156731, 'esES', '', 'Es terrible. Los que no huyen de ti no vuelven a tratarte igual. Te miras en el espejo y solo ves un monstruo, algo que no eres tú.', 28153),
(156730, 'esES', 'Por favor... Necesito... cuidar... de mi familia... pase lo que pase.', '', 28153),
(156729, 'esES', '', 'Te rechazarán si te conviertes en uno de nosotros. Al mirarte en el espejo solo verás un monstruo.', 28153),
(156728, 'esES', 'Señorita Voss, <tose> por favor... tráeme de vuelta... Debo ayudar a mi familia... Haré lo que sea... lo que sea...', '', 28153),
(156727, 'esES', '', '¿Qué? ¡Tu familia pensará que eres un monstruo, no digas tonterías!', 28153),
(156726, 'esES', '', 'De acuerdo. De todas formas, hay algo que quiero saber.', 28153),
(156725, 'esES', '<resopla> Lo... siento. No... puedo... No queda nada... dentro de mí...', '', 28153),
(156724, 'esES', '', '¡Zelling! ¡Maldito seas, te necesitamos vivo!', 28153),
(156723, 'esES', '¡Sí! ¡Por fin, otórgame la vida eterna, estoy listo!', '', 28153),
(156722, 'esES', '', 'De acuerdo, Zelling. ¿Entiendes de verdad lo que está a punto de ocurrir?', 28153),
(156721, 'esES', '¡Buen trabajo! Les has enseñado cómo hacemos las cosas en el valle.', '', 28153),
(156720, 'esES', 'Los exploradores nos han informado de una nueva amenaza en la zona. Acaba con ella antes de que se convierta en un problema mayor.', '', 28153),
(156719, 'esES', 'Ten cuidado, Jaina. Que la Luz te acompañe.', '', 28153),
(156718, 'esES', '', 'Regresaré con la flota... o no regresaré.', 28153),
(156717, 'esES', 'Será difícil... y peligroso.', '', 28153),
(156716, 'esES', 'Estoy de acuerdo... y creo que puedes conseguirlo.', '', 28153),
(156715, 'esES', '', 'Solo conseguiré hacerles volver si enmiendo el pasado.', 28153),
(156714, 'esES', 'Jaina, tú eres el motivo por el que dejaron la Alianza.', '', 28153),
(156713, 'esES', '', 'Pues tendremos que conseguir nuestros propios aliados.', 28153),
(156710, 'esES', '', 'Muéstranos... Muéstranos lo que ocurrió...', 28153),
(156709, 'esES', 'Si la Horda se alía con los Zandalari, no podremos detenerlos.', '', 28153),
(156708, 'esES', '¡Imposible! Es uno de los trucos de Sylvanas. Tiene que serlo...', '', 28153),
(156707, 'esES', 'Y una flota Zandalari gigantesca.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'esES', 'Los supervivientes dicen que se toparon con una magia extraña y aterradora.', '', 28153),
(156705, 'esES', 'Solo ha regresado uno.', '', 28153),
(156704, 'esES', 'Lo sé. ¿Qué hay de los ocho buques de guerra que los perseguían?', '', 28153),
(156703, 'esES', 'Una princesa y un profeta.', '', 28153),
(156702, 'esES', 'Hace poco, agentes de la Horda se colaron en las Mazmorras y liberaron a dos prisioneros Zandalari.', '', 28153),
(156701, 'esES', 'Jaina, ¿podrías ayudarnos a ver lo que vieron los supervivientes?', '', 28153),
(156700, 'esES', 'En esta zona han muerto muchos viajeros. Necesito que te ocupes del responsable de estos ataques.', '', 28153),
(156699, 'esES', 'Estamos todos. ¿Qué noticias traes, maestro de espías?', '', 28153),
(156698, 'esES', '¡Excelente trabajo! Sabía que podíamos contar contigo para protegernos.', '', 28153),
(156697, 'esES', 'Lo siguiente que quiero eh una nave. ¡Le pondré el nombre de mi hijo!', '', 28153),
(156696, 'esES', '¡Ehte lo robé yo mihmo! ¡Lo llamé Fortuna de Mala, en honor a mi hija!', '', 28153),
(156695, 'esES', '¡Si a mí me dicen que vamoh a tratar con piratah, yo digo que voy a necesitar un barco pirata!', '', 28153),
(156694, 'esES', '¡Los nagas están tramando algo!', '', 28153),
(156693, 'esES', '¡Sí... la eternidad...!', '', 28153),
(156692, 'esES', 'Cuando ehtéh $glihto:lihta;, utiliza la cuerda. ¡Ehtoy deseando enseñarte mi barco!', '', 28153),
(156691, 'esES', '', '¡El próximo que se queje está muerto!', 28153),
(156690, 'esES', '', '¡Trabajad más rápido, bastardos patéticos!', 28153),
(156689, 'esES', '', '¡Más trabajo y menos charla! ¡Esta azerita no se va a extraer sola!', 28153),
(156688, 'esES', '', '¿A eso lo llamáis trabajar? ¡Perros! ¡Tenéis suerte de que no os paguemos por esto!', 28153),
(156687, 'esES', '', '¡Volved al trabajo, perros! ¡Poned todo vuestro empeño!', 28153),
(156686, 'esES', '¡Por favor, mátame! ¡Entrégame a la eternidad como Renegado!', '', 28153),
(156685, 'esES', 'Sé que le has estado robando a la compañía. Estoy aquí para asegurarme de no se repita...', 'Sé que le has estado robando a la compañía. Estoy aquí para asegurarme de no se repita...', 28153),
(156684, 'esES', '¿Quieres llevarte una paliza? ¡Ocúpate de tus asuntos!', '¿Quieres llevarte una paliza? ¡Ocúpate de tus asuntos!', 28153),
(156683, 'esES', 'Sigue andando, tripulante. Aquí no hay nada que ver...', 'Sigue andando, tripulante. Aquí no hay nada que ver...', 28153),
(156682, 'esES', '¿Qué estás mirando, tripulante?', '¿Qué estás mirando, tripulante?', 28153),
(156681, 'esES', '<Tose>. Señorita Voss, ¿cómo te convertiste en Renegada?', '', 28153),
(156680, 'esES', 'La Horda está robando azerita de la Compañía Comercial Gobernalle. ¡Aplasta a nuestros enemigos y devuelve esos recursos a la Séptima Legión!', '', 28153),
(156679, 'esES', '¡Solo robé para llenar un corazón vacío que jamás ha conocido el amor!', '¡Solo robé para llenar un corazón vacío que jamás ha conocido el amor!', 28153),
(156678, 'esES', '¡Mi pobre educación me obligó a hacerlo!', '¡Mi pobre educación me obligó a hacerlo!', 28153),
(156677, 'esES', '¡No lo volveré a hacer, lo prometo!', '¡No lo volveré a hacer, lo prometo!', 28153),
(156676, 'esES', '¡Ese lobo de mar de Harrington ha pedido un poco de músculo!', '¡Ese lobo de mar de Harrington ha pedido un poco de músculo!', 28153),
(156675, 'esES', '¡No volveré a robar! ¡Nunca más!', '¡No volveré a robar! ¡Nunca más!', 28153),
(156674, 'esES', '¡No me mates, por favor! ¡No volveré a robar!', '¡No me mates, por favor! ¡No volveré a robar!', 28153),
(156673, 'esES', 'Unos exiliados de Zuldazar retienen a nuestros soldados y piden un rescate. No negociamos con aliados de la Horda. ¡Muéstrales la fuerza de la Alianza!', '', 28153),
(156672, 'esES', 'Te has librado fácilmente de ellos. Bien hecho.', '', 28153),
(156671, 'esES', 'Nuestros espías han localizado un pequeño campamento de tropas de la Horda en las dunas. ¡Ataca rápido y diezma las fuerzas enemigas!', '', 28153),
(156670, 'esES', 'Ha sido un placer hacer negocios contigo. ¡Si algún día quieres trabajo como pirata, eres $gbienvenido:bienvenida; en mi tripulación!', '', 28153),
(156669, 'esES', 'Soy un hombre de palabra, $c. ¡El arcón del capitán es todo tuyo!', '', 28153),
(156668, 'esES', 'Me reuniré contigo en las dependencias del capitán cuando Hartford haya muerto. No te preocupes por el arcón, ¡todo lo que hay dentro será tuyo!', '', 28153),
(156667, 'esES', '', 'Aún no hemos acabado. Tienes buena información, pero aún tenemos que ver lo poderoso que eres.', 28153),
(156666, 'esES', '¡Por favor! Con eso tiene que bastar, tu adalid ha provocado el caos y la destrucción en Fuerte Sabio. ¡Conviérteme en Renegado!', '', 28153),
(156665, 'esES', '', '¿Hicimos... mal... al apoyar a la Alianza?', 28153),
(156664, 'esES', '', '¡La Horda nunca quebrará la voluntad de Kul Tiras!', 28153),
(156663, 'esES', 'Hay que arrojar... el libro... al mar...', '', 28153),
(156662, 'esES', '¡No me arrebatarás este libro, es demasiado peligroso!', '', 28153),
(156661, 'esES', '', 'Morirías sin tiempo para volver a soltar una de tus toses patéticas, Zelling. ¿Quieres ponerme a prueba?', 28153),
(156660, 'esES', '<resopla> ¿No os preocupa que os ataque? ¿Que intente huir?', '', 28153),
(156659, 'esES', '¿Se volvió loca la capitana Stone al convertirse? Sé muy bien lo que le pasó.', '', 28153),
(156658, 'esES', '', 'La conversión a Renegado no es una ciencia exacta. Sin duda, el cuerpo y la mente cambian, pero... es imposible saber hasta qué punto. O cómo se sobrellevará el proceso.', 28153),
(156657, 'esES', 'No, pero ¿puedes responder una pregunta? Cuando uno se convierte en Renegado, ¿desaparecen todas las enfermedades?', '', 28153),
(156656, 'esES', '¡Contigo a mi lado, estaré un paso más cerca de escapar de este maldito desierto!', '', 28153),
(156655, 'esES', 'Reúnete conmigo en el Puerto Peñarroja cuando hayas terminado el trabajo.', '', 28153),
(156654, 'esES', 'Vaya, eso ha sido... original.', '', 28153),
(156653, 'esES', 'Nuestros aliados no podrán completar su misión con la Horda merodeando por estas ruinas, pero los Hierro Negro saben cómo solucionar este problema...', '', 28153),
(156652, 'esES', '2 minutos para que dé comienzo la batalla por Stromgarde.', '', 28153),
(156651, 'esES', 'Creo que he perdido mi fantástico sombrero.', 'Creo que he perdido mi fantástico sombrero.', 28153),
(156650, 'esES', 'Llévanos al Valle Canto Tormenta.', 'Llévanos al Valle Canto Tormenta.', 28153),
(156649, 'esES', 'Bien hecho. Veamos si algo de esto nos resulta útil.', '', 28153),
(156648, 'esES', 'Estas ruinas parecen ser de un templo que cayó al mar. La presencia de los nagas también es preocupante. Buena suerte con la exploración.', '', 28153),
(156647, 'esES', 'Estoy listo para negociar, Ty\'jin.', 'Estoy lista para negociar, Ty\'jin.', 28153),
(156646, 'esES', 'Avísame cuando ehtéh $glihto:lihta; pa empezar, $gjefe:jefa;.', '', 28153),
(156645, 'esES', 'Bien hecho. Mejor ocuparse ahora de la amenaza que dejarlo para más tarde.', '', 28153),
(156644, 'esES', 'Nuestros exploradores han descubierto una plaga de múrlocs. No podemos dejar que se multipliquen y nos ataquen.', '', 28153),
(156643, 'esES', '', 'Buen trabajo, adalid. Hoy loh loa noh sonríen.', 28153),
(156642, 'esES', '', 'Ventura y Cía. profana la tierra de unoh valiosoh aliadoh. A loh loa no leh va a guhtar. Detenloh y arregla la situación.', 28153),
(156641, 'esES', '', '¡Bien hecho! Loh tortolianoh recordarán quién loh salvó de su fatal dehtino.', 28153),
(156640, 'esES', '', 'Me informan de que loh nagah de aquí han ehclavizado a unoh tortolianoh. No sabemoh cuál eh su propósito, ¡tenemoh que liberarloh!', 28153),
(156639, 'esES', 'Desde siempre, los Sabiomar han guiado a las almas perdidas... pero no así.', '', 28153),
(156637, 'esES', 'Bien hecho. Esperemos que los tortolianos nos devuelvan el favor en el futuro.', '', 28153),
(156636, 'esES', 'Estoy listo para zarpar rumbo a Lordaeron.', 'Estoy lista para zarpar rumbo a Lordaeron.', 28153),
(156635, 'esES', 'Ventura y Cía. está liando una buena en la costa. Si ponemos orden, nos ganaremos el favor de los tortolianos.', '', 28153),
(156634, 'esES', '', 'La escuela está cerrada... para siempre...', 28153),
(156633, 'esES', '', '¡Te voy a dar una lección!', 28153),
(156632, 'esES', '¡Buen trabajo! No me atrevo a pensar qué iban a hacer con esos tortolianos.', '', 28153),
(156631, 'esES', 'Nos informan de que los nagas de aquí han apresado a unos tortolianos. Tenemos que impedir lo que sea que planeen.', '', 28153),
(156630, 'esES', '', '¡He visto a granjeros luchar mejor que tú!', 28153),
(156629, 'esES', '¡Bien hecho! ¡Estamos más cerca de la victoria!', '', 28153),
(156628, 'esES', 'Eso las mantendrá a raya por ahora. Bien hecho.', '', 28153),
(156627, 'esES', 'Las víboras emplumadas son famosas por sus plagas agresivas, ¡pero esto se nos está yendo de las manos! Destruye sus huevos.', '', 28153),
(156626, 'esES', 'Estas servirán. Nuestros soldados heridos te estarán agradecidos, adalid.', '', 28153),
(156625, 'esES', 'Los suministros locales pueden sernos útiles. Recoge glándulas salivares de los pterrordáctilos salvajes. Sus propiedades curativas ayudarán a nuestros heridos.', '', 28153),
(156624, 'esES', '¡Normal que los ravasaurios puedan comer casi de todo! Esto nos será muy útil. Gracias.', '', 28153),
(156623, 'esES', 'Necesitamos suministros duraderos. Los ravasaurios de esta tierra son famosos por tener paredes estomacales resistentes. ¿Nos consigues unas cuantas?', '', 28153),
(156622, 'esES', 'Aaaah... Al fondo del mar... contigo...', '', 28153),
(156621, 'esES', '¿Qué es esto? ¿Un motín? ¡Tomad, puercos!', '', 28153),
(156620, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(156619, 'esES', '', 'He terminado mi investigación por el momento. Gracias por la ayuda.', 28153),
(156618, 'esES', '', '¡Así la Horda aprenderá a no interferir! Esta magia nunca debe caer en sus manos...', 28153),
(156617, 'esES', '', 'Agradezco mucho tu ayuda. Esta barrera es muy resistente...', 28153),
(156616, 'esES', '¡Tengo la inmortalidad a mi alcance! Estoy deseando convertirme en Renegado, ¡imagina las posibilidades!\n\nCuando tengas un momento, cuéntame cómo es. La no-muerte, la eternidad, ¡tener el mundo en tus manos!', '', 28153),
(156615, 'esES', 'Me niego a morir aquí por culpa de una... enfermedad. Debo seguir con vida para mantener a mi familia sana y salva.', '', 28153),
(156614, 'esES', 'No molestes a los muertos, $r.', '', 28153),
(156613, 'esES', '', '¡Me vendría bien un poco de ayuda!', 28153),
(156612, 'esES', 'Si no estás avanzando, te estás quedando atrás. ¡Es lo que siempre digo!', '', 28153),
(156611, 'esES', '', 'Tengo que hacer unas pruebas y reunir información. Vigila que nadie interfiera.', 28153),
(156610, 'esES', '', 'Tal vez podamos utilizar esta magia, o incluso replicarla.', 28153),
(156609, 'esES', '', '¡La magia que han usado aquí es fascinante! Es la primera vez que veo algo así.', 28153),
(156608, 'esES', '', '¡Esto no ha acabado!', 28153),
(156607, 'esES', '¿Pero puedeh permitirte perder tanto tiempo?', '', 28153),
(156606, 'esES', 'Necesito un disfraz nuevo.', 'Necesito un disfraz nuevo.', 28153),
(156605, 'esES', '¡La Horda está aquí, corred! ¿No hay ningún lugar seguro?', '¡La Horda está aquí, corred! ¿No hay ningún lugar seguro?', 28153),
(156604, 'esES', '¡Genial, más problemas con la Horda ahora que la Alianza está aquí!', '¡Genial, más problemas con la Horda ahora que la Alianza está aquí!', 28153),
(156603, 'esES', '¡No voy a arriesgar mi vida si la Horda ya está aquí!', '¡No voy a arriesgar mi vida si la Horda ya está aquí!', 28153),
(156602, 'esES', '¡Corred! ¡Esto es lo que pasa por ayudar a la Alianza!', '¡Corred! ¡Esto es lo que pasa por ayudar a la Alianza!', 28153),
(156601, 'esES', '¡Creí que estábamos a salvo de la Horda!', '¡Creí que estábamos a salvo de la Horda!', 28153),
(156600, 'esES', '¡¿Qué hace aquí la Horda?!', '¡¿Qué hace aquí la Horda?!', 28153),
(156599, 'esES', '¡La Horda! ¡Corred!', '¡La Horda! ¡Corred!', 28153),
(156598, 'esES', 'Esto es un texto de prueba, digo cosas en él.', '', 28153),
(156597, 'esES', '', 'Hasta pronto, Nathanos.', 28153),
(156596, 'esES', '', '<Sylvanas comienza a alejarse. Luego duda y mira por encima del hombro>.', 28153),
(156595, 'esES', 'No te fallaremos. Buen viaje, mi señora.', '', 28153),
(156594, 'esES', '', 'Ocupaos e id informándome de vuestro progreso.', 28153),
(156593, 'esES', 'Como ordenes, Jefa de Guerra.', '', 28153),
(156592, 'esES', '', 'Bien. Trabaja con el adalid para decidir dónde establecernos primero.', 28153),
(156591, 'esES', 'Sí, mi señora. El Llanto del Alma en Pena está listo para partir de inmediato.', '', 28153),
(156590, 'esES', '', '¿Está todo en orden?', 28153),
(156589, 'esES', '<Nathanos hace una reverencia>.', '', 28153),
(156588, 'esES', 'Mi Reina.', '', 28153),
(156587, 'esES', 'Adalid, se requiere tu presencia en el Llanto del Alma en Pena. La Dama Oscura tiene órdenes para comenzar la campaña en la costa de Kul Tiras.', '', 28153),
(156586, 'esES', '', 'Sígueme.', 28153),
(156585, 'esES', '', 'Adalid.', 28153),
(156584, 'esES', 'El grupo lo supervisa Garona Semiorco. Ella dirigirá las misiones con tu ayuda.', '', 28153),
(156583, 'esES', 'Hemos reunido a un grupo de élite para que ejecute las órdenes de la Dama Oscura.', '', 28153),
(156582, 'esES', 'Buen trabajo ahí fuera.', '', 28153),
(156581, 'esES', 'Han alertado a la Horda de nuestra presencia y están enviando tropas. ¡Debes intervenir para que nuestros peritos puedan completar su misión!', '', 28153),
(156580, 'esES', '', 'Bueno, tal vez pueda hacer algo, Zelling. Pero solo si demuestras tu valía a la Horda.', 28153),
(156579, 'esES', 'Soy Thomas Zelling, un Sabiomar, ¡un Sabiomar ILUMINADO! Haré todo lo que me pidas, incluso te ayudaré a atacar a la Alianza, pero... ¡por favor, conviérteme en Renegado!', '', 28153),
(156578, 'esES', 'Parece que el vagón ha llegado sano y salvo. Id a recoger vuestra recompensa al castillo.', '', 28153),
(156577, 'esES', '', '¿Quién eres? ¿Qué te hace pensar que mereces ese regalo?', 28153),
(156576, 'esES', '¡Por fin, $gun Renegado:una Renegada;! ¡Por favor, mátame, conviérteme en Renegado... concédeme el don de la inmortalidad!', '', 28153),
(156575, 'esES', '', 'Bueno, podría lanzarle un par de amenazas, a ver si está dispuesta a darnos algunos detalles...', 28153),
(156574, 'esES', 'El Vacío, los elementos <tos>... ¿Nada puede detener esta maldita enfermedad? ¿Por qué ha tenido que acabar así?', '', 28153),
(156573, 'esES', 'El Sabiomar estuvo aquí hace un tiempo. Lo vi proteger y servir a su familia.', '', 28153),
(156572, 'esES', '¿Alguna idea de dónde podemos encontrar a un Sabiomar?', '¿Alguna idea de dónde podemos encontrar a un Sabiomar?', 28153),
(156571, 'esES', 'Hemos visto a unos efectivos de la Horda transportando suministros por el campo de batalla. Balinda busca voluntarios para... reponer nuestras reservas.', '', 28153),
(156570, 'esES', 'Nos han informado de la presencia de exploradores de la Horda cerca de la mina. Ve a ver a Genny al taller, te dará los detalles.', '', 28153),
(156569, 'esES', 'Genny necesita ayuda en el taller. Se nos están acabando los suministros.', '', 28153),
(156568, 'esES', 'Tanto dinero que ganar. Nuevas tierras que explotar...$b$b¡Qué suerte tengo de vivir esto!', '', 28153),
(156567, 'esES', 'No, no me importan.', '', 28153),
(156566, 'esES', 'Misha, quédate aquí. Los demás seguiremos al Sabiomar y después Lilian hará... lo que sea que estés planeando.', '', 28153),
(156565, 'esES', '', '¿No te importan los detalles, Rexxar?', 28153),
(156564, 'esES', 'Estoy listo para ir a Entrañas.', 'Estoy lista para ir a Entrañas.', 28153),
(156563, 'esES', '', 'Camposanto ha dejado de existir. Cuando estés $glisto:lista;, te llevaré al Barrio de los Magos para que te reúnas con el Alto Señor Supremo.', 28153),
(156562, 'esES', '', 'Campeones, ha llegado la hora. Atravesaremos a la Alianza con nuestras hojas mientras intentan tomar nuestra preciada fortaleza de Lordaeron.', 28153),
(156560, 'esES', 'Campeones de la Alianza, ¡ha llegado la hora de reclamar lo que nos pertenece por derecho! El ataque final para reconquistar la fortaleza de Lordaeron comenzará al alba. ¡La Horda y su Jefa de Guerra responderán por sus crímenes!', '', 28153),
(156559, 'esES', '', 'Tu camarada Nocheterna ehtá en la Cámara de Sendah Ancehtraleh. Ven a verme cuando acabeh de ehplorar.', 28153),
(156558, 'esES', '', 'Mi padre guarda muchoh tesoroh aquí, en la cámara real.', 28153),
(156557, 'esES', '', 'Se dice que el Gran Sello eh una de lah pocah cosah máh antiguah que el Imperio Zandalari.', 28153),
(156556, 'esES', '', 'Ven, adalid. Te enseñaré el lugar.', 28153),
(156555, 'esES', 'Mejor ocúpate tú de ehto.', '', 28153),
(156554, 'esES', 'He perdido la cuenta del tiempo que llevo en esta celda, pero ya no importa.', '', 28153),
(156553, 'esES', 'Mi nombre es Sam, Sam Williams. Me alegra ver que alguien con un arma está por fin de nuestro lado.', '', 28153),
(156552, 'esES', 'Esos piratas son unos tipos miserables y detestables. Mátalos con impunidad.', 'Esos piratas son unos tipos miserables y detestables. Mátalos con impunidad.', 28153),
(156551, 'esES', '¿En qué nos hemos metido?', '¿En qué nos hemos metido?', 28153),
(156550, 'esES', '¡Aún no habéis acabado conmigo, monstruos!', '¡Aún no habéis acabado conmigo, monstruos!', 28153),
(156549, 'esES', '¡Maté a una docena de esos monstruos asquerosos antes de que me superaran!', '¡Maté a una docena de esos monstruos asquerosos antes de que me superaran!', 28153),
(156548, 'esES', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(156547, 'esES', '¡No dejaremos a nadie atrás!', '¡No dejaremos a nadie atrás!', 28153),
(156546, 'esES', '¡Sabía que Aterravermis no nos abandonaría aquí!', '¡Sabía que Aterravermis no nos abandonaría aquí!', 28153),
(156545, 'esES', 'Te debo un trago cuando volvamos al barco.', 'Te debo un trago cuando volvamos al barco.', 28153),
(156544, 'esES', 'Nunca imaginé que pudiesen comer tanto...', '', 28153),
(156543, 'esES', 'Los ranishus tienen un apetito insaciable, pero una mente sencilla. Se comen todo lo que ven... incluidos a los suyos. ¡Habrá que aprovecharse!', '', 28153),
(156542, 'esES', '', '<Garona gira sus hojas y parece que desaparecen>.', 28153),
(156541, 'esES', 'Estas águilas de guerra nos llevarán a nuestro destino. ¿Todo listo? ¡Vamos allá!', '', 28153),
(156540, 'esES', 'Vamos allá.', '', 28153),
(156539, 'esES', 'Mi Reina se ha encargado de todo. Un medio de transporte nos espera en las murallas.', '', 28153),
(156538, 'esES', 'Solo quería una parte de su tesoro.', 'Solo quería una parte de su tesoro.', 28153),
(156537, 'esES', '¡Volveré, piratah! ¡Aún no oh habéih librado de mí!', '¡Volveré, piratah! ¡Aún no oh habéih librado de mí!', 28153),
(156536, 'esES', '¡Mata a toda esa tripulación de cobardeh!', '¡Mata a toda esa tripulación de cobardeh!', 28153),
(156535, 'esES', 'Echo de menoh Zuldazar... ¿Cuánto tiempo he de sufrir aquí?', 'Echo de menoh Zuldazar... ¿Cuánto tiempo he de sufrir aquí?', 28153),
(156534, 'esES', 'No veo ningún tesoro por aquí. ¡Menuda sarta de mentirah!', 'No veo ningún tesoro por aquí. ¡Menuda sarta de mentirah!', 28153),
(156533, 'esES', '¡No me dejan unirme a su tripulación! No eh juhto.', '¡No me dejan unirme a su tripulación! No eh juhto.', 28153),
(156532, 'esES', 'Un favor poco frecuente en el desierto.', 'Un favor poco frecuente en el desierto.', 28153),
(156531, 'esES', 'No ehperaba que nadie viniera a por mí. Gracias, $gforastero:forastera;.', 'No ehperaba que nadie viniera a por mí. Gracias, $gforastero:forastera;.', 28153),
(156530, 'esES', 'Algo se ha abierto.', '', 28153),
(156529, 'esES', 'Aún quedan más...', '', 28153),
(156528, 'esES', 'Creo que ya están todos. Buen trabajo, sabía que podía contar contigo.', '', 28153),
(156527, 'esES', 'Aún quedan muchos vulperas atrapados en las madrigueras. ¿Puedes ayudarlos a escapar?', '', 28153),
(156526, 'esES', 'El barredor cuidadosamente calibrado emite un leve zumbido que indica que no ha localizado ningún fósil cerca.', 'El barredor cuidadosamente calibrado emite un leve zumbido que indica que no ha localizado ningún fósil cerca.', 28153),
(156525, 'esES', 'El elemental de excavación refunfuña porque no consigue localizar ningún fósil cerca.', 'El elemental de excavación refunfuña porque no consigue localizar ningún fósil cerca.', 28153),
(156524, 'esES', '', '¡Por Gilneas!', 28153),
(156523, 'esES', '', '¡Guardias, entrad ahí! ¡Traedme sus cabezas!', 28153),
(156522, 'esES', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t ¡El guardián de los titanes Hezrel empieza a lanzar |cFFF00000|Hspell:269310|h[Luz purgadora]|h|r!', '', 28153),
(156521, 'esES', '', 'Así que la Horda ha decidido atacarnos aquí. Me han ahorrado el esfuerzo de rastrearos yo misma. ¡Gilneanos, atacad!', 28153),
(156520, 'esES', 'Hay que hacer muchos más cálculos de lo que imaginaba. Vuelve más tarde a por tu parte del tesoro.', '', 28153),
(156519, 'esES', '', 'Al igual que el banco de Forjaz, este es un trabajo para cinco personas.', 28153),
(156518, 'esES', 'Vamos a convertirnos en héroes... ¡en héroes ricos!', '', 28153),
(156517, 'esES', 'Hazme rico, $p. ¡Quiero ponerme dientes de oro!', '', 28153),
(156516, 'esES', '', '¿Qué tal ese diente, Eddard?', 28153),
(156514, 'esES', '', 'Tuve un sueño así, pero estaba en el banco de Forjaz.', 28153),
(156513, 'esES', '', 'Cuando consigamos el oro, me compraré un buen perfume y me daré un baño en él.', 28153),
(156512, 'esES', 'Quizás volvamos a encontrarnos. ¡Adiós!', '', 28153),
(156511, 'esES', 'Somos libres...', '', 28153),
(156510, 'esES', 'Debemos... escapar...', '', 28153),
(156509, 'esES', '', 'Te agradezco tu ayuda, $n. Debo irme.', 28153),
(156508, 'esES', '', 'No pretendo entender tus motivos, $n, pero me agrada que hayas abatido a otro caballero de la Muerte.', 28153),
(156507, 'esES', '', '¡Vigila los cielos, $n, siento que alguien se acerca!', 28153),
(156506, 'esES', '¿Qué pasa, $p?', '¡Si hay oro de por medio, me apunto!', 28153),
(156505, 'esES', 'Necesito tu ayuda.', 'Necesito tu ayuda.', 28153),
(156504, 'esES', 'Sobrevivir al Rey Exánime para morir a manos de alguien como tú... Agh...', '', 28153),
(156503, 'esES', 'Qué desperdicio...', '', 28153),
(156502, 'esES', 'Necesito tu ayuda.', 'Necesito tu ayuda.', 28153),
(156501, 'esES', 'Tú ganas... dragón...', '', 28153),
(156500, 'esES', 'La muerte... definitiva...', '', 28153),
(156499, 'esES', 'No es... justo...', '', 28153),
(156498, 'esES', 'Entonces tomaré lo que me corresponde... ¡por la fuerza!', '', 28153),
(156497, 'esES', '¡Ya veo, $n! ¡Quieres ser el único caballero de la Muerte con una montura tan espléndida!', '', 28153),
(156496, 'esES', 'Pero le había echado el ojo a esa antigua bestia de hueso que hay detrás de ti. Así que, si no te importa, voy a reclamar lo que es mío.', '', 28153),
(156495, 'esES', 'Ese draco de ahí es algo pequeño... y sigue vivo. No será un gran obstáculo.', '', 28153),
(156494, 'esES', 'Estoy siguiendo tus pasos. ¿Has venido a ayudarme? ¡Veo que has traído un regalo!', '', 28153),
(156493, 'esES', '¡$gSeñor:Señora; de la Muerte $n! ¡Qué sorpresa!', '', 28153),
(156492, 'esES', 'Uf. Si prefieres hacerlo por las malas, ¡que así sea!', '', 28153),
(156491, 'esES', '', '¡$n, protégeme! ¡Hay que completar el ritual!', 28153),
(156490, 'esES', 'Así que mantente al margen, pequeño draco, tengo asuntos pendientes con ese montón de huesos.', '', 28153),
(156489, 'esES', 'Creo que debería ceñirme al plan original y proceder con el ancestro.', '', 28153),
(156488, 'esES', '¡Salgamos de aquí!', '¡Salgamos de aquí!', 28153),
(156487, 'esES', 'Un caballero tan espléndido como yo debería tener la mejor montura.', '', 28153),
(156486, 'esES', '¡Dos dragones! ¡Menuda sorpresa! Aunque el que sigue con vida es... insignificante.', '', 28153),
(156485, 'esES', '', 'Los de tu calaña no sois bienvenidos, $gSeñor:Señora; de la Muerte.', 28153),
(156484, 'esES', 'Bueno, bueno, bueno. Pero ¿qué tenemos aquí?', '', 28153),
(156483, 'esES', 'Loh seguidoreh de Zul no permitirán que Rezan ehcape de su dehtino tan fácilmente. Tendremoh que luchar pa salir de aquí.\n\n¿Ehtáh $gpreparado:preparada;?', '', 28153),
(156482, 'esES', '¿A qué viene tanta prisa? Frena un poco. Recobra el aliento... ¡Échate una siesta! Estás a salvo con nosotros.', '', 28153),
(156481, 'esES', 'Mi padre nos enseñó a usar la forja... Este fue el primer martillo que hicimos juntos.', '', 28153),
(156480, 'esES', '¡Mi martillo! ¡Lo has recuperado!', '', 28153),
(156479, 'esES', '', 'Ehtoh exiliadoh son lo máh parecido a una familia que tengo.', 28153),
(156478, 'esES', '', '$gBienvenido:Bienvenida; a la banda, $p.', 28153),
(156477, 'esES', '$gBienvenido:Bienvenida; a la banda, $p.', '', 28153),
(156476, 'esES', '', '$gBienvenido:Bienvenida; a la banda, $p.', 28153),
(156475, 'esES', '$gBienvenido:Bienvenida; a la banda, $p.', '', 28153),
(156474, 'esES', '¿Necesitas una bebida fuerte o algo de comer?', '¿Necesitas una bebida fuerte o algo de comer?', 28153),
(156473, 'esES', 'Vaya, ¿ereh tú, $p? Loh Furiarena no te han seguido, ¿verdad?', '', 28153),
(156472, 'esES', '¡Un par de embohcadah de caravanah máh y dehpuéh asaltaremoh la arena pa conseguir un botín de verdad!', '', 28153),
(156471, 'esES', '¡Tengo sed! ¡Ve a robarme un poco de ese alcohol Zandalari tan bueno!', '', 28153),
(156470, 'esES', 'Noh ehtamoh quedando sin leña. ¡Buhcadme otra caravana vulpera que asaltar!', '', 28153),
(156469, 'esES', '¡Loh desiertoh pertenecen a loh Furiarena! ¡Si hay alguien máh aquí, ehtá invadiendo nuehtro territorio!', '', 28153),
(156468, 'esES', 'Traedme máh ehclavoh. Tengo muchah máh lanzah que arrojar.', '', 28153),
(156467, 'esES', '¡Dehtrozadloh! ¡Pisoteadloh como a perroh!', '', 28153),
(156466, 'esES', '¡Ahora no soih tan grandeh y poderosoh, Zandalari arroganteh!', '', 28153),
(156465, 'esES', '¡Ja! ¡Le he dado a uno! Juhto en el pecho, vulpera repugnante...', '', 28153),
(156464, 'esES', '¿Quieres que te devuelva el martillo, patata peluda cometierra? PUES VEN A POR ÉL.', '', 28153),
(156463, 'esES', '¡Expulsaremos a esa escoria de Kul Tiras de nuestras tierras! $n, convoca a la Horda y pongamos fin a esto.', '', 28153),
(156462, 'esES', 'Deberíah vigilar esa lengua. Yazma eh la suma sacerdotisa de mi loa y cuenta con el favor del rey Rastakhan.$b$bY si loh rumoreh son ciertoh, tiene aún máh influencia sobre el gran profeta Zul.', 'Deberíah vigilar esa lengua. Yazma eh la suma sacerdotisa de mi loa y cuenta con el favor del rey Rastakhan.$b$bY si loh rumoreh son ciertoh, tiene aún máh influencia sobre el gran profeta Zul.', 28153),
(156461, 'esES', 'Shadra eh la loa favorita del Consejo Zanchuli, así que suh seguidoreh dihfrutamoh de muchoh privilegioh. Uno de elloh eh no tener que rehponder a loh de tu calaña.', 'Shadra eh la loa favorita del Consejo Zanchuli, así que suh seguidoreh dihfrutamoh de muchoh privilegioh. Uno de elloh eh no tener que rehponder a loh de tu calaña.', 28153),
(156460, 'esES', '$gMaldito:Maldita; seas...', '$gMaldito:Maldita; seas...', 28153),
(156459, 'esES', 'Perderéis...', 'Perderéis...', 28153),
(156458, 'esES', 'Mi rey... lo siento...', 'Mi rey... lo siento...', 28153),
(156457, 'esES', 'Lo pagarás... caro...', 'Lo pagarás... caro...', 28153),
(156456, 'esES', 'Por... la Alianza...', 'Por... la Alianza...', 28153),
(156455, 'esES', 'Loh seguidoreh de Shadra hemoh seguido a tu gente con gran interéh.$b$bHemoh vihto a vuehtra Horda enredarse cada vez máh en una gran telaraña de mentiras. Pronto, la trampa se cerrará y no oh daréih cuenta hahta que sea demasiado tarde.', 'Loh seguidoreh de Shadra hemoh seguido a tu gente con gran interéh.$b$bHemoh vihto a vuehtra Horda enredarse cada vez máh en una gran telaraña de mentiras. Pronto, la trampa se cerrará y no oh daréih cuenta hahta que sea demasiado tarde.', 28153),
(156454, 'esES', '¡Muere!', '¡Muere!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'esES', '¡Te mandaré de vuelta a Orgrimmar en pedacitos!', '¡Te mandaré de vuelta a Orgrimmar en pedacitos!', 28153),
(156452, 'esES', '¡Pagarás por tus crímenes contra la Alianza!', '¡Pagarás por tus crímenes contra la Alianza!', 28153),
(156451, 'esES', 'Sirvo a Shadra, maehtra de ehpíah y loa de loh venenoh. ¿A quién sirveh tú?', 'Sirvo a Shadra, maehtra de ehpíah y loa de loh venenoh. ¿A quién sirveh tú?', 28153),
(156450, 'esES', '¡Muere, escoria de la Horda!', '¡Muere, escoria de la Horda!', 28153),
(156449, 'esES', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(156448, 'esES', 'Su señoría ha detectado tu presencia en suh dominioh. Ve con cuidado.', 'Su señoría ha detectado tu presencia en suh dominioh. Ve con cuidado.', 28153),
(156447, 'esES', 'Camina con la Madre Tierra, $n.', 'Camina con la Madre Tierra, $n.', 28153),
(156446, 'esES', 'Nuestra cacería en este lugar no ha hecho más que empezar.', '', 28153),
(156445, 'esES', '¿Rhan\'ka sigue escondiéndose en el oasis? Tengo que ir a visitarlo un día de estos...', '', 28153),
(156444, 'esES', '¡Sabía que volverías a por más! Tengo una nueva tanda aquí, solo para ti.', '', 28153),
(156443, 'esES', '[ESCENA QUE MUESTRA AL GENERAL JAKRA\'ZET Y AL EMPERADOR KORTHEK CONFABULANDO].', '', 28153),
(156442, 'esES', 'Las profundidades... te... vigilan...', 'Las profundidades... te... vigilan...', 28153),
(156441, 'esES', '¡Tiraré tu cadáver destrozado al mar!', '¡Tiraré tu cadáver destrozado al mar!', 28153),
(156440, 'esES', '', 'Debería haber nacido goblin, ellos sí que saben apreciar mis habilidades únicas.', 28153),
(156439, 'esES', 'Debería hacer un trato con la Marea de Hierro, son más idiotas todavía.', '', 28153),
(156438, 'esES', 'Haz lo que tengas que hacer mientras buscamos a Zul, $gpequeño héroe:pequeña heroína;. Pero prepárate, pronto necesitaremos tu ferocidad.', '', 28153),
(156437, 'esES', '', 'Perseguiremos a esos herejes hasta los confines de Azeroth. Reuniré a mi bandada y nos encargaremos de que lluevan piedras y muerte sobre las cabezas de esas criaturas viles que se han atrevido a darnos la espalda.\n\nDe momento, mi bandada surcará los cielos y averiguará lo que traman Zul y sus traidores.', 28153),
(156436, 'esES', 'Me hah dado el golpe de gracia... ehta vez...', '', 28153),
(156435, 'esES', '<Hacer cola para una expedición insular JcJ con tu grupo>.', '<Hacer cola para una expedición insular JcJ con tu grupo>.', 28153),
(156434, 'esES', '<Hacer cola para una expedición insular JcJ>.', '<Hacer cola para una expedición insular JcJ>.', 28153),
(156433, 'esES', '¡Utiliza el fetiche de Jin\'Tiki para acabar con Zulajin!', '¡Utiliza el fetiche de Jin\'Tiki para acabar con Zulajin!', 28153),
(156432, 'esES', 'Solo espero haber escondido mi llave lo bastante bien como para que solo tú la encuentres.', '', 28153),
(156431, 'esES', 'Kega, tu valor es incuestionable, pero no estás en condiciones de combatir. $n, acompañaré a Kega. Reúnete con nosotros en la torre de guerra cuando hayas terminado.', '', 28153),
(156430, 'esES', 'Gracias, voy a asegurar la torre de guerra. La necesitaremos para convocar al resto de las tropas.', 'Gracias, voy a asegurar la torre de guerra. La necesitaremos para convocar al resto de las tropas.', 28153),
(156429, 'esES', '', 'Mis hermanas... te matarán...', 28153),
(156428, 'esES', 'La Horda caerá...', 'La Horda caerá...', 28153),
(156427, 'esES', 'Sigues a una demente...', 'Sigues a una demente...', 28153),
(156426, 'esES', 'Monstruos...', 'Monstruos...', 28153),
(156425, 'esES', 'Te... mataré...', 'Te... mataré...', 28153),
(156424, 'esES', 'La Horda pagará...', 'La Horda pagará...', 28153),
(156423, 'esES', 'Por Teldrassil...', 'Por Teldrassil...', 28153),
(156422, 'esES', 'Hermanas... lo intenté...', 'Hermanas... lo intenté...', 28153),
(156421, 'esES', '', '¡Mi familia murió en Teldrassil! ¡Te mataré!', 28153),
(156420, 'esES', '', '¡Vengaremos Teldrassil!', 28153),
(156419, 'esES', 'Haremos que la gente de Kul Tiras se lo piense dos veces antes de apostar contra la Horda.', '', 28153),
(156418, 'esES', '¡Por Teldrassil y la Alianza!', '¡Por Teldrassil y la Alianza!', 28153),
(156417, 'esES', '¡Morirás entre gritos de dolor, escoria de la Horda!', '¡Morirás entre gritos de dolor, escoria de la Horda!', 28153),
(156416, 'esES', '', '¡Asesinos! ¿Cómo os atrevéis a dar la cara?', 28153),
(156415, 'esES', '¡Por aquí!', '', 28153),
(156414, 'esES', '¡Ahora a caminar!', '', 28153),
(156413, 'esES', '¡Ahora vamos donde yo quiera!', '', 28153),
(156412, 'esES', '¡He ascendido a piernas!', '', 28153),
(156411, 'esES', '¡Ahora yo conduzco!', '', 28153),
(156410, 'esES', '¡Que el fuego sagrado te purifique!', '', 28153),
(156409, 'esES', 'No... Debo encontrar... el anillo...', '', 28153),
(156408, 'esES', '¡Monstruos! ¡Le enviaré vuestras cabezas a la Jefa de Guerra!', '¡Monstruos! ¡Le enviaré vuestras cabezas a la Jefa de Guerra!', 28153),
(156407, 'esES', '¡Tu cabeza será un obsequio para mi reina!', '', 28153),
(156406, 'esES', '', '¡La Horda pagará por lo que le hizo a Teldrassil!', 28153),
(156405, 'esES', '', '¡Te enseñaré cómo quemar un cuerpo!', 28153),
(156404, 'esES', '', '¡Parece que hemos terminado por aquí! Ten cuidado ahí fuera, $p.', 28153),
(156403, 'esES', 'Vengaré a mis hombres, lo juro.', 'Vengaré a mis hombres, lo juro.', 28153),
(156402, 'esES', 'Estúpidos mortales. No podéis detener mi regreso.', '', 28153),
(156401, 'esES', '', '¡Tú! Horda. Ven y ayúdame.', 28153),
(156400, 'esES', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Está disponible una nueva |cFFFF0404|Hspell:263420|h[matriz de poder]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Está disponible una nueva |cFFFF0404|Hspell:263420|h[matriz de poder]|h|r.', 28153),
(156399, 'esES', 'Ese trol está más loco que un saco de ranishus.', '', 28153),
(156398, 'esES', 'Rikati pone los ojos en blanco.', '', 28153),
(156397, 'esES', 'De acuerdo, colega. ¡Lo haré! ¡Gracias!', '', 28153),
(156396, 'esES', '¡No hay tiempo pa hablar, Rikati! ¡Loh Furiarena se han sublevado! ¡Ehcóndete, encanto!', '', 28153),
(156395, 'esES', '¡El Anillo de las Mareas será nuestro! ¡La reina Azshara así lo exige!', '¡El Anillo de las Mareas será nuestro! ¡La reina Azshara así lo exige!', 28153),
(156394, 'esES', '¡No nos detendremos hasta que el anillo sea nuestro!', '¡No nos detendremos hasta que el anillo sea nuestro!', 28153),
(156393, 'esES', '¿Qué diceh? ¿Creeh que voy a contar por ti? De eso nada. Deberíah contarlah tú.\n\n¿Sabeh qué? Volvamoh a empezar.', '', 28153),
(156392, 'esES', '¿Dónde está el Anillo de las Mareas? ¡No lo escondas!', '¿Dónde está el Anillo de las Mareas? ¡No lo escondas!', 28153),
(156391, 'esES', 'El Anillo de las Mareas se perdió en las proximidades. ¡La reina debe recuperarlo!', 'El Anillo de las Mareas se perdió en las proximidades. ¡La reina debe recuperarlo!', 28153),
(156390, 'esES', 'El Despertar de la Tormenta crece. ¿Estás con nosotros?', 'El Despertar de la Tormenta crece. ¿Estás con nosotros?', 28153),
(156389, 'esES', '¿He llegado ya a un millón de almas?', '¿He llegado ya a un millón de almas?', 28153),
(156388, 'esES', '¡Nadie se interpondrá en el camino de nuestra reina!', '¡Nadie se interpondrá en el camino de nuestra reina!', 28153),
(156387, 'esES', '¡El Anillo de las Mareas es nuestro por derecho!', '¡El Anillo de las Mareas es nuestro por derecho!', 28153),
(156386, 'esES', 'Todavía podemos detener a lord Canto Tormenta.', 'Todavía podemos detener a lord Canto Tormenta.', 28153),
(156385, 'esES', '¡El anillo será nuestro!', '¡El anillo será nuestro!', 28153),
(156384, 'esES', '¡La reina Azshara exige el Anillo de las Mareas!', '¡La reina Azshara exige el Anillo de las Mareas!', 28153),
(156383, 'esES', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t ¡La serpiente dorada absorbe un oro animado y obtiene |cFFFF0000|Hspell:265991|h[Lustre]|h|r!', '¡La serpiente dorada absorbe un oro animado y obtiene |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t texto opcional aquí |cFFFF0000|Hspell:265991|h[Lustre]|h|r!', 28153),
(156382, 'esES', '', '¡Oh, no! ¡Eso no es bueno! ¡NADA BUENO!', 28153),
(156381, 'esES', 'Utiliza una de esas cuerdas para descender a una lancha de desembarco... a no ser que prefieras nadar.', '', 28153),
(156380, 'esES', '¡No pienso seguir lavándoles la ropa interior a esos sucios humanos!', '', 28153),
(156379, 'esES', '', '¡Estoy calada hasta los huesos! Gracias.', 28153),
(156378, 'esES', '', '¡Ya he tenido suficiente!', 28153),
(156377, 'esES', 'Me has salvado de un destino terrible.', '', 28153),
(156375, 'esES', 'Mientras estabas de aventuras, yo estudiaba la hoja.', 'Mientras estabas de aventuras, yo estudiaba la hoja.', 28153),
(156374, 'esES', '<El maestro de espías Shaw asiente con la cabeza a modo de saludo>.', '', 28153),
(156373, 'esES', 'Estamos aquí, maestro de espías.', '', 28153),
(156372, 'esES', 'Voy a trabajar con el maestro de espías Shaw. No es un tipo muy amable, pero acaba lo que empieza.', '', 28153),
(156371, 'esES', 'El Rey ha convocado a algunos héroes impresionantes para esta campaña.', '', 28153),
(156370, 'esES', 'Alapresta, ve a buscarte un buen almuerzo.', '', 28153),
(156369, 'esES', 'Sígueme, $gmuchacho:muchacha;.', '', 28153),
(156368, 'esES', '¡Le he dado en la rodilla!', 'Ay... ¡Eso ha tenido que doler!', 28153),
(156367, 'esES', 'No nos rendimos con tanta facilidad.', 'Deberían haber huido cuando tenían la oportunidad.', 28153),
(156366, 'esES', '¡Ha caído otro!', '¡No son tan duros como pensaban!', 28153),
(156365, 'esES', 'Hola, capitana Stone. Estoy deseando conocerte.', '', 28153),
(156364, 'esES', 'En ese caso, cárgalo en el carro. Estás demostrando ser más útil de lo que esperaba, señorita Voss.', '', 28153),
(156363, 'esES', '', 'Bastante.', 28153),
(156362, 'esES', '¿Prácticamente intacto?', '', 28153),
(156361, 'esES', '', 'Aquí, Clamañublo. He recuperado el cuerpo.', 28153),
(156360, 'esES', 'Buen trabajo, $p. ¿Dónde está Lilian?', '', 28153),
(156359, 'esES', 'Tieneh que darte prisa... ¡Van trah Rezan!', '', 28153),
(156358, 'esES', 'Me... me obligaron a contarleh cómo lo hicieron loh Drakkari.', '', 28153),
(156357, 'esES', 'Excelente. Taelia te pondrá al día.', '', 28153),
(156356, 'esES', '', 'Señor, el informe de la situación está listo.', 28153),
(156355, 'esES', '', '¡Has reducido su ejército a cenizas! Bien hecho.', 28153),
(156354, 'esES', '', 'Las brujas se están reagrupando. ¡Hazte con un demoledor y acaba con su ejército!', 28153),
(156353, 'esES', '', 'Tenemos que enseñarles a esos tipos de Kul Tiras lo que significa enemistarse con la Horda.', 28153),
(156352, 'esES', 'Recuerda, Puertopuente es un asentamiento muy grande y bien protegido. Limítate a las afueras de la ciudad... por ahora.', '', 28153),
(156351, 'esES', 'Hemos cumplido con nuestra parte, $p. Estoy orgulloso de lo que hemos conseguido aquí.\n\nPero ahora tengo que cuidar de mi gente y asegurarme de que estén a salvo.\n\nEstoy seguro de que volveremos a encontrarnos. Me enorgullece poder llamarte $gamigo:amiga; y $galiado:aliada;.', '', 28153),
(156350, 'esES', 'Los infieles tratan a sus bestias con crueldad. No es difícil volverlas en contra de sus amos.', '', 28153),
(156349, 'esES', 'No tengo por qué aguantar ehto. ¡Zul el Profeta me asignó mi puehto!', '', 28153),
(156348, 'esES', '', '¡Ha sido una batalla digna de una canción!\n\nEs un honor luchar con Vorrik y contigo. Espero que podamos repetirlo pronto.\n\nDespués de todo, siempre hay más infieles que matar.', 28153),
(156347, 'esES', 'Acabemos con esto juntos.', '', 28153),
(156346, 'esES', '', 'Démosles una lección a esos sethrak.', 28153),
(156345, 'esES', '', 'Estos suministros deberían ayudarnos a seguir luchando contra el aquelarre. Gracias.', 28153),
(156344, 'esES', 'Sígueme, el bastión no está lejos de aquí.', '', 28153),
(156343, 'esES', 'Bien. Entonces serán nuestro objetivo.', '', 28153),
(156342, 'esES', '', 'La ciudad que hemos pasado, Puertopuente, parece la mayor amenaza de la zona.', 28153),
(156341, 'esES', '¡Rexxar! <tose> Muchos resisten aún. N... no les queda mucho tiempo.', '¡Rexxar! <tose> Muchos resisten aún. N... no les queda mucho tiempo.', 28153),
(156340, 'esES', 'Esa bestia ya no se comerá a más soldados de la Horda. Toda una hazaña, adalid.', '', 28153),
(156339, 'esES', '', 'Nos estamos quedando sin plata, un recurso esencial en nuestra lucha contra las brujas. Entra en las minas y reúne toda la que puedas.', 28153),
(156338, 'esES', 'Rakjan parece dispuesto a ayudarnos, y no es difícil imaginar por qué.\n\nLos infieles han sido crueles con él y su prole. Mira las cicatrices de su cuerpo y los nidos vacíos en la cumbre.\n\nMerece venganza tanto como cualquiera de nosotros. Nos la cobraremos juntos.', '', 28153),
(156337, 'esES', 'Pronto, Samuel. Resiste.', '', 28153),
(156336, 'esES', 'Estoy helado... ¿Cuándo pararán las voces?', '', 28153),
(156335, 'esES', '$n, remueve un poco mi estofado para que no se queme.', '', 28153),
(156334, 'esES', 'Gran trabajo. Asegurémonos de que esta fiesta es la última que da el consejo.', '', 28153),
(156333, 'esES', 'Buen trabajo. Ahora ya ehtamoh lihtoh pa la fiehta.', '', 28153),
(156332, 'esES', 'Calma, las hierbas aliviarán tus heridas. ¿Puedes contarnos algo del interior del bastión? ¿Hay más supervivientes?', '', 28153),
(156331, 'esES', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t ¡El daño de Goliat de almas aumenta con cada acumulación de |cFFFF0404|Hspell:260512|h[Cosecha de almas]|h|r!', '', 28153),
(156330, 'esES', '¡Mira! ¡Este todavía respira!', '', 28153),
(156329, 'esES', 'Muchos guerreros valientes cayeron en la batalla. Fue una suerte que llegaras.', '', 28153),
(156328, 'esES', 'Los soldados de Kul Tiras nos atacaron cuando intentábamos salvar a las tripulaciones. Nuestras tropas estaban demasiado dispersas para mantener ambas zonas y tuvimos que retirarnos a la orilla.', '', 28153),
(156327, 'esES', 'Nos atacaron esta mañana. Los magos de Kul Tiras utilizaron un objeto extraño para invocar esos horrores que viste enroscados alrededor de nuestros barcos.', '', 28153),
(156326, 'esES', 'Confirmado. Misión cumplida. ¡Pura perfección! Me encanta que los planes salgan bien. Cambio y corto.', '', 28153),
(156325, 'esES', 'Orden siguiente. ¿Ves ese gran botón rojo? Despeja la zona y pulsa el gran botón rojo. Ejecuta en cuanto puedas. Cambio.', '', 28153),
(156324, 'esES', 'El código de autentificación es uno-nueve-nueve. Alineación de instrumentos fuera de los parámetros aceptables... Nada, ignóralo... Puedo hacerlo funcionar. Espera. Cambio.', '', 28153),
(156323, 'esES', 'Recibido. Calibración completa. Debes orientar los instrumentos en lugares específicos. Infórmame cuando estén situados. Cambio.', '', 28153),
(156322, 'esES', 'Prueba de radio. Aquí Alfa 1. Comunicando con escuadrón Alfa. ¿Me recibes? Cambio.', '', 28153),
(156321, 'esES', '¡Una batalla gloriosa! ¡Y hemos sobrevivido!', '', 28153),
(156320, 'esES', '', 'La llama nunca muere...', 28153),
(156319, 'esES', '', 'Polvo al polvo...', 28153),
(156318, 'esES', 'Tus grandes hazañas nos han dado una lección de humildad. Muchas gracias, $p.', '', 28153),
(156317, 'esES', '', 'Tus huesos me vendrán muy bien para hacer fuego.', 28153),
(156316, 'esES', '', 'Me aseguraré de que no quede nadie para llorar a tus cenizas.', 28153),
(156315, 'esES', '¡Nuestra larga historia ha visto pocos días tan gloriosos como este!', '', 28153),
(156314, 'esES', '¡Voy a crear una sopa nueva en tu honor!', '', 28153),
(156313, 'esES', 'La sopa de tortuga no está ni la mitad de buena que la sopa de $r.\n\nTú ve a por la carne de gusano de lodo y deja estar a las tortuguitas.\n\n¡Vuelve a visitarme en otro momento, probaremos más sopas!', '', 28153),
(156312, 'esES', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡%s empieza a lanzar |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r!', 'Aparece una proyección a lo lejos...', 28153),
(156311, 'esES', '', 'Es tan fácil perder el rumbo...', 28153),
(156310, 'esES', '¡Avísame si necesitah que te ayude!', '', 28153),
(156309, 'esES', 'Ahora que todo ehtá en orden aquí, regresaré.', '', 28153),
(156308, 'esES', '|cFF0000FF(Misión)|r Viaja en barco al Estrecho de Tiragarde.', '|cFF0000FF(Misión)|r Viaja en barco al Estrecho de Tiragarde.', 28153),
(156307, 'esES', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t ¡%s empieza a lanzar |cFFFF0000|Hspell:265360|h[Engaño turbio]|h|r!', 'Aparece una proyección a lo lejos...', 28153),
(156306, 'esES', '', 'Agradezco tu ayuda, adalid.', 28153),
(156305, 'esES', '', 'Las sombras del pasado nos rodean.', 28153),
(156304, 'esES', 'Pensaba que no había nada más pesado que un yunque... pero luego te conocí a ti. Je, je, je.', '', 28153),
(156303, 'esES', 'Te vas a acabar quemando.', '', 28153),
(156302, 'esES', '¡No me hagas soltar el martillo!', '', 28153),
(156301, 'esES', 'Que tu llama arda con fuerza.', '', 28153),
(156300, 'esES', 'No dejes que tu llama se apague.', '', 28153),
(156299, 'esES', '¡Pásalo bien!', '', 28153),
(156298, 'esES', '¿Has visto mi herramienta por ahí?', '', 28153),
(156297, 'esES', '¿Puedo ayudarte?', '', 28153),
(156296, 'esES', '¡Fuego a discreción!', '', 28153),
(156286, 'esES', '', 'Tanto dolor... Tantas pérdidas...', 28153),
(156285, 'esES', '', '¿Qué camino he de seguir?', 28153),
(156284, 'esES', '', 'Debo encontrar la forma de superar esto.', 28153),
(156283, 'esES', 'La arena está roja.', 'La arena está roja.', 28153),
(156282, 'esES', '¿Cómo he acabado aquí?', '¿Cómo he acabado aquí?', 28153),
(156281, 'esES', 'Mis amigos me vengarán.', 'Mis amigos me vengarán.', 28153),
(156280, 'esES', 'Así que Turalyon brilla y Alleria tontea con las sombras... Mmm... Supongo que ahora que he vuelto a la acción, yo también tendré que buscarme un truquito.', '', 28153),
(156279, 'esES', '¿Lo hice bien?', '¿Lo hice bien?', 28153),
(156278, 'esES', '¡Te destruiré!', '¡Te destruiré!', 28153),
(156277, 'esES', '¡Ha llegado tu final!', '¡Ha llegado tu final!', 28153),
(156276, 'esES', '¡No podéis detenernos!', '¡No podéis detenernos!', 28153),
(156275, 'esES', 'Gracias a la Luz que por fin he salido del Bastión del Honor. Ese lugar olía a calcetines sudados.', '', 28153),
(156274, 'esES', '¡Hoy no, demonio!', '¡Hoy no, demonio!', 28153),
(156273, 'esES', 'Quedo con Khadgar una vez a la semana para jugar a las damas... y siempre hace trampas.', '', 28153),
(156272, 'esES', 'Todos debemos cumplir con nuestro deber.', '', 28153),
(156271, 'esES', '¡Por Stromgarde!', '', 28153),
(156270, 'esES', 'No voy a mentirte, $gjefe:jefa;.\n\nSiempre he querido formar parte de un motín.', '', 28153),
(156269, 'esES', '¡Por la Alianza!', '', 28153),
(156268, 'esES', 'La Alianza prevalecerá.', '', 28153),
(156267, 'esES', 'Lucha bien.', '', 28153),
(156266, 'esES', 'Azeroth llama. Debemos responder.', '', 28153),
(156265, 'esES', 'Lucharemos por lo que es nuestro.', '', 28153),
(156264, 'esES', 'Pase lo que pase, nos enfrentaremos a ello juntos.', '', 28153),
(156263, 'esES', 'Mi vida por la Alianza.', '', 28153),
(156262, 'esES', 'Stromgarde volverá a alzarse con orgullo.', '', 28153),
(156261, 'esES', 'Puedes suspirar todo lo que quieras, pero tengo que decirlo: ¡ES LA HORA DEL MARTILLO!', '', 28153),
(156260, 'esES', 'Dicen que tengo el síndrome del hijo mediano, pero no es fácil que uno de tus hermanos esté hecho de diamante y el otro sea un explorador famoso, ¿sabes?', '', 28153),
(156259, 'esES', '¿Pero qué...? ¡Me acaban de llamar \"Rey Caramelo\" y me han preguntado que si tenía piruletas!', '', 28153),
(156258, 'esES', '¡Nunca nos rendimos!', '', 28153),
(156257, 'esES', 'El clan Barbabronce te da las gracias.', '', 28153),
(156256, 'esES', 'Forjaz obtendrá la victoria.', '', 28153),
(156255, 'esES', 'Que tu camino te traiga gloria.', '', 28153),
(156254, 'esES', 'Que tu martillo sea certero.', '', 28153),
(156253, 'esES', 'Que la forja te acompañe.', '', 28153),
(156252, 'esES', 'Tengo el martillo, tengo el hacha... ¡Vamos allá!', '', 28153),
(156251, 'esES', '¿Has venido a ayudar a la Alianza?', '', 28153),
(156250, 'esES', 'Los Tres Martillos están en armonía.', '', 28153),
(156249, 'esES', 'Forjaz cumplirá con su deber.', '', 28153),
(156248, 'esES', '¿Quieres saber qué le pasó a las primeras seis legiones? ¿Quieres descubrirlo?', '', 28153),
(156247, 'esES', '¿Quieres acabar en el calabozo?', '', 28153),
(156246, 'esES', 'Pones a prueba mi paciencia.', '', 28153),
(156245, 'esES', 'Nuestro trabajo acaba de empezar.', '', 28153),
(156244, 'esES', 'Hasta la próxima.', '', 28153),
(156243, 'esES', 'Que la Luz te acompañe.', '', 28153),
(156242, 'esES', 'Gracias al poder de la Alianza, nuestros enemigos solo conocerán la derrota.', '', 28153),
(156241, 'esES', 'Por la Luz, el primer golpe nos pertenece.', '', 28153),
(156240, 'esES', 'Tu leyenda crece.', '', 28153),
(156239, 'esES', 'Hoy el destino nos sonríe.', '', 28153),
(156238, 'esES', 'La Horda caerá.', '', 28153),
(156237, 'esES', 'Soldado.', '', 28153),
(156236, 'esES', 'Somos los hijos y las hijas de la Alianza.', '', 28153),
(156235, 'esES', '', 'Debemos defender este mundo. ¡Adelante, Hierro Negro! ¡Hacia la batalla!', 28153),
(156234, 'esES', '', 'La sangre que corre por nuestras venas es la misma que la que corre por las de Azeroth.', 28153),
(156233, 'esES', '', 'Nuestro reino se forjó con martillos y yunques. Con corazones de fuego... y una voluntad de hierro.', 28153),
(156232, 'esES', '', 'La montaña nos da vida y nos presta su fuerza.', 28153),
(156231, 'esES', '', 'Thurgaden y Thaelin han forjado una armadura para reconocer tus logros. Llévala con orgullo.', 28153),
(156230, 'esES', '', 'Ahora la Alianza sabe que los Hierro Negro van en serio. Estamos orgullosos de que nos representes.', 28153),
(156229, 'esES', '', 'Regresa a la montaña. Tenemos algo especial para ti.', 28153),
(156228, 'esES', '', 'Es un honor tenerte con nosotros. He oído hablar de las hazañas que has realizado en tus viajes por todo Azeroth.', 28153),
(156227, 'esES', '', 'Fuimos forjados en el fuego de la montaña. Muestra tu llama al mundo.', 28153),
(156226, 'esES', '', 'Azeroth te espera, y Ventormenta será la primera chispa del yunque.', 28153),
(156225, 'esES', '', 'Es hora de que los Hierro Negro emerjan de las sombras.', 28153),
(156224, 'esES', '', 'Muchos de los nuestros estaban en contra de salir a la superficie. Pero prevaleció el coraje de los valientes. ', 28153),
(156223, 'esES', '¡Por la Alianza!', '', 28153),
(156222, 'esES', '', 'Los Hierro Negro aceptan la invitación. ¡Por la Alianza!', 28153),
(156221, 'esES', '', 'Solo es una formalidad, Majestad, no tiene importancia.', 28153),
(156220, 'esES', 'Sin embargo, nunca os hemos ofrecido formalmente que os unierais a la Alianza... Te pido disculpas por ello y te ruego que me dejes enmendar este error.', '', 28153),
(156219, 'esES', '', 'Así es.', 28153),
(156218, 'esES', 'Y aunque el clan Hierro Negro es famoso por su espíritu... independiente, nadie puede poner en duda la determinación y la lealtad de tu gente.', '', 28153),
(156217, 'esES', 'Tu posición en el Consejo de los Tres Martillos ha ayudado a mantener el orden y la estabilidad en Forjaz.', '', 28153),
(156216, 'esES', '', 'Lo mismo digo, rey Wrynn.', 28153),
(156215, 'esES', 'Reina regente Thaurissan, me alegra verte de nuevo.', '', 28153),
(156214, 'esES', '¡Eh! Estoy intentando trabajar.', '', 28153),
(156213, 'esES', '', 'Gracias. Debemos conservar lo que queda de las granjas de Drustvar.', 28153),
(156212, 'esES', '', 'Los cerdos de un granjero local han desaparecido en el bosque. ¡Sálvalos antes de que los alcancen las esporas!', 28153),
(156211, 'esES', '', 'Has desenmascarado a las brujas y mi gente vuelve a estar a salvo. Gracias.', 28153),
(156210, 'esES', '', 'El aquelarre intenta infiltrarse en Puesto de Arom. Frustra sus planes y quema su corrupción antes de que dañen a alguien.', 28153),
(156209, 'esES', '<Ofrecer polvo de coagulación: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Ofrecer polvo de coagulación: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'esES', '<Ofrecer pergamino tortoliano antiguo: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Ofrecer pergamino tortoliano antiguo: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'esES', '<Ofrecer salmuera de erizo de mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Ofrecer salmuera de erizo de mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'esES', '<Ofrecer especias astringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Ofrecer especias astringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'esES', 'Presta atención, $n. Te daré instrucciones cuando esté listo para más ingredientes.', '', 28153),
(156204, 'esES', 'Ninguno podemoh hacer nada, camarada. ¡Ehtá en manoh del loa de la muerte!', '', 28153),
(156203, 'esES', 'Bueno. Me temo que esto... es demasiado para mis habilidades.', '', 28153),
(156202, 'esES', '¡Jamil Abul\'housin se encoge de terror!', '', 28153),
(156201, 'esES', '... ¿Jamil?', '', 28153),
(156200, 'esES', 'En cualquier momento.', '', 28153),
(156199, 'esES', 'Bien... Ahora el rey debería despertarse.', '', 28153),
(156198, 'esES', 'La hemorragia no se detiene. ¡Deprisa, $n, tráeme el polvo de coagulación!', '', 28153),
(156196, 'esES', 'Los cánticos de Jamil Abul\'housin aumentan en fuerza y desesperación.', '', 28153),
(156195, 'esES', '¡Listo! Ahora le administraré la poción.', '', 28153),
(156194, 'esES', 'Jamil Abul\'housin comienza a recitar una oración en voz baja.', '', 28153),
(156193, 'esES', 'Eso, TRES pellizcos.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'esES', 'Llevo setecientos años sin hacerla. A ver si tú eres capaz de recordar algo que sea más viejo que tu tatarabuelo.', '', 28153),
(156191, 'esES', '¡¿Que se te ha olvidado la receta?!', '', 28153),
(156190, 'esES', '¿Era un pellizco o dos? $n, tráeme el pergamino.', '', 28153),
(156188, 'esES', 'Gracias. Estoy haciendo la mezcla lo más rápido que puedo. Paciencia.', '', 28153),
(156187, 'esES', '¿Nada? Jol, máh vale que te deh prisa con esa medicina...', '', 28153),
(156186, 'esES', 'Ahora la salmuera. Mira en la despensa.', '', 28153),
(156185, 'esES', '¡Que no escapen los tragadones!', '¡Que no escapen los tragadones!', 28153),
(156184, 'esES', 'Estoy listo, Jol.', 'Estoy lista, Jol.', 28153),
(156183, 'esES', 'Estos ingredientes son complicados. Tendré que poner toda mi atención. Tú debes ser mis manos para completar este brebaje. Recuerda, la vida del Rey pende de un hilo.\n\n¿Empezamos?', '', 28153),
(156182, 'esES', '', 'Si lo que dice eh cierto, hay que invehtigar. Pero con cuidado: puede que Jakra\'zet aún ande cerca.', 28153),
(156181, 'esES', 'Vaya, ¡pensé que no te importaba! ¿Por dónde empiezo?\n\nHacemos un peregrinaje a Nazmir una vez cada pocos años. A veces pasan cinco años, otras veces pueden pasar hasta veinte, todo depende de que Torga esté listo para contar una historia.\n\nCuando oímos susurros y rumores que nos advierten de que Torga tiene historias que transmitirnos, empezamos nuestro peregrinaje. Venimos aquí, nos sentamos y escuchamos todas las historias de Torga. Después se las contamos a todo el mundo.\n\nDeberías considerarte $gafortunado:afortunada;. Es difícil ver a tantos de nosotros reunidos así. Es una buena historia, si es que eso le interesa a $gun:una; $r.', '', 28153),
(156180, 'esES', 'Por encima... de mi cadáver...', 'Por encima... de mi cadáver...', 28153),
(156179, 'esES', 'Háblame acerca de tu peregrinaje.', 'Háblame acerca de tu peregrinaje.', 28153),
(156178, 'esES', '¡Nadie escapa durante mi guardia!', '¡Nadie escapa durante mi guardia!', 28153),
(156177, 'esES', 'Lo dejaremos en empate.', '', 28153),
(156176, 'esES', 'Una nueva pólvora, algo que no he visto nunca.', '', 28153),
(156175, 'esES', 'Boralus me pertenece.', '', 28153),
(156174, 'esES', '¿Qué está pasando?', '¿Qué está pasando?', 28153),
(156173, 'esES', '', '¡Por la Horda!', 28153),
(156172, 'esES', '', '¡Bien, bien! Ahora llévanos lejos de los explosivos, al otro lado del puente.', 28153),
(156171, 'esES', '', '¡No te pares! Reúne a todos los guardias de la ciudad... ¡y a su líder!', 28153),
(156170, 'esES', '', '¡Venid a por nosotros, cobardes!', 28153),
(156169, 'esES', '', '¡La Horda os hará pedazos!', 28153),
(156168, 'esES', '', '¡Hijos de Kul Tiras! ¡Vuestro trato con la Alianza será vuestra sentencia de muerte!', 28153),
(156167, 'esES', '', '¡Entra en la ciudad y reúne a todos los guardias que puedas!', 28153),
(156166, 'esES', '', '¡Flynn! ¡Aquí!', 28153),
(156165, 'esES', '¿Por qué fracasé?', '¿Por qué fracasé?', 28153),
(156164, 'esES', '', 'Eso es. ¡Liquida al capitán y los Velaniebla seguirán siendo hombres y mujeres libres!', 28153),
(156163, 'esES', '', '¿Y dices que te gustaría salir con un chico malo? No te lo recomiendo.', 28153),
(156162, 'esES', '', 'Yo jamás he dicho eso de \"¡Ah del barco!\". Lo juro.', 28153),
(156161, 'esES', '', 'Pues claro que conseguí el bastón del carnero. ¿A quién crees que se le ocurrió el término \"Lanomántico\"?', 28153),
(156160, 'esES', 'Robemos algunas armas antes de irnos.', 'Robemos algunas armas antes de irnos.', 28153),
(156159, 'esES', 'Eso de comprar y vender personas... no está bien.', 'Eso de comprar y vender personas... no está bien.', 28153),
(156158, 'esES', 'Removiendo', 'Removiendo', 28153),
(156157, 'esES', '¡Los vulperas no toleraremos ni una más!', '¡Los vulperas no toleraremos ni una más!', 28153),
(156156, 'esES', '¡Aún no nos han derrotado!', '', 28153),
(156155, 'esES', 'No quiero volver a ver un sethrak en mi vida.', 'No quiero volver a ver un sethrak en mi vida.', 28153),
(156154, 'esES', '¡Y por eso no se molesta a las tortugas!', '', 28153),
(156153, 'esES', '¡Creo que me iban a comer!', '¡Creo que me iban a comer!', 28153),
(156152, 'esES', '¡Caramba, cómo me alegro de que hayas aparecido!', '¡Caramba, cómo me alegro de que hayas aparecido!', 28153),
(156151, 'esES', '', 'Después de tantos años, ¿sigues intentando sacarme de quicio? Algunas cosas nunca cambian...', 28153),
(156150, 'esES', '', 'La verdadera batalla aún está por llegar.', 28153),
(156149, 'esES', '', 'Haré todo lo que pueda.', 28153),
(156148, 'esES', '', 'Nos esperan tiempos duros.', 28153),
(156147, 'esES', 'Duele más de lo que esperaba.', 'Duele más de lo que esperaba.', 28153),
(156146, 'esES', 'Me llevé algunos de sus cristales... El que ríe el último ríe mejor. ¡Ja!', '', 28153),
(156145, 'esES', '¡Este caparazón no está en venta!', '', 28153),
(156144, 'esES', 'De todas formas, ninguno de esos sethrak habría podido permitirse comprarme.', '', 28153),
(156143, 'esES', 'Los infieles no respetan la edad ni la sabiduría.', '', 28153),
(156142, 'esES', '¡Le contaré esta historia a todo Zuldazar!', '', 28153),
(156141, 'esES', '', 'No podemos permitir que este mundo sucumba a la oscuridad.', 28153),
(156140, 'esES', '¡Por fin, mi suerte ha cambiado!', '', 28153),
(156139, 'esES', 'La Jefa de Guerra ordena que aniquilemos a la Alianza en esta región. ¡Ocúpate de ello al instante!', '', 28153),
(156138, 'esES', '', 'El tiempo de los sueños ha acabado.', 28153),
(156137, 'esES', 'Esos bufones de la Alianza se han instalado aquí cerca. Ve... y demuéstrales la futilidad de sus ambiciones.', '', 28153),
(156136, 'esES', 'Se acumulan fuerzas de la Alianza cerca de nuestra ubicación. Que no vean amanecer.', '', 28153),
(156135, 'esES', '', '¿Qué necesitas de la hija del mar?', 28153),
(156134, 'esES', '¡La Alianza flaquea ante nosotros! La Dama Oscura estará satisfecha.', '', 28153),
(156133, 'esES', '¡Eres implacable! La Alianza ha sufrido todo el peso de nuestra cólera.', '', 28153),
(156132, 'esES', '¡Fuego!', '', 28153),
(156131, 'esES', 'La Alianza... ¡patético! Se lo pensarán dos veces antes de volver a interponerse en nuestros planes.', '', 28153),
(156130, 'esES', '', 'Nos espera un largo camino.', 28153),
(156129, 'esES', '¡Ten paciencia!', '', 28153),
(156128, 'esES', '', 'La Alianza resistirá.', 28153),
(156127, 'esES', '', 'Sé lo que debe hacerse.', 28153),
(156126, 'esES', '', 'Una simple chispa puede convertir el mundo en una hoguera.', 28153),
(156125, 'esES', '', 'Controla tu poder... o te controlará él a ti.', 28153),
(156124, 'esES', 'Por Lordaeron.', 'Por Lordaeron.', 28153),
(156123, 'esES', '', 'Jamás olvidaré.', 28153),
(156122, 'esES', '', 'Todos tenemos nuestros fantasmas.', 28153),
(156121, 'esES', '¡Por fin, algo de emoción!', '¡Por fin, algo de emoción!', 28153),
(156120, 'esES', '', 'No confíes en cualquiera.', 28153),
(156119, 'esES', 'Mi alma está sedienta.', 'Mi alma está sedienta.', 28153),
(156118, 'esES', '¡Ahora vas a sangrar!', '¡Ahora vas a sangrar!', 28153),
(156117, 'esES', 'Aprecio mucho las eliminaciones eficientes. Evitan retrasos innecesarios.', '', 28153),
(156116, 'esES', 'Típico... otro enemigo que se enfrenta al poder de la Horda... y pierde.', '', 28153),
(156115, 'esES', 'La Dama Oscura elige bien a sus campeones.', '', 28153),
(156114, 'esES', 'Un trabajo concienzudo... aunque poco refinado. Puedes volver a tus deberes habituales.', '', 28153),
(156113, 'esES', 'Ah... el sencillo placer de masacrar a un enemigo. ¡El deber no tiene por qué impedir el disfrute de una victoria!', '', 28153),
(156112, 'esES', 'Buen trabajo. Nuestras operaciones pueden avanzar según lo previsto.', '', 28153),
(156111, 'esES', 'La Horda pronto reclamará esta zona, pero un poderoso enemigo se interpone. Despeja el camino para nuestras tropas.', '', 28153),
(156110, 'esES', 'Los planes de la Jefa de Guerra en esta zona no incluyen a ese... monstruo. ¡Acaba con él!', '', 28153),
(156109, 'esES', '', '¿Nunca se te ha ocurrido pensar que tu línea temporal podría ser la \"historia alternativa\" y la mía, la real?... ¡Bum! Te acabas de quedar a cuadros, ¿eh?', 28153),
(156108, 'esES', 'Un enemigo notable está cerca de ti. ¿Nos traes su cadáver para poder investigarlo?', '', 28153),
(156107, 'esES', 'Un enemigo cercano ha eliminado a los pusilánimes de nuestros reclutas. Seguro que alguien como tú lo hará mejor.', '', 28153),
(156106, 'esES', '', 'Habéis librado una guerra contra la Legión y a nadie se le ocurrió llamarnos. ¿En serio? El destino de todo el universo estaba en juego y nadie se molestó en... Bah, ¡déjalo!', 28153),
(156105, 'esES', 'Los informes indican que hay un enemigo peligroso cerca de tu ubicación. Elimínalo... ¡y disfruta de su caída!', '', 28153),
(156104, 'esES', 'La Jefa de Guerra necesita que elimines a un objetivo en esta zona. No la decepciones.', '', 28153),
(156103, 'esES', '', 'Desde que llegué a la ciudad, parece que estos orcos de Orgrimmar están más firmes.', 28153),
(156102, 'esES', '', 'Un orco verde me dijo una vez \"Hola, ¿qué Thrall?\". Le partí la cara; odio las Grommash.', 28153),
(156101, 'esES', 'Me estaba entrando hambre...', 'Me estaba entrando hambre...', 28153),
(156100, 'esES', '', 'Habla rápido. ¡Tenemos batallas que ganar!', 28153),
(156099, 'esES', '', 'El corazón de los Mag\'har es puro y fuerte.', 28153),
(156098, 'esES', '', 'Estamos aquí para ganar esta guerra.', 28153),
(156097, 'esES', '', 'Escucharé tus palabras... Pero te juzgaré por tus hazañas.', 28153),
(156096, 'esES', '', 'No quiero imaginarme lo que habría pasado si no las hubiéramos detenido. Gracias por tu ayuda.', 28153),
(156095, 'esES', '', 'Habla.', 28153),
(156094, 'esES', '', 'Volveré a ver los cielos de Draenor.', 28153),
(156093, 'esES', '', 'La guerra es lo único que conocemos.', 28153),
(156092, 'esES', '', 'Que tus enemigos se arrastren ante ti.', 28153),
(156091, 'esES', '', 'Parece que las brujas de Corlain están realizando un nuevo tipo de ritual. ¡Detenlas antes de que sea demasiado tarde!', 28153),
(156090, 'esES', '', 'Lucha con honor. ¡Muere con gloria!', 28153),
(156089, 'esES', '', 'Los Mag\'har obtendrán la victoria.', 28153),
(156088, 'esES', '', 'Que tengas una buena muerte.', 28153),
(156087, 'esES', '', 'Ve con honor.', 28153),
(156086, 'esES', '', '¡Throm-ka!', 28153),
(156085, 'esES', '', '¡Lok\'tar!', 28153),
(156084, 'esES', 'Pobres pájaros... Que sus espíritus vuelen libres eternamente.', '', 28153),
(156083, 'esES', 'Los halcones de este lugar están bajo el influjo de las brujas. Ojalá hubiera una forma de salvarlos, pero es demasiado tarde. ¡Estas cebollas deberían ayudarte a encargarte de ellos!', '', 28153),
(156082, 'esES', '', 'Buen trabajo. ¿Cuándo se dará cuenta la Alianza de que no se puede detener a loh Zandalari?', 28153),
(156081, 'esES', '', 'Lo hah hecho bien. La Alianza temerá el poder de loh Zandalari.', 28153),
(156080, 'esES', '', 'La Alianza pronto entenderá que no se puede conquihtar a loh Zandalari.', 28153),
(156079, 'esES', '', 'Me han comunicado que la Alianza reúne tropah en loh alrededoreh. Impide que lleven a cabo suh planeh.', 28153),
(156078, 'esES', '', 'La Alianza cree que puede derrotar al Imperio Zandalari. Demuétraleh su error.', 28153),
(156077, 'esES', '', '¡De acuerdo chicos, hora de amotinarse! ¡Los Velaniebla se niegan a vendernos nuestra libertad!', 28153),
(156076, 'esES', '', 'Al principio me daba rabia que me llamaran reina del drama, pero como que ya me he acostumbrado.', 28153),
(156075, 'esES', '', 'La Alianza trama algo aquí cerca. Acaba con elloh. Haz que teman al Imperio Zandalari.', 28153),
(156074, 'esES', 'Ahora que este problema se ha resuelto podemos estar más tranquilos.', '', 28153),
(156073, 'esES', 'Los soldados que luchan por la Alianza no olvidarán lo que has hecho hoy.', '', 28153),
(156072, 'esES', 'Buen trabajo. Tengo que contarte historias sobre la Tercera Guerra. Todo esto me recuerda a esos días.', '', 28153),
(156071, 'esES', 'Buen trabajo. Estos recursos nos servirán durante mucho tiempo.', '', 28153),
(156070, 'esES', 'Esta zona es problemática para nuestras tropas. Me recuerda a la Segunda Guerra. ¿Puedes echar una mano?', '', 28153),
(156069, 'esES', 'Necesitamos ocuparnos de los problemas del área cercana. ¿Puedes encargarte?', '', 28153),
(156068, 'esES', '', '¡Pues claro que tengo una relación difícil con mi padre! Si ya cuesta llevarse bien con los padres en general, ¡imagínate con uno hecho de diamante!', 28153),
(156067, 'esES', 'El área cercana nos podría resultar de gran ayuda. Necesitamos despejarla y asegurarla.', '', 28153),
(156066, 'esES', 'Hemos recibido informes de que hay recursos vitales cerca. Conseguirlos inclinaría la balanza a nuestro favor.', '', 28153),
(156065, 'esES', '', 'Venga, haz una broma sobre mi estatura... a ver qué tal te apañas sin rótulas.', 28153),
(156064, 'esES', '¡Me hah cortado el rollo!', '', 28153),
(156063, 'esES', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(156062, 'esES', '', 'Kiro y yo solo estamos de paso. Nuestra próxima parada es el imperio de los infieles.\n\nMi plan está en marcha.\n\nEsos sethrak no lo verán venir.', 28153),
(156061, 'esES', '', 'Volvemos a vernos.', 28153),
(156060, 'esES', 'Honras a los caídos de la Séptima Legión. Daremos buen uso a esta zona.', '', 28153),
(156059, 'esES', 'Lo has hecho bien. Déjales el resto a mis soldados.', '', 28153),
(156058, 'esES', '', 'Mi pueblo vive dentro de un volcán. Sigue molestándome y verás cómo entran en erupción los Hierro Negro.', 28153),
(156057, 'esES', 'Una táctica excelente. Pronto podremos aprovechar esta zona.', '', 28153),
(156056, 'esES', 'Buen trabajo. Estos recursos servirán a la Séptima Legión durante mucho tiempo.', '', 28153),
(156055, 'esES', 'Necesitamos ayuda para tomar esta zona. Mis tropas no logran hacerlo por sí mismas.', '', 28153),
(156054, 'esES', 'Muchos de mis soldados han caído tratando de tomar la zona cercana. Elimina la amenaza que hay allí.', '', 28153),
(156053, 'esES', 'Los exploradores de la Séptima Legión han determinado que esta ubicación es de importancia extrema. Despéjala.', '', 28153),
(156052, 'esES', '', 'Los Tres Martillos están en armonía.', 28153),
(156051, 'esES', 'La Séptima Legión necesita los recursos de las inmediaciones. Recupéralos cueste lo que cueste.', '', 28153),
(156050, 'esES', '', 'Que tu martillo sea certero.', 28153),
(156049, 'esES', '', 'Que el Yunquenegro te proteja.', 28153),
(156048, 'esES', '', 'Los Hierro Negro reclamaremos el lugar que nos corresponde en este mundo.', 28153),
(156047, 'esES', '', 'Venga, vete, ¡tengo trabajo que hacer!', 28153),
(156046, 'esES', '', 'Puedes irte.', 28153),
(156045, 'esES', '', 'Puedes retirarte.', 28153),
(156044, 'esES', '¡Bombardead a mi objetivo!', '¡Bombardead a mi objetivo!', 28153),
(156043, 'esES', '¡Cañones! ¡Fuego!', '¡Cañones! ¡Fuego!', 28153),
(156042, 'esES', '¡Objetivo de destrucción marcado!', '¡Objetivo de destrucción marcado!', 28153),
(156041, 'esES', '¡Artillería! ¡Disparad a mi objetivo!', '¡Artillería! ¡Disparad a mi objetivo!', 28153),
(156040, 'esES', '', 'Vamos al lío.', 28153),
(156039, 'esES', '', '¿Y bien? Te escucho.', 28153),
(156038, 'esES', '', 'Cuida tus modales en presencia de una reina.', 28153),
(156037, 'esES', 'Me alegra ver que las arenas aún no te han tragado.', '', 28153),
(156036, 'esES', '', 'La montaña nos presta su fuerza.', 28153),
(156035, 'esES', '', 'Te diriges a la Reina regente del clan Hierro Negro.', 28153),
(156034, 'esES', '', 'El clan Hierro Negro recibirá el respeto que merece.', 28153),
(156033, 'esES', '', 'La Alianza necesita de nuestra brujería y de nuestra fuerza.', 28153),
(156032, 'esES', 'Vistiéndote', 'Vistiéndote', 28153),
(156031, 'esES', 'Despejando', 'Despejando', 28153),
(156030, 'esES', '', 'Gran trabajo. Ehtoh recursoh ayudarán mucho a loh Zandalari.', 28153),
(156029, 'esES', '', 'Impresionante. Pronto todoh aprenderán a no oponerse al Imperio Zandalari.', 28153),
(156028, 'esES', '', 'Otra victoria en tu poder, adalid de la Horda. Creo que me conviene tenerte en mi bando.', 28153),
(156027, 'esES', '', 'Loh Zandalari te agradecen tuh ehfuerzoh.', 28153),
(156026, 'esES', '', 'Nathanoh no cree que podamoh tomar ehta zona. Demuehtra que se equivoca.', 28153),
(156025, 'esES', '', 'Debemoh dehpejar la zona cercana pa que avance nuehtra campaña. Haz lo que sabeh.', 28153),
(156024, 'esES', '', 'Debemoh conseguir que ehta zona sea segura pa nuehtroh aliadoh. No te detengah ante nadie.', 28153),
(156023, 'esES', '', 'Hay recursoh en loh alrededoreh que serían útileh para nuehtra campaña. Hazte con elloh.', 28153),
(156022, 'esES', 'Dot y Dolly se zamparán esto en un santiamén.', '', 28153),
(156021, 'esES', 'Dot y Dolly son bestias caprichosas: no trabajarán con el estómago vacío. Búscales algo de comer.', '', 28153),
(156020, 'esES', '¡Largo!', '¡Largo!', 28153),
(156019, 'esES', '¡Fuera!', '¡Fuera!', 28153),
(156018, 'esES', '¡Tú no tocar!', '¡Tú no tocar!', 28153),
(156017, 'esES', '¡Tú acercarte y yo aporrearte la cabeza con roca!', '¡Tú acercarte y yo aporrearte la cabeza con roca!', 28153),
(156016, 'esES', '¡Irte de aquí o matarte!', '¡Irte de aquí o matarte!', 28153),
(156015, 'esES', '', 'Ve, reúne lo necesario para curar a ehte hombre serpiente. Yo informaré a Julwaba de lo que sabemoh.', 28153),
(156014, 'esES', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', 28153),
(156013, 'esES', 'He servido a muchos jefes de guerra. Ve a recorrer el mundo, seguro que te encuentras a varios.', '', 28153),
(156012, 'esES', '¿Por qué no dejas de molestarme? ¿No tienes alguna guerra en la que luchar? Pero qué tonterías digo... ¡Siempre hay alguna guerra en la que luchar!', '', 28153),
(156011, 'esES', 'No me darías tanto la lata si supieras cuánta sangre ha probado mi hacha.', '', 28153),
(156010, 'esES', 'Estoy mayor para estas tonterías.', '', 28153),
(156009, 'esES', 'Sirvo a la Horda.', '', 28153),
(156008, 'esES', 'Habla rápido... y sin mentiras.', '', 28153),
(156007, 'esES', 'No hay tiempo para andarse con rodeos.', '', 28153),
(156006, 'esES', '¿Qué necesitas?', '', 28153),
(156005, 'esES', '¡Throm-ka!', '', 28153),
(156004, 'esES', '¡Lok\'tar!', '', 28153),
(156003, 'esES', 'Soy Colmillosauro, hermano de Broxigar.', '', 28153),
(156002, 'esES', 'La Horda prevalecerá.', '', 28153),
(156001, 'esES', 'Ya no gustarme esto. ¡Ahora mí correr!', 'Ya no gustarme esto. ¡Ahora mí correr!', 28153),
(156000, 'esES', 'En el combate, la estrategia es tan importante como la fuerza.', '', 28153),
(155999, 'esES', '¡Hurra! ¡Mí libre!', '¡Hurra! ¡Mí libre!', 28153),
(155998, 'esES', '¡Mí salir de aquí!', '¡Mí salir de aquí!', 28153),
(155997, 'esES', 'Somos la auténtica fuerza de Kalimdor.', '', 28153),
(155996, 'esES', '¿Por qué ocurrir esto?', '¿Por qué ocurrir esto?', 28153),
(155995, 'esES', '¡Mí no morir, tú cubrirme!', '¡Mí no morir, tú cubrirme!', 28153),
(155994, 'esES', '¡¿Qué estar pasando?!', '¡¿Qué estar pasando?!', 28153),
(155993, 'esES', '¡Cuidado, humanos locos por todas partes!', '¡Cuidado, humanos locos por todas partes!', 28153),
(155992, 'esES', 'No envejezcas... si puedes evitarlo.', '', 28153),
(155991, 'esES', 'Sin honor no somos nada.', '', 28153),
(155990, 'esES', 'Morir hoy, en el campo de batalla, sería una muerte digna de un orco.', '', 28153),
(155989, 'esES', 'Te deseo una muerte en combate contra un odiado enemigo.', '', 28153),
(155988, 'esES', 'A ver si puedes poner a Loh a salvo de las algas.', '', 28153),
(155987, 'esES', '\"Loh y el mar\". Un joven tortoliano debe buscar un lugar seguro tras surgir de las arenas.', '', 28153),
(155986, 'esES', '', 'Los esbirros de las brujas han sido derrotados y nuestros leñadores pueden volver al trabajo. Gracias.', 28153),
(155985, 'esES', 'Solo voy a limpiar ehto de aquí...', '', 28153),
(155984, 'esES', '', 'Las brujas han enviado a sus esbirros a reclamar nuestras operaciones forestales. ¡Reúne a los leñadores y quema a esas brujas!', 28153),
(155983, 'esES', '', 'Cuenca del Flechero vuelve a ser libre de la corrupción del aquelarre. Gracias.', 28153),
(155982, 'esES', '', '¡El aquelarre asedia Cuenca del Flechero! ¡Libera a sus habitantes y reconquista la ciudad!', 28153),
(155981, 'esES', 'Psst... ¡Por aquí, $n!', '', 28153),
(155980, 'esES', '', 'Debemos defender lo que es justo.', 28153),
(155979, 'esES', '', 'Cuando llegue la hora, estaré allí.', 28153),
(155978, 'esES', '', 'Que así sea.', 28153),
(155977, 'esES', '', 'Debemos ayudar a los que no pueden valerse por sí mismos.', 28153),
(155976, 'esES', '', 'Sin honor no somos nada.', 28153),
(155975, 'esES', '', 'Si le cuentas a alguien lo que acaba de pasar, serás el desayuno de mi grifo. ¡¿Entendido?!', 28153),
(155974, 'esES', '', 'Lucharé hasta el aciago final.', 28153),
(155973, 'esES', '', 'Oh, no... No has oído nada.', 28153),
(155972, 'esES', '', 'Soy... una escudera... altamente disciplinada... con una voluntad de acero...', 28153),
(155971, 'esES', '', '¡Para! ¡Me haces cosquillas! ¡Las manos quietas!', 28153),
(155970, 'esES', '', '¡Eh! ¡Para!', 28153),
(155969, 'esES', '', 'Podemos hacerlo.', 28153),
(155968, 'esES', '', 'Sirve con honor.', 28153),
(155967, 'esES', '', 'No pierdas el rumbo.', 28153),
(155966, 'esES', '', 'Que el viento os impulse, camaradas. Pero mi batalla está aquí, junto a los vulperas.', 28153),
(155965, 'esES', '', '¡Vuelve con historias!', 28153),
(155964, 'esES', '', '¡Por Kul Tiras!', 28153),
(155963, 'esES', '', 'El deber te llama.', 28153),
(155962, 'esES', '', 'Hasta pronto.', 28153),
(155961, 'esES', '', '¿Cuál es la situación?', 28153),
(155960, 'esES', '', '¡Por fin algo de acción!', 28153),
(155959, 'esES', '', 'He entrenado toda mi vida para esto.', 28153),
(155956, 'esES', '', 'Lograremos unificar Kul Tiras.', 28153),
(155955, 'esES', '', 'Siempre he soñado con vivir aventuras.', 28153),
(155953, 'esES', 'El valle es nuestro hogar.', '', 28153),
(155952, 'esES', 'Yo te cubro si tú me cubres.', '', 28153),
(155950, 'esES', 'Ten cuidado ahí fuera.', '', 28153),
(155947, 'esES', 'Estamos juntos en esto.', '', 28153),
(155946, 'esES', '', 'Aviso. Nivel de potencia de explosión de recreación casi máximo.', 28153),
(155945, 'esES', '', 'Atención. Potencia de explosión de recreación casi máxima.', 28153),
(155944, 'esES', '', 'Atención. Potencia máxima inminente.', 28153),
(155943, 'esES', '', 'Aviso. Nivel de potencia casi máximo.', 28153),
(155942, 'esES', 'No hay nada que el trabajo duro no pueda arreglar.', '', 28153),
(155941, 'esES', 'Mi corazón pertenece a este valle.', '', 28153),
(155939, 'esES', '', '¿En qué puedo ayudar?', 28153),
(155938, 'esES', '¿Oyes eso? Es el abismo que me susurra. Y habla... ¡de ti! ¿Cómo? Ajá. Ya veo. Ha dicho: \"Deja en paz a Pike\". ¿No es increíble?', '', 28153),
(155937, 'esES', 'Bueno, ¡resultan bastante útiles para muchas cosas distintas!$b$bEvidentemente, se pueden utilizar como herramientas afiladas para perforar, pero las plumas también tienen otras propiedades útiles. Si las mueles, puedes obtener un polvo muy fino que es perfecto como agente aglutinante. Puedes hervirlas y utilizar su aceite como detergente y, por supuesto, las puedes aprovechar como mondadientes.', '', 28153),
(155936, 'esES', '¡Tendré que matarte junto con el rehto de tuh ehtúpidoh amigoh!', '', 28153),
(155935, 'esES', 'Tongo... ¿asesinado por $gun forastero:una forastera;? ¡Debí de haberlo sobrevalorado!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'esES', 'Así no... No... Aaaah...', '', 28153),
(155933, 'esES', 'He hecho voto de mantener la paz en estas tierras. Pero estoy dispuesto a hacer una excepción contigo.', '', 28153),
(155932, 'esES', 'Molesta cuanto quieras. La paciencia de los Sabiomar es legendaria.', '', 28153),
(155931, 'esES', '', '¡Muy buenas!', 28153),
(155930, 'esES', 'Por cierto, ¿para qué quieres las plumas?', 'Por cierto, ¿para qué quieres las plumas?', 28153),
(155929, 'esES', 'Ofrenda', 'Ofrenda', 28153),
(155928, 'esES', '¿Se te ha subido el trago a la cabeza? ¿Y ni siquiera lo has compartido? Me ofendes.', '', 28153),
(155927, 'esES', 'Alto. Sé que quito el aliento, pero tenemos trabajo.', '', 28153),
(155926, 'esES', 'Bueno, a menos que la marina te haya reclutado a la fuerza... O que te hayan capturado los piratas... Y luego te haya atrapado la marina...', '', 28153),
(155925, 'esES', 'Ah, mar abierto, una saloma en los labios y el viento en el pelo del pecho. Eso es libertad.', '', 28153),
(155924, 'esES', 'No mires atrás.', '', 28153),
(155923, 'esES', 'No dejes de otear el horizonte.', '', 28153),
(155922, 'esES', 'La próxima ronda corre de mi cuenta.', '', 28153),
(155921, 'esES', 'A por la recompensa.', '', 28153),
(155920, 'esES', 'Ya nos veremos.', '', 28153),
(155919, 'esES', '<El rey Rastakhan respira con mucha dificultad. Los vendajes que le envuelven el pecho están empapados de sangre>.', '', 28153),
(155918, 'esES', 'Ten cuidado ahí fuera.', '', 28153),
(155917, 'esES', 'Que no se te moje la pólvora.', '', 28153),
(155916, 'esES', '¿Cuál es tu historia?', '', 28153),
(155915, 'esES', '¡Excelente! Empezaré a preparar lo que necesitamos de inmediato. Estoy seguro de que los pescadores locales también se alegrarán de ver bandadas más pequeñas.', '', 28153),
(155914, 'esES', 'Soy Jamil Abul\'housin, el Médico Real. No eh la primera vez que curo al Rey y, si loh loa quieren, no será la última.', '', 28153),
(155913, 'esES', 'Necesito ciertas partes de los peces y cangrejos locales. Por desgracia, las gaviotas también las quieren. ¡Consígueme lo que necesito y deshazte de esos pajarracos!', '', 28153),
(155912, 'esES', '¿Cómo va la curación?', '¿Cómo va la curación?', 28153),
(155911, 'esES', 'Sí... ¡sí! Que esta tierra tiemble frente al poder de la Horda!', '', 28153),
(155910, 'esES', 'Hemoh pasado mucho juntoh, el viejo Rahtakhan y yo. Pero ehto...\n\n<Jamil hace un gesto hacia el cuerpo magullado del rey>.\n\nEhto eh malo.', '', 28153),
(155909, 'esES', '<Jol no levanta la vista de sus brebajes>.\n\nAl rey se le acaba el tiempo.', '', 28153),
(155908, 'esES', 'Un trabajo es un trabajo.', '', 28153),
(155907, 'esES', 'Eso servirá. Es una pena no haber podido convertir esa amenaza en un arma contra nuestros enemigos.', '', 28153),
(155906, 'esES', 'Hay un enemigo poderoso en las inmediaciones que... se les resiste a nuestras tropas. Confío en que sepas qué hacer.', '', 28153),
(155905, 'esES', 'A la Jefa de Guerra le complacerá tu éxito.', '', 28153),
(155904, 'esES', 'Un enemigo peligroso acecha cerca. Elimínalo antes de que altere nuestros planes.', '', 28153),
(155903, 'esES', 'Las fuerzas enemigas de esta zona obstaculizan nuestros planes. La Jefa de Guerra espera que se resuelva el problema. No le falles.', '', 28153),
(155902, 'esES', '¿Cómo ha podido Rhenik permitir esto?', '¿Cómo ha podido Rhenik permitir esto?', 28153),
(155901, 'esES', '¡Otra vez no!', '¡Otra vez no!', 28153),
(155900, 'esES', '¡Alguien pagará por esto!', '¡Alguien pagará por esto!', 28153),
(155899, 'esES', '¿Por qué siempre destruyen el grog?', '¿Por qué siempre destruyen el grog?', 28153),
(155898, 'esES', '¡El grog no!', '¡El grog no!', 28153),
(155897, 'esES', 'Oro o sangre, todo tiene un precio.', '', 28153),
(155896, 'esES', 'Bueno, no era así como tenían que salir las cosas. ¿Por qué no pruebas otra vez?', '', 28153),
(155895, 'esES', '¿Tienes sed? Yo tengo sed.', '', 28153),
(155894, 'esES', 'Soy todo oídos.', '', 28153),
(155893, 'esES', '¿Qué te cuentas?', '', 28153),
(155892, 'esES', '¡Ah del barco!', '', 28153),
(155891, 'esES', 'Ándate con cuidado.', '', 28153),
(155890, 'esES', 'Hasta la próxima.', '', 28153),
(155889, 'esES', '¡Hasta otra!', '', 28153),
(155888, 'esES', '¿Grog o cerveza? ¿Qué tal ambos?', '', 28153),
(155887, 'esES', '¿Qué querías?', '', 28153),
(155886, 'esES', '¡Bien hecho!', '', 28153),
(155885, 'esES', '¿Qué puedo hacer por ti?', '', 28153),
(155884, 'esES', '¿Puedes guiar a Loh hasta toda la comida de la isla y después hasta su choza, sin pasar dos veces por el mismo punto?', '', 28153),
(155883, 'esES', '\"Una vida sencilla\". Un día, Loh decidió irse a vivir una vida tranquila en una isla remota.', '', 28153),
(155882, 'esES', '¿Sabes cómo llamábamos a los cadetes como tú en la Segunda Guerra? Percebes... ¡porque se te pegan al trasero!', '', 28153),
(155881, 'esES', 'Su camino solía estar sembrado de peligro. Fíjate en esta historia, por ejemplo...', '', 28153),
(155880, 'esES', 'A los tortolianos nos encanta la historia de Loh, un joven tortoliano que viajó por el mundo.', '', 28153),
(155879, 'esES', '¿Quieres que te cuente una batallita?', '', 28153),
(155878, 'esES', 'En mis tiempos sabíamos cuándo se había terminado la conversación.', '', 28153),
(155877, 'esES', '', 'El ciclo de la vida puede ser cruel...', 28153),
(155876, 'esES', '', '¡Una tortuga ha llegado al agua!', 28153),
(155875, 'esES', '', '¡Gracias!', 28153),
(155874, 'esES', '', 'Los tortolianos inician su vida rodeados de peligro, como estas tortugas de la playa. ¡Defiéndelas mientras se abren paso hacia el océano!', 28153),
(155873, 'esES', '', '¡Buen trabajo! No es el uso original de esa máquina, pero resulta igualmente útil.', 28153),
(155872, 'esES', '', 'Si no llevan una placa de identificación... ¡mátalos!', 28153),
(155871, 'esES', '', '¿Quién es el idiota que ha perdido varias cajas de bombas?', 28153),
(155870, 'esES', '', 'Algunos de los hombres de Puesto de Arom han conseguido hacer funcionar esa máquina minera. ¡Vuélvela contra sus creadores de la Horda!', 28153),
(155869, 'esES', '', '¡Puedo compensar el exceso de gastos suprimiendo tu nómina!', 28153),
(155868, 'esES', '', 'Puede que tenga que hacer algunos recortes para ajustar nuestros gastos.', 28153),
(155867, 'esES', '¡Invasores en la fundición! Repito, INVA...', '¡Invasores en la fundición! Repito, INVA...', 28153),
(155866, 'esES', 'Que el honor te guíe.', '', 28153),
(155865, 'esES', 'Por la Lady Almirante.', '', 28153),
(155864, 'esES', 'Por Kul Tiras.', '', 28153),
(155863, 'esES', '¡No dejes que te vean sudar!', '', 28153),
(155862, 'esES', 'No bajes la guardia.', '', 28153),
(155861, 'esES', 'Buen viento y buena mar.', '', 28153),
(155860, 'esES', '¡Retírate!', '', 28153),
(155859, 'esES', '', '', 28153),
(155858, 'esES', '', '', 28153),
(155857, 'esES', '¡Silencio!', '', 28153),
(155856, 'esES', '', '', 28153),
(155855, 'esES', 'He vivido mil batallas.', '', 28153),
(155854, 'esES', '¿Traes nuevas del frente?', '', 28153),
(155853, 'esES', '¿Qué necesitas?', '', 28153),
(155852, 'esES', 'Estos viejos huesos ansían la batalla.', '', 28153),
(155851, 'esES', '¿Algo de lo que informar?', '', 28153),
(155850, 'esES', '¡Muy buenas!', '', 28153),
(155849, 'esES', '', 'No pidas favores.', 28153),
(155848, 'esES', '', 'Por viento y mar, tenemos libertad.', 28153),
(155847, 'esES', '', 'Kul Tiras capeará cualquier temporal.', 28153),
(155846, 'esES', '', 'Te escucho.', 28153),
(155845, 'esES', '', '¿Cuáles son tus condiciones?', 28153),
(155844, 'esES', 'Debemos seguir adelante.', '', 28153),
(155843, 'esES', 'No temas el curso de las mareas.', '', 28153),
(155842, 'esES', 'Que las corrientes te guíen.', '', 28153),
(155841, 'esES', 'No olvides a los caídos.', '', 28153),
(155840, 'esES', 'Jamás pierdas de vista el mar.', '', 28153),
(155839, 'esES', '', 'No tengo tiempo para charlas.', 28153),
(155838, 'esES', 'La tormenta ruge en el interior de todos.', '', 28153),
(155837, 'esES', 'Estoy aquí para batirme en duelo.', 'Estoy aquí para batirme en duelo.', 28153),
(155836, 'esES', 'Por poco. Vuelve a intentarlo.', '', 28153),
(155835, 'esES', '¡Oh, una pareja!', '', 28153),
(155834, 'esES', '¡Bien hecho!', '', 28153),
(155833, 'esES', 'He coleccionado muchas cosas a lo largo de los años. A ver qué tal se te da a ti.', '', 28153),
(155832, 'esES', 'Eso si te guhta correr. Si quiereh volar, ve a ver a Pa\'ku, loa de loh vientoh. Tiene menoh tótemh, pero loh suyoh conceden atajoh de vuelo por toda la ciudad.', '', 28153),
(155831, 'esES', '', 'Gonk, maehtro de lah formah y señor de la caza, eh un loa poderoso. Te puede conceder acceso a loh tótemh que tiene por la ciudad. Aumentarán tu velocidad al ehtar cerca de elloh.', 28153),
(155830, 'esES', 'Las profundidades anunciaron tu llegada.', '', 28153),
(155829, 'esES', 'Te escucho.', '', 28153),
(155828, 'esES', '¿Me necesitas?', '', 28153),
(155827, 'esES', 'Que las mareas te bendigan.', '', 28153),
(155826, 'esES', 'Levad anclas, zarpamos de inmediato. Lo último que quiero es un agujero en mi precioso barco.', '', 28153),
(155825, 'esES', 'Veo que también quieren la azerita. No son tontos, pero nosotros somos más rápidos. Moveos, antes de que nos vean.', '', 28153),
(155824, 'esES', 'Ya la tenemos toda. Hemos limpiado la isla... Y en el momento idóneo, además. Se acercan barcos Zandalari.', '', 28153),
(155823, 'esES', 'Y parece que también andan recolectando azerita. Qué oportuno. Matadlos y quitádsela.', '', 28153),
(155822, 'esES', '¿Hozen? ¿Aquí? Nunca se sabe a quién se puede encontrar uno en estas islas.', '', 28153),
(155821, 'esES', 'Acabamos de divisar un buen montón de azerita cerca. Esto va a ser genial.', '', 28153),
(155820, 'esES', 'Precioso. Bueno, precioso no; sangriento y asqueroso. Pero la azerita es la azerita.', '', 28153),
(155819, 'esES', '¡Vaya pedazo de bicho! ¡Y está cubierto de azerita! Vosotros matadlo y nosotros extraeremos la mercancía.', '', 28153),
(155818, 'esES', 'Vale, el detector señala otra fuente de azerita por vuestra zona. Id a investigar.', '', 28153),
(155817, 'esES', '¡Yuju! ¡Vaya montón! ¡Buen trabajo!', '', 28153),
(155816, 'esES', '¡Vaya! Qué montón de azerita. Extraed esa preciosidad y llevaremos los fragmentos al barco en un periquete.', '', 28153),
(155815, 'esES', 'Nuestro detector de azerita parece que capta... bueno, azerita, obviamente. ¿Por qué no vais a investigar? Yo... eh... os espero aquí.', '', 28153),
(155814, 'esES', 'Acercaos a la orilla sin chocar con nada y echad el ancla. Gracias.', '', 28153),
(155813, 'esES', 'Igual también hay, no sé, arañas gigantes. Yo solo aviso: nunca se sabe.', '', 28153),
(155812, 'esES', 'Este es el lugar, estoy seguro. Aquí tiene que haber un montón de azerita.', '', 28153),
(155811, 'esES', '¡$n! ¡Estás aquí! ¡Gracias a la Dama Oscura! Rexxar ha desviado a algunos efectivos de Kul Tiras a los edificios de ahí delante. ¡Necesita refuerzos!', '¡$n! ¡Estás aquí! ¡Gracias a la Dama Oscura! Rexxar ha desviado a algunos efectivos de Kul Tiras a los edificios de ahí delante. ¡Necesita refuerzos!', 28153),
(155810, 'esES', '¡Deprisa, baja a la bodega y agarra un cañón! ¡Nuestras tropas nos necesitan!', '', 28153),
(155809, 'esES', 'Esto es lo que queda de Vadekius. Fue un dragón poderoso.', 'Esto es lo que queda de Vadekius. Fue un dragón poderoso.', 28153),
(155808, 'esES', 'No te hagas ilusiones.', 'No te hagas ilusiones.', 28153),
(155807, 'esES', 'Habría hecho falta algo muy oscuro y poderoso para matarlo.', 'Habría hecho falta algo muy oscuro y poderoso para matarlo.', 28153),
(155806, 'esES', 'Esto es lo que queda de Vadekius. Fue un dragón poderoso.', 'Esto es lo que queda de Vadekius. Fue un dragón poderoso.', 28153),
(155805, 'esES', 'Pero por algo se empieza.', 'Pero por algo se empieza.', 28153),
(155804, 'esES', 'Mi corazón no es tan grande como el de mi Reina.', 'Mi corazón no es tan grande como el de mi Reina.', 28153),
(155803, 'esES', 'No podré perdonarte fácilmente lo que le hiciste a Kyranastrasz.', 'No podré perdonarte fácilmente lo que le hiciste a Kyranastrasz.', 28153),
(155802, 'esES', 'Gracias, supongo.', 'Gracias, supongo.', 28153),
(155801, 'esES', 'Te agradezco tu ayuda, $n.', 'Te agradezco tu ayuda, $n.', 28153),
(155800, 'esES', 'No queremos que se repitan esos terribles acontecimientos.', 'No queremos que se repitan esos terribles acontecimientos.', 28153),
(155799, 'esES', 'Para encontrar su lugar de descanso, el Señor de la Muerte invadió nuestro Sagrario Rubí.', 'Para encontrar su lugar de descanso, el Señor de la Muerte invadió nuestro Sagrario Rubí.', 28153),
(155798, 'esES', 'Durante la reciente guerra contra la Legión, uno de los nuestros fue reanimado como una criatura no-muerta.', 'Durante la reciente guerra contra la Legión, uno de los nuestros fue reanimado como una criatura no-muerta.', 28153),
(155797, 'esES', 'Entonces, $n y yo nos encargaremos de la tarea. Ven, $c, te llevaré al lugar del ritual.', 'Entonces, $n y yo nos encargaremos de la tarea. Ven, $c, te llevaré al lugar del ritual.', 28153),
(155796, 'esES', '', 'Veo que $n está regresando. Tal vez pueda ayudarte, Zallestrasza.', 28153),
(155795, 'esES', 'Os preocupáis demasiado. Ya me siento mucho mejor.', 'Os preocupáis demasiado. Ya me siento mucho mejor.', 28153),
(155794, 'esES', 'No te muevas y ayudaré con la sanación.', 'No te muevas y ayudaré con la sanación.', 28153),
(155793, 'esES', '¡Casi no puedes sentarte, Theo!', '¡Casi no puedes sentarte, Theo!', 28153),
(155792, 'esES', '', '¡Bien hecho, $n! Entremos en mi nuevo despacho.', 28153),
(155791, 'esES', '', 'Esos eran míos. ¡Me los cuento!', 28153),
(155790, 'esES', 'Necesitaré un poder increíble para enfrentarme a Korthek en la batalla. Siempre ha sido mejor luchador que yo.\n\nExtraeré todo el poder que pueda de estos cristales. Recemos por que sea suficiente.', '', 28153),
(155789, 'esES', '', 'Las arañas ya no suponen un peligro. Nuestra gente puede volver a ir al bosque sin temor a quedar atrapada en una telaraña.', 28153),
(155788, 'esES', '', 'Arañas muy peligrosas han infectado estos bosques y amenazan a los cazadores de Drustvar. ¡Achichárralas!', 28153),
(155787, 'esES', 'Intercambiando', 'Intercambiando', 28153),
(155786, 'esES', '', 'Buen trabajo. Con ehtoh suminihtroh nuehtrah tropah podrán enfrentarse al clima.', 28153),
(155785, 'esES', '', 'Nuestroh ehploradoreh informan de que loh humanoh han dehcubierto un modo de hacerse con la piel de loh animaleh sin dañarloh. Raro... pero eficaz.', 28153),
(155784, 'esES', 'Algo malvado ronda por el almacén de madera. Está demasiado cerca de Boralus como para ignorarlo.', '', 28153),
(155783, 'esES', '¡Una buena presa! Los días del monstruo estaban contados desde que llegó a las costas de Kul Tiras.', '', 28153),
(155782, 'esES', 'Los de las vintas le han echado el anzuelo a algo grande. Les vendría bien tu ayuda.', '', 28153),
(155781, 'esES', 'Quemando', 'Quemando', 28153),
(155780, 'esES', 'Estamos juntos en esto. ¡No me echaré atrás!', 'Estamos juntos en esto. ¡No me echaré atrás!', 28153),
(155779, 'esES', 'Si muero hoy... ¡caeré luchando!', 'Si muero hoy... ¡caeré luchando!', 28153),
(155778, 'esES', '¡Mojambo nunca me cogerá vivo!', '¡Mojambo nunca me cogerá viva!', 28153),
(155777, 'esES', '¡Me niego a arrodillarme ante Mojambo y su banda!', '¡Me niego a arrodillarme ante Mojambo y su banda!', 28153),
(155776, 'esES', '¡Lucharé hasta mi último aliento!', '¡Lucharé hasta mi último aliento!', 28153),
(155775, 'esES', '¡Mojambo no nos derrotará sin que le plantemos cara!', '¡Mojambo no nos derrotará sin que le plantemos cara!', 28153),
(155774, 'esES', 'La batalla se acerca. Toma esta espada y no bajes la guardia.', 'La batalla se acerca. Toma esta espada y no bajes la guardia.', 28153),
(155773, 'esES', 'Este es nuestro hogar. No lo abandonaremos sin luchar.', 'Este es nuestro hogar. No lo abandonaremos sin luchar.', 28153),
(155772, 'esES', '', '¡Buen trabajo! Un dolor de cabeza menos para los marinos.', 28153),
(155771, 'esES', '', '¡Menuda pieza! Creo que podría aprender mucho observándote.', 28153),
(155770, 'esES', '', 'Los caminos de Kul Tiras son más seguros gracias a ti.', 28153),
(155769, 'esES', '', 'El ejército ha tenido problemas con una bestia en esta zona. ¡Ayudémoslos!', 28153),
(155768, 'esES', '', 'Hay una bestia cruel en la zona. ¡No podemos ignorar esta amenaza por el bien de Kul Tiras!', 28153),
(155767, 'esES', '', 'No podemos permitir que semejante abominación siga atacando a civiles inocentes. ¡Acaba con ella!', 28153),
(155766, 'esES', '¿No tienes que ir a hacer algo?', '¿No tienes que ir a hacer algo?', 28153),
(155765, 'esES', '¡Eh, $geste:esta; me está mirando raro!', '¡Eh, $geste:esta; me está mirando raro!', 28153),
(155764, 'esES', '¡Estás muy lejos de casa, colega!', '¡Estás muy lejos de casa, colega!', 28153),
(155763, 'esES', 'Cielo rojo al anochecer, nada que temer. ¡Cielo rojo en la alborada, cuidado que el tiempo se enfada!', '', 28153),
(155762, 'esES', 'Quiero teletransportarme a donde está G\'huun.', 'Quiero teletransportarme a donde está G\'huun.', 28153),
(155761, 'esES', 'Quiero teletransportarme a donde está Mythrax.', 'Quiero teletransportarme a donde está Mythrax.', 28153),
(155760, 'esES', 'Quiero teletransportarme a donde está Zul.', 'Quiero teletransportarme a donde está Zul.', 28153),
(155759, 'esES', 'Quiero teletransportarme hasta el elemental de sangre.', 'Quiero teletransportarme hasta el elemental de sangre.', 28153),
(155758, 'esES', 'Quiero teletransportarme a donde está Zek\'voz.', 'Quiero teletransportarme a donde está Zek\'voz.', 28153),
(155757, 'esES', 'Quiero teletransportarme a donde está el devorador fétido.', 'Quiero teletransportarme a donde está el devorador fétido.', 28153),
(155756, 'esES', 'Quiero teletransportarme a donde está MADRE.', 'Quiero teletransportarme a donde está MADRE.', 28153),
(155755, 'esES', '¡Saludos y gracias por ayudar a poner a prueba Uldir!\n\nPuedo teletransportarte directamente a cualquier jefe que esté disponible actualmente para una prueba.', '¡Saludos y gracias por ayudar a poner a prueba Uldir!\n\nPuedo teletransportarte directamente a cualquier jefe que esté disponible actualmente para una prueba.', 28153),
(155754, 'esES', '', 'Se me ha perdido el gato.', 28153),
(155753, 'esES', 'Capea el temporal que no puedah evitar y evita el temporal que no puedah capear.', '', 28153),
(155752, 'esES', '¡No olvideh que el lado mojado va abajo!', '', 28153),
(155750, 'esES', '¿Quiereh reunirte con Bwonsamdi?', '', 28153),
(155749, 'esES', 'Debe de ser muy trihte vivir en tierra firme.', '', 28153),
(155748, 'esES', 'Cuando mireh la Bahía de los Reyeh y veah esah benditah llamah azuleh, ¡recuerda que hoy hah cambiado lah tornah! Eh una victoria de peso, $n. ¡La flota pertenece pa siempre a Zandalar!', '', 28153),
(155747, 'esES', 'No dudaré en pasarte por la quilla.', '', 28153),
(155746, 'esES', 'Que tuh velah se hinchen con el viento y tu alma, con tuh sueñoh.', '', 28153),
(155745, 'esES', '¡Noh vemoh!', '', 28153),
(155744, 'esES', 'Que te vaya bien... ¡Loh mareh me llaman!', '', 28153),
(155743, 'esES', 'Si navegah con suavidad, entonceh no hah aprendido nada.', '', 28153),
(155742, 'esES', '¡Te deseo buen viento y buena mar!', '', 28153),
(155741, 'esES', '¡Espero que las mareas nos vuelvan a reunir!', '', 28153),
(155740, 'esES', '¡Ve con el viento! ¡Encuentra nuevoh horizonteh!', '', 28153),
(155739, 'esES', '¿Notah la sal en el aire? Ya ehtáh en casa.', '', 28153),
(155738, 'esES', '¡Taz\'okun! ¡Te doy la bienvenida!', '', 28153),
(155737, 'esES', 'Misión cumplida... pero podrías haber dejado un rastro de sangre menos raquítico. Hazlo mejor la próxima vez.', '', 28153),
(155736, 'esES', '¡Ah del barco!', '', 28153),
(155735, 'esES', 'La Jefa de Guerra te ordena tomar el control de esta zona en nombre de la Horda. Haz lo que consideres apropiado... siempre que te alces con la victoria.', '', 28153),
(155734, 'esES', '¡Un día sin ver tierra firme eh un buen día!', '', 28153),
(155733, 'esES', '¿Quiereh embarcarte en un viaje épico?', '', 28153),
(155732, 'esES', 'Quiero ir a Uldir (banda).', 'Quiero ir a Uldir (banda).', 28153),
(155731, 'esES', '¡Bien hecho! Nuestros pájaros tendrán un sitio más seguro en el que anidar, y de paso hemos eliminado a algunos enemigos.', '', 28153),
(155730, 'esES', '¡Espero tu regreso con gran emoción!', '', 28153),
(155729, 'esES', '¡Vuelve cuanto antes!', '', 28153),
(155728, 'esES', '¡Apuntad!', '¡Apuntad!', 28153),
(155727, 'esES', 'Ya veo, otra vez esto...', '', 28153),
(155726, 'esES', 'Deduzco que has roto algo...', '', 28153),
(155725, 'esES', '¿Puedo ayudarte?', '', 28153),
(155724, 'esES', '¿En qué puedo ayudarte?', '', 28153),
(155723, 'esES', '¡A cubierto!', '¡A cubierto!', 28153),
(155722, 'esES', 'Tienes suerte de caerme bien. Lo arreglaré por esta vez... de nuevo...', '', 28153),
(155721, 'esES', '¿En serio? ¿Se rompió al apilar todo el peso sobre algo pequeño? Quién lo habría pensado...', '', 28153),
(155720, 'esES', 'No debes de ser mucho más inteligente que mi martillo.', '', 28153),
(155719, 'esES', 'Estoy bastante seguro de que es lo mismo que arreglé la última vez.', '', 28153),
(155718, 'esES', 'Ojalá esos idiotas dejaran de romper cosas.', '', 28153),
(155717, 'esES', 'Quiero ir a la Mansión Crestavía (mazmorra).', 'Quiero ir a la Mansión Crestavía (mazmorra).', 28153),
(155716, 'esES', 'Quiero ir a Tol Dagor (mazmorra).', 'Quiero ir a Tol Dagor (mazmorra).', 28153),
(155715, 'esES', 'Quiero ir al Asedio de Boralus (mazmorra).', 'Quiero ir al Asedio de Boralus (mazmorra).', 28153),
(155714, 'esES', 'Quiero ir al Altar de la Tormenta (mazmorra).', 'Quiero ir a Fuerte Libre (mazmorra).', 28153),
(155713, 'esES', 'Quiero ir a Fuerte Libre (mazmorra).', 'Quiero ir a Fuerte Libre (mazmorra).', 28153),
(155712, 'esES', '¡Por las plumas de Plumeria! ¡Me has asustado!', '', 28153),
(155711, 'esES', '¡Los que están bajo la influencia de las brujas han robado nuestros pájaros! ¡Libera a los halcones y acaba con los esbirros de las brujas!', '', 28153),
(155710, 'esES', '¿Necesitas un chisme específico? ¿O un artilugio? ¿Y qué tal un cachivache?', '', 28153),
(155709, 'esES', 'Quiero ir a las Catacumbas Putrefactas (mazmorra).', 'Quiero ir a las Catacumbas Putrefactas (mazmorra).', 28153),
(155708, 'esES', 'Quiero ir a la VETA MADRE (mazmorra).', 'Quiero ir a la VETA MADRE (mazmorra).', 28153),
(155707, 'esES', 'Quiero ir al Templo de Sethraliss (mazmorra).', 'Quiero ir al Templo de Sethraliss (mazmorra).', 28153),
(155706, 'esES', 'Quiero ir al Reposo de los Reyes (mazmorra).', 'Quiero ir al Reposo de los Reyes (mazmorra).', 28153),
(155705, 'esES', '¡La tripulación de las vintas está preparada para todo!', '', 28153),
(155704, 'esES', 'Nuestros amigos emplumados vuelven a estar a salvo de las brujas.', '', 28153),
(155703, 'esES', '¡Las brujas están usando amuletos para maldecir a nuestra bandada antes de que nazca! ¡Deshazte de los amuletos y de los halconeros antes de que su influencia se extienda!', '', 28153),
(155702, 'esES', '', 'Largo.', 28153),
(155701, 'esES', '', 'Tengo un arma y no dudaré en usarla.', 28153),
(155700, 'esES', '', 'Me tienes harta.', 28153),
(155699, 'esES', '', 'Tú dime dónde hay una bestia y mis vintas se encargarán de ella.', 28153),
(155698, 'esES', '', 'Muffy, gato malo. ¡Ven aquí ahora mismo!', 28153),
(155697, 'esES', '', '¡Ven, gatito, gatito!', 28153),
(155696, 'esES', 'Quiero ir a Atal\'Dazar (mazmorra).', 'Quiero ir a Atal\'Dazar (mazmorra).', 28153),
(155695, 'esES', '', 'Avísame cuando te atrevas a jugar con los mayores.', 28153),
(155694, 'esES', '', 'Tengo monstruos que matar.', 28153),
(155693, 'esES', '', '¿Qué quieres?', 28153),
(155692, 'esES', 'Supongo que has completado tu misión. Bien. Informaré a la Jefa de Guerra de tu éxito.', '', 28153),
(155691, 'esES', '¡Saludos y gracias por ayudarnos a probar la beta de Battle for Azeroth!\n\nTe puedo teletransportar directamente a varias estancias de banda o mazmorra. Esto es solo teletransporte, no es un servicio para formar grupo, así que espero que tengas un grupo listo para enfrentarse a los desafíos que aguardan dentro. Si no es así, tal vez quieras probar nuestro nuevo Buscador de grupos para encontrar aliados.\n\nAsegúrate de elegir bien la dificultad que quieres probar antes de teletransportarte, ya que luego ¡no podrás salir fácilmente para cambiarla!', '¡Saludos y gracias por ayudarnos a probar la beta de Battle for Azeroth!\n\nTe puedo teletransportar directamente a varias estancias de banda o mazmorra. Esto es solo teletransporte, no es un servicio para formar grupo, así que espero que tengas un grupo listo para enfrentarse a los desafíos que aguardan dentro. Si no es así, tal vez quieras probar nuestro nuevo Buscador de grupos para encontrar aliados.\n\nAsegúrate de elegir bien la dificultad que quieres probar antes de teletransportarte, ya que luego ¡no podrás salir fácilmente para cambiarla!', 28153),
(155690, 'esES', '¡La ubicación de $n (Horda) está señalada en el mapa con una marca de |c00FFFF00|Hspell:272296|h[Asesino]|h|r! ¡Hay una recompensa por su muerte!', '¡La ubicación de $n (Horda) está señalada en el mapa con una marca de |c00FFFF00|Hspell:272296|h[Asesino]|h|r! ¡Hay una recompensa por su muerte!', 28153),
(155689, 'esES', '¡La ubicación de $n (Alianza) está señalada en el mapa con una marca de |c00FFFF00|Hspell:272295|h[Asesino]|h|r! ¡Hay una recompensa por su muerte!', '¡La ubicación de $n (Alianza) está señalada en el mapa con una marca de |c00FFFF00|Hspell:272295|h[Asesino]|h|r! ¡Hay una recompensa por su muerte!', 28153),
(155688, 'esES', 'Tenemos que contener a las tropas enemigas en esta zona. Confío en ti para esta misión.', '', 28153),
(155687, 'esES', '', 'Nunca he visto un monstruo al que no pudiera abatir.', 28153),
(155686, 'esES', 'Has tardado más de lo que me hubiese gustado... pero los resultados son aceptables. Nuestra campaña continúa.', '', 28153),
(155685, 'esES', 'La Jefa de Guerra ha reclamado todos los recursos de esta zona. Toma lo que es nuestro.', '', 28153),
(155684, 'esES', 'Sigo sin permitirte mencionarla.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'esES', '', 'Haremos buen uso de estos recursos. ¡Buen trabajo!', 28153),
(155682, 'esES', '', 'Luchah como tu hermana.', 28153),
(155681, 'esES', '', 'Los recursos de esta zona serían muy útiles para la Orden. ¡Controla la zona y asegúralos para nuestra causa!', 28153),
(155680, 'esES', 'Como desees, madre...', '', 28153),
(155679, 'esES', '', 'Minino, ¿dónde estás?', 28153),
(155678, 'esES', '', 'Vamos, Arthur.', 28153),
(155677, 'esES', '', 'Ahora, Mariscal, sé bueno y lleva a Lucille a mis aposentos. Pero antes, encárgate de estas alimañas.', 28153),
(155676, 'esES', '', '¿Has visto a mi gato?', 28153),
(155675, 'esES', '', 'Esas no son formas de tratar a una dama, Mariscal. Voy a tener que enseñarte modales.', 28153),
(155674, 'esES', '', '¿Crees que puedes seguir el ritmo?', 28153),
(155673, 'esES', '¡Aléjate de ella, bruja desalmada!', '', 28153),
(155672, 'esES', '', '¡No seas desagradecida! Tu padre está sano y salvo, ¡y además pronto será el señor de todo Kul Tiras! Únete a nosotros, pequeña...', 28153),
(155671, 'esES', '', '¿Qué...? ¡¿Qué le has hecho?!', 28153),
(155670, 'esES', '', 'Me alegro de que estés aquí, cariño. Tu padre te ha echado mucho de menos.', 28153),
(155669, 'esES', '', '¿Madre? ¿Eres tú?', 28153),
(155668, 'esES', '', 'Ya es suficiente.', 28153),
(155667, 'esES', 'He oído que tiene algo que ver con esos cajones que hemos estado recibiendo de los Gobernalle.', 'He oído que tiene algo que ver con esos cajones que hemos estado recibiendo de los Gobernalle.', 28153),
(155666, 'esES', 'La capitana Stone está muy alterada por algo.', 'La capitana Stone está muy alterada por algo.', 28153),
(155665, 'esES', 'Me alegro mucho de que nos asignaran aquí hoy.', 'Me alegro mucho de que nos asignaran aquí hoy.', 28153),
(155664, 'esES', '¿Qué? ¿Es una BOMBA? Pensaba que era un aguacate.', '', 28153),
(155663, 'esES', '', 'Cuidado, John. Esa pólvora podría volarte la mano.', 28153),
(155662, 'esES', '¡Levad anclah! ¡Zarpamoh de inmediato! Muy buen trabajo.', '', 28153),
(155661, 'esES', 'Vienen a por la azerita, como nosotroh. Adelantémonoh sin que noh vean. Hay que informar de ehto.', '', 28153),
(155660, 'esES', 'Ya la tenemoh toda. Hemoh limpiado ehta ihla, y juhto a tiempo. Veo un barco de Kul Tirah en el horizonte.', '', 28153),
(155659, 'esES', 'Parece que también ehtán reuniendo azerita. Eso eh bueno, así daremoh menoh vueltah. Haceoh con ella.', '', 28153),
(155658, 'esES', '¡Hozen! En ehtah ihlah te puedeh encontrar cualquier cosa.', '', 28153),
(155657, 'esES', 'Parece que cerca de vosotroh hay un buen montón de azerita. Id a ver si lo encontráih.', '', 28153),
(155656, 'esES', 'Así se hace. Pronto llenaremoh la bodega de azerita.', '', 28153),
(155655, 'esES', 'Eso sí que eh un monhtruo enorme, y ehtá cubierto de azerita. Acabad con él y se la arrebataremoh.', '', 28153),
(155654, 'esES', 'Parece que hay otra fuente de azerita cerca. Id a ver si la encontráih.', '', 28153),
(155653, 'esES', '¡Así se hace! Qué buen montón.', '', 28153),
(155652, 'esES', 'Ah, sí. Ese eh un buen montón. Ehtraedlo, tendremoh el barco repleto de azerita en menoh que canta un gallo.', '', 28153),
(155651, 'esES', 'La máquina indica que hay máh azerita por aquí cerca. Desembarcad e id a echar un ojo.', '', 28153),
(155650, 'esES', 'Echad anclah. Hemoh llegado.', '', 28153),
(155649, 'esES', 'No sabemoh qué noh encontraremoh aquí, así que andad con ojo.', '', 28153),
(155648, 'esES', 'Ya casi ehtamoh. Ehta eh la ihla repleta de azerita que dehcubrieron loh ehploradoreh.', '', 28153),
(155647, 'esES', 'Por supuesto, Capitana.', 'Por supuesto, Capitana.', 28153),
(155646, 'esES', '', '¡Bueno, cárgalos en el barco! Esos explosivos son un peligro.', 28153),
(155645, 'esES', 'S... sí, capitana Stone.', 'S... sí, capitana Stone.', 28153),
(155644, 'esES', '', '¿Han llegado los cargamentos de pólvora de la Fundición Gobernalle?', 28153),
(155643, 'esES', 'Sangre y truenos, ¿qué brujería es esta? ¡Nuestras naves han sido destruidas y nuestras tropas han caído al mar!', '', 28153),
(155642, 'esES', '¿Sabes? Si vendiera tapones para los oídos en Fuerte Libre me haría rico.', '', 28153),
(155641, 'esES', 'Has... ¿oído eso? ¡Espera! ¡Otra vez no! ¡Mátala, rápido!', '', 28153),
(155640, 'esES', '¡Bien! Puede que Fuerte Libre sea un lugar más seguro a partir de ahora... No me lo creo ni yo.', '', 28153),
(155639, 'esES', '¡Ja! ¡Chúpate esa!', '', 28153),
(155638, 'esES', '¡Excelente! Menos deudas para mí.', '', 28153),
(155637, 'esES', '¿Qué huele a grog y lleva un sombrero rojo? Un pirata. Uno hostil.', '', 28153),
(155636, 'esES', 'Algunos de mis amigos han visto a un criminal cerca de aquí. ¡Hagámonos con la recompensa!', '', 28153),
(155635, 'esES', 'Hay un forajido muy peligroso en la zona. Deberías acabar con él.', '', 28153),
(155634, 'esES', 'Vaya, son nuestros amigos de Ventura y Cía., que vienen a librarnos de nuestra azerita. Qué amables. Os llevaréis bien, id a hacer amigos.', '', 28153),
(155633, 'esES', 'Ventura y Cía. ha comenzado a extraer azerita por toda la isla. Deberíais hundirles el negocio.', '', 28153),
(155632, 'esES', 'Ventura y Cía. acaba de aparecer, pretenden sacar provecho de esta fuente de azerita como solo saben hacer los goblins.', '', 28153),
(155631, 'esES', 'Esos macarras de Ventura y Cía. han aparecido en la isla. Vamos a hacer que bajen sus acciones.', '', 28153),
(155630, 'esES', 'Chalupas, de construcción vrykul, y son muchas. Parece que un clan se ha echado al mar en busca de la azerita.', '', 28153),
(155629, 'esES', 'Un grupo numeroso acaba de salir de esas chalupas vrykuls, seguro que andan tras nuestro botín. No permitiremos que se lo queden, ¿entendido?', '', 28153),
(155628, 'esES', 'Acaba de atracar una flota vrykul y un montón de guerreros con aspecto temible están acampando en la isla. O al menos eso veo yo desde este barril.', '', 28153),
(155627, 'esES', 'Se acercan barcos vrykuls y parece que vienen a saquear. Es lo suyo. Siempre andan saqueando.', '', 28153),
(155626, 'esES', 'Parece que unos trols poco amigables quieren unirse a la fiesta. Están acampando por toda la isla.', '', 28153),
(155625, 'esES', 'Canoas de trols isleños en el horizonte; llegarán en cualquier momento. Esta azerita es como un imán para todo lo que odio.', '', 28153),
(155624, 'esES', 'Acaban de aparecer unos cuantos trols, y es probable que vengan a saquear la azerita. ¿Podríais mantenerlos alejados del barco?', '', 28153),
(155623, 'esES', 'Mira, acaban de llegar un montón de barcos trols. Porque ahora nos hacían falta más trols. Toda una banda de trols, ¿por qué no? Una idea genial.', '', 28153),
(155622, 'esES', '¿Qué podría mejorar mi día? Un dragón enorme salido de la nada. Por supuesto. Vaya semanita... En fin, ya sabéis, que viene un dragón.', '', 28153),
(155621, 'esES', '¡Eh, compis! Un dragón ha decidido unirse a la fiesta y parece que le interesa bastante vuestra azerita. He pensado que querríais saberlo.', '', 28153),
(155620, 'esES', 'Dragones, han venido dragones y están mirando directamente al barco. Creo que pueden verme. ¿Podéis, eh, ayudar?', '', 28153),
(155619, 'esES', 'Acaba de aterrizar todo un vuelo de dragones y apuesto a que sé lo que está buscando. ¡Buena suerte!', '', 28153),
(155618, 'esES', '¿Qué demonios le pasa al cielo? ¿Por qué está tan oscuro? ¿Y POR QUÉ hay cadáveres por toda la isla? Ay, madre.', '', 28153),
(155617, 'esES', '¡Qué pestazo! No he olido nada más asqueroso en mi vida. ¿Quién ha sido? Ah, son los muertos. ¡Escuchad! ¡Los muertos están aquí y vienen a por la azerita!', '', 28153),
(155616, 'esES', 'Y para poner las cosas más interesantes, los no-muertos están invadiendo la isla. No puedo estar ni un minuto tranquilo.', '', 28153),
(155615, 'esES', '¿Los no-muertos? ¿Aquí? No tengo ni idea de qué está pasando, pero tiene que ser algo malo.', '', 28153),
(155614, 'esES', 'Atención, he divisado barcos tol\'vir en el horizonte y parece que no vienen con ganas de comerciar de forma civilizada. Así que daos prisa, ¿vale?', '', 28153),
(155613, 'esES', 'Vaya con los tol\'vir, ¿eh? Hacía muchísimo que no veía uno de esos barcos. Bueno, pues ahora están aquí y nos odian.', '', 28153),
(155612, 'esES', 'Acaban de atracar varios barcos tol\'vir. ¿Cómo sabe todo el mundo dónde está la azerita? Qué pesadez. Anda, ocupaos de ellos.', '', 28153),
(155611, 'esES', '¿Qué es eso, un centauro? ¿Un caballombre? Oye, acaban de aparecer unos cuantos, eh... tol\'vir, creo que se llaman.', '', 28153),
(155610, 'esES', 'Barco pirata a la vista. Seguro que vienen a saquear la isla. Los piratas no saben hacer otra cosa.', '', 28153),
(155609, 'esES', 'Parece que una tripulación pirata está echando anclas, porque claro, donde hay un tesoro, hay un pirata.', '', 28153),
(155608, 'esES', 'Y ahora va y aparece un TERCER barco, claro que sí, porque siempre me tocan las misiones más divertidas. Son piratas, por cierto, por si os lo estabais preguntando.', '', 28153),
(155607, 'esES', '¡Vaya! Ese disparo de cañón casi nos da de pleno. Y ahora hay un montón de piratas llegando a tierra.', '', 28153),
(155606, 'esES', 'Se acercan saurok, probablemente atraídos por el olor de la azerita. Espera, ¿tienen nariz? No seré yo quien se lo pregunte.', '', 28153),
(155605, 'esES', 'Vaya, acaba de salir del océano toda una banda guerrera saurok. Lo que nos hacía falta.', '', 28153),
(155604, 'esES', '¿Qué es eso que viene por el mar? Oh, vaya... Saurok de las profundidades. Todos vuestros.', '', 28153),
(155603, 'esES', 'Unos lagartos con cara de pocos amigos le han echado el ojo a nuestro barco y su azerita. Habría que impedir que nos la roben, ¿no?', '', 28153),
(155602, 'esES', 'Han llegado algunos tipos nuevos; no los había visto antes. Supongo que no han venido a ayudarnos.', '', 28153),
(155601, 'esES', 'Parece que tenemos visita. No sé quiénes son, pero tienen pinta de venir buscando azerita, como nosotros. No sabría decir qué, pero tienen algo raro...', '', 28153),
(155600, 'esES', '¡Ah! ¿De dónde han salido esos tipos? Es como si hubieran surgido de la nada. Eh, tenemos compañía.', '', 28153),
(155599, 'esES', '¿Quién demonios son estos tipos? No consigo distinguir sus caras. ¿Vendrán en son de paz? Me da que no.', '', 28153),
(155598, 'esES', 'Y ahora parece que hemos captado la atención de nada menos que un dios antiguo y sus esbirros. ¿Podéis... mmm... ocuparos de la situación?', '', 28153),
(155597, 'esES', 'Ahora en la isla hay unos monstruos con tentáculos en la cara y sí, se acabó, me voy abajo, adiós.', '', 28153),
(155596, 'esES', '¿Alguien más oye esos susurros? O me estoy volviendo loco o tenemos ignotos en la isla. Ah, y vienen a por la azerita.', '', 28153),
(155595, 'esES', 'Se avecina una tormenta de oscuridad sombría. Genial, serán los dioses antiguos. Cuidado con los tentáculos.', '', 28153),
(155594, 'esES', 'Y han llegado un montón de mogu en busca de la azerita. Probablemente quieran venir aquí.', '', 28153),
(155593, 'esES', 'Acabo de ver a unos mogu vagando por la isla. Estad atentos, no nos llevamos especialmente bien...', '', 28153),
(155592, 'esES', 'Esto... Parece que unos mogu han llegado a la isla. No sé a qué vienen. Id a echar un ojo.', '', 28153),
(155591, 'esES', 'Los dragones mogu están desplegando un grupo de asalto. Una vez más, los ha atraído la azerita. Siempre igual.', '', 28153),
(155590, 'esES', 'Bueno, ya han llegado los nagas. Justo lo que nos hacía falta. Intentad que no os maten, ¿vale?', '', 28153),
(155589, 'esES', 'He avistado algunos nagas con el catalejo. Estarán aquí pronto; dadles una buena bienvenida, ¿de acuerdo?', '', 28153),
(155588, 'esES', 'Unos nagas se han abierto paso hasta la isla y pretenden hacerse con la azerita. Seguro que los envía nuestra amiga Azshara. ¿Qué estará tramando?', '', 28153),
(155587, 'esES', 'Unos nagas han salido reptando de las profundidades y pretenden hacerse con nuestro alijo. Voy a ir cargando los cañones.', '', 28153),
(155586, 'esES', 'Se está formando un banco de niebla. No, esperad, veo naves putrefactas. Vale, son los Kvaldir. Genial.', '', 28153),
(155585, 'esES', 'Hemos divisado varios barcos Kvaldir; llegarán en cualquier momento. Seguro que vienen a por la azerita. ¿Por qué diantres aceptaría este puesto?', '', 28153),
(155584, 'esES', 'La niebla se hace más densa por aquí. Tienen que ser los Kvaldir. Permaneced alerta... si es que podéis ver algo.', '', 28153),
(155583, 'esES', 'Vaya, ¿qué es eso que huele a algas? Eh, mirad, hay algunos Kvaldir por aquí.', '', 28153),
(155582, 'esES', 'Se nos echa encima una plaga de bichos; un enjambre de mántides, para ser exactos. Yo os espero bajo la cubierta, ¡pasadlo bien!', '', 28153),
(155581, 'esES', 'He oído hablar de esos tipos. Se llaman mántides, creo. Haced el favor de encargaos de ellos, ¿vale? Soy alérgico.', '', 28153),
(155580, 'esES', '¿Eso es un enjambre de abejas? No, son demasiado grandes. Son los mántides y... ya casi están aquí.', '', 28153),
(155579, 'esES', 'Esto os va a encantar: acaba de aparecer un enjambre de mántides. Y, por supuesto, vienen a por la azerita. Cómo no.', '', 28153),
(155578, 'esES', '¡Eh! ¿Qué ha pasado volando? ¿Lo habéis visto? Hay un dragón enorme por aquí. Andad con ojo.', '', 28153),
(155577, 'esES', 'Pues ha aparecido un dragón con un montón de dragoncitos y, al parecer, no les hace ninguna gracia que nos quedemos la azerita.', '', 28153),
(155576, 'esES', 'Esto ya es la monda. Un dragón Negro. ¡Un dragón Negro! ¡Y la mitad de su vuelo! ¡Aquí! La monda.', '', 28153),
(155575, 'esES', 'Un dragón enorme acaba de aterrizar en la isla. Mi bote no es ignífugo, así que quiero que lo mantengáis lejos. Hasta que parezca pequeñito.', '', 28153),
(155574, 'esES', 'Loh tol\'vir harán cualquier cosa pa conseguir la azerita. Andad con ojo.', '', 28153),
(155573, 'esES', 'Eh, parece que vienen loh tol\'vir. Y quieren nuehtra azerita. Ja, ja.', '', 28153),
(155572, 'esES', 'Nunca pensé que vería otra nave tol\'vir. Algunoh han llegado a tierra y parecen enfadadoh.', '', 28153),
(155571, 'esES', 'Unoh barcoh acaban de llegar. Solo loh he vihto una vez anteh. Tol\'vir, loh llaman. No parecen muy amihtosoh.', '', 28153),
(155570, 'esES', '', 'Intenta traer de vuelta la reliquia de una pieza, $n. Astrandis es... un tanto entusiasta.', 28153),
(155569, 'esES', '', 'Noh conviene mantener a esoh piratah alejadoh del agua. Te lo agradezco, adalid.', 28153),
(155568, 'esES', 'Te voy a tirar al muelle.', '', 28153),
(155567, 'esES', 'Las mareas no son las únicas que están inquietas.', '', 28153),
(155566, 'esES', 'Te lo advierto, no deberías hacerme enfadar.', '', 28153),
(155565, 'esES', '', 'Necesitamoh saber qué planean esoh piratah. Intercepta suh órdeneh... cuehte lo que cuehte.', 28153),
(155564, 'esES', 'Las mareas siempre vuelven.', '', 28153),
(155561, 'esES', 'Que el mar te guíe con rapidez.', '', 28153),
(155560, 'esES', 'Nunca te alejes del mar.', '', 28153),
(155558, 'esES', 'Odio los pájaros. Son sucios y ruidosos. Pasemos a asuntos más urgentes.', '', 28153),
(155557, 'esES', 'Uno de nuestros contactos en Fuerte Libre solicita ayuda para... calmar a sus pájaros. Te confío esa misión.', '', 28153),
(155556, 'esES', 'Sirvo a las mareas.', '', 28153),
(155554, 'esES', '¿Tú también notas... el poder de la piedra?', '', 28153),
(155553, 'esES', '¡Esta piedra nos hará RICOS! ¡No puedes quedártela!', '', 28153),
(155552, 'esES', 'Que las mareas te guíen.', '', 28153),
(155551, 'esES', 'Si escuchas las mareas, puedes aprender mucho sobre el mundo.', '', 28153),
(155550, 'esES', 'Tengo mis sospechas...', '', 28153),
(155549, 'esES', 'No me obligues a llamar a los guardias.', '', 28153),
(155548, 'esES', 'Si tienes algo que decir, habla.', '', 28153),
(155547, 'esES', 'Por favor... perdona a mi gato.', '', 28153),
(155546, 'esES', 'Soy un hombre muy ocupado.', '', 28153),
(155545, 'esES', '¡Vuelve con más aventuras que contar!', '', 28153),
(155543, 'esES', '¡Más chicos de los recados de Nedly! ¡Los enterraré en el barro como al resto!', '', 28153),
(155540, 'esES', '¡Fenomenal!', '', 28153),
(155539, 'esES', '¡Pásatelo de lujo!', '', 28153),
(155538, 'esES', 'Siéntete como en casa. Mi hacienda es tu hacienda.', '', 28153),
(155536, 'esES', '¡Come, bebe y disfruta!', '', 28153),
(155535, 'esES', '¡Te doy la bienvenida al Festival ecuestre y de caza de Norwington!', '', 28153),
(155534, 'esES', '', 'Y quinientos mil millones de norgabytes con imágenes de adorables felinos.', 28153),
(155533, 'esES', 'Llegas justo a tiempo. ¡Tenemos un ataque de troggs entre manos!', '', 28153),
(155532, 'esES', '', 'Juegan con fuerzah que nadie debería manipular. ¡Debemoh mantener limpioh loh mareh!', 28153),
(155531, 'esES', '¡Guerreroh de la Horda! ¡Enseñadle a la Alianza por qué luchamoh! ¡Atacad la fortaleza!', '', 28153),
(155530, 'esES', '', '¡Todos juntos! ¡Avanzad! ¡Arathi será nuestro!', 28153),
(155529, 'esES', '', 'Loh humanoh ehtán invocando algo terrible de lah profundidadeh. ¡Detenloh!', 28153),
(155528, 'esES', '¿Tortoliano?', '¿Tortoliano?', 28153),
(155527, 'esES', '', '¡Ese caparazón con brazos y piernas de ahí!\n\n¡No te dejes engañar! ¡Es muy listo y entrometido! Siempre está fisgando por ahí en busca de viejas reliquias, pergaminos y trastos.\n\nNo podemos dejar que encuentre el tesoro primero.', 28153),
(155526, 'esES', '¡Informaré a mi tío de esto!', '', 28153),
(155525, 'esES', 'Aléjate un poco.', '', 28153),
(155524, 'esES', 'Perdona, ¿podrías dejarme en paz?', '', 28153),
(155522, 'esES', 'Supongo que eso es todo.', '', 28153),
(155521, 'esES', 'Nadie me advirtió de lo... difícil que es ser líder.', '', 28153),
(155520, 'esES', 'Hago lo que puedo.', '', 28153),
(155516, 'esES', '¡Puntamuelle está bajo mi protección!', '', 28153),
(155515, 'esES', 'Debo probar mi valía ante mi tío.', '', 28153),
(155514, 'esES', 'Las mareas te dan la bienvenida.', '', 28153),
(155513, 'esES', 'Andando.', '', 28153),
(155512, 'esES', 'Si no necesitas nada, márchate.', '', 28153),
(155511, 'esES', 'Vuelvo a mi puesto.', '', 28153),
(155510, 'esES', 'Tengo un deber que cumplir.', '', 28153),
(155509, 'esES', 'Mmm.', '', 28153),
(155508, 'esES', '¡Estupendo! Debería poder crear algunas... pociones interesantes con esto.', '', 28153),
(155507, 'esES', '¡Esta zona está llena de recursos naturales e ingredientes alquímicos interesantes que nos pueden venir bien! Tráeme algunos.', '', 28153),
(155506, 'esES', '', 'Nuestros granjeros te agradecen que hayas mantenido a esas bestias a raya.', 28153),
(155505, 'esES', '', 'Unas bestias salvajes invaden las granjas costeras. Ayuda a los granjeros a solventar el problema.', 28153),
(155504, 'esES', 'Tócanos una vez más y provocarás una reacción negativa y, probablemente, letal.', '', 28153),
(155503, 'esES', 'Si vuelves a hacer eso, comprobarás que no siempre nos quedamos parados comos setas.', '', 28153),
(155502, 'esES', 'Si perdemos el sombrero, lo lamentarás.', '', 28153),
(155501, 'esES', '¿Eso es todo?', '', 28153),
(155500, 'esES', 'Crece con honor. Nuestra mente es clara.', '', 28153),
(155499, 'esES', 'Que las esporas te acompañen.', '', 28153),
(155498, 'esES', 'Te vemos.', '', 28153),
(155497, 'esES', '¡Te saludamos!', '', 28153),
(155496, 'esES', 'Siempre debe haber... un Rey Fungánime...', '', 28153),
(155495, 'esES', 'La Agonía de Hongos está hambrienta.', '', 28153),
(155494, 'esES', '¡Ah!', '', 28153),
(155493, 'esES', 'Las esporas nos encuentran...', '', 28153),
(155492, 'esES', 'No... oímos...', '', 28153),
(155491, 'esES', '¡Muere! ¡Muere! ¡Muere!', '', 28153),
(155490, 'esES', '¡Únete a nosotros!', '', 28153),
(155489, 'esES', '¡Muere! ¡Muere! ¡Muere!', '', 28153),
(155488, 'esES', '', '¡Ja! Los de las vintas se morirán de envidia.', 28153),
(155487, 'esES', 'Una maldita monstruosidad se come las entrañas de nuestros aprendices. Mátala... antes de que me vea forzado a reclutar a otro grupo de conscriptos inexpertos.', '', 28153),
(155486, 'esES', '', 'Algunos guardias de Kul Tiras han visto a una bestia enorme por la zona. Es una amenaza para los que navegan esas aguas.', 28153),
(155485, 'esES', 'Los piratas hablan de un demonio esqueleto que vive en el estrecho. Esta explicación es mucho mejor.', '', 28153),
(155484, 'esES', 'Una bestia gigantesca se ha arrastrado hasta la orilla. No sé de dónde ha salido, pero parece peligrosa.', '', 28153),
(155483, 'esES', '¡Bien hecho! Algunos presos de Tol Dagor habían cometido delitos muy graves. Él era uno de ellos.', '', 28153),
(155482, 'esES', '', 'Menuda locura. Hoy hah salvado la vida de muchoh.', 28153),
(155481, 'esES', 'Me voy...', 'Me voy...', 28153),
(155480, 'esES', 'Ahora estoy a salvo.', 'Ahora estoy a salvo.', 28153),
(155479, 'esES', 'Gracias.', 'Gracias.', 28153),
(155478, 'esES', 'Deseo descansar...', 'Deseo descansar...', 28153),
(155477, 'esES', 'Estaba tan perdido...', 'Estaba tan perdida...', 28153),
(155476, 'esES', 'Tenía mucho miedo... Ahora no lo tengo...', 'Tenía mucho miedo... Ahora no lo tengo...', 28153),
(155475, 'esES', '¿Estás bien?', '', 28153),
(155474, 'esES', 'La Luz es tan cálida...', 'La Luz es tan cálida...', 28153),
(155473, 'esES', '', 'Gracias por la ayuda. No lo olvidaremos.', 28153),
(155471, 'esES', 'Por aquí.', 'Por aquí.', 28153),
(155470, 'esES', '¡Recargad!', '¡Recargad!', 28153),
(155469, 'esES', '', '¡No permitiremos ninguna intromisión!', 28153),
(155468, 'esES', '¡Fuego!', '¡Fuego!', 28153),
(155467, 'esES', '', 'Zandalar está hecha de oro puro. Tiene que haber una forma de robar la ciudad entera.', 28153),
(155466, 'esES', '', 'Uno de loh fugitivoh de la prisión humana llegó a la cohta que hay cerca del puerto de la Horda. Eh un peligro pa todoh.', 28153),
(155465, 'esES', '¡Creo que reconozco a ese tipo! Un momento... claro que lo reconozco. Eso no es bueno.', '', 28153),
(155464, 'esES', '¡Las profundidades... nos darán... más!', '', 28153),
(155463, 'esES', '¡Este poder es un obsequio de las profundidades!', '', 28153),
(155462, 'esES', 'Pensaba que en Kul Tiras encontraríamos adversarios dignos... pero se desploman como el resto de alfeñiques de la Alianza.', '', 28153),
(155461, 'esES', 'Una forestal oscura ha atraído a uno de los consejeros de la gran almirante. La trampa esta lista... te cedo el honor de activarla.', '', 28153),
(155460, 'esES', '', 'Los espíritus de los muertos vuelven a descansar en paz.', 28153),
(155459, 'esES', 'Vale, pero vas a regresar, ¿verdad?', '', 28153),
(155458, 'esES', '¡Vale! ¡Hasta luego!', '', 28153),
(155457, 'esES', '¡Así aprenderá la Horda a no meterse con nuestros soldados! Buen trabajo.', '', 28153),
(155456, 'esES', '¡Uno de los oficiales de los Valiente tiene acorralada a una forestal oscura! ¡Ayúdalo!', '', 28153),
(155455, 'esES', '¡Mi padre es el mejor!', '', 28153),
(155454, 'esES', '¡Hoy va a ser un día guay!', '', 28153),
(155453, 'esES', 'Papá dice que, a veces, los mayores tienen miedo. ¿Tú tienes miedo?', '', 28153),
(155452, 'esES', '¡Mira qué ponis más bonitos!', '', 28153),
(155451, 'esES', '¡Nunca es demasiado tarde para aprender!', '', 28153),
(155450, 'esES', '¡Hasta pronto!', '', 28153),
(155449, 'esES', '', 'Los esbirros de las brujas han alterado a estos espíritus. Elimina su influencia corruptora y devuelve la paz a las almas perdidas.', 28153),
(155448, 'esES', 'Ah, bueno... ¡Al menoh he podido saborear la reserva Zanchuli una...<¡hip!> última vez anteh de morir!', '', 28153),
(155447, 'esES', 'Leh he oído decir que Mojambo ha reclutado refuerzoh pa la batalla. Ahora tendrá el rehpaldo de la tripulación de Tongo...', '', 28153),
(155446, 'esES', 'He vihto a la banda de Mojambo ehplorando la arena...', '', 28153),
(155445, 'esES', 'Hah cumplido tu parte del trato, así que yo también cumpliré la mía...', '', 28153),
(155444, 'esES', '¡Aaah! Hacía añoh que no probaba la reserva Zanchuli... <¡hip!>', '', 28153),
(155443, 'esES', 'Aquí está el ron. Cuéntame lo que has oído.', 'Aquí está el ron. Cuéntame lo que has oído.', 28153),
(155442, 'esES', 'Vale, ¡hasta luego! Yo... me quedo aquí.', '', 28153),
(155441, 'esES', 'Yo busco conocimiento. ¿Qué buscas tú?', '', 28153),
(155440, 'esES', 'Hemos recorrido mucho mundo, ¡pero por fin estamos aquí!', '', 28153),
(155439, 'esES', 'Buena caza.', '', 28153),
(155438, 'esES', '¡Por la Horda!', '', 28153),
(155437, 'esES', '¿Tienes que rastrear algo?', '', 28153),
(155436, 'esES', '¡Colmillos y garras!', '', 28153),
(155435, 'esES', 'Se acabó, ¡te daré caza!', '', 28153),
(155434, 'esES', 'En serio, ¡para!', '', 28153),
(155433, 'esES', 'Yo... eh... cazo solo.', '', 28153),
(155432, 'esES', '¡Que comience la caza!', '', 28153),
(155431, 'esES', 'Que así sea.', '', 28153),
(155430, 'esES', 'Al acecho.', '', 28153),
(155429, 'esES', 'Comienza la cacería.', '', 28153),
(155428, 'esES', 'Mi presa se acerca.', '', 28153),
(155427, 'esES', 'Oigo la llamada de lo salvaje.', '', 28153),
(155426, 'esES', '¿Ves esos caballos? Son bestias magníficas.', '', 28153),
(155425, 'esES', '¡Nos veremos pronto!', '', 28153),
(155424, 'esES', 'Recuerda: ¡no alimentes a los animales salvajes!', '', 28153),
(155423, 'esES', '¡Disfruta de las instalaciones!', '', 28153),
(155422, 'esES', '...', '', 28153),
(155421, 'esES', '¿Por qué estamos aquí abajo?', '¿Por qué estamos aquí abajo?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'esES', '¿Qué ibas a decirme?', '¿Qué ibas a decirme?', 28153),
(155419, 'esES', 'No debemos entretenernos. No tenemos mucho tiempo.', 'No debemos entretenernos. No tenemos mucho tiempo.', 28153),
(155418, 'esES', '¿Cómo va eso?', '', 28153),
(155417, 'esES', '¡Hola!', '', 28153),
(155416, 'esES', '¡Te doy la bienvenida a las Termas Fuenteburbuja!', '', 28153),
(155415, 'esES', '', '¡Mis hermanas... obtendrán... el poder de la piedra!', 28153),
(155414, 'esES', '', '¡Madre estará satisfecha con el poder de esta piedra!', 28153),
(155413, 'esES', 'Tú decides el primer destino. Cuando lo elijas, zarparemos de inmediato.', '', 28153),
(155412, 'esES', 'Bueno, ¿por qué esperar? Ya estamos listos. Es el momento de emprender una misión importante.', '', 28153),
(155411, 'esES', 'Que la Luz esté contigo, rey Wrynn.', '', 28153),
(155410, 'esES', 'Buen viaje, mi Rey.', '', 28153),
(155409, 'esES', 'Mis responsabilidades me exigen volver a Ventormenta, pero espero noticias de vuestros progresos. Sé que dejo esta campaña en las manos adecuadas. Buena suerte a todos.', '', 28153),
(155408, 'esES', 'Adalid.', '', 28153),
(155407, 'esES', 'Si la situación requiere un enfoque más... sutil, tanto el maestro Mathias Shaw como sus operativos del IV:7 están a tu disposición.', '', 28153),
(155406, 'esES', 'Será un honor trabajar contigo.', '', 28153),
(155405, 'esES', 'En tu gesta, contarás con el apoyo de los mejores soldados de la Alianza: la Séptima Legión, a las órdenes del alto comandante Halford Aterravermis.', '', 28153),
(155404, 'esES', 'Como adalid de la Alianza, serás crucial para vencer en esta guerra. Debemos impedir que la Horda consiga su objetivo de aliarse con los Zandalari.', '', 28153),
(155403, 'esES', 'Adalid, es el momento de llevar la lucha a Zandalar. Espero tu llegada en Boralus, a bordo del Redención del Viento.', '', 28153),
(155402, 'esES', '¡Este bosque está maldito! ¡Escapa! ¡Corre mientras puedas!', '¡Este bosque está maldito! ¡Escapa! ¡Corre mientras puedas!', 28153),
(155401, 'esES', '¡Nunca había presenciado semejante locura!', '¡Nunca había presenciado semejante locura!', 28153),
(155400, 'esES', '¡Se comieron a mi perro! ¡Pensé que después irían a por mí!', '¡Se comieron a mi perro! ¡Pensé que después irían a por mí!', 28153),
(155399, 'esES', '¡Por la chalupa cubierta de percebes de mi abuelo! ¿Qué está pasando aquí?', '¡Por la chalupa cubierta de percebes de mi abuelo! ¿Qué está pasando aquí?', 28153),
(155398, 'esES', 'Me perseguía un grupo de conejitos. ¡Conejitos!', 'Me perseguía un grupo de conejitos. ¡Conejitos!', 28153),
(155397, 'esES', '¡Aaaaaaaaaaaaaaaaaaaaaah!', '¡Aaaaaaaaaaaaaaaaaaaaaah!', 28153),
(155396, 'esES', '¡Los animales se han vuelto locos!', '¡Los animales se han vuelto locos!', 28153),
(155395, 'esES', '¡Gracias, colega!', '¡Gracias, colega!', 28153),
(155394, 'esES', 'Loh nagah vienen reptando hacia la orilla. Son muchoh, y quieren saquear la ihla.', '', 28153),
(155393, 'esES', 'Se avihtan nagah. Parece que la azerita loh ehtá atrayendo. Andad con ojo.', '', 28153),
(155392, 'esES', 'Lah fuerzah nagah acaban de aparecer; aseguraoh de que pasan un buen rato, ja.', '', 28153),
(155391, 'esES', 'Loh nagah han emergido de lah profundidadeh; han venido a por lah gemah, igual que nosotroh. Mucho cuidado.', '', 28153),
(155390, 'esES', 'Andaoh con mil ojoh: hemoh divisado un gran dragón que viene hacia nosotroh acompañado de su vuelo.', '', 28153),
(155389, 'esES', 'Han llegado dragoneh a montoneh. Se han puehto a recoger la azerita. Tal vez deberíaih pararleh loh pieh.', '', 28153),
(155388, 'esES', 'Eh, tenemoh compañía. Acaban de aparecer varioh dragoneh, y me temo que noh han vihto.', '', 28153),
(155387, 'esES', 'Algo se acerca volando... Dragoneh. Deben venir a por la azerita. Cuidado.', '', 28153),
(155386, 'esES', '¿Dragoneh negroh? ¿Aquí? Seguro que van buhcando azerita. Id con cuidado.', '', 28153),
(155385, 'esES', 'Dragoneh... Nunca pensé que vería uno adulto. Ehtán buhcando azerita, nuehtra azerita.', '', 28153),
(155384, 'esES', 'Unoh dragoneh ehtán aterrizando por aquí. La azerita loh ha atraído.', '', 28153),
(155383, 'esES', 'El cielo se ehtá ohcureciendo... ¡Un dragón Negro! Ha traído a suh hermanoh pa saquear la ihla. ¡Ayuda!', '', 28153),
(155382, 'esES', 'Acaban de llegar un montón de hombreh y equipamiento de Ventura y Cía. Ehtán buhcando azerita.', '', 28153),
(155381, 'esES', 'Ventura y Cía. quiere empezar a operar en la ihla. Sería mejor impedírselo.', '', 28153),
(155380, 'esES', 'Han venido inversoreh de Ventura y Cía. a por nuehtro botín. Necesito que tengáih una buena charla de negocioh con elloh.', '', 28153),
(155379, 'esES', 'Eh, camaradah, Ventura y Cía. ha llegado. Ehtán ehtableciendo un campamento juhto ahora.', '', 28153),
(155378, 'esES', 'Mirad, allí, un montón de barcoh de loh trolh ihleñoh. También van trah la azerita. ¡No dejéih que la consigan! ¡Ja!', '', 28153),
(155377, 'esES', 'Acaban de llegar unoh trolh de la ihla y quieren lo mihmo que nosotroh. No bajéih la guardia.', '', 28153),
(155376, 'esES', 'Canoah de trolh ihleñoh en el horizonte. Nunca me han guhtado. Matad a unoh cuantoh por mí, ¿vale?', '', 28153),
(155375, 'esES', 'Se acercan loh trolh de la ihla, y no parecen muy simpáticoh.', '', 28153),
(155374, 'esES', 'Noh ehtán friendo a cañonazoh. Hay un barco pirata echando el ancla con intención de saquear la ihla.', '', 28153),
(155373, 'esES', 'Eh, ahora también loh piratah. Ehtán desembarcando; será mejor que leh deih la bienvenida.', '', 28153),
(155372, 'esES', 'Una tripulación pirata ehtá atracando, y buhcan lo mihmo que nosotroh. Tened cuidado.', '', 28153),
(155371, 'esES', 'Me caes fatal.', 'Igual... deberías irte.', 28153),
(155370, 'esES', 'Atihbo otro barco en el horizonte y parece que eh pirata. Será mejor que acabemoh anteh de que noh roben el botín.', '', 28153),
(155369, 'esES', 'Conozco ese sonido de criaturah reptando. Se acerca un asalto saurok. Mantened loh ojoh abiertoh.', '', 28153),
(155368, 'esES', 'Lah olah se mueven de forma ehtraña. Ay, parece que son saurok, y vienen muchoh.', '', 28153),
(155367, 'esES', 'Unoh lagartoh aviesoh han puehto loh ojoh en nuehtro barco. Habrá que acabar con elloh, y rápido.', '', 28153),
(155366, 'esES', 'Una partida de guerra saurok se acerca dehde el mar. Pretenden hacerse con la azerita.', '', 28153),
(155365, 'esES', 'No... ¡En la cara no!', 'Ya puedes parar...', 28153),
(155364, 'esES', '¡No voy a cumplir los plazos!', '¡Mi seguro no cubre esto!', 28153),
(155363, 'esES', '¿Ehcucháih eso? Loh mántideh vienen a por la azerita. ¡Que no oh piquen! ¡Ja, ja!', '', 28153),
(155362, 'esES', 'Se acerca un enjambre enorme de bichoh. Cuidado ahí fuera, buhcan lo mihmo que nosotroh.', '', 28153),
(155361, 'esES', 'Esoh tipoh, mántideh creo, acaban de aparecer. Parece que también ehtán recogiendo azerita.', '', 28153),
(155360, 'esES', 'Ese zumbido... viene del cielo. Creo que hay un montón de bichoh que ehtán a punto de aterrizar en la ihla.', '', 28153),
(155359, 'esES', 'Mi seguro pagará por esto...', 'Qué vergüenza...', 28153),
(155358, 'esES', 'Que loh ehpírituh... me acojan...', 'Que loh ehpírituh... me acojan...', 28153),
(155357, 'esES', '¿Qué eh ehte olor a algah? Ahí, unah chalupah Kvaldir han llegado a la cohta.', '', 28153),
(155356, 'esES', 'No veo nada con ehta niebla. Seguro que loh Kvaldir ehtán ahí fuera, andad con ojo.', '', 28153),
(155355, 'esES', 'Se acercan barcoh putrefactoh, y apehtan a Kvaldir. Vienen a por nuehtra azerita.', '', 28153),
(155354, 'esES', 'Se ehtá levantando niebla. Y no una niebla cualquiera. Se acercan loh Kvaldir.', '', 28153),
(155353, 'esES', 'No ha salido como lo había planeado.', 'No ha salido como lo había planeado.', 28153),
(155352, 'esES', 'Siempre quise un barco pirata, $gjefe:jefa;. ¡Le puse el nombre de mi hija, Mala!\n\n¡Y si consigo una nave, le pondré el nombre de mi hijo!', '', 28153),
(155351, 'esES', '¿Cómo se te ocurrió el nombre?', '¿Cómo se te ocurrió el nombre?', 28153),
(155350, 'esES', 'Je, je, je...\n\nDejaremoh esa hihtoria pa otro momento, $gjefe:jefa;.', '', 28153),
(155349, 'esES', '¿Dónde has conseguido este barco?', '¿Dónde has conseguido este barco?', 28153),
(155348, 'esES', 'Garona me envió a buhcar un barco. Así que he conseguido uno.', '', 28153),
(155347, 'esES', '¿Por qué tienes un barco pirata?', '¿Por qué tienes un barco pirata?', 28153),
(155346, 'esES', 'Acaban de llegar nuevoh amigoh, ja, ja. Guerreroh vrykulh, creo.', '', 28153),
(155345, 'esES', 'Eh, alguien se acerca. Parecen asaltanteh vrykulh. Tened cuidado.', '', 28153),
(155344, 'esES', 'Barcoh vrykulh se acercan a la orilla pa saquear la ihla. Quieren nuehtro alijo.', '', 28153),
(155343, 'esES', 'Oye, $gjefe:jefa;, ¿$glihto:lihta; pa un pequeño motín?', '', 28153),
(155342, 'esES', 'Hay algunah chalupah en el horizonte. Tienen que ser vrykulh que vienen a por lah gemah.', '', 28153),
(155341, 'esES', 'Una fuerza sobrenatural noh ehtá enviando a loh muertoh. Tened cuidado.', '', 28153),
(155340, 'esES', 'Loh ehpírituh me dicen que loh muertoh se acercan. Y quieren la azerita.', '', 28153),
(155339, 'esES', 'Puaj, qué hedor. Seguro que son no-muertoh que han venido a por nuehtro alijo. Atentoh.', '', 28153),
(155338, 'esES', 'Ehta ohcuridad no eh natural, algo ha venido a por la azerita. Algo malvado.', '', 28153),
(155337, 'esES', 'Parece que la azerita también ha atraído a unoh visitanteh un tanto ehtrañoh. Parecen algún tipo de secta.', '', 28153),
(155336, 'esES', 'Vaya, ni siquiera he vihto llegar a ehtoh tipoh. Atención, ¡tenemoh compañía!', '', 28153),
(155335, 'esES', '¿Quiéneh son ehtoh? Parece que ehtán recogiendo azerita. Será mejor que se lo impidáih.', '', 28153),
(155334, 'esES', 'Parece que tenemoh compañía. Nunca loh había vihto anteh. Vendrán a por la azerita.', '', 28153),
(155333, 'esES', 'Dragoneh mogu en la cohta, ehtarán aquí en cualquier momento.', '', 28153),
(155332, 'esES', 'Loh mogu acaban de aparecer, con intencioneh de quedarse nuehtro tesoro. Dadleh una cálida bienvenida, ja.', '', 28153),
(155331, 'esES', 'Uno de loh mogu viene a por nuehtra azerita. ¡Abrid bien loh ojoh! Puede que vengan máh.', '', 28153),
(155330, 'esES', 'He avihtado dragoneh nimbo viniendo hacia aquí. Loh mogu llegarán pronto.', '', 28153),
(155329, 'esES', 'Una tormenta sombría... Ehto solo puede significar una cosa: ignotoh.', '', 28153),
(155328, 'esES', 'Oye, ¿también oíh susurroh? Tiene que ser un dioh antiguo que noh ehtá enviando a suh tropah. Tened cuidado.', '', 28153),
(155327, 'esES', 'Han venido unoh colegah con cara de tentáculo en buhca de azerita. Voy a... bajar.', '', 28153),
(155326, 'esES', 'La azerita ha llamado la atención de loh ignotoh. Acaba de aparecer un grupo por aquí.', '', 28153),
(155325, 'esES', '¡Pájaro malo! Nada de sangre.', '¡Pájaro malo! Nada de sangre.', 28153),
(155324, 'esES', '¡Largo!', '¡Largo!', 28153),
(155323, 'esES', '', 'Los bosques de Valarroyo vuelven a ser seguros.', 28153),
(155322, 'esES', '', '¡Los animales han caído bajo la influencia de las brujas y ahora cazan a nuestros cazadores! ¡Salva a mi gente y acaba con esas bestias!', 28153),
(155321, 'esES', '', 'Es como si fueras mi alivio cómico, $p.', 28153),
(155320, 'esES', '', 'Me resultas familiar... ¿Has cumplido condena en Tol Dagor?', 28153),
(155319, 'esES', '', 'Bien hecho. La fauna de las colinas ya no será un peligro para las aldeas cercanas.', 28153),
(155318, 'esES', '', '¡La maldición de las brujas ha esclavizado a la fauna de estas colinas! ¡Acaba con esta situación antes de que lleguen al pueblo!', 28153),
(155317, 'esES', '¡Empieza a ser difícil respirar!', '¡Empieza a ser difícil respirar!', 28153),
(155312, 'esES', 'Les llevará tiempo recuperarse de este ataque. ¡Por la Dama Oscura!', '', 28153),
(155311, 'esES', 'Los ejércitos de nuestra Jefa de Guerra han tomado posiciones en la academia militar. ¡Ayúdalos!', '', 28153),
(155310, 'esES', '', '¡Entrené con algunos de ellos! ¡La Horda pagará por el daño que ha hecho!', 28153),
(155309, 'esES', '', 'Un destacamento de élites de la Horda ha llegado hasta la Academia Valiente. ¡A los soldados les vendría bien tu ayuda para defenderla!', 28153),
(155308, 'esES', '', 'Alberque del Ocaso está a salvo, pero no podemos bajar la guardia.', 28153),
(155307, 'esES', '', 'La magia de las brujas azota Albergue del Ocaso una vez más. ¡Rompe su maldición antes de que sea tarde!', 28153),
(155306, 'esES', '', 'Ja... ¡El poder de las piedras... pertenecerá a... Canto Tormenta!', 28153),
(155305, 'esES', '', 'Esta piedra es un obsequio de las profundidades. ¡No la tendrás!', 28153),
(155304, 'esES', 'El día que la flor se marchitó, supe que ehtaba solo, así que enseguida buhqué un trabajo en loh muelleh. La flor me impidió convertirme en vagabundo como muchoh otroh.', 'El día que la flor se marchitó, supe que ehtaba solo, así que enseguida buhqué un trabajo en loh muelleh. La flor me impidió convertirme en vagabundo como muchoh otroh.', 28153),
(155303, 'esES', 'Da igual si se trata de jabaespines o de invasores de la Horda, la gente de este valle se mantiene firme.', '', 28153),
(155302, 'esES', 'No coger... piedras de trogg...', '', 28153),
(155301, 'esES', 'Mis piedras...', '', 28153),
(155300, 'esES', 'Aplastar... vosotros...', '', 28153),
(155299, 'esES', 'Trogg... roto...', '', 28153),
(155298, 'esES', 'Trogg destrozar...', '', 28153),
(155297, 'esES', 'Trogg... matar...', '', 28153),
(155296, 'esES', '¡Aaargh!', '', 28153),
(155295, 'esES', 'Gurrum...', '', 28153),
(155294, 'esES', '¡Este ser territorio trogg! ¡Vosotros marchar!', '', 28153),
(155293, 'esES', '¡Aaaah! ¡Trogg matar!', '', 28153),
(155292, 'esES', '¡Romper en pedazos!', '', 28153),
(155291, 'esES', '', 'Me he ocupado de que las cosas funcionen bien por todo Kul Tiras. ¿En qué puedo ayudarte?', 28153),
(155290, 'esES', '¡Piedras brillantes ser de trogg! ¡Largo!', '', 28153),
(155289, 'esES', '¡Aaaargh! ¡Destruir!', '', 28153),
(155288, 'esES', '¡Trogg romper cara!', '', 28153),
(155287, 'esES', '¡Trogg hundir cráneo!', '', 28153),
(155286, 'esES', '¡Este ser territorio trogg!', '', 28153),
(155285, 'esES', '¡Troggzor!', '', 28153),
(155284, 'esES', '¡Piedras mías! ¡No vuestras!', '', 28153),
(155283, 'esES', '¡Mi tesoro! ¡Mío!', '', 28153),
(155282, 'esES', '¡Rarrragh!', '', 28153),
(155281, 'esES', '¡Aaaaaraaagh!', '', 28153),
(155280, 'esES', '¡Machacar! ¡Romper! ¡MATAR!', '', 28153),
(155279, 'esES', '¡Trogg aplastar!', '', 28153),
(155278, 'esES', '¡Trogg no ser tonto!', '', 28153),
(155277, 'esES', '¡Oye! ¿Vihte lo que la Princesa le hizo a la Alianza? Mira loh rehtoh a tu izquierda. ¡Ese era el verdadero poder de un loa!', '', 28153),
(155276, 'esES', 'Loh nagah se fueron durante un tiempo. Se habló de una reconhtrucción, pero Gral ehtaba desaparecido o demasiado débil pa ayudar, así que todo quedó en palabrah.', '', 28153),
(155275, 'esES', 'Todoh suh seguidoreh fueron asesinadoh. ¡Gral ehtaba furioso! Todo el que ehtaba cerca del agua esa noche pudo sentir su dolor... mientrah caían uno a uno.', '', 28153),
(155274, 'esES', '¡Jo, jo! ¡Fue como si me quitaran un peso de encima! ¡Sabíamos que esa bruja con pelo de serpiente estaba muerta!', '', 28153),
(155273, 'esES', 'Que tengas un magnífico día.', '', 28153),
(155272, 'esES', 'Ten cuidado. Estas tierras ya no son seguras.', '', 28153),
(155271, 'esES', 'Canto Tormenta está plagado de tesoros.', '', 28153),
(155270, 'esES', 'El valle te da la bienvenida.', '', 28153),
(155269, 'esES', '¡Saludos!', '', 28153),
(155268, 'esES', 'Brennadam es mi hogar, y lo protegeré siempre.', '', 28153),
(155267, 'esES', '', 'Soy una mujer de palabra. Tu Horda y tú sois bienvenidos en mi puerto.', 28153),
(155266, 'esES', 'Sí, colega $gcapitán:capitana;. Noh unimoh a tu causa. Y ehperamoh que tú también te unah a la nuehtra.', '', 28153),
(155265, 'esES', '', 'Libertad... Bueno, parece que te mantienes fiel a tu palabra.', 28153),
(155264, 'esES', '¿Por qué habéis... venido...?', '', 28153),
(155263, 'esES', 'Solo habéis destruido una espina... La parra perdura...', '', 28153),
(155262, 'esES', '¡Grah!', '', 28153),
(155261, 'esES', 'No... Las gemas...', '', 28153),
(155260, 'esES', 'No podéis matarnos... a todos...', '', 28153),
(155259, 'esES', 'Me marchito...', '', 28153),
(155258, 'esES', 'Rotas...', '', 28153),
(155257, 'esES', 'Espinas... rotas...', '', 28153),
(155256, 'esES', '¡Las gemas brillantes de este lugar son nuestras, $ginvasor:invasora;!', '', 28153),
(155255, 'esES', '¡Las piedras fortalecen nuestras espinas!', '', 28153),
(155254, 'esES', '¡Reclamamos esta tierra y su poder!', '', 28153),
(155253, 'esES', 'Vuestra carne no es nada frente a nuestras lanzas de espinas.', '', 28153),
(155252, 'esES', '¡Colgaré vuestra carne en mi choza!', '', 28153),
(155251, 'esES', 'Hemos elegido bien.', '', 28153),
(155250, 'esES', '¡Nuestras parras reclamarán esta isla y vuestra carne!', '', 28153),
(155249, 'esES', 'Rompeespinas, los de vuestra calaña no pintáis nada aquí.', '', 28153),
(155248, 'esES', '¡Esbirros, defendedme!', '', 28153),
(155247, 'esES', '¡Dales un poco de su propia medicina!', '', 28153),
(155246, 'esES', '¡No podéis detener las parras salvajes!', '', 28153),
(155245, 'esES', 'Vuestra sangre alimentará las espinas.', '', 28153),
(155244, 'esES', '¡Pelotas fuera!', '', 28153),
(155243, 'esES', '¡A destrozar!', '', 28153),
(155242, 'esES', 'Te marchitarás, enemigo de las espinas.', '', 28153),
(155241, 'esES', '¡Este lugar es nuestro!', '', 28153),
(155240, 'esES', 'No habríamos servido de nada sentados en una jaula.', '', 28153),
(155239, 'esES', '¡Perforad su carne!', '', 28153),
(155238, 'esES', '¡Cornead a los intrusos!', '', 28153),
(155237, 'esES', '', 'Se avecinan aguas turbulentas.', 28153),
(155236, 'esES', '¡Invasores!', '', 28153),
(155235, 'esES', '¡Muere, rompeespinas!', '', 28153),
(155234, 'esES', '', 'Que las mareas te guíen.', 28153),
(155233, 'esES', 'Las reliquias están protegidas. Gral aún no está perdido.', '', 28153),
(155232, 'esES', 'Sangre y truenos, $gamigo mío:amiga mía;.', '', 28153),
(155231, 'esES', 'Además, he encontrado este abalorio tan interesante.', '', 28153),
(155230, 'esES', 'Parece que no deberíamos habernos apresurado tanto al abandonar la avanzada.', '', 28153),
(155229, 'esES', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s te marca con una mecha encendida, ¡no te acerques a las barricas de munición!', 28153),
(155228, 'esES', 'Dihfruta de tu último día de vida, Razgaji. La próxima vez que noh veamoh... ¡será la última!', '', 28153),
(155227, 'esES', 'El viaje nos trajo hasta aquí. Los descubrimientos que hemos realizado son otra pieza de este puzle.', '', 28153),
(155226, 'esES', '', 'Ten cuidado ahí fuera.', 28153),
(155225, 'esES', '', 'Soy la alcaldesa. ¿En qué puedo ayudarte?', 28153),
(155224, 'esES', '', 'Debo proteger a los habitantes de Canto Tormenta.', 28153),
(155223, 'esES', '', '¿Vienes a echar una mano?', 28153),
(155222, 'esES', '¡Por la Horda!', '', 28153),
(155221, 'esES', '¡Mira cómo se retuerce en la red! ¡Voy a disfrutar sacándole las tripas!', '¡Mira cómo se retuerce en la red! ¡Voy a disfrutar sacándole las tripas!', 28153),
(155220, 'esES', '¡Ja! ¡He atrapado otro!', '¡Ja! ¡He atrapado otro!', 28153),
(155219, 'esES', 'Sí, colega. ¡Tengo algunah hihtoriah que contar!', '', 28153),
(155218, 'esES', '', 'Bueno, Ty\'jin. Si vamos a trabajar juntos, tienes que contarme más cosas de la Horda.', 28153),
(155217, 'esES', 'Toda la azerita... será... nuestra...', '', 28153),
(155216, 'esES', '¡Esta azerita es propiedad de la Compañía Gobernalle!', '', 28153),
(155215, 'esES', '', 'El enemigo se dispone a atacar. ¡Acaba con él!', 28153),
(155214, 'esES', '', 'Gracias a ti, nuestros soldados tienen un respiro.', 28153),
(155213, 'esES', '', '¡Las brujas retroceden! ¡Bien hecho!', 28153),
(155212, 'esES', '', 'El aquelarre ataca esta zona. ¡Acaba con él!', 28153),
(155211, 'esES', '', 'Nos has dado un respiro. Te lo agradezco.', 28153),
(155210, 'esES', '', 'Los habitantes de Drustvar sufren los ataques del aquelarre. ¡Expulsa a las brujas de aquí!', 28153),
(155209, 'esES', '', 'En nombre de mi gente, agradezco tu ayuda.', 28153),
(155208, 'esES', '', 'Mi gente necesita ayuda. ¡Por favor! ¡Préstales tu fuerza!', 28153),
(155207, 'esES', '¡No! Dejaremoh que se salga con la suya. Noh iremoh por ahora... ¡pero cuando volvamoh no seremoh tan generosoh!', '', 28153),
(155206, 'esES', '¡Puedo con $gel:la; $r, jefe! ¡Sin problema!', '¡Puedo con $gel:la; $r, jefe! ¡Sin problema!', 28153),
(155205, 'esES', 'No voy a volver contigo. ¿De verdad creeh que tuh pobreh matoneh podrán con mi $gamigo:amiga;? No empieceh una pelea que no puedeh ganar.', '', 28153),
(155204, 'esES', '¿Cómo que renunciah? ¡Yo decidiré cuándo renunciah! ¡Ya sabeh lo que leh pasa a loh desertoreh!', '', 28153),
(155203, 'esES', 'Renuncio, Mojambo. Ehtoy cansado de matar y robar pa sobrevivir. Ahora seguiré mi propio camino...', '', 28153),
(155202, 'esES', 'Je, je, je...', 'Je, je, je...', 28153),
(155201, 'esES', 'No te ehtaríah ehcondiendo de tuh viejoh amigoh, ¿verdad?', '', 28153),
(155200, 'esES', '¡Vaya, si eh Razgaji! Te dije que lo encontraríamoh aquí...', '', 28153),
(155199, 'esES', 'No bajeh la guardia. No podemoh confiar en Mojambo...', '', 28153),
(155198, 'esES', 'Estoy listo. Vamos.', 'Estoy lista. Vamos.', 28153),
(155197, 'esES', 'Que el mar bendiga estos lingotes y nunca intente recuperarlos.', 'Que el mar bendiga estos lingotes y nunca intente recuperarlos.', 28153),
(155196, 'esES', '', 'Con la ayuda del poder de nuestro maestro, ¡resurgiremos!', 28153),
(155195, 'esES', '¿Podrías bendecir estos lingotes de plata de tormenta?', '¿Podrías bendecir estos lingotes de plata de tormenta?', 28153),
(155194, 'esES', 'Buena travesía, $r.', 'Buena travesía, $r.', 28153),
(155193, 'esES', '', '¡Todos se inclinarán ante la reina Azshara!', 28153),
(155192, 'esES', '', '¡Te arderán los ojos mientras te consume su voluntad!', 28153),
(155191, 'esES', 'Sacar el arpón.', 'Sacar el arpón.', 28153),
(155190, 'esES', '<La criatura te dedica una débil mirada un momento antes de volverse hacia el arpón que tiene clavado en el costado>.', '<La criatura te dedica una débil mirada un momento antes de volverse hacia el arpón que tiene clavado en el costado>.', 28153),
(155189, 'esES', '¿Adónde vas?', '', 28153),
(155188, 'esES', '¡Muga magudu! ¡Machacarlos!', '', 28153),
(155187, 'esES', '¡Ugafa! ¡Dar donde duele!', '', 28153),
(155186, 'esES', '¡Ooooh, gente mala! ¡Fuera de aquí!', '', 28153),
(155185, 'esES', '¿Quién poder ser?', '', 28153),
(155184, 'esES', '¡Gwaahr! Estas rocas... ¡mis rocas!', '', 28153),
(155183, 'esES', '¡Uaaaah! ¡No llevaros tesoro!', '', 28153),
(155182, 'esES', '¿Gwaaah? ¿Quién ser este?', '', 28153),
(155181, 'esES', '¡Bwaaguugh! ¡Dar de comer a los peces!', '', 28153),
(155180, 'esES', '¿Agu...?', '', 28153),
(155179, 'esES', '¡Hurg!', '', 28153),
(155178, 'esES', 'Gafu... mogo...', '', 28153),
(155177, 'esES', 'Ug...', '', 28153),
(155176, 'esES', '¡¿Mug?!', '', 28153),
(155175, 'esES', 'Matufa...', '', 28153),
(155174, 'esES', '¡Gurk!', '', 28153),
(155173, 'esES', '¡A buu, buu, buu!', '', 28153),
(155172, 'esES', '¡¿Urga Magu?!', '', 28153),
(155171, 'esES', '¡Griip!', '', 28153),
(155170, 'esES', '¡Buga buga!', '', 28153),
(155169, 'esES', '¡Augh!', '', 28153),
(155168, 'esES', '¡Oka magodo!', '', 28153),
(155167, 'esES', '¿Bokum?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'esES', '¡Buga mabugu!', '', 28153),
(155165, 'esES', '¡Ah gah mah gahma!', '', 28153),
(155164, 'esES', 'Su corazón se debilita... No puedo hacer nada más por él, aparte de poner fin a su sufrimiento.', '', 28153),
(155163, 'esES', '¡Gobernalle ha puesto precio a vuestras cabezas!', '¡Gobernalle ha puesto precio a vuestras cabezas!', 28153),
(155162, 'esES', '¡Me llevaré un trofeo de tu cadáver!', '¡Me llevaré un trofeo de tu cadáver!', 28153),
(155161, 'esES', '¡No podéis derrotar a Gobernalle!', '¡No podéis derrotar a Gobernalle!', 28153),
(155160, 'esES', '¡La ciudad es nuestra!', '¡La ciudad es nuestra!', 28153),
(155159, 'esES', '¡Boralus arderá!', '¡Boralus arderá!', 28153),
(155158, 'esES', '¡Nos pondremos al día cuando estemos en un lugar más seguro!', '¡Nos pondremos al día cuando estemos en un lugar más seguro!', 28153),
(155157, 'esES', 'Necesito un ferri que me lleve a Drustvar.', 'Necesito un ferri que me lleve a Drustvar.', 28153),
(155156, 'esES', '¿Por qué... habéis venido...?', '', 28153),
(155155, 'esES', 'Piedras brillantes... mías...', '', 28153),
(155154, 'esES', '¡Mi vela!', '', 28153),
(155153, 'esES', '¡Ay! ¡Ay! ¡Ay!', '', 28153),
(155152, 'esES', '¡Grah!', '', 28153),
(155151, 'esES', 'Vela... apagar...', '', 28153),
(155150, 'esES', '¡Aaaaaaaaaaaaaaaaaaah!', '', 28153),
(155149, 'esES', '¡No!', '', 28153),
(155148, 'esES', '¡Quemar como una vela enorme!', '', 28153),
(155147, 'esES', '¡Ahora velas ser mías!', '', 28153),
(155146, 'esES', '¡Machacar! ¡Coger vuestras cosas!', '', 28153),
(155145, 'esES', '¡Hacer túnel en vuestro cráneo!', '', 28153),
(155144, 'esES', '¡No coger mis piedras brillantes!', '', 28153),
(155143, 'esES', '¡Mi isla! ¡Yo rey!', '', 28153),
(155142, 'esES', '¡Piedras brillantes ser mías! ¡Mías!', '', 28153),
(155141, 'esES', '¡Nosotros encontrar este lugar, no vosotros!', '', 28153),
(155140, 'esES', '¡Este espacio mío!', '', 28153),
(155139, 'esES', '¡Mordedlos! ¡Coged sus velas!', '', 28153),
(155138, 'esES', '¡Argh! ¡Invasores!', '', 28153),
(155135, 'esES', '¡No llevarte vela!', '', 28153),
(155134, 'esES', '¡Bishibosh!', '', 28153),
(155133, 'esES', '¡Piedras brillantes nuestras!', '', 28153),
(155132, 'esES', '¡Piedras brillantes hacer que las velas brillen!', '', 28153),
(155131, 'esES', 'Suerte, continental. Si tienes algún dios, más vale que te acompañe en este lugar.', 'Suerte, continental. Si tienes algún dios, más vale que te acompañe en este lugar.', 28153),
(155130, 'esES', 'Pues ya está, hasta aquí puedo llevarte.', 'Pues ya está, hasta aquí puedo llevarte.', 28153),
(155129, 'esES', 'La última vez que intenté echar el ancla allí, un lobo estuvo a punto de arrancarme la pierna...', 'La última vez que intenté echar el ancla allí, un lobo estuvo a punto de arrancarme la pierna...', 28153),
(155128, 'esES', 'Nos detendremos un poco más adelante; el Puerto del Tallador no es precisamente acogedor últimamente.', 'Nos detendremos un poco más adelante; el Puerto del Tallador no es precisamente acogedor últimamente.', 28153),
(155127, 'esES', 'Te aconsejo que te ocupes de tus asuntos tan aprisa como puedas.', 'Te aconsejo que te ocupes de tus asuntos tan aprisa como puedas.', 28153),
(155126, 'esES', 'En Kul Tiras la gente es muy supersticiosa, no como yo, pero debo admitir que últimamente hay algo en Drustvar que me pone los pelos de punta.', 'En Kul Tiras la gente es muy supersticiosa, no como yo, pero debo admitir que últimamente hay algo en Drustvar que me pone los pelos de punta.', 28153),
(155125, 'esES', 'Pero, últimamente, las minas parecen haberse agotado, y no se ve a ningún carnicero.', 'Pero, últimamente, las minas parecen haberse agotado, y no se ve a ningún carnicero.', 28153),
(155124, 'esES', 'No hace mucho, los comerciantes frecuentaban este ferri para comprar mercancías a granjeros y mineros de allí. ', 'No hace mucho, los comerciantes frecuentaban este ferri para comprar mercancías a granjeros y mineros de allí. ', 28153),
(155123, 'esES', 'La mayoría de los barqueros ya no atracan allí por culpa de todos esos rumores oscuros.', 'La mayoría de los barqueros ya no atracan allí por culpa de todos esos rumores oscuros.', 28153),
(155122, 'esES', 'Te diriges a Drustvar, ¿eh? Tienes suerte de que capitanee este barco.', 'Te diriges a Drustvar, ¿eh? Tienes suerte de que capitanee este barco.', 28153),
(155121, 'esES', '¡Uuh aah! ¡Aaaah!', '', 28153),
(155120, 'esES', 'Argh...', '', 28153),
(155119, 'esES', 'Hace... kraku...', '', 28153),
(155118, 'esES', '¡Ay! ¡Justo en el ruko!', '', 28153),
(155117, 'esES', '¡Ah!', '', 28153),
(155116, 'esES', 'Makakus... malvados...', '', 28153),
(155115, 'esES', 'Dingues... mikos...', '', 28153),
(155114, 'esES', '¡No, mis cosas brillantes!', '', 28153),
(155113, 'esES', 'La diversidad de la fauna y la flora de Zandalar requiere investigación y catalogación.', 'La diversidad de la fauna y la flora de Zandalar requiere investigación y catalogación.', 28153),
(155112, 'esES', '¿De dónde salen estos mikos?', '', 28153),
(155111, 'esES', '¡Yo os hace graku donde más duele!', '', 28153),
(155110, 'esES', '¡Jeringadlos y dadles kaka!', '', 28153),
(155109, 'esES', '¡Un trabajo espléndido! Estaremos elaborando poderosas pociones en nada.', '', 28153),
(155108, 'esES', 'Lo siento, colega. No tengo tiempo para trabajos nuevos. Tengo la agenda completa... Oye, ¿tienes monedas? Olvida lo que he dicho, ¿en qué te puedo ayudar?', 'Lo siento, colega. No tengo tiempo para trabajos nuevos. Tengo la agenda completa... Oye, ¿tienes monedas? Olvida lo que he dicho, ¿en qué te puedo ayudar?', 28153),
(155107, 'esES', '¡Nuestras tropas necesitan más suministros alquímicos! Recoge componentes por esta zona. ¡Ah! Y ten cuidado con los osos.', '', 28153),
(155106, 'esES', '', '¡Las brujas atacan Médano del Halcón! Purga cualquier rastro de su magia vil y devuelve la ciudad a la normalidad!', 28153),
(155105, 'esES', '', 'Has expulsado a las brujas y los habitantes de Médano del Halcón vuelven a estar a salvo. Te estamos muy agradecidos.', 28153),
(155104, 'esES', '$gBienvenido:Bienvenida;, todo lo que hay aquí está recién saqueado de los nativos. ¡Prueba algo nuevo y exótico hoy!', '$gBienvenido:Bienvenida;, todo lo que hay aquí está recién saqueado de los nativos. ¡Prueba algo nuevo y exótico hoy!', 28153),
(155103, 'esES', '¡Fu-uh-uh-era, cosas brillantes mías!', '', 28153),
(155102, 'esES', '¡Makakus jurungos, esta isla mía!', '', 28153),
(155101, 'esES', '¡Yo os pisotea, mikos!', '', 28153),
(155100, 'esES', '¡Desatornillarle la sesera!', '¡La vas a palmar!', 28153),
(155099, 'esES', 'Vas a sufrir un accidente laboral.', '¡Se acabó la seguridad laboral!', 28153),
(155098, 'esES', 'Sé reconocer a un fracasado cuando lo veo.', 'Pillad una llave inglesa, hay que arreglar un problemilla.', 28153),
(155097, 'esES', 'Morimos... por las armas...', '', 28153),
(155096, 'esES', 'Nos derrotas... pero no ganas...', '', 28153),
(155095, 'esES', 'Que las esporas te lleven...', '', 28153),
(155094, 'esES', 'Persistimos... más allá de la muerte...', '', 28153),
(155093, 'esES', 'Abandonamos este cuerpo...', '', 28153),
(155092, 'esES', 'Al menos... morimos... con honor...', '', 28153),
(155091, 'esES', 'Y así caemos...', '', 28153),
(155090, 'esES', 'Crecemos... para volver... a luchar...', '', 28153),
(155089, 'esES', '¡Por las esporas!', '', 28153),
(155088, 'esES', '¡Nuestra voluntad es una!', '', 28153),
(155087, 'esES', '¡Eh! Aquí existen ciertas normas, ¡y tú las estás rompiendo todas!', '¡Eh, tú! ¡Te voy a despedir!', 28153),
(155086, 'esES', '¡Cobarde! ¡Hemos ganado!', '', 28153),
(155085, 'esES', '¡Siente el aguijón de nuestras armas!', '', 28153),
(155084, 'esES', '¡Nuestra voluntad nos protege!', '', 28153),
(155083, 'esES', '¡Ya puedes dar esta batalla por perdida!', '', 28153),
(155082, 'esES', '¡Te falta práctica!', '', 28153),
(155081, 'esES', '¡Te vamos a abrir en canal!', '', 28153),
(155080, 'esES', '¡Por favor, salva Boralus!', '¡Por favor, salva Boralus!', 28153),
(155079, 'esES', '¡Esos piratas están destrozando Boralus!', '¡Esos piratas están destrozando Boralus!', 28153),
(155078, 'esES', '¡Gracias!', '¡Gracias!', 28153),
(155077, 'esES', '¡Machaca a los makakus hasta los rukos!', '', 28153),
(155076, 'esES', '!Aquí yo es el rey, makakus!', '', 28153),
(155075, 'esES', '¡Mátenlos! ¡Cojan sus rukos!', '', 28153),
(155074, 'esES', '¡Makakus intrusos!', '', 28153),
(155073, 'esES', '¡Mata a makakus!', '', 28153),
(155072, 'esES', '¡Cosas brillantes nos hacen más fuertes!', '', 28153),
(155071, 'esES', '¡Isla es nuestra! ¡No vuestra!', '', 28153),
(155070, 'esES', '¡Kraku para vosotros!', '', 28153),
(155069, 'esES', '¡No cogen nuestras cosas brillantes!', '', 28153),
(155068, 'esES', '¡Makakus no pueden estar aquí!', '', 28153),
(155067, 'esES', 'Hace añoh enseñé a Zalazane y Vol\'jin a dominar suh arteh. Nunca imaginé que suh dehtinoh provocarían tal terremoto en el mundo.', '', 28153),
(155066, 'esES', '¡Solo hacía mi trabajo!', '¡Solo hacía mi trabajo!', 28153),
(155065, 'esES', '¡Debería haber trabajado para ti!', '¡Debería haber trabajado para ti!', 28153),
(155064, 'esES', '', '¿Mmsí? ¿Puedo ayudarte en algo?', 28153),
(155063, 'esES', 'Voy a echar de menos... la cerveza.', 'Voy a echar de menos... la cerveza.', 28153),
(155062, 'esES', '¡Sabía que este trabajo era lo peor!', '¡Sabía que este trabajo era lo peor!', 28153),
(155061, 'esES', 'Me uno a loh ehpírituh...', 'Me uno a loh ehpírituh...', 28153),
(155060, 'esES', 'Voy a dehcansar un momento...', 'Voy a dehcansar un momento...', 28153),
(155059, 'esES', 'Yo... chivarme.', '', 28153),
(155058, 'esES', 'Otra vez tú dejarme ganar, ¡jo!', '', 28153),
(155057, 'esES', '¡Ja! ¡Yo ganar! Ah, no...', '', 28153),
(155056, 'esES', 'No... Yo no perder...', '', 28153),
(155055, 'esES', 'Tú problema. Yo arreglar problemas.', '', 28153),
(155054, 'esES', 'Yo ingeniero térmico. Yo listo. ¡Yo hacer fuego!', '', 28153),
(155053, 'esES', 'Tú sentarte en petróleo... ¡Yo darte cerilla!', 'Tú sentarte en petróleo... ¡Yo darte cerilla!', 28153),
(155052, 'esES', 'A mí no gustar fuego. ¡Tú parar fuego!', 'A mí no gustar fuego. ¡A mí no gustar tú!', 28153),
(155051, 'esES', 'Te voy a cocinar al punto.', 'Te voy a cocinar al punto.', 28153),
(155050, 'esES', 'Te arrepentiráh de montar grehca.', 'Te arrepentiráh de montar grehca.', 28153),
(155049, 'esES', 'El que juega conmigo se acaba quemando.', 'El que juega conmigo se acaba quemando.', 28153),
(155048, 'esES', 'Te convertiré en cenizah.', 'Te convertiré en cenizah.', 28153),
(155047, 'esES', '¿Alguien quería algo de calor?', '¿Alguien quería algo de calor?', 28153),
(155046, 'esES', 'De vuelta a las profundidades de las que salió.', '', 28153),
(155045, 'esES', '¡La bestia ha regresado! ¡Rápido, dale caza antes de que cause más daños al muro!', '', 28153),
(155044, 'esES', '¿Qué? Vol\'jin... no pudihte volverte tan fuerte sin convertirte en...', '', 28153),
(155043, 'esES', '¿Creéih que dehtruyendo mi cuerpo... evitaréih que... oh dehtripe?', '', 28153),
(155042, 'esES', '¿Creéih que podéih ganar? Solo ehtáih retrasando lo inevitable.', '', 28153),
(155041, 'esES', 'He aprendido mucho viendo cómo Bwonsamdi torturaba mi alma. Deja que te muehtre el poder de su vudú.', '', 28153),
(155040, 'esES', 'No puedeh ehconderlo de mí eternamente. ¡Me vengaré de Vol\'jin y de loh Lanza Negra! ', '', 28153),
(155039, 'esES', '¡Ehbirroh! Acabad con su adalid y traedme lah cenizah de Vol\'jin. ¡Ahora!', '', 28153),
(155038, 'esES', '¿Cómo eh posible que podáih ehconder a Vol\'jin de mí? ¿Dónde ehtá?', '', 28153),
(155037, 'esES', '¿Dónde lo ehcondéih, Lanza Negra? ¿Dónde ehtá mi viejo amigo?', '', 28153),
(155036, 'esES', 'Masacrad a loh Lanza Negra y traedme lah cenizah.', '', 28153),
(155035, 'esES', 'Adelante, ehbirroh. Encontrad lah cenizah de Vol\'jin y traédmelah.', '', 28153),
(155034, 'esES', 'Esos bichos asquerosos se comen lo que sea. Es repugnante.', '', 28153),
(155033, 'esES', '¡Los ranishus empiezan a agruparse! Acaba con ellos antes de que se conviertan en un problema aún mayor.', '', 28153),
(155032, 'esES', 'Por supuesto. Que el viento te sea favorable.', 'Por supuesto. Que el viento te sea favorable.', 28153),
(155031, 'esES', 'Conseguiste enviarme en la dirección correcta. ¿Estarás bien?', 'Conseguiste enviarme en la dirección correcta. ¿Estarás bien?', 28153),
(155030, 'esES', 'Siento que no podamos ayudar más.', 'Siento que mi hermano y yo no podamos ayudar más.', 28153),
(155029, 'esES', '', '¡Bien hecho! Eh un lujo tenerte de nuehtro lado.', 28153),
(155028, 'esES', '', 'Hay un nido de arañah tejearena cerca de la arena. Necesito que dehpejeh el camino.', 28153),
(155027, 'esES', 'Parece que las armas son de origen gnómico. En cualquier caso, deberían servirnos en la batalla.', '', 28153),
(155026, 'esES', 'Nuestros marinos han encontrado unas armas algo... interesantes. Podrían sernos útiles si averiguamos cómo usarlas. Pruébalas con la fauna de por aquí.', '', 28153),
(155025, 'esES', '', 'A la Compañía Gobernalle le llevará semanah volver a reunir tanta mercancía. ¡Bien hecho!', 28153),
(155024, 'esES', '', 'La Compañía Gobernalle dirige una operación minera ilegal cerca de aquí. Necesito que la detengah.', 28153),
(155023, 'esES', '¡Un centenar de memos metidos en una isla llena de armas! ¡Vender entradas para ver el espectáculo desde zepelines!', '¡Un centenar de memos metidos en una isla llena de armas! ¡Vender entradas para ver el espectáculo desde zepelines!', 28153),
(155022, 'esES', 'Ponemos un impuesto a los robots. ¡Y luego fabricamos robots recaudadores de impuestos! ¡Dinero infinito!', 'Ponemos un impuesto a los robots. ¡Y luego fabricamos robots recaudadores de impuestos! ¡Dinero infinito!', 28153),
(155021, 'esES', '¡Una bombilla negra! Hace lo contrario que una bombilla normal.', '¡Una bombilla negra! Hace lo contrario que una bombilla normal.', 28153),
(155020, 'esES', '¡Sombreritos formales para que los sombreros informales los lleven en eventos formales!', '¡Sombreritos formales para que los sombreros informales los lleven en eventos formales!', 28153),
(155019, 'esES', '¡Flótems, tótems para cuando vayas en barco!', '¡Flótems, tótems para cuando vayas en barco!', 28153),
(155018, 'esES', '¡Botas con pistolas! Espera... eso ya lo hicimos. ¡CALCETINES con pistolas!', '¡Botas con pistolas! Espera... eso ya lo hicimos. ¡CALCETINES con pistolas!', 28153),
(155017, 'esES', '¡Cohetes reciclables!', '¡Cohetes reciclables!', 28153),
(155016, 'esES', '¡Un equipo de trineo bomba formado solo por goblins!', '¡Un equipo de trineo bomba formado solo por goblins!', 28153),
(155015, 'esES', 'Queso para uso armamentístico.', 'Queso para uso armamentístico.', 28153),
(155014, 'esES', '¡Gujas de guerra duales con sierras mecánicas! ¡Para vendérselas a los Illidari!', '¡Gujas de guerra duales con sierras mecánicas! ¡Para vendérselas a los Illidari!', 28153),
(155013, 'esES', 'El Sueño del peridoto, ¡para cuando quieres una siesta mucho más corta!', 'El Sueño del peridoto, ¡para cuando quieres una siesta mucho más corta!', 28153),
(155012, 'esES', '¡Pinzas de barbacoa tácticas!', '¡Pinzas de barbacoa tácticas!', 28153),
(155011, 'esES', 'Una historia de amor... sobre una humana y, mmm... ¡un jinyu!', 'Una historia de amor... sobre una humana y, mmm... ¡un jinyu!', 28153),
(155010, 'esES', '¡Bien hecho! Es un lujo tenerte de nuestro lado.', '', 28153),
(155009, 'esES', 'Un pilar, no para sostener el techo, ¡sino para contener el suelo!', 'Un pilar, no para sostener el techo, ¡sino para contener el suelo!', 28153),
(155008, 'esES', 'Cerca de aquí, hay un nido de arañas tejearena que bloquea el paso al cañón. Necesito que despejes el camino.', '', 28153),
(155007, 'esES', '¿Una bola 8 mágica de azerita? ¿Azeritará o se equivocará?', '¿Una bola 8 mágica de azerita? ¿Azeritará o se equivocará?', 28153),
(155006, 'esES', '¡Briquetas de carbón de Teldrassil! ¡Dan un delicioso sabor ahumado!', '¡Briquetas de carbón de Teldrassil! ¡Dan un delicioso sabor ahumado!', 28153),
(155005, 'esES', '¡Coches que se mueven por el agua en vez de la tierra!', '¡Coches que se mueven por el agua en vez de la tierra!', 28153),
(155004, 'esES', '¡Bardos!', '¡Bardos!', 28153),
(155003, 'esES', '¡Un silbato que trae a los maestros de vuelo a donde estés!', '¡Un silbato que trae a los maestros de vuelo a donde estés!', 28153),
(155002, 'esES', '¡Buen trabajo, soldado! ¡Una monstruosidad menos en esta trampa mortal que es Vol\'dun!', '', 28153),
(155001, 'esES', '¡Un cristal arcano que te mejora en todos los aspectos! Puede que sea un poco inestable, ¡pero no pasa nada!', '¡Un cristal arcano que te mejora en todos los aspectos! Puede que sea un poco inestable, ¡pero no pasa nada!', 28153),
(155000, 'esES', 'Un ranishu gigante está sembrando el terror en el barranco, pero es demasiado feroz para atacarlo de frente. ¡Tendrás que encontrar otra forma de detenerlo!', '', 28153),
(154999, 'esES', '¡Escopetas de papel higiénico! ¡Piensa en todo el tiempo que te ahorrarías!', '¡Escopetas de papel higiénico! ¡Piensa en todo el tiempo que te ahorrarías!', 28153),
(154998, 'esES', '¡Barcos litera! Ahorraremos mucho espacio en el océano para más actividades. ¡Me pido la de arriba!', '¡Barcos litera! Ahorraremos mucho espacio en el océano para más actividades. ¡Me pido la de arriba!', 28153),
(154997, 'esES', '¡Chicle reutilizable! ¡Compártelo con tus amigos, tus mascotas o, incluso, con desconocidos!', '¡Chicle reutilizable! ¡Compártelo con tus amigos, tus mascotas o, incluso, con desconocidos!', 28153),
(154996, 'esES', 'Era un trabajo sucio, ¡pero alguien tenía que hacerlo! ¡Mejor tú que yo, soldado!', '', 28153),
(154995, 'esES', 'Tenemos que encontrar la forma de cultivar este desierto si queremos sobrevivir. Necesitaremos fertilizante. Mira a ver qué encuentras.', '', 28153),
(154994, 'esES', 'Tengo que admitir que no me lo esperaba, pero esto va a ser muy útil contra los infieles.', '', 28153),
(154993, 'esES', 'Tacha ha desenterrado otro tótem Zandalari en una de las ruinas. Ve a ver qué puede hacer.', '', 28153),
(154992, 'esES', '¡Parece divertido! ¡Este me lo guardo para usarlo contra los orcos!', '', 28153),
(154991, 'esES', 'A la Compañía Gobernalle le llevará semanas volver a reunir tanta mercancía. ¡Bien hecho!', '', 28153),
(154990, 'esES', 'Nuestros exploradores han encontrado este tótem Zandalari antiguo en una de las ruinas. Veamos qué hace.', '', 28153),
(154989, 'esES', 'La Compañía Gobernalle dirige una operación minera ilegal cerca de aquí. Necesito que la detengas.', '', 28153),
(154988, 'esES', 'Las arenas se extienden, pero la vida se abre camino. Gracias a ti.', '', 28153),
(154987, 'esES', 'Los oasis de Vol\'dun son un recurso muy preciado. Debemos cuidarlos lo mejor posible.', '', 28153),
(154986, 'esES', 'No todas las victorias surgen de una batalla gloriosa. Los suministros nos mantendrán con vida.', '', 28153),
(154985, 'esES', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg.', '', 28153),
(154984, 'esES', 'Este oasis nos proporcionará una ventaja táctica significativa para expandirnos por el continente.', '', 28153),
(154983, 'esES', 'Mi derrota es solo un latido en el corazón del abismo infinito.', '', 28153),
(154982, 'esES', 'Tengo que admitir que ha salido mejor de lo que pensaba.', '', 28153),
(154981, 'esES', 'Nuestros peculiares aliados del Puerto de Zem\'lan han ideado un plan. Ayúdalos, si es que confías en ellos.', '', 28153),
(154980, 'esES', '¡Ja! ¡Así aprenderán a no meterse con la Alianza!', '', 28153),
(154979, 'esES', 'Algunas de nuestras tropas han robado un barco y lo han llenado de armas. ¡Vamos a por esos no-muertos!', '', 28153),
(154978, 'esES', '¡Bien hecho! Esos malditos diablos se lo pensarán mejor antes de volver a atacar a la Alianza.', '', 28153),
(154977, 'esES', 'Unos sucios piratas no-muertos han capturado a algunos de nuestros soldados. Liberadlos. ¡Que no quede nadie atrás!', '', 28153),
(154976, 'esES', '', 'Graciah. Hahta loh exiliadoh se merecen un dehtino mejor que ese.', 28153),
(154975, 'esES', '', 'Loh piratah de Zem\'lan han apresado a exiliadoh Zandalari. ¡Libéraloh!', 28153),
(154974, 'esES', 'Los infieles están distraídos. ¡Debemos iniciar el bombardeo!', '', 28153),
(154973, 'esES', 'Volverán a alzarse, pero, por ahora, disfrutaremos de un periodo de paz.', '', 28153),
(154972, 'esES', 'Los ejércitos de los infieles son infinitos. Debemos contenerlos aquí.', '', 28153),
(154971, 'esES', '¡Gloria a Sethraliss! Que todos los sethrak la recuerden por siempre...', '', 28153),
(154970, 'esES', 'Toma una parte de mi poder y purga a los infieles de estas tierras.', '', 28153),
(154969, 'esES', '', 'Mi fuerza... ¿Qué me hah hecho?', 28153),
(154968, 'esES', '', 'Tanto poder... No me puedo... mover...', 28153),
(154967, 'esES', 'La vida... me abandona...', '', 28153),
(154966, 'esES', 'No me puedo mover... Ayuda...', '', 28153),
(154965, 'esES', 'Ugh...', '', 28153),
(154964, 'esES', '¿En serio pensahteih que podríaih enfrentaroh a un dioh y sobrevivir? ¡Morid!', '', 28153),
(154963, 'esES', '¡Máh sangre! ¡Debo saciar ehta sed!', '', 28153),
(154962, 'esES', '¡Vuehtra sangre me da poder!', '', 28153),
(154961, 'esES', '¡El trabajo es un asco, se acabó! ¡Voy a entrenar, llegaré a ser alguien!', '¡El trabajo es un asco, se acabó! ¡Voy a entrenar, llegaré a ser alguien!', 28153),
(154960, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t ¡Azerokk se prepara para lanzar |cFFFF0000|Hspell:258622|h[Pulso resonante]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t ¡Azerokk se prepara para lanzar |cFFFF0000|Hspell:258622|h[Pulso resonante]|h|r!', 28153),
(154959, 'esES', 'Lo único que conseguirás con este grifo es perder una mano, colega.', 'Lo único que conseguirás con este grifo es perder una mano, colega.', 28153),
(154956, 'esES', 'Las sombras avanzan. Los elegidos se reúnen. Llega nuestro momento.', '', 28153),
(154955, 'esES', 'Yo le daré sentido a tu carne.', '', 28153),
(154954, 'esES', '', 'Mi poder... Mi maldición... No puede ser...', 28153),
(154953, 'esES', 'Si es que regresas...', '', 28153),
(154952, 'esES', 'Cuando regrese, hablaremos de honor... y de cómo recuperarlo.', '', 28153),
(154951, 'esES', 'Llevadlo a las Mazmorras.', '', 28153),
(154950, 'esES', 'Solo existís para alimentarme.', '', 28153),
(154949, 'esES', 'Hoy sí lo tiene.', '', 28153),
(154948, 'esES', '¡Un Rey de la Alianza no tiene derecho a decidirlo!', '', 28153),
(154947, 'esES', 'Pero no hay nada de honorable en lo que pides.', '', 28153),
(154946, 'esES', 'Mi padre decía que Varok Colmillosauro encarnaba el sentido del honor de la Horda...', '', 28153),
(154945, 'esES', '¡No! ¡Exijo una muerte honorable!', '', 28153),
(154944, 'esES', '¡Alianza! ¡Deteneos!', '', 28153),
(154940, 'esES', '', '¡Qué tenacidad! ¡Deberíaisss essstar contentosss de haber vivido lo sssuficiente como para enfrentarosss a mi mayor orgullo!', 28153),
(154939, 'esES', 'Soldados, ¡disparad todos a esa monstruosidad! ¡Los nagas no atravesarán hoy la muralla!', '', 28153),
(154937, 'esES', '<Hacer cola para una expedición insular en dificultad mítica con tu grupo>.', '<Hacer cola para una expedición insular en dificultad mítica con tu grupo>.', 28153),
(154936, 'esES', '<Hacer cola para una expedición insular en dificultad heroica con tu grupo>.', '<Hacer cola para una expedición insular en dificultad heroica con tu grupo>.', 28153),
(154935, 'esES', '<Hacer cola para una expedición insular en dificultad mítica>.', '<Hacer cola para una expedición insular en dificultad mítica>.', 28153),
(154934, 'esES', '<Hacer cola para una expedición insular en dificultad heroica>.', '<Hacer cola para una expedición insular en dificultad heroica>.', 28153),
(154933, 'esES', 'Ve, caminante de la manada, y construye una estatua en mi honor en los escalones de Dazar\'alor. Muestra a todos la fuerza de la manada y tendrás mi favor.', '', 28153),
(154932, 'esES', '', 'Con estos tres pergaminos, puedo hacer que viajes aquí sin problemas.', 28153),
(154931, 'esES', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t ¡%s se coloca frente a |cFFFF0000$n|r y prepara un |cFFFF0000|Hspell:268403|h[Tajo de vendaval]|h|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se prepara para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', 28153),
(154930, 'esES', 'Al menos muero... con los dos pies... en el suelo...', '', 28153),
(154929, 'esES', '¡Un lanzamiento excelente! Mereces toda mi atención.', '', 28153),
(154928, 'esES', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t¡Han |cFFFF0000|Hspell:267702|h[Confinado]|h|r a %s! ¡Busca signos de forcejeo!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t¡Han |cFFFF0000|Hspell:267702|h[Confinado]|h|r a %s! ¡Busca signos de forcejeo!', 28153),
(154927, 'esES', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t ¡Te han encerrado en una tumba! ¡|cFFFF0000|Hspell:267764|h[Forcejea]|h|r para que tus compañeros descubran dónde estás!', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t ¡Te han encerrado en una tumba! ¡|cFFFF0000|Hspell:267764|h[Forcejea]|h|r para que tus compañeros descubran dónde estás!', 28153),
(154926, 'esES', '¡Tenemos que volver al Santuario de los Devotos cuanto antes e impedir que el general Jakra\'zet libere a Mythrax!', '', 28153),
(154925, 'esES', '¡Necio! ¡No podéis controlar a Mythrax!', '', 28153),
(154924, 'esES', '¡Despertará a Mythrax y juntos conquistaremos todo Azeroth!', '', 28153),
(154923, 'esES', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t ¡%s se prepara para |cFFFF0000|Hspell:267702|h[Confinar]|h|r a |cFFFF0000$n|r!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t ¡%s se prepara para |cFFFF0000|Hspell:267702|h[Confinar]|h|r a |cFFFF0000$n|r!', 28153),
(154922, 'esES', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se prepara para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se prepara para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', 28153),
(154921, 'esES', '¡Aaah! ¡Ven y responde por tus crímenes, Korthek!', '', 28153),
(154920, 'esES', '', 'Ehtoy aquí pa observar. A loh Zandalari noh interesan mucho loh Renegadoh.', 28153),
(154919, 'esES', '', 'Es todo un honor, Clamañublo...', 28153),
(154918, 'esES', '', 'Intentaré averiguar por qué está cortado el camino. ¡Tú convence a los soldados de que nos dejen pasar!', 28153),
(154917, 'esES', 'Moveos, palurdos. Tenemos cosas más importantes que hacer.', 'Moveos, palurdos. Tenemos cosas más importantes que hacer.', 28153),
(154916, 'esES', 'Piérdete, papanatas.', 'Piérdete, papanatas.', 28153),
(154915, 'esES', 'Fuera de mi vista.', 'Fuera de mi vista.', 28153),
(154914, 'esES', 'Te he dejado ganar.', 'Te he dejado ganar.', 28153),
(154913, 'esES', 'Mejor. Ya me había cansado de verte la cara.', 'Ya me había cansado de verte la cara.', 28153),
(154912, 'esES', '', '¡Te estás obsesionando con los detalles! ¡Todo irá bien!', 28153),
(154911, 'esES', '', '¡Todo tiene un precio y voy a ganar una fortuna con estas sabandijas! Una vez las envíe de vuelta a Kalimdor.', 28153),
(154910, 'esES', '', 'Necesitan sangre pa sobrevivir, ¿cómo leh daráh de comer?', 28153),
(154909, 'esES', '', '¿Por qué coleccionah bichoh en una caja?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'esES', 'Abrid el paso de inmediato.', 'Abrid el paso de inmediato.', 28153),
(154907, 'esES', 'Puedo decir que, con los años, tu ferocidad y tu sabiduría se han acentuado, Rakjan. Castigaremos a estos infieles por cómo te han tratado a ti y a tu especie.', '', 28153),
(154906, 'esES', 'Para entrar tendrás que pasar por encima de mí, colega.', 'Para entrar tendrás que pasar por encima de mí, colega.', 28153),
(154905, 'esES', '¿Estás $gsordo, muchacho:sorda, muchacha;? El valle está cerrado.', '¿Estás $gsordo, muchacho:sorda, muchacha;? El valle está cerrado.', 28153),
(154904, 'esES', 'Máscara de gas y bote de añublo, por favor. Quiero ver lo que puede hacer esta cosa.', 'Máscara de gas y bote de añublo, por favor. Quiero ver lo que puede hacer esta cosa.', 28153),
(154903, 'esES', 'Solo una máscara de gas, por favor.', 'Solo una máscara de gas, por favor.', 28153),
(154902, 'esES', 'Mantente detrás de la línea si no quieres problemas, rata de Pantoque.', 'Mantente detrás de la línea si no quieres problemas, rata de Pantoque.', 28153),
(154901, 'esES', 'No se puede entrar sin papeles. Son las normas.', 'No se puede entrar sin papeles. Son las normas.', 28153),
(154899, 'esES', 'Con el duro caparazón de Ai\'twen, mi estrategia infalible y tu gran determinación, somos invencibles.', '', 28153),
(154898, 'esES', 'Iré a la cima de la montaña y me aseguraré de que Rakjan no me ha olvidado después de todos estos años.', '', 28153),
(154897, 'esES', '', 'Ya descansaré en cuanto dejemos de recibir heridos.', 28153),
(154896, 'esES', '', 'Estoy bien. Estos marineros necesitan de mis habilidades.', 28153),
(154895, 'esES', 'A este paso, vas a ser tú quien necesite un sanador. No podrás ayudarlos desde una camilla.', '', 28153),
(154894, 'esES', 'Pareces agotada, Feorea. Deberías descansar.', '', 28153),
(154893, 'esES', 'Toma mi bastón y cárgalo drenando poder de las agujas de supresión de los infieles.', '', 28153),
(154892, 'esES', 'Ai\'twen y yo te esperaremos en el campo de minas de Ventura y Cía.', '', 28153),
(154891, 'esES', '¡Mamá! ¡Meerah y $p nos han salvado!', '¡Mamá! ¡Meerah y $p nos han salvado!', 28153),
(154890, 'esES', '¡Ya te dije que Meerah no se olvidaría de nosotros! ¡Es la mejor!', '¡Ya te dije que Meerah no se olvidaría de nosotros! ¡Es la mejor!', 28153),
(154889, 'esES', '', '¡Kiro! ¡Me alegra que hayas vuelto! ¿Tuviste miedo ahí fuera? ¿Cómo conseguiste uno de sus croluscos? ¿Le has puesto nombre? ¿Se lo puedo poner yo? ¿Muerde?', 28153),
(154888, 'esES', 'Te lo contaré más tarde, Meerah. Primero debemos poner a salvo a nuestra gente.', '', 28153),
(154887, 'esES', '¡Eso ha sido sorprendentemente... divertido!', '', 28153),
(154886, 'esES', '¡Súbete al crolusco y salgamos de aquí antes de que los infieles envíen refuerzos!', '', 28153),
(154885, 'esES', '', '¿Qué está pasando allí abajo? Alatifón, ¡llévanos hasta allí!', 28153),
(154884, 'esES', '', 'Comenzaremos la búsqueda en Brennadam. Así, espero que al menos encontremos al hermano Pike.', 28153),
(154883, 'esES', '', 'Lord Canto Tormenta gobierna la casa... y el valle entero. Parece que él es la clave de todo este asunto, pero lleva meses sin pisar Boralus.', 28153),
(154882, 'esES', '', 'Primero tenemos que traer a los Canto Tormenta de vuelta al redil. Ellos controlan a los Sabiomar; y estos, a la flota.', 28153),
(154881, 'esES', '', '¡Temblad bajo la sombra del estandarte vulpera, escoria infiel!', 28153),
(154880, 'esES', 'Necesitarás una máscara de gas para sobrevivir al añublo. Si quieres, también puedes coger un bote de añublo y ayudar.', 'Necesitarás una máscara de gas para sobrevivir al añublo. Si quieres, también puedes coger un bote de añublo y ayudar.', 28153),
(154879, 'esES', '', 'Me temo que Kul Tiras no podrá ayudar a la Alianza hasta que la flota esté a salvo.', 28153),
(154878, 'esES', '', 'Y los que están encadenados ahí abajo deberían saber que no los hemos abandonado.', 28153),
(154877, 'esES', '', 'Bien. Deberían saber quién ha venido a matarlos.', 28153),
(154876, 'esES', 'Esto es arriesgado, Nisha. Los infieles sabrán que estamos aquí.', '', 28153),
(154875, 'esES', 'Buen trabajo. Las tropas de ese exánime no dejaban de atacar a nuestros exploradores. Ahora podremos ocuparnos de la Horda.', '', 28153),
(154874, 'esES', 'En Drustvar hay brujas y en Nazmir, exánimes. Ocúpate del ejército enemigo y de lo que sea que le esté dando poder.', '', 28153),
(154873, 'esES', '', '¡Nisha se alegrará de verte! Está en el cráter matando sethrak... Como de costumbre.', 28153),
(154872, 'esES', 'Impresionante, aunque me han dicho que los gnomos se niegan a trabajar con tecnología de origen goblin. Pero al menos sabemos de qué es capaz.', '', 28153),
(154871, 'esES', 'Nuestras tropas han requisado un artilugio experimental de los goblins. Pruébalo contra el ejército de trols de sangre para ver qué es lo que puede hacer.', '', 28153),
(154870, 'esES', 'Tengo la impresión de que este no era el único plan de los nagas. Mantente alerta.', '', 28153),
(154869, 'esES', '¡Nagas! Llevan demasiado tiempo aterrorizando este mundo. Pon fin a sus planes.', '', 28153),
(154866, 'esES', 'No había visto tal ferocidad contra la Horda desde la Tercera Guerra. Bien hecho.', '', 28153),
(154864, 'esES', 'Has luchado bien contra la Horda. La gente de Kul Tiras sabrá de tu valía.', '', 28153),
(154863, 'esES', 'Buen trabajo. Esperemos que esto acabe mejor que la Segunda Guerra.', '', 28153),
(154861, 'esES', '', 'Tienen a los niños ahí debajo, en el cráter. ¡Cuidado, por favor!', 28153),
(154859, 'esES', '¡Buen trabajo! ¡Nada detiene a la Horda!', '', 28153),
(154858, 'esES', 'Han asesinado a varios exploradores que intentaban detener a la Horda cerca de aquí. Solo tú puedes detenerlos.', '', 28153),
(154857, 'esES', '¡Buen trabajo! Creo que podría aprender un par de cosah contigo...', '', 28153),
(154856, 'esES', 'Otro enemigo muerto... Aunque pronto vendrá otro a ocupar su lugar. Pero de momento te hah ganado un dehcanso.', '', 28153),
(154855, 'esES', '', 'Llamaré a Alatifón. Puede posarse en el muelle del este; nos encontraremos allí.', 28153),
(154854, 'esES', 'Ah, ¡victoria dulce! Dulce victoria.', '', 28153),
(154853, 'esES', 'Durante la Tercera Guerra, estudié las tácticas de la Horda. Y parece que están llevando a cabo una muy peligrosa cerca de aquí. Mátalos.', '', 28153),
(154852, 'esES', '¡Ja, ja! No sabía a quién se enfrentaba, ¿eh?', '', 28153),
(154851, 'esES', 'Las operaciones que lleva a cabo la Horda en esta zona me recuerdan a la Segunda Guerra. Tenemos que impedir que triunfen.', '', 28153),
(154850, 'esES', '¡Eso ha sido impresionante!', '', 28153),
(154848, 'esES', 'Noto un alma fuerte en loh alrededoreh. Rápido, ¡acaba con ella!', '', 28153),
(154846, 'esES', 'Hay un enemigo cerca de aquí. ¡Mátalo!', '', 28153),
(154845, 'esES', 'En nombre de la Séptima Legión, te doy las gracias por tu lucha contra la Horda.', '', 28153),
(154843, 'esES', 'La derrota de la Horda permitirá avanzar a la Séptima Legión. ¡Bien hecho!', '', 28153),
(154842, 'esES', 'Tus heroicos actos contra la Horda llegarán a oídos del rey Anduin.', '', 28153),
(154838, 'esES', 'Mis exploradores me informan de que la Horda se está acercando a tu zona. ¡Tendámosles una emboscada y acabemos con ellos!', '', 28153),
(154836, 'esES', 'Hay un gran contingente de la Horda cerca de aquí. ¡Es el momento de atacar!', '', 28153),
(154833, 'esES', 'El objetivo ehtá cerca, ¡a por él!', '', 28153),
(154832, 'esES', 'La Séptima Legión ha descubierto tropas de la Horda en las inmediaciones. ¡Tus órdenes son dispersarlas y frustrar sus planes!', '', 28153),
(154831, 'esES', 'Hay otra amenaza cerca de aquí. Ya sabeh qué hacer.', '', 28153),
(154830, 'esES', 'Loh ehpírituh me hablan de un peligroso enemigo en la zona. Dehtrúyelo anteh de que sea tarde.', '', 28153),
(154829, 'esES', 'Hay una gran amenaza cerca de aquí. ¡Acaba con ella!', '', 28153),
(154828, 'esES', '¡Buen trabajo! ¿Te has planteado unirte de forma permanente a la Séptima Legión? ¡Nos vendría bien alguien como tú!', '', 28153),
(154827, 'esES', 'Un trabajo excelente. ¡Por el rey Anduin! ¡Por la Alianza!', '', 28153),
(154826, 'esES', 'Hoy has prestado un gran servicio a la Séptima Legión y a la Alianza.', '', 28153),
(154825, 'esES', 'Te lo agradecemos, tanto yo como los soldados de la Séptima Legión.', '', 28153),
(154824, 'esES', 'Me aseguraré de que el rey Anduin sepa de tu valentía.', '', 28153),
(154823, 'esES', 'Nuestros exploradores informan de que un enemigo poderoso acecha cerca de tu posición. Acaba con él.', '', 28153),
(154822, 'esES', 'La Séptima Legión ha recibido órdenes de acabar con un objetivo cerca de tu ubicación.', '', 28153),
(154821, 'esES', 'Deberían andarse con más cuidado. No estaremos cerca siempre que se metan en líos. Gracias.', '', 28153),
(154820, 'esES', '¡Los no-muertos han atrapado a un equipo de reconocimiento! ¡Ayúdalos antes de que sea demasiado tarde!', '', 28153),
(154819, 'esES', 'Nosotros nos ocupamos. Hora de acabar con G\'huun.', '', 28153),
(154818, 'esES', 'Puaj... ¿entonces es un cadáver reanimado? Devolvámoslo a la tierra.', '', 28153),
(154817, 'esES', 'Hay algo repugnante en ese trol. ¿A qué se dedica Zul?', '', 28153),
(154816, 'esES', '...', '', 28153),
(154815, 'esES', '...', '', 28153),
(154814, 'esES', '...', '', 28153),
(154813, 'esES', '...', '', 28153),
(154812, 'esES', '...', '', 28153),
(154811, 'esES', '...', '', 28153),
(154810, 'esES', '...', '', 28153),
(154809, 'esES', '...', '', 28153),
(154808, 'esES', '¡Os dejasteis uno!', '', 28153),
(154807, 'esES', '', 'En estas instalaciones se ha experimentado con varias formas de vida en busca de soluciones contra la corrupción de los dioses antiguos.', 28153),
(154806, 'esES', '¡Por mis barbas! ¿Qué es esa cosa?', '', 28153),
(154805, 'esES', '...', '', 28153),
(154804, 'esES', 'Había oído historias sobre el poder de los esbirros de N\'zoth, pero nunca creí que vería uno. La verdad es que espero no ver más.', '', 28153),
(154803, 'esES', 'Nos hemos librado por poco. Si no llegamos a detener a esa cosa, la infección en la superficie habría sido imparable.', '', 28153),
(154802, 'esES', 'Es un buen plan. Ya que estamos, veré qué otros secretos han dejado atrás los titanes.', '', 28153),
(154801, 'esES', '...', '', 28153),
(154800, 'esES', '¡Argh! No creo que tengamos tanto tiempo. Será mejor librarnos de G\'huun antes de que empeore esta corrupción.', '', 28153),
(154799, 'esES', '¿Tenemos alguna respuesta?', '', 28153),
(154798, 'esES', 'Eso explica la presencia de los trols de sangre, pero ¿por qué mantendrían con vida los titanes a un dios antiguo?', '', 28153),
(154797, 'esES', 'Qué alegría veros. Esto tiene toda la pinta de ser una instalación de investigación científica.', '', 28153),
(154796, 'esES', '¡Sí! ¡Ha funcionado! Esta tecnología no es tan confusa cuando le pillas el truco.', '', 28153),
(154795, 'esES', '¡Por duodécima vez!', '', 28153),
(154794, 'esES', '¡¿Cómo?! ¡No! ¡Las malditas puertas están selladas! ¡Empezad a romper cosas hasta que se abran!', '', 28153),
(154793, 'esES', 'Un segundo... Voy a abrir estas puertas.', '', 28153),
(154792, 'esES', '¡Lo habéis logrado! Dadme un segundo. He accedido a una especie de vigilante que parece controlar estas instalaciones.', '', 28153),
(154791, 'esES', 'Acabo de hacer historia.', '', 28153),
(154789, 'esES', 'La batalla es feroz. ¡No dejes de hacer frente a nuestros enemigos!', '', 28153),
(154788, 'esES', 'Han avistado a un objetivo importante cerca. Necesitamos que lo elimines de inmediato.', '', 28153),
(154787, 'esES', 'Hay un enemigo poderoso cerca. Elimínalo. ¡Sin compasión!', '', 28153),
(154780, 'esES', 'Listo para el combate.', 'Lista para el combate.', 28153),
(154779, 'esES', '', '¡Torcanata! ¡Ja, ja!', 28153),
(154777, 'esES', '', '¡Hoy eh la Torcanata! Si quiereh unirte, coge una antorcha y prepárate pa correr.', 28153),
(154774, 'esES', '', 'Parece que te estás ganando la confianza de los Zandalari. Debo atender otros asuntos. Buena suerte.', 28153),
(154772, 'esES', '', 'Oculeth, a ver qué puedes hacer con este sistema de portales. Necesitaremos líneas de suministros a las capitales de la Horda.', 28153),
(154770, 'esES', 'Reúnete conmigo en la Caída de Bwoljin en cuanto puedas. Luego, nos infiltraremos en la fortaleza de Korthek.', '', 28153),
(154769, 'esES', '', 'La princesa Talanji tuvo la amabilidad de informarnos de una antigua red de portales que podríamos aprovechar.', 28153),
(154768, 'esES', '', 'Hablad conmigo cuando estéis listos para acabar con la flota de Gobernalle.', 28153),
(154767, 'esES', '', 'Buen trabajo, héroes, pero Boralus aún no está a salvo.', 28153),
(154766, 'esES', 'Vuelve al trabajo. Son responsabilidad mía.', 'Vuelve al trabajo. Son responsabilidad mía.', 28153),
(154765, 'esES', 'No se permiten intrusos en los archivos, hermano.', 'No se permiten intrusos en los archivos, hermano.', 28153),
(154764, 'esES', 'Estaba allí, en la playa, acosado por esos gilblins hediondos... ¡cuando llegó un héroe! ¡Ah! ¡Hola otra vez, $n!', '', 28153),
(154763, 'esES', '¡Consigue esos pergaminos! Voy a tomar la ruta... pintoresca, volveré al campamento e informaré de lo que has averiguado.', '', 28153),
(154762, 'esES', 'No importa con qué nos ataquen: la Alianza solo conocerá la derrota.', '', 28153),
(154761, 'esES', 'Han llegado campeones de la Alianza para intentar salvar la ciudad. Hay que poner fin a su ofensiva.', '', 28153),
(154760, 'esES', 'Gracias a estas armas sembraremos el caos en la Alianza.', '', 28153),
(154759, 'esES', 'Las tropas de Gobernalle están usando artillería de azerita para atacar la ciudad. ¡Hagámonos con sus armas!', '', 28153),
(154758, 'esES', 'Sin sus oficiales, la gente de Kul Tiras se verá obligada a volver al mar.', '', 28153),
(154757, 'esES', 'Un oficial de Kul Tiras está intentando montar su defensa. ¡Hay que eliminarlo del campo de batalla!', '', 28153),
(154756, 'esES', '', 'Un trabajo excelente. La Horda ahora sabrá que nadie puede conquistar Boralus.', 28153),
(154755, 'esES', '', '¡Parece que la Horda se está aprovechando del caos y está saqueando la ciudad! ¡No permitáis que desvalijen Boralus!', 28153),
(154754, 'esES', '', 'Buen trabajo. Ahora lady Gobernalle sabrá que un matón de alquiler no es rival para vosotros.', 28153),
(154753, 'esES', '', 'Uno de los mercenarios de Gobernalle está sembrando el caos en la ciudad. ¡Detenedlo!', 28153),
(154752, 'esES', '', 'Bien hecho. Los únicos que deberían estar encadenados son estos matones.', 28153),
(154751, 'esES', '', '¡Los piratas están tomando a civiles como esclavos! ¡No lo permitáis!', 28153),
(154750, 'esES', 'Viene... Gorak Tul...', '', 28153),
(154749, 'esES', '¡Todo Kul Tiras sufrirá! ¡Pero empezaré contigo!', '', 28153),
(154748, 'esES', '¡Gusano! ¡Morirás aullando!', '', 28153),
(154747, 'esES', 'Oou ph\'magg an\'qov nuq.', '', 28153),
(154746, 'esES', '¡Ywaq ongg uul\'gwa no AN\'zig!', '', 28153),
(154745, 'esES', '¡Arwi ryiu yrr oou qam!', '', 28153),
(154744, 'esES', 'AN\'zig wgah qam za zyqtahg...', '', 28153),
(154743, 'esES', '¡AN\'zig wgah zzof!', '', 28153),
(154742, 'esES', '¡Ywaq fhssh wgah qam!', '', 28153),
(154741, 'esES', '¡Uulg\'ma zyqtahg yrr!', '', 28153),
(154740, 'esES', '¡Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz!', '', 28153),
(154739, 'esES', 'Ahora largo, antes de que sea tarde. Seguro que los otros se han dado cuenta de que pasa algo.', 'Ahora largo, antes de que sea tarde. Seguro que los otros se han dado cuenta de que pasa algo.', 28153),
(154738, 'esES', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Machaque perforante]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Machaque perforante]|h|r!', 28153),
(154737, 'esES', '¡Og qam shfk wgah iiqaah halahs ma!', '', 28153),
(154736, 'esES', 'Buscad al hermano Pike en Brennadam y dadle este colgante. Aún estamos empezando, así que le hará falta vuestra ayuda.', 'Buscad al hermano Pike en Brennadam y dadle este colgante. Aún estamos empezando, así que le hará falta vuestra ayuda.', 28153),
(154735, 'esES', '¡Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma!', '', 28153),
(154734, 'esES', 'Nuestra gente sigue un camino tenebroso, pero somos varios los que nos rebelamos.', 'Nuestra gente sigue un camino tenebroso, pero somos varios los que nos rebelamos.', 28153),
(154733, 'esES', '¡Zuq ag\'xig ka\'kar za wgah!', '', 28153),
(154732, 'esES', '¡Puul qi\'plahf ni oou bormax!', '', 28153),
(154731, 'esES', '¡Xith wgah!', '', 28153),
(154729, 'esES', '¡Naz raqul!', '', 28153),
(154728, 'esES', '¡I wgah far\'al zuq ni shn!', '', 28153),
(154727, 'esES', 'La flota no se ha perdido: está prisionera en una tormenta artificial.', 'La flota no se ha perdido: está prisionera en una tormenta artificial.', 28153),
(154726, 'esES', '¡Zuq wgah qam n\'lyeth!', '', 28153),
(154725, 'esES', '¡Zuq ag\'xig gag wgah naggwa\'fssh!', '', 28153),
(154724, 'esES', '¡Zuq ag\'xig bormax oou iiqaath!', '', 28153),
(154723, 'esES', '¿Estáis bien? Debería haber sabido que la sombra que cubre la casa Canto Tormenta afectaría también a Wade.', '¿Estás bien? Debería haber sabido que la sombra que cubre la casa Canto Tormenta afectaría también a Wade.', 28153),
(154722, 'esES', '', '¿A qué te refieres con peligro?', 28153),
(154721, 'esES', 'Sí, hermano.', 'Sí, hermano.', 28153),
(154720, 'esES', 'Que no entre nadie. Tengo compañía.', 'Que no entre nadie. Tengo compañía.', 28153),
(154719, 'esES', 'No tenéis ni idea del peligro que corréis aquí.', '', 28153),
(154718, 'esES', 'Por aquí. Mirada al suelo.', '', 28153),
(154717, 'esES', 'Nuestras fortificaciones aún son vulnerables. Rápido, ¡impedid que la Horda siga avanzando!', '', 28153),
(154716, 'esES', 'Stromgarde aún es vulnerable, no resistirá un ataque directo. ¡Destruid a la vanguardia de la Horda antes de que se acerque!', '', 28153),
(154715, 'esES', '¡Ja! ¡Una buena muehtra de rehpeto hacia Pa\'ku!', '', 28153),
(154714, 'esES', '¡Enviad a nuehtrah tropah! ¡Hay que acabar con la Alianza anteh de que se dehplieguen!', '', 28153),
(154713, 'esES', '', '¡Eh la hora! Sube lah ehcalerah de Zanchul y muehtra tuh rehpetoh a nuehtro loa. Con su favor, ¡Zandalar resihtirá! ¡Haz que Gonk ehté orgulloso de ti!', 28153),
(154712, 'esES', '', '¡Enviad a nuestras tropas! ¡No podemos permitir que la Alianza se asiente! ', 28153),
(154711, 'esES', '¡Preparad las armas! ¡A luchar!', '', 28153),
(154710, 'esES', '¡Enviad a nuestras tropas! ¡Las murallas de Stromgarde se derrumbarán ante la fuerza de la Horda!', '', 28153),
(154709, 'esES', 'Hay que reforzar el bahtión. Rechazad a suh tropah, ¡no dejéih que se acerquen demasiado!', '', 28153),
(154708, 'esES', 'Rápido. ¡Lord Canto Tormenta necesita esos mapas en el Altar de la Tormenta de inmediato!', '', 28153),
(154707, 'esES', '¡Enviad a nuestras tropas! Reduciremos su ridícula base a cenizas.', '', 28153),
(154706, 'esES', '', 'Las bibliotecas de los Sabiomar son de las más completas del mundo. Seguro que allí encontramos a nuestro archivista.', 28153),
(154705, 'esES', '', '¡La Alianza se dirige a Ar\'gorok! ¡Debemos acabar con ellos antes de que lleguen al bastión!', 28153),
(154704, 'esES', '¡Soldados de la Alianza! ¡Acabad con ellos!', '', 28153),
(154703, 'esES', 'Soldados de la Liga, ¡a la carga!', '', 28153),
(154702, 'esES', 'Horda, ¡haced que esos perros se arrepientan de haber salido de su castillo! ¡Que no derriben las puertas!', '', 28153),
(154701, 'esES', '', '¡Balas con efecto! ¡Efectooo!', 28153),
(154700, 'esES', '¡Balas con efecto! ¡Efectooo!', '', 28153),
(154699, 'esES', '', 'No me gusta cómo pinta esto. Vámonos.', 28153),
(154698, 'esES', '¡Regresad con ese mentecato de Alen si no queréis que os use para estabilizar la falla!', '', 28153),
(154697, 'esES', '¡Idiotas! ¡Redoblad los esfuerzos o perderemos el control!', '', 28153),
(154696, 'esES', '', '¡Pues puede que hagamos eso!', 28153),
(154695, 'esES', '', 'Si habéis venido a perder el tiempo, ¿por qué no vais a molestar a Alen?', 28153),
(154694, 'esES', '', 'Abrid vuestros corazones a las mareas. ¡Sus susurros revelan la verdad!', 28153),
(154693, 'esES', 'Plantando semillas', 'Plantando semillas', 28153),
(154692, 'esES', '', 'Gilneanos, ¡cargad los cañones! ¡Al ataque!', 28153),
(154691, 'esES', 'Damas y caballeros, ¡motores en marcha! ¡Atacad!', '', 28153),
(154690, 'esES', 'Fusileros, ¡preparaos! ¡Vamos allá!', 'Fusileros, ¡preparaos! ¡Vamos allá!', 28153),
(154689, 'esES', '', 'Podemos garantizar la seguridad del barco por un módico precio.', 28153),
(154688, 'esES', '', 'Cuánta tragedia. Quizás deberíamos dejar de celebrar bodas por aquí.', 28153),
(154687, 'esES', '', '¡Una celebración que se supone que va a ser alegre y se echa a perder! ¡Acabad con los monstruos responsables y salvad a los invitados!', 28153),
(154686, 'esES', '', 'Deduzco que eso es un no...', 28153),
(154685, 'esES', '', 'Sois tan insufribles como el hermano Alen.', 28153),
(154684, 'esES', '', 'Tú, ¿quién está al mando aquí?', 28153),
(154683, 'esES', 'Mmm.', 'Mmm.', 28153),
(154682, 'esES', '¡Drenad vuestras heridas purulentas y agonizad!', '', 28153),
(154681, 'esES', 'No huyáis de la locura. ¡Devoradla!', '', 28153),
(154680, 'esES', '¡Contemplad la belleza de la descomposición!', '', 28153),
(154679, 'esES', '¡Te reduciré a cenizas!', '', 28153),
(154678, 'esES', '¡Xalzaix ansía aniquilación!', '', 28153),
(154677, 'esES', '¡No sobrevivirás!', '', 28153),
(154676, 'esES', '¡No podéis eludir la destrucción!', '', 28153),
(154675, 'esES', '¡Nadie escapa de las sombras!', '', 28153),
(154674, 'esES', '¡Exterminio!', '', 28153),
(154673, 'esES', '¡Desintegración!', '', 28153),
(154672, 'esES', 'Nadie se resiste a mi llamada.', '', 28153),
(154671, 'esES', '¡Entrégate a la peste!', '', 28153),
(154670, 'esES', 'Nada detendrá a G\'huun...', '', 28153),
(154669, 'esES', 'La podredumbre lo consume todo.', '', 28153),
(154668, 'esES', 'Tus restos pertenecen a G\'huun.', '', 28153),
(154667, 'esES', '¡Más alimento para la putrefacción!', '', 28153),
(154666, 'esES', '¡G\'huun se alzará!', '', 28153),
(154665, 'esES', '¡Vuestro mundo sucumbirá!', '', 28153),
(154664, 'esES', 'Vuestro declive es inevitable.', '', 28153),
(154663, 'esES', 'El cosquilleo en la garganta. La comezón en el cerebro. Siempre he estado ahí.', '', 28153),
(154662, 'esES', 'Toda la vida se marchita. Acéptalo y transfórmate.', '', 28153),
(154661, 'esES', '', 'Impulso de recreación restaurado. Acceso a la cámara permitido.', 28153),
(154660, 'esES', '', 'Consola activada. Reiniciando salvaguardas de la instalación.', 28153),
(154659, 'esES', '¡Ah! Una cosa más. Bueno, dos.', '', 28153),
(154658, 'esES', '', 'Primera consola activada. Restableciendo matriz de energía.', 28153),
(154657, 'esES', '', 'Sujeto G\'huun eliminado. No quedan muestras viables.', 28153),
(154656, 'esES', '', 'La corrupción desciende a niveles seguros. Integridad del sistema restaurada.', 28153),
(154655, 'esES', 'Al final, cuando el planeta explote como una gran olla, mi podredumbre se expandirá por el cosmos.', '', 28153),
(154654, 'esES', 'Propagaréis mi pestilencia y un gran quiste pútrido efervescente cubrirá el mundo.', '', 28153),
(154653, 'esES', 'Qué buenos anfitriones. Seréis los primeros en recibir mi don.', '', 28153),
(154652, 'esES', 'Los sellos, rotos. Los titanes, desaparecidos. Es la era de la corrupción.', '', 28153),
(154651, 'esES', '', '¡Eso eh por desatar el caoh en Dazar\'alor, dehpreciable criatura!', 28153),
(154650, 'esES', '', 'El rehto noh toca a nosotroh. Acabemoh con la infección de G\'huun.', 28153),
(154649, 'esES', '', 'Alerta, amenaza de contaminación significativa tras este punto. Los protocolos de cuarentena me impiden continuar.', 28153),
(154648, 'esES', '¡Perfecto! Tenemos minas de sobra para asestar un buen golpe a Ventura y Cía.', '', 28153),
(154647, 'esES', '', 'Da igual cómo haya regresado; mi cuchillo lo devolverá al abihmo.', 28153),
(154646, 'esES', 'Hay muchas minas para elegir.', '', 28153),
(154645, 'esES', '', 'El análisis indica niveles altos de corrupción. Hipótesis: G\'huun ha reanimado y mejorado a este espécimen. Se requieren más pruebas.', 28153),
(154644, 'esES', '', '¡¿Zul?! ¿Cómo sigue con vida? ¡Lo vi morir a manoh de mi padre!', 28153),
(154643, 'esES', '¡Estas minas no pueden detectar tortugas! Podemos recolectarlas de forma segura.', '', 28153),
(154642, 'esES', '', 'Parece que oh dejahteih uno.', 28153),
(154641, 'esES', '', 'Se analizó la capacidad de la corrupción de G\'huun para reanimar tejido expirado. Los resultados no fueron concluyentes y los especímenes se destruyeron.', 28153),
(154640, 'esES', '', 'Observación correcta. Se ha experimentado con los loa en busca de soluciones contra la corrupción de los dioses antiguos.', 28153),
(154639, 'esES', '', '¿Qué eh ehta criatura? Parece haber sido un loa en otro tiempo...', 28153),
(154638, 'esES', '', 'Si eso era un ehbirro de G\'huun, tenemoh que detenerlo anteh de que un ejército entero llegue a la superficie.', 28153),
(154637, 'esES', '', 'Error. Fallo del disco. Transmisión de datos corruptos iniciada.', 28153),
(154636, 'esES', '', 'Secuencia de arranque iniciada.', 28153),
(154635, 'esES', '', 'Presentaos en la plataforma médica para la extracción neuronal y la recogida de tejido cerebral.', 28153),
(154634, 'esES', '', 'El análisis de vuestros córtex indica que todos los individuos presentes han interactuado con especímenes de dioses antiguos.', 28153),
(154633, 'esES', '', 'Cualquier dato disponible sobre experiencias anteriores puede ayudar a la investigación.', 28153),
(154632, 'esES', '', 'El análisis de vuestros córtex indica que ciertos individuos han interactuado con especímenes de dioses antiguos.', 28153),
(154631, 'esES', '', 'Y novecientos cincuenta mil millones de norgabytes con listas de música y selfies.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'esES', '', 'Setenta y cinco norgabytes con todos los compuestos químicos existentes.', 28153),
(154629, 'esES', '', 'Estos discos contienen cincuenta norgabytes con datos biológicos sobre formas de vida conocidas en el cosmos.', 28153),
(154628, 'esES', '', 'Accediendo a la cámara de datos. Es una recopilación exhaustiva de conocimientos titánicos.', 28153),
(154627, 'esES', 'Te enfrentas a algo inevitable. Nada podrá detener a la peste. Ya emponzoña tu interior.', '', 28153),
(154626, 'esES', '', 'Si no llegamoh a detener a esa cosa, habría infectado toda la vida en la superficie.', 28153),
(154625, 'esES', 'Ah, $gbienvenido:bienvenida;. Los visitantes escasean últimamente, sobre todo en los archivos.\n\n¿En qué puedo ayudarte?', 'Ah, $gbienvenido:bienvenida;. Los visitantes escasean últimamente, sobre todo en los archivos.\n\n¿En qué puedo ayudarte?', 28153),
(154624, 'esES', '', 'Alerta. Contención vírica comprometida. Se aproxima un espécimen contaminado. Riesgo de infección inminente.', 28153),
(154623, 'esES', '', 'Este laboratorio contiene miles de las cepas víricas más peligrosas del cosmos conocido, por orden alfabético para facilitar el acceso.', 28153),
(154622, 'esES', '', 'Accediendo al ala de ecología vírica.', 28153),
(154621, 'esES', '', 'Mantén Palabra de poder: escudo activa siempre para beneficiarte de Expiación.', 28153),
(154620, 'esES', 'Mantén Palabra de poder: escudo activa siempre para beneficiarte de Expiación.', '', 28153),
(154619, 'esES', '', 'Lánzate Palabra de poder: escudo y luego inflige daño al muñeco-diana para sanar tus heridas.', 28153),
(154618, 'esES', 'Lánzate Palabra de poder: escudo y luego inflige daño al muñeco-diana para sanar tus heridas.', '', 28153),
(154617, 'esES', '', 'Cuando infliges daño a un enemigo, todos los objetivos afectados por tu Expiación se curan.', 28153),
(154616, 'esES', 'Cuando infliges daño a un enemigo, todos los objetivos afectados por tu Expiación se curan.', '', 28153),
(154615, 'esES', '', 'Algunos hechizos, como Palabra de poder: escudo, aplican Expiación a tu objetivo.', 28153),
(154614, 'esES', '¿Sabes algo de la flota desaparecida?', '¿Sabes algo de la flota desaparecida?', 28153),
(154613, 'esES', 'Algunos hechizos, como Palabra de poder: escudo, aplican Expiación a tu objetivo.', '', 28153),
(154612, 'esES', 'Necesito que me ayudes a convencer a la Jefa de Guerra. Vamos.', '', 28153),
(154611, 'esES', 'Puede que sea el momento de cobrar una antigua deuda. Así, reclutaríamos a unos cuantos soldados leales para la Horda.', '', 28153),
(154610, 'esES', 'Adalid, estoy seguro de que amas la Horda tanto como yo, pero si no hacemos algo, no sobrevivirá a esta guerra.', '', 28153),
(154609, 'esES', '', 'Tenemoh un plan. Activemoh lah consolah y acabemoh con la plaga de G\'huun de una vez por todah. ', 28153),
(154608, 'esES', '', 'Activar todas las consolas da acceso a la cámara de G\'huun, donde puede eliminarse el espécimen mediante el impulso de recreación.', 28153),
(154607, 'esES', '', 'Para destruir el espécimen, hay que reactivar las consolas de la cámara ubicadas por toda esta ala.', 28153),
(154606, 'esES', '', '¡No tenemoh tanto tiempo! ¡Debemoh detener a G\'huun de inmediato!', 28153),
(154605, 'esES', '', 'Negativo. Datos no concluyentes. Se están desarrollando pruebas alternativas para su implementación dentro de dos mil trescientos sesenta y cuatro ciclos.', 28153),
(154604, 'esES', '¡Uuh! ¡Vaya potencia!', '', 28153),
(154603, 'esES', '', '¿Y habéih encontrado la rehpuehta?', 28153),
(154602, 'esES', 'Ahora una chispita... Deberías alejarte un poco.', '', 28153),
(154601, 'esES', 'A lo mejor podemos volar el cerrojo... Echa un poco de pólvora encima.', '', 28153),
(154600, 'esES', '', 'La recopilación de datos es vital para combatir a los dioses antiguos. La biología única de G\'huun puede contener la respuesta para eliminar su amenaza.', 28153),
(154599, 'esES', '', '¡¿Habéih mantenido a esa abominación con vida?! ¿Por qué?', 28153),
(154598, 'esES', '', 'Denominación: Uldir. Esta instalación científica se diseñó para contener e investigar a la entidad conocida como G\'huun.', 28153),
(154597, 'esES', '', '¿Qué eh ehte lugar?', 28153),
(154596, 'esES', '', 'Sistemas comprometidos. Se recomienda precaución.', 28153),
(154595, 'esES', '', '¡Ha bloqueado lah puertah! ¡Hay que apagar esa máquina anteh de que noh reduzca a cenizah!', 28153),
(154594, 'esES', '', 'Alerta. Formas de vida contaminadas detectadas. Incineradores activos.', 28153),
(154593, 'esES', '', 'Debe ser la razón por la que la corrupción no ha arrasado por completo ehte lugar.', 28153),
(154592, 'esES', '', 'Soy la Matriarca Alfa de Desinfección del Riego Envenenado. Designación: MADRE.', 28153),
(154591, 'esES', '', '¡Por la Horda!', 28153),
(154590, 'esES', '', '¿Qué ha sido esa voz?', 28153),
(154589, 'esES', '', '¡Por la Horda!', 28153),
(154588, 'esES', '¡Lok\'tar ogar! ¡Por la Horda!', '', 28153),
(154587, 'esES', '', 'Espécimen virulento eliminado. Abriendo cámara de descontaminación.', 28153),
(154586, 'esES', '', 'Acepto tu lealtad, Señora Suprema. Tu pueblo es bienvenido en la ciudad de Orgrimmar.', 28153),
(154585, 'esES', '', 'Draenor cayó, pero Azeroth será nuestro nuevo hogar. ¡Ahora vuestros enemigos son también los nuestros!', 28153),
(154584, 'esES', 'Echando pólvora', 'Echando pólvora', 28153),
(154583, 'esES', '', 'Eitrigg y tu adalid han demostrado su valor y su nobleza. Si representan la esencia de la Horda, entonces nos complace luchar junto a ella.', 28153),
(154582, 'esES', '', '¿¡Taloc sobrevivió al ataque del MEMO!? ¡Impediremoh que esa monhtruosidad se interponga entre nosotroh y G\'huun!', 28153),
(154581, 'esES', 'Bwonsamdi...', 'Tan lejoh de mi hogar...', 28153),
(154580, 'esES', 'Sé que estás disgustada, cielito, pero aquí hay monstruos de verdad. Tenemos que irnos.', 'Sé que estás disgustada, cielito, pero aquí hay monstruos de verdad. Tenemos que irnos.', 28153),
(154578, 'esES', '', '¡El honor lo es todo para nosotros! Este juramento es firme, Jefa de Guerra.', 28153),
(154577, 'esES', 'Ya compraremos otra tarta, será mejor que nos vayamos.', 'Ya compraremos otra tarta, será mejor que nos vayamos.', 28153),
(154576, 'esES', 'Sé que estás enfadada, pero tenemos que irnos, cielito.', 'Sé que estás enfadada, pero tenemos que irnos, cielito.', 28153),
(154575, 'esES', 'Cielito, tenemos que irnos.', 'Cielito, tenemos que irnos.', 28153),
(154574, 'esES', '', 'Eitrigg me ha hablado de la fuerza de tu pueblo. Espero que el honor sea igual de importante para los tuyos.', 28153),
(154572, 'esES', '¡Me has estropeado el vestido! ¡Era el vestido perfecto! ¡Me lo hicieron con seda importada de Quel\'Thalas! ¡Y el velo era de mi madre! ¿Cómo te atreves?', '¡Me has estropeado el vestido! ¡Era el vestido perfecto! ¡Me lo hicieron con seda importada de Quel\'Thalas! ¡Y el velo era de mi madre! ¿Cómo te atreves?', 28153),
(154570, 'esES', 'Hemos tenido éxito, Jefa de Guerra. La señora suprema Geya\'rah ha unido sus tropas a la Horda.', '', 28153),
(154569, 'esES', '¡Has matado al camarero! ¡Y ni siquiera había servido los aperitivos!', '¡Has matado al camarero! ¡Y ni siquiera había servido los aperitivos!', 28153),
(154568, 'esES', 'Lah arenah me engullen.', '¡Por fin! ¡Una muerte digna!', 28153),
(154567, 'esES', '¡Te arrepentirás de haberme estropeado la boda, pedazo de... lo que quiera que seas!', '¡Te arrepentirás de haberme estropeado la boda, pedazo de... lo que quiera que seas!', 28153),
(154566, 'esES', '¿Sabes lo que me ha costado que todo sea perfecto?', '¿Sabes lo que me ha costado que todo sea perfecto?', 28153),
(154565, 'esES', '¿Cómo te atreves a estropearme el día?', '¿Cómo te atreves a estropearme el día?', 28153),
(154564, 'esES', 'Por fin... muero.', 'No puede acabar así.', 28153),
(154563, 'esES', '¡Llevo cuatro meses sin probar el pan!', '¡Llevo cuatro meses sin probar el pan!', 28153),
(154562, 'esES', 'Lah arenah noh reclamarán a todoh.', 'La única ehcapatoria eh la muerte.', 28153),
(154561, 'esES', '¿Tienes la menor idea de lo que ha costado esa tarta?', '¿Tienes la menor idea de lo que ha costado esa tarta?', 28153),
(154560, 'esES', '¡Me pasé dos años en lista de espera para poder celebrar aquí la ceremonia!', '¡Me pasé dos años en lista de espera para poder celebrar aquí la ceremonia! ¡Dos años!', 28153),
(154559, 'esES', 'La muerte no me ha parado hasta ahora...', '', 28153),
(154558, 'esES', '¡Puedo matarte con un solo dedo!', '', 28153),
(154557, 'esES', '', 'Se puede recoger una nueva matriz de poder.', 28153),
(154556, 'esES', '', 'Hay una nueva matriz de poder disponible.', 28153),
(154555, 'esES', '', 'Atención. Hay una nueva matriz de poder disponible.', 28153),
(154554, 'esES', '', 'Atención. Estallido de recreación inminente. Despejad la zona.', 28153),
(154553, 'esES', '', 'Alerta. Secuencia de estallido de recreación iniciada. Despejad la zona.', 28153),
(154551, 'esES', '¡La Horda ha sido derrotada!', '', 28153),
(154550, 'esES', '¡Pronto descubrirás la insensatez de tu resistencia!', '¡Pronto descubrirás la insensatez de tu resistencia!', 28153),
(154549, 'esES', '¡Sal, sométete a tu destino!', '¡Sal, sométete a tu destino!', 28153),
(154548, 'esES', '¡El que acecha en el abismo se hará una capa con tu piel!', '¡El que acecha en el abismo se hará una capa con tu piel!', 28153),
(154547, 'esES', '¡Lucha por tu patética existencia! ¡Tarde o temprano la marea eterna te arrastrará!', '¡Lucha por tu patética existencia! ¡Tarde o temprano la marea eterna te arrastrará!', 28153),
(154546, 'esES', '', 'Usa Penitencia para sanar tus heridas.', 28153),
(154545, 'esES', '¿Pero qué clase de pólvora es esa? Eh, ayúdame a coger un poquito, anda.', '', 28153),
(154544, 'esES', 'Usa Penitencia para sanar tus heridas.', '', 28153),
(154543, 'esES', '', 'Lanzar Penitencia sobre un aliado o sobre ti mismo hará que sane en lugar de infligir daño.', 28153),
(154542, 'esES', 'Lanzar Penitencia sobre ti o un aliado hará que sane en lugar de infligir daño.', '', 28153),
(154541, 'esES', '¡Mata a esos monstruos!', '¡Mata a esos monstruos!', 28153),
(154540, 'esES', '¡Se suponía que iba a ser una ocasión especial!', '¡Se suponía que iba a ser una ocasión especial!', 28153),
(154539, 'esES', '¿Qué ocurre? ¿Qué pasa? ¿Qué son esos monstruos?', '¿Qué ocurre? ¿Qué pasa? ¿Qué son esos monstruos?', 28153),
(154538, 'esES', '¡Esto es mucho peor que un cuñado borracho!', '¡Esto es mucho peor que un cuñado borracho!', 28153),
(154537, 'esES', '¿Por qué está pasando esto?', '¿Por qué está pasando esto?', 28153),
(154536, 'esES', '¡Ni siquiera hemos podido bailar el zancudo funky!', '¡Ni siquiera hemos podido bailar el zancudo funky!', 28153),
(154535, 'esES', '¡Se supone que tiene que ser un día feliz!', '¡Se supone que tiene que ser un día feliz!', 28153),
(154534, 'esES', '¡Aaaaaaaaaaaah!', '¡Aaaaaaaaaaaah!', 28153),
(154533, 'esES', 'Con tu permiso, Jefa de Guerra. Venga, vámonos.', '', 28153),
(154532, 'esES', '', 'Nuestros aliados Nocheterna tienen una habilidad especial para el teletransporte. Te sugiero que hagas uso de ese conocimiento, te ayudará en tus viajes.', 28153),
(154531, 'esES', 'He obtenido un fragmento del artefacto que usó Garrosh para viajar a ese mundo. Creo que puedo volver a abrir el camino... pero necesitaré ayuda.', '', 28153),
(154530, 'esES', '', 'Entiendo el valor de este plan, pero pensaba que la puerta a ese otro Draenor se había cerrado.', 28153),
(154529, 'esES', 'Iré a hablar con Owings. Me gusta mi trabajo y quiero seguir haciéndolo. Con mis propios términos.', '', 28153),
(154528, 'esES', 'Eso significa que... Ya veo.', '', 28153),
(154527, 'esES', 'Mmm... No puedo creerme que el capitán optara por no aliarse con los Gobernalle. Parece muy decidido.', '', 28153),
(154526, 'esES', '', '¿Qué dices, adalid? ¿Podrás reclutar nuevos aliados?', 28153),
(154525, 'esES', '', 'Los orcos Mag\'har son legendarios por su pericia en la batalla. Necesitaré soldados valientes como ellos a nuestro lado.', 28153),
(154524, 'esES', '', '¿Un ejército de soldados orcos de otro mundo? Entrenados... dispuestos a ensartar sus armas en tropas de las Alianza. Interesante...', 28153),
(154523, 'esES', 'Al salvar Draenor de Garrosh y la Legión Ardiente, quien nos acompaña se ganó la confianza de los orcos que allí moraban. Le deben mucho a la Horda. Es hora de que salden su deuda.', '', 28153),
(154522, 'esES', 'Jefa de Guerra, hace años, la Horda persiguió a Garrosh Grito Infernal hasta un eco del Draenor que yo conocía.', '', 28153),
(154521, 'esES', 'Les diremos que no a los Gobernalle. Estas son las órdenes del capitán.', 'Les diremos que no a los Gobernalle. Estas son las órdenes del capitán.', 28153),
(154520, 'esES', 'Tienes una ropa estupenda, $gamigo:amiga;. ¿Necesitas algo?', '', 28153),
(154519, 'esES', 'Empinad el codo, compañeros. Parecéis un poco secos... ¡Ja!', 'Empinad el codo, compañeros. Parecéis un poco secos... ¡Ja!', 28153),
(154518, 'esES', 'Rompiendo', 'Rompiendo', 28153),
(154516, 'esES', 'Tú no eres $gun:una; estudiante. Será mejor que tengas una buena razón para interrumpir mi lección.', 'Tú no eres $gun:una; estudiante. Será mejor que tengas una buena razón para interrumpir mi lección.', 28153),
(154515, 'esES', '<Darrel no parece notar tu presencia>.', '<Darrel no parece notar tu presencia>.', 28153),
(154514, 'esES', 'Interrumpir es de mala educación, $gforastero:forastera;.', 'Interrumpir es de mala educación, $gforastero:forastera;.', 28153),
(154513, 'esES', 'A primera vista, no hay nada aquí que me dé una pista de adónde fueron mis compañeros gnomos. Déjame echar un vistazo a la información que has recabado y volveré a contactar contigo si encuentro algo interesante.', '', 28153),
(154512, 'esES', '|cFF0000FF(Misión)|r Viaja en barco al Valle Canto Tormenta.', '|cFF0000FF(Misión)|r Viaja en barco al Valle Canto Tormenta.', 28153),
(154511, 'esES', '¡Alerta! ¡Alerta! ¡Intrusos! ¡Intrusos!', '', 28153),
(154510, 'esES', '', 'Acepta este obsequio: la armadura tradicional de nuestro pueblo. Llévala con orgullo para recordar nuestra patria. ¡Dranosh\'ek Mag\'har!', 28153),
(154509, 'esES', '', 'Al defender a la Horda contra sus enemigos, has traído honor a los Mag\'har.', 28153),
(154508, 'esES', '', 'Vuelve a Orgrimmar y di a tu gente que reconozco tu dedicación hacia mi pueblo.', 28153),
(154507, 'esES', '', 'Has librado incontables batallas por todo Azeroth. ¡Has mostrado tanto a enemigos como a aliados lo que significa ser un Mag\'har!', 28153),
(154506, 'esES', '', 'No importa dónde nos lleve el camino, no debemos olvidar que el corazón de Draenor late en nuestro interior. ¡Lok\'tar ogar!', 28153),
(154505, 'esES', '', 'Cada victoria mostrará a la gente de Azeroth... ¡que somos maestros de la guerra!', 28153),
(154504, 'esES', '', 'Ahora la Horda nos necesita en su lucha contra la Alianza. Y respondemos a su llamada.', 28153),
(154503, 'esES', '', 'Nuestro pueblo permaneció unido bajo el liderazgo de Grommash Grito Infernal. Se nos conocía como los Mag\'har.', 28153),
(154502, 'esES', '', 'Hace tiempo, los héroes de este mundo viajaron a Draenor y lucharon a nuestro lado contra la Legión Ardiente.', 28153),
(154501, 'esES', '', 'Querido Rokhan, la tribu Lanza Negra se ha ganado de sobra el apoyo de loh Zandalari. Yo también te ayudaré en lo que pueda.', 28153),
(154500, 'esES', 'Necesito a tu adalid un momento. Un viejo enemigo ha logrado ehcapar de Bwonsamdi y amenaza mi hogar.', '', 28153),
(154499, 'esES', 'Estoy preparado. Comienza el ritual.', 'Estoy preparada. Comienza el ritual.', 28153),
(154498, 'esES', '', 'Alguien tiene que saber algo. ¡No se puede perder una flota entera!', 28153),
(154497, 'esES', 'En su lugar... ¿abriremos nuestro puerto a la Horda?', '', 28153),
(154496, 'esES', 'No nos entregaremos a los Gobernalle...', '', 28153),
(154495, 'esES', '¿Y se supone que debo creerte, $r? Dame eso.', '', 28153),
(154494, 'esES', 'Órdenes del capitán, señor. ¡Ha decidido no aliarse con los Gobernalle!', 'Órdenes del capitán, señor. ¡Ha decidido no aliarse con los Gobernalle!', 28153),
(154493, 'esES', '¿De dónde has salido? Está claro que no eres de por aquí.', '', 28153),
(154492, 'esES', '', '¿Qué? Déjame verlo.', 28153),
(154491, 'esES', 'Te traigo nuevas órdenes del capitán, contramaestre.', 'Te traigo nuevas órdenes del capitán, contramaestre.', 28153),
(154490, 'esES', '', 'No solo para que la flota vuelva a casa, sino para que Kul Tiras vuelva a ser lo que era... O para \"curar la infección\", como dice Cyrus.', 28153),
(154489, 'esES', '', '¿Quién eres? ¿Y qué quieres exactamente?', 28153),
(154488, 'esES', '', 'También bendicen todos los barcos de Kul Tiras. Eso es lo que los diferencia de los otros barcos que ves en el puerto.', 28153),
(154487, 'esES', '', 'Nunca había visto tanta azerita junta. Esto me preocupa y me complace a la vez.', 28153),
(154486, 'esES', '', 'Un elemental de azerita pura... Acaba con él, pero no lo destruyas. ¡Hazte con todos los fragmentos que puedas!', 28153),
(154485, 'esES', '', 'Eso debería saciar su apetito... de momento.', 28153),
(154484, 'esES', '', 'Los orcos son unos soldados excelentes, ¡pero cada uno come como doce goblins! Nuestra despensa necesita suministros. ¿Te importa cazar unas pocas bestias mientras diezmas a los kaldorei?', 28153),
(154483, 'esES', '', 'Como siempre digo: \"Corta la rosa antes de que le crezcan espinas\".', 28153),
(154482, 'esES', '', 'Otra Comandante kaldorei en el momento y lugar equivocados. Acaba con ella de inmediato. No podemos permitir que consiga refuerzos.', 28153),
(154481, 'esES', '', 'Has sido justo el arma que necesitábamos, adalid.', 28153),
(154480, 'esES', '', 'Colmillosauro ha coronado las cimas que hay entre Costa Oscura y Frondavil. Reúnete con él en el Valle Rompelanzas y asegúrate de que el camino que busca es seguro.', 28153),
(154479, 'esES', '¡Lo conseguimoh, tripulación! El rey pirata Zem\'lan ehtá muerto por ahora, ¡y el tesoro eh nuehtro!', '', 28153),
(154478, 'esES', '', 'No dudé de ti ni por un momento.', 28153),
(154477, 'esES', '', 'Parece que los kaldorei han reunido refuerzos. Nos lo van a poner difícil, pero solo aceptaré la victoria.', 28153),
(154476, 'esES', '', 'Luchas con pericia y fervor. Tu destreza inspira a todos mis soldados, adalid.', 28153),
(154475, 'esES', '', 'La Alianza está intentando desestabilizar nuestros puestos en Costa Oscura. ¡No cederemos! ¡Defiende nuestra posición!', 28153),
(154474, 'esES', '', 'En tiempos de guerra, matas o mueres. Es muy sencillo.', 28153),
(154473, 'esES', '', '¡No tengas piedad! Estos elfos de la noche no la tendrían contigo.', 28153),
(154472, 'esES', '', 'Hemos asestado un duro golpe a sus tropas. Bien hecho.', 28153),
(154471, 'esES', '', 'Los kaldorei son aún más letales en la oscuridad. ¡Únete a la batalla y acaba con ellos antes de que anochezca!', 28153),
(154470, 'esES', '', 'No me he equivocado al creer en ti. Pronto doblegaremos a todos los kaldorei.', 28153),
(154469, 'esES', '', '¡Nuestro ejército tiene acorralados a los soldados de Malfurion! ¡Debemos avanzar por Costa Oscura mientras tengamos ventaja!', 28153),
(154468, 'esES', '', 'Pobrecilla... No ha tenido ni las más mínima oportunidad.', 28153),
(154467, 'esES', '', 'Esa Comandante elfa de la noche está poniendo a prueba mi paciencia. Mátala.', 28153),
(154466, 'esES', '', 'Dormir durante miles de años solo para despertarse y caer derrotado. ¡Patético!', 28153),
(154465, 'esES', '', 'Así que los ancestros quieren jugar un poco, ¿mm? Hagamos que su despertar sea de todo menos placentero.', 28153),
(154464, 'esES', 'Supongo que podría haber ido peor. Asegúrate de que la Horda no se apropie de los fragmentos.', '', 28153),
(154463, 'esES', '', '¡Un elemental de azerita pura! No sé qué tipo de amenaza supone, adalid... Pero encárgate de él, por favor.', 28153),
(154462, 'esES', 'Los elfos de la noche se resistirán a todos nuestros movimientos.', 'Los elfos de la noche se resistirán a todos nuestros movimientos.', 28153),
(154461, 'esES', '', '¿Has usado alguna vez una bomba de azerita? ¿Quieres ver lo que es el verdadero poder? Prepárate para la explosión... Te va a encantar.', 28153),
(154460, 'esES', '¡Un espécimen magnífico! Se me ocurren varios usos alquímicos para esta criatura.', '', 28153),
(154459, 'esES', 'Los cadetes nuevos siempre se sorprenden con esto. No te preocupes, ¡así se curten!', '', 28153),
(154458, 'esES', '', 'Los kaldorei se resistirán a nuestra ocupación... A menos que acabemos con su moral.\n\nDebemos asestarles un golpe que les demuestre lo que está en juego. Deben perder algo... o a alguien... en quien confíen plenamente y en quien tengan una fe absoluta. Un símbolo de esperanza.\n\n<La Dama Oscura entorna los ojos>.\n\nMalfurion Tempestira debe morir.', 28153),
(154457, 'esES', 'Los pescadores dicen que hay algo grande y extraño en el agua. Nos vendría bien hacernos con una muestra para estudiarla.', '', 28153),
(154456, 'esES', '', 'La Alianza pretende usar armas de asedio contra nosotros. Qué inocentes... Muéstrales de lo que es capaz la Horda.', 28153),
(154455, 'esES', 'Con la escasez de hierro actual, no podemos malgastar ni la munición de entrenamiento. Nuestros marinos han ideado la forma perfecta de recuperarla.', '', 28153),
(154454, 'esES', '', 'Estas ruinas están llenas de recursos naturales... ¡Y serán todos nuestros! No permitas que los kaldorei nos lo impidan.', 28153),
(154453, 'esES', '', 'Contamos con algunos jinetes del viento. Coge nuestros explosivos y siembra el caos en ese muro de fuegos fatuos. Malfurion recibirá el mensaje.', 28153),
(154452, 'esES', '', '¡Así se dispara! Aunque pobre del que tenga que recoger esas balas de cañón...', 28153),
(154451, 'esES', 'Una chamán de Ventura y Cía. se ha hecho con el control de poderosos elementales de azerita. ¡Esos mequetrefes no se merecen tal poder! ¡Acaba con ella!', '', 28153),
(154450, 'esES', '', 'Parece que están haciendo prácticas de tiro en la zona de entrenamiento. Seguro que les puedes enseñar a los cadetes cómo se dispara un cañón.', 28153),
(154449, 'esES', '', 'Esas armas nos vendrán muy bien para nuestra campaña. Has sido muy hábil.', 28153),
(154448, 'esES', '', 'Sea como sea, necesitamos la ayuda de los Sabiomar... Ahora más que nunca.', 28153),
(154447, 'esES', '¡Estupendo! Has vaciado la bolsa de más de un apostador, incluida la mía.', '', 28153),
(154446, 'esES', '', 'Ahora bien, nadie sabe por qué no ha regresado la flota.', 28153),
(154445, 'esES', '', 'Dicen que los Sabiomar han perdido su magia, pero yo creo que compiten por el poder, como los Gobernalle.', 28153),
(154444, 'esES', '', '¡Ese cargamento pertenece a la Horda! No permitas que la Alianza se haga con él.', 28153),
(154443, 'esES', 'Algunos Aguacortada celebran un torneo de duelos piratas aquí de vez en cuando. Y dejan participar a cualquiera.', '', 28153),
(154442, 'esES', '', 'A pesar de su experiencia, las forestales no han acertado con sus ataques. Igual envío a Clamañublo para que hable con ellas...', 28153),
(154441, 'esES', '', 'En los barcos más grandes siempre hay un Sabiomar para navegar por mares agitados y atraer vientos favorables.', 28153),
(154440, 'esES', '', 'Mis forestales oscuras te necesitan. ¡Presta tu ayuda a las que te encuentres!', 28153),
(154439, 'esES', '', 'Se te necesita en otra parte, adalid. Un equipo de goblins se encargará de recoger el resto.', 28153),
(154438, 'esES', 'Ver para creer... Dar de comer la sangre de un planeta a un ogro para que así empiece a usar la sesera. ¡Eso es imposible! ¿Verdad? Bueno, machácalo por si las moscas.', '', 28153),
(154437, 'esES', '¡Estupendo! ¡Seguro que esto llama la atención de la gente!', '', 28153),
(154436, 'esES', '', '¡Unos toneles de pólvora de azerita han caído al agua! ¡Recupéralos antes de que se hundan!', 28153),
(154435, 'esES', 'Ya he usado todas las imágenes que me trajiste. Si te sobra algo de tiempo, me vendrían bien unas cuantas fotografías nuevas.', '', 28153),
(154434, 'esES', '', 'Nuestro campamento vuelve a ser seguro, pero no te descuides.', 28153),
(154433, 'esES', '¡El armero jefe de Ventura y Cía. está aquí! Llevábamos tiempo intentando localizarlo. ¿Podrías ir y darle una paliza de mi parte?', '', 28153),
(154432, 'esES', '', 'Ojalá pudieras ver la flota. ¡Seguro que hasta alguien que ha viajado tanto como tú se impresionaría!', 28153),
(154431, 'esES', 'Ah, ¡Boralus! Una ilustre ciudad repleta de bandas callejeras y nobles pendencieros. En Gnomeregan nunca ha habido esos problemas.', '', 28153),
(154430, 'esES', 'He decidido añadir imágenes de otros lugares de la zona a la publicidad de mi negocio. Empecemos por la ciudad.', '', 28153),
(154429, 'esES', '', '¡Saboteadores de la Alianza se han infiltrado en nuestras filas! ¡Expúlsalos! ¡Haz que sangren!', 28153),
(154428, 'esES', '', 'Pero bueno, ¡es el momento de usar el pase de ferri!', 28153),
(154427, 'esES', 'Ventura y Cía. ofreció un suculento aumento a mi armero jefe y se fue a trabajar para ellos. No le culpo, el oro es el oro, pero ahora vas a tener que matarlo. Una pena, ¿eh?', '', 28153),
(154426, 'esES', '¡Qué hermosura! Y lo mejor de las fotos es que no se nota el olor a caballo.', '', 28153),
(154425, 'esES', 'Lord Norwington quiere que su hermosa hacienda sea la protagonista del siguiente folleto de Fuenteburbuja. Por mí, encantado.', '', 28153),
(154424, 'esES', 'Ventura y Cía. está atiborrando a sus ogros de azerita; dice que los hace más listos. Probablemente no sea así, pero... ve y ocúpate de todas formas. Por si acaso.', '', 28153),
(154423, 'esES', '', 'La esencia de las pozas de la luna te será muy útil en la batalla. Haz lo mismo con cualquier poza que los kaldorei consagren de ahora en adelante.', 28153),
(154422, 'esES', '', 'Los kaldorei se valen de las pozas de la luna para recuperar fuerzas en la batalla. Drena el poder de las pozas para que no puedan usarlas de nuevo. ¿Entendido?', 28153),
(154421, 'esES', '¡Justo a tiempo! Un poco más y esto habría afectado a la reputación de mis termas.', '', 28153),
(154420, 'esES', 'Ten cuidado, Taelia. No confíes en esos sabios encapuchados.', '', 28153),
(154419, 'esES', 'Se rumorea que Ventura y Cía. ha averiguado cómo domar elementales de azerita pura. Alguien tiene que detenerlos. Y con alguien me refiero a ti.', '', 28153),
(154418, 'esES', '', 'Haré que nuestros encantadores imbuyan de azerita los colgantes. ¡Ahora su poder pertenece a la Horda!', 28153),
(154417, 'esES', '', 'Los kaldorei extraen poder de los colgantes de piedra lunar. Arrebátaselos cueste lo que cueste.', 28153),
(154416, 'esES', '', 'Buen trabajo. Enviaré la azerita a nuestras reservas de inmediato.', 28153),
(154415, 'esES', '', 'La azerita brota de entre las ruinas de Costa Oscura. ¡No permitiremos que la Alianza se haga con ningún fragmento!', 28153),
(154414, 'esES', '', 'Este es exactamente el mensaje que quería mandar a Malfurion. Bien hecho.', 28153),
(154413, 'esES', '', 'Esos fuegos fatuos no son más que insectos a los que aplastar. Extingue su luz y pronto un manto de oscuridad cubrirá el cielo.', 28153),
(154412, 'esES', '¡Qué desastre! ¡El agua se ha vuelto loca y está atacando a mis huéspedes!', '', 28153),
(154411, 'esES', '', '¡Idiotah! ¡G\'huun no caerá! ¡Vuehtro poder eh inútil!', 28153),
(154410, 'esES', '', 'Nuestros cocineros podrán preparar un buen plato con esto. Gracias.', 28153),
(154409, 'esES', '', 'Mis hermanos druidas comen como osos y necesitamos más suministros. Sé que no es una tarea agradable, pero ¿podrías encargarte?', 28153),
(154408, 'esES', 'Vamos a ganarnos la paga. ¡Fuego a discreción!', '', 28153),
(154407, 'esES', '¡Ja, ja! Muy bien.', '¡Ja, ja! Muy bien.', 28153),
(154406, 'esES', 'Qué grosería.', 'Qué grosería.', 28153),
(154405, 'esES', '¿Por qué haceh eso?', '¿Por qué haceh eso?', 28153),
(154404, 'esES', 'En nombre de todoh loh loa, ¿qué creeh que ehtáh haciendo?', 'En nombre de todoh loh loa, ¿qué creeh que ehtáh haciendo?', 28153),
(154403, 'esES', '¡Vale ya!', '¡Vale ya!', 28153),
(154402, 'esES', '¡Paso! ¡Aquí viene la artillería pesada!', '', 28153),
(154401, 'esES', 'Ocho octavoh. ¡Eso eh toda una moneda completa! ¡Ale! ¡A vivir la vida!', '', 28153),
(154400, 'esES', 'Loh piratah tienen la cohtumbre de dividir suh realeh de a ocho en octavoh. Sería una suerte si encontrarah ocho de elloh. ¡En Fuerte Libre abundan los tesoroh sin reclamar!', '', 28153),
(154399, 'esES', 'A ese bicho le ha podido la gula. ¿A alguien le apetecen unoh calamareh?', '', 28153),
(154398, 'esES', 'Una medusa gigante campa a suh anchah por lah aguah de Fuerte Libre. No importa cuántoh arponeh le lancemoh, ¡sigue viniendo a por máh!', '', 28153),
(154397, 'esES', 'Hah acabado con el capitán aterrador Vandegrim y liberado su alma. ¡Piensa en todoh loh tesoroh que han dejado de ehtar malditoh!', '', 28153),
(154396, 'esES', 'El capitán Vandegrim eh uno de loh forajidoh máh temidoh en ehtoh lareh. Se rumorea que su codicia era tal, que ni la muerte ha podido detener suh pillajeh.', '', 28153),
(154395, 'esES', '¡Iggksh ywaq ag\'rr ni ky!', '', 28153),
(154394, 'esES', '¡Ah\'shel ywaq qam yrr woth\'gl!', '', 28153),
(154393, 'esES', 'Ocho octavos. ¡Eso es toda una moneda completa! ¡Ale! ¡A vivir la vida!', '', 28153),
(154392, 'esES', '¡Za ag\'rr wgah thyzz zuq!', '', 28153),
(154391, 'esES', 'Los piratas tienen la costumbre de dividir sus reales de a ocho en octavos. Sería una suerte si encontraras ocho de ellos. ¡En Fuerte Libre abundan los tesoros sin reclamar!', '', 28153),
(154390, 'esES', 'A ese bicho le ha podido la gula. ¿A alguien le apetecen unos calamares?', '', 28153),
(154389, 'esES', 'Una medusa gigante campa a sus anchas por las aguas del Fuerte Libre. No importa cuántos arpones le lancemos, ¡sigue viniendo a por más!', '', 28153),
(154388, 'esES', '¡Ga ag\'rr ez AN\'zig wgha kyth zuq!', '', 28153),
(154387, 'esES', 'Has acabado con el capitán aterrador Vandegrim y liberado su alma. ¡Piensa en todos los tesoros que han dejado de estar malditos!', '', 28153),
(154386, 'esES', 'El capitán Vandegrim es uno de los forajidos más temidos en estos lares. Se rumorea que su codicia era tal que ni la muerte ha podido detener sus pillajes.', '', 28153),
(154385, 'esES', 'Ehte no eh el futuro que me prometieron...', '', 28153),
(154384, 'esES', '¡La sangre de G\'huun fluye por mih venah! ¡Temblad ante mi poder!', '', 28153),
(154383, 'esES', 'Las cosas que he visto...', 'Tu amabilidad me sorprende.', 28153),
(154382, 'esES', '¡Mi poder oh doblegará!', '', 28153),
(154381, 'esES', 'Gracias. No habría durado mucho más.', 'Gracias. ¡No miraré atrás!', 28153),
(154380, 'esES', '¡El poder de G\'huun será vuehtro fin!', '', 28153),
(154379, 'esES', '¡Observad vuehtro fin y desehperaoh!', '', 28153),
(154378, 'esES', '¡Acudid, elegidoh! ¡La sangre noh dará la victoria!', '', 28153),
(154377, 'esES', '¡Alzaoh con mi sangre y aplahtad a loh débileh!', '', 28153),
(154376, 'esES', '¡Venid, hermanoh! ¡Alimentaoh de loh infieleh!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'esES', '¡Devolvedme vuehtra sangre!', '', 28153),
(154374, 'esES', '¡G\'huun! ¡Acepta ehta ofrenda de sangre!', '', 28153),
(154373, 'esES', 'Nunca tuvihte futuro.', '', 28153),
(154372, 'esES', 'Débil. Como había predicho.', '', 28153),
(154371, 'esES', '¡Todo eh como lo he previhto!', '', 28153),
(154370, 'esES', '¡Venid, insectoh! Ya he vihto vuehtro final.', '', 28153),
(154369, 'esES', 'Mi madre murió cuando yo era muy joven y tuvo que criarme mi padre. Era marinero y siempre me dejaba la flor de un tallomar cuando se echaba a la mar.', 'Mi madre murió cuando yo era muy joven y tuvo que criarme mi padre. Era marinero y siempre me dejaba la flor de un tallomar cuando se echaba a la mar.', 28153),
(154368, 'esES', '', 'Alerta. Manifestación de proyección oscura.', 28153),
(154367, 'esES', '', 'Alerta. Resguardo de contención de Vacío comprometido.', 28153),
(154366, 'esES', '', 'Has actuado con nobleza, adalid.', 28153),
(154365, 'esES', '', 'Alerta. Detecto niveles peligrosos de energía del Vacío.', 28153),
(154363, 'esES', '', 'Alerta. Réplica de nerubianos adicionales.', 28153),
(154362, 'esES', 'Se ha restaurado el equilibrio. ¡Anu\'dorini talah!', '', 28153),
(154361, 'esES', 'Este ser camina en las sombras, adalid, pero nadie puede esconderse de la Luz sagrada de Elune. Pon fin a su existencia.', '', 28153),
(154360, 'esES', '', 'Alerta. Réplica de silítidos adicionales.', 28153),
(154359, 'esES', '¡Bah! ¡Maldita hierba! El tallomar solo me recuerda que hay buenoh marineroh que no regresan a casa y cargamentoh que se pierden en el fondo del mar.', '¡Bah! ¡Maldita hierba! El tallomar solo me recuerda que hay buenoh marineroh que no regresan a casa y cargamentoh que se pierden en el fondo del mar.', 28153),
(154358, 'esES', '', 'No hay lugar para Mythrax en este mundo.', 28153),
(154357, 'esES', '', 'Que Elune te bendiga, adalid. Brillas con la luz de las estrellas.', 28153),
(154356, 'esES', '', 'A mis arqueros les vendría bien tu ayuda. ¡Échale una mano a quien lo necesite!', 28153),
(154355, 'esES', '', 'Esta guerra debe terminar.', 28153),
(154354, 'esES', '', 'Tienes mi protección.', 28153),
(154353, 'esES', '', 'Carga completada. Apagando disco.', 28153),
(154352, 'esES', '', 'Has eliminado la amenaza y me has devuelto el arma de asedio de una pieza. Eso son puntos extras...', 28153),
(154351, 'esES', '', 'Hay que restaurar el orden.', 28153),
(154350, 'esES', '', 'Todos tenemos nuestro lugar. El mío está aquí.', 28153),
(154349, 'esES', '', 'Estoy débil, pero heme aquí.', 28153),
(154348, 'esES', '', '¿Alguna vez has usado algo así? Agárrate bien, ¡te espera una buena sorpresa!', 28153),
(154347, 'esES', '', 'Acceso al disco. Cargando datos corruptos.', 28153),
(154346, 'esES', 'Enviaré a todos los soldados que pueda. Con suerte, conseguirán repeler el ataque. No podemos permitirnos una guerra en dos frentes.', '', 28153),
(154345, 'esES', 'Siento una perturbación en el norte, pero desconozco el origen. Temo que la Horda haya iniciado un ataque desde las montañas. ¡Investiga qué ocurre!', '', 28153),
(154344, 'esES', '', 'Te has chamuscado un poco. ¿Algo no ha ido según lo previsto?', 28153),
(154343, 'esES', '', 'Aunque están bajo el agua, esos toneles de pólvora de azerita son bastante peligrosos. Detónalos antes de que suban a la superficie, pero intenta volver de una pieza...', 28153),
(154342, 'esES', '', 'Sobrecarga de la matriz de datos. Acceso a múltiples discos.', 28153),
(154341, 'esES', 'Tallomar, ¿eh? Algunoh miembroh de mi tripulación se aseguran de que suh mediah naranjah tengan uno cuando zarpamoh. No me ehtraña que quieran evitar que suh familiah sufran por su dehtino si ocurre algo.', 'Tallomar, ¿eh? Algunoh miembroh de mi tripulación se aseguran de que suh mediah naranjah tengan uno cuando zarpamoh. No me ehtraña que quieran evitar que suh familiah sufran por su dehtino si ocurre algo.', 28153),
(154340, 'esES', '', 'No dudé de ti en ningún momento.', 28153),
(154339, 'esES', '', 'La Horda ha llegado. Son muchos y no podemos subestimar a ninguno de ellos. Este enemigo en concreto parece... resistente. Ten cuidado, adalid.', 28153),
(154338, 'esES', '', 'Acceso al disco. Cargando datos de Yogg-Saron.', 28153),
(154337, 'esES', '', 'Acceso al disco. Cargando datos de C\'thun.', 28153),
(154335, 'esES', '', '¡Hay saboteadores de la Horda entre nuestras filas! ¡Que sufran como hemos sufrido nosotros!', 28153),
(154334, 'esES', '', 'Bien luchado, adalid. Debo admitir que hasta mis centinelas podrían aprender de ti.', 28153),
(154333, 'esES', '', 'Es hora de combatir el fuego con fuego. ¡Debemos librarnos de los demoledores de la Horda y obligarlos a volver a Los Baldíos!', 28153),
(154332, 'esES', '', 'Elune te sonríe, adalid. Y yo también.', 28153),
(154331, 'esES', '', '¡La Horda intenta robar la esencia de nuestras pozas de la luna! ¡No dejes que profanen los manantiales sagrados!', 28153),
(154330, 'esES', '', 'La Horda no debería salir de sus páramos. Les enseñaremos a no acercarse a nuestros bosques.', 28153),
(154329, 'esES', '', 'La Horda ha establecido una base más allá de las fronteras de Vallefresno. ¡Reúne a los druidas que cuidan el bosque!', 28153),
(154328, 'esES', '', 'Bien luchado, adalid. Y con qué fervor...', 28153),
(154327, 'esES', '', '¡La Horda está robando recursos de nuestras tierras! Detenlos antes de que consuman por completo nuestro bosque sagrado.', 28153),
(154326, 'esES', '', 'Suh habilidadeh no han empeorado nada trah mileh de añoh muertoh, pero tú hah sido más fuerte.', 28153),
(154325, 'esES', '', '¡Esa eh la guardia principal del rey Dazar! ¡No se rendirán fácilmente!', 28153),
(154324, 'esES', '¡Ja! ¡Parece que ahora esos no-muertos están requetemuertos! ¡Buen trabajo!', '', 28153),
(154323, 'esES', 'Esos trols no-muertos parecen más duros que el resto. ¡Cuidado!', '', 28153),
(154322, 'esES', '¿Qué puedes contarme acerca del tallomar?', '¿Qué puedes contarme acerca del tallomar?', 28153),
(154321, 'esES', '', 'Justo lo que necesitábamos, adalid. No olvidaremos tu ayuda.', 28153),
(154320, 'esES', '', 'La Horda ya tiene armas de azerita. Veamos si podemos confiscar unas cuantas, ¿eh?', 28153),
(154319, 'esES', 'Las Cámaras de Piedra no cuentan.', '', 28153),
(154318, 'esES', 'Pff. Un producto hecho por un enano jamás tendría una avería así.', '', 28153),
(154317, 'esES', '', '¡Un trabajo excelente! Mis alquimistas mantendrán la azerita fuera del alcance de la Horda.', 28153),
(154316, 'esES', 'Bah, es el típico ejemplo de mala fabricación de los trols. Ese gólem se ha averiado: ¡arreglémoslo a golpes!', '', 28153),
(154315, 'esES', '', 'Tenemoh que encontrar a Julwaba anteh que Jakra\'zet.', 28153),
(154314, 'esES', '', 'La magia ohcura de Zul ha corrompido a ehte guardián. Debemoh calmar su furia pa poder repararlo.', 28153),
(154313, 'esES', '', 'Zul... Lo que le hah hecho a ehte lugar sagrado eh imperdonable.', 28153),
(154312, 'esES', '', 'Adióh, Halu. Dehcansa en paz.', 28153),
(154311, 'esES', '', 'Aaah, el maehtro de armah Halu... Entrenó a mi padre, y a su padre anteh que a él. Su misión ha concluido. Su alma merece dehcansar.', 28153),
(154310, 'esES', '¡Ja! Parece que hoy es él quien ha aprendido algo.', '', 28153),
(154309, 'esES', 'Un guerrero que entrenó a la realeza Zandalari vaga por esta tumba. ¡Hagamos que descanse en paz!', '', 28153),
(154308, 'esES', '', 'Mis arqueros deberían poder encargarse del resto. Tu presencia lo ha cambiado todo, adalid. Gracias.', 28153),
(154307, 'esES', '', 'Las tropas enemigas nos atacan por el norte. Adalid, ha llegado la hora de hacerles frente.', 28153),
(154306, 'esES', '¡Dejad que pasen!', '', 28153),
(154305, 'esES', '', '¡Ya casi ehtá! Oigo cómo la voz de Akunda inunda mi mente.', 28153),
(154304, 'esES', '', 'Haré lo posible pa reparar la mente de Akunda, pero tieneh que prepararte pa reprimir cualquier recuerdo que aflore.', 28153),
(154303, 'esES', 'Ywaq ongg an\'qov i lal halahs nuq.', '', 28153),
(154302, 'esES', 'Ywaq mh\'naus wgah zaix zyqtahg.', '', 28153),
(154301, 'esES', 'Mojambo se cobrará... ehta deuda...', '', 28153),
(154300, 'esES', '', '¿Dónde... dónde ehtoy? ¿Qué ehtoy haciendo aquí?', 28153),
(154299, 'esES', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek...', '', 28153),
(154298, 'esES', '', 'Son un poco misteriosos, pero importantes para Kul Tiras. Ayudan a llevar peces a las redes y lluvia a los campos del valle.', 28153),
(154297, 'esES', '', 'La mayoría de esta gente busca en el mar la guía que otros encuentran en la Luz, pero los Sabiomar tienen una conexión mucho más profunda con el agua.', 28153),
(154296, 'esES', '', 'Te prestaría a Alatifón para que fueses hasta allí, pero los Sabiomar solo aceptan visitas que lleguen en barco.', 28153),
(154295, 'esES', '', 'No me pasará nada, Cyrus. Además, ¡no estaré sola!', 28153),
(154294, 'esES', '¡Oou yyqzz ez thyzz phquathi zuq!', '', 28153),
(154293, 'esES', '¡Oou gul\'kafh lal lwhuk!', '', 28153),
(154292, 'esES', '¡Qam oou iilth ez i awtgsshu amun on\'ma!', '', 28153),
(154291, 'esES', '¡Log\'loth w\'oq Ongg!', '', 28153),
(154290, 'esES', '', 'Ha aparecido azerita entre las ruinas de Costa Oscura. ¡No podemos dejar que la Horda se haga con ella!', 28153),
(154289, 'esES', '¡W\'oq uhn\'agth ez qam Shandai!', '', 28153),
(154288, 'esES', '¡Awtgssh shn ongg shg\'ullwaq!', '', 28153),
(154287, 'esES', '¡Zuq ag\'xig bormaz ag\'thyzak!', '', 28153),
(154286, 'esES', '¡Gracias!', '¡Gracias!', 28153),
(154285, 'esES', '¡Za qualar ag\'xig za al\'tha!', '', 28153),
(154284, 'esES', '¡No cobro lo suficiente por esto!', '¡No cobro lo suficiente por esto!', 28153),
(154283, 'esES', '¡AAAAAAAAAAAAAAAAAAAAAAAAH!', '¡AAAAAAAAAAAAAAAAAAAAAAAAH!', 28153),
(154282, 'esES', '¡Gracias por salvarme!', '¡Gracias por salvarme!', 28153),
(154281, 'esES', '¡Pensé que me iba a convertir en salchichas!', '¡Pensé que me iba a convertir en salchichas!', 28153),
(154280, 'esES', '¡Oou vwahuHn ag\'xig shfk zuq!', '', 28153),
(154279, 'esES', '¡Gracias, colega!', '¡Gracias, colega!', 28153),
(154278, 'esES', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'esES', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma.', '', 28153),
(154276, 'esES', 'Za awtgsshu wgah uulg\'ma ywaq zaix.', '', 28153),
(154275, 'esES', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr.', '', 28153),
(154274, 'esES', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor.', '', 28153),
(154273, 'esES', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma.', '', 28153),
(154272, 'esES', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh.', '', 28153),
(154271, 'esES', 'Cuando los espíritus están en paz, también lo está el bosque. Gracias.', '', 28153),
(154270, 'esES', 'Estos espíritus no son más que una sombra de lo que fueron. Confórtalos, adalid. Otórgales paz.', '', 28153),
(154269, 'esES', 'Por algo me llaman señor de loh maleficioh.', '', 28153),
(154268, 'esES', 'Llévate mi vara de maleficioh y tranhforma a algunoh de esoh sacerdoteh en algo máh interesante.', '', 28153),
(154267, 'esES', 'Si creeh que eso ha sido duro, deberíah ver lo que otroh loa obigan a hacer a suh seguidoreh.', '', 28153),
(154266, 'esES', 'Si nosotros no podemos detener la corrupción, ¿quién lo hará?', 'Si nosotros no podemos detener la corrupción, ¿quién lo hará?', 28153),
(154265, 'esES', 'Loh druidah de Gonk son muy serioh. Quiero que leh gahteh una broma con loh altareh de loh loa pa que se animen. Ah, te aviso de que igual te quieren matar.', '', 28153),
(154264, 'esES', 'Si esto se extiende... Azeroth estará condenado.', 'Si esto se extiende... Azeroth estará condenado.', 28153),
(154263, 'esES', 'La naturaleza grita de dolor... ¿Cómo podemos parar esta locura?', 'La naturaleza grita de dolor... ¿Cómo podemos parar esta locura?', 28153),
(154262, 'esES', 'Nuestros poderes no funcionan... ¿Cómo podemos sanar el planeta?', 'Nuestros poderes no funcionan... ¿Cómo podemos sanar el planeta?', 28153),
(154261, 'esES', '', 'Vaya viajecito, ¿eh? Habéis hecho un trabajo excelente. Formáis muy buen equipo.', 28153),
(154260, 'esES', '', 'Nuestros dragones hada no están acostumbrados a llevar bridas, así que será un viaje movidito. Monta en uno de ellos y guía sus ataques.', 28153),
(154259, 'esES', '¡Me alimento de vuestro terror!', '', 28153),
(154258, 'esES', 'Refuerzos de Forjaz, ¡marchad hacia la base enemiga!', '', 28153),
(154257, 'esES', '¡Aplastad Ar\'gorok! ¡Por Arathor! ¡Por Stromgarde! ¡POR LA ALIANZA!', '', 28153),
(154256, 'esES', '', 'Luchah como loh Zandalari de lah leyendah. Impresionante.', 28153),
(154255, 'esES', '', 'Sigueh demohtrando tu valía. Bien hecho.', 28153),
(154252, 'esES', '', 'Graciah a ti, nuehtroh puebloh ehtán a salvo.', 28153),
(154251, 'esES', '', 'Con la muerte del enemigo, podemoh seguir avanzando.', 28153),
(154246, 'esES', '', 'El escondrijo debería estar más adelante. Ahí estaremos a salvo de momento.', 28153),
(154245, 'esES', '', 'Con suerte, no oiremoh hablar máh de esa criatura.', 28153),
(154244, 'esES', '', 'Loh loa predijeron tu victoria. Me alegra ver que no se equivocaban.', 28153),
(154243, 'esES', '', 'A la Horda le agradará saber que hah acabado con ehta amenaza.', 28153),
(154242, 'esES', '', 'Sabía que, contra ti, su derrota era segura.', 28153),
(154240, 'esES', '¿Sentís un escalofrío en el espinazo? Ese es mi don.', '', 28153),
(154239, 'esES', '', 'Se rumorea que por aquí ronda un poderoso enemigo que quiere matarte. Acaba con él.', 28153),
(154238, 'esES', '', 'Unoh guerreroh de la Horda me informan de que hay una gran amenaza cerca de ti. Acaba con ella.', 28153),
(154237, 'esES', '', 'Unoh ehploradoreh de la Horda han localizado a un poderoso enemigo. Proponen que le demoh una muerte rápida. Ocúpate.', 28153),
(154234, 'esES', 'Nazmir parece suminihtrar una cantidad inagotable de ehtoh salvajeh. Graciah por reducir su número.', '', 28153),
(154232, 'esES', '¡Ja! ¡Lo llevas en la sangre! ¡Hace tiempo que no veía a nadie dominar la pista así!', '', 28153),
(154230, 'esES', 'Loh trolh de sangre atacan lah puertah. ¡Combatid a esoh salvajeh con loh cuernoh de guerra!', '', 28153),
(154228, 'esES', 'Hoy no tengo trabajo para ti. La mayoría de los Bellacos ha ido a tirarse en trineo para desfogarse. ¡Coge un pingüiño y lánzate por la pista!', '', 28153),
(154225, 'esES', '', 'Cuidado, cerca de ti se encuentra un poderoso adversario. Tenemoh que acabar con él anteh de que cause máh daño.', 28153),
(154224, 'esES', 'Elune alaba tu valentía, adalid.', '', 28153),
(154223, 'esES', '', 'Loh loa noh advierten de la presencia de un poderoso enemigo. Exigen su sacrificio.', 28153),
(154222, 'esES', 'Los ataques de la Reina alma en pena son incesantes. ¡Rastrea el bosque y purga este lugar de su presencia oscura!', '', 28153),
(154221, 'esES', '', 'Mih ehploradoreh han detectado a un poderoso adversario cerca de aquí. Mátalo cuanto anteh.', 28153),
(154220, 'esES', 'Mih tropah ya pueden encargarse. Graciah por otorgarleh el tiempo necesario pa reagruparse.', '', 28153),
(154219, 'esES', '', 'Cuidado, un ser poderoso anda cerca. Dale muerte anteh de que acabe contigo.', 28153),
(154218, 'esES', 'La amenaza ha pasado por ahora. Los ancestros descansarán una vez más.', '', 28153),
(154217, 'esES', '', 'Un poderoso adversario anda cerca. Mátalo anteh de que hiera a loh nuehtroh.', 28153),
(154216, 'esES', '¡Matad a todo el que no sea Zandalari!', '', 28153),
(154215, 'esES', 'La amenaza de la Horda ha despertado a los ancestros. Expulsa a estos villanos para devolver la paz a nuestro bosque.', '', 28153),
(154213, 'esES', 'Gracias a ti gozamos de la tregua necesaria para seguir adelante.', '', 28153),
(154212, 'esES', 'Los árboles del bosque se retuercen y se astillan de agonía con el avance de la Horda. ¡Debemos detenerlo de inmediato!', '', 28153),
(154211, 'esES', 'Ten cuidado ahí fuera.', 'Ten cuidado ahí fuera.', 28153),
(154210, 'esES', 'Lah arenah se tragan a loh débileh.', 'Lah arenah se tragan a loh débileh.', 28153),
(154209, 'esES', 'No confíeh en nadie.', 'Ten cuidado ahí fuera.', 28153),
(154208, 'esES', 'Nadie merece ehte dehtino.', 'Nadie merece ehte dehtino.', 28153),
(154207, 'esES', '¿Qué necesitah?', 'Aquí todoh son bienvenidoh.', 28153),
(154205, 'esES', 'Hola.', 'Hola.', 28153),
(154204, 'esES', '', 'Aún te oigo... maestro...', 28153),
(154203, 'esES', 'Mis susurros licuarán vuestras mentes.', '', 28153),
(154202, 'esES', 'Que el hambre te domine. Aliméntate de su sangre.', '', 28153),
(154201, 'esES', 'Ve con tus aliados. Comparte mi don.', '', 28153),
(154200, 'esES', 'Una adquisición excelente. Ahora, rápido, ¡acabad con el resto de los infieles!', '', 28153),
(154199, 'esES', 'La podredumbre corre por tus venas. ¡Que se extienda!', '', 28153),
(154198, 'esES', 'Haceos con uno de los dispositivos de los infieles y cargadlo. Se os recompensará como es debido.', '', 28153),
(154197, 'esES', 'Nuestros hechiceros han detectado corrientes eléctricas inusuales en el templo.', '', 28153),
(154196, 'esES', '¡Que comience el festín de mil fauces!', '', 28153),
(154195, 'esES', '¡Un trabajo excelente! Ahora, a por el corazón de Sethraliss.', '', 28153),
(154194, 'esES', 'Traedme esas reliquias y seréis recompensados.', '', 28153),
(154193, 'esES', 'Crías, ¡venid y alimentaos!', '', 28153),
(154192, 'esES', 'Tengo entendido que los infieles han escondido varios artefactos de mi gente en el bazar, justo antes del corazón del templo.', '', 28153),
(154191, 'esES', 'Venid, siervos de la podredumbre. ¡Consumid!', '', 28153),
(154190, 'esES', '¡Un espécimen excelente! ¡Ahora toca limpiar el templo de esta escoria infiel!', '', 28153),
(154189, 'esES', 'He oído que una raza muy rara de croluscos tiene su madriguera en el templo. Traedme una de sus crías y os recompensaré.', '', 28153),
(154188, 'esES', '¡Nada detiene a mi pestilencia!', '', 28153),
(154187, 'esES', '¡Mi añublo no puede purgarse!', '', 28153),
(154186, 'esES', '¡Los titanes no pueden salvaros!', '', 28153),
(154185, 'esES', '¡Nadie escapa de la infección!', '', 28153),
(154184, 'esES', 'Los sellos se han roto. El fin ha llegado. Venid, seréis los primeros en recibir mi don.', '', 28153),
(154183, 'esES', 'Los trabajadores te están muy agradecidos. Has evitado que los hagan picadillo.  ', '', 28153),
(154182, 'esES', 'La infección... está en vuestro interior...', '', 28153),
(154181, 'esES', '¡Las brujas han vuelto a invadir Puerto del Tallador! ¡Rescata a los trabajadores antes de que los conviertan en salchichas! ', '', 28153),
(154180, 'esES', '', 'Los espíritus de los ancestros descansan y has acabado con los Drust. Buen trabajo.', 28153),
(154179, 'esES', '', 'Esta batalla pone en peligro a los refugiados de Puesto de Arom. ¡Merma las filas enemigas!', 28153),
(154178, 'esES', 'Desata la tormenta. ¡Derroca al usurpador!', '', 28153),
(154177, 'esES', 'Blandes bien mi poder.', '', 28153),
(154176, 'esES', 'Criatura, por fin puedes oírme. Hay un traidor en el templo.', '', 28153),
(154175, 'esES', '', 'Una criatura malvada amenaza a mi gente. Mátala.', 28153),
(154174, 'esES', '', 'Las brujas han liberado a una poderosa criatura en esta zona. ¡Acaba con ella!', 28153),
(154173, 'esES', '', '¡Bien hecho! La gente de Drustvar está más segura gracias a ti.', 28153),
(154172, 'esES', '', '¡Buen golpe! ¡Se lo pensarán dos veces antes de volver a Drustvar!', 28153),
(154171, 'esES', '¡Al fin soy libre! Gracias.', '', 28153),
(154170, 'esES', '', 'Los exploradores han informado de que hay un enemigo peligroso cerca. ¡Acaba con él!', 28153),
(154169, 'esES', '', 'Un poderoso enemigo amenaza a mi gente en esta zona. Neutraliza la amenaza.', 28153),
(154168, 'esES', '¿Cómo perdí?', '', 28153),
(154167, 'esES', '', 'Tienes el más sincero agradecimiento de mi gente. Esta noche todos podremos dormir un poco mejor.', 28153),
(154166, 'esES', '', 'La gente de Drustvar agradece tu ayuda.', 28153),
(154165, 'esES', 'Eso no ha sido muy inteligente.', '', 28153),
(154164, 'esES', '', 'Nos han informado de que hay un enemigo en esta zona. Liquídalo.', 28153),
(154163, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t¡G\'huun te lanza |cFFFF0404|Hspell:272506|h[Corrupción explosiva]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t¡G\'huun te lanza |cFFFF0404|Hspell:272506|h[Corrupción explosiva]|h|r!', 28153),
(154162, 'esES', 'Por fin, paz...', '', 28153),
(154161, 'esES', '', 'Un enemigo peligroso amenaza a la gente de Drustvar. ¡Ocúpate de él!', 28153),
(154160, 'esES', 'Si el océano no ha podido acabar conmigo, ¿qué te hace pensar que tú podrás?', '', 28153),
(154159, 'esES', 'Me propagaré y consumiré este mundo.', '', 28153),
(154158, 'esES', 'Necesitamos un ferri que nos lleve al Monasterio Canto Tormenta.', 'Necesitamos un ferri que nos lleve al Monasterio Canto Tormenta.', 28153),
(154157, 'esES', 'Tus restos sirven a un nuevo amo.', '', 28153),
(154155, 'esES', 'Todas las palabras sin decir...', '', 28153),
(154154, 'esES', '¡Todavía puedo luchar!', '', 28153),
(154153, 'esES', '¡Tus gritos resonarán para siempre!', '', 28153),
(154152, 'esES', '¡La maldición de la carne os consume!', '', 28153),
(154151, 'esES', '¡El brote ha comenzado!', '', 28153),
(154150, 'esES', '', 'Sabeh que debo, Kaja. El deber eh lo primero.', 28153),
(154149, 'esES', '', 'Jakra\'zet eh un traidor, pero el Rey no intervendrá sin pruebah.', 28153),
(154148, 'esES', 'Parece que ahora... podré descansar...', 'Parece que ahora... podré descansar...', 28153),
(154147, 'esES', '¡Intentamos advertirte!', '¡Intentamos advertirte!', 28153),
(154146, 'esES', '', 'Ve a ver qué lograh averiguar. No me separaré de Rakera.', 28153),
(154145, 'esES', 'Ya puedeh ehcuchar lah palabrah de Akunda, pero debeh hacerlo en solitario. Cuando quierah empezar, dirígete al altar y reza.', '', 28153),
(154144, 'esES', 'Akunda solo entrará en tu mente si ha sido purificada.', '', 28153),
(154143, 'esES', 'Deseo volver a este lugar.', 'Deseo volver a este lugar.', 28153),
(154142, 'esES', 'Niveles al máximo. Reiniciando recolección.', '', 28153),
(154141, 'esES', '<Althair te mira con afecto>.', '<Althair te mira con afecto>.', 28153),
(154140, 'esES', '<Althair te mira fijamente>.', '<Althair te mira fijamente>.', 28153),
(154139, 'esES', 'Evacuación de líquidos en proceso. Iniciando reposo.', '', 28153),
(154138, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun empieza a lanzar |cFFFF0404|Hspell:267700|h[Mirada de G\'huun.]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun empieza a lanzar |cFFFF0404|Hspell:267700|h[Mirada de G\'huun.]|h|r.', 28153),
(154133, 'esES', 'Espécimen seleccionado para destrucción.', '', 28153),
(154132, 'esES', 'Iniciando dispersión de sangre en objetivo.', '', 28153),
(154131, 'esES', 'Activando recuperación de maza.', '', 28153),
(154130, 'esES', 'Desplegando maza.', '', 28153),
(154129, 'esES', 'Niveles de combustible agotados. Apagando...', '', 28153),
(154128, 'esES', '', '¡Dranosh\'ek Mag\'har!', 28153),
(154127, 'esES', 'Sujetos listos para contaminación.', '', 28153),
(154126, 'esES', '', 'La guerra domina estas tierras. ¡Bien! Disfrutaremos de la carnicería... ¡y alcanzaremos la victoria!', 28153),
(154125, 'esES', '', 'Somos los últimos supervivientes de una tribu orgullosa. Los incorruptos... Los indómitos... ¡Los Mag\'har!', 28153),
(154124, 'esES', '', 'Para algunos, no son más que palabras... pero para nosotros, lo son todo.', 28153),
(154123, 'esES', '', 'Fuerza y honor. Sangre y trueno.', 28153),
(154122, 'esES', 'Más combustible para corrupción.', '', 28153),
(154121, 'esES', 'Nuevo objetivo de corrupción.', '', 28153),
(154120, 'esES', 'Anfitriones detectados. Activando infección.', '', 28153),
(154119, 'esES', '', 'Son muy reales, te lo prometo. Y también muy peligrosos. Ni los sethrak se atreven a adentrarse en el cañón.', 28153),
(154118, 'esES', 'Iniciando recolección de plasma.', '', 28153),
(154117, 'esES', '¡Más rápido, babosas! ¡Arregladlo y cobraréis!', '', 28153),
(154116, 'esES', 'Qué isla más hermosa...', 'Qué isla más hermosa...', 28153),
(154115, 'esES', '¿Fue glorioso?', '¿Fue glorioso?', 28153),
(154114, 'esES', '', 'Hay que moverse. Rakera no sobrevivirá en ehte desierto mucho tiempo.', 28153),
(154113, 'esES', 'No duele tanto como...', 'No duele tanto como...', 28153),
(154112, 'esES', '¿Por qué fracasé?', '¿Por qué fracasé?', 28153),
(154111, 'esES', '¡Muere, buitre!', '¡Muere, buitre!', 28153),
(154110, 'esES', '¡No me derrotarás!', '¡No me derrotarás!', 28153),
(154109, 'esES', '¿Dónde está tu Reina alma en pena ahora?', '¿Dónde está tu Reina alma en pena ahora?', 28153),
(154108, 'esES', '¡No he sobrevivido al océano para morir a manos de semejante escoria!', '¡No he sobrevivido al océano para morir a manos de semejante escoria!', 28153),
(154107, 'esES', '', 'Me parece que no.', 28153),
(154106, 'esES', 'Es hora de poner en marcha el plan de Nisha. Los sethrak no se olerán nada.', '', 28153),
(154105, 'esES', '', 'Debería haber invertido más en seguridad.', 28153),
(154104, 'esES', '', '¡No puedo permitir que me distraigas!', 28153),
(154103, 'esES', '', '¡Derrótalos a todos si es necesario! Quiero ese destructor de arrecifes operativo a la de ya.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'esES', 'Puede que no dure mucho. Sus heridas son graves.', '', 28153),
(154101, 'esES', '', 'Siempre me las arreglo. ¿Esa es otra superviviente?', 28153),
(154100, 'esES', 'Salva lo que puedas antes de que todo acabe destruido.', 'Salva lo que puedas antes de que todo acabe destruido.', 28153),
(154099, 'esES', 'Aquí hay muchos objetos fascinantes.', 'Aquí hay muchos objetos fascinantes.', 28153),
(154098, 'esES', 'Tardaremoh en tener guardiah suficienteh para proteger el Viejo Camino Mercantil como anteh. Tu ayuda eh importante.', '', 28153),
(154097, 'esES', 'Gracias...', 'Gracias...', 28153),
(154096, 'esES', 'Oh, no... Otra vez no.', 'Oh, no... Otra vez no.', 28153),
(154095, 'esES', 'No dejes que me coman...', 'No dejes que me coman...', 28153),
(154094, 'esES', 'Me dijeron... que sería fácil...', 'Me dijeron... que sería fácil...', 28153),
(154093, 'esES', 'Tu cabeza será un gran trofeo.', 'Tu cabeza será un gran trofeo.', 28153),
(154092, 'esES', 'Algunoh mercadereh han pedido protección pa la caravana. ¿Podríah ehcoltarloh?', '', 28153),
(154091, 'esES', '¡El añublo te llevará!', '¡El añublo te llevará!', 28153),
(154090, 'esES', '¡Te rescataron del mar solo para caer ante mí!', '¡Te rescataron del mar solo para caer ante mí!', 28153),
(154089, 'esES', '¡Morirás aquí!', '¡Morirás aquí!', 28153),
(154088, 'esES', '¡MUESTRA TU VERDADERA CARA, $gSEÑOR:SEÑORA; DE LA MUERTE! ¡ABANDONA ESTE LUGAR SAGRADO!', '¡MUESTRA TU VERDADERA CARA, $gSEÑOR:SEÑORA; DE LA MUERTE! ¡ABANDONA ESTE LUGAR SAGRADO!', 28153),
(154087, 'esES', 'El mayor paso que uno puede dar es el siguiente, $n. Sigue por este camino.', 'El mayor paso que uno puede dar es el siguiente, $n. Sigue por este camino.', 28153),
(154086, 'esES', 'Eres un monstruo creado a imagen y semejanza de Arthas, $n. Cuando te enfrentes a tu final, espero que sufras una muerte lenta, $gtorturado:torturada; por el dolor y el sufrimiento que has infligido a otros.\n\nCuando todo el mundo estaba preocupado por asuntos más importantes, recorriste el planeta a caballo para arrastrar a los muertos hacia una no-vida maldita. Seguro que te decías que era por un bien mayor, pero recuerda mis palabras, $gSeñor:Señora; de la Muerte, habrá consecuencias.\n\n<Zallestrasza se estremece>.\n\nPero, por ahora, tal vez puedas ser útil.', 'Eres un monstruo creado a imagen y semejanza de Arthas, $n. Cuando te enfrentes a tu final, espero que sufras una muerte lenta, $gtorturado:torturada; por el dolor y el sufrimiento que has infligido a otros.\n\nCuando todo el mundo estaba preocupado por asuntos más importantes, recorriste el planeta a caballo para arrastrar a los muertos hacia una no-vida maldita. Seguro que te decías que era por un bien mayor, pero recuerda mis palabras, $gSeñor:Señora; de la Muerte, habrá consecuencias.\n\n<Zallestrasza se estremece>.\n\nPero, por ahora, tal vez puedas ser útil.', 28153),
(154085, 'esES', '<La expresión de Zallestrasza se relaja un poco>.\n\nEso tampoco ha pasado desapercibido, $n. Somos pocos y cada vida es irreemplazable.\n\nEso no justifica la ofensa contra mi vuelo, pero reconocemos y apreciamos tu... moderación. Para alguien como tú no habrá sido fácil.', '<La expresión de Zallestrasza se relaja un poco>.\n\nEso tampoco ha pasado desapercibido, $n. Somos pocos y cada vida es irreemplazable.\n\nEso no justifica la ofensa contra mi vuelo, pero reconocemos y apreciamos tu... moderación. Para alguien como tú no habrá sido fácil.', 28153),
(154084, 'esES', 'Sabemos quién eres, $gSeñor:Señora; de la Muerte $n.\n\nSabemos que atacaste nuestro sagrario. Que corrompiste y esclavizaste a Kyranastrasz.\n\nAlgún día responderás por tus ofensas contra la vida.', 'Sabemos quién eres, $gSeñor:Señora; de la Muerte $n.\n\nSabemos que atacaste nuestro sagrario. Que corrompiste y esclavizaste a Kyranastrasz.\n\nAlgún día responderás por tus ofensas contra la vida.', 28153),
(154083, 'esES', 'Estamos al tanto de tus fechorías, caballero de la Muerte. Tus acciones ayudaron a salvar a Azeroth de la Legión Ardiente, pero has perdido nuestra confianza.\n\nVe con cuidado.', 'Estamos al tanto de tus fechorías, caballero de la Muerte. Tus acciones ayudaron a salvar a Azeroth de la Legión Ardiente, pero has perdido nuestra confianza.\n\nVe con cuidado.', 28153),
(154082, 'esES', 'Parece que me dejé algunos dragones en el Santurario Rubí. <Intentar matarla>', 'Parece que me dejé algunos dragones en el Santurario Rubí. <Intentar matarla>', 28153),
(154081, 'esES', 'Espero que mis actos hayan servido para ganarme un poco de confianza.', 'Espero que mis actos hayan servido para granjearme un poco de confianza.', 28153),
(154080, 'esES', 'De todas formas, tu gente era débil y estaba al borde de la muerte. Solo puse fin a su sufrimiento con más rapidez.', 'De todas formas, tu gente era débil y estaba al borde de la muerte. Solo puse fin a su sufrimiento con más rapidez.', 28153),
(154079, 'esES', 'Salvé todas las vidas que pude.', 'Salvé todas las vidas que pude.', 28153),
(154078, 'esES', '¿Me conoces?', '¿Me conoces?', 28153),
(154077, 'esES', '¡No! ¡No! ¡Nooooooo!', '¡No! ¡No! ¡Nooooooo!', 28153),
(154076, 'esES', '', 'Por la Alianza.', 28153),
(154075, 'esES', '¡Sal de aquí! ¡Sálvate!', '¡Sal de aquí! ¡Sálvate!', 28153),
(154074, 'esES', 'Creo... creo que me lo he hecho encima...', 'Creo... creo que me lo he hecho encima...', 28153),
(154073, 'esES', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(154072, 'esES', '¡Gracias! Creía que no lo contaba.', '¡Gracias! Creía que no lo contaba.', 28153),
(154071, 'esES', '¿Qué son esas cosas? ¡Me largo de aquí!', '¿Qué son esas cosas? ¡Me largo de aquí!', 28153),
(154070, 'esES', '¡Estoy salvado! ¡He estado a punto de convertirme en comida de monstruo!', '¡Estoy salvada! ¡He estado a punto de convertirme en comida de monstruo!', 28153),
(154069, 'esES', '¡Ja! Esto ha sido pan comido...', '', 28153),
(154068, 'esES', 'Inconcebible... ¿Con qué otros horrores se habrá aliado lord Canto Tormenta?', '', 28153),
(154067, 'esES', 'En el santuario hay un poderoso monstruo. Vamos, ¡lo saludaremos con un buen mordisco!', '', 28153),
(154066, 'esES', '¡Cuidado! Siento una fuente de corrupción inmensa en el altar. ¡No podemos permitir que se extienda!', '', 28153),
(154065, 'esES', 'No parece que haya cambiado nada. Mmm... De todas formas, la caza espera.', '', 28153),
(154064, 'esES', '¿No os sentís en paz? ¿O con más voluntad? Sigamos adelante para cumplir nuestro propósito.', '', 28153),
(154063, 'esES', 'Se dice que los Sabiomar se fortalecían con las aguas de estas fuentes purificadoras. Comprobémoslo antes de entrar en el corazón del santuario.', '', 28153),
(154062, 'esES', '¡Bah! ¡Entonceh, seguidme!', '', 28153),
(154061, 'esES', 'Debéis purificaros antes de poner un pie en nuestro lugar más sagrado. Aceptad la bendición de cada fuente de purificación antes de entrar en el corazón del altar.', '', 28153),
(154060, 'esES', 'Toda ayuda nos viene bien. ¡Por la Horda!', '', 28153),
(154059, 'esES', 'Supone un gran alivio saber que no todo está bajo el influjo de lord Canto Tormenta. Gracias.', '', 28153),
(154058, 'esES', 'Hay fuerza en estas pozas. Recoge motas de agua pura, ¡nos otorgarán poder!', '', 28153),
(154057, 'esES', 'Siento que el bien aún mora en este lugar sagrado. Recoged motas de agua pura y con ellas haré que este altar recupere su antigua gloria.', '', 28153),
(154056, 'esES', 'He escapado por poco. Gracias, $c.', 'He escapado por poco. Gracias, $c.', 28153),
(154055, 'esES', '', 'Contagio en propagación.', 28153),
(154054, 'esES', '', 'Niveles víricos en aumento.', 28153),
(154053, 'esES', '', 'Nueva cepa detectada.', 28153),
(154052, 'esES', '', 'Campo quirúrgico iniciado. Preparando muestras de estudio.', 28153),
(154051, 'esES', '', 'Niveles de infección críticos. Purga total iniciada.', 28153),
(154050, 'esES', '', 'Ventilación de cámara de contención.', 28153),
(154049, 'esES', '', 'Probando resistencia bacteriana al calor extremo.', 28153),
(154048, 'esES', '', 'Protocolo de disección iniciado.', 28153),
(154047, 'esES', '', 'Sistema restaurado. Los niveles vuelven a ser seguros.', 28153),
(154046, 'esES', 'No ha sido una operación discreta, pero ha sido eficaz.', '', 28153),
(154045, 'esES', '', 'Esa era la última. ¡Yazma ya no podrá ehpiarnoh!', 28153),
(154044, 'esES', '', 'Yazma tiene ehpíah por doquier. Noh observa a travéh de lah arañah. Aplahtadlah.', 28153),
(154043, 'esES', '', 'Limpieza completada.', 28153),
(154042, 'esES', 'Esta es una misión de rescate: hay que encontrar a los soldados capturados, liberarlos e ir al punto de recogida. Autorizo el uso de fuerza letal. De hecho, lo recomiendo.', '', 28153),
(154041, 'esES', '', 'Nivel de contagio reducido.', 28153),
(154040, 'esES', 'Bien. Ahora el otro equipo podrá liberar a nuestros soldados sin problemas.', '', 28153),
(154039, 'esES', '', 'La hoja de lah Sombrah Razi ya no matará a máh de loh míoh. Graciah.', 28153),
(154038, 'esES', '', 'Infección purgada.', 28153),
(154037, 'esES', 'La misión es simple: crear caos. Tengo a otro equipo preparado para liberar a los guerreros capturados, pero primero hay que encargarse de los guardias. Entra, mata todo lo que veas y sal de ahí.', '', 28153),
(154036, 'esES', '', 'Han vihto a uno de loh asesinoh de confianza de Yazma por la zona. ¡Mucho cuidado!', 28153),
(154035, 'esES', '', 'Cepa virulenta detectada. Neutralización total necesaria.', 28153),
(154034, 'esES', '', 'A ver si así Yazma y su gente aprenden a no jugar con el vudú.', 28153),
(154033, 'esES', '', 'Protocolo de purificación activado.', 28153),
(154032, 'esES', '', '¡El vudú maligno de Yazma ha dado vida a esah máhcarah tiki! Dehtruidlah.', 28153),
(154031, 'esES', '¡Buen trabajo! Ahora la Liga de Expedicionarios podrá investigar el templo en paz.', '', 28153),
(154030, 'esES', '¡Alguien ha matado a los trols Zandalari que había por aquí! La Liga de Expedicionarios no podrá entrar en el templo hasta que descubramos quién ha sido y eliminemos la amenaza.', '', 28153),
(154029, 'esES', '¡Fantástico! Enviaré una expedición al templo de inmediato.', '', 28153),
(154028, 'esES', 'No puedo enviar a nadie al templo con esas máscaras tiki por ahí. ¡Su magia es demasiado fuerte!', '', 28153),
(154027, 'esES', '¡Buen trabajo! Aunque aún noto sus patas por toda mi barba...', '', 28153),
(154026, 'esES', '¡Arañas! ¡Yazma tiene arañas por doquier! Necesitaríamos reducir un poco su número para poder trabajar en paz.', '', 28153),
(154025, 'esES', 'Forjados por la Luz, ¡acabad con los demoledores!', '', 28153),
(154024, 'esES', 'Jinetes de grifos, ¡alzad el vuelo!', '', 28153),
(154023, 'esES', 'Hierro Negro, ¡ahora! ¡Atacadles desde abajo!', '', 28153),
(154022, 'esES', '', 'Tenemos las pruebas, ¡pero se han quedado casi sin gente para llevar a cabo su plan! Buen trabajo.', 28153),
(154021, 'esES', 'Gloria... a la Alianza...', '', 28153),
(154020, 'esES', 'Puede que ahora colabore con los Velaniebla, pero pensar que insultaría mis raíces en la Alianza aliándome con la Horda... ¿Cómo te atreves?', '', 28153),
(154019, 'esES', '', 'Las tripulaciones piratas de Fuerte Libre siempre están tramando algo. Descubre qué es esta vez.', 28153),
(154018, 'esES', 'Gracias a ti, la Séptima Legión tiene una amenaza menos de la que preocuparse.', '', 28153),
(154017, 'esES', '¡Buen combate! ¡Aseguraremos toda la zona para la Alianza de inmediato!', '', 28153),
(154016, 'esES', 'Ha sido todo un desafío, pero lo has superado con valor. ¡Sigue así!', '', 28153),
(154015, 'esES', 'El enemigo ha caído. Es una pena que hayamos tenido que recurrir a la violencia, pero no había otra opción.', '', 28153),
(154014, 'esES', 'Un trabajo excelente. Me habría venido muy bien alguien como tú en la Tercera Guerra.', '', 28153),
(154013, 'esES', '¡Buen combate! Habrías sido muy útil en la Segunda Guerra.', '', 28153),
(154012, 'esES', 'Buen trabajo. ¡Una amenaza menos de la que preocuparnos!', '', 28153),
(154011, 'esES', 'Gracias por prestarnos tu fuerza. ¡Es un honor que ayudes a los devotos!', '', 28153),
(154010, 'esES', '', 'Dales donde más les duele: ¡en la cartera!', 28153),
(154009, 'esES', '', 'Si tuviéramos un libro de contabilidad de la banda, podríamos entorpecer sus operaciones financieras.', 28153),
(154008, 'esES', 'Gracias. Aún no podemos mover a los heridos, pero nos has conseguido un tiempo precioso.', 'Gracias. Aún no podemos mover a los heridos, pero nos has conseguido un tiempo precioso.', 28153),
(154007, 'esES', 'Así, esto detendrá la hemorragia...', 'Así, esto detendrá la hemorragia...', 28153),
(154006, 'esES', 'Sé que duele, pero intenta no moverte...', 'Sé que duele, pero intenta no moverte...', 28153),
(154005, 'esES', '¡Silencio! Nos van a oír...', '¡Silencio! Nos van a oír...', 28153),
(154004, 'esES', '¡Buscad ayuda! ¡Yo veré qué puedo hacer en Uldir para detener la corrupción!', '', 28153),
(154003, 'esES', '', 'Podría reconocer la letra de Owings en cualquier parte. ¡Te mataré, y después a ese traidor!', 28153),
(154002, 'esES', '¡Maldición, se está cerrando la entrada! ¡No puedo dejar escapar esta oportunidad!', '', 28153),
(154001, 'esES', '', '¡Justo donde lo dejé!', 28153),
(154000, 'esES', '', '¡Capitán! Tenemos un motín entre manos...', 28153),
(153999, 'esES', '¿¡Esa cosa acaba de decir \"G\'huun\"!? ¡Hay que seguirla!', '', 28153),
(153997, 'esES', 'Podría estar conectado a Uldir. ¡Corramos a averiguarlo!', '', 28153),
(153996, 'esES', 'Nunca había visto este tipo de corrupción.', '', 28153),
(153995, 'esES', '', 'Oye, $c, ¿te guhtaría aprender un poco de alquimia?$b$bSoy la mejor inhtructora de ehtah tierrah, te lo aseguro.', 28153),
(153994, 'esES', '¡A saber qué secretos esconde! ¡Hasta puede que nos dé la clave para derrotar a los dioses antiguos!', '', 28153),
(153993, 'esES', 'Los titanes construyeron estas instalaciones tras la caída del Imperio Negro para experimentar con todo tipo de bestias.', '', 28153),
(153992, 'esES', '¡Ah! ¡¿Qué tipo de criatura es esta?!', '', 28153),
(153991, 'esES', '¡Estas cuevas deben de llevar a la legendaria Uldir!', '', 28153),
(153990, 'esES', 'Gracias por la ayuda. El desierto es más seguro gracias a tus esfuerzos.', '', 28153),
(153989, 'esES', '', 'No era un objetivo fácil, pero hah luchado bien. ¡Sigue así!', 28153),
(153988, 'esES', '', 'Un problema menoh del que preocuparnoh. ¡Buen trabajo!', 28153),
(153987, 'esES', '', 'Buen trabajo. Le hah dado al enemigo una lección que tardará en olvidar.', 28153),
(153986, 'esES', 'Guíanos.', 'Guíanos.', 28153),
(153985, 'esES', '', 'Esta casa está llena de secretos. Como los pisos superiores están asegurados, puedo enseñarte un camino oculto que lleva al sótano.', 28153),
(153984, 'esES', 'Gracias por ayudarnos. ¡Necesitamos más como tú en Vol\'dun!', '', 28153),
(153983, 'esES', 'Buen trabajo. Ahora el desierto es un poco más seguro gracias a ti.', '', 28153),
(153982, 'esES', 'Un peligro menos del que preocuparnos en Vol\'dun. ¡Bien hecho!', '', 28153),
(153981, 'esES', 'Pero piensa en todo... el oro...', '', 28153),
(153980, 'esES', '¿No ves dónde te estás metiendo? ¡Gobernalle nos dará más poder del que jamás hayamos podido imaginar!', '', 28153),
(153979, 'esES', '¡Nadie dañará a los míos!', '', 28153),
(153978, 'esES', 'Las piedras están... por todas partes... ¡Los mogu... se las quedarán todas!', '', 28153),
(153977, 'esES', '¡Ahí! ¡Atacad!', '', 28153),
(153976, 'esES', '', 'Creo que ya estamos a salvo. Buen trabajo ahí detrás.', 28153),
(153975, 'esES', '¡Con estas piedras, los mogu serán invencibles!', '', 28153),
(153974, 'esES', '¡Por fin das la cara! ¡Desaparece!', '', 28153),
(153973, 'esES', '', 'Parece que tenemos compañía. ¡Ocúpate de ellos!', 28153),
(153972, 'esES', '', '¡Agárrate! Va a ser un viaje movidito.', 28153),
(153971, 'esES', '¡Deja que este viejo lobo te enseñe sus colmillos!', '', 28153),
(153970, 'esES', '¡Te tengo!', '', 28153),
(153969, 'esES', 'Te han crecido agallas, ¿eh? ¡Ja!', '', 28153),
(153968, 'esES', '', 'Me parece que no.', 28153),
(153967, 'esES', '', 'Patético.', 28153),
(153966, 'esES', '', 'No será hoy.', 28153),
(153965, 'esES', 'Mis exploradores informan de que hay un enemigo peligroso cerca. Necesito que lo neutralices.', '', 28153),
(153962, 'esES', 'Un enemigo cercano ha matado a algunos de mis soldados. ¡Venga sus muertes!', '', 28153),
(153959, 'esES', 'La Séptima Legión ha recibido informes de un enemigo poderoso en la zona. ¡Elimínalo!', '', 28153),
(153958, 'esES', 'No hay tesoro... solo ohcuridad.', 'Oro hahta donde alcanza la vihta...', 28153),
(153957, 'esES', 'Quiero ser libre...', 'Soy... ¿libre?', 28153),
(153956, 'esES', 'Tesoro maldito. Oro maldito.', 'Malditoh ladroneh.', 28153),
(153955, 'esES', 'Quiero ser uno con el tesoro.', 'Huesoh de oro...', 28153),
(153954, 'esES', 'Me informan de que hay un peligroso enemigo cerca de ti. Elimínalo, ¡pero cuidado con las sorpresas!', '', 28153),
(153953, 'esES', 'Un peligroso enemigo ha matado a algunos de nuestros exploradores cerca de aquí. ¡Véngalos!', '', 28153),
(153952, 'esES', 'Cuidado, hay una amenaza cerca de aquí. Mantén la calma y acaba con ella antes de que huya.', '', 28153),
(153951, 'esES', 'No ehtá mal, $gjefe:jefa;. Pero si no te guhta puedeh seguir buhcando.', '', 28153),
(153950, 'esES', 'Tengo una poción para cada uno de vosotros. No os la bebáis aún.', '', 28153),
(153949, 'esES', 'Bien. Has conseguido enfurecer de verdad a una ciudad durmiente.\n\nNo perdamos el tiempo buscando culpables, ¿de acuerdo?', '', 28153),
(153948, 'esES', 'Esa historia ya la he oído antes. (Omitir la gesta y teletransportarse al Puerto de Zuldazar en Zandalar)', 'Esa historia ya la he oído antes. (Omitir la gesta y teletransportarse al Puerto de Zuldazar en Zandalar)', 28153),
(153947, 'esES', 'Que esto sirva de mensaje para tus maestros. ¡El Despertar de la Tormenta nunca se rinde!', '', 28153),
(153946, 'esES', 'Que no controle tu mente. ¡Sé fuerte!', '', 28153),
(153945, 'esES', '', 'Todo este sufrimiento... La culpa es tuya, ¡MONSTRUO!', 28153),
(153944, 'esES', '¡Yo os protegeré!', '', 28153),
(153943, 'esES', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far.', '', 28153),
(153942, 'esES', 'Oro. Oro. Oro.', 'Máh tesoro pa la pila.', 28153),
(153941, 'esES', 'No hay luz. Ni escapatoria. El rey olvidado regresa.', '', 28153),
(153940, 'esES', 'No hay tripulación aquí...', 'Corre...', 28153),
(153939, 'esES', 'Todo el tesoro pa Zem\'lan.', 'El tesoro eh pa Zem\'lan.', 28153),
(153938, 'esES', 'Creo que eh hora de presentaroh. Contramaehtre Owings, $n. $n, Owings. Ahora vamoh al grano, ¿vale?', '', 28153),
(153937, 'esES', '', 'Ya advertí a Kiro de que los sethrak vendrían a por nosotros pronto. Podríamos habernos preparado... Quizás ahora nos escuche.', 28153),
(153936, 'esES', '', 'No estábamos preparados para su ataque. Los sethrak matan y esclavizan sin remordimientos.', 28153),
(153935, 'esES', 'Oro...', 'Qué brillante...', 28153),
(153934, 'esES', 'Una peligrosa amenaza acecha en los alrededores. Destrúyela antes de que se cobre más vidas inocentes.', '', 28153),
(153933, 'esES', 'Aquí atacaron a algunos de nuestros aliados. Debes eliminar la amenaza inmediatamente.', '', 28153),
(153930, 'esES', 'Hay una criatura peligrosa en los alrededores. Mátala antes de que haga daño a más inocentes.', '', 28153),
(153929, 'esES', '', 'Me han informado de que hay una amenaza cerca de aquí. ¡Elimínala cuanto anteh!', 28153),
(153928, 'esES', '', 'Algunoh aliadoh sufrieron un ataque cerca de aquí. ¡Elimina la amenaza anteh de que vuelva a ocurrir!', 28153),
(153927, 'esES', '', 'Algo muy peligroso acecha aquí. Mátalo anteh de que acabe contigo.', 28153),
(153926, 'esES', 'Me han informado de que hay una peligrosa criatura en esta zona. Necesito que acabes con ella cuanto antes.', '', 28153),
(153925, 'esES', '¡A mí, rápido!', '', 28153),
(153924, 'esES', 'Una de nuestras caravanas sufrió un ataque cerca de aquí. ¡Elimina la amenaza antes de que ocurra de nuevo!', '', 28153),
(153923, 'esES', 'Sé que eh humana, pero intenta ser $gcomprensivo:comprensiva;.', '', 28153),
(153922, 'esES', 'Nuehtro objetivo eh simple. Contribuiremoh al éxito de su motín, tenemoh permiso pa apohtarnoh aquí y preparar nuehtro ataque.', '', 28153),
(153921, 'esES', 'Owings no quiere renunciar a su libertad como el rehto de piratah.', '', 28153),
(153920, 'esES', 'Hay una criatura muy peligrosa en los alrededores. ¡Necesito que acabes con ella de que sea demasiado tarde!', '', 28153),
(153919, 'esES', 'He recibido noticiah de nuehtro contacto mientrah ehploraba Tiragarde en buhca de puntoh de desembarco.', '', 28153),
(153918, 'esES', '¡Saludoh, colega pirata!', '', 28153),
(153917, 'esES', 'El reino sumergido da la bienvenida a vuestras almas cansadas.', '', 28153),
(153916, 'esES', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma.', '', 28153),
(153915, 'esES', 'Está perdido. Tan solo queda oscuridad.', '', 28153),
(153914, 'esES', '', 'Sam, sé que estás ahí. ¡Tienes que resistirte!', 28153),
(153913, 'esES', 'No hay criatura capaz de hacerte frente, ¿eh?', '', 28153),
(153912, 'esES', '', '¡Excelente! El camino está despejado.', 28153),
(153911, 'esES', 'No era más que una réplica. No volvamos a mencionarlo.', '', 28153),
(153910, 'esES', '', '¡Perfecto! Nos la llevaremos y veremos qué oculta.', 28153),
(153909, 'esES', 'Esto valdrá. La Jefa de Guerra te lo agradece.', '', 28153),
(153908, 'esES', '', '¡Fantástico! Esto ayudará a la campaña.', 28153),
(153907, 'esES', 'De acuerdo, $gjefe:jefa;. Vamoh a reunirnoh con la contramaehtre. Actúa como un pirata.', '', 28153),
(153906, 'esES', 'Me queda bien, ¿eh? ¡Arrrgh!', '', 28153),
(153905, 'esES', 'Una bestia beligerante bloquea nuestra salida de esta prisión. Hay que matarla.', '', 28153),
(153904, 'esES', '', 'Una bestia poderosa nos impide controlar del todo una posición en esta playa. Necesitamos encargarnos de ella para despejar una vía de escape.', 28153),
(153903, 'esES', 'Déjame ponerme el dihfraz, $gjefe:jefa;.', '', 28153),
(153902, 'esES', 'Nuestros maestros de espías dicen que El orgullo de Kul Tiras ha atracado en Tol Dagor. Si es cierto, debes robar ese barco para nosotros.', '', 28153),
(153901, 'esES', '', 'El Sobrestante tiene una reliquia escondida en una maqueta de barco. Me gustaría que la recuperases.', 28153),
(153900, 'esES', 'La maquinaria de guerra de la Horda requiere armas y armaduras. Coge lo que puedas mientras estés allí y vuelve a verme.', '', 28153),
(153899, 'esES', '', 'Con todo el caos, debe de quedar algún cargamento sin reclamar por ahí. Veamos si podemos llevarnos unos cajones de suministros sin que se enteren.', 28153),
(153898, 'esES', 'Mataron a tu padre... Traicionaron a tu Rey... ¡Y no hiciste nada! ¿Sacrificarás a todos tus aliados en favor de la Horda?', '', 28153),
(153897, 'esES', 'En la Horda no hay más que monstruos. ¡Claro que te traicionaron!', '', 28153),
(153896, 'esES', '¡Preferiste a unos perros sarnosos en vez de a tu propia sangre!', '', 28153),
(153895, 'esES', 'Te quedaste mirando mientras esos animales me mataban. ¿De qué te ha valido tu traición?', '', 28153),
(153894, 'esES', 'Se acerca un gran número de trols Secacorteza a Stromgarde por el este. ¿Y si espantamos a unos cuantos? Pero solo a unos cuantos, al resto los matamos.', '', 28153),
(153893, 'esES', 'No quemeh ehte. Lo usaremoh pa salir de la ihla.', '', 28153),
(153892, 'esES', 'Han derribado a varios jinetes de grifos. Mantened los ojos abiertos por si hay supervivientes.', '', 28153),
(153891, 'esES', '', '¡Por fin lo veh! ¡Por fin lo entiendeh! ¡G\'huun oh conquihtará a todoh!', 28153),
(153890, 'esES', '', 'Si liberan a esa cosa, ¡será el fin de Zuldazar!', 28153),
(153889, 'esES', '', 'Sabía que loh trolh de sangre eran una amenaza, pero jamáh imaginé ehto...', 28153),
(153888, 'esES', '¿Quién eres?', '¿Quién eres?', 28153),
(153886, 'esES', '$gBienvenido:Bienvenida;, $n. Tus heroicas hazañas como $gcampeón:campeona; de Azeroth son bien conocidas entre nosotros.', '$gBienvenido:Bienvenida;, $n. Tus heroicas hazañas como $gcampeón:campeona; de Azeroth son bien conocidas entre nosotros.', 28153),
(153885, 'esES', '¡Malditas abominaciones! ¡Que vuelvan al abismo!', '', 28153),
(153884, 'esES', 'Temo que los cultores de la casa Canto Tormenta estén tratando de extender su influencia por Boralus. ¡Desenmascáralos!', '', 28153),
(153883, 'esES', '', 'Los rumores eran ciertos... Al menos ahora las calles son un poco más seguras.', 28153),
(153882, 'esES', '¡Venid, hermanos y hermanas! ¡Resistiremos juntos!', '', 28153),
(153881, 'esES', 'No os paréis. ¡La oscuridad invade su mente!', '', 28153),
(153880, 'esES', '', 'Aguanta, Sam. ¡Casi hemos llegado!', 28153),
(153879, 'esES', '¡MAREAS DE SANGRE! ¡CRECED! ¡CRECED!', '', 28153),
(153878, 'esES', '', 'Se rumorea que la guardia de Boralus trabaja para la banda. ¿Puedes investigarlo?', 28153),
(153877, 'esES', '¡Menos mal! Eso los mantendrá ocupados durante... eeh... ¿cinco minutos?', '', 28153),
(153876, 'esES', '¡Ah! ¡Estos pájaros están descontrolados! Hay que darles comida o algo, ¡rápido!', '', 28153),
(153875, 'esES', 'Vale, ninguna de estas carteras es mía, pero... las guardaré hasta que encontremos a sus dueños.', '', 28153),
(153874, 'esES', '¿Eh? ¿Dónde está mi cartera? ¡Un momento! ¡¿Me acaba de robar un mocoso?! ¡Que no escape!', '', 28153),
(153873, 'esES', '', 'Espero que los otros estén a salvo.', 28153),
(153872, 'esES', '', 'Los vulperas somos sencillos, viajamos en caravanas, recogemos suministros y comerciamos donde podemos.', 28153),
(153871, 'esES', 'Lo has conseguido, $p. ¡Ai\'twen se está despertando!', '', 28153),
(153870, 'esES', '', 'Mira lo que le han hecho los sethrak a nuestro hogar...', 28153),
(153869, 'esES', '', 'Buena elección. Con eso me apañaré.', 28153),
(153868, 'esES', 'Unos ogros Puño de Roca pretenden atacar Stromgarde. Enseñémosles lo que fue del último grupo de matones con barriga cervecera que vino a buscar pelea. ', '', 28153),
(153867, 'esES', 'Paciencia, Taelia. Lo harán.', '', 28153),
(153866, 'esES', '', '¿El resto del Despertar de la Tormenta llegará a tiempo?', 28153),
(153865, 'esES', 'Igual ofrecen una recompensa a quien devuelva a los granujas a su aldea, en el lago del suroeste. Pero mejor evitar el agua... Es la letrina de los renacuajos.', '', 28153),
(153864, 'esES', 'Parece que hay un grupo de renacuajos múrlocs correteando por ahí.', '', 28153),
(153863, 'esES', 'Los exploradores nos han informado de que han robado un vagón de minerales cerca de la mina del noreste. Vamos a recuperarlo a la fuerza.', '', 28153),
(153862, 'esES', 'Han visto a leñadores de la Horda desprotegidos. Seamos buenos vecinos y vayamos a darles leña.', '', 28153),
(153861, 'esES', 'Recordad que la madera consciente y agresiva no deja de ser madera... Un montón de madera en este caso.', '', 28153),
(153860, 'esES', 'Han visto al señor de las ramas Aldrus por la linde del bosque.', '', 28153),
(153859, 'esES', 'El gigante de piedra Fozruk anda por los caminos del sudeste. Mirad hacia arriba si no queréis que os aplaste.', '', 28153),
(153858, 'esES', '¿Por qué no lo \"invitamos\" a que vaya a atacar el frente de la Horda?', '', 28153),
(153857, 'esES', 'Han visto a un elemental de tierra gigante en la colina del este.', '', 28153),
(153856, 'esES', 'Valientes soldados de la Liga, es la hora.', '', 28153),
(153855, 'esES', '¡Cruzados, marchad hacia Ar\'gorok! ¡Es la voluntad de la Luz!', '', 28153),
(153854, 'esES', 'La Horda intenta tomar la Mina de Galson. Dejaos caer por allí y minadles el espíritu.', '', 28153),
(153853, 'esES', 'La Horda ataca a nuestros aliados en el Aserradero de las Tierras Altas. Convencedlos de que son alérgicos al serrín.', '', 28153),
(153852, 'esES', 'Las fuerzas de la Horda han entrado en Stromgarde. Proteged a vuestro comandante y mostradles la salida, ¿de acuerdo?', '', 28153),
(153851, 'esES', 'Atacan Nido Alto. Sugiero mandar a la Horda de vuelta colina abajo rodando.', '', 28153),
(153850, 'esES', '', '¡Empezamos cuando tú digas!', 28153),
(153849, 'esES', '', 'La Jefa de Guerra espera que todos los héroes de la Horda estén preparados. Deberíamos aprovechar para entrenar un poco.', 28153),
(153848, 'esES', '', '¡Saludos! Nuestro deber en Silithus consiste en proteger nuestra operación de azerita de la Alianza.', 28153),
(153847, 'esES', 'Se retuercen... Susurran...', '', 28153),
(153846, 'esES', 'Avísame cuando quieras empezar.', '', 28153),
(153845, 'esES', 'Aprovechemos para pulir tus técnicas de combate mientras patrullamos Silithus.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'esES', '¡Te doy la bienvenida! El rey Wrynn necesita a todos los héroes de la Alianza en forma para cuando nos enfrentemos a la Horda.', '', 28153),
(153843, 'esES', 'Ve con cuidado. Este sitio se ha ganado el nombre.', '', 28153),
(153842, 'esES', '', '¡Impresionante! Ahora veremos... Un momento, ¿eso es...? ¡A las armas! ¡Nos ataca la Alianza!', 28153),
(153841, 'esES', 'Sube la marea... No hay escapatoria...', '', 28153),
(153840, 'esES', '¡Proteged el bancal! Debemos ganar tiempo para que Zul pueda aplastar a estas patéticas criaturas.', '', 28153),
(153839, 'esES', 'Las fuerzas de la Horda se acercan al Círculo de los Elementos. ¿Por qué no les damos una lección de magia?', '', 28153),
(153838, 'esES', '', '¡Por mi padre!', 28153),
(153837, 'esES', '', '¡No tendré piedad!', 28153),
(153836, 'esES', '¡Bien hecho! Ahora veremos... Un momento, ¿eso es...? ¡A las armas! ¡Nos ataca la Horda!', '', 28153),
(153835, 'esES', '', '¡Ha llegado tu hora!', 28153),
(153834, 'esES', '', '¡Por Kul Tiras!', 28153),
(153833, 'esES', 'La Horda nos ataca en el Cruce Redilnorte. Se merecen que les agradezcamos su hospitalidad.', '', 28153),
(153832, 'esES', '', 'Metamorfosis te transforma en un demonio y potencia tu Golpe de caos y tu Danza de hojas.', 28153),
(153831, 'esES', '', '¡Estamos contigo!', 28153),
(153830, 'esES', 'La Horda avanza por la Senda del Valor. Los tenemos a las puertas. Id a darles la bienvenida.', '', 28153),
(153829, 'esES', 'Metamorfosis te transforma en un demonio y potencia tu Golpe de caos y tu Danza de hojas.', '', 28153),
(153828, 'esES', 'La Horda ataca Finca Nueva. Será mejor que vayamos a pararles los pies.', '', 28153),
(153827, 'esES', '', 'Danza de hojas es un aluvión de ataques rápidos que golpea a todos los enemigos cercanos.', 28153),
(153826, 'esES', 'Danza de hojas es un aluvión de ataques rápidos que golpea a todos los enemigos cercanos.', '', 28153),
(153825, 'esES', '', 'Consume muchos recursos, pero es tu ataque más potente y deberías usarlo siempre que puedas.', 28153),
(153824, 'esES', 'Consume muchos recursos, pero es tu ataque más potente y deberías usarlo siempre que puedas.', '', 28153),
(153823, 'esES', '', 'Haz ocular abrasa a tus enemigos con el caos demoníaco que arde en ti.', 28153),
(153822, 'esES', 'Haz ocular abrasa a tus enemigos con el caos demoníaco que arde en ti.', '', 28153),
(153821, 'esES', '', 'Este es uno de tus ataques más potentes. Úsalo a menudo para no malgastar furia.', 28153),
(153820, 'esES', 'Este es uno de tus ataques más potentes. Úsalo a menudo para no malgastar furia.', '', 28153),
(153819, 'esES', '¡Pensaba ir a buscar ayuda y has aparecido! Me has ahorrado el viaje.', '', 28153),
(153818, 'esES', 'Vienen soldados de la Horda. Haced todo lo posible por cerrarles el paso.', '', 28153),
(153817, 'esES', '', 'Usa Abrumar contra el muñeco-diana.', 28153),
(153816, 'esES', 'Usa Abrumar contra el muñeco-diana.', '', 28153),
(153815, 'esES', 'Parece que les hemos dado donde más les duele. La Horda está enviando a todo su ejército.', '', 28153),
(153814, 'esES', '', 'Este ataque devastador también potencia tu siguiente Golpe mortal; úsalo siempre que puedas.', 28153),
(153813, 'esES', 'Este ataque devastador también potencia tu siguiente Golpe mortal; úsalo siempre que puedas.', '', 28153),
(153812, 'esES', '', 'Abrumar usa tu fuerza imparable para asestar un golpe crítico a tu enemigo.', 28153),
(153811, 'esES', 'Abrumar usa tu fuerza imparable para asestar un golpe devastador a tu enemigo.', '', 28153),
(153810, 'esES', '', 'Has recibido daño, pero eso no es problema para ti.', 28153),
(153809, 'esES', 'Has recibido daño, pero eso no es problema para ti.', '', 28153),
(153804, 'esES', 'Usa Drenar vida para recuperar toda tu salud.', '', 28153),
(153803, 'esES', '', 'Usa Drenar vida para recuperar toda tu salud.', 28153),
(153802, 'esES', '', 'Drenar vida consume la energía vital de tu enemigo, lo que le inflige daño y te sana.', 28153),
(153801, 'esES', 'Drenar vida consume la energía vital de tu enemigo, lo que le inflige daño y te sana.', '', 28153),
(153798, 'esES', '', 'Usa Descarga de las Sombras contra el muñeco-diana.', 28153),
(153797, 'esES', 'Usa Descarga de las Sombras contra el muñeco-diana.', '', 28153),
(153796, 'esES', '', 'Lanza Descarga de las Sombras cuando a tu víctima ya le afecten otros hechizos.', 28153),
(153795, 'esES', 'Lanza Descarga de las Sombras cuando a tu víctima ya le afecten otros hechizos.', '', 28153),
(153794, 'esES', '', 'Tras usar Agonía y Corrupción contra tu objetivo, continúa atacando con la siniestra magia de las Sombras.', 28153),
(153793, 'esES', 'Tras usar Agonía y Corrupción contra tu objetivo, continúa atacando con la siniestra magia de las Sombras.', '', 28153),
(153792, 'esES', 'Que lah sombrah te consuman.', '', 28153),
(153791, 'esES', '', 'Usar Frenesí temible también reducirá el tiempo necesario para lanzar Cólera de las bestias de nuevo.', 28153),
(153790, 'esES', 'Usar Frenesí temible también reducirá el tiempo necesario para lanzar Cólera de las bestias de nuevo.', '', 28153),
(153789, 'esES', '', '¡No vamos a tolerar tus acciones!', 28153),
(153788, 'esES', '', 'Usa Frenesí temible para atacar al muñeco-diana.', 28153),
(153787, 'esES', 'Usa Frenesí temible para atacar al muñeco-diana.', '', 28153),
(153786, 'esES', '', 'Frenesí temible hace enfurecer a tu mascota, lo que te permite centrarte en otras facultades.', 28153),
(153785, 'esES', 'Frenesí temible hace enfurecer a tu mascota, lo que te permite centrarte en otras facultades.', '', 28153),
(153784, 'esES', '', 'También le puedes ordenar a tu mascota que lance un aluvión de ataques salvajes.', 28153),
(153783, 'esES', 'También le puedes ordenar a tu mascota que lance un aluvión de ataques salvajes.', '', 28153),
(153782, 'esES', '', 'Usa Bomba de fuego salvaje para acabar con todos los enemigos.', 28153),
(153781, 'esES', 'Usa Bomba de fuego salvaje para acabar con todos los enemigos.', '', 28153),
(153780, 'esES', '', 'Son más eficientes contra grupos, ya que el fuego salvaje alcanza a todos los enemigos en un cono detrás de tu objetivo.', 28153),
(153779, 'esES', 'Son más eficientes contra grupos, ya que el fuego salvaje alcanza a todos los enemigos en un cono detrás de tu objetivo.', '', 28153),
(153778, 'esES', '', 'También cuentas con Bomba de fuego salvaje. Estas bombas prenden fuego a tu enemigo y lo queman en el tiempo.', 28153),
(153777, 'esES', 'También cuentas con Bomba de fuego salvaje. Estas bombas prenden fuego a tu enemigo y lo queman en el tiempo.', '', 28153),
(153776, 'esES', '', 'Usa Picadura de serpiente contra el muñeco-diana.', 28153),
(153775, 'esES', 'Usa Picadura de serpiente contra el muñeco-diana.', '', 28153),
(153774, 'esES', '', 'Picadura de serpiente dispara una flecha venenosa que inflige daño de Naturaleza en el tiempo.', 28153),
(153773, 'esES', 'Picadura de serpiente dispara una flecha venenosa que inflige daño de Naturaleza en el tiempo.', '', 28153),
(153772, 'esES', '', 'Tus habilidades de supervivencia te otorgan potentes recursos para dañar a tus enemigos.', 28153),
(153771, 'esES', 'Tus habilidades de supervivencia te otorgan potentes recursos para dañar a tus enemigos.', '', 28153),
(153770, 'esES', 'Esa serpiente...', '', 28153),
(153769, 'esES', '¡Que los vientos te sean favorables!', '¡Que los vientos te sean favorables!', 28153),
(153768, 'esES', '¡No te acerques a las sirenas!', '¡No te acerques a las sirenas!', 28153),
(153767, 'esES', '¡Mi loa brama! ¡La herejía de Zul no tiene límiteh!', '', 28153),
(153766, 'esES', '¡Abrígate!', '¡Abrígate!', 28153),
(153765, 'esES', 'Recupera mi barco e iremoh a ocuparnoh de loh usurpadoreh que han intentado robarme el trono.', '', 28153),
(153764, 'esES', '¡Levando anclas!', '¡Levando anclas!', 28153),
(153763, 'esES', '¡Adiós!', '¡Adiós!', 28153),
(153762, 'esES', 'Los peces son raros.', 'Los peces son raros.', 28153),
(153761, 'esES', '¿Tienes escorbuto?', '¿Tienes escorbuto?', 28153),
(153759, 'esES', 'He cumplido... con mi parte...', '', 28153),
(153758, 'esES', 'Me gustan los tortolianos.', 'Me gustan los tortolianos.', 28153),
(153757, 'esES', '¿Por dónde dices que queda estribor?', '¿Por dónde dices que queda estribor?', 28153),
(153756, 'esES', '¡Aaarr! ¿Ha sonado pirata?', '¡Aaarr! ¿Ha sonado pirata?', 28153),
(153755, 'esES', '¡Ah del barco!', '¡Ah del barco!', 28153),
(153754, 'esES', '', 'Usa Matar varias veces contra el muñeco-diana.', 28153),
(153753, 'esES', 'Usa Matar varias veces contra el muñeco-diana.', '', 28153),
(153752, 'esES', '', 'Matar ordena a tu mascota lanzar un poderoso ataque y genera enfoque, que puedes usar para otras facultades.', 28153),
(153751, 'esES', 'Matar ordena a tu mascota lanzar un poderoso ataque y genera enfoque, que puedes usar para otras facultades.', '', 28153),
(153750, 'esES', 'Papá dice que soy un marinero de agua dulce, pero mamá dice que soy muy salado.', 'Papá dice que soy una marinera de agua dulce, pero mamá dice que soy muy salada.', 28153),
(153749, 'esES', '', 'Ahora que has acortado la distancia entre tu presa y tú, es hora de desatar tu furia.', 28153),
(153748, 'esES', 'Ahora que has acortado la distancia entre tu presa y tú, es hora de desatar tu furia.', '', 28153),
(153747, 'esES', 'Tengo... mucho frío...', 'Tengo... mucho frío...', 28153),
(153746, 'esES', '¡Este no es tu sitio!', '¡Este no es tu sitio!', 28153),
(153745, 'esES', 'Ciertamente. Adalid, ve a Kezan. Consigue las técnicas de refinado de azerita que nos prometieron... Y haz que Mogul Razdunk sufra por traicionar a la Dama Oscura.', '', 28153),
(153744, 'esES', 'Este acuerdo nos ha traído más problemas que beneficios. Es más fácil conseguir lo que queremos... si nos saltamos al intermediario, no sé si me entiendes.', '', 28153),
(153743, 'esES', 'La Jefa de Guerra no estará contenta. Contábamos con el refinado de azerita de Razdunk en nuestra guerra contra la Alianza.', '', 28153),
(153742, 'esES', 'Uuusted perdone, príncipe alma en pena. Lo siento si me afecta que casi me maten... ¡por un acuerdo al que siempre me opuse!', '', 28153),
(153741, 'esES', 'Cálmate, príncipe mercante. Esos balbuceos no son dignos de un líder de la Horda.', '', 28153),
(153740, 'esES', '¡Mogul Razdunk nos ha traicionado! ¡Una locura! Nunca he visto a esa rata verde echarse atrás de un acuerdo así. Es increí...', '', 28153),
(153739, 'esES', 'Señor Clamañublo, traigo malas noticias...', '', 28153),
(153738, 'esES', '', '¡Trolh de sangre... obtened máh... poder!', 28153),
(153737, 'esES', '', '¡Poder! ¡PODER!', 28153),
(153736, 'esES', 'Ai\'twen ha estado descansando, acumulando fuerzas para cuando fuera necesario.', '', 28153),
(153735, 'esES', 'Teletransporte a G\'huun.', 'Teletransporte a G\'huun.', 28153),
(153734, 'esES', 'Teletransporte a Mythrax.', 'Teletransporte a Mythrax.', 28153),
(153733, 'esES', 'Teletransporte al Descenso de la Ruina.', 'Teletransporte al Descenso de la Ruina.', 28153),
(153732, 'esES', 'Teletransporte a la entrada de Uldir.', 'Teletransporte a la entrada de Uldir.', 28153),
(153731, 'esES', 'La plataforma de desplazamiento parece estar activa y estable.', 'La plataforma de desplazamiento parece estar activa y estable.', 28153),
(153730, 'esES', '¡Otro día, otra victoria!', '', 28153),
(153729, 'esES', '¡Mis guardias me informan de que los troggs parecen estar preparando otro ataque! ¡Detenlos antes de que sea tarde!', '', 28153),
(153728, 'esES', '¿Ya está? Bien. Cuantos menos animales enloquecidos que puedan comerme vivo haya, mejor.', '', 28153),
(153727, 'esES', '¿Osos embrujados...? ¡Ni hablar! De ninguna manera. Por favor... deshazte de ellos.', '', 28153),
(153726, 'esES', '', 'Llámame loca, pero no me gustan los árboles que andan.', 28153),
(153725, 'esES', '', 'Parece que vuelve a haber lío en las tierras de Algerson. ¡Ve a echar una mano!', 28153),
(153724, 'esES', '¡Estupendo! Tu amigo peludo y tú hacéis muy buen equipo.', '', 28153),
(153723, 'esES', 'Níquel ladra porque quiere salir a cazar halcones. ¿Por qué no te lo llevas a que haga algo de ejercicio?', '', 28153),
(153722, 'esES', 'Ah, una caza impresionante, como siempre. ¡Enhorabuena!', '', 28153),
(153721, 'esES', 'Un nuevo día, ¡y una nueva caza! Veamos qué puedes abatir esta vez...', '', 28153),
(153720, 'esES', 'Últimamente han pasado muchah cosah en la ciudad. Eh mejor ehtar en el agua. Se ehtá bien aquí.', '', 28153),
(153719, 'esES', 'Loh nagah vinieron hace unoh añoh. Suh moleh arrasaron el templo.', '', 28153),
(153718, 'esES', 'Lo que ocurrió en Atal\'Gral eh una pena.', '', 28153),
(153717, 'esES', 'Sigo mirando debajo del barco por lah nocheh. Parece que esoh nagah ehtán por todah parteh.', '', 28153),
(153716, 'esES', 'Atal\'Gral', 'Atal\'Gral', 28153),
(153715, 'esES', 'Puerto de Zuldazar', 'Puerto de Zuldazar', 28153),
(153714, 'esES', '', 'Gral se acercó demasiado.', 28153),
(153713, 'esES', '', 'Ve a Atal\'Gral. Espero que el templo siga en pie.', 28153),
(153712, 'esES', 'Con tu ayuda, algún día recuperaremos Puntamuelle.', '', 28153),
(153711, 'esES', 'El fuerte de Guardiaprofunda en Puntamuelle aún resiste. ¡Hagamos todo lo posible para restablecer la normalidad en el muelle!', '', 28153),
(153710, 'esES', 'Ahora el agua está en calma. Has mitigado su dolor, y yo te lo agradezco.', '', 28153),
(153709, 'esES', 'Hace falta ayuda para limpiar la corrupción de la bahía. ¡Purga las aguas de las criaturas infectadas!', '', 28153),
(153708, 'esES', 'Gracias. ¡Llevaré esto a la avanzada de inmediato!', '', 28153),
(153707, 'esES', 'Rosaline necesita más aguijones. ¿Te importaría echar una mano?', '', 28153),
(153706, 'esES', '¡Excelente! Esto debería servir para darle confianza a Mallo durante un tiempo.', '', 28153),
(153705, 'esES', 'Nuestro colega quelonio Mallo ha estado practicando como jinete, pero necesita ayuda de vez en cuando. ¿Te importaría conseguir un poco de su bebida favorita?', '', 28153),
(153704, 'esES', '', 'Espero que esos contrabandistas hayan aprendido la lección. ¡Robar no compensa!', 28153),
(153703, 'esES', '', 'Estos contrabandistas creen que pueden salir de Boralus con las armas de nuestra milicia. ¡Demuéstrales que se equivocan!', 28153),
(153702, 'esES', '¡Niños, poneos a salvo! ¡Rápido!', '¡Niños, poneos a salvo! ¡Rápido!', 28153),
(153701, 'esES', 'No os preocupéis. Yo os protejo.', 'No os preocupéis. Yo os protejo.', 28153),
(153700, 'esES', '¡Rápido! ¡Por aquí!', '¡Rápido! ¡Por aquí!', 28153),
(153699, 'esES', 'Muy bien, ya nos encargamos nosotros del resto. Oye, ¡todos han conservado los dos ojos! ¡Bien hecho!', '', 28153),
(153698, 'esES', '¡Los mares de Kul Tiras os engullirán a todos!', '¡Los mares de Kul Tiras os engullirán a todos!', 28153),
(153697, 'esES', 'Adelante. Mi familia está a salvo.', 'Adelante. Mi familia está a salvo.', 28153),
(153696, 'esES', '¡Pagaréis por esto!', '¡Pagaréis por esto!', 28153),
(153695, 'esES', '¡Salvajes!', '¡Salvajes!', 28153),
(153694, 'esES', '¡Los pájaros han invadido la zona! Deberías evacuar a los civiles antes de que las gaviotas les arranquen los ojos. ¡Pero no les digas que he dicho eso!', '', 28153),
(153693, 'esES', '¡Auxilio! ¡Que alguien nos salve!', '¡Auxilio! ¡Que alguien nos salve!', 28153),
(153692, 'esES', 'Así no...', 'Así no...', 28153),
(153691, 'esES', '¡Tengo miedo!', '¡Tengo miedo!', 28153),
(153690, 'esES', 'Pero... mis papás...', 'Pero... mis papás...', 28153),
(153689, 'esES', '¿Nos vamos a morir?', '¿Nos vamos a morir?', 28153),
(153688, 'esES', '¿Por qué no te mueves? Tengo miedo...', '¿Por qué no te mueves? Tengo miedo...', 28153),
(153687, 'esES', '¡Despierta! Por favor...', '¡Despierta! Por favor...', 28153),
(153686, 'esES', '¡PAPÁ!', '¡PAPI!', 28153),
(153685, 'esES', '¡MAMÁ!', '¡MAMI!', 28153),
(153684, 'esES', '¡Ten cuidado ahí fuera! ¡Que el viento te sea favorable, $gviajero:viajera;!', '', 28153),
(153683, 'esES', '', 'Los pergaminos anunciaron que llegarías hoy.', 28153),
(153682, 'esES', 'Aaah, sí. Ya ha quedado clara su utilidad.', '', 28153),
(153681, 'esES', 'Necesito reparar.', 'Necesito reparar.', 28153),
(153680, 'esES', '', 'Procura descansar. No le servirás de nada a la Alianza si estás $gagotado:agotada;.', 28153),
(153679, 'esES', '¡La Horda controla el Círculo de los Elementos!', '¡La Horda controla el Círculo de los Elementos!', 28153),
(153678, 'esES', '¡$n ha capturado el Círculo de los Elementos!', '¡$n ha capturado el Círculo de los Elementos!', 28153),
(153677, 'esES', '¡La Horda controla la Mina de Galson!', '¡La Horda controla la Mina de Galson!', 28153),
(153676, 'esES', '¡$n ha capturado la Mina de Galson!', '¡$n ha capturado la Mina de Galson!', 28153),
(153675, 'esES', '¡La Horda controla el Cruce Redilnorte!', '¡La Horda controla el Cruce Redilnorte!', 28153),
(153674, 'esES', '¡$n ha capturado el Cruce Redilnorte!', '¡$n ha capturado el Cruce Redilnorte!', 28153),
(153673, 'esES', '¡La Horda controla Nido Alto!', '¡La Horda controla Nido Alto!', 28153),
(153672, 'esES', '¡$n ha capturado Nido Alto!', '¡$n ha capturado Nido Alto!', 28153),
(153671, 'esES', '¡La Horda controla Finca Nueva!', '¡La Horda controla Finca Nueva!', 28153),
(153670, 'esES', '¡$n ha capturado Finca Nueva!', '¡$n ha capturado Finca Nueva!', 28153),
(153669, 'esES', '¡La Horda tiene el control del Aserradero de las Tierras Altas!', '¡La Horda tiene el control del Aserradero de las Tierras Altas!', 28153),
(153668, 'esES', '¡$n ha capturado el Aserradero de las Tierras Altas!', '¡$n ha capturado el Aserradero de las Tierras Altas!', 28153),
(153667, 'esES', '¡La Horda controla la Senda del Valor!', '¡La Horda controla la Senda del Valor!', 28153),
(153666, 'esES', '¡$n ha capturado la Senda del Valor!', '¡$n ha capturado la Senda del Valor!', 28153),
(153665, 'esES', 'Nuestras hazañas pasarán a la posteridad de la historia militar.', '', 28153),
(153664, 'esES', 'Nuestra brillante estrategia e impecable ejecución han confundido al enemigo.', '', 28153),
(153663, 'esES', 'Creo que los hemos pillado con los pantalones bajados.', '', 28153),
(153662, 'esES', '', 'Victoria no ha sobrevivido...', 28153),
(153661, 'esES', '', '¡Atención todos! ¡Seguid a Nathanos al patio! ¡Yo les bloquearé la retaguardia!', 28153),
(153660, 'esES', '¡Soldados! ¡En posición! ¡Se acerca la Alianza!', '', 28153),
(153659, 'esES', '', 'Los Zandalari no son conscientes del horror que se cierne sobre ellos. Debemos avisarlos.', 28153),
(153658, 'esES', '', 'La reina Azshara planea algo, y no está sola.', 28153),
(153657, 'esES', '', '¡Vaya! Es horrible. ¡Son órdenes de matar a los leales a Gral!', 28153),
(153656, 'esES', '¡Los superaremos 10 a 1 en campo abierto!', '', 28153),
(153655, 'esES', 'No me hagah volver al gólem...', 'Libera mi ehpíritu. Por favor...', 28153),
(153654, 'esES', 'Vamoh a por ti, Zak\'rajan...', 'Ereh el siguiente, Zak\'rajan...', 28153),
(153653, 'esES', '¿Paz... al fin...?', 'Por fin... Déjame dehcansar...', 28153),
(153652, 'esES', 'Bwonsamdi no me dejará morir...', '¿Dónde ehtá el otro lado?', 28153),
(153651, 'esES', '¡Los animales salvajes han devorado al pimpollo!', '¡Los animales salvajes han devorado al pimpollo!', 28153),
(153650, 'esES', '¡WAAAAAUUUGH!', '', 28153),
(153649, 'esES', '¡La Horda no debe escapar bajo ningún concepto!', '', 28153),
(153648, 'esES', '¡Guardias! ¡Nos atacan! ¡A vuestros puestos! ¡Bloquead las salidas!', '', 28153),
(153647, 'esES', 'Genial. ¡Vamos a dar una vuelta!', '', 28153),
(153646, 'esES', 'Claro.', 'Claro.', 28153),
(153645, 'esES', 'Las brujas torturaron y asesinaron a todos vuestros amigos.', 'Las brujas torturaron y asesinaron a todos vuestros amigos.', 28153),
(153644, 'esES', '¡Ay, qué fastidio! Eso no es bueno.\n\nTengo buenas noticias: ya casi he terminado de establecer una base en lo alto de esa colina. ¿Quieres echarle un vistazo?', '', 28153),
(153643, 'esES', 'Parece que vienes del bosque. ¿Cómo les va a los chicos allí?', '', 28153),
(153642, 'esES', 'Y justo después de terminar de inventar este lobociclo.', '', 28153),
(153641, 'esES', '¡$gJefe:Jefa;, has venido! ¡Y has traído el triciclo!', '', 28153),
(153640, 'esES', '1 minuto para que dé comienzo la batalla por Stromgarde.', '', 28153),
(153639, 'esES', 'Somoh máh fuerteh juntoh.', '', 28153),
(153638, 'esES', 'No te rindah nunca. Sobrevive a toda cohta.', '', 28153),
(153637, 'esES', 'Sé prudente.', '', 28153),
(153636, 'esES', '¿Qué he dicho de lah ehtupideceh?', '', 28153),
(153635, 'esES', 'Loh dehterradoh te dan la bienvenida.', '', 28153),
(153634, 'esES', '¿Hah venido a echar una mano?', '', 28153),
(153633, 'esES', '¿Qué te trae por aquí?', '', 28153),
(153632, 'esES', 'Que los vientos te sean favorables.', '', 28153),
(153631, 'esES', 'Fueza y virtud.', '', 28153),
(153630, 'esES', 'Ve con honor.', '', 28153),
(153629, 'esES', 'Ehtah tierrah se alzarán... contra vosotroh...', 'Ehtah tierrah se alzarán... contra vosotroh...', 28153),
(153628, 'esES', '¡No! Me iba a quedar con tu cabeza...', '¡No! Me iba a quedar con tu cabeza...', 28153),
(153627, 'esES', 'La Alianza... da pena...', 'La Alianza... da pena...', 28153),
(153626, 'esES', 'No aguantaráh mucho máh...', 'No aguantaráh mucho máh...', 28153),
(153625, 'esES', 'El imperio... aún vive...', 'El imperio... aún vive...', 28153),
(153624, 'esES', 'Seguiremoh viniendo...', 'Seguiremoh viniendo...', 28153),
(153623, 'esES', 'Tienes toda mi atención.', '', 28153),
(153622, 'esES', 'Ehto no ha acabado...', 'Ehto no ha acabado...', 28153),
(153621, 'esES', 'Te doy la bienvenida.', '', 28153),
(153620, 'esES', 'Por la... Horda.', 'Por la... Horda.', 28153),
(153619, 'esES', 'Me darán una recompensa por tu cabeza.', 'Me darán una recompensa por tu cabeza.', 28153),
(153618, 'esES', '¿Te creeh máh $glihto:lihta; que nosotroh? ¡Ja!', '¿Te creeh máh $glihto:lihta; que nosotroh? ¡Ja!', 28153),
(153617, 'esES', '¡Noh quedaremoh vuehtrah cabezah como trofeoh!', '¡Noh quedaremoh vuehtrah cabezah como trofeoh!', 28153),
(153616, 'esES', '¡No noh encontraráh a todoh!', '¡No noh encontraráh a todoh!', 28153),
(153615, 'esES', '¿Hah venido a jugar, alfeñique de la Alianza?', '¿Hah venido a jugar, alfeñique de la Alianza?', 28153),
(153614, 'esES', '¡Ehtah tierrah pertenecen a loh Zandalari!', '¡Ehtah tierrah pertenecen a loh Zandalari!', 28153),
(153613, 'esES', '¡Te arrepentiráh de haber venido!', '¡Te arrepentiráh de haber venido!', 28153),
(153612, 'esES', '¡Ehtah no son tuh tierrah!', '¡Ehtah no son tuh tierrah!', 28153),
(153611, 'esES', 'Estos salvajes no tienen nada que hacer contra nosotros.', 'Estos salvajes no tienen nada que hacer contra nosotros.', 28153),
(153610, 'esES', '¡No me voy si ti!', '¡No me voy si ti!', 28153),
(153609, 'esES', '¡Saldremos de esta, maldita sea!', '¡Saldremos de esta, maldita sea!', 28153),
(153608, 'esES', '¡No te dejaré atrás!', '¡No te dejaré atrás!', 28153),
(153607, 'esES', '¿Qué estás haciendo? ¡Sálvate tú!', '¿Qué estás haciendo? ¡Sálvate tú!', 28153),
(153606, 'esES', 'No te preocupes por mí. ¡Busca ayuda!', 'No te preocupes por mí. ¡Busca ayuda!', 28153),
(153605, 'esES', '¡Vete! Es demasiado tarde...', '¡Vete! Es demasiado tarde...', 28153),
(153604, 'esES', 'Tienes que salir de aquí...', 'Tienes que salir de aquí...', 28153),
(153603, 'esES', 'Te estaré observando.', '', 28153),
(153602, 'esES', 'Puede que la próxima vez tengan más cuidado y no se dejen capturar. Tienen suerte de que la Horda tenga a alguien como tú, capaz de proteger a sus miembros.', '', 28153),
(153601, 'esES', 'Nuestros aliados nos necesitan. Parece que se han dejado capturar... ¡Libéralos!', '', 28153),
(153600, 'esES', 'Seguro que esta información nos proporciona ventaja sobre la Alianza. Tus esfuerzos tendrán su recompensa.', '', 28153),
(153599, 'esES', 'Nuestros espías nos informan de que se va a entregar un mensaje muy importante por esta zona. Haz lo que sea necesario para interceptarlo.', '', 28153),
(153598, 'esES', 'Loh loa ehtán de tu lado. ¡Eso ehtá muy bien! Pero no dejeh que se te suba a la cabeza.', '', 28153),
(153597, 'esES', 'Nuehtroh enemigoh ehtán invadiendo el Jardín de loh Loa. Alguien tiene que enseñarleh modaleh... ¡Que el poder de loh loa te acompañe!', '', 28153),
(153596, 'esES', 'Reúnete con nosotros en la avanzada. Debemos hallar la respuesta. Esto me huele a levantamientos.', '', 28153),
(153595, 'esES', 'No ha sido muy sutil, pero era necesario. No podemos dejar que el enemigo descubra nuestros planes. Bien hecho.', '', 28153),
(153594, 'esES', 'La Alianza ha enviado a sus espías para que saquen a la luz nuestros secretos. Encárgate de que no descubran nuestros planes.', '', 28153),
(153593, 'esES', 'Sin la flota Zandalari, la guerra con la Alianza será nuestro fin.', '', 28153),
(153592, 'esES', 'La Alianza no va a esperar a que tengamos nuestra flota para atacar. Necesitamos a los Zandalari.', '', 28153),
(153591, 'esES', 'Haz que los Zandalari se unan a la Horda, adalid.', '', 28153),
(153590, 'esES', 'Necesitamos a la flota Zandalari.', '', 28153),
(153589, 'esES', 'Que se haga la voluntad de la Jefa de Guerra.', '', 28153),
(153588, 'esES', 'Contigo y con Ai\'twen de nuestro lado, nuestro plan no puede fallar.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'esES', 'Creo que los Zandalari no me tienen mucho aprecio.', '', 28153),
(153586, 'esES', 'Portavoz de la Horda...', '', 28153),
(153585, 'esES', 'La flota Zandalari debe unirse a la Horda. Encárgate de ello.', '', 28153),
(153584, 'esES', '', '¡Hablah de alguien que ha desafiado el poder de Ventormenta pa salvarnoh a Zul y a mí! Se merece una audiencia, padre.', 28153),
(153583, 'esES', 'Mi Rey, el único objetivo de la Horda eh robar nuehtra flota pa su Jefa de Guerra no-muerta.', '', 28153),
(153582, 'esES', 'Tengo buen material. Pero nada de preguntas.', 'Tengo buen material. Pero nada de preguntas.', 28153),
(153581, 'esES', 'Traigo suministros de Monte Alto.', 'Traigo suministros de Monte Alto.', 28153),
(153580, 'esES', '(Presenciar los hechos que provocaron la herida de Azeroth)', '(Presenciar los hechos que provocaron la herida de Azeroth)', 28153),
(153579, 'esES', '<La consola titánica muestra una serie de entradas de datos. Puedes seleccionar una para verla>.', '', 28153),
(153578, 'esES', '¡Espero que lleves ropa interior ignífuga!', '¡Espero que lleves ropa interior ignífuga!', 28153),
(153577, 'esES', '¡El ambiente se va a caldear!', '¡El ambiente se va a caldear!', 28153),
(153576, 'esES', '¡Te voy a prender fuego!', '¡Te voy a prender fuego!', 28153),
(153575, 'esES', 'Ese \"enano de diamante\" es el portavoz del alma del mundo. No intervendría si la situación no fuese desesperada.', '', 28153),
(153574, 'esES', '', 'Oh, ¿te lo puedes creer? ¡El enano de diamante nos podría enviar a cualquier lugar de Azeroth!', 28153),
(153573, 'esES', 'Me gusta este enano de diamante con teletransporte que da obsequios poderosos. ¿Nos lo quedamos?', '', 28153),
(153572, 'esES', 'Estoy seguro de que se trata de algo importante, Magni. Pero, por el bien de Kul Tiras, date prisa.', '', 28153),
(153571, 'esES', 'Ven, adalid. ¡Azeroth te llama!', '', 28153),
(153570, 'esES', 'Ah, se me olvidaba que lo guardé aquí.', 'Ah, se me olvidaba que lo guardé aquí. Mecachis.', 28153),
(153569, 'esES', 'Estoy muy mayor para esto. ¡Yo me largo!', 'Estoy muy mayor para esto. ¡Yo me largo!', 28153),
(153568, 'esES', 'Más vale que espabiles, soldado.', 'Más vale que espabiles, soldado.', 28153),
(153567, 'esES', 'Señor, lo... haré mejor la próxima vez, señor.', 'Señor, lo... haré mejor la próxima vez, señor.', 28153),
(153566, 'esES', 'Soldado James, ¿tus padres no te prestaron suficiente atención cuando eras pequeño? ¿Por qué me haces perder el tiempo buscando tu trasero por tierras inexploradas?', 'Soldado James, ¿tus padres no te prestaron suficiente atención cuando eras pequeño? ¿Por qué me haces perder el tiempo buscando tu trasero por tierras inexploradas?', 28153),
(153565, 'esES', 'Sargento... gracias por venir a buscarme... señor.', 'Sargento... gracias por venir a buscarme... señor.', 28153),
(153564, 'esES', '¡En marcha!', '¡En marcha!', 28153),
(153563, 'esES', 'Es hora de regresar. Aterravermis querrá un informe completo.', 'Es hora de regresar. Aterravermis querrá un informe completo.', 28153),
(153562, 'esES', '', 'Los Lomozarza no pudieron acabar conmigo, y lo lamentarán.', 28153),
(153561, 'esES', '', 'Creo que redecoraré cuando vuelva. Estaba pensando utilizar colmillos... ¿Dónde podré encontrarlos?$b$b<Deal sonríe con malicia>.', 28153),
(153560, 'esES', '', 'Primero, necesito un trago, y después tendré que encargarme de recuperar mi hogar y reconstruirlo. ¡Gracias por reducir su número!', 28153),
(153559, 'esES', 'No puedo quedarme mucho, debo volver a mi granja. El alcalde me pidió que viniera y me asegurara de darte las gracias por ayudarnos con los Lomozarza.$b$bBuen trabajo, $gchico:chica;.', '', 28153),
(153558, 'esES', '¡Buen trabajo con esos jabaespines, $gamigo:amiga;!', '', 28153),
(153557, 'esES', 'No puedo quedarme mucho tiempo. Tenemos que arreglar a esos mozos de labranza para que reparen el daño que han causado en los campos.$b$bPero es importante tomarse un descanso de vez en cuando.', '', 28153),
(153556, 'esES', 'He dejado al mozo de labranza en el modo de autodefensa. Seguro que todo irá bien.', '', 28153),
(153555, 'esES', 'Busca púas de jabaespín. ¡Son sorprendentemente útiles como herramienta y los jabaespines incluso las añaden como ingredientes en sus calderas!', '', 28153),
(153554, 'esES', 'La Horda desde el norte, los jabaespines desde el oeste. ¿Podemos seguir confiando en la milicia?', '', 28153),
(153553, 'esES', 'Espero que Rolf, Mort y Spiff escaparan con vida.', '', 28153),
(153552, 'esES', '', 'Mih ehpíah dicen que no podéih ganar la guerra contra la Alianza sin nuehtra flota.\n\nAsí que... te ocuparáh de todo el trabajo sucio que tenga pendiente hoy. ¡O si no...!', 28153),
(153551, 'esES', '', 'No paro de decirleh a Zolani y Talanji que el puerto eh seguro. ¿Acaso me ehcuchan? No.$b$bSí, bueno, hay peleah, rufianeh y camorra... pero nada tan importante como pa molehtar al Rey.', 28153),
(153550, 'esES', 'Sígueme si quieres.', 'Sígueme si quieres.', 28153),
(153549, 'esES', 'Adalid, tienes que ver esto; es algo que también puede ayudar a esta tierra.', '', 28153),
(153548, 'esES', 'Tranquilos. Es Magni Barbabronce, antiguo Rey de Forjaz y actual Portavoz de Azeroth.', '', 28153),
(153547, 'esES', 'Esto no me lo esperaba.', '', 28153),
(153546, 'esES', '¡Brujería!', '', 28153),
(153545, 'esES', '', 'Un... ¡¿enano de diamante?!', 28153),
(153544, 'esES', '¡Ahora libera el poder del Corazón!', '', 28153),
(153543, 'esES', 'Son malas noticias. Será mejor que informemos al Alto Comandante.', 'Son malas noticias. Será mejor que informemos al Alto Comandante.', 28153),
(153542, 'esES', '¡Korthek está loco! ¡Hay que detenerlo!', '¡Korthek está loco! ¡Hay que detenerlo!', 28153),
(153541, 'esES', 'Korthek se ha cansado de la paz. Ha dado la espalda al sacrificio de Sethraliss y pretende reunir las llaves para liberar al C\'Thraxxi y utilizarlo contra sus enemigos.', 'Korthek se ha cansado de la paz. Ha dado la espalda al sacrificio de Sethraliss y pretende reunir las llaves para liberar al C\'Thraxxi y utilizarlo contra sus enemigos.', 28153),
(153540, 'esES', 'El gran sabio Sulthis nos pidió ayuda a Korthek y a mí para levantar una barrera mágica que encerrara al C\'Thraxxi caído. Juramos que nunca permitiríamos que semejante terror volviera a desatarse.', 'El gran sabio Sulthis nos pidió ayuda a Korthek y a mí para levantar una barrera mágica que encerrara al C\'Thraxxi caído. Juramos que nunca permitiríamos que semejante terror volviera a desatarse.', 28153),
(153539, 'esES', 'El poder que desató la destrucción fue inmenso. Cambió nuestra tierra para siempre.', 'El poder que desató la destrucción fue inmenso. Cambió nuestra tierra para siempre.', 28153),
(153538, 'esES', 'Solo nos salvamos porque nuestra loa intervino. Sethraliss se sacrificó para domeñar al C\'Thraxxi, pero antes la criatura tuvo tiempo de destruir una pirámide ancestral que se erigía en el centro de esta tierra.', 'Solo nos salvamos porque nuestra loa intervino. Sethraliss se sacrificó para domeñar al C\'Thraxxi, pero antes la criatura tuvo tiempo de destruir una pirámide ancestral que se erigía en el centro de esta tierra.', 28153),
(153537, 'esES', 'Hace mucho tiempo, antes de que las arenas empezaran a extenderse, un monstruoso belisario C\'Thraxxi atacó nuestras tierras. Empezó a masacrar a todo el que se interponía en su camino, ya fuera trol o sethrak.', 'Hace mucho tiempo, antes de que las arenas empezaran a extenderse, un monstruoso belisario C\'Thraxxi atacó nuestras tierras. Empezó a masacrar a todo el que se interponía en su camino, ya fuera trol o sethrak.', 28153),
(153536, 'esES', '', 'Debemos estar atentos a la Horda... Siguen atacando la plaza.', 28153),
(153535, 'esES', '', 'Si ves a alguien más con intenciones de invadir mi ciudad, te agradecería que me avisaras.', 28153),
(153534, 'esES', '', 'Todo el mundo confía en mí para que dirija la ciudad. ¡No les defraudaré!', 28153),
(153533, 'esES', '', 'Parece que todo el mundo está a salvo... por ahora.', 28153),
(153532, 'esES', 'No es una simple piedra, es una llave. Es parte de un juego que contenía un poder terrible y devastador.', 'No es una simple piedra, es una llave. Es parte de un juego que contenía un poder terrible y devastador.', 28153),
(153531, 'esES', '¡Ah! Hay una especie de piedra ahí.', '¡Ah! Hay una especie de piedra ahí.', 28153),
(153530, 'esES', '\"¡Temed a la hija del mar!\".', '\"¡Temed a la hija del mar!\".', 28153),
(153529, 'esES', '... muriendo, a su gente advirtió...', '... muriendo, a su gente advirtió...', 28153),
(153528, 'esES', '... tan lejos de su hogar...', '... tan lejos de su hogar...', 28153),
(153527, 'esES', '', 'Ese enano ha prometido otorgarle armah pa salvar a mi pueblo. Creo que vale la pena arriehgarse...', 28153),
(153526, 'esES', 'Y víctima de su traición...', 'Y víctima de su traición...', 28153),
(153525, 'esES', '... su hija lo abandonó.', '... su hija lo abandonó.', 28153),
(153524, 'esES', 'Y al comenzar contra ellos a luchar...', 'Y al comenzar contra ellos a luchar...', 28153),
(153523, 'esES', '... ¡enemigos vio!', '... ¡enemigos vio!', 28153),
(153522, 'esES', 'Pero al llegar a aquel nuevo lugar...', 'Pero al llegar a aquel nuevo lugar...', 28153),
(153521, 'esES', '\"No te puedo perder\".', '\"No te puedo perder\".', 28153),
(153520, 'esES', '\"Espérame\", rogó desde el bajel.', '\"Espérame\", rogó desde el bajel.', 28153),
(153519, 'esES', 'Supongo que nos parece bien que se vaya de paseo con el rey de diamantes...', '', 28153),
(153518, 'esES', '... su padre fue detrás.', '... su padre fue detrás.', 28153),
(153517, 'esES', 'Cuando ella huyó cruzando el ancho mar...', 'Cuando ella huyó cruzando el ancho mar...', 28153),
(153516, 'esES', '... para después dejarlo atrás.', '... para después dejarlo atrás.', 28153),
(153515, 'esES', 'Trajiste honor a nuestro noble hogar...', 'Trajiste honor a nuestro noble hogar...', 28153),
(153514, 'esES', '... ¿por qué tú nos tuviste que olvidar?', '... ¿por qué tú nos tuviste que olvidar?', 28153),
(153513, 'esES', '¿Por qué? ¿Por qué? Dinos, hija del mar...', '¿Por qué? ¿Por qué? Dinos, hija del mar...', 28153),
(153512, 'esES', '... pues ella lo traicionó.', '... pues ella lo traicionó.', 28153),
(153511, 'esES', 'Y él murió en Theramore...', 'Y él murió en Theramore...', 28153),
(153510, 'esES', 'Su flota allí cayó.', 'Su flota allí cayó.', 28153),
(153509, 'esES', 'Sangre y dolor en Kalimdor.', 'Sangre y dolor en Kalimdor.', 28153),
(153508, 'esES', 'Y en el mar halló su fin.', 'Y en el mar halló su fin.', 28153),
(153507, 'esES', 'La voz viajó con la espuma y la sal.', 'La voz viajó con la espuma y la sal.', 28153),
(153506, 'esES', '... al hombre oí decir.', '... al hombre oí decir.', 28153),
(153505, 'esES', '\"Temed, temed a la hija del mar\"...', '\"Temed, temed a la hija del mar\"...', 28153),
(153504, 'esES', 'Buenos días, $r.', '', 28153),
(153502, 'esES', '¿Llevas algo en los bolsillos?', '¿Llevas algo en los bolsillos?', 28153),
(153501, 'esES', 'Me quedaré aquí y me ocuparé de las defensas. Gracias otra vez, $gamigo:amiga;.', 'Me quedaré aquí y me ocuparé de las defensas. Gracias otra vez, $gamigo:amiga;.', 28153),
(153500, 'esES', '', '', 28153),
(153499, 'esES', '', 'Ehbirroh, ¡MATAD!', 28153),
(153498, 'esES', 'No estaría aquí si no fuera por ti y el sargento. Gracias de nuevo.', 'No estaría aquí si no fuera por ti y el sargento. Gracias de nuevo.', 28153),
(153497, 'esES', '', 'Informaré a Zul. Él decidirá si merece la pena informar a Rahtakhan.', 28153),
(153496, 'esES', '¡Matadloh anteh de que pasen!', '', 28153),
(153495, 'esES', 'No volveremoh a parar hahta que lleguemoh al muelle. Cuando quierah.', '', 28153),
(153494, 'esES', 'No le tieneh mucho aprecio a la vida, ¿eh?', '', 28153),
(153493, 'esES', 'Vah a conseguir que noh capturen.', '', 28153),
(153492, 'esES', '¿Quiereh que noh maten?', '', 28153),
(153491, 'esES', '¡Eh! ¡No te alejeh!', '', 28153),
(153490, 'esES', '¡Vuelve aquí, colega!', '', 28153),
(153489, 'esES', '¡Es $n, gracias a la Luz! Me voy hacia el templo, que esto no es seguro.', '', 28153),
(153488, 'esES', 'Y reza para que nunca tengas que elegir.', '', 28153),
(153487, 'esES', 'Espero que distingas la lealtad del honor.', '', 28153),
(153486, 'esES', '¿A qué te refieres?', '¿A qué te refieres?', 28153),
(153485, 'esES', 'Con todo lo que ha hecho, no formaré parte de su Horda.', '', 28153),
(153484, 'esES', 'Crees que estás aquí para llevarme de vuelta a Orgrimmar. Con la Jefa de Guerra. Pues te equivocas.', '', 28153),
(153483, 'esES', '¡Es hora de asestarle un golpe estratégico a Ventura y Cía.!', '', 28153),
(153482, 'esES', 'Da la orden, adalid.', '', 28153),
(153477, 'esES', '', 'No te muerah ahora, hay trabajo que hacer.', 28153),
(153476, 'esES', '', '¿Teníah ganah de ver a Bwonsamdi?', 28153),
(153475, 'esES', '', 'Saldráh de ehta.', 28153),
(153474, 'esES', '', 'Arriba, aún no hemoh terminado.', 28153),
(153473, 'esES', '', 'Mi loa no te dejará caer.', 28153),
(153472, 'esES', 'Parece que nuestra información sobre la maldad de todos los sethrak era incorrecta.', 'Parece que nuestra información sobre la maldad de todos los sethrak era incorrecta.', 28153),
(153471, 'esES', '¡A esto pueden jugar dos!', '¡A esto pueden jugar dos!', 28153),
(153470, 'esES', '', 'El nuevo imperio trol ha llegado. ¡Nuehtro letargo ha terminado!', 28153),
(153469, 'esES', '', 'Zul predijo ehte día. Alzaoh... Alzaoh, ehbirroh de la sangre. ¡Preparaoh pa la siguiente era de ehte mundo!', 28153),
(153468, 'esES', '¡No! No...', '¡No! No...', 28153),
(153467, 'esES', 'Cómo te atreves a quedarte mi parte...', 'Cómo te atreves a quedarte mi parte...', 28153),
(153466, 'esES', 'Recibirás tu merecido...', 'Recibirás tu merecido...', 28153),
(153465, 'esES', '¡Héroes, seguidme!', '', 28153),
(153464, 'esES', 'Te... atraparé...', 'Te... atraparé...', 28153),
(153463, 'esES', '¡Estáis muertos! ¡Estáis todos muertos!', '¡Estáis muertos! ¡Estáis todos muertos!', 28153),
(153462, 'esES', '¿Crees que puedes quedarte con mi parte sin más?', '¿Crees que puedes quedarte con mi parte sin más?', 28153),
(153461, 'esES', '¡Traidores! ¡Os arrancaré la cabeza!', '¡Traidores! ¡Os arrancaré la cabeza!', 28153),
(153460, 'esES', '¡Traidores! ¡Todos vosotros!', '¡Traidores! ¡Todos vosotros!', 28153),
(153459, 'esES', 'Capitana Eudora... guíanos hacia la victoria...', '', 28153),
(153458, 'esES', '¿Carne fresca? ¡Ratas de Pantoque! ¡A comer!', '', 28153),
(153457, 'esES', 'Hoy, ¡loh gritoh de batalla y el entrechocar de lah armah llegarán hahta loh grandeh loa! Y loh caídoh se unirán a elloh en el máh allá.', '', 28153),
(153456, 'esES', 'Otorgadle una muerte honorable...', '', 28153),
(153455, 'esES', 'Otorgadle una muerte honorable...', '', 28153),
(153454, 'esES', '¡¿Aaaah?!', '', 28153),
(153453, 'esES', 'Al máh allá...', '', 28153),
(153452, 'esES', 'Hoy no contabah con la bendición de loh loa...', '', 28153),
(153451, 'esES', '¡Por Zandalar!', '', 28153),
(153450, 'esES', '¡Vendida! ¡Una espada cromática por 281 monedas de oro! Con esta arma tu presencia no pasará inadvertida.', '', 28153),
(153449, 'esES', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Misil buscador]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Misil buscador]|h|r!', 28153),
(153448, 'esES', '¡Este es un día en honor a Kul Tiras!', '', 28153),
(153447, 'esES', 'Hoy el suelo estará sembrado de orejas y narices.', '', 28153),
(153446, 'esES', 'Esto no termina hasta que se termina.', '', 28153),
(153445, 'esES', '¡Tranquilos! ¡La pelea no ha terminado aún!', '', 28153),
(153444, 'esES', '¡Sí, sí, habrá sangre! Un poco de paciencia.', '', 28153),
(153443, 'esES', '¡Vendido! ¡Un recuerdo embrujado por 18 monedas de oro! Francamente, no daría ni una moneda de cobre por él, ¡pero no es mi dinero!', '', 28153),
(153442, 'esES', 'No, no, no. Buen movimiento. Por los pelos.', '', 28153),
(153441, 'esES', 'Mueres siendo un don nadie para Kul Tiras.', '', 28153),
(153440, 'esES', '¡Auch!', '', 28153),
(153439, 'esES', '¡Esta es una noche en honor a Kul Tiras!', '', 28153),
(153438, 'esES', 'No será una pelea limpia, así que mantened las distancias. ¿Listos?', '', 28153),
(153437, 'esES', 'Solo obtendrá este honor el último que quede en pie.', '', 28153),
(153436, 'esES', '¡Amigos! Nos hemos reunido hoy aquí para ver cuál de estos bandidos, matones y patanes tiene derecho a llamarse hijo de Kul Tiras.', '', 28153),
(153435, 'esES', '¡Vendido! ¡Un gran cohete de amor para la encantadora dama por 1412 monedas de oro! ¡Ahora será la comidilla de la ciudad!', '', 28153),
(153434, 'esES', '¡Vendidos! ¡Los espaldares acorator para el joven de la primera fila por 756 monedas de oro! No parece que te los puedas poner, pero bueno...', '', 28153),
(153433, 'esES', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Azerokk está lanzando |cFFFF0000|Hspell:257597|h[Infusión de azerita]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Azerokk está lanzando |cFFFF0000|Hspell:257597|h[Infusión de azerita]|h|r!', 28153),
(153432, 'esES', '¡Traidora! ¡Prendedla!', '', 28153),
(153431, 'esES', 'Es de vital importancia para todos nosotros que la llave no caiga en manos de Korthek. Vamos, nuestro templo está ahí delante.', '', 28153),
(153430, 'esES', 'Se lo deslicé en el bolsillo a un prisionero que acababan de capturar. Creo que se llamaba \"James\".', '', 28153),
(153429, 'esES', '¡Tontos! Me capturaron y me registraron, pero para cuando lo hicieron ya la había escondido en un lugar donde no se les ocurriría mirar.', '', 28153),
(153428, 'esES', 'Pero Korthek nos traicionó y asesinaron a Sulthis. Ahora Korthek y sus seguidores, los infieles, me buscan a mí y a mi llave.', '', 28153),
(153427, 'esES', 'Hace mucho tiempo, Korthek, Sulthis y yo gobernábamos en armonía. Nuestro loa nos encargó proteger tres llaves que encierran un poder malvado y ancestral bajo las arenas.', '', 28153),
(153426, 'esES', 'Nuestro templo es el último bastión contra los infieles.', '', 28153),
(153425, 'esES', '', 'Vale, puede que tengamoh un problemita de nada aquí abajo, pero no merece la pena molehtar al Rey por algo así.', 28153),
(153424, 'esES', '', 'El momento de hacer tratoh con loh loa ya ha pasado. ¡Eh la hora de la sangre!', 28153),
(153423, 'esES', '', 'No te preocupeh por esoh crímeneh sin importancia. Tenemoh que ocuparnoh de cosah máh importanteh.', 28153),
(153421, 'esES', '', '¡Espero que te gusten!', 28153),
(153419, 'esES', '', 'Toma. No iba a dejar que te fueras con hambre, ¿eh?', 28153),
(153418, 'esES', '', '¡Aaah, son perfectas!', 28153),
(153417, 'esES', '', 'Un momento, cariño, tengo algo para ti.', 28153),
(153416, 'esES', '¡Buen trabajo! ¡Le has asestado un duro golpe al Imperio Zandalari!', '', 28153),
(153415, 'esES', 'Elijo a Pa\'ku, maestra de los vientos.', 'Elijo a Pa\'ku, maestra de los vientos.', 28153),
(153414, 'esES', 'Elijo a Gonk, señor de la manada.', 'Elijo a Gonk, señor de la manada.', 28153),
(153413, 'esES', 'Los Zandalari han domesticado a una bestia y creen que los protegerá. ¡Demuéstrales que se equivocan!', '', 28153),
(153412, 'esES', 'Por fin hemos recuperado Stromgarde.', '', 28153),
(153411, 'esES', '¡Muere, miserable!', '', 28153),
(153410, 'esES', 'Eso te pondrá en tu lugar.', '', 28153),
(153409, 'esES', 'Nadie te echará en falta.', '', 28153),
(153408, 'esES', 'Algún día, la Alianza recuperará Stromgarde.', '', 28153),
(153407, 'esES', '¡Que llueva muerte sobre la Horda!', '', 28153),
(153406, 'esES', '¡Tercera división, disparad!', '', 28153),
(153405, 'esES', 'Me gustaría cambiar al loa representado aquí desde Zuldazar.', 'Me gustaría cambiar al loa representado aquí desde Zuldazar.', 28153),
(153404, 'esES', '¡Disparad desde las murallas!', '', 28153),
(153403, 'esES', '¡Ecos del pasado, resurgid!', '', 28153),
(153402, 'esES', '¡Los espíritus de Arathor os destruirán!', '', 28153),
(153401, 'esES', 'No dejaremos que el mal sobreviva en ningún lugar, ni siquiera en estas tierras. ¡Buen trabajo!', '', 28153),
(153400, 'esES', 'Ancestros, alzaos y proteged vuestro hogar.', '', 28153),
(153399, 'esES', 'He matado a cientos de los tuyos, y tú correrás la misma suerte.', '', 28153),
(153398, 'esES', '¡Otra victoria pa el Imperio Zandalari! Buen trabajo, adalid de la Horda.', '', 28153),
(153397, 'esES', 'El mal se esconde en este lugar salvaje. ¡Encárgate de eliminarlo!', '', 28153),
(153396, 'esES', 'Ehta zona se halla amenazada por una criatura muy poderosa. ¡Encuéntrala y acaba con ella!', '', 28153),
(153395, 'esES', 'Los justos siempre triunfan.', '', 28153),
(153394, 'esES', '¡Te he purificado!', '', 28153),
(153393, 'esES', 'Tu destino está sellado.', '', 28153),
(153392, 'esES', 'Se te ha juzgado.', '', 28153),
(153391, 'esES', 'Puede que hayamos perdido Stromgarde, ¡pero la Alianza jamás caerá!', '', 28153),
(153390, 'esES', '¡Por el poder de la Luz!', '', 28153),
(153389, 'esES', '¡Huid de la Luz, sabandijas!', '', 28153),
(153388, 'esES', 'La Luz os aniquilará.', '', 28153),
(153387, 'esES', 'Otra amenaza menos, ¡y otra victoria para la Alianza!', '', 28153),
(153386, 'esES', '¡La Luz triunfará!', '', 28153),
(153385, 'esES', '', 'Soy la primera cronista. El Rey me ha elegido para grabar nuestra historia en la piedra, que perdurará durante eones.', 28153),
(153384, 'esES', '¡Dejad que la Luz os purifique!', '', 28153),
(153383, 'esES', '¡Mi pueblo aclamará tu nombre, adalid de loh Zandalari! ¡Buen trabajo!', '', 28153),
(153382, 'esES', '¡Que la Luz os purifique!', '', 28153),
(153381, 'esES', '¡Por la Luz!', '', 28153),
(153380, 'esES', 'El mal se siente tan atraído por estas tierras como una vid asfixiante. Acaba con él de raíz y protege a nuestras tropas.', '', 28153),
(153379, 'esES', '¡No dejaré que ehte enemigo amenace a mi pueblo! ¡Acaba con él!', '', 28153),
(153378, 'esES', 'Ahora que esa criatura ya no amenaza estas tierras, podemos redoblar nuestros esfuerzos contra los Zandalari. Gracias.', '', 28153),
(153377, 'esES', 'Otro enemigo derrotado en nombre del Imperio Zandalari.', '', 28153),
(153376, 'esES', 'Esta criatura repugnante amenaza a nuestras tropas. Acaba con ella, ¡por la Alianza!', '', 28153),
(153375, 'esES', 'No toleraré una amenaza así dentro de mih fronterah. ¡Acaba con ella!', '', 28153),
(153374, 'esES', 'Sube al triciclo cuando estés $glisto:lista; para partir.', '', 28153),
(153372, 'esES', '', 'Esos nagas tienen miedo. Algo más los empuja. Algo más que simple lealtad a la reina Azshara.', 28153),
(153371, 'esES', '', 'Saludos.', 28153),
(153370, 'esES', '¿Eso es todo? ¡Ja! ¿Para cuándo un desafío de verdad?', '', 28153),
(153369, 'esES', '¡Esto es genial!', '', 28153),
(153368, 'esES', 'No volverás a hacer algo así.', '', 28153),
(153367, 'esES', '¡Saluda a tus ancestros de mi parte!', '', 28153),
(153366, 'esES', '¡Nunca os saldréis con la vuestra!', '', 28153),
(153365, 'esES', 'Esto lleva muchos años de práctica.', '', 28153),
(153364, 'esES', '¡Ja! ¡Así se hace!', '', 28153),
(153363, 'esES', '¡Fuera de aquí!', '', 28153),
(153362, 'esES', '¡Por Khaz Modan!', '', 28153),
(153361, 'esES', 'Toma, de regalo.', '', 28153),
(153360, 'esES', 'Todo para ti.', '', 28153),
(153359, 'esES', '¡Eh, agarra esto!', '', 28153),
(153357, 'esES', '¡Este será tu fin!', '', 28153),
(153351, 'esES', 'Magni, ¿qué quiere darme Azeroth?', 'Magni, ¿qué quiere darme Azeroth?', 28153),
(153350, 'esES', 'Con los gorilas bajo control, podremos centrarnos en la lucha contra la Horda. ¡Bien hecho!', '', 28153),
(153349, 'esES', 'Estos gorilas han absorbido esencia de kaja\'mita, lo que les otorga una inteligencia extraordinaria. No podemos permitir que se extiendan a otros lugares.', '', 28153),
(153348, 'esES', 'Lanzamiento de bomba A. T. O. M. I. K. A. detectado.', 'Lanzamiento de bomba A. T. O. M. I. K. A. detectado.', 28153),
(153347, 'esES', 'La Horda ha caído muy bajo si cree que puede hacernos prisioneros. Gracias por liberar a nuestra gente. ¡Buen trabajo!', '', 28153),
(153346, 'esES', 'No puedo descansar sabiendo que uno de mis hombres sigue ahí fuera.', 'No puedo descansar sabiendo que uno de mis hombres sigue ahí fuera.', 28153),
(153345, 'esES', 'No nos verán venir. ¡Ja! Te doy las gracias.', '', 28153),
(153344, 'esES', 'La Horda cree que puede averiguar lo que estamos haciendo en Zuldazar, pero se equivoca. Ciega los ojos que nos espían, ¡que comprendan que con la Alianza no se juega!', '', 28153),
(153343, 'esES', '¡No pienso volver a entrar en una de esas sin una llave!', '¡No pienso volver a entrar en una de esas sin una llave!', 28153),
(153342, 'esES', '¡Un minuto más dentro de ese trasto y la cosa se habría puesto fea!', '¡Un minuto más dentro de ese trasto y la cosa se habría puesto fea!', 28153),
(153341, 'esES', '¿Por qué nos dejó Thurgaden en esas latas tanto tiempo? ¡Agh!', '¿Por qué nos dejó Thurgaden en esas latas tanto tiempo? ¡Agh!', 28153),
(153340, 'esES', '¡Ahí dentro hacía más calor que en las mismísimas entrañas de Ragnaros!', '¡Ahí dentro hacía más calor que en las mismísimas entrañas de Ragnaros!', 28153),
(153339, 'esES', 'Enviaré a un muchacho para que avise a Aterravermis de que tenemos esta zona controlada. Gracias por la ayuda, $n.', '', 28153),
(153338, 'esES', '¡Trabajo rutinario!', '', 28153),
(153337, 'esES', '¡Eso ha sido realmente aterrador!', '', 28153),
(153336, 'esES', 'Estamos extrayendo poder de las Tierras de Fuego, pero nada peligroso escuchará la llamada.', '', 28153),
(153335, 'esES', 'Calma esa barba temblorosa, Thaelin. No soy tan tonto como el señor feudal hechicero Thaurissan.', '', 28153),
(153334, 'esES', 'Cuidado con lo que invocas, maestro del yunque.', '', 28153),
(153333, 'esES', 'Una excelente invocación, muchachos. Tienes el control, $n. ¡Enséñale a esos palurdos de la Horda lo que pasa cuando te metes con los Hierro Negro!', '', 28153),
(153332, 'esES', '$C, coloca un poco de esa escoria sobre el magma inestable de ahí. Y prepárate.', '', 28153),
(153331, 'esES', '¡La batalla por Stromgarde ha comenzado!', '', 28153),
(153330, 'esES', '30 segundos para que dé comienzo la batalla por Stromgarde.', '', 28153),
(153329, 'esES', 'Sí, no hay problema.', '', 28153),
(153328, 'esES', 'Espera, ¿te has guardado la llave?', '', 28153),
(153327, 'esES', 'Parece que mis chamanes siguen en las máquinas topo. Sabía que me olvidaba de algo.', '', 28153),
(153326, 'esES', 'Ya hemos empezado bien. ¿Qué falta?', '', 28153),
(153325, 'esES', 'No tienes ni idea de a qué fuerzas te enfrentas, criatura.', '', 28153),
(153324, 'esES', '<Buscar en el interior y sacar algo que se parezca más a un edificio>.', '<Buscar en el interior y sacar algo que se parezca más a un edificio>.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'esES', '<Buscar en el interior y sacar algo>.', '<Buscar en el interior y sacar algo>.', 28153),
(153322, 'esES', '<Un agujero de gusano se extiende ante ti. Se supone que debería servirte para construir un edificio... de algún modo>.', '', 28153),
(153321, 'esES', 'Nadie pone a prueba mi paciencia, alimaña. Muere.', '', 28153),
(153320, 'esES', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t ¡%s empieza a lanzar |cFFFF0000|Hspell:264382|h[Haz ocular]|h|r!', 'Aparece una proyección a lo lejos...', 28153),
(153319, 'esES', 'El mar eh nuehtro hogar, pero hay algo ahí fuera que noh mantiene alejadoh. ¡Ehpero que puedah arreglarlo!', '', 28153),
(153318, 'esES', 'Vah a ver a loh buhcadoreh, ¿eh? Son buena gente, deberíah ehtar a salvo con elloh.', '', 28153),
(153317, 'esES', 'Loh barcoh desaparecen. Aparecen tormentah donde nunca se habían vihto anteh. A loh demáh leh da miedo echarse a la mar.', '', 28153),
(153316, 'esES', 'Se rumorea que ocurren cosah ehtrañah en la cohta.', '', 28153),
(153315, 'esES', 'Como desees.', '', 28153),
(153314, 'esES', 'Y, por favor... cuida de Jaina.', '', 28153),
(153313, 'esES', 'Establece una base de operaciones en Kul Tiras. El plan no debe fallar.', '', 28153),
(153312, 'esES', 'Llévate una nave de la Séptima Legión como escolta.', '', 28153),
(153311, 'esES', 'Hm, tan bien como siempre.', '', 28153),
(153310, 'esES', 'Que el abismo os rechace como habéis rechazado a vuestra gente.', '', 28153),
(153309, 'esES', 'No representáis más que odio y sufrimiento.', '', 28153),
(153308, 'esES', 'Escuchad el despertar de la tormenta y enfrentaos a vuestro fin.', '', 28153),
(153307, 'esES', 'No temáis, solo vais a ser juzgados.', '', 28153),
(153306, 'esES', 'Genn... ¿Cómo se te da navegar?', '', 28153),
(153305, 'esES', 'Oíd los gritos de nuestra gente y sabed que os ha llegado la hora.', '', 28153),
(153304, 'esES', 'No obtendréis redención.', '', 28153),
(153303, 'esES', 'No estabais a la altura.', '', 28153),
(153302, 'esES', 'Que vuestras almas sufran eternamente.', '', 28153),
(153301, 'esES', '', 'En cuanto me haga con un arma...', 28153),
(153300, 'esES', '', 'No me mataron. Ese fue su primer error.', 28153),
(153299, 'esES', '', 'Destrozan mi granja y encima se atreven a capturarme. No voy a permitir que se vayan de rositas.', 28153),
(153298, 'esES', '¡No pienso irme hasta que acabemos con esta amenaza!', '¡No pienso irme hasta que acabemos con esta amenaza!', 28153),
(153297, 'esES', '¡Van a pagar por lo que han hecho!', '¡Van a pagar por lo que han hecho!', 28153),
(153296, 'esES', '¡Esos jabaespines se merecen una paliza!', '¡Esos jabaespines se merecen una paliza!', 28153),
(153295, 'esES', '', 'Vuelve a hacer negocios conmigo cuando quieras.', 28153),
(153294, 'esES', '', '¡Libre al fin! ¡Esos puercos se van a enterar de lo que pasa por meterse con mi granja!', 28153),
(153293, 'esES', '¡Eh! ¡Buenos días! Ya era hora...', '', 28153),
(153292, 'esES', 'Temed... Temed... a la hija del mar... Mmm, mmm...', '', 28153),
(153291, 'esES', 'Mantén... mantén eso lejos de mí. ¡Solo quiero... ahogarme... en mi copa! ¡Hip!', 'Mantén... mantén eso lejos de mí. ¡Solo quiero... ahogarme... en mi copa! ¡Hip!', 28153),
(153290, 'esES', 'Antes de embarcarse en un viaje de cuatro meses, mi cuñado le dio a mi hermana un tallomar que solo tardó tres días en marchitarse. El dolor la devoraba por dentro, pero como lo supo pronto, pudo racionar las monedas para mantener a sus hijos.', 'Antes de embarcarse en un viaje de cuatro meses, mi cuñado le dio a mi hermana un tallomar que solo tardó tres días en marchitarse. El dolor la devoraba por dentro, pero como lo supo pronto, pudo racionar las monedas para mantener a sus hijos.', 28153),
(153289, 'esES', 'Tenemos algunos catres preparados en la planta de arriba y en el sótano tienes espacio para guardar tu equipo.\n\nNo es mucho, pero es mejor que estar ahí fuera con las brujas.', 'Tenemos algunos catres preparados en la planta de arriba y en el sótano tienes espacio para guardar tu equipo. No es mucho, pero es mejor que estar ahí fuera con las brujas.', 28153),
(153288, 'esES', 'Algunos marineros consideran que traen mala suerte, que es casi tentar al destino. Otros quieren que sus seres queridos no tengan que esperar malas noticias. No envidio a ninguno.', 'Algunos marineros consideran que traen mala suerte, que es casi tentar al destino. Otros quieren que sus seres queridos no tengan que esperar malas noticias. No envidio a ninguno.', 28153),
(153287, 'esES', 'Recuerda, mientras los árboles sigan en pie, debemos resistir. No podemos malgastar nuestras vidas aquí.', '', 28153),
(153286, 'esES', 'Busquemos a algunos de los nuestros. Juntos, tal vez podamos curar algunos de los males de Drustvar.', '', 28153),
(153285, 'esES', '', '¡Pero...!', 28153),
(153284, 'esES', 'Tenemos todo lo importante en esa arboleda, pimpollo. Si los fungáricos no hubieran atacado, la corrupción del sur nos habría alcanzado.', '', 28153),
(153283, 'esES', '', '¿Irnos? ¿Adónde? Copacinérea es nuestro hogar, Morwin. Y está cubierto de esporas. ¡No podemos abandonarlo sin más!', 28153),
(153282, 'esES', 'Bien hecho, Amalie. Supongo que ya podemos irnos.', '', 28153),
(153278, 'esES', '¿Qué puedes contarme acerca de este tallomar?', '¿Qué puedes contarme acerca de este tallomar?', 28153),
(153277, 'esES', 'Percusión', 'Percusión', 28153),
(153276, 'esES', '|cFF0000FF(Misión)|r Viaja en barco a Zuldazar.', '|cFF0000FF(Misión)|r Viaja en barco a Zuldazar.', 28153),
(153275, 'esES', '¡Ah, estoy recuperando las fuerzas!', '', 28153),
(153274, 'esES', 'Las cosas estaban tranquilas aquí. Luego hubo una tormenta y los demás buscadores ya no volvieron, $c. ¿Qué está pasando ahí fuera?', '', 28153),
(153273, 'esES', 'Te lo agradezco profundamente, puedes quedarte con parte de mi alijo personal por las molestias. Ahora debo partir en mi transporte, ¡buen trabajo!', '', 28153),
(153272, 'esES', 'Vaya, parece que estoy en un aprieto. Ten la amabilidad de ayudarme.', '', 28153),
(153271, 'esES', 'Vaya, gracias, eres un encanto. Toma, esto es para ti. ¡Chao!', 'Vaya, gracias, eres un encanto. Toma, esto es para ti. ¡Chao!', 28153),
(153270, 'esES', '', '¡Eh, tú! ¡Tienes que ayudarme, cielo! Estoy aquí sola y desesperada, ¿sabes?', 28153),
(153269, 'esES', 'Bueno, no voy a darte toda mi azerita. Toma, esta bastará para agradecerte tu amabilidad y para que te apartes de mi camino.', '', 28153),
(153268, 'esES', 'Muy bien, ¿me ayudas a salir de este embrollo?', '', 28153),
(153267, 'esES', '¡Mira, solo es un disfraz! ¿Lo ves? ¡Tócalo!$b$b¿Les dirás que me saquen de aquí? ¡Solo era una broma! ¡No es verdad que Hogger estuviera aterrorizando a la gente de Ventormenta!', '¡Mira, solo es un disfraz! ¿Lo ves? ¡Tócalo!$b$b¿Les dirás que me saquen de aquí? ¡Solo era una broma! ¡No es verdad que Hogger estuviera aterrorizando a la gente de Ventormenta!', 28153),
(153266, 'esES', '', '¡Gracias! Supongo que querrás un poco de mi azerita. Es justo.', 28153),
(153265, 'esES', '', '¡Oye, tú! ¿Crees que podrías ayudarme a salir de aquí?', 28153),
(153264, 'esES', '', 'Supongo que me lo merezco.', 28153),
(153263, 'esES', '', 'Aceptaré mi castigo...', 28153),
(153262, 'esES', '¡Ha regresado para matarnos!', '', 28153),
(153261, 'esES', '¡Asesina!', '¡Asesina!', 28153),
(153260, 'esES', '¡Traidora!', '¡Traidora!', 28153),
(153259, 'esES', '¡Es la hija del mar!', '', 28153),
(153258, 'esES', '', 'Lady Jaina... ¿De verdad es ella?', 28153),
(153257, 'esES', '', 'Ven, nos vamos a casa. ¡Rápido!', 28153),
(153256, 'esES', 'Mami, ¿quién es esa mujer?', 'Mami, ¿quién es esa mujer?', 28153),
(153255, 'esES', 'Hamlet... te han trufado...', '', 28153),
(153254, 'esES', 'Mi cabeza... ¿Qué les ha pasado a mis cerdos?', '', 28153),
(153253, 'esES', 'Contaré historias sobre tu gran victoria de hoy aquí, así que... ¡no pierdas!', '', 28153),
(153252, 'esES', '¡Regresa al Bosque Carmesí!', '¡Regresa al Bosque Carmesí!', 28153),
(153250, 'esES', '¡Mantened a los civiles alejados! ¡Formad un perímetro!', '', 28153),
(153249, 'esES', '%s huye.', '%s huye.', 28153),
(153248, 'esES', '', 'Pero ahora me consideran una criminal.', 28153),
(153247, 'esES', '', 'La guardia sigue siendo igual de disciplinada. Era el orgullo de mi padre.', 28153),
(153246, 'esES', '¡No me metas prisa! ¡Estoy intentando salvar a tu amo!', '', 28153),
(153245, 'esES', '¡Eh, $n! ¡Aquí!', '¡Eh, $n! ¡Aquí!', 28153),
(153244, 'esES', '¡Qué suerte la mía! Voy de camino a Dol\'watha y mi behtia se pone enferma. Eh como eso que dicen. Si algo puede salir mal, saldrá mal.', '', 28153),
(153243, 'esES', '¡Soy Rally!', '¡Soy Rally!', 28153),
(153242, 'esES', 'Ahí fuera hay mucha sangre de la Horda que derramar. Déjame un poco, ¿vale?', 'Ahí fuera hay mucha sangre de la Horda que derramar. Déjame un poco, ¿vale?', 28153),
(153241, 'esES', 'Hagamos sufrir a nuestra víctima.', 'Hagamos sufrir a nuestra víctima.', 28153),
(153240, 'esES', 'Tenemos órdenes de matar.', 'Tenemos órdenes de matar.', 28153),
(153239, 'esES', '', 'No te alejes. No podemos permitir que nos descubran.', 28153),
(153238, 'esES', '', 'Céntrate.', 28153),
(153237, 'esES', '', 'Vas a conseguir que nos vean.', 28153),
(153236, 'esES', 'Oye, Boris... Creo que nuestros días de saqueo han terminado...', '', 28153),
(153235, 'esES', '¡Ni se te ocurra tocar a mi bestia!', '', 28153),
(153234, 'esES', 'Así me gusta. ¡Mira cuánta azerita!', '', 28153),
(153233, 'esES', '¡$gJefe:Jefa;! ¡Estás aquí!', '', 28153),
(153231, 'esES', '¡Abrid paso! ¡Traemos a una prisionera peligrosa!', '', 28153),
(153230, 'esES', '¡Alto! ¿A qué habéis venido?', '', 28153),
(153229, 'esES', '', 'No tenemos tiempo para ir de paseo.', 28153),
(153228, 'esES', 'Ca... cállate.', '', 28153),
(153227, 'esES', 'Vaya... ¡Puede que lo matara una BRUJA!', '', 28153),
(153226, 'esES', 'Otro de tus exploradores, Gallywix... y este está muerto.', '', 28153),
(153225, 'esES', '¡Debemos avanzar al centro de la ciudad para evacuar al resto de ciudadanos!', '', 28153),
(153224, 'esES', 'Cu... cuidado...', '', 28153),
(153223, 'esES', '', '¡Ya casi estamos! ¡Aprisa, héroes!', 28153),
(153222, 'esES', '', '¡No os detengáis!', 28153),
(153220, 'esES', '¡Campeones, conmigo! ¡Nos reuniremos en la fortaleza! ¡Órdenes de la Jefa de Guerra!', '', 28153),
(153217, 'esES', '', 'Colmillosauro, ¿dónde te has metido?', 28153),
(153216, 'esES', '¡Ten cuidado, los campos hundidos aún son peligrosos! El camino que hay a la derecha debería ser un poco más seguro y te conducirá al molino. La granja de Deal está justo después.', '', 28153),
(153215, 'esES', '', 'Si no le haces ascos a una buena pelea, me vendría bien tu ayuda.', 28153),
(153214, 'esES', '', 'Se me han acabado las pociones y, con tanto sethrak, no puedo llegar a mi carro.', 28153),
(153213, 'esES', '', '¿Aún sigues con vida? ¿Qué tal manejas esa arma?', 28153),
(153212, 'esES', '', '¡De eso nada, gusanos!', 28153),
(153211, 'esES', 'Por favor, devuélveme a la entrada.', 'Por favor, devuélveme a la entrada.', 28153),
(153210, 'esES', 'El avatar de Sethraliss ha rejuvenecido gracias a tu esfuerzo y al de tus aliados.', 'El avatar de Sethraliss ha rejuvenecido gracias a tu esfuerzo y al de tus aliados.', 28153),
(153209, 'esES', 'Magni, envíame de vuelta a Zandalar.', 'Magni, envíame de vuelta a Zandalar.', 28153),
(153207, 'esES', 'Esto nos llevará a nuestro destino. Ven conmigo, adalid.', '', 28153),
(153206, 'esES', 'Derrota a cualquier intruso que quede.', 'Derrota a cualquier intruso que quede.', 28153),
(153205, 'esES', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t¡El avatar se une a ti y te |cFFFF0000|Hspell:269670|h[potencia]|h|r para terminar la pelea!', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t¡El avatar se une a ti y te |cFFFF0000|Hspell:269670|h[potencia]|h|r para terminar la pelea!', 28153),
(153204, 'esES', '<Ves al avatar de Sethraliss frente a ti. Está viva, pero muy débil a causa de la intromisión de los trols. A tu alrededor, los antiguos resguardos defensivos cobran vida...>.', '<Ves al avatar de Sethraliss frente a ti. Está viva, pero muy débil a causa de la intromisión de los trols. A tu alrededor, los antiguos resguardos defensivos cobran vida...>.', 28153),
(153203, 'esES', '|cffffff00+$1i de madera|r', '|cffffff00+$1i de madera|r', 28153),
(153202, 'esES', '¡Ya habéis oído a la Princesa! ¡Vamos allá!', '', 28153),
(153201, 'esES', '', '¡El ehcudo! ¡Ehtá desapareciendo!', 28153),
(153199, 'esES', '¡Que no cunda el pánico! Aunque puede que mi entrada haya sido algo abrupta... Soy Magni Barbabronce, portavoz de Azeroth.', '', 28153),
(153198, 'esES', '', 'Ah, ahí ehtáh. Ven, tenemoh planeh que hacer.', 28153),
(153197, 'esES', 'Ah, ahí estás. ¡Tengo que hablar contigo!', '', 28153),
(153196, 'esES', '[IGC: Audiencia con Katherine: Jaina deja su destino en manos de Katherine. Instada por lady Gobernalle a tratar a Jaina como una traidora, Katherine permite que se lleven a Jaina para enfrentarse a la justicia. \"Está muerta para mí\". Detienen al jugador.]', '[IGC: Audiencia con Katherine: Jaina deja su destino en manos de Katherine. Instada por lady Gobernalle a tratar a Jaina como una traidora, Katherine permite que se lleven a Jaina para enfrentarse a la justicia. \"Está muerta para mí\".]', 28153),
(153195, 'esES', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:265212|h[Gestar]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:265212|h[Gestar]|h|r!', 28153),
(153194, 'esES', '¡Te sanaremos!', '¡Te sanaremos!', 28153),
(153193, 'esES', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t ¡Vectis empieza a lanzar |cFFFF0000|Hspell:265217|h[Licuar]|h|r!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t ¡Vectis empieza a lanzar |cFFFF0000|Hspell:265217|h[Licuar]|h|r!', 28153),
(153192, 'esES', 'No le hagas caso a Gallywix. Nos dirigimos a Drustvar para determinar la posición del enemigo. Las ganancias son algo secundario.', '', 28153),
(153191, 'esES', 'Ahora solo hay... silencio.', '', 28153),
(153190, 'esES', 'Oh, me muero...', '', 28153),
(153189, 'esES', 'Asegúrate de que Eitrigg y el capitán están listos. ¡Tenemos mucho dinero que ganar!', '', 28153),
(153188, 'esES', 'Me has.... liquidado', '', 28153),
(153187, 'esES', 'A partir de este momento... no volveré a pronunciar una palabra.', '', 28153),
(153186, 'esES', '¡Espera, ya basta!', '', 28153),
(153185, 'esES', '¡Miserable, me has asesinado!', '', 28153),
(153184, 'esES', '¡Oh, me has matado!', '', 28153),
(153183, 'esES', 'Mi espíritu se va, no puedo... más.', '', 28153),
(153182, 'esES', '', 'No. No haráh sufrir máh a mi gente. ¡Pondré fin a tu locura ahora!', 28153),
(153180, 'esES', '', '¡Así eh, Princesa!', 28153),
(153177, 'esES', 'Se crearon tres dispositivos para contener la corrupción.', '', 28153),
(153174, 'esES', '[Secuencia cinemática impresionante].', '[Secuencia cinemática impresionante].', 28153),
(153173, 'esES', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Vectis lanza |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Vectis lanza |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', 28153),
(153172, 'esES', '', '¡¿Un dioh antiguo?! Por eso loh trolh de sangre ehtán asaltando mi ciudad...', 28153),
(153171, 'esES', 'Datos recuperados. El origen de la corrupción es el dios antiguo que hay en Nazmir.', '', 28153),
(153169, 'esES', '¡Y cuatro litros y medio de tequila!', '¡Y cuatro litros y medio de tequila!', 28153),
(153168, 'esES', '|cFF0000FF(Misión)|r Viaja en barco a Drustvar.', '|cFF0000FF(Misión)|r Viaja en barco a Drustvar.', 28153),
(153167, 'esES', '', 'El Llanto del Alma en Pena es una de las mejores naves de la Dama Oscura. Tal vez no parezca gran cosa, pero es dura y tenaz.\n\nY tampoco tiene una mala capitana.', 28153),
(153166, 'esES', 'Sí, estoy listo para ir a Drustvar.', 'Sí, estoy lista para ir a Drustvar.', 28153),
(153165, 'esES', 'No te dejes engañar por ese goblin, $n. Nuestra misión es reunir INFORMACIÓN sobre la Alianza, no limitarnos a recoger toda la azerita posible.\n\n¿Estás a punto para partir?', '', 28153),
(153164, 'esES', 'No dejes que el príncipe mercante te confunda. Nuestro objetivo principal es el reconocimiento... no las ganancias.', '', 28153),
(153163, 'esES', 'He oído que hay mucha azerita ehperándonoh ahí fuera. Lo único que tenemoh que hacer eh cogerla, y eso depende de ti.\n\nSi te matan, ¡me pido tu sombrero! ¡Ja, ja!', '', 28153),
(153162, 'esES', 'Sigue sanando al avatar de Sethraliss mientras te encargas del resto de intrusos.', 'Sigue sanando al avatar de Sethraliss mientras te encargas del resto de intrusos.', 28153),
(153161, 'esES', 'Bien hecho. Debemos permanecer vigilantes y mantener el templo libre de la infestación Selvaraña.', '', 28153),
(153160, 'esES', 'Las Selvaraña infestan las ruinas del templo. Acaba con ellas y rescata a mis seguidores de sus telas de araña.', '', 28153),
(153159, 'esES', 'Restaurad toda la salud del Avatar.', 'Restaurad toda la salud del Avatar.', 28153),
(153158, 'esES', '¡Malditas arañas!', '', 28153),
(153157, 'esES', '¡Gracias, $n! Te debo la vida.', '', 28153),
(153156, 'esES', '¡Puedo volver a respirar! ¡Gracias!', '', 28153),
(153155, 'esES', '¡Esas arañas se lo comen todo!', '', 28153),
(153154, 'esES', '¡Gracias! Ha estado muy cerca...', '', 28153),
(153153, 'esES', '¡Creí que había llegado mi hora!', '', 28153),
(153152, 'esES', '¿Qué quieres de nosotros?', '¿Qué quieres de nosotros?', 28153),
(153151, 'esES', 'No, por favor...', 'No, por favor...', 28153),
(153150, 'esES', '', 'Entonces monta. Nos adelantaremos y buscaremos al maestro Ashton. Adalid, ¡nos vemos en el Bosque Carmesí!', 28153),
(153149, 'esES', '¡Mis huesos! ¡Qué dolor!', '¡Qué dolor! ¡Mis huesos!', 28153),
(153148, 'esES', 'Ah, cómo echaba esto de menos.', 'Ah, cómo echaba esto de menos.', 28153),
(153147, 'esES', 'Me aburres. Te haré más... interesante.', 'Me aburres. Te haré más... interesante.', 28153),
(153146, 'esES', 'Dime, ¿duele?', 'Dime, ¿duele?', 28153),
(153145, 'esES', 'Supongo que sí.', '', 28153),
(153144, 'esES', '', 'Marten, ¿estás en condiciones de viajar?', 28153),
(153143, 'esES', 'La ciudad está en buenas manos, así que... ¿podrías explicarme qué está pasando?', '', 28153),
(153142, 'esES', '¡Por supuesto! No sé por qué necesitas mi ayuda, ¡pero por los salvadores de mi hogar que la tendrás!\n\nNo obstante, puede que tengas que esperar un poco. No me cabe duda de que la ciudad está en ruinas.', '', 28153),
(153141, 'esES', '¡Tenemos que salir de aquí!', '¡Tenemos que salir de aquí!', 28153),
(153140, 'esES', '¡Ellos no, otra vez no!', '¡Ellos no, otra vez no!', 28153),
(153139, 'esES', 'Estaría muerto de no ser por ti...', 'Estaría muerta de no ser por ti...', 28153),
(153138, 'esES', '¡La Horda! ¿Qué hacen aquí?', '¡La Horda! ¿Qué hacen aquí?', 28153),
(153137, 'esES', '¡Levando anclas, Comandante!', '¡Levando anclas, Comandante!', 28153),
(153136, 'esES', 'Puedo llevarte allí más rápido de lo que vuela una gaviota. Avísame cuando estés $glisto:lista;.', '', 28153),
(153135, 'esES', '¿Estás buscando a Ashton? Camina conmigo. A él no lo he visto, pero a su aprendiz sí.', '', 28153),
(153134, 'esES', 'Uf. Esto no es para timoratos... ni estómagos débiles.', '', 28153),
(153133, 'esES', 'Una vez oí hablar de un rico tentempié típico de un desierto al otro lado del mar. Consigue algunas alas de buitre y unos aguijones de escórpido. Voy a hacer una nueva versión, algo con chispa.', '', 28153),
(153132, 'esES', 'Con cautela, timonel.', 'Con cautela, timonel.', 28153),
(153131, 'esES', 'No, idiota, ¡hacia el otro lado!', 'No, idiota, ¡hacia el otro lado!', 28153),
(153130, 'esES', 'LOS IMPUROS NO ENTRARÁN EN LAS CÁMARAS DE LOS MUERTOS.', '', 28153),
(153129, 'esES', 'NO PODÉIS PASAR.', '', 28153),
(153128, 'esES', 'NADIE PUEDE ENTRAR.', '', 28153),
(153127, 'esES', 'Nos vemos.', '', 28153),
(153126, 'esES', 'Eh.', '', 28153),
(153125, 'esES', '', 'He fracasado como profesora.', 28153),
(153124, 'esES', '', 'Es la hora del recreo.', 28153),
(153123, 'esES', '', 'Os podéis... retirar todos.', 28153),
(153122, 'esES', '', '¡Estamos dando clase!', 28153),
(153121, 'esES', '', 'Es la hora de enseñarte las tres erres: ¡runas, rituales y reliquias!', 28153),
(153120, 'esES', '', '¡Necesitas una buena lección!', 28153),
(153119, 'esES', '¿Quién vigilará las reservas ahora?', '', 28153),
(153118, 'esES', 'Esta remesa... se ha estropeado.', '', 28153),
(153117, 'esES', '¡Prohibido tocar nuestras reservas!', '', 28153),
(153116, 'esES', '¡Esta colección es solo para los invitados!', '', 28153),
(153115, 'esES', '¡Excelente! Estas nos durarán bastante. Si no me las como todas de una vez, claro.', '', 28153),
(153114, 'esES', 'Te sorprendería cómo se adaptan las cosas a este entorno. Los azotadores tienen las semillas más resistentes... ¡y ricas! ¡Trae unas pocas, pero cuidado con las espinas!', '', 28153),
(153113, 'esES', 'Me gusta cómo piensas, Walt.', '', 28153),
(153112, 'esES', 'O... Ya nos han pagado, ¿por qué no le decimos a Vaderia que nos han atacado... y nos bebemos el hidromiel?', '', 28153),
(153111, 'esES', 'De acuerdo... Creo que ahora es seguro. Llevemos estos barriles a Vaderia.', '', 28153),
(153110, 'esES', 'Saldré a buscar pistas sobre James mientras te ocupas de que el barco vuelva. No permitiré que permanezca en las garras de esos desgraciados escurridizos.', 'Saldré a buscar pistas sobre James mientras te ocupas de que el barco vuelva. No permitiré que permanezca en las garras de esos desgraciados escurridizos.', 28153),
(153109, 'esES', '¡Esa cosa chorrea miel!', '', 28153),
(153108, 'esES', '¡Ven aquí, gaviota idiota!', '', 28153),
(153107, 'esES', 'Bueno... Estoy más preparado que nunca. ¡A ver qué sabes hacer, naturaleza!', '', 28153),
(153106, 'esES', '¡Vamos allá!', '¡Vamos allá!', 28153),
(153105, 'esES', 'Llegarán más bestias feroces en cualquier momento, $c. ¡Protege el hidromiel como si tu vida dependiera de ello!', '', 28153),
(153103, 'esES', '¡Ánimo, Bradford! ¡No podemos dejarnos vencer!', '', 28153),
(153102, 'esES', 'Bueno, Walt, este es nuestro final. ¡No sé cuántas bestias más podremos repeler!', '', 28153),
(153101, 'esES', '%s gira un cañón de azerita completamente cargado hacia la torre de asedio.', '', 28153),
(153100, 'esES', '¡$n! ¡Te necesitamos, rápido!', '¡$n! ¡Te necesitamos, rápido!', 28153),
(153099, 'esES', '¡Maldita sea, Leonard, no te he dado permiso para irte!', '¡Maldita sea, Leonard, no te he dado permiso para irte!', 28153),
(153098, 'esES', 'Los demás, seguidme, vamos a maniobrar por su flanco.', 'Los demás, seguidme, vamos a maniobrar por su flanco.', 28153),
(153097, 'esES', 'Qué pequeñas viajeras tan preciosas y fascinantes. Me pregunto qué historias me desvelarán.', '', 28153),
(153096, 'esES', 'Normalmente las revoloteadoras solo viven unos cuantos meses, pero estas de aquí son diferentes. Tráeme algunas, pero trátalas con cuidado. Son muy delicadas.', '', 28153),
(153093, 'esES', '', '¿Quién vigilará los terrenos ahora?', 28153),
(153092, 'esES', '', 'Vuelvo a la tierra.', 28153),
(153091, 'esES', '', 'Serás un buen fertilizante.', 28153),
(153090, 'esES', '', '¡Recogerás lo que siembres!', 28153),
(153089, 'esES', '', '¡Intrusos en mi jardín!', 28153),
(153088, 'esES', '', 'Raído.', 28153),
(153087, 'esES', '', 'Mis planes... deshilachados.', 28153),
(153086, 'esES', '', '¡Mi tejido presagia tu perdición!', 28153),
(153085, 'esES', '', '¡Tu final se acerca!', 28153),
(153084, 'esES', '', '¡Tejeré vuestras almas en mi tapiz!', 28153),
(153083, 'esES', 'Una buena cacería para terminar.', '', 28153),
(153082, 'esES', 'Qué ferocidad.', '', 28153),
(153081, 'esES', 'Nunca pensé... que me convertiría en el trofeo.', '', 28153),
(153080, 'esES', '¡Hora de atacar!', '', 28153),
(153079, 'esES', '¡Os uniréis a la magnífica colección de trofeos de mi pared!', '', 28153),
(153078, 'esES', '¡Se abre la veda!', '', 28153),
(153077, 'esES', '¡Carne fresca para asar!', '', 28153),
(153076, 'esES', '¡A cenar!', '', 28153),
(153075, 'esES', 'El santuario debe abrirse una vez más. ¡Es la hora de la redención!', '', 28153),
(153074, 'esES', 'Esta oscuridad no nos va a cortar el paso.', '', 28153),
(153073, 'esES', 'Buen trabajo. Nunca olvidaremos a los bravos alfazaques del barranco que dieron su vida para salvarnos del régimen del terror del rey Rakataka.', '', 28153),
(153072, 'esES', 'Los vulperas matamos por menos, ¿sabes?', '', 28153),
(153071, 'esES', 'Parece que la disciplina y el tacto no son tu punto fuerte.', '', 28153),
(153070, 'esES', 'Todo tiene valor, incluso tú.', '', 28153),
(153069, 'esES', 'Las arenas se tragan a los derrochadores.', '', 28153),
(153068, 'esES', 'Las arenas nos mostrarán el camino.', '', 28153),
(153067, 'esES', 'Las arenas guían nuestros pasos.', '', 28153),
(153066, 'esES', 'Las dunas tienen todo lo que necesitamos.', '', 28153),
(153065, 'esES', 'Sobrevivir a las arenas implica saber valorar lo olvidado.', '', 28153),
(153064, 'esES', 'Recuerda, todo tiene un uso.', '', 28153),
(153063, 'esES', 'Habla con libertad.', '', 28153),
(153062, 'esES', 'Hola.', '', 28153),
(153061, 'esES', '¿Qué has traído?', '', 28153),
(153060, 'esES', '¿Has venido a comerciar?', '', 28153),
(153059, 'esES', '¿Necesitas algo?', '', 28153),
(153058, 'esES', '', 'Zandalar prevalecerá.', 28153),
(153057, 'esES', '', 'Ve con cuidado.', 28153),
(153056, 'esES', '', 'Lah arenah son un dehtino que nadie merece.', 28153),
(153055, 'esES', '', '¿Qué puedo hacer por ti?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'esES', '', 'Ve al grano.', 28153),
(153053, 'esES', '', 'Te ehcucho.', 28153),
(153052, 'esES', '', '¿Sí?', 28153),
(153051, 'esES', 'Nunca nos rendiremos.', 'Nunca nos rendiremos.', 28153),
(153050, 'esES', 'El imperio de los infieles caerá.', 'El imperio de los infieles caerá.', 28153),
(153049, 'esES', 'Que Sethraliss nos salve a todos.', 'Que Sethraliss nos salve a todos.', 28153),
(153048, 'esES', 'Korthek nos ha traído esta guerra.', 'Korthek nos ha traído esta guerra.', 28153),
(153047, 'esES', 'Debemos mantenernos fuertes.', 'Debemos mantenernos fuertes.', 28153),
(153046, 'esES', '¿Has venido a ayudar?', '¿Has venido a ayudar?', 28153),
(153045, 'esES', '¡El rey Rakataka está aterrorizando el Barranco Pistahueso! Es demasiado poderoso como para atacarlo directamente, pero tiene un apetito insaciable. Si le traes comida, morirá empachado.', '', 28153),
(153044, 'esES', 'Los vulperas matamos por menos, ¿sabes?', 'Los vulperas matamos por menos, ¿sabes?', 28153),
(153043, 'esES', 'Parece que la disciplina y el tacto no son tu punto fuerte.', 'Parece que la disciplina y el tacto no son tu punto fuerte.', 28153),
(153042, 'esES', 'Todo tiene valor, incluso tú.', 'Todo tiene valor, incluso tú.', 28153),
(153041, 'esES', 'Afina tu velocidad y tu ingenio.', 'Afina tu velocidad y tu ingenio.', 28153),
(153040, 'esES', 'Sin ingenio, no hay supervivencia.', 'Sin ingenio, no hay supervivencia.', 28153),
(153039, 'esES', '¡Recuerda, todo tiene un uso!', '¡Recuerda, todo tiene un uso!', 28153),
(153038, 'esES', 'Las dunas tienen todo lo que necesitamos.', 'Las dunas tienen todo lo que necesitamos.', 28153),
(153037, 'esES', 'Cuídate. Nadie lo hará por ti.', 'Cuídate. Nadie lo hará por ti.', 28153),
(153036, 'esES', 'Procura que no te maten.', 'Procura que no te maten.', 28153),
(153035, 'esES', '¿Qué me has traído?', '¿Qué me has traído?', 28153),
(153034, 'esES', '¿Necesitas algo?', '¿Necesitas algo?', 28153),
(153033, 'esES', '¿Has venido a comerciar?', '¿Has venido a comerciar?', 28153),
(153032, 'esES', 'Hola.', 'Hola.', 28153),
(153031, 'esES', '¿Tienes algo para mí?', '¿Tienes algo para mí?', 28153),
(153030, 'esES', '¡Tráeme un trofeo de tu próxima aventura!', '¡Tráeme un trofeo de tu próxima aventura!', 28153),
(153029, 'esES', '¿Ahora somos amigos?', '¿Ahora somos $gamigos:amigas;?', 28153),
(153028, 'esES', 'Gracias por hablar conmigo.', 'Gracias por hablar conmigo.', 28153),
(153027, 'esES', '¿Estás viviendo una gran aventura? ¡Qué guay!', '¿Estás viviendo una gran aventura? ¡Qué guay!', 28153),
(153026, 'esES', '¿Alguna vez has tragado arena a propósito?', '¿Alguna vez has tragado arena a propósito?', 28153),
(153025, 'esES', 'Si mueres, ¿puedo quedarme con tus cosas?', 'Si mueres, ¿puedo quedarme con tus cosas?', 28153),
(153024, 'esES', 'Nunca nos rendiremos.', '', 28153),
(153023, 'esES', 'El imperio de los infieles caerá.', '', 28153),
(153022, 'esES', 'Que Sethraliss nos salve a todos.', '', 28153),
(153021, 'esES', 'Korthek nos ha traído esta guerra.', '', 28153),
(153020, 'esES', 'Debemos mantenernos fuertes.', '', 28153),
(153019, 'esES', '¿Has venido a ayudar?', '', 28153),
(153018, 'esES', 'Haremos lo que haga falta.', '', 28153),
(153017, 'esES', 'Sethraliss nos salvará.', '', 28153),
(153016, 'esES', '¡Los infieles no tomarán nuestro templo!', '', 28153),
(153015, 'esES', 'Korthek nos ha traído esta guerra.', '', 28153),
(153014, 'esES', 'Debemos mantenernos fuertes.', '', 28153),
(153013, 'esES', '¿Has venido a ayudar?', '', 28153),
(153012, 'esES', '', 'No deberíamos haberte salvado. ¡Espera! No lo digo en serio...', 28153),
(153011, 'esES', '', 'No me creo que lo hayas vuelto a hacer...', 28153),
(153010, 'esES', '', 'Deberías parar, en serio.', 28153),
(153009, 'esES', '', '¿Qué estás haciendo?', 28153),
(153008, 'esES', '', 'Volverás, ¿verdad?', 28153),
(153007, 'esES', '', '¡Vuelve de una pieza!', 28153),
(153006, 'esES', '', 'Viajar en solitario es peligroso.', 28153),
(153005, 'esES', '', 'Le caes bien a Dolly, lo noto.', 28153),
(153004, 'esES', '', 'Conozco estas dunas mejor que nadie.', 28153),
(153003, 'esES', '', '¡Hola!', 28153),
(153002, 'esES', '', '¡Puedo ayudar!', 28153),
(153001, 'esES', '', 'La ciudad no caerá.', 28153),
(153000, 'esES', '', 'Ve con cuidado.', 28153),
(152999, 'esES', '', 'He jurado defender a la familia real.', 28153),
(152998, 'esES', '', 'Prevaleceremoh.', 28153),
(152997, 'esES', '', 'Ve al grano.', 28153),
(152996, 'esES', '', '¿Sí?', 28153),
(152995, 'esES', '', 'Te ehcucho.', 28153),
(152994, 'esES', 'Que lah arenah se traguen mih pecadoh.', '', 28153),
(152993, 'esES', 'Lah arenah nunca serán segurah.', '', 28153),
(152992, 'esES', 'Hay cosah que no se pueden deshacer.', '', 28153),
(152991, 'esES', '¿Qué necesitah?', '', 28153),
(152990, 'esES', 'Si puedo ayudar, lo haré.', '', 28153),
(152989, 'esES', 'Merezco mi dehtino.', '', 28153),
(152988, 'esES', 'Aléjate mientrah puedah.', '', 28153),
(152987, 'esES', 'No te pierdo de vihta.', '', 28153),
(152986, 'esES', 'Ve con cuidado.', '', 28153),
(152985, 'esES', 'Ehte no eh tu sitio.', '', 28153),
(152984, 'esES', 'No tengo tiempo pa ti.', '', 28153),
(152983, 'esES', '¿Qué quiereh?', '', 28153),
(152982, 'esES', 'Que la tormenta te guíe.', '', 28153),
(152981, 'esES', 'No temas la tormenta.', '', 28153),
(152980, 'esES', 'La claridad llega tras la tormenta.', '', 28153),
(152979, 'esES', 'La tormenta llama.', '', 28153),
(152978, 'esES', 'Todo el mundo es bienvenido aquí.', '', 28153),
(152977, 'esES', 'Yo soy la tormenta.', '', 28153),
(152976, 'esES', '¿Qué te trae por aquí?', '', 28153),
(152975, 'esES', '¡El festín está listo!', '', 28153),
(152973, 'esES', '', 'Me vendría bien un casco nuevo...', 28153),
(152972, 'esES', '', 'Me acuerdo que un sethrak también me dio un toquecito una vez... una.', 28153),
(152971, 'esES', '', 'Parte con furia y premura.', 28153),
(152970, 'esES', '', 'Que el viento te impulse y la espada te guarde.', 28153),
(152969, 'esES', '', 'Haz que te teman.', 28153),
(152968, 'esES', '', 'Deja algunos sethrak para mí.', 28153),
(152967, 'esES', '', 'Nunca dejes de luchar.', 28153),
(152966, 'esES', '', 'Dime: ¿a cuántos sethrak has matado?', 28153),
(152965, 'esES', '', 'Hoy es un buen día para luchar. Siempre lo es.', 28153),
(152964, 'esES', '', 'Los vulperas somos más fuertes de lo que parecemos.', 28153),
(152963, 'esES', '', 'Mi pueblo será libre.', 28153),
(152962, 'esES', '', 'Estoy lista para luchar.', 28153),
(152961, 'esES', 'Mi vida por el Rey.', '', 28153),
(152960, 'esES', 'Mantén tu arma preparada.', '', 28153),
(152959, 'esES', 'Que loh loa te acompañen.', '', 28153),
(152958, 'esES', 'Zandalar resihte.', '', 28153),
(152957, 'esES', 'Me enfrentaré al peligro.', '', 28153),
(152956, 'esES', 'Nuehtroh enemigoh caerán.', '', 28153),
(152955, 'esES', '', 'Oh, no lo dudo.', 28153),
(152954, 'esES', 'No te fallaremos, mi reina.', '', 28153),
(152953, 'esES', '', '¿Aceptarás esta tarea?', 28153),
(152952, 'esES', '', 'Te infiltrarás en Ventormenta y liberarás a un preso político que podría cambiar el curso de esta guerra a nuestro favor.', 28153),
(152951, 'esES', '', 'El niño rey tiene algo que no le pertenece. Quiero recuperarlo.', 28153),
(152950, 'esES', '', 'Para ganar esta guerra, la Horda necesita aliados.', 28153),
(152949, 'esES', '', 'Pero existe un criterio detrás de mis actos.', 28153),
(152948, 'esES', '', 'Algunos miembros de la Horda consideran que últimamente he sido algo... imprudente.', 28153),
(152947, 'esES', '', 'Requiero los servicios de alguien en quien pueda confiar plenamente.', 28153),
(152946, 'esES', '', 'Ah, ahí estás. Empezaba a preocuparme.', 28153),
(152945, 'esES', '... a la Horda.', '', 28153),
(152944, 'esES', 'Sus consejeros son leales...', '', 28153),
(152943, 'esES', 'Quizás mi Reina sería más abierta si pudiese confiar en su lealtad.', '', 28153),
(152942, 'esES', '¿Cómo podemos ayudar a la Jefa de Guerra si oculta información a sus consejeros?', '', 28153),
(152941, 'esES', 'Esto no te incumbe.', '', 28153),
(152940, 'esES', '¿Te ha llamado la Jefa de Guerra?', '', 28153),
(152939, 'esES', 'Ni siquiera yo sé de qué se trata.', '', 28153),
(152938, 'esES', 'Nuestra Jefa de Guerra te encarga una misión de gran importancia... y discreción.', '', 28153),
(152937, 'esES', '¡Dile a tuh amigoh que visiten la Posada Colmillo Dorado!', '', 28153),
(152936, 'esES', 'No olvideh firmar el libro de invitadoh.', '', 28153),
(152935, 'esES', 'Te necesito con vida.', '', 28153),
(152934, 'esES', 'Eh, ¿tieneh plátanoh?', '', 28153),
(152933, 'esES', 'Loh Colmillo Dorado no mienten.', '', 28153),
(152932, 'esES', '¡Ehtáh en la Posada Colmillo Dorado!', '', 28153),
(152931, 'esES', 'Motín o penol.', '', 28153),
(152930, 'esES', 'Cuida de tu tripulación.', '', 28153),
(152929, 'esES', 'Cuidado con lah profundidadeh.', '', 28153),
(152928, 'esES', 'No solo llora la muerte de su marido caído en Theramore, sino que además ese día también perdió a su hija.', '', 28153),
(152927, 'esES', '¡Deja de cotorrear! Tampoco hay que contárselo a todo el mundo.', '¡Deja de cotorrear! Tampoco hay que contárselo a todo el mundo.', 28153),
(152926, 'esES', '¡Silencio! Aquí hay algo bueno.', '¡Silencio! Aquí hay algo bueno.', 28153),
(152925, 'esES', '¡Silencio! No queremos que nadie empiece a hacer preguntas.', '¡Silencio! No queremos que nadie empiece a hacer preguntas.', 28153),
(152924, 'esES', 'Zem\'lan no eh lugar pa loh vivoh.', '', 28153),
(152923, 'esES', '¿Buhcah tripulación?', '', 28153),
(152921, 'esES', '¡Ah del barco!', '', 28153),
(152920, 'esES', 'Katherine soporta una enorme carga. No me extraña que el regreso de Jaina le haya afectado tanto.', '', 28153),
(152918, 'esES', '', 'Debemos unir las casas bajo el estandarte de los Valiente y encontrar a la flota perdida. De lo contrario, Kul Tiras podría hundirse incluso antes de la guerra.', 28153),
(152917, 'esES', 'Mi clan fue exterminado por el Martillo Crepuscular. Solo pude escapar porque mi hermano Keeland me prestó su grifo. Me salvó la vida.\n\nViajé por casi todo el mundo antes de asentarme aquí, en Kul Tiras. Esta gente cazaba grifos para conseguir carne y pieles. Les enseñé que había otra forma de hacer las cosas. Ahora se han convertido en la nueva generación de jinetes de grifos.\n\nNo creo que vuelva a casa. Este es mi clan ahora.', '', 28153),
(152916, 'esES', 'Llévame de vuelta a Zul\'jan.', 'Llévame de vuelta a Zul\'jan.', 28153),
(152915, 'esES', 'Serrando', 'Serrando', 28153),
(152914, 'esES', '¿Qué hace aquí un enano Martillo Salvaje?', '¿Qué hace aquí un enano Martillo Salvaje?', 28153),
(152913, 'esES', 'Con este botín seremos ricos.', 'Con este botín seremos ricos.', 28153),
(152912, 'esES', 'Los idiotas no entienden el valor de lo que hay bajo sus pies.', 'Los idiotas no entienden el valor de lo que hay bajo sus pies.', 28153),
(152911, 'esES', 'Conozco a un comprador en Lunargenta que pagará una buena suma por estas reliquias.', 'Conozco a un comprador en Lunargenta que pagará una buena suma por estas reliquias.', 28153),
(152910, 'esES', 'Nada de esto acabará en un museo.', '', 28153),
(152907, 'esES', 'No hay lugar seguro en Nazmir, pero ehte sitio parece ehpecialmente peligroso. Permanece alerta.', '', 28153),
(152906, 'esES', '¡Hezrel parece ocupado! ¿Qué andará haciendo ahí abajo?', '', 28153),
(152905, 'esES', 'Contábamoh con Hezrel en el combate, pero fue a ocuparse de unoh asuntoh. ¿Qué ehtará tramando ese ensamblaje?', '', 28153),
(152900, 'esES', 'Que nadie toque mi tesoro.', 'Aunque me hunda, volveré...', 28153),
(152899, 'esES', 'Ehta tierra ehtá maldita... todoh lo ehtamoh.', 'Zem\'lan no noh deja morir... Esa eh la verdadera maldición.', 28153),
(152898, 'esES', 'No siento nada...', '¡Malditoh marineroh de agua dulce!', 28153),
(152897, 'esES', 'El Capitán... se enterará...', 'Rehponderáh... ante el rey pirata Zem\'lan por ehto...', 28153),
(152896, 'esES', 'Bajemos volando y reunámonos con el guardián de los titanes Hezrel.', 'Bajemos volando y reunámonos con el guardián de los titanes Hezrel.', 28153),
(152895, 'esES', '', 'Debo informar a mi padre de lo sucedido. Hemoh obtenido una importante victoria, pero la guerra contra loh trolh de sangre continúa.', 28153),
(152894, 'esES', '', 'No olvidaré todo lo que la Horda ha hecho por mi gente. Sin vosotroh, nada de ehto habría sido posible.', 28153),
(152893, 'esES', '', '¡A tus órdenes!', 28153),
(152892, 'esES', '', '¡La caverna se derrumba! ¡Corred!', 28153),
(152891, 'esES', 'Podéis perecer entre estos escombros o dejar que os despedacen mis vasallos, pero no viviréis para ver mi victoria.', '', 28153),
(152890, 'esES', '', '¡Te llevaré conmigo!', 28153),
(152889, 'esES', '', '¡Un poco más cerca!', 28153),
(152888, 'esES', '', '¡Esto va a ser la bomba!', 28153),
(152887, 'esES', '', '¡Venga, dame un abrazo!', 28153),
(152886, 'esES', '¡Sígueme! Rápido, ¡y no te alejes!', '¡Sígueme! Rápido, ¡y no te alejes!', 28153),
(152885, 'esES', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|t¡Un |cFFFF0000|Hspell:269131|h[Dominamentes ancestral]|h|r se aferra a |cFFFF0000$n|r!', '', 28153),
(152884, 'esES', 'Tercera Flota, ¡preparaos! ¡Presentaos ante el rey Cringrís de inmediato!', 'Tercera Flota, ¡preparaos! ¡Presentaos ante el rey Cringrís de inmediato!', 28153),
(152883, 'esES', 'No, déjalo. Es cerveza. Todo bien.', '', 28153),
(152882, 'esES', '', '.', 28153),
(152881, 'esES', '', 'Nuehtrah tropah ehtán rechazando a loh trolh de sangre, pero no resihtirán eternamente. Hay que acabar con ehto.', 28153),
(152880, 'esES', '', '.', 28153),
(152879, 'esES', '', '¡Pero hace meses que nadie sabe nada de la flota!\nLos Sabiomar se han retirado a sus claustros y no parecen estar interesados en encontrar los barcos desaparecidos.', 28153),
(152878, 'esES', '', 'La casa Crestavía ha sido leal a los Valiente durante siglos, pero últimamente no asisten a las reuniones del consejo y empiezan a correr rumores inquietantes.', 28153),
(152877, 'esES', '¡Vuelve, preciosa!', '', 28153),
(152876, 'esES', 'No iba a dejar que se enfriara.', 'No iba a dejar que se enfriara.', 28153),
(152875, 'esES', 'Déjame morir ehta vez, Bwonsamdi... Por favor...', '', 28153),
(152874, 'esES', 'Habla de una vez.', '', 28153),
(152873, 'esES', '', 'Continuaremos con nuestro... ¿Por qué me miras así? ¿NO LO APRUEBAS?', 28153),
(152872, 'esES', 'Inmediatamente, sí. ¡Por supuesto, y sin más dilación!', '', 28153),
(152871, 'esES', 'Eh, he visto cosas peores. Aunque no deja de ser una historia triste. Tendremos que informar al Alto comandante de lo ocurrido.', '', 28153),
(152870, 'esES', 'Cielos, es mucho peor de lo que me temía. Mis más sinceras disculpas por ponerte en una situación tan peligrosa, sir Barbabronce.', '', 28153),
(152869, 'esES', '¿Y bien? Esa chica estaba más chiflada que un múrloc borracho de hidromiel lunar. Intentó ofrecer a $gnuestro querido:nuestra querida; $c como sacrificio a un Dios de la Sangre llamado G\'huun.', '', 28153),
(152868, 'esES', 'La capitana Conrad... está bien, ¿verdad?', '', 28153),
(152867, 'esES', 'Zul\'Nazman, creo. ¿O Tul\'vor? En realidad, creo que son lo mismo. O casi.', '', 28153),
(152866, 'esES', 'Con conocimiento o sin él, es hora de llegar al fondo de esto. ¿Hacia dónde ha ido esa capitana?', '', 28153),
(152865, 'esES', 'Ay... Madre mía. Seguro que nuestra estimada capitana Conrad ignoraba estas macabras circunstancias.', '', 28153),
(152864, 'esES', 'El rostro de Harry palidece.', '', 28153),
(152863, 'esES', '¿Qué es esto, Harry? Esas ofrendas que ibas a enviar... ¡Han sacrificado a los soldados! Han drenado la sangre de sus cuerpos y los han dejado más secos que una jarra en la Fiesta de la Cerveza.', '', 28153),
(152862, 'esES', '¡Y un cuerno! No se van a llevar otra moneda de cobre nuestra antes de que $n y yo vayamos a ver de qué va esto.', '', 28153),
(152861, 'esES', '¡Acuerdos comerciales con los trols! Incluso tenemos murciélagos preparados para enviar otra oferta de comercio a Zalamar.', '', 28153),
(152860, 'esES', '¡Oh, cielos! Bueno, lo cierto es que sí. Supongo que es cierto, mmm. Pero la capitana Conrad es realmente gloriosa. Impresionante, sin duda.', '', 28153),
(152859, 'esES', 'He oído que son salvajes que practican sacrificios sangrientos.', '', 28153),
(152858, 'esES', '¡Nada malo, te lo aseguro! Nuestra gloriosa capitana está negociando acuerdos comerciales con los trols locales.', '', 28153),
(152857, 'esES', 'De acuerdo, entonces no hay señales de la capitana. ¿Qué está pasando?', '', 28153),
(152856, 'esES', '¡Ah! ¡Ja! Al grano, sí, sí. ¡No te preocupes! Todo está en orden. Retirémonos a un entorno más seguro tras los muros de nuestra fortaleza, ¿de acuerdo?', '', 28153),
(152855, 'esES', '¿Dónde está la capitana?', '', 28153),
(152854, 'esES', 'La capitana Conrad me dejó instrucciones.', '', 28153),
(152853, 'esES', 'Os hemos estado esperando, estimados consejeros y futuros amigos íntimos.', '', 28153),
(152852, 'esES', '¡Bienvenidos! ¡Bienvenidos!', '', 28153),
(152851, 'esES', 'Parece que la comitiva de bienvenida está aquí. Harry es un tipo interesante. No le prestes atención.', '', 28153),
(152850, 'esES', 'Y... ehm... tápate la nariz. ¿Qué es ese hedor asqueroso a muerte y descomposición?', '', 28153),
(152849, 'esES', 'No importa. Mira. Escucha. Mantén los ojos abiertos. Estas tierras inclementes no perdonan a los incautos, $n.', '', 28153),
(152848, 'esES', 'Aun así, esta tierra juega en contra de los Zandalari y sus socios de la Horda. El enemigo de tu enemigo es tu... A ver, ¿cómo era el dicho?', '', 28153),
(152847, 'esES', 'Hemos enviado a la capitana Conrad a construir un fuerte. Dicen que tal vez los trols de sangre locales estén dispuestos a comerciar, pero no creo que sea a un precio que merezca la pena pagar.', '', 28153),
(152846, 'esES', '¡Me gusta! En cualquier lugar que te ponga los pelos de punta hay una oportunidad de vivir aventuras y obtener conocimiento.', '', 28153),
(152845, 'esES', 'Este lugar me da escalofríos...', '', 28153),
(152844, 'esES', 'Pero no viviréis para ver ese día... Álzate, guardián, ¡que esta intrusión no quede impune!', '', 28153),
(152843, 'esES', 'La plaga de Kul Tiras será purificada... ¡Y reconquistaremos nuestras tierras!', '', 28153),
(152842, 'esES', 'Tus ancestros eran unos necios... ¡y tú también!', '', 28153),
(152841, 'esES', 'Toma una de las cuerdas que bajan a la lancha de desembarco, $n. Y buena suerte.', '', 28153),
(152840, 'esES', '', 'Allí hay más grabados. ¡Vamos!', 28153),
(152839, 'esES', '', '¡Gorak Tul no sobrevivió! ¡Los testigos narraron su derrota!', 28153),
(152838, 'esES', 'Las autoridades locales nos han dado permiso para abrir portales aquí.', 'Las autoridades locales nos han dado permiso para abrir portales aquí.', 28153),
(152837, 'esES', 'Este lugar está impregnado de magia. ¿Lo sientes?\n\nMe pregunto qué clase de rituales estarían realizando aquí.', 'Este lugar está impregnado de magia. ¿Lo sientes?\n\nMe pregunto qué clase de rituales estarían realizando aquí.', 28153),
(152836, 'esES', '', '¡Otro grabado! Este también muestra a Gorak Tul.', 28153),
(152835, 'esES', '|cFF0000FF(Misión)|r Viaja en barco a Vol\'dun.', '|cFF0000FF(Misión)|r Viaja en barco a Vol\'dun.', 28153),
(152834, 'esES', '|cFFEF0201+$1i|r |cFFFFFF00azerita|r', '|cFFEF0201+$1i|r |cFFFFFF00azerita|r', 28153),
(152833, 'esES', 'Me dijeron que trabajaría con <tos> de sangre. Dije: \"¿Elfos de sangre?\". Y repitieron lo de \"<tos> de sangre\".\n\nTROLS de sangre, no ELFOS. Pff. No tienen el más mínimo refinamiento.', '', 28153),
(152832, 'esES', '', '¡Señor, sí, señor!', 28153),
(152831, 'esES', '', 'Espera... ¿Qué sucede?', 28153),
(152830, 'esES', 'La unión hace la fuerza.', '', 28153),
(152829, 'esES', 'Vale, he hecho una anotación aquí sobre las rojas. Incluso la he marcado en rojo. Gracias, sin tu ayuda esto no habría acabado bien.', '', 28153),
(152828, 'esES', 'Eh, tú, me gustaría recolectar muestras de una rara flor del desierto. Ayúdame, por favor.', '', 28153),
(152827, 'esES', '¡Menuda lunática! Nos reuniremos en el Fuerte Victoria. Salgamos de este oscuro lugar antes de que todos empiecen a perseguirnos.', '', 28153),
(152826, 'esES', 'Estoy listo.', 'Estoy lista.', 28153),
(152825, 'esES', 'Es inusual ver esto en esta parte del mundo. Se dice que las hojas del azotador rojo tienen propiedades curativas místicas.$b$bMe gustaría recoger algunas, pero al arrancarlas el olor de la planta se esparce por el aire. Sin duda, atraerá la atención de la fauna local.$b$bProtégeme mientras cosecho las hojas. Te recompensaré como es debido.', '', 28153),
(152824, 'esES', 'Alleria, llévate al resto de nuestras tropas y céntrate en aplastar al ejército enemigo.', '', 28153),
(152823, 'esES', '¡Mi vida por la Horda!', '', 28153),
(152822, 'esES', 'Mi padre lo dio todo por la Alianza. Me pregunto si tú estás dispuesto a hacer lo mismo por la Horda.', '', 28153),
(152821, 'esES', '¡Nunca me rendiré! Como, duermo y muero por la espada. ¿Qué precio has pagado tú por tu gente?', '', 28153),
(152820, 'esES', 'Tu padre era un hombre honorable, chico. Al contrario que tú.', '', 28153),
(152819, 'esES', 'Apártate, Colmillosauro. Esta guerra no depende solo de ti, y matarte no nos traerá honor alguno.', '', 28153),
(152818, 'esES', '', '¡Estoy lista!', 28153),
(152817, 'esES', '¡Un trabajo excelente! Sigamos adelante.', '', 28153),
(152816, 'esES', 'Cuatro ojos... Es el fin... ¡Ella se alza!', '', 28153),
(152815, 'esES', 'Sombras infinitas... Miles de brazos...', '', 28153),
(152814, 'esES', 'Te lo debo todo, $p. No lo olvidaré.\n\nPor ahora, ayudaremoh a Norah y loh otroh vulperah a saquear todo el botín robado de Zem\'lan. Pero no dudeh en avisarnoh si necesitah la ayuda de un puñado de piratah no-muertoh.\n\nHemoh liderado un buen motín, pero tengo claro que Zem\'lan no tuvo que forzarnoh a todoh pa que noh convirtiéramoh en monhtruoh. Muchoh miembroh de la tripulación lo hicieron por su cuenta.\n\nTen cuidado si vuelveh al puerto.', '', 28153),
(152813, 'esES', 'Debemos asegurarnos de que el sacrificio de Victoria no sea en vano. Su bastón es la clave del camino al santuario.', '', 28153),
(152812, 'esES', 'Motín hahta el penol, $p. Ehtoy contigo.', '', 28153),
(152811, 'esES', '¿Alguna vez hah vihto tantoh tesoroh en el mihmo sitio?\n\nEhto eh lo que te trae toda una vida de piratería. Qué hermosura...', '', 28153),
(152810, 'esES', '', '<Ahna ronca con fuerza mientras finge estar dormida>.', 28153),
(152809, 'esES', 'Haced sonar ese gong pa retar al rey pirata Zem\'lan. Yo ehtaré preparado pa enfrentarme a él.', '', 28153),
(152808, 'esES', 'Ya veo. Entonces le desvelaremos a Katherine Valiente la misma verdad por la que yo pagué un alto precio.', '', 28153),
(152807, 'esES', '¡Buen trabajo! Las monedas de oro del antiguo imperio trol valen una fortuna. ¡Toma tu parte!', '', 28153),
(152806, 'esES', 'He encontrado un antiguo tótem de la Corte de Zak\'rajan que tiene el poder de resucitar a los muertos. ¡Llévalo a los fosos de huesos y úsalo para desenterrar tesoros ocultos!', '', 28153),
(152805, 'esES', 'Ah, ¡olvídalo! No tengo tiempo para estas tonterías. Me esperan en una fiesta...', '', 28153),
(152804, 'esES', 'Niños, siempre tan impacientes... ¡Si solo estoy calentando!', '', 28153),
(152803, 'esES', 'Si sigues dándome la lata, acabaré contándote una historia. Muy laaaaarga y aburrida.', '', 28153),
(152802, 'esES', 'Ya compartiremos historias la próxima vez.', '', 28153),
(152801, 'esES', 'Vale, vete. Tengo cosas que hacer.', '', 28153),
(152800, 'esES', '¿Por qué tanta prisa?', '', 28153),
(152799, 'esES', 'No hagas ruido.', '', 28153),
(152798, 'esES', '¿Conoces alguna historia buena?', '', 28153),
(152797, 'esES', 'Sí, sí... Te escucho.', '', 28153),
(152796, 'esES', 'Si no tieneh cuidado, la flora de la selva puede ser peor que la fauna.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'esES', '¡No pienso volver a poner un pie en esta mina!', '¡No pienso volver a poner un pie en esta mina!', 28153),
(152794, 'esES', '¡Han salido de la nada!', '¡Han salido de la nada!', 28153),
(152793, 'esES', '¡Gracias! Creía que no lo contaba.', '¡Gracias! Creía que no lo contaba.', 28153),
(152792, 'esES', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(152791, 'esES', '', 'Esto os llevará al puente que hay abajo.', 28153),
(152790, 'esES', 'Creo que tu cara y mi bota aún no se conocen... ¿Qué te parece si le ponemos remedio a eso?', '', 28153),
(152789, 'esES', 'Vuelva, vuela, pajarito...', '', 28153),
(152788, 'esES', 'Nos vemos en los cielos.', '', 28153),
(152787, 'esES', '', 'En el Valle Canto Tormenta, al norte, los Sabiomar de la casa Canto Tormenta fabrican y bendicen los barcos de nuestra legendaria flota.', 28153),
(152786, 'esES', 'Muy bien, sigue tu camino.', '', 28153),
(152785, 'esES', '¡Vuelta al trabajo!', '', 28153),
(152784, 'esES', '¡Venga!', '', 28153),
(152783, 'esES', '¿Qué necesitas?', '', 28153),
(152782, 'esES', '¿Sí? ¡Soy un tipo ocupado!', '', 28153),
(152781, 'esES', 'Esas bestias han sido una pesadilla para las caravanas de Vol\'dun. Buen trabajo.', '', 28153),
(152780, 'esES', 'Los buitres Picohueso son una raza indomable y se han convertido en una molestia. Hay que reducir su número y acabar con sus nidos.', '', 28153),
(152779, 'esES', 'Echa un vistazo si quieres, pero no toques nada, por favor.$b$bEstas plantas son muy delicadas.', '', 28153),
(152778, 'esES', '', 'Al oeste está Drustvar, una región montañosa de la que provienen muchos minerales del reino... y los guerreros más fieros.', 28153),
(152777, 'esES', '', 'Más allá del Estrecho de Tiragarde están las tierras de los Crestavía y los Canto Tormenta.', 28153),
(152776, 'esES', '¡Solo sentiráh dolor!', '¡Solo sentiráh dolor!', 28153),
(152775, 'esES', '¡Conozco métodos para hacerte hablar!', '¡Conozco métodos para hacerte hablar!', 28153),
(152774, 'esES', 'Quebraré tu espíritu.', 'Quebraré tu espíritu.', 28153),
(152773, 'esES', 'En cenizas te convertirás...', '', 28153),
(152772, 'esES', 'Para cuando pedimos ayuda, ya era tarde.', '', 28153),
(152771, 'esES', 'La tierra que amo se está derrumbando, por eso os pido ayuda. Kul Tiras necesita a la Alianza, y vosotros también nos necesitáis.', '', 28153),
(152770, 'esES', 'Pero está cegada. Sus consejeros le ocultan la infección que se ha propagado por nuestro reino.', '', 28153),
(152769, 'esES', 'Kul Tiras aún tiene cicatrices de la Tercera Guerra. Nadie es más consciente de ello que Katherine Valiente.', '', 28153),
(152768, 'esES', '', 'Intenta no dejarme mal, ¿vale?', 28153),
(152767, 'esES', 'Días más tarde, se despertó gritando y cubierto de sudor. La infección se había extendido por todo su cuerpo, y mi amigo no volvió a ver otro amanecer.', '', 28153),
(152766, 'esES', '', 'Si ya no quedan monedas aquí, revisa los otros lugares.', 28153),
(152765, 'esES', 'Ese podría haber sido su billete de vuelta a casa, pero era un cabezón. Se negó a partir antes de ganar la guerra, así que se curó como pudo y les dijo a los sanadores que estaba bien.', '', 28153),
(152763, 'esES', 'Un acorazado orco atacó nuestro transporte. Las astillas de la regala volaron por la cubierta y atravesaron a un amigo mío.', '', 28153),
(152762, 'esES', 'Yo participé en una batalla hace muchos años. ¿Sería en la Segunda Guerra? Hay tantas que...', '', 28153),
(152761, 'esES', 'Mm... Dejad que os cuente una historia.', '', 28153),
(152760, 'esES', '¿Por qué quieres ayudarnos?', '', 28153),
(152759, 'esES', 'Katherine Valiente nos expulsó y desterró a su propia hija tras acusarla de traición.', '', 28153),
(152758, 'esES', 'Un Zandalari errante me ofreció esta poción en un trueque. Se supone que cocina al instante lo que sea, y no diré que no a carne gratis. Pruébala con las criaturas de la zona.', '', 28153),
(152757, 'esES', '¡Taelia! Prepara un informe completo para nuestros invitados.', '', 28153),
(152756, 'esES', 'Todos se derretirán.', '', 28153),
(152755, 'esES', 'Rey Cringrís, es un honor. Tenéis mi permiso para permanecer en el puerto.', '', 28153),
(152754, 'esES', '¡Qué buena pinta! Aun así, dejaré que nuestros amigos prueben la carne primero...', '', 28153),
(152753, 'esES', '', 'El ansia de poder. El anhelo de la verdad absoluta. El deseo de sangre.', 28153),
(152752, 'esES', '', 'Los métodos de los Nazmani eran... desalentadores, al principio. Pero ahora los conozco. Son gente sencilla con aspiraciones simples.', 28153),
(152751, 'esES', '', 'Mira, déjame enseñarte lo que he aprendido.', 28153),
(152750, 'esES', '', 'Aún hay mucho que no entendemos de sus costumbres. Esa magia de sangre... es mucho más potente de lo que puedas imaginar.', 28153),
(152749, 'esES', '', 'Pueden ser una herramienta muy poderosa contra los trols Zandalari y sus aliados de la Horda.', 28153),
(152748, 'esES', '', 'He conseguido ganarme la confianza de esos trols de sangre, los Nazmani, más de lo que me esperaba.', 28153),
(152747, 'esES', '¡Aaaagh, cierra el pico!', '', 28153),
(152746, 'esES', '', '¡Aaaargh!', 28153),
(152745, 'esES', '', 'No es nada personal, entiéndelo, pero no puedo permitirte que interrumpas mis progresos. He aprendido mucho... y aún me quedan cosas por descubrir.', 28153),
(152744, 'esES', '', 'Este Zandalari será sacrificado por el avance de nuestro poder.', 28153),
(152743, 'esES', 'Noh hah traído hahta aquí. Te seguiremoh.', 'Noh hah traído hahta aquí. Te seguiremoh.', 28153),
(152742, 'esES', 'Hay una tripulación de vulperah cerca de aquí. Propongo que aunemoh fuerzah por ahora.', '', 28153),
(152741, 'esES', 'Loh lacayoh de Zem\'lan noh buhcarán por loh mareh.', '', 28153),
(152740, 'esES', 'Sí. Pero anteh tendremoh que ehcondernoh una temporada.', '', 28153),
(152739, 'esES', 'Libreh pa quedarnoh con la riqueza saqueada.', 'Libreh pa quedarnoh con la riqueza saqueada.', 28153),
(152738, 'esES', 'Libreh pa asaltar mil lugareh.', 'Libreh pa asaltar mil lugareh.', 28153),
(152737, 'esES', 'Somoh libreh pa cruzar loh mareh.', 'Somoh libreh pa cruzar loh mareh.', 28153),
(152736, 'esES', 'Lo hemoh logrado, camaradah. Al fin noh hemoh librado de Zem\'lan.', '', 28153),
(152735, 'esES', '¡Todoh juntoh! ¡A la cohta a toda vela!', '¡Todoh juntoh! ¡A la cohta a toda vela!', 28153),
(152734, 'esES', 'Debes de ser $gel emisario:la emisaria; de la Alianza. Me alegro de que Flynn y Taelia consiguieran sacarte de esa maldita prisión.\n\nSoy sir Cyrus Catacresta. En nombre del Almirantazgo de la Casa Valiente, te doy la bienvenida a Kul Tiras.\n\n<Cyrus te extiende su enorme mano con afecto>.', '', 28153),
(152733, 'esES', '<Le estrechas la mano>.', '<Le estrechas la mano>.', 28153),
(152732, 'esES', 'No me quedan muchos días por delante.\n\nNo los desperdiciaré viendo como Kul Tiras se desmorona.', '', 28153),
(152731, 'esES', 'Tripulación, ¡coged el tesoro y subid al barco!', '', 28153),
(152730, 'esES', 'Winston está volando fuera de tu alcance. ¡Vuelve a Corlain!', '', 28153),
(152729, 'esES', 'Mih ehploradoreh me informan de que el guardián de loh titaneh Hezrel merodea por la base de ehta ehtructura.', '', 28153),
(152728, 'esES', 'Dehde lo de Hakkar, lah menteh de loh Gurubashi son muy débileh y eh demasiado fácil corromperloh. Hay que purgarloh.', '', 28153),
(152727, 'esES', '', 'Todos... moriréis...', 28153),
(152726, 'esES', 'A suh órdeneh, Capitana.', '', 28153),
(152725, 'esES', '', '¡Corlain pertenece al aquelarre!', 28153),
(152724, 'esES', 'Ahora relajaos y descansad. ¡Mañana planearemos cómo hacernos con el resto del tesoro!', 'Ahora relajaos y descansad. ¡Mañana planearemos cómo hacernos con el resto del tesoro!', 28153),
(152723, 'esES', '¡Bienvenidos a la caravana!', '¡Bienvenidos a la caravana!', 28153),
(152722, 'esES', 'En ese caso...', 'En ese caso...', 28153),
(152721, 'esES', 'Sí. Hay una ihla cerca de la cohta con máh tesoroh de loh que podáih imaginar.', '', 28153),
(152720, 'esES', 'Los vulperas nunca hemos rechazado un tesoro por una maldición de nada... ¿Tenéis más de eso por ahí?', 'Los vulperas nunca hemos rechazado un tesoro por una maldición de nada... ¿Tenéis más de eso por ahí?', 28153),
(152719, 'esES', 'El único problema eh que el tesoro ehtá maldito.', 'El único problema eh que el tesoro ehtá maldito.', 28153),
(152718, 'esES', 'Buhcamoh una nueva tripulación a la que unirnoh. Si noh aceptáih, compartiremoh el tesoro con vosotroh.', '', 28153),
(152717, 'esES', 'El rey pirata Zem\'lan mató a vuehtro amigo. Luego, noh amotinamoh contra él y le robamoh el tesoro.', '', 28153),
(152716, 'esES', 'Os escucho...', 'Os escucho...', 28153),
(152715, 'esES', '¡Echa el freno! Venimoh en son de paz.', '', 28153),
(152714, 'esES', '¡Esque-que-que-letos! N-n-norah, ¡mátalos!', '¡Esque-que-que-letos! N-n-norah, ¡mátalos!', 28153),
(152713, 'esES', 'Excelente. Un ataque con los propios cañones de los infieles debería debilitar su asedio.', '', 28153),
(152712, 'esES', '¡Nada me gusta tanto como un buen combate!', '¡Nada me gusta tanto como un buen combate!', 28153),
(152711, 'esES', '¡Los infieles siguen atacando! ¡Usa uno de los cañones que hemos requisado para defender el templo!', '', 28153),
(152710, 'esES', '', '¡Parche, ahora!', 28153),
(152709, 'esES', 'Cuando quieras.', 'Cuando quieras.', 28153),
(152708, 'esES', '¿Quieres moverte o qué? No estamos aquí de vacaciones.', '', 28153),
(152707, 'esES', '¡Acribilladlos, chicos!', '', 28153),
(152706, 'esES', '¡Abrid fuego!', '', 28153),
(152705, 'esES', '¡Dadles duro, chicos!', '', 28153),
(152704, 'esES', '¡Objetivo fijado! ¡Fuego!', '', 28153),
(152703, 'esES', '¡Fuego a discreción!', '', 28153),
(152702, 'esES', '¡Ahí está el objetivo! ¡Fuego!', '', 28153),
(152701, 'esES', 'Ja, ja, ja...', '', 28153),
(152700, 'esES', 'Sí. Demasiado espeluznante para nuestros clientes potenciales.', '', 28153),
(152699, 'esES', '¿Demasiado espeluznante?', '', 28153),
(152698, 'esES', 'He hecho un pequeño cálculo de pérdidas y ganancias, y creo que en esta zona estamos perdiendo el tiempo.', '', 28153),
(152697, 'esES', 'Entonces... ¿qué pasa con tu azerita?', '', 28153),
(152696, 'esES', 'Bien. Súbete a la moto. Larguémonos de aquí.', '', 28153),
(152695, 'esES', 'Claro que sí.', '', 28153),
(152694, 'esES', 'Entonces... mmm... ¿quieres irte de aquí?', '', 28153),
(152693, 'esES', 'No, no, no, no...', '', 28153),
(152692, 'esES', 'Más te vale superar ese miedo a las brujas, Eitrigg. Esta zona está LLENA de azerita y... ¡AGH!', '', 28153),
(152691, 'esES', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t¡%s obtiene un |cFFFF0000|Hspell:263246|h[Escudo de relámpagos]|h|r!', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t¡%s obtiene un |cFFFF0000|Hspell:263246|h[Escudo de relámpagos]|h|r!', 28153),
(152690, 'esES', '¡Otra vez no!', '', 28153),
(152689, 'esES', '', '¡Tu sangre es mía!', 28153),
(152688, 'esES', '¡Qué más da! ¿Has encontrado la veta de azerita?', '', 28153),
(152687, 'esES', '¿Qué? ¿Qué pasa?', '', 28153),
(152686, 'esES', 'Ca... cállate.', '', 28153),
(152685, 'esES', '¡Aah, ja, ja, ja! Un orco grandullón que tiene miedo de las brujas.', '', 28153),
(152684, 'esES', '¡NO! Quiero decir, no. Solo que... no me gustan, eso es todo.', '', 28153),
(152683, 'esES', '¿Qué has dicho?', '', 28153),
(152682, 'esES', 'Cuidado... con... las brujas...', '', 28153),
(152681, 'esES', 'Eitrigg... ¿Te dan miedo las brujas?', '', 28153),
(152680, 'esES', '¿Ha dicho... bru-brujas?', '', 28153),
(152679, 'esES', '¡El Ágora no está a salvo! ¡Tenemos a los pájaros encima!', '¡El Ágora no está a salvo! ¡Tenemos a los pájaros encima!', 28153),
(152678, 'esES', 'Bueno, ¡haz tu trabajo y protégeme!', '', 28153),
(152677, 'esES', 'No... pero veo algo. Tenemos compañía.', '', 28153),
(152676, 'esES', 'Bah... Pasa muy a menudo. ¿Ves azerita en algún sitio?', '', 28153),
(152675, 'esES', '¡Están por todas partes!', '¡Están por todas partes!', 28153),
(152674, 'esES', 'Gallywix... ¿ves este cadáver mutilado de aquí? Tu explorador está muerto.', '', 28153),
(152673, 'esES', 'Sí, lo que tú digas.', '', 28153),
(152672, 'esES', 'De acuerdo, investigaremos la azerita. ¡Pero después DEBEMOS centrarnos en la Alianza!', '', 28153),
(152671, 'esES', '¡Demasiados... pájaros!', '¡Demasiados... pájaros!', 28153),
(152670, 'esES', '¡Nunca volveré a confiar en una gaviota!', '¡Nunca volveré a confiar en una gaviota!', 28153),
(152669, 'esES', 'La anciana MacMillan tenía razón. ¡Esos pájaros son malvados!', 'La anciana MacMillan tenía razón. ¡Esos pájaros son malvados!', 28153),
(152668, 'esES', 'Pff. Braceros.', '', 28153),
(152667, 'esES', 'Comprobaremos eso primero.', '', 28153),
(152666, 'esES', '¡Lo primero es lo primero! Mis exploradores han encontrado un filón de azerita ENORME aquí en Drustvar.', '', 28153),
(152665, 'esES', 'Entonces apártate de mi vista, ¡o te daré motivos para tener miedo!', '', 28153),
(152664, 'esES', 'Deberíamos tener cuidado. Lo que dijo fue... preocupante.', '', 28153),
(152663, 'esES', 'Sí, pero...', '', 28153),
(152662, 'esES', '... una maldición terrible... todos los demás están...', '', 28153),
(152661, 'esES', '¡Tienes que volver! Es...', '', 28153),
(152660, 'esES', '', 'Vaya. Pensé que sería más grande.', 28153),
(152659, 'esES', '', 'No tiene suficiente potencia. Supongo que necesita más energía.', 28153),
(152658, 'esES', 'Preferimoh lah arboledah de la naturaleza a la fría piedra de la ciudad. Muchoh Zandalari piensan que somoh herejeh. Afirman que nuehtra matriarca no eh una loa.\n\nQue opinen lo que quieran. Loh Lun\'alai cuhtodiamoh loh doneh de la naturaleza dehde hace mucho, la capacidad de adoptar lah formah de lo salvaje. Nuehtro camino se basa en el equilibrio, no en el negocio.', '', 28153),
(152655, 'esES', '¡Estupendo! ¡Qué bonitos! Uy, este tiene un poco de arena. Da igual. ¡Lo has hecho muy bien!', '', 28153),
(152654, 'esES', 'Las olas arrastran cantidad de cristal marino a este marjal, ¡pero los múrlocs se lo llevan todo! Intenta hacerte con unos trozos como creas conveniente.', '', 28153),
(152653, 'esES', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t ¡Yazma comienza a lanzar |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t ¡Yazma comienza a lanzar |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r!', 28153),
(152652, 'esES', 'Llegas demasiado tarde. ¡La invasión ya ha comenzado!', 'Llegas demasiado tarde. ¡La invasión ya ha comenzado!', 28153),
(152651, 'esES', '¿Te crees que trabajo sola? ¡Te presento a mis socios!', '¿Te crees que trabajo sola? ¡Te presento a mis socios!', 28153),
(152650, 'esES', '', '¡Las acciones del aquelarre son terribles, pero esto ya es demasiado! No tengo palabras para expresaros mi gratitud por detener esta matanza.', 28153),
(152649, 'esES', 'Las inclinaciones del aquelarre rozan lo profano, pero aquí acaba una de sus actividades más sórdidas.', '', 28153),
(152648, 'esES', 'Reúnete conmigo en el barco. ¡Me aseguraré de que la tripulación lo cargue de tesoroh!', '', 28153),
(152647, 'esES', '', 'Cada vida salvada de las garras de este culto es una victoria. Buen trabajo.', 28153),
(152646, 'esES', 'La muerte y el renacimiento nos pertenecen solo a nosotros. Gracias por permitir que siga así.', '', 28153),
(152645, 'esES', '', 'Hoy habéis salvado a los habitantes de Drustvar de este terror aéreo. Os lo agradezco.', 28153),
(152644, 'esES', 'No causes problemas.', 'No causes problemas.', 28153),
(152643, 'esES', 'Con estas plumas, nuestras forestales estarán servidas durante un tiempo.', '', 28153),
(152642, 'esES', 'Una eternidad de pillaje y saqueo... ¡sin ti!', '', 28153),
(152641, 'esES', '¿Qué puede ser mejor que una eternidad de pillaje y saqueo?', '', 28153),
(152640, 'esES', 'Ereh un Capitán cruel, Zem\'lan. ¡La tripulación se merece algo mejor!', '', 28153),
(152639, 'esES', '', 'Si no lo hacéis, todos estamos perdidos. ¡Marchaos!', 28153),
(152638, 'esES', '', '¡No te abandonaremos a tu suerte!', 28153),
(152637, 'esES', '', 'Ha ehtado muy cerca. Debemoh vigilar cuidadosamente loh mareh y también lah arenah de Vol\'dun.', 28153),
(152636, 'esES', '', 'Ha estado muy cerca. Parece que debemos vigilar cuidadosamente los mares y también las arenas.', 28153),
(152635, 'esES', '', 'Un monhtruo marino gigante ha ehtado asolando la cohta. Debemoh detener a esa behtia anteh de que se aventure tierra adentro.', 28153),
(152634, 'esES', '', 'Un monstruo marino descomunal ha estado asolando la costa. ¡Debemos detener a esa bestia antes de que se aventure cerca de nuestro campamento!', 28153),
(152633, 'esES', '', 'Xorreth era un Comandante importante del ejército sethrak. Su muerte eh una gran victoria pa nosotroh.', 28153),
(152632, 'esES', '', 'El llamacolmillos Xorreth era un comandante de alto rango del ejército sethrak. Su muerte es una gran victoria para nosotros.', 28153),
(152631, 'esES', '', 'Loh ehploradoreh vulperah han informado de la presencia de un Comandante sethrak cerca de aquí. Debemoh eliminarlo.', 28153),
(152630, 'esES', '', 'Nuestros exploradores nos han informado de la presencia de un comandante sethrak de alto rango cerca de aquí. Debemos aprovechar la oportunidad de eliminarlo mientras podamos.', 28153),
(152629, 'esES', '', '¡Buen trabajo! La tribu no podrá sobrevivir sin un jefe que la dirija.', 28153),
(152628, 'esES', '', '¡Buen trabajo! La tribu no podrá sobrevivir sin un jefe que la dirija.', 28153),
(152627, 'esES', '', 'Cerca de aquí hay una tribu de múrlocs que ha estado causando problemas. Si acabas con su líder, la tribu se desmoronará.', 28153),
(152626, 'esES', '', 'Cerca de aquí hay una tribu de múrloc que ha ehtado causando problemah. Si acabah con su líder, la tribu se dehmoronará.', 28153),
(152625, 'esES', '', 'Buen trabajo. Nuestros exploradores se alegrarán de que hayas eliminado a Mor\'fani.', 28153),
(152624, 'esES', '', 'Buen trabajo. Loh vulperah se alegrarán de que te hayah ocupado de Mor\'fani.', 28153),
(152623, 'esES', 'Este aquelarre ha hechizado a un gran cuervo para usarlo contra los aldeanos. Los habitantes de Drustvar me son indiferentes, pero las plumas del cuervo serían muy útiles para nuestras forestales oscuras.', '', 28153),
(152622, 'esES', 'Una de las brujas está sacrificando a sus acólitos para obtener más poder. Acabad con ella y demostradle al aquelarre que solo la Dama Oscura domina la muerte.', '', 28153),
(152621, 'esES', 'Parece que el aquelarre ha \"contratado\" a los chefs de la mansión para que preparen platos repugnantes. Sería mejor eliminarlos cuanto antes.', '', 28153),
(152620, 'esES', '', 'El aquelarre Aterracorazón ha hechizado a un cuervo enorme procedente de Drustvar. ¡Matadlo antes de que ataque a nuestros civiles!', 28153),
(152619, 'esES', '', 'Uno de los miembros del aquelarre de lady Crestavía está sacrificando a sus propios acólitos. ¡Detened el ritual antes de que se pierdan demasiadas vidas!', 28153),
(152618, 'esES', '', 'Un exiliado Zandalari ha estado aterrorizando a nuestros exploradores. Encuéntralo y elimínalo antes de que asesine a más víctimas.', 28153),
(152617, 'esES', '', 'Un recién exiliado ha ehtado aterrorizando a loh vulperah. Encuéntralo y elimínalo anteh de que cause máh víctimah.', 28153),
(152616, 'esES', '', 'Los chefs están sirviendo comida de dudosa procedencia a sus invitados sin que estos lo sepan. ¡Acabad con sus monstruosidades culinarias!', 28153),
(152615, 'esES', '¡Señor, sí, señor!', '', 28153),
(152614, 'esES', 'N-no, señor.', '', 28153),
(152613, 'esES', 'Ahora apartaos y dejad que pasen. Hablaremos en mi oficina.', '', 28153),
(152612, 'esES', '¡No! ¡Servís a Kul Tiras! ¡Lleváis el blasón de la casa Valiente! Y seguís mis órdenes.', '', 28153),
(152611, 'esES', 'Es imposible cultivar nada en Vol\'dun sin fertilizante. Normalmente lo obtenemos de las hienas, pero no han dejado mucho últimamente. ¡Prueba a alimentarlas para acelerar el asunto!', '', 28153),
(152610, 'esES', '¿Lady Gobernalle? ¿Servís a lady Gobernalle? ¿Acaso lleváis el blasón de lady Gobernalle en el escudo?', '', 28153),
(152609, 'esES', 'Pero señor... lady Gobernalle ordenó...', '', 28153),
(152608, 'esES', '¡Bajad las armas! ¿Acaso no sabéis quién es?', '', 28153),
(152607, 'esES', '¡Este fertilizante es estupendo! Buen trabajo... Y no olvides lavarte las manos.', '', 28153),
(152606, 'esES', 'Supongo que debemos interrumpirlo, ¿no?', '', 28153),
(152605, 'esES', '¿Eso que se ve en el horizonte es una vela? Puede que estén haciendo un trato con los Zandalari.', '', 28153),
(152604, 'esES', 'Dando una patada', 'Dando una patada', 28153),
(152603, 'esES', 'La caja emite una melodía neutra.', '', 28153),
(152602, 'esES', 'La caja emite una melodía alegre.', '', 28153),
(152601, 'esES', 'La caja emite una melodía neutra.', '', 28153),
(152600, 'esES', 'Ni idea, pero esta noche invito yo a la cerveza, muchacha.', '', 28153),
(152599, 'esES', '', '¿Qué pasa?', 28153),
(152598, 'esES', '', '¡Disfrutaré teletransportándote al fondo del Mare Magnum! ¡Por la Horda!', 28153),
(152597, 'esES', '¿Qu...?', '', 28153),
(152596, 'esES', '', 'Dados los rumores sobre espías e invasores foráneos, hay que ser precavidos. Obedeced sus instrucciones para evitar incidentes.', 28153),
(152595, 'esES', '', 'Ya hablaremos del pago, maestro de embarcadero.', 28153),
(152594, 'esES', 'Sí, ahí está. Lo sellaremos y lo enviaremos de vuelta a Ventormenta.', '', 28153),
(152591, 'esES', '', 'Oculeth... lo siento...', 28153),
(152590, 'esES', 'La aguja apunta al este. Nos reuniremos en las ruinas, $n.', '', 28153),
(152589, 'esES', '', 'Demasiado lento, enano.', 28153),
(152588, 'esES', 'No te alejes. La Horda nos acecha. Están cerca, puedo olerlos.', '', 28153),
(152587, 'esES', 'Es un poco más floral de lo que esperaba. ¿Ahora tienen un nuevo sabor de elfo?', '', 28153),
(152586, 'esES', 'No está aquí. Y para colmo, parece que los Nocheterna andan tras nosotros. Qué maravilla.', '', 28153),
(152585, 'esES', 'Nos estamos acercando. Solo mantén a esos chupópteros de maná asesinos lejos de mí, $n.', '', 28153),
(152584, 'esES', 'Está justo bajo mis pies... ¿Dónde...?', '', 28153),
(152583, 'esES', '¡Eh! ¡Qué truco más sucio!', '', 28153),
(152581, 'esES', 'La caja resuena con suavidad.', '', 28153),
(152580, 'esES', 'La caja resuena con suavidad.', '', 28153),
(152579, 'esES', 'La caja resuena con suavidad.', '', 28153),
(152578, 'esES', '¡Alto! Eh imposible dehtruir loh ídoloh, pero han revelado un viejo recuerdo... Uno que he intentado olvidar.', '', 28153),
(152577, 'esES', 'Hay una espada enorme clavada en el corazón del planeta... ¿Por qué pierdes el tiempo dándome toquecitos? ¡Vuelve al trabajo ahora mismo!', '', 28153),
(152576, 'esES', 'Es tu deber cuidar de Azeroth.', '', 28153),
(152575, 'esES', '¡Nuestro mundo necesita una cura!', '', 28153),
(152574, 'esES', 'Azeroth grita de dolor.', '', 28153),
(152573, 'esES', 'Nuestro mundo nos necesita.', '', 28153),
(152572, 'esES', '', '¡Y pensar que los trols han estado sentados sobre el descubrimiento arqueológico del siglo!', 28153),
(152571, 'esES', 'No perdáis vuestros huesos. Aquí hay poder, puedo saborearlo. Se lo arrebataremos a la Horda delante de sus narices.', '', 28153),
(152570, 'esES', '', 'Ahora ten cuidado con las manos. Despacio y con firmeza.', 28153),
(152569, 'esES', '', 'Procura no dañarlo. Sí, así...', 28153),
(152568, 'esES', '', 'Aaaaaah... Mira eso. ¡Al final serás $gun buen arqueólogo:una buena arqueóloga;!', 28153),
(152567, 'esES', '¿En serio? ¿Pretendes hacerlo todo solo con las manos?', '', 28153),
(152566, 'esES', 'Ve a avisar a mi elemental. Hará esto por ti.', '', 28153),
(152565, 'esES', '', '¡Espera!', 28153),
(152564, 'esES', 'Bien. Ahora empieza el verdadero trabajo.', '', 28153),
(152563, 'esES', '', '¡Lo has rayado! ¡No podemos exhibirlo en este estado!', 28153),
(152562, 'esES', 'Sí, chica, no está mal.', '', 28153),
(152561, 'esES', 'Tengo loh huesoh cansadoh. El peso de la maldición eh muy grande.', '', 28153),
(152560, 'esES', 'El rey pirata Zem\'lan nunca olvidará ehte día.', '', 28153),
(152559, 'esES', '', '¡Vamos! El Despacho del Capitán de Puerto está ahí delante.', 28153),
(152558, 'esES', 'Y tengo que lavar este abrigo...', '', 28153),
(152557, 'esES', 'Un buen martillo sólido es una herramienta muy valiosa y un arma robusta.', '', 28153),
(152556, 'esES', 'Sin mi martillo soy un completo inútil. Es como si me faltara una mano.', '', 28153),
(152555, 'esES', '', 'No podré retenerlos mucho tiempo. ¡Coged la vara y salid de aquí!', 28153),
(152554, 'esES', 'Examinando', 'Examinando', 28153),
(152553, 'esES', 'Esas cuevas están plagadas de asquerosos kóbolds.', '', 28153),
(152552, 'esES', '¡Todoh al barco! Noh vemoh pronto.', '', 28153),
(152551, 'esES', 'Ehtamoh casi lihtoh pa levar anclah. Zem\'lan no se lo ehperará.', '', 28153),
(152550, 'esES', 'Sí.', 'Sí.', 28153),
(152549, 'esES', 'Sí.', 'Sí.', 28153),
(152548, 'esES', 'Sí. Zem\'lan eh un tirano, no un Capitán. Tenemoh que amotinarnoh.', 'Sí. Zem\'lan eh un tirano, no un Capitán. Tenemoh que amotinarnoh.', 28153),
(152547, 'esES', '¿Ehtamoh de acuerdo entonceh?', '', 28153),
(152546, 'esES', 'Sí, y cogeremoh nuehtra parte del tesoro.', '', 28153),
(152545, 'esES', 'Mirad cuánto oro...', 'Mirad cuánto oro...', 28153),
(152544, 'esES', '¡Ehto eh un motín, rata de Pantoque! Vamoh a rajarle lah entrañah a Zem\'lan.', '¡Ehto eh un motín, rata de Pantoque! Vamoh a rajarle lah entrañah a Zem\'lan.', 28153),
(152543, 'esES', 'Y aun así no hemoh dado media vuelta.', 'Y aun así no hemoh dado media vuelta.', 28153),
(152542, 'esES', 'Eh el único dehtino peor que el nuehtro.', '', 28153),
(152541, 'esES', 'Allí solo hay ehclavoh del oro: antiguoh miembroh de la tripulación obligadoh a guardar loh tesoroh de Zem\'lan por toda la eternidad.', '', 28153),
(152540, 'esES', 'Vamoh a la Ihla Dorada, donde Zem\'lan amasa loh tesoroh que hemoh saqueado durante añoh.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'esES', '¡Todoh a remar!', '¡Todoh a remar!', 28153),
(152538, 'esES', '*Aquí irá un poco de acción divertida de transición con una vagoneta.*', '', 28153),
(152537, 'esES', 'Hay demasiada luz aquí fuera... Devuelve mih huesoh a ese agujero.', 'Hay demasiada luz aquí fuera... Devuelve mih huesoh a ese agujero.', 28153),
(152536, 'esES', '', 'Kul Tiras está formado por varias casas. Aunque se unificaron bajo el mando de Daelin Valiente, la situación cambió tras su derrota en Theramore.', 28153),
(152535, 'esES', '', 'Ahora la lady almirante Katherine Valiente gobierna en su lugar, y está al mando del ejército y de la guardia.', 28153),
(152534, 'esES', '', 'Aunque se intente mantener el orden, en Kul Tiras no dejan de aumentar el crimen, la corrupción y la piratería.\nLa gente está perdiendo la fe en el almirantazgo de los Valiente.', 28153),
(152533, 'esES', '', '.', 28153),
(152532, 'esES', '', '.', 28153),
(152531, 'esES', 'Buenos días. ¿Necesitas descansar? ¿Un refrigerio tal vez?', '', 28153),
(152530, 'esES', 'Para mí, es un honor servir a lord y lady Norwington. Si deseas alquilar una habitación para descansar, no dudes en preguntarme.', '', 28153),
(152529, 'esES', 'Una propiedad como esta implica mucho trabajo. Entre fabricar herraduras, reparar rastrillos y ocuparse de algún que otro trabajo ocasional, ¡las labores de un herrero nunca terminan!', '', 28153),
(152528, 'esES', '¿Necesitas reparar algo? Mi especialidad son las herraduras, pero veré qué puedo hacer con tu armadura.', '', 28153),
(152527, 'esES', '', 'Corred. ¡Corred!', 28153),
(152526, 'esES', '', 'Es muy sencillo: tú no sufras ninguna herida y yo no tendré que sanarte.', 28153),
(152525, 'esES', '', 'Los retendré mientras pueda.', 28153),
(152524, 'esES', 'Esto de la pesca es lo tuyo. ¡Sabía que te iría de maravilla! ¡Y todavía conservas brazos y piernas!', '', 28153),
(152523, 'esES', 'Los gusanos de arena son depredadores salvajes que acechan bajo las dunas. Son peligrosos, ¡pero sus colmillos se pagan bien! ¡Toma mi caña de pescar y a ver qué coges!', '', 28153),
(152522, 'esES', 'Las cosas siempre pueden empeorar. Hacemos lo que podemos con los recursos que tenemos.', '', 28153),
(152521, 'esES', 'La flota de Kul Tiras ya obedece mis órdenes. Sucumbid a mi voluntad.', '', 28153),
(152520, 'esES', '', 'No... No creo que pueda seguir.', 28153),
(152519, 'esES', '', 'Solo unos pasos más. ¡No te dejaremos atrás!', 28153),
(152518, 'esES', 'Muéstrales el poder de nuestros nuevos aliados.', '', 28153),
(152517, 'esES', 'Ya no me queda nada, Zem\'lan... Me lo arrebatahte todo.', 'Ya no me queda nada, Zem\'lan... Me lo arrebatahte todo.', 28153),
(152516, 'esES', '¡Otro carnoso al que dominar! Será divertido.', '¡Otro carnoso al que dominar! Será divertido.', 28153),
(152514, 'esES', '', '¡Venga, ya casi estamos!', 28153),
(152513, 'esES', '', 'Solo tenemos que llegar al altar de ahí delante.', 28153),
(152512, 'esES', 'Creéis que os vais a interponer en mi camino, pero el destino de Kul Tiras ya está sellado.', '', 28153),
(152507, 'esES', 'Dejaré que comuniques las buenas noticias. Yo me encargaré de esos cañones.', '', 28153),
(152506, 'esES', '¡Ese es el último!', '', 28153),
(152505, 'esES', 'Ja, ha caído otro. Solo queda uno...', '', 28153),
(152504, 'esES', '¡FUEGO!', '', 28153),
(152503, 'esES', 'Eso ha atraído su atención, sin duda. ¡Ten cuidado con la Horda mientras recargo!', '', 28153),
(152502, 'esES', 'De acuerdo, allá vamos. ¡Tápate los oídos!', '', 28153),
(152501, 'esES', 'Ojalá utilizaran su poder para sanar a Azeroth en lugar de hacerle daño. Buen trabajo, adalid.', '', 28153),
(152500, 'esES', 'Están drenando poder de la azerita de esta zona. ¡Tienes que detenerlos!', '', 28153),
(152499, 'esES', 'Y seré yo quien os guíe hasta nuestro glorioso futuro bajo las olas.', '', 28153),
(152498, 'esES', '', '¡Este poder... será... nuestro!', 28153),
(152497, 'esES', '', '¡Con este poder nadie podrá hacer frente a los sethrak!', 28153),
(152496, 'esES', '¡Recuperad las joyas y colocadlas en sus ranuras para que podamos pasar!', '', 28153),
(152495, 'esES', '¡Han sacado los ojos de Sethraliss!', '', 28153),
(152494, 'esES', 'Tengo todo lo que necesito. Habla conmigo cuando quieras empezar el ritual.', '', 28153),
(152493, 'esES', 'Lo vi caminando hacia la ciudad. Máh le vale no hacer el ridículo o la gente se encargará de él.', '', 28153),
(152492, 'esES', 'Te he vihto ir y venir durante mucho tiempo. He observado tuh peleah y triunfoh con el pequeño. Deberíah ehtar $gorgulloso:orgullosa; de él. $gOrgulloso:Orgullosa; de no separarte de él. Muchoh no habrían hecho lo mihmo.\n\nTrata bien a Kua\'fon. Será un compañero leal, aunque no vuele demasiado bien.', '', 28153),
(152491, 'esES', '', 'G\'huun... quiere... ehte poder...', 28153),
(152490, 'esES', '', '¡Ehta energía noh dará poder, no noh detendráh!', 28153),
(152489, 'esES', 'Ayudando', 'Ayudando', 28153),
(152488, 'esES', 'Eviscerando', 'Eviscerando', 28153),
(152487, 'esES', 'A veces parece que toda la ciénaga viene a por nosotros. ¡Menos mal que estás a la altura del desafío!', '', 28153),
(152486, 'esES', 'Esto me da mala espina... Nuestros exploradores deberían haber vuelto hace rato. Averigua por qué se están retrasando.', '', 28153),
(152484, 'esES', '', 'Continuemos.', 28153),
(152483, 'esES', '', 'Fue su padre quien nos guio hasta este valle hace muchos años.', 28153),
(152482, 'esES', '', 'En absoluto. Era muy atento antes de que empezaran los susurros.', 28153),
(152481, 'esES', '', '¿Siempre fue tan cruel lord Canto Tormenta?', 28153),
(152480, 'esES', '', 'Adiós a la discreción.', 28153),
(152479, 'esES', '', '¿Vais a dejar que me enfrente sola a la muerte?', 28153),
(152478, 'esES', '¡Esta piedra rezuma poder de la mismísima Azshara! Llévasela a las tropas del fuerte, ellos sabrán qué hacer.', '', 28153),
(152477, 'esES', 'Gracias, pero ¡tú y yo deberíamos largarnos de aquí!', 'Gracias, pero ¡tú y yo deberíamos largarnos de aquí!', 28153),
(152476, 'esES', '¡No seré pasto de los bebés de pterrordáctilo!', '¡No seré pasto de los bebés de pterrordáctilo!', 28153),
(152475, 'esES', 'El comandante me despellejará por dejarme atrapar por la fauna.', 'El comandante me despellejará por dejarme atrapar por la fauna.', 28153),
(152474, 'esES', '¡Gracias! Creí que estaba siendo cuidadoso, pero otra bestia se me abalanzó por el costado. Muy lista.', '¡Gracias! Creí que estaba siendo cuidadoso, pero otra bestia se me abalanzó por el costado. Muy lista.', 28153),
(152473, 'esES', '¡Ay, sus garfas hacen mucho daño!', '¡Ay, sus garfas hacen mucho daño!', 28153),
(152472, 'esES', 'Esoh malditoh pterrordáctiloh son un engorro. ¡No quiero que mih soldadoh se conviertan en comida!', 'Esoh malditoh pterrordáctiloh son un engorro. ¡No quiero que mih soldadoh se conviertan en comida!', 28153),
(152471, 'esES', 'Esos malditos pterrordáctilos son un engorro. ¡No quiero que mis soldados se conviertan en comida!', 'Esos malditos pterrordáctilos son un engorro. ¡No quiero que mis soldados se conviertan en comida!', 28153),
(152470, 'esES', 'Esperaba que pudiéramos quitar a los pterrordáctilos de en medio para utilizar la atalaya de la colina, ¡pero nos están liquidando uno a uno como si nada!', 'Esperaba que pudiéramos quitar a los pterrordáctilos de en medio para utilizar la atalaya de la colina, ¡pero nos están liquidando uno a uno como si nada!', 28153),
(152469, 'esES', 'Los mogu... encontrarán... más... piedras...', '', 28153),
(152468, 'esES', '¡El poder de esta piedra revivirá el imperio mogu!', '', 28153),
(152467, 'esES', '¡Buen trabajo! Había un par más de los que esperaba.', '', 28153),
(152466, 'esES', '¡Loh Gurubashi se han sumido en un frenesí homicida! Ayudémohloh... ¡con la muerte! ¡Golpea el gong y veráh como vienen corriendo!', '', 28153),
(152465, 'esES', 'Hemos recibido informes de agitación entre los trols de la zona y tememos un ataque inminente. Es hora de reducir su número. ¡Haz sonar el gong en lo alto de las escaleras para provocarlos!', '', 28153),
(152464, 'esES', 'Te agradeceremos cualquier ayuda que nos puedas prestar.', 'Te agradeceremos cualquier ayuda que nos puedas prestar.', 28153),
(152463, 'esES', '¡Dame un hacha y me pondré a cortar!', '', 28153),
(152462, 'esES', '¿Mimbre? ¿Bestias? ¡Lucharé contra todo lo que se interponga en mi camino!', '', 28153),
(152461, 'esES', '¡La gente de Kul Tiras nunca se rinde sin luchar!', '', 28153),
(152460, 'esES', 'Gracias por la ayuda.', '', 28153),
(152459, 'esES', '', '¡Tenemos compañía!', 28153),
(152458, 'esES', '¡VENGA, VENGA!', '¡VENGA, VENGA!', 28153),
(152457, 'esES', '¡Muy bien, marinos! ¡Escuchad! Cuando alcancemos la playa, quiero a $n al frente. Usa esa bonita pistola de bengalas para iluminar todo lo que se mueva.', '¡Muy bien, marinos! ¡Escuchad! Cuando alcancemos la playa, quiero a $n al frente. Usa esa bonita pistola de bengalas para iluminar todo lo que se mueva.', 28153),
(152456, 'esES', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(152455, 'esES', '¡Aplastad a esos intrusos o me quedo vuestro plus de peligrosidad, gusanos!', '', 28153),
(152454, 'esES', 'Protocolo de reparación de emergencia en curso...', '', 28153),
(152453, 'esES', '¡Dulce, dulce azerita!', '', 28153),
(152452, 'esES', '¡Perfora como si no hubiera un mañana!', '', 28153),
(152451, 'esES', '', 'Será seguro si Canto Tormenta no advierte nuestra presencia.', 28153),
(152450, 'esES', '', 'Es directo.', 28153),
(152449, 'esES', '', '¿Es... seguro?', 28153),
(152448, 'esES', '', 'Los Sabiomar recorren este camino ceremonial para ser bendecidos en el santuario.', 28153),
(152447, 'esES', '', '¡Tus heridas no sanarán mientras seas víctima de la maldición!', 28153),
(152446, 'esES', '', 'Este no puede ser el fin.', 28153),
(152445, 'esES', '', '¡Si fracasas, estoy perdida!', 28153),
(152444, 'esES', '', '¡No debes caer!', 28153),
(152443, 'esES', '¡Atención! ¡Nivel de combustible crítico!', '', 28153),
(152442, 'esES', '¡Atención! Se ha detectado un usuario no autorizado.', '', 28153),
(152441, 'esES', '¡Atención! Tu licencia se ha quedado sin puntos.', '', 28153),
(152440, 'esES', 'Ahí viene otro, ¡prepárate!', 'Ahí viene otro, prepárate para escupir.', 28153),
(152439, 'esES', 'Escupe más alto: llegará más lejos y no fallarás.', 'Escupe más alto: llegará más lejos y no fallarás.', 28153),
(152438, 'esES', '¡Prepárate!', '¡Prepárate!', 28153),
(152437, 'esES', 'Escupe justo cuando despeguen. ¡Así les daremos seguro!', 'Escupe justo cuando despeguen. ¡Así les daremos seguro!', 28153),
(152436, 'esES', '¡Se aceeercaaa un enaaaanooo!', '', 28153),
(152435, 'esES', 'Es una pena que la azerita esté volviendo locos a los elementales. Tenemos que poner fin a esta situación.', '', 28153),
(152434, 'esES', 'Han imbuido de azerita a algunos elementales y se están volviendo locos. ¡Acaba con ellos y absorbe su azerita!', '', 28153),
(152433, 'esES', '¡Están aquí! ¡Prended la munición!', '', 28153),
(152432, 'esES', '', 'Las piedras se mueven... ¡Las conseguiremos todas!', 28153),
(152431, 'esES', '', '¡El poder de esta piedra alimentará nuestro imperio!', 28153),
(152430, 'esES', '<Glibb te mira con curiosidad. Brann no se atreve a decirle que no es un mono>.', '<Glibb te mira con curiosidad. Brann no se atreve a decirle que no es un mono>.', 28153),
(152429, 'esES', 'Te doy la bienvenida al Nidal del Halcón. Gracias a ti los monstruos han retrocedido y podemos retomar la ciudad. Por favor, quédate todo el tiempo que quieras.', 'Te doy la bienvenida al Nidal del Halcón. Gracias a ti los monstruos han retrocedido y podemos retomar la ciudad. Por favor, quédate todo el tiempo que quieras.', 28153),
(152428, 'esES', 'Parece que esas armas son de origen goblin. Da igual, nos vendrán bien contra los sethrak.', '', 28153),
(152427, 'esES', 'Nisha ha conseguido unas armas interesantes... Podríamos usarlas contra los sethrak, si descubrimos cómo funcionan.', '', 28153),
(152426, 'esES', '¡Nunca había visto nada parecido a esos monstruos!', '¡Nunca había visto nada parecido a esos monstruos!', 28153),
(152425, 'esES', '¿Puedo salir de aquí volando?', '¿Puedo salir de aquí volando?', 28153),
(152424, 'esES', 'Ahora no, me temo.\n\nIntenté salir volando cuando el caos comenzó, pero nos atacaron con magia desde el suelo. Lionel se llevó un golpe en el costado y casi no volvemos a Médano del Halcón con vida.\n\nEl alcalde Royston nos ha dicho que nos quedemos hasta que retomemos la ciudad o la situación mejore.\n\nLo siento, pero de momento no podemos volar.', 'Ahora no, me temo.\n\nIntenté salir volando cuando el caos comenzó, pero nos atacaron con magia desde el suelo. Lionel se llevó un golpe en el costado y casi no volvemos a Médano del Halcón con vida.\n\nEl alcalde Royston nos ha dicho que nos quedemos hasta que retomemos la ciudad o la situación mejore.\n\nLo siento, pero de momento no podemos volar.', 28153),
(152423, 'esES', '¡Vaya, desde luego eso no me lo esperaba! Seguro que nuestros magos querrán echarle un vistazo a esto. Un trabajo excelente.', '', 28153),
(152422, 'esES', 'Nuestros espías nos informan de que la Horda planea arrebatar algún tipo de artefacto a esos sethrak. ¿Qué te parece si nos adelantamos?', '', 28153),
(152421, 'esES', 'Déjate llevar, $n.', '', 28153),
(152420, 'esES', '¡Guaaaaaauuuuuuuuu!', '', 28153),
(152417, 'esES', '', '¡Buen trabajo! Ahora esas cosas permanecerán bajo tierra, donde les corresponde.', 28153),
(152416, 'esES', '', 'Sucias criaturas... Están sacrificando a los suyos para crear monstruos. ¡Hay que detenerlos antes de que sus plantas carnívoras nos superen!', 28153),
(152415, 'esES', '<Hacer cola para una expedición insular en dificultad normal con tu grupo>.', '<Hacer cola para una expedición insular en dificultad normal con tu grupo>.', 28153),
(152414, 'esES', '', '¡Nosotroh... controlamoh... la azerita!', 28153),
(152413, 'esES', '', '¡Mi magia de sangre doblega la azerita!', 28153),
(152412, 'esES', '¡Que me arranquen loh huesoh! Claro que ehtoy lihto pa un motín. ¡Llevo semanah colgado aquí!', '¡Que me arranquen loh huesoh! Claro que ehtoy lihta pa un motín. ¡Llevo semanah colgada aquí!', 28153),
(152411, 'esES', '', 'Interesante... Puede que estos objetos nos ayuden a entender tanto los fenómenos extraños de Nazmir como el origen de los viles trols de sangre.', 28153),
(152410, 'esES', '', 'Nuestros investigadores quieren que recojamos los artefactos que encontremos para que no caigan en manos de la Horda. Busca en estas ruinas cualquier cosa de utilidad.', 28153),
(152409, 'esES', 'No hay nada como un buen motín. Me apunto.', 'No hay nada como un buen motín. Me apunto.', 28153),
(152407, 'esES', 'Me uniré a tu motín con mucho guhto. El rey pirata Zem\'lan pagará por su traición.', 'Me uniré a tu motín con mucho guhto. El rey pirata Zem\'lan pagará por su traición.', 28153),
(152406, 'esES', 'Si tienes oro, puedes gastarlo aquí.\n\nNo interfieras en el negocio y mi gente te dejará en paz, ¿entendido?', 'Si tienes oro, puedes gastarlo aquí.\n\nNo interfieras en el negocio y mi gente te dejará en paz, ¿entendido?', 28153),
(152405, 'esES', '', 'Habla con algunas de las personas más influyentes de la zona: Klause Vientopropicio, Kane Carlyle, Klonk Piezagrasienta y Fixi Pincholadino.\n\nSírveme de agente y averigua si necesitan algún favor; yo también precisaré su apoyo.\n\nSi no necesitas nada más, seguiré hablando con esta buena gente que anda un poco preocupada.', 28153),
(152404, 'esES', '¿Con quién debería hablar?', '¿Con quién debería hablar?', 28153),
(152403, 'esES', 'Solo con doh no se hace un motín. ¡Recluta a máh gente!', '', 28153),
(152402, 'esES', '¿Dónde está tu guardián?', '', 28153),
(152401, 'esES', 'No eres una bestia muy educada.', '', 28153),
(152400, 'esES', 'Me iba a comer eso.', '', 28153),
(152399, 'esES', 'Deberías parar.', '', 28153),
(152398, 'esES', '¡Tieneh que pagar por eso!', '¡Tieneh que pagar por eso!', 28153),
(152397, 'esES', '¡Eso no eh tuyo!', '¡Eso no eh tuyo!', 28153),
(152396, 'esES', '¡Oye! ¡Ehcupe eso!', '¡Oye! ¡Ehcupe eso!', 28153),
(152395, 'esES', 'Mih huesoh se alzarán de nuevo.', '', 28153),
(152394, 'esES', '¡Alzaoh, mih marionetah! ¡Y matad!', '', 28153),
(152393, 'esES', 'Venid, buitres... Este es el festín... que esperabais...', '', 28153),
(152392, 'esES', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡$n |cFFFF0000|Hspell:267343|h[Suelta]|h|r el orbe!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡$n |cFFFF0000|Hspell:267343|h[Suelta]|h|r el orbe!', 28153),
(152391, 'esES', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t¡A $n le han |cFFFF0000|Hspell:267633|h[Arrebatado]|h|r el orbe de las manos!', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t¡A $n le han |cFFFF0000|Hspell:267633|h[Arrebatado]|h|r el orbe de las manos!', 28153),
(152390, 'esES', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡%s |cFFFF0000|Hspell:265755|h[Reclama]|h|r uno de los orbes!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡%s |cFFFF0000|Hspell:265755|h[Reclama]|h|r uno de los orbes!', 28153),
(152389, 'esES', '¡Te colgaré boca abajo y dejaré que los buitres te coman!', '', 28153),
(152388, 'esES', 'Primero haremoh correr la voz. Y tú debeh comprender muy bien a qué peligro noh enfrentamoh.', '', 28153),
(152387, 'esES', '¡Así que noh amotinamoh!', '', 28153),
(152386, 'esES', 'Me gustaría hacer otra pregunta.', 'Me gustaría hacer otra pregunta.', 28153),
(152385, 'esES', '¡Oye! ¡Ya bahta!', '¡Oye! ¡Ya bahta!', 28153),
(152384, 'esES', '¡Largo!', '¡Largo!', 28153),
(152383, 'esES', '¡Fuera, fuera!', '¡Fuera, fuera!', 28153),
(152382, 'esES', '¡Deja de armar ehcándalo!', '¡Deja de armar ehcándalo!', 28153),
(152381, 'esES', '¡Baja de ahí!', '¡Baja de ahí!', 28153),
(152380, 'esES', '¿Un loro? ¿Nada de cometas?', '¿Un loro? ¿Nada de cometas?', 28153),
(152379, 'esES', '<Tan se ríe>\n\nLos loros son mucho más inteligentes e interesantes que una cometa.\n\n<Tan abre un ojo y le lanza una mirada a su pájaro>\n\nAunque a veces griten por diversión.', '<Tan se ríe>\n\nLos loros son mucho más inteligentes e interesantes que una cometa.\n\n<Tan abre un ojo y le lanza una mirada a su pájaro>\n\nAunque a veces griten por diversión.', 28153),
(152378, 'esES', 'Desde que llegó la Marea de Hierro, Richard Velarrasgada tiene que aprobar los vuelos de entrada y salida.\n\nEn teoría es por \"seguridad\" y por mantener la existencia de la cala en \"secreto\", pero yo creo que es para que pueda controlarlo todo.\n\nTendría que aprobarlo él. Mira, si no obedezco me juego el pellejo y las alas de mi pájaro.\n\n<Tan se inclina hacia delante y baja la voz>\n\nQuizás si otra persona estuviera al mando...', 'Desde que llegó la Marea de Hierro, Richard Velarrasgada tiene que aprobar los vuelos de entrada y salida.\n\nEn teoría es por \"seguridad\" y por mantener la existencia de la cala en \"secreto\", pero yo creo que es para que pueda controlarlo todo.\n\nTendría que aprobarlo él. Mira, si no obedezco me juego el pellejo y las alas de mi pájaro.\n\n<Tan se inclina hacia delante y baja la voz>\n\nQuizás si otra persona estuviera al mando...', 28153),
(152377, 'esES', '¿Puedo tomar un vuelo para salir de aquí?', '¿Puedo tomar un vuelo para salir de aquí?', 28153),
(152376, 'esES', 'Tendráh que ayudarme a bajar. Me ataron fuerte dehpuéh de mi última huida.', '', 28153),
(152375, 'esES', '¡Estupendo! ¡Me largo de aquí!', '¡Estupendo! ¡Me largo de aquí!', 28153),
(152374, 'esES', 'Tal vez... si te atreves... ¡dile que la próxima vez traeré un sombrero!', '', 28153),
(152373, 'esES', 'Ya no eres tan grande y fuerte, ¿eh? Ve, secuaz. Ve y busca a esa rata de Alfin que te ordenó matar a los míos. Muérdelo y recupera tu forma original.', '', 28153),
(152372, 'esES', '¿La Horda está aquí? ¿De dónde han salido? ¿Quién nos protegerá?', '¿La Horda está aquí? ¿De dónde han salido? ¿Quién nos protegerá?', 28153),
(152371, 'esES', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Merektha |cFFFF0000|Hspell:264206|h[Excava]|h|r por el campo de batalla!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Merektha |cFFFF0000|Hspell:264206|h[Excava]|h|r por el campo de batalla!', 28153),
(152370, 'esES', 'Gracias, $gamigo:amiga;. ¡Pensaba que no saldría de esta, menos mal que llegaste!', 'Gracias, $gamigo:amiga;. ¡Pensaba que no saldría de esta, menos mal que llegaste!', 28153),
(152369, 'esES', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t¡Un |cFFFF0000|Hspell:263958|h[nudo de serpientes]|h|r envuelve a $n! ¡$gLiberadlo:Liberadla;!', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t¡Un |cFFFF0000|Hspell:263958|h[nudo de serpientes]|h|r envuelve a $n! ¡$gLiberadlo:Liberadla;!', 28153),
(152368, 'esES', 'El día en que el Puerto de Zem\'lan quedó maldito... Hace tanto tiempo...', '', 28153),
(152367, 'esES', 'El medallón te revelará mi pasado cuando lo soliciteh.', '', 28153),
(152366, 'esES', 'G-g-gracias. M-M-M-Meeki es un buen amigo.', 'G-g-gracias. M-M-M-Meeki es un buen amigo.', 28153),
(152365, 'esES', 'Te he fallado... Korthek...', '', 28153),
(152364, 'esES', '¡Será un placer satisfacer tus ganas de morir!', '', 28153),
(152363, 'esES', 'Somos... imparables...', '', 28153),
(152362, 'esES', '¡Insolente! ¡Pagarás por tu intrusión!', '', 28153),
(152361, 'esES', '', 'Tu comandante está esperando ahí abajo, en el campo de batalla.', 28153),
(152360, 'esES', 'Esto... no ha acabado...', 'Esto... no ha acabado...', 28153),
(152359, 'esES', 'Hemos encontrado un extraño pergamino con el que, supuestamente, se puede invocar a un ser de un poder inimaginable. Los no-muertos se reúnen en la costa. Veamos si funciona.', '', 28153),
(152358, 'esES', 'Esto... no ha acabado...', 'Esto... no ha acabado...', 28153),
(152357, 'esES', 'Mi vida... por el imperio...', 'Mi vida... por el imperio...', 28153),
(152356, 'esES', 'No puede ser...', 'No puede ser...', 28153),
(152355, 'esES', 'Las arenas... se extenderán...', 'Las arenas... se extenderán...', 28153),
(152354, 'esES', 'Mi muerte... será... vengada...', 'Mi muerte... será... vengada...', 28153),
(152353, 'esES', 'Te he fallado... Korthek...', 'Te he fallado... Korthek...', 28153),
(152352, 'esES', 'Esto no es... una victoria...', 'Esto no es... una victoria...', 28153),
(152351, 'esES', 'No nos... detendrán...', 'No nos... detendrán...', 28153),
(152349, 'esES', 'Mi vida... por el imperio...', 'Mi vida... por el imperio...', 28153),
(152348, 'esES', 'No puede ser...', 'No puede ser...', 28153),
(152347, 'esES', 'Las arenas... se extenderán...', 'Las arenas... se extenderán...', 28153),
(152346, 'esES', 'Mi muerte... será... vengada...', 'Mi muerte... será... vengada...', 28153),
(152345, 'esES', 'Te he fallado... Korthek...', 'Te he fallado... Korthek...', 28153),
(152344, 'esES', 'Esto no es... una victoria...', 'Esto no es... una victoria...', 28153),
(152343, 'esES', 'Nadie nos... detendrá...', 'Nadie nos... detendrá...', 28153),
(152342, 'esES', '', 'Bien hecho. Como siempre, un trabajo digno de admiración.', 28153),
(152341, 'esES', '', 'Esos trols de sangre han atacado el Fuerte Victoria. ¡Sus asaltos no deben quedar impunes!', 28153),
(152340, 'esES', '¡Daos prisa, ratas! ¡Esta azerita no explotará sola!', '', 28153),
(152339, 'esES', '', 'Quemaron Brennadam. Nadie volverá a casa.', 28153),
(152338, 'esES', '¡Máh rápido!', '', 28153),
(152337, 'esES', 'Me recuerdas a cierto hozen joven que conocí una vez. Creía que era el rey de los monos o alguna tontería así. No dejaba de darme toquecitos.', '', 28153),
(152336, 'esES', 'Si crees que puedes molestarme, siento decepcionarte.', '', 28153),
(152335, 'esES', 'Creo que deberíamos comerciar con criaturas de todas las razas y creencias... Menos con los nagas. ¡Qué horror de bichos!', '', 28153),
(152334, 'esES', 'Si encuentras artefactos poderosos, tráemelos y no intentes usarlos tú.', '', 28153),
(152333, 'esES', 'Pff. Los artefactos de gran poder están mejor en manos de los ancianos y no en las de aventureros inquietos.', '', 28153),
(152332, 'esES', 'Nunca subestimes el valor o el poder de algo de más de dos siglos de antigüedad.', '', 28153),
(152331, 'esES', 'Bla, bla, bla. Corta ya.', '', 28153),
(152330, 'esES', '¿Cuáles son tus tarifas por heroicidad y tus costes funerarios?', '', 28153),
(152329, 'esES', 'Bien, alguien que ha vivido aventuras. Necesito tus servicios.', '', 28153),
(152328, 'esES', '¡Os presento... la Cadena Pétrea!', '', 28153),
(152327, 'esES', '¡Estáis viendo el futuro, chicos!', '', 28153),
(152326, 'esES', '¡Felicidades, muchachos, vamos a ser ricos!', '', 28153),
(152325, 'esES', '', '¡Entra! ¡No seas un miedosaurio!', 28153),
(152324, 'esES', 'Nunca aceptes regalos del Imperio Negro.', '', 28153),
(152323, 'esES', 'Puede que nos volvamos a ver en el campo de batalla. Juntos, y superados en número, en equipo y en clase. Je, je.', '', 28153),
(152322, 'esES', '¡Me toca, ven a por el pez!', '', 28153),
(152321, 'esES', '¡Siéntate, hermana!', '', 28153),
(152320, 'esES', '¡Qué inmadura eres!', '', 28153),
(152319, 'esES', '¡Ay! ¡Hah asuhtado a mi pez!', '', 28153),
(152318, 'esES', '', '¡RAAK! ¡Soy Pa\'ku! ¡Fiuu!', 28153),
(152317, 'esES', '', '¡Mira, soy Gral!', 28153),
(152316, 'esES', '', '¡Taz\'okun!', 28153),
(152315, 'esES', '', '¡Ueee!', 28153),
(152314, 'esES', 'Buena suerte. Intenta no morir.', '', 28153),
(152313, 'esES', 'Nunca descuides tu retaguardia... o ponte un caparazón.', '', 28153),
(152312, 'esES', 'Lo pagarás... caro...', 'Lo pagarás... caro...', 28153),
(152311, 'esES', 'No es... justo...', 'No es... justo...', 28153),
(152310, 'esES', '¡Discípulos! ¡Se acercan intrusos a las pozas sagradas!', '', 28153),
(152309, 'esES', 'No... Esto es mío...', 'No... Esto es mío...', 28153),
(152308, 'esES', '¿Cómo... te... atreves...?', '¿Cómo... te... atreves...?', 28153),
(152307, 'esES', '¡Parece que me pagarás con tu pellejo!', '¡Parece que me pagarás con tu pellejo!', 28153),
(152306, 'esES', 'No me desagrada un tumulto. A veces, también he participado en altercados... y hasta en reyertas.', '', 28153),
(152305, 'esES', '¡Te cobraré el doble por eso!', '¡Te cobraré el doble por eso!', 28153),
(152304, 'esES', '¡Parece que te cobraré un ojo de la cara!', '¡Parece que te cobraré un ojo de la cara!', 28153),
(152303, 'esES', '¡Oye! ¡Lo pagarás caro!', '¡Oye! ¡Lo pagarás caro!', 28153),
(152302, 'esES', 'Me han apuñalado por la espalda más razas de las que conoces, así que nada de ideas raras.', '', 28153),
(152301, 'esES', 'Zem\'lan no conoce la piedad, solo la muerte. E incluso a muchoh se la deniega.', '', 28153),
(152300, 'esES', 'Cavando', 'Cavando', 28153),
(152299, 'esES', 'Estoy listo.', 'Estoy lista.', 28153),
(152298, 'esES', '', 'No descansaré hasta que la cabeza de lord Canto Tormenta cuelgue de estos muros.', 28153),
(152297, 'esES', '', '¡Esa es la potencia de fuego que necesitamos!', 28153),
(152296, 'esES', 'Je... Está... bien...', 'Je... Está... bien...', 28153),
(152295, 'esES', 'Lo pagarás... caro...', 'Lo pagarás... caro...', 28153),
(152294, 'esES', 'Nadie... puede... vencerme...', 'Nadie... puede... vencerme...', 28153),
(152293, 'esES', 'Pero... soy el jefe...', 'Pero... soy el jefe...', 28153),
(152292, 'esES', 'Conque le plantas cara al jefe de la cala, ¿eh? ¡JA! ¡Te machacaré igual que al último!', 'Conque le plantas cara al jefe de la cala, ¿eh? ¡JA! ¡Te machacaré igual que al último!', 28153),
(152291, 'esES', '¡Soy el jefe de este lugar! ¡Más te vale ponerte firme!', '¡Soy el jefe de este lugar! ¡Más te vale ponerte firme!', 28153),
(152290, 'esES', 'Silencio. Meeki está bien y yo estoy intentando dormir.', 'Silencio. Meeki está bien y yo estoy intentando dormir.', 28153),
(152289, 'esES', '¡Te pasaré por la quilla!', '¡Te pasaré por la quilla!', 28153),
(152288, 'esES', '¡Nadie navega contra la Marea de Hierro!', '¡Nadie navega contra la Marea de Hierro!', 28153),
(152287, 'esES', '¿Cómo te atreves?', '¿Cómo te atreves?', 28153),
(152286, 'esES', 'Si encuentras tesoros por el camino, tráetelos. Te recompensaremos por las molestias.', 'Si encuentras tesoros por el camino, tráetelos. Te recompensaremos por las molestias.', 28153),
(152285, 'esES', 'Lo pagarás caro...', 'Lo pagarás caro...', 28153),
(152284, 'esES', 'Nadie navega contra la Marea de Hierro...', 'Nadie navega contra la Marea de Hierro...', 28153),
(152283, 'esES', 'Te... atraparé...', 'Te... atraparé...', 28153),
(152282, 'esES', 'Lo siento... jefe...', 'Lo siento... jefe...', 28153),
(152281, 'esES', '¡No puedes estar aquí!', '¡No puedes estar aquí!', 28153),
(152280, 'esES', '¿Qué haces husmeando por aquí?', '¿Qué haces husmeando por aquí?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'esES', '¡No deberías estar aquí!', '¡No deberías estar aquí!', 28153),
(152278, 'esES', '¡Oye!', '¡Oye!', 28153),
(152277, 'esES', '', '¿Sabías que se pueden usar agallas de tiburón ballena en la sopa? ¡Evita que se pudran las escamas! Oh, ¿de qué estábamos hablando?', 28153),
(152276, 'esES', '', 'Bueno, cuando dije \"todo el mundo\" supongo que me refería a todos los que tengan oro para gastar. Humanos, goblins, tauren, elfos, da igual. Su oro vale lo mismo.\n\n<Cesi te mira de arriba abajo>\n\nVaya. Te preguntas si haría negocios con la Horda.\n\nMira, tengo que ganarme la vida. Si tengo un par de anclas que se han caído de un barco, se las vendo al primer cliente que aparezca. Así son los negocios. Cuando me convierta en la jefa, todo el mundo será libre de venir a la cala a comerciar.\n\nSupongo que no querrás tratar con esos piratas Marea de Hierro, ¿verdad?\n\nConfía en mí, colega, va a ser genial.', 28153),
(152275, 'esES', 'Mi prole tiene mejores modales que tú.', '', 28153),
(152274, 'esES', '¿A qué te refieres con libre comercio para \"todo el mundo\"?', '¿A qué te refieres con libre comercio para \"todo el mundo\"?', 28153),
(152271, 'esES', 'Salvo que quieras que convierta ese dedo en ofrenda, mejor que dejes de darme toquecitos.', '', 28153),
(152270, 'esES', 'La posada local está llena de refugiados, pero tengo una habitación libre que te puedo alquilar si necesitas alojamiento.', '', 28153),
(152269, 'esES', 'Recuerda: si encuentras algo brillante, tráeselo al viejo Jani.', '', 28153),
(152268, 'esES', '¿Puedo quedarme tus cosas cuando te vayas?', '', 28153),
(152266, 'esES', 'Que siempre encuentres amigos en los bajos fondos. ¡Ja!', '', 28153),
(152265, 'esES', '¡Bien hecho! Estas tierras son más seguras gracias a ti.', '', 28153),
(152264, 'esES', 'Nuestros espías han identificado una gran amenaza en esta zona. ¡Búscala y neutralízala!', '', 28153),
(152263, 'esES', '', 'Volved a unirlas y acabad con su mascota o no nos quedará nada para repeler a la flota de Gobernalle.', 28153),
(152262, 'esES', '', 'Era un tortoliano orgulloso, aunque no cabía en su caparazón, no sé si me entiendes. Una pena que se lo comiese un tiburón ballena.', 28153),
(152261, 'esES', '', 'Casi no me di cuenta de que estaba roncando. Tiene la voz áspera, muy parecida a la de mi segundo nieto.', 28153),
(152260, 'esES', '', 'Hay quien dice que tiendo a divagar. Aunque mi hermana era mucho peor. ¿Sabías que una vez se quedó dormida a media frase?', 28153),
(152259, 'esES', 'Una pila de basura es el sitio donde guardar tus cosas mientras vas a por más cosas.', '', 28153),
(152258, 'esES', '', 'Qué educados son los aventureros hoy en día.', 28153),
(152257, 'esES', '', '¿Ha estado bien, eh?', 28153),
(152256, 'esES', '', 'Vuelve a visitar a la vieja Nola pronto.', 28153),
(152255, 'esES', '', 'Esto me recuerda una historia...', 28153),
(152254, 'esES', '', 'Qué cosa tan vivaz.', 28153),
(152253, 'esES', '', 'Me alegro mucho de verte, cielo.', 28153),
(152252, 'esES', 'Transpamplinador. ¡Convierte ideas terribles en ideas malas a secas!', 'Transpamplinador. ¡Convierte ideas terribles en ideas malas a secas!', 28153),
(152251, 'esES', '¡Kaja\'Cola, ahora con agua de verdad!', '¡Kaja\'Cola, ahora con agua de verdad!', 28153),
(152250, 'esES', '', 'Pareces el tipo de persona que disfruta con una buena historia.', 28153),
(152249, 'esES', '', 'Reúnete conmigo al norte de este pozo infernal cuando tengas la vara. Busca un montón de cadáveres de estos bellacos.', 28153),
(152248, 'esES', 'Sigue así y descubrirás por qué me llaman gruñón.', '', 28153),
(152246, 'esES', 'Saludos, alhaja.', '', 28153),
(152243, 'esES', 'Como siempre digo, la basura de unos es el loa de otros.', '', 28153),
(152241, 'esES', '', 'Nazmir es el hogar de muchas amenazas. Al menos, ahora hay una menos.', 28153),
(152239, 'esES', '', '¿Qué son esos bichos? ¡Adalid! Nuestros ingenieros tienen algo que nos será de ayuda. ¡Úsalo para quemar a esos engendros antes de que invadan nuestros campamentos!', 28153),
(152232, 'esES', 'Tu amistad es muy valiosa. Estas dunas son más seguras gracias a ti.', '', 28153),
(152231, 'esES', 'Nuestra caravana vio algo peligroso en las dunas. Lo dejo en tus manos.', '', 28153),
(152230, 'esES', 'Taelia, adalid, sois vosotros los que debéis llevar esta carga. Yo me llevaré a Samuel y, en cuanto pueda, nos reuniremos en el altar.', '', 28153),
(152229, 'esES', 'Entrando en comunión', 'Entrando en comunión', 28153),
(152228, 'esES', 'Sabía que eras inteligente. Vamos, nos reuniremos allí.', 'Sabía que eras inteligente. Vamos, nos reuniremos allí.', 28153),
(152227, 'esES', '¡Mucha suerte ocupándote de ellos! Yo me dedico al contrabando, no soy mercenario.', '¡Mucha suerte ocupándote de ellos! Yo me dedico al contrabando, no soy mercenaria.', 28153),
(152226, 'esES', '¡Bueno, entonces puede que la Marea de Hierro tenga que irse!', '¡Bueno, entonces puede que la Marea de Hierro tenga que irse!', 28153),
(152225, 'esES', 'La Marea de Hierro me está dejando sin oro, Cesi. Apenas llego a fin de mes.', 'La Marea de Hierro me está dejando sin oro, Cesi. Apenas llego a fin de mes.', 28153),
(152224, 'esES', 'Y ahora... ¡Que comience la caza!', '', 28153),
(152223, 'esES', '', '¡Mira, aún podemos sacar beneficios de esto!', 28153),
(152222, 'esES', '', 'Esta gente estaba intentando escapar. Debe de haber más supervivientes en algún sitio.', 28153),
(152221, 'esES', 'Esto es una prueba.', 'Esto es una prueba.', 28153),
(152220, 'esES', 'Hay que atacar ahora, antes de que informen a lord Canto Tormenta.', '', 28153),
(152219, 'esES', '|cFF0000FF(Misión)|r Viaja en barco a Nazmir.', '|cFF0000FF(Misión)|r Viaja en barco a Nazmir.', 28153),
(152218, 'esES', '', 'Este barco está a tu servicio, $n. He preparado a la tripulación para cualquier eventualidad.', 28153),
(152217, 'esES', '¿Dónde deberíamos dirigir nuestros esfuerzos?', '', 28153),
(152216, 'esES', 'Bueno, son cosas que pasan. La próxima vez que veamos a estos tipos, nos vengaremos.', '', 28153),
(152215, 'esES', 'Nada de caras largas, ¡hemos conseguido un buen botín!', '', 28153),
(152214, 'esES', 'Todo el mundo a bordo. Tenemos que irnos ya o perderemos el barco.', '', 28153),
(152213, 'esES', 'No se puede ganar siempre, pero la próxima vez venceremos.', '', 28153),
(152212, 'esES', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t¡Algunas de las defensas empiezan a |cFFFF0000|Hspell:267931|h[sobrecargarse]|h|r!', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t¡Algunas de las defensas empiezan a |cFFFF0000|Hspell:267931|h[sobrecargarse]|h|r!', 28153),
(152211, 'esES', 'Ya tenemoh suficiente. Larguémonoh.', '', 28153),
(152210, 'esES', 'No se pueden ganar todah lah batallah. Eh ley de vida.', '', 28153),
(152209, 'esES', '¡Bah! Tenemoh que irnoh. Ya oh encargaréih de elloh la próxima vez.', '', 28153),
(152208, 'esES', 'Buen trabajo, ¡leh habéih mohtrado quién manda! ¡Ja, ja!', '', 28153),
(152207, 'esES', 'Buen trabajo. ¡Dihparadle a ese barco de la Alianza cuando pasemoh por su lado!', '', 28153),
(152206, 'esES', 'El barco ehtá cargado. Izad velah, ¡volvemoh a casa!', '', 28153),
(152205, 'esES', 'Tenemoh lo que queríamoh. ¡Larguémonoh! ¡Ja, ja!', '', 28153),
(152204, 'esES', 'Traed lo que podáih. Pronto tendremoh que irnoh de aquí.', '', 28153),
(152203, 'esES', 'Parece que el otro barco partirá pronto. Tenemoh que darnoh prisa.', '', 28153),
(152202, 'esES', 'Parece que el barco de Kul Tirah ehtá casi lleno. Tendremoh que irnoh pronto.', '', 28153),
(152201, 'esES', 'Ya casi ehtamoh. Seguid así un poco máh...', '', 28153),
(152200, 'esES', 'El barco ehtá casi lleno. Solo un poco máh y podremoh partir.', '', 28153),
(152199, 'esES', 'Ya casi hemoh terminado. ¡Buen trabajo!', '', 28153),
(152198, 'esES', '¡Ja, ja! Eh imposible mantenerse en pie con ehte terremoto. Hay un poderoso elemental de tierra buhcando azerita como nosotroh.', '', 28153),
(152197, 'esES', 'El viento lo ehtá dehtruyendo todo. Seguro que eh culpa de un elemental de aire, y puede que tenga un buen puñado de azerita. Haceoh con ella.', '', 28153),
(152196, 'esES', 'Seguro que un señor del agua ha provocado ehta nevada. Liberadlo de su miseria. ¡Odio el frío!', '', 28153),
(152195, 'esES', 'Menudo calor... Seguro que un señor del fuego ha venido a por nuehtra azerita. ¡Eliminadlo anteh de que prenda fuego a lah velah!', '', 28153),
(152194, 'esES', 'Seguro que hay un señor elemental detráh de todo ehto. Si lo matáih, ¡quitadle la azerita!', '', 28153),
(152193, 'esES', 'Hoy tenemoh a loh elementoh en nuehtra contra. Seguro que buhcamoh lo mihmo...', '', 28153),
(152192, 'esES', 'Hemoh llamado la atención de unoh cuantoh elementaleh... ¡Cuidado con su líder!', '', 28153),
(152191, 'esES', 'Ehte tiempo no eh normal. Seguro que algún elemental poderoso quiere nuehtra azerita.', '', 28153),
(152190, 'esES', 'Aún tenemoh medio barco que llenar. ¡Prehtad mucha atención!', '', 28153),
(152189, 'esES', 'Lo ehtáih haciendo genial, ¡ya solo falta la mitad!', '', 28153),
(152188, 'esES', 'La bodega ehtá medio llena. ¡Seguid así y acabaremoh en nada!', '', 28153),
(152187, 'esES', 'Lah cosah se van a poner máh interesanteh.', '', 28153),
(152186, 'esES', 'Acaban de llegar unoh amigoh, ja, ja, ja.', '', 28153),
(152185, 'esES', 'Tened cuidado ahí fuera, ¡tenemoh compañía!', '', 28153),
(152184, 'esES', 'Hemoh llegado al dehtino. ¡En marcha! La azerita oh ehpera.', '', 28153),
(152183, 'esES', 'Ya hemoh atracado. Que no oh maten. ¡Ja, ja, ja!', '', 28153),
(152182, 'esES', 'Ya podéih desembarcar. Prepararemoh el detector.', '', 28153),
(152181, 'esES', 'Tenemoh un montón de azerita por aquí. Echadle un vihtazo.', '', 28153),
(152180, 'esES', '¡Acaba de salir un montón de azerita del suelo! ¿A qué ehperáih? ¡Ja, ja!', '', 28153),
(152179, 'esES', 'El artilugio se ha vuelto loco. ¡Seguro que hay un buen depósito de azerita por ahí!', '', 28153),
(152178, 'esES', '¡Detector conectado! Ehtoy marcando loh nodoh de azerita en el mapa.', '', 28153),
(152177, 'esES', 'Detector conectado. Mirad el mapa pa ver dónde se concentra la azerita.', '', 28153),
(152176, 'esES', '¡Yo solo descansar ojos! ¡Yo volver al trabajo ahora!', '', 28153),
(152175, 'esES', 'Vale, jefe, vuelvo a la mina.', '', 28153),
(152174, 'esES', 'Sueño... tener tanto sueño...', '', 28153),
(152173, 'esES', '¡Ay! ¡Muy bien, volveré al trabajo, $n!', '', 28153),
(152172, 'esES', 'Acaba con los aojadores hudú y sus tótems derribadores.', 'Acaba con los aojadores hudú y sus tótems derribadores.', 28153),
(152171, 'esES', 'Otro continente, otro demonio que cazar.', '', 28153),
(152170, 'esES', '¡Ja! Nunca me decepcionáis. Eso me gusta.', '', 28153),
(152169, 'esES', 'Ya hemos acabado. Buen trabajo, ¡volvamos a casa!', '', 28153),
(152168, 'esES', 'Tenemos montañas de azerita. Vámonos antes de que la Horda se dé cuenta.', '', 28153),
(152167, 'esES', '¡Nos vamos! Vaya, ¡mirad qué botín! Lo habéis hecho genial.', '', 28153),
(152166, 'esES', 'La Horda nos va ganando... ¡Tenéis que recoger azerita más deprisa!', '', 28153),
(152165, 'esES', 'Voy... con Xibala...', '', 28153),
(152164, 'esES', 'La Horda está acabando ya. Si no nos vamos pronto, estaremos vendidos.', '', 28153),
(152163, 'esES', 'La Horda casi ha acabado. Intentad coger todo lo que podáis.', '', 28153),
(152162, 'esES', 'No quiero alarmaros, pero creo que el barco de la Horda está casi lleno. En cuanto acaben, tendremos que irnos.', '', 28153),
(152161, 'esES', 'Ya casi hemos acabado. Mantened los ojos bien abiertos, ¡podéis conseguirlo!', '', 28153),
(152160, 'esES', 'Nuestra bodega reluce como el oro. Unas cuantas rocas más y nos vamos.', '', 28153),
(152159, 'esES', 'El casco está ya casi lleno de azerita. ¡Preparad las velas! Nos marcharemos en cuanto acabéis.', '', 28153),
(152158, 'esES', 'Eh, ¡ya casi hemos acabado! Solo un poco más y nos vamos.', '', 28153),
(152157, 'esES', '¿Por qué tiembla el suelo? Me estoy mareando... Hemos visto elementales de tierra, así que tiene que haber un señor elemental por aquí. ¡Id a por él antes de que acabe echando la pota!', '', 28153),
(152156, 'esES', 'Este huracán acabará por destrozarnos las velas. Parece que un señor elemental del viento ha enviado a sus esbirros a por la azerita. No podremos irnos mientras sigan por aquí.', '', 28153),
(152155, 'esES', 'Eh, ¿a-adalides? Un señor del agua ha enviado a sus tropas para que roben nuestra azerita. M-me estoy congelando... ¿Podéis encargaros? No me he traído el abrigo.', '', 28153),
(152154, 'esES', 'Cada vez hace más calor. ¿Pero qué...? Ah. Vale, eso lo explica todo: un señor del fuego ha enviado a sus esbirros a por la azerita. Genial.', '', 28153),
(152153, 'esES', 'Ya llevamos la mitad. ¡Seguid así y pronto podremos marcharnos!', '', 28153),
(152152, 'esES', 'Tenemos la bodega medio llena de azerita. Buen trabajo, ¡seguid así!', '', 28153),
(152151, 'esES', '¡Estás pisando terreno sagrado!', '', 28153),
(152150, 'esES', 'Estoy preparado.', 'Estoy preparada.', 28153),
(152149, 'esES', 'La inspección apuntaba a estas ruinas. El campamento de la Horda está bajando la colina, al noreste, así que será mejor que entremos y salgamos lo más rápido posible.\n\nConseguiremos el Aliento de Xibala antes que ellos, te lo garantizo.\n\nHabla conmigo cuando quieras empezar el reconocimiento.', '', 28153),
(152148, 'esES', 'El detector está en marcha. Consultad el mapa para ver dónde se encuentra la azerita.', '', 28153),
(152147, 'esES', 'Detector conectado. Voy a marcar en el mapa dónde se encuentra la azerita. De nada.', '', 28153),
(152146, 'esES', 'Acabo de descubrir un montón de cristales de azerita cerca de aquí. Seguro que es la causa de este temblor.', '', 28153),
(152145, 'esES', 'Se está acumulando una gran cantidad de azerita cerca de aquí. ¡Adelantaos a la Horda!', '', 28153),
(152144, 'esES', 'Ya podéis desembarcar. Prepararemos el detector de azerita mientras os encargáis de los malos.', '', 28153),
(152143, 'esES', 'Ya hemos atracado. ¡Disfrutad de la aventura! El detector de azerita pronto estará listo.', '', 28153),
(152142, 'esES', 'Ya estamos aquí. Ah, el viento no deja de despeinarme... Démonos prisa en recoger la azerita y largarnos.', '', 28153),
(152141, 'esES', 'Resulta que hay un señor elemental que busca la misma azerita que nosotros. Me ocultaré bajo cubierta mientras os encargáis de esta... situación.', '', 28153),
(152140, 'esES', 'La azerita está atrayendo a fuerzas elementales. Seguro que su señor codicia nuestro botín. Pero quien lo encuentra se lo queda, ¿no?', '', 28153),
(152139, 'esES', 'Veo que la Horda también ha encontrado esta isla. Su barco acaba de atracar.', '', 28153),
(152138, 'esES', 'La Horda está aquí. Tened mucho cuidado, ¿entendido?', '', 28153),
(152137, 'esES', 'Veo un barco hecho completamente de oro. Zandalari, sin duda. La Horda está aquí; tened cuidado.', '', 28153),
(152136, 'esES', 'Yo solía ser un aventurero como tú... y mejoré. Ja, ja.', '', 28153),
(152135, 'esES', 'Parece que has vivido bastantes gestas. Deberíamos intercambiar historias de guerra.', '', 28153),
(152134, 'esES', 'Recuerdo la gran guerra entre el rey Raka y su hermana, la reina Tola. Al menos recuerdo cosas. Bueno, estoy casi seguro de que sucedió. Al cincuenta por ciento.', '', 28153),
(152133, 'esES', 'Me recuerdas a un tipo con el que asalté las playas de Krasarang durante la tercera dinastía. Una pena lo que le hicieron los mogu.', '', 28153),
(152132, 'esES', '¡No ha llegado la hora de Picofino! ¡Cra!', '', 28153),
(152131, 'esES', 'Por eso no me gustan los compañeros.', '', 28153),
(152130, 'esES', 'Cuando dijiste que te llamabas Aterravil pensé que era porque aterrabas a lo vil, no al revés.', '', 28153),
(152129, 'esES', '¡Es hora de abatirlos!', '', 28153),
(152128, 'esES', 'Dijiste: \"Vamos a la jungla, verás qué vistas\". Debería haber sabido que tu punto ciego nos metería en problemas.', '', 28153),
(152127, 'esES', 'Si morimos, será culpa tuya.', '', 28153),
(152126, 'esES', 'Oí que podrías estar merodeando por aquí.$b$bGracias a una... indiscreción por parte de Marius, no mía, hemos tenido que venir a buscar a ese terrible demonio a este infierno húmedo lleno de cosas a las que les gusta mordisquearte los huesos.$b$bAyúdanos y puedes quedarte lo que haya de valor en su cadáver.$b$bNosotros solo queremos el trozo de papel que lleva encima. Nada que merezca la pena leer.', '', 28153),
(152125, 'esES', '¡Cra! ¡Todo tuyo!', '', 28153),
(152124, 'esES', '¿Picofino va a por pescado?', '', 28153),
(152123, 'esES', '¡Deja de pegarle!', '', 28153),
(152122, 'esES', '¡Vosotros nunca aprendéis!', '', 28153),
(152121, 'esES', 'Tal vez, si no se lo hubieras repetido tantas veces... ¡Cra!', '', 28153),
(152120, 'esES', 'Ese botín... siempre será mío...', 'Ese botín... siempre será mío...', 28153),
(152119, 'esES', '', 'Ay, vale, ahí me has dado.', 28153),
(152118, 'esES', '', '¡Picofino, ven aquí y deja de holgazanear!', 28153),
(152117, 'esES', '', '¡Largo, pájaro, no necesito tu ayuda!', 28153),
(152116, 'esES', '', 'Eso ni siquiera me ha dolido. ¿Es todo lo que sabes hacer, carnaza para tiburones?', 28153),
(152115, 'esES', '¡JA! ¡He estado buscando una oportunidad de desquitarme un poco!', '¡JA! ¡He estado buscando una oportunidad de desquitarme un poco!', 28153),
(152114, 'esES', '', 'Yo estaba muy a gusto... hasta que se negaron a hacer lo que yo decía...', 28153),
(152113, 'esES', '', '¿A qué te refieres con \"vosotros\"?', 28153),
(152112, 'esES', '', '¿Abandonan el barco? ¡Créeme, reconstruiré el Gran Cuerno y usaré el bauprés para ensartar a cada uno de esos perros traicioneros!', 28153),
(152111, 'esES', '', '¡Maldita escoria inútil!', 28153),
(152110, 'esES', 'Ella... reinará... eternamente...', 'Ella... reinará... eternamente...', 28153),
(152109, 'esES', 'Derrotado... por alguien como tú...', 'Derrotado... por alguien como tú...', 28153),
(152108, 'esES', 'La Horda... siempre será... suya...', 'La Horda... siempre será... suya...', 28153),
(152107, 'esES', 'Otra vez... no...', 'Otra vez... no...', 28153),
(152106, 'esES', '¡No hay más destino que la muerte!', '¡No hay más destino que la muerte!', 28153),
(152105, 'esES', '¿Oyes los gritos?', '¿Oyes los gritos?', 28153),
(152104, 'esES', '¡Nadie sobrevivirá!', '¡Nadie sobrevivirá!', 28153),
(152103, 'esES', '¡Por la Dama Oscura!', '¡Por la Dama Oscura!', 28153),
(152102, 'esES', '¡Lok\'tar ogar!', '¡Lok\'tar ogar!', 28153),
(152101, 'esES', '¡Lok-narash!', '¡Lok-narash!', 28153),
(152100, 'esES', '¡Gakarah ma!', '¡Gakarah ma!', 28153),
(152099, 'esES', '¡Victoria o muerte!', '¡Victoria o muerte!', 28153),
(152098, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(152097, 'esES', '¡Muerte a nuestros enemigos!', '¡Muerte a nuestros enemigos!', 28153),
(152096, 'esES', '¡Hoy morirás!', '¡Hoy morirás!', 28153),
(152095, 'esES', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(152094, 'esES', 'Me reúno... con mis ancestros...', 'Me reúno... con mis ancestros...', 28153),
(152093, 'esES', 'Perderéis... esta guerra...', 'Perderéis... esta guerra...', 28153),
(152092, 'esES', 'Vuestro fin... llegará...', 'Vuestro fin... llegará...', 28153),
(152091, 'esES', 'Muero... como guerrero...', 'Muero... como guerrera...', 28153),
(152090, 'esES', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(152089, 'esES', 'Mi vida... por Draenor...', 'Mi vida... por Draenor...', 28153),
(152088, 'esES', 'Ponte en marcha.', 'Ponte en marcha.', 28153),
(152087, 'esES', 'Vete. ¡Ya!', 'Vete. ¡Ya!', 28153),
(152086, 'esES', 'No le falles a la Horda.', 'No le falles a la Horda.', 28153),
(152085, 'esES', 'Que tengas una buena muerte.', 'Que tengas una buena muerte.', 28153),
(152084, 'esES', 'No tengo nada más que decir.', 'No tengo nada más que decir.', 28153),
(152083, 'esES', 'Vete.', 'Vete.', 28153),
(152082, 'esES', 'Ve con honor.', 'Ve con honor.', 28153),
(152081, 'esES', 'Mantén tu espada afilada.', 'Mantén tu espada afilada.', 28153),
(152080, 'esES', 'Ve y hazte con la victoria.', 'Ve y hazte con la victoria.', 28153),
(152079, 'esES', 'No pierdas de vista tu deber.', 'No pierdas de vista tu deber.', 28153),
(152078, 'esES', '¿A qué has venido?', '¿A qué has venido?', 28153),
(152077, 'esES', 'No tengo tiempo para tonterías.', 'No tengo tiempo para tonterías.', 28153),
(152076, 'esES', '¿Y bien? Estoy esperando...', '¿Y bien? Estoy esperando...', 28153),
(152075, 'esES', 'Habla.', 'Habla.', 28153),
(152074, 'esES', 'Hola.', 'Hola.', 28153),
(152073, 'esES', '¡Lok\'tar!', '¡Lok\'tar!', 28153),
(152072, 'esES', '¡Throm-ka!', '¡Throm-ka!', 28153),
(152071, 'esES', '¿Qué necesitas?', '¿Qué necesitas?', 28153),
(152070, 'esES', 'Zug-zug.', 'Zug-zug.', 28153),
(152069, 'esES', 'Fuerza y honor.', 'Fuerza y honor.', 28153),
(152068, 'esES', '¿En Azeroth es todo el mundo igual de pesado?', '¿En Azeroth es todo el mundo igual de pesado?', 28153),
(152067, 'esES', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 28153),
(152066, 'esES', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadado.', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadada.', 28153),
(152065, 'esES', 'ORCO... ¡APLASTAR!', 'ORCO... ¡APLASTAR!', 28153),
(152064, 'esES', 'Seguro que siguen retenidos al otro lado del muro con los esbirros del aquelarre.', '', 28153),
(152063, 'esES', '', '¿Dónde están los otros inquisidores?', 28153),
(152062, 'esES', '¡Lok\'tar ogar!', '¡Lok\'tar ogar!', 28153),
(152061, 'esES', '¡Cae ante mi furia!', '¡Cae ante mi furia!', 28153),
(152060, 'esES', '¡Acepta tu destino!', '¡Acepta tu destino!', 28153),
(152059, 'esES', '¡Cae ante mi furia!', '¡Cae ante mi furia!', 28153),
(152058, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(152057, 'esES', '¡Muerte a nuestros enemigos!', '¡Muerte a nuestros enemigos!', 28153),
(152056, 'esES', '¡Hoy morirás!', '¡Hoy morirás!', 28153),
(152055, 'esES', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(152054, 'esES', 'Me reúno... con mis ancestros...', 'Me reúno... con mis ancestros...', 28153),
(152053, 'esES', 'Perderéis... esta guerra...', 'Perderéis... esta guerra...', 28153),
(152052, 'esES', 'Vuestro fin... llegará...', 'Vuestro fin... llegará...', 28153),
(152051, 'esES', 'Que los espíritus... me acojan...', 'Que los espíritus... me acojan...', 28153),
(152050, 'esES', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(152049, 'esES', 'Mi espíritu regresa... a Draenor...', 'Mi espíritu regresa... a Draenor...', 28153),
(152048, 'esES', 'Regresa con más dinero.', 'Regresa con más dinero.', 28153),
(152047, 'esES', 'Espero que esta mercancía te sea útil.', 'Espero que esta mercancía te sea útil.', 28153),
(152046, 'esES', 'Vuelve pronto.', 'Vuelve pronto.', 28153),
(152045, 'esES', 'Que tengas una buena muerte.', 'Que tengas una buena muerte.', 28153),
(152044, 'esES', 'Tengo poco más que decir.', 'Tengo poco más que decir.', 28153),
(152043, 'esES', 'Ya está todo dicho.', 'Ya está todo dicho.', 28153),
(152042, 'esES', 'Ve con honor.', 'Ve con honor.', 28153),
(152041, 'esES', 'Que los espíritus te guíen.', 'Que los espíritus te guíen.', 28153),
(152040, 'esES', 'Ve y hazte con la victoria.', 'Ve y hazte con la victoria.', 28153),
(152039, 'esES', 'Que así sea.', 'Que así sea.', 28153),
(152038, 'esES', '¿Qué estás buscando?', '¿Qué estás buscando?', 28153),
(152037, 'esES', '¿Qué necesitas?', '¿Qué necesitas?', 28153),
(152036, 'esES', 'Echa un vistazo.', 'Echa un vistazo.', 28153),
(152035, 'esES', 'Habla.', 'Habla.', 28153),
(152034, 'esES', 'Hola.', 'Hola.', 28153),
(152033, 'esES', '¡Lok\'tar!', '¡Lok\'tar!', 28153),
(152032, 'esES', '¡Throm-ka!', '¡Throm-ka!', 28153),
(152031, 'esES', '¿Qué necesitas?', '¿Qué necesitas?', 28153),
(152030, 'esES', 'Zug-zug.', 'Zug-zug.', 28153),
(152029, 'esES', 'Fuerza y honor.', 'Fuerza y honor.', 28153),
(152028, 'esES', '¿En Azeroth es todo el mundo igual de pesado?', '¿En Azeroth es todo el mundo igual de pesado?', 28153),
(152027, 'esES', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 28153),
(152026, 'esES', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadado.', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadada.', 28153),
(152025, 'esES', 'ORCO... ¡APLASTAR!', 'ORCO... ¡APLASTAR!', 28153),
(152024, 'esES', 'Cocinar un pez recién pehcado. Pocah cosah mejoreh hay.', '', 28153),
(152023, 'esES', '', 'Hemoh ehtado viajando pa alejarnoh de todo eso. Tiene gracia que nunca lleguemoh lejoh. Eh una vihta incomparable.', 28153),
(152017, 'esES', '¡¿Cómo ha roto las cadenas?!', '¡¿Cómo ha roto las cadenas?!', 28153),
(152016, 'esES', '¡No vamos a quedarnos para averiguarlo!', '¡No vamos a quedarnos para averiguarlo!', 28153),
(152015, 'esES', '¡Contagio de sangre!', '', 28153),
(152014, 'esES', 'Examinando flor', 'Examinando flor', 28153),
(152013, 'esES', '¡El avatar de Sethraliss ya no está embrujado! ¡Devuélvele toda la salud para desactivar las defensas!', '¡El avatar de Sethraliss ya no está embrujado! ¡Devuélvele toda la salud para desactivar las defensas!', 28153),
(152012, 'esES', '¡Evolución!', '', 28153),
(152011, 'esES', '¡Infección!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'esES', '¡La pestilencia se extiende!', '', 28153),
(152009, 'esES', '¡Gestación violenta!', '', 28153),
(152008, 'esES', 'Consumir...', '', 28153),
(152007, 'esES', '¡Se acabó! Ya me he hartado de la Horda.', '', 28153),
(152006, 'esES', 'Cepa letal. El contagio ha tenido éxito.', '', 28153),
(152005, 'esES', 'He perdido mi disfraz. ¿Tienes otro pergamino?', 'He perdido mi disfraz. ¿Tienes otro pergamino?', 28153),
(152004, 'esES', '¡La zampona selvática salta al agua!', '', 28153),
(152003, 'esES', '¡Supura!', '', 28153),
(152002, 'esES', 'La infección te lleva...', '', 28153),
(152001, 'esES', 'El contagio es inevitable...', '', 28153),
(152000, 'esES', '', 'Bien. BAH. No tiene nada de amable.', 28153),
(151999, 'esES', '', '¿Has encontrado al ruin cerebro, Don Amable?', 28153),
(151998, 'esES', 'Nuevos anfitriones...', '', 28153),
(151990, 'esES', 'Bien... Hora de hacerse con un trofeo.', '', 28153),
(151989, 'esES', '¡La perla es nuestra! Con ella, nuestras naves serán depredadoras del mar.', '', 28153),
(151987, 'esES', '', 'Disssfrutad de esssta victoria; ssserá la última.', 28153),
(151986, 'esES', 'Es la ley natural. Los fuertes se alimentan de los débiles.', '', 28153),
(151985, 'esES', 'Estad alerta. Nos acecha alguna fuerza oculta.', '', 28153),
(151983, 'esES', 'La Alianza no debe hacerse con este trofeo. ¡Todos nuestros enemigos caerán!', '', 28153),
(151982, 'esES', '', 'Recuperaste mi negocio, así que sí. Tener a Cesi como jefa haría que empezáramos de nuevo a ganar dinero de verdad por aquí.', 28153),
(151981, 'esES', '¿Apoyarás a Cesi Gatillofácil?', '¿Apoyarás a Cesi Gatillofácil?', 28153),
(151980, 'esES', '', 'Este lugar antes daba muchos más beneficios.', 28153),
(151979, 'esES', '', 'Salgamos de aquí antes de que nos acorralen. ¡Vamos!', 28153),
(151978, 'esES', 'La casa Canto Tormenta gobernará este reino anegado gracias a la furia de la madre de las mareas.', '', 28153),
(151977, 'esES', 'La flota... será suya...', '', 28153),
(151976, 'esES', 'Tan solo estaba jugando con ellos, mi señor. ¡Se hará como dices!', '', 28153),
(151975, 'esES', 'Nuestro destino está cerca. No deben entrar al Altar de la Tormenta.', '', 28153),
(151974, 'esES', '', 'Mira en qué te has convertido. ¡Cuánta sangre derramada por tu culpa!', 28153),
(151973, 'esES', 'El pergamino flota y zumba, con visiones de otros lugares apenas ocultas por la magia.', '', 28153),
(151972, 'esES', 'Supervivencia del alma del mundo improbable...', '', 28153),
(151971, 'esES', 'Infección del planeta inminente.', '', 28153),
(151970, 'esES', 'Deberíamos dejar que la Marea de Hierro se quede el tesoro.', 'Deberíamos dejar que la Marea de Hierro se quede el tesoro.', 28153),
(151969, 'esES', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', 28153),
(151968, 'esES', '<Apuñalarlo y punto>', '<Apuñalarlo y punto>', 28153),
(151967, 'esES', '¿Va en serio?', '¿Va en serio?', 28153),
(151966, 'esES', '¡Eso es abusivo! ¡No pienso pagarlo!', '¡Eso es abusivo! ¡No pienso pagarlo!', 28153),
(151965, 'esES', 'El trozo de suelo para pasar la noche está a cincuenta de oro. Sesenta si quieres estar junto al fuego. Trae tus propias mantas.\n\nLas camas están a cien de oro.\n\nVincular tu piedra de hogar son setenta y cinco de oro por semana.\n\n¿No te gusta?\n\n<Se ríe y se cruza de brazos con una sonrisa>.\n\nUna pena. Son los precios que hay.', '', 28153),
(151964, 'esES', 'Las profundidades anunciaron vuestra llegada... ¡y vuestro fin!', '', 28153),
(151963, 'esES', 'Gran brecha detectada.', '', 28153),
(151962, 'esES', '', 'Debemoh reunirnoh y detener la podredumbre de raíz.', 28153),
(151961, 'esES', '', 'El titán noh ha hecho ganar tiempo, pero G\'huun no tardará en liberarse.', 28153),
(151960, 'esES', 'Espécimen virulento detectado. Prioridad de contención uno.', '', 28153),
(151959, 'esES', '¡Devorar! ¡Consumir! ¡Propagar!', '', 28153),
(151958, 'esES', '', '¿Ehta cosa buhca a su madre? Ojalá noh lleve hahta algo que pueda detener la ehpansión del añublo.', 28153),
(151957, 'esES', 'Fallo de contención de G\'huun. MADRE no responde.', '', 28153),
(151954, 'esES', '', 'Si ehto alcanza la superficie, no podremoh contenerlo.', 28153),
(151953, 'esES', '', 'Nunca había vihto ehta forma de corrupción.', 28153),
(151952, 'esES', '', '¡No podemoh permitir que llegue a la superficie! ¡Dehtruidla!', 28153),
(151951, 'esES', '', '¡Ah! ¡¿Qué clase de criatura eh ehta?!', 28153),
(151950, 'esES', '', 'Protegeoh, quién sabe qué acecha en ehtah cuevah.', 28153),
(151949, 'esES', '', 'Loh trolh de sangre ehtán dihpersoh, pero hay que buhcar el origen de la podredumbre y dehtruirlo.', 28153),
(151948, 'esES', 'Te traemoh una ofrenda, gran loa de la muerte.', '', 28153),
(151947, 'esES', 'Si eso significa que tendremos caras nuevas por aquí, sí, lo haré.', '', 28153),
(151946, 'esES', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t ¡%s comienza a lanzar |cFFFF0404|Hspell:260773|h[Ritual temible]|h|r!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t ¡%s comienza a lanzar |cFFFF0404|Hspell:260773|h[Ritual temible]|h|r!', 28153),
(151945, 'esES', '¿Apoyarás a Cesi Gatillofácil?', '¿Apoyarás a Cesi Gatillofácil?', 28153),
(151944, 'esES', '¿Compras o vendes?', '', 28153),
(151943, 'esES', '', 'Esto no tiene buena pinta...', 28153),
(151942, 'esES', 'Será un placer. Sufrirán en tu nombre.', '', 28153),
(151941, 'esES', 'Contagio detectado. Iniciando desinfección.', '', 28153),
(151940, 'esES', '¡Explosión pestilente!', '', 28153),
(151939, 'esES', 'Activando salvaguardia definitiva. Destruyendo fuente de infección.', '', 28153),
(151938, 'esES', 'Enseguida, mi señor. Tan solo tengo que ocuparme de ciertas alimañas.', 'Enseguida, mi señor. Tan solo tengo que ocuparme de ciertas alimañas.', 28153),
(151937, 'esES', 'Purificando área.', '', 28153),
(151936, 'esES', 'Protocolos de purga iniciados.', '', 28153),
(151935, 'esES', '¡Ruptura inmunda!', '', 28153),
(151934, 'esES', 'Solo tengo algunoh huesoh rotoh... Minuciah.', '', 28153),
(151933, 'esES', 'Guíanoh al campamento vulpera. Nosotroh llevaremoh el tesoro.', '', 28153),
(151932, 'esES', '¡Expulsión sangrienta!', '', 28153),
(151931, 'esES', '', '¡Deponed las armas! ¡No tenéis que hacer esto!', 28153),
(151930, 'esES', 'Debo... propagar...', '', 28153),
(151929, 'esES', '¡La plaga te ha alcanzado!', '', 28153),
(151928, 'esES', '¡Te he infectado!', '', 28153),
(151927, 'esES', 'Carne corrupta.', '', 28153),
(151926, 'esES', '¡Consumir!', '', 28153),
(151925, 'esES', '¡Debo propagar!', '', 28153),
(151924, 'esES', 'Pero no te olvideh de cumplir con tu parte...', '', 28153),
(151923, 'esES', '¡Ja, ja, ja, ja! ¿Veh, Majehtad? ¡Bwonsamdi siempre cumple loh tratoh!', '', 28153),
(151922, 'esES', '¡Alzaoh, alzaoh! ¡No oh hagáih de rogar! ¡Empuñad lah lanzah y luchad!', '', 28153),
(151921, 'esES', 'Tranquilo, Majehtad, Bwonsamdi siempre ayuda a suh amigoh...', '', 28153),
(151920, 'esES', '', 'No tieneh por qué mirarme dehde ahí mientrah trabajo. Tenemoh mucho que hacer.', 28153),
(151919, 'esES', 'El barco ehtá preparado pa partir a nuehtra orden.', '', 28153),
(151918, 'esES', 'Ehtoh traidoreh se interponen entre mi reino y yo, pero ¿dónde ehtá la ayuda que prometihte? ¿Cumpliráh tu palabra?', '', 28153),
(151916, 'esES', 'Bien hecho, adalid. Siento cómo Azeroth recupera su fuerza. Muchas gracias.', '', 28153),
(151915, 'esES', 'Varias heridas emanan azerita por aquí y están expuestas a un ataque. ¡Usa el Corazón de Azeroth para sanarlas!', '', 28153),
(151913, 'esES', '¡Huye mientras puedas!', '', 28153),
(151912, 'esES', '¡Tch, tch! Ese no eh un tono muy rehpetuoso pa dirigirse a un loa, Majehtad. ¡Pero supongo que lah almah que conseguiré hoy compensarán tu insolencia!', '', 28153),
(151911, 'esES', 'Ehtamoh en ehto juntoh, $p.\n\nMotín o el penol.', '', 28153),
(151910, 'esES', 'Bwonsamdi, ¡muéhtrate!', '', 28153),
(151909, 'esES', 'Zul ya tiene demasiadoh aliadoh. Solo podemoh hacer una cosa...', '', 28153),
(151908, 'esES', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t¡%s mira a |cFFFF0000$n|r y se prepara para |cFFFF0000|Hspell:266951|h[Atravesar]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t¡%s mira a |cFFFF0000$n|r y se prepara para |cFFFF0000|Hspell:266951|h[Atravesar]|h|r!', 28153),
(151907, 'esES', 'Un grupo de Zandalari ha desactivado los antiguos resguardos que defendían el corazón de Sethraliss...', 'Un grupo de Zandalari ha desactivado los antiguos resguardos que defendían el corazón de Sethraliss...', 28153),
(151906, 'esES', 'Sí, Cesi puede contar con mi apoyo.', '', 28153),
(151905, 'esES', '¡Poneos manos a la obra, goblins holgazanes! ¡Quiero esa Base de Bolsillo preparada ya!', '¡Poneos manos a la obra, goblins holgazanes! ¡Quiero esa Base de Bolsillo preparada ya!', 28153),
(151904, 'esES', '¿Apoyarás a Cesi Gatillofácil?', '¿Apoyarás a Cesi Gatillofácil?', 28153),
(151902, 'esES', 'Mmmmmmm. Sí. Déjame ver.\n\n<Kooda busca durante largo rato antes de sacar un tarro de las profundidades de la mochila>.\n\nCompré esto hace un par de siglos, lo había olvidado. Supongo que podría venderla.', '', 28153),
(151901, 'esES', '¿Has oído hablar de algo llamado \"salsa centenaria\"? ¿Tú tienes?', '¿Has oído hablar de algo llamado \"salsa centenaria\"? ¿Tú tienes?', 28153),
(151900, 'esES', 'Hola, $r. ¿Tienes algo interesante que vender?', '', 28153),
(151899, 'esES', '¡Por las mareas, aquí viene!', '¡Por las mareas, aquí viene!', 28153),
(151898, 'esES', 'Un hambre insaciable. El Rey se alimenta.', '', 28153),
(151897, 'esES', 'La herida se infecta. El mundo se pudre.', '', 28153),
(151896, 'esES', 'Siempre hemos estado en vuestras mentes.', '', 28153),
(151895, 'esES', 'Los gritos de agonía anunciarán su llegada.', '', 28153),
(151894, 'esES', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t¡Zanazal el Sabio empieza a lanzar |cFFFF0000|Hspell:267273|h[Nova de veneno]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t¡Zanazal el Sabio empieza a lanzar |cFFFF0000|Hspell:267273|h[Nova de veneno]|h|r!', 28153),
(151893, 'esES', '', '¡Los reptadores han despertado!', 28153),
(151892, 'esES', '', '¡Kril lax qutholil!', 28153),
(151890, 'esES', 'Te has enfrentado a los nagas como mi avatar y has puesto fin al ataque contra mi templo.', '', 28153),
(151889, 'esES', '', '¡Oh! ¡Llevo mucho tiempo queriendo usar salsa centenaria! Es una pasta culinaria hecha de varios ingredientes que se mezclan y luego se dejan fermentar durante siglos. Cuanto más tiempo pasa fermentando, más complejo es el perfil de su sabor. Se dice que añade una fuerza y un olor característicos a cualquier plato.\n\nHay rumores de que algunos comerciantes tortolianos la llevan, pero es difícil de encontrar y muy cara.\n\n<Xun Xun suspira con tristeza>\n\n¡Es el ingrediente soñado de cualquier cocinero!', 28153),
(151888, 'esES', 'Tienes una buena despensa. ¿Te falta alguna especia?', 'Tienes una buena despensa. ¿Te falta alguna especia?', 28153),
(151887, 'esES', '', '¡Una cara nueva! Y creo que amistosa. ¿Te gustaría probar algo especial? ¿O quizás buscas especias o recetas raras?', 28153),
(151886, 'esES', 'El Corazón de Azeroth se está recuperando gracias a ti. Cada vez queda menos para curar las heridas de este mundo.', '', 28153),
(151885, 'esES', 'Siento que hay azerita cerca... Y también la presencia de aquellos que quieren abusar de su poder. ¡Hay que detenerlos!', '', 28153),
(151884, 'esES', 'Ven, pequeño retoño. Calma tu corazón y ayúdame a sanar a este hombre.', '', 28153),
(151883, 'esES', '', 'La sangre mana en las profundidades.', 28153),
(151882, 'esES', '', 'Os aguarda la verdad bajo las mareas.', 28153),
(151881, 'esES', '', 'Escuchad la música de los ahogados.', 28153),
(151880, 'esES', '', 'La oscuridad se arraiga. La pestilencia se propaga. La puerta está abierta.', 28153),
(151879, 'esES', '', '¡El abismo devorará vuestros gritos!', 28153),
(151878, 'esES', '', '¡Vivo en vuestros pulmones!', 28153),
(151877, 'esES', '', 'Os espero... en la oscuridad...', 28153),
(151876, 'esES', '', '¡Te tengo!', 28153),
(151875, 'esES', '', 'Tus aliados disfrutaron viéndote morir.', 28153),
(151874, 'esES', '', 'Estamos unidos para siempre en la inmensidad de las profundidades.', 28153),
(151873, 'esES', 'No hay uno solo que tenga un rasgo digno.', '', 28153),
(151872, 'esES', '¡Tan frágil! ¡Tan despreciable!', '', 28153),
(151871, 'esES', '¡Eras el eslabón más débil!', '', 28153),
(151870, 'esES', '¿Cómo es... posible...?', '', 28153),
(151869, 'esES', 'Ul basha krix.', '', 28153),
(151868, 'esES', '', '¡Iluminad el cielo con fuego! Derribadlos.', 28153),
(151867, 'esES', 'Las criaturas inferiores deben servir... ¡O morir!', '', 28153),
(151866, 'esES', '', '¡Por la Horda!', 28153),
(151865, 'esES', '', '¡No tengáis piedad!', 28153),
(151864, 'esES', '¡Ug\' crish zul Thraxas!', '', 28153),
(151863, 'esES', '', '¡Mantened el fuego! Nuestras fuerzas terrestres dependen de vosotros.', 28153),
(151862, 'esES', '', '¡Seguid disparando!', 28153),
(151861, 'esES', '¡Ehte lugar será vuehtra tumba!', '', 28153),
(151860, 'esES', '¡No soih rivaleh pa loh Zandalari!', '', 28153),
(151859, 'esES', '¡Ehte templo pertenece a G\'huun!', '', 28153),
(151858, 'esES', '¡Loh Zandalari reinarán!', '', 28153),
(151857, 'esES', '', '¡Por aquí! ¡Nos espera una batalla gloriosa!', 28153),
(151856, 'esES', '¡Nada puede detener a G\'huun!', '', 28153),
(151855, 'esES', '¡El Dioh de la Sangre exige sacrificioh!', '', 28153),
(151854, 'esES', 'Voy a investigar un poco por mi cuenta. Si descubro algo, os informaré de inmediato.', '', 28153),
(151853, 'esES', '¡Ya habéis oído! Hay que descubrir el origen de la corrupción de los dioses antiguos..., ¡y destruirla a martillazos!', '', 28153),
(151852, 'esES', '¡Ja! ¿Eso es todo, Zul? ¡No me extraña que el imperio trol cayera!', '', 28153),
(151850, 'esES', 'Podría haber metido tu cadáver infecto en uno de esos sarcófagos.', '', 28153),
(151849, 'esES', '¡Gloria y honor, lucho por el Despertar de la Tormenta!', '¡Gloria y honor, lucho por el Despertar de la Tormenta!', 28153),
(151848, 'esES', 'Tienes mi hoja.', 'Tienes mi hoja.', 28153),
(151847, 'esES', '¡Aún no estoy muerto!', '¡Aún no estoy muerta!', 28153),
(151846, 'esES', '¡Detendremos a esos demonios juntos!', '¡Detendremos a esos demonios juntos!', 28153),
(151845, 'esES', '¡Mientras pueda mantenerme en pie, este valle permanecerá libre!', '¡Mientras pueda mantenerme en pie, este valle permanecerá libre!', 28153),
(151844, 'esES', 'Si el Despertar de la Tormenta me llama, debo responder.', 'Si el Despertar de la Tormenta me llama, debo responder.', 28153),
(151843, 'esES', 'Vivid o morid, ha llegado nuestra hora.', 'Vivid o morid, ha llegado nuestra hora.', 28153),
(151842, 'esES', '¡Estoy contigo!', '¡Estoy contigo!', 28153),
(151841, 'esES', 'Es una pena que no estés aquí para ver caer a tu precioso ensamblaje, Zul.', '', 28153),
(151840, 'esES', '¡Grr! ¡Eso habrá que verlo, cobarde!', '', 28153),
(151839, 'esES', '¡Pronto se alzarán y todo aquel que se oponga a G\'huun caerá!', '', 28153),
(151838, 'esES', '¡Puede que tengamos una posibilidad después de todo! ¡Por el Despertar de la Tormenta!', '¡Puede que tengamos una posibilidad después de todo! ¡Por el Despertar de la Tormenta!', 28153),
(151837, 'esES', '¡Insensatoh! Mi poder ya ha vinculado loh ehpírituh antiguoh a la voluntad de mi maehtro.', '', 28153),
(151836, 'esES', 'Oigo el canto de la tormenta. ¡Aún hay esperanza!', 'Oigo el canto de la tormenta. ¡Aún hay esperanza!', 28153),
(151835, 'esES', 'Hay otros. ¡No todos estamos perdidos!', 'Hay otros. ¡No todos estamos perdidos!', 28153),
(151834, 'esES', 'No sé qué magia oscura yace en este lugar, pero tenemos que sofocarla.', '', 28153),
(151833, 'esES', 'Nosotros no somos así. ¡Aún podemos detener a lord Canto Tormenta!', 'Nosotros no somos así. ¡Aún podemos detener a lord Canto Tormenta!', 28153),
(151832, 'esES', 'Según mis investigaciones, aquí reposa el primer Rey de Zandalar.', '', 28153),
(151831, 'esES', 'La puerta ha caído. ¡Moveos! ¡Recuperad Arathi por la Alianza!', '', 28153),
(151830, 'esES', '¿Pike sigue con vida? Lo buscaré de inmediato.', '¿Pike sigue con vida? Lo buscaré de inmediato.', 28153),
(151829, 'esES', 'La puerta ha caído. Adelante, ¡expulsad a la Horda de Arathi!', '', 28153),
(151828, 'esES', '¡Ya está, la puerta ha caído! ¡Vamos!', '', 28153),
(151827, 'esES', '', '¡Las puertas han caído! ¡Seguid atacando!', 28153),
(151826, 'esES', '¡La puerta ha caído! ¡Asaltad la fortaleza!', '', 28153),
(151825, 'esES', 'Hay que detenerlo... Por Zandalar... Y por vuehtroh propioh reinoh.', '', 28153),
(151824, 'esES', 'Las puertas han caído, ¡tomad la fortaleza!', '', 28153),
(151823, 'esES', '¡Debemos abrir el Altar de la Tormenta de inmediato!', '¡Debemos abrir el Altar de la Tormenta de inmediato!', 28153),
(151822, 'esES', 'Su amo se hace máh fuerte por momentoh. Zul no dehcansará hahta que el Dioh de la Sangre se apodere del mundo.', '', 28153),
(151821, 'esES', 'Ya está. Arathi vuelve a ser nuestro. ¡Por la Alianza!', '', 28153),
(151820, 'esES', 'La tormenta despierta en mi interior. ¡Me enfrentaré a la sombra!', 'La tormenta despierta en mi interior. ¡Me enfrentaré a la sombra!', 28153),
(151819, 'esES', '', 'Nuestra victoria estaba clara. ¡Por la Horda!', 28153),
(151818, 'esES', 'Me habéih liberado de un dehtino cruel, pero Zul eh solo una marioneta en un plan mayor.', '', 28153),
(151817, 'esES', 'Arráhtrate hahta tu maehtro, a ver qué tal recompensa el fracaso.', '', 28153),
(151816, 'esES', 'Sabía que este día llegaría. Debo unirme a los demás.', 'Sabía que este día llegaría. Debo unirme a los demás.', 28153),
(151815, 'esES', '¡Imposible! ¡Nadie rechaza a G\'huun!', '', 28153),
(151814, 'esES', '¡Me habéih liberado del control de Zul! ¡Ya no sirvo a ese cerdo!', '', 28153),
(151813, 'esES', 'Quéjate si quiereh, mi Rey... pero deberíah haber comprendido que no podíah huir de G\'huun.', '', 28153),
(151812, 'esES', 'Loh intrusoh morirán... pero no quiero oír tu verborrea mientrah loh mato.', '', 28153),
(151811, 'esES', 'Dediqué mi vida a resihtirme a tu maehtro y, al morir, me vinculahte a su voluntad.', '', 28153),
(151810, 'esES', 'Silencio, ¡profeta de lah mentirah!', '', 28153),
(151809, 'esES', 'Ehte eh el lugar de dehcanso del primer rey de Zandalar. Dazar era terco... ¡pero ahora obedece!', '', 28153),
(151808, 'esES', '¿Has perdido el juicio?', '¿Has perdido el juicio?', 28153),
(151807, 'esES', 'Habla.', 'Habla.', 28153),
(151806, 'esES', 'Pero en la muerte, graciah a mí, su propósito eh único: mataroh.', '', 28153),
(151805, 'esES', 'La tierra me acoge.', 'La tierra me acoge.', 28153),
(151804, 'esES', 'Se odiaron en vida y acabaron por dehtruirse loh unoh a loh otroh.', '', 28153),
(151803, 'esES', 'Oh acercáih a loh treh lídereh que controlaron el imperio cuando nadie era capaz de reclamar el trono.', '', 28153),
(151802, 'esES', 'Aquí no se permite la entrada de forasteros.', 'Aquí no se permite la entrada de forasteros.', 28153),
(151801, 'esES', '¡Al retroceder el mar se alzará la tierra!', '¡Al retroceder el mar se alzará la tierra!', 28153),
(151800, 'esES', 'Seguro que no tendrán problema en deshacerse de vosotroh también.', '', 28153),
(151799, 'esES', 'Loh muertoh se amontonaban en loh temploh, así que crearon gólemh pa deshacerse de loh infectadoh.', '', 28153),
(151798, 'esES', 'Hace mil añoh una plaga contagiosa casi acaba con loh Zandalari.', '', 28153),
(151797, 'esES', '¡Pronto se alzarán y todo aquel que se oponga a G\'huun caerá!', '', 28153),
(151796, 'esES', 'Mi poder crece. He vinculado loh ehpírituh antiguoh a la voluntad de mi maehtro.', '', 28153),
(151795, 'esES', 'Bienvenidoh a la tumba del primer Rey de loh trolh. Me encantaría poder daroh la bienvenida en persona.', '', 28153),
(151794, 'esES', '¡Te dije que no me uniría a ti en esta locura!', '¡Te dije que no me uniría a ti en esta locura!', 28153),
(151793, 'esES', 'No voy a dejarme engañar otra vez.', 'No voy a dejarme engañar otra vez.', 28153),
(151792, 'esES', '¿Es... seguro?', '¿Es... seguro?', 28153),
(151791, 'esES', 'Somos emprendedores y especialistas en traslados. No como esos malditos mercenarios de abrigos rojos. No somos piratas.', '', 28153),
(151790, 'esES', '', 'Volvamos con Katherine, adalid.', 28153),
(151789, 'esES', '', '¡Organizad una partida de búsqueda y encontradla!', 28153),
(151788, 'esES', '', 'Espera, ¡no!', 28153),
(151787, 'esES', '', 'Insolente. ¡Esto no ha acabado!', 28153),
(151786, 'esES', '', 'Se acabó. No hay escapatoria.', 28153),
(151785, 'esES', '', '¡Fuera de mi camino, inútiles!', 28153),
(151784, 'esES', '', '¡Toma esto!', 28153),
(151783, 'esES', '', '¡Tu estratagema no ha servido de nada! ¡Esta ciudad es MÍA!', 28153),
(151782, 'esES', '¡Esperaré aquí por si alguien consigue volver a casa!', '', 28153),
(151781, 'esES', '', 'Las cosas mejorarán cuando yo sea la jefa.\n\nCuando nos libremos de esos piratas Marea de Hierro, todo el mundo podrá venir a comprar y vender. ¡Será genial!', 28153),
(151780, 'esES', '', '¡Uf! La cosa estaba mejor antes de que aparecieran esos desgraciados de los abrigos rojos.', 28153),
(151779, 'esES', 'Mira, yo solo intento ganarme la vida.', '', 28153),
(151778, 'esES', 'Velarrasgada y su gente son malos para el negocio. Si esto se pone mucho peor, puede que coja mis pájaros y me vaya.', '', 28153),
(151777, 'esES', 'Iba a ser rico...', '', 28153),
(151776, 'esES', '¿Intentas interponerte en nuestro camino? ¡He matado a otros por menos!', '', 28153),
(151775, 'esES', '', '¡No nos arrebataréis esta arboleda!', 28153),
(151774, 'esES', '', 'Gracias. Creí que podría enfrentarme a ellos sin ayuda. Ahora volveré con Morwin.', 28153),
(151773, 'esES', 'Yo gusta lo que has hecho con este sitio.', '', 28153),
(151772, 'esES', 'Los tortolianos llevamos mucho tiempo comerciando en este lugar. Los Zandalari han acabado por crecer a nuestro alrededor, pero les han llegado tiempos duros. Nosotros, por supuesto, sobreviviremos.', '', 28153),
(151771, 'esES', 'Trabajo aquí mismo. No necesario ir por camino peligroso.', '', 28153),
(151770, 'esES', '¡Lok\'tar ogar!', '¡Lok\'tar ogar!', 28153),
(151769, 'esES', '¡Lok-narash!', '¡Lok-narash!', 28153),
(151768, 'esES', '¡Gakarah ma!', '¡Gakarah ma!', 28153),
(151767, 'esES', '¡Cae ante mi furia!', '¡Cae ante mi furia!', 28153),
(151766, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(151765, 'esES', '¡Muerte a nuestros enemigos!', '¡Muerte a nuestros enemigos!', 28153),
(151764, 'esES', '¡Hoy morirás!', '¡Hoy morirás!', 28153),
(151763, 'esES', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(151762, 'esES', '¡Ja! Veo que te incorporas al servicio. ¡Échalo al cofre y vuelve al trabajo!', '', 28153),
(151761, 'esES', 'Me reúno... con mis ancestros...', 'Me reúno... con mis ancestros...', 28153),
(151760, 'esES', 'Perderéis... esta guerra...', 'Perderéis... esta guerra...', 28153),
(151759, 'esES', 'Vuestro fin... llegará...', 'Vuestro fin... llegará...', 28153),
(151758, 'esES', 'Muero... como guerrero...', 'Muero... como guerrera...', 28153),
(151757, 'esES', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(151756, 'esES', 'Mi espíritu regresa... a Draenor...', 'Mi espíritu regresa... a Draenor...', 28153),
(151755, 'esES', 'Que tengas una buena muerte.', 'Que tengas una buena muerte.', 28153),
(151754, 'esES', 'No tengo nada más que decir.', 'No tengo nada más que decir.', 28153),
(151753, 'esES', 'Márchate.', 'Márchate.', 28153),
(151752, 'esES', 'Ve con honor.', 'Ve con honor.', 28153),
(151751, 'esES', 'Mantén tu espada afilada.', 'Mantén tu espada afilada.', 28153),
(151750, 'esES', 'Ve y hazte con la victoria.', 'Ve y hazte con la victoria.', 28153),
(151749, 'esES', 'Que así sea.', 'Que así sea.', 28153),
(151748, 'esES', 'Habla.', 'Habla.', 28153),
(151747, 'esES', 'Hola.', 'Hola.', 28153),
(151746, 'esES', '¡Lok\'tar!', '¡Lok\'tar!', 28153),
(151745, 'esES', '¡Throm-ka!', '¡Throm-ka!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'esES', '¿Qué necesitas?', '¿Qué necesitas?', 28153),
(151743, 'esES', 'Zug-zug.', 'Zug-zug.', 28153),
(151742, 'esES', 'Fuerza y honor.', 'Fuerza y honor.', 28153),
(151741, 'esES', 'Compra más la próxima vez.', 'Compra más la próxima vez.', 28153),
(151740, 'esES', 'Espero que esta mercancía te sea útil.', 'Espero que esta mercancía te sea útil.', 28153),
(151739, 'esES', '¡No se admiten devoluciones!', '¡No se admiten devoluciones!', 28153),
(151738, 'esES', '¿Qué estás buscando?', '¿Qué estás buscando?', 28153),
(151737, 'esES', '¿Qué necesitas?', '¿Qué necesitas?', 28153),
(151736, 'esES', 'Echa un vistazo.', 'Echa un vistazo.', 28153),
(151735, 'esES', '¿En Azeroth es todo el mundo igual de pesado?', '¿En Azeroth es todo el mundo igual de pesado?', 28153),
(151734, 'esES', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 'Yo mato cosas que me molestan por diversión. ¿Seguro que no quieres parar?', 28153),
(151733, 'esES', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadado.', 'Mira, me estoy enfadando. Y no te iba a gustar verme enfadada.', 28153),
(151732, 'esES', 'ORCO... ¡APLASTAR!', 'ORCO... ¡APLASTAR!', 28153),
(151731, 'esES', 'Ven... Ven, mi querido Reban. ¡Eh hora de comer!', '', 28153),
(151730, 'esES', '<Applause sounds>', '', 28153),
(151729, 'esES', '<Yawning sound>', '', 28153),
(151728, 'esES', '<Short cheer--Wooooo!>', '', 28153),
(151727, 'esES', '<Slightly longer cheer--Woohoo!>', '', 28153),
(151726, 'esES', '<Chicken sounds>', '', 28153),
(151725, 'esES', '<Crying sounds>', '', 28153),
(151724, 'esES', '<Crying sounds, variant>', '', 28153),
(151723, 'esES', '<Crying sounds, variant.>', '', 28153),
(151722, 'esES', '<Kiss sound>', '', 28153),
(151721, 'esES', '<Laughing sounds>', '', 28153),
(151720, 'esES', '<Laughing>', '', 28153),
(151719, 'esES', '<Making a raspberry sound--Pfffthblth!>', '', 28153),
(151718, 'esES', '<Roar of dominance>', '', 28153),
(151717, 'esES', '<Variant roar>', '', 28153),
(151716, 'esES', '<Sighing sound>', '', 28153),
(151715, 'esES', '<Train noises--chugga chugga choo choo!>', '', 28153),
(151714, 'esES', 'Lo... lamento.', '', 28153),
(151713, 'esES', '¡Patético! ¡Caerás ante los Mag\'har!', '', 28153),
(151712, 'esES', 'Te lo agradezco.', '', 28153),
(151711, 'esES', 'Gracias.', '', 28153),
(151710, 'esES', 'Estoy en deuda contigo.', '', 28153),
(151709, 'esES', '¡Caerás ante mí!', '', 28153),
(151708, 'esES', '¡Por las lunas de Draenor!', '', 28153),
(151707, 'esES', 'Solo cumplo mi deber.', '', 28153),
(151706, 'esES', 'No me pidas que lo repita.', '', 28153),
(151705, 'esES', 'Ha sido un placer.', '', 28153),
(151704, 'esES', 'Habla.', '', 28153),
(151703, 'esES', 'Hola.', '', 28153),
(151702, 'esES', '¡Lok\'tar!', '', 28153),
(151701, 'esES', '¡Throm-ka!', '', 28153),
(151700, 'esES', 'No.', '', 28153),
(151699, 'esES', '¡Me niego!', '', 28153),
(151698, 'esES', '¡Jamás!', '', 28153),
(151697, 'esES', 'Así es.', '', 28153),
(151696, 'esES', 'Correcto.', '', 28153),
(151695, 'esES', 'En efecto.', '', 28153),
(151694, 'esES', 'Llamando a peón', 'Llamando a peón', 28153),
(151693, 'esES', '¡He avergonzado a mi clan!', '', 28153),
(151692, 'esES', 'Deja que recupere maná.', '', 28153),
(151691, 'esES', '¡Necesito maná!', '', 28153),
(151690, 'esES', '¿Mi música favorita? ¡El Roc\'a Negra!', '', 28153),
(151689, 'esES', 'A mí los lobos me gustan gélidos.', '', 28153),
(151688, 'esES', '¡Aaaaah! El quiropráctico de Orgrimmar ha hecho maravillas con mi espalda.', '', 28153),
(151687, 'esES', '¡Prueba tú a pasarte un par de décadas en un planeta lleno de draenei fanáticos a ver qué te parece!', '', 28153),
(151686, 'esES', 'El clan Riecráneos me abucheó en el club de los comediantes. ¡Con ese nombre pensé que tendrían sentido del humor!', '', 28153),
(151685, 'esES', 'Azeroth cambia de Jefe de Guerra como Draenor de línea temporal.', '', 28153),
(151684, 'esES', 'Nunca conocí a Gul\'dan, pero dicen que era lo peor en las fiestas. Siempre intentaba echar algo en el ponche...', '', 28153),
(151683, 'esES', '¡El círculo ritual de Xal\'vor se activa!', '¡El círculo ritual de Xal\'vor se activa!', 28153),
(151682, 'esES', '¡Por favor! ¡Te lo ruego!', '', 28153),
(151681, 'esES', '¡Apiádate de mí!', '', 28153),
(151680, 'esES', '¡Muestra un poco de compasión!', '', 28153),
(151679, 'esES', 'Buen trabajo.', '', 28153),
(151678, 'esES', 'Impresionante, supongo.', '', 28153),
(151677, 'esES', 'Pff. Te felicito.', '', 28153),
(151676, 'esES', 'Suéltate el pelo, hazme ese favor, y baila conmigo hasta Draenor.', '', 28153),
(151675, 'esES', 'Tengo el corazón contento desde aquel momento en que llegaste a mí.', '', 28153),
(151674, 'esES', 'Mi palabra de seguridad es \"zug-zug\".', '', 28153),
(151673, 'esES', 'Cuanto Mag\'har te miro, Mag\'har me gustas.', '', 28153),
(151672, 'esES', 'Hace años viajé a lo mochilero por Roca Negra.', '', 28153),
(151671, 'esES', '¿Te vienes a dar un paseo a la luz de la Sombraluna?', '', 28153),
(151670, 'esES', '¿Tu madre era una elemental de fuego? Porque haces que me suba la temperatura.', '', 28153),
(151669, 'esES', 'Que tengas una buena muerte.', '', 28153),
(151668, 'esES', 'No tengo nada más que decir.', '', 28153),
(151667, 'esES', 'Puedes irte.', '', 28153),
(151666, 'esES', 'Ve con honor.', '', 28153),
(151665, 'esES', '<Breathe as if you are running: Total 3>', '', 28153),
(151664, 'esES', '<Jumping off ground: Total 3>', '', 28153),
(151663, 'esES', '<Landing from jump: Total 3>', '', 28153),
(151662, 'esES', '<Vocalized cheer: Total 3>', '', 28153),
(151661, 'esES', '<Deep breath before focusing magic: Total 3>', '', 28153),
(151660, 'esES', '<Release after expending magic: Total 3>', '', 28153),
(151659, 'esES', '<Distressed cry: Total 3>', '', 28153),
(151658, 'esES', '<Convey summoning power. Energy buildup: Total 5-7>', '', 28153),
(151657, 'esES', '<Release spell, throwing energy: Total 3-5>', '', 28153),
(151656, 'esES', '<Standard attack: Total 10>', '', 28153),
(151655, 'esES', '<Big attack: Total 5>', '', 28153),
(151654, 'esES', '<Falling from high terrain. Impending injury or death: Total 1>', '', 28153),
(151653, 'esES', '<Player takes a wound: Total 10>', '', 28153),
(151652, 'esES', '<Player takes significant wound: Total 5>', '', 28153),
(151651, 'esES', '<Long attack with wind up. Jump attacks: Total 5-7>', '', 28153),
(151650, 'esES', '<Convey releasing power or charging enemy: Total 4-6>', '', 28153),
(151649, 'esES', '<Charging to attack enemy: Total 5-7>', '', 28153),
(151648, 'esES', '<Dying sounds: Total 5>', '', 28153),
(151647, 'esES', 'No se puede unir a este grupo.', '', 28153),
(151646, 'esES', 'No me queda munición.', '', 28153),
(151645, 'esES', 'Me falta energía.', '', 28153),
(151644, 'esES', 'No tengo suficiente energía.', '', 28153),
(151643, 'esES', 'Me hace falta maná.', '', 28153),
(151642, 'esES', 'Tengo poco maná.', '', 28153),
(151641, 'esES', 'Necesito maná.', '', 28153),
(151640, 'esES', 'No tengo suficiente ira.', '', 28153),
(151639, 'esES', 'Me hace falta más ira.', '', 28153),
(151638, 'esES', 'Demasiado lejos.', '', 28153),
(151637, 'esES', 'Está fuera de mi alcance.', '', 28153),
(151636, 'esES', 'Debo acercarme.', '', 28153),
(151635, 'esES', 'No podemos invitar a nadie más.', '', 28153),
(151634, 'esES', 'No puedo beber más ahora mismo.', '', 28153),
(151633, 'esES', 'Aún no tengo esa facultad.', '', 28153),
(151632, 'esES', 'Aún no puedo utilizar eso.', '', 28153),
(151631, 'esES', 'Ese hechizo aún no está listo.', '', 28153),
(151630, 'esES', 'No puedo lanzar ese hechizo aún.', '', 28153),
(151629, 'esES', '¡Levando anclas!', '¡Levando anclas!', 28153),
(151628, 'esES', 'Se está recargando.', '', 28153),
(151627, 'esES', 'Que no se te moje la pólvora.', 'Que no se te moje la pólvora.', 28153),
(151626, 'esES', 'Mantente leal.', 'Mantente leal.', 28153),
(151625, 'esES', 'Que el lastre no te arrastre.', 'Que el lastre no te arrastre.', 28153),
(151624, 'esES', 'La marea no espera a nadie.', 'La marea no espera a nadie.', 28153),
(151623, 'esES', 'Se acerca una tormenta. Lo siento en el agua.', 'Se acerca una tormenta. Lo siento en el agua.', 28153),
(151622, 'esES', 'El aquelarre caerá.', 'El aquelarre caerá.', 28153),
(151621, 'esES', 'La única bruja buena es la bruja muerta.', 'La única bruja buena es la bruja muerta.', 28153),
(151620, 'esES', 'Gloria a la casa Crestavía.', 'Gloria a la casa Crestavía.', 28153),
(151619, 'esES', 'Sé veloz como el viento y firme como el ancla.', 'Sé veloz como el viento y firme como el ancla.', 28153),
(151618, 'esES', 'Mantén un ojo en el horizonte.', 'Mantén un ojo en el horizonte.', 28153),
(151617, 'esES', 'Buen viento y buena mar.', 'Buen viento y buena mar.', 28153),
(151616, 'esES', '¡Por Kul Tiras!', '¡Por Kul Tiras!', 28153),
(151615, 'esES', 'No se puede despojar todavía.', '', 28153),
(151614, 'esES', 'No tengo un objetivo.', '', 28153),
(151613, 'esES', 'Necesito un objetivo primero.', '', 28153),
(151612, 'esES', 'Necesito un objetivo.', '', 28153),
(151611, 'esES', 'No puedo hacer eso.', '', 28153),
(151610, 'esES', 'Necesito permiso primero.', '', 28153),
(151609, 'esES', 'No puedo atacar a ese objetivo.', '', 28153),
(151608, 'esES', 'No se puede atacar.', '', 28153),
(151607, 'esES', 'Mi inventario está lleno.', '', 28153),
(151606, 'esES', 'No puedo llevar más.', '', 28153),
(151605, 'esES', 'Eso está bloqueado.', '', 28153),
(151604, 'esES', 'No puedo llevar más de eso.', '', 28153),
(151603, 'esES', 'Stromgarde aún es vulnerable, no resistirá un ataque directo de los demoledores. ¡Destruidlos antes de que se acerquen!', '', 28153),
(151602, 'esES', 'Aún no puedo usar ese objeto.', '', 28153),
(151601, 'esES', 'Aún no está a punto.', '', 28153),
(151600, 'esES', 'Este objeto aún se está recargando.', '', 28153),
(151599, 'esES', 'Nuestras fortificaciones aún son vulnerables. Rápido, ¡destruid esos demoledores antes de que se acerquen!', '', 28153),
(151598, 'esES', 'Me falta furia.', '', 28153),
(151597, 'esES', 'Tengo poca furia.', '', 28153),
(151596, 'esES', 'Me falta dolor.', '', 28153),
(151595, 'esES', 'Tengo poco dolor.', '', 28153),
(151594, 'esES', 'Eso no es una bolsa.', '', 28153),
(151593, 'esES', '¡Hay que detener a esos demoledores antes de que nos destruyan!', '', 28153),
(151592, 'esES', 'No tengo los fondos necesarios.', '', 28153),
(151591, 'esES', 'Está fuera de mis posibilidades.', '', 28153),
(151590, 'esES', '', '¡Desplegad ya a los demoledores! ¡No podemos permitir que la Alianza se asiente!', 28153),
(151589, 'esES', 'Demasiado caro.', '', 28153),
(151588, 'esES', '¿Alguna vez has visto el estómago de un kraken? Sigue así y pronto lo verás... por dentro.', '¿Alguna vez has visto el estómago de un kraken? Sigue así y pronto lo verás... por dentro.', 28153),
(151587, 'esES', '¡Enviad a loh demoledoreh! ¡Aplahtemoh a esoh insectoh de la Alianza anteh de que reaccionen!', '', 28153),
(151586, 'esES', 'Me da la impresión de que esto se está yendo a pique...', 'Me da la impresión de que esto se está yendo a pique...', 28153),
(151585, 'esES', '¡Enviad a los demoledores! ¡Las murallas de Stromgarde se derrumbarán ante la fuerza de la Horda!', '', 28153),
(151584, 'esES', '¡Eh! Maldita rata de cloaca...', '¡Eh! Maldita rata de cloaca...', 28153),
(151583, 'esES', '¡Máquinas de asedio! ¡Borradlos del mapa!', '', 28153),
(151582, 'esES', 'No tenéis derecho a estar aquí, gusanos.', '', 28153),
(151581, 'esES', '', '¡Han enviado máquinas de asedio! Tenemos que destruirlas antes de que se acerquen demasiado a nuestra base.', 28153),
(151580, 'esES', 'Mi arma requiere dos manos.', '', 28153),
(151579, 'esES', 'Esa facultad no está lista.', '', 28153),
(151578, 'esES', 'Aún no puedo hacer eso.', '', 28153),
(151577, 'esES', 'Aún no está lista.', '', 28153),
(151576, 'esES', 'No se puede poner ahí.', '', 28153),
(151575, 'esES', 'Esa bolsa está llena.', '', 28153),
(151574, 'esES', 'No puedo hacer eso aquí.', '', 28153),
(151573, 'esES', 'No puedo deshacerme de eso.', '', 28153),
(151572, 'esES', 'Eso está ligado a mí.', '', 28153),
(151571, 'esES', 'No puedo equipar eso.', '', 28153),
(151570, 'esES', 'Me falta nivel para usar eso.', '', 28153),
(151569, 'esES', 'No puedo usar eso todavía.', '', 28153),
(151568, 'esES', 'Mi nivel de habilidad no me permite equipar eso.', '', 28153),
(151567, 'esES', 'Nunca podré equipar eso.', '', 28153),
(151566, 'esES', 'Lo primero es lo primero. Necesitamos madera del Aserradero de las Tierras Altas y el hierro que podamos extraer de la Mina de Galson.', '', 28153),
(151565, 'esES', 'No puedo aprender ese hechizo.', '', 28153),
(151564, 'esES', 'En eso te equivocas, lady Liadrin. Las banderas de la Alianza volverán a ondear sobre Arathi.', '', 28153),
(151563, 'esES', '', 'Acaba con esta farsa, Danath. Los Aterratrols perdieron sus derechos sobre esta tierra hace años.', 28153),
(151562, 'esES', 'No puedo despojar eso.', '', 28153),
(151561, 'esES', 'No tengo derecho a despojar eso.', '', 28153),
(151560, 'esES', 'Necesito acercarme.', '', 28153),
(151559, 'esES', 'Ojalá pudiese decir lo mismo, Cazador de las Sombras.', '', 28153),
(151558, 'esES', 'Está demasiado lejos.', '', 28153),
(151557, 'esES', 'Está fuera de mi alcance.', '', 28153),
(151556, 'esES', 'Danath Aterratrolh. Me alegro de conocerte por fin...', '', 28153),
(151555, 'esES', 'No puedo comerciar con eso.', '', 28153),
(151554, 'esES', 'No puedo usar eso.', '', 28153),
(151553, 'esES', 'Eso no está equipado.', '', 28153),
(151552, 'esES', 'No, Arathi me pertenece a mí. Tu Horda y tú pagaréis por esta transgresión, Eitrigg.', '', 28153),
(151551, 'esES', 'Debo equiparlo primero.', '', 28153),
(151550, 'esES', '¡Aterratrols! Será mejor que pases de largo. Ahora Arathi pertenece a la Horda.', '', 28153),
(151549, 'esES', 'Primero tenemos que fortificar esta zona. Hay que conseguir madera y hierro.', '', 28153),
(151548, 'esES', '¡Aplastaré a este enemigo!', '', 28153),
(151547, 'esES', 'Desde luego, lady Liadrin. Me voy a deleitar ajusticiando a una paladín de la Horda que ha renunciado a sus principios.', '', 28153),
(151546, 'esES', '¡A por mi objetivo!', '', 28153),
(151545, 'esES', '¡Abatiré a mi oponente!', '', 28153),
(151544, 'esES', 'Por aquí.', '', 28153),
(151543, 'esES', 'Deja que este orco te guíe.', '', 28153),
(151542, 'esES', '', '¿Turalyon? Esto va a ser interesante...', 28153),
(151541, 'esES', 'Sígueme.', '', 28153),
(151540, 'esES', '¡Por la Horda!', '', 28153),
(151539, 'esES', '¡Estoy herido!', '', 28153),
(151538, 'esES', '¡Remiéndame!', '', 28153),
(151537, 'esES', 'No te quedes ahí mirando, ¡ayúdame!', '', 28153),
(151536, 'esES', '¡Ayúdame!', '', 28153),
(151535, 'esES', 'Espera aquí.', '', 28153),
(151534, 'esES', '¡No te muevas!', '', 28153),
(151533, 'esES', 'La Luz nos acompaña, Rokhan. No tememos a las sombras.', '', 28153),
(151532, 'esES', 'Vigila lah sombrah, Turalyon. La Horda y yo vamoh a por ti...', '', 28153),
(151531, 'esES', '¡Morid con honor!', '', 28153),
(151530, 'esES', '¡Atacad!', '', 28153),
(151529, 'esES', '¡Mok-thora ka!', '', 28153),
(151528, 'esES', '¡Aplastad al enemigo!', '', 28153),
(151527, 'esES', 'Vamos a expulsaros a ti y a tu ejército de la Horda de las colinas de Arathi, Eitrigg.', '', 28153),
(151526, 'esES', '¡Romped sus líneas!', '', 28153),
(151525, 'esES', '¡Retiraos o morid!', '', 28153),
(151524, 'esES', '¡Lucharemos otro día!', '', 28153),
(151523, 'esES', '¡Fuera! ¡Largo!', '', 28153),
(151522, 'esES', '¿Qué es ese olor que viene del campo de batalla? ¿La Alianza? Creo que es hora de luchar.', '', 28153),
(151521, 'esES', '¡En guardia!', '', 28153),
(151520, 'esES', 'Revísalo de cuando en cuando. No quiero que el hierro que hay en ese cofre se eche a perder.', '', 28153),
(151519, 'esES', '¡Que ardan!', '', 28153),
(151518, 'esES', '¡Fuego!', '', 28153),
(151517, 'esES', 'El enemigo llegará pronto. Hay que fortificar esta base, y, para eso, necesitamos madera y hierro.', '', 28153),
(151516, 'esES', '¡Tu Horda saldrá de aquí con el rabo entre las piernas cuando haya terminado con ella! ¡Ja!', '', 28153),
(151515, 'esES', '', 'Desiste, Muradin. Este territorio es de la Horda.', 28153),
(151514, 'esES', 'No, ¡busco a unos chuchos de la Horda para probar mi nueva hoja!', '', 28153),
(151513, 'esES', '¿Qué haceh aquí, Muradin? ¿Buhcah pelea?', '', 28153),
(151512, 'esES', '¿¡Por qué no te vuelves tú a tu asqueroso páramo, orco pulgoso!?', '', 28153),
(151511, 'esES', '¡Muradin! Tus enanos se han sobrepasado. Volved a esconderos en vuestra montaña.', '', 28153),
(151510, 'esES', '', 'Pronto tendremos a la Alianza a las puertas. Hay que darse prisa. Necesitamos madera y hierro para asegurar nuestra posición.', 28153),
(151509, 'esES', '', '¡Ja! En tus sueños, anciano. Hemos venido a reconquistar Stromgarde.', 28153),
(151508, 'esES', '¡Lady Liadrin! Bienvenida a Arathi. Supongo que habrás venido a rendirte.', '', 28153),
(151507, 'esES', '', 'Llevas mucho tiempo fuera, Turalyon. El mundo ha seguido adelante.', 28153),
(151506, 'esES', '¿Cómo? ¿Invasores de la Horda con una paladín al mando? ¿En qué se ha convertido el mundo?', '', 28153),
(151505, 'esES', '', 'Inténtalo, Muradin. Este territorio ahora es de la Horda.', 28153),
(151504, 'esES', 'Será mejor que pares antes si no quieres comer proyectiles de mortero de la Alianza.', '', 28153),
(151503, 'esES', 'Danath Aterratrolh... ¡Tú y yo tenemoh cuentah pendienteh! Te veré en el campo de batalla...', '', 28153),
(151502, 'esES', '¿Osáis invadir Arathi con un trol como comandante? Craso error.', '', 28153),
(151501, 'esES', '¿\"Pieles verdes\"? Jo, jo, jo... Ahora sí que me has hecho enfadar.', '', 28153),
(151500, 'esES', 'Reclamando', 'Reclamando', 28153),
(151499, 'esES', '<Klause se ríe>.\n\nSí, probablemente. Tengo un buen número de parientes desperdigados por ahí.', '', 28153),
(151498, 'esES', '¿Osáis invadir Stromgarde, el legítimo hogar de los Aterratrols? Fuera de mi vista, pieles verdes.', '', 28153),
(151497, 'esES', 'Hoy recuperaremos lo que nos pertenece por derecho. ¡Por la Alianza!', '', 28153),
(151496, 'esES', 'Los invasores han traído la ruina a Stromgarde durante demasiado tiempo.', '', 28153),
(151495, 'esES', '¡Por la Alianza!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'esES', '¡Soldados de la Alianza! Hoy arrebataremos la noble ciudad de Stromgarde a los monstruos de la Horda.', '', 28153),
(151493, 'esES', 'Hoy recuperaremos las colinas de Arathi... ¡Por la Alianza!', '', 28153),
(151492, 'esES', 'Cargad los rifles y desenvainad las espadas.', '', 28153),
(151491, 'esES', '', '¡Arathi será nuestro! ¡Por la Horda!', 28153),
(151490, 'esES', '', 'Centraos en la tarea que nos ocupa. Primero capturaremos Ar\'gorok, ¡y luego avanzaremos hacia Stromgarde!', 28153),
(151489, 'esES', '¿Vientopropicio? Ya he conocido a alguien con ese apellido.', '¿Vientopropicio? Ya he conocido a alguien con ese apellido.', 28153),
(151488, 'esES', '¡Haced las maletas! ¡Hay que sacar estas armas de aquí!', '', 28153),
(151487, 'esES', 'La fortaleza de Stromgarde se ha mejorado a castillo.', '', 28153),
(151486, 'esES', 'Hemos acabado de construir el arsenal.', '', 28153),
(151485, 'esES', 'El taller ya está listo.', '', 28153),
(151484, 'esES', 'Nuestro concejo se ha convertido en fortaleza.', '', 28153),
(151483, 'esES', 'El altar de los reyes está completo.', '', 28153),
(151482, 'esES', '¡Ahora nuestra fortaleza es un castillo!', '', 28153),
(151481, 'esES', 'El arsenal está construido.', '', 28153),
(151480, 'esES', 'El taller está listo para empezar a construir tanques.', '', 28153),
(151479, 'esES', 'Nuestro concejo ahora es una fortaleza.', '', 28153),
(151478, 'esES', 'El altar de los reyes está completo.', '', 28153),
(151477, 'esES', '¡Muy bien! ¡Nuestra fortaleza ahora es un castillo!', '', 28153),
(151476, 'esES', '¡El arsenal está listo para equipar a nuestras tropas!', '', 28153),
(151475, 'esES', 'Ya tenemos el taller en marcha. ¡Vamos a construir tanques!', '', 28153),
(151474, 'esES', '¡El concejo se ha mejorado a fortaleza!', '', 28153),
(151473, 'esES', '¡El altar de los reyes está listo!', '', 28153),
(151472, 'esES', '', 'Nuestro bastión se ha convertido en una fortaleza. ¡Por la Horda!', 28153),
(151471, 'esES', '', 'Este arsenal nos permitirá equipar mejor a nuestras tropas.', 28153),
(151470, 'esES', '', 'El taller ya está listo.', 28153),
(151469, 'esES', '', 'Nuestra base es más fuerte. La gran sala ahora es un bastión.', 28153),
(151468, 'esES', '', 'El altar de las tormentas está listo.', 28153),
(151467, 'esES', 'Nuestro cuartel está listo para entrenar a las tropas.', '', 28153),
(151466, 'esES', 'Hemos completado el cuartel. Es hora de empezar a entrenar a las tropas.', '', 28153),
(151465, 'esES', '¡Ya tenemos cuartel! ¡Empezad a entrenar a las tropas!', '', 28153),
(151464, 'esES', '', 'El cuartel está listo para entrenar a nuestras tropas.', 28153),
(151463, 'esES', '¡El bahtión se ha convertido en una fortaleza!', '', 28153),
(151462, 'esES', 'Hemoh mejorado la gran sala a bahtión.', '', 28153),
(151461, 'esES', 'El altar de lah tormentah ehtá lihto.', '', 28153),
(151460, 'esES', 'El cuartel ehtá lihto. Ehta guerra la van a ganar los brutoh.', '', 28153),
(151459, 'esES', '¡Ahora nuestro bastión es una fortaleza!', '', 28153),
(151458, 'esES', '¡Ahora nuestra gran sala es un bastión!', '', 28153),
(151457, 'esES', 'El altar de las tormentas ha sido completado.', '', 28153),
(151456, 'esES', 'Ya tenemos cuartel, ¡ahora a entrenar brutos!', '', 28153),
(151455, 'esES', '', 'Sigue soñando. Caballeros de sangre, ¡acabad con ellos!', 28153),
(151454, 'esES', 'Y a mí me llaman cazador de lah Sombrah también por algo. Ahora, asesinoh. ¡Mohtraoh!', '', 28153),
(151453, 'esES', 'Conozco perfectamente vuestra \"justicia de la Alianza\". Jinetes del viento, ¡hacedles sentir la furia de la Horda!', '', 28153),
(151452, 'esES', '', '¡Jamás!', 28153),
(151451, 'esES', 'Ehta tierra no oh pertenece, Aterratrolh. Era nuehtra mucho anteh de que llegaraih.', '', 28153),
(151450, 'esES', '¡Ja! Te equivocas.', '', 28153),
(151449, 'esES', '', 'Ya estoy harta de tu insolencia. Caballeros de sangre, ¡que sufran la furia de la Luz!', 28153),
(151448, 'esES', 'La Luz no podrá salvarte ahora. Cazadoreh de lah Sombrah, ¡mohtraoh!', '', 28153),
(151447, 'esES', 'Jinetes del viento, ¡atacad desde el cielo!', '', 28153),
(151446, 'esES', '', 'Eso ya lo veremos, Turalyon. Aún tienes que vértelas conmigo.', 28153),
(151445, 'esES', 'Te ehtaré ehperando.', '', 28153),
(151444, 'esES', 'No, si puedo evitarlo, Turalyon.', '', 28153),
(151443, 'esES', '', 'Eso no será suficiente, enano. ¡Caballeros de sangre, a las armas!', 28153),
(151442, 'esES', 'Hah caído en mi trampa, Muradin. Cazadoreh de lah Sombrah, ¡mohtraoh!', '', 28153),
(151441, 'esES', '¡Ahora, jinetes del viento! ¡Al ataque!', '', 28153),
(151440, 'esES', '', 'Nunca.', 28153),
(151439, 'esES', '¡Mejor que te cubrah lah ehpaldah, Muradin!', '', 28153),
(151438, 'esES', 'No por mucho tiempo, enano. ¡Por la Horda!', '', 28153),
(151437, 'esES', 'Perdí esta ciudad una vez, no volveré a permitirlo. Y menos contra vosotros. ¡Defensores, mostradles la fuerza de Stromgarde!', '', 28153),
(151436, 'esES', 'Yo a salvo ahora. Vuelta al trabajo.', '', 28153),
(151435, 'esES', 'La Luz está de mi lado. ¡Defensores, adelante!', '', 28153),
(151434, 'esES', 'Defenderé Stromgarde hasta la muerte, Liadrin. ¡Defensores, manteneos firmes!', '', 28153),
(151433, 'esES', 'No lo celebres todavía, elfa de sangre. Aún tienes que vértelas conmigo.', '', 28153),
(151432, 'esES', 'Sí... Cuento con ello.', '', 28153),
(151431, 'esES', '¡Bah! ¡El terreno elevado está sobrevalorado!', '', 28153),
(151430, 'esES', 'Este viejo idiota aún tiene algunos ases en la manga. Defensores, ¡mostradles la fuerza de Stromgarde!', '', 28153),
(151429, 'esES', 'La Luz siempre triunfará sobre las sombras, Rokhan. ¡Defensores, adelante!', '', 28153),
(151428, 'esES', 'Rokhan, ¡te estaba esperando! Defensores, ¡demostradles de qué pasta estamos hechos!', '', 28153),
(151427, 'esES', 'Cierra el pico, trol. La Alianza triunfará frente a tu asqueroso ejército de monstruos. ', '', 28153),
(151426, 'esES', 'Pero la Luz aún brilla sobre Stromgarde.', '', 28153),
(151425, 'esES', 'Pronto, chaval. Primero dejaré que mis fusileros os ablanden un poco.', '', 28153),
(151424, 'esES', 'Stromgarde aún resiste, orco. Disfrutaré viendo tu cadáver flotar en mi foso. ¡Defensores, mostradles la fuerza de nuestra ciudad!', '', 28153),
(151423, 'esES', 'He ganado y perdido mil batallas más de las que tú has librado, Eitrigg. Y esta aún no está perdida. Defensores, ¡adelante!', '', 28153),
(151422, 'esES', 'Primero tendrás que echarle el guante. ¡Defensores, rechazadlos!', '', 28153),
(151421, 'esES', 'Bah. A mí los de tu especie me parecen todos iguales. Morirás de rodillas, como el resto.', '', 28153),
(151420, 'esES', 'Ten paciencia, orco. No tardarán en llegar.', '', 28153),
(151419, 'esES', '¡Y yo te huelo el aliento desde aquí abajo! ¡Da la cara, orco!', '', 28153),
(151418, 'esES', 'Máquinas de asedio, ahora, reventad esa puerta. ¡Clavaré la cabeza de esa elfa de sangre en una pica!', '', 28153),
(151417, 'esES', 'Máquinas de asedio, ahora, ¡reventad esa puerta y traedme a Rokhan! Me llaman Aterratrols por algo...', '', 28153),
(151416, 'esES', 'Máquinas de asedio, ahora, reventad esa puerta. ¡Ese orco vil va a saber lo que es la justicia de la Alianza!', '', 28153),
(151415, 'esES', 'Nido Alto es nuestro. Es vuestra última oportunidad... Rendíos, y puede que os perdone la vida.', '', 28153),
(151414, 'esES', 'Hemos conquistado Nido Alto. ¡Pronto saquearemos Ar\'gorok y reclamaremos lo que es nuestro!', '', 28153),
(151413, 'esES', 'Nido Alto es nuestro. Poco a poco conseguiremos expulsar a estos intrusos.', '', 28153),
(151412, 'esES', 'La Mina de Galson nos proporcionará hierro sin límite. Eso nos vendrá bien.', '', 28153),
(151411, 'esES', 'Perfecto. Gracias al Aserradero de las Tierras Altas tendremos madera para reconstruir Stromgarde.', '', 28153),
(151410, 'esES', 'Esta es nuestra oportunidad. ¡Asediad la puerta! ¡Castigad a esos invasores de la Horda!', '', 28153),
(151409, 'esES', 'Esta es nuestra oportunidad. ¡La Luz viene a por ti, Rokhan!', '', 28153),
(151408, 'esES', 'Esta es nuestra oportunidad. ¡Asediad la puerta! ¡Ha llegado tu fin, Eitrigg!', '', 28153),
(151407, 'esES', 'Hemos capturado Nido Alto. La Luz favorece a la Alianza.', '', 28153),
(151406, 'esES', 'Nido Alto es nuestro y Ar\'gorok lo será pronto. Vamos a por ti, Rokhan.', '', 28153),
(151405, 'esES', 'Nos hemos hecho con Nido Alto. Pronto destruiremos las fuerzas de la Horda por completo.', '', 28153),
(151404, 'esES', 'Bien. La Mina de Galson debería proporcionarnos todo el hierro que necesitamos.', '', 28153),
(151403, 'esES', 'La madera del aserradero será crucial para construir nuestra base.', '', 28153),
(151402, 'esES', '¡Rápido, traed las máquinas de asedio! ¡Demostradle a esa elfa de sangre lo que pueden hacer los morteros de los enanos!', '', 28153),
(151401, 'esES', '¡Rápido, traed las máquinas de asedio! ¡Derribad la puerta! ¡Quemad la choza de ese trol!', '', 28153),
(151400, 'esES', '¡Rápido, traed las máquinas de asedio! ¡Derribad la puerta! ¡Haced pedazos a esos orcos!', '', 28153),
(151399, 'esES', '¡Nido Alto pertenece a la Alianza! ¿Estás lista para sacar la bandera blanca?', '', 28153),
(151398, 'esES', '¡Hemos tomado Nido Alto! Vamos a por ti, Rokhan.', '', 28153),
(151397, 'esES', 'Je... No he pagado mi cuenta...', 'Je... No he pagado mi cuenta...', 28153),
(151396, 'esES', '¡Nido Alto es nuestro! ¡Por la Alianza!', '', 28153),
(151395, 'esES', 'Quizás... podamos llegar a un acuerdo...', 'Quizás... podamos llegar a un acuerdo...', 28153),
(151394, 'esES', 'Ahora que la Mina de Galson está bajo nuestro control, debería sobrarnos el hierro.', '', 28153),
(151393, 'esES', 'Bien, nos hemos hecho con el Aserradero de las Tierras Altas. Nos vendrá bien para construir nuestra base.', '', 28153),
(151392, 'esES', '', 'Aquí hace falta habilidad... ¡y vosotroh no tenéih de eso!', 28153),
(151391, 'esES', '', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Arrasad Stromgarde!', 28153),
(151390, 'esES', '¡Ojo!', '¡Ojo!', 28153),
(151389, 'esES', '', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Ha llegado tu hora, Turalyon!', 28153),
(151388, 'esES', '¿A qué ha venido eso?', '¿A qué ha venido eso?', 28153),
(151387, 'esES', '', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Obligad a ese enano a dar la cara!', 28153),
(151386, 'esES', '', '¡Nido Alto es nuestro! ¡Un paso más para que la Horda conquiste Arathi!', 28153),
(151385, 'esES', '', '¡Nido Alto es nuestro! La Horda pronto se cernirá sobre ti, Turalyon.', 28153),
(151384, 'esES', '', 'Hemos tomado Nido Alto, ahora ocupamos el terreno elevado. La balanza se inclina a nuestro favor.', 28153),
(151383, 'esES', '', 'Bien hecho. No íbamos a llegar muy lejos sin el hierro de esa mina.', 28153),
(151382, 'esES', '¡Ni muertoh servíh pa nada! Apartaoh, ¡mirad cómo se hace!', '', 28153),
(151381, 'esES', '', 'Usaremos la madera de Cumbre Destral para construir los cimientos de nuestra base. Bien hecho.', 28153),
(151380, 'esES', '¡Enviad a loh demoledoreh! ¡Dehtruid la puerta! ¡Y traedme la cabeza de ese viejo idiota de Aterratrolh!', '', 28153),
(151379, 'esES', '¡Enviad a loh demoledoreh! ¡No hay Luz que pueda proteger a ese paladín del poder de la Horda!', '', 28153),
(151378, 'esES', '¡Enviad a loh demoledoreh! ¡Hagamoh que ese enano deje de ocultarse trah la puerta!', '', 28153),
(151377, 'esES', 'Nido Alto ha caído ante la Horda, Aterratrolh.', '', 28153),
(151376, 'esES', 'Nido Alto eh nuehtro, Turalyon. Lah sombrah se acercan...', '', 28153),
(151375, 'esES', 'Muradin... Hemoh tomado Nido Alto. ¿Ehtáh lihto pa salir a luchar?', '', 28153),
(151374, 'esES', 'La Mina Mohtacho Seco pertenece a la Horda.', '', 28153),
(151373, 'esES', '', 'Valéih lo mihmo muertoh que vivoh: ¡nada! ¡Yo me encargo!', 28153),
(151372, 'esES', 'Bien. Usaremoh la madera de Cumbre Dehtral pa conhtruir nuehtro bahtión.', '', 28153),
(151371, 'esES', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Que ese idiota de Aterratrols vea de lo que son capaces unos pieles verdes!', '', 28153),
(151370, 'esES', '', 'Taelia, eres una mujer joven y valiente. Tu padre estaría orgulloso.', 28153),
(151369, 'esES', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Esta batalla está casi ganada!', '', 28153),
(151368, 'esES', '¡Atacad con los demoledores! ¡Derribad esa puerta! ¡Plantaremos la cabeza de ese maldito enano en una pica!', '', 28153),
(151367, 'esES', 'El jefe no va a estar contento...', 'El jefe no va a estar contento...', 28153),
(151366, 'esES', 'Nido Alto pertenece a la Horda. O debería decir a los \"pieles verdes\".', '', 28153),
(151365, 'esES', 'Nido Alto es nuestro. ¿Qué hay de esas represalias, Turalyon? Estoy esperando.', '', 28153),
(151364, 'esES', 'Ay...', 'Ay...', 28153),
(151363, 'esES', 'Nada... personal...', 'Nada... personal...', 28153),
(151362, 'esES', 'Hemos capturado Nido Alto. ¡Muradin! ¡Te veo la napia desde aquí arriba!', '', 28153),
(151361, 'esES', 'Solo... hacía mi trabajo...', 'Solo... hacía mi trabajo...', 28153),
(151360, 'esES', '', 'Taelia... Claro. Nuestra joven guarda de ultramar. ¿Ha pasado tanto tiempo?', 28153),
(151359, 'esES', 'Bien hecho. Con la Mina Mostacho Seco bajo control, nunca nos faltará hierro.', '', 28153),
(151358, 'esES', 'Cumbre Destral es nuestra. Su madera nos vendrá bien para construir nuestra base.', '', 28153),
(151357, 'esES', '¡No es nada personal, pero tenemos unas normas!', '¡No es nada personal, pero tenemos unas normas!', 28153),
(151356, 'esES', 'La Senda del Valor es nuestra. ¡Seguid atacando!', '', 28153),
(151355, 'esES', '', 'Taelia, señora.', 28153),
(151354, 'esES', 'Bien hecho. Hemos retomado el Círculo de los Elementos.', '', 28153),
(151353, 'esES', 'Los estandartes de la Alianza ondean sobre Finca Nueva una vez más.', '', 28153),
(151352, 'esES', '', 'Tienes razón. Y tu nombre es...', 28153),
(151351, 'esES', 'Hemos capturado la Senda del Valor.', '', 28153),
(151350, 'esES', 'Ahora el Círculo de los Elementos pertenece a la Alianza.', '', 28153),
(151349, 'esES', 'Bien hecho, soldados. Finca Nueva es nuestra.', '', 28153),
(151348, 'esES', '¡Para ya!', '¡Para ya!', 28153),
(151347, 'esES', '', 'Lady almirante, deberíamos llevarte de vuelta al fuerte. Allí podremos examinar las pruebas contra la casa Gobernalle.', 28153),
(151346, 'esES', 'Bien, los hemos expulsado de la Senda del Valor. ¡Sigamos adelante!', '', 28153),
(151345, 'esES', '¡Hemos tomado el Círculo de los Elementos!', '', 28153),
(151344, 'esES', '¡Acabas de pasarte de la raya!', '¡Acabas de pasarte de la raya!', 28153),
(151343, 'esES', '¡Hemos saqueado Finca Nueva!', '', 28153),
(151342, 'esES', '', 'El Círculo de los Elementos es nuestro.', 28153),
(151341, 'esES', '', 'Hemos tomado Finca Nueva.', 28153),
(151340, 'esES', '¡Tenemos formas de encargarnos de los alborotadores!', '¡Tenemos formas de encargarnos de los alborotadores!', 28153),
(151338, 'esES', '', 'Vale, eso debería de darnos algo de margen.', 28153),
(151337, 'esES', '¡Oye!', '¡Oye!', 28153),
(151336, 'esES', 'Cuidado con lah sombrah, ehcoria de la Alianza. La Horda va a por vosotroh...', '', 28153),
(151335, 'esES', 'Bien hecho. Ahora que tenemos Cruce Redilnorte, podemos centrarnos en objetivos mayores.', '', 28153),
(151333, 'esES', '', '¡Tú! Necesito hablar contigo.', 28153),
(151332, 'esES', 'Esperé un sinfín de años para llevar a cabo mi venganza, hasta que al fin tu madre me proporcionó los medios necesarios.', '', 28153),
(151331, 'esES', 'Tus ancestros aniquilaron a mi pueblo, pero no consiguieron acabar conmigo.', '', 28153),
(151330, 'esES', '', '¡¿Gorak Tul?! ¿Cómo es posible? ¡Mis ancestros te derrotaron hace eones!', 28153),
(151329, 'esES', 'Máquinas de asedio, ¡destruid esa base!', '', 28153),
(151328, 'esES', 'Se os avisó, escoria de la Horda. Ahora preparaos para ser aniquilados.', '', 28153),
(151327, 'esES', '¡Estas tierras son de la Alianza! Los muros benditos de Stromgarde nunca caerán ante los de vuestra calaña.', '', 28153),
(151326, 'esES', '¿Eso que veo en mi campo de batalla es la Horda? ¡Me muero por una buena pelea!', '', 28153),
(151324, 'esES', '¡Hay que detenerlos y absorber esa azerita para potenciar el corazón!', '', 28153),
(151323, 'esES', 'Están apareciendo más heridas por todo Azeroth, y hay más fuerzas que pretenden usar la azerita para sus propios fines.', '', 28153),
(151322, 'esES', 'El Corazón de Azeroth es la clave para curar nuestro mundo... pero si queremos tener éxito, deberás potenciarlo primero.', '', 28153),
(151321, 'esES', 'Magni, estoy listo para que potencies el Corazón de Azeroth.', 'Magni, estoy lista para que potencies el Corazón de Azeroth.', 28153),
(151320, 'esES', 'Tengo que hablar contigo en Silithus. ¡Aún queda mucho por hacer para salvar nuestro mundo!', '', 28153),
(151319, 'esES', '', '¡Tengo una escoba y estoy dispuesta a usarla!', 28153),
(151318, 'esES', '', '¡Atrás, roedores del cielo!', 28153),
(151317, 'esES', '', '¡Fuera de ahí!', 28153),
(151316, 'esES', '', '¡Largo de aquí, sucios pájaros!', 28153),
(151315, 'esES', '¡A pagar, piltrafas!', '', 28153),
(151314, 'esES', '¡Bestias de pesadilla, acudid!', '', 28153),
(151313, 'esES', 'Tengo un buen presentimiento. Creo que lo encontraremos hoy.', 'Tengo un buen presentimiento. Creo que lo encontraremos hoy.', 28153),
(151312, 'esES', 'Esas botas me quedarán bien.', 'Esas botas me quedarán bien.', 28153),
(151311, 'esES', '¡Te voy a rajar!', '¡Te voy a rajar!', 28153),
(151310, 'esES', 'Aquí no hay nadie que pueda salvarte, escoria.', 'Aquí no hay nadie que pueda salvarte, escoria.', 28153),
(151309, 'esES', 'Mira por dónde pisas.', 'Mira por dónde pisas.', 28153),
(151308, 'esES', 'No aguantarás nada...', 'No aguantarás nada...', 28153),
(151307, 'esES', 'Espera y verás...', 'Espera y verás...', 28153),
(151306, 'esES', '¡Estos recursos no te pertenecen!', '¡Estos recursos no te pertenecen!', 28153),
(151305, 'esES', '¡Carne fresca!', '¡Carne fresca!', 28153),
(151304, 'esES', '¡Desbordaos, océanos! ¡Alzaos, esbirros!', '', 28153),
(151303, 'esES', '¡Horrores reptantes, venid a comer!', '', 28153),
(151302, 'esES', '¡Criaturas de las profundidades, yo os llamo!', '', 28153),
(151301, 'esES', 'Aire buen olor aquí. No como mina llena de orcos.', '', 28153),
(151300, 'esES', '¡Que la oscuridad os lleve!', '', 28153),
(151299, 'esES', 'Me estoy cansando. ¡Vuestra hora ha llegado!', '', 28153),
(151298, 'esES', 'Los esbirros de Azshara son innumerables, ¿por qué resistirse?', '', 28153),
(151297, 'esES', 'Yo no tan asustado ahora, pero rocas cansan brazos.', '', 28153),
(151295, 'esES', 'Ha empezado a oír susurros. Creo que no nos queda mucho tiempo.', '', 28153),
(151294, 'esES', '', 'Os sigo. ¡No paréis!', 28153),
(151293, 'esES', 'Bajo las mareas... Esperando... Llamándome...', '', 28153),
(151292, 'esES', 'Por aquí. Consigo hierro.', '', 28153),
(151291, 'esES', 'Busca expositores de armas por aquí cerca. Los infieles los tienen por todas partes.\n\nYo procuraré no llamar la atención hasta que vuelvas.', 'Busca expositores de armas por aquí cerca. Los infieles los tienen por todas partes.\n\nYo procuraré no llamar la atención hasta que vuelvas.', 28153),
(151290, 'esES', '', '¡Vientos, protegedme!', 28153),
(151289, 'esES', 'Volveré cuando encuentre un arma para ti.', 'Volveré cuando encuentre un arma para ti.', 28153),
(151288, 'esES', '', '¡Nosotros siempre tenemos el viento a favor!', 28153),
(151287, 'esES', '¡Os haré astillas!', '', 28153),
(151286, 'esES', '¡Mi casco es impenetrable!', '', 28153),
(151285, 'esES', '¡Los elementos hierven de ira!', '¡Los elementos hierven de ira!', 28153),
(151284, 'esES', 'Los ladrones de mundos mortales perecerán.', 'Los ladrones de mundos mortales perecerán.', 28153),
(151283, 'esES', '¡Os quitaremos todo lo que habéis saqueado!', '¡Os quitaremos todo lo que habéis saqueado!', 28153),
(151282, 'esES', '¡Los elementos reinarán para siempre!', '¡Los elementos reinarán para siempre!', 28153),
(151281, 'esES', '¡Esto no nos lo arrebataréis!', '¡Esto no nos lo arrebataréis!', 28153),
(151280, 'esES', '¡Estas gemas pertenecen a los señores de los elementos!', '¡Estas gemas pertenecen a los señores de los elementos!', 28153),
(151279, 'esES', '<Romper sus cadenas y darle un arma con la que luchar>.', '<Romper sus cadenas y darle un arma con la que luchar>.', 28153),
(151278, 'esES', '¡Con este poder recuperaremos este mundo!', '¡Con este poder recuperaremos este mundo!', 28153),
(151277, 'esES', '<Romper sus cadenas y darle un arma con la que luchar>.', '<Romper sus cadenas y darle un arma con la que luchar>.', 28153),
(151276, 'esES', 'Mi señor me recompensará por destruiros.', 'Mi señor me recompensará por destruiros.', 28153),
(151275, 'esES', 'Dame un arma y yo te daré diez infieles muertos.', 'Dame un arma y yo te daré diez infieles muertos.', 28153),
(151274, 'esES', 'Coge tus cosas. Te vienes conmigo.', 'Coge tus cosas. Te vienes conmigo.', 28153),
(151273, 'esES', 'Rompe estas cadenas, $gamigo:amiga;. Los vulperas deben ser libres.', 'Rompe estas cadenas, $gamigo:amiga;. Los vulperas deben ser libres.', 28153),
(151272, 'esES', 'Quiero trabajar, pero no es seguro.', '', 28153),
(151271, 'esES', 'Libérame, $pr, y te ayudaré a matar a los infieles.', 'Libérame, $pr, y te ayudaré a matar a los infieles.', 28153),
(151270, 'esES', 'No habrá piedad para los infieles. No después de lo que han hecho.', 'No habrá piedad para los infieles. No después de lo que han hecho.', 28153),
(151269, 'esES', 'Haré que los infieles paguen por lo que me han hecho.', 'Haré que los infieles paguen por lo que me han hecho.', 28153),
(151268, 'esES', '¿Te ha enviado Nisha? Sea cual sea su plan, me apunto.', '¿Te ha enviado Nisha? Sea cual sea su plan, me apunto.', 28153),
(151267, 'esES', 'Tú consígueme un arma, $gamigo:amiga;, y yo me ocuparé del resto.', 'Tú consígueme un arma, $gamigo:amiga;, y yo me ocuparé del resto.', 28153),
(151266, 'esES', 'Solo necesito un arma.', 'Solo necesito un arma.', 28153),
(151265, 'esES', 'No... Las gemas son mías... No podéis... llevároslas...', '', 28153),
(151264, 'esES', '¡No! ¡Idiotas!', '', 28153),
(151263, 'esES', 'No... habéis... ganado...', '', 28153),
(151262, 'esES', '¡Volveré!', '', 28153),
(151261, 'esES', 'Nuestro momento se acerca...', '', 28153),
(151260, 'esES', 'Solo estáis retrasando... lo inevitable...', '', 28153),
(151259, 'esES', 'El caos... no se puede contener...', '', 28153),
(151258, 'esES', 'No se puede detener... a los elementos...', '', 28153),
(151257, 'esES', '¡Vuestros mares hervirán, vuestro cielo se abrirá, vuestras montañas se alzarán y nosotros volveremos!', '', 28153),
(151256, 'esES', '¡Se acerca el amanecer de los elementos!', '', 28153),
(151255, 'esES', 'Se os acaba el tiempo, mortales.', '', 28153),
(151254, 'esES', 'Con estas gemas por fin os destruiremos.', '', 28153),
(151253, 'esES', '¡Los elementos volverán a reinar!', '', 28153),
(151252, 'esES', '¡Los minerales dorados nos dan poder!', '', 28153),
(151251, 'esES', '¡Vuestro mundo volverá a ser nuestro!', '', 28153),
(151250, 'esES', '¿Cómo osáis enfrentaros a mí en mi propio plano?', '', 28153),
(151249, 'esES', 'Yo miro. ¡Manos demasiado llenas!', '', 28153),
(151248, 'esES', 'Envíame a Orgrimmar.', 'Envíame a Orgrimmar.', 28153),
(151247, 'esES', '', 'Me alegro de verte, $n. Voy a quedarme aquí por ahora pa ehtar cerca de Krag\'wa.\n\nMih padreh me contaban todo tipo de hihtoriah sobre el loa rana. Pa mí eh un honor defenderlo de loh trolh de sangre.', 28153),
(151246, 'esES', 'Con esto bastará. ¡Gracias!', 'Con esto bastará. ¡Gracias!', 28153),
(151245, 'esES', '¡Eh! ¡Tráeme balas de cañón para que pueda seguir disparando!', '¡Eh! ¡Tráeme balas de cañón para que pueda seguir disparando!', 28153),
(151244, 'esES', '', 'Draénor. Dráenor. Drinor... Drenor. Mira, mejor digo que soy de Terrallende.', 28153),
(151243, 'esES', '', 'Se puede decir que estoy incorrupta, pero prefiero considerarme orgánica.', 28153),
(151242, 'esES', '', 'Me teñí el pelo de verde una vez. Al jefe de guerra Grito Infernal no le hizo gracia.', 28153),
(151241, 'esES', '', '¡Ya basta de tanto bamboleo y trastabilleo! Anda, ¡déjame aplastar cosas!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'esES', '', 'Los Mano Destrozada son guerreros legendarios, pero no les pidas que te den un masaje, hazme caso...', 28153),
(151239, 'esES', '', 'En Azeroth hay demasiadas reglas: a quién se puede apuñalar, a quién no, a quién se puede pegar, a quién no... ¡A ver si os relajáis un poco!', 28153),
(151238, 'esES', '', 'Oye... ¿¡No eres tú quien dejó abandonada esa ciudadela en Fuego Glacial!?', 28153),
(151237, 'esES', '', 'Quédate el tiempo que quieras, pero recuerda: ¡el que rompe paga, colega!', 28153),
(151236, 'esES', '', 'Antes de seguir, dime una cosa: ¿qué tal toleras el dolor?', 28153),
(151235, 'esES', '', 'Que esté disfrutando de tu compañía no quita que tenga ganas de pegarte un buen puñetazo.', 28153),
(151234, 'esES', '', 'Un chamán de los Foso Sangrante me ha tirado los trastos. Creo... O me estaba guiñando el ojo o acababa de arrancárselo.', 28153),
(151233, 'esES', '', 'La última persona que me tiró los tejos se los tragó.', 28153),
(151232, 'esES', '', 'Un orco verde me dio un caramelo con forma de corazón que decía: \"Te quiero desde que te vil\". Le dije que aborrezco la sangre de demonio y lo noqueé.', 28153),
(151231, 'esES', '', '¿Sabes si Colmillosauro está soltero? Tiene ese rollo madurito interesante...', 28153),
(151230, 'esES', '', 'No necesitas un Portal Oscuro... Ya has invadido mi corazón.', 28153),
(151229, 'esES', '', 'Lo... lo lamento.', 28153),
(151228, 'esES', '', '¡Patético! ¡Caerás ante los Mag\'har!', 28153),
(151227, 'esES', 'Si quieres que algo salga bien...', 'Si quieres que algo salga bien...', 28153),
(151226, 'esES', 'Debí pedir ese ascenso...', 'Al final... me he quemado...', 28153),
(151225, 'esES', 'Enterradme... con mi oro...', 'Nadie escapa de la muerte... ni de los impuestos...', 28153),
(151224, 'esES', 'Eso... duele...', 'Pagaréis por esto...', 28153),
(151223, 'esES', 'No... valió la pena...', 'No... valió la pena...', 28153),
(151222, 'esES', '¿Y mi... paga por peligrosidad?', 'No... valió la pena...', 28153),
(151221, 'esES', '', 'Te lo agradezco.', 28153),
(151220, 'esES', '', 'Gracias.', 28153),
(151219, 'esES', 'La Jefa de Guerra ha dicho que los daños colaterales son aceptables. ¡Arde, escoria!', 'La Jefa de Guerra ha dicho que los daños colaterales son aceptables. ¡Arde, escoria!', 28153),
(151218, 'esES', 'Daños colaterales permitidos. ¡Arde, escoria!', 'Han puesto precio a tu cabeza... ¡y ese oro lleva mi nombre!', 28153),
(151217, 'esES', '', 'Estoy en deuda contigo.', 28153),
(151216, 'esES', '', '¡Caerás ante mí!', 28153),
(151215, 'esES', 'Nadie puede detenerla...', 'Nadie puede detenerla...', 28153),
(151214, 'esES', 'Has intentado salvar la ciudad equivocada.', '¡Acabas de cometer un gran error!', 28153),
(151213, 'esES', '', '¡Por las lunas de Draenor!', 28153),
(151212, 'esES', '¡Voy a disfrutar con esto!', '¡Me encanta quemar cosas!', 28153),
(151211, 'esES', 'Por la Horda... ¡y por los beneficios!', '¡Por la Horda!', 28153),
(151210, 'esES', '', 'Solo cumplo mi deber.', 28153),
(151209, 'esES', '', 'No me pidas que lo repita.', 28153),
(151208, 'esES', '', 'Ha sido un placer.', 28153),
(151207, 'esES', '', 'No.', 28153),
(151206, 'esES', '', '¡Me niego!', 28153),
(151205, 'esES', '', '¡Jamás!', 28153),
(151204, 'esES', '', 'Correcto.', 28153),
(151203, 'esES', '', 'Correcto.', 28153),
(151202, 'esES', '', 'En efecto.', 28153),
(151201, 'esES', '', '¡He avergonzado a mi clan!', 28153),
(151200, 'esES', '', 'Deja que recupere maná.', 28153),
(151199, 'esES', '', '¡Necesito maná!', 28153),
(151198, 'esES', '', 'Que tengas una buena muerte.', 28153),
(151197, 'esES', '', 'No tengo nada más que decir.', 28153),
(151196, 'esES', '', 'Puedes irte.', 28153),
(151195, 'esES', '', 'Ve con honor.', 28153),
(151194, 'esES', '', 'Habla.', 28153),
(151193, 'esES', '', 'Hola.', 28153),
(151192, 'esES', '', '¡Lok\'tar!', 28153),
(151191, 'esES', '', '¡Throm-ka!', 28153),
(151190, 'esES', '', '¡Por favor! ¡Te lo ruego!', 28153),
(151189, 'esES', '', '¡Apiádate de mí!', 28153),
(151188, 'esES', '', '¡Muestra un poco de compasión!', 28153),
(151187, 'esES', '', 'Buen trabajo.', 28153),
(151186, 'esES', '', 'Impresionante, supongo.', 28153),
(151185, 'esES', '', 'Pff. Te felicito.', 28153),
(151184, 'esES', '¡Vamos, tacaños, que estas defensas no se pagan solas!', '', 28153),
(151183, 'esES', '', '¡Aplastaré a este enemigo!', 28153),
(151182, 'esES', '', '¡A por mi objetivo!', 28153),
(151181, 'esES', '', '¡Abatiré a mi oponente!', 28153),
(151180, 'esES', '', '¡Morid con honor!', 28153),
(151179, 'esES', '', '¡Atacad!', 28153),
(151178, 'esES', '', '¡Mok-thora ka!', 28153),
(151177, 'esES', '¿Por qué luchas?', '¿Por qué luchas?', 28153),
(151176, 'esES', 'La Horda prevalecerá.', 'La Horda prevalecerá.', 28153),
(151175, 'esES', '', '¡Nos atacan!', 28153),
(151174, 'esES', '', '¡Aplastad al enemigo!', 28153),
(151173, 'esES', '', '¡Romped sus líneas!', 28153),
(151172, 'esES', '', '¡Retiraos o morid!', 28153),
(151171, 'esES', '', '¡Lucharemos otro día!', 28153),
(151170, 'esES', '', '¡Fuera! ¡Largo!', 28153),
(151169, 'esES', '', 'Por aquí.', 28153),
(151168, 'esES', '', 'Deja que esta orco te guíe.', 28153),
(151167, 'esES', 'Camaradas... seguid sin mí...', 'Camaradas... seguid sin mí...', 28153),
(151166, 'esES', 'Ahora descansaré.', 'Ahora descansaré.', 28153),
(151165, 'esES', '', 'Sígueme.', 28153),
(151164, 'esES', 'Que los espíritus... me guíen.', 'Que los espíritus... me guíen.', 28153),
(151163, 'esES', 'Apártate y vivirás.', 'Apártate y vivirás.', 28153),
(151162, 'esES', 'Sanamos y dañamos a voluntad.', 'Sanamos y dañamos a voluntad.', 28153),
(151161, 'esES', '', '¡Por la Horda!', 28153),
(151160, 'esES', '¡Horda, a mí! ¡Sanaré vuestras heridas!', '¡Horda, a mí! ¡Sanaré vuestras heridas!', 28153),
(151159, 'esES', '', '¡Estoy herida!', 28153),
(151158, 'esES', '', '¡Remiéndame!', 28153),
(151157, 'esES', 'Que la Madre Tierra nos guíe.', 'Que la Madre Tierra nos guíe.', 28153),
(151156, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(151155, 'esES', '', 'No te quedes ahí mirando, ¡ayúdame!', 28153),
(151154, 'esES', '', '¡Ayúdame!', 28153),
(151153, 'esES', '', '¡En guardia!', 28153),
(151152, 'esES', '', '¡Que ardan!', 28153),
(151151, 'esES', '', '¡Fuego!', 28153),
(151150, 'esES', '', 'Espera aquí.', 28153),
(151149, 'esES', '', '¡No te muevas!', 28153),
(151148, 'esES', '', '<Applause sounds>', 28153),
(151147, 'esES', '', '<Yawning sound>', 28153),
(151146, 'esES', '', '<Short cheer--Wooooo!>', 28153),
(151145, 'esES', '', '<Slightly longer cheer--Woohoo!>', 28153),
(151144, 'esES', '', '<Chicken sounds>', 28153),
(151143, 'esES', '', '<Crying sounds>', 28153),
(151142, 'esES', '', '<Crying sounds, variant>', 28153),
