(151113, 'esES', '¿Estas son las alimañas, Reid? Pon fin a esto de inmediato.', '', 28153),
(151112, 'esES', '', 'Mi arma requiere dos manos.', 28153),
(151111, 'esES', '', 'Esa facultad no está lista.', 28153),
