(151107, 'esES', '', 'Esa bolsa está llena.', 28153),
(151106, 'esES', '', 'No puedo hacer eso aquí.', 28153),
(151105, 'esES', '', 'No puedo deshacerme de eso.', 28153),
(151104, 'esES', '', 'Eso está ligado a mí.', 28153),
