(151085, 'esES', '', 'Necesito un objetivo primero.', 28153),
(151084, 'esES', '', 'Necesito un objetivo.', 28153),
(151083, 'esES', '', 'No puedo hacer eso.', 28153),
(151082, 'esES', '', 'Necesito permiso primero.', 28153),
(151081, 'esES', '', 'No puedo atacar a ese objetivo.', 28153),
(151080, 'esES', '', 'No se puede atacar.', 28153),
(151079, 'esES', '', 'Mi inventario está lleno.', 28153),
(151078, 'esES', '', 'No puedo llevar más.', 28153),
(151077, 'esES', '', 'Eso está bloqueado.', 28153),
(151076, 'esES', '', 'No puedo llevar más de eso.', 28153),
(151075, 'esES', '', 'Aún no puedo usar ese objeto.', 28153),
(151074, 'esES', '', 'Aún no está a punto.', 28153),
(151073, 'esES', '', 'Este objeto aún se está recargando.', 28153),
(151072, 'esES', '', 'Me falta furia.', 28153),
(151071, 'esES', '', 'Tengo poca furia.', 28153),
(151070, 'esES', '', 'Me falta dolor.', 28153),
(151069, 'esES', '', 'Tengo poco dolor.', 28153),
(151068, 'esES', '', 'Eso no es una bolsa.', 28153),
(151067, 'esES', '', 'No tengo los fondos necesarios.', 28153),
(151066, 'esES', '', 'Está fuera de mis posibilidades.', 28153),
(151065, 'esES', '', 'Demasiado caro.', 28153),
(151064, 'esES', '', 'No se puede unir a este grupo.', 28153),
(151063, 'esES', '', 'No me queda munición.', 28153),
(151062, 'esES', '', 'Me falta energía.', 28153),
(151061, 'esES', '', 'No tengo suficiente energía.', 28153),
(151060, 'esES', '', 'Me hace falta maná.', 28153),
(151059, 'esES', '', 'Tengo poco maná.', 28153),
(151058, 'esES', '', 'Necesito maná.', 28153),
(151057, 'esES', '', 'No tengo suficiente ira.', 28153),
(151056, 'esES', '', 'Me hace falta más ira.', 28153),
(151055, 'esES', '', 'Demasiado lejos.', 28153),
(151054, 'esES', '', 'Está fuera de mi alcance.', 28153),
(151053, 'esES', '', 'Debo acercarme.', 28153),
(151052, 'esES', '', 'No podemos invitar a nadie más.', 28153),
(151051, 'esES', '', 'No puedo beber más ahora mismo.', 28153),
(151050, 'esES', '', 'Aún no tengo esa facultad.', 28153),
(151049, 'esES', '', 'Aún no puedo utilizar eso.', 28153),
(151047, 'esES', '', 'Ese hechizo aún no está listo.', 28153),
(151046, 'esES', '', 'No puedo lanzar ese hechizo aún.', 28153),
(151045, 'esES', '', 'Se está recargando.', 28153),
(151044, 'esES', 'Tendría que... ¡Deja que les dé una lección!', '', 28153),
(151043, 'esES', 'Ehto no lo vi... en mih visioneh...', 'Eso... ehtaba muy afilado...', 28153),
(151042, 'esES', '¡Quiero a $gese:esa; inútil fuera de mi partida!', '', 28153),
(151041, 'esES', '¡Venga, tíos, que puedo pagar!', '', 28153),
(151040, 'esES', 'Antes de adentrarnos en él, tenemos que averiguar qué traman estos trols y cómo detenerlos.', '', 28153),
(151039, 'esES', 'Aunque me temo que nos esperan otros peligros en lo más profundo del templo.', '', 28153),
(151038, 'esES', '¡Buen trabajo! Esa bestia ya no dará problemas.', '', 28153),
(151037, 'esES', 'Y parece que no somos los únicos que las buscan.', '', 28153),
(151036, 'esES', 'Sí, este es el lugar. Siento el poder de esas reliquias en mis huesos.', '', 28153),
(151034, 'esES', '', '¡Eh, tú! Mis amigos me dan por muerta. ¿Me echas una mano?', 28153),
(151031, 'esES', '', 'Mmmm... Fascinante.', 28153),
(151030, 'esES', '¡Aprende a hacer tu propia comida! ¡Nunca te fíes de un cocinero flacucho!', '', 28153),
(151029, 'esES', 'Loh loa... me llaman...', 'Pura... suerte...', 28153),
(151028, 'esES', 'La Horda... pervive...', 'La Horda... ganará...', 28153),
(151027, 'esES', 'Bwonsamdi, acógeme...', 'Bwonsamdi, acógeme...', 28153),
(151026, 'esES', '¡Idiotasss! ¿Cómo podéisss caer ante un loa sssin ssseguidores y con un templo en ruinasss? ¡Dadle muerte!', '', 28153),
(151025, 'esES', 'Bwonsamdi, acógeme...', 'Veo... el otro lado...', 28153),
(151024, 'esES', 'Ahí te va algo de mal juju.', 'Mal juju en camino.', 28153),
(151023, 'esES', 'Así sí. Son órdeneh de la Jefa de Guerra.', 'Así sí. Son órdeneh de la Jefa de Guerra.', 28153),
(151022, 'esES', '¡No te muevah!', 'Ehto no hay quien lo ehquive.', 28153),
(151021, 'esES', '¿Qué tenemoh aquí? ¿Unoh humanoh débileh y lihtoh pa ser masacradoh?', '¿Qué tenemoh aquí? ¿Unoh humanoh débileh y lihtoh pa ser masacradoh?', 28153),
(151020, 'esES', 'Razdunk dice que no deberías estar aquí, $gpipiolo:pipiola;.', '', 28153),
(151019, 'esES', 'Razdunk te manda recuerdos.', '', 28153),
(151018, 'esES', '¡Bah! ¡Venga, me muero de hambre!', '', 28153),
(151017, 'esES', 'Mis hermanos y hermanas una vez cuidaron de esta tierra como iguales de los árboles. Esa era pasó hace mucho tiempo.\n\nAlgunos de nosotros no hemos olvidado ese camino.\n\nLa Arboleda Copacinérea era uno de nuestros santuarios. Un refugio de la corrupción que lentamente se extiende por el Bosque Carmesí.\n\nCon la infestación que crece en sus sombras, parece que su era también ha acabado. Ahora observo cómo se marchita y pervive solo en los recuerdos de aquellos a los que alimentó.', '', 28153),
(151016, 'esES', '¡Que loh loa guíen mi hacha!', 'Te voy a mandar con Bwonsamdi.', 28153),
(151015, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(151014, 'esES', '¿Le pasa algo malo a la arboleda?', '¿Le pasa algo malo a la arboleda?', 28153),
(151013, 'esES', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t ¡G\'huun invoca las |cFFFF0404|Hspell:267509|h[Mil Fauces]|h|r para que lo ayuden!', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t ¡G\'huun invoca las |cFFFF0404|Hspell:267509|h[Mil Fauces]|h|r para que lo ayuden!', 28153),
(151011, 'esES', '', 'Aunque tardaré un poco en recuperar todo mi poder, la maldición que me impedía volver ya no existe.', 28153),
(151010, 'esES', '', 'Tenéis toda mi gratitud.', 28153),
(151009, 'esES', 'Un momento, ¿quiénes son esos intrusos? ¡Están corrompiendo a Sethraliss!', '', 28153),
(151008, 'esES', 'Envíame al campo de batalla.', 'Envíame al campo de batalla.', 28153),
(151007, 'esES', 'Su sagrario debería estar ahí delante.', '', 28153),
(151006, 'esES', 'De no ser por ella, el mundo se habría sumido en el caos.', '', 28153),
(151005, 'esES', 'Yo presencié cuando Sethraliss se sacrificó para detener a Mythrax.', '', 28153),
(151003, 'esES', 'Incluso desde aquí puedo oír las raíces del Bosque Carmesí clamar pidiendo sangre. Nunca pensé que su corrupción podría llegar tan lejos.', '', 28153),
(151002, 'esES', '¿Tenéis que revisar si todos los cadáveres tienen botín? ¡El objetivo es Sethraliss!', '', 28153),
(151001, 'esES', 'Bueno, veo que se os da bien la destrucción.', '', 28153),
(151000, 'esES', 'Ahora debemos actuar rápido. Siento que una oscuridad creciente se hace con el templo.', '', 28153),
(150999, 'esES', 'Os agradezco que hayáis eliminado esa infección.', '', 28153),
(150998, 'esES', 'Se sacrificó para detener a Mythrax, pero, con su muerte, las selvas de Vol\'dun se volvieron arena.', '', 28153),
(150997, 'esES', 'En este templo yace Sethraliss, una poderosa loa que protegió a mi pueblo de la destrucción hace tiempo.', '', 28153),
(150996, 'esES', '', '¡Sí! ¡Dales bien fuerte!', 28153),
(150995, 'esES', '', '¡Apuesto diez de oro por el grandote!', 28153),
(150993, 'esES', 'La hora de su renacimiento ha pasado, y temo que haya algo que le impida regresar.', '', 28153),
(150990, 'esES', 'Estás abandonando la zona designada y se te expulsará del vehículo.', 'Estás abandonando la zona designada y se te expulsará del vehículo.', 28153),
(150989, 'esES', 'Un breve respiro. Con suerte será lo bastante largo para que nos reagrupemos y nos recuperemos.', '', 28153),
(150988, 'esES', '¡Rápido! ¡Nuestros marineros necesitan ayuda! ¡Están heridos y la Horda avanza!', '', 28153),
(150987, 'esES', 'Que la marea te sea favorable.', '', 28153),
(150986, 'esES', '¡Repollos frescos!', '', 28153),
(150985, 'esES', 'Mantén tu rumbo firme.', '', 28153),
(150984, 'esES', 'Que el viento te sea favorable.', '', 28153),
(150983, 'esES', 'Oh, hola.', '', 28153),
(150982, 'esES', '¿Qué necesitas?', '', 28153),
(150981, 'esES', 'Hola.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'esES', '¡Es hora de una buena tunda!', '', 28153),
(150979, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(150978, 'esES', '¡Es imposible detener a la Horda!', '¡Es imposible detener a la Horda!', 28153),
(150977, 'esES', 'Somos la punta de la lanza...', 'Somos la punta de la lanza...', 28153),
(150976, 'esES', '', 'Ugalazul bwrxil\' qu rax.', 28153),
(150975, 'esES', '¿Derrotado por... semejante gusano?', '¿Derrotada por... semejante gusano?', 28153),
(150974, 'esES', 'La Horda... prevalecerá...', 'Estas tierras... serán nuestras...', 28153),
(150973, 'esES', 'Somos la punta de la lanza...', 'Muero... con honor...', 28153),
(150972, 'esES', 'Nadie puede... detenernos...', 'Escoria... despreciable...', 28153),
(150971, 'esES', '', '¡El abisssmo se... tragará esssta tierra!', 28153),
(150970, 'esES', '', 'No... ¡Le he fallado!', 28153),
(150969, 'esES', '', '¡Maldigo a tu essspecie!', 28153),
(150968, 'esES', '', 'Agua... ¡Llévame contigo!', 28153),
(150967, 'esES', '', '¡Mi vida por... nuessstra reina!', 28153),
(150966, 'esES', '', 'Se alza... de lasss profundidadesss...', 28153),
(150965, 'esES', '', 'Nuessstra reina prevalecerá...', 28153),
(150964, 'esES', 'Ah, ¡voy enseguida! Por favor, ¡no se lo digas a nadie!', 'Ah, ¡voy enseguida! Por favor, ¡no se lo digas a nadie!', 28153),
(150963, 'esES', 'Me servirás como rival.', 'Me servirás como rival.', 28153),
(150962, 'esES', '¡No metas las narices donde no te llaman!', '¡No metas las narices donde no te llaman!', 28153),
(150961, 'esES', '¡El abisssmo se... tragará esssta tierra!', '', 28153),
(150960, 'esES', 'No... ¡Le he fallado!', '', 28153),
(150959, 'esES', '¡Maldigo a tu essspecie!', '', 28153),
(150958, 'esES', 'Agua... ¡Llévame contigo!', '', 28153),
(150957, 'esES', '¡Mi vida por... nuessstra reina!', '', 28153),
(150956, 'esES', 'Nadie... puede detenerla...', '', 28153),
(150955, 'esES', 'Se alza... de lasss profundidadesss...', '', 28153),
(150954, 'esES', 'Nuessstra reina prevalecerá...', '', 28153),
(150953, 'esES', '', 'Impedir que se ehtablezcan aquí protege nuehtro hogar. Que Gonk te recompense velozmente por llevar a cabo su venganza.', 28153),
(150952, 'esES', '', 'Permitir que la Alianza se haga con una posición en Zandalar sería una calamidad. Recupera lo que puedah, pero no tengah piedad con elloh.', 28153),
(150951, 'esES', 'Si quieres que algo salga bien...', '', 28153),
(150950, 'esES', 'Tu muerte me otorgará honor.', '¡Ha llegado tu final!', 28153),
(150949, 'esES', '¡Matadlos a todos!', '¡Lok\'tar!', 28153),
(150948, 'esES', 'Me servirás como rival.', '¡No toméis prisioneros!', 28153),
(150947, 'esES', '¡Por... la Horda!', '¡Por... la Horda!', 28153),
(150946, 'esES', '¡Oh, qué preciosidad! Hoy te has ganado la paga.', '', 28153),
(150945, 'esES', '', '¡¿Cómo osssáisss interferir en misss asssuntosss?! ¡¿Qué osss hace pensssar que sssoisss rival para mí?!', 28153),
(150944, 'esES', 'Preparaos. ¡Esta bestia será una pieza digna de cobrar!', '', 28153),
(150943, 'esES', '¡Nos ha atraído a su guarida!', '', 28153),
(150942, 'esES', 'Mm... El rastro se adentra más aún en este paso maloliente.', '', 28153),
(150941, 'esES', 'La perla no está aquí. Puede que el esbirro de Azshara fuera más listo de lo que parecía.', '', 28153),
(150940, 'esES', '¡Tu cabeza adornará pronto mis paredes!', '', 28153),
(150939, 'esES', 'Despídete de tu Reina, porque tu vida acabará aquí.', '', 28153),
(150938, 'esES', '¡¿Intrusos?! ¡Lanzaré vuestros cuerpos a las negras profundidades para su tormento eterno!', '', 28153),
(150937, 'esES', '¡El loa esss demasssiado poderossso! ¡Volved al océano! La batalla essstá perdida.', '', 28153),
(150936, 'esES', '¡Dessstruid el templo! Romped lasss piedrasss y derribad lasss essstatuasss. ¡Todosss ssse arrodillarán ante nuessstra Reina!', '', 28153),
(150935, 'esES', '¡Los poderes oscuros no os servirán de nada!', '', 28153),
(150934, 'esES', 'Bienvenidos, intrusos. ¡Habéis llegado justo a tiempo para ver lo que es el verdadero poder!', '', 28153),
(150933, 'esES', 'Eso ha estado bien, pero la verdadera presa se ha adentrado en el altar.', '', 28153),
(150932, 'esES', '', '¡La Reina ordena que muerasss!', 28153),
(150931, 'esES', '', '¡Gloria a Azssshara!', 28153),
(150930, 'esES', '', '¡Nuessstro dessstino ssse acerca!', 28153),
(150929, 'esES', '', '¡Mía ssserá la gloria de tu muerte!', 28153),
(150928, 'esES', '', '¡Nadie ssse opondrá a la reina Azssshara!', 28153),
(150927, 'esES', '', '¡El Anillo de las Mareasss esss nuessstro!', 28153),
(150926, 'esES', '', '¡No puedesss comprender nuessstro poder!', 28153),
(150925, 'esES', 'Calla, no llevah zapatoh.', '', 28153),
(150924, 'esES', '', '¿Y si fuera solo uno? Me vendrían bien unoh zapatoh nuevoh.', 28153),
(150923, 'esES', '¡Paciencia, hermanita!', '', 28153),
(150922, 'esES', '', 'No se darán cuenta. Nadie dice que haya que irrumpir a lo loco en el campamento, ¡pero no noh iría mal acabar con unoh cuantoh!', 28153),
(150921, 'esES', '¡La Reina ordena que muerasss!', '', 28153),
(150920, 'esES', '¡Gloria a Azssshara!', '', 28153),
(150919, 'esES', '¡Nuessstro dessstino ssse acerca!', '', 28153),
(150918, 'esES', '¡Mía ssserá la gloria de tu muerte!', '', 28153),
(150917, 'esES', '¡Nadie ssse opondrá a la reina Azssshara!', '', 28153),
(150916, 'esES', '¡El Anillo de las Mareasss esss nuessstro!', '', 28153),
(150914, 'esES', 'Tenemoh que quedarnoh aquí. Si te vah y haceh que noh maten, no habrá nadie que informe.', '', 28153),
(150913, 'esES', '¡No puedesss comprender nuessstro poder!', '', 28153),
(150912, 'esES', '¡¡¡Mis repollos!!!', '', 28153),
(150911, 'esES', 'Hay que afanar otro grifo. ¡Monta!', '', 28153),
(150908, 'esES', 'El trabajo de Bellaco no es muy glamuroso, pero se paga bien.', '', 28153),
(150907, 'esES', 'Tenemos un gran pedido de sillas para grifos, pero necesitamos más pelaje. ¡A trabajar!', '', 28153),
(150906, 'esES', 'Cuantos menos haya allá arriba, menos bajarán aquí. ¡Buen trabajo!', '', 28153),
(150905, 'esES', 'Cada vez hay más wendigos en el glaciar. ¡Ve allí y haz algo al respecto!', '', 28153),
(150904, 'esES', 'Con el poder de la perla de las mareas, nuestras flotas serán imparables.', '', 28153),
(150903, 'esES', '', '¿Qué te piensas, que estoy hecha de oro?', 28153),
(150902, 'esES', 'Lo siento mucho...', '', 28153),
(150901, 'esES', '', '¡Patán estúpido! ¡Costaban un ojo de la cara!', 28153),
(150900, 'esES', 'Gracias, héroes. Habéis devuelto la esperanza a la gente de Kul Tiras.', '', 28153),
(150899, 'esES', 'Siento cómo la presencia oscura retrocede. El santuario volverá a la normalidad.', '', 28153),
(150898, 'esES', '¡Ignorad los susurros! ¡Este horror quiere doblegar vuestras almas!', '', 28153),
(150897, 'esES', '¡Por la madre de las mareas!', '', 28153),
(150896, 'esES', 'Cuidado, héroes, un mal oculto vaga en la oscuridad. Debemos perseverar para limpiar el santuario de su influencia.', '', 28153),
(150895, 'esES', 'Algo no va bien. La oscuridad aún infecta este lugar.', '', 28153),
(150894, 'esES', 'Has dado la espalda a la marea, maestro, y ahora te hundes bajo ella.', '', 28153),
(150893, 'esES', 'Entonces arrojaré vuestros cadáveres a las profundidades abisales para que se pudran eternamente.', '', 28153),
(150892, 'esES', 'Nunca.', '', 28153),
(150891, 'esES', 'Por última vez, únete a mí... o muere.', '', 28153),
(150890, 'esES', '¡Insensato! Debemos volver al mar, ¡y la reina Azshara nos otorgará el poder para conseguirlo!', '', 28153),
(150889, 'esES', '¡Maestro! ¡Detén esta locura! ¡La flota de Kul Tiras no puede caer en la oscuridad!', '', 28153),
(150888, 'esES', '', 'Parece que tienesss visssita, lord Canto Tormenta.', 28153),
(150887, 'esES', '', 'Muehtra rehpeto y deja que hable él... Y puede que no acabe tirándote de lo alto de la pirámide.', 28153),
(150886, 'esES', 'La flota de Kul Tiras ya casi es tuya, mi Reina.', '', 28153),
(150885, 'esES', 'Mar al mar y cenizas a las cenizas. Que vuestras almas encuentren corrientes favorables.', '', 28153),
(150884, 'esES', '¡Rápido, héroes! ¡Detenedlos antes de que perdamos la flota!', '', 28153),
(150883, 'esES', 'Discos titánicos activados. Inicio de protocolo de corrupción.', 'Discos titánicos activados. Inicio de protocolo de corrupción.', 28153),
(150882, 'esES', 'Discos titánicos activados. Iniciando protocolo de engaño.', 'Discos titánicos activados. Iniciando protocolo de engaño.', 28153),
(150881, 'esES', '', 'Una vez completado el ritual, ¡la flota de Kul Tiras pertenecerá a la reina Azshara!', 28153),
(150880, 'esES', 'Bienvenido, hermano Pike. Llegas justo a tiempo para presenciar nuestra victoria.', '', 28153),
(150879, 'esES', 'Canto Tormenta ha corrompido este lugar sagrado. Debemos avanzar y deshacer su perversa obra.', '', 28153),
(150878, 'esES', '¿Voces?', '¿Voces?', 28153),
(150877, 'esES', 'Pero cuidado, una presencia oscura nos sigue vigilando.', '', 28153),
(150876, 'esES', 'Debemos purificar el santuario de la maldad de lord Canto Tormenta.', '', 28153),
(150875, 'esES', '', '¡Maehtro! ¡No me abandoneh! ¡Nooo!', 28153),
(150874, 'esES', '', '¿De verdad pensabah que resihtiríah ante el poder de G\'huun? ¡Pagaráh por tu arrogancia!', 28153),
(150873, 'esES', '¡Hay voces en el barro!', '¡Hay voces en el barro!', 28153),
(150872, 'esES', '', 'Ehtamoh rotoh.\n\nLa luz de Rezan noh ha abandonado. Solo unoh pocoh de loh que seguían al gran rey de loh loa tienen aún algún tipo de poder, e incluso elloh ehtán bajo sohpecha.\n\nNuehtra vida era pura devoción. Ahora, ¿en quién noh convertimoh?', 28153),
(150871, 'esES', '¡Es hora de hacer algunas mejoras!', '', 28153),
(150870, 'esES', 'Vale, se acabó el jugar limpio.', '', 28153),
(150869, 'esES', '¡Excelente! Nuestros soldados harán buen uso de esos suministros. ¡Bien hecho!', '', 28153),
(150868, 'esES', 'Nuestros exploradores informan de que un carguero Zandalari ha sido asaltado por una banda de trols de sangre. Mátalos y hazte con esos suministros.', '', 28153),
(150867, 'esES', '¡Atención, parece que viene alguien a pedir algo!', '', 28153),
(150866, 'esES', '¡Sí! ¡Búscate un estilista!', '', 28153),
(150865, 'esES', '', '¡$n! ¡Oye, $n! ¡Tenemos una misión para ti!', 28153),
(150864, 'esES', '¡Salta!', '¡Salta!', 28153),
(150863, 'esES', 'No puedeh ehconderte de Bwonsamdi.', '', 28153),
(150862, 'esES', 'Mmm... ¿A qué hueleh? Ah, sí... A cazador de demonioh.', '', 28153),
(150861, 'esES', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', 28153),
(150860, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan la Senda del Valor!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan la Senda del Valor!', 28153),
(150859, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan Finca Nueva!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan Finca Nueva!', 28153),
(150858, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan el Círculo de los Elementos!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan el Círculo de los Elementos!', 28153),
(150857, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan Nido Alto!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan Nido Alto!', 28153),
(150856, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan el Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Atacan el Cruce Redilnorte!', 28153),
(150855, 'esES', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Atacan la Mina Mostacho Seco!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Atacan la Mina Mostacho Seco!', 28153),
(150854, 'esES', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Atacan Cumbre Destral!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Atacan Cumbre Destral!', 28153),
(150853, 'esES', '¡Tenemos que llegar hasta nuestros exploradores de avanzada y acabar con esa plaga voladora cuanto antes!', '¡Tenemos que llegar hasta nuestros exploradores de avanzada y acabar con esa plaga voladora cuanto antes!', 28153),
(150852, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido la Senda del Valor!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido la Senda del Valor!', 28153),
(150851, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Finca Nueva!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Finca Nueva!', 28153),
(150850, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de los Elementos!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de los Elementos!', 28153),
(150849, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Nido Alto!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Nido Alto!', 28153),
(150848, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Cruce Redilnorte!', 28153),
(150847, 'esES', 'No ehtáh soñando, colega.', '', 28153),
(150846, 'esES', 'Loh ehpírituh ahora sí que ehtán contigo.', '', 28153),
(150845, 'esES', 'Caballero de la Muerte, ¿Vieneh a visitar mi portón de la muerte?', '', 28153),
(150844, 'esES', '¡Estas tierras serán las siguientes en caer!', '¡Estas tierras serán las siguientes en caer!', 28153),
(150843, 'esES', '¡Nadie puede detener el avance de las arenas!', '¡Nadie puede detener el avance de las arenas!', 28153),
(150842, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Hemos perdido la Mina Mostacho Seco!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Hemos perdido la Mina Mostacho Seco!', 28153),
(150841, 'esES', '¡Ja! Eso no ha ido \"rodado\" ¿verdad?', '', 28153),
(150840, 'esES', '¡Lo dominamos todo!', '¡Lo dominamos todo!', 28153),
(150839, 'esES', '¡Te exterminaremos como a un insecto!', '¡Te exterminaremos como a un insecto!', 28153),
(150838, 'esES', 'Fingir muerte no funciona así, colega.', '', 28153),
(150837, 'esES', '¡Por el Emperador!', '¡Por el Emperador!', 28153),
(150836, 'esES', 'Creo que hah ido hacia la luz equivocada, colega.', '', 28153),
(150835, 'esES', 'Esa trahlación no te ha llevado muy lejoh, ¿eh?', '', 28153),
(150834, 'esES', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Cumbre Destral!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Cumbre Destral!', 28153),
(150833, 'esES', '¡Sí! ¡Tiene muy mal aspecto, pero claramente es $gdistinto:distinta;!', '', 28153),
(150832, 'esES', '', 'Vaya, sí que parece $gdistinto ese aventurero:distinta esa aventurera;.', 28153),
(150831, 'esES', 'Creo que es $gotro de esos \"héroes\":otra de esas \"heroínas\";. ¡Huele como si alguien se hubiera metido en el fuego!', '', 28153),
(150830, 'esES', '', '¡¿A qué demonios huele?!', 28153),
(150829, 'esES', '', '¡Waldorf, eso no es un jabaespín, solo es $gotro de esos \"héroes\":otra de esas \"heroínas\";!', 28153),
(150828, 'esES', '¡Ja, ja! Tanta armadura pa nada...', '', 28153),
(150827, 'esES', '¡Oye, Statler, dame mi espada! ¡Se acerca un jabaespín por el camino!', '', 28153),
(150826, 'esES', 'Ooh, ¿has perdido la piedra de alma?', '', 28153),
(150825, 'esES', '', '¡Tienes razón! ¡Le queda peor que mal!', 28153),
(150824, 'esES', '¿Ves la ropa que lleva $n? ¡No le queda mal!', '', 28153),
(150823, 'esES', '¡Ah! ¿Vieneh a pasar el rato con Bwonsamdi?', '', 28153),
(150822, 'esES', '¡Ja! Eso sí que ha sido una muerte impresionante.', '', 28153),
(150821, 'esES', 'Diría que tiene mal aspecto... ¡pero creo que su aspecto siempre es así de malo!', '', 28153),
(150820, 'esES', '', 'Vaya, vaya, vaya. ¡Mira quién está aquí! ¡Es $n!', 28153),
(150819, 'esES', '', 'Sí, ¿de dónde has sacado ese equipo? ¿Se lo has quitado a un trogg?', 28153),
(150818, 'esES', '¡Oye, Statler, no te pierdas el equipo que lleva $n!', '', 28153),
(150817, 'esES', '¡Creo que sí! ¡Uf, huele peor de lo que imaginaba! ¡Ja!', '', 28153),
(150816, 'esES', '', '¡Oye, Waldorf! ¿Es $gese el \"famoso\":esa la \"famosa\"; $r que apareció con Jaina?', 28153),
(150815, 'esES', '', '¡Sí! ¡Apestas! ¡Ja, ja, ja!', 28153),
(150814, 'esES', '¡Eh, tú! ¡Sí, tú, $gel:la; $r de la cara rara!', '', 28153),
(150813, 'esES', '¡He visto caballos con mejor transfiguración!', '', 28153),
(150812, 'esES', '', '¡Oye! ¡$n! ¿Te parece que ese yelmo combina con esas botas?', 28153),
(150811, 'esES', 'Quería saber algo más.', 'Quería saber algo más.', 28153),
(150810, 'esES', '', 'Los antiguos Drust. Su odio por la gente de Kul Tiras trascendió sus vidas mortales. Hasta sus ecos del más allá aborrecen nuestra misma existencia.\n\nSiento pena por el necio que los haya hecho venir.', 28153),
(150809, 'esES', '¿Muertos vengativos?', '¿Muertos vengativos?', 28153),
(150808, 'esES', '¡Seréis erradicados!', '', 28153),
(150807, 'esES', '', 'La magia que usan esas brujas es antigua y profundamente corrupta. Han retorcido la vida salvaje para que las sirva y han perturbado el equilibrio. Sus miserables creaciones albergan espíritus de muertos vengativos.', 28153),
(150806, 'esES', '', '¡La caza eh un placer y la venganza una satihfacción!', 28153),
(150805, 'esES', '', 'Ehtoh traidoreh mataloa aún tratan de mancillar el Templo de Rezan. El viejo K\'zlotec leh enseñará lo que pasa cuando le ehcupeh a la cara al loa de loh Reyeh.', 28153),
(150804, 'esES', 'Naza bul rexil qalic ul\'.', '', 28153),
(150803, 'esES', '¿Qué le ha pasado al bosque?', '¿Qué le ha pasado al bosque?', 28153),
(150802, 'esES', '¡Ca\' lish!', '', 28153),
(150801, 'esES', '', 'Puede que lo encuentres en una de las cuevas cercanas. Buena suerte, $n.', 28153),
(150800, 'esES', '', 'Acechaverde quedó debilitado, pero solo es cuestión de tiempo que vuelva a la caza.', 28153),
(150799, 'esES', '¡Ug\' bwafa qilikx za!', '', 28153),
(150798, 'esES', 'Siempre tendrás cobijo entre estas paredes.', '', 28153),
(150797, 'esES', 'Pobre... ¿Necesitah algo de ayuda del viejo Bwonsamdi?', '', 28153),
(150796, 'esES', 'Los ranishus han envenenado a mis crías. Están débiles... Y se mueren. Usa mi poder para salvarlas, como hiciste conmigo.', '', 28153),
(150795, 'esES', 'Hul bala miz rilakich...', '', 28153),
(150794, 'esES', 'Vaya. No te ehperaba en mi reino tan pronto.', '', 28153),
(150793, 'esES', '¡Lok\'tar ogar!', '¡Lok\'tar ogar!', 28153),
(150792, 'esES', '¡POR LA HORDA!', '¡POR LA HORDA!', 28153),
(150791, 'esES', '¡Soy superior!', '', 28153),
(150790, 'esES', 'Soldados de la Horda, ¡preparad vuestras hojas! ¡Hoy marchamos contra los kaldorei!', '', 28153),
(150789, 'esES', 'Déjame adivinar... ¿Ehtáh con el agua al cuello?', '', 28153),
(150788, 'esES', '¡Il qul zerakish!', '', 28153),
(150787, 'esES', 'Ya debería estar arreglado. Ve a ver a Sylvanas en Orgrimmar para comenzar tu épica aventura.', '', 28153),
(150786, 'esES', 'Empecé Nazmir pero no puedo empezar Zuldazar. Arréglame, por favor.', 'Empecé Nazmir pero no puedo empezar Zuldazar. Arréglame, por favor.', 28153),
(150785, 'esES', '¿Qué necesitas?', '', 28153),
(150784, 'esES', 'Nos resultaría provechoso que siguiera así...', '', 28153),
(150783, 'esES', 'No des tregua a los que muestren lealtad a los Crestavía y recibirás una recompensa.', '', 28153),
(150781, 'esES', 'Reúne a tu mejor tripulación y zarpad hacia el Muelle Mercante. Desde allí, asaltad, saquead y expoliad sus tierras para dejarlos sin suministros y llenar nuestras arcas.', '', 28153),
(150779, 'esES', 'Capitán Puñoplomo, ha llegado a mis oídos que la casa Crestavía está entrando en decadencia.', '', 28153),
(150778, 'esES', '¿Por qué no estás en tu puesto?', '¿Por qué no estás en tu puesto?', 28153),
(150777, 'esES', 'Deseo escoger a Kimbul como mi loa.', 'Deseo escoger a Kimbul como mi loa.', 28153),
(150776, 'esES', '¡El mismísimo Corazón de Azeroth!', '', 28153),
(150775, 'esES', '<Este santuario se construyó como tributo a Kimbul, el señor de las bestias>.', '<Este santuario se construyó como tributo a Kimbul, el señor de las bestias>.', 28153),
(150773, 'esES', '¿Sí?', '¿Sí?', 28153),
(150772, 'esES', 'Puede que yo sea su portavoz, pero tú eres su adalid. Y necesita que luches por ella.', '', 28153),
(150771, 'esES', 'Azeroth te llama, adalid. Y te ofrece un don... Nacido de su propia esencia.', '', 28153),
(150770, 'esES', '¡Libre! ¡Debemoh ponernoh a salvo en el interior del templo!', '¡Libre! ¡Debemoh ponernoh a salvo en el interior del templo!', 28153),
(150769, 'esES', '¿Qué...? ¿Qué me ha pasado?', '¿Qué...? ¿Qué me ha pasado?', 28153),
(150768, 'esES', '', '¡G\'huun! ¡Otórgame poder!', 28153),
(150767, 'esES', 'Te debo una en el otro lado, colega.', 'Te debo una en el otro lado, colega.', 28153),
(150766, 'esES', '', '¡El fin se acerca!', 28153),
(150765, 'esES', '', '¡Quiero oíroh suplicar!', 28153),
(150764, 'esES', '', '¡Todoh servirán al maehtro!', 28153),
(150763, 'esES', '¡Por fin libre de esos malditos huesos!', '¡Por fin libre de esos malditos huesos!', 28153),
(150762, 'esES', 'Creo que eh el momento de aligerar un poco lah arcah de Harlan Sweete.', '', 28153),
(150761, 'esES', 'Discos titánicos activados. Iniciando protocolo de caos.', 'Discos titánicos activados. Iniciando protocolo de caos.', 28153),
(150760, 'esES', '¡Devolveré lo que he robado! ¡Lo juro!', '¡Devolveré lo que he robado! ¡Lo juro!', 28153),
(150759, 'esES', 'Eh el fin de Harlan Sweete. Ahora loh mareh noh pertenecen.', '', 28153),
(150758, 'esES', '¡Aaaah!', '¡Aaaah!', 28153),
(150757, 'esES', '¡Ha sido un robo con todas las de la ley!', '¡Ha sido un robo con todas las de la ley!', 28153),
(150756, 'esES', '¡Ja! ¡Sabía que eraih una apuehta segura!', '', 28153),
(150755, 'esES', '¡Dispersaos!', '¡Dispersaos!', 28153),
(150754, 'esES', '¡Ah! ¡Socorro!', '¡Ah! ¡Socorro!', 28153),
(150753, 'esES', '¿Qué tal si reventamoh unoh cuantoh cráneoh a cambio de oro?', '', 28153),
(150752, 'esES', 'La ihla ehtará cerrada a cal y canto hahta que acabe la fiehta en el foso de lucha.', '', 28153),
(150750, 'esES', 'Bien hecho, aunque será máh complicado asesinar a Harlan.', '', 28153),
(150749, 'esES', 'Si conseguíh que oh inviten, será pan comido. Si irrumpíh ehpadah en mano pa matar a treh de loh capitaneh máh temibleh... lah cosah se complicarán. ¿Qué va a ser?', '', 28153),
(150748, 'esES', '¡Hahta loh peceh beben menoh que lah Ratah de Pantoque! Si conseguíh seguirle el ritmo a ehta recua, la capitana Eudora no dudará en invitaroh a la reunión.', '', 28153),
(150747, 'esES', 'A loh Camorrihtah Dientenegro leh encanta curtirse loh nudilloh en una pelea. Si conseguíh arrancarleh un par de dienteh, el capitán Raoul oh invitará a la reunión.', '', 28153),
(150746, 'esES', 'He oído que loh capitaneh se van a reunir. Eh nuehtra oportunidad pa cortarle todah lah cabezah a ehta hidra de una vez.', '', 28153),
(150745, 'esES', 'Esta guerra no se va a ganar sola. ¡Tenemos trabajo que hacer!', '', 28153),
(150744, 'esES', 'Y luego noh encargaremoh de Harlan pa siempre.', '', 28153),
(150743, 'esES', 'Así que ehte eh el plan: dejar secoh a los Aguacortada, tumbar a lah Ratah de Pantoque, aplahtar a loh Camorrihtah Dientenegro y dehmantelar a loh Marea de Hierro.', '', 28153),
(150742, 'esES', 'Si lo consigue, comandará una flota que pondrá en peligro nuehtroh intereseh.', '', 28153),
(150741, 'esES', 'Harlan quiere usar a loh Marea de Hierro pa reclutar a lah otrah tripulacioneh piratah.', '', 28153),
(150740, 'esES', 'Graciah por liberarme. Siento la llamada de Bwonsamdi dehde el interior del templo, vamoh.', 'Graciah por liberarme. Siento la llamada de Bwonsamdi dehde el interior del templo, vamoh.', 28153),
(150739, 'esES', 'Creía que sería un ehqueleto feo pa siempre. ¡Debo volver rápido al templo!', 'Creía que sería un ehqueleto feo pa siempre. ¡Debo volver rápido al templo!', 28153),
(150738, 'esES', 'Volver a Bwonsamdi... al templo... rápido...', 'Volver a Bwonsamdi... al templo... rápido...', 28153),
(150737, 'esES', 'Loh sentidoh que me quedan ehtán atrofiadoh por su repugnante ritual... Ayúdame a llegar a loh ehcaloneh del templo.', 'Loh sentidoh que me quedan ehtán atrofiadoh por su repugnante ritual... Ayúdame a llegar a loh ehcaloneh del templo.', 28153),
(150736, 'esES', '¡Graciah, colega! Me dehvanezco rápidamente, ayúdame a llegar al templo de Bwonsamdi, por favor.', '¡Graciah, colega! Me dehvanezco rápidamente, ayúdame a llegar al templo de Bwonsamdi, por favor.', 28153),
(150735, 'esES', '¿Qué tieneh ahí, alhaja? ¿Una baratija brillante pa Jani? Acércamela...', '', 28153),
(150734, 'esES', '¡Soy el único que sabe de matemáticas por aquí! Por eso vigilo los gastos y me aseguro de que todo el mundo se guarde las manos en los bolsillos correspondientes.', '', 28153),
(150733, 'esES', 'Los peones son el pilar sobre el que se apoya esta guerra.', '', 28153),
(150732, 'esES', 'Intenta volver de una pieza.', '', 28153),
(150731, 'esES', 'Cuidado con loh trolh de sangre.', '', 28153),
(150730, 'esES', 'Ándate con cuidado. ¡Te necesito con vida!', '', 28153),
(150729, 'esES', 'Tiempoh ohcuroh pa Zandalar.', '', 28153),
(150728, 'esES', 'Agh. Odio a loh trolh de sangre.', '', 28153),
(150727, 'esES', '¿Cómo vamoh a salir de ehta?', '', 28153),
(150726, 'esES', '¡Bah! La Horda tuvo su merecido. Llevaré este artilugio a Puesto de Arom, a ver si a alguien le sirve de algo. Buen trabajo.', '', 28153),
(150719, 'esES', 'Estoy listo para defender Zandalar.', 'Estoy lista para defender Zandalar.', 28153),
(150718, 'esES', '¡Por aquí! Nuestras fuerzas terrestres nos esperan abajo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'esES', '', 'El bosque grita de agonía. ¿Puedes oírlo?', 28153),
(150716, 'esES', '¡Volvemoh a casa!', '¡Volvemoh a casa!', 28153),
(150715, 'esES', '¡Veo que no hah necesitado mi ayuda! ¡Hemoh vuelto en cuanto hemoh podido!', '', 28153),
(150714, 'esES', 'Daryl y yo llevamos toda la vida viniendo a estos montes. Podemos sobrevivir aquí arriba mucho más tiempo que cualquiera de la Horda.', '', 28153),
(150713, 'esES', '¿Quieres volver a Zuldazar y que te maten allí o quedarte aquí y que te maten los raptores?', '¿Quieres volver a Zuldazar y que te maten allí o quedarte aquí y que te maten los raptores?', 28153),
(150712, 'esES', 'No voy a ir a Vol\'dun, ¿me oyeh? ¡Viviré mi vida en la ciudad!', '', 28153),
(150711, 'esES', '', '¡Tortugas frescas, Emma! ¡Ahora tienes que pagarme mi parte!', 28153),
(150710, 'esES', '¿Qué tienes ahí, alhaja? ¿Una baratija brillante para Jani? Acércamela...', '', 28153),
(150709, 'esES', '', '¡Xul krass qi\' UN skush!', 28153),
(150708, 'esES', '', '¡Skitsh qi\'uthik illith!', 28153),
(150707, 'esES', '', 'La sangre gotea entre las tablas del suelo.', 28153),
(150706, 'esES', '', '¿Por qué no os reunís conmigo en el sótano y admiráis la belleza de la muerte?', 28153),
(150705, 'esES', '', 'Vaya, parece que habéis masacrado a toda mi gente.', 28153),
(150704, 'esES', '<Ves la imagen de un trol joven que mira lo que parece ser un cortejo fúnebre. Tiene los ojos muy abiertos y parece inocente>.', '<Ves la imagen de un trol joven que mira lo que parece ser un cortejo fúnebre. Tiene los ojos muy abiertos y parece inocente>.', 28153),
(150703, 'esES', '¡Aléjate de la puerta! Aquí arriba corres peligro.', '¡Aléjate de la puerta! Aquí arriba corres peligro.', 28153),
(150702, 'esES', 'Kua\'fon te gruñe. ¡Vuelve con Raal o te tirará!', 'Kua\'fon te gruñe. ¡Vuelve con Raal o te tirará!', 28153),
(150701, 'esES', '', '¡Retuércete de agonía!', 28153),
(150700, 'esES', '', '¡Os voy a desgarrar el alma!', 28153),
(150699, 'esES', '', '¡Usar esa cosa hizo que se me pusiera el pelo verde!', 28153),
(150698, 'esES', '', '¡Tus gritos resonarán eternamente!', 28153),
(150697, 'esES', '', '¡Todo está bajo mi dominio!', 28153),
(150696, 'esES', '', 'Kiro, ¡aún están vivos! No podemos dejarlos así...', 28153),
(150695, 'esES', '¡Rápido! Hay que rapiñar todo lo que se pueda. Que los buitres se encarguen del resto.', '', 28153),
(150694, 'esES', 'Moriréis en estas dunas...', '', 28153),
(150693, 'esES', '¡Intrusoh!', '', 28153),
(150692, 'esES', 'General, haz tu parte y yo haré la mía.', '', 28153),
(150691, 'esES', 'Hay que darse prisa. Unoh entrometidoh visitan al Rey... Podría ser un problema.', '', 28153),
(150690, 'esES', '', '¡Había $gun:una; guardia en Tol Dagor $gclavadito:clavadita; a ti!', 28153),
(150689, 'esES', '', '¿Crees que podrías colarme en el banco de Boralus?', 28153),
(150688, 'esES', '', '¿Alguna vez te preocupa la radiación?', 28153),
(150687, 'esES', '', '¿Tienes alguna habilidad útil? ¿Se te da bien falsificar cosas o abrir cajas fuertes?', 28153),
(150686, 'esES', '', 'La tormenta ha cesado, y vuelvo a ser yo misma. Gracias.', 28153),
(150685, 'esES', '', 'Vuestras vidas no tuvieron sentido, y en la muerte os espera el olvido.', 28153),
(150684, 'esES', '', '¡Profanadores!', 28153),
(150683, 'esES', '', '¡Ayudadme y me encargaré de ellas!', 28153),
(150682, 'esES', '', 'El maleficio se ha roto, ¡pero las defensas del templo han despertado!', 28153),
(150681, 'esES', '', '¡Vuestro tormento no tendrá fin!', 28153),
(150680, 'esES', '¡Disfrutaré viendo cómo os freís!', '', 28153),
(150679, 'esES', '¡Morid, alimañas!', '', 28153),
(150678, 'esES', '¡Tajo arqueado!', '', 28153),
(150677, 'esES', '¡Amputar!', '', 28153),
(150676, 'esES', '¡Nos vemos!', '', 28153),
(150675, 'esES', '¡Frágil como el cristal!', '', 28153),
(150674, 'esES', '¡No esh que eshté ashushtado ni nada, esh sholo que no me da la gana!', '', 28153),
(150673, 'esES', '¡Nadie puede oponerse a nuestro imperio!', '', 28153),
(150672, 'esES', 'Por supuesto que puedo trepar allí. ¡No soy una nenaza!', '', 28153),
(150671, 'esES', '¡No tengo que demostrarte nada!', '', 28153),
(150670, 'esES', 'Venga, Abraham, he visto a niños hacerlo.', '', 28153),
(150669, 'esES', 'Venga, si no está tan alto.', '', 28153),
(150668, 'esES', 'Apuesto a que no puedes trepar hasta allí.', '', 28153),
(150667, 'esES', '¡No tiene gracia! ¡Bájame de aquí!', '', 28153),
(150666, 'esES', '¡Deja de hacer el tonto y ayúdame a bajar!', '', 28153),
(150665, 'esES', '¡Ayúdame a bajar!', '', 28153),
(150664, 'esES', '¡Vete mientras puedas!', '¡Vete mientras puedas!', 28153),
(150663, 'esES', '¡No acabarán conmigo!', '¡No acabarán conmigo!', 28153),
(150662, 'esES', '¡Que se queden con mi parte!', '¡Que se queden con mi parte!', 28153),
(150661, 'esES', '¡Mataremos a toda la Marea de Hierro!', '¡Mataremos a toda la Marea de Hierro!', 28153),
(150660, 'esES', '¡No acabarán conmigo!', '¡No acabarán conmigo!', 28153),
(150659, 'esES', '¡Yo no trabajo para piratas!', '¡Yo no trabajo para piratas!', 28153),
(150658, 'esES', '', '¡Te aplastaré la cabeza!', 28153),
(150657, 'esES', '¿Te diviertesh ahí? ¡Ja!', '', 28153),
(150656, 'esES', '¿Tienesh algún problema, Abraham?', '', 28153),
(150655, 'esES', '¡Oye, idiota! ¡Eshtásh atrapado ahí arriba!', '', 28153),
(150654, 'esES', 'Sethraliss sacrificó su vida para salvar nuestro mundo. Si Mythrax vuelve, su valiente sacrificio habrá sido en vano...', '', 28153),
(150653, 'esES', 'Aunque Mythrax esté muerto, su esencia sigue teniendo una fuerte presencia aquí. Temo por el mundo si vuelve a alzarse...', '', 28153),
(150652, 'esES', 'Hay una presencia oscura aquí. Deberíamos mantenernos alerta...', '', 28153),
(150651, 'esES', '', 'Comienzan su camino hacia la grandeza.', 28153),
(150650, 'esES', '', 'Hora de poner a prueba a loh pequeñoh pa que comiencen a labrar su dehtino. Anímaloh a que vuelvan al Salón de lah Cahtah.', 28153),
(150649, 'esES', '¡Muy bien! Gracias a estas criaturas tendremos flechas y revestimientos para las armaduras.', '', 28153),
(150648, 'esES', 'Es difícil llevar suministros a la ciénaga, así que tendrás que buscar materiales que nos ayuden en nuestra campaña entre la fauna y la flora locales.', '', 28153),
(150647, 'esES', 'Con eso bastará. Estoy seguro de que esas alimañas resbaladizas no le habrán dado muchos problemas a alguien como tú.', '', 28153),
(150646, 'esES', '¿Un enjambre de lanzatintas? ¡Qué detalle han tenido al presentarse justo cuando se me estaba acabando! Toma este pergamino y úsalo para extraer la tinta de esos bichos.', '', 28153),
(150645, 'esES', '', 'Parece que esta tecnología resultará muy útil para nuestras fuerzas. ¡Bien hecho!', 28153),
(150644, 'esES', '', 'Mekkatorque ha mejorado su tecnología DRON y necesita objetivos para ponerla a prueba. Sabemos que hay un gran número de trols de sangre ocultos cerca. ¡Usa la tecnología DRON para encontrarlos y destruirlos!', 28153),
(150643, 'esES', '<¡A bordo!>', '<¡A bordo!>', 28153),
(150642, 'esES', '<Kua\'fon gira la cabeza para mirarte. Te saluda con un agudo graznido>.\n\n¡Prrii!', '', 28153),
(150641, 'esES', '', 'Monstruitos inmundos.', 28153),
(150640, 'esES', '', 'Los ranishus tienen varios estómagos, sigue buscando después de encontrar el primero.', 28153),
(150639, 'esES', 'Le llevará un tiempo volver al nido, ya que no puede volar. Seguro que ehtá bien.$b$bMira luego, debería haber vuelto.', '', 28153),
(150638, 'esES', 'Bueno, la he arreglado. De nada, por cierto.$b$bMe di cuenta de que parecía un poco alicaído. ¡Tal vez podríah llevártelo pa otro vuelo! El ejercicio le vendría bien.', '', 28153),
(150637, 'esES', '¿Y esa cometa?', '¿Y esa cometa?', 28153),
(150636, 'esES', '', 'Tenemoh que alcanzarla. ¡Vamoh!', 28153),
(150635, 'esES', '', '¡Tenemoh que apresurarnoh y encontrar a Rakera!', 28153),
(150634, 'esES', 'Te llevo la delantera, Kenzou.', '', 28153),
(150633, 'esES', 'Gracias, $p. No podríamos haberlo hecho sin ti. Toma tu parte.', '', 28153),
(150632, 'esES', 'Y ahora, Tacha y Omi... Vamos a limpiar este sitio de cualquier cosa de valor.', '', 28153),
(150631, 'esES', '¡Bahta! ¡Oh habéih ganado el honor de que oh mate yo mihmo!', '', 28153),
(150630, 'esES', 'Ni la muerte puede romper nuehtro vínculo, mahcotah míah. Ahora... ¡Aliméntate, T\'zala!', '', 28153),
(150629, 'esES', '¡Nadie puede oponerse a mi hoja!', '', 28153),
(150628, 'esES', '¡Ahora vas a sangrar!', '', 28153),
(150627, 'esES', '¡Te arrancaré la piel!', '', 28153),
(150626, 'esES', '¿Eh posible? Sí... ¡Por fin!', '', 28153),
(150625, 'esES', '¡Mi leyenda sobrevivirá a la tuya!', '', 28153),
(150624, 'esES', '¿Pensabah que te haríah con mi corona?', '', 28153),
(150623, 'esES', 'Por eso yo soy el Rey... y vosotroh nada.', '', 28153),
(150622, 'esES', '¡Pagaréih por haber profanado mi templo!', '', 28153),
(150621, 'esES', '¡Empieza la temporada de caza!', '', 28153),
(150620, 'esES', '¡No hay antídoto pa ehte veneno!', '', 28153),
(150619, 'esES', '¡Loh elementoh acuden a mi llamada!', '', 28153),
(150618, 'esES', '¡Ehto sí que eh un maleficio de verdad!', '', 28153),
(150617, 'esES', '', '¡Aquí viene el dolor!', 28153),
(150616, 'esES', '', '¡Hora de morir!', 28153),
(150615, 'esES', '', '¡Mi hacha tiene hambre!', 28153),
(150614, 'esES', '', 'Sigue andando si sabes lo que te conviene.', 28153),
(150613, 'esES', '', '¡Alguien va a perder la cabeza!', 28153),
(150612, 'esES', 'Enterradme... lejoh... de ehtoh... idiotah...', '', 28153),
(150611, 'esES', '', 'Mi cabeza... será... un gran trofeo...', 28153),
(150610, 'esES', '', 'Mi ira... eh... eterna...', 28153),
(150609, 'esES', 'Ssh... ¡Intento encontrar unas mariposas!', '', 28153),
(150608, 'esES', '', '¡Ooooh! Me voy a hacer unoh adornoh preciosoh con vuehtrah cabezah.', 28153),
(150607, 'esES', '', 'Pff, he aplahtado insectoh máh fuerteh...', 28153),
(150606, 'esES', '¡Que el vudú te lleve!', '', 28153),
(150605, 'esES', '', '¡Nada sobrevive a mi rabia!', 28153),
(150603, 'esES', '¡Me quedo con el tesoro!', '¡Me quedo con el tesoro!', 28153),
(150602, 'esES', '¡Haz que paren las voces!', '¡Haz que paren las voces!', 28153),
(150601, 'esES', '¡Ese tesoro es mío!', '¡Ese tesoro es mío!', 28153),
(150599, 'esES', '', '¡Ja! ¡Te he quitado un peso de encima!', 28153),
(150598, 'esES', '¡Ja! No deberíaih haber dehpertado mi poder...', '', 28153),
(150597, 'esES', '', '¡Sangre y huesoh!', 28153),
(150596, 'esES', '', '¡No hay ehcapatoria!', 28153),
(150595, 'esES', 'Ha llegado el médico.', '', 28153),
(150594, 'esES', '¡Hay que preparar el cuerpo!', '', 28153),
(150593, 'esES', '¡Varios huevos empiezan a abrirse al norte!', '¡Varios huevos empiezan a abrirse al norte!', 28153),
(150592, 'esES', '¡Habéih perturbado a loh muertoh!', '', 28153),
(150591, 'esES', '¡Unos huevos cubiertos de polvo empiezan a abrirse al este!', '¡Unos huevos cubiertos de polvo empiezan a abrirse al este!', 28153),
(150590, 'esES', '¡Unos huevos cubiertos de veneno empiezan a abrirse al oeste!', '¡Unos huevos cubiertos de veneno empiezan a abrirse al oeste!', 28153),
(150589, 'esES', '¡Eliminar el cerebro pa prevenir la infección!', '', 28153),
(150588, 'esES', '¡La maldición sangrienta debe ser purgada!', '', 28153),
(150587, 'esES', 'Hay que... preservar... a loh muertoh...', '', 28153),
(150586, 'esES', '', 'Le dije a Kaja que no parásemoh. Hay que detener a Jakra\'zet anteh de que sea tarde.', 28153),
(150585, 'esES', '¡Libre de la plaga!', '', 28153),
(150584, 'esES', '¡Polvo al polvo!', '', 28153),
(150583, 'esES', 'Dehcansad.', '', 28153),
(150582, 'esES', '¡Vuehtra sangre ehtá maldita!', '', 28153),
(150581, 'esES', '¡Vuehtroh cuerpoh ehtán infectadoh!', '', 28153),
(150580, 'esES', '', 'Uff... Mi cabeza... ¿Qué son ehtah cosah?', 28153),
(150574, 'esES', '¡Eso habrá que verlo, vil criatura!', '', 28153),
(150573, 'esES', 'La tormenta despierta.', 'La tormenta despierta.', 28153),
(150572, 'esES', '¡Piérdete!', '¡Piérdete!', 28153),
(150571, 'esES', 'Claro, Vali, enséñame qué tienes.', 'Claro, Vali, enséñame qué tienes.', 28153),
(150570, 'esES', '¿Por qué necesitas monedas?', '¿Por qué necesitas monedas?', 28153),
(150569, 'esES', 'Los caracolmillos que vienen aquí siempre ofrecen monedas al comerciar.$b$b¡Vali cree que deben ser importantes para comerciar fuera de Vol\'dun!$b$bSi Vali quiere irse de Vol\'dun, Vali necesita monedas.', '', 28153),
(150568, 'esES', '¡Vali vende cosas si tienes monedas!', '', 28153),
(150567, 'esES', '¡Hola! ¡Sí, tú! ¡Parece que no te vendría mal un poco de agua!', '', 28153),
(150566, 'esES', '', 'Gracias, Mace. Cuando esto termine, ¿te interesaría el puesto de diplomática de mi casa?', 28153),
(150565, 'esES', '', 'Confío en ti. Si alguien más te da problemas, se le rompe el cráneo y listo.', 28153),
(150564, 'esES', 'Debería volver al altar. Merece la pena investigar esta esencia.', 'Debería volver al altar. Merece la pena investigar esta esencia.', 28153),
(150563, 'esES', '¿Necesitah reparacioneh? Lah herramientah son viejah, pero siguen siendo útileh.', '¿Necesitah reparacioneh? Lah herramientah son viejah, pero siguen siendo útileh.', 28153),
(150562, 'esES', 'Deseo escoger a Akunda como mi loa.', 'Deseo escoger a Akunda como mi loa.', 28153),
(150561, 'esES', '<Este santuario se construyó como tributo a Akunda, el loa de las tormentas>.', '<Este santuario se construyó como tributo a Akunda, el loa de las tormentas>.', 28153),
(150560, 'esES', '', '¡Qué insolencia! Ya verás cuando se entere tu padre. Hasta entonces, los sirvientes se ocuparán de ti.', 28153),
(150559, 'esES', '', '¡No te atrevas a llamarme hija, bruja!', 28153),
(150558, 'esES', '', 'Bienvenida a casa, hija. Veo que traes invitados.', 28153),
(150557, 'esES', '¡AAAAAAH!', '¡AAAAAAH!', 28153),
(150556, 'esES', 'Inspeccionar el tejido más de cerca.', 'Inspeccionar el tejido más de cerca.', 28153),
(150555, 'esES', 'Este telar y sus creaciones parecen estar imbuidos de la magia del aquelarre.', 'Este telar y sus creaciones parecen estar imbuidos de la magia del aquelarre.', 28153),
(150554, 'esES', 'Coger la botella.', 'Coger la botella.', 28153),
(150553, 'esES', 'Aunque hace tiempo que esta botella se echó a perder, aún podría resultarle útil a un cocinero experimentado.', 'Aunque hace tiempo que esta botella se echó a perder, aún podría resultarle útil a un cocinero experimentado.', 28153),
(150552, 'esES', '¡Aah! ¿Qué pasa? ¡Socorro!', '', 28153),
(150551, 'esES', 'Destruir la vaina inmadura.', 'Destruir la vaina inmadura.', 28153),
(150550, 'esES', 'Una vaina infecta permanece inactiva. Parece que alguien la está cultivando con aviesas intenciones.', 'Una vaina infecta permanece inactiva. Parece que alguien la está cultivando con aviesas intenciones.', 28153),
(150549, 'esES', 'Coger el mapa.', 'Coger el mapa.', 28153),
(150548, 'esES', 'Aquí hay un mapa gastado que señala zonas de caza locales y comerciantes de cuero regionales.', 'Aquí hay un mapa gastado que señala zonas de caza locales y comerciantes de cuero regionales.', 28153),
(150547, 'esES', '¿Seguro que quieres hacerlo?', '¿Seguro que quieres hacerlo?', 28153),
(150546, 'esES', 'Has... ¡Has SALTADO dentro de la olla! Pero ¿cómo se te ocurre? ¡Tenemos que empezar de nuevo!', '', 28153),
(150545, 'esES', '', '¡El camino ehtá dehpejado! A lah puertah, anteh de que la siguiente oleada se abra paso.', 28153),
(150544, 'esES', '', 'Adalid, ayuda al maestro en lo que haga falta. Yo voy a ver si el alcalde Royston necesita ayuda.', 28153),
(150543, 'esES', '¡Nunca me cogeréis con vida!', '¡Nunca me cogeréis con vida!', 28153),
(150542, 'esES', '', 'Me alegra que así sea, maestro Ashton.', 28153),
(150541, 'esES', 'Inquisidora, será un auténtico honor ayudaros a lady Lucille y a ti con esta tarea.', '', 28153),
(150540, 'esES', '¡Fascinante! Una fórmula extraordinaria. ¡E inflamable!', '', 28153),
(150539, 'esES', 'Lady Lucille cree que podría ser útil, ¿no? Bien, ¡vamos allá!', '', 28153),
(150538, 'esES', '', 'Ha encontrado una receta alquímica que funcionó en el pasado y quiere que intentes recrear la fórmula.', 28153),
(150537, 'esES', '', 'Lady Lucille ha fundado de nuevo la Orden de Ascuas. Con la ayuda de textos antiguos, lucharemos contra las brujas como hicimos con los Drust.', 28153),
(150536, 'esES', '', '¡Krax il\' oni ogog!', 28153),
(150535, 'esES', '', 'Ul tala kraza.', 28153),
(150534, 'esES', '', 'Bwaxa za\' raga xil.', 28153),
(150533, 'esES', '', '¡Kryl!', 28153),
(150532, 'esES', 'Eso ya lo he deducido, ¿pero por qué yo?', '', 28153),
(150531, 'esES', '', 'Bwixki amala zal qulllll...', 28153),
(150530, 'esES', '', 'Aglathrax hig\' thrixa.', 28153),
(150529, 'esES', '', 'Maestro Ashton, lady Lucille Crestavía nos ha enviado a buscarte.', 28153),
(150528, 'esES', '', '¡Ull vera skish!', 28153),
(150527, 'esES', '¿Qué podíais vosotros contra mi poder?', '', 28153),
(150526, 'esES', '¡Elimino la corrupción!', '', 28153),
(150525, 'esES', '¡Te he purificado!', '', 28153),
(150524, 'esES', 'Las mareas se vuelven contra mí...', '', 28153),
(150523, 'esES', '¡Estoy deseando ahogaros yo mismo!', '', 28153),
(150522, 'esES', '¡No toleraré vuestra insolencia por más tiempo!', '', 28153),
(150521, 'esES', '¡Invoco el poder de las aguas torrenciales! ¡Álzate y acaba con estos intrusos!', '', 28153),
(150520, 'esES', '¡Cómo osáis mancillar este lugar sagrado con vuestra presencia!', '', 28153),
(150519, 'esES', 'Disfruta de tu tumba acuática.', '', 28153),
(150518, 'esES', '[LA ESCENA MUESTRA A JAKRA\'ZET Y AL EMPERADOR SETHRAK KORTHEK RODEADOS DE SETHRAK, CONSPIRANDO PARA IRRUMPIR EN LA PIRÁMIDE. KORTHEK TE DERRIBA DEL CIELO].', '', 28153),
(150517, 'esES', '¿Qué quiere Azeroth de mí, Magni?', '¿Qué quiere Azeroth de mí, Magni?', 28153),
(150516, 'esES', 'Debiste quedarte en la orilla.', '', 28153),
(150515, 'esES', 'Devolvedme... al mar...', '', 28153),
(150514, 'esES', '¡Os arrojaré a las profundidades por eso!', '', 28153),
(150513, 'esES', '¡NO!', '', 28153),
(150512, 'esES', '¡Que las mareas os lleven!', '', 28153),
(150511, 'esES', 'Ningún poder puede romper nuestro vínculo.', '', 28153),
(150510, 'esES', '', 'Juntos, mi amor, somos una fuerza de la naturaleza.', 28153),
(150509, 'esES', '', '¡Te ha purificado la tormenta!', 28153),
(150508, 'esES', '', '¡Te ha llevado la corriente!', 28153),
(150507, 'esES', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t¡%s ha recibido una |cFFFF0000|Hcurrency:1559|hEsencia de tormenta!|h|r!', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t¡%s ha recibido una |cFFFF0000|Hcurrency:1559|hEsencia de tormenta!|h|r!', 28153),
(150506, 'esES', '', 'Las nubes... se abren...', 28153),
(150505, 'esES', '', '¡Los vientos os arrancarán la carne de los huesos!', 28153),
(150504, 'esES', '', '¡Amor mío! ¡No!', 28153),
(150503, 'esES', 'Si alguien puede sobrevivir a eso, es él. Voy a ver cómo están los jardines del laboratorio.', '', 28153),
(150502, 'esES', '', '¡Nadie puede oponerse a la tormenta!', 28153),
(150501, 'esES', '', 'El ataque a Médano del Halcón fue feroz. Espero que el maestro Ashton siga vivo.', 28153),
(150500, 'esES', '', '¡Priscilla huye a caballo! ¡Monta en uno de nuestros destreros y persíguela!', 28153),
(150499, 'esES', 'Maestro Ashton, necesitamos tu ayuda.', 'Maestro Ashton, necesitamos tu ayuda.', 28153),
(150498, 'esES', 'Muchas gracias, me voy ahora mismo.', 'Muchas gracias, me voy ahora mismo.', 28153),
(150497, 'esES', '¡No me olvidaré de esto! ¡Me largo!', '¡No me olvidaré de esto! ¡Me largo!', 28153),
(150496, 'esES', 'Temía que iba a quedarme ahí para siempre... ¡Toma una muestra de mi gratitud!', 'Temía que iba a quedarme ahí para siempre... ¡Toma una muestra de mi gratitud!', 28153),
(150495, 'esES', 'Gracias por liberarme, quizás esto te ayude.', 'Gracias por liberarme, quizás esto te ayude.', 28153),
(150494, 'esES', '¡Menos mal que me has salvado! Deja que ayude en lo que pueda.', '¡Menos mal que me has salvado! Deja que ayude en lo que pueda.', 28153),
(150493, 'esES', '¡No me dejes aquí!', '¡No me dejes aquí!', 28153),
(150492, 'esES', '¡Déjame salir!', '¡Déjame salir!', 28153),
(150491, 'esES', '', 'Por favor, ¡ayudadnos! Si no detenemos a Gorak Tul, su maldad se propagará por todo Azeroth.', 28153),
(150490, 'esES', '¡Socorro!', '¡Socorro!', 28153),
(150489, 'esES', '¡Rápido, encuentra una forma de abrir esta celda!', '¡Rápido, encuentra una forma de abrir esta celda!', 28153),
(150488, 'esES', '¡Libérame!', '¡Libérame!', 28153),
(150487, 'esES', '¡Ayuda! ¡Por favor!', '¡Ayuda! ¡Por favor!', 28153),
(150486, 'esES', '¿Un sáurido? ¿Qué hace aquí?', '', 28153),
(150485, 'esES', '', 'No importa quiénes sean; necesitamos su ayuda. ¡No podemos permitir que Gorak Tul entre en nuestro mundo!', 28153),
(150484, 'esES', '', '¡Tranquilo, maestro Ashton! ¡Somos amigos!', 28153),
(150483, 'esES', '¡Llegamos tarde! Un momento, ¡¿quiénes sois vosotros?!', '', 28153),
(150482, 'esES', 'Pues tenéis una pinta peligrosa... ¿Entonces ha acabado el ataque?', '', 28153),
(150480, 'esES', '¡Atrás! ¡Tengo alquimia y sé cómo usarla!', '', 28153),
(150479, 'esES', 'Al destruir a lady Crestavía, me habéis abierto la puerta a vuestro mundo.', '', 28153),
(150478, 'esES', 'Mortales, os falta visión. La muerte es imparable.', '', 28153),
(150477, 'esES', '', 'Habéis abusado de mi hospitalidad. Muy bien, ¡ahora ya nunca saldréis de este lugar!', 28153),
(150476, 'esES', '', 'Seguid metiéndoos en mis asuntos y vuestras muertes serán lentas y abominables.', 28153),
(150475, 'esES', '', 'Por la expresión alelada de vuestros rostros, me parece que el concepto de una morada que no esté hecha de estiércol os debe de resultar fascinante.', 28153),
(150474, 'esES', '', 'Pensándolo mejor, no contestéis.', 28153),
(150473, 'esES', '', '¿En vuestra tierra se considera de buena educación asesinar a los sirvientes de la anfitriona?', 28153),
(150472, 'esES', 'Estoy listo. Vayamos a buscar a los demás.', 'Estoy lista. Vayamos a buscar a los demás.', 28153),
(150471, 'esES', 'No hay tiempo que perder. Tus amigos ya están dentro de Atul\'Aman...', '', 28153),
(150470, 'esES', 'Kua\'fon grazna indignado y echa a correr.', '', 28153),
(150469, 'esES', '', '¡Pequeñín! Si quieres regresar al nido, más te vale empezar a correr.', 28153),
(150468, 'esES', '', 'Por ahora vamos a enseñarle una lección práctica.', 28153),
(150467, 'esES', '', 'Tu pequeño no tiene fe en sus alas. Debes seguir enseñándole la alegría de los cielos.', 28153),
(150466, 'esES', '', '¡¿Por qué sigues usando las patas?!', 28153),
(150465, 'esES', '', 'Estáis los dos vivos. Bien. Como dije...', 28153),
(150464, 'esES', '', 'Gracias, héroes. Habéis acabado con el aquelarre y nos habéis liberado del poder de Gorak Tul. Estamos en deuda con vosotros.', 28153),
(150463, 'esES', '', 'Ya veis, no hay nada que un brazo fuerte y una hoja afilada no puedan arreglar.', 28153),
(150462, 'esES', '¡Lo hemos logrado! Gorak Tul ha sido derrotado.', '', 28153),
(150461, 'esES', '¡Ante el choque inminente, Kua\'fon chilla pidiendo ayuda!', '¡Ante el choque inminente, Kua\'fon chilla pidiendo ayuda!', 28153),
(150460, 'esES', 'Venid, mortales. Vuestro fin os espera.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'esES', '', 'Mareasevera y yo los retendremos aquí. ¡Tenéis que acabar con esto!', 28153),
(150458, 'esES', '', '¡Todos los horrores de la mansión se dirigen hacia nosotros!', 28153),
(150457, 'esES', '', '¡No podemos permitir que Gorak Tul acceda a nuestro mundo!', 28153),
(150456, 'esES', 'La cometa empieza a temblar violentamente. ¡Vuelve a un aire más calmado!', 'La cometa empieza a temblar violentamente. ¡Vuelve a un aire más calmado!', 28153),
(150455, 'esES', '|TInterface\\ICONS\\INV_POTION_24:20|t ¡Usa |cFFFF0404|Hspell:266198|h[Fuego alquímico]|h|r para destruir cadáveres de esclavistas toquemuerte!', '', 28153),
(150454, 'esES', 'Vuestra pesadilla no ha hecho más que empezar.', '', 28153),
(150453, 'esES', 'Lady Crestavía era una mera receptora de mi poder. Al destruirla, me habéis abierto una puerta a vuestro mundo.', '', 28153),
(150452, 'esES', 'Absorbiendo.', 'Absorbiendo.', 28153),
(150451, 'esES', 'Criatura inconsciente, te falta visión. La muerte es una fuerza inevitable que te acecha en cada esquina.', '', 28153),
(150450, 'esES', '', 'Al fin ha terminado la pesadilla.', 28153),
(150448, 'esES', 'Ve. Roba su gorro y gana el favor de Jani. Pero cuidado: que no te vean los depredadores hambrientos...', '', 28153),
(150446, 'esES', '', 'Cierto. Pero ¿cómo recuperaré la confianza de mi gente cuando sepan que mi familia ha cometido semejantes horrores?', 28153),
(150445, 'esES', '', 'Lo único que importa ahora es acabar con su maldad.', 28153),
(150444, 'esES', '', 'Mi madre tenía una vena cruel, pero jamás imaginé que sería capaz de esto.', 28153),
(150443, 'esES', 'Seguid. Encontrad a lady Crestavía y vengaos.', '', 28153),
(150442, 'esES', '¡Je! Carne muerta.', '', 28153),
(150441, 'esES', 'Aseguraos de que lady Crestavía pague por esta magia maligna.', '', 28153),
(150440, 'esES', 'Habéis hecho un favor a esas almas; las habéis liberado.', '', 28153),
(150439, 'esES', 'Seguid buscando a lady Crestavía, yo comprobaré si estas habitaciones están vacías.', '', 28153),
(150438, 'esES', 'Descansaré mejor sabiendo que esas despreciables criaturas ya no acechan en la noche.', '', 28153),
(150437, 'esES', 'Investigaremos la propiedad mientras acabáis con los sirvientes. Buena caza.', '', 28153),
(150436, 'esES', '', 'Héroes, necesito vuestra fuerza. Debemos poner fin a este horror.', 28153),
(150435, 'esES', 'No parece buena idea salir corriendo. Tenemos un plan más sólido... ¿No?', '', 28153),
(150434, 'esES', '¡Mace!', '', 28153),
(150433, 'esES', '', '¡Vuelve y enfréntate a mi acero!', 28153),
(150432, 'esES', '', 'Como ordenes, señora.', 28153),
(150431, 'esES', '', 'Encargaos de que nuestros visitantes estén cómodos.', 28153),
(150430, 'esES', '', 'Parece que tenemos visitantes que no han sido invitados. Pero seguro que podemos acogerlos.', 28153),
(150429, 'esES', 'Eres una caja de sorpresas.', 'Eres una caja de sorpresas.', 28153),
(150428, 'esES', '¡Buen trabajo, $r!', 'Buen trabajo, $p.', 28153),
(150427, 'esES', '¡Soy libre!', '¡Soy libre!', 28153),
(150426, 'esES', '¡Te debo una!', '¡Te debo una!', 28153),
(150425, 'esES', '¡Muchas gracias!', '¡Muchas gracias!', 28153),
(150421, 'esES', 'Te concederé una porción de mi poder. Mi baluarte eliminará a cualquier infiel que ose desafiarte.', '', 28153),
(150420, 'esES', '¿Tanto miedo tienes, viejo amigo, que te escondes mientras tu pueblo sufre? ¡Ven a poner fin a esto, Korthek!', '', 28153),
(150419, 'esES', 'Deberías trabajar conmigo, $p. Lo voy a encontrar.', 'Deberías trabajar conmigo, $p. Lo voy a encontrar.', 28153),
(150418, 'esES', '', '¡Un contratiempo sin importancia! ¡Cuando mis fuerzas se reagrupen, este pueblucho será nuestro!', 28153),
(150417, 'esES', 'La traición de Zul eh máh profunda de lo que creía. Con su rebelión prácticamente ha diezmado mi ejército.\n\nLoh que aún me son lealeh mueren en el campo de batalla que hay detráh de mí a manoh de esah interminableh manadah de trolh de sangre invasoreh.\n\nDebería haber ehcuchado a Talanji.', '', 28153),
(150416, 'esES', 'Conozco a alguien que sabe dónde está.', 'Conozco a alguien que sabe dónde está.', 28153),
(150415, 'esES', '¿Sabes dónde está el oro?', '¿Sabes dónde está el oro?', 28153),
(150414, 'esES', 'Si encuentras el tesoro podríamos compartirlo.', 'Si encuentras el tesoro podríamos compartirlo.', 28153),
(150413, 'esES', 'He oído que la Marea de Hierro ya lo ha encontrado.', 'He oído que la Marea de Hierro ya lo ha encontrado.', 28153),
(150412, 'esES', '¡Eh, ayúdame a encontrar el tesoro!', '¡Oye, ayúdame a encontrar el tesoro!', 28153),
(150411, 'esES', 'Conozco a un tipo que tiene un amigo que ha oído a la Marea de Hierro decir que saben dónde está.', 'Conozco a un tipo que tiene un amigo que ha oído a la Marea de Hierro decir que saben dónde está.', 28153),
(150410, 'esES', 'Puede que las historias del oro sean un puñado de mentiras.', 'Puede que las historias del oro sean un puñado de mentiras.', 28153),
(150409, 'esES', 'Tenemos que encontrar el tesoro antes de que la Marea de Hierro asalte este lugar.', 'Tenemos que encontrar el tesoro antes de que la Marea de Hierro asalte este lugar.', 28153),
(150408, 'esES', '', 'Tal vez alguien se ha comido al gato.', 28153),
(150407, 'esES', 'Vuela a casa, orgulloso rak\'jani, y dile a tu padre quién te liberó.', '', 28153),
(150406, 'esES', '', 'Reuniré a algunoh tripulanteh y buhcaré a otroh pa que cojan lah chalupah que hay cerca. ¡Que te diviertah, $n!', 28153),
(150405, 'esES', '¡Deprisa! ¡Hay que quemarlos antes de que el rey los resucite!', '', 28153),
(150404, 'esES', '¡Rápido! ¡Prendedles fuego!', '', 28153),
(150403, 'esES', '¡Nos vendría bien algo de ayuda por aquí!', '', 28153),
(150402, 'esES', '¡Nos superan en número!', '', 28153),
(150401, 'esES', '¡Sucumbe a la oscuridad!', '', 28153),
(150400, 'esES', '¡Alzaos!', '', 28153),
(150399, 'esES', '¡Nadie puede oponerse a mí!', '', 28153),
(150398, 'esES', '¡No eres nada!', '', 28153),
(150397, 'esES', 'Toda vida tiene un final.', '', 28153),
(150396, 'esES', 'La muerte... no puede retenerme...', '', 28153),
(150395, 'esES', '¡La muerte lo consume todo!', '', 28153),
(150394, 'esES', '¡Nadie escapará a mi venganza!', '', 28153),
(150393, 'esES', '¡Todo el personal a la cocina!', '', 28153),
(150392, 'esES', '¡A macerar!', '', 28153),
(150391, 'esES', 'El menú de esta noche será sabrosísimo...', '', 28153),
(150390, 'esES', 'Qué... deliciosa... agonía...', '', 28153),
(150388, 'esES', '', 'Los vulperas te apoyamos, $p.\n\nEnvíame a cualquier infiel problemático y me encargaré de él. Con mucho gusto.', 28153),
(150387, 'esES', '¡Qué delicia!', '', 28153),
(150386, 'esES', '¡Carne fresca!', '', 28153),
(150385, 'esES', '¡Se me hace la boca agua!', '', 28153),
(150384, 'esES', '¡Quedaos para la cena!', '', 28153),
(150383, 'esES', '¡Quien encuentre el tesoro se llevará una porción triple!', '', 28153),
(150382, 'esES', '¿Quieres enriquecerte? ¡Encuéntrame ese tesoro!', '', 28153),
(150381, 'esES', '¡Moxie, pon a estos holgazanes a trabajar!', '', 28153),
(150380, 'esES', '¡Apestosos Marea de Hierro, nunca conseguiréis el tesoro!', '', 28153),
(150379, 'esES', '¡Mata a ese tipo del sombrero de pirata! ¡Sí, a ese!', '', 28153),
(150378, 'esES', '¡Mirad debajo de las rocas! ¡Mirad por todas partes!', '', 28153),
(150377, 'esES', '¡Deshazte de esos Marea de Hierro!', '', 28153),
(150376, 'esES', 'Muuu.', '', 28153),
(150375, 'esES', '', 'Muuu.', 28153),
(150374, 'esES', '', 'Lo siento.', 28153),
(150373, 'esES', '', 'Soy la Matrona Alfa de Desinfección del Riego Envenenado. Designación: MADRE.', 28153),
(150372, 'esES', '', '¡Lo que estabais haciendo aquí se acaba hoy!', 28153),
(150371, 'esES', '', '¿Dónde está el dinero?', 28153),
(150370, 'esES', '', '¡Sé que estáis escondiendo algo por aquí!', 28153),
(150369, 'esES', '', 'No aguantaréis en el astillero.', 28153),
(150368, 'esES', '', 'No sois tan duros como esperaba.', 28153),
(150367, 'esES', '', '¡Llevaréis estas cadenas hasta los astilleros!', 28153),
(150366, 'esES', 'Saludos, alhaja. ¿Has traído algo sólido y resistente al Santuario de los Carroñeros?', '', 28153),
(150365, 'esES', '¡Que se lo queden, si mueres no podrás gastártelo!', '¡Que se lo queden, si mueres no podrás gastártelo!', 28153),
(150364, 'esES', 'No voy a abandonar el tesoro. ¡Está aquí!', 'No voy a abandonar el tesoro. ¡Está aquí!', 28153),
(150363, 'esES', '¡La Marea de Hierro viene hacia aquí! ¡Tenemos que salir de aquí, y pronto!', '¡La Marea de Hierro viene hacia aquí! ¡Tenemos que salir de aquí, y pronto!', 28153),
(150362, 'esES', 'Saludos, alhaja. ¿Has traído algo brillante y suave al Santuario de los Carroñeros?', '', 28153),
(150361, 'esES', 'Ya hemoh llegado. ¡Qué buen día pa salir a ehplorar!', '', 28153),
(150360, 'esES', 'Ehte terremoto no parece normal. Ehtá aflorando azerita cerca de aquí.', '', 28153),
(150359, 'esES', 'El artilugio ehtá conectado. Ahora deberíaih poder ver toda la azerita.', '', 28153),
(150358, 'esES', '¡Cuidado! Un barco de Kul Tirah ha recalado en la ihla.', '', 28153),
(150357, 'esES', '¡No es justo, te has llevado el último!', '¡No es justo, te has llevado el último!', 28153),
(150356, 'esES', '¡Eh, eso es mío!', '¡Eh, eso es mío!', 28153),
(150355, 'esES', '¡Regístrale los bolsillos!', '¡Regístrale los bolsillos!', 28153),
(150354, 'esES', '¡Coge las llaves!', '¡Coge las llaves!', 28153),
(150353, 'esES', '¡Idiota! ¡Razgaji te ha enviado a tu muerte!', '', 28153),
(150352, 'esES', '', 'Justo lo que estaba pensando. Adalid, ¿por qué no pones a prueba nuestra teoría?', 28153),
(150351, 'esES', 'Interesante. Los fuegos fatuos responden a la llamada de Malfurion. Pero ¿y si las voces del bosque pidieran ayuda?', '', 28153),
(150350, 'esES', '', 'No podemos matarlos... Al menos no a los suficientes. Pero tal vez podamos dispersarlos.', 28153),
(150349, 'esES', '¡Nadie le roba a Tongo y sale impune!', '', 28153),
(150348, 'esES', '', 'El grupo de exploradores que envié hasta Malfurion subestimó a los fuegos fatuos. Y pagaron caro su error...', 28153),
(150347, 'esES', '¿Un muro de fuegos fatuos? Ja, eso no es nada para nuestras forestales oscuras y nuestros demoledores, mi señora.', '', 28153),
(150346, 'esES', 'Nadie... me doblegará...', '', 28153),
(150345, 'esES', '¡Otro pterrordáctilo demasiado débil para los infieles!', '', 28153),
(150344, 'esES', '', '¡Me alegro de verte! Ven y descansa un poco.', 28153),
(150343, 'esES', '', '¡Si necesitas algo solo tienes que decírmelo!', 28153),
(150342, 'esES', '', '¡Te doy la bienvenida a mi taberna! Ven, tómate algo.', 28153),
(150341, 'esES', '', '¿Todo bien, dulzura? Entra, como si estuvieras en tu casa.', 28153),
(150340, 'esES', '', 'Tienes pinta de necesitar un descanso. ¡Siéntate y come algo!', 28153),
(150339, 'esES', 'Saludos, alhaja. ¿Has traído algo chispeante y afilado al Santuario de los Carroñeros?', '', 28153),
(150338, 'esES', '¡Toda esta azerita es mía!', '¡Toda esta azerita es mía!', 28153),
(150337, 'esES', '', 'Avísame si duele...', 28153),
(150336, 'esES', '', 'Hala, ¡sangras un montón!', 28153),
(150335, 'esES', '', 'Capitana, el cachivache ha detectado enemigos cerca de aquí. Cogeré mis cuchillos buenos.', 28153),
(150334, 'esES', '', 'Que me encargue de los fuegos, de las explosiones... Pff, ¡explotadores!', 28153),
(150333, 'esES', '', 'Que explote no implica que no funcione... Una cosa no quita la otra.', 28153),
(150332, 'esES', '', 'A la capitana... no le va a gustar esto...', 28153),
(150331, 'esES', '', '¡Puñalada!', 28153),
(150330, 'esES', '', '¡Sorpresa!', 28153),
(150329, 'esES', '', '¡Hora de apuñalar!', 28153),
(150328, 'esES', 'Esto duele un poco...', '', 28153),
(150327, 'esES', 'Oooh, ¡te va la marcha!', '', 28153),
(150326, 'esES', 'Ahora eres carnada.', '', 28153),
(150325, 'esES', '¿Qué estás mirando?', '', 28153),
(150324, 'esES', 'Soy comida para los peces...', '', 28153),
(150323, 'esES', 'Mmm, no es la fauna habitual de esta isla... Puede que valga la pena el desvío.', '', 28153),
(150322, 'esES', '¡Cebo para mi próxima pesca!', '', 28153),
(150321, 'esES', '¡Material para mi carnada!', '', 28153),
(150320, 'esES', '... pues recoge \"torbellinos\".', '', 28153),
(150319, 'esES', '', '¡Un cubo! ¡Rápido! No podemos desperdiciar ni una gota de sangre...', 28153),
(150318, 'esES', '', 'Una isla llena de criaturas, gente, cosas... ¡y miembros de la Horda! Traedme sangre.', 28153),
(150317, 'esES', '', 'Muy bien, tripulación, traedme sangre, mi preciada sangre... Os podéis quedar con el resto del botín.', 28153),
(150316, 'esES', '', 'Sangre de la Horda, mi preferida... Tripulación, ¡ya sabéis qué hacer!', 28153),
(150315, 'esES', '', 'Hola, ¿necesitas toda tu sangre? ¿No te sobra un poco?', 28153),
(150314, 'esES', '', 'Qué desperdicio de sangre...', 28153),
(150313, 'esES', '', 'Más rápido, ¡QUIERO SANGRE!', 28153),
(150312, 'esES', '', '¡Sangre!', 28153),
(150311, 'esES', '', '¡Nadie sobrevivirá!', 28153),
(150310, 'esES', '¡Aah! ¡Ja, ja, ja!', '', 28153),
(150309, 'esES', '¡Je, je, je, je!', '', 28153),
(150308, 'esES', '¡Alianzaaaaa! ¡Hora de jugar!', '', 28153),
(150307, 'esES', '¡Hola!', '', 28153),
(150306, 'esES', 'Ja... ja... ja...', '', 28153),
(150305, 'esES', '¡Alto!', '', 28153),
(150304, 'esES', '¡Pete el Curioso!', '', 28153),
(150303, 'esES', '¡Pete el Curioso!', '', 28153),
(150302, 'esES', '¡Pete el Curioso!', '', 28153),
(150301, 'esES', '¡Basta ya de molestar!', '', 28153),
(150300, 'esES', '¡Eso me hace cosquillas!', '', 28153),
(150299, 'esES', '¡En todo el blanco!', '', 28153),
(150298, 'esES', '¡Ja! ¡Te pillé!', '', 28153),
(150297, 'esES', 'Leer el texto rúnico en voz alta.', 'Leer el texto rúnico en voz alta.', 28153),
(150295, 'esES', 'Llévame al Trono Dorado.', 'Llévame al Trono Dorado.', 28153),
(150294, 'esES', '', 'Hay que llamar la atención de los kaldorei mientras busco una solución para el problema de los fuegos fatuos.', 28153),
(150293, 'esES', '', 'Mmm, ¿los fuegos fatuos se dispersaban? Excelente. Nuestro plan promete...', 28153),
(150292, 'esES', '', '¡Mi demoledor os hará pedazos! ¡Solo retrasáis lo inevitable!', 28153),
(150291, 'esES', '', '¡Acólitos, derribad esa barricada!', 28153),
(150290, 'esES', '', 'Adelante, mis mascotas. ¡Matad!', 28153),
(150289, 'esES', '', 'Campeones, conmigo. Os invito a presenciar el gran final.', 28153),
(150288, 'esES', '', 'O puede que tengas la ocasión de saludar a tu hijo.', 28153),
(150287, 'esES', '', 'Así que muere como un guerrero, señor supremo Colmillosauro. A mí me da igual. Quizás resucite tu cadáver destrozado para que me sirvas una vez más.', 28153),
(150286, 'esES', '', 'Puede que a ti no te importe que tu gente muera, siempre que sea con honor, pero yo creo que merece la pena salvar a la Horda. Quien no esté de acuerdo no merece luchar a nuestro lado.', 28153),
(150285, 'esES', '', 'El honor no significa nada para un cadáver, Colmillosauro. Tú gozas del lujo de poder subestimar a la muerte, pero yo ya la conozco demasiado bien.', 28153),
(150284, 'esES', '¡Confía en la estrategia de la Jefa de Guerra, Theron!', '', 28153),
(150283, 'esES', 'Los elfos del Vacío... ¡Debemos eliminar a esos traidores!', '', 28153),
(150282, 'esES', '¡Lordaeron pertenece a los Renegados! ¡No flaqueéis ahora!', '', 28153),
(150281, 'esES', 'Sus ataques cesarán pronto. ¡Resistid!', '', 28153),
(150280, 'esES', '¡La Alianza está en las últimas, campeones! Han perdido a más de la mitad de sus efectivos.', '', 28153),
(150279, 'esES', '¡Ja, ja, ja! Mira quién se une a la reyerta. Bien, ¡contaba contigo para añadir emoción!', '', 28153),
(150278, 'esES', 'Será mejor que te lo diga ella, ¡ahora vete!', '', 28153),
(150277, 'esES', '¿Cuánto crees que podrás retenerlos? ¿Cuál es la estrategia de la Jefa de Guerra?', '', 28153),
(150276, 'esES', 'No. Lor\'themar y yo nos encargaremos de los intrusos. No puedo arriesgarme a dejar a la Jefa de Guerra desprotegida. Quédate a su lado.', '', 28153),
(150275, 'esES', 'Entendido. Me reuniré contigo en cuanto pueda.', '', 28153),
(150274, 'esES', 'Vamos a crear un cuello de botella que los obligará a pasar por el lado de la fortaleza y mermará sus filas.', '', 28153),
(150273, 'esES', '¡No podemos esperar! ¡Solo tenemos unos momentos antes de perder la ventaja del terreno!', '', 28153),
(150272, 'esES', 'Sí, Clamañublo. Pero... ¿dónde está Colmillosauro?', '', 28153),
(150271, 'esES', '¡Baine! Reúne las catapultas y a todos los boticarios que encuentres. ¡Envíalos a la fortaleza de inmediato!', '', 28153),
(150270, 'esES', 'Será un placer, Clamañublo.', '', 28153),
(150269, 'esES', 'Lor\'themar, ¡toma el mando de los forestales del flanco! ¡Posiciónalos en los tejados!', '', 28153),
(150268, 'esES', '¡Lanzadores de añublo al frente! ¡Debéis crear una barrera de añublo entre nosotros y el enemigo!', '', 28153),
(150267, 'esES', 'Como ordenes, mi Reina.', '', 28153),
(150266, 'esES', '', 'Reúnete con Lor\'themar. ¡Rápido! ¡No me falles, Nathanos!', 28153),
(150265, 'esES', '¡Máscaras de gas! ¡Coged aquí vuestras máscaras de gas! Y si estáis de humor, ¡podéis coger una de estas mochilas y poneros a la faena!', '', 28153),
(150264, 'esES', 'Conservad vuestro honor, héroes. Lok-narash.', '', 28153),
(150263, 'esES', '', '¡Matadlos a todos, campeones! Escuchad bien, el rey Anduin y su ejército no han venido aquí de visita, ¡pretenden destruirnos! ¡No mostréis piedad, porque ellos no lo harán!', 28153),
(150262, 'esES', '¡Soldados de la Horda! ¡Vuestros hermanos y hermanas yacen heridos en el campo de batalla! ¡No habrá honor en esta victoria si abandonamos a los nuestros!', '', 28153),
(150261, 'esES', '¡Lok\'tar ogar!', '', 28153),
(150260, 'esES', 'Son muchos, pero nosotros somos más fuertes. ¡Somos la Horda! ¡Aplastamos a los que pretenden herirnos!', '', 28153),
(150259, 'esES', 'Campeones, ¡obedeced a vuestra Jefa de Guerra! ¡Es hora de alzarse en armas contra la Alianza!', '', 28153),
(150258, 'esES', '', 'Entonces acabemos con esto de una vez por todas. Colmillosauro, reúne a tus tropas. Yo prepararé la máquina de azerita.', 28153),
(150257, 'esES', 'Sí, Jefa de Guerra.', '', 28153),
(150256, 'esES', '¡Rápido! ¡La Jefa de Guerra espera!', '', 28153),
(150255, 'esES', '¡A mí, rápido! ¡Tenemos que seguir avanzando antes de que la Horda pueda reaccionar!', '', 28153),
(150254, 'esES', 'Sus vientos son fuertes, pero, juntos, ¡lo somos aún más! ¡Perseverad, campeones!', '', 28153),
(150253, 'esES', '¡No tan deprisa!', '', 28153),
(150252, 'esES', '', '¡Deprisa! ¡Mis barreras de hielo no resistirán eternamente!', 28153),
(150251, 'esES', 'Héroes, ¡centraos primero en los refuerzos! ¡Luego nos ocuparemos de esos chamanes!', '', 28153),
(150250, 'esES', 'La Jefa de Guerra... oh... detendrá.', '', 28153),
(150249, 'esES', '¡Loh vientoh del ehpíritu águila oh arrancarán loh huesoh!', '', 28153),
(150248, 'esES', '', '', 28153),
(150246, 'esES', 'PRRII.', '', 28153),
(150245, 'esES', '¡PRRIIIIIII!', '', 28153),
(150244, 'esES', '¡PRRII!', '', 28153),
(150242, 'esES', 'El libro está lleno de runas encantadas que recorren las páginas.', 'El libro está lleno de runas encantadas que recorren las páginas.', 28153),
(150241, 'esES', '¿Puedo matar ya? Se me prometió que podría matar...', '', 28153),
(150240, 'esES', '¡¿QUÉ?!', '', 28153),
(150239, 'esES', '¡Búscate tu propia caja, $r mangante!', '¡No, la caja es mía!\n\nHe venido a buscar gusanos para hacer sopa. Algunos tortolianos dicen que la carne de reptador es mejor para la sopa, pero yo no coincido con ellos. La sopa de reptador no merece el esfuerzo que supone entablar amistad con un desconocido.\n\nLa sopa de gusano de lodo forja amistades para toda la vida, y los tortolianos vivimos mucho tiempo.\n\nEncuéntrame carne de gusano de lodo y me pensaré si te doy esta caja.', 28153),
(150238, 'esES', 'Eso... duele...', '', 28153),
(150237, 'esES', '¡Graaaaa!', '', 28153),
(150236, 'esES', 'Antes de sacar el arma, escúchame...', '', 28153),
(150235, 'esES', '', '¡Que alguien registre el cadáver!', 28153),
(150234, 'esES', '', 'Hay tesoros en esta isla que aún no están en mi barco. ¿A qué esperáis? Traedme también la parte de la Alianza.', 28153),
(150233, 'esES', '', 'Veo que la Alianza está por aquí... y que sigue con vida. Ponedle remedio.', 28153),
(150232, 'esES', '', 'Hay que saquear esta isla. ¡Venga! ¡Odio que me hagan esperar!', 28153),
(150231, 'esES', '', '¿Yarr?', 28153),
(150230, 'esES', '', 'No voy... a devolver... nada...', 28153),
(150229, 'esES', '', '¡Basta! ¡Muerte al enemigo!', 28153),
(150228, 'esES', '', 'Siempre es más fácil despojar a un cadáver...', 28153),
(150227, 'esES', '', 'Mejor mantenerse lejos de la Alianza. He oído cosas muy malas sobre ellos.', 28153),
(150226, 'esES', '', '¿Así mejor?', 28153),
(150225, 'esES', '', 'Yo me encargo.', 28153),
(150224, 'esES', '', 'Saludos.', 28153),
(150223, 'esES', '', 'Yo... tenía... razón...', 28153),
(150222, 'esES', '', 'Oh, no, ¡están aquí!', 28153),
(150221, 'esES', 'Puede que convenga retirarse.', '', 28153),
(150220, 'esES', 'Ya no molestarás más.', '', 28153),
(150219, 'esES', 'No os acerquéis a nosotros, Alianza, o me veré obligado a machacaros.', '', 28153),
(150218, 'esES', 'Saludos.', '', 28153),
(150217, 'esES', 'Kua\'fon devora la comida y desparrama trozos por todas partes.', '', 28153),
(150216, 'esES', 'La Luz... Volveré...', '', 28153),
(150215, 'esES', '¡Que fluya la cólera!', '', 28153),
(150214, 'esES', '¡No tengo tiempo que perder!', '', 28153),
(150213, 'esES', '', 'Calma...', 28153),
(150212, 'esES', '', 'No tan rápido.', 28153),
(150211, 'esES', '', 'Ha llegado tu hora.', 28153),
(150210, 'esES', '', 'Polvo al polvo.', 28153),
(150209, 'esES', '', 'Los vientos nos han guiado hasta aquí... y a la Alianza también. A veces los elementos me sorprenden.', 28153),
(150208, 'esES', '', 'Escuchadme, miembros de la Alianza: dejadnos en paz y os ignoraremos.', 28153),
(150207, 'esES', '', 'Los elementos no están en equilibrio. Vamos a ver qué podemos hacer, pero no dejéis que la Alianza se inmiscuya.', 28153),
(150206, 'esES', '', '¿Cómo por aquí?', 28153),
(150205, 'esES', '', 'Mi... espíritu... volverá...', 28153),
(150204, 'esES', '', 'Mi paciencia tiene un límite.', 28153),
(150203, 'esES', '', 'Elementos, enviad vuestra ayuda.', 28153),
(150202, 'esES', '', 'Deja que te ayude...', 28153),
(150201, 'esES', '', '¡La Luz te ilumina!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'esES', '', 'No disfruto quitando vidas.', 28153),
(150199, 'esES', '', 'Cuidado, ha llegado el enemigo. Mejor no acercarse...', 28153),
(150198, 'esES', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Comida de dinosaurio con más tropezones]|h|r>', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Comida de dinosaurio con más tropezones]|h|r>', 28153),
(150197, 'esES', '', '¡La Luz nos ampara!', 28153),
(150196, 'esES', '', 'Me dirijo... a la Luz...', 28153),
(150195, 'esES', '<Kua\'fon chaquea sus fauces con impaciencia>.\n\nPRRII.', '', 28153),
(150194, 'esES', '', 'Capitular también es una opción... Mejor que la muerte.', 28153),
(150193, 'esES', '<Kua\'fon te olfatea>.\n\nPrrii.', '', 28153),
(150192, 'esES', '¿Seguro que quieres hacer esto? No tendrá ningún impacto sobre la trama, más allá de poder presumir de ello.', '¿Seguro que quieres hacer esto? No tendrá ningún impacto sobre la trama, más allá de poder presumir de ello.', 28153),
(150191, 'esES', '¡El enemigo es muy poderoso!', '', 28153),
(150190, 'esES', '¡La Luz te ha sentenciado!', '', 28153),
(150189, 'esES', 'La Jefa de Guerra quiere ahuyentar a los fuegos fatuos, ¿eh? Tengo justo lo que hace falta.\n\n¿Quieres pilotar el cacharro o prefieres lanzar las bombas?', '', 28153),
(150188, 'esES', 'La Luz brilla con fuerza en este lugar. Debe haber mucha azerita.', '', 28153),
(150187, 'esES', 'Todavía estoy viendo cuánto espacio hace falta. Puede que necesitemos quitar algunos árboles de en medio o conseguir un modelo de árbol que pueda hacer brillar.\n\nHaced como que ha sido impresionante, como si hubieran salido fuegos fatuos de la pared y hubieran aparecido grietas donde el bombardeo.', 'Todavía estoy viendo cuánto espacio hace falta. Puede que necesitemos quitar algunos árboles de en medio o conseguir un modelo de árbol que pueda hacer brillar. Haced como que ha sido impresionante, como si hubieran salido fuegos fatuos a montones y hubieran aparecido grietas en la pared de fuegos fatuos.', 28153),
(150186, 'esES', '¡A volar!', '¡A volar!', 28153),
(150185, 'esES', 'Yo puedo volar. Incendiar el bosque no es mi estilo.', 'Yo puedo volar. Incendiar el bosque no es mi estilo.', 28153),
(150184, 'esES', 'Que la Luz nos acompañe.', '', 28153),
(150183, 'esES', 'Ha sido... un buen combate...', '', 28153),
(150181, 'esES', 'Luz, ¡acaba con el enemigo!', '', 28153),
(150180, 'esES', '¡Por la Luz!', '', 28153),
(150179, 'esES', '', 'No tan rápido.', 28153),
(150178, 'esES', '', '¡Que corra el aire!', 28153),
(150177, 'esES', '', '¡Acabemos con esto!', 28153),
(150176, 'esES', '', '¡Victoria!', 28153),
(150175, 'esES', '', '¡Una aventura de verdad! Una isla inexplorada, peligros desconocidos y tesoros ocultos... Un momento, ¿qué hace aquí la Horda?', 28153),
(150174, 'esES', '', 'Veamos qué aventuras nos esperan aquí. Lo único que tenemos que hacer es librarnos de la Horda.', 28153),
(150173, 'esES', '', 'Moradores de la oscuridad, ¡no prevaleceréis! ¡La venganza de la Luz caerá sobre vosotros!', 28153),
(150172, 'esES', '', 'Saludos.', 28153),
(150171, 'esES', '', 'La Luz... me redimirá...', 28153),
(150170, 'esES', '', '¡Esto es demasiado fácil!', 28153),
(150169, 'esES', '<Kua\'fon te saluda con un graznido>.\n\n¡Prrii!', '', 28153),
(150168, 'esES', '<Kua\'fon agita la cabeza con fuerza hacia ti>.', '', 28153),
(150166, 'esES', '<Kua\'fon gorjea de forma juguetona>.', '', 28153),
(150165, 'esES', '', '¡Su alma alimentará el Vacío!', 28153),
(150164, 'esES', '<Kua\'fon inclina la cabeza a un lado cuando te acercas>.\n\n¿Prrii?', '', 28153),
(150163, 'esES', '', '¡POR EL VACÍO!', 28153),
(150162, 'esES', '', 'Aquí, desembarcamos aquí. ¡Me lo han dicho los susurros! Ja, ja, ja. ¡Sí!', 28153),
(150161, 'esES', '', '¿Qué? ¿Quién ha dicho eso?', 28153),
(150160, 'esES', '', 'Ja, ja, ja, ja... Me voy al Vacío...', 28153),
(150159, 'esES', '', '¡Alimentaos, mis mascotas!', 28153),
(150158, 'esES', '', '¡Deliciosas almas para el Vacío!', 28153),
(150157, 'esES', '¡Siente la entropía!', '', 28153),
(150156, 'esES', 'Patético.', '', 28153),
(150155, 'esES', 'Los salvajes de la Horda ya están aquí. Pff, como si pudieran hacer algo contra el Vacío...', '', 28153),
(150154, 'esES', '¡Contra kóbolds en las Catacumbas!', '¡Contra kóbolds en las Catacumbas!', 28153),
(150153, 'esES', 'Entre kóbolds y catacumbas.', 'Entre kóbolds y catacumbas.', 28153),
(150152, 'esES', 'Buscabas botín, ¿será este tu fin?', 'Buscabas botín, ¿será este tu fin?', 28153),
(150151, 'esES', '... ¡y temes que esta sea tu tumba!', '... ¡y temes que esta sea tu tumba!', 28153),
(150150, 'esES', 'Vacío, ¡aliméntame!', '', 28153),
(150149, 'esES', 'Se acercan a ti, ya están aquí...', 'Se acercan a ti, ya están aquí...', 28153),
(150148, 'esES', 'Ahora debes correr, trampas hay por doquier y no tienes ni idea de dónde estás.', 'Ahora debes correr, trampas hay por doquier y no tienes ni idea de dónde estás.', 28153),
(150147, 'esES', '¡Acepta el Vacío!', '', 28153),
(150146, 'esES', 'Si les robas su luz, esa será tu cruz, ¡mejor huye sin mirar atrás!', 'Si les robas su luz, esa será tu cruz, ¡mejor huye sin mirar atrás!', 28153),
(150145, 'esES', '¡TÚ NO LLEVARTE VELA!', '¡TÚ NO LLEVARTE VELA!', 28153),
(150144, 'esES', '¡TÚ NO LLEVAR VELA!', '¡TÚ NO LLEVAR VELA!', 28153),
(150143, 'esES', 'Elige del montón, solo hay una excepción...', 'Elige del montón, solo hay una excepción...', 28153),
(150142, 'esES', 'Ojo al pasar, peligros vas a encontrar, mas también todo el oro que uno sueña.', 'Ojo al pasar, peligros vas a encontrar, mas también todo el oro que uno sueña.', 28153),
(150141, 'esES', 'Tesoros hay mil, la tierra es hostil y los puentes no son de fiar.', 'Tesoros hay mil, la tierra es hostil y los puentes no son de fiar.', 28153),
(150140, 'esES', 'Saludos.', '', 28153),
(150139, 'esES', '... hallar riquezas sin igual.', '... hallar riquezas sin igual.', 28153),
(150138, 'esES', 'Ah... La oscuridad... me espera...', '', 28153),
(150137, 'esES', 'Qué grupo más patético... ¡Preparaos para morir!', '', 28153),
(150136, 'esES', '¡Nadie puede seguirme el ritmo!', '', 28153),
(150135, 'esES', 'Tu expedición tiene una misión...', 'Tu expedición tiene una misión...', 28153),
(150134, 'esES', '... y de los tesoros que ahí se encierran llaman a la aventura.', '... y de los tesoros que ahí se encierran llaman a la aventura.', 28153),
(150133, 'esES', '¿Puedo poner ya mi pose de victoria? ¿Qué? ¿Que debería matarlos primero? Bueno, vale.', '', 28153),
(150132, 'esES', 'Leyendas de un mundo bajo tierra...', 'Leyendas de un mundo bajo tierra...', 28153),
(150131, 'esES', '¡Sí!', '¡Sí!', 28153),
(150130, 'esES', '¡Seguro que estáis emocionados de verme! Imaginaos cómo os sentiréis cuando os mate...', '', 28153),
(150129, 'esES', '¡Un barco de la Horda! Me muero por verles la cara cuando se enteren de que estamos aquí...', '', 28153),
(150128, 'esES', '¿Os gustaría cantar una canción?', '¿Os gustaría cantar una canción?', 28153),
(150127, 'esES', 'Je, je.', 'Je, je.', 28153),
(150126, 'esES', '¡Saludos!', '', 28153),
(150125, 'esES', '¡Ja, ja!', '¡Ja, ja!', 28153),
(150124, 'esES', '¡Aquí!', '', 28153),
(150123, 'esES', '¿Qué? ¿Voy demasiado rápido?', '', 28153),
(150122, 'esES', '¡Bien!', '¡Bien!', 28153),
(150121, 'esES', '¡A por ellos!', '¡A por ellos!', 28153),
(150120, 'esES', '¡Ay! ¿quién lo habría imaginado...?', '', 28153),
(150119, 'esES', '¡Oh, vaya!', '¡Oh, vaya!', 28153),
(150118, 'esES', '¡AQUÍ ESTOY! Calma, intentaré ser bueno...', '', 28153),
(150117, 'esES', 'Hola, Horda, soy Kelain. ¡Qué casualidad encontraros aquí!', '', 28153),
(150116, 'esES', '', '¡Largo, escoria!', 28153),
(150115, 'esES', 'Si te cruzah con Grozztok, no dudeh en clavar tu acero en su negro corazón.', '', 28153),
(150114, 'esES', '', '¡Escoria repugnante!', 28153),
(150113, 'esES', '', '¿Cómo osas mancharme de sangre? ¡Ten más cuidado!', 28153),
(150112, 'esES', '', 'Ah, qué desdicha... para la Alianza. Pronto os demostraremos quién manda aquí.', 28153),
(150111, 'esES', 'Grozztok merecía su dehtino. Ehpero que lo hicierah sufrir.', '', 28153),
(150110, 'esES', '', '¡Cielo santo! Qué falta de finura...', 28153),
(150109, 'esES', 'Moriré en ehtah dunah... y me lo merezco.', '', 28153),
(150108, 'esES', '', 'Aaay. Deja que te arregle.', 28153),
(150107, 'esES', '', 'Ah, eres tú. Hola.', 28153),
(150106, 'esES', '', 'Qué poco... satisfactorio...', 28153),
(150105, 'esES', '', '¡Menos mal que tengo guantes! No quiero ensuciarme las manos.', 28153),
(150104, 'esES', '', '¡Aprovechémonos de su debilidad!', 28153),
(150103, 'esES', '', '¡SÍÍÍÍÍ! ¿Habéis visto eso?', 28153),
(150102, 'esES', '', '¿Qué hacemos todavía en el barco? ¡Estamos perdiendo el tiempo! Vamos, ¡vamos!', 28153),
(150101, 'esES', '', '¿Por qué estoy aquí cuando podría estar luchando?', 28153),
(150100, 'esES', 'Ahora que tenemos las llaves del sobrestante, podemos liberar a nuestro recurso y usar sus habilidades para respaldar el esfuerzo de guerra.', '', 28153),
(150099, 'esES', '', '¡Ja, ja! ¡Buen intento!', 28153),
(150098, 'esES', '', '¡Más rápido!', 28153),
(150097, 'esES', 'La Dama Oscura estará satisfecha.', '', 28153),
(150096, 'esES', '', 'No es... justo... Sois... horribles...', 28153),
(150095, 'esES', '', '¡Vamos! ¡Al ataque!', 28153),
(150094, 'esES', '', '¡Nadie puede huir de mí!', 28153),
(150093, 'esES', '¡Muerte a este objetivo!', '', 28153),
(150092, 'esES', 'Un destino inevitable.', '', 28153),
(150091, 'esES', 'Arrebátale las llaves, hazte con nuestro recurso y acaba con todo el que se interponga en tu camino.', '', 28153),
(150090, 'esES', 'Es la hora. Recordad vuestro entrenamiento y demostradle a la Alianza lo que significa ser Altonato.', '', 28153),
(150089, 'esES', 'Ábrete paso hasta el piso superior, donde encontrarás al sobrestante. ', '', 28153),
(150088, 'esES', 'Preparaos, hay poderosos enemigos por aquí. Y también está la Alianza.', '', 28153),
(150087, 'esES', 'Una fuga reciente ha desatado el caos en los niveles inferiores de la prisión. Cosa que puede venirnos bien.', '', 28153),
(150086, 'esES', 'Canalizad vuestra energía: la Alianza está aquí. No cometeremos errores.', '', 28153),
(150085, 'esES', 'Nuestro objetivo está en Tol Dagor.', '', 28153),
(150084, 'esES', 'Saludos.', '', 28153),
(150083, 'esES', 'Rápido... Retirada...', '', 28153),
(150082, 'esES', '¡Al ataque, según el plan!', '', 28153),
(150081, 'esES', '¡Detrás de mí! ¡Al asalto!', '', 28153),
(150080, 'esES', '¡Oh, oh, oh! ¡Objetivo prioritario!', '', 28153),
(150079, 'esES', '¡He matado a uno!', '', 28153),
(150078, 'esES', 'Ay, ¡la Horda está aquí! ¿Seguro que queréis hacer esto? Tengo instrumentos delicados... ¡y muy CAROS!', '', 28153),
(150077, 'esES', '¡Hola!', '', 28153),
(150076, 'esES', 'Yo... tenía... razón...', '', 28153),
(150075, 'esES', '¡$n se ha cargado por completo!', '¡$n se ha cargado por completo!', 28153),
(150074, 'esES', '¡$n empieza a rebosar de poder!', '¡$n empieza a rebosar de poder!', 28153),
(150073, 'esES', '¡Largo!', '', 28153),
(150072, 'esES', 'El nivel de poder de $n vuelve a aumentar...', 'El nivel de poder de $n vuelve a aumentar...', 28153),
(150071, 'esES', 'No sé si esto es lo correcto...', '', 28153),
(150070, 'esES', 'El nivel de poder de $n crece...', 'El nivel de poder de $n crece...', 28153),
(150069, 'esES', '', '¡Médico!', 28153),
(150068, 'esES', '¡Una chispa caótica irrumpe en el campo de batalla!', '¡Una chispa caótica irrumpe en el campo de batalla!', 28153),
(150067, 'esES', '', 'Objetivo eliminado.', 28153),
(150066, 'esES', 'Un núcleo de energía se forma cerca.', 'Un núcleo de energía se forma cerca.', 28153),
(150065, 'esES', '', 'Preparaos, hay Horda por aquí. ¡Disparad primero y despojad después!', 28153),
(150064, 'esES', '', 'No rechaces una buena oferta.', 28153),
(150063, 'esES', '', '¡Retirada!', 28153),
(150062, 'esES', '¡Un ser de energía pura toma forma en el aire delante de ti!', '¡Un ser de energía pura toma forma en el aire delante de ti!', 28153),
(150061, 'esES', '', 'Uff... Eso escuece...', 28153),
(150060, 'esES', '', 'El enemigo avanza.', 28153),
(150059, 'esES', '', 'A por la cabeza, ¡es su punto débil!', 28153),
(150058, 'esES', 'Hora de acabar con el enemigo.', '', 28153),
(150057, 'esES', '¿Quién lleva un cuchillo a una pelea de mecas?', '', 28153),
(150056, 'esES', '¡Me he quedado sin mecazancudo! ¡Retirada!', '', 28153),
(150055, 'esES', '¡El mecazancudo ha caído! ¡Retirada!', '', 28153),
(150054, 'esES', 'Te he hecho puré.', '', 28153),
(150053, 'esES', 'El único insecto bueno es el que está muerto. Y la Horda me recuerda mucho a los insectos.', '', 28153),
(150052, 'esES', 'La violencia ha resuelto más problemas a lo largo de la historia que ninguna otra cosa. Vamos a añadir uno más.', '', 28153),
(150051, 'esES', 'La Horda está aquí, así que más vale que hagáis vuestro trabajo. Si no cumplís, os mataré. ¡En formación!', '', 28153),
(150050, 'esES', '¡Hora de alistarse!', '', 28153),
(150049, 'esES', '¡Fuego va!', '', 28153),
(150048, 'esES', 'No me... falléis...', '', 28153),
(150047, 'esES', 'Un poco de vidilla, ¡tenemos compañía!', '', 28153),
(150046, 'esES', '¡VAMOS ALLÁ!', '', 28153),
(150044, 'esES', '¡Hora de reparar!', '', 28153),
(150043, 'esES', '¡Cava más deprisa, el tesoro tiene que estar por aquí!', '¡Cava más deprisa, el tesoro tiene que estar por aquí!', 28153),
(150041, 'esES', '¡Bam!', '', 28153),
(150040, 'esES', 'Afilad las navajas: tenemos cuerpos de los que deshacernos. Despacio y en silencio.', '', 28153),
(150039, 'esES', '¿Qué hay?', '', 28153),
(150038, 'esES', '¡Soy demasiado rápido!', '', 28153),
(150037, 'esES', '¡Ja!... No sois... nada...', '', 28153),
(150036, 'esES', 'Mucho ojo, Alianza.', '', 28153),
(150035, 'esES', '', 'A nuehtro pueblo le asuhta el tipo de cambio que sugiere Talanji. El miedo hace que la gente cometa ehtupideceh.', 28153),
(150034, 'esES', '', 'Cañones, ¡preparaos para disparar!', 28153),
(150033, 'esES', '', 'Me estoy cansando de este juego. ¡Reduciré Boralus a cenizas antes de dejaros ganar!', 28153),
(150032, 'esES', '', '¿¡Osáis herir a mi hermosa mascota!?', 28153),
(150031, 'esES', '', 'Siguiente objetivo.', 28153),
(150030, 'esES', '', 'Todo va según lo previsto.', 28153),
(150029, 'esES', '', 'Lo tengo todo planeado. Es un plan atrevido y eficaz, como tiene que ser. ¡Que nadie lo ignore!', 28153),
(150028, 'esES', '', 'Interesante armadura... Aunque le hacen falta más pinchos.', 28153),
(150027, 'esES', '', 'Esto no... nos detendrá...', 28153),
(150026, 'esES', '', '¡Zap!', 28153),
(150025, 'esES', '', '¡Por Kul Tiras!', 28153),
(150024, 'esES', '', 'Este plan no está demasiado meditado, ¿verdad?', 28153),
(150023, 'esES', 'Vuelta al trabajo.', '', 28153),
(150022, 'esES', '¡Hora de triturar!', '', 28153),
(150021, 'esES', '¡Eh! ¡Reparar eso es muy caro!', '', 28153),
(150020, 'esES', '', '¡La puerta ha caído! ¡Entrad en la ciudad y matad a todo el que se oponga a mí!', 28153),
(150019, 'esES', 'Montón de chatarra.', '', 28153),
(150018, 'esES', '¡Ja, ja, ja! ¡Cling-cling!', '', 28153),
(150017, 'esES', 'Este lugar tiene mucho que ofrecer: sombra, botín... ¿La Alianza? Ya nos han arruinado el día.', '', 28153),
(150016, 'esES', 'Aquí veo oportunidades de negocio... Incluso puede que consigamos vender a la Alianza como chatarra.', '', 28153),
(150015, 'esES', '', 'Permitidme demostrároslo.', 28153),
(150014, 'esES', '', 'Disfrutad de vuestra victoria fútil, necios. Sin la flota de Kul Tiras no podréis derrotarme.', 28153),
(150013, 'esES', '¿Oléis eso? Huele a que vamos a pillar botín. ¡Preparad las bolsas!', '', 28153),
(150012, 'esES', '¿Qué pasa?', '', 28153),
(150011, 'esES', 'Esto no ha acabado...', '', 28153),
(150010, 'esES', '', '¡Lo habéis conseguido! Sin el gigante, las fuerzas de Gobernalle tendrán que abandonar la ciudad.', 28153),
(150009, 'esES', '¡Para eso construí esta belleza!', '', 28153),
(150008, 'esES', '¡Seguro desconectado!', '', 28153),
(150007, 'esES', '¡A la refriega!', '', 28153),
(150006, 'esES', 'Uy, ¿demasiado brusco?', '', 28153),
(150005, 'esES', '¡Oaaa! ¿Ya hemos llegado? Pero si es el mejor momento para echarse una siesta...', '', 28153),
(150004, 'esES', 'Si dejáramos de luchar, no tendría que estar haciendo esto.', '', 28153),
(150003, 'esES', 'Alguien tendrá que lamerte las heridas...', '', 28153),
(150002, 'esES', 'Grrr... ¡Hola!', '', 28153),
(150001, 'esES', 'Ah, por fin un descanso...', '', 28153),
(150000, 'esES', '¡Hora de descansar!', '', 28153),
(149999, 'esES', 'Ja, ja, ja. Deberíais huir... ¡No os perseguiremos!', '', 28153),
(149998, 'esES', '', '¡Empieza a rezar!', 28153),
(149997, 'esES', '', '¡Ahora necesito una nueva presa!', 28153),
(149996, 'esES', '', 'Aaah... ¡Huele a presas! Nada como una buena persecución antes de matar...', 28153),
(149995, 'esES', '', 'Hueles raro.', 28153),
(149994, 'esES', '', 'Ah... El dulce olor de la sangre...', 28153),
(149993, 'esES', '', '¿A quién le toca?', 28153),
(149992, 'esES', '', '¡A la yugular!', 28153),
(149991, 'esES', '¡Bien hecho, adalid! Estas tierras son más seguras gracias a tus esfuerzos.', '', 28153),
(149990, 'esES', '¡A por el golpe de gracia!', '', 28153),
(149989, 'esES', '¡Eso leh mohtrará el poder de loh Zandalari!', '', 28153),
(149988, 'esES', 'Huelo tu miedo.', '', 28153),
(149987, 'esES', '¡Eso sí que ha sido divertido!', '', 28153),
(149986, 'esES', '¡La Horda! Esto huele a persecución. ¡Que comience la caza! ¡Auuu!', '', 28153),
(149985, 'esES', 'Nuestros espías han detectado una amenaza peligrosa en la zona. ¡Búscala y elimínala!', '', 28153),
(149984, 'esES', 'Sniff, sniff. ¡La Horda! Ojalá el viento soplara en otra dirección...', '', 28153),
(149983, 'esES', '', 'Da igual. Pronto mis cañones reducirán al enemigo a cenizas.', 28153),
(149982, 'esES', 'No os separéis de la manada. ¡Huelo algo repugnante en el aire!', '', 28153),
(149981, 'esES', '¡Grrrr!', '', 28153),
(149980, 'esES', 'No es tan fácil librarse... del líder de la manada...', '', 28153),
(149979, 'esES', '¡Pagará por ehta herejía! ¡Di chuka Rezan!', '', 28153),
(149978, 'esES', '¡Hay que descuartizar al enemigo!', '', 28153),
(149977, 'esES', '¡Auuu! Jauría de Lobos, ¡atacad!', '', 28153),
(149976, 'esES', '', '¡Me pido la cabeza!', 28153),
(149975, 'esES', '', 'Ooh, ehta ihla promete. Apartad, ¡tengo mucho vudú que hacer!', 28153),
(149974, 'esES', '', 'Yo te curo.', 28153),
(149973, 'esES', '', '¡Tieneh una buena cabeza! ¿Me la puedo quedar cuando muerah?', 28153),
(149972, 'esES', '', 'Ah, pero loh Lanza Negra... nunca mueren...', 28153),
(149971, 'esES', '', '¡Toma maleficio!', 28153),
(149970, 'esES', '', '¡Fatalidad!', 28153),
(149969, 'esES', '', 'Tú, ¡deja que te reduzca la cabeza!', 28153),
(149968, 'esES', 'A por ese objetivo.', '', 28153),
(149967, 'esES', 'Te he ganado.', '', 28153),
(149966, 'esES', 'Ehta eh una buena ihla, me pregunto qué encontraremoh en ella...', '', 28153),
(149965, 'esES', '¿Qué hay?', '', 28153),
(149964, 'esES', 'Solo quiero dormir un ratito...', '', 28153),
(149963, 'esES', 'A dormir.', '', 28153),
(149962, 'esES', '¿De dónde han salido y qué ehtán haciendo aquí?', '', 28153),
(149961, 'esES', '', '¡GRRRRRR!', 28153),
(149960, 'esES', '', '¡Máh sangre!', 28153),
(149959, 'esES', '', '¡Máh! ¡Traedme máh!', 28153),
(149958, 'esES', '', 'Equipo... Ehtrategia... Bah, ¡matadloh sin máh! ¡Grrrrrr!', 28153),
(149957, 'esES', '', '¡Alianza! ¡Matadloh! Traedme suh corazoneh...', 28153),
(149956, 'esES', '', '¡Perseguidloh! ¡Dehtripadloh! Sangre por doquier... ¡Ja, ja, ja!', 28153),
(149955, 'esES', '', '¿Qué?', 28153),
(149954, 'esES', '', 'Muero como una guerrera...', 28153),
(149953, 'esES', '', '¡Suh brazoh como trofeo!', 28153),
(149952, 'esES', 'Ahora estoy... ¡Ahora no estoy!', '', 28153),
(149951, 'esES', '¡Congelación!', '', 28153),
(149950, 'esES', 'Vaya, vaya... Hola.', '', 28153),
(149949, 'esES', 'Buena... ejecución...', '', 28153),
(149948, 'esES', '¡Una muerte más para mi contador! Seguro que voy en cabeza.', '', 28153),
(149947, 'esES', '¡Vamos allá!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'esES', 'Antes tendrás que comprarte una cara nueva.', 'Antes tendrás que comprarte una cara nueva.', 28153),
(149945, 'esES', '', 'Veo indecisión en tus ojos, $n.\n\nTe concedo permiso para preguntarme por mis planes, si lo deseas.', 28153),
(149944, 'esES', 'Jefa de Guerra, ¿puedo preguntar por qué queremos capturar Teldrassil?', 'Jefa de Guerra, ¿puedo preguntar por qué queremos capturar Teldrassil?', 28153),
(149943, 'esES', '¿Oportunidad?', '¿Oportunidad?', 28153),
(149942, 'esES', 'No se sabe, Jefa de Guerra.', 'No se sabe, Jefa de Guerra.', 28153),
(149940, 'esES', '', 'Lo que está claro es que la Alianza usará Darnassus como un punto seguro desde el que canalizar azerita y enviarla a los Reinos del Este. Anduin Wrynn construirá armas nuevas y poderosas, y será cuestión de tiempo que las utilice para atacar nuestros hogares. Primero irá a por Entrañas y Lunargenta, y luego posará la mirada sobre Kalimdor.\n\nPor el futuro de la Horda, debemos dar nosotros el primer paso.\n\nSi ocupamos Darnassus, controlaremos el flujo de azerita y nos aseguraremos de que no puedan usarla contra nosotros. La Alianza no se atreverá a atacar su propia ciudad por miedo a herir a los civiles.\n\nCon un único golpe, garantizaremos la paz durante generaciones.', 28153),
(149939, 'esES', '', 'Aunque no nos sobra el tiempo, respeto tu deseo de saber más.\n\n<Sylvanas señala Silithus en el mapa>.\n\nEsto ha cambiado para siempre el equilibrio de poder en Azeroth.\n\nSe están encontrando depósitos de azerita por todo el mundo, $n. Aunque aún no comprendemos del todo su auténtico potencial, está claro que esta sustancia tiene una capacidad destructiva impresionante.\n\n¿Cómo será la guerra dentro de veinte años? ¿Y dentro de cien?\n\n¿Qué esperanza le queda a la Horda de defender sus fronteras si la Alianza controla el flujo de azerita?', 28153),
(149938, 'esES', '', '¿Quieres hacerme una pregunta, $n?', 28153),
(149937, 'esES', 'Los infieles tienen bestias salvajes encerradas cerca de aquí. Parece una buena oportunidad...', '', 28153),
(149936, 'esES', 'Parece que ha llegado la Horda. Esto se va a poner... interesante.', '', 28153),
(149935, 'esES', 'No hay por qué acercarse tanto.', '', 28153),
(149934, 'esES', '¡Que sienta el frío!', '', 28153),
(149933, 'esES', 'Hola, hermosura.', '', 28153),
(149932, 'esES', 'Buen golpe... Hasta que... volvamos a vernos...', '', 28153),
(149931, 'esES', '¡Ja! ¡Otra muerte más para mí!', '', 28153),
(149930, 'esES', '¡Mi cuerpo está listo!', '', 28153),
(149929, 'esES', 'Aunque estas armas nos darán una ventaja aún mayor.', '', 28153),
(149928, 'esES', '¿Te gustan mis alas nuevas? ¡Son tan rápidas que no hay manduka que se me escape!$b$bNi makaku.$b$b$b$bAsquerosos makakus.', '', 28153),
(149927, 'esES', 'La manduka de Zandalar es rara. Está dingue salada y a veces te contesta.', '', 28153),
(149926, 'esES', '¡La Horda! ¡Al fin un poco de acción! Será mejor que me quite la camisa...', '', 28153),
(149925, 'esES', 'Kua\'fon chilla de alegría y engulle la comida.', '', 28153),
(149924, 'esES', 'Kua\'fon olfatea la comida antes de devorarla con entusiasmo.', '', 28153),
(149923, 'esES', 'Kua\'fon muerde la comida en el aire.', '', 28153),
(149922, 'esES', 'Kua\'fon se abalanza sobre la comida y se la traga entera.', '', 28153),
(149921, 'esES', 'Hay muchos secretos, tanto misteriosos como divinos, tú tienes los tuyos y yo los míos.', '', 28153),
(149920, 'esES', '¿Prrii?', '', 28153),
(149919, 'esES', '¡PRRIIIIIII!', '', 28153),
(149918, 'esES', '¡Prrii!', '', 28153),
(149917, 'esES', 'PRRII.', '', 28153),
(149916, 'esES', '¿Hozen voladores? ¿Cómo?', '¿Hozen voladores? ¿Cómo?', 28153),
(149915, 'esES', '¡Toca una retirada táctica!', '', 28153),
(149914, 'esES', '¡Yo me encargo!', '', 28153),
(149913, 'esES', 'Sé que soy el mejor. Estoy acostumbrado a tener público.', '', 28153),
(149912, 'esES', 'No tenemoh muchoh suminihtroh, pero puedo sacar algo pa ti. Si noh ayudah, probablemente pueda conseguirte algo de lo bueno.', 'No tenemoh muchoh suminihtroh, pero puedo sacar algo pa ti. Si noh ayudah, probablemente pueda conseguirte algo de lo bueno.', 28153),
(149911, 'esES', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Comida de dinosaurio de corral]|h|r>', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Comida de dinosaurio de corral]|h|r>', 28153),
(149910, 'esES', 'Tenemos el mejor sitio, el tesoro está aquí.', 'Tenemos el mejor sitio, el tesoro está aquí.', 28153),
(149909, 'esES', 'Esto... no ha acabado...', '', 28153),
(149908, 'esES', '<Kua\'fon te inspecciona las manos en busca de comida>.\n\n¿Prriii? PRRII.', '', 28153),
(149907, 'esES', 'Ese es... tu... lugar.', '', 28153),
(149906, 'esES', '¡Fuera, Horda! Panda de chuchos...', '', 28153),
(149905, 'esES', '¡Nadie se mueve como yo!', '', 28153),
(149904, 'esES', 'La Horda... Sucios, estúpidos, sin imaginación. ¿Cómo habéis encontrado esta isla? Seguro que por casualidad.', '', 28153),
(149903, 'esES', 'Por el bien de la Horda, hablaré despacio: Isla... nuestra. Horda... fuera. ¿Os queda lo bastante claro?', '', 28153),
(149902, 'esES', '¡Salvajes de la Horda! Aceptamos vuestra rendición si nos entregáis toda vuestra azerita. Espero que tengáis el cerebro suficiente para aceptar mi oferta.', '', 28153),
(149901, 'esES', '', '¿Sí? ¿Nos conocemos?', 28153),
(149900, 'esES', '', 'Cielos, ¿es así como os vestís en la Alianza? No sé si mataros o dejar que os muráis de la vergüenza.', 28153),
(149899, 'esES', '', '¿Ese es el barco de la Alianza? ¿Lo ha atacado un gigante de mar o es que es así?', 28153),
(149898, 'esES', '¿No hace calor? Si es que es llegar yo y empezar a subir la temperatura...', '', 28153),
(149897, 'esES', '¡Te has quemado!', '', 28153),
(149896, 'esES', '¡Más fuego!', '', 28153),
(149895, 'esES', '¡Quiero fuego!', '', 28153),
(149894, 'esES', 'Sabotearé los cañones de los niveles superiores mientras tú quemas el barranco. Reúnete conmigo en los fosos de bestias cuando termines.', '', 28153),
(149893, 'esES', '', 'Ojalá pudiera matar a miembros de la Alianza sin tener que mirarlos...', 28153),
(149892, 'esES', 'Podéis quitaros esa peste en el océano o bañaros en mis llamas. La elección es vuestra.', '', 28153),
(149891, 'esES', 'Puaj, ¿a qué huele? Ah, la Alianza ha mandado a sus mejores agentes... ¿Sabéis por qué apestan así? Es porque comen mucho queso.', '', 28153),
(149890, 'esES', 'Que la Luz nos bendiga.', '', 28153),
(149889, 'esES', 'Has luchado bien. Yo he luchado mejor.', '', 28153),
(149888, 'esES', '¡Me retiro!', '', 28153),
(149887, 'esES', '¡Que la Luz te cure!', '', 28153),
(149886, 'esES', 'Ooh, la Alianza. Con el día tan estupendo que estaba teniendo... ¿Por qué no me hacéis un favor y os largáis?', '', 28153),
(149885, 'esES', 'Esta isla es nuestra, Alianza. Si os vais ahora, la violencia no será necesaria.', '', 28153),
(149884, 'esES', '¡El enemigo está aquí!', '', 28153),
(149883, 'esES', '¡$n comienza a lanzar Gran sanación!', '¡$n comienza a lanzar Gran sanación!', 28153),
(149882, 'esES', '', 'Si no encontráis ninguno, abridlo vosotros. El tiempo es un lujo del que no disponemos.', 28153),
(149881, 'esES', '', 'Entonces está decidido. Colmillosauro, Nathanos, partid sin demora.', 28153),
(149880, 'esES', 'La mayoría de los contrabandistas preferirá no llamar la atención del Alto Señor Supremo... pero creo que puedo convencer a alguien de que nos ayude.', '', 28153),
(149879, 'esES', 'No me creo que Vista Eterna consiga todos sus suministros de forma legítima. Alguien está usando una ruta oculta para atravesar Frondavil.', '', 28153),
(149878, 'esES', '¿Perdón?', '', 28153),
(149877, 'esES', 'Mmm... ¿Conoces a algún contrabandista, Clamañublo?', '', 28153),
(149876, 'esES', '', 'Aplastaremos a Malfurion desde ambos lados.', 28153),
(149875, 'esES', '', 'Colmillosauro, llévate a un escuadrón a Frondavil. Buscad un camino por la montaña hasta Costa Oscura, pero dejad las armas de asedio bajo mi mando.', 28153),
(149874, 'esES', '', 'Parece que los fuegos fatuos se distraen fácilmente. Podemos aprovechar esta debilidad para pasar.', 28153),
(149873, 'esES', 'Jefa de Guerra, no hay ningún camino seguro por Frondavil.', '', 28153),
(149872, 'esES', '', 'Zuldazar, una de las pocas ciudades que también prosperan tras sobrevivir al Cataclismo. En su apogeo, el Imperio Zandalari dominaba medio mundo. En Suramar, aún prevenimos a los niños sobre los trols y sus oscuras artes.\n\nLos teníamos por salvajes sedientos de sangre. Pero viendo esto... no cuesta preguntarse quiénes son los que necesitan al otro, si los Zandalari o la Horda.', 28153),
(149871, 'esES', '', 'La furia de los vulperas se alza de las arenas para reclamar venganza. ¡Y la obtendré!', 28153),
(149870, 'esES', '', '¡La muerte llama a vuestra puerta, infieles!', 28153),
(149869, 'esES', '', 'A Zoram\'gar, ¡rápido!', 28153),
(149868, 'esES', 'La ceremonia está lista para comenzar.', 'La ceremonia está lista para comenzar.', 28153),
(149867, 'esES', 'Vaya, esto es un poco embarazoso.\n\nTenía el discurso escrito en el cuaderno, pero debo de haberlo... perdido.\n\nTiene que estar en esta sala, en alguna parte. ¡Si me ayudaras a encontrarlo, te estaría eternamente agradecido!', '', 28153),
(149866, 'esES', 'Ah, hola. Me temo que no nos conocemos, pero te agradezco que hayas venido por mi querida Lucille.\n\n¿En qué puedo ayudarte?', '', 28153),
(149865, 'esES', '¡No te preocupeh, Vaza se encargará de ti en Nazmir!', '', 28153),
(149864, 'esES', 'Lucille no sabe que yo la visitaba siempre que venía a la Arboleda Blanca.\n\nSu desesperación por lo que sucedió en este lugar debe de estar impidiéndole ver mi espíritu. Espero que al menos parte de ella sepa que estoy aquí.', '', 28153),
(149858, 'esES', 'Y ahora debes unirte a ellos. Que Sethraliss te perdone.', '', 28153),
(149857, 'esES', '¡TENEMOS UNA PELEA!', '¡TENEMOS UNA PELEA!', 28153),
(149856, 'esES', 'Kua\'fon devora el pez.', '', 28153),
(149855, 'esES', 'Kua\'fon olfatea con recelo el pescado.', '', 28153),
(149854, 'esES', '<Ofrecer carne de Aletabrillante>.', '<Ofrecer carne de Aletabrillante>.', 28153),
(149853, 'esES', '<Kua\'fon se encoge de miedo y se aparta cuando te acercas>.$b$bTal vez necesite un poco de persuasión. ¿Quizás con una chuchería?', '', 28153),
(149852, 'esES', 'Siempre...', '', 28153),
(149851, 'esES', 'Siempre estaré aquí, mi querida Lucille...', '', 28153),
(149850, 'esES', '', 'Oh, Alexander... Ojalá estuvieras aquí ahora...', 28153),
(149849, 'esES', 'Gracias.', '', 28153),
(149848, 'esES', 'Por fin... puedo dejar atrás los recuerdos de este lugar.', '', 28153),
(149847, 'esES', 'No, viejo amigo. Nuestra gente ha muerto por tu culpa.', '', 28153),
(149846, 'esES', 'Vorrik, yo no he obligado a nadie a seguirme... Somos un pueblo de conquistadores.', '', 28153),
(149845, 'esES', 'Lamentarás... lo que has visto...', 'Lamentarás... lo que has visto...', 28153),
(149844, 'esES', 'Lady Crestavía es una poderosa enemiga...', 'Lady Crestavía es una poderosa enemiga...', 28153),
(149843, 'esES', '', '¡Más te vale!', 28153),
(149842, 'esES', 'No te preocupes, yo me ocuparé de este estorbo.', 'No te preocupes, yo me ocuparé de este estorbo.', 28153),
(149841, 'esES', '', '¡Idiota! ¡No debe haber ningún testigo!', 28153),
(149840, 'esES', 'Parece que tenemos visita...', 'Parece que tenemos visita...', 28153),
(149839, 'esES', 'Siempre es un placer hacer negocios contigo, milady.', 'Siempre es un placer hacer negocios contigo, milady.', 28153),
(149838, 'esES', '', 'Aquí tienes tu dinero. ¡Cógelo antes de que alguien te vea!', 28153),
(149837, 'esES', '¡Una emboscada! Lucille, ¡detrás de mí! Guardias, ¡a las armas!', '', 28153),
(149836, 'esES', '', 'Alexander, ¡no!', 28153),
(149835, 'esES', 'No es nada personal.', 'No es nada personal.', 28153),
(149834, 'esES', 'Alexander, ¿has preparado...? Espera, ¿qué es eso?', '', 28153),
(149833, 'esES', 'Como señor gobernante de Drustvar y orgulloso padre de Lucille, para mí es un honor casarlos en presencia de la tierra, el cielo y el mar.', '', 28153),
(149832, 'esES', 'Familiares, amigos y estimados invitados. Nos hemos reunido en este magnífico día otoñal para celebrar la unión entre Lucille y Alexander.', '', 28153),
(149831, 'esES', 'Muy bien.', '', 28153),
(149830, 'esES', '', 'Por supuesto. Adelante, padre.', 28153),
(149829, 'esES', '¿Procedemos?', '', 28153),
(149828, 'esES', 'Ahora mismo baja. Me ha pedido que vaya empezando por ella.', '', 28153),
(149827, 'esES', '', 'No pasa nada, padre. ¿Y madre?', 28153),
(149826, 'esES', 'Por favor, perdonad la tardanza.', '', 28153),
(149825, 'esES', 'Pero ¿dónde está lady Crestavía?', '', 28153),
(149824, 'esES', '', '¡Aquí viene!', 28153),
(149823, 'esES', 'Y transmíteles mis disculpas por el retraso.', '', 28153),
(149822, 'esES', 'Por favor, informa a la feliz pareja de que bajaré dentro de poco.', '', 28153),
(149821, 'esES', '¡Ah, lo has encontrado! ¡Gracias a las mareas!', '', 28153),
(149820, 'esES', '', '¡¿Intentas hacernos perder el tiempo?!', 28153),
(149819, 'esES', '', 'Estamos buscando un libro, ¿acaso crees que no habríamos mirado ya en la estantería?', 28153),
(149818, 'esES', '', '¿Por qué metería mi marido su cuaderno en la mochila de Lucille? ¡Qué tontería!', 28153),
(149817, 'esES', 'No creo que esté entre las cartas de Lucille, pero no está de más comprobarlo.', '', 28153),
(149816, 'esES', 'Aunque agradezco tu ayuda, debo pedirte que no hurgues entre la ropa interior de mi hija...', '', 28153),
(149815, 'esES', '', 'Su corazón no le hace ningún bien a nuestra casa...', 28153),
(149814, 'esES', 'Lucille solo sigue a su corazón, Meredith. Como hice yo cuando me casé contigo.', '', 28153),
(149813, 'esES', '', 'Arthur, no deberías permitirlo. ¿Nuestra hija, casada con un mercader común y corriente?', 28153),
(149812, 'esES', '', 'Gracias por venir. Es un honor que estéis aquí.', 28153),
(149811, 'esES', '¿Por qué has venido aquí?', '', 28153),
(149810, 'esES', '¿Lucy? Has venido... Espera, tú no eres Lucy.', '', 28153),
(149809, 'esES', 'Tampoco tú ereh bienvenida. Tu padre no aprueba que hayah traído aquí a esah criaturah. Me ha ordenado que te lleve ante él.', '', 28153),
(149807, 'esES', 'He asegurado mi victoria pase lo que pase aquí. El general Jakra\'zet ya tiene mi llave, y supongo que la tuya también a estas alturas.', '', 28153),
(149806, 'esES', '¿Qué has hecho, Korthek?', '', 28153),
(149805, 'esES', 'Tengo una duda, Vorrik... Si tú estás aquí, ¿quién está guardando las llaves en tu templo?', '', 28153),
(149804, 'esES', '', '[PH] Vivo para defender a mi gente. ¡Caerás a manos de esta escoria!', 28153),
(149803, 'esES', '[PH] ¡Escoria vulpera, solo vives para servir a mi imperio!', '', 28153),
(149802, 'esES', '', '', 28153),
(149801, 'esES', '¡Voy a comprarme dientes nuevos, de oro!', '¡Voy a comprarme dientes nuevos, de oro!', 28153),
(149800, 'esES', 'Mantendremos sellada la prisión de Mythrax y uniré a nuestro pueblo.', '', 28153),
(149799, 'esES', 'Hacemos todo el trabajo, deberíamos llevarnos todo el oro.', 'Hacemos todo el trabajo, deberíamos llevarnos todo el oro.', 28153),
(149798, 'esES', 'No, eres nuestro fracaso. Sethraliss se sacrificó para que pudiéramos vivir en paz.', '', 28153),
(149797, 'esES', '¡Soy el verdadero poder de los sethrak!', '', 28153),
(149796, 'esES', 'Más vale que nadie intente quitarme mi parte.', 'Más vale que nadie intente quitarme mi parte.', 28153),
(149795, 'esES', '¡Como lo encuentre, no nos volvéis a ver el pelo ni a mí ni al tesoro!', '¡Como lo encuentre, no nos volvéis a ver el pelo ni a mí ni al tesoro!', 28153),
(149794, 'esES', '¡Quien encuentre el tesoro se llevará una parte más grande!', '¡Quien encuentre el tesoro se llevará una parte más grande!', 28153),
(149793, 'esES', '¡Tres millones en monedas de oro, vamos a ser ricos!', '¡Tres millones en monedas de oro, vamos a ser ricos!', 28153),
(149792, 'esES', '¿Estaremos cavando en el lugar equivocado?', '¿Estaremos cavando en el lugar equivocado?', 28153),
(149791, 'esES', 'Me voy a comprar un castillo con un baño caliente y sirvientes.', 'Me voy a comprar un castillo con un baño caliente y sirvientes.', 28153),
(149790, 'esES', 'Nedly dice que estamos cerca, que lo conseguiremos cualquier día de estos.', 'Nedly dice que estamos cerca, que lo conseguiremos cualquier día de estos.', 28153),
(149789, 'esES', '¡Voy a comprar un barco más grande que cualquiera de los de la flota!', '¡Voy a comprar un barco más grande que cualquiera de los de la flota!', 28153),
(149788, 'esES', '¿Cuánto son 3 millones divididos entre 267?', '¿Cuánto son 3 millones divididos entre 267?', 28153),
(149787, 'esES', '¡Es tanto que Jaina Valiente se casará conmigo por mi dinero!', '¡Es tanto que Jaina Valiente se casará conmigo por mi dinero!', 28153),
(149786, 'esES', '', 'Bueno, eso pasa de vez en cuando.', 28153),
(149785, 'esES', '', 'Por primera vez sentirán el viento bajo las alas. ¡La alegría de volar! El...', 28153),
(149784, 'esES', '', '¡Ah, otro que responde a la llamada de los cielos!', 28153),
(149783, 'esES', 'Vuelve pronto. Debemos atacar al emperador Korthek cuanto antes.', '', 28153),
(149782, 'esES', 'Me quedaré aquí para preparar nuestro ataque mientras tú siembras el caos entre los infieles.', '', 28153),
(149781, 'esES', '<Empujar a la cría fuera del nido>.', '<Empujar a la cría fuera del nido>.', 28153),
(149779, 'esES', '[Escena de cliente - Taelia se acerca para acusar a lady Gobernalle de estar detrás del ataque. ¿No lo ves, Katherine? Reemplazarte era su plan desde el principio. Katherine se vuelve hacia Priscilla: ¿Es eso cierto? Priscilla deja de hacerse la amable y comprensiva. Ataca a Katherine con dureza: ¡Débil! ¡No eres digna de gobernar! ¡Gobernalle CONSTRUYÓ esta ciudad! Dispara a Katherine con su pistola. Los guardias entran en acción. Priscilla dispara a las barricas de un carro cercano a la multitud, que liberan una nube de humo que envuelve rápidamente la plaza. Cunde el caos].', '[Escena de cliente - Taelia se acerca para acusar a lady Gobernalle de estar detrás del ataque. ¿No lo ves, Katherine? Reemplazarte era su plan desde el principio. Katherine se vuelve hacia Priscilla: ¿Es eso cierto? Priscilla deja de hacerse la amable y comprensiva. Ataca a Katherine con dureza: ¡Débil! ¡No eres digna de gobernar! ¡Gobernalle CONSTRUYÓ esta ciudad! Dispara a Katherine con su pistola. Los guardias entran en acción. Priscilla dispara a las barricas de un carro cercano a la multitud, que liberan una nube de humo que envuelve rápidamente la plaza. Cunde el caos].', 28153),
(149778, 'esES', 'Vorrik, estoy listo para enfrentarme al emperador Korthek.', 'Vorrik, estoy lista para enfrentarme al emperador Korthek.', 28153),
(149777, 'esES', '', 'Mi botín... Noooo...', 28153),
(149776, 'esES', '¡Destruid este miserable navío y liberad a nuestro pueblo!', '', 28153),
(149775, 'esES', '', '¡Qué bonita arma que tieneh, máh botín pa mí!', 28153),
(149774, 'esES', 'Grandes tormentas del mar, ¡acudid a mi llamada!', '', 28153),
(149772, 'esES', '[PH] Impresionante, \"viejo amigo\". ¡Pero no será suficiente para detenerme!', '', 28153),
(149771, 'esES', '[PH] La llave está en lo más profundo de mi fortaleza, Vorrik. ¿No pensarías que sería tan tonto como para llevarla encima?', '', 28153),
(149770, 'esES', '[PH] Sí que tienes razón en una cosa. ¡Se acabó la charla!', '', 28153),
(149769, 'esES', '[PH] Basta de charla, viejo amigo. Entrégame la llave de la prisión de Mythrax. ¡Nos condenarás a todos!', '', 28153),
(149768, 'esES', '¡Os enfrentáis a la fuerza de Kortherk, el Emperador eterno!', '', 28153),
(149767, 'esES', '[PH] Está hecho, puedo utilizar el poder de esta aguja. ¡A la puerta, rápido!', '', 28153),
(149766, 'esES', '', 'Por las arenas, ¡cuánto me alegro de verte! Esto me supera...', 28153),
(149765, 'esES', '', 'Es difícil tener localizado a Kiro. Nunca para, siempre está trabajando en algún gran plan.\n\nSe fue con Nisha. Lo último que supe de él es que iba al barranco para robar suministros, sabotear los cañones o algo.', 28153),
(149764, 'esES', '', 'Nisha ha estado armando alboroto en el campamento de esclavos. Dirígete hacia el oeste al salir de esta cueva y baja por la primera rampa a tu derecha.\n\nEn caso de duda, escucha los estertores de los sethrak moribundos y ve hacia ellos; ella estará cerca.', 28153),
(149763, 'esES', '', '¡Vaya, esa es la mejor parte! Seguro que no los has visto al entrar, ¿eh?\n\n¡Tenemos vulperas escondidos por toda la ruta de escape, atentos a los infieles!\n\nCuando nos confirman que es seguro viajar, guío a algunos vulperas hasta la salida y los llevo a las caravanas que los ponen a salvo.\n\nDespués vuelvo a entrar y me preparo para sacar a otro grupo. ¡Es muy emocionante y, hasta hoy, solo he gritado de miedo tres veces!\n\nSi tienes que marcharte, sal de la cueva y dirígete al oeste. Cruza el puente hacia las ruinas y estarás fuera de peligro.', 28153),
(149762, 'esES', '', 'Lo mismo que tú, supongo. Mira a estos vulperas... Están heridos y necesitan ayuda.\n\nLos infieles han esclavizado a muchos de nosotros para obligarnos a trabajar y luchar para ellos.\n\nHasta ahora, nunca habíamos podido detenerlos. Pero Nisha y Kiro nos han demostrado que podemos plantar cara.\n\nPor la noche, Kiro y los demás se cuelan en el campamento de esclavos y rescatan a los vulperas más vulnerables.\n\nLos traen de vuelta aquí. Luego yo me encargo de que crucen las dunas de forma segura y lleguen a las caravanas que esperan para ponerlos a salvo.\n\nEs peligroso y preferiría estar en el campamento, escuchando a Ahna cantar junto a una acogedora fogata, pero ¿cómo podría quedarme allí sabiendo que mis amigos necesitan mi ayuda?', 28153),
(149761, 'esES', 'Quiero preguntarte algo más.', 'Quiero preguntarte algo más.', 28153),
(149760, 'esES', '¿Dónde está Nisha?', '¿Dónde está Nisha?', 28153),
(149759, 'esES', '¿Dónde está Kiro?', '¿Dónde está Kiro?', 28153),
(149758, 'esES', '¿Cómo sacas a los esclavos?', '¿Cómo sacas a los esclavos?', 28153),
(149757, 'esES', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(149756, 'esES', '', '¡$p! ¡Sabía que vendrías! Se lo dije a los demás: \"$p se preocupa por los vulperas y no nos abandonará\".\n\n¡Yo también he venido a ayudar! Kiro y Nisha están rescatando esclavos vulperas y yo estoy organizando caravanas para sacarlos de aquí.\n\nLa verdad es que da un poco de miedo estar tan cerca de los sethrak. Pero sé que es lo correcto. Eso ha dicho Nisha.\n\nAh, por cierto, $gbienvenido:bienvenida; a nuestro pequeño escondite.', 28153),
(149755, 'esES', 'Guíanos.', 'Guíanos.', 28153),
(149754, 'esES', 'Si mientes, irás a la horca.', 'Si mientes, irás a la horca.', 28153),
(149753, 'esES', 'Estoy contigo.', 'Estoy contigo.', 28153),
(149752, 'esES', '', '¡Buen trabajo! El ejército se alegrará de recibir ehtoh suminihtroh.', 28153),
(149751, 'esES', '', 'Hemoh encontrado loh rehtoh de un barco fluvial saqueado por loh trolh de sangre. Pon a salvo su cargamento... ¡anteh de que se lo lleven elloh!', 28153),
(149750, 'esES', 'Espero que esto merezca la pena.', 'Espero que esto merezca la pena.', 28153),
(149749, 'esES', 'Mmm. De acuerdo, vámonos.', 'Mmm. De acuerdo, vámonos.', 28153),
(149748, 'esES', '¡¿Qué?! Más te vale estar en lo cierto...', '¡¿Qué?! Más te vale estar en lo cierto...', 28153),
(149747, 'esES', 'Bien, mi fiel $gescudero:escudera;, parece que nuestro trabajo aquí ha terminado. Si me disculpas, tengo un ettin al que dar muerte.', '', 28153),
(149746, 'esES', '¡Un bandido! ¡No temas, doncella, pues yo te protegeré!', '', 28153),
(149745, 'esES', '¿Demonio astral? ¡No permitiré que se insulte a Centella Segundo de esta manera! Prepárate para sufrir el poder de Johnny... ¿Eso es un ettin?', '', 28153),
(149744, 'esES', '¡Veo que te las has visto con este demonio astral! ¡Te felicito por derrotarlo sin ayuda! ¿Te ha herido?', '', 28153),
(149743, 'esES', '', 'La gente está perdiendo la fe en Katherine...', 28153),
(149742, 'esES', '', 'Estupendo... Puede que tengamos que armarla.', 28153),
(149741, 'esES', '', 'Paso uno: comenzar una revuelta.', 28153),
(149740, 'esES', '[PH] Detente. ¡Mythrax se alzará y los traidores pereceréis!', '', 28153),
(149739, 'esES', 'Las llaves serán nuestras... ¡y Mythrax se alzará!', '', 28153),
(149738, 'esES', 'Centella Segundo... ¿por qué no has volado?', '', 28153),
(149737, 'esES', '[PH] Voy a empezar... y justo a tiempo, ¡ahí vienen las tropas de Korthek!', '', 28153),
(149736, 'esES', 'Estoy listo para defenderte de los sethrak, comienza tu armonización.', 'Estoy lista para defenderte de los sethrak, comienza tu armonización.', 28153),
(149735, 'esES', '[PH] ¡Estás $gpreparado:preparada;? Debemos darnos prisa, las fuerzas de Korthek intentarán impedir que obtenga el poder de esta aguja, tendrás que defenderme durante mi hechizo.', '', 28153),
(149730, 'esES', '¿De dónde han salido todos estos fuegos fatuos?', '', 28153),
(149729, 'esES', '¡Ay! ¡Condenados fuegos fatuos! ¡Qué dolor!', '', 28153),
(149726, 'esES', 'Habéis acabado con una gran amenaza para Boralus, héroes, pero apostaría mi peso en grog a que la ciudad aún no está fuera de peligro.', '', 28153),
(149725, 'esES', 'Sin ese cobarde traidor y sus capitanes, este ejército de piratas no distinguirá sus hebillas de sus calzones.', '', 28153),
(149724, 'esES', 'Harlan debería haber sabido que acabaría así si me traicionaba.', '', 28153),
(149723, 'esES', 'Pero eso no os preocupa, ¿verdad?', '', 28153),
(149722, 'esES', 'Excepto su guardia aterradora de asesinos y matones despiadados.', '', 28153),
(149720, 'esES', '[PH] Me dirigiré a la aguja. Reúnete conmigo allí. Seguro que las fuerzas de Korthek intentarán evitar que utilicemos su poder.', '', 28153),
(149719, 'esES', 'Hermosa doncella, ¿qué te aflige? ¡Maximillian de Villanorte está aquí para ayudar!', '', 28153),
(149717, 'esES', '', 'Sin ti, no habríamoh encontrado a Rakera, pequeña.', 28153),
(149716, 'esES', 'Eso suena como una damisela en apuros. ¡Sígueme, $gescudero:escudera;!', '', 28153),
(149715, 'esES', 'Ya ves que el único resultado de mis intentos previos de abatir a este ettin es que ahora lleva mis lanzas firmemente clavadas en el costado. Por eso, mi primera tarea para ti...', '', 28153),
(149714, 'esES', '', 'Porque somos colegas, ¿no?', 28153),
(149713, 'esES', '', 'Las ruinas están de camino a Zem\'lan. No me importa acercaros. Dolly y Dot me hacen compañía, pero siempre es bueno tener colegas con los que hablar.', 28153),
(149712, 'esES', 'Entonces, esa burbuja... ¡Ah! ¿El agua salada no te va bien? Qué raro, hombrecillo.', '', 28153),
(149711, 'esES', '¡¡¡¡NOOOOOO!!!! ¡¡¡¡NO PUEDE SER!!!!', '', 28153),
(149710, 'esES', 'Espera... ¿Qué hacen aquí los vulperas?', '', 28153),
(149709, 'esES', 'Lleva años abandonado, pero será el lugar perfecto para lanzar nuestro...', '', 28153),
(149708, 'esES', 'Mi santuario personal estaba oculto en las colinas. Un pequeño tributo a Sethraliss donde podía meditar.', '', 28153),
(149707, 'esES', 'En aquel entonces, Korthek y yo guiábamos a todos los sethrak en el culto a Sethraliss.', '', 28153),
(149706, 'esES', '¡El sueño ahogado me consume!', '¡El sueño ahogado me consume!', 28153),
(149705, 'esES', 'Viví aquí hace mucho tiempo. Antes de que Korthek traicionara a nuestra gente a cambio de poder y locura.', '', 28153),
(149704, 'esES', 'Es un cruel nido de rocas y polvo, repleto de sethrak que han dado la espalda a nuestros loa.', '', 28153),
(149703, 'esES', 'Bebo del Vacío infinito.', 'Bebo del Vacío infinito.', 28153),
(149702, 'esES', 'Mi ceguera se desvanece.', 'Mi ceguera se desvanece.', 28153),
(149701, 'esES', 'Nos dirigimos al corazón del imperio de los infieles.', '', 28153),
(149700, 'esES', 'El círculo... ¡Veo el círculo!', 'El círculo... ¡Veo el círculo!', 28153),
(149699, 'esES', '¡La sombra retorcida viene a por mí!', '¡La sombra retorcida viene a por mí!', 28153),
(149698, 'esES', '¡Escucho la voz! ¡Las mil verdades!', '¡Escucho la voz! ¡Las mil verdades!', 28153),
(149697, 'esES', 'Viviré eternamente en el abismo.', 'Viviré eternamente en el abismo.', 28153),
(149696, 'esES', '¡Por fin! El camino hasta Harlan Sweete está despejado y nada puede detenernos.', '', 28153),
(149695, 'esES', '¡Mi alma es del ancestro!', '¡Mi alma es del ancestro!', 28153),
(149694, 'esES', '', 'Defenderemoh a tu gente como si fuera la nuehtra.', 28153),
(149693, 'esES', '¿Qué tal si sacamos partido a vuestras habilidades pugilísticas?', '', 28153),
(149692, 'esES', 'Ese maldito percebe tiene la isla bloqueada hasta que acaben las celebraciones en el foso de lucha.', '', 28153),
(149691, 'esES', '¡No llevo floreh de la paz en la solapa, ehcoria de la Alianza!', '¡No llevo floreh de la paz en la solapa, ehcoria de la Alianza!', 28153),
(149690, 'esES', '¡No sé nada de ningún Tranvía Subterráneo!', '¡No sé nada de ningún Tranvía Subterráneo!', 28153),
(149689, 'esES', 'Ahora solo queda atravesarle el gaznate a Harlan, pero no será fácil.', '', 28153),
(149688, 'esES', '¡Loh lechúcicoh lunareh no vuelan! ¡Vete!', '¡Loh lechúcicoh lunareh no vuelan! ¡Vete!', 28153),
(149687, 'esES', '¡No soy ehpía!', '¡No soy ehpía!', 28153),
(149686, 'esES', '¿Que el qué múrloc ehtá dónde? ¡No ehtáh bien de la cabeza!', '¿Que el qué múrloc ehtá dónde? ¡No ehtáh bien de la cabeza!', 28153),
(149685, 'esES', '\"¿Una botella de sudor de trol?\". ¡Aquí no vendemoh de eso!', '\"¿Una botella de sudor de trol?\". ¡Aquí no vendemoh de eso!', 28153),
(149684, 'esES', 'Claro que loh árboleh son bonitoh y loh incendioh son maloh. ¿Qué quiereh decir?', 'Claro que loh árboleh son bonitoh y loh incendioh son maloh. ¿Qué quiereh decir?', 28153),
(149683, 'esES', '¡Zandalar eterno!', '¡Zandalar eterno!', 28153),
(149682, 'esES', '', 'En ehte templo hay algo raro. Tenemoh que encontrar una forma de entrar.', 28153),
(149681, 'esES', 'Si no os fuera lo de ser héroes, se os daría bien la vida pirata.', '', 28153),
(149680, 'esES', 'Duermo... solo para despertar...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'esES', 'Eso es... genial, Maximillian. Yo me voy ya.', 'Eso es... genial, Maximillian. Yo me voy ya.', 28153),
(149678, 'esES', 'La sombra eterna... me abraza...', '', 28153),
(149677, 'esES', 'Tu esperanza... se desvanece...', '', 28153),
(149676, 'esES', 'Eh... ¿Qué?', 'Eh... ¿Qué?', 28153),
(149675, 'esES', 'La semilla... echa raíces...', '', 28153),
(149674, 'esES', 'Solo soy uno... de tantos...', '', 28153),
(149673, 'esES', 'El ciclo... continúa...', '', 28153),
(149672, 'esES', 'Hasta la muerte... puede... morir...', '', 28153),
(149671, 'esES', 'Al final... conocerás la verdad...', '', 28153),
(149670, 'esES', '¿Te has enterado? ¡La Puerta de Daelin ha caído!', '¿Te has enterado? ¡La Puerta de Daelin ha caído!', 28153),
(149669, 'esES', '¿Qué piensas de todo esto?', '¿Qué piensas de todo esto?', 28153),
(149668, 'esES', 'Las corrientes te arrastrarán al abismo.', '', 28153),
(149667, 'esES', 'Y a mí me dan ganah de arrancarme lah orejah.', '', 28153),
(149666, 'esES', 'A los Camorristas Dientenegro les encanta curtirse los nudillos en una pelea. Si conseguís arrancarles un par de dientes, el capitán Raoul os invitará a la reunión.', '', 28153),
(149665, 'esES', '¿Qué eh ese chillido que sale de tu boca?', '', 28153),
(149664, 'esES', '¡Hasta los peces beben menos que las Ratas de Pantoque! Si conseguís seguirle el ritmo a esta recua, la capitana Eudora no dudará en invitaros a la reunión.', '', 28153),
(149663, 'esES', '¿Qué has oído sobre el ataque?', '¿Qué has oído sobre el ataque?', 28153),
(149662, 'esES', 'Que no se diga que no he contribuido en la guerra. Aquí está mi informe.', 'Que no se diga que no he contribuido en la guerra. Aquí está mi informe.', 28153),
(149661, 'esES', '', 'Muy bien... Dot y Dolly son mis mejores colegas. Tiran de mi carro por dunas y arenas.', 28153),
(149660, 'esES', 'No sé... Las cosas cada día están peor. Quizás sea hora de que Katherine deje su puesto.', 'No sé... Las cosas cada día están peor. Quizás sea hora de que Katherine deje su puesto.', 28153),
(149659, 'esES', 'No fallaré a la Alianza. Aunque haya tenido que sentarme en el barro tres días para conseguirlo. Toma mi informe, por favor.', 'No fallaré a la Alianza. Aunque haya tenido que sentarme en el barro tres días para conseguirlo. Toma mi informe, por favor.', 28153),
(149658, 'esES', '', 'A Dot y a Dolly les gusta que les cante. Los tranquiliza.', 28153),
(149657, 'esES', '¿Te puedes creer que hay gente que piensa que los trols y los elfos de la noche son parientes? Ha sido una experiencia horrible. Ten, mi informe.', '¿Te puedes creer que hay gente que piensa que los trols y los elfos de la noche son parientes? Ha sido una experiencia horrible. Ten, mi informe.', 28153),
(149656, 'esES', 'Conseguir una invitación facilitaría el trabajo. A menos que prefiráis lanzaros de cabeza e intentar matar a la vez a tres de los capitanes piratas más temidos. Vosotros veréis.', '', 28153),
(149655, 'esES', '', 'Dot y Dolly son mis mejores colegas. Tiran de mi carro por dunas y arenas, y yo los quiero y les doy chuletas.', 28153),
(149654, 'esES', 'Dije que haría lo que fuera necesario por vengar a Teldrassil. Claramente, era necesario que me hiciera pasar por trol. Toma mi informe.', 'Dije que haría lo que fuera necesario por vengar a Teldrassil. Claramente, era necesario que me hiciera pasar por trol. Toma mi informe.', 28153),
(149653, 'esES', 'Sé de buena tinta que los capitanes van a reunirse. Si nos colamos en el grupo, podréis cortar todas las cabezas de la hidra a la vez.', '', 28153),
(149652, 'esES', '¿Dónde está mi pterrordáctilo?', '¿Dónde está mi pterrordáctilo?', 28153),
(149651, 'esES', '¿Qué le pasa a mi cría?', '¿Qué le pasa a mi cría?', 28153),
(149650, 'esES', '\"Un viajecito de nada a la jungla\", decían. \"Será fácil\", decían. Anda, toma mi informe.', '\"Un viajecito de nada a la jungla\", decían. \"Será divertido\", decían. Anda, toma mi informe.', 28153),
(149649, 'esES', '¿Por qué hace ese ruido?', '¿Por qué hace ese ruido?', 28153),
(149648, 'esES', 'Salvajes. Menuda panda de salvajes. Toma mi informe, por favor.', 'Salvajes. Menuda panda de salvajes. Toma mi informe, por favor.', 28153),
(149647, 'esES', 'Ni preguntes dónde tuve que dormir anoche. Aquí está tu informe.', 'Ni preguntes dónde tuve que dormir anoche. Aquí está tu informe.', 28153),
(149646, 'esES', 'Gracias.', 'Gracias.', 28153),
(149645, 'esES', 'Yo soy más de ver las cosas de lejos, así que os dejaré los detalles a vosotros.', '', 28153),
(149644, 'esES', 'Y luego le daremos a Harlan su merecido.', '', 28153),
(149643, 'esES', 'Te ahogarás en la sangre de lo infinito.', '', 28153),
(149642, 'esES', 'Así que este es el plan: dejad secos a los Aguacortada, tumbad a las Ratas de Pantoque, aplastad a los Camorristas Dientenegro y desmantelad a los Marea de Hierro.', '', 28153),
(149641, 'esES', 'Si lo consigue, estará al mando de una flota que amenazará a toda la región.', '', 28153),
(149640, 'esES', 'Me parece que he oído graznidoh, pero no puedo dejar loh nidoh pa ir a mirar.$b$bDate prisa o te quedaráh sin un pterrordáctilo que cuidar. No todoh llegan a adultoh.', '', 28153),
(149639, 'esES', 'Harlan Sweete quiere usar a los Marea de Hierro para reclutar a las otras tripulaciones piratas.', '', 28153),
(149638, 'esES', 'Ah, se ha ido. Seguramente se aburría.$b$bDeberíah ir a buhcarlo anteh de que se haga daño. No ehtá preparado pa cuidarse solo.', '', 28153),
(149637, 'esES', '¿A que parece un poco desanimado?$b$bSeguro que echa de menoh a su madre. Y tú ereh su madre, ¿no?', '', 28153),
(149636, 'esES', 'Tu alma solo conocerá la penuria.', '', 28153),
(149635, 'esES', 'La estrellas temen nuestro ascenso.', '', 28153),
(149634, 'esES', 'Ese ruido que hace eh una clara señal de que tiene hambre.$b$bSerá mejor que lo alimenteh anteh de que te coma un dedo.$b$bSi no llevah comida encima, puedeh conseguir un poco en el Redil Behtia de Guerra.', '', 28153),
(149633, 'esES', 'Siente el abrazo de la verdadera nada.', '', 28153),
(149632, 'esES', 'Tu sueño será eterno en Ny\'alotha.', '', 28153),
(149631, 'esES', 'La luz muere en los abismos sin fin.', '', 28153),
(149630, 'esES', 'Soy el alero Goja. Pa\'ku eh mi loa y sirvo a la señora de loh vientoh cuidando de su prole.$b$bElla me ha dicho que puede que te haga falta un poco de ayuda.$b$b<El alero Goja se ríe>.$b$b¿Qué necesitah?', '', 28153),
(149629, 'esES', 'Observa la sombra de tu perdición.', '', 28153),
(149628, 'esES', 'He oído que fueron piratas. ¿Te lo puedes creer? ¡PIRATAS, de esos consumidos por el escorbuto y las pulgas! ¿Es que los Valiente ya ni siquiera pueden protegernos?', 'He oído que fueron piratas. ¿Te lo puedes creer? ¡PIRATAS, de esos consumidos por el escorbuto y las pulgas! ¿Es que los Valiente ya ni siquiera pueden protegernos?', 28153),
(149627, 'esES', '¡Ah! ¡Mi fiel $gescudero:escudera;! Siempre apareces cuando más te necesito.\n\nHe venido a Kul Tiras con la esperanza de encontrar ciudadanos que necesiten un salvador. Ahora mismo el agravio que me ocupa es salvar a los pobres pescadores de esta aldea de los ettins que han decidido acosarlos.\n\nTienen una piel más gruesa de lo normal.', '', 28153),
(149626, 'esES', 'Sí, tú y todo el mundo. Ponte a la cola e intenta no montar un espectáculo. La gente ya está bastante alterada.', 'Sí, tú y todo el mundo. Ponte a la cola e intenta no montar un espectáculo. La gente ya está bastante alterada.', 28153),
(149625, 'esES', 'Tengo que hablar con Katherine Valiente de inmediato.', 'Tengo que hablar con Katherine Valiente de inmediato.', 28153),
(149624, 'esES', 'La lady almirante Valiente se está preparando para hablarle a la gente. Por favor, ten paciencia.', 'La lady almirante Valiente se está preparando para hablarle a la gente. Por favor, ten paciencia.', 28153),
(149623, 'esES', 'La Lady Almirante está en peligro. ¡Ven con nosotros!', 'La Lady Almirante está en peligro. ¡Ven con nosotros!', 28153),
(149622, 'esES', 'Que todo el mundo mantenga la calma. Todo está bajo control.', 'Que todo el mundo mantenga la calma. Todo está bajo control.', 28153),
(149621, 'esES', 'A Nedly Sonrisas no le gusta que se aprovechen de él. ¡Nadie encontrará ese tesoro antes que yo!', '', 28153),
(149620, 'esES', 'No me vas a coger dormido.\n\nIntenta engañarme y te venderé a los leales.', '', 28153),
(149619, 'esES', 'Hace poco que corrompieron a este olasangre. Debería poder purificarlo.', '', 28153),
(149618, 'esES', '¡Ah! Es más volátil de lo que pensaba.', '', 28153),
(149617, 'esES', '¡Saludos, $gviajero:viajera;!\n\n¿Has seguido mis heroicas hazañas con la esperanza de convertirte en $gescudero:escudera; de Maximillian de Villanorte?\n\n¡Estás de suerte, ya no tendrás que esperar más! Necesito a alguien que me ayude con mis tareas mientras me enfrento a peligrosos enemigos.', '', 28153),
(149616, 'esES', '', 'La encontraré o moriré en el intento.', 28153),
(149615, 'esES', '', 'El puerto de Zem\'lan está al sur. Hace años que no atracan barcos en sus muelles, pero es nuestra mejor opción para conseguir lo que Kiro y Nisha necesitan para atacar a los sethrak.', 28153),
(149614, 'esES', '', 'Manteneos alerta por si veis a vuestra amiga. Yo no le quito ojo a la carretera.', 28153),
(149613, 'esES', '', 'Es de después de la batalla, pero... Tul no aparece muerto. Sale herido y derrotado, pero no muerto.', 28153),
(149612, 'esES', '', 'Las historias cuentan que lord Arom mató a Gorak Tul y que su ejército cayó acto seguido. Pero aquí se ve cómo sus ensamblajes se desploman cuando lo ensartan y pierde su poder. Deben estar conectados de alguna forma.', 28153),
(149611, 'esES', '', 'Ese es Arom Crestavía cuando no era más que un coronel que lideraba el asalto final. Y ahí está Crestavía... acabando con Gorak Tul.', 28153),
(149610, 'esES', '', 'Esto no es Drust. Es un grabado de Kul Tiras en un monolito Drust.', 28153),
(149609, 'esES', '', 'Mmm. No había caído en que los ensamblajes fueron solo un intento desesperado.', 28153),
(149608, 'esES', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz.', '', 28153),
(149607, 'esES', 'Fhssh zzof og far\'al awtgsshu.', '', 28153),
(149606, 'esES', '', '¡Bien hecho! Ehto debería darle un rehpiro a la prole de Krag\'wa. Graciah.', 28153),
(149605, 'esES', 'Kua\'fon chilla de alegría y engulle la comida.', '', 28153),
(149604, 'esES', 'Kua\'fon olfatea la comida antes de devorarla con entusiasmo.', '', 28153),
(149603, 'esES', 'Kua\'fon muerde la comida en el aire.', '', 28153),
(149602, 'esES', 'Kua\'fon se abalanza sobre la comida y se la traga entera.', '', 28153),
(149601, 'esES', '', 'Loh trolh de sangre han reanudado su cacería contra la prole de Krag\'wa. ¡Ayuda al colérico señor de lah ranah a vengarse!', 28153),
(149600, 'esES', '¡Por Canto Tormenta!', '¡Por Canto Tormenta!', 28153),
(149599, 'esES', '¡Este valle nos pertenece, rata!', '¡Este valle nos pertenece, rata!', 28153),
(149598, 'esES', '¡Kul Tiras se hunde sin nosotros!', '¡Kul Tiras se hunde sin nosotros!', 28153),
(149597, 'esES', '¡Nuestra flota no tiene rival!', '¡Nuestra flota no tiene rival!', 28153),
(149596, 'esES', '¡Todos los que se opongan morirán!', '¡Todos los que se opongan morirán!', 28153),
(149595, 'esES', '¡Somos implacables, como las mareas!', '¡Somos implacables, como las mareas!', 28153),
(149594, 'esES', '¿Osas enfrentarte a la casa Canto Tormenta?', '¿Osas enfrentarte a la casa Canto Tormenta?', 28153),
(149593, 'esES', '¡Kul Tiras pertenece al mar!', '¡Kul Tiras pertenece al mar!', 28153),
(149592, 'esES', 'Entrego mi vida... al mar.', 'Entrego mi vida... al mar.', 28153),
(149591, 'esES', 'Sabiomar... conservadme...', 'Sabiomar... conservadme...', 28153),
(149590, 'esES', 'Solo... cumplía órdenes...', 'Solo... cumplía órdenes...', 28153),
(149589, 'esES', 'Ya... hemos ganado...', 'Ya... hemos ganado...', 28153),
(149588, 'esES', 'Mi muerte no cambia... nada...', 'Mi muerte no cambia... nada...', 28153),
(149587, 'esES', 'Nunca... descansaremos...', 'Nunca... descansaremos...', 28153),
(149586, 'esES', 'Mi sangre... alimenta las mareas...', 'Mi sangre... alimenta las mareas...', 28153),
(149585, 'esES', 'Vi la verdad... en las profundidades.', 'Vi la verdad... en las profundidades.', 28153),
(149584, 'esES', 'No tienes ni idea de lo degradante que es esto. Aquí tienes tu informe.', 'No tienes ni idea de lo degradante que es esto. Aquí tienes tu informe.', 28153),
(149583, 'esES', '', 'Necios. Al menos ya sabemos lo peligrosos que pueden ser los fuegos fatuos.', 28153),
(149582, 'esES', '', 'La próxima vez que nos veamos, no escaparás, Malfurion.', 28153),
(149581, 'esES', '¡No llegarás más lejos, Reina alma en pena!', '', 28153),
(149580, 'esES', '<Kua\'fon descansa con la cabeza bajo el ala, mientras grazna con tristeza>.', '', 28153),
(149579, 'esES', '', '¡Es hora de apuñalar!', 28153),
(149577, 'esES', '[PH] Dales duro, $p.', '', 28153),
(149575, 'esES', '', '¿Qué esperabas? Acaba de salir del cascarón. Tiene que comer. Ve al redil a pedir algo de carne.', 28153),
(149574, 'esES', 'Quien siembra vientos...', '', 28153),
(149573, 'esES', '', 'Puedo oírlo. Menudos pulmones tiene la cría.\n\n¿Por qué tienes esa cara de miedo?', 28153),
(149571, 'esES', '<Te mira sin comprender>.', '<Te mira sin comprender>.', 28153),
(149570, 'esES', 'Yo no digo nada.', 'Yo no digo nada.', 28153),
(149569, 'esES', '¿Te sobra una moneda de oro?', '¿Te sobra una moneda de oro?', 28153),
(149568, 'esES', 'Ereh un trol un poco raro.', 'Ereh un trol un poco raro.', 28153),
(149567, 'esES', '¿Qué?', '¿Qué?', 28153),
(149566, 'esES', 'Me ehtáh tapando la vihta.', 'Me ehtáh tapando la vihta.', 28153),
(149565, 'esES', '<Eructa>.', '<Eructa>.', 28153),
(149564, 'esES', '<Decir el santo y seña>.', '<Decir el santo y seña>.', 28153),
(149563, 'esES', '¿Qué quiereh?', '¿Qué quiereh?', 28153),
(149562, 'esES', 'La sopa de tortuga no está ni la mitad de buena que la sopa de $r.\n\nTú ve a por la carne de gusano de lodo y deja estar a las tortuguitas.\n\n¡Vuelve a visitarme en otro momento y podremos explorar otras sopas!', '', 28153),
(149561, 'esES', '¿Sopa de tortuga?', '¿Sopa de tortuga?', 28153),
(149560, 'esES', '¡Por Sethraliss!', '', 28153),
(149559, 'esES', 'Los infieles bloquean el paso al emperador Korthek. ¡Debemos destruir ese obstáculo!', '', 28153),
(149558, 'esES', '¡Atención! Margie necesita ayuda en el taller... Algo de unas piezas para... bueno, algo. Yo de eso no entiendo, ¿vale?', '', 28153),
(149557, 'esES', 'Excelente. Esta información será vital para nuestra guerra. Y no, no sé a quién se le ocurrió el santo y seña esta vez.', '', 28153),
(149556, 'esES', 'Nuestros espías se han infiltrado en la capital Zandalari, pero necesitamos que recuperes sus informes. Habla con los vagantes. Nuestro espía responderá al santo y seña.', '', 28153),
(149555, 'esES', 'Hay... eh... unos ogros cerca de la base que no parecen muy contentos. Señoras y señores, ¡armas a punto!', '', 28153),
(149554, 'esES', 'Aquí solo hallaréih a Akunda. Solo loh que comparten su nombre pueden entrar en su morada.', '', 28153),
(149553, 'esES', '¿Buhcáih redención? Akunda acoge a todo el mundo.', '', 28153),
(149552, 'esES', '', 'Buhcamoh a una exiliada llamada Rakera. Creemoh que podría ehtar en ehte templo.', 28153),
(149551, 'esES', '', 'Iré yo primero por si hay oro.', 28153),
(149550, 'esES', '', 'Cuando llegamos, queríamos la paz, pero los Drust se lanzaron a la batalla. Solo unos pocos nos toleraron.', 28153),
(149549, 'esES', '', 'Aquí se ve uno de los primeros asentamientos de Kul Tiras. Uno de los asentamientos perdidos.', 28153),
(149548, 'esES', 'Yo hablaré con Maokka.', 'Yo hablaré con Maokka.', 28153),
(149547, 'esES', 'Bien, estamos todos.', '', 28153),
(149545, 'esES', 'Hola.', '', 28153),
(149544, 'esES', '', 'Volvemos a encontrarnos.', 28153),
(149543, 'esES', '', 'Este mundo no puede soportar la destrucción que traerá Mythrax.', 28153),
(149542, 'esES', '¡Deja que se vaya, Taelia!', '', 28153),
(149541, 'esES', '', '¡Sam, no!', 28153),
(149540, 'esES', '¡Por Addington! ¡Por Canto Tormenta!', '', 28153),
(149539, 'esES', 'Esos desgraciados pagarán por lo que han hecho.', '', 28153),
(149538, 'esES', '', 'Jakra\'zet merecía ese final.', 28153),
(149537, 'esES', '¡Luchamos por el Despertar de la Tormenta!', '', 28153),
(149535, 'esES', '', 'Me he tomado la libertad de organizar un equipo. Recuperad mi premio.', 28153),
(149533, 'esES', 'Más desertores de mi orden... Bien, puede que no todo esté perdido.', '', 28153),
(149532, 'esES', 'Si caminan entre nosotros, la flota está en grave peligro.', '', 28153),
(149531, 'esES', 'Muchos creen que son una leyenda para advertir del peligro que conlleva abusar de la magia.', '', 28153),
(149530, 'esES', 'Esas... cosas... son K\'thir. Vienen de los rincones más oscuros del océano.', '', 28153),
(149529, 'esES', '', '', 28153),
(149528, 'esES', '¿Qué necesitas, Jefa de Guerra?', '¿Qué necesitas, Jefa de Guerra?', 28153),
(149527, 'esES', '', '¡Baine, haz que retrocedan!', 28153),
(149526, 'esES', '', 'Usa el designador remoto para mover a Gual-I. ¡Mándalo a las perturbaciones que veas en la tierra y él atraerá a los gusanos!', 28153),
(149525, 'esES', 'Tratamos de protegernos de ellos, de ignorarlos, pero me temo que puede que hayamos fracasado.', '', 28153),
(149523, 'esES', 'Con el tiempo los susurros... cambiaron. A veces eran exigentes, incluso violentos.', '', 28153),
(149522, 'esES', 'Mi orden escucha al mar para que guíe a nuestros barcos y a nuestro pueblo con susurros imperceptibles para la mayoría.', '', 28153),
(149521, 'esES', 'Hay un puente cerca que tiene buenas vistas del Altar de la Tormenta. El augurio viene de allí.', '', 28153),
(149520, 'esES', 'Dihfrutaré quebrantándote.', '', 28153),
(149519, 'esES', '', 'Ten cuidado con eso, a no ser que quieras pelear con algunos de los inútiles que hay por ahí. ¡Si es eso, dale caña!', 28153),
(149518, 'esES', 'Idiota. Muere.', '', 28153),
(149517, 'esES', '¡Ehtoh prisioneroh pertenecen a loh Zandalari!', '', 28153),
(149516, 'esES', '¡Ja, ja, ja!', '', 28153),
(149515, 'esES', '¡Vah a morir!', '', 28153),
(149514, 'esES', 'La Alianza da pena.', '', 28153),
(149513, 'esES', '¡Te machacaré!', '', 28153),
(149512, 'esES', '¿Quiereh ir al interrogador?', '', 28153),
(149511, 'esES', '¡Carne frehca!', '', 28153),
(149510, 'esES', '¿Esa cosa es... segura? ¡Estoy dispuesto a arriesgarme!', '¿Esa cosa es... segura? ¡Estoy dispuesta a arriesgarme!', 28153),
(149509, 'esES', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(149508, 'esES', 'Madre de las mareas... ¿En qué nos hemos convertido?', '', 28153),
(149507, 'esES', '¡Puntual como un clavo!', '¡Puntual como un clavo!', 28153),
(149506, 'esES', '¿Eso es... una máquina topo?', '¿Eso es... una máquina topo?', 28153),
(149505, 'esES', 'Me asusta ir bajo tierra... ¡pero me asustan más esos trols!', 'Me asusta ir bajo tierra... ¡pero me asustan más esos trols!', 28153),
(149504, 'esES', '¡Gracias, gracias!', '¡Gracias, gracias!', 28153),
(149503, 'esES', '¡Has llegado justo a tiempo!', '¡Has llegado justo a tiempo!', 28153),
(149502, 'esES', '¡Creía que iban a comerme!', '¡Creía que iban a comerme!', 28153),
(149501, 'esES', 'Comandante, la Jefa de Guerra pide que prepares tu avanzada para la llegada de un ejército.', 'Comandante, la Jefa de Guerra pide que prepares tu avanzada para la llegada de un ejército.', 28153),
(149500, 'esES', 'Necesitamos hacer sitio para la llegada de la flota de la Jefa de Guerra. ¿Podéis despejar los muelles?', 'Necesitamos hacer sitio para la llegada de la flota de la Jefa de Guerra. ¿Podéis despejar los muelles?', 28153),
(149499, 'esES', 'La Jefa de Guerra necesita raciones y alojamiento para el ejército que viene hacia aquí.', 'La Jefa de Guerra necesita raciones y alojamiento para el ejército que viene hacia aquí.', 28153),
(149498, 'esES', '¿Doscientos soldados con la Jefa de Guerra, dices? Prepararé la avanzada para su llegada.', '', 28153),
(149497, 'esES', 'Lo que sea por la Jefa de Guerra. Reuniré a los guardias para despejar los muelles inmediatamente. Lok\'tar, camarada.', '', 28153),
(149496, 'esES', '', '¿La Jefa de Guerra necesita alojamiento y comida para su ejército? Nuestras reservas deberían poder soportarlo, tuvimos una primavera muy fructífera y un invierno muy suave la temporada pasada.', 28153),
(149495, 'esES', 'Está matando a sus propias tropas...', '', 28153),
(149494, 'esES', 'Déjame ayudar. Sé lo que le pasa.', '', 28153),
(149493, 'esES', 'Devuélveme a Ventormenta. (Volver/Reiniciar gesta).', 'Devuélveme a Ventormenta. (Volver/Reiniciar gesta).', 28153),
(149492, 'esES', 'Envíame a Zuldazar. (Saltar gesta de introducción).', 'Envíame a Zuldazar. (Saltar gesta de introducción).', 28153),
(149491, 'esES', '', 'Demasiadas naves de nuestra armada cayeron a manos de la Legión o de la Alianza. Tengo a nuestros maestros de embarcadero trabajando noche y día, pero necesitamos más.', 28153),
(149490, 'esES', 'Para.', '', 28153),
(149489, 'esES', 'Hablo... en nombre de G\'huun. Él... dirigirá. Tú... obedecerás... o morirás.', '', 28153),
(149488, 'esES', 'Ven.', '', 28153),
(149487, 'esES', 'Los restos de este loa... me alimentan. Alimentan... a G\'huun.', '', 28153),
(149486, 'esES', 'Intentarás... detener... a G\'huun. Fracasarás... y... sufrirás.', '', 28153),
(149485, 'esES', 'Sí... Pelea... Resiste... G\'huun tiene hambre... de tu... sufrimiento.', '', 28153),
(149484, 'esES', 'Vuestros esfuerzos... son inútiles. Soy... intocable.', '', 28153),
(149483, 'esES', 'Vuestros esfuerzos... son en vano... Soy... intoca... ¿Qué? No. ¡NO!', '', 28153),
(149482, 'esES', 'Esto... no prueba... NADA. Encontrará... a otro... receptor. Los sellos... se romperán... ¡G\'huun... será... libre!', '', 28153),
(149481, 'esES', 'Espera... ¿Esto es del sótano?', '', 28153),
(149480, 'esES', '', '[PH] Buena suerte.', 28153),
(149479, 'esES', '', '[PH] Su patrulla acaba de pasar. Ahora deberías poder cruzar.', 28153),
(149478, 'esES', '', '', 28153),
(149477, 'esES', '', '[PH] Los infieles se van a llevar una gran sorpresa.', 28153),
(149476, 'esES', '', '', 28153),
(149475, 'esES', 'El niño se aleja riéndose mientras lo persigues.', 'La niña se aleja riéndose mientras la persigues.', 28153),
(149474, 'esES', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t¡%s selecciona a |cFFFF0000$n|r como objetivo de |cFFFF0000|Hspell:257617|h[Agitación]|h|r! ¡Dispersaos!', '', 28153),
(149473, 'esES', 'Ehtoy pensando que podríamoh quitar de en medio a loh pterrordáctiloh pa usar la atalaya de la colina, pero acaban con nosotroh uno a uno como si nada.', 'Ehtoy pensando que podríamoh quitar de en medio a loh pterrordáctiloh pa usar la atalaya de la colina, pero acaban con nosotroh uno a uno como si nada.', 28153),
(149472, 'esES', 'No me ofendo, señora.', '', 28153),
(149471, 'esES', '', 'No me gustan los discursos, así que seré breve. Gracias. Siempre tendrás aliados en el Valle Canto Tormenta.', 28153),
(149470, 'esES', '', 'Sin ánimo de ofender, Calvin.', 28153),
(149469, 'esES', '', 'Espantar a los jabaespines, atravesar las granjas y llevarlos hasta el horado. Rescatar a los ciudadanos y a los granjeros... Has hecho más de lo que podría... o querría... hacer la milicia.', 28153),
(149468, 'esES', '', 'Te ahorraré los cumplidos. De todas formas, nunca se me han dado bien.', 28153),
(149466, 'esES', 'Los Zandalari llevan en barco a sus prisioneros de guerra. ¡No podemos permitirlo! Usa la máquina topo Hierro Negro para evitar que los interroguen y los maten.', '', 28153),
(149465, 'esES', '', 'Hay que entregarle los planes de ataque a Kiro. No hay tiempo que perder, ¡vámonos!', 28153),
(149464, 'esES', '', 'Tiene razón. Nombraron lord a Arom Crestavía por su victoria aquí.', 28153),
(149463, 'esES', '', 'Si seguimos las órdenes, ninguno de esos monstruos llegará a Puesto de Arom. Echemos una mano.', 28153),
(149462, 'esES', '', 'Se piensa que somos parte de su milicia...', 28153),
(149461, 'esES', '', '¡El sacrificio de sangre debe acabar! Eh el primer paso pa detener al Dioh de la Sangre.', 28153),
(149460, 'esES', '', '¡Loh ritualeh ohcuroh de Zul\'Nazman han ehparcido su corrupción por la tierra y han hecho que vuelvan ehpírituh del otro lado! ¡Purifica suh rehtoh y haz que loh demáh dehcansen en paz!', 28153),
(149459, 'esES', 'Dioh... de la Sangre... ¡Agh!', 'Dioh... de la Sangre... ¡Agh!', 28153),
(149458, 'esES', 'Reúnete conmigo en Atul\'Aman. ¡Los demás nos esperan dentro!', '', 28153),
(149457, 'esES', 'Noh ehtá llamando...', 'Noh ehtá llamando...', 28153),
(149456, 'esES', 'Parece que tenemos algunos jinetes del viento en apuros. ¡Hay que buscar a los supervivientes en el campo de batalla!', '', 28153),
(149455, 'esES', '¡Déjame!', '¡Déjame!', 28153),
(149454, 'esES', '¡No, no, no, no!', '¡No, no, no, no!', 28153),
(149453, 'esES', '¡Sal de mi cabeza!', '¡Sal de mi cabeza!', 28153),
(149452, 'esES', '¡Aagh!', '¡Aagh!', 28153),
(149451, 'esES', '¡Bahta!', '¡Bahta!', 28153),
(149450, 'esES', 'Ojalá los infieles se hubieran conformado con la paz. Para nosotros siempre ha sido suficiente.\n\nPero su implacable agresión no nos ha dejado opción.\n\nAcabaremos con el emperador Korthek... y nos quedaremos cualquier cosa útil que encontremos por el camino.', '', 28153),
(149449, 'esES', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t¡Saca rápidamente las barricas de munición del fuego para evitar que %s las haga explotar!', 28153),
(149448, 'esES', '¡Vanguardia! ¡Preparaos para apoyar al coronel Crestavía!', '¡Vanguardia! ¡Preparaos para apoyar al coronel Arom!', 28153),
(149447, 'esES', '¡Por Drustvar y Kul Tiras!', '¡Por Drustvar y Kul Tiras!', 28153),
(149446, 'esES', '¡Se han llevado a nuestros hijos e hijas! ¡Haz que paguen por ello!', '¡Se han llevado a nuestros hijos e hijas! ¡Haz que paguen por ello!', 28153),
(149445, 'esES', '¡Es hora de hacer que vuestros antepasados se sientan orgullosos!', '¡Es hora de hacer que vuestros antepasados se sientan orgullosos!', 28153),
(149444, 'esES', '¡Los hemos rechazado! ¡Seguid!', '¡Los hemos rechazado! ¡Seguid!', 28153),
(149443, 'esES', '¡Resistid!', '¡Resistid!', 28153),
(149442, 'esES', '¡Hemos rechazado al enemigo!\n\n¡No te quedes ahí, entra y lucha!', '¡Hemos rechazado al enemigo!\n\n¡No te quedes ahí, entra y lucha!', 28153),
(149441, 'esES', '¡La nube agorera comienza a hervir al tocar a %s!', '¡La nube agorera comienza a hervir al tocar a %s!', 28153),
(149440, 'esES', 'Gracias...', 'Gracias...', 28153),
(149439, 'esES', 'Por fin... puedo descansar...', 'Por fin... puedo descansar...', 28153),
(149438, 'esES', 'Mi guardia ha terminado...', 'Mi guardia ha terminado...', 28153),
(149437, 'esES', 'Vuelvo... a descansar...', 'Vuelvo... a descansar...', 28153),
(149436, 'esES', 'Mi labor ha terminado...', 'Mi labor ha terminado...', 28153),
(149435, 'esES', 'Iré a por la carne.', 'Iré a por la carne.', 28153),
(149434, 'esES', '¡La caja es mía, $r metomentodo!\n\nNecesito gusanos de lodo para hacer sopa, ¡pero se esconden! Tengo paciencia, puedo esperar aquí unos días y tal vez encuentre más cajas.\n\nTráeme carne de gusano de lodo y te la cambiaré por esta caja.', '¡No, la caja es mía!\n\nHe venido a buscar gusanos para hacer sopa. Algunos tortolianos dicen que la carne de reptador es mejor para la sopa, pero yo no coincido con ellos. La sopa de reptador no merece el esfuerzo que supone entablar amistad con un desconocido.\n\nLa sopa de gusano de lodo forja amistades para toda la vida, y los tortolianos vivimos mucho tiempo.\n\nEncuéntrame carne de gusano de lodo y me pensaré si te doy esta caja.', 28153),
(149433, 'esES', '¿Esa caja?', '¿Esa caja?', 28153),
(149432, 'esES', 'Estuve aquí parado mucho tiempo. Luego encontré esta interesante caja en el lodo.', 'Estuve aquí parada mucho tiempo. Luego encontré esta interesante caja en el lodo.', 28153),
(149431, 'esES', 'Buen trabajo, colega. Me... ehtaba volviendo loco, ¡mi ehpíritu se consumía lento como una caravana tortoliana!', 'Buen trabajo, colega. Me... ehtaba volviendo loca, ¡mi ehpíritu se consumía lento como una caravana tortoliana!', 28153),
(149430, 'esES', 'Te lo agradezco, $gforahtero:forahtera;.', 'Te lo agradezco, $gforahtero:forahtera;.', 28153),
(149429, 'esES', 'Por fin se acabó. Graciah.', 'Por fin se acabó. Graciah.', 28153),
(149428, 'esES', 'Puedo descansar de nuevo. Graciah, $gforahtero:forahtera;.', 'Puedo descansar de nuevo. Graciah, $gforahtero:forahtera;.', 28153),
(149427, 'esES', 'El... fin...', 'El... fin...', 28153),
(149426, 'esES', '¿Cuál es el plan?', '¿Cuál es el plan?', 28153),
(149425, 'esES', '', 'Yo estaba pensando en descargas eléctricas, o fuego, ¡o tal vez volarlo por los aires y ya está!\n\nPero matar a un tortoliano da mala suerte y yo de eso voy sobrada.\n\nAsí que muéstrame lo que harías tú con este tortoliano.', 28153),
(149424, 'esES', '', 'Tenemos problemas, $p. ¡El tortoliano ha encontrado una caja y la queremos!', 28153),
(149423, 'esES', '¡Maldito pantano! Con ehta humedad todo se ehtropea.\n\nBueno, ¿qué necesitah? Dilo ya pa que pueda volver a mih reparacioneh.', '¡Maldito pantano! Con ehta humedad todo se ehtropea.\n\nBueno, ¿qué necesitah? Dilo ya pa que pueda volver a mih reparacioneh.', 28153),
(149422, 'esES', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'esES', 'Solo los necios más arrogantes considerarían sensato alojar a los Amani dentro de sus muros. Muy buen trabajo, adalid.', '', 28153),
(149420, 'esES', 'El único Amani bueno es el Amani muerto. Pero los Zandalari los refugian en la ciudad. Derrota a sus discípulos, ¡por la Alianza!', '', 28153),
(149419, 'esES', '¡La bestia ha muerto! ¡Gobernalle, asegurad los pisos superiores! Yo me encargo de $geste ladrón:esta ladrona;...', '¡La bestia ha muerto! ¡Gobernalle, asegurad los pisos superiores! Yo me encargo de $geste ladrón:esta ladrona;...', 28153),
(149418, 'esES', '¡Mientras siga en pie, no dejaré que caiga este bastión!', '', 28153),
(149417, 'esES', 'Eso debería recordarles cuál es su lugar.', '', 28153),
(149416, 'esES', '<Mostrarle a Kellam la piedracanto>.', '<Mostrarle a Kellam la piedracanto>.', 28153),
(149415, 'esES', 'La tribu Amani haría bien en recordar que la Horda tiene una posición de fuerza en Zuldazar. ¿Por qué no les refrescas la memoria? Haz sonar su gong y derrota a sus discípulos.', '', 28153),
(149414, 'esES', 'Me adelantaré para ver si encuentro a los granjeros. ¡Que no te capturen!', '', 28153),
(149413, 'esES', '', '¡Taz\'dingo!', 28153),
(149411, 'esES', 'Hay un montón de tesoro en el barro, ¡y Moxie y tú vais a colaborar para encontrarlo!', '', 28153),
(149410, 'esES', '¡No! Los tragadones... no pueden quedar libres...', '', 28153),
(149409, 'esES', '¡A la batalla!', '¡A la batalla!', 28153),
(149408, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(149407, 'esES', 'Luchamos juntos.', 'Luchamos juntos.', 28153),
(149406, 'esES', 'Lucharé a tu lado.', 'Lucharé a tu lado.', 28153),
(149405, 'esES', 'Estoy en deuda contigo, $n.', 'Estoy en deuda contigo, $n.', 28153),
(149404, 'esES', '¡Aún no se ha completado el ritual, hay que domar a los tragadones!', '', 28153),
(149403, 'esES', 'Seguid atacando. Puedo apañármelas solo.', '', 28153),
(149402, 'esES', '', 'Mi fuerza... ¿Qué... eh ehto...?', 28153),
(149401, 'esES', '', 'Mi cuerpo... No puedo... ¡Aaaah!', 28153),
(149400, 'esES', 'Vale.', 'Vale.', 28153),
(149399, 'esES', '', 'Los trabajadores dicen que oyen voces en el barro. ¡Algunos se han vuelto locos!\n\n¡Yo no escucho y punto!', 28153),
(149398, 'esES', '', 'Algunos tipos de Kul Tiras me relacionan con ciertos robos de los que no sé absolutamente nada.', 28153),
(149397, 'esES', '', 'Navego hacia... aguas desconocidas...', 28153),
(149396, 'esES', '', '¡Se comporta como si nunca hubiera visto un gnomo!', 28153),
(149395, 'esES', '', '¡Me estoy hartando de esto!', 28153),
(149394, 'esES', '', 'Salvas de exterminio, ¡fuego!', 28153),
(149393, 'esES', '', '¡Tomad plomo en las tripas!', 28153),
(149392, 'esES', '', '¡Os haré trizas!', 28153),
(149391, 'esES', '', '¡Despejad la cubierta!', 28153),
(149390, 'esES', 'Loh Zandalari... ehtán llenoh de promesah vacíah.', 'Loh Zandalari... ehtán llenoh de promesah vacíah.', 28153),
(149389, 'esES', 'Tendráh noticiah de mi loa...', 'Tendráh noticiah de mi loa...', 28153),
(149388, 'esES', 'Ya no hay ningún sitio seguro pa nosotroh.', 'Ya no hay ningún sitio seguro pa nosotroh.', 28153),
(149387, 'esES', 'En su propia ciudad... noh dejan morir.', 'En su propia ciudad... noh dejan morir.', 28153),
(149386, 'esES', '¿Qué será de nosotroh?', '¿Qué será de nosotroh?', 28153),
(149385, 'esES', 'El imperio... ha caído de verdad.', 'El imperio... ha caído de verdad.', 28153),
(149384, 'esES', '¿Cómo han podido permitir que ocurra... ehto?', '¿Cómo han podido permitir que ocurra... ehto?', 28153),
(149383, 'esES', 'Loh Zandalari... prometieron que ehtaríamoh a salvo...', 'Loh Zandalari... prometieron que ehtaríamoh a salvo...', 28153),
(149382, 'esES', '¡Por fin! Alguien ha encontrado mi ofrenda para Bwonsamdi. ¡Úsala bien!', '¡Por fin! Alguien ha encontrado mi ofrenda para Bwonsamdi. ¡Úsala bien!', 28153),
(149381, 'esES', '', '¡Traedme lo que tengan y haced lo que queráis con sus cuerpos!', 28153),
(149380, 'esES', '', '¡Si mueres, tu parte es para mí!', 28153),
(149379, 'esES', '', 'Tu cabeza quedará ehtupenda en mi colección.', 28153),
(149378, 'esES', '', 'Nos hemos hecho muy $gamigos:amigas; tú y yo. ¿Me prestas algo de oro?', 28153),
(149377, 'esES', '', 'Vi a alguien clavado a ti en Tol Dagor.', 28153),
(149376, 'esES', '¡Hah cometido un gran error!', '¡Hah cometido un gran error!', 28153),
(149375, 'esES', '¡Ayuda! ¡Atacan el bancal!', '¡Ayuda! ¡Atacan el bancal!', 28153),
(149374, 'esES', '¡A por elloh!', '¡A por elloh!', 28153),
(149373, 'esES', '¡No deberíah ehtar aquí, colega!', '¡No deberíah ehtar aquí, colega!', 28153),
(149372, 'esES', '¡Largo! ¡Zandalar pertenece a loh trolh!', '¡Largo! ¡Zandalar pertenece a loh trolh!', 28153),
(149371, 'esES', 'Sabía que algo me olía mal...', 'Sabía que algo me olía mal...', 28153),
(149370, 'esES', '¡Socorro! ¡Me ehtán atacando!', '¡Socorro! ¡Me ehtán atacando!', 28153),
(149369, 'esES', '¡Sucia alimaña!', '¡Sucia alimaña!', 28153),
(149368, 'esES', 'Coda gime y mira a la garganta.', '', 28153),
(149367, 'esES', '', 'Yo también estoy preocupada, Coda.', 28153),
(149366, 'esES', 'Necesito ir a la Estación Punto Este.', 'Necesito ir a la Estación Punto Este.', 28153),
(149365, 'esES', '', '¿Adónde vas?', 28153),
(149364, 'esES', '', '¡Gracias! ¡Y dale muchos abrazos a Roda!', 28153),
(149363, 'esES', '', 'Todos los cañones, ¡fuego!', 28153),
(149362, 'esES', 'Los astilleros serán vuestro nuevo hogar.', '', 28153),
(149361, 'esES', 'Todos serviréis a lord Canto Tormenta en los astilleros.', '', 28153),
(149360, 'esES', 'Todo el mundo a las vagonetas.', '', 28153),
(149359, 'esES', '¡Una vez más, los trols de sangre amenazan a mis hijos!$b$b¡Ven, $gpequeño:pequeña;, juntos les recordaremos lo que pasa cuando hacen enfadar a Krag\'wa!', '', 28153),
(149358, 'esES', '', '¡La ciudad es nuestra, grumetes!', 28153),
(149357, 'esES', '', '¡Tus tripas colgarán del palo mayor!', 28153),
(149356, 'esES', '', 'Otra muesca en mi hoja.', 28153),
(149355, 'esES', '', '¡Todos al ataque!', 28153),
(149354, 'esES', '', '¡Que no queden supervivientes!', 28153),
(149353, 'esES', 'Su espera casi ha terminado.', '', 28153),
(149352, 'esES', '¿Cómo de pronto?', '¿Cómo de pronto?', 28153),
(149351, 'esES', 'La Marea de Hierro nos ataca todos los días y, además, un ejército de la Horda se dirige hacia aquí. Dentro de poco, la ciudad entera tendrá que huir.', '', 28153),
(149348, 'esES', 'Completaré el ritual... ¡con vuehtra sangre!', '', 28153),
(149347, 'esES', 'Vale.', 'Vale.', 28153),
(149346, 'esES', '¿Fracasado? No...', '', 28153),
(149345, 'esES', 'Hay una fortuna en oro en el fondo embarrado del lago. ¡Un barco del tesoro hundido de la Segunda Guerra!\n\n¡La ciudad entera está colaborando para encontrar el tesoro primero! ¡Pero el tiempo apremia, hay que encontrarlo pronto!', '', 28153),
(149344, 'esES', 'Lith qul\'shoth wshh... yzsh uovssh qvask.', '', 28153),
(149343, 'esES', '', 'Se acabó, Jakra\'zet. ¡Tu plan ha fracasado!', 28153),
(149341, 'esES', 'Os debatís en la superficie... pero Él espera abajo.', '', 28153),
(149340, 'esES', '', '¡Juhto a tiempo pa detenerte!', 28153),
(149339, 'esES', 'Llegáih juhto a tiempo...', '', 28153),
(149338, 'esES', '', '¡Sí! ¡Se han vuelto a casa!', 28153),
(149337, 'esES', '¡El ritual de sangre casi ehtá completo!', '', 28153),
(149336, 'esES', '', '¡Por favor, date prisa en encontrarlos! Coda se pondrá muy triste si pierde a su familia.', 28153),
(149335, 'esES', '¿Tesoro?', '¿Tesoro?', 28153),
(149334, 'esES', 'Los Marea de Hierro están apresando a todo el mundo. ¡Intentan evitar que encontremos antes el tesoro!', '', 28153),
(149333, 'esES', '', '¡Volved, pequeños! ¡Podemos ayudaros!', 28153),
(149332, 'esES', '', '¡Si entramos ahí, esos aguijones también acabarán con nosotros!', 28153),
(149331, 'esES', '', '¡No puedo verlos, Coda!', 28153),
(149330, 'esES', 'Zaix lal sk\'woth\'gl Zaix lal uulwi.', '', 28153),
(149329, 'esES', 'La Marea de Hierro está apresando a la gente, ¡nos vendría bien tu ayuda!', '', 28153),
(149328, 'esES', 'Son la redención. Son la verdad.', '', 28153),
(149327, 'esES', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg.', '', 28153),
(149326, 'esES', 'Os ahogaréis todos en el abismo sin luz.', '', 28153),
(149325, 'esES', '', 'Si no explota, prueba otra vez.', 28153),
(149323, 'esES', 'Ni hablar. Tengo órdenes de llevarte directamente ante la Jefa de Guerra.', '', 28153),
(149322, 'esES', '', 'Dado que el barco eh mío, me parece que tendráh que cambiar de planeh.', 28153),
(149321, 'esES', 'Podemoh hablarlo por el camino, Alteza.', '', 28153),
(149320, 'esES', '', 'Vamoh, hay que zarpar hacia Zuldazar.', 28153),
(149319, 'esES', 'Creo que lo que quiereh decir eh \"te lo agradezco\".', '', 28153),
(149318, 'esES', 'Parece que leh vendría bien una... maga como tú, ¿mmm?', '', 28153),
(149317, 'esES', '', 'No... No puede ser.', 28153),
(149315, 'esES', 'Si luchamoh, probablemente venceráh.', '', 28153),
(149314, 'esES', '¿Veh lah llamah que consumen tu ciudad?', '', 28153),
(149313, 'esES', 'No te precipiteh.', '', 28153),
(149312, 'esES', '', 'Entonces, morid.', 28153),
(149311, 'esES', 'Con todo respeto, tenemos que coger un barco.', '', 28153),
(149310, 'esES', '', 'Rendíos y os llevaré de vuelta a las mazmorras, donde debéis estar. Allí esperaréis la justicia del Rey.', 28153),
(149309, 'esES', 'Ehperad aquí.', '', 28153),
(149307, 'esES', 'Ya me he encargado de eso. Mira.', '', 28153),
(149306, 'esES', '¿A qué esperáis? ¡Romped el hielo!', '', 28153),
(149305, 'esES', 'No conozco a ningún Rezan, pero se lo agradezco.', '', 28153),
(149303, 'esES', '', '¡Morid, escoria de la Horda!', 28153),
(149302, 'esES', '', '¡Ha bloqueado nuestra vía de escape!', 28153),
(149300, 'esES', '', 'Necesito veinte de esoh pájaroh.', 28153),
(149299, 'esES', '¡Ajá! Lasan, ¡qué lihto ereh!', '', 28153),
(149298, 'esES', 'No... Pero creo que sé por qué. ¡Mira ahí!', '', 28153),
(149297, 'esES', 'Que loh loa protejan a quien ose contrariarte, Zul.', '', 28153),
(149296, 'esES', '', 'Habéis matado a muchos inocentes para llegar hasta aquí. Pero se acabó.', 28153),
(149295, 'esES', '', '¿No nos persiguen?', 28153),
(149294, 'esES', '¡Ja, ja, ja, ja!', '', 28153),
(149292, 'esES', '', 'Sus fuerzas deben de haber vuelto de Lordaeron. ¿Cómo vamos a pasar?', 28153),
(149291, 'esES', '¡En marcha!', '', 28153),
(149290, 'esES', '', 'Mi loa noh acompaña. Poderoso Rezan, ¡préhtame tu fuerza!', 28153),
(149289, 'esES', '', '¡No haréis daño a una sola alma más de esta ciudad!', 28153),
(149288, 'esES', '', '¡Hasta aquí habéis llegado!', 28153),
(149287, 'esES', 'Tened cuidado. Parece que la diplomática más famosa de la Alianza no tomará prisioneros esta vez.', '', 28153),
(149286, 'esES', '¡¡¡Puaj!!!', '', 28153),
(149285, 'esES', '', '¡Has encontrado a mi mamá! ¡Muchas gracias por salvarla de los monstruos malos!', 28153),
(149284, 'esES', '', 'Gracias por traer mi juguete. Si ves a mi mamá, ¿le puedes pedir que venga a casa, por favor?\n\nHace rato que no la veo.', 28153),
(149283, 'esES', 'Ahora. Rompe el último sello.', '', 28153),
(149282, 'esES', '', 'Talanji, sigue a Zul con tu adalid. Yo reuniré a todo el que pueda pa intentar frenar al Desintegrador. Hará falta un ejército pa acabar con esa cosa.', 28153),
(149281, 'esES', 'Controla a Mythrax. Debemos detener al sirviente del Imperio Negro.', '', 28153),
(149280, 'esES', '', 'Adalid, loh loa y yo retendremoh a Mythrah todo lo posible. ¡Buhca a mi padre y acabad con Zul!', 28153),
(149279, 'esES', 'Ven, Mythrah. Ven, Desintegrador. Debemoh romper el último sello.', '', 28153),
(149278, 'esES', 'El camino está despejado, pequeños. Moveos. Mythrax se acerca.', '', 28153),
(149277, 'esES', '', 'Hermanoh y hermanah de Zandalar, ¡recuperemoh la ciudad! ¡Avanzad!', 28153),
(149276, 'esES', '', 'Adalid, buhca a loh civileh que queden en El Zócalo y envíaloh pa acá. Luego noh reuniremoh cuando podamoh.', 28153),
(149275, 'esES', '', 'Fatal. Ehtamoh rodeadoh. Loh loa hacen lo que pueden, pero necesitamoh a todo trol capaz de empuñar un arma.', 28153),
(149274, 'esES', '', 'En tiempoh desehperadoh, medidah ehtraordinariah. ¿Qué tal todo?', 28153),
(149273, 'esES', '', 'Talanji, veo que vah a la batalla en loa.', 28153),
(149272, 'esES', '', 'Rakera, veo que te hah puehto al mando del ejército.', 28153),
(149271, 'esES', '', '¡Formad filah! Arqueroh, ¡preparaoh!', 28153),
(149270, 'esES', '', 'Resulta... muy... inoportuno.', 28153),
(149269, 'esES', '', 'Al parecer, Mythrah el Desintegrador se ha alzado.', 28153),
(149268, 'esES', '', 'Algo hace que los sethrak ataquen. Nunca los había visto arremeter de esta manera.', 28153),
(149267, 'esES', '', 'Ten cuidado, padre. Un enemigo muy poderoso ha preparado con paciencia ehte plan.', 28153),
(149266, 'esES', 'Talanji, llévate a tu adalid de la Horda y reúne allí a lah tropah. Krag\'wa y yo protegeremoh el Rehquicio Frondoso.', '', 28153),
(149265, 'esES', '', '¡Rastakhan! Las serpientes de Vol\'dun asedian tu frontera oeste. Haz algo.', 28153),
(149264, 'esES', 'Ehtán entrando demasiadoh. Ve al puente de Dazar\'alor. Loh forzaremoh a luchar en un lugar ehtrecho.', '', 28153),
(149263, 'esES', 'Una ofrenda pa Bwonsamdi.', '', 28153),
(149262, 'esES', 'Morid, invasoreh.', '', 28153),
(149261, 'esES', 'Hay demasiadoh...', '', 28153),
(149260, 'esES', 'Loh invasoreh atraviesan la Puerta de Sangre. Rápido, ¡matemoh a cuantoh podamoh anteh de que entren en la ciudad!', '', 28153),
(149259, 'esES', '', 'La tormenta es imparable...', 28153),
(149258, 'esES', '', '¡El imperio de los infieles es imparable!', 28153),
(149257, 'esES', 'Me las arreglaré para salir de aquí. ¡Ten cuidado!', '', 28153),
(149256, 'esES', 'Gracias... Creí que ya no lo contaba.', '', 28153),
(149255, 'esES', 'Así debería bastar. ¿Qué se siente al saquear en solitario toda una ciudad?', '', 28153),
(149254, 'esES', 'Corre... ¡¡¡CORRE!!!', '', 28153),
(149253, 'esES', 'Es demasiado pronto. ¡Aún no se ha ahogado en la gloria del amo!', '', 28153),
(149252, 'esES', '¡No, no, no! ¡La ciudad está en pie de guerra! Yo me encargo de que salgamos de aquí.', '', 28153),
(149250, 'esES', 'Intenta usar la daga que te he metido en el bolsillo. Creo que te gustará.', '', 28153),
(149249, 'esES', 'Después de ti. Marca los blancos seguros y yo me ocuparé de ellos.', '', 28153),
(149248, 'esES', 'Una vez rota, la confianza es casi imposible de reparar. Esto dañará a los Zandalari nobles. Bien hecho, adalid.', '', 28153),
(149247, 'esES', 'Representantes de las tribus trol inferiores se reúnen bajo la protección de los Zandalari, pero son vulnerables. Mata a sus portavoces y siembra la discordia entre nuestros enemigos.', '', 28153),
(149246, 'esES', '¡Quemadles los carros y rompedles los huesos!', '¡Quemadles los carros y rompedles los huesos!', 28153),
(149245, 'esES', '¡Si estas alimañas esconden la llave, la encontraremos!', '¡Si estas alimañas esconden la llave, la encontraremos!', 28153),
(149244, 'esES', 'No matéis a los fuertes. Se venderán bien en el mercado.', 'No matéis a los fuertes. Se venderán bien en el mercado.', 28153),
(149243, 'esES', '¿Casi ha acabado? ¡Dime que casi ha acabado!', '', 28153),
(149242, 'esES', '¡Vuelve aquí!', '¡Vuelve aquí!', 28153),
(149241, 'esES', '', 'Deberíamos ir dirigiéndonos al risco del noroeste. Desde Puesto de Arom habrá buena visibilidad para nuestra señal.', 28153),
(149240, 'esES', '', '¡Pero antes de ir deberíamos aprovechar la situación y diezmar a su ejército!', 28153),
(149239, 'esES', '', 'Podemos señalar para la extracción en el terreno elevado al noroeste de aquí.', 28153),
(149238, 'esES', '¡Qué locura! ¡No vayas tan rápido!', '', 28153),
(149237, 'esES', 'Me encanta cuando pega esos pisotones.', '', 28153),
(149236, 'esES', '', 'Usar su propia arma contra ellos resulta bastante satisfactorio.', 28153),
(149235, 'esES', 'El fuego desprende un humo morado. En cuanto se eleve por encima de los árboles, lo verán.', '', 28153),
(149234, 'esES', 'Deja que antes dé la señal a los demás para que comiencen el ataque.', '', 28153),
(149233, 'esES', 'No. Con el tiempo, vendrá él.', '', 28153),
(149232, 'esES', '', '¿Deberíamoh perseguirloh?', 28153),
(149231, 'esES', 'Se acabó el tratar con invasoreh y con loa. La sangre eh el nuevo camino... ¡El camino de G\'huun!', '', 28153),
(149230, 'esES', 'Ahora no tengo mucha hambre. Vuelve máh tarde...', '', 28153),
(149229, 'esES', '¿Me creerías si te dijera que todo esto va según el plan? Ya, lo suponía.', '', 28153),
(149228, 'esES', '¡Buenas noticias! He localizado al enemigo: está por todas partes.', '', 28153),
(149227, 'esES', '¿Podríamos... no contarle a Roz lo que ha pasado?', '', 28153),
(149226, 'esES', 'Este no es mi mejor momento.', '', 28153),
(149225, 'esES', 'Ehcucha ehta profecía: el imperio trol dominará ehte mundo, al final como fue en un principio. En su trono habrá un rey, al final como fue en un principio, pero ni tú ni yo viviremoh pa verlo. Esa eh la visión que me ha mostrado mi dioh...', '', 28153),
(149224, 'esES', 'Te hah quedado atráh, viejo amigo. Hah dejado que nuehtro reino se pudra. Pero he predicho un nuevo apogeo del imperio trol.', '', 28153),
(149223, 'esES', 'Deberíah haber ehcuchado a Talanji.', '', 28153),
(149221, 'esES', '¡No! ¡Habutu!', '', 28153),
(149220, 'esES', '¡Ja! ¡Buen trabajo!', '', 28153),
(149219, 'esES', 'La hora de la sangre se acerca.', '', 28153),
(149218, 'esES', 'El tiempo de loh loa... ha pasado.', '', 28153),
(149217, 'esES', 'No soy tu súbdito...', '', 28153),
(149216, 'esES', 'Rezan, Rezan...', '', 28153),
(149215, 'esES', 'Cuidado con lo que dices, traidor.', '', 28153),
(149214, 'esES', 'Ah, aquí llega: el loa de... Mmm...', '', 28153),
(149212, 'esES', '', 'Ehpero que tuh visioneh sean correctah.', 28153),
(149211, 'esES', '¡Herejía!', '', 28153),
(149210, 'esES', '', '¡Adelantaos al siguiente movimiento de vuestro compañero!', 28153),
(149209, 'esES', '', '¡Golpead como el viento! ¡Bloquead!', 28153),
(149208, 'esES', '', '¡No habrá descanso hasta que acabe el entrenamiento!', 28153),
(149207, 'esES', '', '¡Centraos en vuestro compañero! ¡Golpead con decisión!', 28153),
(149206, 'esES', '¡Comandante! ¿Está... inconsciente?', '¡Comandante! ¿Está... inconsciente?', 28153),
(149205, 'esES', 'Hermana, ¿estás bien? ¡No quería golpear tan fuerte!', 'Hermana, ¿estás bien? ¡No quería golpear tan fuerte!', 28153),
(149204, 'esES', 'Vaya... ¿Te he...? ¿Estás bien?', 'Vaya... ¿Te he...? ¿Estás bien?', 28153),
(149200, 'esES', 'No hay nada como acabar con un comandante de la Alianza. Y tan fácilmente...', '', 28153),
(149199, 'esES', '', 'Que el viento te sea favorable.', 28153),
(149198, 'esES', '', 'La Orden de Ascuas ha vuelto a hacer frente a Gorak Tul. Con aliados, podremos seguir resistiendo.', 28153),
(149197, 'esES', '', 'Gracias por ayudarme. Informaré a lady Lucille de que la misión ha sido un éxito.', 28153),
(149196, 'esES', 'Tiemblo de pensar qué habría sido de mí si la inquisidora y tú no hubieseis intervenido.', '', 28153),
(149195, 'esES', 'Me alegro de seguir con vida.', '', 28153),
(149194, 'esES', '', 'Ahora sobrevolar el bosque es seguro. Espero que lleguen rápido.', 28153),
(149193, 'esES', '', 'Hay jinetes de grifos esperando esta señal.', 28153),
(149192, 'esES', 'Torpe, muy torpe. ¡Haz menos ruido la próxima vez!', '', 28153),
(149191, 'esES', '¡Maldita sea! Esto tenía que ser rápido y discreto. ¡Concéntrate!', '', 28153),
(149190, 'esES', 'Rápido, ¡asegúrate de que no alerta a los demás!', '', 28153),
(149189, 'esES', '¡Que no te detecten! No podemos llamar demasiado la atención...', '', 28153),
(149187, 'esES', 'Aaah, no, no. Ya me encargo yo.', '', 28153),
(149186, 'esES', 'Yo voy a mirar para otro lado. No puedo decir que haya matado antes a un hombre dormido.', '', 28153),
(149185, 'esES', 'Oye, oye. Cuidado con los civiles: podríamos atraer la atención de los guardias.', '', 28153),
(149184, 'esES', 'No era un guardia, pero no seré yo quien te impida matar a un miembro de la Alianza.', '', 28153),
(149183, 'esES', 'Técnicamente no hace falta que matemos a los civiles, pero me gusta tu estilo.', '', 28153),
(149182, 'esES', 'Eres como el hielo... Me gusta.', '', 28153),
(149181, 'esES', 'Un ingeniero vio a unos matones de la Alianza cerca de nuestra mina mientras buscaba piezas de repuesto. Ve a ver a Margie al taller para que te dé más detalles y para eh..., prepararte.', '', 28153),
(149180, 'esES', 'El pecho... ¡No puedo respirar!', 'El pecho... ¡No puedo respirar!', 28153),
(149179, 'esES', '¡La garganta... se me cierra!', '¡La garganta... se me cierra!', 28153),
(149178, 'esES', 'Me parece que voy a vomitar...', 'Me parece que voy a vomitar...', 28153),
(149177, 'esES', 'Solo necesito... descansar...', 'Solo necesito... descansar...', 28153),
(149176, 'esES', 'Todo está tan... oscuro...', 'Todo está tan... oscuro...', 28153),
(149175, 'esES', 'Me siento... extraño.', 'Me siento... extraña.', 28153),
(149174, 'esES', '¡No! ¡Noooo!', '', 28153),
(149173, 'esES', '¡¿Q-qué?!', '', 28153),
(149172, 'esES', '¡Vosotros! ¡Alto ahí!', '', 28153),
(149171, 'esES', '', 'Eh como si quisieran morir... Solo ehpero que su sangre no alimente a G\'huun.', 28153),
(149170, 'esES', '', 'Si siguen desafiando a Bwonsamdi, ehto no acabará bien pa elloh. Adalid, nuehtro pacto con Bwonsamdi se mantiene. ¡Envíale ehtah almah dehcarriadah!', 28153),
(149169, 'esES', 'Ah, no. Era solo mi otra pierna, todo bien.', '', 28153),
(149168, 'esES', '¡Algo me ha tocado la pierna!', '', 28153),
(149167, 'esES', 'La veta madre está a buen recaudo. ¡Ven a por tu parte!', '', 28153),
(149166, 'esES', '¡A nuestros mineros les ha tocado el premio gordo! Trae la carga a la base, nos vamos a hacer de oro.', '', 28153),
(149165, 'esES', '', '¡Vamos! No te quitaré el ojo de encima.', 28153),
(149164, 'esES', '', '¡Los explosivos nunca sobran!', 28153),
(149163, 'esES', '', '¿Conoces a algún noble de Kul Tiras que tenga montañas de oro y poca seguridad?', 28153),
(149162, 'esES', '', 'Estoy buscando gente inteligente como tú, $p, para invertir muchísimo oro en un nuevo negocio que estoy montando.', 28153),
(149161, 'esES', '', 'Una gnoma tiene que cubrirse las espaldas entre toda esta gente de Kul Tiras.', 28153),
(149160, 'esES', '', 'En caso de duda, hazlo explotar.', 28153),
(149159, 'esES', '', 'Tol Barad, Tol Dagor, las Mazmorras de Ventormenta... ¡Las conozco todas!', 28153),
(149158, 'esES', 'Manda la señal. ¡Salgamos de aquí!', 'Manda la señal. ¡Salgamos de aquí!', 28153),
(149157, 'esES', '', 'Por favor, Rakera, ¡no lo hagah! ¡Conseguiráh que te maten!', 28153),
(149156, 'esES', '', '¡Gracias a las arenas que estás a salvo!', 28153),
(149155, 'esES', '', '¡Ehta intromisión acaba aquí! ¡No vaih a interrumpir a la maehtra!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'esES', 'Estos pequeñajos no parecen una gran amenaza, $r.', '', 28153),
(149151, 'esES', '', '¡Sigues con vida, $p! Tienes suerte, como yo.', 28153),
(149150, 'esES', 'Noh vemoh máh tarde.', '', 28153),
(149149, 'esES', '¿Eso eh todo?', '', 28153),
(149148, 'esES', 'Relájate.', '', 28153),
(149147, 'esES', 'Deja atráh lah preocupacioneh.', '', 28153),
(149146, 'esES', '¿Necesitah el vudú?', '', 28153),
(149145, 'esES', '¿Qué necesitah?', '', 28153),
(149144, 'esES', '', 'Mientrah siga viva, loh trolh de sangre no volverán a engañarnoh.', 28153),
(149143, 'esES', '', 'Loh trolh de sangre tratan de pillarnoh por sorpresa, pero tengo algo pa ayudarte a verloh. ¡Úsalo y acaba con elloh!', 28153),
(149142, 'esES', 'Recupera el aliento. No pararemos hasta llegar al barco.', '', 28153),
(149141, 'esES', '¡Corro! ¡Corro como el viento!', '¡Corro! ¡Corro como el viento!', 28153),
(149140, 'esES', 'Zul acabará por matarnoh a todoh.', 'Zul acabará por matarnoh a todoh.', 28153),
(149139, 'esES', '¡Eh el fin de loh tiempoh!', '¡Eh el fin de loh tiempoh!', 28153),
(149138, 'esES', 'Ehto eh malísimo pa el negocio.', 'Ehto eh malísimo pa el negocio.', 28153),
(149137, 'esES', 'Me largo de aquí.', 'Me largo de aquí.', 28153),
(149136, 'esES', '¡Eh! ¡¿Qué está pasando aquí?!', '', 28153),
(149135, 'esES', '¡Guardia! ¡Guardia! ¡Ayuda! ¡Oh!', '', 28153),
(149134, 'esES', '¡Ah! ¡Bestia parda!', '', 28153),
(149133, 'esES', 'No te cortes, pega con ganas.', '', 28153),
(149132, 'esES', '¡Venga, pégame!', '', 28153),
(149131, 'esES', 'Pégame.', '', 28153),
(149130, 'esES', 'Muy bien, este es el plan.', '', 28153),
(149129, 'esES', 'Entrada tres: ¡Casi lo he conseguido! Las abejas crecen y la productividad aumenta de manera exponencial. Aunque debo vigilar mejor a la reina...', '', 28153),
(149128, 'esES', 'Entrada dos: El hidromiel animado empieza a dar muestras de agresividad. Puede que haya cometido un ligero error de cálculo.', '', 28153),
(149127, 'esES', 'Entrada uno: La miel ha cobrado vida, pero se multiplica más rápido de lo que jamás había soñado. ¡Debo realizar más pruebas!', '', 28153),
(149126, 'esES', '¡Sofocad las llamas! ¡Que no escapen!', '', 28153),
(149125, 'esES', '¡Mira cómo huyen con el rabo entre las piernas!', '', 28153),
(149124, 'esES', '¡Huid como las alimañas que sois!', '', 28153),
(149123, 'esES', '', 'Esto es absurdo. Moriréis aquí y lo único que conseguiréis será una tumba sin nombre.', 28153),
(149122, 'esES', '', 'Sé que la Horda es cruel y desalmada. Despiadada con tal de vencer. Pero ¿esto...?', 28153),
(149121, 'esES', '¡Los he encontrado, mi Rey! ¡Te traeré sus pellejos como trofeo!', '', 28153),
(149120, 'esES', 'No hagah como si no te alegrarah de vernoh.', '', 28153),
(149119, 'esES', 'Estoy emocionadísimo. Venga, en marcha. A tu señal.', '', 28153),
(149118, 'esES', '', 'No tieneh piedad con el enemigo, Zul.', 28153),
(149117, 'esES', '', 'No podemos luchar contra ella. ¡Corred!', 28153),
(149116, 'esES', '', '¿Qué pasa ahora?', 28153),
(149115, 'esES', 'Parece que estamos en un buen lío.', '', 28153),
(149114, 'esES', '', '¡El puerto! ¡Casi estamos allí!', 28153),
(149113, 'esES', 'No sabía que la piedra fuera tan... inflamable.', '', 28153),
(149112, 'esES', 'Ehtán intentando acorralarnoh. ¡No lo permitáih!', '', 28153),
(149111, 'esES', 'Debemoh ehperar aquí.', '', 28153),
(149110, 'esES', 'Tenemoh que volver a loh canaleh. ¡Seguidme!', '', 28153),
(149109, 'esES', 'Vaya, vaya, ehto podría sernoh útil.', '', 28153),
(149108, 'esES', '', '¡Tenemos que refugiarnos!', 28153),
(149107, 'esES', '', '¡Cuidado!', 28153),
(149106, 'esES', 'El viejo lobo noh ha olido. ¡Tenemoh que irnoh!', '', 28153),
(149105, 'esES', '', '¡Son demasiados! ¡La barrera no aguantará!', 28153),
(149104, 'esES', '¡Ahí está! ¡Detenlos antes de que lleguen a las puertas!', '¡Ahí está! ¡Detenlos antes de que lleguen a las puertas!', 28153),
(149103, 'esES', '¿Creías que te habías escapado? ¡Pues no!', '¿Creías que te habías escapado? ¡Pues no!', 28153),
(149102, 'esES', '¡Ahí abajo! ¡A por esos recursos!', '¡Ahí abajo! ¡A por esos recursos!', 28153),
(149101, 'esES', '', 'Loh trolh de sangre son criaturah malvadah y siniehtrah. Nunca cambiarán.', 28153),
(149100, 'esES', '', 'Loh trolh de sangre ehtán devorando a mi gente. ¡Detenloh!', 28153),
(149099, 'esES', '¡El alboroto atrae a Picomuerte!', '¡El alboroto atrae a Picomuerte!', 28153),
(149098, 'esES', '¡Los hachapicos se sienten atraídos por el olor del cebo en el agua!', '¡Los hachapicos se sienten atraídos por el olor del cebo en el agua!', 28153),
(149097, 'esES', '¡Gracias! No me apetecía que me clavaran en una pica.', '', 28153),
(149096, 'esES', '¡Ahí estás! ¿Te importaría echarme una mano?', '', 28153),
(149095, 'esES', 'Se agradece tu entusiasmo. Nos reuniremos con la señorita Crestavía.', '', 28153),
(149094, 'esES', '', '¿Un poquito de ayuda?', 28153),
(149093, 'esES', 'Gracias por la ayuda.', '', 28153),
(149092, 'esES', '¡Condenadas brujas y sus barreras!', '', 28153),
(149091, 'esES', '', 'Ehtah críah crecen bien. Algún día serán buenah behtiah de guerra.', 28153),
(149090, 'esES', '', 'Lah behtiah de guerra jóveneh requieren mucho afecto y cuidadoh. Deben aprender a interactuar con nosotroh tanto como nosotroh con ellah.', 28153),
(149089, 'esES', '¡Oigo la llamada!', '', 28153),
(149088, 'esES', 'Perdí todah lah armah, pero al menoh no perdí la vida.', '', 28153),
(149087, 'esES', 'Me sorprendieron mientrah ehtaba ehplorando. No volvera á pasar.', '', 28153),
(149086, 'esES', '¡Voy a hacérselo pagar a esoh trolh de sangre!', '', 28153),
(149085, 'esES', 'Graciah, me vuelvo a Zul\'jan.', '', 28153),
(149084, 'esES', '', 'Graciah. ¡Máh vale que loh goblinh se centren en salvar mi ciudad y no en sacar beneficioh!', 28153),
(149083, 'esES', '', 'Loh no-muertoh han atrapado a un grupo de prohpectoreh goblinh. ¡Debemoh liberarloh!', 28153),
(149082, 'esES', '¿Sabes para qué se puede usar este alquitrán? Yo tampoco, ¡pero dicen que pagan MUCHO por él!', '', 28153),
(149081, 'esES', 'Esto es un agujero, en el peor de los sentidos. Yo me largo de aquí.', '', 28153),
(149080, 'esES', 'Sí, bueno, iba a salir de todos modos. ¡Este alquitrán se venderá a precio de oro!', '', 28153),
(149079, 'esES', '¡Por qué poco! Oye, cógeme un poco de alquitrán, ¿quieres? Podemos venderlo por un buen pico en casa.', '', 28153),
(149078, 'esES', 'Gracias, ¿quién iba a imaginar lo peligroso que sería sacar alquitrán de un pantano prohibido?', '', 28153),
(149076, 'esES', 'Korthek se ha vuelto loco. Debo encargarme de esto personalmente. Protege las llaves en mi ausencia.', '', 28153),
(149075, 'esES', '', 'Ahora loh trolh de sangre sabrán que suh díah ehtán contadoh.', 28153),
(149074, 'esES', '', 'El Ehcuadrón Gob tiene un plan contra loh trolh de sangre. A ver qué puedeh hacer pa mantenerloh con vida.', 28153),
(149073, 'esES', 'Subamos al MEMOV y detengamos a ese ejército de trols de sangre.', 'Subamos al MEMOV y detengamos a ese ejército de trols de sangre.', 28153),
(149072, 'esES', '¡Eh! Hay unos trols de sangre chungos camino de Zuldazar. ¡Por suerte le hemos hecho alguna mejorilla al MEMO!\n\nDeléitate con el MEMOV. ¡Esta monada puede volar! ¡Muerte desde el cielo!\n\nClaro que tuvimos que quitarle el escudo, no podía volar con él.\n\n¿Quieres llevarlo a dar una vuelta? ¡Podemos despedazar a ese ejército!', '', 28153),
(149071, 'esES', 'No sirves para nada... Como los demás...', '', 28153),
(149070, 'esES', '¿Más escoria exiliada para matar? Hoy es un buen día.', '', 28153),
(149066, 'esES', 'Vete, pequeño Rey. Me tragaré a todos los que intenten seguirte.', '', 28153),
(149065, 'esES', 'Bueno, nada no.', '', 28153),
(149064, 'esES', '', 'Zul ehtá muy tranquilo. Puede que no sea nada.', 28153),
(149063, 'esES', 'No pueden haber ido lejos. Vuestra vigilancia nos protege a todos.', '', 28153),
(149062, 'esES', '¡Intrusos de la Horda se han infiltrado en las Mazmorras! ¡Permaneced en vuestras casas hasta que haya pasado la amenaza!', '', 28153),
(149061, 'esES', '¡El Rey lo ordena!', '', 28153),
(149060, 'esES', 'Puedo mantenernoh ocultoh, siempre y cuando nadie haga ninguna ehtupidez.', '', 28153),
(149059, 'esES', '¡Ja, ja! No te preocupes, mi querido Ancel, ¡solo es un contratiempo! Volveremos a estar funcionando en breve.', '¡Ja, ja! No te preocupes, mi querido Ancel, ¡solo es un contratiempo! Volveremos a estar funcionando en breve.', 28153),
(149058, 'esES', '¡¿D-d-de qué estás hablando?! ¡Casi te matas y te cargas toda la granja!', '', 28153),
(149057, 'esES', '¡De que depende de nosotros impulsar el arte de la producción de miel, cueste lo que cueste!', '¡De que depende de nosotros impulsar el arte de la producción de miel, cueste lo que cueste!', 28153),
(149056, 'esES', 'Se ve que no hacía falta.', '', 28153),
(149055, 'esES', 'AHORA.', '', 28153),
(149054, 'esES', '¿Cómo?', '', 28153),
(149053, 'esES', '', 'No te preocupeh, si su vida ehtá en peligro lo sabremoh.', 28153),
(149052, 'esES', 'Continuemoh.', '', 28153),
(149051, 'esES', '', 'Espera... ¿Y los guardias?', 28153),
(149050, 'esES', 'Máh vale darse prisa. No oh separéih.', '', 28153),
(149049, 'esES', '¿No podíah avisarnoh con tiempo?', '', 28153),
(149048, 'esES', 'Atentos, el IV:7 nos ha informado de que el enemigo ha salido cerca del castillo.', '', 28153),
(149047, 'esES', 'Saltad al canal. Ya.', '', 28153),
(149046, 'esES', 'Crucemoh por el puente. A menoh que eso sea un problema pa tu profeta.', '', 28153),
(149045, 'esES', 'Rápido, fuera del camino.', '', 28153),
(149044, 'esES', 'Paremoh aquí.', '', 28153),
(149043, 'esES', '¡Atención, ciudadanos de Ventormenta!', '', 28153),
(149042, 'esES', 'Bien, no oh separéih. Ahora somoh todoh amigoh.', '', 28153),
(149041, 'esES', '', 'Toda la ciudad nos busca. Debemos marcharnos cuanto antes.', 28153),
(149040, 'esES', '¡Listo para zarpar!', '¡Lista para zarpar!', 28153),
(149039, 'esES', '', '¿Estás $gpreparado:preparada; para el viaje a Kul Tiras?', 28153),
(149038, 'esES', '', 'Graciah a ti, hemoh ganado algo de tiempo pa que Krag\'wa prepare suh defensah. Graciah.', 28153),
(149037, 'esES', '¡No podéis evitar que reclame lo que es mío!', '', 28153),
(149036, 'esES', '', '¡Loh trolh de sangre siguen atacando a Krag\'wa! ¡Acaba con suh suminihtroh y que paguen caro ehte ataque!', 28153),
(149035, 'esES', 'Sethraliss... He olvidado tu voz...', '', 28153),
(149034, 'esES', 'Nosotros no dependemos de los loa. ¡Somos los amos de nuestra propia fuerza!', '', 28153),
(149033, 'esES', '¡Intrusos! Os metéis en asuntos que no comprendéis.', '', 28153),
(149031, 'esES', 'ESCENA PLACEHOLDER - Talanji pregunta si de verdad todo ha terminado, Rokhan dice que el mal tiene la capacidad de sobrevivir y que duda que sea la última vez que vea este lugar.\nToma: planos cortos de Talanji y Rokhan y luego una toma ominosa del foso recién descubierto.', 'ESCENA PLACEHOLDER - Talanji pregunta si de verdad todo ha terminado, Rokhan dice que el mal tiene la capacidad de sobrevivir y que duda que sea la última vez que vea este lugar.\nToma: planos cortos de Talanji y Rokhan y luego una toma ominosa del foso recién descubierto.', 28153),
(149030, 'esES', '', 'Maestro... He... fracasado...', 28153),
(149029, 'esES', '', 'Viene... Gorak Tul...', 28153),
(149028, 'esES', '', 'Gorak Tul... me prometió poder...', 28153),
(149027, 'esES', '', 'Puede que no sirva para luchar, pero mi madre debe pagar por sus crímenes y yo debo asegurarme de que se hace justicia.', 28153),
(149026, 'esES', '', '¡Por mi padre y por Drustvar!', 28153),
(149025, 'esES', '', 'Nos veremos dentro.', 28153),
(149024, 'esES', '', '¡Inquisidores, a mí! ¡Gloria a la casa Crestavía!', 28153),
(149023, 'esES', '', 'Sí, señora. Acabaremos con el aquelarre.', 28153),
(149022, 'esES', '', 'Inquisidores, llega la batalla final. Que los vientos os sean favorables.', 28153),
(149021, 'esES', '', 'Madre... ¿Qué has hecho?', 28153),
(149020, 'esES', '', 'Mariscal, no...', 28153),
(149019, 'esES', 'Lo... siento...', '', 28153),
(149018, 'esES', 'Querida Lucy... Te he... fallado...', '', 28153),
(149017, 'esES', '', '¡Resíste, Mariscal!', 28153),
(149016, 'esES', 'No... Esto no está... ¡bien!', '', 28153),
(149015, 'esES', 'Yo... obedezco...', '', 28153),
(149014, 'esES', 'Cubriremos los flancos. ¡No te separes de Lucille y el mariscal!', '', 28153),
(149013, 'esES', '', '¡Le has chillado a la mujer equivocada, bruja!', 28153),
(149012, 'esES', '¡Seguid, casi lo hemos conseguido! ¡A los ojos, Winston!', '', 28153),
(149011, 'esES', 'Yo te seguiré.', 'Yo te seguiré.', 28153),
(149010, 'esES', '¡Por la casa Crestavía!', '', 28153),
(149009, 'esES', '¡No os separéis y no dejéis de avanzar hasta cruzar las puertas de la mansión!', '', 28153),
(149008, 'esES', 'A ehte ritmo no duraremoh mucho. Tenemoh que llegar a loh muelleh.\n\nCuando tú digah, iremoh.', '', 28153),
(149007, 'esES', 'Inquisidores, ¡esta es nuestra oportunidad de rescatar a lord y lady Crestavía, y poner fin a este aquelarre insufrible!', '', 28153),
(149005, 'esES', '', 'Me encanta que la Alianza tiemble ante mí.', 28153),
(149004, 'esES', '', 'Que nadie se mueva.', 28153),
(149003, 'esES', '', '¿Creías que tenías alguna posibilidad?', 28153),
(149002, 'esES', '', 'Que te derrote... semejante escoria...', 28153),
(149001, 'esES', '¡Vuestras posibilidades de victoria son nulas!', '', 28153),
(149000, 'esES', '¡Cambio de posición!', '', 28153),
(148999, 'esES', '¡Prendedle fuego!', '', 28153),
(148998, 'esES', 'Eso ha sido... trampa...', '', 28153),
(148997, 'esES', '¡Yo te curo!', '', 28153),
(148996, 'esES', '¡Posición de defensa!', '', 28153),
(148995, 'esES', 'La Luz... me guiará de vuelta.', '', 28153),
(148994, 'esES', '', '¡A por el corazón!', 28153),
(148993, 'esES', '', '¡Enviaré tu alma a Gorak Tul!', 28153),
(148991, 'esES', '¡Preparaos! Ahí vienen.', '¡Preparaos! Ahí vienen.', 28153),
(148990, 'esES', '¡Proteged los recursos!', '¡Proteged los recursos!', 28153),
(148989, 'esES', '¡Esta madera es nuestra!', '¡Esta madera es nuestra!', 28153),
(148988, 'esES', '¡No os acerquéis más!', '¡No os acerquéis más!', 28153),
(148987, 'esES', '¡Atrás!', '¡Atrás!', 28153),
(148986, 'esES', 'Los guardianes eran los más poderosos de entre nosotros, los encargados de encerrar el cadáver de Mythrax dentro de la gran pirámide.\n\nSulthis era el fundador, pero no podía sellar la tumba él solo.\n\nPidió ayuda a Vorrik y Korthek, y juntos crearon una barrera alrededor de la gran pirámide, dejando encerrado en su interior el cadáver de Mythrax.', 'Los guardianes eran los más poderosos de entre nosotros, los encargados de encerrar el cadáver de Mythrax dentro de la gran pirámide.\n\nSulthis era el fundador, pero no podía sellar la tumba él solo.\n\nPidió ayuda a Vorrik y Korthek, y juntos crearon una barrera alrededor de la gran pirámide, dejando encerrado en su interior el cadáver de Mythrax.', 28153),
(148985, 'esES', 'Se hace llamar emperador Korthek, pero mucho tiempo atrás fue uno de los guardianes a los que se encomendó proteger la tumba.\n\nSu ansia de guerra va en contra de todo lo que nuestra loa representa y, aun así, él la denuncia y desafía levantando un ejército con planes para conquistar todo Zuldazar.', 'Se hace llamar emperador Korthek, pero mucho tiempo atrás fue uno de los guardianes a los que se encomendó proteger la tumba.\n\nSu ansia de guerra va en contra de todo lo que nuestra loa representa y, aun así, él la denuncia y desafía levantando un ejército con planes para conquistar todo Zuldazar.', 28153),
(148984, 'esES', 'Los infieles son una fuerza de sethrak militantes, comandados por el emperador Korthek.\n\nHace mucho tiempo vivíamos todos unidos, como Sethraliss habría querido.\n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras.\n\nNo se detendrán hasta haber conquistado el mundo.', 'Los infieles son una fuerza de sethrak militantes, comandados por el emperador Korthek.\n\nHace mucho tiempo vivíamos todos unidos, como Sethraliss habría querido.\n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras.\n\nNo se detendrán hasta haber conquistado el mundo.', 28153),
(148983, 'esES', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax asoló nuestras tierras y amenazaba con borrarnos de la existencia, fue ella quien lo detuvo, dando su vida para salvar las nuestras.\n\nAl contrario que los infieles, aún sentimos su presencia, y creemos que algún día nos será devuelta.', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax asoló nuestras tierras y amenazaba con borrarnos de la existencia, fue ella quien lo detuvo, dando su vida para salvar las nuestras.\n\nAl contrario que los infieles, aún sentimos su presencia, y creemos que algún día nos será devuelta.', 28153),
(148982, 'esES', 'Los guardianes eran los más poderosos de entre nosotros, los encargados de encerrar el cadáver de Mythrax dentro de la gran pirámide.\n\nSulthis era el fundador, pero no podía sellar la tumba él solo.\n\nPidió ayuda a Vorrik y Korthek, y juntos crearon una barrera alrededor de la gran pirámide, dejando encerrado en su interior el cadáver de Mythrax.', '', 28153),
(148981, 'esES', 'Se hace llamar emperador Korthek, pero mucho tiempo atrás fue uno de los guardianes a los que se encomendó proteger la tumba.\n\nSu ansia de guerra va en contra de todo lo que nuestra loa representa y, aun así, él la denuncia y desafía levantando un ejército con planes para conquistar todo Zuldazar.', '', 28153),
(148980, 'esES', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax asoló nuestras tierras y amenazaba con borrarnos de la existencia, fue ella quien lo detuvo, dando su vida para salvar las nuestras.\n\nAl contrario que los infieles, aún sentimos su presencia, y creemos que algún día nos será devuelta.', '', 28153),
(148979, 'esES', '', 'Requiero tu presencia inmediata en Orgrimmar para una misión de la máxima urgencia. No me hagas esperar.', 28153),
(148978, 'esES', '', 'Nuestro éxito en este conflicto puede depender de tus habilidades.', 28153),
(148977, 'esES', 'Los infieles son una fuerza de sethrak militantes, comandados por el emperador Korthek.\n\nHace mucho tiempo vivíamos todos unidos, como Sethraliss habría querido.\n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras.\n\nNo se detendrán hasta haber conquistado el mundo.', '', 28153),
(148976, 'esES', '', 'Adalid, la Horda está en guerra abierta con la Alianza.', 28153),
(148975, 'esES', 'La isla está expulsando una gran cantidad de azerita. Debería haber un buen montón cerca de aquí.', '', 28153),
(148974, 'esES', 'El detector de azerita está conectado. Ya deberíamos poder ver la isla entera.', '', 28153),
(148973, 'esES', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax asoló nuestras tierras y amenazaba con borrarnos de la existencia, fue ella quien lo detuvo, dando su vida para salvar las nuestras.\n\nAl contrario que los infieles, aún sentimos su presencia, y creemos que algún día nos será devuelta.', '', 28153),
(148972, 'esES', 'Se hace llamar emperador Korthek, pero mucho tiempo atrás fue uno de los guardianes a los que se encomendó proteger la tumba.\n\nSu ansia de guerra va en contra de todo lo que nuestra loa representa y, aun así, él la denuncia y desafía levantando un ejército con planes para conquistar todo Zuldazar.', '', 28153),
(148971, 'esES', 'Nunca olvidaremos lo que nuestra loa hizo por nosotros.', 'Nunca olvidaremos lo que nuestra loa hizo por nosotros.', 28153),
(148970, 'esES', '', 'Graciah, adalid. Mih auxiliareh ansían examinar loh documentoh. Ehpero que consigan dehcifrar algo útil contra el Dioh de la Sangre.', 28153),
(148969, 'esES', '', 'Aquí aún podemoh encontrar información que sirva pa contener o dehtruir a G\'huun. Buhca reliquiah y documentoh que puedan sernoh útileh.', 28153),
(148968, 'esES', 'Nuestra fe nos mantiene fuertes.', 'Nuestra fe nos mantiene fuertes.', 28153),
(148966, 'esES', 'Defenderemos el templo cueste lo que cueste.', 'Defenderemos el templo cueste lo que cueste.', 28153),
(148965, 'esES', 'No abandonaremos el templo.', 'No abandonaremos el templo.', 28153),
(148962, 'esES', 'Una nave entra en la mazmorra. Pike expresa una gran preocupación sobre el motivo de que una nave con aldeanos entre en el santuario de su orden.', 'Una nave entra en la mazmorra. Pike expresa una gran preocupación sobre el motivo de que una nave con aldeanos entre en el santuario de su orden.', 28153),
(148959, 'esES', '¿Qué pasa?', '¿Qué pasa?', 28153),
(148958, 'esES', 'Puedo sentirlo con fuerza aquí. Algo oscuro se agita.', '', 28153),
(148955, 'esES', 'Me pregunto en qué trabajaba aquí papá...', '', 28153),
(148954, 'esES', 'Tenemoh que salir de aquí. Sé cómo hacer pa burlar a todoh esoh guardiah.\n\nAvísame cuando ehtéh $glihto:lihta;.', '', 28153),
(148953, 'esES', '¡Paso!', '', 28153),
(148952, 'esES', '¡A la derecha! ¡Creo que he visto una salida!', '', 28153),
(148946, 'esES', '¡Bien! Con ehtoh materialeh tendremoh buenoh remateh pa lah flechah y forro pa lah armadurah.', '', 28153),
(148945, 'esES', 'Nazmir eh letal, pero hay muchoh recursoh si sabeh dónde buhcarloh. Recoge lo que necesitamoh de la flora y la fauna de la cohta pa reabahtecer a lah tropah.', '', 28153),
(148944, 'esES', '¡¿Qué hacemos, $p?!', '', 28153),
(148943, 'esES', '', '¡Jinx!', 28153),
(148942, 'esES', '', '¡Deberías informar a Theock! Le gustará saber que la mina está bajo control.', 28153),
(148941, 'esES', '', '¡Lo conseguimos!', 28153),
(148940, 'esES', '', '¿Morir yo... tan lejoh... de... G\'huun...?', 28153),
(148939, 'esES', '', '¡SANGRE PARA G\'HUUN!', 28153),
(148938, 'esES', '¡Nos vemos en el laboratorio!', '¡Nos vemos en el laboratorio!', 28153),
(148936, 'esES', 'El templo está ahí delante.', '', 28153),
(148935, 'esES', 'Haremos lo que haga falta para detenerlo.', '', 28153),
(148934, 'esES', 'Él los dirige en su lucha, buscando las restantes llaves que le permitan romper la barrera en torno a Atul\'Aman y usar lo que hay dentro para conquistar todo Zuldazar.', '', 28153),
(148933, 'esES', 'Desde la traición de Korthek, los infieles han asolado esta tierra con la guerra.', '', 28153),
(148932, 'esES', 'Tiempo atrás, vivíamos unidos, tal como hubiera querido nuestra loa.', '', 28153),
(148931, 'esES', 'Nuestro templo es el último bastión contra los infieles.', '', 28153),
(148930, 'esES', '¡Guerreros de la Horda, atended la llamada a las armas! Dad muerte rápida al enemigo.', '', 28153),
(148929, 'esES', 'Creo que buscas un tortoliano, ¿no?', 'Creo que buscas un tortoliano, ¿no?', 28153),
(148928, 'esES', '¡Comprad tortolianos! Mantenedlos vivos o usad sus caparazones para almacenar cosas.', '¡Comprad tortolianos! Mantenedlos vivos o usad sus caparazones para almacenar cosas.', 28153),
(148927, 'esES', '¿Alguien da más? ¡Tortolianos recién capturados en su peregrinaje de Nazmir!', '¿Alguien da más? ¡Tortolianos recién capturados en su peregrinaje de Nazmir!', 28153),
(148925, 'esES', '¡No tendréis otra oportunidad de conseguir vulperas como estos!', '¡No tendréis otra oportunidad de conseguir vulperas como estos!', 28153),
(148924, 'esES', '¡Conseguid aquí vuestro propio vulpera, energía a raudales!', '¡Conseguid aquí vuestro propio vulpera, energía a raudales!', 28153),
(148923, 'esES', '¿Alguien da más por los vulperas? ¡Os servirán bien!', '¿Alguien da más por los vulperas? ¡Os servirán bien!', 28153),
(148922, 'esES', '¡Hay que detener a los infieles!', '¡Hay que detener a los infieles!', 28153),
(148921, 'esES', 'Debería ser capaz de ponerme a salvo solo.', 'Debería ser capaz de ponerme a salvo sola.', 28153),
(148920, 'esES', 'Gracias. Desde aquí puedo seguir yo.', 'Gracias. Desde aquí puedo seguir yo.', 28153),
(148919, 'esES', 'Venga a los que no nos pudimos salvar.', 'Venga a los que no nos pudimos salvar.', 28153),
(148918, 'esES', 'No tienes ni idea de lo que nos han hecho pasar...', 'No tienes ni idea de lo que nos han hecho pasar...', 28153),
(148917, 'esES', 'Ten cuidado. Vas a meterte directamente en su nido.', '', 28153),
(148916, 'esES', 'Reúnete allí con nosotros cuando tengas la piedra de Korthek.', '', 28153),
(148910, 'esES', '¡¿Cómo te atreveh a poner un pie en ehtoh terrenoh de caza?!', '¡¿Cómo te atreveh a poner un pie en ehtoh terrenoh de caza?!', 28153),
(148909, 'esES', '¡Pagaráh por eso!', '¡Pagaráh por eso!', 28153),
(148908, 'esES', '¡Aquí no hay cabida pa la Alianza!', '¡Aquí no hay cabida pa la Alianza!', 28153),
(148907, 'esES', '¡Ehta reserva de caza pertenece a loh Zandalari!', '¡Ehta reserva de caza pertenece a loh Zandalari!', 28153),
(148906, 'esES', 'Perded máh el tiempo, no pasa nada.', '', 28153),
(148905, 'esES', '', 'Fuera, si creemos al trol.', 28153),
(148904, 'esES', '¿Adónde lleva ehto?', '', 28153),
(148903, 'esES', '', 'Qué olor tan... desagradable.', 28153),
(148902, 'esES', '', 'Leh enseñaremoh a esoh trolh de sangre que ya no leh tenemoh miedo. Buen trabajo.', 28153),
(148901, 'esES', '', 'Que alguien... los detenga.', 28153),
(148900, 'esES', '', 'Nadie sorprende a la Séptima Legión. ¡Morid, ratas de la Horda!', 28153),
(148899, 'esES', '', 'Mih ehploradoreh informan de que hay tropah de loh trolh de sangre cerca de aquí. ¡Enséñaleh a no oponerse a loh Zandalari!', 28153),
(148898, 'esES', '', '¡De aquí no pasaréis!', 28153),
(148897, 'esES', '', '¡Es un campo antimagia! ¡No puedo lanzar hechizos!', 28153),
(148896, 'esES', 'Qué vudú tan terrible. ¿Thalyssra?', '', 28153),
(148895, 'esES', '', 'Necesito un momento. Llevo horas intentando salir de esta jaula.', 28153),
(148894, 'esES', '', '¡Jamásss dessstruirásss mi maldición!', 28153),
(148893, 'esES', 'Todas estas bestias pueden servir algún día a la Horda. No podemos permitir que ocurra.', '', 28153),
(148892, 'esES', 'Puede que pronto vuelva a haber las mismas bestias de antes, pero la Horda tardará mucho más en reemplazar a sus cuidabestias. ¡Bien hecho!', '', 28153),
(148891, 'esES', 'La reserva Zandalari está repleta de bestias aptas para la guerra, pero solo si se adiestran bien. Envenénalas para atraer a los cuidabestias. Ellos son el auténtico objetivo.', '', 28153),
(148890, 'esES', '', 'Máh te vale ehtar en lo cierto, Zul.', 28153),
(148889, 'esES', 'Eso sería un error. Eh por el otro lado.', '', 28153),
(148888, 'esES', '¡Por aquí!', '', 28153),
(148887, 'esES', '', '¿Cómo salimoh de aquí?', 28153),
(148886, 'esES', '', 'Graciah a ti, ehtamoh un paso máh cerca de acabar con la amenaza de loh trolh de sangre.', 28153),
(148885, 'esES', '', 'Siento un mojo ohcuro cerca de aquí. ¡Seguro que son loh trolh de sangre! Encuéntraloh y acaba con lo que ehtén haciendo.', 28153),
(148884, 'esES', '', '¡Debemos avanzar!', 28153),
(148883, 'esES', '', '¡Cogedlos!', 28153),
(148879, 'esES', 'Las nubes se desvanecen... La tormenta amaina...', '', 28153),
(148878, 'esES', '¡Soy el heraldo de las tormentas!', '', 28153),
(148877, 'esES', 'Lah presentacioneh tendrán que ehperar.', '', 28153),
(148876, 'esES', '', 'Venimos de parte de la Horda. Soy Thalyssra, y este es Rokhan.', 28153),
(148875, 'esES', '', 'Hum... Graciah. Mi profeta dice que soih aliadoh.', 28153),
(148874, 'esES', '¡Ja, ja, ja! No, no, no, colega. Te conozco. Ereh la serpiente que...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'esES', '¡Ah! Llega la caballería. Juhto como predije, Princesa.', '', 28153),
(148871, 'esES', 'Vamoh. Por aquí.', '', 28153),
(148870, 'esES', 'Necesito descansar un momento.', '', 28153),
(148868, 'esES', '¿Korthek se cree que puede esconderse de nosotros detrás de un muro? Menudo idiota.', '', 28153),
(148867, 'esES', 'Cíñete al plan. Ya te alcanzaré.', '', 28153),
(148858, 'esES', '', 'Entiendo. ¿Esa es tu decisión?', 28153),
(148857, 'esES', 'Lo es. Lok\'tar.', '', 28153),
(148856, 'esES', 'Así que no vieneh con nosotroh...', '', 28153),
(148855, 'esES', 'Ambos sabemos que no estáis aquí por mí. Los que buscáis están al final del pasillo.', '', 28153),
(148854, 'esES', 'Según estos informes, sospecho que cuando más vulnerable es el Emperador es mientras visita el mercado. Y queda cerca.', '', 28153),
(148853, 'esES', 'Creo que eh mejor que tomeh ehto.', '', 28153),
(148852, 'esES', '', 'Nosotros desviaremos su atención. Ten cuidado.', 28153),
(148851, 'esES', 'Me adelantaré y buhcaré a loh prisioneroh. Cubridme.', '', 28153),
(148850, 'esES', 'La Séptima Legión ehtá aquí. No sé a quién tienen encerrado, pero loh humanoh no quieren correr riehgoh.', '', 28153),
(148849, 'esES', 'Nos reuniremos allí.', '', 28153),
(148848, 'esES', 'Esa es nuestra vía de escape. Tras rescatar a los prisioneros, dirigíos a aquel barco.', '', 28153),
(148847, 'esES', 'Os he proporcionado algo que os otorgará una muerte rápida; si os atrapan, usadlo.', '', 28153),
(148846, 'esES', 'La Jefa de Guerra y la Horda negarán tener conocimiento de esta misión si os capturan.', '', 28153),
(148845, 'esES', 'Nuestros exploradores han descubierto una entrada secreta. El tauren y yo os cubriremos.', '', 28153),
(148844, 'esES', 'Thalyssra, Rokhan y tú os infiltraréis en las Mazmorras y liberaréis a los prisioneros.', '', 28153),
(148843, 'esES', 'Escuchad atentamente, una vez en Ventormenta, perderemos el contacto.', '', 28153),
(148842, 'esES', '', 'Vamos a asegurarnos de que los jabaespines no puedan volver a atacar así.', 28153),
(148841, 'esES', 'Tu fin... se acerca...', 'Tu fin... se acerca...', 28153),
(148840, 'esES', 'Cómo... es posible...', 'Cómo... es posible...', 28153),
(148839, 'esES', 'Te enfrentarás... al ojo... de la tormenta...', 'Te enfrentarás... al ojo... de la tormenta...', 28153),
(148838, 'esES', 'Caerás...', 'Caerás...', 28153),
(148837, 'esES', 'Mi alma... se hunde... en el mar...', 'Mi alma... se hunde... en el mar...', 28153),
(148836, 'esES', 'Viajo... al fondo... de las mareas...', 'Viajo... al fondo... de las mareas...', 28153),
(148835, 'esES', 'Regreso... a las profundidades...', 'Regreso... a las profundidades...', 28153),
(148834, 'esES', 'Hasta la marea... sucumbe...', 'Hasta la marea... sucumbe...', 28153),
(148833, 'esES', '¡Su poder fluye por mis venas!', '¡Su poder fluye por mis venas!', 28153),
(148832, 'esES', '¡Acepta tu fin!', '¡Acepta tu fin!', 28153),
(148831, 'esES', '¡Los tentáculos del destino te atraparán!', '¡Los tentáculos del destino te atraparán!', 28153),
(148830, 'esES', '¡Serás un caparazón sin vida!', '¡Serás un caparazón sin vida!', 28153),
(148829, 'esES', '¡Ahógate mientras se apaga tu luz!', '¡Ahógate mientras se apaga tu luz!', 28153),
(148828, 'esES', '¡Nadie puede detener la marea eterna!', '¡Nadie puede detener la marea eterna!', 28153),
(148827, 'esES', '¡Las profundidades te llaman!', '¡Las profundidades te llaman!', 28153),
(148826, 'esES', '¡El mar te arrastrará!', '¡El mar te arrastrará!', 28153),
(148825, 'esES', 'Está tan... oscuro...', 'Está tan... oscuro...', 28153),
(148824, 'esES', 'Que las mareas... me lleven...', 'Que las mareas... me lleven...', 28153),
(148823, 'esES', 'Al menos muero... por Kul Tiras...', 'Al menos muero... por Kul Tiras...', 28153),
(148822, 'esES', '¿Cómo... has...?', '¿Cómo... has...?', 28153),
(148821, 'esES', 'Así no...', 'Así no...', 28153),
(148820, 'esES', '¡Cobraré una recompensa por tu pellejo!', '¡Cobraré una recompensa por tu pellejo!', 28153),
(148819, 'esES', '¡Voy a fregar la cubierta con tu cara!', '¡Voy a fregar la cubierta con tu cara!', 28153),
(148818, 'esES', '¡Ven a por mí!', '¡Ven a por mí!', 28153),
(148817, 'esES', '¡Esta historia triunfará cuando la cuente en el bar!', '¡Esta historia triunfará cuando la cuente en el bar!', 28153),
(148816, 'esES', '¡Te arrepentirás de esto!', '¡Te arrepentirás de esto!', 28153),
(148815, 'esES', 'El barquero... llama...', 'El barquero... llama...', 28153),
(148814, 'esES', 'Que las mareas... me lleven...', 'Que las mareas... me lleven...', 28153),
(148813, 'esES', 'Al menos muero... por Kul Tiras...', 'Al menos muero... por Kul Tiras...', 28153),
(148812, 'esES', 'El mar... se cobrará... su deuda...', 'El mar... se cobrará... su deuda...', 28153),
(148811, 'esES', 'Yaceré bajo cinco brazas de agua...', 'Yaceré bajo cinco brazas de agua...', 28153),
(148810, 'esES', '¡Otro trofeo para el manto!', '¡Otro trofeo para el manto!', 28153),
(148809, 'esES', '', 'Aquí podemos hablar con libertad. No se puede decir lo mismo de Orgrimmar.', 28153),
