(145611, 'esES', '', '¡Por la Horda!', 28153),
(145610, 'esES', '', 'Tengo heridah graveh.', 28153),
(145609, 'esES', '¡Eh la rehpuehta correcta! Solo queda una pregunta.\n\n¿Ehtáh $glihto:lihta;?', '', 28153),
(145608, 'esES', 'Mi sombra.', 'Mi sombra.', 28153),
