(145281, 'esES', 'Un pandaren.', 'Un pandaren.', 28153),
(145280, 'esES', 'Un incendio.', 'Un incendio.', 28153),
(145279, 'esES', 'Rehponde a ehte acertijo.\n\nSi bebo, muero. Si devoro, vivo. ¿Qué soy?', '', 28153),
(145278, 'esES', '¡Listo!', '¡Lista!', 28153),
(145277, 'esES', '¡Correcto!\n\n¿Ehtáh $glihto:lihta; pa otro?', '', 28153),
(145276, 'esES', 'La oscuridad se ha tragado a Uuna.', 'La oscuridad se ha tragado a Uuna.', 28153),
(145275, 'esES', '', '¡Aaaaah! ¡No! ¡Ayuda!', 28153),
(145273, 'esES', '', 'Oyes una voz que retumba y te pone en tensión.', 28153),
(145272, 'esES', '', '¡Te lo suplico!', 28153),
(145271, 'esES', '', 'Te pido misericordia.', 28153),
(145270, 'esES', '', '¡Pido clemencia!', 28153),
(145269, 'esES', '', 'No está nada mal.', 28153),
(145268, 'esES', '', 'Impresionante.', 28153),
(145267, 'esES', '', 'Muy bien.', 28153),
(145266, 'esES', '', 'Pero... todavía no.', 28153),
(145265, 'esES', '', 'Sé que algún día tendré que volver con papá y mamá.', 28153),
(145264, 'esES', '', 'Que la forja ilumine tu camino.', 28153),
(145263, 'esES', '', 'Me has enseñado tantas cosas bonitas... ¡Jamás había conocido a nadie como tú!', 28153),
(145262, 'esES', '', 'Aire.', 28153),
(145261, 'esES', '', '¡PAGARÁH por lo que hah hecho!', 28153),
(145260, 'esES', '', '¡Nos vemos!', 28153),
(145259, 'esES', '', 'Adiós.', 28153),
(145258, 'esES', '', '¡Muchísimas gracias por haberme traído aquí!', 28153),
(145257, 'esES', '', '¿No murieron todos en Argus?', 28153),
(145256, 'esES', '', '¡Mi gente está aquí! ¡Sobrevivieron!', 28153),
(145255, 'esES', '', 'Qué... Qué bonito...', 28153),
(145254, 'esES', '', 'Eso es una tontería.', 28153),
(145253, 'esES', '', 'Pero se mueve como si fuera agua... ¿Es un lago brillante?', 28153),
(145252, 'esES', '', 'Métete en tus asuntos.', 28153),
(145251, 'esES', 'Volveré a intentarlo.', 'Volveré a intentarlo.', 28153),
(145250, 'esES', '¡Incorrecto!\n\n¿Quiereh volver a intentarlo?', '', 28153),
(145249, 'esES', 'Una loa.', 'Una loa.', 28153),
(145248, 'esES', 'Una vela.', 'Una vela.', 28153),
(145247, 'esES', '', 'Mira ahí abajo. ¡Cómo brilla!', 28153),
(145246, 'esES', '', '¿Dónde estamos? ¿Por qué hay tanto humo?', 28153),
(145245, 'esES', '', 'Así que ten cuidado, ¿vale?', 28153),
(145244, 'esES', 'Una encina.', 'Una encina.', 28153),
(145243, 'esES', '', '¡No te caigas! A mí no me pasaría nada, pero tú harías... ¡PATAPLAF!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'esES', '', 'Saludos.', 28153),
(145241, 'esES', '', '¡No sabía que las montañas pudieran ser así de altas!', 28153),
(145240, 'esES', '', '¡Desde aquí lo veo todo!', 28153),
(145239, 'esES', '', 'Me alegro de verte.', 28153),
(145238, 'esES', '', 'Hola.', 28153),
(145237, 'esES', '', '¡Pío, pío, pío, pío, pío!', 28153),
(145236, 'esES', '', 'No.', 28153),
(145235, 'esES', '', 'Nop.', 28153),
(145234, 'esES', '', 'Ni de broma.', 28153),
(145233, 'esES', '', 'Eso es.', 28153),
(145232, 'esES', '', 'Mmm, mmm.', 28153),
(145231, 'esES', '', 'Sí.', 28153),
(145230, 'esES', '', 'Estoy muy agradecida.', 28153),
(145229, 'esES', '', 'Te doy las gracias.', 28153),
(145228, 'esES', 'Una gnoma.', 'Una gnoma.', 28153),
(145227, 'esES', '', 'Te debo una.', 28153),
(145226, 'esES', '', '¡Por el Yunquenegro!', 28153),
(145225, 'esES', '', 'Al menos... ¡DIEZ!', 28153),
(145224, 'esES', '', '¿No puedes hacerlo mejor?', 28153),
(145222, 'esES', '', '¡Te voy a machacar!', 28153),
(145221, 'esES', '', 'Me pregunto cuántos pájaros viven en ese árbol. ¡Seguro que un montón!', 28153),
(145220, 'esES', 'Rehponde a ehte acertijo.\n\nSoy alta cuando soy joven y baja cuando soy vieja. ¿Qué soy?', '', 28153),
(145219, 'esES', '', 'Ha sido un placer.', 28153),
(145218, 'esES', '', '¡Mira, mira! ¡Estamos debajo de un árbol gigante!', 28153),
(145217, 'esES', '', 'Me alegra ser de ayuda.', 28153),
(145216, 'esES', '', 'De nada.', 28153),
(145215, 'esES', 'Vamos a jugar.', 'Vamos a jugar.', 28153),
(145214, 'esES', '¿Ehtáh $glihto:lihta; pa poner a prueba tu mente?', '', 28153),
(145213, 'esES', '', '¿Me puedo quedar uno?', 28153),
(145212, 'esES', '', 'Pero para pájaros-lagarto.', 28153),
(145211, 'esES', '', '¡Vaya torre más grande! ¡Es como una pajarera gigante!', 28153),
(145210, 'esES', '', 'Eh, ¿qué son esas cosas voladoras? ¡Son muy bonitas!', 28153),
(145209, 'esES', '', 'Ahora que lo pienso... ¿Vives en algún sitio?', 28153),
(145208, 'esES', '', '¿Vives aquí?', 28153),
(145207, 'esES', '', '¿Cómo lo hace?', 28153),
(145206, 'esES', '', 'Hala... ¡Una ciudad voladora! ¡¿Es de verdad?!', 28153),
(145205, 'esES', '', '¿Quieres jugar a las princesas conmigo?', 28153),
(145204, 'esES', '', '¿Sabes quién vive ahí? ¡Seguro que es una princesa!', 28153),
(145203, 'esES', '', '¡Hala! ¡Esa tiene que ser la casa más bonita del mundo entero!', 28153),
(145202, 'esES', '', '¡¡¡Puaaaaaj!!!', 28153),
(145201, 'esES', '', 'A lo mejor era a los bichos. ¡Seguro que sí! ¡Puaj! ¡Odio a los bichos!', 28153),
(145200, 'esES', '', '¿A quién crees que querían cortarle el paso?', 28153),
(145199, 'esES', '', '¡Hala! ¡Nunca había visto una muralla así de grande!', 28153),
(145197, 'esES', '', 'Uuna te da un abrazo.', 28153),
(145196, 'esES', '¡Tú no llevar bota!', '', 28153),
(145195, 'esES', '', 'Vale, ¡vámonos! ¡Tenemos que visitar un montón de sitios!', 28153),
(145194, 'esES', '', 'Dile a papá y a mamá que los echo de menos... ¡Y que pronto los veré!', 28153),
(145193, 'esES', '', '¡La Luz dice que me puedo quedar! ¡Yupi!', 28153),
(145192, 'esES', '', '¿Me puedo quedar contigo? Solo durante un tiempo...', 28153),
(145191, 'esES', '', 'Hay tantas cosas que nunca he podido hacer. Tantos lugares que nunca he visto...', 28153),
(145190, 'esES', '', 'Un momento...', 28153),
(145189, 'esES', '', '¡Mamá! ¡Papá! ¡Me están esperando!', 28153),
(145188, 'esES', '', 'La Luz... Me dice que la siga...', 28153),
(145187, 'esES', '', '¿Qué... Qué está pasando?', 28153),
(145186, 'esES', '', 'Ah, ¡lo hemos conseguido! ¡Hemos ganado!', 28153),
(145185, 'esES', '', '¡La oscuridad se ha ido! ¡Veo!', 28153),
(145184, 'esES', '', '¡Pagaráh por lo que hah hecho!', 28153),
(145183, 'esES', 'Maldición. ¡$gMaldito:Maldita; seas! No había terminado...', '', 28153),
(145182, 'esES', '¡Tu muerte complacerá a la Reina alma en pena!', '', 28153),
(145181, 'esES', '¡Escoria de la Alianza! ¡Le llevaré tu cabeza a la Dama Oscura!', '', 28153),
(145180, 'esES', '', '¡Te voy a cortar el cuello, $n!', 28153),
(145179, 'esES', 'El sonido de unos cascos al galope resuena en la distancia. Algo se acerca.', 'El sonido de unos cascos al galope resuena en la distancia. Algo se acerca.', 28153),
(145178, 'esES', '', 'Te atreveh a interrumpirme. ¡Pagaráh por ello con tu vida, $n!', 28153),
(145177, 'esES', '', 'Te ehtado vigilando, $n.', 28153),
(145176, 'esES', '¡Te voy a freír, igual que a tu rey perro! ¡Por la Horda!', '', 28153),
(145175, 'esES', 'Hueles el ozono a medida que el aire empieza a chisporrotear.', 'Hueles el ozono a medida que el aire empieza a chisporrotear.', 28153),
(145173, 'esES', '', 'Tienes mucha osadía, pero yo soy máh que mi magia.', 28153),
(145172, 'esES', 'Estoy listo. Que empiece el ritual.', 'Estoy lista. Que empiece el ritual.', 28153),
(145171, 'esES', 'Oigo los gritos del mundo bajo mis pies. ¡Azeroth tiembla de dolor! Debemos encontrar la forma de aliviar su sufrimiento...', '', 28153),
(145170, 'esES', '', 'No moriré tan fácilmente, $n. ¡Sufriráh mi cólera!', 28153),
(145169, 'esES', '', 'Por fin te encuentro, $n.', 28153),
(145168, 'esES', '¡Te machacaré el cráneo!', '', 28153),
(145167, 'esES', '¡Te arrancaré la carne de los huesos!', '', 28153),
(145166, 'esES', 'Acecharé tu tumba toda la eternidad.', '', 28153),
(145165, 'esES', 'Me han quitado toda esperanza.', '', 28153),
(145164, 'esES', 'Maldición. Otra vez no.', '', 28153),
(145163, 'esES', 'Sufrirás por lo que me has hecho.', '', 28153),
(145162, 'esES', 'Absorberé tu fuerza vital.', '', 28153),
(145161, 'esES', 'Me deleito con el sonido del choque del metal y el aroma del miedo.', '', 28153),
(145160, 'esES', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Estás bajo la |cFFF00000|Hspell:260953|h[Mirada de hierro]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Estás |cFFF00000|Hspell:257459|h[Enganchado]|h|r!', 28153),
(145159, 'esES', '', '¡YA NO TENDRÉ MIEDO NUNCA MÁS!', 28153),
(145158, 'esES', '', '¡Mi luz es superfuerte!', 28153),
(145157, 'esES', 'Quiero ir a casa.', '', 28153),
(145156, 'esES', '', 'Y mientras mi luz esté conmigo, ¡la oscuridad no podrá ganar!', 28153),
(145155, 'esES', '', 'Mi mamá me dijo que la Luz siempre me encontraría. Hablaba de ti. ¡Tú eres mi luz!', 28153),
(145154, 'esES', '', '¡Estás aquí! ¡No me has abandonado!', 28153),
(145153, 'esES', 'No... No...', 'No... No...', 28153),
(145152, 'esES', 'Dama Oscura... He fallado...', 'Dama Oscura... He fallado...', 28153),
(145151, 'esES', 'Ehtoy en la parte máh baja del tótem, colega.', '', 28153),
(145150, 'esES', 'Por fin...', 'Por fin...', 28153),
(145149, 'esES', 'No... Otra vez no...', 'No... Otra vez no...', 28153),
(145148, 'esES', '¡Por la Dama Oscura!', '¡Por la Dama Oscura!', 28153),
(145147, 'esES', '¡Abandona toda esperanza!', '¡Abandona toda esperanza!', 28153),
(145146, 'esES', '¡Únete a los muertos!', '¡Únete a los muertos!', 28153),
(145145, 'esES', '¡Devoraré tus huesos!', '¡Devoraré tus huesos!', 28153),
(145144, 'esES', '¡Muerte a los vivos!', '¡Muerte a los vivos!', 28153),
(145143, 'esES', '¡Por Sylvanas!', '¡Por Sylvanas!', 28153),
(145142, 'esES', '', 'Uuna se abraza a sí misma y empieza a llorar.', 28153),
(145141, 'esES', '', '¡No... no puedo hacerlo! ¡Solo quiero irme a casa!', 28153),
(145140, 'esES', '', '¿Todavía estás ahí? ¡Tengo miedo!', 28153),
(145139, 'esES', '¡El mal Juju te alcanzará!', '', 28153),
(145137, 'esES', 'Tuh antepasadoh quieren que te unah a elloh.', '', 28153),
(145136, 'esES', 'Que acabeh tan $gfeo:fea; como mi hermano.', '', 28153),
(145135, 'esES', '¿Qué tipo de vudú haceh, colega?', '', 28153),
(145133, 'esES', 'Que loh huesoh caigan donde deben.', '', 28153),
(145130, 'esES', '¡Las espinas van a por vuestras almas!', '', 28153),
(145129, 'esES', 'A continuación, se volvió y desapareció en el bosque. Desde entonces, los valientes y los fieles han encontrado un refugio con el venado blanco del bosque.', 'A continuación, se volvió y desapareció en el bosque. Desde entonces, los valientes y los fieles han encontrado un refugio con el venado blanco del bosque.', 28153),
(145128, 'esES', '\"Soy Athair, el corazón de este bosque. Mientras exista, os protegeré a ti y a los tuyos si acuden a mí\", dijo el venado.', '\"Soy Athair, el corazón de este bosque. Mientras exista, os protegeré a ti y a los tuyos si acuden a mí\", dijo el venado.', 28153),
(145127, 'esES', '\"¡Por la Luz! ¡Pero si puedes hablar!\", exclamó Arom.', '\"¡Por la Luz! ¡Pero si puedes hablar!\", exclamó Arom.', 28153),
(145126, 'esES', '', '<Applause sounds>', 28153),
(145125, 'esES', '', '<Yawning sound>', 28153),
(145124, 'esES', '', '<Short cheer--Wooooo!>', 28153),
(145123, 'esES', '', '<Slightly longer cheer--Woohoo!>', 28153),
(145122, 'esES', '¡El fuego lo destruirá!', '', 28153),
(145121, 'esES', '', '<Chicken sounds>', 28153),
(145120, 'esES', '', '<Crying sounds>', 28153),
(145119, 'esES', '\"No hay de qué. Estaba correspondiendo a la bondad que mostraste conmigo\".', '\"No hay de qué. Estaba correspondiendo a la bondad que mostraste conmigo\".', 28153),
(145118, 'esES', '', '<Crying sounds, variant>', 28153),
(145117, 'esES', '', '<Crying sounds, variant.>', 28153),
(145116, 'esES', '', '<Kiss sound>', 28153),
(145115, 'esES', '\"Gracias, amigo mío\", dijo Arom al venado.', '\"Gracias, amigo mío\", dijo Arom al venado.', 28153),
(145114, 'esES', '', '<Laughing sounds>', 28153),
(145113, 'esES', '', '<Laughing>', 28153),
(145112, 'esES', '', '<Making a raspberry sound--Pfffthblth!>', 28153),
(145111, 'esES', 'Juntos, Arom y el venado blanco combatieron a los guerreros y los vencieron.', 'Juntos, Arom y el venado blanco combatieron a los guerreros y los vencieron.', 28153),
(145110, 'esES', '', '<Roar of dominance>', 28153),
(145109, 'esES', '', '<Variant roar>', 28153),
(145108, 'esES', '', '<Sighing sound>', 28153),
(145107, 'esES', '', '<Train noises--chugga chugga choo choo!>', 28153),
(145106, 'esES', '¡El venado blanco regresó y aplastó a algunos de los Drust!', '¡El venado blanco regresó y aplastó a algunos de los Drust!', 28153),
(145105, 'esES', '¡Un potente bramido surgió de la espesura!', '¡Un potente bramido surgió de la espesura!', 28153),
(145104, 'esES', 'Decidido a acabar con tantos como pudiera, se mantuvo firme.', 'Decidido a acabar con tantos como pudiera, se mantuvo firme.', 28153),
(145103, 'esES', '¡Lord Arom se enfrentaba a diez guerreros! ¡Luchó con valor y astucia, pero lo superaban en número y lo rodearon!', '¡Lord Arom se enfrentaba a diez guerreros! ¡Luchó con valor y astucia, pero lo superaban en número y lo rodearon!', 28153),
(145102, 'esES', 'Curioso...', 'Curioso...', 28153),
(145101, 'esES', '¡Por la noche, los Drust lo atacaron!', '¡Por la noche, los Drust lo atacaron!', 28153),
(145100, 'esES', 'El venado se alejó brincando por el bosque y Arom acampó allí.', 'El venado se alejó brincando por el bosque y Arom acampó allí.', 28153),
(145099, 'esES', '\"Cualquiera que pueda repeler a tantos Drust me vendrá muy bien en mi bosque\", pensó. Así que lord Arom sanó las heridas del venado.', '\"Cualquiera que pueda repeler a tantos Drust me vendrá muy bien en mi bosque\", pensó. Así que lord Arom sanó las heridas del venado.', 28153),
(145098, 'esES', '¡Cuidado con las espinas!', '', 28153),
(145097, 'esES', 'La gente de lord Arom necesitaba comida y el enorme ciervo podría haber alimentado a muchos, pero decidió no atacar.', 'La gente de lord Arom necesitaba comida y el enorme ciervo podría haber alimentado a muchos, pero decidió no atacar.', 28153),
(145096, 'esES', 'Los Drust habían atacado al venado y él había matado a muchos, pero lograron herirlo.', 'Los Drust habían atacado al venado y él había matado a muchos, pero lograron herirlo.', 28153),
(145095, 'esES', 'Un día, mientras lord Arom cazaba en el bosque para comer, se encontró con un enorme venado blanco.', 'Un día, mientras lord Arom cazaba en el bosque para comer, se encontró con un enorme venado blanco.', 28153),
(145094, 'esES', '¡Sí! ¡Liberadnos!', '', 28153),
(145093, 'esES', 'Nos habéis... liberado...', '', 28153),
(145092, 'esES', 'Libres... Por fin...', '', 28153),
(145091, 'esES', 'Gracias...', '', 28153),
(145090, 'esES', 'Otra alma atormentada.', '', 28153),
(145089, 'esES', 'No hay escapatoria.', '', 28153),
(145088, 'esES', '', '¡Acabad con este objetivo!', 28153),
(145087, 'esES', '', '¡Acabad con mi objetivo!', 28153),
(145086, 'esES', '', '¡Centraos en el enemigo!', 28153),
(145085, 'esES', '¡Huid! ¡No hay esperanza!', '', 28153),
(145084, 'esES', 'Juntos... eternamente.', '', 28153),
(145083, 'esES', '', '¡A las armas!', 28153),
(145082, 'esES', '', '¡Por la reina!', 28153),
(145081, 'esES', '', '¡Por el poder de la montaña!', 28153),
(145080, 'esES', '¡Proteged vuestras almas!', '', 28153),
(145079, 'esES', '', '¡A por ellos!', 28153),
(145078, 'esES', '', '¡Que no den un paso más!', 28153),
(145077, 'esES', '', '¡Hay que retroceder!', 28153),
(145076, 'esES', '', '¡Retirada!', 28153),
(145075, 'esES', '', '¡Fuera de aquí!', 28153),
(145074, 'esES', '', 'Por aquí.', 28153),
(145073, 'esES', '', 'Yo iré primero.', 28153),
(145072, 'esES', '', 'Sígueme.', 28153),
(145071, 'esES', '', '¡Por la Alianza!', 28153),
(145070, 'esES', '', '¡Necesito ayuda!', 28153),
(145069, 'esES', '', '¡Ayúdame!', 28153),
(145068, 'esES', '', '¡El peligro anda cerca!', 28153),
(145067, 'esES', '', '¡Fuego a discreción!', 28153),
(145066, 'esES', '', '¡Fuego!', 28153),
(145065, 'esES', '', 'Quédate aquí.', 28153),
(145064, 'esES', '', 'No te muevas.', 28153),
(145063, 'esES', '', '¡Tengo heridas graves!', 28153),
(145062, 'esES', '', '¡Necesito sanación!', 28153),
