(145043, 'esES', '', 'No apartes los ojos del objetivo.', 28153),
(145042, 'esES', '', 'Hacemos lo que debemos por los que amamos.', 28153),
(145041, 'esES', '', 'Apunta bien.', 28153),
(145040, 'esES', '', 'Adiós.', 28153),
(145039, 'esES', '', 'Las sombras pueden ser tus aliadas... si se controlan.', 28153),
(145038, 'esES', '', 'Saludos.', 28153),
(145037, 'esES', '', 'No podemos invitar a nadie más.', 28153),
(145036, 'esES', '', 'Todos elegimos un bando. Escoge el tuyo.', 28153),
(145035, 'esES', '', 'No puedo beber más ahora mismo.', 28153),
