(145019, 'esES', '', 'No puedo llevar más.', 28153),
(145018, 'esES', '', 'Las hermanas son complicadas. Sobre todo las no-muertas.', 28153),
(145017, 'esES', '', 'Eso está bloqueado.', 28153),
(145016, 'esES', '', 'No puedo llevar más de eso.', 28153),
