(144996, 'esES', '', 'Me hace falta más ira.', 28153),
(144995, 'esES', '', 'Demasiado lejos.', 28153),
(144994, 'esES', '', 'Pues claro que todavía le quiero. ¿Quién te ha dado vela en este entierro?', 28153),
