INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'esES', '', 'No puedo hacer eso aquí.', 28153),
(144984, 'esES', '', 'No puedo deshacerme de eso.', 28153),
(144983, 'esES', '', 'Eso está ligado a mí.', 28153),
(144982, 'esES', '', 'No puedo equipar eso.', 28153),
(144981, 'esES', '', 'No tengo el nivel suficiente para usar eso.', 28153),
(144980, 'esES', '', 'No puedo usar eso todavía.', 28153),
(144979, 'esES', '', 'Mi nivel de habilidad no me permite equipar eso.', 28153),
(144978, 'esES', '', 'Nunca podré equipar eso.', 28153),
(144977, 'esES', '', 'No puedo aprender ese hechizo.', 28153),
(144976, 'esES', '', 'No puedo despojar eso.', 28153),
(144975, 'esES', '', 'Eso no me pertenece.', 28153),
(144974, 'esES', '', 'Necesito acercarme.', 28153),
(144973, 'esES', '', 'Está demasiado lejos.', 28153),
(144972, 'esES', '', 'Está fuera de mi alcance.', 28153),
(144971, 'esES', '', 'No puedo comerciar con eso.', 28153),
(144970, 'esES', '', 'No puedo usar eso.', 28153),
(144969, 'esES', '', 'Eso no está equipado.', 28153),
(144968, 'esES', '', 'Eso debo equiparlo primero.', 28153),
(144967, 'esES', '', 'No se puede despojar todavía.', 28153),
(144966, 'esES', '', 'No tengo un objetivo.', 28153),
(144965, 'esES', '', 'Necesito un objetivo primero.', 28153),
(144964, 'esES', '', 'Necesito un objetivo.', 28153),
(144963, 'esES', '', '¡Poderes superiores y espíritus inmundos, otorgad a mis espinas tallos fecundos!', 28153),
(144962, 'esES', '', '¡Entrégame el iris, hermana!', 28153),
(144961, 'esES', '', '¡Mis espinas te harán pedazos!', 28153),
(144960, 'esES', '', '¡Cuanto más te resistas, más sangrarás!', 28153),
(144959, 'esES', '', '¡Llevas la marca negra!', 28153),
(144958, 'esES', '', 'Vuestros cráneos me servirán de adorno.', 28153),
(144956, 'esES', '', 'Mis raíces brotarán de nuevo...', 28153),
(144955, 'esES', '', 'Me encanta el sonido de los huesos al romperse.', 28153),
(144954, 'esES', 'Ehta noche comeré bien. Muchah graciah y $gbendito:bendita; seah.', 'Ehta noche comeré bien. Muchah graciah y $gbendito:bendita; seah.', 28153),
(144953, 'esES', 'Ereh muy amable con ehte pobre viejo. ¡Graciah!', 'Ereh muy amable con ehta pobre vieja. ¡Graciah!', 28153),
(144952, 'esES', 'Graciah, $gamigo:amiga;.', 'Graciah, $gamigo:amiga;.', 28153),
(144951, 'esES', '', '¡Qué huesos tan blandos!', 28153),
(144950, 'esES', '<Dar diez monedas de oro>.', '<Dar diez monedas de oro>.', 28153),
(144949, 'esES', '<Dar una moneda de oro>.', '<Dar una moneda de oro>.', 28153),
(144948, 'esES', '<Dar cinco monedas de cobre>.', '<Dar cinco monedas de cobre>.', 28153),
(144947, 'esES', '¿Tieneh una moneda de cobre, $gamigo:amiga;?', '¿Tieneh una moneda de cobre, $gamigo:amiga;?', 28153),
(144946, 'esES', '', '¡Carne podrida y gritos de dolor componen la sinfonía de vuestro adiós!', 28153),
(144945, 'esES', '', '¡Tu destrucción se acerca!', 28153),
(144944, 'esES', '', '¡Trae! ¡Es mi turno!', 28153),
(144943, 'esES', '', '... y Rezan rugió sobre loh cadávereh del ejército de loh trolh de sangre. ¡Triunfante!', 28153),
(144942, 'esES', '', 'Vuestro tormento no ha hecho más que empezar.', 28153),
(144941, 'esES', '', '¡Dulce agonía!', 28153),
(144940, 'esES', '', 'Mi cuerpo perece... Pero mi maldición... perdurará...', 28153),
(144939, 'esES', '', '¡Arrancaré gritos de vuestra carne!', 28153),
(144938, 'esES', '', 'Alma negra como la brea, destruye a todo aquel que veas.', 28153),
(144937, 'esES', '', '¡Ahora me perteneces!', 28153),
(144936, 'esES', '', '¡Baila, marioneta, baila!', 28153),
(144935, 'esES', '', '¡Dame el iris, necia! ¡Tan solo yo puedo enfocar su poder!', 28153),
(144934, 'esES', '', 'Vuestras almas son mías... para siempre.', 28153),
(144933, 'esES', '', 'La muerte no me silenciará...', 28153),
(144932, 'esES', '', '¡Qué alma tan frágil!', 28153),
(144931, 'esES', '', '¡No tenéis poder aquí!', 28153),
(144930, 'esES', '', 'Adalid, sígueme. Loh demáh, id con Rokhan al frente norte.', 28153),
(144929, 'esES', '¡Mira todas esas tropas de la Alianza! ¡Han mandado todo lo que tienen!', '', 28153),
(144928, 'esES', '¡Envían una oleada de soldados contra nosotros! ¡Detenedlos!', '', 28153),
(144926, 'esES', '', 'Saludos, $c.', 28153),
(144925, 'esES', '', 'Nunca olvides lo que significa entregarse a la Luz.', 28153),
(144924, 'esES', '', '<Fareeya te saluda con una cálida sonrisa>.$B$BHas hecho un buen trabajo superando las pruebas, $c, pero creo que tu historia no ha hecho más que empezar.', 28153),
(144923, 'esES', 'Si estás buscando a Maela, está ayudando en el frente.$B$BEn Ventormenta hay varios sastres competentes que podrían enseñarte un par de cosas.', '', 28153),
(144921, 'esES', '', '¡Que la Luz se lleve esta mesa! Tal vez no pueda volver a usar este taller jamás.$B$BPor más que intente limpiar la superficie, no hay forma de eliminar la mancha que dejaron los pellejos de las bestias de Argus.', 28153),
(144908, 'esES', 'El Vindicaar espera su próximo viaje.\n\nY yo también.', '', 28153),
(144907, 'esES', '¡Gracias por la ayuda, $gmuchacho:muchacha;! ¡Te debo una!', '', 28153),
(144906, 'esES', 'Bueno, me voy a la taberna.', '', 28153),
(144905, 'esES', 'Aah, mucho mejor. ¡Una armadura digna de un poderoso héroe! ¡Uno cuyas hazañas legendarias sacuden los mismísimos cimientos de Azeroth!', '', 28153),
(144904, 'esES', '¡Claro que puedo! Compré esta armadura con todas las de la ley, aunque aún no haya acabado de pagarla.', '', 28153),
(144903, 'esES', '', 'Parece que hoy es tu día de suerte, señor Petrocejas. Puedes recuperar la mercancía.', 28153),
(144902, 'esES', '¡Quítame las pezuñas de encima, bola de pelo!', '', 28153),
(144901, 'esES', '', 'Sí, señora.', 28153),
(144900, 'esES', '', '¡Fuera! ¡No os tenemos miedo!', 28153),
(144899, 'esES', '%s asiente con la cabeza.', '', 28153),
(144898, 'esES', '', 'Señor Chu, acompaña a este enano a la salida. Señora Xiulan, vuelve a poner a la venta la armadura.', 28153),
(144897, 'esES', 'Te he enviado el cheque esta mañana, ¡lo juro! ¡No me puedes dejar en la estacada!', '', 28153),
(144896, 'esES', '', 'Te has retrasado en el pago demasiadas veces, señor Petrocejas. Procedo a embargarle la mercancía, como estipulamos en el contrato.', 28153),
(144895, 'esES', '', 'Están aquí...', 28153),
(144894, 'esES', '', 'Lo haremos. De momento descansa.', 28153),
(144893, 'esES', 'Llegaron del bosque. Intentamos luchar, pero el maestro Ashton me apartó y entonces se lo llevaron. ¡Tenemos que salvarlo!', '', 28153),
(144892, 'esES', '', 'Lo sé, Marten. Cuéntanos qué ha ocurrido.', 28153),
(144891, 'esES', '¡He hecho lo que he podido para rechazarlos!', '', 28153),
(144889, 'esES', '', 'Dime, ¿para qué has traído a la enana? ¿Es una demostración de fuerza? ¿Un elemento disuasorio?', 28153),
(144888, 'esES', 'Ha ido justo como imaginé que iría.', '', 28153),
(144887, 'esES', 'Ya... Sí. ¡Claro!', '', 28153),
(144886, 'esES', 'No olvides nuestro objetivo aquí. Debemos encontrar el ojo antes que la Alianza.', '', 28153),
(144885, 'esES', '', '¡Y pensar que quizás los trols han estado sentados sobre el descubrimiento arqueológico del milenio!', 28153),
(144884, 'esES', '', '¡La batalla ha comenzado! ¡Guíanoh a la victoria!', 28153),
(144883, 'esES', 'Cuando te fuihte, dijihte a tu padre que ibah a explorar, no a negociar con loh perroh de la Horda.', '', 28153),
(144882, 'esES', 'Princesa.', '', 28153),
(144881, 'esES', 'Ehtamoh haciendo ehperar a tu padre.', '', 28153),
(144880, 'esES', '', 'Princesa... Permíteme ser la primera en darte la bienvenida...', 28153),
(144879, 'esES', '', 'Que sepah que mi padre eh terco, pero muy observador. Apohtaría a que ya sabe que participahte en mi liberación de Ventormenta.', 28153),
(144878, 'esES', '', 'No ereh tú quien decide su dehtino, general.', 28153),
(144877, 'esES', 'La mejor forma de proteger el reino sería dehterrar a ehta... cosa... a Vol\'dun. No queremoh a la Horda en Zandalar.', '', 28153),
(144876, 'esES', '', 'Jurahte proteger ehte reino. Si no cumpleh con tu misión, tendré que buhcar a alguien que lo haga.', 28153),
(144875, 'esES', '<Toca la lágrima>.', '<Toca la lágrima>.', 28153),
(144874, 'esES', '', 'General.', 28153),
(144873, 'esES', '<La lágrima de un dragón verde, envuelta en sombras por unas fuerzas desconocidas>.', '', 28153),
(144872, 'esES', '', 'Entretanto, loh políticoh conhpiradoreh y loh viejoh del consejo Zanchuli niegan la amenaza y convencen a mi padre de que no haga nada.', 28153),
(144871, 'esES', '', 'Loh trolh de sangre inundan la frontera norte y arrahtran a nuehtro pueblo hacia loh pantanoh de Nazmir. Y allí desaparecen.', 28153),
(144870, 'esES', '', 'Zandalar ehtá repleto de enemigoh, de dentro y de fuera. Por eso buhqué a la Horda... y por eso recurro a ti, su gran adalid.', 28153),
(144869, 'esES', '', 'Por fin tenemoh ocasión de hablar en privado. Hay cosah sobre mi reino que debeh saber.', 28153),
(144868, 'esES', '', 'Ven, adalid de la Horda. Vamoh a visitar a mi padre. Zul... hablaremoh máh tarde.', 28153),
(144867, 'esES', '', '¡Tze\'na! Hola, pequeña. ¿Me hah echado de menoh?', 28153),
(144866, 'esES', '', 'He oído los lamentos de esa niña que mencionas.\n\nTe pondré una marca para que puedas entrar en ese reino y buscarla.\n\nHabita en un lugar donde la frontera entre los reinos de la vida y la muerte es muy delgada; un mundo en que los dos reinos se entremezclan.\n\nPero ten cuidado: no tendrás poder en ese lugar, pues ningún mortal puede dañar a sus habitantes.\n\nInténtalo si quieres, pero nada te garantiza que puedas ayudar a tu amiga.', 28153),
(144864, 'esES', 'Que la Luz esté contigo.', 'Que la Luz esté contigo.', 28153),
(144863, 'esES', 'Estoy buscando a una niñita que se llama Uuna, ¿la has visto?', 'Estoy buscando a una niñita que se llama Uuna, ¿la has visto?', 28153),
(144862, 'esES', '', 'T\'paartos nos enseñó a jugar a roca, pergamino o espada... Pero he olvidado las reglas.', 28153),
(144860, 'esES', '¡Han destruido la puerta de la Alianza!', '', 28153),
(144859, 'esES', '', '¡Grifos! ¡Al ataque!', 28153),
(144853, 'esES', 'Nuestros guerreros más valientes suelen estar en la vanguardia. Lo mínimo que podemos hacer es cuidar de sus familias hasta que regresen.', 'Nuestros guerreros más valientes suelen estar en la vanguardia. Lo mínimo que podemos hacer es cuidar de sus familias hasta que regresen.', 28153),
(144852, 'esES', '¿Entras en mis túneles? ¡Qué insensatez!', '', 28153),
(144851, 'esES', '', '¡Qué cola tan suave!', 28153),
(144850, 'esES', '', '¿Se puede quedar conmigo?', 28153),
(144849, 'esES', '', '¡No! ¡Quédate y cuéntanos historias de aventuras, T\'paartos!', 28153),
(144848, 'esES', '', '¡Ha vuelto!', 28153),
(144847, 'esES', '', '¡Es T\'paartos!', 28153),
(144846, 'esES', 'No os preocupéis. T\'paartos volverá con más historias... Y tal vez con otro amigo nuevo.', '', 28153),
(144845, 'esES', 'Es hora de volver a casa. Decidle adiós, niños.', '', 28153),
(144842, 'esES', '', '¡Oh!', 28153),
(144841, 'esES', 'Cuéntame lo que pasó en el banquete.', 'Cuéntame lo que pasó en el banquete.', 28153),
(144840, 'esES', 'La Dama Oscura tiene un encargo importante para ti. Espero que te hayas preparado...', '', 28153),
(144839, 'esES', '', '¡T\'paartos!', 28153),
(144838, 'esES', '', 'Prométeme que no me abandonarás. Aunque todo se vuelva oscuro...', 28153),
(144837, 'esES', '', 'Pero ahora estás aquí, ¡así que podemos hacerles frente! Creo...', 28153),
(144836, 'esES', '', 'Nunca dejo de correr, pero siempre me encuentran.', 28153),
(144835, 'esES', '', 'Pronto llegarán...', 28153),
(144834, 'esES', '', '¡Estás aquí! Mucho mejor.', 28153),
(144833, 'esES', '¡Ja, ja! T\'paartos se alegra de veros bien. T\'paartos os ha traído un regalo que encontró en Val\'sharah.', '', 28153),
(144832, 'esES', '¡NO PUEDE SER!', '', 28153),
(144831, 'esES', 'Parece que estos globos contienen algún tipo de poder. Tal vez si quito la capa exterior...', '', 28153),
(144830, 'esES', '¡Ah!', '', 28153),
(144829, 'esES', 'Estos ojos parecen muy jugosos. Los estrujaré un poco para sacar algunas gotas y...', '', 28153),
(144828, 'esES', '', 'Tengo tanto frío, y esto está muy oscuro... ¡No sé qué hacer!', 28153),
(144827, 'esES', '', '¡No me rendiré! ¡Te lo prometo!', 28153),
(144826, 'esES', '', '¿Eres tú?', 28153),
(144825, 'esES', 'Nuestros agentes ya se han infiltrado en la operación minera que se está llevando a cabo aquí abajo. Pronto sabremos qué están tramando...', '', 28153),
(144824, 'esES', 'Debí... cavar... más profundo...', 'Debí... cavar... más profundo...', 28153),
(144823, 'esES', 'Un elfo... cavando... ¡Ja!', 'Un elfo... cavando... ¡Ja!', 28153),
(144822, 'esES', 'Llegas demasiado tarde. Hemos encontrado...', 'Llegas demasiado tarde. Hemos encontrado...', 28153),
(144821, 'esES', 'Quien lo encuentra se lo queda...', 'Quien lo encuentra se lo queda...', 28153),
(144820, 'esES', 'Nunca lo encontrarás...', 'Nunca lo encontrarás...', 28153),
(144819, 'esES', 'Tu búsqueda termina ahora. ¡Muere!', 'Tu búsqueda termina ahora. ¡Muere!', 28153),
(144818, 'esES', 'Voy a disfrutar enterrándote.', 'Voy a disfrutar enterrándote.', 28153),
(144817, 'esES', '¡Te excavaremos por los pies!', '¡Te excavaremos por los pies!', 28153),
(144816, 'esES', '¿Pensaste que podías meterte con los Hierro Negro? Mal pensado.', '¿Pensaste que podías meterte con los Hierro Negro? Mal pensado.', 28153),
(144815, 'esES', '¡$gElfo entrometido:Elfa entrometida;! ¡Estas ruinas pertenecen a los Hierro Negro!', '¡$gElfo entrometido:Elfa entrometida;! ¡Estas ruinas pertenecen a los Hierro Negro!', 28153),
(144812, 'esES', '', '¡El enemigo envía refuerzoh!', 28153),
(144811, 'esES', '¡Estas lecturas son inequívocas! ¡Nos dirigiremos al oeste!', '', 28153),
(144810, 'esES', '', '¡El barranco noh pertenece! Hay que reagruparse y planear el siguiente asalto.', 28153),
(144809, 'esES', '', 'Ehtáh intentando colocar un tótem cuadrado en el soporte de uno redondo. El vudú entiende de ehtadoh de ánimo, goblin.', 28153),
(144808, 'esES', '¡Han surgido de la nada, están por todas partes!', '¡Han surgido de la nada, están por todas partes!', 28153),
(144807, 'esES', '', 'Una cualidad admirable. Me gusta eso de él.', 28153),
(144806, 'esES', '', 'Sí, y ayer también. Y anteayer... ¡Y el día de antes también!', 28153),
(144805, 'esES', 'Hemos asegurado los túneles, ¡abrid la puerta!', '', 28153),
(144804, 'esES', 'Veo que hoy está de buen humor, ¿eh?', '', 28153),
(144803, 'esES', '', 'El enemigo se acerca. ¡Bwonsalaka!', 28153),
(144802, 'esES', 'Volveré con el resto. Debemos detenerlo mientras aún podamos.', '', 28153),
(144801, 'esES', 'Gracias, adalid. Me temo que esto es mucho peor de lo que pensaba.', '', 28153),
(144800, 'esES', 'Cuéntame lo que ha pasado en Reposo del León.', 'Cuéntame lo que ha pasado en Reposo del León.', 28153),
(144799, 'esES', 'Mis agentes han asegurado la zona, pero siempre es prudente no hablar muy alto.', '', 28153),
(144798, 'esES', '¡Bwon\'chaga di choka!', '¡Bwon\'chaga di choka!', 28153),
(144796, 'esES', '', 'El vudú alcanza a todoh loh corazoneh, Cala, independientemente de si creen o no.', 28153),
(144795, 'esES', '', '¿El vudú te permite leer la mente de los dinosaurios? ¿En serio?', 28153),
(144794, 'esES', '', 'Eh una cuehtión de amor, Cala. El corazón, incluso el tuyo, comprende el vudú mejor que el cerebro.', 28153),
(144792, 'esES', '¡Ahora tu voluntad me pertenece!', '¡Ahora tu voluntad me pertenece!', 28153),
(144791, 'esES', '¡Loh vaporeh ocultan la verdad!', '¡Loh vaporeh ocultan la verdad!', 28153),
(144790, 'esES', '¡Rehpira hondo!', '¡Rehpira hondo!', 28153),
(144789, 'esES', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Rezan |cFFFF0000|Hspell:260683|h[despierta]|h|r a todos los montones de huesos que quedan!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Rezan |cFFFF0000|Hspell:260683|h[despierta]|h|r a todos los montones de huesos que quedan!', 28153),
(144788, 'esES', '', 'G\'huun...', 28153),
(144787, 'esES', '', 'No... No así...', 28153),
(144786, 'esES', '', 'Mih hermanah... me... vengarán...', 28153),
(144785, 'esES', '', '¡Gachaga!', 28153),
(144784, 'esES', '', 'Zuldazar... caerá...', 28153),
(144783, 'esES', '', 'Maehtra... Véngame...', 28153),
(144782, 'esES', '', 'Pero yo iba a ser la máh fuerte...', 28153),
(144781, 'esES', '', 'Pohkiza...', 28153),
(144780, 'esES', 'Hala, es estupendo.', '', 28153),
(144779, 'esES', 'Excelente trabajo con esas pociones, $n. Ahora solo añadiré un par de gotas de cada uno y...', '', 28153),
(144778, 'esES', '', '¡Ehto va a ser fácil!', 28153),
(144777, 'esES', '', '¡Será una muerte rápida!', 28153),
(144776, 'esES', '', '¡Ja! Ehto eh demasiado fácil...', 28153),
(144775, 'esES', '', '¡Otra calavera pa mi colección!', 28153),
(144774, 'esES', '', '¡Ehta eh nuehtra tierra!', 28153),
(144773, 'esES', '¡Vamos! ¡Por aquí! ¡Tenemos trabajo que hacer!', '', 28153),
(144772, 'esES', 'Está bien descansar de vez en cuando.$B$B¡Sobre todo después de una aventura provechosa!', '', 28153),
(144771, 'esES', 'Tú apaga esos fuegos mientras yo lo preparo todo en el laboratorio. ¡Va a ser divertido!', '', 28153),
(144770, 'esES', 'Se me acaban de terminar los suministros. Lo siento.', '', 28153),
(144769, 'esES', 'Tengo varios globos para ti, Elric.', 'Tengo varios globos para ti, Elric.', 28153),
(144768, 'esES', 'Te he conseguido esas hierbas.', 'Te he conseguido esas hierbas.', 28153),
(144767, 'esES', 'Aquí están los ojos que pediste.', 'Aquí están los ojos que pediste.', 28153),
(144766, 'esES', 'Aquí tienes las pociones que necesitabas.', 'Aquí tienes las pociones que necesitabas.', 28153),
(144765, 'esES', '¡Ah, $gotro:otra; alquimista! Tal vez te interesen algunas de mis últimas recetas.$b$bMi especialidad son las pociones, pero de vez en cuando también me atrevo con la transmutación.', '', 28153),
(144764, 'esES', '¡$gBienvenido:Bienvenida; a mi tienda, $c! ¿Te interesaría un jarabe refrescante o buscas algo distinto?$b$bMi especialidad son las pociones, pero de vez en cuando también me atrevo con la transmutación.', '', 28153),
(144763, 'esES', '', '¡Carne frehca!', 28153),
(144762, 'esES', '', '¡Añadiré tuh orejah a mi colgante!', 28153),
(144761, 'esES', '', '¡Sangre pa G\'huun!', 28153),
(144760, 'esES', 'Shh, ¡no te muevas! Su visión se basa en el movimiento.', 'Shh, ¡no te muevas! Su visión se basa en el movimiento.', 28153),
(144759, 'esES', 'Que la Luz me proteja... ¡Ha vuelto!', 'Que la Luz me proteja... ¡Ha vuelto!', 28153),
(144758, 'esES', 'El vindicador forjado por la Luz suelta un gemido de irritación.', 'El vindicador forjado por la Luz suelta un gemido de irritación.', 28153),
(144757, 'esES', 'Creía que mi mente estaba perdida.', 'Creía que mi mente estaba perdida.', 28153),
(144756, 'esES', '¡Que la Madre Tierra te bendiga!', '¡Que la Madre Tierra te bendiga!', 28153),
(144755, 'esES', 'Ha sido horrible, $r.', 'Ha sido horrible, $r.', 28153),
(144754, 'esES', 'Debo... Mi mente... ¡Debo huir de este lugar!', 'Debo... Mi mente... ¡Debo huir de este lugar!', 28153),
(144753, 'esES', 'Los susurros... ¡Me están volviendo loco!', 'Los susurros... ¡Me están volviendo loca!', 28153),
(144752, 'esES', 'Gracias, adalid.', 'Gracias, adalid.', 28153),
(144751, 'esES', '', 'Hasta la mejor de las armas se mella si se usa demasiado. Tómate el tiempo de sanar por completo, T\'paartos.', 28153),
(144750, 'esES', 'T\'paartos le ofrece su gratitud a Lysara. ¡T\'paartos se siente preparado para luchar otra vez!', '', 28153),
(144749, 'esES', '¡No las suficientes para parar a T\'paartos!', '', 28153),
(144748, 'esES', 'Llévate mi amuleto de efigie a cambio. Créeme, eh lo mejor que tengo.', '', 28153),
(144747, 'esES', '¡Eh una falsificación muy buena! ¿Quién te la dio? ¡No me digah su nombre! Solo dile que venga a verme.', '', 28153),
(144746, 'esES', 'Mantén la boca cerrada y no digah de dónde lo hah sacado o te enseñaré cómo me gané mi apodo.', '', 28153),
(144745, 'esES', '', '¿Otra vez, T\'paartos? Con esta, ¿cuántas veces has...?', 28153),
(144744, 'esES', 'No es la cabeza de cualquier elfa de la noche... ¡Formó parte de la realeza hace miles de años!', '', 28153),
(144743, 'esES', 'El tiempo lo dirá. Ocúpate de esa flor centenaria, $p. Solo florece una vez cada cien años.', '', 28153),
(144742, 'esES', '', '¡Semillah doradah! Tenemoh que plantarlah pa el rey de inmediato. ¿Qué creeh que crecerá, Jahden?', 28153),
(144741, 'esES', 'Ehte pimiento eh perfecto pa mi próxima tanda de chili ehtrapicante... ¡y esah semillah doradah saben fatal!', '', 28153),
(144740, 'esES', '', 'Era real. Es real. Lady Lucille se ha propuesto recuperar nuestras tierras y a nuestra gente.', 28153),
(144739, 'esES', 'Si lo logra, contará con todo mi apoyo.', '', 28153),
(144738, 'esES', '¿En serio? ¡Creía que era una leyenda!', '', 28153),
(144737, 'esES', '', 'Ahora soy inquisidora, alcalde. Lady Lucille ha reformado la Orden de Ascuas para luchar contra estas brujas.', 28153),
(144736, 'esES', 'Estamos tan agradecidos de que aparecieras en el momento justo, teniente...', '', 28153),
(144735, 'esES', '', '¡Graciah, $p! Nuehtrah exihtenciah de piedrah de hogar ehtaban en lah últimah. Coge un pimiento, invita la casa.', 28153),
(144734, 'esES', '¿Te interesa un trabajo, $p? Encuentra a alguien que te compre esah piedrah de hogar. Cámbialah por algo realmente valioso y te recompensaré bien.', '', 28153),
(144733, 'esES', 'Ya sabes lo que significa... ¡Madera gratis!', '', 28153),
(144732, 'esES', 'Oye, mmm... Me han informado de que una especie de árbol monstruoso está deambulando por el bosque.', '', 28153),
(144731, 'esES', '¡Kruac! ¡Tu madre es un trogg! ¡Kruac!', '', 28153),
(144730, 'esES', '¡Cobardes marineros de agua dulce! ¡KRUAC!', '', 28153),
(144729, 'esES', '¡KRUAC!', '', 28153),
(144728, 'esES', 'Psst, $p, ¿alguna vez hah querido darle un puñetazo en la cara a alguien sabiendo que no podíah? ¡Aquí tengo la solución pa ese problema!', '', 28153),
(144727, 'esES', '¡Amuletoh increíbleh! ¡Curiosidadeh asombrosah! ¡Tengo ofertah pa comercianteh de primer nivel!', '', 28153),
(144726, 'esES', 'Escucha los susurros. Son hermosos...', 'Escucha los susurros. Son hermosos...', 28153),
(144725, 'esES', 'Las sombras te consumirán.', 'Las sombras te consumirán.', 28153),
(144724, 'esES', '¡Lah bendicioneh y gritoh ehtán pasadoh de moda! Solo la azerita te puede proporcionar la fuerza que necesitah pa enfrentarte a ehte mundo peligroso y exigente. ¡Empieza a beber azerita embotellada hoy mihmo!', '', 28153),
(144723, 'esES', 'Tu muerte es necesaria.', 'Tu muerte es necesaria.', 28153),
(144722, 'esES', '¡HAZ QUE PARE!', '¡HAZ QUE PARE!', 28153),
(144721, 'esES', 'Llega la Oscuridad...', 'Llega la Oscuridad...', 28153),
(144720, 'esES', 'Si Vol\'jin hubiera llevado su infalible tótem de invulnerabilidad consigo cuando fue a la Costa Abrupta, aún ehtaría entre nosotroh. ¡No cometah el mihmo error!', '', 28153),
(144719, 'esES', 'Ehpía a tuh enemigoh, no pierdah de vihta a tuh amigoh, echa un vihtazo a lah cámarah realeh... ¡Haz todo eso con ehte increíble tótem de fuegoh fatuoh susurranteh!', '', 28153),
(144718, 'esES', 'La llama de ehte tótem ha brillado con fuerza dehde que el rey Rastakhan se sentó por primera vez en el trono. ¡Llévate hoy ehta reliquia de la hihtoria Zandalari!', '', 28153),
(144717, 'esES', 'Con la garantía de Griftah: ¡no hagah preguntah, llévate un dehcuento!', '', 28153),
(144716, 'esES', '¡T\'paartos está aquí!', '', 28153),
(144715, 'esES', '', 'Ahora me siento mucho mejor.', 28153),
(144714, 'esES', '¡T\'PAARTOS!', '', 28153),
(144713, 'esES', '', 'No puedes enfrentarte a la oscuridad sin una corona. ¡Son las reglas!', 28153),
(144712, 'esES', '', '¡Dispara estrellas! Los malos lo odian.', 28153),
(144711, 'esES', 'Mi gente reúne y custodia el conocimiento.\n\nMi trabajo consiste en asegurarme de que nuestros descubrimientos se archivan de forma adecuada.', '', 28153),
(144706, 'esES', 'Tengo mucho que preparar. Ocúpate de ellos.', 'Tengo mucho que preparar. Ocúpate de ellos.', 28153),
(144705, 'esES', 'Esta cháchara me aburre.', 'Esta cháchara me aburre.', 28153),
(144704, 'esES', '¡Esas voces solo proclaman mentiras!', '', 28153),
(144703, 'esES', '¿No sientes el poder de nuestra maestra en las profundidades? ¡Volveremos a unirnos por su voluntad!', '¿No sientes el poder de nuestra maestra en las profundidades? ¡Volveremos a unirnos por su voluntad!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'esES', 'Juramos proteger Brennadam. ¡Proteger a nuestro pueblo! ¿Has olvidado nuestro juramento?', '', 28153),
(144701, 'esES', 'Siempre fuiste demasiado débil para servir a lord Canto Tormenta. Preferiste languidecer como un necio en Brennadam.', 'Siempre fuiste demasiado débil para servir a lord Canto Tormenta. Preferiste languidecer como un necio en Brennadam.', 28153),
(144700, 'esES', '¡Eres tú el que está perdido!', '', 28153),
(144699, 'esES', 'Que losss maresss... te traguen...', '', 28153),
(144698, 'esES', 'Mi vida... por... Azssshara...', '', 28153),
(144697, 'esES', 'Que el abisssmo te lleve...', '', 28153),
(144696, 'esES', 'Mi Reina... He... fallado...', '', 28153),
(144695, 'esES', 'La marea... fluye...', '', 28153),
(144694, 'esES', '', 'La marea... fluye...', 28153),
(144693, 'esES', '', 'Mi Reina... He... fallado...', 28153),
(144692, 'esES', '', 'Que el abisssmo te lleve...', 28153),
(144691, 'esES', '', '¡Mi vida por Azssshara!', 28153),
(144690, 'esES', '', 'Que losss maresss... te traguen...', 28153),
(144689, 'esES', 'Tengo otra pregunta...', 'Tengo otra pregunta...', 28153),
(144688, 'esES', 'Yo diría que te vendría bien un amigo.', 'Yo diría que te vendría bien un amigo.', 28153),
(144687, 'esES', '¿Qué estás haciendo?', '¿Qué estás haciendo?', 28153),
(144686, 'esES', '¡Estoy aquí para ayudar, Kugro!', '¡Estoy aquí para ayudar, Kugro!', 28153),
(144685, 'esES', '¿Puedes echarle un vistazo a este pergamino?', '¿Puedes echarle un vistazo a este pergamino?', 28153),
(144684, 'esES', 'No gastes saliva, joven.\n\nSea lo que sea lo que quieres, no tengo tiempo.', '', 28153),
(144683, 'esES', '¿Un amigo? No, pero un ayudante sí.', '', 28153),
(144682, 'esES', 'Te puedo decir lo que no voy a hacer, no voy a hablar de trivialidades con $gun:una; $r mientras hay trabajo que hacer.', '', 28153),
(144681, 'esES', 'En ese caso, espero que seas multitarea.', '', 28153),
(144680, 'esES', 'No acepto trabajos extras ahora mismo. Voy con mucho retraso. Estos pergaminos no van a escribirse solos.', '', 28153),
(144679, 'esES', 'Estoy en números rojos.', '', 28153),
(144678, 'esES', '', '<Arluelle tiene una mirada distante>.$B$BOjalá mi hermano pudiera ver la ciudad ahora...', 28153),
(144677, 'esES', '', 'Tengo el presentimiento de que no tardarán en recurrir a nuestra ciudad. Cuando llegue la hora, estaré preparada.', 28153),
(144676, 'esES', '¡Qué pena que no consiguiéramos convencer a los forjados por la Luz para que se unieran a nuestro bando! Su destreza marcial es formidable.', '', 28153),
(144675, 'esES', '¿Por qué número iba? ¡Arg!', '', 28153),
(144674, 'esES', 'Los Vigías del ocaso estarán mejor con Victoire entre sus filas una vez más.', '', 28153),
(144673, 'esES', '', 'En marcha.', 28153),
(144672, 'esES', 'Me alegro de que Arluelle continúe con su entrenamiento. Ya se la ve más fuerte.$B$BTal vez debería comprobar cuánto ha mejorado.', '', 28153),
(144671, 'esES', 'Las mareas cambian, hermano. Si no estás con nosotros, estás perdido.', 'Las mareas cambian, hermano. Si no estás con nosotros, estás perdido.', 28153),
(144670, 'esES', 'Uno para ti. Uno para mí.', '', 28153),
(144669, 'esES', '¡Me encanta manipular las cuentas!', '', 28153),
(144668, 'esES', '¡Reid! ¡La flota debe volver a Kul Tiras de inmediato!', '', 28153),
(144667, 'esES', '¿Ya he contado este montón?', '', 28153),
(144666, 'esES', 'Uno... dos... siete... rojo... dos...', '', 28153),
(144665, 'esES', '', 'Ya deberías saber que se me da de lujo volar cosas... ¡Y adivina quién está subiendo como la espuma en la lista de objetivos!', 28153),
(144664, 'esES', '', 'Si sigues así, podrías acabar sufriendo un pequeño \"accidente\".', 28153),
(144663, 'esES', '', '¡Argh! Esto no va a quedar así...', 28153),
(144662, 'esES', '', 'Nos vemos.', 28153),
(144661, 'esES', '', '¿Eh? ¿Eso era todo?', 28153),
(144660, 'esES', '', '¡Hasta otra!', 28153),
(144659, 'esES', '', '¿Qué necesitas, menda?', 28153),
(144658, 'esES', '', '¿Nos ponemos en marcha?', 28153),
(144657, 'esES', '', 'Eh, ¿qué pasa, menda?', 28153),
(144656, 'esES', 'Supongo que ESTO es mi vida ahora. Genial. Siiimplemente... genial.', '', 28153),
(144655, 'esES', 'Así que estas tenemos, ¿eh? ¿En serio? No te aburres de marearme con tanto toqueteo...', '', 28153),
(144654, 'esES', '¿No tienes nada mejor que hacer? Como... ¿ir a besar a un múrloc o algo así?', '', 28153),
(144653, 'esES', 'Eh, ¡venga ya! ¡Un poco de respeto!', '', 28153),
(144652, 'esES', 'Sí, sí, lo que tú digas...', '', 28153),
(144651, 'esES', 'Venga, sigue andando...', '', 28153),
(144650, 'esES', '¡Nos vemos!', '', 28153),
(144649, 'esES', '¡Cargado y listo!', '', 28153),
(144648, 'esES', '¡Listo para la acción!', '', 28153),
(144647, 'esES', 'Si sigues con los toquecicos, vas a acabar perdiendo un dedo...', '', 28153),
(144646, 'esES', 'Y pensar que la mañana había empezado tan bien...', '', 28153),
(144645, 'esES', 'Hola, me llamo \"Parche\", pero tú puedes llamarme \"señor\".', '', 28153),
(144644, 'esES', 'Ninguna muerte es demasiado brutal.', '', 28153),
(144643, 'esES', 'Me encanta que los planes salgan bien.', '', 28153),
(144642, 'esES', 'Nos vemos.', '', 28153),
(144641, 'esES', '¿Cuáles son tus órdenes?', '', 28153),
(144640, 'esES', '¿Cuáles son tus órdenes?', '', 28153),
(144639, 'esES', '¡Ey!', '', 28153),
(144638, 'esES', '¿Te va ehto? A todo el mundo le va algo hoy en día.', '', 28153),
(144637, 'esES', '¿Quiereh saber cómo conseguí ehtah calaverah?', '', 28153),
(144636, 'esES', 'Eh una pena que el nombre \"Lanza Rosa\" ya ehtuviera cogido.', '', 28153),
(144635, 'esES', '¡He perdido la cabeza! Era como... bueno... enorme. Si la encuentrah, dímelo.', '', 28153),
(144634, 'esES', 'Vuelve si necesitah mi ayuda.', '', 28153),
(144633, 'esES', 'No juegueh con el vudú.', '', 28153),
(144632, 'esES', 'Ve con cuidado.', '', 28153),
(144631, 'esES', '¿Qué te cuentah?', '', 28153),
(144630, 'esES', '¡Por loh Lanza Negra!', '', 28153),
(144629, 'esES', 'Te ehcucho.', '', 28153),
(144628, 'esES', 'Muy bien, tú lo has querido. Iniciando reinicio del universo.', '', 28153),
(144627, 'esES', 'Los golpecitos continuados no hacen que el sistema actúe más rápido.', '', 28153),
(144626, 'esES', 'Objetivo potencial detectado para contención.', '', 28153),
(144625, 'esES', 'Error. Se recomienda no intentar de nuevo.', '', 28153),
(144624, 'esES', 'Interacción completada.', '', 28153),
(144623, 'esES', 'Reanudando protocolo de contención.', '', 28153),
(144622, 'esES', 'Reiniciando escáner.', '', 28153),
(144621, 'esES', '', '¡Saludos, $p! En Azeroth nos esperan nuevas tierras y nuevos aliados.$B$BOculeth ha preparado unos portales más abajo para cuando quieras partir.', 28153),
(144620, 'esES', 'Corrupción detectada. Activando programa de contención.', '', 28153),
(144619, 'esES', 'Protocolo de alta prioridad: contener la corrupción.', '', 28153),
(144618, 'esES', 'Unidad Hezrel conectada. Objetivo: contener la corrupción.', '', 28153),
(144617, 'esES', '', 'Estás haciendo que cada segundo contigo me parezca una eternidad...', 28153),
(144616, 'esES', '', '¿Alguna vez has oído la historia de la tortoliana que se volvió loca y atacó a quien la estaba molestando?', 28153),
(144614, 'esES', '', 'Me estás cabreando...', 28153),
(144613, 'esES', '', '¿Ya has terminado?', 28153),
(144612, 'esES', '', 'La próxima vez busca otra víctima a la que molestar.', 28153),
(144611, 'esES', '', 'Ya tardabas...', 28153),
(144610, 'esES', '', 'Uff. ¿Qué quieres?', 28153),
(144609, 'esES', '', '¿De verdad tienes que hablar conmigo?', 28153),
(144608, 'esES', '', '¿Qué quieres ahora?', 28153),
(144605, 'esES', 'Lárgate... ¡o usaré tu alma pa pagar mi deuda!', '', 28153),
(144604, 'esES', 'Un consejito: ¡nunca hagah tratoh con un loa muerto!', '', 28153),
(144603, 'esES', 'No pierdah tu alma.', '', 28153),
(144602, 'esES', 'Ve con cuidado.', '', 28153),
(144601, 'esES', 'Cuídate.', '', 28153),
(144600, 'esES', 'Saludoh.', '', 28153),
(144599, 'esES', '¿Qué puede hacer Hanzabu por ti?', '', 28153),
(144598, 'esES', 'Tengo mucho que hacer.', '', 28153),
(144597, 'esES', 'Nos has salido rana...', '', 28153),
(144596, 'esES', 'Tengo un rebote...', '', 28153),
(144595, 'esES', '¡Estoy a la que salto!', '', 28153),
(144594, 'esES', 'No has venido a besarme, ¿verdad?', '', 28153),
(144593, 'esES', 'Hasta la próxima.', '', 28153),
(144592, 'esES', 'Mira antes de brincar.', '', 28153),
(144591, 'esES', 'Que nunca te falten moscas frescas.', '', 28153),
(144590, 'esES', 'Habla.', '', 28153),
(144589, 'esES', '¿Te estás dirigiendo a Krag\'wa?', '', 28153),
(144588, 'esES', '¿Sí?', '', 28153),
(144587, 'esES', 'Noh vemoh pronto... MUY pronto.', '', 28153),
(144586, 'esES', 'Venga, ¡lárgate!', '', 28153),
(144585, 'esES', 'Tarde o temprano, todoh vienen a mí.', '', 28153),
(144584, 'esES', 'Parece que tieneh sed... ¿Quiereh algo de beber? ¿Qué tal una sangría? ¡Ja, ja, ja!', '', 28153),
(144583, 'esES', 'En ocasioneh veo muertoh. Deformación profesional.', '', 28153),
(144582, 'esES', 'Mm... Veo que te guhta tentar a la suerte.', '', 28153),
(144581, 'esES', 'Cuidado. No olvideh con quién ehtáh tratando...', '', 28153),
(144580, 'esES', 'Bueno, bueno... ¿Vieneh a hacer un trato?', '', 28153),
(144579, 'esES', '¿Qué quiereh de la muerte?', '', 28153),
(144578, 'esES', '¿Qué te trae hahta el viejo y solitario Bwonsamdi?', '', 28153),
(144577, 'esES', 'Estoy listo.', 'Estoy lista.', 28153),
(144576, 'esES', 'Debemos detener esta locura antes de que sea demasiado tarde.', '', 28153),
(144575, 'esES', '', 'No me separaré de él. Así no se volverá a perder.', 28153),
(144574, 'esES', '¡Se la han llevado delante de nuestras narices! ¡Qué descaro!', '', 28153),
(144573, 'esES', 'No, no, esto no puede ser. Según mis cálculos debería ser...', '', 28153),
(144572, 'esES', 'Estos resultados son tan confusos. ¡Si estos pequeños... barbosos... o como se llamen... me dejaran concentrarme!', '', 28153),
(144571, 'esES', 'Debo volver a intentarlo. Lo has hecho bien, aunque creía que nuestros enemigos serían más altos.', '', 28153),
(144570, 'esES', 'Confío en que podrás encargarte de cualquier intromisión.', '', 28153),
(144569, 'esES', '¡Por aquí! Cuando empiece a buscar, estaré totalmente centrado en la visión.', '', 28153),
(144568, 'esES', '¡Argus el Aniquilador está desplegando módulos de recreación!', '¡Argus el Aniquilador está desplegando módulos de recreación!', 28153),
(144567, 'esES', '', 'Nuu ha venido a ayudarnos. ¡Sabía que nos encontrarías, Nuu!', 28153),
(144566, 'esES', 'Seguimos registrando daños estructurales y energía inestable en los acueductos. La puerta permanecerá cerrada de momento.', 'Seguimos registrando daños estructurales y energía inestable en los acueductos. La puerta permanecerá cerrada de momento.', 28153),
(144565, 'esES', 'Yo lo vigilaré. Creo que estará feliz paseando por los jardines.', 'Yo lo vigilaré. Creo que estará feliz paseando por los jardines.', 28153),
(144564, 'esES', '', '¡Muy bien! ¡Estoy impresionada!', 28153),
(144563, 'esES', '', 'Dirigir la energía chi hacia un objetivo puede resultar difícil al principio.\n\nTú, en primera fila, intenta golpear a ese muñeco de entrenamiento.', 28153),
(144562, 'esES', 'Psst, $pr... ¿Quiereh comprar?', '', 28153),
(144561, 'esES', '¿Qué tienes ahí, $p? ¿Es una flor centenaria?', '', 28153),
(144560, 'esES', '', 'Tenemoh que empezar a preparar la próxima temporada de siembra, Jahden.', 28153),
(144559, 'esES', 'Mmm... A ehte chili le falta algo... Necesita un poco de picante.', '', 28153),
(144558, 'esES', '', '¡Zancha! ¿Te hah olvidado de rellenar la cehta de piedrah de hogar otra vez?', 28153),
(144557, 'esES', '¡Adióoooos!', '', 28153),
(144556, 'esES', 'Que nades bien.', '', 28153),
(144555, 'esES', 'El agua mola tanto. Me gusta el agua. ¿Y a ti? ¿Qué es lo que más te gusta de ella? A mí, lo mojada que está. El agua mola, ¿a que sí?', '', 28153),
(144554, 'esES', 'Mi mamá dice que somos anfobios... anfábulos... ah... eeh... ¡anfibios! Uff, ¡por fin!', '', 28153),
(144553, 'esES', 'Tortol tortol tortol, siempre voy rodando. Tortol tortol tortol, con las patas volando.', '', 28153),
(144552, 'esES', '¡Cuando crezca, pienso leer TODO lo que vea!', '', 28153),
(144551, 'esES', '¿Dónde llevas todas tus cosas sin un caparazón?', '', 28153),
(144550, 'esES', '¡Me gusta rodar!', '', 28153),
(144549, 'esES', '¡Pronto seré tan mayor como tú!', '', 28153),
(144548, 'esES', 'Vale, adiós. Ya había acabado de hablarte de todas formas.', '', 28153),
(144547, 'esES', 'No todo lo que hay en el océano es tan atractivo y amable como yo.', '', 28153),
(144546, 'esES', 'Si encuentras algo exótico, tráemelo.', '', 28153),
(144545, 'esES', 'Vuelve con historias mejores.', '', 28153),
(144544, 'esES', 'He visto cosas que te dejarían con la boca abierta.', '', 28153),
(144543, 'esES', 'Acércate y no masculles.', '', 28153),
(144542, 'esES', 'Saludos, dama o caballero.', '', 28153),
(144541, 'esES', '¿Tienes algún objeto antiguo que intercambiar? Que tenga al menos dos siglos.', '', 28153),
(144540, 'esES', '', '¡¿Me ehtáh evitando?!', 28153),
(144539, 'esES', '', 'Adióh.', 28153),
(144538, 'esES', '', 'Una vez robé una alpaca y me la llevé al templo. Pero mi madre me obligó a soltarla.', 28153),
(144537, 'esES', '', 'Una vez le di una paliza a un aventurero y me llevé su cráneo. Era máh grande que tú...', 28153),
(144536, 'esES', '', 'Una vez cogí a un brutosaurio por la cola. Dejé que me arrahtrara durante 32 suhpiroh y medio.', 28153),
(144535, 'esES', 'Un albatros sañoso se lanza hacia el huevo en eclosión.', '', 28153),
(144534, 'esES', '', 'Una vez capturé un sáurido. Era muy, muy, muy, muy, muy, muy, muy, muy, muy grande. Me dijeron que era un ravasaurio, pero creo que loh mayoreh mentían.', 28153),
(144533, 'esES', '', 'Una vez cogí el pez máh grande nunca vihto. Pero al final era un guardia maldito.', 28153),
(144532, 'esES', '', '¡Taz\'okun!', 28153),
(144531, 'esES', '', '¡Taz\'dingo!', 28153),
(144530, 'esES', '', '¡Mi loa podría darle una paliza al tuyo!', 28153),
(144529, 'esES', '', '¡Algún día seré un loa!', 28153),
(144528, 'esES', 'Adióh, coleguita.', '', 28153),
(144527, 'esES', '¿Adónde vah?', '', 28153),
(144526, 'esES', 'Loh loa son lo mejor. ¡Son tan grandeh que podrían comerte!', '', 28153),
(144525, 'esES', 'De mayor seré un druida brutosaurio. ¡Grrr!', '', 28153),
(144524, 'esES', 'Tengo diez dedoh... pero solo ocho son míoh.', '', 28153),
(144523, 'esES', 'Alguien me ha robado mi caja de cabezah reducidah. ¿Hah sido tú?', '', 28153),
(144522, 'esES', 'Oh, hola.', '', 28153),
(144521, 'esES', '¡Taz\'okun!', '', 28153),
(144520, 'esES', '¡Taz\'dingo!', '', 28153),
(144519, 'esES', '¡Grr!', '', 28153),
(144518, 'esES', 'Loh loa son fuerteh aquí.', 'Loh loa son fuerteh aquí.', 28153),
(144517, 'esES', 'Que loh ehpírituh te guíen.', 'Que loh ehpírituh te guíen.', 28153),
(144516, 'esES', 'Loh loa siempre ehtán observando.', 'Loh loa siempre ehtán observando.', 28153),
(144515, 'esES', '¡Bah! Tómate doh de ehtah y vuelve mañana.', '¡Bah! Tómate doh de ehtah y vuelve mañana.', 28153),
(144513, 'esES', '¡No tienteh a la suerte!', '¡No tienteh a la suerte!', 28153),
(144512, 'esES', 'Aquí encontraráh el mejor juju.', 'Aquí encontraráh el mejor juju.', 28153),
(144511, 'esES', 'Loh ehpírituh susurran tu nombre.', 'Loh ehpírituh susurran tu nombre.', 28153),
(144510, 'esES', '¿Con qué loa tratah?', '¿Con qué loa tratah?', 28153),
(144509, 'esES', '', '¡Adelante, por el futuro de Zandalar!', 28153),
(144508, 'esES', 'Bueno, ha sido una presentación incómoda... Será mejor que me dé prisa o Kugro se enfadará.', '', 28153),
(144498, 'esES', 'Zandalar prevalecerá.', 'Zandalar prevalecerá.', 28153),
(144497, 'esES', 'Nunca temas a los débiles.', '', 28153),
(144496, 'esES', 'Inflige heridas a tus enemigos.', '', 28153),
(144495, 'esES', 'Que pruebes la carne de tus enemigos.', '', 28153),
(144494, 'esES', '¿Qué ocurre, criatura de la Horda?', '', 28153),
(144493, 'esES', 'Estás en mis tierras.', '', 28153),
(144492, 'esES', '¿Eres el depredador, o la presa?', '', 28153),
(144491, 'esES', '¿Has venido a hacer un trato?', '', 28153),
(144490, 'esES', 'Habla a otros de mí.', '', 28153),
(144489, 'esES', 'Que tus enemigos nunca te huelan venir.', '', 28153),
(144488, 'esES', 'Aporta fuerza a tu manada.', '', 28153),
(144486, 'esES', 'Si piensas huir, ten en cuenta que sé abrir puertas.', '', 28153),
(144484, 'esES', 'Si sigues así, serás mi próxima presa.', '', 28153),
(144481, 'esES', 'Soy el maestro de las formas, el líder de la manada y el señor de la caza.', '', 28153),
(144480, 'esES', '¿Qué te trae ante el señor de la caza?', '', 28153),
(144479, 'esES', '¿Has venido a hacer un trato?', '', 28153),
(144478, 'esES', '', 'Que tengas el viento a favor... y aléjate de mí.', 28153),
(144477, 'esES', '', 'Recuerda, los cielos son míos.', 28153),
(144476, 'esES', '', 'Sembrarás la muerte desde el cielo.', 28153),
(144475, 'esES', '', 'El viento es mi voluntad.', 28153),
(144474, 'esES', '', 'Te llevaré a lo más alto... ¡y te dejaré caer sobre una roca!', 28153),
(144473, 'esES', '', '¿Quieres enfurecerme?', 28153),
(144472, 'esES', '', 'Pones a prueba mi paciencia, joven.', 28153),
(144471, 'esES', '', '¿Por qué debo respirar el mismo aire que tú?', 28153),
(144470, 'esES', '', '¿Qué ocurre, joven?', 28153),
(144469, 'esES', '', '¿Has venido a hacer un trato?', 28153),
(144468, 'esES', '', 'Psst, $pr... ¿Ehtáh $gharto:harta; de parecer un sáurido? ¡Mi mojo hará que parezcah un demosaurio!', 28153),
(144462, 'esES', '', 'Elige bien a tu loa.', 28153),
(144461, 'esES', '', 'Ehpero que siempre encuentreh lah huellah de tuh enemigoh.', 28153),
(144460, 'esES', '', 'Por la manada.', 28153),
(144459, 'esES', '', 'Nunca domeh a la behtia interior.', 28153),
(144458, 'esES', '', 'Abraza el lado salvaje.', 28153),
(144457, 'esES', '', 'Quédate por aquí, puede que te necesite máh tarde.', 28153),
(144456, 'esES', '', 'Ehtoy agotada.', 28153),
(144455, 'esES', '', 'No pareh.', 28153),
(144454, 'esES', '', 'Si no parah de hacer eso, mi marido se va a poner celoso.', 28153),
(144453, 'esES', '', '¿Alguna vez te hah pasado al lado salvaje?', 28153),
(144452, 'esES', 'Voy a tener que ocuparme yo mismo del asunto. ¡No permitiré que arruines la operación!', '', 28153),
(144451, 'esES', 'Gracias, $n. Parece que Kugro ha estado ocupado. Ahora... ¿qué hacemos con todos estos pergaminos?', '', 28153),
(144450, 'esES', '', 'Loh loa son fuerteh aquí.', 28153),
(144449, 'esES', '', '¿Saleh de casa con esa forma?', 28153),
(144448, 'esES', '¡No eres mi contacto! ¡Venid aquí, muchachos, carne fresca!', '', 28153),
(144447, 'esES', '', 'Sirvo a Gonk, maehtro de lah formah.', 28153),
(144446, 'esES', '<Entregar los pergaminos a Itokka>.', '<Entregar los pergaminos a Itokka>.', 28153),
(144445, 'esES', '', 'Ojalá Nuu estuviera aquí. Él sabría qué hacer.', 28153),
(144444, 'esES', '', 'Ah, ¡hola! ¿Quién eres? Yo soy Uuna. ¿Quieres que sea tu amiga? Si unimos fuerzas, puede que podamos salir de este lugar.', 28153),
(144443, 'esES', '¡Oye! Tengo juhto lo que necesitah. ¡El rehguardo sáurido personal de Zul! ¡Mantiene alejadoh a esoh malandrineh ladroneh!', '', 28153),
(144442, 'esES', '', '¡Brilla demasiado! ¡No puedo! ¡Ayyy!', 28153),
(144441, 'esES', 'Mil bendiciones, $gviajero:viajera;.\n\nDeja tu arma y descansa un momento.\n\nLa guerra puede esperar.', '', 28153),
(144440, 'esES', '¡Saludoh, pakura\'ai!', '', 28153),
(144439, 'esES', 'Elige bien a tu loa.', '', 28153),
(144438, 'esES', 'Como siempre dice mi loa... Retírate.', '', 28153),
(144437, 'esES', 'Que Pa\'ku dehcubra a tu enemigo anteh de que él te dehcubra a ti.', '', 28153),
(144436, 'esES', 'Que loh vientoh de la guerra te sean favorableh.', '', 28153),
(144435, 'esES', '¡Perfecto! ¡Hah dado en el clavo!', '', 28153),
(144434, 'esES', 'Oh, oh, sigue por ahí... Un poco máh a la derecha... Oh...', '', 28153),
(144433, 'esES', 'Ojalá mi ehposa me prehtase tanta atención.', '', 28153),
(144432, 'esES', 'Como siempre dice mi loa... ¡No toqueh!', '', 28153),
(144431, 'esES', 'Como siempre dice mi loa... ¡Agáchate! ¡Ja, ja, ja, ja, ja!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'esES', '¿Te vieneh con loh saurioh?', '', 28153),
(144429, 'esES', 'El cielo me guía.', '', 28153),
(144428, 'esES', 'Sirvo a Pa\'ku, una de lah loa máh antiguah.', '', 28153),
(144427, 'esES', '', 'Lucho pa proteger a loh que no pueden defenderse soloh.', 28153),
(144425, 'esES', 'Todoh tenemoh un propósito, incluso tú.', '', 28153),
(144424, 'esES', 'He presenciado muchoh eventoh importanteh de nuehtro tiempo, y aparecíah en todoh. Curioso.', '', 28153),
(144423, 'esES', 'Se acercan díah terribleh.', '', 28153),
(144422, 'esES', 'Ehto eh el horror, colega. Verdadero horror.', '', 28153),
(144421, 'esES', 'El imperio trol resurgirá. Lo he vihto.', '', 28153),
(144420, 'esES', 'Loh trolh fueron loh primeroh en gobernar el mundo, y serán loh últimoh.', '', 28153),
(144419, 'esES', 'La suerte no te acompaña.', '', 28153),
(144418, 'esES', 'Ya sé lo que vah a decir, así que acabemoh cuanto anteh.', '', 28153),
(144417, 'esES', 'He vihto el fin del mundo, y no te va a guhtar.', '', 28153),
(144416, 'esES', '', 'Zandalar prevalecerá.', 28153),
(144415, 'esES', '', 'Venganza por loh caídoh.', 28153),
(144414, 'esES', '', 'Que lah calaverah de tuh enemigoh adornen tu atuendo.', 28153),
(144413, 'esES', '', 'Loh tiempoh cambian, y loh Zandalari deben cambiar también.', 28153),
(144412, 'esES', '', 'Hay mucho que hacer. Habla rápido.', 28153),
(144411, 'esES', 'Que tuh enemigoh tiemblen ante ti.', '', 28153),
(144410, 'esES', 'Zandalar eterno.', '', 28153),
(144409, 'esES', 'Que Rezan te otorgue fuerza.', '', 28153),
(144408, 'esES', 'Sienta bien ser rey.', '', 28153),
(144407, 'esES', 'Te encuentrah ante el rey Rahtakhan.', '', 28153),
(144406, 'esES', 'Te doy la bienvenida a Zuldazar.', '', 28153),
(144405, 'esES', '¿Ereh el depredador, o la presa?', '', 28153),
(144404, 'esES', '', 'Ojalá pudiera ver mejor... ¡Siempre está todo tan oscuro por aquí!', 28153),
(144403, 'esES', '', 'Pero estás conmigo, y sé que todo va a salir bien.', 28153),
(144402, 'esES', '', 'Al menos ahora nos hacemos compañía, aunque no sepamos dónde estamos...', 28153),
(144401, 'esES', '', '¡Socorro! ¡SOCORRO!', 28153),
(144400, 'esES', '', '¿Quién eres? ¿Puedes ayudarme?', 28153),
(144399, 'esES', '', 'Está tan oscuro... ¡No veo nada!', 28153),
(144397, 'esES', '', 'Aunque los problemas con Elisande ya son historia, aún quedan muchas cosas que hacer por la ciudad.', 28153),
(144396, 'esES', '', 'Ahora los Nocheterna somos completamente libres. Ya no necesitamos la Fuente de la Noche ni su poder.$b$bPodemos forjar nuestro propio destino.', 28153),
(144395, 'esES', 'He traído muestras para combatir los rumores infundados de que nuestro vino sabe a gruta... ¡A fruta! Quería decir \"a fruta\".', '', 28153),
(144394, 'esES', 'Algunos vinateros han dejado de cuidar de las vides y se están dedicando a otras tareas botánicas.', '', 28153),
(144393, 'esES', 'Loh trolh de sangre ehtaban luchando contra loh guardiah cuando llegamoh. No ehperaban un ataque dehde la retaguardia.', '', 28153),
(144392, 'esES', 'Vaya, es muy grande. ¡Vas a tener que ayudarme a acabar con él!', '', 28153),
(144391, 'esES', 'Si te encuentras con un grupo, ¡lánzales una de esas bombas de púas para que prueben su propia medicina!', '', 28153),
(144390, 'esES', '¡A que duele! ¡Fuera de mis tierras!', '', 28153),
(144389, 'esES', '¡Ja, le he dado entre ceja y ceja!', '', 28153),
(144388, 'esES', 'Puedes volver y decirle a Roz que estoy bien, pero nunca dejaré mi granja. Nunca los abandonaré.', '', 28153),
(144387, 'esES', 'Sí, servirá. Siempre les ha encantado este lugar...', '', 28153),
(144386, 'esES', 'Puedes usar el portal a Orgrimmar para reunirte con nuestros aliados de la Horda en su capital, en Kalimdor.', '', 28153),
(144385, 'esES', '', '¡Rokhan! ¿Ehtáh bien? Parece que aquí se ha librado una batalla.', 28153),
(144384, 'esES', 'He oído que Dalaran tiene toda una planta dedicada al transporte mágico.$B$B¡Imagina las posibilidades!', '', 28153),
(144383, 'esES', 'Resulta muy pesado mantener estos portales. Además, ¡le roban tiempo a otras investigaciones más útiles!$B$BEstoy seguro de que la telemancia nos permitirá obtener una solución más estable.', '', 28153),
(144382, 'esES', '¿Quién dijo que los goblins no tenían cultura?', '', 28153),
(144381, 'esES', '¡Hasta tienen uno de nuestros tambores!', '', 28153),
(144380, 'esES', '¡Y encuentra un tambor abierto!', '', 28153),
(144379, 'esES', '¡$gBienvenido:Bienvenida; a El Tamborilero Beodo, $pr! Toma un trago...', '', 28153),
(144378, 'esES', '¡Argh! ¡Pensaba que mi plan era infalible, colega!', '', 28153),
(144377, 'esES', '¡Idiota! ¡Pagaráh por pasar por debajo de mi puente!', '', 28153),
(144376, 'esES', '¡Oye, colega! Ehtáh cruzando mi puente, colega. Paga el peaje del trol, colega, ¡o pagaráh con tu sangre!', '', 28153),
(144375, 'esES', 'Estoy listo para comenzar la prueba.', 'Estoy lista para comenzar la prueba.', 28153),
(144374, 'esES', '', '¿Y si les pegásemos unos cuantos explosivos? Sería divertidísimo... ¡Dinosaurios explosivos!', 28153),
(144373, 'esES', '', 'Aprecio tu entusiasmo, Shuga. Pero estoy segura de que los Zandalari prefieren encantar sus armas con magia poderosa, no con monstruosidades grasientas.', 28153),
(144372, 'esES', '¿En qué nos hemos... convertido?', '', 28153),
(144371, 'esES', '', '¡No! ¡Suéltame! ¡Socorro! ¡Ayúdame!', 28153),
(144370, 'esES', '', '¡Vuelve a estar oscuro! ¿Dónde estás? ¡No me dejes sola!', 28153),
(144369, 'esES', '', '¡Antes tenía una varita como esa! Pero la perdí hace mucho tiempo.', 28153),
(144368, 'esES', '', '¡Una corona! ¡Qué bonita es!', 28153),
(144367, 'esES', '', '¡Nuu-nuu! ¡Me daba miedo no volver a verte nunca! ¿Cómo has llegado hasta aquí?', 28153),
(144366, 'esES', '', '¡Ah! ¡Ahora hay más luz! Veo... más o menos.', 28153),
(144365, 'esES', '', '¿Qué es eso? ¡Una luz en la oscuridad! Brilla mucho...', 28153),
(144364, 'esES', 'Lo... prometió...', '', 28153),
(144363, 'esES', '¡Me dijeron que así podríamos estar juntos!', '', 28153),
(144362, 'esES', '', '¡Con el apoyo de loh loa y valor en nuehtroh corazoneh, alcanzaremoh la victoria!', 28153),
(144361, 'esES', '', 'Acabaremoh con loh trolh de sangre. Hay que asegurarse de que no usen suh abominacioneh contra nosotroh.', 28153),
(144360, 'esES', '', 'Nuehtroh enemigoh pretenden dehtruir todo cuanto amamoh. ¡No permitiremoh que triunfen! ¡Zandalar depende de lo que hagamoh aquí hoy!', 28153),
(144359, 'esES', '', 'Soldadoh, amigoh, hemoh sufrido mucho, pero pronto terminarán nuehtrah penuriah.', 28153),
(144358, 'esES', 'Muéstrame adónde puedo ir en ferri.', 'Muéstrame adónde puedo ir en ferri.', 28153),
(144357, 'esES', '¿Necesitas un ferri?', '¿Necesitas un ferri?', 28153),
(144356, 'esES', '', '¡Menos mal que me puse las botas!', 28153),
(144355, 'esES', 'Me llevaré a algunoh tortolianoh e iremoh a Zul\'jan a pie. Que tengáih mucha suerte.', '', 28153),
(144354, 'esES', 'Vivo y muero... ¡por la Horda!', 'Vivo y muero... ¡por la Horda!', 28153),
(144353, 'esES', '¡Sangre y honor!', '¡Sangre y honor!', 28153),
(144352, 'esES', '¡Arathi pertenece a la Horda!', '¡Arathi pertenece a la Horda!', 28153),
(144351, 'esES', '¡Seguidme!', '¡Seguidme!', 28153),
(144350, 'esES', '¡Muerte a la Alianza!', '¡Muerte a la Alianza!', 28153),
(144349, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(144348, 'esES', '¡Por aquí! ¡A la batalla!', '¡Por aquí! ¡A la batalla!', 28153),
(144347, 'esES', '¡Vamos, brutos! ¡Tenemos una guerra que ganar!', '¡Vamos, brutos! ¡Tenemos una guerra que ganar!', 28153),
(144346, 'esES', '¡Soy Gral!', '', 28153),
(144345, 'esES', 'Al sur encontrarás lo que queda de mi templo. ¡Nos reuniremos allí y les enseñaremos a esos nagas la furia de un loa tiburón!', '', 28153),
(144344, 'esES', 'Oh... Estabas delicioso.', '', 28153),
(144343, 'esES', '¡No hay profundidades lo suficientemente oscuras para ti!', '', 28153),
(144342, 'esES', '¡Los nagas no son bienvenidos en Atal\'Gral!', '', 28153),
(144341, 'esES', 'El aroma deliciosamente penetrante de la sangre naga infundida de ira... Los bocados tiernos y dulces... Acudiré por eso.', '', 28153),
(144340, 'esES', '', 'Madre, Benjamin me lo contó todo.\n\nNo pudiste oírme antes, ¿podrás ahora tal vez? Solo quería una explicación.', 28153),
(144339, 'esES', '', 'Madre, sé que no estás aquí, pero si puedes oírme...', 28153),
(144338, 'esES', 'Puede que no sea el mejor administrador, pero mamá era increíble. Cómo pudo caer así...$b$bNos las apañaremos, $n. Gracias por tu ayuda.', '', 28153),
(144337, 'esES', '', '¿Adónde vas?', 28153),
(144336, 'esES', '', 'Por favor, no me dejes.', 28153),
(144335, 'esES', '¡Nuestra maestra bajo las mareas nos guiará hasta la victoria!', '¡Nuestra maestra bajo las mareas nos guiará hasta la victoria!', 28153),
(144334, 'esES', 'Me alegra ver que habéis vuelto de una pieza, ¡y todo gracias al nuevo fichaje!', '', 28153),
(144333, 'esES', '¿Te quedas o te vas?', '', 28153),
(144332, 'esES', 'Discúlpame. Tengo que encontrar a mi hermana.', '', 28153),
(144331, 'esES', 'Cuando mi padre murió, mi madre desapareció. Pero nunca pensé que...', '', 28153),
(144330, 'esES', 'Mi padre y ella trabajaron toda la vida para construir este negocio y que no nos faltara nada ni a mi hermana ni y a mí.', '', 28153),
(144329, 'esES', 'Esa bruja... era mi madre.', '', 28153),
(144328, 'esES', 'Parece que sabes apañártelas con las bestias. ¿Qué necesitas?', '', 28153),
(144327, 'esES', '¿Qué pasa ahora? ¿Has perdido algo?', '', 28153),
(144326, 'esES', '¡Excelente! Otra vez, desde el principio.', '', 28153),
(144325, 'esES', 'Es peligroso gastar demasiada energía de golpe. Tomáoslo con calma, alumnos.', '', 28153),
(144324, 'esES', 'El chi enfocado es extremadamente potente. El maestro Tau Li os guiará cuando estéis preparados.', '', 28153),
(144323, 'esES', 'Para sanar, debéis reunir vuestra fuerza interior y pasársela a otro.', '', 28153),
(144322, 'esES', 'Me alegro de no haberlo perdido todo.', 'Me alegro de no haberlo perdido todo.', 28153),
(144321, 'esES', 'Nuestros hermanos corruptos siguen vagando por los bosques.', 'Nuestros hermanos corruptos siguen vagando por los bosques.', 28153),
(144320, 'esES', '', 'Mi vida... por la Horda.', 28153),
(144319, 'esES', '', 'Noh vemoh pronto, colega.', 28153),
(144318, 'esES', '', '¡Sangre y truenos!', 28153),
(144317, 'esES', '', 'Acabaré contigo.', 28153),
(144316, 'esES', '', 'Mi acero quiere tu carne.', 28153),
(144315, 'esES', '', '¡Tu fuerza no puede rivalizar con la de un orco!', 28153),
(144314, 'esES', '', '¡Tus huesos no son rival para mis hojas!', 28153),
(144313, 'esES', '', '¡Mantened la posición! ¡Que no pase nadie!', 28153),
(144312, 'esES', 'Gracias, $gamigo:amiga;.', '', 28153),
(144311, 'esES', 'Perdóname si no te recuerdo la próxima vez que nos encontremos.', '', 28153),
(144310, 'esES', 'Gracias por encargarte de Torok. Se negaba a ver los peligros del poder que andaba buscando.', 'Gracias por encargarte de Torok. Se negaba a ver los peligros del poder que andaba buscando.', 28153),
(144309, 'esES', '<El tauren dormido ronca con fuerza y se da la vuelta>.', '<La tauren dormida ronca con fuerza y se da la vuelta>.', 28153),
(144308, 'esES', 'Zzzzz...', 'Zzzzz...', 28153),
(144307, 'esES', 'Yo también, Princesa. Hahta el final.', '', 28153),
(144306, 'esES', '', 'Ehta eh la única forma de proteger a mi pueblo, Rokhan. Ehtoy dihpuehta a darlo todo por salvarloh. ¿Y tú?', 28153),
(144305, 'esES', 'Aún me cuesta creer que mis hermanos y hermanas sucumbieran a la magia vil.', 'Aún me cuesta creer que mis hermanos y hermanas sucumbieran a la magia vil.', 28153),
(144304, 'esES', '', '¡Hijah, así eh como se trata a loh invitadoh!', 28153),
(144303, 'esES', '', 'La sangre... me vengará...', 28153),
(144302, 'esES', '', '¡Por lah matriarcah de guerra!', 28153),
(144301, 'esES', 'Ahora concentraos en vuestro chi. Expulsad la energía hacia fuera.', '', 28153),
(144300, 'esES', '', '¡Tu esencia será máh útil dehde fuera!', 28153),
(144299, 'esES', '', 'Será divertido drenarte.', 28153),
(144298, 'esES', '', '¡Tu sangre va a alimentarnoh!', 28153),
(144297, 'esES', '', 'Me haré con tu sangre. ¡El resto se puede pudrir!', 28153),
(144296, 'esES', '', 'Tu sangre bañará mi hoja.', 28153),
(144295, 'esES', '¡Si necesitas transporte, ya sabes dónde encontrarme!', '', 28153),
(144294, 'esES', '', '¡Sangre pa nuehtroh ritualeh!', 28153),
(144293, 'esES', '', 'Me haré un bonito arnéh con tu piel.', 28153),
(144292, 'esES', '', 'Los cielos... me llaman.', 28153),
(144291, 'esES', '', 'Un día precioso para una batalla.', 28153),
(144290, 'esES', '', '¡Loh tragadoneh comerán bien ehta noche!', 28153),
(144289, 'esES', '¡Aguanta! Iré a ver cómo ehtá Satao.', '', 28153),
(144288, 'esES', 'ENTRADA: El experimento de las babosas\n\nHe tenido éxito animando a las babosas. En lugar de disolver materia orgánica como carne o vegetación, pueden subsistir completamente con miel. Los abundantes desechos que producen se pueden fermentar en barricas, dando lugar a un hidromiel excepcionalmente potente y delicioso.\n\nSin embargo, si no se las contiene, las babosas tarde o temprano comienzan a buscar y consumir colmenas enteras. Durante el proceso, tienden a volverse más agresivas y a descontrolarse.\n\nNaturalmente, como respuesta a la amenaza, las abejas han adoptado una actitud más defensiva y es más difícil trabajar con ellas. Sin duda, en algún punto tendré que buscar una solución, no puedo simplemente reemplazar a las abejas.', '', 28153),
(144287, 'esES', '', 'Pohkiza...', 28153),
(144286, 'esES', '', 'El Dioh de la Sangre... lo reclama... todo...', 28153),
(144285, 'esES', '', '¡Ja, ja, ja!', 28153),
(144284, 'esES', '', 'Zuldazar... va a... caer...', 28153),
(144283, 'esES', '', '¡Gachaga!', 28153),
(144282, 'esES', '', 'Mih hermanah... me... vengarán...', 28153),
(144281, 'esES', '', 'Mi sangre... por... G\'huun.', 28153),
(144280, 'esES', '', '¡G\'huun!', 28153),
(144279, 'esES', '<Tsunga te gruñe de forma afectuosa>.', '', 28153),
(144278, 'esES', 'He venido de entre la bruma para alertar a la gente de Zandalar. La azerita ha dotado a los gorilas de una gran inteligencia. Y la inteligencia trae guerra.', '', 28153),
(144277, 'esES', 'Pohkiza...', '', 28153),
(144276, 'esES', 'El Dioh de la Sangre... lo reclama... todo...', '', 28153),
(144275, 'esES', 'Ya... hah... perdido...', '', 28153),
(144274, 'esES', 'Zuldazar... va a... caer...', '', 28153),
(144273, 'esES', '¡Gachaga!', '', 28153),
(144272, 'esES', '¡Mi vida por lah madreh!', '', 28153),
(144271, 'esES', 'Mi sangre... por... G\'huun.', '', 28153),
(144270, 'esES', '¡G\'huun!', '', 28153),
(144269, 'esES', 'Bien, bien. ¡Una vez más!', '', 28153),
(144268, 'esES', 'Ehtate quieto.', '', 28153),
(144266, 'esES', '', 'Ayudaré a reforzar las defensas de la aldea. ¡Te veo allí!', 28153),
(144265, 'esES', '', 'Los hemos rechazado. ¡Ven! Debemos hablar con el alcalde Royston.', 28153),
(144264, 'esES', '', 'Alleria suspira y frunce el ceño.', 28153),
(144263, 'esES', '<Quédate un rato y escucha>.', '<Quédate un rato y escucha>.', 28153),
(144262, 'esES', '', '<La mirada de Alleria pasa del frío rostro de piedra de la estatua a la placa grabada con su epitafio>.', 28153),
(144261, 'esES', '¡Firmes! ¡Mantendremos la posición!', '¡Firmes! ¡Mantendremos la posición!', 28153),
(144260, 'esES', 'Oyes un pequeño gemido con el último aliento de Rohn\'kor.', '', 28153),
(144259, 'esES', '', '¡Utilizaré tu tripa pa hacerme un sombrero nuevo!', 28153),
(144258, 'esES', '', '¡No! ¡Mi bebé!', 28153),
(144257, 'esES', '', '¡Deja de hacerle daño a esa preciosidad! ¡No saldráh de ehte agujero!', 28153),
(144256, 'esES', '', '¡Noh quieren muertoh! ¡Híncaleh el diente, mi mahcota!', 28153),
(144255, 'esES', '¡Bwonsamdi... ten piedad!', '¡Bwonsamdi... ten piedad!', 28153),
(144254, 'esES', 'Zandalar... eterno...', 'Zandalar... eterno...', 28153),
(144253, 'esES', '¡Vamoh a acabar contigo, Urok! Lo siento, pero tenemoh que hacerlo.', '', 28153),
(144252, 'esES', '¿Qué... qué son esah cosah que hay dentro de Urok?', '', 28153),
(144251, 'esES', '¡Ya casi ehtamoh lihtoh! Solo deja que me ponga ehto...', '', 28153),
(144250, 'esES', 'Así no...', 'Así no...', 28153),
(144249, 'esES', 'Bwonsamdi... viene... a por mí...', 'Bwonsamdi... viene... a por mí...', 28153),
(144248, 'esES', '¡Mantened la posición, se aproximan más hostiles!', '¡Mantened la posición, se aproximan más hostiles!', 28153),
(144247, 'esES', 'Mi... vida... por Zandalar...', 'Mi... vida... por Zandalar...', 28153),
(144245, 'esES', '¡Di chuka Zandalar!', '¡Di chuka Zandalar!', 28153),
(144243, 'esES', '¡Que no quede ninguno vivo!', '¡Que no quede ninguno vivo!', 28153),
(144242, 'esES', '¡Por el verdadero Zandalar!', '¡Por el verdadero Zandalar!', 28153),
(144240, 'esES', '¡Tu sangre cubrirá nuehtra tierra!', '¡Tu sangre cubrirá nuehtra tierra!', 28153),
(144239, 'esES', '¡Te enterraremoh!', '¡Te enterraremoh!', 28153),
(144238, 'esES', '¡Moriráh aquí!', '¡Moriráh aquí!', 28153),
(144237, 'esES', '¡Zandalar eterno!', '¡Zandalar eterno!', 28153),
(144236, 'esES', 'La Princesa dijo que buhcáramoh a loh monhtruoh. ¡Pero todoh son monhtruoh!', '', 28153),
(144235, 'esES', '¿Dónde ehtá el sol? No veo nada en ehte pantano mugriento.', '', 28153),
(144234, 'esES', '¡Ehto no tiene sentido! Veo un gran agujero. ¡No hay ningún agujero en ehte mapa!', '', 28153),
(144233, 'esES', '¡Vaya! Ehto eh... No eh... nada... Qué decepción.', '', 28153),
(144232, 'esES', '¡Taz\'okun! ¡Ehto parece un trozo de azerita!', '', 28153),
(144231, 'esES', '¿Qué eh ehto? Parece una aguja. Puaj. ¿Por qué eh tan pegajoso?', '', 28153),
(144230, 'esES', 'Hala, qué maravilla. Seguro que Talanji querría uno.', '', 28153),
(144229, 'esES', '¡Un ballestero hechizado se ha fijado en ti! ¡Evade!', '', 28153),
(144228, 'esES', 'No recibo muchos pedidos de espadas por aquí, pero me encanta hacerlas. ¡Aunque no puedo decir que me guste la razón por la que necesitamos tantas!', '', 28153),
(144227, 'esES', 'Entiendo por qué la gente tiene miedo de ehte pantano.', '', 28153),
(144226, 'esES', 'Qué ehtraño.', '', 28153),
(144225, 'esES', 'Creo que nunca podré sacarme ehta suciedad de lah manoh. Mih pobreh pergaminoh.', '', 28153),
(144224, 'esES', 'Que roca máh ehtraña... ¡Anda! ¡Se ha movido!', '', 28153),
(144223, 'esES', 'Fahcinante.', '', 28153),
(144222, 'esES', 'Que Gonk te guíe.', 'Que Gonk te guíe.', 28153),
(144221, 'esES', 'Que Pa\'ku te guarde.', 'Que Pa\'ku te guarde.', 28153),
(144220, 'esES', 'Que Rezan te dé fuerza.', 'Que Rezan te dé fuerza.', 28153),
(144219, 'esES', 'Ve con cuidado.', 'Ve con cuidado.', 28153),
(144218, 'esES', 'Compórtate en nuehtra ciudad.', 'Compórtate en nuehtra ciudad.', 28153),
(144217, 'esES', '¡Zandalar eterno!', '¡Zandalar eterno!', 28153),
(144216, 'esES', '¿Necesitah protección?', '¿Necesitah protección?', 28153),
(144215, 'esES', 'No encontaráh una oferta mejor.', 'No encontaráh una oferta mejor.', 28153),
(144214, 'esES', '¿Qué te trae por aquí?', '¿Qué te trae por aquí?', 28153),
(144213, 'esES', 'Saludoh.', 'Saludoh.', 28153),
(144209, 'esES', 'He jurado defender a la familia real.', 'He jurado defender a la familia real.', 28153),
(144208, 'esES', 'La defensa del reino eh sagrada.', 'La defensa del reino eh sagrada.', 28153),
(144201, 'esES', 'Comencemos.', 'Comencemos.', 28153),
(144200, 'esES', 'Estamos muy cerca, $n.$b$bEn cuanto des la orden, empezaré a buscar.$b$bAh, se me olvidaba. Nuestros adversarios han montado un campamento justo enfrente, en la playa. Yo vigilaría los alrededores por si nos preparan alguna emboscada.$b$b¡Confío en que me defiendas si nos atacan!', '', 28153),
(144199, 'esES', '¡Seguid así! ¡Estamos rechazando a esos malditos!', '', 28153),
(144198, 'esES', '¡Cae la noche! ¡Que no se apaguen las hogueras! Avisad si necesitáis más leña.', '', 28153),
(144197, 'esES', '¡Que no pase ningún monstruo! Hemos matado a ese behemoth, pero hemos perdido demasiados barcos.', '', 28153),
(144196, 'esES', 'Los que hayáis descansado, ¡relevad a los de la barricada! ¡Sobreviviremos a estos monstruos!', '', 28153),
(144195, 'esES', '¡Necesito voluntarios para ir a ver a Ashton! Quizás pueda crear unos explosivos.', '', 28153),
(144194, 'esES', '¡Que se alimente primero a los niños y después a los heridos!', '', 28153),
(144193, 'esES', '¡Los sanadores deben rotar y descansar! ¡Tú también, Krystin!', '', 28153),
(144192, 'esES', '¡Ayudad a reforzar la barricada! ¡Aprovechad todo lo que no esté clavado y, cuando acabéis con eso, empezad a sacar clavos!', '', 28153),
(144191, 'esES', 'El tragadín emite algunos chillidos extraños y se sacude los pies en el nenúfar.', '', 28153),
(144190, 'esES', 'Esos marineros deberían emplear su tiempo en vigilar a la Horda, no a nosotros.', 'Esos marineros deberían emplear su tiempo en vigilar a la Horda, no a nosotros.', 28153),
(144189, 'esES', 'Cuanto antes encontremos lo que estamos buscando y zarpemos, mejor.', 'Cuanto antes encontremos lo que estamos buscando y zarpemos, mejor.', 28153),
(144188, 'esES', '¡La Horda está cerca, mucho cuidado!', '¡La Horda está cerca, mucho cuidado!', 28153),
(144187, 'esES', 'Ojalá la Liga de Expedicionarios hubiera empleado a más gente en esta expedición.', 'Ojalá la Liga de Expedicionarios hubiera empleado a más gente en esta expedición.', 28153),
(144186, 'esES', 'Si no estuviéramos aquí para vigilar a los Hierro Negro, ¿quién sabe lo que harían?', 'Si no estuviéramos aquí para vigilar a los Hierro Negro, ¿quién sabe lo que harían?', 28153),
(144185, 'esES', '', '¡Y también sus pequeños! Puedo improvisar un fotomatón con peluches de dinosaurios. Te llevarías un porcentaje, por supuesto, Jangalar. 70-30 o algo así. A mi favor, ya que la idea es mía.', 28153),
(144184, 'esES', 'Otro necesita ayuda ahí delante, si ehtáh $gdihpuehto:dihpuehta;.', '', 28153),
(144183, 'esES', '', 'REUSE ME: Es hora de enfurecer a Ben\'jin con el inyector para luego seguirlo y ayudarlo a destruir a la especie invasora.', 28153),
(144182, 'esES', '¡Para cuando terminemos de cavar aquí, la Horda estará a medio camino de Forjaz!', '¡Para cuando terminemos de cavar aquí, la Horda estará a medio camino de Forjaz!', 28153),
(144181, 'esES', 'A los Hierro Negro nos da igual el calor. Pero esta humedad...', 'A los Hierro Negro nos da igual el calor. Pero esta humedad...', 28153),
(144180, 'esES', 'Desde luego, a la Liga de Expedicionarios le gusta tomarse su tiempo cavando, cuando hay una guerra que ganar.', 'Desde luego, a la Liga de Expedicionarios le gusta tomarse su tiempo cavando, cuando hay una guerra que ganar.', 28153),
(144179, 'esES', '¿Para esto nos fuimos de nuestra montaña?', '¿Para esto nos fuimos de nuestra montaña?', 28153),
(144178, 'esES', 'No hace falta tanto dramatismo.', '', 28153),
(144177, 'esES', '', 'Los arañazos... la limpieza desigual de la suciedad... Ay, ¿cómo lo vamos a mostrar ahora?', 28153),
(144176, 'esES', '¿En serio? ¿Tan mal ha estado?', '', 28153),
(144175, 'esES', '', '¡Espera!', 28153),
(144174, 'esES', '$gAmigo:Amiga;, por favor, acelera las cosas si quieres. Este dispositivo te será de utilidad.', '', 28153),
(144173, 'esES', '¿Satisfactorio? Señora, a este paso estaremos aquí todo el año.', '', 28153),
(144172, 'esES', '', 'Aaaaaah, maravilloso. ¿A que resulta satisfactorio?', 28153),
(144171, 'esES', '', 'Procura no dañar el fósil... Excelente.', 28153),
(144170, 'esES', '', 'Muy bien. Mantén el pulso firme.', 28153),
(144169, 'esES', '', '¡Andaos con cuidado, druidas! ¡Este lugar es una trampa mortal!', 28153),
(144168, 'esES', '¡Excelente trabajo! Deberíamos poder utilizarlo contra esas criaturas monstruosas de madera. Ah... Pero vigila que no se derrame.', '', 28153),
(144167, 'esES', 'Gracias por traérmela de vuelta.', '', 28153),
(144166, 'esES', '', 'RESUSE ME: Aquí tienes la caja para el artilugio inyector. Por favor, instálalo.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'esES', '', '¡Hola, papi!', 28153),
(144164, 'esES', '¡Penny! ¡Hija mía!', '', 28153),
(144163, 'esES', '¡Vuestro avance en el aserradero es solo temporal! ¡Pronto volverá a ser nuestro!', '', 28153),
(144162, 'esES', 'Vayamos a buscar a tu padre.', 'Vayamos a buscar a tu padre.', 28153),
(144161, 'esES', '', '¡Hola! ¿Cómo te llamas?', 28153),
(144160, 'esES', '¿No veis que estáis en grave peligro?', '¿No veis que estáis en grave peligro?', 28153),
(144159, 'esES', '¡No podéis detenernos a todos!', '¡No podéis detenernos a todos!', 28153),
(144158, 'esES', '¡Nunca nos encontraréis a todos!', '¡Nunca nos encontraréis a todos!', 28153),
(144157, 'esES', '¡Me han localizado!', '¡Me han localizado!', 28153),
(144156, 'esES', '¡Mira! ¡Hasta tienen uno de nuestros tambores!\n\n¿Quién dijo que los goblins no tenían cultura?', '', 28153),
(144153, 'esES', 'Ahora necesitaremos un par de gotas de savia volátil. ¡Ten cuidado de no agitar el tarro demasiado!', '', 28153),
(144152, 'esES', 'Añade un poco de azufre. ¡Cuidado con los gases!', '', 28153),
(144151, 'esES', 'Ahora añade cuidadosamente un poco de hogarita.', '', 28153),
(144150, 'esES', '¡Tenemos que añadir un poco de salitre para darle un poco de fuerza!', '', 28153),
(144148, 'esES', 'Krag\'wa asiente a tu compañero.', '', 28153),
(144147, 'esES', 'Krag\'wa y el joven tragadín parecen estar comunicándose.', '', 28153),
(144146, 'esES', '¡No! ¡Nunca volveré a esa celda! ¡NUNCA!', '', 28153),
(144145, 'esES', '', '¡Mantened el santuario! No debemos perder el control.', 28153),
(144144, 'esES', '¡Excelente! Te diré qué debes añadir al caldero. Sigue mis indicaciones o el resultado podría ser... explosivo.', '', 28153),
(144142, 'esES', '¡Adiós, Penny!', '', 28153),
(144141, 'esES', '', '¡Sí! ¡Nos vemos luego, Joe!', 28153),
(144140, 'esES', '', '¡Eh, Joe!', 28153),
(144139, 'esES', 'Hola, Penny. ¿Vas a ver a tu padre?', '', 28153),
(144138, 'esES', '¡¿Qué le pasa a todo el mundo?!', '', 28153),
(144137, 'esES', '', '¡Necesito sanación!', 28153),
(144136, 'esES', '', '¡Ríndete ante los elementos!', 28153),
(144135, 'esES', '$n, no puedo hacer nada para devolverlo a la normalidad. Sin embargo, tendrá una vida mejor si está contigo. Mantenlo a tu lado. Cuida de él.', '', 28153),
(144134, 'esES', 'Ya veo.', '', 28153),
(144133, 'esES', 'Acércate, joven.', '', 28153),
(144132, 'esES', 'Pesadilla...', '', 28153),
(144131, 'esES', 'La luna... ehtá saliendo...', '', 28153),
(144130, 'esES', 'Cohtah lejanah...', '', 28153),
(144129, 'esES', 'No remuevah... la olla...', '', 28153),
(144128, 'esES', 'Doh tragoh máh... y tu pimiento máh grande...', '', 28153),
(144127, 'esES', 'La montaña central... se derrumba...', '', 28153),
(144126, 'esES', 'Diez minutoh máh...', '', 28153),
(144125, 'esES', 'Aún no...', '', 28153),
(144124, 'esES', 'Slinky ruge de forma protectora.', '', 28153),
(144123, 'esES', '¡Enfréntate a la muerte!', '¡Enfréntate a la muerte!', 28153),
(144122, 'esES', 'Tu fin... es inevitable...', '', 28153),
(144121, 'esES', 'No obtendrás la victoria... Solo... la muerte...', '', 28153),
(144120, 'esES', 'Insignificante... frente... al... Vacío...', '', 28153),
(144119, 'esES', 'No... has conseguido... nada...', '', 28153),
(144118, 'esES', 'Los maestros... se revuelven...', '', 28153),
(144117, 'esES', 'El Vacío viene... a por todos...', '', 28153),
(144116, 'esES', 'Es inútil... La oscuridad lo consumirá todo...', '', 28153),
(144115, 'esES', '¡Encontrarán tu cadáver en el puerto!', '¡Encontrarán tu cadáver en el puerto!', 28153),
(144114, 'esES', '¡Kul Tiras no necesita a la Alianza!', '¡Kul Tiras no necesita a la Alianza!', 28153),
(144113, 'esES', '¡Te arrojaré a las olas!', '¡Te arrojaré a las olas!', 28153),
(144112, 'esES', '<Hacer cola para la Batalla de Stromgarde>', '<Hacer cola para la Batalla de Stromgarde>', 28153),
(144111, 'esES', 'Desde esta tabla puedes hacer cola para luchar en un frente de guerra.', '', 28153),
(144110, 'esES', '¡Katherine querría vernos ahogados a todos!', '¡Katherine querría vernos ahogados a todos!', 28153),
(144109, 'esES', 'Azeroth nos pertenece.', '', 28153),
(144108, 'esES', '¡El imperio renacerá!', '', 28153),
(144107, 'esES', '¡Encontradlos!', '', 28153),
(144106, 'esES', 'Se perderá... todo.', '', 28153),
(144105, 'esES', 'Todo caerá.', '', 28153),
(144104, 'esES', 'No hay esperanza... ni vida.', '', 28153),
(144103, 'esES', 'Todo será consumido.', '', 28153),
(144102, 'esES', 'La sombra lo invadirá todo.', '', 28153),
(144101, 'esES', 'El Vacío lo consume todo.', '', 28153),
(144100, 'esES', '', '¡Druidas de la Zarpa, al ataque!', 28153),
(144099, 'esES', '<Silbido>.', '', 28153),
(144097, 'esES', '', 'Toca \"plan B\"...', 28153),
(144096, 'esES', 'Tengo la información, ¡ahora solo falta escapar con ella!', '', 28153),
(144095, 'esES', '', '¡Estamos en peligro!', 28153),
(144094, 'esES', 'Sa-sa-sa-sa (ruido estático) sangre de Azeroth detectada. Núcleo de dat-dat-dat-dat datos no encontrado. Solicito instalación.', '', 28153),
(144093, 'esES', 'Uf. ¡Eh ahqueroso!', '', 28153),
(144092, 'esES', 'Jabari, tieneh la memoria de un elekk y el ingenio de Gonk.', '', 28153),
(144091, 'esES', 'Por supuehto, el \"picante\" y lah inyeccioneh de veneno mortal son lo mihmo, muy buena comparación...', '', 28153),
(144090, 'esES', '¡No necesito tuh cuidadoh, Jabari! ¡He sobrevivido al chili de Haw\'li!', '', 28153),
(144089, 'esES', 'Para ya. Ereh como un bruto con la garganta irritada.', '', 28153),
(144088, 'esES', 'Chitón, hermano. Toma ehto.', '', 28153),
(144087, 'esES', '¡Deja de fastidiar!', '', 28153),
(144086, 'esES', '¡Correcto! Veamos qué más...', '', 28153),
(144085, 'esES', '¡Se nota que no es la primera vez que practicas la alquimia!', '', 28153),
(144084, 'esES', '¡Bien hecho! Ahora necesitamos...', '', 28153),
(144082, 'esES', 'El primer disparo está cargado. Cuando empiece a disparar, se darán cuenta de que estamos aquí.$b$b¿Estás $gpreparado:preparada;?', '', 28153),
(144081, 'esES', 'Es solo cuestión de tiempo que vengan a investigar...', '', 28153),
(144080, 'esES', '', '¡Vale! ¡Vamos!', 28153),
(144079, 'esES', '', '¡Espera! ¡Tenemos que darnos la mano!', 28153),
(144078, 'esES', '¡La casa Valiente caerá!', '¡La casa Valiente caerá!', 28153),
(144077, 'esES', 'Mi muerte no evitará que la marea cambie.', 'Mi muerte no evitará que la marea cambie.', 28153),
(144076, 'esES', '¡Lo lamentarás!', '¡Lo lamentarás!', 28153),
(144075, 'esES', '¡No pintas nada aquí, $gforastero:forastera;!', '¡No pintas nada aquí, $gforastero:forastera;!', 28153),
(144074, 'esES', '¡Boralus nos pertenece!', '¡Boralus nos pertenece!', 28153),
(144073, 'esES', '', 'Hay muchah tropah de Zul de aquí a Atal\'Dazar. Tenemoh que eliminarlah.', 28153),
(144072, 'esES', 'Elfoh...', 'Elfoh...', 28153),
(144071, 'esES', 'El déspota Rastali escupe en el suelo.', 'El déspota Rastali suspira.', 28153),
(144070, 'esES', 'Pues claro. Es muy antiguo. Vale, en 3... 2... 1...', '', 28153),
(144069, 'esES', '', 'Asegúrate de que ese templo feo y gigantesco salga al fondo.', 28153),
(144068, 'esES', '', 'Nuestros amigos de Lunargenta se morirán de envidia cuando vean esta foto.', 28153),
(144067, 'esES', 'Con la prueba completada, le di la última pincelada a mi historia y regresé al reino material.', 'Con la prueba completada, le di la última pincelada a mi historia y regresé al reino material.', 28153),
(144066, 'esES', 'Captó mi atención y se introdujo en mi mente, proporcionándome el conocimiento necesario para invocarlo.', 'Captó mi atención y se introdujo en mi mente, proporcionándome el conocimiento necesario para invocarlo.', 28153),
(144065, 'esES', 'Terminó de formarse y gritó con vida nueva.', 'Terminó de formarse y gritó con vida nueva.', 28153),
(144064, 'esES', 'Con el ritual completado, vi una criatura tomar forma ante mis ojos.', 'Con el ritual completado, vi una criatura tomar forma ante mis ojos.', 28153),
(144063, 'esES', 'Cuando puse un pie en la habitación, descubrí que había cuatro runas repartidas por el suelo. La tinta tenía que ser para eso.', 'Cuando puse un pie en la habitación, descubrí que había cuatro runas repartidas por el suelo. La tinta tenía que ser para eso.', 28153),
(144062, 'esES', 'Cuando había recogido suficiente tinta, sentí que algo me atraía hacia el extremo de uno de los pasillos.', 'Cuando había recogido suficiente tinta, sentí que algo me atraía hacia el extremo de uno de los pasillos.', 28153),
(144061, 'esES', 'Un esqueleto del suelo me recordó que soy mortal. Me pregunté si otros se habrían enfrentado a esta prueba antes y habían fracasado.', 'Un esqueleto del suelo me recordó que soy mortal. Me pregunté si otros se habrían enfrentado a esta prueba antes y habían fracasado.', 28153),
(144060, 'esES', 'Los viscosos empezaban a ser bastante molestos.', 'Los viscosos empezaban a ser bastante molestos.', 28153),
(144059, 'esES', 'Los fangos eran la clave del acertijo. Y hasta ese momento, había ido encontrando todo lo que necesitaba.', 'Los fangos eran la clave del acertijo. Y hasta ese momento, había ido encontrando todo lo que necesitaba.', 28153),
(144058, 'esES', 'De algún modo, supe qué debía hacer. Decidí seguir adelante.', 'De algún modo, supe qué debía hacer. Decidí seguir adelante.', 28153),
(144057, 'esES', 'Cuidado con el azabache, reúne el carmesí, y tu asesino de sangre vinculada se alzará\".', 'Cuidado con el azabache, reúne el carmesí, y tu asesino de sangre vinculada se alzará\".', 28153),
(144056, 'esES', '\"Lo que derrama la pluma y lo que derraman las venas se entremezclan aquí dentro.', '\"Lo que derrama la pluma y lo que derraman las venas se entremezclan aquí dentro.', 28153),
(144055, 'esES', 'Me desperté en una cámara. Una extraña voz recitaba un poema dentro de mi cabeza.', 'Me desperté en una cámara. Una extraña voz recitaba un poema dentro de mi cabeza.', 28153),
(144054, 'esES', 'Empiezas a escribir en el libro: \"Cuando mi pluma tocó la página, empecé a sentir una atracción\".', 'Empiezas a escribir en el libro: \"Cuando mi pluma tocó la página, empecé a sentir una atracción\".', 28153),
(144053, 'esES', 'Examinas el libro entero y todas las páginas parecen vacías. Miras a Kronah con frustración y te preguntas si sabrá la clave de la prueba.', '', 28153),
(144052, 'esES', 'Estoy deseando leer sobre los acontecimientos a los que te enfrentarás.', '', 28153),
(144051, 'esES', 'Tú coge una de tus plumas y ponte a escribir. No te preocupes, el libro hará el resto.', '', 28153),
(144050, 'esES', 'Bueno, eso es fácil, encanto. Tendrás que escribir tu propia historia en el libro.', '', 28153),
(144049, 'esES', 'Oh, no, aquí viene...', '', 28153),
(144048, 'esES', 'Me gustaría intercambiar algunas de mis plumas.', 'Me gustaría intercambiar algunas de mis plumas.', 28153),
(144047, 'esES', 'Vaya, no ha salido según lo esperado. ¡Habrá que volver a intentarlo!', '', 28153),
(144046, 'esES', '¡La alquimia es una ciencia exacta! Intenta prestar más atención, por favor.', '', 28153),
(144045, 'esES', 'Vaya, no era así. ¡Tendremos que empezar de cero!', '', 28153),
(144044, 'esES', '¡La mezcla ha salido ardiendo! ¡Tenemos que empezar de nuevo!', '¡La mezcla ha salido ardiendo! ¡Tenemos que empezar de nuevo!', 28153),
(144043, 'esES', 'Zul predijo este día. ¡Luchar para cambiar el destino solo prueba que su verdad es inevitable!', '', 28153),
(144042, 'esES', 'Zul... nunca dijo... que perdería...', '', 28153),
(144041, 'esES', '¡Nunca llegaréis al precipicio a tiempo!', '', 28153),
(144040, 'esES', '¡Estoy listo para empezar!', '¡Estoy lista para empezar!', 28153),
(144039, 'esES', '¡Espera! ¡Ahora me encuentro mejor! Uf...', '¡Espera! ¡Ahora me encuentro mejor! Uf...', 28153),
(144038, 'esES', '¡Fui un idiota!', '¡Fui un idiota!', 28153),
(144037, 'esES', 'Ya no oigo su canción...', 'Ya no oigo su canción...', 28153),
(144036, 'esES', '¡Nunca te amará!', '¡Nunca te amará!', 28153),
(144035, 'esES', '¡Noooo, mi amor!', '¡Noooo, mi amor!', 28153),
(144034, 'esES', 'El amor duele.', 'El amor duele.', 28153),
(144033, 'esES', '¡Vale la pena!', '¡Vale la pena!', 28153),
(144032, 'esES', 'La separación provoca un dolor tan dulce...', 'La separación provoca un dolor tan dulce...', 28153),
(144031, 'esES', 'Encanto, mira cómo acabo con este tipo.', 'Encanto, mira cómo acabo con este tipo.', 28153),
(144030, 'esES', '¡¿Estás mirando a mi chica?!', '¡¿Estás mirando a mi chica?!', 28153),
(144029, 'esES', '¡El amor todo lo puede!', '¡El amor todo lo puede!', 28153),
(144028, 'esES', '¡Es mía! ¡MÍA!', '¡Es mía! ¡MÍA!', 28153),
(144027, 'esES', 'Gracias. Has salvado la aldea y me has infundido valor. Alby, Therold, ocupaos de que Puntamuelle se recupere. No tardaré en ponerme en contacto con vosotros.', '', 28153),
(144026, 'esES', '¡No la toques!', '¡No la toques!', 28153),
(144025, 'esES', '¡¿Que Zul quiere despertar a Dazar?! No me quedaré de brazos cruzados mientras ese \"profeta\" corrompe los huesos del primer Rey. Ven, adalid, y únete a nosotros en las puertas del sur de este lugar.', '', 28153),
(144024, 'esES', 'Debo volver a casa. Puede que mi tío y sus Sabiomar de Valle Canto Tormenta sepan algo sobre esta magia oscura.', '', 28153),
(144023, 'esES', 'Guardiaprofunda siempre fue inteligente, pero nunca pensé que jugaría con semejante magia. Que utilizaría un poder capaz de atemorizar así al océano.', '', 28153),
(144022, 'esES', '¡Atrás, está comprometida!', '¡Atrás, está comprometida!', 28153),
(144021, 'esES', '', '¡Sí! ¡Un hueco entre sus aniquiladoras celestiales! Crías, ¡volad y masacrad a esos herejes!', 28153),
(144020, 'esES', 'Puntamuelle está a salvo, pero tengo miedo. Guardiaprofunda siempre fue inteligente, pero antes no poseía este tipo de poder.', '', 28153),
(144019, 'esES', '¡Yo te protegeré, amor mío!', '¡Yo te protegeré, amor mío!', 28153),
(144018, 'esES', '¡La quiero tanto...!', '¡La quiero tanto...!', 28153),
(144017, 'esES', 'LA MANO DEL DESTINO ESTÁ SACIADA, TE LLEVARÉ A LUGAR SEGURO. A VECES EL DESTINO ES BENEVOLENTE.', '', 28153),
(144016, 'esES', '¡Abandona nuehtra ciudad, $p! ¡Noh condenaráh a todoh!', '', 28153),
(144015, 'esES', '¡Dejad paso a quien han bendecido loh loa!', '', 28153),
(144013, 'esES', '', 'Loh presagioh ehtán mezcladoh... Te enfrentaráh a desafíoh imposibleh, pero loh superaráh. Loh loa no te abandonarán.', 28153),
(144012, 'esES', '', 'Me temo que son todoh maloh presagioh... Habrá problemah sin fin en tu futuro. Lo siento.', 28153),
(144011, 'esES', '', 'Evita el agua hoy. Eh peligrosa.', 28153),
(144010, 'esES', '', '¿Vacío? No... Tieneh que cambiar eso.', 28153),
(144009, 'esES', '', 'Tendráh que soportar traicioneh y grandeh dificultadeh. Elige a tuh compañeroh con cuidado hoy.', 28153),
(144008, 'esES', '', 'No he oído ehte presagio en mucho, mucho tiempo... Debeh cambiar tu dehtino.', 28153),
(144007, 'esES', '', 'No tomeh atajoh pa conseguir tuh metah hoy. Cualquier riehgo o dehcuido te conducira a un final ehpantoso.', 28153),
(144006, 'esES', '', 'Una advertencia del otro lado. Ten cuidado.', 28153),
(144005, 'esES', '', 'Cuidado con la ciudad de oro. No merece la pena arriehgarse.', 28153),
(144004, 'esES', '', 'Me temo que debeh caminar a ciegah hacia tu futuro.', 28153),
(144003, 'esES', '', 'Una mano invisible arrahtra a Gral hacia lah profundidadeh.', 28153),
(144002, 'esES', '', 'El nido de Shadra está vacío.', 28153),
(144001, 'esES', '', 'Torcali duerme.', 28153),
(144000, 'esES', '', 'Rezan cae al suelo... muerto.', 28153),
(143999, 'esES', '', 'Bwonsamdi ofrece un trato con una sonrisa pícara.', 28153),
(143998, 'esES', '', 'Krag\'wa se traga una manada de cuernoatroceh azuleh.', 28153),
(143997, 'esES', '', 'Gonk está solo, nadando por un río de oro.', 28153),
(143996, 'esES', '', 'Pa\'ku cierra loh ojoh en la ohcuridad.', 28153),
(143995, 'esES', '', 'Hay pocoh presagioh tan indeseableh como ehte. Ve con cuidado.', 28153),
(143994, 'esES', '', 'Un presagio ohcuro pa todoh nosotroh. ¿Qué hah traído a nuehtrah cohtah?', 28153),
(143993, 'esES', '', 'Ehtáh malgahtando tu potencial. Afronta lah oportunidadeh que se te presentan o caeráh en el olvido entre montoneh de muertoh sin nombre.', 28153),
(143992, 'esES', '', 'La división entre tuh aliadoh y tú eh una amenaza pa todoh. Debeh unir Zandalar.', 28153),
(143991, 'esES', '', 'Un presagio aciago, pero que se puede superar con fuerza y determinación.', 28153),
(143990, 'esES', '', 'Loh lídereh divididoh no son lídereh en absoluto. Si no colaborah con tuh rivaleh, sufriráh lah consecuenciah.', 28153),
(143989, 'esES', '', 'Se alza una ohcuridad que consumirá hahta al máh fuerte de nosotroh. $gIncluido:Incluida; tú.', 28153),
(143988, 'esES', '', 'Un presagio ohcuro pa todoh nosotroh...', 28153),
(143987, 'esES', '', 'La muerte de un nuevo amigo.', 28153),
(143986, 'esES', '', 'Un sol poniente en loh pantanoh ohcuroh de Nazmir.', 28153),
(143985, 'esES', '', 'Un jarrón agrietado del que gotea vino.', 28153),
(143984, 'esES', '', 'Dos sacerdotes matándose el uno al otro.', 28153),
(143983, 'esES', '', 'Un barco humano que llega a nuestras costas...', 28153),
(143982, 'esES', '', 'Un trono de hielo y fuego destrozado...', 28153),
(143981, 'esES', '', 'Un brutosaurio ahogándose en sangre.', 28153),
(143980, 'esES', '', 'Un río de sangre, con cadáveres flotando corriente arriba...', 28153),
(143979, 'esES', '¡Venga, Arañazos! ¡Vamos!', '¡Venga, Arañazos! ¡Vamos!', 28153),
(143978, 'esES', '¡Yupi! ¡Gracias!', '¡Yupi! ¡Gracias!', 28153),
(143977, 'esES', 'Ah. ¡Mucho mejor!', '', 28153),
(143976, 'esES', 'Loh animé a marcharnoh, pero tenían que ver uno máh... Apenah pude ehcapar... De no ser por ti, no lo habría contado.', '', 28153),
(143975, 'esES', '', '¡Habla a travéh de tu receptora, Zetoa!', 28153),
(143974, 'esES', '', '¡Habla a travéh de tu receptora, Iluna!', 28153),
(143973, 'esES', '', 'Ehtamoh lihtoh. Llenad a mih receptoreh y reveladnoh el futuro.', 28153),
(143972, 'esES', '', 'Ehpírituh de loh muertoh, ehpírituh de loh loa, ehpírituh de loh perdidoh y preocupadoh, ¡atended mi llamada!', 28153),
(143971, 'esES', '¡Vuelvo a la línea de defensa!', '¡Vuelvo a la línea de defensa!', 28153),
(143970, 'esES', '¡No podía moverme!', '¡No podía moverme!', 28153),
(143969, 'esES', '¡Creí que iban a arrastrarme al bosque!', '¡Creí que iban a arrastrarme al bosque!', 28153),
(143968, 'esES', '¡Ya se han llevado gente al bosque!', '¡Ya se han llevado gente al bosque!', 28153),
(143967, 'esES', '¡Regresaré a la barricada!', '¡Regresaré a la barricada!', 28153),
(143966, 'esES', '', 'Son todoh buenoh presagioh pa ti... ¡Actúa con atrevimiento hoy!', 28153),
(143965, 'esES', '¡Creí que había llegado mi hora!', '¡Creí que había llegado mi hora!', 28153),
(143964, 'esES', '¡Gracias!', '¡Gracias!', 28153),
(143963, 'esES', '', 'Una estampida...', 28153),
(143962, 'esES', '', 'Un presagio de alegría... Que no te abrume la ansiedad. La felicidad y el humor te guiarán hacia el éxito.', 28153),
(143961, 'esES', '¡El añublo se ehparce!', '', 28153),
(143960, 'esES', 'Todo... se marchita...', '', 28153),
(143959, 'esES', '', 'La bendición máh habitual de Shadra, con un añadido inehperado. Sigue siendo algo bueno, pero no lo entiendo del todo.', 28153),
(143958, 'esES', '', 'La bendición del defensor... Salvaráh muchah vidah, pero tal vez tengah que sacrificar la tuya.', 28153),
(143957, 'esES', '', 'El loa del rey eh un presagio poco común. Grande y poderoso. Dehtruiráh a loh enemigoh del rey.', 28153),
(143956, 'esES', '', 'Un buen presagio de una vida larga y una muerte dulce.', 28153),
(143955, 'esES', '¡Debo alimentarme!', '', 28153),
(143954, 'esES', '¡Marchitaoh!', '', 28153),
(143953, 'esES', '¡La corrupción florece!', '', 28153),
(143952, 'esES', '', 'Si esa ihla no eh tu hogar, eh un buen presagio.', 28153),
(143951, 'esES', '¡Creced!', '', 28153),
(143950, 'esES', '', 'Siempre lucharáh junto a tuh aliadoh. Gonk permanecerá a tu lado cuando máh lo necesiteh.', 28153),
(143949, 'esES', '', 'Pa\'ku te guiará en tu viaje y mantendrá a loh enemigoh lejoh...', 28153),
(143948, 'esES', 'Tierra fértil...', '', 28153),
(143947, 'esES', '', 'Gral salta sobre la flota del rey...', 28153),
(143946, 'esES', '', 'Los huevos de Shadra eclosionan. Innumerables ojos empiezan a aparecer...', 28153),
(143945, 'esES', '', 'Torcali erguido en la cima de una montaña, solo...', 28153),
(143944, 'esES', '', 'Rezan da un pisotón y los trols de sangre se desperdigan...', 28153),
(143943, 'esES', '', 'Bwonsamdi aparta la mirada...', 28153),
(143942, 'esES', '', 'Krag\'wa se traga una ihla...', 28153),
(143941, 'esES', 'Supura...', '', 28153),
(143940, 'esES', '', 'Gonk corre junto a su manada...', 28153),
(143939, 'esES', '¡A cosechar!', '', 28153),
(143938, 'esES', '¡La corrupción debe propagarse!', '', 28153),
(143937, 'esES', '', 'Casi siempre eh un buen presagio, pero depende de tu camarada...', 28153),
(143936, 'esES', '', 'Un buen presagio pa todoh nosotroh. Tu presencia debería ser bienvenida en Zandalar.', 28153),
(143935, 'esES', '', 'Al contrario de lo que muchoh piensan, aún no hah alcanzado tu máximo potencial. Tu poder crecerá y superaráh todah lah ehpectativah.', 28153),
(143934, 'esES', '', 'Un... presagio sorprendente pa $gun forahtero:una forahtera;. ¿Qué significa?', 28153),
(143933, 'esES', '', '¡Un poderoso presagio! Ehto pinta bien pa ti...', 28153),
(143932, 'esES', '', 'Un buen presagio de la ehpansión y crecimiento de nuehtra gente. Muy interesante que se te conceda a ti...', 28153),
(143931, 'esES', '', 'Un buen presagio de prohperidad y legado.', 28153),
(143930, 'esES', '', 'Un buen presagio de fuerza, poder y éxito.', 28153),
(143929, 'esES', '', 'La resurrección de un antiguo amigo...', 28153),
(143928, 'esES', '', 'Un sol naciente sobre aguas doradas...', 28153),
(143927, 'esES', '', 'Un huevo enorme que se agita con fuerza, pero no eclosiona...', 28153),
(143926, 'esES', '', 'Todah lah tribuh trolh, reunidah bajo el ehtandarte Zandalari...', 28153),
(143925, 'esES', '', 'Una cabeza de elfo cercenada...', 28153),
(143924, 'esES', '', 'Aguas ancestrales, inalteradas durante generaciones...', 28153),
(143923, 'esES', '', 'Máscaras de oro...', 28153),
(143922, 'esES', '', 'La sombra de Pa\'ku cruza un camino de piedra...', 28153),
(143921, 'esES', '', 'Muy bien. Veamoh lo que loh ehpírituh tienen que decirte...', 28153),
(143920, 'esES', '', '¿Seguro que quiereh saberlo, $p?\n\nNo todoh loh dehtinoh ehtán llenoh de grandeh hazañah y finaleh feliceh...', 28153),
(143919, 'esES', 'No tengo miedo. Dime qué ves en mi futuro.', 'No tengo miedo. Dime qué ves en mi futuro.', 28153),
(143918, 'esES', '¿Qué ves en mi futuro?', '¿Qué ves en mi futuro?', 28153),
(143917, 'esES', '', 'Oíd mi llamada, ehpírituh perdidoh y antiguoh. Llenad a mih receptoreh y reveladnoh el futuro.', 28153),
(143916, 'esES', 'Da igual. Estamos en todas partes... bajo tus pies.', '', 28153),
(143915, 'esES', 'Eres débil... Nuestra tribu... se fortalece.', 'Eres débil... Nuestra tribu... se fortalece.', 28153),
(143914, 'esES', '', '$gBienvenido:Bienvenida; al Salón del Ehpíritu Perdido, $p.\n\nLlegah tarde. No ehtaba segura de que pudierah venir.\n\nDime, ¿qué puede hacer la señora Konawla hoy por ti?', 28153),
(143913, 'esES', 'Muero bien.', 'Muero bien.', 28153),
(143912, 'esES', '¡Nuestras espinas cubrirán la tierra!', '¡Nuestras espinas cubrirán la tierra!', 28153),
(143911, 'esES', 'Los Lomozarza... seguirán fortaleciéndose...', 'Los Lomozarza... seguirán fortaleciéndose...', 28153),
(143910, 'esES', 'Mi camino... acaba.', 'Mi camino... acaba.', 28153),
(143909, 'esES', 'Tu muerte me otorga gloria.', 'Tu muerte me otorga gloria.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'esES', 'Tu sangre fortalecerá mis espinas.', 'Tu sangre fortalecerá mis espinas.', 28153),
(143907, 'esES', '¡Jamás nos rendimos!', '¡Jamás nos rendimos!', 28153),
(143906, 'esES', '¿Por qué está el Compendio de derramamiento de sangre en blanco?', '¿Por qué está el Compendio de derramamiento de sangre en blanco?', 28153),
(143905, 'esES', 'Alimentarás a nuestros jabalíes.', 'Alimentarás a nuestros jabalíes.', 28153),
(143904, 'esES', '¡Nadie puede detenernos!', '¡Nadie puede detenernos!', 28153),
(143903, 'esES', '¡Reclamamos esta tierra!', '¡Reclamamos esta tierra!', 28153),
(143902, 'esES', 'Empezar a escribir en el libro.', 'Empezar a escribir en el libro.', 28153),
(143901, 'esES', 'Hojear todo el libro.', 'Hojear todo el libro.', 28153),
(143900, 'esES', '¡Arañaaazooos! ¿Sigues ahí arriba? Si me oyes, ¡maúlla dos veces!', '¡Arañaaazooos! ¿Sigues ahí arriba? Si me oyes, ¡maúlla dos veces!', 28153),
(143899, 'esES', 'Las páginas siguientes también parecen estar en blanco.', '', 28153),
(143898, 'esES', '¡Te vamos a bajar, Arañazos, pero pórtate bien!', '¡Te vamos a bajar, Arañazos, pero pórtate bien!', 28153),
(143897, 'esES', '¡Todo irá bien, Arañazos! ¡Espera ahí!', '¡Todo irá bien, Arañazos! ¡Espera ahí!', 28153),
(143896, 'esES', 'Pasar unas cuantas páginas más.', 'Pasar unas cuantas páginas más.', 28153),
(143895, 'esES', 'Parece que las páginas del libro están en blanco.', '', 28153),
(143894, 'esES', 'MiiAUUuu.', '', 28153),
(143893, 'esES', '¡Aguanta, Arañazos! ¡La ayuda está en camino!', '¡Aguanta, Arañazos! ¡La ayuda está en camino!', 28153),
(143892, 'esES', '¡Baja aquí, Arañazos! ¡Es peligroso que estés ahí arriba!', '¡Baja aquí, Arañazos! ¡Es peligroso que estés ahí arriba!', 28153),
(143891, 'esES', '¡Salta, Arañazos! ¡Yo te cojo!', '¡Salta, Arañazos! ¡Yo te cojo!', 28153),
(143890, 'esES', '¡Arañaaazooos! ¡Baja!', '¡Arañaaazooos! ¡Baja!', 28153),
(143889, 'esES', '', '¡Te daré de comer a mih mahcotah, $r!', 28153),
(143888, 'esES', '¡Aquí, adalid!', '', 28153),
(143887, 'esES', '¡Aquí!', '', 28153),
(143886, 'esES', '¡Cuidado!', '', 28153),
(143885, 'esES', 'Por aquí.', '', 28153),
(143884, 'esES', 'Por aquí.', '', 28153),
(143883, 'esES', '¡Cuidado!', '', 28153),
(143882, 'esES', '¡Aquí!', '', 28153),
(143881, 'esES', 'Tú, ¡aquí!', '', 28153),
(143879, 'esES', '¡Purgar!', '', 28153),
(143876, 'esES', 'Ya está.', '', 28153),
(143875, 'esES', '¡Sangre! ¡Sangre! ¡Sangre!', '', 28153),
(143874, 'esES', '¡Zuldazar caerá!', '', 28153),
(143873, 'esES', '¡Carne frehca!', '', 28153),
(143872, 'esES', '¡Quiero tu sangre!', '', 28153),
(143871, 'esES', '¡Tuh huesoh me servirán!', '', 28153),
(143870, 'esES', '¡Tu sangre eh pa G\'huun!', '', 28153),
(143869, 'esES', '¡Nadie puede ehconderse del Dioh de la Sangre!', '', 28153),
(143868, 'esES', '¡Guzincha!', '', 28153),
(143867, 'esES', '¡Kachago!', '', 28153),
(143865, 'esES', '¿No has leído la letra pequeña, $gchico:chica;?\n\nNada de reembolsos. Sin excepciones. Y nada de lloriqueos.\n\nYa sé lo que te levantará el ánimo... ¡Una caída divertida de Piesplumas!', '', 28153),
(143864, 'esES', '¡Una caída divertida de Piesplumas, por favor!', '¡Una caída divertida de Piesplumas, por favor!', 28153),
(143863, 'esES', 'Quiero un reembolso.', 'Quiero un reembolso.', 28153),
(143862, 'esES', '¡$gBienvenido:Bienvenida; de nuevo, $p!\n\nSin duda habrás disfrutado tu tiempo con la familia de las caídas divertidas de Piesplumas.\n\nComo miembro de pleno derecho tienes acceso a un número ilimitado de caídas lentas desde este divertido zigurat. ¡Avísame cuando quieras más!\n\nNo se admiten reembolsos.', '', 28153),
(143861, 'esES', '¡Únete hoy mismo a la familia de las caídas divertidas de Piesplumas!\n\nPor una única tarifa reducida tendrás acceso a caídas lentas ilimitadas desde la cima de este zigurat. ¡Supervivencia garantizada!\n\nNada de reembolsos.', '', 28153),
(143860, 'esES', 'Aquí arriba los vientos son más fuertes que en Monte Alto. Nuestra decisión de unirnos a la Horda ya está dando frutos.', '', 28153),
(143859, 'esES', 'Regresad a la tormenta y encontrad la paz. Fluid por el santuario para que podamos compartir vuestra fuerza.', '', 28153),
(143858, 'esES', '', 'Qué ciudad más maravillosa. ¡Explorar el mundo es tan divertido!', 28153),
(143857, 'esES', 'Escuchad la llamada, caídos. Hoy se perdonan vuestros malos actos.', '', 28153),
(143856, 'esES', 'Cuando esté todo listo, libera las almas de la campana.', '', 28153),
(143855, 'esES', 'Rosaline, lo siento, pero la cacería tendrá que esperar. Tenemos asuntos más importantes de los que ocuparnos hoy.', '', 28153),
(143854, 'esES', '', '¡Eh! ¡Therold! Basta de perder el tiempo. ¡Necesitamos tu bendición para salir a cazar!', 28153),
(143853, 'esES', '¡Vuelve pronto, $p!', '', 28153),
(143852, 'esES', '¡Diez puntos por escupir a cualquier trol de sangre que veas!', '', 28153),
(143851, 'esES', '¡Caídas divertidas de Piesplumas! ¡Cuéntaselo a tus amigos!', '', 28153),
(143850, 'esES', 'Me alegro de volver a verte, $p. ¡Disfruta de las caídas!', '', 28153),
(143849, 'esES', '¡Intenta aterrizar sobre el brutosaurio!', '', 28153),
(143848, 'esES', '¡Intenta aterrizar en una cascada!', '', 28153),
(143847, 'esES', '¡Cuidado con los pterrordáctilos!', '', 28153),
(143846, 'esES', 'Buen viaje, $p.', '', 28153),
(143845, 'esES', '¡Aaaayyy!', '', 28153),
(143844, 'esES', 'Por la Alianza.', '', 28153),
(143843, 'esES', '¡Por la Horda!', '', 28153),
(143842, 'esES', 'Stromgarde ha caído. Ríndete ahora, Rogerh, y salva el pellejo.', '', 28153),
(143841, 'esES', 'Claro que sí, ahí está... ¡mi martillo!', '', 28153),
(143840, 'esES', 'Toc, toc, pequeño Barbabronce. ¿Hay alguien en casa?', '', 28153),
(143839, 'esES', 'La Luz aún me acompaña. ¡No caeré tan fácilmente!', '', 28153),
(143838, 'esES', '¡Almirante Rogers! Hemos asaltado tu fortaleza. ¿Dónde está tu venganza ahora, paladín?', '', 28153),
(143837, 'esES', '¿Se creen que un puñado de soldadoh a caballo noh van a detener? ¡Ja! ¡Demohtradleh de lo que ehtá hecha la Horda!', '', 28153),
(143836, 'esES', 'Hay que reforzar el bahtión. ¡Dehtruid esoh tanqueh anteh de que se acerquen demasiado!', '', 28153),
(143835, 'esES', 'Nuestras defensas siguen siendo débiles. ¡Tropas de la Horda, volved a la base y defended nuestra posición!', '', 28153),
(143834, 'esES', 'Muy bien. Si queréis guerra, guerra tendréis. ¡Enviad un batallón montado a acabar con ellos!', '', 28153),
(143833, 'esES', 'Ahora el Círculo de loh Elementoh lo controla la Horda.', '', 28153),
(143832, 'esES', 'Finca Nueva eh nuehtra... Y ahora tenemoh jineteh de loboh.', '', 28153),
(143831, 'esES', '¡El arsenal ehtá lihto, colega!', '', 28153),
(143830, 'esES', 'El taller ehtá lihto. ¡Nuehtroh demoledoreh acabarán pronto con loh muroh de la Alianza!', '', 28153),
(143829, 'esES', 'Máquinas de asedio, ¡al ataque!', '', 28153),
(143828, 'esES', 'Se os avisó, escoria de la Horda. Ahora preparaos para ser aniquilados.', '', 28153),
(143827, 'esES', 'Ehtah tierrah pertenecían a loh trolh anteh de que la Alianza supiera de su exihtencia, Turalyon.', '', 28153),
(143826, 'esES', 'Mmm. Te queda perfecto.', '', 28153),
(143825, 'esES', 'Habrá que apañarse con esas ropas por ahora.', '', 28153),
(143824, 'esES', 'Lo primero eh lo primero. Necesitamoh madera y hierro pa ehtablecer una base pa la Horda. Seguro que loh encuentrah cerca.', '', 28153),
(143823, 'esES', 'Yo también, Muradin.', '', 28153),
(143822, 'esES', 'Tal vez estas prendas te ayuden a mejorar tu habilidad de recolección.', '', 28153),
(143821, 'esES', '¡Bah! ¡Puedes tragarte tu venganza, Turalyon!', '', 28153),
(143820, 'esES', '¡Esto es territorio de la Alianza! ¡La venganza caerá sobre esos invasores de la Horda!', '', 28153),
(143819, 'esES', '¡Hoy pertenece a la Horda!', '', 28153),
(143818, 'esES', 'En el pasado, toda ehta tierra pertenecía a loh trolh.', '', 28153),
(143817, 'esES', 'Aah... con mucho gusto, chaval. Te has metido con el enano equivocado.', '', 28153),
(143816, 'esES', '¡Muradin! ¡Muéstrate, cobarde!', '', 28153),
(143815, 'esES', 'Nuestras defensas siguen siendo débiles. ¡Detened a esos tanques antes de que lleguen a la base!', '', 28153),
(143814, 'esES', '¡Ni la mitad de fea que la tuya, Barbabronce!', '', 28153),
(143813, 'esES', 'Perdóname, examinadora.', '', 28153),
(143812, 'esES', 'Es un honor servirte, examinadora.', '', 28153),
(143811, 'esES', '', 'La batalla ha terminado... y seguimoh con vida. ¡Ateena pagará por su locura!', 28153),
(143810, 'esES', '', '¡Contemplad al dehtructor de Zuldazar! Ehpero que intentéih detenernoh... ¡Quiero que sufráih!', 28153),
(143809, 'esES', '', 'Tanto ehfuerzo... ¡solo pa caer ante la furia del maehtro!', 28153),
(143808, 'esES', 'Trabajar para el Relicario es agotador...', '', 28153),
(143807, 'esES', 'Je, ¡estaba tirado! A ver cómo te defiendes en el campo. Siempre nos viene bien más madera.', '', 28153),
(143806, 'esES', 'Como quieras, examinadora.', '', 28153),
(143805, 'esES', 'Te serviré en lo que pueda, examinadora.', '', 28153),
(143804, 'esES', 'Encantado de ayudar, examinadora.', '', 28153),
(143803, 'esES', '', '¡Mi maehtro usará tu cuerpo como recipiente!', 28153),
(143802, 'esES', '', 'La Horda será la siguiente en caer. ¡Pagaréih por matar a Hir\'eek! No podéih huir.', 28153),
(143801, 'esES', '', 'Zuldazar caerá... ¡y mi maehtro pronto será libre! ¡Vuehtroh débileh loa no pueden impedirlo!', 28153),
(143800, 'esES', 'Por supuesto, examinadora.', '', 28153),
(143799, 'esES', 'Ya voy, examinadora.', '', 28153),
(143798, 'esES', '', 'Interesante... Baeloth, ven a echar un vistazo y dime qué ves.', 28153),
(143797, 'esES', '', '¿Adónde habías ido, Baeloth? Tengo más ideas valiosas para que las escribas.', 28153),
(143796, 'esES', '', 'Mi querido Baeloth, ven a ver esto.', 28153),
(143795, 'esES', '', 'En el Relicario no hay tiempo para descansar, Baeloth.', 28153),
(143794, 'esES', '', '¡Baeloth, no toques los artefactos!', 28153),
(143793, 'esES', '', 'Es maravilloso... ¡Baeloth, ven a ver lo maravilloso que es!', 28153),
(143792, 'esES', '', 'El ehcudo de Hezrel ehta activo, ¡métete dentro!', 28153),
(143791, 'esES', '', 'Baeloth, ¿otra vez soñando despierto? Me vendría bien tu ayuda aquí.', 28153),
(143790, 'esES', '', 'Baeloth, sé bueno y transcribe todo lo que diga.', 28153),
(143789, 'esES', '¡Las vintas necesitan muchos suministros para seguir rindiendo al máximo nivel! Mi trabajo es localizar y reabastecer las reservas, además de reparar artilugios y cacharros averiados.$b$b...$b$bSe cargan muchos al día.$b$bNo es que sean precisamente gente delicada.', '', 28153),
(143788, 'esES', '', '¿Podemos hablar un momento? Necesito tu ayuda.', 28153),
(143787, 'esES', '<< Se desarrolla un evento en el que yo y los trabajadores caminamos hacia el paso elevado con cañones >>.', '', 28153),
(143786, 'esES', 'Tengo paz para todos. Tengo paz para tos. Tengo paz par\' tos. Ten paz par\' tos. Ten paar\' tos. T\'paartos. T\'paartos. ¡T\'paartos!', '', 28153),
(143785, 'esES', 'Parece ser que mi engaño ha surtido efecto. Resulta inaudito que hayan llegado a creer que alguien como yo pudiera ser tan simple y... ¿Qué? ¿Que pueden oírme? Esto... ¡T\'paartos!', '', 28153),
(143784, 'esES', 'Lista de cosas que no le gustan a T\'paartos: serpientes, niños crueles, serpientes, cuevas oscuras, serpientes... Y piltrafas que molestan a T\'paartos.', '', 28153),
(143783, 'esES', '¡Claro que T\'paartos ha leído libros! Libros con pocas palabras y muchos dibujos, pero siguen siendo libros.', '', 28153),
(143782, 'esES', 'Piltrafa no estará intentando aprovecharse de la bondad de T\'paartos... ¿no?', '', 28153),
(143781, 'esES', 'A T\'paartos le siguen dando un poco de miedo las serpientes.', '', 28153),
(143780, 'esES', '¡T\'paartos está orgulloso de ser un forjado por la Luz!', '', 28153),
(143779, 'esES', 'Vuelve a hablar con T\'paartos cuando quieras.', '', 28153),
(143778, 'esES', 'T\'paartos debe volver al trabajo.', '', 28153),
(143777, 'esES', 'T\'paartos tiene mucho que hacer.', '', 28153),
(143776, 'esES', 'T\'paartos te volverá a ver pronto.', '', 28153),
(143775, 'esES', 'T\'paartos.', '', 28153),
(143774, 'esES', 'Date prisa, $n. Hay vidas en juego.', '', 28153),
(143773, 'esES', '¡T\'paartos está listo!', '', 28153),
(143772, 'esES', 'Que la Luz esté contigo.', '', 28153),
(143771, 'esES', '¿Peligro? ¡T\'paartos se ríe del peligro!', '', 28153),
(143770, 'esES', '¿Piltrafa necesita algo de T\'paartos?', '', 28153),
(143769, 'esES', 'T\'paartos saluda a piltrafa.', '', 28153),
(143768, 'esES', '¿T\'paartos?', '', 28153),
(143767, 'esES', '¡T\'paartos!', '', 28153),
(143766, 'esES', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s empieza a lanzar |cFFFF0000|Hspell:259610|h[Apocalipsis sangriento]|h|r. ¡Ponte a cubierto!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s empieza a lanzar |cFFFF0000|Hspell:259610|h[Apocalipsis sangriento]|h|r. ¡Ponte a cubierto!', 28153),
(143765, 'esES', '', '¡Luchad! ¡Vuehtro dolor alimenta a mi maehtro!', 28153),
(143764, 'esES', '¿Jaina? ¡Querrás decir \"Sosaina\"! ¿Modera? Más bien... Eh... Nada. Se me han acabado las ideas.', '', 28153),
(143763, 'esES', '¿El archimago Khadgar? ¡Deberían llamarlo \"el archiyayo Khadgar\"! ¿Eh?', '', 28153),
(143762, 'esES', '¿Los magos del Kirin Tor? ¡Más bien \"los vagos del Kirin Tor\"! ¿Eh?', '', 28153),
(143761, 'esES', 'Si hicierais lo que yo digo en lugar de intentar pensar por vosotros mismos, Azeroth sería un lugar mejor.', '', 28153),
(143760, 'esES', 'Sería una insensatez oponerse a nosotros.', '', 28153),
(143759, 'esES', 'Por Quel\'Thalas.', '', 28153),
(143758, 'esES', 'Superamos tantas adversidades...', '', 28153),
(143757, 'esES', 'Construimos nuestro futuro sobre los cimientos de nuestras tradiciones.', '', 28153),
(143756, 'esES', 'Sigue con tus asuntos.', '', 28153),
(143755, 'esES', 'Nuestros asuntos son cosa nuestra.', '', 28153),
(143754, 'esES', 'Respeta nuestras costumbres.', '', 28153),
(143753, 'esES', 'El sol eterno aún nos guía.', '', 28153),
(143752, 'esES', '¿Qué necesitas?', '', 28153),
(143751, 'esES', 'Sirvo a Lunargenta.', '', 28153),
(143750, 'esES', 'Estoy muy ocupado.', '', 28153),
(143749, 'esES', 'No malgastes recursos.', '', 28153),
(143748, 'esES', '¿Qué pasa?', '', 28153),
(143747, 'esES', 'Debemos proteger la Fuente del Sol.', '', 28153),
(143746, 'esES', 'Toma esto como muestra de agradecimiento.', '', 28153),
(143745, 'esES', '', '¿Planes? ¿Yo? No sé de qué me hablas...', 28153),
(143744, 'esES', '', '¿Creías que no me iba a dar cuenta de cómo miras a mis forestales oscuras? Te sugiero que busques otro objetivo para tus miradas y pensamientos.', 28153),
(143743, 'esES', '', 'He estado observando tu progreso... Y voy a tener que enviarte a Nathanos para un entrenamiento correctivo.', 28153),
(143742, 'esES', '', 'Sé que soy tu Brisaveloz preferida. ¿O acaso me equivoco...?', 28153),
(143741, 'esES', '', 'La sangre de Azeroth pertenece a la Horda.', 28153),
(143740, 'esES', '¡Me empecé a cuestionar la existencia de semejante criatura!', '', 28153),
(143739, 'esES', '', 'Reclamaremos lo que es nuestro.', 28153),
(143738, 'esES', '', 'Al final, todos servirán a la Horda.', 28153),
(143737, 'esES', '', 'Aumentaré las filas de los Renegados. De la forma que sea...', 28153),
(143736, 'esES', '', 'Haremos que la Alianza se arrodille ante nosotros.', 28153),
(143735, 'esES', '', 'Sirve a la Horda. Sírveme a mí.', 28153),
(143734, 'esES', '¡Es precioso!', '', 28153),
(143733, 'esES', '', 'Vete. Tengo mucho que hacer.', 28153),
(143732, 'esES', '', 'Sírveme bien y tendrás tu recompensa.', 28153),
(143731, 'esES', '', 'Forjaremos un nuevo futuro para la Horda.', 28153),
(143730, 'esES', '', 'Nuestro trabajo no ha hecho más que empezar.', 28153),
(143729, 'esES', '', 'Saludos, adalid.', 28153),
(143728, 'esES', '', 'Adelante.', 28153),
(143727, 'esES', '', 'Espero que no me hagas perder el tiempo.', 28153),
(143726, 'esES', '', '¿Qué quieres? Díselo a tu Jefa de Guerra.', 28153),
(143725, 'esES', '', 'Los elementos de Zandalar han soportado mucho. Debemos detener a los chamanes oscuros que abusan de su poder para sus propios fines egoístas.', 28153),
(143724, 'esES', 'Me llamo Berthold y soy un fanático de los caballos.\n\nSe rumorea que hay una majestuosa criatura equina al oeste de este complejo, en algún tipo de montaña. Acepté un trabajo aquí para tener una oportunidad de verla en mi tiempo libre.\n\nLo que daría por ver algo así...', '', 28153),
(143721, 'esES', 'Afirmativo. Solicitud de reubicación del guardián de los titanes Hezrel aceptada. Dirección establecida a zona designada: Zul\'Nazman.', '', 28153),
(143720, 'esES', '', 'Hezrel, loh trolh de sangre se van a reunir en Zul\'Nazman. Si quiereh ayudarnoh, ve allí.', 28153),
(143719, 'esES', 'Invítame a un trago, $pr.\n\nMi gente salvó ehte mundo mientrah loh tuyoh corrían a ehconderse como cobardeh detráh de esa niebla.\n\nMe debeh un trago.', '', 28153),
(143718, 'esES', 'Los sistemas del guardián de los titanes Hezrel funcionan al 50%. Se debe conservar la energía restante para la purga de trols de sangre.', '', 28153),
(143717, 'esES', 'En ehta sala solía mezclar mih brebajeh. La familia real recibía a la nobleza de todoh loh rinconeh del mundo y yo loh conquihtaba con mih bebidah.\n\nAhora eh un cubil de esoh forahteroh inmundoh y suh amigoh horrendoh. Qué dehgracia.', '', 28153),
(143716, 'esES', 'Rehpeto a algunoh de loh cárteleh goblinh. Neutraleh y fuerteh, dihpuehtoh a hacer lo que sea necesario. Como loh Zandalari... aunque peoreh, por supuehto.\n\nPero loh Pantoque soih una dehgracia. Oh metéih en la cama con loh elfoh y la Horda. Unoh auténticoh vendidoh.', '', 28153),
(143715, 'esES', '¡Siente mi poder!', '', 28153),
(143714, 'esES', 'Me guhta la forma de operar de tu Horda, $p. Lídereh fuerteh. Unidoh por un mihmo propósito. Líneah de suminihtroh ehtableh.\n\n¿Ehtáih reclutando?', '', 28153),
(143713, 'esES', 'Estoy listo para buscar a nuestros siguientes aliados.', 'Estoy lista para buscar a nuestros siguientes aliados.', 28153),
(143712, 'esES', '', 'Por fin se va a acabar toda esta farsa entre la Horda y la Alianza.$b$b¡Es hora de que empiece la guerra!', 28153),
(143711, 'esES', 'Siempre me ha sorprendido que loh Lanza Negra oh unieraih a la Horda. Supongo que siempre fuihteih demasiado débileh pa defenderoh soloh.\n\n¿Cómo ehtá Vol\'jin?', '', 28153),
(143710, 'esES', 'Mira, $gelfo:elfa;, ya no soy el dueño de ehte bar, así que no tengo que fingir que me guhtah.\n\nFuera de mi vihta, ehcoria.', '', 28153),
(143709, 'esES', 'Parece que tieneh sed. Toma un trago. Quédate y charlemoh un poco.\n\nZuldazar ha ehtado aquí dehde tiempoh ancehtraleh. No va a desaparecer de la noche a la mañana.', '', 28153),
(143708, 'esES', 'He oído que algunoh oh dirigíh a Nazmir. Evita esa tarea si puedeh. No ha salido nada bueno de ese pantano durante generacioneh.', '', 28153),
(143707, 'esES', 'He oído que hay máh problemah de lo habitual entre lah arenah de Vol\'dun. Ten cuidado si vah en esa dirección.', '', 28153),
(143706, 'esES', 'Mi pueblo fundó una civilización en loh alboreh del tiempo y oh hemoh cargado a loh demáh a nuehtrah ehpaldah dehde entonceh.\n\nDime, $pr, ¿qué ha hecho tu gente que sea digno de recordar?\n\nNo se me ocurre absolutamente nada.', '', 28153),
(143705, 'esES', '(Saltar sobre el hombro de Hezrel para volver a la Cuenca Tenebrosa).', '(Saltar sobre el hombro de Hezrel para volver a la Cuenca Tenebrosa).', 28153),
(143704, 'esES', 'Reparación de la contención de G\'huun fallida. Es necesario evitar que las unidades designadas como trols de sangre destruyan Zuldazar para que G\'huun no se libere por completo.\n\nEstructura rodeada por trols de sangre. El guardián de los titanes Hezrel garantizará la seguridad de $n y la princesa Talanji.\n\nSaltar a los hombros. Agachar la cabeza.', '', 28153),
(143703, 'esES', '$gInmundo:Inmunda;. Repugnante. Hueleh peor que un trol de sangre.\n\nSi todavía fuera el dueño de ehte bar, te tiraría a la basura.', '', 28153),
(143702, 'esES', '¿Qué sabeh de lo que ocurre fuera de la ciudad?', '', 28153),
(143700, 'esES', 'Gallywix está realizando operaciones en Silithus. Dirígete allí de inmediato. Y si ves a la Alianza merodeando... ya sabes qué hacer.', '', 28153),
(143699, 'esES', 'Hemos improvisado una base en Silithus. Habla con los agentes que tenemos allí... Pero ten cuidado con los ataques de la Horda.', '', 28153),
(143698, 'esES', 'Loh orcoh sabéih beber, tengo que admitirlo.\n\nPero decidleh a loh ehtiradoh de vuehtroh amigoh loh elfoh que se mantengan alejadoh de aquí, ¿vale?', '', 28153),
(143697, 'esES', '¿Alleria y Turalyon? ¡Ni hablar! Bueno, no es que yo tenga ningún interés especial en el tema, pero... ¿Y si hablamos de otra cosa?', '', 28153),
(143696, 'esES', 'No pasa nada si no te gustan los elfos. Al fin y al cabo, la mitad de nosotros odiamos intensamente a la otra mitad.', '', 28153),
(143695, 'esES', 'Siempre me ha gustado ponerme morado... Pero nunca pensé que lo haría de forma literal.', '', 28153),
(143694, 'esES', '¿Elfo noble? Por favor... ¿Quién quiere ser elfo noble cuando puede ir por ahí con esta pinta trágica y siniestra?', '', 28153),
(143693, 'esES', 'Mantén la concentración y el control.', '', 28153),
(143692, 'esES', 'No te sometas a los susurros.', '', 28153),
(143691, 'esES', 'Libera tu mente.', '', 28153),
(143690, 'esES', 'Que las sombras te protejan.', '', 28153),
(143689, 'esES', 'Servimos a la Alianza.', '', 28153),
(143688, 'esES', 'La Luz no es el único camino.', '', 28153),
(143687, 'esES', 'Los ren\'dorei probaremos nuestra valía.', '', 28153),
(143686, 'esES', 'Tengo mucho que enseñarte.', '', 28153),
(143685, 'esES', 'Ven con mente abierta.', '', 28153),
(143684, 'esES', 'Todos los caminos son posibles.', '', 28153),
(143683, 'esES', 'No tememos el poder, lo aceptamos.', '', 28153),
(143682, 'esES', 'Las sombras nos sirven.', '', 28153),
(143681, 'esES', 'Bal\'a dash, malanore.', '', 28153),
(143680, 'esES', 'Saludos, viajante.', '', 28153),
(143679, 'esES', '¿Cómo que qué le pasaba a mi parche del ojo? ¡Nada! Siempre ha estado en su sitio...', '', 28153),
(143678, 'esES', 'Trabajar para Sylvanas no siempre es fácil. Desde que murió se ha vuelto mucho más mandona. Pero... no le digas nada a ella, ¿eh?', '', 28153),
(143677, 'esES', 'Puede que Nathanos sea el campeón de la Reina, pero yo disparo mejor.', '', 28153),
(143676, 'esES', 'No creas que este pelazo se consigue así como así. Le dedico muchas horas e innumerables cuidados.', '', 28153),
(143675, 'esES', 'Ningún rey volverá a gobernar Lunargenta.', '', 28153),
(143674, 'esES', 'Nuestra nación crece.', '', 28153),
(143673, 'esES', 'Al diel shala.', '', 28153),
(143672, 'esES', 'La Horda nos hace más fuertes.', '', 28153),
(143671, 'esES', 'Lo que hago, lo hago por Quel\'Thalas.', '', 28153),
(143670, 'esES', 'Que la luz de la Fuente del Sol esté contigo.', '', 28153),
(143669, 'esES', 'Lunargenta prosperará una vez más.', '', 28153),
(143668, 'esES', 'La belleza de Canción Eterna perdura.', '', 28153),
(143667, 'esES', 'El sol eterno aún nos guía.', '', 28153),
(143666, 'esES', 'La recuperación de nuestro pueblo continúa.', '', 28153),
(143665, 'esES', 'Hemos hecho muchos sacrificios.', '', 28153),
(143664, 'esES', 'Es un honor servir como Señor regente.', '', 28153),
(143663, 'esES', 'Bal\'a dash, malanore.', '', 28153),
(143662, 'esES', 'En nombre de Lunargenta, te saludo.', '', 28153),
(143651, 'esES', '¡Hala, creo que he capturado uno grande!', '', 28153),
(143650, 'esES', 'ESCENA PLACEHOLDER - Hezrel cuenta que G\'huun era un dios antiguo y los experimentos que sufrió, además revela que los trols de sangre quieren destruir Zuldazar para liberar a G\'huun. El sistema de contención actual no se puede reparar, por lo que hay que proteger Zuldazar. Ateena, la matriarca de los trols de sangre, llega, hiere de gravedad a Hezrel y se prepara para atacar.', 'ESCENA PLACEHOLDER - Hezrel cuenta que G\'huun era un dios antiguo, relata los experimentos que sufrió y revela que los trols de sangre quieren destruir Zuldazar para liberar a G\'huun. El sistema de contención actual no se puede reparar, por lo que hay que proteger Zuldazar. Ateena, la matriarca de los trols de sangre, llega, hiere de gravedad a Hezrel y se prepara para atacar.', 28153),
(143649, 'esES', '', '¡Vuelve, $r! ¡Su voz me pertenece!', 28153),
(143648, 'esES', '', 'Hay tanto... poder... aquí...', 28153),
(143647, 'esES', '', 'Cuidado, Umbric. La respuesta a estos misterios normalmente tiene un precio.', 28153),
(143646, 'esES', 'Mira este cubo, por ejemplo. Es un artilugio antiguo; puede que hasta sea anterior a todo rastro de vida en Azeroth... Pero está cerrado y no podemos abrirlo.', '', 28153),
(143645, 'esES', '¡Así es! Como tú, creemos que se puede usar el Vacío para proteger la vida en vez de para consumirla. Hemos avanzado mucho, lady Brisaveloz, pero aún quedan muchos misterios.', '', 28153),
(143644, 'esES', '', 'Ya trataremos ese tema en otro momento. Os hemos estado buscando. Sabemos que os expulsaron de Lunargenta y creemos que tenemos mucho en común.', 28153),
(143643, 'esES', 'A mi gente le llegaron historias de lo que ocurrió en Argus. Como podrás imaginar, estamos muy interesados en tu interacción con la naaru oscura.', '', 28153),
(143642, 'esES', '¡¿Alleria Brisaveloz?! ¿Cómo...? Ah, ¡no esperaba este honor!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'esES', '', '¡Magister Umbric! Soy Alleria Brisaveloz.', 28153),
(143640, 'esES', '', 'Allí delante. Aquel debe ser Umbric.', 28153),
(143639, 'esES', '', 'Con estas notas, creo que podré volver a abrir el portal a ese mundo del que hablaba. Veamos...', 28153),
(143638, 'esES', '', '<Landing from jump: Total 3>', 28153),
(143637, 'esES', 'Drathir creía que en este lugar había un objeto antiguo de poder indescriptible. Puede que esta sea la clave que nos permita controlar las sombras.', '', 28153),
(143636, 'esES', 'Sus notas indican que se encuentra en una falla en el mismísimo tejido de la realidad. Nunca lo encontró... ¡pero yo he tenido éxito donde él fracasó! Pronto se abrirá el camino ante nosotros.', '', 28153),
(143635, 'esES', 'El ansia de poder de Drathir lo llevó a buscar los fragmentos de un mundo antiguo, un mundo a las puertas del Vacío.', '', 28153),
(143634, 'esES', '<Landing from jump: Total 3>', '', 28153),
(143633, 'esES', '', 'Vamos a la Aguja de la Estrella del Alba.', 28153),
(143632, 'esES', 'Pero creo que podemos usar este conocimiento para hacer el bien. Drathir realizó su investigación en la Aguja de la Estrella del Alba. Debemos ir allí.', '', 28153),
(143631, 'esES', 'La traición de Drathir permitió que Arthas corrompiera la Fuente del Sol... y destruyera nuestro reino. Por primera vez, entiendo por qué Rommath se opone a nuestra investigación.', '', 28153),
(143630, 'esES', 'Veo que nuestra gente ya ha intentado controlar el Vacío antes. He encontrado cuadernos de aquel cuyo mero nombre es una maldición: Dar\'Khan Drathir.', '', 28153),
(143629, 'esES', '<Landing from jump: Total 3>', '', 28153),
(143628, 'esES', '', 'He encontrado unas notas.', 28153),
(143627, 'esES', '', '<Landing from jump: Total 3>', 28153),
(143626, 'esES', 'Por desgracia, nuestra investigación ha llegado a un punto muerto. Creo que en los Dominios Andilien podríamos encontrar información que nos ayude a avanzar.', '', 28153),
(143625, 'esES', 'El gran magister debería comprender que necesitamos este poder para defender Lunargenta. ¡Los sin\'dorei no volveremos a caer ante nuestros enemigos!', '', 28153),
(143624, 'esES', 'Los experimentos con el Vacío progresan. Sé que estamos a punto de descubrir algo... pese a las protestas del estrecho de miras de Rommath.', '', 28153),
(143623, 'esES', '<Landing from jump: Total 3>', '', 28153),
(143622, 'esES', '', '<Landing from jump: Total 3>', 28153),
(143621, 'esES', '<Distressed cry: Total 3>', '', 28153),
(143620, 'esES', '<Landing from jump: Total 3>', '', 28153),
(143619, 'esES', 'Hezrel, comienza a explorar en busca de una solución a la corrupción del dios antiguo de Nazmir.', 'Hezrel, comienza a explorar en busca de una solución a la corrupción del dios antiguo de Nazmir.', 28153),
(143618, 'esES', '¡A ver si estos peces están listos para picar!', '', 28153),
(143617, 'esES', '', '<Landing from jump: Total 3>', 28153),
(143616, 'esES', '', 'Mis hermanas y yo éramos muy felices en este bosque. Verlo así... me llena el corazón de pesar.', 28153),
(143615, 'esES', 'Pero, juntos, demostraremos que se equivocan.', '', 28153),
(143614, 'esES', 'Tardaremos un tiempo en acostumbrarnos a nuestra nueva forma. Esperamos con impaciencia tu regreso, lady Brisaveloz. Y, adalid... gracias.', '', 28153),
(143613, 'esES', '', 'A cambio, juro ayudaros en vuestro viaje. Informaremos al rey Wrynn. Luego volveré y empezaremos vuestro entrenamiento.', 28153),
(143612, 'esES', 'Lunargenta nos dio la espalda hace tiempo. Hoy hemos vuelto a nacer... Y lo mejor es tomar un nuevo camino. De ahora en adelante, la Alianza cuenta con nuestra lealtad.', '', 28153),
(143611, 'esES', '', 'Percibo los poderes que controláis. Son... considerables. Seríais unos aliados muy valiosos para la Alianza.', 28153),
(143610, 'esES', 'Mi arrogancia casi nos cuesta la vida. Intenté jugar con poderes que escapaban a mi comprensión. Si tú nos instruyes, Alleria, te seguiremos.', '', 28153),
(143609, 'esES', '', 'He autorizado la creación de una embajada en Orgrimmar desde la que buscar aliados para nuestra causa. Reúnete allí conmigo de inmediato.', 28153),
(143608, 'esES', '', 'El mandato desinteresado de la Horda en la guerra contra la Legión nos ha dejado sin recursos. Nuestros enemigos ansían robar lo que es nuestro. No lo permitiremos.', 28153),
(143607, 'esES', '', 'Has visto nuestras operaciones en Silithus. No cabe duda de que la Alianza está haciendo lo posible por entorpecer nuestro trabajo.', 28153),
(143606, 'esES', 'Es hora de que la Alianza busque nuevos miembros que se unan a nuestra causa. Para ello, hemos establecido una embajada en Ventormenta. Reúnete allí conmigo.', '', 28153),
(143605, 'esES', 'La Horda no se detendrá ante nada para obtener la sangre de Azeroth. Tras la guerra contra la Legión, temo que nuestras filas estén demasiado mermadas para hacerles frente.', '', 28153),
(143604, 'esES', 'Has visto la devastación de Silithus con tus propios ojos. Ya sabes lo que está en juego.', '', 28153),
(143603, 'esES', 'Reúnete conmigo fuera del Fuerte Grommash. No se lo digas a nadie... o habrá graves consecuencias.', '', 28153),
(143602, 'esES', 'Tenemos información crucial para los intereses de la Horda. Es esencial que nos mantengamos un paso por delante de nuestros rivales.', '', 28153),
(143601, 'esES', '¡Adalid! La Dama Oscura ordena que te reúnas conmigo en Orgrimmar.', '', 28153),
(143600, 'esES', 'Reúnete conmigo en Reposo del León. Y no compartas con nadie lo que hemos hablado.', '', 28153),
(143599, 'esES', 'Hemos descubierto cierta información... delicada. Su Majestad insiste en que te la comuniquemos.', '', 28153),
(143598, 'esES', 'Adalid, el rey Wrynn solicita que te reúnas conmigo en Ventormenta.', '', 28153),
(143597, 'esES', 'También he traído a alguien que solicita audiencia, ¡oh, poderoso loa!', '', 28153),
(143596, 'esES', '', 'Los Nocheterna sois un pueblo sabio y poderoso. Vuestro conocimiento antiguo será muy valioso para nuestra causa.', 28153),
(143595, 'esES', '', 'Pero basta ya de formalidades. Tienes mucho que demostrar, adalid. Dondequiera que te lleve tu camino, no olvides que luchas... ¡por la Horda!', 28153),
(143594, 'esES', '', 'Ten por seguro que iré observando tu progreso. Como Jefa de Guerra, espero mucho de ti... Y recompenso a aquellos que me sirven bien.', 28153),
(143593, 'esES', '', 'La Horda tiene muchos rivales en este mundo. Algunos nos consideran enemigos; otros, marginados. Pero hay fuerza en nuestra unión... y en la lucha contra los que amenazan nuestra libertad.', 28153),
(143592, 'esES', '', 'Los tauren Monte Alto poseéis fuerza y valor. Nos harán falta ambas cualidades en los días que están por venir.', 28153),
(143591, 'esES', '', 'Ah, mira quién está aquí. Me han dicho que tienes un futuro muy prometedor... Esperemos que sea cierto.', 28153),
(143590, 'esES', 'Buen viaje. Que la Luz esté siempre contigo.', '', 28153),
(143589, 'esES', 'Los elfos del Vacío acabáis de entrar en la Alianza, pero Alleria Brisaveloz es una de nuestras más valiosas heroínas. Sigue sus enseñanzas y tus poderes servirán a nuestra causa.', '', 28153),
(143588, 'esES', '¡Te sacaremos de estas tierras!', '', 28153),
(143587, 'esES', 'Buen viaje. Aunque caminas entre las sombras, eres una señal de esperanza para nosotros.', '', 28153),
(143586, 'esES', 'Estoy impaciente por ver cómo te desenvuelves. Algo me dice que volveremos a hablar pronto.', '', 28153),
(143585, 'esES', 'Estos son tiempos oscuros para Azeroth. En los días que se avecinan, te enfrentarás a muchas pruebas y enemigos, pero no olvides que la Alianza está a tu lado en tu lucha contra la oscuridad.', '', 28153),
(143584, 'esES', 'Aunque los forjados por la Luz acabáis de incorporaros a nuestras filas, conozco bien a los draenei. Sé que mostrarás la dedicación y el valor propios del Ejército de la Luz.', '', 28153),
(143583, 'esES', 'Te saludo, adalid. Soy el rey Anduin Wrynn. Quería darte la bienvenida a la Alianza personalmente.', '', 28153),
(143582, 'esES', '¡Necesito sanación!', '', 28153),
(143581, 'esES', '¡Búscate tu propio aserradero!', '', 28153),
(143580, 'esES', 'A qué rincón más interesante y recóndito del mundo nos ha llevado la Horda.\n\nSupongo que la mayoría de los establecimientos de mi nueva facción serán más elegantes y limpios que este.', '', 28153),
(143579, 'esES', 'Perdóname, $p.\n\nMe encantaría charlar contigo, pero me temo que empiezo a encontrarme indispuesto.\n\nNo pruebes el vino.', '', 28153),
(143578, 'esES', '<El vinatero Thesnala mira al camarero mientras derrama su vino poco a poco en el suelo a su lado>.', '', 28153),
(143577, 'esES', '¿Ya has probado el vino local?\n\nNo puedes perdértelo. El sabor es increíblemente asqueroso.\n\nLos bardos podrían componer canciones sobre su legendaria textura horrible.\n\nSin duda es un verdadero logro, un alcohol malogrado con inmundicias abismales, capaz de matar de asco al que lo bebe.', '', 28153),
(143576, 'esES', 'De momento, confío en los Zandalari para que construyan edificios grandes y horrorosos.\n\nPero NO confío en ellos para que hagan vino.', '', 28153),
(143575, 'esES', 'Si no puedes hacer un buen vino, deberías dedicarte a otra cosa.', '', 28153),
(143574, 'esES', 'Invítame a otra copa de este vino para que pueda escupir su inmundicia al suelo una segunda vez.', '', 28153),
(143573, 'esES', '¿Llaman vino a esta bazofia? No me extraña que los trols estén abandonando la ciudad.', '', 28153),
(143572, 'esES', '¡Al fin libres! ¡Rápido, salgamos de aquí!', '¡Al fin libres! ¡Rápido, salgamos de aquí!', 28153),
(143571, 'esES', '¡Estas abominaciones de madera parecen salidas de una pesadilla!', '', 28153),
(143569, 'esES', 'Espero... cobrar... plus de peligrosidad...', 'Espero... cobrar... plus de peligrosidad...', 28153),
(143568, 'esES', '', 'Pese a ehtar tan devahtado, ehte lugar me resulta familiar...', 28153),
(143567, 'esES', '¡Esforzaos más, pedazo de holgazanes!', '¡Esforzaos más, pedazo de holgazanes!', 28153),
(143566, 'esES', 'Estructura interior despejada. El ser designado, la princesa Talanji, ha llegado.', '', 28153),
(143565, 'esES', 'Se ha dado la orden. ¡Nos vamos a Corlain!', '', 28153),
(143562, 'esES', 'Demasiado tarde. G\'huun no puede ser contenido. Todos caerán. Todos morirán.', '', 28153),
(143561, 'esES', 'Ha llegado el final. G\'huun será liberado. Azeroth será nuestro.', '', 28153),
(143560, 'esES', 'Pon tuh objetoh de valor en la cámara y no te pareh, $p.\n\nTe ehtoy vigilando...', '', 28153),
(143559, 'esES', 'Han llegado tiempos oscuros a Drustvar, ¡pero debemos recuperar nuestra tierra!', '', 28153),
(143558, 'esES', '¡Por Zandalar!', '', 28153),
(143557, 'esES', 'Rezan, vamoh de cacería.', '', 28153),
(143556, 'esES', 'Así es. Continental, partimos a tu señal.', '', 28153),
(143555, 'esES', 'Pa\'ku, loa del viento, vuela y encuentra a loh herejeh. Averigua su misión y reúnete con nosotroh en el templo.', '', 28153),
(143554, 'esES', 'Gonk, loa de la caza, lleva a tuh seguidoreh al Templo del Profeta y mata a loh enemigoh que veah. Expúlsaloh al ehterior.', '', 28153),
(143553, 'esES', 'Hermanoh y hermanah de Zandalar, ha llegado la hora de cortarleh la cabeza a loh traidoreh que han jurado lealtad a Zul.', '', 28153),
(143552, 'esES', '', 'Los demás debemos prepararnos para nuestro viaje a Corlain. Mariscal, ¿tienes un plan de ataque?', 28153),
(143551, 'esES', '', '¡Sí, señora!', 28153),
(143550, 'esES', '', 'Llévale esta receta de fuego alquímico al maestro Ashton en Médano del Halcón. Él sabrá qué hacer con ella.', 28153),
(143549, 'esES', '', 'Por suerte, conozco a un alquimista experto en Médano del Halcón, al sur. Los bosques son traicioneros, así que tendrás que viajar por los viejos caminos de montaña.', 28153),
(143548, 'esES', '', 'El tomo contiene una receta de fuego alquímico, pero ninguno de nosotros es capaz de crearlo.', 28153),
(143547, 'esES', '', 'Si queremos derrotar al aquelarre para siempre, no bastará con plata. Necesitaremos fuego.', 28153),
(143546, 'esES', '', '¡Gracias, señor! ¿Qué necesitas, mi señora?', 28153),
(143545, 'esES', 'No conozco a nadie más fiable que la capitana... perdón, la inquisidora Albaclara. Ella podrá encargarse de lo que haga falta.', '', 28153),
(143544, 'esES', '', '¿Alguna recomendación, Mariscal?', 28153),
(143543, 'esES', '', 'Antes de partir, necesito a alguien para una misión especial para la Orden.', 28153),
(143542, 'esES', '¿Te puedes creer que la Horda nunca ha fundado una agencia oficial de telemancia? Es decir, no tengo ni idea de cómo han podido los ciudadanos viajar con alguna clase de seguridad. Y pensar en todos esos portales aleatorios abriendo grietas en la realidad sin un anclaje adecuado...\n\nBueno, en cualquier caso, me encantaría ofrecer mi red de teletransporte estable a la Horda. Aparta, por favor.', '', 28153),
(143540, 'esES', 'La gente de mi pueblo es dura, pero esto pone a prueba nuestro coraje.', '', 28153),
(143539, 'esES', '', 'Haced que me sssienta orgullosssa: ¡no dejéisss que sssobreviva ningún insssecto!', 28153),
(143537, 'esES', '¡Brgl! ¡Brglrgl!', '', 28153),
(143536, 'esES', '¡Mrgl, mrglrglrgl! ¡Mrrrg! ¡Mrrrg!', '', 28153),
(143531, 'esES', 'Abriendo', 'Abriendo', 28153),
(143530, 'esES', '¡Ehto eh por ti! ¡Sube!', '', 28153),
(143529, 'esES', 'Algo no va bien en el Garra de Rezan. Tenemoh un vuelo de ehploración cerca del campamento.', '', 28153),
(143523, 'esES', 'Dadme vuestro oro, ¡tengo una conferencia sobre beneficios en cinco minutos!', '', 28153),
(143520, 'esES', 'Estoy listo para que me apliques la esencia sintética de G\'huun.', 'Estoy lista para que me apliques la esencia sintética de G\'huun.', 28153),
(143519, 'esES', '¡Rey Da\'ka! ¡Noh ha encontrado! ¡Ayuda!', '', 28153),
(143518, 'esES', '¿Habéis... perdido? ¿Contra ellos? ¡Patético! Volved a Entrañas para un entrenamiento correctivo. Vamos a tener que empezar desde cero...', '', 28153),
(143517, 'esES', 'No es lo que yo llamaría una victoria elegante, pero al menos habéis puesto en su lugar a esos perros de la Alianza. ¡Por la Horda!', '', 28153),
(143516, 'esES', '¿A qué huele? ¿A huargen? Es difícil saberlo con esa peste a arrogancia que despide la Alianza...', '', 28153),
(143515, 'esES', '¡Matadlos! No os conviene decepcionar a vuestra Jefa de Guerra...', '', 28153),
(143514, 'esES', '¿Esos son los soldados de la Alianza? ¡Patético! Si no saben ni sujetar una espada...', '', 28153),
(143513, 'esES', '¡Al ataque! Que no quede ni uno con vida...', '', 28153),
(143512, 'esES', '¡Rayos y centellas! Hay más azerita... ¡Seguid el mapa y proteged esos emplazamientos!', '', 28153),
(143511, 'esES', '¡Hay más erupciones de azerita en esta maldita isla! Usad el mapa para encontrarlas.', '', 28153),
(143510, 'esES', 'Ya casi estamos... ¡No os rindáis! ¡Más azerita!', '', 28153),
(143509, 'esES', '¡Ja! ¡En las mismísimas narices de la Alianza! ¡Bien hecho!', '', 28153),
(143508, 'esES', 'No está mal para empezar, pero necesitamos más azerita.', '', 28153),
(143507, 'esES', 'Recoged los suministros si queréis, ¡pero recordad el verdadero objetivo de la Reina alma en pena!', '', 28153),
(143506, 'esES', 'Os van a llegar suministros. ¡Más vale que los recojáis antes de que la Alianza se haga con ellos!', '', 28153),
(143505, 'esES', 'Allí abajo... ¡Azerita! Llevádsela a nuestra Jefa de Guerra. Si la Alianza se interpone en vuestro camino, pintad la playa con su sangre. ¡En marcha!', '', 28153),
(143504, 'esES', 'Dejad que os eche un vistazo. Oh, ¿no tenéis ninguna forestal oscura? ¡Patético! Bueno, habrá que conformarse...', '', 28153),
(143503, 'esES', '¡Viene una nave de la Alianza! Esos perros no pueden vivir sin nosotros... ¡Zafarrancho de combate!', '', 28153),
(143502, 'esES', 'Vuestra misión es sencilla: recoger hasta el último resquicio de azerita y no dejar nada para la Alianza. ¡Espero que lo hayáis entendido!', '', 28153),
(143501, 'esES', '¡Escuchadme! Hemos encontrado depósitos de azerita en una isla cerca de Feralas. ¡Es vuestro deber haceros con ella en nombre de la Dama Oscura!', '', 28153),
(143500, 'esES', '¡Echadlos de aquí! ¡Esta isla es nuestra!', '', 28153),
(143499, 'esES', '¡Luchad por el Rey! ¡Y por la Alianza!', '', 28153),
(143498, 'esES', 'La Horda se cree muy lista... ¡Dadle una lección!', '', 28153),
(143497, 'esES', '¡Disparad a los sanadores!', '', 28153),
(143496, 'esES', 'Parecéis bastante fuertes... No está mal, aunque preferiría contar también con algún pícaro.', '', 28153),
(143495, 'esES', '¡Maldita sea! La Horda se nos ha adelantado... ¡Pero juro por Reposo del León que al final ganaremos!', '', 28153),
(143494, 'esES', '¡Buen trabajo! El rey Wrynn se alegrará de vuestra victoria. ¡Por la Alianza!', '', 28153),
(143493, 'esES', 'Os enviamos suministros. ¡Id a por ellos!', '', 28153),
(143492, 'esES', '¡Más erupciones de azerita! ¡Usad el mapa para encontrarlas y asegurarlas!', '', 28153),
(143491, 'esES', 'Lo estáis haciendo genial. ¡Un poco más de azerita y habremos vencido!', '', 28153),
(143490, 'esES', 'Habéis evitado que la Horda se hiciera con esa azerita. ¡Bien hecho!', '', 28153),
(143489, 'esES', 'No lo estáis haciendo nada mal, pero necesitamos más azerita.', '', 28153),
(143488, 'esES', 'Os estamos enviando suministros. ¡No dejéis que la Horda se haga con ellos!', '', 28153),
(143487, 'esES', '¡Hemos localizado más erupciones de azerita por la isla! Las tenéis marcadas en el mapa.', '', 28153),
(143486, 'esES', 'Hay un depósito de azerita debajo de nosotros. Recoged toda la que podáis, y si alguno de esos maleantes de la Horda se interpone en vuestro camino... ¡matadlo!', '', 28153),
(143485, 'esES', '¡Viene una nave de la Horda! Seguro que nos han seguido... ¡Zafarrancho de combate!', '', 28153),
(143484, 'esES', 'Hemos llevado nuestra nave hasta el centro de la isla. Recoged tanta azerita como podáis. ¡Es crucial para nuestra victoria!', '', 28153),
(143483, 'esES', 'Hemos localizado depósitos de azerita en una isla cerca de Feralas. Debemos hacernos con ella antes de que lo haga la Horda.', '', 28153),
(143482, 'esES', '', 'Será un honor, lady Liadrin. Oculeth tiene las coordenadas de vuestra capital. Avisaré a Silgryn y Valtrois y nos reuniremos contigo en Lunargenta.', 28153),
(143481, 'esES', '', 'Seguro que el Señor regente se alegrará de teneros como aliados. ¿Estás lista para partir?', 28153),
(143480, 'esES', '', 'Por eso agradezco la invitación a Lunargenta. Me gustaría averiguar si tu Horda aceptaría a los Nocheterna entre sus filas.', 28153),
(143479, 'esES', '', 'La Alianza está demasiado recluida... demasiado aislada. Mi pueblo no volverá a sufrir un estancamiento así.', 28153),
(143478, 'esES', '', 'También desdeñan a los sin\'dorei, aunque el orgulloso pueblo de Tyrande pasó años durmiendo en guaridas y ocultándose entre los árboles mientras mi gente luchaba para salvar este mundo.', 28153),
(143477, 'esES', '', 'Parece que la \"sabiduría de Elune\" la llevó a romper el vínculo que compartíamos. Que así sea.', 28153),
(143476, 'esES', '', 'Los kaldorei lucharán para derrotar a la Legión y destruir la Fuente de la Noche. Después, veremos adónde nos lleva la sabiduría de Elune.', 28153),
(143475, 'esES', '', 'No queremos ser esclavos de la Fuente de la Noche. Queremos expulsar a la Legión de Suramar y acabar con la opresión de Elisande.', 28153),
(143474, 'esES', '', 'Arcanista Thalyssra, recuerdo la posición de tu orden en la Guerra de los Ancestros. ¿Cómo sabemos que no nos traicionarás y te convertirás en la próxima Elisande? ¿O en la próxima Azshara?', 28153),
(143473, 'esES', '', 'Creí que nuestros hermanos de Kalimdor serían buenos aliados, pero su arrogancia y desconfianza me demostraron lo contrario.', 28153),
(143472, 'esES', '', 'Admito que la primera vez que oí hablar de la Horda pensé que no tendríamos nada en común.', 28153),
(143471, 'esES', '', 'Fue un honor para la Horda luchar contra la Legión Ardiente a vuestro lado.', 28153),
(143470, 'esES', '', 'Eso os lo debemos a vosotros: desempeñasteis un papel clave para nuestra causa.', 28153),
(143469, 'esES', '', 'Y yo de ver libre tu ciudad, Primera Arcanista.', 28153),
(143468, 'esES', '', 'Saludos, lady Liadrin, adalid. Os doy la bienvenida a Suramar. Me alegro de poder recibiros en mejores circunstancias.', 28153),
(143467, 'esES', '', 'Eh decepcionante, pero no me sorprende... Loh loa no te han bendecido, joven. No te uniráh a nosotroh en el Bancal de loh Elegidoh.', 28153),
(143466, 'esES', 'Vaya, sí que has viajado lejos para visitarme, joven.$b$bTengo varias novelas sobre la historia de los cangrejos, ¿te interesa el tema?', '', 28153),
(143465, 'esES', '', 'Con esa resistencia y orgullo, puedes sobrevivir a tus enemigos y capear cualquier tormenta. Necesitaremos tu fuerza para defender nuestra ciudad.', 28153),
(143464, 'esES', '', 'Ehto eh... de lo máh inusual. Necesitaremoh tu fuerza en loh tiempoh que se avecinan.', 28153),
(143463, 'esES', '', 'Egoísta y sin honor... Será mejor que busques otro camino, joven.', 28153),
(143462, 'esES', '', 'Interesante... Te valeh del sigilo y la inteligencia pa golpear dehde las sombrah. La sorpresa será tu mejor arma.', 28153),
(143461, 'esES', '', 'Ya veo. Eres veloz, prestas atención y golpeas de forma certera. Tu paciencia será recompensada.', 28153),
(143460, 'esES', '', 'Busca en tu interior, joven. Muéstrame cómo cazarás a tu presa. ¿Con sabiduría, fuerza, o algo completamente distinto?', 28153),
(143459, 'esES', '', 'La manada te llama con fuerza. Acepta tuh lazoh de parentehco y caza con tuh hermanoh y hermanah.', 28153),
(143458, 'esES', '¿Hueles eso? Huele a repollo.$b$b<Kronah se inclina y te huele>.$b$bNo eres tú, debe de ser algo de por aquí.$b$b¿Qué tal tu caligrafía? ¿Te gustaría que te dieran una clase? Aunque no lo parezca, soy una maestra escriba.', '', 28153),
(143457, 'esES', '¡Nos atacan!', '¡Nos atacan!', 28153),
(143456, 'esES', '¡Hermanos, hermanas, preparad las armas!', '¡Hermanos, hermanas, preparad las armas!', 28153),
(143455, 'esES', '¡Hay enemigos entre nosotros!', '¡Hay enemigos entre nosotros!', 28153),
(143454, 'esES', '¡Intrusión! ¡A las armas!', '¡Intrusión! ¡A las armas!', 28153),
(143452, 'esES', 'Con mucho gusto.', '', 28153),
(143451, 'esES', '¡Muévete!', '', 28153),
(143450, 'esES', '¡Tenemos pedidos que atender!', '', 28153),
(143449, 'esES', '', 'Por favor, no dihtraigah al chico.\n\nEhtoy comprobando si ehtoh niñoh muehtran algún signo de conexión con loh loa. Loh que tienen la bendición de un loa reciben entrenamiento como sacerdoteh y dihfrutan del honor y loh privilegioh que la clase comporta.\n\nA loh que no cuentan con tal bendición, se leh da la oportunidad de demohtrar su valía pa convertirse en poderosoh guerreroh algún día.\n\nLoh que fracasan en ambah pruebah no noh son de utilidad. Suelen acabar robando en loh muelleh o mendigando en El Zócalo.', 28153),
(143448, 'esES', 'Puedo hacerlo.', '', 28153),
(143447, 'esES', 'Está bien.', '', 28153),
(143446, 'esES', 'No hago más que trabajar.', '', 28153),
(143445, 'esES', '¡Necesitamos más madera!', '', 28153),
(143444, 'esES', 'Podrás descansar cuando estés criando malvas. Hasta entonces, ¡tenemos pedidos que atender!', '', 28153),
(143443, 'esES', 'Volveré a la aldea lo más rápido que pueda, antes de que todo desaparezca. Tal vez no me hayan olvidado.', '', 28153),
(143442, 'esES', 'No creo que pueda vivir como antes. Como un simio descerebrado. No después de lo que he visto y sentido, aunque fuera por tan breve tiempo.', '', 28153),
(143441, 'esES', 'Da\'ka tenía razón. Empiezo a sentir cómo mi mente vuelve a su estado primitivo.', '', 28153),
(143440, 'esES', 'Hola, $gviajero:viajera;. ¿Andas buscando algún pergamino?$b$b¿O tal vez una tinta exótica hecha con las hierbas más excepcionales?', '', 28153),
(143439, 'esES', 'Aunque los goblins tienen el cerebro tan pequeño que lo entenderán mejor si machacáis a unos cientos más.', '', 28153),
(143438, 'esES', '¡Muy bien! Les habéis demostrado a esos goblins lo que ocurre si te metes con los enanos Hierro Negro.', '', 28153),
(143437, 'esES', '¡Romped sus máquinas! ¡Destruid sus herramientas! ¡Aplastad a todos los goblins con los que os crucéis!', '', 28153),
(143436, 'esES', '¡Estos goblins están corrompiendo la azerita a gran escala! ¡No podemos permitirlo!', '', 28153),
(143435, 'esES', 'Ferromazo por fin está a nuestro alcance. ¡Enseñadles a esos goblins lo que ocurre si robas a los Hierro Negro!', '', 28153),
(143434, 'esES', '¿Quién anda ahí? ¿Quién ha detenido la bruma? ¡El rey Da\'ka te matará!', '', 28153),
(143433, 'esES', '¡Por la Horda!', '¡Por la Horda!', 28153),
(143432, 'esES', 'La pequeña Tika observa a los cerdos hambrienta.', '', 28153),
(143431, 'esES', 'La pequeña Tika menea la cola con aire juguetón.', '', 28153),
(143430, 'esES', '', '¿Quién eh un raptorcito devoracarah precioso? ¡Tú! ¡Sí, tú!', 28153),
(143429, 'esES', '', '¡Oh, me alegro de volver a verte, peque! $n... Graciah.', 28153),
(143428, 'esES', '', '¡¿Es Tika?!', 28153),
(143427, 'esES', 'La pequeña Tika trina feliz.', '', 28153),
(143426, 'esES', '', 'Habrá... otros...', 28153),
(143425, 'esES', '', 'El sol se pone para el Imperio Zandalari. ¡Los infieles reclamarán los restos!', 28153),
(143424, 'esES', '¡Haré que te ahoguen y te despiecen por eso!', '¡Haré que te ahoguen y te despiecen por eso!', 28153),
(143423, 'esES', 'La pequeña Tika alza el hocico al viento. Emite un quejido lastimero.', '', 28153),
(143422, 'esES', '¡La plebe debe arrodillarse ante su reina!', '¡La plebe debe arrodillarse ante su reina!', 28153),
(143421, 'esES', 'También... te reclamará... a ti...', 'También... te reclamará... a ti...', 28153),
(143420, 'esES', '¡La casa Canto Tormenta dominará esta tierra!', '¡La casa Canto Tormenta dominará esta tierra!', 28153),
(143419, 'esES', '', '¡Gracias a $glos:las; dos por vuestra ayuda! $n, prepárate para dirigirte a la cueva de Colasombría para ayudar a Ben\'jin cuando esto funcione.', 28153),
(143418, 'esES', '', 'Podría haber inventado un dispositivo para leer la actividad cerebral de los brutosaurios y ejecutar un análisis. No es por nada.', 28153),
(143417, 'esES', '', 'La ciencia es la única respuesta, Jangalar. No pretendo desprestigiar tu poder, pero la palabrería no puede reemplazar a la alquimia lógica y agresiva.', 28153),
(143416, 'esES', '¡Les enseñaremos a esos humanos pusilánimes la fuerza de la Horda!', '', 28153),
(143415, 'esES', '¡Esos humanos deberían temernos antes de que nuestras hojas les corten la carne!', '', 28153),
(143414, 'esES', '¡Por la Horda!', '', 28153),
(143413, 'esES', 'Voy a regresar a Zuldazar... No te preocupeh por mí, puedo volver solo. ¡Ven a verme la próxima vez que visiteh la ciudad!', '', 28153),
(143412, 'esES', 'Ehpera, Jin\'Tiki. Quédate el raptor. Al fin y al cabo... parece que le caeh mejor que yo.', '', 28153),
(143411, 'esES', '¡Mantén los ojos abiertos! ¡No quiero que esos humanos anden husmeando por nuestro aserradero!', '', 28153),
(143410, 'esES', '¡Con buen ritmo!', '', 28153),
(143409, 'esES', 'Parece que nuehtro trabajo aquí ha acabado. Eh hora de que vaya a Vol\'dun y pague por mih crímeneh.', '', 28153),
(143408, 'esES', '¡Si pillo a alguno durmiendo en el trabajo, lo echaré a los lobos yo mismo!', '', 28153),
(143407, 'esES', '¡Que sigan llegando esos recursos!', '', 28153),
(143404, 'esES', 'Tu fin... se acerca...', 'Tu fin... se acerca...', 28153),
(143403, 'esES', 'Cómo... es posible...', 'Cómo... es posible...', 28153),
(143402, 'esES', '', 'Coge tuh behtiah y dirígete a la ciudad. ¡Te llevaré una cehta de cabezah de serpiente cuando hayamoh acabado!', 28153),
(143401, 'esES', 'Te enfrentarás... al ojo... de la tormenta...', 'Te enfrentarás... al ojo... de la tormenta...', 28153),
(143400, 'esES', 'Caerás...', 'Caerás...', 28153),
(143399, 'esES', 'Ahí. De ahí proviene la bruma, de lah profundidadeh.', '', 28153),
(143398, 'esES', 'Mi alma... se hunde... en el mar...', 'Mi alma... se hunde... en el mar...', 28153),
(143397, 'esES', 'Viajo... al fondo... de las mareas...', 'Viajo... al fondo... de las mareas...', 28153),
(143396, 'esES', '¡Han matado a nuehtro jefe! ¡Toda la aldea ehtá perdida!', '', 28153),
(143395, 'esES', 'El rehpiradero principal ehtá dentro. ¡Ven, rápido!', '', 28153),
(143394, 'esES', 'Regreso... a las profundidades...', 'Regreso... a las profundidades...', 28153),
(143391, 'esES', 'Hasta la marea... sucumbe...', 'Hasta la marea... sucumbe...', 28153),
(143390, 'esES', '¡Su poder fluye por mis venas!', '¡Su poder fluye por mis venas!', 28153),
(143389, 'esES', '¡Acepta tu fin!', '¡Acepta tu fin!', 28153),
(143388, 'esES', '¡Los tentáculos del destino te atraparán!', '¡Los tentáculos del destino te atraparán!', 28153),
(143387, 'esES', '¡Serás un caparazón sin vida!', '¡Serás un caparazón sin vida!', 28153),
(143386, 'esES', '¡Ahógate mientras se apaga tu luz!', '¡Ahógate mientras se apaga tu luz!', 28153),
(143385, 'esES', '¡Nadie puede detener la marea eterna!', '¡Nadie puede detener la marea eterna!', 28153),
(143384, 'esES', '¡Las profundidades te llaman!', '¡Las profundidades te llaman!', 28153),
(143383, 'esES', '¡El mar te arrastrará!', '¡El mar te arrastrará!', 28153),
(143382, 'esES', 'Y así cayó... el rey Da\'ka.', '', 28153),
(143381, 'esES', '', 'Me prometieron... grandeza...', 28153),
(143380, 'esES', '¡$gVillano:Villana;! Eres como una vela, mejor cuando está ardiendo.', '', 28153),
(143379, 'esES', '', 'Eres fuerte, ¡pero tú también caerás ante el aquelarre!', 28153),
(143378, 'esES', '', 'Da igual, tu descubrimiento morirá contigo. ¡Atacad, mis mascotas!', 28153),
(143377, 'esES', '', 'Nos has descubierto. Debes creerte tan inteligente...', 28153),
(143376, 'esES', '¡Ja! ¿De qué sirve la inteligencia si no te proporciona poder? Me convertiré en el rey de Zandalar. ¡Ya lo verás, o morirás!', '', 28153),
(143375, 'esES', 'Hay que detenerte, Da\'ka. Nuestra inteligencia nunca debió existir ¡y mucho menos llevarnos a la guerra!', '', 28153),
(143374, 'esES', 'Tsunga... Has traído a un ser inferior a las brumas sagradas. ¿Por qué has venido?', '', 28153),
(143373, 'esES', '¿Qué está pasando aquí?', '¿Qué está pasando aquí?', 28153),
(143372, 'esES', 'Vi la verdad... en las profundidades...', 'Vi la verdad... en las profundidades...', 28153),
(143371, 'esES', 'Mi sangre... alimenta las mareas...', 'Mi sangre... alimenta las mareas...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'esES', 'Ve, el origen de lah brumah ehtá en ehta cueva. No ehtoy seguro de dónde ehtá el rey Da\'ka. ¡Deprisa!', '', 28153),
(143369, 'esES', 'La magia de sangre eh muy fuerte en ehte lugar. No hace falta ser doctor brujo pa sentirla en el aire... Ehtá por todah parteh...', '', 28153),
(143368, 'esES', '', 'Ah... ¿Qué haces aquí, continental?\n\n¿Puedo ayudarte en algo?', 28153),
(143367, 'esES', '¿A quién tengo que matar?', '', 28153),
(143366, 'esES', '¡Taz\'dingo!', '', 28153),
(143365, 'esES', '¡Por la Horda!', '', 28153),
(143364, 'esES', '¡Hora de matar!', '', 28153),
(143363, 'esES', 'Matar es fácil.', '', 28153),
(143362, 'esES', '¡Sin piedad!', '', 28153),
(143361, 'esES', '¡Rodarán cabezas!', '', 28153),
(143360, 'esES', '¡Gloria a la Horda!', '', 28153),
(143359, 'esES', '', '¡Gloria a la Horda!', 28153),
(143358, 'esES', '', '¡Rodarán cabezas!', 28153),
(143357, 'esES', '', '¡Sin piedad!', 28153),
(143356, 'esES', 'Nunca... descansaremos...', 'Nunca... descansaremos...', 28153),
(143355, 'esES', 'Mi muerte no cambia... nada...', 'Mi muerte no cambia... nada...', 28153),
(143354, 'esES', 'Ya... hemos ganado...', 'Ya... hemos ganado...', 28153),
(143353, 'esES', '', 'Matar es fácil.', 28153),
(143352, 'esES', 'Solo... cumplía órdenes...', 'Solo... cumplía órdenes...', 28153),
(143351, 'esES', 'Sabiomar... conservadme...', 'Sabiomar... conservadme...', 28153),
(143350, 'esES', 'Entrego mi vida... al mar.', 'Entrego mi vida... al mar.', 28153),
(143349, 'esES', '¡Kul Tiras pertenece al mar!', '¡Kul Tiras pertenece al mar!', 28153),
(143348, 'esES', '¿Osas enfrentarte a la casa Canto Tormenta?', '¿Osas enfrentarte a la casa Canto Tormenta?', 28153),
(143347, 'esES', '¡Somos implacables, como las mareas!', '¡Somos implacables, como las mareas!', 28153),
(143346, 'esES', '¡Todos los que se opongan morirán!', '¡Todos los que se opongan morirán!', 28153),
(143345, 'esES', '¡Nuestra flota no tiene rival!', '¡Nuestra flota no tiene rival!', 28153),
(143344, 'esES', '', '¡Hora de matar!', 28153),
(143343, 'esES', '', '¡Ven a por mí, hermana!', 28153),
(143342, 'esES', '¡Kul Tiras se hunde sin nosotros!', '¡Kul Tiras se hunde sin nosotros!', 28153),
(143341, 'esES', '', '¡Ven a por mí, hermano!', 28153),
(143340, 'esES', '¡Este valle nos pertenece, rata!', '¡Este valle nos pertenece, rata!', 28153),
(143339, 'esES', '¡Por Canto Tormenta!', '¡Por Canto Tormenta!', 28153),
(143338, 'esES', '', 'Demasiadoh saurioh muertoh... Loh crie dehde que salieron del huevo. Eh como si viera morir a mih hijoh.$b$bEsoh hombreh serpiente lo pagarán caro.', 28153),
(143337, 'esES', 'Corrupción masiva detectada en estructura cercana. Se requiere intervención inmediata.', '', 28153),
(143336, 'esES', 'Restauración parcial completada. Se requiere continuar para reparar la contención de la corrupción.', '', 28153),
(143335, 'esES', 'Mejorando sistemas auxiliares. Espera...', '', 28153),
(143334, 'esES', '¿Puedes reparar equipo?', '¿Puedes reparar equipo?', 28153),
(143333, 'esES', 'La aldea ehtá perdida, pero tendrán que arrebatarme la forja pasando por encima de mi cadáver.', '', 28153),
(143332, 'esES', '', '¡Por la Horda!', 28153),
(143331, 'esES', '', '¡Taz\'dingo!', 28153),
(143330, 'esES', '', '¿A quién tengo que matar?', 28153),
(143329, 'esES', 'Me alegra que los inocentes estén a salvo, pero queda mucho por hacer.', '', 28153),
(143328, 'esES', '', 'Hasta ahora solo había oído historias de Ventormenta. Por fin podré explorar sus calles y las maravillas que esconde. Que las sombras te guíen, $n.', 28153),
(143327, 'esES', 'Que la Luz esté contigo, $n. Yo buscaré a la Legión en Azeroth para continuar nuestro combate eterno.', '', 28153),
(143326, 'esES', 'No voy a hacerlo, claro... pero lo pensé. ¡Durante casi un segundo! ', '', 28153),
(143325, 'esES', 'Admito que veros trabajar casi me hace plantearme daros una parte de los beneficios.', '', 28153),
(143324, 'esES', '¡Buen trabajo! Y ahora que empiecen las heroicidades de verdad... A firmar los formularios de propiedad de la mina. Todo muy oficial.', '', 28153),
(143323, 'esES', 'Ahora en serio, será mejor deshacernos de ellos antes de que reduzcan mis beneficios.', '', 28153),
(143322, 'esES', 'Objetivo completado. Siguiente ubicación asignada. Entregar misiones en nueva posición.', '', 28153),
(143321, 'esES', '¡Ja! Mirad cómo aplastan a esos pringados. Esos elementales les están pegando duro.', '', 28153),
(143320, 'esES', 'La pequeña Tika lanza un gruñido leve pero amenazante.', '', 28153),
(143319, 'esES', '¡La pequeña Tika pía con agitación!', '', 28153),
(143318, 'esES', '¡¿El mundo sangra y vosotros hurgáis en las heridas?! ¡Morid!', '', 28153),
(143317, 'esES', '¡Quiero ver explosiones, caos y violencia sin límites! Ya sabéis... vuestra especialidad.', '', 28153),
(143316, 'esES', 'Enseñadles a esos trepas de Ventura y Cía. que no hay nada que no pueda arrebatarles.', '', 28153),
(143315, 'esES', 'Solo hay un problema... ¡que no me pertenece a mí! Tenéis que solucionar eso.', '', 28153),
(143314, 'esES', 'Así que de aquí viene toda la azerita del mercado negro, ¿eh? No es mal negocio.', '', 28153),
(143313, 'esES', '', 'No sé lo que es este \"aterrahuargen\", pero... Espera, ¿qué es esto?', 28153),
(143312, 'esES', 'Eras demasiado bueno, hermano. Me aseguraré de que recibas un entierro digno.', '', 28153),
(143311, 'esES', '¡Me encanta el olor a mojo por la mañana!', '', 28153),
(143310, 'esES', '', 'Rokhan dijo que teníah ehperiencia con ehte tipo de asuntoh. Haz lo que puedah. Yo ehperaré aquí al Ehcuadrón Gob.', 28153),
(143308, 'esES', '', 'Necesitamoh todo el apoyo posible. Ayuda a ehte guardián cuanto anteh.', 28153),
(143307, 'esES', 'Hezrel necesita reparación. Acudir al interior de la estructura cercana. Contener toda la corrupción de Nazmir.', '', 28153),
(143306, 'esES', 'Corrupción desmedida detectada en Nazmir. Debe procederse a la contención.', '', 28153),
(143305, 'esES', 'He librado innumerableh batallah... pero nunca anteh había vihto semejante... monhtruo...', '', 28153),
(143304, 'esES', '¡Nunca me cogeráh vivo!', '', 28153),
(143303, 'esES', 'Muy bien, ¡Vol\'dun tiene que ser máh seguro que ehte lugar!', '', 28153),
(143302, 'esES', '¡No! ¡No lo hagah! ¡Loh raptoreh... me comerán!', '', 28153),
(143301, 'esES', 'Graciah, Zaluto. Tal vez en otra vida habríamoh sido hermanoh.', '', 28153),
(143300, 'esES', '¡Usa el fetiche de sangre con Zulajin pa absorber su poder y enviarlo de vuelta a la tumba!', '', 28153),
(143299, 'esES', '¡No te preocupeh, colega! ¡Yo me encargaré del capitán aquí mientrah limpiah lah ruinah!', '', 28153),
(143298, 'esES', '¡Bien! ¡Ahora ponte el camuflaje y coge la llave!', '', 28153),
(143297, 'esES', 'Necesitaráh un dihfraz pa sortear a Zulajin. ¡Vuelve en cuanto tengah loh suminihtroh!', '', 28153),
(143296, 'esES', 'Puede que sea un delincuente, pero no soy malo. ¡No pienso dejarte morir aquí!', '', 28153),
(143295, 'esES', 'Graciah a ti, si muero... será con mi honor intacto...', '', 28153),
(143294, 'esES', '¡Aquí, aquí! ¡Un brindis por $gel:la; valiente <hip> $gcampeón:campeona; que nos salvará a todos!', '', 28153),
(143293, 'esES', '', 'Ve a Orgrimmar. Únete a nuestros aliados y forjad un nuevo futuro juntos.', 28153),
(143292, 'esES', '', 'Mientras recorres los caminos de Azeroth, cuéntale a todo el que encuentres la orgullosa historia de los Nocheterna... y muéstrales que ya no vivimos aislados.', 28153),
(143291, 'esES', '¿Qué sabemos sobre los Nocheterna?', '¿Qué sabemos sobre los Nocheterna?', 28153),
(143290, 'esES', '', 'Me alegro de que estés aquí, $n. Debemos convencer a la Jefa de Guerra de que se alíe con los Nocheterna.', 28153),
(143289, 'esES', '¿Qué sabemos sobre los tauren Monte Alto?', '¿Qué sabemos sobre los tauren Monte Alto?', 28153),
(143288, 'esES', '', 'Ahora nos toca a nosotros demostrar la fuerza y el honor que aportamos a la Horda.', 28153),
(143287, 'esES', 'Tenemos mucho en común con los tauren Monte Alto. Creo que serían unos aliados excelentes para los tiempos que se avecinan.', '', 28153),
(143286, 'esES', '', 'No te preocupeh por Tsunga. Cuidaremoh de él. Incluso si no se acuerda de su propio nombre.', 28153),
(143285, 'esES', '', 'Vaya, era muy grande, ¿verdad? ¡Buen trabajo, $gamigo:amiga;!', 28153),
(143284, 'esES', '', 'Que las estrellas te guíen, $p. He oído cosas intrigantes sobre las Laderas de Trabalomas. Es probable que me dirija hacia allí.', 28153),
(143283, 'esES', '', '¿Ehtáh seguro de ehto, Tsunga? ¿Sabeh lo que perderáh si $gehte campeón:ehta campeona; cierra lah brumah?', 28153),
(143282, 'esES', 'Iré a preparar el ritual para liberar a estas almas. Buscadme en la ribera justo al norte de aquí.', '', 28153),
(143281, 'esES', 'Soy totalmente consciente de las consecuencias. Sin embargo creo que, aunque a veces es difícil perder algunas cosas, es necesario deshacerse de ellas.', '', 28153),
(143280, 'esES', 'Iré al desfiladero por otro camino y nos encontraremos allí.', '', 28153),
(143279, 'esES', '¡No rompáis filas! Los refuerzos están en camino. ¡No podemos permitir que los nagas destruyan el dique!', '', 28153),
(143278, 'esES', 'Que tu corazón olvide el odio.', '', 28153),
(143277, 'esES', '', 'Pero los sin\'dorei, los elfos de sangre, nos mostraron respeto y comprensión. Nos enseñaron que hay quienes comparten nuestros valores en Azeroth.', 28153),
(143276, 'esES', '', 'En los días más aciagos de nuestra ciudad, los héroes de Azeroth nos ayudaron a expulsar a la Legión. Algunos a disgusto...', 28153),
(143275, 'esES', '', 'Te entrego el atuendo tradicional de Suramar. Llévalo como recordatorio de nuestro pasado... y del nuevo futuro que forjaremos junto a nuestros aliados.', 28153),
(143274, 'esES', '¡No me lo digas dos veces!', '', 28153),
(143273, 'esES', '', 'Le has mostrado a la Horda, y a todo Azeroth, que los Nocheterna poseemos la voluntad y el valor para defender nuestro mundo.', 28153),
(143272, 'esES', 'Acércate a la ribera que hay al otro lado del dique. Busca a Taelia, una joven cadete de la casa Valiente. ¡En marcha!', '', 28153),
(143271, 'esES', '', 'Regresa a Suramar para que podamos agradecerte que estés ayudando a nuestro pueblo a recuperar su lugar en el mundo.', 28153),
(143270, 'esES', '', 'Te encuentras entre los primeros shal\'dorei que se han aventurado a explorar Azeroth. Pero es hora de volver a casa.', 28153),
(143269, 'esES', 'Esos obreros... ¡están atrapados por la magia de los Sabiomar! Debemos ayudarlos.', '', 28153),
(143268, 'esES', 'Gracias a las mareas no todos han perdido la cabeza. ¡La mitad de la casa ha enloquecido!', '', 28153),
(143267, 'esES', 'Un poco menos de franela no estaría mal.', 'Un poco menos de franela no estaría mal.', 28153),
(143266, 'esES', '', 'Me adelantaré. ¡Nos vemos en la ribera!', 28153),
(143265, 'esES', 'Te sienta bien, $n.', '', 28153),
(143264, 'esES', 'Tenemos trabajo que hacer.', '', 28153),
(143263, 'esES', 'No me vendría mal un poco más de franela.', 'No me vendría mal un poco más de franela.', 28153),
(143262, 'esES', '', '¡A las armas!', 28153),
(143261, 'esES', '', '¡Por el Rey!', 28153),
(143260, 'esES', '', '¡Toma esto!', 28153),
(143259, 'esES', '', '¡A muerte!', 28153),
(143258, 'esES', '', '¡Por Ventormenta!', 28153),
(143257, 'esES', '', '¡Por la Alianza!', 28153),
(143256, 'esES', '', '¡Sin retirada!', 28153),
(143255, 'esES', '', '¡Yo me encargo!', 28153),
(143254, 'esES', '', '¿De qué corrupción hablah? Adalid, puede que con \"corrupción\" se refiera a loh trolh de sangre...', 28153),
(143253, 'esES', '', '¿Qué será ehto? ¿Creeh que querrá ayudarnoh?', 28153),
(143252, 'esES', '', '¿Qué clase de vudú eh ehte? Puede que sea útil pa detener a loh trolh de sangre y a G\'huun...', 28153),
(143251, 'esES', '¡Yo me encargo!', '', 28153),
(143250, 'esES', '¡Sin retirada!', '', 28153),
(143249, 'esES', '¡Por la Alianza!', '', 28153),
(143248, 'esES', '¡Por Ventormenta!', '', 28153),
(143247, 'esES', '¡A muerte!', '', 28153),
(143246, 'esES', '¡Toma esto!', '', 28153),
(143245, 'esES', '¡Por el Rey!', '', 28153),
(143244, 'esES', '¡A las armas!', '', 28153),
(143243, 'esES', '¡Hala! El detector se ha vuelto loco. Hay una explosión enorme de azerita en algún lugar de la isla.', '', 28153),
(143242, 'esES', 'Debemos descubrir el origen de esta profanación.', '', 28153),
(143241, 'esES', '', 'Que esta armadura te recuerde todo lo que has conseguido. Acéptala, junto con mi gratitud.', 28153),
(143240, 'esES', 'Por supuesto.', '', 28153),
(143239, 'esES', '¿Crees... Crees que esto ha afectado también a las criaturas del mar?', '', 28153),
(143238, 'esES', 'Te daré otro \"mal presagio\": la bahía está plagada de presas de las vintas.', '', 28153),
(143237, 'esES', 'Tsunga observa la entrada de la cueva, preocupado.', '', 28153),
(143236, 'esES', '', 'Muchos creían que los ren\'dorei jamás podrían controlar el poder del Vacío sin sucumbir a él, pero les has demostrado que se equivocaban.', 28153),
(143235, 'esES', 'Los gritos de las aguas se intensifican al adentrarnos en la bahía. Siento el tormento de las mareas. Son malos presagios.', '', 28153),
(143234, 'esES', '', 'Te has convertido en un arma sin igual para la Alianza. Vuelve a la falla de Vacío para que podamos honrarte por tus logros.', 28153),
(143233, 'esES', 'Ocupémonos de esto.', '', 28153),
(143230, 'esES', 'Me pondré a trabajar en el entrenamiento. Tú ve a ver a Tagart, que tiene más tareas para ti.', '', 28153),
(143229, 'esES', 'Guardián de los titanes Hezrel reiniciado. Protocolo: contener la corrupción sin control en Nazmir. Tarea imposible debido a daños en el sistema.', '', 28153),
(143228, 'esES', '', 'Durante tus viajes por Azeroth has conseguido dominar las fuerzas que intentaban controlarte.', 28153),
(143227, 'esES', 'Buen ejemplar, $gamigo:amiga;. Veamos cómo vuela. ¡Vamos!', '', 28153),
(143226, 'esES', '¡Ja, ja! ¡Mira lo que ha traído el gato! ¡Increíble!', '', 28153),
(143224, 'esES', '¡Le diré al rey Rahtakhan que encenderemoh lah torreh cuando hayamoh recuperado loh barcoh! ¡Será una señal pa mi tripulación de que pueden volver a casa!', '', 28153),
(143223, 'esES', 'El sujeto solicitado no se ve con claridad en la imagen, Wulferd no la querrá.', 'El sujeto solicitado no se ve con claridad en la imagen, Wulferd no la querrá.', 28153),
(143222, 'esES', '¡Préstame tu ayuda!', '', 28153),
(143221, 'esES', 'Mis trabajadores... Les he fallado.', '', 28153),
(143220, 'esES', '', '¡Ayuda! ¡Le han dado al comandante!', 28153),
(143219, 'esES', '¡Socorro! ¡Me atacan!', '', 28153),
(143218, 'esES', '¡Pagaréis por esto!', '', 28153),
(143217, 'esES', '¡Este tipo me saca de mis casillas!', '', 28153),
(143216, 'esES', '¡Ay! ¡Las primas del seguro!', '', 28153),
(143215, 'esES', 'Inútiles, ¡¿para qué os pago?! ¡Venga, arreglad esto!', '', 28153),
(143214, 'esES', '¡Probad una matanza de gran calibre!', '', 28153),
(143213, 'esES', '¡Tomad 300 proyectiles por minuto!', '', 28153),
(143212, 'esES', '¡Estáis donde os corresponde! A mis pies...', '', 28153),
(143211, 'esES', '¡Muerde el polvo!', '', 28153),
(143210, 'esES', '', 'Voy a explorar la zona. ¡Me reuniré contigo más adelante!', 28153),
(143209, 'esES', '¡Nunca me cogeréis vivo!', '', 28153),
(143208, 'esES', 'Debería... haber cogido... el paquete con asiento eyectable...', '', 28153),
(143207, 'esES', 'Le pasaré la factura de la munición a vuestros herederos.', '', 28153),
(143206, 'esES', '', 'Usa las lecciones que te he enseñado para mantener el control. Conviértete en un arma para la Alianza... desde el filo de la oscuridad.', 28153),
(143205, 'esES', 'Algunos dudarán de ti. Cuestionarán tu determinación y tu capacidad para controlar poderes que han causado la ruina de almas más débiles.', '', 28153),
(143204, 'esES', '', 'Pero nosotros vemos otros caminos. Vemos multitud de alternativas y posibilidades a nuestro alcance.', 28153),
(143203, 'esES', '', 'Hay quienes aseguran que la Luz es el único camino, la única arma capaz de detener a los enemigos de Azeroth.', 28153),
(143202, 'esES', 'Salvajes, ¡¿tenéis idea del valor de los daños que habéis causado?!', '', 28153),
(143201, 'esES', '¡Te has unido a los Bellacos!', '', 28153),
(143200, 'esES', 'Eh juhto como dijo esa vieja serpiente. Sube a bordo, entonceh. El Rey ehtá ehperando.', '', 28153),
(143199, 'esES', '¡Aplastar!', '', 28153),
(143198, 'esES', '¡Machacar!', '', 28153),
(143197, 'esES', '¡Pulverizar!', '', 28153),
(143196, 'esES', 'Una pena que no pudiese enseñarle la lección máh importante.', '', 28153),
(143195, 'esES', 'Dile al viejo Rahtakhan que volveré llegado el momento. Oh, y graciah.', '', 28153),
(143193, 'esES', '¡Cuando les ponga las garras encima a Yazma y Zul, los dejaré caer sobre una roca!', '', 28153),
(143192, 'esES', 'Nuestra presa está cerca. Pronto derramaremos la sangre de Zul, Yazma y sus herejes. Será una gran cacería.', '', 28153),
(143191, 'esES', '¡Gloria a Pa\'ku!', '¡Gloria a Pa\'ku!', 28153),
(143190, 'esES', '¡El barco será nuehtro!', '¡El barco será nuehtro!', 28153),
(143189, 'esES', '¡Taz\'okun!', '¡Taz\'okun!', 28153),
(143188, 'esES', 'Es solo una herida superficial. Creo que aguantaré...', '', 28153),
(143185, 'esES', '', '¡Vais a arder!', 28153),
(143184, 'esES', '', '¡Arded! ¡Sí! ¡Arded!', 28153),
(143183, 'esES', '', '¿Buscáis azerita? ¡Tomad una poca!', 28153),
(143182, 'esES', '', '¡Oh, oh! Tengo que reiniciar el contador de \"días desde la última muerte horrible\".', 28153),
(143181, 'esES', '¡Nada vale esto!', '', 28153),
(143180, 'esES', '', '¡La falta de experiencia es letal!', 28153),
(143179, 'esES', '¡Por la Alianza!', '', 28153),
(143178, 'esES', '', 'Es un honor servir una vez más, Majestad. ¡Por la Alianza!', 28153),
(143177, 'esES', '', '¡Otro aspirante no apto!', 28153),
(143176, 'esES', 'Hoy nos habéis prestado un gran servicio. Lady Brisaveloz, adalid, os lo agradezco.', '', 28153),
(143175, 'esES', 'Puede que algunos de los nuestros tarden en confiar en estos elfos del Vacío, pero mientras sigan tus enseñanzas, serán bien recibidos en la Alianza.', '', 28153),
(143174, 'esES', '', 'Merezco... un plus de peligrosidad...', 28153),
(143173, 'esES', '', 'Yo seré su guía. Les enseñaré a controlar los susurros de las sombras. A cambio, lucharán junto a la Alianza contra todos sus enemigos.', 28153),
(143172, 'esES', '', 'Rey Wrynn, hemos encontrado a los sin\'dorei exiliados. El Vacío los ha cambiado, como a mí... Pero sus corazones y sus mentes les pertenecen.', 28153),
(143171, 'esES', '', 'Si quieres un trabajo bien hecho... ¡usa explosivos más grandes!', 28153),
(143170, 'esES', '', '¿Esta es la causa de que mis empleados se distraigan?', 28153),
(143169, 'esES', '', '¡Eh! ¿A dónde creéis que vais?', 28153),
(143168, 'esES', '¡¿Intrusos?! ¡¡¡Corred!!!', '¡¿Intrusos?! ¡¡¡Corred!!!', 28153),
(143167, 'esES', 'Hermana, no sé qué oscuridad anegó tu mente, pero no seguirá atormentando a nuestro pueblo.', '', 28153),
(143166, 'esES', '¡Todo controlado!', '', 28153),
(143165, 'esES', '¡Una fuga!', '', 28153),
(143164, 'esES', '', '¡No quiero más quejas sobre condiciones laborales peligrosas!', 28153),
(143163, 'esES', 'Aquí no estáis seguros. Abandonad este lugar.', '', 28153),
(143162, 'esES', '¡De todos modos, no es la mejor isla!', '', 28153),
(143161, 'esES', '¡Estamos condenados!', '', 28153),
(143160, 'esES', '¡Marchaos! Vuestro trabajo aquí ha acabado.', '', 28153),
(143159, 'esES', '¡Se ha liberado! ¡Atrás!', '', 28153),
(143158, 'esES', 'Ahora sois libres, hermanos y hermanas.', '', 28153),
(143157, 'esES', '', '¡Si os quejáis es que no estáis aguantando la respiración! ¡Si aspiráis gases tóxicos es vuestra culpa!', 28153),
(143156, 'esES', 'Volved con vuestras familias. Nosotros nos ocupamos.', '', 28153),
(143155, 'esES', '¡Volad, insensatos!', '', 28153),
(143154, 'esES', 'Que tu alma abandone su caparazón mortal y fluya hacia las aguas.', '', 28153),
(143153, 'esES', 'Escucha la canción de la tormenta y descansa.', '', 28153),
(143152, 'esES', 'No preguntes por quién doblan las campanas, doblan por ti.', '', 28153),
(143151, 'esES', '', '¡Por la Horda!', 28153),
(143150, 'esES', '', '¡Por la Horda!', 28153),
(143149, 'esES', '', '¡Suramar está con la Horda!', 28153),
(143148, 'esES', '', 'Durante milenios, Suramar ha estado aislada. Hoy pasa a formar parte de algo mayor. Acepto tu juramento de lealtad, Thalyssra.', 28153),
(143147, 'esES', '', 'Es hora de que los Nocheterna busquemos aliados en los reinos de Azeroth. Si nos aceptáis, nos sentiremos honrados de unirnos a vuestra causa.', 28153),
(143146, 'esES', '', 'La Horda es fuerza. Determinación. Individualidad. Los shal\'dorei también valoramos estos rasgos.', 28153),
(143145, 'esES', '', 'En efecto, Primera Arcanista.', 28153),
(143144, 'esES', '', 'Es un honor, Jefa de Guerra. He combatido junto a lady Liadrin y el Señor regente. Su valor honra a la Horda.', 28153),
(143143, 'esES', 'No temas, hermano. Las olas no juzgan tu superficie.', '', 28153),
(143142, 'esES', 'Mareas y corrientes conforman tus infortunios, alma doliente.', '', 28153),
(143141, 'esES', 'Tu espíritu intrépido descansará eternamente.', '', 28153),
(143140, 'esES', 'Que las profundidades abisales acojan tu alma cansada.', '', 28153),
(143139, 'esES', 'La madre de las mareas purificará tu carne impura.', '', 28153),
(143138, 'esES', 'Las corrientes te llevarán, oh, caído.', '', 28153),
(143137, 'esES', '¡La tierra os consumirá!', '', 28153),
(143136, 'esES', 'Mar al mar, polvo al polvo y marea a la marea.', '', 28153),
(143135, 'esES', '¡Os destrozaré!', '', 28153),
(143134, 'esES', '¡La sangre de Azeroth fluye por ti!', '', 28153),
(143133, 'esES', 'No permitamos que estas almas perdidas sigan vagando. Tenemos que hablar.', '', 28153),
(143132, 'esES', '¡Desata tu poder!', '', 28153),
(143131, 'esES', 'Están empapados, pero todavía se pueden usar. Estos instrumentos nos serán útiles.', '', 28153),
(143130, 'esES', 'Las nieblas del océano ocultan mucho, pero esta baliza nos permitirá llegar.', '', 28153),
(143129, 'esES', '¡Alzaos!', '', 28153),
(143128, 'esES', '', '$gBienvenido, hijo:Bienvenida, hija;. Puede que la vihta me haya abandonado, pero Pa\'ku no lo ha hecho.\n\nSiéntate conmigo y pregúntame lo que quierah sobre la gran loa. Te rehponderé lo mejor que pueda.', 28153),
(143127, 'esES', 'Bien, esta hoja aún está afilada. Una hoja afilada da seguridad.', '', 28153),
(143126, 'esES', 'Ya no causarás más daño.', '', 28153),
(143125, 'esES', '¿Cuánto vale tu sangre?', '', 28153),
(143124, 'esES', '', 'Jefa de guerra Sylvanas Brisaveloz, esta es la primera arcanista Thalyssra de Suramar.', 28153),
(143123, 'esES', '', 'Me uniré a los otros y esperaré mis órdenes.', 28153),
(143122, 'esES', '', 'Yo tengo mis dudas... pero haré lo que se me pide.', 28153),
(143121, 'esES', '', '¿Así que el mariscal Reade cree que tú eres la clave para expulsar al aquelarre?', 28153),
(143120, 'esES', '¡Dale con ganas!', '', 28153),
(143119, 'esES', 'Ya era hora.', '', 28153),
(143118, 'esES', '¡Ponle un poco de fuerza!', '', 28153),
(143117, 'esES', '¡Tira!', '', 28153),
(143116, 'esES', 'Vamos, Winston. Tenemos que combatir a las brujas.', '', 28153),
(143115, 'esES', 'Unos cuantos cortes profundos más y lo tendremos.', '', 28153),
(143114, 'esES', '¡Ya casi está! Solo un poco más.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'esES', 'Nuevas órdenes, ¿eh?', '', 28153),
(143112, 'esES', 'Gracias por entregarme las órdenes. Me presentaré ante la señorita Crestavía de inmediato.', '', 28153),
(143111, 'esES', 'Y yo que creía que esas historias eran fruto de la imaginación de algún historiador...', '', 28153),
(143110, 'esES', 'No erais nada más que parásitos.', '', 28153),
(143109, 'esES', '¿Entonces es cierto? ¿Se ha vuelto a formar la Orden de Ascuas?', '', 28153),
(143108, 'esES', 'Las heridas... deben curarse...', '', 28153),
(143107, 'esES', '', 'Cuenta con mi hoja.', 28153),
(143106, 'esES', '¡Habéis invadido mis dominios!', '', 28153),
(143105, 'esES', '', 'No me convencen todos esos abracadabras, pero cualquier cosa es mejor que quedarme aquí esperando a que el aquelarre nos mate.', 28153),
(143104, 'esES', '', 'Así que eres tú quien está detrás de la famosa \"Orden de Ascuas\"...', 28153),
(143103, 'esES', '<Entregar las órdenes del mariscal Reade>.', '<Entregar las órdenes del mariscal Reade>.', 28153),
(143102, 'esES', '', 'Los ensamblajes empiezan a entrar en el campo de batalla. Tras quedarse sin guerreros, crea un nuevo ejército. ¿Pero qué potencia las piedras?', 28153),
(143101, 'esES', '', '¿Qué puedo hacer por ti, $c?', 28153),
(143100, 'esES', '', 'Este es claramente Gorak Tul, su mayor líder. ¡Ah, dirige un ritual para crear los ensamblajes de piedra!', 28153),
(143099, 'esES', '<El teniente Mareasevera asiente ligeramente aceptando tu acercamiento>.', '', 28153),
(143098, 'esES', 'Un buen ejemplar, ¿verdad? La casa Crestavía es famosa por su destreza en el arte de la halconería.\n\nPor desgracia, la mayoría de nuestras mejores aves han caído bajo la maldición del aquelarre. Winston es uno de los pocos halcones Crestavía que han escapado al hechizo.\n\nLa situación es verdaderamente triste.', '', 28153),
(143097, 'esES', '', 'Pero... ¡Esto glorifica una matanza! ¡La gente de Kul Tiras ni siquiera tiene armas!', 28153),
(143096, 'esES', 'Algo perverso se agita en el bosque, continental. Por la noche, el antiguo monumento Drust que hay en su interior brilla con un poder profano.\n\nYo que tú evitaría viajar a ese lugar.', '', 28153),
(143095, 'esES', '', '¿Qué pasa, continental?\n\nPor si no te habías dado cuenta, estoy bastante ocupada.', 28153),
(143094, 'esES', 'ELIMINAR INTRUSO, PUR-PURIFICAR. PURIFICAR.', '', 28153),
(143093, 'esES', 'PROPAGACIÓN DE CORRUPCIÓN INMINENTE. ACT... ACTIVANDO LOS PR... PROTOCOLOS DE SEGURIDAD. INTR... INTRUSO LOCALIZADO.', '', 28153),
(143092, 'esES', 'ERROR... INTRUSIÓN... DE... DETECTADA... ESCANEANDO EN BUSCA DE... CORRUPCIÓN.', '', 28153),
(143091, 'esES', 'Uso de gas tóxico aprobado.', '', 28153),
(143090, 'esES', 'Voltaje aumentado.', '', 28153),
(143089, 'esES', 'Sistemas activados. Iniciando apaleamiento.', '', 28153),
(143088, 'esES', '', 'Parece que en este grabado hay... ¿civiles de Kul Tiras? ¿Marinos y granjeros?', 28153),
(143087, 'esES', '', 'Hasta su líder se retira del campo de batalla.', 28153),
(143086, 'esES', '', '¡JA! ¡Y aquí estamos defendiéndonos!', 28153),
(143085, 'esES', '', 'Qué curioso no ver a ninguno de sus ensamblajes en la batalla.', 28153),
(143084, 'esES', 'Ventura y Cía. le agradece la confianza. Disfrute de su paquete de tundas deluxe.', '', 28153),
(143083, 'esES', '', 'Es una victoria sobre otro asentamiento de Kul Tiras. Creo que la figura grande del centro es su líder legendario.', 28153),
(143082, 'esES', 'Ventura y Cía. le agradece la confianza. Disfrute de su paquete de tundas básico.', '', 28153),
(143081, 'esES', '¡Dame un par de meses y convertiré este lugar en un complejo de seis estrellas o más!', '', 28153),
(143080, 'esES', '¡Inútil! ¡NUNCA se compra la garantía extendida!', '¡Inútil! ¡NUNCA se compra la garantía extendida!', 28153),
(143079, 'esES', '¡Vale, vale! Espera... ¿Compro la garantía extendida?', '¡Vale, vale! Espera... ¿Compro la garantía extendida?', 28153),
(143078, 'esES', 'Vamos, adalid.', '', 28153),
(143077, 'esES', '¡Van a matarnos!', '¡Van a matarnos!', 28153),
(143076, 'esES', '¡No me metas prisa, estoy leyendo las condiciones de uso!', '¡No me metas prisa, estoy leyendo las condiciones de uso!', 28153),
(143075, 'esES', '¡Rápido, que vienen!', '¡Rápido, que vienen!', 28153),
(143074, 'esES', 'Solo necesitaba un pequeño descanso.', '', 28153),
(143073, 'esES', 'Cálmate, buena chica. Cálmate.', '', 28153),
(143072, 'esES', 'Error... de sistema. Fallo en la devolución del cambio...', '', 28153),
(143071, 'esES', '¿Quién quiere volar? ¿Te apetece volar? ¡Vamos a volar!', '', 28153),
(143070, 'esES', '¡No se muerde!', '', 28153),
(143069, 'esES', 'Rutina de control de daños activada.', '', 28153),
(143068, 'esES', 'Dañar esta unidad supone una infracción de las condiciones de uso.', '', 28153),
(143067, 'esES', '¡Bombas van!', '¡Bombas van!', 28153),
(143066, 'esES', '¡Cuidado ahí abajo, escoria!', '¡Cuidado ahí abajo, escoria!', 28153),
(143065, 'esES', 'Oye, tú. ¡Vuelve al trabajo!', 'Oye, tú. ¡Vuelve al trabajo!', 28153),
(143064, 'esES', 'Fuerza letal autorizada.', '', 28153),
(143063, 'esES', 'Aforo máximo superado. Dispersaos.', '', 28153),
(143062, 'esES', 'Servicios funerarios disponibles a buen precio.', '', 28153),
(143061, 'esES', 'Otro cliente satisfecho.', '', 28153),
(143060, 'esES', 'Ventura y Cía. no se hace responsable de los miembros amputados.', '', 28153),
(143059, 'esES', '¡La Horda se ha defendido de un ataque!', '¡La Horda se ha defendido de un ataque!', 28153),
(143058, 'esES', '¡Y dispersaos! Esos perros de la Alianza enviarán refuerzos hacia aquí.', '', 28153),
(143057, 'esES', '', '¡Cuando ehte barco llegue al puerto, me convertiré en capitana! ¡Máh oh vale enteraroh y aprender a inclinaroh!', 28153),
(143056, 'esES', '', '¡Ehtoh prisioneroh no saben lo afortunadoh que son! Pronto se reunirán con Zul.', 28153),
(143055, 'esES', '', '¡Si vamoh a tomar ehte puerto, tendréih que ehforzaroh máh!', 28153),
(143054, 'esES', 'No puedo... evit... ¡AAAARGG!', '', 28153),
(143050, 'esES', '¡No! ¡No moriré aquí! ¡No eh mi hora!', '', 28153),
(143049, 'esES', '¿Cómo... lo sabía...?', '', 28153),
(143048, 'esES', 'No... ¡Ehto no puede ehtar pasando!', '', 28153),
(143047, 'esES', '¡Ereh fuerte, pero mi visión lo eh máh!', '', 28153),
(143046, 'esES', '¡Largo! ¡Oh lo ordeno!', '', 28153),
(143045, 'esES', '¡Elegidoh! ¡Vuehtro maehtro oh necesita!', '', 28153),
(143044, 'esES', '¡Soih vosotroh quieneh moriréih aquí!', '', 28153),
(143043, 'esES', '¡No me intimidah, viejo!', '', 28153),
(143042, 'esES', 'Eh verdad, no puedo. Pero mi camarada sí.', '', 28153),
(143041, 'esES', 'Todoh sabemoh que no acabaráh conmigo. No puedeh detenerme.', '', 28153),
(143040, 'esES', 'Buena chica. ¡Ya casi es la hora de una chuchería!', '', 28153),
(143039, 'esES', 'Ehte juego me aburre. Hah entregado tu mensaje, eh hora de afrontar tu dehtino.', '', 28153),
(143038, 'esES', 'Zul engulle la poción con un largo trago. El sabor le hace estremecerse.', '', 28153),
(143037, 'esES', 'La veráh enseguida. No puedeh equivocarte.', '', 28153),
(143036, 'esES', 'Suh ehbirroh intentarán pararte. Ehtate alerta.', '', 28153),
(143035, 'esES', 'Mmm.', '', 28153),
(143034, 'esES', 'Ven aquí. Eh la hora.', '', 28153),
(143033, 'esES', 'Bien. Ahora cambia una de lah pocioneh de Vol\'jamba por la que te he dado.', '', 28153),
(143032, 'esES', 'Ahora que lo pienso... muévela un poco a la izquierda.', '', 28153),
(143031, 'esES', 'Ahora coloca la urna cerca del arco.', '', 28153),
(143030, 'esES', 'Ten las armas preparadas fuera de la embajada, $p. Estos Zandalari carecen de la fuerza y la voluntad necesarias para mantener el control. Necesitan una Jefa de Guerra fuerte como la nuestra.\n\nBueno, ¿y qué puedo hacer por ti?', 'Ten las armas preparadas fuera de la embajada, $p. Estos Zandalari carecen de la fuerza y la voluntad necesarias para mantener el control. Necesitan una Jefa de Guerra fuerte como la nuestra.\n\nBueno, ¿y qué puedo hacer por ti?', 28153),
(143029, 'esES', 'Si ves a algún miembro de la Alianza merodeando, avísame. Me ocuparé de él.\n\nMientras tanto, ¿qué es lo que buscas?', 'Si ves a algún miembro de la Alianza merodeando, avísame. Me ocuparé de él.\n\nMientras tanto, ¿qué es lo que buscas?', 28153),
(143028, 'esES', 'Debo admitir una cosa sobre los Zandalari, saben cómo construir una embajada. ¡Y esta ciudad es enorme!\n\n¿Te has perdido?', 'Debo admitir una cosa sobre los Zandalari, saben cómo construir una embajada. ¡Y esta ciudad es enorme!\n\n¿Te has perdido?', 28153),
(143027, 'esES', 'Estoy ocupado. Date prisa.', 'Estoy ocupada. Date prisa.', 28153),
(143026, 'esES', '¿Qué necesitas, $pr?', '¿Qué necesitas, $pr?', 28153),
(143025, 'esES', '¡Gloria a la Jefa de Guerra! ¿Buscas algo?', '¡Gloria a la Jefa de Guerra! ¿Buscas algo?', 28153),
(143024, 'esES', 'Esta enorme embajada demuestra que los Zandalari respetan la fuerza de nuestra Jefa de Guerra. También deberían temerla.\n\nBueno, ¿qué quieres?', 'Esta enorme embajada demuestra que los Zandalari respetan la fuerza de nuestra Jefa de Guerra. También deberían temerla.\n\nBueno, ¿qué quieres?', 28153),
(143023, 'esES', 'Esta humedad hace que me suden los huesos. ¿Qué puedo hacer por ti?', 'Esta humedad hace que me suden los huesos. ¿Qué puedo hacer por ti?', 28153),
(143022, 'esES', 'Vamos progresando, grandullón. Un día todo esto será nuestro.', '', 28153),
(143021, 'esES', '¿Para qué te pagamos? ¿Para que holgazanees?', '', 28153),
(143020, 'esES', '', 'Puede que la muerte sea el auténtico legado de los Brisaveloz.', 28153),
(143019, 'esES', '', 'Sí. A veces siento que he muerto dos veces. La primera, cuando nos dieron por perdidos en Draenor. La segunda, cuando me golpeó la sombra de la naaru caída.', 28153),
(143018, 'esES', 'Resulta inquietante observar estos monumentos a nuestra muerte.', '', 28153),
(143017, 'esES', '', 'Ha llegado el momento, Turalyon. Debo ver mi hogar con mis propios ojos... y escuchar las razones de Sylvanas para convertirse en Jefa de Guerra.', 28153),
(143016, 'esES', 'Cada una tenéis vuestro propio camino. Si la Luz quiere que esos caminos se crucen, lo harán. No hay por qué forzar la mano del destino.', '', 28153),
(143015, 'esES', 'No tienes por qué ir. Nadie te obliga a verla.', '', 28153),
(143014, 'esES', '', 'Mejor que nadie, amor mío.', 28153),
(143013, 'esES', 'Estás nerviosa. Lo disimulas bien... pero te conozco.', '', 28153),
(143012, 'esES', 'Sé que se avecinan tiempos difíciles, pero pase lo que pase... ¡nunca olvidéis que servimos a Azeroth!', '', 28153),
(143011, 'esES', 'Jamás había visto nada similar a la energía que late en el interior de vuestras armas. Pero recordad: el poder tiene un precio.', '', 28153),
(143010, 'esES', '¡Sí! ¡Habéis neutralizado la espada de Sargeras! Azeroth sigue herida... pero hemos ganado un tiempo muy valioso.', '', 28153),
(143009, 'esES', '¡Todos juntos! ¡Por Azeroth!', '', 28153),
(143008, 'esES', 'Alzadlas, todos a una... ¡Extraed la corrupción de la hoja del Titán Oscuro!', '', 28153),
(143007, 'esES', 'Los únicos objetos capaces de contener ese tremendo poder... son vuestras armas.', '', 28153),
(143006, 'esES', 'La espada de Sargeras está envenenando la sangre del mundo.', '', 28153),
(143005, 'esES', 'Venid a Silithus... ¡mientras aún quede un mundo por el que luchar!', '', 28153),
(143004, 'esES', 'La tensión aumenta... pero os pido que luchéis unidos una vez más.', '', 28153),
(143003, 'esES', 'Campeones, unificasteis vuestras órdenes y combatisteis juntos para expulsar a la Legión de Azeroth.', '', 28153),
(143002, 'esES', 'Se avecina una tormenta. Si no encontramos la forma de curar a Azeroth... lo demás será irrelevante.', '', 28153),
(143001, 'esES', 'No sé cómo arreglarlo, no creo que nadie lo sepa, pero debemos intentarlo.', '', 28153),
(143000, 'esES', 'Desde que volvimos de Argus, los gritos de Azeroth se han vuelto... abrumadores. Contienen tanto dolor...', '', 28153),
(142999, 'esES', 'Adalid... Qué alegría ver un rostro amigo en estos tiempos oscuros.', '', 28153),
(142998, 'esES', 'Aún ehtamoh a la ehpera, Princesa, pero tenemoh una pihta sobre el loa Krag\'wa.', '', 28153),
(142997, 'esES', '', '... Y eso eh lo que le pasó a Torga. ¿Sabemoh algo de loh refuerzoh de la Horda?', 28153),
(142996, 'esES', 'Ya casi hemoh acabado con ehto. Solo hay que aguantar un poco máh.', '', 28153),
(142995, 'esES', 'No puedo creer que esos monstruos destriparan a Torga...', '', 28153),
(142994, 'esES', 'Bah, Torga está muerto y ahora no tengo nada que contar a los demás cuando vuelva.', '', 28153),
(142993, 'esES', '¿Donde está Kisha? Pensé que estaría aquí para darnos indicaciones...', '', 28153),
(142992, 'esES', 'De acuerdo, iré a la Cuenca Tenebrosa y veremos si se arma un buen lío.', '', 28153),
(142991, 'esES', 'Eh... Bueno, supongo que un combate contra una horda de trols de sangre puede ser una historia interesante. De acuerdo, iré a la Cuenca Tenebrosa.', '', 28153),
(142990, 'esES', '¿Que habéis QUÉ? No me pienso perder esta historia, me voy a la Cuenca Tenebrosa.', '', 28153),
(142989, 'esES', 'Vale, Kisha, nos vamos a la Cuenca Tenebrosa. Reclutaremos a los tortolianos que nos encontremos. Adalid, ocúpate tú de los que queden.', '', 28153),
(142988, 'esES', '', 'Iré a la Cuenca Tenebrosa mientrah tú te ocupah de loh tortolianoh del camino.', 28153),
(142987, 'esES', '¡$n, a los cañones!', '', 28153),
(142986, 'esES', 'Buena suerte, $p. En cuanto a mí, voy a poner a prueba mis habilidades en Vallefresno. ¡Por la Horda!', '', 28153),
(142985, 'esES', 'El Brisa de Pa\'ku y el Garra de Rezan han ido hahta el fin del mundo y han vuelto. Asegúrate de que recorren el camino de vuelta a casa.', '', 28153),
(142984, 'esES', 'Cuando loh barcoh volvieron, una ohcuridad loh envolvía. Tuve una sensación muy desagradable en la boca del ehtómago.', '', 28153),
(142983, 'esES', 'El Brisa de Pa\'ku fue mi hogar durante muchoh añoh. Mi corazón, como ehte puerto, ha ehtado vacío dehde que partió.', '', 28153),
(142982, 'esES', 'El rugido de Anji el Atronador te colma de vigor.', '', 28153),
(142981, 'esES', '¡Eh! ¡Sube al barco! ¡El capitán dice que el Brisa de Pa\'ku ehtá en problemah!', '', 28153),
(142980, 'esES', '', 'Comandante, hemos venido a ayudar. ¡El dique no se romperá hoy!', 28153),
(142979, 'esES', '', 'Vayamos al dique. ¡Al comandante Reed no le gusta esperar!', 28153),
(142977, 'esES', '¡Tú no sirves para este sitio!', '', 28153),
(142976, 'esES', '¡Eres tan idiota como cobarde!', '', 28153),
(142975, 'esES', '¡Te desprecio, $gasqueroso bribón:asquerosa bribona;!', '', 28153),
(142974, 'esES', '¡Déjame, canalla!', '', 28153),
(142973, 'esES', '¡Te propinaré una paliza descomunal!', '', 28153),
(142972, 'esES', '¡Me hartaré de aporrearte aunque me aturda con tus aullidos!', '', 28153),
(142971, 'esES', '¡Juro que con esta mano que te extraeré los dientes!', '', 28153),
(142970, 'esES', '¡Atención!', '', 28153),
(142969, 'esES', '', 'Por el poder de la casa Crestavía, yo os nombro inquisidores de la Orden de Ascuas.', 28153),
(142968, 'esES', '', '... y en un rayo de esperanza contra el enemigo eterno.', 28153),
(142967, 'esES', '', 'Hoy os convertís en la hoja que atraviesa a los malvados...', 28153),
(142966, 'esES', '', 'Hermanos y hermanas, hoy os convertís en el fuego cuya llama aleja la oscuridad.', 28153),
(142965, 'esES', '', 'Ah, aquí está.', 28153),
(142964, 'esES', '', 'Había un discurso de iniciación en algún lugar del tomo. Veamos...', 28153),
(142963, 'esES', '', 'Gracias por cederme a tus hombres, Mariscal. ¡Ya empezamos a parecer una orden de verdad!', 28153),
(142962, 'esES', 'He ehtado ehperando pa ver al Rey durante varioh díah. Uno pensaría que ehtaría máh interesado en lo que hacen loh goblinh en ehtah tierrah.', '', 28153),
(142961, 'esES', 'Tenemos buenos soldados cerca de aquí, mi señora. Serán unos reclutas excelentes para tu Orden de Ascuas.', '', 28153),
(142960, 'esES', '', 'Mariscal, creo que hemos encontrado armas efectivas contra el aquelarre. Necesitamos soldados capaces de empuñarlas.', 28153),
(142959, 'esES', '¡Nunca traicionaría a loh loa ni a la ciudad!', '', 28153),
(142958, 'esES', 'Adoro a Pa\'ku. ¡La magia de sangre ehtá prohibida!', '', 28153),
(142957, 'esES', 'Ehtoy diciendo la verdad. ¡No sé nada de reliquiah de sangre!', '', 28153),
(142956, 'esES', '¡Soy inocente! ¡Piedad, por favor!', '', 28153),
(142955, 'esES', 'Nunca traficaría con reliquiah de sangre. ¡La magia de sangre eh maligna!', '', 28153),
(142954, 'esES', '¡No he vihto ninguna reliquia de sangre!', '', 28153),
(142953, 'esES', '¡No sé de qué ehtáh hablando!', '', 28153),
(142952, 'esES', '¡No he hecho nada malo!', '', 28153),
(142951, 'esES', 'No me obligueh a apuñalarte otra vez...', '', 28153),
(142950, 'esES', '¿A quién le vendihte lah reliquiah de sangre?', '', 28153),
(142949, 'esES', 'Me dah ahco, traidor.', '', 28153),
(142948, 'esES', 'Te voy a hacer sufrir, Pro\'ditor. Te daremoh un cahtigo ejemplar.', '', 28153),
(142947, 'esES', 'Si confiesah, te prometo que te concederé una muerte rápida.', '', 28153),
(142946, 'esES', 'Ereh la peor ehcoria que he vihto jamáh, Pro\'ditor. ¡La magia de sangre ehtá matando a nuehtra gente!', '', 28153),
(142945, 'esES', 'Sabemoh que hah ehtado traficando con reliquiah de sangre en la ciudad.', '', 28153),
(142944, 'esES', '¡Cuéntanoh cómo conseguihte lah reliquiah de sangre, Pro\'ditor!', '', 28153),
(142943, 'esES', 'Ehta ehcoria ha ehtado pasando reliquiah de sangre de contrabando a nuehtra ciudad.\n\nConfesará y, dehpuéh, le daremoh un cahtigo ejemplar.', '', 28153),
(142942, 'esES', '¡No he hecho nada malo! ¡Díselo!', '', 28153),
(142941, 'esES', '(Marcharse)', '(Marcharse)', 28153),
(142940, 'esES', '<Los restos sangrientos y andrajosos de la criminal fugada Teshyambi son casi irreconocibles. Parece obra de los raptores cercanos>.', '<Los restos sangrientos y andrajosos de la criminal fugada Teshyambi son casi irreconocibles. Parece obra de los raptores cercanos>.', 28153),
(142939, 'esES', 'Sé quién eres, Mojoba. Ve a Vol\'dun y vive tu exilio en paz.', 'Sé quién eres, Mojoba. Ve a Vol\'dun y vive tu exilio en paz.', 28153),
(142938, 'esES', '¿Quién ereh? ¿Qué quiereh, eh?', '', 28153),
(142937, 'esES', 'Lo siento, pero te han exiliado a Vol\'dun por tus crímenes.', 'Lo siento, pero te han exiliado a Vol\'dun por tus crímenes.', 28153),
(142936, 'esES', '¡Chist! Me ehcondo de loh raptoreh y de Zulajin. Tengo que volver a Zuldazar.', '', 28153),
(142935, 'esES', '', 'Trabajas bien... para haberte escapado de la cárcel.', 28153),
(142934, 'esES', '', 'Ahora que la prisión está bajo control y tenemos las llaves, podemos empezar a poner la azerita a buen recaudo y liberar a los rehenes.', 28153),
(142933, 'esES', '', 'Parece que lady Gobernalle tendrá que buscar pronto un nuevo sobrestante.', 28153),
(142932, 'esES', '¡Cuidado con el fuego! Te hablo a ti, lanzallamas. Si esta munición de azerita explota, ¡volaremos en mil pedazos!', '', 28153),
(142931, 'esES', '¡Preparaos! ¡Ya vienen!', '', 28153),
(142930, 'esES', '', 'Terminaremos de asegurar los niveles inferiores mientras os abrís paso hasta el sobrestante.', 28153),
(142929, 'esES', '', 'Bien hecho. Parece que lo tenéis todo bajo control.', 28153),
(142928, 'esES', 'Cuando le echemos el guante a los rehenes del sobrestante, ¡nos haremos asquerosamente ricos!', '', 28153),
(142927, 'esES', '¡Venga, chicos! ¡Derribad esas puertas!', '', 28153),
(142926, 'esES', '', 'Espero que así sea, o la primera tarea de tu sustituto será ver cómo te ahogas con el resto de esa escoria.', 28153),
(142925, 'esES', 'Mis disculpas, lady Gobernalle. Confío en que mis hombres restaurarán el orden pronto.', '', 28153),
(142924, 'esES', '', '¡Korgus! ¿Por qué no has inundado los niveles inferiores para ahogar a estas ratas?', 28153),
(142923, 'esES', '', '¡Uf! ¿Tuvisteis que arrastraros por ahí para escapar? No os pongáis en la dirección del viento.', 28153),
(142922, 'esES', '', 'Esa criatura debe de ser la razón por la que el sobrestante no tenía demasiadas patrullas en este lado de la isla. Buen trabajo.', 28153),
(142921, 'esES', '', 'Nos ocuparemos de los guardias del perímetro mientras vais a la reja de las alcantarillas. Aún deberían conducir al interior de la prisión.', 28153),
(142920, 'esES', '', 'Según nos han informado, las llaves del alijo de azerita y del ala de los rehenes las tiene el sobrestante... colgadas del cuello.', 28153),
(142919, 'esES', '', '¡Con cautela! Aún no nos han visto.', 28153),
(142918, 'esES', '¿Tengo que hacerlo?', '', 28153),
(142917, 'esES', '¿Qué quieres?', '', 28153),
(142916, 'esES', 'Listo para la acción.', '', 28153),
(142915, 'esES', '¡Han destruido nuestro cuartel!', '', 28153),
(142914, 'esES', 'Necesitaremos refuerzos para ganar esta guerra.', '', 28153),
(142913, 'esES', '¡Vuelta al trabajo!', '', 28153),
(142912, 'esES', '¡El edificio no se va a construir solo!', '', 28153),
(142911, 'esES', '¡Golpea con ese martillo!', '', 28153),
(142910, 'esES', '', 'Alleria se tensa, desafiante.', 28153),
(142909, 'esES', '¡Me has salvado la vida!', '¡Me has salvado la vida!', 28153),
(142908, 'esES', 'Debería ser capaz de ponerme a salvo solo. Gracias.', 'Debería ser capaz de ponerme a salvo sola. Gracias.', 28153),
(142907, 'esES', 'Sus ataques son implacables. Gracias por tu ayuda.', 'Sus ataques son implacables. Gracias por tu ayuda.', 28153),
(142906, 'esES', 'No olvidaré tu valor.', 'No olvidaré tu valor.', 28153),
(142905, 'esES', '¡Pensé que no lo contaba!', '¡Pensé que no lo contaba!', 28153),
(142904, 'esES', '¡A nuestra aldea le vendrían bien más héroes como tú!', '¡A nuestra aldea le vendrían bien más héroes como tú!', 28153),
(142903, 'esES', 'Venga a los que no nos pudimos salvar.', 'Venga a los que no nos pudimos salvar.', 28153),
(142902, 'esES', '¡Esos nagas son unos monstruos!', '¡Esos nagas son unos monstruos!', 28153),
(142901, 'esES', '¡Os voy a clavar este chafarote entre las costillas!', '', 28153),
(142900, 'esES', '¡Los intrusos están entrando por las cloacas!', '', 28153),
(142898, 'esES', 'Esta piedra canta una canción silenciosa y poderosa. Solo hay alguien capaz de oír esta melodía, y más vale que nunca llegue a este lugar.', '', 28153),
(142897, 'esES', 'He visto suficiente. Esta piedra es malvada y debe ser destruida.', '', 28153),
(142894, 'esES', 'Dudo que la entregue por las buenas, así que tendréis que arrancársela a su cadáver.', '', 28153),
(142893, 'esES', 'Nuestra siguiente presa está al sur. Será mejor que os mováis rápido.', '', 28153),
(142892, 'esES', 'Me fastidia que destruir esa nave vaya a beneficiar a los habitantes de Kul Tiras.', '', 28153),
(142891, 'esES', 'Seguro que la Dama Oscura aprecia vuestra ayuda.', '', 28153),
(142890, 'esES', '', 'Lo haré encantada, Señor regente. Nos vemos en Lunargenta, adalid.', 28153),
(142889, 'esES', '¡Excelente! Lady Liadrin, vuelve a Orgrimmar y dale las buenas noticias a la Jefa de Guerra.', '', 28153),
(142888, 'esES', '', 'En nombre de los Nocheterna, acepto tu oferta. De ahora en adelante, Suramar lucha por la Horda.', 28153),
(142887, 'esES', 'Eso es lo que os ofrece la Horda, Primera Arcanista. Uníos a nosotros. Os abrimos las puertas de Lunargenta.', '', 28153),
(142886, 'esES', '', 'Suramar siempre será nuestro hogar, pero entre mi gente hay quienes desean explorar el mundo y recuperar nuestro lugar en Azeroth. Para ello, necesitamos aliados.', 28153),
(142885, 'esES', '', 'Nuestros aliados nos dan fuerza... pero no hemos olvidado quiénes somos.', 28153),
(142884, 'esES', '', 'Al contrario: este conflicto me ha mostrado tu dedicación hacia tu pueblo. Veo que la Horda os ha permitido conservar vuestras tradiciones, algo fundamental para nosotros.', 28153),
(142883, 'esES', 'Lamento que hayas tenido que presenciar eso, Thalyssra. No es lo que tenía planeado para tu visita.', '', 28153),
(142882, 'esES', '', 'Como ordenes, Señor regente. Por ahora.', 28153),
(142881, 'esES', '¡Basta! Alleria, vete de inmediato. Aunque sea por accidente, tu presencia es una amenaza para Quel\'Thalas. Vuelve a Ventormenta. Lunargenta ya no es tu hogar.', '', 28153),
(142880, 'esES', '', '¡No permitiré que me apresen en mi propia tierra!', 28153),
(142879, 'esES', '¡Guardias! Apresad a esta boicoteadora.', '', 28153),
(142878, 'esES', 'La Fuente del Sol está a salvo. Tu ayuda ha sido muy valiosa, Thalyssra. Y la tuya, adalid.', '', 28153),
(142877, 'esES', '¡Solo estáis retrasando lo inevitable! Obtendré mi recompensa...', '', 28153),
(142876, 'esES', '', '¡Ahora! ¡Unid vuestro poder al mío!', 28153),
(142875, 'esES', 'La puerta se abre. Sí... Esto servirá a nuestros propósitos.', '', 28153),
(142874, 'esES', '', 'Dinos qué hacer y te prestaremos nuestra fuerza.', 28153),
(142873, 'esES', '', 'Puedo cerrar la falla, pero necesitaré ayuda.', 28153),
(142872, 'esES', 'Algo intenta abrir una falla en la cámara. Si lo consigue, podríamos perder la Fuente del Sol.', '', 28153),
(142871, 'esES', 'Empieza a lanzar el hechizo, Rikal.', 'Empieza a lanzar el hechizo, Rikal.', 28153),
(142870, 'esES', 'La marea cambiará antes o después. Siempre lo hace.', '', 28153),
(142869, 'esES', '¡Te está fallando el agarre!', '', 28153),
(142868, 'esES', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t¡%s se prepara para lanzar |cFFFF0000|Hspell:257785|h[Dagas deslumbrantes]|h|r! ¡Escóndete!', '', 28153),
(142867, 'esES', 'Bal\'a dash, malanore.', '', 28153),
(142866, 'esES', 'Debemos recorrer nuestro propio camino.', '', 28153),
(142865, 'esES', 'Nuestro pueblo representa un nuevo futuro.', '', 28153),
(142864, 'esES', 'No des ninguna verdad por hecho.', '', 28153),
(142863, 'esES', 'El universo está repleto de misterios.', '', 28153),
(142862, 'esES', 'Nos aguardan nuevas oportunidades.', '', 28153),
(142861, 'esES', 'El pasado está escrito. El futuro no.', '', 28153),
(142860, 'esES', 'Shorel\'aran.', '', 28153),
(142859, 'esES', 'Nuestro pueblo no teme a las sombras.', '', 28153),
(142858, 'esES', 'No existe la verdad absoluta.', '', 28153),
(142857, 'esES', 'Los susurros no nos controlan.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'esES', 'Debemos controlar los impulsos.', '', 28153),
(142855, 'esES', 'No temas el poder. Contrólalo.', '', 28153),
(142854, 'esES', 'Considera todas las posibilidades.', '', 28153),
(142853, 'esES', 'No conseguirás provocarme con tu comportamiento infantil.', '', 28153),
(142852, 'esES', '¿Que si recuerdo la Fuente del Sol? Bah, hace siglos que la he olvidado.', '', 28153),
(142851, 'esES', 'Si se abriese un portal hacia la nada infinita bajo tus pies y te consumiese en mi presencia, no dudes que sería pura casualidad. Estas cosas pasan a veces.', '', 28153),
(142850, 'esES', 'Claro, una fuerza cósmica conocida por inducir a la locura me transforma físicamente y de repente se me considera \"sospechoso\". Si eso no es discriminación...', '', 28153),
(142849, 'esES', '¿Qué buscas?', '', 28153),
(142848, 'esES', 'Ofrezco productos poco comunes de reinos lejanos.', '', 28153),
(142847, 'esES', 'Todo tiene un precio... si quieres pagarlo.', '', 28153),
(142846, 'esES', 'Espero que tu adquisición sea satisfactoria.', '', 28153),
(142845, 'esES', 'Gracias por ver la mercancía.', '', 28153),
