(142820, 'esES', '', 'Bal\'a dash, malanore.', 28153),
(142819, 'esES', 'Esa criatura bloquea vuestra vía de escape. Debéis matarla para llegar a nuestros barcos en la orilla opuesta.', '', 28153),
(142818, 'esES', '¡¿Lady Gobernalle tiene un kraken?!', '', 28153),
(142817, 'esES', 'Gobernalle nos ha proporcionado una buena salida. Es hora de partir y dejar que el fuego consuma Boralus.', '', 28153),
(142816, 'esES', 'Esta bestia está usando un arma potenciada con azerita.', '', 28153),
(142815, 'esES', 'Bal\'a dash, malanore.', '', 28153),
(142814, 'esES', 'Recorre tu propio camino.', '', 28153),
