(142810, 'esES', 'Te saludo.', '', 28153),
(142809, 'esES', 'Se han abierto nuevas puertas ante nosotros.', '', 28153),
(142808, 'esES', 'Shorel\'aran.', '', 28153),
(142807, 'esES', 'Hay fuerza en la sombra.', '', 28153),
(142806, 'esES', 'Decidimos nuestro destino.', '', 28153),
(142805, 'esES', 'Los susurros no me controlan.', '', 28153),
(142804, 'esES', 'Mantén el control. Siempre.', '', 28153),
(142803, 'esES', 'El poder debe usarse, no temerse.', '', 28153),
(142802, 'esES', 'Ese barco está cargado de azerita. Deshaceos de la tripulación, y yo sacaré el cargamento de la ciudad.', '', 28153),
