(142468, 'esES', '', 'Volvemos al mundo.', 28153),
(142467, 'esES', '', 'Camina con la luz de la luna.', 28153),
(142466, 'esES', '', 'Son tiempos inciertos. Ve con cuidado.', 28153),
(142465, 'esES', '', 'Nor\'bethos Suramar.', 28153),
(142464, 'esES', '', 'Que la noche te guíe.', 28153),
(142463, 'esES', '', 'Kal\'theros maldin.', 28153),
(142462, 'esES', 'Le compré esto a un explorador. Él lo llamaba \"cámara SELFI\". ¿Tienes idea de qué es?', '', 28153),
(142461, 'esES', 'Suramar sigue siendo una joya refulgente entre los escombros del Cataclismo.', '', 28153),
(142460, 'esES', '¡Exploraremos el mundo y les demostraremos que seguimos siendo relevantes!', '', 28153),
(142459, 'esES', 'Tú pareces lo bastante joven como para usar este artilugio. ¿Puedes hacer que me funcione?', '', 28153),
(142455, 'esES', '¿Qué deseas?', '', 28153),
(142454, 'esES', 'Echa un vistazo, vendo de todo.', '', 28153),
(142453, 'esES', 'Mis mercancías son exquisitas.', '', 28153),
(142452, 'esES', '¡No encontrarás una ganga así!', '', 28153),
(142451, 'esES', 'Un placer hacer negocios.', '', 28153),
(142450, 'esES', 'Vuelve cuando quieras.', '', 28153),
