INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142041, 'esES', '', 'Mordedura de demonio es un ataque que inflige daño y genera furia.', 28153),
(142040, 'esES', 'Usa Mordedura de demonio contra el muñeco-diana.', '', 28153),
(142039, 'esES', 'Mordedura de demonio es un ataque que inflige daño y genera furia.', '', 28153),
(142038, 'esES', 'Ahora que está a tu alcance, es hora de atacar con saña.', '', 28153),
(142036, 'esES', '', 'Usa Carga vil para lanzarte contra el muñeco-diana.', 28153),
(142035, 'esES', '¿Qué ha traído el viento?', '', 28153),
(142034, 'esES', 'El río nos sustenta.', '', 28153),
(142033, 'esES', 'Saludos, viajante.', '', 28153),
(142032, 'esES', '', 'Eliges dónde y cuándo entablar combate con una agilidad asombrosa.', 28153),
(142031, 'esES', '', 'Como cazadora de demonios Devastación, has sacrificado mucho para blandir el poder vil de los demonios.', 28153),
(142030, 'esES', '', 'Como cazador de demonios Devastación, has sacrificado mucho para blandir el poder vil de los demonios.', 28153),
(142029, 'esES', 'Monte Alto resiste.', '', 28153),
(142028, 'esES', 'Como cazadora de demonios Devastación, has sacrificado mucho para blandir el poder vil de los demonios.', '', 28153),
(142027, 'esES', 'Usa Carga vil para lanzarte contra el muñeco-diana.', '', 28153),
(142026, 'esES', 'Eliges dónde y cuándo entablar combate con una agilidad asombrosa.', '', 28153),
(142025, 'esES', 'Como cazador de demonios Devastación, has sacrificado mucho para blandir el poder vil de los demonios.', '', 28153),
(142022, 'esES', 'Parece que ya tieneh un plan en mente, Princesa.', '', 28153),
(142021, 'esES', '', 'Ese tal G\'huun debe de ehtar dándoleh poder... Demasiado pa nosotroh. Hay que cambiar de ehtrategia.', 28153),
(142020, 'esES', '¡¿Que tienen qué?! ¿No habíah dicho que no eran máh que unoh catetoh?', '', 28153),
(142019, 'esES', '¡Escuchad! ¡Lord Canto Tormenta le ha transmitido su palabra a los fieles!', '¡Escuchad! ¡Lord Canto Tormenta le ha transmitido su palabra a los fieles!', 28153),
(142018, 'esES', 'El supervisor Scripps se ha vuelto loco. ¡Y los demás también!', 'El supervisor Scripps se ha vuelto loco. ¡Y los demás también!', 28153),
(142017, 'esES', '¡Creía que iba a desmayarme!', '¡Creía que iba a desmayarme!', 28153),
(142016, 'esES', '¡No dejarán que nos vayamos!', '¡No dejarán que nos vayamos!', 28153),
(142015, 'esES', '¡Que las mareas te bendigan!', '¡Que las mareas te bendigan!', 28153),
(142014, 'esES', '¡Mil gracias, visitante!', '¡Mil gracias, visitante!', 28153),
(142013, 'esES', '¡Los cosechadores se han vuelto en nuestra contra!', '¡Los cosechadores se han vuelto en nuestra contra!', 28153),
(142012, 'esES', '¡Que las mareas me protejan!', '¡Que las mareas me protejan!', 28153),
(142011, 'esES', '¡Sabía que el mar no nos había abandonado!', '¡Sabía que el mar no nos había abandonado!', 28153),
(142007, 'esES', 'Recibirás tu... merecido...', 'Recibirás tu... merecido...', 28153),
(142006, 'esES', 'Insu... bordinación...', 'Insu... bordinación...', 28153),
(142004, 'esES', 'Te... despido...', 'Te... despido...', 28153),
(142003, 'esES', 'Mis mascotas tienen hambre.', '', 28153),
(142002, 'esES', '¡Romper!', '', 28153),
(142001, 'esES', 'Devolved... mi cuerpo... al mar...', '', 28153),
(142000, 'esES', 'Es difícil... encontrar... buen servicio...', 'Es difícil... encontrar... buen servicio...', 28153),
(141999, 'esES', 'Te castigarán... por... esto...', 'Te castigarán... por... esto...', 28153),
(141998, 'esES', 'Oh... maldición...', 'Oh... maldición...', 28153),
(141997, 'esES', 'Nada sobrevive a las profundidades.', '', 28153),
(141996, 'esES', '¿Es... lo mejor... que sabes hacer...?', '¿Es... lo mejor... que sabes hacer...?', 28153),
(141995, 'esES', 'Rata... indigna...', 'Rata... indigna...', 28153),
(141994, 'esES', '¡¿Acaso te he ordenado parar?!', '¡¿Acaso te he ordenado parar?!', 28153),
(141993, 'esES', '¡En pedazos!', '', 28153),
(141992, 'esES', '¡Servirás de ejemplo para el resto!', '¡Servirás de ejemplo para el resto!', 28153),
(141991, 'esES', '¡Se acabó el descanso, piojo!', '¡Se acabó el descanso, piojo!', 28153),
(141990, 'esES', '¡Te arrepentirás de desafiarme!', '¡Te arrepentirás de desafiarme!', 28153),
(141989, 'esES', '¡¿Osas no acatar las normas!?', '¡¿Osas no acatar las normas!?', 28153),
(141988, 'esES', '¡Pagarás el precio de tu desobediencia!', '¡Pagarás el precio de tu desobediencia!', 28153),
(141987, 'esES', 'Te aventuraste demasiado.', '', 28153),
(141986, 'esES', '¡Vuelve a tu sitio!', '¡Vuelve a tu sitio!', 28153),
(141985, 'esES', '¡Vuelve al trabajo, gusano!', '¡Vuelve al trabajo, gusano!', 28153),
(141984, 'esES', 'Niveles de energía críticos.', '', 28153),
(141983, 'esES', 'Reinicio del sistema requerido.', '', 28153),
(141982, 'esES', '¡El abismo será vuestra tumba!', '', 28153),
(141981, 'esES', 'Entidad desconocida detectada en el puerto A.', '', 28153),
(141980, 'esES', 'Unidad desactivada.', '', 28153),
(141979, 'esES', 'Protocolo de cosecha fallido.', '', 28153),
(141978, 'esES', '¡Vuestros huesos yacerán bajo cinco brazas de agua!', '', 28153),
(141977, 'esES', 'Integridad estructural: 0%%.', '', 28153),
(141976, 'esES', 'Fuga detectada.', '', 28153),
(141975, 'esES', 'Sistema desconectado.', '', 28153),
(141974, 'esES', 'Entidad hostil identificada.', '', 28153),
(141973, 'esES', 'Activando defensas.', '', 28153),
(141972, 'esES', 'Iniciando servocosecha.', '', 28153),
(141971, 'esES', 'Alerta: intrusos.', '', 28153),
(141970, 'esES', 'Usuario no autorizado.', '', 28153),
(141969, 'esES', 'Secuencia de ataque iniciada.', '', 28153),
(141968, 'esES', 'Atacando.', '', 28153),
(141967, 'esES', 'Amenaza detectada.', '', 28153),
(141966, 'esES', '¡Artillería! ¡Sacad esta basura de mi campo de batalla!', '', 28153),
(141965, 'esES', '¡Cañones! ¡Fuego en mi posición!', '', 28153),
(141964, 'esES', '¡Nadie puede resistir la marea!', '', 28153),
(141963, 'esES', '¡Prepárate para morir!', '', 28153),
(141962, 'esES', '¡Te haré trizas!', '', 28153),
(141961, 'esES', '¡Probad mi acero!', '', 28153),
(141960, 'esES', 'No podía esperar otra cosa de la Horda.', '', 28153),
(141959, 'esES', '¡Ninguna disciplina!', '', 28153),
(141958, 'esES', '¡El mar reclamará tus huesos!', '', 28153),
(141957, 'esES', 'No... merecéis... la victoria...', '', 28153),
(141956, 'esES', '¡Este es vuestro fin, escoria de la Horda!', '', 28153),
(141955, 'esES', '¡Por Boralus!', '', 28153),
(141954, 'esES', '¡El enemigo está por todas partes!', '', 28153),
(141953, 'esES', '¡Cuidado!', '', 28153),
(141952, 'esES', '¡Aquí!', '', 28153),
(141951, 'esES', '¡Por aquí!', '', 28153),
(141950, 'esES', '', 'Lleva estas vestimentas con orgullo. Para el Ejército de la Luz siempre será un honor tenerte entre sus filas.', 28153),
(141949, 'esES', '', 'A lo largo de tus viajes, has sido un auténtico foco de luz en la oscuridad. Le has demostrado a la Alianza el valor de los forjados por la Luz.', 28153),
(141948, 'esES', '', 'Reúnete conmigo en el Vindicaar. Es hora de recompensarte por tus esfuerzos.', 28153),
(141947, 'esES', '', 'Le has ofrecido un servicio muy valioso a la Alianza. Ni yo misma lo habría hecho mejor. Bueno, sí... pero por poco.', 28153),
(141946, 'esES', '¡Fuego! ¡Fuego!', '', 28153),
(141945, 'esES', '¡Arded!', '', 28153),
(141944, 'esES', '', 'Es un honor para mí otorgarte la armadura de nuestro pueblo. Dondequiera que te lleve tu viaje; siempre te recordará tus orígenes.', 28153),
(141943, 'esES', '', 'Hasta en los momentos más sombríos has demostrado tu fuerza, valor y determinación. Gracias a ti, la Horda sabe lo que significa ser Monte Alto.', 28153),
(141942, 'esES', '¡Te voy a echar el gancho!', '', 28153),
(141941, 'esES', '', 'Ahora Tótem del Trueno te reclama. Es hora de agradecerte todo lo que has hecho por nosotros.', 28153),
(141940, 'esES', '', 'Tu viaje por Azeroth ha sido largo. Durante todo este tiempo, has traído honor a Monte Alto.', 28153),
(141939, 'esES', '¡Ven aquí!', '', 28153),
(141938, 'esES', '¡Voy a por ti!', '', 28153),
(141937, 'esES', '¡No puedes escapar!', '', 28153),
(141936, 'esES', '¡Me daré un festín con vuestras tripas!', '', 28153),
(141935, 'esES', '¡La cámara SELFI capta el filtro de Argus!', '¡La cámara SELFI capta el filtro de Argus!', 28153),
(141934, 'esES', '¡La cámara SELFI capta el filtro de la Agonía de Escarcha!', '¡La cámara SELFI capta el filtro de la Agonía de Escarcha!', 28153),
(141933, 'esES', '¡La cámara SELFI capta el filtro de sha!', '¡La cámara SELFI capta el filtro de sha!', 28153),
(141932, 'esES', '¡La cámara SELFI capta el filtro de las Tierras de Fuego!', '¡La cámara SELFI capta el filtro de las Tierras de Fuego!', 28153),
(141931, 'esES', '¡La cámara SELFI capta el filtro Crepuscular!', '¡La cámara SELFI capta el filtro Crepuscular!', 28153),
(141930, 'esES', 'No dejéis que me pudra...', '', 28153),
(141929, 'esES', 'Unos pedazos deliciosos.', '', 28153),
(141928, 'esES', '¡Más carnada para el mar!', '', 28153),
(141927, 'esES', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|t¡Te afecta |cFFFF0000|Hspell:248396|h[Añublo de alma]|h|r!', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|t¡Te afecta |cFFFF0000|Hspell:248396|h[Añublo de alma]|h|r!', 28153),
(141926, 'esES', '¡Menudo corte!', '', 28153),
(141925, 'esES', '¡Os voy a cortar en pedazos!', '', 28153),
(141924, 'esES', '<El pescador fija la mirada en el agua de forma obsesiva, murmurando para sí mismo. Tiene los labios agrietados, las manos sangrando y el cuerpo cubierto de cortes y arañazos, probablemente infligidos por los pájaros voraces que proliferan en la costa.\n\nParece que no se ha movido del sitio durante días.\n\nEstá claro que se encuentra bajo la influencia del hechizo del aquelarre, pero, a diferencia de otros que has visto, puede moverse y hablar, aunque no se dirige a ti cuando te acercas>.', '', 28153),
(141923, 'esES', 'Como corderos al matadero.', '', 28153),
(141922, 'esES', '', 'Jamás olvides quién eres. Y si alguna vez echas de menos tu hogar, recuerda que Monte Alto siempre estará aquí para lo que necesites.', 28153),
(141921, 'esES', '', 'Ve a Orgrimmar. Conoce a nuestros nuevos aliados y averigua qué les preocupa... y por qué luchan.', 28153),
(141920, 'esES', '', 'Hoy empiezas un nuevo viaje. Tú serás nuestra voz en las tierras más allá de la montaña.', 28153),
(141919, 'esES', '', 'Es hora de cambiar eso.', 28153),
(141918, 'esES', '', 'Durante años, las Islas Abruptas han sido nuestro hogar. Poco sabemos del Azeroth que existe más allá de nuestras costas.', 28153),
(141917, 'esES', '¡He oído que hay espías! ¿Qué hago?', '¡He oído que hay espías! ¿Qué hago?', 28153),
(141916, 'esES', '', 'Y sigue siempre el camino de la Luz.', 28153),
(141915, 'esES', '', 'Tu deber empieza en Ventormenta. Explora el mundo de Azeroth: conoce a la gente y los lugares que hemos jurado proteger.', 28153),
(141914, 'esES', '', 'Pero no debemos confiarnos. Una guerra acaba y otra comienza. Esa es la vida del soldado.', 28153),
(141913, 'esES', '', 'Ahora, por primera vez en mucho tiempo, podemos caminar bajo un cielo libre de la barbarie de la Legión... y sentir la tierra bajo nuestras pezuñas.', 28153),
(141912, 'esES', '', 'Durante miles de años, los forjados por la Luz nos enfrentamos a los demonios en el Vacío Abisal. El Xenedar era nuestro único hogar.', 28153),
(141911, 'esES', '¡No podríamos haber elegido un momento mejor, adalid! Así verás lo que significa para un soldado convertirse en forjado por la Luz. Adelante, Fareeya.', '', 28153),
(141910, 'esES', '', 'Sabes que me encantan tus discursos, ¿pero no puede esperar? Estábamos a punto de enviar a estos iniciados a realizar las pruebas.', 28153),
(141909, 'esES', 'Así es. Está ansioso por que el Ejército de la Luz entre a formar parte de la Alianza. Reúne a nuestras tropas, Capitana, y se lo comunicaré.', '', 28153),
(141908, 'esES', '', 'No te esperaba tan pronto, Alto Exarca. ¿Significa eso que la reunión con el Rey ha sido un éxito?', 28153),
(141905, 'esES', '¡Addington! Por las profundidades...', '', 28153),
(141902, 'esES', '¡Vuelve al Vacío al que perteneces!', '', 28153),
(141901, 'esES', '¡Cima del Trueno será libre!', '', 28153),
(141900, 'esES', '¡Ja, ja, ja, ja! ¡Qué bien sienta volver a blandir mi maza!', '', 28153),
(141899, 'esES', '¡Libraremos Mulgore de la sombra!', '', 28153),
(141898, 'esES', '¡Por la Alianza!', '', 28153),
(141897, 'esES', '¡Por la Alianza!', '', 28153),
(141896, 'esES', 'A veces me pregunto si es lo correcto.', '', 28153),
(141895, 'esES', 'Nos harán falta ambas cualidades en los tiempos que se avecinan. Gracias por ayudarnos a atraerlos a nuestra causa, adalid.', '', 28153),
(141894, 'esES', 'He pasado miles de años combatiendo junto a estos draenei en el Vacío Abisal. No encontrarás soldados más diestros ni leales que estos.', '', 28153),
(141893, 'esES', 'La fuerza de los forjados por la Luz es más que bienvenida entre nuestras filas, Alto Exarca.', '', 28153),
(141892, 'esES', 'Rey Wrynn, el Ejército de la Luz jura defender a la Alianza.', '', 28153),
(141891, 'esES', 'Lord Canto Tormenta ha prohibido estos rituales. Ahora se centra en construir nuevos barcos.', '', 28153),
(141890, 'esES', 'Al investigar la superficie del agua, me encuentro con una tormenta oscura que nubla mi visión.', '', 28153),
(141889, 'esES', '', '¿Sabes dónde está la flota?', 28153),
(141888, 'esES', 'La casa Canto Tormenta cambió cuando su flota no regresó.', '', 28153),
(141887, 'esES', 'A uno de mis hermanos... y respuestas, espero.', '', 28153),
(141886, 'esES', '', '¿Y qué encontraremos allí exactamente?', 28153),
(141885, 'esES', 'Ribera del Marinero está cerca de aquí. Vamos.', '', 28153),
(141884, 'esES', '¡Y no te levantes!', '', 28153),
(141883, 'esES', '', 'No volveréih de Nazmir. ¡Nuehtro pobre Rey perderá a su hija en ehta ehtúpida cruzada!', 28153),
(141882, 'esES', 'Me dirijo a Nazmir. Prepárate, allí solo encontraremoh trolh de sangre y vudú ohcuro.', '', 28153),
(141881, 'esES', '', '¡Mih mahcotah no alimentarán a loh trolh de sangre! Nadie regresa de Nazmir.', 28153),
(141880, 'esES', 'Antes de que te marches, permíteme hablarte de los siguientes tres santuarios.', '', 28153),
(141879, 'esES', 'Es una tierra llamada Zandalar. Probablemente necesites un barco, está prácticamente en el otro lado del mundo.', '', 28153),
(141878, 'esES', 'Creo que sé dónde pueden residir unos pocos más, pero es un territorio bastante hostil.', '', 28153),
(141877, 'esES', 'Mientras estabas fuera, he estado repasando el diario buscando la ubicación de más santuarios.', '', 28153),
(141876, 'esES', '', 'Será un placer, Alto Exarca.', 28153),
(141875, 'esES', 'Adalid, es hora de volver a Ventormenta. Fareeya, corre la voz: ¡ahora los forjados por la Luz luchan junto a la Alianza!', '', 28153),
(141874, 'esES', 'T\'paartos es... poco convencional. Pero servirá bien a nuestra causa.', '', 28153),
(141873, 'esES', '¡T\'paartos!', '', 28153),
(141872, 'esES', '', 'Pheta thones gamera. ¡Que la Luz guíe nuestro camino!', 28153),
(141871, 'esES', 'De ahora en adelante, eres un forjado por la Luz.', '', 28153),
(141870, 'esES', 'T\'paartos lo siente.', '', 28153),
(141869, 'esES', 'olfatea el aliento de Wees\'ki. ¡Uf!', '', 28153),
(141868, 'esES', 'Acabamoh de pasar la mejor noche de la hihtoria. Una pena que no pueda recordar nada.\n\n¡Aun así, tenemoh huevoh de dinosaurio pa desayunar!', '', 28153),
(141867, 'esES', 'Mih cazadoreh de lah Sombrah y yo iremoh delante. Te confío la guardia de la Princesa.', '', 28153),
(141866, 'esES', '¿Te acuerdah de lo que ocurrió anoche?\n\nYo tampoco.', '', 28153),
(141865, 'esES', 'Princesa, la Horda enviará refuerzoh pronto. No creo que sea necesario que noh involucremoh.', '', 28153),
(141864, 'esES', 'Uf... Debería empezar... a cuidarme mejor...', '', 28153),
(141863, 'esES', 'Adelántate. Me sanaré, solo necesito... ¡AY! Solo... necesito tiempo.', '', 28153),
(141862, 'esES', '¡No tenemoh tiempo pa ehto!\n\nLa Horda noh enviará refuerzoh pronto y necesitamoh un puerto pa recibirloh.', '', 28153),
(141861, 'esES', '', '¡Esta vez hay demasiados! ¡Fuego!', 28153),
(141860, 'esES', 'Ojalá lo supiese.', '', 28153),
(141859, 'esES', '', '¿Qué sucede aquí, hermano?', 28153),
(141858, 'esES', '', '¡Ciudadanos, dispersaos!', 28153),
(141857, 'esES', 'No te quedarás el tesoro de mi maestro. ¡Prepárate para ser $ganiquilado, intruso:aniquilada, intrusa;!', '', 28153),
(141856, 'esES', '¡¿QUIÉN OSA ENTRAR EN LA CÁMARA?!', '', 28153),
(141855, 'esES', '', 'Cuando llames su atención, los sacaré de aquí.', 28153),
(141852, 'esES', 'El miedo... ¡seguía a T\'paartos por doquier!', '', 28153),
(141851, 'esES', 'T\'paartos se arrepiente de llamarte piltrafa.', '', 28153),
(141850, 'esES', '¡T\'paartos no conoce el miedo!', '', 28153),
(141849, 'esES', '¡Aquí!', '', 28153),
(141848, 'esES', '¡Cuidado!', '', 28153),
(141847, 'esES', '¡Aquí!', '', 28153),
(141846, 'esES', '¡Por aquí!', '', 28153),
(141845, 'esES', 'Hemos recuperado el alijo de azerita y tenemos bajo control a los guardias de los Gobernalle. La prisión es nuestra. ', 'Hemos recuperado el alijo de azerita y tenemos bajo control a los guardias de los Gobernalle. La prisión es nuestra. ', 28153),
(141844, 'esES', 'Espero que Korgus haya pagado cara su crueldad.', 'Espero que Korgus haya pagado cara su crueldad.', 28153),
(141843, 'esES', '¡Gracias!', '¡Gracias!', 28153),
(141842, 'esES', 'Hemos puesto a buen recaudo a los prisioneros y restablecido el perímetro. Los niveles inferiores son nuestros.', 'Hemos puesto a buen recaudo a los prisioneros y restablecido el perímetro. Los niveles inferiores son nuestros.', 28153),
(141841, 'esES', '', '¡Enseguida, Alto Exarca!', 28153),
(141840, 'esES', 'Fareeya, necesito una baliza para el Vindicaar.', '', 28153),
(141839, 'esES', 'Por aquí, adalid.', '', 28153),
(141838, 'esES', 'A tus órdenes, Majestad.', '', 28153),
(141837, 'esES', 'Los forjados por la Luz serían unos aliados valiosos para la Alianza. Turalyon, adalid, id al Vindicaar y dirigíos juntos a las tropas.', '', 28153),
(141836, 'esES', '', 'Me gustas. Nada te satisface, igual que a mí. Eso es porque buscas siempre la perfección.$B$BAunque no estoy muy segura, ¿sabes? Este cacharro tiene lo mejor de la ingeniería goblin concentrado en una cajita diminuta. ¡Seguro que tiene un enorme potencial sin explotar!$B$BTal vez si encontraras una fuente de gran poder podrías... ¿probar a ver qué pasa? Aunque no te garantizo nada.', 28153),
(141835, 'esES', '', 'Niko, ¡más luz! Ah, hola, cielo. ¡No te había visto! ¿Qué puedo hacer por ti?', 28153),
(141834, 'esES', '', 'Mmm, no estoy muy segura. Este dispositivo tiene una mecánica muy poderosa en su interior... Seguro que posee más de una característica oculta.$B$B¿Por qué no pruebas a llevarla cerca de fuentes de gran poder? ¡Parece que eso siempre hace que surjan cosas!', 28153),
(141833, 'esES', '¿Sabes si esta cámara tiene más funciones?', '¿Sabes si esta cámara tiene más funciones?', 28153),
(141832, 'esES', 'He perdido mi cámara. ¿Podrías hacerme otra?', 'He perdido mi cámara. ¿Podrías hacerme otra?', 28153),
(141831, 'esES', '', 'De \"Servicio Extractor Ligero de Fotografías e Imágenes\".', 28153),
(141830, 'esES', '¿De dónde viene el nombre de SELFI?', '¿De dónde viene el nombre de SELFI?', 28153),
(141829, 'esES', '', 'Ah, ¡hola! ¿Querías hacerte un selfi conmigo?', 28153),
(141828, 'esES', '¡Queremos respuestas, Pike!', '¡Queremos respuestas, Pike!', 28153),
(141827, 'esES', '¡Estás demasiado ocupado llevándote la cosecha \"para los soldados\"!', '¡Estás demasiado ocupado llevándote la cosecha \"para los soldados\"!', 28153),
(141826, 'esES', '¡La milicia lleva días sin patrullar!', '¡La milicia lleva días sin patrullar!', 28153),
(141825, 'esES', '¡Están atacando Entrañas! ¡Ve al portal de mago!', '¡Están atacando Entrañas! ¡Ve al portal de mago!', 28153),
(141824, 'esES', '¿Se supone que vamos a abandonarlo todo y trasladarnos a Orgrimmar?', '¿Se supone que vamos a abandonarlo todo y trasladarnos a Orgrimmar?', 28153),
(141823, 'esES', 'De pronto han empezado a cerrar las puertas, ¿qué está pasando?', 'De pronto han empezado a cerrar las puertas, ¿qué está pasando?', 28153),
(141822, 'esES', 'A salvo o no, ¡no quiero perder todos mis bienes en esta guerra!', 'A salvo o no, ¡no quiero perder todos mis bienes en esta guerra!', 28153),
(141821, 'esES', '¡Tengo que encontrar a mis amigos!', '¡Tengo que encontrar a mis amigos!', 28153),
(141820, 'esES', 'Mi mamá me contó que los soldados mantienen alejados a los malos. ¿Dónde están los soldados?', 'Mi mamá me contó que los soldados mantienen alejados a los malos. ¿Dónde están los soldados?', 28153),
(141819, 'esES', '¡Tenía mucho miedo! ¡Gracias!', '¡Tenía mucho miedo! ¡Gracias!', 28153),
(141818, 'esES', '¡Quiero a mi papá!', '¡Quiero a mi papá!', 28153),
(141817, 'esES', '¿Dónde está la milicia?', '¿Dónde está la milicia?', 28153),
(141816, 'esES', 'Me has salvado. ¡Gracias!', 'Me has salvado. ¡Gracias!', 28153),
(141815, 'esES', '¡Nunca antes nos habían atacado con tanta ferocidad!', '¡Nunca antes nos habían atacado con tanta ferocidad!', 28153),
(141814, 'esES', 'Puedo apañármelas desde aquí. ¡Rezo para que los demás estén a salvo!', 'Puedo apañármelas desde aquí. ¡Rezo para que los demás estén a salvo!', 28153),
(141813, 'esES', 'No lo sé... Mayla, debemos seguir adelante. Baine, adalid, vosotros reunid a los demás. Nos veremos en la cima.', '', 28153),
(141812, 'esES', 'Vástago de... ¿A qué se refiere?', '', 28153),
(141811, 'esES', 'Sí... ¡ven! Tu fuerza será nuestra, vástago de la oscuridad.', '', 28153),
(141810, 'esES', 'El último resguardo se colocó en la Cima Monte Alto. Es allí adonde debemos dirigirnos. Tenemos que trabajar juntos, como hicieron Huln y sus aliados.', '', 28153),
(141809, 'esES', 'Así es. Y cuando dejé la montaña para visitar Mulgore, los resguardos se debilitaron lo suficiente para que la Oscuridad escapara.', '', 28153),
(141808, 'esES', '', 'Todo este tiempo, los Necroscuro han vagado entre las sombras, esperando el momento de invocar a su maestro.', 28153),
(141807, 'esES', 'Por lo que Huln ideó un plan: colocar resguardos para capturar al enviado de los dioses antiguos. Aunque Uul\'gyneth sobrevivió, consiguieron atrapar su esencia.', '', 28153),
(141806, 'esES', 'Huln reunió a héroes de todas las tribus para enfrentarse a los sirvientes de Uul\'gyneth, los Necroscuro. Pero las fuerzas sombrías eran demasiado poderosas...', '', 28153),
(141805, 'esES', 'Hace tiempo, los dioses antiguos intentaron conquistar Monte Alto. Su campaña la lideraba una terrible criatura: Uul\'gyneth, la Oscuridad.', '', 28153),
(141804, 'esES', '', 'Pero queda mucho por hacer. Cuerno de Ébano, debemos descubrir qué quiere esa Oscuridad.', 28153),
(141803, 'esES', '¡Adalid! Cielogrís me ha hablado de tu valor.', '', 28153),
(141802, 'esES', 'He recuperado el control de mi mente. Vuelve a Tótem del Trueno. Debemos reunir fuerzas para lo que está por venir.', '', 28153),
(141801, 'esES', '', '¡Rápido! El grupo anda cerca.', 28153),
(141800, 'esES', '', 'Me quedaré aquí mientras Cielogrís te ayuda. Espero que restaurar los resguardos cure la mente de Cuerno de Ébano.', 28153),
(141799, 'esES', '', 'Las aguas han calmado a Cuerno de Ébano, pero me temo que lo estamos perdiendo.', 28153),
(141798, 'esES', 'Ve a Monte Alto y ayuda a Mayla. Yo no tardaré.', '', 28153),
(141797, 'esES', 'Debo asegurarme de que no queda ningún esbirro de los dioses antiguos en Mulgore.', '', 28153),
(141796, 'esES', '¡Tus maestros no dominarán mi ciudad, monstruo!', '', 28153),
(141795, 'esES', '¡Acabad con ellos! ¡Que no entorpezcan mi retorno!', '', 28153),
(141794, 'esES', '', 'Si liberan a ese monhtruo, loh trolh de sangre serán imparableh. Tú y tu Horda no vaih a ser suficienteh. Necesitamoh otro plan.', 28153),
(141793, 'esES', '', 'Ya no noh siguen... Parece que ehtamoh a salvo.', 28153),
(141792, 'esES', 'Muy bien. Limpiaremos Cima del Trueno de la mugre de los dioses antiguos.', '', 28153),
(141791, 'esES', '', 'Entendido, amigo mío. Baine, debemos llevar a Cuerno de Ébano a Monte Alto.', 28153),
(141790, 'esES', 'Mayla... Las pozas...', '', 28153),
(141789, 'esES', '', 'No te temo a ti ni a tuh abominacioneh. ¡Oh mataré a todoh!', 28153),
(141788, 'esES', '', '¡Corre, princesita! ¡Nada te salvará de mi maehtro! ¡G\'huun te devorará!', 28153),
(141787, 'esES', '', '¡Debemoh movernoh! ¡Sujétate!', 28153),
(141786, 'esES', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t¡La reina de las arenas se |cFFFF0000|Hspell:257609|h[Enfurece]|h|r!', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t¡La reina de las arenas se |cFFFF0000|Hspell:257609|h[Enfurece]|h|r!', 28153),
(141784, 'esES', '¡Los resguardos se han debilitado! ¡Será nuestro!', '', 28153),
(141783, 'esES', 'Juntos regresaremos a las mareas. ¡Juntos volveremos a ser poderosos!', '', 28153),
(141782, 'esES', '¡Nuestros poderosos Sabiomar nos guiarán a la victoria gracias al poder del mar!', '', 28153),
(141781, 'esES', 'Debemos trabajar unidos y concentrar nuestras fuerzas. ¡Kul Tiras siempre pertenecerá a su pueblo!', '', 28153),
(141780, 'esES', '¡La casa Canto Tormenta debe recuperar el control de este reino y restaurar su gloria!', '', 28153),
(141779, 'esES', 'Se acabó trabajar los campos y construir barcos para la arrogante élite de Boralus sin recibir nada a cambio.', '', 28153),
(141778, 'esES', 'Hijos del mar, hoy amanece una nueva era para todos.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141777, 'esES', 'Si hubieseh vihto lo que yo vi, haríah lo mihmo. ¡Ven y te lo mohtraré!', '', 28153),
(141776, 'esES', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|t¡Golganneth te ha elegido para que transmitas su |cFFFF0000|Hspell:257306|h[Obsequio del mar]|h|r!', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|t¡Golganneth te ha elegido para que transmitas su |cFFFF0000|Hspell:257306|h[Obsequio del mar]|h|r!', 28153),
(141775, 'esES', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|t¡Golganneth te ha elegido para que transmitas su |cFFFF0000|Hspell:257313|h[Obsequio del cielo]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|t¡Golganneth te ha elegido para que transmitas su |cFFFF0000|Hspell:257313|h[Obsequio del cielo]|h|r!', 28153),
(141774, 'esES', 'El sistema se está quedando sin energía.', '', 28153),
(141773, 'esES', 'Selección de objetivo principal fa-fallida...', '', 28153),
(141772, 'esES', 'Pérdida de salud. Asistencia requerida.', '', 28153),
(141771, 'esES', '¡Error!', '', 28153),
(141770, 'esES', '', '¿El santuario dorado? Será Atal\'Dazar. Es una ciudad. De oro. Una ciudad dorada.$b$b¿Un santuario? Tal vez dedicado al oro. O a los dinosaurios. ¡O a los dinosaurios bañados en oro!$b$b¡Yo probaría suerte allí!', 28153),
(141769, 'esES', 'Parece que los arrastraron hacia allí, por el glaciar del noroeste.', '', 28153),
(141768, 'esES', '¿Has oído hablar de un lugar llamado \"el santuario dorado\"?', '¿Has oído hablar de un lugar llamado \"el santuario dorado\"?', 28153),
(141767, 'esES', 'Vuestra misión consiste en sacarlos de su escondite y eliminarlos, y en evacuar a nuestros civiles a Orgrimmar sanos y salvos.', '', 28153),
(141766, 'esES', 'Hemos acorralado a esos cobardes en el Barrio de la Magia y hemos asegurado el resto de la ciudad.', '', 28153),
(141765, 'esES', 'Nuestros enemigos están atacando Entrañas y pretenden hacerse con Lordaeron.', '', 28153),
(141764, 'esES', 'Entrañas ya no es segura para los civiles. La batalla arrecia en la superficie y hay docenas de espías en las murallas de la ciudad.', '', 28153),
(141762, 'esES', '¡Soldados de la Horda, ha llegado la hora!', '', 28153),
(141761, 'esES', '', '¡Nos reuniremos en el Valle del Honor cuando llegues a Orgrimmar! ¡Aquí no estamos a salvo!', 28153),
(141760, 'esES', '', '¡Mi portal está abierto, tenemos que irnos!', 28153),
(141759, 'esES', '', '¡Debemos ir a Orgrimmar! ¡Aquí no estamos a salvo!', 28153),
(141758, 'esES', 'Buen... disparo...', '', 28153),
(141757, 'esES', '¡Corre cuanto quieras! Nunca fallo.', '', 28153),
(141756, 'esES', '¡Caeréis en el fuego cruzado!', '', 28153),
(141755, 'esES', 'Estaba deseando probar esto con objetivos vivos.', '', 28153),
(141754, 'esES', 'Consideraos rehabilitados.', '', 28153),
(141753, 'esES', 'Disfruta de tu último festín... ¡de balas!', '', 28153),
(141752, 'esES', '¡Te sentencio a muerte!', '', 28153),
(141751, 'esES', 'Es un detalle que volváis para vuestra ejecución.', '', 28153),
(141750, 'esES', '¡Vienen más bombas!', '', 28153),
(141749, 'esES', '¡Sí, señora!', '', 28153),
(141748, 'esES', '', '¡Quiero que esas llamas ardan más!', 28153),
(141747, 'esES', '', '¡Más combustible para las llamas! ¡Ahora!', 28153),
(141746, 'esES', '', '¡Os reduciré a cenizas!', 28153),
(141745, 'esES', '', '¡Arded en la pira!', 28153),
(141744, 'esES', '', '¡Hora de caldear el ambiente!', 28153),
(141743, 'esES', '¡Le haces daño a mi amigo!', '', 28153),
(141742, 'esES', '', 'Las estrellas más brillantes... se consumen... más rápido.', 28153),
(141741, 'esES', '¡Pagarás por lo que has hecho!', '', 28153),
(141740, 'esES', '¡Mantenlos ocupados, grandullón! Yo los diezmaré.', '', 28153),
(141739, 'esES', '', 'Debemoh encontrar el arma anteh de que Jakra\'zet logre hacerse con ella.', 28153),
(141738, 'esES', '', 'No tengo ni idea de qué eh esa arma o dónde encontrarla, pero no puede ser buena si Jakra\'zet intenta ocultársela al Rey.', 28153),
(141737, 'esES', '', 'Regihtran lah dunah pa buhcar un arma que puede dehtruir la ciudad y matan a quien se leh oponga.', 28153),
(141736, 'esES', '', 'Como sohpechaba, el general Jakra\'zet tiene tropah en el desierto sin que el Rey lo sepa. ', 28153),
(141735, 'esES', 'Prospección', 'Prospección', 28153),
(141734, 'esES', '¡Claro que sí! Ven, $gchico:chica;, tengo un trabajo para ti.', '', 28153),
(141733, 'esES', '¡Oye, Rulf! ¡Parece que $geste chico:esta chica; promete! ¿Tienes algún trabajo pendiente?', '', 28153),
(141732, 'esES', '', 'Me gustan las burbujas. ¡Hacen que me sienta segura!', 28153),
(141731, 'esES', '¿Te puedes creer que existen ciudades que no están rodeadas por una burbuja mágica? ¿Cómo harán para que no se les llenen las calles de polvo? Bárbaros...', '', 28153),
(141730, 'esES', '', 'Creí que no volvería a verla nunca...', 28153),
(141729, 'esES', 'Loh recuerdoh regresan... y el dolor también.', '', 28153),
(141728, 'esES', '', '¡Quien juega con fuego, se acaba quemando!', 28153),
(141727, 'esES', '', 'Oh... ¡Escucha cómo crepita la carne!', 28153),
(141726, 'esES', '', 'Vuestros cadáveres servirán de combustible.', 28153),
(141725, 'esES', '', 'Estoy deseando ver cómo os derretís.', 28153),
(141724, 'esES', '', '¡Ven, rápido! ¡Rakera ehtá recuperando la memoria!', 28153),
(141723, 'esES', 'Se suponía... que teníais que sangrar... vosotros...', '', 28153),
(141722, 'esES', '', 'Mi cabeza... Kaja, ¿ereh tú?', 28153),
(141721, 'esES', '¡Hora de cazar!', '', 28153),
(141720, 'esES', 'Habéis matado a mi hermano pequeño. Ahora os voy a despedazar.', '', 28153),
(141719, 'esES', '¡Hermanito!', '', 28153),
(141718, 'esES', '¡En pie, hermanito! Esta gente no se va a matar sola.', '', 28153),
(141717, 'esES', '¡Vamos, chicos! ¡Que vean quién manda aquí!', '', 28153),
(141716, 'esES', 'He estado afilando las hojas solo para vosotros.', '', 28153),
(141715, 'esES', 'Pero... me iban a dar... la condicional...', '', 28153),
(141714, 'esES', 'Debisteis quedaros en vuestras celdas.', '', 28153),
(141713, 'esES', 'Llévame a Ulduar. (Banda de Paseo en el tiempo)', 'Llévame a Ulduar. (Banda de Paseo en el tiempo)', 28153),
(141712, 'esES', '', 'Saludos, $n. Seguramente no te acuerdes de mí, nos conocimos la semana que viene.$b$b¿Te gustaría volver a visitar Ulduar?', 28153),
(141711, 'esES', '¡Soy el macho alfa!', '', 28153),
(141710, 'esES', 'Carne muerta.', '', 28153),
(141709, 'esES', '¡Carne fresca!', '', 28153),
(141708, 'esES', 'Debilita al grifo sin perder el agarre con |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Agarrar fuerte]|h|r', '', 28153),
(141707, 'esES', 'Estoy listo.', 'Estoy lista.', 28153),
(141706, 'esES', '', 'Vamos allá.', 28153),
(141705, 'esES', '', 'Parece que ehtamos a salvo. Cuando lleguemoh a lah Ruinah de Zul\'jan habrá que darse prisa.', 28153),
(141704, 'esES', '', 'Loh trolh de sangre son implacableh e infinitoh graciah al poder de un dioh antiguo.', 28153),
(141703, 'esES', '', 'Me alegra que te hayah dado cuenta, Parche. Ereh máh observador que mi padre.', 28153),
(141701, 'esES', '', '¡No-muertoh! Se dirigen hacia Zuldazar. ¡Debemoh liquidarloh!', 28153),
(141696, 'esES', 'Parece que el talismán no funciona. Pruébalo con algunos esclavos maldiformes primero.', '', 28153),
(141695, 'esES', 'No parece demasiado listo.', '', 28153),
(141694, 'esES', '¡Colafortuna corre hacia las cascadas!', '', 28153),
(141693, 'esES', '', '', 28153),
(141692, 'esES', '|cffffff00+$1i de restos de armadura|r', '|cffffff00+$1i de restos de armadura|r', 28153),
(141691, 'esES', '¡Colafortuna huye hacia un lugar seguro!', '', 28153),
(141690, 'esES', '', '¿Qué le habrán hecho esoh cultoreh a Rakera? Ni siquiera recuerda su propio nombre.', 28153),
(141689, 'esES', '¡Tú! Sí, tú. Acércate con disimulo. Intenta no llamar la atención.', '', 28153),
(141688, 'esES', '', '¿Qué te han hecho...?', 28153),
(141687, 'esES', '', 'Todoh somoh Akunda.', 28153),
(141686, 'esES', '', '¿Rakera?', 28153),
(141685, 'esES', '', 'Ehtá aquí y ehtá viva. ¡Rakera!', 28153),
(141684, 'esES', '', '¡Rakera!', 28153),
(141683, 'esES', '', 'Alguien tiene que saber algo en ehte ehtraño templo.', 28153),
(141682, 'esES', 'No me importa qué trato pienseh hacer con el Rey y su hija. Tu presencia no eh bienvenida en Zuldazar.$b$bY aunque la Princesa tenga mucha autoridad, aún no eh Reina.$b$bHahta entonceh, el verdadero poder de Zuldazar reside en el Consejo Zanchuli y en mí.', '', 28153),
(141681, 'esES', '', 'Esta es una ceremonia oficial. No interrumpas.', 28153),
(141680, 'esES', 'Ahora T\'paartos lo sabe.', '', 28153),
(141679, 'esES', 'Todos tenemos oscuridad en nuestro interior. No es fácil aceptarlo.', '', 28153),
(141678, 'esES', '', 'T\'paartos... Te has enfrentado a tus miedos... a tus fracasos... y has renacido.', 28153),
(141677, 'esES', '', 'Bienvenido, T\'paartos.', 28153),
(141676, 'esES', '', 'Si Rakera ehtá en ehte templo, la encontraremoh.', 28153),
(141675, 'esES', '¡Huele raro! ¡Raaaaat!', '', 28153),
(141674, 'esES', '¡Siento el olor a guano de loro! ¡Raak!', '', 28153),
(141673, 'esES', '¡Raak! Kragg muerto! ¡Cazatiburones arrepentido!', '', 28153),
(141672, 'esES', '', 'Ah, un miembro de la Horda. Curioso...', 28153),
(141671, 'esES', '¡$n ha atacado a las fuerzas de la Alianza en el aserradero!', '¡$n ha atacado a las fuerzas de la Alianza en el aserradero!', 28153),
(141669, 'esES', '', 'Aquí el propio viento sopla con el poder de la loa. Pa\'ku se eleva en algún lugar de ehtoh cieloh, puedo sentirlo.$b$bNunca anteh había puehto un pie en Zandalar, pero mi abuelo solía contarme hihtoriah de ehte lugar.', 28153),
(141668, 'esES', '', 'Loh loa son poderosoh aquí. Puedo sentir la presencia de mi propio loa, Gonk, al acecho trah cada árbol y arbuhto.$b$bGonk ehtá cerca. Será bueno verlo en persona.', 28153),
(141667, 'esES', 'No caeremos con tanta facilidad. Soldados, ¡recuperad nuestro aserradero!', '', 28153),
(141666, 'esES', 'Saludoh, $gpequeño:pequeña;.$b$bSoy el señor de loh maleficioh Raal, el de máh alto rango entre quieneh tratan con Pa\'ku, la loa de loh vientoh, y miembro del Consejo Zanchuli.$b$bSoy muy importante y ehtoy muy ocupado. ¿Qué quiereh?', '', 28153),
(141665, 'esES', '', 'Tenemoh poco tiempo con el señor de loh maleficioh. No interrumpah. Tenemoh mucho que hacer.', 28153),
(141664, 'esES', '¡Mi amigo!', '', 28153),
(141663, 'esES', '', '¡Ahora los sethrak aprenderán a temer a los vulperas!', 28153),
(141662, 'esES', 'Parece que el general Jakra\'zet, ese arribihta trol Furiarena que dirige el ejército de Zuldazar, ha decidido retirar suh guardiah del puerto.\n\nAparentemente, no todoh loh trolh ehtán de acuerdo con el decreto de la princesa Talanji de permitir la entrada al puerto a loh no trolh.\n\nVa a necesitar la ayuda de al menoh un miembro del Consejo Zanchuli. Afortunadamente, sé dónde hay doh.', '', 28153),
(141660, 'esES', '', 'Los vulperas somos de todo menos débiles. ¡Nos temerán!', 28153),
(141658, 'esES', 'Drenando', 'Drenando', 28153),
(141657, 'esES', '', 'Estos sethrak pagarán por lo que le han hecho a nuestro hogar.', 28153),
(141655, 'esES', 'No, no te preocupesh por mí, $gsheñor:sheñora; <hip>. Me pondré en marcha ahora... ah... ¿Dónde diablosh eshtoy?$b$bEshcucha, deja que duerma la mona un poco aquí y para cuando <hip> vuelvash, she me habrá pashado. Te lo prometo.', '', 28153),
(141654, 'esES', 'Ja, ja, esha esh la parte divertida. Eshcucha, ¡she fue y lo <hip> atraparon! Eshe eshtúpido cantamañanash intentó matar a alguien.$b$bLo llevaron a la prishión con el reshto de esha bashura <hip>. Shi aún lo tiene encima, apueshto <hip> a que la única forma en que lo vash a conseguir esh por encima de <hip> shu cadáver.$b$bOye, no intentarásh matarme a mí también, ¿verdad? <hip>. No te he hecho nada.$b$bEshcucha, me iré a otro lado y dormiré <hip> la mona. Por mi honor de marinero, ja, ja.', '', 28153),
(141653, 'esES', '¿Dónde está la persona que se llevó la joya?', '¿Dónde está la persona que se llevó la joya?', 28153),
(141652, 'esES', 'Eshe bashtardo she llevó nueshtra <hip> joya. Nosh pashamosh todo eshe tiempo tallando esha cosha y ¿qué hace? <hip>.$b$bShe larga en mitad de la <hip> noche. ¡Íbamosh a venderla para hacernosh ricosh! <hip>.$b$b<Salton le pega otro trago a su jarra>.$b$bDime, ¿llevash algo de oro encima, $gsheñor:sheñora;?', '', 28153),
(141651, 'esES', '', 'Estoy lista. Vamos a cazar sethrak.', 28153),
(141649, 'esES', 'La princesa Talanji dice que necesita tu ayuda con Jakra\'zet.', 'La princesa Talanji dice que necesita tu ayuda con Jakra\'zet.', 28153),
(141648, 'esES', '', 'Ehtáh ante la druida de guerra Loti, devota de Gonk, campeón de la caza y maehtro rahtreador. ¿Qué se te ofrece, $c?', 28153),
(141647, 'esES', '¡Activad las hojas de sierra! Necesitamos más madera.', '', 28153),
(141646, 'esES', 'Uf, vaya, tenemoh un problema con eso. Jakra\'zet se niega a llevar a cabo la voluntad de la Princesa.$b$bNecesito la ayuda de otro miembro del Consejo Zanchuli, pero loh doh que hay aquí abajo ehtán ocupadoh lidiando con una dihputa tribal.$b$bHabla con Tal\'aman o Tal\'farrak e intenta convencer a uno de esoh Zanchuli pa que noh ayude.$b$bSoy demasiado importante pa ocuparme de semejante tarea, de otra forma lo haría yo mihmo.', '', 28153),
(141645, 'esES', 'La princesa Talanji quiere saber dónde están los guardias.', 'La princesa Talanji quiere saber dónde están los guardias.', 28153),
(141644, 'esES', 'En cuanto vi tu rohtro en Ventormenta, supe que el momento de la profecía había llegado.$b$bLoh ehpírituh me enseñan muchah cosah y en esah visioneh he vihto tu rohtro a la cabeza de muchoh sucesoh importanteh del futuro.$b$bTodo ehtá en marcha, $c. Pronto, tú y yo haremoh que el mihmo tejido del mundo se ehtremezca.', '', 28153),
(141643, 'esES', 'Yo en tu lugar haría lo mismo. Buena suerte.', 'Yo en tu lugar haría lo mismo. Buena suerte.', 28153),
(141642, 'esES', 'Sí... Ríndete, T\'paartos. ¡Acepta tu auténtico poder!', '', 28153),
(141641, 'esES', 'Libérate de las cadenas con las que te ata la Luz.', '', 28153),
(141640, 'esES', 'La Luz no es el camino hacia la auténtica fuerza.', '', 28153),
(141639, 'esES', 'Nos espera un gran poder, T\'paartos.', '', 28153),
(141638, 'esES', '¡La Luz siempre ha acompañado a T\'paartos! ¡T\'paartos nunca abandonará a la Luz!', '', 28153),
(141637, 'esES', '¡¡¡BASTA!!!', '', 28153),
(141636, 'esES', 'No...', '', 28153),
(141635, 'esES', 'No... Esto no es real. ¡No puede ser el T\'paartos de verdad!', '', 28153),
(141634, 'esES', '¡Ah! ¿Puede piltrafa hacer desaparecer las serpientes?', '', 28153),
(141633, 'esES', 'Esto... le da a T\'paartos un poco de vergüenza.', '', 28153),
(141632, 'esES', '¡T\'paartos puede levantar montañas!', '', 28153),
(141631, 'esES', 'T\'paartos se ha enfrentado a muchos enemigos así con el Ejército de la Luz.', '', 28153),
(141630, 'esES', 'Aah, Ika. T\'paartos crió a este elekk cuando mataron a su madre.', '', 28153),
(141629, 'esES', '¡No! ¡La oscuridad no se llevará a T\'paartos!', '', 28153),
(141628, 'esES', '¿Estaba T\'paartos destinado a recorrer esta senda? ¿Es digno de convertirse en un forjado por la Luz?', '', 28153),
(141623, 'esES', '¡Me has salvado el pellejo otra vez! Me vuelvo al campamento antes de que pille un resfriado.', '', 28153),
(141620, 'esES', '', '¡No los mates sin mí!', 28153),
(141619, 'esES', '', 'Los vulperas estamos preparados. Los infieles nos temerán.', 28153),
(141618, 'esES', 'Mmmm... Te daré... mmm...', '', 28153),
(141617, 'esES', 'Iba a ushar el oro para casharme <sollozo>.', '', 28153),
(141616, 'esES', 'En cuanto <hip> conshiga una barca... ¡iré a por ti!', '', 28153),
(141615, 'esES', '¡Te hash llevado nueshtra maldita joya, canta... <hip>... mañanash!', '', 28153),
(141614, 'esES', 'Has cogido nuestro <hip>...', '', 28153),
(141613, 'esES', 'Tengo que dejar de permitirle a Nisha idear los planes...', '', 28153),
(141612, 'esES', '', 'Es poco probable. Los vuestros normalmente no sobreviven. Ya no.', 28153),
(141611, 'esES', 'Ten cuidado, Meerah. Nuestros carros no siempre soportan bien las antiguas carreteras trols.', '', 28153),
(141610, 'esES', '', 'Los sethrak se arrepentirán de haber atacado nuestra caravana.', 28153),
(141609, 'esES', '¡Atención a las cuerdas! ¡Que quede bien amarrada!', '', 28153),
(141608, 'esES', '', 'Aquí tienes, $n. La traducción de tu diario. Si quieres mi opinión, es interesantísimo.', 28153),
(141607, 'esES', '', '¿Sí? ¡Sí! ¡Eso es! Ahora, ¿dónde están mis libros vacíos de...? Ajá, aquí hay uno.', 28153),
(141606, 'esES', '', '¡AH! Entonces la runa es para ESO. Interesante...', 28153),
(141605, 'esES', '', '¿Los tienes todos? Excelente trabajo, $n. Ahora a traducir este diario.', 28153),
(141604, 'esES', '<El soldado murmura de forma ininteligible en voz baja>.', '<La soldado murmura de forma ininteligible en voz baja>.', 28153),
(141603, 'esES', 'Aquí tienes los libros que pediste.', 'Aquí tienes los libros que pediste.', 28153),
(141602, 'esES', '¿Está subiendo la marea, o es que estamos cayendo?\n\nMás y más profundo...', '¿Está subiendo la marea, o es que estamos cayendo?\n\nMás y más profundo...', 28153),
(141601, 'esES', 'Perfecto, perfecto, dijo que todo debía ser perfecto...\n\n¿Qué lo dijo?', 'Perfecto, perfecto, dijo que todo debía ser perfecto...\n\n¿Qué lo dijo?', 28153),
(141600, 'esES', '¡Loh Zandalari van a llevarse una gran sorpresa muy pronto!', '¡Loh Zandalari van a llevarse una gran sorpresa muy pronto!', 28153),
(141599, 'esES', 'Loh tragadoneh ehtán creciendo muy bien. Pronto podremoh montarloh.', 'Loh tragadoneh ehtán creciendo muy bien. Pronto podremoh montarloh.', 28153),
(141598, 'esES', 'Lo siento, madre, me apartaré de tu camino de inmediato.', 'Lo siento, madre, me apartaré de tu camino de inmediato.', 28153),
(141597, 'esES', 'Máh te vale afilarte bien el cuchillo, he oído que vamoh a luchar contra loh Zandalari pronto.', 'Máh te vale afilarte bien el cuchillo, he oído que vamoh a luchar contra loh Zandalari pronto.', 28153),
(141596, 'esES', 'Jefa de guerra Sylvanas Brisaveloz, te presento a la jefa Mayla Monte Alto.', '', 28153),
(141595, 'esES', 'Una de nuestras mochilas. Parece que hemos encontrado el lugar correcto.', '', 28153),
(141594, 'esES', 'Una de nuestras hachas. Estamos en el buen camino.', '', 28153),
(141593, 'esES', 'Esta pobre alma lleva tiempo sin vida. Busquemos el carro de suministros al este.', '', 28153),
(141592, 'esES', 'No te he vihto anteh. Deberíah darte prisa y entrar, dicen que el grupo de trabajo de Najima ha aparecido muerto.', 'No te he vihto anteh. Deberíah darte prisa y entrar, dicen que el grupo de trabajo de Najima ha aparecido muerto.', 28153),
(141591, 'esES', 'El último resguardo se colocó en la Cima Monte Alto. Es allí adonde debemos dirigirnos. Tenemos que trabajar juntos, como hicieron Huln y sus aliados.', '', 28153),
(141590, 'esES', 'Así es. Y cuando dejé la montaña para visitar Mulgore, los resguardos se debilitaron lo suficiente para que la Oscuridad recuperara el control.', '', 28153),
(141589, 'esES', '', 'Así que los Necroscuro han vagado entre las sombras, esperando el momento de invocar a su maestro...', 28153),
(141588, 'esES', 'Por lo que Huln ideó un plan: colocar resguardos para capturar al enviado de los dioses antiguos. Aunque Uul\'gyneth sobrevivió, consiguieron atrapar su esencia.', '', 28153),
(141587, 'esES', 'Huln reunió a héroes de todas las tribus para enfrentarse juntos a los sirvientes de Uul\'gyneth, los Necroscuro. Pero las fuerzas sombrías eran demasiado poderosas...', '', 28153),
(141586, 'esES', 'Hace tiempo, los dioses antiguos intentaron conquistar Monte Alto. Su campaña la lideraba un terrible general: Uul\'gyneth, la Oscuridad.', '', 28153),
(141585, 'esES', 'Sígueme, adalid.', '', 28153),
(141584, 'esES', '<El alcalde no responde>.', '', 28153),
(141583, 'esES', '<Busca el origen del hechizo>.', '<Busca el origen del hechizo>.', 28153),
(141582, 'esES', '<La efigie que se erige amenazante en el centro de la ciudad palpita con una energía oscura similar a la que ha atrapado a los aldeanos. Tal vez sea el foco que mantiene el hechizo.\n\nSi se destruye, el hechizo podría romperse>.', '', 28153),
(141581, 'esES', '<Este hombre coincide con la descripción de Cyril White, el alcalde de Albergue del Ocaso. Desafortunadamente, no está en condiciones de ayudarte ahora mismo.\n\nEl alcalde, junto con el resto de habitantes de Albergue del Ocaso, parece estar bajo el efecto de una magia desconocida. Aunque sigue respirando, es incapaz de moverse o responder.\n\nTendrás que encontrar la forma de romper la maldición si quieres que te ayude a contactar con la casa Crestavía>.', '', 28153),
(141580, 'esES', '¡Me has salvado la vida! Me pregunto adónde me enviarán los Bellacos ahora...', '', 28153),
(141579, 'esES', '¡Los resguardos se han debilitado! ¡Será nuestro!', '', 28153),
(141578, 'esES', '¡Habéis fracasado! La Oscuridad se alza... ¡y Monte Alto caerá!', '', 28153),
(141577, 'esES', '¡La Legión no era nada comparada con nuestro poder! ¡Ríndete!', '', 28153),
(141576, 'esES', '¡Los Cuerno del Cielo servirán a mis maestros! ¡Seréis la sombra que oscurece los cielos!', '', 28153),
(141575, 'esES', '¡Sirve a tus auténticos maestros, drógbar! O muere...', '', 28153),
(141573, 'esES', '', '¡Saludos! ¿Te, mmm... interesa la historia de Kul Tiras? Tengo varios tomos sobre la fundación y la política de nuestra gran nación. Es una materia realmente fascinante, te lo aseguro.$b$b¡También soy una experta transcriptora y podría entrenarte en el arte de la tinta y la pluma!', 28153),
(141572, 'esES', 'Un paso en falso y te enterraremoh aquí.', '', 28153),
(141571, 'esES', 'Meerah, prepara el carro, hay que recoger los suministros del puerto. Nuestros nuevos aliados pueden venir y continuar su búsqueda.', '', 28153),
(141570, 'esES', 'Ehta humedad eh casi tan desagradable como tu cara.', 'Ehta humedad eh casi tan desagradable como tu cara.', 28153),
(141569, 'esES', '¿Y tú qué mirah?', '¿Y tú qué mirah?', 28153),
(141568, 'esES', 'Tieneh influencia en la casa real, así que no te mataremoh, por ahora.', 'Tieneh influencia en la casa real, así que no te mataremoh, por ahora.', 28153),
(141567, 'esES', 'Usurpadoreh. Tu Horda pagará por lo que le hizo a nuehtra gente en Tanaris.', 'Usurpadoreh. Tu Horda pagará por lo que le hizo a nuehtra gente en Tanaris.', 28153),
(141566, 'esES', 'Que tengas un buen día, $gseñor:señora;. ¿Te interesa el delicado arte lapidario?$b$bMás conocido como la joyería.', '', 28153),
(141565, 'esES', 'Sonríe mientrah puedah, $c. Si dah un paso en falso aquí, te mataremoh nosotroh mihmoh.', 'Sonríe mientrah puedah, $c. Si dah un paso en falso aquí, te mataremoh nosotroh mihmoh.', 28153),
(141564, 'esES', 'La Horda eligió a suh adoradoh elfoh de sangre en lugar de nosotroh. Y dehpuéh mataron a nuehtro gran líder, Zul\'jin.$b$bSangre. Loh tuyoh tienen una gran deuda de sangre con nosotroh, colega.', '', 28153),
(141563, 'esES', 'Anda con cuidado, colega. En cuanto la Princesa haya acabado contigo, tendráh que darle ehplicacioneh a mi cuchillo sobre lo que la Horda le hizo a Zul\'jin.', '', 28153),
(141562, 'esES', 'Tieneh la marca de la princesa Talanji y eso significa que no podemoh matarte, pero no tieneh por qué guhtarnoh.', '', 28153),
(141561, 'esES', '¿Y tú qué mirah?', '', 28153),
(141559, 'esES', '¡El templo ehtá en ruinah! Eh incluso peor de lo que me temía...', '', 28153),
(141558, 'esES', 'Debo volver deprisa al templo. Tengo miedo de lo que haya podido ocurrir en mi ausencia...', '', 28153),
(141557, 'esES', '', '¡Ahora me pertenecen!', 28153),
(141556, 'esES', 'Ya soy libre del control de los dioses antiguos. Gracias.', '', 28153),
(141555, 'esES', '¡Mayla! ¡Debemos permanecer unidos!', '', 28153),
(141554, 'esES', '', '¡No dejaré que la Oscuridad posea el cuerpo de mi padre!', 28153),
(141552, 'esES', 'Quería... ver...', 'Quería... ver...', 28153),
(141549, 'esES', '¡De cabeza al caldero!', '¡De cabeza al caldero!', 28153),
(141547, 'esES', '¡Ah, graciah por liberarme! ¡Debía haber sabido que no podía confiar en esoh Tortuka traicioneroh!', '', 28153),
(141546, 'esES', 'Vol\'jamba lo prometió...', 'Vol\'jamba lo prometió...', 28153),
(141544, 'esES', '¿Se... equivocó?', '¿Se... equivocó?', 28153),
(141538, 'esES', '¡Solo Vol\'jamba puede salvarnoh!', '¡Solo Vol\'jamba puede salvarnoh!', 28153),
(141536, 'esES', 'Ven... Rehpira un poco. ¡Veremoh quién tiene la voluntad máh fuerte!', '', 28153),
(141535, 'esES', 'Nunca me someteré...', 'Nunca me someteré...', 28153),
(141528, 'esES', 'Dijo... que... sobreviviría...', 'Dijo... que... sobreviviría...', 28153),
(141527, 'esES', '¡¿Por qué nadie ehcucha?! ¡Se acerca el fin!', '¡¿Por qué nadie ehcucha?! ¡Se acerca el fin!', 28153),
(141524, 'esES', 'Entendido, jefe.', '', 28153),
(141523, 'esES', '¡Leo!', '', 28153),
(141522, 'esES', '¡Ladrones de madera! ¡A por ellos, Leo!', '', 28153),
(141519, 'esES', '', 'Eh, ¿ereh tú? ¿Dónde ehtamoh?', 28153),
(141518, 'esES', 'Este T\'paartos ha jurado servir a la Luz, ¿pero trata con la oscuridad? ¡Este no puede ser el destino de T\'paartos!', '', 28153),
(141517, 'esES', 'Todo eh como dijo mi profeta. Quizá ahora comprendah por qué cuento con él.', '', 28153),
(141512, 'esES', 'Llévate el sello que te he dado y colócalo en el gong.', '', 28153),
(141510, 'esES', '¡Bah!', '', 28153),
(141509, 'esES', '¡Aléjate! ¡No toqueh!', '', 28153),
(141508, 'esES', 'La visión eh así: Velah doradah anuncian la última llegada. El manipulador ansía romper el sello.', '', 28153),
(141507, 'esES', 'Me siento generoso. Te ehcucharé. Sin embargo, mi acompañante...', '', 28153),
(141506, 'esES', 'Tengo que hablar con mi antiguo aprendiz. Me encontraráh cuando te hayah ocupado de suh seguidoreh.', '', 28153),
(141505, 'esES', 'Deja de ocultarte detráh de tuh máhcarah. Solo retrasah lo inevitable... Y no por mucho tiempo.', '', 28153),
(141504, 'esES', 'Ya veo. ¡Ah, portavoz! Juhto a quien necesitamoh.', '', 28153),
(141503, 'esES', 'Se hará lo que ordeneh. Pero... he previhto que no seré yo quien mate a Vol\'jamba.', '', 28153),
(141502, 'esES', 'Tú hah provocado ehte caoh, profeta. Ahora arréglalo.', '', 28153),
(141501, 'esES', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|tLa |cFFFF0000|Hspell:258068|h[Mirada de Sargeras]|h|r se lanza sobre el combate...', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|tLa |cFFFF0000|Hspell:258068|h[Mirada de Sargeras]|h|r se lanza sobre el combate...', 28153),
(141500, 'esES', '¡Nigel! ¡Ahí estás!', '', 28153),
(141499, 'esES', '', '¿Qué sería la exploración sin un poco de peligro? No tengo ni un rasguño.', 28153),
(141498, 'esES', '', 'Y eso es todo lo que he podido sacar por mi cuenta.', 28153),
(141497, 'esES', 'Solo me alegro de que hayas podido salir.', '', 28153),
(141496, 'esES', '¿El camino lleva a la grandeza? ¿A la gloria? ¿O a la aniquilación?', '', 28153),
(141495, 'esES', 'El alma atesora muchas verdades. Algunas nobles, otras...', '', 28153),
(141494, 'esES', 'Una oferta rechazada... pero el miedo permanece.', '', 28153),
(141493, 'esES', 'Puede que para superar el miedo a la oscuridad haya que rendirse a él.', '', 28153),
(141492, 'esES', 'El miedo es incansable. Implacable. Un enemigo al que hay que derrotar.', '', 28153),
(141491, 'esES', 'A salvo. Seguro. Alejado de todos y de todo.', '', 28153),
(141490, 'esES', '¿Y si la respuesta es la soledad? Nadie puede herirte si estás solo.', '', 28153),
(141489, 'esES', 'Los enemigos acechan en las sombras. ¿Se puede detener esta oscuridad?', '', 28153),
(141488, 'esES', '¡Es injusto! ¡Nada es lo que parece!', '', 28153),
(141487, 'esES', 'Las distracciones son una vía de escape.', '', 28153),
(141486, 'esES', 'Esconderte... Ponerte a salvo... Buscar consuelo...', '', 28153),
(141485, 'esES', '¿No existe descanso? ¿Ni sosiego?', '', 28153),
(141484, 'esES', 'Hasta en la peor situación se puede encontrar alivio.', '', 28153),
(141483, 'esES', 'Angustia y dolor... La búsqueda de consuelo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141482, 'esES', 'Aquí no existe la bondad.', '', 28153),
(141481, 'esES', 'El dolor es el arquitecto de los recuerdos.', '', 28153),
(141480, 'esES', 'El único camino es hacia delante.', '', 28153),
(141479, 'esES', 'Recuerdo la época en que solo los trols podían entrar en Zandalar. Bueno... los trols y los tortolianos, claro.\n\nJe, intentaron deshacerse de nosotros una vez. Creo que fue el bisabuelo de Rastakhan, el rey Tezlekhan el Virulento. Era un engreído. Le hicimos cambiar de parecer más rápido que un elemental en una reunión de chamanes.\n\nTe sorprendería la cantidad de trapos sucios que puedes conocer de una familia real cuando vives más que ellos.', 'Recuerdo la época en que solo los trols podían entrar en Zandalar. Bueno... los trols y los tortolianos, claro.\n\nJe, intentaron deshacerse de nosotros una vez. Creo que fue el bisabuelo de Rastakhan, el rey Tezlekhan el Virulento. Era un engreído, pero le hicimos cambiar de parecer más rápido que a un elemental en una reunión de chamanes.\n\nTe sorprendería la cantidad de trapos sucios que puedes conocer de una familia real cuando vives más que ellos.', 28153),
(141478, 'esES', 'Los Zandalari conceden a nuestra gente paso libre por sus tierras a cambio de información útil.\n\nMe pregunto qué les habréis prometido vosotros.', 'Los Zandalari conceden a nuestra gente paso libre por sus tierras a cambio de información útil.\n\nMe pregunto qué les habréis prometido vosotros.', 28153),
(141477, 'esES', 'Ah... $gun:una; $c. ¿De qué continente vienes?', 'Ah... $gun:una; $c. ¿De qué continente vienes?', 28153),
(141476, 'esES', '', 'Ehperemoh que Rokham y loh otroh hayan llegado a salvo a Zul\'jan. Si no, ehte va a ser un viaje muy corto.', 28153),
(141475, 'esES', 'Ah, $gun aventurero:una aventurera;. ¿Qué tarifas tienes? Puede que necesite ayuda más tarde con una tarea bastante... peligrosa. Necesito recuperar un objeto muy valioso.', 'Ah, $gun aventurero:una aventurera;. ¿Qué tarifas tienes? Puede que necesite ayuda más tarde con una tarea bastante... peligrosa. Necesito recuperar un objeto muy valioso.', 28153),
(141474, 'esES', '¿Nos conocemos? Mi memoria no es lo que era hace cien años.', '¿Nos conocemos? Mi memoria no es lo que era hace cien años.', 28153),
(141473, 'esES', 'Vaya, ¿permiten a la Horda entrar en Zuldazar? Qué progresistas.', 'Vaya, ¿permiten a la Horda entrar en Zuldazar? Qué progresistas.', 28153),
(141472, 'esES', '', '', 28153),
(141471, 'esES', '', 'Acabad con esoh trolh de sangre. ¡Que no hundan la barca!', 28153),
(141470, 'esES', '', 'Mira... trolh de sangre. Deben ehtar preparándose pa atacar mi ciudad.', 28153),
(141469, 'esES', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|t¡Sal de las bahías de construcción durante |cFFFF0000|Hspell:248061|h[Protocolo de purga]|h|r para que no te maten!', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|t¡Sal de las bahías de construcción durante |cFFFF0000|Hspell:248061|h[Protocolo de purga]|h|r para que no te maten!', 28153),
(141468, 'esES', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t¡Aléjate del jefe durante |cFFF00000|Hspell:246220|h[Bombardeo vil]|h|r para evitar el daño!', '', 28153),
(141467, 'esES', '|TInterface\\ICONS\\spell_shadow_shadesofdarkness.blp:20|t¡Ponte cerca de los aliados para evitar |cFFF00000|Hspell:243963|h[Solo en la oscuridad]|h|r!', '', 28153),
(141466, 'esES', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tLos destructores imbuidos de vileza dañan a Eonar con su |cFFFF0000|Hspell:246305|h[Ataque de artillería]|h|r, procura acabar con ellos rápidamente.', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|tLos destructores imbuidos de vileza dañan a Eonar con su |cFFFF0000|Hspell:246305|h[Ataque de artillería]|h|r, procura acabar con ellos rápidamente.', 28153),
(141465, 'esES', 'Esta criatura se girará y atacará a los jugadores. ¡Asegúrate de que esté atacando a un tanque antes de atacarla tú!', 'Esta criatura se girará y atacará a los jugadores. ¡Asegúrate de que esté atacando a un tanque antes de atacarla tú!', 28153),
(141464, 'esES', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|t|cFFFF0000|Hspell:248333|h[Tormenta de meteoritos]|h|r se puede esquivar, procura evitar su impacto.', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|t|cFFFF0000|Hspell:248333|h[Tormenta de meteoritos]|h|r se puede esquivar, procura evitar su impacto.', 28153),
(141463, 'esES', '¿Qué esh eshe shonido?', '', 28153),
(141462, 'esES', '¿Hola? ¿Hay alguien ahí?', '', 28153),
(141461, 'esES', '¡NUB NUB, SUBE AQUÍ Y LIMPIA ESTA KAKA!', '', 28153),
(141460, 'esES', 'Muévete, lagarto de ojoh vacíoh.', 'Muévete, lagarto de ojoh vacíoh.', 28153),
(141459, 'esES', '', 'Negociah como un gusano. Di la verdad, ¿qué quiereh?', 28153),
(141458, 'esES', '', 'Raal, tu mujer intentó matarme ehta mañana. ¿Qué se pensará que ehtáh tramando aquí?', 28153),
(141457, 'esES', '', 'Raal, tenemoh que resolver ehto. Esah peticioneh de loh Amani tienen que parar.', 28153),
(141456, 'esES', '¡Un yeti! Casi acierto. Tiene forma de hombre y es peludo como un oso.', '', 28153),
(141455, 'esES', '', 'Argh... Sholo con PENSHAR en lash algash me shiento... mareada... <eructo> Upsh...', 28153),
(141454, 'esES', '', '¿Algo shobre cubrirlo con algash?', 28153),
(141453, 'esES', '', '<Eructo> Ah, shí, recuerdo a un zoquete que fanfarroneaba shobre un teshoro.', 28153),
(141452, 'esES', '¿Por qué tenemoh que hacer guardia aquí, colega? Ehto eh ridículo.', '¿Por qué tenemoh que hacer guardia aquí, colega? Ehto eh ridículo.', 28153),
(141451, 'esES', '', '¡Guaaaauuu! <Hip>$b$b¿Eh? ¿Qué pasha?', 28153),
(141450, 'esES', '<Suspira>. No ayuda a Nub Nub, eso seguro.', '', 28153),
(141449, 'esES', 'Solo dijo que estaba enterrado en un \"lugar arenoso\". ¿A quién ayuda eso?', '', 28153),
(141448, 'esES', 'Nub Nub ha oído lo del tesoro. ¡Toda la taberna lo ha oído!', '', 28153),
(141447, 'esES', '¿Hay que limpiar algo?', '', 28153),
(141446, 'esES', 'TESORO. ENTERRADO.', 'TESORO. ENTERRADO.', 28153),
(141445, 'esES', '¡¿UN TORO ATERRADO?!', '', 28153),
(141444, 'esES', 'No, no. Tesoro enterrado.', 'No, no. Tesoro enterrado.', 28153),
(141443, 'esES', '¿AFORO CERRADO?', '', 28153),
(141442, 'esES', 'UN TIPO ESTABA FANFARRONEANDO SOBRE LOS PLACERES DEL MATRIMONIO EL OTRO DÍA EN LA TABERNA. COMO SI A ALGUIEN LE IMPORTARA.', '', 28153),
(141441, 'esES', 'NO, NO SÉ NADA DE UN TESORO.', '', 28153),
(141440, 'esES', 'OOOOOH. TESORO ENTERRADO.', '', 28153),
(141439, 'esES', '<Enseñas el cartel>. ¿Qué sabes de este tesoro enterrado?', '<Enseñas el cartel>. ¿Qué sabes de este tesoro enterrado?', 28153),
(141438, 'esES', '¿QUÉEE? TENDRÁS QUE HABLAR MÁS ALTO. NO OIGO BIEN DESDE...$b$bEL INCIDENTE.', '', 28153),
(141435, 'esES', '¡Pete el Curioso!', '', 28153),
(141434, 'esES', '', '¡Sonreíd todo el rato! ¡Nunca se sabe si habrá un huésped mirando, sobre todo los sigilosos!', 28153),
(141433, 'esES', '', 'Recordad, si un huésped os hace una pregunta y no sabéis la respuesta, ¡inventáosla! Utilizad el ingenio gnómico.', 28153),
(141432, 'esES', '', '¡Trabajad esos hoyuelos, reclutas! ¡Demostradles lo increíblemente adorables que podemos ser los gnomos!', 28153),
(141431, 'esES', '¡¿Qué?! ¡No es justo! ¡Eso no es justo!', '', 28153),
(141430, 'esES', '', '¡Flynn! ¡Aguanta!', 28153),
(141429, 'esES', '¡Diez mil monedas de oro a quien me traiga sus cabezas!', '', 28153),
(141428, 'esES', '¡Los Valiente están acabados! Cuando lady Gobernalle ocupe el trono, ¡yo comandaré la flota!', '', 28153),
(141427, 'esES', '¡Basta! ¡Es demasiado tarde de todas formas! ¡Ya hemos iniciado el ataque contra la Puerta de Daelin!', '', 28153),
(141426, 'esES', '¡Estos dados están malditos! ¡Vamos, adelante!', '', 28153),
(141425, 'esES', 'Harlan tira una bolsa entera de dados y casi todo lo que saca son tesoros.', 'Harlan tira una bolsa entera de dados y casi todo lo que saca son tesoros.', 28153),
(141424, 'esES', 'Harlan vuelve a tirar los dados y saca un cañón y dos calaveras.', 'Harlan vuelve a tirar los dados y saca un cañón y dos calaveras.', 28153),
(141423, 'esES', 'Harlan saca dos tesoros y una brújula.', 'Harlan saca dos tesoros y una brújula.', 28153),
(141422, 'esES', 'Harlan saca tres espadas.', 'Harlan saca tres espadas.', 28153),
(141421, 'esES', '¡Mucho mejor! ¿He mencionado que no juego limpio? ¡Ja, ja!', '', 28153),
(141420, 'esES', '¡¿Qué?! No, no, no, no, no. Esto está mal.', '', 28153),
(141419, 'esES', '¡Bah! ¡De acuerdo! ¡Tiro otra vez!', '', 28153),
(141418, 'esES', '¡Ah, mira, una cara nueva! Espero que seas más interesante que esta gente.', '', 28153),
(141417, 'esES', '¡Oh, mala suerte! Ja, ja. ¡Linchamiento!', '', 28153),
(141416, 'esES', 'Mm... ¿Qué hacer con un par de ratas amotinadas? ¡Que decidan los dados!', '', 28153),
(141415, 'esES', '¡Jo, jo, jo! ¡Carne fresca! ¡Esto va a ser divertido!', '', 28153),
(141414, 'esES', '', 'Mi marido nunca dejará de explotar a sus trabajadores...', 28153),
(141413, 'esES', 'Las cosas han cambiado, Flynn. Ahora soy yo el capitán. En cuanto nos deshagamos de los Valiente, ¡tendremos vía libre para saquear todo Kul Tiras!', '', 28153),
(141412, 'esES', 'Nghh... Corre...', '', 28153),
(141411, 'esES', '¡Eso es, muchachos! Dadle su merecido.', '', 28153),
(141410, 'esES', '', 'Es hora de que te aventures más allá de nuestros picos sagrados.', 28153),
(141409, 'esES', '', 'Hubo veces en las que nos dividimos o perdimos el rumbo, pero los espíritus de nuestros ancestros nos recordaron que nos unen la tierra, el río y el cielo. Que somos familia. Y por la familia merece la pena luchar.', 28153),
(141408, 'esES', '', 'Hay algo más que tierra y piedras en estas palabras. Cuentan la historia de nuestro pueblo, que hizo frente a las adversidades para unirse contra enemigos comunes.', 28153),
(141407, 'esES', '', 'Monte Alto resiste.', 28153),
(141406, 'esES', '', '¡Interponerte en mi camino es una necedad!', 28153),
(141405, 'esES', '', '¡Silgryn! ¡Valtrois! ¡Ayudad al Señor regente!', 28153),
(141404, 'esES', '¡Basta! ¡Debemos limpiar la corrupción o la fuente estará perdida!', '', 28153),
(141403, 'esES', '', 'No pretendía que mi presencia...', 28153),
(141402, 'esES', '¡Por eso pedí el exilio de Umbric y de sus radicales! Aquellos que usan el Vacío son un peligro para la Fuente del Sol.', '', 28153),
(141401, 'esES', '¿Qué está pasando?', '', 28153),
(141400, 'esES', '¡Atrás!', '', 28153),
(141399, 'esES', '', 'La Fuente del Sol ha cambiado, pero conserva su belleza. Ha pasado tanto tiempo...', 28153),
(141398, 'esES', '', 'Nuestro enemigo corrompió la Fuente del Sol, pero un sacrificio naaru purificó sus aguas. Ahora la esencia de la Luz nos da sustento.', 28153),
(141397, 'esES', '', 'Siento el poder. Tan potente como el de la Fuente de la Noche, pero de naturaleza distinta.', 28153),
(141396, 'esES', 'Seguidme.', '', 28153),
(141395, 'esES', 'Rommath, haz los honores.', '', 28153),
(141394, 'esES', '', 'Será un honor ver La Fuente del Sol, Lor\'themar. Aunque prefiero que mis amigos me llamen Thalyssra.', 28153),
(141393, 'esES', 'Da igual en lo que se haya convertido: Alleria es una hija de Quel\'Thalas. No me interpondré en su peregrinaje a nuestro lugar más sagrado. Primera Arcanista, ¿por qué no nos acompañas con tu séquito?', '', 28153),
(141392, 'esES', 'No lo aconsejo. ¿Cómo sabemos que no...?', '', 28153),
(141391, 'esES', '', 'Hace mil años que no veo la Fuente del Sol. ¿Podría visitarla una vez más?', 28153),
(141389, 'esES', '', 'Veo que no necesitas oír la oferta para rechazarla. Que así sea. Pero antes de partir, me gustaría pedirte un favor.', 28153),
(141388, 'esES', 'Dudas de mis palabras, ¿pero cómo podemos confiar en las tuyas? ¿Niegas que los señores del Vacío te susurran? ¿Acaso no te rendiste a las sombras en Argus?', '', 28153),
(141387, 'esES', '', 'Mordaces palabras, Lor\'themar. ¿Son tuyas? ¿O ahora el leal forestal que conocí solo repite lo que le dice su Jefa de Guerra?', 28153),
(141384, 'esES', 'Esperaba que tu visita estuviera motivada por tu amor a Lunargenta, no por las órdenes de ese \"niño rey\" de la Alianza. ¡Qué decepción!', '', 28153),
(141383, 'esES', '', 'Como desees. Traigo una oferta de su Majestad, el rey Anduin...', 28153),
(141382, 'esES', 'Pamplinas. Lo que tengas que decir puedes decirlo frente a nuestros invitados.', '', 28153),
(141381, 'esES', '', 'El honor es mío, Primera Arcanista. Pero no quiero interrumpir tu visita. Quizás debería volver más tarde.', 28153),
(141380, 'esES', '', 'Un honor inesperado, lady Brisaveloz. Silgryn me ha hablado de tu valor en la campaña de Argus.', 28153),
(141379, 'esES', 'Llámame Lor\'themar. Ah, y permíteme presentarte a otra de nuestras invitadas: lady Alleria Brisaveloz, una heroína del pasado de Lunargenta.', '', 28153),
(141376, 'esES', '', 'Me alegro de poder visitar al fin vuestra hermosa ciudad. Gracias por la invitación, Señor regente.', 28153),
(141375, 'esES', '', 'Primera arcanista Thalyssra y demás invitados de honor, bienvenidos a Lunargenta.', 28153),
(141374, 'esES', 'No tengo secretos con nuestros aliados, Alleria. Además, algunos de nuestros nuevos amigos acaban de llegar.', '', 28153),
(141373, 'esES', '', 'Hola de nuevo, Liadrin, adalid. Lor\'themar, he venido a tratar un asunto... en privado.', 28153),
(141372, 'esES', 'Lady Liadrin, adalid... Os doy la bienvenida. Como podéis ver, tenemos... una visita inesperada.', '', 28153),
(141371, 'esES', '', 'A tus órdenes. Reúnete conmigo en la finca de lady Thalyssra en Suramar, adalid.', 28153),
(141370, 'esES', '', 'No volváis hasta que Suramar haya jurado lealtad a la Horda. Sé que no me fallaréis.', 28153),
(141369, 'esES', '', 'El Señor regente ha invitado a los Nocheterna a Lunargenta. Debo viajar a Suramar y escoltar a lady Thalyssra hasta allí.', 28153),
(141366, 'esES', '', 'Para asegurar el futuro de nuestro pueblo, debes ayudarnos a recuperar nuestro lugar en Azeroth.', 28153),
(141365, 'esES', '', 'Nuestros líderes nos traicionaron; hicieron un trato con los demonios. Pero nos rebelamos contra la tiranía... y expulsamos al enemigo. Suramar vuelve a ser nuestra. Jamás permitiremos que sucumba de nuevo a la oscuridad.', 28153),
(141364, 'esES', '', 'A medida que pasaron los años, Azeroth cambió a nuestro alrededor. Y cayó en manos de la Legión.', 28153),
(141363, 'esES', '', 'Durante diez mil años, Suramar fue todo lo que conocimos.', 28153),
(141362, 'esES', '', 'Vuestra misión como forjados por la Luz es convertiros en un foco de esperanza en la oscuridad...', 28153),
(141361, 'esES', '', 'Al fin, nuestro enemigo ha caído. La Legión ya no existe... Pero nuestra guerra continúa. Nuevas amenazas acechan entre las sombras, esperando el momento de atacar.', 28153),
(141360, 'esES', '', 'Durante miles de años de conflicto, la Luz nos ha mostrado el auténtico camino.', 28153),
(141359, 'esES', '', 'Somos soldados.', 28153),
(141358, 'esES', '', 'El Vacío nos ha moldeado... nos ha cambiado. Pero aprenderás a controlarlo.', 28153),
(141357, 'esES', '', 'No comprenden la realidad como nosotros.', 28153),
(141356, 'esES', '', 'Los sabios y académicos temen el Vacío.', 28153),
(141355, 'esES', '', 'El Vacío. Una fuerza de hambre infinita.', 28153),
(141354, 'esES', '', 'Voy a la barca, reúnete conmigo allí.', 28153),
(141353, 'esES', 'Que Bwonsamdi te bendiga, $gforahtero:forahtera;.', '', 28153),
(141352, 'esES', '', 'Loh goblinh me aseguraron que el plan funcionaría... y te necesito aquí pa garantizar que así sea.$b$b¿Ehtáh $glihto:lihta; pa dar un paseo por el río?', 28153),
(141351, 'esES', 'Nuestro campeón que duerme con los peces... ¡literalmente! El fanático de Fuerte Libre... el maestro de las mandíbulas molidas... el portentoso púgil de puños poderosos... ¡Trothak, el Atizatiburones!', '', 28153),
(141350, 'esES', '¡Increíble! ¡Estas ratas sudorosas han logrado superar a Gryff y Stevin! Solo queda un contendiente y no necesita presentación.', '', 28153),
(141349, 'esES', 'Dos presagistas de fatalidad de mucho peso... Los que parten la pana allá donde van... Un dúo de destrucción doble... ¡Gryff y Stevin!', '', 28153),
(141348, 'esES', 'Sin más dilación, aquí llega un peligroso dúo de tierras lejanas. Un par inimitable de bestias combativas que aterra incluso a los guerreros más intrépidos.', '', 28153),
(141347, 'esES', '¡Sufre, $gprofanador:profanadora;!', '', 28153),
(141345, 'esES', '¡No saldrás de aquí!', '', 28153),
(141344, 'esES', '¡Ludwig ha caído! ¡Menudo combate! Estos bucaneros malolientes son duros... y más les vale serlo, porque su siguiente desafío es la brutalidad personificada.', '', 28153),
(141343, 'esES', 'Sálvate... tú...', '', 28153),
(141342, 'esES', '', '¡Niña dehdichada! ¡Hice un trato con Bwonsamdi pa vivir a cambio de tu alma! ¡Lo vah a arruinar todo!', 28153),
(141341, 'esES', 'De las cloacas de Fuerte Libre llega un salteador tortoliano emperrado en zurraros de lo lindo. Es el relámpago de la defensa... el sargento quelonio... un demonio con caparazón... Es... ¡Ludwig!', '', 28153),
(141340, 'esES', '¡Vaya! Han atrapado a un cerdo. Quizás haya que pasar a un desafío más... ¡amenazador!', '', 28153),
(141334, 'esES', '', '¿Nunca hah oído hablar del clan Diente Ohcuro? No me sorprende, la tribu fue aniquilada por el Martillo Crepuhcular.\n\nLoh Zandalari conservan un representante como recuerdo del pasado. Ahora no soy máh que una curiosidad.\n\nNo ehtá tan mal. Nunca tengo que pagarme lah bebidah.', 28153),
(141332, 'esES', 'Dicen que el rey Rahtakhan no se encuentra muy bien últimamente. Eh solo cuehtión de tiempo que todo Zandalar caiga. ¿Dónde ehtaremoh entonceh?', 'Dicen que el rey Rahtakhan no se encuentra muy bien últimamente. Eh solo cuehtión de tiempo que todo Zandalar caiga. ¿Dónde ehtaremoh entonceh?', 28153),
(141331, 'esES', 'Antaño, loh Zandalari gobernaron a todoh loh trolh. Ahora, ni siquiera pueden defender suh fronterah.', 'Antaño, loh Zandalari gobernaron a todoh loh trolh. Ahora, ni siquiera pueden defender suh fronterah.', 28153),
(141330, 'esES', 'Loh Zandalari permiten que la magia de sangre cruce suh fronterah. Solo eh cuehtión de tiempo que loh lleve a su dehtrucción.', 'Loh Zandalari permiten que la magia de sangre cruce suh fronterah. Solo eh cuehtión de tiempo que loh lleve a su dehtrucción.', 28153),
(141329, 'esES', 'Loh Zandalari envían a todo el que causa problemah al desierto. Ninguno vuelve.', 'Loh Zandalari envían a todo el que causa problemah al desierto. Ninguno vuelve.', 28153),
(141328, 'esES', 'En tiempoh, loh Zandalari fueron la tribu máh orgullosa, y ahora ese orgullo eh lo único que mantiene el lugar en pie.', 'En tiempoh, loh Zandalari fueron la tribu máh orgullosa, y ahora ese orgullo eh lo único que mantiene el lugar en pie.', 28153),
(141327, 'esES', 'Tieneh un ahpecto delicioso.', 'Tieneh un ahpecto delicioso.', 28153),
(141326, 'esES', 'Odio a loh elfoh. Odio a loh no-muertoh. La Horda tiene amboh.', 'Odio a loh elfoh. Odio a loh no-muertoh. La Horda tiene amboh.', 28153),
(141325, 'esES', 'La flota dorada representa el poder real de loh Zandalari. Quien controla la flota, tiene el poder.', 'La flota dorada representa el poder real de loh Zandalari. Quien controla la flota, tiene el poder.', 28153),
(141324, 'esES', 'Dicen que el rey Rahtakhan no se encuentra muy bien últimamente. Eh solo cuehtión de tiempo que todo Zandalar caiga. ¿Dónde ehtaremoh entonceh?', 'Dicen que el rey Rahtakhan no se encuentra muy bien últimamente. Eh solo cuehtión de tiempo que todo Zandalar caiga. ¿Dónde ehtaremoh entonceh?', 28153),
