(140136, 'esES', 'Adiós.', '', 28153),
(140135, 'esES', '', 'Busca la paz, pero prepárate para la guerra.', 28153),
(140134, 'esES', 'Busca la paz, pero prepárate para la guerra.', '', 28153),
(140133, 'esES', 'Sirve con valor y humildad.', '', 28153),
(140132, 'esES', '', 'Sirve con valor y humildad.', 28153),
(140131, 'esES', 'Nos abriremos paso en este mundo.', '', 28153),
(140130, 'esES', '', 'Nos abriremos paso en este mundo.', 28153),
