(167308, 'esMX', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'esMX', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'esMX', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
(167305, 'esMX', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 28153),
(167304, 'esMX', 'I want to teleport to Temple of Sethraliss (Dungeon).', 'I want to teleport to Temple of Sethraliss (Dungeon).', 28153),
(167302, 'esMX', 'I want to teleport to Siege of Boralus (Dungeon).', 'I want to teleport to Siege of Boralus (Dungeon).', 28153),
(167301, 'esMX', 'I want to teleport to Shrine of the Storm (Dungeon).', 'I want to teleport to Shrine of the Storm (Dungeon).', 28153),
(167300, 'esMX', 'I want to teleport to Kings\' Rest (Dungeon).', 'I want to teleport to Kings\' Rest (Dungeon).', 28153),
