(167298, 'esMX', 'I want to teleport to Atal\'dazar (Dungeon).', 'I want to teleport to Atal\'dazar (Dungeon).', 28153),
(167297, 'esMX', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'esMX', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'esMX', 'Ciudad Forjatiniebla', 'Ciudad Forjatiniebla', 28153),
(162170, 'esMX', '¡No puedes abandonar tu deber, regresa a Darnassus!', '¡No puedes abandonar tu deber, regresa a Darnassus!', 28153),
(162169, 'esMX', '', '¿Estás $Ulisto:lista; para acabar con esto de una vez por todas, $n?', 28153),
(162168, 'esMX', '<Volar a Dalaran>', '<Volar a Dalaran>', 28153),
(162167, 'esMX', '¿Puedes llevar a Loh a todas las tiendas, y después a la posada, sin volver a cruzar el camino que ya ha tomado?', '', 28153),
(162166, 'esMX', '', '¿Estás $Ulisto:lista; para defender a las pequeñas tortugas mientras se abren paso hasta el mar?', 28153),
(162165, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(162164, 'esMX', 'Te doy la bienvenida, $n. ¿Crees que tienes la destreza mental para superar mi juego de memoria?', '', 28153),
(162161, 'esMX', '¿Estás seguro de que quieres omitir la introducción de la Costa Oscura?', '¿Estás segura de que quieres omitir la introducción de la Costa Oscura?', 28153),
(162160, 'esMX', '¿Sí, $n? Parece que algo te preocupa...', '', 28153),
(162159, 'esMX', '<El marinero perdido te observa con desconfianza. No deberías estar aquí.>', '<El marinero perdido te observa con desconfianza. No deberías estar aquí.>', 28153),
(162158, 'esMX', 'Ya he oído esa historia... <Omitir las misiones introductorias y comenzar tu viaje en Costa Oscura.>', 'Ya he oído esta historia... <Omitir la gesta y comenzar tu próxima misión.>', 28153),
(162157, 'esMX', 'Te llevaré a un lugar seguro, $n. ¡Sujétate bien!', '', 28153),
(162156, 'esMX', '¡La ira de la naturaleza cae sobre ustedes!', '', 28153),
(162155, 'esMX', 'Sujétate fuerte de mis ramas, $c.', '', 28153),
(162152, 'esMX', '¡Nos aseguraremos de que esta azerita no caiga en manos de la Alianza!', '¡Nos aseguraremos de que esta azerita no caiga en manos de la Alianza!', 28153),
(162151, 'esMX', '|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t¡Encerraron a $n en |cFFF00000|Hspell:260551|h[Espinas de alma]|h|r!', '', 28153),
(162150, 'esMX', 'Deseo ayudar al Almirantazgo con su campaña en Kul Tiras. <Establece la reputación con el Almirantazgo Valiente en Amistoso.>', 'Deseo ayudar al Almirantazgo con su campaña en Kul Tiras. <Establece la reputación con el Almirantazgo Valiente en Amistoso.>', 28153),
(162149, 'esMX', '¡Eres $Uel:la; mejor, $n!', '¡Eres $Uel:la; mejor, $n!', 28153),
(162148, 'esMX', '$n luce tan bien.', '$n luce tan bien.', 28153),
(162147, 'esMX', '¡Tú puedes!', '¡Tú puedes!', 28153),
(162146, 'esMX', '¡Eso es!', '¡Eso es!', 28153),
(162145, 'esMX', '¡$n! ¡$n! ¡$n!', '¡$n! ¡$n! ¡$n!', 28153),
(162144, 'esMX', '¡Es $n! ¡$n ha subido al escenario!', '¡Es $n! ¡$n ha subido al escenario!', 28153),
(162143, 'esMX', '¡Vamos $n! ¡Iujuuu!', '¡Vamos $n! ¡Iujuuu!', 28153),
(162142, 'esMX', '¡Vamos, $n!', '¡Vamos, $n!', 28153),
(162141, 'esMX', 'Mi forja está siempre lista, $n.', 'Mi forja está siempre lista, $n.', 28153),
(162140, 'esMX', 'Tomaré las raciones que tenemos y prepararé las camas disponibles. ¡Lok\'tar ogar!', 'Somos un puesto de avanzada pequeño, pero reuniré lo que tenemos. A la jefa de guerra y a su ejército no les faltará nada, ¡lo juro! ¡Lok\'tar ogar!', 28153),
(162139, 'esMX', '¡Zoram\'gar estará preparada! ¡Por la Horda!', '¡Zoram\'gar estará preparada! ¡Por la Horda!', 28153),
(162138, 'esMX', 'La jefa de guerra Sylvanas Brisaveloz necesita tu ayuda para reparar las armas de sus soldados.', 'La jefa de guerra Sylvanas Brisaveloz necesita tu ayuda para reparar las armas de sus soldados.', 28153),
(162137, 'esMX', '', 'Hay un camino oculto que podemos usar para regresar al vestíbulo de la mansión.', 28153),
(162135, 'esMX', '¡Volver a la Vega Crepuscular!', '', 28153),
(162134, 'esMX', '', '¡Fórjenlo! ¡Muéstrennos cómo se hace, enanos Hierro Negro!', 28153),
(162133, 'esMX', '', '¡Vamos, nene, mantenlo prendido fuego! ¡Un aplauso para los enanos Hierro Negro!', 28153),
(162132, 'esMX', '', 'Sus pasos de baile son de otro mundo. ¡Un aplauso para los Mag\'har!', 28153),
(162131, 'esMX', '', '¡Que suban los Mag\'har al escenario!', 28153),
(162130, 'esMX', 'Muéstrame las investigaciones posibles.', 'Muéstrame las investigaciones posibles.', 28153),
(162129, 'esMX', '¡Regresa al Río Culebra!', '', 28153),
(162128, 'esMX', '¡Regresa a La Espada del Maestro!', '', 28153),
(162127, 'esMX', '', 'Si quieres un trabajo bien hecho... ¡usa explosivos más grandes!', 28153),
(162123, 'esMX', '¡$n prepara un festín abundante del capitán!', '¡$n prepara un festín abundante del capitán!', 28153),
(162122, 'esMX', '¡$n prepara un banquete magistral!', '¡$n prepara un banquete magistral!', 28153),
(162121, 'esMX', '¿Estás seguro de que deseas omitir la Batalla por Lordaeron?', '¿Estás segura de que deseas omitir la Batalla por Lordaeron?', 28153),
(162120, 'esMX', 'Ya he oído esta historia... <Omitir la gesta y comenzar tu próxima misión.>', 'Ya he oído esta historia... <Omitir la gesta y comenzar tu próxima misión.>', 28153),
(162119, 'esMX', '', '¡Hermanas, vengan conmigo! ¡Debemos proteger nuestras tierras de la Horda!', 28153),
(162118, 'esMX', '', '¡Están atacando Costa Oscura! ¡Informaré a la suma sacerdotisa de inmediato!', 28153),
(162117, 'esMX', '¡Reúne a nuestros aliados del bosque! ¡Debemos preservar el Árbol del Mundo!', '', 28153),
(162116, 'esMX', '¡Están atacando Costa Oscura! ¡Debemos apresurarnos para proteger nuestro bosque!', '', 28153),
(162110, 'esMX', 'Debemos encargarnos del general Grebo.', 'Debemos encargarnos del general Grebo.', 28153),
(162109, 'esMX', 'Un gusto.', '', 28153),
(162108, 'esMX', '¡La Horda ha detenido su avance en el Río Culebra! ¡Debemos expulsarlos de inmediato!', '¡La Horda ha detenido su avance en el Río Culebra! ¡Debemos expulsarlos de inmediato!', 28153),
(162107, 'esMX', 'Oigo el eco de los tambores de guerra por el bosque. ¡Los druidas de la Zarpa están listos para proteger esta tierra de todos aquellos que osen destruirla!', '', 28153),
(162106, 'esMX', '¡Qué poder!', '', 28153),
(162105, 'esMX', 'Sí, es perfecto. Es exactamente lo que necesitaba. Solo me tomará un momento.', '', 28153),
(162104, 'esMX', 'Puedo sentirlo. ¡El fragmento rezuma poder! Es... hermoso, aunque aterrador.', '', 28153),
(162103, 'esMX', '', 'Hemos esperado mucho tiempo. Los Hierro Negro por fin emergeremos de la montaña para reclamar el lugar que nos corresponde en la Alianza.', 28153),
(162102, 'esMX', '¿Crees que me permitirán conducir mi tanque por las calles de Ventormenta?', '', 28153),
(162101, 'esMX', '¡Será mejor que los demás miembros de la Alianza se acostumbren a sus nuevos aliados ardientes!', '', 28153),
(162100, 'esMX', 'No me gustan las miradas que me lanzan los demás enanos en Ventormenta.', 'No me gustan las miradas que me lanzan los demás enanos en Ventormenta.', 28153),
(162099, 'esMX', 'No me acostumbro al brillo de la superficie.', 'No me acostumbro al brillo de la superficie.', 28153),
(162098, 'esMX', 'Una casa solo se consagra como hogar cuando tiene una fina capa de hollín.', 'Una casa solo se consagra como hogar cuando tiene una fina capa de hollín.', 28153),
(162097, 'esMX', '¡El fuego de Roca Negra arde por la Alianza!', '¡El fuego de Roca Negra arde por la Alianza!', 28153),
(162096, 'esMX', 'Casi todo puede arreglarse con una llave inglesa y una buena horquilla.', 'Casi todo puede arreglarse con una llave inglesa y una buena horquilla.', 28153),
(162095, 'esMX', 'Los Hierro Negro son los únicos enanos auténticos. ¡Los otros clanes son muy débiles!', 'Los Hierro Negro son los únicos enanos auténticos. ¡Los otros clanes son muy débiles!', 28153),
(162094, 'esMX', 'Somos la verdadera fuerza de la montaña.', 'Somos la verdadera fuerza de la montaña.', 28153),
(162093, 'esMX', '¿Qué quieres de mí? No me molestes, ¡no tengo paciencia!', '¿Qué quieres de mí? No me molestes, ¡no tengo paciencia!', 28153),
(162089, 'esMX', '¡Abandona este lugar!', '', 28153),
(162088, 'esMX', '¡Largo! ¡No eres $Ubienvenido:bienvenida; en nuestra guarida!', '', 28153),
(162087, 'esMX', '¡No conquistarás nuestro hogar!', '', 28153),
(162086, 'esMX', '¡Basta! ¡Piedad! Tú ganas...', '', 28153),
(162085, 'esMX', 'Muy bien... Déjame reunir a mi gente y nos marcharemos.', '', 28153),
(162084, 'esMX', '¡Alto! ¡Por favor! Me rindo...', '', 28153),
(162082, 'esMX', '', 'La Alianza recibe con los brazos abiertos a los draenei y sus Templeluz.\n\nEsa es razón suficiente para hacer polvo sus ciudades.', 28153),
(162081, 'esMX', '', '¿Hay draenei en este mundo?\n\n<Geya\'rah entrecierra los ojos.>\n\nNo por mucho tiempo.', 28153),
(162080, 'esMX', '', '¡Prometemos nuestras espadas a la Horda!', 28153),
(162079, 'esMX', '', 'Los Mag\'har formarán un nuevo hogar aquí en Azeroth.', 28153),
(162078, 'esMX', '', 'Puede que hayamos perdido Draenor pero mi corazón me dice que volveré a ver su cielo.\n\n¡Que los ancestros me cumplan este sueño!', 28153),
(162077, 'esMX', '¿Despellejamiento? Es una práctica salvaje y muy antigua. Ni siquiera sabría cómo comenzar un ritual semejante.\n\n<El orco se acerca y susurra.>\n\nSé exactamente cómo comenzar. ¿Quieres que te muestre?', '¿Despellejamiento? Es una práctica salvaje y muy antigua. Ni siquiera sabría cómo comenzar un ritual semejante.\n\n<La orco se acerca y susurra.>\n\nSé exactamente cómo comenzar. ¿Quieres que te muestre?', 28153),
(162076, 'esMX', 'A veces miro a los draenei y me pregunto si tendrán huesos en esos tentáculos carnosos que tienen en la cara, porque si tienen, coleccionaría muchos cientos y los ataría para armar guirnaldas que colgaría de los muros de nuestra fortaleza, así los visitantes se maravillarían y dirían \"Oye, mira todos esos huesos de tentáculos, apuesto a que los coleccionó un orco muy sabio y talentoso\", y yo les respondería que sí, que eso era lo que siempre me decía mi mamá.\n\nLo siento, ¿tenías una pregunta?', 'A veces miro a los draenei y me pregunto si tendrán huesos en esos tentáculos carnosos que tienen en la cara, porque si tienen, coleccionaría muchos cientos y los ataría para armar guirnaldas que colgaría de los muros de nuestra fortaleza, así los visitantes se maravillarían y dirían \"Oye, mira todos esos huesos de tentáculos, apuesto a que los coleccionó una orco muy sabia y talentosa\", y yo les respondería que sí, que eso era lo que siempre me decía mi mamá.\n\nLo siento, ¿tenías una pregunta?', 28153),
(162075, 'esMX', '¿Ya es hora de comer? ¡Espero que sea hora de comer!\n\nCambiando de tema... Si tuvieras que elegir, ¿qué preferirías? ¿Vivir sin un brazo o vivir sin una pierna?', '¿Ya es hora de comer? ¡Espero que sea hora de comer!\n\nCambiando de tema... Si tuvieras que elegir, ¿qué preferirías? ¿Vivir sin un brazo o vivir sin una pierna?', 28153),
(162074, 'esMX', '', '<Lasha te clava la mirada en la cabeza.>\n\n¿Cómo está tu cráneo? ¿Te cabe?\n\n¿Tienes la mente libre... vacía... o dividida?', 28153),
(162073, 'esMX', '', 'Extraño los botani.\n\nCuando los rostizabas bien, eran DELICIOSOS.\n\n<Lasha se limpia una gota de baba de los labios.>', 28153),
(162072, 'esMX', '', '¿Ya podemos prender fuego a los lazoluz?', 28153),
(162071, 'esMX', '$UBienvenido:Bienvenida; a mi posada, $Uviajero exhausto:viajera exhausta;. ¿En qué puedo ayudarte?', '$UBienvenido:Bienvenida; a mi posada, $Uviajero exhausto:viajera exhausta;. ¿En qué puedo ayudarte?', 28153),
(162070, 'esMX', 'Fija tu hogar en esta taberna.', 'Fija tu hogar en esta taberna.', 28153),
(162069, 'esMX', '¡Los que desafíen al jefe de guerra Grito Infernal pagarán con la vida!', '¡Los que desafíen al jefe de guerra Grito Infernal pagarán con la vida!', 28153),
(162068, 'esMX', 'Caminas sobre NUESTRO mundo, $uforastero:forastera;.\n\nSi traes la corrupción, perderás la vida.', 'Caminas sobre NUESTRO mundo, $uforastero:forastera;.\n\nSi traes la corrupción, perderás la vida.', 28153),
(162067, 'esMX', 'Si atrapo a alguno de esos traidores lazoluz, ¡lo degollaré!', 'Si atrapo a alguno de esos traidores lazoluz, ¡lo degollaré!', 28153),
(162066, 'esMX', 'Vencimos a los primigenios. Podemos derrotar a cualquier enemigo.', 'Vencimos a los primigenios. Podemos derrotar a cualquier enemigo.', 28153),
(162065, 'esMX', '¡Draenor será libre!', '¡Draenor será libre!', 28153),
(162064, 'esMX', 'Si te ganas la confianza de la señora suprema, te ganarás la mía.', 'Si te ganas la confianza de la señora suprema, te ganarás la mía.', 28153),
(162063, 'esMX', 'La señora suprema Geya\'rah es la mano derecha del jefe de guerra. No hay otra orco más valiente en todo Draenor.\n\n¡Ni en tu mundo, $uforastero:forastera;!', 'La señora suprema Geya\'rah es la mano derecha del jefe de guerra. No hay otra orco más valiente en todo Draenor.\n\n¡Ni en tu mundo, $uforastero:forastera;!', 28153),
(162062, 'esMX', '', 'Cuando era niña, los sabios draenei me enseñaron a leer y a escribir. Me caían bien. Los respetaba.\n\nPero luego llegaron los naaru y surgió el fanatismo por ellos.\n\nLos draenei renacieron... No, ellos usan una palabra diferente... Se reforjaron en su preciosa Luz.\n\nSus creencias los ciegan, los atan a amos que buscan controlar el universo como hizo la Legión.\n\nDraenei... eredar... tan dispuestos a doblegarse. Tan propensos a la corrupción.', 28153),
(162061, 'esMX', '', 'Grommash Grito Infernal ha sido un buen líder. Lo respeto tanto como a mi padre.\n\nPero si alguna vez vuelvo a ver al traidor de su hijo...\n\n<Geya\'rah escupe en el suelo.>\n\n... Lo liquidaré.', 28153),
(162060, 'esMX', '', 'Draenor debe ser libre de los fanáticos y los tiranos.', 28153),
(162059, 'esMX', 'Una vez, los héroes de tu mundo me libraron de las garras de un demonio en Ciudadela del Fuego Infernal. ¿Tú estabas entre ellos?\n\n<Grommash te observa.>\n\nSi es así, tengo una enorme deuda contigo. Quizás los espíritus me muestren cómo pagártela.', '', 28153),
(162058, 'esMX', 'Los Mag\'har no se inclinarán ante nadie. Ni siquiera ante los que consideramos amigos.', '', 28153),
(162057, 'esMX', 'Has recorrido un largo camino, $c. Quizás nuestro mundo te parezca aun mucho más salvaje de lo que era cuando tu pueblo lo conoció.', '', 28153),
(162047, 'esMX', '', '¿Qué recuerdos puedo manifestarte hoy?', 28153),
(162046, 'esMX', '¿Cómo puede ayudarte el viejo T\'omkus?', '', 28153),
(162045, 'esMX', 'Cuéntame sobre la batalla por Lordaeron.', 'Cuéntame sobre la batalla por Lordaeron.', 28153),
(162044, 'esMX', 'Cuéntame sobre el enfrentamiento en la sala del trono.', 'Cuéntame sobre el enfrentamiento en la sala del trono.', 28153),
(162043, 'esMX', 'Cuéntame sobre la traición de Valiente.', 'Cuéntame sobre la traición de Valiente.', 28153),
(162042, 'esMX', 'Cuéntame sobre las pruebas de Jaina.', 'Cuéntame sobre las pruebas de Jaina.', 28153),
(162041, 'esMX', 'Cuéntame sobre la pesadilla de Jaina.', 'Cuéntame sobre la pesadilla de Jaina.', 28153),
(162040, 'esMX', 'Cuéntame sobre el regreso de Jaina a Theramore.', 'Cuéntame sobre el regreso de Jaina a Theramore.', 28153),
(162039, 'esMX', 'Cuéntame sobre la batalla en la pirámide.', 'Cuéntame sobre la batalla en la pirámide.', 28153),
(162038, 'esMX', 'Cuéntame sobre la decisión de Rastakhan.', 'Cuéntame sobre la decisión de Rastakhan.', 28153),
(162037, 'esMX', 'Cuéntame sobre el regreso de Talanji a Zuldazar.', 'Cuéntame sobre el regreso de Talanji a Zuldazar.', 28153),
(162035, 'esMX', 'Esta no es manera de morir.', 'Esta no es manera de morir.', 28153),
(162034, 'esMX', 'Sentía cómo el frío me abrumaba...', 'Sentía cómo el frío me abrumaba...', 28153),
(162033, 'esMX', 'Te doy las gracias.', 'Te doy las gracias.', 28153),
(162032, 'esMX', 'Será mejor que esto no haya sido una trampa. Todavía necesitamos los servicios de $n.', '', 28153),
(162031, 'esMX', 'Estoy listo para irme de Límite del Destino.', 'Estoy lista para irme de Límite del Destino.', 28153),
(162030, 'esMX', 'Estoy listo para ir a Límite del Destino.', 'Estoy lista para ir a Límite del Destino.', 28153),
(162029, 'esMX', '¿Qué...? ¿Qué necesita Magni Barbabronce?', '', 28153),
(162025, 'esMX', '¿No te enteraste? La Horda tiene el cadáver de Derek Valiente en Puerto Saqueo. Lady Valiente envió a casi toda la armada a recuperarlo.', '¿No te enteraste? La Horda tiene el cadáver de Derek Valiente en Puerto Saqueo. Lady Valiente envió a casi toda la armada a recuperarlo.', 28153),
(162024, 'esMX', 'Hoy sí que está tranquilo. ¿Dónde están todos?', 'Hoy sí que está tranquilo. ¿Dónde están todos?', 28153),
(162023, 'esMX', '', 'Stone parece estar adaptándose bastante bien.\n\nCreo que con el tiempo se convertirá en una aliada leal.', 28153),
(162021, 'esMX', '', 'Fue... estimulante ver a todas esas personas recibir su merecido.\n\n¿Así se siente ser libre? ¿Poner tus propias reglas?\n\nQuizá pueda acostumbrarme a esto.', 28153),
(162020, 'esMX', '', 'Amalia parece estar llevándolo bastante bien. \n\nLo que está atravesando no es nada fácil, pero es más fuerte de lo que era yo cuando me convirtieron. Yo maté a casi todos los que me hicieron enfadar. Ella solo se ha aislado.\n\nCon el tiempo, cambiará. Confía en mí.', 28153),
(162019, 'esMX', '¡Se acercan! Háganlos llorar de dolor.', '', 28153),
(162018, 'esMX', 'Vamos, muchachos. ¡Que sufran!', '', 28153),
(162017, 'esMX', 'Flaquearás... ya llega... ya llega...', '', 28153),
(162016, 'esMX', '', 'Déjame sola. No quiero hablar contigo.', 28153),
(162015, 'esMX', 'El maestro tiene hambre... El Corazón alimentará su sueño lúcido...', '', 28153),
(162014, 'esMX', 'Los zandalari adoran a Bwonsamdi hace mucho tiempo, como los Lanza Negra.\n\nMira eh\'te ídolo de Bwonsamdi que traje al puerto. ¡Es fabuloso! Mejor que la mayoría de los que vi en mi hogar.\n\nLos Lanza Negra y los zandalari tienen muchas diferencias, es cierto, pero tenemos aún más en común.\n\nSi alguna vez los zandalari bajan un poco los humos, ¡creo que seremos amigos!', '¿Cuándo volveremos a cazar, $p?\n\nEn todos mis años en Azeroth, nunca ha habido escasez de monstruos.', 28153),
(162013, 'esMX', '', '¡No! Nuestro hogar...', 28153),
(162012, 'esMX', '', '¡No darás un paso más hacia nuestra casa, $r! ¡Tor ilisar\'thera\'nal!', 28153),
(162011, 'esMX', 'Demasiado tarde... tontos...', '', 28153),
(162010, 'esMX', 'Arrasaremos con lo que queda de esta pequeña aldea, ¡y nos desharemos de ti de una vez y para siempre!', '', 28153),
(162009, 'esMX', 'Me han dicho que los zandalari adoran a un loa pterrordáctilo.\n\nUn dios reptil... ¡que vuela!\n\n<A Lasan parecen brillarle los ojos.>\n\nAviash está listo para organizar una carrera con sus mejores jinetes. O mejor aún, ¡una pelea!\n\nA nosotros no nos importa. ¡Los derrotaremos como sea!\n\n¡Jajajajajajajajajaja!', '¿Cuándo volveremos a cazar, $p?\n\nEn todos mis años en Azeroth, nunca ha habido escasez de monstruos.', 28153),
(162008, 'esMX', 'Cuéntame tu plan, Nathanos.', 'Cuéntame tu plan, Nathanos.', 28153),
(162007, 'esMX', 'Muy bien. $n, dile a Velandrajo que estamos listos para partir.', '', 28153),
(162006, 'esMX', 'Y la Horda va a robarlo.', '', 28153),
(162005, 'esMX', 'Este artefacto está guardado bajo llave en el corazón de Boralus, la capital de Kul Tiras.', '', 28153),
(162004, 'esMX', 'Empuñar el cetro abisal es empuñar el mismísimo poder del mar y la tormenta.', '', 28153),
(162003, 'esMX', 'El cetro abisal.', '', 28153),
(162002, 'esMX', 'La Casa Canto Tormenta, mis antiguos hermanos maresabios, tienen un artefacto poderoso.', '', 28153),
(162001, 'esMX', 'Sí, Clamañublo.', '', 28153),
(162000, 'esMX', 'Zelling, ¿harías los honores?', '', 28153),
(161999, 'esMX', '¡Mira el tamaño de esos dinosaurios!\n\n<Ji suspira anhelante.>\n\n¡Qué ganas de pegarle a uno!', '¿Cuándo volveremos a cazar, $p?\n\nEn todos mis años en Azeroth, nunca ha habido escasez de monstruos.', 28153),
(161998, 'esMX', 'Costa Quebrada', 'Costa Quebrada', 28153),
(161997, 'esMX', 'Bóveda de Neltharion', 'Bóveda de Neltharion', 28153),
(161996, 'esMX', 'Meseta Elemental', 'Meseta Elemental', 28153),
(161995, 'esMX', 'Mirador de la Fundición de Roca Negra', 'Mirador de la Fundición de Roca Negra', 28153),
(161994, 'esMX', 'Cervecería del Trueno', 'Cervecería del Trueno', 28153),
(161993, 'esMX', 'Barrilia', 'Barrilia', 28153),
(161992, 'esMX', 'Peleé muchas guerras. Vi a héroes y cobardes desangrarse por igual en el campo de batalla.\n\nPero esta guerra es... diferente.\n\nPone a prueba nuestra entereza y habilidad. Pone a prueba nuestro corazón. Nuestra fe en nuestros compañeros.\n\nPase lo que pase, la Horda resistirá.\n\nNo hay otra opción.', '¿Cuándo volveremos a cazar, $p?\n\nEn todos mis años en Azeroth, nunca ha habido escasez de monstruos.', 28153),
(161991, 'esMX', 'Santuario de Dragones Rubí', 'Santuario de Dragones Rubí', 28153),
(161990, 'esMX', 'Campos del Torneo Argenta', 'Campos del Torneo Argenta', 28153),
(161989, 'esMX', 'Skald', 'Skald', 28153),
(161988, 'esMX', 'Fosas Viles', 'Fosas Viles', 28153),
(161987, 'esMX', 'Bastión del Honor', 'Bastión del Honor', 28153),
(161986, 'esMX', 'La Gran División', 'La Gran División', 28153),
(161985, 'esMX', 'Trono de la Llama', 'Trono de la Llama', 28153),
(161984, 'esMX', 'Cresta del Penacho en Llamas', 'Cresta del Penacho en Llamas', 28153),
(161983, 'esMX', 'El Masón', 'El Masón', 28153),
(161982, 'esMX', 'Pico Nidal', 'Pico Nidal', 28153),
(161981, 'esMX', 'Castillo de Nethergarde', 'Castillo de Nethergarde', 28153),
(161980, 'esMX', 'Ventormenta', 'Ventormenta', 28153),
(161979, 'esMX', 'Forjaz', 'Forjaz', 28153),
(161978, 'esMX', 'Zandalar', 'Zandalar', 28153),
(161977, 'esMX', 'Kul Tiras', 'Kul Tiras', 28153),
(161976, 'esMX', 'Islas Quebradas', 'Islas Quebradas', 28153),
(161975, 'esMX', 'Rasganorte', 'Rasganorte', 28153),
(161974, 'esMX', 'Pandaria', 'Pandaria', 28153),
(161973, 'esMX', 'Draenor', 'Draenor', 28153),
(161972, 'esMX', 'Terrallende', 'Terrallende', 28153),
(161971, 'esMX', 'Kalimdor', 'Kalimdor', 28153),
(161970, 'esMX', 'Reinos del Este', 'Reinos del Este', 28153),
(161969, 'esMX', 'Si vale la pena tenerlo, vale la pena encerrarlo en una caja.\n\n¡A menos que hablemos de una persona! No se puede poner a $p en una caja, ¿no?\n\n<Hobart se queda pensativo por un momento.>\n\nDe todos modos, estoy haciendo algunos ajustes. Tendré el traje en funcionamiento en poco tiempo... ¡con algunas mejoras explosivas!', '¿Cuándo volveremos a cazar, $p?\n\nEn todos mis años en Azeroth, nunca ha habido escasez de monstruos.', 28153),
(161968, 'esMX', 'No moriré en esta colina, George.', '', 28153),
(161967, 'esMX', '¡Pelea con Jeph, prepárate para la muerte!', '', 28153),
(161966, 'esMX', 'Se llevaron a tu hija a Límite del Destino.', 'Se llevaron a tu hija a Límite del Destino.', 28153),
(161965, 'esMX', '¡Excelente! ¡Le dimos su merecido!', '', 28153),
(161964, 'esMX', '¿Un desierto? Qué... pintoresco.', '', 28153),
(161963, 'esMX', 'Estoy aquí como pediste, Aterravermis.', '', 28153),
(161962, 'esMX', 'Aquí vamos...', '', 28153),
(161961, 'esMX', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡Intercepta el |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r para volver a lanzarlo al aire!', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡Intercepta el |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r para volver a lanzarlo al aire!', 28153),
(161960, 'esMX', '¡Fuego!', '¡Fuego!', 28153),
(161959, 'esMX', '¡Muy bien! ¡Cuando quieras!', '', 28153),
(161958, 'esMX', '¡Contén a esa cosa mientras preparo el cañón para disparar!', '', 28153),
(161957, 'esMX', '|cFF0000FF(Misión)|r Estoy listo para ir a Draenor.', '|cFF0000FF(Misión)|r Estoy lista para ir a Draenor.', 28153),
(161956, 'esMX', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t ¡%s te marca con |cFFFF0000|Hspell:259720|h[Levantamiento]|h|r!', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t ¡%s te marca con |cFFFF0000|Hspell:259720|h[Levantamiento]|h|r!', 28153),
(161955, 'esMX', 'Mira, ¡tengo la última llave!', 'Mira, ¡tengo la última llave!', 28153),
(161954, 'esMX', 'Estoy listo para buscar el Eco de Garrosh.', 'Estoy lista para buscar el Eco de Garrosh.', 28153),
(161953, 'esMX', 'No te estaría ayudando en esta misión si no creyera que es importante.', '', 28153),
(161952, 'esMX', '¡Basta de parlotear! No hace falta que todos se enteren.', 'Tendríamos que habernos ido ayer.', 28153),
(161950, 'esMX', '¡Esto no es lo que esperaba de este día!', '', 28153),
(161949, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t ¡El Aporreador masivo a monedas lanza |cFFFF0000|Hspell:256214|h[Lanzador de bombalones]|h|r!', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t ¡El Aporreador masivo a monedas lanza |cFFFF0000|Hspell:256214|h[Lanzador de bombalones]|h|r!', 28153),
(161948, 'esMX', 'Tu fragmento es cada vez más poderoso, $p.', '', 28153),
(161947, 'esMX', 'Aún se siente el hedor de mis hermanos. Ocúpate de este rápido.', '', 28153),
(161946, 'esMX', 'Nuestra misión está completa, $p. Tu jefe telemante Oculeth espera tu llegada en Zuldazar.', '', 28153),
(161945, 'esMX', '', 'Siempre y cuando cumplas con tu parte del trato, mugroso.', 28153),
(161944, 'esMX', 'Muy bien, ¡cincuenta! Me parece justo. Sin rencores, ¿no?', '', 28153),
(161943, 'esMX', '', 'Digamos cincuenta. A menos que prefieras que te saque el cincuenta por ciento de los dientes.', 28153),
(161942, 'esMX', 'Te propongo un trato, ¿qué tal si te doy una parte de las ganancias en plata y tú bajas ese pico? ¿Veinte por ciento?', '', 28153),
(161941, 'esMX', '¿De veras? Creo que lo recordaría...', '', 28153),
(161940, 'esMX', '', '¡Porque te gritamos mientras te ibas con nuestros únicos guardias!', 28153),
(161939, 'esMX', 'Eh, ¡tranquila! ¿Cómo podía saber que había sobrevivientes?', '', 28153),
(161938, 'esMX', '', '¡Cobarde! Nos abandonaste y no te importó dejarnos morir.', 28153),
(161937, 'esMX', '¡Califica mi próxima pasada!', '¡Califica mi próxima pasada!', 28153),
(161936, 'esMX', '¡Espero que estés $Ulisto:lista; para montar!', '', 28153),
(161935, 'esMX', '', 'Si no te importa, iré a buscar a Cochambro. Mi pico tiene un par de cosas que decirle...', 28153),
(161934, 'esMX', '', 'Gracias de nuevo por tu ayuda, $Uforastero:forastera;.', 28153),
(161933, 'esMX', 'Misiones de mundo desbloqueadas', '', 28153),
(161932, 'esMX', '¡Trataron de vender estas cosas como comida!', 'Sella esos cajones. ¡Tenemos que limpiar este desastre!', 28153),
(161931, 'esMX', 'Batalla por Stromgarde desbloqueada', '', 28153),
(161930, 'esMX', '¡Odio a esos niños!', '¡Deshazte de esas cosas!', 28153),
(161929, 'esMX', '¡Esos niños horribles trajeron estas cosas al pueblo!', 'Esta es otra de las ideas de esos niños, ¡otra que salió mal!', 28153),
(161928, 'esMX', '|TInterface\\ICONS\\INV_Misc_Bell_Green:20|t ¡Raal el Glotón comienza a lanzar |cFFFF0404|Hspell:264931|h[Llamar sirviente]|h|r!', '', 28153),
(161927, 'esMX', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t ¡Lady Tarjasenda comienza a lanzar |cFFFF0404|Hspell:268306|h[Cadencia discordante]|h|r!', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t ¡Lady Tarjasenda comienza a lanzar |cFFFF0404|Hspell:268306|h[Cadencia discordante]|h|r!', 28153),
(161926, 'esMX', '¡Lo lograste! Azeroth está más fuerte... ¡y tú también, $ucampeón:campeona;!', '', 28153),
(161925, 'esMX', '¡Un esbirro de los dioses antiguos! El Corazón de Azeroth ya tiene la fuerza necesaria para expulsarlo. ¡Usa el Corazón, $n!', '', 28153),
(161924, 'esMX', 'Islas desbloqueadas', '', 28153),
(161923, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Festín de sangre]|h|r para purgar tus acumulaciones de |cFFFF0404|Hspell:263227|h[Sangre pútrida]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Festín de sangre]|h|r para purgar tus acumulaciones de |cFFFF0404|Hspell:263227|h[Sangre pútrida]|h|r.', 28153),
(161922, 'esMX', 'Elévate sobre la tormenta. Que se mojen los demás.', '', 28153),
(161921, 'esMX', '', '¡Lo logramos! Regresemos a Ventormenta para hablar con el rey.', 28153),
(161920, 'esMX', '', 'Decidimos hacer algunas mejoras cuando reparamos el Yunquenegro.', 28153),
(161919, 'esMX', '', 'Seguiré cazando al enemigo hasta que hayamos ganado esta guerra, $n.\n\nEsa es mi promesa para todos los caídos en Teldrassil.\n\n<Shandris baja la cabeza para rezar.>', 28153),
(161918, 'esMX', '', 'Monta las corrientes. ¡Doma la tormenta!', 28153),
(161917, 'esMX', 'Volver a la Puerta de Sangre.', 'Volver a la Puerta de Sangre.', 28153),
(161916, 'esMX', 'En líneas generales, no puedo decir que sea fanático de los botes, pero admiro lo que tienes guardado aquí.\n\nSi encuentras alguna reliquia más que valga la pena ver, estaré encantado de echar un vistazo.\n\nY puertas. Puertas misteriosas. ¡Las puertas titánicas misteriosas son mi especialidad!', '', 28153),
(161915, 'esMX', '', 'Halford tiene unas notas muy interesantes aquí. Informes de guerra, movimientos de tropas...\n\n<Kelsey mira la puerta y se acerca para susurrarte.>\n\n¡Y hasta puede que haya encontrado su diario personal!\n\n<Kelsey te guiña un ojo cómplice.>', 28153),
(161914, 'esMX', '', 'No quieres irte sin tus amigos, ¿o sí?', 28153),
(161913, 'esMX', 'Es bueno estar peleando otra vez con soldados honestos y fornidos de la Alianza. Me recuerda a mis épocas en la Compañía Bravo.\n\n<Los ojos de Keeshan parecen mirar a un lugar muy lejano.>\n\nTen siempre lista el arma, $n. Y escóndete otra en caso de que te capturen. En algún lugar donde nadie quiera buscarla.', '', 28153),
(161912, 'esMX', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t ¡Rixxa Llamaflujo está lanzando |cFFFF0000|Hspell:259940|h[Ráfaga propelente]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t ¡Rixxa Llamaflujo está lanzando |cFFFF0000|Hspell:259940|h[Ráfaga propelente]|h|r!', 28153),
(161911, 'esMX', 'Mi pueblo ha estado entrenando. Mejorando sus habilidades.\n\n<Umbric entrecierra los ojos.>\n\nLos susurros hablan de muchas posibilidades. Estaremos preparados para lo que sea.', '', 28153),
(161910, 'esMX', 'Sí. Todo este arreglo no me convencía, pero parece que al final todo fue para mejor.', '', 28153),
(161909, 'esMX', '¡Es un buen día para ser Hierro Negro!', '', 28153),
(161908, 'esMX', '', 'El último golpe es tuyo, $p.', 28153),
(161907, 'esMX', '', 'Me alegra que estemos en guerra nuevamente, $n. Pero debo reconocerlo... me estoy cansando de sanar a los heridos. Hay muchas mejores formas de utilizar mis talentos.\n\nMuchas de las técnicas que los Templeluz usamos contra la Legión serían útiles para pelear contra la Horda.\n\nInforma al alto comandante que con gusto me aseguraré de que los prisioneros que capturemos sean adecuadamente... \"purificados\".', 28153),
(161906, 'esMX', '', 'No me sorprende que Jaina Valiente haya decidido volver a casa.\n\nUna herida que no se trata no puede sanar. Y ella tiene una herida muy grande.', 28153),
(161905, 'esMX', '¡El guardián del corazón se mueve para atacarte!', '¡El guardián del corazón se mueve para atacarte!', 28153),
(161904, 'esMX', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerektha está a punto de golpearte con |cFFFF0000|Hspell:263914|h[Arena cegadora]|h|r, ¡mira para otro lado!', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerektha está a punto de golpearte con |cFFFF0000|Hspell:263914|h[Arena cegadora]|h|r, ¡mira para otro lado!', 28153),
(161903, 'esMX', '', 'Estoy lista cuando digas, $n. Ven a buscarme cuando quieras ir a Profundidades de Roca Negra.', 28153),
(161902, 'esMX', '', 'Ya sabes lo que tenemos que hacer, $n. Hora de irnos.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161901, 'esMX', '|cFF0000FF(Misión)|r Estoy listo para ir a las Tierras de Fuego.', '|cFF0000FF(Misión)|r Estoy lista para ir a las Tierras de Fuego.', 28153),
(161900, 'esMX', '', 'Ven, $n. Vamos a acabar con ella.', 28153),
(161899, 'esMX', 'No nos estarán esperando aquí en Vol\'Dun, pero pronto empezarán a preguntarse quién está matando a sus operativos.', '', 28153),
(161898, 'esMX', 'Tenemos que actuar rápido, $n. La Horda todavía no sabe que aterrizamos.', '', 28153),
(161897, 'esMX', 'Plantará esas bombas y lo tendremos aquí de nuevo con nosotros en cuestión de segundos.', '', 28153),
(161896, 'esMX', 'Puede que no parezca, pero sabe manejarse en la batalla. Y su experiencia en demoliciones no tiene igual.', '', 28153),
(161895, 'esMX', 'No te preocupes. Ya trabajé con Guzbert. Es un profesional.', '', 28153),
(161894, 'esMX', 'Con ayuda de la Luz, le pondremos fin a eso.', '', 28153),
(161893, 'esMX', 'Lo que no pueden usar, lo venden. Y eso financia los gastos de guerra de la Horda.', '', 28153),
(161892, 'esMX', 'Pero sería un error. Se sabe que esas sabandijas desentierran artefactos poderosos y los usan contra sus enemigos.', '', 28153),
(161891, 'esMX', 'Es tentador pasar por alto al Vigía del Sol y el Relicario. Vamos... después de todo son arqueólogos.', '', 28153),
(161890, 'esMX', '|cFF0000FF(Misión)|r Estoy listo para ir a Profundidades de Roca Negra.', '|cFF0000FF(Misión)|r Estoy lista para ir a Profundidades de Roca Negra.', 28153),
(161889, 'esMX', '', 'En este momento es demasiado peligroso viajar por Arathi.$B$BEl acceso al portal se restablecerá cuando hayamos recuperado el control de Stromgarde.', 28153),
(161888, 'esMX', '¿Qué sabemos acerca de orcos mag\'har?', '¿Qué sabemos acerca de orcos mag\'har?', 28153),
(161887, 'esMX', '¿Qué sabes acerca de los enanos Hierro Negro?', '¿Qué sabes acerca de los enanos Hierro Negro?', 28153),
(161886, 'esMX', 'Cuando crezca, ¡quiero ser como Nisha! ¡Es la mejor!\n\n¡O como Kiro! Es súper inteligente...\n\n¡O como Meerah! Es tan buena...\n\n¡O como Jena! Tiene un montón de cosas...\n\nO como...\n\n<Rudo sigue nombrando otros vulperas del campamento.>', '', 28153),
(161885, 'esMX', '', 'En este momento es demasiado peligroso viajar por Arathi.$B$BEl acceso al portal se restablecerá cuando hayamos recuperado el control de Ar\'gorok.', 28153),
(161884, 'esMX', '', '¿Quieres una bebida refrescante?', 28153),
(161883, 'esMX', '¡Tengo los mejores tratos! ¡No puedes ganar sin estos artículos!', '', 28153),
(161882, 'esMX', 'Hola, $Uamigo:amiga;. Tengo muchas cosas buenas aquí.', 'Oh,¡espero que te gusten mis inventos!', 28153),
(161881, 'esMX', '¿Buscas armas y armaduras recién forjadas? ¡Estás en el lugar indicado!', '', 28153),
(161880, 'esMX', '', '¡Tengo suministros de Ventormenta para ti!', 28153),
(161879, 'esMX', 'Traigo instrumentos de oscuridad.', '', 28153),
(161878, 'esMX', 'Tengo artefactos mágicos que tal vez sean de tu interés.', 'Tengo muchas cosas buenas aquí y no hago preguntas.', 28153),
(161877, 'esMX', '¡Cervezas en oferta!', 'Tengo muchas cosas buenas aquí y no hago preguntas.', 28153),
(161876, 'esMX', 'Los Mag\'har están contigo, ¡sangre y truenos!', 'Tengo muchas cosas buenas aquí y no hago preguntas.', 28153),
(161875, 'esMX', '¿Buscan explosivos? Tengo lo que necesitan aquí mismo.', 'Tengo muchas cosas buenas aquí y no hago preguntas.', 28153),
(161874, 'esMX', '¡Lok\'tar! Tengo suministros de Orgrimmar.', 'Tengo muchas cosas buenas aquí y no hago preguntas.', 28153),
(161873, 'esMX', '¡Tengo bienes para comerciar! ¡Te traerán mucha suerte!', '¡Tengo bienes para comerciar! ¡Te traerán mucha suerte!', 28153),
(161872, 'esMX', 'Se dice que Elisande dominaba encantamientos que solo conocen los dragones de bronce. Quizá estén dispuestos a ayudarte.', '', 28153),
(161871, 'esMX', 'La magia temporal era la especialidad de nuestra líder anterior, la Gran Magistrix Elisande. Gran parte de su conocimiento murió con ella.', '', 28153),
(161870, 'esMX', 'Tengo que infiltrarme en la Academia Valiente.', 'Tengo que infiltrarme en la Academia Valiente.', 28153),
(161869, 'esMX', 'Tengo que infiltrarme en el Cuartel Valiente.', 'Tengo que infiltrarme en el Cuartel Valiente.', 28153),
(161868, 'esMX', '', '¡Por la Alianza!', 28153),
(161867, 'esMX', 'Resistiremos. Tú avanza. ¡Por la Alianza!', '', 28153),
(161866, 'esMX', 'Estamos entre la espada y la pared, ante un océano repleto de naves enemigas que no nos permiten movernos.', '', 28153),
(161865, 'esMX', 'Me temo que debo coincidir con el gnomo, $p.', '', 28153),
(161864, 'esMX', '', '¡Ey!', 28153),
(161863, 'esMX', '%s se apresura a volver a Ranastanque.', '%s se apresura a volver a Ranastanque.', 28153),
(161862, 'esMX', 'Con este hablaré. Por lo menos todavía tiene lengua, no como esos Renegados apestosos.', '', 28153),
(161861, 'esMX', '', '¡Vamos, $p! ¡Habla con el capitán así podemos irnos!', 28153),
(161860, 'esMX', '', 'A veces me gustaría SER una máquina...', 28153),
(161859, 'esMX', '', 'Máquinas... <suspiro>', 28153),
(161858, 'esMX', 'Ya tienes tus órdenes. ¡Retírate!', '', 28153),
(161857, 'esMX', 'Evalúa estos campamentos y vuelve a informarnos lo que descubras.', '', 28153),
(161856, 'esMX', '', '¡Ooh! ¡Enanos Hierro Negro! ¡Me encantan los enanos Hierro Negro! Tienen MÁQUINAS.', 28153),
(161855, 'esMX', 'Te encontrarás con el señor feudal del yunque Thurgaden en la costa sureste de Zuldazar.', '', 28153),
(161854, 'esMX', '', '¡Sí, señor!', 28153),
(161853, 'esMX', '¡Kelsey!', '', 28153),
(161852, 'esMX', 'Su tripulación tuvo algunos problemas en alta mar, pero se las ingeniaron para improvisar un campamento en las orillas orientales.', '', 28153),
(161851, 'esMX', 'Encuéntrense con el brigadier Thom, uno de nuestros oficiales de la Séptima Legión.', '', 28153),
(161850, 'esMX', '¡$p!', '', 28153),
(161849, 'esMX', '', 'Mucha comida fresca dentro.', 28153),
(161848, 'esMX', 'Ya tenemos los pies sobre no UNA, sino DOS ubicaciones en Zuldazar.', '', 28153),
(161847, 'esMX', 'Vengan, todos. Este es el plan.', '', 28153),
(161846, 'esMX', 'Terminarás... en la prisión Valiente...', '', 28153),
(161845, 'esMX', '', 'Escoria... de la Horda...', 28153),
(161844, 'esMX', 'Recuperaremos el cuerpo de Derek... de un modo u otro...', '', 28153),
(161843, 'esMX', '', 'Nunca podrán manejar el poder de nuestras enseñanzas...', 28153),
(161842, 'esMX', 'Las mareas se los llevarán...', '', 28153),
(161841, 'esMX', 'Ve. Regresa con Oculeth. Con el fragmento recompuesto, podrá enviarte al lugar que buscas.', '', 28153),
(161840, 'esMX', 'Si hubiera tenido alguna duda, no habría permitido que el fragmento cayera en las manos equivocadas. No de nuevo.', '', 28153),
(161839, 'esMX', 'Los hilos del destino se ciernen sobre ti. Eres $Udigno:digna; de lo que está por venir.', '', 28153),
(161838, 'esMX', 'Incluso como reverberación del pasado, Garrosh fue un enemigo formidable.', '', 28153),
(161837, 'esMX', 'Lo que has visto aquí es una de sus peores encarnaciones posibles. Un desperdicio.', '', 28153),
(161836, 'esMX', 'En múltiples líneas temporales, su pueblo lo alaba como un gran héroe. Algunos incluso lo consideraron el mejor jefe de guerra de la Horda.', '', 28153),
(161835, 'esMX', 'Garrosh Grito Infernal... Es una pena cómo resultaron las cosas.', '', 28153),
(161834, 'esMX', '¿Cree\' que tú me da\' miedo?', '', 28153),
(161833, 'esMX', 'Cuéntanos todo, zandalari.', 'Cuéntanos todo, zandalari.', 28153),
(161832, 'esMX', 'Te contaré mi historia\n\nYo eh\'taba en la nave insignia.\n\nBien. Eh\'to es lo que pasó. Mejor que lo sepan. Mejor que sientan el miedo.', '', 28153),
(161831, 'esMX', 'Ven, ahora debemos viajar al Templo del Tigre Blanco.', '', 28153),
(161830, 'esMX', 'Nadie extrañará a Gul\'dan... ni en esta ni en ninguna otra línea temporal.', '', 28153),
(161829, 'esMX', 'Aunque esto es un mero eco de este enemigo de Azeroth, tienes que saber que la muerte a manos de esta entidad será muy real.', '', 28153),
(161828, 'esMX', 'Fue aquí que Gul\'dan una vez viajó entre mundos con la ayuda de la Visión en el tiempo.', '', 28153),
(161827, 'esMX', 'Los ecos de magia que hay aquí retumban en los portales del tiempo.', '', 28153),
(161826, 'esMX', 'Incluso ahora, puedo... Espera, ¿qué es eso?', '', 28153),
(161825, 'esMX', 'Dentro de esta cámara, ¡el Corazón de Azeroth puede fortalecerse mucho más!', '', 28153),
(161824, 'esMX', 'La Cámara del Corazón está mucho mejor que la última vez que estuviste aquí, ¿no?', '', 28153),
(161823, 'esMX', 'Pero no podemos entregarnos al desánimo. ¡Sé que puedes revertir esta marea de oscuridad!', '', 28153),
(161822, 'esMX', 'Me temo que todavía nos queda mucho por hacer, $n. Las cosas allí afuera parecen estar empeorando.', '', 28153),
(161821, 'esMX', '¿Lo sientes? ¡El poder del Corazón sigue aumentando!', '', 28153),
(161820, 'esMX', '¡Al diablo contigo! Escucha mis palabras... Al Señor del fuego le llegará su momento. Y ese día nos veremos... viejo amigo.', '', 28153),
(161819, 'esMX', 'Ah, sí... me gusta el olor del fuego por la mañana... y al mediodía, y la noche. Tenemos que internarnos en la guarida del Señor del fuego para cargar ese Núcleo de Magma.', '', 28153),
(161818, 'esMX', 'Enviaré a nuestros mejores exploradores a buscar a Pedrasiniestra. Tenemos que detener a ese maldito demente antes de que les lave el cerebro a más seguidores.', '', 28153),
(161817, 'esMX', '¿Estas $useguro:segura; de que quieres omitir las misiones introductorias de Kul Tiras?', '¿Estas $useguro:segura; de que quieres omitir las misiones introductorias de Kul Tiras?', 28153),
(161816, 'esMX', 'Eso ya lo he oído antes... <Omitir las misiones introductorias de Kul Tiras y empezar tu viaje por Boralus.>', 'Eso ya lo he oído antes... <Omitir las misiones introductorias de Kul Tiras y empezar tu viaje por Boralus.>', 28153),
(161815, 'esMX', 'Usa su poder con sabiduría, $n. Y ten cuidado... hay quienes quieren que fracases en la tarea de salvar a nuestro mundo.', '', 28153),
(161814, 'esMX', 'A medida que recupera fuerzas, ¡también se fortalece el Corazón de Azeroth que llevas en el cuello!', '', 28153),
(161813, 'esMX', 'Azeroth todavía está dolorida, pero gracias a los esfuerzos de todos ya puede mantenerse en pie.', '', 28153),
(161812, 'esMX', 'Muy bien. Levantemos este puente. Creo que conozco el hechizo indicado...', '', 28153),
(161811, 'esMX', '¡Con eso debería bastar! Salgamos de aquí.', '', 28153),
(161810, 'esMX', 'Pero primero lo primero. Tenemos que cargar ese Núcleo de Magma para poder arreglar el Yunquenegro.', '', 28153),
(161809, 'esMX', 'Traigo terribles noticias, $p. Pedrasiniestra y sus fanáticos están trabajando para traer de vuelta a Ragnaros... Pensé que ya había aprendido.', '', 28153),
(161808, 'esMX', 'Muéstrame los sucesos que trajeron a la Alianza a Silithus.', 'Muéstrame los sucesos que trajeron a la Alianza a Silithus.', 28153),
(161807, 'esMX', 'Muéstrame los sucesos que trajeron a la Horda a Silithus.', 'Muéstrame los sucesos que trajeron a la Horda a Silithus.', 28153),
(161806, 'esMX', 'Que no paren de venir.', '', 28153),
(161805, 'esMX', '¡Todavía tengo sed!', '', 28153),
(161804, 'esMX', '¡Una más!', '', 28153),
(161803, 'esMX', '¡Otra!', '', 28153),
(161802, 'esMX', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t ¡Hadal crea una |cFFFF0000|Hspell:276068|h[Fuerza del oleaje]|h|r!', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t ¡Hadal crea una |cFFFF0000|Hspell:276068|h[Fuerza del oleaje]|h|r!', 28153),
(161801, 'esMX', 'Muy bien. Entonces no tenemos nada más que hablar.', '', 28153),
(161800, 'esMX', '¡Por supuesto!', '', 28153),
(161799, 'esMX', 'Cuando el verdadero Señor del fuego vuelva a levantarse, todos los Hierro Negro fieles responderán su llamado. ¿Piensas oponerte a nosotros?', '', 28153),
(161798, 'esMX', '¿Y crees que esa pobre banda de ascuas que reuniste lo impresionará? Creo que la mayoría de tus cultistas andrajosos se extinguió de camino aquí.', '', 28153),
(161797, 'esMX', 'A Thaurissan no le faltaba visión, pero fue tonto de su parte tratar de controlar al Señor del fuego. Nosotros debemos ser sus sirvientes.', '', 28153),
(161796, 'esMX', '¡¿Ragnaros?! ¿Quieres traer de vuelta al tirano? Cuando el señor feudal hechicero lo intentó...', '', 28153),
(161795, 'esMX', '¿Líder legítima? No corre fuego por las venas de Moira. Nuestro líder legítimo es el verdadero señor de las llamas, no una mocosa Barbabronce... ni un aspirante al trono.', '', 28153),
(161794, 'esMX', 'Muy bien. Debería ser más cuidadoso, mi lord. Blasfema contra nuestra líder legítima.', '', 28153),
(161793, 'esMX', '¡Muestra un poco de respeto! Usa mi título cuando te dirijas a mí.', '', 28153),
(161792, 'esMX', 'Deberías ser más cuidadoso, Harrold. Es peligroso hablar así.', '', 28153),
(161791, 'esMX', 'Todo a su tiempo, señor feudal del yunque. Sabes tan bien como yo que la reina regente es frágil. Débil.', '', 28153),
(161790, 'esMX', 'Pedrasiniestra... Por todos los núcleos, ¿qué está pasando aquí? ¿Dónde está Fulguron?', '', 28153),
(161789, 'esMX', '¡Ho-hola, colega!', '', 28153),
(161788, 'esMX', '¡HA LLEGADO EL SEÑOR FEUDAL DEL YUNQUE THURGADEN! ¡AVISEN AL ALTO JUSTICIERO PEDRASINIESTRA!', '¡HA LLEGADO EL SEÑOR FEUDAL DEL YUNQUE THURGADEN! ¡AVISEN AL ALTO JUSTICIERO PEDRASINIESTRA!', 28153),
(161786, 'esMX', 'Basta de balbuceos. ¡Habla de una vez, muchacho!', '', 28153),
(161785, 'esMX', 'Eh... Bueno, verá...', 'Eh... Bueno, verá...', 28153),
(161784, 'esMX', '¿Quién ordenó que se cerrara el puente? ¿Quién está a cargo aquí?', '', 28153),
(161783, 'esMX', '¡¿Señor feudal del yunque?!', '¡¿Señor feudal del yunque?!', 28153),
(161782, 'esMX', '¿Qué significa esto?', '', 28153),
(161781, 'esMX', '¡Saluda a mi amiguito!', '', 28153),
(161780, 'esMX', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 28153),
(161779, 'esMX', '<No queda claro cómo fue el fin de este mercader, pero ya hace tiempo que está a merced de los cuervos.>', '', 28153),
(161774, 'esMX', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t ¡El kraken despierta un |cFFFF0000|Hspell:279897|h[Terror de las profundidades]|h|r!', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t ¡El kraken despierta un |cFFFF0000|Hspell:279897|h[Terror de las profundidades]|h|r!', 28153),
(161773, 'esMX', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t ¡El tiburón huele |cFFFF0000|Hspell:279893|h[Sangre en el agua]|h|r!', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t ¡El tiburón huele |cFFFF0000|Hspell:279893|h[Sangre en el agua]|h|r!', 28153),
(161772, 'esMX', 'Él te admiraba por eso, y yo también.', '', 28153),
(161771, 'esMX', 'Supongo que era demasiado esperar que perdonaran a Jaina. Su destino incierto me preocupa, pero debemos concentrarnos en la misión.\n\nTenemos que asegurar la incorporación de Kul Tiras a la Alianza. Si Katherine Valiente no quiere escucharnos, estos simpatizantes son nuestra esperanza.', '', 28153),
(161770, 'esMX', 'Hrkk...', '', 28153),
(161769, 'esMX', '¿La Alianza? ¿Está aquí?', '', 28153),
(161768, 'esMX', '', 'Mi vida por la arqueología...', 28153),
(161767, 'esMX', '', '¡Manténganlos alejados de la excavación!', 28153),
(161766, 'esMX', 'El Relicario me vengará...', '', 28153),
(161765, 'esMX', '', 'Tengo que avisar... a Vigía del Sol...', 28153),
(161764, 'esMX', '', '¡Ey! ¡Este es territorio Horda! ¡No debes estar aquí!', 28153),
(161763, 'esMX', '¡Siga peleando, $ujefe:jefa;! Yo... esperaré aquí.', '', 28153),
(161762, 'esMX', '¡Haremos a la Horda victoriosa!', '¡Haremos a la Horda victoriosa!', 28153),
(161761, 'esMX', 'Te veré en el campo de batalla.', 'Te veré en el campo de batalla.', 28153),
(161760, 'esMX', '¿$UListo:Lista; para partir?', '¿$UListo:Lista; para partir?', 28153),
(161759, 'esMX', 'Nuestros enemigos se acobardarán cuando nos vean.', 'Nuestros enemigos se acobardarán cuando nos vean.', 28153),
(161758, 'esMX', '¡La batalla espera!', '¡La batalla espera!', 28153),
(161757, 'esMX', 'Las raíces de este conflicto son muy profundas.', 'Las raíces de este conflicto son muy profundas.', 28153),
(161756, 'esMX', '¿Me llevarás en tus ramas, anciano?', '¿Me llevarás en tus ramas, anciano?', 28153),
(161755, 'esMX', 'Cada vez que veo a la Horda se me hace un nudo en la garganta.', 'Cada vez que veo a la Horda se me hace un nudo en la garganta.', 28153),
(161754, 'esMX', 'Ciudadanos de Boralus, ¡fijen sus ojos en las mareas y observen!', '', 28153),
(161753, 'esMX', 'Mis Martillo Salvaje harán que la Horda se entretenga con esa nave mientras nosotros hacemos blanco en Dreven en la otra nave.', '', 28153),
(161752, 'esMX', 'Estoy listo para volver a Boralus.', 'Estoy lista para volver a Boralus.', 28153),
(161751, 'esMX', '', 'La cacería ha terminado. El mundo es más seguro.\n\nHoy es un buen día.', 28153),
(161750, 'esMX', '¡A la batalla!', '¡A la batalla!', 28153),
(161749, 'esMX', 'Yo te sigo.', 'Yo te sigo.', 28153),
(161748, 'esMX', '¡Muy bien, $Umuchachito:muchachita;! Ahora manos a la obra.', '¡Muy bien, $Umuchachito:muchachita;! Ahora manos a la obra.', 28153),
(161747, 'esMX', 'Lucharé a tu lado.', 'Lucharé a tu lado.', 28153),
(161746, 'esMX', 'Estoy en deuda contigo, $n.', 'Estoy en deuda contigo, $n.', 28153),
(161745, 'esMX', '¡Ohhh, guau! ¡Muchas gracias, $p!', '', 28153),
(161744, 'esMX', '¿Darle a Ancel Mildenhall la carta de Rosalinda?', '¿Darle a Ancel Mildenhall la carta de Rosalinda?', 28153),
(161743, 'esMX', '¡Tenemos un ataque de troggs entre manos! Súbete a Arión y dales su merecido a los troggs.', '', 28153),
(161742, 'esMX', '¡Hasta pronto!', '¡Hasta pronto!', 28153),
(161741, 'esMX', '', 'Los extraño mucho y espero regresar a casa pronto. Estoy segura de que Raimond está haciendo lo mejor que puede, pero el pobre tiene un verdadero talento para generar caos en cualquier lugar.', 28153),
(161740, 'esMX', 'Eso te mantendrá $Uabrigado:abrigada;.', '', 28153),
(161739, 'esMX', 'Esta ropa servirá.', '', 28153),
(161738, 'esMX', 'Quizás esa ropa te ayude con tus tareas.', '', 28153),
(161737, 'esMX', 'Luces bien, $n.', '', 28153),
(161736, 'esMX', '¡Lanzo Descarga de escarcha en la oscuridad!', '¡Lanzo Descarga de escarcha en la oscuridad!', 28153),
(161735, 'esMX', 'Gracias, ¡prometo que la entregaré a tiempo!', 'Gracias, ¡prometo que la entregaré a tiempo!', 28153),
(161734, 'esMX', '¡No tires cerveza en mi ficha de personaje!', '¡No tires cerveza en mi ficha de personaje!', 28153),
(161733, 'esMX', 'Yo me llevaré la vela.', 'Yo me llevaré la vela.', 28153),
(161732, 'esMX', '¿Mmm?', '', 28153),
(161731, 'esMX', 'Sería más fácil curarte si no te pararas en el fuego todo el tiempo.', 'Sería más fácil curarte si no te pararas en el fuego todo el tiempo.', 28153),
(161730, 'esMX', 'Yo... eeeh... bueno, la perdí. ¿Me darías otra copia?', 'Yo... eeeh... bueno, la perdí. ¿Me darías una copia?', 28153),
(161729, 'esMX', '¿El guardia ve que estoy saqueando este cadáver?', '¿El guardia ve que estoy saqueando este cadáver?', 28153),
(161728, 'esMX', '¡Deja de contradecir a tu asignador de misiones!', '¡Deja de contradecir a tu asignadora de misiones!', 28153),
(161727, 'esMX', 'No, el árbol no es vulnerable a ataques con fuego.', 'No, el árbol no es vulnerable a ataques con fuego.', 28153),
(161726, 'esMX', 'Ya te lo dije: ¡bardo no es una clase!', 'Ya te lo dije: ¡bardo no es una clase!', 28153),
(161725, 'esMX', '', 'Hola, $p. No esperaba verte tan pronto. ¿Cómo reaccionó Ancel a mi carta?', 28153),
(161724, 'esMX', '', 'Santo cielo, $p... Sinceramente, espero que perder cosas no sea un hábito para ti. Espera un momento... escribiré otra.', 28153),
(161723, 'esMX', '¿Darle a Rosalina el amuleto de miel templada?', '¿Darle a Rosalina Mildenhall el amuleto de miel templada?', 28153),
(161722, 'esMX', '', 'Ah... otro día, otra muerte.', 28153),
(161721, 'esMX', '', 'Espera... ¿¡Dices que has conocido a Ancel y Raimond!?', 28153),
(161720, 'esMX', 'Bueno... es una larga historia pero estaba dentro de una abominación viviente hecha de miel. Lo encontré mientras ayudaba a Ancel y Raimond a limpiar la granja.', 'Bueno... es una larga historia pero estaba dentro de una abominación viviente hecha de miel. Lo encontré mientras ayudaba a Ancel y Raimond a limpiar la granja.', 28153),
(161719, 'esMX', 'Encontré este amuleto, ¿es tuyo?', 'Encontré este amuleto, ¿es tuyo?', 28153),
(161718, 'esMX', '', '¿Cómo puedo ayudarte, $Uamigo:amiga;? ¿Tienes instrumentos arcanos que necesitas identificar?', 28153),
(161717, 'esMX', 'Estamos casi listos para reparar el Yunquenegro. Ahora solo necesitamos cargar el Núcleo con la esencia de Ragnaros.', '', 28153),
(161716, 'esMX', '|cFF0000FF(Misión)|r Estoy listo para ir al Núcleo de Magma.', '|cFF0000FF(Misión)|r Estoy lista para ir al Núcleo de Magma.', 28153),
(161715, 'esMX', 'Es una belleza, ¿no? Salgamos de aquí. Con la máquina topo regresaremos a Ventormenta sanos y salvos.', '', 28153),
(161714, 'esMX', 'Lo mismo digo, hermano engendro.', '', 28153),
(161713, 'esMX', '¡Nunca fuiste nuestro igual!', '', 28153),
(161712, 'esMX', 'No sé de quién estaría más decepcionado.', '', 28153),
(161711, 'esMX', '¿Qué pensaría nuestro padrespora si viera en lo que nos hemos convertido?', '', 28153),
(161710, 'esMX', 'Ya lo veremos, hermano engendro.', '', 28153),
(161709, 'esMX', 'Nunca lograrás nada.', '', 28153),
(161708, 'esMX', 'Parece que tendremos que terminar la travesía a pie.', '', 28153),
(161707, 'esMX', 'Bien, lo que pasó, pasó. Por suerte tengo más de repuesto.', '', 28153),
(161706, 'esMX', '¡IZQUIERDA! ¡DERECHA! IZ... ¡LAVA!', '', 28153),
(161705, 'esMX', '¡Agh! Nunca podrá quitar la arena de esta vestimenta.', '', 28153),
(161704, 'esMX', '¡Auch! ¡Ten cuidado!', '', 28153),
(161703, 'esMX', 'Falta un poco más para completar el cargamento, luego podremos irnos de esta costa devastada... y dejar este olor... bien lejos.', '', 28153),
(161702, 'esMX', 'Como sea, con mi tanque todo será un poco más sencillo. Trata de no rayarlo, yo prepararé algunas cosas.', '', 28153),
(161701, 'esMX', 'Por no decir que probablemente tendremos que lidiar con el viejo Gezzrok si queremos obtener un pedazo del Núcleo.', '', 28153),
(161700, 'esMX', '¿Es posible que no trabajen al ritmo de una tortuga?', '', 28153),
(161699, 'esMX', 'El único problema es que nos encontraremos con un puñado de bestiecillas feroces en el camino hacia la vieja guarida de Ragnaros.', '', 28153),
(161698, 'esMX', 'Muy bien, $n. Tal vez pienses que será cuestión de arrebatar y correr, y estás casi en lo cierto.', '', 28153),
(161697, 'esMX', 'Si tu tripulación puede elevarse un poco más arriba de la mediocridad, quedaré impresionado.', '', 28153),
(161696, 'esMX', 'Recomiendo que te concentres en la tarea más inmediata.', '', 28153),
(161695, 'esMX', 'Para ser franco, la postura política de tu... líder... no me interesa a mí ni a mis representados.', '', 28153),
(161694, 'esMX', 'Sí, sí... te escucho.', '', 28153),
(161693, 'esMX', '¡Nadie quiere ver eso!', '', 28153),
(161692, 'esMX', 'Ey, bacanes, si seguimos perdiendo integrantes de la tripulación y nuestro equipo sigue rompiéndose, llevarán la azerita sobre sus flacuchas patas de elfo.', '', 28153),
(161691, 'esMX', 'Sí, no le importa.', '', 28153),
(161690, 'esMX', 'Bueno, muchacha, sí. Es cierto. Lo siento, $n.', '', 28153),
(161689, 'esMX', '', 'Sabemos que tienes una reserva de menas casi infinita en la Cámara Negra.', 28153),
(161688, 'esMX', '', 'No seas avaro, Thaelin. A $n le esperan tareas importantes.', 28153),
(161687, 'esMX', 'El Yunquenegro está hecho exclusivamente con el hierro negro más puro fundido y refinado con secretos que no puedo revelar a nadie más que a nuestros mineros y herreros de mayor confianza.', '', 28153),
(161686, 'esMX', '¡Necesitaremos toneladas de hierro negro para reparar esta cosa!', '', 28153),
(161685, 'esMX', '', 'Es evidente que Volrath está detrás de los movimientos de la Horda en Kul Tiras.\n\nPrimero Ashran, luego esa condenada isla lejos de Feralas y ahora aquí... es como un resfrío que no se va.', 28153),
(161684, 'esMX', 'Supongo que los duelos pueden ser una buena forma de afilar tus habilidades de combate.\n\n¿Mi opinión? No hay mejor muñeco de práctica que un miembro de la Alianza.', 'Supongo que los duelos pueden ser una buena forma de afilar tus habilidades de combate.\n\n¿Mi opinión? No hay mejor muñeco de práctica que un miembro de la Alianza.', 28153),
(161683, 'esMX', 'Ven a verme a bordo del Lamento del Alma en Pena, en el Puerto de Zandalar.', '', 28153),
(161682, 'esMX', '¡Vuelva a la formación, soldado!', '¡Vuelva a la formación, soldado!', 28153),
(161681, 'esMX', 'Nuestro siguiente escuadrón de refuerzos se prepara para zarpar.', 'Nuestro siguiente escuadrón de refuerzos se prepara para zarpar.', 28153),
(161680, 'esMX', 'Responde al llamado de la batalla.', 'Responde al llamado de la batalla.', 28153),
(161679, 'esMX', 'Para esto hemos estado entrenando.', 'Para esto hemos estado entrenando.', 28153),
(161678, 'esMX', 'La batalla espera.', 'La batalla espera.', 28153),
(161677, 'esMX', 'Muy bien, $n. Toma un trozo de ese Núcleo para que podamos volver a las cuevas superiores. Prepararé una máquina topo.', '', 28153),
(161676, 'esMX', 'A $uun:una; $c como tú le iría bien en nuestras filas.', 'A $uun:una; $c como tú le iría bien en nuestras filas.', 28153),
(161675, 'esMX', 'Prepárate para la batalla.', 'Prepárate para la batalla.', 28153),
(161674, 'esMX', '¡De acuerdo!', '', 28153),
(161673, 'esMX', 'Sí, ya lo creo. Si me derrotas, podrás volver con un fragmento del Núcleo.', '', 28153),
(161672, 'esMX', 'Necesitamos una pieza del Núcleo de Magma para reparar el Yunquenegro.', '', 28153),
(161671, 'esMX', '¿Y qué buscas, criatura del fuego?', '', 28153),
(161670, 'esMX', 'Thaelin Yunqueoscuro del clan Hierro Negro.', '', 28153),
(161669, 'esMX', '¿Quién anda ahí?', '', 28153),
(161668, 'esMX', 'Muy bien. Te has ganado una pieza del Núcleo de Magma. Úsala bien.', '', 28153),
(161667, 'esMX', 'Hojatemblorosa piensa que puede superarnos con su banda de tontos de la Alianza.\n\nSu arrogancia será su fin.', '', 28153),
(161666, 'esMX', '', 'No le digas a nadie, pero me alegra un poco que haya menos halcones últimamente.\n\nNo tengo nada en contra de las aves, pero siento un poco de apego por estas criaturas peludas. \n\nSi no hay halcones, mis conejos podrán estar mucho más... vivos.', 28153),
(161665, 'esMX', '¡Por la Alianza!', 'Y por los caídos... Elune-adore.', 28153),
(161664, 'esMX', '¡Ah, Falstad! Estás aquí.', '', 28153),
(161663, 'esMX', '¡Abandona este lugar!', '¡Abandona este lugar!', 28153),
(161662, 'esMX', '¡No destruirán estas tierras!', '¡No destruirán estas tierras!', 28153),
(161661, 'esMX', 'Los eh\'píritus... me dan la bienvenida...', 'Los eh\'píritus... me dan la bienvenida...', 28153),
(161660, 'esMX', 'No nos matarán... a todo\'...', 'No nos matarán... a todo\'...', 28153),
(161659, 'esMX', 'Me uno a los espíritu\'...', 'Me uno a los espíritu\'...', 28153),
(161658, 'esMX', 'Eh\'to no estaba... en mis visione\'...', 'Eh\'to no estaba... en mis visione\'...', 28153),
(161657, 'esMX', 'La Horda... prevalece...', 'La Horda... prevalece...', 28153),
(161656, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(161655, 'esMX', '¡No te mueva\'!', '¡No te mueva\'!', 28153),
(161654, 'esMX', '¡Eh\'to no te va a guh\'tar nada!', '¡Eh\'to no te va a guh\'tar nada!', 28153),
(161653, 'esMX', 'No pueden detenernos...', 'No pueden detenernos...', 28153),
(161652, 'esMX', '', 'Ven a verme a mis recámaras en Entrañas, donde podremos discutir nuestro próximo movimiento... con discreción.', 28153),
(161651, 'esMX', '¿Whisky? Nunca fue lo mío.\n\nNo, vine aquí solo por los pretzels.', '', 28153),
(161650, 'esMX', 'Gracias, magíster. Su aporte será muy valorado.', '', 28153),
(161649, 'esMX', 'Con gusto contaré todo lo que recuerde y que sirva para ayudarlos.', '', 28153),
(161648, 'esMX', 'Hay un solo Gallywix verdadero, y lo encontraremos. Informaré a Shaw sobre los señuelos.', '', 28153),
(161647, 'esMX', '', 'Como si Azeroth no tuviera suficiente con un solo Gallywix, ahora tenemos... ¿Cuántos crees, Halford? ¿Decenas?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161645, 'esMX', '¡Que alguien se ocupe de $uese:esa; $pr! ¡Y que alguien me traiga manteca de cacao al balcón!', '', 28153),
(161644, 'esMX', '¡Estoy listo para partir!', '¡Estoy lista para partir!', 28153),
(161643, 'esMX', '¡Me alegra que lo hayas logrado, $n! Avísame cuando estés $ulisto:lista; para ver a Ulfar y yo te llevaré con él.', '', 28153),
(161642, 'esMX', 'No comprendo las fiestas goblins. En absoluto.', '', 28153),
(161641, 'esMX', 'Nunca volvamos a hablar de este lugar.', '', 28153),
(161640, 'esMX', 'Semejante glotonería y derroche de recursos... mientras otros goblins se mueren de hambre.', '', 28153),
(161639, 'esMX', 'Agh, ¿qué es ese olor asqueroso?', '', 28153),
(161638, 'esMX', 'Nunca necesite una ducha tanto como en este momento.', '', 28153),
(161637, 'esMX', 'No pondría ni el meñique en esa piscina sucia. Quién sabe qué cosas han estado haciendo allí.', '', 28153),
(161636, 'esMX', 'Desde luego, tiran la basura al agua. Son tan vulgares.', '', 28153),
(161635, 'esMX', 'Una agradable parcela de la naturaleza... arruinada por franjas de pasto artificial de mal gusto.', '', 28153),
(161634, 'esMX', 'Tu cuerpo se va poniendo pesado a medida que tus pulmones se llenan de humo..', 'Tu cuerpo se va poniendo pesado a medida que tus pulmones se llenan de humo..', 28153),
(161633, 'esMX', '', 'Qué... alivio... haberte encontrado...', 28153),
(161632, 'esMX', '', 'Adalid... ¿adalid? ¿Me oyes?', 28153),
(161631, 'esMX', '¡Las llamas se apaciguaron! ¡Ve al Templo de la Luna!', '¡Las llamas se apaciguaron! ¡Ve al Templo de la Luna!', 28153),
(161630, 'esMX', '¡Ishala! ¡Ishala! ¿Estás ahí? Por favor, Ishala, ¡oye mi voz!', '¡Ishala! ¡Ishala! ¿Estás ahí? Por favor, Ishala, ¡oye mi voz!', 28153),
(161629, 'esMX', '¡No me iré sin mi hija! ¡Ayuda, por favor!', '¡No me iré sin mi hija! ¡Ayuda, por favor!', 28153),
(161628, 'esMX', '¡Por favor! ¡Alguien ayúdeme! ¡Encuentren a mi familia!', '¡Por favor! ¡Alguien ayúdeme! ¡Encuentren a mi familia!', 28153),
(161627, 'esMX', '¡Por favor! ¡Ayúdame! ¡No encuentro a mi hija!', '¡Por favor! ¡Ayúdame! ¡No encuentro a mi hija!', 28153),
(161626, 'esMX', 'Aprovéchala. Tráela de vuelta a casa.', '', 28153),
(161625, 'esMX', 'Te han concedido otra oportunidad.', '', 28153),
(161624, 'esMX', 'Daría lo que sea por volver a abrazar a mi hijo.', '', 28153),
(161623, 'esMX', 'Si la oyes... es porque todavía no es tarde.', '', 28153),
(161622, 'esMX', '', 'Es demasiado tarde.', 28153),
(161621, 'esMX', 'Katherine, te está llamando... Debes acudir a ella.', '', 28153),
(161620, 'esMX', '', 'Genn... la veo entre las llamas.', 28153),
(161619, 'esMX', '', '...La veo... en mis sueños...', 28153),
(161618, 'esMX', '...Y ahora sufre todavía más. ¿No crees?', '', 28153),
(161617, 'esMX', 'Jaina no hizo más que seguir su corazón. Y ha sufrido por eso.', '', 28153),
(161616, 'esMX', '', 'Jaina traicionó al reino.', 28153),
(161615, 'esMX', 'Tienes a Jaina.', '', 28153),
(161614, 'esMX', '', 'Ya no tengo nada... no me queda... nadie.', 28153),
(161613, 'esMX', '', 'Priscilla, la amiga más cercana a mi corazón... me ha traicionado.', 28153),
(161612, 'esMX', '', 'No sé qué hacer, Daelin. Ya no sé qué creer... en quién confiar.', 28153),
(161611, 'esMX', 'Contra ella. Contra los kultiranos. Contra toda la Alianza, si es necesario.\n\nAmo a la Horda. Le prometí a Thrall que la defendería.\n\nSea quien sea que haya comenzado esta guerra, lucharé hasta su fin... o hasta el mío.', '', 28153),
(161610, 'esMX', 'No podemos perder Darnassus... ¡No puede terminar así!', 'No podemos perder Darnassus... ¡No puede terminar así!', 28153),
(161609, 'esMX', 'Maldita sea la Horda. ¡Malditos todos ellos!', 'Maldita sea la Horda. ¡Malditos todos ellos!', 28153),
(161608, 'esMX', 'No... entiendo...', 'No... entiendo...', 28153),
(161607, 'esMX', '¡Gracias! Espero que los demás hayan logrado escapar.', '¡Gracias! Espero que los demás hayan logrado escapar.', 28153),
(161606, 'esMX', '¿Pelearás contra Jaina Valiente?', '¿Pelearás contra Jaina Valiente?', 28153),
(161605, 'esMX', 'Jaina Valiente.\n\nUna vez tomó la decisión de librarnos de la tiranía de su padre. Respeté su decisión, lo difícil que fue\n\nPero ella no pudo perdonar lo que Grito Infernal le hizo a Theramore. Volcó su odio contra toda la Horda.\n\nFue muy lejos. Asesinó a demasiados. Hay que poner fin a su deseo de venganza.', '', 28153),
(161604, 'esMX', 'Gracias... Pensé que no viviría para contarla.', 'Gracias... Pensé que no viviría para contarla.', 28153),
(161603, 'esMX', 'Todo se quema... todo...', 'Todo se quema... todo...', 28153),
(161602, 'esMX', 'Que Elune te bendiga...', 'Que Elune te bendiga...', 28153),
(161601, 'esMX', 'Bendita sea Elune por ti, $n.', 'Bendita sea Elune por ti, $n.', 28153),
(161600, 'esMX', '¡Envíame a Boralus!', '¡Envíame a Boralus!', 28153),
(161599, 'esMX', '', 'Saludos, $c. ¿Quieres regresar a Boralus?', 28153),
(161598, 'esMX', '', 'Saludos, $c. ¿Te diriges al frente?', 28153),
(161597, 'esMX', '¿\"Ella\"? ¿Qué quieres decir?', '¿\"Ella\"? ¿Qué quieres decir?', 28153),
(161596, 'esMX', 'No puedo... respirar...', 'No puedo... respirar...', 28153),
(161595, 'esMX', 'Había fundado una hermandad con otros cazadores de la Senda Oculta. Luchamos para defender una tierra quebrada.\n\nPero el cuerno de guerra ha vuelto a sonar.\n\nCuando escuché que ella había regresado... tuve que responder la llamada.', '', 28153),
(161594, 'esMX', '¿Qué te trae a este conflicto, Rexxar?', '¿Qué te trae a este conflicto, Rexxar?', 28153),
(161593, 'esMX', '¡Ayuda por favor!', '¡Ayuda por favor!', 28153),
(161592, 'esMX', '¡Apáguenlo! ¡Alguien apáguelo!', '¡Apáguenlo! ¡Alguien apáguelo!', 28153),
(161591, 'esMX', 'Parece que tenemos otra guerra que luchar.\n\nNo hay tiempo de charlar.', '', 28153),
(161590, 'esMX', 'Hace tanto... calor...', 'Hace tanto... calor...', 28153),
(161589, 'esMX', '¿Por qué ocurre todo esto?', '¿Por qué ocurre todo esto?', 28153),
(161588, 'esMX', '¡¡AAAHHH!!', '¡¡AAAHHH!!', 28153),
(161587, 'esMX', '¡Agua! ¡Por favor! ¡Por favor!', '¡Agua! ¡Por favor! ¡Por favor!', 28153),
(161586, 'esMX', '¡Elune, sálvanos!', '¡Elune, sálvanos!', 28153),
(161585, 'esMX', 'Sí, tengo que concentrarme. La tarea que me encomendaron. Complacer al Clamañublo. Mantenerlos a salvo.\n\nTengo que seguir trabajando, $n.', '', 28153),
(161584, 'esMX', '¡Concéntrate, hermano Zelling!', '¡Concéntrate, hermano Zelling!', 28153),
(161583, 'esMX', '¡Es que lo son TODO para mí!\n\nMe di cuenta de que... de que ya no me quieren más en sus vidas. ¡Pero eso podría cambiar!\n\nCuando se den cuenta de que soy yo, de que todavía los amo, estoy seguro de que... Creo que...\n\nYo... no...', '', 28153),
(161582, 'esMX', 'Aún piensas en ellos.', 'Aún piensas en ellos.', 28153),
(161581, 'esMX', 'No estoy seguro si... Creo que todavía no...\n\nNo es fácil, $n.\n\nLa señorita Voss me pidió que me concentrara en la misión que se me ha encomendado. Me dijo que la mejor manera de mantener a salvo mi familia es demostrarle al Clamañublo de lo que soy capaz.\n\nMi familia...', '', 28153),
(161580, 'esMX', '¿Cómo ha sido tu transición, Zelling?', '¿Cómo ha sido tu transición, Zelling?', 28153),
(161579, 'esMX', 'Haré todo lo que está a mi alcance para impulsar la causa de los Renegados.', '', 28153),
(161578, 'esMX', '¡Envíame a Zuldazar!', '¡Envíame a Zuldazar!', 28153),
(161577, 'esMX', '', 'Throm-ka, $c. ¿Quieres regresar a Zuldazar?', 28153),
(161576, 'esMX', '', 'En vida, me criaron para odiar a los no-muertos. Me entrenaron para destruirlos.\n\nCuando me convertí en Renegada, me odié a mí misma más que a nadie.\n\nPero ahora veo que la Alianza es el catalizador de toda esta malicia. Los reinos humanos evitan a sus antiguos hermanos y hermanas porque nosotros les recordamos lo que mora debajo de la fachada de carne con la que se cubren.\n\nEs hora de ponerle fin a su ciclo de odio. La Alianza merece caer.', 28153),
(161575, 'esMX', '', '¡La oscuridad no puede permanecer en la Luz!', 28153),
(161574, 'esMX', 'Ese vudú e\' peligroso.', '', 28153),
(161573, 'esMX', 'Esto está bien.', 'Esto está bien.', 28153),
(161572, 'esMX', '¡Nada detendrá a la Horda!', '', 28153),
(161571, 'esMX', '¿Y qué hay de la Alianza?', '¿Y qué hay de la Alianza?', 28153),
(161570, 'esMX', '', 'No hace falta ser un profeta para darse cuenta de que Sylvanas usará esta guerra como medio para traer más Renegados a este mundo.\n\nMi conversión fue... difícil. Tuve que atravesar muchas cosas. Tuve que saldar muchas cuentas.\n\nTodavía no me olvido de todo eso. Pero también siento la obligación de ayudar a los recién resucitados a adaptarse a la situación. Quizá pueda ahorrarles todo el dolor que yo tuve que atravesar.', 28153),
(161569, 'esMX', 'Pero sí, desde luego.', 'Pero sí, desde luego.', 28153),
(161568, 'esMX', 'Tenemos todo bajo control. Relájate y disfruta tu cerveza.', 'Tenemos todo bajo control. Relájate y disfruta tu cerveza.', 28153),
(161567, 'esMX', 'Te lo agradezco, mi amigo de higiene dudosa, pero avanzamos más rápido solos.', 'Te lo agradezco, mi amigo de higiene dudosa, pero avanzamos más rápido solos.', 28153),
(161566, 'esMX', '¿Necesitan ayuda con la misión, elfitos queridos? ¡Los Hierro Negro se ocuparán!', '¿Necesitan ayuda con la misión, elfitos queridos? ¡Los Hierro Negro se ocuparán!', 28153),
(161565, 'esMX', '¿De qué tipo de oportunidad hablas?', '¿De qué tipo de oportunidad hablas?', 28153),
(161564, 'esMX', '', 'Parece que a las autoridades les llamaron la atención mis poderes. Solicitaron mis \"servicios\"...\n\n¿Detectaste el significado oculto de lo que acabo de decir? Lo siento. A pesar de mi profesión, la sutileza no se me da muy bien.\n\nNo importa. Lo cierto es que reconozco una oportunidad cuando se me presenta.', 28153),
(161563, 'esMX', 'Parece que te has aliado con la Horda.', 'Parece que te has aliado con la Horda.', 28153),
(161562, 'esMX', 'Halford, comencemos el proceso para hacer estallar esta nave.', 'Halford, comencemos el proceso para hacer estallar esta nave.', 28153),
(161561, 'esMX', '¿Te llevo a algún lado?', '', 28153),
(161560, 'esMX', '¿Te llevo a algún lado?', '', 28153),
(161559, 'esMX', 'El capitán Brewston dijo que me podías mostrar un poco el área.', 'El capitán Brewston dijo que me podías mostrar un poco el área.', 28153),
(161558, 'esMX', 'Gracias.', 'Gracias.', 28153),
(161557, 'esMX', 'Wistel dijo que me podías mostrar un poco el área.', 'Wistel dijo que me podías mostrar un poco el área.', 28153),
(161556, 'esMX', 'Gracias.', 'Gracias.', 28153),
(161555, 'esMX', 'Bien, ya es suficiente. Acabemos con ella.', '', 28153),
(161554, 'esMX', 'Allí delante está Alto Pedestal, ¿y más allá? Eso es Ar\'gorok, $gmuchacho:muchacha;. El enemigo. El lugar que tenemos que conquistar.', '', 28153),
(161553, 'esMX', '¿Al este? Allí está Granovel. Granjas y tierras de pastoreo. Nada del otro mundo.', '', 28153),
(161552, 'esMX', 'Al este está el Círculo de Elementos. Tienen tótems de piedra grandes, elementales de fuego enormes y círculos titánicos en el cuelo. A los chamanes les encantan.', '', 28153),
(161551, 'esMX', 'No te preocupes, no iremos lejos. Quiero señalar algunos de los lugares en los que nos hemos enfrentado a la Horda. En caso de que necesitemos que... ya sabes... los mates.', '', 28153),
(161550, 'esMX', 'Te doy la bienvenida a Aserradero de Tierras Altas, fuente de toda la madera de Stromgarde. Bueno, al menos este es el sitio donde HABITUALMENTE obtenemos madera. Desde el último ataque de la Horda, nos hemos visto obligados a huir, y parece que la naturaleza se ha apoderado de nuestro molino.\n\nPero no es para preocuparse. Cuando traigamos a algunos lacayos, el molino volverá a trabajar en menos de lo que canta un gallo.', '', 28153),
(161549, 'esMX', 'Te doy la bienvenida a Aserradero de Tierras Altas, fuente de toda la madera de Stromgarde.\n\nLos bosques han estado muy tranquilos hoy. Uno de los aldeanos tuvo un altercado con un oso, pero eso es bastante común por estos lares. Ya sabes cómo son los aldeanos...', '', 28153),
(161548, 'esMX', '', '$n, ¿cierto? Tully.\n\n<La capataz Tully extiende una mano callosa.>\n\nEsto es Filón de Galson. Normalmente, aquí verías a mis obreros recolectando mena para financiar la guerra, pero desde el último ataque de la Horda, no hemos tenido más remedio que irnos.\n\nDile a Brewston que nos vendría bien un poco de apoyo militar por esta zona. Estamos listos para empezar a trabajar, pero no podremos entrar a esa mina sin antes luchar.', 28153),
(161547, 'esMX', '', '$n, ¿cierto? Tully.\n\n<La capataz Tully extiende una mano callosa.>\n\nNo hay nada para informar sobre este sitio. La Horda sigue siendo una piedra en el zapato, y los kóbolds no dejan de... molestarnos, pero de ellos podemos encargarnos sin problemas.', 28153),
(161546, 'esMX', 'Bien, ya es suficiente. Acabemos con ella.', '', 28153),
(161545, 'esMX', 'Allí delante está Alto Pedestal, ¿y más allá? Eso es Stromgarde, $gmuchacho:muchacha;. El enemigo. El lugar que tenemos que conquistar.', '', 28153),
(161544, 'esMX', '¿Al este? Allí está Granovel. Granjas y tierras de pastoreo. Nada del otro mundo.', '', 28153),
(161543, 'esMX', 'Al este está el Círculo de Elementos. Tienen tótems de piedra grandes, elementales de fuego enormes y círculos titánicos en el suelo. A los chamanes les encantan.', '', 28153),
(161542, 'esMX', 'No te preocupes, no iremos lejos. Quiero señalar algunos de los lugares en los que nos hemos enfrentado a la Alianza. En caso de que necesitemos que... ya sabes... los mates.', '', 28153),
(161541, 'esMX', 'Te doy la bienvenida a Cresta Hachazo, fuente de toda la madera de Ar\'gorok. Bueno, al menos este es el sitio donde HABITUALMENTE obtenemos madera. Desde el último ataque de la Alianza, nos hemos visto obligados a huir, y parece que la naturaleza se ha apoderado de nuestro molino.\n\nPero no es para preocuparse. Cuando traigamos a algunos brutos, el molino volverá a trabajar en menos de lo que canta un gallo.', '', 28153),
(161540, 'esMX', 'Te doy la bienvenida a Cresta Hachazo, fuente de toda la madera de Ar\'gorok.\n\nLos bosques han estado muy tranquilos hoy. Uno de los peones tuvo un altercado con un oso, pero eso es bastante común por estos lares. Ya sabes cómo son los peones...', '', 28153),
(161539, 'esMX', '$n, ¿cierto? Drogg.\n\n<Drogg extiende una mano callosa.>\n\nEsta es la mina Mostacho Seco. Normalmente, aquí verías a mis peones recolectando mena para financiar la guerra, pero desde el último ataque de la Alianza, no hemos tenido más remedio que irnos.\n\nDile a Wistel que nos vendría bien un poco de apoyo militar por esta zona. Estamos listos para empezar a trabajar, pero no podremos entrar a esa mina sin antes luchar.', '', 28153),
(161538, 'esMX', '', '$n, ¿cierto? Drogg.\n\n<Drogg extiende una mano callosa.>\n\nNo hay nada para informar sobre este sitio. La Alianza sigue siendo una piedra en el zapato, y los kóbolds no dejan de... molestarnos, pero de ellos podemos encargarnos sin problemas.', 28153),
(161537, 'esMX', 'Mientras Lunargenta esté del lado de la Horda, siempre habrá quienes desconfíen de nosotros.\n\nPero la Alianza es el lugar al que pertenece nuestro pueblo. Tengo más certeza que nunca.\n\nSigue tu camino, $n. Demuéstrales a nuestros camaradas de la Alianza que luchamos por la misma causa.\n\nUn día, la Horda dejará de aferrar nuestra tierra y los hijos de Quel\'Thalas volverán a unirse.\n\nLo sé.', '', 28153),
(161536, 'esMX', '¿Crees que nos hemos ganado la confianza de la Alianza?', '¿Crees que nos hemos ganado la confianza de la Alianza?', 28153),
(161535, 'esMX', 'Lucho para apresar los susurros, al igual que tú. Por suerte, Alleria Brisaveloz sigue guiándonos.\n\nSin su intervención... Bueno, me temo que habríamos estado perdidos.\n\nY aunque al principio no quería tratar con él, he aprendido mucho del Caminante intersticial. Pero ten en cuenta que todo lo que ofrece de alguna manera sirve a sus propios objetivos.', '', 28153),
(161534, 'esMX', '¿Cómo has estado, magíster Umbric?', '¿Cómo has estado, magíster Umbric?', 28153),
(161533, 'esMX', 'No estamos del lado de la Alianza por conveniencia. Tampoco como gesto de agradecimiento a Alleria.\n\nNuestro martirio nos enseñó la importancia de que los grandes poderes estén en manos correctas. No podemos permitir que la Horda sepa las cosas que sabemos, ni que las use como armas para conseguir lo que quieren.\n\nLuchamos por la Alianza porque creemos en sus valores. Y rezo porque algún día toda Lunargenta también se nos una.', '', 28153),
(161532, 'esMX', 'Ahora luchas por la Alianza.', 'Ahora luchas por la Alianza.', 28153),
(161531, 'esMX', 'Nos llevé directamente a una trampa de etéreos. Si no hubiese sido por Alleria Brisaveloz, habríamos estado perdidos.\n\nEn cambio, la energía de las sombras nos transformaron... y nos abrieron la mente a los susurros del Vacío. Sin la guía de Alleria, habríamos sucumbido ante la locura.\n\nElla nos ayudó a tranquilizar nuestras mentes. A calmar los susurros. Es una lucha constante.', '', 28153),
(161530, 'esMX', '¿Estuviste cerca de ceder al Vacío?', '¿Estuviste cerca de ceder al Vacío?', 28153),
(161529, 'esMX', 'Mis seguidores y yo no sentíamos lealtad hacia la Horda. Cuando el gran magíster Rommath prohibió nuestra investigación del Vacío, no dudamos en separarnos e iniciar nuestro camino.\n\nPero la soberbia me jugó una mala pasada. Pensé que podía dominar cualquier fuerza que encontráramos.\n\nEstaba tan equivocado...', '', 28153),
(161528, 'esMX', '¿Y decidiste acudir al poder de la sombra?', '¿Y decidiste acudir al poder de la sombra?', 28153),
(161527, 'esMX', 'Como magíster, me debo a Lunargenta y a su pueblo. Cuando el demente de Arthas destruyó nuestra tierra, supe que teníamos que aprovechar todo el poder que pudiéramos para sobrevivir.\n\nEl príncipe Kael\'thas propuso una manera. Yo busqué otra.', '', 28153),
(161526, 'esMX', '¿Cuál es su papel en esta campaña, magíster?', '¿Cuál es su papel en esta campaña, magíster?', 28153),
(161525, 'esMX', '', '$n, ¿vamos?', 28153),
(161524, 'esMX', '¿Ya regresaste?', '', 28153),
(161523, 'esMX', 'He perdido la flauta.', 'He perdido la flauta.', 28153),
(161521, 'esMX', 'Impresionante. Gracias, magíster.', '', 28153),
(161520, 'esMX', 'Viajaré contigo en esta nave para aprovechar el tiempo y planear nuestra estrategia.', '', 28153),
(161519, 'esMX', 'Nos estarán esperando en la costa cuando lleguemos, con un informe de exploración detallado de toda el área.', '', 28153),
(161518, 'esMX', 'Gracias, magíster Umbric. ¿Cuánto tiempo tardarán en llegar hasta allí?', '', 28153),
(161517, 'esMX', 'Alto comandante, he quedado con un regimiento de mis mejores exploradores y asesinos para que nos encontremos en Xibala.', '', 28153),
(161516, 'esMX', '', 'Tenemos público... ¡perfecto! Quieto, $Usiervo:sierva; de la Alianza. ¡Mira cómo destruyo a uno de tus grandes héroes!', 28153),
(161515, 'esMX', '¡Envíame a Tierras Altas de Arathi!', '¡Envíame a Tierras Altas de Arathi!', 28153),
(161514, 'esMX', '', 'Throm-ka, $c. ¿Te diriges al frente?', 28153),
(161513, 'esMX', '', '¡Hola! Este lugar es impresionante, ¿no? Nunca puedo elegir cuál es mi bar preferido, pero este sin duda está entre los diez mejores. Sencillo.', 28153),
(161512, 'esMX', 'Ningún navío se compara con el nuestro. Ninguno.', 'Ningún navío se compara con el nuestro. Ninguno.', 28153),
(161511, 'esMX', 'Alabada sea la Madre de las mareas.', 'Alabada sea la Madre de las mareas.', 28153),
(161510, 'esMX', 'Escucha a las profundidades. Solo ellas nos mostrarán la verdad.', 'Escucha a las profundidades. Solo ellas nos mostrarán la verdad.', 28153),
(161509, 'esMX', '', 'Ah, ey, otro artefacto drust. Tendría que llevárselo a Jane.', 28153),
(161508, 'esMX', 'Que las corrientes te guíen.', 'Que las corrientes te guíen.', 28153),
(161507, 'esMX', '', 'Mmm, mi pico de minería se está aflojando. Tendría que pedirle a Grix que lo mire.', 28153),
(161506, 'esMX', '', 'Me está dando hambre. Tendría que ir con Alan a lo de Byron.', 28153),
(161505, 'esMX', '', 'Por mucho que me cueste admitirlo, mover materiales era mucho más sencillo cuando Franklin estaba aquí.', 28153),
(161504, 'esMX', '', '$UBienvenido:Bienvenida; a nuestra humilde posada. ¿En qué puedo ayudarte?', 28153),
(161503, 'esMX', '', '¿Necesitas ayuda para regresar a Boralus?', 28153),
(161502, 'esMX', 'Has demostrado ser $Uun verdadero aliado:una verdadera aliada;, $p.\n\nSiempre serás $Ubienvenido:bienvenida; a nuestra caravana, aquí y en cualquier lugar al que nos lleven las arenas.', '', 28153),
(161501, 'esMX', '', 'La vida nunca será fácil en Vol\'dun, pero será más sencilla después de nuestras victorias contra los infieles.\n\nGracias, $p.\n\nDescansa y disfruta la hospitalidad de mi pueblo. Habla con los pequeños que nos ayudaste a rescatar. Bebe un trago.\n\nEs por estos momentos de paz que luchamos, y debemos procurar disfrutarlos.', 28153),
(161500, 'esMX', '', 'Ha sido una gran aventura, $p. La recordaré por mucho tiempo.\n\nAh, no te olvides de saludar a Dolly. ¡Te echa de menos!', 28153),
(161499, 'esMX', 'La situación en el Patio de la Maderera Algerson se ha resuelto. Todos aquellos que estén a la espera de madera recibirán sus pedidos pronto.', '', 28153),
(161498, 'esMX', '', 'Agh, el pelo de estas pieles de jabalí me desafila la navaja. Tengo que pedirle a Grix que me haga algo mejor.', 28153),
(161497, 'esMX', 'La Guardia Tarjasenda nos ha informado que ya se puede volver a viajar a Drustvar con seguridad. No obstante, advierte a los viajeros curiosos que no se desvíen de los caminos.', '', 28153),
(161496, 'esMX', '¿Quién va con Talanji? ¿Será de... la Horda?', '', 28153),
(161495, 'esMX', '¿Tiene alguna calavera nueva? ¡Déjame ver!', '', 28153),
(161494, 'esMX', '¡La princesa ha vuelto!', '', 28153),
(161493, 'esMX', '¡Talanji! ¡Talanji!', '¡Talanji! ¡Talanji!', 28153),
(161492, 'esMX', 'Llévame de regreso a Zuldazar.', 'Llévame de regreso a Zuldazar.', 28153),
(161491, 'esMX', 'Lord Norwington quisiera invitar a todos los jinetes habilidosos y a los cazadores de caza mayor a participar del 15.° Festival de Equitación y Cacería  de Norwington en su finca.', '', 28153),
(161490, 'esMX', '', 'La civilización es tan aburrida... Tendría que estar en la naturaleza, cazando...', 28153),
(161489, 'esMX', 'Mi último... fin de turno...', 'Mi último... fin de turno...', 28153),
(161488, 'esMX', '¡Te moleré a golpes!', '¡Te moleré a golpes!', 28153),
(161487, 'esMX', 'La Guardia Valiente desaconseja los viajes a Drustvar hasta próximo aviso. Está a la espera de una repuesta de la Guardia Tarjasenda. No hay más información por el momento.', '', 28153),
(161486, 'esMX', 'No te preocupes, seguro que sí. Toma, me pidió que te diera esta carta.', 'No te preocupes, seguro que sí. Toma, me pidió que te diera esta carta.', 28153),
(161485, 'esMX', '', 'Ey, Cass. No encuentro mi cuchillo para desollar favorito. De casualidad no lo... ¡Olvídalo! Lo encontré.', 28153),
(161484, 'esMX', 'A quienes estén preocupados por los rumores extraños sobre el Patio de la Maderera Algerson: Maynard quiere que sepan que son puras exageraciones para afectar sus emociones, y que el patio simplemente está atravesando problemas de negocios habituales.', '', 28153),
(161483, 'esMX', 'Priscilla... se quedará con tu cabeza por esto...', 'Priscilla... se quedará con tu cabeza por esto...', 28153),
(161482, 'esMX', '¡Husmear no es bueno para la salud!', '¡Husmear no es bueno para la salud!', 28153),
(161481, 'esMX', 'Por decreto de la gran almirante, quisiera recordarles que todos los ciudadanos que planeen visitar Canto Tormenta deben presentarse en el puesto de control del valle para someterse a una inspección ante los guardias de Lord Canto Tormenta.', '', 28153),
(161480, 'esMX', '¡Ahhhh, mamá! La extraño mucho. De veras espero que vuelva a casa pronto.', '', 28153),
(161479, 'esMX', 'Los viento\' siempre cambian y mutan. A veces para bien. A veces para mal. Pa\'ku nos enseña que hay que ir allí donde el viento nos lleva, pues es allí donde nos necesitan.\n\nTú y tu Horda han ayudado muchísimo a mi rey y a mi gente. Nunca nos olvidaremo\' de eso.\n\nLoti no nos dejará. Quizá debería perdonarla. O perdirle perdón. No me acuerdo. Eh\'te puede ser el final.', '', 28153),
(161478, 'esMX', '', '¡Ey!$b$b¿Sientes curiosidad por el oficio de ingeniería?', 28153),
(161477, 'esMX', '¡Y papá trabaja como una hormiga para arreglar la granja!', '', 28153),
(161476, 'esMX', 'Extraño a mi mamá... Hace mucho que se ha ido de casa.', '', 28153),
(161475, 'esMX', 'Sabes... Creo que algún día yo también quiero ser aventurero.', '', 28153),
(161474, 'esMX', '¡¡No puedo creer que luchaste contra los wendigos y ganaste!!', '', 28153),
(161473, 'esMX', 'Ohhhh, ¡dime que tienes nuevas historias emocionantes para contar!', '', 28153),
(161472, 'esMX', '¡Hola, $p!', '', 28153),
(161471, 'esMX', 'Estaría muerto si no fuera por ti. Gracias.', 'Estaría muerta si no fuera por ti. Gracias.', 28153),
(161470, 'esMX', '¡Oh, loa, esto será durísimo!', '¡Oh, loa, esto será durísimo!', 28153),
(161469, 'esMX', '¡Maldita Horda! ¡Lor\'danel no hizo nada para merecer esto!', '¡Maldita Horda! ¡Lor\'danel no hizo nada para merecer esto!', 28153),
(161468, 'esMX', 'Ey, hola. Vaya, luces... terrible.$b$bNo te preocupes, pastelito. ¡Danny tiene lo que necesitas!', '', 28153),
(161467, 'esMX', 'Que los loa los acompañen.', '', 28153),
(161466, 'esMX', 'Es una época aciaga para Zandalar. Trols de sangre, traidores y loas muertos. Nueh\'tros cielo\' están llenos de oscuridad y los susurro\' del viento nos traen más problema\'.\n\nIncluso Loti se muestra amable hacia mí. No es natural. No me gusta.\n\nMe alegro de que eh\'tés aquí, $n. Y también la Horda.', '', 28153),
(161465, 'esMX', '¡Que Elune nos ayude!', '¡Que Elune nos ayude!', 28153),
(161464, 'esMX', 'Un momento... ¡¿que quieres hacer QUÉ?!', 'Un momento... ¡¿que quieres hacer QUÉ?!', 28153),
(161463, 'esMX', '¡¿A quién se le ocurrió que esto era buena idea?!', '¡¿A quién se le ocurrió que esto era buena idea?!', 28153),
(161462, 'esMX', 'La granja es un caos, ¡no sé qué sucedió!', '', 28153),
(161461, 'esMX', 'Todo pasó tan rápido...', 'Todo pasó tan rápido...', 28153),
(161460, 'esMX', '¡Alabada sea Elune!', '¡Alabada sea Elune!', 28153),
(161459, 'esMX', '¿Vas a alguna parte?', '¿Vas a alguna parte?', 28153),
(161458, 'esMX', 'Pensé que era final. ¡Gracias!', 'Pensé que era final. ¡Gracias!', 28153),
(161457, 'esMX', 'No puede haber tantos árbole\' en este sitio.', 'No puede haber tantos árbole\' en este sitio.', 28153),
(161456, 'esMX', 'Hay demasiados árbole\' aquí.', 'Hay demasiados árbole\' aquí.', 28153),
(161455, 'esMX', 'Lor\'danel no tenía chances...', 'Lor\'danel no tenía chances...', 28153),
(161454, 'esMX', 'El k\'liyant sufrirá por eh\'to.', 'El k\'liyant sufrirá por eh\'to.', 28153),
(161453, 'esMX', 'Conocí a tu madre. ¡Te envía saludos!', 'Conocí a tu madre. ¡Te envía saludos!', 28153),
(161452, 'esMX', 'Me desconcierta el desempeño de eh\'tos cuernoatroz en este momento.', 'Me desconcierta el desempeño de eh\'tos cuernoatroz en este momento.', 28153),
(161451, 'esMX', '¡Auu! ¡Soy alérgico al dolor!', '¡Auu! ¡Soy alérgica al dolor!', 28153),
(161450, 'esMX', '¿Y si me rindo y me quedo aquí?', '¿Y si me rindo y me quedo aquí?', 28153),
(161449, 'esMX', '¡Gonk, no me falles ahora!', '¡Gonk, no me falles ahora!', 28153),
(161448, 'esMX', '¡A volar!', '¡A volar!', 28153),
(161447, 'esMX', '¡¿Por qué nos atacan?!', '¡¿Por qué nos atacan?!', 28153),
(161446, 'esMX', '¡Nooo! ¡Noooooo! ¡Nooooooooooo!', '¡Nooo! ¡Noooooo! ¡Nooooooooooo!', 28153),
(161445, 'esMX', '¡Por má\' rápido que sean, no me atraparán!', '¡Por má\' rápido que sean, no me atraparán!', 28153),
(161444, 'esMX', '¡Corre!', '¡Corre!', 28153),
(161443, 'esMX', '<El diario está abierto en una página que detalla el ataque de la Horda a Plaza Presabrenna.>', '<El diario está abierto en una página que detalla el ataque de la Horda a Plaza Presabrenna.>', 28153),
(161442, 'esMX', '', '¡Yo ni siquiera sabía para qué servía el sello!\n\nAhora, más que nunca, tenemo\' que trabajar juntos para superar los desafío\' que amenazan Zandalar. Buh\'ca a tus compañero\' de manada y ayúdalos a llevar el peso de su carga.\n\nEl traidor Zul ha muerto. Podría recordarle a Raal que yo tenía razón, pero ya que somo\' tan pocos, tal vez sería mejor hacer las paces, ¿no? Bah.', 28153),
(161441, 'esMX', '', '¡$UBienvenido:Bienvenida; a Pieles y Cueros Kultiranos!$b$bAy... tenemos que pensar un nombre mejor.$b$bSoy Cass, y ofrezco lecciones de peletería. Mi compañera, Cami, es un poco gruñona, pero no encontrarás a ninguna peletera mejor que ella.$b$b¿Qué buscabas?', 28153),
(161440, 'esMX', '', 'La pérdida de tantos loa... Que Gonk proteja a quienes eh\'tán a la deriva. Siento un dolor muy fuerte en el corazón por mi rey y la princesa. La pérdida de Rezan les ha abierto una herida en el corazón.\n\nBAH. Puede que tenga que ser un poco más amable con Raal, pero solo por unos día\'.\n\nGracias, $n. Tú y tu Horda son fuertes. Nuestra manada es más fuerte gracias a ustede\'. Los necesitaremo\'.', 28153),
(161439, 'esMX', '', 'Una y otra vez, has demostrado tu valor ante el Imperio zandalari. La derrota de los trol\' de sangre, la amenaza sethrak y también del profeta traidor.\n\nE\' un honor tener un aliado como tú, $n.', 28153),
(161438, 'esMX', '¿Supongo que buscas una mascota nueva?\n\n<Ulfar se burla>\n\nLa magia de este lugar es extensa y profunda. Vive incluso en algunos animales de la región. Son manifestaciones poderosas de la naturaleza que hay que respetar.', '', 28153),
(161437, 'esMX', 'Eres $Uobservador:observadora;, ¿eh?\n\n<Ulfar se ríe.>\n\nYo ciertamente lo soy, pero no todo mi pueblo estaba de acuerdo con el conflicto.\n¿Jamás hubo disidencias entre tu gente? \nLos oradores de espinas nos unimos a la sociedad kultirana. Algunos de sus descendientes oyeron el llamado de la naturaleza y desearon aprender las tradiciones antiguas, así que se las enseñamos. ¿Tal vez tú escuchaste el llamado? ¿No?', '', 28153),
(161436, 'esMX', 'Zul eh\'tá muerto, ¿pero a qué costo?\n\nEl Gran Sello está roto. Mythrax el Revelador vuelve a andar por el mundo. Un mal mayor al que cualquiera de los zandalari se haya enfrentado nos acecha, y lleva el nombre de G\'huun.\n\nLa culpa e\' mía, $n. Si hubiera escuchado a Talanji, si hubiera lidiado con Zul en alguna de las numerosa\' veces en que moh\'tró un comportamiento dudoso, quizá podríamos haber evitado todo esto. Quizá mi loa todavía estaría vivo y yo no hubiera tenido que aliar a mi gente con el loa de la muerte.\n\nEstoy avergonzado.\n\nPero tú, $n, has permanecido a mi lado. Tu Horda ha luchado junto a nosotro\' en contra nueh\'tros enemigo\' más antiguos. Los zandalari no lo olvidarán.\n\nYo me cercioraré de que no lo hagan.', '', 28153),
(161435, 'esMX', 'Así es. No todo mi pueblo estuvo de acuerdo con el conflicto. ¿Jamás hubo disidencias entre tu gente? \n\nLos oradores de espinas nos unimos a la sociedad kultirana. Algunos de sus descendientes oyeron el llamado de la naturaleza y desearon aprender las tradiciones antiguas, así que se las enseñamos.', '', 28153),
(161434, 'esMX', 'Soy Ulfar, el último de los oradores de espinas drust, y el maestro de estos estudiantes. Algún día habré cumplido mi labor, entonces volveré a la tierra y un nuevo alto orador de espinas surgirá para dirigir. Ese es el orden natural de las cosas.\n\nPero ese día todavía no ha llegado.', '', 28153),
(161433, 'esMX', '¡Bu! ¡Me sorprendiste!$b$bAsí que... ¿has venido para aprender a pescar? Porque es lo único que sé hacer.', '', 28153),
(161432, 'esMX', 'He visto animales que parecen tener algo de planta. ¿Me cuentas algo de ellos?', 'He visto animales que parecen tener algo de planta. ¿Me cuentas algo de ellos?', 28153),
(161431, 'esMX', '¡Eres drust! ¡Luchamos una guerra contra ustedes!', '¡Eres drust! ¡Luchamos una guerra contra ustedes!', 28153),
(161430, 'esMX', '¿Eres drust? ¿No hubo una guerra contra ustedes?', '¿Eres drust? ¿No hubo una guerra contra ustedes?', 28153),
(161429, 'esMX', '¿Volverías a contarme tu historia?', '¿Volverías a contarme tu historia?', 28153),
(161428, 'esMX', '¿Quién eres?', '¿Quién eres?', 28153),
(161427, 'esMX', '', 'Debemos recordar que también tenemos que cuidarnos a nosotros mismos, $p. No podemos ayudar a nuestros seres queridos si apenas estamos sobreviviendo.', 28153),
(161426, 'esMX', '¿Tú también eres druida?', '¿Tú también eres druida?', 28153),
(161425, 'esMX', '¿Ustedes son druidas?', '¿Ustedes son druidas?', 28153),
(161424, 'esMX', '', '¡Espero que hayas tenido suerte en tus aventuras, $p!', 28153),
(161423, 'esMX', 'Sí, $n. Somos los guardianes del equilibrio natural, los vigilantes del ciclo. La vida es parte de la naturaleza, al igual que la muerte.', '', 28153),
(161422, 'esMX', 'No somos tan distintos a ti, $n. Somos los guardianes del equilibrio, vigilantes del ciclo. La vida es parte de la naturaleza, al igual que la muerte. Pero tú sabes esto, pues eres $uun:una; druida.\n\n$UBienvenido:Bienvenida; a nuestra arboleda.', '', 28153),
(161421, 'esMX', '', 'Extraño mucho a Ancel y a su padre. Ojalá pueda regresar a casa pronto.', 28153),
(161420, 'esMX', '', 'Qué bueno volver a verte, $p. Espero que hayas estado bien.', 28153),
(161419, 'esMX', '<Leer la entrada del diario.>', '<Leer la entrada del diario.>', 28153),
(161418, 'esMX', '¡Ningún problema!', '¡Ningún problema!', 28153),
(161417, 'esMX', 'Lee la parte en la que tú y Talanji vieron por primera vez el Corazón de las Tinieblas.', 'Lee la parte en la que tú y Talanji vieron por primera vez el Corazón de las Tinieblas.', 28153),
(161416, 'esMX', '', 'Los extraño mucho y espero regresar a casa pronto. Estoy segura de que Raimond está haciendo lo mejor que puede, pero el pobre tiene un verdadero talento para generar caos en cualquier lugar.\n\nSi vuelves a verlos, entrégale esta carta a mi querido Ancel.', 28153),
(161414, 'esMX', 'Vaza el loco ha tomado notas sobre todos los acontecimientos que ocurrieron en Nazmir. Pese a su nombre, sus notas están muy bien escritas y organizadas.', '', 28153),
(161413, 'esMX', '', 'El caos que ha sembrado Zul...\n\nEstoy agradecida de que tú y la Horda aún eh\'tén aquí, $n. Me alegro de no haberme equivocado cuando deposité mi fe en ustede\'. Pensar que los zandalari podrían haberse enfrentado semejantes cosa\' sin la ayuda de nadie es tan aterrador que... no encuentro palabras para describirlo.\n\nSi sobrevivimo\' a todo esto, espero que podamo\' devolverte el favor. Los zandalari siempre estarán en deuda contigo.', 28153),
(161412, 'esMX', '\"Bien, hermano\", dijo Koralynn. \"Eres un marinero terrible, pero creo que serás un excelente maresabio\".', '\"Bien, hermano\", dijo Koralynn. \"Eres un marinero terrible, pero creo que serás un excelente maresabio\".', 28153),
(161411, 'esMX', '', 'Eitrigg, iré contigo y hablaré con tu jefa de guerra. Aunque mi madre me había dicho que el jefe era un trol, no entiendo...', 28153),
(161410, 'esMX', '', 'Rezan... mi loa... eh\'tá muerto.\n\nMe duele el corazón. Mi padre nunca cargó con semejante peso. La traición de Zul nos golpeó con má\' fuerza de lo que todos nos podríamo\' haber imaginado... Ha sorprendido incluso a quienes sospecharon de él desde el principio.\n\nPero un hereje como él no se saldrá con la suya tan fácil, $n. ¡Tenemo\' que reunir a nuestra gente, a nuestros loa, a nuestros aliado\'! Solo así podremos ponerle punto final a las lucubracione\' de Zul.', 28153),
(161409, 'esMX', '', 'Muy bien entonces. Hasta la próxima.', 28153),
(161408, 'esMX', 'Ey, hola, $umuchacho:muchacha;!$b$b¡$UBienvenido:Bienvenida; a Barbacoa boralana de Byron y hnos.! ¡Las mejores carnes ahumadas de este lado de Forjaz!$b$b¿Qué deseabas?', '', 28153),
(161407, 'esMX', 'Cuéntame sobre el trato que hizo Rastakhan con Bwonsamdi.', 'Cuéntame sobre el trato que hizo Rastakhan con Bwonsamdi.', 28153),
(161406, 'esMX', 'Ante nosotros se erigen los muros de Orgrimmar, capital de la Horda.', '', 28153),
(161405, 'esMX', 'Hace mucho tiempo, sentí lo mismo. Puede ser... inquietante. Haré lo que sea para ayudarte a ti y a tu pueblo.', '', 28153),
(161404, 'esMX', 'Guau... qué historia.', 'Guau... qué historia.', 28153),
(161403, 'esMX', '', '¡Mythrax el Revelador anda suelto por el mundo otra vez! Pensamo\' que era una leyenda, una tradición antigua que servía de advertencia para no sucumbir ante la corrupción del tiempo y la complacencia. Gracias a esa serpiente de Jakra\'zet y a sus aliado\', los fiele\', el terror ha renacido.\n\nPero todo no está perdido. Jakra\'zet se topó con su destino, y nosotros tenemo\' nuevos aliado\': los vulpera y los que idolatran al loa Sethraliss. Sin embargo... Me temo que ni siquiera con la ayuda de ambos podremo\' superar a un enemigo semejante.\n\nEh\'tos son días aciagos... y espero que no sean los último\' días de Zandalar.', 28153),
(161402, 'esMX', '', 'Hace apenas unos momentos, defendíamos nuestra vida en Draenor. Nunca pensé que volvería a ver otro mundo.', 28153),
(161401, 'esMX', 'Cuéntame sobre Reprimenda de Talanji.', 'Cuéntame sobre Reprimenda de Talanji.', 28153),
(161400, 'esMX', 'Cuéntame sobre el ataque de Mythrax.', 'Cuéntame sobre el ataque de Mythrax.', 28153),
(161399, 'esMX', 'Está hecho. Señora suprema, esto... es Azeroth.', '', 28153),
(161398, 'esMX', 'Cuéntame sobre la traición de Zul.', 'Cuéntame sobre la traición de Zul.', 28153),
(161397, 'esMX', '', 'Durante generaciones, los zandalari se han enfrentado a los nazmani. Nueh\'tras frontera\' han estado asediadas desde mucho ante\' de que yo naciera, y mi padre no ha conocido tiempos de paz con los trol\' de sangre. Mi padre los consideraba una peste, y nosotros les permitimo\' reunir fuerzas. Ahora sabemos cuál es la fuente de esa fuerza.\n\nNuestro enemigo responde al dios de la sangre, G\'huun.\n\nNo podemo\' fallar. Si Zuldazar cae, el resto del mundo caerá con nosotro\'. No se detendrán hasta que el dios de la sangre lo domine todo.', 28153),
(161396, 'esMX', '', '$UBienvenido:Bienvenida; a mi tienda.$b$bMira cuanto quieras. Si tienes alguna pregunta, seguramente podré ayudarte.', 28153),
(161395, 'esMX', '', '¡Miip! ¡Miip!', 28153),
(161394, 'esMX', '¡Estos especímenes zandalari requieren de una taxonomía completamente nueva!', '¡Estos especímenes zandalari requieren de una taxonomía completamente nueva!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161393, 'esMX', '', '¡$UBienvenido:Bienvenida; a Encantamientos delicados de Buentiempo!\n\nSi tienes alguna pregunta que hacerme sobre temas místicos, ¡no dudes en preguntar!', 28153),
(161391, 'esMX', '', 'Ay, no... Rompí otra púa.', 28153),
(161390, 'esMX', 'La llave... gira una vez más.', '', 28153),
(161389, 'esMX', '¡Carne errante! Cuando despierte, conocerás la eternidad. ¡Y temblarás!', '', 28153),
(161388, 'esMX', '', '¡Ay! ¡Calambre en la mano!', 28153),
(161387, 'esMX', 'Hay una verdad enorme y terrible al comienzo de todas las cosas. Y yo soy su heraldo. Escuchen mi sermón y conozcan su infinita insignificancia.', '', 28153),
(161386, 'esMX', 'No entré en pánico. Nadé y nadé, sin dejar de beber.', '', 28153),
(161385, 'esMX', '¡Y ahí estaba yo, encerrado en un tanque enorme de cerveza de trueno!', '', 28153),
(161384, 'esMX', 'Han visto el más allá. Ahora percibirán las cosas como son realmente.', '', 28153),
(161383, 'esMX', '', 'Momento, ¿esto es una mancha o un glifo?', 28153),
(161382, 'esMX', 'Sylvanas quiere enfrentarse conmigo, y yo pienso darle lo que quiere.', '', 28153),
(161381, 'esMX', 'Un par de cervecerías de enanos le vendrían muy bien a Claro de Luna.', '', 28153),
(161380, 'esMX', '', '¡Vamos! El submarino ya debería estar desplegado.', 28153),
(161379, 'esMX', '¡Otra ronda para mis amigos!', '', 28153),
(161378, 'esMX', '¡Entrega especial para usted, señor!', '', 28153),
(161377, 'esMX', 'Bueno, reconozco que fue malo. Como sea, ¡estamos aquí!', '', 28153),
(161376, 'esMX', '¡Estoy demasiado arraigado! ¿Entiendes?', '', 28153),
(161375, 'esMX', 'Mis padres querían que fuera a la marina. ¿Te imaginas? Imposible.', '', 28153),
(161374, 'esMX', 'Él y los demás me han guiado desde que escuché el llamado, cuando era pequeño.', '', 28153),
(161373, 'esMX', 'Puede que Ulfar sea un maestro exigente, pero es justo.', '', 28153),
(161372, 'esMX', '¡Espera!', '', 28153),
(161371, 'esMX', '¡Ey! ¡$n! ¡Por aquí!', '', 28153),
(161370, 'esMX', 'El sendero hacia la arboleda de Ulfar puede ser peligroso. Arthur, reúnete con nuestros amigos al comienzo del camino.', '', 28153),
(161369, 'esMX', '¡Claro! ¡Te veré allí, $n!', '', 28153),
(161368, 'esMX', 'Tus hazañas han estado en boca de todos en Falla de Telogrus, $p.\n\nAgradezco que estés a mi lado en esta misión. Juntos, nada podrá detenernos.', '', 28153),
(161367, 'esMX', 'Estoy haciendo todo lo posible para limpiar el terreno.', 'Estoy haciendo todo lo posible para limpiar el terreno.', 28153),
(161366, 'esMX', 'Con el desarme de esos dispositivos esta área debería ser un poco más segura... por el momento.', 'Con el desarme de esos dispositivos esta área debería ser un poco más segura... por el momento.', 28153),
(161365, 'esMX', 'Cuidado donde pisas.', 'Cuidado donde pisas.', 28153),
(161364, 'esMX', 'He desarmado todos los dispositivos que encontré, ¡pero debes tener cuidado allá afuera!', 'He desarmado todos los dispositivos que encontré, ¡pero debes tener cuidado allá afuera!', 28153),
(161363, 'esMX', '', '¡Sí, está reparado, sin dudas! ¡Eh! ¿Por qué no les echamos un vistazo a los registros que encontró $n?', 28153),
(161362, 'esMX', 'Ya veo. Es bueno que lo hayas reparado.', '', 28153),
(161361, 'esMX', 'Qué flor más bonita.', '', 28153),
(161360, 'esMX', '', '¡Oh! Ja, ja... bueno, el campo de contención miniaturizado no estaba funcionando tan bien hace diez minutos.', 28153),
(161359, 'esMX', 'Kelsey, ¿por qué no llevamos este submarino hacia la Isla de Colmillos?', '', 28153),
(161358, 'esMX', '', 'Siéntense y relájense; ¡estaremos en el puerto de guerra en un abrir y cerrar de ojos!', 28153),
(161357, 'esMX', 'Tu saltamareas se está asustando. ¡Vuelve ahora!', 'Tu saltamareas se está asustando. ¡Vuelve ahora!', 28153),
(161356, 'esMX', 'Mmm... ¡Áfidos! Tendré que encargarme de USTEDES más tarde.', '', 28153),
(161355, 'esMX', 'Vamos,pequeñín. Germina.', '', 28153),
(161354, 'esMX', 'Ahh, lo mejor de este trabajo es la delicada fragancia del aethril.', '', 28153),
(161353, 'esMX', 'Conocí la Isla Yojamba hace muchos años en una expedición a Vega de Tuercespina. Yo formé parte de las fuerzas que derrotaron a Hakkar cuando intentó volver a este mundo. Nosotros les dimos las gloriosas armas a los héroes que lucharon contra esa vil abominación que se hacía llamar \"loa\".\n\nCuando volvimos victoriosos a Zandalar, cometí el error de exagerar mi victoria ante el profeta Zul. Quizá dije algunas cosas en público que no cayeron demasiado bien.\n\nAhora sirvo bocadillos y dulces.', '', 28153),
(161352, 'esMX', 'Comienzas a perder interés en la historia. ¡Vuelve ahora!', 'Comienzas a perder interés en la historia. ¡Vuelve ahora!', 28153),
(161351, 'esMX', '', 'Qué bueno volver a verte, $p. Admiro la rapidez con la que has ascendido en los rangos de la Alianza. \n\nPero me complace aún más que sigas resistiéndote a los susurros.\n\nLa guerra es salvaje y caótica. Veas lo que veas... vivas lo que vivas... nunca debes perder el control. No permitas que las sombras se apoderen de tu voluntad.\n\nLa Alianza cuenta contigo.\n\nY yo también.', 28153),
(161350, 'esMX', '¿Qué es o fue Yojamba?', '¿Qué es o fue Yojamba?', 28153),
(161349, 'esMX', 'La Alianza está atacando. ¡Tenemo\' que advertirle\' al rey!', 'La Alianza está atacando. ¡Tenemo\' que advertirle\' al rey!', 28153),
(161348, 'esMX', '¡La Alianza está aquí! ¡Adviértanle al continente!', '¡La Alianza está aquí! ¡Adviértanle al continente!', 28153),
(161347, 'esMX', '¡Nos ataca la Alianza! ¡Tengo que avisarle al continente!', '¡Nos ataca la Alianza! ¡Tengo que avisarle al continente!', 28153),
(161346, 'esMX', 'La Alianza está atacando. ¡Tenemo\' que advertirle\' a los demá\'!', 'La Alianza está atacando. ¡Tenemo\' que advertirle\' a los demá\'!', 28153),
(161345, 'esMX', '', 'No bajes la guardia, Umbric. Es un plan ambicioso. Si algo sale mal, se perderán muchas vidas.', 28153),
(161344, 'esMX', 'Parece que esta misión no es tan suicida como había pensado.', '', 28153),
(161343, 'esMX', 'No quiero ofenderte, Halford, pero lo que propones es una misión suicida. Los zandalari exterminaron la última flota que se acercó a sus orillas.', '', 28153),
(161342, 'esMX', 'Sí, tal y como están las cosas, nuestras pérdidas serían catastróficas si intentáramos recalar aquí.', '', 28153),
(161341, 'esMX', 'Sus defensas navales destruyeron la última flota que se acercó a la isla, y solo estaban persiguiendo a una princesa en un barco.', '', 28153),
(161340, 'esMX', '¿Bienes enterrados?', '¿Bienes enterrados?', 28153),
(161339, 'esMX', 'Gracias, supongo...', 'Gracias, supongo...', 28153),
(161338, 'esMX', '¿Querías decirme algo?', '¿Querías decirme algo?', 28153),
(161337, 'esMX', 'Qué calor hace aquí.', 'Qué calor hace aquí.', 28153),
(161336, 'esMX', '<Haces un ademán mostrando el lugar>', '<Haces un ademán mostrando el lugar>', 28153),
(161335, 'esMX', '¿Qué decías?', '¿Qué decías?', 28153),
(161334, 'esMX', '¿Esto era lo que tenías en mente?', '¿Esto era lo que tenías en mente?', 28153),
(161333, 'esMX', 'Ey, hola, no tengas miedo.', '', 28153),
(161332, 'esMX', '¡Creo que será suficiente hasta para una propina!', '', 28153),
(161331, 'esMX', 'Sí, los enterré ante\' de que me atraparan. Lo único que tienes que hacer es encontrar la torre de Sendarraíz, cerca del río, en Nazmir. Eh\'tán ahí, al pie de la torre.', '', 28153),
(161330, 'esMX', 'Creo que te debo el depósito deh\'de hace tiempo. Así que te dejaré ver mis bienes enterrado\'.', '', 28153),
(161329, 'esMX', 'Tengo que admitir que eres $uel mejor:la mejor; guía que una calavera podría pedir.', '', 28153),
(161328, 'esMX', 'Me siento bien. Eh\'te es un lugar acogedor.', '', 28153),
(161327, 'esMX', 'Te lo dije, escuché a uno de esos petaca\' de carbón decir que vivían en un volcán.', '', 28153),
(161326, 'esMX', 'Muy bien, esas cosa\' pasan... te pondrás azul... pero no dejes aquí.', '', 28153),
(161325, 'esMX', 'Sabes, estuve a punto de tener una pih\'ta de carreras en Vol\'dun. A mi socio le preocupaba que otro cataclismo nos dejase bajo el agua y se retiró. Ademá\' no teníamo\' dinero, nos lo quitaron cuando nos exiliamo\'.', '', 28153),
(161324, 'esMX', 'Eso no es un reptil de verdad... Pero no le digas que dije eso.', '', 28153),
(161323, 'esMX', 'Tenemo\' reptile\' grandes en Zandalar, no hubo más grandes jamá\'.', '', 28153),
(161322, 'esMX', 'Creo que tengo más frío, ¿es posible?', '', 28153),
(161321, 'esMX', '¿Alguna vez vih\'te un sable en la nieve? Qué idea tan loca, la nieve digo.', '', 28153),
(161320, 'esMX', 'Eh\'te lugar es agradable. Podría aparecerme aquí.', '', 28153),
(161319, 'esMX', '¿Cuándo vamo\' a visitar un lugar bonito?', '', 28153),
(161318, 'esMX', '', 'Nos mudamos a esa granja con la esperanza de cambiar nuestra vida. Las cosas no andaban bien en la ciudad y a Ancel no le estaba yendo bien en la escuela. Su padre y yo creímos que sería una buena idea alejarnos del bullicio de la ciudad y buscar un lugar más tranquilo en el campo. \n\nTuve que abandonar mis estudios arcanos y dedicarme a trabajar la tierra para que empezara a producir. Las cosas no fueron fáciles, el trabajo era muy duro y durante mucho tiempo sobrevivimos con migajas. Cada vez que Raimond creía que estábamos por tener un respiro, inevitablemente algo salía muy mal.\n\nEntonces decidí que lo mejor sería que retomara mi búsqueda de lo arcano. He estado viajando, mejorando mis habilidades y ofreciendo mis talentos a los ricos para mantener a mi familia.', 28153),
(161317, 'esMX', '¿Hace un poco de frío aquí o soy yo?', '', 28153),
(161316, 'esMX', 'Eh\'te lugar parece interesante.', '', 28153),
(161315, 'esMX', 'Ooh, ¿a dónde iremo\' hoy?', '', 28153),
(161314, 'esMX', '¿Gracias...?', '¿Gracias...?', 28153),
(161313, 'esMX', 'Tendremos que dejarlo para otro día.', 'Tendremos que dejarlo para otro día.', 28153),
(161312, 'esMX', '¿Tal vez? Pero no soy druida.', '¿Tal vez? Pero no soy druida.', 28153),
(161311, 'esMX', 'Desde luego.', 'Desde luego.', 28153),
(161310, 'esMX', 'Qué frustrante.', 'Qué frustrante.', 28153),
(161309, 'esMX', 'Apuesto que sí.', 'Apuesto que sí.', 28153),
(161308, 'esMX', '¿Pero acaso esas formas épicas no te permiten volar más rápido?', '¿Pero acaso esas formas épicas no te permiten volar más rápido?', 28153),
(161307, 'esMX', 'En realidad, cambié de opinión, prefiero no saber.', 'En realidad, cambié de opinión, prefiero no saber.', 28153),
(161306, 'esMX', '¿Qué es lo que te ha molestado?', '¿Qué es lo que te ha molestado?', 28153),
(161305, 'esMX', 'Parece que tienes una buena historia.', 'Parece que tienes una buena historia.', 28153),
(161304, 'esMX', '', 'Bueno... es una historia un poco larga, pero te la contaré con gusto si estás $Udispuesto:dispuesta; a escuchar. ¿Tienes un momento libre?', 28153),
(161303, 'esMX', 'No voy a usar eso en tu contra. Solo voy escribírtelo, en letras grandes, para que sea más fácil de leer.', '', 28153),
(161302, 'esMX', 'Ey, estaba pensando... si les enseño a verse respetables sin que tengan que renunciar a su preciado \"vuelo rápido\", tal vez me escuchen.', '', 28153),
(161301, 'esMX', 'Tú lo sabes bien. Pero nadie me escucha. Se limitan a mover sus desprolijas melenas... piel... hojas... cuello... ah, demonios, qué importa.', '', 28153),
(161300, 'esMX', 'Sí... Pero, ¿puedo preguntar por qué no estás con ellos? ¡Hicieron un lío enorme en la granja!', 'Sí... Pero, ¿puedo preguntar por qué no estás con ellos? ¡Hicieron un lío enorme en la granja!', 28153),
(161299, 'esMX', 'Ahí está, lisa y llana ignorancia. ¿Quién dice que un veterano no está a la altura de ese nuevo estilo elegante? Las formas sencillas y originales nos sirvieron por milenios.', '', 28153),
(161298, 'esMX', 'Bueno, ya ves, así son los druidas de hoy en día. No nos respetan a nosotros, que seguimos la tradición. No me verás volando por ahí con borlas o armaduras elegantes.', '', 28153),
(161297, 'esMX', '', '¿Dónde lo encontraste? ¡Creí que lo había perdido para siempre!', 28153),
(161296, 'esMX', 'Ah, ¿eres $uun:una; escriba? ¿Podrías escucharme por un rato?', '', 28153),
(161295, 'esMX', 'Todos andan tan elegantes.', '', 28153),
(161294, 'esMX', 'En mi época las personas respetaban las tradiciones de los más viejos.', '', 28153),
(161293, 'esMX', 'Vine a Kul Tiras para alejarme de la guerra. Así es mi vida.', '', 28153),
(161292, 'esMX', 'No entiendo a los druidas de hoy en día.', '', 28153),
(161291, 'esMX', '¿No vez que estoy disfrutando del sol?', '', 28153),
(161290, 'esMX', 'Márchate.', '', 28153),
(161289, 'esMX', 'He despejado el camino... ¡Debes escapar ahora!', 'He despejado el camino... ¡Debes escapar ahora!', 28153),
(161288, 'esMX', 'Déjame en paz.', '', 28153),
(161287, 'esMX', '', '¿Qué tipo de gran aventura te ha traído a esta parte del mundo?', 28153),
(161286, 'esMX', '', 'Hacer sacrificios siempre es difícil, aun si son por el bien común.', 28153),
(161285, 'esMX', '', 'Espero algún día regresar a casa con el poder de curar nuestras desgracias frecuentes.', 28153),
(161284, 'esMX', '', 'La búsqueda de conocimiento arcano es muy demandante. A veces, siento que el viaje me abruma...', 28153),
(161283, 'esMX', '', '¿Tienes hijos? Me pregunto cómo estará mi querido Ancel... Tendría que enviarle una carta.', 28153),
(161282, 'esMX', '', '¿Por casualidad no vendes instrumentos mágicos poco comunes?', 28153),
(161281, 'esMX', '', 'Hola, encantada de conocerte.', 28153),
(161280, 'esMX', '¡Ack! ¡Tenía la boca abierta!', '¡Ack! ¡Tenía la boca abierta!', 28153),
(161279, 'esMX', '¡El parche! ¡No sirve!', '¡El parche! ¡No sirve!', 28153),
(161278, 'esMX', '¡Gyahhh! ¡Te arrancaré las alas, rata voladora!', '¡Gyahhh! ¡Te arrancaré las alas, rata voladora!', 28153),
(161277, 'esMX', '¡¡Argh!! ¡Mi ojo bueno!', '¡¡Argh!! ¡Mi ojo bueno!', 28153),
(161276, 'esMX', '¡Maldito seas, diablo emplumado!', '¡Maldito seas, diablo emplumado!', 28153),
(161275, 'esMX', 'Agghh...', 'Agghh...', 28153),
(161274, 'esMX', '¡¡Otra vez no!!', '¡¡Otra vez no!!', 28153),
(161273, 'esMX', '¡Agh! ¡Qué asco!', '¡Agh! ¡Qué asco!', 28153),
(161272, 'esMX', 'No irán a perder, ¿no? He apostado dinero por ustedes... y a mi padre no le gustará que pierda dinero.', '', 28153),
(161271, 'esMX', 'No te preocupe\', oro querido. ¡Volveré por ti pronto!', 'No te preocupe\', oro querido. ¡Volveré por ti pronto!', 28153),
(161270, 'esMX', '¡Levante la mirada, soldado! ¡Estamos en zona de guerra!', '', 28153),
(161269, 'esMX', 'Mire todo ese oro, sargento... ¡Brilla tanto!', '', 28153),
(161268, 'esMX', '¡Hola! Estoy tratando de entretener a los niños. ¿Qué sugieres que escuchemos?', '¡Hola! Estoy tratando de entretener a los niños. ¿Qué sugieres que escuchemos?', 28153),
(161267, 'esMX', '', '¡Oye tú! ¿Te gustaría resolver acertijos en los que si fracasas podrías terminar $Umuerto:muerta; o $Uconvertido:convertida; en gallina? En ese caso, ¡tendrías que considerar aprender ingeniería!', 28153),
(161266, 'esMX', '', 'Sabes... Todavía tengo que terminar el gólem aéreo en el que estaba trabajando.', 28153),
(161265, 'esMX', 'Quiero escuchar una canción seria.', 'Quiero escuchar una canción seria.', 28153),
(161264, 'esMX', 'Quiero escuchar una historia sobre los maresabios.', 'Quiero escuchar una historia sobre los maresabios.', 28153),
(161263, 'esMX', 'Quisiera escuchar una tonta canción.', 'Quisiera escuchar una tonta canción.', 28153),
(161262, 'esMX', 'Cuéntame sobre Athair.', 'Cuéntame sobre Athair.', 28153),
(161261, 'esMX', '¡Platería! ¡Teteras! ¡Finos utensilios! ¡Todo hecho según los estándares de calidad Aspafresno!', '¡Platería! ¡Teteras! ¡Finos utensilios! ¡Todo hecho según los estándares de calidad Aspafresno!', 28153),
(161260, 'esMX', '', 'Si aumento la fuerza de la carga inicial, aumentaría también el rendimiento de la carga... ¿qué probabilidades hay de que eso salga mal?', 28153),
(161259, 'esMX', '¡Tengo para todos los gustos, compañeros!', '¡Tengo para todos los gustos, compañeros!', 28153),
(161258, 'esMX', '¡Relojes de bolsillo marítimos! ¡Algunos de estos ya no se fabrican más!', '¡Relojes de bolsillo marítimos! ¡Algunos de estos ya no se fabrican más!', 28153),
(161257, 'esMX', '¡... doce monedas de plata menos que en Vientos Alisios!', '¡... doce monedas de plata menos que en Vientos Alisios!', 28153),
(161256, 'esMX', '¡Brújulas bañadas en oro! ¡Directo del proveedor personal del almirantazgo!', '¡Brújulas bañadas en oro! ¡Directo del proveedor personal del almirantazgo!', 28153),
(161255, 'esMX', '', '¿Dónde puse esa llave?', 28153),
(161254, 'esMX', 'Míralos, se escabullen como rata\' de cubierta. ¡Lanza las cargas de profundidad sobre ello\', $p!', 'Míralos, se escabullen como rata\' de cubierta. ¡Lanza las cargas de profundidad sobre ello\', $p!', 28153),
(161253, 'esMX', '¡Mira abajo, $p! ¡Tienen depósitos enteros bajo el agua! ¡Lanza las cargas de profundidad sobre ellos!', '', 28153),
(161252, 'esMX', '', '¡Encantamientos! ¡Son muy lucrativos!', 28153),
(161251, 'esMX', '', '¿Dónde quedó ese anillo? Lo tenía puesto cuando... ay, no... Otra vez...', 28153),
(161250, 'esMX', '', 'El guerrero más fuerte no es nada sin su armadura y sus armas mágicas. ¡Aprende encantamientos!', 28153),
(161249, 'esMX', '', '¿Quieres experimentas en las artes arcanas? ¡Aprende a encantar objetos con propiedades mágicas!', 28153),
(161248, 'esMX', '¡Y los cañones a la pared!', '', 28153),
(161247, 'esMX', '¡Dirige el fuego de las antorchas a las canoas con la bandera roja!', '', 28153),
(161246, 'esMX', '¡Y los cañone\' a la pared! No quiero bucear en las profundidade\' salobre\' hoy.', '', 28153),
(161245, 'esMX', '¡Dirige las antorcha\' a las canoa\' con la bandera roja!', '', 28153),
(161244, 'esMX', '¡Aprende a dominar el fuego y las especias!', '', 28153),
(161243, 'esMX', '¿Tienes hambre? ¿Quieres calmar tu apetito? ¡Prepárate algo de comer!', '', 28153),
(161242, 'esMX', '¡Carnes ahumadas que hacen agua la boca! No están a la venta, ¡pero puedes aprender a prepararlas!', '', 28153),
(161241, 'esMX', '', 'Si alguna vez averiguo quién es el bromista que deja que se destruyan estas reliquias en el camino, le romperé cada hueso del cuerpo.', 28153),
(161240, 'esMX', '', 'Has demostrado gran honor y valentía. Le he transmitido al rey Rastakhan que tal vez se te puedan confiar tareas más importante\'.\n\nAhora, ten cuidado, porque no tengo dudas de que nos observan ojos hostile\'.', 28153),
(161239, 'esMX', '', 'Un coleccionista pagará una buena suma por esto.', 28153),
(161238, 'esMX', '¡Y por eso nuestras naves son las mejores!', '¡Y por eso nuestras naves son las mejores!', 28153),
(161237, 'esMX', 'Y Domenic, con las manos temblando y los ojos como platos, se dio cuenta de que el mar había respondido su llamado.', 'Y Domenic, con las manos temblando y los ojos como platos, se dio cuenta de que el mar había respondido su llamado.', 28153),
(161236, 'esMX', 'Pero las aguas retrocedieron. ¡La bestia quedó empalada en las rocas!', 'Pero las aguas retrocedieron. ¡La bestia quedó empalada en las rocas!', 28153),
(161234, 'esMX', '¡Levantó las naves fugitivas sobre las rocas! El kraken que los perseguía nadó en busca de su presa.', '¡Levantó las naves fugitivas sobre las rocas! El kraken que los perseguía nadó en busca de su presa.', 28153),
(161233, 'esMX', '', 'Realmente tengo que calibrar mi equipo de análisis antes de volver a salir.', 28153),
(161231, 'esMX', 'Luego, de repente, ¡otro kraken tres veces más grande que el que los perseguía, salió de las aguas!', 'Luego, de repente, ¡otro kraken tres veces más grande que el que los perseguía, salió de las aguas!', 28153),
(161229, 'esMX', '\"¡Es nuestro fin!\", gritó la tripulación.', '\"¡Es nuestro fin!\", gritó la tripulación.', 28153),
(161228, 'esMX', 'De repente, ante ellos se elevaron unas rocas enormes que salían del agua.', 'De repente, ante ellos se elevaron unas rocas enormes que salían del agua.', 28153),
(161227, 'esMX', 'Se abrieron paso entre las rocas, y la dirección era certera... ¡pero el kraken ganaba terreno en la persecución!', 'Se abrieron paso entre las rocas, y la dirección era certera... ¡pero el kraken ganaba terreno en la persecución!', 28153),
(161226, 'esMX', '\"¡Al puerto!\", gritó llenó de pánico Domenic, con un pálpito fuerte como una marea que lo empujaba en esa dirección. La nave giró. \"¡A estribor!\". Nuevamente, su hermana lo siguió.', '\"¡Al puerto!\", gritó llenó de pánico Domenic, con un pálpito fuerte como una marea que lo empujaba en esa dirección. La nave giró. \"¡A estribor!\". Nuevamente, su hermana lo siguió.', 28153),
(161225, 'esMX', '¡Un kraken enorme, más grande que su nave más grande, surgió de las profundidades!', '¡Un kraken enorme, más grande que su nave más grande, surgió de las profundidades!', 28153),
(161224, 'esMX', 'Pero cuando llegaron, advirtieron que ahora sus barcos  eran la presa.', 'Pero cuando llegaron, advirtieron que ahora sus barcos  eran la presa.', 28153),
(161223, 'esMX', '\"Creo que los mares estarán calmos y los vientos también\", dijo Domenic. Su predicción resultó acertada, y la pequeña flota de caza se maravilló ante la velocidad con que avanzaban.', '\"Creo que los mares estarán calmos y los vientos también\", dijo Domenic. Su predicción resultó acertada, y la pequeña flota de caza se maravilló ante la velocidad con que avanzaban.', 28153),
(161222, 'esMX', '\"¡Es peligroso!\", exclamó la tripulación. \"¡La nave se hará pedazos!\"', '\"¡Es peligroso!\", exclamó la tripulación. \"¡La nave se hará pedazos!\"', 28153),
(161221, 'esMX', 'Su hermano pensó la pregunta por un tiempo largo, como si estuviera escuchando una canción que solo él oía. Luego dijo. \"Mi instinto me dice que a los bajíos cerca de Kalimdor\".', 'Su hermano pensó la pregunta por un tiempo largo, como si estuviera escuchando una canción que solo él oía. Luego dijo. \"Mi instinto me dice que a los bajíos cerca de Kalimdor\".', 28153),
(161220, 'esMX', '\"Hermano, ¿a dónde crees que deberíamos ir a cazar?\", preguntó, pues su intuición nunca erraba.', '\"Hermano, ¿a dónde crees que deberíamos ir a cazar?\", preguntó, pues su intuición nunca erraba.', 28153),
(161219, 'esMX', 'Koralyn decidió que debían cazar en otro lado.', 'Koralyn decidió que debían cazar en otro lado.', 28153),
(161218, 'esMX', 'Un día zarparon en busca de un kraken para alimentar a la tripulación, pero no encontraron ninguno en los lugares habituales. No encontraron comida durante semanas, ¡la situación era cada vez más funesta!', 'Un día zarparon en busca de un kraken para alimentar a la tripulación, pero no encontraron ninguno en los lugares habituales. No encontraron comida durante semanas, ¡la situación era cada vez más funesta!', 28153),
(161217, 'esMX', 'Un día zarparon en busca de un kraken para alimentar a la tripulación, pero no encontraron ninguno en los lugares habituales.', 'Un día zarparon en busca de un kraken para alimentar a la tripulación, pero no encontraron ninguno en los lugares habituales.', 28153),
(161215, 'esMX', 'Él parecía conocer el mar como nadie. Sabía cuándo vendría una tormenta, cuándo cambiarían las mareas y dónde pescar para conseguir comida.', 'Él parecía conocer el mar como nadie. Sabía cuándo vendría una tormenta, cuándo cambiarían las mareas y dónde pescar para conseguir comida.', 28153),
(161214, 'esMX', 'Pero Koralynn, que tanto había observado y aprendido, también había observado mucho a su hermano.', 'Pero Koralynn, que tanto había observado y aprendido, también había observado mucho a su hermano.', 28153),
(161213, 'esMX', '¡Curioso! NUNCA lo había visto hacer eso...', '', 28153),
(161212, 'esMX', 'Nota mental: Tienes poco extracto de musgo estelar. Consigue más cuando puedas.', '', 28153),
(161211, 'esMX', 'Así que todos se sorprendieron cuando Koralynn lo escogió para su tripulación en su primera jefatura... ¡Incluso Dominic!', 'Así que todos se sorprendieron cuando Koralynn lo escogió para su tripulación en su primera jefatura... ¡Incluso Dominic!', 28153),
(161210, 'esMX', '¡Mejor no hablar de sus intentos por navegar una galera!', '¡Mejor no hablar de sus intentos por navegar una galera!', 28153),
(161209, 'esMX', 'Ah, qué linda condensación.', '', 28153),
(161208, 'esMX', 'Perdía el equilibro en los cordajes, jamás aprendió a hacer buenos nudos ni a orientas las velas.', 'Perdía el equilibro en los cordajes, jamás aprendió a hacer buenos nudos ni a orientas las velas.', 28153),
(161207, 'esMX', 'Domenic era raro. Caminaba por las cubiertas como en un sueño, y a menudo murmuraba.', 'Domenic era raro. Caminaba por las cubiertas como en un sueño, y a menudo murmuraba.', 28153),
(161206, 'esMX', 'Tengo que hacer que regrese el calor...', '', 28153),
(161205, 'esMX', 'Koralynn era todo lo que debía ser una kultirana. Pero su hermano era distinto.', 'Koralynn era todo lo que debía ser una kultirana. Pero su hermano era distinto.', 28153),
(161203, 'esMX', 'Estudiaba los mapas celestes, las corrientes y los terrenos de caza. Miraba a los marinos y aprendía.', 'Estudiaba los mapas celestes, las corrientes y los terrenos de caza. Miraba a los marinos y aprendía.', 28153),
(161202, 'esMX', 'Mmmm... Creo que tendré que pedirle más fjarnskaggl a Enges.', '', 28153),
(161201, 'esMX', 'Koralynn era fuerte e inteligente.', 'Koralynn era fuerte e inteligente.', 28153),
(161200, 'esMX', 'Había una vez dos niños, Koralynn y Domenic.', 'Había una vez dos niños, Koralynn y Domenic.', 28153),
(161199, 'esMX', '', 'Gracias, comandante. ¡Habríamos muerto si no nos hubiese salvado! ¡Volveremos a nuestros puestos de inmediato!', 28153),
(161198, 'esMX', 'Miimii decide empezar a seguirte.', 'Miimii decide empezar a seguirte.', 28153),
(161197, 'esMX', 'De un sarcófago cercano sale un sonido...', 'De un sarcófago cercano sale un sonido...', 28153),
(161196, 'esMX', 'Miimii la momia te mira expectante.', 'Miimii la momia te mira expectante.', 28153),
(161195, 'esMX', '¿Ni un pescado? Muy bien. Moriré.', '', 28153),
(161194, 'esMX', 'Siento que la última vez que comí fue hace un siglo.', '', 28153),
(161193, 'esMX', '¡¿TODAVÍA no picó nada?!', '', 28153),
(161192, 'esMX', 'He sido testigo de muchos momentos trascendentales. He contemplado el desarrollo de la historia, he visto la resolución de los conflictos y su resurgimiento, he visto traiciones y grandes victorias.\n\nEsta es una derrota como cualquier otra. Zul siempre estuvo un paso delante de nosotros y alcanzó su objetivo más importante. No podemos dejar que este sea el fin.\n\nEl conflicto incipiente contra este enemigo ancestral, un enemigo al que este pueblo se ha enfrentado desde los albores de su raza, definirá el destino de la Horda y los zandalari. Tenemos que responder a su llamado. Tenemos que enderezar lo que torció Zul.\n\nPrepárate, no bajes la guardia y anda con cuidado, $n.', '', 28153),
(161191, 'esMX', '', 'Temía no poder entregar estos suministros a tu ejército. Gracias, y por favor llévate estos recursos como recompensa.', 28153),
(161190, 'esMX', 'No sé en qué estará pensando el rey zandalari en este momento. Lo que sé es que no podemos dejar que estos acontecimientos nos alejen de nuestro objetivo. Los zandalari deben sobrevivir a este conflicto. La Horda ha jurado defender a esta gente con sus espadas, y es posible que tengamos que defenderlos en soledad si sus dioses no los salvan.\n\nAhora más que nunca, todos los ojos estarán puestos en ti. Represéntanos bien, portavoz de la Horda.', '', 28153),
(161189, 'esMX', '', 'Ah, guau, pensé que estaba bien muerta. ¡Pero apareciste tú! Solo por eso, mejoraré la armadura de tu ejército. ¡Gracias!', 28153),
(161188, 'esMX', '¿Te gusta la magia y las tierras lejanas? ¿O acaso la guerra te llevará lejos por un tiempo?\n\nSi estás buscando los portales a Ciudad de Ventormenta, Forjaz y el Exodar, los encontrarás en la parte baja del Mercado Vientos Alisios, en la zona sur. Busca la cámara que está junto a ese extraño transfigurador etéreo.', '¿Te gusta la magia y las tierras lejanas? ¿O acaso la guerra te llevará lejos por un tiempo?\n\nSi estás buscando los portales a Ciudad de Ventormenta, Forjaz y el Exodar, los encontrarás en la parte baja del Mercado Vientos Alisios, en la zona sur. Busca la cámara que está junto a ese extraño transfigurador etéreo.', 28153),
(161187, 'esMX', '', 'Tengo que conservar la esperanza. Jaina puede estar viva todavía.', 28153),
(161186, 'esMX', 'Veo la oscuridad en tus ojos. El próximo intento te destrozará la mente y te transformarás en otro de los fantasmas que me persiguen.$b$bNo estás $Ulisto:lista;. Regresa cuando lo estés y te estará esperando tu próxima tarea. La corrupción lleva una eternidad creciendo y supurando. Unos días más no serán de gran importancia.', '', 28153),
(161185, 'esMX', 'Encontré esta pista en las oficinas de Aspafresno.', 'Encontré esta pista en las oficinas de Aspafresno.', 28153),
(161184, 'esMX', 'Así que finalmente te decidiste a salvarme, ¿eh? Bueno, supongo que te debo una. Tal vez pueda pagarte mejorando las armas de tu ejército.', '', 28153),
(161183, 'esMX', '', 'Me niego a creer que Jaina está muerta.', 28153),
(161181, 'esMX', 'Ah, ¡esta kolsch de Vientos Alisios es deliciosa! ¡Nunca me canso de beberla!\n\n¡Me tomaré esta de un trago e iré a buscar otra!', '', 28153),
(161180, 'esMX', 'Me encanta la cerveza que hacen aquí. ¡Es de mis favoritas!\n\n¡Salud!', '', 28153),
(161179, 'esMX', '¡$UBienvenido:Bienvenida; a nuestra cervecería!\n\nEspero que disfrutes las cervezas que tenemos para ofrecer. Si buscas comprar barriles para un evento, avísame.\n\nMientras tanto, ¿por qué no disfrutas un vaso?', '', 28153),
(161178, 'esMX', '¡Allí estás! Las fuerzas de Zul trataron de expulsarnos, pero la Horda ha demostrado su fuerza. Por ahora, la lucha ha terminado.\n\nTeníamos razones para sospechar que Zul estaba complotando en nuestra contra. Nunca pensé que actuaría tan pronto ni con tanta firmeza. Supongo que sus habilidades como profeta no fueron exageradas.\n\nTenemos que hacer algo para conservar a nuestros nuevos aliados. Ve y haz todo lo que esté a tu alcance para que el rey Rastakhan vuelva al poder. La Horda mantendrá el orden aquí.', '', 28153),
(161177, 'esMX', 'El primer poder que se sentó sobre eh\'te trono gobernó a toda la gente civilizada de este mundo.\n\nY míranos ahora... Todo nueh\'tro poder encerrado en una sola isla. Hasta los trols inferiore\' desafían nuestro poder.\n\nEsto cambiará.', '', 28153),
(161176, 'esMX', '¿Llegaste en ese barco nuevo? ¡Tomemos una cerveza y cuéntame todo sobre la arquitectura de su estructura!', '', 28153),
(161175, 'esMX', '¡Otro día, otra cerveza!\n\n¿Cuál es tu tipo favorito?', '', 28153),
(161174, 'esMX', '¿Hace falta arreglar algo?', '', 28153),
(161173, 'esMX', '¡A beber!', '', 28153),
(161172, 'esMX', 'Mi hija cree que las amenaza\' contra Nazmir son tan grande\' que tenemos que enviar a nueh\'tro ejército entero a la frontera septentrional.\n\nPero ella es joven e impaciente, no entiende que los trols de sangre han fastidiado a nueh\'tro pueblo durante generacione\'.\n\nSi cree que la Horda puede ayudarla, quisiera ver qué puedes lograr tú. Le vendría bien un poco de experiencia en lidiar con poderes foráneo\'.\n\nDebes saber que, si le llegara a pasar algo, reduciré a cenizas a toda la Horda y convertiré a esa patética colección de botes de remo en basura marina.\n\nBuena suerte.', '', 28153),
(161171, 'esMX', '¡A la salud de todos!', '', 28153),
(161170, 'esMX', 'En cuanto termine mi trago, iré hacia allá y los ayudaré con eso.', '', 28153),
(161169, 'esMX', '¡Malfurion ha enviado un mensaje que dice que la Legión Ardiente ataca Costa Quebrada!', '', 28153),
(161168, 'esMX', 'Tyrande y yo éramos pareja antes de que conociera a Mildred aquí.', '', 28153),
(161167, 'esMX', 'Puse manos a la obra de inmediato, ¡y salvé todos los barriles de ron!', '', 28153),
(161166, 'esMX', 'El bote se hundió, todos se ahogaban, treinta barriles de ron de Tiragarde se fueron directo al fondo del mar.', '', 28153),
(161165, 'esMX', 'No hay ni una cerveza decente en la Arboleda de los Sueños. Por eso nunca voy.', '', 28153),
(161164, 'esMX', '¡Todos a bordo! ¡Nos vamos a Zuldazar!', '', 28153),
(161163, 'esMX', '¡Todos a bordo! ¡Nos vamos a las Islas del Eco!', '', 28153),
(161162, 'esMX', 'No temas las mareas de guerra que se acercan, $p. Solo cuando nos ponemos a prueba de verdad salimos fortalecidos.', '', 28153),
(161161, 'esMX', '¡Tienes que convencer al rey de que me envíe a un clima más templado!', '', 28153),
(161160, 'esMX', 'El conflicto recién empieza, $p. Espero que estés $Upreparado:preparada; para las pruebas de la guerra.', '', 28153),
(161159, 'esMX', 'Si quieren que trabaje aquí, creo tendré que pedir un aumento. ¡Pago adicional por peligro, $r! ¡Pago adicional por peligro!', '', 28153),
(161158, 'esMX', 'Me prenderé fuego si me siguen picando más insectos en regiones abisales. ¡Odio este lugar!', '', 28153),
(161157, 'esMX', 'Que la Horda nos envíe sus guerreros más fuertes. Nada me gustaría más que probar mi espada contra un adversario digno.', '', 28153),
(161156, 'esMX', '¡Ah! ¡Qué calor! ¿Ves las gotas de sudor que corren por mi barba?', '', 28153),
(161155, 'esMX', 'Si ves una posibilidad de dar una mano, hazlo. No hay necesidad de esperar a recibir permiso en estos tiempos aciagos.', '', 28153),
(161154, 'esMX', 'No te preocupes, esta es una de las naves más rápidas de Zandalar. Te llevaremos a destino.', '', 28153),
(161153, 'esMX', 'Si queremos eliminar a la Horda, debemos ser astutos y precisos. No hay lugar para equivocarse.', '', 28153),
(161152, 'esMX', '¡Estamos llegando a las Islas del Eco!', '', 28153),
(161151, 'esMX', '¡Estamos llegando a Zuldazar!', '', 28153),
(161150, 'esMX', 'Acabo de ordenar los barriles de cervezas más claras a más oscuras.\n\n¿Pero quizá sea mejor el orden alfabético? ¿Por fecha?', '', 28153),
(161149, 'esMX', '', 'Hola, cariño. ¿Buscas un compañero leal? ¿Una mascota para abrazar en las noches tormentosas? ¿Un mejor amigo para compartir las alegrías y dificultades de la vida?', 28153),
(161148, 'esMX', 'Mmm... me recuerda... cuando aprendí a minar... Secott siempre me decía... el truco eh\'taba... en golpear con el pico a cierto ángulo... para que... la mena...', '¡Puaj! Demasiada fruta del sol...', 28153),
(161147, 'esMX', 'Gracias, comandante. ¡Habríamos muerto si no nos hubiese salvado! ¡Volveremos a nuestros puestos de inmediato!', '', 28153),
(161146, 'esMX', 'Tenía gusto a \"mula\", sí.', 'Tenía gusto a \"mula\", sí.', 28153),
(161145, 'esMX', 'Veo nuestra victoria.', 'Veo nuestra victoria.', 28153),
(161144, 'esMX', 'Siempre odié este bosque.', 'Siempre odié este bosque.', 28153),
(161143, 'esMX', '¿Eso era...? ¿Era un cubo de agua podrida?', '¿Eso era...? ¿Era un cubo de agua podrida?', 28153),
(161142, 'esMX', 'Capturaremos el árbol.', 'Capturaremos el árbol.', 28153),
(161141, 'esMX', '¡Mmruf! ¡Ahh, odio el gin, colega!', '¡Mmruf! ¡Ahh, odio el gin, colega!', 28153),
(161140, 'esMX', '', 'La nave ya debe haber dejado Zandalar, tendría que eh\'tar en camino hacia aquí en eh\'te preciso momento.', 28153),
(161139, 'esMX', 'Al menos he muerto en batalla.', 'Al menos he muerto en batalla.', 28153),
(161138, 'esMX', '', 'Ha cruzado todo el océano hacia Zandalar. Volverá pronto, no te preocupe\'.', 28153),
(161137, 'esMX', 'No eres más que una molestia.', 'No eres más que una molestia.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161136, 'esMX', 'Eso tenía guh\'to a muerte, colega.', 'Eso tenía guh\'to a muerte, colega.', 28153),
(161135, 'esMX', '', 'La nave acaba de partir a Zandalar. Volverá dentro de muy poco.', 28153),
(161134, 'esMX', '', 'Está aquí mih\'mo, frente a ti. ¡Vamos!', 28153),
(161133, 'esMX', 'Agh, ¿qué es eh\'to? ¿Vino tortollano?', 'Agh, ¿qué es eh\'to? ¿Vino tortollano?', 28153),
(161132, 'esMX', 'Recomiendo acompañar nuestra porter Punta Garfio con unas semillas de azotador rostizadas.\n\nNo te dejes engañar por las semillas. Los sabores con tonos tostados y asados de las semillas de azotador armonizan muy bien con el sabor profundo de la malta. Puede parecer una extraña pareja, pero, por las mareas, es una de mis preferidas.', '', 28153),
(161131, 'esMX', '¡Puaj! Demasiada fruta del sol...', '¡Puaj! Demasiada fruta del sol...', 28153),
(161130, 'esMX', 'Recomiendo nuestra cerveza rubia con pátina para acompañar un plato que alimenta el corazón, mi favorito: el pollo especiado del Coronel Tenders.\n\nEl ligero sabor a miel de la cerveza hace un equilibrio maravilloso con el pollo especiado. ¡Y limpia el paladar con el efecto del trigo cuando el picante abruma!', '', 28153),
(161129, 'esMX', '¡Hola! ¿Viniste a ver mi colección?', '', 28153),
(161128, 'esMX', 'Les imploro que sigan su ejemplo. Sean flexibles para no quebrarse. ¡Y arrojen a sus enemigo\' sobre una roca cuando terminen con ellos!', 'Les imploro que sigan su ejemplo. Sean flexibles para no quebrarse. ¡Y arrojen a sus enemigo\' sobre una roca cuando terminen con ellos!', 28153),
(161127, 'esMX', '', 'No e\' seguro, pero parece que hay una tormenta en el horizonte.', 28153),
(161126, 'esMX', 'Los viento\' traen más tormenta\' y comercio. Traen cambio. Cambio que Pa\'ku nos ha enseñado a capear.', 'Los viento\' traen más tormenta\' y comercio. Traen cambio. Cambio que Pa\'ku nos ha enseñado a capear.', 28153),
(161125, 'esMX', 'Y yo que... *¡hip!* justo estaba pensando en beber algo...', 'Y yo que... *¡hip!* justo estaba pensando en beber algo...', 28153),
(161124, 'esMX', '¡Ya has perdido!', '¡Ya has perdido!', 28153),
(161123, 'esMX', '¡Tomaremos lo que es nuestro!', '¡Tomaremos lo que es nuestro!', 28153),
(161122, 'esMX', 'Desconfíen de las palabra\' maliciosas de los que se quebraron ante la tormenta. Atiendan, en cambio, las de los que, por ser flexibles, resistieron.', 'Desconfíen de las palabra\' maliciosas de los que se quebraron ante la tormenta. Atiendan, en cambio, las de los que, por ser flexibles, resistieron.', 28153),
(161121, 'esMX', '¿Qué tienes?', '¿Qué tienes?', 28153),
(161120, 'esMX', 'Dijeron que e\' lasciva, rápida para enfadarse y caprichosa. Pero yo los desafío a mirar más de cerca.', 'Dijeron que e\' lasciva, rápida para enfadarse y caprichosa. Pero yo los desafío a mirar más de cerca.', 28153),
(161119, 'esMX', 'Tienes el honor de morir en mis manos.', 'Tienes el honor de morir en mis manos.', 28153),
(161118, 'esMX', '¿Bebida gratis?', '¿Bebida gratis?', 28153),
(161117, 'esMX', 'Más vale que eh\'to valga la pena...', 'Más vale que eh\'to valga la pena...', 28153),
(161116, 'esMX', 'Sus viento\' traen las lluvia\', impulsan nueh\'tras vela\' y envían nueh\'tra nave\' a surcar los mares. ¡Su fuerza es la que nos hace lo que somos!', 'Sus viento\' traen las lluvia\', impulsan nueh\'tras vela\' y envían nueh\'tra nave\' a surcar los mares. ¡Su fuerza es la que nos hace lo que somos!', 28153),
(161115, 'esMX', 'Recomiendo nuestra pilsner flotante para acompañar nuestro enérgico bacalao salado.\n\nLa destacada amargura de la cerveza contrasta agradablemente con la dulzura del bacalao, mientras que el lúpulo le da un toque especiado que se complementa con el característico sabor salado del pescado.', '', 28153),
(161114, 'esMX', '', '¿Vas a Zandalar? Allí va la nave de eh\'te muelle, colega.', 28153),
(161113, 'esMX', 'Allí voy, mi amor...', 'Allí voy, mi amor...', 28153),
(161112, 'esMX', 'Ofrecer Mula amani', 'Ofrecer Mula amani', 28153),
(161111, 'esMX', 'Ofrecer Jugo de Jani', 'Ofrecer Jugo de Jani', 28153),
(161110, 'esMX', 'Ofrecer Mojo\'ito', 'Ofrecer Mojo\'ito', 28153),
(161109, 'esMX', 'Ofrecer Gin de Zul', 'Ofrecer Gin de Zul', 28153),
(161108, 'esMX', 'Ofrecer Bwonzombi', 'Ofrecer Bwonzombi', 28153),
(161107, 'esMX', 'Ofrecer Puñetazo de las grutas', 'Ofrecer Puñetazo de las grutas', 28153),
(161106, 'esMX', 'Recomiendo acompañar nuestra dunkel de anclaje fuerte con un queso marrón de Vadoarlén.\n\nMe encanta un buen maridaje de cerveza y queso, y estos dos combinan a la perfección. Los dos tienen un suave gusto a caramelo, y cuando están juntos se resalta lo mejor de ambos.', '', 28153),
(161105, 'esMX', 'Ofrecer Azotatrols', 'Ofrecer Azotatrols', 28153),
(161104, 'esMX', 'Que la muerte te lleve...', 'Que la muerte te lleve...', 28153),
(161103, 'esMX', '', 'Mis mascotas solo se hacen más fuertes cuando un aliado cae en batalla.', 28153),
(161102, 'esMX', '¿Por qué las aves están tan silenciosas?', '¿Por qué las aves están tan silenciosas?', 28153),
(161101, 'esMX', 'Lady Tyrande te detendrá.', 'Lady Tyrande te detendrá.', 28153),
(161100, 'esMX', '', 'Las especies de Zandalar tienen un poder sin igual. El resto de tus mascotas no tienen la menor oportunidad.', 28153),
(161099, 'esMX', 'Nunca acorrales a un sable de la noche herido...', 'Nunca acorrales a una sable de la noche herida...', 28153),
(161098, 'esMX', '¡Esta tierra es nuestra!', '¡Esta tierra es nuestra!', 28153),
(161097, 'esMX', '', 'Qué inesperado. La próxima vez que nos encontremos ganaré, $uextraño:extraña;.', 28153),
(161096, 'esMX', '', 'Parece que en mi terruño llevo la ventaja.', 28153),
(161095, 'esMX', 'Hasta aquí llega el honor.', 'Hasta aquí llega el honor.', 28153),
(161094, 'esMX', '', '¿Te atreves a desafiarme en mi propia casa? Buena suerte.', 28153),
(161093, 'esMX', 'No quiero matarte, pero lo haré.', 'No quiero matarte, pero lo haré.', 28153),
(161092, 'esMX', '', 'Tal vez esta no sea la especie nueva más fuerte que hay aquí. Debería seguir buscando mejores cosas para capturar.', 28153),
(161091, 'esMX', '¡Te recomiendo acompañar nuestra berlinesa de bayas de nieve ni más ni menos que con una natilla de bayas de nieve!\n\nCon este maridaje, sentirás las dos facetas de sabor de la baya de nieve: el amargor de la cerveza y la dulzura delicada de la natilla. La cremosidad de la natilla contrarresta la aspereza de la cerveza y te embarca en una mágica aventura de sabores.', '', 28153),
(161090, 'esMX', '', 'Seguramente deje una cicatriz.', 28153),
(161089, 'esMX', '', 'Necesito más tiempo para entrenar con estas especies nuevas. Seré más fuerte en la próxima batalla.', 28153),
(161088, 'esMX', '', 'Como dije antes, las criaturas de esta tierra son feroces. Como sea, buena pelea.', 28153),
(161087, 'esMX', '', 'En esta tierra las criaturas son feroces. Espero que estés $listo:lista; para esto.', 28153),
(161086, 'esMX', '', 'No te preocupes, criaturita, yo te cuidaré.', 28153),
(161085, 'esMX', 'Todo debe morir.', 'Todo debe morir.', 28153),
(161084, 'esMX', '', 'No estés triste por esta pérdida, el resto de tus mascotas parecen muy fuertes.', 28153),
(161083, 'esMX', 'Solo quería proteger mi hogar.', 'Solo quería proteger mi hogar.', 28153),
(161082, 'esMX', '', 'Parece que perdí la práctica.', 28153),
(161081, 'esMX', 'Espero soñar...', 'Espero soñar...', 28153),
(161080, 'esMX', '', 'Cielos, parece que tenía un equipo más fuerte de lo que pensaba.', 28153),
(161079, 'esMX', 'Las hojas caen...', 'Las hojas caen...', 28153),
(161078, 'esMX', 'Ojalá tuviera tiempo de matarte lentamente.', 'Ojalá tuviera tiempo de matarte lentamente.', 28153),
(161077, 'esMX', '', 'Hace mucho que no peleo. Espero que todavía sea una buena contrincante para ti.', 28153),
(161076, 'esMX', '¡Prueba mis garras!', '¡Prueba mis garras!', 28153),
(161075, 'esMX', '¡Las espinas te atravesarán!', '¡Las espinas te atravesarán!', 28153),
(161074, 'esMX', '', '¡No estaba lista, no vale!', 28153),
(161073, 'esMX', '¡Vengaré a los bosques!', '¡Vengaré a los bosques!', 28153),
(161072, 'esMX', '', 'Parece que mi racha ganadora seguirá.', 28153),
(161071, 'esMX', 'Recomiendo acompañar nuestra kolsch de Vientos Alisos con mi hogaza de centeno y comino casera\n\nEl tono panificado de la cerveza se combina muy bien con el sabor terroso de la hogaza, que además limpia el paladar por su efecto de carbonación.', '', 28153),
(161070, 'esMX', '', 'Esto no cuenta como un fracaso. Mi racha ganadora sigue.', 28153),
(161069, 'esMX', '', '¡Hurra! ¡Mi racha ganadora sigue!', 28153),
(161068, 'esMX', '', 'Tengo una racha ganadora, tú no tienes ninguna oportunidad contra mí y mi equipo.', 28153),
(161067, 'esMX', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|tEl avatar ya no está  |cFFFF0000|Hspell:274148|h[Maculado]|h|r, ¡tus sanaciones ya son ciento por ciento efectivas!', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|tEl avatar ya no está  |cFFFF0000|Hspell:274148|h[Maculado]|h|r, ¡tus sanaciones ya son ciento por ciento efectivas!', 28153),
(161066, 'esMX', 'No te acobardes ante la posibilidad de la derrota: ponte a la altura del desafío, si puedes.', '', 28153),
(161065, 'esMX', 'Quisiera comprar algo para comer.', 'Quisiera comprar algo para comer.', 28153),
(161064, 'esMX', 'La victoria está al alcance de mi mano, casi la palpo.', '', 28153),
(161063, 'esMX', 'Den gracias a Gonk, corran con su manada y sepan que los demá\' camino\' también permanecerán abierto\' para ustede\'. Eh\'te es su regalo a los zandalari.', 'Den gracias a Gonk, corran con su manada y sepan que los demá\' camino\' también permanecerán abierto\' para ustede\'. Eh\'te es su regalo a los zandalari.', 28153),
(161062, 'esMX', 'Pero Gonk e\' sabio, y sabe que somos más fuerte\' cuando estamo\' junto que cuando estamo\' separados. Él no exige que su ídolo eh\'té solo en sus altare\'.', 'Pero Gonk e\' sabio, y sabe que somos más fuerte\' cuando estamo\' junto que cuando estamo\' separados. Él no exige que su ídolo eh\'té solo en sus altare\'.', 28153),
(161061, 'esMX', '¿Qué me recomiendas para acompañar una porter Punta Garfio?', '¿Qué me recomiendas para acompañar una porter Punta Garfio?', 28153),
(161060, 'esMX', 'Sorprendente. Hace años que no pierdo una batalla. ¡Buena pelea!', '', 28153),
(161059, 'esMX', 'Con un poco más de práctica serás un gran desafío incluso para mí. Sigue así.', '', 28153),
(161058, 'esMX', '¿Qué me recomiendas para acompañar una cerveza rubia con pátina?', '¿Qué me recomiendas para acompañar una cerveza rubia con pátina?', 28153),
(161057, 'esMX', '¿Qué me recomiendas para acompañar una pilsner flotante?', '¿Qué me recomiendas para acompañar una pilsner flotante?', 28153),
(161056, 'esMX', '¿Qué me recomiendas para acompañar una dunkel de anclaje fuerte?', '¿Qué me recomiendas para acompañar una dunkel de anclaje fuerte?', 28153),
(161055, 'esMX', '¿Qué me recomiendas para acompañar una berlinesa de bayas de nieve?', '¿Qué me recomiendas para acompañar una berlinesa de bayas de nieve?', 28153),
(161054, 'esMX', '¿Qué me recomiendas para acompañar una kolsch de Vientos Alisos?', '¿Qué me recomiendas para acompañar una kolsch de Vientos Alisos?', 28153),
(161053, 'esMX', 'Los otro\' loa, al principio, se enfadaron. Lo escupieron, dijeron que era caprichoso y débil por aceptar menos de lo que le correspondía.', 'Los otro\' loa, al principio, se enfadaron. Lo escupieron, dijeron que era caprichoso y débil por aceptar menos de lo que le correspondía.', 28153),
(161052, 'esMX', 'Y dijo a sus seguidore\': \"Pueden elegir el camino correcto para ustedes. Todos somo\' una manada ante mis ojo\'\".', 'Y dijo a sus seguidore\': \"Pueden elegir el camino correcto para ustedes. Todos somo\' una manada ante mis ojo\'\".', 28153),
(161051, 'esMX', '¿Buscas un plato delicioso que combine bien con tu cerveza?\n\nTengo justo lo que necesitas.', '', 28153),
(161050, 'esMX', 'El loa de las forma\' observó a su gente y vio que tenían muchas necesidade\'. Necesidade\' que él no podía saciar.', 'El loa de las forma\' observó a su gente y vio que tenían muchas necesidade\'. Necesidade\' que él no podía saciar.', 28153),
(161049, 'esMX', 'Reflexionen sobre eh\'to, hermanos y hermanas. Elijan con sabiduría.', 'Reflexionen sobre eh\'to, hermanos y hermanas. Elijan con sabiduría.', 28153),
(161048, 'esMX', '¿O se sentirán atormentado\' hasta que el sol se oscurezca en los cielo\'...?', '¿O se sentirán atormentado\' hasta que el sol se oscurezca en los cielo\'...?', 28153),
(161047, 'esMX', '¿Compartirán su risa? ¿Bailarán junto a los otro\' que han muerto agradecido\'?', '¿Compartirán su risa? ¿Bailarán junto a los otro\' que han muerto agradecido\'?', 28153),
(161046, 'esMX', 'Cuando llegue el momento y su eh\'píritu atraviese el velo para pasar hacia el Otro Lado, ¿será Bwonsamdi su amigo?', 'Cuando llegue el momento y su eh\'píritu atraviese el velo para pasar hacia el Otro Lado, ¿será Bwonsamdi su amigo?', 28153),
(161045, 'esMX', 'Pero debo recordarles algo. Bwonsamdi también observa el mundo de los vivo\'. Nos vigila. Nos mide.', 'Pero debo recordarles algo. Bwonsamdi también observa el mundo de los vivo\'. Nos vigila. Nos mide.', 28153),
(161044, 'esMX', 'Pero como eh\'toy vivo, ustede\' pensarán que no hay lugar en mi altar para semejante loa. Aún no.', 'Pero como eh\'toy viva, ustede\' pensarán que no hay lugar en mi altar para semejante loa. Aún no.', 28153),
(161043, 'esMX', 'Krag\'wa ha regresado y eh\'tas son las leccione\' que trajo para los zandalari.', 'Krag\'wa ha regresado y eh\'tas son las leccione\' que trajo para los zandalari.', 28153),
(161042, 'esMX', 'Quienes buh\'can valor, fortaleza para proteger a otros, voluntad para continuar, ya pueden dejar de buh\'car.', 'Quienes buh\'can valor, fortaleza para proteger a otros, voluntad para continuar, ya pueden dejar de buh\'car.', 28153),
(161041, 'esMX', 'Tomen su ejemplo al pie de la letra, hermanos y hermanas. La convicción de proteger lo que e\' suyo e\' una poderosa bendición.', 'Tomen su ejemplo al pie de la letra, hermanos y hermanas. La convicción de proteger lo que e\' suyo e\' una poderosa bendición.', 28153),
(161040, 'esMX', 'Nos ha demostrado que incluso ante la amenaza de la nada sigue siendo fuerte para defender a los suyo\'.', 'Nos ha demostrado que incluso ante la amenaza de la nada sigue siendo fuerte para defender a los suyo\'.', 28153),
(161039, 'esMX', 'Hoy me encuentro ante ustede\' para decirles que el gran guardián ha vuelto con nosotro\' y que su fuerza eh\'tá intacta.', 'Hoy me encuentro ante ustede\' para decirles que el gran guardián ha vuelto con nosotro\' y que su fuerza eh\'tá intacta.', 28153),
(161038, 'esMX', 'Siempre valoro una buena batalla contra un adversario nuevo.', '', 28153),
(161037, 'esMX', 'Hora de traer más vendajes para mascotas', '', 28153),
(161036, 'esMX', 'Fue una buena pelea, chiquitín. Espero que te mejores.', '', 28153),
(161035, 'esMX', 'Diantres, odio perder. Buena pelea.', '', 28153),
(161034, 'esMX', 'Luego, cuando lleguen las tormentas, sabrán a ciencia cierta que es hora de comenzar de nuevo. No le tendrán miedo a las nube\' que se posan en el horizonte.', 'Luego, cuando lleguen las tormentas, sabrán a ciencia cierta que es hora de comenzar de nuevo. No le tendrán miedo a las nube\' que se posan en el horizonte.', 28153),
(161033, 'esMX', '¿Gané? ¡Excelente, les contaré a todos mis amigos sobre esto!', '', 28153),
(161032, 'esMX', '¡Hora de una gran aventura!', '', 28153),
(161031, 'esMX', 'Estos desafío\' ponen a prueba nuestra fuerza, nuestra determinación. Quienes aún eh\'tén de pie cuando las nube\' se hayan disipado serán más fuertes.', 'Estos desafío\' ponen a prueba nuestra fuerza, nuestra determinación. Quienes aún eh\'tén de pie cuando las nube\' se hayan disipado serán más fuertes.', 28153),
(161030, 'esMX', 'No importa, esa mascota era un poco escalofriante, no es una gran pérdida.', '', 28153),
(161029, 'esMX', 'Sí, los rayo\' están cargado\' de furia y los trueno\' de ira. Pero la agonía del cambio no es fácil.', 'Sí, los rayo\' están cargado\' de furia y los trueno\' de ira. Pero la agonía del cambio no es fácil.', 28153),
(161028, 'esMX', 'Los viento\' limpiarán la tierra y la dejarán lih\'ta para los próximos brote\'.', 'Los viento\' limpiarán la tierra y la dejarán lih\'ta para los próximos brote\'.', 28153),
(161027, 'esMX', 'Es mejor que te encargues de eso antes de que lo usen para algún ritual de sangre.', '', 28153),
(161026, 'esMX', 'Nos enseña a no tenerle miedo a la tormenta que se aproxima en el horizonte, porque la lluvia borrará las pena\' del pasado.', 'Nos enseña a no tenerle miedo a la tormenta que se aproxima en el horizonte, porque la lluvia borrará las pena\' del pasado.', 28153),
(161025, 'esMX', 'Este lugar está maldito, nunca pierdo de esa manera.', '', 28153),
(161024, 'esMX', 'Fue una pelea buena, pero no eres un contrincante digno para mí.', '', 28153),
(161023, 'esMX', 'Este lugar es espeluznante, hagamos que esta batalla termine rápido.', '', 28153),
(161022, 'esMX', '¡Monstruo! ¡Era mi mascota favorita!', '', 28153),
(161021, 'esMX', 'Otro que muerde el polvo.', '', 28153),
(161020, 'esMX', '¡Ven a verme si necesitas un trago!\n\nAunque si quieres un vuelo, pregúntale a otra persona. Por mi cordura.', '', 28153),
(161019, 'esMX', '', '¡Seguro! Aquí tienes.', 28153),
(161018, 'esMX', '¡Odio perder! Seré más fuerte la próxima vez; no lo dudes ni un segundo.', '', 28153),
(161017, 'esMX', '¿Tienes una cubeta para leche de más?', '¿Tienes una cubeta para leche de más?', 28153),
(161016, 'esMX', 'Otra victoria para el mejor equipo... ¡el mío!', '', 28153),
(161015, 'esMX', '¡Hora de luchar! ¡Que empiece la acción!', '', 28153),
(161014, 'esMX', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t¡Empiezan a |cFFFF0000|Hspell:269688|h[llover]|h|r sapos del cielo!', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t¡Empiezan a |cFFFF0000|Hspell:269688|h[llover]|h|r sapos del cielo!', 28153),
(161013, 'esMX', '', 'Eres muy $Ubien parecido:bonita;, ¿sabes?', 28153),
(161012, 'esMX', '', 'Si en algún momento puedo ayudarte con algo, ¡no dudes en preguntármelo!', 28153),
(161011, 'esMX', '', 'Cuando alguien cae en batalla, los demás se fortalecen para luchar más duro aún.', 28153),
(161010, 'esMX', '', 'No sé cómo agradecerte que hayas rescatado a Millie.', 28153),
(161009, 'esMX', '', 'Saludos, $p. Siempre es bueno verte.', 28153),
(161008, 'esMX', '', '¡Ja! ¡Uno menos!', 28153),
(161007, 'esMX', '', 'Entrenaré y estaré preparada para la próxima vez que nos enfrentemos.', 28153),
(161006, 'esMX', '', 'No te sientas mal por la derrota; aprende de tus errores y vuelve a plantarle cara al desafío.', 28153),
(161005, 'esMX', '', '¡Ya era hora de que llegaran unos brazos fuertes para ayudarnos!', 28153),
(161004, 'esMX', '', 'Luchemos con honor, $uforastero:forastera;.', 28153),
(161003, 'esMX', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tUn fragmento de energía se forma cerca. ¡Úsalo para |cFFFF0000|Hspell:274149|h[energizar]|h|r al avatar!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tUn fragmento de energía se forma cerca. ¡Úsalo para |cFFFF0000|Hspell:274149|h[energizar]|h|r al avatar!', 28153),
(161002, 'esMX', '<Darle un momento a Genn para que hable con Katherine.>', '<Darle un momento a Genn para que hable con Katherine.>', 28153),
(161001, 'esMX', '¡Es nuestra oportunidad!', '¡Es nuestra oportunidad!', 28153),
(161000, 'esMX', '¡Tomen sus cosas, rápido!', '¡Tomen sus cosas, rápido!', 28153),
(160999, 'esMX', '¡Vamos!', '¡Vamos!', 28153),
(160998, 'esMX', '¡Vamos, salgamos de aquí!', '¡Vamos, salgamos de aquí!', 28153),
(160997, 'esMX', 'Un guardián se forma cerca para proteger el Corazón de Sethraliss.', 'Un guardián se forma cerca para proteger el Corazón de Sethraliss.', 28153),
(160996, 'esMX', 'Los seguidores de Jakra\'zet arremeten contra el Corazón de Sethraliss.', 'Los seguidores de Jakra\'zet arremeten contra el Corazón de Sethraliss.', 28153),
(160995, 'esMX', '¡En la naturaleza hay osos, lobos y cabras que muerden!', '', 28153),
(160994, 'esMX', 'Creo que eres fascinante, pero respeto tu distancia.', '', 28153),
(160993, 'esMX', 'No quiero herir al animal, solo quiero darle una advertencia.', '', 28153),
(160992, 'esMX', 'Pero también debes tener precaución, por eso siempre salgo armado.', '', 28153),
(160991, 'esMX', 'Un dato curioso: pasear por la naturaleza es una de las actividades más fascinantes que existen.', '', 28153),
(160990, 'esMX', 'Y esto que vemos aquí es un pino. ¡Puedes identificarlo por su forma de pino!', '', 28153),
(160989, 'esMX', 'Dato curioso sobre las cascadas: ¡El agua siempre cae de arriba hacia abajo!', '', 28153),
(160988, 'esMX', 'Las cascadas son majestuosas... e imponentes.', '', 28153),
(160987, 'esMX', 'Esto que vemos aquí se llama cascada.', '', 28153),
(160986, 'esMX', '¿No es fascinante?', '', 28153),
(160985, 'esMX', '¡Vaya, qué belleza!', '', 28153),
(160984, 'esMX', 'Y así el señor de las bestias enseñó a sus seguidores las virtudes de la valentía y la convicción.', 'Y así el señor de las bestias enseñó a sus seguidores las virtudes de la valentía y la convicción.', 28153),
(160983, 'esMX', 'Pero la fuente del poder no reside en la fuerza, sino en una voluntad irrefrenable que el tiempo es incapaz de domar.', 'Pero la fuente del poder no reside en la fuerza, sino en una voluntad irrefrenable que el tiempo es incapaz de domar.', 28153),
(160982, 'esMX', 'Así como las flores de la selva se marchitan con el paso del tiempo, la edad devora la fuerza de la juventud.', 'Así como las flores de la selva se marchitan con el paso del tiempo, la edad devora la fuerza de la juventud.', 28153),
(160981, 'esMX', 'Actúen con valentía frente a todo y no perderán de vista a su presa.', 'Actúen con valentía frente a todo y no perderán de vista a su presa.', 28153),
(160980, 'esMX', 'Así como un tigre atraviesa roca y abismo de un salto durante la caza, el valeroso no pierde tiempo agazapándose frente al temor.', 'Así como un tigre atraviesa roca y abismo de un salto durante la caza, el valeroso no pierde tiempo agazapándose frente al temor.', 28153),
(160979, 'esMX', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 28153),
(160978, 'esMX', 'Y así el rey de los felinos enseñó a sus seguidores la virtudes de la dedicación.', 'Y así el rey de los felinos enseñó a sus seguidores la virtudes de la dedicación.', 28153),
(160977, 'esMX', 'Vivan con determinación inquebrantable y los golpes jamás los vencerán.', 'Vivan con determinación inquebrantable y los golpes jamás los vencerán.', 28153),
(160976, 'esMX', 'Así como la corriente incesante de agua da forma los cañones, los grandes actos nacen de la perseverancia.', 'Así como la corriente incesante de agua da forma los cañones, los grandes actos nacen de la perseverancia.', 28153),
(160975, 'esMX', 'Vivan con honor y tendrán una vida plena.', 'Vivan con honor y tendrán una vida plena.', 28153),
(160974, 'esMX', 'Así como un rey no entrega sus más grandes tesoros a cambio de un puñado de tierra, los honorables no negocian su integridad por riquezas ni por fama.', 'Así como un rey no entrega sus más grandes tesoros a cambio de un puñado de tierra, los honorables no negocian su integridad por riquezas ni por fama.', 28153),
(160973, 'esMX', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 28153),
(160972, 'esMX', 'Y así la perdición de las presa\' enseñó a sus seguidores las virtude\' de la paciencia y el respeto.', 'Y así la perdición de las presa\' enseñó a sus seguidores las virtude\' de la paciencia y el respeto.', 28153),
(160971, 'esMX', 'Y estos individuos son quienes respetan el orden natural y toman solo lo que necesitan para vivir.', 'Y estos individuos son quienes respetan el orden natural y toman solo lo que necesitan para vivir.', 28153),
(160970, 'esMX', 'Los iluminados comprenden que la naturaleza no les pertenece; más bien a la inversa.', 'Los iluminados comprenden que la naturaleza no les pertenece; más bien a la inversa.', 28153),
(160969, 'esMX', 'Así como la selva concede el don de la vida, puede arrebatarla en un instante.', 'Así como la selva concede el don de la vida, puede arrebatarla en un instante.', 28153),
(160968, 'esMX', 'Los necios pasan por la vida motivados por la ansiedad y la emoción, mas no sobreviven mucho tiempo en la jungla.', 'Los necios pasan por la vida motivados por la ansiedad y la emoción, mas no sobreviven mucho tiempo en la jungla.', 28153),
(160967, 'esMX', 'Del mismo modo que el jaguar acecha a su presa durante varios días, el sabio actúa con paciencia en todos los asunto\'.', 'Así como el jaguar acecha a su presa durante varios días, el sabio actúa con paciencia en toda empresa.', 28153),
(160966, 'esMX', '¡No solo sobrevivir, también prosperar! Les digo, ¡vayan! Vivan en las alcantarilla\' con la frente en alto, pues ese es el dominio de Jani.', '¡No solo sobrevivir, también prosperar! Les digo, ¡vayan! Vivan en las alcantarilla\' con la frente en alto, pues ese es el dominio de Jani.', 28153),
(160965, 'esMX', 'Jani no pide palabras difícile\' ni grandes sacrificio\'. Alabar a Jani es sobrevivir bajo las narices de quienes reprimen a los indeseado\'.', 'Jani no pide palabras difícile\' ni grandes sacrificio\'. Alabar a Jani es sobrevivir bajo las narices de quienes reprimen a los indeseado\'.', 28153),
(160964, 'esMX', '¡Jani no quita, Jani es generoso! Jani da a todos los que se sacrifican. A los que los grandioso\' y los ricachone\' dejan de lado.', '¡Jani no quita, Jani es generoso! Jani da a todos los que se sacrifican. A los que los grandioso\' y los ricachone\' dejan de lado.', 28153),
(160963, 'esMX', '¡Pero Jani es más poderoso que todos los demá\', y les diré por qué!', '¡Pero Jani es más poderoso que todos los demá\', y les diré por qué!', 28153),
(160962, 'esMX', 'Extienden sus mano\', ansían la adoración de su pueblo.', 'Extienden sus mano\', ansían la adoración de su pueblo.', 28153),
(160961, 'esMX', 'Thros... devora...', '', 28153),
(160960, 'esMX', 'No hay escapatoria...', '', 28153),
(160959, 'esMX', 'La esperanza está perdida...', '', 28153),
(160958, 'esMX', '¡Despellejen la carne!', '', 28153),
(160957, 'esMX', '¡Retuércete en agonía!', '', 28153),
(160956, 'esMX', '¡Eh\'cupo a tu loa ricachón!', '¡Eh\'cupo a tu loa ricachón!', 28153),
(160955, 'esMX', '¡Sufre!', '', 28153),
(160954, 'esMX', '¡Dispérsense!', '¡Dispérsense!', 28153),
(160953, 'esMX', '¡Jani es mi loa! ¡Ajaja!', '¡Jani es mi loa! ¡Ajaja!', 28153),
(160952, 'esMX', '¡Jani nos hará ricos!', '¡Jani nos hará ricos!', 28153),
(160951, 'esMX', '¡Basta de eh\'ta parranda ridícula! ¡Fuera!', '¡Basta de eh\'ta parranda ridícula! ¡Fuera!', 28153),
(160950, 'esMX', '¡Esto es una insolencia! ¡Fuera!', '¡Esto es una insolencia! ¡Fuera!', 28153),
(160949, 'esMX', '¡Estás faltando el respeto a los verdadero\' loa! ¡Saca esa basura de aquí!', '¡Estás faltando el respeto a los verdadero\' loa! ¡Saca esa basura de aquí!', 28153),
(160948, 'esMX', '¡Ese Jani inútil siempre hace desastre\'! ¡Fuera, fuera!', '¡Ese Jani inútil siempre hace desastre\'! ¡Fuera, fuera!', 28153),
(160947, 'esMX', 'Eso no servirá. ¡Toma el favor de mi loa!', 'Eso no servirá. ¡Toma el favor de mi loa!', 28153),
(160946, 'esMX', 'Quizás he llegado tarde...', 'Quizás he llegado tarde...', 28153),
(160945, 'esMX', 'Semejante devoción me hace llorar. ¿Contemplah\'te la generosidad del loa?', 'Semejante devoción me hace llorar. ¿Contemplah\'te la generosidad del loa?', 28153),
(160944, 'esMX', 'El ritual comenzará pronto, $n.\n\nNueh\'tro pueblo viaja desde todos los rincones de Zandalar para escuchar la sabiduría de su loa. Muchos vienen esperando que el loa les conceda su favor. ¡Quizá te lo concedan a ti!\n\nQuédate y celebra al loa con el pueblo zandalari.', 'El ritual comenzará pronto, $n.\n\nNueh\'tro pueblo viaja desde todos los rincones de Zandalar para escuchar la sabiduría de su loa. Muchos vienen esperando que el loa les conceda su favor. ¡Quizá te lo concedan a ti!\n\nQuédate y celebra al loa con el pueblo zandalari.', 28153),
(160943, 'esMX', 'Desearás... la muerte...', '', 28153),
(160942, 'esMX', '¡Tus alaridos serán eternos!', '', 28153),
(160941, 'esMX', 'No nos negarán... nuestra venganza...', '', 28153),
(160940, 'esMX', '¡Ella le pertenece a Gorak Tul!', '', 28153),
(160939, 'esMX', '¡Jamás te quedarás con nuestro premio!', '', 28153),
(160938, 'esMX', 'Tú estabas a mi lado en Entrañas. ¡Estaban acorralados! ¡La justicia estaba al alcance de mi mano!', '', 28153),
(160937, 'esMX', 'Ey, $Uhermano:hermana;, parece que necesitas un trago. ¿Quieres una cerveza?', '', 28153),
(160936, 'esMX', 'Acabo de empezar un tipo de cerveza nueva con miel de Canto Tormenta del primer nivel.\n\nPagamos una buena suma por ella, ¡pero creo con todo mi corazón que valdrá la pena!', '', 28153),
(160935, 'esMX', '', '¿Quieres una pinta? ¡También he preparado café si necesitas un poco de energía!', 28153),
(160934, 'esMX', '¡Seré un ricachón! ¡Uuu!', '¡Seré una ricachona! ¡Uuu!', 28153),
(160933, 'esMX', '¡Tu loa no pertenece aquí! ¡Largo!', '¡Tu loa no pertenece aquí! ¡Largo!', 28153),
(160932, 'esMX', '¡El dios de la basura les concede su favor! ¡Ajajaja!', '¡El dios de la basura les concede su favor! ¡Ajajaja!', 28153),
(160931, 'esMX', 'Algunos afirmarán que su loa es el más generoso, el más fuerte o el que se enfada más rápido.', 'Algunos afirmarán que su loa es el más generoso, el más fuerte o el que se enfada más rápido.', 28153),
(160930, 'esMX', '¡Ajajaja! ¡Es hora de alabar al loa de todos! ¡Vengan a los Peldaño\' de Dazar\'alor para celebrar a Jani!', '¡Ajajaja! ¡Es hora de alabar al loa de todos! ¡Vengan a los Peldaño\' de Dazar\'alor para celebrar a Jani!', 28153),
(160929, 'esMX', 'Si no se ha retrasado, la nave ha abandonado las Islas del Eco y llegará pronto.', '', 28153),
(160928, 'esMX', '¡Pueblo de Zandalar! ¡Es hora de venerar a la señora de los viento\', reina de los cielo\', matrona del mar! ¡Vengan a los peldaño\' y alaben a Pa\'ku!', '¡Pueblo de Zandalar! ¡Es hora de venerar a la señora de los viento\', reina de los cielo\', matrona del mar! ¡Vengan a los peldaño\' y alaben a Pa\'ku!', 28153),
(160927, 'esMX', 'Los que hoy eh\'tán frente a mí han sentido la bendición de Pa\'ku, mi loa.', 'Los que hoy eh\'tán frente a mí han sentido la bendición de Pa\'ku, mi loa.', 28153),
(160926, 'esMX', '¡Alabada sea Pa\'ku! ¡Que sus vientos inflen sus vela\'!', '¡Alabada sea Pa\'ku! ¡Que sus vientos inflen sus vela\'!', 28153),
(160925, 'esMX', '¡Gonk nos bendice con su favor! ¡Que la manada los acompañe siempre!', '¡Gonk nos bendice con su favor! ¡Que la manada los acompañe siempre!', 28153),
(160924, 'esMX', 'Les doy la bienvenida, hermanos y hermanas, y sepan que el eh\'píritu de Gonk hoy está con nosotro\'.', 'Les doy la bienvenida, hermanos y hermanas, y sepan que el eh\'píritu de Gonk hoy está con nosotro\'.', 28153),
(160923, 'esMX', '¡Pueblo de Zandalar! El loa de las forma\' busca la adoración de su pueblo. ¡Vengan, alcemos nuestras voce\' para el jefe de la manada, el loa más generoso! ¡Alaben a Gonk!', '¡Pueblo de Zandalar! El loa de las forma\' busca la adoración de su pueblo. ¡Vengan, alcemos nuestras voce\' para el jefe de la manada, el loa más generoso! ¡Alaben a Gonk!', 28153),
(160922, 'esMX', '¡Mis compañero\' zandalari! ¡El poderoso Krag\'wa ha regresado! ¡Vengan a los Peldaños de Dazar\'alor para rendir tributo al gran guardián!', '¡Mis compañero\' zandalari! ¡El poderoso Krag\'wa ha regresado! ¡Vengan a los Peldaños de Dazar\'alor para rendir tributo al gran guardián!', 28153),
(160921, 'esMX', 'Muchos me han dicho: \"¿Krag\'wa? ¿El gran sapo? ¡Ese loa e\' un mito! ¡E\' ficción!', 'Muchos me han dicho: \"¿Krag\'wa? ¿El gran sapo? ¡Ese loa e\' un mito! ¡E\' ficción!', 28153),
(160920, 'esMX', '¡El gran guardián ofrece su protección! ¡Alabado sea Krag\'wa!', '¡El gran guardián ofrece su protección! ¡Alabado sea Krag\'wa!', 28153),
(160919, 'esMX', 'Bwonsamdi nos vigila a todos. ¡Sean digno\' de su favor, hermanos y hermanas!', 'Bwonsamdi nos vigila a todos. ¡Sean digno\' de su favor, hermanos y hermanas!', 28153),
(160918, 'esMX', 'Eh\'toy seguro de que todo\' conocen a Bwonsamdi. \"Claro, es el loa de la muerte\", dirán todo\'.', 'Eh\'toy segura de que todo\' conocen a Bwonsamdi. \"Claro, es el loa de la muerte\", dirán todo\'.', 28153),
(160917, 'esMX', '¡Los eh\'píritus nos acompañan! Vengan a los Peldaños de Dazar\'alor y veneren al guardián de nuestros difunto\'. ¡Den las gracias a Bwonsamdi!', '¡Los eh\'píritus nos acompañan! Vengan a los Peldaños de Dazar\'alor y veneren al guardián de nuestros difunto\'. ¡Den las gracias a Bwonsamdi!', 28153),
(160916, 'esMX', 'La nave está en las Islas del Eco. Estoy seguro de que zarpará y regresara con nosotro\' pronto.', '', 28153),
(160915, 'esMX', '', 'No le prestes atención a la pizarra. Es un plan inconcluso.', 28153),
(160914, 'esMX', 'Se acaba de ir. Se dirige a las Islas del Eco. La nave regresará pronto.', '', 28153),
(160913, 'esMX', '¡Mis compañeros zandalari! Vengan a los Peldaño\' de Dazar\'alor para escuchar la sabiduría del rey de los felino\', la perdición de las presa\', el señor de las bestia\'. ¡Alabado sea Kimbul!', '¡Mis compañeros zandalari! Vengan a los Peldaño\' de Dazar\'alor para escuchar la sabiduría del rey de los felino\', la perdición de las presa\', el señor de las bestia\'. ¡Alabado sea Kimbul!', 28153),
(160912, 'esMX', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 'Comparto con ustedes la palabra de mi loa. Así se dirigió a sus seguidore\':', 28153),
(160911, 'esMX', '¡La perdición de las presas bendice sus cacerías! ¡Avancen!', '¡La perdición de las presas bendice sus cacerías! ¡Avancen!', 28153),
(160910, 'esMX', '¡Gocen de la bendición de Akunda!', '¡Gocen de la bendición de Akunda!', 28153),
(160909, 'esMX', 'Compartiré contigo la sabiduría de Akunda. Es el loa de las tormenta\', de los nuevos comienzo\'.', 'Compartiré contigo la sabiduría de Akunda. Es el loa de las tormenta\', de los nuevos comienzo\'.', 28153),
(160908, 'esMX', '¡Se acerca una tormenta! Que la lluvia se lleve sus preocupacione\', hermanos y hermanas. ¡Acérquense a los Peldaños de Dazar y veneren a Akunda!', '¡Se acerca una tormenta! Que la lluvia se lleve sus preocupacione\', hermanos y hermanas. ¡Acérquense a los Peldaños de Dazar y veneren a Akunda!', 28153),
(160907, 'esMX', 'Vaya, es aquí, $Uamigo:amiga;. Sube antes de que zarpe.', '', 28153),
(160906, 'esMX', '¡$uUn verdadero fanático:Una verdadera fanática;! ¡Qué alegría! Debes sentir una vorágine de emociones ahora que me conoces. No te preocupes, dulzura, soy un aventurero común y corriente, como tú. Con la excepción de que soy un autor galardonado e increíblemente rico con fanáticos que cruzan océanos para verme en persona.\n\nAquí tienes tu libro. Estoy seguro de que te encantará.', '', 28153),
(160905, 'esMX', '¡Un día más, una cerveza más! ¿Ya has probado algo excepcionalmente delicioso?', '', 28153),
(160904, 'esMX', '¿Eres $Uun:una; caballero de la muerte? ¡Siempre quise conocer a $Uuno:una;!\n\n¿Cómo es la no-muerte? ¿Siempre quisiste ser $Uun:una; caballero de la muerte? Yo sí. ¿Dónde me inscribo?', '', 28153),
(160903, 'esMX', '¿Podrías firmar mi libro, por favor?', '¿Podrías firmar mi libro, por favor?', 28153),
(160902, 'esMX', 'Mi última creación es una verdadera obra maestra. Una joya literaria desenterrada de las profundidades oceánicas para encantar y seducir al lector. ¿Estás aquí para cantarme alabanzas?', '', 28153),
(160901, 'esMX', 'Francamente, en eh\'te momento no lo sé. Ojalá la Alianza no los haya atrapado.', '', 28153),
(160900, 'esMX', 'No podremos frenar a Mythrax durante mucho tiempo más. Mata a Zul mientras podamos.', '', 28153),
(160899, 'esMX', '¡Me salvaste! ¡Muchas gracias! Tengo una recompensa para ti, por aquí en esta bolsa.', '', 28153),
(160898, 'esMX', 'Cuida tu ciudad, adalid. Yo ahuyentaré a estos sethrak viles del camino del norte.', '', 28153),
(160897, 'esMX', '', 'Jamás creí que vería las calle\' de Zuldazar repletas de enemigos...', 28153),
(160896, 'esMX', '', '¿Dónde están las defensa\'? ¿Es que la traición de Zul ha debilitado tanto a Zuldazar que ni siquiera pueden defenderse?\n\nLogré que Meerah nos llevará allí a tiempo para advertir a la guardia real, pero han sobrevivido tan pocos soldado\'. De nosotro\' dependerá la defensa de lo que queda.', 28153),
(160895, 'esMX', '', 'No creerías la ruta que tuvimos que tomar para llegar aquí antes de los sethrak. Sin mi ayuda, tus amigos jamás habrían atravesado esas montañas a tiempo.\n\nAh, y trajimos a Akunda y a Kimbul. Akunda nos cubre la espalda. No sé a dónde se fue Kimbul, pero dijo algo de \"desgarrar al enemigo\" o algo así.\n\nTodo lo que sé es que vimos que MUCHOS sethrak venían en esta dirección. ¡MUCHÍSIMOS!', 28153),
(160894, 'esMX', '¿Puedes contarnos algo sobre los movimientos de la Horda en el área?', '¿Puedes contarnos algo sobre los movimientos de la Horda en el área?', 28153),
(160893, 'esMX', 'Pensé que no volvería. Te doy las gracias, $r. A ustedes siguen llamándolos $r, ¿verdad?', 'Pensé que no volvería. Te doy las gracias, $r. A ustedes siguen llamándolos $r, ¿verdad?', 28153),
(160892, 'esMX', '', '¡Luces como si te faltara un buen trago de agua! ¡O de cerveza!', 28153),
(160891, 'esMX', 'Déjame ver tu lista de cervezas.', 'Déjame ver tu lista de cervezas.', 28153),
(160890, 'esMX', '', '¿Puedo sugerirte una cerveza? ¡Tenemos opciones para cada paladar!', 28153),
(160889, 'esMX', 'Vaya, los aniquilaste en un segundo. ¿Sabes algo? Si quieres, podría pertrechar a tus tropas con armaduras nuevas. ¡Sin cargo, por supuesto!', '', 28153),
(160888, 'esMX', '', 'Si usas Disparo lacerante, podrás volver a usar Cólera de las bestias en menos tiempo.', 28153),
(160887, 'esMX', '¡Lo hago tan rápido como puedo!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160886, 'esMX', '', '¡Más rápido, Colton! ¡Tenemos clientes que alimentar!', 28153),
(160885, 'esMX', 'Si usas Disparo lacerante, podrás volver a usar Cólera de las bestias en menos tiempo.', '', 28153),
(160884, 'esMX', '¡Vamos, muchacha!', '', 28153),
(160883, 'esMX', '¿Todo listo?', '', 28153),
(160882, 'esMX', '¿Es hora de jugar, Luna?', '', 28153),
(160881, 'esMX', 'Soy muy afortunado de haber encontrado a una esposa tan brillante.', '', 28153),
(160880, 'esMX', '', '¡Tengo una sorpresa para ti!', 28153),
(160879, 'esMX', '', 'Esto es fascinante, ¿lo has visto?', 28153),
(160878, 'esMX', 'Ah, no sé. Quizás encuentre algún lugar agradable donde pueda sentar cabeza en alguna granja pequeña...\n\n¿Tú qué CREES que haré?!\n\nTomaré el dinero que Cyrus me debe, compraré una ronda para todos en Puerto Cálido y buscaré mi próxima aventura.\n\nEs la única manera de vivir, $Uamigo:amiga;.', '', 28153),
(160877, 'esMX', '¿Qué harás ahora?', '¿Qué harás ahora?', 28153),
(160876, 'esMX', 'Invasiones, golpes de estado, dioses antiguos, ¡bah! No me iré del Zócalo hasta que el Viejo Cuentero me pague lo que me debe.', '', 28153),
(160875, 'esMX', 'Esto no es nada. Durante la Tercera Guerra, contemplé la gran danza de huesos de Sendarraíz. Jamás estuve tan emocionado y aterrado a la vez.', '', 28153),
(160874, 'esMX', 'Lo juro, si sobrevivo a esto, prometo que no volveré a timar a mis cliente\' durante por lo menos dos... o tres semanas.', '', 28153),
(160873, 'esMX', '¿Dónde está la nave ahora?', '¿Dónde está la nave ahora?', 28153),
(160872, 'esMX', '', 'Enviaré toda la ayuda que pueda, $n.', 28153),
(160871, 'esMX', '', 'Yo viví el momento en que la Plaga arrasó Zul\'Drak, y aun así, este ataque a nuestra tierra natal de parte de quienes creíamos que eran nuestros amigos… \n\nBueno, normalmente no soy una trol violenta, pero creo que quizás deba matar a alguien por esto.', 28153),
(160870, 'esMX', '¡Archidruida, Malfurion necesita tu ayuda en Costa Oscura!', '¡Archidruida, Malfurion necesita tu ayuda en Costa Oscura!', 28153),
(160869, 'esMX', 'Sacerdotisa, necesitamos tu ayuda para repeler a la Horda en el Río Culebra.', 'Sacerdotisa, necesitamos tu ayuda para repeler a la Horda en el Río Culebra.', 28153),
(160868, 'esMX', 'Eh\'tás ayudando a la princesa, y eso es bueno. Sigue así. Destruye a los trols de sangre antes de que nos consuman a todo\'.\n\nLa emisaria que buh\'cas se encuentra en las Ruina\' de Zul\'jan. Se llama proveedora Lija. Ella te ayudará con todo lo que necesites.', 'Eh\'tás ayudando a la princesa, y eso es bueno. Sigue así. Destruye a los trols de sangre antes de que nos consuman a todo\'.\n\nLa emisaria que buh\'cas se encuentra en las Ruina\' de Zul\'jan. Se llama proveedora Lija. Ella te ayudará con todo lo que necesites.', 28153),
(160867, 'esMX', 'La jefa de guerra desea que hagas todo lo que esté a tu alcance para que los zandalari y su flota se unan a la Horda. Para cumplir con ese pedido, deberías seguir apoyando a Talanji. Si eso significa que tienes que destruir hasta el último trol de sangre, entonces hazlo.\n\nSu emisaria, la proveedora Lija, se encuentra en Nazmir, en las Ruinas de Zul\'jan. Que la Dama Oscura te proteja.', 'La jefa de guerra desea que hagas todo lo que esté a tu alcance para que los zandalari y su flota se unan a la Horda. Para cumplir con ese pedido, deberías seguir apoyando a Talanji. Si eso significa que tienes que destruir hasta el último trol de sangre, entonces hazlo.\n\nSu emisaria, la proveedora Lija, se encuentra en Nazmir, en las Ruinas de Zul\'jan. Que la Dama Oscura te proteja.', 28153),
(160866, 'esMX', 'Emisaria de la Expedición de Talanji', 'Emisaria de la Expedición de Talanji', 28153),
(160865, 'esMX', '¡La cerveza de estos kultiranos es interesante!\n\nTiene mucho más sabor que la que he tomado en el continente. ¡Realmente le ponen empeño a sus bebidas!', '', 28153),
(160864, 'esMX', 'Ve a la ubicación de la princesa Talanji y la guardiana bélica Rakera.', 'Ve a la ubicación de la princesa Talanji y la guardiana bélica Rakera.', 28153),
(160863, 'esMX', '', '¿Cultistas de sangre, sethrak, mogu y hasta nuestro propio Zul? Extraño los días en que solo intentábamos conquistar el mundo.', 28153),
(160862, 'esMX', '', 'Aunque nuestra larga guerra contra la Legión ha terminado, la Horda no puede darse el lujo de descansar.', 28153),
(160861, 'esMX', 'La Legión ha caído, pero crece otra amenaza. Llegan mensajes inquietantes de nuestros agentes en Orgrimmar. Reunámonos en el Castillo de Ventormenta para hablar más sobre esto.', '', 28153),
(160860, 'esMX', '¡Te doy la bienvenida a Aguas Impetuosas! ¿Buscas suministros para tu pequeñín o pequeñita?', '', 28153),
(160859, 'esMX', '', 'Todo comenzó con tres gatos. ¡Tres gatos! ¡Eso parecía razonable!\n\nPero después un amigo tuvo que partir y necesitaba reubicar a su gato. Después encontré un gato callejero con ojos tristes en la calle. Un vecino falleció. Una tuvo gatitos. ¡Otros simplemente aparecieron de la nada!\n\nLos quiero a todos. No los cambiaría por nada en el mundo.', 28153),
(160858, 'esMX', '¡Sí! ¡Otra vez!', '', 28153),
(160857, 'esMX', 'Ninguno de estos cachorros me pertenece. Perdí a mi querido Willoughby hace muchos años. Así que vengo aquí todos los días a buscar al más solitario. Los acaricio y les recuerdo que son buenos perros.', '', 28153),
(160856, 'esMX', 'Haría lo que fuera por mi perro.', '', 28153),
(160855, 'esMX', 'Este es mi perro, Bucket. ¡Es muy bueno cavando!\n\nLo puse aquí arriba para poder acariciarlo mejor. Creo que le agrada estar aquí.', '', 28153),
(160854, 'esMX', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Asegúrate de que al menos un jugador esté parado sobre cada área objetivo de |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Asegúrate de que al menos un jugador esté parado sobre cada área objetivo de |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', 28153),
(160853, 'esMX', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t ¡Tienes más de 50 acumulaciones de |cFFFF0000|Hspell:272146|h[Aniquilación]|h|r! ¡Busca Fragmentos de esencia para recuperar puntos de salud máxima!', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t ¡Tienes más de 50 acumulaciones de |cFFFF0000|Hspell:272146|h[Aniquilación]|h|r! ¡Busca Fragmentos de esencia para recuperar puntos de salud máxima!', 28153),
(160852, 'esMX', 'He oído que necesitas ayuda con los ettins.', 'He oído que necesitas ayuda con los ettins.', 28153),
(160851, 'esMX', '¡Por la Alianza!', '', 28153),
(160850, 'esMX', 'Me aseguraré de que el rey Anduin se entere en persona de los actos heroicos de hoy. Todos han hecho un excelente trabajo.', '', 28153),
(160849, 'esMX', 'Y un reconocimiento especial para el gran señor feudal Falstad y todo el clan Martillo Salvaje.', '', 28153),
(160848, 'esMX', 'Estás muy lejos de casa, $r.$b$bLes pediré a los espíritu\' que te protejan mientras estás en Vol\'dun. Pero debo advertirte: ya no me escuchan.', 'Estás muy lejos de casa, $r.$b$bLes pediré a los espíritu\' que te protejan mientras estás en Vol\'dun. Pero debo advertirte: ya no me escuchan.', 28153),
(160847, 'esMX', 'No hay manera de escapar de eh\'te calor.', 'No hay manera de escapar de eh\'te calor.', 28153),
(160846, 'esMX', '¡Sabandija imbécil! ¡Te arrancaré la cabeza por eso!', '¡Sabandija imbécil! ¡Te arrancaré la cabeza por eso!', 28153),
(160845, 'esMX', '¿Tú otra vez? Tuve piedad la última vez. ¡No pienso volver a cometer el mismo error!', '¿Tú otra vez? Tuve piedad la última vez. ¡No pienso volver a cometer el mismo error!', 28153),
(160844, 'esMX', 'Gracias por rescatarme. Te diré algo: como recompensa, pertrecharé a tu ejército entero con las mejores armas de Industrias Tarque. ¡Que viva la paz! ¡Salud!', '', 28153),
(160843, 'esMX', 'Y yo... que temía... a los tiburones...', 'Y yo... que temía... a los tiburones...', 28153),
(160842, 'esMX', 'Quiero la revancha... en tierra firme...', 'Quiero la revancha... en tierra firme...', 28153),
(160841, 'esMX', 'Por... la Horda...', 'Por... la Horda...', 28153),
(160840, 'esMX', '¿A dónde... huirás...?', '¿A dónde... huirás...?', 28153),
(160839, 'esMX', 'Así no...', 'Así no...', 28153),
(160838, 'esMX', 'Arrástrame... al bote...', 'Arrástrame... al bote...', 28153),
(160837, 'esMX', 'Déjame... hundirme...', 'Déjame... hundirme...', 28153),
(160836, 'esMX', 'Muero... por un rescate...', 'Muero... por un rescate...', 28153),
(160835, 'esMX', '¡Ni siquiera necesito mis pantalones para vencerte!', '¡Ni siquiera necesito mis pantalones para vencerte!', 28153),
(160834, 'esMX', '¡Como pescar un pez con un arpón!', '¡Como pescar un pez con un arpón!', 28153),
(160833, 'esMX', '¡Por fin esto de bucear se pone interesante!', '¡Por fin esto de bucear se pone interesante!', 28153),
(160832, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(160831, 'esMX', '¡No es justo! ¡Mi equipo está en el bote!', '¡No es justo! ¡Mi equipo está en el bote!', 28153),
(160830, 'esMX', '¿Qué sucedió mientras estaba ahí abajo? ¡La Alianza ha llegado!', '¿Qué sucedió mientras estaba ahí abajo? ¡La Alianza ha llegado!', 28153),
(160829, 'esMX', '¿La Alianza también está aquí?', '¿La Alianza también está aquí?', 28153),
(160828, 'esMX', 'Un momento, ¿qué haces aquí?', 'Un momento, ¿qué haces aquí?', 28153),
(160827, 'esMX', '¡No toques nada!', '¡No toques nada!', 28153),
(160826, 'esMX', '¡Fregaré las cubiertas con tu sangre!', '¡Fregaré las cubiertas con tu sangre!', 28153),
(160825, 'esMX', '¡Yo detendré a $Ueste:esta; $pr!', '¡Yo detendré a $Ueste:esta; $pr!', 28153),
(160824, 'esMX', 'No me interesa qué estás haciendo, ¡detente ahora!', 'No me interesa qué estás haciendo, ¡detente ahora!', 28153),
(160823, 'esMX', '¿Qué me ha traído el loa hoy?', '¿Qué me ha traído el loa hoy?', 28153),
(160822, 'esMX', '¡Quita las manos de los suministros!', '¡Quita las manos de los suministros!', 28153),
(160821, 'esMX', '¡No dejen que se acerquen a los cañones!', '¡No dejen que se acerquen a los cañones!', 28153),
(160820, 'esMX', '¡No toques eso!', '¡No toques eso!', 28153),
(160819, 'esMX', '¡Aléjate de eso!', '¡Aléjate de eso!', 28153),
(160818, 'esMX', 'Arrójame... por la borda...', 'Arrójame... por la borda...', 28153),
(160817, 'esMX', '$UMaldito:Maldita; seas tú... y tu rey...', '$UMaldito:Maldita; seas tú... y tu rey...', 28153),
(160816, 'esMX', 'Estás $Uatrapado:atrapada; aquí... con nosotros...', 'Estás $Uatrapado:atrapada; aquí... con nosotros...', 28153),
(160815, 'esMX', 'Por mi... jefa de guerra...', 'Por mi... jefa de guerra...', 28153),
(160814, 'esMX', 'Bestia de la Alianza...', 'Bestia de la Alianza...', 28153),
(160813, 'esMX', 'Se suponía... que sería... sencillo...', 'Se suponía... que sería... sencillo...', 28153),
(160812, 'esMX', 'Nathanos... acabará... contigo...', 'Nathanos... acabará... contigo...', 28153),
(160811, 'esMX', 'Por... la Reina... alma en pena...', 'Por... la Reina... alma en pena...', 28153),
(160810, 'esMX', 'Sabía que había sentido el hedor de $Uun:una; $pr.', 'Sabía que había sentido el hedor de $Uun:una; $pr.', 28153),
(160809, 'esMX', '¡Te cortaré la lengua!', '¡Te cortaré la lengua!', 28153),
(160808, 'esMX', '¡Avísenle a Nathanos!', '¡Avísenle a Nathanos!', 28153),
(160807, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(160806, 'esMX', '¡Por la Dama Oscura!', '¡Por la Dama Oscura!', 28153),
(160805, 'esMX', '¡A ellos!', '¡A ellos!', 28153),
(160804, 'esMX', '¡Fuera de nuestro barco!', '¡Fuera de nuestro barco!', 28153),
(160803, 'esMX', '¡La Alianza ha llegado!', '¡La Alianza ha llegado!', 28153),
(160802, 'esMX', 'Dreven acabará... contigo...', 'Dreven acabará... contigo...', 28153),
(160801, 'esMX', 'Solo un poco... más de... poder...', 'Solo un poco... más de... poder...', 28153),
(160800, 'esMX', 'Soy... invencible...', 'Soy... invencible...', 28153),
(160799, 'esMX', 'Te maldigo...', 'Te maldigo...', 28153),
(160798, 'esMX', 'El príncipe de sangre... te... drenará...', 'El príncipe de sangre... te... drenará...', 28153),
(160797, 'esMX', '¡No!', '¡No!', 28153),
(160796, 'esMX', '¡Sigue así! Solo un poco más...', '', 28153),
(160795, 'esMX', 'Una... última... gota...', 'Una... última... gota...', 28153),
(160794, 'esMX', 'Solo... una vez... más...', 'Solo... una vez... más...', 28153),
(160793, 'esMX', 'Te quebrarás antes de que termine contigo.', 'Te quebrarás antes de que termine contigo.', 28153),
(160792, 'esMX', '¡No eres más que alimento para los san\'layn!', '¡No eres más que alimento para los san\'layn!', 28153),
(160791, 'esMX', '¡Muy bien! ¡Creo que está funcionando!', '', 28153),
(160790, 'esMX', '$Un:Una; $pr... Qué curioso.', '$Un:Una; $pr... Qué curioso.', 28153),
(160789, 'esMX', '¡Te arrancaré la carne de los huesos!', '¡Te arrancaré la carne de los huesos!', 28153),
(160788, 'esMX', 'Miren lo que acaba de llegar a nuestra nave.', 'Miren lo que acaba de llegar a nuestra nave.', 28153),
(160787, 'esMX', 'Esto te dolerá mucho.', 'Esto te dolerá mucho.', 28153),
(160786, 'esMX', 'Quiero oírte gritar.', 'Quiero oírte gritar.', 28153),
(160785, 'esMX', 'Acércate, $pr...', 'Acércate, $pr...', 28153),
(160784, 'esMX', '$UUn:Una; $c, ¿eh? ¿Qué te trae por estas tierras?\n\nAh, seguramente sea una batalla inminente. Muy bien, esta charla me ha dejado sediento.\n\nAhora, si me disculpas, me iré a seguir con mis preparativos.', '', 28153),
(160783, 'esMX', 'La batalla nos espera. $uUn:una; $c como tú nos vendría bien en nuestras filas.', '', 28153),
(160782, 'esMX', 'Ven con nosotros, estarás bien. No te haremos daño.', 'Ven con nosotros, estarás bien. No te haremos daño.', 28153),
(160781, 'esMX', '¡Por favor, no me lleven!', '¡Por favor, no me lleven!', 28153),
(160780, 'esMX', '¿La Horda? ¿Aquí?', '¿La Horda? ¿Aquí?', 28153),
(160779, 'esMX', 'Sal de aquí, ya es tarde...', 'Sal de aquí, ya es tarde...', 28153),
(160778, 'esMX', '¡Este debería ser un tiempo de celebraciones! Pero a veces es difícil festejar en un mundo tan cambiante como este. ¡Puedo ayudarte si quieres unirte a las celebraciones!', '', 28153),
(160777, 'esMX', '<Dale un golpe.>', '<Dale un golpe.>', 28153),
(160776, 'esMX', 'Roko te envía saludos.', 'Roko te envía saludos.', 28153),
(160775, 'esMX', '¿Te acuerdas de mí?', '¿Te acuerdas de mí?', 28153),
(160774, 'esMX', '¿Qué tienes tú que hablar con los exiliado\' y la escoria de las arena\'? Vol\'dun es el sitio donde enviamo\' a morir a quienes causan muchos problemas.\n\nDe todas formas, confío en ti. Bueno, escúchame con atención. Tienes que ir a hablar con una vulpera. Se llama acaparadora Jena. La encontrarás en un sitio al que llaman Escondite Vulpera.', '¿Qué tienes tú que hablar con los exiliado\' y la escoria de las arena\'? Vol\'dun es el sitio donde enviamo\' a morir a quienes causan muchos problemas.\n\nDe todas formas, confío en ti. Bueno, escúchame con atención. Tienes que ir a hablar con una vulpera. Se llama acaparadora Jena. La encontrarás en un sitio al que llaman Escondite Vulpera.', 28153),
(160773, 'esMX', '¿Has venido a suplicar caridad como el resto de la chusma apestosa que está afuera?$B$BNo pierdas el tiempo. Estoy aquí para trabajar.', '¿Has venido a suplicar caridad como el resto de la chusma apestosa que está afuera?$B$BNo pierdas el tiempo. Estoy aquí para trabajar.', 28153),
(160772, 'esMX', '¿Para qué quieres hablar con ellos? Son una caterva de exiliados y carroñeros. ¿Acaso la Dama Oscura te ha pedido que los incorpores a nuestras filas?\n\nNo sé cuáles serán tus razones, pero te recomiendo ir al Escondite Vulpera, en Vol\'dun. Allí hay una muchacha con aspecto de zorro que se hace llamar Acaparadora Jena. Quizá ella pueda ayudarte.', '¿Para qué quieres hablar con ellos? Son una caterva de exiliados y carroñeros. ¿Acaso la Dama Oscura te ha pedido que los incorpores a nuestras filas?\n\nNo sé cuáles serán tus razones, pero te recomiendo ir al Escondite Vulpera, en Vol\'dun. Allí hay una muchacha con aspecto de zorro que se hace llamar Acaparadora Jena. Quizá ella pueda ayudarte.', 28153),
(160771, 'esMX', 'Emisaria voldunai', 'Emisaria voldunai', 28153),
(160770, 'esMX', 'Si me preguntas a mí, la Estela de la Tormenta es un grupo de gente decente. Si quieres hablar con alguno de sus líderes, ve a Brennadam, en el Valle Canto Tormenta.\n\nCuando estés allí, busca a la Hermana Lilyana. Te ayudará con todo lo que quieras saber sobre la Estela.', 'Si me preguntas a mí, la Estela de la Tormenta es un grupo de gente decente. Si quieres hablar con alguno de sus líderes, ve a Brennadam, en el Valle Canto Tormenta.\n\nCuando estés allí, busca a la Hermana Lilyana. Te ayudará con todo lo que quieras saber sobre la Estela.', 28153),
(160769, 'esMX', 'Emisaria de Estela de la Tormenta', 'Emisaria de Estela de la Tormenta', 28153),
(160768, 'esMX', '<Quédate un rato y escucha.>', '<Quédate un rato y escucha.>', 28153),
(160767, 'esMX', 'Je, parece que hasta ahuyentamos a la tormenta.', '', 28153),
(160766, 'esMX', 'Esta guerra se veía venir.\n\nLa Alianza se oculta entre la justicia y la devoción. ¡Patrañas! Rechazan y denigran a cualquiera que no tenga lugar en su cosmovisión estrecha.', '', 28153),
(160765, 'esMX', '<Quédate un rato y escucha.>', '<Quédate un rato y escucha.>', 28153),
(160764, 'esMX', '', 'Parece que me han obligado a regresar al servicio militar para cumplir las órdenes de otro amo.\n\nHaré lo que debo hacer, diré lo que debo decir para sobrevivir.\n\nPero, tarde o temprano, esta guerra llegará a su fin. Debemos prepararnos para lo que siga.', 28153),
(160763, 'esMX', '<Quédate un rato y escucha.>', '<Quédate un rato y escucha.>', 28153),
(160762, 'esMX', 'La sutileza y la sagacidad son nuestras mejores armas en esta guerra, $n.', '', 28153),
(160761, 'esMX', '<Quédate un rato y escucha.>', '<Quédate un rato y escucha.>', 28153),
(160759, 'esMX', '¡Cuando los Martillo Salvaje están de tu lado, solo debes mirar al cielo si estás en problemas y ahí estaremos!', '', 28153),
(160758, 'esMX', 'La campaña avanza a paso firme, $n. Sin duda has cumplido con tu parte.', '', 28153),
(160757, 'esMX', 'Cómo se reirá la Dama Oscura...Cuando le diga que has muerto en una trampa, como la escoria que eres.', '', 28153),
(160756, 'esMX', 'Hace mucho tiempo que anhelo acabar con tu entrometida existencia.', '', 28153),
(160755, 'esMX', 'Terminemos con esto.', '', 28153),
(160754, 'esMX', '¿La Orden de las Ascuas? ¿Qué es eso? Suena terriblemente misterioso.\n\nCasualmente, he oído sobre alguien que está en el Alto de Arom, en Drustvar, bien al oeste. Se hace llamar Intendente Alcorn. Pero si me has preguntado por esto, imagino que sabrás llegar. Dame tu mapa y marcaré la zona para que no te pierdas.', '¿La Orden de las Ascuas? ¿Qué es eso? Suena terriblemente misterioso.\n\nCasualmente, he oído sobre alguien que está en el Alto de Arom, en Drustvar, bien al oeste. Se hace llamar Intendente Alcorn. Pero si me has preguntado por esto, imagino que sabrás llegar. Dame tu mapa y marcaré la zona para que no te pierdas.', 28153),
(160753, 'esMX', 'Las hermanas Fenlow solicitaron mi asistencia. El mundo ha sido testigo de muchos cambios. Eso no debe impedir la diversión.', '', 28153),
(160752, 'esMX', '¿Qué hace por aquí un miembro del vuelo bronce?', '¿Qué hace por aquí un miembro del vuelo bronce?', 28153),
(160751, 'esMX', '¿Estás disfrutando de las festividades?', '', 28153),
(160750, 'esMX', 'Emisario de la Orden de las Ascuas', 'Emisario de la Orden de las Ascuas', 28153),
(160749, 'esMX', 'Sí. Mis Martillo Salvaje, guarden sus martillos de tormenta y preparen un circuito de espera hasta que dé la orden.', '', 28153),
(160748, 'esMX', '', 'Será mejor tomar distancia. Quiero observarlos e idear un plan antes de que sepan que estamos aquí.', 28153),
(160747, 'esMX', 'Allí están, general. Dos acorazados a la vista. Renegados.', '', 28153),
(160746, 'esMX', 'Ximo dice que no debo hablar con los cliente\'.', '', 28153),
(160745, 'esMX', '', 'Que mueras bien, Grommash Grito Infernal.', 28153),
(160744, 'esMX', '¡Que su sacrificio no sea en vano! ¡Nos vamos! ¡AHORA!', '', 28153),
(160743, 'esMX', '', '¡No! ¡Me quedaré junto a mi jefe de guerra!', 28153),
(160742, 'esMX', '¡Reúnanse, rápido! ¡Solo tenemos una oportunidad!', '', 28153),
(160741, 'esMX', '¡Por los Mag\'har! ¡Por Draenor! ¡Lok-tar ogar!', '', 28153),
(160740, 'esMX', '', 'Me las ingenié para tomar algunas cajas de provisiones antes de irme. Te invito a que te quedes con algunas. ¡Necesitarás tu fuerza!', 28153),
(160739, 'esMX', '', 'Mis hermanos y hermanas han ido demasiado lejos. Depende de nosotros reparar este error.', 28153),
(160738, 'esMX', '', 'Si quieres descansar, tenemos algunos catres. No es mucho, pero es lo que hay.', 28153),
(160737, 'esMX', 'Geya\'rah, llévate a todos de aquí. Ahora. Y no hagas preguntas.', '', 28153),
(160736, 'esMX', '<Grommash baja la voz para que solo los Mag\'har puedan oírlo.>', '', 28153),
(160735, 'esMX', '', 'Me apena perder a un viejo amigo, Grommash. Pero... que así sea. Resolveremos esto a tu manera.', 28153),
(160734, 'esMX', '¿Cómo puedes ser tan ciega, Yrel? ¡Es la Luz la que ha maldecido este mundo!', '', 28153),
(160733, 'esMX', '', 'Tu pueblo está succionándole la vida a este mundo... ha maldecido a este mundo con el flagelo de la desecación.', 28153),
(160732, 'esMX', '', 'He venido a ofrecerte una última oportunidad para que te unas a la Luz.', 28153),
(160731, 'esMX', 'Alta exarca. Es un honor... peculiar.', '', 28153),
(160730, 'esMX', '', 'Grommash Grito Infernal. Ha pasado mucho tiempo.', 28153),
(160729, 'esMX', '', '¡Debemos hacerlo! ¡Nuestro destino NO ES caer ante esta corrupción!', 28153),
(160728, 'esMX', 'El bote hacia Kul Tiras acaba de llegar. ¡Todos a bordo para ir a Boralus!', 'El bote hacia Kul Tiras acaba de llegar. ¡Todos a bordo para ir a Boralus!', 28153),
(160727, 'esMX', '¡Son demasiados! ¡No podremos resistir por siempre!', '', 28153),
(160726, 'esMX', '$n, ¡ve a la parte superior de la torre y acribilla a los Lazoluz!', '', 28153),
(160725, 'esMX', 'Señora suprema, Eitrigg, ¡defiendan esta posición junto a mí!', '', 28153),
(160724, 'esMX', '¡Lantresor, cabalga lo más rápido que puedas! ¡Junta a todos los orcos que veas y tráelos aquí!', '', 28153),
(160723, 'esMX', '...', '', 28153),
(160722, 'esMX', '¿A todos?', '', 28153),
(160721, 'esMX', 'A todos.', '', 28153),
(160720, 'esMX', '¿A cuántos nos enfrentamos, Lantresor?', '', 28153),
(160719, 'esMX', '¡Jefe de guerra Grito Infernal! ¡Se acerca un ejército!', '', 28153),
(160718, 'esMX', '<Vuela a Ventormenta>', '<Vuela a Ventormenta>', 28153),
(160717, 'esMX', '', '¡El Implacable acaba de encallar! ¡Todos a bordo para ir a Ventormenta!', 28153),
(160716, 'esMX', '¡Señora suprema! Los Quebrantarrocas no queremos problemas con los orcos. Kor\'gall está en su cueva.', '', 28153),
(160715, 'esMX', '¿Ya vuelves a tu hogar? Qué suerte tienes; uno de los pocos barcos que quedan de la Alianza viaja desde aquí hasta Ventormenta con bastante frecuencia. Dirígete al pequeño muelle de madera que está al sur del Mercado Vientos Alisios.\n\nNos vemos.', '¿Ya vuelves a tu hogar? Qué suerte tienes; uno de los pocos barcos que quedan de la Alianza viaja desde aquí hasta Ventormenta con bastante frecuencia. Dirígete al pequeño muelle de madera que está al sur del Mercado Vientos Alisios.\n\nNos vemos.', 28153),
(160714, 'esMX', 'Nave a Ventormenta', 'Nave a Ventormenta', 28153),
(160713, 'esMX', 'No tienes idea de la cantidad de reparaciones que he tenido que hacer. Uno creería que con toda la magia que conjuran los maresabios, al menos usarían materiales a prueba de agua.', '', 28153),
(160712, 'esMX', '<Vuela a Orgrimmar>', '<Vuela a Orgrimmar>', 28153),
(160711, 'esMX', 'Para ser honesto, jamás confié en ellos. ¿Acaso has visto sus estandartes?', '', 28153),
(160710, 'esMX', '¡Los maresabios han enloquecido!', '', 28153),
(160709, 'esMX', '¿Has visitado nueh\'tros bares acuático\'? ¡No te los puedes perder!', '', 28153),
(160708, 'esMX', 'Cuando el barco eh\'tá vacío, me relajo y sumerjo mis cuatro dedo\' de los pie\' en el agua.', '', 28153),
(160707, 'esMX', 'Nada mejor que el aroma del mar.', '', 28153),
(160706, 'esMX', 'Vivimo\' en una isla para que el resto del mundo no nos moleste. ¿Por qué vuelven a sus casa\'? No eh\'toy hablando de ti, claro.', '', 28153),
(160705, 'esMX', 'El sonido del remo atravesando el agua es muy relajante.', '', 28153),
(160704, 'esMX', 'Zeb\'ahari era mi favorita, tranquila y relajante. Nada que ver con el bullicio de Dazar\'alor, se puede apreciar la belleza de Zuldazar.', '', 28153),
(160703, 'esMX', 'Recuerdo cuando era un trol pequeñito, me encantaban los viaje\' a la orilla.', '', 28153),
(160702, 'esMX', '¡Cuanto antes limpien nuestras playa\', más felice\' seremos!', '', 28153),
(160701, 'esMX', 'Envíame a Filón de Galson.', 'Envíame a Filón de Galson.', 28153),
(160700, 'esMX', 'Envíame a Aserradero de Tierras Altas.', 'Envíame a Aserradero de Tierras Altas.', 28153),
(160699, 'esMX', 'Envíame a Castillo de Stromgarde.', 'Envíame a Castillo de Stromgarde.', 28153),
(160698, 'esMX', '¿Te llevo a algún lado?', '', 28153),
(160697, 'esMX', '¡Si trabajamos juntos lograremos ordenar la situación!', '', 28153),
(160696, 'esMX', '¡Deja que la Corporación de Ingenieros de Control de Calidad se encargue de encontrar los problemas!', '', 28153),
(160695, 'esMX', '¿Una abolladura? ¿Dónde? ¡Yo me encargo!', '', 28153),
(160694, 'esMX', '<Toma las notas.>', '<Toma las notas.>', 28153),
(160693, 'esMX', '', '\"Tras descubrir finalmente una base apropiada, hemos logrado producir un compuesto estable.$B$B¡En este estado, se puede almacenar, transportar o incorporar al proceso de mezcla para crear una pólvora negra increíblemente potente!$B$BConfío tanto en su estabilidad que las muestras iniciales se enviaron a Boralus suspendidas dentro de un collar.$B$BMientras los calderos trabajan día y noche mezclando pólvora, también seguimos creando prototipos para otros usos. El prototipo más prometedor hasta ahora es una pistola, que esperamos que se convierta en otro regalo apropiado para nuestra estimada presidenta\".$B$B<Las notas desorganizadas dan detalles sobre diversos proyectos e ideas.>', 28153),
(160692, 'esMX', 'Potenciamiento', 'Potenciamiento', 28153),
(160691, 'esMX', '', 'Una ve\' que Zandalar eh\'té en ruinas, ¡el imperio de los dioses antiguo\' renacerá!', 28153),
(160690, 'esMX', '', 'Tu lucha es en vano... ¡G\'huun será libre!', 28153),
(160689, 'esMX', '', 'Si deh\'truyen el último sello, ¡desatarán a ese monstruo sobre Azeroth!', 28153),
(160688, 'esMX', 'Análisis concluido: dispositivos de Nazmir y Vol\'dun fuera de servicio. Último sello en funcionamiento: Zuldazar.', '', 28153),
(160687, 'esMX', 'Designación: G\'huun.', '', 28153),
(160686, 'esMX', '', 'Eh\'to. Termina. Ahora.', 28153),
(160685, 'esMX', '', 'Ya no escaparás de tus crímenes.', 28153),
(160684, 'esMX', 'Y tú no tienes lugar entre los reye\'.', '', 28153),
(160683, 'esMX', '¿Es que no lo entiende\'?', '', 28153),
(160682, 'esMX', '¿Cómo te llamamo\' ahora?', '', 28153),
(160681, 'esMX', 'Invades tierras sagradas.', '', 28153),
(160680, 'esMX', 'Estoy $Ulisto:lista; para ayudar.', 'Estoy $Ulisto:lista; para ayudar.', 28153),
(160679, 'esMX', '', 'Aunque estos días han estado marcados por las pérdidas, seguiremos adelante.', 28153),
(160678, 'esMX', 'Recuerda, ¡el lado húmedo va a hacia abajo!', '', 28153),
(160677, 'esMX', 'Cielo rojo al atardecer, buen tiempo has de tener. Cielo rojo a la alborada, cuidado que el marinero se enfada.', '', 28153),
(160676, 'esMX', 'La nave eh\'tá a salvo en el puerto... ¿pero qué tiene eso de divertido?', '', 28153),
(160675, 'esMX', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t ¡Mythrax comienza a lanzar |cFFFF0000|Hspell:274113|h[Rayo desintegrador]|h|r!', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t ¡Mythrax comienza a lanzar |cFFFF0000|Hspell:274113|h[Rayo desintegrador]|h|r!', 28153),
(160674, 'esMX', 'Bien hecho, $p. Bien hecho, Shandris.', '', 28153),
(160673, 'esMX', 'Xibala', 'Xibala', 28153),
(160672, 'esMX', 'Si quieres aprender a fabricar tu equipo de manera más eficiente, ¡no busques más! Tengo lo que necesitas.', '', 28153),
(160671, 'esMX', 'Los Martillo Salvaje contarán anécdotas de esta misión por años... Pero ahora, necesito una pinta.', '', 28153),
(160670, 'esMX', '', 'Seguiremos muy de cerca los movimientos de los sethrak que están aquí abajo. ¡Cuenta con nosotros!', 28153),
(160669, 'esMX', '¡Eres $Uel:la; mejor!', '¡Eres $Uel:la; mejor!', 28153),
(160668, 'esMX', '¡Hazlos volar otra vez!', '¡Hazlos volar otra vez!', 28153),
(160667, 'esMX', '¡Cuando crezca quiero ser como tú!', '¡Cuando crezca quiero ser como tú!', 28153),
(160666, 'esMX', '¡Eres $Uun héroe:una heroína;!', '¡Eres $Uun héroe:una heroína;!', 28153),
(160665, 'esMX', 'Si quieres aprender a fabricar tu equipo de manera más eficiente, ¡no busques más! Tengo lo que necesitas.', '', 28153),
(160664, 'esMX', '|TInterface\\Icons\\70_inscription_vantus_rune_light:20|t¡%s crea un |cFFFF0000|Hspell:267905|h[Resguardo reforzante]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', 28153),
(160663, 'esMX', '', '¡Maldigo a esta Luz nefasta!', 28153),
(160662, 'esMX', '', 'No... Un naaru... ¡Otra vez no!', 28153),
(160661, 'esMX', '', 'Y sobre el destino de mis hermanos y hermanas en Fuerte Siempredía. Me temo que ya no podemos hacer nada para salvarlos.', 28153),
(160660, 'esMX', '¡Hora de irnos, héroes! ¡No me pagan por quedarme esperando de brazos cruzados!', '¡Hora de irnos, héroes! ¡No me pagan por quedarme esperando de brazos cruzados!', 28153),
(160659, 'esMX', 'Magni Barbabronce te espera en Silithus. ¡Apresúrate! ¡La tierra misma se alza en nuestra contra!', '', 28153),
(160658, 'esMX', 'Magni Barbabronce necesita tu ayuda, adalid. Hablemos cuanto antes.', '', 28153),
(160657, 'esMX', '¡Debo hablar contigo, adalid!', '', 28153),
(160656, 'esMX', 'Adalid, debemos hablar. ¡Magni Barbabronce necesita tu asistencia!', '', 28153),
(160655, 'esMX', '¡Adalid! Traigo un mensaje urgente de Magni Barbabronce, el Portavoz de Azeroth.', '', 28153),
(160654, 'esMX', 'Estoy listo para partir.', 'Estoy lista para partir.', 28153),
(160653, 'esMX', '¿Todo listo para partir?', '¿Todo listo para partir?', 28153),
(160652, 'esMX', '', 'Una vez que se ha abierto una fisura, el dolor es... soportable. Solo... necesito un momento.', 28153),
(160650, 'esMX', '', 'Prepárense...', 28153),
(160649, 'esMX', '', '¡Atravesaremos el muro cuando dé la orden!', 28153),
(160648, 'esMX', '¡Se ha activado la autodestrucción!', '¡Se ha activado la autodestrucción!', 28153),
(160647, 'esMX', 'No, hay algo que no está bien. ¿Intentamos de nuevo?', '', 28153),
(160646, 'esMX', '', 'Mi pueblo resistirá.', 28153),
(160645, 'esMX', 'Estoy listo para partir.', 'Estoy lista para partir.', 28153),
(160644, 'esMX', '', '¡La Horda pagará por esta incursión!', 28153),
(160643, 'esMX', '', 'Elune... sálvanos.', 28153),
(160642, 'esMX', '', 'Sirvo a los kaldorei.', 28153),
(160641, 'esMX', '', 'Me alegra que estés con nosotros.', 28153),
(160640, 'esMX', '', 'Hay mucho que hacer.', 28153),
(160639, 'esMX', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Fuerza vital]|h|rdel avatar ha aumentado, ¡sánalo!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Fuerza vital]|h|r del avatar ha aumentado, ¡sánalo!', 28153),
(160638, 'esMX', 'Jinetes de grifos, despliéguense y regresen a formación. ¡Hemos terminado!', '', 28153),
(160637, 'esMX', 'Ya oíste a la general, Alapresta. ¡Llévanos de regreso a Boralus!', '', 28153),
(160636, 'esMX', '', 'Estamos listos para partir, Falstad.', 28153),
(160635, 'esMX', '¿La Horda está aquí? ¡Prefiero probar suerte con los tiburones!', '¿La Horda está aquí? ¡Prefiero probar suerte con los tiburones!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160634, 'esMX', 'Mejor que se vayan a que me apresure con mi plato. Cortar sandía exige una delicadeza violenta.', '', 28153),
(160633, 'esMX', 'Quizá debería cortar las sandías con tu lengua filosa, Grozzak.', '', 28153),
(160632, 'esMX', '¡Estoy cortando lo mejor que puedo!', '', 28153),
(160631, 'esMX', 'No puedes cortar sandía a las apuradas. Deja que el chef haga su trabajo.', '', 28153),
(160630, 'esMX', 'Necesito la sandía, si no los clientes se irán.', '', 28153),
(160629, 'esMX', 'Quizás esté desafilado, mi $Uamigo:amiga;.', '', 28153),
(160628, 'esMX', 'Parece mucho tiempo para cortar una sandía, Ka\'ro.', '', 28153),
(160627, 'esMX', 'Los clientes esperan. ¿Cuánto demorará esto?', '', 28153),
(160626, 'esMX', 'Mis Martillo Salvaje no podrán mantener a Nathanos y al resto de la Horda ocupados por mucho tiempo más. ¿Estás $Ulisto:lista; para partir?', '', 28153),
(160625, 'esMX', 'Azeroth será un lugar mejor sin ese príncipe de sangre. Buen trabajo, $p.', '', 28153),
(160624, 'esMX', 'Termina la pelea.', 'Termina la pelea.', 28153),
(160623, 'esMX', 'Hoy han hecho muchísimo por Boralus, héroes. Ahora es mi turno.', 'Hoy han hecho muchísimo por Boralus, héroes. Ahora es mi turno.', 28153),
(160622, 'esMX', 'Prepárate para saltar, $p. Te dejaré justo sobre el Borrasca Carmesí.', '', 28153),
(160621, 'esMX', '', '¿A qué loa te gustaría que le hiciera una estatua?', 28153),
(160620, 'esMX', 'Puedo llevarte hasta el Borrasca Carmesí, $p. Shandris te está esperando ahí.', '', 28153),
(160619, 'esMX', 'Nunca... escapará de las Tierras Plagadas...', '', 28153),
(160618, 'esMX', '¡Thros consume todo! ¡Jaina es nuestra!', '', 28153),
(160617, 'esMX', 'Me gustaría cambiar el loa de Vol\'Dun representado aquí.', 'Me gustaría cambiar el loa de Vol\'Dun representado aquí.', 28153),
(160616, 'esMX', 'Me gustaría cambiar el loa de Nazmir representado aquí.', 'Me gustaría cambiar el loa de Nazmir representado aquí.', 28153),
(160615, 'esMX', '', 'Iré a las afueras para alertar a los ciudadanos. Ve a los muelles, rápido. ¡Te veré allí!', 28153),
(160614, 'esMX', '', 'Entendido... Lady almirante.', 28153),
(160613, 'esMX', '', 'Parece que tu agasajo de bienvenida tendrá que esperar.', 28153),
(160612, 'esMX', '¡$n! ¡Has regresado! ¿Qué sucedió?', '', 28153),
(160611, 'esMX', '¡$n! Te estás desvanecien…', '', 28153),
(160609, 'esMX', 'Buena suerte.', '', 28153),
(160608, 'esMX', 'Me quedaré con nuestros guías y seré tu faro cuando necesites encontrar el camino de regreso a la orilla.', '', 28153),
(160607, 'esMX', 'Ruego que encontremos a los que buscamos. Pero ten cuidado. Esa isla rezuma maldad.', '', 28153),
(160606, 'esMX', 'No sé qué encontraremos cuando lleguemos a Límite del Destino, $p.', '', 28153),
(160605, 'esMX', '¿Qué? ¿Acaso te preocupaste? ¡Jaja! \n\n<tose>\n\nAh... todavía me duele un poco. Pero estaré bien.\n\nAdemás, he cumplido con mi trabajo.\n\nTú y Taelia regresen a Boralus y conviértanse en $Uhéroes:heroínas;.', '', 28153),
(160604, 'esMX', '', 'Ven, Amalia. Continuemos nuestra lección sobre lo que significa ser un Renegado.', 28153),
(160603, 'esMX', 'Muéstrame lo que tienes en venta.', 'Muéstrame lo que tienes en venta.', 28153),
(160602, 'esMX', 'Iba en busca de suministros cuando empecé a tener problemas con el motor. Aterricé de emergencia en este mismísimo lugar y esperé durante días para que llegara la ayuda.$b$b¿Alguna vez tuviste que sobrevivir en un pantano comiendo ramitas y musgo? ¡Yo sí!', '', 28153),
(160601, 'esMX', '', 'Envíale una señal a Falstad y acompáñame en los cielos. Regresaremos a Boralus $Ujuntos:juntas;.', 28153),
(160600, 'esMX', '', 'El príncipe de sangre Dreven está muerto. Debemos irnos antes de que Nathanos y los demás se recuperen de la distracción de los Martillo Salvaje.', 28153),
(160599, 'esMX', '', 'Anu\'dorini talah... monstruo.', 28153),
(160598, 'esMX', 'Gorak Tul... te destruirá...', '', 28153),
(160597, 'esMX', '¡Pagarás!', '', 28153),
(160596, 'esMX', '¿$UUn extraño:Una extraña; se atreve a profanar estos huesos?', '', 28153),
(160595, 'esMX', 'Oh, vaya, mi madre hacía lo mismo después de cocinar su célebre pastel.\n\nMuy bien, te mostraré... ¡el trabajo de toda mi vida!\n\nEstá en el cofre de atrás, ¡y es todo tuyo!\n\n¡Espero que haya valido la pena!', 'Oh, vaya, mi madre hacía lo mismo después de cocinar su célebre pastel.\n\nMuy bien, te mostraré... ¡el trabajo de toda mi vida!\n\nEstá en el cofre de atrás, ¡y es todo tuyo!\n\n¡Espero que haya valido la pena!', 28153),
(160594, 'esMX', '¿Huelo bien?', '¿Huelo bien?', 28153),
(160593, 'esMX', 'Ah, eso es excelente. Pero aún... ehh... mmm.', 'Ah, eso es excelente. Pero aún... ehh... mmm.', 28153),
(160592, 'esMX', 'Les he enviado algunos mensajes a tus enemigos. Ahora, en cuanto a esos secretos...', 'Les he enviado algunos mensajes a tus enemigos. Ahora, en cuanto a esos secretos...', 28153),
(160591, 'esMX', 'Soy yo, soy tu amigo. ¿Tienes secretos para contarme?', 'Soy yo, soy tu amiga. ¿Tienes secretos para contarme?', 28153),
(160590, 'esMX', '¡No tengo idea de qué estás hablando!', '¡No tengo idea de qué estás hablando!', 28153),
(160589, 'esMX', '¡Hola! No suelo recibir muchas visitas, tendrán que disculparme por el desorden.', '¡Hola! No suelo recibir muchas visitas, tendrán que disculparme por el desorden.', 28153),
(160588, 'esMX', '', '¡Diosa, dame fuerza!', 28153),
(160587, 'esMX', '', '¡No! No más trampas. No más huídas. No seguiré esperando para impartir justicia.', 28153),
(160586, 'esMX', 'El príncipe de sangre Dreven comienza a lanzar un hechizo para escapar.', '', 28153),
(160585, 'esMX', 'Ya me he cansado de tus patéticas habilidades de combate. Dejaré a un lado estas ideas raras.', '', 28153),
(160584, 'esMX', 'Siéntanse como en su casa.', 'Siéntanse como en su casa.', 28153),
(160583, 'esMX', 'Te recibiría con una sonrisa y un brindis, pero no tengo piel ni cerveza, ¡ay de mí!', 'Te recibiría con una sonrisa y un brindis, pero no tengo piel ni cerveza, ¡ay de mí!', 28153),
(160582, 'esMX', '¡Oh, hay visitas! Y yo que no tengo ropa decente.', '¡Oh, hay visitas! Y yo que no tengo ropa decente.', 28153),
(160581, 'esMX', '', 'La Alianza atacó. Te perdiste la diversión, $p.', 28153),
(160580, 'esMX', '¡Has vuelto! Hemos estado, eh, un poco ocupados mientras estabas ahí abajo.', '', 28153),
(160579, 'esMX', 'Le da un toque encantador.', '', 28153),
(160578, 'esMX', 'Niña tonta. Conocía sus nombres antes de arrancarles la vida de sus cuerpos frágiles.', '', 28153),
(160577, 'esMX', '¡Alapresta y yo te cuidaremos la espalda, $p! ¡Lanzaremos una lluvia de martillos desde los puertos!', '', 28153),
(160576, 'esMX', '', 'Me temo que ya es tarde para eso, Amalia. Tenemos visitas.', 28153),
(160575, 'esMX', '', 'Las fuerzas de Lady Valiente son implacables, Nathanos. Deberíamos salir de aquí cuanto antes.', 28153),
(160574, 'esMX', 'Ah, bien. No solo será un beneficio para la armada zandalari... también será un detrimento para los kultiranos.', '', 28153),
(160573, 'esMX', 'Hemos recuperado el cetro abisal, Nathanos.', '', 28153),
(160572, 'esMX', '¡Lo lograste, adalid! ¡La cámara está a salvo!', '', 28153),
(160571, 'esMX', '¡No! ¡El sello se resquebraja! ¡Resiste, muchacha! ¡Resiste por favor!', '', 28153),
(160570, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Recuerda observar mientras G\'huun lanza |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Recuerda observar mientras G\'huun lanza |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', 28153),
(160569, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t ¡Recoge la |cFFFF0404|Hspell:263420|h[Matriz de poder]|h|r para activar un |cFFFF0404|Hspell:263482|h[Estallido de reoriginación]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t ¡Recoge la |cFFFF0404|Hspell:263420|h[Matriz de poder]|h|r para activar un |cFFFF0404|Hspell:263482|h[Estallido de reoriginación]|h|r!', 28153),
(160568, 'esMX', 'Zeb\'ahari', 'Zeb\'ahari', 28153),
(160567, 'esMX', 'Avísame cuando estés $ulisto:lista; para avanzar al sitio del ritual, $n.', '', 28153),
(160566, 'esMX', '', 'Esto no puede ser bueno.', 28153),
(160565, 'esMX', '', 'Espera, ¿qué está pasando ahí abajo?', 28153),
(160564, 'esMX', '', '¿Quería probar sus nuevas armas... o hay algo más?', 28153),
(160563, 'esMX', '', 'No entiendo... ¿Por qué lady Aspafresno contrataría piratas para atacar la Puerta de Daelin?', 28153),
(160562, 'esMX', 'Ve con honor. Por la Horda.', '', 28153),
(160561, 'esMX', 'La próxima vez que te llame, tendremos que atacar Boralus, la capital kultirana.', '', 28153),
(160560, 'esMX', 'Hemos conseguido todas las piezas que necesitábamos.', '', 28153),
(160558, 'esMX', 'Vámonos entonces. Dile a Velandrajo que nuestro trabajo aquí ha terminado.', '', 28153),
(160557, 'esMX', 'Será mejor que nos vayamos antes de que regresen. No podemos arriesgarnos a que descubran nuestras últimas adquisiciones.', '', 28153),
(160556, 'esMX', 'La Alianza atacó mientras buceabas, $p. Nos encargamos de ellos, pero destruyeron nuestra otra nave.', '', 28153),
(160555, 'esMX', '', 'Sí. Incluso yo.', 28153),
(160554, 'esMX', '', '¿Incluso a ti?', 28153),
(160553, 'esMX', '', 'Dale tiempo, Stone. A todos nos lleva un tiempo acostumbrarnos a la vida después de la muerte.', 28153),
(160552, 'esMX', '', 'Sé que jamás me aceptarían... así, pero no puedo volverme contra mi pueblo.', 28153),
(160551, 'esMX', '', 'No puedo hacerlo, Lilian.', 28153),
(160550, 'esMX', 'Como desees.', '', 28153),
(160549, 'esMX', 'Excelente. Tú y $p, hablen con Hobart. Le dará a $p el conocimiento y el equipo necesario para bucear hasta el fondo del océano.', '', 28153),
(160548, 'esMX', 'Estoy seguro. Las mareas no mienten. Valentine está ahí abajo.', '', 28153),
(160547, 'esMX', '¿Este es el lugar?', '', 28153),
(160546, 'esMX', 'Sí, milord.', '', 28153),
(160545, 'esMX', 'Entrega las coordenadas a Velandrajo. Debemos partir cuanto antes.', '', 28153),
(160544, 'esMX', 'Es un tabú del que ya no tienes que preocuparte.', '', 28153),
(160543, 'esMX', 'Eso creo, sí. Aunque, debo decir que utilizar los poderes de un maresabio para recuperar un cadáver perdido en el mar... es...', '', 28153),
(160542, 'esMX', 'Zelling. ¿Estás seguro de que puedes encontrar la ubicación del cadáver del mariscal Valentine?', '', 28153),
(160541, 'esMX', '¿Tienes ganas de practicar? Bien por ti. Tienes que mantenerte en forma si no quieres terminar bajo tierra. Bueno, lo que tienes que hacer es ir a la parte más alta del muro que está por encima de Puerto Boralus.\n\nLa mejor manera de ir hasta allí es acercarte a Joan Weber, la maestra de vuelo del Mercado Vientos Alisios, y bajar por las escaleras que están a su izquierda. Síguelas y ve hacia el sur, pasando el puesto de control. Hay un pequeño claro donde entrenan mis compañeros.', '¿Tienes ganas de practicar? Bien por ti. Tienes que mantenerte en forma si no quieres terminar bajo tierra. Bueno, lo que tienes que hacer es ir a la parte más alta del muro que está por encima de Puerto Boralus.\n\nLa mejor manera de ir hasta allí es acercarte a Joan Weber, la maestra de vuelo del Mercado Vientos Alisios, y bajar por las escaleras que están a su izquierda. Síguelas y ve hacia el sur, pasando el puesto de control. Hay un pequeño claro donde entrenan mis compañeros.', 28153),
(160540, 'esMX', '', 'Tenemos que llegar a Boralus. ¡Debemos advertirle a lady almirante!', 28153),
(160539, 'esMX', '', 'Le contaré al teniente lo que ha sucedido. Búscame en Colina de la Vigilia cuando hayas terminado aquí.', 28153),
(160538, 'esMX', '', 'Pero podrían regresar. Y si llevan esas armas a Boralus...', 28153),
(160537, 'esMX', '', '¡Apresurémonos!', 28153),
(160536, 'esMX', '', 'Mensaje urgente de Nathanos. Los Valiente han anclado en Puerto Saqueo.', 28153),
(160535, 'esMX', '', 'Usa Disparo lacerante mientras atacas al muñeco de práctica.', 28153),
(160534, 'esMX', 'Usa Disparo lacerante mientras atacas al muñeco de práctica.', '', 28153),
(160533, 'esMX', '', 'El olor de la sangre enfurece a tu mascota y te otorga enfoque para usar en otras habilidades.', 28153),
(160532, 'esMX', 'El olor de la sangre enfurece a tu mascota y te otorga enfoque para usar en otras habilidades.', '', 28153),
(160531, 'esMX', '', 'También puedes atacar a tus enemigos con un Disparo lacerante para que reciban daño por sangrado con el transcurso del tiempo.', 28153),
(160530, 'esMX', '¡Tu faro atrajo a un tiburón ballena!', '¡Tu faro atrajo a un tiburón ballena!', 28153),
(160529, 'esMX', '', 'Lo logramos... ¡Realmente lo logramos!', 28153),
(160528, 'esMX', '¿Realmente quieres volver a invocar una gárgola en lugar de una val\'kyr?', '¿Realmente quieres volver a invocar una gárgola en lugar de una val\'kyr?', 28153),
(160527, 'esMX', '¿Realmente quieres aprender a invocar una val\'kyr en lugar de una gárgola?', '¿Realmente quieres aprender a invocar una val\'kyr en lugar de una gárgola?', 28153),
(160526, 'esMX', 'Parece que se fue.', 'Parece que se fue.', 28153),
(160525, 'esMX', 'No importa, le diré a Sylvanas que tú los mataste... ¡antes de matarte yo a ti!', '', 28153),
(160524, 'esMX', 'El problema con los no-muertos siempre ha sido la falta de carne en los huesos. Tuve que drenar a tres para equiparar el poder de un elfo de la noche.', '', 28153),
(160523, 'esMX', 'Sientes algo grande que nada en el agua cercana...', 'Sientes algo grande que nada en el agua cercana...', 28153),
(160522, 'esMX', '', 'No escaparás esta vez, abominación. Deberías haber muerto hace mucho tiempo.', 28153),
(160521, 'esMX', '', 'Conocerás los nombres de mis hermanas antes de caer, monstruo.', 28153),
(160520, 'esMX', '', 'Centinela Falia. Centinela Aeolyn. Centinela Lyrias.', 28153),
(160519, 'esMX', 'Abre bien los ojos, $n. No estamos en un sótano cualquiera, estamos en las profundidades de Boralus.', '', 28153),
(160518, 'esMX', '', 'Recuerda, terminarás en las profundidades de Boralus. Debes estar muy alerta.', 28153),
(160517, 'esMX', 'Regresemos a Zuldazar.', 'Regresemos a Zuldazar.', 28153),
(160516, 'esMX', '¡Hemos perdido todo!', '¡Hemos perdido todo!', 28153),
(160515, 'esMX', '¡Mira! Allí va $uel héroe:la heroína; que nos ayudó a escapar.', '¡Mira! Allí va $uel héroe:la heroína; que nos ayudó a escapar.', 28153),
(160514, 'esMX', 'Me imagino que no pensarán tenernos aquí indefinidamente, ¿verdad?', 'Me imagino que no pensarán tenernos aquí indefinidamente, ¿verdad?', 28153),
(160513, 'esMX', '¡Argh! ¡Aquí hay DEMASIADO brillo!', '¡Argh! ¡Aquí hay DEMASIADO brillo!', 28153),
(160512, 'esMX', 'La entrada a la cámara es por aquí. ¡Vamos!', '', 28153),
(160511, 'esMX', '¡Lordaeron pertenece a los Renegados!', '¡Lordaeron pertenece a los Renegados!', 28153),
(160510, 'esMX', '', 'Llegamos en el momento justo. Thorgen no habría sobrevivido mucho tiempo más sin refuerzos... a pesar de que el enano seguramente dirá otra cosa.', 28153),
(160509, 'esMX', 'Has vuelto. ¿Estás $listo:lista; para volver a zambullirte?', '', 28153),
(160508, 'esMX', 'Quiero volver a invocar una gárgola en vez de una val\'kyr con mi hechizo Invocar gárgola.', 'Quiero volver a invocar una gárgola en vez de una val\'kyr con mi hechizo Invocar gárgola.', 28153),
(160507, 'esMX', 'Quiero aprender a invocar una val\'kyr en vez de una gárgola con mi hechizo Invocar gárgola.', 'Quiero aprender a invocar una val\'kyr en vez de una gárgola con mi hechizo Invocar gárgola.', 28153),
(160506, 'esMX', '¿La Horda? Toma lo que quieras, ¡pero no me mates!', '', 28153),
(160505, 'esMX', 'Ey, ¡devuélveme eso!', '', 28153),
(160504, 'esMX', '<Recoge el cadáver de Derek Valiente>', '<Recoge el cadáver de Derek Valiente>', 28153),
(160503, 'esMX', '<Recoge el cadáver del mariscal Valentine>', '<Recoge el cadáver del mariscal Valentine>', 28153),
(160502, 'esMX', '¡Las almAs se alImMeNtan del sUfrimientO eTernO, en la oBsCuridad soLlozan sIn ConsuElo, y juNto a Ellas haS de padeCer en todO momeNto!', '¡Las almAs se alImMeNtan del sUfrimientO eTernO, en la oBsCuridad soLlozan sIn ConsuElo, y juNto a Ellas haS de padeCer en todO momeNto!', 28153),
(160501, 'esMX', '', '¡Las fuerzas de la Horda avanzan sobre Lor\'danel! ¡Adalid, vamos!', 28153),
(160500, 'esMX', '', '¡Atrápalo, camarada! ¡Usa el ataque de tu mascota de batalla!', 28153),
(160499, 'esMX', '', '¡Come estrellas, malo!', 28153),
(160498, 'esMX', '', '¡Ohhh! ¡Sé lo que hacer con tipos como este!', 28153),
(160497, 'esMX', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Valiente\n\nPríncipe heredero de Kul Tiras', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Valiente\n\nPríncipe heredero de Kul Tiras', 28153),
(160496, 'esMX', '', '¡Tu magia de sangre nefasta no podrá protegerte, Dreven!', 28153),
(160495, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMariscal M. Valentine\n\nCapitán del Orgullo de Tiragarde\nMariscal de la tercera flota kultirana', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMariscal M. Valentine\n\nCapitán del Orgullo de Tiragarde\nMariscal de la tercera flota kultirana', 28153),
(160494, 'esMX', 'No hace falta que resalte la importancia de esta misión, $n. La Dama Oscura depende de nosotros para que su voluntad se cumpla.', '', 28153),
(160493, 'esMX', '', 'Atacaremos al príncipe de sangre Dreven juntos. Nada de piedad. Nada de escapar.', 28153),
(160492, 'esMX', 'Ven a hablarme cuando estés en condiciones de empezar.', '', 28153),
(160491, 'esMX', '¡Sí! Esa es su nave insig... Momento, no. Es una mancha en el lente.', '¡Sí! Esa es su nave insig... Momento, no. Es una mancha en el lente.', 28153),
(160490, 'esMX', '¿Ya has visto a los kultiranos?', '¿Ya has visto a los kultiranos?', 28153),
(160489, 'esMX', '¡La caja de acertijo reacciona ante la proyección de Yogg-Saron!', '¡La caja de acertijo reacciona ante la proyección de Yogg-Saron!', 28153),
(160488, 'esMX', 'Los Mag\'har están condenados, Geya\'rah. Pero me he asegurado de que mi clan perdure mucho después de que el tuyo sea polvo.', '', 28153),
(160487, 'esMX', '', '|TInterface\\Icons\\Ability_Mage_RayofFrost:20|t¡%s activa los|cFFFF0000|Hspell:268253|h[Haces defensivos de Uldir]|h|r!', 28153),
(160486, 'esMX', '', '¡Silencio! Si no te calmas, tendré que calmarte por la fuerza.', 28153),
(160485, 'esMX', 'Ey, ¡dame una mano con estas cuerdas!', 'Ey, ¡dame una mano con estas cuerdas!', 28153),
(160484, 'esMX', '¡No dejes que me coman!', '¡No dejes que me coman!', 28153),
(160483, 'esMX', '¡Ayuda!', '¡Ayuda!', 28153),
(160482, 'esMX', 'No puedes proteger ni a tu propia gente, hija de los lobos. ¿Por qué deberíamos seguirte?', '', 28153),
(160481, 'esMX', '', '¿A qué se debe esta revuelta, Kor\'gall? Sabes que debemos unirnos, ahora más que nunca.', 28153),
(160480, 'esMX', 'Me gustaría elegir a Akunda, loa de las tormentas.', 'Me gustaría elegir a Akunda, loa de las tormentas.', 28153),
(160479, 'esMX', 'Me gustaría elegir a Kimbul, señor de las bestias.', 'Me gustaría elegir a Kimbul, señor de las bestias.', 28153),
(160478, 'esMX', 'Me gustaría elegir a Bwonsamdi, loa de la muerte.', 'Me gustaría elegir a Bwonsamdi, loa de la muerte.', 28153),
(160477, 'esMX', 'Me gustaría elegir a Krag\'wa el Gigante.', 'Me gustaría elegir a Krag\'wa el Gigante.', 28153),
(160476, 'esMX', '', 'Parece que el mariscal Valentine entregó nuestro mensaje. La flota Valiente ha mordido la carnada.', 28153),
(160475, 'esMX', '', 'El puesto de avanzada está demasiado cerca de la ciudad, y eso es muy peligroso, pero está bastante oculto y nos permite ver el Trono Dorado a la perfección.\n\nDesde este sitio, nuestros espías podrán seguir de cerca los movimientos del rey Rastakhan y de la Horda.', 28153),
(160474, 'esMX', 'Estoy listo para empezar.', 'Estoy lista para empezar.', 28153),
(160473, 'esMX', 'Si queremos que el ritual de salvoconducto funcione, tendremos que trabajar a la par. \n\n¿$uEstás listo:Estás lista;?', '', 28153),
(160472, 'esMX', 'Un poco... macabro, ¿no crees? Supongo que si quisiéramos llamar la atención de lady Valiente...', '', 28153),
(160471, 'esMX', '¡Fuego!', '¡Fuego!', 28153),
(160470, 'esMX', '¡Llamen a los bomberos!', '¡Llamen a los bomberos!', 28153),
(160469, 'esMX', '¡Fuego! ¡Fuego!', '¡Fuego! ¡Fuego!', 28153),
(160468, 'esMX', 'No debe haber sido fácil. Mantén los ojos bien abiertos.', 'No debe haber sido fácil. Mantén los ojos bien abiertos.', 28153),
(160467, 'esMX', '¿Cómo crees que llegaron hasta las Mazmorras?', '¿Cómo crees que llegaron hasta las Mazmorras?', 28153),
(160466, 'esMX', '¿Hay algo que esa miserable de Brisaveloz no esté dispuesta a intentar a esta altura?', '¿Hay algo que esa miserable de Brisaveloz no esté dispuesta a intentar a esta altura?', 28153),
(160465, 'esMX', 'Oí que querían asesinar al rey.', 'Oí que querían asesinar al rey.', 28153),
(160464, 'esMX', 'No pueden intentar atacar la ciudad con esa cantidad de hombres.', 'No pueden intentar atacar la ciudad con esa cantidad de hombres.', 28153),
(160463, 'esMX', 'No puedo dejar pasar a nadie. Órdenes del rey.', 'No puedo dejar pasar a nadie. Órdenes del rey.', 28153),
(160462, 'esMX', 'Ustedes y sus familias no corren peligro. Regresen a sus hogares de inmediato.', 'Ustedes y sus familias no corren peligro. Regresen a sus hogares de inmediato.', 28153),
(160461, 'esMX', 'Ya les he dicho todo lo que sé. Regresen a sus hogares.', 'Ya les he dicho todo lo que sé. Regresen a sus hogares.', 28153),
(160460, 'esMX', 'Por favor, mi hija vive en el Distrito de Mercaderes. ¡Necesito ir con ella!', 'Por favor, mi hija vive en el Distrito de Mercaderes. ¡Necesito ir con ella!', 28153),
(160459, 'esMX', '¡Déjenme pasar de inmediato! Exijo hablar con tu superior.', '¡Déjenme pasar de inmediato! Exijo hablar con tu superior.', 28153),
(160458, 'esMX', '¿Qué es todo este alboroto? ¿Tienes idea de la hora que es?', '¿Qué es todo este alboroto? ¿Tienes idea de la hora que es?', 28153),
(160457, 'esMX', '¿Cuántos son? ¿Nos están atacando?', '¿Cuántos son? ¿Nos están atacando?', 28153),
(160456, 'esMX', '¿Crees que el rey corre peligro?', '¿Crees que el rey corre peligro?', 28153),
(160455, 'esMX', 'No te preocupes. Ve adentro y ocúltate como te enseñé.', 'No te preocupes. Ve adentro y ocúltate como te enseñé.', 28153),
(160454, 'esMX', 'Siento temor...', 'Siento temor...', 28153),
(160453, 'esMX', '¿Qué sucede? ¿Por qué está cerrada la puerta?', '¿Qué sucede? ¿Por qué está cerrada la puerta?', 28153),
(160452, 'esMX', 'No quiero problemas, $r.', 'No quiero problemas, $r.', 28153),
(160451, 'esMX', 'Mmm. ¿Se supone que están aquí...?', 'Mmm. ¿Se supone que están aquí...?', 28153),
(160450, 'esMX', '¿Así es como cae Ventormenta? Ja. ¡Tengo un asiento en primera fila!', '¿Así es como cae Ventormenta? Ja. ¡Tengo un asiento en primera fila!', 28153),
(160449, 'esMX', '¡Guardias! ¡¿Guardias?!', '¡Guardias! ¡¿Guardias?!', 28153),
(160448, 'esMX', 'Atrás. No planeo morir aquí.', 'Atrás. No planeo morir aquí.', 28153),
(160447, 'esMX', '¡Sí! ¡Tú eres mi boleto para salir de aquí, $r!', '¡Sí! ¡Tú eres mi boleto para salir de aquí, $r!', 28153),
(160446, 'esMX', '¡Ey! ¡Ven aquí y déjame salir!', '¡Ey! ¡Ven aquí y déjame salir!', 28153),
(160445, 'esMX', '¿Qué está sucediendo? ¡¿Qué hace la Horda aquí?!', '¿Qué está sucediendo? ¡¿Qué hace la Horda aquí?!', 28153),
(160444, 'esMX', 'Cuando hayan desplegado a sus guardias más fuertes, nuestro amigo Oculeth abrirá un portal para que $n y Zelling atraviesen y tomen el cetro.', '', 28153),
(160443, 'esMX', 'En cualquier momento, las fuerzas de élite de Valiente llegarán para intentar recuperar el cadáver de Derek.', '', 28153),
(160442, 'esMX', 'Este es Hannibal, el halcón mensajero más rápido de todo Kul Tiras.', '', 28153),
(160441, 'esMX', '¡Una unidad de eliminación de desechos se abre y forma una masa mutada!', '¡Una unidad de eliminación de desechos se abre y forma una masa mutada!', 28153),
(160440, 'esMX', '¡Adalid! ¡Azeroth pide a gritos tu ayuda! Ven a Silithus. Hay algo que tienes que ver.', '', 28153),
(160439, 'esMX', 'Esto no está bien. ¡Se supone que yo debería estar ganando!', '', 28153),
(160438, 'esMX', 'Centro de entrenamiento para duelos de mascotas de Fornido. Me gusta cómo suena. ¡Y ahora estoy un paso más cerca de vencerte!', '', 28153),
(160437, 'esMX', 'Ahora que lo pienso, creo que debería diversificar un poco mi alineación de mascotas. Tres del mismo tipo... ¿en qué estaba pensando?', '', 28153),
(160436, 'esMX', 'Con todos esos pinchos y esas caras de malos, ¿de veras creíste que podías ganar?', '', 28153),
(160435, 'esMX', 'Estos pequeñines son muy extraños, pero tienen muchísima fuerza. ¿Estás $useguro:segura; de que quieres luchar?', '', 28153),
(160434, 'esMX', '', 'Inesperado.', 28153),
(160433, 'esMX', '', '¡Aniquilado!', 28153),
(160432, 'esMX', '', 'Esto sí que no me lo esperaba. La próxima vez que nos encontremos estaré preparada, te lo aseguro.', 28153),
(160431, 'esMX', '', 'Te lo había dicho al principio: mi equipo es claramente superior.', 28153),
(160430, 'esMX', '', 'Antes de comenzar, me gustaría recordarte que no hace falta que te sientas mal cuando mi equipo aniquile al tuyo.', 28153),
(160429, 'esMX', 'El olor de la sangre en el agua atraerá a más tiburones.', '', 28153),
(160428, 'esMX', '¡Hora de comer, muchachos!', '', 28153),
(160427, 'esMX', 'Me importa muy poco que me hayas vencido. Yo me quedaré aquí abajo por toda la eternidad. Por lo menos hoy pude hablar con alguien.', '', 28153),
(160426, 'esMX', 'Una persona contra un tiburón quizá sea una lucha pareja. ¿Una persona contra tres tiburones? Has perdido la razón.', '', 28153),
(160425, 'esMX', 'Si quieres vencer a alguien como yo, necesitarás un barco más grande para llevarte a tus criaturas de aquí.', '', 28153),
(160424, 'esMX', '', 'Tu determinación es admirable, pero el resultado de esta batalla ya estaba decidido.', 28153),
(160423, 'esMX', '', '¡Vuelve al lugar de donde saliste!', 28153),
(160422, 'esMX', '', 'Esto no es lo que tenía que pasar. Las profecías decían otra cosa.', 28153),
(160421, 'esMX', '', 'Necesitas entrenar muchísimo más si esperas ganarle a una maestra como yo.', 28153),
(160420, 'esMX', '', 'Las extrañas criaturas de esta isla prometen brindarnos una batalla más extraña aún.', 28153),
(160419, 'esMX', '', 'Parece que naciste para carnada y no para miembro de mi equipo.', 28153),
(160418, 'esMX', '', '¡Alguien se fue a dormir con los peces!', 28153),
(160417, 'esMX', '', 'Parece que los peces no solo mueren por la boca...', 28153),
(160416, 'esMX', '', '¡Como pez en el agua!', 28153),
(160415, 'esMX', '', 'He encontrado las criaturas marinas más poderosas de todas. No tienes posibilidades de vencerme.', 28153),
(160414, 'esMX', 'Siempre que entreno abejas nuevas pasa lo mismo. Se vuelven grandes, fuertes y parecen invencibles. Después pican a alguien y se mueren...', '', 28153),
(160413, 'esMX', '¡Punto para las abejas!', '', 28153),
(160412, 'esMX', '¡Mis abejas no! ¡No!', '', 28153),
(160411, 'esMX', 'Las abejas son muy superiores, y esto lo demuestra.', '', 28153),
(160410, 'esMX', 'Recuerda que fuiste tú quien pidió esto.', '', 28153),
(160409, 'esMX', '', 'Esa era mi favorita... ¡Hora de poner en cancha a las mascotas más duras! ¡Prepárense!', 28153),
(160408, 'esMX', '', '¡Punto para el equipo Fizzie!', 28153),
(160407, 'esMX', '', '¡Pero mis mascotas están insufladas con azerita! ¡A las mascotas les encanta la azerita!', 28153),
(160406, 'esMX', '', 'La verdad, no me sorprende. Mi equipo es mucho mejor.', 28153),
(160405, 'esMX', '', '¿Crees que tus mascotas tienen posibilidades de vencer a mi equipo insuflado con azerita? ¡Sigue soñando!', 28153),
(160404, 'esMX', '', 'Hay muchas criaturas en Zuldazar. Algunas son pequeñas y otras, enormes. Me tomaré el trabajo de capturar y entrenar a las criaturas más pequeñas para demostrarles a todos que desde algo muy pequeño se pueden conseguir cosas grandiosas.', 28153),
(160403, 'esMX', '', 'Reúnete conmigo bajo cubierta cuando termines. Encontraré una manera de destruir la barrera que protege al príncipe de sangre Dreven.', 28153),
(160402, 'esMX', '¡El Devorador fétido ha |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t usado |cFFFF0000|Hspell:262370|h[Consumir corrupción]|h|r con éxito! ¡Debes matar a los corpúsculos de corrupción cuando aparezcan!', '¡El Devorador fétido ha |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t usado |cFFFF0000|Hspell:262370|h[Consumir corrupción]|h|r con éxito! ¡Debes matar a los corpúsculos de corrupción cuando aparezcan!', 28153),
(160401, 'esMX', 'Shandris te esperará a bordo. Mucha suerte.', '', 28153),
(160400, 'esMX', '¡Buen lanzamiento! Ahora, te llevaremos al Borrasca Carmesí.', '', 28153),
(160399, 'esMX', '', '¡Aaaaargh!', 28153),
(160398, 'esMX', '', '¡SÍIIII! ¡La sangre de G\'huun corre por nuestras venas!', 28153),
(160397, 'esMX', '', 'La sangre del maestro... nuestra carne, ¡nuestras vidas por G\'huun!', 28153),
(160396, 'esMX', 'Te tengo, Alapresta. Ningún cañón de la Horda nos derribará hoy.', '', 28153),
(160395, 'esMX', '¡Vaya! ¡Esto es grandioso! ¡Gracias, $Useñor:señora;!', '¡Vaya! ¡Esto es grandioso! ¡Gracias, $Useñor:señora;!', 28153),
(160394, 'esMX', '¿Nos...? ¿Nos trajiste... dulces nuevos? ¿Más ricos?', '¿Nos...? ¿Nos trajiste... dulces nuevos? ¿Más ricos?', 28153),
(160393, 'esMX', '¡Eh! ¡Tú eres $Uel:la; $r que se llevó nuestro dulce!', '¡Eh! ¡Tú eres $Uel:la; $r que se llevó nuestro dulce!', 28153),
(160392, 'esMX', '<Después de saquear el cofre, solo quedan algunos envoltorios de caramelos... Envoltorios y una vergüenza que te carcome el alma.>', '<Después de saquear el cofre, solo quedan algunos envoltorios de caramelos... Envoltorios y una vergüenza que te carcome el alma.>', 28153),
(160391, 'esMX', '<Coloca un dulce mejor en el cofre.>', '<Coloca un dulce mejor en el cofre.>', 28153),
(160390, 'esMX', 'No puedo esperar a sumergirme en los secretos de Xibala. ¡Este lugar es muy misterioso!\n\n¿Quién es Xibala? ¿Qué es Xibala? ¿Por qué los zandalari abandonaron este lugar? ¿Qué hace el Ojo de Xibala?\n\n¡Sin duda alguna, la examinadora Tae\'shra nos guiará hasta la respuestas!', 'No puedo esperar a sumergirme en los secretos de Xibala. ¡Este lugar es muy misterioso!\n\n¿Quién es Xibala? ¿Qué es Xibala? ¿Por qué los zandalari abandonaron este lugar? ¿Qué hace el Ojo de Xibala?\n\n¡Sin duda alguna, la examinadora Tae\'shra nos guiará hasta la respuestas!', 28153),
(160389, 'esMX', '¿Crees que Astrandis podría presentarme al jefe telemante Oculeth...?\n\nHe oído mucho sobre él. ¿Crees que me firmaría mi tabardo?', '¿Crees que Astrandis podría presentarme al jefe telemante Oculeth...?\n\nHe oído mucho sobre él. ¿Crees que me firmaría mi tabardo?', 28153),
(160388, 'esMX', 'Son admirables. Después de vivir una breve eternidad recluidos en un mundo de sillones de felpa y vino, estos Natonocturno no están teniendo problemas para adaptarse a los vigores del mundo más allá de sus fronteras.\n\n¡Hasta pude enseñarle a uno a usar una pala!', 'Son admirables. Después de vivir una breve eternidad recluidos en un mundo de sillones de felpa y vino, estos Natonocturno no están teniendo problemas para adaptarse a los vigores del mundo más allá de sus fronteras.\n\n¡Hasta pude enseñarle a uno a usar una pala!', 28153),
(160387, 'esMX', 'La examinadora Tae\'shara es una mujer de paciencia inagotable. Una digna sucesora de su padre, si decide rescindir su posición.\n\nAunque, me pregunto si ese tal Astrandis está poniendo a prueba su inmensa tolerancia.', 'La examinadora Tae\'shara es una mujer de paciencia inagotable. Una digna sucesora de su padre, si decide rescindir su posición.\n\nAunque, me pregunto si ese tal Astrandis está poniendo a prueba su inmensa tolerancia.', 28153),
(160386, 'esMX', 'El Relicario no dejó pasar la oportunidad de excavar en un sitio como este. Tenemos suerte de que los trols que viven aquí no se hayan quejado.', 'El Relicario no dejó pasar la oportunidad de excavar en un sitio como este. Tenemos suerte de que los trols que viven aquí no se hayan quejado.', 28153),
(160385, 'esMX', 'Le ofrecí una piqueta a un Natonocturno. Jamás vi a alguien tan desconcertado.\n\n\"¿Para qué sirve?\", me preguntó, como si no pudiese aventurar la más mínima respuesta.\n\nSu poderío mágico habla muy bien de su raza, pero tienen mucho que aprender sobre el mundo. Por suerte, los sin\'dorei estamos bien equipados para enseñarles', 'Le ofrecí una piqueta a un Natonocturno. Jamás vi a alguien tan desconcertado.\n\n\"¿Para qué sirve?\", me preguntó, como si no pudiese aventurar la más mínima respuesta.\n\nSu poderío mágico habla muy bien de su raza, pero tienen mucho que aprender sobre el mundo. Por suerte, los sin\'dorei estamos bien equipados para enseñarles', 28153),
(160384, 'esMX', 'Los Natonocturno han resultado muy útiles durante esta expedición, pero no de las formas que imaginaba.\n\nEs cierto que amenizan el ambiente del viaje, y es un respiro agradable de la típica rudeza del campamento.\n\n<Bebe de su copa de vino.>', 'Los Natonocturno han resultado muy útiles durante esta expedición, pero no de las formas que imaginaba.\n\nEs cierto que amenizan el ambiente del viaje, y es un respiro agradable de la típica rudeza del campamento.\n\n<Bebe de su copa de vino.>', 28153),
(160383, 'esMX', 'No mires ahora, pero creo que ese shal\'dorei está usando su herramienta al revés.', 'No mires ahora, pero creo que ese shal\'dorei está usando su herramienta al revés.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160382, 'esMX', 'Debo confesar que no sabía en qué me estaba metiendo cuando accedí a visitar esta tierra extraña.\n\nEs más cálida de lo que esperaba. Mucho más cálida. Pero es una oportunidad inestimable para avanzar la causa de la Primera Arcanista y congraciarnos con nuestros nuevos aliados.\n\nSupongo que es una excelente razón para aguantársela sin chistar.\n\n<Esboza una sonrisa forzada.>', 'Debo confesar que no sabía en qué me estaba metiendo cuando accedí a visitar esta tierra extraña.\n\nEs más cálida de lo que esperaba. Mucho más cálida. Pero es una oportunidad inestimable para avanzar la causa de la Primera Arcanista y congraciarnos con nuestros nuevos aliados.\n\nSupongo que es una excelente razón para aguantársela sin chistar.\n\n<Esboza una sonrisa forzada.>', 28153),
(160381, 'esMX', 'Espero que les demos una buena impresión a los zandalari. Fueron muy amables, ¡y reacios!, al darnos la oportunidad de estudiar este sitio.', 'Espero que les demos una buena impresión a los zandalari. Fueron muy amables, ¡y reacios!, al darnos la oportunidad de estudiar este sitio.', 28153),
(160380, 'esMX', '¿Crees que nuestros aliados del Relicario me permitan utilizar uno de estos cepillos diminutos...?', '¿Crees que nuestros aliados del Relicario me permitan utilizar uno de estos cepillos diminutos...?', 28153),
(160379, 'esMX', 'Nuestros aliados sin\'dorei me han estado deleitando con historias de sus expediciones pasadas. Detecto un tema recurrente en sus encuentros con los enanos.', 'Nuestros aliados sin\'dorei me han estado deleitando con historias de sus expediciones pasadas. Detecto un tema recurrente en sus encuentros con los enanos.', 28153),
(160378, 'esMX', '¿Crees que los trols nos permitirán llevarnos una de estas criaturas de cuello largo a Suramar...? ¡A Su\'esh le encantaría tener un compañero!\n\n¡Quizás deberías preguntarles!', '¿Crees que los trols nos permitirán llevarnos una de estas criaturas de cuello largo a Suramar...?\n\n¡Quizás deberías preguntarles!', 28153),
(160377, 'esMX', '<Mata un mosquito.>\n\n¡Las cosas que tenemos que soportar para demostrar nuestra valía ante la Horda! ¡Estas condiciones laborales son paupérrimas!', '<Mata un mosquito.>\n\n¡Las cosas que tenemos que soportar para demostrar nuestra valía ante la Horda! ¡Estas condiciones laborales son paupérrimas!', 28153),
(160376, 'esMX', '<Se abanica vigorosamente con una mano.>\n\nAntes de esto, no había podido apreciar el clima de Suramar. Será un alivio grato regresar a casa cuando esta excavación haya terminado.', '<Se abanica vigorosamente con una mano.>\n\nAntes de esto, no había podido apreciar el clima de Suramar. Será un alivio grato regresar a casa cuando esta excavación haya terminado.', 28153),
(160375, 'esMX', 'Leí sobre las selvas en la biblioteca, ¡pero por alguna razón olvidé mencionar el calor infernal!\n\nSe me pega la ropa. Hay insectos. ¡Insectos!\n\n¿A quién se le ocurriría vivir aquí?', 'Leí sobre las selvas en la biblioteca, ¡pero por alguna razón olvidé mencionar el calor infernal!\n\nSe me pega la ropa. Hay insectos. ¡Insectos!\n\n¿A quién se le ocurriría vivir aquí?', 28153),
(160374, 'esMX', 'Ah, esos dos. Los encontrará\' discutiendo dentro del Gran Sello. Están sobre el balcón de la parte este.\n\nCasi no me dan ganas de ir allí cuando eh\'tán ellos. Aunque tengo que admitir que estoy de acuerdo con el tauren. En casi todo...', 'Ah, esos dos. Los encontrará\' discutiendo dentro del Gran Sello. Están sobre el balcón de la parte este.\n\nCasi no me dan ganas de ir allí cuando eh\'tán ellos. Aunque tengo que admitir que estoy de acuerdo con el tauren. En casi todo...', 28153),
(160373, 'esMX', 'Te recomiendo hablar con Cringely y Ulla. Los encontrarás discutiendo sobre las políticas de la jefa de guerra. De más está decir que Cringely está en lo cierto y que Ulla, pobrecita, es muy obstinada.\n\nEstán siempre en el Gran Sello. En el balcón del este, sobre la galería.', 'Te recomiendo hablar con Cringely y Ulla. Los encontrarás discutiendo sobre las políticas de la jefa de guerra. De más está decir que Cringely está en lo cierto y que Ulla, pobrecita, es muy obstinada.\n\nEstán siempre en el Gran Sello. En el balcón del este, sobre la galería.', 28153),
(160372, 'esMX', '¡Tenemos bacalao! ¡Preparado y listo para comer!', '', 28153),
(160371, 'esMX', '¡Pesca del día! ¡Tiburón fresco, capturado esta mañana!', '', 28153),
(160370, 'esMX', 'Ayúdennos a atravesar la tormenta.', '', 28153),
(160369, 'esMX', 'Guíennos por las aguas traicioneras, que ahora son su dominio.', '', 28153),
(160368, 'esMX', 'Rompan el velo y pisen la orilla.', '', 28153),
(160367, 'esMX', 'Almas que el mar devoró, regresen.', '', 28153),
(160366, 'esMX', 'Somos los faros que las guiarán a casa.', '', 28153),
(160365, 'esMX', 'Levantamos nuestros faroles sobre las aguas oscuras.', '', 28153),
(160364, 'esMX', 'Su tañido las lleva a casa.', '', 28153),
(160363, 'esMX', 'Oigan nuestras campanas resonar sobre la canción de la tormenta.', '', 28153),
(160362, 'esMX', 'Regresen a casa sobre aguas tranquilas y corrientes suaves.', '', 28153),
(160361, 'esMX', 'Con sangre amansamos el océano salvaje que se las llevó.', '', 28153),
(160360, 'esMX', 'Dejen el abrazo del abismo y ayuden a sus hermanos otra vez.', '', 28153),
(160359, 'esMX', 'Almas cansadas perdidas en las profundidades, respondan.', '', 28153),
(160358, 'esMX', 'Viento y corrientes, lleven nuestra súplica.', '', 28153),
(160357, 'esMX', '', '¡Preparadas con la mejor carne de los Reinos del Este! ¡Directo desde Amparo del Ocaso!', 28153),
(160356, 'esMX', '', '¡Salchichas! ¡Salchichas frescas de Drustvar y Ventormenta!', 28153),
(160355, 'esMX', '', '¡Nada mejor que probar una cerveza exótica mientras das un paseo por el mercado! Y si la cerveza no es lo tuyo, ¡tengo una gran variedad de tés!', 28153),
(160354, 'esMX', '', '¡Cerveza, cerveza! ¡Barriles directo de Pandaria!', 28153),
(160353, 'esMX', '¡Ey! ¡Tú! ¡Sí, tú! Tengo algo que quizá pueda interesarle a una persona de tu... vocación.', '', 28153),
(160352, 'esMX', 'Nuestra jefa de guerra nos necesita más rápidos y organizados que nunca. ¿Qué sacrificará tu hermandad para avanzar la causa de la Horda?', '', 28153),
(160351, 'esMX', '', '¡Repollos frescos! ¡Cultivados en la zona!', 28153),
(160350, 'esMX', '', '¡Vegetales frescos directo de las granjas de Canto Tormenta! ¡El mejor maíz que probarás en tu vida!', 28153),
(160349, 'esMX', 'No sé dónde está la nave ahora.', 'No sé dónde está la nave ahora.', 28153),
(160348, 'esMX', 'El Implacable debería haber partido hace un instante del muelle de Ventormenta.', 'El Implacable debería haber partido hace un instante del muelle de Ventormenta.', 28153),
(160347, 'esMX', 'El Implacable debería haber partido hace un instante de Boralus.', 'El Implacable debería haber partido hace un instante de Boralus.', 28153),
(160346, 'esMX', 'Si alguna vez necesitas resolver cualquier problema relacionado con zapatos, ven a verme. ¡Disfruta de tu nuevo brillo!', '', 28153),
(160345, 'esMX', 'Una pulida de zapatos, ¡en camino!', '', 28153),
(160344, 'esMX', '¿Ere\' $uun:una; profesional? Bien. Siempre nos vienen bien más como tú. Si buscas las herramienta\' de tu profesión, ve a hablar con el tauren llamado Hanul Ventoveloz. Búscalo en el Salón de los Paso\' Ancestrale\', que se encuentra en la parte este del Gran Sello.', '¿Ere\' $uun:una; profesional? Bien. Siempre nos vienen bien más como tú. Si buscas las herramienta\' de tu profesión, ve a hablar con el tauren llamado Hanul Ventoveloz. Búscalo en el Salón de los Paso\' Ancestrale\', que se encuentra en la parte este del Gran Sello.', 28153),
(160343, 'esMX', 'Si buscas objetos comerciables, te recomiendo ir al Gran Sello. Cuando entres, camina hacia el este y busca el Salón de los Pasos Ancestrales. Allí encontrarás a un tauren llamado Hanul Ventoveloz. Él te dará todo lo que necesites.', 'Si buscas objetos comerciables, te recomiendo ir al Gran Sello. Cuando entres, camina hacia el este y busca el Salón de los Pasos Ancestrales. Allí encontrarás a un tauren llamado Hanul Ventoveloz. Él te dará todo lo que necesites.', 28153),
(160342, 'esMX', '¿Víveres? La Horda trajo de todo cuando llegó a eh\'te lugar. Habla con la orco Araka, que está dentro del Salón de los Pasos Ancestrale\'. Hay un cuarto en la parte este del Gran Sello donde encontrarás todos los vívere\' que necesites.', '¿Víveres? La Horda trajo de todo cuando llegó a eh\'te lugar. Habla con la orco Araka, que está dentro del Salón de los Pasos Ancestrale\'. Hay un cuarto en la parte este del Gran Sello donde encontrarás todos los vívere\' que necesites.', 28153),
(160341, 'esMX', 'Araka puede ayudarte. Está dentro del Salón de los Pasos Ancestrales, en la parte este del Gran Sello.', 'Araka puede ayudarte. Está dentro del Salón de los Pasos Ancestrales, en la parte este del Gran Sello.', 28153),
(160340, 'esMX', '¿Quieres crear una hermandad nueva? Entonces ve con el guardián del puerto Finnson y Perry Charlton. Son una pareja un poco turbia, pero te mostrarán de qué va la cosa.\n\nBúscalos en el edificio que está en la entrada del puerto que da a la ciudad.', '¿Quieres crear una hermandad nueva? Entonces ve con el guardián del puerto Finnson y Perry Charlton. Son una pareja un poco turbia, pero te mostrarán de qué va la cosa.\n\nBúscalos en el edificio que está en la entrada del puerto que da a la ciudad.', 28153),
(160339, 'esMX', 'No hay nadie mejor que Leila Stafford. Me ayudó muchísimo cuando mi hermosa Esponjín estaba enferma.\n\nLa encontrarás en la parte superior del Mercado Vientos Alisios, del lado oeste.', 'No hay nadie mejor que Leila Stafford. Me ayudó muchísimo cuando mi hermosa Esponjín estaba enferma.\n\nLa encontrarás en la parte superior del Mercado Vientos Alisios, del lado oeste.', 28153),
(160338, 'esMX', 'Teníamos un barbero, pero desapareció así como si nada no hace mucho y nadie sabe qué le pasó. Fue lo único de lo que se habló durante todo un día.\n\nAhora este gnomo ha ocupado la antigua barbería. No estoy sugiriendo nada, no me malinterpretes, pero si estás buscando cortarte el cabello o teñírtelo, busca a Teri Campobucle en Punta Garfio. Por las dudas, cuídate la zona lumbar.', 'Teníamos un barbero, pero desapareció así como si nada no hace mucho y nadie sabe qué le pasó. Fue lo único de lo que se habló durante todo un día.\n\nAhora este gnomo ha ocupado la antigua barbería. No estoy sugiriendo nada, no me malinterpretes, pero si estás buscando cortarte el cabello o teñírtelo, busca a Teri Campobucle en Punta Garfio. Por las dudas, cuídate la zona lumbar.', 28153),
(160337, 'esMX', '', 'El fjarnskaggl es muy popular entre los nobles. Lo vendo todo enseguida.\n\nVuelve la próxima semana, quizá tenga más.', 28153),
(160336, 'esMX', 'Ya compraste sellos para esta semana. Deja de hacerme perder el tiempo.\n\nVen a buscar más la semana que viene.', '', 28153),
(160335, 'esMX', 'Henrick Wyther vende toda clase de productos para apoyar a los profesionales como tú. Podrás encontrarlo en la parte superior del Mercado Vientos Alisios.\n\nEs imposible que no veas su puesto. Es de esos locos que hablan todo el día de conspiraciones. No te rías cuando veas sus mapas y sus anotaciones. Se toma muy en serio esas cuestiones, y además es buen tipo.', 'Henrick Wyther vende toda clase de productos para apoyar a los profesionales como tú. Podrás encontrarlo en la parte superior del Mercado Vientos Alisios.\n\nEs imposible que no veas su puesto. Es de esos locos que hablan todo el día de conspiraciones. No te rías cuando veas sus mapas y sus anotaciones. Se toma muy en serio esas cuestiones, y además es buen tipo.', 28153),
(160334, 'esMX', 'Objetos comerciables', 'Objetos comerciables', 28153),
(160333, 'esMX', 'No me hagas hablar sobre la cantidad de oro que he gastado en reparaciones. Gracias al cielo, el almirantazgo tiene un herrero que se encarga de cuidar nuestro equipamiento reglamentario. Para arreglos personales, te recomiendo visitar a Patrick Markson. Sí, sé que vende armas de fuego, pero también se las ingenia para arreglar casi cualquier cosa.\n\nBusca su puesto en la fuente que está en la parte inferior del Mercado Vientos Alisios, justo debajo de las escaleras que llevan a la posada.', 'No me hagas hablar sobre la cantidad de oro que he gastado en reparaciones. Gracias al cielo, el almirantazgo tiene un herrero que se encarga de cuidar nuestro equipamiento reglamentario. Para arreglos personales, te recomiendo visitar a Patrick Markson. Sí, sé que vende armas de fuego, pero también se las ingenia para arreglar casi cualquier cosa.\n\nBusca su puesto en la fuente que está en la parte inferior del Mercado Vientos Alisios, justo debajo de las escaleras que llevan a la posada.', 28153),
(160332, 'esMX', '¿Nunca pensaste en revertir tu destino? Quizá para encontrar una pieza de armadura especial, un arma o un abalorio de gran poder.\n\nPor un precio, te daré un sello que te permitirá torcer el destino para obtener un tesoro más en una tirada pasada.\n\nSi tienes un sello, podrás activarlo luego de derrotar a un jefe poderoso en calabozos y bandas difíciles.\n\nPronto podré otorgarte Sellos de destino bélico a cambio de oro, recursos bélicos o marcas de honor.\n\nEn este momento, no tengo ninguno para darte.', '', 28153),
(160331, 'esMX', 'Ofrezco varias maneras de comprar un Sello del destino bélico.\n\n¿Qué prefieres entregar para tener la oportunidad de torcer el destino?', '', 28153),
(160330, 'esMX', 'Ya has alcanzado la cantidad máxima de sellos.\n\nÚsalos antes de seguir molestándome.', '', 28153),
(160329, 'esMX', 'Víveres, perfecto. Ve a hablar con Ninette Shoams. Todos los días despliega sus pertrechos en la fuente que está en la parte inferior del Mercado Vientos Alisios.', 'Víveres, perfecto. Ve a hablar con Ninette Shoams. Todos los días despliega sus pertrechos en la fuente que está en la parte inferior del Mercado Vientos Alisios.', 28153),
(160328, 'esMX', 'Este muelle ahora funciona como el punto de desembarco de El Implacable.\n\nLa Alianza lo ha contratado como el medio de transporte principal para diplomáticos entre Ventormenta y Kul Tiras. La nave te llevará directamente hacia Puerto Boralus.', 'Este muelle ahora funciona como el punto de desembarco de El Implacable.\n\nLa Alianza lo ha contratado como el medio de transporte principal para diplomáticos entre Ventormenta y Kul Tiras. La nave te llevará directamente hacia Puerto Boralus.', 28153),
(160327, 'esMX', 'Víveres', 'Víveres', 28153),
(160326, 'esMX', 'El Implacable encalla aquí con frecuencia para regresar a las personas al continente. Si quieres viajar a Ventormenta, es la nave que buscas. Te dejará en el puerto de la ciudad.', 'El Implacable encalla aquí con frecuencia para regresar a las personas al continente. Si quieres viajar a Ventormenta, es la nave que buscas. Te dejará en el puerto de la ciudad.', 28153),
(160325, 'esMX', 'Vendedores. Bien. ¿Qué clase de mercader buscas?', 'Vendedores. Bien. ¿Qué clase de mercader buscas?', 28153),
(160324, 'esMX', 'Quieres un cambio, entiendo. Esto te puede sonar extrañísimo, pero creo que necesitas ir a ver al Tejedor de distorsión Ezil. Sí, entiendo que te parezca raro; Ezil parece una venda andante. Pero confía en mí: no hay nadie mejor que él. Aunque primero tienes que conseguir una cita.\n\nSu tienda está en el edificio junto a la Posada Puerto Cálido.', 'Quieres un cambio, entiendo. Esto te puede sonar extrañísimo, pero creo que necesitas ir a ver al Tejedor de distorsión Ezil. Sí, entiendo que te parezca raro; Ezil parece una venda andante. Pero confía en mí: no hay nadie mejor que él. Aunque primero tienes que conseguir una cita.\n\nSu tienda está en el edificio junto a la Posada Puerto Cálido.', 28153),
(160323, 'esMX', 'Si lo que buscas es aprender una nueva técnica de bordado o cómo suturar una herida sangrante... o hasta si buscas una bolsa nueva, te recomiendo hablar con Daniel Tejesalmuera. Búscalo en la parte superior del Mercado Vientos Alisios, al norte.\n\nDaniel es un buen muchacho, aunque quizá un poco sombrío. Me ha vendado las heridas más veces de las que recuerdo. Siempre se pone muy contento cuando se le da la oportunidad de enseñar su arte.', 'Si lo que buscas es aprender una nueva técnica de bordado o cómo suturar una herida sangrante... o hasta si buscas una bolsa nueva, te recomiendo hablar con Daniel Tejesalmuera. Búscalo en la parte superior del Mercado Vientos Alisios, al norte.\n\nDaniel es un buen muchacho, aunque quizá un poco sombrío. Me ha vendado las heridas más veces de las que recuerdo. Siempre se pone muy contento cuando se le da la oportunidad de enseñar su arte.', 28153),
(160322, 'esMX', '¿Te gusta mucho cazar? Tengo buenas noticias para ti, $uamigo:amiga;. Las criaturas de esta zona tienen la piel más dura que hayas visto. En Kul Tiras, las criamos para que sean fuertes y mortales.\n\nSi quieres aprender algo, tienes que ir con la mejor. Te recomiendo hablar con Camila Cielonegro. La encontrarás en la parte superior del Mercado Vientos Alisios, al norte.', '¿Te gusta mucho cazar? Tengo buenas noticias para ti, $uamigo:amiga;. Las criaturas de esta zona tienen la piel más dura que hayas visto. En Kul Tiras, las criamos para que sean fuertes y mortales.\n\nSi quieres aprender algo, tienes que ir con la mejor. Te recomiendo hablar con Camila Cielonegro. La encontrarás en la parte superior del Mercado Vientos Alisios, al norte.', 28153),
(160321, 'esMX', '¿A salvo? ¿Has visto las cosas que merodean por este lugar?\n\nGracias, pero más vale curar que prevenir... digo, prevenir que curar.', '', 28153),
(160320, 'esMX', 'No tienes que blandir tu arma aquí. Estamos a salvo.', 'No tienes que blandir tu arma aquí. Estamos a salvo.', 28153),
(160319, 'esMX', 'Prepárate para lo que sea.', '', 28153),
(160318, 'esMX', 'Se acerca la batalla. No nos vendría mal $Uun:una; $r como tú entre nuestras filas.', '', 28153),
(160317, 'esMX', 'Puedo verlo en tus ojos. Tu mente ha sido erosionada lentamente por la locura insidiosa. Sin embargo, quizás haya una forma de aliviarte.$b$bLos sabios alguna vez habitaron este lugar e intentaron combatir la oscuridad. Construyeron capillas, baluartes de fe y entereza. También erigieron una taberna para ahogar los susurros en un océano de hidromiel. Ahora solo quedan escombros y polvo...$b$bDirígete hacia el noroeste. En ese punto está lo que queda de ellos, un ídolo enorme y abisal. Encuentra la efigie y quizá logres hacer desaparecer los horrores de este lugar. Ten cuidado, tendrás que beber grandes cantidades, y el mar siempre encuentra una forma de cobrar su precio.', '', 28153),
(160316, 'esMX', 'Estoy en problemas. ¿Me podrías ayudar?', 'Estoy en problemas. ¿Me podrías ayudar?', 28153),
(160315, 'esMX', '¿Puedes sentirlo? Los muros... se derrumban. Se acercan, un susurro terrible a la vez.', '', 28153),
(160314, 'esMX', 'En una época, estas ruinas eran la envidia del valle.', '', 28153),
(160313, 'esMX', 'Debo confesar que ni siquiera recuerdo cuándo se envió esa carta...', '', 28153),
(160312, 'esMX', 'Recuerda que el exceso de confianza es un asesino lento e insidioso.', '', 28153),
(160311, 'esMX', '¿Buscas oro? ¿Platino? ¡¿Plata de tormenta?! Si quieres aprender las últimas técnicas de minería, entonces te recomiendo hablar con Myra Cabot. Tiene un sexto sentido que le permite oler las venas de minerales.\n^La encontrarás en la zona norte del Mercado Vientos Alisios, en el nivel superior. No te olvides de visitarme si te vuelves $urico:rica;, eh.', '¿Buscas oro? ¿Platino? ¡¿Plata de tormenta?! Si quieres aprender las últimas técnicas de minería, entonces te recomiendo hablar con Myra Cabot. Tiene un sexto sentido que le permite oler las venas de minerales.\n^La encontrarás en la zona norte del Mercado Vientos Alisios, en el nivel superior. No te olvides de visitarme si te vuelves $urico:rica;, eh.', 28153),
(160310, 'esMX', 'Bien, regresaremos después de rematarlos.', '', 28153),
(160309, 'esMX', 'No es mi especialidad, pero si buscas mejorar tu habilidad en peletería, conozco a la kultirana perfecta. Se llama Cassandra Brennor y es una hechicera con punzón y dedal incorporados.\n\nA menudo la puedes ver trabajando con Camila Cielonegro. Comparten un espacio en el nivel superior del Mercado Vientos Alisios, al norte.', 'No es mi especialidad, pero si buscas mejorar tu habilidad en peletería, conozco a la kultirana perfecta. Se llama Cassandra Brennor y es una hechicera con punzón y dedal incorporados.\n\nA menudo la puedes ver trabajando con Camila Cielonegro. Comparten un espacio en el nivel superior del Mercado Vientos Alisios, al norte.', 28153),
(160308, 'esMX', 'Avísame cuando estés $Ulisto:lista; para iniciar el bombardeo.', '', 28153),
(160307, 'esMX', 'Creo que buscas a Samuel D. Colton III... es un milagro que no se haya puesto \"doctor\" ni se haya agregado más títulos. Sin embargo, tengo que admitir algo: su trabajo es exquisito. Si quieres seguir entrenándote, no hay nadie mejor que él.\n\nLo encontrarás muy orgulloso detrás de sus vitrinas en el centro del nivel superior del Mercado Vientos Alisios, del lado norte.', 'Creo que buscas a Samuel D. Colton III... es un milagro que no se haya puesto \"doctor\" ni se haya agregado más títulos. Sin embargo, tengo que admitir algo: su trabajo es exquisito. Si quieres seguir entrenándote, no hay nadie mejor que él.\n\nLo encontrarás muy orgulloso detrás de sus vitrinas en el centro del nivel superior del Mercado Vientos Alisios, del lado norte.', 28153),
(160306, 'esMX', 'La persona indicada es Zooey Tintengranaje. Hace poco alquiló un sitio en la zona norte del Mercado Vientos Alisios, en el área superior.\n\nEs difícil creer que dentro de una personita tan diminuta pueda haber tanto conocimiento y poder, ¿no te parece?', 'La persona indicada es Zooey Tintengranaje. Hace poco alquiló un sitio en la zona norte del Mercado Vientos Alisios, en el área superior.\n\nEs difícil creer que dentro de una personita tan diminuta pueda haber tanto conocimiento y poder, ¿no te parece?', 28153),
(160305, 'esMX', 'Si tenemos esperanza de traer los zandalari a la Horda, debemos mantenernos fuertes.', '', 28153),
(160304, 'esMX', '¿Te gustan las flores? A mí también. Huelen tan bien. Bueno, la mayoría...\n\nSi lo que quieres es aprender los secretos para trabajar con la flora de esta parte del mundo, deberías hablar con Declan Senal. Lo encontrarás cuidando su jardín en la parte superior del Mercado Vientos Alisios, al norte.', '¿Te gustan las flores? A mí también. Huelen tan bien. Bueno, la mayoría...\n\nSi lo que quieres es aprender los secretos para trabajar con la flora de esta parte del mundo, deberías hablar con Declan Senal. Lo encontrarás cuidando su jardín en la parte superior del Mercado Vientos Alisios, al norte.', 28153),
(160303, 'esMX', '¡Alguien está protegiendo al Lamento del Alma en Pena con sofisticada magia maresabia!', '', 28153),
(160302, 'esMX', 'Alan Goyle tiene su choza de pesca en la parte superior del Mercado Vientos Alisios. Siempre está ahí arriba, pescando en su estanque. No me preguntes cómo es posible que siempre haya algo para pescar ahí... supongo que los peces caen por las cataratas, ¿no?\n\nNo es fácil llegar hasta allí arriba; tendrás que encontrar las escaleras que están entre los instructores de joyería y sastrería.', 'Alan Goyle tiene su choza de pesca en la parte superior del Mercado Vientos Alisios. Siempre está ahí arriba, pescando en su estanque. No me preguntes cómo es posible que siempre haya algo para pescar ahí... supongo que los peces caen por las cataratas, ¿no?\n\nNo es fácil llegar hasta allí arriba; tendrás que encontrar las escaleras que están entre los instructores de joyería y sastrería.', 28153),
(160301, 'esMX', 'Toma mis martillos, $p, ¡y arrójalos con todas tus fuerzas!', '', 28153),
(160300, 'esMX', '¡Mis Martillo Salvaje, concéntrense en el Lamento del Alma en Pena! ¡Que no se mueva!', '', 28153),
(160299, 'esMX', '¿Eres $uun granadero:una granadera;, $uun tirador:una tiradora; o $uuno de esos inventores locos:una de esas inventoras locas;? ¿O quizás eres las tres cosas?\n\nNo importa, la persona que buscas se llama Layla Marcalmo. Podrás encontrarla jugando con sus máquinas en la parte superior del Mercado Vientos Alisios, al norte.', '¿Eres $uun granadero:una granadera;, $uun tirador:una tiradora; o $uuno de esos inventores locos:una de esas inventoras locas;? ¿O quizás eres las tres cosas?\n\nNo importa, la persona que buscas se llama Layla Marcalmo. Podrás encontrarla jugando con sus máquinas en la parte superior del Mercado Vientos Alisios, al norte.', 28153),
(160298, 'esMX', '', 'Los Mag\'har... sobrevivirán...', 28153),
(160297, 'esMX', '', '¡Tu destrucción está cerca!', 28153),
(160296, 'esMX', 'Tu victoria vacía... no significa nada...', '', 28153),
(160295, 'esMX', '', '¡Caerás!', 28153),
(160294, 'esMX', '', '¡Mira! ¡Están retrocediendo!', 28153),
(160293, 'esMX', '', '¡Ja, jaaaa! ¡Tomen eso, inútiles!', 28153),
(160292, 'esMX', '', '¡Lok-tar ogar!', 28153),
(160291, 'esMX', '', '¡Dranosh\'ek mag\'har!', 28153),
(160290, 'esMX', 'Te espero... en las Tierras Plagadas...', '', 28153),
(160289, 'esMX', '', '¡Nunca nos rendiremos!', 28153),
(160288, 'esMX', 'Nuestra batalla... no ha terminado... intruso… $uintruso:intrusa;...', '', 28153),
(160287, 'esMX', '', '¡Por los Mag\'har!', 28153),
(160286, 'esMX', 'Regresaré...', '', 28153),
(160285, 'esMX', 'Tontos... solo han... destruido... una cáscara...', '', 28153),
(160284, 'esMX', '¿Piensas que has ganado? Mira a tu alrededor... Lo que buscas no está aquí.', '', 28153),
(160283, 'esMX', 'Tu niñita perdida está bajo mi cuidado. Ay, cómo llora. ¡Su dolor no tendrá fin!', '', 28153),
(160282, 'esMX', '', 'Si la azerita es capaz de provocar tanta destrucción, temo que ni siquiera la gran puerta de Boralus será capaz de soportarla.', 28153),
(160281, 'esMX', '', 'Cuánta devastación... La Puerta de Daelin nunca tuvo ninguna posibilidad.', 28153),
(160280, 'esMX', '', '¡Apunta a los barriles de pólvora!', 28153),
(160279, 'esMX', 'Emily Buentiempo es a quien buscas. La encontrarás en la parte más alta del Mercado Vientos Alisios, al norte.\n\nAhora que lo recuerdo, una vez encantó con magia un par de brazales que le llevé. Te la recomiendo sin dudas.', 'Emily Buentiempo es a quien buscas. La encontrarás en la parte más alta del Mercado Vientos Alisios, al norte.\n\nAhora que lo recuerdo, una vez encantó con magia un par de brazales que le llevé. Te la recomiendo sin dudas.', 28153),
(160278, 'esMX', '', 'Las criaturas que deambulan por aquí pueden ser muy nefastas, pero yo no me rindo fácilmente y estoy decidida a capturarlas a todas. Mi colección aún no es demasiado grande, pero las criaturas que he logrado capturar son muy poderosas. ¿Estás $ulisto:lista; para una pelea?', 28153),
(160277, 'esMX', '¿Visitantes en mi guarida? Qué curioso.', '', 28153),
(160276, 'esMX', '¡Cuando se encienda la última llama, la ciudad sabrá que eh\'tamos a salvo! ¡Y mi tripulación regresará!', '', 28153),
(160275, 'esMX', 'Es vulnerable dentro de su propio reino, y hará todo lo posible para impedir que entres en él.', '', 28153),
(160274, 'esMX', 'Te deseo suerte en tu viaje, continental. Ve con cuidado, Gorak Tul te estará observando.', '', 28153),
(160273, 'esMX', 'Hondonada Glauca es una zona más que adecuada para un puesto de avanzada oculto. ¡Hay mucha azerita cerca y ni un trol a la vista! No se puede pedir más.', '', 28153),
(160272, 'esMX', '', 'Nos hemos acostumbrado a los muchos insectos que vuelan por estas tierras; algunos son muy dóciles y otros, muy peligrosos... A lo largo de los años, he recogido algunas especies interesantes y estaría encantada de lanzarme a una escaramuza contra otros duelistas. ¿Te interesa?', 28153),
(160271, 'esMX', '', 'Deberíamos lanzar la próxima desde el aire. ¿Qué dices?', 28153),
(160270, 'esMX', '', '¡Ah! Quizá fue demasiado cerca...', 28153),
(160269, 'esMX', 'Desenterrando', 'Desenterrando', 28153),
(160268, 'esMX', 'Ah, buscas al \"Capitán\". Ve a su restaurante al aire libre, que está entre el corral y la fosa del herrero, en la parte superior del Mercado Vientos Alisios. Del lado norte.\n\n¡No te pierdas el pescado del pantano con papas! Se me hace agua la boca de solo pensar en ese plato...', 'Ah, buscas al \"Capitán\". Ve a su restaurante al aire libre, que está entre el corral y la fosa del herrero, en la parte superior del Mercado Vientos Alisios. Del lado norte.\n\n¡No te pierdas el pescado del pantano con papas! Se me hace agua la boca de solo pensar en ese plato...', 28153),
(160267, 'esMX', '¿Preguntas si sé dónde está el entrenador de herreros? Por supuesto que sé dónde está. Soy un guardia, ¿o acaso eres $uciego:ciega;?\n\nVe a la parte superior del Mercado Vientos Alisios. En la zona norte, encontrarás una fosa. Dentro de ella, verás al herrero más habilidoso que conozco: Grix \"Puños de hierro\" Barlow. Es imposible que no lo veas.', '¿Preguntas si sé dónde está el entrenador de herreros? Por supuesto que sé dónde está. Soy una guardia, ¿o acaso eres $uciego:ciega;?\n\nVe a la parte superior del Mercado Vientos Alisios. En la zona norte, encontrarás una fosa. Dentro de ella, verás al herrero más habilidoso que conozco: Grix \"Puños de hierro\" Barlow. Es imposible que no lo veas.', 28153),
(160266, 'esMX', 'Comenzaré con los preparativos. Ven a verme cuando tengas lo que necesitamos.', '', 28153),
(160265, 'esMX', 'Eso estuvo demasiado cerca. ¡Gracias por rescatarnos justo a tiempo!', 'Eso estuvo demasiado cerca. ¡Gracias por rescatarnos justo a tiempo!', 28153),
(160263, 'esMX', 'Yo superviso todos los impuestos de inscripción de las hermandades y compañías de comercio del muelle. ¿Cómo puedo ayudarte?', '', 28153),
(160262, 'esMX', '¿Hacer pozos en la tierra en busca de tesoros perdidos? Eso es vida. ¿Ya tienes uno de esos aparatos sofisticados para explorar el terreno?\n\nTe recomiendo hablar con Jane Hudson en la parte superior del Mercado Vientos Alisios. Cuando llegues allí, la verás trabajando en la zona oeste del bancal, cerca del corral.', '¿Hacer pozos en la tierra en busca de tesoros perdidos? Eso es vida. ¿Ya tienes uno de esos aparatos sofisticados para explorar el terreno?\n\nTe recomiendo hablar con Jane Hudson en la parte superior del Mercado Vientos Alisios. Cuando llegues allí, la verás trabajando en la zona oeste del bancal, cerca del corral.', 28153),
(160261, 'esMX', '', '¿$uListo:Lista;? ¡Arrójala!', 28153),
(160260, 'esMX', 'Un maestro de pociones, entendido. Sí, te recomiendo hablar con Elric Trismagisto. Podrás encontrarlo bien al norte del Mercado Vientos Alisios, en la zona que está por encima de la fosa del herrero.\n\nNo tiene bastón ni sombrero en punta, pero no te confundas: Elric es un hechicero. Uno muy poderoso y extraño. ¿Quién bebe una poción para convertirse en una nube? No me digas que no es raro... De todas formas, debo admitir que me encanta beber una dosis de su poción de pies ligeros de vez en cuando. ¡Te convierte en una gacela!', 'Un maestro de pociones, entendido. Sí, te recomiendo hablar con Elric Trismagisto. Podrás encontrarlo bien al norte del Mercado Vientos Alisios, en la zona que está por encima de la fosa del herrero.\n\nNo tiene bastón ni sombrero en punta, pero no te confundas: Elric es un hechicero. Uno muy poderoso y extraño. ¿Quién bebe una poción para convertirse en una nube? No me digas que no es raro... De todas formas, debo admitir que me encanta beber una dosis de su poción de pies ligeros de vez en cuando. ¡Te convierte en una gacela!', 28153),
(160259, 'esMX', 'Para que nuestra tierra sane, tenemos que creer que la redención es posible. Para todos.', '', 28153),
(160258, 'esMX', '¡Cuánto dolor deben haberle causado esas muertes! ¡Ella también... cuánto debe ansiar la redención!', '', 28153),
(160257, 'esMX', 'Lady Jaina vio morir a su padre y a sus compatriotas, y no hizo nada.', '', 28153),
(160256, 'esMX', 'Aún hoy sigo preguntándome si podría haber hecho más. Esa idea me persigue hasta en los sueños.', '', 28153),
(160255, 'esMX', 'La locura los había consumido, pero aun así siento remordimiento por sus muertes.', '', 28153),
(160254, 'esMX', 'He tenido que luchar contra mi propio pueblo, incluso matarlos. Fue una decisión difícil, pero necesaria.', '', 28153),
(160253, 'esMX', 'Muchos de mis compatriotas creen que Jaina Valiente es una traidora. Algunos cuestionarían mi decisión de ayudar a salvarla.', '', 28153),
(160252, 'esMX', '¿Eres $uun profesional:una profesional;? ¿Quieres seguir entrenándote? Tenemos lo que buscas. Al fin y al cabo, esto es Boralus. No hay sitio mejor que este.', '¿Eres $uun profesional:una profesional;? ¿Quieres seguir entrenándote? Tenemos lo que buscas. Al fin y al cabo, esto es Boralus. No hay sitio mejor que este.', 28153),
(160251, 'esMX', '¡Derriben $Ual:a la; $pr!', '', 28153),
(160250, 'esMX', '', 'He merodeado mucho por estas dunas y encontré algunas de las especies de mascotas más espectaculares que he visto en toda mi vida. Son carroñeras y se las ingenian para sobrevivir con lo que encuentran, igual que nosotros. Su voluntad de vivir es fuerte y las vuelve muy versátiles. ¿Quieres descubrir de lo que son capaces?', 28153),
(160249, 'esMX', '¡No me comas, Milden, soy tu amigo!', '', 28153),
(160248, 'esMX', '¡Solo traga a las personas malas!', '', 28153),
(160247, 'esMX', 'Intentaron espantar a Milden, ¡pero se enfureció!', '', 28153),
(160246, 'esMX', '¡Se tragó al señor Anderson!', '', 28153),
(160245, 'esMX', '¡Apresúrate!', '¡Apresúrate!', 28153),
(160244, 'esMX', 'Tienes que conseguir lo que necesito rápido. Hay una vida en juego.', '', 28153),
(160242, 'esMX', 'Pero estamos lejos de haber purgado la corrupción de nuestra tierra.', '', 28153),
(160241, 'esMX', 'Luchamos junto a hermanos y hermanas leales contra viento y marea... literalmente, muchas veces.', '', 28153),
(160240, 'esMX', 'Lord Canto Tormenta ya no existe, pero la oscuridad que se lo llevó perdura.', '', 28153),
(160239, 'esMX', 'El simple hecho de pisar esa orilla es una condena a muerte.', '', 28153),
(160238, 'esMX', 'Los maresabios somos los únicos que podemos llegar hasta allí a salvo, pero incluso nosotros permanecemos en el agua.', '', 28153),
(160237, 'esMX', 'Nunca cargué con la responsabilidad de escoltar un alma hasta Límite del Destino.', '', 28153),
(160236, 'esMX', 'Lo siento, $Upequeño:pequeña;... No puedo dejarte entrar. Toma lo que hayas venido a buscar y márchate.', '', 28153),
(160235, 'esMX', 'Si enviaron a lady Jaina a esa isla maldita, quizá no tengamos demasiado tiempo. Ven conmigo.', '', 28153),
(160234, 'esMX', '¿Condenó a su hija a Límite del Destino? ¡Por todas las mareas!', '', 28153),
(160233, 'esMX', 'Lady Katherine ha reconsiderado su decisión de ejecutar a su hija. Sabemos que a Jaina la llevaron al Límite del Destino. Necesito llegar hasta allí.', 'Lady Katherine ha reconsiderado su decisión de ejecutar a su hija. Sabemos que a Jaina la llevaron al Límite del Destino. Necesito llegar hasta allí.', 28153),
(160232, 'esMX', 'El tiempo apremia y debemos trabajar rápido si queremos salvar a Jaina.', '', 28153),
(160230, 'esMX', '¡Tu cabeza es perfecta para mi próxima creación!', '', 28153),
(160229, 'esMX', 'Uno de mis mejores trabajos. Las piezas se combinan a la perfección.', '', 28153),
(160228, 'esMX', 'Ah, $n. Qué bueno volver a verte, $uamigo mío:amiga mía;. ¿Qué te trae de vuelta a Canto Tormenta?', '', 28153),
(160227, 'esMX', 'Estoy seguro de que Lady Katherine querrá saber lo que descubriste.', '', 28153),
(160226, 'esMX', '', 'Es ancestral... y más despiadado de lo que imaginas...', 28153),
(160225, 'esMX', '', 'Sé $Umío:mía;. Por siempre.', 28153),
(160224, 'esMX', '', 'Hola, cariño. ¿Te gustaría escuchar mi canción?', 28153),
(160223, 'esMX', '$UNecio:Necia;... no debiste confiar... como nosotros.', '', 28153),
(160222, 'esMX', '¡No te quedarás con estos artefactos!', '', 28153),
(160221, 'esMX', '¡Los envíos no se pueden demorar!', '', 28153),
(160220, 'esMX', '¿Qué te llevaría a hablar con un gnomo tan demente? Si me preguntas a mí, su taller es un completo desastre.\n\nBueno, veo que no puedo disuadirte. La persona que buscas se llama Crenzo Aplastachispas. Está en la zona superior del Mercado Vientos Alisios, del lado este. Lo encontrarás jugueteando con esa pila de chatarra interminable que tiene allí. Te deseo la mejor de las suertes, $uamigo:amiga;.', '¿Qué te llevaría a hablar con un gnomo tan demente? Si me preguntas a mí, su taller es un completo desastre.\n\nBueno, veo que no puedo disuadirte. La persona que buscas se llama Crenzo Aplastachispas. Está en la zona superior del Mercado Vientos Alisios, del lado este. Lo encontrarás jugueteando con esa pila de chatarra interminable que tiene allí. Te deseo la mejor de las suertes, $uamigo:amiga;.', 28153),
(160219, 'esMX', 'Déjame decirte algo, $uamigo:amiga;: el sistema de ferries de la ciudad es una de las maravillas de este mundo. No solo te permite ir de un lugar a otro dentro de los majestuosos canales de agua de Boralus, sino que los maestros del ferry también comunican las afueras de la ciudad con el resto del Canal de Tiragarde.\n\nSi buscas un viaje en bote placentero, te recomiendo hablar con Will Melborne. Lo encontrarás junto a su hija, Sally, en la zona sur del Mercado Vientos Alisios, cerca del agua.', 'Déjame decirte algo, $uamigo:amiga;: el sistema de ferries de la ciudad es una de las maravillas de este mundo. No solo te permite ir de un lugar a otro dentro de los majestuosos canales de agua de Boralus, sino que los maestros del ferry también comunican las afueras de la ciudad con el resto del Canal de Tiragarde.\n\nSi buscas un viaje en bote placentero, te recomiendo hablar con Will Melborne. Lo encontrarás junto a su hija, Sally, en la zona sur del Mercado Vientos Alisios, cerca del agua.', 28153),
(160218, 'esMX', 'Maestro del ferry', 'Maestro del ferry', 28153),
(160217, 'esMX', 'Hay un montón de lugares interesantes en Boralus. ¿Qué andas buscando, $uamigo:amiga;?', 'Hay un montón de lugares interesantes en Boralus. ¿Qué andas buscando, $uamigo:amiga;?', 28153),
(160216, 'esMX', 'Si buscas un sitio para contar ovejitas, te recomiendo ir a la Posada Puerto Cálido. La encontrarás en el nivel superior, por encima de la fuente.\n\nBusca a Wesley Petroalijo. Te preparará una cama cómoda. Nada de colchón de paja y esas cosas. Ah, y su estofado legendario siempre está sobre el fuego; no olvides servirte un buen plato antes de irte a dormir.', 'Si buscas un sitio para contar ovejitas, te recomiendo ir a la Posada Puerto Cálido. La encontrarás en el nivel superior, por encima de la fuente.\n\nBusca a Wesley Petroalijo. Te preparará una cama cómoda. Nada de colchón de paja y esas cosas. Ah, y su estofado legendario siempre está sobre el fuego; no olvides servirte un buen plato antes de irte a dormir.', 28153),
(160215, 'esMX', 'Wgullll naq xizzuoog', '', 28153),
(160214, 'esMX', 'Wgul naq zzigla ouug anagih', '', 28153),
(160213, 'esMX', '¡No me lo digas dos veces!', '', 28153),
(160212, 'esMX', 'Veo que tienes intenciones de irte de viaje, eh. Sí, lo sé. Es muy emocionante atravesar las nubes para llegar a tierras exóticas y distantes. El entusiasmo del peligro desconocido que acecha al otro lado... La promesa de tesoros suntuosos y brillantes para quien derrote al gran villano...\n\nEh, ¿que no buscas eso? Ah, perdón... solo quieres viajar. ¿Por qué no me lo dijiste antes? Te recomiendo ir a la parte alta del Mercado Vientos Alisios, al oeste. Busca a Joan Weber cerca de la percha de grifo.', 'Veo que tienes intenciones de irte de viaje, eh. Sí, lo sé. Es muy emocionante atravesar las nubes para llegar a tierras exóticas y distantes. El entusiasmo del peligro desconocido que acecha al otro lado... La promesa de tesoros suntuosos y brillantes para quien derrote al gran villano...\n\nEh, ¿que no buscas eso? Ah, perdón... solo quieres viajar. ¿Por qué no me lo dijiste antes? Te recomiendo ir a la parte alta del Mercado Vientos Alisios, al oeste. Busca a Joan Weber cerca de la percha de grifo.', 28153),
(160211, 'esMX', '', 'Ahora márchate.', 28153),
(160210, 'esMX', '', 'Y tú, portavoz de la Horda. Ya decidiré qué hacer contigo.', 28153),
(160209, 'esMX', '', 'Tu, pequeñín verde, ya no ere\' bienvenido en el Redil de Bestias de Guerra. ¡Lárgate!', 28153),
(160208, 'esMX', '', 'Bien. Hemo\' disipado el vudú sobrenatural.', 28153),
(160207, 'esMX', '', 'Esto no estaba... en mi contrato...', 28153),
(160206, 'esMX', '', '¡Esto es propiedad privada de la compañía Aspafresno!', 28153),
(160205, 'esMX', 'El cuernoatroz joven gruñe y se desploma.', '', 28153),
(160204, 'esMX', 'El cuernoatroz joven huye después de sentir el gusto.', '', 28153),
(160203, 'esMX', '', 'Necesitaremos un bote para llegar a la próxima nave.', 28153),
(160202, 'esMX', 'No me preguntes cómo sé lo que voy a contarte, pero lo sé. Si quieres llevarte bien con estos misteriosos hombres tortuga, deberías hablar con su emisario, el Coleccionista Tojo.\n\nLa mala noticia es que no es fácil de encontrar. Está bastante lejos, en el Valle Canto Tormenta, en un sitio al que llaman Vista de los Buscadores. No me gustaría tener que ir hasta allí arriba, camarada. Aunque, ahora que te miro bien, seguro que ya sabes cómo llegar, ¿verdad?', 'No me preguntes cómo sé lo que voy a contarte, pero lo sé. Si quieres llevarte bien con estos misteriosos hombres tortuga, deberías hablar con su emisario, el Coleccionista Tojo.\n\nLa mala noticia es que no es fácil de encontrar. Está bastante lejos, en el Valle Canto Tormenta, en un sitio al que llaman Vista de los Buscadores. No me gustaría tener que ir hasta allí arriba, camarada. Aunque, ahora que te miro bien, seguro que ya sabes cómo llegar, ¿verdad?', 28153),
(160201, 'esMX', '¡Es hora de martillar!', '', 28153),
(160200, 'esMX', '¡No puedes vencer al martillo, no puedes detener a los grifos!', '', 28153),
(160199, 'esMX', '', '¡Ahora! ¡Sin piedad!', 28153),
(160198, 'esMX', 'Te llevas bien con el almirantazgo, ¿verdad? Bien por ti.\n\nSí, sé dónde está. La persona que buscas es la proveedora Fray y se encuentra en la Oficina del Supervisor de puerto junto a algunos de los individuos más importantes de la zona.', 'Te llevas bien con el almirantazgo, ¿verdad? Bien por ti.\n\nSí, sé dónde está. La persona que buscas es la proveedora Fray y se encuentra en la Oficina del Supervisor de puerto junto a algunos de los individuos más importantes de la zona.', 28153),
(160197, 'esMX', 'Emisaria del Almirantazgo Valiente', 'Emisaria del Almirantazgo Valiente', 28153),
(160196, 'esMX', '¿Emisarios? ¿Con cuál quieres hablar?', '¿Emisarios? ¿Con cuál quieres hablar?', 28153),
(160195, 'esMX', 'El banco, sí. Encontrarás a los banqueros en el extremo noroeste de la ciudad, en el distrito del Mercado Vientos Alisios.\n\nEso me recuerda: tengo que ir a revisar mi cuenta cuando termine mi turno. Esos tipos no ofrecen protección contra sobregiros.', 'El banco, sí. Encontrarás a los banqueros en el extremo noroeste de la ciudad, en el distrito del Mercado Vientos Alisios.\n\nEso me recuerda: tengo que ir a revisar mi cuenta cuando termine mi turno. Esos tipos no ofrecen protección contra sobregiros.', 28153),
(160194, 'esMX', 'Ah, hola, $c. ¿Qué tal?', '', 28153),
(160193, 'esMX', '¡A bucear!', '¡A bucear!', 28153),
(160192, 'esMX', 'Perfecto. Veamos…\n\n<Hobart hojea un manual empapado.>\n\nLas reglas de seguridad número tres a diecisiete son aburridas y no interesan. ¿Estás $Ulisto:lista;?', '', 28153),
(160191, 'esMX', 'El faro no puede estar encendido durante mucho tiempo. Entendido.', 'El faro no puede estar encendido durante mucho tiempo. Entendido.', 28153),
(160190, 'esMX', 'Excelente. Regla número dos: NO DEJES EL FARO ENCENDIDO.\n\nNo es broma. No dejes el faro encendido durante más de, no sé, veinte segundos. A menos que quieras que te devore un tiburón. Si ves un tiburón, apagas la luz. ¿Entendido?', '', 28153),
(160189, 'esMX', 'No me quito la escafandra. Entendido.', 'No me quito la escafandra. Entendido.', 28153),
(160188, 'esMX', '¡Muy bien! Regla número uno: Nunca te quites la escafandra.\n\nNo me importa si puedes respirar debajo del agua por alguna magia extraña. La presión te aplastará el cráneo. Además, utilizaré un auricular a prueba de estática para comunicarme contigo durante la misión. ¿Entendido?', '', 28153),
(160187, 'esMX', 'Sí, estoy prestando atención.', 'Sí, estoy prestando atención.', 28153),
(160186, 'esMX', '¡Ajá! ¡Ahí está $Unuestro:nuestra; buzo!\n\nHas llegado justo a tiempo. Acabo de terminar de reparar el último agujero de la manguera de aire.\n\nAntes de que te vayas, tengo que darte una serie de instrucciones de seguridad. ¿Estás prestando atención?', '', 28153),
(160185, 'esMX', '', 'Yo cerraría la boca si fuera tú', 28153),
(160184, 'esMX', '¿No podemos solucionarlo hablando? Digo, es un efecto secundario muy leve...', '', 28153),
(160183, 'esMX', 'Ah... eres TÚ. Vaya, vaya, ¡qué sorpresa!', '', 28153),
(160182, 'esMX', '', 'Monstruos... ¿cómo pudieron hacer esto?', 28153),
(160181, 'esMX', '¡Eeh! ¡Ey, ey, ey! ¡¿Te importaría bajar esas cosas puntiagudas?!', '', 28153),
(160180, 'esMX', '', 'Tenemos que resistir.', 28153),
(160179, 'esMX', '', '¡Explícate!', 28153),
(160178, 'esMX', '', 'Estaré esperando en las sombras, $n. Si me necesitas, no tienes más que llamarme.', 28153),
(160177, 'esMX', '', 'Mi consejo: evita los pozos de energía mágica. No solo desarrollarás una adicción, sino que involucionarás a una especie de... elfo de segunda mano.', 28153),
(160176, 'esMX', '', 'No, NO tengo un fetiche con las vendas. Bueno... tal vez un poquito.', 28153),
(160175, 'esMX', '', 'Me gustas. Dime... ¿Tienes un hermano gemelo?', 28153),
(160174, 'esMX', '', 'Puedes impedir que me lo lleve y morir, o quedarte ahí, de rodillas en la tierra, y vivir.', 28153),
(160173, 'esMX', '', 'El rey Anduin me dio una piedra de hogar para volver a Ventormenta. Allí curaré las heridas de mi amado... y ayudaré a mi pueblo a recuperarse de esta locura.', 28153),
(160172, 'esMX', 'Salgamos de aquí.', 'Salgamos de aquí.', 28153),
(160171, 'esMX', 'La guardia de honor se encargará del resto de este desastre. ¿Estás $Ulisto:lista;?', '', 28153),
(160170, 'esMX', '', 'Prepárate.', 28153),
(160169, 'esMX', '', '¡Adalid!', 28153),
(160168, 'esMX', '', '¡Cuidado!', 28153),
(160167, 'esMX', '|cFF0000FF(Misión)|r Llévanos al naufragio del mariscal Valentine, en el medio del Mare Magnum.', '|cFF0000FF(Misión)|r Llévanos al naufragio del mariscal Valentine, en el medio del Mare Magnum.', 28153),
(160166, 'esMX', '', 'Por aquí.', 28153),
(160165, 'esMX', 'Es un gusto verte, $uviajero:viajera;. ¿Con qué puedo ayudarte hoy?', 'Es un gusto verte, $uviajero:viajera;. ¿Con qué puedo ayudarte hoy?', 28153),
(160164, 'esMX', '', '¡Por aquí!', 28153),
(160163, 'esMX', '', 'Ante su luz, se revelan todas las verdades.', 28153),
(160162, 'esMX', 'La azerita... Eh\'to no es... lo que Zul prometió...', '', 28153),
(160161, 'esMX', '¡Sus esfuerzo\' son en vano! ¡Los poderes de la azerita fluyen por mis venas!', '', 28153),
(160160, 'esMX', '¡Retrocedan! ¡Los atraparemos del otro lado!', '¡Retrocedan! ¡Los atraparemos del otro lado!', 28153),
(160159, 'esMX', '¡Nosotros te cubrimos, $p!', '', 28153),
(160158, 'esMX', 'Me gustaría comerciar.', 'Me gustaría comerciar.', 28153),
(160157, 'esMX', 'Regresemos al portal.', '', 28153),
(160156, 'esMX', '', 'Es un honor servir a Elune.', 28153),
(160155, 'esMX', '', 'Hablo en nombre de mi pueblo.', 28153),
(160154, 'esMX', '', 'El enemigo conocerá nuestra furia.', 28153),
(160153, 'esMX', 'Tienes el corazón de tu madre.', '', 28153),
(160152, 'esMX', 'Para mí, nadie tendría que perder su hogar. Si los hace sentirse así, no debería pasar.', '', 28153),
(160151, 'esMX', 'Mamá a veces hablaba sobre este tema... Creo... que la hacía llorar.', '', 28153),
(160150, 'esMX', '', 'Los kaldorei resistirán.', 28153),
(160149, 'esMX', 'No éramos... nosotros mismos. Es difícil de explicar, hijo.', '', 28153),
(160148, 'esMX', '¿Y eso no los puso tristes?', '', 28153),
(160147, 'esMX', 'Eso pasó hace mucho tiempo.', '', 28153),
(160146, 'esMX', 'Una vez me dijiste que los orcos habíamos perdido nuestro hogar.', '', 28153),
(160145, 'esMX', '', 'A veces hay que esperar... otras hay que actuar.', 28153),
(160144, 'esMX', '¿Por qué?', '', 28153),
(160143, 'esMX', 'No me gusta que los elfos hayan perdido su árbol.', '', 28153),
(160142, 'esMX', '¡Y devolveré tus dones a los poderes del abismo!', '', 28153),
(160141, 'esMX', 'Concédeme tu poder para derribar a mi enemigo…', '', 28153),
(160140, 'esMX', 'Y castíganos si traicionamos tu voluntad.', '', 28153),
(160139, 'esMX', '', 'Lucharemos para proteger nuestro futuro.', 28153),
(160138, 'esMX', 'Mas tu poder permítenos domar,', '', 28153),
(160137, 'esMX', '', 'Escucha la voz de Elune.', 28153),
(160136, 'esMX', 'Ya lo veremos, hijo. Ya lo veremos.', '', 28153),
(160135, 'esMX', '¿Crees que esta guerra cambiará a la Horda?', '', 28153),
(160134, 'esMX', 'El mar se llevará al hombre a su regazo.', '', 28153),
(160133, 'esMX', 'Las guerras nunca cambian. Solo los guerreros cambian.', '', 28153),
(160132, 'esMX', '¿Esta guerra es mala? Quiero decir... ¿es peor que las otras?', '', 28153),
(160131, 'esMX', 'Se agita la marea, se unen los lazos...', '', 28153),
(160130, 'esMX', '¿Qué pasa, hijo?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160129, 'esMX', '¿Padre?', '', 28153),
(160128, 'esMX', '', 'El Monte Mugamba es un lugar salvaje e implacable. Dudo mucho que la Horda venga a buscarnos a un sitio como este; a fin de cuentas, está protegido por una tribu de gorilas gigantes y rodeado de riscos traicioneros.', 28153),
(160127, 'esMX', '', 'Cuando quieras regresar a la Costa Oscura del presente, lo único que tienes que hacer es pedírmelo.', 28153),
(160126, 'esMX', 'Sí, papá.', '', 28153),
(160125, 'esMX', 'Recuerda eso, muchacho.', '', 28153),
(160124, 'esMX', 'La guerra es una prueba de honor. Cuando el honor se pierde, no es fácil recuperarlo.', '', 28153),
(160123, 'esMX', 'La guerra saca lo peor de todos.', '', 28153),
(160122, 'esMX', 'Oí que los otros chicos estaban hablando sobre la guerra. La Horda... ¿La Horda hizo algo mal?', '', 28153),
(160121, 'esMX', 'Estás callado. Más de lo normal.', '', 28153),
(160120, 'esMX', '¿Sí, papá?', '', 28153),
(160119, 'esMX', 'Hijo.', '', 28153),
(160118, 'esMX', 'Esta tierra está llena de criaturas interesantes y poderosas. Mientras nuestros defensores del templo se enorgullecen de ser valerosos y hábiles en la batalla, yo me enorgullezco de entrenar a mis mascotas para que alcancen el máximo nivel de habilidad en la lucha. ¿Crees que tus mascotas están listas para desafiar a las mías?', '', 28153),
(160117, 'esMX', '¿Puedes mostrarme cómo lucía el mundo antes de que Teldrassil ardiera en llamas?', '¿Puedes mostrarme cómo lucía el mundo antes de que Teldrassil ardiera en llamas?', 28153),
(160116, 'esMX', 'Un momento... ¿acabas de hacer una broma sobre mi peso? Para que sepas, estaba llevando un cofre muy importante.', '', 28153),
(160115, 'esMX', 'He terminado. ¡Toma el cetro y larguémonos de aquí!', '', 28153),
(160114, 'esMX', '¡Aléjate de eso!', '', 28153),
(160113, 'esMX', '', 'Bueno, ¡podrías haber tirado ese abrigo andrajoso que tienes, Flynn!', 28153),
(160112, 'esMX', '¡Cómo te atreves!', '', 28153),
(160111, 'esMX', 'Bueno, bueno. Compraremos pescado para la grifo maravilla y le daremos un respiro antes de regresar.', '', 28153),
(160110, 'esMX', '', 'No quiero extenuar a mi pobre chica. Hoy tuvo que llevar una carga pesada.', 28153),
(160109, 'esMX', '', 'Volveremos a la ciudad. Pero primero Corazón de vendaval necesita descansar.', 28153),
(160108, 'esMX', 'Hazme espacio, Taelia. ¡Esta vez pienso montar tu grifo en un asiento de verdad!', '', 28153),
(160107, 'esMX', 'Bien. Mientras $n visita Tol Dagor, nosotros deberíamos llevar este cofre a Boralus.', '', 28153),
(160106, 'esMX', 'Ere\' demasiado amable para este mundo, $n. ¿Dónde estaba? Ah, sí. Nuestro escape fallido.', '', 28153),
(160105, 'esMX', 'Mucho mejor. Déjame continuar...', '', 28153),
(160104, 'esMX', 'Ah, eso eh\'tá mucho mejor.', '', 28153),
(160103, 'esMX', '¡Nooo! No... otra vez...', '', 28153),
(160102, 'esMX', '¡Siento que la vida regresa a mí! ¡Debo conseguir más poder!', '', 28153),
(160101, 'esMX', 'Por desgracia, el barco está en proceso de reparación. Su impecable récord de servicio se ha mancillado. Pero no te preocupes, estoy aquí para ayudarte a llegar a destino por otros medios.\n\nUn simple portal quizá no sea lo mismo que sentir el viento en el cabello en una travesía a través de los mares, pero podrás llevar a cabo tus tareas sin inconvenientes.\n\nUsa este portal cuando lo necesites. Estoy a tu servicio.', 'Por desgracia, el barco está en proceso de reparación. Su impecable récord de servicio se ha mancillado. Pero no te preocupes, estoy aquí para ayudarte a llegar a destino por otros medios.\n\nUn simple portal quizá no sea lo mismo que sentir el viento en el cabello en una travesía a través de los mares, pero podrás llevar a cabo tus tareas sin inconvenientes.\n\nUsa este portal cuando lo necesites. Estoy a tu servicio.', 28153),
(160100, 'esMX', '¡Gah!', '¡Gah!', 28153),
(160099, 'esMX', '¡Destriparé a quien haya puesto eh\'to aquí!', '¡Destriparé a quien haya puesto eh\'to aquí!', 28153),
(160098, 'esMX', '¡Otra vez no!', '¡Otra vez no!', 28153),
(160097, 'esMX', '¡¿Quién puso eh\'to aquí?!', '¡¿Quién puso eh\'to aquí?!', 28153),
(160096, 'esMX', '', '¡Ya veo Puerto del Puente! ¡Aterrizaremos ahí!', 28153),
(160095, 'esMX', '¡Thros despierta!', '', 28153),
(160094, 'esMX', 'Sabes que no puedes derrotarme, Ulfar. Pero si lo que buscas es pelea, ¡la tendrás!', '', 28153),
(160093, 'esMX', 'Mi... poder...', 'Mi... poder...', 28153),
(160092, 'esMX', 'Poder... ¡más poder del que tuve en toda mi vida! ¡Tengo que conseguir más!', 'Poder... ¡más poder del que tuve en toda mi vida! ¡Tengo que conseguir más!', 28153),
(160091, 'esMX', 'Aquí encontrará\' la nave que sale del Puerto de Zandalar a las Islas del Eco.\n\n¿Te dirige\' allí?', '', 28153),
(160090, 'esMX', '', 'Con estas bastará. ¡Salgamos del barco y probemos qué pueden hacer!', 28153),
(160089, 'esMX', 'Encárgate de esta molestia, $n.', '', 28153),
(160088, 'esMX', '¡Escupes a mi loa! ¡Te arrancaré los labio\' con los diente\'!', '¡Escupes a mi loa! ¡Te arrancaré los labio\' con los diente\'!', 28153),
(160087, 'esMX', '¡Te enseñaré a no faltarle el respeto a mi loa!', '¡Te enseñaré a no faltarle el respeto a mi loa!', 28153),
(160086, 'esMX', '¡Pagarás por eh\'te insulto!', '¡Pagarás por eh\'te insulto!', 28153),
(160085, 'esMX', '¿Por qué harías eso?', '¿Por qué harías eso?', 28153),
(160084, 'esMX', '¡En nombre de todo\' los loa! ¿Qué cree\' que estás haciendo?', '¡En nombre de todo\' los loa! ¿Qué cree\' que estás haciendo?', 28153),
(160083, 'esMX', '¡Ya deja eso!', '¡Ya deja eso!', 28153),
(160082, 'esMX', 'Vamos.', 'Vamos.', 28153),
(160081, 'esMX', 'Parece que tenemos visitas. ¿Te molestaría acompañarme a saludar?', '', 28153),
(160080, 'esMX', 'Katherine no descansará hasta recuperar el cadáver de su hijo.\n\nAprovecharemos sus emociones en nuestro beneficio, para sacarle ventaja a su flota.', '', 28153),
(160079, 'esMX', 'Hemos frustrado otro plan destartalado de la Alianza. Supongo que tengo que felicitarte.', '', 28153),
(160078, 'esMX', 'La Alianza ha armado su propia máquina de guerra potenciada por azerita. Si es aunque sea la mitad de potente que la nuestra, ¡tenemos que destruirla ahora!', '', 28153),
(160077, 'esMX', '\"Aullido de Fatalidad\", cómo no. ¡Bien hecho!', '', 28153),
(160076, 'esMX', 'Las fuerzas de la Horda han construido otra máquina de guerra potenciada por azerita. Destrúyela... ¡antes de que puedan usarla para destruir Stromgarde!', '', 28153),
(160075, 'esMX', '', 'Hora de combatir fuego con fuego. Busquemos algunas de esas bombas de azerita en uno de sus barcos.', 28153),
(160074, 'esMX', '', 'Me encargaré de que se haga justicia. Primero con estos piratas, y después con la Compañía Aspafresno.', 28153),
(160073, 'esMX', '', 'Aguanta, Flynn. Por favor... no mueras.', 28153),
(160072, 'esMX', 'El emplazamiento desde el que vigilamos el Camino Dorado es un mirador excelente para controlar el tráfico enemigo que entra a la capital zandalari y sale de ella.', '', 28153),
(160071, 'esMX', 'Colocando cebo', 'Colocando cebo', 28153),
(160070, 'esMX', 'Que así sea, cadáver. Recuperaré el cuerpo de Derek sobre tu cadáver.', '', 28153),
(160069, 'esMX', 'Pero, francamente, puedes hacer lo que quieras con Valentine. No significa nada para nosotros.', '', 28153),
(160068, 'esMX', 'Ah, mi buen hombre. Esa táctica funcionaría de maravilla en alguien que no fuera yo...', '', 28153),
(160067, 'esMX', 'Devuelvan a Derek Valiente a mis manos, y volverán a tener a su hombre.', '', 28153),
(160066, 'esMX', 'Invirtiendo', 'Invirtiendo', 28153),
(160065, 'esMX', 'Cuando oí que los trols hablaban sobre las sombras, pensé que se referían a sombras reales. ¿Quién iba a pensar que les gustaban tanto las metáforas?', 'Cuando oí que los trols hablaban sobre las sombras, pensé que se referían a sombras reales. ¿Quién iba a pensar que les gustaban tanto las metáforas?', 28153),
(160064, 'esMX', '¿Sabes lo que le vendría bien a este sitio? Un poco de fango verde.', '¿Sabes lo que le vendría bien a este sitio? Un poco de fango verde.', 28153),
(160063, 'esMX', '¡Intolerable! El agua de este sitio es demasiado azul para mi gusto.', '¡Intolerable! El agua de este sitio es demasiado azul para mi gusto.', 28153),
(160062, 'esMX', '¿Sabes? Creo que a mí también me vendría bien un cambio. Sin dudas, te recomiendo hablar con el Tejedor de distorsión Hayri cerca de los muelles.\n\nPara llegar hasta ahí, ve hasta el Gran Bazar, que está un bancal por encima del puerto. Hayri es el encargado de un sitio llamado la Vorágine Mercantil, en la zona este.', '¿Sabes? Creo que a mí también me vendría bien un cambio. Sin dudas, te recomiendo hablar con el Tejedor de distorsión Hayri cerca de los muelles.\n\nPara llegar hasta ahí, ve hasta el Gran Bazar, que está un bancal por encima del puerto. Hayri es el encargado de un sitio llamado la Vorágine Mercantil, en la zona este.', 28153),
(160061, 'esMX', 'Estoy seguro de que si me quedo con algunas partes de los cuerpos que hay diseminados por el campo de batalla nadie se dará cuenta.', 'Estoy seguro de que si me quedo con algunas partes de los cuerpos que hay diseminados por el campo de batalla nadie se dará cuenta.', 28153),
(160060, 'esMX', '¿Quieres cambiar un poco tu estilo? Hay un etéreo llamado Tejedor de distorsión Hayri en la zona de los muelles.\n\nPara encontrarlo, primero ve al Gran Bazar, que eh\'tá un bancal por encima del puerto. Podrás hablar con él en un sitio llamado Vorágine Mercantil, en la parte eh\'te.', '¿Quieres cambiar un poco tu estilo? Hay un etéreo llamado Tejedor de distorsión Hayri en la zona de los muelles.\n\nPara encontrarlo, primero ve al Gran Bazar, que eh\'tá un bancal por encima del puerto. Podrás hablar con él en un sitio llamado Vorágine Mercantil, en la parte eh\'te.', 28153),
(160059, 'esMX', 'Este lugar no es el Apothecarium, pero tendrá que bastar.', 'Este lugar no es el Apothecarium, pero tendrá que bastar.', 28153),
(160058, 'esMX', 'Eh, tú. Parece que tienes experiencia en duelos de mascotas. No perdamos el tiempo, ¿quieres luchar?', '', 28153),
(160057, 'esMX', 'Esta ciudad es demasiado amplia para mi gusto. Necesito lugares oscuros como este para completar mi trabajo.', 'Esta ciudad es demasiado amplia para mi gusto. Necesito lugares oscuros como este para completar mi trabajo.', 28153),
(160056, 'esMX', '¡Excelente! Ya siento cómo regresan las fuerzas a Azeroth.', '', 28153),
(160055, 'esMX', 'Transfigurador', 'Transfigurador', 28153),
(160054, 'esMX', 'Puedo sentir la azerita cerca... y hay algo que la está usando para extraer mucho poder. ¡Tienes que detenerlo!', '', 28153),
(160053, 'esMX', 'Pasaron varios día\' hasta que comprendí la horrible verdad...\n\nKaiani eh\'taba muerta, su padre la había asesinado, pero yo era el culpable. \n\n<Zenbaro tose violentamente.>\n\nCreo que no me queda mucho tiempo. \n\n¿Serías tan amable de traerle a eh\'te hombre agonizante un último trago de la fuente?', '', 28153),
(160052, 'esMX', 'Después de un año, había reunido dinero suficiente para que Kaiani y yo pudiéramo\' huir. \n\nAcordamos partir esa misma noche. Le dije que nos encontraríamo\' cerca del camino antiguo de mercaderes a la hora del crepúsculo. \n\nEn cuanto el sol se puso detrás de las montaña\', corrí hacia mi futuro.\n\nCuando llegué al camino de mercadere\', había guardias armados esperándome. \n\nMe encerraron sin mediar palabra.', '', 28153),
(160051, 'esMX', 'Qué vergüenza... poner su propia codicia por sobre la salud de Azeroth. Gracias, adalid.', '', 28153),
(160050, 'esMX', 'Durante el tiempo que trabajé para su padre, entablamo\' una relación. \n\nElla me suplicó que dejara a los bribone\' y me fuera de la ciudad, pero yo sabía que no tenía escapatoria. \n\nNo tenía dinero. Todo lo que robaba iba directo a las mano\' de Rajin. Pero, ¿tenía que ser así?\n\nDesde ese día, por cada dos moneda\' que robaba, escondía una para mí.\n\n<Zenabo tose violentamente.>\n\nAgua, $n. Por favor...', '', 28153),
(160049, 'esMX', 'Logré ganarme por completo la confianza y el respeto de Rajin. \n\nPara un bribón, eso era un sueño, pero yo tenía otras cosa\' en mente... \n\nRajin tenía una hija, Kaiani. Ella era todo lo opuesto a él: era honesta, amable... hermosa.', '', 28153),
(160048, 'esMX', 'El jefe notó mis habilidade\' rápidamente. \n\nAl poco tiempo, empecé a encargarme de los recados personale\' del propio Rajin. \n\nSi había que ir a conversar con alguien, iba yo. \n\nAunque créeme que lo que menos hacía era hablar. \n\n<Zenbaro tose.>\n\nMe vendría bien un poco má\' de agua, $n.', '', 28153),
(160047, 'esMX', 'Alguien en esta cueva está minando azerita de las heridas del mundo. ¡No lo permitas!', '', 28153),
(160046, 'esMX', 'Cuéntame más.', 'Cuéntame más.', 28153),
(160045, 'esMX', 'No es sensato molestar al oso.', '', 28153),
(160044, 'esMX', 'Mis costumbres aceptan la muerte como parte del ciclo natural. ¿Quieres que te lo demuestre?', '', 28153),
(160043, 'esMX', 'Puede que sea viejo, pero no estoy senil. Ya basta.', '', 28153),
(160042, 'esMX', 'Mantente firme.', '', 28153),
(160041, 'esMX', 'Que la fuerza del bosque te acompañe.', '', 28153),
(160040, 'esMX', 'Golpea rápido y con certeza.', '', 28153),
(160039, 'esMX', 'Cuídate del bosque.', '', 28153),
(160038, 'esMX', 'Mantén el equilibrio.', '', 28153),
(160037, 'esMX', 'Un gusto, continental.', '', 28153),
(160036, 'esMX', 'Nuestras raíces surcan lo profundo de esta tierra.', '', 28153),
(160035, 'esMX', 'Devolvemos el golpe a la oscuridad.', '', 28153),
(160034, 'esMX', 'La vida tiene un ritmo. ¿Lo sientes?', '', 28153),
(160033, 'esMX', '¿Has venido a aprender?', '', 28153),
(160032, 'esMX', '', '¡Ahógate con este repollo!', 28153),
(160031, 'esMX', 'Mi sabiduría no es para corazones débiles.', '', 28153),
(160030, 'esMX', '¿Qué necesitas de los Oradores de espinas?', '', 28153),
(160029, 'esMX', '¿Cómo podemos hacer ofertas por las cosas que necesitamos si no tenemos dinero?', '¿Cómo podemos hacer ofertas por las cosas que necesitamos si no tenemos dinero?', 28153),
(160028, 'esMX', 'No nos quedan muchos objetos de valor para vender.', 'No nos quedan muchos objetos de valor para vender.', 28153),
(160027, 'esMX', 'Esto debería alcanzar para comprar suministros... espero.', 'Esto debería alcanzar para comprar suministros... espero.', 28153),
(160026, 'esMX', '¿Cuánto oro nos queda?', '¿Cuánto oro nos queda?', 28153),
(160025, 'esMX', '¿Nos queda algo valioso para vender?', '¿Nos queda algo valioso para vender?', 28153),
(160024, 'esMX', 'No tengo la certeza de que esos banqueros goblin sean mejores que los robacobres de los Montesco.', 'No tengo la certeza de que esos banqueros goblin sean mejores que los robacobres de los Montesco.', 28153),
(160023, 'esMX', '¡Sacúdete más fuerte! Espera... ¡no tanto!', '', 28153),
(160022, 'esMX', '', '¡No puedo sacudir a ese último!', 28153),
(160021, 'esMX', '¡Huimos con tanta prisa que no pude llevarme nada!', '¡Huimos con tanta prisa que no pude llevarme nada!', 28153),
(160020, 'esMX', '', '¡Lárgate de aquí, $r!', 28153),
(160019, 'esMX', '', '¡Te perseguirán, $r!', 28153),
(160018, 'esMX', '', '¡Sal de Ventormenta, $r!', 28153),
(160017, 'esMX', 'Veamos a quién ha enviado Valiente ahora.', '', 28153),
(160016, 'esMX', '¡Alto!', '¡Alto!', 28153),
(160015, 'esMX', 'Creías que podías pasar $uinadvertido:inadvertida;, ¿no?', 'Creías que podías pasar $uinadvertido:inadvertida;, ¿no?', 28153),
(160014, 'esMX', '¡Ja! Te atrapé espiando.', '¡Ja! Te atrapé espiando.', 28153),
(160013, 'esMX', '¡Fuera de aquí, escoria de la Horda!', '¡Fuera de aquí, escoria de la Horda!', 28153),
(160012, 'esMX', '', '¡FIRMEMARES! ¡ABRAN FUEGO!', 28153),
(160011, 'esMX', 'Poder recuperado. Continuar directiva principal. ¡Exterminar!', 'Poder recuperado. Continuar directiva principal. ¡Exterminar!', 28153),
(160010, 'esMX', '¡Te arrancaré ese martillo de esas manos frías y muertas!', '¡Te arrancaré ese martillo de esas manos frías y muertas!', 28153),
(160009, 'esMX', '', '¡Satisfacemos todos los gustos!', 28153),
(160008, 'esMX', '', '¡Veo a $Uun:una; $r $Ual:a la; que le faltan unas vitaminas!', 28153),
(160007, 'esMX', '', '¡Tú pareces necesitar un nabo maduro!', 28153),
(160006, 'esMX', '', '¡Tengo todo tipo de artilugios a la venta!', 28153),
(160005, 'esMX', '¡Largo de ahí!', '', 28153),
(160004, 'esMX', '¡Alto!', '', 28153),
(160003, 'esMX', '¡¿Qué haces ahí?!', '', 28153),
(160002, 'esMX', '¡Alto ahí!', '', 28153),
(160001, 'esMX', '¡Salgan de sus escondites, escorias de la Horda! Tenemos a uno de sus amigos.', '', 28153),
(160000, 'esMX', 'Me largaré de aquí en cuanto el camino esté despejado. Nos veremos en casa de la abuela, ¡buena suerte!', '', 28153),
(159999, 'esMX', '¿Dónde iremos ahora, jefa de guerra?', '¿Dónde iremos ahora, jefa de guerra?', 28153),
(159998, 'esMX', '¡Ni mesa sin pan ni ejército sin capitán!', '', 28153),
(159997, 'esMX', 'Uno de los Lanza Negra llamado Capataz Al\'jibo es el que se encarga de las reparaciones de casi todas nuestras fuerzas. Lo podrás encontrar en el Salón de los Pasos Ancestrales, dentro del Gran Sello, al este.', 'Uno de los Lanza Negra llamado Capataz Al\'jibo es el que se encarga de las reparaciones de casi todas nuestras fuerzas. Lo podrás encontrar en el Salón de los Pasos Ancestrales, dentro del Gran Sello, al este.', 28153),
(159996, 'esMX', '¿Quieres desprenderte de parte de esas ganancias mal habidas? Entiendo. ¿De qué sirve luchar si no se consigue algún botín? Estoy en lo cierto, ¿no crees? O quizá solo necesitas que alguien repare tus pertrechos...\n\n¿Qué clase de mercader buscas?', '¿Quieres desprenderte de parte de esas ganancias mal habidas? Entiendo. ¿De qué sirve luchar si no se consigue algún botín? Estoy en lo cierto, ¿no crees? O quizá solo necesitas que alguien repare tus pertrechos...\n\n¿Qué clase de mercader buscas?', 28153),
(159995, 'esMX', 'Si quieres aprender sobre sastrería, sin dudas tienes que hablar con Pin\'jin el Paciente. Cuando sostiene su aguja, no le tiembla el pulso, es experto en el bordado de togas y, para colmo, sabe cómo coserte de pies a cabeza. Gracias a él, tengo el brazo donde tiene que estar.\n\nBúscalo detrás de esos nobles charlatanes, en el Bancal de los Artesanos, al oeste de Dazar\'alor.', 'Si quieres aprender sobre sastrería, sin dudas tienes que hablar con Pin\'jin el Paciente. Cuando sostiene su aguja, no le tiembla el pulso, es experto en el bordado de togas y, para colmo, sabe cómo coserte de pies a cabeza. Gracias a él, tengo el brazo donde tiene que estar.\n\nBúscalo detrás de esos nobles charlatanes, en el Bancal de los Artesanos, al oeste de Dazar\'alor.', 28153),
(159994, 'esMX', '¡Prúebalo y sácate las dudas!', '', 28153),
(159993, 'esMX', 'Voy a decir algo que quizá suene demasiado evidente... Rana la Cortadora tiene que ser una de las mejores desolladoras del mundo. ¿Has visto la vida salvaje que hay por este lugar?\n^Búscala en el Bancal de los Artesanos, en la base de la pirámide que está al oeste de Dazar\'alor.', 'Voy a decir algo que quizá suene demasiado evidente... Rana la Cortadora tiene que ser una de las mejores desolladoras del mundo. ¿Has visto la vida salvaje que hay por este lugar?\n^Búscala en el Bancal de los Artesanos, en la base de la pirámide que está al oeste de Dazar\'alor.', 28153),
(159992, 'esMX', '¿Minería? Delicioso. Si fuera minero, sin dudas me sumergiría en su fabulosa \"Ciudad de Oro\", Atal\'Dazar. Pero procura que no te atrapen, $n.\n\nSi quieres seguir mejorando tu arte, habla con Secott el Forjaoros. Para encontrarlo, ve al Bancal de los Artesanos, en la parte baja de Dazar\'alor, al oeste.', '¿Minería? Delicioso. Si fuera minera, sin dudas me sumergiría en su fabulosa \"Ciudad de Oro\", Atal\'Dazar. Pero procura que no te atrapen, $n.\n\nSi quieres seguir mejorando tu arte, habla con Secott el Forjaoros. Para encontrarlo, ve al Bancal de los Artesanos, en la parte baja de Dazar\'alor, al oeste.', 28153),
(159991, 'esMX', '', 'Cuando quieras regresar a los Claros de Tirisfal del presente, lo único que tienes que hacer es pedírmelo.', 28153),
(159990, 'esMX', '¡Esta cosa es una bomba! No, de verdad, podría volar el techo del palacete de Gallywix.', '', 28153),
(159989, 'esMX', 'Es un orgullo para un goblin, ¿entiendes?', '', 28153),
(159987, 'esMX', 'Unas pizcas de mi ingrediente secreto... ¡y voilà! ¡Las modificaciones están listas!', '', 28153),
(159986, 'esMX', 'Un poco de pólvora... unos fusibles y unos pedacitos de cobre...', '', 28153),
(159985, 'esMX', 'Le agregamos un poco de esto. Lo aplastamos muuuy bien.', '', 28153),
(159984, 'esMX', 'Deja que... Espera un segundo, ¿sí?', '', 28153),
(159983, 'esMX', 'Oooh, ¿me conseguiste azerita? Excelente...', '', 28153),
(159982, 'esMX', '¿Quieres explosiones? Tus deseos son órdenes. Sube a una de estas bellezas y llévala a dar un paseo.', '', 28153),
(159981, 'esMX', '¡Quita tus manos de mi poción!', '¡Quita tus manos de mi poción!', 28153),
(159980, 'esMX', 'El Sr. Sonrisa no quiere que hable con adultos.', '', 28153),
(159979, 'esMX', 'Cables y engranajes rotos cuelgan desde este cosechador averiado.', 'Cables y engranajes rotos cuelgan desde este cosechador averiado.', 28153),
(159978, 'esMX', 'Un martillo usado descansa sobre la mesa.', 'Un martillo usado descansa sobre la mesa.', 28153),
(159977, 'esMX', 'Reparar el cosechador.', 'Reparar el cosechador.', 28153),
(159976, 'esMX', '¿Has visto las armaduras de cuero que usan los zandalari? Si lo que quieres es aprender sus secretos, ve al Bancal de los Artesanos, en la parte baja de Dazar\'alor, al oeste.\n\nCuando llegues, busca a Xanjo. Es el peletero experto allí.', '¿Has visto las armaduras de cuero que usan los zandalari? Si lo que quieres es aprender sus secretos, ve al Bancal de los Artesanos, en la parte baja de Dazar\'alor, al oeste.\n\nCuando llegues, busca a Xanjo. Es el peletero experto allí.', 28153),
(159975, 'esMX', 'Recupera el martillo.', 'Recupera el martillo.', 28153),
(159974, 'esMX', 'Examinar las propiedades de la poción.', 'Examinar las propiedades de la poción.', 28153),
(159973, 'esMX', 'Recuperaremos a Derek... de una forma u otra.', '', 28153),
(159972, 'esMX', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', 28153),
(159971, 'esMX', 'La botella está llena de un líquido extraño y turbulento.', 'La botella está llena de un líquido extraño y turbulento.', 28153),
(159970, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCampeón caballero Dirk Longfellow\n\nCapitán de los Drustvaria', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCampeón caballero Dirk Longfellow\n\nCapitán de los Drustvaria', 28153),
(159969, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitán del Indulto del Vendaval', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitán del Indulto del Vendaval', 28153),
(159968, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTeniente coronel Andrew Avrinn\n\nCapitán de las Aves Canoras', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTeniente coronel Andrew Avrinn\n\nCapitán de las Aves Canoras', 28153),
(159967, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Aloysius Millsworth', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Aloysius Millsworth', 28153),
(159966, 'esMX', 'Te subes a un bote, llegas a este nuevo lugar, comienzas a atrapar a los insectos y a toda la vida salvaje que tienes a tu alrededor y terminas en el medio de una zona escalofriante como esta. Al menos eso es lo que me sucedió a mí. De todas formas, me las ingenié para atrapar a algunas criaturitas muy valientes. Antes de venir a este lugar, no las había visto en ninguna otra parte. ¿Quieres ver de lo que son capaces?', '', 28153),
(159965, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Ava MacArthur', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Ava MacArthur', 28153),
(159964, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Chris Lee', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Chris Lee', 28153),
(159963, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Evan Morris', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento Evan Morris', 28153),
(159962, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nTeniente caballero Samuel Robertson', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nTeniente caballero Samuel Robertson', 28153),
(159961, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Eloise Hesterfield', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Eloise Hesterfield', 28153),
(159960, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Sarah Gallows', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Sarah Gallows', 28153),
(159959, 'esMX', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendente O\'Keefe', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendente O\'Keefe', 28153),
(159958, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento J. Mills', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSargento J. Mills', 28153),
(159957, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSargento primero Murgatroyd Smith', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSargento primero Murgatroyd Smith', 28153),
(159956, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Geoffrey Van Houten', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Geoffrey Van Houten', 28153),
(159955, 'esMX', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nProveedor Jarrod', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nProveedor Jarrod', 28153),
(159954, 'esMX', '¿Necesitas reparar tu armadura? Tengo la mejor forja del desierto... bueno, la única forja del desierto.', '¿Necesitas reparar tu armadura? Tengo la mejor forja del desierto... bueno, la única forja del desierto.', 28153),
(159953, 'esMX', '¡El mar te devorará!', '', 28153),
(159952, 'esMX', '', '¿Qué necesitas de los kaldorei?', 28153),
(159951, 'esMX', '', '¡Fuera de nuestros archivos! ¡Estas investigaciones no les pertenecen!', 28153),
(159950, 'esMX', '', 'Que Elune ilumine tu camino.', 28153),
(159949, 'esMX', '', 'No pierdas la fe.', 28153),
(159948, 'esMX', 'Con todos los elfos de sangre que hemos traído, uno pensaría que tendría que haber algún joyero, dado que ellos prácticamente inventaron la profesión. Supongo que los zandalari no nos quieren confiar sus riquezas.\n\nSi lo que quieres es aprender más, tendrás que hablar con Seshuli. La encontrarás en el Salón de los Brillos. Para llegar hasta allí, ve al Bancal de los Artesanos, al oeste de Dazar\'alor. Luego gira y cuando veas la pirámide, métete en uno de los túneles. Allí la encontrarás.', 'Con todos los elfos de sangre que hemos traído, uno pensaría que tendría que haber algún joyero, dado que ellos prácticamente inventaron la profesión. Supongo que los zandalari no nos quieren confiar sus riquezas.\n\nSi lo que quieres es aprender más, tendrás que hablar con Seshuli. La encontrarás en el Salón de los Brillos. Para llegar hasta allí, ve al Bancal de los Artesanos, al oeste de Dazar\'alor. Luego gira y cuando veas la pirámide, métete en uno de los túneles. Allí la encontrarás.', 28153),
(159947, 'esMX', 'Si buscas a alguien para aprender más sobre el arte de la inscripción, dirígete al Gran Sello.\n\nCuando llegues allí, sube las escaleras del lado este y encontrarás el Salón de los Cronistas. Una vez adentro, busca a la Cronista Kizani.', 'Si buscas a alguien para aprender más sobre el arte de la inscripción, dirígete al Gran Sello.\n\nCuando llegues allí, sube las escaleras del lado este y encontrarás el Salón de los Cronistas. Una vez adentro, busca a la Cronista Kizani.', 28153),
(159946, 'esMX', '¿Herboristería? Conozco a alguien. Se hace llamar Jahden Fla. Lo encontrarás cuidando su jardín en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.', '¿Herboristería? Conozco a alguien. Se hace llamar Jahden Fla. Lo encontrarás cuidando su jardín en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.', 28153),
(159945, 'esMX', '', 'Somos los hijos de Elune.', 28153),
(159944, 'esMX', '', 'Ishnu-alah.', 28153),
(159943, 'esMX', '', 'La diosa me da fuerzas.', 28153),
(159942, 'esMX', 'Hay una zandalari en la rivera de la Esquirla, al norte de Dazar\'alor. Se llama Tali la silente, y cuentan los rumores que puede pescar cualquier cosa desde cualquier sitio.\n\nComo su nombre lo indica, no hace alarde de sus habilidades. Deberás descubrir por tu cuenta si realmente es tan buena.', 'Hay una zandalari en la rivera de la Esquirla, al norte de Dazar\'alor. Se llama Tali la silente, y cuentan los rumores que puede pescar cualquier cosa desde cualquier sitio.\n\nComo su nombre lo indica, no hace alarde de sus habilidades. Deberás descubrir por tu cuenta si realmente es tan buena.', 28153),
(159941, 'esMX', 'Descansen.', 'Descansen.', 28153),
(159940, 'esMX', 'Más rápido. ¡Sigan practicando!', 'Más rápido. ¡Sigan practicando!', 28153),
(159939, 'esMX', '¡Ojos bien abiertos! ¡No pueden dispararle a lo que no ven!', '¡Ojos bien abiertos! ¡No pueden dispararle a lo que no ven!', 28153),
(159938, 'esMX', '¡Muy pobre! ¡Tendremos que repetirlo hasta que les salga bien!', '¡Muy pobre! ¡Tendremos que repetirlo hasta que les salga bien!', 28153),
(159937, 'esMX', '¡Dejó caer sus municiones, Kelada! <Suspiro> ¡Hágalo bien la próxima!', '¡Dejó caer sus municiones, Kelada! <Suspiro> ¡Hágalo bien la próxima!', 28153),
(159936, 'esMX', '¿Cuándo fue la última vez que limpió su rifle, soldado? ¿Es que no sabe cómo hacerlo?', '¿Cuándo fue la última vez que limpió su rifle, soldado? ¿Es que no sabe cómo hacerlo?', 28153),
(159935, 'esMX', '¡PRESENTEN!', '¡PRESENTEN!', 28153),
(159934, 'esMX', '¡ARMAAAAS... al hombro!', '¡ARMAAAAS... al hombro!', 28153),
(159933, 'esMX', 'Ahora entiendo por qué Aspafresno no logró mandar a su gente. ¡Ese lugar es aterrador!', '', 28153),
(159932, 'esMX', '¡Eh, tú! ¿Has visto lo que pueden hacer estas criaturas? Cazan en manada. Acechan a su presa, la distraen y luego lanzan el golpe de gracia. Son criaturitas muy voraces, eh. Pero aquí mando yo, ¡y ellas lo saben! ¿Quieres ver qué tal les va a tus bestias luchando contra las mías?', '', 28153),
(159931, 'esMX', '$n mastica algunas palomitas de maíz.', '$n mastica algunas palomitas de maíz.', 28153),
(159930, 'esMX', 'Sí, buscas a Shuga Rompetapas. La encontrarás en el Bancal de los Artesanos junto a su compañero, Myxle. El Bancal está en la parte oeste de Dazar\'alor, cerca de la base de la pirámide.\n\n¿Qué es lo que piensas hacer volar por los aires?', 'Sí, buscas a Shuga Rompetapas. La encontrarás en el Bancal de los Artesanos junto a su compañero, Myxle. El Bancal está en la parte oeste de Dazar\'alor, cerca de la base de la pirámide.\n\n¿Qué es lo que piensas hacer volar por los aires?', 28153),
(159929, 'esMX', 'Uh... Esto es malo. Esto es muy malo... La llevaron a Límite del Destino.', '', 28153),
(159928, 'esMX', 'Ah. Veamos qué tenemos.', '', 28153),
(159927, 'esMX', 'Hay pruebas suficientes para encerrarlo de por vida. Pero como está muerto, ya no tiene que preocuparse por eso.', '', 28153),
(159926, 'esMX', 'La encantadora elfa de sangre Quinni vino con nosotros. Presta atención. Para encontrarla, tendrás que ir a la parte oeste de Dazar\'alor, al Bancal de los Artesanos. Cuando llegues a ese lugar, gira de cara a la pirámide y busca un camino que va hacia abajo. Hay un túnel te llevará hacia un sitio al que llaman el Salón de los Destellos.\n\nEn mi opinión, trajimos demasiados elfos de sangre. Algo así genera muchas sospechas...', 'La encantadora elfa de sangre Quinni vino con nosotros. Presta atención. Para encontrarla, tendrás que ir a la parte oeste de Dazar\'alor, al Bancal de los Artesanos. Cuando llegues a ese lugar, gira de cara a la pirámide y busca un camino que va hacia abajo. Hay un túnel te llevará hacia un sitio al que llaman el Salón de los Destellos.\n\nEn mi opinión, trajimos demasiados elfos de sangre. Algo así genera muchas sospechas...', 28153),
(159925, 'esMX', 'Oro, gemas, mapas del tesoro, notas de rescate... Vaya, vaya, Harlan fue un niño muy, muy travieso.', '', 28153),
(159924, 'esMX', 'Debo admitir que admiro tu ética de trabajo. Bien hecho.', '', 28153),
(159923, 'esMX', '', 'Por lo general, eso es una buena señal. ¿Qué hay adentro?', 28153),
(159922, 'esMX', 'Quién lo habría dicho... ¡no explotó!', '', 28153),
(159921, 'esMX', 'Los Pantoque necesitan mantener a los ranishu bien alimentados para que sus mecas funcionen. Ayuda a los goblins. Cuanto antes terminen, más pronto se irán.', '', 28153),
(159920, 'esMX', 'Una última cerradura. Esperemos que no tenga trampa.', '', 28153),
(159919, 'esMX', 'Bien. Abramos este cofre.', '', 28153),
(159918, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCapitán caballero Ellis R. Ladimore\n\nCapitán de los Trotafondos', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCapitán caballero Ellis R. Ladimore\n\nCapitán de los Trotafondos', 28153),
(159917, 'esMX', '¡Inspección... armas!', '¡Inspección... armas!', 28153),
(159916, 'esMX', 'Los reales zandalari nos prestaron a su cocinera. Se llama T\'sarah. La podrás encontrar dentro del Gran Sello, en la parte oeste, subiendo unas escaleras.\n\nNo podría decirte si cocina bien o no porque yo como todo crudo.', 'Los reales zandalari nos prestaron a su cocinera. Se llama T\'sarah. La podrás encontrar dentro del Gran Sello, en la parte oeste, subiendo unas escaleras.\n\nNo podría decirte si cocina bien o no porque yo como todo crudo.', 28153),
(159915, 'esMX', 'En la parte oeste de Dazar\'alor, abajo, encontrarás el Bancal de los Artesanos. Allí verás a un trol zandalari enorme y siniestro golpeando su yunque día y noche. Lo llaman maestro de forja Zak o algo así. Créeme, es imposible que no lo veas.', 'En la parte oeste de Dazar\'alor, abajo, encontrarás el Bancal de los Artesanos. Allí verás a un trol zandalari enorme y siniestro golpeando su yunque día y noche. Lo llaman maestro de forja Zak o algo así. Créeme, es imposible que no lo veas.', 28153),
(159914, 'esMX', 'Trajimos a la Examinadora Alerinda con nosotros. Está dentro del Gran Sello, en una sala en el lado oeste.\n\nCreo que su gente está intentando desenterrar un dinosaurio gigante al sudoeste. ¿Por qué no preguntas si necesitan ayuda?', 'Trajimos a la Examinadora Alerinda con nosotros. Está dentro del Gran Sello, en una sala en el lado oeste.\n\nCreo que su gente está intentando desenterrar un dinosaurio gigante al sudoeste. ¿Por qué no preguntas si necesitan ayuda?', 28153),
(159913, 'esMX', '¡Fusileros! ¡Formen fila!', '¡Fusileros! ¡Formen fila!', 28153),
(159912, 'esMX', '', 'Los dos estamos felices de que hayas regresado a salvo, $n.', 28153),
(159911, 'esMX', '', '¡Espera! Yo no fui la que... <suspiro>', 28153),
(159910, 'esMX', '¡Ah, ahí está $unuestro valiente adalid:nuestra valiente adalid;! Te dije que $n estaría bien, Taelia. Te preocupas demasiado.', '', 28153),
(159909, 'esMX', '', 'La preocupación me invade cada vez que mi familia se dirige a esas colinas.', 28153),
(159908, 'esMX', '¡Ey! ¡Fíjate dónde tiras esas cosas!', '', 28153),
(159907, 'esMX', '', '¡Quedan unas pocas granadas, $n! ¡Arrójaselas!', 28153),
(159906, 'esMX', 'Entonces buscas a Kumali la inteligente. Está en el Bancal de los Artesanos, en la parte inferior de la zona oeste de Dazar\'alor.\n\nTen cuidado. Kumali es de esos Lanza Negra sobre los que siempre nos advierten por su espeluznante vudú.', 'Entonces buscas a Kumali la inteligente. Está en el Bancal de los Artesanos, en la parte inferior de la zona oeste de Dazar\'alor.\n\nTen cuidado. Kumali es de esos Lanza Negra sobre los que siempre nos advierten por su espeluznante vudú.', 28153),
(159905, 'esMX', 'Si ves a alguien sospechoso por aquí, avísame. Le sacaré la verdad a los golpe\'.', '', 28153),
(159904, 'esMX', 'Lok la Roca protege esta bóveda. ¡Nadie podrá saquearla!', '', 28153),
(159903, 'esMX', '... Después de esto, tenemos que hablar sobre los gustos que tenemos en común.', '', 28153),
(159902, 'esMX', '', '¡Hemos llegado a mi parte favorita!', 28153),
(159901, 'esMX', 'Hemos llegado a mi parte favorita.', '', 28153),
(159900, 'esMX', 'Regresaremos a salvo... con el prisionero.', '', 28153),
(159899, 'esMX', 'Al parecer, los tesoro\' tienen todo tipo formas y tamaño\'. Todos los días me sorprenden las cosa\' que guardan en estas bóveda\'.', '', 28153),
(159898, 'esMX', '', 'Entendido.', 28153),
(159897, 'esMX', 'No dejaré que les pasa nada a tus objeto\' valioso\', $p.\n\nHe protegido tesoro\' de reyes, almacenes de mercadere\', abalorios de demente\' y almuerzos de personas sin linaje.\n\nNo importa qué guardes, me aseguraré de que no le pase nada.', '', 28153),
(159896, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nAlférez Alison Flint', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nAlférez Alison Flint', 28153),
(159895, 'esMX', 'La última pandilla que intentó robar eh\'ta bóveda ahora está en Vol\'dun... como todos los que lo intentaron.', '', 28153),
(159894, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Jameson Keefe', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCabo Jameson Keefe', 28153),
(159893, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Lorelei Whetstone', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado Lorelei Whetstone', 28153),
(159892, 'esMX', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado James Simmons', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldado James Simmons', 28153),
(159891, 'esMX', 'Eh\'ta es la bóveda más segura de Zandalar. Nada entra ni sale sin mi aprobación\n\nSi guardas tus cosa\' aquí, no tendrás de qué preocuparte. Es así de simple.', '', 28153),
(159890, 'esMX', 'No me tomo mi trabajo como guardia de la bóveda a la ligera, $p.\n\nSi tienes buenas intencione\', yo tengo buenas intencione\'.\n\nSi tienes malas intencione\', entonces te aplastaré hasta que quepas en una caja diminuta y te enviaré en barco a Vol\'dun para que te devoren los buitre\' de los sethrak.\n\n¿Entiendes?', '', 28153),
(159889, 'esMX', 'Un acuerdo que he pactado con los zandalari. Me dejan quedarme y yo los invito a mis fiestas.', '', 28153),
(159888, 'esMX', 'Alianza en Zandalar, debes tener muchísimo cuidado.\n\nSi te ven, los guardias y los dioses no dudarán en atacarte.', '', 28153),
(159887, 'esMX', 'Estamos muy lejos de casa, tú y yo. ¿Por qué no te quedas a tomar algo en el Gran Bazar?', '', 28153),
(159886, 'esMX', '', 'Astarii... apresúrate. Evacúa la ciudad... antes de que arda...', 28153),
(159885, 'esMX', 'Claro. Si buscas ayuda de profesionales, los encontrarás a casi todos en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.\n\n¿En qué profesión quieres entrenarte?', 'Claro. Si buscas ayuda de profesionales, los encontrarás a casi todos en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.\n\n¿En qué profesión quieres entrenarte?', 28153),
(159884, 'esMX', 'El saurolisco dio vuelta la carreta y los suministros salieron volando por todas partes.', '', 28153),
(159883, 'esMX', '', 'Puede que a Genn le digan \"Viejo lobo\", pero yo lo hago ronronear como un gatito.', 28153),
(159882, 'esMX', '', 'Los elfos de la noche salvaron a mi pueblo. Haré todo lo que pueda por ellos.', 28153),
(159881, 'esMX', 'Me quedaré aquí y alistaré los caballos.', '', 28153),
(159880, 'esMX', '', 'Los kaldorei necesitan nuestra ayuda.', 28153),
(159879, 'esMX', '', 'Queda poco tiempo.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159878, 'esMX', '', '¡Gracias! Creo que puedo volver por mi cuenta.', 28153),
(159877, 'esMX', '', 'Haz que paguen por esto, adalid.', 28153),
(159876, 'esMX', '', 'Tanta sangre inocente...', 28153),
(159875, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(159874, 'esMX', '¡Déjenme $Ual feo:a la fea;!', '¡Déjenme $Ual feo:a la fea;!', 28153),
(159873, 'esMX', '¡No se lleven prisioneros!', '¡No se lleven prisioneros!', 28153),
(159872, 'esMX', '¡Esto es propiedad de la Alianza! ¡Largo de aquí!', '¡Esto es propiedad de la Alianza! ¡Largo de aquí!', 28153),
(159871, 'esMX', '¡Has cometido un grave error, escoria de la Horda!', '¡Has cometido un grave error, escoria de la Horda!', 28153),
(159870, 'esMX', '', '¡Salva a todos los que puedas!', 28153),
(159869, 'esMX', '', 'Los culpables pagarán por sus crímenes.', 28153),
(159868, 'esMX', 'El resto de nosotros te veremos allí cuando todo haya terminado, ayudaremos con cualquier informe que sea necesario.', '', 28153),
(159867, 'esMX', '', 'Por la Alianza.', 28153),
(159866, 'esMX', '', 'Mi hogar me llama.', 28153),
(159865, 'esMX', '', 'Gracias por tu servicio.', 28153),
(159864, 'esMX', '', '¿Puedo ayudarte?', 28153),
(159863, 'esMX', '', 'Un reino no es un lugar: es un pueblo.', 28153),
(159862, 'esMX', '', 'Gilneas honra tu servicio.', 28153),
(159861, 'esMX', '', 'Saludos, adalid.', 28153),
(159860, 'esMX', 'Cuchillo. Garganta. No es tan complicado.', '', 28153),
(159859, 'esMX', 'Matar ya es una recompensa. Pero el oro también es bienvenido.', '', 28153),
(159858, 'esMX', '$n, avísanos cuando estés $Ulisto:lista; para comenzar los preparativos para hacer estallar esta nave. Después, quiero que vayas a informarle nuestro triunfo al rey Wrynn.', '', 28153),
(159857, 'esMX', 'Vamos a impresionar a la jefa de guerra... y ganarnos una buena recompensa.', '', 28153),
(159856, 'esMX', 'Vamos a darles una lección a estos salvajes.', '', 28153),
(159855, 'esMX', 'Keeshan, Kelsey, coloquen los explosivos para que exploten después de que se hayan ido todos.', '', 28153),
(159854, 'esMX', 'No perdamos el tiempo.', '', 28153),
(159853, 'esMX', 'La guerra trae muchas oportunidades.', '', 28153),
(159852, 'esMX', 'Umbric, necesitamos una última falla del Vacío para sacar a todas nuestras tropas de aquí.', '', 28153),
(159851, 'esMX', 'Hay que destruir esta nave. Shandris, ayuda a las tropas que nos quedan a emprender la retirada.', '', 28153),
(159848, 'esMX', 'Me encanta mi trabajo.', '', 28153),
(159847, 'esMX', '¿Manos a la obra?', '', 28153),
(159845, 'esMX', '¡Mi pueblo me liberará de sus cárceles, tal como hicieron con la princesa Talanji y Zul!', '', 28153),
(159844, 'esMX', 'Muero de ganas de ver cómo lo intentan. Bien, pasemos a otro asunto.', '', 28153),
(159843, 'esMX', 'Puedes luchar contra nosotros durante todo el camino o cooperar. Tú decides.', '', 28153),
(159842, 'esMX', 'Yo me encargaré.', 'Yo me encargaré.', 28153),
(159841, 'esMX', 'No. Ya hemos derramado demasiada sangre por hoy, capitán. Te encerraremos, volverás a Ventormenta.', '', 28153),
(159840, 'esMX', '¡Perros de la Alianza! ¡Mátenme, acaben con esto de una vez!', '', 28153),
(159839, 'esMX', '', 'El capitán Zalkran intentaba huir a Zuldazar, pero Falstad y yo lo frenamos.', 28153),
(159838, 'esMX', 'Shandris, ¿me podrías informar cuál es la situación?', 'Shandris, ¿me podrías informar cuál es la situación?', 28153),
(159837, 'esMX', 'Can you return me to the present time?', 'Can you return me to the present time?', 28153),
(159836, 'esMX', '¿Puedes mostrarme cómo lucían los Claros de Tirisfal antes de la Batalla por Lordaeron?', '¿Puedes mostrarme cómo lucían los Claros de Tirisfal antes de la Batalla por Lordaeron?', 28153),
(159835, 'esMX', '', 'Ah... y si ves a mi nieto, Charles, asegúrate de que no se esté ocultando debajo de un árbol en algún lugar.', 28153),
(159834, 'esMX', '¿Has comenzado a capturar las mascotas que ofrece esta extraña tierra? Yo, personalmente, estoy buscando una de esas sangrientas máscaras tikis, aunque no sé bien qué pensarán sobre eso los habitantes de este lugar...\n\nSi buscas un maestro de establo, encontrarás a un zandalari, el cuidador de bestias Kalatak, cerca de la base noroeste de Dazar\'alor.', '¿Has comenzado a capturar las mascotas que ofrece esta extraña tierra? Yo, personalmente, estoy buscando una de esas sangrientas máscaras tikis, aunque no sé bien qué pensarán sobre eso los habitantes de este lugar...\n\nSi buscas un maestro de establo, encontrarás a un zandalari, el cuidador de bestias Kalatak, cerca de la base noroeste de Dazar\'alor.', 28153),
(159833, 'esMX', 'La tripulación de la Princesa Púrpura está de huelga. No les presté mucha atención, pero parece que protestan porque hace once años que no les pagan.', 'La tripulación de la Princesa Púrpura está de huelga. Creo que protestan porque hace once años que no les pagan, pero no presté mucha atención.', 28153),
(159832, 'esMX', '¿Cómo puedo llegar a la Vega de Tuercespina?', '¿Cómo puedo llegar a la Vega de Tuercespina?', 28153),
(159831, 'esMX', '', '¡Adalid! Parece que necesito tu ayuda nuevamente.', 28153),
(159830, 'esMX', '', 'Te agradezco nuevamente, adalid... aunque parece que todavía estamos en apuros.', 28153),
(159829, 'esMX', '', 'Sí, madre. Regresaré con ellos en breve.', 28153),
(159828, 'esMX', '', '¡Taelia! Lleva a $n y reúne a la milicia. Jaina y yo prepararemos las defensas.', 28153),
(159827, 'esMX', '', '¡$n! Parece que necesito tu ayuda nuevamente.', 28153),
(159826, 'esMX', '', 'Priscilla ha regresado por mi ciudad...', 28153),
(159825, 'esMX', '', '¿O... llegamos demasiado tarde?', 28153),
(159824, 'esMX', '', 'Dime lo que descubriste. ¿Había alguna señal de Jaina?', 28153),
(159823, 'esMX', '', '¡$n!... Veo que vuelves $usolo:sola;.', 28153),
(159822, 'esMX', '', 'La carreta está destruida y podríamos haber muerto. \n\nLa bestia que nos atacó está en esa cueva. ¡No me iré de aquí hasta que esté muerta!', 28153),
(159821, 'esMX', '', '¡Lady almirante! ¡Hay naves a la vista! ¡Llevan los colores de Aspafresno!', 28153),
(159820, 'esMX', '', 'Madre... Yo...', 28153),
(159819, 'esMX', '', 'Déjame ver si puedo hacerlo como corresponde esta vez... Bienvenida a casa, hija.', 28153),
(159818, 'esMX', '', 'Es bueno sentir la brisa marina. Gracias, $n. Sin tu intervención, quizás nunca habría vuelto a sentirla.', 28153),
(159817, 'esMX', '¡Saludos, $uInquisidor:Inquisidora;!\n\nLady Tarjasenda me ha pedido que aliste mi halcón más veloz para entregarte un mensaje.', '', 28153),
(159816, 'esMX', 'Dile a Katherine Valiente que nos encontraremos en Gol Inath.', 'Dile a Katherine Valiente que nos encontraremos en Gol Inath.', 28153),
(159815, 'esMX', 'Estoy buscando la forma de entrar en las Tierras Plagadas.', 'Estoy buscando la forma de entrar en las Tierras Plagadas.', 28153),
(159814, 'esMX', '', 'Protégela con tu vida. Kul Tiras ya ha perdido a demasiados Valiente.', 28153),
(159813, 'esMX', '', '¡Lo lograste! ¡La efigie funcionó!', 28153),
(159812, 'esMX', '', '¡Eso es! ¡Las marcas en la pared muestran la secuencia!', 28153),
(159811, 'esMX', '', 'Tal vez haya que seguir un patrón para activar las runas...', 28153),
(159810, 'esMX', '', 'Eso debe haber sido desagradable...', 28153),
(159809, 'esMX', '', 'Intenta activar otra.', 28153),
(159808, 'esMX', '', '¡Se esfumó! ¿Acaso estas runas son un resguardo?', 28153),
(159807, 'esMX', '', 'Ahora... debe haber alguna pista sobre cómo funciona esto.', 28153),
(159806, 'esMX', '', 'Bueno, eso activó... algo...', 28153),
(159805, 'esMX', '', 'Esto parece una especie de portal. Tal vez debamos colocar la efigie aquí.', 28153),
(159804, 'esMX', '', 'Tengo que tranquilizarme. Jaina ha tenido que enfrentar cosas mucho peores por mi culpa.', 28153),
(159803, 'esMX', '', 'Este lugar me congela el alma... siento que camino sobre mi propia tumba...', 28153),
(159802, 'esMX', '', 'Parece que a partir de aquí estamos solos. Te sigo.', 28153),
(159801, 'esMX', '', 'Esos... monstruos de los bosques emboscaron a mi guardia de honor. Su sacrificio me salvó la vida.', 28153),
(159800, 'esMX', '', '¡$n! ¡Qué bueno verte!', 28153),
(159799, 'esMX', '¡Sí, $useñor:señora;! ¡Hannibal llevará su mensaje a la Fortaleza Valiente de inmediato!', '', 28153),
(159798, 'esMX', 'Ahora estás a salvo.', 'Ahora estás a salvo.', 28153),
(159797, 'esMX', '', '$UInquisidor:Inquisidora;, sé que Katherine planea unirse a ti en esta persecución insensata.', 28153),
(159796, 'esMX', 'Oculeth, ese natonocturno tenebroso, creó algunos portales para que pudiéramos viajar a Orgrimmar, Ciudad de Lunargenta y Cima del Trueno. Podrás encontrarlo en el Salón de los Pasos Ancestrales dentro del Gran Sello, al este.\n\nPor desgracia, no hay un portal que lleve a Entrañas. ¡Pronto nos vengaremos de la escoria de la Alianza! ¡Genn, Jaina y el rey Anduin pagarán por sus delitos!\n\n¡Victoria para Sylvanas! ¡Que nos gobierne como jefa de guerra durante miles de años!', 'Oculeth, ese natonocturno tenebroso, creó algunos portales para que pudiéramos viajar a Orgrimmar, Ciudad de Lunargenta y Cima del Trueno. Podrás encontrarlo en el Salón de los Pasos Ancestrales dentro del Gran Sello, al este.\n\nPor desgracia, no hay un portal que lleve a Entrañas. ¡Pronto nos vengaremos de la escoria de la Alianza! ¡Genn, Jaina y el rey Anduin pagarán por sus delitos!\n\n¡Victoria para Sylvanas! ¡Que nos gobierne como jefa de guerra durante miles de años!', 28153),
(159795, 'esMX', 'El camino a Thros será traicionero, pero no será nada en comparación con lo que te espera en las Tierras Plagadas.\n\nPrepárate, $c, los esbirros de Thros usarán tus miedos y remordimientos más profundos como armas para lastimarte.', '', 28153),
(159794, 'esMX', 'La entrada a Thros yace dentro de este gran árbol, Gol Inath, pero cruzar el umbral no es tan sencillo como pasar caminando.\n\nPara abrir la senda, necesitarás una efigie de mucho poder. No uno de los abalorios del aquelarre, sino uno que posea magia ancestral de los drust.', '', 28153),
(159793, 'esMX', '', 'La carreta giró en el aire. ¡Fue aterrador!\n\nMe dirigía al pueblo para buscar ayuda, pero sentí temor.', 28153),
(159792, 'esMX', 'Ah, es bueno ver a $uotro seguidor:otra seguidora; de la senda.\n\n¿Qué necesitas de los Oradores de Espinas?', '', 28153),
(159791, 'esMX', '¿Así que $uel:la continental regresa?\n\nCreo que nuestra deuda ha sido saldada. ¿Vienes a buscar más favores de los Oradores de Espinas?', '', 28153),
(159790, 'esMX', 'Hace mucho que $uun:una; continental no pone un pie en mi arboleda.\n\n¿Vienes a aprender los misterios de los Oradores de Espinas o quieres quedarte con el control de esta tierra, como la mayoría de los de tu clase?', '', 28153),
(159789, 'esMX', 'Esto... cambia todo.', '', 28153),
(159788, 'esMX', 'Parece que me he equivocado. Thros ha venido a nosotros.', '', 28153),
(159787, 'esMX', 'Esto no ha terminado, viejo oso.', '', 28153),
(159786, 'esMX', 'Me encargaré de que estén a salvo.', 'Me encargaré de que estén a salvo.', 28153),
(159785, 'esMX', '¿Quién eres tú para decidir quién es digno? ¡Tus métodos viles avergüenzan a nuestra especie, Tul!', '', 28153),
(159784, 'esMX', '¿Compartirás nuestros dones con estos desgraciados, Ulfar? ¡Mereces arder con ellos!', '', 28153),
(159783, 'esMX', '¿Cómo puedo llegar al Fiordo Aquilonal?', '¿Cómo puedo llegar al Fiordo Aquilonal?', 28153),
(159782, 'esMX', '¡Oradores de espinas, a las armas!', '', 28153),
(159781, 'esMX', 'Perdimos contacto con el Besanubes en el Mare Magnum. Queríamos establecer un récord: ¡ochocientos quince vuelos sin cargar combustible! Seguramente están bien.', 'Perdimos contacto con el Besanubes en el Mare Magnum. Queríamos establecer un récord: ¡ochocientos quince vuelos sin cargar combustible! Seguramente están bien.', 28153),
(159780, 'esMX', '¡Gorak Tul! ¡No puede ser!', '', 28153),
(159779, 'esMX', 'Oh, ya es tarde para eso, viejo oso.', '', 28153),
(159778, 'esMX', 'Es mejor que algunos caminos permanezcan cerrados. Los del otro lado podrían recorrerlos.', '', 28153),
(159777, 'esMX', 'Me temo que no podré ayudarte en esto, continental.', '', 28153),
(159776, 'esMX', '¿Deseas entrar en Thros? Temo que no podré ayudarte, continental.', '', 28153),
(159775, 'esMX', '', 'Espero que no estés hablando en serio cuando dices que irás a las Tierras Plagadas.', 28153),
(159774, 'esMX', '', '¡$UInquisidor:Inquisidora;! ¡He recibido un mensaje de Katherine!', 28153),
(159773, 'esMX', '', 'Yo soy la culpable de su destino. Estaré allí para cerciorarme de arreglarlo.', 28153),
(159772, 'esMX', '', 'Si encuentras... Cuando encuentres a Jaina, quiero estar ahí. Me enfrentaré a cualquier peligro.', 28153),
(159771, 'esMX', '', 'Una cosa más, $n.', 28153),
(159770, 'esMX', 'Un saurolisco espantó a los caballos, la carreta se fue de costado y perdimos todos nuestros suministros.\n\nMis dos chicas, Lorraine y Mallory, aún están por ahí sueltas. Les vendría bien tu ayuda.', '', 28153),
(159769, 'esMX', 'Allí es donde iremos con algunos de mis camaradas cuando termine nuestro turno. Hay que mantenerse en forma, ¿sabes?\n\nEstá en la Armería Real, en la zona norte de Dazar\'alor, cerca de la base de la pirámide. Deberías venir con nosotros.', 'Allí es donde iremos con algunos de mis camaradas cuando termine nuestro turno. Hay que mantenerse en forma, ¿sabes?\n\nEstá en la Armería Real, en la zona norte de Dazar\'alor, cerca de la base de la pirámide. Deberías venir con nosotros.', 28153),
(159768, 'esMX', '', '¡Busca al hermano Pike! Es un maresabio leal y devoto. Sé que nos ayudará.', 28153),
(159767, 'esMX', '', 'Después de todo, seguía mis órdenes.', 28153),
(159766, 'esMX', '', 'Los maresabios son los únicos que pueden acercarse sin correr peligro, y Aspafresno no debe haber tenido ningún problema para convencerlos de que llevaran a Jaina hasta la orilla.', 28153),
(159765, 'esMX', '', 'Dime que no es demasiado tarde.', 28153),
(159764, 'esMX', '', '¿A dónde llevaron a Jaina?', 28153),
(159763, 'esMX', 'Sí, yo también.', '', 28153),
(159762, 'esMX', '', 'Sabes perfectamente lo que quise decir, Flynn. Por el bien de lady Katherine, espero que te equivoques.', 28153),
(159761, 'esMX', '¿Así que ahora apuestas, eh? ¡Qué vergüenza! ¿Qué diría Cyrus?', '', 28153),
(159760, 'esMX', 'Me imagino que tienes algo que resolver con los Lanza Negra. Sabes que el barco va hacia las Islas del Eco, ¿verdad? ¿O solo buscas dar un paseo antes de volver a Orgrimmar?\n\nSolo tienes que ir al final del muelle, al sur del Puerto de Zandalar.', 'Me imagino que tienes algo que resolver con los Lanza Negra. Sabes que el barco va hacia las Islas del Eco, ¿verdad? ¿O solo buscas dar un paseo antes de volver a Orgrimmar?\n\nSolo tienes que ir al final del muelle, al sur del Puerto de Zandalar.', 28153),
(159759, 'esMX', '', 'Bueno, si alguien puede traerla de regreso de ese lugar horrible, yo apuesto mi dinero a $n.', 28153),
(159758, 'esMX', 'La isla se llama Límite del Destino, Taelia. No Esperanza del Destino.', '', 28153),
(159757, 'esMX', 'Buen trabajo. Reagrupémonos.', '', 28153),
(159756, 'esMX', 'Puedo acercarte hasta el Lamento del Alma en Pena, $p. ¡Pero tendrás que sujetarte con fuerza!', '', 28153),
(159755, 'esMX', 'Martillo Salvaje, sepárense, despejen los cielos y eviten la detección.', '', 28153),
(159750, 'esMX', '', 'Ja... el capitán... los matará... a todos...', 28153),
(159749, 'esMX', '', '¡Es demasiado tarde! El capitán ya eh\'tá listo para revelar tu ubicación a la princesa Talanji.', 28153),
(159748, 'esMX', 'Conozco al goblin perfecto. Se llama Myxle Torcatripas. Él y su Trituramática Mk1 están en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.\n\nEste goblin afirma que su aparato puede desguazar cualquier equipo en diferentes piezas para darles otro uso o venderlas. Estuve a punto de aceptar su oferta, pero esta armadura es de la Horda.', 'Conozco al goblin perfecto. Se llama Myxie Torcatripas. Él y su Chatarramático 1000 están en el Bancal de los Artesanos, en la zona baja oeste de Dazar\'alor.\n\nEste goblin afirma que su aparato puede desguazar cualquier equipo en diferentes piezas para darles otro uso o venderlas. Estuve a punto de aceptar su oferta, pero esta armadura es de la Horda.', 28153),
(159747, 'esMX', 'Para llegar al Trono Dorado, tienes que tomar los elevadores que están dentro del Gran Sello.\n\n¿Te llevas bien con los reales? ¿Que piensas de esos ornatos que llevan en la cabeza? ¡Esos sí son cuellos fuertes, eh!', 'Para llegar al Trono Dorado, tienes que tomar los elevadores que están dentro del Gran Sello.\n\n¿Te llevas bien con los reales? ¿Que piensas de esos ornatos que llevan en la cabeza? ¡Esos sí son cuellos fuertes, eh!', 28153),
(159746, 'esMX', 'Este lugar es enorme, tengo que admitirlo. Conozco algunos lugares que podrían ser de interés para alguien como tú.', 'Este lugar es enorme, tengo que admitirlo. Conozco algunos lugares que podrían ser de interés para alguien como tú.', 28153),
(159745, 'esMX', 'Brillin la Bella está en medio del Gran Sello. Baila como los dioses, ¿no crees?', 'Brillin la Bella está en medio del Gran Sello. Baila como los dioses, ¿no crees?', 28153),
(159744, 'esMX', 'Hay una zandalari llamada Paku\'ai que se encarga de proveer vuelos. Si quieres subirte a un pterrordáctilo, la podrás encontrar en la cornisa que está afuera del Gran Sello, al este.', 'Hay una zandalari llamada Paku\'ai que se encarga de proveer vuelos. Si quieres subirte a un pterrordáctilo, la podrás encontrar en la cornisa que está afuera del Gran Sello, al este.', 28153),
(159743, 'esMX', 'Eso depende de qué emisario buscas, $n.', 'Eso depende de qué emisario buscas, $n.', 28153),
(159742, 'esMX', '¿Te llevas bien con los zandalari? Eso es muy inteligente de tu parte. Es exactamente lo que quiere la jefa de guerra.\n\nPuedes encontrar a su emisario, Natal\'hakata, dentro del Gran Sello.', '¿Te llevas bien con los zandalari? Eso es muy inteligente de tu parte. Es exactamente lo que quiere la jefa de guerra.\n\nPuedes encontrar a su emisario, Natal\'hakata, dentro del Gran Sello.', 28153),
(159741, 'esMX', '¿Quieres conocer los secretos de los tortollanos? Según dicen, viven muchísimo tiempo. No tanto como viviré yo, claro, pero viven mucho.\n\nComo sea, te recomiendo que vayas hasta el Puesto Vendescamas, al noroeste de Dazar\'alor. Busca al Coleccionista Tojo.', '¿Quieres conocer los secretos de los tortollanos? Según dicen, viven muchísimo tiempo. No tanto como viviré yo, claro, pero viven mucho.\n\nComo sea, te recomiendo que vayas hasta el Puesto Vendescamas, al noroeste de Dazar\'alor. Busca al Coleccionista Tojo.', 28153),
(159740, 'esMX', 'Claro, buscas un estilo diferente. ¿O quizás un cambio de color? Te recomiendo hablar con Connor Fígaro. Lo encontrarás en el Gran Bazar, en el puerto.', 'Claro, buscas un estilo diferente. ¿O quizás un cambio de color? Te recomiendo hablar con Connor Fígaro. Lo encontrarás en el Gran Bazar, en el puerto.', 28153),
(159739, 'esMX', '¿Por qué nunca me toca a mí montar el grifo?', '', 28153),
(159738, 'esMX', '¡No tan bajo! ¡No tan bajo!', '', 28153),
(159737, 'esMX', '', 'Volaré bajo e intentaré perderlos. ¡Abajo, Corazón de vendaval!', 28153),
(159736, 'esMX', '¡No sé cuánto más podré esperar!', '', 28153),
(159735, 'esMX', '', '¡Esperen! ¡Nos están disparando!', 28153),
(159734, 'esMX', 'El Tesoro Real está dentro de la pirámide que se encuentra en el lado oeste del Gran Sello. Queríamos que todo el personal fuera goblin, pero los zandalari se negaron.\n\nSon inteligentes.', 'El Tesoro Real está dentro de la pirámide que se encuentra en el lado oeste del Gran Sello. Queríamos que todo el personal fuera goblin, pero los zandalari se negaron.\n\nSon inteligentes.', 28153),
(159733, 'esMX', '¿Quieres ir a las Ih\'las del Eco? ¿Por qué? Allí viven los Lanza Negra. Es un lugar diminuto. Quédate en Zandalar, es más grande.\n\n¿No? Pues tienes suerte: les hemos prestado uno de nuestros barco\' de guerra pequeños. Si quieres abordarlo, ve al final del muelle, al sur del Puerto de Zandalar.', '¿Quieres ir a las Ih\'las del Eco? ¿Por qué? Allí viven los Lanza Negra. Es un lugar diminuto. Quédate en Zandalar, es más grande.\n\n¿No? Pues tienes suerte: les hemos prestado uno de nuestros barco\' de guerra pequeños. Si quieres abordarlo, ve al final del muelle, al sur del Puerto de Zandalar.', 28153),
(159732, 'esMX', 'Nave a las Islas del Eco', 'Nave a las Islas del Eco', 28153),
(159731, 'esMX', 'El capataz Al\'jibo de los Lanza Negra está en el Salón de los Pasos Ancestrale\', en el lado eh\'te del Gran Sello. No tengo muchas certeza\' sobre él porque vino con la Horda, pero sin duda dejará tus armadura\' como nueva\' y afilará tus arma\'.\n\nEso espero, o pronto te encontrarás con Bwonsamdi.', 'El capataz Al\'jibo de los Lanza Negra está en el Salón de los Pasos Ancestrale\', en el lado eh\'te del Gran Sello. No tengo muchas certeza\' sobre él porque vino con la Horda, pero sin duda dejará tus armadura\' como nueva\' y afilará tus arma\'.\n\nEso espero, o pronto te encontrarás con Bwonsamdi.', 28153),
(159730, 'esMX', 'Si nos necesitas, aléjate del bote y envía una señal. Alapresta y yo te encontraremos.', '', 28153),
(159729, 'esMX', '¡Ja! ¡Me encanta esta parte!', '', 28153),
(159728, 'esMX', 'Aquí vamos, Alapresta. Acércanos lo más bajo que puedas para evitar que nos detecten. Lo más rápido que puedas.', '', 28153),
(159727, 'esMX', 'Reparaciones', 'Reparaciones', 28153),
(159726, 'esMX', 'Claro que tienes oro para gastar. ¡Eh\'to es Zandalar! Ni siquiera los goblins tienen más oro que nosotro\'.\n\nCuéntame, ¿qué es lo que buscas?', 'Claro que tienes oro para gastar. ¡Eh\'to es Zandalar! Ni siquiera los goblins tienen más oro que nosotro\'.\n\nCuéntame, ¿qué es lo que buscas?', 28153),
(159725, 'esMX', 'Vendedores', 'Vendedores', 28153),
(159724, 'esMX', '', 'Exploraré el Borrasca Carmesí mientras tú exploras el Lamento del Alma en Pena. ¡Tor ilisar\'thera\'nal!', 28153),
(159723, 'esMX', '', 'Nos estamos acercando. Puedo sentir el hedor pútrido de la no-muerte.', 28153),
(159722, 'esMX', 'El elfo natonocturno ha estado usando su vudú en el Salón de los Pasos Ancestrale\'. Encontrarás ese lugar en el lado este del Gran Sello.\n\nEse elfo creó algo que les permite volver a sus pequeñas ciudade\'. ¿Cómo se llaman? ¿Orgrimmar, Ciudad de Lunargenta y Cima del Trueno? Bah.', 'El elfo natonocturno ha estado usando su vudú en el Salón de los Pasos Ancestrale\'. Encontrarás ese lugar en el lado este del Gran Sello.\n\nEse elfo creó algo que les permite volver a sus pequeñas ciudade\'. ¿Cómo se llaman? ¿Orgrimmar, Ciudad de Lunargenta y Cima del Trueno? Bah.', 28153),
(159721, 'esMX', 'Portales', 'Portales', 28153),
(159720, 'esMX', '¿Cómo llegaste aquí?', '¿Cómo llegaste aquí?', 28153),
(159719, 'esMX', '¡Aquí vamos! La información sobre el paradero de Jaina tiene que estar aquí dentro, no tengo dudas.\n\n<Flynn señala el cofre.>\n\nTú tienes las llaves. Haz los honores.', '', 28153),
(159718, 'esMX', '', '¡Demasiado tarde!', 28153),
(159717, 'esMX', '', 'Como sea, gané.', 28153),
(159716, 'esMX', 'Así que quieres practicar, ¿eh? En Dazar\'alor tenemo\' los mejores muñeco\' de práctica. Ve a la Armería Real.\n\nLa encontrarás al norte de la pirámide de Dazar\'alor.', 'Así que quieres practicar, ¿eh? En Dazar\'alor tenemo\' los mejores muñeco\' de práctica. Ve a la Armería Real.\n\nLa encontrarás al norte de la pirámide de Dazar\'alor.', 28153),
(159715, 'esMX', '<Zenbaro tose.>', '', 28153),
(159714, 'esMX', 'Muñecos de práctica', 'Muñecos de práctica', 28153),
(159713, 'esMX', '', 'Cuando quieras regresar a las Tierras Altas de Arathi del presente, lo único que tienes que hacer es pedírmelo.', 28153),
(159712, 'esMX', 'Necesito que me cuides la espalda mientras realizo el ritual. Solo me tomará unos momentos.', '', 28153),
(159711, 'esMX', '¿Puedes llevarme de regreso al presente?', '¿Puedes llevarme de regreso al presente?', 28153),
(159710, 'esMX', '<Dale la cantimplora a Zenbaro.>', '<Dale la cantimplora a Zenbaro.>', 28153),
(159709, 'esMX', 'Bien, $n. Acabemos con esto.', '', 28153),
(159708, 'esMX', '¿Puedes mostrarme cómo lucían las Tierras Altas de Arathi antes de que estallara la guerra?', '¿Puedes mostrarme cómo lucían las Tierras Altas de Arathi antes de que estallara la guerra?', 28153),
(159707, 'esMX', '', '¡Aquí veo su nombre! Suba por las escaleras y diríjase a la oficina más alejada. El Sr. Camden lo estará esperando.', 28153),
(159706, 'esMX', '', 'La guerra azota estas tierras y repite los mismos patrones de antaño. El tiempo es cíclico.\n\nDisculpa. A veces olvido que ustedes son muy... lineales.\n\n¿Cómo puedo ayudarte?', 28153),
(159705, 'esMX', '', 'Lo siento, pero nadie puede entrar sin una cita. ¡Guardias!', 28153),
(159704, 'esMX', 'Sí, tengo una cita. Mi nombre es M. Arbor.', 'Sí, tengo una cita. Mi nombre es M. Arbor.', 28153),
(159703, 'esMX', '¿No sabes quién soy? Soy $n, ¡campeón de la Alianza! ¡Tengo que ver sus archivos ahora mismo!', '¿No sabes quién soy? Soy $n, ¡campeona de la Alianza! ¡Tengo que ver sus archivos ahora mismo!', 28153),
(159702, 'esMX', 'Tengo una cita con tu jefe. ¡Es vital que hable con él lo antes posible!', 'Tengo una cita con tu jefe. ¡Es vital que hable con él lo antes posible!', 28153),
(159701, 'esMX', '', '¿En qué puedo ser de ayuda hoy?', 28153),
(159700, 'esMX', '', '$uBienvenido:Bienvenida; a las oficinas de la Compañía Comercial Aspafresno. ¿Tiene una cita pactada?', 28153),
(159699, 'esMX', 'Ah, ahí estabas, $p. ¡Sube!', '', 28153),
(159698, 'esMX', 'Sí. Acabemos con esto de una vez.', '', 28153),
(159697, 'esMX', '', 'Esta tierra tiene una larga historia. Debo mostrarte cómo lucía todo esto cuando el Imperio de Arathor estaba en su apogeo.\n\nHmm... Pero supongo que tendremos que esperar.\n\n¿Ya has resuelto tus asuntos del pasado, $ucampeón:campeona;?', 28153),
(159696, 'esMX', 'Así es. No fingiré que es la mejor solución, en absoluto, pero es lo que el destino decidió.', '', 28153),
(159695, 'esMX', '¿Es siniestro, no, Halford? Matar a todos y cada uno de los zandalari de la nave.', '', 28153),
(159694, 'esMX', 'Cuando estés $Ulisto:lista; para iniciar el ritual, coloca la llave del mar en el cuenco.', '', 28153),
(159693, 'esMX', 'He estado esperando tu regreso con ansias, $n.', '', 28153),
(159692, 'esMX', 'Empezaba a preocuparme que no regresaras.', '', 28153),
(159691, 'esMX', 'Me alegra verte, $n. Debo admitir que pensé que no regresarías.', '', 28153),
(159689, 'esMX', 'Empezaré por el principio. \n\nMis primero\' recuerdo son los más felice\' que tengo. Me la pasaba corriendo con los bribone\' de Zuldazar. \n\nLo único que hacíamo\' en esa época era meternos en problema\', pero era la única realidad que conocíamo\'. \n\nRajin era nuestro líder. Nos daba refugio y, a cambio, hacíamo\' lo que nos pedía. \n\nQue normalmente era estafar a algunas persona\' en la ciudad o robar de las arcas de los templo\' de los loa.', '', 28153),
(159688, 'esMX', '', '¡Deprisa! ¡Estamos en territorio enemigo, esto no es Ventormenta! ¡Descargemos esto cuanto antes y evacuemos a los heridos!', 28153),
(159687, 'esMX', '¿Acaso no es esa la pregunta que todos nos hacemo\'?\n\n<Zenbaro tose.>\n\nLas arena\' no me han tratado bien, $n. Mi fin se acerca. \n\nMi garganta se hincha con el calor del desierto. \n\nTráeme un poco de agua fría de la fuente cercana y te contaré mi historia.', '', 28153),
(159686, 'esMX', '¿Estás hablando del goblin y ese artilugio loco del Bancal de los Artesano\'? Ese maniático dice que su Chatarramático 1000 puede despedazar cualquier equipo para crear otras cosa\'.\n\nSi quieres hablar con él, ve a la zona baja oeste de Dazar\'alor.', '¿Estás hablando del goblin y ese artilugio loco del Bancal de los Artesano\'? Ese maniático dice que su Chatarramático 1000 puede despedazar cualquier equipo para crear otras cosa\'.\n\nSi quieres hablar con él, ve a la zona baja oeste de Dazar\'alor.', 28153),
(159685, 'esMX', 'Jamás imaginé que eh\'te sería mi destino. Una muerte en soledad, en medio de las duna\'.', '', 28153),
(159684, 'esMX', 'Desguazador', 'Desguazador', 28153),
(159683, 'esMX', 'Este es el lugar. Bajemos al sótano.', '', 28153),
(159682, 'esMX', '¿Qué tienes que hacer en el Trono Dorado? ¿Acaso quieres una audiencia?\n\nPara llegar hasta allí, toma los elevadore\' en el Gran Sello.', '¿Qué tienes que hacer en el Trono Dorado? ¿Acaso quieres una audiencia?\n\nPara llegar hasta allí, toma los elevadore\' en el Gran Sello.', 28153),
(159681, 'esMX', 'El sótano en cuestión debería estar cerca. No hay tiempo que perder.', '', 28153),
(159680, 'esMX', 'El Trono Dorado', 'El Trono Dorado', 28153),
(159679, 'esMX', '¿Estás $ulisto:lista; para partir?', '', 28153),
(159678, 'esMX', 'Acabemos con esto rápido. Entramos y salimos antes de que nos descubran.', '', 28153),
(159677, 'esMX', '¡Andando!', '', 28153),
(159676, 'esMX', '', 'Inmediatamente.', 28153),
(159675, 'esMX', 'Shandris, necesito que patrulles las playas y te asegures de que ningún sobreviviente escape. Falstad te acompañará después de llevarnos.', '', 28153),
(159674, 'esMX', '', 'No saben qué les espera.', 28153),
(159673, 'esMX', 'Entendido.', '', 28153),
(159672, 'esMX', 'Keeshan, Kelsey, atraviesen el portal de Umbric y establezcan una zona de aterrizaje sobre el barco.', '', 28153),
(159671, 'esMX', 'Como ordenes.', '', 28153),
(159670, 'esMX', 'Umbric, convoca un portal del Vacío para traer a los enanos Hierro Negro al Llamado de Gral.', '', 28153),
(159669, 'esMX', 'Debemos asegurarnos de que nadie que esté a bordo de esa nave regrese a Zuldazar. Si no, será el fin de nuestra misión. Y de nuestras vidas.', '', 28153),
(159668, 'esMX', 'Estoy listo para salir.', 'Estoy lista para salir.', 28153),
(159667, 'esMX', '', '¡Todos los miembros de la academia se burlarán de mí por esto! Oh, Yuke, ¡qué torpe eres!', 28153),
(159666, 'esMX', '', '¡Gracias! Soy miembro de los Shadopan, en serio. Hoy es mi día libre, ¿entiendes? Toma un poco de azerita, pero no le cuentes a nadie, ¿sí?', 28153),
(159665, 'esMX', 'Por las olas, no me imaginé que pasaría esto. ¿Acaso moriré aquí?', '', 28153),
(159664, 'esMX', 'Muchísimas gracias. Debería tener más cuidado de ahora en más. Toma este regalo por tu amabilidad.', '', 28153),
(159663, 'esMX', 'Qué chistoso... ¡me hago llamar cartógrafo y me perdí!', '', 28153),
(159662, 'esMX', '¡Ja, ja! ¡Qué sería de la cartografía sin un poco de aventura, eh! ¡Sin un poco de peligro! Sí, en tu mirada perdida veo que estás de acuerdo conmigo. Ten, toma esto. Ahora, ¡debo seguir dibujando mapas!', '', 28153),
(159661, 'esMX', 'Es bastante vergonzoso ser un dragón y tener que decir esto, pero... ¿podrías darme una mano?', '', 28153),
(159660, 'esMX', 'Gracias, $uamigo:amiga;. En estas islas hay una gran cantidad de objetos mágicos que merecen mi atención y mi tiempo. Aunque no estaría mal que hubiera menos trampas...', '', 28153),
(159659, 'esMX', 'Ayuda a Dosalbo; ¡tendrás muchísima suerte si lo haces!', '', 28153),
(159658, 'esMX', '¡Dosalbo está libre! ¡Hoy tendrás más suerte que nunca, $uamigo:amiga;! ¡Es tu destino, en serio!', '', 28153),
(159657, 'esMX', '', '¡Oh, Pía! ¡Otra vez estás en problemas! Tengo que encontrar una salida...', 28153),
(159656, 'esMX', '', '¡Eres $uel mejor:la mejor;! Pero no dejaré de explorar, no. ¡Jamás! Si no exploro, ¡no merezco que me llamen Pía Trabaluz!', 28153),
(159655, 'esMX', 'Mecanismo de agradecimiento activado. Dispensando agradecimiento. Agradecimiento dispensado.', '', 28153),
(159654, 'esMX', 'Los circuitos registran una obstrucción. Ingresando al modo de ayuda. AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA AYUDA. Repitiendo.', '', 28153),
(159653, 'esMX', '', 'Eh, colega, ¿qué hace\' aquí? ¿Podrías ayudarme a resolver esto?', 28153),
(159652, 'esMX', '', 'Ahora eh\'tá mejor. Se ve que ere\' buena persona. Ten, toma esto por lo que has hecho.', 28153),
(159651, 'esMX', '¡Eh, tú! ¿No me darías una mano? Juro que YA NO SOY de la Legión. Esos tipos no existen. Ahora estoy yo solo, Sylvester, el Diablillo Honesto.', '', 28153),
(159650, 'esMX', 'Vaya, gracias, en serio. No tengo palabras para agradecerte. Bueno, me voy. No me sigas.', '', 28153),
(159649, 'esMX', '', '¡Hola! ¿Hola? Eh, hola, sí. ¿Puedes ayudarme? No sé qué hacer aquí. Estoy perdidísima.', 28153),
(159648, 'esMX', '', '¡Gracias! Gracias, en serio. Muchas gracias. ¿Sabes dónde estamos? No recuerdo lo que estaba haciendo... ¿Dónde está mi bote? ¿Tenía un bote?', 28153),
(159647, 'esMX', '¡Necesito ayuda! ¿Alguien me oye?', '', 28153),
(159646, 'esMX', 'Ah, gracias, $uamigo pescador:amiga pescadora;. ¿Cómo has llegado hasta aquí? No importa, me imagino que tendrás que marcharte.', '', 28153),
(159645, 'esMX', 'La gran ciudad de Dazar\'alor es la más poderosa del mundo. Sus numerosos distrito\' están lleno\' de maravillas y atracciones. Sus habitantes son los más sabio\' y tenace\' que hayan existido.\n\n¡Pero ten cuidado con el vudú!', 'La gran ciudad de Dazar\'alor es la más poderosa del mundo. Sus numerosos distrito\' están lleno\' de maravillas y atracciones. Sus habitantes son los más sabio\' y tenace\' que hayan existido.\n\n¡Pero ten cuidado con el vudú!', 28153),
(159644, 'esMX', 'Ay ay ay, parece que estoy un poco hasta el cuello. Mmm... Piensa, piensa...', '', 28153),
(159643, 'esMX', 'Oh, gracias, $uamigo:amiga;. No te imaginas la cantidad de veces que me pasó esto. ¡Algún día aprenderé! Ja, ja, pero parece que hoy no es el día. Toma, te comparto lo poco que tengo.', '', 28153),
(159642, 'esMX', '¡Gregg necesita ayuda! ¡Que alguien ayude a Gregg!', '', 28153),
(159641, 'esMX', '¡Ayudaste a Gregg! Gregg está feliz. ¡Gregg te da piedras! Gregg ama las piedras.', '', 28153),
(159640, 'esMX', 'Eh, tú. ¿Qué tal si le das una mano al viejo Frankie? Quizá pueda darte algo que quieres... ¡y que él sabe que quieres! ¿Qué dices?', '', 28153),
(159639, 'esMX', 'Uf, eso está mejor. Nunca creí que me salvaría alguien como tú, pero la vida siempre nos da sorpresas. Toma un poco de azerita por las molestias, y no le digas a nadie que viste al viejo Frankie aquí.', '', 28153),
(159638, 'esMX', '¡Ayyyy! ¡Sí! ¡Chispita te da las gracias! ¡Sí, toma, toma las gemas!', '', 28153),
(159637, 'esMX', '¡Eh! ¡Ayuda! ¡Eh, tú! ¡Ayúdame!', '', 28153),
(159636, 'esMX', '¡Eh, brul, necesito una mano!', '', 28153),
(159635, 'esMX', 'Se me fue un poco la mano y casi me meto en un lío tremendo. Muchas gracias, brul.', '', 28153),
(159634, 'esMX', 'Emisario del Imperio zandalari', 'Emisario del Imperio zandalari', 28153),
(159633, 'esMX', '', '¡Vaya, muchas gracias! Eres increíble. Trataré de no volver a hacerlo.', 28153),
(159632, 'esMX', '', 'Mira en lo que te has metido ESTA vez, Karyn. Un momento, ¿cómo saldré de esto?', 28153),
(159631, 'esMX', 'Encontrarás al Coleccionista Tojo en el Puesto Vendescama\', al noreste de la ciudad.\n\nTen cuidado con ese mojo tortollano, es bastante extraño...', 'Encontrarás al Coleccionista Tojo en el Puesto Vendescama\', al noreste de la ciudad.\n\nTen cuidado con ese mojo tortollano, es bastante extraño...', 28153),
(159630, 'esMX', 'Emisario de los Buscadores tortollanos', 'Emisario de los Buscadores tortollanos', 28153),
(159629, 'esMX', 'Conozco varios. ¿De cuál quiere\' información?', 'Conozco varios. ¿De cuál quiere\' información?', 28153),
(159628, 'esMX', 'Puntos de interés', 'Puntos de interés', 28153),
(159627, 'esMX', 'Te doy la bienvenida a mi humilde morada, $c. Espero que puedas descansar... en paz.', '', 28153),
(159626, 'esMX', 'Ya no. Puedo explicarlo...', '', 28153),
(159625, 'esMX', '', 'No hay tiempo de llorar lo que se ha perdido. Los Mag\'har formarán un nuevo hogar. Aquí.', 28153),
(159624, 'esMX', 'El portal que lleva a Azeroth permanecerá abierto el tiempo necesario para que tus soldados se preparen para el viaje y lo atraviesen.', '', 28153),
(159623, 'esMX', 'Aka\'magosh, Geya\'rah. Le informaré a tu madre sobre tu decisión. Que tengas buen viaje, Eitrigg. También tú, $n.', '', 28153),
(159622, 'esMX', '', '¡Hola, $n! El puesto de avanzada está a tus órdene\'.', 28153),
(159621, 'esMX', 'Volver a sentir las piedras de Draenor bajo los pies en una batalla... Hoy ha sido un gran día.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159620, 'esMX', '', 'Ya pudieron abrir un camino a Draenor antes. En mi corazón, sé que encontraremos una forma de volver.', 28153),
(159619, 'esMX', 'La magia que te permitirá llegar a Azeroth es volátil. Quizá nunca consigas volver a tu hogar.', '', 28153),
(159618, 'esMX', 'Tienes todo nuestro agradecimiento. $n, prepárate para regresar a...', '', 28153),
(159617, 'esMX', 'Geya\'rah. Me imaginaba que, después de luchar junto a ellos en la batalla, sentirías deseos de unirte a estos héroes. Te doy mi bendición.', '', 28153),
(159616, 'esMX', '', 'El jefe de guerra puede hacer frente a los draenei y a esos traidores de los Lazoluz. Los Mag\'har te ayudaremos a ganar tu guerra, y nuestra deuda será saldada.', 28153),
(159615, 'esMX', '¿A ti, señora suprema? ¿Y qué hay de la lucha que tu pueblo está librando aquí?', '', 28153),
(159614, 'esMX', '', 'Me enviarán a mí. Junto a una compañía de voluntarios. Con tu permiso, jefe de guerra.', 28153),
(159613, 'esMX', 'Ahora, en cuanto al tema de la deuda con tu Horda, enviaremos...', '', 28153),
(159612, 'esMX', '', 'Lucharon con valentía. Debo admitirlo... Te juzgué injustamente, Eitrigg. También a ti, $n.', 28153),
(159611, 'esMX', 'Estaremos preparados. ¿Y qué me cuentas de los héroes de Azeroth? ¿Te ayudaron?', '', 28153),
(159610, 'esMX', '', 'Frustramos el ataque de los draenei, jefe de guerra. Pero la Alta exarca no se rendirá. Los fanáticos nunca se rinden.', 28153),
(159609, 'esMX', 'Si los piratas zarparon de Puerto Libre, puede que haya más información allí. Y creo que conozco a alguien que podría ayudarnos.', '', 28153),
(159608, 'esMX', '', 'Pero... Quizá tengas razón, Genn. Pero aún si es así, tenemos muy pocas pistas para continuar.', 28153),
(159607, 'esMX', 'Quizá todavía no hayan llegado a destino, Katherine. Puede que todavía tengamos una oportunidad.', '', 28153),
(159606, 'esMX', 'En el contrato se hablaba de mover a Jaina a un lugar, no de matarla.', '', 28153),
(159605, 'esMX', '', '¿Cómo puedes creer eso?', 28153),
(159604, 'esMX', '', 'Nos volveremos a ver en el campamento, $n.', 28153),
(159603, 'esMX', '', '¡Contrató piratas para ejecutar a mi hija, Genn! ¡Piratas! ¡La basura del mar!', 28153),
(159602, 'esMX', '', 'Se acaba el tiempo, ¿y lo único que tenemos es un contrato entre Priscilla y unos salteadores de Puerto Libre?', 28153),
(159601, 'esMX', 'Piénsalo de esta manera, Katherine. Podría ser una buena noticia.', '', 28153),
(159600, 'esMX', '', 'Momento... eres... ¿en serio... ?', 28153),
(159599, 'esMX', '', '¡Solo la Alianza puede ver estos planes de batalla! ¡Hora de morir, trol de sangre!', 28153),
(159598, 'esMX', 'No puede ser... $Uun:una; trol de sangre...', '', 28153),
(159597, 'esMX', '¡Trols de sangre! Ja, eres demasiado $Uestúpido:estúpida; para comprender los secretos de la Alianza.', '', 28153),
(159596, 'esMX', '', '¡Tú... no eres... $Uun:una; trol de sangre!', 28153),
(159595, 'esMX', '', '¿$UUn:Una; trol de sangre? Acabaré contigo antes de llevar estos planes a los zandalari.', 28153),
(159594, 'esMX', '¡Ahora huelo horrible!', '¡Ya no quiero jugar a este juego!', 28153),
(159593, 'esMX', '¡Se lo compramos a un tipo verde en la costa!', '¡Se lo compramos a un tipo verde en la costa!', 28153),
(159592, 'esMX', '¡La milicia siempre está aquí para protegernos! Bueno, a excepción de ahora mismo. Se han ido a una reunión importante con los maresabios. A veces me dan un poco de miedo, pero el hermano Pike siempre es muy amable cuando viene de visita.', '¡La milicia siempre está aquí para protegernos! Bueno, a excepción de ahora mismo. Se han ido a una reunión importante con los maresabios. A veces me dan un poco de miedo, pero el hermano Pike siempre es muy amable cuando viene de visita.', 28153),
(159591, 'esMX', '¡Esto fue todo idea de Grettle!', '¿Quieres comprar uno como mascota?', 28153),
(159590, 'esMX', '¿Por qué será que se llama Canto Tormenta? Jamás los he oído cantar.$b$bLos adultos son extraños, ¿verdad?', '¿Por qué será que se llama Canto Tormenta? Jamás los he oído cantar.$b$bLos adultos son extraños, ¿verdad?', 28153),
(159589, 'esMX', '¿Has probado las almejas al vapor? ¡Son la especialidad de Canto Tormenta!', '¿Has probado las almejas al vapor? ¡Son la especialidad de Canto Tormenta!', 28153),
(159588, 'esMX', '¡Me encanta cuando vamos de visita a la Hidromielería de Mildenhall! Mis padres dicen que soy demasiado pequeño para beber hidromiel, pero siempre me dan un bocadillo de miel.', '¡Me encanta cuando vamos de visita a la Hidromielería de Mildenhall! Mis padres dicen que soy demasiado pequeña para beber hidromiel, pero siempre me dan un bocadillo de miel.', 28153),
(159587, 'esMX', 'Me pregunto si algún día seré tan grande como mamá o papá. Ellos siempre terminan sus vegetales, quizás debería hacer lo mismo...', 'Me pregunto si algún día seré tan grande como mamá o papá. Ellos siempre terminan sus vegetales, quizás debería hacer lo mismo...', 28153),
(159586, 'esMX', 'Mi papá y mi mamá trabajan muy duro para asegurarse que todos tengan para comer. ¡La comida es deliciosa!', 'Mi papá y mi mamá trabajan muy duro para asegurarse que todos tengan para comer. ¡La comida es deliciosa!', 28153),
(159585, 'esMX', '¡Hola, $Useñor:señorita;! ¿Es su primera vez en el valle?', '¡Hola, $Useñor:señorita;! ¿Es su primera vez en el valle?', 28153),
(159584, 'esMX', 'Espero que nadie haya visto eso.', '¡Finjamos que eso nunca sucedió!', 28153),
(159583, 'esMX', 'Hemos confiado en los consejos de los maresabios por generaciones. El mar les otorga un enorme conocimiento, no tengo dudas.', 'Hemos confiado en los consejos de los maresabios por generaciones. El mar les otorga un enorme conocimiento, no tengo dudas.', 28153),
(159582, 'esMX', 'He tenido días mejores.', 'No se lo contemos a nadie.', 28153),
(159581, 'esMX', '¿Has probado algunas de las delicias del valle? Prueba nuestro pan fresco con una salchicha de Drustvar. Disfrútalo acompañado de una deliciosa jarra de hidromiel... Se me hace agua la boca de solo imaginarlo.', '¿Has probado algunas de las delicias del valle? Prueba nuestro pan fresco con una salchicha de Drustvar. Disfrútalo acompañado de una deliciosa jarra de hidromiel... Se me hace agua la boca de solo imaginarlo.', 28153),
(159580, 'esMX', 'Siempre teníamos la protección de la milicia. Me pregunto qué los habrá hecho retirarse.', 'Siempre teníamos la protección de la milicia. Me pregunto qué los habrá hecho retirarse.', 28153),
(159579, 'esMX', 'Trabajamos en el campo para llevar alimento a los habitantes de Kul Tiras. ¡Es un trabajo duro, pero muy gratificante!', 'Trabajamos en el campo para llevar alimento a los habitantes de Kul Tiras. ¡Es un trabajo duro, pero muy gratificante!', 28153),
(159578, 'esMX', 'A pesar de que vivimos de la tierra, somos hijos del mar.', 'A pesar de que vivimos de la tierra, somos hijos del mar.', 28153),
(159577, 'esMX', 'Que los mares te guíen, $Uforastero:forastera;.', 'Que los mares te guíen, $Uforastero:forastera;.', 28153),
(159576, 'esMX', 'Te doy la bienvenida al valle.', 'Te doy la bienvenida al valle.', 28153),
(159575, 'esMX', '[DNT NOT USED] Ah, $n, ahí estabas. Algunos Valiente han atravesado las defensas. Elimínalos.', '', 28153),
(159574, 'esMX', '', 'Estoy ansiosa. Déjame ayudar desde las sombras.', 28153),
(159573, 'esMX', '', 'Mamá, ¿dónde está papá?', 28153),
(159572, 'esMX', 'Saludos, $r. ¿Deseas reforjar algo?\n\nEl poder de la azerita es ilimitado. Por suerte, mis precios no.', '', 28153),
(159571, 'esMX', '', 'Vengan conmigo, campeones de Azeroth. Debemos informar al jefe de guerra sobre nuestra victoria...', 28153),
(159570, 'esMX', '', 'Su Alta exarca no puede salvarlos. ¡Mi pueblo no dejará de luchar hasta que Draenor sea libre!', 28153),
(159569, 'esMX', 'Yrel... te he fallado...', '', 28153),
(159568, 'esMX', 'Esta tierra, antes fértil, ahora es un erial sin vida. ¡Eso es obra de su ira!', '', 28153),
(159567, 'esMX', '', '¡Nosotros nos ocuparemos de nuestras propias cicatrices!', 28153),
(159566, 'esMX', '¡Deja de lado tu odio! ¡La Luz puede sanar las cicatrices de la guerra!', '', 28153),
(159565, 'esMX', '', '¡Sometimiento, querrás decir!', 28153),
(159564, 'esMX', '¡Los naaru nos ofrecen paz y orden!', '', 28153),
(159563, 'esMX', '¡Por Draenor! ¡Por los Mag\'har!', '', 28153),
(159562, 'esMX', '', '¡Estoy harta de tanto palabrerío! ¡La sentencia se definirá en el campo de batalla!', 28153),
(159561, 'esMX', 'La Alta exarca les ordena que se rindan... ¡o enfrentarán su sentencia!', '', 28153),
(159560, 'esMX', '', '¡Váyanse de aquí mientras puedan! ¡No nos impondrán sus doctrinas, draenei!', 28153),
(159559, 'esMX', '¡Depongan sus armas, Mag\'har! ¡Su esfuerzo es inútil! ¡Abran las puertas a la Luz!', '', 28153),
(159558, 'esMX', '¡Estamos contigo, Geya\'rah!', '', 28153),
(159557, 'esMX', '', '¡Están atacando el Fuerte Siempredía! ¡Conmigo, héroes!', 28153),
(159556, 'esMX', '¡La Alta exarca solo quiere nuestro bien!', '¡La Alta exarca solo quiere nuestro bien!', 28153),
(159555, 'esMX', 'La Luz nos salvó. ¡También puede salvarlos a ustedes!', 'La Luz nos salvó. ¡También puede salvarlos a ustedes!', 28153),
(159554, 'esMX', 'La era de Grommash es parte del pasado. ¡Abran las puertas a un nuevo futuro!', 'La era de Grommash es parte del pasado. ¡Abran las puertas a un nuevo futuro!', 28153),
(159553, 'esMX', '¡Únanse a nosotros en la Luz, hermanos y hermanas!', '¡Únanse a nosotros en la Luz, hermanos y hermanas!', 28153),
(159552, 'esMX', '¡Juntos podemos salvar a Draenor!', '¡Juntos podemos salvar a Draenor!', 28153),
(159551, 'esMX', 'Han arruinado estas tierras, ¡pero hay tiempo de salvarlas!', 'Han arruinado estas tierras, ¡pero hay tiempo de salvarlas!', 28153),
(159550, 'esMX', '¡Acaten las visiones de la Alta exarca!', '¡Acaten las visiones de la Alta exarca!', 28153),
(159549, 'esMX', '¡Hemos venido para librarlos de su salvajismo!', '¡Hemos venido para librarlos de su salvajismo!', 28153),
(159548, 'esMX', '¡Ríndanse, Mag\'har! ¡Reciban la Luz!', '¡Ríndanse, Mag\'har! ¡Reciban la Luz!', 28153),
(159547, 'esMX', 'Te doy la bienvenida.', '', 28153),
(159546, 'esMX', '', '¡Acaben con la corrupción de la Luz!', 28153),
(159545, 'esMX', '', '¡Atrás, draenei! ¡Su Luz no es bienvenida en este lugar!', 28153),
(159544, 'esMX', '', '¡Mantengan la posición! ¡Esta tierra les pertenece a los Mag\'har!', 28153),
(159543, 'esMX', 'Akunda recibe a todos con beneplácito.', '', 28153),
(159542, 'esMX', '', '¡Fuera las máquinas de asedio!', 28153),
(159541, 'esMX', '', '¡Entonces lucharemos juntos por la sangre y el honor! ¡Conmigo, héroes!', 28153),
(159540, 'esMX', 'Jamás abandoné un campo de batalla. Y hoy no será la primera vez.', '', 28153),
(159539, 'esMX', '', 'Esta no es su guerra, visitantes. Pueden regresar a Azeroth.', 28153),
(159538, 'esMX', 'Mantenemos nuestra posición, señora suprema. Pero parece que el enemigo se prepara para lanzar un ataque a gran escala.', '', 28153),
(159537, 'esMX', '', '¡Lantresor! ¡El informe!', 28153),
(159536, 'esMX', 'También puedes atacar a tus enemigos con un Disparo lacerante para que reciban daño por sangrado durante un tiempo.', '', 28153),
(159535, 'esMX', '¡Lucharemos contigo, señora suprema!', '', 28153),
(159534, 'esMX', '', '¡No me quedaré de brazos cruzados mientras la Alta exarca atenta contra la libertad de los Mag\'har! ¡La tiranía de la Luz debe terminar!', 28153),
(159533, 'esMX', '', 'Incluso hubo algunos orcos que se aliaron con los draenei en contra de sus hermanos... ¡Y hasta perdimos al hijo del jefe de guerra! Estos traidores son los Lazoluz.', 28153),
(159532, 'esMX', '', 'Sus maestros naaru los presionaron para que expandieran la influencia de la Luz entre los orcos. Algunos se convirtieron por voluntad propia. Otros fueron obligados.', 28153),
(159531, 'esMX', '', 'Sin embargo, cuando ya no quedaron demonios para enfrentar, los draenei concentraron todas sus energías en su preciosa Luz.', 28153),
(159530, 'esMX', '', 'Tras la caída de Archimonde, los orcos y los draenei se unieron para expulsar a la Legión de Draenor. Fueron buenos años...', 28153),
(159529, 'esMX', '', 'Supongo que se han ganado ese derecho.', 28153),
(159528, 'esMX', 'Es hora de que nos expliques quiénes son estos Lazoluz, señora suprema.', '', 28153),
(159527, 'esMX', '', '¡Bien! Siempre quise lucir la cabeza de otro exarca en mi hogar. ¡Vengan, forasteros!', 28153),
(159526, 'esMX', 'Los comanda una exarca. Sus ejércitos son... numerosos.', 'Los comanda una exarca. Sus ejércitos son... numerosos.', 28153),
(159525, 'esMX', '', '¡Malditos traidores! ¿Qué tan grandes son sus ejércitos?', 28153),
(159524, 'esMX', '¡Señora suprema Geya\'rah! ¡Los Lazoluz están atacando el Observatorio de Bestias!', '¡Señora suprema Geya\'rah! ¡Los Lazoluz están atacando el Observatorio de Bestias!', 28153),
(159523, 'esMX', 'Listo. Ahora eres... $Uun:una; trol de sangre. Al menos por un rato.', '', 28153),
(159522, 'esMX', 'Pero no podemos arriesgarnos a que vean a un miembro de la Alianza en el Puerto de Guerra Rastari.', '', 28153),
(159521, 'esMX', 'Me disculpo por el dolor y la falta de decoro de este ritual, $n.', '', 28153),
(159520, 'esMX', 'Umbric, estoy listo para convertirme en trol de sangre.', 'Umbric, estoy lista para convertirme en trol de sangre.', 28153),
(159519, 'esMX', 'Dicen que Pin\'jin es uno de los trols más paciente\' que hayan existido jamás. De otro modo no podría soportar a todos esos noble\' que le taladran los tímpanos y no dejan de hablar de sus hermosos vestido\'.\n\nSi tienes la paciencia que se necesita para aprender de él, ve al Bancal de los Artesano\', en la zona oeste de Dazar\'alor.', 'Dicen que Pin\'jin es uno de los trols más paciente\' que hayan existido jamás. De otro modo no podría soportar a todos esos noble\' que le taladran los tímpanos y no dejan de hablar de sus hermosos vestido\'.\n\nSi tienes la paciencia que se necesita para aprender de él, ve al Bancal de los Artesano\', en la zona oeste de Dazar\'alor.', 28153),
(159517, 'esMX', '¿Piensas que es fácil despellejar a un anklydón? ¡Pues no! Si quieres aprender la técnica, tienes que entrenar con Rana.\n\nLo último que supe fue que volvió a la ciudad. La encontrarás en el Bancal de los Artesano\', en la zona oeste de Dazar\'alor.\n\nProcura ser amable... ¡o te despellejará a ti también!', '¿Piensas que es fácil despellejar a un anklydón? ¡Pues no! Si quieres aprender la técnica, tienes que entrenar con Rana.\n\nLo último que supe fue que volvió a la ciudad. La encontrarás en el Bancal de los Artesano\', en la zona oeste de Dazar\'alor.\n\nProcura ser amable... ¡o te despellejará a ti también!', 28153),
(159515, 'esMX', '¿Qué quieres con ese ladrón de Secott? Aún no lo hemo\' atrapado, ¡pero sabemos que ha estado robando oro de Atal\'Dazar! Los loa harán que pague. Y si no, ¡yo mih\'mo me encargaré!\n\nPodrás encontrar a tu \"amigo\" en el Bancal de los Artesano\'. Los estaremo\' vigilando.', '¿Qué quieres con ese ladrón de Secott? Aún no lo hemo\' atrapado, ¡pero sabemos que ha estado robando oro de Atal\'Dazar! Los loa harán que pague. Y si no, ¡yo mih\'ma me encargaré!\n\nPodrás encontrar a tu \"amigo\" en el Bancal de los Artesano\'. Los estaremo\' vigilando.', 28153),
(159513, 'esMX', 'Xanjo usa las pieles que le da Rana para crear alguna\' de las armadura\' más hermosas que haya\' visto en tu vida.\n\nLo encontrarás en el Bancal de los Artesano\', en la zona oeste de Dazar\'alor.', 'Xanjo usa las pieles que le da Rana para crear alguna\' de las armadura\' más hermosas que haya\' visto en tu vida.\n\nLo encontrarás en el Bancal de los Artesano\', en la zona oeste de Dazar\'alor.', 28153),
(159511, 'esMX', 'Nuestra querida Seshuli crea las mejores joya\' de los Mares del Sur. Si quieres aprender su arte, la encontrarás en el Salón de los Destello\'.\n\nPara llegar a ese lugar, ve al Bancal de los Artesano\', en la zona oeste de Dazar\'alor. Luego, dobla hacia el este y toma el túnel que te lleva hacia la pirámide. Es imposible que no la veas con todos los objeto\' brillante\' que hay a su alrededor.', 'Nuestra querida Seshuli crea las mejores joya\' de los Mares del Sur. Si quieres aprender su arte, la encontrarás en el Salón de los Destello\'.\n\nPara llegar a ese lugar, ve al Bancal de los Artesano\', en la zona oeste de Dazar\'alor. Luego, dobla hacia el este y toma el túnel que te lleva hacia la pirámide. Es imposible que no la veas con todos los objeto\' brillante\' que hay a su alrededor.', 28153),
(159509, 'esMX', '', 'Ve a Darnassus con mi hipogrifo. Procura que la ocupación de la Horda sea... lo más tolerable posible.', 28153),
(159506, 'esMX', 'Los cronista\' viajan a todo\' los confine\' para conocer las verdade\' del mundo. Creo que deberías hablar con Kizani.\n\nLa encontrarás arriba, en el Gran Sello, en el Salón de los Cronista\'.', 'Los cronista\' viajan a todo\' los confine\' para conocer las verdade\' del mundo. Creo que deberías hablar con Kizani.\n\nLa encontrarás arriba, en el Gran Sello, en el Salón de los Cronista\'.', 28153),
(159504, 'esMX', 'Jahden Fla siempre eh\'tá cuidando sus flore\' en el Bancal de los Artesanos. Encontrarás ese lugar en la zona oeste de Dazar\'alor.\n\nJahden no bromea cuando dice que tiene mano verde...', 'Jahden Fla siempre eh\'tá cuidando sus flore\' en el Bancal de los Artesanos. Encontrarás ese lugar en la zona oeste de Dazar\'alor.\n\nJahden no bromea cuando dice que tiene mano verde...', 28153),
(159503, 'esMX', 'La guerra nos pone a prueba. Nos obliga a replantearnos nuestro honor, nuestras convicciones.\n\nHe venido para cerciorarme de que la Horda no pierda de vista en el fragor de la lucha todo lo que nos define. Lo que nos hace fuertes.\n\nTengo fe de que no te olvidarás de esto, portavoz de la Horda.', '', 28153),
(159502, 'esMX', '¡Necesito volverme más fuerte!', '', 28153),
(159500, 'esMX', 'Espero que estés bien, $p.', '', 28153),
(159499, 'esMX', 'Gracias a ti, empezaré a entrenarme para convertirme en un guerrero valiente. ¡Quiero poder defender a nuestro pueblo!', '', 28153),
(159498, 'esMX', 'La abuela no deja de mencionar que querría que me pareciera más a ti...', '', 28153),
(159497, 'esMX', 'A mí... me alegra que llegaras cuando llegaste.', '', 28153),
(159496, 'esMX', '¿Quieres aprender a pescar? Entonce\' tienes que ir a ver a Tali la silente. Está pescando en la Esquirla, al norte de Dazar\'alor.\n\nProcura no hacer ruido o espantarás a los pece\'.', '¿Quieres aprender a pescar? Entonce\' tienes que ir a ver a Tali la silente. Está pescando en la Esquirla, al norte de Dazar\'alor.\n\nProcura no hacer ruido o espantarás a los pece\'.', 28153),
(159495, 'esMX', 'No quiero fallarle a mi abuela, pero no estoy hecho para esto... Solo quiero que todo vuelva a la normalidad.', '', 28153),
(159494, 'esMX', 'Cuidado con la cabeza, ¡caen rocas del cielo!', '', 28153),
(159492, 'esMX', 'Hay una goblin llamada Shuga que enseña ese tipo de cosas en el Bancal de los Artesano\'. Eso es en las afuera\', del lado oeste de Dazar\'alor.\n\nEh\'pero que no planees explotar nada importante. Nos guh\'ta Zuldazar así como está.', 'Hay una goblin llamada Shuga que enseña ese tipo de cosas en el Bancal de los Artesano\'. Eso es en las afuera\', del lado oeste de Dazar\'alor.\n\nEh\'pero que no planees explotar nada importante. Nos guh\'ta Zuldazar así como está.', 28153),
(159491, 'esMX', '¡¡Mataron a mi vaca!!', '¡¡Mataron a mi vaca!!', 28153),
(159489, 'esMX', '¡Esta no es mi primera batalla!', '¡Esta no es mi primera batalla!', 28153),
(159488, 'esMX', '¡Ayudaré como pueda!', '¡Ayudaré como pueda!', 28153),
(159487, 'esMX', '¡Déjamelos a mí!', '¡Déjamelos a mí!', 28153),
(159486, 'esMX', '¡Les daré su merecido!', '¡Les daré su merecido!', 28153),
(159485, 'esMX', '¡Sí! ¡Pagarán por esto!', '¡Sí! ¡Pagarán por esto!', 28153),
(159484, 'esMX', 'Te recomiendo hablar con una encantadora elfa de sangre llamada Quinni. La podrás encontrar en la base oeste de Dazar\'alor, en el Bancal de los Artesano\'. Cuando eh\'tés allí, gira hacia la pirámide y baja hasta dar con el Salón de los Destello\'.', 'Te recomiendo hablar con una encantadora elfa de sangre llamada Quinni. La podrás encontrar en la base oeste de Dazar\'alor, en el Bancal de los Artesano\'. Cuando eh\'tés allí, gira hacia la pirámide y baja hasta dar con el Salón de los Destello\'.', 28153),
(159482, 'esMX', '', '¡La herencia de fracasos de los Valiente muere contigo!', 28153),
(159481, 'esMX', '', 'Tu familia siempre ha sido débil.', 28153),
(159480, 'esMX', '', '¡Y tenemos pruebas!', 28153),
(159479, 'esMX', '', 'Cargaré con este peso. Mi único deseo es ser una sucesora digna.', 28153),
(159478, 'esMX', 'Si buh\'cas a una cocinera real, ve a hablar con T\'sarah. La encontrarás en Dazar\'alor, en el Costillar Real, al lado del Gran Sello.', 'Si buh\'cas a una cocinera real, ve a hablar con T\'sarah. La encontrarás en Dazar\'alor, en el Costillar Real, al lado del Gran Sello.', 28153),
(159476, 'esMX', '', 'Mi querida amiga Priscilla y yo hemos discutido esto. Creo que lo mejor para Kul Tiras es que yo me retire del almirantazgo...', 28153),
(159475, 'esMX', '', '¡Katherine Valiente ha dedicado toda su vida al bienestar de Kul Tiras!', 28153),
(159473, 'esMX', '¡Mueran, escoria de la Horda!', '¡Mueran, escoria de la Horda!', 28153),
(159472, 'esMX', '¡Los enviaré en pedazos a su jefa de guerra!', '¡Los enviaré en pedazos a su jefa de guerra!', 28153),
(159471, 'esMX', '¡Jamás nos derrotarán!', '¡Jamás nos derrotarán!', 28153),
(159470, 'esMX', '¡Boralus no caerá!', '¡Boralus no caerá!', 28153),
(159469, 'esMX', '¡Por Boralus!', '¡Por Boralus!', 28153),
(159468, 'esMX', 'Sujétate, $p. Alapresta nos llevará allí en un abrir y cerrar de ojos.', '', 28153),
(159467, 'esMX', '', 'La emoción de la caza... No hay nada que se le parezca.', 28153),
(159466, 'esMX', '', 'Pa\'ku mira a Kua\'fon y suspira.', 28153),
(159465, 'esMX', '¡Vamos, Alapresta! De regreso a los cielos, nuestro hogar.', '', 28153),
(159464, 'esMX', 'Cerrando', 'Cerrando', 28153),
(159463, 'esMX', 'Es IMPERATIVO que demos las órdenes de ignición desde una posición con vista a todos los sitios de explosión. Lamentablemente, debo verificar todos los parámetros configurados de forma manual, y no puedo hacerlo desde otro lugar más que aquí.\n\nEn pocas palabras: tienes que subir a la máquina voladora y presionar el gran botón rojo cuando te dé la señal.', '', 28153),
(159462, 'esMX', '', 'Basta de preguntas. ¡Muévanse!', 28153),
(159461, 'esMX', '¿Los Lazoluz?', '', 28153),
(159460, 'esMX', '', 'Mi madre comanda una fortaleza en Nagrand. Mi padre cayó en batalla, luchando contra los Lazoluz.', 28153),
(159459, 'esMX', 'Eres la hija de Durotan y Draka. Te pareces a los dos. ¿Acaso tus padres han...?', '', 28153),
(159458, 'esMX', '', 'No necesito la ayuda de ningún forastero... pero haré lo que ordenas. ¡Vengan conmigo!', 28153),
(159457, 'esMX', 'Eitrigg y $n te ayudarán a darle su merecido al instigador de los ogros, Geya\'rah.', '', 28153),
(159456, 'esMX', 'Durotan le debía algo a estos héroes, Geya\'rah, al igual que yo. Tu arrebato de ira es una deshonra para el espíritu de tu padre. De todas formas... me has dado una idea...', '', 28153),
(159455, 'esMX', '', '¡¿Nos tomas por idiotas?! Jefe de guerra, no podemos confiarles nuestros soldados a estos desterrados. ¡No cuando los enemigos también asedian nuestras puertas!', 28153),
(159454, 'esMX', 'Antaño, los héroes de mi mundo liberaron a los suyos de las garras de los tiranos. Ahora, Azeroth se enfrenta a una amenaza similar. Hemos venido a pedir una retribución por los favores concedidos.', '', 28153),
(159453, 'esMX', 'Aquí estamos... dos viejos fantasmas. ¿Por qué han regresado a Draenor después de tanto tiempo?', '', 28153),
(159452, 'esMX', 'Y el Grommash Grito Infernal que yo conocí entregó su vida para liberarnos del yugo de los demonios. Una muerte digna.', '', 28153),
(159451, 'esMX', 'Eitrigg... Conocí a un Eitrigg que sirvió a Puño Negro. Era un orco honorable que murió en una batalla gloriosa.', '', 28153),
(159450, 'esMX', 'Ciertamente. Soy Eitrigg, y me acompaña $n, $ucampeón:campeona; de la Horda.', '', 28153),
(159449, 'esMX', 'Hacía muchos años que no veía a un orco de piel verde. Y quien te acompaña me parece... familiar. Vienen de Azeroth.', '', 28153),
(159448, 'esMX', '¡Suficiente! Yo mismo juzgaré a los prisioneros, Geya\'rah.', '', 28153),
(159447, 'esMX', '', 'Tus palabras me han tocado el corazón, anciano. Nosotros aún honramos la historia de nuestros clanes, aunque estamos unidos bajo el estandarte de los Mag\'har. Pero aún tienes que probar...', 28153),
(159446, 'esMX', 'Durotan fue el jefe del clan Lobo Gélido. Jamás conocí a un orco más honorable. Era un verdadero líder que amaba a su gente. Extraño su sabiduría.', '', 28153),
(159445, 'esMX', 'El clan Grito de Guerra luchó durante generaciones contra los ogros. A pesar de su clara desventaja numérica, Grommash Grito Infernal guio a su pueblo hasta la victoria en Gran Magullador.', '', 28153),
(159444, 'esMX', 'Los Roca Negra... mi propio clan. Éramos soldados orgullosos y feroces. Pero la magia vil de Gul\'dan nos engañó y nos llevó a cometer actos... terribles.', '', 28153),
(159443, 'esMX', '', 'Cualquier orco verdadero conoce los tres estandartes que hay en este campamento. Hablen sobre ellos, ¡o el verdugo hará rodar sus cabezas!', 28153),
(159442, 'esMX', '', 'Solo conozco a un jefe de guerra... ¡Y ustedes no son Roca Negra! Deberán probar lo que dicen.', 28153),
(159441, 'esMX', 'Soy Eitrigg, del clan Roca Negra. Venimos de Azeroth en nombre de nuestra jefa de guerra.', '', 28153),
(159440, 'esMX', '', 'Ya veremos. Hablen, intrusos. ¿Quiénes son?', 28153),
(159439, 'esMX', '¡Son espías lazoluz! ¡Traidores asquerosos!', '¡Son espías lazoluz! ¡Traidores asquerosos!', 28153),
(159438, 'esMX', '', 'Tráiganlos ante mí.', 28153),
(159437, 'esMX', '¡Señora suprema Geya\'rah! Tenemos prisioneros.', '', 28153),
(159436, 'esMX', 'La señora suprema sabrá lo que hay que hacer.', 'La señora suprema sabrá lo que hay que hacer.', 28153),
(159435, 'esMX', 'Con cuidado. Por lo que sabemos, son espías enviados por los draenei.', '', 28153),
(159434, 'esMX', 'Piel verde... ¡qué asco! He oído rumores sobre esta corrupción, pero jamás la había visto.', 'Piel verde... ¡qué asco! He oído rumores sobre esta corrupción, pero jamás la había visto.', 28153),
(159433, 'esMX', '¡Silencio! La señora suprema decidirá su destino. ¡Encadénenlos!', '', 28153),
(159432, 'esMX', '¡No tan rápido! Hemos venido en paz. Queremos hablar con su jefe de guerra.', '', 28153),
(159431, 'esMX', '¡Intrusos!', '¡Intrusos!', 28153),
(159430, 'esMX', '¿Por qué quieres cavar en nueh\'tras tierra\'? Si has de hacerlo, ve y habla con la examinadora Alerinda en el Gran Sello.', '¿Por qué quieres cavar en nueh\'tras tierra\'? Si has de hacerlo, ve y habla con la examinadora Alerinda en el Gran Sello.', 28153),
(159429, 'esMX', 'Arqueología', 'Arqueología', 28153),
(159428, 'esMX', '¿Qué hace eh\'te vudú del Vacío aquí?', '¿Qué hace eh\'te vudú del Vacío aquí?', 28153),
(159427, 'esMX', '¿Qué es eh\'te vudú?', '¿Qué es eh\'te vudú?', 28153),
(159426, 'esMX', '¿Qué vudú oscuro es eh\'te?', '¿Qué vudú oscuro es eh\'te?', 28153),
(159425, 'esMX', 'Vayan, pero procuren no perderse entre los hilos del destino.', '', 28153),
(159424, 'esMX', 'Enviaré el fragmento con ustedes. Cuando estén listos, podrán volver gracias a él.', '', 28153),
(159423, 'esMX', '¿Podrás mantener abierto el camino el tiempo suficiente para traer a los orcos de Draenor?', '', 28153),
(159422, 'esMX', 'Estos torrentes de tiempo y realidad cambian continuamente. Buscas un ancla al mundo que será muy endeble.', '', 28153),
(159421, 'esMX', '¿Cómo puedo llegar a Orgrimmar?', '¿Cómo puedo llegar a Orgrimmar?', 28153),
(159420, 'esMX', 'Nuestra batalla ha terminado, pero la guerra continúa...', '', 28153),
(159419, 'esMX', 'Nuestra jefa de guerra no tolerará excusas. Parece que $p tiene que ir a Tanaris. Mis viejos huesos necesitan un descanso.', '', 28153),
(159418, 'esMX', 'Si el fragmento no estuviera agotado, podría usarlo para ayudarte a llegar. Pero mi especialidad es la teletransportación, no la cronomancia.', '', 28153),
(159417, 'esMX', 'Te recomiendo que vayas al Bancal de los Artesano\', en la zona baja oeste de Dazar\'alor.\n\n¡No encontrarás a un herrero más fuerte que el maestro de forja Zak\'aal en todo Azeroth!', 'Te recomiendo que vayas al Bancal de los Artesano\', en la zona baja oeste de Dazar\'alor.\n\n¡No encontrarás a un herrero más fuerte que el maestro de forja Zak\'aal en todo Azeroth!', 28153),
(159416, 'esMX', '', 'La vida salvaje de esta zona e\' increíble. Krag\'wa está cerca. Me pregunto si la presencia de un loa hará que las criatura\' de aquí se fortalezcan. ¿Quieres poner a prueba a tus mascota\' contra las mías?', 28153),
(159415, 'esMX', '', 'Pa\'ku suelta una risa agorera.', 28153),
(159414, 'esMX', '¡Qué alivio!', '¡Qué alivio!', 28153),
(159413, 'esMX', '¡El dolor ha desaparecido!', '¡El dolor ha desaparecido!', 28153),
(159412, 'esMX', 'Eso se siente mucho mejor.', 'Eso se siente mucho mejor.', 28153),
(159411, 'esMX', 'Será un honor, general. $p, sube a Alapresta cuando estés $Ulisto:lista;.', '', 28153),
(159410, 'esMX', '', 'Falstad, ve adelante con $p. Yo subiré a Jai\'alator.', 28153),
(159409, 'esMX', 'Ahh... Ya veo. Tal vez no nació para surcar los cielo\'. Pero con $n a su lado, tendrá una buena vida.', '', 28153),
(159408, 'esMX', 'Sígannos. Si hay confianza entre nosotros, todo saldrá bien. Ahora, ¡al cielo!', '', 28153),
(159407, 'esMX', '¡No te preocupes! Tu alado amigo eh\'tará bien. Tengo un plan.', '', 28153),
(159405, 'esMX', 'Kumali la inteligente crea toda clase de mojo\' en el Bancal de los Artesanos. La encontrarás en la base, al oeste de Dazar\'alor.', 'Kumali la inteligente crea toda clase de mojo\' en el Bancal de los Artesanos. La encontrarás en la base, al oeste de Dazar\'alor.', 28153),
(159404, 'esMX', 'Como los miembros de la Horda han utilizado nuestros ilustres servicios durante tanto tiempo, hemos proporcionado portales mágicos para ciertas personas distinguidas, como tú. Te prometo que el viaje no te causará casi ninguna molestia.', 'Como los miembros de la Horda han utilizado nuestros ilustres servicios durante tanto tiempo, hemos proporcionado portales mágicos para ciertas personas distinguidas, como tú. Te prometo que el viaje no te causará casi ninguna molestia.', 28153),
(159403, 'esMX', '', '¡Jajajajajaja!', 28153),
(159402, 'esMX', '', '¡Que los vientos estén a tu favor!', 28153),
(159401, 'esMX', '¿Cómo puedo llegar a los Claros de Tirisfal?', '¿Cómo puedo llegar a los Claros de Tirisfal?', 28153),
(159399, 'esMX', 'El Invocador del Trueno está en proceso de mantenimiento. Se incendió demasiadas veces. Una lástima.', '', 28153),
(159398, 'esMX', 'Sí, Pa\'ku.', 'Sí, Pa\'ku.', 28153),
(159397, 'esMX', 'Tenemos los mejores instructore\' profesionales del mundo entero. Podrás encontrar a la mayoría en la zona baja oeste de Dazar\'alor, en el Bancal de los Artesanos.\n\n¿Buh\'cas a alguien en particular?', 'Tenemos los mejores instructore\' profesionales del mundo entero. Podrás encontrar a la mayoría en la zona baja oeste de Dazar\'alor, en el Bancal de los Artesanos.\n\n¿Buh\'cas a alguien en particular?', 28153),
(159396, 'esMX', '', 'Ahhh, presentía que pronto vendrías. Ha pasado un tiempo desde la última lección del pequeñín.\n\nVen, veamos qué ha aprendido.', 28153),
(159395, 'esMX', 'Instructores', 'Instructores', 28153),
(159394, 'esMX', 'Así que mascotas, ¿eh? Los únicos compañero\' que vale la pena tener son los hijo\' de los loa.\n\nTe recomiendo ir a ver al cuidador de bestia\' Kalatak, cerca de la base noroeste de Dazar\'alor.', 'Así que mascotas, ¿eh? Los únicos compañero\' que vale la pena tener son los hijo\' de los loa.\n\nTe recomiendo ir a ver al cuidador de bestia\' Kalatak, cerca de la base noroeste de Dazar\'alor.', 28153),
(159392, 'esMX', 'Si has cumplido los deseo\' del rey Rastakhan, Natal\'hakata quizás tenga algo bueno para ti dentro del Gran Sello.', 'Si has cumplido los deseo\' del rey Rastakhan, Natal\'hakata quizás tenga algo bueno para ti dentro del Gran Sello.', 28153),
(159391, 'esMX', 'Emisarios', 'Emisarios', 28153),
(159390, 'esMX', '', 'Tirisfal ha visto el auge y la caída de grandes poderes. Me pregunto si los de tu tipo alguna vez... cosecharán las lecciones de su pasado.\n\nPero ese no es el punto.\n\n¿Ya te encargaste de tus antiguos asuntos, $Ucampeón:campeona;?', 28153),
(159389, 'esMX', '', 'Teldrassil... Era un paisaje magnífico, ¿no es cierto? A menudo, las cosas más hermosas son también las más fugaces.\n\nEspecialmente cuando los mortales insisten en arrojarles fuego.\n\n¿Ya has resuelto tus asuntos del pasado, $Ucampeón:campeona;?', 28153),
(159388, 'esMX', 'Si tú cree\' que puedes descansar con esa cosa muerta bailando sin parar, ve a buscarla dentro del Gran Sello.', 'Si tú cree\' que puedes descansar con esa cosa muerta bailando sin parar, ve a buscarla dentro del Gran Sello.', 28153),
(159386, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t ¡Vectis comienza a lanzar |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t ¡Vectis comienza a lanzar |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', 28153),
(159385, 'esMX', 'Los pedidos de refugio se organizarán de acuerdo con la prioridad de cada caso.', '', 28153),
(159384, 'esMX', '', 'Desde estas costas, podrás contemplar Teldrassil. Fue cuna de vida, y ahora no es más que un montón de ruinas de cenizas y brasas.\n\nTambién los Árboles del Mundo deben inclinarse ante el ciclo de la vida. Todo lo que ha nacido alguna vez morirá.\n\nNadie comprende esta noción mejor que el vuelo bronce.\n\n¿Te gustaría ver cómo era el árbol antes?', 28153),
(159383, 'esMX', 'Por desgracia, nuestros recursos están bastante restringidos en este momento.', '', 28153),
(159382, 'esMX', 'Encontrarás a Paku\'ai en la cornisa que eh\'tá afuera del Gran Sello. ¿A dónde vas?', 'Encontrarás a Paku\'ai en la cornisa que eh\'tá afuera del Gran Sello. ¿A dónde vas?', 28153),
(159381, 'esMX', 'Tengan paciencia. Estamos haciendo todo lo que podemos en esta situación.', '', 28153),
(159379, 'esMX', '', 'Tirisfal... un lugar donde abunda la belleza y la oscuridad. Una tierra repleta de remordimientos... y de tumbas.\n\nLos de tu clase han luchado por apoderarse de ella una y otra vez.\n\n¿Quieres ver cómo era antes de la última guerra?', 28153),
(159378, 'esMX', 'Ya me estaba cansando de la carne de cabra.', '', 28153),
(159377, 'esMX', '¿Quiénes vienen?', '', 28153),
(159376, 'esMX', 'Podemos llevarte a ti y a un pequeño escuadrón en un abrir y cerrar de ojos.', '', 28153),
(159375, 'esMX', 'Falstad Martillo Salvaje silba y sus jinetes de grifos descienden a la cubierta.', '', 28153),
(159374, 'esMX', 'Tu nave es demasiado lenta para llegar a tiempo. Pero la velocidad no es un problema para los Martillo Salvaje.', '', 28153),
(159373, 'esMX', 'Si Dreven está a bordo de ese barco, estará acorralado. No tendrá a dónde escapar... si podemos atacarlo antes de que llegue a tierra firme.', '', 28153),
(159372, 'esMX', '', 'Durante mi cacería, me enteré de que el príncipe de sangre Dreven está viajando en barco con un maresabio traidor.', 28153),
(159371, 'esMX', '', 'De hecho, creo que es la máxima prioridad. Gracias, Mathias.', 28153),
(159370, 'esMX', '', 'Shandris Plumaluna desciende a la cubierta a lomos de su hipogrifo.', 28153),
(159369, 'esMX', 'No estamos seguros, pero puedo enviar unos agentes a investigar. Creemos que es una tarea de poca prioridad.', '', 28153),
(159368, 'esMX', '¿Qué estará buscando la Horda en naufragios antiguos...?', '', 28153),
(159367, 'esMX', 'Gracias, Mathias.', '', 28153),
(159366, 'esMX', 'Por supuesto, dejamos que el original llegara a destino sin rastros de manipulación, pero creamos un duplicado para ti.', '', 28153),
(159365, 'esMX', 'Alto comandante, mis agentes han interceptado órdenes de Sylvanas.', '', 28153),
(159364, 'esMX', 'Mi pueblo no cometerá el mismo error con el Vacío. Lo prometo.', '', 28153),
(159363, 'esMX', '', 'Como has dicho, Umbric, he vivido durante mucho tiempo. He visto cómo el poder corrompió a las razas más nobles... la resistencia no es algo común.', 28153),
(159362, 'esMX', 'Suenas sorprendida. ¿Creías que la magia del Vacío no era más que un juguete para mi pueblo?', '', 28153),
(159361, 'esMX', '', '¿Para proteger? Qué interesante, Umbric.', 28153),
(159360, 'esMX', 'El Vacío puede utilizarse para proteger, siempre y cuando no sucumbas ante su poder.', '', 28153),
(159359, 'esMX', '', 'Y parece que no dudas en utilizar tus poderes del Vacío contra ellos.', 28153),
(159358, 'esMX', 'Tú y yo hemos vivido durante mucho tiempo, Shandris. Conozco a muchos que han sido víctimas de la barbarie zandalari.', '', 28153),
(159357, 'esMX', '', 'Suenas como si ya te hubieses enfrentado a los zandalari antes.', 28153),
(159356, 'esMX', 'Mi pueblo y yo no permitiremos que esos trols monstruosos destruyan la Alianza. Lo juro.', '', 28153),
(159355, 'esMX', '', 'La cantidad de guardias que hay en este puerto es impresionante. Deben estar preparándose para desplegar la flota.', 28153),
(159354, 'esMX', '', 'Tenemos que advertirle a Halford apenas dejemos a $n.', 28153),
(159353, 'esMX', 'Suena mal si consideras que su ruta la llevará por las inmediaciones del puesto de avanzada que tenemos en Xibala.', '', 28153),
(159352, 'esMX', '', '¿Una nave? No suena tan mal.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159351, 'esMX', 'Tenemos un problema. Hay una nave que no tuvimos en cuenta. Quizá sea una que estaba atracada en Pandaria.', '', 28153),
(159350, 'esMX', 'Veamos. Parece que la inteligencia de Halford estaba en lo cierto respecto a ubicación de la mayoría de las naves, además de las rutas de navegación. Aunque...', '', 28153),
(159349, 'esMX', '', 'Espiar no es lo mío... pero esta vez haré una excepción. Veamos...', 28153),
(159348, 'esMX', '¿Has conseguido información de los registros que recuperó $n?', '', 28153),
(159347, 'esMX', '', '¡Mucha suerte! El Puerto de Guerra Rastari está colmado de zandalari. Estoy segura de que Shandris tiene un plan.', 28153),
(159346, 'esMX', 'Si lo que buscas es un cambio, te recomiendo ver a esos goblins extraño\' del Gran Bazar, el que eh\'tá cerca del puerto.', 'Si lo que buscas es un cambio, te recomiendo ver a esos goblins extraño\' del Gran Bazar, el que eh\'tá cerca del puerto.', 28153),
(159343, 'esMX', 'Por estas zonas deambulan toda clase de criaturas extrañas. Hay castores, conejos y ardillas, lo de siempre, pero también unos seres extraños que parecen un fardo de pinchos andante. Después de días y días, pude atrapar a uno y entrenarlo. Resultó ser de lo más leal. No me malinterpretes: aullarás de dolor si te alcanza con uno de esos pinchos afilados, pero es genial, de eso no hay dudas. ¿Quieres verlo en acción?', '', 28153),
(159342, 'esMX', 'El Tesoro Real eh\'tá en el medio de la pirámide que eh\'tá cerca del Gran Sello.', 'El Tesoro Real eh\'tá en el medio de la pirámide que eh\'tá cerca del Gran Sello.', 28153),
(159340, 'esMX', 'Es hora de poner algunas bombas... y no explotarlas. Por ahora.', '', 28153),
(159339, 'esMX', '', 'No digas eso, Flynn. ¡Tenemos que aferrarnos a la esperanza de que Jaina siga viva!', 28153),
(159338, 'esMX', '$n, extiéndele mis más sinceras condolencias a Lady Katherine.', '', 28153),
(159337, 'esMX', 'Límite del Destino... Sin dudas no elegiría irme de este mundo de esa forma.', '', 28153),
(159336, 'esMX', '¡Vamos a jugar!', '¡Vamos a jugar!', 28153),
(159335, 'esMX', '¡Quítenles sus cosas brillantes!', '¡Quítenles sus cosas brillantes!', 28153),
(159334, 'esMX', '¡Ohhh, tienen cosas brillantes!', '¡Ohhh, tienen cosas brillantes!', 28153),
(159333, 'esMX', '¡Vengan a jugar con nosotros!', '¡Vengan a jugar con nosotros!', 28153),
(159332, 'esMX', '¡Ja, ja, ja!', '¡Ja, ja, ja!', 28153),
(159331, 'esMX', '¡Atrapados!', '¡Atrapados!', 28153),
(159330, 'esMX', '¡Los tengo!', '¡Los tengo!', 28153),
(159329, 'esMX', '¡Je, je, je!', '¡Je, je, je!', 28153),
(159228, 'esMX', '', 'Ten cuidado. ¡Estaré esperando tu señal!', 28153),
(159227, 'esMX', 'Cuando hayas terminado, nos encontraremos en Puerto Libre.', '', 28153),
(159226, 'esMX', 'Tú toma algunas granadas. Yo tengo que ir a hablar con una cadete sobre un pajarito.', '', 28153),
(159225, 'esMX', 'Parece que no se atrevieron a revelar el destino, ni siquiera en esta maraña de jerga legal y ambigüedad. Pero apuesto a que sé dónde guardaron esa información.', '', 28153),
(159224, 'esMX', 'Quizás haya algo en la letra pequeña...', '', 28153),
(159223, 'esMX', '¿Así que Lady Katherine te está haciendo buscar a su hija? Bueno, veamos qué tiene para decir este contrato al respecto.', '', 28153),
(159222, 'esMX', '¡Vamos! ¿A dónde \"llevan\" a Jaina?', '', 28153),
(159221, 'esMX', 'Más definiciones, más condiciones de servicio... puro palabrerío jurídico que jamás se sostendría en un juicio a menos que el juez fuera muy corrupto....', '', 28153),
(159220, 'esMX', 'Diez páginas de medidas de seguridad... veinte páginas de condiciones de responsabilidad...', '', 28153),
(159219, 'esMX', 'Descripción de servicios, el locador proveerá al locatario... bla, bla, bla...', '', 28153),
(159218, 'esMX', 'Por la presente, Aspafresno etc. contrata los servicios... Puaj, ¿quién escribe estas cosas?', '', 28153),
(159217, 'esMX', '', 'Atraviesen el muro, ¡rápido! No podré contenerlo mucho más tiempo.', 28153),
(159216, 'esMX', 'Lady Katherine me ha pedido que busque a su hija. Hasta ahora, esta es la única pista que tengo.', 'Lady Katherine me ha pedido que busque a su hija. Hasta ahora, esta es la única pista que tengo.', 28153),
(159215, 'esMX', 'Hola, $n. Me alegra volver a verte.', '', 28153),
(159214, 'esMX', '', 'Vuelve a verme apenas descubras a dónde llevaron a Jaina, $n.', 28153),
(159213, 'esMX', '', 'Espero que tengas razón, Genn.', 28153),
(159212, 'esMX', '$n es $Uuno de los mejores:una de las mejores; de la Alianza, Katherine. No creo que haya alguien más capaz de recuperar a Jaina.', '', 28153),
(159211, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t ¡|cFFFF0000|Hspell:265129|h[Vector omega]|h|r te ha infectado!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t ¡|cFFFF0000|Hspell:265129|h[Vector omega]|h|r te ha infectado!', 28153),
(159210, 'esMX', '¡Espera! ¡Usa el talismán de control!', '', 28153),
(159209, 'esMX', 'Esta es tu parada. Ten cuidado. No lo olvides: ¡coloca las bombas y no dejes que alerten al continente de tu presencia!', '', 28153),
(159208, 'esMX', '... Este podría ser el comienzo de una hermosa amistad.', '', 28153),
(159207, 'esMX', '', '¿Una? No, no, no. Tengo MUCHAS colecciones de cuchillos.', 28153),
(159206, 'esMX', '¿Tienes una colección de cuchillos?', '', 28153),
(159205, 'esMX', '', 'Eres de los míos, Keeshan. Tendremos que comparar nuestras colecciones de cuchillos después de esto.', 28153),
(159204, 'esMX', 'Y yo ayudaré a $n plantando las bombas de Kelsey en las naves pequeñas... y también mataré a cualquier zandalari que me vea.', '', 28153),
(159203, 'esMX', '', 'Estaré ocupada trabajando en un dispositivo para ayudar a $n a cruzar el agua para la próxima parte del plan.', 28153),
(159202, 'esMX', 'Solo tienen que asegurarse de que no los vean plantando esas bombas en las bases de las naves.', '', 28153),
(159201, 'esMX', 'No hace falta que lo repitas. Los dejaré en la Isla de Colmillos. Está a una distancia suficiente de la ciudad para que puedan actuar contra los zandalari con impunidad.', '', 28153),
(159200, 'esMX', 'Una vez casi me devoran. No lo recomiendo.', '', 28153),
(159199, 'esMX', '', 'Nos harían alimento para sus dinosaurios. Nos morderían y nos masticarían.', 28153),
(159198, 'esMX', 'Sí. Si encuentran a unos pocos, como a $n, es una cosa. ¿Pero si encuentran todo el maldito campamento?', '', 28153),
(159197, 'esMX', '', '¿Por qué crees que Halford avanza tan rápido? Sabe que si los zandalari nos atrapan en su hogar, será nuestro fin.', 28153),
(159196, 'esMX', 'El campamento de la Alianza sobresale como mosca en la leche. Tenemos que prepararnos para cuando los zandalari nos descubran.', '', 28153),
(159195, 'esMX', '¡Listo! Esta altura debería ser suficiente para evitar que los zandalari nos detecten.', '', 28153),
(159194, 'esMX', 'Sujétate, ¡tenemos que volar MUY alto para evitar que nos detecten!', '', 28153),
(159193, 'esMX', '', 'Puedes venir a visitar cuando lo desees, $p.', 28153),
(159192, 'esMX', '', 'Siempre que te veo estás $Udesabrigado:desabrigada;, cariño. ¡Te pescarás un resfriado si no te cuidas!', 28153),
(159191, 'esMX', '', 'Espero que estés descansando bien. ¡Siempre habrá monstruos contra los que luchar!', 28153),
(159190, 'esMX', 'Hablemos del plan para debilitar a la flota zandalari.', 'Hablemos del plan para debilitar a la flota zandalari.', 28153),
(159189, 'esMX', '¿Cómo te... ATREVES...?', '¿Cómo te... ATREVES...?', 28153),
(159188, 'esMX', 'La marea aplastante... está por llegar...', 'La marea aplastante... está por llegar...', 28153),
(159187, 'esMX', 'La oscuridad... solo es temporal...', 'La oscuridad... solo es temporal...', 28153),
(159186, 'esMX', '$UMocoso:Mocosa;... insolente...', '$UMocoso:Mocosa;... insolente...', 28153),
(159185, 'esMX', 'Tenemos miles de ensamblajes... no pueden ganar...', 'Tenemos miles de ensamblajes... no pueden ganar...', 28153),
(159184, 'esMX', 'Mi espíritu... regresará...', 'Mi espíritu... regresará...', 28153),
(159183, 'esMX', 'Esto no se termina con mi muerte...', 'Esto no se termina con mi muerte...', 28153),
(159182, 'esMX', 'Reconstruiremos... todo...', 'Reconstruiremos... todo...', 28153),
(159181, 'esMX', '¡La muerte será solo el comienzo de tu castigo!', '¡La muerte será solo el comienzo de tu castigo!', 28153),
(159180, 'esMX', '', '¡Vaya! ¡Hola, encanto! ¿Podrías darme una mano con un encargo o dos? ¡Solo si no es mucha molestia!', 28153),
(159179, 'esMX', 'Necio, tu suerte está echada.', 'Necio, tu suerte está echada.', 28153),
(159178, 'esMX', '¡Arrodíllate, $uintruso:intrusa;!', '¡Arrodíllate, $uintruso:intrusa;!', 28153),
(159177, 'esMX', '¡Tu muerte será lenta, $uintruso:intrusa;!', '¡Tu muerte será lenta, $uintruso:intrusa;!', 28153),
(159176, 'esMX', 'Nosotros llegamos antes que ustedes a este sitio, ¡y estaremos aquí cuando mueran!', 'Nosotros llegamos antes que ustedes a este sitio, ¡y estaremos aquí cuando mueran!', 28153),
(159175, 'esMX', '¡Criatura cárnica insolente!', '¡Criatura cárnica insolente!', 28153),
(159174, 'esMX', '¡Aprenderás a respetar a tus superiores!', '¡Aprenderás a respetar a tus superiores!', 28153),
(159173, 'esMX', '¡Este no es lugar para los débiles!', '¡Este no es lugar para los débiles!', 28153),
(159172, 'esMX', 'Lo que está muerto... no puede morir...', 'Lo que está muerto... jamás morirá...', 28153),
(159171, 'esMX', 'Regreso con ella, solo por un momento...', 'Regreso con ella, solo por un momento...', 28153),
(159170, 'esMX', 'Nadie se olvidará de nosotros en las profundidades...', 'Nadie se olvidará de nosotros en las profundidades...', 28153),
(159169, 'esMX', 'Ella nos librará de este tormento...', 'Ella nos librará de este tormento...', 28153),
(159168, 'esMX', 'Ella se quedará con el líquido dorado... No puedes detenernos a todos...', 'Ella se quedará con el líquido dorado... No puedes detenernos a todos...', 28153),
(159167, 'esMX', 'Somos eternos... Tu victoria no significa nada...', 'Somos eternos... Tu victoria no significa nada...', 28153),
(159166, 'esMX', 'Ella me revivirá...', 'Ella me revivirá...', 28153),
(159165, 'esMX', 'Los mortales... no pueden matarnos...', 'Los mortales... no pueden matarnos...', 28153),
(159164, 'esMX', '¡Te robaré el aire de los pulmones!', '¡Te robaré el aire de los pulmones!', 28153),
(159163, 'esMX', '¡Estas aguas nos pertenecen!', '¡Estas aguas nos pertenecen!', 28153),
(159162, 'esMX', '¡Las profundidades aplastarán tus huesos frágiles!', '¡Las profundidades aplastarán tus huesos frágiles!', 28153),
(159161, 'esMX', '¡Las mareas te llevarán!', '¡Las mareas te llevarán!', 28153),
(159160, 'esMX', '¡Helya te llama!', '¡Helya te llama!', 28153),
(159159, 'esMX', '¡Sus almas serán nuestras!', '¡Sus almas serán nuestras!', 28153),
(159158, 'esMX', 'Te unirás a nosotros en la muerte, ¡te unirás a su ejército!', 'Te unirás a nosotros en la muerte, ¡te unirás a su ejército!', 28153),
(159157, 'esMX', '¡Las nieblas vienen por ti!', '¡Las nieblas vienen por ti!', 28153),
(159156, 'esMX', 'Nunca dominarás los mares...', 'Nunca dominarás los mares...', 28153),
(159155, 'esMX', 'Muere uno, pero miles siguen con vida...', 'Muere uno, pero miles siguen con vida...', 28153),
(159154, 'esMX', 'No creas que has ganado...', 'No creas que has ganado...', 28153),
(159153, 'esMX', 'Tu futuro... es fatídico...', 'Tu futuro... es fatídico...', 28153),
(159152, 'esMX', 'La muerte viene a buscarlos...', 'La muerte viene a buscarlos...', 28153),
(159151, 'esMX', 'Azshara... es todo...', 'Azshara... es todo...', 28153),
(159150, 'esMX', 'Mi Azshara... Regreso a las olas...', 'Mi Azshara... Regreso a las olas...', 28153),
(159149, 'esMX', 'Mi reina...', 'Mi reina...', 28153),
(159148, 'esMX', '¡El dios de las profundidades te espera y se retuerce de solo pensar en tu llegada!', '¡El dios de las profundidades te espera y se retuerce de solo pensar en tu llegada!', 28153),
(159147, 'esMX', '¡Los ojos de las profundidades te volverán $uloco:loca;!', '¡Los ojos de las profundidades te volverán $uloco:loca;!', 28153),
(159146, 'esMX', '¿Sientes el miedo? ¿El terror perpetuo de las profundidades?', '¿Sientes el miedo? ¿El terror perpetuo de las profundidades?', 28153),
(159145, 'esMX', 'El Imperio Negro renacerá en este mundo, ¡y su alma alimentará a los grandes!', 'El Imperio Negro renacerá en este mundo, ¡y su alma alimentará a los grandes!', 28153),
(159144, 'esMX', 'Hemos esperado demasiado tiempo... ¡La era de los naga ha llegado!', 'Hemos esperado demasiado tiempo... ¡La era de los naga ha llegado!', 28153),
(159143, 'esMX', '¡La Ciudad Sumergida se alzará y será heraldo de tu perdición!', '¡La Ciudad Sumergida se alzará y será heraldo de tu perdición!', 28153),
(159142, 'esMX', 'N\'zoth nos invoca a todos nosotros, ¿acaso no lo oyes?', 'N\'zoth nos invoca a todos nosotros, ¿acaso no lo oyes?', 28153),
(159141, 'esMX', 'Por la gran reina Azshara, ¡que reine eternamente!', 'Por la gran reina Azshara, ¡que reine eternamente!', 28153),
(159140, 'esMX', '¡Tu tiempo se acaba ahora!', '¡Tu tiempo se acaba ahora!', 28153),
(159139, 'esMX', '¡Venimos desde las profundidades!', '¡Venimos desde las profundidades!', 28153),
(159138, 'esMX', '¡Asesínenlos!', '¡Asesínenlos!', 28153),
(159137, 'esMX', '¡Te hundirás en la angustia!', '¡Te hundirás en la angustia!', 28153),
(159136, 'esMX', '¡El que se retuerce nos canta!', '¡El que se retuerce nos canta!', 28153),
(159135, 'esMX', '¡Las profundidades susurrantes te llaman!', '¡Las profundidades susurrantes te llaman!', 28153),
(159134, 'esMX', '¡Por Azshara!', '¡Por Azshara!', 28153),
(159133, 'esMX', '¡Arrástrate de nuevo al agujero de donde saliste!', '¡Arrástrate de nuevo al agujero de donde saliste!', 28153),
(159132, 'esMX', 'Maldición de sangre detectada; iniciando protocolo de sanidad.', 'Maldición de sangre detectada; iniciando protocolo de sanidad.', 28153),
(159131, 'esMX', 'Tienen cuerpos débiles y maleables. Les daré una forma nueva.', 'Tienen cuerpos débiles y maleables. Les daré una forma nueva.', 28153),
(159130, 'esMX', 'Buscan lastimar al alma del mundo y robarle su sangre. Tendremos que reformarlos.', 'Buscan lastimar al alma del mundo y robarle su sangre. Tendremos que reformarlos.', 28153),
(159129, 'esMX', 'Somos los defensores de esta alma del mundo... No pueden continuar.', 'Somos los defensores de esta alma del mundo... No pueden continuar.', 28153),
(159128, 'esMX', 'Están entorpeciendo nuestro deber sagrado. Tendremos que purificarlos.', 'Están entorpeciendo nuestro deber sagrado. Tendremos que purificarlos.', 28153),
(159127, 'esMX', 'Los de carne maldita deben volver a nacer. Este es nuestro deber.', 'Los de carne maldita deben volver a nacer. Este es nuestro deber.', 28153),
(159126, 'esMX', '¡Nos han creado para proteger a este mundo de los de la carne maldita!', '¡Nos han creado para proteger a este mundo de los de la carne maldita!', 28153),
(159125, 'esMX', 'Nos han creado para eliminar su enfermedad. No se muevan.', 'Nos han creado para eliminar su enfermedad. No se muevan.', 28153),
(159124, 'esMX', 'Nadie torcerá nuestro destino...', 'Nadie torcerá nuestro destino...', 28153),
(159123, 'esMX', 'Lo reconstruiremos todo... una y otra vez...', 'Lo reconstruiremos todo... una y otra vez...', 28153),
(159122, 'esMX', 'Nuestra misión... no puede fracasar...', 'Nuestra misión... no puede fracasar...', 28153),
(159121, 'esMX', 'Sus acciones causarán el fin de este mundo...', 'Sus acciones causarán el fin de este mundo...', 28153),
(159120, 'esMX', 'Debemos proteger... al alma del mundo...', 'Debemos proteger... al alma del mundo...', 28153),
(159119, 'esMX', 'No lo... entienden...', 'No lo... entienden...', 28153),
(159118, 'esMX', 'Este no es... nuestro destino...', 'Este no es... nuestro destino...', 28153),
(159117, 'esMX', 'Los creadores... regresarán...', 'Los creadores... regresarán...', 28153),
(159116, 'esMX', 'Están perdidos. Dejen que los reorientemos.', 'Están perdidos. Dejen que los reorientemos.', 28153),
(159115, 'esMX', 'Nadie debe interferir con nuestro deber sagrado.', 'Nadie debe interferir con nuestro deber sagrado.', 28153),
(159114, 'esMX', '¡Los creadores nos dejaron aquí para proteger este mundo! ¡Apártense!', '¡Los creadores nos dejaron aquí para proteger este mundo! ¡Apártense!', 28153),
(159113, 'esMX', '¡Los de la carne maldita están fuera de control!', '¡Los de la carne maldita están fuera de control!', 28153),
(159112, 'esMX', 'Les daremos un nuevo origen. No se muevan...', 'Les daremos un nuevo origen. No se muevan...', 28153),
(159111, 'esMX', 'Tenemos que curarlos de su enfermedad.', 'Tenemos que curarlos de su enfermedad.', 28153),
(159110, 'esMX', 'Su carne está maldita. Los curaremos.', 'Su carne está maldita. Los curaremos.', 28153),
(159109, 'esMX', 'Es nuestra tarea supervisar la sangre del planeta.', 'Es nuestra tarea supervisar la sangre del planeta.', 28153),
(159108, 'esMX', 'Al menos moriré con los bolsillos llenos...', 'Al menos moriré con los bolsillos llenos...', 28153),
(159107, 'esMX', 'Díganles a mis hijos... que no hay herencia...', 'Díganles a mis hijos... que no hay herencia...', 28153),
(159106, 'esMX', 'Recuérdenme... por mis ganancias trimestrales...', 'Recuérdenme... por mis ganancias trimestrales...', 28153),
(159105, 'esMX', '¡Un momento! ¡Les pagaré para que me resuciten! ¡Vamos!', '¡Un momento! ¡Les pagaré para que me resuciten! ¡Vamos!', 28153),
(159104, 'esMX', '¡Uf! Una auditoría...', '¡Uf! Una auditoría...', 28153),
(159103, 'esMX', 'Espero que esto... no afecte mi... pensión...', 'Espero que esto... no afecte mi... pensión...', 28153),
(159102, 'esMX', '¡Estamos en rojo!', '¡Estamos en rojo!', 28153),
(159101, 'esMX', 'Ha caído... la bolsa...', 'Ha caído... la bolsa...', 28153),
(159100, 'esMX', '¡Prepárense para cobrar!', '¡Prepárense para cobrar!', 28153),
(159099, 'esMX', '¡Si no los matamos, los gastos saldrán del presupuesto para el almuerzo!', '¡Si no los matamos, los gastos saldrán del presupuesto para el almuerzo!', 28153),
(159098, 'esMX', '¡Me aumentarán el suelo cuando lleve sus cabezas!', '¡Me aumentarán el suelo cuando lleve sus cabezas!', 28153),
(159097, 'esMX', '¡Guardé un poco de tiempo libre en mi cronograma solo para matarlos!', '¡Guardé un poco de tiempo libre en mi cronograma solo para matarlos!', 28153),
(159096, 'esMX', '¡A los accionistas no les gustará nada que se entrometan en nuestro negocio!', '¡A los accionistas no les gustará nada que se entrometan en nuestro negocio!', 28153),
(159095, 'esMX', '¡Se acabó! ¡Ya no más técnicas de gestión!', '¡Se acabó! ¡Ya no más técnicas de gestión!', 28153),
(159094, 'esMX', 'Los convertiré en dulces y hermosas ganancias.', 'Los convertiré en dulces y hermosas ganancias.', 28153),
(159093, 'esMX', '¡Las ganancias son mejores de lo que esperaba!', '¡Las ganancias son mejores de lo que esperaba!', 28153),
(159092, 'esMX', '¡Considérense adquiridos!', '¡Considérense adquiridos!', 28153),
(159091, 'esMX', '¡Esto es una sublevación hostil!', '¡Esto es una sublevación hostil!', 28153),
(159090, 'esMX', '¡Que alguien active el kit de emergencia! ¡Tenemos compañía!', '¡Que alguien active el kit de emergencia! ¡Tenemos compañía!', 28153),
(159089, 'esMX', '¡Gracias! Te lo agradezco.', '¡Gracias! Te lo agradezco.', 28153),
(159088, 'esMX', '¡Están recortando mi margen de ganancias!', '¡Están recortando mi margen de ganancias!', 28153),
(159087, 'esMX', '¡No podemos darnos el lujo de detener las operaciones por esto!', '¡No podemos darnos el lujo de detener las operaciones por esto!', 28153),
(159086, 'esMX', '¿Qué hacen aquí? ¡Estas son tierras de Ventura! ¿No recibieron el memo?', '¿Qué hacen aquí? ¡Estas son tierras de Ventura! ¿No recibieron el memo?', 28153),
(159085, 'esMX', '¡Argh! ¡Intrusos! ¡Que alguien me defienda!', '¡Argh! ¡Intrusos! ¡Que alguien me defienda!', 28153),
(159084, 'esMX', '¡Atrápenlos! ¡Pero usen lo más barato!', '¡Atrápenlos! ¡Pero usen lo más barato!', 28153),
(159083, 'esMX', 'Recuerden, nuestro objetivo principal es debilitar sus defensas y que no descubran la posición de nuestras fuerzas. Si nos descubren, todo está perdido. ¡Retírense!', '', 28153),
(159082, 'esMX', '¿Darle 20 helados de fresa de Tigule y Foror a Marie Davenport?', '¿Darle 20 helados de fresa de Tigule y Foror a Marie Davenport?', 28153),
(159081, 'esMX', '', 'Umbric y yo nos adelantaremos para preparar un ataque sigiloso en el puerto de guerra.', 28153),
(159080, 'esMX', 'Marchan hacia la muerte de su mundo... cegados por su arrogancia...', 'Marchan hacia la muerte de su mundo... cegados por su arrogancia...', 28153),
(159079, 'esMX', 'Solo queríamos... lo que nos pertenece...', 'Solo queríamos... lo que nos pertenece...', 28153),
(159078, 'esMX', 'Solo retrasan... lo inevitable...', 'Solo retrasan... lo inevitable...', 28153),
(159077, 'esMX', 'La nidada crecerá más fuerte... sin mí...', 'La nidada crecerá más fuerte... sin mí...', 28153),
(159076, 'esMX', 'El cielo se oscurece...', 'El cielo se oscurece...', 28153),
(159075, 'esMX', 'Exacto. $n, tú serás estarás a cargo del operativo para debilitar las defensas portuarias de los zandalari. Kelsey, Falstad y Keeshan te ayudarán con el primer objetivo.', '', 28153),
(159074, 'esMX', 'Nosotros... no elegimos nuestro destino...', 'Nosotros... no elegimos nuestro destino...', 28153),
(159073, 'esMX', 'Nunca nos dieron... una oportunidad...', 'Nunca nos dieron... una oportunidad...', 28153),
(159072, 'esMX', 'Caemos... otra vez...', 'Caemos... otra vez...', 28153),
(159071, 'esMX', 'Antaño caímos ante ustedes, ¡pero no volverá a suceder! ¡Este es el albor del crepúsculo!', 'Antaño caímos ante ustedes, ¡pero no volverá a suceder! ¡Este es el albor del crepúsculo!', 28153),
(159070, 'esMX', 'Necesitamos las menas brillantes, no podemos sobrevivir por nuestra cuenta... ¿Acaso no lo ven?', 'Necesitamos las menas brillantes, no podemos sobrevivir por nuestra cuenta... ¿Acaso no lo ven?', 28153),
(159069, 'esMX', '', 'Ah... y esperamos a que llegue nuestra flota para detonarlos. La ciudad entrará en caos y podremos recalar.', 28153),
(159068, 'esMX', '¡Solo queremos lo que nos prometieron hace mucho tiempo!', '¡Solo queremos lo que nos prometieron hace mucho tiempo!', 28153),
(159067, 'esMX', 'El líquido dorado anuncia el regreso de nuestro vuelo... ¡Están perdidos!', 'El líquido dorado anuncia el regreso de nuestro vuelo... ¡Están perdidos!', 28153),
(159066, 'esMX', 'Si hacemos las cosas bien, los zandalari no sabrán que hemos colocado explosivos en sus defensas.', '', 28153),
(159065, 'esMX', '¡Ahora controlamos nuestras mentes! ¡Déjennos en paz!', '¡Ahora controlamos nuestras mentes! ¡Déjennos en paz!', 28153),
(159064, 'esMX', 'Exacto. Shandris, Falstad y yo hemos propuesto un plan que el rey Wrynn aprobó. Si triunfamos, nuestras fuerzas tendrán una posibilidad.', '', 28153),
(159063, 'esMX', 'Ahora, nuestro vuelo nos pertenece. ¡No seremos prisioneros de nadie, y menos de ustedes!', 'Ahora, nuestro vuelo nos pertenece. ¡No seremos prisioneros de nadie, y menos de ustedes!', 28153),
(159062, 'esMX', 'El vuelo crepuscular regresa sin que puedan evitarlo. ¡La arrogancia será su fin!', 'El vuelo crepuscular regresa sin que puedan evitarlo. ¡La arrogancia será su fin!', 28153),
(159061, 'esMX', '', '¡Para eso querían las bombas!', 28153),
(159060, 'esMX', 'Los llamados \"gobernantes\" de este mundo nos hicieron a un lado... ¡Pero nadie nos olvidará!', 'Los llamados \"gobernantes\" de este mundo nos hicieron a un lado... ¡Pero nadie nos olvidará!', 28153),
(159059, 'esMX', '', 'Los zandalari son poderosos, pero no invencibles. Sabotearemos las ubicaciones clave de sus defensas portuarias con bombas de detonación remota.', 28153),
(159058, 'esMX', '¡Esta vez no podrán detenernos!', '¡Esta vez no podrán detenernos!', 28153),
(159057, 'esMX', '¡Gloria al crepúsculo!', '¡Gloria al crepúsculo!', 28153),
(159056, 'esMX', '¡Ahora nosotros decidimos nuestro destino!', '¡Ahora nosotros decidimos nuestro destino!', 28153),
(159055, 'esMX', 'Terminemos con esto de una vez. La Alianza necesita nuestro apoyo para prepararse para una invasión total a Zuldazar.', '', 28153),
(159054, 'esMX', '¡No nos volverán a hacer a un lado!', '¡No nos volverán a hacer a un lado!', 28153),
(159053, 'esMX', '¡El vuelo olvidado no esperará más!', '¡El vuelo olvidado no esperará más!', 28153),
(159052, 'esMX', 'Llegamos desde la oscuridad para gobernar este mundo.', 'Llegamos desde la oscuridad para gobernar este mundo.', 28153),
(159051, 'esMX', '¡El vuelo crepuscular imperará!', '¡El vuelo crepuscular imperará!', 28153),
(159050, 'esMX', '¡Por el crepúsculo!', '¡Por el crepúsculo!', 28153),
(159049, 'esMX', 'Somos los guardianes de la tierra. ¡Estás entrometiéndote donde no debes, pielsuave!', 'Somos los guardianes de la tierra. ¡Estás entrometiéndote donde no debes, pielsuave!', 28153),
(159048, 'esMX', 'No tienes idea dónde está nuestra nidada, no podrás ganar. ¡Ríndete ahora!', 'No tienes idea dónde está nuestra nidada, no podrás ganar. ¡Ríndete ahora!', 28153),
(159047, 'esMX', '¡El vuelo negro se vengará de una vez por todas!', '¡El vuelo negro se vengará de una vez por todas!', 28153),
(159046, 'esMX', '¡Nosotros protegemos las piedras de este mundo de seres como tú!', '¡Nosotros protegemos las piedras de este mundo de seres como tú!', 28153),
(159045, 'esMX', 'Patéticas criaturas cárnicas... ¡nosotros protegemos la sangre dorada del mundo!', 'Patéticas criaturas cárnicas... ¡nosotros protegemos la sangre dorada del mundo!', 28153),
(159044, 'esMX', 'El mundo se entregó a los dragones, ¡tu especie es una plaga!', 'El mundo se entregó a los dragones, ¡tu especie es una plaga!', 28153),
(159043, 'esMX', '¿Cómo te atreves a tomar lo que es legítimamente nuestro?', '¿Cómo te atreves a tomar lo que es legítimamente nuestro?', 28153),
(159042, 'esMX', '¡La sangre del mundo es nuestra carga! ¡Somos los guardianes!', '¡La sangre del mundo es nuestra carga! ¡Somos los guardianes!', 28153),
(159041, 'esMX', 'Nos robas... lo que nos pertenece por derecho...', 'Nos robas... lo que nos pertenece por derecho...', 28153),
(159040, 'esMX', 'La historia no nos olvidará...', 'La historia no nos olvidará...', 28153),
(159039, 'esMX', 'El vuelo negro viene por todos ustedes...', 'El vuelo negro viene por todos ustedes...', 28153),
(159038, 'esMX', 'No pueden ganar esta guerra...', 'No pueden ganar esta guerra...', 28153),
(159037, 'esMX', 'Este mundo les pertenece... a los dragones...', 'Este mundo les pertenece... a los dragones...', 28153),
(159036, 'esMX', 'Tu especie... no pertenece a este sitio...', 'Tu especie... no pertenece a este sitio...', 28153),
(159035, 'esMX', 'Nadie puede derrotar al vuelo negro...', 'Nadie puede derrotar al vuelo negro...', 28153),
(159034, 'esMX', 'Regresaremos...', 'Regresaremos...', 28153),
(159033, 'esMX', '¡El vuelo negro renacerá!', 'The black flight will be reborn!', 28153),
(159032, 'esMX', '¡Erradicaremos a los tuyos!', '¡Erradicaremos a los tuyos!', 28153),
(159031, 'esMX', '¡Traeremos el fuego y la muerte!', '¡Traeremos el fuego y la muerte!', 28153),
(159030, 'esMX', '¿Te atreves a enfrentarte a un vuelo?', '¿Te atreves a enfrentarte a un vuelo?', 28153),
(159029, 'esMX', '¡El vuelo negro volverá a alzarse!', '¡El vuelo negro volverá a alzarse!', 28153),
(159028, 'esMX', '¡Gloria al vuelo negro!', '¡Gloria al vuelo negro!', 28153),
(159027, 'esMX', '¡Por los guardianes de la tierra!', '¡Por los guardianes de la tierra!', 28153),
(159026, 'esMX', '¡Defenderé el vuelo!', '¡Defenderé el vuelo!', 28153),
(159025, 'esMX', 'Por ti... emperatriz...', 'Por ti... emperatriz...', 28153),
(159024, 'esMX', 'Aplastaste a uno... pero vendrán miles...', 'Aplastaste a uno... pero vendrán miles...', 28153),
(159023, 'esMX', 'Llévenle las menas... a la emperatriz...', 'Llévenle las menas... a la emperatriz...', 28153),
(159022, 'esMX', 'Su llamado... es música...', 'Su llamado... es música...', 28153),
(159021, 'esMX', 'La oigo... incluso en mi muerte...', 'La oigo... incluso en mi muerte...', 28153),
(159020, 'esMX', 'La canción de la emperatriz... se disipa...', 'La canción de la emperatriz... se disipa...', 28153),
(159019, 'esMX', 'Somos... miles... no puedes detenernos...', 'Somos... miles... no puedes detenernos...', 28153),
(159018, 'esMX', 'Kshh... muero...', 'Kshh... muero...', 28153),
(159017, 'esMX', 'Te asesinaré, ¡y tu cadáver alimentará al enjambre!', 'Te asesinaré, ¡y tu cadáver alimentará al enjambre!', 28153),
(159016, 'esMX', 'Se nota que deseas morir...', 'Se nota que deseas morir...', 28153),
(159015, 'esMX', '¡Las menas doradas son nuestras! ¡Es un obsequio de la emperatriz!', '¡Las menas doradas son nuestras! ¡Es un obsequio de la emperatriz!', 28153),
(159014, 'esMX', '¡Somos el enjambre de la emperatriz!', '¡Somos el enjambre de la emperatriz!', 28153),
(159013, 'esMX', '¡Nadie puede detener al enjambre!', '¡Nadie puede detener al enjambre!', 28153),
(159012, 'esMX', '¡La dulce canción de nuestra emperatriz exige tu muerte!', '¡La dulce canción de nuestra emperatriz exige tu muerte!', 28153),
(159011, 'esMX', '¡La emperatriz me dirige!', '¡La emperatriz me dirige!', 28153),
(159010, 'esMX', '¡Por la emperatriz!', '¡Por la emperatriz!', 28153),
(159009, 'esMX', 'La Alianza prevalecerá... y el reinado insidioso de la Reina alma en pena terminará.', '', 28153),
(159008, 'esMX', 'Ella espera que esta atrocidad destruya nuestro espíritu. Que quiebre nuestra unidad. Pero juro que...', '', 28153),
(159007, 'esMX', '¡Rargh! Muero con honor...', '¡Rargh! Muero con honor...', 28153),
(159006, 'esMX', '¡Yargh! ¡Esta es la muerte que quiero!', '¡Yargh! ¡Esta es la muerte que quiero!', 28153),
(159005, 'esMX', 'Pero ese sueño nunca podrá hacerse realidad si Sylvanas Brisaveloz lidera la Horda.', '', 28153),
(159004, 'esMX', 'Navego... hacia el ocaso...', 'Navego... hacia el ocaso...', 28153),
(159003, 'esMX', 'Toda mi vida he rezado por que este mundo encuentre la paz.', '', 28153),
(159002, 'esMX', 'Descansaré junto a los guerreros de antaño...', 'Descansaré junto a los guerreros de antaño...', 28153),
(159001, 'esMX', 'Has demostrado valentía y corazón, adalid. En este, uno de los días más oscuros para la Alianza.', '', 28153),
(159000, 'esMX', 'Los espíritus bendicen mi muerte...', 'Los espíritus bendicen mi muerte...', 28153),
(158999, 'esMX', '', 'Descansa mientras puedas. Prepárate para las batallas que se avecinan. Te necesitaré.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'esMX', '¡Muero en una batalla gloriosa!', '¡Muero en una batalla gloriosa!', 28153),
(158997, 'esMX', 'El clan me vengará...', 'El clan me vengará...', 28153),
(158996, 'esMX', '', 'Pero ESTÁN desangrándose. En la guerra por venir, su ira demostrará ser su punto débil, no su fortaleza.', 28153),
(158995, 'esMX', 'La muerte viene a buscarlos...', 'La muerte viene a buscarlos...', 28153),
(158994, 'esMX', '¡Más miserables para conquistar!', '¡Más miserables para conquistar!', 28153),
(158993, 'esMX', '¡Otra batalla gloriosa!', '¡Otra batalla gloriosa!', 28153),
(158992, 'esMX', '¡Les arrancaré los ojos!', '¡Les arrancaré los ojos!', 28153),
(158991, 'esMX', '', 'Nuestro triunfo es parcial. La Alianza se vengará. Vendrán por nosotros. Por mí. Por ti.', 28153),
(158990, 'esMX', '', 'Este ataque debía terminar con la guerra antes de empezar... debía conquistar el hogar de un enemigo y aniquilar a sus líderes de un solo golpe. Tenía que infligir una herida que desangrara a la Alianza.', 28153),
(158989, 'esMX', '', 'Cuando te envié a cumplir esta misión, no preví este resultado.', 28153),
(158988, 'esMX', '¡Los mil barcos los llevarán hacia su perdición!', '¡Los mil barcos los llevarán hacia su perdición!', 28153),
(158987, 'esMX', '¡Mi vida por Jorun!', '¡Mi vida por Jorun!', 28153),
(158986, 'esMX', '¡Por los Regasangre!', '¡Por los Regasangre!', 28153),
(158985, 'esMX', '¡Mueran con honor!', '¡Mueran con honor!', 28153),
(158984, 'esMX', '¡Les comeré el corazón!', '¡Les comeré el corazón!', 28153),
(158983, 'esMX', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'esMX', '¿Mrrg mrgl?', '¿Mrrg mrgl?', 28153),
(158981, 'esMX', 'Rgll mgrgl... rgl...', 'Rgll mgrgl... rgl...', 28153),
(158980, 'esMX', 'Grgl...', 'Grgl...', 28153),
(158979, 'esMX', '¡Mrg!', '¡Mrg!', 28153),
(158978, 'esMX', 'Rgl... mrg...', 'Rgl... mrg...', 28153),
(158977, 'esMX', '¡Mrrrmgrl!', '¡Mrrrmgrl!', 28153),
(158976, 'esMX', '¿Mrglrgl? ¡Mrg! ¡Rgl!', '¿Mrglrgl? ¡Mrg! ¡Rgl!', 28153),
