(158771, 'esMX', 'Puedo ver... a los ancestro\'...', 'Puedo ver... a los ancestro\'...', 28153),
(158770, 'esMX', 'Los espíritu\'... me dan la bienvenida...', 'Los espíritu\'... me dan la bienvenida...', 28153),
(158769, 'esMX', 'No tienen... honor...', 'No tienen... honor...', 28153),
(158768, 'esMX', 'Agh... Lo consiguieron...', 'Agh... Lo consiguieron...', 28153),
(158767, 'esMX', 'No nos matarán... a todo\'...', 'No nos matarán... a todo\'...', 28153),
(158766, 'esMX', 'Me vengaré de ustede\'... en la otra vida...', 'Me vengaré de ustede\'... en la otra vida...', 28153),
(158765, 'esMX', 'Me uno a los espíritu\'...', 'Me uno a los espíritu\'...', 28153),
(158764, 'esMX', 'Haré un maleficio con sus hueso\', ¡y maldeciré a toda sus familia\'!', 'Haré un maleficio con sus hueso\', ¡y maldeciré a toda sus familia\'!', 28153),
(158763, 'esMX', '¡Son unos maldito\' forasteros! ¡No pertenecen a este lugar!', '¡Son unos maldito\' forasteros! ¡No pertenecen a este lugar!', 28153),
(158762, 'esMX', '', 'Parece como si hubiera sido ayer cuando nuestro chico tenía a este chico. ¡Míralo ahora!', 28153),
(158761, 'esMX', '¿Quiénes son ustede\'? No son bienvenido\' aquí, ¿entienden?', '¿Quiénes son ustede\'? No son bienvenido\' aquí, ¿entienden?', 28153),
(158760, 'esMX', 'Déjenme ver lo que tienen...', 'Déjenme ver lo que tienen...', 28153),
(158759, 'esMX', 'Las gema\' son nuestras ahora. ¡Mi clan será el más fuerte de todo\'!', 'Las gema\' son nuestras ahora. ¡Mi clan será el más fuerte de todo\'!', 28153),
(158758, 'esMX', 'No me encontrarán tan fácilmente, je, je.', 'No me encontrarán tan fácilmente, je, je.', 28153),
(158757, 'esMX', 'Esta es mi isla y esta\' son mis gema\'. ¡Aquí solo encontrarán la muerte!', 'Esta es mi isla y esta\' son mis gema\'. ¡Aquí solo encontrarán la muerte!', 28153),
(158756, 'esMX', 'Nosotro\' encontramos este lugar. ¡No nos lo robarán!', 'Nosotro\' encontramos este lugar. ¡No nos lo robarán!', 28153),
(158755, 'esMX', '¡Esta e\' nuestra isla!', '¡Esta e\' nuestra isla!', 28153),
(158754, 'esMX', '¿Qué hacen en eh\'ta isla?', '¿Qué hacen en eh\'ta isla?', 28153),
(158753, 'esMX', '¡Nos atacan, colegas! ¡Por aquí!', '¡Nos atacan, colegas! ¡Por aquí!', 28153),
(158752, 'esMX', '¡Despedácenlos, rápido!', '¡Despedácenlos, rápido!', 28153),
(158751, 'esMX', '¡Me mirarán a los ojo\' mientras los devoro!', '¡Me mirarán a los ojo\' mientras los devoro!', 28153),
(158750, 'esMX', '¡Los despellejaremo\' mientra\' respiran!', '¡Los despellejaremo\' mientra\' respiran!', 28153),
(158749, 'esMX', '¡Haré un collar con sus hueso\'!', '¡Haré un collar con sus hueso\'!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'esMX', '¡Les abriré el eh\'tómago y me beberé su sangre, colegas!', '¡Les abriré el eh\'tómago y me beberé su sangre, colegas!', 28153),
(158747, 'esMX', '¡Raggh! ¡Caigo con honor!', '', 28153),
(158746, 'esMX', 'Ustedes... son los invasores aquí... Nosotros no hicimos nada...', '', 28153),
(158745, 'esMX', 'Las gemas... no pudieron salvarnos...', '', 28153),
(158744, 'esMX', 'Regresaremos... y seremos muchos más...', '', 28153),
(158743, 'esMX', 'Las estrellas... mintieron...', '', 28153),
(158742, 'esMX', 'Oigo el llamado... de los ancestros...', '', 28153),
(158741, 'esMX', 'Los espíritus... me dan la bienvenida...', '', 28153),
(158740, 'esMX', 'Me uno... a mis ancestros...', '', 28153),
(158739, 'esMX', 'Las estrellas guían mis puños. ¡El futuro está escrito con su sangre!', '', 28153),
(158738, 'esMX', 'Los vientos me han dicho que hoy caerán en la derrota.', '', 28153),
(158737, 'esMX', '¡Espíritus! ¡Denme la fuerza de una llamarada inextinguible!', '', 28153),
(158736, 'esMX', '¡Iniciaron una lucha que no pueden ganar, insensatos!', '', 28153),
(158735, 'esMX', 'Las riquezas de esta isla son nuestras, idiotas.', '', 28153),
(158734, 'esMX', '¡Los ancestros me han dado fuerza y sabiduría!', '', 28153),
(158733, 'esMX', '¡Ungiré mis cuernos con su sangre, idiotas!', '', 28153),
(158732, 'esMX', '¡Defenderé mi clan, forasteros!', '', 28153),
(158731, 'esMX', '¡Guerreros, ayúdenme!', '', 28153),
(158730, 'esMX', '¡Reagrúpense! ¡Nos atacan!', '', 28153),
(158729, 'esMX', 'Esta es nuestra isla. ¡Aquí no tienen derecho!', '', 28153),
(158728, 'esMX', 'Las gemas brillantes son nuestras. ¡Ni se acerquen!', '', 28153),
(158727, 'esMX', '¡No nos quitarán este lugar, forasteros!', '', 28153),
(158726, 'esMX', '¡Invasores! ¡Que no se acerquen!', '', 28153),
(158725, 'esMX', '¡Los espíritus guían mi arma!', '', 28153),
(158724, 'esMX', '¡Por los ancestros!', '', 28153),
(158723, 'esMX', 'Eso... dolió...', '', 28153),
(158722, 'esMX', '¿Por qué... vienes... aquí?', '', 28153),
(158721, 'esMX', '¡Argh! En la tripa...', '', 28153),
(158720, 'esMX', 'Eres... $uun ladrón:una ladrona;...', '', 28153),
(158719, 'esMX', '¡No! Mis gemas...', '', 28153),
(158718, 'esMX', '¿Por qué... hiciste eso...?', '', 28153),
(158717, 'esMX', 'Uf... No me gusta...', '', 28153),
(158716, 'esMX', '¿Por qué veo todo negro?', '', 28153),
(158715, 'esMX', '', 'Hay quienes creen que un trato es solo un trato. Promesas falsas y careta\'. Las recompensas de eh\'te día a cambio del futuro incierto.\n\nPero debes recordar que Bwonsamdi cobrará todas las deuda\' tarde o temprano.', 28153),
(158714, 'esMX', '¡Ogros míos! ¡Hora de aplastar!', '', 28153),
(158713, 'esMX', '¡No! ¡Mis gemas! ¡Tuyas no! ¡Necesito!', '', 28153),
(158712, 'esMX', 'Las gemas nos hacen fuertes, $uinvasor:invasora;. ¡Más fuertes que tú!', '', 28153),
(158711, 'esMX', '¡Cuando terminemos con esto, yo llevar cabeza tuya como trofeo!', '', 28153),
(158710, 'esMX', '¡A ellos! ¡Rómpanles la columna!', '', 28153),
(158709, 'esMX', 'Esta isla es mía, $udebilucho:debilucha;. ¡Mía!', '', 28153),
(158708, 'esMX', '¡Te aplastaré! ¡Beberé tu sangre!', '', 28153),
(158707, 'esMX', '¡Te aplastaré y machacaré! ¡Rrawgh!', '', 28153),
(158706, 'esMX', '¡Gemas mías! ¡Rrrawgh!', '', 28153),
(158705, 'esMX', '¡No llevar nuestras cosas!', '', 28153),
(158704, 'esMX', '¡A ellos!', '', 28153),
(158703, 'esMX', '¡Tú no llevarte gemas!', '', 28153),
(158702, 'esMX', '¡Esta es mi isla! ¡Vete ahora!', '', 28153),
(158701, 'esMX', '¡Maten $ual intruso:a la intrusa;!', '', 28153),
(158700, 'esMX', '¡Aplastar, machacar, matar!', '', 28153),
(158699, 'esMX', '¡Te aplastaré!', '', 28153),
(158698, 'esMX', 'Quizá si le prometo que seré una persona mejor... ¡a diferencia de la última vez!', 'Quizá si le prometo que seré una persona mejor... ¡a diferencia de la última vez!', 28153),
(158697, 'esMX', '¿Qué crees que Bwonsamdi querría de mí?', '¿Qué crees que Bwonsamdi querría de mí?', 28153),
(158696, 'esMX', 'Qué tengo que hacer... qué tengo que hacer... ¡tiene que haber una forma de escapar!', 'Qué tengo que hacer... qué tengo que hacer... ¡tiene que haber una forma de escapar!', 28153),
(158695, 'esMX', 'Si hago un trato con Bwonsamdi, todo volverá a la normalidad, ¿cierto?', 'Si hago un trato con Bwonsamdi, todo volverá a la normalidad, ¿cierto?', 28153),
(158694, 'esMX', '¡Odio esto! ¡Odio todo!', '¡Odio esto! ¡Odio todo!', 28153),
(158693, 'esMX', '¡Esto es inaceptable! ¿Acaso no saben quién soy?', '¡Esto es inaceptable! ¿Acaso no saben quién soy?', 28153),
(158692, 'esMX', '¡Encontraré al que me hizo esto! ¡Aunque sea lo último que haga!', '¡Encontraré al que me hizo esto! ¡Aunque sea lo último que haga!', 28153),
(158691, 'esMX', '¿Cómo pudo suceder esto? ¡No es justo!', '¿Cómo pudo suceder esto? ¡No es justo!', 28153),
(158690, 'esMX', 'Nada mejorará, y no puedes convencerme de eso.', 'Nada mejorará, y no puedes convencerme de eso.', 28153),
(158689, 'esMX', 'Me iba tan bien, y mírame ahora... no soy nada.', 'Me iba tan bien, y mírame ahora... no soy nada.', 28153),
(158688, 'esMX', 'Jamás volveré a sentir el sol.', 'Jamás volveré a sentir el sol.', 28153),
(158687, 'esMX', 'Si solo hubiese tenido unos días más... habría hecho tantas cosas.', 'Si solo hubiese tenido unos días más... habría hecho tantas cosas.', 28153),
(158686, 'esMX', '¿Muerto? Nah, es solo una siesta.', '¿Muerta? Nah, es solo una siesta.', 28153),
(158685, 'esMX', '¿Quién eres? Qué más da, no debe ser tan importante.', '¿Quién eres? Qué más da, no debe ser tan importante.', 28153),
(158684, 'esMX', 'Ojos que no ven, corazón que no siente. Así de simple.', 'Ojos que no ven, corazón que no siente. Así de simple.', 28153),
(158683, 'esMX', 'Solo sigue… solo sigue… Todo saldrá bien al final...', 'Solo sigue… solo sigue… Todo saldrá bien al final...', 28153),
(158682, 'esMX', '¿Cómo te atreves a pisotear MI fortaleza? ¡Suficiente!', '', 28153),
(158681, 'esMX', 'Eres débil. ¡Enfréntame en un combate de verdad!', '', 28153),
(158680, 'esMX', '¡¿Crees que tu máquina patética podrá contra mí?!', '', 28153),
(158679, 'esMX', '¡Increíble! ¡Apareció un desafiante! ¡Aquí voy!', '', 28153),
(158678, 'esMX', 'Pero soy... demasiado bello para morir...', '', 28153),
(158677, 'esMX', '', 'Te... destriparé...', 28153),
(158676, 'esMX', '', '¡Te cortaré en tiras!', 28153),
(158675, 'esMX', 'Entiérrenme en el mar...', '', 28153),
(158674, 'esMX', '¡Te pasaré por la quilla!', '', 28153),
(158673, 'esMX', 'Uf. Este tipo. No sé qué es peor... si su uso excesivo de gel para el cabello o su poesía amateur. Pero debo admitir: Reed se apasiona por el amor... y por la lucha.', '', 28153),
(158672, 'esMX', 'Pobre Beckett, sufre delirios de grandeza.', '', 28153),
(158671, 'esMX', 'Luna es un poco... filosa, digamos.', '', 28153),
(158670, 'esMX', 'Je... Lo único cierto. Los impuestos y...', '', 28153),
(158669, 'esMX', '¿Qué tenemos aquí? ¡Parece que hay que saldar una cuenta!', '', 28153),
(158668, 'esMX', '', 'Ruego que no sea demasiado tarde, $n. Apresúrate. Encuentra a mi hija.', 28153),
(158666, 'esMX', '', 'Límite del Destino es una isla cerca de la costa de Canto Tormenta. Allí abandonan a su suerte a los peores criminales y traidores, que jamás regresan.', 28153),
(158665, 'esMX', '', '¡$n! ¿Qué descubriste?', 28153),
(158661, 'esMX', '¡Me largo de aquí! ¡Gracias por tu ayuda, $p!', '', 28153),
(158660, 'esMX', 'Kua\'fon lanza un chirrido ensordecedor y mueve la cola con mucha energía.', '', 28153),
(158659, 'esMX', 'Kua\'fon regresa la calavera a tu mano.', '', 28153),
(158658, 'esMX', 'Kua\'fon deja caer la calavera a sus pies y chilla con ganas de jugar.', '', 28153),
(158657, 'esMX', '', 'Esta guerra está perdida. Teldrassil caerá pronto.', 28153),
(158656, 'esMX', '¡Las mareas te devorarán!', '', 28153),
(158655, 'esMX', 'Ven, adalid. Debemos seguir a nuestra jefa de guerra... a la victoria.', '', 28153),
(158654, 'esMX', '', 'Eso funciona. ¡Suban todos!', 28153),
(158653, 'esMX', 'Tú también tienes una oportunidad. Llévalo a Darnassus y los dos morirán cuando la conquistemos... o huye a algún lugar lejano para que los dos puedan vivir.', '', 28153),
(158652, 'esMX', '', 'Le has perdonado la vida a Malfurion, y por eso te daré una oportunidad.', 28153),
(158651, 'esMX', '', 'Firmes.', 28153),
(158650, 'esMX', 'No es en vano. Derramamos sangre para que la Horda sobreviva.', '', 28153),
(158649, 'esMX', '', 'Toda esta guerra es deshonrosa. Cómo se atreven a derramar tanta sangre inocente... ¡en vano!', 28153),
(158648, 'esMX', 'Lo ataqué deshonrosamente. No merecía terminar con él.', '', 28153),
(158647, 'esMX', '', 'No lo mataste, orco. ¿Por qué?', 28153),
(158646, 'esMX', '', '¡Malfurion! ¡No!', 28153),
(158645, 'esMX', 'Has puesto... a tu Horda... al servicio... de la muerte. Te arrepentirás... de este día...', '', 28153),
(158642, 'esMX', '', 'Sana tus heridas y dale descanso a tus huesos. Estarás $Useguro:segura; aquí.', 28153),
(158641, 'esMX', 'Morí luchando contra la beh\'tia equivocada. Ya sabes cuál.', 'Morí luchando contra la beh\'tia equivocada. Ya sabes cuál.', 28153),
(158640, 'esMX', 'Eh\'toy igual de confundido, colega.', 'Eh\'toy igual de confundida, colega.', 28153),
(158639, 'esMX', 'El chile de Haw\'li me venció.', 'El chile de Haw\'li me venció.', 28153),
(158638, 'esMX', 'Morí corriendo en la Torcanata. ¡Y lo haría de nuevo si pudiera!', 'Morí corriendo en la Torcanata. ¡Y lo haría de nuevo si pudiera!', 28153),
(158637, 'esMX', '¿Dejarás tu cadáver en la puerta, eh?', '¿Dejarás tu cadáver en la puerta, eh?', 28153),
(158636, 'esMX', 'Me partió un rayo caminando por el Zócalo.', 'Me partió un rayo caminando por el Zócalo.', 28153),
(158635, 'esMX', 'Morí tras caer de una pirámide, y ahora no puedo recordar cómo llegué hasta ahí arriba.', 'Morí tras caer de una pirámide, y ahora no puedo recordar cómo llegué hasta ahí arriba.', 28153),
(158634, 'esMX', 'Muy bien veh\'tida, pero sin lugar a donde ir.', 'Muy bien veh\'tida, pero sin lugar a donde ir.', 28153),
(158633, 'esMX', 'Calcular la ubicación correcta donde colocar el portal en Boralus no fue fácil, ¡pero fue un desafío interesante! No olvides contarme cómo avanza, ¿sí?', '', 28153),
(158632, 'esMX', 'Como desees, Nathanos.', '', 28153),
(158631, 'esMX', 'Zelling, acompaña a $n a Boralus. Oculeth espera con un portal.', '', 28153),
(158630, 'esMX', 'Buenas, $Uhéroe:heroína;. Tenemo\' que hablar.', '', 28153),
(158629, 'esMX', 'Eh\'te es el mejor asiento de la casa... Podrás usarlo cuando me levante.', '', 28153),
(158628, 'esMX', '', '¿$p? Pff, jamás oí hablar de ti.', 28153),
(158627, 'esMX', 'Cuando estés $Ulisto:lista; para ir a las naves, Hobart está esperándote afuera para ayudarte.', '', 28153),
(158626, 'esMX', 'No digas que no te lo advertimos.', 'No digas que no te lo advertimos.', 28153),
(158625, 'esMX', '¡Atrás! Es por tu propio bien.', '¡Atrás! Es por tu propio bien.', 28153),
(158624, 'esMX', 'Kua\'fon tiembla de miedo.', '', 28153),
(158623, 'esMX', 'Las mareas nos han empezado a favorecer, ¿verdad, $n?', '', 28153),
(158622, 'esMX', 'A ti y a mí nos esperan grandes cosas.', '', 28153),
(158621, 'esMX', 'No puedes simplemente abandonarme aquí. Mis hueso\' son demasiado frágile\' para trabajar en estas minas.', 'No puedes simplemente abandonarme aquí. Mis hueso\' son demasiado frágile\' para trabajar en estas minas.', 28153),
(158620, 'esMX', 'Creo que entiendo qué nos salió mal durante la fase de fermentación.', '', 28153),
(158619, 'esMX', 'Es posible que la inserción de contaminantes inadvertidos esté teniendo un impacto en el proceso de reducción inicial.', '', 28153),
(158618, 'esMX', 'Enseguida.', '', 28153),
(158617, 'esMX', 'Haré lo que sea para ayudar.', '', 28153),
(158616, 'esMX', 'Hora de trabajar.', '', 28153),
(158615, 'esMX', 'Claro, te daré una mano.', '', 28153),
(158614, 'esMX', 'Supongo que puedo darte una mano.', '', 28153),
(158612, 'esMX', '', 'Levanta la cabeza y mira a tu alrededor. Estos árboles tienen ojos, adalid. Ciégalos.', 28153),
(158611, 'esMX', 'Tenemos que concentrarnos en estabilizar los componentes clave primero.', '', 28153),
(158610, 'esMX', '¡Ahhhh! ¡Esto explica una parte importante! \"La primera ley de la alquimia: Para obtener algo beneficioso, debe entregarse algo de valor recíproco\".', '', 28153),
(158609, 'esMX', '¡Hagámoslo!', '¡Hagámoslo!', 28153),
(158608, 'esMX', 'Interesante... la aplicación precisa del calor es clave.', '', 28153),
(158607, 'esMX', '¡Ahhh! Creo que comprendo dónde falló el catalizador.', '', 28153),
(158606, 'esMX', 'Qué extraño... no había manera de que predijéramos eso.', '', 28153),
(158605, 'esMX', 'Mmmm... qué interesante.', '', 28153),
(158604, 'esMX', 'Algunos de nuestros compañeros quedaron atrapados. ¿Quieres darles una mano?', '', 28153),
(158603, 'esMX', '¡Ey! Alguien se robó algunos de nuestros bienes. Tenemos que recuperarlos AHORA MISMO. Preferiblemente, con intereses.', '', 28153),
(158602, 'esMX', 'Ooh, heridos por TODOS LADOS. ¡Tenemos que ayudarlos!', '', 28153),
(158601, 'esMX', '¿Algún ladrón escurridizo por aquí? ¡Tengo un trabajo para darles!', '', 28153),
(158600, 'esMX', 'Escucha, si encuentras partes de triciclos de guerra por ahí, avísame. Cuando termine de repararlo, puedes ir a dar una vuelta.', '', 28153),
(158599, 'esMX', 'Veo algo que necesita una buena golpiza al estilo de Kezan.', '', 28153),
(158598, 'esMX', 'Ohh, miren el tamaño de ESA cosa. ¡Ey! ¿Quién quiere matarla?', '', 28153),
(158597, 'esMX', 'Han capturado a algunos de nuestros aliados. ¿Cómo te sientes para una operación de rescate?', '', 28153),
(158596, 'esMX', 'Las fuerzas enemigas se han escapado con suministros vitales. ¿Qué dices si les hacemos probar un poco de justicia de la Alianza?', '', 28153),
(158595, 'esMX', 'Hay soldados heridos en el campo de batalla. ¿Algún médico cerca?', '', 28153),
(158594, 'esMX', 'Sí, jovencita. Elune los acompañó. Bendijo a los druidas con la fuerza para conjurar vientos potentes que llenaran sus velas.', '', 28153),
(158593, 'esMX', '', '¿El Mar de la Bruma fue amable con ellos, shan\'do?', 28153),
(158592, 'esMX', 'Devuélveme al muelle.', 'Devuélveme al muelle.', 28153),
(158591, 'esMX', 'Envíame a la nave pequeña.', 'Envíame a la nave pequeña.', 28153),
(158590, 'esMX', 'Se buscan voluntarios para una operación encubierta peligrosa. Se requieren habilidades de sigilo y engaño.', '', 28153),
(158589, 'esMX', 'Estamos intentando rescatar una máquina de guerra del enemigo. Tráenos cualquier pieza suelta que encuentres.', '', 28153),
(158588, 'esMX', 'Ah. No podemos desaprovechar esta oportunidad.', '', 28153),
(158587, 'esMX', 'Una bestia grande y hostil ha entrado sin darse cuenta en el campo de batalla. ¡Que empiece la cacería!', '', 28153),
(158586, 'esMX', '¿Quieres saludar a mi amiguito?', '', 28153),
(158585, 'esMX', 'Sigue así y estallaré como una bomba', '', 28153),
(158584, 'esMX', 'Ey. Cálmate.', '', 28153),
(158583, 'esMX', 'Regresa en una pieza, ¿sí?', '', 28153),
(158582, 'esMX', 'Mantén los ojos abiertos.', '', 28153),
(158581, 'esMX', 'Ten cuidado allí afuera.', '', 28153),
(158580, 'esMX', '¿Qué cuentas?', '', 28153),
(158579, 'esMX', '¿Cómo te va?', '', 28153),
(158578, 'esMX', 'Qué bien te ves.', '', 28153),
(158577, 'esMX', 'Por la Luz, qué bien me vendría otro trago.', '', 28153),
(158576, 'esMX', 'Ni la paga de un oficial justifica esto.', '', 28153),
(158575, 'esMX', 'Sí, sí...', '', 28153),
(158574, 'esMX', 'Vete de aquí.', '', 28153),
(158573, 'esMX', 'Puedes retirarte.', '', 28153),
(158572, 'esMX', 'No pierdas de vista a los enemigos.', '', 28153),
(158571, 'esMX', '¿Sí?', '', 28153),
(158570, 'esMX', 'Tienes toda mi atención.', '', 28153),
(158569, 'esMX', 'Gloria a la Alianza.', '', 28153),
(158568, 'esMX', '', 'No... esto no puede ser.', 28153),
(158565, 'esMX', '', '¡Tú me ayudarás a probar los límites de mi poder!', 28153),
(158564, 'esMX', '', 'Algunos dicen que mi magia es cruel, pero solo busco explorar los límites de lo posible.', 28153),
(158563, 'esMX', 'Enraizando', 'Enraizando', 28153),
(158562, 'esMX', 'Mía... ¡MÍA! Abre los ojos, mi reina... ¡mi amor!', '', 28153),
(158561, 'esMX', 'Que su diosa los proteja.', '', 28153),
(158560, 'esMX', 'La Reina alma en pena asesinó a mi hijo. Se robó mi reino. ¡No se llevará a mi amada!', '', 28153),
(158559, 'esMX', '', 'Ellos... no irán...', 28153),
(158558, 'esMX', 'Astarii, ¡has hecho todo lo que podías! ¡Ordénales a los sacerdotes que vengan con nosotros!', '', 28153),
(158557, 'esMX', '¡No! ¡Las llevaré a las dos!', '', 28153),
(158555, 'esMX', '', 'El árbol... ¡están quemando el árbol! La niña... sálvala. Yo... no importo.', 28153),
(158554, 'esMX', '¡Ya no puedes quedarte aquí! ¡Debemos escapar por el portal!', '', 28153),
(158553, 'esMX', '', 'Astarii, no hay tiempo que perder. ¡Tenemos que evacuar esta ciudad antes de que el fuego la devore!', 28153),
(158551, 'esMX', '', 'Remátalo y termina con esto de una vez. Tómate un momento, si quieres, y luego llévate su cabeza. Te veré en el Árbol del Mundo.', 28153),
(158550, 'esMX', '', 'Mi victoria era inevitable. Solo me estaba haciendo perder el tiempo.', 28153),
(158549, 'esMX', 'No tenía por qué interferir.', '', 28153),
(158548, 'esMX', '', 'No lamentes nada. Hiciste bien.', 28153),
(158547, 'esMX', 'Fue un golpe deshonroso... Lo lamento.', '', 28153),
(158546, 'esMX', '¡¡Aaah!! ¡¿Colmillo... sauro?!', '', 28153),
(158545, 'esMX', '¡La jefa de guerra se enfrenta a Tempestira sola! Debo...', '', 28153),
(158544, 'esMX', '¿Desde el norte? ¿Cómo...? Escalaron las montañas de Frondavil. ¡Claro!', '', 28153),
(158543, 'esMX', 'Adalid, Delaryn... intercéptenlos en Auberdine. Yo iré al norte.', '', 28153),
(158542, 'esMX', 'En cualquier momento la Horda logrará pasar. Nos atacarán desde ambos flancos.', '', 28153),
(158541, 'esMX', 'Los fuegos fatuos... ¡se están desorientando! ¡El muro se quiebra!', '', 28153),
(158540, 'esMX', '', 'Ese sonido... ¿Será...? ¡Shan\'do! La Horda se acerca desde el norte.', 28153),
(158539, 'esMX', '', 'Ahora es el momento. ¡El Árbol del Mundo será nuestro! Busca a Colmillosauro. Terminaremos con esto de una vez y para siempre.', 28153),
(158537, 'esMX', '', '¡Mira a tu alrededor, $uhéroe:heroína;! Qué hermoso paisaje. Los fuegos fatuos se dispersan. Cada vez que se va uno, el muro se desmorona un poco más.', 28153),
(158536, 'esMX', '', '¡Colmillosauro! Por fin.', 28153),
(158535, 'esMX', '¡POR LA HORDA!', '', 28153),
(158534, 'esMX', '', '¿A dónde te fuiste, pajarito?', 28153),
(158533, 'esMX', '', '¡Aah! ¡Mis ojos! ¡Quema!', 28153),
(158532, 'esMX', '¡Fuera, bruja!', '', 28153),
(158531, 'esMX', '', '¿Quién habría dicho que vendrías a proteger a tus preciosos árboles?', 28153),
(158530, 'esMX', '', 'Malfurion. Qué amable de tu parte haber venido...', 28153),
(158529, 'esMX', '¡Sylvanas! Tus actos infames profanan este lugar sagrado. ¡Andu-falah-dor!', '', 28153),
(158528, 'esMX', '', 'No les daremos la satisfacción de una noche de descanso tranquilo. Estamos en guerra.', 28153),
(158527, 'esMX', '', 'Mientras tanto, haremos todo lo posible para mantener la presión sobre los kaldorei.', 28153),
(158526, 'esMX', '', 'Seguiré enviando a nuestros soldados a cruzar el muro mientras esperamos novedades de Colmillosauro.', 28153),
(158525, 'esMX', '', 'Por ahora, debemos continuar así.', 28153),
(158524, 'esMX', '', 'El conflicto en Río Culebra está estancado, y Malfurion lo sabe.', 28153),
(158523, 'esMX', '', 'Campeones de la Horda, ¡necesitamos su ayuda en Río Culebra! ¡Esta es nuestra oportunidad de triunfar!', 28153),
(158522, 'esMX', '', '...Que tengo un cuervo que cazar.', 28153),
(158521, 'esMX', '', 'Acaba pronto con este lugar. Lleva la azerita a nuestros ingenieros cuando hayas juntado toda la que puedas sostener.', 28153),
(158520, 'esMX', '', 'Esa nave debe haber venido de Darnassus... Eso significa...', 28153),
(158519, 'esMX', '', 'Avanza con cautela, adalid. Parece que la Alianza ha llegado antes que nosotros.', 28153),
(158518, 'esMX', '', 'Azerita... Con esto en nuestro poder, los que se atrevan a oponerse a la Horda caerán.', 28153),
(158517, 'esMX', '', '¡Zapadores! ¡Busquen su equipo y síganme! Traigan todas las trituradoras que encuentren.', 28153),
(158516, 'esMX', '', 'Acaba con su existencia, o bañarán el bosque con la sangre de nuestros pueblos.', 28153),
(158515, 'esMX', '', 'Veo que esto te pone nervioso. Estos ancianos se han puesto en tu contra, druida... en contra de su deber sagrado.', 28153),
(158514, 'esMX', '¡Taelia! ¡Nos vendría bien un poco de ayuda!', '', 28153),
(158513, 'esMX', 'Y con eso quiero decir \"saltar del acantilado para salvar nuestras vidas\". ¡Vamos!', '', 28153),
(158512, 'esMX', '¡Y hacer un escape teatral!', '', 28153),
(158511, 'esMX', 'Solo tenemos que tomar el cofre...', '', 28153),
(158510, 'esMX', 'Nunca me di cuenta lo duro que puede ser el sol sobre la piel que a uno le queda en el cuerpo.', 'Nunca me di cuenta lo duro que puede ser el sol sobre la piel que a uno le queda en el cuerpo.', 28153),
(158509, 'esMX', 'Te aseguro que mi plan es brillante.', '', 28153),
(158508, 'esMX', 'Me imagino que tendrás un plan para salir de este sitio con eso bajo el brazo, ¿verdad?', 'Me imagino que tendrás un plan para salir de este sitio con eso bajo el brazo, ¿verdad?', 28153),
(158507, 'esMX', 'Harlan aumentó su seguridad agregando otro candado a su caja fuerte.\n\n<Flynn se frota la barbilla.>\n\nSí. No nos queda más remedio que... robar el cofre.', '', 28153),
(158506, 'esMX', 'Bien jugado, Harlan. Bien jugado.', '', 28153),
(158505, 'esMX', 'Cien vueltas alrededor de la academia por cada cadete que encuentre.', '', 28153),
(158504, 'esMX', 'Tienen que estar aquí, en alguna parte.', '', 28153),
(158503, 'esMX', 'Nosotros nunca pedimos que nos resuciten... ni tener que soportar esto.', 'Nosotros nunca pedimos que nos resuciten... ni tener que soportar esto.', 28153),
(158502, 'esMX', '¿Cuatro cerraduras? ¿¡Cuatro!?', '', 28153),
(158501, 'esMX', '¿La Alianza se atreve a pensar que NOSOTROS somos monstruos?', '¿La Alianza se atreve a pensar que NOSOTROS somos monstruos?', 28153),
(158500, 'esMX', '¿A dónde fueron esos cadetes...?', '', 28153),
(158499, 'esMX', 'Ahhh, aquí está... La caja fuerte de Harlan Sweete.', '', 28153),
(158498, 'esMX', 'Con todo lo que ha sucedido, no puedo decir que la envidio. Pero quizás es hora de que le entregue el mando de Kul Tiras a alguien con más capacidad para gobernar.', 'Con todo lo que ha sucedido, no puedo decir que la envidio. Pero quizás es hora de que le entregue el mando de Kul Tiras a alguien con más capacidad para gobernar.', 28153),
(158497, 'esMX', 'Parece que cada día que pasa solo sirve para hacer más obvio el hecho de que Katherine está usando los logros de su difunto marido para alcanzar sus propios fines.', 'Parece que cada día que pasa solo sirve para hacer más obvio el hecho de que Katherine está usando los logros de su difunto marido para alcanzar sus propios fines.', 28153),
(158496, 'esMX', 'Otra semana sin una reunión entre las casas.', 'Otra semana sin una reunión entre las casas.', 28153),
(158495, 'esMX', 'Totalmente. Cualquier noble de Tiragarde que se precie habría tenido el sentido común de evitar un drama semejante en beneficio de la víctima.', 'Totalmente. Cualquier noble de Tiragarde que se precie habría tenido el sentido común de evitar un drama semejante en beneficio de la víctima.', 28153),
(158494, 'esMX', 'Asesinado a plena luz del día en el día de su boda. Qué falta de planificación.', 'Asesinado a plena luz del día en el día de su boda. Qué falta de planificación.', 28153),
(158493, 'esMX', '¿Sobre su prometido? Por supuesto, una pena.', '¿Sobre su prometido? Por supuesto, una pena.', 28153),
(158492, 'esMX', '¿Ya oíste lo que le sucedió a la muchacha Tarjasenda?', '¿Ya oíste lo que le sucedió a la muchacha Tarjasenda?', 28153),
(158491, 'esMX', 'Qué desgracia. ¿Qué clase de Canto Tormenta no puede invocar al mar? Si yo perteneciera a esa familia, lo habría desheredado hace muchos años.', 'Qué desgracia. ¿Qué clase de Canto Tormenta no puede invocar al mar? Si yo perteneciera a esa familia, lo habría desheredado hace muchos años.', 28153),
(158490, 'esMX', '¿Así que su tío simplemente lo envió para que seamos nosotros los que nos preocupamos por él?', '¿Así que su tío simplemente lo envió para que seamos nosotros los que nos preocupamos por él?', 28153),
(158489, 'esMX', 'He oído que Brannon ha vuelto a trabajar al Canal.', 'He oído que Brannon ha vuelto a trabajar al Canal.', 28153),
(158488, 'esMX', 'Me alivia ver que Jaina tiene los rasgos de su madre. Debo decir que Daelin no era el tipo más atractivo que he conocido.', 'Me alivia ver que Jaina tiene los rasgos de su madre. Debo decir que Daelin no era el tipo más atractivo que he conocido.', 28153),
(158487, 'esMX', '', '<Aún conserva una daga clavada en la espalda, pero se han robado el resto de sus pertenencias.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'esMX', '', '<Este cadáver zandalari parece fresco.>', 28153),
(158485, 'esMX', '<Examina el cadáver.>', '<Examina el cadáver.>', 28153),
(158484, 'esMX', 'Hace mucho tiempo que los Tarjasenda no vienen a Boralus. Me pregunto si Meredith finalmente ha comprendido que no encaja aquí.', 'Hace mucho tiempo que los Tarjasenda no vienen a Boralus. Me pregunto si Meredith finalmente ha comprendido que no encaja aquí.', 28153),
(158483, 'esMX', '¿Viste el atuendo de lord Canto Tormenta la última vez que pasó por aquí? En mi opinión, los sombreros con tentáculos ya han pasado de moda.', '¿Viste el atuendo de lord Canto Tormenta la última vez que pasó por aquí? En mi opinión, los sombreros con tentáculos ya han pasado de moda.', 28153),
(158482, 'esMX', '<Simón mira a Kunga.>\n\nEmm, sí... ¡Ja! ¡JA! Eres todo un bromista, amigo.\n\n¡Ja, ja! ¡Me descostillo!\n\nDeberías irte ahora, antes de que encuentres a otro. ¡Ja! ¡Ja!\n\nVe y mira la pelea mientras... repongo la mercadería.', '', 28153),
(158481, 'esMX', 'Encontré un cadáver detrás de la tienda.', 'Encontré un cadáver detrás de la tienda.', 28153),
(158480, 'esMX', 'Hola, eh, sí.\n\nTe doy la bienvenida a mi tienda, la tienda... de cosas... vendibles... de Simón.\n\nVendo...\n\n<Simón mira hacia atrás rápidamente.>\n\nArmas. Todo tipo de armas. Pero ahora están todas reservadas.\n\nRegresa más tarde, cuando haya... repuesto la mercadería.', '', 28153),
(158479, 'esMX', 'Los derribaré, ¡escorias de la Horda!', '', 28153),
(158478, 'esMX', '¡La Alianza no tiene ningún derecho sobre estas tierras!', '¡La Alianza no tiene ningún derecho sobre estas tierras!', 28153),
(158477, 'esMX', 'Cualquier cosa es mejor que el pan para el camino.', '', 28153),
(158476, 'esMX', 'Hemos invertido todos nuestros recursos en contener a la Horda y ganar tiempo para que nuestro pueblo pueda evacuar. Busca algo para darles de comer a nuestras centinelas.', '', 28153),
(158475, 'esMX', '', '¡Los lanzaré a las profundidades del mar!', 28153),
(158474, 'esMX', 'Eso en mi bolsillo no e\' un mojo.', '', 28153),
(158473, 'esMX', '¡Te daré una cucharada de tu propia medicina!', '', 28153),
(158472, 'esMX', '¡No me obligue\' a convertirte en un sapo!', '', 28153),
(158471, 'esMX', 'Será mejor que te detenga\'. Puede que sea viejo, pero es por eso que sé cuáles son los mejore\' maleficios.', '', 28153),
(158470, 'esMX', 'Calma, colega. No tiene\' que ser tan $utoquetón:toquetona;.', '', 28153),
(158469, 'esMX', 'He entrenado trols Lanza Negra durante generacione\'.', '', 28153),
(158468, 'esMX', 'Buena suerte, y siempre conserva un buen mojo a mano.', '', 28153),
(158467, 'esMX', '', 'Cualquier cosa es mejor que las raciones para el camino.', 28153),
(158466, 'esMX', '', 'Un ejército se mueve mejor con la panza llena, o al menos eso me han dicho. En este bosque tiene que haber algo que se pueda comer.', 28153),
(158465, 'esMX', 'Recuerda: no todo se regenera.', '', 28153),
(158464, 'esMX', '¡Cuidado!', '', 28153),
(158463, 'esMX', '¡Casi tengo lo que necesito! Un poquito más de tiempo...', '', 28153),
(158462, 'esMX', 'Mmm... estas hojas son más testarudas de lo que había previsto. Pero creo que estoy avanzando.', '', 28153),
(158461, 'esMX', 'Esto puede llevar tiempo. Sacar las hojas es un proceso delicado.', '', 28153),
(158460, 'esMX', 'Ya eh\'toy viejo para esto.', '', 28153),
(158459, 'esMX', 'Que los espíritus te guíen.', '', 28153),
(158458, 'esMX', 'Eekum bokum.', '', 28153),
(158457, 'esMX', '¿Alguien llamó a un médico?', '', 28153),
(158456, 'esMX', '¿Necesita\' mi ayuda?', '', 28153),
(158455, 'esMX', 'Hola, colega.', '', 28153),
(158454, 'esMX', 'Me gustaría que los espíritus me guíen.', 'Me gustaría que los espíritus me guíen.', 28153),
(158453, 'esMX', 'Los espíritus podrán guiarte por este lugar.', '', 28153),
(158452, 'esMX', 'Una\'fe, $n. El puesto de avanzada está a tus órdenes.', '', 28153),
(158451, 'esMX', '', 'Los has desarmado... por el momento. Mientras no les cortemos los suministros, tenemos que estar atentos.', 28153),
(158450, 'esMX', '', '¡Llénate la panza y descansa un poco!', 28153),
(158449, 'esMX', 'El sello de esta cámara protege el alma del mundo. Pero con toda la azerita que está saliendo, ¡el sello está a punto de estallar!', '', 28153),
(158448, 'esMX', 'Usa tu amuleto para absorber la azerita, ¡su poder tal vez pueda enmendar el sello de la cámara!', '', 28153),
(158447, 'esMX', '', 'Dicen que las pandillas se han apoderado de unos terribles explosivos de azerita. Si no recuperamos esos armamentos, ¡nadie estará a salvo en Boralus!', 28153),
(158446, 'esMX', 'Mi bote se hundió y cientos de hombres cayeron al mar. En una hora, aparecieron los tiburones. Pequeños, grandes, enfadados... Nos defendimos lo mejor que pudimos, pero cuando un tiburón te mira con esos ojos negros y sin vida, piensas que está muerto hasta que te muerde. El océano se tiñe de rojo, todo se vuelve oscuro y, de un momento a otro, un tiburón despedaza a alguien. Debo haber perdido a la mitad de mis hombres en la primera noche. No sé cuántos tiburones había: cien o diez, daba igual. Con el tiempo, llegó el rescate, creo que cinco días después. Casi demasiado tarde. Trescientos dieciséis hombres cayeron al mar, y solo siete salieron vivos. Los tiburones se encargaron del resto.\n\nBasta de charla. ¿Quieres luchar contra algunos tiburones?', '', 28153),
(158445, 'esMX', 'Gracias. Me arriesgaré. Préstame las botas.', 'Gracias. Me arriesgaré. Préstame las botas.', 28153),
(158444, 'esMX', '', '¡Auch! Solo estaba tratando de mover algunas cajas que... eh... se cayeron de la parte de atrás de la carreta.\n\nAl menos Coda está bien. ¡Nada puede herir a mi pequeñín!\n\nTengo un par de botas de más si necesitas regresar al norte. Aunque debo advertirte... aún no las he probado.', 28153),
(158443, 'esMX', '', 'Llegamos tarde.', 28153),
(158442, 'esMX', '', 'Ve a ver si esas personas necesitan ayuda. ¡Yo me adelantaré!', 28153),
(158441, 'esMX', '', '¡Primero tenemos que defender esa puerta!', 28153),
(158440, 'esMX', '', 'Oh, no...', 28153),
(158439, 'esMX', '', 'Ya sabemos. Descansa. Recibirá su merecido.', 28153),
(158438, 'esMX', 'Harlan... el bastardo se vendió a Aspafresno... Va a... ¡AH!', '', 28153),
(158437, 'esMX', 'Eh... en todas partes... <tose>', '', 28153),
(158436, 'esMX', '', '¡Flynn! Tranquilo. ¡Te tengo! ¿Estás bien? ¿Dónde te duele?', 28153),
(158435, 'esMX', 'Uhh... ah... ¡Ah... aaaaaah!', '', 28153),
(158434, 'esMX', '', 'Muy bien. Ven, madre. Es hora de ir a casa.', 28153),
(158433, 'esMX', '', '¡Sujétate bien!', 28153),
(158432, 'esMX', 'Estoy listo para partir.', 'Estoy lista para partir.', 28153),
(158431, 'esMX', '', 'Puedo teletransportarnos fuera de aquí cuando estés $ulisto:lista;, $c.\n\nApresúrate, no resisto un minuto más en este sitio.', 28153),
(158430, 'esMX', '¡ESCENA!', '¡ESCENA!', 28153),
(158429, 'esMX', 'Los elfos de la noche son vecinos agradables. Pero... lleva algo de tiempo acostumbrarse a esos fuegos fatuos.', '', 28153),
(158428, 'esMX', 'Usen la tierra para trabajarla. Ese fue nuestro trato.', '', 28153),
(158427, 'esMX', 'Es una pena lo que le sucedió a su árbol.', '', 28153),
(158426, 'esMX', '¿Creen que puedes impedir que recuperemos el cadáver de Derek? ¡No saben lo que les espera!', '', 28153),
(158425, 'esMX', 'Esta vez Loh solo tiene que llegar a la meta, pero debes cuidarte de los peligros que acechan en el laberinto.', '', 28153),
(158424, 'esMX', 'Ahora, ¿puedes llevar a Loh al tesoro y después a la meta sin cruzar el camino que ya ha tomado?', '', 28153),
(158423, 'esMX', 'Muy fácil, ¿no, $n?', '', 28153),
(158422, 'esMX', 'Primero, un desafío simple: lleva a Loh a la meta.', '', 28153),
(158421, 'esMX', 'Cuando contamos estas historias, les pedimos a los tortollanos jóvenes que guíen a Loh por pequeños laberintos como desafío.', '', 28153),
(158420, 'esMX', '¿Estás $Ulisto:lista; para tu instrucción de combate?', '¿Estás $Ulisto:lista; para tu instrucción de combate?', 28153),
(158419, 'esMX', '¡No dejes que te piquen las abejas, $p!', '¡No dejes que te piquen las abejas, $p!', 28153),
(158418, 'esMX', 'Los hallazgos de Loh en sus primeras exploraciones le dieron mucha confianza, y comenzó a buscar áreas más fantásticas para investigar.', '', 28153),
(158416, 'esMX', '¿Puedes llevar a Loh hasta los tesoros, y después a la salida, sin volver a cruzar el camino que ya ha tomado?', '', 28153),
(158415, 'esMX', 'Loh comenzó a explorar las ruinas antiguas que encontraba, y muchas veces descubría tesoros maravillosos.', '', 28153),
(158414, 'esMX', '\"Loh el Explorador\". A medida que Loh fue creciendo, el mundo despertó su curiosidad.', '', 28153),
(158413, 'esMX', 'La diligencia de Loh dio sus frutos. La tierra le brindó muchas cosas nutritivas para comer.', '', 28153),
(158412, 'esMX', '¿Puedes ayudar a Loh a visitar todas las plantas del jardín una vez más?', '', 28153),
(158411, 'esMX', 'Todas las mañanas visitaba las plantas de su jardín para ver cómo estaban.', '', 28153),
(158410, 'esMX', '', 'Es evidente que a los drust no les interesa mantener vivos a sus prisioneros. No podemos dejar que Jaina sufra este destino.', 28153),
(158409, 'esMX', '\"Cosecha de Loh\". A Loh le encantaba ver cómo crecían las cosas.', '', 28153),
(158408, 'esMX', 'Loh apenas pudo escapar, así que decidió seguir una vida un poco menos emocionante.', '', 28153),
(158407, 'esMX', '¿Puedes ayudar a Loh a apagar todos las baldosas luminosas y desactivar la trampa?', '', 28153),
(158406, 'esMX', '\"La curiosidad y el tortollano\". ¡Una vez, la curiosidad casi mata a Loh cuando activó una trampa zandalari antigua!', '', 28153),
(158405, 'esMX', '', '¡Suplica piedad!', 28153),
(158404, 'esMX', 'La vida en la gran ciudad no era para Loh. Decidió volver a una vida más simple.', '', 28153),
(158403, 'esMX', 'Pero no dejaba de perderse. ¿Puedes llevar a Loh a todas las tiendas y luego a la posada sin pasar por el camino que ya tomó?', '', 28153),
(158402, 'esMX', '\"La vida en la gran ciudad\". Una vez, Loh fue a una gran ciudad, muy parecida a la ciudad de Boralus.', '', 28153),
(158401, 'esMX', 'Loh decidió llevar una vida tranquila y pacífica... y la panza llena.', '', 28153),
(158399, 'esMX', '', 'He logrado capturar algunos elementales menores por estos santuarios. ¡Son fascinantes! ¿Te gustaría descubrir de lo que son capaces?', 28153),
(158398, 'esMX', 'Invitados huyen... $pr fuerte...', '', 28153),
(158397, 'esMX', 'Sigo hambriento...', '', 28153),
(158396, 'esMX', '¿Y la luz?', '', 28153),
(158395, 'esMX', 'Adiós, Gallywix...', '', 28153),
(158394, 'esMX', '¡Nada de peleas!', '', 28153),
(158393, 'esMX', '¡Primer día de trabajo! ¡Mucha suerte!', '', 28153),
(158392, 'esMX', '¡No se permiten $pr!', '', 28153),
(158391, 'esMX', '¡Es una fiesta privada!', '', 28153),
(158390, 'esMX', 'Aun así, eres $el segundo peor cliente:la segunda peor clienta;... que he tenido en el día...', 'Aun así, eres $el segundo peor cliente:la segunda peor clienta;... que he tenido en el día...', 28153),
(158389, 'esMX', 'Un goblin... con mucho hielo...', 'Un goblin... con mucho hielo...', 28153),
(158388, 'esMX', 'Última ronda... de Kaja\'Cola...', 'Última ronda... de Kaja\'Cola...', 28153),
(158387, 'esMX', 'Más te vale... que dejes una buena propina...', 'Más te vale... que dejes una buena propina...', 28153),
(158386, 'esMX', 'Nunca aprendí... a jugar... golf...', 'Nunca aprendí... a jugar... golf...', 28153),
(158385, 'esMX', 'Nunca serás más... que un doble bogey...', 'Nunca serás más... que un doble bogey...', 28153),
(158384, 'esMX', 'No me entierren con este uniforme... Es espantoso...', 'No me entierren con este uniforme... Es espantoso...', 28153),
(158383, 'esMX', 'Ya no quiero cargar estos palos...', 'Ya no quiero cargar estos palos...', 28153),
(158382, 'esMX', 'El Gran G... te hará pagar por esto...', 'El Gran G... te hará pagar por esto...', 28153),
(158381, 'esMX', 'Espera, nunca llegué... a disfrutar mi sueldo...', 'Espera, nunca llegué... a disfrutar mi sueldo...', 28153),
(158380, 'esMX', 'Espera... aún no he marcado tarjeta...', 'Espera... aún no he marcado tarjeta...', 28153),
(158379, 'esMX', 'Dile a Gallywix... que me siga pagando.', 'Dile a Gallywix... que me siga pagando.', 28153),
(158378, 'esMX', 'Apuesto a que ni siquiera das propina, $Utacaño:tacaña;.', 'Apuesto a que ni siquiera das propina, $Utacaño:tacaña;.', 28153),
(158377, 'esMX', '¡No te llevarás mi Kaja\'Cola!', '¡No te llevarás mi Kaja\'Cola!', 28153),
(158376, 'esMX', 'Te arrancaré hasta las cejas... ¡y fabricaré una cerveza!', 'Te arrancaré hasta las cejas... ¡y fabricaré una cerveza!', 28153),
(158375, 'esMX', 'Oigo algo...', 'Oigo algo...', 28153),
(158374, 'esMX', '¡La casa no invita esos tragos, colega!', '¡La casa no invita esos tragos, colega!', 28153),
(158373, 'esMX', 'Haré un hoyo en... ¡una de tus rodillas!', 'Haré un hoyo en... ¡una de tus rodillas!', 28153),
(158372, 'esMX', '<El doctor se voltea hacia ti y te habla en un susurro.>$b$bEstán muy heridos. No podemos moverlos en estas condiciones. Lo mejor que puedo hacer es sanar sus heridas e intentar escapar a toda prisa.$b$bAllí arriba es una locura...', 'n/a', 28153),
(158371, 'esMX', 'Cualquier cosa es mejor que ver cómo estos idiotas erran sus tiros todo el día.', 'Cualquier cosa es mejor que ver cómo estos idiotas erran sus tiros todo el día.', 28153),
(158370, 'esMX', '¡Para esta situación, recomiendo un hierro nueve directo a la cara!', '¡Para esta situación, recomiendo un hierro nueve directo a la cara!', 28153),
(158369, 'esMX', '¡Por fin es mi turno de golpear algo!', '¡Por fin es mi turno de golpear algo!', 28153),
(158368, 'esMX', '¡Ja! ¡Te engañé! ¡En realidad era un agente de seguridad encubierto!', '¡Ja! ¡Te engañé! ¡En realidad era un agente de seguridad encubierto!', 28153),
(158367, 'esMX', 'No te preocupes. Yo me encargo.', 'No te preocupes. Yo me encargo.', 28153),
(158366, 'esMX', '¡Aléjate de los invitados!', '¡Aléjate de los invitados!', 28153),
(158365, 'esMX', 'No me pagan lo suficiente para soportar esto.', 'No me pagan lo suficiente para soportar esto.', 28153),
(158364, 'esMX', 'Necesito tostarme... una última vez...', 'Necesito tostarme... una última vez...', 28153),
(158363, 'esMX', 'Déjame al sol... y dame vuelta antes de que me queme...', 'Déjame al sol... y dame vuelta antes de que me queme...', 28153),
(158362, 'esMX', '¡Ja! Y decían... que el sol me mataría...', '¡Ja! Y decían... que el sol me mataría...', 28153),
(158361, 'esMX', 'No, mi bello cuerpo bronceado...', 'No, mi bello cuerpo bronceado...', 28153),
(158360, 'esMX', 'Le daré mi opinión sobre esto... a Gallywix...', 'Le daré mi opinión sobre esto... a Gallywix...', 28153),
(158359, 'esMX', 'Solo quería divertirme...', 'Solo quería divertirme...', 28153),
(158358, 'esMX', 'Qué decepción... que aberración...', 'Qué decepción... que aberración...', 28153),
(158357, 'esMX', 'Pero... soy VIP...', 'Pero... soy VIP...', 28153),
(158356, 'esMX', 'Caddie, llévame... al hoyo.', 'Caddie, llévame... al hoyo.', 28153),
(158355, 'esMX', 'Al menos morí... bajo par.', 'Al menos morí... bajo par.', 28153),
(158354, 'esMX', 'Entiérrenme... en el banco de arena.', 'Entiérrenme... en el banco de arena.', 28153),
(158353, 'esMX', 'Diles... que estaba bajo par.', 'Diles... que estaba bajo par.', 28153),
(158352, 'esMX', 'La mejor fiesta... de mi vida.', 'La mejor fiesta... de mi vida.', 28153),
(158351, 'esMX', 'La peor fiesta... de mi vida.', 'La peor fiesta... de mi vida.', 28153),
(158350, 'esMX', 'Quiero... que me devuelvan el dinero.', 'Quiero... que me devuelvan el dinero.', 28153),
(158349, 'esMX', 'Solo... un trago... más...', 'Solo... un trago... más...', 28153),
(158348, 'esMX', 'No tenemos más capacidad. ¡Ve a nadar a otro lado!', 'No tenemos más capacidad. ¡Ve a nadar a otro lado!', 28153),
(158347, 'esMX', '¡Esto no es una piscina para $pr!', '¡Esto no es una piscina para $pr!', 28153),
(158346, 'esMX', '¿Has visto mi zambullida? ¡Un diez perfecto, sí!', '¿Has visto mi zambullida? ¡Un diez perfecto, sí!', 28153),
(158345, 'esMX', 'Ey, $pr. ¡Tu enorme rostro repugnante me tapa el sol!', 'Ey, $pr. ¡Tu enorme rostro repugnante me tapa el sol!', 28153),
(158344, 'esMX', 'En serio, la seguridad de Gallywix empeora cada fin de semana.', 'En serio, la seguridad de Gallywix empeora cada fin de semana.', 28153),
(158343, 'esMX', '¡No pagué extra para que me atacara $un:una; $pr horrible!', '¡No pagué extra para que me atacara $un:una; $pr horrible!', 28153),
(158342, 'esMX', 'Largo, $p. Ve a hacer tus asquerosidades lejos de la piscina.', 'Largo, $p. Ve a hacer tus asquerosidades lejos de la piscina.', 28153),
(158341, 'esMX', 'Sostén mi Kaja\'Cola. Yo me encargo.', 'Sostén mi Kaja\'Cola. Yo me encargo.', 28153),
(158340, 'esMX', '¡Fuera del green! Tus zapatos arruinarán el césped.', '¡Fuera del green! Tus zapatos arruinarán el césped.', 28153),
(158339, 'esMX', '¡Caddie, tráeme mi driver! Este será un tiro largo.', '¡Caddie, tráeme mi driver! Este será un tiro largo.', 28153),
(158338, 'esMX', '¡Haré mi próximo hoyo en uno con tu ojo!', '¡Haré mi próximo hoyo en uno con tu ojo!', 28153),
(158337, 'esMX', '¡Hay disturbios en el campo! ¡Exijo un mulligan!', '¡Hay disturbios en el campo! ¡Exijo un mulligan!', 28153),
(158336, 'esMX', 'Lárgate, $pr. ¡Estamos ocupados con tragos, comida y más tragos!', 'Lárgate, $pr. ¡Estamos ocupados con tragos, comida y más tragos!', 28153),
(158335, 'esMX', 'No me molestaría un poco más de diversión.', 'No me molestaría un poco más de diversión.', 28153),
(158334, 'esMX', '¡Seguridad! ¡Llévense a $Ueste:esta; $pr!', '¡Seguridad! ¡Llévense a $Ueste:esta; $pr!', 28153),
(158333, 'esMX', '¡No compré el paquete de debiluchos de la Alianza!', '¡No compré el paquete de debiluchos de la Alianza!', 28153),
(158332, 'esMX', 'Auchi...', '', 28153),
(158331, 'esMX', '¡Goblins... correr!', '', 28153),
(158330, 'esMX', 'Solo quería... brillante...', '', 28153),
(158329, 'esMX', 'Hice lo mejor que poder...', '', 28153),
(158328, 'esMX', 'Decir a Gran G... mí perdón...', '', 28153),
(158327, 'esMX', 'Seguir trabajando...', '', 28153),
(158326, 'esMX', 'Yo tener sueño...', '', 28153),
(158325, 'esMX', 'No parar... el oro.', '', 28153),
(158324, 'esMX', '¡No tocar!', '', 28153),
(158323, 'esMX', '¡Nuestro oro brilloso!', '', 28153),
(158322, 'esMX', 'Gran G dice aplastar a $pr.', '', 28153),
(158321, 'esMX', '¡Alejarse de goblins!', '', 28153),
(158320, 'esMX', '¡Dar oro!', '', 28153),
(158319, 'esMX', '¡Gallawick ser el mejor!', '', 28153),
(158318, 'esMX', '¡No parar de trabajar!', '', 28153),
(158317, 'esMX', '¡No demorar!', '', 28153),
(158316, 'esMX', 'Se encogerán de miedo ante el Vacío.', 'Se encogerán de miedo ante el Vacío.', 28153),
(158315, 'esMX', 'Los he visto a través del velo. Sígueme.', 'Los he visto a través del velo. Sígueme.', 28153),
(158314, 'esMX', 'Vengan, pequeños goblincitos...', 'Vengan, pequeños goblincitos...', 28153),
(158313, 'esMX', '', 'Nuestras fuerzas están reunidas en Ar\'gorok. ¡Convoca a tus aliados y conquista Stromgarde para la Horda!', 28153),
(158312, 'esMX', '<Sal y únete al ataque en Lordaeron>', '<Sal y únete al ataque en Lordaeron>', 28153),
(158311, 'esMX', 'Las sorpresas continuarán hasta que mejore el estado de ánimo.', '', 28153),
(158310, 'esMX', 'Esta será una historia muy graciosa para contar a tus amigos.', '', 28153),
(158309, 'esMX', 'Preparen las cámaras. En tres... dos... uno...', '', 28153),
(158308, 'esMX', 'Iniciando buenos tiempos.', '', 28153),
(158307, 'esMX', 'Solicitud de sorpresa recibida. Procediendo sin pensar.', '', 28153),
(158306, 'esMX', 'Debe excederse el nivel máximo de diversión.', '', 28153),
(158305, 'esMX', 'No se tolerarán invitados aburridos.', '', 28153),
(158304, 'esMX', 'Falta de diversión detectada. Corrigiendo.', '', 28153),
(158303, 'esMX', '', 'Te contaré cuando la guerra haya terminado...', 28153),
(158302, 'esMX', 'Olvídalo.', 'Olvídalo.', 28153),
(158301, 'esMX', 'Sí.', 'Sí.', 28153),
(158300, 'esMX', '', '¿Estamos por llegar a un importante punto de reunión de la Horda y tú quieres saber por qué tengo una botella que puede volverme invisible?', 28153),
(158299, 'esMX', '¿Por qué tienes un frasco de invisibilidad?', '¿Por qué tienes un frasco de invisibilidad?', 28153),
(158298, 'esMX', 'Shh, sal de aquí. Harás que me descubran.', '', 28153),
(158297, 'esMX', 'Llévame a la nave insignia.', 'Llévame a la nave insignia.', 28153),
(158296, 'esMX', '¡Si necesitas que te lleve hasta esos barcos, no dudes en pedírmelo!', '', 28153),
(158295, 'esMX', '¡Ese enorme árbol viejo es toda una maravilla!', '', 28153),
(158294, 'esMX', '¡Pagarás por inquietar a Vog\'rish!', '', 28153),
(158293, 'esMX', '¡Eso nunca le había pasado a Vog\'rish!', '', 28153),
(158292, 'esMX', '¡Raaaaagh! ¡Vog\'rish está avergonzado!', '', 28153),
(158291, 'esMX', 'Ciertamente los elfos tienen habilidad para cultivar.', '', 28153),
(158290, 'esMX', '¡Te mostraré el verdadero poder de Vog\'rish!', '', 28153),
(158289, 'esMX', '¡Prepárense para el infierno, débiles!', '', 28153),
(158288, 'esMX', '¡No más ogro bueno!', '', 28153),
(158287, 'esMX', 'Es bueno contar con un poco más de ayuda.', '', 28153),
(158286, 'esMX', '', 'Shandris... tienes que... sobrevivir...', 28153),
(158285, 'esMX', '', 'Por... mi... gente...', 28153),
(158284, 'esMX', '¡Vog\'rish te quema los pies!', '', 28153),
(158283, 'esMX', '¡La magia de Vog\'rish está fuera de control!', '', 28153),
(158282, 'esMX', '', '¡Únete a mí en la muerte!', 28153),
(158281, 'esMX', '¡Contempla el poder magnífico!', '', 28153),
(158280, 'esMX', 'Ah, justo a tiempo.', '', 28153),
(158279, 'esMX', '', 'Parece que no tendrás que esperar mucho más, Nathanos.', 28153),
(158278, 'esMX', '', '¡Son tan brillantes! Yo digo que esta grande está bendecida por los maresabios y esta que tiene forma de espiral es de un cofre del tesoro pirata!', 28153),
(158277, 'esMX', '', 'Menos fuegos fatuos lastimando a nuestros soldados. Bien hecho.', 28153),
(158276, 'esMX', '', 'Debemos despejar esta área para que nuestras tropas puedan pasar sin problemas. No subestimes a los fuegos fatuos: son letales en grandes cantidades.', 28153),
(158275, 'esMX', '', 'No creerías las cosas extrañas que puedes pescar aquí abajo. He capturado algunas criaturas exóticas en los últimos días. ¿Te interesaría luchar contra ellas?', 28153),
(158274, 'esMX', 'Lilian no deja de decirme que la Horda es una familia.\n\nAhora que mi verdadera familia no me acepta... honestamente, no me vendría mal un poco de apoyo emocional.\n\nPero a cambio, Lilian me ha garantizado la seguridad de mi familia. Y si para eso debo ayudar a la Horda...\n\nEntonces es exactamente lo que haré.', '', 28153),
(158273, 'esMX', '', '¡Nos largamo\' de aquí!', 28153),
(158272, 'esMX', '', '¡Caracolas a la venta! Las más bonitas de todo Kul Tiras. Un momento... ¡de Azeroth! ¡Las más bonitas de todo Azeroth!', 28153),
(158271, 'esMX', '', 'Estoy empezando a entrar en razón, $n.\n\nCon la ayuda de Lilian, quizá pueda aceptar mi nuevo destino.\n\nAunque debo decir que... cuanto más pueda sacar de Kul Tiras... mejor.', 28153),
(158270, 'esMX', 'Agradezco esta oportunidad de demostrar el valor de los ren\'dorei para nuestra causa.\n\nHaremos todo lo necesario para que la Alianza triunfe.', '', 28153),
(158269, 'esMX', '', 'Hasta el momento, el alto comandante Aterravermis me ha causado una muy buena impresión.\n\nUtiliza una amplia variedad de tácticas y se adapta rápidamente a circunstancias cambiantes con estrategias apropiadas y necesarias.\n\nLos esfuerzos de guerra de la Alianza están en manos capaces. Como tú, estoy orgullosa de participar en ellos.', 28153),
(158268, 'esMX', '', 'Debemos erradicar a los san\'layn. La imprudencia de la Horda nos pone en peligro a todos.', 28153),
(158267, 'esMX', 'Pronto lo verás. ¡Fuego! ¡Sí, mucho fuego!', '', 28153),
(158266, 'esMX', 'Te volveré a llamar cuando te necesitemos. Por la Alianza.', '', 28153),
(158265, 'esMX', 'Debemos informar al rey Anduin de inmediato. Hemos terminado nuestra tarea aquí, pero nuestra misión acaba de comenzar.', '', 28153),
(158264, 'esMX', '¿La Horda está usando a esos elfos vampíricos? Qué bajo han caído.', '', 28153),
(158263, 'esMX', '¡No se me subieron los humos a la cabeza!', '', 28153),
(158262, 'esMX', 'Por lo que me describes, pareces estar hablando de un san\'layn... un príncipe de sangre.', '', 28153),
(158261, 'esMX', '', '¿G-Guzzy está muerto?', 28153),
(158260, 'esMX', 'Donde hay humo, hay fuego... ¡créeme!', '', 28153),
(158259, 'esMX', 'Es hora de pasar al próximo paso de nuestro plan.', '', 28153),
(158258, 'esMX', 'Tenemos el cadáver de Derek Valiente. No necesitamos recuperar más cuerpos de kultiranos. Por ahora.', '', 28153),
(158257, 'esMX', 'Esperemos que tu esfuerzo no haya sido en vano.', '', 28153),
(158256, 'esMX', 'La guerra ha llegado hasta Costa Oscura. Debemos proteger a nuestra gente de la mejor manera posible. Dirige a todos los fuegos fatuos que veas hacia las líneas de vanguardia y elimina cualquier amenaza.', '', 28153),
(158255, 'esMX', '', '¡Ja! ¡Oí el grito de un traidor atascado!', 28153),
(158254, 'esMX', '', 'Descanso para los agotado\', comida para los hambriento\'.', 28153),
(158253, 'esMX', '', 'No accedí a que atrajeran la flota kultirana a mi muelle.\n\nMás vale que tengas un buen plan. Me niego a perder la libertad.', 28153),
(158252, 'esMX', 'Comienza el ritual.', 'Comienza el ritual.', 28153),
(158251, 'esMX', '¿De dónde eres?', '¿De dónde eres?', 28153),
(158250, 'esMX', '¿Cuánto hace que estás aquí?', '¿Cuánto hace que estás aquí?', 28153),
(158249, 'esMX', 'Este es el único hogar que conozco.\n\nVamos a donde nos lleven las arenas.', 'Este es el único hogar que conozco.\n\nVamos a donde nos lleven las arenas.', 28153),
(158248, 'esMX', 'Mi caravana considera estas arenas como su hogar desde antes que yo naciera. \n\nMás allá del mar hay otros, aunque yo nunca los he visto.', 'Mi caravana considera estas arenas como su hogar desde antes que yo naciera. \n\nMás allá del mar hay otros, aunque yo nunca los he visto.', 28153),
(158247, 'esMX', 'Tonterías. Tú y tu pueblo se desenvolvieron maravillosamente, magíster. Son un orgullo para la Alianza.', '', 28153),
(158246, 'esMX', 'En nombre de todos los elfos del Vacío, pido disculpas por nuestro fracaso.', '', 28153),
(158245, 'esMX', '', 'Tenemos que llegar a Colina de la Vigilia. ¡Rápido, sube!', 28153),
(158244, 'esMX', 'Kua\'fon pía satisfecho y se acurruca para dormir.', '', 28153),
(158243, 'esMX', 'El aldeano gime de dolor.', 'El aldeano gime de dolor.', 28153),
(158242, 'esMX', '¡Mok\'rah, $n! El puesto de avanzada está a tus órdenes.', '', 28153),
(158241, 'esMX', '', 'Mmm.', 28153),
(158240, 'esMX', 'Te pagaremos muy bien por el inconveniente.', '', 28153),
(158239, 'esMX', '', 'Nathanos, te dije que tu Horda podía establecerse en mi muelle. ¡No te di permiso para atraer a la flota Valiente hasta mi puerta!', 28153),
(158238, 'esMX', 'El cetro es un artefacto con inmenso poder sobre el mar. Podremos utilizarlo para sacarle una buena ventaja a la flota kultirana.', '', 28153),
(158237, 'esMX', '', '¿Cómo piensas escabullirte? No puedes pasearte por la entrada principal como si nada...', 28153),
(158236, 'esMX', 'Envié a Valentine a Boralus para que le entregue un mensaje a Lady Valiente a cualquier costo: \"Tenemos a tu hijo\".', '', 28153),
(158235, 'esMX', 'Calma, amigos. Les aseguro que este pirata pagará por sus crímenes. Pero debemos esperar la sentencia final de los tribunales.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'esMX', 'Nuestra misión es recuperar el cetro abisal Abyssal que se encuentra en las profundidades del Monasterio de Canto Tormenta en Boralus.', '', 28153),
(158233, 'esMX', '', 'Pasa, $n. Nathanos te pondrá al día.', 28153),
(158232, 'esMX', 'Por el delito de usura, los tribunales te han declarado culpable. Tus préstamos rapaces despojaron a muchas buenas personas de Punta Garfio de sus ahorros. Muchos de ellos ahora están en la calle por tus fechorías.', '', 28153),
(158231, 'esMX', 'Por los delitos de piratería, robo y asesinato, los tribunales te han declarado culpable. La piratería es uno de los delitos más viles según la ley kultirana, y se hará justicia.', '', 28153),
(158230, 'esMX', '¡Extorsión y chantaje! Muchas de las familias presentes han sido víctimas de tus maniobras. Le has costado muy caro al pueblo de Kul Tiras, y ahora deberás pagar por los crímenes cometidos.', '', 28153),
(158229, 'esMX', 'Síganme. Los llevaré con Alleria y al alto comandante directamente.', '', 28153),
(158228, 'esMX', 'No es la victoria total que esperaba conseguir para la Alianza, pero no sumaré demora a mis fracasos.', '', 28153),
(158227, 'esMX', '¿Todo este tiempo estuvimos cazando a un Gallywix falso? Los goblins son lo peor de lo peor.', '', 28153),
(158226, 'esMX', '¡Nos vemos luego, perdedores!', '', 28153),
(158225, 'esMX', 'Aunque esos trajes mecánicos no son baratos, $p. ¡Te enviaré la factura de este!', '', 28153),
(158224, 'esMX', 'Cayeron en el truco más viejo de Pantoque: ¡obreros de excelente calidad y salario paupérrimo!', '', 28153),
(158223, 'esMX', '¡Ja! Ojalá pudieran ver sus rostros ahora mismo.', '', 28153),
(158222, 'esMX', '', 'La idea de que un eh\'píritu pueda evadir a Bwonsamdi es impresionante. Tengo la esperanza de que los lazo\' de sus amigo\' sean suficientes para conectarnos con él en el otro lado.', 28153),
(158221, 'esMX', '$n, hay un telescopio en el lado oeste del campamento. ¿Por qué no vas a buscarlo?', '', 28153),
(158220, 'esMX', 'Mmm... Sí, ¿dónde está Guzbert? Debería aparecer por esa esquina en cualquier momento.', '', 28153),
(158219, 'esMX', '', '¿Soy la primera en regresar? ¿Dónde está Guzzy?', 28153),
(158218, 'esMX', 'Bienvenida una vez más, señorita Chispacero.', '', 28153),
(158217, 'esMX', '', '¡Ey, jefe! ¿Oyó esa explosión? Creo que acabo de poner a un goblin en órbita.', 28153),
(158216, 'esMX', 'Guzbert y Kelsey deberían llegar en cualquier momento.', '', 28153),
(158215, 'esMX', 'Eh, ¿y el mundo qué ha hecho por mí?', '', 28153),
(158214, 'esMX', 'Tu ego está más inflado que tu cuerpo. ¡Piensa en todo el bien que podrías haberle hecho a este mundo!', '', 28153),
(158213, 'esMX', 'Has acumulado riquezas incontables, ¿y esto es lo que construyes, Gallywix? ¡Un basurero de depravación!', '', 28153),
(158212, 'esMX', '', 'Usa Vivificar para recuperar tu salud por completo.', 28153),
(158211, 'esMX', 'Usa Vivificar para recuperar tu salud por completo.', '', 28153),
(158210, 'esMX', '', 'Recibir daño es parte de un combate, pero puedes usar las nieblas espirituales para sanarte a ti o a un aliado. Usa Vivificar para sanar tus heridas.', 28153),
(158209, 'esMX', 'Recibir daño es parte de un combate, pero puedes usar las nieblas espirituales para sanarte a ti o a un aliado. Usa Vivificar para sanar tus heridas.', '', 28153),
(158208, 'esMX', '¡La Alianza ha sido derrotada!', '', 28153),
(158207, 'esMX', '|A:Warfront-HordeWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Horda!', '|A:Warfront-HordeWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Horda!', 28153),
(158206, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Paso Valeroso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Paso Valeroso!', 28153),
(158205, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Granovel!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Granovel!', 28153),
(158204, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de Elementos!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de Elementos!', 28153),
(158203, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Alto Pedestal!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Alto Pedestal!', 28153),
(158202, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Hemos perdido Cruce Redilnorte!', 28153),
(158201, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Hemos perdido Filón de Galson!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Hemos perdido Filón de Galson!', 28153),
(158200, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Aserradero de Tierras Altas!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Aserradero de Tierras Altas!', 28153),
(158199, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Están atacando Filón de Galson!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Están atacando Filón de Galson!', 28153),
(158198, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Están atacando Aserradero de Tierras Altas!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Están atacando Aserradero de Tierras Altas!', 28153),
(158197, 'esMX', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', 28153),
(158196, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Paso Valeroso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Paso Valeroso!', 28153),
(158195, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Granovel!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Granovel!', 28153),
(158194, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de Elementos!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de Elementos!', 28153),
(158193, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Cruce Redilnorte!', 28153),
(158192, 'esMX', 'Apretar el gran botón rojo cuando me des la señal. Entendido.', 'Apretar el gran botón rojo cuando me des la señal. Entendido.', 28153),
(158191, 'esMX', 'Muéstrame adónde puedo ir volando.', 'Muéstrame adónde puedo ir volando.', 28153),
(158190, 'esMX', '¿Quieres volar a algún lado?', '', 28153),
(158189, 'esMX', '¡Otra subasta perdida! ¿Por qué buscamos beneficiarnos con la miseria de los demás?', '¡Otra subasta perdida! ¿Por qué buscamos beneficiarnos con la miseria de los demás?', 28153),
(158188, 'esMX', 'No nos queda nada de valor para vender.', 'No nos queda nada de valor para vender.', 28153),
(158187, 'esMX', 'Espero que tengamos suficiente para comprar los suministros que necesitamos.', 'Espero que tengamos suficiente para comprar los suministros que necesitamos.', 28153),
(158186, 'esMX', '¿Cuánto oro nos queda?', '¿Cuánto oro nos queda?', 28153),
(158185, 'esMX', 'No hay suficientes raciones...', 'No hay suficientes raciones...', 28153),
(158183, 'esMX', 'Ten cuidado en el camino, $Uviajero:viajera;. Algo extraño acecha en las sombras de Drustvar.', 'Ten cuidado en el camino, $Uviajero:viajera;. Algo extraño acecha en las sombras de Drustvar.', 28153),
(158182, 'esMX', 'Espera... momento... ¡El traje está fallando!', '', 28153),
(158181, 'esMX', '¡Los cuervos nos vigilan! ¡La risa no se detiene! Vendrán por mí!', '', 28153),
(158180, 'esMX', '', 'Me hiciste... derramar... el trago...', 28153),
(158179, 'esMX', '', '¿Crees que puedes engañarme a MÍ?! ¡Te <hip> destriparé!', 28153),
(158178, 'esMX', '', 'Bien hecho. Te veo del otro lado del campamento.', 28153),
(158177, 'esMX', '¡Mira esto, Gallywix!', '¡Mira esto, Gallywix!', 28153),
(158176, 'esMX', '¿La Alianza? ¿Aquí? ¿En Zandalar?', '', 28153),
(158175, 'esMX', 'Nos movemos al compás de las arenas.', 'Nos movemos al compás de las arenas.', 28153),
(158174, 'esMX', 'Las dunas están llenas de tesoros a la espera de que alguien los encuentre.', 'Las dunas están llenas de tesoros a la espera de que alguien los encuentre.', 28153),
(158173, 'esMX', 'El hogar está donde está tu carreta.', 'El hogar está donde está tu carreta.', 28153),
(158171, 'esMX', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t¡%s te marca como objetivo de |cFFFF0000|Hspell:271296|h[Cayada violenta]|h|r!', '', 28153),
(158170, 'esMX', '', 'Pobres almas... nadie debería tener que soportar esto. Después de salvar a Jaina debemos encontrar la forma de volver por ellos.', 28153),
(158169, 'esMX', 'De algo no hay dudas, y es que el caos reina en Drustvar.', 'De algo no hay dudas, y es que el caos reina en Drustvar.', 28153),
(158168, 'esMX', 'Uno dijo algo sobre los ciervos devoran la carne de los hombres.', 'Uno dijo algo sobre los ciervos devoran la carne de los hombres.', 28153),
(158167, 'esMX', '¿Sobre los hombres bestia y los demonios de madera? Sí, los oí hablar sobre eso.', '¿Sobre los hombres bestia y los demonios de madera? Sí, los oí hablar sobre eso.', 28153),
(158166, 'esMX', '¿Oíste lo que decían? ¿Por qué están aquí esos refugiados?', '¿Oíste lo que decían? ¿Por qué están aquí esos refugiados?', 28153),
(158165, 'esMX', 'Hay días en los que pienso que puedo improvisar algunos zumbidos con la boca y comunicarme con mis abejas, pero no podré lograr mi objetivo hasta que termine de crear mi disfraz de abeja... aunque eso no viene al caso, ¿verdad? Mis abejas son las mejores de este lugar. ¿Quieres luchar contra ellas o te irás volando de aquí?', '', 28153),
(158164, 'esMX', '', 'Que nuestra voluntad sea más fuerte que sus máquinas de guerra.', 28153),
(158163, 'esMX', 'Los kaldorei no olvidarán tus hazañas, $n. La ayuda que nos brindaste en estos tiempos oscuros podría marcar una verdadera diferencia.', '', 28153),
(158162, 'esMX', 'Aunque nos enfrentamos a una prueba difícil, no podemos darnos por vencidos. La diosa nos da fuerza y tenemos que aferrarnos a ella.', '', 28153),
(158161, 'esMX', 'Ninguna guerra se gana ni se pierde en una sola batalla. Nuestro día llegará.', '', 28153),
(158160, 'esMX', 'El rey Anduin enviará sus soldados a ayudarnos. Tenemos que resistir hasta que lleguen.', '', 28153),
(158159, 'esMX', 'Nuestra flota ha regresado de Silithus. ¡Alabada sea Elune! Necesitábamos su fuerza más que nunca.', '', 28153),
(158158, 'esMX', 'El muro de fuegos fatuos aún resiste, pero la Horda está llegando a Costa Oscura.', '', 28153),
(158157, 'esMX', 'Fue un golpe a la moral. Nunca subestimes el valor de la guerra psicológica.', '', 28153),
(158156, 'esMX', 'Le diste un buen discurso a Nathanos.', 'Le diste un buen discurso a Nathanos.', 28153),
(158155, 'esMX', 'Los piratas de Puerto Libre son cada día más valientes. Tenemos que sembrar el caos entre sus filas. ¡Usa una de sus monturas para lanzar un diluvio de mugre sobre ellos!', '', 28153),
(158154, 'esMX', '', 'Todos los marineros temen el canto de las sirena\'. Algunos no le temen lo suficiente.', 28153),
(158153, 'esMX', '', 'Las sirena\' han atrapado otra nave de suministros kultirana. Busca cosa\' que puedan servirnos en el naufragio... ¡pero cuídate de no terminar como la tripulación!', 28153),
(158152, 'esMX', 'Los espera un destino mucho peor que la muerte...', '', 28153),
(158151, 'esMX', '¡¿Creen que han ganado?! ¡Mi caída es solo el comienzo de su perdición!', '', 28153),
(158150, 'esMX', 'Bien hecho. Nuestros enemigos no estarán armados para desafiarnos.', '', 28153),
(158149, 'esMX', 'Los kultiranos no deben producir más municiones de azerita. ¡Detén la producción de esa forja!', '', 28153),
(158148, 'esMX', '', 'Cuando los fanáticos dudan de tu lealtad, significa que tu fin está cerca.\n\nA mí me obligaron a participar en esta campaña. Quizás a ti también. Tenemos que hacer y decir todo lo que sea necesario para sobrevivir.\n\nPero debes saber esto: sola una guerra importa. Y no es esta.', 28153),
(158147, 'esMX', 'Compartirás... su destino...', '', 28153),
(158146, 'esMX', 'Llegas... demasiado tarde... para salvarla...', '', 28153),
(158145, 'esMX', 'El tormento... los espera a todos...', '', 28153),
(158144, 'esMX', 'Ya está... condenada...', '', 28153),
(158143, 'esMX', '¡La venganza está cerca!', '', 28153),
(158142, 'esMX', '¡Valiente es nuestra!', '', 28153),
(158141, 'esMX', '¡A ti también te consumirán!', '', 28153),
(158140, 'esMX', '¡Sufrirás junto a ella!', '', 28153),
(158139, 'esMX', '', 'He trabajado en este sitio durante el tiempo suficiente para encontrar ciertas manifestaciones interesantes de este material al que llaman azerita. ¿Quieres probar suerte y luchar contra algunos elementales de azerita solitarios que he descubierto allí abajo?', 28153),
(158138, 'esMX', '¡IMBÉCILES! ¡Jamás comprenderán el poder al que se enfrentan!', '', 28153),
(158137, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Alto Pedestal!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Están atacando Alto Pedestal!', 28153),
(158136, 'esMX', '', 'No exactamente. Cuando ves una oportunidad, debes aprovecharla.\n\nSiempre he tenido planes para mi futuro. Ya era hora de que trabajara para hacer realidad esos planes.', 28153),
(158135, 'esMX', 'Pensé que estabas al servicio de los Descoronados. ¿Cambiaste de bando?', 'Pensé que estabas al servicio de los Descoronados. ¿Cambiaste de bando?', 28153),
(158134, 'esMX', '¡Soy LIBRE! Gracias... ¡ahora sus almas saciarán mi hambre infinito!', '', 28153),
(158133, 'esMX', 'Tú decides qué región visitaremos primero. Cuando hayas elegido una, partiremos.', '', 28153),
(158132, 'esMX', '', 'Buen trabajo. Los guardias pueden encargarse de los rezagados. Tenemos que vigilar la mansión de cerca.', 28153),
(158131, 'esMX', '', '¡Cientos de abominaciones han comenzado a salir de la Mansión Tarjasenda! ¡Debemos detener su avance antes de que lleguen a Alto de Arom!', 28153),
(158129, 'esMX', 'Ganaremos esta guerra, $n. ¡Por la Alianza!', '', 28153),
(158128, 'esMX', 'Busca objetivos desprevenidos en las tierras de los trols. Debilita los esfuerzos de la jefa de guerra en cada oportunidad.', '', 28153),
(158127, 'esMX', 'Las posiciones que aseguraste en Zandalar fueron un excelente primer paso. Ahora, ¡las usaremos para llevar la lucha a la Horda!', '', 28153),
(158126, 'esMX', 'Las mareas de guerra cambian constantemente. Es hora de cambiar la filosofía de nuestra campaña.', '', 28153),
(158125, 'esMX', 'Jamás me he sentido tan hambriento...', 'Jamás me he sentido tan hambriento...', 28153),
(158124, 'esMX', 'Adalid, tu trabajo en Kul Tiras ha sido vital para nuestra causa. La Alianza solo se fortalecerá si se une.', '', 28153),
(158123, 'esMX', '¡Por la Alianza!', '', 28153),
(158122, 'esMX', 'Pero al menos por ahora, debes saber que eres una inspiración para los que te rodean. Y por eso, estoy muy agradecido.', '', 28153),
(158121, 'esMX', 'La Alianza debe pedirte aún más, $n. No podemos acabar con el reinado de la jefa de guerra hasta que cortemos su vínculo con los zandalari. Ese día llegará... pronto.', '', 28153),
(158120, 'esMX', 'Quisiera decir que hemos terminado nuestro trabajo, pero queda mucho por delante. Temo que los días serán cada vez más oscuros... hasta que encontremos la luz.', '', 28153),
(158119, 'esMX', 'Adalid, has encabezado una extensa campaña contra un enemigo implacable. Además, enfrentaste a la Horda con valentía... y honor.', '', 28153),
(158118, 'esMX', '', '¡Por la Horda!', 28153),
(158117, 'esMX', '', 'Representas lo mejor de la Horda, $n. Sé que serás la chispa que haga arder a Boralus.', 28153),
(158116, 'esMX', '', 'Kul Tiras se ha convertido en un punto de reunión de la Alianza. El regreso de su aclamada armada los ha envalentonado. Pronto, esos marinos mugrientos pagarán por desafiarnos.', 28153),
(158115, 'esMX', '', 'Aunque aún no hemos alcanzado la victoria, cada día está más cerca. No descansaremos hasta que el niño rey pierda el último atisbo de esperanza que habita en su corazón.', 28153),
(158114, 'esMX', '', 'El mundo está repleto de soldados, adalid. Pero solo unos pocos tienen agallas para la guerra. Parece que en ti eso es innato.', 28153),
(158113, 'esMX', '', 'Quítales toda esperanza y te quedarás con la victoria, $n. ¡Por la Horda!', 28153),
(158112, 'esMX', '', 'Usa las posiciones que aseguraste en Kul Tiras para diezmar las fuerzas del niño rey. Sacude la fe que tienen en su causa.', 28153),
(158111, 'esMX', '', 'Pero para alcanzar la victoria no basta con fortalecernos. Debemos debilitar a nuestro enemigo hasta que quede de rodillas.', 28153),
(158110, 'esMX', '', 'Sabía que no había nadie más capaz que tú para sumar a los zandalari a nuestra causa.', 28153),
(158109, 'esMX', '', 'Adalid, cuando la princesa Talanji vino en busca de ayuda, vi la oportunidad de sumar a su reino para fortalecer el nuestro.', 28153),
(158108, 'esMX', 'Aquí hasta la tierra está muerta. Esto e\' siniestro, colega. Muy siniestro.', '', 28153),
(158107, 'esMX', '', 'Calienta tus manos y dales respiro a tus huesos, $c.', 28153),
(158106, 'esMX', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t ¡%s comienza a lanzar |cFFFF0000|Hspell:273361|h[Charco de oscuridad]|h|r!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t ¡%s comienza a lanzar |cFFFF0000|Hspell:273361|h[Charco de oscuridad]|h|r!', 28153),
(158105, 'esMX', 'Te doy la bienvenida a Puesto Vientorraudo, $n. El puesto de avanzada está a tus órdenes.', '', 28153),
(158104, 'esMX', 'Debí... comprar... la opción con garantía...', '', 28153),
(158103, 'esMX', '¡$UBienvenido:Bienvendida; al palacete del DOLOR de Gallywix, $Uladrón:ladrona; repugnante!', '', 28153),
(158102, 'esMX', 'Pídele a Fozruk que ataque Ar\'gorok.', 'Pídele a Fozruk que ataque Ar\'gorok.', 28153),
(158101, 'esMX', 'La corrupción se propaga más rápido de lo que había imaginado...', '', 28153),
(158100, 'esMX', 'Estas esporas no son naturales. Tenemos que encontrar su origen.', '', 28153),
(158099, 'esMX', 'Hicimos lo que pudimos. Ojalá encuentren la paz en la otra vida.', '', 28153),
(158098, 'esMX', 'Los espíritus se impacientan. Debemos poner fin a su tormento.', '', 28153),
(158097, 'esMX', '', 'Bien hecho. Eh\'pero que encuentren la paz.', 28153),
(158096, 'esMX', '', 'Los eh\'píritus se impacientan. Ayúdalos a encontrar la paz.', 28153),
(158095, 'esMX', '', 'Con estas eh\'poras podemos encontrar el origen de la podredumbre y deh\'truirla.', 28153),
(158094, 'esMX', '', 'La podredumbre se propaga rápido. Tenemo\' que detenerla. Recoge las eh\'poras para aprender más.', 28153),
(158093, 'esMX', '¡Hermanos y hermanas! ¡La Horda se abre paso por la Costa Oscura! Todos a Río Culebra.', '', 28153),
(158092, 'esMX', '¡Te han insuflado el poder del viento en las venas!', '¡Te han insuflado el poder del viento en las venas!', 28153),
(158091, 'esMX', 'Quiero que lleven todo este oro al palacio DE INMEDIATO y...', '', 28153),
(158090, 'esMX', '¡Nada de demoras! ¡Nada de excusas! ¡Nada de aumentos de sueldo!', '', 28153),
(158089, 'esMX', '¡Fuera de mi camino! ¡La Alianza ha llegado!', '', 28153),
(158088, 'esMX', 'No moriré... en manos de un goblin.', '', 28153),
(158087, 'esMX', 'La Alianza cuenta con los elfos del Vacío. No los decepcionaremos.', '', 28153),
(158086, 'esMX', '¡Gallywiiiiix!', '¡Gallywiiiiix!', 28153),
(158085, 'esMX', '¡Rayos! ¡Es la Alianza!', '¡Rayos! ¡Es la Alianza!', 28153),
(158084, 'esMX', '', 'La Horda debe haber expulsado a los fúrbolgs de su hogar.', 28153),
(158083, 'esMX', '', 'La Horda... son tantos...', 28153),
(158082, 'esMX', '¡Santas monedas de oro! ¡¿De dónde salió $Uese elfo:esa elfa;?!', '¡Santas monedas de oro! ¡¿De dónde salió $Uese elfo:esa elfa;?!', 28153),
(158081, 'esMX', '', 'Los fúrbolgs suelen ser una tribu pacífica. Deben estar alterados porque los expulsaron de su hogar.', 28153),
(158078, 'esMX', '', 'Camino en las sombras.', 28153),
(158077, 'esMX', '', '¡Enseguida!', 28153),
(158076, 'esMX', '', '¡Con cuidado, adalid! ¡Tenemos que ir con sigilo!', 28153),
(158075, 'esMX', '', '¡Mata a este rápido, antes de que alerte a los demás!', 28153),
(158074, 'esMX', '', '¡Que no te detecten! Debemos pasar inadvertidos...', 28153),
(158073, 'esMX', '¡Bajaré enseguida, Lanfa!', '', 28153),
(158072, 'esMX', '', 'Adelante, $n. Si quieres que incapacite a alguno, no tienes más que decirlo. Pero... en voz baja.', 28153),
(158071, 'esMX', 'Harli te llevará allí y luego regresará por mí. ¡Debo saber si mi compañera eh\'tá bien!', '', 28153),
(158070, 'esMX', 'Les dih\'te una verdadera lección. Veamos si eh\'ta vez aprenden.', '', 28153),
(158069, 'esMX', 'Eh\'tos enanos no entienden el mensaje. ¡No son bienvenidos aquí! Muéstrales cómo lidiamo\' los zandalari con los intruso\'.', '', 28153),
(158068, 'esMX', 'Si alguien intenta escalar esta colina... ¡lo mataré!', '', 28153),
(158067, 'esMX', 'Una vez que desmantelemos la flota, ¡Zandalar será nuestro!', '', 28153),
(158066, 'esMX', '¡Alcen esos pilares!', '', 28153),
(158065, 'esMX', '<Esperar un momento mientras Genn convence a Katherine en una escena realmente fantástica>', '<Esperar un momento mientras Genn convence a Katherine en una escena realmente fantástica>', 28153),
(158064, 'esMX', 'La gente de Kul Tiras está unida, pero su casa más importante no lo está, y la Alianza ha perdido a una de sus líderes más poderosas.\n\nEspero que esta falla también se pueda sanar.', '', 28153),
(158063, 'esMX', 'Reúnete conmigo en el monumento conmemorativo de la familia junto a Fortaleza Valiente. Con suerte, quizá convenzamos a lady almirante Valiente de que suspenda la ejecución.', '', 28153),
(158062, 'esMX', 'Adalid, has colaborado para unir a los kultiranos y has logrado que apoyen a la Alianza. Tal vez ahora puedas volver a unir a una madre con su hija.', '', 28153),
(158061, 'esMX', 'La falta de suministros frenará los ataques de la Horda. Nos has conseguido un tiempo valioso.', '', 28153),
(158060, 'esMX', 'Esos goblins monstruosos perforan la tierra para obtener combustible para sus máquinas de guerra. ¡Detenlos!', '', 28153),
(158059, 'esMX', '', 'Avanzamos mientras el fuego sigue ardiendo.', 28153),
(158058, 'esMX', '', 'Estos elementales nos servirán como combustible para nuestros demoledores. Mátalos, junto con todos los kaldorei que se te crucen.', 28153),
(158057, 'esMX', 'Podemos viajar a través del Vacío para ahorrar tiempo. Sígueme.', '', 28153),
(158056, 'esMX', 'Gallywix es escurridizo. No estará en campo abierto por mucho tiempo.', '', 28153),
(158055, 'esMX', 'Sabía que un goblin como Gallywix no podría resistir la tentación de saquear una ciudad literalmente hecha de oro.', '', 28153),
(158054, 'esMX', '', '¡Nos descubrieron! Reúne toda la azerita que puedas. ¡Tendremos que salir de aquí pronto!', 28153),
(158053, 'esMX', '', 'Por la diosa... ¡Azerita! ¡Está por todas partes!', 28153),
(158052, 'esMX', 'Por todo el lugar aparecen nodos de azerita', 'Por todo el lugar aparecen nodos de azerita', 28153),
(158051, 'esMX', '<Colocar la mano sobre el nodo de azerita>.', '<Colocar la mano sobre el nodo de azerita>.', 28153),
(158050, 'esMX', '<El nodo de azerita bulle con poder>.', '', 28153),
(158049, 'esMX', '', 'La trituradora es tuya. Yo me ocuparé de los invasores de la arboleda.', 28153),
(158048, 'esMX', '¡El Páramo de los Ancianos! Por los bosques...', '¡El Páramo de los Ancianos! Por los bosques...', 28153),
(158047, 'esMX', '¡Yo me encargo!', '¡Yo me encargo!', 28153),
(158046, 'esMX', 'Cuidado con los fúrbolgs. De repente, han aparecido manadas.', 'Cuidado con los fúrbolgs. De repente, han aparecido manadas.', 28153),
(158045, 'esMX', '¡Voy en camino!', '¡Voy en camino!', 28153),
(158044, 'esMX', 'Los fúrbolgs están extrañamente agresivos...', 'Los fúrbolgs están extrañamente agresivos...', 28153),
(158043, 'esMX', '|TInterface\\Icons\\INV_misc_boilingblood:20|t¡%s te marca como objetivo de |cFFFF0000|Hspell:271224|h[Descarga de plasma]|h|r!', '', 28153),
(158042, 'esMX', 'No subestimes el valor de tus acciones. Mientras se recuperan de la derrota, nosotros podemos consolidar nuestra posición en la región.', '', 28153),
(158041, 'esMX', 'La Horda quiere fortalecer su posición aquí. ¡No lo permitas, adalid!', '', 28153),
(158040, 'esMX', '', 'La manada sobrevive. Has hecho un buen trabajo.', 28153),
(158039, 'esMX', '', 'Una manada de crias muy inusuale\' corre peligro. Ayúdalas y gánate el favor de Gonk.', 28153),
(158038, 'esMX', 'Un destacamento de guerra menos con que lidiar. Excelente trabajo.', '', 28153),
(158037, 'esMX', '', '¡Zandalar por siempre!', 28153),
(158036, 'esMX', '', 'Si no fuera por $Ueste héroe:esta heroína; de la Horda, nueh\'tras pérdidas habrían sido mucho peores. $bEh\'to demueh\'tra, más que nunca, que es hora de que nos adaptemo\' y regresemos al mundo.', 28153),
(158035, 'esMX', '', 'Que esta guja sirva como recordatorio: aunque caigamo\' en lo más profundo, aunque lo perdamo\' todo, ¡somos zandalari!$b ¡Nos adaptamos y sobrevivimo\'!', 28153),
(158034, 'esMX', '', 'Por su voluntad murieron tantos de nueh\'tros hermanos y hermana\'.', 28153),
(158033, 'esMX', '', 'Contemplen la sangre de G\'huun, reh\'ponsable de las muerte\' de Shadra, Hi\'reek, Torga y... Rezan.', 28153),
(158032, 'esMX', 'Nuestros exploradores han reportado la presencia de una nave de guerra de la Horda cerca de la costa. Encárgate de que sus refuerzos no desembarquen.', '', 28153),
(158031, 'esMX', '', 'Eh\'te logro no me pertenece.', 28153),
(158030, 'esMX', 'No podemos dar nada por sentado aquí, adalid. Gracias a ti, nuestros exploradores podrán seguir espiando.', '', 28153),
(158029, 'esMX', 'Muéstrales tu eh\'pada. Conviértete en el símbolo que necesitan.', '', 28153),
(158028, 'esMX', 'Hicih\'te lo necesario para salvar a tu pueblo. Ahora más que nunca, ello\' quieren un líder para amar, y en quien confiar.', '', 28153),
(158027, 'esMX', 'Trajih\'te al $Ual:a la; adalid a estas costa\' contra la voluntad de tu padre. Deh\'cubriste los secreto\' de G\'huun cuando nadie escuchaba.', '', 28153),
(158026, 'esMX', 'Hemos enviado varios agentes del IV:7 a esta región, pero aún no se han reportado. Encárgate de esta demora de inmediato.', '', 28153),
(158025, 'esMX', 'Muéstrales, líder de Zandalar. Muéstrales la eh\'pada a quiene\' la merecen. Otórgales la paz.', '', 28153),
(158024, 'esMX', '', 'Vol\'jin, ¿puedes oírno\'? Revélate, eh\'píritu.', 28153),
(158023, 'esMX', 'La Horda pagará con sangre cada centímetro de terreno que quiera conquistar. Incluso las victorias más pequeñas pueden darnos ventaja. Bien hecho.', '', 28153),
(158022, 'esMX', 'Perdidos... Tantos se han perdido... Tantos sin guía. Sin juh\'ticia. G\'huun les arrebató la eh\'peranza.', '', 28153),
(158021, 'esMX', 'La Horda cree que puede obrar como se le da la gana en esta área. Muéstrales su error, adalid.', '', 28153),
(158020, 'esMX', '', 'Silencio.', 28153),
(158019, 'esMX', '¡Lo eh\'cucho!', '', 28153),
(158018, 'esMX', 'Perdido...', '', 28153),
(158017, 'esMX', '', 'Vol\'jin, hijo de Sen\'jin, eh\'cucha las voces de tus amigo\' y tu familia. Quieren saber dónde eh\'tás.', 28153),
(158016, 'esMX', 'Colocando azerita', 'Colocando azerita', 28153),
(158015, 'esMX', '¡Debes defender el Páramo de los Ancianos!', '¡Debes defender el Páramo de los Ancianos!', 28153),
(158014, 'esMX', 'Seguiré alerta.', 'Seguiré alerta.', 28153),
(158013, 'esMX', '<Ayúdalo a levantarse.>', '<Ayúdalo a levantarse.>', 28153),
(158012, 'esMX', 'Seré honesto contigo... no es lo más bajo que he caído.\n\nPero se acerca bastante.', '', 28153),
(158011, 'esMX', '', '¡$uHéroe:Heroína;, los ancianos nos llaman! Busca a los druidas de la Zarpa en el bosque y nos encontraremos en el Páramo de los Ancianos.', 28153),
(158009, 'esMX', '', 'Eso nos dará algo de tiempo. Centinelas, ¡resistan!', 28153),
(158008, 'esMX', '', 'No he visto a nadie con esas características. Me temo que quizá tu amigo haya sido víctima del canto de la sirena.', 28153),
(158007, 'esMX', '<Pregúntale si ha visto a Flynn.>', '<Pregúntale si ha visto a Flynn.>', 28153),
(158006, 'esMX', '¿Desaparecido? ¿Cómo que ha desaparecido? ¡Exijo un reembolso!', '¿Desaparecido? ¿Cómo que ha desaparecido? ¡Exijo un reembolso!', 28153),
(158005, 'esMX', '', 'Tú no eres el único que ha solicitado archivos del IV:7.', 28153),
(158004, 'esMX', '¿Cómo es posible que una general élfica condecorada sepa algo sobre mí?', '', 28153),
(158003, 'esMX', '', 'Eres un héroe a tu manera, Keeshan. Recuerda tus servicios en las primeras tres guerras y tus acciones valerosas en Crestagrana.', 28153),
(158002, 'esMX', 'En lo que me concierne, no creo ser digno de servir a su lado. Lo mínimo que puedo hacer es mantenerme en silencio y mostrarle respeto.', '', 28153),
(158001, 'esMX', 'Señora, he leído su archivo del IV:7. Ha vivido durante más de diez mil años y ha luchado en más guerras de las que yo podría imaginarme.', '', 28153),
(158000, 'esMX', '', 'Keeshan, tienes permitido estar tranquilo cuando estás conmigo.', 28153),
(157999, 'esMX', 'Dijo que debería estar asesinando a los miembros de la Alianza en vez de preocuparse por esas ridiculeces. Cuando oí eso, me di cuenta de que tenía que irme a buscar historias a otro lado.', '', 28153),
(157998, 'esMX', 'Esa Areiel que buscan está en la Necrópolis, ¡junto a una gran cantidad de miembros de la Horda! Parecía muy preocupada por una carta que recibió.', '', 28153),
(157997, 'esMX', '¡Esto será divertidísimo! Les daré la información que necesitan, y luego podrán contarme todos los detalles de sus experiencias en la guerra.', '', 28153),
(157996, 'esMX', '', 'Yo estoy viva hace más de 10,000 años y he luchado en todas las guerras que puedas pensar. Vi el Pozo de la Eternidad original con mis propios ojos.', 28153),
(157995, 'esMX', 'Y yo serví en las primeras tres guerras, sobreviví a un campo de prisioneros a manos de una pandilla de orcos bárbaros y ayudé a matar a un dragón negro.', '', 28153),
(157994, 'esMX', '¡Una buena historia! Se suponía que las mejores anécdotas las iba a escuchar de boca de Torga, pero ahora está muerto. ¿Tienen alguna historia interesante para contarme?', '', 28153),
(157993, 'esMX', 'Acabamos de salvarte la vida. ¿Qué más necesitas?', '', 28153),
(157992, 'esMX', 'Puedo contarles lo que quieran sobre la Horda. Solo necesito algo a cambio.', '', 28153),
(157991, 'esMX', 'Gracias, señora.', '', 28153),
(157990, 'esMX', '', '$n, Keeshan, gracias por la ayuda que me han dado. Debo continuar con la cacería de Dreven. Que Elune bendiga su camino.', 28153),
(157989, 'esMX', '¡Ve! ¡Yo cuidaré el flanco!', '', 28153),
(157988, 'esMX', '', '$n, Keeshan, vengan. Regresemos a Fuerte Victoria... y solicitemos un entierro digno para mis amigos.', 28153),
(157987, 'esMX', '', 'Elfo, humano, todos somos iguales, Keeshan. Todos tenemos el mismo valor.', 28153),
(157986, 'esMX', 'Estaré... como nuevo en poco tiempo... Pero yo no debería estar aquí... Tus amigos deberían haber sobrevivido.', '', 28153),
(157985, 'esMX', '', '¡Keeshan! Alabada sea Elune, ¡por lo menos alguien ha sobrevivido a esta masacre!', 28153),
(157984, 'esMX', '<tose> Señora... aún no he... muerto. Parece que el poder de Dreven... no es tan grande... sin sus esbirros.', '', 28153),
(157983, 'esMX', '', 'Falia... Lyrias... Aeolyn... Keeshan... Lo juro, $n. ¡Dreven las pagará!', 28153),
(157982, 'esMX', '¡Agh!', '', 28153),
(157981, 'esMX', 'Nunca me rendiré, Shandris Plumaluna. ¡Veamos qué tan frágiles son tus aliados!', '', 28153),
(157980, 'esMX', 'Debemo\' marcharnos. Los espíritu\' tendrán que encontrar su camino hasta Bwonsamdi por su cuenta.', '', 28153),
(157979, 'esMX', 'Los trols de sangre regresarán, eh\'toy seguro. Pero ahora saben que podemo\' herirlos en su hogar y se lo pensarán dos vece\' antes de volver a atacar.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'esMX', '', 'Shandris, sigue... sin mí...', 28153),
(157977, 'esMX', 'Me escabulliré antes para buscar un punto de reunión seguro. Reúnete conmigo fuera de la aldea cuando haya\' terminado.', '', 28153),
(157976, 'esMX', '¡Recibe la muerte junto a mí, elfa de la noche!', '', 28153),
(157975, 'esMX', '¡Es hora de mostrarte lo que este humano patético puede hacer!', '', 28153),
(157974, 'esMX', '', '¡Bajen el escudo! ¡Aprovechen la oportunidad! ¡Stromgarde será nuestra!', 28153),
(157973, 'esMX', '', 'Todos los cañones... ¡FUEGO!', 28153),
(157972, 'esMX', '', '¿Sí?', 28153),
(157971, 'esMX', 'Seguramente nos dejarán regresar para recuperar nuestras pertenencias. Una vez que el humo se disipe, claro.', 'Seguramente nos dejarán regresar para recuperar nuestras pertenencias. Una vez que el humo se disipe, claro.', 28153),
(157970, 'esMX', '¡Todo lo que teníamos estaba almacenado en la Rama de los Eternos!', '¡Todo lo que teníamos estaba almacenado en la Rama de los Eternos!', 28153),
(157969, 'esMX', '¡Desearás haber ardido en llamas junto con Darnassus!', '', 28153),
(157968, 'esMX', '¿Shandris Plumaluna intenta llevar a cabo una emboscada? Qué audaz.', '', 28153),
(157967, 'esMX', 'Quizás este humano patético sirva como ejemplo.', '', 28153),
(157966, 'esMX', '', 'A partir de hoy no habrá más muertes, Dreven.', 28153),
(157965, 'esMX', '¿A cuántos más tengo que matar para que entiendan que deben apartarse de nuestro camino?', '', 28153),
(157964, 'esMX', 'La Alianza. Sabía que serían demasiado idiotas para aprender la lección después de nuestro último encuentro.', '', 28153),
(157963, 'esMX', 'Parece que llegó la hora de hacer a un lado a las arañas inofensivas y traer a las arañas asesinas.', '', 28153),
(157962, 'esMX', 'Un hombre, tres arañas, veintiséis patas en total. No había manera de vencernos.', '', 28153),
(157961, 'esMX', '¡Cuando una cae, otra toma su lugar!', '', 28153),
(157960, 'esMX', 'Calma, pequeñín. ¿Nos ayudarás?', 'Calma, pequeñín. ¿Nos ayudarás?', 28153),
(157959, 'esMX', '<Flicka te observa detalladamente>\n\n¿Flicka?', '', 28153),
(157958, 'esMX', 'Sí, es cierto. ¡Somos malos! ¡A rockear!', '', 28153),
(157957, 'esMX', 'Estoy listo para matar a Dreven y a sus seguidores.', 'Estoy lista para matar a Dreven y a sus seguidores.', 28153),
(157956, 'esMX', 'Hola, me llamo Dilbert McClint, y trabajo en el sector de control de infestaciones. Siempre es un placer luchar contra $uotro:otra; amante del mundo arácnido.', '', 28153),
(157955, 'esMX', 'Parece que somos la carnada de un grupo de elfos hambrientos y con sed de sangre. ¿Estás $ulisto:lista; para lo que puede suceder?', '', 28153),
(157954, 'esMX', '', 'Avisaré a los demás. Keeshan te buscará en los túneles.', 28153),
(157953, 'esMX', '', 'Bien hecho. Deberíamos poder controlarlo desde aquí.', 28153),
(157952, 'esMX', '', '¡Las fuerzas de la Horda han abierto una brecha! ¡Intentan establecer una base! ¡Hazlos retroceder con tu dragón hada!', 28153),
(157951, 'esMX', 'Quizá camines por este matorral cercano y pienses que a las arañas no les gusta el aire libre y la brisa. Pues déjame decirte que, en ese aspecto, las arañas son iguales a nosotros. Ah, y las telas de araña también son una señal bastante evidente de presencia arácnida.', '', 28153),
(157950, 'esMX', '', 'Te veré en las afueras de las ruinas de Zo\'bal. Ten cuidado.', 28153),
(157949, 'esMX', 'Ah, la emoción de la caza. Saboréala. Como yo.', '', 28153),
(157948, 'esMX', '', 'Descanso para los agotados, comida para los hambrientos.', 28153),
(157947, 'esMX', 'Siempre, princesa.', '', 28153),
(157946, 'esMX', '', 'Ya veo. Regresaré a Zuldazar. Mantenme informada sobre las operacione\' de la Horda en Nazmir. Y ten cuidado, Rokhan.', 28153),
(157945, 'esMX', 'Sylvanas quiere darles una oportunidad. Se han quedado sin hogar. Si pueden trabajar con nosotros, entonce\' tendrán un lugar dentro de la Horda. Si no, desaparecerán.', '', 28153),
(157944, 'esMX', 'Esa amenaza aviar acecha los mares y persigue todas las naves que zarpan contra Kul Tiras. Termina con ella.', '', 28153),
(157943, 'esMX', '', 'No confío en este Dreven, Rokhan. No e\' sensato involucrar justamente a los san\'layn en este conflicto.', 28153),
(157942, 'esMX', 'Haré lo que pides... por ahora. Despejaremos el túnel y les informaremos cuando sus fuerzas puedan avanzar.', '', 28153),
(157941, 'esMX', 'Porque parte del acuerdo que firmaste con Sylvanas decía que reh\'petarías la jerarquía utilizada dentro de la Horda. Y déjame decirte, hermano, que mi rango es má\' alto que el tuyo.', '', 28153),
(157940, 'esMX', 'Quieres que usemos nuestras habilidades para... mover rocas. ¿Y por qué debería seguirte, trol?', '', 28153),
(157939, 'esMX', 'Hay un túnel colapsado que conecta Nazmir con Vol\'dun. Toma tus seguidore\', usa tus podere\' para despejar los escombros y nosotro\' nos encargaremos de atacar a las fuerzas de la Alianza.', '', 28153),
(157938, 'esMX', '', 'Hay un túnel colapsado al sur de eh\'ta posición que conecta Nazmir y Vol\'dun. Despéjenlo y la Horda podrá atacar la base principal que la Alianza ha montado en Vol\'dun con facilidad.', 28153),
(157937, 'esMX', 'A Sylvanas no le gustará eso. Tenemo\' que actuar más rápido si queremos que nuestro plan de detener a la Alianza tenga éxito, príncipe Dreven.', '', 28153),
(157936, 'esMX', 'Digamos que es uno de mis atributos especiales. La Alianza ha perturbado a las fuerzas que la Horda tenía en la Necrópolis y ha matado a Areiel.', '', 28153),
(157935, 'esMX', '', 'Para ti, princesa Talanji, príncipe Dreven. ¿Cómo sabe\' eso?', 28153),
(157934, 'esMX', 'La capitana Areiel no está aquí porque la han asesinado, Talanji.', '', 28153),
(157933, 'esMX', '', 'Pero no la veo aquí. ¿Eh\'tá tan ocupada que no puede darnos un simple informe de la situación?', 28153),
(157932, 'esMX', 'Areiel ha estado matando a las fuerza\' de la Alianza y de los trol\' de sangre y nos ha ayudado a montar una base en la Necrópolis.', '', 28153),
(157931, 'esMX', '', 'Te pido disculpa\' por mi retraso, Rokhan. Cuéntame cuál es la situación actual. ¿La capitana Areiel ha sido de ayuda?', 28153),
(157930, 'esMX', 'Princesa, gracias por venir desde Zandalar. Estamo\' trabajando muy duro para mantener a raya a los trols de sangre y a los invasore\' de la Alianza.', '', 28153),
(157929, 'esMX', '', 'Te doy la bienvenida, $n. El puesto de avanzada está a tus órdenes.', 28153),
(157927, 'esMX', 'Mis servicios son tuyos.', '', 28153),
(157926, 'esMX', '(Tomar el frasco de invisibilidad).', '(Tomar el frasco de invisibilidad).', 28153),
(157925, 'esMX', '', 'Procura que nadie te vea. Yo me quedaré aquí para cerciorarme de que nadie descubra lo que estamos haciendo.\n\nTengo un frasco de invisibilidad que puedes usar para escabullirte. Te volverá completamente invisible... por un breve lapso.\n\nBebe el contenido del frasco y entra en las ruinas sin que nadie te vea. Descubre cuáles son los planes de la Horda y luego sal de allí.', 28153),
(157924, 'esMX', 'Incluso me temo que las pequeñas victorias están dilatando lo inevitable.', '', 28153),
(157923, 'esMX', 'Estamos manteniendo a raya a la Horda, pero ahora se han concentrado en una erupción de azerita en la costa. Debemos detenerlos.', '', 28153),
(157920, 'esMX', 'Acércate, dulzura. ¡Wunja está ciega, pero no sorda! ¡Je, je, je! ¿Has venido a lo de la vieja Wunja en busca de una poción?', 'Acércate, dulzura. ¡Wunja está ciega, pero no sorda! ¡Je, je, je! ¿Has venido a lo de la vieja Wunja en busca de una poción?', 28153),
(157919, 'esMX', '', 'Al Gran G no le gustará esto...', 28153),
(157918, 'esMX', '', '¡Te reventaré toda la boca, toda!', 28153),
(157917, 'esMX', 'Mi pueblo está listo, $p. Por la Alianza.', '', 28153),
(157916, 'esMX', '', 'Entonces supongo que me acompañarás, $p. Te veré en el Campamento Relicario.', 28153),
(157915, 'esMX', 'Mechazoidea, andando.', '', 28153),
(157914, 'esMX', 'Luché en las tres guerras. Creí que había visto lo peor que podía ofrecer Azeroth.\n\nQué equivocado estaba.', '', 28153),
(157913, 'esMX', '', 'Tengo algo que podría ayudar.', 28153),
(157912, 'esMX', '', 'Y me faltas tú, $uhéroe:heroína;. ¡Repórtate ante la capitana Luna de Verano y refuerza esa frontera!', 28153),
(157911, 'esMX', '', 'Arqueras de hipogrifos, vengan conmigo. ¡Nos reagruparemos en Lor\'danel y haremos guardia como unidad de respuesta móvil!', 28153),
(157910, 'esMX', '', 'Centinelas, ¡creen una línea de batalla en Río Culebra! ¡Convoquen a nuestros aliados de Páramo de los Ancianos!', 28153),
(157909, 'esMX', '', 'Cazadoras, ¡refuercen la frontera sur de Costa Oscura! ¡Traigan los lanzagujas!', 28153),
(157908, 'esMX', '', '¡Tenemos que hacer algo! ¡Centinelas, adelante!', 28153),
(157907, 'esMX', '¡Capitana, la Horda ha llegado al Río Culebra! ¡No podremos resistir mucho tiempo!', '¡Capitana, la Horda ha llegado al Río Culebra! ¡No podremos resistir mucho tiempo!', 28153),
(157906, 'esMX', '¡Una alpaca! ¡Iupi!', '', 28153),
(157905, 'esMX', '¿Estás seguro?', '¿Estás segura?', 28153),
(157904, 'esMX', '', '¡Como ordenes!', 28153),
(157903, 'esMX', '<Ataca directamente.>', '<Ataca directamente.>', 28153),
(157902, 'esMX', '¿Qué tal un poco de oro?', '¿Qué tal un poco de oro?', 28153),
(157900, 'esMX', 'Sylvanas quiere enfrentarse conmigo, y yo pienso darle lo que quiere. Ya avisamos a nuestras tropas. Elune mediante, regresarán pronto.', '', 28153),
(157899, 'esMX', '$n, te pido que te ocupes de la defensa de Darnassus.', '', 28153),
(157898, 'esMX', 'Delaryn, viaja a nuestros puestos de avanzada. Reúne todos los soldados que encuentres y tráelos aquí.', '', 28153),
(157897, 'esMX', '', '¿Y tú, shan\'do?', 28153),
(157896, 'esMX', 'La Reina alma en pena quiere capturar el Árbol del Mundo.', '', 28153),
(157895, 'esMX', '', '¡Malfurion! Las fuerzas de la Horda se han reunido en la Avanzada de Zoram\'gar.', 28153),
(157894, 'esMX', 'Puedes atravesar el muro, $n. Los fuegos fatuos no te lastimarán.', '', 28153),
(157893, 'esMX', '', 'Ni siquiera en tus últimos momentos eres capaz de ver el verdadero potencial de los humanos.', 28153),
(157892, 'esMX', '', 'Y tú sigues aferrándote a tus opiniones obsoletas sobre los humanos. Tendría que haberte matado hace mucho tiempo.', 28153),
(157891, 'esMX', '', 'Estoy destinado a vivir por toda la eternidad. ¡No moriré aquí!', 28153),
(157890, 'esMX', '', '¡Es una lástima que estés luchando junto a los sucios humanos, Shandris! Vidas tan cortas e insignificantes...', 28153),
(157889, 'esMX', '', 'Shandris, han pasado... ¿dos mil, tres mil años? Jamás pensé que nos volveríamos a encontrar así, mientras tú ayudas a un humano.', 28153),
(157888, 'esMX', '', 'Oscuridad... Sylvanas... ¿Es eso lo que viste? ¿De eso nos querías salvar?', 28153),
(157887, 'esMX', '', 'Y yo pensaba que esto sería una simple misión de exploración. ¡Lo disfrutaré muchísimo!', 28153),
(157886, 'esMX', '', 'Se acabó... Encuentra sus planes y regresa a Avanzada Camporrojo cuando hayas terminado.', 28153),
(157885, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Xibala, en Zuldazar.', '|cFF0000FF(Misión)|r Zarpar rumbo a Xibala, en Zuldazar.', 28153),
(157884, 'esMX', '¡Muy bien! Ahora que hemos destruido a esa criatura, nuestras tropas pueden viajar por el área sin problemas.', '', 28153),
(157883, 'esMX', 'El ron es para los mareaférrea. ¡Quítale las manos de encima!', 'El ron es para los mareaférrea. ¡Quítale las manos de encima!', 28153),
(157882, 'esMX', 'Ya es bastante difícil montar líneas de suministros en un pantano sin bestias mágicas al acecho. Acaba con esta y despeja el camino.', '', 28153),
(157881, 'esMX', '', '¡Bien hecho! Esa criatura ya no nos moleh\'tará.', 28153),
(157880, 'esMX', '', '¡Un mojo oscuro alimenta a eh\'ta criatura! Regrésale las alma\' a Bwonsamdi.', 28153),
(157879, 'esMX', '', 'Otra victoria.', 28153),
(157878, 'esMX', '¡Tendrán que aprender que hay un costo por interrumpir a Bwonsamdi! ¿Por qué no se embarcan en un pequeño viaje?', '', 28153),
(157877, 'esMX', '', 'Mis exploradores me han informado sobre una erupción repentina de azerita en Costa Oscura. Ayuda a nuestros aliados goblin a tomar la azerita.', 28153),
(157876, 'esMX', '¡No te acerques mucho a Bwonsamdi!', '¡No te acerques mucho a Bwonsamdi!', 28153),
(157875, 'esMX', '¿Qué tienen las orejas?$B$BSe llama moda, OBVIAMENTE. Pff.', '', 28153),
(157874, 'esMX', 'Hozen infelices. Será mejor que no falte ni una gota de ron.', 'Hozen infelices. Será mejor que no falte ni una gota de ron.', 28153),
(157873, 'esMX', 'Ratas de sentina inservibles, ¡ya dejen de tomarse el ron!', 'Ratas de sentina inservibles, ¡ya dejen de tomarse el ron!', 28153),
(157872, 'esMX', 'Quebrar la alianza de la Horda con los zandalari es nuestra prioridad. Para lograrlo, tenemos que establecer una posición en territorio enemigo.', '', 28153),
(157871, 'esMX', 'Es hora de demostrarle a la Horda que la Séptima Legión habla en serio, $n.', '', 28153),
(157870, 'esMX', '', 'Soldados... ¡No! ¡No carguen contra los...!', 28153),
(157869, 'esMX', 'Ejem, ejem. Ehh... ¿Esto está encendido? Eh... ¿Hola? Bien.', '', 28153),
(157868, 'esMX', 'Ja, ¡salieron corriendo como cucarachas! Les llevará un tiempo volver a movilizar a sus tropas. Buen trabajo.', '', 28153),
(157867, 'esMX', 'Hemos logrado capturar otra de las armas de asedio de la Horda. ¡Dales a probar de su propia medicina!', '', 28153),
(157866, 'esMX', '¡No! ¡No! Imposible. Al jefe no le guh\'tará esto. El viejo Bwonsamdi no ha perdido un espíritu en... ay, eh\'to será malo.', '', 28153),
(157865, 'esMX', 'Ey, ¿Vol\'jin? Sal de esa urna. Eh\'pera... eh\'pera... ¡no! ¿Dónde está el eh\'piritu? ¿Dónde está Vol\'jin?', '', 28153),
(157864, 'esMX', 'Vete, $Uhéroe:heroína;. Ya no tienes nada que hacer aquí.', '', 28153),
(157863, 'esMX', 'Por fortuna, a los trabajadores no parece importarles que husmeemos... solo a los matones de la compañía.\n\n¿Tienes lo que necesitamos?', '', 28153),
(157862, 'esMX', 'Hemos logrado mucho aquí hoy. Podremos reagruparnos afuera.', 'Hemos logrado mucho aquí hoy. Podremos reagruparnos afuera.', 28153),
(157861, 'esMX', '', 'Hay que detener a Jakra\'zet.', 28153),
(157860, 'esMX', '¿Qué está haciendo el rey respecto de nuestra tierra natal?', '¿Qué está haciendo el rey respecto de nuestra tierra natal?', 28153),
(157859, 'esMX', 'Ventormenta ese está quedando sin recursos. No habrá suficiente para mantenernos a todos con vida.', 'Ventormenta ese está quedando sin recursos. No habrá suficiente para mantenernos a todos con vida.', 28153),
(157858, 'esMX', 'No, no, no, mi $Upequeño héroe:pequeña heroína;. No dejará\' eso aquí.', '', 28153),
(157857, 'esMX', '¡Bien hecho! Unas fauces menos de que preocuparse.', '', 28153),
(157856, 'esMX', 'En lugar de combatir por unas ruinas, ¡la Alianza debería recuperar nuestra tierra natal!', 'En lugar de combatir por unas ruinas, ¡la Alianza debería recuperar nuestra tierra natal!', 28153),
(157855, 'esMX', 'Ese es el segundo hogar que perdemos.', 'Ese es el segundo hogar que perdemos.', 28153),
(157854, 'esMX', '¿A dónde se supone que iremos ahora?', '¿A dónde se supone que iremos ahora?', 28153),
(157853, 'esMX', 'Bien hecho. Las próximas generacione\' podrán proh\'perar gracias a su deceso.', '', 28153),
(157852, 'esMX', 'Tenemos problemas más importantes, general. Debemos adaptarnos a esta nueva información.', '', 28153),
(157851, 'esMX', '', 'No podemos dejar que ese monstruo escape, Aterravermis.', 28153),
(157850, 'esMX', '¡Nada de Lanza Negra! ¡Nada de trols tontos en este lugar para trols elegantes!', '', 28153),
(157849, 'esMX', 'Ninguna mugre de la Horda es digna de pisar eh\'te lugar. ¡Nosotros, los Furiarena, te desafiamo\'!', 'Ninguna mugre de la Horda es digna de pisar eh\'te lugar. ¡Nosotros, los Furiarena, te desafiamo\'!', 28153),
(157848, 'esMX', '', 'Gracias, Alleria. Agradecemos tu asistencia.', 28153),
(157847, 'esMX', 'Una estrategia sabia. Estoy de acuerdo.', '', 28153),
(157846, 'esMX', '', 'Lo cazaremos y les traeremos su cabeza. Shandris puede concentrarse en rastrear al príncipe de sangre.', 28153),
(157845, 'esMX', '', 'Mis fuerzas de elfos del Vacío pueden dirigir la misión para eliminar a Gallywix.', 28153),
(157844, 'esMX', '', 'Alleria abre un portal del Vacío a sus espaldas.', 28153),
(157843, 'esMX', '', 'No podemos permitirnos que estos objetivos se nos escapen de las manos... es lo último que necesitamos.', 28153),
(157842, 'esMX', '', 'Disculpen la interrupción, pero creo que ambos tienen razón.', 28153),
(157841, 'esMX', '', 'Pude ver de primera mano de qué era capaz Dreven, Aterravermis. ¿Qué haremos si hay más como él?', 28153),
(157840, 'esMX', 'En términos de táctica, él es el eslabón débil de la cadena. Esta es una oportunidad peculiar. Tenemos que atacar ahora.', '', 28153),
(157839, 'esMX', 'Gallywix funda la campaña de guerra de la Horda y comprende en qué consiste la azerita mejor que cualquiera de sus otros líderes.', '', 28153),
(157838, 'esMX', '', '¡Podemos matar a ese goblin glotón cualquier día! Si Dreven escapa, quizá jamás volvamos a encontrarlo.', 28153),
(157837, 'esMX', 'Pronto nos encargaremos del príncipe de sangre Dreven, general. Pero esta es una oportunidad única de perjudicar al ejército de la Horda que no podemos desperdiciar. Todo lo demás debe esperar.', '', 28153),
(157836, 'esMX', '¡Una bestia alada está alimentando a sus crías con mis hombres! Hazle probar el acero en su próxima comida.', '', 28153),
(157835, 'esMX', '¡No traerás a ese traidor amante de la Horda a eh\'te lugar sagrado!', '', 28153),
(157834, 'esMX', '', 'Nuestros aliados esperan tus órdenes.', 28153),
(157833, 'esMX', 'La gran Pa\'ku ha decretado que Ji\'arak ya ha vivido más que suficiente. Reúne a tus fuerza\' y mata a eh\'ta criatura.', '', 28153),
(157832, 'esMX', 'Te doy la bienvenida, $n. Tenemos trabajo que hacer.', '', 28153),
(157831, 'esMX', 'Eso es... ¿sangre? ¿En serio? ¿Me estás diciendo que esa cosa está protegida literalmente por un escudo de sangre?\n\nMuy bien... Ahora sí que he visto todo.', '', 28153),
(157830, 'esMX', '', '¡El Círculo es nuestro! ¡Todos a sus puestos!', 28153),
(157829, 'esMX', 'La próxima guerra. Y la que le sigue.', '', 28153),
(157828, 'esMX', 'La Luz prevalecerá mucho después de que nos hayamos ido. Cuando la guerra termine, ¿qué te sostendrá a ti, Shaw?', '', 28153),
(157827, 'esMX', '¿Tu fe en la Luz? ¿O en Turalyon?', '', 28153),
(157826, 'esMX', 'Al contrario. Presenciar el regreso de Turalyon y saber que la Luz lo había mantenido con vida y lo había transformado solo fortaleció mi determinación. Sé que deposité mi fe en el lugar correcto.', '', 28153),
(157825, 'esMX', 'Cuando supiste que Turalyon estaba con vida, ¿dudaste de tu devoción? ¿De tus decisiones?', '', 28153),
(157824, 'esMX', 'Cuando partió hacia Terrallende con la expedición de la Alianza y se lo dio por muerto, la Luz me abrió los ojos. Comprendí que podía ser un soldado y un paladín. Juré honrar su sacrificio.', '', 28153),
(157823, 'esMX', 'Sin embargo, mientras observaba a esos primeros paladines, hubo uno en particular que me inspiró... Turalyon. Su fe lo sostuvo, lo impulsó y lo convirtió en un gran líder.', '', 28153),
(157822, 'esMX', 'Drukan toma un descanso.', '', 28153),
(157821, 'esMX', 'Serví como caballero cuando se fundó la Mano de plata. No creía que los mandatos sacerdotales pudieran mezclarse con las habilidades marciales. Y me dediqué a entrenarme en el combate.', '', 28153),
(157820, 'esMX', 'Dime, Aterravermis, ¿cómo llega un paladín a liderar una fuerza de soldados de élite? ¿No deberías estar consagrando templos o algo así?', '', 28153),
(157819, 'esMX', 'Oh, por supuesto.', '', 28153),
(157818, 'esMX', 'Eres muy amable, pero si tuviera que elegir entre conservar mi honor y cumplir con mi trabajo, no dudaría en elegir lo último. Por la Alianza, por supuesto.', '', 28153),
(157817, 'esMX', 'Debo admitirlo... Como paladín, he cuestionado la necesidad de tener espías y asesinos en las filas de la Alianza. Pero el honor y la lealtad que has demostrado hacia tu rey son incuestionables.', '', 28153),
(157816, 'esMX', 'El IV:7 se diseñó para trabajar de forma sigilosa. Prefiero mantenerme en las sombras, donde no me siento tan... expuesto.', '', 28153),
(157815, 'esMX', 'He dejado de contar. Voy donde la Alianza me necesite... y donde la Luz me llame. Tú tampoco eres un novato en la batalla, ¿verdad?', '', 28153),
(157814, 'esMX', '¿En cuántas campañas contra la Horda has participado, Aterravermis?', '', 28153),
(157813, 'esMX', 'Ten cuidado al blandir eso, $n.', '', 28153),
(157812, 'esMX', 'Pensé que tenías que saberlo.', '', 28153),
(157811, 'esMX', '¡El taller está abierto! Si necesitas algo, ¡tenemos el sudor y la grasa necesarios para hacerlo realidad!', '', 28153),
(157810, 'esMX', '¡Les devolveremos diez veces el daño que le hagan a Guerracolmillo!', '', 28153),
(157809, 'esMX', 'Ya no le temo a la muerte, la muerte me teme a mí...', '', 28153),
(157808, 'esMX', 'La jefa de guerra no permitirá que esto quede impune.', '', 28153),
(157807, 'esMX', 'La muerte es un castigo muy leve para ti.', '', 28153),
(157806, 'esMX', '¡Me daré un festín con tu cadáver!', '', 28153),
(157805, 'esMX', '¡Los cortaré en dos!', '', 28153),
(157804, 'esMX', '', 'Bien hecho, pero algo me dice que no será su último intento.', 28153),
(157803, 'esMX', '', '¡Los piratas asaltan Colina de la Vigilia! ¡¿Alguna vez aprenderán?! ¡Ayuda a los marinos a ahuyentarlos!', 28153),
(157802, 'esMX', '¡Gracias! Tengo que regresar con mi familia.', '¡Gracias! Tengo que regresar con mi familia.', 28153),
(157801, 'esMX', '¡¿Viste sus caras?! Ay, ¡fue graciosísimo! ¡Les llevará muchos días limpiar todo eso!', '', 28153),
(157800, 'esMX', '¡Todos los de la Horda son unos bárbaros!', '¡Todos los de la Horda son unos bárbaros!', 28153),
(157799, 'esMX', 'Es mejor purgar una corrupción tan insidiosa... antes de que infecte a la Horda.', '', 28153),
(157798, 'esMX', 'Muy bien. ¡No nos quedaremos de brazos cruzados mientras el abismo corrompe nuestra tierra!', '', 28153),
(157797, 'esMX', 'Venrik y yo nos emborrachábamos y montábamos unos loros para divertirnos. ¡Pruébalo! ¡Y que llueva justicia sobre esos bandidos!', '', 28153),
(157796, 'esMX', 'Desguazado...', '', 28153),
(157795, 'esMX', 'Un error... de cálculo.', '', 28153),
(157794, 'esMX', 'Esta abominación es la encarnación misma de la locura y la corrupción. ¡Destrúyela!', '', 28153),
(157793, 'esMX', 'Solo espero que mi familia haya logrado escapar a tiempo.', 'Solo espero que mi familia haya logrado escapar a tiempo.', 28153),
(157792, 'esMX', 'El humo era tan denso. Nos habríamos perdido en él de no haber sido por la reina Cringris.', 'El humo era tan denso. Nos habríamos perdido en él de no haber sido por la reina Cringris.', 28153),
(157791, 'esMX', 'Debemos devolver esta criatura al abismo. ¡Destrúyela!', '', 28153),
(157790, 'esMX', 'Apenas logramos salir con vida.', 'Apenas logramos salir con vida.', 28153),
(157789, 'esMX', '¿Por qué harían una cosa así?', '¿Por qué harían una cosa así?', 28153),
(157788, 'esMX', '¡Estás empezando a molestarme!', '', 28153),
(157787, 'esMX', '¡Es todo míoooo!', '', 28153),
(157786, 'esMX', '¡Te haré picadillo!', '', 28153),
(157785, 'esMX', '', 'Podría haber sido una pérdida terrible para la Guardia Valiente. Gracias a ti, apenas fue un contratiempo.', 28153),
(157784, 'esMX', '', 'Una de nuestras naves de suministros encalló en el canal del sur. La mayor parte de la tripulación escapó, pero dejaron atrás bienes valiosos.', 28153),
(157783, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t ¡El belisario Yenajz comienza a lanzar |cFFF00000|Hspell:274932|h[Abismo interminable]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t ¡El belisario Yenajz comienza a lanzar |cFFF00000|Hspell:274932|h[Abismo interminable]|h|r!', 28153),
(157782, 'esMX', '¡¿Es alcohol?! Buu, yo esperaba oro... ¡para gastar en alcohol!', '', 28153),
(157781, 'esMX', 'En Puerto Libre se dice que uno de esos piratas esconde un botín interesante en las aguas cercanas a los muelles. ¡Búscalo!', '', 28153),
(157780, 'esMX', 'Buen trabajo. Así entrarán menos armas de azerita a Boralus mientras nos ocupamos del motín de Aspafresno.', '', 28153),
(157779, 'esMX', 'La Compañía Comercial Aspafresno aún no ha detenido su producción de armas como se le ordenó. Destroza la fundición, pero sin herir a los civiles.', '', 28153),
(157778, 'esMX', 'Ey, no te preocupes. Ya les encontraremos un nuevo hogar. Lo importante es que ya no vagan por las calles y están lejos del peligro.', '', 28153),
(157777, 'esMX', 'La Compañía Comercial Aspafresno atrae huérfanos prometiéndoles comida y luego los obliga a trabajar hasta el cansancio. ¡Rescaten a esos niños!', '', 28153),
(157776, 'esMX', 'Dicen que Azurethos podía arrancar a un kraken del agua con sus garras. Fue mortal, camarada. Te has convertido en leyenda.', '', 28153),
(157775, 'esMX', 'Los marineros cantan sobre el legendario Azurethos, capaz de volcar un galeón con una ráfaga de viento. Bueno, las historias son ciertas. Derríbalo para que canten sobre ti.', '', 28153),
(157774, 'esMX', '', 'Preséntense ante el alto señor supremo Colmillosauro. Que paguen por su necedad. ¡Por la Horda!', 28153),
(157773, 'esMX', 'Cada vez que cierro los ojos... veo las llamas.', 'Cada vez que cierro los ojos... veo las llamas.', 28153),
(157772, 'esMX', 'Espero que nuestros amigos estén a salvo.', 'Espero que nuestros amigos estén a salvo.', 28153),
(157771, 'esMX', 'No podemos dar por perdido Kalimdor.', 'No podemos dar por perdido Kalimdor.', 28153),
(157770, 'esMX', 'No puedo creer que el Árbol del Mundo... ya no exista...', 'No puedo creer que el Árbol del Mundo... ya no exista...', 28153),
(157769, 'esMX', '¡Esos perros de la Horda destruyeron nuestro hogar!', '¡Esos perros de la Horda destruyeron nuestro hogar!', 28153),
(157768, 'esMX', '¿Qué quieres? Oh, tienes pinta de u$uingeniero:ingeniera; como yo...', '', 28153),
(157767, 'esMX', 'Me gustaría hacer otra pregunta.', 'Me gustaría hacer otra pregunta.', 28153),
(157766, 'esMX', '¿Ese loco? Creo que es un primo segundo. Es triste, solo piensa en bombas y bombas más grandes. La verdadera genialidad sería inventar una fuente de energía total que alimentase máquinas que rompan, destrocen, taladren o hagan volar por los aires muchísimas cosas durante todo el tiempo posible.', '', 28153),
(157765, 'esMX', 'Buen día, $udoctor:doctora;, quería comprar uno de sus reactores. Sin duda, será provechoso para usted.', 'Buen día, $udoctor:doctora;, quería comprar uno de sus reactores. Sin duda, será provechoso para usted.', 28153),
(157764, 'esMX', '¡¿Eres ese Dr. Bum?!', '¡¿Eres ese Dr. Bum?!', 28153),
(157763, 'esMX', 'Ah, ¿en serio? ¡Entonces sí eres $uun ingeniero:una ingeniera; con muchas habilidades! No me llegas a los talones, pero hay pocos como yo.', '', 28153),
(157762, 'esMX', '', 'No sé quién es esa, ¡pero necesita morir!', 28153),
(157761, 'esMX', '¡$UDoctor:Doctora;, la ingeniería de esa pieza es magistral!', '¡$UDoctor:Doctora;, la ingeniería de esa pieza es magistral!', 28153),
(157760, 'esMX', '', 'Todos, ¡reúnanse en el Yunquenegro! ¡Necesitamos evaluar los daños!', 28153),
(157759, 'esMX', 'Oye, ¡estoy trabajando! Vuelve cuando tus habilidades de ingeniero sean un poco más interesantes.', '', 28153),
(157758, 'esMX', '', '¡Excelente, te encargaste de ellos muy rápido! Abriremos la puerta. Oigo una gran cantidad de enemigos del otro lado. ¡Ten cuidado!', 28153),
(157757, 'esMX', 'Pasé los últimos cinco años ajustando y mejorando el equipo de robots más avanzados y letales que se puedan crear. ¿Quieres ver qué les sucede a tus mascotas aburridas y normales cuando se enfrentan a las mascotas creadas por el técnico de reparaciones inferior más brillante del universo?', '', 28153),
(157756, 'esMX', '¡¿Fallas?! ¡No debería pasar esto!', '', 28153),
(157755, 'esMX', 'Mi mente brillante y las máquinas aún más brillantes que crea forman una combinación imbatible.', '', 28153),
(157754, 'esMX', '', '¡Bien hecho! Ese ensamblaje quedó reducido a escombros y Drustvar está a salvo.', 28153),
(157753, 'esMX', '', '¡Un ensamblaje de piedra enorme ha despertado en las montañas cercanas! ¡Tenemos que derribarlo antes de que descienda sobre el pueblo de Drustvar!', 28153),
(157752, 'esMX', '¡Inconcebible! La próxima vez construiré robots más grandes.', '', 28153),
(157751, 'esMX', '¡Ninguna mascota puede competir contra mi equipo! ¡Soy imparable!', '', 28153),
(157750, 'esMX', '¡Prepárate para enfrentarte a mi invencible equipo de robots altamente modificados y personalizados!', '', 28153),
(157749, 'esMX', 'Estoy listo para partir, Krag\'wa.', 'Estoy lista para partir, Krag\'wa.', 28153),
(157748, 'esMX', 'Los trols de sangre todavía siguen asesinado a mis criaturas.$b$bTe ayudaré a llegar hasta su líder, pero debo regresar rápidamente a la marisma para cuidar a mis niños.', '', 28153),
(157747, 'esMX', 'Krag\'wa, el líder de los trols de sangre ha huido hacia aquella estructura grande que se ve a lo lejos. Por favor, ayúdanos.', 'Krag\'wa, el líder de los trols de sangre ha huido hacia aquella estructura grande que se ve a lo lejos. Por favor, ayúdanos.', 28153),
(157746, 'esMX', 'Ah... ejem. Ahora no, Venrik. Estamos tratando un tema serio.', '', 28153),
(157745, 'esMX', '', '¡Estoy aquí para ayudar, para luchar!', 28153),
(157744, 'esMX', '', 'Lucho por mi pueblo.', 28153),
(157743, 'esMX', '', 'Un enemigo fácil, ¡encárguense de él, rápido!', 28153),
(157742, 'esMX', 'Ya sabes, la de \"cabello negro como cola de cuervo\". ¡Jaja!', '', 28153),
(157741, 'esMX', '', '¡En memoria de Darnassus!', 28153),
(157740, 'esMX', '', 'Será un alivio dejar atrás este lugar.', 28153),
(157739, 'esMX', '', 'Será mejor que nos vayamos antes de que lleguen más de... esas cosas.', 28153),
(157738, 'esMX', '', 'Sí... Estaré bien.', 28153),
(157737, 'esMX', 'Dime, Flynn. ¿Qué pasó con esa mujer de la que siempre hablabas?', '', 28153),
(157736, 'esMX', '', '¡Madre! ¿Estás bien?', 28153),
(157735, 'esMX', '', '¿Podrías recuperar el martillo? Es un arma de mucho poder. Sería catastrófico que los goblins aprendieran a usarlo.', 28153),
(157734, 'esMX', '', '$n, tengo otro encargo para ti. Esos salvajes eran miembros de Ventura y Cía. Eso significa que estarán en Kezan, probablemente para poner a Ferromazo en las manos grasientas de Mogul Razdunk en este mismísimo momento.', 28153),
(157733, 'esMX', '', 'Señor feudal del yunque, Yunqueoscuro, averigüen cómo reparar el Yunquenegro.', 28153),
(157732, 'esMX', '', '¡Uf! ¡Se han robado a Ferromazo y partieron el Yunquenegro por la mitad!', 28153),
(157731, 'esMX', '', 'Y Kul Tiras jamás se rendirá.', 28153),
(157730, 'esMX', 'Los drust... nunca... retrocederán...', '', 28153),
(157729, 'esMX', '¡Madre mía!', '', 28153),
(157728, 'esMX', '¡Eh, ustedes dos! ¡Abran bien los ojos! ¡Miren al Yunquenegro!', '', 28153),
(157727, 'esMX', '', '¡Hijo del núcleo! ¡Ese debe ser el enorme meca que me golpeó!', 28153),
(157726, 'esMX', 'Una especie de aporreadora me emboscó. ¡Se llevaron a Ferromazo!', '', 28153),
(157725, 'esMX', '', 'Yo sí, pero tú no te ves nada bien.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'esMX', '¡Reina regente! ¡¿Estás bien, muchacha?!', '', 28153),
(157723, 'esMX', '', '¡Muy bien, chicos y chicas, terminemos con esto!', 28153),
(157722, 'esMX', '', 'Mi pueblo derrotó a los tuyos una vez, monstruo. ¡Volveremos a hacerlo!', 28153),
(157721, 'esMX', '¡Thros los consumirá a todos! ¡Por fin tendré mi venganza!', '', 28153),
(157720, 'esMX', '', 'Justo cuando la balanza se inclinaba a nuestro favor.', 28153),
(157719, 'esMX', '', '<Moira murmura para sí misma.>', 28153),
(157718, 'esMX', '', '¡Thaelin! ¡Cruza la Sala de los Oficios! Quizá estén yendo hacia la Cámara Negra.', 28153),
(157717, 'esMX', '', '¡$uCampeón:Campeona;, toma la Ruta Hierro Negro y asegúrate de protegerla!', 28153),
(157716, 'esMX', '', '¡Señor feudal del yunque, reúne a tus hechiceros para contraatacar!', 28153),
(157715, 'esMX', '', '¡¿Estos gusanos verdes y descerebrados piensan que pueden atacarnos en nuestro hogar?!', 28153),
(157714, 'esMX', '¡Goblins! ¡En los túneles!', '', 28153),
(157713, 'esMX', '', '¡A las armas, $n!', 28153),
(157712, 'esMX', '', '¡Te has metido con la familia equivocada, bestia!', 28153),
(157711, 'esMX', '', '¡Madre!', 28153),
(157710, 'esMX', '', '¡Madre, cuidado!', 28153),
(157709, 'esMX', '', '¡Vaya, ese es gigante!', 28153),
(157708, 'esMX', '¡Nadie escapará!', '', 28153),
(157707, 'esMX', '', 'Vamos, hija. Encontraremos la forma de salir de aquí.', 28153),
(157706, 'esMX', '', '¡Llegan más elementales!', 28153),
(157705, 'esMX', '', '¡Se acercan algunos elementales!', 28153),
(157704, 'esMX', '', 'Hemos descubierto que, si aplicamos mucha magia sobre la azerita, podemos obtener resultados inesperados.', 28153),
(157703, 'esMX', '', '¿Jaina? ¿De verdad eres tú?', 28153),
(157702, 'esMX', 'Déjame traducirte lo que el gran sabelotodo malhumorado quiso decir: protégenos de los ataques de los elementales.', '', 28153),
(157701, 'esMX', 'Han llegado... demasiado tarde...', '', 28153),
(157700, 'esMX', '$C, sin dudas nos toparemos con algunos incidentes azergenéticos espontáneos mientras le damos forma a la azerita. ¿Podrás ocuparte de eso?', '', 28153),
(157699, 'esMX', '¿Te molestaría tirar un poco más de azerita en el yunque por mí, $n?', '', 28153),
(157698, 'esMX', '¡Y siguen ustedes!', '', 28153),
(157697, 'esMX', '¡$UNecios:Necias; insolentes! ¡Ya no pueden salvarla!', '', 28153),
(157696, 'esMX', 'Sí, reina regente.', '', 28153),
(157695, 'esMX', '', 'Thaelin, Thurgaden, a trabajar.', 28153),
(157694, 'esMX', '', '¡Basta! ¡Muestra tu verdadera forma, monstruo!', 28153),
(157693, 'esMX', '', 'Están avanzando mucho. Anduin nos pide noticias casi todos los días, así que me parece sensato mostrarte lo que hemos aprendido.', 28153),
(157692, 'esMX', '', 'Mis mejores hombres han estado refinando azerita desde que apareció en nuestras cámaras por primera vez.', 28153),
(157691, 'esMX', '', 'Gracias por venir, $n.', 28153),
(157690, 'esMX', '', 'Padre... por favor...', 28153),
(157689, 'esMX', '', 'Te veré en la estatua que está en la colina.', 28153),
(157688, 'esMX', '', 'Gran Krag\'wa, ¡necesitamo\' tu ayuda!', 28153),
(157687, 'esMX', 'Igual que en la Tercera Guerra.', '', 28153),
(157686, 'esMX', '¡Por la Compañía Bravo!', '', 28153),
(157685, 'esMX', '¡Como en Draenor!', '', 28153),
(157684, 'esMX', 'Me recuerda a la Segunda Guerra.', '', 28153),
(157683, 'esMX', 'Mpf mpf mpf mpf.', 'Mpf mpf mpf mpf.', 28153),
(157682, 'esMX', 'Repasemos el plan para matar a la capitana Areiel.', 'Repasemos el plan para matar a la capitana Areiel.', 28153),
(157681, 'esMX', 'General.', '', 28153),
(157680, 'esMX', '', 'Nos pondremos en marcha ahora mismo. $n irá al frente. Nosotros brindaremos asistencia y exploraremos las inmediaciones. Keeshan, eso te incluye a ti.', 28153),
(157679, 'esMX', '', 'Si salvamos a los tortollanos, obtendremos información sobre los movimientos de la Horda, y eso nos llevará a la capitana Areiel.', 28153),
(157678, 'esMX', 'Señora. En Nazmir hay tortollanos, y hay información que indicaría que conocen los movimientos de la Horda. Los trols de sangre han capturado a varios de ellos.', '', 28153),
(157677, 'esMX', '¡Más fácil que pescar con lluvia!', '¡Más fácil que pescar con lluvia!', 28153),
(157676, 'esMX', '¡Justo en el blanco! Eh, ¡justo en el pez!', '¡Justo en el blanco! Eh, ¡justo en el pez!', 28153),
(157675, 'esMX', '', 'Necesitamos información y aliados en Nazmir para lograr nuestro cometido. Por suerte, tenemos una oportunidad. ¿Keeshan?', 28153),
(157674, 'esMX', '', 'La muerte de la capitana Areiel entorpecerá las operaciones de la Horda en Nazmir y debilitará a los forestales oscuros de Sylvanas.', 28153),
(157673, 'esMX', '¡Estos trols han dañado a mis hijos durante demasiado tiempo! Ahora seré yo quien se encargue de la cacería.', '', 28153),
(157672, 'esMX', 'Siempre creí que La Rivera Muerta quedaba hacia el otro lado...', '', 28153),
(157671, 'esMX', '', 'Ha estado muy tranquilo desde que Nedly se esfumó.', 28153),
(157670, 'esMX', 'No podemos permitir que eso suceda. Reúne a tus aliados, adalid. ¡Stromgarde le pertenece a la Alianza!', '', 28153),
(157669, 'esMX', 'Pero la Horda está reuniendo fuerzas para arrebatarnos el castillo. Si lo logran, conseguirán una posición estratégica muy importante en los Reinos del Este.', '', 28153),
(157668, 'esMX', 'Stromgarde era un centro de poder clave en los días de la Alianza de Lordaeron. Queremos que recupere su gloria.', '', 28153),
(157667, 'esMX', 'Forma una expedición y apodérate de esa azerita... antes de que nos gane la Horda.', '', 28153),
(157666, 'esMX', 'Los exploradores de Shaw han descubierto depósitos de azerita en muchas islas dispersas por los mares. La Alianza necesita ese recurso, adalid.', '', 28153),
(157665, 'esMX', 'Los agentes que reclutes se dedicarán a socavar los esfuerzos de la Horda... y garantizar nuestra victoria.', '', 28153),
(157664, 'esMX', 'Trabaja junto con Mathias Shaw para formar un equipo de operativos especiales. Nadie mejor para esta misión que el espía maestro de Ventormenta.', '', 28153),
(157663, 'esMX', 'Adalid, para ganar la guerra se precisan armas. Sin embargo, a veces es necesario recurrir a métodos más... sutiles.', '', 28153),
(157662, 'esMX', 'Estoy listo para invocar a Krag\'wa.', 'Estoy lista para invocar a Krag\'wa.', 28153),
(157661, 'esMX', '', 'Zelling está hablando con su familia. Mantente a un lado, veremos si tengo que intervenir.', 28153),
(157660, 'esMX', '', 'Usa su sagacidad y su sigilo para detectar puntos débiles en las defensas del enemigo... y aprovecharlos.', 28153),
(157659, 'esMX', '', 'Trabaja con Garona Semiorca para formar una unidad con los agentes más astutos y peligrosos de la Horda. Enviarás estas fuerzas a misiones encubiertas en Kul Tiras y Zandalar.', 28153),
(157658, 'esMX', '', 'Para asegurar tu éxito, enviaré un agente que tiene... habilidades únicas. Creo que te será bastante útil en esta misión.', 28153),
(157657, 'esMX', '', 'Debes actuar rápido. Usa las penumbras de la noche para ocultarte mientras buscas los restos. Esas aguas están repletas de patrullas de la Alianza.', 28153),
(157656, 'esMX', '', 'Nathanos, tu conversión del hermano Zelling ya está dando resultados. Ha revelado la ubicación del naufragio que buscamos.', 28153),
(157655, 'esMX', '', 'Ahora, el niño rey envía a sus súbditos a recuperarlo. No podemos permitir que lo logren.', 28153),
(157654, 'esMX', '', 'Stromgarde era el centro de poder de la Alianza en el corazón de los Reinos del Este... antes de que el castillo quedara en ruinas.', 28153),
(157653, 'esMX', '', 'Debemos aprovechar la ventaja. Explora las islas y contrólalas... antes que la Alianza.', 28153),
(157652, 'esMX', '', 'Nuestros aliados goblin vuelven a demostrar su valor. Han marcado depósitos de azerita en islas dispersas por los vastos mares.', 28153),
(157651, 'esMX', '', 'En una guerra, a veces una daga en la espalda en el momento indicado hace más daño que mil espadas en el campo de batalla.', 28153),
(157650, 'esMX', '', '¡Ese maldito Mildenhall está loco! Sus experimentos han infestado la hidromielería. Investiga antes de que todo se salga de control.', 28153),
(157649, 'esMX', '', 'Te agradezco a ti y a tu Horda por ayudarme a liberar a mi tripulación.\n\n¡Mientras siga a cargo, los Velaniebla navegarán los mares libremente!', 28153),
(157648, 'esMX', '', 'El último sacrificio era él... Hemo\' fracasado.', 28153),
(157647, 'esMX', 'No... ¡No puede ser!', '', 28153),
(157646, 'esMX', '¡Pero lo verás!', '', 28153),
(157645, 'esMX', '¿Sufrimiento? No has visto el verdadero sufrimiento. No todavía...', '', 28153),
(157644, 'esMX', 'Taelia, cuando el tiempo lo permita, serás mi invitada en Ventormenta. Tengo muchas historias que contarte sobre tu padre.', '', 28153),
(157643, 'esMX', '', 'Dejé de recibir sus cartas. Tengo... tantas preguntas...', 28153),
(157642, 'esMX', '', 'Que sea una muerte limpia. Ya ha sido suficiente sufrimiento por un día.', 28153),
(157641, 'esMX', '', '\"Mi estrella brillante\".', 28153),
(157640, 'esMX', 'Ahora lo recuerdo... Él te escribía cartas. Te había puesto un apodo...', '', 28153),
(157639, 'esMX', 'El alto señor Bolvar fue un gran hombre. Un verdadero héroe para la Alianza... y para mí.', '', 28153),
(157638, 'esMX', '', '¿Conoció a mi padre?', 28153),
(157637, 'esMX', '<Jakra\'zet gruñe.>', '', 28153),
(157636, 'esMX', 'Taelia... De pie, por favor. El honor es mío.', '', 28153),
(157635, 'esMX', '', 'La hija de Bolvar. Criada bajo nuestro amparo desde la Tercera Guerra.', 28153),
(157634, 'esMX', '¡¿Fordragón?!', '', 28153),
(157633, 'esMX', '', 'Taelia Fordragón.', 28153),
(157632, 'esMX', '', 'Es un honor conocerlo, rey Wrynn. Mi nombre es Taelia.', 28153),
(157631, 'esMX', '', 'Junto a su adalid, ella fue fundamental para salvar nuestro reino... y mi vida.', 28153),
(157630, 'esMX', '', 'Rey Wrynn, hay alguien a quien debe conocer.', 28153),
(157629, 'esMX', 'Es un placer y un honor volver a recibir a Kul Tiras en la Alianza. Que la Luz nos guíe hacia la victoria.', '', 28153),
(157628, 'esMX', '', 'Muchas gracias... a todos. Daré todo de mí para demostrarles que soy digna de confianza.', 28153),
(157627, 'esMX', '', '¿Qué dices?', 28153),
(157626, 'esMX', '', 'Esto termina aquí, general. Las conspiracione\'. Las mentira\'. Los asesinato\'.', 28153),
(157625, 'esMX', '', '¡Sam, no!', 28153),
(157624, 'esMX', '¡CANTO TORMENTA!', '', 28153),
(157623, 'esMX', 'Cavaste tu propia tumba, Pike. Debo llevar la flota a nuestra gloriosa salvadora... Azshara.', '', 28153),
(157622, 'esMX', 'Solo veo almas perdidas que claman por su libertad.', '', 28153),
(157621, 'esMX', '¡Se acabó, Canto Tormenta! Mira a tu alrededor... ¡Estás rodeado!', '', 28153),
(157620, 'esMX', 'Es obvio que sabías lo que hacías. ¡Cuento contigo cuando necesite un poco de caos!', '', 28153),
(157619, 'esMX', 'No tenemos precisamente muchas armas, así que debemos ser astutos. Descubre la forma de darles un buen golpe sin que te descubran.', '', 28153),
(157618, 'esMX', '', '¿Quién sabe lo que esa cosa podría haberle hecho a la flota? Gracias a ti, jamás lo averiguaremos.', 28153),
(157617, 'esMX', '', 'Eres demasiado débil para gobernar, Katherine.', 28153),
(157616, 'esMX', '', 'Y yo casi... Priscilla... ¿Cómo pudiste traicionar a tu pueblo? ¿Cómo pudiste traicionarme?', 28153),
(157615, 'esMX', '', '¡Ese gólem podría partir un barco por la mitad! Lord Canto Tormenta no puede tener un arma de tal magnitud.', 28153),
(157614, 'esMX', '', '¡Contrataste una flota pirata, los armaste hasta los dientes y los hiciste atacar a tu propio pueblo!', 28153),
(157613, 'esMX', '', 'Se llama azerita... y la Alianza y la Horda ya están en guerra por ella.', 28153),
(157612, 'esMX', '', '¡Tu compañía FABRICÓ las armas que destruyeron la Puerta de Daelin con esto!', 28153),
(157611, 'esMX', '', 'Lady Priscilla Aspafresno, queda arrestada por contrabandear, conspirar con piratas y cometer alta traición contra el Almirantazgo de Kul Tiras.', 28153),
(157610, 'esMX', 'El océano nos da mucho, pero bajo su superficie solo hay desesperanza.', '', 28153),
(157609, 'esMX', '', '¡¿Qué significa esto, niña?!', 28153),
(157608, 'esMX', '', 'Conque este era tu plan desde el principio. Despreciable.', 28153),
(157607, 'esMX', '', '¡Una mentirosa!', 28153),
(157606, 'esMX', 'Un horror ancestral de las profundidades se ha manifestado. Húndelo bajo las mareas.', '', 28153),
(157605, 'esMX', '', 'Lady Aspafresno ha sido mi amparo desde los primeros días oscuros, cuando las dos perdimos a nuestros esposos. Y ahora es el amparo del reino. Ahora es...', 28153),
(157603, 'esMX', '', 'Pero no ha sido suficiente.', 28153),
(157602, 'esMX', '', '¡Muy bien! Así podremos seguir luchando en tierra seca.', 28153),
(157601, 'esMX', 'La última vez que vi tanto humo fue cuando la abuela Davenport quiso enseñarle a cocinar al tonto de su nieto. ¡Excelente trabajo!', '', 28153),
(157600, 'esMX', '', '¡Qué vergüenza!', 28153),
(157599, 'esMX', '', '¡Los nagas han invocado una máquina de asedio andante para destruir el dique! ¡A las armas!', 28153),
(157598, 'esMX', '¡¿Piratas?! ¡Los Valiente ya ni siquiera pueden protegernos de los piratas!', '', 28153),
(157597, 'esMX', '', 'Una flota pirata atacó la puerta con una fuerza abrumadora...', 28153),
(157596, 'esMX', 'La furia de la tormenta es impredecible y peligrosa, pero no se compara con tu talento.', '', 28153),
(157595, 'esMX', 'Esto es obra de la magia de los maresabios. ¡Haz lo que puedas para frenarla!', '', 28153),
(157594, 'esMX', 'Creo que hemos debilitado sus fuerzas, pero se reconstruyen más rápido de lo que podemos destruirlas. ¡Debemos cortar su suministro de madera! ¡Quema todo!', '', 28153),
(157593, 'esMX', '', 'Los rumores son ciertos. La Puerta de Daelin... ha caído.', 28153),
(157592, 'esMX', 'Esas explosiones me han dejado sordo. ¿Acaso quedó algo más que un montón de polvo?', '', 28153),
(157591, 'esMX', '', '¡La cosecha está a salvo, y todo se debe a ti! Intentaremos reubicar a estos pequeños lejos de las granjas.', 28153),
(157590, 'esMX', '', 'Sabía con certeza que valdría la pena. ¡Qué suerte tenerla de nuestro lado!', 28153),
(157589, 'esMX', '', 'Algo está devorando las semillas de los granjeros antes de que puedan germinar. ¡Descubre la amenaza!', 28153),
(157588, 'esMX', '', 'La señorita Davenport ha pedido unos objetos para ayudar en la guerra. Esa mujer es un hueso duro de roer. ¡Sería una locura negarnos a ayudarla!', 28153),
(157587, 'esMX', 'Expulsaremos su corrupción una y otra vez, hasta purificar el Santuario de la Tormenta.', '', 28153),
(157586, 'esMX', 'Esos malignos intentan profanar nuestros terrenos sagrados. ¡No podemos permitirlo!', '', 28153),
(157585, 'esMX', '', 'Sé que el control de plagas no es una tarea glamorosa, pero te aseguro que la gente de Poblado Molino apreciará tu ayuda.', 28153),
(157584, 'esMX', '', 'Una desdicha terrible aflige a los habitantes de Poblado Molino. Sus reservas de comida están infestadas de plagas. Ayudemos a exterminarlas.', 28153),
(157583, 'esMX', 'Algún día, el sonido jubiloso de los maresabios que lanzan sus primeros hechizos volverá a resonar en estas tierras... pero no hoy.', '', 28153),
(157582, 'esMX', '', 'Esperemos que eso espante al resto de esos gigantes horribles y que vuelvan a las montañas, ¡donde pertenecen!', 28153),
(157581, 'esMX', 'Los tentáculos de mi antiguo maestro aún azotan estas tierras. Erradícalos.', '', 28153),
(157580, 'esMX', 'Gracias. La gente del valle nunca olvidará tus hazañas.', '', 28153),
(157579, 'esMX', '', 'Los ettins han estado aterrorizando a los civiles en Poblado Molino. No pueden defenderse solos. ¡Somos su única esperanza!', 28153),
(157578, 'esMX', 'Te necesitamos en Presabrenna, $uhéroe:heroína;. Aún no tenemos fuerzas para organizar un contraataque por nuestra cuenta.', '', 28153),
(157577, 'esMX', 'Habla con la capitana Angélica cuando estés $ulisto:lista; para desembarcar.', '', 28153),
(157576, 'esMX', '', 'Debería haberte preguntado si les tenías alergia a las abejas antes de enviarte allí. ¡Pero te ves bien! ¡Ya sé a quién pedirle ayuda la próxima vez!', 28153),
(157575, 'esMX', 'Gracias por acudir tan rápido, $n. Zarparás con la tercera flota.', '', 28153),
(157574, 'esMX', 'Una maldad tan desvergonzada no puede florecer en nuestro mundo.', '', 28153),
(157573, 'esMX', '', 'La hidromielería se ha llenado de abejas que atacan a los clientes y los granjeros han perdido el control de la situación. ¡Qué sorpresa!', 28153),
(157572, 'esMX', 'El rey Anduin me envió, maestro espía.', 'El rey Anduin me envió, maestro espía.', 28153),
(157571, 'esMX', '', 'Algo sucede en la granja, los wendigos han enloquecido. Antes de que se mudaran esos locos Mildenhall, no causaban problemas.', 28153),
(157570, 'esMX', '', 'Me han informado que la Hidromielería de Mildenhall está sufriendo una invasión de wendigos. ¿Puedes ir a dar una mano?', 28153),
(157569, 'esMX', 'Los k\'thir practican su magia oscura sin impedimentos a bordo del Melodía Abisal. Purga esta corrupción de sus cubiertas.', '', 28153),
(157568, 'esMX', 'Puede que nos superen en número, pero gracias a ti seguimos intactos.', '', 28153),
(157567, 'esMX', 'Los maresabios caídos han embelesado a los marineros perdidos y planean atacar Cruce Mareal. ¡Detén su avance!', '', 28153),
(157566, 'esMX', '', 'En otra época, esa criatura debe haber sido un fungálido honorable. Un destino trágico para un guerrero tan noble.', 28153),
(157565, 'esMX', '', 'Recibimos informes de una presencia poderosa en una cueva al sur. Ten cuidado. Las descripciones de esa criatura me dan escalofríos...', 28153),
(157564, 'esMX', '', 'Buen trabajo, pero dudo que sea la última vez que debamos salvarle el pellejo...', 28153),
(157563, 'esMX', 'Aún no hemos logrado desplazar a la Horda. Arrasa con su producción, sea como sea. ¡Haz volar el lugar, si es necesario!', '', 28153),
(157562, 'esMX', '', 'Las armas de las fundiciones de Canto Tormenta deberían servir para proteger al pueblo, no para oprimirlo.', 28153),
(157561, 'esMX', 'Quizá la tarea te resulte sencilla por tus antecedentes. De todos modos, alguien debe hacerlo.', '', 28153),
(157560, 'esMX', 'El Recinto de Kennings está atrasado con los pedidos para el almirantazgo debido a ciertas... complicaciones. Para ti será fácil ayudarlos.', '', 28153),
(157559, 'esMX', '', 'Sería una pena desperdiciar estas municiones. Ya sabes qué hacer.', 28153),
(157558, 'esMX', 'Es nuestro deber mantenerlos a raya ahora que la milicia no está.', '', 28153),
(157557, 'esMX', 'Los jabaespines otra vez están haciendo de las suyas en su horado. ¡Frustra sus planes antes de que recuperen su fuerza!', '', 28153),
(157556, 'esMX', 'Nura, he venido a ayudar.', 'Nura, he venido a ayudar.', 28153),
(157555, 'esMX', '', '¿Qué te trae hasta aquí?', 28153),
(157554, 'esMX', '¡Nos volveremos a ver en el pueblo y dividiremos el botín!', '', 28153),
(157553, 'esMX', '¿Puedes dejarme cerca de La Carretera, en los Baldíos del Sur?', '¿Puedes dejarme cerca de La Carretera, en los Baldíos del Sur?', 28153),
(157552, 'esMX', 'Una nave sin velas es como una caballería sin caballos. No es... Bueno, no sirve para nada.', '', 28153),
(157551, 'esMX', 'Una tormenta terrible amenaza nuestras provisiones de cuerdas. ¡Cálmala si puedes!', '', 28153),
(157550, 'esMX', 'Hoy le has hecho justicia al legado de Addington. Gracias.', '', 28153),
(157549, 'esMX', 'El hermano Addington jamás habría permitido tal depravación. ¡Recupera los patios en su nombre!', '', 28153),
(157548, 'esMX', '', 'Lo importante es la materia prima. Después se suman el esfuerzo y la pasión.', 28153),
(157547, 'esMX', '', 'Los carpinteros de barcos de Canto Tormenta son legendarios, pero necesitan madera para trabajar. ¡Encárgate de eso!', 28153),
(157546, 'esMX', '', 'Espero que hayan aprendido la lección. ¡Canto Tormenta está abierto a todos!', 28153),
(157545, 'esMX', '', '¡Las fuerzas de Lord Canto Tormenta han establecido otro bloqueo! ¡Destrúyelo para que los comerciantes puedan transitar!', 28153),
(157544, 'esMX', 'Ahora, ¡apresúrate!', '', 28153),
(157543, 'esMX', 'Habla con Isabella. Ella se asegurará de que llegues a salvo a tu punto de encuentro en Entrañas.', '', 28153),
(157542, 'esMX', 'Una vez que tengamos refuerzos suficientes, te daré tus indicaciones.', '', 28153),
(157541, 'esMX', 'Gracias por venir tan rápido, $n. No hay tiempo que perder.', '', 28153),
(157540, 'esMX', 'Proteger, educar y guiar. Ese es el verdadero camino de los maresabios.', '', 28153),
(157539, 'esMX', 'Todos los maresabios juran proteger a nuestro pueblo. ¡Respeta los juramentos y socorre a estas almas agobiadas!', '', 28153),
(157538, 'esMX', 'Nuestros enemigos son implacables. Pero gracias a ti, viviremos para volver a luchar.', '', 28153),
(157537, 'esMX', 'Parece que el ritual fracasó sin pena ni gloria. La magia vil de los nagas no puede seguir contaminando los mares.', '', 28153),
(157536, 'esMX', 'Los seguidores de Azshara están probando un nuevo ritual tras su derrota reciente. Muéstrales las profundidades a las que se aferran con tanta desesperación.', '', 28153),
(157535, 'esMX', '', 'Parece que los nagas se vuelven más agresivos con el paso de los días. Temo por nuestro futuro.', 28153),
(157534, 'esMX', '', 'Los Estela de la Tormenta aún están recuperándose del ataque de los nagas. ¡Ayúdalos a defender su posición mientras se reorganizan!', 28153),
(157533, 'esMX', 'Estos recursos serían una gran ventaja para nuestras fuerzas. ¡Tómalos!', '', 28153),
(157532, 'esMX', 'Que las mareas te bendigan. ¡Mientras estemos de pie, no tomarán nuestro valle!', '', 28153),
(157531, 'esMX', 'Hay una primera vez para todo y... espero que para eso no haya una segunda.', '', 28153),
(157530, 'esMX', 'Eh, no sé cómo explicar esto, pero algo extraño está sucediendo en el pueblo. Quizá tú puedas solucionarlo.', '', 28153),
(157529, 'esMX', '', 'Si no escuchas tus sentimientos, solo te quedará una oscuridad vacía.', 28153),
(157528, 'esMX', '', 'Jaina, cariño... algunas decisiones no pueden tomarse solo con la razón.', 28153),
(157527, 'esMX', '', '¡No es real, Jaina! ¡Ninguno de ellos es real!', 28153),
(157526, 'esMX', '', 'Pero... me mintieron...', 28153),
(157525, 'esMX', '¡Fui un necio al creer que podías ser nuestra líder!', '', 28153),
(157524, 'esMX', '¡Tus parcialidades corrompieron al Kirin Tor!', '', 28153),
(157523, 'esMX', '', 'Ojalá tu padre hubiera aprendido esa lección.', 28153),
(157522, 'esMX', '', 'Poner fin al derramamiento de sangre es un propósito noble, Jaina.', 28153),
(157521, 'esMX', 'Los ejércitos de Lord Canto Tormenta intentan apoderarse de esta área. ¡No lo permitas!', '', 28153),
(157520, 'esMX', '', '¡Aléjate de ella!', 28153),
(157519, 'esMX', 'Hir\'eek es el loa de la noche. No hace faltas que sepas más de él.', 'Hir\'eek es el loa de la noche. No hace faltas que sepas más de él.', 28153),
(157518, 'esMX', '', 'Todo por culpa mía...', 28153),
(157517, 'esMX', 'Pero tú... Tú frenaste mi espada. ¿Cuántos soldados de la Alianza murieron aquel día? ¿Y en todas las batallas que siguieron?', '', 28153),
(157516, 'esMX', '¡Podría haberlos aniquilado a todos! A Sylvanas... a Thrall... ¡Imagina lo que podría haber sido nuestro mundo sin ellos y su Horda corrupta!', '', 28153),
(157515, 'esMX', '', 'No. Debe ser otra de esas criaturas que atormentan a Jaina. ¡Apresúrate!', 28153),
(157514, 'esMX', '', 'Esa voz... ¡¿Daelin?!', 28153),
(157513, 'esMX', '', '¿Otra ilusión? Jaina debe estar atrapada cerca.', 28153),
(157512, 'esMX', '', 'La encontraremos... y la liberaremos de este lugar condenado.', 28153),
(157511, 'esMX', '', 'Mi hija está aquí en algún lado. Escondida. Sufriendo.', 28153),
(157510, 'esMX', '¡Has luchado bien! Las corrientes contarán tus hazañas en los años venideros.', '', 28153),
(157509, 'esMX', '', 'Tenemos que seguir buscando.', 28153),
(157508, 'esMX', '', 'Se fue. La niña era solo un reflejo... un eco del sufrimiento de Jaina.', 28153),
(157507, 'esMX', '', '...pero ni siquiera la más fuerte de nosotros puede salvar a todos.', 28153),
(157506, 'esMX', '', 'Jaina... tú eras... eres... el orgullo de Kul Tiras. Su poder, y también su furia...', 28153),
(157505, 'esMX', '', '¡No! ¡No los escuches, Jaina!', 28153),
(157504, 'esMX', '', 'Les fallé... Les fallé a todos...', 28153),
(157503, 'esMX', '', '¡Podrías haberlo detenido! ¡Podrías habernos salvado!', 28153),
(157502, 'esMX', 'A la orden, alto señor supremo.', 'A la orden, alto señor supremo.', 28153),
(157501, 'esMX', 'Estela de la Tormenta necesita tu ayuda una vez más. Que las mareas te guíen hacia la victoria.', '', 28153),
(157500, 'esMX', '¡Nos entregaste a la muerte!', '', 28153),
(157499, 'esMX', '', 'Ve adelante, $p.', 28153),
(157498, 'esMX', '', 'Yo siempre la encontraba... y esta vez no será diferente.', 28153),
(157497, 'esMX', '', 'Cuando Jaina era pequeña, se escondía cada vez que estaba asustada o enojada.', 28153),
(157496, 'esMX', '', '¡Espera!', 28153),
(157495, 'esMX', '', '¡No! ¡No puedes ayudarme! ¡Nadie puede ayudarme!', 28153),
(157494, 'esMX', '', 'Tranquila, cariño...', 28153),
(157493, 'esMX', '', 'Jaina está más adelante. ¡Debemos apresurarnos!', 28153),
(157492, 'esMX', 'Thros... te consumirá...', '', 28153),
(157491, 'esMX', '', '¡No si puedo impedirlo!', 28153),
(157490, 'esMX', '¡La hija de Valiente es nuestra, $uintruso:intrusa;!', '', 28153),
(157489, 'esMX', '', '$n, ¡tenemos que seguirla!', 28153),
(157488, 'esMX', '', 'Jaina, ¡espera!', 28153),
(157487, 'esMX', '', '¡No! ¡Vete!', 28153),
(157486, 'esMX', '', '¡¿Jaina?!', 28153),
(157485, 'esMX', '', 'Todo... es mi culpa.', 28153),
(157484, 'esMX', '', 'Las Tierras Plagadas... Sin dudas el lugar hace honor a su nombre.', 28153),
(157483, 'esMX', 'Que las mareas te bendigan. Nuestro valle está a salvo una vez más.', '', 28153),
(157482, 'esMX', 'Por las profundidades abisales... ¡esta aberración no puede seguir amenazando a nuestro pueblo!', '', 28153),
(157481, 'esMX', 'Que esto sirva de lección para todos los que blanden los dones de la Madre de las mareas.', '', 28153),
(157480, 'esMX', 'Un desprecio tan temerario por el poder del mar debe destruirse.', '', 28153),
(157479, 'esMX', 'Torga es un ser poderoso en ruinas, pero nosotros, los tortollanos, no dejaremos que lo olviden.', '', 28153),
(157478, 'esMX', 'Detengámonos aquí por un momento, $p.', '', 28153),
(157477, 'esMX', 'Gral es un loa sabio. Mira las cosa\' desde una perspectiva amplia. El mar profundo e\' su reino, el océano oscuro su dominio.', 'Gral es un loa sabio. Mira las cosa\' desde una perspectiva amplia. El mar profundo e\' su reino, el océano oscuro su dominio.', 28153),
(157476, 'esMX', 'Que las mareas los rechacen, tal como ellos rechazaron a su pueblo.', '', 28153),
(157475, 'esMX', '¡Hay muchas menos espinas de nuestro lado! Buen trabajo.', '', 28153),
(157474, 'esMX', 'Los jabaespines traman algo en la granja que está fuera de su horado. ¿Por qué no vas a echar un vistazo y frustras sus planes?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'esMX', 'Otra alma malvada ha respondido el llamado de Lord Canto Tormenta. ¡No puede arruinar nuestro trabajo!', '', 28153),
(157472, 'esMX', 'Descansa, alma miserable. Tu sufrimiento ha terminado.', '', 28153),
(157471, 'esMX', 'Cuántos horrores han provocado mis hermanos... Acaba con la miseria de esta criatura.', '', 28153),
(157470, 'esMX', 'Me marcho...', 'Me marcho...', 28153),
(157469, 'esMX', 'Sí... milord.', 'Sí... milord.', 28153),
(157468, 'esMX', '¿Qué sssuceeeede?', '¿Qué sssuceeeede?', 28153),
(157467, 'esMX', '¡Hora de moverse!', '¡Hora de moverse!', 28153),
(157466, 'esMX', '¿Más trabajo?', '¿Más trabajo?', 28153),
(157465, 'esMX', '', '¡Yo me encargo, jefe!', 28153),
(157464, 'esMX', 'Veo otra excavación pequeña al oeste. ¿Kelsey?', '', 28153),
(157463, 'esMX', 'Resistan juntos. ¡No llegamos tan lejos para caer!', '', 28153),
(157462, 'esMX', 'Las excavaciones más grandes del Relicario están más lejos, hacia el sur. Tal como lo sospechaba.', '', 28153),
(157461, 'esMX', '¡La Horda ha incendiado los edificios! ¡Apaga las llamas antes de que arda todo el valle!', '', 28153),
(157460, 'esMX', '¡Buen trabajo! El fuego se apaga y nuestros hogares siguen en pie. Gracias.', '', 28153),
(157459, 'esMX', 'Me ocuparé de que los sethrak ni siquiera tengan su propio botín cuando abandonen este lugar.', 'Me ocuparé de que los sethrak ni siquiera tengan su propio botín cuando abandonen este lugar.', 28153),
(157458, 'esMX', 'Aunque no pueda replegar a nuestros marinos, al menos sé que las naves están allí... en alguna parte. El destino de nuestra flota ahora depende de los Valiente.', '', 28153),
(157457, 'esMX', 'Jani es el loa de los desecho\' y de las persona\' apartadas o ignoradas. Busca $Uhuérfanos:huérfanas; como tú, o cualquiera que eh\'té en un mal momento.', '', 28153),
(157456, 'esMX', 'Aquí mi magia es más fuerte. Si hay una posibilidad de encontrar la flota, este es el momento de intentarlo.', '', 28153),
(157455, 'esMX', 'Errn... Lárgate... <¡hip!> Estoy ocupado.', '', 28153),
(157454, 'esMX', 'Somos seguidore\' de Torcali: la montaña movediza, el baluarte errante. Si nuestro loa lo desea, nada atravesará nuestros escudo\'.', '', 28153),
(157453, 'esMX', '', '¡Una amenaza menos en el valle! ¡Bien hecho!', 28153),
(157452, 'esMX', '', 'Guau... Me he quedado sin palabras. ¡Fue una pelea impresionante!', 28153),
(157451, 'esMX', 'Espera aquí. Creo que veo algo.', '', 28153),
(157450, 'esMX', 'Realmente no creí que fuera a funcionar, ¡pero ese oro ayudará a mucha gente a reconstruir sus vidas!', '', 28153),
(157449, 'esMX', 'Sí... Siento las naves... ¡Nuestra flota! ¡Las nieblas oscuras que la rodean se disipan!', '', 28153),
(157448, 'esMX', 'Estoy aquí para resolver tus problemas, Krog.', 'Estoy aquí para resolver tus problemas, Krog.', 28153),
(157447, 'esMX', '', 'Algunos de los Estela de la Tormenta informan sobre una bestia molesta aquí cerca. ¡Tú podrás encargarte!', 28153),
(157446, 'esMX', '', 'Algo muy peligroso acecha en las colinas. ¡Encuéntralo antes de que alguien salga lastimado!', 28153),
(157445, 'esMX', 'Los cazatesoros de La Rivera Muerta donarán un poco de oro para la reconstrucción de Presabrenna. ¡El truco está en que tenemos que recogerlo nosotros mismos!', '', 28153),
(157444, 'esMX', 'Arthur...', '', 28153),
(157443, 'esMX', 'Doras, necesito un jinete del viento para llegar a al Poblado Murohelecho.', 'Doras, necesito un jinete del viento para llegar a al Poblado Murohelecho.', 28153),
(157442, 'esMX', '', 'Bien hecho, adalid. Salvando a Ai\'twen ayudas a los tortollano\'... y creo que complaces a los loa también.', 28153),
(157441, 'esMX', '¡Eh, derribé piedras! Piedras muy enfadadas.', '', 28153),
(157440, 'esMX', 'La orden era derribar los hitos.', '', 28153),
(157439, 'esMX', '¡Ah! Al final, salió todo bien. $UEl continental:La continental; y yo eliminamos a ese gran monstruo de rocas y sobrevivimos. Toda una victoria.', '', 28153),
(157438, 'esMX', '¡Arthur! ¿Qué te dije sobre eso de lanzarte de cabeza a todo?', '', 28153),
(157437, 'esMX', '', 'Los tortollano\' veneran a la gran tortuga Ai\'twen, un aliado poderoso del pasado. Si lo mantienes a salvo y bien alimentado, puede que vuelva a ayudarno\'.', 28153),
(157436, 'esMX', '¡Abandona este lugar!', '', 28153),
(157435, 'esMX', '¡Que las corrientes te guíen, adalid! Tus acciones son un ejemplo para todos.', '', 28153),
(157434, 'esMX', 'Nosotros seguiremos camino al sur. Estaremos en contacto, Guzbert.', '', 28153),
(157433, 'esMX', '¡Tú puedes, Guzzy!', '', 28153),
(157432, 'esMX', '', '¡Ve por ellos, Guzbert!', 28153),
(157431, 'esMX', '... ¡con una MONTAÑA DE BOMBAS!', '', 28153),
(157430, 'esMX', '¿Una pequeña excavación? Parece ser un trabajo apropiado para un gnomo...', '', 28153),
(157429, 'esMX', 'Hay una pequeña excavación del Relicario cerca de aquí, al este.', '', 28153),
(157428, 'esMX', '¡$n, detrás de ti! Ayúdame a quitar a estas molestias del camino.', '', 28153),
(157427, 'esMX', 'La tortuga ancestral Ai\'twen es un misterio del mar que debemos proteger. Ayuda a los tortollanos a mantenerla a salvo y bien alimentada.', '', 28153),
(157426, 'esMX', 'Haremos que Lord Canto Tormenta pague por sus transgresiones... o moriremos en el intento.', '', 28153),
(157425, 'esMX', 'El pueblo de Canto Tormenta merece sentirse a salvo. No tengas piedad con aquellos que amenazan su seguridad.', '', 28153),
(157424, 'esMX', 'Debemos actuar ahora si queremos salvar a nuestra flota del yugo de Azshara.', '', 28153),
(157423, 'esMX', 'Este lugar no es seguro. Conozco un viejo puesto de vigilancia que da al santuario cercano.', '', 28153),
(157422, 'esMX', 'Pero no lo olvidaremos. No mientras estemos de pie.', '', 28153),
(157421, 'esMX', 'La voz ahora es un eco de la tuya. Sientes que busca una respuesta porque tú también la buscas.\n\n\"¿Con qué fin?\"', '', 28153),
(157420, 'esMX', 'La voz empieza a gritar en tu interior y te retuerces de dolor.\n\n\"¿Dónde empezó?\"', '', 28153),
(157419, 'esMX', 'Te lo agradezco. Los granjeros pronto podrán volver a sus campos.', '', 28153),
(157418, 'esMX', 'He recibido informes sobre un peligro en las granjas más lejanas. ¡Ayuda a restaurar el orden en el valle!', '', 28153),
(157417, 'esMX', 'La voz se vuelve más fuerte y más ansiosa.\n\n\"¡Más! ¡Más! ¡Más!\"', '', 28153),
(157416, 'esMX', 'La voz ancestral es ahora apenas un eco que llama desde las profundidades de tu mente.\n\n\"¿Qué buscas?\"', '', 28153),
(157415, 'esMX', '¡Eres una caja de sorpresas! Me gustaría aprender algunos de tus trucos.', '', 28153),
(157414, 'esMX', 'Si necesitas una extracción de Boralus, hay agentes esperando aquí cerca.', '', 28153),
(157413, 'esMX', 'Me escabulliré y le contaré a Abedulio. ¡Nos vemos allí!', '', 28153),
(157412, 'esMX', '¡JA! ¡Se desmoronó ante nuestro poder!', '', 28153),
(157411, 'esMX', '', 'Sam... está... está muerto...', 28153),
(157410, 'esMX', 'Cuando hayamos asesinado y resucitado como Renegado hasta al último de sus seguidores, el niño rey se arrodillará ante la Dama Oscura. Y finalmente habrá una reina para gobernarlos a todos.', '', 28153),
(157409, 'esMX', 'Venganza. Desprecio. Llámalo como quieras.', '', 28153),
(157408, 'esMX', '', 'La venganza te motiva. Entiendo eso.', 28153),
(157407, 'esMX', 'Cuando se quebró el dominio del Rey Exánime sobre nosotros, Sylvanas buscó aliados. En lugar de aceptar a sus hermanos caídos de Lordaeron, los humanos nos rechazaron. Nos persiguieron. Así que juré cazarlos.', '', 28153),
(157406, 'esMX', '', '¿Les dieron la espalda?', 28153),
(157405, 'esMX', 'Alguna vez luché por su causa. La arrogancia insufrible de la Alianza ha crecido a pasos agigantados desde que nos dieron la espalda.', '', 28153),
(157404, 'esMX', '', 'El fervor con el que atacas a la Alianza parece fundado en algo más que en la lealtad hacia tu reina, Clamañublo.', 28153),
(157403, 'esMX', '', 'Fui responsable de la caída de un rey. Quizás es hora de que la historia se repita.', 28153),
(157402, 'esMX', 'Bien. La Alianza no merece compasión. Ni piedad. Hazlos sufrir y la Dama Oscura te recompensará.', '', 28153),
(157401, 'esMX', '', 'No. Y sin duda sabes que trabajé con la Alianza cuando me resultó útil para mis propósitos. Pero no les debo nada. La Horda es mi hogar.', 28153),
(157400, 'esMX', 'Necios...', '', 28153),
(157399, 'esMX', '¡En nombre de Kul Tiras, abandonarás este lugar!', '', 28153),
(157398, 'esMX', 'Conozco la historia. También sé que matar a Llane Wrynn no fue tu decisión.', '', 28153),
(157397, 'esMX', '', '¿Solo porque alguna vez tuve amistad con el abuelo del joven rey? Por si no lo recuerdas, lo asesiné.', 28153),
(157396, 'esMX', 'Tus ataques contra los objetivos de la Alianza han sido impresionantes, Garona. Debo admitir que dudaba de tu... lealtad.', '', 28153),
(157395, 'esMX', 'Jejeje... ¡carne fresca!', '', 28153),
(157394, 'esMX', '¡Siente la furia de la naturaleza!', '', 28153),
(157393, 'esMX', '¡Te convertiré en escombros!', '', 28153),
(157392, 'esMX', '¿Estás seguro de que quieres continuar?', '¿Estás segura de que quieres continuar?', 28153),
(157391, 'esMX', 'Buen trabajo, $p. El Valle Canto Tormenta tiene una deuda impagable contigo.', '', 28153),
(157390, 'esMX', 'Sueña, sueña con la Ciudad Sumergida.', 'Sueña, sueña con la Ciudad Sumergida.', 28153),
(157389, 'esMX', 'A la sombra de su mirada invariable...', 'A la sombra de su mirada invariable...', 28153),
(157388, 'esMX', 'Perdido en su abrazo implacable...', 'Perdida en su abrazo implacable...', 28153),
(157387, 'esMX', 'Para absorber de los ahogados la sabiduría...', 'Para absorber de los ahogados la sabiduría...', 28153),
(157386, 'esMX', 'Los sobrevivientes del Recinto de Colinas Temibles han estado luchando durante días. Ayúdalos y dales un momento para descansar.', '', 28153),
(157383, 'esMX', '¡Qué cantidad de explosiones! Me alegra ver que Toki y tú siguen $uenteros:enteras;.', '', 28153),
(157382, 'esMX', 'Bebe la profundidad de la marea brillante...', 'Bebe la profundidad de la marea brillante...', 28153),
(157381, 'esMX', 'Ventura y Cía. sigue destruyendo la costa. Reúnete con Toki y ayúdalo a lidiar con ellos.', '', 28153),
(157380, 'esMX', 'Uh...', 'Uh...', 28153),
(157379, 'esMX', 'Encuentras un altar ominoso. Las palabras inundan tu mente apenas le pones una mano encima.\n\n\"¿Cómo empezarás?\"', '', 28153),
(157378, 'esMX', 'Buen trabajo. Te debo un trago por esto.', '', 28153),
(157377, 'esMX', '¡Espera a que te ponga las zarpas encima!', '', 28153),
(157376, 'esMX', '¡Te haré pedazos!', '', 28153),
(157375, 'esMX', 'Quiero a los mareaférrea fuera de esta área. Veamos si aún quieren quedarse después de que convierta sus vidas en un martirio.', '', 28153),
(157374, 'esMX', '¡Por Drustvar!', '', 28153),
(157373, 'esMX', '¡Vamos! ¡Hay que convertir a ese monstruo en escombros!', '', 28153),
(157372, 'esMX', '', 'Los tortollano\' te agradecen la ayuda, al igual que yo.', 28153),
(157371, 'esMX', '', '¡Esos bruto\' de Ventura y Cía. siguen hostigando a los tortollano\'! Encuéntrate con Toki y ayúdalos, adalid.', 28153),
(157370, 'esMX', '', 'Nueh\'tros enemigo\' sabrán que un adalid de la Horda puso fin a sus plane\'. Bien hecho.', 28153),
(157369, 'esMX', '', '¡Nuestros enemigo\' cobran cada día más valor! Quítales los recurso\'... y la vida, si es necesario.', 28153),
(157368, 'esMX', '', 'Nos fortalecemo\' mientras nuestro enemigo se debilita. A veces las pequeñas victorias llevan a un triunfo mayor.', 28153),
(157367, 'esMX', '', 'Los soldado\' no pueden ganar una guerra con la panza vacía. La carne de oso alimentará a nueh\'tras tropas. Que el enemigo no interfiera.', 28153),
(157362, 'esMX', 'Por el lugar deambulan cosas ancestrales que no deberían existir. No bajes la guardia.', 'Por el lugar deambulan cosas ancestrales que no deberían existir. No bajes la guardia.', 28153),
(157361, 'esMX', '¡No imaginábamos que los muertos podían caminar!', '¡No esperábamos que los muertos se levantaran y caminaran!', 28153),
(157360, 'esMX', '¡No esperábamos un poder semejante! Ten cuidado, continental.', '¡No esperábamos un poder semejante! Ten cuidado, continental.', 28153),
(157359, 'esMX', 'Hay que destruir los ensamblajes. ¡Por favor, ayúdanos!', 'Hay que destruir los ensamblajes. ¡Por favor, ayúdanos!', 28153),
(157358, 'esMX', 'Una ayuda más que oportuna, continental.', 'Una ayuda más que oportuna, continental.', 28153),
(157357, 'esMX', '$p, alto. ¿Ves eso?', '', 28153),
(157356, 'esMX', 'Se han marchado por ahora, y la ciudad sigue de pie. Te debemos la vida.', '', 28153),
(157355, 'esMX', 'La Horda ha regresado con más fuerza para terminar el trabajo. ¡Haz todo lo que sea necesario para detenerlos!', '', 28153),
(157354, 'esMX', 'En general se las arregla solo, pero sabe reconocer cuándo está en apuros. ¡Gracias por ayudarlo!', '', 28153),
(157353, 'esMX', 'Campoáureo dice que necesita una mano. Siguen los ataques a su granja y se le acaban los suministros. Bríndale toda la ayuda que puedas.', '', 28153),
(157352, 'esMX', '¡Lo pensarán dos veces antes de volver a intentarlo! Dale a ese perro un bocadillo extra de mi parte.', '', 28153),
(157351, 'esMX', 'Los jabaespines intentan expandir su red de túneles y ponen al valle en peligro. Nuestros canes pueden rastrearlos y espantarlos si saben dónde buscar.', '', 28153),
(157350, 'esMX', '$p, andando.', '', 28153),
(157349, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t ¡|cFFFF0000|Hspell:272536|h[Ruina inminente]|h|r te ha afectado!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t ¡|cFFFF0000|Hspell:272536|h[Ruina inminente]|h|r te ha afectado!', 28153),
(157348, 'esMX', '¿Sabes? Eh\'ta cámara sería ideal para exhibir la colección real de antigüedade\'. Quizás deberíamos...', '', 28153),
(157347, 'esMX', '', 'Estaré cerca.', 28153),
(157346, 'esMX', 'Shandris, no llames la atención. Quédate en las sombras... si puedes encontrar alguna.', '', 28153),
(157345, 'esMX', '', '¡10-4, alto comandante! ¡A volar!', 28153),
(157344, 'esMX', 'Kelsey, necesitamos que seas nuestros ojos en el cielo. Regresa si ves algo.', '', 28153),
(157343, 'esMX', '¿Podrías repetir el plan?', '¿Podrías repetir el plan?', 28153),
(157342, 'esMX', 'Mis padres siempre me dijeron que tenía demasiada imaginación.', '', 28153),
(157341, 'esMX', '¡A veces bajábamos por las colinas de un valle en una carreta! ¡Fingíamos que Hobbs era un tigre!', '', 28153),
(157340, 'esMX', 'Hobbs y yo compartimos todo tipo de aventuras cuando éramos niños.', '', 28153),
(157339, 'esMX', 'Muéstrame.', 'Muéstrame.', 28153),
(157338, 'esMX', 'Las visiones pueden ayudarnos a observar la carnicería, $r.', 'Las visiones pueden ayudarnos a observar la carnicería, $r.', 28153),
(157337, 'esMX', 'Pronto su fulgor bañará a la flota, y todo Kul Tiras se arrodillará ante la luz de las mareas.', '', 28153),
(157336, 'esMX', 'No ves nada. Los dones de la Madre de las mareas nos han fortalecido una vez más.', '', 28153),
(157335, 'esMX', 'Almas de los corruptos, cumplirán nuestros juramentos. ¡Derriben esta puerta!', '', 28153),
(157334, 'esMX', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t ¡La ancestra Leaxa empieza a lanzar |cFFF00000|Hspell:264603|h[Espejo de sangre]|h|r!', 28153),
(157333, 'esMX', '', 'Tengo un buen presentimiento con esta cueva. Imagino que hay una gran cantidad de oro dentro.', 28153),
(157332, 'esMX', '¡Pero estaba llegando a la parte en la que me zambullí en su garganta y lo degollé por dentro!', '¡Pero estaba llegando a la parte en la que me zambullí en su garganta y lo rebané!', 28153),
(157331, 'esMX', 'De acuerdo, de acuerdo, Line y Cebo me ayudaron. Pero todo lo demás es cierto... ¡cada palabra!', 'De acuerdo, de acuerdo, Line y Cebo me ayudaron. Pero todo lo demás es cierto... ¡cada palabra!', 28153),
(157330, 'esMX', '¡Mpf mpf mpf mpf, mpf mpf!', '¡Mpf mpf mpf mpf, mpf mpf!', 28153),
(157329, 'esMX', 'Cierra el pico, Line. ¡Espera tu turno!', 'Cierra el pico, Line. ¡Espera tu turno!', 28153),
(157328, 'esMX', '', 'No hay oro, ¡pero sí mucho ron!', 28153),
(157327, 'esMX', '¡Exacto! ¡Con mi pericia en pesca!', '¡Exacto! ¡Con mi pericia en pesca!', 28153),
(157326, 'esMX', 'Gracias a mi gran astucia, sabía exactamente cómo derribar a la bestia.', 'Gracias a mi gran astucia, sabía exactamente cómo derribar a la bestia.', 28153),
(157325, 'esMX', 'Y entonces la vi, acercándose desde el horizonte. ¡Una bestia como ninguna que hubiera visto jamás!', 'Cuando la vi, acercándose desde el horizonte. ¡Una bestia como ninguna que haya visto jamás!', 28153),
(157324, 'esMX', 'Yo cumplía con la primera guardia, atento a la presencia de esos asquerosos nagas.', 'Yo cumplía con la primera guardia, atento a la presencia de esos asquerosos nagas.', 28153),
(157323, 'esMX', 'Ahora, déjame contarte cómo conocí a estos dos pésimos marineros.', 'Ahora, permíteme contarte cómo conocí a estos dos pésimos marineros.', 28153),
(157322, 'esMX', 'Sí, hasta yo concuerdo... ¡Ey, ey, un momento!', 'Sí, y hasta concuerdo... ¡Ey, ey, un momento!', 28153),
(157321, 'esMX', 'Ese yelmo debe estar apretándote el cerebro. ¡Me resultaría más fácil creer que Line atrapó un pez!', 'Ese yelmo debe estar apretándote el cerebro. ¡Me resultaría más fácil creer que Line atrapó un pez!', 28153),
(157320, 'esMX', 'Mpf, mpf mpf mpf mpf. Mpf.', 'Mpf, mpf mpf mpf mpf. Mpf.', 28153),
(157319, 'esMX', '¡¡¡MPF!!!', '¡¡¡MPF!!!', 28153),
(157318, 'esMX', 'Mpf mpf... mpf.', 'Mpf mpf... mpf.', 28153),
(157317, 'esMX', 'Por fortuna, tenía mi bala especial colgada del cuello como siempre, y era justo lo que necesitaba.', 'Por fortuna, tenía mi bala especial colgada del cuello como siempre, y era justo lo que necesitaba.', 28153),
(157316, 'esMX', 'Protejo el ron hasta que regrese el capitán.', '', 28153),
(157315, 'esMX', 'Capitán... No bebí ni un sorbo.', '', 28153),
(157314, 'esMX', '', 'Y donde hay piratas, ¡normalmente hay oro!', 28153),
(157313, 'esMX', '', 'Algunos de los trabajadores dicen haber visto el fantasma de un pirata en esta cueva.', 28153),
(157312, 'esMX', '', 'Presabrenna está más adelante. ¡Vamos!', 28153),
(157311, 'esMX', '', 'Todo Kul Tiras está desprotegido sin ella. Solo es cuestión de tiempo antes de que nos ataquen.', 28153),
(157310, 'esMX', '', 'Tenemos que encontrar al hermano Pike de inmediato. Con suerte, él podrá ayudarnos a recuperar la flota.', 28153),
(157309, 'esMX', '', '¿No es majestuoso el valle? No me sorprende que haya tanta gente que se asienta aquí.', 28153),
(157308, 'esMX', '', 'Este camino es la única ruta terrestre hacia el valle. La casa Canto Tormenta trama algo.', 28153),
(157307, 'esMX', '', 'Presabrenna es el punto de comercio más grande de Kul Tiras fuera de Boralus.', 28153),
(157306, 'esMX', '¡Mas rápido, holgazanes!', '¡Pónganse a trabajar, sacos de carne perezosos!', 28153),
(157305, 'esMX', 'Está ahí arriba. ¡Dos cabezas y enorme!', '¡Está ahí arriba, preparándose para atacar!', 28153),
(157304, 'esMX', 'Ocúpate de tu propio panal y no molestes. ¡Es un asunto oficial!', 'Ocúpate de tu propio panal y no molestes. ¡Es un asunto oficial!', 28153),
(157303, 'esMX', '¿Qué tramas? ¡Tienes que evacuar, como todos nosotros!', '¿Qué tramas? ¡Tienes que evacuar, como todos nosotros!', 28153),
(157302, 'esMX', '¡Cuidado con el garrote!', 'Será mejor que corras, Tom. ¡Somos muchos más!', 28153),
(157301, 'esMX', 'Los dos te culpamos... por esto...', 'Los dos te culpamos... por esto...', 28153),
(157300, 'esMX', 'Enfréntame... ¡a mí y a mi otro yo!', 'Enfréntame... ¡a mí y a mi otro yo!', 28153),
(157299, 'esMX', 'Me quedaré con la cabeza derecha.', 'Es más grande de lo que pensé.', 28153),
(157298, 'esMX', 'Inspeccionando', 'Inspeccionando', 28153),
(157296, 'esMX', 'Bienvenidos, amiguitos. ¡Escuchen esta canción nueva que he aprendido!', '', 28153),
(157294, 'esMX', '¡Morirás! ¡Y luego aplastaré a toda la gente de la ciudad!', '¡Morirás! ¡Y luego aplastaré a toda la gente de la ciudad!', 28153),
(157293, 'esMX', 'Los Estela de la Tormenta guiaremos la flota hacia la victoria por la Alianza, como antes.', '', 28153),
(157292, 'esMX', '', 'La casa Tarjasenda la respalda, Lady almirante. Y también a la Alianza.', 28153),
(157291, 'esMX', '', 'Y que renovemos nuestro vínculo con la Alianza, cuyos héroes nos han salvado de nuestra propia ruina.', 28153),
(157290, 'esMX', '', 'Les pido que confíen en mi hija Jaina... la verdadera Lady almirante de Kul Tiras.', 28153),
(157289, 'esMX', '', 'La Horda también ha dejado en claro sus intenciones. Esos salvajes quieren vernos arder.', 28153),
(157288, 'esMX', '', 'Las divisiones nos han vuelto vulnerables. Nos asedian enemigos internos.', 28153),
(157287, 'esMX', '', 'Gracias a todos por venir. Seré breve.', 28153),
(157286, 'esMX', '¡Apuesto a que entre los dos podríamos expulsar a estos monstruos!', '', 28153),
(157285, 'esMX', 'Cuando Daelin me pidió que dejara su guardia y criara a esta criatura de los Reinos del Este, me costó mucho esfuerzo comprender por qué. \n\n¿Por qué me confiaría una tarea semejante a mí? ¿Por qué me negaría el honor de luchar a su lado? Creí que quizás había hecho algo que lo hizo perder su fe en mí. \n\nCon los años, aprendí que en realidad fue todo lo contrario. Quería que Taelia creciera con un brazo fuerte y un corazón noble, y confió en mí para hacer que eso sucediera.', '', 28153),
(157284, 'esMX', '', '¿Es cierto que se puede viajar desde Ventormenta a Forjaz en una especie de túnel subterráneo?$B$B¡Eso suena increíble! Me encantaría verlo algún día.', 28153),
(157283, 'esMX', '¡Y eso fue apenas una pizca! Imagínate el daño que podrían hacer con más.', '', 28153),
(157282, 'esMX', '', 'Gracias. Espero que los granjeros puedan volver a sus campos ahora.', 28153),
(157281, 'esMX', '', 'Hay una criatura por aquí que amenaza a los granjeros. ¡Tenemos que ayudarlos!', 28153),
(157280, 'esMX', '', '¡Excelente! Apuesto a que encontrarán un uso para los suministros de inmediato.', 28153),
(157279, 'esMX', '', 'Espero que llegue el día en que los ciudadanos kultiranos puedan volver a confiar en la guía de los maresabios. Hasta entonces, debemos trazar nuestro propio camino.', 28153),
(157278, 'esMX', '', 'Nos has brindado el respiro que tanto necesitábamos. Gracias.', 28153),
(157277, 'esMX', '', 'El pueblo de Canto Tormenta no olvidará tus acciones. ¡Bien hecho!', 28153),
(157276, 'esMX', '', 'Estas colinas rebosan de recursos cruciales para los esfuerzos de Estela de la Tormenta. ¿Puedes ayudarlos?', 28153),
(157275, 'esMX', '', 'Las fuerzas de Lord Canto Tormenta están causando problemas de nuevo. ¡Sus rituales oscuros no pueden continuar!', 28153),
(157274, 'esMX', '', '¡Hemos perdido el control del área! ¡Ve y desplaza al enemigo!', 28153),
(157273, 'esMX', '', 'Estela de la Tormenta necesita tu ayuda aquí. ¡Haz todo lo que puedas para recuperar la paz del valle!', 28153),
(157272, 'esMX', '', '¡Cañoneros! ¡Prepárense para la tromba final!', 28153),
(157271, 'esMX', '', '¡Mantengan el escudo! ¡Sin él, se caerá a pedazos!', 28153),
(157270, 'esMX', 'Una Renegada. Jamás pensé que... <tos>. Dígame, ¿señorita...?', '', 28153),
(157269, 'esMX', '<tose> La Horda. Y yo que pensaba que moriría en paz.\n\n¿Y tú eres $Uun Renegado:una Renegada;? Interesante, pero es demasiado tarde.\n\n¿Y bien? ¿Qué esperas?', '', 28153),
(157268, 'esMX', '¡Nos vemos en la carreta, $p!', '', 28153),
(157267, 'esMX', '', '¡Iuuuuju! ¡Hora de saquear!', 28153),
(157266, 'esMX', 'Llévame de vuelta.', 'Llévame de vuelta.', 28153),
(157265, 'esMX', 'Gracias por la ayuda que me has brindado hoy. Deberíamos volver.', 'Gracias por la ayuda que me has brindado hoy. Deberíamos volver.', 28153),
(157264, 'esMX', 'Observa el encuentro entre Zelling y su familia.', 'Observa el encuentro entre Zelling y su familia.', 28153),
(157263, 'esMX', 'Excelente, como siempre, mi $uamigo:amiga;. Si todos los miembros de la Alianza cabalgan como tú, ¡siempre serán bienvenidos en mi finca!', '', 28153),
(157262, 'esMX', 'Ah, ¡un día perfecto para un espectáculo! ¡Monta y demuestra tu destreza en la arena!', '', 28153),
(157261, 'esMX', '', 'Como tú quieras. Vamos, $n.', 28153),
(157260, 'esMX', 'Yo regresaré a la base. Ya sé cómo termina esto. No necesito verlo otra vez.', '', 28153),
(157259, 'esMX', 'Debes saber que estás entre los mejore\'. No te entrometa\' cuando esté con el señor aojador.', '', 28153),
(157258, 'esMX', '', '¡Fantástico! Eso debería frenar a los nagas.', 28153),
(157257, 'esMX', '', 'Te doy mi palabra. Ven. $n, regresemos con Nathanos e informémosle que tenemos lo que necesitamos.', 28153),
(157256, 'esMX', 'Me uniré a ustedes... y los ayudaré a encontrar al mariscal Valentine. Siempre y cuando me prometan que mi familia permanecerá a salvo.', '', 28153),
(157255, 'esMX', '', '¡Los nagas intentan atacar el fuerte de nuevo! ¡Encárgate de ellos al estilo tortollano!', 28153),
(157254, 'esMX', '', 'Acepta a los Renegados y forja tu propio camino. Estarás rodeado por los únicos que te aceptarán por quien eres ahora.', 28153),
(157253, 'esMX', '¿Y ahora qué soy? ¿Un sirviente descerebrado de la Reina alma en pena?', '', 28153),
(157252, 'esMX', '', 'Eh\'te es un honor que pocas vece\' se otorga a alguien que no es de Zandalar. Ven, camina conmigo y comparte las hazaña\' de Vol\'jin.', 28153),
(157250, 'esMX', '', 'Traté de advertirte, Zelling. El proceso te cambia. Los vivos ya no te aceptarán.', 28153),
(157249, 'esMX', 'No... Julia... Matthew... Hannah... ¿Qué he hecho? ¿Qué... qué soy?', '', 28153),
(157248, 'esMX', '', '¡Que el monstruo se aleje de nosotros!', 28153),
(157247, 'esMX', '', '¡Déjanos en paz!', 28153),
(157246, 'esMX', '¡Que se vaya!', '', 28153),
(157245, 'esMX', '¡Silencio!', '', 28153),
(157244, 'esMX', '', 'No sé quién serás, pero mi marido JAMÁS nos levantó la mano, ni a mí ni a mis hijos. Nos iremos... ¡no nos sigas!', 28153),
(157243, 'esMX', 'Yo... yo...', '', 28153),
(157242, 'esMX', '¡BASTA!', '', 28153),
(157241, 'esMX', '¡Mamá! ¡Ayúdanos!', '', 28153),
(157240, 'esMX', '', '¡Fuera de aquí!', 28153),
(157239, 'esMX', 'Papá está aquí. ¡Escuchen mi voz! ¡¿Cómo puede ser que no lo entiendan?!', '', 28153),
(157238, 'esMX', '', '¡Aléjate!', 28153),
(157237, 'esMX', '¡Mami, este monstruo me da miedo!', '', 28153),
(157236, 'esMX', '¡¿Por qué no quieres entenderlo?! ¡Soy tu esposo...! ¡Niños, soy su padre!', '', 28153),
(157235, 'esMX', '', 'Lo diré por última vez: ¡NO TE ACERQUES! ¡NO ERES mi marido!', 28153),
(157234, 'esMX', 'Mi fuerza no me abandona... ni en la muerte.', '', 28153),
(157233, 'esMX', '¡No viniste $Upreparado:preparada; para enfrentarme en combate!', '', 28153),
(157232, 'esMX', 'Zelling, necesitamos que encuentres el cadáver del mariscal Valentine.', 'Zelling, necesitamos que encuentres el cadáver del mariscal Valentine.', 28153),
(157231, 'esMX', 'Mi familia me... vengará.', '', 28153),
(157230, 'esMX', '¡Serás el foco de mi ira!', '', 28153),
(157229, 'esMX', '', 'Supongo que tendremos que ver qué sucederá ahora.', 28153),
(157228, 'esMX', 'Estoy... ¡estoy vivo! ¡Ja, ja! Debo ver a Julia y a mis hijos con mis propios ojos. ¡Estarán encantados!', '', 28153),
(157227, 'esMX', '', 'Pocos espíritu\' han demostrado semejante... poder. Maestro Gadrin, lo invito a llevar las ceniza\' de eh\'te jefe a Atal\'Dazar. Si su espíritu es digno, quizá pueda ocupar un lugar de honor entre nueh\'tros reyes.', 28153),
(157226, 'esMX', 'Zalazane no regresará de eso. Aún en la muerte, Vol\'jin nos vigila.', '', 28153),
(157225, 'esMX', 'Los muerto\', están cayendo...', '', 28153),
(157224, 'esMX', 'Nuestros refuerzos esperan tus órdenes.', '', 28153),
(157223, 'esMX', 'Si la Horda quiere guerra, ¡les daremos lo que quieren!', '', 28153),
(157222, 'esMX', 'Espero que traigas buenas noticias.', '', 28153),
(157221, 'esMX', 'Canto Tormenta resistirá.', '', 28153),
(157220, 'esMX', 'Buen viaje.', '', 28153),
(157219, 'esMX', 'Que las mareas te guíen.', '', 28153),
(157218, 'esMX', '¡Excelente! Los suministros sin duda nos serán útiles y les encontraremos algún propósito a esos cerditos.', '', 28153),
(157217, 'esMX', 'Los jabaespines han estado asaltando nuestros almacenes otra vez. Lo justo es justo; ¡recupera nuestros suministros y toma todo lo que parezca útil!', '', 28153),
(157216, 'esMX', 'Enseguida.', '', 28153),
(157215, 'esMX', '', '¡Sí, señor!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'esMX', '', 'Misericordiosa Elune, bendice a los caídos.', 28153),
(157213, 'esMX', 'Taelia, prepárate para hacer tu ronda de nuevo. Dile a la guardia de la ciudad que investigue todas las armas que entren a Boralus, especialmente las poco comunes.', '', 28153),
(157212, 'esMX', '', 'Que todo\' sepan que Vol\'jin, hijo de Sen\'jin, es digno de eh\'tas tumba\' sagradas. Habrá que luchar para entrar en Atal\'Dazar. Recomiendo que $Uel:la; adalid lleve esta\' cenizas a su lugar de deh\'canso final.', 28153),
(157211, 'esMX', '', 'Es duro encargarte de lo que deberían hacer tus lídere\'.', 28153),
(157210, 'esMX', 'Cuando fue evidente que Garrosh, nueh\'tro jefe de guerra, no esh\'taba dispuesto a liderar con honor, Vol\'jin lideró la rebelión para destituirlo.', '', 28153),
(157209, 'esMX', '', 'En esos tiempo\', la visión de Zul acerca de un gran imperio trol fue muy tentadora para mi padre. Mis respeto\' para tu jefe, que pudo ver lo que realmente sucedía.', 28153),
(157208, 'esMX', 'Cuando Zandalar quiso unir a las tribu\' de trols, Vol\'jin eligió la seguridad de su pueblo y no los podere\' oscuro del profeta.', '', 28153),
(157207, 'esMX', 'Vol\'jin hizo un trato con Bwonsamdi para derrotar al poderoso Zalazane.', '', 28153),
(157206, 'esMX', '', 'Hay más fuegos fatuos de los que puedo contar. Tantas vidas perdidas...', 28153),
(157205, 'esMX', 'Traemo\' las cenizas de Vol\'jin, hijo de Sen\'jin, para honrarlas en eh\'te lugar sagrado.', '', 28153),
(157204, 'esMX', 'Flynn, tengo otro trabajo para ti. Ayuda a nuestro nuevo aliado a rastrear el origen de esta pólvora.', '', 28153),
(157203, 'esMX', 'En estas tierras se agitan amenazas ancestrales. Ten cuidado.', '', 28153),
(157202, 'esMX', 'Clamavientos, he venido por orden de la jefa de guerra.', 'Clamavientos, he venido por orden de la jefa de guerra.', 28153),
(157201, 'esMX', 'Sí, tengo que ir a Silithus.', 'Sí, tengo que ir a Silithus.', 28153),
(157200, 'esMX', '¿Por qué estoy aquí, humano?', '¿Por qué estoy aquí, humano?', 28153),
(157199, 'esMX', '¡$UEmisario:Emisaria;! ¿Podrías darles una demostración a nuestros colegas escépticos?', '', 28153),
(157198, 'esMX', 'No como estas, no.', '', 28153),
(157197, 'esMX', '¿Y por qué dices que esto es una pista? Todo el tiempo fabrican armas nuevas.', '', 28153),
(157196, 'esMX', '', 'Bien, Flynn. ¿Cuál era pista de la que hablabas? ¿Algo de una nueva pólvora de los Aspafresno?', 28153),
(157195, 'esMX', 'Necesito un jinete del viento para llegar al Refugio de Marshal, en el Cráter de Un\'Goro.', 'Necesito un jinete del viento para llegar al Refugio de Marshal, en el Cráter de Un\'Goro.', 28153),
(157194, 'esMX', 'Regresaste... ¡Excelente! ¡Me atemorizaba tener que decirle a la princesa que un enano de diamante\' había secuestrado a su adalid!', '', 28153),
(157193, 'esMX', '¡Guau! ¡Hicimos un excelente trabajo!', '', 28153),
(157192, 'esMX', 'Debemos recuperar el cargamento perdido. Es decir... \"debes\".', '', 28153),
(157191, 'esMX', 'No sé a dónde vas, pero eh\'pero que regreses pronto. ¡La princesa necesita tu ayuda!', 'No sé a dónde vas, pero eh\'pero que regreses pronto. ¡La princesa necesita tu ayuda!', 28153),
(157190, 'esMX', '¡Esto e\' extraordinario! Debería tomar notas.', '¡Esto e\' extraordinario! Debería tomar notas.', 28153),
(157189, 'esMX', 'Proteger las líneas de suministros es esencial para la guerra... tan esencial como desbaratar las del enemigo.', '', 28153),
(157188, 'esMX', 'Ah, sí. Disfrútalo, deléitate. Naufragios de la Alianza... ¡qué agradable vista! Registra la zona y busca suministros que le sirvan a la Horda.', '', 28153),
(157187, 'esMX', 'Un día más en el trabajo.', '', 28153),
(157186, 'esMX', '¡Están atacando al extractor! ¡Protégelo!', '', 28153),
(157185, 'esMX', 'Esos recursos son el combustible vital de la labor de la Horda. Bien hecho.', '', 28153),
(157184, 'esMX', '¡Protege nuestro extractor! ¡Necesitamos esa azerita!', '', 28153),
(157183, 'esMX', '¿Cuál es tu estrategia, Shandris?', '¿Cuál es tu estrategia, Shandris?', 28153),
(157182, 'esMX', '', '<Los ojos insuperables de Shandris registran el horizonte. Mira en tu dirección y asiente.>', 28153),
(157181, 'esMX', 'Encontrar a Vigía del Sol y llenarlo de flechas.', '', 28153),
(157180, 'esMX', '¿Mi estrategia?', '', 28153),
(157179, 'esMX', 'El equipo de operaciones especiales de Gnomeregan plantará las bombas para provocar a Vigía del Sol, y luego lo atacaremos cuando reine la confusión.', '', 28153),
(157178, 'esMX', '', '¡Eh, eh!', 28153),
(157177, 'esMX', '¡Afirmativo! Para llevar a cabo esa misión, he enlistado un equipo de comandos especializados en explosiones.', '', 28153),
(157176, 'esMX', '', 'Quieres... hacer estallar unas cuantas bombas al mismo tiempo.', 28153),
(157175, 'esMX', 'Me gustaría ejecutar un ataque incendiario sincronizado a todos los sitios de excavación.', '', 28153),
(157174, 'esMX', 'Sí. Nuestros informes nos sugieren que hay tres excavaciones.', '', 28153),
(157173, 'esMX', '', '¿Arqueología?', 28153),
(157172, 'esMX', 'Vigía del Sol está aquí, como miembro del Relicario, para cumplir una misión arqueológica.', '', 28153),
(157171, 'esMX', 'Yo... No lo recuerdo. Mejor así.', '', 28153),
(157170, 'esMX', '', 'Disculpa, $uamigo:amiga;... ¿quién me dijiste que eras? ¿Fue de ti que me habló Malfurion?', 28153),
(157168, 'esMX', 'Le entregué tu nota a B\'wizati.', 'Le entregué tu nota a B\'wizati.', 28153),
(157167, 'esMX', '', 'Y los civiles... Ni siquiera a ellos perdonaron. Solo espero que algunos hayan conseguido escapar antes.', 28153),
(157166, 'esMX', '', 'Atacaron nuestros puestos de avanzada por sorpresa. Cayeron de a uno. Envenenaron a los guardias.', 28153),
(157165, 'esMX', '', '%s se levanta y se seca una lágrima.', 28153),
(157164, 'esMX', '', 'Intentamos tenderle una trampa a la Horda. Falló. No pudimos detenerlos.', 28153),
(157163, 'esMX', 'Es bueno ver que estás bien, $n. \n\nYo también eh\'toy bien.\n\nAkunda me ha dado la oportunidad de empezar de cero.', '', 28153),
(157162, 'esMX', '¿Cuál es su plan, alto comandante?', '¿Cuál es su plan, alto comandante?', 28153),
(157161, 'esMX', 'La Séptima Legión representa lo mejor que Azeroth tiene para ofrecer.\n\n¡Por la Alianza!', '', 28153),
(157160, 'esMX', '¿Quién? Creo que no conozco a ningún trol con ese nombre, ¿o sí?', '', 28153),
(157159, 'esMX', '', 'Los cuerpos... tantos cuerpos...', 28153),
(157158, 'esMX', 'Hay algo que $n necesita ver. Un don que podría ayudar a la gente de esta tierra.', '', 28153),
(157157, 'esMX', 'Un enano... hecho de diamante\'... ¡en el corazón de Zuldazar! ¿Quién...?', '', 28153),
(157156, 'esMX', '', 'He visto cosas extrañas en estos bosques, pero nada como esto.', 28153),
(157155, 'esMX', '¿Siente\' eso? La tierra eh\'tá temblando...', '', 28153),
(157153, 'esMX', 'La jefa de guerra me ordenó que te asistiera.', 'La jefa de guerra me ordenó que te asistiera.', 28153),
(157152, 'esMX', 'Tengo que volar a Gadgetzan, en Tanaris.', 'Tengo que volar a Gadgetzan, en Tanaris.', 28153),
(157151, 'esMX', 'Debes...', '', 28153),
(157150, 'esMX', '¡Prefiero... maldecir mi alma... por toda la eternidad… para hacer feliz a mi familia... por favor! Debes...', '', 28153),
(157149, 'esMX', '', 'Me lo pregunto todos los días, Zelling.', 28153),
(157148, 'esMX', 'Objetivo en la mira.', '', 28153),
(157147, 'esMX', '', 'Todos enloquecimos un poco cuando nos volvimos Renegados. Algunos más que otros.', 28153),
(157146, 'esMX', '¿Conoces a Akunda?', '¿Conoces a Akunda?', 28153),
(157145, 'esMX', 'Deja que Akunda te libere de todo lo que aflige a tu corazón.', 'Deja que Akunda te libere de todo lo que aflige a tu corazón.', 28153),
(157144, 'esMX', 'Akunda nos da una oportunidad para volver a empezar.', 'Akunda nos da una oportunidad para volver a empezar.', 28153),
(157143, 'esMX', 'Siempre serás $Ubienvenido:bienvenida; aquí.', 'Siempre serás $Ubienvenido:bienvenida; aquí.', 28153),
(157142, 'esMX', 'El loa recibe a todos en su templo.', 'El loa recibe a todos en su templo.', 28153),
(157141, 'esMX', '¿Conoces a Akunda?', '¿Conoces a Akunda?', 28153),
(157140, 'esMX', 'Deja que Akunda te libere de todo lo que aflige a tu corazón.', 'Deja que Akunda te libere de todo lo que aflige a tu corazón.', 28153),
(157139, 'esMX', 'Akunda nos da una oportunidad para volver a empezar.', 'Akunda nos da una oportunidad para volver a empezar.', 28153),
(157138, 'esMX', 'Siempre serás $Ubienvenido:bienvenida; aquí.', 'Siempre serás $Ubienvenido:bienvenida; aquí.', 28153),
(157137, 'esMX', 'El loa recibe a todos en su templo.', 'El loa recibe a todos en su templo.', 28153),
(157136, 'esMX', 'Estoy aquí para ayudar, Nyse.', 'Estoy aquí para ayudar, Nyse.', 28153),
(157135, 'esMX', 'Ah, la pesadilla ha terminado.', 'Ah, la pesadilla ha terminado.', 28153),
(157134, 'esMX', '¡Armados y listos! ¡Manden a ese kraken de vuelta a las profundidades!', '¡Armados y listos! ¡Manden a ese kraken de vuelta a las profundidades!', 28153),
(157133, 'esMX', '¡Todo listo para disparar!', '¡Todo listo para disparar!', 28153),
(157132, 'esMX', 'Doras, necesito volar hasta Piñón de Barro, en Marjal Revolcafango.', 'Doras, necesito volar hasta Piñón de Barro, en Marjal Revolcafango.', 28153),
(157131, 'esMX', '¡Cañones listos! ¡Conviertan a esa bestia en carnada!', '¡Cañones listos! ¡Conviertan a esa bestia en carnada!', 28153),
(157130, 'esMX', 'No... ¡NO!', 'No... ¡NO!', 28153),
(157129, 'esMX', '¡Te agradezco! ¡Ahora prepararé este cañón para la venganza!', '¡Te agradezco! ¡Ahora prepararé este cañón para la venganza!', 28153),
(157128, 'esMX', 'Zabanji ronca.', 'Zabanji ronca.', 28153),
(157127, 'esMX', '¡Te debo una! Solo dame un segundo para poner en marcha este cañón.', '¡Uuf, Te debo una! Solo dame un segundo para poner en marcha este cañón.', 28153),
(157126, 'esMX', '¿Fue todo un sueño?', '¿Fue todo un sueño?', 28153),
(157125, 'esMX', '¡No dejes que esta bestia me coma!', '¡No dejes que esta bestia me coma!', 28153),
(157124, 'esMX', '¡Redúzcanlos a cenizas a todos!', '', 28153),
(157123, 'esMX', '¡Quítenme esta cosa!', '¡Quítenme esta cosa!', 28153),
(157122, 'esMX', '$p, toma una antorcha y golpea todo lo que se mueva. ¡Estas abominaciones no-muertas no merecen consideración!', '', 28153),
(157121, 'esMX', 'Exacto, soldado. Y hay una cantidad infinita de monstruos para matar en este puerto infame.', '', 28153),
(157120, 'esMX', '¡Ayuda!', '¡Ayuda!', 28153),
(157119, 'esMX', 'Y nadie podrá arrebatarnos a nuestras víctimas, señor.', '', 28153),
(157118, 'esMX', '¿Quién eres? ¿Dónde estamos?', '¿Quién eres? ¿Dónde estamos?', 28153),
(157117, 'esMX', 'No habrá apoyo ni rescate si fallamos.', '', 28153),
(157116, 'esMX', 'Escuchen, soldados. Esta es una misión no autorizada.', '', 28153),
(157115, 'esMX', '¿Qué esperas, $p?\n\nTenemos armas y tenemos un enemigo. ¡Sube al bote!', '¿Qué esperas, $p?\n\nTenemos armas y tenemos un enemigo. ¡Sube al bote!', 28153),
(157114, 'esMX', 'Akunda el Fatigado ronca.', 'Akunda el Fatigado ronca.', 28153),
(157113, 'esMX', 'Todos somo\'... Akunda.', 'Todos somo\'... Akunda.', 28153),
(157112, 'esMX', '¿Más trabajo?', '', 28153),
(157111, 'esMX', 'Como diga.', '', 28153),
(157110, 'esMX', 'Muy bien.', '', 28153),
(157109, 'esMX', 'Sí, milord.', '', 28153),
(157108, 'esMX', '', 'Sí, señor.', 28153),
(157107, 'esMX', 'Bien. Seguiremos sin ella. Si no llega pronto... preparen sus espadas.', '', 28153),
(157106, 'esMX', '', 'Le está llevando... un tiempo acostumbrarse.', 28153),
(157105, 'esMX', '', 'Hnn.... gh....', 28153),
(157104, 'esMX', 'Stone, sé amable y comparte el nombre del héroe de guerra más importante de este cementerio.', '', 28153),
(157103, 'esMX', 'Ahora que estás aquí, podemos empezar.', '', 28153),
(157102, 'esMX', '¡Luchen por sus hermanos y hermanas!', '¡Luchen por sus hermanos y hermanas!', 28153),
(157101, 'esMX', '¡Victoria para la Alianza!', '¡Victoria para la Alianza!', 28153),
(157100, 'esMX', '¡A la batalla!', '¡A la batalla!', 28153),
(157099, 'esMX', 'Te encargaste muy bien de eso, $p. Esta noche todos volverán sanos y salvos.', '', 28153),
(157098, 'esMX', '¡Arathi nos pertenece!', '¡Arathi nos pertenece!', 28153),
(157097, 'esMX', '¡Muerte a la Horda!', '¡Muerte a la Horda!', 28153),
(157096, 'esMX', '¡Síganme!', '¡Síganme!', 28153),
(157095, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(157094, 'esMX', '¡Por aquí! ¡Tenemos una guerra que ganar!', '¡Por aquí! ¡Tenemos una guerra que ganar!', 28153),
(157093, 'esMX', 'La Horda ha ahuyentado a la fauna de aquí hacia los bajíos. Ayuda a los cazadores a encargarse de los osos.', '', 28153),
(157092, 'esMX', 'Hiciste... ¡Hiciste que matara a mi amigo! ¡Morirás!', '', 28153),
(157091, 'esMX', 'Hermanos y hermanas, ¡contemplen nuestro glorioso destino!', '', 28153),
(157090, 'esMX', 'Gracias, $Uamigo:amiga;. Todo el valle te apoya.', 'Me alegra tanto verte, $p. No olvidaré esto.', 28153),
(157089, 'esMX', 'Ahora puedo seguir solo. Ten cuidado.', '¡Qué alegría verte!', 28153),
(157088, 'esMX', '¡Creí que moriría!', 'Gracias, no lo olvidaré.', 28153),
(157087, 'esMX', '¡Ja! Quizás los jabalíes no sean tan malos después de todo. Me pregunto si les gustarán las almejas al vapor...', '', 28153),
(157086, 'esMX', 'Hemos visto algunos jabalíes desprotegidos fuera del horado. Si estás $Udispuesto:dispuesta; a montar uno, ¡podemos usarlos contra los jabaespines!', '', 28153),
(157085, 'esMX', 'Véngame... Taptaf...', '', 28153),
(157084, 'esMX', '', 'Al fin... El tormento termina...', 28153),
(157083, 'esMX', '', 'Sí... Libertad...', 28153),
(157082, 'esMX', '', 'Era... una trampa...', 28153),
(157081, 'esMX', '', 'Je... La cazadora se convierte... en la presa...', 28153),
(157080, 'esMX', '', 'Viene por todos nosotros...', 28153),
(157079, 'esMX', '¡Un momento, su majestad! Ha llegado información nueva.', '', 28153),
(157078, 'esMX', '', 'No debía... pasar... esto', 28153),
(157077, 'esMX', '', '¡Qué bueno que la presa camine hacia su propia muerte!', 28153),
(157076, 'esMX', '', '¡Mira lo que ha entrado en mi zona de trampas!', 28153),
(157075, 'esMX', '', 'No eres muy grande, ¡pero de todas formas me quedaré con tu pellejo!', 28153),
(157074, 'esMX', '', '¡Me prometieron todas las recompensas del bosque!', 28153),
(157073, 'esMX', '', '¡Tu pellejo será un buen premio!', 28153),
(157072, 'esMX', '', '¡Otro pellejo para mi colección!', 28153),
(157071, 'esMX', 'Tú... caerás...', '', 28153),
(157070, 'esMX', 'Regreso a la tierra...', '', 28153),
(157069, 'esMX', 'El fin... se acerca...', '', 28153),
(157068, 'esMX', '¡¿Qué quieres?! ¡Vete!', '', 28153),
(157067, 'esMX', 'Mi alma... está corrompida...', '', 28153),
(157066, 'esMX', 'El velo se ha caído...', '', 28153),
(157065, 'esMX', '¡Thros lo consumirá todo!', '', 28153),
(157064, 'esMX', '¡Habla desde el más allá!', '', 28153),
(157063, 'esMX', '¡La venganza será nuestra, y también el tesoro!', '', 28153),
(157062, 'esMX', '¡Toma una antorcha y ponte a trabajar, $p!', '¡Toma una antorcha y ponte a trabajar, $p!', 28153),
(157061, 'esMX', 'Exacto. ¡Causaremos estrago\' y los enviaremo\' a todos a lo más profundo del mar!', '', 28153),
(157060, 'esMX', 'Así que los vamos a hacer arder, ¿verdad?', 'Así que los vamos a hacer arder, ¿verdad?', 28153),
(157059, 'esMX', 'Nuestra antigua tripulación maldita en el Puerto de Zem\'lan enviará grupos enorme\' de asalto hoy y nosotros somos uno de sus objetivo\'.', '', 28153),
(157058, 'esMX', '¡Bienvenidos de vuelta al mar salado, mis valiente\'!', '', 28153),
(157057, 'esMX', '¡Todos a cubierta!', '¡Todos a cubierta!', 28153),
(157056, 'esMX', 'Cuando logre recordar el hechizo, quizás me dejen volver con ellos. Tal vez sea... ¡Ta ergsi leinad!', '', 28153),
(157055, 'esMX', 'Taptaf, no sé si puedes entenderme, pero quería decirte que lamento mucho lo de tu polimorfia. Tu polimorfia permanente, claro.', '', 28153),
(157054, 'esMX', 'Me pregunto si tu nombre servirá, Taptaf. Probemos: ¡Nolem asi Taptaf!', '', 28153),
(157053, 'esMX', 'No es justo que me hayan echado, Taptaf. Les mostraré todo mi poder... Ehh... En cuanto recuerde el hechizo.', '', 28153),
(157052, 'esMX', 'Mmm, no. Parece que no era así.', '', 28153),
(157051, 'esMX', 'No recuerdo ese maldito hechizo. ¿Cómo era, Taptaf? Leinad... ¿Nos fatsug?', '', 28153),
(157050, 'esMX', '¡Al fin he abierto los ojos!', '', 28153),
(157049, 'esMX', '¡Tu sangre regará el bosque!', '', 28153),
(157048, 'esMX', '¡Rrrraaaaagh!', '', 28153),
(157047, 'esMX', 'Excelente trabajo. Quizás algún día este vuelva a ser un lugar de culto.', '', 28153),
(157046, 'esMX', 'Si no hacemos algo, esta magia corromperá las aguas cercanas. Demora a los maresabios todo lo que puedas.', '', 28153),
(157045, 'esMX', 'Que la marea guíe sus almas descarriadas hacia la paz.', '', 28153),
(157044, 'esMX', 'La oscura influencia de la casa Canto Tormenta llegó aquí de la mano de individuos particulares. Acaba con sus vidas antes de que sigan haciendo más daño.', '', 28153),
(157043, 'esMX', '¡Bien hecho! ¡Puedo ver el humo desde aquí! Volveremos a golpearlos apenas podamos.', '', 28153),
(157042, 'esMX', '¡Espero que te gusten los grifos! Ve a hablar con Bernadette Robels. Ha ideado un plan para atacar a la Horda en Fuerte Guerracolmillo.', '', 28153),
(157041, 'esMX', '', '¿Yarr?', 28153),
(157040, 'esMX', '¡Ere\' débil sin los loa! ¡Dale el golpe de gracia!', '', 28153),
(157039, 'esMX', '¡El maligno se eh\'conde detrás del poder de Rezan! ¡Se lo arrebataré!', '', 28153),
(157038, 'esMX', 'Recuerda, continental, teme a lo que acecha en las profundidades. Nada bueno vive en las sombras más oscuras.', '', 28153),
(157037, 'esMX', 'Algunos de los maresabios de aquí están tratando de invocar una fuerza que podría arrasar con Boralus. ¡Hay que detenerlos!', '', 28153),
(157036, 'esMX', '', 'Deja que ella te guíe: te llevará y te traerá de vuelta sin un rasguño.', 28153),
(157035, 'esMX', '', '¡Está lista para partir!', 28153),
(157034, 'esMX', '', 'Es la grifo más rápida del valle. Si alguien dice lo contrario, está mintiendo.', 28153),
(157033, 'esMX', '¡Luego te toca a ti!', '¡Luego te toca a ti!', 28153),
(157032, 'esMX', 'Tú y el pajarito no me agradan.', 'Tú y el pajarito no me agradan.', 28153),
(157031, 'esMX', '¡Yo también quiero volar!', '¡Yo también quiero volar!', 28153),
(157030, 'esMX', 'Odio a la Alianza.', 'Odio a la Alianza.', 28153),
(157029, 'esMX', '¡Mira! Qué lindo pajarito.', '¡Mira! Qué lindo pajarito.', 28153),
(157028, 'esMX', '', 'El Motor de reoriginación está lih\'to. Usémoh\'lo para poner fin a la plaga de G\'huun de una vez por toda\'.', 28153),
(157027, 'esMX', 'El motor de reoriginación está listo. Activémoslo y reventemos a G\'huun como la pústula purulenta que es.', '', 28153),
(157026, 'esMX', '¿Soy yo... quien terminó aplastado?', '¿Soy yo... quien terminó aplastada?', 28153),
(157025, 'esMX', '¡Miserable! ¡Te aplastaré como a un insecto!', '¡Miserable! ¡Te aplastaré como a un insecto!', 28153),
(157024, 'esMX', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(157023, 'esMX', '¡La cría de cuernoatroz ruge y corre en busca de su madre!', '¡La cría de cuernoatroz ruge y corre en busca de su madre!', 28153),
(157022, 'esMX', '¡Llévame!', '¡Llévame!', 28153),
(157021, 'esMX', '¿Te llevo a algún lado?', '¿Te llevo a algún lado?', 28153),
(157020, 'esMX', '', 'Everit te ha entrenado bien. Sé que estaría orgulloso de ti.', 28153),
(157019, 'esMX', '', 'Gracias, milady. No la defraudaré.', 28153),
(157018, 'esMX', '', 'La nombro mariscal Alborada y la designo jefa de la Guardia Tarjasenda.', 28153),
(157017, 'esMX', '', 'Pero Drustvar necesita sus servicios en asuntos más importantes.', 28153),
(157016, 'esMX', '', 'Inquisidora Alborada, ha superado todas nuestras expectativas. Demostró compasión, valentía, liderazgo y astucia.', 28153),
(157015, 'esMX', '', 'Todos hemos sufrido pérdidas, pero la luz de la esperanza brilla con fuerza.', 28153),
(157014, 'esMX', 'Nada personal.', 'Nada personal.', 28153),
(157013, 'esMX', 'Nuestro enemigo controla el Círculo de Elementos... por ahora.', 'Nuestro enemigo controla el Círculo de Elementos... por ahora.', 28153),
(157012, 'esMX', '¡Veo estandartes de la Horda en el Círculo de Elementos!', '¡Veo estandartes de la Horda en el Círculo de Elementos!', 28153),
(157011, 'esMX', '¡La Horda controla el Círculo de Elementos!', '¡La Horda controla el Círculo de Elementos!', 28153),
(157010, 'esMX', '¡El Círculo de Elementos luce nuestros estandartes!', '¡El Círculo de Elementos luce nuestros estandartes!', 28153),
(157009, 'esMX', 'Nuestras fuerzas controlan el Círculo de Elementos.', 'Nuestras fuerzas controlan el Círculo de Elementos.', 28153),
(157008, 'esMX', 'El Círculo de Elementos permanece bajo nuestro mando.', 'El Círculo de Elementos permanece bajo nuestro mando.', 28153),
(157007, 'esMX', 'Granovel luce los estandartes de la Horda... por ahora.', 'Granovel luce los estandartes de la Horda... por ahora.', 28153),
(157006, 'esMX', '¿Esos monstruos se creen capaces de controlar Granovel? Ya verán...', '¿Esos monstruos se creen capaces de controlar Granovel? Ya verán...', 28153),
(157005, 'esMX', 'Esas bestias no pueden ocupar Granovel por siempre.', 'Esas bestias no pueden ocupar Granovel por siempre.', 28153),
(157004, 'esMX', 'Nuestras fuerzas controlan Granovel.', 'Nuestras fuerzas controlan Granovel.', 28153),
(157003, 'esMX', 'Tenemos Granovel bajo nuestro control.', 'Tenemos Granovel bajo nuestro control.', 28153),
(157002, 'esMX', 'Parece que controlamos Granovel. Será mejor que eso no cambie.', 'Parece que controlamos Granovel. Será mejor que eso no cambie.', 28153),
(157001, 'esMX', 'El loa de reyes ha caído. Debemos tener cautela si nos lanzamos a otra cacería.\n\nRastakhan está malherido y envejece con rapidez. Solo el poder de Rezan podría frenar a Bwonsamdi. Le ofrecería mi poder, pero desafiar al loa de la muerte no es algo que yo pueda hacer.', '', 28153),
(157000, 'esMX', 'Diga, señora.', '', 28153),
(156999, 'esMX', '', 'La Señora de las bestias L\'kala mira al goblin que tiene a su lado con recelo.', 28153),
(156998, 'esMX', '', 'Parece que tu pequeño está cansado despué\' de tanta lucha. Aquí estará seguro. Yo misma lo cuidaré.', 28153),
(156996, 'esMX', 'La prole de cuernoatroz bosteza y cierra los ojos.', 'La prole de cuernoatroz bosteza y cierra los ojos.', 28153),
(156995, 'esMX', '¡Hora de irse!', '¡Hora de irse!', 28153),
(156994, 'esMX', 'Siento como si alguien me hubiera arrancado el alma del cuerpo.', '', 28153),
(156993, 'esMX', '¡Eso estuvo cerca! ¡Gracias por la ayuda!', '¡Eso estuvo cerca! ¡Gracias por la ayuda!', 28153),
(156992, 'esMX', '¡Te agradezco la ayuda! Por algún motivo, mis zapatillas antipegote fallaron.', '¡Te agradezco la ayuda! Por algún motivo, mis zapatillas antipegote fallaron.', 28153),
(156991, 'esMX', '¡Muchas gracias! Apenas regrese presentaré una queja. Los obstáculos logísticos con los que se ha topado esta expedición exceden por completo lo que nos habían detallado en el informe.', '¡Muchas gracias! Apenas regrese presentaré una queja. Los obstáculos logísticos con los que se ha topado esta expedición exceden por completo lo que nos habían detallado en el informe.', 28153),
(156990, 'esMX', 'Oh, no, ¡estaré en el Sanitrón por una semana después de esto!', 'Oh, no, ¡estaré en el Sanitrón por una semana después de esto!', 28153),
(156989, 'esMX', '¡Esa sí que fue una situación pegajosa! ¡Te lo agradezco!', '¡Esa sí que fue una situación pegajosa! ¡Te lo agradezco!', 28153),
(156988, 'esMX', 'Que los mare\' bendigan esta mena, y que nunca intenten reclamar lo que alguna vez bendijeron.', 'Que los mare\' bendigan esta mena, y que nunca intenten reclamar lo que alguna vez bendijeron.', 28153),
(156987, 'esMX', '¿Podrías bendecir estos lingotes de plata de tormenta?', '¿Podrías bendecir estos lingotes de plata de tormenta?', 28153),
(156986, 'esMX', 'Nadie debería pensar en los Renegados como una segunda oportunidad para nada.', '', 28153),
(156985, 'esMX', 'No me gusta lo que insinúas, Zelling.', '', 28153),
(156984, 'esMX', '¡Sí! ¡El poder de los crustáceos!', '', 28153),
(156983, 'esMX', 'Mis cangrejos fueron demasiado para ti. ¡La victoria es mía! ¡Búscate otro caparazón para refugiarte!', '', 28153),
(156982, 'esMX', '¡No permitiré que esto quede así! ¡Esta no será la última vez que veas al capitán Hermes y a su trío de cangrejos despiadados!', '', 28153),
(156981, 'esMX', '¡¿Cómo es posible?!', '', 28153),
(156980, 'esMX', '¡Por fin, un contendiente!', '', 28153),
(156979, 'esMX', 'Zarpar rumbo a Valle Canto Tormenta.', 'Zarpar rumbo a Valle Canto Tormenta.', 28153),
(156978, 'esMX', 'Zarpar rumbo al Canal de Tiragarde.', 'Zarpar rumbo al Canal de Tiragarde.', 28153),
(156977, 'esMX', 'Zarpar rumbo a Drustvar.', 'Zarpar rumbo a Drustvar.', 28153),
(156976, 'esMX', '... ¿Qué?', '', 28153),
(156974, 'esMX', 'Ese tipo de la camisa roja me dijo que no estoy en el \"canon\". ¡No me dejaré ofender por alguien que ni siquiera sabe cómo pronunciar \"cañón\"!', '', 28153),
(156973, 'esMX', '¿Puedes darme información sobre Kul Tiras de nuevo?', '¿Puedes darme información sobre Kul Tiras de nuevo?', 28153),
(156972, 'esMX', 'Haremos lo correcto.', '', 28153),
(156971, 'esMX', '', 'Sí, ¿en qué puedo ayudarlos?', 28153),
(156970, 'esMX', '¡Excelente! Parece que arrancaste sus planes de raíz.', '', 28153),
(156969, 'esMX', '¿Los mares te llaman como a mí?', '', 28153),
(156968, 'esMX', '¡Debo saber si mi familia está a salvo! <tos>', '', 28153),
(156967, 'esMX', '', 'Dije que no pusieras a prueba mi pacien...', 28153),
(156966, 'esMX', 'He oído informes sobre una horrible planta monstruosa cerca del horado. Nuestros mozos de labranza mecanizados deberían poder encargarse de eso.', '', 28153),
(156965, 'esMX', 'Que los mares te guíen a tu hogar.', '', 28153),
(156964, 'esMX', '¿Qué necesitas de la casa Valiente?', '', 28153),
(156963, 'esMX', 'Zarpar rumbo a Zuldazar.', 'Zarpar rumbo a Zuldazar.', 28153),
(156962, 'esMX', 'Zarpar rumbo a Nazmir.', 'Zarpar rumbo a Nazmir.', 28153),
(156961, 'esMX', 'Juntos somos fuertes.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'esMX', 'Honraré el legado de mi padre.', '', 28153),
(156959, 'esMX', 'Pasé años en el mar en mi afán por conseguir la colección más letal de cangrejos ermitaños que el mundo haya visto jamás. ¿Quieres luchar o tienes miedo de terminar en lo profundo del mar?', '', 28153),
(156958, 'esMX', 'Buen trabajo. Pondremos a nuestros mejores investigadores a estudiar estas escrituras. Gracias.', '', 28153),
(156957, 'esMX', 'Nuestros magos de batalla vieron varios pergaminos de magia tortollana entre los caídos. Debemos obtenerlos antes de que se entere la Horda. Recupera todos los que encuentres.', '', 28153),
(156956, 'esMX', '¡La Alianza ha recuperado Stromgarde!', '¡La Alianza ha recuperado Stromgarde!', 28153),
(156955, 'esMX', '¡Ey, $n! ¡Por aquí!', '', 28153),
(156954, 'esMX', 'Hola, $p. Oí que eras $Uamigo:amiga; del buen Kiro y lo\' vulpera.\n\nNo tenemo\' tiempo para una charla larga, así que con confiar en Kiro me basta.\n\nSi te interesa surcar los mare\' y saquear, eres $Ubienvenido:bienvenida; en mi tripulación.\n\nSube al barco cuando eh\'tés $Ulisto:lista; y zarparemos.', '', 28153),
(156953, 'esMX', 'Interesante... Haré que nuestros magos investiguen este pergamino en profundidad de inmediato. ¡Gracias!', '', 28153),
(156952, 'esMX', '¡Hola, $p! Me alegra volver a verte.\n\n¿Te interesa un saqueo marino? Zem\'lan ha ordenado a su tripulación que suba a lo\' botes, y eso lo\' convierte en objetivos fáciles para nosotros... si tiene\' buena puntería.\n\nYa te he vih\'to en combate, así que sé que puedes acabar con esos eh\'queletitos sin problemas.\n\nSube al bote cuando estés $Ulisto:lista;.', '', 28153),
(156951, 'esMX', 'Regresaré al Redención del Viento. Cuando desees volver a Boralus, avisa al gran almirante.', '', 28153),
(156950, 'esMX', 'Pasé años en el mar buscando los cangrejos más despiadados contra los que jamás lucharás. ¿Quieres ver qué tan rápido acabo con tus mascotas?', '', 28153),
(156949, 'esMX', '¡$n! ¿Qué puedo hacer por ti?', '', 28153),
(156948, 'esMX', '¿Qué essh esssto?', '¿Qué essh esssto?', 28153),
(156947, 'esMX', '¡$n! Es bueno volver a verte. Ha pasado un tiempo desde que estuve a tus órdenes en Draenor.', '', 28153),
(156946, 'esMX', '¡Los kultiranos conocerán el miedo!', '', 28153),
(156945, 'esMX', 'Pe... qué....', 'Pe... qué....', 28153),
(156944, 'esMX', '¡Ajj! ¡Qué amargo!', '¡Ajj! ¡Qué amargo!', 28153),
(156943, 'esMX', 'Sabe a... ganchos...', 'Sabe a... ganchos...', 28153),
(156942, 'esMX', '¿Qué soy?... ¿Una vrykul?... <¡hic!>', '¿Qué soy?... ¿Una vrykul?... <¡hic!>', 28153),
(156941, 'esMX', 'Ay... odio... <¡hic!> la cerveza rubia...', 'Ay... odio... <¡hic!> la cerveza rubia...', 28153),
(156940, 'esMX', 'Abre un portal para traer a nuestras tropas.', 'Abre un portal para traer a nuestras tropas.', 28153),
(156939, 'esMX', 'Es un honor servir a la Horda como parte de mis estudios sobre telemancia con el tutelaje de Oculeth. \n\nTambién será un honor marcharme apenas terminemos con la tarea.', '', 28153),
(156938, 'esMX', 'Mis sabuesos... ladraron... pero no... mordieron...', 'Mis sabuesos... ladraron... pero no... mordieron...', 28153),
(156937, 'esMX', 'Perfecto, ¡nuestra presa ha venido hacia nosotros!', 'Perfecto, ¡nuestra presa ha venido hacia nosotros!', 28153),
(156936, 'esMX', 'Infunde este amuleto con poder... ¡Puede que sea la única manera de salvar Azeroth!', '', 28153),
(156935, 'esMX', '¿Lo sienten? Es un... temblor...', '', 28153),
(156934, 'esMX', '', 'Asunto: Azeroth. Arritmia severa detectada.\n\nLos signos vitales exceden los parámetros aceptables.\n\nIntentando actualizar informes de incidentes...\n\nERROR. ERROR. ERROR. ERROR.', 28153),
(156933, 'esMX', '¡Juju! ¡Eso sí que es fuerte!', '', 28153),
(156932, 'esMX', 'Mmmm... Me recuerda... a mis tiempos de minero... el truco era golpear con el pico a cierto ángulo... para conservar... la mena.', '', 28153),
(156931, 'esMX', '', 'ADVERTENCIA: Se han registrado múltiples problemas de contención.\n\nSe recomienda expurgar los siguientes complejos:\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld... Uld... Uld... Uld...', 28153),
(156930, 'esMX', 'Urg... Eso no me sienta muy bien...', '', 28153),
(156929, 'esMX', 'Según mis cálculos, nuestra probabilidad de éxito se ha reducido en dos punto cinco tres nueve (periódico, claro está). ¡Debemos apresurar las reparaciones!', 'Según mis cálculos, nuestra probabilidad de éxito se ha reducido en dos punto cinco tres nueve (periódico, claro está). ¡Debemos apresurar las reparaciones!', 28153),
(156928, 'esMX', '¡Vamos! ¡Reparen esos tanques! ¡Nos estamos atrasando!', '¡Vamos! ¡Reparen esos tanques! ¡Nos estamos atrasando!', 28153),
(156927, 'esMX', '¡Todos, apresúrense! Tenemos un plazo acotado para desplegar estos tanques de asedio antes de que la Horda descubra que estamos aquí.', '¡Todos, apresúrense! Tenemos un plazo acotado para desplegar estos tanques de asedio antes de que la Horda descubra que estamos aquí.', 28153),
(156926, 'esMX', 'Ofrecer café espumoso del mayor', 'Ofrecer café espumoso del mayor', 28153),
(156925, 'esMX', 'Ofrecer \"Aurora Borealis\"', 'Ofrecer \"Aurora Borealis\"', 28153),
(156924, 'esMX', 'Ofrecer vodka de raizoscura amarga', 'Ofrecer vodka de raizoscura amarga', 28153),
(156923, 'esMX', 'Ofrecer coñac de manzana de Presabrenna', 'Ofrecer coñac de manzana de Presabrenna', 28153),
(156922, 'esMX', 'Ofrecer schnapps de Punta Garfio', 'Ofrecer schnapps de Punta Garfio', 28153),
(156921, 'esMX', 'Ofrecer hidromiel de Mildenhall', 'Ofrecer hidromiel de Mildenhall', 28153),
(156920, 'esMX', 'Ofrecer cerveza rubia de Bosquealbo', 'Ofrecer cerveza rubia de Bosquealbo', 28153),
(156919, 'esMX', 'Ofrecer vino sangriento dientenegro', 'Ofrecer vino sangriento dientenegro', 28153),
(156918, 'esMX', 'Llévanos de regreso a Boralus.', 'Llévanos de regreso a Boralus.', 28153),
(156917, 'esMX', '', '¡Ay, ay! No te decepcionaré, $n. ¡Lo juro!', 28153),
(156916, 'esMX', '', 'Eh, ¿disculpe? ¿$USeñor:Señora; $n? ¡Por aquí!', 28153),
(156915, 'esMX', 'Ah, ¿precisabas algo de mí?', '', 28153),
(156914, 'esMX', '¿Dónde deberíamos concentrar nuestros esfuerzos?', '', 28153),
(156913, 'esMX', 'Llévanos de regreso a Zuldazar.', 'Llévanos de regreso a Zuldazar.', 28153),
(156912, 'esMX', '', '¿Necesitas un bote? ¿Enviar un mensaje?\n\n¿QUIZÁS AYUDA PARA APUÑALAR A ALGUIEN?', 28153),
(156911, 'esMX', 'Vete, colega... ¿No ves... <hip!> que estoy ocupado?', '', 28153),
(156910, 'esMX', '', 'Asunto: Azeroth.\n\nADVERTENCIA: Falla catastrófica del sistema en curso.\n\nIntegridad planetaria al...\n\ncalculando... calculando... calculando...', 28153),
(156909, 'esMX', 'Esto no estaba en mis cálculos...', 'Esto no estaba en mis cálculos...', 28153),
(156908, 'esMX', 'Según mis cálculos, tus probabilidades de vencer son... ¡nulas!', 'Según mis cálculos, tus probabilidades de vencer son... ¡nulas!', 28153),
(156907, 'esMX', '', 'Ese jabaeh\'pín tenía un mojo poderoso, pero no era un contrincante digno para ti, adalid.', 28153),
(156906, 'esMX', '', 'La tierra se moviliza bajo las órdene\' de un chamán jabaespín. Encárgate de eh\'ta nueva amenaza antes de que afecte nueh\'tros planes.', 28153),
(156905, 'esMX', 'Dormiré más tranquilo esta noche sabiendo que en Canto Tormenta hay menos rocas deambulando.', '', 28153),
(156904, 'esMX', '¡La cría de pterrordáctilo chilla en señal de advertencia!', '¡La cría de pterrordáctilo chilla en señal de advertencia!', 28153),
(156903, 'esMX', 'Hay un clamatierras jabaespín invocando un ejército de elementales. ¡Acaba con ese ejército, y luego acaba con él!', '', 28153),
(156902, 'esMX', 'Gracias. Pensé que era el fin.', 'Gracias. Pensé que era el fin.', 28153),
(156901, 'esMX', 'Me alegra saber que aún queda gente buena en este mundo.', 'Me alegra saber que aún queda gente buena en este mundo.', 28153),
(156900, 'esMX', '¡Gracias! Puedo seguir desde aquí.', '¡Gracias! Puedo seguir desde aquí.', 28153),
(156899, 'esMX', 'Venga a los que no pudieron ser salvados.', 'Venga a los que no pudieron ser salvados.', 28153),
(156898, 'esMX', 'No tienes idea de lo que nos han hecho sufrir...', 'No tienes idea de lo que nos han hecho sufrir...', 28153),
(156897, 'esMX', '¡Me salvah\'te la vida!', '¡Me salvah\'te la vida!', 28153),
(156896, 'esMX', 'Tieneh\' mi agradecimiento.', 'Tieneh\' mi agradecimiento.', 28153),
(156895, 'esMX', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 28153),
(156894, 'esMX', 'Tu valentía no tiene comparación.', 'Tu valentía no tiene comparación.', 28153),
(156893, 'esMX', 'No olvidaré tu amabilidad.', 'No olvidaré tu amabilidad.', 28153),
(156892, 'esMX', '¡Llegas justo a tiempo!', '¡Llegas justo a tiempo!', 28153),
(156891, 'esMX', 'Nunca olvidaré tu compasión.', 'Nunca olvidaré tu compasión.', 28153),
(156890, 'esMX', 'Te debo la vida.', 'Te debo la vida.', 28153),
(156889, 'esMX', 'Será mejor que regrese al combate.', 'Será mejor que regrese al combate.', 28153),
(156888, 'esMX', '¡Revuelve todo hasta que no tenga grumos!', '', 28153),
(156887, 'esMX', '¡Mézclalo bien!', '', 28153),
(156886, 'esMX', 'Por último, ¡el calor!', '', 28153),
(156885, 'esMX', '¡Esto le dará un toque de sabor!', '', 28153),
(156884, 'esMX', '¡Uno a la vez!', '', 28153),
(156883, 'esMX', 'Vale la pena pelear por este valle.', '', 28153),
(156882, 'esMX', '¿Tienes suministros adicionales?', '¿Tienes suministros adicionales?', 28153),
(156881, 'esMX', 'Rezan... se... se ha ido. Esa... cosa no e\' un loa.', '', 28153),
(156880, 'esMX', '¡Ach! Esta cámara está en ruinas, $n. ¡Se derrumbará en cualquier momento!', '', 28153),
(156879, 'esMX', 'Kul Tiras enfrenta un grave peligro, Magni. Pero supongo que has venido por... otras razones.', '', 28153),
(156878, 'esMX', '', '¿Dónde dejé mi caña de pescar? Juro haberla visto por aquí...', 28153),
(156877, 'esMX', '', 'Si sabes dónde buscar, aquí hay buenos sitios de caza y pesca.', 28153),
(156876, 'esMX', '<Una brisa suave acaricia los costados del carro y la madera arruinada cruje.\n\nUna de las ruedas parece estar atascada.>', '', 28153),
(156875, 'esMX', '<Dar un golpe al carro.>', '<Dar un golpe al carro.>', 28153),
(156874, 'esMX', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca de la nave de la Horda. ¡Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca de la nave de la Horda. ¡Cuidado!', 28153),
(156873, 'esMX', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca de la nave de la Alianza. ¡Cuidado!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tEstás cerca de la nave de la Alianza. ¡Cuidado!', 28153),
(156872, 'esMX', '', 'El muro debe caer, el mar regresará.', 28153),
(156871, 'esMX', '$n... Busca una tarea en alguna otra parte. Cuando te necesitemos de nuevo, te avisaré.', '', 28153),
(156870, 'esMX', 'Lilian. Stone. Vengan conmigo y ayúdenme a encontrar a uno de estos... maresabios.', '', 28153),
(156869, 'esMX', 'Estoy harto, cansado de estos constantes impedimentos.', '', 28153),
(156868, 'esMX', '¿Y, $n? ¿Qué has encontrado? Quiero ver.', '', 28153),
(156867, 'esMX', 'Bien, adalid. Tienes trabajo por delante. La plataforma de teletransporte te llevará con tus aliados. Buena suerte... para todos nosotros.', '', 28153),
(156866, 'esMX', 'Seguiré buscando formas de sanar el daño que sufrió Azeroth. Cuando te necesite, te contactaré por medio de ese talismán.', '', 28153),
(156865, 'esMX', 'Conserva ese amuleto cerca de tu corazón, $n. Te ayudará a atravesar los tiempos oscuros que se avecinan.', '', 28153),
(156864, 'esMX', 'Entonces, lo único que necesitamos es algo que nos lleve hacia él.', '', 28153),
(156863, 'esMX', '', 'Las murallas de la fortaleza se desmoronarán ante tu embate.', 28153),
(156862, 'esMX', '', 'Espera la orden para atacar las murallas, Skoloth.', 28153),
(156861, 'esMX', '', 'Recibirás una recompensa por tu servicio.', 28153),
(156860, 'esMX', '', 'Amalia, cuéntale a Nathanos sobre los maresabios.', 28153),
(156859, 'esMX', '', 'Con ayuda... pueden encontrar... naufragios...', 28153),
(156858, 'esMX', '', 'Los maresabios... Sacerdotes... del mar...', 28153),
(156857, 'esMX', '', 'Ah, creo que eso se puede arreglar.', 28153),
(156856, 'esMX', '¡¿Perdido en el mar?! ¡Necesitamos su cuerpo!', '', 28153),
(156855, 'esMX', '', 'Mariscal M. Valentine... Victorioso de la Segunda Guerra... Perdido en el mar...', 28153),
(156854, 'esMX', 'Quiero regresar a Canal de Tiragarde.', 'Quiero regresar a Canal de Tiragarde.', 28153),
(156853, 'esMX', 'Tendré las velas preparadas mientras ustedes salen y hacen lo que tienen que hacer.', '', 28153),
(156851, 'esMX', '¡¿DÓNDE ESTÁ EL CUERPO?!', '', 28153),
(156850, 'esMX', 'Un momento... ¿Qué es esto?', '', 28153),
(156849, 'esMX', 'Valentine... Hace mucho tiempo que nos esquivas.', '', 28153),
(156848, 'esMX', 'No debemos hacer esperar a Valentine.', '', 28153),
(156847, 'esMX', 'Activar Sabletrón...¡ugh!', '', 28153),
(156846, 'esMX', '¿Qué...? ¡No estamos listos!', '', 28153),
(156845, 'esMX', '¡Nadie puede oponerse a Sabletrón!', '', 28153),
(156844, 'esMX', '¡Cinco gatos pequeños se combinan para formar un supergato!', '', 28153),
(156843, 'esMX', 'Tu poder ya no protegerá este navío.', '', 28153),
(156842, 'esMX', 'Lárgate, maldita oscuridad.', '', 28153),
(156841, 'esMX', 'Las mareas consumirán tu carne corrupta.', '', 28153),
(156840, 'esMX', '', '¡No dejes que lastimen a Dot!', 28153),
(156839, 'esMX', '', '¡Ayuuudaaa!', 28153),
(156838, 'esMX', 'Zarpar rumbo a Vol\'Dun.', 'Zarpar rumbo a Vol\'Dun.', 28153),
(156837, 'esMX', 'Aunque esa cosa esté muerta, seguiré teniendo pesadillas.', '', 28153),
(156836, 'esMX', 'Es una... ehh... ¡una cosa! ¡Mátala! ¡Mátala con fuego!', '', 28153),
(156835, 'esMX', '|A:Warfront-AllianceWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Alianza!', '|A:Warfront-AllianceWave3:25:23:0:0|a¡Se ha desplegado una fuerza de asalto de la Alianza!', 28153),
(156834, 'esMX', 'Los sethrak han encontrado la carreta de Meerah en las dunas. Está completamente sola y no le vendría mal un poco de ayuda para ahuyentarlos, si deciden atacarla.', '', 28153),
(156833, 'esMX', '', 'Como ordenes, por la voluntad de la Dama Oscura.', 28153),
(156832, 'esMX', '', 'Devuélvanle la vida a este hombre. Ha sido elegido para convertirse en Renegado.', 28153),
(156831, 'esMX', 'Lilian. Podemos encontrar otros maresabios. Sabes que su familia no lo aceptará.', '', 28153),
(156830, 'esMX', '', 'Lilian Voss. ¿Por qué me has llamado?', 28153),
(156829, 'esMX', 'Un contratiempo leve. Demuestra que no afecta en nada a nuestro plan.', '', 28153),
(156828, 'esMX', 'Desear es una palabra fuerte. Es algo que... estoy dispuesto a aguantar, si sirve para ayudar a mi familia.', '', 28153),
(156827, 'esMX', '', 'Con muchísimo dolor.', 28153),
(156826, 'esMX', 'Pero una parte de usted sobrevivió, ¿no es así?', '', 28153),
(156825, 'esMX', '', 'Espero que vivas lo suficiente para ayudarnos a encontrar a Valentine.', 28153),
(156824, 'esMX', '¡Vamos!', '¡Vamos!', 28153),
(156823, 'esMX', '', 'Podemos reclutar fuerzas adicionales de la Horda de inmediato. Solo tienes que decirlo.', 28153),
(156822, 'esMX', 'Hmm... Espero que sepas lo que haces.', '', 28153),
(156821, 'esMX', '', 'Yo me encargo de ella, Nathanos. Sigue sin nosotras.', 28153),
(156820, 'esMX', '', '¡Alto!', 28153),
(156819, 'esMX', '', '¡AAHHHH!', 28153),
(156818, 'esMX', '', 'No... No puedo...', 28153),
(156817, 'esMX', '', 'Es un buen comienzo. Veamos qué más puedes hacer.', 28153),
(156816, 'esMX', 'Hay fuerzas de Kul Tiras y la Alianza en Fortesabio. Están esperando refuerzos, así que podríamos atacarlos en este momento.', '', 28153),
(156815, 'esMX', '¿Mi familia está a salvo?', '', 28153),
(156814, 'esMX', '', 'Bien. Demuéstrame tu valor para la Horda y veremos cuánto más te dejaremos disfrutar de esta vida.', 28153),
(156813, 'esMX', 'Están a salvo. Ayúdanos y nos aseguraremos de que siga siendo así.', '', 28153),
(156812, 'esMX', '<Tos> Haré... haré lo que pueda, señorita Voss. Quiere localizar a alguien o algo, ¿cierto? Veamos qué puedo hacer sin mi libro...', '', 28153),
(156811, 'esMX', '', 'No pongas a prueba mi paciencia, o desearás que tu enfermedad ya te hubiese matado. Debo averiguar cuán buena es tu magia antes de continuar.', 28153),
(156810, 'esMX', 'Señorita Voss. Cuando volvió a la vida, ¿conservaba alguna de las enfermedades que tenía en su vida pasada?', '', 28153),
(156809, 'esMX', '', 'Lilian Voss. De las preguntas me encargo yo. ¿Puedes rastrear personas? ¿Objetos?', 28153),
(156808, 'esMX', 'Una Renegada. Quizás es <tos> una señal. Dígame, ¿señorita...?', '', 28153),
(156807, 'esMX', '', '$n tiene razón, por así decirlo. No saldrás lastimado si nos ayudas, si es posible antes de morir.', 28153),
(156806, 'esMX', 'Que la Dama Oscura cuide de ti.', '', 28153),
(156805, 'esMX', 'Necesito refuerzos.', 'Necesito refuerzos.', 28153),
(156804, 'esMX', '¿Buscas refuerzos? Da la orden y organizaré el transporte desde Ventormenta.', '', 28153),
(156803, 'esMX', 'No tenemos tiempo que perder. ¿Qué precisas?', '', 28153),
(156802, 'esMX', 'Eres muy difícil de matar... mucho más que ese enemigo.', '', 28153),
(156801, 'esMX', 'Esta vez no tenemos un plan, así que solo ve allí, acaba con la amenaza y no mueras.', '', 28153),
(156799, 'esMX', '%s machaca la comida fresca.', '', 28153),
(156798, 'esMX', '%s mastica las hojas verdes con mucho entusiasmo.', '', 28153),
(156797, 'esMX', '%s entierra el hocico en la comida.', '', 28153),
(156796, 'esMX', '¡Te aplastaré la cabeza!', '¡Te aplastaré la cabeza!', 28153),
(156795, 'esMX', '¡¿Quién quiere ser el próximo en morir?!', '¡¿Quién quiere ser el próximo en morir?!', 28153),
(156794, 'esMX', '¡Vamos!', '¡Vamos!', 28153),
(156793, 'esMX', '[ESCENA] - ¡Llega Jaina! ¡Sus fuerzas derriban el muro de la fortaleza de Lordaeron! Y, por cierto, es *espectacular*.', '[ESCENA] - ¡Llega Jaina! ¡Sus fuerzas derriban el muro de la fortaleza de Lordaeron! Y, por cierto, es *espectacular*.', 28153),
(156792, 'esMX', '[ESCENA] - Sylvanas está esperando en la sala del trono cuando llega Anduin. Anduin le ofrece la posibilidad de rendirse. En cambio, hace explotar la ciudad. ¿Qué esperabas?', '[ESCENA] - Sylvanas está esperando en la sala del trono cuando llega Anduin. Anduin le ofrece la posibilidad de rendirse. En cambio, hace explotar la ciudad. ¿Qué esperabas?', 28153),
(156791, 'esMX', '', 'Si consiguiera que Kul Tiras vuelva a la Alianza...', 28153),
(156790, 'esMX', '', 'Mi pueblo controla la armada más poderosa de todo Azeroth.', 28153),
(156789, 'esMX', '', 'Es un hechizo simple, siempre y cuando el sujeto coopere.', 28153),
(156788, 'esMX', '', 'Ten, bebe esto.', 28153),
(156787, 'esMX', '', 'Bien, Amalia. Dame un segundo...', 28153),
(156786, 'esMX', 'He venido a pedirte ayuda, no a matarte.', 'He venido a pedirte ayuda, no a matarte.', 28153),
(156785, 'esMX', '<Tose> La Horda. Y yo que creía que moriría en paz. \n\n¿Y bien? ¿Qué esperas?', '', 28153),
(156784, 'esMX', '', 'Oye... $n, aquí, junto a la trituradora.', 28153),
(156783, 'esMX', 'Debemos apresurarnos si queremos conseguir la ayuda del maresabio.', '', 28153),
(156782, 'esMX', '', 'Nada de lo que puedas hacer podría ser peor que la enfermedad...Fue al este a morir en paz, lejos de sus hijos. Por favor, déjanos en paz.', 28153),
(156781, 'esMX', 'Solo quiero averiguar el paradero de tu esposo. Prometo que tú y tu familia estarán a salvo.', '', 28153),
(156780, 'esMX', '', 'La Horda... ¿qué más has venido a arrebatarme? Mi esposo agoniza, no tengo ni una moneda... deja a mis hijos en paz, por favor.', 28153),
(156779, 'esMX', 'Eso no es para nada honorable. Podemos preguntarle y listo. No tenemos por qué meternos con una pobre madre.', '', 28153),
(156778, 'esMX', '', '', 28153),
(156777, 'esMX', '', '', 28153),
(156776, 'esMX', '', '', 28153),
(156775, 'esMX', '', '', 28153),
(156774, 'esMX', '', '', 28153),
(156773, 'esMX', '¡Ja! ¡Parece que al fin esa cosa no podrá comer más!', '', 28153),
(156772, 'esMX', 'Le soltaron la cadena al perrote.', '', 28153),
(156771, 'esMX', 'Ni cuenta se dará.', '', 28153),
(156770, 'esMX', '¿Alguien llamó a un reconfigulador?', '', 28153),
(156769, 'esMX', '', '', 28153),
(156768, 'esMX', '', '', 28153),
(156767, 'esMX', 'Sujétate con fuerza, esto se va a poner feo.', '', 28153),
(156766, 'esMX', 'En la trayectoria correcta, sin errores.', '', 28153),
(156765, 'esMX', '', 'Hnngh...', 28153),
(156764, 'esMX', '', 'Cuanto más rápido recojas las flores, más rápido podré ayudar a Amalia para que sea útil.', 28153),
(156763, 'esMX', 'He oído historias de gusanos gigantes que se alimentan de carroña y provocan alborotos en la superficie. ¡Si encontramos uno, tenemos que exterminarlo!', '', 28153),
(156762, 'esMX', 'Qué bueno que salvaste a los niños. ¡Seguramente ahora querrán huir para ser como tú!', '', 28153),
(156761, 'esMX', 'Un grupo de niños de La Rivera Muerta huyó para convertirse en piratas, ¡y terminaron prisioneros de los mareaférrea! ¡Necesito que los salves!', '', 28153),
(156760, 'esMX', '', 'Psst... $n, ¡por aquí!', 28153),
(156759, 'esMX', '', 'Una monstruosidad meno\' para aterrorizar a mi pueblo en la superficie. Tus accione\' complacen a los loa.', 28153),
(156758, 'esMX', '', 'He oído que unos gusano\' se alimentan de carroña y causan eh\'tragos en la superficie. ¡Debemo\' exterminar a los que encontremo\'!', 28153),
(156757, 'esMX', 'Dijeron que habría dulces.', '¿Ya soy una pirata?', 28153),
(156756, 'esMX', 'Mire, jefe, sé que está financiando esta expedición, pero Gallywix va a querer asegurarse de que la Dama Oscura reciba su parte.', '', 28153),
(156755, 'esMX', 'Necesito viajar al Cementerio Tremulante.', 'Necesito viajar al Cementerio Tremulante.', 28153),
(156754, 'esMX', '', '¡Vendo los cohetes más seguros de todo Kul Tiras!$b$bNo hagan caso a mi apellido.', 28153),
(156753, 'esMX', '¡Retirada! Soldado que huye sirve para otra guerra.', '', 28153),
(156752, 'esMX', '¡Zandalari, retrocedan y reagrúpense! Podemo\' seguir la lucha otro día.', '', 28153),
(156751, 'esMX', '¡Destruyan a eh\'tos invasore\'!', '', 28153),
(156750, 'esMX', '¡Son débiles!', '', 28153),
(156749, 'esMX', '¡Su muerte se acerca!', '', 28153),
(156748, 'esMX', '¡Soy el temible pirata Beuford! ¡No quedarán sobrevivientes!', '¡Creo que veo a mi gato!', 28153),
(156747, 'esMX', 'Entra a la tormenta y terminemos con esto.', '', 28153),
(156746, 'esMX', '¡No eres $uun:una; pirata!', '¡Dijeron que me darían un sombrero!', 28153),
(156745, 'esMX', '¡Argh! ¡Dame un poco de ron!', '¡Tengo que ir a la cubierta!', 28153),
(156744, 'esMX', '', 'Bien, no te ensuciarás las manos.', 28153),
(156743, 'esMX', 'Quiero regresar a Zuldazar.', 'Quiero regresar a Zuldazar.', 28153),
(156742, 'esMX', 'Tendré las vela\' lista\' para que podamo\' partir rápido. ¡Busquen esa azerita!', '', 28153),
(156741, 'esMX', '', 'Yo me encargo del cuerpo, $n. Tú regresa con Nathanos y dile que todo va según planeado.', 28153),
(156740, 'esMX', 'No me involucraré en convertir a este hombre en Renegado. Encárgate tú.', 'No me involucraré en convertir a este hombre en Renegado. Encárgate tú.', 28153),
(156739, 'esMX', '', 'Aprenderás a sobrellevarlo. Yo te ayudaré.', 28153),
(156738, 'esMX', '¡No necesito que me salven!', 'Ahora soy una pirata. No tengo por qué escucharte.', 28153),
(156737, 'esMX', '', 'Ahora eres de los nuestros. No te aceptarán.', 28153),
(156736, 'esMX', 'Lilian, mata a Zelling.', 'Lilian, mata a Zelling.', 28153),
(156735, 'esMX', '', 'Stone, comprendo lo que te pasa. No dejes que este cambio se apodere de tu mente, como me pasó a mí.', 28153),
(156734, 'esMX', '¡No es justo! Yo quería ser pirata.', '¡Grettly me vendió a los piratas!', 28153),
(156733, 'esMX', 'Lilian, haz lo que debas hacer con Zelling.', 'Lilian, haz lo que debas hacer con Zelling.', 28153),
(156732, 'esMX', '', 'Veremos. Quizá sea diferente... solo esta vez.', 28153),
(156731, 'esMX', '', 'Terrible. Los que no te rechacen no volverán a verte de la misma forma. Cuando te mires en el espejo solo verás un monstruo, un ser que no eres tú.', 28153),
(156730, 'esMX', 'Por favor... necesito... cuidar... a mi familia... sea como sea.', '', 28153),
(156729, 'esMX', '', 'Te rechazarán si te conviertes en uno de nosotros. Cuando te mires en el espejo solo verás un monstruo.', 28153),
(156728, 'esMX', 'Señorita Voss, <tos> por favor... devuélvame a la vida... Debo ayudar a mi familia... Haré lo que sea... cualquier cosa...', '', 28153),
(156727, 'esMX', '', '¿Qué? ¡Tu familia te creerá un monstruo! ¡No seas ridículo!', 28153),
(156726, 'esMX', '', 'Bien. De todos modos, hay algo que quiero saber.', 28153),
(156725, 'esMX', '<Jadeo> Lo... lo siento. No... no puedo... No me queda... nada...', '', 28153),
(156724, 'esMX', '', '¡Zelling! Maldición, ¡te necesitamos vivo!', 28153),
(156723, 'esMX', '¡Sí! Se me concederá la vida eterna, al fin, ¡estoy listo!', '', 28153),
(156722, 'esMX', '', 'Bien, Zelling. ¿Comprendes, verdaderamente, lo que sucederá?', 28153),
(156721, 'esMX', 'Excelente trabajo. Les enseñaste cómo hacemos las cosas en el valle.', '', 28153),
(156720, 'esMX', 'Los exploradores informan de una nueva amenaza en esta área. Mátala antes de que sea un problema más grande.', '', 28153),
(156719, 'esMX', 'Ten cuidado, Jaina. Que la Luz te acompañe.', '', 28153),
(156718, 'esMX', '', 'Regresaré con la flota... o no regresaré.', 28153),
(156717, 'esMX', 'Será difícil... y peligroso.', '', 28153),
(156716, 'esMX', 'Eso creo... y creo que tú puedes hacerlo.', '', 28153),
(156715, 'esMX', '', 'Y lidiar con eso es la única esperanza que tenemos para recuperarlos.', 28153),
(156714, 'esMX', 'Jaina, tú eres la razón por la que abandonaron la Alianza.', '', 28153),
(156713, 'esMX', '', 'Entonces debemos buscar nuestros propios aliados.', 28153),
(156710, 'esMX', '', 'Muéstranos... muéstranos qué pasó...', 28153),
(156709, 'esMX', 'Si la Horda se alía con los zandalari, no tendremos el poder para detenerlos.', '', 28153),
(156708, 'esMX', '¡Imposible! Es uno de los trucos de Sylvanas. Debe ser...', '', 28153),
(156707, 'esMX', 'Y una flota zandalari inconmensurable.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'esMX', 'Los sobrevivientes hablan de magias extrañas y aterradoras.', '', 28153),
(156705, 'esMX', 'Solo uno regresó.', '', 28153),
(156704, 'esMX', 'Lo sé. ¿Qué hay de los ocho barcos de guerra que enviamos para perseguirlos?', '', 28153),
(156703, 'esMX', 'Una princesa. Y un profeta.', '', 28153),
(156702, 'esMX', 'Hace poco, unos agentes de la Horda se infiltraron en las Mazmorras y liberaron a dos prisioneros zandalari.', '', 28153),
(156701, 'esMX', 'Jaina, quizá tú puedas ayudarnos a ver lo que este sobreviviente ha visto.', '', 28153),
(156700, 'esMX', 'Muchos viajeros han muerto en esta área. Necesito que te encargues de quien esté detrás de esos ataques.', '', 28153),
(156699, 'esMX', 'Ya han llegado todos. ¿Qué noticias traes, maestro espía?', '', 28153),
(156698, 'esMX', '¡Muy buen trabajo! Sabía que podía contar contigo para protegernos.', '', 28153),
(156697, 'esMX', 'Si consigo una nave aérea, ¡le pondré el nombre de mi hijo!', '', 28153),
(156696, 'esMX', '¡Eh\'to me lo robé yo mismo! Lo llamo Fortuna de Mala... ¡como mi propia hija!', '', 28153),
(156695, 'esMX', 'Si me dicen que lucharemo\' contra lo\' piratas, ¡yo digo que necesitaremo\' barcos pirata!', '', 28153),
(156694, 'esMX', '¡Los nagas planean algo!', '', 28153),
(156693, 'esMX', 'Sí... ¡Eternidad...!', '', 28153),
(156692, 'esMX', 'Cuando quiera\' irte, usa la cuerda. ¡Me encantaría mostrarte mi bote!', '', 28153),
(156691, 'esMX', '', '¡El siguiente en quejarse terminará muerto!', 28153),
(156690, 'esMX', '', '¡Trabajen más rápido, perros patéticos!', 28153),
(156689, 'esMX', '', '¡Menos charla y más acción! ¡La azerita no se extraerá sola!', 28153),
(156688, 'esMX', '', '¿A eso llaman trabajar? ¡Tienen suerte de que no les estemos pagando por esto, cerdos!', 28153),
(156687, 'esMX', '', '¡Vuelvan al trabajo, perros asquerosos! ¡Nada de descansos!', 28153),
(156686, 'esMX', '¡Por favor, máteme! ¡Concédame la vida eterna como Renegado!', '', 28153),
(156685, 'esMX', 'Sé que has estado robándole a la compañía. He venido a asegurarme de que no vuelva a suceder...', 'Sé que has estado robándole a la compañía. He venido a asegurarme de que no vuelva a suceder...', 28153),
(156684, 'esMX', '¿Quieres que te golpee? ¡Ocúpate de tus asuntos!', '¿Quieres que te golpee? ¡Ocúpate de tus asuntos!', 28153),
(156683, 'esMX', 'Sigue caminando, tripulante. Aquí no hay nada que ver...', 'Sigue caminando, tripulante. Aquí no hay nada que ver...', 28153),
(156682, 'esMX', '¿Qué miras, tripulante?', '¿Qué miras, tripulante?', 28153),
(156681, 'esMX', '<cough> Señorita Voss, ¿cómo llegó usted a convertirse en Renegada?', '', 28153),
(156680, 'esMX', 'Los ladrones de la Horda están saqueando azerita de la Compañía Comercial Aspafresno. ¡Aplasta a nuestros enemigos y recupera los recursos para la Séptima Legión!', '', 28153),
(156679, 'esMX', '¡Solo robé para llenar un corazón vacío que nunca conoció el amor!', '¡Solo robé para llenar un corazón vacío que nunca conoció el amor!', 28153),
(156678, 'esMX', '¡Es todo culpa de la forma en que me criaron!', '¡Es todo culpa de la forma en que me criaron!', 28153),
(156677, 'esMX', '¡No lo volveré a hacer, lo prometo!', '¡No lo volveré a hacer, lo prometo!', 28153),
(156676, 'esMX', '¡Ese perro astuto de Harrington recurrió a la fuerza!', '¡Ese perro astuto de Harrington recurrió a la fuerza!', 28153),
(156675, 'esMX', '¡Ya no robaré! ¡Nunca más!', '¡Ya no robaré! ¡Nunca más!', 28153),
(156674, 'esMX', '¡Por favor, no me mates! ¡No volveré a robar, lo juro!', '¡Por favor, no me mates! ¡No volveré a robar, lo juro!', 28153),
(156673, 'esMX', 'Unos exiliados de Zuldazar han tomado de rehenes a nuestros soldados. No negociamos con aliados de la Horda. ¡Muéstrales la fuerza de la Alianza!', '', 28153),
(156672, 'esMX', 'Acabaste con ellos sin problemas. Muy bien.', '', 28153),
(156671, 'esMX', 'Nuestros espías han localizado un pequeño campamento de tropas de la Horda en las dunas. ¡Atácalos raudamente y diezma a las fuerzas enemigas!', '', 28153),
(156670, 'esMX', 'Fue todo un placer hacer negocios contigo. Si en algún momento quieres trabajo de pirata, ¡puedes unirte a mi tripulación!', '', 28153),
(156669, 'esMX', 'Siempre cumplo con mi palabra, $c. ¡El arcón del capitán es todo tuyo!', '', 28153),
(156668, 'esMX', 'Nos veremos en los cuarteles del capitán una vez que Hartford esté muerto. No te preocupes por el arcón, ¡todo lo que tiene dentro será tuyo!', '', 28153),
(156667, 'esMX', '', 'Aún no hemos terminado. Tienes buena información, pero tenemos que averiguar cuán fuerte eres en verdad.', 28153),
(156666, 'esMX', '¡Por favor! Con esto tiene que alcanzar, su campéon ha sembrado el caos y la destrucción en Fortesabio. ¡Conviértame en Renegado!', '', 28153),
(156665, 'esMX', '', '¿Nos equivocamos... al apoyar... a la Alianza?', 28153),
(156664, 'esMX', '', '¡La Horda jamás quebrantará la voluntad de Kul Tiras!', 28153),
(156663, 'esMX', 'El libro... debe terminar... en el fondo del mar...', '', 28153),
(156662, 'esMX', '¡No te llevarás este libro! ¡Es demasiado peligroso!', '', 28153),
(156661, 'esMX', '', 'Estarías muerto antes de tu próxima patética tos, Zelling. ¿Quieres probar?', 28153),
(156660, 'esMX', '<Jadeo> ¿No le preocupa que la ataque? ¿Que salga corriendo?', '', 28153),
(156659, 'esMX', '¿La capitana Stone enloqueció cuando se convirtió? Estoy al tanto de lo que le sucedió.', '', 28153),
(156658, 'esMX', '', 'Convertirse en Renegado es un proceso impredecible. Tu cuerpo y tu mente cambiarán, de eso no hay dudas, pero cuánto... eso nadie lo sabe. Lo que tampoco se sabe es cómo reacciona uno al proceso.', 28153),
(156657, 'esMX', 'No, pero, ¿puede responder mi pregunta? Cuando uno se convierte en Renegado, ¿se purgan sus enfermedades?', '', 28153),
(156656, 'esMX', 'Contigo a mi lado, ¡estoy un paso más cerca de abandonar este desierto asqueroso!', '', 28153),
(156655, 'esMX', 'Reúnete conmigo en Puerto Piedrarroja cuando termines el trabajo.', '', 28153),
(156654, 'esMX', 'Vaya, eso fue... creativo.', '', 28153),
(156653, 'esMX', 'Nuestros aliados no pueden completar su misión mientras la Horda recorre estas ruinas. Los Hierro Negro han pensado una solución para esto.', '', 28153),
(156652, 'esMX', '2 minutos para que comience la batalla de Stromgarde.', '', 28153),
(156651, 'esMX', 'Parece que dejé caer mi fabuloso sombrero.', 'Parece que dejé caer mi fabuloso sombrero.', 28153),
(156650, 'esMX', 'Llévanos a Valle Canto Tormenta.', 'Llévanos a Valle Canto Tormenta.', 28153),
(156649, 'esMX', 'Muy bien. Veamos si has encontrado algo útil.', '', 28153),
(156648, 'esMX', 'Estas ruinas parecen ser de un templo hundido. La presencia de los nagas también me preocupa. Mucha suerte en la misión de reconocimiento.', '', 28153),
(156647, 'esMX', 'Estoy listo para negociar, Ty\'jin.', 'Estoy lista para negociar, Ty\'jin.', 28153),
(156646, 'esMX', 'Avísame cuando eh\'tés $Glisto:lista; para partir, $Ujefe:jefa;.', '', 28153),
(156645, 'esMX', 'Muy buen trabajo. Más vale prevenir que curar.', '', 28153),
(156644, 'esMX', 'Hemos descubierto una infestación de múrlocs. No podemos permitir que se multipliquen y ataquen nuestros flancos.', '', 28153),
(156643, 'esMX', '', '¡Hicih\'te un buen trabajo, adalid! Los loa sonríen hoy.', 28153),
(156642, 'esMX', '', 'Ventura y Cía. eh\'tá desgarrando la tierra en buh\'ca de un aliado valioso. Los loa no eh\'tarán complacidos. Acaba con sus accione\' y soluciona eh\'te desastre.', 28153),
(156641, 'esMX', '', '¡Buen trabajo! Esos tortollano\' recordarán quiénes los salvaron de ese deh\'tino.', 28153),
(156640, 'esMX', '', 'Me han informado que los nagas de eh\'tas costas esclavizan a los tortollanos por motivos deh\'conocidos. ¡No lo permitas, adalid! Mata a los nagas y libera a los tortollano\'.', 28153),
(156639, 'esMX', 'Los maresabios siempre han guiado almas perdidas en el mar... pero no así.', '', 28153),
(156637, 'esMX', 'Buen trabajo. ¡Esperemos que los tortollanos recuerden esto cuando los necesitemos!', '', 28153),
(156636, 'esMX', 'Estoy listo para partir hacia Lordaeron.', 'Estoy lista para partir hacia Lordaeron.', 28153),
(156635, 'esMX', 'Ventura y Cía. está causando un desastre en la costa. Acabemos con estas cosas para ganar el favor de los tortollanos.', '', 28153),
(156634, 'esMX', '', 'Se acabaron... las clases...', 28153),
(156633, 'esMX', '', '¡Voy a darte una lección!', 28153),
(156632, 'esMX', 'Excelente trabajo. Odio pensar en lo que los nagas planeaban para esos tortollanos.', '', 28153),
(156631, 'esMX', 'Los exploradores informan que los nagas de esta área están capturando tortollanos. Sean cuales sean sus planes, debemos detenerlos.', '', 28153),
(156630, 'esMX', '', '¡Peleas como $uun granjero:una granjera;!', 28153),
(156629, 'esMX', '¡Bien hecho, $p! ¡Estamos un paso más cerca de la victoria!', '', 28153),
(156628, 'esMX', 'Eso los mantendrá a raya... por ahora. Bien hecho.', '', 28153),
(156627, 'esMX', 'Estas víboras emplumadas son conocidas por sus infestaciones excesivas, ¡pero esto es demasiado! Destruye sus huevos de inmediato.', '', 28153),
(156626, 'esMX', 'Estas servirán muy bien. Los soldados heridos estarán agradecidos por tu ayuda, adalid.', '', 28153),
(156625, 'esMX', 'Aprovechemos los suministros locales. Recoge las glándulas salivales de los pterrordáctilos salvajes. Sus propiedades curativas ayudarán a los heridos.', '', 28153),
(156624, 'esMX', '¡No me sorprende que los ravasaurios puedan devorar cualquier cosa! Les daremos un buen uso. Gracias, adalid.', '', 28153),
(156623, 'esMX', 'Necesitamos suministros duraderos. Se supone que los ravasaurios de la zona tienen estómagos con revestimientos muy resistentes. ¿Podrías juntar algunos para nosotros?', '', 28153),
(156622, 'esMX', 'Arghh... vete al armario... de Neptulon...', '', 28153),
(156621, 'esMX', '¿Qué es esto?... ¡¿Un motín?! ¡Toma esto, cerdo!', '', 28153),
(156620, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(156619, 'esMX', '', 'Mi investigación está terminada, por ahora. Gracias por tu ayuda.', 28153),
(156618, 'esMX', '', '¡Eso le enseñará a la Horda a no interferir! Esta magia nunca debe caer en sus manos...', 28153),
(156617, 'esMX', '', 'Tu ayuda es más que bienvenida. Esta barrera es demasiado resistente...', 28153),
(156616, 'esMX', '¡La inmortalidad está al alcance de mi mano! No puedo esperar a convertirme en un Renegado. ¡Imagina todo ese abanico de posibilidades! \n\nCuando tengas un momento, dime qué se siente. La no-muerte, la eternidad, ¡tener el mundo a tus pies!', '', 28153),
(156615, 'esMX', 'Me niego a dejar que mi vida termina ahora a causa de una... enfermedad. Tengo que vivir para cuidar a mi familia.', '', 28153),
(156614, 'esMX', 'No molestes a los muertos, $r.', '', 28153),
(156613, 'esMX', '', '¡Me vendría bien un poco de ayuda!', 28153),
(156612, 'esMX', 'Si no avanzas, es porque te estás quedando atrás. ¡Es lo que siempre digo!', '', 28153),
(156611, 'esMX', '', 'Tengo que realizar algunas pruebas y recopilar datos. Vigila que nadie me interrumpa.', 28153),
(156610, 'esMX', '', 'Tal vez podamos controlar esta magia, o incluso replicarla.', 28153),
(156609, 'esMX', '', '¡La magia del lugar es fascinante! No se parece a nada que haya visto antes.', 28153),
(156608, 'esMX', '', '¡Esto no ha terminado!', 28153),
(156607, 'esMX', '¿Pero te alcanzará el tiempo?', '', 28153),
(156606, 'esMX', 'Necesito un nuevo disfraz.', 'Necesito un nuevo disfraz.', 28153),
(156605, 'esMX', 'La Horda está aquí, ¡corran! ¡¿Ya no hay lugar seguro?!', 'La Horda está aquí, ¡corran! ¡¿Ya no hay lugar seguro?!', 28153),
(156604, 'esMX', 'Genial, ¡más problemas con la Horda ahora que la Alianza está aquí!', 'Genial, ¡más problemas con la Horda ahora que la Alianza está aquí!', 28153),
(156603, 'esMX', '¡No arriesgaré mi vida si la Horda ya está aquí!', '¡No arriesgaré mi vida si la Horda ya está aquí!', 28153),
(156602, 'esMX', '¡Corran! ¡Esto es lo que obtenemos por ayudar a la Alianza!', '¡Corran! ¡Esto es lo que obtenemos por ayudar a la Alianza!', 28153),
(156601, 'esMX', '¡Creí que estábamos a salvo de la Horda!', '¡Creí que estábamos a salvo de la Horda!', 28153),
(156600, 'esMX', '¡¿Cómo llegó la Horda hasta aquí?!', '¡¿Cómo llegó la Horda hasta aquí?!', 28153),
(156599, 'esMX', 'La Horda. ¡Corran!', 'La Horda. ¡Corran!', 28153),
(156598, 'esMX', 'This is test text, I say things in it.', '', 28153),
(156597, 'esMX', '', 'Adiós, Nathanos.', 28153),
(156596, 'esMX', '', '<Sylvanas comienza a marcharse, luego duda y mira hacia atrás.>', 28153),
(156595, 'esMX', 'No le fallaremos. Viaje segura, milady.', '', 28153),
(156594, 'esMX', '', 'Encárgate de ello y envíame informes sobre tus progresos.', 28153),
(156593, 'esMX', 'Como ordene, jefa de guerra.', '', 28153),
(156592, 'esMX', '', 'Bien. Trabaja con $n para decidir dónde estableceremos nuestra primera base.', 28153),
(156591, 'esMX', 'Sí, milady. El Lamento del Alma en Pena está listo para zarpar cuando desee.', '', 28153),
(156590, 'esMX', '', '¿Todo está en orden?', 28153),
(156589, 'esMX', '<Nathanos hace una gran reverencia.>', '', 28153),
(156588, 'esMX', 'Mi reina.', '', 28153),
(156587, 'esMX', '$n, se requiere tu presencia en el Lamento del Alma en Pena. La Dama Oscura ordena que comencemos nuestra campaña en las costas de Kul Tiras.', '', 28153),
(156586, 'esMX', '', 'Sígueme.', 28153),
(156585, 'esMX', '', '$n.', 28153),
(156584, 'esMX', 'Garona Semiorca lidera el grupo. Ella organizará estas misiones con tu ayuda.', '', 28153),
(156583, 'esMX', 'Hemos formado un grupo de élite para ejecutar las órdenes de la Dama Oscura.', '', 28153),
(156582, 'esMX', 'Buen trabajo, $p.', '', 28153),
(156581, 'esMX', 'La Horda sabe de nuestra presencia y ha desplegado tropas para atacarnos. ¡Detenlos para que nuestros exploradores puedan completar su misión!', '', 28153),
(156580, 'esMX', '', 'Bueno, quizás pueda arreglarlo, Zelling, pero solo si demuestras tu valor para la Horda.', 28153),
(156579, 'esMX', 'Soy Thomas Zelling, soy maresabio, ¡un maresabio ILUMINADO! Haré lo que sea que me pida, incluso ayudar a atacar a las fuerzas de la Alianza cercanas, pero por favor, ¡conviértame en Renegado!', '', 28153),
(156578, 'esMX', 'Parece que el carro llegó a destino sano y salvo. Tu recompensa te aguarda en el castillo.', '', 28153),
(156577, 'esMX', '', '¿Quién eres? ¿Por qué crees que mereces este don?', 28153),
(156576, 'esMX', '¡Por fin, una Renegada! Por favor, máteme, conviértame en Renegado... ¡concédame el don de la inmortalidad!', '', 28153),
(156575, 'esMX', '', 'Bueno, podría amenazar un poco a la mujer, a ver si nos da un poco de información...', 28153),
(156574, 'esMX', 'El Vacío, los elementos <tos>... ¿es que nada puede detener a esta maldita enfermedad? ¿Por qué tuvo que terminar así?', '', 28153),
(156573, 'esMX', 'Mmm, el maresabio estuvo aquí no hace mucho. Lo vi proteger y servir a su familia.', '', 28153),
(156572, 'esMX', '¿Alguna pista sobre dónde podemos encontrar a un maresabio?', '¿Alguna pista sobre dónde podemos encontrar a un maresabio?', 28153),
(156571, 'esMX', 'Hemos visto a la Horda transportando sus suministros por el campo de batalla. Balinda está buscando voluntarios para ayudar a... reponer nuestras existencias.', '', 28153),
(156570, 'esMX', 'Hemos recibido informes de que hay exploradores de la Horda cerca de la mina. Busca a Genny en el taller para conseguir más información.', '', 28153),
(156569, 'esMX', 'Genny necesita una mano en el taller. Se nos están acabando los suministros.', '', 28153),
(156568, 'esMX', 'Dinero que ganar. Tierras nuevas que explotar... $B$B¡Qué época más hermosa para estar vivo!', '', 28153),
(156567, 'esMX', 'No, para nada.', '', 28153),
(156566, 'esMX', 'Misha, quédate aquí. Los demás rastrearemos al maresabio y luego Lillian hará... lo que sea que tengas en mente.', '', 28153),
(156565, 'esMX', '', '¿No te interesan los detalles, Rexxar?', 28153),
(156564, 'esMX', 'Estoy listo para ir a Entrañas.', 'Estoy lista para ir a Entrañas.', 28153),
(156563, 'esMX', '', 'Camposanto ya no existe. Te llevaré al Barrio de los Magos para que te reúnas con el alto señor supremo cuando estés $Ulisto:lista;.', 28153),
(156562, 'esMX', '', 'Campeones, la hora se acerca. La Alianza caerá ante nuestras espadas si intenta aferrarse a nuestra preciada fortaleza de Lordaeron.', 28153),
(156560, 'esMX', 'Adalides de la Alianza, ¡ha llegado la hora de recuperar lo que nos pertenece por derecho! Al amanecer se iniciará el ataque final para recuperar la fortaleza de Lordaeron. ¡La Horda y su jefa de guerra responderán por sus crímenes!', '', 28153),
(156559, 'esMX', '', 'Podrás encontrar a tu colega natonocturno en el Salón de los Paso\' Ancestrales. Ven a verme cuando tu búh\'queda haya terminado.', 28153),
(156558, 'esMX', '', 'Mi padre conserva mucho\' de sus tesoros aquí, en la bóveda real.', 28153),
(156557, 'esMX', '', 'Dicen que el Gran Sello es una de las pocas cosa\' en pie que son más antigua\' que el Imperio zandalari.', 28153),
(156556, 'esMX', '', 'Sígueme, $uhéroe:heroína;. Te moh\'traré el lugar.', 28153),
(156555, 'esMX', 'Será mejor que te encargue\' de esto.', '', 28153),
(156554, 'esMX', 'He perdido la noción del tiempo en esta celda. Pero eso no importa, a fin de cuentas.', '', 28153),
(156553, 'esMX', 'Me llamo Sam... Sam Williams. Me alegra tener a alguien con un arma de nuestro lado para variar.', '', 28153),
(156552, 'esMX', 'Estos piratas son seres horribles e impuros. Mátalos con impunidad.', 'Estos piratas son seres horribles e impuros. Mátalos con impunidad.', 28153),
(156551, 'esMX', '¿En qué nos hemos metido?', '¿En qué nos hemos metido?', 28153),
(156550, 'esMX', '¡Volverán a verme, monstruos!', '¡Volverán a verme, monstruos!', 28153),
(156549, 'esMX', '¡Maté decenas de estos monstruos nefastos antes de que me superaran!', '¡Maté decenas de estos monstruos nefastos antes de que me superaran!', 28153),
(156548, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(156547, 'esMX', '¡Nadie queda atrás!', '¡Nadie queda atrás!', 28153),
(156546, 'esMX', '¡Sabía que Aterravermis no nos abandonaría aquí!', '¡Sabía que Aterravermis no nos abandonaría aquí!', 28153),
(156545, 'esMX', 'Te debo un trago en el barco.', 'Te debo un trago en el barco.', 28153),
(156544, 'esMX', 'Jamás imaginé que pudieran comer tanto...', '', 28153),
(156543, 'esMX', 'Los ranishu tienen un apetito insaciable, pero no son muy brillantes. Comen todo lo que se les cruza por delante, hasta a los de su propia especie. ¡Usemos eso a nuestro favor!', '', 28153),
(156542, 'esMX', '', '<Garona hace girar sus espadas y parecen desvanecerse.>', 28153),
(156541, 'esMX', 'Estas águilas de guerra nos llevarán a nuestro destino. ¿Todo listo? ¡Entonces, a volar!', '', 28153),
(156540, 'esMX', 'Vamos.', '', 28153),
(156539, 'esMX', 'Mi reina ha organizado todo. Nuestro transporte nos aguarda en las murallas.', '', 28153),
(156538, 'esMX', 'Solo quería una parte de su enorme botín.', 'Solo quería una parte de su enorme botín.', 28153),
(156537, 'esMX', '¡Volveré, piratas! ¡Volverán a saber de mí!', '¡Volveré, piratas! ¡Volverán a saber de mí!', 28153),
(156536, 'esMX', '¡Maten a toda esa tripulación de cobarde\'!', '¡Maten a toda esa tripulación de cobarde\'!', 28153),
(156535, 'esMX', 'Extraño Zuldazar... ¿Hasta cuándo debo sufrir aquí?', 'Extraño Zuldazar... ¿Hasta cuándo debo sufrir aquí?', 28153),
(156534, 'esMX', 'Ni siquiera hay tesoros aquí. ¡Pura\' mentiras!', 'Ni siquiera hay tesoros aquí. ¡Pura\' mentiras!', 28153),
(156533, 'esMX', '¡No me dejan unirme a su tripulación! No e\' justo.', '¡No me dejan unirme a su tripulación! No e\' justo.', 28153),
(156532, 'esMX', 'Un geh\'to poco común en el desierto.', 'Un geh\'to poco común en el desierto.', 28153),
(156531, 'esMX', 'Creí que nadie vendría por mí. Gracia\', $Uforastero:forastera;.', 'Creí que nadie vendría por mí. Gracia\', $Uforastero:forastera;.', 28153),
(156530, 'esMX', 'Algo se abrió.', '', 28153),
(156529, 'esMX', 'Aún faltan más...', '', 28153),
(156528, 'esMX', 'Creo que son todos. Muy bien, $p. Sabía que podía contar contigo.', '', 28153),
(156527, 'esMX', 'Aún hay muchos vulperas atrapados en los túmulos. ¿Podemos pedirte que nos ayudes a rescatarlos?', '', 28153),
(156526, 'esMX', 'El Barredor calibrado cuidadosamente emite una nota breve cuando no puede encontrar ningún fósil en las inmediaciones.', 'El Barredor calibrado cuidadosamente emite una nota breve cuando no puede encontrar ningún fósil en las inmediaciones.', 28153),
(156525, 'esMX', 'El elemental de excavación refunfuña con fastidio porque no encuentra ningún fósil en las inmediaciones.', 'El elemental de excavación refunfuña con fastidio porque no encuentra ningún fósil en las inmediaciones.', 28153),
(156524, 'esMX', '', '¡Por Gilneas!', 28153),
(156523, 'esMX', '', '¡Guardias, muévanse! ¡Tráiganme sus cabezas!', 28153),
(156522, 'esMX', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t ¡El guardián titánico Hezrel comienza a lanzar |cFFF00000|Hspell:269310|h[Luz purificadora]|h|r!', '', 28153),
(156521, 'esMX', '', '¿Así que la Horda ha decidido venir a atacarnos? Me han ahorrado el esfuerzo de tener que rastrearlos yo misma. ¡Gilneanos, ataquen!', 28153),
(156520, 'esMX', 'Esto requiere más matemáticas de lo que pensaba. Ven a verme más tarde para cobrar tu parte del tesoro.', '', 28153),
(156519, 'esMX', '', 'Es un trabajo para cinco personas, como en el banco de Forjaz.', 28153),
(156518, 'esMX', 'Seremos héroes...¡héroes asquerosamente ricos!', '', 28153),
(156517, 'esMX', 'Hazme rico, $p, ¡quiero comprarme unos dientes de oro!', '', 28153),
(156516, 'esMX', '', '¿Qué tal ese diente Eddard?', 28153),
(156514, 'esMX', '', 'Tuve un sueño con esto, pero estaba en el banco de Forjaz.', 28153),
(156513, 'esMX', '', 'Cuando consigamos el oro, voy a comprarme un perfume muy elegante y voy a bañarme en él.', 28153),
(156512, 'esMX', 'Quizá nos volvamos a ver. ¡Hasta pronto!', '', 28153),
(156511, 'esMX', 'Somo\' libres...', '', 28153),
(156510, 'esMX', 'Debemos... eh\'capar...', '', 28153),
(156509, 'esMX', '', 'Gracias por tu ayuda, $n. Debo seguir en otra parte.', 28153),
(156508, 'esMX', '', 'No fingiré que comprendo tus motivos, $n, pero valoro que derribaras a otro Caballero de la muerte.', 28153),
(156507, 'esMX', '', '¡Mira los cielos, $n! ¡Siento que algo se acerca!', 28153),
(156506, 'esMX', '¿Qué cuentas, $p?', 'Si hay oro de por medio, ¡cuenta conmigo!', 28153),
(156505, 'esMX', 'Necesito tu ayuda.', 'Necesito tu ayuda.', 28153),
(156504, 'esMX', 'Sobreviví al Rey Exánime solo para caer ante los de tu clase... Agh...', '', 28153),
(156503, 'esMX', 'Qué desperdicio...', '', 28153),
(156502, 'esMX', 'Necesito tu ayuda.', 'Necesito tu ayuda.', 28153),
(156501, 'esMX', 'Tú ganas... dragón...', '', 28153),
(156500, 'esMX', 'Muerte... eterna...', '', 28153),
(156499, 'esMX', 'No es... justo...', '', 28153),
(156498, 'esMX', 'Entonces me llevaré lo que me corresponde... ¡por la fuerza!', '', 28153),
(156497, 'esMX', 'Ah, ¡ahora entiendo, $n! ¡Quieres ser $Uel:la; Caballero de la muerte con la montura más espléndida de todas!', '', 28153),
(156496, 'esMX', 'Pero había puesto mi atención en la bestia de huesos ancestral que está detrás de ti. Así que, si no te importa, me llevaré lo que me pertenece.', '', 28153),
(156495, 'esMX', 'El draco que habita ahí es pequeño... y aún está con vida. Difícilmente sea el mayor obstáculo.', '', 28153),
(156494, 'esMX', 'Estoy siguiendo tus pasos. ¿Vienes a ayudarme? ¡Veo que trajiste un obsequio!', '', 28153),
(156493, 'esMX', '¡$USeñor de la muerte:Señora de la muerte; $n! ¡Qué sorpresa!', '', 28153),
(156492, 'esMX', 'Agh. Si prefieres el camino difícil, ¡que así sea!', '', 28153),
(156491, 'esMX', '', '¡$n, protégeme! ¡El ritual se debe completar!', 28153),
(156490, 'esMX', 'Así que apártate, pequeño dragoncito, tengo asuntos que atender con esa pila de huesos.', '', 28153),
(156489, 'esMX', 'Creo que me atendré a mi plan original y me quedaré con el más antiguo.', '', 28153),
(156488, 'esMX', '¡Salgamos de aquí!', '¡Salgamos de aquí!', 28153),
(156487, 'esMX', 'Un caballero de mi altura debería tener la mejor montura de todas.', '', 28153),
(156486, 'esMX', '¡Dos dragones! ¡Pero qué sorpresa! Aunque el que sigue vivo es... penoso.', '', 28153),
(156485, 'esMX', '', '¡No eres $Ubienvenido:bienvenida; aquí, Caballero de la muerte!', 28153),
(156484, 'esMX', 'Vaya, vaya, vaya. ¿Qué tenemos aquí?', '', 28153),
(156483, 'esMX', 'Los seguidore\' de Zul no permitirán que Rezan escape a su destino con tanta facilidad. Debemo\' luchar para salir de aquí.\n\n¿Todo listo?', '', 28153),
(156482, 'esMX', '¿Por qué tanta prisa? Tranquilízate. Respira... ¡toma una siesta! Estás a salvo con nosotros.', '', 28153),
(156481, 'esMX', 'Mi padre nos enseñó el trabajo de la forja... Este martillo fue el primero que hicimos juntos.', '', 28153),
(156480, 'esMX', '¡Mi martillo! ¡Lo recuperaste!', '', 28153),
(156479, 'esMX', '', 'Estos exiliado\' son lo más parecido que tengo a una familia.', 28153),
(156478, 'esMX', '', '$UBienvenido:Bienvenida; a la pandilla, $p.', 28153),
(156477, 'esMX', '$UBienvenido:Bienvenida; a la pandilla, $p.', '', 28153),
(156476, 'esMX', '', '$UBienvenido:Bienvenida; a la pandilla, $p.', 28153),
(156475, 'esMX', '$UBienvenido:Bienvenida; a la pandilla, $p.', '', 28153),
(156474, 'esMX', '¿Necesitas una bebida fuerte o algo de comer?', '¿Necesitas una bebida fuerte o algo de comer?', 28153),
(156473, 'esMX', 'Ah, ¿ere\' tú, $p? Los furiarena no te siguieron, ¿verdad?', '', 28153),
(156472, 'esMX', '¡Unas pocas emboh\'cadas más a las caravanas y luego saquearemo\' la arena para conseguir un verdadero botín!', '', 28153),
(156471, 'esMX', '¡Tengo sed! ¡Roben un poco de ese alcohol zandalari para mí!', '', 28153),
(156470, 'esMX', 'Noh\' queda poca madera para fogatas. ¡Buh\'quen otra caravana vulpera para saquear!', '', 28153),
(156469, 'esMX', '¡Los desiertos son territorio de loh\' Furiarena! ¡Todoh\' los demás son intrusos!', '', 28153),
(156468, 'esMX', 'Tráiganme más eh\'clavos. Tengo muchas más lanza\' para arrojar.', '', 28153),
(156467, 'esMX', '¡Mátenlo\'! ¡Mátenlo\' como perros!', '', 28153),
(156466, 'esMX', 'Ya no te cree\' tan superior, ¿eh? ¡Zandalari arrogante!', '', 28153),
(156465, 'esMX', '¡Ja! ¡Le di a uno! Justo en el pecho, asqueroso vulpera...', '', 28153),
(156464, 'esMX', '¿Quieres recuperar tu martillo, papa peluda y agusanada? VEN Y QUÍTAMELO.', '', 28153),
(156463, 'esMX', '¡Purgaremos esta peste kultirana de nuestras tierras! $n, llama a la Horda y pongámosle punto final a este caos.', '', 28153),
(156462, 'esMX', 'Debería\' tener cuidado con lo que dices. Yazma es la Suma sacerdotisa de mi loa y cuenta con toda la confianza del rey Rastakhan.$b$bSi lo\' rumores son ciertos, el gran profeta Zul le otorga mucho\' más beneficios.', 'Debería\' tener cuidado con lo que dices. Yazma es la Suma sacerdotisa de mi loa y cuenta con toda la confianza del rey Rastakhan.$b$bSi lo\' rumores son ciertos, el gran profeta Zul le otorga mucho\' más beneficios.', 28153),
(156461, 'esMX', 'Shadra es una loa favorecida dentro del Concilio zanchuli. Por eso, nosotros su\' seguidores disfrutamo\' de muchos privilegios, como el derecho de no tener que responder a individuo\' como tú.', 'Shadra es una loa favorecida dentro del Concilio zanchuli. Por eso, nosotros su\' seguidores disfrutamo\' de muchos privilegios, como el derecho de no tener que responder a individuo\' como tú.', 28153),
(156460, 'esMX', '$UMaldito:Maldita; seas...', '$UMaldito:Maldita; seas...', 28153),
(156459, 'esMX', 'Perderás...', 'Perderás...', 28153),
(156458, 'esMX', 'Mi rey... Lo siento...', 'Mi rey... Lo siento...', 28153),
(156457, 'esMX', 'Pagarán...', 'Pagarán...', 28153),
(156456, 'esMX', 'Por... la Alianza...', 'Por... la Alianza...', 28153),
(156455, 'esMX', 'Lo\' seguidores de Shadra han observado a tu clase con muchísimo interés.$b$BVemos a tu Horda mientra\' se interna más y más en una gran red de mentiras. Pronto, la trampa se cerrará y solo lo comprenderás cuando sea demasiado tarde.', 'Lo\' seguidores de Shadra han observado a tu clase con muchísimo interés.$b$BVemos a tu Horda mientra\' se interna más y más en una gran red de mentiras. Pronto, la trampa se cerrará y solo lo comprenderás cuando sea demasiado tarde.', 28153),
(156454, 'esMX', '¡Muere!', '¡Muere!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'esMX', '¡Te enviaré de regreso a Orgrimmar en pedazos!', '¡Te enviaré de regreso a Orgrimmar en pedazos!', 28153),
(156452, 'esMX', '¡Pagarás por los crímenes que has cometido contra la Alianza!', '¡Pagarás por los crímenes que has cometido contra la Alianza!', 28153),
(156451, 'esMX', 'Sirvo a Shadra, dama de los espías y loa de lo\' venenos. ¿Tú a quién sirves en realidad?', 'Sirvo a Shadra, dama de los espías y loa de lo\' venenos. ¿Tú a quién sirves en realidad?', 28153),
(156450, 'esMX', '¡Muere, escoria de la Horda!', '¡Muere, escoria de la Horda!', 28153),
(156449, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(156448, 'esMX', 'Su excelencia se ha percatado de tu presencia en su dominio. Ve con cuidado.', 'Su excelencia se ha percatado de tu presencia en su dominio. Ve con cuidado.', 28153),
(156447, 'esMX', 'Sigue los pasos de la Madre Tierra, $n.', 'Sigue los pasos de la Madre Tierra, $n.', 28153),
(156446, 'esMX', 'Nuestra cacería en esta tierra apenas comienza.', '', 28153),
(156445, 'esMX', '¿Rhan\'ka aún se esconde en el oasis? Tengo que visitarlo uno de estos días...', '', 28153),
(156444, 'esMX', '¡Sabía que volverías por más! Tengo un lote fresco justo aquí, ideal para ti.', '', 28153),
(156443, 'esMX', '[SCENE SHOWING GENERAL JAKRA\'ZET AND EMPEROR KORTHEK COLLUDING.]', '', 28153),
(156442, 'esMX', 'Las profundidades... te observan...', 'Las profundidades... te observan...', 28153),
(156441, 'esMX', '¡Arrojaré tu cadáver quebrado al mar!', '¡Arrojaré tu cadáver quebrado al mar!', 28153),
(156440, 'esMX', '', '¿Por qué no habré nacido goblin? Ellos valoran más mis habilidades únicas.', 28153),
(156439, 'esMX', 'Debería cerrar un trato con los mareaférrea. Son todavía más idiotas.', '', 28153),
(156438, 'esMX', 'Haz lo que debas mientras nosotros buscamos a Zul, joven adalid. Pero prepárate: pronto necesitaremos de tu ferocidad.', '', 28153),
(156437, 'esMX', '', 'Perseguiremos a esos herejes hasta los confines de Azeroth. Reuniré a mi bandada y haremos llover muerte y rocas sobre las cabezas de estas viles criaturas que se atrevieron a darnos la espalda.\n\nPor ahora, mi bandada buscará en los cielos y descubrirá qué están haciendo Zul y sus traidores.', 28153),
(156436, 'esMX', 'Has dado el golpe de gracia... eh\'ta vez...', '', 28153),
(156435, 'esMX', '<Hacer cola con mi grupo para comenzar una Expedición insular JcJ.>', '<Hacer cola con mi grupo para comenzar una Expedición insular JcJ.>', 28153),
(156434, 'esMX', '<Hacer cola para una Expedición insular JcJ.>', '<Hacer cola para una Expedición insular JcJ.>', 28153),
(156433, 'esMX', '¡Usa el fetiche de Jin\'Tiki para destruir a Zulajin!', '¡Usa el fetiche de Jin\'Tiki para destruir a Zulajin!', 28153),
(156432, 'esMX', 'Solo espero haber ocultado bien mi llave para que seas el único que la encuentre.', '', 28153),
(156431, 'esMX', 'Kaga, nadie puede poner en duda tu valor, pero no estás en condiciones de luchar. $n, yo acompañaré a Kaga. Cuando termines, reúnete con nosotros en la torre de guerra.', '', 28153),
(156430, 'esMX', 'Gracias. Aseguraré la torre de guerra. La necesitaremos para llamar al resto de las tropas.', 'Gracias. Aseguraré la torre de guerra. La necesitaremos para llamar al resto de las tropas.', 28153),
(156429, 'esMX', '', 'Mis hermanas... te matarán...', 28153),
(156428, 'esMX', 'La Horda caerá...', 'La Horda caerá...', 28153),
(156427, 'esMX', 'Siguen a una demente...', 'Siguen a una demente...', 28153),
(156426, 'esMX', 'Monstruos...', 'Monstruos...', 28153),
(156425, 'esMX', 'Te... mataré...', 'Te... mataré...', 28153),
(156424, 'esMX', 'La Horda pagará...', 'La Horda pagará...', 28153),
(156423, 'esMX', 'Por Teldrassil...', 'Por Teldrassil...', 28153),
(156422, 'esMX', 'Hermanas... Lo intenté...', 'Hermanas... Lo intenté...', 28153),
(156421, 'esMX', '', '¡Mi familia murió en Teldrassil! ¡Te mataré!', 28153),
(156420, 'esMX', '', '¡Cobraremos venganza por Teldrassil!', 28153),
(156419, 'esMX', 'Haremos que los kultiranos piensen dos veces antes de apostar contra la Horda.', '', 28153),
(156418, 'esMX', '¡Por Teldrassil y por la Alianza!', '¡Por Teldrassil y por la Alianza!', 28153),
(156417, 'esMX', '¡Muere chillando, escoria de la Horda!', '¡Muere chillando, escoria de la Horda!', 28153),
(156416, 'esMX', '', '¡Asesinos! ¿Cómo se atreven a aparecer por aquí?', 28153),
(156415, 'esMX', '¡Vamos por aquí!', '', 28153),
(156414, 'esMX', '¡Ahora yo caminaré!', '', 28153),
(156413, 'esMX', '¡Ahora iremos a donde yo quiera!', '', 28153),
(156412, 'esMX', '¡Me promocionaron a piernas!', '', 28153),
(156411, 'esMX', '¡Ahora yo conduzco!', '', 28153),
(156410, 'esMX', '¡Que el fuego sagrado te purifique!', '', 28153),
(156409, 'esMX', 'No... Debo encontrar... el anillo...', '', 28153),
(156408, 'esMX', '¡Monstruos! ¡Le enviaré sus cabezas a su Jefa de guerra!', '¡Monstruos! ¡Le enviaré sus cabezas a su Jefa de guerra!', 28153),
(156407, 'esMX', '¡Tu cabeza será un premio para mi reina!', '', 28153),
(156406, 'esMX', '', '¡La Horda pagará por lo que le hicieron a Teldrassil!', 28153),
(156405, 'esMX', '', '¡Te enseñaré cómo se quema un cuerpo!', 28153),
(156404, 'esMX', '', '¡Parece que nuestro trabajo aquí ha terminado! Ve con cuidado, $p.', 28153),
(156403, 'esMX', 'Vengaremos a mis hombres. Lo juro.', 'Vengaremos a mis hombres. Lo juro.', 28153),
(156402, 'esMX', 'Tontos mortales. No pueden detener mi regreso.', '', 28153),
(156401, 'esMX', '', '¡Tú! Horda. Necesito de tus habilidades.', 28153),
(156400, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Hay una nueva |cFFFF0404|Hspell:263420|h[Matriz de poder]|h|r disponible.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Hay una nueva |cFFFF0404|Hspell:263420|h[Matriz de poder]|h|r disponible.', 28153),
(156399, 'esMX', 'Ese trol está más loco que un ranishu.', '', 28153),
(156398, 'esMX', 'Rikati pone los ojos en blanco.', '', 28153),
(156397, 'esMX', 'Está bien, amigo. ¡Ahora mismo! ¡Gracia\'!', '', 28153),
(156396, 'esMX', '¡No hay tiempo para hablar, Rikati! ¡Los furiarena eh\'tán desenfrenados! ¡Oculta tu miel!', '', 28153),
(156395, 'esMX', '¡El Anillo de las mareas será nuestro! ¡La reina Azshara lo exige!', '¡El Anillo de las mareas será nuestro! ¡La reina Azshara lo exige!', 28153),
(156394, 'esMX', '¡No nos detendremos hasta conseguir el anillo!', '¡No nos detendremos hasta conseguir el anillo!', 28153),
(156393, 'esMX', '¿De qué estás hablando? ¿Contar? ¿Yo? No, no, yo no hago eso. Tú debería\' ser quien lleve la cuenta.\n\nCreo que será mejor que vuelvas a empezar.', '', 28153),
(156392, 'esMX', '¿Dónde está el Anillo de las mareas? ¡No pueden ocultarlo!', '¿Dónde está el Anillo de las mareas? ¡No pueden ocultarlo!', 28153),
(156391, 'esMX', 'El Anillo de las mareas se perdió por aquí. ¡Debemos recuperarlo para la reina!', 'El Anillo de las mareas se perdió por aquí. ¡Debemos recuperarlo para la reina!', 28153),
(156390, 'esMX', 'La Estela de la Tormenta crece. ¿Estás con nosotros?', 'La Estela de la Tormenta crece. ¿Estás con nosotros?', 28153),
(156389, 'esMX', '¿Ya he alcanzado el millón de almas?', '¿Ya he alcanzado el millón de almas?', 28153),
(156388, 'esMX', '¡Nadie se interpondrá en el camino de nuestra reina!', '¡Nadie se interpondrá en el camino de nuestra reina!', 28153),
(156387, 'esMX', '¡El Anillo de las mareas es nuestro derecho de nacimiento!', '¡El Anillo de las mareas es nuestro derecho de nacimiento!', 28153),
(156386, 'esMX', 'Todavía podemos detener a Lord Canto Tormenta.', 'Todavía podemos detener a Lord Canto Tormenta.', 28153),
(156385, 'esMX', '¡El anillo será nuestro!', '¡El anillo será nuestro!', 28153),
(156384, 'esMX', '¡La reina Azshara reclama el Anillo de las mareas!', '¡La reina Azshara reclama el Anillo de las mareas!', 28153),
(156383, 'esMX', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t ¡La serpiente dorada absorbe un Oro animado y obtiene |cFFFF0000|Hspell:265991|h[Lustre]|h|r!', '¡La serpiente dorada absorbe un Oro animado y obtiene |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t optional text here |cFFFF0000|Hspell:265991|h[Lustre]|h|r!', 28153),
(156382, 'esMX', '', 'Oh, oh. Eso no está nada bien. ¡NADA BIEN!', 28153),
(156381, 'esMX', 'Usa una de esas sogas para bajar rápidamente a un bote de desembarco... a menos que prefieras nadar.', '', 28153),
(156380, 'esMX', '¡No pienso lavar otra sucia ropa interior de humanos!', '', 28153),
(156379, 'esMX', '', '¡Estoy empapada hasta las medias! Gracias.', 28153),
(156378, 'esMX', '', '¡Ya me cansé de esto!', 28153),
(156377, 'esMX', 'Me salvaste de un destino terrible.', '', 28153),
(156375, 'esMX', 'Mientras estabas de aventuras, yo estudié el arte de la espada.', 'Mientras estabas de aventuras, yo estudié el arte de la espada.', 28153),
(156374, 'esMX', '<El maestro espía Shaw asiente.>', '', 28153),
(156373, 'esMX', 'Llegamos, maestro espía.', '', 28153),
(156372, 'esMX', 'Trabajaré con el maestro espía Shaw. No es muy amigable, pero sabe hacer su trabajo.', '', 28153),
(156371, 'esMX', 'El rey ha convocado varios héroes de peso para esta campaña.', '', 28153),
(156370, 'esMX', 'Alapresta, búscate un rico almuerzo.', '', 28153),
(156369, 'esMX', 'Sígueme, $Umuchacho:muchacha;.', '', 28153),
(156368, 'esMX', '¡Le di en la rodilla!', 'Oh... ¡eso tuvo que doler!', 28153),
(156367, 'esMX', 'No nos rendimos tan fácilmente.', 'Debió huir mientras tenía la oportunidad.', 28153),
(156366, 'esMX', '¡$uUno:Una; menos!', '¡No eres tan $urudo:ruda; como creías!', 28153),
(156365, 'esMX', 'Hola, capitana Stone. Estaba ansioso por conocerte.', '', 28153),
(156364, 'esMX', 'Entonces, súbelo a la carreta. Es más útil de lo que pensaba, señorita Voss.', '', 28153),
(156363, 'esMX', '', 'Lo suficiente.', 28153),
(156362, 'esMX', '¿Casi intacto?', '', 28153),
(156361, 'esMX', '', 'Aquí, Clamañublo. He recuperado el cuerpo.', 28153),
(156360, 'esMX', 'Buen trabajo, $p. Bien, ¿dónde está Lilian?', '', 28153),
(156359, 'esMX', 'Tiene\' que apresurarte... ¡van por Rezan!', '', 28153),
(156358, 'esMX', 'Me obligaron... Me obligaron a decirle\' cómo lo hicieron los Drakkari.', '', 28153),
(156357, 'esMX', 'Excelente. Adalid, Taelia te pondrá al tanto.', '', 28153),
(156356, 'esMX', '', '¡Señor! ¡El informe de la situación está listo!', 28153),
(156355, 'esMX', '', '¡Has reducido su ejército a cenizas! Bien hecho.', 28153),
(156354, 'esMX', '', 'Las brujas empiezan a recuperar sus fuerzas. ¡Apodérate de un demoledor y destruye su ejército!', 28153),
(156353, 'esMX', '', 'Debemos enseñarle a los kultiranos qué significa ser enemigo de la Horda.', 28153),
(156352, 'esMX', 'Recuerda: Puerto del Puente es un asentamiento importante con muchos guardias. Quédate en los límites de la ciudad... por ahora.', '', 28153),
(156351, 'esMX', 'Nosotros cumplimos con nuestra parte, $p. Estoy orgulloso de lo que hemos logrado.\n\nPero ahora es momento de cuidar de mi pueblo y velar por su seguridad.\n\nSeguro nos veremos de nuevo. Es un orgullo contarte entre mis amigos.', '', 28153),
(156350, 'esMX', 'Los infieles tratan a sus bestias con crueldad. No es difícil volverlas contra sus amos.', '', 28153),
(156349, 'esMX', 'No tengo que soportar eh\'to. ¡Zul el Profeta me asignó eh\'te puesto!', '', 28153),
(156348, 'esMX', '', '¡Esa SÍ que fue una batalla digna de canciones!\n\nEs un honor pelear junto a Vorrik y a ti. Espero que se repita pronto.\n\nDespués de todo, siempre hay más infieles que matar.', 28153),
(156347, 'esMX', 'Terminemos con esto juntos.', '', 28153),
(156346, 'esMX', '', 'Vamos a enseñarles una lección a estos sethrak.', 28153),
(156345, 'esMX', '', 'Estos suministros nos ayudarán a continuar nuestra lucha contra el aquelarre. Gracias.', 28153),
(156344, 'esMX', 'Sígueme, la fortaleza está cerca.', '', 28153),
(156343, 'esMX', 'Bien. Entonces ese será nuestro objetivo.', '', 28153),
(156342, 'esMX', '', 'El pueblo que pasamos, Puerto del Puente, parece la mayor amenaza del lugar.', 28153),
(156341, 'esMX', '¡Rexxar! <tose> ¡Aún quedan muchos vivos! No... No les queda mucho tiempo.', '¡Rexxar! <tose> ¡Aún quedan muchos vivos! No... No les queda mucho tiempo.', 28153),
(156340, 'esMX', 'Esa bestia ya no se alimentará con soldados de la Horda. Una buena muerte, adalid.', '', 28153),
(156339, 'esMX', '', 'Nos estamos quedando sin plata, que es crucial para nuestra lucha contra las brujas. Métete en las minas y recoge toda la que puedas.', 28153),
(156338, 'esMX', 'Parece que Rakjan está dispuesto a ayudarnos, y es muy comprensible.\n\nLos infieles han sido crueles con él y su prole. Mira las cicatrices de su cuerpo y las perchas vacías en su pico.\n\nMerece ser vengado como cualquiera de nosotros. Y lo conseguiremos juntos.', '', 28153),
(156337, 'esMX', 'Sí, Samuel. No pierdas las fuerzas.', '', 28153),
(156336, 'esMX', 'Tengo mucho frío. ¿Las voces se callarán pronto?', '', 28153),
(156335, 'esMX', '$n, revuelve un poco mi brebaje o se quemará.', '', 28153),
(156334, 'esMX', 'Un gran trabajo. Asegurémonos de que esta sea la última fiesta del consejo.', '', 28153),
(156333, 'esMX', 'Buen trabajo, $Uricachón:ricachona;. Ahora estamo\' listos para aguarle la fiesta al consejo.', '', 28153),
(156332, 'esMX', 'Calma... Las hierbas aliviaran tus heridas. ¿Puedes contarnos algo sobre el interior de la fortaleza? ¿Hay más sobrevivientes?', '', 28153),
(156331, 'esMX', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t ¡El daño del Goliat ligado al alma aumenta con cada acumulación de |cFFFF0404|Hspell:260512|h[Cosecha de almas]|h|r!', '', 28153),
(156330, 'esMX', '¡Miren! ¡Aquí hay alguien que todavía respira!', '', 28153),
(156329, 'esMX', 'Muchos guerreros valientes cayeron en la batalla. Tu llegada fue una bendición.', '', 28153),
(156328, 'esMX', 'Mientras intentábamos salvar a la tripulación, los kultiranos atacaron. Nuestras tropas estaban muy dispersas para proteger los dos lugares y tuvimos que volver a la costa.', '', 28153),
(156327, 'esMX', 'El ataque ocurrió esta mañana. Los magos kultiranos usaron un objeto extraño para invocar esos horrores que viste alrededor de nuestros barcos.', '', 28153),
(156326, 'esMX', '¡Ja! Confirmado. Misión cumplida. ¡Pura perfección! ¡Ja, ja! Me encanta cuando un plan se concreta, jaja. Cambio y fuera.', '', 28153),
(156325, 'esMX', 'Instrucciones. ¿Ven ese botón rojo enorme? Sí. Salgan del área y opriman el botón. Ejecuten cuando estén listos. Cambio.', '', 28153),
(156324, 'esMX', 'Código de autenticación: uno-nueve-nueve. Uhm. Alineación de instrumentos por encima de parámetros admisibles... Pero esto puede funcionar. Aguarden. Cambio.', '', 28153),
(156323, 'esMX', 'Entendido. Sí. Calibración completa. Todos deben orientar los instrumentos en lugares muy específicos. Contáctenme cuando estén en posición. Cambio.', '', 28153),
(156322, 'esMX', 'Prueba de radio. Aquí, Alfa 1. Me dirijo al grupo, escuadrón Alfa. ¿Me copian? Cambio.', '', 28153),
(156321, 'esMX', '¡Una batalla gloriosa! ¡Y sobrevivimos, $p!', '', 28153),
(156320, 'esMX', '', 'La llama nunca muere...', 28153),
(156319, 'esMX', '', 'Cenizas a las cenizas...', 28153),
(156318, 'esMX', 'Tus grandes actos nos dejan sin palabras. Muchas gracias, $p.', '', 28153),
(156317, 'esMX', '', 'Tus huesos servirán para encender la fogata.', 28153),
(156316, 'esMX', '', 'No dejaré a nadie que llore sobre tus cenizas.', 28153),
(156315, 'esMX', '¡No hay muchos días tan gloriosos como este en nuestra extensa historia!', '', 28153),
(156314, 'esMX', '¡Voy a crear una sopa nueva en tu honor!', '', 28153),
(156313, 'esMX', 'La sopa de tortuga no se compara con la sopa de $r.\n\nConsigue carne de gusano fangoso y deja a las tortuguitas en paz.\n\n¡Vuelve a visitarme algún día y podemos explorar otras opciones de sopa!', '', 28153),
(156312, 'esMX', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t ¡El %s comienza a lanzar |cFFFF0000|Hspell:267334|h[Orbe de corrupción]|h|r!', 'Aparece una proyección a la distancia...', 28153),
(156311, 'esMX', '', 'Es fácil perder el rumbo.', 28153),
(156310, 'esMX', '¡Avísame si vuelve\' a necesitar mi ayuda!', '', 28153),
(156309, 'esMX', 'Ahora que todo eh\'tá arreglado, creo que es hora de regresar.', '', 28153),
(156308, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo al Canal de Tiragarde.', '|cFF0000FF(Misión)|r Zarpar rumbo al Canal de Tiragarde.', 28153),
(156307, 'esMX', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t ¡El %s comienza a lanzar |cFFFF0000|Hspell:265360|h[Engaño turbador]|h|r!', 'Aparece una proyección a la distancia...', 28153),
(156306, 'esMX', '', 'Me alegra contar con tu ayuda, adalid.', 28153),
(156305, 'esMX', '', 'Las sombras del pasado nos rodean.', 28153),
(156304, 'esMX', '¿Sabes qué música escucho cuando quiero relajarme? ¡Heavy mitril, por supuesto! ¡Jajajajaja!', '', 28153),
(156303, 'esMX', '¿Te gusta quemar naves?', '', 28153),
(156302, 'esMX', '¡No me obligues a usar el martillo!', '', 28153),
(156301, 'esMX', 'Que tu llama crezca sin cesar.', '', 28153),
(156300, 'esMX', 'Que tu forja siempre arda.', '', 28153),
(156299, 'esMX', '¡Pásala bien!', '', 28153),
(156298, 'esMX', '¿Has visto mi llave inglesa por ahí?', '', 28153),
(156297, 'esMX', '¿Cómo puedo ayudarte?', '', 28153),
(156296, 'esMX', '¡Fuego a discreción!', '', 28153),
(156286, 'esMX', '', 'Tanto sufrimiento. Tantas pérdidas.', 28153),
(156285, 'esMX', '', '¿Qué camino debo seguir?', 28153),
(156284, 'esMX', '', 'Debo hallar mi lugar entre los acontecimientos.', 28153),
(156283, 'esMX', 'La arena es roja.', 'La arena es roja.', 28153),
(156282, 'esMX', '¿Cómo terminé aquí?', '¿Cómo terminé aquí?', 28153),
(156281, 'esMX', 'Mis amigos me vengarán.', 'Mis amigos me vengarán.', 28153),
(156280, 'esMX', 'Así que Turalyon brilla por todos lados, Alleria está toda sombría... Mmm... ¡Supongo que ahora que estoy de regreso debería buscarme algo que me distinga!', '', 28153),
(156279, 'esMX', '¿Lo hice bien?', '¿Lo hice bien?', 28153),
(156278, 'esMX', '¡Te destruiré!', '¡Te destruiré!', 28153),
(156277, 'esMX', '¡Este será tu fin!', '¡Este será tu fin!', 28153),
(156276, 'esMX', '¡No puedes detenernos!', '¡No puedes detenernos!', 28153),
(156275, 'esMX', 'Gracias a la Luz al fin salí de Bastión del Honor. Ese lugar ya estaba empezando a apestar demasiado.', '', 28153),
(156274, 'esMX', '¡Hoy no, maligno!', '¡Hoy no, maligno!', 28153),
(156273, 'esMX', 'Khadgar y yo nos reunimos una vez a la semana para jugar a las damas. (Te aviso... hace trampas.)', '', 28153),
(156272, 'esMX', 'Cada cual debe cumplir con su parte.', '', 28153),
(156271, 'esMX', '¡Por Stromgarde!', '', 28153),
(156270, 'esMX', 'No te mentiré, $Ujefe:jefa;.\n\nSiempre he querido participar en un motín.', '', 28153),
(156269, 'esMX', '¡Por la Alianza!', '', 28153),
(156268, 'esMX', 'La Alianza prevalecerá.', '', 28153),
(156267, 'esMX', 'Lucha bien, camarada.', '', 28153),
(156266, 'esMX', 'Azeroth llama, y debemos responder.', '', 28153),
(156265, 'esMX', 'Pelearemos por lo que nos pertenece.', '', 28153),
(156264, 'esMX', 'Enfrentaremos cualquier destino juntos.', '', 28153),
(156263, 'esMX', 'Mi vida por la Alianza.', '', 28153),
(156262, 'esMX', 'Stromgarde volverá a erguirse orgullosa.', '', 28153),
(156261, 'esMX', 'No me importa lo que creas, voy a decirlo de todos modos... ¡EEEEES LA HORA DEL MARTILLO!!!', '', 28153),
(156260, 'esMX', 'Podría decirse que sufro el síndrome del hijo del medio. Porque si un hermano está hecho de diamante y el otro es un explorador famoso, ¡no es fácil destacarse!', '', 28153),
(156259, 'esMX', '¡¿Pero qué...?! ¡Alguien acaba de llamarme \"Rey Karamelo\" y me pidió que le diera una paleta!', '', 28153),
(156258, 'esMX', '¡Jamás nos rendimos!', '', 28153),
(156257, 'esMX', 'El clan Barbabronce te lo agradece, adalid.', '', 28153),
(156256, 'esMX', 'Forjaz vencerá.', '', 28153),
(156255, 'esMX', 'Que tu camino te conduzca a la gloria.', '', 28153),
(156254, 'esMX', 'Que tu martillo impacte con fuerza.', '', 28153),
(156253, 'esMX', 'Que la forja te acompañe, $uamigo:amiga;.', '', 28153),
(156252, 'esMX', 'Tengo mi martillo y mi hacha... ¡A trabajar!', '', 28153),
(156251, 'esMX', '¿Viniste a ayudar a la Alianza?', '', 28153),
(156250, 'esMX', 'Los Tres Martillos pelean unidos.', '', 28153),
(156249, 'esMX', 'Forjaz está lista para hacer su aporte.', '', 28153),
(156248, 'esMX', '¿Sabes qué les paso a las seis primeras legiones? ¿Te gustaría descubrirlo?', '', 28153),
(156247, 'esMX', '¿Quieres visitar el reclusadero, soldado?', '', 28153),
(156246, 'esMX', 'Pones a prueba mi paciencia.', '', 28153),
(156245, 'esMX', 'Nuestro trabajo apenas comienza.', '', 28153),
(156244, 'esMX', 'Hasta que nos volvamos a ver.', '', 28153),
(156243, 'esMX', 'Que la Luz te acompañe.', '', 28153),
(156242, 'esMX', 'Por el poder de la Alianza, nuestros enemigos verán solo la derrota.', '', 28153),
(156241, 'esMX', 'Por la Luz, el primer golpe es nuestro.', '', 28153),
(156240, 'esMX', 'Tu leyenda crece.', '', 28153),
(156239, 'esMX', 'El destino nos sonríe hoy.', '', 28153),
(156238, 'esMX', 'La Horda caerá.', '', 28153),
(156237, 'esMX', 'Soldado.', '', 28153),
(156236, 'esMX', 'Somos los hijos y las hijas de la Alianza.', '', 28153),
(156235, 'esMX', '', 'Debemos defender este mundo. ¡Adelante, Hierro Negro! ¡Marchemos a la batalla!', 28153),
(156234, 'esMX', '', 'La sangre que corre por las venas de Azeroth... es la misma que corre por nuestras venas.', 28153),
(156233, 'esMX', '', 'Nuestro reino se forjó con yunque y martillo, con corazones ardientes... y voluntades de hierro.', 28153),
(156232, 'esMX', '', 'La montaña nos da la vida. Nos concede la fuerza.', 28153),
(156231, 'esMX', '', 'Thurgaden y Thaelin forjaron una armadura en reconocimiento de tus logros. Úsala con orgullo, $n.', 28153),
(156230, 'esMX', '', 'Ahora la Alianza sabe que los Hierro Negro hablamos en serio. No podría pedir $Uun:una; adalid mejor.', 28153),
(156229, 'esMX', '', 'Regresa a la montaña. Tenemos algo especial para ti.', 28153),
(156228, 'esMX', '', 'Eres un orgullo para nuestro pueblo, $n. He oído anécdotas sobre las hazañas que lograste en tus viajes por Azeroth.', 28153),
(156227, 'esMX', '', 'Nos forjamos en las llamas de la montaña, $n. Muéstrale tu fuego al mundo.', 28153),
(156226, 'esMX', '', 'Azeroth te aguarda, y el primer yunque que golpearás está en Ventormenta.', 28153),
(156225, 'esMX', '', 'Es hora de que los Hierro Negro surjan de entre las sombras.', 28153),
(156224, 'esMX', '', 'Muchos de los nuestros se oponen a que salgamos a la superficie. Pero somos valientes y no tenemos miedo.', 28153),
(156223, 'esMX', '¡Por la Alianza!', '', 28153),
(156222, 'esMX', '', 'Los Hierro Negro aceptan su invitación. ¡Por la Alianza!', 28153),
(156221, 'esMX', '', 'Ah, ¡es apenas una formalidad, mi rey! No se preocupe.', 28153),
(156220, 'esMX', 'Sin embargo, nunca le pedimos oficialmente a su clan que se uniera a la Alianza... un desliz que espero sepa disculpar y me permita corregir.', '', 28153),
(156219, 'esMX', '', 'Sí.', 28153),
(156218, 'esMX', 'Y a pesar de que el clan Hierro Negro es reconocido por su... espíritu independiente, la determinación y la lealtad de su pueblo son incuestionables.', '', 28153),
(156217, 'esMX', 'Su posición en el Consejo de los Tres Martillos ha sido de ayuda para mantener el orden y la estabilidad en Forjaz.', '', 28153),
(156216, 'esMX', '', 'Lo mismo digo, rey Wrynn.', 28153),
(156215, 'esMX', 'Reina regente Thaurissan, estoy encantado de volver a verla.', '', 28153),
(156214, 'esMX', '¡Ey! Estoy intentando trabajar.', '', 28153),
(156213, 'esMX', '', 'Gracias. Debemos preservar lo que queda de las granjas de Drustvar.', 28153),
(156212, 'esMX', '', 'Los cerdos de un granjero local se perdieron en la espesura del bosque. ¡Sálvalos antes de que las esporas se los lleven!', 28153),
(156211, 'esMX', '', 'Has desenmascarado a las brujas y mi pueblo está otra vez a salvo. Gracias.', 28153),
(156210, 'esMX', '', 'El aquelarre intenta infiltrarse en Alto de Arom. Descubre sus planes y quema su corrupción antes de que le hagan daño a alguien.', 28153),
(156209, 'esMX', '<Ofrecer polvo coagulante: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Ofrecer polvo coagulante: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'esMX', '<Ofrecer pergamino tortollano ancestral: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Ofrecer pergamino tortollano ancestral: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'esMX', '<Ofrecer salmuera de erizo de mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Ofrecer salmuera de erizo de mar: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'esMX', '<Ofrecer especias astringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Ofrecer especias astringentes: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'esMX', 'Mantente alerta, $n. Te daré las indicaciones en cuanto necesite más ingredientes.', '', 28153),
(156204, 'esMX', 'Eh\'to está más allá de todos nosotros. ¡El loa de la muerte se ha apoderado de él!', '', 28153),
(156203, 'esMX', 'Bueno. Me temo que esto... está más allá de mis habilidades.', '', 28153),
(156202, 'esMX', '¡Jamil Abul\'housin se encoge de terror!', '', 28153),
(156201, 'esMX', '¿Jamil...?', '', 28153),
(156200, 'esMX', 'En breve.', '', 28153),
(156199, 'esMX', 'Listo... El rey debería despertarse.', '', 28153),
(156198, 'esMX', 'La sangre no se detiene. ¡Rápido, $n, trae el polvo coagulante de inmediato!', '', 28153),
(156196, 'esMX', 'La oración de Jamil Abul\'housin se vuelve más potente y desesperada.', '', 28153),
(156195, 'esMX', '¡Listo! Administraré la poción.', '', 28153),
(156194, 'esMX', 'Jamil Abul\'housin comienza a recitar una oración entre dientes.', '', 28153),
(156193, 'esMX', 'Bien, TRES pizcas.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'esMX', 'Han pasado setecientos años desde que la creé. Quisiera verte tratando de recordar algo más viejo que tu tatarabuelo.', '', 28153),
(156191, 'esMX', '¡¿Olvidaste la receta?!', '', 28153),
(156190, 'esMX', '¿Era una o dos pizcas...? $n, tráeme mi pergamino.', '', 28153),
(156188, 'esMX', 'Gracias. Estoy haciendo la mezcla lo más rápido que puedo. Paciencia.', '', 28153),
(156187, 'esMX', '¿Nada? Jol, será mejor que te apresure\' con esa medicina...', '', 28153),
(156186, 'esMX', 'Ahora la salmuera. Fíjate en la despensa.', '', 28153),
(156185, 'esMX', '¡No dejen que los crustájeos escapen!', '¡No dejen que los crustájeos escapen!', 28153),
(156184, 'esMX', 'Estoy listo, Jol.', 'Estoy lista, Jol.', 28153),
(156183, 'esMX', 'Estos ingredientes son complicados. Requieren toda mi atención. Tú deberás ser mis manos para que pueda completar este brebaje. Recuerda, la vida del rey está en peligro.\n\n¿Estás $Ulisto:lista; para empezar?', '', 28153),
(156182, 'esMX', '', 'Si lo que dice este exiliado e\' cierto, debes investigar. Pero ten cuidado. Jakra\'zet aún debe eh\'tar cerca.', 28153),
(156181, 'esMX', 'Ah, ¡creí que no te importaba! ¿Por dónde empiezo?\n\nHacemos este peregrinaje a Nazmir una vez cada cierta cantidad de años. A veces pasan cinco años, otras veces pueden pasar veinte, depende del momento en que Torga esté listo para contar una anécdota.\n\nCuando oímos rumores y susurros de que Torga tiene una historia que contarnos, emprendemos nuestro peregrinaje. Venimos, nos sentamos y escuchamos todas las historias de Torga. Luego, se las contamos a todos los que nos cruzamos en el camino.\n\nDeberías considerarte $Uafortunado:afortunada;. No es común ver a tantos de nosotros reunidos de esta forma. Es una anécdota que puedes contarles a tus amigos $r, si es que les interesa.', '', 28153),
(156180, 'esMX', 'Sobre mi... cadáver...', 'Sobre mi... cadáver...', 28153),
(156179, 'esMX', 'Cuéntame sobre este peregrinaje en el que te encuentras.', 'Cuéntame sobre este peregrinaje en el que te encuentras.', 28153),
(156178, 'esMX', '¡Nadie escapa cuando estoy a cargo!', '¡Nadie escapa cuando estoy a cargo!', 28153),
(156177, 'esMX', 'Digamos que es un empate.', '', 28153),
(156176, 'esMX', 'Una nueva pólvora, jamás había visto algo así.', '', 28153),
(156175, 'esMX', 'Boralus me pertenece.', '', 28153),
(156174, 'esMX', '¿Qué sucede?', '¿Qué sucede?', 28153),
(156173, 'esMX', '', '¡Por la Horda!', 28153),
(156172, 'esMX', '', '¡Bien, bien! Ahora llévanos lejos de los explosivos, cruzando el puente.', 28153),
(156171, 'esMX', '', '¡No se detengan! Reúnan a todos los guardias del pueblo... ¡Y a su líder!', 28153),
(156170, 'esMX', '', '¡Vengan por nosotros, cobardes!', 28153),
(156169, 'esMX', '', '¡La Horda los destrozará!', 28153),
(156168, 'esMX', '', '¡Kultiranos! ¡Su trato con la Alianza significará su muerte!', 28153),
(156167, 'esMX', '', '¡Vayan al pueblo y reúne a todos los guardias que puedas!', 28153),
(156166, 'esMX', '', '¡Flynn! ¡Por aquí!', 28153),
(156165, 'esMX', '¿Cómo es que fallé?', '¿Cómo es que fallé?', 28153),
(156164, 'esMX', '', 'Ha llegado la hora. ¡Acaben con la capitana y los velaniebla seremos libres!', 28153),
(156163, 'esMX', '', '¿Y crees que tú sabes lo que es salir con un chico malo? Ay, amiga... no tienes la menor idea...', 28153),
(156162, 'esMX', '', 'Qué raro... Nunca me di cuenta de que había perdido mi acento kultirano.', 28153),
(156161, 'esMX', '', 'Claro que tengo mi bastón para ovejas. ¿Quién crees que acuñó el término \"lanomante\"?', 28153),
(156160, 'esMX', 'Robemos unas armas antes de irnos.', 'Robemos unas armas antes de irnos.', 28153),
(156159, 'esMX', 'Comerciar personas... está muy mal.', 'Comerciar personas... está muy mal.', 28153),
(156158, 'esMX', 'Revolviendo', 'Revolviendo', 28153),
(156157, 'esMX', '¡Los vulpera ya no toleraremos esto!', '¡Los vulpera ya no toleraremos esto!', 28153),
(156156, 'esMX', '¡Eso no es todo lo que tenemos!', '', 28153),
(156155, 'esMX', 'No quiero volver a ver un sethrak jamás.', 'No quiero volver a ver un sethrak jamás.', 28153),
(156154, 'esMX', '¡Por eso no debes golpear a una tortuga!', '', 28153),
(156153, 'esMX', '¡Creo que querían comerme!', '¡Creo que querían comerme!', 28153),
(156152, 'esMX', '¡Por la arena del desierto, me alegra verte!', '¡Por la arena del desierto, me alegra verte!', 28153),
(156151, 'esMX', '', 'Después de todos estos años, ¿TODAVÍA quieres fastidiarme? Algunas cosas nunca cambian...', 28153),
(156150, 'esMX', '', 'La verdadera batalla nos espera.', 28153),
(156149, 'esMX', '', 'Haré lo que pueda.', 28153),
(156148, 'esMX', '', 'El camino que nos espera no será fácil.', 28153),
(156147, 'esMX', 'Duele más de lo que imaginé.', 'Duele más de lo que imaginé.', 28153),
(156146, 'esMX', 'Me robé algunos de sus cristales... ¡Ahora yo reiré último! ¡Ja!', '', 28153),
(156145, 'esMX', '¡Este caparazón no está en venta!', '', 28153),
(156144, 'esMX', 'De todos modos, ninguno de estos sethrak podía pagar mi precio.', '', 28153),
(156143, 'esMX', 'Los infieles no respetan ni la edad ni la sabiduría.', '', 28153),
(156142, 'esMX', '¡Les contaré esta historia a todos en Zuldazar!', '', 28153),
(156141, 'esMX', '', 'No podemos permitir que el mundo caiga en la oscuridad.', 28153),
(156140, 'esMX', '¡Finalmente, mi suerte ha empezado a cambiar!', '', 28153),
(156139, 'esMX', 'La jefa de guerra exige que hagamos desaparecer todo rastro de la Alianza en esta región. ¡Aniquílalos de inmediato!', '', 28153),
(156138, 'esMX', '', 'Ya no es hora de soñar.', 28153),
(156137, 'esMX', 'Esos tontos de la Alianza se han agrupado cerca. Ve a visitarlos... y demuéstrales lo inútiles que son sus ambiciones.', '', 28153),
(156136, 'esMX', 'Fuerzas de la Alianza se agrupan cerca de tu posición. Encárgate de que no vean un nuevo amanecer.', '', 28153),
(156135, 'esMX', '', '¿Qué necesitas de la hija del mar?', 28153),
(156134, 'esMX', '¡La Alianza cae ante nosotros! La Dama Oscura estará complacida.', '', 28153),
(156133, 'esMX', '¡Pero qué despiadado! Ahora la Alianza conoce el verdadero poder de nuestra furia.', '', 28153),
(156132, 'esMX', '¡Comiencen a disparar!', '', 28153),
(156131, 'esMX', 'La Alianza... ¡qué patéticos! Ahora lo pensarán dos veces antes de interferir en nuestros planes.', '', 28153),
(156130, 'esMX', '', 'Tenemos un largo camino que recorrer.', 28153),
(156129, 'esMX', '¡Contén el aliento, $p!', '', 28153),
(156128, 'esMX', '', 'La Alianza resistirá.', 28153),
(156127, 'esMX', '', 'Sé qué debo hacer.', 28153),
(156126, 'esMX', '', 'Una sola chispa puede incendiar el mundo.', 28153),
(156125, 'esMX', '', 'Controla tu poder... o te controlará.', 28153),
(156124, 'esMX', 'Por Lordaeron.', 'Por Lordaeron.', 28153),
(156123, 'esMX', '', 'Jamás olvidaré.', 28153),
(156122, 'esMX', '', 'Todos tenemos nuestros fantasmas.', 28153),
(156121, 'esMX', '¡Al fin algo emocionante!', '¡Al fin algo emocionante!', 28153),
(156120, 'esMX', '', 'Cuidado en quién confías.', 28153),
(156119, 'esMX', 'Mi alma tiene sed.', 'Mi alma tiene sed.', 28153),
(156118, 'esMX', '¡Es hora de sangrar!', '¡Es hora de sangrar!', 28153),
(156117, 'esMX', 'Nada mejor que una muerte eficiente. Mantiene nuestros esfuerzos de guerra dentro de los planes.', '', 28153),
(156116, 'esMX', 'Típico... otro enemigo que se encuentra con el poder de la Horda... y pierde.', '', 28153),
(156115, 'esMX', 'La Dama Oscura sabe elegir a sus campeones.', '', 28153),
(156114, 'esMX', 'Un trabajo bastante correcto... aunque le faltó un poco de estilo. Puedes volver a tus tareas normales.', '', 28153),
(156113, 'esMX', 'Ah... los simples placeres de hacer trizas a un enemigo. ¡El deber no tiene por qué impedir el disfrute de una victoria!', '', 28153),
(156112, 'esMX', 'Buen trabajo. Nuestras operaciones pueden seguir como planeamos.', '', 28153),
(156111, 'esMX', 'La Horda pronto controlará esta área, pero un enemigo poderoso se interpone. Despeja el camino para nuestras fuerzas.', '', 28153),
(156110, 'esMX', 'Los planes de la jefa de guerra para esta área no incluyen a ese... monstruo. ¡Extermínalo!', '', 28153),
(156109, 'esMX', '', 'Oye, sabelotodo... ¿Alguna vez se te ocurrió que TU línea temporal es la \"historia alternativa\" y que la MÍA es la VERDADERA? Je... no lo puedes creer, ¿eh?', 28153),
(156108, 'esMX', 'Un enemigo notable está cerca de tu posición. ¿Qué tal si les traes a nuestros investigadores un cadáver para estudiar?', '', 28153),
(156107, 'esMX', 'Un enemigo cercano ha estado despachando a nuestros reclutas más suaves. Confío en que un \"campeón de la Horda\" lo hará mejor.', '', 28153),
(156106, 'esMX', '', 'Libraron una guerra contra la Legión... ¿y no nos pidieron ayuda? ¿En serio? El destino de todo el universo estaba en juego, pero ni si quiera se les ocurrió... Bah, ¡quién los entiende!', 28153),
(156105, 'esMX', 'Los informes indican que hay un enemigo poderoso cerca de tu posición. Acábalo... ¡y recuerda disfrutar del golpe de gracia!', '', 28153),
(156104, 'esMX', 'La jefa de guerra quiere que te encargues de un objetivo en esta área. No la decepciones.', '', 28153),
(156103, 'esMX', '', 'Desde que llegué a la ciudad, estos orcos de Orgrimmar parecen estar más erguidos.', 28153),
(156102, 'esMX', '', 'Un orco verde me dijo que tenía una mirada teaTHRALL... así que le rompí las piernas.', 28153),
(156101, 'esMX', 'El hambre se había apoderado de mí...', 'El hambre se había apoderado de mí...', 28153),
(156100, 'esMX', '', 'Habla rápido. ¡Tenemos batallas que ganar!', 28153),
(156099, 'esMX', '', 'El corazón de los Mag\'har es fuerte y puro.', 28153),
(156098, 'esMX', '', 'Estamos aquí para ganar la guerra.', 28153),
(156097, 'esMX', '', 'Escucharé tus palabras... pero te juzgaré por tus acciones.', 28153),
(156096, 'esMX', '', 'No quiero imaginar lo que habría ocurrido si seguían con esos rituales. Gracias por tu ayuda.', 28153),
(156095, 'esMX', '', 'Habla.', 28153),
(156094, 'esMX', '', 'Volveré a contemplar los cielos de Draenor.', 28153),
(156093, 'esMX', '', 'Somos la guerra.', 28153),
(156092, 'esMX', '', 'Que tus enemigos se postren ante ti.', 28153),
(156091, 'esMX', '', 'Las brujas de Corlain parecen estar probando un nuevo tipo de ritual. ¡Debes detenerlas antes de que sea demasiado tarde!', 28153),
(156090, 'esMX', '', 'Pelea con honor. ¡Muere con gloria!', 28153),
(156089, 'esMX', '', 'Los Mag\'har se alzarán victoriosos.', 28153),
(156088, 'esMX', '', 'Que mueras bien.', 28153),
(156087, 'esMX', '', 'Ve con honor.', 28153),
(156086, 'esMX', '', '¡Throm-ka!', 28153),
(156085, 'esMX', '', '¡Lok-tar!', 28153),
(156084, 'esMX', 'Pobres aves... Que sus espíritus vuelen libres por siempre.', '', 28153),
(156083, 'esMX', 'Los halcones de este lugar han caído bajo la maldición de las brujas. Ojalá pudiéramos salvarlos, pero ya es tarde. ¡Estas cebollas te ayudarán a encargarte de ellos!', '', 28153),
(156082, 'esMX', '', 'Bien hecho. ¿Cuándo deh\'cubrirá la Alianza que los zandalari somos imparable\'?', 28153),
(156081, 'esMX', '', 'Buen trabajo. La Alianza aprenderá a temerle al poder de lo\' zandalari.', 28153),
(156080, 'esMX', '', 'Pronto la Alianza deh\'cubrirá que los zandalari no seremo\' conquistado\'.', 28153),
(156079, 'esMX', '', 'Me ha llegado información de que la Alianza eh\'tá reuniendo fuerzas cerca. Detengan lo que sea que eh\'tén planeando.', 28153),
(156078, 'esMX', '', 'La Alianza cree que puede desafiar al Imperio zandalari. Muéh\'trales la gravedad de su error.', 28153),
(156077, 'esMX', '', '¡Muy bien, muchachos! ¡Hora del motín! ¡Los velaniebla se niegan a vender nuestra libertad!', 28153),
(156076, 'esMX', '', 'Al principio me irritaba toda esa tontería de \"ssssí, reina\". Pero, eh... ¡tienes mi permiso para seguir diciéndolo!', 28153),
(156075, 'esMX', '', 'La Alianza planea algo en las cercanía\'. Acábalos. Que aprendan a temerle al Imperio zandalari.', 28153),
(156074, 'esMX', 'Ahora que hemos lidiado con ese problema podemos descansar más tranquilos.', '', 28153),
(156073, 'esMX', 'Los soldados que pelean por la Alianza no olvidarán lo que has hecho hoy.', '', 28153),
(156072, 'esMX', 'Buen trabajo. Tengo algunas historias de la Tercera Guerra para contarte. Esto me recuerda a esos días.', '', 28153),
(156071, 'esMX', 'Buen trabajo. Estos recursos serán de ayuda más adelante.', '', 28153),
(156070, 'esMX', 'Esta área es un tanto problemática para nuestras fuerzas. Me recuerda a la Segunda Guerra. ¿Podrías ayudarnos?', '', 28153),
(156069, 'esMX', 'Tenemos que lidiar con unos problemas en el área cercana. ¿Podrías encargarte?', '', 28153),
(156068, 'esMX', '', 'Pero claro que mi relación con mi padre es complicada. Ya es bastante difícil relacionarse con un padre común, ¡imagínate con uno de diamantes!', 28153),
(156067, 'esMX', 'El área que te rodea podría sernos muy útil. Debemos despejarla y asegurarla.', '', 28153),
(156066, 'esMX', 'Nos han informado que hay recursos vitales cerca. Si los controlamos, podríamos cambiar el curso de los eventos.', '', 28153),
(156065, 'esMX', '', 'Vamos... cuéntame un chiste de enanos. ¡Veremos hasta dónde llegas con las rodillas rotas!', 28153),
(156064, 'esMX', 'No me hagas perder el estilo.', '', 28153),
(156063, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(156062, 'esMX', '', 'Kiro y yo solo estamos de paso. Nuestra siguiente parada es el imperio de los Infieles. \n\nMi plan está en orden. \n\nEsos sethrak nunca sabrán qué los golpeó.', 28153),
(156061, 'esMX', '', 'Volvemos a vernos.', 28153),
(156060, 'esMX', 'Honras a los caídos de la Séptima Legión. Le daremos un buen uso a esta área.', '', 28153),
(156059, 'esMX', 'Muy bien. Mis soldados se encargarán del resto.', '', 28153),
(156058, 'esMX', '', 'Mi pueblo vive dentro de un volcán. ¡Si sigues molestándome te mostraré la erupción de un Hierro Negro!', 28153),
(156057, 'esMX', 'Excelentes tácticas. Pronto podremos hacer uso de esta área.', '', 28153),
(156056, 'esMX', 'Buen trabajo. Estos recursos servirán a la Séptima Legión durante mucho tiempo.', '', 28153),
(156055, 'esMX', 'Necesitamos tu ayuda para asegurar esta área. Mis fuerzas solas no pueden capturarla.', '', 28153),
(156054, 'esMX', 'Varios de mis soldados han caído tratando de asegurar el área cercana. Extermina la amenaza de inmediato.', '', 28153),
(156053, 'esMX', 'Los exploradores de la Séptima Legión han determinado que esta ubicación es vital. Despéjala para que podamos usarla.', '', 28153),
(156052, 'esMX', '', 'Los Tres Martillos pelean unidos.', 28153),
(156051, 'esMX', 'La Séptima Legión necesita recursos cercanos. Haz lo que sea para conseguirlos.', '', 28153),
(156050, 'esMX', '', 'Que tu martillo impacte con fuerza.', 28153),
(156049, 'esMX', '', 'Que el Yunquenegro te proteja.', 28153),
(156048, 'esMX', '', 'Los Hierro Negro recuperarán su lugar legítimo en el mundo.', 28153),
(156047, 'esMX', '', 'Bien, vamos. ¡Tengo trabajo que hacer!', 28153),
(156046, 'esMX', '', 'Puedes marcharte.', 28153),
(156045, 'esMX', '', 'Puedes retirarte.', 28153),
(156044, 'esMX', '¡Bombardeen a mi objetivo!', '¡Bombardeen a mi objetivo!', 28153),
(156043, 'esMX', '¡Cañones! ¡Abran fuego!', '¡Cañones! ¡Abran fuego!', 28153),
(156042, 'esMX', '¡Objetivo marcado para destrucción!', '¡Objetivo marcado para destrucción!', 28153),
(156041, 'esMX', '¡Artillería! ¡Disparen sobre mi objetivo!', '¡Artillería! ¡Disparen sobre mi objetivo!', 28153),
(156040, 'esMX', '', 'Vamos directo al grano, entonces.', 28153),
(156039, 'esMX', '', '¿Bien? Te escucho.', 28153),
(156038, 'esMX', '', 'Cuida tus modales en presencia de la reina.', 28153),
(156037, 'esMX', 'Me alegra ver que las arenas aún no te han devorado.', '', 28153),
(156036, 'esMX', '', 'La montaña nos presta su fuerza.', 28153),
(156035, 'esMX', '', 'Te diriges a la reina regente del clan Hierro Negro.', 28153),
(156034, 'esMX', '', 'El clan Hierro Negro tendrá el respeto que se merece.', 28153),
(156033, 'esMX', '', 'La Alianza necesita nuestra hechicería, y también nuestra fuerza.', 28153),
(156032, 'esMX', 'Vistiendo', 'Vistiendo', 28153),
(156031, 'esMX', 'Despejando', 'Despejando', 28153),
(156030, 'esMX', '', 'Excelente trabajo. Esto\' recursos serán de gran ayuda para los zandalari.', 28153),
(156029, 'esMX', '', 'Impresionante. Pronto todo\' sabrán que no deben meterse con el Imperio zandalari.', 28153),
(156028, 'esMX', '', 'Otra victoria para $uel campeón:la campeona; de la Horda. Puedo acoh\'tumbrarme a que seamos aliados.', 28153),
(156027, 'esMX', '', 'Los zandalari agradecemo\' tus esfuerzo\'.', 28153),
(156026, 'esMX', '', 'Nathanos no cree que podamo\' apoderarnos de eh\'ta área. Demuéh\'trale que se equivoca.', 28153),
(156025, 'esMX', '', 'Debes deh\'pejar el área que te rodea para que nueh\'tra campaña pueda continuar. Ya sabes qué hacer.', 28153),
(156024, 'esMX', '', 'Debemos asegurar eh\'ta área para nueh\'tros aliados. No tengas piedad con lo\' que quieran detenerte.', 28153),
(156023, 'esMX', '', 'Hay recursos en las cercanías que podrían ser útiles para nueh\'tra campaña. Recupéralos para nosotro\'.', 28153),
(156022, 'esMX', 'Dot y Dolly devorarán esto al instante.', '', 28153),
(156021, 'esMX', 'Dot y Dolly son unas bestias caprichosas. No trabajarán con el estómago vacío. Ayuda a encontrar algo para alimentarlas.', '', 28153),
(156020, 'esMX', '¡Fuera!', '¡Fuera!', 28153),
(156019, 'esMX', '¡Vete!', '¡Vete!', 28153),
(156018, 'esMX', '¡No me toques!', '¡No me toques!', 28153),
(156017, 'esMX', '¡Si te acercas, te golpearé la cabeza con una roca!', '¡Si te acercas, te golpearé la cabeza con una roca!', 28153),
(156016, 'esMX', '¡Vete o te mataré!', '¡Vete o te mataré!', 28153),
(156015, 'esMX', '', 'Ve. Consigue lo que se necesita para sanar a eh\'te hombre serpiente. Le contaré a Julwaba lo que sabemo\'.', 28153),
(156014, 'esMX', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Nueva construcción disponible!', 28153),
(156013, 'esMX', 'He servido a muchos jefes de guerra. Deberías recorrer un poco el mundo. Seguramente te encontrarás con algunos.', '', 28153),
(156012, 'esMX', '¿Por qué sigues molestándome? ¿Hay otra guerra que pelear? Pero qué digo... SIEMPRE hay otra guerra que pelear.', '', 28153),
(156011, 'esMX', '¡Si supieras cuánta sangre ha manchado mi hacha, no me molestarías tanto!', '', 28153),
(156010, 'esMX', 'Estoy muy viejo para estas tonterías.', '', 28153),
(156009, 'esMX', 'Sirvo a la Horda.', '', 28153),
(156008, 'esMX', 'Habla rápido... y solo con la verdad.', '', 28153),
(156007, 'esMX', 'No hay tiempo para cumplidos.', '', 28153),
(156006, 'esMX', '¿Qué quieres de mí?', '', 28153),
(156005, 'esMX', '¡Throm-ka!', '', 28153),
(156004, 'esMX', '¡Lok-tar!', '', 28153),
(156003, 'esMX', 'Soy Colmillosauro, hermano de Broxigar.', '', 28153),
(156002, 'esMX', 'La Horda resistirá.', '', 28153),
(156001, 'esMX', 'Esto ya no me gusta. ¡Me largo!', 'Esto ya no me gusta. ¡Me largo!', 28153),
(156000, 'esMX', 'En la batalla, la estrategia es tan fundamental como la fuerza.', '', 28153),
(155999, 'esMX', '¡Hurra! ¡Libertad!', '¡Hurra! ¡Libertad!', 28153),
(155998, 'esMX', '¡Me voy de aquí!', '¡Me voy de aquí!', 28153),
(155997, 'esMX', 'Somos la verdadera fuerza de Kalimdor.', '', 28153),
(155996, 'esMX', '¿Por qué sucede esto?', '¿Por qué sucede esto?', 28153),
(155995, 'esMX', '¡No voy a morir! ¡Cuídame la espalda!', '¡No voy a morir! ¡Cuídame la espalda!', 28153),
(155994, 'esMX', '¡¿Qué sucede?!', '¡¿Qué sucede?!', 28153),
(155993, 'esMX', 'Cuidado, ¡hay humanos locos por todos lados!', 'Cuidado, ¡hay humanos locos por todos lados!', 28153),
(155992, 'esMX', 'No envejezcas... si puedes.', '', 28153),
(155991, 'esMX', 'Sin honor, no somos nada.', '', 28153),
(155990, 'esMX', 'Morir hoy, en el campo de batalla, es morir como un auténtico orco.', '', 28153),
(155989, 'esMX', 'Que caigas en combate ante un enemigo odiado.', '', 28153),
(155988, 'esMX', 'Intenta guiar a Loh a salvo hacia las algas.', '', 28153),
(155987, 'esMX', '\"Loh y el Mar\". Un joven tortollano debe encontrar un lugar seguro tras surgir de las arenas.', '', 28153),
(155986, 'esMX', '', 'Has ahuyentado a las fuerzas de las brujas y nuestros trabajadores pueden regresar. Gracias por mantenerlos a salvo.', 28153),
(155985, 'esMX', 'Solo voy a limpiarme esto aquí...', '', 28153),
(155984, 'esMX', '', 'Las brujas han enviado a sus esbirros a apoderarse de nuestra leña. ¡Reúne a los leñadores y quemen a las brujas!', 28153),
(155983, 'esMX', '', 'Hondonada Fletcher está a salvo de la influencia del aquelarre una vez más. Gracias.', 28153),
(155982, 'esMX', '', '¡El aquelarre ha invadido Hondonada Fletcher! ¡Libera a sus ciudadanos y recupera el pueblo!', 28153),
(155981, 'esMX', 'Psssst... ¡por aquí, $n!', '', 28153),
(155980, 'esMX', '', 'Debemos defender lo que es justo.', 28153),
(155979, 'esMX', '', 'Cuando llegue el momento, allí estaré.', 28153),
(155978, 'esMX', '', 'Cumple tu deber.', 28153),
(155977, 'esMX', '', 'Debemos ayudar a los indefensos.', 28153),
(155976, 'esMX', '', 'Sin honor, no somos nada.', 28153),
(155975, 'esMX', '', 'Si le cuenta a UNA sola persona, te daré de alimento a mi grifo. ¡¿Entendido?!', 28153),
(155974, 'esMX', '', 'Pelearé hasta el amargo final.', 28153),
(155973, 'esMX', '', '<risotada> Oh, no... Espero que no hayas oído eso..', 28153),
(155972, 'esMX', '', 'Soy... ja, una escudera... muy disciplinada... ja, ja ... con voluntad de hierro...', 28153),
(155971, 'esMX', '', '¡Ey, me hace cosquillas! ¡Ya basta!', 28153),
(155970, 'esMX', '', '¡Ey! ¡Ya basta!', 28153),
(155969, 'esMX', '', 'Podemos lograrlo.', 28153),
(155968, 'esMX', '', 'Sirve con honor.', 28153),
(155967, 'esMX', '', 'Mantén el rumbo.', 28153),
(155966, 'esMX', '', 'Que los vientos estén a su favor, amigos míos. Mi lucha está aquí, junto a los vulperas.', 28153),
(155965, 'esMX', '', '¡Vuelve con historias para contar!', 28153),
(155964, 'esMX', '', '¡Por Kul Tiras!', 28153),
(155963, 'esMX', '', 'El deber llama.', 28153),
(155962, 'esMX', '', 'Adiós.', 28153),
(155961, 'esMX', '', '¿Cuál es la situación?', 28153),
(155960, 'esMX', '', '¡Al fin un poco de acción!', 28153),
(155959, 'esMX', '', 'He entrenado toda mi vida para esto.', 28153),
(155956, 'esMX', '', 'Juntos podemos unificar Kul Tiras.', 28153),
(155955, 'esMX', '', 'Siempre soñé con tener aventuras.', 28153),
(155953, 'esMX', 'El valle siempre es tu hogar.', '', 28153),
(155952, 'esMX', 'Yo te cuido si tú me cuidas.', '', 28153),
(155950, 'esMX', 'Cuídate allí afuera.', '', 28153),
(155947, 'esMX', 'Estamos juntos en esto.', '', 28153),
(155946, 'esMX', '', 'Actualización. Estallido de reoriginación cerca de máximo poder.', 28153),
(155945, 'esMX', '', 'Atención. Estallido de reoriginación cerca de capacidad máxima.', 28153),
(155944, 'esMX', '', 'Atención. Máximo poder inminente.', 28153),
(155943, 'esMX', '', 'Actualización. Nivel de poder casi al máximo.', 28153),
(155942, 'esMX', 'Nada que un día de trabajo duro no arregle.', '', 28153),
(155941, 'esMX', 'Mi corazón le pertenece a este valle.', '', 28153),
(155939, 'esMX', '', '¿En qué puedo ayudarte?', 28153),
(155938, 'esMX', '¿Oyes eso? Las profundidades me susurran algo. Es... ¡es sobre ti! ¿Cómo? Ajá. Ya veo. Dicen: \"Deja de hacer clic en Pike, maldito monstruo\". ¡Increíble!', '', 28153),
(155937, 'esMX', '¡Oh, son muy útiles para diferentes cosas!$b$bAdemás de su uso evidente como elementos de perforación, las púas poseen muchas propiedades. Al molerlas en un polvo fino, actúan como agente aglutinante. También puedes hervirlas y usar el aceite como detergente, ¡y si hace falta sirven de mondadientes!', '', 28153),
(155936, 'esMX', '¡Tendré que matarte yo mih\'mo junto con el reh\'to de tus amigo\' idiota\'!', '', 28153),
(155935, 'esMX', '¿Tongo... murió a manos de $Uun forah\'tero:una forah\'tera;? ¡Creo que lo sobreh\'timé!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'esMX', 'Así no... no... argghh....', '', 28153),
(155933, 'esMX', 'Juré mantener la paz en estas tierras. Por ti, estoy dispuesto a hacer una excepción.', '', 28153),
(155932, 'esMX', 'Sigue todo lo que quieras. La paciencia de un maresabio es legendaria.', '', 28153),
(155931, 'esMX', '', '¡Un gusto!', 28153),
(155930, 'esMX', '¿Para qué sirven estas púas?', '¿Para qué sirven estas púas?', 28153),
(155929, 'esMX', 'Ofreciendo', 'Ofreciendo', 28153),
(155928, 'esMX', 'Parece que bebiste demasiado. ¿Y no me invitaste? Estoy ofendido.', '', 28153),
(155927, 'esMX', 'Calma, camarada. Sé que soy muy atractivo, pero tenemos trabajo que hacer.', '', 28153),
(155926, 'esMX', 'Bueno, a menos que te hayan obligado a servir en la marina... O que te hayan capturado los piratas... y DESPUÉS te haya capturado la marina...', '', 28153),
(155925, 'esMX', 'Ah, el mar abierto. Una canción en los labios. El viento que agita suavemente el pelo del pecho. ESO es libertad.', '', 28153),
(155924, 'esMX', 'No mires atrás.', '', 28153),
(155923, 'esMX', 'Ojos en el horizonte.', '', 28153),
(155922, 'esMX', 'Yo invito la próxima ronda.', '', 28153),
(155921, 'esMX', 'Hora de cobrar.', '', 28153),
(155920, 'esMX', 'Nos vemos.', '', 28153),
(155919, 'esMX', '<La respiración del rey Rastakhan es difícil y entrecortada. Las vendas que le cruzan el pecho están cubiertas de sangre.>', '', 28153),
(155918, 'esMX', 'Cuídate la espalda allí afuera.', '', 28153),
(155917, 'esMX', 'Que tu pólvora nunca se moje.', '', 28153),
(155916, 'esMX', '¿Cuál es tu historia?', '', 28153),
(155915, 'esMX', '¡Excelente! Comenzaré a preparar lo que necesitamos de inmediato. Estoy seguro de que los pescadores locales también estarán agradecidos de que haya menos aves.', '', 28153),
(155914, 'esMX', 'Soy Jamil Abul\'housin, el médico real del rey. Eh\'ta no es la primera vez que trato al rey por sus herida\', y si es la voluntad de los loa, no será la última.', '', 28153),
(155913, 'esMX', 'Necesito componentes de pescados y cangrejos de la zona. Por desgracia, las gaviotas los encuentran apetitosos. ¡Consigue los suministros que necesito y deshazte de algunas aves!', '', 28153),
(155912, 'esMX', '¿Qué tal van las curaciones?', '¿Qué tal van las curaciones?', 28153),
(155911, 'esMX', '¡Sí... sí! ¡Esta tierra temblará ante el poder de la Horda!', '', 28153),
(155910, 'esMX', 'Hemos pasado por muchas cosa\' juntos, el viejo Rastakhan y yo. Pero eh\'to...\n\n<Jamil hace un gesto para señalar la figura maltrecha del rey.>\n\nEh\'to no es nada bueno.', '', 28153),
(155909, 'esMX', '<Jol no levanta la mirada de sus brebajes.>\n\nAl rey le queda poco tiempo.', '', 28153),
(155908, 'esMX', 'Trabajo es trabajo.', '', 28153),
(155907, 'esMX', 'Con eso basta. Pero es una pena que esa amenaza no pudiera convertirse en un arma contra nuestros enemigos.', '', 28153),
(155906, 'esMX', 'Hay un enemigo poderoso cerca que es un tanto... problemático para nuestras fuerzas. Supongo que ya sabes qué hacer.', '', 28153),
(155905, 'esMX', 'La jefa de guerra estará complacida con tu éxito.', '', 28153),
(155904, 'esMX', 'Un enemigo peligroso acecha en las cercanías. Elimínalo antes de que altere nuestros planes.', '', 28153),
(155903, 'esMX', 'Las fuerzas enemigas del área se interponen en nuestros planes. la jefa de guerra espera que te encargues del problema. No la decepciones.', '', 28153),
(155902, 'esMX', '¡¿Cómo pudo Rhenik permitir que esto sucediera?!', '¡¿Cómo pudo Rhenik permitir que esto sucediera?!', 28153),
(155901, 'esMX', '¡No otra vez!', '¡No otra vez!', 28153),
(155900, 'esMX', '¡Alguien va a pagar por eso!', '¡Alguien va a pagar por eso!', 28153),
(155899, 'esMX', '¡¿Por qué siempre destruyen el grog?!', '¡¿Por qué siempre destruyen el grog?!', 28153),
(155898, 'esMX', '¡El grog no!', '¡El grog no!', 28153),
(155897, 'esMX', 'Sangre u oro; todo tiene un precio.', '', 28153),
(155896, 'esMX', 'No se supone que la historia transcurra de esa forma. ¿Por qué no vuelves a intentarlo?', '', 28153),
(155895, 'esMX', '¿Tienes sed? Yo sí.', '', 28153),
(155894, 'esMX', 'Soy todo oídos.', '', 28153),
(155893, 'esMX', '¿Qué dicen en las calles?', '', 28153),
(155892, 'esMX', 'Ah, del barco.', '', 28153),
(155891, 'esMX', 'Ten cuidado allí afuera.', '', 28153),
(155890, 'esMX', 'Hasta la próxima.', '', 28153),
(155889, 'esMX', '¡Salud!', '', 28153),
(155888, 'esMX', '¿Grog o cerveza? ¿O los dos?', '', 28153),
(155887, 'esMX', '¿Qué necesitas?', '', 28153),
(155886, 'esMX', '¡Bien hecho, $n!', '', 28153),
(155885, 'esMX', '¿En qué puedo ayudarte?', '', 28153),
(155884, 'esMX', '¿Puedes mostrarle a Loh toda la comida de la isla y después llevarlo a su choza sin volver a pasar por el camino que ha tomado?', '', 28153),
(155883, 'esMX', '\"La vida simple\". Un día, Loh decidió llevar una vida tranquila en una isla remota.', '', 28153),
(155882, 'esMX', '¿Sabes cómo llamábamos a los cadetes como tú en la Segunda Guerra? Percebes... ¡porque te quedas pegado a mí!', '', 28153),
(155881, 'esMX', 'Muy a menudo, Loh encontraba grandes peligros en sus viajes. En esta historia, por ejemplo...', '', 28153),
(155880, 'esMX', 'A los tortollanos nos encanta la historia de Loh, un joven tortollano que recorrió el mundo.', '', 28153),
(155879, 'esMX', '¿Qué quieres, una historia de guerra?', '', 28153),
(155878, 'esMX', 'En MI época, sabíamos cuándo era el fin de una conversación.', '', 28153),
(155877, 'esMX', '', 'El ciclo de la vida puede ser cruel...', 28153),
(155876, 'esMX', '', '¡Una tortuga llegó al agua!', 28153),
(155875, 'esMX', '', '¡Gracias, $n!', 28153),
(155874, 'esMX', '', 'Un tortollano comienza su vida en medio de un gran peligro, como estas tortugas en la playa. ¡Defiéndelas mientras intentan llegar a salvo al océano!', 28153),
(155873, 'esMX', '', '¡Buen trabajo! No es la finalidad de una máquina como esa, pero resultó efectiva de todos modos.', 28153),
(155872, 'esMX', '', 'Si no llevan una identificación... ¡Mátalos!', 28153),
(155871, 'esMX', '', '¿Quién fue el idiota que perdió varias cajas con bombas?', 28153),
(155870, 'esMX', '', 'Los hombres que están en Alto de Arom lograron hacer funcionar la máquina de minería. ¡Úsala contra sus propios creadores de la Horda!', 28153),
(155869, 'esMX', '', '¡Puedo compensar las pérdidas si te elimino de la nómina!', 28153),
(155868, 'esMX', '', 'Tal vez deba hacer unos recortes para balancear el presupuesto.', 28153),
(155867, 'esMX', '¡Invasores en la Fundición! Repito, INVA...', '¡Invasores en la Fundición! Repito, INVA...', 28153),
(155866, 'esMX', 'Que te guíe el honor.', '', 28153),
(155865, 'esMX', 'Por la Lady almirante.', '', 28153),
(155864, 'esMX', 'Por Kul Tiras.', '', 28153),
(155863, 'esMX', '¡Que nunca te vean en aprietos!', '', 28153),
(155862, 'esMX', 'Permanece alerta.', '', 28153),
(155861, 'esMX', 'Vientos favorables y mares calmos.', '', 28153),
(155860, 'esMX', '¡Retírate!', '', 28153),
(155859, 'esMX', '', '', 28153),
(155858, 'esMX', '', '', 28153),
(155857, 'esMX', '¡Vamos, habla!', '', 28153),
(155856, 'esMX', '', '', 28153),
(155855, 'esMX', 'He visto suficientes guerras por los dos.', '', 28153),
(155854, 'esMX', '¿Noticias del frente?', '', 28153),
(155853, 'esMX', '¿Qué necesitas?', '', 28153),
(155852, 'esMX', 'Estos viejos huesos todavía quieren pelear.', '', 28153),
(155851, 'esMX', '¿Alguna novedad?', '', 28153),
(155850, 'esMX', '¡Un gusto!', '', 28153),
(155849, 'esMX', '', 'No pidas favores.', 28153),
(155848, 'esMX', '', 'El viento y el mar nos guían a la libertad.', 28153),
(155847, 'esMX', '', 'Kul Tiras resistirá cualquier tormenta.', 28153),
(155846, 'esMX', '', 'Tienes mi atención.', 28153),
(155845, 'esMX', '', 'Presenta tus términos.', 28153),
(155844, 'esMX', 'Debemos continuar.', '', 28153),
(155843, 'esMX', 'No temas el devenir de la marea.', '', 28153),
(155842, 'esMX', 'Que las corrientes te guíen.', '', 28153),
(155841, 'esMX', 'No olvides a los caídos.', '', 28153),
(155840, 'esMX', 'No saques la vista del mar.', '', 28153),
(155839, 'esMX', '', 'No tengo tiempo para parlotear.', 28153),
(155838, 'esMX', 'La tormenta despierta en todos nosotros.', '', 28153),
(155837, 'esMX', 'Estoy aquí para batirme a duelo.', 'Estoy aquí para batirme a duelo.', 28153),
(155836, 'esMX', 'Mmm, no. Inténtalo de nuevo.', '', 28153),
(155835, 'esMX', '¡Ohh, una coincidencia!', '', 28153),
(155834, 'esMX', '¡Bien hecho, $n!', '', 28153),
(155833, 'esMX', 'He coleccionado muchas cosas con el paso de los años. Intenta combinarlas.', '', 28153),
(155832, 'esMX', 'Claro... si te gusta correr. Si quieres volar, visita a Pa\'ku, loa de los viento\'. Tiene menos tótems pero puede\' volar de uno a otro por toda la ciuda\'.', '', 28153),
(155831, 'esMX', '', 'Gonk, maestro de formas y señor de la cacería, es un loa poderoso. Puede darte acceso a sus innumerable\' tótems, que están por toda la ciudad y aumentarán tu velocidad con solo acercarte a ellos.', 28153),
(155830, 'esMX', 'Las profundidades anunciaron tu llegada.', '', 28153),
(155829, 'esMX', 'Te escucho.', '', 28153),
(155828, 'esMX', '¿Me necesitas?', '', 28153),
(155827, 'esMX', 'Que las mareas te bendigan.', '', 28153),
(155826, 'esMX', 'Suban esas tablas, partiremos de inmediato. Lo último que necesito es que le hagan agujeros a mi nave.', '', 28153),
(155825, 'esMX', 'Veo que también buscan azerita. Son astutos, pero les falta rapidez para vencernos. Pongámonos en marcha antes de que llamemos su atención.', '', 28153),
(155824, 'esMX', 'Eso es todo. Parece que la isla está despejada y justo a tiempo. Se acerca una nave zandalari.', '', 28153),
(155823, 'esMX', 'Y también han estado recogiendo azerita. Qué conveniente. Mátenlos y róbenles sus cosas.', '', 28153),
(155822, 'esMX', '¿Hozen? ¿Aquí? Ja, supongo que nunca sabes con qué te puedes encontrar en estas islas.', '', 28153),
(155821, 'esMX', 'Acabamos de ver una gran acumulación de azerita cerca. Esto se pondrá bueno.', '', 28153),
(155820, 'esMX', 'Excelente. Un poco sangriento y asqueroso, ¿pero qué podemos hacer? La azerita es azerita.', '', 28153),
(155819, 'esMX', 'Vaya, ese monstruo es enorme y está completamente cubierto de residuos de azerita. Mátenlo y nosotros extraeremos la azerita.', '', 28153),
(155818, 'esMX', 'Muy bien, el detector indica que hay otra fuente de azerita cerca de su posición. Echen un vistazo.', '', 28153),
(155817, 'esMX', '¡Iujuu! Es un gran botín. ¡Buen trabajo!', '', 28153),
(155816, 'esMX', 'Guau, eso es un gran filón de azerita. Extraigan toda la que puedan y llevaremos los fragmentos al barco de inmediato.', '', 28153),
(155815, 'esMX', 'Nuestro detector de azerita muestra una fuente de... bueno, azerita cerca. ¿Por qué no van a investigar? Yo, eh, me quedaré por aquí.', '', 28153),
(155814, 'esMX', 'Acércala e intenta no golpear nada. No olvides bajar las rampas de desembarco. Gracias.', '', 28153),
(155813, 'esMX', 'Claro que también puede haber arañas gigantes o cosas así. Nunca se sabe con qué te encontrarás.', '', 28153),
(155812, 'esMX', 'Estoy casi seguro de que este es el lugar. Se supone que debería haber mucha azerita por aquí.', '', 28153),
(155811, 'esMX', '¡$n! ¡Gracias a la Dama Oscura que estás aquí! Rexxar desvió a varios kultiranos hacia aquellas edificaciones que están más adelante. ¡Necesita ayuda!', '¡$n! ¡Gracias a la Dama Oscura que estás aquí! Rexxar desvió a varios kultiranos hacia aquellas edificaciones que están más adelante. ¡Necesita ayuda!', 28153),
(155810, 'esMX', 'Deprisa, ¡ve bajo cubierta y toma un arma! ¡Nuestras tropas nos necesitan!', '', 28153),
(155809, 'esMX', 'Ahí están los restos de Vadekius. Era un dragón poderoso.', 'Ahí están los restos de Vadekius. Era un dragón poderoso.', 28153),
(155808, 'esMX', 'No te hagas ilusiones.', 'No te hagas ilusiones.', 28153),
(155807, 'esMX', 'Para matarlo se habría necesitado algo sumamente poderoso y oscuro.', 'Para matarlo se habría necesitado algo sumamente poderoso y oscuro.', 28153),
(155806, 'esMX', 'Ahí están los restos de Vadekius. Era un dragón poderoso.', 'Ahí están los restos de Vadekius. Era un dragón poderoso.', 28153),
(155805, 'esMX', 'Pero esto es un comienzo.', 'Pero esto es un comienzo.', 28153),
(155804, 'esMX', 'Mi corazón no es tan grande como el de mi Reina.', 'Mi corazón no es tan grande como el de mi Reina.', 28153),
(155803, 'esMX', 'No puedo perdonar tan fácilmente lo que le hiciste a Kyranastrasz.', 'No puedo perdonar tan fácilmente lo que le hiciste a Kyranastrasz.', 28153),
(155802, 'esMX', 'Gracias, supongo.', 'Gracias, supongo.', 28153),
(155801, 'esMX', 'Gracias por tu ayuda, $n.', 'Gracias por tu ayuda, $n.', 28153),
(155800, 'esMX', 'No queremos que esos eventos terribles se repitan.', 'No queremos que esos eventos terribles se repitan.', 28153),
(155799, 'esMX', 'Para encontrar su lugar de reposo, $Uel Señor de la muerte:la Señora de la muerte; invadió nuestro Sagrario Rubí.', 'Para encontrar su lugar de reposo, $Uel Señor de la muerte:la Señora de la muerte; invadió nuestro Sagrario Rubí.', 28153),
(155798, 'esMX', 'Durante la última guerra con la Legión, uno de los nuestros revivió como una criatura no-muerta.', 'Durante la última guerra con la Legión, uno de los nuestros revivió como una criatura no-muerta.', 28153),
(155797, 'esMX', 'Entonces $n y yo nos encargaremos de esta tarea. Vamos, $c, te llevaré al lugar del ritual.', 'Entonces $n y yo nos encargaremos de esta tarea. Vamos, $c, te llevaré al lugar del ritual.', 28153),
(155796, 'esMX', '', '$n ha regresado de su tarea. Quizá pueda ayudarte, Zallestrasza.', 28153),
(155795, 'esMX', 'Están haciendo demasiado escándalo. Me siento mucho mejor.', 'Están haciendo demasiado escándalo. Me siento mucho mejor.', 28153),
(155794, 'esMX', 'Quédate quieto mientras ayudo con la sanación.', 'Quédate quieto mientras ayudo con la sanación.', 28153),
(155793, 'esMX', '¡Apenas si te puedes incorporar, Theo!', '¡Apenas si te puedes incorporar, Theo!', 28153),
(155792, 'esMX', '', '¡Bien hecho, $n! Ahora, pasemos a mi oficina nueva.', 28153),
(155791, 'esMX', '', 'Esos los maté yo. ¡Estoy llevando la cuenta!', 28153),
(155790, 'esMX', 'Necesitaré de un poder increíble para enfrentar a Korthek en batalla. Siempre fue el mejor guerrero de los dos.\n\nExtraeré todo lo que pueda de estos cristales y recemos por que sea suficiente.', '', 28153),
(155789, 'esMX', '', 'Has reducido la plaga de arañas a niveles seguros. Los aldeanos pueden adentrarse en el bosque sin temor a quedar atrapados en una telaraña.', 28153),
(155788, 'esMX', '', 'Unas arañas peligrosas han infestado el bosque y amenazan a los cazadores de Drustvar. ¡Quémalas!', 28153),
(155787, 'esMX', 'Cambiando', 'Cambiando', 28153),
(155786, 'esMX', '', 'Buen trabajo. Estos suministro\' ayudarán a nuestras fuerzas a resistir el clima local.', 28153),
(155785, 'esMX', '', 'Nueh\'tros exploradores informan que esos humanos han desarrollado un método para obtener piel animal sin lastimar a las criatura\'. Es extraño... pero efectivo.', 28153),
(155784, 'esMX', 'Algo perturbador deambula por el aserradero. Está muy cerca de Boralus. No me gusta.', '', 28153),
(155783, 'esMX', '¡Una muerte impecable! El monstruo tenía los días contados en cuanto pisó las costas kultiranas.', '', 28153),
(155782, 'esMX', 'Los Firmemares han pescado algo grande. Les vendría bien tu ayuda.', '', 28153),
(155781, 'esMX', 'Ardiendo', 'Ardiendo', 28153),
(155780, 'esMX', 'Estamos juntos en esto. ¡No voy a retirarme!', 'Estamos $ujuntos:juntas; en esto. ¡No voy a retirarme!', 28153),
(155779, 'esMX', 'Si muero hoy... ¡lo haré peleando!', 'Si muero hoy... ¡lo haré peleando!', 28153),
(155778, 'esMX', '¡Mojambo nunca me llevará con vida!', '¡Mojambo nunca me llevará con vida!', 28153),
(155777, 'esMX', '¡Me niego a humillarme frente a Mojambo y su pandilla!', '¡Me niego a humillarme frente a Mojambo y su pandilla!', 28153),
(155776, 'esMX', '¡Pelearé hasta mi último aliento!', '¡Pelearé hasta mi último aliento!', 28153),
(155775, 'esMX', '¡No nos rendiremos ante Mojambo sin pelear!', '¡No nos rendiremos ante Mojambo sin pelear!', 28153),
(155774, 'esMX', 'La batalla se acerca. Toma esta espada y mantente alerta.', 'La batalla se acerca. Toma esta espada y mantente alerta.', 28153),
(155773, 'esMX', 'Este es nuestro hogar. No nos iremos sin dar pelea.', 'Este es nuestro hogar. No nos iremos sin dar pelea.', 28153),
(155772, 'esMX', '', '¡Buen trabajo! Un dolor de cabeza menos para los marinos.', 28153),
(155771, 'esMX', '', '¡Vaya muerte! Creo que puedo aprender mucho observándote pelear.', 28153),
(155770, 'esMX', '', 'Los caminos de Kul Tiras son más seguros gracias ti.', 28153),
(155769, 'esMX', '', 'El ejército ya ha tenido que lidiar con una bestia aquí. ¡Solucionemos su problema!', 28153),
(155768, 'esMX', '', 'Hay una bestia feroz en el área. Por el bien de Kul Tiras, ¡no podemos ignorar esta amenaza!', 28153),
(155767, 'esMX', '', 'Debemos impedir que esa abominación siga causando estragos entre los civiles. ¡Extermínala!', 28153),
(155766, 'esMX', '¿No tienes que estar en alguna otra parte?', '¿No tienes que estar en alguna otra parte?', 28153),
(155765, 'esMX', 'Ey, ¡no me gusta cómo me mira $ueste:esta;!', 'Ey, ¡no me gusta cómo me mira $ueste:esta;!', 28153),
(155764, 'esMX', '¡Estás muy lejos de casa, $uamigo:amiga;!', '¡Estás muy lejos de casa, $uamigo:amiga;!', 28153),
(155763, 'esMX', 'Cielo rojo al atardecer, buen tiempo has de tener. Cielo rojo a la alborada, cuidado que el marinero se enfada.', '', 28153),
(155762, 'esMX', 'Quiero teletransportarme hasta G\'huun.', 'Quiero teletransportarme hasta G\'huun.', 28153),
(155761, 'esMX', 'Quiero teletransportarme hasta Mythrax.', 'Quiero teletransportarme hasta Mythrax.', 28153),
(155760, 'esMX', 'Quiero teletransportarme hasta Zul.', 'Quiero teletransportarme hasta Zul.', 28153),
(155759, 'esMX', 'Quiero teletransportarme hasta el Elemental de sangre.', 'Quiero teletransportarme hasta el Elemental de sangre.', 28153),
(155758, 'esMX', 'Quiero teletransportarme hasta Zek\'voz.', 'Quiero teletransportarme hasta Zek\'voz.', 28153),
(155757, 'esMX', 'Quiero teletransportarme hasta el Devorador fétido.', 'Quiero teletransportarme hasta el Devorador fétido.', 28153),
(155756, 'esMX', 'Quiero teletransportarme hasta MADRE.', 'Quiero teletransportarme hasta MADRE.', 28153),
(155755, 'esMX', '¡Saludos, y gracias por ayudar a probar Uldir!\n\nPuedo teletransportarte directamente hasta cualquier jefe que esté disponible en este momento para realizar pruebas.', '¡Saludos, y gracias por ayudar a probar Uldir!\n\nPuedo teletransportarte directamente hasta cualquier jefe que esté disponible en este momento para realizar pruebas.', 28153),
(155754, 'esMX', '', 'He perdido a mi gato.', 28153),
(155753, 'esMX', '¡Sobrevive a la tormenta inevitable, y evita la tormenta despiadada!', '', 28153),
(155752, 'esMX', 'Recuerda, ¡el lado húmedo va a hacia abajo!', '', 28153),
(155750, 'esMX', '¿Quiereh\' conocer a Bwonsamdi?', '', 28153),
(155749, 'esMX', 'Oh. Vivir en tierra debe ser muy aburrido para ti.', '', 28153),
(155748, 'esMX', '¡Cuando contemples la Bahía de Reyes y veas las llamas azules benditas, recuerda que hoy cambiah\'te el curso de la marea! Es una victoria digna, $n. ¡La flota pertenece a Zandalar, para siempre!', '', 28153),
(155747, 'esMX', 'No dudaré en pasarte por la quilla.', '', 28153),
(155746, 'esMX', '¡Que el viento infle tus vela\' y tu alma encuentre propósito!', '', 28153),
(155745, 'esMX', '¡Nos vemo\'!', '', 28153),
(155744, 'esMX', '¡Cuídate! ¡El mar me llama!', '', 28153),
(155743, 'esMX', 'Si las aguas eh\'tán tranquila\', no has aprendido nada.', '', 28153),
(155742, 'esMX', '¡Vientos favorable\' y mares calmo\' para ti!', '', 28153),
(155741, 'esMX', '¡Que las mareas vuelvan a juntarnos!', '', 28153),
(155740, 'esMX', '¡Que el viento te acompañe hacia nuevos horizonte\'!', '', 28153),
(155739, 'esMX', '¿Sientes la sal del aire? Eh\'te es tu hogar.', '', 28153),
(155738, 'esMX', '¡Taz\'okun! ¡Te doy la bienvenida, itinerante!', '', 28153),
(155737, 'esMX', 'El trabajo está hecho... pero podrías haber dejado un rastro de sangre menos anémico a tu paso. Hazlo mejor la próxima vez.', '', 28153),
(155736, 'esMX', '¡Ey! ¡Eres tú!', '', 28153),
(155735, 'esMX', 'La jefa de guerra ha ordenado que te apoderes de esta área en nombre de la Horda. Usa los medios que creas apropiados... siempre que te garanticen la victoria.', '', 28153),
(155734, 'esMX', '¡Un día sin ver tierra e\' un buen día!', '', 28153),
(155733, 'esMX', '¿Todo lih\'to para el viaje épico?', '', 28153),
(155732, 'esMX', 'Quiero ir a Uldir (banda)', 'Quiero ir a Uldir (banda)', 28153),
(155731, 'esMX', '¡Bien hecho! Nuestras aves encontrarán un lugar más seguro donde anidar y ahora tenemos menos enemigos que enfrentar.', '', 28153),
(155730, 'esMX', '¡Aguardo ansiosamente tu regreso!', '', 28153),
(155729, 'esMX', '¡Regresa cuanto antes!', '', 28153),
(155728, 'esMX', '¡Apunten!', '¡Apunten!', 28153),
(155727, 'esMX', 'Ya veo, otra vez...', '', 28153),
(155726, 'esMX', 'Supongo que rompiste algo...', '', 28153),
(155725, 'esMX', '¿Puedo ayudarte?', '', 28153),
(155724, 'esMX', '¿Qué puedo hacer por ti?', '', 28153),
(155723, 'esMX', '¡¡¡Pónganse a cubierto!!!', '¡¡¡Pónganse a cubierto!!!', 28153),
(155722, 'esMX', 'Tienes suerte, me caes bien. Esta vez lo arreglaré... nuevamente...', '', 28153),
(155721, 'esMX', '¿En serio? ¿Esa cosita minúscula se rompió porque tenía mucho peso encima? Quién lo hubiera pensado, ¿verdad?', '', 28153),
(155720, 'esMX', 'A que no eres mucho más inteligente que mi martillo.', '', 28153),
(155719, 'esMX', 'Estoy seguro de que esta es la misma cosa que arreglé la última vez.', '', 28153),
(155718, 'esMX', 'Me encantaría que estos torpes dejaran de romper cosas.', '', 28153),
(155717, 'esMX', 'Quiero ir a la Mansión Tarjasenda (calabozo).', 'Quiero ir a la Mansión Tarjasenda (calabozo).', 28153),
(155716, 'esMX', 'Quiero ir a Tol Dagor (calabozo).', 'Quiero ir a Tol Dagor (calabozo).', 28153),
(155715, 'esMX', 'Quiero ir a Asedio de Boralos (calabozo).', 'Quiero ir a Asedio de Boralos (calabozo).', 28153),
(155714, 'esMX', 'Quiero ir al Santuario de la Tormenta (calabozo).', 'Quiero ir a Puerto Libre (calabozo).', 28153),
(155713, 'esMX', 'Quiero ir a Puerto Libre (calabozo).', 'Quiero ir a Puerto Libre (calabozo).', 28153),
(155712, 'esMX', '¡Por las plumas de Plumeria! ¡Me asustaste!', '', 28153),
(155711, 'esMX', '¡Los que fueron cautivados por las brujas se han robado nuestras aves! ¡Libera a los halcones y acaba con los esbirros de las brujas!', '', 28153),
(155710, 'esMX', '¿Necesitas un artilugio especial? ¿Un aparato? ¡Quizás un accesorio!', '', 28153),
(155709, 'esMX', 'Quiero ir a Bardoma (calabozo).', 'Quiero ir a Bardoma (calabozo).', 28153),
(155708, 'esMX', 'Quiero ir a EL FILÓN (calabozo).', 'Quiero ir a EL FILÓN (calabozo).', 28153),
(155707, 'esMX', 'Quiero ir al Templo de Sethraliss (calabozo).', 'Quiero ir al Templo de Sethraliss (calabozo).', 28153),
(155706, 'esMX', 'Quiero ir a Reposo de los Reyes (calabozo).', 'Quiero ir a Reposo de los Reyes (calabozo).', 28153),
(155705, 'esMX', '¡Los Firmemares están listos para lo que sea!', '', 28153),
(155704, 'esMX', 'Nuestros amigos emplumados están a salvo de la magia de las brujas una vez más.', '', 28153),
(155703, 'esMX', '¡Las brujas usan talismanes para maldecir a nuestras aves! ¡Elimina los talismanes y a todos los halconeros aojados que veas antes de que su influencia se propague!', '', 28153),
(155702, 'esMX', '', 'Lárgate.', 28153),
(155701, 'esMX', '', '¡Tengo un arma y no temo usarla!', 28153),
(155700, 'esMX', '', 'Ay, ya no puedo ni verte.', 28153),
(155699, 'esMX', '', 'Dame una bestia y mis Firmemares se encargarán de ella.', 28153),
(155698, 'esMX', '', 'Peludín, gato malo. ¡Ven aquí ahora mismo!', 28153),
(155697, 'esMX', '', '¡Ven, gatito, gatito!', 28153),
(155696, 'esMX', 'Quiero ir a Atal\'Dazar (calabozo).', 'Quiero ir a Atal\'Dazar (calabozo).', 28153),
(155695, 'esMX', '', 'Dime cuando te atrevas a jugar con los grandes.', 28153),
(155694, 'esMX', '', 'Tengo monstruos que matar.', 28153),
(155693, 'esMX', '', '¿Y ahora qué?', 28153),
(155692, 'esMX', 'Supongo que has cumplido con la misión. Bien. Le informaré a la jefa de guerra sobre tu éxito.', '', 28153),
(155691, 'esMX', '¡Saludos y gracias por ayudarnos a probar la beta de Battle for Azeroth! \n\nPuedo teletransportarte directamente a varios calabozos o bandas disponibles para probar. Esto funciona solo como un teletransporte y no como un servicio de buscador de partidas, así que espero que tengas un grupo listo para enfrentar los desafíos que esperan dentro. De no ser así, quizá te convenga probar la nueva función de Buscador de grupos para encontrar algunos aliados.\n\n¡Debes seleccionar la dificultad que quieres probar antes de teletransportarte, porque es probable que no puedas abandonar la zona fácilmente si quieres cambiar de dificultad!', '¡Saludos y gracias por ayudarnos a probar la beta de Battle for Azeroth! \n\nPuedo teletransportarte directamente a varios calabozos o bandas disponibles para probar. Esto funciona solo como un teletransporte y no como un servicio de buscador de partidas, así que espero que tengas un grupo listo para enfrentar los desafíos que esperan dentro. De no ser así, quizá te convenga probar la nueva función de Buscador de grupos para encontrar algunos aliados.\n\n¡Debes seleccionar la dificultad que quieres probar antes de teletransportarte, porque es probable que no puedas abandonar la zona fácilmente si quieres cambiar de dificultad!', 28153),
(155690, 'esMX', '¡$n (Horda) está marcado en tu mapa como |c00FFFF00|Hspell:272296|h[Asesino]|h|r! Mátalo y obtén una recompensa.', '¡$n (Horda) está marcado en tu mapa como |c00FFFF00|Hspell:272296|h[Asesino]|h|r! Mátalo y obtén una recompensa.', 28153),
(155689, 'esMX', '¡$n (Alianza) está marcado en tu mapa como |c00FFFF00|Hspell:272295|h[Asesino]|h|r! Mátalo y obtén una recompensa.', '¡$n (Alianza) está marcado en tu mapa como |c00FFFF00|Hspell:272295|h[Asesino]|h|r! Mátalo y obtén una recompensa.', 28153),
(155688, 'esMX', 'Hay que controlar las fuerzas enemigas en el área. Supongo que podrás encargarte de esta tarea.', '', 28153),
(155687, 'esMX', '', 'Jamás he visto un monstruo que no pudiera derrotar.', 28153),
(155686, 'esMX', 'Eso llevó más tiempo del que esperaba... pero los resultados son aceptables. Nuestra campaña continúa.', '', 28153),
(155685, 'esMX', 'La jefa de guerra quiere todos los recursos de esta área. Ve a buscar lo que nos pertenece.', '', 28153),
(155684, 'esMX', 'Todavía no te permito mencionar a mi hermana.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'esMX', '', '¡Les daremos un buen uso a estos recursos! Bien hecho.', 28153),
(155682, 'esMX', '', 'Peleas como tu hermana.', 28153),
(155681, 'esMX', '', 'Aquí hay recursos que le serían muy útiles a la Orden. ¡Controla el área y apodérate de ellos!', 28153),
(155680, 'esMX', 'Como desees, madre...', '', 28153),
(155679, 'esMX', '', 'Gatito, ¿dónde estás?', 28153),
(155678, 'esMX', '', 'Ven, Arthur.', 28153),
(155677, 'esMX', '', 'Ahora, Mariscal, sea un buen hombre. Deshágase de estas molestias y después traiga a Lucille a mis aposentos...', 28153),
(155676, 'esMX', '', '¿Has visto a mi gato?', 28153),
(155675, 'esMX', '', 'Ay, mariscal, esa no es forma de hablarle a una dama. Te enseñaré algunos modales.', 28153),
(155674, 'esMX', '', '¿Crees poder seguirme el paso?', 28153),
(155673, 'esMX', '¡Aléjate de ella, bruja desalmada!', '', 28153),
(155672, 'esMX', '', '¡No seas malagradecida! ¡Tu padre no solo está bien y con vida, sino que pronto será lord de todo Kul Tiras! Ven, acompáñanos, querida...', 28153),
(155671, 'esMX', '', 'Qué... ¡¿Qué le has hecho?!', 28153),
(155670, 'esMX', '', 'Me alegra tanto que nos acompañes, querida. Tu padre te ha extrañado tanto.', 28153),
(155669, 'esMX', '', '¿Madre? ¿Eres... tú?', 28153),
(155668, 'esMX', '', 'Es suficiente.', 28153),
(155667, 'esMX', 'Oí que tiene algo que ver con todos los cajones que hemos recibido de Aspafresno.', 'Oí que tiene algo que ver con todos los cajones que hemos recibido de Aspafresno.', 28153),
(155666, 'esMX', 'Algo tiene muy preocupada a la capitana Stone.', 'Algo tiene muy preocupada a la capitana Stone.', 28153),
(155665, 'esMX', 'Estoy feliz de que me hayan asignado este puesto hoy.', 'Estoy feliz de que me hayan asignado este puesto hoy.', 28153),
(155664, 'esMX', '¿Qué? ¿Es una BOMBA? Creí que era un aguacate.', '', 28153),
(155663, 'esMX', '', 'Ten cuidado, John. Esa pólvora podría volarte la cabeza.', 28153),
(155662, 'esMX', '¡Suban las tabla\'! ¡Nos marchamo\'! Hicieron un excelente trabajo.', '', 28153),
(155661, 'esMX', 'Parece que vienen por nueh\'tra azerita. Escapemos ante\' de que nos vean. Tenemo\' que informar sobre eh\'to.', '', 28153),
(155660, 'esMX', 'Eso es todo. Parece que hemo\' deh\'pejado esta isla, y justo a tiempo. Hay una nave kultirana en el horizonte.', '', 28153),
(155659, 'esMX', 'Parece que también eh\'tán recogiendo azerita. Eso nos sirve... ¡La tienen toda en un lugar, ja! Vayan y quítensela de las mano\'.', '', 28153),
(155658, 'esMX', '¡Hozen! ¡Ja! Uno nunca sabe con quién se cruzará en eh\'te lugar.', '', 28153),
(155657, 'esMX', 'Hemos vih\'to una acumulación de azerita cerca de ustede\'. Les recomiendo echen un vih\'tazo.', '', 28153),
(155656, 'esMX', 'Eso es. Llenaremo\' el casco en un abrir y cerrar de ojo\'.', '', 28153),
(155655, 'esMX', 'Ese monstruo es enorme y eh\'tá completamente cubierto de residuos de azerita. Mátenlo y le quitaremo\' la azerita.', '', 28153),
(155654, 'esMX', 'Parece que hay otra fuente de azerita cerca de uh\'tedes. Echen un vih\'tazo.', '', 28153),
(155653, 'esMX', 'Eso e\' lo que yo llamo un buen botín. Excelente trabajo.', '', 28153),
(155652, 'esMX', 'Ah, sí, un trozo enorme de azerita. Vayan a extraerlo. Tendremo\' la azerita en la nave en un instante.', '', 28153),
(155651, 'esMX', 'La máquina mueh\'tra algunas fuentes de azerita cerca. Vayan y echen un vistazo.', '', 28153),
(155650, 'esMX', 'Bajen las rampa\' de desembarco. Es aquí.', '', 28153),
(155649, 'esMX', 'No sabemo\' qué más encontraremo\' aquí. Tengan cuidado ahí afuera.', '', 28153),
(155648, 'esMX', 'Ya casi llegamo\'. Esta es la isla que, según nuestros exploradore\', está repleta de azerita.', '', 28153),
(155647, 'esMX', 'Por supuesto, capitana.', 'Por supuesto, capitana.', 28153),
(155646, 'esMX', '', '¡Bueno, súbanlos a la nave! Esos explosivos son un riesgo para la seguridad.', 28153),
(155645, 'esMX', 'S-sí, capitana Stone.', 'S-sí, capitana Stone.', 28153),
(155644, 'esMX', '', '¿Esos son cargamentos de pólvora de la Fundición Aspafresno?', 28153),
(155643, 'esMX', '¡Sangre y truenos! ¿Qué hechizo es este? ¡Han destruido nuestros barcos y han empujado a nuestras tropas hacia el mar!', '', 28153),
(155642, 'esMX', '¿Sabes? Un vendedor de tapones para los oídos se haría rico en Puerto Libre.', '', 28153),
(155641, 'esMX', '¿Oyes... oyes eso? ¡Alto! ¡No de nuevo! ¡Mátala, rápido!', '', 28153),
(155640, 'esMX', '¡Bien! Tal vez Puerto Libre sea un lugar más seguro ahora. Ah, ¿a quién engaño?', '', 28153),
(155639, 'esMX', '¡Ja! ¡Toma eso, pajarraco!', '', 28153),
(155638, 'esMX', '¡Excelente! Una deuda menos de qué preocuparme.', '', 28153),
(155637, 'esMX', '¿Qué huele a grog y usa un sombrero rojo? Un pirata. Un pirata nada amistoso.', '', 28153),
(155636, 'esMX', 'Unos amigos míos vieron a un prófugo de la ley cerca. ¡Quedémonos con la recompensa!', '', 28153),
(155635, 'esMX', 'Hay un forajido particularmente molesto en el área. Deberías exterminarlo.', '', 28153),
(155634, 'esMX', 'Oigan, son nuestros amigos de Ventura y Cía. Han venido a ayudarnos a llevarse nuestra azerita. Son tan amables. Seguramente les agraden, vayan a saludarlos.', '', 28153),
(155633, 'esMX', 'Ventura y Cía. ha iniciado operaciones en varias ubicaciones alrededor de la isla. Vayan a hacerles una visita y déjenlos fuera del mercado.', '', 28153),
(155632, 'esMX', 'Ventura y Cía. acaba de aparecer y quieren cambiar esta azerita por dinero al mejor estilo goblin.', '', 28153),
(155631, 'esMX', 'Hemos avistado algunos matones de Ventura y Cía. en la isla. Parece que nos espera una transacción hostil.', '', 28153),
(155630, 'esMX', 'Veo chalupas vrykul, y muchas. Parece que un clan decidió zarpar en busca de la azerita.', '', 28153),
(155629, 'esMX', 'Acaba de desembarcar un grupo enorme de vrykul. Deben venir por nuestro botín. No dejemos que se lo lleven, ¿de acuerdo?', '', 28153),
(155628, 'esMX', 'Acaba de llegar una flota vrykul. Un grupo enorme de guerreros muy amenazantes está montando campamento en toda la isla, o al menos eso veo desde atrás de este barril.', '', 28153),
(155627, 'esMX', 'Se acercan barcos vrykul. Parece ser un grupo de asalto. Estos tipos no se cansan de asaltar...', '', 28153),
(155626, 'esMX', 'Algunos trols poco amigables de la isla han decidido venir a aguarnos la fiesta. Están montando campamento en la isla.', '', 28153),
(155625, 'esMX', 'Veo canoas de trols de la isla en el horizonte y estarán aquí en cualquier momento. Esta azerita es como un faro que atrae todo lo que odio.', '', 28153),
(155624, 'esMX', 'Han aparecido algunos trols de la isla. Posiblemente también vienen en busca del botín de azerita. Si pudieran mantenerlos alejados de la nave, se los agradecería.', '', 28153),
(155623, 'esMX', 'Miren, acaba de llegar un gran puñado de barcos trols. Justo lo que necesitamos. Un grupo de asalto entero de trols. ¿Por qué no? Una idea fantástica.', '', 28153),
(155622, 'esMX', 'Y un dragón ENORME acaba de aparecer de la nada. Justo lo que le faltaba a mi día. Ha sido una semana dura para mí, ¿saben? Bueno... como decía, sí, un dragón.', '', 28153),
(155621, 'esMX', 'Ey, amigos. Un dragón enorme ha decidido unirse a la fiesta y parece interesado en la azerita. Solo quería avisarles.', '', 28153),
(155620, 'esMX', 'Dragones, tenemos dragones, y vienen directo hacia la nave. Creo que pueden verme. Eh, ¿podrían ayudarme?', '', 28153),
(155619, 'esMX', 'Bueno, acaba de llegar algo así como un vuelo entero de dragones. Apuesto a que sé qué vienen a buscar. ¡Buena suerte!', '', 28153),
(155618, 'esMX', '¿Qué le está pasando al cielo? ¿Por qué de repente se oscureció todo? ¿Y POR QUÉ hay cadáveres por toda la isla? Ay, ay, ay.', '', 28153),
(155617, 'esMX', 'Pero qué olor TAN desagradable. ¿Quién fue el responsable? Ah, los muertos. Oigan todos, ¡los muertos han venido a buscar la azerita! ¿De acuerdo?', '', 28153),
(155616, 'esMX', 'Ah, y esto se pone mejor. Parece que los no-muertos están invadiendo la isla. Ya no quiero enterarme de nada más.', '', 28153),
(155615, 'esMX', '¿Los no-muertos? ¿Aquí? No tengo idea de qué es lo que está sucediendo, pero seguramente es algo malo.', '', 28153),
(155614, 'esMX', 'Cuidado, veo algunos barcos tol\'vir en el horizonte y no parecen interesados en comerciar pacíficamente. ¿Podrían apresurarse un poco, por favor?', '', 28153),
(155613, 'esMX', 'Vaya, conque los tol\'vir... Hacía mucho, mucho tiempo que no veía uno de sus barcos. Bien, ya están aquí. Ah, y nos detestan.', '', 28153),
(155612, 'esMX', 'Unos barcos tol\'vir acaban de atracar. ¿Cómo es que todos saben dónde está la azerita? Detesto esta cosa. ¿Pueden encargarse de ellos?', '', 28153),
(155611, 'esMX', '¿Qué es eso, centauros? ¿Fortachones? Oigan, creo que acaban de aparecer unos... tol\'vir, o como sea que se llamen.', '', 28153),
(155610, 'esMX', 'Barco pirata en el horizonte. Posiblemente vengan a saquear este lugar. Los piratas suelen hacer eso.', '', 28153),
(155609, 'esMX', 'Está desembarcando una tripulación de piratas. Era de esperar. En una isla con un tesoro, no pueden faltar los piratas.', '', 28153),
(155608, 'esMX', 'Ah, por supuesto, ahora tenemos un TERCER barco. Siempre me dan las misiones más divertidas. Son piratas, por si se lo estaban preguntando.', '', 28153),
(155607, 'esMX', '¡Vaya! Nos acaba de rozar una bala de cañón. Tenemos piratas. Muchos. Y están llegando a la costa en este mismo instante.', '', 28153),
(155606, 'esMX', 'Acaban de aparecer unos saurok. Deben haber sentido el aroma de la azerita. Un momento, ¿tienen narices? No pienso preguntarles.', '', 28153),
(155605, 'esMX', 'Bueno, una banda de guerra saurok acaba de salir nadando del océano. Sí, así como lo oyen.', '', 28153),
(155604, 'esMX', '¿Qué es eso que veo en las olas? Ah, acaban de emerger muchos saurok de las profundidades. Ustedes se encargarán.', '', 28153),
(155603, 'esMX', 'Unos lagartos que lucen poco amistosos están observando nuestra nave y su azerita. Pienso que quizá sería mejor que no les permitan llevársela. Es mi opinión, claro.', '', 28153),
(155602, 'esMX', 'Tenemos algunas visitas, jamás había visto a estos tipos antes. Me atrevo a pensar que no están aquí para ayudarnos.', '', 28153),
(155601, 'esMX', 'Acabo de ver algunas visitas extrañas. Parece que están juntando azerita como nosotros, pero... algo me dice que no son de fiar.', '', 28153),
(155600, 'esMX', '¡Ah! ¿De dónde salieron esos tipos? Es como si se hubieran materializado de la nada. Oigan, héroes. Tenemos compañía.', '', 28153),
(155599, 'esMX', '¿Quién demonios son estos tipos? No logro reconocer sus caras. ¿Serán amistosos? Lo dudo.', '', 28153),
(155598, 'esMX', 'Y ahora parece que hemos captado la atención nada más ni nada menos que de un dios antiguo y sus esbirros. Eh, ¿podrían encargarse de todo esto?', '', 28153),
(155597, 'esMX', 'Tenemos algunas monstruosidades con tentáculos en la cara en la isla y... bueno, eso... Yo me esconderé aquí abajo. Adiós.', '', 28153),
(155596, 'esMX', '¿Nadie más oye los susurros? Tal vez estoy enloqueciendo o quizás hay ignotos en la isla. Ah, y vienen en busca de la azerita.', '', 28153),
(155595, 'esMX', 'Esto es una tormenta de oscuridad sombría. Genial. Deben ser los dioses antiguos. Cuidado con los tentáculos.', '', 28153),
(155594, 'esMX', 'Bien, tenemos mogu que vienen a buscar la azerita. Muchos. Será mejor que vengan.', '', 28153),
(155593, 'esMX', 'Vi a algunos mogu por la isla hace un instante. Tengan cuidado... no somos precisamente amigos.', '', 28153),
(155592, 'esMX', 'Algunos, eh, mogu, acaban de desembarcar en la isla. No sé qué estarán haciendo, pero dejaré que ustedes investiguen.', '', 28153),
(155591, 'esMX', 'Los dragones voladores de los mogu traen un grupo de asalto. Una vez más, la azerita nos ha delatado. Siempre lo mismo.', '', 28153),
(155590, 'esMX', 'Bien, los nagas están aquí. Justo lo que necesitábamos. Intenten no morir ahí fuera, ¿de acuerdo?', '', 28153),
(155589, 'esMX', 'He visto algunos nagas por el catalejo, estarán aquí muy pronto. Denles una calurosa bienvenida de mi parte, ¿sí?', '', 28153),
(155588, 'esMX', 'Algunos nagas acaban de llegar a la isla en busca de azerita. Sin dudas es una tarea que les encomendó nuestra amiga Azshara. ¿Qué es lo que trama?', '', 28153),
(155587, 'esMX', 'Los nagas emergen desde las profundidades, parece que quieren robarse nuestro botín. Me adelantaré y empezaré a cargar los cañones.', '', 28153),
(155586, 'esMX', '¡Cuánta niebla! Ah, un momento, veo barcos derruidos. Bien, son los kvaldir. Fantástico.', '', 28153),
(155585, 'esMX', 'Hemos visto algunos barcos kvaldir y estarán aquí en cualquier instante. Deben venir por la azerita. No sé por qué acepté este trabajo.', '', 28153),
(155584, 'esMX', '¿Pero qué es toda esta niebla? Ah, seguramente sean kvaldir. Abran bien los ojos... aunque entre toda esta bruma dudo que sea de ayuda.', '', 28153),
(155583, 'esMX', 'Vaya, ¿qué es lo que huele a algas? Ah, muchachos, veo que han llegado algunos kvaldir.', '', 28153),
(155582, 'esMX', 'Estamos a punto de quedar cubiertos de insectos... Se acerca un enjambre enorme de mántides. Estaré bajo cubierta, ¡que se diviertan!', '', 28153),
(155581, 'esMX', 'He oído hablar de estos tipos, se llaman mántides, creo. Ustedes, eh, encárguense de ellos por nosotros, ¿sí? Yo soy alérgico a esas cosas.', '', 28153),
(155580, 'esMX', '¿Eso es un enjambre de abejas? No, son demasiado grandes. Ah, son los mántides. Y ya casi los tenemos encima.', '', 28153),
(155579, 'esMX', 'Escuchen esto, les encantará. Llegaron mántides. ¿Y adivinen qué buscan? La azerita, por supuesto.', '', 28153),
(155578, 'esMX', '¡Uoo! ¿Qué fue eso que voló por encima? ¿Lo vieron? Hay un dragón enorme en algún lugar de la isla. Tengan cuidado.', '', 28153),
(155577, 'esMX', 'Bien, acaba de llegar un dragón enorme con un puñado de dragones más pequeños. Y no parecen estar muy contentos con nuestro plan de llevarnos la azerita.', '', 28153),
(155576, 'esMX', 'Esto es simplemente perfecto, un dragón negro. ¡Un dragón negro! ¡Y medio vuelo lo acompaña! ¡Aquí! Simplemente perfecto.', '', 28153),
(155575, 'esMX', 'Eh, un dragón enorme acaba de descender sobre la isla. Saben que mi bote es inflamable, ¿verdad? Manténganlo lejos. Lo más lejos posible.', '', 28153),
(155574, 'esMX', 'Los tol\'vir están trayendo sus fuerza\' para la cacería de azerita. Tengan cuidado ahí afuera.', '', 28153),
(155573, 'esMX', 'Ey, han llegado algunos tol\'vir. Vienen en busca de la azerita, como nosotro\', ja, ja.', '', 28153),
(155572, 'esMX', 'Jamás creí que vería otra nave tol\'vir. Alguno\' de ello\' están en la costa y lucen bastante enojado\'.', '', 28153),
(155571, 'esMX', 'Acaban de llegar unos bote\'. Los he vih\'to en una sola ocasión, son los tol\'vir. No lucen muy amistoso\'.', '', 28153),
(155570, 'esMX', '', 'Trata de traer la reliquia sana y salva, $n. Astrandis está... un poco entusiasmado.', 28153),
(155569, 'esMX', '', 'Lo mejor que podemo\' hacer es mantener a estos piratas lejos de las aguas. Te lo agradezco, adalid.', 28153),
(155568, 'esMX', 'Te arrojaré al muelle.', '', 28153),
(155567, 'esMX', 'No solo el mar puede ser implacable.', '', 28153),
(155566, 'esMX', 'No sabes con quién te estás metiendo.', '', 28153),
(155565, 'esMX', '', 'Debemo\' saber qué planean eh\'tos piratas. Intercepta sus órdenes... sea como sea.', 28153),
(155564, 'esMX', 'Las mareas regresan, siempre.', '', 28153),
(155561, 'esMX', 'Que el mar te transporte con ligereza.', '', 28153),
(155560, 'esMX', 'Nunca te alejes del mar.', '', 28153),
(155558, 'esMX', 'Odio a las aves. Criaturas sucias y chillonas. Pasemos a asuntos importantes.', '', 28153),
(155557, 'esMX', 'Uno de nuestros contactos en Puerto Libre necesita ayuda para... calmar a sus aves. Supongo que podrás encargarte.', '', 28153),
(155556, 'esMX', 'Sirvo a las mareas.', '', 28153),
(155554, 'esMX', '¿Tú también sientes... el poder de la... roca?', '', 28153),
(155553, 'esMX', '¡Esta roca nos hará RICOS! ¡No te la llevarás!', '', 28153),
(155552, 'esMX', 'Que las mareas te guíen.', '', 28153),
(155551, 'esMX', 'Si escuchas las mareas, aprenderás mucho del mundo.', '', 28153),
(155550, 'esMX', 'Tengo mis sospechas...', '', 28153),
(155549, 'esMX', 'No me hagas llamar a los guardias.', '', 28153),
(155548, 'esMX', 'Si tienes algo que decir, ¡dilo de una vez!', '', 28153),
(155547, 'esMX', 'Por favor... tengan piedad de mi gato.', '', 28153),
(155546, 'esMX', '¿Te importa? Soy un hombre muy ocupado.', '', 28153),
(155545, 'esMX', '¡Regresa con más historias de tus aventuras!', '', 28153),
(155543, 'esMX', '¡Más de los secuaces de Nedly! ¡Los dejaré bajo tierra como a todos los demás!', '', 28153),
(155540, 'esMX', '¡Estupendo!', '', 28153),
(155539, 'esMX', '¡Que lo pases sensacional!', '', 28153),
(155538, 'esMX', 'Siéntete como en casa. Mi finca es tu finca.', '', 28153),
(155536, 'esMX', '¡Come, bebe y disfruta!', '', 28153),
(155535, 'esMX', '¡Te doy la bienvenida al Festival de Equitación y Cacería de Norwington!', '', 28153),
(155534, 'esMX', '', 'Y 500 mil millones de norgabytes de imágenes de felinos adorables.', 28153),
(155533, 'esMX', 'Qué $uoportuno:oportuna;. ¡Tenemos un ataque de troggs entre manos!', '', 28153),
(155532, 'esMX', '', 'Eh\'tán jugando con fuerzas con las que nadie debería meterse. ¡Debemo\' mantener los mares despejados!', 28153),
(155531, 'esMX', '¡Guerreros de la Horda! ¡Enséñenle a la Alianza por qué luchamos! ¡Avancen hacia el castillo!', '', 28153),
(155530, 'esMX', '', '¡Reúnanse! ¡Avancen! ¡Arathi será nuestra!', 28153),
(155529, 'esMX', '', 'Los humanos eh\'tán invocando algo terrible desde las profundidade\'. ¡Detenlos!', 28153),
(155528, 'esMX', '¿El tortollano?', '¿El tortollano?', 28153),
(155527, 'esMX', '', '¡Ese caparazón con manos y patas de ahí! \n\nQue no te engañe. ¡Es astuto y muy entrometido! Siempre anda hurgando en busca de viejas reliquias, pergaminos y otras basuras. \n\nNo queremos que encuentre el tesoro primero.', 28153),
(155526, 'esMX', '¡Mi tío se enterará de esto!', '', 28153),
(155525, 'esMX', '¿Por qué no te alejas un poco... por favor?', '', 28153),
(155524, 'esMX', 'Disculpa, ¿podrías dejarme en paz?', '', 28153),
(155522, 'esMX', 'Creo que eso es todo.', '', 28153),
(155521, 'esMX', 'Nadie me advirtió... sobre las dificultades de ser líder.', '', 28153),
(155520, 'esMX', 'Hago lo que puedo.', '', 28153),
(155516, 'esMX', '¡Yo vigilo Puntanzuelo!', '', 28153),
(155515, 'esMX', 'Debo demostrarle a mi tío lo que valgo.', '', 28153),
(155514, 'esMX', 'Las mareas te dan la bienvenida.', '', 28153),
(155513, 'esMX', 'De acuerdo.', '', 28153),
(155512, 'esMX', 'Si no necesitas nada, retírate por favor.', '', 28153),
(155511, 'esMX', 'Vuelvo a mi puesto.', '', 28153),
(155510, 'esMX', 'Tengo un deber que cumplir.', '', 28153),
(155509, 'esMX', 'Mmm.', '', 28153),
(155508, 'esMX', '¡Fascinante! Debería poder crear algunas... pociones interesantes con estos objetos.', '', 28153),
(155507, 'esMX', '¡Esta área está repleta de recursos naturales y componentes alquímicos interesantes que podemos aprovechar! Recupera algunos de estos objetos valiosos para mí.', '', 28153),
(155506, 'esMX', '', 'Nuestros granjeros agradecen tu ayuda para mantener a la fauna a raya.', 28153),
(155505, 'esMX', '', 'Las bestias salvajes invaden las granjas cerca de la costa. Ayuda a los granjeros y encárgate del problema.', 28153),
(155504, 'esMX', 'Si nos tocas una vez más, provocarás una reacción seria. Posiblemente fatal.', '', 28153),
(155503, 'esMX', 'Si vuelves a hacer eso, descubrirás que no siempre somos divertidos.', '', 28153),
(155502, 'esMX', 'Si perdemos el gorro, te arrepentirás.', '', 28153),
(155501, 'esMX', '¿Eso es todo?', '', 28153),
(155500, 'esMX', 'Crezcan con honor. Nuestras mentes están despejadas.', '', 28153),
(155499, 'esMX', 'Que las esporas te acompañen.', '', 28153),
(155498, 'esMX', 'Te vemos.', '', 28153),
(155497, 'esMX', '¡Te ofrecemos nuestros saludos!', '', 28153),
(155496, 'esMX', 'Siempre debe haber... un Rey liquen...', '', 28153),
(155495, 'esMX', '¡Agonía de hongos está hambrienta!', '', 28153),
(155494, 'esMX', '¡Agh!', '', 28153),
(155493, 'esMX', 'Las esporas nos encuentran...', '', 28153),
(155492, 'esMX', 'No... podemos... oír...', '', 28153),
(155491, 'esMX', '¡Matarte! ¡Matar! ¡Matar!', '', 28153),
(155490, 'esMX', '¡Únete a nosotros!', '', 28153),
(155489, 'esMX', '¡Muere! ¡Muere! ¡Muere!', '', 28153),
(155488, 'esMX', '', '¡Ja! Los Firmemares estarían celosos de verte matar así.', 28153),
(155487, 'esMX', 'Una monstruosidad maldita está alimentándose con las tripas de nuestros novatos. Mátala... o tendré que reclutar más conscriptos inútiles.', '', 28153),
(155486, 'esMX', '', 'Algunos guardias kultiranos han informado de la presencia de una bestia grande en el área. Es una amenaza para todos los navegantes.', 28153),
(155485, 'esMX', 'Los cuentos de piratas mencionan un demonio esquelético que vive en el canal. Esta explicación es mucho mejor.', '', 28153),
(155484, 'esMX', 'Una gran bestia se ha arrastrado hasta la costa. No sé de dónde vino, pero parece peligrosa.', '', 28153),
(155483, 'esMX', '¡Buen trabajo! Algunos de los prisioneros de Tol Dagor estaban allí por una razón. Él era uno.', '', 28153),
(155482, 'esMX', '', 'Pero qué demente. Has salvado la vida de mucho\'.', 28153),
(155481, 'esMX', 'Ahora partiré...', 'Ahora partiré...', 28153),
(155480, 'esMX', 'Ahora estoy a salvo.', 'Ahora estoy a salvo.', 28153),
(155479, 'esMX', 'Gracias.', 'Gracias.', 28153),
(155478, 'esMX', 'Anhelo descansar...', 'Anhelo descansar...', 28153),
(155477, 'esMX', 'Estaba perdida...', 'Estaba perdida...', 28153),
(155476, 'esMX', 'Tenía miedo... pero ya no...', 'Tenía miedo... pero ya no...', 28153),
(155475, 'esMX', '¿Estás bien?', '', 28153),
(155474, 'esMX', 'La Luz es tan cálida...', 'La Luz es tan cálida...', 28153),
(155473, 'esMX', '', 'Gracias por tu ayuda. Jamás la olvidaremos.', 28153),
(155471, 'esMX', 'Por aquí.', 'Por aquí.', 28153),
(155470, 'esMX', '¡¡¡Recarguen!!!', '¡¡¡Recarguen!!!', 28153),
(155469, 'esMX', '', '¡Hereje! ¡No interferirás!', 28153),
(155468, 'esMX', '¡¡¡Fuego!!!', '¡¡¡Fuego!!!', 28153),
(155467, 'esMX', '', 'Zandalar está hecha de oro. Tiene que haber una forma de robar toda una ciudad, ¿no?', 28153),
(155466, 'esMX', '', 'Un prófugo de la prisión humana atracó cerca del puerto de la Horda. Es un peligro para todo\' nosotros.', 28153),
(155465, 'esMX', '¡Creo que reconozco a ese tipo! Un segundo... claro que lo conozco. Y no es nada bueno.', '', 28153),
(155464, 'esMX', '¡Las profundidades... nos concederán... más!', '', 28153),
(155463, 'esMX', '¡Este poder es un obsequio de las profundidades!', '', 28153),
(155462, 'esMX', 'Creí que tal vez estos kultiranos serían adversarios dignos... pero se desmoronan como cualquier cobarde inútil de la Alianza.', '', 28153),
(155461, 'esMX', 'Un forestal oscuro ha atraído a uno de los consejeros del gran almirante. La trampa está lista... Tienes el honor de activarla.', '', 28153),
(155460, 'esMX', '', 'Los espíritus de los muertos pueden volver a descansar tranquilos.', 28153),
(155459, 'esMX', 'Bueno... pero volverás, ¿cierto?', '', 28153),
(155458, 'esMX', 'Bien, ¡nos vemos luego!', '', 28153),
(155457, 'esMX', '¡Eso le enseñará a la Horda a no meterse con nuestros marinos! Buen trabajo.', '', 28153),
(155456, 'esMX', 'Uno de los oficiales de Valiente ha arrinconado a una forestal oscura. ¡Ayúdalo!', '', 28153),
(155455, 'esMX', '¡Estoy orgulloso de mi papá!', '', 28153),
(155454, 'esMX', '¡Hoy será un buen día!', '', 28153),
(155453, 'esMX', 'Papá dice que los grandes a veces se asustan. ¿Tú te asustas?', '', 28153),
(155452, 'esMX', '¡Oh! ¡Mira qué ponis más preciosos!', '', 28153),
(155451, 'esMX', '¡Nunca es demasiado tarde para aprender!', '', 28153),
(155450, 'esMX', '¡Hasta la próxima!', '', 28153),
(155449, 'esMX', '', 'Los esbirros de las brujas han agitado a estos espíritus. Elimina esa influencia corruptora y guía a los perdidos de regreso a la paz.', 28153),
(155448, 'esMX', 'En fin... ¡Al menos pude probar un Reserva zanchuli una...<¡hic!>...última vez antes de morir!', '', 28153),
(155447, 'esMX', 'Oí que decían que Mojambo contrató refuerzo\' para la batalla. Ahora cuenta con el apoyo de la tripulación de Tongo...', '', 28153),
(155446, 'esMX', 'Vi a la pandilla de Mojambo explorando la arena...', '', 28153),
(155445, 'esMX', 'Tú cumplih\'te con tu parte del trato, así que yo cumpliré con la mía...', '', 28153),
(155444, 'esMX', '¡Ahhh! Han pasado año\' desde la última vez que probé un Reserva zanchuli...<¡hic!>', '', 28153),
(155443, 'esMX', 'Aquí tienes el ron. Dime lo que oíste.', 'Aquí tienes el ron. Dime lo que oíste.', 28153),
(155442, 'esMX', '¡Bien, nos vemos! Estaré... aquí.', '', 28153),
(155441, 'esMX', 'Busco conocimiento. ¿Tú qué buscas?', '', 28153),
(155440, 'esMX', 'Hemos viajado a lo largo y a lo ancho, ¡pero por fin llegamos!', '', 28153),
(155439, 'esMX', 'Buena caza.', '', 28153),
(155438, 'esMX', '¡Por la Horda!', '', 28153),
(155437, 'esMX', '¿Tienes que rastrear algo?', '', 28153),
(155436, 'esMX', 'Con colmillos y garras.', '', 28153),
(155435, 'esMX', 'Esto es el colmo, ¡te cazaré!', '', 28153),
(155434, 'esMX', '¡Bueno, ya basta!', '', 28153),
(155433, 'esMX', 'Yo... eh... me gusta cazar solo.', '', 28153),
(155432, 'esMX', '¡Que empiece la cacería!', '', 28153),
(155431, 'esMX', 'Que así sea.', '', 28153),
(155430, 'esMX', 'Al acecho.', '', 28153),
(155429, 'esMX', 'Que empiece la cacería.', '', 28153),
(155428, 'esMX', 'Mi presa se acerca.', '', 28153),
(155427, 'esMX', 'Oigo el rugido de la naturaleza.', '', 28153),
(155426, 'esMX', '¿Ves esos caballos? ¡Criaturas majestuosas!', '', 28153),
(155425, 'esMX', '¡Espero volver a verte pronto!', '', 28153),
(155424, 'esMX', '¡Recuerda, no alimentes a los animales!', '', 28153),
(155423, 'esMX', '¡Disfruta del Centro Manantial!', '', 28153),
(155422, 'esMX', '...', '', 28153),
(155421, 'esMX', '¿Por qué estamos aquí?', '¿Por qué estamos aquí?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'esMX', '¿Qué ibas a decirme?', '¿Qué ibas a decirme?', 28153),
(155419, 'esMX', 'No debemos demorarnos. Nos queda poco tiempo.', 'No debemos demorarnos. Nos queda poco tiempo.', 28153),
(155418, 'esMX', '¿Cómo estás?', '', 28153),
(155417, 'esMX', '¡Hola!', '', 28153),
(155416, 'esMX', '¡$uBienvenido:Bienvenida; al Centro Manantial Burbujeante!', '', 28153),
(155415, 'esMX', '', '¡Mis hermanas... obtendrán... el poder de la piedra!', 28153),
(155414, 'esMX', '', '¡Madre estará complacida con el poder de esta piedra!', 28153),
(155413, 'esMX', 'Tú decides qué región visitaremos primero. Cuando hayas elegido una, partiremos de inmediato.', '', 28153),
(155412, 'esMX', 'Bueno, $n, es hora de poner manos a la obra. Tenemos un operativo listo para emprender una misión importante.', '', 28153),
(155411, 'esMX', 'Que la Luz te acompañe, rey Wrynn.', '', 28153),
(155410, 'esMX', 'Buen viaje, mi rey.', '', 28153),
(155409, 'esMX', 'Debo regresar a Ventormenta, pero espero con ansias oír sobre su progreso. Tengo la certeza de que esta campaña está en las manos indicadas. Mucha suerte.', '', 28153),
(155408, 'esMX', 'Adalid.', '', 28153),
(155407, 'esMX', 'Para las situaciones que exijan métodos más... sutiles: el maestro Mathias Shaw y la IV:7 estarán a tu disposición.', '', 28153),
(155406, 'esMX', 'Es un honor trabajar contigo, $n.', '', 28153),
(155405, 'esMX', 'Para asistirte, contarás con todo el apoyo de los mejores soldados de la Alianza: la Séptima Legión, liderada por el Alto comandante Halford Aterravermis.', '', 28153),
(155404, 'esMX', 'Como gran adalid de la Alianza, serás una parte esencial de nuestra estrategia para ganar la guerra. La Horda no debe cumplir su meta de aliarse con los zandalari.', '', 28153),
(155403, 'esMX', '$n, ha llegado la hora de luchar en Zandalar. Espero tu llegada abordo del Redención del Viento en Boralus.', '', 28153),
(155402, 'esMX', '¡Este bosque está maldito! ¡Lárgate! ¡Corre mientras puedas!', '¡Este bosque está maldito! ¡Lárgate! ¡Corre mientras puedas!', 28153),
(155401, 'esMX', '¡Jamás vi una locura semejante!', '¡Jamás vi una locura semejante!', 28153),
(155400, 'esMX', '¡Se comieron a mi perro! ¡Y me iban a comer a mí!', '¡Se comieron a mi perro! ¡Y me iban a comer a mí!', 28153),
(155399, 'esMX', 'Por los percebes del bote de mi abuelo, ¿qué está pasando aquí?', 'Por los percebes del bote de mi abuelo, ¿qué está pasando aquí?', 28153),
(155398, 'esMX', 'Me persiguió un grupo de conejitos. ¡Conejitos!', 'Me persiguió un grupo de conejitos. ¡Conejitos!', 28153),
(155397, 'esMX', '¡Ahhhhhhhhhhhhhhhhhhhhhh!', '¡Ahhhhhhhhhhhhhhhhhhhhhh!', 28153),
(155396, 'esMX', '¡Los animales han enloquecido!', '¡Los animales han enloquecido!', 28153),
(155395, 'esMX', '¡Gracias, $Uamigo:amiga;!', '¡Gracias, $Uamigo:amiga;!', 28153),
(155394, 'esMX', 'Los nagas eh\'tán apareciendo por la costa. Muchos vienen a asaltar la isla.', '', 28153),
(155393, 'esMX', 'Hemos avistado a los naga\'. Deben venir por la azerita que recolectaron. Tengan cuidado.', '', 28153),
(155392, 'esMX', 'Acaban de aparecer unas fuerzas nagas. Vayan a darles la bienvenida, ja.', '', 28153),
(155391, 'esMX', 'Los nagas vienen desde las profundidades a buscar las mismas gema\' que nosotro\'. Tengan cuidado.', '', 28153),
(155390, 'esMX', 'Tengan cuidado, un dragón enorme y todo su vuelo acaban de aparecer a lo lejo\' y van camino a ustede\'.', '', 28153),
(155389, 'esMX', 'Acaba de aparecer un grupo enorme de dragone\' y han empezado a recoger azerita por su cuenta. Será mejor que los detengan.', '', 28153),
(155388, 'esMX', 'Ey, tenemos visita\'. Un grupo de dragone\' acaba de pasar volando y tienen a nuestro navío en la mira.', '', 28153),
(155387, 'esMX', 'Algo se acerca volando... Parece que son dragone\'. Deben venir por la azerita. Tengan cuidado.', '', 28153),
(155386, 'esMX', '¿Dragones negro\'? ¿Aquí? Deben eh\'tar buscando azerita también. Tengan cuidado.', '', 28153),
(155385, 'esMX', 'Dragones... Jamá\' creí que vería a uno adulto. Vienen a buscar la azerita, nueh\'tra azerita.', '', 28153),
(155384, 'esMX', 'Eh, llegaron alguno\' dragone\' por aquí. Parece que la azerita llamó su atención.', '', 28153),
(155383, 'esMX', 'El cielo se oscurece... ¡es un dragón negro! Y trajo a sus hermano\' para saquear la isla. ¡Ayuda!', '', 28153),
(155382, 'esMX', 'Acaba de llegar una tripulación enorme repleta de equipo\' de Ventura y Cía. Vienen a buscar la azerita.', '', 28153),
(155381, 'esMX', 'Ventura y Cía. quiere montar una operación en eh\'ta isla. Deténgalos.', '', 28153),
(155380, 'esMX', 'Han llegado algunos inversore\' de Ventura y Cía. que quieren llevarse nueh\'tro botín. Necesito que vayan a negociar los término\' de esta transacción.', '', 28153),
(155379, 'esMX', 'Ey, amigos, Ventura y Cía. está aquí. Parece que eh\'tán montando campamento ahora mismo.', '', 28153),
(155378, 'esMX', 'Ey, miren, por ahí, un grupo de barco\' de trols de la isla. Quieren la azerita, igual que nosotro\'. ¡No dejen que se la lleven, ja!', '', 28153),
(155377, 'esMX', 'Alguno\' trols de la isla acaban de llegar para saquear eh\'te territorio. Traten de no llamar la atención.', '', 28153),
(155376, 'esMX', 'Veo canoa\' de trols de la isla en el horizonte. Nunca me agradaron. Maten a alguno\' de ello\' por mí, ¿sí?', '', 28153),
(155375, 'esMX', 'Eh\'tán llegando trols de la isla a la costa y no parecen muy amigable\'.', '', 28153),
(155374, 'esMX', 'Nos están disparando con unos cañone\'. Una nave pirata acaba de atracar, vienen a saquear la isla.', '', 28153),
(155373, 'esMX', 'Eh, ahora también tenemo\' pirata\'. Acaban de desembarcar, será mejor que vayan a darle\' la bienvenida.', '', 28153),
(155372, 'esMX', 'Una tripulación de pirata\' está atracando. Buscan lo mismo que nosotro\'. Tengan cuidado.', '', 28153),
(155371, 'esMX', '¡Ah! No me simpatizas...', '¡Ah! Creo... que deberías irte...', 28153),
(155370, 'esMX', 'Se acerca otro barco... Parecen ser pirata\'. Desháganse de ellos rápido, antes de que se roben nueh\'tro botín.', '', 28153),
(155369, 'esMX', 'Conozco a eso\' reptile\'. Un grupo de asalto saurok viene hacia aquí. Tengan cuidado.', '', 28153),
(155368, 'esMX', 'Hay un movimiento extraño en las ola\'. Parece que acaban de llegar los saurok. Y son mucho\'.', '', 28153),
(155367, 'esMX', 'Hay unos lagarto\' con cara de malo\' mirando nueh\'tro bote. Creo que será mejor que acaben con ello\', rápido.', '', 28153),
(155366, 'esMX', 'Una banda de guerra saurok eh\'tá saliendo del agua. También vienen a buscar la azerita.', '', 28153),
(155365, 'esMX', '¡Ah! No... ¡En la cara no!', '¡Agh! Ya puedes detenerte...', 28153),
(155364, 'esMX', '¡Agh! ¡No podré cumplir con mi entrega!', '¡Agh! ¡Mi seguro no cubre esto!', 28153),
(155363, 'esMX', '¿Oyeron eso? Los mántide\' han venido a buscar azerita. ¡No dejen que los piquen! ¡Ja, ja!', '', 28153),
(155362, 'esMX', 'Se acerca un enorme enjambre de insecto\'. Tengan cuidado... Vienen a buscar lo mismo que nosotro\'.', '', 28153),
(155361, 'esMX', 'Acaban de aparecer esto\' tipo\', creo que se hacen llamar mántide\'. Parece que también vienen a buscar azerita.', '', 28153),
(155360, 'esMX', 'Ese zumbido... viene del cielo. Hay un enjambre de insecto\' a punto de aterrizar en la isla, o eso creo.', '', 28153),
(155359, 'esMX', '¡Oh! Mi seguro paga el doble por esto...', '¡Agh! ¡Esto es vergonzoso!', 28153),
(155358, 'esMX', 'Eh\'píritus... llévenme…', 'Eh\'píritus... llévenme...', 28153),
(155357, 'esMX', 'Oigan, ¿qué es lo que huele a alga\'? Por allí, son chalupa\' kvaldir que acaban de llegar a la costa.', '', 28153),
(155356, 'esMX', 'No logro ver nada con toda eh\'ta niebla. Deben ser los kvaldir, tengan cuidado.', '', 28153),
(155355, 'esMX', 'Se acercan unos botes destruido\', y apestan a kvaldir. Vienen por nuestra azerita.', '', 28153),
(155354, 'esMX', 'Eh\'ta neblina que empieza a rodearnos no es normal. Los kvaldir llegarán pronto.', '', 28153),
(155353, 'esMX', 'Eh\'to no es... lo que planeé...', 'Eh\'to no es... lo que planeé...', 28153),
(155352, 'esMX', 'Siempre quise un barco pirata, colega. ¡Lo bauticé en honor a mi hija, Mala!\n\nSi consigo una nave aérea, ¡le pondré el nombre de mi hijo!', '', 28153),
(155351, 'esMX', '¿Cómo se te ocurrió el nombre?', '¿Cómo se te ocurrió el nombre?', 28153),
(155350, 'esMX', 'Ejejejejejejej...\n\nEsa e\' una historia para otro momento, colega.', '', 28153),
(155349, 'esMX', '¿De dónde sacaste este barco?', '¿De dónde sacaste este barco?', 28153),
(155348, 'esMX', 'Garona me encargó conseguir un barco. Así que conseguí uno.', '', 28153),
(155347, 'esMX', '¿Por qué tienes un barco pirata?', '¿Por qué tienes un barco pirata?', 28153),
(155346, 'esMX', 'Tenemo\' unos amigo\' nuevos que han venido a visitarno\', ja, ja. Creo que son guerrero\' vrykul.', '', 28153),
(155345, 'esMX', 'Ey, alguien acaba de llegar a la isla. Parece que son asaltante\' vrykul. Tengan cuidado.', '', 28153),
(155344, 'esMX', 'Unos bote\' vrykul están atracando. Un grupo de asalto... Vienen por nueh\'tro botín.', '', 28153),
(155343, 'esMX', 'Ey, $Ujefe:jefa;, ¿$Ulisto:lista; para el motín?', '', 28153),
(155342, 'esMX', 'Veo algunas chalupa\' en el horizonte. Deben ser los vrykul que se quieren llevar las gema\'.', '', 28153),
(155341, 'esMX', 'Algo está enviando a los muerto\' hacia nosotro\'. Algo de otro mundo. Tengan cuidado.', '', 28153),
(155340, 'esMX', 'Los espíritu\' me dicen que los muerto\' han llegado y que vienen a buscar nuestra azerita.', '', 28153),
(155339, 'esMX', 'Agh, qué olor tan horrible. Deben ser los no-muerto\' que vienen a buscar nueh\'tro botín. Protéjanlo.', '', 28153),
(155338, 'esMX', 'Esta oscuridad no e\' natural, algo ha venido a buscar la azerita. Algo sinieh\'tro.', '', 28153),
(155337, 'esMX', 'Tenemo\' a unos visitante\' extraño que vienen por la azerita. Parecen una especie de culto.', '', 28153),
(155336, 'esMX', 'Eh, ni siquiera los vi llegar. Tienen compañía, ¡cuidado!', '', 28153),
(155335, 'esMX', 'Oigan, ¿quiénes son estos tipo\'? Parece que también están recolectando azerita. Será mejor que los detengan.', '', 28153),
(155334, 'esMX', 'Tenemos amigos nuevo\'. Jamás los había vih\'to. Seguramente vienen por la azerita.', '', 28153),
(155333, 'esMX', 'Veo alguno\' dragone\' mogu por la costa, estarán aquí en cualquier momento.', '', 28153),
(155332, 'esMX', 'Acaban de llegar los mogu y quieren llevarse nuestro botín. Denle\' una calurosa bienvenida, ja.', '', 28153),
(155331, 'esMX', 'Uno de los mogu viene por nuestra azerita. Estén atentos a los grupo\' de asalto.', '', 28153),
(155330, 'esMX', 'Vi algunos dragone\' volando a lo lejos. Los mogu llegarán pronto.', '', 28153),
(155329, 'esMX', 'Una tormenta de las sombra\'... Debe haber ignotos en camino.', '', 28153),
(155328, 'esMX', 'Eh, ¿ustede\' también oyen los susurro\'? Debe ser un dio\' antiguo que envía sus fuerza\' contra nosotro\'. Tengan cuidado.', '', 28153),
(155327, 'esMX', 'Unos amigo\' con tentáculo en la cara vienen a llevarse su azerita. Yo... me esconderé aquí abajo.', '', 28153),
(155326, 'esMX', 'La azerita ha llamado la atención de los ignoto\'. Algunos acaban de aparecer por aquí.', '', 28153),
(155325, 'esMX', '¡Ave mala, mala! Nada de sangre.', '¡Ave mala, mala! Nada de sangre.', 28153),
(155324, 'esMX', '¡Fuera!', '¡Fuera!', 28153),
(155323, 'esMX', '', 'Los bosques de Glenbrook vuelven a ser seguros para nuestros cazadores.', 28153),
(155322, 'esMX', '', '¡Los animales han caído bajo la influencia de las brujas y cazan a nuestros cazadores! ¡Sálvalos y acaba con estas bestias malditas!', 28153),
(155321, 'esMX', '', 'Eres como mi $ugracioso compañero:graciosa compañera; de aventuras, $p.', 28153),
(155320, 'esMX', '', 'Tu rostro se me hace conocido... ¿estuviste en la prisión de Tol Dagor?', 28153),
(155319, 'esMX', '', 'Bien hecho. La fauna de las colinas ya no será una amenaza para las comunidades circundantes.', 28153),
(155318, 'esMX', '', '¡La maldición de las brujas ha caído sobre la fauna de estas colinas! Ponle fin a esto antes de que lleguen al pueblo.', 28153),
(155317, 'esMX', '¡Te cuesta respirar!', '¡Te cuesta respirar!', 28153),
(155312, 'esMX', 'No se recuperarán pronto de este ataque. ¡Por la Dama Oscura!', '', 28153),
(155311, 'esMX', 'Las fuerzas de nuestra jefa de guerra han establecido una posición en la academia militar. ¡Ayúdalas!', '', 28153),
(155310, 'esMX', '', '¡Me entrené con algunos de esos hombres! ¡La Horda pagará por el daño que ha causado!', 28153),
(155309, 'esMX', '', 'Un grupo de élite de la Horda se abrió paso hasta la Academia Valiente. ¡Deberíamos ayudar a los marinos a defender!', 28153),
(155308, 'esMX', '', 'Amparo del Ocaso está a salvo otra vez, pero debemos permanecer atentos.', 28153),
(155307, 'esMX', '', 'La maldición de las brujas cae una vez más sobre Amparo del Ocaso. ¡Rómpela antes de que sea demasiado tarde!', 28153),
(155306, 'esMX', '', 'Ja... ¡El poder de las rocas... le pertenecerá a... Canto Tormenta!', 28153),
(155305, 'esMX', '', 'Esta roca es una dádiva de la tierra. ¡No se la llevarán!', 28153),
(155304, 'esMX', 'Cuando se marchitó, supe que debía arreglármelas por mi cuenta, así que de inmediato conseguí trabajo en el puerto. Esa flor evitó que me convirtiera en un vagante, como muchos otros.', 'Cuando se marchitó, supe que debía arreglármelas por mi cuenta, así que de inmediato conseguí trabajo en el puerto. Esa flor evitó que me convirtiera en un vagante, como muchos otros.', 28153),
(155303, 'esMX', 'No importa si vienen jabespines o invasores de la Horda, los habitantes de este valle resistirán.', '', 28153),
(155302, 'esMX', 'No llevarte... rocas de trogg...', '', 28153),
(155301, 'esMX', 'Mis rocas...', '', 28153),
(155300, 'esMX', 'Aplastarlos...', '', 28153),
(155299, 'esMX', 'Trogg... roto...', '', 28153),
(155298, 'esMX', 'Trogg se derrumba...', '', 28153),
(155297, 'esMX', 'Trogg... matar...', '', 28153),
(155296, 'esMX', '¡Arrraagh!', '', 28153),
(155295, 'esMX', 'Garuuuu...', '', 28153),
(155294, 'esMX', '¡Esta es tierra de troggs! ¡Largo!', '', 28153),
(155293, 'esMX', '¡Aaaraauuh! ¡Trogg matarlos!', '', 28153),
(155292, 'esMX', '¡Romperlos en piedritas!', '', 28153),
(155291, 'esMX', '', 'He mantenido el orden en todo Kul Tiras. ¿En qué puedo ayudarte?', 28153),
(155290, 'esMX', '¡Rocas brillantes le pertenecen a trogg! ¡Largo!', '', 28153),
(155289, 'esMX', '¡Graaaaraah! ¡Destruir!', '', 28153),
(155288, 'esMX', '¡Trogg romperles la cara!', '', 28153),
(155287, 'esMX', '¡Trogg aplastar sus cabezotas!', '', 28153),
(155286, 'esMX', '¡Esta es tierra de troggs!', '', 28153),
(155285, 'esMX', '¡Troggzor!', '', 28153),
(155284, 'esMX', '¡Mis rocas! ¡No de ustedes!', '', 28153),
(155283, 'esMX', '¡Mi tesoro! ¡Mío!', '', 28153),
(155282, 'esMX', '¡Rarrragh!', '', 28153),
(155281, 'esMX', '¡Aaaaaraaagh!', '', 28153),
(155280, 'esMX', '¡Aplastar! ¡Romper! ¡MATAR!', '', 28153),
(155279, 'esMX', '¡Trogg aplasta!', '', 28153),
(155278, 'esMX', '¡Trogg no tonto!', '', 28153),
(155277, 'esMX', '¡Eh! ¿Has vih\'to lo que la princesa le hizo a la Alianza? A tu izquierda, podrás ver parte de los reh\'tos. ¡Es una muestra clara del poder de los loa!', '', 28153),
(155276, 'esMX', 'Durante un tiempo, los naga\' desaparecieron. Se habló mucho de la reconstrucción, pero con Gral desaparecido o demasiado débil para ayudar, todo quedó en la nada.', '', 28153),
(155275, 'esMX', 'Hasta el último de sus seguidore\' fue asesinado. ¡Gral estaba furioso! Esa noche, todo\' los que eh\'taban cerca del agua sintieron su dolor... mientras caían, uno a uno.', '', 28153),
(155274, 'esMX', '¡Oh, oh! ¡Es como si se hubiera aliviado un gran peso! ¡Sabíamos que esa bruja con pelo de serpiente estaba muerta!', '', 28153),
(155273, 'esMX', 'Que tengas un día fabuloso.', '', 28153),
(155272, 'esMX', 'Ten cuidado. Esta tierra ya no es segura.', '', 28153),
(155271, 'esMX', 'Hay tesoros por todo Canto Tormenta.', '', 28153),
(155270, 'esMX', 'Te doy la bienvenida al valle.', '', 28153),
(155269, 'esMX', '¡Saludos!', '', 28153),
(155268, 'esMX', 'Presabrenna es mi hogar, y lo protegeré.', '', 28153),
(155267, 'esMX', '', 'Soy una mujer de palabra. Tú y tu Horda son bienvenidos en mi pueblo.', 28153),
(155266, 'esMX', 'Sí, capitán. Eh\'tamos comprometido\' con tu causa. Y esperamo\' que tú también con la nueh\'tra.', '', 28153),
(155265, 'esMX', '', 'Libertad... Parece que son fieles a su palabra.', 28153),
(155264, 'esMX', '¿Por qué... han venido?', '', 28153),
(155263, 'esMX', 'Destruyeron solo una espina... las vides permanecen...', '', 28153),
(155262, 'esMX', '¡Grah!', '', 28153),
(155261, 'esMX', 'No... las gemas...', '', 28153),
(155260, 'esMX', 'No puedes matarnos... a todos...', '', 28153),
(155259, 'esMX', 'Me marchito...', '', 28153),
(155258, 'esMX', 'Quebrado...', '', 28153),
(155257, 'esMX', 'Espinas... rotas...', '', 28153),
(155256, 'esMX', '¡Las gemas resplandecientes de este lugar nos pertenecen, $Uinvasor:invasora;!', '', 28153),
(155255, 'esMX', '¡Las piedras fortalecen nuestras espinas!', '', 28153),
(155254, 'esMX', '¡Esta tierra y su poder nos pertenecen!', '', 28153),
(155253, 'esMX', 'Tu sangre no es nada contra nuestras lanzas de espinas.', '', 28153),
(155252, 'esMX', '¡Colgaré su carne en mi choza!', '', 28153),
(155251, 'esMX', 'Tomamos una buena decisión.', '', 28153),
(155250, 'esMX', '¡Nuestras vides se apoderarán de la isla y de su carne!', '', 28153),
(155249, 'esMX', 'Rompeespinas, su especie no tiene lugar aquí.', '', 28153),
(155248, 'esMX', '¡Esbirros, defiéndanme!', '', 28153),
(155247, 'esMX', '¡Que prueben una dosis de su propia medicina!', '', 28153),
(155246, 'esMX', '¡No pueden detener a las vides salvajes!', '', 28153),
(155245, 'esMX', 'Su sangre regará las espinas.', '', 28153),
(155244, 'esMX', '¡A llenarlos de balas!', '', 28153),
(155243, 'esMX', '¡Que mueran!', '', 28153),
(155242, 'esMX', 'Te marchitarás, $Uenemigo:enemiga; de las espinas.', '', 28153),
(155241, 'esMX', '¡Ese lugar es nuestro!', '', 28153),
(155240, 'esMX', 'Dentro de una jaula, no habríamos sido de mucha ayuda.', '', 28153),
(155239, 'esMX', '¡Desgarren su carne!', '', 28153),
(155238, 'esMX', '¡Atraviesen a los intrusos!', '', 28153),
(155237, 'esMX', '', 'Aguas turbulentas al frente.', 28153),
(155236, 'esMX', '¡Invasores!', '', 28153),
(155235, 'esMX', '¡Mueran, rompeespinas!', '', 28153),
(155234, 'esMX', '', 'Que la marea te guíe.', 28153),
(155233, 'esMX', 'Las reliquias están protegidas. Gral aún no está perdido.', '', 28153),
(155232, 'esMX', 'Sangre y truenos, camarada.', '', 28153),
(155231, 'esMX', 'Además, encontré este abalorio interesante.', '', 28153),
(155230, 'esMX', 'Según parece, no deberíamos habernos apurado tanto y abandonar el puesto de avanzada.', '', 28153),
(155229, 'esMX', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t%s te marca con una mecha ardiente, ¡aléjate de los barriles de municiones!', 28153),
(155228, 'esMX', 'Dih\'fruta tu último día de vida, Razgaji. La próxima vez que nos veamo\'... ¡será la última!', '', 28153),
(155227, 'esMX', 'La aventura nos trajo hasta aquí. Los descubrimientos que hicimos son otra pieza de este rompecabezas.', '', 28153),
(155226, 'esMX', '', 'Ten cuidado allá afuera.', 28153),
(155225, 'esMX', '', 'La alcaldesa está a tu servicio. ¿Cómo puedo ayudarte?', 28153),
(155224, 'esMX', '', 'Debo proteger a los ciudadanos de Canto Tormenta.', 28153),
(155223, 'esMX', '', '¿Vienes a dar una mano?', 28153),
(155222, 'esMX', '¡Por la Horda!', '', 28153),
(155221, 'esMX', '¡Mira cómo se retuerce en la red! ¡Será divertido destriparlo!', '¡Mira cómo se retuerce en la red! ¡Será divertido destriparlo!', 28153),
(155220, 'esMX', '¡Ja! ¡Capturé otro más!', '¡Ja! ¡Capturé otro más!', 28153),
(155219, 'esMX', 'Sí, colega. ¡Tengo muchas historia\' para contarte!', '', 28153),
(155218, 'esMX', '', 'Bien, Ty\'jin. Si vamos a trabajar juntos, cuéntame más sobre la Horda.', 28153),
(155217, 'esMX', 'Toda la azerita... será... nuestra...', '', 28153),
(155216, 'esMX', '¡Esta azerita es propiedad de la Compañía Aspafresno!', '', 28153),
(155215, 'esMX', '', '¡Nos atacan fuerzas enemigas! ¡Expúlsalas!', 28153),
(155214, 'esMX', '', 'Les has dado un respiro a nuestras fuerzas.', 28153),
(155213, 'esMX', '', '¡Has expulsado a las brujas! ¡Bien hecho!', 28153),
(155212, 'esMX', '', 'El aquelarre ataca esta área. ¡Deshazte de ellos!', 28153),
(155211, 'esMX', '', 'Nos has dado un respiro. Gracias.', 28153),
(155210, 'esMX', '', '¡Las fuerzas del aquelarre atacan a los ciudadanos de Drustvar! ¡Expulsa a las brujas!', 28153),
(155209, 'esMX', '', 'Te agradezco la ayuda en nombre de mi pueblo.', 28153),
(155208, 'esMX', '', 'Mi pueblo necesita tu asistencia. ¡Por favor, ayúdalos!', 28153),
(155207, 'esMX', '¡No! Dejémoslo en paz. Nos iremo\' por ahora... ¡pero no seremoh\' tan generosos cuando regresemo\'!', '', 28153),
(155206, 'esMX', '¡Yo puedo encargarme $udel:de la; $r, jefe! ¡No hay problema!', '¡Yo puedo encargarme $udel:de la; $r, jefe! ¡No hay problema!', 28153),
(155205, 'esMX', 'No volveré contigo. ¿Creeh\' que tus matones insignificante\' pueden contra mi $uamigo:amiga;? No comience\' una pelea que no puedes ganar.', '', 28153),
(155204, 'esMX', '¿Bah\'ta? ¡Yo decido cuándo se acabó tu tiempo! ¡Ya sabes lo que les pasa a los desertore\'!', '', 28153),
(155203, 'esMX', 'Ya basta, Mojambo. Eh\'toy cansado de matar y robar para sobrevivir. Ahora eh\'toy por mi cuenta...', '', 28153),
(155202, 'esMX', 'Jejeje...', 'Jejeje...', 28153),
(155201, 'esMX', 'No eh\'tabas tratando de eh\'conderte de tus viejos amigo\', ¿verdad?', '', 28153),
(155200, 'esMX', '¡Vaya, pero si es Razgaji! Les dije que lo encontraríamo\' aquí...', '', 28153),
(155199, 'esMX', 'No baje\' la guardia. Mojambo no es de confianza...', '', 28153),
(155198, 'esMX', 'Estoy listo. Vamos.', 'Estoy lista. Vamos.', 28153),
(155197, 'esMX', 'Que el mar bendiga estos lingotes, y nunca quiera recuperarlos.', 'Que el mar bendiga estos lingotes, y nunca quiera recuperarlos.', 28153),
(155196, 'esMX', '', '¡Gracias al poder de nuestra maestra, volveremos a alzarnos!', 28153),
(155195, 'esMX', '¿Puedes bendecir estos lingotes de plata de tormenta?', '¿Puedes bendecir estos lingotes de plata de tormenta?', 28153),
(155194, 'esMX', 'Buen viaje, $r.', 'Buen viaje, $r.', 28153),
(155193, 'esMX', '', '¡Todos se arrodillarán ante la reina Azshara!', 28153),
(155192, 'esMX', '', '¡Cuando su voluntad te consuma, tus ojos arderán!', 28153),
(155191, 'esMX', 'Quítale el arpón.', 'Quítale el arpón.', 28153),
(155190, 'esMX', '<La criatura te mira débilmente por un momento antes de volver la mirada hacia el arpón que tiene clavado en las costillas.>', '<La criatura te mira débilmente por un momento antes de volver la mirada hacia el arpón que tiene clavado en las costillas.>', 28153),
(155189, 'esMX', '¿Dónde vas?', '', 28153),
(155188, 'esMX', '¡Muga magudu! ¡Aplástenlos!', '', 28153),
(155187, 'esMX', '¡Ugafa! ¡Los haré sufrir!', '', 28153),
(155186, 'esMX', '¡Uuuuh, tipos malos! ¡Fuera!', '', 28153),
(155185, 'esMX', '¿Quién maguda es $Ueste:esta;?', '', 28153),
(155184, 'esMX', '¡Guaar! ¡Estas rocas... son mis rocas!', '', 28153),
(155183, 'esMX', '¡Guaaah! ¡No te llevarás el tesoro!', '', 28153),
(155182, 'esMX', '¿Guaaah? ¿Quién es este tipo?', '', 28153),
(155181, 'esMX', '¡Buaaguugh! ¡Serás alimento de los pececitos!', '', 28153),
(155180, 'esMX', '¿Agu...?', '', 28153),
(155179, 'esMX', '¡Urg!', '', 28153),
(155178, 'esMX', 'Gafu... mogo...', '', 28153),
(155177, 'esMX', 'Uug...', '', 28153),
(155176, 'esMX', '¡¿Mug?!', '', 28153),
(155175, 'esMX', 'Matufa...', '', 28153),
(155174, 'esMX', '¡Gurk!', '', 28153),
(155173, 'esMX', '¡A-bu-bu-bu-bu!', '', 28153),
(155172, 'esMX', '¡¿Urga magu?!', '', 28153),
(155171, 'esMX', '¡Grip!', '', 28153),
(155170, 'esMX', '¡Buga buga!', '', 28153),
(155169, 'esMX', '¡Agh!', '', 28153),
(155168, 'esMX', '¡Oka magodo!', '', 28153),
(155167, 'esMX', '¿Bokum?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'esMX', '¡Buga mabugu!', '', 28153),
(155165, 'esMX', '¡Ah gah mah gahma!', '', 28153),
(155164, 'esMX', 'Su corazón se debilita... Lo único que puedo hacer por él es acabar con su sufrimiento.', '', 28153),
(155163, 'esMX', '¡Aspafresno le ha puesto un precio a tu cabeza!', '¡Aspafresno le ha puesto un precio a tu cabeza!', 28153),
(155162, 'esMX', '¡Me llevaré una parte de tu cadáver como trofeo!', '¡Me llevaré una parte de tu cadáver como trofeo!', 28153),
(155161, 'esMX', '¡No puedes derrotar a Aspafresno!', '¡No puedes derrotar a Aspafresno!', 28153),
(155160, 'esMX', '¡La ciudad es nuestra!', '¡La ciudad es nuestra!', 28153),
(155159, 'esMX', '¡Boralus arderá!', '¡Boralus arderá!', 28153),
(155158, 'esMX', '¡Te pondré al tanto de todo en un lugar un poco más seguro!', '¡Te pondré al tanto de todo en un lugar un poco más seguro!', 28153),
(155157, 'esMX', 'Necesito un ferry para viajar a Drustvar.', 'Necesito un ferry para viajar a Drustvar.', 28153),
(155156, 'esMX', '¿Por qué... han venido?', '', 28153),
(155155, 'esMX', 'Rocas brillantes... mías...', '', 28153),
(155154, 'esMX', '¡Mi vela!', '', 28153),
(155153, 'esMX', '¡Ay, ay, ay!', '', 28153),
(155152, 'esMX', '¡Grah!', '', 28153),
(155151, 'esMX', 'La vela... apagarse...', '', 28153),
(155150, 'esMX', '¡Aaaaaaaaaaaaaaaaaaah!', '', 28153),
(155149, 'esMX', '¡No!', '', 28153),
(155148, 'esMX', '¡Quemarte como vela gigante!', '', 28153),
(155147, 'esMX', '¡Sus velas mías ahora!', '', 28153),
(155146, 'esMX', '¡Aplastarlos! ¡Llevarme sus cosas!', '', 28153),
(155145, 'esMX', '¡Agujero en tu calavera!', '', 28153),
(155144, 'esMX', '¡No llevarse rocas brillantes!', '', 28153),
(155143, 'esMX', '¡Mi isla! ¡Yo rey!', '', 28153),
(155142, 'esMX', '¡Rocas brillantes son mías! ¡Mías!', '', 28153),
(155141, 'esMX', 'Nosotros encontramos este lugar, ¡no ustedes!', '', 28153),
(155140, 'esMX', '¡Este es mi lugar!', '', 28153),
(155139, 'esMX', '¡Muérdanlos! ¡Quítenles las velas!', '', 28153),
(155138, 'esMX', '¡Grah! ¡Invasores!', '', 28153),
(155135, 'esMX', '¡No llevarse vela!', '', 28153),
(155134, 'esMX', '¡Bishibosh!', '', 28153),
(155133, 'esMX', '¡Rocas brillantes nuestras!', '', 28153),
(155132, 'esMX', '¡Rocas resplandecientes hacen brillar vela!', '', 28153),
(155131, 'esMX', 'Mucha suerte, continental. Si crees en algún dios, reza para que te acompañe.', 'Mucha suerte, continental. Si crees en algún dios, reza para que te acompañe.', 28153),
(155130, 'esMX', 'Aquí vamos. Esto es lo más lejos que te puedo llevar.', 'Aquí vamos. Esto es lo más lejos que te puedo llevar.', 28153),
(155129, 'esMX', 'La última vez que atraqué ahí, un lobo casi me arranca la pierna...', 'La última vez que atraqué ahí, un lobo casi me arranca la pierna...', 28153),
(155128, 'esMX', 'Iremos un poco más lejos... Puerto Trinchante no es un lugar muy amigable estos días.', 'Iremos un poco más lejos... Puerto Trinchante no es un lugar muy amistoso estos días.', 28153),
(155127, 'esMX', 'Sea cual sea tu propósito aquí, te recomiendo que no lo demores mucho.', 'Sea cual sea tu propósito aquí, te recomiendo que no lo demores demasiado.', 28153),
(155126, 'esMX', 'Al contrario de la mayoría de los kultiranos, no soy supersticioso, pero debo admitir que Drustvar tiene algo que me pone los pelos de punta.', 'Al contrario de la mayoría de los kultiranos, no soy supersticiosa, pero debo admitir que hay algo sobre Drustvar que me eriza los pelos de la nuca.', 28153),
(155125, 'esMX', 'Sin embargo, últimamente estas minas parecen haber quedado vacías y los carniceros han desaparecido.', 'Sin embargo, últimamente estas minas parecen haber quedado vacías y los carniceros han desaparecido.', 28153),
(155124, 'esMX', 'No hace mucho, los mercaderes usaban este ferry para proteger sus bienes contra los granjeros y mineros de la zona.', 'No hace mucho, los mercaderes usaban este ferry para proteger sus bienes contra los granjeros y mineros de la zona.', 28153),
(155123, 'esMX', 'La mayoría de los barqueros ya no atracan allí debido a los rumores oscuros que se oyen.', 'La mayoría de los barqueros ya no atracan ahí debido a los rumores oscuros que circulan.', 28153),
(155122, 'esMX', 'Vas camino a Drustvar, ¿eh? Tienes suerte de que esté al mando de este bote.', 'Vas camino a Drustvar, ¿eh? Tienes suerte de que esté al mando de este bote.', 28153),
(155121, 'esMX', '¡Uuh, ahh! ¡Ahhhh!', '', 28153),
(155120, 'esMX', 'Agh...', '', 28153),
(155119, 'esMX', 'Te... jeringaré...', '', 28153),
(155118, 'esMX', '¡Auch! ¡Mi kraku!', '', 28153),
(155117, 'esMX', '¡Gah!', '', 28153),
(155116, 'esMX', 'Malditos... makakus...', '', 28153),
(155115, 'esMX', 'Dingues... kakadores...', '', 28153),
(155114, 'esMX', '¡No, mis brillantes!', '', 28153),
(155113, 'esMX', 'La diversidad de flora y fauna de Zandalar debe investigarse y catalogarse.', 'La diversidad de flora y fauna de Zandalar debe investigarse y catalogarse.', 28153),
(155112, 'esMX', '¿De dónde salieron estos kakadores?', '', 28153),
(155111, 'esMX', '¡Les golpearé el kraku donde más duele!', '', 28153),
(155110, 'esMX', '¡Jerínguenlos y makúkenlos!', '', 28153),
(155109, 'esMX', '¡Excelente trabajo! ¡Volveremos a crear pociones potentes en un abrir y cerrar de ojos!', '', 28153),
(155108, 'esMX', 'Lo siento, $Ucompañero:compañera;, no tengo tiempo para trabajos nuevos. Mi agenda está reple... Ah, ¿tienes oro? No he dicho nada, ¿en qué puedo ayudarte?', 'Lo siento, $Ucompañero:compañera;, no tengo tiempo para trabajos nuevos. Mi agenda está reple... Ah, ¿tienes oro? No he dicho nada, ¿en qué puedo ayudarte?', 28153),
(155107, 'esMX', '¡Nuestras fuerzas necesitan más suministros alquímicos! Recupera los componentes necesarios en esta área. Ah, y ten cuidado con los osos.', '', 28153),
(155106, 'esMX', '', '¡Las fuerzas de las brujas están atacando Halcónida! ¡Elimina cualquier rastro de su magia asquerosa y restablece el orden en el pueblo!', 28153),
(155105, 'esMX', '', 'Has expulsado a las brujas y los ciudadanos de Halcónida están a salvo una vez más. Te lo agradecemos.', 28153),
(155104, 'esMX', '$UBienvenido:Bienvenida;, todo lo que ves acaba de ser robado a los nativos. ¡Es un buen día para probar algo nuevo y exótico!', '$UBienvenido:Bienvenida;, todo lo que ves acaba de ser robado a los nativos. ¡Es un buen día para probar algo nuevo y exótico!', 28153),
(155103, 'esMX', 'Márchense a hacer kraku a otra parte, ¡brillantes míos!', '', 28153),
(155102, 'esMX', 'Makakus lamekakus, ¡esta es mi isla!', '', 28153),
(155101, 'esMX', '¡Los aplastaré, kakadores!', '', 28153),
(155100, 'esMX', '¡Golpéalos con una llave inglesa!', '¡Mátalos!', 28153),
(155099, 'esMX', '¡Estamos por presenciar un accidente de trabajo!', '¡Se acabó la seguridad en el trabajo!', 28153),
(155098, 'esMX', '¡Reconozco a $uun perdedor:una perdedora; cuando $ulo:la; veo!', '¡Busca una llave inglesa! ¡$uEste:Esta; necesita unas reparaciones!', 28153),
(155097, 'esMX', 'Morimos... luchando...', '', 28153),
(155096, 'esMX', 'Perdimos... pero tú no ganas...', '', 28153),
(155095, 'esMX', 'Las esporas te reclaman....', '', 28153),
(155094, 'esMX', 'Persistimos... aun después de la muerte...', '', 28153),
(155093, 'esMX', 'Abandonamos este cuerpo...', '', 28153),
(155092, 'esMX', 'Al menos... morimos... con honor...', '', 28153),
(155091, 'esMX', 'Y así, caemos.', '', 28153),
(155090, 'esMX', 'Crecemos... para luchar... otra vez...', '', 28153),
(155089, 'esMX', '¡Por las esporas!', '', 28153),
(155088, 'esMX', '¡Nuestra voluntad es única!', '', 28153),
(155087, 'esMX', '¡Oye! ¡Tenemos reglas aquí, y las estás rompiendo todas!', 'Oye, tú... ¡estás $udespedido:despedida;!', 28153),
(155086, 'esMX', '¡Te asustaste! ¡Hemos ganado!', '', 28153),
(155085, 'esMX', '¡Siente el filo de nuestra espada!', '', 28153),
(155084, 'esMX', '¡Nuestra voluntad nos protege!', '', 28153),
(155083, 'esMX', '¡Ya has perdido esta batalla!', '', 28153),
(155082, 'esMX', '¡Tienes que practicar más!', '', 28153),
(155081, 'esMX', '¡Te cortaremos de pies a cabeza!', '', 28153),
(155080, 'esMX', 'Por favor, ¡salva a Boralus!', 'Por favor, ¡salva a Boralus!', 28153),
(155079, 'esMX', '¡Estos piratas están destrozando Boralus!', '¡Estos piratas están destrozando Boralus!', 28153),
(155078, 'esMX', '¡Gracias!', '¡Gracias!', 28153),
(155077, 'esMX', '¡Aplasten a los makakus y háganlos pedazos!', '', 28153),
(155076, 'esMX', '¡Yo rey aquí, makakus!', '', 28153),
(155075, 'esMX', '¡Mátenlos! ¡Tomen sus cosas!', '', 28153),
(155074, 'esMX', '¡Makakus continentales!', '', 28153),
(155073, 'esMX', '¡Maten a los makakus!', '', 28153),
(155072, 'esMX', '¡Brillantes hacernos fuertes!', '', 28153),
(155071, 'esMX', '¡Isla nuestra! ¡No de ustedes!', '', 28153),
(155070, 'esMX', '¡Vete a krakar!', '', 28153),
(155069, 'esMX', '¡No llevarte nuestros brillantes!', '', 28153),
(155068, 'esMX', '¡No se permiten makakus!', '', 28153),
(155067, 'esMX', 'Hace algunos años, entrené a Zalazane y a Vol\'jin para que se convirtieran en expertos de su oficio. Jamás imaginé el impacto que sus destinos tendrían en el mundo.', '', 28153),
(155066, 'esMX', '¡Oh! ¡Solo cumplía con mi trabajo!', '¡Solo cumplía con mi trabajo!', 28153),
(155065, 'esMX', '¡Oh! ¡Tendría que haber trabajado para ti!', '¡Tendría que haber trabajado para ti!', 28153),
(155064, 'esMX', '', '¿Mmm... sí? ¿Hay algo en lo que pueda ayudarte?', 28153),
(155063, 'esMX', '¡Uh! Extrañaré... las cervezas...', 'Extrañaré... las cervezas...', 28153),
(155062, 'esMX', '¡Uh! ¡Sabía que esto iba a salir mal!', '¡Sabía que este era un pésimo trabajo!', 28153),
(155061, 'esMX', 'Eh\'píritus... me uno a ustede\'...', 'Eh\'píritus... me uno a ustede\'...', 28153),
(155060, 'esMX', 'Solo deh\'cansaré... un momento...', 'Solo deh\'cansaré... un momento...', 28153),
(155059, 'esMX', 'Yo voy a... acusarte...', '', 28153),
(155058, 'esMX', 'Tú dejarme ganar la próxima...', '', 28153),
(155057, 'esMX', '¡Ja, ja! Yo ganar... Oh, un momento...', '', 28153),
(155056, 'esMX', 'No... yo no perder...', '', 28153),
(155055, 'esMX', 'Tú, problema... Yo solucionarlo.', '', 28153),
(155054, 'esMX', 'Yo té-té-técnico térmico. Yo inteligente. ¡Hacer fuego!', '', 28153),
(155053, 'esMX', 'Tú sentarte en aceite... ¡Yo darte fósforo!', 'Tú sentarte en aceite... ¡Yo darte fósforo!', 28153),
(155052, 'esMX', 'Yo no gustar fuego... ¡Tú parar!', 'Yo no gustar fuego... ¡Tú tenerlo!', 28153),
(155051, 'esMX', 'Tal ve\' te cocine a fuego lento.', 'Tal ve\' te cocine a fuego lento.', 28153),
(155050, 'esMX', 'Lo pensarás dos vece\' antes de entrometerte aquí.', 'Lo pensarás doh\' veces antes de entrometerte aquí.', 28153),
(155049, 'esMX', 'No te meta\' conmigo, o te quemarás.', 'No te meta\' conmigo, o te quemarás.', 28153),
(155048, 'esMX', 'Pronto eh\'tarás en llamas.', 'Pronto eh\'tarás en llamas.', 28153),
(155047, 'esMX', '¡Oh! ¿Alguien necesita un poco de calor?', '¿Alguien necesita un poco de calor?', 28153),
(155046, 'esMX', 'De regreso a las profundidades que la engendraron.', '', 28153),
(155045, 'esMX', '¡La bestia ha regresado! ¡Rápido, persíguela antes de que cause más daños al muro!', '', 28153),
(155044, 'esMX', '¿Qué? Vol\'jin... No podrías haberte vuelto tan fuerte sin convertirte... en...', '', 28153),
(155043, 'esMX', '¿Crees que deh\'truir mi cuerpo... me impedirá... hacerte pedazo\'?', '', 28153),
(155042, 'esMX', '¿Crees que puedes ganar? Solo demoras tu deh\'tino.', '', 28153),
(155041, 'esMX', 'He aprendido mucho mientra\' observaba a Bwonsamdi torturar mi alma. Te moh\'traré un poco de su estilo de vudú.', '', 28153),
(155040, 'esMX', 'No podrás ocultarlo de mí para siempre. ¡Me vengaré de Vol\'jin y de todo\' los Lanza Negra!', '', 28153),
(155039, 'esMX', '¡Esbirros! Maten a su adalid y tráiganme las ceniza\' de Vol\'jin. ¡AHORA!', '', 28153),
(155038, 'esMX', '¿Dónde? ¿Dónde ocultan a Vol\'jin? ¿Cómo lo han ocultado?', '', 28153),
(155037, 'esMX', '¿Dónde lo tienen oculto, Lanza Negra? ¿Dónde eh\'tá mi viejo amigo?', '', 28153),
(155036, 'esMX', 'Aplah\'ten a lo\' Lanza Negra y encuentren esas cenizas.', '', 28153),
(155035, 'esMX', 'Buh\'quen, esbirros. Encuentren las ceniza\' de Vol\'jin y tráiganmelas.', '', 28153),
(155034, 'esMX', 'Esos insectos asquerosos comen cualquier cosa. Son repulsivos.', '', 28153),
(155033, 'esMX', '¡Los ranishu están apareciendo por todas partes! Espántalos antes de que se conviertan en un problema mayor.', '', 28153),
(155032, 'esMX', 'Así será. Que los vientos te acompañen.', 'Así será. Que los vientos te acompañen.', 28153),
(155031, 'esMX', 'Pudiste guiarme en la dirección correcta. ¿Estarás bien?', 'Pudiste guiarme en la dirección correcta. ¿Estarás bien?', 28153),
(155030, 'esMX', 'Lamento que no hayamos podido ser de más ayuda.', 'Lamento que mi hermano y yo no hayamos podido ayudarte más.', 28153),
(155029, 'esMX', '', '¡Bien hecho! Es bueno tenerte de nueh\'tro lado.', 28153),
(155028, 'esMX', '', 'Hay un nido de arañas hilarena\' cerca de la arena. ¡Necesito que vayas y las elimine\'!', 28153),
(155027, 'esMX', 'Parece que esa arma es de origen gnómico. Sea como sea, nos servirá en la batalla.', '', 28153),
(155026, 'esMX', 'Nuestros marinos encontraron una especie de... arma interesante que podría servirnos, si descubrimos cómo usarla. Pruébala contra la fauna de la zona.', '', 28153),
(155025, 'esMX', '', 'La Compañía Aspafresno tardará semana\' en recuperar todo ese cargamento. ¡Buen trabajo!', 28153),
(155024, 'esMX', '', 'La Compañía Aspafresno eh\'tá causando problemas en las cercanías. Necesito que desbarates sus operacione\'.', 28153),
(155023, 'esMX', '¡Tirar a cien idiotas en una isla llena de armas! ¡Después vendemos entradas para verlos desde zepelines en los cielos!', '¡Tirar a cien idiotas en una isla llena de armas! ¡Después vendemos entradas para verlos desde zepelines en los cielos!', 28153),
(155022, 'esMX', 'Creemos un impuesto a los robots. ¡Y luego creamos robots recolectores de impuestos! ¡Dinero infinito!', 'Creemos un impuesto a los robots. ¡Y luego creamos robots recolectores de impuestos! ¡Dinero infinito!', 28153),
(155021, 'esMX', '¡Lámparas cuadradas! Así no se caerán si las apoyas en la mesa.', '¡Lámparas cuadradas! Así no se caerán si las apoyas en la mesa.', 28153),
(155020, 'esMX', '¡Pequeños sombreros formales para sombreros informales que pueden usarse en funciones formales!', '¡Pequeños sombreros formales para sombreros informales que pueden usarse en funciones formales!', 28153),
(155019, 'esMX', 'Flotatótems: ¡tótems para viajar en barco!', 'Flotatótems: ¡tótems para viajar en barco!', 28153),
(155018, 'esMX', '¡Zapatos con armas! Espera, no... eso ya existe. ¡MEDIAS con armas!', '¡Zapatos con armas! Espera, no... eso ya existe. ¡MEDIAS con armas!', 28153),
(155017, 'esMX', '¡Cohetes reciclables!', '¡Cohetes reciclables!', 28153),
(155016, 'esMX', '¡Un equipo de bombardeos en trineo formado solo por goblins!', '¡Un equipo de bombardeos en trineo formado solo por goblins!', 28153),
(155015, 'esMX', 'Queso con capacidad nuclear.', 'Queso con capacidad nuclear.', 28153),
(155014, 'esMX', '¡Gujas de guerra con sierras dobles! ¡Podríamos vendérselas a los Illidari!', '¡Gujas de guerra con sierras dobles! ¡Podríamos vendérselas a los Illidari!', 28153),
(155013, 'esMX', '¡La Sopor Peridoto, para cuando necesitas una siesta mucho más corta!', '¡La Sopor Peridoto, para cuando necesitas una siesta mucho más corta!', 28153),
(155012, 'esMX', '¡Pinzas para parrilladas tácticas!', '¡Pinzas para parrilladas tácticas!', 28153),
(155011, 'esMX', 'Una historia de amor... ¡sobre un humano y, eh, ¡un jinyu!', 'Una historia de amor... ¡sobre un humano y, eh, ¡un jinyu!', 28153),
(155010, 'esMX', '¡Bien hecho, soldado! Es bueno tenerte de nuestro lado.', '', 28153),
(155009, 'esMX', 'Un pilar... Pero no para sostener el techo, ¡para sostener el suelo!', 'Un pilar... Pero no para sostener el techo, ¡para sostener el suelo!', 28153),
(155008, 'esMX', 'Hay un nido de arañas hilarenas cerca que bloquea el paso al cañón. ¡Necesito que despejes el camino para nuestras fuerzas!', '', 28153),
(155007, 'esMX', '¡Objetos legendarios de azerita! Seguro nadie pensará en eso.', '¡Objetos legendarios de azerita! Seguro nadie pensará en eso.', 28153),
(155006, 'esMX', '¡Carbones de Teldrassil! ¡Para un delicioso olor ahumado de parrillada!', '¡Carbones de Teldrassil! ¡Para un delicioso olor ahumado de parrillada!', 28153),
(155005, 'esMX', '¡Vehículos que andan por el agua en lugar de la tierra!', '¡Vehículos que andan por el agua en lugar de la tierra!', 28153),
(155004, 'esMX', '¡Bardos!', '¡Bardos!', 28153),
(155003, 'esMX', '¡Un silbato que trae a los maestros de vuelo hacia ti!', '¡Un silbato que trae a los maestros de vuelo hacia ti!', 28153),
(155002, 'esMX', '¡Buen trabajo, soldado! ¡Una bestia menos de la que preocuparnos en esta trampa mortal a la que llaman Vol\'dun!', '', 28153),
(155001, 'esMX', '¡Un tipo de cristal arcano que mejora todas tus habilidades! Puede que sea un poco inestable, ¡pero no importa!', '¡Un tipo de cristal arcano que mejora todas tus habilidades! Puede que sea un poco inestable, ¡pero no importa!', 28153),
(155000, 'esMX', 'Un ranishu gigante está aterrorizando el barranco, pero es demasiado feroz para atacarlo directamente. ¡Tendrás que encontrar otra forma de detenerlo!', '', 28153),
(154999, 'esMX', '¡Escopetas de papel higiénico! ¡Piensa en todo el tiempo que podrías ahorrar!', '¡Escopetas de papel higiénico! ¡Piensa en todo el tiempo que podrías ahorrar!', 28153),
(154998, 'esMX', '¡Botes cucheta! Eso dejará más espacio en el océano para más actividades. ¡Pido ir arriba!', '¡Botes cucheta! Eso dejará más espacio en el océano para más actividades. ¡Pido ir arriba!', 28153),
(154997, 'esMX', '¡Goma de mascar reutilizable! Compártela con amigos, tus mascotas, ¡o incluso los extraños!', '¡Goma de mascar reutilizable! Compártela con amigos, tus mascotas, ¡o incluso los extraños!', 28153),
(154996, 'esMX', '¡Fue un trabajo sucio, pero alguien tenía que hacerlo! ¡Prefiero que hayas sido tú!', '', 28153),
(154995, 'esMX', 'Si queremos sobrevivir, debemos encontrar la forma de cultivar en este desierto. Necesitaremos fertilizante... Fíjate qué encuentras.', '', 28153),
(154994, 'esMX', 'Admito que tenía mis dudas, pero nos será realmente útil contra los infieles.', '', 28153),
(154993, 'esMX', 'Tacha ha desenterrado otro tótem zandalari en una de las ruinas. Pruébalo para ver qué puede hacer.', '', 28153),
(154992, 'esMX', '¡Eso sí que fue muy divertido! ¡Reservaré esto para los orcos!', '', 28153),
(154991, 'esMX', 'La Compañía Aspafresno necesitará varias semanas para recuperar todo ese cargamento. ¡Buen trabajo!', '', 28153),
(154990, 'esMX', 'Nuestros exploradores encontraron este antiguo tótem zandalari en una de las ruinas. Veamos qué puede hacer.', '', 28153),
(154989, 'esMX', 'La Compañía Aspafresno mantiene una operación de minería ilegal en las cercanías. Necesito que la interrumpas.', '', 28153),
(154988, 'esMX', 'Las arenas avanzan, pero la vida prevalece. Gracias.', '', 28153),
(154987, 'esMX', 'Los oasis de Vol\'dun son un recurso muy valioso. Debemos cuidarlos con esmero.', '', 28153),
(154986, 'esMX', 'Hay victorias que no se logran en el campo de batalla. Estos suministros nos mantendrán con vida.', '', 28153),
(154985, 'esMX', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg.', '', 28153),
(154984, 'esMX', 'Este oasis nos brindará una ventaja táctica clave para expandirnos en el continente.', '', 28153),
(154983, 'esMX', 'Mi caída es solo un latido en el corazón del abismo infinito.', '', 28153),
(154982, 'esMX', 'Debo admitir que todo resultó mucho mejor de lo que esperaba.', '', 28153),
(154981, 'esMX', 'Nuestros... aliados de siempre en el Puerto de Zem\'lan han ideado un nuevo plan. Ayúdalos, si es que confías en ellos.', '', 28153),
(154980, 'esMX', '¡Ja! ¡Eso les enseñará a no meterse con la Alianza!', '', 28153),
(154979, 'esMX', 'Algunas de nuestras tropas robaron un bote y lo llenaron de armas. ¡Lleva la lucha a estos monstruos no-muertos!', '', 28153),
(154978, 'esMX', '¡Bien hecho! Esos malditos demonios lo pensarán dos veces antes de volver a atacar a la Alianza.', '', 28153),
(154977, 'esMX', 'Esos horribles piratas no-muertos han capturado a algunos de nuestros soldados. Libérenlos. ¡Que nadie quede atrás!', '', 28153),
(154976, 'esMX', '', 'Gracias. Hasta los exiliado\' merecen un mejor deh\'tino que ese.', 28153),
(154975, 'esMX', '', '¡Los pirata\' de Zem\'lan mantienen cautivos a exiliados zandalari! ¡Libérenlos!', 28153),
(154974, 'esMX', 'Los infieles están distraídos. ¡Que les llueva muerte desde el cielo!', '', 28153),
(154973, 'esMX', 'Ah... Volverán a levantarse, lo sé. Pero por ahora podemos disfrutar de un poco de paz.', '', 28153),
(154972, 'esMX', 'Los infieles son muchísimos. Debemos mantenerlos confinados aquí.', '', 28153),
(154971, 'esMX', '¡Gloria a Sethraliss! Ojalá todos los sethrak la recuerden algún día...', '', 28153),
(154970, 'esMX', 'Toma una parte de mi poder y echa a los infieles de estas tierras.', '', 28153),
(154969, 'esMX', '', 'Mi fuerza... ¿Qué has hecho?', 28153),
(154968, 'esMX', '', 'Eh\'te poder... No puedo... moverme...', 28153),
(154967, 'esMX', 'La vida... me abandona...', '', 28153),
(154966, 'esMX', 'No puedo moverme... Ayuda...', '', 28153),
(154965, 'esMX', 'Unnggrrh...', '', 28153),
(154964, 'esMX', '¿Creíh\'te que podías enfrentarte a un dios y salir con vida? ¡MUERE!', '', 28153),
(154963, 'esMX', '¡Más sangre! ¡Debo saciar mi sed!', '', 28153),
(154962, 'esMX', '¡Tu sangre me fortalece!', '', 28153),
(154961, 'esMX', 'El trabajo es basura, ¡me cansé! ¡Voy a entrenar, voy a ser alguien!', 'El trabajo es basura, ¡me cansé! ¡Voy a entrenar, voy a ser alguien!', 28153),
(154960, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t ¡Azerokk se prepara para lanzar |cFFFF0000|Hspell:258622|h[Pulso resonante]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t ¡Azerokk se prepara para lanzar |cFFFF0000|Hspell:258622|h[Pulso resonante]|h|r!', 28153),
(154959, 'esMX', 'Lo único que conseguirás con este grifo es que te arranque la mano, $utonto:tonta;.', 'Lo único que conseguirás con este grifo es que te arranque la mano, $utonto:tonta;.', 28153),
(154956, 'esMX', 'Las sombras crecen. Los elegidos se reúnen. Nuestra hora se avecina.', '', 28153),
(154955, 'esMX', 'Le daré propósito a tu carne.', '', 28153),
(154954, 'esMX', '', 'Mi poder... mi maldición... no puede ser...', 28153),
(154953, 'esMX', 'Si es que... regresas. ', '', 28153),
(154952, 'esMX', 'Cuando regrese, hablaremos del honor... y de cómo aún puede recuperarse.', '', 28153),
(154951, 'esMX', 'Llévenlo a las Mazmorras.', '', 28153),
(154950, 'esMX', 'Tu especie existe para alimentarme.', '', 28153),
(154949, 'esMX', 'En este momento sí.', '', 28153),
(154948, 'esMX', '¡Un Rey de la Alianza no tiene derecho a decidirlo!', '', 28153),
(154947, 'esMX', 'Escúchame. No hay honor en esto.', '', 28153),
(154946, 'esMX', 'Mi padre me dijo una vez que Varok Colmillosauro encarnaba el honor de la Horda...', '', 28153),
(154945, 'esMX', '¡No! ¡Exijo una muerte honorable!', '', 28153),
(154944, 'esMX', '¡Alianza... alto!', '', 28153),
(154940, 'esMX', '', '¡Cuánta tenacidad! Deberían sentirse honrados de haber vivido lo suficiente para enfrentarse a mi orgullo.', 28153),
(154939, 'esMX', 'Todas las fuerzas, ¡dispárenle a esa monstruosidad! ¡Los nagas no atravesarán el muro hoy!', '', 28153),
(154937, 'esMX', '<Hacer cola con mi grupo para una Expedición insular en dificultad mítica.>', '<Hacer cola con mi grupo para una Expedición insular en dificultad mítica.>', 28153),
(154936, 'esMX', '<Hacer cola con mi grupo para una Expedición insular en dificultad heroica.>', '<Hacer cola con mi grupo para una Expedición insular en dificultad heroica.>', 28153),
(154935, 'esMX', '<Hacer cola para una Expedición insular en dificultad mítica.>', '<Hacer cola para una Expedición insular en dificultad mítica.>', 28153),
(154934, 'esMX', '<Hacer cola para una Expedición insular en dificultad heroica.>', '<Hacer cola para una Expedición insular en dificultad heroica.>', 28153),
(154933, 'esMX', 'Ve, caminante de la manada, y levanta una estatua en mi honor en las escaleras de Dazar\'alor. Haz que se conozca la fuerza de la manada y tendrás mi bendición.', '', 28153),
(154932, 'esMX', '', 'Con estos tres pergaminos, puedo facilitar tu viaje hasta aquí.', 28153),
(154931, 'esMX', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t ¡%s se voltea hacia |cFFFF0000$n|r y prepara un |cFFFF0000|Hspell:268403|h[Tajo de vendaval]|h|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se está preparando para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', 28153),
(154930, 'esMX', 'Al menos muero... con los pies... sobre la tierra...', '', 28153),
(154929, 'esMX', '¡Excelente lanzamiento, $Uforastero:forastera;! Te has ganado mi atención.', '', 28153),
(154928, 'esMX', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t¡%s ha quedado |cFFFF0000|Hspell:267702|h[Sepultado]|h|r! ¡Busca señales de forcejeo para encontrarlo!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t¡%s ha quedado |cFFFF0000|Hspell:267702|h[Sepultado]|h|r! ¡Busca señales de forcejeo para encontrarlo!', 28153),
(154927, 'esMX', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t ¡Te han atrapado dentro de una tumba! ¡|cFFFF0000|Hspell:267764|h[Lucha]|h|r para que tus amigos sepan dónde estás!', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t ¡Te han atrapado dentro de una tumba! ¡|cFFFF0000|Hspell:267764|h[Lucha]|h|r para que tus amigos sepan dónde estás!', 28153),
(154926, 'esMX', '¡Debemos regresar al Santuario de los Devotos de inmediato para impedir que el general Jakra\'zet libere a Mythrax!', '', 28153),
(154925, 'esMX', '¡Idiota! ¡Nadie puede controlar a Mythrax!', '', 28153),
(154924, 'esMX', 'Él despertará a Mythrax, ¡y conquistaremos todo Azeroth!', '', 28153),
(154923, 'esMX', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t ¡%s se está preparando para |cFFFF0000|Hspell:267702|h[Sepultar]|h|r a |cFFFF0000$n|r!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t ¡%s se está preparando para |cFFFF0000|Hspell:267702|h[Sepultar]|h|r a |cFFFF0000$n|r!', 28153),
(154922, 'esMX', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se está preparando para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t ¡%s se está preparando para dar un |cFFFF0000|Hspell:268932|h[Salto sísmico]|h|r hacia |cFFFF0000$n|r!', 28153),
(154921, 'esMX', '¡Raagh! ¡Acércate y recibe el castigo por tus crímenes, Korthek!', '', 28153),
(154920, 'esMX', '', 'Estoy aquí para observar. A los Zandalari nos interesan mucho lo\' renegados.', 28153),
(154919, 'esMX', '', 'Te lo aseguro, Clamañublo, el placer es todo mío.', 28153),
(154918, 'esMX', '', 'Trataré de averiguar por qué el camino está cerrado. ¡Intenta convencer a los soldados de que se dispersen!', 28153),
(154917, 'esMX', 'Recojan sus cosas, tontos inservibles. Tenemos asuntos más importantes que atender.', 'Recojan sus cosas, tontos inservibles. Tenemos asuntos más importantes que atender.', 28153),
(154916, 'esMX', 'Lárgate, sabandija.', 'Lárgate, sabandija.', 28153),
(154915, 'esMX', 'Déjame en paz.', 'Déjame en paz.', 28153),
(154914, 'esMX', 'Te tuve piedad.', 'Te tuve piedad.', 28153),
(154913, 'esMX', 'Bah, ya estaba cansado de ti.', 'Bah, ya estaba cansada de ti.', 28153),
(154912, 'esMX', '', '¡Te concentras demasiado en los detalles! ¡Todo estará bien!', 28153),
(154911, 'esMX', '', 'Todo tiene un precio... ¡y estas sabandijas me harán ganar una fortuna! Cuando las envíe de nuevo a Kalimdor, claro.', 28153),
(154910, 'esMX', '', 'Necesitan sangre para sobrevivir. ¿Cómo las alimentarás?', 28153),
(154909, 'esMX', '', '¿Por qué coleccionas alimañas en una caja?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'esMX', 'Abre este paso de inmediato.', 'Abre este paso de inmediato.', 28153),
(154907, 'esMX', 'Veo que la edad solo te ha vuelto más feroz y sabio, Rakjan. Castigaremos a estos infieles por la forma en que te trataron a ti y a tus hermanos.', '', 28153),
(154906, 'esMX', 'Tendrás que pasar sobre mi cadáver para entrar, $uamigo:amiga;.', 'Tendrás que pasar sobre mi cadáver para entrar, $uamigo:amiga;.', 28153),
(154905, 'esMX', '¿Acaso tienes cera en los oídos, $Umuchacho:muchacha;? El valle está cerrado.', '¿Acaso tienes cera en los oídos, $Umuchacho:muchacha;? El valle está cerrado.', 28153),
(154904, 'esMX', 'Una máscara de gas y un bote de añublo, por favor. Quiero ver de qué es capaz esta cosa.', 'Una máscara de gas y un bote de añublo, por favor. Quiero ver de qué es capaz esta cosa.', 28153),
(154903, 'esMX', 'Solo una máscara de gas para mí, por favor.', 'Solo una máscara de gas para mí, por favor.', 28153),
(154902, 'esMX', 'Vuelve a la fila si no quieres meterte en problemas, rata de sentina.', 'Vuelve a la fila si no quieres meterte en problemas, rata de sentina.', 28153),
(154901, 'esMX', 'Sin documentos, no hay entrada. Reglas son reglas.', 'Sin documentos, no hay entrada. Reglas son reglas.', 28153),
(154899, 'esMX', 'Con la fuerte espalda de Ai\'twen, mi estrategia brillante y tu determinación intrépida, somos invencibles.', '', 28153),
(154898, 'esMX', 'Escalaré hasta la cima para asegurarme de que Rakjan no se haya olvidado de mí después de tantos años.', '', 28153),
(154897, 'esMX', '', 'Descansaré cuando dejen de llegar heridos.', 28153),
(154896, 'esMX', '', 'Estoy bien. Estos marineros necesitan mis habilidades.', 28153),
(154895, 'esMX', 'A este ritmo, tú también necesitarás un sanador. No serás de mucha ayuda desde una camilla.', '', 28153),
(154894, 'esMX', 'Te ves cansada, Feorea. Deberías descansar.', '', 28153),
(154893, 'esMX', 'Toma mi bastón y cárgalo con el poder de los pináculos de represión de los infieles.', '', 28153),
(154892, 'esMX', 'Ai\'twen y yo te veremos en el campo minado de Ventura y Cía.', '', 28153),
(154891, 'esMX', '¡Mamá! ¡Meerah y $p nos salvaron!', '¡Mamá! ¡Meerah y $p nos salvaron!', 28153),
(154890, 'esMX', '¡Te dije que Meerah no nos olvidaría! ¡Es la mejor!', '¡Te dije que Meerah no nos olvidaría! ¡Es la mejor!', 28153),
(154889, 'esMX', '', '¡Kiro! ¡Me alegra volver a verte! ¿Tuviste temor? ¿Cómo conseguiste un krolusko? ¿Qué nombre le pusiste? ¿Puedo ponerle un nombre? No muerde, ¿cierto?', 28153),
(154888, 'esMX', 'Luego te contaré las historias, Meerah. Primero, pongamos a nuestra gente a salvo.', '', 28153),
(154887, 'esMX', 'Eso fue... ¡muy divertido!', '', 28153),
(154886, 'esMX', '¡Sube al krolusko y larguémonos de aquí antes de que los infieles envíen refuerzos!', '', 28153),
(154885, 'esMX', '', '¿Qué está pasando? ¡Corazón de vendaval, llévanos allí!', 28153),
(154884, 'esMX', '', 'Comenzaremos la búsqueda en Presabrenna. Al menos puede que encontremos al hermano Pike allí.', 28153),
(154883, 'esMX', '', 'Lord Canto Tormenta gobierna la dinastía, y prácticamente todo el valle. Parece que es la clave de todo esto, pero no ha estado en Boralus desde hace meses.', 28153),
(154882, 'esMX', '', 'Primero debemos buscar aliarnos con la casa Canto Tormenta. Ellos controlan a los maresabios, y los maresabios, controlan la flota.', 28153),
(154881, 'esMX', '', 'Tiemblen ante la sombra del estandarte vulpera, ¡escorias infieles!', 28153),
(154880, 'esMX', 'Necesitarás una máscara de gas para sobrevivir al añublo. Si quieres, también puedes llevarte un bote de añublo y ayudar.', 'Necesitarás una máscara de gas para sobrevivir al añublo. Si quieres, también puedes llevarte un bote de añublo y ayudar.', 28153),
(154879, 'esMX', '', 'Me temo que Kul Tiras no será de gran ayuda para la Alianza hasta que la flota regrese.', 28153),
(154878, 'esMX', '', 'Y nuestro pueblo encadenado debe saber que no los hemos abandonado.', 28153),
(154877, 'esMX', '', 'Mejor. Deben saber quién los matará.', 28153),
(154876, 'esMX', 'Esto es arriesgado, Nisha. Los infieles sabrán que estamos aquí.', '', 28153),
(154875, 'esMX', 'Bien hecho. Ese exánime atacaba a nuestros exploradores con sus fuerzas. Ahora podremos concentrarnos en la Horda.', '', 28153),
(154874, 'esMX', 'En Drustvar hay brujas y parece que en Nazmir, exánimes. Extermina a su ejército y a lo que sea que le esté dando poder.', '', 28153),
(154873, 'esMX', '', '¡Nisha se alegrará tanto de verte! Está matando a los sethrak en el cráter... como siempre.', 28153),
(154872, 'esMX', 'Impresionante, aunque me he enterado de que los gnomos se niegan a trabajar con tecnología de origen goblin. Al menos ya conocemos su poder.', '', 28153),
(154871, 'esMX', 'Hemos incautado un dispositivo experimental de los goblins. Pruébalo con ese ejército de trols de sangre para tener una idea de su poder.', '', 28153),
(154870, 'esMX', 'Presiento que los nagas tienen más planes que esos. No te descuides.', '', 28153),
(154869, 'esMX', '¡Nagas! Nos han atormentado durante demasiado tiempo. Acaba con sus actividades.', '', 28153),
(154866, 'esMX', 'No presenciaba una ferocidad semejante contra la Horda desde la Tercera Guerra. Buen trabajo.', '', 28153),
(154864, 'esMX', 'Luchaste bien contra la Horda. El pueblo de Kul Tiras sabrá de tu valentía.', '', 28153),
(154863, 'esMX', 'Buen trabajo. Esperemos que este conflicto termine mejor que la Segunda Guerra.', '', 28153),
(154861, 'esMX', '', 'Tienen a los niños en el cráter de allá abajo. ¡Ten cuidado!', 28153),
(154859, 'esMX', '¡Bien hecho! ¡Nada detendrá a la Horda!', '', 28153),
(154858, 'esMX', 'Han asesinado a varios exploradores que combatían a la Horda en esta área. Encárgate de detener lo que sea que estén haciendo.', '', 28153),
(154857, 'esMX', '¡Bien hecho! Creo que podría aprender una o do\' cosa\' de ti, colega.', '', 28153),
(154856, 'esMX', 'Otro enemigo muerto y pronto otro ocupará su lugar. Pero por ahora te merece\' un descanso.', '', 28153),
(154855, 'esMX', '', 'Llamaré a Corazón de vendaval. Hay una percha en el puerto oriental donde podemos reunirnos.', 28153),
(154854, 'esMX', '¡Ah, victoria! ¡Dulce victoria, colega!', '', 28153),
(154853, 'esMX', 'Durante la Tercera Guerra me familiaricé con las tácticas de la Horda. Parece que están usando una peligrosa. Derríbalos.', '', 28153),
(154852, 'esMX', '¡Jaja! No sabía contra quién se enfrentaba, ¿verdad?', '', 28153),
(154851, 'esMX', 'Las operaciones de la Horda me recuerdan a algunas de sus tácticas de la Segunda Guerra. Tenemos que detenerlos antes de que cumplan con su cometido.', '', 28153),
(154850, 'esMX', '¡Eso fue impresionante, colega!', '', 28153),
(154848, 'esMX', 'Hay un alma poderosa cerca. Pronto, ¡acaba con ella!', '', 28153),
(154846, 'esMX', 'Un enemigo se oculta cerca. ¡Matémoh\'lo!', '', 28153),
(154845, 'esMX', 'En nombre de la Séptima Legión, te agradezco por luchar contra la Horda.', '', 28153),
(154843, 'esMX', 'La derrota de la Horda permitirá el avance de la Séptima Legión. ¡Bien hecho!', '', 28153),
(154842, 'esMX', 'El rey Anduin sabrá de tu valentía frente a la Horda.', '', 28153),
(154838, 'esMX', 'Mis exploradores han informado que la Horda avanza cerca de tu ubicación. Son vulnerables a una emboscada. ¡Destrúyelos!', '', 28153),
(154836, 'esMX', 'Hemos recibido noticias de un enorme contingente de la Horda aquí cerca. ¡Es hora de atacar!', '', 28153),
(154833, 'esMX', 'Hay un objetivo cerca, ¡ataca rápido!', '', 28153),
(154832, 'esMX', 'La Séptima Legión ha descubierto fuerzas de la Horda cerca. ¡Tu tarea es desbaratar sus planes!', '', 28153),
(154831, 'esMX', 'Hay otra amenaza cerca. Ya sabe\' qué hacer.', '', 28153),
(154830, 'esMX', 'Los espíritu\' me indican que hay un enemigo poderoso en el área. Deberíamo\' matarlo... antes de que se convierta en una amenaza.', '', 28153),
(154829, 'esMX', 'Una amenaza poderosa acecha cerca. ¡Elimínala!', '', 28153),
(154828, 'esMX', '¡Buen trabajo! ¿Has pensado en unirte a la Séptima Legión? ¡Alguien como tú sería muy útil!', '', 28153),
(154827, 'esMX', 'Excelente trabajo. ¡Por el rey Anduin! ¡Por la Alianza!', '', 28153),
(154826, 'esMX', 'Hoy le has prestado un servicio muy valioso a la Séptima Legión.', '', 28153),
(154825, 'esMX', 'Tienes mi agradecimiento, y el de todos los soldados de la Séptima Legión.', '', 28153),
(154824, 'esMX', 'Tu valentía llegará a oídos del rey Anduin, lo prometo.', '', 28153),
(154823, 'esMX', 'Nuestros exploradores nos han informado que un enemigo poderoso ronda tu posición. Elimínalo.', '', 28153),
(154822, 'esMX', 'La Séptima Legión ha recibido órdenes de eliminar a un objetivo cerca de tu posición.', '', 28153),
(154821, 'esMX', 'Deberían ser más cuidadosos. No estaremos siempre ahí para ayudarlos. Gracias, adalid.', '', 28153),
(154820, 'esMX', '¡Un equipo de investigación ha quedado atrapado en manos de los no-muertos! ¡Ayúdalos antes de que sea demasiado tarde!', '', 28153),
(154819, 'esMX', 'Es nuestro turno. Es hora de poner fin a G\'huun.', '', 28153),
(154818, 'esMX', 'Ugh, ¿es un cadáver reanimado? Devolvámoslo a la tierra.', '', 28153),
(154817, 'esMX', 'La maldad de ese trol se nota a la legua. ¿Qué trama Zul?', '', 28153),
(154816, 'esMX', '...', '', 28153),
(154815, 'esMX', '...', '', 28153),
(154814, 'esMX', '...', '', 28153),
(154813, 'esMX', '...', '', 28153),
(154812, 'esMX', '...', '', 28153),
(154811, 'esMX', '...', '', 28153),
(154810, 'esMX', '...', '', 28153),
(154809, 'esMX', '...', '', 28153),
(154808, 'esMX', '¡Te faltó uno!', '', 28153),
(154807, 'esMX', '', 'Este complejo experimenta con formas de vida diversas para encontrar la solución a la corrupción de los dioses antiguos.', 28153),
(154806, 'esMX', '¡Agg! ¿¡Qué rayos es eso!?', '', 28153),
(154805, 'esMX', '...', '', 28153),
(154804, 'esMX', 'Había oído hablar de los esbirros de N\'zoth, pero jamás creí que vería uno. Y espero que sea la última vez.', '', 28153),
(154803, 'esMX', 'Eso estuvo cerca. Si nos hubiese derrotado, no sé a cuántos habría infectado.', '', 28153),
(154802, 'esMX', 'Buen plan. Aprovechemos la ocasión e investiguemos qué otros secretos han escondido los titanes.', '', 28153),
(154801, 'esMX', '...', '', 28153),
(154800, 'esMX', '¡Agg! No tenemos tiempo. Encarguémonos de G\'huun antes de que su podredumbre empeore.', '', 28153),
(154799, 'esMX', '¿Encontraron la respuesta?', '', 28153),
(154798, 'esMX', 'Eso explica los trols de sangre, ¿pero por qué los titanes mantendrían con vida a un dios antiguo?', '', 28153),
(154797, 'esMX', 'Dichosos los ojos que los ven. Según parece, estamos en un complejo de investigación.', '', 28153),
(154796, 'esMX', '¡Sí! ¡Funcionó! Esta tecnología no es tan difícil si tienes talento.', '', 28153),
(154795, 'esMX', '¡Y van doce veces!', '', 28153),
(154794, 'esMX', '¿Qué?! ¡No! ¡Las malditas puertas están selladas! Ah... ¡Rompe cosas hasta que se abran!', '', 28153),
(154793, 'esMX', 'Un segundo. Abriré las puertas.', '', 28153),
(154792, 'esMX', '¡Jaja! ¡Lo lograste! Dame un segundo. Creo que he accedido a una especie de custodio que maneja este complejo.', '', 28153),
(154791, 'esMX', 'Acabo de convertirme en Leyenda.', '', 28153),
(154789, 'esMX', 'La batalla continúa. ¡No dejes de combatir a nuestros enemigos!', '', 28153),
(154788, 'esMX', 'Hemos avistado un objetivo importante cerca. Necesitamos que lo aniquiles de inmediato.', '', 28153),
(154787, 'esMX', 'Hay un enemigo poderoso cerca. Elimínalo. ¡Sin piedad!', '', 28153),
(154780, 'esMX', 'Listo para la batalla.', 'Lista para la batalla.', 28153),
(154779, 'esMX', '', '¡Torcanata! ¡Ja, ja!', 28153),
(154777, 'esMX', '', '¡Hoy es la Torcanata! Si tú quiere\' participar, toma una antorcha y prepárate para correr.', 28153),
(154774, 'esMX', '', 'Adalid, parece que te estás ganando la confianza de los zandalari. Debo atender otras obligaciones. Buena suerte.', 28153),
(154772, 'esMX', '', 'Oculeth, fíjate qué puedes hacer con el sistema de portales de aquí. Necesitaremos enviar suministros a las capitales de la Horda.', 28153),
(154770, 'esMX', 'Encuéntrame en la Caída de Bwoljin lo antes posible, $p. Nos escabulliremos en la fortaleza de Korthek.', '', 28153),
(154769, 'esMX', '', 'La princesa Talanji fue tan amable que nos informó sobre una vieja red de portales a la que tal vez podamos acceder.', 28153),
(154768, 'esMX', '', 'Vengan a verme cuando estén listos para acabar con la flota de Aspafresno.', 28153),
(154767, 'esMX', '', 'Hicieron un buen trabajo, héroes, pero Boralus aún corre peligro.', 28153),
(154766, 'esMX', 'Vuelve al trabajo. Vienen conmigo.', 'Vuelve al trabajo. Vienen conmigo.', 28153),
(154765, 'esMX', 'No se permiten forasteros en los archivos, hermano.', 'No se permiten forasteros en los archivos, hermano.', 28153),
(154764, 'esMX', 'Estaba allí parado en la playa, asolado por unos giblins nefastos, cuando... ¡apareció $Uun héroe:una heroína;! ¡Oh! ¡Hola de nuevo, $n!', '', 28153),
(154763, 'esMX', '¡Consigue esos pergaminos! Yo tomaré la... ruta escénica... para volver al campamento y compartir la información que has recabado.', '', 28153),
(154762, 'esMX', 'No importa lo que hagan, la Alianza está condenada a la derrota.', '', 28153),
(154761, 'esMX', 'Han llegado algunos campeones de la Alianza y quieren salvar la ciudad. Acaben con sus esfuerzos.', '', 28153),
(154760, 'esMX', 'Desataremos el caos en la Alianza con estas municiones.', '', 28153),
(154759, 'esMX', 'Las fuerzas de Aspafresno están usando artillería de azerita para atacar la ciudad. ¡Reclama esas armas para la Horda!', '', 28153),
(154758, 'esMX', 'Sin sus oficiales, los kultiranos retrocederán hasta el mar.', '', 28153),
(154757, 'esMX', 'Un oficial kultirano intenta reunir una defensa. Elimínalos del campo de batalla.', '', 28153),
(154756, 'esMX', '', 'Buen trabajo. ¡Le han demostrado a la Horda que ningún enemigo capturará Boralus!', 28153),
(154755, 'esMX', '', '¡Parece que la Horda ha decidido aprovechar el asedio y saquea la ciudad! ¡No permitan que vacíen Boralus!', 28153),
(154754, 'esMX', '', 'Bien hecho. Aspafresno aprendió que los mercenarios no están a tu altura.', 28153),
(154753, 'esMX', '', 'Uno de los mercenarios de Aspafresno está causando caos en la ciudad. ¡Detenlo!', 28153),
(154752, 'esMX', '', 'Bien hecho. Los únicos que merecen los grilletes son esos criminales.', 28153),
(154751, 'esMX', '', '¡Los piratas están esclavizando civiles! ¡Acaben con esto!', 28153),
(154750, 'esMX', 'Gorak Tul... se acerca...', '', 28153),
(154749, 'esMX', 'Todos en Kul Tiras sufrirán. ¡Tú serás la primera víctima!', '', 28153),
(154748, 'esMX', '¡Idiota! ¡Morirás aullando!', '', 28153),
(154747, 'esMX', 'Oou ph\'magg an\'qov nuq.', '', 28153),
(154746, 'esMX', '¡Ywaq ongg uul\'gwa no AN\'zig!', '', 28153),
(154745, 'esMX', '¡Arwi ryiu yrr oou qam!', '', 28153),
(154744, 'esMX', 'AN\'zig wgah qam za zyqtahg...', '', 28153),
(154743, 'esMX', '¡AN\'zig wgah zzof!', '', 28153),
(154742, 'esMX', '¡Ywaq fhssh wgah qam!', '', 28153),
(154741, 'esMX', '¡Uulg\'ma zyqtahg yrr!', '', 28153),
(154740, 'esMX', '¡Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz!', '', 28153),
(154739, 'esMX', '¡Y ahora vete mientras puedas! Seguramente los demás están siguiendo tus movimientos.', '¡Y ahora vete mientras puedas! Seguro los demás están siguiendo tus movimientos.', 28153),
(154738, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Machaque taladrante]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Machaque taladrante]|h|r!', 28153),
(154737, 'esMX', '¡Og qam shfk wgah iiqaah halahs ma!', '', 28153),
(154736, 'esMX', 'Busca al hermano Pike en Presabrenna. Entrégale este colgante. Nuestro trabajo acaba de comenzar, y necesitará tu ayuda.', 'Busca al hermano Pike en Presabrenna. Entrégale este colgante. Nuestro trabajo acaba de comenzar, y necesitará tu ayuda.', 28153),
(154735, 'esMX', '¡Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma!', '', 28153),
(154734, 'esMX', 'Nuestro pueblo sigue un camino oscuro. Pero algunos de los nuestros han sembrado semillas de resistencia.', 'Nuestro pueblo sigue un camino oscuro. Pero algunos de los nuestros han sembrado semillas de resistencia.', 28153),
(154733, 'esMX', '¡Zuq ag\'xig ka\'kar za wgah!', '', 28153),
(154732, 'esMX', '¡Puul qi\'plahf ni oou bormax!', '', 28153),
(154731, 'esMX', '¡Xith wgah!', '', 28153),
(154729, 'esMX', '¡Naz raqul!', '', 28153),
(154728, 'esMX', '¡I wgah far\'al zuq ni shn!', '', 28153),
(154727, 'esMX', 'La flota no está perdida. Está atrapada en una tormenta sobrenatural.', 'La flota no está perdida. Está atrapada en una tormenta sobrenatural.', 28153),
(154726, 'esMX', '¡Zuq wgah qam n\'lyeth!', '', 28153),
(154725, 'esMX', '¡Zuq ag\'xig gag wgah naggwa\'fssh!', '', 28153),
(154724, 'esMX', '¡Zuq ag\'xig bormax oou iiqaath!', '', 28153),
(154723, 'esMX', '¿Estás bien? Debí suponer que Wade sería víctima de la sombra que se ha apoderado de la Casa Canto Tormenta.', '¿Estás bien? Debí suponer que Wade sería víctima de la sombra que se ha apoderado de la Casa Canto Tormenta.', 28153),
(154722, 'esMX', '', '¿Qué quieres decir con \"peligro\"?', 28153),
(154721, 'esMX', 'Sí, hermano.', 'Sí, hermano.', 28153),
(154720, 'esMX', 'Que no entre nadie. Tengo invitados.', 'Que no entre nadie. Tengo invitados.', 28153),
(154719, 'esMX', 'No tienes idea del peligro en el que te encuentras.', '', 28153),
(154718, 'esMX', 'Sígueme. No levantes la vista.', '', 28153),
(154717, 'esMX', 'Nuestras fortificaciones aún están débiles. ¡Rápido, detengamos el avance de la Horda antes de que se acerquen!', '', 28153),
(154716, 'esMX', 'Stromgarde aún está débil. No sobrevivirá a un ataque directo. ¡Destruye a la vanguardia de la Horda antes de que se acerque!', '', 28153),
(154715, 'esMX', '¡Ah! ¡Una gran muestra de respeto para Paku!', '', 28153),
(154714, 'esMX', '¡Envíen a nuestra\' fuerzas! ¡Tenemo\' que aplastar a estos insecto\' de la Alianza antes de que se propaguen!', '', 28153),
(154713, 'esMX', '', '¡Es hora! Asciendan los escalone\' de Zanchul y ofrezcan sus respeto\' a nuestros loa. ¡Con su favor, Zandalar triunfará! ¡Por Gonk!', 28153),
(154712, 'esMX', '', '¡Desplieguen a nuestras fuerzas, ahora! ¡No podemos permitir que la Alianza asegure una posición!', 28153),
(154711, 'esMX', '¡Preparen sus armas! ¡Es hora de luchar!', '', 28153),
(154710, 'esMX', '¡Envíen a nuestras fuerzas! ¡Las murallas de Stromgarde se derrumbarán ante el poder de la Horda!', '', 28153),
(154709, 'esMX', 'El bastión necesita refuerzos. ¡Expulsen a sus fuerzas antes de que se acerquen demasiado!', '', 28153),
(154708, 'esMX', 'No tardes. ¡Lord Canto Tormenta necesita esos mapas en el Santuario de la Tormenta cuanto antes!', '', 28153),
(154707, 'esMX', '¡Envíen a nuestras tropas! Haremos pedazos su base.', '', 28153),
(154706, 'esMX', '', 'Los maresabios tienen las bibliotecas más completas del mundo. Seguramente ahí está nuestro archivista.', 28153),
(154705, 'esMX', '', '¡La Alianza marcha sobre Ar\'gorok! ¡Debemos expulsarlos antes de que lleguen al bastión!', 28153),
(154704, 'esMX', '¡Soldados de la Alianza! ¡Que caigan todos!', '', 28153),
(154703, 'esMX', 'Soldados de la Liga, ¡a la carga!', '', 28153),
(154702, 'esMX', '¡Horda, a la batalla! ¡Aplasten a esos cobardes moradores de castillos antes de que atraviesen nuestras puertas!', '', 28153),
(154701, 'esMX', '', '¡Bola curva! ¡Bola curva!', 28153),
(154700, 'esMX', '¡Oh! ¡Bola curva! ¡Bola curva!', '', 28153),
(154699, 'esMX', '', 'Esto no me gusta nada. Salgamos de aquí.', 28153),
(154698, 'esMX', '¡Ve a los archivos con ese tonto de Alen! O te usaré para estabilizar la falla.', '', 28153),
(154697, 'esMX', '¡Trabajen más duro, tontos! ¡Antes de que perdamos el control!', '', 28153),
(154696, 'esMX', '', 'Bueno... ¡Puede que lo hagamos!', 28153),
(154695, 'esMX', '', '¿Por qué no molestas a Alen si solo viniste a perder el tiempo?', 28153),
(154694, 'esMX', '', 'Revela tu alma a las mareas. ¡Sus susurros te guiarán a la verdad!', 28153),
(154693, 'esMX', 'Plantando semillas', 'Plantando semillas', 28153),
(154692, 'esMX', '', '¡Gilneanos, carguen sus cañones! ¡Avancen!', 28153),
(154691, 'esMX', 'Ehm... ¡Damas y caballeros, enciendan los motores! ¡Ataquen!', '', 28153),
(154690, 'esMX', '¡Fusileros! ¡Preparen las armas! ¡Avancen!', '¡Fusileros! ¡Preparen las armas! ¡Avancen!', 28153),
(154689, 'esMX', '', 'Podemos garantizar el paso de tu navío, por un precio.', 28153),
(154688, 'esMX', '', 'Qué tragedia. Quizás deberíamos dejar de celebrar bodas aquí.', 28153),
(154687, 'esMX', '', '¡Han arruinado lo que iba a ser una celebración maravillosa! ¡Elimina a los monstruos responsables de esto y salva a los invitados de la boda!', 28153),
(154686, 'esMX', '', 'Entonces... ¿supongo que eso es un no?', 28153),
(154685, 'esMX', '', 'Eres casi tan insoportable como el hermano Alen.', 28153),
(154684, 'esMX', '', 'Ey, tú, ¿quién está a cargo?', 28153),
(154683, 'esMX', 'Pff.', 'Mmm.', 28153),
(154682, 'esMX', '¡Drenen sus heridas purulentas y canten en agonía!', '', 28153),
(154681, 'esMX', '¡No rechacen la locura! ¡Devórenla!', '', 28153),
(154680, 'esMX', '¡Entréguense a la belleza de la descomposición!', '', 28153),
(154679, 'esMX', '¡Te convertiré en cenizas!', '', 28153),
(154678, 'esMX', '¡Xalzaix tiene sed de aniquilación!', '', 28153),
(154677, 'esMX', '¡No sobrevivirás!', '', 28153),
(154676, 'esMX', '¡No pueden huir de la destrucción!', '', 28153),
(154675, 'esMX', '¡No pueden escapar de las sombras!', '', 28153),
(154674, 'esMX', '¡Exterminio!', '', 28153),
(154673, 'esMX', '¡Desintegración!', '', 28153),
(154672, 'esMX', 'No puedes resistirte a mi llamado.', '', 28153),
(154671, 'esMX', '¡Entrégate a la plaga!', '', 28153),
(154670, 'esMX', 'Nada detendrá a G\'huun...', '', 28153),
(154669, 'esMX', 'La podredumbre lo consume todo.', '', 28153),
(154668, 'esMX', 'Tu cuerpo le pertenece a G\'huun.', '', 28153),
(154667, 'esMX', '¡Más comida para la podredumbre!', '', 28153),
(154666, 'esMX', '¡G\'huun se alzará!', '', 28153),
(154665, 'esMX', '¡Su mundo acabará!', '', 28153),
(154664, 'esMX', 'Tu descomposición es inevitable.', '', 28153),
(154663, 'esMX', '¿Sientes eso en tu garganta, en tu mente? Siempre he estado a tu lado.', '', 28153),
(154662, 'esMX', 'Toda la vida se marchita. Acepta mi regalo y transfórmate.', '', 28153),
(154661, 'esMX', '', 'Motor de reoriginación restaurado. Acceso a la bóveda concedido.', 28153),
(154660, 'esMX', '', 'Consola activada. Reiniciando salvaguardias.', 28153),
(154659, 'esMX', '¡Ah! Una cosa más. Bueno, un par.', '', 28153),
(154658, 'esMX', '', 'Primera consola activada. Restableciendo matriz de energía.', 28153),
(154657, 'esMX', '', 'G\'huun exterminado. No se detectan muestras viables.', 28153),
(154656, 'esMX', '', 'Niveles de corrupción seguros. Integridad del sistema restaurada.', 28153),
(154655, 'esMX', 'Finalmente, cuando el planeta explote como un forúnculo, mi podredumbre se propagará por el cosmos.', '', 28153),
(154654, 'esMX', 'Esparcirán mi pestilencia, y un quiste pútrido y vasto cubrirá el mundo.', '', 28153),
(154653, 'esMX', 'Huéspedes ansiosos. Serán los primeros en recibir mi regalo.', '', 28153),
(154652, 'esMX', 'Sin titanes y sin sellos, comienza la era de la podredumbre.', '', 28153),
(154651, 'esMX', '', '¡Esa fue por traer la deh\'trucción a Dazar\'alor, criatura vil!', 28153),
(154650, 'esMX', '', 'Ahora nos toca a nosotros. Acabaremo\' con la enfermedad de G\'huun.', 28153),
(154649, 'esMX', '', 'Advertencia: peligro grave de contaminación a partir de este punto. Los protocolos de cuarentena me impiden proceder.', 28153),
(154648, 'esMX', '¡Perfecto, $p! Tenemos minas más que suficientes para atacar a Ventura y Cía.', '', 28153),
(154647, 'esMX', '', 'No importa cómo regresó. Mi cuchillo lo devolverá al abismo.', 28153),
(154646, 'esMX', 'Veo muchas minas para elegir.', '', 28153),
(154645, 'esMX', '', 'Los análisis indican niveles altos de corrupción. Hipótesis: G\'huun reanimó y fortaleció a este espécimen. Pruebas adicionales requeridas.', 28153),
(154644, 'esMX', '', '¡¿Zul?! ¿Cómo puede eh\'tar vivo? ¡Lo vi morir a manos de mi padre!', 28153),
(154643, 'esMX', '¡Estas minas no están diseñadas para detectar tortugas! Podemos recogerlas sin riesgo.', '', 28153),
(154642, 'esMX', '', 'Parece que te faltó uno.', 28153),
(154641, 'esMX', '', 'Las pruebas se enfocaban en la capacidad de la corrupción de G\'huun para reanimar tejidos muertos. Los resultados fueron inconclusos, y los especímenes se destruyeron.', 28153),
(154640, 'esMX', '', 'Observación acertada. Este complejo ha realizado numerosos experimentos con loa en busca de una solución para la corrupción de los dioses antiguos.', 28153),
(154639, 'esMX', '', '¡¿Qué es eh\'ta criatura?! Parece que era un loa.', 28153),
(154638, 'esMX', '', 'Si esa cosa era un esbirro de G\'huun, debemo\' detenerlo antes de que un ejército de ellos alcance la superficie.', 28153),
(154637, 'esMX', '', 'Error. Error en disco. Corriente de datos corruptos desplegada.', 28153),
(154636, 'esMX', '', 'Secuencia de arranque iniciada.', 28153),
(154635, 'esMX', '', 'Preséntense en la plataforma médica para la extracción neuronal y la recolección de tejido cerebral.', 28153),
(154634, 'esMX', '', 'El análisis de las cortezas cerebrales indica que todos los individuos presentes han interactuado con especímenes de dioses antiguos.', 28153),
(154633, 'esMX', '', 'Cualquier información sobre sus experiencias previas puede ayudar en la investigación del complejo.', 28153),
(154632, 'esMX', '', 'El análisis de sus cortezas cerebrales indica que algunos de ustedes han interactuado con dioses antiguos.', 28153),
(154631, 'esMX', '', 'Y 950 mil millones de norgabytes de listas de música y autorretratos.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'esMX', '', 'Setenta y cinco norgabytes de cada compuesto químico existente.', 28153),
(154629, 'esMX', '', 'Estos discos contienen 50 norgabytes de biodatos de formas de vida conocidas en todo el cosmos.', 28153),
(154628, 'esMX', '', 'Bienvenidos a la bóveda de datos, una colección exhaustiva de conocimiento titánico.', 28153),
(154627, 'esMX', 'Luchas contra lo inevitable. Mi plaga es implacable. Ya te ha infectado.', '', 28153),
(154626, 'esMX', '', 'Si esa cosa nos hubiese derrotado, habría infectado toda la vida en la superficie.', 28153),
(154625, 'esMX', 'Ah, $ubienvenido:bienvenida;. Los visitantes son cada vez más raros estos días, en especial en los archivos.\n\n¿En qué puedo ayudarte?', 'Ah, $ubienvenido:bienvenida;. Los visitantes son cada vez más raros estos días, en especial en los archivos.\n\n¿En qué puedo ayudarte?', 28153),
(154624, 'esMX', '', 'Alerta. Contención viral quebrantada. Se acerca un espécimen contaminado. Riesgo de infección inminente.', 28153),
(154623, 'esMX', '', 'Este laboratorio alberga miles de las cepas virales más peligrosas del cosmos, organizadas alfabéticamente para facilitar el acceso.', 28153),
(154622, 'esMX', '', 'Bienvenidos al ala de ecología viral.', 28153),
(154621, 'esMX', '', 'Debes mantener Palabra de poder: escudo activo siempre para beneficiarte con Contrición.', 28153),
(154620, 'esMX', 'Debes mantener siempre activo Palabra de poder: escudo para beneficiarte con Contrición.', '', 28153),
(154619, 'esMX', '', 'Lanza Palabra de poder: escudo sobre ti mismo y luego inflige daño al muñeco de prueba para curar tus heridas.', 28153),
(154618, 'esMX', 'Lanza Palabra de poder: escudo sobre ti mismo y luego inflige daño al muñeco de práctica para curar tus heridas.', '', 28153),
(154617, 'esMX', '', 'Cuando inflijas daño a un enemigo, todos los que estén afectados por tu Contrición sanarán.', 28153),
(154616, 'esMX', 'Cuando inflijas daño a un enemigo, todos los que estén afectados por tu Contrición sanarán.', '', 28153),
(154615, 'esMX', '', 'Algunos hechizos, como Palabra de poder: escudo, aplican Contrición en tu objetivo.', 28153),
(154614, 'esMX', '¿Puedes decirme algo sobre la flota perdida?', '¿Puedes decirme algo sobre la flota perdida?', 28153),
(154613, 'esMX', 'Algunos hechizos, como Palabra de poder: escudo, aplican Contrición en tu objetivo.', '', 28153),
(154612, 'esMX', 'Tenemos que convencer a nuestra Jefa de guerra. Necesito tu ayuda. Vamos.', '', 28153),
(154611, 'esMX', 'Tal vez es hora de cobrarnos una vieja deuda. Así, quizá logremos incorporar soldados leales a las filas de la Horda.', '', 28153),
(154610, 'esMX', '$n, creo que amas a la Horda tanto como yo. Pero si no actuamos, me temo que no sobreviviremos a esta guerra.', '', 28153),
(154609, 'esMX', '', 'Tenemos un plan: activar las consola\' y acabar con la plaga de G\'huun de una vez por toda\'.', 28153),
(154608, 'esMX', '', 'Si activan todas, obtendrán acceso a la bóveda de G\'huun, donde podrán purgar al espécimen activando el motor de reoriginación.', 28153),
(154607, 'esMX', '', 'Para destruir al espécimen, deben reactivar las bóvedas de consolas dispersas por esta ala.', 28153),
(154606, 'esMX', '', '¡No tenemo\' tanto tiempo! ¡Debemo\' detener a G\'huun ahora!', 28153),
(154605, 'esMX', '', 'Negativo. Datos inconclusos. Ensayos de investigación alternativos en curso. Se aplicarán en 2,364 ciclos.', 28153),
(154604, 'esMX', '¡Uff! ¡Es muy, muy potente!', '', 28153),
(154603, 'esMX', '', '¿Y has encontrado la reh\'puesta?', 28153),
(154602, 'esMX', 'Ahora la chispa... Te recomiendo retroceder.', '', 28153),
(154601, 'esMX', '¿Quizá podamos hacer volar el candado? Échale un poco de pólvora.', '', 28153),
(154600, 'esMX', '', 'La recolección de datos es fundamental para combatir a los dioses antiguos. Es posible que la biología singular de G\'huun esconda la respuesta para eliminar su amenaza.', 28153),
(154599, 'esMX', '', '¡¿Has mantenido a esa abominación con vida?! ¿Por qué?', 28153),
(154598, 'esMX', '', 'Designación: Uldir. Este complejo se diseñó para contener y estudiar a la entidad conocida como G\'huun.', 28153),
(154597, 'esMX', '', '¿Qué es eh\'te lugar?', 28153),
(154596, 'esMX', '', 'Sistemas del complejo en peligro. Procedan con cautela.', 28153),
(154595, 'esMX', '', '¡Las puertas eh\'tán cerradas! Apaguen esa máquina... ¡o nos reducirá a cenizas!', 28153),
(154594, 'esMX', '', 'Alerta. Formas de vida contaminadas detectadas. Incineradores activados.', 28153),
(154593, 'esMX', '', 'Ah... Ella debe ser el motivo por el que la corrupción aún no se ha apoderado de eh\'te lugar.', 28153),
(154592, 'esMX', '', 'Soy la Matrona del Afán, Directora Radical de Estudios. Designación: M.A.D.R.E.', 28153),
(154591, 'esMX', '', '¡Por la Horda!', 28153),
(154590, 'esMX', '', '¿Qué fue esa voz?', 28153),
(154589, 'esMX', '', '¡Por la Horda!', 28153),
(154588, 'esMX', '¡Lok-tar ogar! ¡Por la Horda!', '', 28153),
(154587, 'esMX', '', 'Espécimen virulento eliminado. Abriendo la cámara de descontaminación.', 28153),
(154586, 'esMX', '', 'Acepto tu lealtad, Señora suprema. Tu pueblo será bienvenido dentro de las puertas de Orgrimmar.', 28153),
(154585, 'esMX', '', 'Draenor ha caído, pero construiremos un nuevo hogar en Azeroth. ¡Sus enemigos ahora son nuestros enemigos!', 28153),
(154584, 'esMX', 'Echando pólvora', 'Echando pólvora', 28153),
(154583, 'esMX', '', 'Eitrigg y tu adalid demostraron su coraje y nobleza. Si ellos representan el propósito de la Horda, con gusto lucharemos a su lado.', 28153),
(154582, 'esMX', '', '¡¿Taloc sobrevivió al ataque del M.I.D.A.S.?! ¡Esa monstruosidad no puede separarno\' de G\'huun!', 28153),
(154581, 'esMX', 'Bwonsamdi...', 'Tan lejo\' de casa...', 28153),
(154580, 'esMX', 'Sé que estás molesta, cariño, pero hay monstruos de verdad. Tenemos que irnos.', 'Sé que estás molesta, cariño, pero hay monstruos de verdad. Tenemos que irnos.', 28153),
(154578, 'esMX', '', '¡El honor es todo para nosotros! No nos tomamos este juramento a la ligera, Jefa de guerra.', 28153),
(154577, 'esMX', 'Podemos comprar otro pastel, pero tenemos que irnos.', 'Podemos comprar otro pastel, pero tenemos que irnos.', 28153),
(154576, 'esMX', 'Sé que aún sigues enfadada, pero realmente tenemos que irnos, cariño.', 'Sé que aún sigues enfadada, pero realmente tenemos que irnos, cariño.', 28153),
(154575, 'esMX', 'Cariño, tenemos que irnos.', 'Cariño, tenemos que irnos.', 28153),
(154574, 'esMX', '', 'Eitrigg me ha contado sobre la fuerza de tu pueblo. Confío en que son tan honorables como él, ¿verdad?', 28153),
(154572, 'esMX', '¡Arruinaste mi vestido! ¡Era el vestido perfecto! ¡Hecho con tela importada de Quel\'Thalas! ¡El velo era de mi madre! ¡Cómo te atreves!', '¡Arruinaste mi vestido! ¡Era el vestido perfecto! ¡Hecho con tela importada de Quel\'Thalas! ¡El velo era de mi madre! ¡Cómo te atreves!', 28153),
(154570, 'esMX', 'Nuestra misión fue un éxito, Jefa de guerra. La Señora suprema Geya\'rah ha puesto sus soldados a disposición de la Horda.', '', 28153),
(154569, 'esMX', '¡Mataste al encargado de cocina! ¡Y todavía no había servido los bocadillos!', '¡Mataste al encargado de cocina! ¡Y todavía no había servido los bocadillos!', 28153),
(154568, 'esMX', 'Perdido en las arena\'.', '¡Al fin una buena muerte!', 28153),
(154567, 'esMX', '¡Te haré pagar por arruinar el día de mi boda, tú... cosa... monstruosa!', '¡Te haré pagar por arruinar el día de mi boda, tú... cosa... monstruosa!', 28153),
(154566, 'esMX', '¿Sabes el tiempo que me llevó preparar todo para que saliera así de perfecto?', '¿Sabes el tiempo que me llevó preparar todo para que saliera así de perfecto?', 28153),
(154565, 'esMX', '¡¿Cómo te atreves a arruinar mi día especial?!', '¡¿Cómo te atreves a arruinar mi día especial?!', 28153),
(154564, 'esMX', 'El fin... Lo eh\'peraba.', 'No puede ser el fin... No así.', 28153),
(154563, 'esMX', '¡No he comido pan en cuatro meses!', '¡No he comido pan en cuatro meses!', 28153),
(154562, 'esMX', 'Todos volveremo\' a las arena\'.', 'La muerte e\' la única escapatoria.', 28153),
(154561, 'esMX', '¡¿Siquiera tienes idea de lo que costó este pastel?!', '¡¿Siquiera tienes idea de lo que costó este pastel?!', 28153),
(154560, 'esMX', '¡Estuve dos años en lista de espera para conseguir este lugar!', '¡Estuve dos años en lista de espera para conseguir este lugar! ¡Dos años!', 28153),
(154559, 'esMX', 'La muerte nunca me ha detenido...', '', 28153),
(154558, 'esMX', '¡Te podría matar con un dedo!', '', 28153),
(154557, 'esMX', '', 'Hay una nueva matriz de poder para recolectar.', 28153),
(154556, 'esMX', '', 'Hay una matriz de poder lista para recoger.', 28153),
(154555, 'esMX', '', 'Atención. Hay una nueva matriz de poder disponible.', 28153),
(154554, 'esMX', '', 'Advertencia. Estallido de reoriginación inminente. Despejen el área.', 28153),
(154553, 'esMX', '', 'Alerta. Secuencia de estallido de reoriginación iniciada. Evacúen el área.', 28153),
(154551, 'esMX', '¡La Horda ha sido derrotada!', '', 28153),
(154550, 'esMX', '¡Pronto comprenderás la inutilidad de tu resistencia!', '¡Pronto comprenderás la inutilidad de tu resistencia!', 28153),
(154549, 'esMX', '¡Sal de tu escondite y entrégate a tu destino!', '¡Sal de tu escondite y entrégate a tu destino!', 28153),
(154548, 'esMX', '¡El que ronda en las profundidades vestirá tu piel como una capa!', '¡El que ronda en las profundidades vestirá tu piel como una capa!', 28153),
(154547, 'esMX', '¡Lucha para conservar tu patética existencia! ¡Tarde o temprano, la marea sin fin se apoderará de ti!', '¡Lucha para conservar tu patética existencia! ¡Tarde o temprano, la marea sin fin se apoderará de ti!', 28153),
(154546, 'esMX', '', 'Usa Penitencia para curar tus heridas.', 28153),
(154545, 'esMX', '¿Pero qué tipo de pólvora es esta? Ey, ayúdame a recoger un poco.', '', 28153),
(154544, 'esMX', 'Usa Penitencia para curar tus heridas.', '', 28153),
(154543, 'esMX', '', 'Si lanzas Penitencia sobre ti mismo o sobre un aliado, sanará en lugar de infligir daño.', 28153),
(154542, 'esMX', 'Si lanzas Penitencia sobre ti mismo o sobre un aliado, sanará en lugar de infligir daño.', '', 28153),
(154541, 'esMX', '¡Mata a esos monstruos!', '¡Mata a esos monstruos!', 28153),
(154540, 'esMX', '¡Se suponía que este sería un día alegre!', '¡Se suponía que este sería un día alegre!', 28153),
(154539, 'esMX', '¿Qué está pasando? ¿Qué sucede? ¿Qué son estos monstruos?', '¿Qué está pasando? ¿Qué sucede? ¿Qué son estos monstruos?', 28153),
(154538, 'esMX', '¡Esto es mucho peor que escuchar el discurso de un familiar borracho!', '¡Esto es mucho peor que escuchar el discurso de un familiar borracho!', 28153),
(154537, 'esMX', '¿Por qué ocurre todo esto?', '¿Por qué ocurre todo esto?', 28153),
(154536, 'esMX', '¡Ni siquiera hemos podido bailar el vals del halcón zancudo!', '¡Ni siquiera hemos podido bailar el vals del halcón zancudo!', 28153),
(154535, 'esMX', '¡Se suponía que este sería un día de celebración!', '¡Se suponía que este sería un día de celebración!', 28153),
(154534, 'esMX', '¡Ahhhhhhhhh!', '¡Ahhhhhhhhh!', 28153),
(154533, 'esMX', 'Nos retiramos, Jefa de guerra. Vamos, $n.', '', 28153),
(154532, 'esMX', '', 'Nuestros aliados natonocturnos tienen una afinidad particular por la teletransportación. Te sugiero que aproveches su conocimiento para tus viajes.', 28153),
(154531, 'esMX', 'He obtenido un fragmento del artefacto que Garrosh usó para viajar allí. Creo que puedo volver a abrir un camino... pero necesitaré la ayuda de los dragones para hacerlo.', '', 28153),
(154530, 'esMX', '', 'Veo el potencial de este plan. Pero creí que el acceso a ese Draenor estaba cerrado.', 28153),
(154529, 'esMX', 'Hablaré con Owings. Disfruto mi trabajo y quiero seguir haciéndolo. Bajo mis propios términos.', '', 28153),
(154528, 'esMX', 'Esto significa que... Ya entiendo.', '', 28153),
(154527, 'esMX', 'Mmm... No creo que el capitán haya decidido no aliarse con los Aspafresno. Lo vi bastante convencido.', '', 28153),
(154526, 'esMX', '', '¿Qué dices, $n? ¿Estás en condiciones de reclutar a un aliado nuevo?', 28153),
(154525, 'esMX', '', 'La destreza bélica de los orcos Mag\'har es legendaria. Necesitaré guerreros temerarios en los días que se avecinan.', 28153),
(154524, 'esMX', '', '¿Un ejército de orcos militantes de otro mundo? Soldados entrenados... Armas con ansia de sangre de la Alianza. Interesante...', 28153),
(154523, 'esMX', '$UEste:esta; adalid salvó a Draenor de Garrosh y de la Legión Ardiente, y se ganó la confianza de los orcos que habitan ahí. Están en deuda con la Horda. Propongo que nos cobremos esa deuda.', '', 28153),
(154522, 'esMX', 'Jefa de guerra, hace años la Horda persiguió al fugitivo Garrosh Grito Infernal hacia un Draenor que era apenas el eco del planeta que conocí.', '', 28153),
(154521, 'esMX', 'Les diremos que no a los Aspafresno. Estas son las órdenes del capitán.', 'Les diremos que no a los Aspafresno. Estas son las órdenes del capitán.', 28153),
(154520, 'esMX', 'Qué prendas elegantes llevas... ¿Necesitas algo?', '', 28153),
(154519, 'esMX', 'Tomen, mi\' valientes. Se ven secos... ¡Ja!', 'Tomen, mi\' valientes. Se ven secos... ¡Ja!', 28153),
(154518, 'esMX', 'Ruptura', 'Ruptura', 28153),
(154516, 'esMX', 'No eres $uun:una; estudiante. Espero que tengas una buena razón para interrumpir mi lección.', 'No eres $uun:una; estudiante. Espero que tengas una buena razón para interrumpir mi lección.', 28153),
(154515, 'esMX', '<Darrel parece no percatarse de tu presencia.>', '<Darrel parece no percatarse de tu presencia.>', 28153),
(154514, 'esMX', 'Es de mala educación interrumpir, $uforastero:forastera;.', 'Es de mala educación interrumpir, $uforastero:forastera;.', 28153),
(154513, 'esMX', 'A primera vista, no veo nada aquí que me diga a dónde fueron los demás gnomos. Déjame ver la información que recopilaste y te llamaré si encuentro algo interesante.', '', 28153),
(154512, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Valle Canto Tormenta.', '|cFF0000FF(Misión)|r Zarpar rumbo a Valle Canto Tormenta.', 28153),
(154511, 'esMX', '¡Alerta! ¡Alerta! ¡Intruso! ¡Intruso!', '', 28153),
(154510, 'esMX', '', 'Acepta este obsequio... la armadura tradicional de nuestro pueblo. Vístela con orgullo como un recuerdo de nuestra tierra. ¡Dranosh\'ek mag\'har!', 28153),
(154509, 'esMX', '', 'Al defender a la Horda de sus enemigos, has honrado a los Mag\'har.', 28153),
(154508, 'esMX', '', 'Vuelve a Orgrimmar y dile a tu gente que reconozco tu dedicación hacia mi pueblo.', 28153),
(154507, 'esMX', '', 'Has luchado incontables batallas en todo Azeroth. ¡Les has demostrado a nuestros aliados y enemigos qué significa ser Mag\'har!', 28153),
(154506, 'esMX', '', 'Vayas a donde vayas, jamás olvides que el corazón de Draenor late contigo. ¡Lok-tar ogar!', 28153),
(154505, 'esMX', '', '¡Con cada victoria les demostrarás a los habitantes de Azeroth que somos los amos de la guerra!', 28153),
(154504, 'esMX', '', 'Ahora la Horda necesita nuestra fuerza para enfrentar a la Alianza. Y hemos respondido a su llamado.', 28153),
(154503, 'esMX', '', 'Nuestro pueblo permaneció unido bajo el liderazgo de Grommash Grito Infernal en una única tribu: los Mag\'har.', 28153),
(154502, 'esMX', '', 'Hace muchos años, los héroes de este mundo viajaron a Draenor y lucharon a nuestro lado contra la Legión Ardiente.', 28153),
(154501, 'esMX', '', 'Mi eh\'timado Rokhan, la tribu Lanza Negra se ha ganado con crece\' la ayuda de los zandalari. Colaboraré en todo lo que pueda.', 28153),
(154500, 'esMX', 'Necesito $Ual:a la; adalid un momento. Un viejo enemigo logró eh\'capar de Bwonsamdi y ahora amenaza mi hogar.', '', 28153),
(154499, 'esMX', 'Estoy listo. Comiencen con el ritual.', 'Estoy lista. Comiencen con el ritual.', 28153),
(154498, 'esMX', '', 'Alguien por aquí debe saber algo. ¡Es imposible que una flota entera desaparezca!', 28153),
(154497, 'esMX', 'Mejor... ¿le abriremos nuestro puerto a la Horda?', '', 28153),
(154496, 'esMX', 'No nos entregaremos a Aspafresno...', '', 28153),
(154495, 'esMX', '¿Y se supone que tengo que creerte, $r? Dame eso.', '', 28153),
(154494, 'esMX', 'Órdenes del capitán, señor. ¡Ha decidido no aliarse con los Aspafresno!', 'Órdenes del capitán, señor. ¡Ha decidido no aliarse con los Aspafresno!', 28153),
(154493, 'esMX', '¿De dónde vienes exactamente? Es claro que no eres de por aquí.', '', 28153),
(154492, 'esMX', '', '¿Qué? Déjame ver eso.', 28153),
(154491, 'esMX', 'Tengo nuevas órdenes del capitán para ti, subalterna', 'Tengo nuevas órdenes del capitán para ti, subalterna.', 28153),
(154490, 'esMX', '', 'No solo para traer la flota a casa, sino para que Kul Tiras recupere su identidad... o para \"curar la infección\", como suele decir Cyrus.', 28153),
(154489, 'esMX', '', '¿Quién eres? ¿Y qué quieres, exactamente?', 28153),
(154488, 'esMX', '', 'También bendicen a todos los barcos kultiranos. Eso es lo que realmente los separa de los navíos pasajeros que ves en el puerto.', 28153),
(154487, 'esMX', '', 'Jamás había visto tanta azerita en un solo lugar. Me preocupa y me complace a la vez.', 28153),
(154486, 'esMX', '', 'Un elemental... de azerita pura. Mátalo, adalid, pero no lo destruyas. ¡Recoge toda la resina que puedas!', 28153),
(154485, 'esMX', '', 'Eso debería saciar su apetito... Al menos por un tiempo.', 28153),
(154484, 'esMX', '', 'Los orcos son grandes soldados, ¡pero cada uno come lo mismo que doce goblins! Nuestras reservas de alimentos se están agotando. ¿Podrías matar algunas bestias mientras acabas con los kaldorei?', 28153),
(154483, 'esMX', '', 'Como siempre digo, la rosa se corta antes de que le salgan espinas.', 28153),
(154482, 'esMX', '', 'Otra comandante kaldorei en el lugar y el momento equivocados. Mátala de inmediato. No podemos permitir que consiga refuerzos.', 28153),
(154481, 'esMX', '', 'Eras la flecha indicada para ese disparo, adalid.', 28153),
(154480, 'esMX', '', 'Colmillosauro llegó a la cima de las montañas entre la Costa Oscura y Frondavil. Reúnete con él en Valle Rompelanzas y asegúrate de que pueda cruzar a salvo.', 28153),
(154479, 'esMX', '¡Lo logramos, tripulación! ¡El rey pirata Zem\'lan eh\'tá muerto por ahora! ¡Y el tesoro e\' nuestro!', '', 28153),
(154478, 'esMX', '', 'Jamás dudé de ti, ni por un instante.', 28153),
(154477, 'esMX', '', 'Parece que los kaldorei han conseguido refuerzos. Esto puede ser un desafío. Espero que lo superes.', 28153),
(154476, 'esMX', '', 'Luchas con astucia y fervor. Tus actos sirven de inspiración para todos mis soldados, adalid.', 28153),
(154475, 'esMX', '', 'La Alianza está registrando la Costa Oscura para destruir nuestras bases. ¡No podemos perder terreno! ¡Defiende lo que es nuestro!', 28153),
(154474, 'esMX', '', 'En épocas de guerra, debes matar o morir. No queda nada más por decir.', 28153),
(154473, 'esMX', '', '¡No tengas piedad, adalid! Estos elfos salvajes no la tendrían contigo.', 28153),
(154472, 'esMX', '', 'Les dimos un golpe considerable a sus reservas, adalid. Bien hecho.', 28153),
(154471, 'esMX', '', 'Los kaldorei son más letales en la oscuridad. ¡Lánzate a la batalla y acaba con ellos antes de que llegue la noche!', 28153),
(154470, 'esMX', '', 'Hice bien en depositar mi confianza en ti. Pronto, la voluntad de los kaldorei se quebrará.', 28153),
(154469, 'esMX', '', '¡Nuestro ejército ha puesto a los soldados de Malfurion a la defensiva! ¡Debemos adentrarnos en la Costa Oscura mientras tengamos ventaja!', 28153),
(154468, 'esMX', '', 'Pobrecita... Apenas pudo tomar su arma.', 28153),
(154467, 'esMX', '', 'Esa comandante elfa de la noche está poniendo a prueba mi paciencia. Acábala.', 28153),
(154466, 'esMX', '', 'Imagina dormir miles de años para despertar y que te derroten. ¡Patético!', 28153),
(154465, 'esMX', '', 'Así que los ancestros decidieron salir a jugar... Hagamos que tengan un despertar agitado.', 28153),
(154464, 'esMX', 'Supongo que podría haber sido peor. Encárgate de que la Horda no recoja su resina.', '', 28153),
(154463, 'esMX', '', '¡Un elemental nacido de azerita pura! No sé qué tipo de amenaza representa, adalid... pero te pido que te ocupes.', 28153),
(154462, 'esMX', 'Los elfos de la noche nos disputarán cada palmo de territorio.', 'Los elfos de la noche nos disputarán cada palmo de territorio.', 28153),
(154461, 'esMX', '', '¿Ya has usado una bomba de azerita alguna vez? ¿Quieres conocer la potencia de verdad? Prepárate para el impacto. Te llevarás una buena sorpresa.', 28153),
(154460, 'esMX', '¡Qué espécimen tan espléndido! Se me ocurren varios usos alquímicos para esta criatura.', '', 28153),
(154459, 'esMX', 'Los cadetes nuevos siempre tardan en acostumbrase. No te preocupes, ¡eso forja el carácter!', '', 28153),
(154458, 'esMX', '', 'Los kaldorei desafiarán nuestra ocupación... A menos que dobleguemos sus espíritus.\n\nDebemos asestarles un golpe que les demuestre lo que está en juego. Tienen que perder algo... o a alguien... en quien depositen toda su fe y confianza. Un símbolo de esperanza.\n\n<La Dama Oscura entrecierra los ojos.>\n\nMalfurion Tempestira debe morir.', 28153),
(154457, 'esMX', 'Los pescadores han visto algo grande y extraño en el agua. Conseguir una muestra para estudiarla sería de gran ayuda.', '', 28153),
(154456, 'esMX', '', '¿La Alianza busca utilizar armas de asedio contra nosotros? Qué pintoresco. Muéstrales lo que puede hacer la Horda.', 28153),
(154455, 'esMX', 'Con la falta de hierro actual, ni siquiera podemos desperdiciar nuestras municiones de práctica. Nuestros marinos han ideado la forma perfecta para recuperarlas.', '', 28153),
(154454, 'esMX', '', 'Estas ruinas están repletas de recursos naturales... ¡que podemos tomar! No permitas que los kaldorei interfieran, adalid.', 28153),
(154453, 'esMX', '', 'Hay varios jinetes del viento a nuestra disposición. Toma nuestros explosivos y causa estragos en ese muro de fuegos fatuos. Será un mensaje para Malfurion.', 28153),
(154452, 'esMX', '', '¡Ja! ¡Buen disparo, $Uhéroe:heroína;! Aunque me siento mal por el que tenga que ir a buscar esas balas de cañón.', 28153),
(154451, 'esMX', '¡Una chamán de Ventura y Cía. controla elementales repletos de azerita! Esos enanos rateros no se merecen un poder así. ¡Aplástala!', '', 28153),
(154450, 'esMX', '', 'Parece que hay práctica de tiro en el área de entrenamiento. Seguramente puedes enseñarles un par cosas a los cadetes sobre cómo disparar un cañón.', 28153),
(154449, 'esMX', '', 'Las armas que recuperaste serán útiles para nuestra campaña de guerra. Un trabajo fantástico.', 28153),
(154448, 'esMX', '', 'Sea como sea, necesitamos la ayuda de los maresabios más que nunca.', 28153),
(154447, 'esMX', '¡Buen trabajo! Seguramente dejaste a varios sin monedas para apostar. Como a mí.', '', 28153),
(154446, 'esMX', '', 'Parece que nadie sabe por qué la flota no ha vuelto a casa.', 28153),
(154445, 'esMX', '', 'La gente dice que los maresabios han perdido su magia, pero creo que solo quieren poder, como Aspafresno.', 28153),
(154444, 'esMX', '', '¡Ese cargamento le pertenece a la Horda! No permitas que la Alianza le ponga las manos encima.', 28153),
(154443, 'esMX', 'Algunos de los Surcamar organizan un torneo de duelos piratas ocasionalmente, y no son muy meticulosos con la inscripción.', '', 28153),
(154442, 'esMX', '', 'A pesar de todo su entrenamiento, parece que esos forestales oscuros han fallado en sus ataques. Quizás Clamañublo debería hablar con ellos...', 28153),
(154441, 'esMX', '', 'Nuestros barcos más grandes siempre llevan a un maresabio para atravesar las tormentas, resistir los mares inclementes y poner viento a las velas.', 28153),
(154440, 'esMX', '', 'Mis forestales oscuros necesitan tu asistencia, adalid. ¡Ayuda a todos los que encuentres!', 28153),
(154439, 'esMX', '', 'Necesitamos tu ayuda en otro lugar, adalid. Tengo un equipo de goblins listos para encargarse del resto.', 28153),
(154438, 'esMX', 'De todas las posibilidades... ¡¿optaron por darle la sangre vital del planeta a un ogro y pensaron que lo volvería más inteligente?! No funcionará... ¿Verdad? Mejor lo matamos por las dudas, ¿no?', '', 28153),
(154437, 'esMX', '¡Estupendo! ¡Esto llamará la atención de todos los peatones!', '', 28153),
(154436, 'esMX', '', '¡Han arrojado los toneles de pólvora de azerita al mar! ¡Recógelos antes de que se hundan! ¡Rápido!', 28153),
(154435, 'esMX', 'Ya he usado las fotografías que tomaste antes. Si tienes algo de tiempo de sobra, me vendrían bien unas imágenes adicionales.', '', 28153),
(154434, 'esMX', '', 'Nuestro campamento está a salvo por ahora, pero debes mantenerte alerta.', 28153),
(154433, 'esMX', '¡El investigador principal de armas de Ventura y Cía. está aquí! Hemos estado intentando ubicarlo durante años. ¡Ve y dale una buena paliza!', '', 28153),
(154432, 'esMX', '', 'Ojalá pudieras ver la flota. ¡Incluso con todos los lugares que has visto, creo que te impactará!', 28153),
(154431, 'esMX', '¡Ah, Boralus! La ilustre ciudad de pandillas callejeras y nobles fanfarrones. ¿Sabes? Gnomeregan nunca tuvo esos problemas.', '', 28153),
(154430, 'esMX', 'He decidido incorporar otros sitios de interés en la publicidad de mi negocio. La ciudad es un buen lugar para comenzar.', '', 28153),
(154429, 'esMX', '', '¡Se han infiltrado saboteadores de la Alianza en nuestra base! ¡Expúlsalos! ¡Hazlos sangrar!', 28153),
(154428, 'esMX', '', 'En fin, ¡es hora de darle un buen uso a ese ferry!', 28153),
(154427, 'esMX', 'Mi investigador de armas se fue a trabajar a Ventura y Cía. por una paga mucho más alta. No soy quién para juzgarlo por avaro. Es una pena que tengas que ir a matarlo por mí, ¿no crees?', '', 28153),
(154426, 'esMX', '¡Excelente! ¿Sabes? Lo mejor de las fotografías es que no puedes oler a los caballos.', '', 28153),
(154425, 'esMX', 'Lord Norwington quiere un espacio destacado para su maravillosa finca en el próximo folleto del Manantial Burbujeante. Y no pienso decepcionarlo.', '', 28153),
(154424, 'esMX', 'Ventura y Cía. está llenando de azerita a sus ogros, dicen que los hará más inteligentes. Lo dudo, pero... quizá deberías encargarte de ellos. Por si acaso.', '', 28153),
(154423, 'esMX', '', 'La esencia de la poza de la luna te servirá en la batalla. Haz lo mismo con todas las pozas que los kaldorei consagren en el futuro.', 28153),
(154422, 'esMX', '', 'Los kaldorei usan las pozas de la luna para recuperar su fuerza en la batalla. Extrae lo que puedas de las pozas y luego... déjalas inutilizables. ¿Queda claro?', 28153),
(154421, 'esMX', '¡Qué oportuno! Un poco más y mi reputación como anfitrión habría sufrido un daño irreparable.', '', 28153),
(154420, 'esMX', 'Ten cuidado, Taelia. No confío en estos sabios encapuchados.', '', 28153),
(154419, 'esMX', 'Se comenta que Ventura y Cía. encontró la forma de someter a los elementales de azerita pura. Debemos ponerle fin a eso. Y cuando digo \"debemos\", me refiero a ti.', '', 28153),
(154418, 'esMX', '', 'Ordenaré a nuestros encantadores que infundan estas piedras lunares con azerita. ¡Su poder ahora es de la Horda!', 28153),
(154417, 'esMX', '', 'Los kaldorei obtienen su poder de colgantes de piedra lunar. Haz todo lo que puedas para quitarles estos abalorios.', 28153),
(154416, 'esMX', '', 'Bien hecho, adalid. Haré que agreguen la azerita a nuestras reservas.', 28153),
(154415, 'esMX', '', 'Ha aparecido azerita entre las ruinas de la Costa Oscura. ¡No podemos dejar que la Alianza recoja ni un solo fragmento!', 28153),
(154414, 'esMX', '', 'Ese es exactamente el mensaje que le quiero enviar a Malfurion. Excelente trabajo.', 28153),
(154413, 'esMX', '', 'Estos fuegos fatuos son como insectos que esperan ser aplastados. Apaga cada una de las luces, y el cielo se oscurecerá.', 28153),
(154412, 'esMX', '¡Esto es un desastre! ¡Los manantiales están fuera de control y atacan a mis huéspedes!', '', 28153),
(154411, 'esMX', '', '¡Imbéciles! ¡G\'huun no fallará! ¡Su poder es inservible!', 28153),
(154410, 'esMX', '', 'Nuestros cocineros deberían poder preparar algo sabroso con esto. Gracias.', 28153),
(154409, 'esMX', '', 'Mis hermanos druidas, bueno... comen como osos. Es un trabajo sucio, pero alguien tiene que reponer nuestras existencias. ¿Qué dices?', 28153),
(154408, 'esMX', 'Hora de ganarnos el pan. ¡Fuego a discreción!', '', 28153),
(154407, 'esMX', '¡Ja, ja! Eso estuvo bien.', '¡Ja, ja! Eso estuvo bien.', 28153),
(154406, 'esMX', 'Qué falta de modales.', 'Qué falta de modales.', 28153),
(154405, 'esMX', '¿Por qué harías eso?', '¿Por qué harías eso?', 28153),
(154404, 'esMX', '¡En nombre de todo\' los loa! ¿Qué cree\' que estás haciendo?', '¡En nombre de todo\' los loa! ¿Qué cree\' que estás haciendo?', 28153),
(154403, 'esMX', '¡Ya termina con eso!', '¡Ya termina con eso!', 28153),
(154402, 'esMX', '¡Apártense! ¡Traemos la artillería pesada!', '', 28153),
(154401, 'esMX', 'Esa es la última. ¡Tenemo\' una moneda entera, $Uricachón:ricachona;!', '', 28153),
(154400, 'esMX', 'Los pirata\' tienen el hábito de dividir sus moneda\' en ocho parte\'. Si tienes suerte quizá puedas recogerlas toda\'. Debe haber muchos tesoro\' abandonados en Puerto Libre.', '', 28153),
(154399, 'esMX', 'Esa sí que fue una pelea exquisita. Je, je, je. ¿Quieres un calamar? Ja, ja, ja.', '', 28153),
(154398, 'esMX', 'Una carabela gigante ha adoptado la\' aguas de Puerto Libre como su hogar. ¡No importa cuántos arpone\' le lancemos, siempre regresa!', '', 28153),
(154397, 'esMX', '¡Has matado al capitán siniestro Vandegrim y su alma descansa en paz! ¡Piensa en todo el tesoro que ya no eh\'tá maldito!', '', 28153),
(154396, 'esMX', 'El capitán Vandegrim se ganó la fama de ser una sabandija temible a lo largo de esta\' costas. Se rumorea que su avaricia era tan grande que sigue asaltando la\' costas desde la tumba.', '', 28153),
(154395, 'esMX', '¡Iggksh ywaq ag\'rr ni ky!', '', 28153),
(154394, 'esMX', '¡Ah\'shel ywaq qam yrr woth\'gl!', '', 28153),
(154393, 'esMX', '¡Esta es la última! ¡Tenemos una moneda entera! ¡Somos ricos!', '', 28153),
(154392, 'esMX', '¡Za ag\'rr wgah thyzz zuq!', '', 28153),
(154391, 'esMX', 'Los piratas tienen el hábito de dividir sus monedas en ocho partes. Si tienes suerte quizá puedas recogerlas todas. Debe haber muchos tesoros abandonados en Puerto Libre.', '', 28153),
(154390, 'esMX', 'Esa fue una pelea exquisita. ¿Te apetece un calamar?', '', 28153),
(154389, 'esMX', 'Una medusa gigante ha adoptado las aguas de Puerto Libre como su hogar. ¡No importa cuántos arpones le lancemos, siempre regresa!', '', 28153),
(154388, 'esMX', '¡Ga ag\'rr ez AN\'zig wgha kyth zuq!', '', 28153),
(154387, 'esMX', '¡Has matado al capitán siniestro Vandegrim y su alma descansa en paz! ¡Piensa en todo el tesoro que ya no está maldito!', '', 28153),
(154386, 'esMX', 'El capitán Vandegrim se ganó la fama de ser una sabandija temible por aquí. Se rumorea que su avaricia era tan grande que sigue asaltando las costas aún después de muerto.', '', 28153),
(154385, 'esMX', 'Eh\'te... no es el futuro que me prometieron...', '', 28153),
(154384, 'esMX', '¡La sangre de G\'huun corre por mis vena\'! ¡Tiemblen ante mi poder!', '', 28153),
(154383, 'esMX', 'Las cosas que he visto...', 'No esperaba tanta amabilidad.', 28153),
(154382, 'esMX', '¡Mi poder los deh\'truirá!', '', 28153),
(154381, 'esMX', 'Gracias. No habría durado mucho más.', 'Gracias. ¡No miraré hacia atrás!', 28153),
(154380, 'esMX', '¡El poder de G\'huun será su perdición!', '', 28153),
(154379, 'esMX', '¡Sientan el fin y la deseh\'peración!', '', 28153),
(154378, 'esMX', '¡Levántense, mis elegido\'! ¡Con sangre conquistaremos!', '', 28153),
(154377, 'esMX', '¡Surjan de mi sangre para aplah\'tar a los débiles!', '', 28153),
(154376, 'esMX', '¡Aquí, hermanos! ¡Aliméntense de los impíos!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'esMX', '¡Devuélvanme su sangre!', '', 28153),
(154374, 'esMX', '¡G\'huun! ¡Acepta eh\'ta ofrenda de sangre!', '', 28153),
(154373, 'esMX', 'Nunca tuvih\'te un futuro.', '', 28153),
(154372, 'esMX', 'Débil. Tal como lo predije.', '', 28153),
(154371, 'esMX', '¡Todo es tal como predije!', '', 28153),
(154370, 'esMX', '¡Vengan, necios! Ya he vislumbrado su fin.', '', 28153),
(154369, 'esMX', 'Mi madre murió cuando yo era muy joven, y mi padre se encargó de mi crianza. Era marinero, y siempre me dejaba una flor de tallo marino cuando se hacía a la mar.', 'Mi madre murió cuando yo era muy joven, y mi padre se encargó de mi crianza. Era marinero, y siempre me dejaba una flor de tallo marino cuando se hacía a la mar.', 28153),
(154368, 'esMX', '', 'Alerta. Se manifiesta una proyección oscura.', 28153),
(154367, 'esMX', '', 'Alerta. Sistema de contención del Vacío en peligro.', 28153),
(154366, 'esMX', '', 'Ese fue un acto noble, adalid.', 28153),
(154365, 'esMX', '', 'Alerta. Niveles de energía del Vacío peligrosos.', 28153),
(154363, 'esMX', '', 'Advertencia. Se están replicando nerubianos adicionales.', 28153),
(154362, 'esMX', 'Se ha restablecido el equilibrio. ¡Anu\'dorini talah!', '', 28153),
(154361, 'esMX', 'Este camina en las sombras, adalid. Pero nadie escapa de la luz de luna bendita de Elune. Acábalo.', '', 28153),
(154360, 'esMX', '', 'Advertencia. Se están replicando silítidos adicionales.', 28153),
(154359, 'esMX', '¡Bah! ¡Cosas horrendas! Al ver un tallo marino solo pienso en lo\' buenos marineros que no regresan y en los cargamentos que yacen en el fondo del mar.', '¡Bah! ¡Cosas horrendas! Al ver un tallo marino solo pienso en los bueno\' marinero\' que no regresan y en los cargamento\' que yacen en el fondo del mar.', 28153),
(154358, 'esMX', '', 'Mythrax no tiene cabida en este mundo.', 28153),
(154357, 'esMX', '', 'Que Elune te bendiga, adalid. Brillas como una estrella.', 28153),
(154356, 'esMX', '', 'Mis arqueros necesitan tu colaboración, adalid. ¡Ayuda a todos los que encuentres!', 28153),
(154355, 'esMX', '', 'Esta guerra debe cesar.', 28153),
(154354, 'esMX', '', 'Seré tu amparo.', 28153),
(154353, 'esMX', '', 'Datos cargados. Apagando disco.', 28153),
(154352, 'esMX', '', 'Eliminaste la amenaza y ADEMÁS devolviste intacta la máquina de asedio. El reconocimiento es aún mayor.', 28153),
(154351, 'esMX', '', 'Debemos restaurar el orden.', 28153),
(154350, 'esMX', '', 'Cada uno tiene un lugar. El mío es este.', 28153),
(154349, 'esMX', '', 'Estoy debilitada, pero estoy aquí.', 28153),
(154348, 'esMX', '', '¿Ya habías usado una de estas? Sujétate, ¡te llevarás una sorpresa!', 28153),
(154347, 'esMX', '', 'Ingreso al disco exitoso. Cargando datos corruptos.', 28153),
(154346, 'esMX', 'Enviaré a todos los soldados que pueda reunir. Espero que sean capaces de repeler el asalto. No podemos lidiar con dos frentes de guerra.', '', 28153),
(154345, 'esMX', 'Siento una perturbación hacia el norte. ¿Será...? ¿Será que la Horda nos ha empezado a atacar desde las montañas? ¡Ve a investigar, rápido!', '', 28153),
(154344, 'esMX', '', 'Te ves mal, adalid. ¿Falló el plan?', 28153),
(154343, 'esMX', '', 'Esos toneles de pólvora de azerita pueden ser peligrosos incluso bajo el agua. Detónalos antes de que salgan a la superficie. Intenta no volar en mil pedazos, ¿de acuerdo?', 28153),
(154342, 'esMX', '', 'Sobrecarga de matriz de datos. Se accedió a varios discos.', 28153),
(154341, 'esMX', 'Un tallo marino, ¿eh? Algunos de los miembro\' de mi tripulación les dejan uno siempre a sus seres queridos cuando zarpamos. No los culpo. Quieren evitar que su\' familias pasen vicisitudes si algo malo sucede.', 'Un tallo marino, ¿eh? Algunos de los miembro\' de mi tripulación les dejan uno siempre a sus seres queridos cuando zarpamos. No los culpo. Quieren evitar que su\' familias pasen vicisitudes si algo malo sucede.', 28153),
(154340, 'esMX', '', 'Jamás dude de ti, ni por un instante.', 28153),
(154339, 'esMX', '', 'Han llegado miles de soldados de la Horda. No debemos subestimarlos. Este en particular se ve... resistente. Acércate con cuidado, adalid.', 28153),
(154338, 'esMX', '', 'Ingreso al disco exitoso. Cargando datos de Yogg-Saron.', 28153),
(154337, 'esMX', '', 'Ingreso al disco exitoso. Cargando datos de C\'thun.', 28153),
(154335, 'esMX', '', '¡Los saboteadores de la Horda se han colado en nuestras filas! ¡Expúlsalos! ¡Que sangren como nosotros!', 28153),
(154334, 'esMX', '', 'Debo admitir que sabes lo que haces, $uhéroe:heroína;. Hasta mis centinelas podrían aprender algunas cosas de ti.', 28153),
(154333, 'esMX', '', '¡Es hora de combatir fuego con fuego! ¡Debemos destruir a los demoledores de la Horda y expulsarlos a los Baldíos de donde vienen!', 28153),
(154332, 'esMX', '', 'Elune te sonríe, adalid. Y yo también.', 28153),
(154331, 'esMX', '', '¡La Horda intenta robar la esencia de nuestras pozas de la luna! ¡No permitas que profanen nuestras fuentes sagradas!', 28153),
(154330, 'esMX', '', 'Que esos miserables de la Horda se queden en sus páramos. Les enseñaremos a no meterse en nuestros bosques.', 28153),
(154329, 'esMX', '', 'La Horda ha montado una base cerca de la frontera de Vallefresno. ¡Reúne a los druidas que cuidan el bosque!', 28153),
(154328, 'esMX', '', 'Buena lucha, adalid. Cuánto fervor...', 28153),
(154327, 'esMX', '', '¡Los soldados de la Horda están robando recursos de nuestras tierras! Detenlos... antes de que vacíen nuestro bosque sagrado.', 28153),
(154326, 'esMX', '', 'Milenios de muerte no lograron menguar sus habilidade\'. Hicih\'te bien en aplacar su poder.', 28153),
(154325, 'esMX', '', '¡Esa... esa e\' la guardia prima del rey Dazar! ¡No se rendirán fácilmente!', 28153),
(154324, 'esMX', '¡Ja! Parece que re-mataste a esos no-muertos! Buen trabajo.', '', 28153),
(154323, 'esMX', 'Esos trols no-muertos parecen más peligrosos que el resto. ¡Cuidado!', '', 28153),
(154322, 'esMX', '¿Qué puedes contarme sobre los tallos marinos?', '¿Qué puedes contarme sobre los tallos marinos?', 28153),
(154321, 'esMX', '', 'Perfecto, adalid. La colaboración que has brindado hoy no pasará inadvertida.', 28153),
(154320, 'esMX', '', 'La Horda ya tiene armas de azerita. Veamos si podemos confiscarles algunas. ¿Qué dices?', 28153),
(154319, 'esMX', 'Eh... Las Cámaras de Piedra no cuentan.', '', 28153),
(154318, 'esMX', 'Pfff. Los ensamblajes de lo enanos jamás se descontrolarían así.', '', 28153),
(154317, 'esMX', '', '¡Excelente trabajo! Haré que los alquimistas guarden la azerita lejos del alcance de la Horda.', 28153),
(154316, 'esMX', 'Bah, típica fabricación trol... Pésima calidad. Ese gólem se ha vuelto loco. ¡Domínalo a los golpes!', '', 28153),
(154315, 'esMX', '', 'Tenemo\' que encontrar a Julwaba ante\' que Jakra\'zet.', 28153),
(154314, 'esMX', '', 'La magia oscura de Zul ha corrompido a eh\'te guardián. Detén su frenesí para que podamo\' repararlo.', 28153),
(154313, 'esMX', '', 'Zul... lo que le has hecho a eh\'te lugar sagrado es imperdonable.', 28153),
(154312, 'esMX', '', 'Adiós, Halu. Deh\'cansa en paz.', 28153),
(154311, 'esMX', '', 'Ahh, el maestro de armas Halu... él entrenó a mi padre, y a su padre antes que a él. Sus día\' han terminado. Ayuda a su eh\'píritu agitado a encontrar la paz.', 28153),
(154310, 'esMX', '¡Ja! Parece que le mostraste quién es $Uel verdadero maestro:la verdadera maestra;.', '', 28153),
(154309, 'esMX', 'Un guerrero que entrenaba a la realeza zandalari aún acecha en esta tumba. ¡Acaba con él!', '', 28153),
(154308, 'esMX', '', 'Mis arqueros se encargarán de terminar con esto. Tu presencia marcó la diferencia, adalid. Te lo agradezco.', 28153),
(154307, 'esMX', '', 'Las fuerzas enemigas nos atacan desde el norte. Es hora de que tomemos la iniciativa, adalid.', 28153),
(154306, 'esMX', '¡Déjenlos pasar!', '', 28153),
(154305, 'esMX', '', '¡Ya casi termino! Puedo oír la voz de Akunda penetrando en mi mente.', 28153),
(154304, 'esMX', '', 'Haré lo que pueda para preparar la mente de Akunda, pero deberás prepararte para contener los recuerdos que pueden despertar.', 28153),
(154303, 'esMX', 'Ywaq ongg an\'qov i lal halahs nuq.', '', 28153),
(154302, 'esMX', 'Ywaq mh\'naus wgah zaix zyqtahg.', '', 28153),
(154301, 'esMX', 'Mojambo te hará... pagar...', '', 28153),
(154300, 'esMX', '', '¿Dónde...? ¿Dónde eh\'toy? ¿Qué hago aquí?', 28153),
(154299, 'esMX', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek...', '', 28153),
(154298, 'esMX', '', 'Son un poco misteriosos, pero son importantes para Kul Tiras. Ayudan a llevar peces a las redes, y lluvias a los campos del valle.', 28153),
(154297, 'esMX', '', 'La mayoría de las personas buscan una guía en el mar, así como muchos depositan su fe en la Luz, pero los maresabios tienen una conexión mucho más profunda con el agua.', 28153),
(154296, 'esMX', '', 'Normalmente, te ofrecería un paseo en Corazón de vendaval, pero los maresabios solo permiten visitas en bote.', 28153),
(154295, 'esMX', '', 'Esteré bien, Cyrus. Puedo protegerme. Además, ¡tengo $ual emisario:a la emisaria; de la Alianza a mi lado!', 28153),
(154294, 'esMX', '¡Oou yyqzz ez thyzz phquathi zuq!', '', 28153),
(154293, 'esMX', '¡Oou gul\'kafh lal lwhuk!', '', 28153),
(154292, 'esMX', '¡Qam oou iilth ez i awtgsshu amun on\'ma!', '', 28153),
(154291, 'esMX', '¡Log\'loth w\'oq Ongg!', '', 28153),
(154290, 'esMX', '', 'Ha aparecido azerita entre las ruinas de Costa Oscura. ¡No podemos dejar que la Horda se apodere de ella!', 28153),
(154289, 'esMX', '¡W\'oq uhn\'agth ez qam Shandai!', '', 28153),
(154288, 'esMX', '¡Awtgssh shn ongg shg\'ullwaq!', '', 28153),
(154287, 'esMX', '¡Zuq ag\'xig bormaz ag\'thyzak!', '', 28153),
(154286, 'esMX', '¡Gracias!', '¡Gracias!', 28153),
(154285, 'esMX', '¡Za qualar ag\'xig za al\'tha!', '', 28153),
(154284, 'esMX', '¡No me pagan lo suficiente como para soportar esto!', '¡No me pagan lo suficiente como para soportar esto!', 28153),
(154283, 'esMX', '¡AHHHHHHHHHHHHHHHHHHHHHHHH!', '¡AHHHHHHHHHHHHHHHHHHHHHHHH!', 28153),
(154282, 'esMX', '¡Gracias por salvarme!', '¡Gracias por salvarme!', 28153),
(154281, 'esMX', '¡Ya me veía entre dos panes!', '¡Ya me veía entre dos panes!', 28153),
(154280, 'esMX', '¡Oou vwahuHn ag\'xig shfk zuq!', '', 28153),
(154279, 'esMX', '¡Gracias, $Uamigo:amiga;!', '¡Gracias, $Uamigo:amiga;!', 28153),
(154278, 'esMX', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'esMX', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma.', '', 28153),
(154276, 'esMX', 'Za awtgsshu wgah uulg\'ma ywaq zaix.', '', 28153),
(154275, 'esMX', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr.', '', 28153),
(154274, 'esMX', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor.', '', 28153),
(154273, 'esMX', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma.', '', 28153),
(154272, 'esMX', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh.', '', 28153),
(154271, 'esMX', 'El bosque descansa cuando los espíritus encuentran la paz. Te lo agradezco.', '', 28153),
(154270, 'esMX', 'Los espíritus que tienes ante ti son solo ecos de lo que alguna vez fueron. Bríndales la calidez de tu toque, adalid. Concédeles la paz.', '', 28153),
(154269, 'esMX', 'Por algo me llaman señor aojador.', '', 28153),
(154268, 'esMX', 'Toma mi vara de aojamiento y transforma a alguno\' de eh\'tos sacerdotes en algo más interesante.', '', 28153),
(154267, 'esMX', 'Si crees que eso fue difícil, deberías ver lo que los demás loa les exigen a sus seguidore\'.', '', 28153),
(154266, 'esMX', 'Si nosotros no podemos parar esta corrupción, ¿quién podrá?', 'Si nosotros no podemos parar esta corrupción, ¿quién podrá?', 28153),
(154265, 'esMX', 'Los druidas de Gonk son demasiado serios. Haz algunas bromas sobre sus altare\' para alegrarlos un poco. Ah, quizás intenten matarte por eso.', '', 28153),
(154264, 'esMX', 'Si esto se propaga... Azeroth no tendrá salvación.', 'Si esto se propaga... Azeroth no tendrá salvación.', 28153),
(154263, 'esMX', 'La naturaleza grita de dolor... ¿qué podemos hacer para frenar esta locura?', 'La naturaleza grita de dolor... ¿qué podemos hacer para frenar esta locura?', 28153),
(154262, 'esMX', 'Si nuestros poderes no funcionan... ¿cómo curaremos al planeta?', 'Si nuestros poderes no funcionan... ¿cómo curaremos al planeta?', 28153),
(154261, 'esMX', '', '¡Fue un viaje movido! Hicieron un excelente trabajo.', 28153),
(154260, 'esMX', '', 'Nuestros dragones hada no están acostumbrados a usar brida, así que será un viaje difícil. Sube y guía sus ataques.', 28153),
(154259, 'esMX', '¡Me alimento con su terror!', '', 28153),
(154258, 'esMX', '¡Refuerzos de Forjaz! ¡Marchen hacia la base del enemigo!', '', 28153),
(154257, 'esMX', '¡Aplasten Ar\'gorok, por Arathor! ¡Por Stromgarde! ¡POR LA ALIANZA!', '', 28153),
(154256, 'esMX', '', 'Luchas como los zandalari de las leyenda\'. Impresionante.', 28153),
(154255, 'esMX', '', 'Vuelve\' a probar tu valor. Bien hecho.', 28153),
(154252, 'esMX', '', 'Nueh\'tros pueblo\' están a salvo gracias a ti.', 28153),
(154251, 'esMX', '', 'Ahora que ese enemigo está muerto, podemo\' continuar con nueh\'tro trabajo.', 28153),
(154246, 'esMX', '', 'El escondite está más adelante. Allí estaremos a salvo... por un rato.', 28153),
(154245, 'esMX', '', 'Ojalá sea la última vez que veamo\' a esa bestia.', 28153),
(154244, 'esMX', '', 'Los loa predijeron tu victoria. E\' bueno ver que no se equivocaron.', 28153),
(154243, 'esMX', '', 'Los miembro\' de tu Horda eh\'tarán complacidos de saber que acabah\'te con eh\'ta amenaza.', 28153),
(154242, 'esMX', '', 'Sabía que no eh\'taría a la altura de tu poderío.', 28153),
(154240, 'esMX', '¿Sienten ese hormigueo en la espalda? Ese soy yo.', '', 28153),
(154239, 'esMX', '', 'Me han informado que hay un enemigo poderoso cerca que te quiere ver morir. No tenga\' piedad.', 28153),
(154238, 'esMX', '', 'Los guerrero\' de la Horda me advierten que hay una amenaza cerca de ti. Elimínala para aliviarle\' la carga.', 28153),
(154237, 'esMX', '', 'Tus exploradore\' de la Horda informan que hay un enemigo formidable cerca. Concuerdo con el método que sugieren: una muerte rápida.', 28153),
(154234, 'esMX', 'Parece que Nazmir tiene una cantidad ilimitada de estos bárbaro\'. Gracias por matar alguno\'.', '', 28153),
(154232, 'esMX', '¡Ja, ja, ja! ¡Tienes talento! ¡No he visto a nadie recorrer las pendientes así en mucho tiempo!', '', 28153),
(154230, 'esMX', 'Los trols de sangre invaden nuestras puerta\'. Pelea a lomo de los cuernos de guerra para derrotar a estos bárbaro\'.', '', 28153),
(154228, 'esMX', 'Hoy no tengo trabajo para ti. La mayoría de los Rabaleros fueron a andar en trineo para relajarse. ¡Toma un pingüino y busca una pendiente!', '', 28153),
(154225, 'esMX', '', 'Ten cuidado. Hay un oponente peligroso cerca. Tenemo\' que matarlo antes de que ocasione más problema\'.', 28153),
(154224, 'esMX', 'Que Elune te bendiga por tu valentía, adalid.', '', 28153),
(154223, 'esMX', '', 'Los loa me susurran que hay un enemigo poderoso cerca. Exigen que lo borremo\' de la faz de Azeroth.', 28153),
(154222, 'esMX', 'Los ataques de la Reina alma en pena son implacables. ¡Explora el bosque y elimina su presencia oscura!', '', 28153),
(154221, 'esMX', '', 'Mis exploradore\' me informan que hay un oponente temible cerca. Mátalo antes de que se convierta en un peligro mayor.', 28153),
(154220, 'esMX', 'Mis fuerzas eh\'tán listas para seguir desde aquí. Gracia\' por darles tiempo para reagruparse.', '', 28153),
(154219, 'esMX', '', 'No baje\' la guardia. Siento algo siniestro aquí. ¡Deh\'trúyelo antes de que te deh\'truya a ti!', 28153),
(154218, 'esMX', 'La amenaza ha desaparecido por ahora. Los ancestros pueden volver a estar tranquilos.', '', 28153),
(154217, 'esMX', '', 'Hay un enemigo letal en el área. Mátalo, antes de que lastime a nuestros aliado\'.', 28153),
(154216, 'esMX', '¡Maten a todo\' los que no sean zandalari!', '', 28153),
(154215, 'esMX', 'Los ancianos están inquietos porque sienten la amenaza de la Horda. Elimina a estos villanos para devolver la paz a nuestros bosques.', '', 28153),
(154213, 'esMX', 'Tus acciones nos han dado el respiro que necesitamos para perseverar.', '', 28153),
(154212, 'esMX', 'Los árboles de este gran bosque se retuercen de agonía mientras la Horda se adentra cada vez más en nuestras tierras. ¡No podemos permitir que sigan avanzando!', '', 28153),
(154211, 'esMX', 'Ve con cuidado.', 'Ve con cuidado.', 28153),
(154210, 'esMX', 'Las arena\' devorarán a los debile\'.', 'Las arena\' devoran a los débile\'.', 28153),
(154209, 'esMX', 'No confíes en nadie.', 'Cuídate las eh\'paldas.', 28153),
(154208, 'esMX', 'Nadie merece eh\'te destino.', 'Nadie merece eh\'te destino.', 28153),
(154207, 'esMX', '¿Qué necesitas?', 'Aquí todos son bienvenido\'.', 28153),
(154205, 'esMX', 'Hola, colega.', 'Hola, colega.', 28153),
(154204, 'esMX', '', 'Aún te escucho... maestra...', 28153),
(154203, 'esMX', 'Mis susurros desgarrarán sus mentes.', '', 28153),
(154202, 'esMX', 'Que el hambre te abrume. Aliméntate de su sangre.', '', 28153),
(154201, 'esMX', 'Busca a tus aliados. Comparte mi regalo.', '', 28153),
(154200, 'esMX', 'Una adquisición excelente. ¡Y ahora, purguen al resto de los infieles!', '', 28153),
(154199, 'esMX', 'La podredumbre corre por tus venas. Propágala.', '', 28153),
(154198, 'esMX', 'Quítenles un dispositivo a los hechiceros infieles y cárguenlo. Recibirán una recompensa por sus esfuerzos.', '', 28153),
(154197, 'esMX', 'Nuestros hechiceros han detectado corrientes eléctricas demasiado fuertes en el templo.', '', 28153),
(154196, 'esMX', '¡Que comience el festín de las mil fauces!', '', 28153),
(154195, 'esMX', '¡Excelente! Ahora encarguémonos del corazón de Sethraliss.', '', 28153),
(154194, 'esMX', 'Tráiganme estas reliquias, y serán recompensados.', '', 28153),
(154193, 'esMX', '¡Hijos míos, vengan a alimentarse!', '', 28153),
(154192, 'esMX', 'Tengo entendido que los infieles han ocultado varios artefactos de nuestro pueblo en algún lugar del bazar, frente al corazón del templo.', '', 28153),
(154191, 'esMX', 'Sirvientes de la podredumbre, ¡consuman!', '', 28153),
(154190, 'esMX', '¡Un espécimen perfecto! ¡Rápido, eliminen a estas basuras infieles del templo!', '', 28153),
(154189, 'esMX', 'Me han dicho que una raza inusual de kroluskos ha formado una madriguera en el templo. Tráiganme una de sus crías y los recompensaré.', '', 28153),
(154188, 'esMX', '¡Nada detiene a mi pestilencia!', '', 28153),
(154187, 'esMX', '¡Mi añublo es eterno!', '', 28153),
(154186, 'esMX', '¡Los titanes no pueden salvarlos!', '', 28153),
(154185, 'esMX', '¡No pueden escapar de la infección!', '', 28153),
(154184, 'esMX', 'Los sellos desaparecieron. Se acerca el fin. Sean los primeros en recibir mi regalo.', '', 28153),
(154183, 'esMX', 'Los trabajadores están muy agradecidos por el rescate. Sin ti, estaban \"fritos\".', '', 28153),
(154182, 'esMX', 'El contagio... ha echado raíces...', '', 28153),
(154181, 'esMX', 'Las brujas han invadido Puerto Trinchante otra vez. ¡Salva a los trabajadores antes de que los transformen en salchichas!', '', 28153),
(154180, 'esMX', '', 'Los espíritus de los ancestros descansan y los drust están acabados. Buen trabajo.', 28153),
(154179, 'esMX', '', 'Esta batalla eterna pone en peligro a los refugiados de Alto de Arom. ¡Reduce las filas de los enemigos!', 28153),
(154178, 'esMX', 'Invoca a la tormenta, $n. ¡Desplaza a este usurpador!', '', 28153),
(154177, 'esMX', 'Blandes mi poder con gran destreza, $n.', '', 28153),
(154176, 'esMX', 'Mi querida criatura... Al fin puedes oírme. Un traidor acecha en nuestro templo.', '', 28153),
(154175, 'esMX', '', 'Una criatura malévola amenaza a mi pueblo, $Uinquisidor:inquisidora;. Elimínala.', 28153),
(154174, 'esMX', '', 'Las brujas han liberado una criatura poderosa en esta área. ¡Destrúyela!', 28153),
(154173, 'esMX', '', '¡Bien hecho! La gente de Drustvar está más segura gracias a ti.', 28153),
(154172, 'esMX', '', '¡Buen golpe, $Uinquisidor:inquisidora;! Lo pensarán dos veces antes de regresar a Drustvar.', 28153),
(154171, 'esMX', '¡Al fin, soy libre! Gracias, adalid.', '', 28153),
(154170, 'esMX', '', 'Los exploradores nos informan que hay un enemigo al acecho cerca. ¡Acaba con él!', 28153),
(154169, 'esMX', '', 'Un enemigo poderoso amenaza a mi pueblo en esta área. Neutralízalo.', 28153),
(154168, 'esMX', '¿Cómo es que perdí?', '', 28153),
(154167, 'esMX', '', 'Tienes el más profundo agradecimiento de mi pueblo. Todos dormiremos más tranquilos hoy.', 28153),
(154166, 'esMX', '', 'El pueblo de Drustvar te agradece por tu ayuda.', 28153),
(154165, 'esMX', 'Eso no fue muy inteligente.', '', 28153),
(154164, 'esMX', '', 'Nos informan que hay un enemigo en esta área. Aniquílalo.', 28153),
(154163, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t ¡G\'huun te lanza |cFFFF0404|Hspell:272506|h[Corrupción explosiva]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t ¡G\'huun te lanza |cFFFF0404|Hspell:272506|h[Corrupción explosiva]|h|r!', 28153),
(154162, 'esMX', 'Paz, por fin...', '', 28153),
(154161, 'esMX', '', 'Un enemigo peligroso amenaza al pueblo de Drustvar. ¡Encárgate!', 28153),
(154160, 'esMX', 'Si el océano no pudo matarme, ¿qué te hace pensar que tú podrás?', '', 28153),
(154159, 'esMX', 'Me propagaré y consumiré este mundo.', '', 28153),
(154158, 'esMX', 'Necesitamos un ferry al Monasterio de Canto Tormenta.', 'Necesitamos un ferry al Monasterio de Canto Tormenta.', 28153),
(154157, 'esMX', 'Tu cuerpo ahora sirve a un nuevo maestro.', '', 28153),
(154155, 'esMX', 'Todas las palabras que no se dijeron...', '', 28153),
(154154, 'esMX', '¡Aún hay ansias de lucha en mí!', '', 28153),
(154153, 'esMX', '¡Tus gritos resonarán para siempre!', '', 28153),
(154152, 'esMX', '¡La maldición de la carne los consumirá!', '', 28153),
(154151, 'esMX', '¡El brote ha comenzado!', '', 28153),
(154150, 'esMX', '', 'Sabe\' que debo hacerlo, Kaja. El deber ante todo.', 28153),
(154149, 'esMX', '', 'Jakra\'zet es un traidor, pero el rey no actuará sin prueba\'.', 28153),
(154148, 'esMX', 'Parece que... ahora puedo descansar...', 'Parece que... ahora puedo descansar...', 28153),
(154147, 'esMX', '¡Intentamos advertirte!', '¡Intentamos advertirte!', 28153),
(154146, 'esMX', '', 'Ve y fíjate qué puede\' encontrar. No me apartaré de Rakera.', 28153),
(154145, 'esMX', 'Ya eh\'tás $Ulisto:lista; para escuchar las palabras de Akunda, aunque debe hacerse en soledad. Ve al altar y comienza a rezar cuando eh\'tés $Udispuesto:dispuesta;.', '', 28153),
(154144, 'esMX', 'Akunda solo penetrará tu mente si te has purificado.', '', 28153),
(154143, 'esMX', 'Quiero regresar a este lugar.', 'Quiero regresar a este lugar.', 28153),
(154142, 'esMX', 'Niveles máximos. Reanudando recolección.', '', 28153),
(154141, 'esMX', '<Althair te mira con cariño.>', '<Althair te mira con cariño.>', 28153),
(154140, 'esMX', '<Althair te mira fijo.>', '<Althair te mira fijo.>', 28153),
(154139, 'esMX', 'Evacuación de fluidos en curso. Entrando en modo de espera.', '', 28153),
(154138, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun comienza a lanzar |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun comienza a lanzar |cFFFF0404|Hspell:267700|h[Mirada de G\'huun]|h|r.', 28153),
(154133, 'esMX', 'Espécimen marcado para la destrucción.', '', 28153),
(154132, 'esMX', 'Iniciando dispersión de sangre del huésped objetivo.', '', 28153),
(154131, 'esMX', 'Activando recuperación de cayada.', '', 28153),
(154130, 'esMX', 'Cayada en uso.', '', 28153),
(154129, 'esMX', 'Combustible a-agotado. Apagando...', '', 28153),
(154128, 'esMX', '', '¡Dranosh\'ek mag\'har!', 28153),
(154127, 'esMX', 'Sujetos listos para la contaminación.', '', 28153),
(154126, 'esMX', '', 'La guerra asedia estas tierras. <Ríe> ¡Bien! Disfrutaremos de la carnicería... ¡y nos alzaremos victoriosos!', 28153),
(154125, 'esMX', '', 'Somos los últimos sobrevivientes de una tribu orgullosa. Los incorruptos... los invulnerables... ¡los Mag\'har!', 28153),
(154124, 'esMX', '', 'Simples palabras para los demás... que significan todo para nosotros.', 28153),
(154123, 'esMX', '', 'Fuerza y honor. Sangre y truenos.', 28153),
(154122, 'esMX', 'Más leña para la podredumbre.', '', 28153),
(154121, 'esMX', 'Nuevo candidato para la corrupción.', '', 28153),
(154120, 'esMX', 'Huéspedes detectados. Iniciando infección.', '', 28153),
(154119, 'esMX', '', 'Te digo que son muy reales. Y un peligro inmenso. Ni siquiera los sethrak se atreven a ir al cañón.', 28153),
(154118, 'esMX', 'Iniciando recolección de plasma.', '', 28153),
(154117, 'esMX', '¡Más rápido, babosas! ¡Lo arreglan, les pago!', '', 28153),
(154116, 'esMX', 'Una isla tan hermosa...', 'Una isla tan hermosa...', 28153),
(154115, 'esMX', '¿Fue glorioso?', '¿Fue glorioso?', 28153),
(154114, 'esMX', '', 'Sigamo\' avanzando. Rakera no sobrevivirá a eh\'te desierto mucho tiempo.', 28153),
(154113, 'esMX', 'Esto no duele tanto como yo...', 'Esto no duele tanto como yo...', 28153),
(154112, 'esMX', '¿Por qué fracasé?', '¿Por qué fracasé?', 28153),
(154111, 'esMX', '¡Muere, buitre!', '¡Muere, buitre!', 28153),
(154110, 'esMX', '¡No me vencerás!', '¡No me vencerás!', 28153),
(154109, 'esMX', '¿Dónde está ahora tu Reina alma en pena?', '¿Dónde está ahora tu Reina alma en pena?', 28153),
(154108, 'esMX', '¡No sobreviví al océano para morir en manos de una basura como tú!', '¡No sobreviví al océano para morir en manos de una basura como tú!', 28153),
(154107, 'esMX', '', 'Oh, ni lo sueñes.', 28153),
(154106, 'esMX', 'Hora de ejecutar el plan de Nisha. Esos sethrak estarán sorprendidos como nunca en su vida.', '', 28153),
(154105, 'esMX', '', 'Debería haber invertido más en seguridad.', 28153),
(154104, 'esMX', '', '¡No puedo tolerar una distracción!', 28153),
(154103, 'esMX', '', '¡Azótenlos a todos si hace falta! Necesito a ese rompearrecifes operativo ahora.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'esMX', 'Quizás no sobreviva mucho más. Son heridas graves.', '', 28153),
(154101, 'esMX', '', 'Siempre encuentro la solución. ¿Es otra sobreviviente?', 28153),
(154100, 'esMX', 'Agarra lo que puedas antes de que todo quede destruido.', 'Agarra lo que puedas antes de que todo quede destruido.', 28153),
(154099, 'esMX', 'Hay muchos objetos fascinantes aquí.', 'Hay muchos objetos fascinantes aquí.', 28153),
(154098, 'esMX', 'Llevará tiempo reunir suficientes guardia\' para dominar el Camino Antiguo de Mercaderes como alguna vez hicimo\'. Apreciamos tu ayuda.', '', 28153),
(154097, 'esMX', 'Gracias...', 'Gracias...', 28153),
(154096, 'esMX', 'Oh, no... No otra vez.', 'Oh, no... No otra vez.', 28153),
(154095, 'esMX', 'No dejes que me devoren...', 'No dejes que me devoren...', 28153),
(154094, 'esMX', 'Me dijeron... que sería fácil...', 'Me dijeron... que sería fácil...', 28153),
(154093, 'esMX', 'Tu cabeza será un buen trofeo.', 'Tu cabeza será un buen trofeo.', 28153),
(154092, 'esMX', 'Algunos de nueh\'tros mercaderes han pedido guardias para sus caravanas. ¿Te interesa escoltarlo\'?', '', 28153),
(154091, 'esMX', '¡La peste te llevará!', '¡La peste te llevará!', 28153),
(154090, 'esMX', '¡Te has salvado del mar solo para morir en mis manos!', '¡Te has salvado del mar solo para morir en mis manos!', 28153),
(154089, 'esMX', '¡Morirás aquí!', '¡Morirás aquí!', 28153),
(154088, 'esMX', '¡SE TE HA CAÍDO LA MÁSCARA, $USEÑOR DE LA MUERTE:SEÑORA DE LA MUERTE;! ¡ABANDONA ESTE LUGAR SAGRADO!', '¡SE TE HA CAÍDO LA MÁSCARA, $USEÑOR DE LA MUERTE:SEÑORA DE LA MUERTE;! ¡ABANDONA ESTE LUGAR SAGRADO!', 28153),
(154087, 'esMX', 'El paso más importante que uno puede dar es el próximo, $n. Sigue por este camino.', 'El paso más importante que uno puede dar es el próximo, $n. Sigue por este camino.', 28153),
(154086, 'esMX', 'Eres un monstruo de la calaña de Arthas, $n. Cuando te llegue la muerte final, espero que agonices lentamente, $Utorturado:torturada; por el dolor y el sufrimiento que les infligiste a los demás. \n\nCuando todo el mundo se ocupaba de asuntos importantes, tú elegiste recorrer el planeta arrastrando a los muertos a una existencia maldita. Estoy segura de que te convenciste de que era por una buena causa, pero escucha bien mis palabras, $USeñor de la muerte:Señora de la muerte;, habrá consecuencias.\n\n<Zallestrasza se sacude ligeramente>\n\nPero por ahora, quizá puedas ayudarme.', 'Eres un monstruo de la calaña de Arthas, $n. Cuando te llegue la muerte final, espero que agonices lentamente, $Utorturado:torturada; por el dolor y el sufrimiento que les infligiste a los demás. \n\nCuando todo el mundo se ocupaba de asuntos importantes, tú elegiste recorrer el planeta arrastrando a los muertos a una existencia maldita. Estoy segura de que te convenciste de que era por una buena causa, pero escucha bien mis palabras, $USeñor de la muerte:Señora de la muerte;, habrá consecuencias.\n\n<Zallestrasza se sacude ligeramente>\n\nPero por ahora, quizá puedas ayudarme.', 28153),
(154085, 'esMX', '<La expresión de Zallestrasza se suaviza un poco.>\n\nNo creas que tampoco notamos eso, $n. Los de mi clase somos pocos y cada vida es preciosa.\n\nEso no te disculpa por la ofensa a mi vuelo, pero reconocemos y valoramos tu... autocontrol. Para un ser como tú no puede haber sido fácil.', '<La expresión de Zallestrasza se suaviza un poco.>\n\nNo creas que tampoco notamos eso, $n. Los de mi clase somos pocos y cada vida es preciosa.\n\nEso no te disculpa por la ofensa a mi vuelo, pero reconocemos y valoramos tu... autocontrol. Para un ser como tú no puede haber sido fácil.', 28153),
(154084, 'esMX', 'Sí, $USeñor de la muerte:Señora de la muerte; $n. \n\nSabemos que fuiste tú $Uel que:la que; asaltó nuestro sagrario. Sabemos que corrompiste y esclavizaste a Kyranastrasz. \n\nEsas son ofensas contra la vida por las que tendrás que responder... algún día.', 'Sí, $USeñor de la muerte:Señora de la muerte; $n. \n\nSabemos que fuiste tú $Uel que:la que; asaltó nuestro sagrario. Sabemos que corrompiste y esclavizaste a Kyranastrasz. \n\nEsas son ofensas contra la vida por las que tendrás que responder... algún día.', 28153),
(154083, 'esMX', 'Sabemos de tus fechorías, caballero de la muerte. Ayudaste a salvar a Azeroth de la Legión Ardiente, pero te hemos perdido la confianza. \n\nPiensa bien lo que haces.', 'Sabemos de tus fechorías, caballero de la muerte. Ayudaste a salvar a Azeroth de la Legión Ardiente, pero te hemos perdido la confianza. \n\nPiensa bien lo que haces.', 28153),
(154082, 'esMX', 'Parece que me faltaron un par de dragones en el Santuario Rubí. <Intenta matarla>', 'Parece que me faltaron un par de dragones en el Santuario Rubí. <Intenta matarla>', 28153),
(154081, 'esMX', 'Espero haberme ganado un voto de confianza por lo que hice aquí.', 'Espero haberme ganado un voto de confianza por lo que hice aquí.', 28153),
(154080, 'esMX', 'Tu pueblo es débil y estaba a punto de morir de todas formas. Solo acabe más rápido con su miseria.', 'Tu pueblo es débil y estaba a punto de morir de todas formas. Solo acabe más rápido con su miseria.', 28153),
(154079, 'esMX', 'Perdoné las vidas que pude.', 'Perdoné las vidas que pude.', 28153),
(154078, 'esMX', '¿Me conocen?', '¿Me conocen?', 28153),
(154077, 'esMX', '¡No! ¡No! ¡Nooooooo!', '¡No! ¡No! ¡Nooooooo!', 28153),
(154076, 'esMX', '', 'Por la Alianza.', 28153),
(154075, 'esMX', '¡Sal de aquí! ¡Sálvate!', '¡Sal de aquí! ¡Sálvate!', 28153),
(154074, 'esMX', 'Creo... creo que me hice encima...', 'Creo... creo que me hice encima...', 28153),
(154073, 'esMX', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(154072, 'esMX', '¡Gracias! Ya tenía un pie en la tumba.', '¡Gracias! Ya tenía un pie en la tumba.', 28153),
(154071, 'esMX', '¡¿Qué son estas cosas?! ¡Yo me largo de aquí!', '¡¿Qué son estas cosas?! ¡Yo me largo de aquí!', 28153),
(154070, 'esMX', '¡Me salvaste! Estaba a un paso de convertirme en comida para monstruos.', '¡Me salvaste! Estaba a un paso de convertirme en comida para monstruos.', 28153),
(154069, 'esMX', '¡Bah! Parece que no fue muy difícil.', '', 28153),
(154068, 'esMX', 'increíble... ¡¿con qué otros terrores ha conspirado Lord Canto Tormenta?!', '', 28153),
(154067, 'esMX', 'Un gran horror nos espera en el santuario. Vamos, ¡mostremos los colmillos!', '', 28153),
(154066, 'esMX', '¡Ten cuidado! Siento una masa de gran corrupción en el santuario. ¡No puede arraigarse!', '', 28153),
(154065, 'esMX', 'No te ves para nada diferente. Mmm. No importa, la cacería espera.', '', 28153),
(154064, 'esMX', '¿No sientes la calma? ¿La fortaleza de la determinación? Continuemos y hagamos lo que hay que hacer.', '', 28153),
(154063, 'esMX', 'Según los rumores, los maresabios se fortalecen con las aguas de las fuentes purificadoras. Veamos si es verdad antes de entrar al santuario.', '', 28153),
(154062, 'esMX', '¡Bah! ¡Síganme, vamo\'!', '', 28153),
(154061, 'esMX', 'Todos deben purificarse antes de entrar en nuestro lugar más sagrado. Debo pedirte que recibas la bendición de todas las fuentes purificadoras antes de entrar al santuario.', '', 28153),
(154060, 'esMX', 'Todo ayuda, adalid. ¡Por la Horda!', '', 28153),
(154059, 'esMX', 'Me reconforta saber que no todo ha caído en la corrupción de Lord Canto Tormenta. Gracias.', '', 28153),
(154058, 'esMX', 'Hay fuerza en estas pozas. ¡Consigue motas de agua pura para incrementar nuestro poder!', '', 28153),
(154057, 'esMX', 'Siento que el bien aún habita este lugar sagrado. Busca motas de agua pura para restaurar la antigua gloria de este santuario.', '', 28153),
(154056, 'esMX', 'Creí que no saldría de esta con vida. Gracias, $c.', 'Creí que no saldría de esta con vida. Gracias, $c.', 28153),
(154055, 'esMX', '', 'El contagio se propaga.', 28153),
(154054, 'esMX', '', 'Niveles virales en aumento.', 28153),
(154053, 'esMX', '', 'Nueva cepa detectada.', 28153),
(154052, 'esMX', '', 'Campo quirúrgico activado. Preparando muestras para su estudio.', 28153),
(154051, 'esMX', '', 'Niveles de infección críticos. Purga total iniciada.', 28153),
(154050, 'esMX', '', 'Ventilando cámara de contención.', 28153),
(154049, 'esMX', '', 'Evaluando resistencia bacteriana al calor extremo.', 28153),
(154048, 'esMX', '', 'Protocolo de disección iniciado.', 28153),
(154047, 'esMX', '', 'Si-si-sistema restaurado. Niveles en índices seguros.', 28153),
(154046, 'esMX', 'No fue una operación muy sigilosa, pero fue efectiva.', '', 28153),
(154045, 'esMX', '', 'Esa e\' la última. ¡Yazma ya no podrá continuar eh\'piándonos!', 28153),
(154044, 'esMX', '', 'Yazma tiene eh\'pías por todo\' lados. Mira a través de los ojos de las araña\'. Acaben con ellas.', 28153),
(154043, 'esMX', '', 'Saneamiento finalizado.', 28153),
(154042, 'esMX', 'Esta es una misión de rescate. Busca a los soldados capturados, libéralos y dirígete al punto de extracción. Te autorizo a usar fuerza letal. De hecho, lo recomiendo.', '', 28153),
(154041, 'esMX', '', 'Nivel de contagio reducido.', 28153),
(154040, 'esMX', 'Bien. Ahora el segundo equipo podrá liberar fácilmente a nuestros soldados.', '', 28153),
(154039, 'esMX', '', 'Hoja de las sombras Razi ya no matará a más de los mío\'. Gracias.', 28153),
(154038, 'esMX', '', 'Infección purgada.', 28153),
(154037, 'esMX', 'Esta operación es simple. Crea un caos. Tengo otro equipo listo para liberar a nuestros guerreros capturados, pero antes debes encargarte de esos guardias. Entra, mata a todos los que encuentres y sal de allí.', '', 28153),
(154036, 'esMX', '', 'Uno de los asesino\' de confianza de Yazma ha sido avih\'tado en el área. ¡Tengan cuidado!', 28153),
(154035, 'esMX', '', 'Cepa virulenta detectada. Neutralícenla por completo.', 28153),
(154034, 'esMX', '', 'Eso le enseñará a Yazma y a los de su clase a no experimentar con vudú oh\'curo.', 28153),
(154033, 'esMX', '', 'Protocolo de purificación activado.', 28153),
(154032, 'esMX', '', '¡El vudú maligno de Yazma ha animado a esa\' máh\'caras tiki! Deh\'truyan esos ensamblajes corruptos.', 28153),
(154031, 'esMX', '¡Lo lograron! Ahora los muchachos de la Liga de Expedicionarios pueden investigar el templo en paz.', '', 28153),
(154030, 'esMX', '¡Alguien ha estado matando a los trols zandalari por aquí! ¡No podemos enviar a la Liga de Expedicionarios al templo hasta que nos hayamos encargado de esa amenaza! ¡Es muy peligroso! ¡Vayan y encuentren al responsable!', '', 28153),
(154029, 'esMX', '¡Fantástico! Enviaré una expedición de inmediato.', '', 28153),
(154028, 'esMX', 'No puedo enviar a mis muchachos al templo con todas estas máscaras tiki alrededor. ¡Su magia es demasiado poderosa!', '', 28153),
(154027, 'esMX', '¡Bien hecho! ¡Aunque todavía siento algunas que me caminan por la barba!', '', 28153),
(154026, 'esMX', '¡Bah, arañas! ¡Siempre arañas! Esta Yazma las tiene por todos lados. Aplasten algunas para trabajar tranquilos.', '', 28153),
(154025, 'esMX', '¡Templeluz, acaben con esos demoledores!', '', 28153),
(154024, 'esMX', '¡Jinetes de grifos, a los cielos!', '', 28153),
(154023, 'esMX', '¡Hierro Negro, ahora! ¡Ataquen desde abajo!', '', 28153),
(154022, 'esMX', '', 'Bueno, tenemos las pruebas. ¡Aunque no dejaste muchos para llevar a cabo el plan! Como sea, buen trabajo.', 28153),
(154021, 'esMX', 'Gloria... a la Alianza...', '', 28153),
(154020, 'esMX', 'Quizás esté junto a los Velaniebla ahora, pero insinuar que soy capaz de traicionar a la Alianza, mis propias raíces, para aliarme con la Horda... ¡Cómo te atreves!', '', 28153),
(154019, 'esMX', '', 'Las tripulaciones piratas de Puerto Libre siempre planean algo. Ve a ver de qué se trata esta vez.', 28153),
(154018, 'esMX', 'Gracias a ti, la Séptima Legión tiene una amenaza menos de que preocuparse.', '', 28153),
(154017, 'esMX', '¡Buena pelea! ¡Pronto toda esta área será territorio de la Alianza!', '', 28153),
(154016, 'esMX', 'Eso fue un verdadero desafío, pero lo superaste con valentía. ¡Sigue así!', '', 28153),
(154015, 'esMX', 'El enemigo ha caído. Es una lástima que haya terminado tan violentamente, pero hiciste lo que había que hacer.', '', 28153),
(154014, 'esMX', 'Me habría sido útil tener a alguien como tú en la Tercera Guerra. Excelente trabajo.', '', 28153),
(154013, 'esMX', 'Te habría ido bien durante la Segunda Guerra. Buena pelea.', '', 28153),
(154012, 'esMX', 'Buen trabajo. ¡Ahora hay una amenaza menos de que preocuparse!', '', 28153),
(154011, 'esMX', 'Gracias por prestarnos tu ayuda. ¡Eres $Uel mejor:la mejor; adalid de los devotos!', '', 28153),
(154010, 'esMX', '', '¡Hay que golpearlos donde duele! ¡En el bolsillo!', 28153),
(154009, 'esMX', '', '¡Si tuviéramos uno de los libros de contabilidad de la pandilla, podríamos arruinar sus operaciones financieras!', 28153),
(154008, 'esMX', 'Gracias. Todavía no podemos mover a los heridos, pero nos has otorgado tiempo valioso.', 'Gracias. Todavía no podemos mover a los heridos, pero nos has otorgado tiempo valioso.', 28153),
(154007, 'esMX', 'Toma, esto detendrá la hemorragia por ahora...', 'Toma, esto detendrá la hemorragia por ahora...', 28153),
(154006, 'esMX', 'Sé que duele, pero trata de no moverte...', 'Sé que duele, pero trata de no moverte...', 28153),
(154005, 'esMX', '¡Silencio! Nos escucharán...', '¡Silencio! Nos oirán...', 28153),
(154004, 'esMX', '¡Vayan a buscar ayuda! Veré qué puedo hacer desde el interior de Uldir para detener esta corrupción!', '', 28153),
(154003, 'esMX', '', 'Reconocería la letra de Owings en cualquier parte. ¡Primero te mataré a ti y después a esa traidora!', 28153),
(154002, 'esMX', '¡Aj, se está cerrando la entrada! ¡No puedo perderme esta oportunidad!', '', 28153),
(154001, 'esMX', '', '¡Justo donde lo dejé!', 28153),
(154000, 'esMX', '', '¡Capitán! Tenemos un motín...', 28153),
(153999, 'esMX', '¡¿Esa cosa dijo G\'huun?! ¡Sigan a esa máquina!', '', 28153),
(153997, 'esMX', 'Tal vez tenga algo que ver con Uldir. ¡Rápido, averigüémoslo!', '', 28153),
(153996, 'esMX', 'Oh... Nunca había visto una corrupción como esa.', '', 28153),
(153995, 'esMX', '', 'Hola, $c. ¿Quiere\' aprender un poco de alquimia?$b$bNadie te enseñará como yo, te lo aseguro.', 28153),
(153994, 'esMX', '¿Quién sabe los secretos que contiene? ¡Tal vez incluso tenga la respuesta para derrotar a los dioses antiguos!', '', 28153),
(153993, 'esMX', 'Los titanes construyeron este complejo después de la caída del Imperio Negro para hacer experimentos en todo tipo de bestias.', '', 28153),
(153992, 'esMX', '¡Aj! ¡¿Qué clase de bestia es esta?!', '', 28153),
(153991, 'esMX', '¡Estas cuevas deben llevar al legendario Uldir!', '', 28153),
(153990, 'esMX', 'Gracias por tu ayuda. El desierto es un lugar más seguro gracias a tu esfuerzo.', '', 28153),
(153989, 'esMX', '', 'Eso fue todo un desafío, pero has peleado bien. ¡Sigue así!', 28153),
(153988, 'esMX', '', 'Un problema meno\' de qué preocuparnos. ¡Buen trabajo!', 28153),
(153987, 'esMX', '', 'Bien hecho. Le has enseñado al enemigo una lección difícil de olvidar.', 28153),
(153986, 'esMX', 'Muéstrame el camino.', 'Muéstrame el camino.', 28153),
(153985, 'esMX', '', 'Esta casa está repleta de secretos ocultos. Ahora que aseguramos los pisos de arriba, puedo mostrarte un camino secreto al sótano.', 28153),
(153984, 'esMX', 'Gracias por darnos una mano. ¡Necesitamos más adalides como tú en Vol\'dun!', '', 28153),
(153983, 'esMX', 'Buen trabajo. Gracias a tu ayuda, ahora el desierto es un poco más seguro.', '', 28153),
(153982, 'esMX', 'Un peligro menos por el que preocuparse en Vol\'dun. ¡Bien hecho!', '', 28153),
(153981, 'esMX', 'Pero piensa en todo... el oro...', '', 28153),
(153980, 'esMX', '¿Llegas a entender en qué te estás entrometiendo? ¡Aspafresno nos dará más poder del que podríamos haber soñado!', '', 28153),
(153979, 'esMX', '¡No le harás daño a mi pueblo!', '', 28153),
(153978, 'esMX', 'Las piedras están... por todas partes... ¡Los mogu... se quedarán con todas!', '', 28153),
(153977, 'esMX', '¡Allí! ¡Ataquen!', '', 28153),
(153976, 'esMX', '', 'Creo que eso es todo. Sí que sabes cuidar espaldas.', 28153),
(153975, 'esMX', '¡Con estas piedras, los mogu serán invencibles!', '', 28153),
(153974, 'esMX', '¡Al fin apareciste! ¡Largo!', '', 28153),
(153973, 'esMX', '', 'Tenemos compañía. ¡Vuélalos por los aires, $p!', 28153),
(153972, 'esMX', '', '¡Sujétate! ¡Será un paseo movido!', 28153),
(153971, 'esMX', '¡Deja que este viejo lobo te muestre los dientes!', '', 28153),
(153970, 'esMX', '¡Me perteneces!', '', 28153),
(153969, 'esMX', 'Ahora tienes coraje, ¿eh? ¡Ja!', '', 28153),
(153968, 'esMX', '', 'No lo creo.', 28153),
(153967, 'esMX', '', 'Patético.', 28153),
(153966, 'esMX', '', 'Hoy no.', 28153),
(153965, 'esMX', 'Mis exploradores informan de un enemigo peligroso cerca. Necesito que lo neutralices.', '', 28153),
(153962, 'esMX', 'Un enemigo cercano ha matado a algunos de mis soldados. ¡Venga sus muertes!', '', 28153),
(153959, 'esMX', 'La Séptima Legión ha recibido informes sobre un enemigo poderoso en las cercanías. Elimínalo de inmediato.', '', 28153),
(153958, 'esMX', 'Ningún tesoro... Solo oscuridad.', 'Oro interminable a donde mire\'...', 28153),
(153957, 'esMX', 'Libérame...', 'Soy... ¿libre?', 28153),
(153956, 'esMX', 'Tesoro maldito. Oro maldito.', 'Maldito maleante.', 28153),
(153955, 'esMX', 'Arrójenme al montón.', 'Huesos dorado\'.', 28153),
(153954, 'esMX', 'He oído sobre un enemigo peligroso cerca de tu posición. Elimínalo, pero no te confíes.', '', 28153),
(153953, 'esMX', 'Perdimos algunos exploradores en las cercanías a manos de un enemigo peligroso. Acábalo y honra sus muertes.', '', 28153),
(153952, 'esMX', 'Ten cuidado, hay una amenaza cerca. Mantén la calma y extermínala antes de que escape.', '', 28153),
(153951, 'esMX', 'Eso no se ve nada mal. Pero si no te gusta puede\' seguir cavando.', '', 28153),
(153950, 'esMX', 'Tengo una poción para cada uno. Todavía no la beban.', '', 28153),
(153949, 'esMX', 'Bien. Has logrado enfurecer mucho a una ciudad que estaba dormida.\n\nNo perdamos tiempo en señalar al culpable, ¿de acuerdo?', '', 28153),
(153948, 'esMX', 'Ya he oído esta historia. (Omitir la gesta y viajar al Puerto de Zuldazar en Zandalar)', 'Ya he oído esta historia. (Omitir la gesta y viajar al Puerto de Zuldazar en Zandalar)', 28153),
(153947, 'esMX', 'Que sea un mensaje para tus maestros. ¡Estela de la Tormenta jamás se rinde!', '', 28153),
(153946, 'esMX', 'No dejes que entre en tu cabeza. ¡Resiste!', '', 28153),
(153945, 'esMX', '', 'Todo este dolor y sufrimiento es tu culpa. ¡MONSTRUO!', 28153),
(153944, 'esMX', '¡Nos protegeré de su ataque!', '', 28153),
(153943, 'esMX', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far.', '', 28153),
(153942, 'esMX', 'Oro, oro, oro...', 'Más tesoro\' para el montón.', 28153),
(153941, 'esMX', 'Sin luz. Sin escapatoria. El rey olvidado regresa.', '', 28153),
(153940, 'esMX', 'Aquí no hay tripulantes...', 'Corre...', 28153),
(153939, 'esMX', 'Todo el tesoro para Zem\'lan.', 'El tesoro es solo para Zem\'lan.', 28153),
(153938, 'esMX', 'Hay que hacer la\' presentaciones. Contramaestre Owings, $n. $n, Owings. Ahora, vamos a lo nuestro, ¿sí?', '', 28153),
(153937, 'esMX', '', 'Le advertí a Kiro sobre el ataque inminente de los sethrak. Podríamos habernos preparado... Quizás ahora por fin me haga caso.', 28153),
(153936, 'esMX', '', 'No estábamos preparados para este ataque. Los sethrak asesinan y esclavizan sin remordimiento.', 28153),
(153935, 'esMX', 'Oro...', 'Brillante...', 28153),
(153934, 'esMX', 'Una amenaza peligrosa merodea en las cercanías. Destrúyela antes de que cace más vidas inocentes.', '', 28153),
(153933, 'esMX', 'Algunos de nuestros aliados fueron atacados por aquí. Debes eliminar la amenaza de inmediato.', '', 28153),
(153930, 'esMX', 'Hay una criatura peligrosa cerca. Debes eliminarla antes de que siga hiriendo a más inocentes.', '', 28153),
(153929, 'esMX', '', 'He recibido informes de una amenaza aquí cerca. ¡Elimínala cuanto ante\'!', 28153),
(153928, 'esMX', '', 'Atacaron a alguno\' de nueh\'tros aliados aquí cerca. ¡Elimina la amenaza ante\' de que ataque otra vez!', 28153),
(153927, 'esMX', '', 'Algo muy poderoso merodea por aquí. Tienes que matarlo ante\' de que te mate a ti.', 28153),
(153926, 'esMX', 'Hemos recibido informes sobre una criatura peligrosa en esta zona. Necesito que la extermines lo antes posible.', '', 28153),
(153925, 'esMX', '¡Rápido, a mí!', '', 28153),
(153924, 'esMX', 'Una de nuestras caravanas fue atacada por aquí. ¡Elimina la amenaza antes de que vuelva a suceder!', '', 28153),
(153923, 'esMX', 'Sé que es una humana, pero tratemo\' de ser comprensivos.', '', 28153),
(153922, 'esMX', 'El objetivo e\' simple. Si los ayudamo\' a que su motín tenga éxito, podremos quedarno\' aquí para lanzar nuestro ataque.', '', 28153),
(153921, 'esMX', 'Owings no quiere entregar su libertad como el reh\'to de los piratas.', '', 28153),
(153920, 'esMX', 'Hay una criatura peligrosa en las cercanías. ¡Necesito que te encargues de ella antes de que sea demasiado tarde!', '', 28153),
(153919, 'esMX', 'Oí hablar de nuestro contacto mientra\' estaba explorando Tiragarde para encontrar puntos de desembarco.', '', 28153),
(153918, 'esMX', '¡Ah, colega pirata!', '', 28153),
(153917, 'esMX', 'El reino hundido les da la bienvenida a sus almas cavernosas.', '', 28153),
(153916, 'esMX', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma.', '', 28153),
(153915, 'esMX', '¡Está perdido! Solo queda la oscuridad.', '', 28153),
(153914, 'esMX', '', 'Sam, sé que estás ahí. ¡Tienes que resistir!', 28153),
(153913, 'esMX', 'Veo que no hay criatura que pueda hacerte frente.', '', 28153),
(153912, 'esMX', '', '¡Excelente! El camino está despejado.', 28153),
(153911, 'esMX', 'No era más que una réplica. Jamás volvamos a hablar de esto.', '', 28153),
(153910, 'esMX', '', '¡Perfecto! Lo recuperaremos y veremos lo que oculta.', 28153),
(153909, 'esMX', 'Esto bastará. La jefa de guerra envía sus saludos.', '', 28153),
(153908, 'esMX', '', '¡Fantástico! Esto nos ayudará en nuestra campaña.', 28153),
(153907, 'esMX', 'Muy bien, vamo\' a ver a ese contramaestre. Actúa como pirata.', '', 28153),
(153906, 'esMX', 'Me veo bien, ¿no e\' verdad? ¡Arrrgh!', '', 28153),
(153905, 'esMX', 'Una bestia belicosa bloquea nuestra ruta de escape de esta prisión. Mátala.', '', 28153),
(153904, 'esMX', '', 'Una bestia poderosa nos impide asegurar una posición en esta playa. Necesito que te encargues para liberar una ruta de escape.', 28153),
(153903, 'esMX', 'Déjeme vestirme así también, $Ujefe:jefa;.', '', 28153),
(153902, 'esMX', 'Nuestros espías afirman que el Orgullo de Kul Tiras está anclado en Tol Dagor. Si los informes son ciertos, tienes que robar ese barco para nosotros.', '', 28153),
(153901, 'esMX', '', 'El Sobrestante tiene una reliquia oculta en una maqueta de barco. Me gustaría que la recuperaras.', 28153),
(153900, 'esMX', 'La máquina de guerra de la Horda necesita armas y armaduras. Junta todo lo que puedas y vuelve a verme.', '', 28153),
(153899, 'esMX', '', 'Con todo este caos, no pueden haber transportado todo el cargamento. Veamos si podemos arrebatarles algunos suministros sin que se den cuenta.', 28153),
(153898, 'esMX', 'Derrotaron a tu padre... Traicionaron a tu rey... ¡Y no hiciste nada! ¿Abandonarás a todos tus aliados por la Horda?', '', 28153),
(153897, 'esMX', 'En la Horda no hay más que monstruos. ¡No me sorprende que se volviesen en tu contra!', '', 28153),
(153896, 'esMX', '¡Te pusiste del lado de esos perros y olvidaste a tu propia sangre!', '', 28153),
(153895, 'esMX', 'Te quedaste mirando cómo esos animales me destrozaban. ¿Qué has ganado con tu traición?', '', 28153),
(153894, 'esMX', 'Una fuerza considerable de trols Secacorteza se acerca desde el este. ¿Qué dices si obligamos a algunos a huir hacia sus madrigueras? Mata al resto, por supuesto.', '', 28153),
(153893, 'esMX', 'No vayas a quemar eh\'te, cabeza hueca. Lo usaremo\' para salir de eh\'ta isla.', '', 28153),
(153892, 'esMX', 'Han derribado a varios de nuestros jinetes de grifos. Busca sobrevivientes en el campo de batalla.', '', 28153),
(153891, 'esMX', '', '¡Ahora lo ven! ¡Ahora comprenden! ¡G\'huun será su amo!', 28153),
(153890, 'esMX', '', '¡Si liberan esa monstruosidad, será el fin de Zuldazar!', 28153),
(153889, 'esMX', '', 'Sabía que los trol\' de sangre eran una amenaza, pero jamás imaginé... eh\'to...', 28153),
(153888, 'esMX', '¿Quién eres?', '¿Quién eres?', 28153),
(153886, 'esMX', 'Un gusto, $n. Hemos oído todo acerca de tus hazañas heroicas como adalid de Azeroth.', 'Un gusto, $n. Hemos oído todo acerca de tus hazañas heroicas como adalid de Azeroth.', 28153),
(153885, 'esMX', '¡Abominaciones corruptas! ¡Vuelvan a las profundidades!', '', 28153),
(153884, 'esMX', 'Temo que los cultistas de la casa Canto Tormenta están tratando de propagar su influencia en Boralus. Revela su verdadero rostro frente al pueblo.', '', 28153),
(153883, 'esMX', '', 'Así que los rumores eran ciertos. Al menos las calles son un poco más seguras ahora.', 28153),
(153882, 'esMX', 'A mí, hermanos y hermanas. ¡Resistimos juntos!', '', 28153),
(153881, 'esMX', 'No se detengan. ¡La oscuridad desgarra su mente!', '', 28153),
(153880, 'esMX', '', '¡Resiste, Sam! ¡Ya casi llegamos!', 28153),
(153879, 'esMX', '¡MAREAS DE SANGRE! ¡A MÍ! ¡A MÍ!', '', 28153),
(153878, 'esMX', '', 'Dicen que algunos de la Guardia de Boralus están en la nómina de la pandilla. ¿Podrías investigarlo?', 28153),
(153877, 'esMX', 'Fiu. Eso los mantendrá ocupados durante... ehh.... ¿unos cinco minutos?', '', 28153),
(153876, 'esMX', '¡Guau! ¡Estas aves están fuera de control! ¡Dales una galleta o algo! ¡Rápido!', '', 28153),
(153875, 'esMX', 'Bueno. Ninguna de estas carteras es mía, pero... me las quedaré hasta que encontremos a sus dueños.', '', 28153),
(153874, 'esMX', '¿Eh? ¿Dónde está mi cartera? ¡Ey! ¡¿Ese mocoso se llevó mi cartera?! ¡Atrápenlo!', '', 28153),
(153873, 'esMX', '', 'Espero que los demás estén a salvo.', 28153),
(153872, 'esMX', '', 'En general, los vulperas somos un pueblo pacífico. Viajamos en caravanas, buscamos suministros y hacemos trueques donde podemos.', 28153),
(153871, 'esMX', 'Lo lograste, $p. ¡Ai\'twen está despertando!', '', 28153),
(153870, 'esMX', '', 'Mira lo que los sethrak han hecho con nuestro hogar...', 28153),
(153869, 'esMX', '', 'Buena elección. Esta va a servir.', 28153),
(153868, 'esMX', 'Algunos ogros Puño de Roca planean asaltar Stromgarde. Demuéstrales amablemente lo que le sucedió al último grupo de panzones que intentó atravesar nuestra puerta.', '', 28153),
(153867, 'esMX', 'Paciencia, Taelia. Sé que vendrán.', '', 28153),
(153866, 'esMX', '', '¿Podrá llegar a tiempo el resto de los Estela de la Tormenta?', 28153),
(153865, 'esMX', 'Envía a los bribones de regreso a su aldea en el lago del sudoeste para obtener una recompensa. Recuerda alejarte del agua... Allí es donde se originan los renacuajos, puaj.', '', 28153),
(153864, 'esMX', 'Parece que hay unos cuantos renacuajos múrloc merodeando por los alrededores.', '', 28153),
(153863, 'esMX', 'Nuestros exploradores informan que hay un carro de mineral robado cerca de la mina al noreste. Habrá que usar la violencia para recuperarlo.', '', 28153),
(153862, 'esMX', 'Hemos avistado algunos cortadores de leña de la Horda desprotegidos. ¿No es hora de salir a talar un poco?', '', 28153),
(153861, 'esMX', 'No olvides que a pesar de que es madera agresiva y con conciencia... no deja de ser madera. Y mucha.', '', 28153),
(153860, 'esMX', 'Se ha visto al Ramaseñor Aldrus en la línea de árboles.', '', 28153),
(153859, 'esMX', 'El gigante de piedra Fozruk está avanzando a pisotones por los caminos del sureste. Que no te aplaste.', '', 28153),
(153858, 'esMX', '¿Qué dices si le damos una paliza y lo arrojamos a la primera fila de la Horda?', '', 28153),
(153857, 'esMX', 'Hemos avistado un elemental de tierra enorme en las colinas al este.', '', 28153),
(153856, 'esMX', 'Soldados valientes de la Liga, es hora.', '', 28153),
(153855, 'esMX', '¡Cruzados, avancen sobre Ar\'gorok! ¡Es la voluntad de la Luz!', '', 28153),
(153854, 'esMX', 'La Horda intenta apoderarse de Filón de Galson. Enséñales que acá no se comparte nada, ¿sí?', '', 28153),
(153853, 'esMX', 'La Horda ataca a nuestros aliados en el Aserradero de Tierras Altas. Invítalos a irse... con violencia.', '', 28153),
(153852, 'esMX', 'Las fuerzas de la Horda han entrado a Stromgarde. Protege a tu comandante y muéstrales la salida, ¿de acuerdo?', '', 28153),
(153851, 'esMX', 'Están atacando Alto Pedestal. Sugiero que envíes a la Horda rodando colina abajo, ¿qué opinas?', '', 28153),
(153850, 'esMX', '', '¡Solo dilo y comenzaremos!', 28153),
(153849, 'esMX', '', 'La jefa de guerra espera que todos los héroes de la Horda estén atentos y preparados. Sugiero que aprovechemos este momento para entrenar.', 28153),
(153848, 'esMX', '', '¡Un gusto! Te doy la bienvenida al puesto Silithus, protegemos nuestra azerita de los ataques de la Alianza.', 28153),
(153847, 'esMX', 'Agitándose... retorciéndose... los susurros...', '', 28153),
(153846, 'esMX', 'Avísame cuando estés $ulisto:lista; para comenzar.', '', 28153),
(153845, 'esMX', 'Mientras patrullamos Silithus, aprovechemos el tiempo para pulir nuestras habilidades de batalla.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'esMX', '¡$uBienvenido:Bienvenida; a bordo! El rey Wrynn necesita a todos los héroes de la Alianza en su mejor forma para enfrentar a la Horda.', '', 28153),
(153843, 'esMX', 'Cuidado. Este puente le hace honor a su nombre.', '', 28153),
(153842, 'esMX', '', '¡Impresionante! Ahora pasemos a... Espera, ¿esa es...? ¡Prepárense para luchar! ¡La Alianza nos ataca!', 28153),
(153841, 'esMX', 'Una marea creciente... no hay escapatoria...', '', 28153),
(153840, 'esMX', '¡Defiendan los bancales! Denle a Zul el tiempo que necesita para aplastar a estas criaturas patéticas.', '', 28153),
(153839, 'esMX', 'Las fuerzas de la Horda se acercan al Círculo de Elementos. Quizá deberíamos darles una lección de magia.', '', 28153),
(153838, 'esMX', '', '¡Por mi padre!', 28153),
(153837, 'esMX', '', '¡No te lo haré fácil!', 28153),
(153836, 'esMX', '¡Bien hecho! Ahora pasemos a... Espera, ese es... ¡A las armas! ¡La Horda nos ataca!', '', 28153),
(153835, 'esMX', '', '¡Ha llegado tu hora!', 28153),
(153834, 'esMX', '', '¡Por Kul Tiras!', 28153),
(153833, 'esMX', 'La Horda ataca nuestra posición en Cruce Redilnorte. ¿Por qué no les enviamos unos tanques para agradecerles la hospitalidad?', '', 28153),
(153832, 'esMX', '', 'Metamorfosis te transforma en un demonio y potencia tu Golpe de caos y Danza de hojas.', 28153),
(153831, 'esMX', '', '¡Lucharemos a tu lado!', 28153),
(153830, 'esMX', 'La Horda marcha hacia Paso Valeroso. Esa es nuestra puerta de entrada. Ve y dales una calurosa bienvenida.', '', 28153),
(153829, 'esMX', 'Metamorfosis te transforma en un demonio y potencia tu Golpe de caos y Danza de hojas.', '', 28153),
(153828, 'esMX', 'La Horda está atacando Granovel. Terminemos con sus payasadas.', '', 28153),
(153827, 'esMX', '', 'Danza de hojas es un aluvión de ataques rápidos que golpean a todos los enemigos cercanos.', 28153),
(153826, 'esMX', 'Danza de hojas es un aluvión de ataques rápidos que golpean a todos los enemigos cercanos.', '', 28153),
(153825, 'esMX', '', 'Aunque es costoso, este es tu ataque más poderoso y debes usarlo siempre que puedas.', 28153),
(153824, 'esMX', 'Aunque es costoso, este es tu ataque más poderoso y debes usarlo siempre que puedas.', '', 28153),
(153823, 'esMX', '', 'Haz ocular derrite a tus enemigos con el caos demoníaco que arde en tu interior.', 28153),
(153822, 'esMX', 'Haz ocular derrite a tus enemigos con el caos demoníaco que arde en tu interior.', '', 28153),
(153821, 'esMX', '', 'Este es uno de tus ataques más poderosos. Úsalo con frecuencia para no desperdiciar Furia.', 28153),
(153820, 'esMX', 'Este es uno de tus ataques más poderosos. Úsalo con frecuencia para no desperdiciar Furia.', '', 28153),
(153819, 'esMX', 'Estaba en busca de ayuda, ¡y me topé contigo! Me ahorraste un viaje.', '', 28153),
(153818, 'esMX', 'Se acercan soldados de la Horda. Intenta detenerlos, ¿sí?', '', 28153),
(153817, 'esMX', '', 'Usa Abrumar contra el muñeco de práctica.', 28153),
(153816, 'esMX', 'Usa Abrumar contra el muñeco de práctica.', '', 28153),
(153815, 'esMX', 'Parece que hemos agitado el nido de avispas. La Horda nos está enviando todo lo que tiene.', '', 28153),
(153814, 'esMX', '', 'Este ataque también potencia tu siguiente Golpe mortal. Úsalo siempre que puedas.', 28153),
(153813, 'esMX', 'Este ataque también potencia tu siguiente Golpe mortal. Úsalo siempre que puedas.', '', 28153),
(153812, 'esMX', '', 'Abrumar utiliza tu inmensa fuerza para ejecutar un golpe crítico contra tu enemigo.', 28153),
(153811, 'esMX', 'Abrumar utiliza tu inmensa fuerza para asestarle un golpe devastador a tu enemigo.', '', 28153),
(153810, 'esMX', '', 'Recibiste daño, pero no es problema para ti.', 28153),
(153809, 'esMX', 'Recibiste daño, pero no es problema para ti.', '', 28153),
(153804, 'esMX', 'Usa Drenar vida para restablecer tu salud por completo.', '', 28153),
(153803, 'esMX', '', 'Usa Drenar vida para restablecer tu salud por completo.', 28153),
(153802, 'esMX', '', 'Drenar vida consume la fuerza vital de tu objetivo y te sana mientras le inflige daño.', 28153),
(153801, 'esMX', 'Drenar vida consume la fuerza vital de tu objetivo y te sana mientras le inflige daño.', '', 28153),
(153798, 'esMX', '', 'Usa Descarga de las sombras contra el muñeco de práctica.', 28153),
(153797, 'esMX', 'Usa Descarga de las sombras contra el muñeco de práctica.', '', 28153),
(153796, 'esMX', '', 'Lanza Descarga de las sombras cuando tus otros hechizos ya estén atormentando a tu víctima.', 28153),
(153795, 'esMX', 'Lanza Descarga de las sombras cuando tus otros hechizos ya estén atormentando a tu víctima.', '', 28153),
(153794, 'esMX', '', 'Después de afligir a tu objetivo con Agonía y Corrupción, continúa el ataque con magia de las sombras siniestra.', 28153),
(153793, 'esMX', 'Después de afligir a tu objetivo con Agonía y Corrupción, continúa el ataque con magia de las sombras siniestra.', '', 28153),
(153792, 'esMX', 'Las sombra\' te consumirán.', '', 28153),
(153791, 'esMX', '', 'Si usas Furia temible, podrás volver a usar Cólera de las bestias en menos tiempo.', 28153),
(153790, 'esMX', 'Si usas Furia temible, podrás volver a usar Cólera de las bestias en menos tiempo.', '', 28153),
(153789, 'esMX', '', '¡No toleraré tus acciones!', 28153),
(153788, 'esMX', '', 'Usa Furia temible mientras atacas al muñeco de práctica.', 28153),
(153787, 'esMX', 'Usa Furia temible mientras atacas al muñeco de práctica.', '', 28153),
(153786, 'esMX', '', 'Furia temible envía a tu mascota a atacar con furia para que puedas concentrarte en tus otras habilidades.', 28153),
(153785, 'esMX', 'Furia temible envía a tu mascota a atacar con furia para que puedas concentrarte en tus otras habilidades.', '', 28153),
(153784, 'esMX', '', 'También puedes ordenarle a tu mascota que ejecute un aluvión de ataques salvajes.', 28153),
(153783, 'esMX', 'También puedes ordenarle a tu mascota que ejecute un aluvión de ataques salvajes.', '', 28153),
(153782, 'esMX', '', 'Usa Bomba de fuego salvaje para quemar a todos los enemigos.', 28153),
(153781, 'esMX', 'Usa Bomba de fuego salvaje para quemar a todos los enemigos.', '', 28153),
(153780, 'esMX', '', 'Son aún más efectivas contra grupos, porque el fuego quema a los enemigos en un cono detrás de tu objetivo.', 28153),
(153779, 'esMX', 'Son aun más efectivas contra grupos porque el fuego quema a los enemigos en un cono detrás de tu objetivo.', '', 28153),
(153778, 'esMX', '', 'Puedes usar las Bombas de fuego salvaje para envolver a tus enemigos en llamas y quemarlos con el tiempo.', 28153),
(153777, 'esMX', 'Puedes usar las Bombas de fuego salvaje para envolver a tus enemigos en llamas y quemarlos con el tiempo.', '', 28153),
(153776, 'esMX', '', 'Usa Picadura de serpiente contra el muñeco de práctica.', 28153),
(153775, 'esMX', 'Usa Picadura de serpiente contra el muñeco de práctica.', '', 28153),
(153774, 'esMX', '', 'Picadura de serpiente dispara una flecha envenenada que inflige daño de naturaleza con el tiempo.', 28153),
(153773, 'esMX', 'Picadura de serpiente dispara una flecha envenenada que inflige daño de naturaleza con el tiempo.', '', 28153),
(153772, 'esMX', '', 'Tus habilidades de superviviente te otorgan herramientas poderosas para dañar a tus enemigos.', 28153),
(153771, 'esMX', 'Tus habilidades de superviviente te brindan herramientas poderosas para dañar a tus enemigos.', '', 28153),
(153770, 'esMX', 'Esa serpiente...', '', 28153),
(153769, 'esMX', '¡Que el viento te guíe!', '¡Que los vientos soplen a tu favor!', 28153),
(153768, 'esMX', '¡Aléjate de las sirenas!', '¡Aléjate de las sirenas!', 28153),
(153767, 'esMX', '¡Mi loa grita! ¡La herejía de Zul no tiene límite\'!', '', 28153),
(153766, 'esMX', '¡Cuídate del frío!', '¡Cuídate del frío!', 28153),
(153765, 'esMX', 'Recupera mi nave, $n. Después nos ocuparemo\' de los usurpadore\' que trataron de quedarse con mi trono.', '', 28153),
(153764, 'esMX', '¡Leven anclas!', '¡Leven anclas!', 28153),
(153763, 'esMX', '¡Adiós!', '¡Adiós!', 28153),
(153762, 'esMX', 'Los peces son raros.', 'Los peces son extraños.', 28153),
(153761, 'esMX', '¿Tienes escorbuto?', '¿Tienes escorbuto?', 28153),
(153759, 'esMX', 'He cumplido... con mi parte...', '', 28153),
(153758, 'esMX', 'Me gustan los tortollanos.', 'Me gustan los tortollanos.', 28153),
(153757, 'esMX', '¿Qué lado era estribor?', '¿Qué lado era estribor?', 28153),
(153756, 'esMX', '¡¡ARRR!! ¿Parezco un pirata?', '¡¡ARRR!! ¿Parezco una pirata?', 28153),
(153755, 'esMX', '¡Ah, del barco!', '¡Ah, del barco!', 28153),
(153754, 'esMX', '', 'Usa Matar muchas veces contra el muñeco de práctica.', 28153),
(153753, 'esMX', 'Usa Matar muchas veces sobre el muñeco de práctica.', '', 28153),
(153752, 'esMX', '', 'Matar le ordena a tu mascota que ejecute un ataque potente y genera Enfoque, que puedes gastar en tus otras habilidades.', 28153),
(153751, 'esMX', 'Matar le ordena a tu mascota que ejecute un ataque potente y genera Enfoque, que puedes gastar en tus otras habilidades.', '', 28153),
(153750, 'esMX', 'Papi dice que necesito mis piernas de marinero... ¡pero yo ya tengo dos piernas!', 'Papi dice que necesito mis piernas de marinero... ¡pero yo ya tengo dos piernas!', 28153),
(153749, 'esMX', '', 'Ahora que has acortado la distancia hasta tu presa, es tiempo de liberar tu furia.', 28153),
(153748, 'esMX', 'Ahora que has acortado la distancia con tu presa, es tiempo de liberar tu furia.', '', 28153),
(153747, 'esMX', 'Tengo... frío...', 'Tengo... frío...', 28153),
(153746, 'esMX', '¡Tú no perteneces aquí!', '¡Tú no perteneces aquí!', 28153),
(153745, 'esMX', 'Ciertamente. $n, ve a Kezan. Consigue las técnicas de refinamiento de azerita que nos prometieron... y procura que Mogul Razdunk sufra por haber faltado a la palabra que le dio a la Dama Oscura.', '', 28153),
(153744, 'esMX', 'Ese acuerdo solo nos traería problemas. Hay una forma más fácil de conseguir lo que queremos: sacar al intermediario. ¿Me entiendes?', '', 28153),
(153743, 'esMX', 'La jefa de guerra no estará complacida. Contábamos con los métodos de Razdunk para refinar azerita durante nuestra guerra contra la Alianza.', '', 28153),
(153742, 'esMX', 'Ay, pues disculpa, príncipe de las almas en pena. Perdón por estar un poco alterado porque casi me matan... ¡por un acuerdo al que me opuse desde un principio!', '', 28153),
(153741, 'esMX', 'No pierdas la calma, príncipe mercante. Ese parloteo no es digno de un líder de la Horda.', '', 28153),
(153740, 'esMX', '¡Mogul Razdunk nos ha traicionado! ¡Fue increíble! Nunca vi que ese maldito verduzco se arrepintiera de un acuerdo así. Nadie creería...', '', 28153),
(153739, 'esMX', 'Eh, señor Clamañublo. Traigo malas noticias...', '', 28153),
(153738, 'esMX', '', '¡Los trols de sangre... quieren más... de ese poder!', 28153),
(153737, 'esMX', '', '¡Poder! ¡PODER!', 28153),
(153736, 'esMX', 'Ai\'twen ha estado descansando, juntando energía para cuando se lo necesite de nuevo.', '', 28153),
(153735, 'esMX', 'Teletransporte a G\'huun.', 'Teletransporte a G\'huun.', 28153),
(153734, 'esMX', 'Teletransporte a Mythrax.', 'Teletransporte a Mythrax.', 28153),
(153733, 'esMX', 'Teletransporte a Descenso a las Ruinas.', 'Teletransporte a Descenso a las Ruinas.', 28153),
(153732, 'esMX', 'Teletransporte a la entrada de Uldir.', 'Teletransporte a la entrada de Uldir.', 28153),
(153731, 'esMX', 'Parece que la plataforma de desplazamiento está activa y estable.', 'Parece que la plataforma de desplazamiento está activa y estable.', 28153),
(153730, 'esMX', '¡Otro día, otra victoria!', '', 28153),
(153729, 'esMX', '¡Según los informes de mis guardias parece que los troggs preparan otro ataque! ¡Detenlos antes de que sea tarde!', '', 28153),
(153728, 'esMX', '¿Has terminado? Bien. Cuantos menos animales enloquecidos quieran devorarme vivo, mejor.', '', 28153),
(153727, 'esMX', '¿Osos embrujados...? ¡No! Mil veces no. Por favor, eh... encárgate de ellos.', '', 28153),
(153726, 'esMX', '', 'Me creerás loca, pero no me gustan tanto los árboles que caminan.', 28153),
(153725, 'esMX', '', 'Parece que hay problemas en el Patio de la Maderera Algerson otra vez. ¡Ayúdalos!', 28153),
(153724, 'esMX', '¡Excelente, $umi buen amigo:mi buena amiga;! Tú y tu compañero peludo forman un muy buen equipo.', '', 28153),
(153723, 'esMX', 'Níquel está ladrando porque quiere salir y cazar algunos halcones. ¿Por qué no lo llevas a hacer un poco de ejercicio?', '', 28153),
(153722, 'esMX', 'Ah, una cacería impresionante como siempre, $umi amigo;mi amiga;. ¡Felicitaciones!', '', 28153),
(153721, 'esMX', '¡Otro día, otra cacería! ¡Veamos qué presa consigues esta vez!', '', 28153),
(153720, 'esMX', 'Últimamente, han sucedido muchas cosa\' en la ciudad. Eh\'tar en el agua es mejor. Aquí hay tranquilidad.', '', 28153),
(153719, 'esMX', 'Hace algunos años, llegaron los naga\'. Sus mole\' derribaron el templo.', '', 28153),
(153718, 'esMX', 'Lo que pasó en Atal\'gral es muy triste.', '', 28153),
(153717, 'esMX', 'Todas las noche\' echo una mirada debajo de mi bote. Estos naga\' parecen eh\'tar en todas partes.', '', 28153),
(153716, 'esMX', 'Atal\'Gral', 'Atal\'Gral', 28153),
(153715, 'esMX', 'El puerto de Zuldazar', 'El puerto de Zuldazar', 28153),
(153714, 'esMX', '', 'Gral estuvo muy cerca.', 28153),
(153713, 'esMX', '', 'Ve a Atal\'gral. Guardo la esperanza de que el templo siga en pie.', 28153),
(153712, 'esMX', 'Con tu ayuda, Puntanzuelo recuperará su identidad.', '', 28153),
(153711, 'esMX', 'El poder de Celaoscuro en Puntanzuelo sigue siendo fuerte. ¡Debemos hacer lo posible para restaurar la normalidad en el muelle!', '', 28153),
(153710, 'esMX', 'Las aguas respiran con alivio. Has aplacado su dolor, y te lo agradezco.', '', 28153),
(153709, 'esMX', 'Necesitan ayuda en la bahía para limpiar la corrupción persistente. ¡Purga las aguas de las criaturas infectadas!', '', 28153),
(153708, 'esMX', 'Gracias, $uamigo mío:amiga mía;. ¡Las enviaré al puesto de avanzada de inmediato!', '', 28153),
(153707, 'esMX', 'Rosalina ha pedido más púas. ¿Podrías darme una mano?', '', 28153),
(153706, 'esMX', '¡Excelente, $uamigo mío:amiga mía! Eso le dará confianza a Majo por un tiempo.', '', 28153),
(153705, 'esMX', 'Nuestro amigo acorazado Majo ha estado trabajando en su equitación, pero necesita un poco de valor de vez en cuando. ¿Podrías buscar un poco de su bebida favorita?', '', 28153),
(153704, 'esMX', '', 'Espero que esos contrabandistas hayan aprendido la lección. ¡El crimen no paga!', 28153),
(153703, 'esMX', '', 'Estos contrabandistas creen que pueden escapar de Boralus con las armas de la milicia. ¡Demuéstrales que se equivocan!', 28153),
(153702, 'esMX', '¡Niños, huyan a un lugar seguro! ¡Rápido!', '¡Niños, huyan! ¡Rápido!', 28153),
(153701, 'esMX', 'No te preocupes, estoy detrás de ti...', 'No te preocupes, estoy detrás de ti...', 28153),
(153700, 'esMX', '¡Aquí, rápido!', '¡Aquí, rápido!', 28153),
(153699, 'esMX', 'Bueno, ya podemos encargarnos solos. Y mira eso, ¡todos conservan los dos ojos! ¡Bien hecho!', '', 28153),
(153698, 'esMX', '¡Los mares de Kul Tiras los tragarán a todos!', '¡Los mares de Kul Tiras los tragarán a todos!', 28153),
(153697, 'esMX', 'Que así sea. Mi familia está a salvo.', 'Que así sea. Mi familia está a salvo.', 28153),
(153696, 'esMX', '¡Pagarás por esto!', '¡Pagarás por esto!', 28153),
(153695, 'esMX', '¡Salvajes!', '¡Salvajes!', 28153),
(153694, 'esMX', '¡Esta plaza ha caído en las garras de las aves! Será mejor evacuar a los civiles antes de que las gaviotas les saquen los ojos. ¡Pero no les digas que dije eso!', '', 28153),
(153693, 'esMX', '¡Ayuda! ¡Sálvennos!', '¡Ayuda! ¡Sálvennos!', 28153),
(153692, 'esMX', 'Así no...', 'Así no...', 28153),
(153691, 'esMX', '¡Tengo miedo!', '¡Tengo miedo!', 28153),
(153690, 'esMX', 'Pero mis padres...', 'Pero mis padres...', 28153),
(153689, 'esMX', '¿Vamos a morir?', '¿Vamos a morir?', 28153),
(153688, 'esMX', '¿Por qué no te mueves? ¡Tengo miedo!', '¿Por qué no te mueves? ¡Tengo miedo!', 28153),
(153687, 'esMX', '¡Despierta! Por favor, despierta...', '¡Despierta! Por favor, despierta...', 28153),
(153686, 'esMX', '¡PAPI!', '¡PAPI!', 28153),
(153685, 'esMX', '¡MAMI!', '¡MAMI! ', 28153),
(153684, 'esMX', '¡Cuídate! ¡Que los viento\' te acompañen, $Uviajero:viajera;!', '', 28153),
(153683, 'esMX', '', 'Tu llegada hoy aquí estaba escrita en los pergaminos.', 28153),
(153682, 'esMX', 'Ahhh, $n. Sí. Ha demoh\'trado ser útil.', '', 28153),
(153681, 'esMX', 'Necesito una reparación.', 'Necesito una reparación.', 28153),
(153680, 'esMX', '', 'Recuerda descansar. No le sirves a la Alianza si estás $Uexhausto:exhausta;.', 28153),
(153679, 'esMX', '¡La Horda se ha apoderado del Círculo de los Elementos!', '¡La Horda se ha apoderado del Círculo de los Elementos!', 28153),
(153678, 'esMX', '¡$n ha capturado el Círculo de Elementos!', '¡$n ha capturado el Círculo de Elementos!', 28153),
(153677, 'esMX', '¡La Horda se ha apoderado del Filón de Galson!', '¡La Horda se ha apoderado de Filón de Galson!', 28153),
(153676, 'esMX', '¡$n ha capturado Filón de Galson!', '¡$n ha capturado Filón de Galson!', 28153),
(153675, 'esMX', '¡La Horda se ha apoderado de Cruce Redilnorte!', '¡La Horda se ha apoderado de Cruce Redilnorte!', 28153),
(153674, 'esMX', '¡$n ha capturado Cruce Redilnorte!', '¡$n ha capturado Cruce Redilnorte!', 28153),
(153673, 'esMX', '¡La Horda se ha apoderado de Alto Pedestal!', '¡La Horda se ha apoderado de Alto Pedestal!', 28153),
(153672, 'esMX', '¡$n ha capturado Alto Pedestal!', '¡$n ha capturado Alto Pedestal!', 28153),
(153671, 'esMX', '¡La Horda se ha apoderado de Granovel!', '¡La Horda se ha apoderado de Granovel!', 28153),
(153670, 'esMX', '¡$n ha capturado Granovel!', '¡$n ha capturado Granovel!', 28153),
(153669, 'esMX', '¡La Horda se ha apoderado del Aserradero de Tierras Altas!', '¡La Horda se ha apoderado del Aserradero de Tierras Altas!', 28153),
(153668, 'esMX', '¡$n ha capturado el Aserradero de Tierras Altas!', '¡$n ha capturado el Aserradero de Tierras Altas!', 28153),
(153667, 'esMX', '¡La Horda se ha apoderado de Paso Valeroso!', '¡La Horda se ha apoderado de Paso Valeroso!', 28153),
(153666, 'esMX', '¡$n ha capturado Paso Valeroso!', '¡$n ha capturado Paso Valeroso!', 28153),
(153665, 'esMX', 'Nuestras hazañas heroicas quedarán en los pergaminos de la historia militar.', '', 28153),
(153664, 'esMX', 'Nuestra brillante estrategia y su perfecta ejecución han confundido al enemigo.', '', 28153),
(153663, 'esMX', 'Creo que los atrapamos con los pantalones bajos.', '', 28153),
(153662, 'esMX', '', '¡Victoria! Ella... no lo logró...', 28153),
(153661, 'esMX', '', '¡Todos! ¡Sigan a Nathanos hasta el patio! ¡Yo bloquearé la retaguardia de la Alianza!', 28153),
(153660, 'esMX', '¡Soldados, en posición! ¡La Alianza se acerca!', '', 28153),
(153659, 'esMX', '', 'Los zandalari no saben el terror que se les avecina. Debemos advertirles.', 28153),
(153658, 'esMX', '', 'La reina Azshara planea algo, y no está sola.', 28153),
(153657, 'esMX', '', '¡Oh, vaya! Esto es terrible. ¡Estas son órdenes para matar a quienes sean leales a Gral!', 28153),
(153656, 'esMX', '¡Con nuestra presencia, los superaremos diez a uno!', '', 28153),
(153655, 'esMX', 'No me regreses al gólem...', 'Libera mi eh\'píritu. Por favor...', 28153),
(153654, 'esMX', 'Vamo\' por ti, Zak\'rajan...', 'Tú sigue\', Zak\'rajan...', 28153),
(153653, 'esMX', 'El fin... Lo eh\'peraba.', 'Al fin... Déjame deh\'cansar...', 28153),
(153652, 'esMX', 'Bwonsamdi... no dejará que muera...', '¿Dónde eh\'ta... el otro lado?', 28153),
(153651, 'esMX', '¡La fauna ha consumido el retoño!', '¡La fauna ha consumido el retoño!', 28153),
(153650, 'esMX', '¡AAAAAUUUGH!', '', 28153),
(153649, 'esMX', '¡La Horda no puede escapar!', '', 28153),
(153648, 'esMX', '¡Guardias! ¡Nos atacan! ¡A sus puestos! ¡Bajen las puertas, cierren las salidas!', '', 28153),
(153647, 'esMX', 'Excelente. ¡Andando!', '', 28153),
(153646, 'esMX', 'Claro.', 'Claro.', 28153),
(153645, 'esMX', 'Todos tus amigos fueron torturados y asesinados por brujas.', 'Todos tus amigos fueron torturados y asesinados por brujas.', 28153),
(153644, 'esMX', '¡Oh, vaya! Eso es terrible.\n\nYo tengo buenas noticias. Ya casi terminé de establecer una base aquí arriba en la colina. ¿Quieres ir a verla?', '', 28153),
(153643, 'esMX', 'Veo que vienes del bosque. ¿Cómo están los muchachos por allá?', '', 28153),
(153642, 'esMX', '¡Y después terminé de inventar este lobociclo!', '', 28153),
(153641, 'esMX', '¡Jefe, estás aquí! ¡Y has traído el triciclo!', '', 28153),
(153640, 'esMX', '1 minuto para que comience la batalla de Stromgarde.', '', 28153),
(153639, 'esMX', 'Juntos somos más fuertes.', '', 28153),
(153638, 'esMX', 'Nunca te rindas. Y sobrevive siempre.', '', 28153),
(153637, 'esMX', 'Ten cuidado.', '', 28153),
(153636, 'esMX', '¿Qué dije sobre no hacer nada eh\'túpido?', '', 28153),
(153635, 'esMX', 'Los Deh\'terrados te damo\' la bienvenida, $uviajero:viajera;.', '', 28153),
(153634, 'esMX', '¿Vinih\'te a dar una mano?', '', 28153),
(153633, 'esMX', '¿Qué te trae por aquí?', '', 28153),
(153632, 'esMX', 'Que el viento sople a tu favor.', '', 28153),
(153631, 'esMX', 'Fuerza y virtud.', '', 28153),
(153630, 'esMX', 'Ve con honor.', '', 28153),
(153629, 'esMX', 'Esta\' tierras se levantarán... en tu contra...', 'Esta\' tierras se levantarán... en tu contra...', 28153),
(153628, 'esMX', '¡No! Iba a arrancarte la cabeza...', '¡No! Iba a arrancarte la cabeza...', 28153),
(153627, 'esMX', 'Alianza... patética...', 'Alianza... patética...', 28153),
(153626, 'esMX', 'No durarás mucho má\'...', 'No durarás mucho má\'...', 28153),
(153625, 'esMX', 'El imperio... sigue vivo...', 'El imperio... sigue vivo...', 28153),
(153624, 'esMX', 'No dejaremo\' de venir...', 'No dejaremo\' de venir...', 28153),
(153623, 'esMX', 'Tienes mi atención.', '', 28153),
(153622, 'esMX', 'Eh\'to no ha terminado...', 'Eh\'to no ha terminado...', 28153),
(153621, 'esMX', 'Te damos la bienvenida.', '', 28153),
(153620, 'esMX', 'Por... la Horda.', 'Por... la Horda.', 28153),
(153619, 'esMX', 'Me darán una recompensa por tu cabeza.', 'Me darán una recompensa por tu cabeza.', 28153),
(153618, 'esMX', '¿Se creen más listos que nosotro\'? ¡Ja!', '¿Se creen más listos que nosotro\'? ¡Ja!', 28153),
(153617, 'esMX', '¡Nos llevaremo\' sus cabezas como trofeos!', '¡Nos llevaremo\' sus cabezas como trofeos!', 28153),
(153616, 'esMX', '¡No podrán encontrarno\' a todos!', '¡No podrán encontrarno\' a todos!', 28153),
(153615, 'esMX', '¿Quiere\' jugar un rato, Alianza?', '¿Quiere\' jugar un rato, Alianza?', 28153),
(153614, 'esMX', '¡Esta\' tierras les pertenecen a los Zandalari!', '¡Esta\' tierras les pertenecen a los Zandalari!', 28153),
(153613, 'esMX', '¡Te arrepentirá\' de haber venido!', '¡Te arrepentirá\' de haber venido!', 28153),
(153612, 'esMX', '¡No tienes nada que hacer en eh\'tas tierras!', '¡No tienes nada que hacer en eh\'tas tierras!', 28153),
(153611, 'esMX', 'Olvídalo. No somos como estos salvajes.', 'Olvídalo. No somos como estos salvajes.', 28153),
(153610, 'esMX', '¡No me iré sin ti!', '¡No me iré sin ti!', 28153),
(153609, 'esMX', '¡Maldita sea, claro que saldremos de aquí!', '¡Saldremos de aquí, te lo aseguro!', 28153),
(153608, 'esMX', '¡No te abandonaré!', '¡No te abandonaré!', 28153),
(153607, 'esMX', '¿Qué estás haciendo? ¡Sálvate!', '¿Qué estás haciendo? ¡Sálvate!', 28153),
(153606, 'esMX', '¡Ve a buscar ayuda! ¡Estaré bien!', '¡Ve a buscar ayuda! ¡Estaré bien!', 28153),
(153605, 'esMX', 'Sal de aquí, ya es tarde...', 'Sal de aquí, ya es tarde...', 28153),
(153604, 'esMX', 'Tienes que huir...', 'Tienes que huir...', 28153),
(153603, 'esMX', 'Te observo.', '', 28153),
(153602, 'esMX', 'Quizá la próxima vez sean más cuidadosos. Tuvieron suerte de que la Horda tuviera a alguien tan capaz como tú para rescatarlos.', '', 28153),
(153601, 'esMX', 'Nuestros aliados necesitan nuestra ayuda. Parece que los han capturado. Encárgate de que los liberen.', '', 28153),
(153600, 'esMX', 'Con esta información seguramente tendremos la ventaja contra la Alianza. Tus esfuerzos serán recompensados.', '', 28153),
(153599, 'esMX', 'Nuestros espías nos han informado que se entregará un mensaje importante en esta zona en cualquier momento. Intercéptalo como sea.', '', 28153),
(153598, 'esMX', 'Los loa te favorecen. ¡Eso es muy bueno! Pero no dejes que se te suba a la cabeza.', '', 28153),
(153597, 'esMX', 'Nueh\'tros enemigo\' están infeh\'tando el Jardín de los Loa otra vez y necesitan que alguien les enseñe modale\'. ¡Que el poder de los loa eh\'té contigo!', '', 28153),
(153596, 'esMX', 'Reunámonos en el puesto de avanzada. Debemos encontrar la respuesta. Esto huele a un posible levantamiento.', '', 28153),
(153595, 'esMX', 'No será un trabajo sutil, pero es necesario. Tenemos que mantener al enemigo en la oscuridad. Bien hecho.', '', 28153),
(153594, 'esMX', 'La Alianza ha enviado a sus espías a desenterrar nuestros secretos de las sombras. No dejaremos que descubran nuestros planes. Encárgate.', '', 28153),
(153593, 'esMX', 'La guerra contra la Alianza nos exterminará si no tenemos la flota zandalari.', '', 28153),
(153592, 'esMX', 'La Alianza no va a esperar a que construyamos una flota para atacarnos. Necesitamos a los zandalari.', '', 28153),
(153591, 'esMX', 'Haz que los zandalari se unan a la Horda.', '', 28153),
(153590, 'esMX', 'Necesitamos esa flota zandalari.', '', 28153),
(153589, 'esMX', 'Que se haga la voluntad de la jefa de guerra.', '', 28153),
(153588, 'esMX', 'Con Ai\'twen y tú de nuestro lado, el plan es infalible.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'esMX', 'Parece que no les gusto mucho a los zandalari.', '', 28153),
(153586, 'esMX', 'Portavoz de la Horda.', '', 28153),
(153585, 'esMX', 'La flota zandalari debe unirse a la Horda. Haz que suceda.', '', 28153),
(153584, 'esMX', '', '$UEste adalid:Esta adalid; desafió el poder de Ventormenta para salvarno\' a Zul y a mí. Su valor le ha ganado una audiencia, padre.', 28153),
(153583, 'esMX', 'Mi rey, la Horda solo ha venido a robar nueh\'tra flota para su jefa de guerra no-muerta.', '', 28153),
(153582, 'esMX', 'Tengo muy buena mercadería y no hago preguntas.', 'Tengo muy buena mercadería y no hago preguntas.', 28153),
(153581, 'esMX', 'Traigo suministros de Altamontaña.', 'Traigo suministros de Altamontaña.', 28153),
(153580, 'esMX', '(Ver los sucesos que llevaron a la herida de Azeroth)', '(Ver los sucesos que llevaron a la herida de Azeroth)', 28153),
(153579, 'esMX', '<La consola titánica muestra una serie de entradas de datos. Puedes seleccionar una de ellas para verla.>', '', 28153),
(153578, 'esMX', '¡Espero que tengas calzones ignífugos! ¡Ja, ja, ja!', '¡Espero que tengas calzones ignífugos!', 28153),
(153577, 'esMX', '¡Ey! ¡Esto está por ponerse acalorado! ¡Ja, ja!', '¡Esto está por ponerse acalorado!', 28153),
(153576, 'esMX', '¡Ah! ¡Hora de prenderte fuego!', '¡Hora de prenderte fuego!', 28153),
(153575, 'esMX', 'Ese \"enano de diamantes\" habla en nombre del alma del mundo. No intervendría de esta forma si la situación no fuera grave.', '', 28153),
(153574, 'esMX', '', 'Oh, ¿te lo imaginas? ¡El enano de diamante nos puede enviar a a todas partes de Azeroth!', 28153),
(153573, 'esMX', 'Me agrada este enano de diamantes teletransportador que concede dones poderosos. ¿Nos lo quedamos?', '', 28153),
(153572, 'esMX', 'No dudo que sea importante, Magni. Pero por el bien de los kultiranos... te pido que seas breve.', '', 28153),
(153571, 'esMX', 'Ven, adalid. ¡Azeroth nos llama!', '', 28153),
(153570, 'esMX', 'Ah, olvidé que la había vinculado a este lugar.', 'Ah, olvidé que la había vinculado a este lugar. Rayos.', 28153),
(153569, 'esMX', 'Ya estoy muy viejo para esto. ¡Me largo!', 'Ya estoy muy viejo para esto. ¡Me largo!', 28153),
(153568, 'esMX', 'Será mejor que se aliste, soldado.', 'Será mejor que se aliste, soldado.', 28153),
(153567, 'esMX', 'Señor, yo... me comportaré, señor.', 'Señor, yo... me comportaré, señor.', 28153),
(153566, 'esMX', 'Soldado James, ¿sus padres no le prestaban atención cuando era niño? ¿Por qué me hace perder el tiempo buscándolo por tierras desconocidas?', 'Soldado James, ¿sus padres no le prestaban atención cuando era niño? ¿Por qué me hace perder el tiempo buscándolo por tierras desconocidas?', 28153),
(153565, 'esMX', 'Sargento... gracias por venir a buscarme... señor', 'Sargento... gracias por venir a buscarme... señor', 28153),
(153564, 'esMX', '¡En marcha!', '¡En marcha!', 28153),
(153563, 'esMX', 'Es hora de emprender el regreso. Aterravermis pedirá un informe completo.', 'Es hora de emprender el regreso. Aterravermis pedirá un informe completo.', 28153),
(153562, 'esMX', '', 'Los zarzalomo no lograron matarme, y se arrepentirán.', 28153),
(153561, 'esMX', '', 'Creo que redecoraré cuando vuelva. Estaba pensando en una temática de colmillos.... ¿dónde podré encontrar algunos?$b$b<Deal sonríe con malicia.>', 28153),
(153560, 'esMX', '', 'Necesito un trago, después tengo que recuperar y reconstruir mi casa. ¡Gracias por matar tantos!', 28153),
(153559, 'esMX', 'No puedo quedarme demasiado, tengo que volver a mi granja. El alcalde me dijo que viniera a agradecerte por habernos ayudado con los zarzalomo.$b$bBuen trabajo, $Umuchacho:muchacha;.', '', 28153),
(153558, 'esMX', '¡Buen trabajo con esos jabaespines, $Uamigo:amiga;!', '', 28153),
(153557, 'esMX', 'No puedo quedarme demasiado. Necesitamos reparar a esos mozos de labranza para que arreglen los daños que produjeron en los campos.$b$bPero es importante tomarse un descanso de vez en cuando.', '', 28153),
(153556, 'esMX', 'Dejé al mozo de labranza en modo defensivo. Estoy seguro de que va a estar bien.', '', 28153),
(153555, 'esMX', 'Presta atención en el camino por si encuentras púas de jabaespín. Te sorprendería lo útiles que son como herramientas, ¡y hasta los jabaespines las usan como ingrediente en sus propios calderos!', '', 28153),
(153554, 'esMX', 'La Horda desde el norte, los jabaespines desde el oeste. ¿Ya no podemos confiar en la milicia?', '', 28153),
(153553, 'esMX', 'Espero que Rolf, Mort y Spiff hayan sobrevivido.', '', 28153),
(153552, 'esMX', '', 'Mis espía\' me dicen que a ustedes les es imposible ganar la guerra contra la Alianza sin nueh\'tra flota. \n\nPues bien... Eso significa que cada tarea que tenga que hacer hoy te la asignaré a ti, y la cumplirás. ¡O verás lo que pasa!', 28153),
(153551, 'esMX', '', 'Ya les he dicho mil vece\' a Zolani y a Talanji que el puerto es seguro. ¿Acaso no me escuchan? No.$b$b¿Que si hay peleas, rufianes y grescas? Por supuesto, pero nada tan dramático que amerite molestar al rey.', 28153),
(153550, 'esMX', 'Sígueme, por favor.', 'Sígueme, por favor.', 28153),
(153549, 'esMX', 'Hay algo que $n necesita ver. Un don que podría ayudar a esta tierra también.', '', 28153),
(153548, 'esMX', 'Tranquilos. Es Magni Barbabronce, que fue rey de Forjaz, y ahora es Portavoz de Azeroth.', '', 28153),
(153547, 'esMX', 'Bueno, ejem. Esto es nuevo.', '', 28153),
(153546, 'esMX', '¡Hechicería!', '', 28153),
(153545, 'esMX', '', '¡Guau, un enano de diamante!', 28153),
(153544, 'esMX', '¡Ahora libera el poder del Corazón!', '', 28153),
(153543, 'esMX', 'Estas son noticias terribles. Será mejor que informemos de esto al alto comandante.', 'Estas son noticias terribles. Será mejor que informemos de esto al alto comandante.', 28153),
(153542, 'esMX', '¡Korthek está loco! ¡Hay que detenerlo!', '¡Korthek está loco! ¡Hay que detenerlo!', 28153),
(153541, 'esMX', 'Korthek se hartó de la paz. Le dio la espalda al sacrificio de Sethraliss. Ahora se comporta estúpidamente: busca combinar las llaves y liberar al c\'thrax contra sus enemigos.', 'Korthek se hartó de la paz. Le dio la espalda al sacrificio de Sethraliss. Ahora se comporta estúpidamente: busca combinar las llaves y liberar al c\'thrax contra sus enemigos.', 28153),
(153540, 'esMX', 'El gran sabio Sulthis buscó mi ayuda y la de Korthek para levantar una barrera mágica e impedir el regreso del c\'thrax caído. Juramos que nunca dejaríamos que volviera a desatarse un terror semejante.', 'El gran sabio Sulthis buscó mi ayuda y la de Korthek para levantar una barrera mágica e impedir el regreso del c\'thrax caído. Juramos que nunca dejaríamos que volviera a desatarse un terror semejante.', 28153),
(153539, 'esMX', 'El poder que se liberó a causa de la destrucción fue inmenso. Nuestra tierra cambió para siempre.', 'El poder que se liberó a causa de la destrucción fue inmenso. Nuestra tierra cambió para siempre.', 28153),
(153538, 'esMX', 'Solo la intervención de nuestra loa nos salvó de la muerte. Sethraliss se sacrificó para vencerlo, pero antes el c\'thrax logró destruir una pirámide ancestral que se alzaba en el centro de estas tierras.', 'Solo la intervención de nuestra loa nos salvó de la muerte. Sethraliss se sacrificó para vencerlo, pero antes el c\'thrax logró destruir una pirámide ancestral que se alzaba en el centro de estas tierras.', 28153),
(153537, 'esMX', 'Hace mucho tiempo, antes de que las arenas comenzaran a dispersarse, un Belisario C\'Thraxxi monstruoso descendió sobre nuestras tierras. Y comenzó a asesinar a todos los que encontraba en su camino, fuesen trols o sethrak.', 'Hace mucho tiempo, antes de que las arenas comenzaran a dispersarse, un Belisario C\'Thraxxi monstruoso descendió sobre nuestras tierras. Y comenzó a asesinar a todos los que encontraba en su camino, fuesen trols o sethrak.', 28153),
(153536, 'esMX', '', 'Debemos estar atentos a la Horda. Siguen atacando la plaza.', 28153),
(153535, 'esMX', '', 'Si llegas a ver por ahí algo más que quiera invadir mi pueblo, te agradeceré que me avises.', 28153),
(153534, 'esMX', '', 'Todos cuentan conmigo para que guíe al pueblo. ¡No los defraudaré!', 28153),
(153533, 'esMX', '', 'Todos parecen estar fuera de peligro... por ahora.', 28153),
(153532, 'esMX', 'No es una piedra, es una llave. Es parte de un conjunto que se usa para guardar un poder enorme y terrible.', 'No es una piedra, es una llave. Es parte de un conjunto que se usa para guardar un poder enorme y terrible.', 28153),
(153531, 'esMX', '¡Ah! Hay una especie de piedra ahí adentro.', '¡Ah! Hay una especie de piedra ahí adentro.', 28153),
(153530, 'esMX', '\"Cuidado con la hija del mar\".', '\"Cuidado con la hija del mar\".', 28153),
(153529, 'esMX', 'Con su último aliento advirtió:', 'Con su último aliento advirtió:', 28153),
(153528, 'esMX', 'Una traición fatal.', 'Una traición fatal.', 28153),
(153527, 'esMX', '', 'Este enano prometió armar mejor a tu adalid para salvar a mi gente. Estoy dispuesta a asumir el riesgo.', 28153),
(153526, 'esMX', 'Su tumba fue el ancho mar.', 'Su tumba fue el ancho mar.', 28153),
(153525, 'esMX', 'pero ella no peleó.', 'pero ella no peleó.', 28153),
(153524, 'esMX', 'Los enfrentó con alma y con valor,', 'Los enfrentó con alma y con valor,', 28153),
(153523, 'esMX', '¡un enemigo hostil!', '¡un enemigo hostil!', 28153),
(153522, 'esMX', 'Mas encontró en esa costa ruin,', 'Mas encontró en esa costa ruin,', 28153),
(153521, 'esMX', 'La buscó con gran pesar.', 'La buscó con gran pesar.', 28153),
(153520, 'esMX', 'Para salvarla, él eligió zarpar.', 'Para salvarla, él eligió zarpar.', 28153),
(153519, 'esMX', 'Supongo que dejaremos que $Unuestro adalid: nuestra adalid; dé un paseo con el rey de diamantes, ¿verdad?', '', 28153),
(153518, 'esMX', 'su padre la siguió.', 'su padre la siguió.', 28153),
(153517, 'esMX', 'Cuando cruzó las aguas para huir,', 'Cuando cruzó las aguas para huir,', 28153),
(153516, 'esMX', '¿Por qué nos traicionó?', '¿Por qué nos traicionó?', 28153),
(153515, 'esMX', 'El pueblo entero siempre la adoró.', 'El pueblo entero siempre la adoró.', 28153),
(153514, 'esMX', '¿Por qué, si este siempre fue tu hogar?', '¿Por qué, si este siempre fue tu hogar?', 28153),
(153513, 'esMX', '¿Por qué? ¿Por qué? ¿Por qué, hija del mar?', '¿Por qué? ¿Por qué? ¿Por qué, hija del mar?', 28153),
(153512, 'esMX', 'porque lo abandonó.', 'porque lo abandonó.', 28153),
(153511, 'esMX', 'En Theramore su padre cayó,', 'En Theramore su padre cayó,', 28153),
(153510, 'esMX', 'la muerte los venció.', 'la muerte los venció.', 28153),
(153509, 'esMX', 'Sangre y dolor en Kalimdor se vio,', 'Sangre y dolor en Kalimdor se vio,', 28153),
(153508, 'esMX', 'cuando el mar lo devoró.', 'cuando el mar lo devoró.', 28153),
(153507, 'esMX', 'Su voz oí, sonaba sin cesar,', 'Su voz oí, sonaba sin cesar,', 28153),
(153506, 'esMX', '\"Cuidado\", pregonó.', '\"Cuidado\", pregonó.', 28153),
(153505, 'esMX', '\"Cuidado, ahí va, es la hija del mar\".', '\"Cuidado, ahí va, es la hija del mar\".', 28153),
(153504, 'esMX', 'Buen día, $r.', '', 28153),
(153502, 'esMX', '¿Tienes algo en los bolsillos?', '¿Tienes algo en los bolsillos?', 28153),
(153501, 'esMX', 'Yo me quedaré para encargarme de las defensas. Gracias de nuevo, $uamigo:amiga;.', 'Yo me quedaré para encargarme de las defensas. Gracias de nuevo, $uamigo:amiga;.', 28153),
(153500, 'esMX', '', '', 28153),
(153499, 'esMX', '', '¡Esbirros! ¡MÁTENLOS!', 28153),
(153498, 'esMX', 'No estaría aquí de no haber sido por ti y el sargento. Gracias de nuevo.', 'No estaría aquí de no haber sido por ti y el sargento. Gracias de nuevo.', 28153),
(153497, 'esMX', '', 'Yo informaré a Zul. Él decidirá si vale la pena que Rastakhan se involucre.', 28153),
(153496, 'esMX', '¡Mátenlos ante\' de que pasen!', '', 28153),
(153495, 'esMX', 'No nos detendremos hasta llegar a los muelle\'. Eh\'peramos tu orden, $n.', '', 28153),
(153494, 'esMX', '¿Tienes gana\' de morir?', '', 28153),
(153493, 'esMX', '¿Quieres que nos atrapen, $n?', '', 28153),
(153492, 'esMX', '¿Quieres que nos maten?', '', 28153),
(153491, 'esMX', '¡Eh! ¡Eh! ¡No huyas!', '', 28153),
(153490, 'esMX', '¡Vuelve aquí, colega!', '', 28153),
(153489, 'esMX', '¡Es $n, gracias a la Luz! Me dirigiré al templo. No es seguro aquí.', '', 28153),
(153488, 'esMX', 'Y reza para que nunca tengas que elegir.', '', 28153),
(153487, 'esMX', 'Debes saber distinguir entre la lealtad y el honor.', '', 28153),
(153486, 'esMX', '¿Qué quieres decir con eso?', '¿Qué quieres decir con eso?', 28153),
(153485, 'esMX', 'Después de todo lo que ella ha hecho, nunca volveré a su Horda.', '', 28153),
(153484, 'esMX', 'Crees que viniste para llevarme de regreso a Orgrimmar. Con la jefa de guerra. Estás $uequivocado:equivocada;.', '', 28153),
(153483, 'esMX', '¡Es hora de darle un golpe estratégico a Ventura y Cía.!', '', 28153),
(153482, 'esMX', 'Cuando tú digas, $n.', '', 28153),
(153477, 'esMX', '', 'No puedes morir aún. Tenemo\' cosas que hacer.', 28153),
(153476, 'esMX', '', 'No baile\' con Bwonsamdi, $n.', 28153),
(153475, 'esMX', '', 'Camina, se te pasará.', 28153),
(153474, 'esMX', '', 'De pie, $n. Aún no terminamo\'.', 28153),
(153473, 'esMX', '', 'Mi loa no te abandonará, $n.', 28153),
(153472, 'esMX', 'Parece que nuestros informes eran erróneos, no todos los sethrak son malos.', 'Parece que nuestros informes eran erróneos, no todos los sethrak son malos.', 28153),
(153471, 'esMX', '¡Este juego se puede jugar de a dos!', '¡Este juego se puede jugar de a dos!', 28153),
(153470, 'esMX', '', 'El nuevo imperio trol está delante de nosotro\'. ¡Nuestro largo aislamiento ha terminado!', 28153),
(153469, 'esMX', '', 'Zul predijo este día. Levántense... levántense, discípulo\' de la sangre. ¡Prepárense para la próxima era de eh\'te mundo!', 28153),
(153468, 'esMX', '¡No! No...', '¡No! No...', 28153),
(153467, 'esMX', 'Cómo te atreves a llevarte mi parte...', 'Cómo te atreves a llevarte mi parte...', 28153),
(153466, 'esMX', 'Te darán tu merecido...', 'Te darán tu merecido...', 28153),
(153465, 'esMX', '¡Héroes, síganme!', '', 28153),
(153464, 'esMX', 'Te... mataré...', 'Te... mataré...', 28153),
(153463, 'esMX', '¡Los mataré! ¡Los mataré a todos!', '¡Los mataré! ¡Los mataré a todos!', 28153),
(153462, 'esMX', '¿Creen que se pueden llevar mi parte así como así?', '¿Creen que se pueden llevar mi parte así como así?', 28153),
(153461, 'esMX', '¡Traidores! ¡Me quedaré con sus cabezas!', '¡Traidores! ¡Me quedaré con sus cabezas!', 28153),
(153460, 'esMX', '¡Traidores! ¡Todos ustedes!', '¡Traidores! ¡Todos ustedes!', 28153),
(153459, 'esMX', 'Capitana Eudora... llévanos a la victoria...', '', 28153),
(153458, 'esMX', '¿Carne fresca? ¡Ratas de sentina! ¡Hora de comer!', '', 28153),
(153457, 'esMX', 'Hoy, ¡los poderoso\' loa oirán sus gritoh\' de batalla y el sonido de sus espada\' en la batalla! Y los caídos se unirán a ellos... en el más allá.', '', 28153),
(153456, 'esMX', 'Concédele una muerte honorable...', '', 28153),
(153455, 'esMX', 'Concédele una muerte honorable...', '', 28153),
(153454, 'esMX', '¡¿Ahhhh?!', '', 28153),
(153453, 'esMX', 'Al má\' allá...', '', 28153),
(153452, 'esMX', 'Lo\' loa no te bendijeron hoy.', '', 28153),
(153451, 'esMX', '¡Por Zandalar!', '', 28153),
(153450, 'esMX', '¡Vendida! ¡Una espada cromática por 281 de oro! Ciertamente no podrás escabullirte con esta arma.', '', 28153),
(153449, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Misil buscador]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:260838|h[Misil buscador]|h|r!', 28153),
(153448, 'esMX', '¡Este día es de Kul Tiras!', '', 28153),
(153447, 'esMX', 'El suelo quedará decorado con ojos y narices el día de hoy.', '', 28153),
(153446, 'esMX', '¡Ey, ey! No se termina hasta que quede uno solo.', '', 28153),
(153445, 'esMX', '¡Ey! ¡Silencio! ¡La pelea no ha terminado!', '', 28153),
(153444, 'esMX', '¡Ey! ¡Tranquilos, ya correrá sangre! Tengan paciencia. ¡Jajajaja!', '', 28153),
(153443, 'esMX', '¡Vendido! ¡Un recuerdo embrujado por 18 de oro! Honestamente, no pagaría ni un centavo por esto. ¡Pero no es mi dinero!', '', 28153),
(153442, 'esMX', '¡No, no, no! Bien recuperado, bien recuperado.', '', 28153),
(153441, 'esMX', 'Mueres... pero no como $Uun auténtico kultirano:una auténtica kultirana;.', '', 28153),
(153440, 'esMX', '¡Ay, qué pena!', '', 28153),
(153439, 'esMX', '¡Esta noche es de Kul Tiras!', '', 28153),
(153438, 'esMX', 'Posiblemente no sea una pelea limpia, así que mantengan distancia, ¿sí? Ahora, ¿todos listos?', '', 28153),
(153437, 'esMX', 'El último que quede en pie se ganará ese honor.', '', 28153),
(153436, 'esMX', '¡Amigos! ¡Nos reunimos hoy aquí para decidir cuáles de estos bandidos, estos matones, estos malhechores, tienen derecho a considerarse verdaderos kultiranos!', '', 28153),
(153435, 'esMX', '¡Vendido! ¡Un gran cohete de amor para la hermosa señorita por 1412 de oro! ¡Ahora todos hablarán de ella en el pueblo!', '', 28153),
(153434, 'esMX', '¡Vendidos! ¡Los espaldares de acorazado van al joven de la primera fila por 756 de oro! No parece que vayas a poder usarlos, ¡pero qué importa!', '', 28153),
(153433, 'esMX', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Azerokk está lanzando |cFFFF0000|Hspell:257597|h[Infusión de azerita]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t ¡Azerokk está lanzando |cFFFF0000|Hspell:257597|h[Infusión de azerita]|h|r!', 28153),
(153432, 'esMX', '¡Traidora! ¡Atrápenla!', '', 28153),
(153431, 'esMX', 'Es vital para todos que Korthek no encuentre la llave. Ven, nuestro templo está más adelante.', '', 28153),
(153430, 'esMX', 'La guardé en el bolsillo de un prisionero que acababan de capturar. Creo que se llamaba James.', '', 28153),
(153429, 'esMX', '¡Esos necios! Me capturaron y me registraron, pero yo ya había escondido la llave en un lugar secreto, un lugar que no podrían adivinar.', '', 28153),
(153428, 'esMX', 'Pero Korthek nos traicionó y a Sulthis lo asesinaron. Ahora Korthek y sus seguidores, los infieles, están detrás de mí y mi llave.', '', 28153),
(153427, 'esMX', 'Hace mucho, nosotros tres —Korthek, Sulthis y yo— gobernábamos juntos. Nuestra loa nos encargó que protegiéramos tres llaves que mantenían un poder antiguo y malvado encerrado bajo las arenas.', '', 28153),
(153426, 'esMX', 'Nuestro templo es el último bastión contra los infieles.', '', 28153),
(153425, 'esMX', '', 'Sí, sí. Quizá tengamo\' un pequeño problema aquí abajo, pero no deberíamo\' preocupar a nuestro rey con algo así.', 28153),
(153424, 'esMX', '', 'La hora de forjar acuerdos con lo\' loa ha terminado. ¡Ha llegado la hora de la sangre!', 28153),
(153423, 'esMX', '', 'No te preocupes por alguno\' crímenes menores. Hay asuntos mucho más urgente\' que atender.', 28153),
(153421, 'esMX', '', '¡Espero que te gusten!', 28153),
(153419, 'esMX', '', 'Aquí tienes. No podía dejar que te marcharas con hambre, ¿no?', 28153),
(153418, 'esMX', '', 'Ahhh, ¡ahora sí! Perfecto.', 28153),
(153417, 'esMX', '', 'Un momento, cariño, tengo algo para ti.', 28153),
(153416, 'esMX', '¡Bien hecho! ¡Tu ataque causará estragos en el Imperio zandalari!', '', 28153),
(153415, 'esMX', 'Quisiera elegir a Pa\'ku, señora de los vientos.', 'Quisiera elegir a Pa\'ku, señora de los vientos.', 28153),
(153414, 'esMX', 'Quisiera elegir a Gonk, el jefe de la manada.', 'Quisiera elegir a Gonk, el jefe de la manada.', 28153),
(153413, 'esMX', 'Los zandalari creen que encadenar a una bestia entrenada los mantendrá a salvo. ¡Muéstrales que se equivocan!', '', 28153),
(153412, 'esMX', 'Finalmente, hemos recuperado Stromgarde.', '', 28153),
(153411, 'esMX', '¡Muere, escoria!', '', 28153),
(153410, 'esMX', 'Aprende a comportarte.', '', 28153),
(153409, 'esMX', 'Nadie llorará su muerte.', '', 28153),
(153408, 'esMX', 'Algún día, Stromgarde le pertenecerá UNA VEZ MÁS a la Alianza.', '', 28153),
(153407, 'esMX', '¡Que lluevan flechas sobre la Horda!', '', 28153),
(153406, 'esMX', '¡Tercera división, fuego!', '', 28153),
(153405, 'esMX', 'Me gustaría cambiar el loa de Zuldazar representado aquí.', 'Me gustaría cambiar el loa de Zuldazar representado aquí.', 28153),
(153404, 'esMX', '¡Arqueros, suelten flechas!', '', 28153),
(153403, 'esMX', '¡Levántense, ecos del pasado!', '', 28153),
(153402, 'esMX', '¡Los espíritus de Arathor los destruirán!', '', 28153),
(153401, 'esMX', 'El mal no podrá ocultarse, ni siquiera en estas tierras. Buen trabajo.', '', 28153),
(153400, 'esMX', 'Levántense, mis ancestros, y protejan su hogar.', '', 28153),
(153399, 'esMX', 'He matado a miles de los de tu clase. Eres igual a todos ellos.', '', 28153),
(153398, 'esMX', '¡Otra victoria para el Imperio zandalari! Buen trabajo, adalid de la Horda.', '', 28153),
(153397, 'esMX', 'Un mal plaga este lugar salvaje. ¡Encárgate de aniquilarlo!', '', 28153),
(153396, 'esMX', 'Una de las criaturas más poderosa\' de la selva amenaza este lugar. ¡Búscala y encárgate de ella!', '', 28153),
(153395, 'esMX', 'Los honrados siempre triunfan.', '', 28153),
(153394, 'esMX', '¡Te purificarás!', '', 28153),
(153393, 'esMX', 'Tu destino está decidido.', '', 28153),
(153392, 'esMX', 'Has sido juzgado.', '', 28153),
(153391, 'esMX', 'Stromgarde puede caer, pero la Alianza jamás será vencida.', '', 28153),
(153390, 'esMX', '¡Por el poder de la Luz!', '', 28153),
(153389, 'esMX', '¡Huye de la Luz, alimaña!', '', 28153),
(153388, 'esMX', 'La Luz te castigará.', '', 28153),
(153387, 'esMX', 'Otra amenaza eliminada, ¡y otra victoria para la Alianza!', '', 28153),
(153386, 'esMX', '¡La Luz triunfará!', '', 28153),
(153385, 'esMX', '', 'Soy el primer cronista. El rey me ha elegido para registrar nuestra historia en la piedra, para que se conserve durante siglos.', 28153),
(153384, 'esMX', '¡La Luz te purificará!', '', 28153),
(153383, 'esMX', 'Mi gente recordará tu nombre como adalid de lo\' Zandalari. ¡Bien hecho!', '', 28153),
(153382, 'esMX', '¡Que la Luz te purifique!', '', 28153),
(153381, 'esMX', '¡Por la Luz!', '', 28153),
(153380, 'esMX', 'El mal florece en esta tierra como vides asfixiantes. Hay que desarraigarlo para proteger nuestras tropas.', '', 28153),
(153379, 'esMX', 'No dejaré que este enemigo amenace a mi pueblo. ¡Aplástenlo!', '', 28153),
(153378, 'esMX', 'Con el camino despejado, podemos redoblar nuestros esfuerzos contra los zandalari. Gracias, adalid.', '', 28153),
(153377, 'esMX', 'Otro enemigo que cae en nombre del Imperio zandalari.', '', 28153),
(153376, 'esMX', 'Esta criatura desagradable amenaza nuestras fuerzas. Destrúyela, ¡por la Alianza!', '', 28153),
(153375, 'esMX', 'No toleraré una amenaza semejante dentro de mi\' fronteras. ¡Elimínala!', '', 28153),
(153374, 'esMX', 'Sube al triciclo cuando estés listo para partir.', '', 28153),
(153372, 'esMX', '', 'Estos nagas están atemorizados. Hay algo más que los impulsa. No es solo lealtad a la reina Azshara.', 28153),
(153371, 'esMX', '', 'Saludos.', 28153),
(153370, 'esMX', '¿Eso es todo lo que tienen? ¡Ja! ¡Dame un desafío de verdad!', '', 28153),
(153369, 'esMX', '¡Ja! ¡Hombre, qué divertido!', '', 28153),
(153368, 'esMX', 'No volverás a hacer eso.', '', 28153),
(153367, 'esMX', '¡Saluda a tus ancestros de mi parte!', '', 28153),
(153366, 'esMX', '¡No te saldrás con la tuya!', '', 28153),
(153365, 'esMX', '¡El secreto está en dónde pegarles!', '', 28153),
(153364, 'esMX', '¡Ja, ja, ja! ¡Así lo hacemos los enanos!', '', 28153),
(153363, 'esMX', '¡Fuera de aquí!', '', 28153),
(153362, 'esMX', '¡Por Khaz Modan!', '', 28153),
(153361, 'esMX', '¡Aquí te va un regalito!', '', 28153),
(153360, 'esMX', 'Esto es para ti.', '', 28153),
(153359, 'esMX', '¡Oye, tú! ¡Atrápalo!', '', 28153),
(153357, 'esMX', '¡Hasta aquí ha llegado tu pelea!', '', 28153),
(153351, 'esMX', 'Magni, ¿qué quiere darme Azeroth?', 'Magni, ¿qué quiere darme Azeroth?', 28153),
(153350, 'esMX', 'Ahora que los gorilas están controlados, podemos concentrarnos en la Horda. Buen trabajo.', '', 28153),
(153349, 'esMX', 'Estos gorilas han absorbido la esencia de kaja\'mita y ahora son mucho más inteligentes. No podemos dejar que salgan de su cañón.', '', 28153),
(153348, 'esMX', 'Lanzamiento N.U.K.L.E.A.R. detectado', 'Lanzamiento N.U.K.L.E.A.R. detectado', 28153),
(153347, 'esMX', 'La Horda ha caído muy bajo si piensa que puede hacernos prisioneros. Gracias a ti, nuestro pueblo es libre. ¡Bien hecho!', '', 28153),
(153346, 'esMX', 'No puedo descansar sabiendo que uno de mis hombres sigue allá afuera.', 'No puedo descansar sabiendo que uno de mis hombres sigue allá afuera.', 28153),
(153345, 'esMX', 'Nunca nos verán llegar. ¡Ja! Te lo agradezco, adalid.', '', 28153),
(153344, 'esMX', 'La Horda cree que puede espiar nuestra posición aquí en Zuldazar, ¡pero se equivocan! Déjenlos ciegos para que sepan que la Alianza sigue en pie.', '', 28153),
(153343, 'esMX', '¡No volveré a entrar a una de esas cosas sin una llave!', '¡No volveré a entrar a una de esas cosas sin una llave!', 28153),
(153342, 'esMX', '¡Un minuto más adentro de esa cosa y ya iba a patear traseros!', '¡Un minuto más adentro de esa cosa y ya iba a patear traseros!', 28153),
(153341, 'esMX', '¿Por qué Thurgaden nos dejaría en esas latas por tanto tiempo? ¡Fiuu!', '¿Por qué Thurgaden nos dejaría en esas latas por tanto tiempo? ¡Fiuu!', 28153),
(153340, 'esMX', '¡Hacía más calor que en los pantalones de Ragnaros!', '¡Hacía más calor que en los pantalones de Ragnaros!', 28153),
(153339, 'esMX', 'Enviaré a alguien para que le avise a Aterravermis que ya aseguramos el área. Gracias por la ayuda, $n.', '', 28153),
(153338, 'esMX', '¡Un día más en el trabajo!', '', 28153),
(153337, 'esMX', '¡Eso sí que fue aterrador!', '', 28153),
(153336, 'esMX', 'Invocamos poder de las Tierras de Fuego, pero nada peligroso responderá a nuestro llamado.', '', 28153),
(153335, 'esMX', 'No hay motivos para que te tiemble la barba, Thaelin. No soy tan tonto como el señor feudal hechicero Thaurissan.', '', 28153),
(153334, 'esMX', 'Ten cuidado con lo que invocas, señor feudal del yunque.', '', 28153),
(153333, 'esMX', 'Buena invocación, muchachos. Ya está bajo tu control, $n. ¡Muéstrales a esos mequetrefes de la Horda lo que pasa cuando se meten con los Hierro Negro!', '', 28153),
(153332, 'esMX', '$C, coloca un poco de esa escoria en el magma inestable. Y prepárate.', '', 28153),
(153331, 'esMX', '¡La batalla por Stromgarde ha comenzado!', '', 28153),
(153330, 'esMX', '30 segundos para que comience la batalla de Stromgarde.', '', 28153),
(153329, 'esMX', 'Sí, no hay problema.', '', 28153),
(153328, 'esMX', 'Oye, ¿te quedaste con la llave?', '', 28153),
(153327, 'esMX', 'Parece que mis chamanes siguen en las máquinas topo. Sabía que me estaba olvidando de algo.', '', 28153),
(153326, 'esMX', 'Creo que este es un buen comienzo. ¿Qué nos falta?', '', 28153),
(153325, 'esMX', 'No tienes idea de las fuerzas que están actuando aquí.', '', 28153),
(153324, 'esMX', '<Busca en el interior y saca algo que se parezca más a una edificación.>', '<Busca en el interior y saca algo que se parezca más a una edificación.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'esMX', '<Busca en el interior y saca algo.>', '<Busca en el interior y saca algo.>', 28153),
(153322, 'esMX', '<Un agujero de gusano se abre ante ti. Según parece, deberías ser capaz de usarlo de algún modo para construir una edificación.>', '', 28153),
(153321, 'esMX', 'No pongas a prueba mi paciencia, insecto. Muere.', '', 28153),
(153320, 'esMX', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t ¡El %s comienza a lanzar |cFFFF0000|Hspell:264382|h[Haz ocular]|h|r!', 'Aparece una proyección a la distancia...', 28153),
(153319, 'esMX', 'El mar e\' nuestro hogar. Pero hay algo que nos impide acercarno\'. ¡Espero que puedas ocuparte de eso!', '', 28153),
(153318, 'esMX', 'Irás a ver a los Buscadores, ¿verdad? Son fuerte\', estarás a salvo con ellos.', '', 28153),
(153317, 'esMX', 'Los barco\' desaparecían. Se desataban tormenta\' en lugare\' insólitos. Algunos sienten temor de acercarse al agua.', '', 28153),
(153316, 'esMX', 'Hubo rumore\' sobre cosas extrañas que sucedían cerca de la costa.', '', 28153),
(153315, 'esMX', 'Como desees.', '', 28153),
(153314, 'esMX', 'Y por favor... cuida de Jaina.', '', 28153),
(153313, 'esMX', 'Establece una base de operaciones en Kul Tiras. Nuestro plan no puede fracasar.', '', 28153),
(153312, 'esMX', 'Lleva una nave de la Séptima Legión como escolta.', '', 28153),
(153311, 'esMX', 'Mmm. Firme como siempre.', '', 28153),
(153310, 'esMX', 'Que las profundidades te rechacen, como tú rechazaste a tu pueblo.', '', 28153),
(153309, 'esMX', 'Solo defendías el odio y el sufrimiento.', '', 28153),
(153308, 'esMX', 'Escucha el despertar de la tormenta y acepta que es tu fin.', '', 28153),
(153307, 'esMX', 'No temas, tu juicio está por llegar.', '', 28153),
(153306, 'esMX', 'Dime, Genn... no te mareas en altamar, ¿cierto?', '', 28153),
(153305, 'esMX', 'Escucha los gritos de nuestro pueblo, y acepta que es tu hora.', '', 28153),
(153304, 'esMX', 'Ya no tienes redención.', '', 28153),
(153303, 'esMX', 'No has estado a la altura.', '', 28153),
(153302, 'esMX', 'Que tu alma languidezca por siempre.', '', 28153),
(153301, 'esMX', '', 'En cuanto encuentre un arma...', 28153),
(153300, 'esMX', '', 'No lograron matarme. Ese fue su primer error.', 28153),
(153299, 'esMX', '', 'Arruinan mi granja y se atreven a capturarme. ¡No se salvarán de esta!', 28153),
(153298, 'esMX', '¡No me iré hasta haber eliminado esta amenaza!', '¡No me iré hasta haber eliminado esta amenaza!', 28153),
(153297, 'esMX', '¡Pagarán por lo que hicieron!', '¡Pagarán por lo que hicieron!', 28153),
(153296, 'esMX', '¡Les debo una golpiza a estos jabaespines!', '¡Les debo una golpiza a estos jabaespines!', 28153),
(153295, 'esMX', '', 'Regresa y negociaremos cuando quieras.', 28153),
(153294, 'esMX', '', '¡Por fin estoy libre! Les mostraré a estos cerdos sucios lo que pasa cuando se meten con mi granja.', 28153),
(153293, 'esMX', '¡Miren quién se despertó! ¡Por fin!', '', 28153),
(153292, 'esMX', 'Cuidado... ahí va... es la hija del mar... Hmmmm...', '', 28153),
(153291, 'esMX', 'Saca... saca eso de mi vista. Yo solo... quiero ahogarme... ¡en mis copas! <¡hic!>', 'Saca... saca eso de mi vista. Yo solo... quiero ahogarme... ¡en mis copas! <¡hic!>', 28153),
(153290, 'esMX', 'El marido de mi hermana le dio un tallo marino antes de zarpar por cuatro meses. Al tercer día, la flor comenzó a marchitarse. Ella estaba loca de dolor, pero como lo supo enseguida, pudo administrar bien su dinero para que a sus hijos no les faltara nada.', 'El marido de mi hermana le dio un tallo marino antes de zarpar por cuatro meses. Al tercer día, la flor comenzó a marchitarse. Ella estaba loca de dolor, pero como lo supo enseguida, pudo administrar bien su dinero para que a sus hijos no les faltara nada.', 28153),
(153289, 'esMX', 'Tenemos catres arriba y espacio en el sótano para guardar tu equipo.\n\nNo es mucho, pero es mejor que estar ahí afuera con las brujas.', 'Tenemos catres arriba y espacio en el sótano para guardar tu equipo. No es mucho, pero es mejor que estar ahí afuera con las brujas.', 28153),
(153288, 'esMX', 'Algunos marinos los consideran mala suerte, casi como tentar al destino. Otros prefieren que sus seres queridos no tengan que esperar para enterarse de las malas noticias... Yo no me inclino por ninguna de las dos.', 'Algunos marinos los consideran mala suerte, casi como tentar al destino. Otros prefieren que sus seres queridos no tengan que esperar para enterarse de las malas noticias... Yo no me inclino por ninguna de las dos.', 28153),
(153287, 'esMX', 'Recuerda: mientras los árboles estén de pie, nosotros debemos resistir también. No podemos desperdiciar nuestra vida aquí.', '', 28153),
(153286, 'esMX', 'Intentemos encontrar a más de los nuestros. Juntos, quizás podamos aliviar un poco las aflicciones de Drustvar.', '', 28153),
(153285, 'esMX', '', '¡Pero...!', 28153),
(153284, 'esMX', 'Todo lo que era importante está en esa arboleda, retoño. Si los fungálidos no hubieran atacado, nos habría alcanzado la corrupción del sur.', '', 28153),
(153283, 'esMX', '', '¿Marcharnos? ¿A dónde? Xiloceniza es nuestro hogar, Morwin. Y está cubierto de esporas. ¡No podemos abandonarlo!', 28153),
(153282, 'esMX', 'Bien hecho, Amélie. Ahora supongo que deberíamos marcharnos.', '', 28153),
(153278, 'esMX', '¿Qué puedes contarme sobre este tallo marino?', '¿Qué puedes contarme sobre este tallo marino?', 28153),
(153277, 'esMX', 'Tamborileo', 'Tamborileo', 28153),
(153276, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Zuldazar.', '|cFF0000FF(Misión)|r Zarpar rumbo a Zuldazar.', 28153),
(153275, 'esMX', '¡Ah, mi fuerza regresa!', '', 28153),
(153274, 'esMX', 'Todo estaba tranquilo por aquí. Luego hubo una tormenta. Y los demás buscadores dejaron de regresar, $c. ¿Qué está pasando?', '', 28153),
(153273, 'esMX', 'Mi más sincero agradecimiento, y por la molestia, parte de mi alijo personal es tuyo. Ahora debo partir de inmediato, ¡buena suerte!', '', 28153),
(153272, 'esMX', 'Créeme, parece que me he metido en un embrollo. Sé $Ubueno:buena; y dame una mano.', '', 28153),
(153271, 'esMX', 'Oh, ¡gracias! Eres un encanto. Aquí tienes una pequeña muestra de agradecimiento. ¡Hasta luego!', 'Oh, ¡gracias! Eres un encanto. Aquí tienes una pequeña muestra de agradecimiento. ¡Hasta luego!', 28153),
(153270, 'esMX', '', '¡Oye, tú! ¡Tienes que ayudarme, cariño! Estoy sola y desesperada, ¿no ves?', 28153),
(153269, 'esMX', 'Eh, sabes que no puedo darte toda mi azerita. Aquí tienes suficiente como agradecimiento y ahora lárgate de aquí.', '', 28153),
(153268, 'esMX', 'Muy bien, ¿puedes ayudarme a salir de este embrollo?', '', 28153),
(153267, 'esMX', 'Mira, ¡es solo un disfraz! ¿Ves? ¡Tócalo!$b$b¿Ahora podrías decirles que me suelten? ¡Era una broma! Era mentira que Hogger estaba aterrorizando Ventormenta.', 'Mira, ¡es solo un disfraz! ¿Ves? ¡Tócalo!$b$b¿Ahora podrías decirles que me suelten? ¡Era una broma! Era mentira que Hogger estaba aterrorizando Ventormenta.', 28153),
(153266, 'esMX', '', '¡Gracias! Supongo que querrás un poco de mi azerita. Muy bien, es justo.', 28153),
(153265, 'esMX', '', '¡Oye! ¿Crees que puedes ayudarme con esto?', 28153),
(153264, 'esMX', '', 'Supongo que me lo merezco.', 28153),
(153263, 'esMX', '', 'Sufriré lo que tenga que sufrir...', 28153),
(153262, 'esMX', '¡Ha... ha vuelto para acabar con nosotros!', '', 28153),
(153261, 'esMX', '¡Asesina!', '¡Asesina!', 28153),
(153260, 'esMX', '¡Traidora!', '¡Traidora!', 28153),
(153259, 'esMX', '¡Es la hija del mar!', '', 28153),
(153258, 'esMX', '', 'Lady Jaina... ¿En verdad es ella?', 28153),
(153257, 'esMX', '', 'Nos vamos a casa. ¡Ahora!', 28153),
(153256, 'esMX', 'Mami, ¿quién es esa señora?', 'Mami, ¿quién es esa señora?', 28153),
(153255, 'esMX', 'Orson... basta de trufas para ti...', '', 28153),
(153254, 'esMX', 'Mi cabeza... ¡¿Qué les pasó a mis cerdos!?', '', 28153),
(153253, 'esMX', 'Contaré la historia de tu gran victoria hoy aquí. Así que... ¡debes ganar!', '', 28153),
(153252, 'esMX', '¡Regresa al Bosque Carmesí!', '¡Regresa al Bosque Carmesí!', 28153),
(153250, 'esMX', '¡Aparten a esos civiles! ¡Formen un perímetro!', '', 28153),
(153249, 'esMX', '%s huye.', '%s huye.', 28153),
(153248, 'esMX', '', 'Y ahora creen que soy una criminal.', 28153),
(153247, 'esMX', '', 'Veo que la guardia de la ciudad sigue tan disciplinada como siempre. Era el orgullo de mi padre.', 28153),
(153246, 'esMX', '¡No me apures! ¡Estoy tratando de salvar a tu amo!', '', 28153),
(153245, 'esMX', '¡Ey, $n! ¡Por aquí!', '¡Ey, $n! ¡Por aquí!', 28153),
(153244, 'esMX', '¡Qué mala suerte! Iba camino a Dol\'watha y mi beh\'tia se enfermó. Es como dicen: \"Todo lo que pueda salir mal, saldrá mal\".', '', 28153),
(153243, 'esMX', '¡Soy Rally!', '¡Soy Rally!', 28153),
(153242, 'esMX', 'Mucha sangre de la Horda para derramar por aquí. Guárdame un poco, ¿quieres?', 'Mucha sangre de la Horda para derramar por aquí. Guárdame un poco, ¿quieres?', 28153),
(153241, 'esMX', 'Queremos que sufra.', 'Queremos que sufra.', 28153),
(153240, 'esMX', 'Tenemos órdenes de matar a $Ueste:esta;.', 'Tenemos órdenes de matar a $Ueste:esta;.', 28153),
(153239, 'esMX', '', 'No te alejes, $uamigo:amiga;. No podemos arriesgarnos a que nos vean.', 28153),
(153238, 'esMX', '', 'Concéntrate, $n.', 28153),
(153237, 'esMX', '', '¿Acaso quieres que nos descubran?', 28153),
(153236, 'esMX', 'Oye, Boris... Creo que nuestros días de bandidos han terminado...', '', 28153),
(153235, 'esMX', '¡Quita las manos de mi bestia!', '', 28153),
(153234, 'esMX', '¡Esto sí me gusta! ¡Mira toda esta azerita!', '', 28153),
(153233, 'esMX', '¡Jefe! ¡Estás aquí!', '', 28153),
(153231, 'esMX', '¡Despejen el camino! ¡Aquí vienen prisioneros peligrosos!', '', 28153),
(153230, 'esMX', '¡Alto! ¡Declaren sus intenciones!', '', 28153),
(153229, 'esMX', '', 'Este no es el momento de alejarse.', 28153),
(153228, 'esMX', 'Ca-cállate.', '', 28153),
(153227, 'esMX', 'Ooohhh... Quizás lo mató... ¡UNA BRUJA!', '', 28153),
(153226, 'esMX', 'Otro de tus exploradores, Gallywix... Y este está muerto.', '', 28153),
(153225, 'esMX', '¡Debemos adentrarnos en la ciudad para evacuar a los civiles restantes!', '', 28153),
(153224, 'esMX', 'Cui... Cuidado...', '', 28153),
(153223, 'esMX', '', '¡Ya casi llegamos! ¡Rápido, héroes!', 28153),
(153222, 'esMX', '', '¡No se detengan!', 28153),
(153220, 'esMX', '¡Campeones, síganme! ¡Nos reuniremos en la fortaleza! ¡Su jefa de guerra lo ordena!', '', 28153),
(153217, 'esMX', '', '¡Colmillosauro! ¿Dónde estás?', 28153),
(153216, 'esMX', 'Ten cuidado, los campos colapsados todavía son peligrosos. El camino de la derecha debería ser un poco más seguro y llevarte al molino. La granja de Deal está apenas lo pasas.', '', 28153),
(153215, 'esMX', '', 'Si tienes deseos de luchar, serías de gran ayuda.', 28153),
(153214, 'esMX', '', 'Me he quedado sin pociones, y un grupo enorme de sethrak nos separa de mi carreta.', 28153),
(153213, 'esMX', '', '¿Aún vives? ¿Sabes usar esa arma?', 28153),
(153212, 'esMX', '', '¡Hoy no, hombres serpiente!', 28153),
(153211, 'esMX', 'Por favor, llévame de vuelta a la entrada.', 'Por favor, llévame de vuelta a la entrada.', 28153),
(153210, 'esMX', 'El avatar de Sethraliss rejuvenece gracias a tus esfuerzos y los de tus aliados.', 'El avatar de Sethraliss rejuvenece gracias a tus esfuerzos y los de tus aliados.', 28153),
(153209, 'esMX', 'Magni, envíame de vuelta a Zandalar.', 'Magni, envíame de vuelta a Zandalar.', 28153),
(153207, 'esMX', 'Ah, con esto podemos llegar a nuestro destino. Acompáñame, adalid.', '', 28153),
(153206, 'esMX', 'Derrota a los intrusos que queden.', 'Derrota a los intrusos que queden.', 28153),
(153205, 'esMX', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tEl avatar se une a ti, y te  |cFFFF0000|Hspell:269670|h[Potencia]|h|r para terminar la batalla.', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|tEl avatar se une a ti, y te  |cFFFF0000|Hspell:269670|h[Potencia]|h|r para terminar la batalla.', 28153),
(153204, 'esMX', '<Ves el avatar de Sethraliss ante ti. Aunque está viva, la intromisión de los trols la ha dejado muy débil. A tu alrededor, antiguos resguardos defensivos cobran vida con un destello...>', '<Ves el avatar de Sethraliss ante ti. Aunque está viva, la intromisión de los trols la ha dejado muy débil. A tu alrededor, antiguos resguardos defensivos cobran vida con un destello...>', 28153),
(153203, 'esMX', '|cffffff00+$1i de madera|r', '|cffffff00+$1i de madera|r', 28153),
(153202, 'esMX', '¡Ya oyeron a la princesa! ¡Fuego!', '', 28153),
(153201, 'esMX', '', '¡El eh\'cudo! ¡Se eh\'tá disipando!', 28153),
(153199, 'esMX', '¡Calma, calma! Fue una entrada abrupta, es cierto... Me llamo Magni Barbabronce, y te hablo en nombre de Azeroth.', '', 28153),
(153198, 'esMX', '', 'Ah, conque ahí eh\'tabas, $n. Ven, tenemo\' planes que dih\'cutir.', 28153),
(153197, 'esMX', 'Ah, conque ahí estabas, $n. ¡Tengo que hablar contigo!', '', 28153),
(153196, 'esMX', '[IGC - Audience with Katherine - Jaina leaves her fate in Katherine\'s hands. Urged by Lady Ashvane to treat Jaina as a traitor, Katherine allows Jaina to be taken away to face justice. \"She is already dead to me.\" Player is arrested.]', '[IGC - Audience with Katherine - Jaina leaves her fate in Katherine\'s hands. Urged by Lady Ashvane to treat Jaina as a traitor, Katherine allows Jaina to be taken away to face justice. \"She is already dead to me.\"]', 28153),
(153195, 'esMX', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:265212|h[Gestar]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t ¡Eres el objetivo de |cFFFF0000|Hspell:265212|h[Gestar]|h|r!', 28153),
(153194, 'esMX', '¡Te restauraremos!', '¡Te restauraremos!', 28153),
(153193, 'esMX', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t ¡Vectis comienza a |cFFFF0000|Hspell:265217|h[Licuar]|h|r!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t ¡Vectis comienza a |cFFFF0000|Hspell:265217|h[Licuar]|h|r!', 28153),
(153192, 'esMX', 'No le prestes atención a Gallywix. Nos dirigimos a Drustvar para explorar las posiciones de nuestro enemigo. Hacer dinero es un tema secundario.', '', 28153),
(153191, 'esMX', 'Ahora hay solo... silencio.', '', 28153),
(153190, 'esMX', 'Oh, muero...', '', 28153),
(153189, 'esMX', 'Asegúrate de que Eitrigg y el capitán estén listos. ¡Vamos a hacer dinero!', '', 28153),
(153188, 'esMX', 'Me has... aniquilado...', '', 28153),
(153187, 'esMX', 'De aquí en más... no diré ni una palabra.', '', 28153),
(153186, 'esMX', 'Espera, ¡basta!', '', 28153),
(153185, 'esMX', '$UVillano:Villana;, ¡me has asesinado!', '', 28153),
(153184, 'esMX', 'Oh, ¡muero!', '', 28153),
(153183, 'esMX', 'Ahora mi espíritu me abandona, ya no... puedo.', '', 28153),
(153182, 'esMX', '', 'No. No le causará\' más daño a mi pueblo. ¡Hah\'ta aquí ha llegado tu locura!', 28153),
(153180, 'esMX', '', '¡Así es, princesa!', 28153),
(153177, 'esMX', 'Tres dispositivos creados para sellar la corrupción. ', '', 28153),
(153174, 'esMX', '[Awesome cutscene.]', '[Awesome cutscene.]', 28153),
(153173, 'esMX', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Vectis lanza |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t ¡Vectis lanza |cFFFF0000|Hspell:266948|h[Bomba de peste]|h|r!', 28153),
(153172, 'esMX', '', '¿Un dio\' antiguo? Es por eso que los trols de sangre asaltan mi ciudad...', 28153),
(153171, 'esMX', 'Datos recuperados. La corrupción tiene su origen en el dios antiguo contenido en Nazmir.', '', 28153),
(153169, 'esMX', '...¡y 1,1 galones de tequila!', '...¡y 1,1 galones de tequila!', 28153),
(153168, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Drustvar.', '|cFF0000FF(Misión)|r Zarpar rumbo a Drustvar.', 28153),
(153167, 'esMX', '', 'El Lamento del Alma en Pena es una de las mejores naves de la Dama Oscura. Quizás no cause una gran impresión, pero es fuerte y resistente.\n\nY su capitana no está nada mal.', 28153),
(153166, 'esMX', 'Sí, estoy listo para ir a Drustvar.', 'Sí, estoy lista para ir a Drustvar.', 28153),
(153165, 'esMX', 'No dejes que ese goblin te confunda, $n. Nuestra tarea es reunir INFORMACIÓN sobre la Alianza, no solo recoger toda la azerita posible.\n\n¿Estás $Ulisto:lista; para partir?', '', 28153),
(153164, 'esMX', 'No dejes que el príncipe mercante te desvíe del camino. Nuestro interés principal son las tareas de reconocimiento, no las ganancias.', '', 28153),
(153163, 'esMX', 'Me dijeron que habría mucha azerita aquí esperándono\'. Lo único que tenemo\' que hacer es tomarla y eso depende de ti.\n\nSi te matan, ¡me quedo con tu sombrero! ¡Ja, ja!', '', 28153),
(153162, 'esMX', 'Continúa recuperando la salud del avatar de Sethraliss mientras te deshaces de los intrusos que queden.', 'Continúa recuperando la salud del avatar de Sethraliss mientras te deshaces de los intrusos que queden.', 28153),
(153161, 'esMX', 'Bien hecho, $n. Debemos estar atentos y proteger las tierras del templo de las arañas telaselva.', '', 28153),
(153160, 'esMX', 'Las arañas telaselva infestan las ruinas del templo. Elimina esta plaga y libera a mis seguidores atrapados en las telarañas.', '', 28153),
(153159, 'esMX', 'Recupera toda la salud del avatar.', 'Recupera toda la salud del avatar.', 28153),
(153158, 'esMX', '¡Malditas arañas!', '', 28153),
(153157, 'esMX', '¡Gracias, $n! Te debo la vida.', '', 28153),
(153156, 'esMX', '¡Ya puedo respirar de nuevo! ¡Gracias!', '', 28153),
(153155, 'esMX', '¡Esas arañas comen lo que sea!', '', 28153),
(153154, 'esMX', '¡Gracias! Eso estuvo cerca...', '', 28153),
(153153, 'esMX', '¡Creí que sería el fin!', '', 28153),
(153152, 'esMX', '¿Qué quieres de nosotros?', '¿Qué quieres de nosotros?', 28153),
(153151, 'esMX', 'No, por favor...', 'No, por favor...', 28153),
(153150, 'esMX', '', '¡Entonces, sube! $n, nos adelantaremos para buscar al maestro Ashton. ¡Reúnete con nosotros en el Bosque Carmesí!', 28153),
(153149, 'esMX', '¡Mis huesos! ¡El dolor!', '¡El dolor! ¡Mis huesos!', 28153),
(153148, 'esMX', 'Oh, cómo extrañé esto.', 'Oh, cómo extrañé esto.', 28153),
(153147, 'esMX', 'Me aburres. Hagamos que seas más... interesante.', 'Me aburres. Hagamos que seas más... interesante.', 28153),
(153146, 'esMX', 'Dime, ¿duele?', 'Dime, ¿duele?', 28153),
(153145, 'esMX', 'Supongo que sí.', '', 28153),
(153144, 'esMX', '', 'Marten, ¿estás en condiciones de viajar?', 28153),
(153143, 'esMX', 'Ahora que la ciudad está en buenas manos, ¿podrías explicarme qué sucede?', '', 28153),
(153142, 'esMX', '¡Por supuesto! No sé bien para qué necesitas mi ayuda, pero por los salvadores de mi casa, ¡te la daré!\n\nAunque quizá tengas que esperar un poco. Estoy seguro de que el pueblo es un caos.', '', 28153),
(153141, 'esMX', '¡Tenemos que salir de aquí!', '¡Tenemos que salir de aquí!', 28153),
(153140, 'esMX', '¿Otra vez ellos? ¡No!', '¿Otra vez ellos? ¡No!', 28153),
(153139, 'esMX', 'Estaría muerto de no ser por ti...', 'Estaría muerta de no ser por ti...', 28153),
(153138, 'esMX', '¡La Horda! ¿Qué están haciendo aquí?', '¡La Horda! ¿Qué están haciendo aquí?', 28153),
(153137, 'esMX', '¡Leva anclas, comandante!', '¡Leva anclas, comandante!', 28153),
(153136, 'esMX', 'Puedo llevarte hasta allí en lo que una gaviota monta vuelo. Dime cuando estés $Ulisto:lista;.', '', 28153),
(153135, 'esMX', '¿Buscas a Ashton? Ven, acompáñame. No lo he visto, pero sí vi a su aprendiz.', '', 28153),
(153134, 'esMX', 'Uf. Esto no es para cobardes... Ni para débiles...', '', 28153),
(153133, 'esMX', 'Una vez oí hablar de un bocadillo sabroso de un desierto al otro lado del mar. Tráeme alas de águila ratonera y aguijones de escórpido. Quiero probar una variante nueva. Algo con un toque especial.', '', 28153),
(153132, 'esMX', 'Manténgala firme, timonel.', 'Manténgala firme, timonel.', 28153),
(153131, 'esMX', '¡No, idiota, PARA EL OTRO LADO!', '¡No, idiota, AL OTRO LADO!', 28153),
(153130, 'esMX', 'LOS IMPUROS NO PASARÁN A LOS SALONES DE LOS MUERTOS.', '', 28153),
(153129, 'esMX', 'NO PUEDEN PASAR.', '', 28153),
(153128, 'esMX', 'NO ENTRARÁN.', '', 28153),
(153127, 'esMX', 'Nos vemos.', '', 28153),
(153126, 'esMX', 'Ey.', '', 28153),
(153125, 'esMX', '', 'No fui una buena maestra.', 28153),
(153124, 'esMX', '', 'Es la hora del recreo.', 28153),
(153123, 'esMX', '', 'Todos pueden... retirarse.', 28153),
(153122, 'esMX', '', '¡Ha comenzado la clase!', 28153),
(153121, 'esMX', '', 'Es hora de que aprendas las tres \"R\": ¡runas, rituales y reliquias!', 28153),
(153120, 'esMX', '', '¡Te enseñaré una lección!', 28153),
(153119, 'esMX', '¿Quién vigilará las reservas ahora?', '', 28153),
(153118, 'esMX', 'Este lote... se ha arruinado.', '', 28153),
(153117, 'esMX', '¡No puedes tocar nuestras bodegas!', '', 28153),
(153116, 'esMX', '¡Esta colección es solo para invitados!', '', 28153),
(153115, 'esMX', '¡Excelente! Estas semillas nos durarán un largo rato... si no me las como todas de una vez.', '', 28153),
(153114, 'esMX', 'La vida se adapta de formas extrañas para sobrevivir aquí. Los azotadores tienen semillas muy resistentes, ¡y sabrosísimas! Recoge algunas para nosotros, ¡pero cuidado con las espinas!', '', 28153),
(153113, 'esMX', '... Me gusta tu forma de pensar, Walt.', '', 28153),
(153112, 'esMX', 'Aunque... ya nos pagaron. ¿Por qué no decimos en Vadoarlén que nos atacaron... y nos tomamos la hidromiel?', '', 28153),
(153111, 'esMX', 'Muy bien... Creo que ya no hay peligro. Llevemos estos barriles a Vadoarlén.', '', 28153),
(153110, 'esMX', 'Yo buscaré pistas sobre el paradero de James mientras tú te encargas de la nave. No lo dejaré en las garras de esos sucios bastardos.', 'Yo buscaré pistas sobre el paradero de James mientras tú te encargas de la nave. No lo dejaré en las garras de esos sucios bastardos.', 28153),
(153109, 'esMX', '¡Esa cosa rebalsa de miel!', '', 28153),
(153108, 'esMX', '¡Ven aquí, maldita gaviota!', '', 28153),
(153107, 'esMX', 'Bueno... no voy a estar más listo que esto. ¡Danos tu mejor golpe, naturaleza!', '', 28153),
(153106, 'esMX', '¡Hagámoslo!', '¡Hagámoslo!', 28153),
(153105, 'esMX', 'En cualquier momento llegarán más bestias feroces, $c. ¡Protege la hidromiel como si tu vida dependiera de eso!', '', 28153),
(153103, 'esMX', '¡Ánimo, Bradford! ¡No podemos darnos por vencidos!', '', 28153),
(153102, 'esMX', 'Bien, Walt, este es nuestro fin. No sé cuántas más de estas bestias podemos repeler.', '', 28153),
(153101, 'esMX', '%s apunta un cañón de azerita cargado a la torre de asedio.', '', 28153),
(153100, 'esMX', '¡$n! ¡Te necesitamos, pronto!', '¡$n! ¡Te necesitamos, pronto!', 28153),
(153099, 'esMX', 'Maldición, Leonard, ¡no te di permiso para que te marcharas!', 'Maldición, Leonard, ¡no te di permiso para que te marcharas!', 28153),
(153098, 'esMX', 'Los demás, síganme. Vamos a rodearlos por el flanco.', 'Los demás, síganme. Vamos a rodearlos por el flanco.', 28153),
(153097, 'esMX', 'Fascinante. Estas pequeñas viajeras son fascinantes. Me pregunto qué historias contarán.', '', 28153),
(153096, 'esMX', 'Por lo general, las mapirosas solo viven unos meses, pero estas de aquí son diferentes. Atrápame algunas. Ten cuidado, son muy delicadas.', '', 28153),
(153093, 'esMX', '', '¿Quién protegerá las tierras ahora?', 28153),
(153092, 'esMX', '', 'Vuelvo a la tierra.', 28153),
(153091, 'esMX', '', 'Serás un buen fertilizante.', 28153),
(153090, 'esMX', '', '¡Cosecharás lo que siembras!', 28153),
(153089, 'esMX', '', '¡Intrusos en mi jardín!', 28153),
(153088, 'esMX', '', 'En jirones.', 28153),
(153087, 'esMX', '', 'Mi trama... se revela.', 28153),
(153086, 'esMX', '', '¡Mi tejido presagia tu destrucción!', 28153),
(153085, 'esMX', '', '¡Se acerca tu fin!', 28153),
(153084, 'esMX', '', '¡Bordaré mi tapiz con sus almas!', 28153),
(153083, 'esMX', 'Una buena cacería en la que terminar.', '', 28153),
(153082, 'esMX', 'Qué ferocidad.', '', 28153),
(153081, 'esMX', 'Nunca pensé... que el trofeo sería yo.', '', 28153),
(153080, 'esMX', '¡Hora de atacar!', '', 28153),
(153079, 'esMX', '¡Serán trofeos perfectos para lucir en mi pared!', '', 28153),
(153078, 'esMX', '¡Que comience la cacería!', '', 28153),
(153077, 'esMX', '¡Carne fresca para asar!', '', 28153),
(153076, 'esMX', '¡La cena está lista!', '', 28153),
(153075, 'esMX', 'Debemos abrir el santuario una vez más. ¡Nuestra redención está cerca!', '', 28153),
(153074, 'esMX', 'Esta oscuridad no bloqueará nuestro camino.', '', 28153),
(153073, 'esMX', 'Bien hecho. ¡Jamás olvidaremos a los valerosos alfazaques de barranco que se sacrificaron heroicamente para salvarnos del terror del rey Rakataka!', '', 28153),
(153072, 'esMX', 'Nosotros matamos por mucho menos, sabes.', '', 28153),
(153071, 'esMX', 'Parece que la disciplina y el tacto no son tus mejores recursos.', '', 28153),
(153070, 'esMX', 'Todo tiene valor. Incluso tú.', '', 28153),
(153069, 'esMX', 'Las arenas devoran a los derrochadores.', '', 28153),
(153068, 'esMX', 'Las arenas nos mostrarán el camino.', '', 28153),
(153067, 'esMX', 'Vamos a donde nos lleven las arenas.', '', 28153),
(153066, 'esMX', 'Las dunas tienen todo lo que necesitamos.', '', 28153),
(153065, 'esMX', 'Para sobrevivir en las arenas hay que apreciar el valor de lo abandonado.', '', 28153),
(153064, 'esMX', 'Recuerda, todo tiene valor.', '', 28153),
(153063, 'esMX', 'Habla sin reservas.', '', 28153),
(153062, 'esMX', 'Hola.', '', 28153),
(153061, 'esMX', '¿Qué has traído?', '', 28153),
(153060, 'esMX', '¿Has venido a comerciar?', '', 28153),
(153059, 'esMX', '¿Necesitas algo?', '', 28153),
(153058, 'esMX', '', 'Zandalar resih\'tirá.', 28153),
(153057, 'esMX', '', 'Ve con cuidado.', 28153),
(153056, 'esMX', '', 'Nadie se merece un deh\'tino como las dunas.', 28153),
(153055, 'esMX', '', '¿Qué puedo hacer por ti?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'esMX', '', 'Habla, rápido.', 28153),
(153053, 'esMX', '', 'Te eh\'cucho.', 28153),
(153052, 'esMX', '', '¿Sí?', 28153),
(153051, 'esMX', 'Nunca nos rendiremos.', 'Nunca nos rendiremos.', 28153),
(153050, 'esMX', 'El imperio infiel caerá.', 'El imperio infiel caerá.', 28153),
(153049, 'esMX', 'Que Sethraliss nos proteja.', 'Que Sethraliss nos proteja.', 28153),
(153048, 'esMX', 'Korthek es culpable de esta guerra.', 'Korthek es culpable de esta guerra.', 28153),
(153047, 'esMX', 'No podemos flaquear.', 'No podemos flaquear.', 28153),
(153046, 'esMX', '¿Has venido a ayudar?', '¿Has venido a ayudar?', 28153),
(153045, 'esMX', '¡El rey Rakataka aterroriza Garganta Sendahuesos! No podemos atacarlo de frente, pero tiene un apetito insaciable. ¡Aliméntalo hasta que muera!', '', 28153),
(153044, 'esMX', 'Nosotros matamos por mucho menos, sabes.', 'Nosotros matamos por mucho menos, sabes.', 28153),
(153043, 'esMX', 'Parece que la disciplina y el tacto no son tus mejores recursos.', 'Parece que la disciplina y el tacto no son tus mejores recursos.', 28153),
(153042, 'esMX', 'Todo tiene valor, incluso tú.', 'Todo tiene valor, incluso tú.', 28153),
(153041, 'esMX', 'Sé veloz. Sé sagaz.', 'Sé veloz. Sé sagaz.', 28153),
(153040, 'esMX', 'Solo los ingeniosos sobreviven.', 'Solo los ingeniosos sobreviven.', 28153),
(153039, 'esMX', 'Recuerda, ¡todo tiene valor!', 'Recuerda, ¡todo tiene valor!', 28153),
(153038, 'esMX', 'Las dunas tienen todo lo que necesitamos.', 'Las dunas tienen todo lo que necesitamos.', 28153),
(153037, 'esMX', 'Cuídate. Nadie lo hará por ti.', 'Cuídate. Nadie lo hará por ti.', 28153),
(153036, 'esMX', 'Procura no morir ahí afuera.', 'No mueras allí.', 28153),
(153035, 'esMX', '¿Qué me has traído?', '¿Qué me has traído?', 28153),
(153034, 'esMX', '¿Necesitas algo?', '¿Necesitas algo?', 28153),
(153033, 'esMX', '¿Has venido a comerciar?', '¿Has venido a comerciar?', 28153),
(153032, 'esMX', 'Hola.', 'Hola.', 28153),
(153031, 'esMX', '¿Qué tienes para mí?', '¿Qué tienes para mí?', 28153),
(153030, 'esMX', '¡Tráeme un premio de tu próxima aventura!', '¡Tráeme un premio de tu próxima aventura!', 28153),
(153029, 'esMX', '¿Ya somos amigos?', '¿Ya somos amigos?', 28153),
(153028, 'esMX', 'Gracias por hablar conmigo.', 'Gracias por hablar conmigo.', 28153),
(153027, 'esMX', '¿Estás en medio de una gran aventura? ¡Qué increíble!', '¿Estás en medio de una gran aventura? ¡Qué increíble!', 28153),
(153026, 'esMX', '¿Alguna vez tomaste sopa porque querías?', '¿Alguna vez tomaste sopa porque querías?', 28153),
(153025, 'esMX', 'Si mueres, ¿puedo quedarme con tus cosas?', 'Si mueres, ¿puedo quedarme con tus cosas?', 28153),
(153024, 'esMX', 'Nunca nos rendiremos.', '', 28153),
(153023, 'esMX', 'El imperio de los infieles caerá.', '', 28153),
(153022, 'esMX', 'Que Sethraliss nos proteja.', '', 28153),
(153021, 'esMX', 'Korthek es culpable de esta guerra.', '', 28153),
(153020, 'esMX', 'Debemos mantenernos fuertes.', '', 28153),
(153019, 'esMX', '¿Has venido a ayudar?', '', 28153),
(153018, 'esMX', 'Cumplimos con nuestro deber.', '', 28153),
(153017, 'esMX', 'Sethraliss nos salvará.', '', 28153),
(153016, 'esMX', 'Los infieles no tomarán nuestro templo.', '', 28153),
(153015, 'esMX', 'Korthek es culpable de esta guerra.', '', 28153),
(153014, 'esMX', 'Debemos mantenernos fuertes.', '', 28153),
(153013, 'esMX', '¿Has venido a ayudar?', '', 28153),
(153012, 'esMX', '', 'No deberíamos haberte salvado. Oh. ¡Espera! No quise decir eso...', 28153),
(153011, 'esMX', '', '¡¿Lo hiciste de nuevo!?', 28153),
(153010, 'esMX', '', 'Deberías dejar de hacer eso.', 28153),
(153009, 'esMX', '', '¿Qué haces?', 28153),
(153008, 'esMX', '', 'Je, je, je. Volverás, ¿cierto?', 28153),
(153007, 'esMX', '', '¡Ey, intenta no morir!', 28153),
(153006, 'esMX', '', 'Nunca es seguro viajar sin compañía.', 28153),
(153005, 'esMX', '', 'A Dolly le gustas. Puedo verlo.', 28153),
(153004, 'esMX', '', 'Conozco estas dunas mejor que nadie.', 28153),
(153003, 'esMX', '', '¡Uh! ¡Hola!', 28153),
(153002, 'esMX', '', '¡Yo puedo ayudar!', 28153),
(153001, 'esMX', '', 'La ciudad no caerá.', 28153),
(153000, 'esMX', '', 'Ve con cuidado.', 28153),
(152999, 'esMX', '', 'Mi deber e\' defender a la familia real.', 28153),
(152998, 'esMX', '', 'Resih\'tiremos.', 28153),
(152997, 'esMX', '', 'Habla, rápido.', 28153),
(152996, 'esMX', '', '¿Sí?', 28153),
(152995, 'esMX', '', 'Te eh\'cucho.', 28153),
(152994, 'esMX', 'Que las arenas engullan mis pecado\'.', '', 28153),
(152993, 'esMX', 'Las arena\' nunca serán segura\'.', '', 28153),
(152992, 'esMX', 'No todo puede deshacerse.', '', 28153),
(152991, 'esMX', '¿Qué necesitas?', '', 28153),
(152990, 'esMX', 'Si puedo ayudar, lo haré.', '', 28153),
(152989, 'esMX', 'Me merezco mi deh\'tino.', '', 28153),
(152988, 'esMX', 'Vete, mientra\' puedas.', '', 28153),
(152987, 'esMX', 'No te quitaré los ojo\' de encima.', '', 28153),
(152986, 'esMX', 'Ten cuidado.', '', 28153),
(152985, 'esMX', 'Tú no tiene\' nada que hacer aquí.', '', 28153),
(152984, 'esMX', 'No tengo tiempo para ti.', '', 28153),
(152983, 'esMX', '¿Qué quieres?', '', 28153),
(152982, 'esMX', 'Que la tormenta te guíe.', '', 28153),
(152981, 'esMX', 'No le temas a la tormenta.', '', 28153),
(152980, 'esMX', 'La calma sucede a la tormenta.', '', 28153),
(152979, 'esMX', 'La tormenta llama.', '', 28153),
(152978, 'esMX', 'Aquí todos son bienvenidos.', '', 28153),
(152977, 'esMX', 'Soy la tormenta.', '', 28153),
(152976, 'esMX', '¿Qué te trae por aquí?', '', 28153),
(152975, 'esMX', '¡A comer!', '', 28153),
(152973, 'esMX', '', 'Me vendría bien un nuevo casco...', 28153),
(152972, 'esMX', '', 'Eso me recuerda... Una vez un sethrak quiso tocarme. Fue una sola vez.', 28153),
(152971, 'esMX', '', '', 28153),
(152970, 'esMX', '', 'Viento a favor, espada en mano.', 28153),
(152969, 'esMX', '', 'Que los invada el terror.', 28153),
(152968, 'esMX', '', 'Déjame unos sethrak.', 28153),
(152967, 'esMX', '', 'Nunca dejes de luchar.', 28153),
(152966, 'esMX', '', '', 28153),
(152965, 'esMX', '', 'Hoy es un buen día para pelear. ¡Como todos!', 28153),
(152964, 'esMX', '', 'Los vulperas somos más fuertes de lo que parece.', 28153),
(152963, 'esMX', '', 'Mi pueblo será libre.', 28153),
(152962, 'esMX', '', 'Estoy lista para pelear.', 28153),
(152961, 'esMX', 'Mi vida por el rey.', '', 28153),
(152960, 'esMX', 'Mantén las arma\' listas.', '', 28153),
(152959, 'esMX', 'Que lo\' loa te acompañen.', '', 28153),
(152958, 'esMX', 'Zandalar se mantiene firme.', '', 28153),
(152957, 'esMX', 'Me enfrentaré al peligro.', '', 28153),
(152956, 'esMX', 'Nuestros enemigo\' caerán.', '', 28153),
(152955, 'esMX', '', 'Oh, sé que no.', 28153),
(152954, 'esMX', 'No te fallaremos... mi reina.', '', 28153),
(152953, 'esMX', '', '¿Creen estar a la altura?', 28153),
(152952, 'esMX', '', 'Deben infiltrarse en Ventormenta y liberar a un prisionero político. Un prisionero que podría inclinar la balanza de la guerra... a nuestro favor.', 28153),
(152951, 'esMX', '', 'El niño rey tiene algo que no le pertenece. Lo quiero de vuelta.', 28153),
(152950, 'esMX', '', 'Para ganar esta guerra, la Horda necesita aliados.', 28153),
(152949, 'esMX', '', 'Pero comprendo muy bien la discreción.', 28153),
(152948, 'esMX', '', 'Parece que algunos miembros de la Horda consideran mis últimas acciones... indiscriminadas.', 28153),
(152947, 'esMX', '', 'Necesito los servicios de alguien en quien pueda confiar plenamente.', 28153),
(152946, 'esMX', '', 'Ah, aquí están. Ya me estaba preocupando.', 28153),
(152945, 'esMX', '...a la Horda.', '', 28153),
(152944, 'esMX', 'Sus consejeros son fieles...', '', 28153),
(152943, 'esMX', 'Quizá mi reina sería más franca si no tuviera dudas sobre su lealtad.', '', 28153),
(152942, 'esMX', '¿Cómo podemos ayudar a la jefa de guerra si les esconde cosas a sus consejeros?', '', 28153),
(152941, 'esMX', 'Esto no es de tu incumbencia.', '', 28153),
(152940, 'esMX', '¿La jefa de guerra te llamó?', '', 28153),
(152939, 'esMX', 'Ni siquiera yo sé de qué se trata exactamente.', '', 28153),
(152938, 'esMX', 'Nuestra jefa de guerra tiene una misión de gran importancia para ti... y es secreta.', '', 28153),
(152937, 'esMX', '¡Dile\' a tus amigo que visiten la Posada Colmilloáureo!', '', 28153),
(152936, 'esMX', 'No olvide\' firmar el libro de huéspede\'.', '', 28153),
(152935, 'esMX', 'No te vaya\' a morir.', '', 28153),
(152934, 'esMX', 'Ey, ¿tiene\' alguna banana?', '', 28153),
(152933, 'esMX', 'Los Colmilloáureo son leale\'.', '', 28153),
(152932, 'esMX', '¡$uBienvenido:Bienvenida; a la posada Colmilloáureo!', '', 28153),
(152931, 'esMX', 'Motín o muerte.', '', 28153),
(152930, 'esMX', 'Cuida de tu tripulación.', '', 28153),
(152929, 'esMX', 'Cuidado con la marea baja.', '', 28153),
(152928, 'esMX', 'Llora por su esposo que cayó en Theramore, pero ese día también perdió a su hija.', '', 28153),
(152927, 'esMX', '¡Basta de parlotear! No hace falta que todos se enteren.', '¡Basta de parlotear! No hace falta que todos se enteren.', 28153),
(152926, 'esMX', '¡Silencio! Hemos encontrado algo bueno.', '¡Silencio! Hemos encontrado algo bueno.', 28153),
(152925, 'esMX', '¡Shh! No queremos que nadie nos haga preguntas.', '¡Shh! No queremos que nadie nos haga preguntas.', 28153),
(152924, 'esMX', 'Zem\'lan no es lugar para los vivo\'.', '', 28153),
(152923, 'esMX', '¿Buh\'cas una tripulación?', '', 28153),
(152921, 'esMX', '¡Ah, del barco!', '', 28153),
(152920, 'esMX', 'Katherine carga con un peso inmenso. Entiendo por qué el regreso de Jaina fue tan duro para ella.', '', 28153),
(152918, 'esMX', '', 'Debemos unir las dinastías bajo el estandarte Valiente y encontrar a la flota desaparecida. De lo contrario, Kul Tiras podría desmoronarse antes de que la guerra comience.', 28153),
(152917, 'esMX', 'El Martillo Crepuscular acabó con mi clan. La única razón por la que pude escapar es porque mi hermano Keeland me subió a su grifo. Me salvó la vida.\n\nRecorrí casi todo el mundo antes de asentarme en Kul Tiras. Encontré a unos tipos que cazaban grifos por su carne y pieles. Les enseñé que había otra forma de tratarlos. Ahora son la nueva generación de jinetes de grifos.\n\nNo creo que regrese a casa. Este es mi clan ahora.', '', 28153),
(152916, 'esMX', 'Llévame de regreso a Zul\'jan.', 'Llévame de regreso a Zul\'jan.', 28153),
(152915, 'esMX', 'Serruchando', 'Serruchando', 28153),
(152914, 'esMX', '¿Qué hace un enano Martillo Salvaje por aquí?', '¿Qué hace un enano Martillo Salvaje por aquí?', 28153),
(152913, 'esMX', 'Después de esta redada seremos ricos.', 'Después de esta redada seremos ricos.', 28153),
(152912, 'esMX', 'Esos tontos no tenían idea del valor de lo que pisaban.', 'Esos tontos no tenían ni idea del valor de lo que pisaban.', 28153),
(152911, 'esMX', 'Tengo un comprador en Lunargenta que pagará mucho por estas reliquias.', 'Tengo un comprador en Lunargenta que pagará mucho por estas reliquias.', 28153),
(152910, 'esMX', 'Nada de esto terminará en un museo.', '', 28153),
(152907, 'esMX', 'De todo lo que está mal en Nazmir... eh\'te lugar parece ser el peor. Ten cuidado.', '', 28153),
(152906, 'esMX', 'Ja. ¡Hezrel eh\'tá ocupado! ¿Qué estará haciendo aquí abajo?', '', 28153),
(152905, 'esMX', 'Esperábamo\' que Hezrel nos ayudara en la batalla, pero se fue para encargarse de sus propio\' asunto\'. ¿Qué estará haciendo ese ensamblaje?', '', 28153),
(152900, 'esMX', 'Quita las mano\' de mi tesoro...', 'Yo me bajo en eh\'te puerto, pero volveré...', 28153),
(152899, 'esMX', 'La tierra eh\'tá maldita... como todos nosotro\'...', 'Zem\'lan nos niega la muerte eterna... esa e\' la verdadera maldición.', 28153),
(152898, 'esMX', 'No siento nada...', '¡Corre, marinero de agua dulce!', 28153),
(152897, 'esMX', 'El capitán... se enterará de eh\'to...', 'Te las verás... con el rey pirata Zem\'lan...', 28153),
(152896, 'esMX', 'Descendamos y hablemos con el guardián titánico Hezrel.', 'Descendamos y hablemos con el guardián titánico Hezrel.', 28153),
(152895, 'esMX', '', 'Debo informarle a mi padre lo que ha sucedido aquí. Nos hemo\' alzado con una gran victoria, pero la lucha contra lo\' trols de sangre continuará.', 28153),
(152894, 'esMX', '', 'No olvidaré todo lo que la Horda ha hecho por mi gente. Sin ustede\', nada de eh\'to habría sido posible.', 28153),
(152893, 'esMX', '', '¡A tus órdenes!', 28153),
(152892, 'esMX', '', '¡La caverna se está derrumbando! ¡Corran!', 28153),
(152891, 'esMX', 'Mueran aquí entre los escombros, o serán destrozados por mis vasallos. No vivirán para ver mi victoria.', '', 28153),
(152890, 'esMX', '', '¡Tú vienes conmigo!', 28153),
(152889, 'esMX', '', '¡Acércate un poco más!', 28153),
(152888, 'esMX', '', '¡Vamos a pasarla bomba!', 28153),
(152887, 'esMX', '', 'Vamos, ¡dame un abrazo!', 28153),
(152886, 'esMX', '¡Sígueme! ¡Apresúrate y no te alejes!', '¡Síganme! ¡Apresúrense y no se alejen!', 28153),
(152885, 'esMX', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|tUn |cFFFF0000|Hspell:269131|h[Dominamentes antiguo]|h|r se aferra a |cFFFF0000$n|r!', '', 28153),
(152884, 'esMX', 'Héroes de la tercera flota, ¡prepárense! ¡Preséntense ante el rey Cringris de inmediato!', '¡Héroes de la tercera flota, prepárense! Preséntense ante el rey Cringris de inmediato.', 28153),
(152883, 'esMX', 'Ah, no, no. Es cerveza. Todo en orden.', '', 28153),
(152882, 'esMX', '', '.', 28153),
(152881, 'esMX', '', 'Nuestra\' fuerzas mantienen a raya al resto de lo\' trols de sangre, pero no resih\'tirán por siempre... Tenemo\' que terminar eh\'to, y pronto.', 28153),
(152880, 'esMX', '', '.', 28153),
(152879, 'esMX', '', '¡Pero han pasado meses sin novedades de la flota! Los maresabios se han encerrado en sus claustros y no parecen interesados en encontrar los barcos desaparecidos.', 28153),
(152878, 'esMX', '', 'La casa Tarjasenda ha apoyado fielmente al gobierno Valiente durante siglos, pero su reciente ausencia en las reuniones del concilio ha despertado rumores.', 28153),
(152877, 'esMX', '¡Regresa, belleza!', '', 28153),
(152876, 'esMX', 'No podía dejar que se enfriara.', 'No podía dejar que se enfriara.', 28153),
(152875, 'esMX', 'Déjame morir eh\'ta vez, Bwonsamdi... por favor...', '', 28153),
(152874, 'esMX', 'Dilo de una vez.', '', 28153),
(152873, 'esMX', '', 'Continuaremos nuestro... ¿por qué me miras así? ¿ACASO NO ESTÁS DE ACUERDO?', 28153),
(152872, 'esMX', 'De inmediato, sí. ¡Por supuesto, y sin demoras!', '', 28153),
(152871, 'esMX', 'Eh, he visto cosas peores... pero fue una historia triste. Tendremos que informar al alto comandante de lo ocurrido.', '', 28153),
(152870, 'esMX', 'Cielos. Es peor de lo que temía. Mis más sinceras disculpas por ponerlo en una situación tan arriesgada, señor Barbabronce.', '', 28153),
(152869, 'esMX', '¡¿Y BIEN?! Esa muchacha estaba más loca que un múrloc borracho de hidromiel lunar. Intentó sacrificar a $Unuestro querido:nuestra querida; $c para un dios de sangre llamado G\'huun.', '', 28153),
(152868, 'esMX', 'La capitana Conrad... confío en que está bien, ¿no?', '', 28153),
(152867, 'esMX', 'Zul\'Nazman, creo. ¿O Tul\'vor? En realidad, creo que son el mismo lugar. O casi el mismo.', '', 28153),
(152866, 'esMX', 'Eso no importa, es hora de llegar al fondo de este asunto. ¿A dónde fue esa capitana?', '', 28153),
(152865, 'esMX', 'Cie... cielos. Sin duda la estimada capitana Conrad ignoraba completamente esta macabra situación, ¿no?', '', 28153),
(152864, 'esMX', 'Harry se pone blanco como un papel.', '', 28153),
(152863, 'esMX', '¿¡Pero qué es esto, Harry?! Esas ofrendas que enviabas... ¡Estaban sacrificando a los soldados! Les succionaban la sangre como si fueran licor de la Fiesta de la Cerveza.', '', 28153),
(152862, 'esMX', '¡Al diablo con eso! No volverán a ver otra moneda de cobre antes de que $n y yo sepamos qué sucede exactamente.', '', 28153),
(152861, 'esMX', '¡Acuerdos comerciales con los trols! Hasta tenemos murcielagos listos para enviar otro acuerdo comercial a Zala\'mar.', '', 28153),
(152860, 'esMX', '¡Ay, cielos! Sí, efectivamente, sí. Supongo que es una descripción acertada, mmm. Pero la capitana Conrad es gloriosa. Impresionante, sin duda.', '', 28153),
(152859, 'esMX', 'Oí que eran bárbaros que practicaban sacrificios sangrientos.', '', 28153),
(152858, 'esMX', 'Nada inapropiado, ¡te lo aseguro! Nuestra gloriosa capitana salió a negociar acuerdos comerciales con los trols del área.', '', 28153),
(152857, 'esMX', 'Bien, no hay señales de la capitana. ¿Qué sucede?', '', 28153),
(152856, 'esMX', '¡Ah! ¡Ja ja! Directo al grano, ¿eh? Sí, sí. ¡No se preocupen! Todo a su debido tiempo. Vamos a un lugar más seguro, detrás de los muros de nuestro fuerte.', '', 28153),
(152855, 'esMX', '¿Dónde está la capitana?', '', 28153),
(152854, 'esMX', 'La capitana Conrad me dejó estas instrucciones.', '', 28153),
(152853, 'esMX', 'Los estábamos esperando, nuestros estimados consejeros y futuros amigos fieles.', '', 28153),
(152852, 'esMX', '¡Bienvenidos! ¡Bienvenidos!', '', 28153),
(152851, 'esMX', 'Parece que nuestra fiesta de bienvenida está aquí. Harry es un tipo interesante. No le hagas caso.', '', 28153),
(152850, 'esMX', 'Y... eh... cúbrete la nariz. ¿Qué es ese hedor fétido y nauseabundo?', '', 28153),
(152849, 'esMX', 'No importa. Observa. Escucha. Mantente alerta. Las tierras despiadadas no suelen perdonar a los incautos, $n.', '', 28153),
(152848, 'esMX', 'Aun así, esta tierra está en contra de los zandalari y sus socios de la Horda. El enemigo de tu enemigo es tu... momento, ¿cómo decía el dicho?', '', 28153),
(152847, 'esMX', 'Hemos enviado a la capitana Conrad a construir un fuerte. Dicen que los trols de sangre de allí quizás estén dispuestos a negociar, pero no creo que el precio que suponga valga la pena.', '', 28153),
(152846, 'esMX', '¡Me gusta! Si un lugar te eriza la piel, es una oportunidad para vivir una nueva aventura y aprender algo.', '', 28153),
(152845, 'esMX', 'Este lugar me eriza la barba...', '', 28153),
(152844, 'esMX', 'Pero ustedes no vivirán para verlo. ¡Levántate, guardián, y asesina a estos intrusos!', '', 28153),
(152843, 'esMX', '¡Purificaremos la plaga kultirana y recuperaremos nuestras tierras!', '', 28153),
(152842, 'esMX', 'Tus ancestros eran unos tontos... ¡como tú!', '', 28153),
(152841, 'esMX', 'Usa las cuerdas para bajar al bote de desembarco, $n. Mucha suerte.', '', 28153),
(152840, 'esMX', '', 'Ahí hay más grabados. ¡Vamos!', 28153),
(152839, 'esMX', '', '¡Gorak Tul no sobrevivió! ¡Hubo testigos que escribieron sobre su derrota!', 28153),
(152838, 'esMX', 'Las autoridades locales nos han dado permiso para abrir portales aquí.', 'Las autoridades locales nos han dado permiso para abrir portales aquí.', 28153),
(152837, 'esMX', 'Este lugar está impregnado de magia. ¿La siente?\n\nMe pregunto qué tipo de rituales estarían haciendo aquí.', 'Este lugar está impregnado de magia. ¿La siente?\n\nMe pregunto qué tipo de rituales estarían haciendo aquí.', 28153),
(152836, 'esMX', '', '¡Otra estela! Aquí se ve a Gorak Tul.', 28153),
(152835, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Vol\'Dun.', '|cFF0000FF(Misión)|r Zarpar rumbo a Vol\'Dun.', 28153),
(152834, 'esMX', '|cFFEF0201+$1i|r de |cFFFFFF00azerita|r', '|cFFEF0201+$1i|r de |cFFFFFF00azerita|r', 28153),
(152833, 'esMX', 'Me dijeron que trabajaría con \"<tose> de sangre\". Y les dije: \"¡¿ELFOS de sangre?¡\", y repitieron \"<tose> de sangre\".\n\nTROLS de sangre. NO ELFOS. Ugh. Qué poco refinado.', '', 28153),
(152832, 'esMX', '', '¡Sí, señor!', 28153),
(152831, 'esMX', '', 'Un momento... ¿qué está pasando?', 28153),
(152830, 'esMX', 'La unión hace la fuerza.', '', 28153),
(152829, 'esMX', '... Bien, hice una nota aquí mismo sobre las rojas. Hasta le hice un círculo. Rojo. Gracias por la ayuda. Sin ella, quizás esto habría terminado mal.', '', 28153),
(152828, 'esMX', 'Ey, tú. Me gustaría recolectar muestras de esta flor del desierto poco común. Préstame tu ayuda, por favor.', '', 28153),
(152827, 'esMX', '¡Qué chiflada! Nos vemos en Fuerte Victoria. Vámonos de este lugar oscuro antes de que empiecen a perseguirnos.', '', 28153),
(152826, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(152825, 'esMX', 'Esto no se ve muy a menudo por esta parte del mundo. Se dice que las hojas de los azotadores rojos tienen propiedades curativas místicas.$b$bMe gustaría recolectar algunas, pero arrancarlas liberaría la fragancia de la planta. Y eso sin duda atraería la atención de la fauna local.$b$bProtégeme mientras las arranco. Te daré una recompensa que valdrá la pena.', '', 28153),
(152824, 'esMX', 'Alleria, guía al resto de tus tropas y arrasen con el ejército enemigo.', '', 28153),
(152823, 'esMX', '¡MI VIDA POR LA HORDA!', '', 28153),
(152822, 'esMX', '¡Mi padre lo dio todo por la Alianza! La pregunta es, ¿tú estás dispuesto a hacer lo mismo por la Horda?', '', 28153),
(152821, 'esMX', '¡Yo NUNCA me retiraré! Como, duermo y muero por la espada. ¿Qué precio pagaste tú por tu pueblo?', '', 28153),
(152820, 'esMX', 'Tu padre era un hombre de honor, niño. Tú no sabes nada de eso.', '', 28153),
(152819, 'esMX', 'A un lado, Colmillosauro. Tú no debes cargar con esta guerra, y no hay honor en tu muerte.', '', 28153),
(152818, 'esMX', '', '¡Estoy lista!', 28153),
(152817, 'esMX', '¡Excelente trabajo! Sigamos avanzando.', '', 28153),
(152816, 'esMX', 'Cuatro ojos... el fin... ¡ya viene!', '', 28153),
(152815, 'esMX', 'Sombras interminables... mil brazos...', '', 28153),
(152814, 'esMX', 'Te debo la vida, $p. No lo olvidaré.\n\nPor ahora, ayudaremo\' a Norah y a los demás vulpera a saquear todo el botín robado de Zem\'lan. Pero no dudes en decirno\' si necesitas algo de estos piratas no-muerto\'.\n\nHicimos un buen motín, pero sé que Zem\'lan no necesitó obligar a toda la tripulación a transformarse en monstruos. Muchos lo hicieron por voluntad propia.\n\nTen cuidado si vuelve\' al puerto.', '', 28153),
(152813, 'esMX', 'El sacrificio de Victoria no puede haber sido en vano. Su bastón es la llave para despejar el camino hasta el Santuario.', '', 28153),
(152812, 'esMX', 'Motín o muerte, $p. Estaré contigo.', '', 28153),
(152811, 'esMX', '¿Alguna vez vih\'te tantos tesoro\' en un solo lugar?\n\nEh\'to es lo que te depara una vida de piratería eterna. Será hermoso...', '', 28153),
(152810, 'esMX', '', '<Ahna finge que duerme y ronca ruidosamente.>', 28153),
(152809, 'esMX', 'Haz sonar el gong para desafiar al rey pirata Zem\'lan. Eh\'toy listo para enfrentarlo.', '', 28153),
(152808, 'esMX', 'Entiendo. Entonces le enseñaré a Katherine Valiente la misma verdad que aprendí con un costo muy alto...', '', 28153),
(152807, 'esMX', '¡Bien hecho! Las monedas de oro del antiguo imperio trol valen muchísimo. ¡Toma tu parte!', '', 28153),
(152806, 'esMX', 'He encontrado un tótem antiguo en la Corte de Zak\'rajan que puede despertar a los muertos. ¡Llévalo al Foso de Huesos y úsalo para desenterrar tesoros!', '', 28153),
(152805, 'esMX', 'Ah, olvídalo. No tengo tiempo para tonterías. ¡Tengo una fiesta a la que asistir!', '', 28153),
(152804, 'esMX', 'Los niños de hoy son tan impacientes. ¡Apenas estoy empezando!', '', 28153),
(152803, 'esMX', 'Si me sigues molestando, creo que empezaré a contar una historia. Una historia laaaarga y aburrida.', '', 28153),
(152802, 'esMX', 'Compartiremos historias la próxima vez.', '', 28153),
(152801, 'esMX', 'Bien. Vete. Tengo cosas que hacer.', '', 28153),
(152800, 'esMX', '¿Por qué tanta prisa?', '', 28153),
(152799, 'esMX', '¡Baja la voz!', '', 28153),
(152798, 'esMX', '¿Tienes alguna historia divertida?', '', 28153),
(152797, 'esMX', 'Sí, sí... Te estoy escuchando.', '', 28153),
(152796, 'esMX', 'Debe\' andar con cuidado, la flora de la jungla puede ser peor que la fauna.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'esMX', '¡No volveré a pisar esta mina!', '¡No volveré a pisar esta mina!', 28153),
(152794, 'esMX', '¡Salieron de la nada!', '¡Salieron de la nada!', 28153),
(152793, 'esMX', '¡Gracias! Pensé que no volvía.', '¡Gracias! Pensé que no volvía.', 28153),
(152792, 'esMX', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(152791, 'esMX', '', 'Por aquí llegarán hasta el puente de abajo.', 28153),
(152790, 'esMX', 'Creo que mi bota y tu cara aún no se conocen. ¡¿Qué tal si les damos un tiempo a solas?!', '', 28153),
(152789, 'esMX', 'Vuela, pajarito...', '', 28153),
(152788, 'esMX', 'Nos vemos en los cielos.', '', 28153),
(152787, 'esMX', '', 'En el Valle Canto Tormenta, hacia el norte, los maresabios de la casa Canto Tormenta construyen y bendicen los barcos de nuestra flota legendaria.', 28153),
(152786, 'esMX', 'Muy bien. Hora de moverse.', '', 28153),
(152785, 'esMX', '¡Volvamos al trabajo!', '', 28153),
(152784, 'esMX', '¡Vamos, habla de una vez!', '', 28153),
(152783, 'esMX', '¿Qué necesitas?', '', 28153),
(152782, 'esMX', '¿Sí? ¡Soy un tipo ocupado!', '', 28153),
(152781, 'esMX', 'Esas bestias han sido la ruina de muchas caravanas en Vol\'dun. Bien hecho.', '', 28153),
(152780, 'esMX', 'Los buitres picóseos son indomables. Se han vuelto una molestia, y debemos exterminar a algunos junto con sus nidos.', '', 28153),
(152779, 'esMX', 'Puedes mirar $Utranquilo:tranquila; pero por favor no toques nada.$b$bEstas plantas son muy delicadas.', '', 28153),
(152778, 'esMX', '', 'Al oeste se encuentra Drustvar, una región montañosa que brinda casi todos los minerales del reino... y algunos de sus mejores guerreros.', 28153),
(152777, 'esMX', '', 'Pasando el Canal de Tiragarde se encuentran las tierras de las familias Tarjasenda y Canto Tormenta.', 28153),
(152776, 'esMX', '¡Para ti solo hay dolor!', '¡Para ti solo hay dolor!', 28153),
(152775, 'esMX', '¡Tengo formas de obligarte a hablar!', '¡Tengo formas de obligarte a hablar!', 28153),
(152774, 'esMX', 'Destruiré tu espíritu.', 'Destruiré tu espíritu.', 28153),
(152773, 'esMX', 'La vida se reduce a cenizas...', '', 28153),
(152772, 'esMX', 'Cuando por fin pidió ayuda, ya era muy tarde.', '', 28153),
(152771, 'esMX', 'La tierra que amo se cae a pedazos... por eso les pido ayuda. Kul Tiras necesita a la Alianza, tanto como ustedes nos necesitan a nosotros.', '', 28153),
(152770, 'esMX', 'Pero ha perdido el rumbo. Sus consejeros la han cegado y no puede ver la infección que se propaga por nuestro reino.', '', 28153),
(152769, 'esMX', 'Las cicatrices de la Tercera Guerra aún no han sanado en Kul Tiras. Y a nadie le duelen tanto como a Katherine Valiente.', '', 28153),
(152768, 'esMX', '', 'Trata de no dejarme en ridículo, ¿sí?', 28153),
(152767, 'esMX', 'Unos días después, despertó gritando y empapado en sudor. La infección lo había carcomido por dentro. Mi amigo jamás volvió a ver el amanecer.', '', 28153),
(152766, 'esMX', '', 'Si no hay más monedas aquí, busca en los otros sitios.', 28153),
(152765, 'esMX', 'Cualquiera habría abandonado después de eso, pero él era terco como una mula. Se negó a marcharse hasta ganar la guerra. Así que se curó como pudo y les dijo a los sanadores que estaba bien.', '', 28153),
(152763, 'esMX', 'Un acorazado orco se estrelló contra nuestro transporte. Las astillas de la borda atravesaron la cubierta y se clavaron en un amigo mío.', '', 28153),
(152762, 'esMX', 'Hace muchos años, luchaba en una guerra. Creo que era... ¿la Segunda Guerra? Son tantas que me confundo.', '', 28153),
(152761, 'esMX', 'Mmm... Sígale la corriente a este viejo caballero, ¿sí?', '', 28153),
(152760, 'esMX', '¿Por qué nos ayudarías?', '', 28153),
(152759, 'esMX', 'Katherine Valiente nos rechazó y exilió a su propia hija por traidora.', '', 28153),
(152758, 'esMX', 'Un zandalari me ofreció esta poción en una negociación. Se supone que cocina cualquier cosa al instante. Y la comida gratis siempre es bienvenida. Pruébala con las criaturas de esta zona.', '', 28153),
(152757, 'esMX', '¡Taelia! Prepara un informe completo para nuestros invitados.', '', 28153),
(152756, 'esMX', 'Todo se derretirá.', '', 28153),
(152755, 'esMX', 'Rey Cringris, es un honor. Tiene mi autorización para permanecer en el muelle todo lo que quiera.', '', 28153),
(152754, 'esMX', '¡Los resultados son irrebatibles! Para estar seguros, dejemos que nuestros amigos con colmillos lo prueben primero...', '', 28153),
(152753, 'esMX', '', 'El anhelo de poder. El deseo de comprender la gran verdad. La voluntad de la sangre.', 28153),
(152752, 'esMX', '', 'Al principio, los métodos de los nazmani me parecían... desagradables. Pero ahora los comprendo. Son un pueblo sencillo, con anhelos sencillos.', 28153),
(152751, 'esMX', '', 'Ven, te mostraré lo que he aprendido.', 28153),
(152750, 'esMX', '', 'Aún queda mucho por aprender de ellos. Esta magia de sangre... es más potente de lo que imaginas.', 28153),
(152749, 'esMX', '', 'Podrían ser herramientas muy poderosas en la batalla contra los trols zandalari y sus aliados de la Horda.', 28153),
(152748, 'esMX', '', 'Me he ganado la confianza de estos trols de sangre, los nazmani, mucho más de lo que esperaba.', 28153),
(152747, 'esMX', 'Aaahh, ¡cierra la boca!', '', 28153),
(152746, 'esMX', '', '¡Uuurgh!', 28153),
(152745, 'esMX', '', 'Creo que entiendes que no es nada personal. Pero no puedo permitir que interrumpas el progreso que he realizado. Todo lo que aprendido... lo que aún no he descubierto.', 28153),
(152744, 'esMX', '', 'Sacrificaremos a este zandalari para reafirmar nuestro poder.', 28153),
(152743, 'esMX', 'Nos guiah\'te hasta aquí. Te seguiremo\'.', 'Nos guiah\'te hasta aquí. Te seguiremo\'.', 28153),
(152742, 'esMX', '$p sabe de una tripulación de vulperas cerca. Deberíamo\' unirnos a ellos hasta que la situación se calme.', '', 28153),
(152741, 'esMX', 'Los lacayos de Zem\'lan nos buh\'carán en los mare\'.', '', 28153),
(152740, 'esMX', 'Sí. Pero antes tendremo\' que eh\'condernos por un tiempo.', '', 28153),
(152739, 'esMX', 'Libreh\' para quedarno\' con el tesoro.', 'Libreh\' para quedarno\' con el tesoro.', 28153),
(152738, 'esMX', 'Libreh\' para saquear donde queramo\'.', 'Libreh\' para saquear donde queramo\'.', 28153),
(152737, 'esMX', 'Libreh\' para navegar los mare\' abierto\'.', 'Libreh\' para navegar los mare\' abierto\'.', 28153),
(152736, 'esMX', 'Lo logramo\', compañero\'. ¡Al fin somoh\' libres de Zem\'lan!', '', 28153),
(152735, 'esMX', '¡Todo\' a cubierta! ¡A toda velocidad hacia la coh\'ta!', '¡Todo\' a cubierta! ¡A toda velocidad hacia la coh\'ta!', 28153),
(152734, 'esMX', 'Debes ser $Uel emisario:la emisaria; de la Alianza. Me alegra que Flynn y Taelia te hayan liberado de esa prisión horrenda. \n\nMi nombre es Sir Cyrus Catacresta. En nombre del almirantazgo Valiente, te doy la bienvenida a Kul Tiras.\n\n<Cyrus te extiende su mano enorme con amabilidad.>', '', 28153),
(152733, 'esMX', '<Darle la mano.>', '<Darle la mano.>', 28153),
(152732, 'esMX', 'Me temo que no me quedan muchos días por delante.\n\nNo los malgastaré viendo cómo Kul Tiras cae a pedazos.', '', 28153),
(152731, 'esMX', 'Muy bien, tripulación. ¡Tomen los tesoro\' y métanse en el barco!', '', 28153),
(152730, 'esMX', 'Winston vuela lejos de tu alcance. ¡Regresa a Corlain!', '', 28153),
(152729, 'esMX', 'Princesa, $n, los exploradore\' me informan que el guardián titánico Hezrel está merodeando por la base de eh\'ta estructura.', '', 28153),
(152728, 'esMX', 'Desde Hakkar, las mente\' de los gurubashi quedaron débile\'. Es muy fácil corromperlos y hay que purgarlos. ¡Toca el gong y vendrán corriendo!', '', 28153),
(152727, 'esMX', '', 'No podrán... prevalecer...', 28153),
(152726, 'esMX', 'A la orden, capitán.', '', 28153),
(152725, 'esMX', '', '¡Corlain le pertenece al aquelarre!', 28153),
(152724, 'esMX', 'Descansen y disfruten del campamento esta noche. Mañana planearemos cómo vamos a conseguir el resto del tesoro.', 'Descansen y disfruten del campamento esta noche. Mañana planearemos cómo vamos a conseguir el resto del tesoro.', 28153),
(152723, 'esMX', '¡Bienvenidos a la caravana!', '¡Bienvenidos a la caravana!', 28153),
(152722, 'esMX', 'De acuerdo...', 'De acuerdo...', 28153),
(152721, 'esMX', 'Sí. Hay toda una isla llena cerca de la coh\'ta. Más tesoro\' de los que puedes contar.', '', 28153),
(152720, 'esMX', 'Una pequeña maldición nunca les impidió a los vulperas echar mano a un tesoro valioso... ¿Tienes más de eso en algún lado?', 'Una pequeña maldición nunca les impidió a los vulperas echar mano a un tesoro valioso... ¿Tienes más de eso en algún lado?', 28153),
(152719, 'esMX', 'El único problema e\' que el tesoro eh\'tá maldito.', 'El único problema e\' que el tesoro eh\'tá maldito.', 28153),
(152718, 'esMX', 'Queremo\' unirnos a una nueva tripulación. Si nos aceptan, compartiremos nueh\'tro tesoro con ustede\'.', '', 28153),
(152717, 'esMX', 'El rey pirata Zem\'lan mató a tu amigo. Nos amotinamo\' contra él y le robamo\' el tesoro.', '', 28153),
(152716, 'esMX', 'Te escucho...', 'Te escucho...', 28153),
(152715, 'esMX', '¡Un momento! Vinimo\' a uh\'tedes en son de paz.', '', 28153),
(152714, 'esMX', '¡E-e-esqueletos! ¡N-n-norah, mátalos!', '¡E-e-esqueletos! ¡N-n-norah, mátalos!', 28153),
(152713, 'esMX', 'Excelente trabajo. Una ráfaga de sus propios cañones sin duda debilitará el asedio de los infieles.', '', 28153),
(152712, 'esMX', '¡Vivo por una buena pelea!', '¡Vivo por una buena pelea!', 28153),
(152711, 'esMX', '¡Los infieles redoblan sus ataques! ¡Usa uno de los cañones que hemos tomado para defender el templo!', '', 28153),
(152710, 'esMX', '', '¡Parche, ahora!', 28153),
(152709, 'esMX', 'Cuando quieras.', 'Cuando quieras.', 28153),
(152708, 'esMX', 'Muévete de una vez. No estamos aquí de vacaciones.', '', 28153),
(152707, 'esMX', '¡No tengan piedad, muchachos!', '', 28153),
(152706, 'esMX', '¡Apunten y disparen!', '', 28153),
(152705, 'esMX', '¡Que sufran, muchachos!', '', 28153),
(152704, 'esMX', '¡Objetivo en la mira! ¡Disparen!', '', 28153),
(152703, 'esMX', '¡Fuego a discreción!', '', 28153),
(152702, 'esMX', '¡Ese es el objetivo! ¡Disparen!', '', 28153),
(152701, 'esMX', 'Ja ja ja...', '', 28153),
(152700, 'esMX', 'Sí... Un poco aterradora para nuestros posibles clientes.', '', 28153),
(152699, 'esMX', '¿Demasiado aterradora?', '', 28153),
(152698, 'esMX', 'Hice algunos cálculos de pérdida y ganancia, y no creo que valga la pena perder tiempo en esta zona.', '', 28153),
(152697, 'esMX', 'Y... ¿qué hay de tu azerita?', '', 28153),
(152696, 'esMX', 'Bien. Súbete a la moto. Larguémonos de aquí.', '', 28153),
(152695, 'esMX', 'Claro que sí.', '', 28153),
(152694, 'esMX', 'Entonces... Ehhh... ¿tal vez es mejor que nos larguemos de aquí?', '', 28153),
(152693, 'esMX', 'No no no no...', '', 28153),
(152692, 'esMX', 'Será mejor que superes tu miedo a las brujas, Eitrigg. Esta zona está REPLETA de azerita y... ¡AH!', '', 28153),
(152691, 'esMX', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t¡%s obtiene un |cFFFF0000|Hspell:263246|h[Escudo de relámpagos]|h|r!', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t¡%s obtiene un |cFFFF0000|Hspell:263246|h[Escudo de relámpagos]|h|r!', 28153),
(152690, 'esMX', '¡Ay, no, otra más!', '', 28153),
(152689, 'esMX', '', '¡Tu sangre me pertenece!', 28153),
(152688, 'esMX', '¡A quién le importa! ¿Has encontrado la veta de azerita?', '', 28153),
(152687, 'esMX', '¿Qué? ¿Qué pasa?', '', 28153),
(152686, 'esMX', 'Ca-cállate.', '', 28153),
(152685, 'esMX', '¡Aaah! ¡Ja ja ja! Un orco grande como tú, con miedo a las brujas.', '', 28153),
(152684, 'esMX', '¡NO! Quiero decir... No. Es solo que... no me gustan. Eso es todo.', '', 28153),
(152683, 'esMX', '¿Qué dijiste?', '', 28153),
(152682, 'esMX', 'Cuidado... con... las brujas...', '', 28153),
(152681, 'esMX', 'Eitrigg... ¿les temes a las brujas?', '', 28153),
(152680, 'esMX', '¿Acaso dijo... b-bru-brujas?', '', 28153),
(152679, 'esMX', '¡El Parque no es seguro! ¡Las aves nos atacan!', '¡El Parque no es seguro! ¡Las aves nos atacan!', 28153),
(152678, 'esMX', 'Bueno, haz tu trabajo, ¡protégeme!', '', 28153),
(152677, 'esMX', 'No... Pero veo otra cosa. Tenemos compañía.', '', 28153),
(152676, 'esMX', 'Bahhh... pasa todo el tiempo. ¿Ves azerita por aquí?', '', 28153),
(152675, 'esMX', '¡Vuelan por todas partes!', '¡Vuelan por todas partes!', 28153),
(152674, 'esMX', 'Gallywix... ¿ves este cuerpo destrozado? Tu explorador está muerto.', '', 28153),
(152673, 'esMX', 'Sí, como sea.', '', 28153),
(152672, 'esMX', 'Está bien, investigaremos la azerita. ¡Pero luego DEBEMOS concentrarnos en la Alianza!', '', 28153),
(152671, 'esMX', '¡Demasiadas... aves!', '¡Demasiadas... aves!', 28153),
(152670, 'esMX', '¡Jamás volveré a confiar en una gaviota!', '¡Jamás volveré a confiar en una gaviota!', 28153),
(152669, 'esMX', 'La anciana MacMillan tenía razón. ¡Estos pájaros son diabólicos!', 'La anciana MacMillan tenía razón. ¡Estos pájaros son diabólicos!', 28153),
(152668, 'esMX', 'Pfff... Esclavos', '', 28153),
(152667, 'esMX', 'Vamos a ver eso antes que nada.', '', 28153),
(152666, 'esMX', '¡Lo primero es lo primero! Mis exploradores me cuentan que hay una ENORME vena de azerita en Drustvar.', '', 28153),
(152665, 'esMX', '¡Entonces lárgate de mi vista, o te daré un motivo para sentirte $Uaterrado:aterrada;!', '', 28153),
(152664, 'esMX', 'Debemos ser cautelosos. Sus palabras fueron... inquietantes.', '', 28153),
(152663, 'esMX', 'Sí, pero...', '', 28153),
(152662, 'esMX', '... terrible maldición... todos los demás...', '', 28153),
(152661, 'esMX', '¡Deben irse! Es...', '', 28153),
(152660, 'esMX', '', 'Mmm. Pensé que sería más grande.', 28153),
(152659, 'esMX', '', 'Le falta potencia. Creo que necesita más combustible.', 28153),
(152658, 'esMX', 'Preferimo\' las arboledas de la naturaleza antes que las piedras frías de la ciudad. Mucho\' zandalari nos consideran herejes. Afirman que nuestra matrona no es ninguna loa. \n\nCada uno tiene derecho a su propia opinión. Nosotro\', los lun\'alai, poseemos los dones de la naturaleza desde hace mucho tiempo, y podemo\' adoptar formas salvajes. Nueh\'tro camino es el equilibrio, no los negocios.', '', 28153),
(152655, 'esMX', '¡Maravilloso! ¡Hermoso! Ah, este tiene un poco de arena. No importa. ¡Buen trabajo!', '', 28153),
(152654, 'esMX', 'Toneladas de vidrio marino brillante llegan hasta estos pantanos, ¡pero los múrlocs se lo llevan todo! Intenta recoger algunas piezas bonitas como mejor te parezca.', '', 28153),
(152653, 'esMX', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma comienza a lanzar |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma comienza a lanzar |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r!', 28153),
(152652, 'esMX', 'Llegas demasiado tarde. ¡La invasión ya ha comenzado!', 'Llegas demasiado tarde. ¡La invasión ya ha comenzado!', 28153),
(152651, 'esMX', '¿Crees que trabajo sola? ¡Conoce a mis socios!', '¿Crees que trabajo sola? ¡Conoce a mis socios!', 28153),
(152650, 'esMX', '', 'Los actos del aquelarre son terribles, ¡pero esto es demasiado bajo incluso para ellas! No tengo palabras para agradecerles por detener esta... carnicería.', 28153),
(152649, 'esMX', 'Los gustos de este aquelarre bordean lo profano. Así termina una de sus más sórdidas aventuras.', '', 28153),
(152648, 'esMX', '¡Rápido! Veámono\' en el bote. Me encargaré de que la tripulación lo haya cargado con los tesoro\'.', '', 28153),
(152647, 'esMX', '', 'Cada vida que salvemos de este culto es una victoria. Buen trabajo.', 28153),
(152646, 'esMX', 'El manejo de la muerte y el renacimiento son solo nuestros. Los felicito por mantenerlo así.', '', 28153),
(152645, 'esMX', '', 'Han salvado a los ciudadanos de Drustvar de este terror de los cielos. Les agradezco.', 28153),
(152644, 'esMX', 'No causes ningún problema.', 'No causes ningún problema.', 28153),
(152643, 'esMX', 'Estas plumas abastecerán a nuestros forestales por un buen tiempo.', '', 28153),
(152642, 'esMX', 'Una eternidad de saqueos y botines... ¡sin ti!', '', 28153),
(152641, 'esMX', '¿Qué mejor que toda una eternidad de saqueos y botines?', '', 28153),
(152640, 'esMX', 'Ere\' un capitán cruel, Zem\'lan. ¡La tripulación merece algo mejor!', '', 28153),
(152639, 'esMX', '', 'Deben hacerlo, o todo estará perdido. ¡Muévanse!', 28153),
(152638, 'esMX', '', '¡No te dejaremos morir aquí!', 28153),
(152637, 'esMX', '', 'Eso eh\'tuvo cerca. Aquí en Vol\'Dun, ademá\' de las arenas, también tendremo\' que vigilar los mares de cerca.', 28153),
(152636, 'esMX', '', 'Eso estuvo cerca. Parece que, además de las arenas, también tendremos que vigilar los mares de cerca.', 28153),
(152635, 'esMX', '', 'Un monstruo marino gigante siembra el caos en la costa. ¡Debemo\' detenerlo antes de que se adentre en tierra firme!', 28153),
(152634, 'esMX', '', 'Un monstruo marino gigante está sembrando el caos en la costa. ¡Debemos detenerlo antes de que se acerque a nuestro campamento!', 28153),
(152633, 'esMX', '', 'Xorrath era un comandante deh\'tacado del ejército sethrak. Eliminarlo es una gran victoria.', 28153),
(152632, 'esMX', '', 'El clamacolmillos Xorrath era un comandante de alto rango del ejército sethrak. Eliminarlo fue una gran victoria.', 28153),
(152631, 'esMX', '', 'Los exploradore\' vulperas nos han informado que hay un comandante sethrak cerca. Debemos aprovechar la oportunidad para eliminarlo.', 28153),
(152630, 'esMX', '', 'Nuestros exploradores nos han informado que hay un comandante sethrak de alto rango cerca. Debemos aprovechar la oportunidad para eliminarlo mientras podamos.', 28153),
(152629, 'esMX', '', '¡Bien hecho! La tribu se desintegrará sin un líder que seguir.', 28153),
(152628, 'esMX', '', '¡Bien hecho! La tribu se desintegrará sin un líder que seguir.', 28153),
(152627, 'esMX', '', 'Hay una tribu de múrlocs por aquí que está provocando muchos problemas. Acaba con su líder y la tribu se desintegrará.', 28153),
(152626, 'esMX', '', 'Hay una tribu de múrlocs por aquí que causa muchos problema\'. Acaba con su líder y la tribu se desintegrará.', 28153),
(152625, 'esMX', '', 'Bien hecho. A nuestros exploradores les gustará saber que eliminaste a Mor\'fani.', 28153),
(152624, 'esMX', '', 'Bien hecho. A los vulperas les guh\'tará saber que eliminaste a Mor\'fani.', 28153),
(152623, 'esMX', 'El aquelarre ha encantado un enorme cuervo para atacar a los civiles. Aunque los residentes de Drustvar no me agradan, los forestales oscuros podrán hacer excelentes flechas con las plumas.', '', 28153),
(152622, 'esMX', 'Una de las brujas más importantes del aquelarre está sacrificando acólitas para ganar más poder. Destrúyanlas y demuéstrenles a estas novatas que solo hay una Dama Oscura.', '', 28153),
(152621, 'esMX', 'Parece que el aquelarre ha \"contratado\" a los cocineros de la mansión para que preparen platos desagradables. Elimínenlos cuanto antes.', '', 28153),
(152620, 'esMX', '', 'El aquelarre Hiel de corazón ha encantado a un enorme cuervo de Drustvar. ¡Mátalo antes de que ataque a nuestros civiles!', 28153),
(152619, 'esMX', '', 'Una integrante del aquelarre de Lady Tarjasenda está sacrificando a sus acólitas. ¡Detengan el ritual antes de que haya más muertes!', 28153),
(152618, 'esMX', '', 'Un exiliado zandalari está aterrorizando nuestras fuerzas. Búscalo y elimínalo antes de que caigan más de nuestras tropas.', 28153),
(152617, 'esMX', '', 'Un exiliado reciente está aterrorizando a lo\' vulperas. Elimínalo ante\' de que encuentre nuevas víctimas.', 28153),
(152616, 'esMX', '', 'Los cocineros han estado sirviendo platos de dudoso contenido a nuestros invitados desprevenidos. ¡Detengan estas monstruosidades culinarias!', 28153),
(152615, 'esMX', '¡Sí, señor!', '', 28153),
(152614, 'esMX', 'N-no, señor.', '', 28153),
(152613, 'esMX', 'Bajen las armas y déjenlos pasar. Hablaremos en mi oficina.', '', 28153),
(152612, 'esMX', '¡No! ¡Sirven a Kul Tiras! ¡Portan el emblema de los Valiente! Y ustedes me obedecen a MÍ.', '', 28153),
(152611, 'esMX', 'Es imposible cosechar en Vol\'dun sin fertilizante. Por lo general utilizamos el fertilizante de las hienas, pero últimamente no dejan mucho. ¡Aliméntalas para acelerar el proceso!', '', 28153),
(152610, 'esMX', '¿Lady Aspafresno? ¿Sirven a Lady Aspafresno? ¿Ese es el emblema de Lady Aspafresno en su escudo?', '', 28153),
(152609, 'esMX', 'Pero, señor... Lady Aspafresno ordenó...', '', 28153),
(152608, 'esMX', '¡Bajen las armas! ¿Acaso no saben quién es?', '', 28153),
(152607, 'esMX', '¡Este es un fertilizante de buena calidad! Buen trabajo... ¡pero no olvides lavarte las manos!', '', 28153),
(152606, 'esMX', '... supongo que tenemos que interrumpirlo, ¿no?', '', 28153),
(152605, 'esMX', '¿Eso que veo en el horizonte es una vela? Quizás están negociando con los zandalari.', '', 28153),
(152604, 'esMX', 'Dando patadas', 'Dando patadas', 28153),
(152603, 'esMX', 'La caja suelta un repique neutral.', '', 28153),
(152602, 'esMX', ' La caja suelta un repique alegre.', '', 28153),
(152601, 'esMX', 'La caja suelta un repique neutral.', '', 28153),
(152600, 'esMX', 'Ni idea. Pero esta noche yo invito la cerveza, muchacha.', '', 28153),
(152599, 'esMX', '', '¿Qué sucede?', 28153),
(152598, 'esMX', '', '¡Será maravilloso teletransportarme al fondo del Mare Magnum! ¡Por la Horda!', 28153),
(152597, 'esMX', 'Qué...', '', 28153),
(152596, 'esMX', '', 'Obedezcan sus órdenes para evitar incidentes innecesarios. Existen rumores de que hay espías e invasores del exterior entre nosotros, debemos ser cuidadosos.', 28153),
(152595, 'esMX', '', 'Discutiremos el pago más tarde, maestro de embarcadero.', 28153),
(152594, 'esMX', 'Sí, ahí está. Sellemos esto y enviémoslo de vuelta a Ventormenta.', '', 28153),
(152591, 'esMX', '', 'Oculeth... lo siento...', 28153),
(152590, 'esMX', 'La aguja apunta al este. Nos vemos en las ruinas, $n.', '', 28153),
(152589, 'esMX', '', 'Muy lento, enano.', 28153),
(152588, 'esMX', 'No te alejes. La Horda está cerca. Puedo olerlos.', '', 28153),
(152587, 'esMX', 'Es más florido de lo que esperaba. ¿Consiguieron un nuevo sabor de elfos?', '', 28153),
(152586, 'esMX', 'No está aquí. Y como si fuera poco, nos persiguen los Natonocturno. Justo lo que quería.', '', 28153),
(152585, 'esMX', 'Nos acercamos. Mantén lejos a esos bebemaná asesinos, $n.', '', 28153),
(152584, 'esMX', 'Justo debajo mis pies... ¿Dónde...?', '', 28153),
(152583, 'esMX', '¡Uff! ¡Qué truco sucio!', '', 28153),
(152581, 'esMX', 'La caja tararea suavemente.', '', 28153),
(152580, 'esMX', 'La caja tararea suavemente.', '', 28153),
(152579, 'esMX', 'La caja tararea suavemente.', '', 28153),
(152578, 'esMX', '¡Alto! Los ídolo\' no se pueden destruir, pero revivieron un viejo recuerdo... Uno que intentaba olvidar.', '', 28153),
(152577, 'esMX', 'Hay una espada ENORME clavada en el corazón del planeta, ¿y tú te tomas el tiempo para sentarte y molestarme? ¡VUELVE A TRABAJAR AHORA MISMO!', '', 28153),
(152576, 'esMX', 'Recuerda que tienes un deber con Azeroth.', '', 28153),
(152575, 'esMX', '¡Debemos sanar a nuestro mundo!', '', 28153),
(152574, 'esMX', 'Azeroth grita de dolor.', '', 28153),
(152573, 'esMX', 'Nuestro mundo nos necesita, adalid.', '', 28153),
(152572, 'esMX', '', '¡Y pensar que los trols han estado sentados sobre el hallazgo arqueológico del siglo!', 28153),
(152571, 'esMX', 'Quédate con tus huesos. Aquí hay poder, puedo saborearlo. Se lo arrebataremos a la Horda bajo sus narices.', '', 28153),
(152570, 'esMX', '', 'Cuidado con las manos. Lento, pero seguro.', 28153),
(152569, 'esMX', '', 'Intenta no dañarlo. Sí, así...', 28153),
(152568, 'esMX', '', 'Aaaaaahhh... mira eso. ¡Algún día serás $Uun verdadero arqueólogo:una verdadera arqueóloga;!', 28153),
(152567, 'esMX', '¿En serio? ¿Vas a hacerlo todo con las manos?', '', 28153),
(152566, 'esMX', 'Ve y dale una palmada a mi elemental. Hará este trabajo por ti.', '', 28153),
(152565, 'esMX', '', '¡Espera!', 28153),
(152564, 'esMX', 'Bien. Ahora al trabajo de verdad.', '', 28153),
(152563, 'esMX', '', '¡Lo rayaste! ¡Ahora no podemos exponerlo!', 28153),
(152562, 'esMX', 'Sí, muchacha, no está tan mal.', '', 28153),
(152561, 'esMX', 'Mis huesos eh\'tán cansado\'. La maldición me pesa.', '', 28153),
(152560, 'esMX', 'El rey pirata Zem\'lan jamás olvidará eh\'te día.', '', 28153),
(152559, 'esMX', '', '¡Vamos! La oficina del supervisor de puerto está por aquí.', 28153),
(152558, 'esMX', 'Y también tengo que lavar mi ropa.', '', 28153),
(152557, 'esMX', 'Un buen martillo es una herramienta invaluable, y un arma resistente.', '', 28153),
(152556, 'esMX', 'No puedo hacer nada sin mi martillo. Es como si me faltara una mano.', '', 28153),
(152555, 'esMX', '', 'No podré detenerlos mucho más. ¡Tomen la vara y salgan de aquí!', 28153),
(152554, 'esMX', 'Investigando', 'Investigando', 28153),
(152553, 'esMX', 'Estas cuevas están repletas de alimañas kóbold.', '', 28153),
(152552, 'esMX', '¡Todos al bote! Nos veremo\' pronto, $p.', '', 28153),
(152551, 'esMX', 'Casi eh\'tamos listos para levar ancla\'. Zem\'lan nunca eh\'perará esto.', '', 28153),
(152550, 'esMX', 'Sí.', 'Sí.', 28153),
(152549, 'esMX', 'Sí.', 'Sí.', 28153),
(152548, 'esMX', 'Sí. Zem\'lan es un tirano, no un capitán. Necesitamo\' un motín.', 'Sí. Zem\'lan es un tirano, no un capitán. Necesitamo\' un motín.', 28153),
(152547, 'esMX', '¿Entonces eh\'tamos de acuerdo?', '', 28153),
(152546, 'esMX', 'Sí, y nos llevaremos nueh\'tra parte del botín.', '', 28153),
(152545, 'esMX', 'Mira todo ese oro...', 'Mira todo ese oro...', 28153),
(152544, 'esMX', '¡Eh\'to es un motín, rata de sentina! Clavaremo\' nueh\'tras espadas en la\' tripas huesudas de Zem\'lan.', '¡Eh\'to es un motín, rata de sentina! Clavaremo\' nueh\'tras espadas en la\' tripas huesudas de Zem\'lan.', 28153),
(152543, 'esMX', 'Y aún así vamo\' en esa dirección.', 'Y aún así vamo\' en esa dirección.', 28153),
(152542, 'esMX', 'Es el único deh\'tino peor que el nuestro.', '', 28153),
(152541, 'esMX', 'Allí solo hay eh\'clavos de oro que antes eran tripulantes, forzados a cuidar el botín de Zem\'lan por toda la eternidad.', '', 28153),
(152540, 'esMX', 'Nos dirigimos a la Isla Dorada, donde Zem\'lan acumula lo\' tesoros que saqueamos durante un sinfín de años.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'esMX', '¡Todo\' a cubierta!', '¡Todo\' a cubierta!', 28153),
(152538, 'esMX', '*Insertar acción de transición de vagoneta divertida aquí.*', '', 28153),
(152537, 'esMX', 'Mucha luz... devuélveme al agujero.', 'Mucha luz... devuélveme al agujero.', 28153),
(152536, 'esMX', '', 'Hay varias dinastías mayores en Kul Tiras. Daelin Valiente había logrado unificarlas, pero eso fue cambiando luego de su derrota en Theramore.', 28153),
(152535, 'esMX', '', 'Ahora la Lady almirante Katherine Valiente gobierna el lugar, y está a cargo del ejército y de la guardia.', 28153),
(152534, 'esMX', '', 'A pesar de nuestros esfuerzos por mantener el orden, el crimen, la corrupción y la piratería han aumentado en Kul Tiras. El pueblo pierde la fe en el almirantazgo Valiente.', 28153),
(152533, 'esMX', '', '.', 28153),
(152532, 'esMX', '', '.', 28153),
(152531, 'esMX', 'Buen día. ¿Necesitas descansar? ¿Comer algo?', '', 28153),
(152530, 'esMX', 'Es un honor servir de amo de llaves a Lord y Lady Norwington. Si busca una habitación para descansar, no dude en preguntarme.', '', 28153),
(152529, 'esMX', 'Una finca de este nivel requiere mucho mantenimiento. Entre forjar herraduras, reparar herramientas y alguna que otra tarea extraordinaria de tanto en tanto, ¡el trabajo del herrero nunca termina!', '', 28153),
(152528, 'esMX', '¿Necesitas reparar algo? Mi especialidad son las herraduras de caballo, pero puedo revisar tu armadura si quieres.', '', 28153),
(152527, 'esMX', '', 'Corran. ¡CORRAN!', 28153),
(152526, 'esMX', '', 'Es muy sencillo. Si no te lastimas, no tendré que curarte.', 28153),
(152525, 'esMX', '', 'Yo los detendré todo el tiempo que pueda.', 28153),
(152524, 'esMX', 'La pesca se te da bien. ¡Sabía que lo lograrías! Y además, ¡aún conservas brazos y piernas!', '', 28153),
(152523, 'esMX', 'Los gusanos de arena son depredadores que acechan bajo las dunas. Son peligrosos, ¡pero sus colmillos valen fortunas! ¡Toma mi caña de pescar y fíjate qué encuentras!', '', 28153),
(152522, 'esMX', 'Todo puede empeorar, siempre. Hacemos lo mejor que podemos con lo que tenemos.', '', 28153),
(152521, 'esMX', 'La flota kultirana obedece mis órdenes. Y ahora ustedes también.', '', 28153),
(152520, 'esMX', '', 'Creo... que no puedo continuar.', 28153),
(152519, 'esMX', '', 'Solo faltan algunos escalones. ¡No te dejaremos!', 28153),
(152518, 'esMX', 'Háganles probar una muestra del poder de nuestros nuevos aliados.', '', 28153),
(152517, 'esMX', 'Ya he renunciado a todo, Zem\'lan... me has arrebatado todo.', 'Ya he renunciado a todo, Zem\'lan... me has arrebatado todo.', 28153),
(152516, 'esMX', '¡Otro carnosito para dominar! Eh\'to será divertido.', '¡Otro carnosito para dominar! Eh\'to será divertido.', 28153),
(152514, 'esMX', '', '¡Vamos, ya casi llegamos!', 28153),
(152513, 'esMX', '', 'Solo debemos llegar al altar más adelante.', 28153),
(152512, 'esMX', '¿Creen que pueden detenerme? El destino de Kul Tiras quedó sellado hace mucho.', '', 28153),
(152507, 'esMX', 'Te concedo el honor de dar las buenas noticias. Yo me encargaré de que alguien se ocupe de estos cañones.', '', 28153),
(152506, 'esMX', '¡Ese fue el último!', '', 28153),
(152505, 'esMX', 'Ja, otro más cae. Solo queda uno...', '', 28153),
(152504, 'esMX', '¡FUEGO!', '', 28153),
(152503, 'esMX', 'Eso sí que llamó su atención. ¡Ten cuidado con la Horda mientras recargo!', '', 28153),
(152502, 'esMX', 'Bien, todo listo. ¡Cúbrete los oídos!', '', 28153),
(152501, 'esMX', 'Ojalá usaran su poder para sanar a Azeroth en lugar de lastimarla. Buen trabajo, adalid.', '', 28153),
(152500, 'esMX', 'Alguien está absorbiendo el poder de la azerita en este lugar. ¡Tienes que detenerlo!', '', 28153),
(152499, 'esMX', 'Y yo nos guiaré a nuestro glorioso futuro bajo las mareas.', '', 28153),
(152498, 'esMX', '', '¡Este poder... será... nuestro!', 28153),
(152497, 'esMX', '', '¡Nadie puede oponerse a los sethrak con este poder!', 28153),
(152496, 'esMX', '¡Recuperen las joyas y pónganlas en su lugar para que podamos pasar!', '', 28153),
(152495, 'esMX', '¡Los ojos de Sethraliss han desaparecido!', '', 28153),
(152494, 'esMX', 'Tengo todo lo que necesito. Háblame cuando estés $Ulisto:lista; para empezar el ritual.', '', 28153),
(152493, 'esMX', 'Lo vi andando como un pato hacia la ciudad. Eh\'pero que no haga el ridículo, si no la gente lo verá como una presa fácil.', '', 28153),
(152492, 'esMX', 'Te vi corriendo de un lado a otro durante mucho tiempo. Vi los desafíos que superah\'te y las victorias que lograh\'te con ese pequeñín. Deberías eh\'tar orgulloso de él. Y orgulloso de ti por no abandonarlo. Muchos aquí no habrían estado dispuestos a hacer algo así.\n\nCuida de Kua\'fon. Quizás le cueh\'te volar, pero no encontrará\' compañero más fiel.', '', 28153),
(152491, 'esMX', '', 'G\'huun... desea... este poder...', 28153),
(152490, 'esMX', '', '¡Eh\'ta energía nos fortalece! ¡No la detendrás!', 28153),
(152489, 'esMX', 'Ayudando', 'Ayudando', 28153),
(152488, 'esMX', 'Eviscerando', 'Eviscerando', 28153),
(152487, 'esMX', 'A veces siento que todo el pantano busca matarnos. ¡Qué bueno que estés a la altura del desafío!', '', 28153),
(152486, 'esMX', 'Tengo un mal presentimiento... Nuestros exploradores deberían haber vuelto hace mucho tiempo. Averigua la causa de su demora.', '', 28153),
(152484, 'esMX', '', 'Continuemos.', 28153),
(152483, 'esMX', '', 'Fue su padre el que nos guio hasta este valle, hace muchos años.', 28153),
(152482, 'esMX', '', 'Para nada. Era tan amable antes de que los susurros lo dominaran.', 28153),
(152481, 'esMX', '', '¿Lord Canto Tormenta siempre fue así de cruel?', 28153),
(152480, 'esMX', '', 'Bueno, creo que ya nos descubrieron.', 28153),
(152479, 'esMX', '', '¿Piensas dejarme morir?', 28153),
(152478, 'esMX', '¡La piedra vibra con el poder de la propia Azshara! Llévala a las fuerzas del fuerte de inmediato. Ellos sabrán que hacer.', '', 28153),
(152477, 'esMX', 'Gracias. ¡Pero tú y yo deberíamos marcharnos de aquí!', 'Gracias. ¡Pero tú y yo deberíamos marcharnos de aquí!', 28153),
(152476, 'esMX', '¡No me convertiré en alimento de los bebés de pterrordáctilo!', '¡No me convertiré en alimento de los bebés de pterrordáctilo!', 28153),
(152475, 'esMX', 'El comandante me dará una paliza cuando se entere de que me atrapó la fauna.', 'El comandante me dará una paliza cuando se entere de que me atrapó la fauna.', 28153),
(152474, 'esMX', '¡Gracias! Pensé que estaba siendo cuidadoso, pero otra bestia se me abalanzó desde el costado. Muy astuta.', '¡Gracias! Pensé que estaba siendo cuidadoso, pero otra bestia se me abalanzó desde el costado. Muy astuta.', 28153),
(152473, 'esMX', 'Uff, ¡esas garfas sí que duelen!', 'Uff, ¡esas garfas sí que duelen!', 28153),
(152472, 'esMX', 'Estos maldito\' pterrordáctilos son muy molestos. ¡No quiero que mis tropa\' se conviertan en su alimento!', 'Estos maldito\' pterrordáctilos son muy molestos. ¡No quiero que mis tropa\' se conviertan en su alimento!', 28153),
(152471, 'esMX', 'Estos maldito\' pterrordáctilos son muy molestos. ¡No quiero que mis tropa\' se conviertan en su alimento!', 'Estos maldito\' pterrordáctilos son muy molestos. ¡No quiero que mis tropa\' se conviertan en su alimento!', 28153),
(152470, 'esMX', 'Estaba pensando en eliminar a los pterrordáctilos para poder usar ese punto de observación en la colina, pero nos matarán uno a uno muy fácilmente...', 'Estaba pensando en eliminar a los pterrordáctilos para poder usar ese punto de observación en la colina, pero nos matarán uno a uno muy fácilmente...', 28153),
(152469, 'esMX', 'Los mogu... hallarán... más... piedras...', '', 28153),
(152468, 'esMX', '¡El poder de esta piedra revivirá al imperio mogu!', '', 28153),
(152467, 'esMX', '¡Buen trabajo! Había más de los que esperaba.', '', 28153),
(152466, 'esMX', '¡Los gurubashi se han vuelto locos, eh\'tán matando a todos como desenfrenados! Ayudémoh\'los... ¡matándolos! ¡Toca el gong y verás cómo vienen corriendo!', '', 28153),
(152465, 'esMX', 'Nos han informado que hay actividad trol en la zona, y tememos que el ataque sea inminente. Necesitamos reducir sus números. ¡Golpea el gong en la cima de las escaleras para provocarlos!', '', 28153),
(152464, 'esMX', 'Cualquier cosa que puedas hacer para ayudarnos será agradecida.', 'Cualquier cosa que puedas hacer para ayudarnos será agradecida.', 28153),
(152463, 'esMX', '¡Dame un hacha y talaré!', '', 28153),
(152462, 'esMX', 'Mimbre, bestias... ¡me enfrentaré a lo que sea!', '', 28153),
(152461, 'esMX', '¡Los kultiranos no caeremos sin dar batalla!', '', 28153),
(152460, 'esMX', 'Gracias por la ayuda, $Uamigo:amiga;.', '', 28153),
(152459, 'esMX', '', '¡Tenemos compañía!', 28153),
(152458, 'esMX', '¡Vamos, vamos, vamos!', '¡Vamos, vamos, vamos!', 28153),
(152457, 'esMX', '¡Marinos, escuchen! Cuando lleguemos a la playa, quiero que $n tome la delantera. Usa esa bonita pistola de bengalas para iluminar todo lo que se mueva.', '¡Marinos, escuchen! Cuando lleguemos a la playa, quiero que $n tome la delantera. Usa esa bonita pistola de bengalas para iluminar todo lo que se mueva.', 28153),
(152456, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(152455, 'esMX', '¡Aplasten a estos intrusos o me quedaré con su bonificación por riesgo, gusanos!', '', 28153),
(152454, 'esMX', 'Protocolo de reparación de emergencia en curso...', '', 28153),
(152453, 'esMX', '¡Azerita, dulce azerita!', '', 28153),
(152452, 'esMX', '¡Taladra, bebé, taladra!', '', 28153),
(152451, 'esMX', '', 'Será bueno si Canto Tormenta no nos descubre recorriéndolo.', 28153),
(152450, 'esMX', '', 'Es directo.', 28153),
(152449, 'esMX', '', '¿Y eso es... bueno?', 28153),
(152448, 'esMX', '', 'Los maresabios recorren este sendero ceremonial antes de recibir la bendición del santuario.', 28153),
(152447, 'esMX', '', '¡Sus heridas no sanarán mientras estén afectados por la maldición!', 28153),
(152446, 'esMX', '', 'Este no puede ser el fin.', 28153),
(152445, 'esMX', '', 'Si fallan, ¡estaré perdida!', 28153),
(152444, 'esMX', '', '¡No debes caer!', 28153),
(152443, 'esMX', '¡Cuidado! ¡Combustible en niveles críticos!', '', 28153),
(152442, 'esMX', '¡Cuidado! Se ha detectado un usuario no autorizado.', '', 28153),
(152441, 'esMX', '¡Cuidado! No te quedan puntos en la licencia.', '', 28153),
(152440, 'esMX', 'Aquí viene otro, ¡prepárate!', 'Aquí viene otro, prepárate para escupir.', 28153),
(152439, 'esMX', 'Escupe más alto, llegará más lejos y no fallarás.', 'Escupe más alto, llegará más lejos y no fallarás.', 28153),
(152438, 'esMX', '¡Prepárate!', '¡Prepárate!', 28153),
(152437, 'esMX', 'Escupe apenas despeguen. ¡Así no podrás fallar!', 'Escupe apenas despeguen. ¡Así no podrás fallar!', 28153),
(152436, 'esMX', '¡Enaaanooooooo en camiiiiiinoooooo!', '', 28153),
(152435, 'esMX', 'Es una pena que la azerita esté enloqueciendo a los elementales. Otro motivo más para ponerle fin a esto.', '', 28153),
(152434, 'esMX', 'Algunos elementales de tierra han sido imbuidos con azerita y están enloqueciendo. ¡Acaba con ellos y absorbe su azerita!', '', 28153),
(152433, 'esMX', '¡Han llegado! ¡Enciendan las municiones!', '', 28153),
(152432, 'esMX', '', 'Las piedras se estremecen... ¡debemos tomarlas todas!', 28153),
(152431, 'esMX', '', '¡El poder de esta piedra será el combustible de nuestro imperio!', 28153),
(152430, 'esMX', '<Glibb te mira con curiosidad. Brann no tiene el valor para decirle que no es un mono.>', '<Glibb te mira con curiosidad. Brann no tiene el valor para decirle que no es un mono.>', 28153),
(152429, 'esMX', '$UBienvenido:Bienvenida; a Nidal del Halcón. Gracias a ti hemos expulsado a los monstruos y recuperamos la ciudad. Por favor, quédate todo el tiempo que quieras.', '$UBienvenido:Bienvenida; a Nidal del Halcón. Gracias a ti hemos expulsado a los monstruos y recuperamos la ciudad. Por favor, quédate todo el tiempo que quieras.', 28153),
(152428, 'esMX', 'Parece que esas armas son de origen goblin. Sea como sea, nos servirán contra los sethrak.', '', 28153),
(152427, 'esMX', 'Nisha ha recogido una especie de... arma interesante que podemos usar contra los sethrak, si descubrimos cómo usarla.', '', 28153),
(152426, 'esMX', '¡Nunca he visto nada como estos monstruos!', '¡Nunca he visto nada como estos monstruos!', 28153),
(152425, 'esMX', '¿Puedo irme volando?', '¿Puedo irme volando?', 28153),
(152424, 'esMX', 'Me temo que ahora no es posible. \n\nIntenté irme volando cuando empezó el desastre, pero nos dispararon desde la tierra con magia. A Lionel le dieron en el flanco y por poco no llegamos vivos a Halcónida.\n\nEl alcalde Royston nos dijo que nos quedáramos hasta que recuperáramos la ciudad o mejorara la situación.\n\nLo siento, pero estamos anclados.', 'Me temo que ahora no es posible. \n\nIntenté irme volando cuando empezó el desastre, pero nos dispararon desde la tierra con magia. A Lionel le dieron en el flanco y por poco no llegamos vivos a Halcónida.\n\nEl alcalde Royston nos dijo que nos quedáramos hasta que recuperáramos la ciudad o mejorara la situación.\n\nLo siento, pero estamos anclados.', 28153),
(152423, 'esMX', 'Bueno, eso no me lo esperaba. Estoy seguro de que nuestros magos querrán echarle un vistazo a esta cosa. Excelente trabajo, adalid.', '', 28153),
(152422, 'esMX', 'Los informes de inteligencia indican que la Horda planea obtener una especie de artefacto de estos sethrak. Consigámoslo antes que ellos, ¿de acuerdo?', '', 28153),
(152421, 'esMX', 'Manos a la obra, $n.', '', 28153),
(152420, 'esMX', '¡Guaaaaaaaaaaaaaaaaaaau!', '', 28153),
(152417, 'esMX', '', '¡Bien hecho, adalid! Esas cosas deberían quedarse bajo tierra, donde pertenecen.', 28153),
(152416, 'esMX', '', 'Criaturas asquerosas... Sacrifican a su propia gente para crear monstruosidades. ¡Detenlas antes de que nos arrasen las plantas carnívoras!', 28153),
(152415, 'esMX', '<Hacer cola con mi grupo para una Expedición insular en dificultad normal.>', '<Hacer cola con mi grupo para una Expedición insular en dificultad normal.>', 28153),
(152414, 'esMX', '', '¡La azerita... está bajo nueh\'tro... control!', 28153),
(152413, 'esMX', '', '¡Manipulo la azerita para mi magia de sangre!', 28153),
(152412, 'esMX', '¡Que me parta un rayo! Claro que eh\'toy listo para un motín. ¡Llevo semana\' aquí colgado!', '¡Que me parta un rayo! Claro que eh\'toy lista para un motín. ¡Llevo semana\' aquí colgada!', 28153),
(152411, 'esMX', '', 'Interesante. Puede que esto nos ayude a comprender el extraño fenómeno que hemos visto por Nazmir, y también el origen de estos sañosos trols de sangre.', 28153),
(152410, 'esMX', '', 'Nuestros investigadores han solicitado que estemos alerta por si encontramos artefactos, especialmente para que no caigan en manos de la Horda. Registra estas ruinas.', 28153),
(152409, 'esMX', 'Nunca vi un motín que no me guh\'tara. Cuenta conmigo.', 'Nunca vi un motín que no me guh\'tara. Cuenta conmigo.', 28153),
(152407, 'esMX', 'Claro que me uniré a tu motín, mequetrefe. El rey pirata Zem\'lan pagará por traicionarme.', 'Claro que me uniré a tu motín, mequetrefe. El rey pirata Zem\'lan pagará por traicionarme.', 28153),
(152406, 'esMX', 'Si tienes oro, será un gusto que lo gastes aquí.\n\nSi no interfieres con mis negocios, mi gente no interferirá contigo, ¿de acuerdo?', 'Si tienes oro, será un gusto que lo gastes aquí.\n\nSi no interfieres con mis negocios, mi gente no interferirá contigo, ¿de acuerdo?', 28153),
(152405, 'esMX', '', 'Tienes que hablar con los peces gordos de aquí: Klause Céfiro, Kane Carlyle, Clonk Grasoso y Fixi Filoartero.\n\nVe como mi agente, averigua si necesitan algún favor. Necesitaré el apoyo de ellos también.\n\nY a menos que surja otra cosa, yo seguiré hablando con la gente decente, honorable pero interesada, de este lugar.', 28153),
(152404, 'esMX', '¿Con quién tengo que hablar?', '¿Con quién tengo que hablar?', 28153),
(152403, 'esMX', 'No podemos hacer un motín solos, $p. ¡Recluta a otros!', '', 28153),
(152402, 'esMX', '¿Dónde está tu dueño?', '', 28153),
(152401, 'esMX', 'No eres una bestia muy educada.', '', 28153),
(152400, 'esMX', 'Iba a comerme eso.', '', 28153),
(152399, 'esMX', '...deberías detenerte.', '', 28153),
(152398, 'esMX', '¡Tiene\' que pagar por eso!', '¡Tiene\' que pagar por eso!', 28153),
(152397, 'esMX', '¡Eso no es tuyo!', '¡Eso no es tuyo!', 28153),
(152396, 'esMX', '¡Ey! ¡Eh\'cupe eso!', '¡Ey! ¡Eh\'cupe eso!', 28153),
(152395, 'esMX', 'Mis huesos volverán a alzarse.', '', 28153),
(152394, 'esMX', '¡Levántense, mis marioneta\'! ¡Deh\'truyan $Ual intruso:a la intrusa;!', '', 28153),
(152393, 'esMX', 'Acérquense, buitres... Este es el festín... que estaban esperando...', '', 28153),
(152392, 'esMX', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[suelta]|h|r el orbe!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t$n |cFFFF0000|Hspell:267343|h[suelta]|h|r el orbe!', 28153),
(152391, 'esMX', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t¡Le han |cFFFF0000|Hspell:267633|h[arrebatado]|h|r el orbe a $s!', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t¡Le han |cFFFF0000|Hspell:267633|h[arrebatado]|h|r el orbe a $s!', 28153),
(152390, 'esMX', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡%s |cFFFF0000|Hspell:265755|h[recupera]|h|r uno de los orbes!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t¡%s |cFFFF0000|Hspell:265755|h[recupera]|h|r uno de los orbes!', 28153),
(152389, 'esMX', '¡Te colgaré de los pies y dejaré que los buitres te coman vivo!', '', 28153),
(152388, 'esMX', 'Primero, haremo\' correr la voz. Debes comprender a qué nos enfrentamos exactamente.', '', 28153),
(152387, 'esMX', '¡Que empiece el motín!', '', 28153),
(152386, 'esMX', 'Quiero preguntar algo más.', 'Quiero preguntar algo más.', 28153),
(152385, 'esMX', '¡Ey! ¡Bah\'ta!', '¡Ey! ¡Bah\'ta!', 28153),
(152384, 'esMX', '¡Fuera!', '¡Fuera!', 28153),
(152383, 'esMX', '¡Fuera, fuera!', '¡Fuera, fuera!', 28153),
(152382, 'esMX', '¡Bah\'ta de barullo!', '¡Bah\'ta de barullo!', 28153),
(152381, 'esMX', '¡Baja de ahí!', '¡Baja de ahí!', 28153),
(152380, 'esMX', '¿Un loro? ¿Y las cometas?', '¿Un loro? ¿Y las cometas?', 28153),
(152379, 'esMX', '<Tan se burla.>\n\nLos loros son mucho más inteligentes y más interesantes que una cometa.\n\n<Tan abre un ojo y mira a su ave.>\n\nAunque a veces solo griten por diversión.', '<Tan se burla.>\n\nLos loros son mucho más inteligentes y más interesantes que una cometa.\n\n<Tan abre un ojo y mira a su ave.>\n\nAunque a veces solo griten por diversión.', 28153),
(152378, 'esMX', 'Desde que llegaron los mareaférrea, Richard Velajada tiene que autorizar el ingreso y la salida de las naves.\n\nSe supone que lo hace para que la caleta sea \"secreta\" y \"segura\", pero en mi opinión, su propósito es controlar todo.\n\nTendría que autorizarlo él. Mira, pagaré con mi pellejo y con las alas de mis aves si no hago caso.\n\n<Tan se inclina hacia adelante y baja la voz.>\n\nO tendría que haber otra persona a cargo.', 'Desde que llegaron los mareaférrea, Richard Velajada tiene que autorizar el ingreso y la salida de las naves.\n\nSe supone que lo hace para que la caleta sea \"secreta\" y \"segura\", pero en mi opinión, su propósito es controlar todo.\n\nTendría que autorizarlo él. Mira, pagaré con mi pellejo y con las alas de mis aves si no hago caso.\n\n<Tan se inclina hacia adelante y baja la voz.>\n\nO tendría que haber otra persona a cargo.', 28153),
(152377, 'esMX', '¿Puedo tomar un vuelo para irme de aquí?', '¿Puedo tomar un vuelo para irme de aquí?', 28153),
(152376, 'esMX', 'Necesito que me ayudes. Me ataron muy bien después de la última vez que intenté eh\'capar.', '', 28153),
(152375, 'esMX', '¡Estupendo! ¡Me largo de aquí!', '¡Estupendo! ¡Me largo de aquí!', 28153),
(152374, 'esMX', 'Quizás... si te sientes valiente... ¡dile que la próxima traeré un sombrero!', '', 28153),
(152373, 'esMX', '¿Ahora no ere\' tan grande ni tan fuerte, eh? Vamos, esbirro. Encuentra a esa rata de Alfin que te dijo que mataras a los mío\'. Muérdelo y adopta tu forma real otra vez.', '', 28153),
(152372, 'esMX', '¿La Horda está aquí? ¡¿De dónde han salido?! ¿Quién nos protegerá?', '¿La Horda está aquí? ¡¿De dónde han salido?! ¿Quién nos protegerá?', 28153),
(152371, 'esMX', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Merektha |cFFFF0000|Hspell:264206|h[excava]|h|r para atravesar el campo de batalla!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t¡Merektha |cFFFF0000|Hspell:264206|h[excava]|h|r para atravesar el campo de batalla!', 28153),
(152370, 'esMX', 'Gracias, $Uamigo:amiga;. ¡Si no hubiera sido por ti, habría llegado mi fin!', 'Gracias, $Uamigo:amiga;. ¡Si no hubiera sido por ti, habría llegado mi fin!', 28153),
(152369, 'esMX', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n está $genvuelto:envuelta; en |cFFFF0000|Hspell:263958|h[Un nudo de serpientes]|h|r, ¡$glibéralo:libérala;!', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t$n está $genvuelto:envuelta; en |cFFFF0000|Hspell:263958|h[Un nudo de serpientes]|h|r, ¡$glibéralo:libérala;!', 28153),
(152368, 'esMX', 'El día en que la maldición se apoderó del Puerto de Zem\'lan... Hace tanto tiempo.', '', 28153),
(152367, 'esMX', 'Mi medallón te revelará una visión de mi pasado cuando quiera\'.', '', 28153),
(152366, 'esMX', 'Gra... gracias, $p. Me... Meeki es un buen amigo.', 'Gra... gracias, $p. Me... Meeki es un buen amigo.', 28153),
(152365, 'esMX', 'Te he fallado... Korthek...', '', 28153),
(152364, 'esMX', '¡Ah, así que anhelas morir! ¡Te concederé el deseo!', '', 28153),
(152363, 'esMX', 'Nadie puede... detenernos...', '', 28153),
(152362, 'esMX', '¡Imbécil insolente! ¡Pagarás por tu intromisión!', '', 28153),
(152361, 'esMX', '', 'Tu comandante te espera abajo, en el campo de batalla.', 28153),
(152360, 'esMX', 'Este no es... el final...', 'Este no es... el final...', 28153),
(152359, 'esMX', 'Encontramos un pergamino extraño que se supone que invoca un poder increíble. En la costa se están reuniendo muchos no-muertos. Veamos si este pergamino es tan poderoso como dicen.', '', 28153),
(152358, 'esMX', 'Este no es... el final...', 'Este no es... el final...', 28153),
(152357, 'esMX', 'Mi vida... por el imperio...', 'Mi vida... por el imperio...', 28153),
(152356, 'esMX', 'No puede ser...', 'No puede ser...', 28153),
(152355, 'esMX', 'Las arenas... se esparcirán...', 'Las arenas... se esparcirán...', 28153),
(152354, 'esMX', 'Vengarán... mi... muerte...', 'Vengarán... mi... muerte...', 28153),
(152353, 'esMX', 'Te he fallado... Korthek...', 'Te he fallado... Korthek...', 28153),
(152352, 'esMX', 'No han... ganado...', 'No han... ganado...', 28153),
(152351, 'esMX', 'No... nos... detendrán...', 'No... nos... detendrán...', 28153),
(152349, 'esMX', 'Mi vida... por el imperio...', 'Mi vida... por el imperio...', 28153),
(152348, 'esMX', 'No puede ser...', 'No puede ser...', 28153),
(152347, 'esMX', 'Las arenas... se esparcirán...', 'Las arenas... se esparcirán...', 28153),
(152346, 'esMX', 'Vengarán... mi... muerte...', 'Vengarán... mi... muerte...', 28153),
(152345, 'esMX', 'Te he fallado... Korthek...', 'Te he fallado... Korthek...', 28153),
(152344, 'esMX', 'No han... ganado...', 'No han... ganado...', 28153),
(152343, 'esMX', 'No... nos... detendrán...', 'No... nos... detendrán...', 28153),
(152342, 'esMX', '', 'Buen trabajo. Como siempre, podemos contar contigo.', 28153),
(152341, 'esMX', '', 'Adalid, estos trols de sangre han estado atacando Fuerte Victoria. ¡Demuéstrales que sus asaltos no quedarán impunes!', 28153),
(152340, 'esMX', '¡Rápido, ratas! ¡Esa azerita no estallará sola!', '', 28153),
(152339, 'esMX', '', 'Incendiaron Presabrenna. Ninguno de nosotros volverá a casa.', 28153),
(152338, 'esMX', '¡Tenemos que apresurarnos!', '', 28153),
(152337, 'esMX', 'Me recuerdas a un joven hozen que conocí una vez. Se creía el rey de los monos o algo así. No dejaba de picarme.', '', 28153),
(152336, 'esMX', 'Si piensas que puedes molestarme, te equivocas.', '', 28153),
(152335, 'esMX', 'Creo que tendríamos que comerciar con pueblos de todas las razas y credos... excepto los nagas. Criaturas horribles.', '', 28153),
(152334, 'esMX', 'Si encuentras artefactos poderosos, tráemelos, y no se te ocurra usarlos por tu cuenta.', '', 28153),
(152333, 'esMX', 'Mmm. Los artefactos poderosos deben quedar en manos de los mayores, no de un aventurero revoltoso.', '', 28153),
(152332, 'esMX', 'Nunca subestimes el valor o el poder de algo que tiene más de dos siglos.', '', 28153),
(152331, 'esMX', 'Bla, bla, bla. Termina de una vez.', '', 28153),
(152330, 'esMX', '¿Cuáles son tus honorarios de héroe y los gastos de entierro estimados?', '', 28153),
(152329, 'esMX', 'Ah, qué bien, $uun aventurero:una aventurera;. Necesito tus servicios.', '', 28153),
(152328, 'esMX', 'Les presento... ¡la cadena rocosa!', '', 28153),
(152327, 'esMX', '¡Tienen su futuro frente a sus ojos, chicos!', '', 28153),
(152326, 'esMX', 'Felicitaciones, chicos, ¡seremos ricos!', '', 28153),
(152325, 'esMX', '', '¡Pasa, pasa! Vamos, ¡sin miedo!', 28153),
(152324, 'esMX', 'Nunca aceptes regalos del Imperio Negro.', '', 28153),
(152323, 'esMX', 'Tal vez volvamos a encontrarnos en el campo de batalla. Lado a lado, espalda contra espalda, superados en número, en armas y en fuerza. Je, je.', '', 28153),
(152322, 'esMX', '¡Es mi turno, ven y toma los peces!', '', 28153),
(152321, 'esMX', '¡Siéntate, hermana!', '', 28153),
(152320, 'esMX', '¡Eres una inmadura!', '', 28153),
(152319, 'esMX', '¡Ey! ¡Eh\'pantaste a mis peces!', '', 28153),
(152318, 'esMX', '', '¡CRA! ¡Soy Pa\'ku! ¡Fiuuu!', 28153),
(152317, 'esMX', '', 'Miren, ¡soy Gral!', 28153),
(152316, 'esMX', '', '¡Taz\'okun!', 28153),
(152315, 'esMX', '', '¡Uiii!', 28153),
(152314, 'esMX', 'Buena suerte. Trata de no morir.', '', 28153),
(152313, 'esMX', 'Cuídate la espalda. O consigue un caparazón.', '', 28153),
(152312, 'esMX', 'Pagarán...', 'Pagarán...', 28153),
(152311, 'esMX', 'No es... justo...', 'No es... justo...', 28153),
(152310, 'esMX', '¡Discípulos! ¡Los intrusos se acercan a las pozas sagradas!', '', 28153),
(152309, 'esMX', 'No... Esto es mío...', 'No... Esto es mío...', 28153),
(152308, 'esMX', 'Cómo... te... atreves...', 'Cómo... te... atreves...', 28153),
(152307, 'esMX', '¡Parece que estoy cobrándote el pellejo!', '¡Parece que estoy cobrándote el pellejo!', 28153),
(152306, 'esMX', 'Me gusta hacer un poco de alboroto. Algunas veces he participado en peleas, e incluso me he enfrentado a puñetazos.', '', 28153),
(152305, 'esMX', '¡Por eso, te cobraré el doble!', '¡Por eso, te cobraré el doble!', 28153),
(152304, 'esMX', '¡Parece que te estuviera cobrando un brazo y una pierna!', '¡Parece que te estuviera cobrando un brazo y una pierna!', 28153),
(152303, 'esMX', '¡Ey! ¡Eso te va a costar caro!', '¡Ey! ¡Eso te va a costar caro!', 28153),
(152302, 'esMX', 'Me han traicionado más razas de las que conoces, así que ni siquiera lo pienses.', '', 28153),
(152301, 'esMX', 'La muerte e\' la única piedad que Zem\'lan tiene para ofrecer. Y mucho\' ni siquiera tienen esa suerte.', '', 28153),
(152300, 'esMX', 'Cavando', 'Cavando', 28153),
(152299, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(152298, 'esMX', '', 'No descansaré hasta que la cabeza de Lord Canto Tormenta cuelgue de estos muros.', 28153),
(152297, 'esMX', '', '¡Esa es la potencia de fuego que buscábamos!', 28153),
(152296, 'esMX', 'Aah... está... bien...', 'Aah... está... bien...', 28153),
(152295, 'esMX', 'Pagarán...', 'Pagarán...', 28153),
(152294, 'esMX', 'No pueden... derrotarme...', 'No pueden... derrotarme...', 28153),
(152293, 'esMX', 'Pero... yo mando...', 'Pero... yo mando...', 28153),
(152292, 'esMX', '¿Conque quieres ser jefa, eh? ¡Ja! ¡Te haré pedazos como al último!', '¿Conque quieres ser jefa, eh? ¡Ja! ¡Te haré pedazos como al último!', 28153),
(152291, 'esMX', '¡Yo dirijo este lugar! ¡Será mejor que te pongas en fila!', '¡Yo dirijo este lugar! ¡Será mejor que te pongas en fila!', 28153),
(152290, 'esMX', 'Silencio, todos. Meeki está bien y yo intento volver a dormir.', 'Silencio, todos. Meeki está bien y yo intento volver a dormir.', 28153),
(152289, 'esMX', '¡Haré que te arrastren por la quilla!', '¡Haré que te arrastren por la quilla!', 28153),
(152288, 'esMX', '¡Nadie alza sus velas contra los mareaférrea!', '¡Nadie alza sus velas contra los mareaférrea!', 28153),
(152287, 'esMX', '¡Cómo te atreves!', '¡Cómo te atreves!', 28153),
(152286, 'esMX', 'Si encuentras tesoros en el camino, tráelos a tu regreso. Quizás tu esfuerzo valga la pena.', 'Si encuentras tesoros en el camino, tráelos a tu regreso. Quizás tu esfuerzo valga la pena.', 28153),
(152285, 'esMX', 'Pagarán...', 'Pagarán...', 28153),
(152284, 'esMX', 'Nadie alza sus velas contra los mareaférrea...', 'Nadie alza sus velas contra los mareaférrea...', 28153),
(152283, 'esMX', 'Te.... atraparé...', 'Te.... atraparé...', 28153),
(152282, 'esMX', 'Lo siento... jefe...', 'Lo siento... jefe...', 28153),
(152281, 'esMX', '¡No debes estar aquí!', '¡No debes estar aquí!', 28153),
(152280, 'esMX', '¿Qué haces fisgoneando por aquí?', '¿Qué haces fisgoneando por aquí?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'esMX', '¡Este no es tu lugar!', '¡Este no es tu lugar!', 28153),
(152278, 'esMX', '¡Ey!', '¡Ey!', 28153),
(152277, 'esMX', '', '¿Sabías que puedes agregar branquias de tiburón ballena en la sopa? Previenen el deterioro de las escamas. ¿Qué? ¿De qué hablábamos?', 28153),
(152276, 'esMX', '', 'Bueno, cuando dije \"todos\" supongo que me refería a la gente que tiene oro para gastar. Humanos, goblins, tauren, elfos, lo que sea. El dinero es dinero, no importa de dónde venga.\n\n<Cesi te mira de arriba abajo>\n\nAh. Quieres saber si comerciaría con la Horda.\n\nMira, tengo que ganarme el pan. Si tengo unas anclas que se cayeron de un barco, se las vendo al primero que encuentro. Así trabajo yo. Cuando sea jefa, todos podrán comerciar en la caleta.\n\nY tú no quieres hacer negocios con esos piratas mareaférrea, ¿no?\n\nCréeme, $Uamigo:amiga;, esto será maravilloso.', 28153),
(152275, 'esMX', 'Mis criatura\' tienen mejores modale\' que tú.', '', 28153),
(152274, 'esMX', '¿Qué quieres decir con abrir el mercado a \"todos\"?', '¿Qué quieres decir con abrir el mercado a \"todos\"?', 28153),
(152271, 'esMX', 'A meno\' que quieras ofrendarme ese dedo, será mejor que no juegues conmigo.', '', 28153),
(152270, 'esMX', 'La posada local está repleta de refugiados, pero tengo un cuarto vacío en renta si necesitas alojamiento.', '', 28153),
(152269, 'esMX', 'Recuerda, si encuentras algo brillante, se lo trae\' al viejo Jani.', '', 28153),
(152268, 'esMX', 'Cuando te vayas, ¿me puedo quedar con tus cosa\'?', '', 28153),
(152266, 'esMX', '¿Buscabas un amigo? ¡Loa-s encontrado! ¡Ja!', '', 28153),
(152265, 'esMX', '¡Bien hecho, adalid! Estas tierras son más seguras gracias a tus esfuerzos.', '', 28153),
(152264, 'esMX', 'Nuestros espías han detectado una amenaza peligrosa en el área. ¡Búscala y elimínala!', '', 28153),
(152263, 'esMX', '', '¡Reconstrúyanlas y maten a su mascota o no tendremos nada para repeler la flota de Aspafresno!', 28153),
(152262, 'esMX', '', 'Era un tortollano muy orgulloso, aunque el caparazón le quedaba grande, si me entiendes... Se lo comió un tiburón ballena, una pena.', 28153),
(152261, 'esMX', '', 'Casi no me di cuenta de que estaba roncando. Tiene la voz tan ronca como sus ronquidos. Como mi segundo nieto, de hecho.', 28153),
(152260, 'esMX', '', 'Algunos dicen que me voy por las ramas. Mi hermana era peor. Una vez se quedó dormida mientras hablaba.', 28153),
(152259, 'esMX', 'El tesoro de uno es la basura de otro\'.', '', 28153),
(152258, 'esMX', '', 'Los aventureros son tan amables últimamente.', 28153),
(152257, 'esMX', '', 'Ah, ¿no fue lindo?', 28153),
(152256, 'esMX', '', 'Ven a ver a la vieja Nola alguna vez.', 28153),
(152255, 'esMX', '', 'Esto me recuerda una historia...', 28153),
(152254, 'esMX', '', '¡Pero qué joven y vivaz eres!', 28153),
(152253, 'esMX', '', 'Qué bueno verte, cariño.', 28153),
(152252, 'esMX', 'Transblagrificador. ¡Hace que las ideas terribles no sean tan malas!', 'Transblagrificador. ¡Hace que las ideas terribles no sean tan malas!', 28153),
(152251, 'esMX', '¡Kaja\'cola, ahora con agua de verdad!', '¡Kaja\'cola, ahora con agua de verdad!', 28153),
(152250, 'esMX', '', 'Creo que apreciarías una buena historia.', 28153),
(152249, 'esMX', '', 'Veámonos al norte de este infierno cuando consigas la vara. Sigue el rastro de estos bastardos muertos.', 28153),
(152248, 'esMX', 'Sigue así y verá\' por qué dicen que soy un gruñón.', '', 28153),
(152246, 'esMX', 'Saludos, $Uricachón:ricachona;.', '', 28153),
(152243, 'esMX', 'Como siempre digo, la basura de un colega es el loa de otro.', '', 28153),
(152241, 'esMX', '', 'Nazmir alberga demasiadas amenazas. Al menos ahora hay una menos.', 28153),
(152239, 'esMX', '', '¿Qué son esas cosas? ¡Adalid! Nuestros ingenieros tienen la herramienta ideal. ¡Tómala y quémalos antes de que lleguen a nuestros campamentos!', 28153),
(152232, 'esMX', 'Es bueno contar con tu amistad. Gracias a ti, estas dunas son un poco más seguras.', '', 28153),
(152231, 'esMX', 'Nuestra caravana ha divisado un peligro en las dunas. Confío en que te encargarás de eso.', '', 28153),
(152230, 'esMX', 'Taelia, $p, ustedes deberán soportar esta carga. Me llevaré a Samuel, los espero en el santuario. Vengan cuanto antes.', '', 28153),
(152229, 'esMX', 'En comunión', 'En comunión', 28153),
(152228, 'esMX', 'Sabía que eras inteligente. Vamos, te veré allí.', 'Sabía que eras inteligente. Vamos, te veré allí.', 28153),
(152227, 'esMX', 'Si quieres librarte de ellos, buena suerte. Soy contrabandista, no mercenario.', 'Si quieres librarte de ellos, buena suerte. Soy contrabandista, no mercenario.', 28153),
(152226, 'esMX', 'Bien, tal vez sea hora de que los mareaférrea se vayan.', 'Bien, tal vez sea hora de que los mareaférrea se vayan.', 28153),
(152225, 'esMX', 'Los mareaférrea me están exprimiendo todo el oro, Cesi. Apenas puedo pagar las cuentas.', 'Los mareaférrea me están exprimiendo todo el oro, Cesi. Apenas puedo pagar las cuentas.', 28153),
(152224, 'esMX', 'Ahora... ¡que comience la cacería!', '', 28153),
(152223, 'esMX', '', 'Mira, ¡todavía podemos ganar algo de dinero con esto!', 28153),
(152222, 'esMX', '', 'Estas personas intentaban escapar. Tiene que haber sobrevivientes en algún lugar.', 28153),
(152221, 'esMX', 'Esto es una prueba.', 'Esto es una prueba.', 28153),
(152220, 'esMX', 'Deberíamos atacar ahora, antes de que los rumores lleguen a Lord Canto Tormenta.', '', 28153),
(152219, 'esMX', '|cFF0000FF(Misión)|r Zarpar rumbo a Nazmir.', '|cFF0000FF(Misión)|r Zarpar rumbo a Nazmir.', 28153),
(152218, 'esMX', '', 'Está nave está a tu disposición, $n. La tripulación está preparada para cualquier eventualidad.', 28153),
(152217, 'esMX', '¿Dónde deberíamos concentrar nuestros esfuerzos?', '', 28153),
(152216, 'esMX', 'Ey, son cosas que pasan. La próxima vez que vean a esos muchachos, piensen en la dulce venganza.', '', 28153),
(152215, 'esMX', 'No se depriman, de todos modos conseguimos un botín decente.', '', 28153),
(152214, 'esMX', '¡Todos a bordo! Tenemos que largarnos de aquí antes de que perdamos nuestra nave.', '', 28153),
(152213, 'esMX', 'No se puede ganar siempre, ¿no? La próxima serán nuestros.', '', 28153),
(152212, 'esMX', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t¡Algunas de las defensas comienzan a |cFFFF0000|Hspell:267931|h[sobrecargarse]|h|r!', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t¡Algunas de las defensas comienzan a |cFFFF0000|Hspell:267931|h[sobrecargarse]|h|r!', 28153),
(152211, 'esMX', 'Eh, ya tenemo\' suficiente. Larguémono\' de aquí.', '', 28153),
(152210, 'esMX', 'No se pueden ganar toda\' las batalla\', así es la vida.', '', 28153),
(152209, 'esMX', 'Eh, ya tenemo\' que irno\'. La próxima vez será suyo\'.', '', 28153),
(152208, 'esMX', '¡Buen trabajo ahí afuera! Les dieron una lección, ¡ja, ja!', '', 28153),
(152207, 'esMX', 'Listo. Eh, prueben su puntería con ese navío de la Alianza cuando pasemo\' cerca. ¡Ja!', '', 28153),
(152206, 'esMX', 'El casco eh\'tá lleno. Desplieguen las vela\' y vámono\' a casa.', '', 28153),
(152205, 'esMX', '¡Eso eh\' todo lo que necesitamo\'! ¡Vámono\'! ¡Ja, ja!', '', 28153),
(152204, 'esMX', 'Tomen lo que puedan, tendremo\' que partir pronto.', '', 28153),
(152203, 'esMX', 'Parece que el otro navío partirá pronto. Tenemo\' que moverno\' rápido.', '', 28153),
(152202, 'esMX', 'Parece que esa nave kultirana eh\'tá casi llena. Tendremo\' que marcharno\' pronto.', '', 28153),
(152201, 'esMX', 'Ya casi terminamos, mantengan un perfil bajo un rato más.', '', 28153),
(152200, 'esMX', 'El casco eh\'tá casi lleno. Solo un poco más y terminaremos.', '', 28153),
(152199, 'esMX', 'Ya casi terminamos. Buen trabajo.', '', 28153),
(152198, 'esMX', 'Ja, ja, no puedo mantenerme en pie con eh\'te temblor. Debe haber un elemental de tierra poderoso por aquí que buh\'ca azerita como nosotro\'.', '', 28153),
(152197, 'esMX', 'El viento está haciendo estrago\'... Apuesto a que hay un elemental de aire detrás de todo eh\'to. Seguramente tenga un montón de azerita. ¡Lista para recoger!', '', 28153),
(152196, 'esMX', 'Eh, eh\'ta ventisca seguramente viene de un Señor del agua poderoso. Acaben con su miseria de inmediato. Odio el frío.', '', 28153),
(152195, 'esMX', 'Está haciendo calor ahí. Debe haber un Señor del fuego que se quiere llevar nueh\'tra azerita. Extínganlo ante\' de que se prendan fuego las vela\'. Ja, ja.', '', 28153),
(152194, 'esMX', 'Debe haber un Señor de los elemento\' detrás de eh\'to. Mátenlo, y quítenle la azerita también.', '', 28153),
(152193, 'esMX', 'Los elemento\' están en nuestra contra hoy. Posiblemente busquen lo mismo que nosotro\'.', '', 28153),
(152192, 'esMX', 'Eh, hemo\' llamado la atención de algunos elementale\' poderoso\'. Tengan cuidado con su líder.', '', 28153),
(152191, 'esMX', 'Eh\'te clima no es normal. Algún elemental poderoso debe venir a buh\'car nuestra azerita.', '', 28153),
(152190, 'esMX', 'Les queda la mitad del barco por llenar. Abran bien los ojo\'.', '', 28153),
(152189, 'esMX', 'Eh\'tán haciendo un trabajo excelente, ya tenemo\' la mitad.', '', 28153),
(152188, 'esMX', 'El casco está medio lleno. Sigan así y terminaremo\' en un santiamén.', '', 28153),
(152187, 'esMX', 'Eh\'to se va a poner un poco más interesante.', '', 28153),
(152186, 'esMX', 'Acaban de llegar algunos amiguitos, je, je.', '', 28153),
(152185, 'esMX', 'Eh, abran bien los ojos. Tenemo\' compañía.', '', 28153),
(152184, 'esMX', 'Ya llegamo\'. !A trabajar! ¡La azerita los eh\'pera!', '', 28153),
(152183, 'esMX', '¡El navío ha atracado! Intenten no morir ahí afuera, je, je.', '', 28153),
(152182, 'esMX', 'Ya pueden bajar, amigos. Pondremo\' a funcionar el detector.', '', 28153),
(152181, 'esMX', 'Eh, tenemo\' un montón de azerita por aquí. Vayan a echar un vih\'tazo.', '', 28153),
(152180, 'esMX', 'Un trozo enorme de azerita acaba de surgir de la tierra. ¡Andando! ¡Ja, ja, jaja!', '', 28153),
(152179, 'esMX', 'Eh, el dispositivo eh\'tá enloqueciendo. Debe haber una gran concentración de azerita ahí afuera.', '', 28153),
(152178, 'esMX', '¡Ja, ja, ja! Hemos pueh\'to a andar el detector. Marcaré los nodo\' de azerita en tu mapa.', '', 28153),
(152177, 'esMX', 'El detector está activo. Busquen concentracione\' de azerita en su mapa.', '', 28153),
(152176, 'esMX', '¡Yo solo descansar ojos! ¡Yo volver al trabajo ahora!', '', 28153),
(152175, 'esMX', 'Muy bien, $ujefe:jefa;, yo volver a la mina.', '', 28153),
(152174, 'esMX', 'Sueño... tener tanto sueño...', '', 28153),
(152173, 'esMX', '¡Oh! ¡Muy bien, volveré al trabajo, $n!', '', 28153),
(152172, 'esMX', 'Encárgate de los aojadores hudú y los tótems derribadores.', 'Encárgate de los aojadores hudú y los tótems derribadores.', 28153),
(152171, 'esMX', 'Otro continente, otro demonio que cazar.', '', 28153),
(152170, 'esMX', '¡Ja! Esta tripulación nunca me defrauda. Eso me gusta.', '', 28153),
(152169, 'esMX', '¡Y... listo! Excelente trabajo, vámonos a casa.', '', 28153),
(152168, 'esMX', '¡Los depósitos de azerita están llenos! Marchémonos de aquí antes de que se den cuenta.', '', 28153),
(152167, 'esMX', '¡Y nosotros nos vamos! Guau, miren ese cargamento. Hicieron un gran trabajo.', '', 28153),
(152166, 'esMX', 'La Horda casi nos gana. ¡Recojan esa azerita tan rápido como puedan!', '', 28153),
(152165, 'esMX', 'Voy... con Xibala...', '', 28153),
(152164, 'esMX', 'Parece que la Horda está terminando. Quedaremos muy expuestos si no partimos pronto.', '', 28153),
(152163, 'esMX', 'La Horda ya casi termina. Intenten tomar todo lo que puedan, ¿de acuerdo?', '', 28153),
(152162, 'esMX', 'No quiero alarmarlos, pero el navío de la Horda luce bastante lleno. Y una vez que esté lleno, nosotros también tendremos que partir.', '', 28153),
(152161, 'esMX', '¡Falta poco para terminar! Abran bien los ojos y los oídos, ya casi lo logran.', '', 28153),
(152160, 'esMX', '¡La bodega resplandece brillante! Solo algunas rocas más y partiremos.', '', 28153),
(152159, 'esMX', 'El casco está casi lleno de azerita. ¡Preparen las velas! Podemos partir en cuanto terminen.', '', 28153),
(152158, 'esMX', '¡Eh, ya casi terminamos! Solo un poco más y zarparemos.', '', 28153),
(152157, 'esMX', '¿Por qué se sacude la tierra? Voy a vomitar. Oigan, hemos avistado algunos elementales de tierra, así que seguramente hay un Señor elemental detrás de esto. Encárguense de él antes de que pierda el apetito.', '', 28153),
(152156, 'esMX', 'Las velas no aguantarán mucho con este huracán. Un Señor elemental de viento debe estar enviando a sus esbirros por la azerita. Salir navegando será difícil mientras estén por aquí.', '', 28153),
(152155, 'esMX', 'Oigan, he-héroes... Un Señor del agua ha enviado a sus tropas a robar nuestra azerita y me estoy c-c-congelando. ¡Acaben con ellos! No traje mi ropa de invierno.', '', 28153),
(152154, 'esMX', 'Hace MUCHO calor. Pero qué demonios es... Ah. Eso lo explica todo. Un Señor del fuego ha enviado a sus esbirros a buscar azerita. Genial. Fantástico. Súper.', '', 28153),
(152153, 'esMX', '¡Llegamos a la mitad! Sigan así y nos largaremos de aquí en un abrir y cerrar de ojos.', '', 28153),
(152152, 'esMX', 'La mitad del casco está llena de azerita. Sigan así, lo están haciendo muy bien.', '', 28153),
(152151, 'esMX', '¡Estás pisando tierra sagrada!', '', 28153),
(152150, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(152149, 'esMX', 'El reconocimiento señaló estas ruinas. El campamento de la Horda está en la colina del noreste, así que mejor entramos y salimos lo más rápido posible.\n\nConseguiremos el Aliento de Xibala antes que ellos, te lo aseguro.\n\nHáblame cuando estés $Ulisto:lista; para empezar el reconocimiento.', '', 28153),
(152148, 'esMX', '¡El detector está en funcionamiento! Echen un vistazo al mapa para ver dónde está la azerita.', '', 28153),
(152147, 'esMX', 'El detector está activo. Marcaré las ubicaciones de azerita en el mapa. De nada.', '', 28153),
(152146, 'esMX', 'Acabo de identificar un gran cúmulo de cristales de azerita cerca. Seguramente a eso se deba el temblor.', '', 28153),
(152145, 'esMX', 'Guau. Ha aparecido una gran cantidad de azerita cerca de aquí. Será mejor que investiguemos antes que la Horda.', '', 28153),
(152144, 'esMX', '¡Hemos anclado y ya pueden bajar! Nosotros pondremos a funcionar el detector de azerita, ustedes encárguense de los tipos malos.', '', 28153),
(152143, 'esMX', '¡El navío ha atracado! Disfruten de su aventura mientras activamos el viejo detector de azerita.', '', 28153),
(152142, 'esMX', 'Hemos llegado, y este viento no es bueno para mi peinado. Tomemos la azerita y larguémonos rápido, ¿de acuerdo?', '', 28153),
(152141, 'esMX', 'Bueno, parece que tenemos un Señor de los elementos aquí en busca de la azerita que queremos. Estaré bajo cubierta mientras se encargan de esta... situación.', '', 28153),
(152140, 'esMX', 'Parece que la azerita llamó la atención de algunas fuerzas elementales. Quizás haya un Señor elemental interesado en nuestro botín. Pero nosotros lo vimos primero, ¿verdad?', '', 28153),
(152139, 'esMX', 'Supongo que la Horda también encontró este lugar. Su navío acaba de atracar.', '', 28153),
(152138, 'esMX', 'Oh, parece que la Horda está aquí. Cuídense ahí afuera, ¿de acuerdo?', '', 28153),
(152137, 'esMX', 'Veo un navío muy... dorado. Sí, definitivamente son zandalari. La Horda ha llegado, estén atentos.', '', 28153),
(152136, 'esMX', 'Yo era un aventurero como tú... después me puse bien, ja ja.', '', 28153),
(152135, 'esMX', 'Parece que has visto muchas cosas. Tenemos que intercambiar historias de guerra.', '', 28153),
(152134, 'esMX', 'Recuerdo la gran guerra del rey Raka y su hermana, la reina Tola. Bueno, alguna que otra parte. Mmm... estoy casi seguro de que esa guerra existió. Casi casi.', '', 28153),
(152133, 'esMX', 'Me recuerdas a un sujeto con el que asalté las playas de Krasarang en la tercera dinastía. Una pena que los mogu le hayan hecho eso.', '', 28153),
(152132, 'esMX', '¡No es hora de Picodulce! ¡Cra!', '', 28153),
(152131, 'esMX', 'Por esto no me gustan los compañeros.', '', 28153),
(152130, 'esMX', 'Cuando dijiste que eras Aterravil, pensé que te referías a que aterrabas la vileza, ¡no que te aterraba ti!', '', 28153),
(152129, 'esMX', '¡Hora de hacerlos volar!', '', 28153),
(152128, 'esMX', '\"Vamos a la jungla\", me dijiste. \"A ver el paisaje\", me dijiste. Sabía que tu punto ciego nos metería en problemas.', '', 28153),
(152127, 'esMX', 'Si morimos, será tu culpa.', '', 28153),
(152126, 'esMX', 'Dijeron que andarías por aquí.$b$bGracias a un... desliz... de Maius, no mío, tuvimos que viajar a este infierno húmedo repleto de monstruos con hambre de huesos para encontrar a este demonio nefasto.$b$bAyúdanos y te daremos cualquier objeto de valor que haya quedado junto a su cadáver.$b$bSolo queremos un papel que tiene. Nada que valga la pena leer.', '', 28153),
(152125, 'esMX', '¡Cra! ¡Todo tuyo!', '', 28153),
(152124, 'esMX', '¿Picodulce buscar pescado?', '', 28153),
(152123, 'esMX', '¡Deja de golpear! ¡A mi humana!', '', 28153),
(152122, 'esMX', 'Ustedes nunca aprenden.', '', 28153),
(152121, 'esMX', 'Quizás si no los hubieses regañado tantas veces. ¡Cra!', '', 28153),
(152120, 'esMX', 'Ese botín... siempre será mío...', 'Ese botín... siempre será mío...', 28153),
(152119, 'esMX', '', 'Bueno, auch, esa sí me dolió.', 28153),
(152118, 'esMX', '', 'Ven aquí, Picodulce, ¡basta de holgazanear!', 28153),
(152117, 'esMX', '', 'Apártate, pajarraco, ¡no necesito tu ayuda!', 28153),
(152116, 'esMX', '', 'Ni siquiera me dolió. ¿Eso es todo lo que tienes, cebo de tiburón?', 28153),
(152115, 'esMX', '¡JA! ¡Estaba buscando la oportunidad de desahogarme un poco!', '¡JA! ¡Estaba buscando la oportunidad de desahogarme un poco!', 28153),
(152114, 'esMX', '', 'Estaba más que satisfecha... hasta que dejaron de seguir mis órdenes...', 28153),
(152113, 'esMX', '', '¿Cómo que \"los tuyos\"?', 28153),
(152112, 'esMX', '', '¿Y por qué no abandonan mi nave? ¡Reconstruiré el Gran Cuerno y arponearé hasta el último canalla del bauprés!', 28153),
(152111, 'esMX', '', '¡Pedazo de basura bueno para nada!', 28153),
(152110, 'esMX', 'Ella... gobernará... por siempre...', 'Ella... gobernará... por siempre...', 28153),
(152109, 'esMX', 'Derrotado... por seres como tú...', 'Derrotada... por seres como tú...', 28153),
(152108, 'esMX', 'La Horda... siempre será... de ella...', 'La Horda... siempre será... de ella...', 28153),
(152107, 'esMX', 'Otra vez... no...', '¡Ah! Otra vez... no...', 28153),
(152106, 'esMX', '¡La única opción es la muerte!', '¡La única opción es la muerte!', 28153),
(152105, 'esMX', '¿Oyes los gritos?', '¡Ja, ja, ja, ja! ¿Oyes los gritos?', 28153),
(152104, 'esMX', '¡Ni un sobreviviente!', '¡Ni un sobreviviente!', 28153),
(152103, 'esMX', '¡Por la Dama Oscura!', '¡Por la Dama Oscura!', 28153),
(152102, 'esMX', '¡Lok-tar ogar!', '¡Lok-tar ogar!', 28153),
(152101, 'esMX', '¡Lok-narash!', '¡Lok-narash!', 28153),
(152100, 'esMX', '¡Gakarah ma!', '¡Gakarah ma!', 28153),
(152099, 'esMX', '¡Victoria o muerte!', '¡Victoria o muerte!', 28153),
(152098, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(152097, 'esMX', '¡Muerte a nuestros enemigos!', '¡Muerte a nuestros enemigos!', 28153),
(152096, 'esMX', '¡No sobrevivirás a este día!', '¡No sobrevivirás a este día!', 28153),
(152095, 'esMX', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(152094, 'esMX', 'Ancestros... Aquí voy...', 'Ancestros... Aquí voy...', 28153),
(152093, 'esMX', 'Perderás... esta guerra...', 'Perderás... esta guerra...', 28153),
(152092, 'esMX', 'Tu final... llegará...', 'Tu final... llegará...', 28153),
(152091, 'esMX', 'Muero... como un guerrero...', 'Muero... como una guerrera...', 28153),
(152090, 'esMX', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(152089, 'esMX', 'Mi vida... por Draenor...', 'Mi vida... por Draenor...', 28153),
(152088, 'esMX', 'Márchate ahora.', 'Márchate ahora.', 28153),
(152087, 'esMX', 'Vete. Ahora.', 'Vete. Ahora.', 28153),
(152086, 'esMX', 'No le falles a la Horda.', 'No le falles a la Horda.', 28153),
(152085, 'esMX', 'Que mueras bien.', 'Que mueras bien.', 28153),
(152084, 'esMX', 'No tengo nada más que decir.', 'No tengo nada más que decir.', 28153),
(152083, 'esMX', 'Lárgate.', 'Lárgate.', 28153),
(152082, 'esMX', 'Ve con honor.', 'Ve con honor.', 28153),
(152081, 'esMX', 'Que tus armas nunca pierdan filo.', 'Que tus armas nunca pierdan filo.', 28153),
(152080, 'esMX', 'Adelante. Quédate con la victoria.', 'Adelante. Quédate con la victoria.', 28153),
(152079, 'esMX', 'No olvides tu deber.', 'No olvides tu deber.', 28153),
(152078, 'esMX', 'Di qué te trae por aquí.', 'Di qué te trae por aquí.', 28153),
(152077, 'esMX', 'No tengo tiempo para tonterías.', 'No tengo tiempo para tonterías.', 28153),
(152076, 'esMX', '¿Y bien? Estoy esperando...', '¿Y bien? Estoy esperando...', 28153),
(152075, 'esMX', 'Habla.', 'Habla.', 28153),
(152074, 'esMX', 'Un gusto.', 'Un gusto.', 28153),
