(152070, 'esMX', 'Zug-zug.', 'Zug-zug.', 28153),
(152069, 'esMX', 'Fuerza y honor.', 'Fuerza y honor.', 28153),
(152068, 'esMX', '¿Todos los de Azeroth son así de fastidiosos?', '¿Todos los de Azeroth son así de fastidiosos?', 28153),
(152067, 'esMX', 'Mi pasatiempo es matar todo lo que me molesta. ¿Realmente quieres seguir con esto?', 'Mi pasatiempo es matar todo lo que me molesta. ¿Realmente quieres seguir con esto?', 28153),
(152066, 'esMX', 'Oye, me estás haciendo enfadar. No te recomiendo verme enfadado.', 'Oye, me estás haciendo enfadar. No te recomiendo verme enfadada.', 28153),
(152065, 'esMX', 'ORCO... ¡¡¡¡APLASTA!!!!!', 'ORCO... ¡¡¡¡APLASTA!!!!!', 28153),
(152064, 'esMX', 'Aún deben estar ocupados con los esbirros del aquelarre fuera del muro.', '', 28153),
(152063, 'esMX', '', '¿Pero dónde están los demás inquisidores?', 28153),
(152062, 'esMX', '¡Lok-tar ogar!', '¡Lok-tar ogar!', 28153),
(152061, 'esMX', '¡Cae ante mi furia!', '¡Cae ante mi furia!', 28153),
(152060, 'esMX', '¡Tu suerte está echada!', '¡Tu suerte está echada!', 28153),
(152059, 'esMX', '¡Cae ante la Horda!', '¡Cae ante la Horda!', 28153),
(152058, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
