(152056, 'esMX', '¡No sobrevivirás a este día!', '¡No sobrevivirás a este día!', 28153),
(152055, 'esMX', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(152054, 'esMX', 'Ancestros... Aquí voy...', 'Ancestros... Aquí voy...', 28153),
(152053, 'esMX', 'Perderás... esta guerra...', 'Perderás... esta guerra...', 28153),
(152052, 'esMX', 'Tu final... llegará...', 'Tu final... llegará...', 28153),
(152051, 'esMX', 'Espíritus... llévenme...', 'Espíritus... llévenme...', 28153),
(152050, 'esMX', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(152049, 'esMX', 'Mi espíritu regresa... a Draenor...', 'Mi espíritu regresa... a Draenor...', 28153),
(152048, 'esMX', 'Regresa con más oro.', 'Regresa con más oro.', 28153),
(152047, 'esMX', 'Que estos bienes te resulten útiles.', 'Que estos bienes te resulten útiles.', 28153),
(152046, 'esMX', 'Regresa.', 'Regresa.', 28153),
