INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'esMX', '¡La pestilencia se esparce!', '', 28153),
(152009, 'esMX', '¡Gestación violenta!', '', 28153),
(152008, 'esMX', '¡Consumir huéspedes!', '', 28153),
(152007, 'esMX', '¡Se acabó! Ahora verán, malditos de la Horda.', '', 28153),
(152006, 'esMX', 'Cepa fatal. Contagio exitoso.', '', 28153),
(152005, 'esMX', 'He perdido mi disfraz. ¿Tienes otro pergamino?', 'He perdido mi disfraz. ¿Tienes otro pergamino?', 28153),
(152004, 'esMX', '¡Tragón de la jungla salta al agua!', '', 28153),
(152003, 'esMX', '¡Peste!', '', 28153),
(152002, 'esMX', '¡Infecciones por doquier!', '', 28153),
(152001, 'esMX', 'La epidemia es inevitable...', '', 28153),
(152000, 'esMX', '', 'Qué bueno. BAH. No tiene nada de bueno.', 28153),
(151999, 'esMX', '', '¿Ya encontraste a Sr. Sonrisa, el genio ruin?', 28153),
(151998, 'esMX', 'Mmm. ¡Huéspedes frescos!', '', 28153),
(151990, 'esMX', 'Ahora... es hora de llevarse un trofeo.', '', 28153),
(151989, 'esMX', '¡Tenemos la perla! Con ella, nuestros navíos se convertirán en depredadores marítimos.', '', 28153),
(151987, 'esMX', '', 'Disfruten esta victoria. Será la última.', 28153),
(151986, 'esMX', 'Es la ley de la naturaleza. Los fuertes dominan a los débiles.', '', 28153),
(151985, 'esMX', 'Mantengan los sentidos alerta. Una fuerza invisible nos acecha.', '', 28153),
(151983, 'esMX', 'La Alianza no debe quedarse con este premio. ¡Los que se opongan, caerán!', '', 28153),
(151982, 'esMX', '', 'Me ayudaste a recuperar mi negocio, así que sí. Con Cesi como jefa volveríamos a hacer dinero como antes.', 28153),
(151981, 'esMX', '¿Apoyarás a Cesi Cañonfácil?', '¿Apoyarás a Cesi Cañonfácil?', 28153),
(151980, 'esMX', '', 'Este lugar solía dar mucha más ganancia.', 28153),
(151979, 'esMX', '', 'Vámonos de aquí antes de quedar atrapados. ¡Vamos!', 28153),
(151978, 'esMX', 'La Casa Canto Tormenta gobernará este reino anegado. La Cólera de la Madre de las mareas se encargará de ello.', '', 28153),
(151977, 'esMX', 'La flota... será de ella...', '', 28153),
(151976, 'esMX', 'Solo estaba jugando con ellos, mi lord. ¡Se hará su voluntad!', '', 28153),
(151975, 'esMX', 'Nuestro destino está cerca. No deben entrar al Santuario de la Tormenta.', '', 28153),
(151974, 'esMX', '', 'Mira en qué te has convertido. ¡Todo este derramamiento de sangre es tu culpa!', 28153),
(151973, 'esMX', 'El pergamino flota y resuena, muestra visiones de otros lugares oscurecidas con magia.', '', 28153),
(151972, 'esMX', 'Supervivencia de alma del mundo: improbable...', '', 28153),
(151971, 'esMX', 'Infección planetaria inminente.', '', 28153),
(151970, 'esMX', 'Deberíamos dejar que los Mareaférrea se queden con el tesoro.', 'Deberíamos dejar que los Mareaférrea se queden con el tesoro.', 28153),
(151969, 'esMX', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t¡%s crea un |cFFFF0000|Hspell:267891|h[Resguardo de presteza]|h|r!', 28153),
(151968, 'esMX', '<Clávale el puñal>', '<Clávale el puñal>', 28153),
(151967, 'esMX', '¿... hablas en serio?', '¿... hablas en serio?', 28153),
(151966, 'esMX', '¡Eso es ridículo! ¡No voy a pagar eso!', '¡Eso es ridículo! ¡No voy a pagar eso!', 28153),
(151965, 'esMX', 'Un lugar en el piso para pasar la noche cuesta cincuenta de oro. Sesenta si quieres estar junto al fuego. Tienes que traer mantas. \n\nVincular tu piedra de hogar cuesta setenta y cinco de oro por semana.\n\n¿No te gusta? \n\n<Suelta una risa y se cruza de brazos con una sonrisa burlona.>\n\nQué pena. Esas son las tarifas actuales.', '', 28153),
(151964, 'esMX', 'Las profundidades anunciaron su llegada... ¡y la muerte de ustedes dos!', '', 28153),
(151963, 'esMX', 'Infiltración masiva detectada.', '', 28153),
(151962, 'esMX', '', 'Debemo\' reunir nuestras fuerzas y cortar la infección de raíz.', 28153),
(151961, 'esMX', '', 'El titán nos ganó algo de tiempo, pero G\'huun no permanecerá encerrado.', 28153),
(151960, 'esMX', 'Espécimen virulento detectado. Primera prioridad: contención.', '', 28153),
(151959, 'esMX', '¡Devorar! ¡Consumir! ¡Propagar!', '', 28153),
(151958, 'esMX', '', '¿Esta cosa está buscando a su madre? Eh\'peremos que nos lleve a algo que pueda detener la propagación de esta peste.', 28153),
(151957, 'esMX', 'Contención de G\'huun defectuosa. M.A.D.R.E. no responde.', '', 28153),
(151954, 'esMX', '', 'Si se propaga a la superficie, no podremo\' contenerla.', 28153),
(151953, 'esMX', '', 'Nunca había visto una corrupción como eh\'ta.', 28153),
(151952, 'esMX', '', '¡No podemo\' permitir que llegue a la superficie! ¡Deh\'trúyanla!', 28153),
(151951, 'esMX', '', '¡Aj! ¡¿Qué clase de criatura es eh\'ta?!', 28153),
(151950, 'esMX', '', 'Tengan cuidado. Quién sabe lo que acecha en eh\'tas cuevas.', 28153),
(151949, 'esMX', '', 'Los trols de sangre están dispersos, pero debemo\' encontrar la fuente de la infección y destruirla.', 28153),
(151948, 'esMX', '¡Tenemos una ofrenda para ti, gran loa de la muerte!', '', 28153),
(151947, 'esMX', 'Si esto traerá caras nuevas aquí, sí, lo haré.', '', 28153),
(151946, 'esMX', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t¡$s comienza a lanzar |cFFFF0404|Hspell:260773|h[Ritual temible]|h|r!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t¡$s comienza a lanzar |cFFFF0404|Hspell:260773|h[Ritual temible]|h|r!', 28153),
(151945, 'esMX', '¿Apoyarás a Cesi Cañonfácil?', '¿Apoyarás a Cesi Cañonfácil?', 28153),
(151944, 'esMX', '¿Compras o vendes?', '', 28153),
(151943, 'esMX', '', 'Esto no se ve bien...', 28153),
(151942, 'esMX', 'Con gusto. ¡Sufrirán en tu nombre!', '', 28153),
(151941, 'esMX', 'Contagio detectado. Esterilizar.', '', 28153),
(151940, 'esMX', '¡Explosión pestilente!', '', 28153),
(151939, 'esMX', 'Activando medida preventiva definitiva. Destruir fuente virulenta.', '', 28153),
(151938, 'esMX', 'A la orden, mi lord. Solo debo lidiar con unos insectos antes.', 'A la orden, mi lord. Solo debo lidiar con unos insectos antes.', 28153),
(151937, 'esMX', 'Purificando área.', '', 28153),
(151936, 'esMX', 'Protocolos de purga activados.', '', 28153),
(151935, 'esMX', '¡Ruptura ruin!', '', 28153),
(151934, 'esMX', 'Solo unos hueso\' rotos... nada importante.', '', 28153),
(151933, 'esMX', 'Guíanos al campamento vulpera, $p. Llevaremo\' el tesoro.', '', 28153),
(151932, 'esMX', '¡Expulsión de sangre!', '', 28153),
(151931, 'esMX', '', '¡Baja tus armas! ¡No tienes que hacer esto!', 28153),
(151930, 'esMX', 'Debo... propagar...', '', 28153),
(151929, 'esMX', '¡Muerte por añublo!', '', 28153),
(151928, 'esMX', '¡Infectado!', '', 28153),
(151927, 'esMX', 'Carne corrupta.', '', 28153),
(151926, 'esMX', '¡Consumir!', '', 28153),
(151925, 'esMX', '¡Debo propagar!', '', 28153),
(151924, 'esMX', 'No olvides cumplir con tu parte del trato...', '', 28153),
(151923, 'esMX', '¡Jajajaja! ¿Ya lo ve, su majestad? ¡Bwonsamdi siempre cumple con sus trato\'!', '', 28153),
(151922, 'esMX', 'Levántense... ¡Levántense! ¡No sean perezoso\'! ¡Tomen sus lanzas nuevamente y LUCHEN!', '', 28153),
(151921, 'esMX', 'Tranquilo, majestad. Bwonsamdi siempre ayuda a sus amigo\'...', '', 28153),
(151920, 'esMX', '', 'No te quede\' ahí viendo cómo trabajo. Los dos tenemo\' cosas que hacer.', 28153),
(151919, 'esMX', 'El barco partirá cuando estemo\' listos.', '', 28153),
(151918, 'esMX', 'Estos traidore\' son lo único que se interpone entre mi reino y yo, ¿y dónde está la ayuda que prometiste? ¿Planeas mantener tu palabra?', '', 28153),
(151916, 'esMX', 'Lo hiciste bien, adalid. Puedo sentir cómo Azeroth recupera su fuerza gracias a ti.', '', 28153),
(151915, 'esMX', 'Hay varias heridas de azerita abiertas en las cercanías. ¡Usa el Corazón de Azeroth para curarlas!', '', 28153),
(151913, 'esMX', '¡Huye mientras puedas!', '', 28153),
(151912, 'esMX', '¡Tch, tch! ¿Así le habla a su loa, su majeh\'tad? ¡Supongo que las almas que recolectaré hoy compensarán su conducta!', '', 28153),
(151911, 'esMX', 'Eh\'tamos juntos en eh\'to, $p.\n\nMotín o muerte.', '', 28153),
(151910, 'esMX', '¡Bwonsamdi, muéstrate!', '', 28153),
(151909, 'esMX', 'Son demasiados los que se aliaron con Zul. Solo hay una manera de hacer eh\'to...', '', 28153),
(151908, 'esMX', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t¡%s se fija en |cFFFF0000$n|r y se prepara para lanzar |cFFFF0000|Hspell:266951|h[Barrilazo]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t¡%s se fija en |cFFFF0000$n|r y se prepara para lanzar |cFFFF0000|Hspell:266951|h[Barrilazo]|h|r!', 28153),
(151907, 'esMX', 'Un grupo de zandalari ha desactivado los resguardos ancestrales que defienden el corazón de Sethraliss...', 'Un grupo de zandalari ha desactivado los resguardos ancestrales que defienden el corazón de Sethraliss...', 28153),
(151906, 'esMX', 'Sí, Cesi puede contar con mi apoyo.', '', 28153),
(151905, 'esMX', '¡A trabajar, goblins perezosos! ¡Quiero esa base de bolsillo lista en este instante!', '¡A trabajar, goblins perezosos! ¡Quiero esa base de bolsillo lista en este instante!', 28153),
(151904, 'esMX', '¿Apoyarás a Cesi Cañonfácil?', '¿Apoyarás a Cesi Cañonfácil?', 28153),
(151902, 'esMX', 'Mmmmmm. Sí. Déjame ver.\n\n<Kooda revuelve un momento y luego saca un frasco del fondo de su mochila.>\n\nLa compré hace un par de siglos. La había olvidado. Supongo que podría venderla.', '', 28153),
(151901, 'esMX', '¿Alguna vez has oído hablar de la \"Salsa centenaria\"? ¿Tienes un poco?', '¿Alguna vez has oído hablar de la \"Salsa centenaria\"? ¿Tienes un poco?', 28153),
(151900, 'esMX', 'Hola, $r. ¿Tienes algo interesante para vender?', '', 28153),
(151899, 'esMX', 'Por la marea, ¡se acerca!', 'Por la marea, ¡se acerca!', 28153),
(151898, 'esMX', 'Hambre insaciable. El rey se da un festín.', '', 28153),
(151897, 'esMX', 'La herida se infecta. El mundo se pudre.', '', 28153),
(151896, 'esMX', 'Siempre hemos habitado tu mente.', '', 28153),
(151895, 'esMX', 'Los gritos desgarradores anunciarán su llegada.', '', 28153),
(151894, 'esMX', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t¡Zanazal el Sabio empieza a lanzar |cFFFF0000|Hspell:267273|h[Nova de veneno]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t¡Zanazal el Sabio empieza a lanzar |cFFFF0000|Hspell:267273|h[Nova de veneno]|h|r!', 28153),
(151893, 'esMX', '', '¡Los reptantes se han despertado!', 28153),
(151892, 'esMX', '', '¡Kril lax qutholil!', 28153),
(151890, 'esMX', 'Te has enfrentado a los nagas como mi avatar y has acabado con su ataque a mi templo.', '', 28153),
(151889, 'esMX', '', '¡Ay! ¡Siempre quise usar la Salsa centenaria! Es una pasta para sazonar hecha con varios ingredientes que se mezclan y luego se dejan fermentar durante siglos. Cuanto más tiempo se fermenta, más complejo se vuelve el perfil de su sabor. Parece que agrega un toque especiado muy característico a cualquier plato.\n\nSe dice que algunos comerciantes tortollanos la venden, pero es muy difícil de encontrar y ridículamente cara.\n\n<Xun Xun suspira anhelosamente>\n\n¡Es el ingrediente soñado de cualquier chef!', 28153),
(151888, 'esMX', 'Tienes una despensa muy bien provista. ¿Te falta algo en el especiero?', 'Tienes una despensa muy bien provista. ¿Te falta algo en el especiero?', 28153),
(151887, 'esMX', '', '¡Una cara nueva! Y parece amigable. ¿Te gustaría probar algo especial? ¿O tal vez buscas especias y recetas poco comunes?', 28153),
(151886, 'esMX', 'El Corazón de Azeroth es más fuerte gracias a ti. Estás un paso más cerca de curar las heridas de Azeroth.', '', 28153),
(151885, 'esMX', 'Puedo sentir la azerita cerca... y a los que intentan explotarla para beneficiarse. ¡Tienes que detenerlos!', '', 28153),
(151884, 'esMX', 'Ven, pequeño retoño. Calma tu corazón y ayúdame a curar a este hombre.', '', 28153),
(151883, 'esMX', '', 'La sangre fluye en las profundidades.', 28153),
(151882, 'esMX', '', 'Tu verdad te aguarda bajo las mareas.', 28153),
(151881, 'esMX', '', 'Escucha el canto de los ahogados.', 28153),
(151880, 'esMX', '', 'La oscuridad se arraiga. La pestilencia se propaga. El portal está abierto.', 28153),
(151879, 'esMX', '', '¡Tus gritos no se oirán en las profundidades!', 28153),
(151878, 'esMX', '', '¡Estoy dentro de tus pulmones!', 28153),
(151877, 'esMX', '', 'Te esperaré... en la oscuridad...', 28153),
(151876, 'esMX', '', '¡Me perteneces!', 28153),
(151875, 'esMX', '', 'Tus aliados disfrutaron al verte morir.', 28153),
(151874, 'esMX', '', 'Estamos vinculados eternamente con la inmensidad de las profundidades.', 28153),
(151873, 'esMX', 'No hay ni un solo atributo digno en ti.', '', 28153),
(151872, 'esMX', '¡Tan frágil! ¡Tan $Uindigno:indigna;!', '', 28153),
(151871, 'esMX', '¡Eras $Uel:la; más débil!', '', 28153),
(151870, 'esMX', '¿Cómo es... posible...?', '', 28153),
(151869, 'esMX', 'Ul basha krix.', '', 28153),
(151868, 'esMX', '', '¡Iluminen los cielos! Derríbenlos.', 28153),
(151867, 'esMX', 'Las criaturas inferiores servirán... ¡o morirán!', '', 28153),
(151866, 'esMX', '', '¡Por la Horda!', 28153),
(151865, 'esMX', '', '¡No tengan piedad!', 28153),
(151864, 'esMX', '¡Ug\' crish zul Thraxas!', '', 28153),
(151863, 'esMX', '', '¡No dejen de disparar! Nuestras fuerzas terrestres dependen de ustedes.', 28153),
(151862, 'esMX', '', '¡Sigan disparando!', 28153),
(151861, 'esMX', '¡Morirán en eh\'ta tumba!', '', 28153),
(151860, 'esMX', '¡No pueden resistir contra lo\' zandalari!', '', 28153),
(151859, 'esMX', '¡El poder de G\'huun controla eh\'te templo!', '', 28153),
(151858, 'esMX', '¡Los zandalari gobernarán!', '', 28153),
(151857, 'esMX', '', '¡Por aquí! ¡Nos espera una batalla gloriosa!', 28153),
(151856, 'esMX', '¡No pueden detener a G\'huun!', '', 28153),
(151855, 'esMX', '¡Sangren para el dios de la sangre!', '', 28153),
(151854, 'esMX', 'Intentaré averiguar algo por mi cuenta. Si sé algo, serán los primeros en enterarse.', '', 28153),
(151853, 'esMX', '¡Ya los oyeron! Será mejor que averigüemos de dónde viene la corrupción de los dioses antiguos... ¡para aplastarla con un martillo!', '', 28153),
(151852, 'esMX', '¡Ja! ¿Esa fue tu mejor jugada, Zul? ¡No me sorprende que el imperio trol cayera!', '', 28153),
(151850, 'esMX', 'Podría haber llenado uno de estos sarcófagos con tu cadáver putrefacto.', '', 28153),
(151849, 'esMX', 'Gloria y honor, ¡peleo por la Estela de la Tormenta!', 'Gloria y honor, ¡peleo por la Estela de la Tormenta!', 28153),
(151848, 'esMX', 'Mi espada está a tu servicio.', 'Mi espada está a tu servicio.', 28153),
(151847, 'esMX', '¡Aún no he muerto!', '¡Aún no he muerto!', 28153),
(151846, 'esMX', '¡Detendremos a estos demonios juntos!', '¡Detendremos a estos demonios juntos!', 28153),
(151845, 'esMX', '¡Mientras yo siga en pie, este valle será libre!', '¡Mientras yo siga en pie, este valle será libre!', 28153),
(151844, 'esMX', 'Si la Estela de la Tormenta llama, debo responder.', 'Si la Estela de la Tormenta llama, debo responder.', 28153),
(151843, 'esMX', 'Vivas o mueras, llegó nuestra hora.', 'Vivas o mueras, llegó nuestra hora.', 28153),
(151842, 'esMX', '¡Estoy contigo!', '¡Estoy contigo!', 28153),
(151841, 'esMX', 'Es una pena que no estés aquí para ver cómo se destruye tu ensamblaje, Zul.', '', 28153),
(151840, 'esMX', '¡Bah! ¡Ya veremos, trol cobarde!', '', 28153),
(151839, 'esMX', 'Pronto se alzarán, ¡y todo\' los que se oponen a G\'huun caerán!', '', 28153),
(151838, 'esMX', '¡Tal vez aún podamos vencer! ¡Por la Estela de la Tormenta!', '¡Tal vez aún podamos vencer! ¡Por la Estela de la Tormenta!', 28153),
(151837, 'esMX', '¡Necios! Mi poder ya ha vinculado a los eh\'píritus ancestrale\' a la voluntad de mi maestro.', '', 28153),
(151836, 'esMX', 'Oigo la canción de la tormenta. ¡Aún hay esperanza!', 'Oigo la canción de la tormenta. ¡Aún hay esperanza!', 28153),
(151835, 'esMX', 'Hay otros. ¡No todos estamos perdidos!', 'Hay otros. ¡No todos estamos perdidos!', 28153),
(151834, 'esMX', 'No sé qué clase de magia oscura se ha asentado aquí, pero será mejor que encontremos una forma de disiparla.', '', 28153),
(151833, 'esMX', 'Nosotros no somos así. ¡Aún podemos detener a Lord Canto Tormenta!', 'Nosotros no somos así. ¡Aún podemos detener a Lord Canto Tormenta!', 28153),
(151832, 'esMX', 'Según mi investigación, aquí descansa el primer rey de Zandalar.', '', 28153),
(151831, 'esMX', 'La puerta cayó. ¡Muévanse! ¡Recuperen Arathi en nombre de la Alianza!', '', 28153),
(151830, 'esMX', '¿Pike sigue vivo? Lo buscaré de inmediato.', '¿Pike sigue vivo? Lo buscaré de inmediato.', 28153),
(151829, 'esMX', 'La puerta ha caído. ¡Vamos, recuperen Arathi de las manos de la Horda!', '', 28153),
(151828, 'esMX', '¡La puerta cayó! ¡Vamos, avancen!', '', 28153),
(151827, 'esMX', '', '¡Las puertas han caído! ¡Ataquen!', 28153),
(151826, 'esMX', '¡La puerta ha caído! ¡Ataquen la fortaleza!', '', 28153),
(151825, 'esMX', 'Por el bien de Zandalar... y también por el de su\' reinos... deben detenerlo.', '', 28153),
(151824, 'esMX', '¡Las puertas han caído! ¡Ahora, capturen la fortaleza!', '', 28153),
(151823, 'esMX', '¡Debemos abrir el Santuario de la Tormenta de inmediato!', '¡Debemos abrir el Santuario de la Tormenta de inmediato!', 28153),
(151822, 'esMX', 'Ahora mismo su maeh\'tro acumula poder. Zul no descansará hasta que todo el mundo caiga bajo el dio\' de la sangre.', '', 28153),
(151821, 'esMX', 'Lo logramos. Arathi nos pertenece otra vez. ¡Por la Alianza!', '', 28153),
(151820, 'esMX', 'La tormenta en mí despierta. ¡Me enfrentaré a la sombra!', 'La tormenta en mí despierta. ¡Me enfrentaré a la sombra!', 28153),
(151819, 'esMX', '', 'Nuestra victoria jamás estuvo en duda. ¡Por la Horda!', 28153),
(151818, 'esMX', 'Me han liberado de un deh\'tino cruel, pero Zul es apenas una marioneta en un plan más perverso.', '', 28153),
(151817, 'esMX', '¡Arrástrate hah\'ta tu maestro y descubre cómo recompensa el fracaso!', '', 28153),
(151816, 'esMX', 'Sabía que este día llegaría. Me uniré a los demás.', 'Sabía que este día llegaría. Me uniré a los demás.', 28153),
(151815, 'esMX', '¡Imposible! ¡No desafiarán a G\'huun!', '', 28153),
(151814, 'esMX', '¡Han quebrado la influencia de Zul! ¡Ya no estoy al servicio de ese cerdo!', '', 28153),
(151813, 'esMX', 'Quéjate todo lo que quiera\', mi rey... pero deberías haberte percatado de que nadie eh\'capa de G\'huun.', '', 28153),
(151812, 'esMX', 'Estos intruso\' morirán... Pero no tengo que escuchar tu parloteo mientras me encargo de eso.', '', 28153),
(151811, 'esMX', 'Me pasé la vida resistiéndome a tu maestro y tú me sometes a su volunta\' en la muerte.', '', 28153),
(151810, 'esMX', '¡Silencio, profeta de la mentira!', '', 28153),
(151809, 'esMX', 'Aquí deh\'cansa el primer rey de Zandalar. Dazar fue obstinado... ¡pero ahora me sirve!', '', 28153),
(151808, 'esMX', '¿Has enloquecido?', '¿Has enloquecido?', 28153),
(151807, 'esMX', 'Habla de una vez.', 'Habla de una vez.', 28153),
(151806, 'esMX', 'Pero la muerte los unió con un propósito en común. Asesinarlos a ustede\'.', '', 28153),
(151805, 'esMX', 'La tierra me lleva.', 'La tierra me lleva.', 28153),
(151804, 'esMX', 'En la vida, se odiaban. Y terminaron por deh\'truirse uno a otro.', '', 28153),
(151803, 'esMX', 'Los eh\'peran tres gobernante\' que controlaban el imperio en una época en la que el trono no podía ser de un solo trol.', '', 28153),
(151802, 'esMX', 'Los forasteros no son bienvenidos aquí.', 'Los forasteros no son bienvenidos aquí.', 28153),
(151801, 'esMX', '¡El mar huye, y la tierra se alza!', '¡El mar huye y se alza la tierra!', 28153),
(151800, 'esMX', 'Estoy seguro de que no tendrá problemas para deshacerse de ustede\'.', '', 28153),
(151799, 'esMX', 'Mientras los muerto\' atascaban sus templo\', se construyeron gólems para que se deshicieran de los cuerpos infectado\'.', '', 28153),
(151798, 'esMX', 'Hace mile\' de años, una infección de sangre casi acaba con los zandalari.', '', 28153),
(151797, 'esMX', 'Pronto se alzarán, ¡y todos los que se oponen a G\'huun caerán!', '', 28153),
(151796, 'esMX', 'Mi poder ya se ha asentado y ha vinculado a los eh\'píritus ancestrales a la voluntad de mi maestro.', '', 28153),
(151795, 'esMX', 'Bienvenidos a la tumba del primer rey trol. Ojalá pudiera eh\'tar ahí para saludarlos personalmente.', '', 28153),
(151794, 'esMX', '¡Ya te lo dije, no seré parte de esta locura!', '¡Ya te lo dije, no seré parte de esta locura!', 28153),
(151793, 'esMX', 'No me dejaré engañar otra vez.', 'No me dejaré engañar otra vez.', 28153),
(151792, 'esMX', '¿Esto es... seguro?', '¿Esto es... seguro?', 28153),
(151791, 'esMX', 'Somos emprendedores y especialistas en reubicación. No como estos malditos mercenarios rojos. No somos piratas.', '', 28153),
(151790, 'esMX', '', 'Adalid, volvamos con Katherine.', 28153),
(151789, 'esMX', '', 'Ustedes tres, ¡consigan un grupo de búsqueda y encuéntrenla!', 28153),
(151788, 'esMX', '', 'Espera, ¡no!', 28153),
(151787, 'esMX', '', 'Basura INSOLENTE. ¡Esto recién empieza!', 28153),
(151786, 'esMX', '', 'Se acabó. Ya no tienes adónde huir.', 28153),
(151785, 'esMX', '', '¡Fuera de mi camino, cerebros de cebo!', 28153),
(151784, 'esMX', '', '¡Toma esto!', 28153),
(151783, 'esMX', '', '¡Tu estúpida maniobra no significó nada! ¡Esta ciudad es MÍA!', 28153),
(151782, 'esMX', '¡Esperaré aquí por si alguna encuentra el camino de regreso!', '', 28153),
(151781, 'esMX', '', 'Todo será muchísimo mejor cuando yo sea la jefa.\n\nCuando estos piratas mareaférrea se vayan, todos podrán venir a comerciar aquí. ¡Será maravilloso!', 28153),
(151780, 'esMX', '', '¡Aj! Las cosas eran mejores antes de que aparecieran esos idiotas de rojo.', 28153),
(151779, 'esMX', 'Mira, solo trato de ganarme la vida.', '', 28153),
(151778, 'esMX', 'Velajada y los suyos no son buenos para los negocios. Si las cosas empeoran, tal vez tome mis aves y me largue de aquí.', '', 28153),
(151777, 'esMX', 'Yo iba a ser rico...', '', 28153),
(151776, 'esMX', '¿Intentas meterte en nuestro camino? ¡He matado por menos!', '', 28153),
(151775, 'esMX', '', '¡No te apoderarás de esta arboleda!', 28153),
(151774, 'esMX', '', 'Gracias. Pensé que podía enfrentarlos sin ayuda. Ahora regresaré con Morwin.', 28153),
(151773, 'esMX', 'A mí gustar lo que hiciste con el lugar.', '', 28153),
(151772, 'esMX', 'Los tortollanos hemos comerciado en este lugar por mucho tiempo. Luego, los zandalari se asentaron a nuestro alrededor, pero ahora enfrentan tiempos adversos. Nosotros perduraremos, por supuesto.', '', 28153),
(151771, 'esMX', 'Yo trabajar aquí. No hay por qué ir a camino peligroso.', '', 28153),
(151770, 'esMX', '¡Lok-tar ogar!', '¡Lok-tar ogar!', 28153),
(151769, 'esMX', '¡Lok-narash!', '¡Lok-narash!', 28153),
(151768, 'esMX', '¡Gakarah ma!', '¡Gakarah ma!', 28153),
(151767, 'esMX', '¡Cae ante la Horda!', '¡Cae ante la Horda!', 28153),
(151766, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(151765, 'esMX', '¡Muerte a nuestros enemigos!', '¡Muerte a nuestros enemigos!', 28153),
(151764, 'esMX', '¡No sobrevivirás a este día!', '¡No sobrevivirás a este día!', 28153),
(151763, 'esMX', 'Una... muerte... honorable...', 'Una... muerte... honorable...', 28153),
(151762, 'esMX', '¡Ja! Veo que te presentas para el servicio. ¡Déjalo en el cofre y vuelve al trabajo!', '', 28153),
(151761, 'esMX', 'Ancestros... Aquí voy...', 'Ancestros... Aquí voy...', 28153),
(151760, 'esMX', 'Perderás... esta guerra...', 'Perderás... esta guerra...', 28153),
(151759, 'esMX', 'Tu final... llegará...', 'Tu final... llegará...', 28153),
(151758, 'esMX', 'Muero... como un guerrero...', 'Muero... como una guerrera...', 28153),
(151757, 'esMX', 'Mi batalla... termina...', 'Mi batalla... termina...', 28153),
(151756, 'esMX', 'Mi espíritu regresa... a Draenor...', 'Mi espíritu regresa... a Draenor...', 28153),
(151755, 'esMX', 'Que mueras bien.', 'Que mueras bien.', 28153),
(151754, 'esMX', 'No tengo nada más que decir.', 'No tengo nada más que decir.', 28153),
(151753, 'esMX', 'Lárgate.', 'Lárgate.', 28153),
(151752, 'esMX', 'Ve con honor.', 'Ve con honor.', 28153),
