(151733, 'esMX', 'Oye, me estás haciendo enfadar. No te recomiendo verme enfadado.', 'Oye, me estás haciendo enfadar. No te recomiendo verme enfadada.', 28153),
(151732, 'esMX', 'ORCO... ¡¡¡¡APLASTA!!!!!', 'ORCO... ¡¡¡¡APLASTA!!!!!', 28153),
