(151709, 'esMX', '¡Caerás ante mí!', '', 28153),
(151708, 'esMX', '¡Por las lunas de Draenor!', '', 28153),
(151707, 'esMX', 'Solo cumplí con mi deber.', '', 28153),
(151706, 'esMX', 'No vuelvas a pedirme eso.', '', 28153),
