(151659, 'esMX', '<Grito de temor: Total 3>', '', 28153),
(151658, 'esMX', '<Transmite la idea de invocar poder, de que aumenta el torrente de energía: Total 5-7>', '', 28153),
(151657, 'esMX', '<Lanza un hechizo, arroja energía: Total 3-5>', '', 28153),
