(151628, 'esMX', 'El hechizo se está recargando.', '', 28153),
(151627, 'esMX', 'Que tu pólvora nunca se moje.', 'Que tu pólvora nunca se moje.', 28153),
(151626, 'esMX', 'La lealtad ante todo.', 'La lealtad ante todo.', 28153),
(151625, 'esMX', 'No dejes que el lastre te golpee.', 'No dejes que el lastre te golpee.', 28153),
(151624, 'esMX', 'La marea no espera a nadie.', 'La marea no espera a nadie.', 28153),
(151623, 'esMX', 'Se acerca una tormenta. Las aguas no mienten.', 'Se acerca una tormenta. Las aguas no mienten.', 28153),
(151622, 'esMX', 'El aquelarre caerá.', 'El aquelarre caerá.', 28153),
(151621, 'esMX', 'La única bruja buena es una bruja muerta.', 'La única bruja buena es una bruja muerta.', 28153),
(151620, 'esMX', 'Gloria a la casa Tarjasenda.', 'Gloria a la casa Tarjasenda.', 28153),
(151619, 'esMX', 'Vientos fuertes y ancla firme.', 'Vientos fuertes y ancla firme.', 28153),
