(151617, 'esMX', 'Vientos favorables y mares calmos.', 'Vientos favorables y mares calmos.', 28153),
(151616, 'esMX', '¡Por Kul Tiras!', '¡Por Kul Tiras!', 28153),
(151615, 'esMX', 'No puedo quedarme con eso ahora.', '', 28153),
(151614, 'esMX', 'No tengo un objetivo.', '', 28153),
(151613, 'esMX', 'Primero necesito un objetivo.', '', 28153),
