(151610, 'esMX', 'Primero necesito permiso.', '', 28153),
(151609, 'esMX', 'No puedo atacar al objetivo.', '', 28153),
(151608, 'esMX', 'No puedo atacar eso.', '', 28153),
(151607, 'esMX', 'Mi inventario está lleno.', '', 28153),
(151606, 'esMX', 'No puedo llevar nada más.', '', 28153),
(151605, 'esMX', 'El objeto está bloqueado.', '', 28153),
(151604, 'esMX', 'No puedo cargar más de eso.', '', 28153),
(151603, 'esMX', 'Stromgarde aún está débil. No sobrevivirá a un ataque directo de un demoledor. ¡Destrúyelos antes de que se acerquen!', '', 28153),
(151602, 'esMX', 'Aún no puedo usar ese objeto.', '', 28153),
(151601, 'esMX', 'El objeto aún no está listo.', '', 28153),
(151600, 'esMX', 'Ese objeto aún se está recargando.', '', 28153),
(151599, 'esMX', 'Nuestras fortificaciones aún están débiles. ¡Rápido, destruye a esos demoledores antes de que se acerquen!', '', 28153),
(151598, 'esMX', 'Me falta furia.', '', 28153),
(151597, 'esMX', 'Tengo poca furia.', '', 28153),
(151596, 'esMX', 'No tengo suficiente dolor.', '', 28153),
(151595, 'esMX', 'Tengo poco dolor.', '', 28153),
(151594, 'esMX', 'Eso no es una bolsa.', '', 28153),
(151593, 'esMX', '¡Tenemos que detener a esos demoledores antes de que nos demuelan a nosotros!', '', 28153),
(151592, 'esMX', 'No tengo fondos suficientes.', '', 28153),
(151591, 'esMX', 'No puedo permitírmelo.', '', 28153),
(151590, 'esMX', '', '¡Desplieguen los demoledores, ahora! ¡No podemos permitir que la Alianza asegure una posición!', 28153),
(151589, 'esMX', 'Es demasiado caro.', '', 28153),
(151588, 'esMX', '¿Alguna vez viste la panza de un kraken? Sigue así y la verás.', '¿Alguna vez viste la panza de un kraken? Sigue así y la verás.', 28153),
(151587, 'esMX', '¡Envíen a lo\' demoledores! ¡Tenemo\' que aplastar a estos insectos de la Alianza antes de que nos aplasten a nosotro\'!', '', 28153),
(151586, 'esMX', 'Empiezo a pensar que no tienes los dos remos en el agua.', 'Empiezo a pensar que no tienes los dos remos en el agua.', 28153),
(151585, 'esMX', '¡Envíen los demoledores! ¡Las murallas de Stromgarde se derrumbarán ante el poder de la Horda!', '', 28153),
(151584, 'esMX', 'Ese olor a agua estancada eres tú, ¿verdad?', '¡Ugh! Ese olor a agua estancada eres tú, ¿verdad?', 28153),
(151583, 'esMX', '¡Máquinas de asedio! ¡Bórrenlas del mapa!', '', 28153),
(151582, 'esMX', 'Gusanos miserables, no tienen derecho a estar aquí.', '', 28153),
(151581, 'esMX', '', '¡Han enviado máquinas de asedio! Tenemos que destruirlas antes de que se acerquen a nuestra base.', 28153),
(151580, 'esMX', 'Necesito las dos manos para blandir mi arma.', '', 28153),
(151579, 'esMX', 'Esa habilidad no está lista.', '', 28153),
(151578, 'esMX', 'Aún no puedo hacer eso.', '', 28153),
(151577, 'esMX', 'Todavía no está lista.', '', 28153),
(151576, 'esMX', 'No puedo poner eso ahí.', '', 28153),
(151575, 'esMX', 'La bolsa está llena.', '', 28153),
(151574, 'esMX', 'No puedo hacer eso aquí.', '', 28153),
(151573, 'esMX', 'No puedo soltar eso.', '', 28153),
(151572, 'esMX', 'El objeto está ligado a mí.', '', 28153),
(151571, 'esMX', 'No puedo equipármelo.', '', 28153),
(151570, 'esMX', 'No tengo el nivel suficiente para usar eso.', '', 28153),
(151569, 'esMX', 'Aún no puedo usar eso.', '', 28153),
(151568, 'esMX', 'No tengo el nivel de habilidad suficiente para equipar eso.', '', 28153),
(151567, 'esMX', 'Nunca podré equipar eso.', '', 28153),
(151566, 'esMX', 'Primero lo primero. Necesitamos madera del Aserradero de Tierras Altas. También necesitamos hierro, que podemos obtener en el Filón de Galson.', '', 28153),
(151565, 'esMX', 'No puedo aprender ese hechizo.', '', 28153),
(151564, 'esMX', 'En eso te equivocas, Lady Liadrin. Las banderas de la Alianza flamearán sobre Arathi una vez más.', '', 28153),
(151563, 'esMX', '', 'Termina con esta farsa, Danath. El reclamo de los Aterratrols sobre esta tierra caducó hace años.', 28153),
(151562, 'esMX', 'No puedo quedarme con eso.', '', 28153),
(151561, 'esMX', 'Eso no me pertenece.', '', 28153),
(151560, 'esMX', 'Tengo que acercarme más.', '', 28153),
(151559, 'esMX', 'El sentimiento no es mutuo, cazador de las sombras.', '', 28153),
(151558, 'esMX', 'Está muy lejos.', '', 28153),
(151557, 'esMX', 'No alcanzo.', '', 28153),
(151556, 'esMX', 'Danath Aterratrols. Un guh\'to conocerte al fin...', '', 28153),
(151555, 'esMX', 'No puedo comerciar eso.', '', 28153),
(151554, 'esMX', 'No puedo usar eso.', '', 28153),
(151553, 'esMX', 'Eso no está equipado.', '', 28153),
(151552, 'esMX', 'No, Arathi me pertenece a MÍ. Tú y tu Horda pagarán por esta intromisión, Eitrigg.', '', 28153),
(151551, 'esMX', 'Primero debería equiparlo.', '', 28153),
(151550, 'esMX', '¡Aterratrols! Será mejor que te muevas. Arathi es de la Horda ahora.', '', 28153),
(151549, 'esMX', 'Pero antes, debemos fortificar esta posición. Necesitamos hierro y madera.', '', 28153),
(151548, 'esMX', '¡Aplasta a este enemigo!', '', 28153),
(151547, 'esMX', 'Ya lo creo, Lady Liadrin. Será un placer hacer justicia con una paladín de la Horda que ha perdido el rumbo.', '', 28153),
(151546, 'esMX', '¡A mi objetivo!', '', 28153),
(151545, 'esMX', '¡Destruye a mi enemigo!', '', 28153),
(151544, 'esMX', 'Ven por aquí.', '', 28153),
(151543, 'esMX', 'Deja que lidere un orco.', '', 28153),
(151542, 'esMX', '', '¿Turalyon? Esto será interesante...', 28153),
(151541, 'esMX', 'Sígueme.', '', 28153),
(151540, 'esMX', '¡Por la Horda!', '', 28153),
(151539, 'esMX', '¡Estoy herido!', '', 28153),
(151538, 'esMX', '¡Sáname!', '', 28153),
(151537, 'esMX', '¡No te quedes ahí! ¡Ayúdame!', '', 28153),
(151536, 'esMX', '¡Ayúdame ahora!', '', 28153),
(151535, 'esMX', 'Espera aquí.', '', 28153),
(151534, 'esMX', 'No te muevas.', '', 28153),
(151533, 'esMX', 'La Luz nos guía, Rokhan. No le tememos a las sombras.', '', 28153),
(151532, 'esMX', 'Cuídate de las sombra\', Turalyon. La Horda y yo vamo\' por ti...', '', 28153),
(151531, 'esMX', '¡Mueran con honor!', '', 28153),
(151530, 'esMX', '¡Al ataque!', '', 28153),
(151529, 'esMX', '¡Mok-thora ka!', '', 28153),
(151528, 'esMX', '¡Aplasten a nuestros enemigos!', '', 28153),
(151527, 'esMX', 'Es hora de expulsarte a ti y a tu ejército de la Horda de las colinas de Arathi, Eitrigg.', '', 28153),
(151526, 'esMX', '¡Atraviesen sus filas!', '', 28153),
(151525, 'esMX', '¡Retrocedan o mueran!', '', 28153),
(151524, 'esMX', '¡Lucharemos otro día!', '', 28153),
(151523, 'esMX', '¡Vamos! ¡Huyan!', '', 28153),
(151522, 'esMX', '¿Eso que huelo en mi campo de batalla son escorias de la Alianza? Parece que es hora de pelear.', '', 28153),
(151521, 'esMX', '¡Prepárense!', '', 28153),
(151520, 'esMX', 'Deberías volver regularmente. Sería una lástima desperdiciar ese hierro.', '', 28153),
(151519, 'esMX', '¡Que ardan todos!', '', 28153),
(151518, 'esMX', '¡Abran fuego!', '', 28153),
(151517, 'esMX', 'Llegarán pronto. Tenemos que construir esta base, y para eso debemos conseguir hierro y madera.', '', 28153),
(151516, 'esMX', '¡Tu Horda tendrá que vendarse el trasero cuando termine con ustedes! ¡Ja!', '', 28153),
(151515, 'esMX', '', 'Atrás, Muradin. Este territorio le pertenece a la Horda.', 28153),
(151514, 'esMX', '¡No, quiero un montón de cerdos de la Horda para probar el filo de mi espada nueva!', '', 28153),
(151513, 'esMX', '¿Qué hace\' aquí, Muradin? ¿Vienes a pelear?', '', 28153),
(151512, 'esMX', '¿Por qué no vuelves a tu páramo desolado, orco pulgoso?', '', 28153),
(151511, 'esMX', '¡Muradin! Tus enanos se han sobrepasado. Regresen a su montaña.', '', 28153),
(151510, 'esMX', '', 'La Alianza pronto estará en nuestra puerta. Debemos movernos rápido. Hay que asegurar reservas de hierro y madera para establecer una base.', 28153),
(151509, 'esMX', '', 'No te mientas a ti mismo, anciano. Vinimos para recuperar Stromgarde.', 28153),
(151508, 'esMX', '¡Lady Liadrin! Bienvenida a Arathi. Supongo que viniste a rendirte.', '', 28153),
(151507, 'esMX', '', 'Has estado ausente mucho tiempo, Turalyon. El mundo ha cambiado en tu ausencia.', 28153),
(151506, 'esMX', '¿Qué es esto? ¿Invasores de la Horda con un paladín al mando? Qué bajo ha caído el mundo.', '', 28153),
(151505, 'esMX', '', 'Me gustaría verte intentarlo, Muradin. Ahora este territorio le pertenece a la Horda.', 28153),
(151504, 'esMX', 'Quédate donde estás, muchacha, o decoraremos tu rostro con proyectiles de los morteros de la Alianza.', '', 28153),
(151503, 'esMX', 'Danath Aterratrols... ¡tú y yo tenemo\' asuntos pendiente\'! Te veré en el campo de batalla...', '', 28153),
(151502, 'esMX', '¿Se atreven a invadir Arathi? ¿Con un TROL al mando? Han cometido un grave error.', '', 28153),
(151501, 'esMX', '¿\"Piel verde\"? Ojojo... ahora me has hecho enojar.', '', 28153),
(151500, 'esMX', 'Reclamando', 'Reclamando', 28153),
(151499, 'esMX', '<Klause larga una risotada>\n\nSí, es muy probable. Tengo varios parientes dispersos por el mundo.', '', 28153),
(151498, 'esMX', '¿Te atreves a invadir Stromgarde, el hogar de los Aterratrols? Fuera de mi vista, piel verde.', '', 28153),
(151497, 'esMX', 'Hoy reclamamos lo que nos pertenece por derecho. ¡Por la Alianza!', '', 28153),
(151496, 'esMX', 'Los invasores han saqueado Stromgarde durante demasiado tiempo.', '', 28153),
(151495, 'esMX', '¡Por la Alianza!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'esMX', '¡Soldados de la Alianza! Hoy recuperaremos la noble ciudad de Stromgarde de las garras monstruosas de la Horda.', '', 28153),
(151493, 'esMX', 'Hoy recuperaremos las colinas de Arathi... ¡Por la Alianza!', '', 28153),
(151492, 'esMX', 'Carguen los rifles y desenvainen las espadas.', '', 28153),
(151491, 'esMX', '', '¡Arathi será nuestra! ¡Por la Horda!', 28153),
(151490, 'esMX', '', 'Concéntrense en su deber. Primero capturamos Ar\'gorok, ¡y luego avanzamos a Stromgarde!', 28153),
(151489, 'esMX', '¿Céfiro? Ya he conocido a alguien con ese nombre.', '¿Céfiro? Ya he conocido a alguien con ese nombre.', 28153),
(151488, 'esMX', '¡A guardar todo, muchachos! ¡Saquemos estas armas de aquí!', '', 28153),
(151487, 'esMX', 'El Castillo de Stromgarde se ha convertido en un Baluarte.', '', 28153),
(151486, 'esMX', 'Hemos terminado de construir la Armería.', '', 28153),
(151485, 'esMX', 'El Taller está listo.', '', 28153),
(151484, 'esMX', 'Nuestro Concejo se ha convertido en un Castillo.', '', 28153),
(151483, 'esMX', 'El Altar de Reyes está completo.', '', 28153),
(151482, 'esMX', '¡Ahora nuestro Castillo es un Baluarte!', '', 28153),
(151481, 'esMX', 'La Armería está construida.', '', 28153),
(151480, 'esMX', 'El Taller está listo para construir nuestros tanques.', '', 28153),
(151479, 'esMX', 'Nuestro Concejo se ha convertido en un Castillo.', '', 28153),
(151478, 'esMX', 'El Altar de Reyes está completo.', '', 28153),
(151477, 'esMX', '¡Perfecto! ¡El castillo ahora es un Baluarte!', '', 28153),
(151476, 'esMX', '¡La Armería está lista para equipar a nuestras fuerzas!', '', 28153),
(151475, 'esMX', 'Taller listo y en funcionamiento. ¡Hora de construir unos tanques!', '', 28153),
(151474, 'esMX', '¡El Concejo se ha convertido en Castillo!', '', 28153),
(151473, 'esMX', '¡El Altar de Reyes está listo!', '', 28153),
(151472, 'esMX', '', 'Ahora nuestro Bastión es una Fortaleza. ¡Por la Horda!', 28153),
(151471, 'esMX', '', 'Esta nueva Armería nos permitirá equipar mejor a nuestras tropas.', 28153),
(151470, 'esMX', '', 'El Taller se ha completado.', 28153),
(151469, 'esMX', '', 'Nuestra base se ha fortalecido. Ahora el Gran Salón es un Bastión.', 28153),
(151468, 'esMX', '', 'El Altar de Tormentas está listo.', 28153),
(151467, 'esMX', 'Nuestro Cuartel está listo para entrenar a nuestras fuerzas.', '', 28153),
(151466, 'esMX', 'Hemos terminado nuestro Cuartel. Es hora de comenzar a entrenar a las tropas.', '', 28153),
(151465, 'esMX', '¡Tenemos un Cuartel! ¡Empieza a entrenar a nuestras tropas!', '', 28153),
(151464, 'esMX', '', 'El Cuartel está listo para entrenar a nuestras tropas.', 28153),
(151463, 'esMX', '¡El Bastión ahora e\' una Fortaleza!', '', 28153),
(151462, 'esMX', 'Hemo\' mejorado nuestro Gran Salón a un Bastión.', '', 28153),
(151461, 'esMX', 'El Altar de Tormentas eh\'tá listo.', '', 28153),
(151460, 'esMX', 'El Cuartel eh\'tá listo. Eh\'ta es una guerra que tendrán que ganar los bruto\'.', '', 28153),
(151459, 'esMX', '¡Nuestro Bastión se ha convertido en Fortaleza!', '', 28153),
(151458, 'esMX', '¡Ahora nuestro Gran Salón es un Bastión!', '', 28153),
(151457, 'esMX', 'El Altar de Tormentas está terminado.', '', 28153),
(151456, 'esMX', 'Tenemos un Cuartel. ¡Empiecen a entrenar brutos!', '', 28153),
(151455, 'esMX', '', 'Ni lo sueñes. ¡Caballeros de sangre, elimínenlos!', 28153),
(151454, 'esMX', 'Y a mí tampoco me llaman cazador de las sombra\' sin motivo. ¡Ahora, asesino\'! ¡Muéstrense!', '', 28153),
(151453, 'esMX', 'Ya sé todo sobre la \"Justicia de la Alianza\". Jinetes del viento, ¡demuéstrenles el significado de la furia de la Horda!', '', 28153),
(151452, 'esMX', '', '¡Jamás!', 28153),
(151451, 'esMX', 'Nada en esta tierra te pertenece, Aterratrols. Los trols llegaron aquí mucho ante\' que tú.', '', 28153),
(151450, 'esMX', '¡Ja! Eso es lo que tú crees.', '', 28153),
(151449, 'esMX', '', 'Ya me cansé de sus amenazas vacías. ¡Caballeros de sangre, ataquen con la furia de la Luz!', 28153),
(151448, 'esMX', 'La Luz no te salvará ahora. Cazadore\' de las sombras, ¡muéh\'trense!', '', 28153),
(151447, 'esMX', '¡Jinetes del viento, ataquen desde los cielos!', '', 28153),
(151446, 'esMX', '', 'Ya veremos, Turalyon. Aún tienes que lidiar conmigo.', 28153),
(151445, 'esMX', 'Y yo te eh\'taré esperando.', '', 28153),
(151444, 'esMX', 'No si yo puedo evitarlo, Turalyon.', '', 28153),
(151443, 'esMX', '', 'No bastará, enano. ¡Caballeros de sangre, a las armas!', 28153),
(151442, 'esMX', 'Caíh\'te justo en mi trampa, Muradin. ¡Cazadores de las sombras, muéh\'trense!', '', 28153),
(151441, 'esMX', '¡Ahora, jinetes del viento! ¡Ataquen!', '', 28153),
(151440, 'esMX', '', 'Nunca.', 28153),
(151439, 'esMX', '¡No te descuides, Muradin!', '', 28153),
(151438, 'esMX', 'No por mucho tiempo, enano. ¡Por la Horda!', '', 28153),
(151437, 'esMX', 'Ya perdí esta ciudad una vez. No permitiré que suceda de nuevo, y menos contra alguien como tú. Defensores, ¡muéstrenles el poder de Stromgarde!', '', 28153),
(151436, 'esMX', 'Yo estar a salvo ahora. Vuelvo a trabajar.', '', 28153),
(151435, 'esMX', 'La Luz está de mi lado. ¡Defensores, avancen!', '', 28153),
(151434, 'esMX', '¡Defenderé Stromgarde hasta mi último aliento, Liadrin! ¡Defensores, firmes!', '', 28153),
(151433, 'esMX', 'Ahórrate tus celebraciones, elfa de sangre. Todavía debes enfrentarte a mí.', '', 28153),
(151432, 'esMX', 'Sí... cuento con eso.', '', 28153),
(151431, 'esMX', '¡Bah! ¡El terreno elevado está sobrevaluado!', '', 28153),
(151430, 'esMX', 'Este viejo tonto aún tiene algunos trucos bajo la manga, trol. Defensores, ¡muéstrenle el poder de Stromgarde!', '', 28153),
(151429, 'esMX', 'La Luz siempre vencerá a las sombras, Rokhan. ¡Defensores, avancen!', '', 28153),
(151428, 'esMX', '¡Vamos, Rokhan! Te he estado esperando. ¡Defensores, demuéstrenles de qué estamos hechos!', '', 28153),
(151427, 'esMX', 'Cierra la boca, trol. La Alianza prevalecerá sobre tu sucio ejército de monstruos.', '', 28153),
(151426, 'esMX', 'Pero la Luz brilla sobre Stromgarde.', '', 28153),
(151425, 'esMX', 'Pronto, muchachito. Creo que antes dejaré que mis fusileros se diviertan contigo.', '', 28153),
(151424, 'esMX', 'Stromgarde sigue en pie, orco. Será un placer ver tu cadáver flotando en mi foso. Defensores, ¡muéstrenle lo fuerte que es nuestra ciudad!', '', 28153),
(151423, 'esMX', 'He ganado y perdido muchas más batallas de las que jamás verás, Eitrigg. Y esta batalla aún no termina. ¡Defensores, avancen!', '', 28153),
(151422, 'esMX', 'Primero tendrás que alcanzarla, muchachito. ¡Defensores, expúlsenlos!', '', 28153),
(151421, 'esMX', 'Pff... Tú y los de tu clase son todos iguales. Morirás de rodillas, como los demás.', '', 28153),
(151420, 'esMX', 'Ten paciencia, orco. Ya verás.', '', 28153),
(151419, 'esMX', '¡Y yo huelo tu aliento desde aquí! ¡Veamos lo que tienes, orco!', '', 28153),
(151418, 'esMX', 'Ahora, máquinas de asedio, derriben esa puerta. ¡Quiero la cabeza de esa elfa de sangre en una pica!', '', 28153),
(151417, 'esMX', 'Ahora, máquinas de asedio, derriben esa puerta, ¡y tráiganme a Rokhan! No por nada me llaman Aterratrols...', '', 28153),
(151416, 'esMX', 'Ahora, máquinas de asedio, derriben esa puerta. ¡Este orco vil conocerá lo que es la justicia de la Alianza!', '', 28153),
(151415, 'esMX', 'El Alto Pedestal es nuestro. Esta es tu última oportunidad, elfa de sangre. Ríndete, y tal vez te perdone la vida.', '', 28153),
(151414, 'esMX', 'Hemos asegurado el Alto Pedestal. ¡Pronto saquearemos Ar\'gorok, y recuperaremos lo que nos pertenece por derecho!', '', 28153),
(151413, 'esMX', 'El Alto Pedestal es nuestro. Pronto cumpliremos con nuestra misión de lidiar con estos intrusos.', '', 28153),
(151412, 'esMX', 'El control del Filón de Galson representa un suministro de hierro ilimitado. Eso nos será útil.', '', 28153),
(151411, 'esMX', 'Perfecto. El Aserradero de Tierras Altas nos proveerá la madera necesaria para reconstruir Stromgarde.', '', 28153),
(151410, 'esMX', 'Esta es nuestra oportunidad. ¡Asedien la puerta! ¡Estos invasores de la Horda merecen el peor castigo!', '', 28153),
(151409, 'esMX', 'Esta es nuestra oportunidad. ¡Asedien la puerta! ¡La Luz ha venido a buscarte, Rokhan!', '', 28153),
(151408, 'esMX', 'Esta es nuestra oportunidad. ¡Asedien la puerta! ¡Ha llegado tu fin, Eitrigg!', '', 28153),
(151407, 'esMX', 'Hemos capturado Alto Pedestal. La Luz marcha junto a la Alianza.', '', 28153),
(151406, 'esMX', 'El Alto Pedestal es nuestro y Ar\'gorok caerá pronto. Vamos por ti, Rokhan.', '', 28153),
(151405, 'esMX', 'Hemos asegurado el Alto Pedestal. Pronto destruiremos las fuerzas de la Horda por completo.', '', 28153),
(151404, 'esMX', 'Bien hecho. El Filón de Galson nos proveerá todo el hierro que necesitamos.', '', 28153),
(151403, 'esMX', 'La madera de ese aserradero será esencial para construir nuestra base.', '', 28153),
(151402, 'esMX', '¡Rápido, traigan las máquinas de asedio! ¡Derriben la puerta! ¡Muéstrenle a esa elfa de sangre de qué están hechos los morteros enanos!', '', 28153),
(151401, 'esMX', '¡Rápido, traigan las máquinas de asedio! ¡Derriben la puerta! ¡Prendan fuego la choza de ese trol!', '', 28153),
(151400, 'esMX', '¡Rápido, traigan las máquinas de asedio! ¡Derriben la puerta! ¡Hagan volar a esos orcos por los aires!', '', 28153),
(151399, 'esMX', '¡El Alto Pedestal le pertenece a la Alianza! ¿Ya estás lista para ondear esa bandera blanca, muchachita?', '', 28153),
(151398, 'esMX', '¡Capturamos el Alto Pedestal! Ahora vamos por ti, Rokhan.', '', 28153),
(151397, 'esMX', 'Je... Nunca pagué la cuenta del bar...', 'Je... Nunca pagué la cuenta del bar...', 28153),
(151396, 'esMX', '¡El Alto Pedestal es nuestro! ¡Por la Alianza!', '', 28153),
(151395, 'esMX', 'Tal vez... podamos hacer un trato...', 'Tal vez... podamos hacer un trato...', 28153),
(151394, 'esMX', 'Con el Filón de Galson bajo control, deberíamos tener más que suficiente hierro.', '', 28153),
(151393, 'esMX', 'Bien, hemos asegurado el Aserradero de Tierras Altas. Ahora podemos usar ese lugar para construir nuestra base.', '', 28153),
(151392, 'esMX', '', 'Eh\'ta lucha requiere habilidad. ¡Algo que ustedes no tienen!', 28153),
(151391, 'esMX', '', '¡Traigan los demoledores! ¡Destruyan su puerta! ¡Que no queden más que escombros de Stromgarde!', 28153),
(151390, 'esMX', '¡Cuidado, $gcompañero:compañera;!', '¡Cuidado, $gcompañero:compañera;!', 28153),
(151389, 'esMX', '', '¡Traigan los demoledores! ¡Destruyan su puerta! ¡Ha llegado tu hora, Turalyon!', 28153),
(151388, 'esMX', '¿Cuál es la gran idea?', '¿Cuál es la gran idea?', 28153),
(151387, 'esMX', '', '¡Traigan los demoledores! ¡Destruyan su puerta! ¡Obliguen a ese enano a salir!', 28153),
(151386, 'esMX', '', '¡El Alto Pedestal es nuestro! ¡Estamos cada vez más cerca de reclamar Arathi para la Horda!', 28153),
(151385, 'esMX', '', '¡Nos hemos apoderado del Alto Pedestal! La Horda pronto te alcanzará, Turalyon.', 28153),
(151384, 'esMX', '', 'Hemos capturado el Alto Pedestal, y también el terreno elevado. Tenemos la ventaja.', 28153),
(151383, 'esMX', '', 'Buen trabajo. No llegaremos lejos sin el hierro de esa mina.', 28153),
(151382, 'esMX', '¡Ni siquiera en la muerte pueden triunfar! ¡Apártense y contemplen la grandeza!', '', 28153),
(151381, 'esMX', '', 'Usaremos la madera de la Cresta Hachazo para construir los cimientos de nuestra base. Excelente trabajo.', 28153),
(151380, 'esMX', '¡Envíen a los demoledore\'! ¡Destruyan la puerta! ¡Y tráiganme la cabeza de ese viejo tonto de Aterratrols!', '', 28153),
(151379, 'esMX', '¡Envíen a los demoledore\'! ¡Ninguna Luz protegerá a ese paladín del poder de la Horda!', '', 28153),
(151378, 'esMX', '¡Envíen a los demoledore\'! ¡Ese enano no puede esconderse detrás de esa puerta para siempre!', '', 28153),
(151377, 'esMX', 'El Alto Pedestal ha caído en mano\' de la Horda, Aterratrols.', '', 28153),
(151376, 'esMX', 'El Alto Pedestal nos pertenece, Turalyon. Las sombra\' se acercan...', '', 28153),
(151375, 'esMX', 'Muradin... hemo\' capturado el Alto Pedestal. ¿Ya estás listo para salir a luchar?', '', 28153),
(151374, 'esMX', 'La Mina Mostacho Seco le pertenece a la Horda.', '', 28153),
(151373, 'esMX', '', 'Mhrr. Sus muertes inútile\' son un reflejo de lo que fueron en vida. ¡Yo me encargaré de ellos!', 28153),
(151372, 'esMX', 'Bien. Usaremo\' la madera de la Cresta Hachazo para construir nuestro bastión.', '', 28153),
(151371, 'esMX', '¡Traigan los demoledores! ¡Derriben esa puerta! ¡Mostrémosle a ese necio de Aterratrols lo que pueden hacer unos pocos pieles verdes!', '', 28153),
(151370, 'esMX', '', 'Te has vuelto una mujer valiente, Taelia. Tu padre estaría orgulloso.', 28153),
(151369, 'esMX', '¡Traigan los demoledores! ¡Derriben esa puerta! ¡Esta batalla ha terminado!', '', 28153),
(151368, 'esMX', '¡Traigan los demoledores! ¡Derriben esa puerta! ¡Clavaremos la apestosa cabeza de ese enano en una pica!', '', 28153),
(151367, 'esMX', 'El jefe no estará muy feliz...', 'El jefe no estará muy contento...', 28153),
(151366, 'esMX', 'El Alto Pedestal le pertenece a la Horda. O tal vez deba decir... a los \"pieles verdes\".', '', 28153),
(151365, 'esMX', 'El Alto Pedestal es nuestro. ¿Qué ha pasado con ese castigo, Turalyon? Estoy esperando...', '', 28153),
(151364, 'esMX', 'Au...', 'Au...', 28153),
(151363, 'esMX', 'No era... personal...', 'No era... personal...', 28153),
(151362, 'esMX', 'Hemos capturado Alto Pedestal. ¡Muradin! ¡Puedo ver tu narizota deforme desde aquí arriba!', '', 28153),
(151361, 'esMX', 'Solo hacía... mi trabajo..', 'Solo hacía... mi trabajo..', 28153),
(151360, 'esMX', '', 'Taelia... Claro. Nuestra joven protectora del otro lado del mar. ¿De verdad ha pasado tanto tiempo?', 28153),
(151359, 'esMX', 'Bien hecho. Con la Mina Mostacho Seco bajo nuestro control, nunca nos faltará hierro.', '', 28153),
(151358, 'esMX', 'La Cresta Hachazo es nuestra. Podemos usar el aserradero de allí para construir nuestra base.', '', 28153),
(151357, 'esMX', 'No es nada personal, ¡pero tenemos reglas!', 'No es nada personal, ¡pero tenemos reglas!', 28153),
(151356, 'esMX', 'Paso Valeroso nos pertenece. ¡Sigan atacando!', '', 28153),
(151355, 'esMX', '', 'Taelia, señora.', 28153),
(151354, 'esMX', 'Bien hecho. Hemos recapturado el Círculo de Elementos.', '', 28153),
(151353, 'esMX', 'Los estandartes de la Alianza flamean sobre Granovel una vez más.', '', 28153),
(151352, 'esMX', '', 'Desde luego. ¿Tu nombre es...?', 28153),
(151351, 'esMX', 'Hemos asegurado Paso Valeroso.', '', 28153),
(151350, 'esMX', 'Ahora el Círculo de Elementos le pertenece a la Alianza.', '', 28153),
(151349, 'esMX', 'Buen trabajo, soldados. Granovel nos pertenece.', '', 28153),
(151348, 'esMX', '¡Ya basta!', '¡Ya basta!', 28153),
(151347, 'esMX', '', 'Lady almirante, quizá debamos regresar al fuerte. Puedo analizar la evidencia en contra de la casa Aspafresno allí, con usted.', 28153),
(151346, 'esMX', 'Bien, los expulsamos de Paso Valeroso. ¡No se detengan!', '', 28153),
(151345, 'esMX', '¡Hemos tomado el Círculo de Elementos!', '', 28153),
(151344, 'esMX', '¡Acabas de cruzar la línea!', '¡Acabas de cruzar la línea!', 28153),
(151343, 'esMX', '¡Hemos saqueado Granovel!', '', 28153),
(151342, 'esMX', '', 'El Círculo de Elementos nos pertenece.', 28153),
(151341, 'esMX', '', 'Hemos logrado asegurar Granovel.', 28153),
(151340, 'esMX', '¡Tenemos métodos para lidiar con gente problemática!', '¡Tenemos métodos para lidiar con gente problemática!', 28153),
(151338, 'esMX', '', 'Listo, eso debería darnos un respiro.', 28153),
(151337, 'esMX', '¡Oye!', '¡Oye!', 28153),
(151336, 'esMX', 'Cuídate de las sombra\', escoria de la Alianza. La Horda va por ti...', '', 28153),
(151335, 'esMX', 'Bien peleado. Con el Cruce Redilnorte en nuestras manos, podemos concentrarnos en objetivos más grandes.', '', 28153),
(151333, 'esMX', '', '¡Ey, tú! Me gustaría hablar contigo.', 28153),
(151332, 'esMX', 'Esperé una eternidad para ejecutar mi venganza, hasta que por fin tu madre me proporcionó los medios.', '', 28153),
(151331, 'esMX', 'Tus ancestros aniquilaron a mi pueblo, pero no pudieron conmigo.', '', 28153),
(151330, 'esMX', '', '¡¿Gorak Tul?! ¿Cómo es posible? ¡Mis ancestros te derrotaron hace eones!', 28153),
(151329, 'esMX', '¡Máquinas de asedio, destruyan esa base!', '', 28153),
(151328, 'esMX', 'Se los advertí, escorias de la Horda. Ahora prepárense para la aniquilación.', '', 28153),
(151327, 'esMX', '¡Estas son tierras de la Alianza! Las murallas bendecidas por la Luz de Stromgarde nunca caerán ante alguien como tú.', '', 28153),
(151326, 'esMX', '¿Es la Horda lo que veo en mi campo de batalla? ¡He estado esperando por una buena pelea!', '', 28153),
(151324, 'esMX', '¡Tienes que detenerlos... y absorber la azerita para alimentar el corazón!', '', 28153),
(151323, 'esMX', 'Están apareciendo más heridas por todo Azeroth... y hay más fuerzas que buscan apoderarse de la azerita para sus propios fines.', '', 28153),
(151322, 'esMX', 'El Corazón de Azeroth es la clave para curar a nuestro mundo... pero si realmente planeamos salvarlo, necesitarás reunir más poder.', '', 28153),
(151321, 'esMX', 'Magni, estoy listo para que potencies el Corazón de Azeroth.', 'Magni, estoy lista para que potencies el Corazón de Azeroth.', 28153),
(151320, 'esMX', 'Adalid, debo hablar contigo en Silithus. ¡Aún queda mucho por hacer para sanar a nuestro mundo!', '', 28153),
(151319, 'esMX', '', '¡Tengo una escoba y no temo usarla!', 28153),
(151318, 'esMX', '', '¡Fuera, roedores con alas!', 28153),
(151317, 'esMX', '', '¡Largo de mi puerta!', 28153),
(151316, 'esMX', '', '¡Fuera de aquí, pájaros asquerosos!', 28153),
(151315, 'esMX', '¡Es hora de pagar, miserables!', '', 28153),
(151314, 'esMX', '¡Bestias de pesadillas, vengan a mí!', '', 28153),
(151313, 'esMX', 'Tengo un buen presentimiento. Hoy lo encontraremos.', 'Tengo un buen presentimiento. Hoy lo encontraremos.', 28153),
(151312, 'esMX', 'Esas botas me quedarán de maravilla.', 'Esas botas me quedarán de maravilla.', 28153),
(151311, 'esMX', '¡Te cortaré!', '¡Te cortaré!', 28153),
(151310, 'esMX', 'Nadie puede salvarte aquí, miserable.', 'Nadie puede salvarte aquí, miserable.', 28153),
(151309, 'esMX', 'Mira por donde caminas.', 'Mira por donde caminas.', 28153),
(151308, 'esMX', 'Puedo matarte muy fácilmente...', 'Puedo matarte muy fácilmente...', 28153),
(151307, 'esMX', 'Ya verás...', 'Ya verás...', 28153),
(151306, 'esMX', '¡Esos recursos no te pertenecen!', '¡Esos recursos no te pertenecen!', 28153),
(151305, 'esMX', '¡Mercancías nuevas!', '¡Mercancías nuevas!', 28153),
(151304, 'esMX', '¡Los océanos se alzan! ¡Vengan, mis esbirros!', '', 28153),
(151303, 'esMX', '¡Horrores reptantes, vengan a alimentarse!', '', 28153),
(151302, 'esMX', '¡Criaturas de las profundidades, a mí!', '', 28153),
(151301, 'esMX', 'Aire oler bien aquí. No como mina llena de orcos.', '', 28153),
(151300, 'esMX', '¡La oscuridad los tragará!', '', 28153),
(151299, 'esMX', 'Ya estoy harto. ¡Este será su fin!', '', 28153),
(151298, 'esMX', 'Los esbirros de Azshara son infinitos. ¿Por qué resistir?', '', 28153),
(151297, 'esMX', 'Yo ya no tener tanto miedo, pero rocas me cansan brazos.', '', 28153),
(151295, 'esMX', 'Ya puede oír los susurros. Creo que no tenemos mucho tiempo.', '', 28153),
(151294, 'esMX', '', 'Iré detrás de ti. ¡No me esperes!', 28153),
(151293, 'esMX', 'Bajo las mareas... esperando... llamando...', '', 28153),
(151292, 'esMX', 'Por aquí. Yo conseguir hierro.', '', 28153),
(151291, 'esMX', 'Busca expositores de armas en las cercanías. Los infieles las guardan por aquí.\n\nMantendré un perfil bajo hasta que regreses.', 'Busca expositores de armas en las cercanías. Los infieles las guardan por aquí.\n\nMantendré un perfil bajo hasta que regreses.', 28153),
(151290, 'esMX', '', 'Vientos, ¡protéjanme!', 28153),
(151289, 'esMX', 'Regresaré cuando encuentre un arma para ti.', 'Regresaré cuando encuentre un arma para ti.', 28153),
(151288, 'esMX', '', '¡El viento siempre está a nuestro favor!', 28153),
(151287, 'esMX', '¡Convertiré sus huesos en astillas!', '', 28153),
(151286, 'esMX', '¡Mi casco es impenetrable!', '', 28153),
(151285, 'esMX', '¡Los elementos se enfurecen!', '¡Los elementos se enfurecen!', 28153),
(151284, 'esMX', 'Los mortales ladrones de mundos perecerán.', 'Los mortales ladrones de mundos perecerán.', 28153),
(151283, 'esMX', '¡Tomaremos todo lo que saquearon!', '¡Tomaremos todo lo que saquearon!', 28153),
(151282, 'esMX', '¡Los elementos imperarán!', '¡Los elementos imperarán!', 28153),
(151281, 'esMX', '¡No nos las arrebatarán!', '¡No nos las arrebatarán!', 28153),
(151280, 'esMX', '¡Estas gemas pertenecen a los señores elementales!', '¡Estas gemas pertenecen a los señores elementales!', 28153),
(151279, 'esMX', '<Libera al esclavo y dale un arma para pelear.>', '<Libera al esclavo y dale un arma para pelear.>', 28153),
(151278, 'esMX', 'Con este poder, ¡reconquistaremos el mundo!', 'Con este poder, ¡reconquistaremos el mundo!', 28153),
(151277, 'esMX', '<Libera al esclavo y dale un arma para pelear.>', '<Libera al esclavo y dale un arma para pelear.>', 28153),
(151276, 'esMX', 'El señor me recompensará por tu destrucción.', 'El señor me recompensará por tu destrucción.', 28153),
(151275, 'esMX', 'Dame un arma y yo te daré diez cadáveres de infieles.', 'Dame un arma y yo te daré diez cadáveres de infieles.', 28153),
(151274, 'esMX', 'Junta tus cosas. Tú vienes conmigo.', 'Junta tus cosas. Tú vienes conmigo.', 28153),
(151273, 'esMX', 'Rompe estas cadenas, $Gamigo:amiga;. Los vulperas no nacimos para ser prisioneros.', 'Rompe estas cadenas, $Gamigo:amiga;. Los vulperas no nacimos para ser prisioneros.', 28153),
(151272, 'esMX', 'Yo querer trabajar, pero no seguro.', '', 28153),
(151271, 'esMX', 'Libérame, $pr, y te ayudaré a matar a los infieles.', 'Libérame, $pr, y te ayudaré a matar a los infieles.', 28153),
(151270, 'esMX', 'No habrá piedad para los infieles. No después de lo que han hecho.', 'No habrá piedad para los infieles. No después de lo que han hecho.', 28153),
(151269, 'esMX', 'Haré que los infieles paguen por lo que me han hecho.', 'Haré que los infieles paguen por lo que me han hecho.', 28153),
(151268, 'esMX', '¿Te ha enviado Nisha? No sé cuál es su plan, pero cuenten conmigo.', '¿Te ha enviado Nisha? No sé cuál es su plan, pero cuenten conmigo.', 28153),
(151267, 'esMX', 'Solo consígueme un arma y yo me encargaré del resto.', 'Solo consígueme un arma y yo me encargaré del resto.', 28153),
(151266, 'esMX', 'Solo necesito un arma.', 'Solo necesito un arma.', 28153),
(151265, 'esMX', 'No... las gemas son mías... no pueden... llevárselas...', '', 28153),
(151264, 'esMX', '¡No! ¡Necios!', '', 28153),
(151263, 'esMX', 'No... han... ganado...', '', 28153),
(151262, 'esMX', '¡Regresaré!', '', 28153),
(151261, 'esMX', 'Nuestro momento se acerca...', '', 28153),
(151260, 'esMX', 'Solo retrasas... lo inevitable...', '', 28153),
(151259, 'esMX', 'El caos... reinará...', '', 28153),
(151258, 'esMX', 'Nada puede detener... a los elementos...', '', 28153),
(151257, 'esMX', '¡Sus mares hervirán, sus cielos se partirán, sus montañas se alzarán y nosotros regresaremos!', '', 28153),
(151256, 'esMX', '¡Un nuevo amanecer para los elementales se acerca!', '', 28153),
(151255, 'esMX', 'Se les acaba el tiempo, mortales.', '', 28153),
(151254, 'esMX', 'Con estas gemas, por fin los destruiremos.', '', 28153),
(151253, 'esMX', '¡Los elementos volverán a gobernar!', '', 28153),
(151252, 'esMX', '¡Los minerales dorados nos fortalecen!', '', 28153),
(151251, 'esMX', '¡Su mundo volverá a pertenecernos!', '', 28153),
(151250, 'esMX', '¿Cómo se atreven a enfrentarme en mi propio plano?', '', 28153),
(151249, 'esMX', 'Yo observar. ¡Manos muy llenas!', '', 28153),
(151248, 'esMX', 'Envíame a Orgrimmar.', 'Envíame a Orgrimmar.', 28153),
(151247, 'esMX', '', '$n, me alegra verte. Por lo pronto, me quedaré aquí para estar cerca de Krag\'wa.\n\nMis padres me han contado mile\' de historias sobre el loa rana. Será un honor protegerlo de lo\' trols de sangre.', 28153),
(151246, 'esMX', 'Eso debería bastar. ¡Gracias!', 'Eso debería bastar. ¡Gracias!', 28153),
(151245, 'esMX', 'Adalid, ¡tráeme las balas de cañón para que pueda seguir disparando!', 'Adalid, ¡tráeme las balas de cañón para que pueda seguir disparando!', 28153),
(151244, 'esMX', '', 'Drahnor. ¿Draynor? Draanur. Draenor. <Suspiro>. Digamos que soy de Terrallende.', 28153),
(151243, 'esMX', '', 'Puedes llamarme incorrupta, pero prefiero considerarme una orco \"orgánica\".', 28153),
(151242, 'esMX', '', 'Una vez me teñí el pelo de color verde. Al jefe de guerra Grito Infernal no le gustó NADA.', 28153),
(151241, 'esMX', '', 'Ya basta de tanta estrategia y cháchara... ¡BAH! ¡Solo quiero aplastar cosas!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'esMX', '', 'Los guerreros de Mano Destrozada son legendarios, pero jamás le pidas a uno que te rasque la espalda. Sé lo que te digo... <sonidos de dolor>', 28153),
(151239, 'esMX', '', 'Azeroth tiene tantas reglas... No puedes apuñalar a estos, pero a estos otros sí... No puedes golpear a aquellos, pero a los otros sí... ¡Tienen que relajarse!', 28153),
(151238, 'esMX', '', 'Oye... ¿No eres tú quien dejó esa fortaleza abandonada en medio de Pirofrío?', 28153),
(151237, 'esMX', '', 'Puedes quedarte todo el tiempo que quieras. Pero recuerda: ¡el que rompe, paga, $gamigo:amiga;!', 28153),
(151236, 'esMX', '', 'Antes de seguir, debo preguntarte algo... ¿Cuánto dolor puedes soportar?', 28153),
(151235, 'esMX', '', 'Que disfrute de tu compañía no implica que no tenga ganas de golpearte.', 28153),
(151234, 'esMX', '', 'Un chamán Foso Sangrante se la pasó guiñándome un ojo. No sé si estaba coqueteando o si había perdido el otro ojo en un sacrificio.', 28153),
(151233, 'esMX', '', 'La última persona que intentó coquetear conmigo tuvo que acudir al dentista de urgencia.', 28153),
(151232, 'esMX', '', 'Un orco verde se me acercó y me dijo que renunciaría a la vileza por mí. Le agradecí la oferta y le hundí mi maza en la cabeza.', 28153),
(151231, 'esMX', '', '¿Sabes si Colmillosauro está soltero? El paso del tiempo sí que le sienta bien...', 28153),
(151230, 'esMX', '', 'No necesitas un Portal Oscuro... Ya has invadido mi corazón.', 28153),
(151229, 'esMX', '', 'Lo... lamento.', 28153),
(151228, 'esMX', '', '¡Patético! ¡Caerás ante los Mag\'har!', 28153),
(151227, 'esMX', 'Si quieres que algo se haga bien...', '¡Arrrgh! Si quieres que algo salga bien...', 28153),
(151226, 'esMX', 'Debería haber pedido... ese aumento...', 'Parece que... me quemaron...', 28153),
(151225, 'esMX', 'Sepúltenme... junto con mi dinero...', 'Nada detiene a la muerte... ni a los impuestos...', 28153),
(151224, 'esMX', 'Eso... duele...', 'Pagarás... por eso...', 28153),
(151223, 'esMX', 'No valió... la pena...', 'No valió... la pena...', 28153),
(151222, 'esMX', 'Dónde está... mi adicional... por riesgos...', 'No valió... la pena...', 28153),
(151221, 'esMX', '', 'Estoy agradecida.', 28153),
(151220, 'esMX', '', 'Te lo agradezco.', 28153),
(151219, 'esMX', 'La jefa de guerra no tiene problema con los daños colaterales. ¡Arde, nena!', 'La jefa de guerra no tiene problema con los daños colaterales. ¡Arde, nena!', 28153),
(151218, 'esMX', '¡Daño colateral aprobado! ¡Arde, mi amor, arde!', 'Le han puesto precio a tu cabeza... ¡y pienso quedarme con ella!', 28153),
(151217, 'esMX', '', 'Estoy en deuda contigo.', 28153),
(151216, 'esMX', '', '¡Caerás ante mí!', 28153),
(151215, 'esMX', 'Nunca... la detendrán...', 'Nunca... la detendrán...', 28153),
(151214, 'esMX', 'Intentaste salvar la ciudad equivocada, camarada.', '¡Acabas de cometer un grave error!', 28153),
(151213, 'esMX', '', '¡Por las lunas de Draenor!', 28153),
(151212, 'esMX', '¡Oh! ¡Disfrutaré mucho de esto!', '¡Me encanta quemar cosas!', 28153),
(151211, 'esMX', 'Por la Horda... ¡Y por el dinero!', '¡Por la Horda!', 28153),
(151210, 'esMX', '', 'Solo cumplí con mi deber.', 28153),
(151209, 'esMX', '', 'No vuelvas a pedirme eso.', 28153),
(151208, 'esMX', '', 'Un placer.', 28153),
(151207, 'esMX', '', 'No.', 28153),
(151206, 'esMX', '', '¡Dije que no!', 28153),
(151205, 'esMX', '', '¡Jamás!', 28153),
(151204, 'esMX', '', 'Así es.', 28153),
(151203, 'esMX', '', 'Bien.', 28153),
(151202, 'esMX', '', 'Ciertamente.', 28153),
(151201, 'esMX', '', '¡He deshonrado a mi clan!', 28153),
(151200, 'esMX', '', 'Déjame recuperar maná.', 28153),
(151199, 'esMX', '', '¡Necesito maná!', 28153),
(151198, 'esMX', '', 'Que mueras bien.', 28153),
(151197, 'esMX', '', 'No tengo nada más que decir.', 28153),
(151196, 'esMX', '', 'Puedes irte.', 28153),
(151195, 'esMX', '', 'Ve con honor.', 28153),
(151194, 'esMX', '', 'Habla.', 28153),
(151193, 'esMX', '', 'Un gusto.', 28153),
(151192, 'esMX', '', '¡Lok-tar!', 28153),
(151191, 'esMX', '', '¡Throm-ka!', 28153),
(151190, 'esMX', '', '¡Por favor! ¡Te lo ruego!', 28153),
(151189, 'esMX', '', '¡Apiádate de esta pobre orco!', 28153),
(151188, 'esMX', '', '¡Ten piedad con esta peona!', 28153),
(151187, 'esMX', '', 'Un trabajo bien hecho.', 28153),
(151186, 'esMX', '', 'Impresionante... supongo.', 28153),
(151185, 'esMX', '', '<Hum.> Te felicito.', 28153),
(151184, 'esMX', '¡A moverse, ratas! ¡Las defensas no se sostendrán por sí solas!', '', 28153),
(151183, 'esMX', '', '¡Aplasta a este enemigo!', 28153),
(151182, 'esMX', '', '¡A mi objetivo!', 28153),
(151181, 'esMX', '', '¡Destruye a mi enemigo!', 28153),
(151180, 'esMX', '', '¡Mueran con honor!', 28153),
(151179, 'esMX', '', '¡Al ataque!', 28153),
(151178, 'esMX', '', '¡Mok-thora ka!', 28153),
(151177, 'esMX', '¿Y tú por qué peleas?', '¿Y tú por qué peleas?', 28153),
(151176, 'esMX', 'La Horda prevalecerá.', 'La Horda prevalecerá.', 28153),
(151175, 'esMX', '', '¡Nos atacan!', 28153),
(151174, 'esMX', '', '¡Aplasten a nuestros enemigos!', 28153),
