(151172, 'esMX', '', '¡Retrocedan o mueran!', 28153),
(151171, 'esMX', '', '¡Lucharemos otro día!', 28153),
(151170, 'esMX', '', '¡Vamos! ¡Huyan!', 28153),
(151169, 'esMX', '', 'Ven por aquí.', 28153),
(151168, 'esMX', '', 'Deja que lidere una orco.', 28153),
(151167, 'esMX', 'Camaradas... sigan sin mí...', 'Camaradas... sigan sin mí...', 28153),
(151166, 'esMX', 'Ahora descansaré.', 'Ahora descansaré.', 28153),
