(151163, 'esMX', 'Da un paso al costado, y quizá te perdone la vida.', 'Da un paso al costado, y quizá te perdone la vida.', 28153),
(151162, 'esMX', 'Sanamos, pero también podemos hacer mucho daño...', 'Sanamos, pero también podemos hacer mucho daño...', 28153),
(151161, 'esMX', '', '¡Por la Horda!', 28153),
(151160, 'esMX', 'Horda, ¡aquí! ¡Sanaré sus heridas!', 'Horda, ¡aquí! ¡Sanaré sus heridas!', 28153),
(151159, 'esMX', '', '¡Estoy herida!', 28153),
(151158, 'esMX', '', '¡Sáname!', 28153),
