(151044, 'esMX', 'Yo debería... ¡Déjenmelo a mí!', '', 28153),
(151043, 'esMX', 'Eh\'to no eh\'taba... en mis visione\'...', 'Eso... fue sorprendente...', 28153),
(151042, 'esMX', '¡Mantengan a esa lacra fuera de mi partida, amigos!', '', 28153),
(151041, 'esMX', '¡Vamos, muchachos! ¡Me gusta el dinero!', '', 28153),
(151040, 'esMX', 'Antes de entrar, necesitamos investigar un poco más para descubrir qué traman estos trols y cómo detenerlos.', '', 28153),
(151039, 'esMX', 'Por supuesto, mi instinto me dice que hay más problemas en las profundidades del templo.', '', 28153),
(151038, 'esMX', 'Hicieron un buen trabajo al acabar con esa bestia.', '', 28153),
(151037, 'esMX', 'Claro que no somos los únicos a los que han atraído hasta aquí.', '', 28153),
(151036, 'esMX', 'Sí, este es el lugar. Puedo sentir el poder de estas reliquias en mis huesos.', '', 28153),
(151034, 'esMX', '', '¡Ey, tú! Mis amigos me dieron por muerta... ¿Me ayudas?', 28153),
(151031, 'esMX', '', 'Mmmm.... Fascinante...', 28153),
(151030, 'esMX', '¡Aprende a preparar tus propias comidas! ¡Nunca confíes en un cocinero flacucho!', '', 28153),
(151029, 'esMX', 'Lo\' loa... me llaman...', 'Pura... suerte...', 28153),
(151028, 'esMX', 'La Horda... prevalece...', 'La Horda... vencerá...', 28153),
(151027, 'esMX', 'Bwonsamdi, ahí voy...', 'Bwonsamdi, ahí voy...', 28153),
(151026, 'esMX', '¡Tontos! ¡¿Cómo pueden morir frente al loa de un templo en ruinas que se ha quedado sin seguidores?! ¡Mátenlo!', '', 28153),
(151025, 'esMX', 'Bwonsamdi... voy a ti...', 'Veo... el Otro Lado...', 28153),
(151024, 'esMX', '¡Eh\'to no te va a guh\'tar nada!', '¡Algo malo viene por ti!', 28153),
(151023, 'esMX', 'Oh, sí. Órdenes de la jefa de guerra. Sin sobrevivente\'.', 'Oh, sí. Órdenes de la jefa de guerra. Sin sobrevivente\'.', 28153),
(151022, 'esMX', '¡No te mueva\'!', '¡No podrás eh\'quivar eh\'to, colega!', 28153),
(151021, 'esMX', '¿Qué tenemo\' aquí? ¿Unos humanos débiles y lih\'tos para la matanza?', '¿Qué tenemo\' aquí? ¿Unos humanos débiles y lih\'tos para la matanza?', 28153),
(151020, 'esMX', 'Razdunk dice que no perteneces a este lugar.', '', 28153),
(151019, 'esMX', 'Razdunk te manda saludos.', '', 28153),
(151018, 'esMX', '¡Bah! ¡Vamos, me muero de hambre!', '', 28153),
(151017, 'esMX', 'Mis hermanos y hermanas cuidaban de esta tierra como si fueran un árbol más. Pero eso fue hace mucho tiempo.\n\nAlgunos de nosotros no hemos olvidado ese camino.\n\nLa Arboleda Xiloceniza era uno de nuestros santuarios. Un refugio de la corrupción que poco a poco se infiltra en el Bosque Carmesí.\n\nCon la infestación que crece en las sombras, parece que ese tiempo también ha quedado en el olvido. Ahora veo cómo se desvanece, y lo único que lo mantiene con vida son los recuerdos de los seres que supo nutrir.', '', 28153),
(151016, 'esMX', '¡Loa, guíen mi eh\'pada!', '¡Te enviaré con Bwonsamdi!', 28153),
(151015, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(151014, 'esMX', '¿Algo anda mal en la arboleda?', '¿Algo anda mal en la arboleda?', 28153),
(151013, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t ¡G\'huun invoca las |cFFFF0404|Hspell:267509|h[Mil fauces]|h|r para que lo ayuden!', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t ¡G\'huun invoca las |cFFFF0404|Hspell:267509|h[Mil fauces]|h|r para que lo ayuden!', 28153),
(151011, 'esMX', '', 'Aunque mi poder demorará un tiempo en llegar a su esplendor, la maldición que impedía mi regreso se ha disipado.', 28153),
(151010, 'esMX', '', 'Les doy las gracias, héroes.', 28153),
(151009, 'esMX', 'Alto, ¡¿quiénes son estos intrusos?! ¡Están corrompiendo a Sethraliss!', '', 28153),
(151008, 'esMX', 'Envíame al campo de batalla.', 'Envíame al campo de batalla.', 28153),
(151007, 'esMX', '¡Ah! Su sagrario debe estar más adelante.', '', 28153),
(151006, 'esMX', 'De no ser por ella, el mundo habría caído en el caos.', '', 28153),
(151005, 'esMX', 'Yo estuve allí cuando Sethraliss se sacrificó para detener a Mythrax.', '', 28153),
(151003, 'esMX', 'Aún desde aquí puedo oír a las raíces del Bosque Carmesí, que gritan con ansias de sangre. Jamás esperé que su corrupción llegara tan lejos.', '', 28153),
(151002, 'esMX', '¿Tienes que detenerte a despojar cada cadáver? ¡Sethraliss es nuestro verdadero objetivo!', '', 28153),
(151001, 'esMX', 'Vaya, sí que tienes talento para la destrucción.', '', 28153),
(151000, 'esMX', 'Pero ahora debemos darnos prisa. Siento una oscuridad que busca apoderarse del templo.', '', 28153),
(150999, 'esMX', 'Les agradezco por eliminar esa infestación.', '', 28153),
(150998, 'esMX', 'Se sacrificó para detener a Mythrax... Pero con su muerte, las selvas de Vol\'dun se convirtieron en desiertos.', '', 28153),
(150997, 'esMX', 'Este templo es el lugar de descanso de Sethraliss, una loa poderosa que protegió a mi pueblo de la destrucción hace tiempo.', '', 28153),
(150996, 'esMX', '', '¡Oh, sí! ¡Dales duro!', 28153),
(150995, 'esMX', '', '¡Apuesto diez piezas de oro por $Gel grandote:la grandota;!', 28153),
(150993, 'esMX', 'El tiempo de su renacer ya ha pasado, y me temo que ahora algo impide su regreso.', '', 28153),
(150990, 'esMX', 'Estás abandonando el área designada, se te retirará de tu vehículo.', 'Estás abandonando el área designada, se te retirará de tu vehículo.', 28153),
(150989, 'esMX', 'Un breve respiro. Ojalá dure lo suficiente para que podamos reagruparnos y recuperarnos.', '', 28153),
(150988, 'esMX', '¡Rápido! ¡Nuestros marineros necesitan ayuda! ¡Están heridos y la Horda sigue atacando!', '', 28153),
(150987, 'esMX', 'Que las mareas te favorezcan.', '', 28153),
(150986, 'esMX', '¡Repollos frescos!', '', 28153),
(150985, 'esMX', 'Mantén las velas izadas.', '', 28153),
(150984, 'esMX', 'Buenos vientos, $Uamigo:amiga:.', '', 28153),
(150983, 'esMX', 'Ah, hola.', '', 28153),
(150982, 'esMX', '¿Qué necesitas?', '', 28153),
(150981, 'esMX', 'Un gusto.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'esMX', '¡Es hora de golpear!', '', 28153),
(150979, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(150978, 'esMX', '¡Nadie puede detener a la Horda!', '¡Nadie puede detener a la Horda!', 28153),
(150977, 'esMX', 'Somos la punta de la lanza...', 'Somos la punta de la lanza...', 28153),
(150976, 'esMX', '', 'Ugalazul bwrxil\' qu rax.', 28153),
(150975, 'esMX', 'Derrotado... ¿por $uno:una; de tu especie?', 'Derrotada... ¿por $uno:una; de tu especie?', 28153),
(150974, 'esMX', 'La Horda... prevalecerá...', 'Estas tierras... serán nuestras...', 28153),
(150973, 'esMX', 'Somos la punta... de la lanza...', 'Muero... con honor...', 28153),
(150972, 'esMX', 'Nadie puede... detenernos...', 'Basura... inútil...', 28153),
(150971, 'esMX', '', '¡El abismo... devorará estas tierras!', 28153),
(150970, 'esMX', '', 'No... ¡Le he fallado!', 28153),
(150969, 'esMX', '', '¡Maldigo a los tu clase!', 28153),
(150968, 'esMX', '', '¡Que las aguas... me reciban en su seno!', 28153),
(150967, 'esMX', '', '¡Mi vida... por nuestra reina!', 28153),
(150966, 'esMX', '', 'Emerge... desde las profundidades...', 28153),
(150965, 'esMX', '', 'Nuestra reina prevalecerá...', 28153),
(150964, 'esMX', '¡Oh! Ya vuelvo. Por favor, ¡no me delates!', '¡Ah! Ya vuelvo. Por favor, ¡no me delates!', 28153),
(150963, 'esMX', 'Serás un oponente digno.', 'Serás un oponente digno.', 28153),
(150962, 'esMX', '¡No metas tus narices en lo que no te incumbe!', '¡No metas tus narices en lo que no te incumbe!', 28153),
(150961, 'esMX', '¡El abismo... devorará estas tierras!', '', 28153),
(150960, 'esMX', 'No... ¡Le he fallado!', '', 28153),
(150959, 'esMX', '¡Maldigo a los tu clase!', '', 28153),
(150958, 'esMX', '¡Que las aguas... me reciban en su seno!', '', 28153),
(150957, 'esMX', '¡Mi vida... por nuestra reina!', '', 28153),
(150956, 'esMX', 'Jamás... la detendrán...', '', 28153),
(150955, 'esMX', 'Emerge... desde las profundidades...', '', 28153),
(150954, 'esMX', 'Nuestra reina prevalecerá...', '', 28153),
(150953, 'esMX', '', 'Si evitamo\' que aseguren una posición, nueh\'tro hogar estará a salvo. Que Gonk te otorgue una dulce recompensa por llevar a cabo su venganza.', 28153),
(150952, 'esMX', '', 'Dejar que la Alianza asegure una posición en Zandalar sería desah\'troso. Salva lo que puedas, pero no tengas piedad con la Alianza.', 28153),
(150951, 'esMX', 'Si quieres que algo salga bien…', '', 28153),
(150950, 'esMX', '¡Tu muerte me traerá honor!', '¡Este es tu fin!', 28153),
(150949, 'esMX', '¡Mátenlos a todos!', '¡Lok\'tar!', 28153),
(150948, 'esMX', '¡Serás $Uun oponente digno:una oponente digna;!', '¡No tomen prisioneros!', 28153),
(150947, 'esMX', 'Por la... Horda...', 'Por la... Horda...', 28153),
(150946, 'esMX', 'Ah, ¡qué belleza! Te ganaste tu paga.', '', 28153),
(150945, 'esMX', '', '¿Se atreven a interferir en mis asuntos? ¿Cómo osan oponerse a mi voluntad?', 28153),
(150944, 'esMX', 'Prepárense. ¡La cacería de esta bestia será emocionante!', '', 28153),
(150943, 'esMX', '¡Nos llevó hasta su guarida!', '', 28153),
(150942, 'esMX', 'Mmm... El rastro lleva a las profundidades de este pasaje hediondo.', '', 28153),
(150941, 'esMX', 'La perla no está aquí. Quizás el esbirro de Azshara era más astuto de lo que parecía.', '', 28153),
(150940, 'esMX', '¡Pronto, tu cabeza decorará mi pared!', '', 28153),
(150939, 'esMX', 'Reconcíliate con tu reina, ¡porque tu vida acaba aquí!', '', 28153),
(150938, 'esMX', '¿Intrusos? Tendré que arrojar sus cuerpos a las profundidades oscuras, donde sufrirán por toda la eternidad.', '', 28153),
(150937, 'esMX', '¡El loa es demasiado poderoso! ¡Regresen a la seguridad del océano! ¡Esta batalla está perdida!', '', 28153),
(150936, 'esMX', '¡Destruyan el templo! Rompan todo. ¡Que caigan las estatuas! ¡Todos se arrodillarán ante nuestra reina!', '', 28153),
(150935, 'esMX', 'No me importa qué poderes tengas, ¡serás nuestra próxima víctima!', '', 28153),
(150934, 'esMX', 'Bienvenidos, intrusos. ¡Llegan justo a tiempo para conocer el verdadero poder!', '', 28153),
(150933, 'esMX', 'Una muerte impecable... Pero la verdadera presa se retiró al santuario.', '', 28153),
(150932, 'esMX', '', '¡La reina ha ordenado que mueras!', 28153),
(150931, 'esMX', '', '¡Gloria a Azshara!', 28153),
(150930, 'esMX', '', '¡Nuestro destino está cerca!', 28153),
(150929, 'esMX', '', '¡Tendré la gloria de matarte!', 28153),
(150928, 'esMX', '', '¡Nadie puede oponerse a la reina Azshara!', 28153),
(150927, 'esMX', '', '¡El Anillo de las mareas es nuestro!', 28153),
(150926, 'esMX', '', '¡No puedes comprender nuestro poder!', 28153),
(150925, 'esMX', 'Cállate. Tú no usa\' zapatos.', '', 28153),
(150924, 'esMX', '', '¿Un solo par? Me vendrían bien unos zapato\' nuevos.', 28153),
(150923, 'esMX', '¡Paciencia, hermana!', '', 28153),
(150922, 'esMX', '', 'Nunca se darán cuenta. Nadie dice que ataquemo\' el campamento, ¡pero a nadie le molestará que nos llevemo\' algunos!', 28153),
(150921, 'esMX', '¡La reina ha ordenado que mueras!', '', 28153),
(150920, 'esMX', '¡Gloria a Azshara!', '', 28153),
(150919, 'esMX', '¡Nuestro destino está cerca!', '', 28153),
(150918, 'esMX', '¡Tendré la gloria de matarte!', '', 28153),
(150917, 'esMX', '¡Nadie puede oponerse a la reina Azshara!', '', 28153),
(150916, 'esMX', '¡El Anillo de las mareas es nuestro!', '', 28153),
(150914, 'esMX', 'Tenemo\' que quedarnos aquí. Si escapas y hace\' que nos maten, no habrá nadie para contar lo que sucedió.', '', 28153),
(150913, 'esMX', '¡No puedes comprender nuestro poder!', '', 28153),
(150912, 'esMX', '¡¡¡Mis repollos!!!', '', 28153),
(150911, 'esMX', 'Hora de atrapar a otro grifo. ¡Sube!', '', 28153),
(150908, 'esMX', 'El trabajo de un rabalero no siempre es glamoroso, pero paga bien.', '', 28153),
(150907, 'esMX', 'Tenemos un gran pedido de monturas para grifos, pero nos faltan pieles. ¡A trabajar!', '', 28153),
(150906, 'esMX', 'Si hay menos en las alturas, menos bajarán por la montaña. ¡Bien hecho!', '', 28153),
(150905, 'esMX', 'Los números de los wendigo han aumentado sin control en el glaciar. ¡Sube y encárgate de la situación!', '', 28153),
(150904, 'esMX', 'Con el poder de la perlazur, nuestras flotas serán imparables.', '', 28153),
(150903, 'esMX', '', '¿Acaso crees que estoy hecha de oro?', 28153),
(150902, 'esMX', 'Lo siento, jefe...', '', 28153),
(150901, 'esMX', '', '¡Estúpido patán! ¡Esas eran costosas!', 28153),
(150900, 'esMX', 'Gracias, héroes. Han devuelto la esperanza al pueblo kultirano.', '', 28153),
(150899, 'esMX', 'Siento que la presencia oscura retrocede. El santuario será restaurado.', '', 28153),
(150898, 'esMX', '¡No escuchen sus susurros! ¡Este horror tratará de corromper sus almas!', '', 28153),
(150897, 'esMX', '¡Por la Madre de las mareas!', '', 28153),
(150896, 'esMX', 'Cuidado, héroes. Un mal invisible aún acecha en la oscuridad. Debemos continuar para eliminar su influencia del santuario.', '', 28153),
(150895, 'esMX', 'Algo no está bien. La oscuridad persiste.', '', 28153),
(150894, 'esMX', 'Se ha rebelado contra la marea, maestro, y ahora yace debajo de ella.', '', 28153),
(150893, 'esMX', 'Entonces tendré que arrojar sus cuerpos a las profundidades oscuras, donde sufrirán por toda la eternidad.', '', 28153),
(150892, 'esMX', 'Nunca.', '', 28153),
(150891, 'esMX', 'Por última vez, únete a mí o muere.', '', 28153),
(150890, 'esMX', '¡Idiota! Debemos regresar al mar, ¡y la reina Azshara nos concederá el poder necesario!', '', 28153),
(150889, 'esMX', '¡Maestro! ¡Detenga esta locura de inmediato! ¡La flota kultirana no puede caer en la oscuridad!', '', 28153),
(150888, 'esMX', '', 'Parece que tienes invitados, Lord Canto Tormenta.', 28153),
(150887, 'esMX', '', 'Muéstrale respeto y déjalo hablar... Si tenemo\' suerte, no te arrojará de la cima de la pirámide.', 28153),
(150886, 'esMX', 'La flota kultirana ya casi es suya, mi reina.', '', 28153),
(150885, 'esMX', 'Mar al mar, cenizas a las cenizas, mareas a las mareas. Que sus almas surquen arroyos pacíficos.', '', 28153),
(150884, 'esMX', '¡Rápido, héroes! ¡Deténganlos o perderemos la flota!', '', 28153),
(150883, 'esMX', 'Discos titánicos activados: Iniciando protocolo de corrupción', 'Discos titánicos activados: Iniciando protocolo de corrupción', 28153),
(150882, 'esMX', 'Discos titánicos activados: Iniciando protocolo de engaño', 'Discos titánicos activados: Iniciando protocolo de engaño', 28153),
(150881, 'esMX', '', 'Una vez que completemos el ritual, ¡la flota kultirana le pertenecerá a la reina Azshara!', 28153),
(150880, 'esMX', 'Bienvenido, hermano Pike. Llegas justo a tiempo para presenciar nuestra victoria.', '', 28153),
(150879, 'esMX', 'Canto Tormenta ha corrompido este lugar sagrado. Debemos proseguir y anular sus obras nefastas.', '', 28153),
(150878, 'esMX', '¿Voces?', '¿Voces?', 28153),
(150877, 'esMX', 'Cuidado. Una presencia oscura nos observa.', '', 28153),
(150876, 'esMX', 'Hay que purificar el mal de Lord Canto Tormenta del santuario, héroes.', '', 28153),
(150875, 'esMX', '', '¡Maestro! ¡No me abandone\'! ¡Nooooo!', 28153),
(150874, 'esMX', '', '¿De vera\' crees que puedes resih\'tirte al poder de G\'huun? ¡Sufre por tu arrogancia!', 28153),
(150873, 'esMX', '¡Oigo voces en el lodo!', '¡Oigo voces en el lodo!', 28153),
(150872, 'esMX', '', 'Nos han destrozado.\n\nLa luz de Rezan no\' ha abandonado. Solo un puñado de lo\' que siguieron al gran rey de los loa aún conservan algo de poder, e incluso ello\' son sospechoso\'.\n\nNuestra vida era pura devoción. ¿Qué haremo\' ahora?', 28153),
(150871, 'esMX', '¡Es hora de hacer algunas mejoras!', '', 28153),
(150870, 'esMX', 'Bien, me cansé de jugar limpio..', '', 28153),
(150869, 'esMX', '¡Excelente! Nuestros soldados le darán un buen uso a esos suministros. ¡Buen trabajo!', '', 28153),
(150868, 'esMX', 'Nuestros exploradores informan que un grupo de asalto de trols de sangre ha capturado un bote de carga zandalari. Mátalos y quédate con los suministros.', '', 28153),
(150867, 'esMX', '¡Atentos, muchachos! ¡Parece que tenemos intrusos!', '', 28153),
(150866, 'esMX', '¡Sí! ¡Tu misión es encontrar un buen estilista!', '', 28153),
(150865, 'esMX', '', '¡$n! ¡Eh, $n! ¡Tenemos una misión para ti!', 28153),
(150864, 'esMX', '¡Salta!', '¡Salta!', 28153),
(150863, 'esMX', 'No te puede\' ocultar de Bwonsamdi, criaturita.', '', 28153),
(150862, 'esMX', 'Algo en ti me resulta extraño... Ah, el hedor de $Uun cazador:una cazadora; de demonio\'.', '', 28153),
(150861, 'esMX', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando a tu comandante!', 28153),
(150860, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Paso Valeroso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Paso Valeroso!', 28153),
(150859, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Granovel!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Granovel!', 28153),
(150858, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de Elementos!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando el Círculo de Elementos!', 28153),
(150857, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Alto Pedestal!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Alto Pedestal!', 28153),
(150856, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a¡Están atacando Cruce Redilnorte!', 28153),
(150855, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Están atacando la Mina Mostacho Seco!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a¡Están atacando la Mina Mostacho Seco!', 28153),
(150854, 'esMX', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Están atacando Cresta Hachazo!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a¡Están atacando Cresta Hachazo!', 28153),
(150853, 'esMX', '¡Tenemos que alcanzar a los exploradores más adelantados y exterminar a estas plagas de inmediato!', '¡Tenemos que alcanzar a los exploradores más adelantados y exterminar a estas plagas de inmediato!', 28153),
(150852, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Paso Valeroso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Paso Valeroso!', 28153),
(150851, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Granovel!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Granovel!', 28153),
(150850, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de Elementos!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido el Círculo de Elementos!', 28153),
(150849, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Alto Pedestal!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Alto Pedestal!', 28153),
(150848, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Cruce Redilnorte!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a¡Hemos perdido Cruce Redilnorte!', 28153),
(150847, 'esMX', 'No estás soñando, colega.', '', 28153),
(150846, 'esMX', 'Oh, los espíritu\' te acompañan ahora, colega.', '', 28153),
(150845, 'esMX', 'Ah, $Uun:una; Caballero de la muerte. ¡Debería\' venir a ver MI portón de la muerte!', '', 28153),
(150844, 'esMX', '¡Tus tierras serán las próximas en caer!', '¡Tus tierras serán las próximas en caer!', 28153),
(150843, 'esMX', '¡No puedes evitar que las arenas se esparzan!', '¡No puedes evitar que las arenas se esparzan!', 28153),
(150842, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Hemos perdido Mina Mostacho Seco!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a¡Hemos perdido Mina Mostacho Seco!', 28153),
(150841, 'esMX', '¡Ja! No lograh\'te escapar rodando de esa.', '', 28153),
(150840, 'esMX', '¡Lo dominaremos todo!', '¡Lo dominaremos todo!', 28153),
(150839, 'esMX', '¡Los erradicaremos como insectos!', '¡Los erradicaremos como insectos!', 28153),
(150838, 'esMX', '¿Acaso intentas fingir tu muerte, colega? Qué pena...', '', 28153),
(150837, 'esMX', '¡Por el emperador!', '¡Por el emperador!', 28153),
(150836, 'esMX', 'Creo que has seguido la lu\' incorrecta, colega.', '', 28153),
(150835, 'esMX', 'Esa traslación no te ha llevado muy lejo\', ¿verdad?', '', 28153),
(150834, 'esMX', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Cresta Hachazo!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a¡Hemos perdido Cresta Hachazo!', 28153),
(150833, 'esMX', '¡Sí! Luce terrible, ¡pero definitivamente es diferente!', '', 28153),
(150832, 'esMX', '', 'Bueno, $Gese aventurero:esa aventurera; sí que es diferente a $Glos:las; demás.', 28153),
(150831, 'esMX', 'Creo que es $Gotro:otra; de esos \"adalides\". ¡Por el olor, parece que alguien se está quemando vivo!', '', 28153),
(150830, 'esMX', '', '¡¿Pero qué es ese olor?!', 28153),
(150829, 'esMX', '', 'Waldorf, eso no es un jabaespín, ¡es solo $Gotro:otra; de esos \"adalides\"!', 28153),
(150828, 'esMX', 'Jaja, toda esa armadura no fue de mucha ayuda, ¿verdad?', '', 28153),
(150827, 'esMX', '¡Eh, Statler, pásame mi espada! ¡Se acerca un jabaespín por el camino!', '', 28153),
(150826, 'esMX', 'Ohhhh, ¿qué ha pasado? ¿Perdiste tu brillante piedrita de alma?', '', 28153),
(150825, 'esMX', '', '¡Tienes razón! No luce tan mal... ¡Luce pésimo!', 28153),
(150824, 'esMX', '¿Ves lo que lleva puesto $n? ¡No luce tan mal, eh!', '', 28153),
(150823, 'esMX', 'Ah, ¿viene\' a pasar un rato con Bwonsamdi?', '', 28153),
(150822, 'esMX', '¡Jaja! ¡Esa fue una muerte impresionante!', '', 28153),
(150821, 'esMX', 'Podría decirse que luce peor que antes...¡Pero creo que siempre tuvo un aspecto horrible!', '', 28153),
(150820, 'esMX', '', 'Vaya, vaya, vaya. ¡Miren lo que trajo el saurolisco! ¡Es $n!', 28153),
(150819, 'esMX', '', 'Sí, ¿dónde lo conseguiste? ¡¿De un trogg?!', 28153),
(150818, 'esMX', '¡Eh, Statler, mira el equipo de $n!', '', 28153),
(150817, 'esMX', '¡Creo que sí! ¡Uf, huele peor de lo que imaginé! ¡Ja!', '', 28153),
(150816, 'esMX', '', '¡Eh, Waldorf! ¿Acaso $Geste es el \"famoso\":esta es la \"famosa\"; $r que apareció con Jaina?', 28153),
(150815, 'esMX', '', '¡Sí! ¡Hueles horrible! ¡Ja ja ja!', 28153),
(150814, 'esMX', '¡Eh, tú! ¡Sí, tú, $Gel:la; $r con esa cara!', '', 28153),
(150813, 'esMX', '¡He visto caballos con mejores transfiguraciones!', '', 28153),
(150812, 'esMX', '', '¡Eh, $n! ¿Te parece que ese yelmo combina con esas botas?', 28153),
(150811, 'esMX', 'Me gustaría saber algo más.', 'Me gustaría saber algo más.', 28153),
(150810, 'esMX', '', 'Los antiguos drust. Su odio por los kultiranos ha trascendido sus vidas mortales. Incluso sus ecos del más allá aborrecen nuestra existencia. \n\nSiento lástima por el idiota que los haya invocado.', 28153),
(150809, 'esMX', '¿Los muertos vengativos?', '¿Los muertos vengativos?', 28153),
(150808, 'esMX', '¡Serás $Uerradicado:erradicada;!', '', 28153),
(150807, 'esMX', '', 'La magia que usan estas brujas es antigua y emana una oscuridad poderosa. Han corrompido la vida salvaje para que las obedezca, y han alterado el equilibrio. Sus creaciones retorcidas albergan los espíritus de los muertos vengativos.', 28153),
(150806, 'esMX', '', '¡Hay placer en la cacería y satisfacción en la venganza!', 28153),
(150805, 'esMX', '', 'Estos traidores asesino\' de loa aún buscan mancillar el Templo de Rezan. El viejo K\'zlotec les enseñará lo que sucede cuando alguien le eh\'cupe la cara al loa de reyes.', 28153),
(150804, 'esMX', 'Naza bul rexil qalic ul\'.', '', 28153),
(150803, 'esMX', '¿Qué le sucedió al bosque?', '¿Qué le sucedió al bosque?', 28153),
(150802, 'esMX', '¡Ca\' lish!', '', 28153),
(150801, 'esMX', '', 'Tal vez lo encuentres en una de las cuevas cercanas. Buena suerte, $n.', 28153),
(150800, 'esMX', '', 'Acechador Glauco está débil, pero es solo cuestión de tiempo para que reanude la cacería.', 28153),
(150799, 'esMX', '¡Ug\' bwafa qilikx za!', '', 28153),
(150798, 'esMX', 'Siempre te recibiremos con los brazos abiertos.', '', 28153),
(150797, 'esMX', 'Pobre criaturita, ¿necesita\' que el viejo Bwonsamdi te ayude?', '', 28153),
(150796, 'esMX', 'Los ranishu han envenenado a mis crías. Ahora se sienten débiles y se aferran a la vida. Sálvalas con mi poder, como me has salvado a mí.', '', 28153),
(150795, 'esMX', 'Hul bala miz rilakich...', '', 28153),
(150794, 'esMX', 'Tsk, tsk. No eh\'peraba verte por aquí tan pronto.', '', 28153),
(150793, 'esMX', '¡Lok\'tar ogar!', '¡Lok\'tar ogar!', 28153),
(150792, 'esMX', '¡POR LA HORDA!', '¡POR LA HORDA!', 28153),
(150791, 'esMX', '¡Soy superior!', '', 28153),
(150790, 'esMX', 'Soldados de la Horda, ¡preparen sus espadas! ¡Hoy marchamos contra los kaldorei!', '', 28153),
(150789, 'esMX', 'Déjame adivinar... ¿Demasiada presión para ti?', '', 28153),
(150788, 'esMX', '¡Il qul zerakish!', '', 28153),
(150787, 'esMX', 'Listo, estás $garreglado:arreglada;. Ve a Orgrimmar y habla con Sylvanas para comenzar tus aventuras épicas.', '', 28153),
(150786, 'esMX', 'Empecé Nazmir pero no puedo empezar Zuldazar. Arréglame, por favor.', 'Empecé Nazmir pero no puedo empezar Zuldazar. Arréglame, por favor.', 28153),
(150785, 'esMX', '¿Qué necesitas?', '', 28153),
(150784, 'esMX', 'Nos sería muy útil mantener la situación en ese estado.', '', 28153),
(150783, 'esMX', 'Si mantiene a esos partidarios de Tarjasenda a la defensiva, recibirá una generosa recompensa.', '', 28153),
(150781, 'esMX', 'Reúna a lo mejor de su tripulación y zarpe hacia el Muelle Arrumaje. Desde allí deberá robar, saquear y atracar todas las tierras para llenar nuestras arcas con sus suministros.', '', 28153),
(150779, 'esMX', 'Capitán Puñoplomizo, nuestro benefactor me ha informado que la casa Tarjasenda está sumida en el caos.', '', 28153),
(150778, 'esMX', '¿Por qué no estás en tu puesto?', '¿Por qué no estás en tu puesto?', 28153),
(150777, 'esMX', 'Deseo elegir a Kimbul como mi loa.', 'Deseo elegir a Kimbul como mi loa.', 28153),
(150776, 'esMX', '¡El mismísimo Corazón de Azeroth!', '', 28153),
(150775, 'esMX', '<Este santuario fue construido como tributo a Kimbul, señor de las bestias.>', '<Este santuario fue construido como tributo a Kimbul, señor de las bestias.>', 28153),
(150773, 'esMX', '¿Sí?', '¿Sí?', 28153),
(150772, 'esMX', 'Yo seré su portavoz, pero tú eres su adalid. Y necesita que luches por ella.', '', 28153),
(150771, 'esMX', 'Azeroth te invoca, adalid. Te ofrece un regalo... un regalo nacido de su propia esencia.', '', 28153),
(150770, 'esMX', '¡Libertad! ¡Debemo\' llegar a la seguridad del templo interior!', '¡Libertad! ¡Debemo\' llegar a la seguridad del templo interior!', 28153),
(150769, 'esMX', '¿Qué... qué me sucedió?', '¿Qué... qué me sucedió?', 28153),
(150768, 'esMX', '', '¡G\'huun! ¡Dame tu poder!', 28153),
(150767, 'esMX', 'Te debo una en el Otro Lado, colega.', 'Te debo una en el Otro Lado, colega.', 28153),
(150766, 'esMX', '', '¡El fin se acerca!', 28153),
(150765, 'esMX', '', '¡Supliquen piedad!', 28153),
(150764, 'esMX', '', '¡Todo\' servirán al maestro!', 28153),
(150763, 'esMX', 'Por fin, ¡libre de esos hueso\' malditos!', 'Por fin, ¡libre de esos hueso\' malditos!', 28153),
(150762, 'esMX', 'Ya es hora de quitarle sus riqueza\' a Harlan Sweete.', '', 28153),
(150761, 'esMX', 'Discos titánicos activados: Iniciando protocolo de caos', 'Discos titánicos activados: Iniciando protocolo de caos', 28153),
(150760, 'esMX', '¡Lo devolveré! ¡Lo juro!', '¡Lo devolveré! ¡Lo juro!', 28153),
(150759, 'esMX', 'Y ese fue el fin de Harlan Sweete. Ahora, podemo\' salir a conquistar los mare\'.', '', 28153),
(150758, 'esMX', '¡Aaaah!', '¡Aaaah!', 28153),
(150757, 'esMX', '¡Ey! ¡Yo robé eso en buena ley!', '¡Yo robé eso en buena ley!', 28153),
(150756, 'esMX', '¡Ja! ¡Sabía que debía apostar por ti!', '', 28153),
(150755, 'esMX', '¡Dispérsense!', '¡Dispérsense!', 28153),
(150754, 'esMX', '¡Ah! ¡Forastero! ¡Mal agüero!', '¡Ah! ¡Forastero! ¡Mal agüero!', 28153),
(150753, 'esMX', '¿Qué dices si nos ganamo\' algo de oro partiendo cráneos?', '', 28153),
(150752, 'esMX', 'El acceso a la isla está bloqueado hasta que terminen la\' celebraciones en el foso de pelea.', '', 28153),
(150750, 'esMX', 'Buen trabajo. Pero hacer que Harlan conozca el filo de tu eh\'pada será más difícil.', '', 28153),
(150749, 'esMX', 'Si consigue\' una invitación, te será más sencillo. O puedes entrar repartiendo golpes contra los tre\' piratas más temibles. Tú decides, $Uricachón:ricachona;.', '', 28153),
(150748, 'esMX', '¡Ni siquiera lo\' peces beben tanto como las rata\' de sentina! Sígueles el ritmo a esto\' animales y la capitana Eudora te invitará a esa reunión.', '', 28153),
(150747, 'esMX', 'A lo\' Camorristas dientenegro les encanta pelear. Si logra\' partirles la mandíbula, el capitán Raúl sin duda te invitará a la reunión.', '', 28153),
(150746, 'esMX', 'Supe que habrá una reunión de capitane\'. Si logramos entrar, cortaremos todas la\' cabezas de esta hidra de una vez.', '', 28153),
(150745, 'esMX', 'Esta guerra no se va a ganar por sí sola. ¡Tenemos trabajo por hacer!', '', 28153),
(150744, 'esMX', 'Luego, nos encargaremo\' de Harlan Sweete de una vez por todas.', '', 28153),
(150743, 'esMX', 'Eh\'te es el plan. Expulsa a los surcamar, purga a las rata\' de sentina, destroza a los dientenegro y desbarata a lo\' mareaférrea.', '', 28153),
(150742, 'esMX', 'Si lo logra, controlará una flota que representará una amenaza contra nuestro\' intereses marítimos.', '', 28153),
(150741, 'esMX', 'Harlan usa a lo\' mareaférrea para unir al resto de las tripulacione\' pirata bajo su estandarte.', '', 28153),
(150740, 'esMX', 'Gracia\' por liberarme. Siento el llamado de Bwonsamdi deh\'de el interior del templo. Vamos.', 'Gracia\' por liberarme. Siento el llamado de Bwonsamdi deh\'de el interior del templo. Vamos.', 28153),
(150739, 'esMX', 'Creí que sería un eh\'queleto horripilante por siempre. ¡Debo regresar al templo ya mismo!', 'Creí que sería un eh\'queleto horripilante por siempre. ¡Debo regresar al templo ya mismo!', 28153),
(150738, 'esMX', 'Regresa al templo de... Bwonsamdi... rápido...', 'Regresa al templo de... Bwonsamdi... rápido...', 28153),
(150737, 'esMX', 'Mis sentido\' están adormecidos por el ritual... Ayúdame a llegar a las eh\'caleras del templo.', 'Mis sentido\' están adormecidos por el ritual... Ayúdame a llegar a las eh\'caleras del templo.', 28153),
(150736, 'esMX', '¡Gracia\', colega! Me desvanezco. Ayúdame a llegar al templo de Bwonsamdi.', '¡Gracia\', colega! Me desvanezco. Ayúdame a llegar al templo de Bwonsamdi.', 28153),
(150735, 'esMX', '¿Qué e\' lo que tienes ahí, $Uricachón:ricachona;? ¿Un abalorio brillante para el viejo Jani? Acércalo…', '', 28153),
(150734, 'esMX', '¡Soy el único por aquí que sabe de matemática! Así que controlo los gastos y me aseguro de que nadie meta la mano donde no debe.', '', 28153),
(150733, 'esMX', 'Los peones son el pilar de esta guerra.', '', 28153),
(150732, 'esMX', 'Intenta regresar con vida.', '', 28153),
(150731, 'esMX', 'Cuídate de los trols de sangre.', '', 28153),
(150730, 'esMX', 'Ten cuidado. ¡Te necesito con vida!', '', 28153),
(150729, 'esMX', 'Son tiempos duros para Zandalar.', '', 28153),
(150728, 'esMX', 'Agh. ODIO a los trols de sangre.', '', 28153),
(150727, 'esMX', '¿Cómo saldremo\' de esta?', '', 28153),
(150726, 'esMX', '¡Pf! La Horda recibió su merecido. Llevaré este artilugio a Alto de Arom y averiguaré si le puede ser útil a alguien. Buen trabajo.', '', 28153),
(150719, 'esMX', 'Estoy listo para defender a Zandalar.', 'Estoy lista para defender a Zandalar.', 28153),
(150718, 'esMX', '¡Por aquí! Nuestras fuerzas terrestres esperan abajo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'esMX', '', 'El bosque agoniza y se lamenta. ¿Lo oyes?', 28153),
(150716, 'esMX', '¡Vamos a casa!', '¡Vamos a casa!', 28153),
(150715, 'esMX', '¡Parece que no necesitah\'te mi ayuda! ¡Volvimos apena\' pudimo\'!', '', 28153),
(150714, 'esMX', 'Dayrl y yo conocemos estas colinas desde siempre. Podemos sobrevivir aquí mucho más tiempo que cualquiera de la Horda.', '', 28153),
(150713, 'esMX', '¿Quieres regresar a Zuldazar y morir, o quedarte aquí para que te maten los raptores?', '¿Quieres regresar a Zuldazar y morir, o quedarte aquí para que te maten los raptores?', 28153),
(150712, 'esMX', 'No iré a Vol\'dun, ¿entiendes? ¡Voy a hacer mi vida en la ciudad!', '', 28153),
(150711, 'esMX', '', '¡Tortugas frescas, Emma! ¡Ahora debes darme mi parte!', 28153),
(150710, 'esMX', '¿Qué e\' lo que tienes ahí, $Uricachón:ricachona;? ¿Un abalorio brillante para el viejo Jani? Acércalo…', '', 28153),
(150709, 'esMX', '', '¡Xul krass qi\' UN skush!', 28153),
(150708, 'esMX', '', '¡Skitsh qi\'uthik illith!', 28153),
(150707, 'esMX', '', 'La sangre gotea por las tablas del piso.', 28153),
(150706, 'esMX', '', '¿Por qué no me acompañan en el sótano para admirar la belleza de la muerte?', 28153),
(150705, 'esMX', '', 'Ay, no... parece que han asesinado a todo mi servicio.', 28153),
(150704, 'esMX', '<Ves la imagen de un joven trol observando lo que parece ser un cortejo fúnebre. Parece perplejo y distante.>', '<Ves la imagen de un joven trol observando lo que parece ser un cortejo fúnebre. Parece perplejo y distante.>', 28153),
(150703, 'esMX', '¡Aléjate de la puerta! No es seguro.', '¡Aléjate de la puerta! No es seguro.', 28153),
(150702, 'esMX', 'Kua\'fon te gruñe. ¡Regresa con Raal o caerás de tu montura!', 'Kua\'fon te gruñe. ¡Regresa con Raal o caerás de tu montura!', 28153),
(150701, 'esMX', '', '¡Retuércete en agonía!', 28153),
(150700, 'esMX', '', '¡Desgarraré sus almas!', 28153),
(150699, 'esMX', '', '¡Con esa cosa mi pelo se volvió verde!', 28153),
(150698, 'esMX', '', '¡Sus gritos resonarán por toda la eternidad!', 28153),
(150697, 'esMX', '', '¡Yo lo controlo todo!', 28153),
(150696, 'esMX', '', '¡Kiro, aún están vivos! No podemos dejarlos aquí...', 28153),
(150695, 'esMX', '¡Rápido, toma lo que puedas! Deja los cuerpos para los buitres.', '', 28153),
(150694, 'esMX', 'Morirás en estas dunas...', '', 28153),
(150693, 'esMX', '¡Intrusos!', '', 28153),
(150692, 'esMX', 'Cumple con tu parte, general, y yo cumpliré con la mía.', '', 28153),
(150691, 'esMX', 'Tenemo\' que acelerar las cosa\'. El rey tiene visitas entrometida\'... que podrían ser un problema.', '', 28153),
(150690, 'esMX', '', 'Había un guardia en Tol Dagor, ¡y era igualito a ti!', 28153),
(150689, 'esMX', '', '¿Crees que podrías ayudarme a escabullirme en el \nBanco de Boralus?', 28153),
(150688, 'esMX', '', '¿Te preocupa la radiación?', 28153),
(150687, 'esMX', '', '¿Tienes alguna habilidad útil? Como hacer falsificaciones o abrir cajas fuertes...', 28153),
(150686, 'esMX', '', 'La tormenta ha cedido y vuelvo a ser yo. Gracias.', 28153),
(150685, 'esMX', '', 'Sus vidas fueron insignificantes. La muerte se llevará sus recuerdos.', 28153),
(150684, 'esMX', '', '¡Profanadores!', 28153),
(150683, 'esMX', '', '¡Restáurenme y las desactivaré!', 28153),
(150682, 'esMX', '', 'El maleficio está destruido, ¡pero las defensas del templo se han activado!', 28153),
(150681, 'esMX', '', '¡Su tormento será eterno!', 28153),
(150680, 'esMX', '¡Disfrutaré al ver cómo te fríes!', '', 28153),
(150679, 'esMX', '¡Muere, alimaña!', '', 28153),
(150678, 'esMX', '¡Golpe tajante!', '', 28153),
(150677, 'esMX', '¡A cercenar!', '', 28153),
(150676, 'esMX', '¡Perdedor!', '', 28153),
(150675, 'esMX', '¡Se quiebran como el vidrio!', '', 28153),
(150674, 'esMX', 'No es que tenga miedo o algo así. ¡Simplemente no tengo ganas!', '', 28153),
(150673, 'esMX', '¡Nadie puede resistirse a nuestro imperio!', '', 28153),
(150672, 'esMX', '¡Por supuesto que puedo subir, no soy un debilucho!', '', 28153),
(150671, 'esMX', '¡No necesito demostrarte nada!', '', 28153),
(150670, 'esMX', 'Vamos, Abraham. He visto a niños hacer esto.', '', 28153),
(150669, 'esMX', 'Vamos, no es tan alta.', '', 28153),
(150668, 'esMX', 'Apuesto a que no puedes subir.', '', 28153),
(150667, 'esMX', '¡No es gracioso! ¡Bájame de aquí!', '', 28153),
(150666, 'esMX', '¡Deja de burlarte y ayúdame!', '', 28153),
(150665, 'esMX', '¡Solo ayúdame a bajar!', '', 28153),
(150664, 'esMX', '¡Huye mientras puedas!', '¡Huye mientras puedas!', 28153),
(150663, 'esMX', '¡No podrán conmigo!', '¡No podrán conmigo!', 28153),
(150662, 'esMX', '¡Pueden quedarse con mi parte!', '¡Pueden quedarse con mi parte!', 28153),
(150661, 'esMX', '¡Mataremos a todos los Mareaférrea!', '¡Mataremos a todos los Mareaférrea!', 28153),
(150660, 'esMX', '¡No podrán conmigo!', '¡No podrán conmigo!', 28153),
(150659, 'esMX', '¡No trabajo para piratas!', '¡No trabajo para piratas!', 28153),
(150658, 'esMX', '', '¡Te aplastaré la cabeza!', 28153),
(150657, 'esMX', '¿Te estás divirtiendo ahí colgado? ¡Ja ja!', '', 28153),
(150656, 'esMX', '¿Tienes problemas, Abraham?', '', 28153),
(150655, 'esMX', '¡Idiota! ¡Estás atascado!', '', 28153),
(150654, 'esMX', 'Sethraliss dio su vida para salvar nuestro mundo. Si Mythrax regresa, su valeroso sacrificio habrá sido en vano...', '', 28153),
(150653, 'esMX', 'Incluso en la muerte, la esencia de Mythrax perdura. Temo por el destino de nuestro mundo si se levanta una vez más...', '', 28153),
(150652, 'esMX', 'Hay una presencia oscura por aquí. Tenemos que permanecer alertas...', '', 28153),
(150651, 'esMX', '', 'Comienzan su camino a la grandeza.', 28153),
(150650, 'esMX', '', 'Es hora de poner a prueba a estos pequeño\' para que empiecen a cumplir con su destino. Aliéntalo\' a que vuelvan al Salón de las Castas.', 28153),
(150649, 'esMX', '¡Bien! Con esas criaturas podremos fabricar flechas para nuestros cazadores y revestimientos para nuestras armaduras.', '', 28153),
(150648, 'esMX', 'Es difícil establecer una línea de suministros para el pantano. Si queremos seguir con esta guerra, necesitamos que consigas materiales entre la fauna y flora local.', '', 28153),
(150647, 'esMX', 'Ah, eso servirá. Espero que esas criaturitas tan resbaladizas no te hayan dado muchos problemas.', '', 28153),
(150646, 'esMX', '¿Un enjambre de calapinosos? ¡Qué curioso que aparecieran justo cuando se me acabó la tinta! Toma este pergamino, úsalo para succionarles esa preciada tinta.', '', 28153),
(150645, 'esMX', '', 'Parece que esta tecnología será muy útil para nuestras fuerzas. ¡Bien hecho!', 28153),
(150644, 'esMX', '', 'Mekkatorque ha mejorado su tecnología D.R.O.N. y necesita evaluar sus capacidades en el campo. Nos dijeron que hay muchos trols de sangre escondidos cerca. ¡Búscalos y destrúyelos!', 28153),
(150643, 'esMX', '<¡Súbete!>', '<¡Súbete!>', 28153),
(150642, 'esMX', '<Kua\'fon gira la cabeza para examinarte y lanza un grito agudo a modo de saludo.>\n\n¡Riiii!', '', 28153),
(150641, 'esMX', '', 'Pequeños y asquerosos monstruos.', 28153),
(150640, 'esMX', '', 'Los ranishu tienen varios estómagos, así que no dejes de cavar después de encontrar al primero.', 28153),
(150639, 'esMX', 'Le lleva un tiempo volver a la percha, porque, bueno, ya sabes, no puede volar. Seguro eh\'tá bien.$b$bVuelve a fijarte en un rato, y verá\' que ya está de regreso.', '', 28153),
(150638, 'esMX', 'Bien, ya me ocupé de eso. Por cierto, de nada.$b$bMe di cuenta de que se veía un poco trih\'te. ¡Llévalo a hacer otro vuelo! Le vendría bien un poco de ejercicio.', '', 28153),
(150637, 'esMX', '¿Y esa cometa?', '¿Y esa cometa?', 28153),
(150636, 'esMX', '', 'Tenemo\' que alcanzarla. ¡Vamos!', 28153),
(150635, 'esMX', '', '¡Debemos apresurarno\' y encontrar a Rakera!', 28153),
(150634, 'esMX', 'Te llevo mucha ventaja, Kenzou.', '', 28153),
(150633, 'esMX', 'Gracias, $p. No podríamos haberlo logrado sin tu ayuda. Toma tu parte.', '', 28153),
(150632, 'esMX', 'Y ahora, Tacha y Omi... No dejaremos ni el más mínimo objeto de valor en este lugar.', '', 28153),
(150631, 'esMX', '¡Suficiente! ¡Se han ganado el honor de morir en mi\' manos!', '', 28153),
(150630, 'esMX', 'Ni siquiera la muerte puede romper nueh\'tro vínculo, mis mascotas. Ahora, aliméntate, T\'zala... ¡ALIMÉNTATE!', '', 28153),
(150629, 'esMX', '¡Nadie sobrevive a mi espada!', '', 28153),
(150628, 'esMX', '¡Es hora de sangrar!', '', 28153),
(150627, 'esMX', '¡Te desgarraré la carne!', '', 28153),
(150626, 'esMX', '¿Puede ser? Sí... ¡Al fin!', '', 28153),
(150625, 'esMX', '¡Mi leyenda opacará la tuya!', '', 28153),
(150624, 'esMX', '¡Jamá\' me podrías quitar la corona!', '', 28153),
(150623, 'esMX', 'Por esto yo soy rey... Y ustede\' no son nada.', '', 28153),
(150622, 'esMX', '¡Pagarán por profanar mi templo!', '', 28153),
(150621, 'esMX', '¡La temporada de cacería ha comenzado!', '', 28153),
(150620, 'esMX', '¡No hay antídoto para eh\'te veneno!', '', 28153),
(150619, 'esMX', '¡Los elemento\' responderán a mi llamado!', '', 28153),
(150618, 'esMX', '¡Te mostraré lo que es un VERDADERO maleficio!', '', 28153),
(150617, 'esMX', '', '¡Siente el dolor!', 28153),
(150616, 'esMX', '', '¡Y ahora, muere!', 28153),
(150615, 'esMX', '', '¡Hora de rebanar cabezah\'!', 28153),
(150614, 'esMX', '', 'Será mejor que sigas caminando, si sabes lo que te conviene.', 28153),
(150613, 'esMX', '', '¡Alguien perderá la cabeza!', 28153),
(150612, 'esMX', 'Entiérrame... lejos... de esto\'... imbéciles...', '', 28153),
(150611, 'esMX', '', 'Mi cabeza... será... un gran trofeo...', 28153),
(150610, 'esMX', '', 'Mi ira... es... infinita...', 28153),
(150609, 'esMX', 'Shh... ¡Estoy intentando encontrar mariposas!', '', 28153),
(150608, 'esMX', '', '¡Uuuh! Sus cabeza\' se convertirán en adornos encantadores.', 28153),
(150607, 'esMX', '', '¡He aplastado insecto\' más fuertes que tú!', 28153),
(150606, 'esMX', '¡El vudú te llevará!', '', 28153),
(150605, 'esMX', '', '¡Nada sobrevive a mi ira!', 28153),
(150603, 'esMX', '¡Me llevo el tesoro!', '¡Me llevo el tesoro!', 28153),
(150602, 'esMX', '¡Haz callar esas voces!', '¡Haz callar esas voces!', 28153),
(150601, 'esMX', '¡Ese tesoro es mío!', '¡Ese tesoro es mío!', 28153),
(150599, 'esMX', '', '¡Ja! ¡Apuesto a que tus hombro\' se sienten más livianos!', 28153),
(150598, 'esMX', '¡Ja! No deberías haber deh\'pertado mi poder.', '', 28153),
(150597, 'esMX', '', '¡Je, je! ¡Sangre y hueso\'!', 28153),
(150596, 'esMX', '', '¡No tienes escapatoria!', 28153),
(150595, 'esMX', '¡El doctor eh\'tá aquí!', '', 28153),
(150594, 'esMX', '¡Preparen el cadáver!', '', 28153),
(150593, 'esMX', '¡Varios huevos comienzan a eclosionar al norte!', '¡Varios huevos comienzan a eclosionar al norte!', 28153),
(150592, 'esMX', '¡Has perturbado a lo\' muertos!', '', 28153),
(150591, 'esMX', '¡Huevos cubiertos de polvo comienzan a eclosionar al este!', '¡Huevos cubiertos de polvo comienzan a eclosionar al este!', 28153),
(150590, 'esMX', '¡Huevos cubiertos de veneno comienzan a eclosionar al oeste!', '¡Huevos cubiertos de veneno comienzan a eclosionar al oeste!', 28153),
(150589, 'esMX', '¡Evitar la infección! ¡Quitar el cerebro!', '', 28153),
(150588, 'esMX', '¡Debemo\' purgar la maldición sangrienta!', '', 28153),
(150587, 'esMX', 'Debemos... preservar... a lo\' muertos...', '', 28153),
(150586, 'esMX', '', 'Le dije a Kaja que siguiera avanzando. Tenemo\' que detener a Jakra\'zet ante\' de que sea demasiado tarde.', 28153),
(150585, 'esMX', '¡Libre de la pestilencia!', '', 28153),
(150584, 'esMX', '¡Vuelve al polvo!', '', 28153),
(150583, 'esMX', 'Descansa.', '', 28153),
(150582, 'esMX', '¡Su sangre eh\'tá maldita!', '', 28153),
(150581, 'esMX', '¡Sus cadáveres eh\'tán infectados!', '', 28153),
(150580, 'esMX', '', 'Ugh... Mi cabeza... ¿Qué son eh\'tas cosas?', 28153),
(150574, 'esMX', '¡Ya veremos, criatura asquerosa!', '', 28153),
(150573, 'esMX', 'Se avecina la tormenta.', 'Se avecina la tormenta.', 28153),
(150572, 'esMX', '¡Fuera de mi vista!', '¡Fuera de mi vista!', 28153),
(150571, 'esMX', 'Seguro, muéstrame lo que tienes, Vali.', 'Seguro, muéstrame lo que tienes, Vali.', 28153),
(150570, 'esMX', '¿Por qué necesitas monedas?', '¿Por qué necesitas monedas?', 28153),
(150569, 'esMX', 'El cara de colmillos que viene por acá siempre ofrece monedas para comerciar. $B$BVali piensa que las monedas deben ser importantes para el comercio fuera de Vol\'dun. $B$BSi Vali quiere irse de Vol\'dun, Vali necesitará monedas.', '', 28153),
(150568, 'esMX', '¡Si tienes monedas, Vali tiene mercancías!', '', 28153),
(150567, 'esMX', '¡Eh! ¡Sí, tú! ¡Me parece que te vendría bien un poco de agua!', '', 28153),
(150566, 'esMX', '', 'Gracias, Mace. Cuando esto termine, hablaremos sobre tu puesto como mi nueva diplomática.', 28153),
(150565, 'esMX', '', 'Confío en ti. Si alguien te da problemas, un golpe rápido en la cabeza solucionará todo.', 28153),
(150564, 'esMX', 'Debo regresar al Altar. Esta esencia es digna de investigación.', 'Debo regresar al Altar. Esta esencia es digna de investigación.', 28153),
(150563, 'esMX', '¿Necesitas reparacione\'? Las herramientas son vieja\', pero puedo darles un buen uso.', '¿Necesitas reparacione\'? Las herramientas son vieja\', pero puedo darles un buen uso.', 28153),
(150562, 'esMX', 'Deseo elegir a Akunda como mi loa.', 'Deseo elegir a Akunda como mi loa.', 28153),
(150561, 'esMX', '<Este santuario fue construido como tributo a Akunda, loa de las tormentas.>', '<Este santuario fue construido como tributo a Akunda, loa de las tormentas.>', 28153),
(150560, 'esMX', '', '¡Qué insolencia! Ya verás cuando tu padre se entere de esto. Mientras tanto, los dejo en manos de mis sirvientes.', 28153),
(150559, 'esMX', '', '¡No te atrevas a llamarme \"hija\", bruja!', 28153),
(150558, 'esMX', '', 'Bienvenida, hija. Veo que has traído invitados.', 28153),
(150557, 'esMX', '¡AAAHHHHHH!', '¡AAAHHHHHH!', 28153),
(150556, 'esMX', 'Inspecciona de cerca el tejido.', 'Inspecciona de cerca el tejido.', 28153),
(150555, 'esMX', 'Este telar y sus creaciones parecen estar imbuidos con la magia del aquelarre.', 'Este telar y sus creaciones parecen estar imbuidos con la magia del aquelarre.', 28153),
(150554, 'esMX', 'Toma la botella.', 'Toma la botella.', 28153),
(150553, 'esMX', 'Aunque el contenido de esta botella venció hace mucho, aún puede ser útil para un cocinero experimentado.', 'Aunque el contenido de esta botella venció hace mucho, aún puede ser útil para un cocinero experimentado.', 28153),
(150552, 'esMX', '¡Ahh! ¡¿Qué está sucediendo?! ¡Ayuda!', '', 28153),
(150551, 'esMX', 'Destruye la vaina inmadura.', 'Destruye la vaina inmadura.', 28153),
(150550, 'esMX', 'Una vaina infectada yace inerte. Parece que alguien la cultiva con fines perversos.', 'Una vaina infectada yace inerte. Parece que alguien la cultiva con fines perversos.', 28153),
(150549, 'esMX', 'Toma el mapa.', 'Toma el mapa.', 28153),
(150548, 'esMX', 'Aquí yace un mapa desgastado que señala lugares de caza locales y asentamientos de mercaderes de cuero regionales.', 'Aquí yace un mapa desgastado que señala lugares de caza locales y asentamientos de mercaderes de cuero regionales.', 28153),
(150547, 'esMX', '¿Seguro que quieres hacer esto?', '¿Segura que quieres hacer esto?', 28153),
(150546, 'esMX', 'Tú... ¡Te llevaste la olla por delante! ¡¿Por qué harías algo así?! ¡Debemos empezar de nuevo!', '', 28153),
(150545, 'esMX', '', '¡El camino está deh\'pejado! ¡Avancen hacia las puerta\' antes del próximo ataque!', 28153),
(150544, 'esMX', '', '$n te asistirá en todo lo que necesites, maestro. Yo veré si puedo darle una mano al alcalde Royston.', 28153),
(150543, 'esMX', '¡Nunca me atraparán con vida!', '¡Nunca me atraparán con vida!', 28153),
(150542, 'esMX', '', 'Me alegra oír eso, maestro Ashton.', 28153),
(150541, 'esMX', 'Inquisidora, sería un grandísimo placer poder ayudarla a usted y a Lady Lucille con esta tarea.', '', 28153),
(150540, 'esMX', '¡Fascinante! ¡Una fórmula sorprendente! ¡Muy inflamable!', '', 28153),
(150539, 'esMX', 'Me imagino que Lady Lucille piensa que podría ser útil. ¡Bueno, vamos a descubrirlo!', '', 28153),
(150538, 'esMX', '', 'Encontró una receta alquímica que fue efectiva tiempo atrás, y ahora quiere que tú intentes recrear la fórmula.', 28153),
(150537, 'esMX', '', 'Lady Lucille ha reforjado la Orden de las Ascuas. Usaremos textos antiguos como guía y lucharemos contra estas brujas como luchamos contra los drust.', 28153),
(150536, 'esMX', '', '¡Krax il\' oni OGOG!', 28153),
(150535, 'esMX', '', 'Ul tala kraza.', 28153),
(150534, 'esMX', '', 'Bwaxa za\' raga xil.', 28153),
(150533, 'esMX', '', '¡Kryl!', 28153),
(150532, 'esMX', 'Eso deduje, pero... ¿por qué yo?', '', 28153),
(150531, 'esMX', '', 'Bwixki amala zal qulllll...', 28153),
(150530, 'esMX', '', 'Aglathrax hig\' thrixa.', 28153),
(150529, 'esMX', '', 'Maestro Ashton, Lady Lucille Tarjasenda nos ha enviado a buscarlo.', 28153),
(150528, 'esMX', '', '¡ULL vera skish!!', 28153),
(150527, 'esMX', '¿Qué posibilidad tenían contra mi poder?', '', 28153),
(150526, 'esMX', '¡Purga!', '', 28153),
(150525, 'esMX', '¡Purificación!', '', 28153),
(150524, 'esMX', 'Las mareas... me arrastran...', '', 28153),
(150523, 'esMX', '¡No puedo esperar para ahogarlos!', '', 28153),
(150522, 'esMX', '¡Ya no toleraré su insolencia!', '', 28153),
(150521, 'esMX', '¡Invoco las aguas turbulentas! ¡Vengan y eliminen a estos intrusos!', '', 28153),
(150520, 'esMX', '¡¿Cómo se atreven a mancillar este lugar sagrado con su presencia?!', '', 28153),
(150519, 'esMX', '¡Disfruta de tu tumba acuática!', '', 28153),
(150518, 'esMX', '[SCENE SHOWS JAKRA\'ZET AND SETHRAK EMPEROR KORTHEK SURROUNDED BY SETHRAK, CONSPIRING ABOUT BREAKING INTO THE PYRAMID. KORTHEK SHOOTS YOU OUT OF THE SKY.]', '', 28153),
(150517, 'esMX', '¿Qué quiere Azeroth de mí, Magni?', '¿Qué quiere Azeroth de mí, Magni?', 28153),
(150516, 'esMX', '¡Deberías haber permanecido en la orilla!', '', 28153),
(150515, 'esMX', 'Devuélvanme... al mar...', '', 28153),
(150514, 'esMX', '¡Los enviaré a las profundidades por eso!', '', 28153),
(150513, 'esMX', '¡NO!', '', 28153),
(150512, 'esMX', '¡Las mareas se los llevarán!', '', 28153),
(150511, 'esMX', 'No hay poder capaz de quebrar nuestro vínculo.', '', 28153),
(150510, 'esMX', '', 'Juntos, amor mío, tenemos la fuerza de la naturaleza.', 28153),
(150509, 'esMX', '', '¡La tormenta te ha purificado!', 28153),
(150508, 'esMX', '', '¡Hundido!', 28153),
(150507, 'esMX', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t¡%s ha recibido una |cFFFF0000|Hcurrency:1559|hesencia de tormenta|h|r!', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t¡%s ha recibido una |cFFFF0000|Hcurrency:1559|hesencia de tormenta|h|r!', 28153),
(150506, 'esMX', '', 'Las nubes... se despejan...', 28153),
(150505, 'esMX', '', '¡Los vientos les arrancarán la carne de los huesos!', 28153),
(150504, 'esMX', '', '¡Mi amado! ¡No!', 28153),
(150503, 'esMX', 'Si hay alguien capaz de sobrevivir, es él. Revisaré los jardines del laboratorio, Inquisidora.', '', 28153),
(150502, 'esMX', '', '¡Nadie resistirá la tormenta!', 28153),
(150501, 'esMX', '', 'El ataque a Halcónida fue feroz. Espero que el maestro Ashton haya sobrevivido.', 28153),
(150500, 'esMX', '', '¡Priscilla está escapando a caballo! ¡Monta uno de nuestros destreros y persíguela!', 28153),
(150499, 'esMX', 'Maestro Ashton, necesitamos su ayuda.', 'Maestro Ashton, necesitamos su ayuda.', 28153),
(150498, 'esMX', 'Te doy las gracias. Ahora, me marcharé.', 'Te doy las gracias. Ahora, me marcharé.', 28153),
(150497, 'esMX', '¡Nunca olvidaré esto! ¡Me voy de aquí!', '¡Nunca olvidaré esto! ¡Me voy de aquí!', 28153),
(150496, 'esMX', 'Pensé que me quedaría ahí para siempre...¡Aquí tienes una muestra de gratitud!', 'Pensé que me quedaría ahí para siempre...¡Aquí tienes una muestra de gratitud!', 28153),
(150495, 'esMX', 'Gracias por liberarme. Quizás esto te ayude.', 'Gracias por liberarme. Quizás esto te ayude.', 28153),
(150494, 'esMX', '¡Gracias al cielo! ¡Me has salvado! Permíteme hacer algo para ayudar.', '¡Gracias al cielo! ¡Me has salvado! Permíteme hacer algo para ayudar.', 28153),
(150493, 'esMX', '¡No me dejes aquí!', '¡No me dejes aquí!', 28153),
(150492, 'esMX', '¡Déjenme salir!', '¡Déjenme salir!', 28153),
(150491, 'esMX', '', '¡Por favor, ayúdennos! Si no detenemos a Gorak Tul, su mal se diseminará por todo Azeroth.', 28153),
(150490, 'esMX', '¡Ayuda!', '¡Ayuda!', 28153),
(150489, 'esMX', '¡Rápido! ¡Encuentra una forma de abrir esta celda!', '¡Rápido! ¡Encuentra una forma de abrir esta celda!', 28153),
(150488, 'esMX', '¡Libérame!', '¡Libérame!', 28153),
(150487, 'esMX', '¡Por favor, ayúdame!', '¡Por favor, ayúdame!', 28153),
(150486, 'esMX', '¿Un sáurido? ¿Y qué hace esto por aquí?', '', 28153),
(150485, 'esMX', '', 'No importa quiénes sean; necesitamos su ayuda. ¡Gorak Tul no puede llegar a nuestro mundo!', 28153),
(150484, 'esMX', '', '¡Tranquilo, maestro Ashton! ¡Somos $ualiados:aliadas;!', 28153),
(150483, 'esMX', '¡Llegamos tarde! Un momento... ¡¿quiénes son ustedes?!', '', 28153),
(150482, 'esMX', 'Vaya que se ven $Upeligrosos:peligrosas;. ¡Ja! ¿Ya se acabó el ataque?', '', 28153),
(150480, 'esMX', '¡Atrás! ¡Tengo alquimia y sé cómo usarla!', '', 28153),
(150479, 'esMX', 'Al destruir a Lady Tarjasenda, han abierto una puerta a su mundo.', '', 28153),
(150478, 'esMX', 'Mortales, carecen de visión. No se puede detener a la muerte.', '', 28153),
(150477, 'esMX', '', 'Se han quedado más de la cuenta. Muy bien. ¡Ahora nunca dejarán estas tierras!', 28153),
(150476, 'esMX', '', 'Si siguen metiéndose en mis asuntos, sus muertes serán largas y dolorosas.', 28153),
(150475, 'esMX', '', 'Por su asombro supongo que en el lugar de donde ustedes vienen la idea de una casa que no sea de estiércol es nueva y emocionante.', 28153),
(150474, 'esMX', '', 'Pensándolo bien, no tienen que responder.', 28153),
(150473, 'esMX', '', '¿Acaso está bien visto en su ciudad asesinar a los sirvientes de su anfitriona?', 28153),
(150472, 'esMX', 'Estoy listo. Busquemos a los demás.', 'Estoy lista. Busquemos a los demás.', 28153),
(150471, 'esMX', 'No hay tiempo que perder. Tus amigos ya están en Atul\'Aman...', '', 28153),
(150470, 'esMX', 'Kua\'fon chilla con indignación y sale corriendo.', '', 28153),
(150469, 'esMX', '', '¡Pequeño! Si quieres volver al nido, je, será mejor que empieces a correr.', 28153),
(150468, 'esMX', '', 'Por ahora le daremos una lección práctica.', 28153),
(150467, 'esMX', '', 'Tu pequeño no confía en sus alas. Debes seguir mostrándole la belleza de los cielos.', 28153),
(150466, 'esMX', '', '¡¿Por qué sigues usando tus piernas?!', 28153),
(150465, 'esMX', '', 'Están vivos. Bien. Tal como dije...', 28153),
(150464, 'esMX', '', 'Gracias, héroes. Han destruido al aquelarre y nos libraron del poder de Gorak Tul. Estamos en deuda con ustedes.', 28153),
(150463, 'esMX', '', '¿Lo ven? No hay nada que la fuerza y el acero no puedan arreglar.', 28153),
(150462, 'esMX', '¡Lo logramos! Gorak Tul ha caído.', '', 28153),
(150461, 'esMX', '¡El choque es inminente! ¡Kua\'fon chilla pidiendo ayuda!', '¡El choque es inminente! ¡Kua\'fon chilla pidiendo ayuda!', 28153),
(150460, 'esMX', 'Vengan, mortales. La muerte los espera.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'esMX', '', 'Severola y yo resistiremos aquí. ¡Tienen que terminar con esto!', 28153),
(150458, 'esMX', '', '¡Todos los horrores de la mansión vienen a nosotros!', 28153),
(150457, 'esMX', '', '¡No podemos permitir que Gorak Tul llegue a nuestro mundo!', 28153),
(150456, 'esMX', 'La cometa empieza a sacudirse con violencia. ¡Retrocede y busca una brisa más suave!', 'La cometa empieza a sacudirse con violencia. ¡Retrocede y busca una brisa más suave!', 28153),
(150455, 'esMX', '|TInterface\\ICONS\\INV_POTION_24:20|t ¡Usa |cFFFF0404|Hspell:266198|h[Fuego alquímico]|h|r para destruir los cadáveres de los esclavistas necroimbuidos!', '', 28153),
(150454, 'esMX', 'La pesadilla recién empieza.', '', 28153),
(150453, 'esMX', 'Lady Tarjasenda era solo un conducto para mi poder. Al destruirla, han abierto una puerta a su mundo.', '', 28153),
(150452, 'esMX', 'Absorbiendo', 'Absorbiendo', 28153),
(150451, 'esMX', 'Criatura necia. No tienes visión. La muerte es una fuerza inevitable que acecha en cada rincón.', '', 28153),
(150450, 'esMX', '', 'Al fin, la pesadilla ha terminado.', 28153),
(150448, 'esMX', 'Ve, mi $Uesbirro:esbirra;. Roba su gorro y gánate el favor de Jani. Pero ten cuidado. No deje\' que los predadores hambriento\' te vean…', '', 28153),
(150446, 'esMX', '', 'Tienes razón. Pero, ¿cómo recuperaré la confianza de mi gente cuando se enteren de los horrores que ha cometido mi familia?', 28153),
(150445, 'esMX', '', 'Lo único importante ahora es terminar con su maldad.', 28153),
(150444, 'esMX', '', 'Mi madre siempre tuvo una vena cruel, pero jamás pensé que fuera capaz de algo semejante.', 28153),
(150443, 'esMX', 'Tú continúa. Encuentra a Lady Tarjasenda. Salda las cuentas pendientes.', '', 28153),
(150442, 'esMX', '¡Je! Carne muerta.', '', 28153),
(150441, 'esMX', 'Procura que Lady Tarjasenda reciba un castigo por practicar esa magia horrenda.', '', 28153),
(150440, 'esMX', 'Has ayudado mucho a esas almas al liberarlas.', '', 28153),
(150439, 'esMX', 'Sigue buscando a Lady Tarjasenda. Yo me ocuparé de despejar estos cuartos.', '', 28153),
(150438, 'esMX', 'Descansaré en paz sabiendo que estas criaturas repugnantes ya no acechan.', '', 28153),
(150437, 'esMX', 'Investigaremos las tierras mientras ustedes despachan a sus sirvientes. Buena cacería.', '', 28153),
(150436, 'esMX', '', 'Héroes, necesitamos de su fuerza. Tenemos que ponerle punto final a este mal.', 28153),
(150435, 'esMX', 'Salir corriendo no parece una buena idea. Tenemos un plan mejor, ¿verdad?', '', 28153),
(150434, 'esMX', '¡Mace!', '', 28153),
(150433, 'esMX', '', '¡Vuelve y enfrenta mi acero!', 28153),
(150432, 'esMX', '', 'Como lo ordene, maestra.', 28153),
(150431, 'esMX', '', 'Señoritas, pongan cómodos a nuestros invitados.', 28153),
(150430, 'esMX', '', 'Parece que tenemos invitados inesperados. No importa, seguramente podremos alojarlos.', 28153),
(150429, 'esMX', 'Eres una caja de sorpresas.', 'Eres una caja de sorpresas.', 28153),
(150428, 'esMX', '¡Excelente trabajo, $r!', 'Buen trabajo, $p.', 28153),
(150427, 'esMX', '¡Soy libre!', '¡Soy libre!', 28153),
(150426, 'esMX', '¡Te debo una!', '¡Te debo una!', 28153),
(150425, 'esMX', '¡Muchas gracias!', '¡Muchas gracias!', 28153),
(150421, 'esMX', 'Te concederé una parte de mi poder, $p. Mi baluarte suprimirá a todo infiel que te amenace.', '', 28153),
(150420, 'esMX', '¿Acaso sientes tanto temor, viejo amigo, que te ocultas mientras tu pueblo sufre? ¡Ven a terminar con esto, Korthek!', '', 28153),
(150419, 'esMX', '$p, deberías trabajar conmigo. Voy a encontrarlo.', '$p, deberías trabajar conmigo. Voy a encontrarlo.', 28153),
(150418, 'esMX', '', '¡Un pequeño contratiempo! Cuando mis fuerzas se reagrupen, ¡esta ciudad miserable será nuestra!', 28153),
(150417, 'esMX', 'La traición de Zul fue peor de lo que imaginaba. Su rebelión prácticamente acabó con mi ejército.\n\nLos que aún me son leales están muriendo en ese campo de batalla a mis espaldas, a manoh\' de esos enjambres infinitoh\' de trols de sangre.\n\nDebí haberle hecho caso a Talanji.', '', 28153),
(150416, 'esMX', 'Conozco a un tipo que sabe dónde está.', 'Conozco a un tipo que sabe dónde está.', 28153),
(150415, 'esMX', '¿Sabes dónde está el oro?', '¿Sabes dónde está el oro?', 28153),
(150414, 'esMX', 'Si encuentras el tesoro, podríamos repartirlo entre nosotros.', 'SI encuentras el tesoro, podríamos repartirlo entre nosotros.', 28153),
(150413, 'esMX', 'Oí que los Mareaférrea ya lo encontraron.', 'Oí que los Mareaférrea ya lo encontraron.', 28153),
(150412, 'esMX', 'Ey, ¡ayúdame a encontrar el tesoro!', 'Ey, ¡ayúdame a encontrar el tesoro!', 28153),
(150411, 'esMX', 'Este tipo tiene un amigo que oyó a uno de los Mareaférrea decir que sabe dónde está el tesoro.', 'Este tipo tiene un amigo que oyó a uno de los Mareaférrea decir que sabe dónde está el tesoro.', 28153),
(150410, 'esMX', 'Tal vez estas historias del oro son una gran mentira.', 'Tal vez estas historias del oro son una gran mentira.', 28153),
(150409, 'esMX', 'Tenemos que encontrar este tesoro antes de que los Mareaférrea saqueen este lugar.', 'Tenemos que encontrar este tesoro antes de que los Mareaférrea saqueen este lugar.', 28153),
(150408, 'esMX', '', 'Tal vez alguien se comió al gato.', 28153),
(150407, 'esMX', 'Vuela a casa, orgulloso rak\'jani, y dile a tu padre quién te liberó.', '', 28153),
(150406, 'esMX', '', 'Reuniré a alguno\' de los miembros de mi tripulación y haré que los demás tomen esos esquife\' cercanos. ¡Que te diviertas, $n!', 28153),
(150405, 'esMX', '¡Rápido! ¡Préndanlos fuego antes de que el rey drust los reviva!', '', 28153),
(150404, 'esMX', 'Rápido, ¡quemen eso!', '', 28153),
(150403, 'esMX', '¡Nos vendría bien un poco de ayuda aquí!', '', 28153),
(150402, 'esMX', '¡$n! ¡Nos aplastan!', '', 28153),
(150401, 'esMX', '¡Sométete a la oscuridad!', '', 28153),
(150400, 'esMX', '¡Levántense!', '', 28153),
(150399, 'esMX', '¡Nadie puede oponerse a mí!', '', 28153),
(150398, 'esMX', '¡No eres nada!', '', 28153),
(150397, 'esMX', 'La vida siempre termina.', '', 28153),
(150396, 'esMX', 'La muerte... no me retendrá...', '', 28153),
(150395, 'esMX', '¡La muerte consume todo!', '', 28153),
(150394, 'esMX', '¡Nadie se salvará de mi venganza!', '', 28153),
(150393, 'esMX', '¡Todo el personal a la cocina!', '', 28153),
(150392, 'esMX', '¡Ablandado!', '', 28153),
(150391, 'esMX', 'El menú de esta noche será SUMAMENTE delicioso...', '', 28153),
(150390, 'esMX', 'Una... deliciosa... agonía...', '', 28153),
(150388, 'esMX', '', 'Los vulperas están contigo, $p.\n\nEnvíame a cualquier infiel problemático y yo me encargaré. Con gusto.', 28153),
(150387, 'esMX', '¡Suculento!', '', 28153),
(150386, 'esMX', '¡Carne fresca!', '', 28153),
(150385, 'esMX', '¡Qué apetecible!', '', 28153),
(150384, 'esMX', '¡Quédate a cenar!', '', 28153),
(150383, 'esMX', '¡Le daré el triple al primero que encuentre el tesoro!', '', 28153),
(150382, 'esMX', '¿Quieren ser ricos? ¡Encuéntrenme el tesoro!', '', 28153),
(150381, 'esMX', 'Moxie, ¡pon a estos holgazanes a trabajar!', '', 28153),
(150380, 'esMX', 'Sucios mareaférrea, ¡nunca se quedarán con este tesoro!', '', 28153),
(150379, 'esMX', '¡Mata al que tiene el sombrero de pirata! ¡Sí, ese!', '', 28153),
(150378, 'esMX', '¡Levanten las rocas! ¡Revisen en todos lados!', '', 28153),
(150377, 'esMX', '¡Encárgate de esos mareaférrea!', '', 28153),
(150376, 'esMX', '<Mugido>', '', 28153),
(150375, 'esMX', '', '<Mugido>', 28153),
(150374, 'esMX', '', 'Lo siento...', 28153),
(150373, 'esMX', '', 'Soy la Matrona del Afán, Directora Radical de Estudios. Designación: M.A.D.R.E.', 28153),
(150372, 'esMX', '', 'Lo que sea que estaban haciendo aquí, ¡hoy se termina!', 28153),
(150371, 'esMX', '', '¿Dónde está el dinero?', 28153),
(150370, 'esMX', '', '¡Sé que esconden algo por aquí!', 28153),
(150369, 'esMX', '', 'Todos ustedes se quebrarán en los astilleros.', 28153),
(150368, 'esMX', '', 'No son tan rudos como pensaba.', 28153),
(150367, 'esMX', '', '¡Llevarán estas cadenas hasta los astilleros!', 28153),
(150366, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo sólido y resistente al Sagrario de los Carroñeros?', '', 28153),
(150365, 'esMX', 'Que se lo queden. ¡No podrás gastarlo si estás muerto!', 'Que se lo queden. ¡No podrás gastarlo si estás muerto!', 28153),
(150364, 'esMX', 'No voy a abandonar el tesoro. ¡Está aquí!', 'No voy a abandonar el tesoro. ¡Está aquí!', 28153),
(150363, 'esMX', '¡Se acercan los Mareaférrea! ¡Tenemos que irnos de aquí pronto!', '¡Se acercan los Mareaférrea! ¡Tenemos que irnos de aquí pronto!', 28153),
(150362, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo brillante y suave al Sagrario de los Carroñeros?', '', 28153),
(150361, 'esMX', 'Hemo\' llegado. El cielo eh\'tá despejado, es un gran día para explorar.', '', 28153),
(150360, 'esMX', 'Eh\'te no es un temblor normal... La azerita está emergiendo en algún lugar cercano.', '', 28153),
(150359, 'esMX', 'El dispositivo eh\'tá activo. Deberíamos poder ver toda la azerita ahora.', '', 28153),
(150358, 'esMX', 'Cuidado, una nave kultirana acaba de atracar.', '', 28153),
(150357, 'esMX', '¡No es justo! ¡Tú te quedaste con el último!', '¡No es justo! ¡Tú te quedaste con el último!', 28153),
(150356, 'esMX', '¡Eh! ¡Eso es mío!', '¡Eh! ¡Eso es mío!', 28153),
(150355, 'esMX', '¡Busca en sus bolsillos!', '¡Busca en sus bolsillos!', 28153),
(150354, 'esMX', '¡Toma las llaves!', '¡Toma las llaves!', 28153),
(150353, 'esMX', '¡Idiota! ¡Razgaji te ha enviado a tu muerte!', '', 28153),
(150352, 'esMX', '', 'Eso es justo lo que estaba pensando. $n, ¿te importaría poner a prueba nuestra teoría?', 28153),
(150351, 'esMX', 'Qué interesante. Los fuegos fatuos responden al llamado de Malfurion. ¿Pero qué tal si otras zonas del bosque pidieran ayuda?', '', 28153),
(150350, 'esMX', '', 'No podemos destruir a los fuegos fatuos... no suficientes. Quizá podamos dispersarlos.', 28153),
(150349, 'esMX', '¡Nadie le roba a Tongo y se sale con la suya!', '', 28153),
(150348, 'esMX', '', 'El grupo de exploración que envié a lidiar con Malfurion subestimó a los fuegos fatuos. Pagaron el precio de su error.', 28153),
(150347, 'esMX', '¿Un muro de fuegos fatuos? Seguramente no es nada que nuestros forestales oscuros y un par de demoledores no puedan resolver, milady.', '', 28153),
(150346, 'esMX', 'Nunca... me vencerán...', '', 28153),
(150345, 'esMX', '¡Otro pterrordáctilo demasiado débil para los infieles!', '', 28153),
(150344, 'esMX', '', '¡Es bueno verte! Ven, descansa un poco.', 28153),
(150343, 'esMX', '', '¡Si necesitas algo, solo dímelo!', 28153),
(150342, 'esMX', '', '¡$GBienvenido:Bienvenida; a mi taberna! Pasa, bebe algo.', 28153),
(150341, 'esMX', '', '¿Estás bien, cariño? Entra, haz de cuenta que estás en tu casa.', 28153),
(150340, 'esMX', '', 'Parece que necesitas descansar. ¡Toma asiento, come algo!', 28153),
(150339, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo cargado de electricidad y filoso al Sagrario de los Carroñeros?', '', 28153),
(150338, 'esMX', '¡Toda esta azerita es mía!', '¡Toda esta azerita es mía!', 28153),
(150337, 'esMX', '', 'Dime si esto te duele...', 28153),
(150336, 'esMX', '', '¡Guau! ¡Sí que sangras mucho!', 28153),
(150335, 'esMX', '', '¡Capitana! El artilugio ha detectado enemigos cerca. ¡Es hora de usar mis cuchillas nuevas!', 28153),
(150334, 'esMX', '', 'Arregla los incendios... arregla las explosiones... ¡Pffft! ¡Explotadores!', 28153),
(150333, 'esMX', '', 'Puede ser que funcione Y TAMBIÉN explote. Una cosa no quita la otra, ¿sabes?', 28153),
(150332, 'esMX', '', 'A la capitana... no le gustará... esto...', 28153),
(150331, 'esMX', '', '¡Te apuñalaré!', 28153),
(150330, 'esMX', '', '¡Sorpresa!', 28153),
(150329, 'esMX', '', '¡Hora de apuñalar!', 28153),
(150328, 'esMX', '¡Eso me dolió un poco!', '', 28153),
(150327, 'esMX', '¡Aahhh, jo, jo, jo, jo! ¡Tienes espíritu! ¡Ja!', '', 28153),
(150326, 'esMX', '¡Eres carnada!', '', 28153),
(150325, 'esMX', '¿Qué miras?', '', 28153),
(150324, 'esMX', 'Ahora seré... alimento para los peces...', '', 28153),
(150323, 'esMX', 'Mmm. No es la típica basura que se encuentra en esta isla. Quizás este desvío valga la pena después de todo.', '', 28153),
(150322, 'esMX', '¡Gusanos vivos para mi anzuelo!', '', 28153),
(150321, 'esMX', '¡Se convertirán en carnada!', '', 28153),
(150320, 'esMX', '¡Ahora hazte cargo!', '', 28153),
(150319, 'esMX', '', '¡Rápido! ¡Tráiganme un cubo! ¡No hay que desperdiciar ni una gota!', 28153),
(150318, 'esMX', '', 'Una isla repleta de criaturas y personas y cosas, y... y la Horda. ¡Tráiganme algo de sangre!', 28153),
(150317, 'esMX', '', '¡De acuerdo, tripulación! Tráiganme sangre... ¡mi amada y deliciosa sangre! Mm, tal vez los recompense si lo hacen.', 28153),
(150316, 'esMX', '', 'Sangre de la Horda... ¡mi favorita! Tripulación, ¡ya saben qué hacer!', 28153),
(150315, 'esMX', '', 'Ah, hola. ¿Realmente necesitan toda su sangre? Seguramente me pueden dar un poco...', 28153),
(150314, 'esMX', '', 'Tanta sangre... desperdiciada...', 28153),
(150313, 'esMX', '', '¡Mátenlos más rápido! ¡QUIERO SANGRE!', 28153),
(150312, 'esMX', '', '¡Hora de sangrar!', 28153),
(150311, 'esMX', '', '¡Ni un sobreviviente!', 28153),
(150310, 'esMX', '¡Ahh! ¡Ja, ja, ja!', '', 28153),
(150309, 'esMX', '¡Je, je, je, je!', '', 28153),
(150308, 'esMX', 'A... lian... ¡za! ¡Hora de jugar!', '', 28153),
(150307, 'esMX', '¡HOLA!', '', 28153),
(150306, 'esMX', 'Je... je, je...', '', 28153),
(150305, 'esMX', '¡No te muevas!', '', 28153),
(150304, 'esMX', '¡Petey el Escurridizo!', '', 28153),
(150303, 'esMX', '¡Petey el Escurridizo!', '', 28153),
(150302, 'esMX', '¡Petey el Escurridizo!', '', 28153),
(150301, 'esMX', '¡Deja de golpearme!', '', 28153),
(150300, 'esMX', '¡Oye, eso hace cosquillas!', '', 28153),
(150299, 'esMX', '¡Al piso he dicho!', '', 28153),
(150298, 'esMX', '¡Ja! ¡Te tengo!', '', 28153),
(150297, 'esMX', 'Lee el texto rúnico en voz alta.', 'Lee el texto rúnico en voz alta.', 28153),
(150295, 'esMX', 'Llévame volando al Trono Dorado.', 'Llévame volando al Trono Dorado.', 28153),
(150294, 'esMX', '', '$n, tenemos que llamar la atención de los kaldorei mientras pienso una solución para el problema de los fuegos fatuos.', 28153),
(150293, 'esMX', '', 'Mmm, ¿los fuegos fatuos se estaban dispersando? Excelente. Nuestro plan podría funcionar...', 28153),
(150292, 'esMX', '', '¡Mis demoledores los harán pedazos! ¡Solo están demorando lo inevitable!', 28153),
(150291, 'esMX', '', '¡Acólitos, derriben esa barricada!', 28153),
(150290, 'esMX', '', '¡Vamos, mascotas mías! ¡Háganlos pedazos!', 28153),
(150289, 'esMX', '', 'Campeones, síganme. Los invito a contemplar el gran final.', 28153),
(150288, 'esMX', '', 'O tal vez tengas la oportunidad de saludar a tu hijo.', 28153),
(150287, 'esMX', '', 'Ve a buscar tu muerte de guerrero, alto señor supremo Colmillosauro. No es algo que me importe. Quizá reviva tu cadáver maltrecho para que vuelva a servirme.', 28153),
(150286, 'esMX', '', 'Puede que a ti no te importe que tu pueblo muera, con tal de que mueran con honor. Pero para mí, esta Horda merece salvarse. Los que no creen lo mismo no merecen estar entre nosotros.', 28153),
(150285, 'esMX', '', 'El honor no significa nada para un cadáver, Colmillosauro. Tú tienes el lujo de subestimar a la muerte, pero es algo que yo conozco muy íntimamente.', 28153),
(150284, 'esMX', 'Ten fe en la estrategia de la jefa de guerra, Theron.', '', 28153),
(150283, 'esMX', 'Los elfos del Vacio... ¡debemos lidiar con esos traidores!', '', 28153),
(150282, 'esMX', '¡Lordaeron le pertenece a los Renegados! ¡No retrocedan!', '', 28153),
(150281, 'esMX', 'Su ataque pronto flaqueará. ¡Resistan!', '', 28153),
(150280, 'esMX', '¡La Alianza no resistirá mucho más, campeones! Ya han perdido más de la mitad de su ejército.', '', 28153),
(150279, 'esMX', '¡Jajaja! Miren quién se une a la batalla. ¡Bien, esperaba que mantuvieras las cosas interesantes!', '', 28153),
(150278, 'esMX', 'Es mejor que te lo diga ella misma. ¡Vete!', '', 28153),
(150277, 'esMX', '¿Cuánto tiempo piensas contenerlos? ¿Qué planea la jefa de guerra?', '', 28153),
(150276, 'esMX', 'No. Lor\'themar y yo nos encargaremos de los intrusos. No puedo dejar a la jefa de guerra desprotegida. Quédate a su lado.', '', 28153),
(150275, 'esMX', 'Entendido. Iré contigo en cuanto pueda.', '', 28153),
(150274, 'esMX', 'El camino estrecho los obligará a pasar en fila junto a la fortaleza, y eso reducirá sus números.', '', 28153),
(150273, 'esMX', '¡No hay tiempo! ¡Muy pronto perderemos la ventaja del terreno!', '', 28153),
(150272, 'esMX', 'Sí, Clamañublo. Pero... ¿dónde está Colmillosauro?', '', 28153),
(150271, 'esMX', '¡Baine! Reúne las catapultas y todos los boticarios que encuentres. ¡Envíalos a la fortaleza de inmediato!', '', 28153),
(150270, 'esMX', 'Desde luego, Clamañublo.', '', 28153),
(150269, 'esMX', '¡Lor\'themar, guía a nuestros forestales del flanco! ¡Deben posicionarse en los tejados!', '', 28153),
(150268, 'esMX', '¡Lanzañublos, son nuestra vanguardia! ¡Deben crear una franja de añublo entre nosotros y el enemigo!', '', 28153),
(150267, 'esMX', 'Obedezco, mi reina.', '', 28153),
(150266, 'esMX', '', 'Reúnete con Lor\'themar. ¡RÁPIDO! ¡No me falles, Nathanos!', 28153),
(150265, 'esMX', '¡Máscaras de gas! ¡Consigan sus máscaras de gas aquí! Y si tienen ganas, ¡pueden tomar una de estas mochilas y ponerse a trabajar! Ji, ja, ja, ja, ja.', '', 28153),
(150264, 'esMX', 'Conserven su honor, héroes. Lok-narash.', '', 28153),
(150263, 'esMX', '', '¡Mátenlos a todos, campeones! Se los aseguro, el rey Anduin y su ejército no vinieron aquí para divertirse. ¡Quieren destruirnos! ¡No tengan piedad, porque ustedes no la recibirán!', 28153),
(150262, 'esMX', '¡Soldados de la Horda! ¡Sus hermanos y hermanas yacen heridos en el campo de batalla! ¡No habrá honor en la victoria si los abandonamos!', '', 28153),
(150261, 'esMX', '¡Lok\'tar ogar!', '', 28153),
(150260, 'esMX', 'Se avecinan muchas tropas, pero somos fuertes. ¡Somos la Horda! ¡Aplastamos a los que osan enfrentarnos!', '', 28153),
(150259, 'esMX', '¡Campeones! ¡Su jefa de guerra los llama! ¡Es hora de alzarse en armas contra la Alianza!', '', 28153),
(150258, 'esMX', '', 'Entonces terminemos con esto de una vez por todas. Colmillosauro, reúne tus tropas. Yo prepararé la máquina de azerita.', 28153),
(150257, 'esMX', 'Sí, jefa de guerra.', '', 28153),
(150256, 'esMX', '¡Rápido! ¡La jefa de guerra espera!', '', 28153),
(150255, 'esMX', '¡Conmigo, rápido! ¡Hay que seguir avanzando antes que la Horda se recupere!', '', 28153),
(150254, 'esMX', '¡Sus vientos son fuertes, pero juntos venceremos! ¡Perseveren, campeones!', '', 28153),
(150253, 'esMX', '¡No tan rápido!', '', 28153),
(150252, 'esMX', '', '¡Y apresúrense! ¡Mi barrera de hielo no resistirá mucho!', 28153),
(150251, 'esMX', '¡Héroes! Concéntrense en los refuerzos primero. ¡Luego nos encargaremos de esos chamanes!', '', 28153),
(150250, 'esMX', 'La jefa de guerra... los... detendrá...', '', 28153),
(150249, 'esMX', '¡Los viento\' del espíritu de águila les DESPELLEJARÁN LOS HUESO\'!', '', 28153),
(150248, 'esMX', '', '', 28153),
(150246, 'esMX', 'RIIIII.', '', 28153),
(150245, 'esMX', '¡RRIIIIIIIIIIII!', '', 28153),
(150244, 'esMX', '¡RIIII!', '', 28153),
(150242, 'esMX', 'El libro está lleno de runas encantadas que se mueven rápidamente entre sus páginas.', 'El libro está lleno de runas encantadas que se mueven rápidamente entre sus páginas.', 28153),
(150241, 'esMX', '¿Ya puedo matarlos? Me prometiste una matanza.', '', 28153),
(150240, 'esMX', '¡¿QUÉ?!', '', 28153),
(150239, 'esMX', 'Busca tu propia caja, ¡$r $gacaparador:acaparadora;!', '¡No, la caja es mía!\n\nVine hasta aquí en busca de gusanos para hacer sopa. Algunos tortollanos dicen que con la carne de reptador se hace una sopa deliciosa, pero no estoy seguro. La sopa de reptador no es motivo para hacerme amigo de $Gun extraño:una extraña;. \n\nPero la sopa de carne de gusano fangoso construye amistades de por vida, y los tortollanos vivimos mucho tiempo. \n\nSi encuentras un poco de carne de gusano fangoso, quizás te dé esta caja.', 28153),
(150238, 'esMX', 'Eso... duele...', '', 28153),
(150237, 'esMX', '¡Graaaah!', '', 28153),
(150236, 'esMX', 'Antes de sacar tu arma, escúchame, por favor...', '', 28153),
(150235, 'esMX', '', 'Que alguien revise a ese cadáver a ver si tiene algo de valor.', 28153),
(150234, 'esMX', '', 'En esta isla aún hay tesoros que no están en mi barco. ¡Vamos, buenos para nada! ¡Y también tomen el botín de la Alianza!', 28153),
(150233, 'esMX', '', 'Veo que la Alianza está aquí y que aún respira. Vamos a encargarnos de eso.', 28153),
(150232, 'esMX', '', 'A esta isla hay que quitarle todo el botín, muchachos. ¡Empecemos! No me gusta esperar.', 28153),
(150231, 'esMX', '', '¿Yarr?', 28153),
(150230, 'esMX', '', 'No les... daré... nada...', 28153),
(150229, 'esMX', '', '¡Ya fue suficiente! ¡Mátenlos a todos!', 28153),
(150228, 'esMX', '', 'Cuando estés muerto, será más fácil quitarte todo.', 28153),
(150227, 'esMX', '', 'He oído cosas feas sobre la Alianza. No nos acerquemos a ellos.', 28153),
(150226, 'esMX', '', 'Esto te ayudará.', 28153),
(150225, 'esMX', '', 'Yo me encargo.', 28153),
(150224, 'esMX', '', 'Saludos.', 28153),
(150223, 'esMX', '', 'Yo tenía... razón...', 28153),
(150222, 'esMX', '', 'Oh, no... Están aquí.', 28153),
(150221, 'esMX', 'Quizás sea prudente retirarse.', '', 28153),
(150220, 'esMX', 'Ya fue suficiente.', '', 28153),
(150219, 'esMX', 'No se entrometan, miembros de la Alianza. O me veré en la obligación de aplastarlos.', '', 28153),
(150218, 'esMX', 'Saludos.', '', 28153),
(150217, 'esMX', 'Kua\'fon devora la comida y deja trozos desparramados aquí y allá.', '', 28153),
(150216, 'esMX', 'La Luz... Yo... regresaré...', '', 28153),
(150215, 'esMX', '¡Desata tu furia!', '', 28153),
(150214, 'esMX', '¡No tengo tiempo para esto!', '', 28153),
(150213, 'esMX', '', 'Quédate ahí.', 28153),
(150212, 'esMX', '', 'No tan rápido...', 28153),
(150211, 'esMX', '', 'Ha llegado tu hora.', 28153),
(150210, 'esMX', '', 'Cenizas a las cenizas.', 28153),
(150209, 'esMX', '', 'Los vientos nos han guiado hasta aquí... y también a la Alianza. Los elementos me siguen sorprendiendo.', 28153),
(150208, 'esMX', '', 'Oigan esto, miembros de la Alianza. Si no nos molestan, no los molestaremos.', 28153),
(150207, 'esMX', '', 'Aquí, los elementos no están en equilibrio. Tratemos de ayudarlos, pero sin que la Alianza se interponga en nuestro camino.', 28153),
(150206, 'esMX', '', '¿Qué los trae por aquí?', 28153),
(150205, 'esMX', '', 'Mi espíritu... regresará...', 28153),
(150204, 'esMX', '', 'Estás poniendo a prueba mi paciencia.', 28153),
(150203, 'esMX', '', 'Elementos, ayúdennos.', 28153),
(150202, 'esMX', '', 'Déjame ayudarte.', 28153),
(150201, 'esMX', '', '¡La Luz brilla sobre ti!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'esMX', '', 'Matar no me complace en absoluto.', 28153),
(150199, 'esMX', '', 'Cuidado, nuestros enemigos han llegado. Hay que evitarlos mientras podamos.', 28153),
(150198, 'esMX', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Alimento para dinosaurios extracrocante]|h|r>', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Alimento para dinosaurios extracrocante]|h|r>', 28153),
(150197, 'esMX', '', '¡La Luz te saluda!', 28153),
(150196, 'esMX', '', 'Voy... con la Luz...', 28153),
(150195, 'esMX', '<Kua\'fon bate la mandíbula con impaciencia.>\n\nRIIIII.', '', 28153),
(150194, 'esMX', '', '¡Ríndete! ¡Sálvate de una muerte innecesaria!', 28153),
(150193, 'esMX', '<Kua\'fon te olfatea.>\n\nRiiii.', '', 28153),
(150192, 'esMX', '¿Estás seguro de que quieres hacer esto? No cambiará nada, solo te dará derecho a alardear un poco.', '¿Estás seguro de que quieres hacer esto? No cambiará nada, solo te dará derecho a alardear un poco.', 28153),
(150191, 'esMX', '¡Un enemigo poderoso!', '', 28153),
(150190, 'esMX', '¡La Luz te ha juzgado!', '', 28153),
(150189, 'esMX', 'Así que la jefa de guerra quiere espantar a los fuegos fatuos, ¿eh? Tengo justo lo que necesita. \n\n¿Quieres pilotar esta máquina? ¿O prefieres arrojar las bombas?', '', 28153),
(150188, 'esMX', 'La Luz resplandece en este lugar. Aquí hay mucha azerita.', '', 28153),
(150187, 'esMX', 'Aún se intenta idear el espacio para esto. Quizás sea necesario sacar algunos árboles o conseguir un elemento de árbol que se pueda hacer brillar. \n\nHay que generar la sensación de que fue genial que los fuegos fatuos atravesaran la pared y crearan grietas visibles en el lugar donde se arrojaron las bombas.', 'Aún se intenta idear el espacio para esto. Quizás sea necesario sacar algunos árboles o conseguir un elemento de árbol que se pueda hacer brillar. Hay que generar la sensación de que fue genial que los fuegos fatuos atravesaran la pared y crearan grietas visibles en el lugar donde se arrojaron las bombas.', 28153),
(150186, 'esMX', 'A volar.', 'A volar.', 28153),
(150185, 'esMX', 'Puedo volar. Encender en llamas el bosque no es mi estilo.', 'Puedo volar. Encender en llamas el bosque no es mi estilo.', 28153),
(150184, 'esMX', 'Que la Luz te acompañe.', '', 28153),
(150183, 'esMX', 'Has luchado... bien...', '', 28153),
(150181, 'esMX', '¡Luz! ¡Destruye a mi enemigo!', '', 28153),
(150180, 'esMX', '¡Por la Luz!', '', 28153),
(150179, 'esMX', '', 'No tan rápido.', 28153),
(150178, 'esMX', '', 'Atrás.', 28153),
(150177, 'esMX', '', '¡Terminemos con esto!', 28153),
(150176, 'esMX', '', '¡Hemos triunfado!', 28153),
(150175, 'esMX', '', '¡Qué aventura! ¡Una isla inexplorada con peligros desconocidos y tesoros ocultos! Un momento, ¿la Horda también está aquí?', 28153),
(150174, 'esMX', '', 'Veamos qué aventuras nos esperan por aquí. Lo único que nos resta es deshacernos de la Horda.', 28153),
(150173, 'esMX', '', '¡Moradores de la oscuridad, no prevalecerán! ¡La Venganza de la Luz los destrozará a todos!', 28153),
(150172, 'esMX', '', 'Qué gusto saludarte.', 28153),
(150171, 'esMX', '', 'La Luz... me redimirá...', 28153),
(150170, 'esMX', '', '¡No eres rival para nosotros!', 28153),
(150169, 'esMX', '<Kua\'fon te saluda con un graznido.>\n\n¡Riiii!', '', 28153),
(150168, 'esMX', '<Kua\'fon te apunta con la cabeza enérgicamente.>', '', 28153),
(150166, 'esMX', '<Kua\'fon gorgotea de felicidad al verte.>', '', 28153),
(150165, 'esMX', '', '¡Alimenten al Vacío con el alma de este ente!', 28153),
(150164, 'esMX', '<Kua\'fon inclina la cabeza a un costado al verte.>\n\n¿Riii?', '', 28153),
(150163, 'esMX', '', '¡AH! ¡POR EL VACÍO!', 28153),
(150162, 'esMX', '', '¡Aquí! ¡Aterrizaremos aquí, como dijeron los susurros! ¡Ah! ¡Sí! ¡Ja, ja, ja! Sí, sí, sí...', 28153),
(150161, 'esMX', '', '¿Qué? ¿Q-Quién dijo eso?', 28153),
(150160, 'esMX', '', 'Ja, ja, ja, ja... mi destino es el Vacío...', 28153),
(150159, 'esMX', '', '¡Ha llegado el festín, mascotas mías!', 28153),
(150158, 'esMX', '', '¡Almas exquisitas para el Vacío!', 28153),
(150157, 'esMX', '¡Siente la entropía!', '', 28153),
(150156, 'esMX', 'Patético.', '', 28153),
(150155, 'esMX', 'Los salvajes de la Horda ya están aquí. Ja, es como si tuvieran oportunidad de vencer al Vacío.', '', 28153),
(150154, 'esMX', '¡Kóbolds y Catacumbas!', '¡Kóbolds y Catacumbas!', 28153),
(150153, 'esMX', 'En Kóbolds y Catacumbas.', 'En Kóbolds y Catacumbas.', 28153),
(150152, 'esMX', 'Buscabas riqueza, te irás sin cabezaaaa...', 'Buscabas riqueza, te irás sin cabezaaaa...', 28153),
(150151, 'esMX', '¡y temes que este pozo sea tu tumbaaaaa!', '¡y temes que este pozo sea tu tumbaaaaa!', 28153),
(150150, 'esMX', '¡Dame fuerzas, Vacío!', '', 28153),
(150149, 'esMX', 'Los sientes venir, ya no hay dónde huir,', 'Los sientes venir, ya no hay dónde huir,', 28153),
(150148, 'esMX', 'Corre, no te detengas; los monstruos acechan. ¡Sigue el mapa y la salida encontrarás!', 'Corre, no te detengas; los monstruos acechan. ¡Sigue el mapa y la salida encontrarás!', 28153),
(150147, 'esMX', '¡Abraza el Vacío!', '', 28153),
(150146, 'esMX', 'Y si su luz te llevas, huye de esta cueva, ¡evita los obstáculos sin dudar!', 'Y si su luz te llevas, huye de esta cueva, ¡evita los obstáculos sin dudar!', 28153),
(150145, 'esMX', '¡TÚ NO LLEVAR VELA!', '¡TÚ NO LLEVAR VELA!', 28153),
(150144, 'esMX', '¡TÚ NO LLEVAR VELA!', '¡TÚ NO LLEVAR VELA!', 28153),
(150143, 'esMX', 'Tuyo será todo, si dejas un tesoroooo...', 'Tuyo será todo, si dejas un tesoroooo...', 28153),
(150142, 'esMX', 'No seas confiado, puedes quedar asado, ¡roba todo lo que tu corazón anhela!', 'No seas confiado, puedes quedar asado, ¡roba todo lo que tu corazón anhela!', 28153),
(150141, 'esMX', 'Tesoros sin fin, peligros por mil, y una escena que prueba tu valor.', 'Tesoros sin fin, peligros por mil, y una escena que prueba tu valor.', 28153),
(150140, 'esMX', 'Saludos.', '', 28153),
(150139, 'esMX', 'en busca de riquezas por doquier.', 'en busca de riquezas por doquier.', 28153),
(150138, 'esMX', 'Ahh... la oscuridad... me envuelve...', '', 28153),
(150137, 'esMX', 'Qué grupo tan patético. Prepárense para que los consuma.', '', 28153),
(150136, 'esMX', 'Vamos, sé que puedes hacerlo mejor.', '', 28153),
(150135, 'esMX', 'Vas con los mejores, exploras sin temores', 'Vas con los mejores, exploras sin temores', 28153),
(150134, 'esMX', 'y los grandes tesoros que encierran sus túneles a la espera de aventureros...', 'y los grandes tesoros que encierran sus túneles a la espera de aventureros...', 28153),
(150133, 'esMX', 'Ah... ¿Puedo hacer mi pose de victoria ahora? ¿Qué? ¿Primero tengo que matarlos? Bah, muy bien.', '', 28153),
(150132, 'esMX', 'Abundan leyendas de un vasto mundo bajo tierra...', 'Abundan leyendas de un vasto mundo bajo tierra...', 28153),
(150131, 'esMX', '¡Sí!', '¡Sí!', 28153),
(150130, 'esMX', '¡Oh, deben estar emocionados de verme! ¡Imagínense cómo se sentirán cuando hayan muerto!', '', 28153),
(150129, 'esMX', '¡Una nave de la Horda! Muero de ganas de verles las caras cuando se den cuenta de que estamos aquí.', '', 28153),
(150128, 'esMX', '¿Quieren cantar una canción, niños?', '¿Quieren cantar una canción, niños?', 28153),
(150127, 'esMX', 'Jijii.', 'Jijii.', 28153),
(150126, 'esMX', 'Ah... Bienvenidos.', '', 28153),
(150125, 'esMX', '¡Ja, ja!', '¡Ja, ja!', 28153),
(150124, 'esMX', '¡Por aquí!', '', 28153),
(150123, 'esMX', '¿Qué sucede? ¿No das abasto?', '', 28153),
(150122, 'esMX', '¡Iupi!', '¡Iupi!', 28153),
(150121, 'esMX', '¡A ellos!', '¡A ellos!', 28153),
(150120, 'esMX', '¡Ah! ¿Cómo me pudo pasar esto?', '', 28153),
(150119, 'esMX', '¡Oh, vaya!', '¡Oh, vaya!', 28153),
(150118, 'esMX', '¡SOY YO! No se preocupen, tendré piedad.', '', 28153),
(150117, 'esMX', 'Hola, Horda, soy Kelain. Es un placer encontrarlos aquí.', '', 28153),
(150116, 'esMX', '', '¡Fuera, plaga!', 28153),
(150115, 'esMX', 'Si te cruza\' con Grozztok, no dude\' en atravesar su corazón negro con una daga.', '', 28153),
(150114, 'esMX', '', '¡Basura miserable!', 28153),
(150113, 'esMX', '', '¿Cómo te atreves a mancharme de sangre? ¡Ten más cuidado!', 28153),
(150112, 'esMX', '', 'Ah, qué mala suerte... para ustedes, Alianza. Pronto sabrán cuál es su lugar.', 28153),
(150111, 'esMX', 'Grozztok merecía el fin que tuvo. Eh\'pero que lo hayas hecho sufrir.', '', 28153),
(150110, 'esMX', '', '¡Santo cielo! Esa no es forma de comportarse para una dama.', 28153),
(150109, 'esMX', 'Moriré en estas dunas... y lo tendré merecido.', '', 28153),
(150108, 'esMX', '', 'Tsk, tsk... Déjame ayudarte.', 28153),
(150107, 'esMX', '', 'Ah, eres tú. Hola.', 28153),
(150106, 'esMX', '', 'Un completo... fracaso...', 28153),
(150105, 'esMX', '', '¡Usen guantes! No debemos ensuciarnos las manos.', 28153),
(150104, 'esMX', '', 'Ey, ¡acabemos con esta basura!', 28153),
(150103, 'esMX', '', '¡SÍÍÍÍÍ! ¿Vieron eso, muchachos?', 28153),
(150102, 'esMX', '', 'Vamos, abandonemos esta nave de una vez. ¡Estamos perdiendo tiempo! ¡Vamos, VAMOS!', 28153),
(150101, 'esMX', '', '¿Por qué debo quedarme aquí cuando podría estar luchando?', 28153),
(150100, 'esMX', 'Con las llaves del sobrestante en nuestro poder, podemos liberar a nuestras tropas y usar sus habilidades para fortalecer nuestra campaña.', '', 28153),
(150099, 'esMX', '', '¡Jaja! ¡Buen intento!', 28153),
(150098, 'esMX', '', '¡Demasiado lento!', 28153),
(150097, 'esMX', 'La Dama Oscura estará complacida.', '', 28153),
(150096, 'esMX', '', '¡No es... justo! Ustedes son... horribles…', 28153),
(150095, 'esMX', '', '¡Todos! ¡Ataquen!', 28153),
(150094, 'esMX', '', '¡No puedes escapar de mí!', 28153),
(150093, 'esMX', '¡Ahora! ¡Eliminen a esta escoria!', '', 28153),
(150092, 'esMX', 'Mm. Un destino inevitable.', '', 28153),
(150091, 'esMX', 'Quítenle las llaves, aseguren nuestro objetivo y maten a todos los que se interpongan en su camino.', '', 28153),
(150090, 'esMX', 'Llegó la hora. Recuerden su entrenamiento y muéstrenles a los perros de la Alianza lo que significa ser altonato.', '', 28153),
(150089, 'esMX', 'Diríjanse al último piso, allí encontrarán al sobrestante.', '', 28153),
(150088, 'esMX', 'Concéntrense. Se acercan enemigos dignos. Y también la Alianza.', '', 28153),
(150087, 'esMX', 'Un escape reciente ha causado caos en los niveles inferiores de la prisión. Aprovechemos.', '', 28153),
(150086, 'esMX', 'La Alianza está aquí. Canalicen sus energías. No cometeremos errores.', '', 28153),
(150085, 'esMX', 'Nuestro objetivo está encerrado en Tol Dagor.', '', 28153),
(150084, 'esMX', 'Saludos.', '', 28153),
(150083, 'esMX', 'Rápido... Retirada...', '', 28153),
(150082, 'esMX', '¡Sigamos nuestro plan! ¡Al ataque!', '', 28153),
(150081, 'esMX', '¡Que caigan todos! ¡Sigan mis órdenes!', '', 28153),
(150080, 'esMX', '¡Oh, oh, oh! ¡Objetivo de alta prioridad!', '', 28153),
(150079, 'esMX', '¡Le di a uno! ¡Le di a uno!', '', 28153),
(150078, 'esMX', '¿Llegó la Horda? ¿E-están seguros de lo que dicen? Digo, tengo instrumentos delicados. Y son M-M-MMUY CAROS.', '', 28153),
(150077, 'esMX', '¡Hola!', '', 28153),
(150076, 'esMX', 'Yo tenía... razón... muchachos...', '', 28153),
(150075, 'esMX', '¡$n se ha cargado de poder por completo!', '¡$n se ha cargado de poder por completo!', 28153),
(150074, 'esMX', '¡$n comienza a rebosar de poder!', '¡$n comienza a rebosar de poder!', 28153),
(150073, 'esMX', '¡Fuera!', '', 28153),
(150072, 'esMX', 'El poder de $n vuelve a aumentar...', 'El poder de $n vuelve a aumentar...', 28153),
(150071, 'esMX', 'Oh, no, n-no. ¡Creo que no deberíamos estar haciendo esto!', '', 28153),
(150070, 'esMX', 'El poder de $n aumenta...', 'El poder de $n aumenta...', 28153),
(150069, 'esMX', '', '¡Médico!', 28153),
(150068, 'esMX', '¡Una chispa caótica ha caído en el campo de batalla!', '¡Una chispa caótica ha caído en el campo de batalla!', 28153),
(150067, 'esMX', '', 'Objetivo eliminado.', 28153),
(150066, 'esMX', 'Se ha formado un núcleo de energía en las cercanías.', 'Se ha formado un núcleo de energía en las cercanías.', 28153),
(150065, 'esMX', '', 'Preparados y listos, muchachos; la Horda está cerca. Primero disparen y luego busquen el botín.', 28153),
