(150063, 'esMX', '', 'Retrocedo.', 28153),
(150062, 'esMX', '¡Un ser de energía pura se forma en el aire frente a ti!', '¡Un ser de energía pura se forma en el aire frente a ti!', 28153),
(150061, 'esMX', '', 'Uf... eso duele...', 28153),
(150060, 'esMX', '', 'Los enemigos avanzan.', 28153),
(150059, 'esMX', '', '¡A la cabeza! ¡Es su punto débil!', 28153),
(150058, 'esMX', 'Llegó la hora de derribarlos.', '', 28153),
(150057, 'esMX', 'Nunca lleves un cuchillo a una pelea de mecas.', '', 28153),
(150056, 'esMX', '¡Han derribado a mi mecazancudo! ¡Retrocedan!', '', 28153),
(150055, 'esMX', '¡Mi mecazancudo ha caído! ¡Sáquenme de aquí, RÁPIDO!', '', 28153),
(150054, 'esMX', '$UAplastado:Aplastada;.', '', 28153),
(150053, 'esMX', 'Los únicos insectos buenos son los insectos muertos. Y ustedes se parecen mucho a los insectos.', '', 28153),
(150052, 'esMX', 'Históricamente, se han resuelto más conflictos con la violencia que con cualquier otra arma. Agreguemos otra marca a la lista.', '', 28153),
(150051, 'esMX', 'Llegó la Horda, así que escúchenme bien: hagan lo que tienen que hacer o les dispararé. ¡Formen filas!', '', 28153),
(150050, 'esMX', '¡Alístense hoy!', '', 28153),
(150049, 'esMX', '¡Fuego va!', '', 28153),
(150048, 'esMX', 'No me... decepciones...', '', 28153),
(150047, 'esMX', '¡Despierten! ¡Tenemos compañía!', '', 28153),
(150046, 'esMX', '¡NOS ATACAN!', '', 28153),
(150044, 'esMX', '¡A repararse!', '', 28153),
(150043, 'esMX', '¡Caven más rápido, los tesoros deben estar por aquí!', '¡Caven más rápido, los tesoros deben estar por aquí!', 28153),
(150041, 'esMX', 'Uh, ja. ¡Ja! ¡Bam!', '', 28153),
(150040, 'esMX', 'Afilen sus cuchillas; tenemos que encargarnos de algunos cadáveres. Vamos lento, despacio...', '', 28153),
(150039, 'esMX', '¿Qué quieres, eh?', '', 28153),
(150038, 'esMX', '¡Demasiado lento!', '', 28153),
(150037, 'esMX', 'No eres... nada...', '', 28153),
(150036, 'esMX', 'No parpadeen, miembros de la Alianza.', '', 28153),
(150035, 'esMX', '', 'Nueh\'tro pueblo siente temor del tipo de cambio\' que sugiere Talanji. Y cuando la gente siente temor, hace tonterías.', 28153),
(150034, 'esMX', '', 'Todos los cañones, ¡prepárense para disparar!', 28153),
(150033, 'esMX', '', 'Este juego es agotador. ¡Reduciré a Boralus a cenizas antes de permitirles ganar!', 28153),
(150032, 'esMX', '', '¡¿Cómo te atreves a herir a mi hermosa mascota?!', 28153),
(150031, 'esMX', '', 'Este será el próximo.', 28153),
(150030, 'esMX', '', 'Todo salió como estaba planeado.', 28153),
(150029, 'esMX', '', 'He planeado nuestra ruta a la perfección. Es audaz, eficiente y tiene todo lo que debe tener. Ahora, respetémosla.', 28153),
(150028, 'esMX', '', 'Qué armadura interesante. Aunque necesita más pinchos.', 28153),
(150027, 'esMX', '', 'Esto... no nos detendrá...', 28153),
(150026, 'esMX', '', '¡Zap!', 28153),
(150025, 'esMX', '', '¡Por Kul Tiras!', 28153),
(150024, 'esMX', '', 'No planearon nada muy bien que digamos, ¿verdad?', 28153),
(150023, 'esMX', '¡Aquí vamos de nuevo!', '', 28153),
(150022, 'esMX', '¡Jojojojo! ¡Es hora de triturar!', '', 28153),
(150021, 'esMX', '¡Ey! ¡Arreglar esa cosa no es barato!', '', 28153),
(150020, 'esMX', '', '¡Su puerta ha caído! ¡Irrumpan en la ciudad y asesinen a todos los que se me opongan!', 28153),
(150019, 'esMX', '¡Ah! ¡Porquería mal ensamblada!', '', 28153),
(150018, 'esMX', '¡Ja, ja, ja! ¡Clin caja!', '', 28153),
(150017, 'esMX', '¡Ah, parece que este lugar tiene mucho para ofrecer! Sombra, botín... ¿la Alianza? Bah, ya lo arruinaron todo.', '', 28153),
(150016, 'esMX', 'Se nos ha presentado una oportunidad de negocios. ¡Quizás hasta podamos vender a la Alianza como chatarra!', '', 28153),
(150015, 'esMX', '', 'Déjenme demostrarlo.', 28153),
(150014, 'esMX', '', '¡Disfruten de su victoria efímera, necios! Sin la flota kultirana, no tienen posibilidades de derrotarme.', 28153),
(150013, 'esMX', '¿Hueles eso? Botín. Muchísimo botín. ¡Preparen sus mochilas!', '', 28153),
(150012, 'esMX', '¡¿Qué onda?!', '', 28153),
(150011, 'esMX', 'Volverás... a verme...', '', 28153),
(150010, 'esMX', '', '¡Lo han logrado! Sin su gigante, las fuerzas de Aspafresno serán expulsadas de la ciudad.', 28153),
(150009, 'esMX', '¡Este bebé se construyó para eso!', '', 28153),
(150008, 'esMX', '¡Exterminador activado!', '', 28153),
(150007, 'esMX', '¡A la batalla!', '', 28153),
(150006, 'esMX', 'Uf, creo que se me fue un poco la mano.', '', 28153),
(150005, 'esMX', '*Bosteza* ¿Ya llegamos? Pero es el momento ideal para dormir una siesta.', '', 28153),
(150004, 'esMX', 'No tendría que hacer esto si dejáramos de pelear.', '', 28153),
(150003, 'esMX', 'Alguien tiene que lamerte las heridas.', '', 28153),
(150002, 'esMX', '¡Rrrr! ¡Hola!', '', 28153),
(150001, 'esMX', 'Al fin... hora de la siesta...', '', 28153),
(150000, 'esMX', '¡Hora de la siesta!', '', 28153),
(149999, 'esMX', '*Risa* ¡Huyan, perritos de la Horda! ¡No los perseguiremos!', '', 28153),
(149998, 'esMX', '', '¡Ponte a rezar, rata!', 28153),
(149997, 'esMX', '', '¡Parece que necesito una nueva presa!', 28153),
(149996, 'esMX', '', 'Ahhhh... Puedo sentir el aroma de la presa. ¡Me encanta la cacería!', 28153),
(149995, 'esMX', '', 'Hueles raro.', 28153),
(149994, 'esMX', '', 'Ah... El dulce aroma... de la sangre...', 28153),
(149993, 'esMX', '', 'Tan solo espera... ¡Tú sigues!', 28153),
(149992, 'esMX', '', '¡Apunten a la yugular!', 28153),
(149991, 'esMX', '¡Bien hecho, adalid! Estas tierras son más seguras gracias a tus esfuerzos.', '', 28153),
(149990, 'esMX', '¡A la garganta!', '', 28153),
(149989, 'esMX', '¡Ahora conocerán la fuerza de lo\' Zandalari!', '', 28153),
(149988, 'esMX', 'Puedo oler tu miedo.', '', 28153),
(149987, 'esMX', '¡Ja! ¡Eso me encantó!', '', 28153),
(149986, 'esMX', '¡La Horda! Los aplastaremos. ¡Qué comience la cacería! *aúlla*', '', 28153),
(149985, 'esMX', 'Nuestros espías han encontrado una amenaza peligrosa en el área. ¡Búscala y elimínala!', '', 28153),
(149984, 'esMX', '*Olfatea* ¡La Horda! Me gustaría tener el viento a favor...', '', 28153),
(149983, 'esMX', '', 'Da igual. ¡Mis cañones pronto harán polvo a la oposición!', 28153),
(149982, 'esMX', 'No se alejen mucho de la manada. Huelo algo fétido en el aire.', '', 28153),
(149981, 'esMX', '*gruñe*', '', 28153),
(149980, 'esMX', 'Perro grande... nunca muere...', '', 28153),
(149979, 'esMX', '¡Se arrepentirá de eh\'ta herejía! ¡Di chuka Rezan!', '', 28153),
(149978, 'esMX', '¡Háganlos pedazos!', '', 28153),
(149977, 'esMX', '*Aúlla* ¡Jauría, al ataque!', '', 28153),
(149976, 'esMX', '', '¡Sí! ¡La cabeza e\' mía! Ja, ja, ja.', 28153),
(149975, 'esMX', '', 'Ooh, eh\'ta isla promete mucho... Aléjense de aquí; tengo que hacer algo de vudú...', 28153),
(149974, 'esMX', '', 'Te arreglaré.', 28153),
(149973, 'esMX', '', '¡Oh! ¡Ja, ja! ¡Qué linda cabeza tienes! ¿Me la puedo quedar cuando te muera\'?', 28153),
(149972, 'esMX', '', '¡Ja, ja! Oh, pero lo\' Lanza Negra... nunca mueren... ja, ja.', 28153),
(149971, 'esMX', '', '¡Aojado eh\'tá\'! ¡Ja, ja, ja!', 28153),
(149970, 'esMX', '', '¡Ja, ja, ja! ¡Eh\'tás condenado!', 28153),
(149969, 'esMX', '', '¡Ehh, tú! ¡Déjame rebanarte la cabeza!', 28153),
(149968, 'esMX', 'Eh\'te es mío...', '', 28153),
(149967, 'esMX', 'Parece que te atrapé.', '', 28153),
(149966, 'esMX', 'Eh\'ta es una isla muy bella, me pregunto qué encontraremo\' aquí...', '', 28153),
(149965, 'esMX', '¿Qué quiere\'?', '', 28153),
(149964, 'esMX', 'Voy a... deh\'cansar un poco...', '', 28153),
