(149961, 'esMX', '', '¡RAAARRR!', 28153),
(149960, 'esMX', '', '¡Má\' sangre!', 28153),
(149959, 'esMX', '', '¡Más! ¡Tráiganme má\'!', 28153),
(149958, 'esMX', '', 'Equipos... tácticas... Bah... ¡Mátenlos a todo\'! ¡Raaarrr!', 28153),
(149957, 'esMX', '', '¡La Alianza! ¡Ja! ¡Mátenlos a todo\'! Y tráiganme sus corazone\'...', 28153),
(149956, 'esMX', '', '¡Adelante! ¡Arránquenle\' todas las extremidade\'! ¡Habrá sangre por toda\' partes! ¡Ja, ja, ja!', 28153),
(149955, 'esMX', '', '¿Qué?', 28153),
(149954, 'esMX', '', 'Muero... como una guerrera... *escupe*', 28153),
(149953, 'esMX', '', '¡Arránquenle\' los brazo\'!', 28153),
(149952, 'esMX', '¿Me extrañaste?', '', 28153),
(149951, 'esMX', '¡Congélate!', '', 28153),
(149950, 'esMX', 'Vaya, vaya... Hola.', '', 28153),
(149949, 'esMX', 'Bien... hecho...', '', 28153),
(149948, 'esMX', '¡Una muerte más en mi lista! Sin duda llevo la delantera.', '', 28153),
(149947, 'esMX', '¡Hagámoslo!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'esMX', 'Primero tendrás que comprarte un rostro nuevo.', 'Primero tendrás que comprarte un nuevo rostro.', 28153),
(149945, 'esMX', '', 'Tus ojos transmiten incertidumbre, $n.\n\nTe permitiré que hagas preguntas sobre mis planes, si así lo deseas.', 28153),
(149944, 'esMX', 'Jefa de guerra, ¿puedo preguntar por qué queremos capturar Teldrassil?', 'Jefa de guerra, ¿puedo preguntar por qué queremos capturar Teldrassil?', 28153),
(149943, 'esMX', '¿Una oportunidad?', '¿Una oportunidad?', 28153),
(149942, 'esMX', 'No podemos saberlo, Jefa de Guerra.', 'No podemos saberlo, Jefa de Guerra.', 28153),
(149940, 'esMX', '', 'Pero hay algo seguro: la Alianza usará Darnassus como puerto seguro para enviar azerita a los Reinos del Este. Anduin Wrynn construirá armas nuevas y poderosas, y tarde o temprano las usará contra nuestras tierras. Primero atacará Entrañas y Lunargenta, y luego posará la vista en Kalimdor.\n\nPor el bien de la Horda y su futuro, debemos actuar primero.\n\nSi ocupamos Darnassus, controlaremos el flujo de azerita y nos aseguraremos de que no la usen contra nosotros. La Alianza no se atreverá a atacar su propia ciudad si teme herir civiles.\n\nCon un solo golpe, garantizaremos generaciones de paz.', 28153),
(149939, 'esMX', '', 'Desperdiciar el tiempo es un lujo que no podemos darnos, pero respeto tu deseo de aprender más sobre el tema.\n\n<Sylvanas señala Silithus en el mapa>.\n\nESTO ha alterado para siempre el equilibrio de poder en Azeroth.\n\nSe están avistando depósitos de azerita por todo el mundo, $n. Aunque aún no comprendemos todo su potencial, está claro que esta sustancia tiene un potencial destructivo enorme.\n\n¿Cómo serán las guerras dentro de veinte años? ¿Y dentro de cien?\n\n¿Cómo puede la Horda defender sus fronteras si la Alianza controla el flujo de azerita?', 28153),
(149938, 'esMX', '', '¿Tienes alguna pregunta para mí, $n?', 28153),
(149937, 'esMX', 'Los infieles tienen bestias salvajes enjauladas en las cercanías. En mi opinión, es una buena oportunidad.', '', 28153),
(149936, 'esMX', 'Parece que ha llegado la Horda. Esto se va a poner... interesante.', '', 28153),
(149935, 'esMX', 'No puedes alejarte de mí, ¿verdad?', '', 28153),
(149934, 'esMX', '¡A congelarlos, muchachos!', '', 28153),
(149933, 'esMX', 'Hola, preciosura.', '', 28153),
(149932, 'esMX', '¡Auch! Buen golpe... Hasta... la próxima...', '', 28153),
(149931, 'esMX', '¡Ja! ¡Otro para mí!', '', 28153),
(149930, 'esMX', '¡Mi cuerpo está listo!', '', 28153),
(149929, 'esMX', 'Aunque... estas armas nos darán una ventaja mucho mayor.', '', 28153),
(149928, 'esMX', '¿Te gustan mis nuevas alas? ¡Son tan rápidas que ningún waku se puede ocultar de mí!$b$bTampoco los makakus.$b$b$b$bAsquerosos makakus.', '', 28153),
(149927, 'esMX', 'Los wakus de Zandalar son rarus. Muy jeringosamente salados, y a veces hablan.', '', 28153),
(149926, 'esMX', '¡La Horda! Por fin algo de acción. ¡Será mejor que me quite la camisa para esta pelea!', '', 28153),
(149925, 'esMX', 'Kua\'fon chilla de alegría y devora la comida que le ofrecen.', '', 28153),
(149924, 'esMX', 'Kua\'fon huele la comida antes de devorarla con entusiasmo.', '', 28153),
(149923, 'esMX', 'Kua\'fon atrapa la comida en el aire.', '', 28153),
(149922, 'esMX', 'Kua\'fon se abalanza sobre la comida que le ofrecen y la traga de un bocado.', '', 28153),
(149921, 'esMX', 'Miles de secretos hay, misteriosos y divinos. Tú tienes los tuyos, yo tengo los míos.', '', 28153),
(149920, 'esMX', '¿Riiii?', '', 28153),
(149919, 'esMX', '¡RIIII!', '', 28153),
(149918, 'esMX', '¡Riiii!', '', 28153),
(149917, 'esMX', 'RIIIII.', '', 28153),
(149916, 'esMX', '¿Un hozen que vuela? ¿Cómo es posible?', '¿Un hozen que vuela? ¿Cómo es posible?', 28153),
(149915, 'esMX', '¡Es hora de una retirada táctica!', '', 28153),
(149914, 'esMX', '¡Déjame arreglar eso!', '', 28153),
(149913, 'esMX', 'Ah, hola. ¿Vienes a deleitar tus ojos?', '', 28153),
(149912, 'esMX', 'Estamos un poco escaso\' de suministros, pero puedo conseguirte algunas cosa\'. Si nos ayudas, haré todo lo posible para conseguirte artículos de calidad.', 'Estamos un poco escaso\' de suministros, pero puedo conseguirte algunas cosa\'. Si nos ayudas, haré todo lo posible para conseguirte artículos de calidad.', 28153),
(149911, 'esMX', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Croquetas para dinosaurios ecológicas]|h|r>', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Croquetas para dinosaurios ecológicas]|h|r>', 28153),
(149910, 'esMX', 'Tenemos el mejor lugar, el tesoro está aquí.', 'Tenemos el mejor lugar, el tesoro está aquí.', 28153),
(149909, 'esMX', 'Nos volveremos... a ver...', '', 28153),
(149908, 'esMX', '<Kua\'fon busca comida entre tus manos.>\n\n¿Riii? RIIII.', '', 28153),
(149907, 'esMX', 'Aprenderás a comportarte.', '', 28153),
(149906, 'esMX', '¡Fuera! ¡Perros asquerosos de la Horda!', '', 28153),
(149905, 'esMX', '¡No podrás con mis tácticas!', '', 28153),
(149904, 'esMX', 'La Horda... Apestosos, sin imaginación y ni una pizca de intelecto. ¿Cómo encontraron esta isla? Por accidente, sin duda.', '', 28153),
(149903, 'esMX', 'Hablaré despacio para que la Horda me entienda. Isla ser nuestra. Ustedes ir afuera. ¿Así me entienden?', '', 28153),
(149902, 'esMX', '¡Bestias de la Horda! Aceptaremos su rendición, siempre que entreguen toda la azerita. Espero que tengan capacidad intelectual para apreciar mi oferta.', '', 28153),
(149901, 'esMX', '', '¿Sí? ¿Te conozco?', 28153),
(149900, 'esMX', '', '¡Aj! ¿Así se visten siempre los perros de la Alianza? Deberían irse... ¡antes de morir de vergüenza!', 28153),
(149899, 'esMX', '', '¿De verdad esa es la nave de la Alianza? ¿Acaso la atacó un gigante de mar o siempre luce así?', 28153),
(149898, 'esMX', '¿Soy yo o aquí hace calor? Estoy bromeando... ¡Claro que soy yo!', '', 28153),
(149897, 'esMX', '¡Rostizado!', '', 28153),
(149896, 'esMX', '¡Más incineración!', '', 28153),
(149895, 'esMX', '¡Provoquemos algunos incendios!', '', 28153),
(149894, 'esMX', 'Sabotearé sus cañones en el nivel superior mientras incendias el barranco. Te veré en sus jaulas de bestias cuando termines.', '', 28153),
(149893, 'esMX', '', '¡Agh! ¡Si tan solo pudiera matarlos sin mirarlos!', 28153),
(149892, 'esMX', 'Ahoguen su hedor en el océano o báñense en mis llamas. ¡Ustedes deciden, Alianza!', '', 28153),
(149891, 'esMX', '¡Ja! ¿Qué es ese olor? Ah... La Alianza envió a sus \"mejores\" guerreros. ¿Saben por qué apestan? Porque se la pasan comiendo queso.', '', 28153),
(149890, 'esMX', 'Que la Luz te bendiga.', '', 28153),
(149889, 'esMX', 'Peleaste bien, pero yo peleé mejor.', '', 28153),
(149888, 'esMX', 'Retrocedo.', '', 28153),
(149887, 'esMX', '¡Que la Luz te sane!', '', 28153),
(149886, 'esMX', 'Ahh, la Alianza. Y yo que estaba tan contento. ¿Qué tal si me dan otra alegría y se retiran?', '', 28153),
(149885, 'esMX', 'Esta isla es nuestra, Alianza. Si la abandonan, no será necesario recurrir a la violencia.', '', 28153),
(149884, 'esMX', '¡El enemigo está cerca!', '', 28153),
(149883, 'esMX', '¡$n empieza a lanzar una sanación superior!', '¡$n empieza a lanzar una sanación superior!', 28153),
(149882, 'esMX', '', 'Encuentren uno o invéntenlo. El tiempo es un lujo que no nos podemos dar.', 28153),
(149881, 'esMX', '', 'Entonces está resuelto. Colmillosauro, Nathanos: partirán de inmediato.', 28153),
(149880, 'esMX', 'La mayoría de los contrabandistas prefieren no llamar la atención del alto señor supremo... pero creo que podemos convencer a uno de que nos ayude.', '', 28153),
(149879, 'esMX', 'No soy tan ingenuo. Es muy poco probable que Vista Eterna reciba todos sus cargamentos legítimamente. Alguien debe estar usando una ruta oculta a través de Frondavil.', '', 28153),
(149878, 'esMX', '¿Disculpa?', '', 28153),
(149877, 'esMX', 'Mmmm... ¿A cuántos contrabandistas conoces, Clamañublo?', '', 28153),
(149876, 'esMX', '', 'Acorralaremos a Malfurion.', 28153),
(149875, 'esMX', '', 'Colmillosauro, lleva un escuadrón a Frondavil. Busca un camino por la montaña para llegar a Costa Oscura, pero deja las armas de asedio bajo mi mando.', 28153),
(149874, 'esMX', '', 'Parece que los fuegos fatuos son susceptibles a las distracciones. Explotaremos esta debilidad para pasar sin que nos vean.', 28153),
(149873, 'esMX', 'Jefa de Guerra, no hay ningún camino seguro por Frondavil.', '', 28153),
(149872, 'esMX', '', 'Zuldazar, una de las pocas ciudades que sobrevivió al Gran Cataclismo y sigue de pie. En el pináculo de su historia, el Imperio zandalari gobernaba la mitad del mundo. En Suramar, aún les advertimos a los más pequeños que se cuiden de los trols y sus magias oscuras.\n\nLos vimos actuar como salvajes sedientos de sangre. Pero al ver esto... No puedo evitar preguntarme quién en realidad necesita a quién: si la Horda a los zandalari o los zandalari a la Horda.', 28153),
(149871, 'esMX', '', 'La furia de los vulperas emerge de las arenas para clamar venganza. ¡Y la tendremos!', 28153),
(149870, 'esMX', '', '¡La muerta llama a sus puertas, infieles!', 28153),
(149869, 'esMX', '', 'A Zoram\'gar, ¡rápido!', 28153),
(149868, 'esMX', 'La ceremonia está lista para comenzar.', 'La ceremonia está lista para comenzar.', 28153),
(149867, 'esMX', 'Bueno, esto es un poco vergonzoso.\n\nVerá, tenía mi discurso escrito en mi cuaderno, pero parece que lo he... perdido.\n\nDebe estar en esta habitación. Si me ayudara a encontrarlo, ¡estaré muy agradecido!', '', 28153),
(149866, 'esMX', 'Oh, hola. Me temo que no nos hemos conocido, pero le agradezco que haya venido por mi querida Lucy.\n\n¿Cómo puedo $gayudarlo:ayudarla;?', '', 28153),
(149865, 'esMX', 'No te preocupe\', ¡Vaza se encargará de ti en Nazmir!', '', 28153),
(149864, 'esMX', 'Lucille no sabe que yo siempre la visitaba cuando venía a Bosquealbo. \n\nSu desconcierto por lo que sucedió en este lugar debe impedir que vea mi espíritu. Espero que parte de ella sepa que estoy aquí.', '', 28153),
(149858, 'esMX', 'Y ahora tú también debes morir. Que Sethraliss te perdone.', '', 28153),
(149857, 'esMX', '¡PARECE QUE TENEMOS UNA GRESCA!', '¡PARECE QUE TENEMOS UNA GRESCA!', 28153),
(149856, 'esMX', 'Kua\'fon devora el pescado.', '', 28153),
(149855, 'esMX', 'Kua\'fon huele el pescado con recelo.', '', 28153),
(149854, 'esMX', '<Ofrecerle carne de aletardiente.>', '<Ofrecerle carne de aletardiente.>', 28153),
(149853, 'esMX', '<Kua\'fon se encoje, temerosa, y se aparta con timidez a medida que te acercas.>$b$bMe parece que necesita algún incentivo. ¿Un bocadillo tal vez?', '', 28153),
(149852, 'esMX', 'Siempre...', '', 28153),
(149851, 'esMX', 'Siempre estaré aquí, querida Lucy...', '', 28153),
(149850, 'esMX', '', 'Oh, Alexander... ojalá estuvieras aquí...', 28153),
(149849, 'esMX', 'Gracias, $Uamigo:amiga;.', '', 28153),
(149848, 'esMX', 'Finalmente... Puedo dejar atrás los recuerdos de este lugar.', '', 28153),
(149847, 'esMX', 'No, viejo amigo. Nuestro pueblo está muerto, por tu culpa.', '', 28153),
(149846, 'esMX', 'No obligué a nadie a seguirme, Vorrik... Nuestro pueblo ansía la conquista...', '', 28153),
(149845, 'esMX', 'Te arrepentirás... de haber visto esto...', 'Te arrepentirás... de lo que viste...', 28153),
(149844, 'esMX', 'Lady Tarjasenda es una enemiga poderosa...', 'Lady Tarjasenda es una enemiga poderosa...', 28153),
(149843, 'esMX', '', '¡Será mejor que lo hagas!', 28153),
(149842, 'esMX', 'No se preocupe, yo me ocuparé de este insecto.', 'No se preocupe, yo me ocuparé de este insecto.', 28153),
(149841, 'esMX', '', '¡Idiota! ¡No puede haber testigos!', 28153),
(149840, 'esMX', 'Parece que tenemos visitas...', 'Parece que tenemos visitas...', 28153),
(149839, 'esMX', 'Siempre es un placer hacer negocios con usted, milady.', 'Siempre es un placer hacer negocios con usted, milady.', 28153),
(149838, 'esMX', '', 'Aquí está tu dinero, forajido. ¡Tómalo antes de que alguien te vea!', 28153),
(149837, 'esMX', '¡Una emboscada! ¡Lucy, ponte detrás de mí! ¡Guardias, a las armas!', '', 28153),
(149836, 'esMX', '', '¡Alexander, no!', 28153),
(149835, 'esMX', 'Nada personal, niño.', 'Nada personal, muchacho.', 28153),
(149834, 'esMX', 'Alexander, ¿has preparado el...? Un momento, ¡¿qué fue eso?!', '', 28153),
(149833, 'esMX', 'En mi rol de gobernador de Drustvar —y de orgulloso padre de Lucille—, es un honor unir en matrimonio a estas dos personas en presencia de la tierra, el cielo y el mar.', '', 28153),
(149832, 'esMX', 'Amigos, familiares e invitados de honor. Nos hemos reunido en este bello día de otoño para celebrar la unión de Lucille y Alexander.', '', 28153),
(149831, 'esMX', 'Muy bien.', '', 28153),
(149830, 'esMX', '', 'Por supuesto, padre. Por favor.', 28153),
(149829, 'esMX', '¿Comenzamos?', '', 28153),
(149828, 'esMX', 'Bajará pronto. Me pidió que yo comience con la ceremonia en su lugar.', '', 28153),
(149827, 'esMX', '', 'Está bien, padre. ¿Dónde está mi madre?', 28153),
(149826, 'esMX', 'Pido disculpas por mi tardanza.', '', 28153),
(149825, 'esMX', 'Pero, ¿dónde está Lady Tarjasenda?', '', 28153),
(149824, 'esMX', '', '¡Ahí viene!', 28153),
(149823, 'esMX', 'Ah, y pídeles disculpas por la demora.', '', 28153),
(149822, 'esMX', 'Infórmale a la pareja feliz que pronto estaré con ellos.', '', 28153),
(149821, 'esMX', '¡Lo has encontrado! ¡Gracias a las mareas!', '', 28153),
(149820, 'esMX', '', '¿Por qué te empeñas en hacernos perder el tiempo?', 28153),
(149819, 'esMX', '', 'Buscamos un libro. ¿Realmente crees que no revisamos en la estantería?', 28153),
(149818, 'esMX', '', '¿Por qué mi marido pondría su cuaderno en la mochila de Lucille? ¿Qué tienes en la cabeza?', 28153),
(149817, 'esMX', 'Creo que no lo dejé entre las cartas de Lucy, pero no está de más revisar.', '', 28153),
(149816, 'esMX', 'Si bien agradezco mucho tu ayuda, debo pedirte que no revuelvas la ropa interior de mi hija...', '', 28153),
(149815, 'esMX', '', 'Su corazón contradice los intereses de nuestra casa...', 28153),
(149814, 'esMX', 'Lucy solo sigue su corazón, Meredith. Es lo mismo que hice yo cuando me casé contigo.', '', 28153),
(149813, 'esMX', '', 'Te digo, Arthur, que no deberías permitir esto. ¡¿Nuestra hija se casará con un simple mercader?!', 28153),
(149812, 'esMX', '', 'Muchas gracias por venir. Es un honor que estés con nosotros.', 28153),
(149811, 'esMX', '¿Por qué has venido?', '', 28153),
(149810, 'esMX', '¿Lucy? Has venido... Espera, tú no eres Lucy.', '', 28153),
(149809, 'esMX', 'Tampoco tú. A tu padre no le guh\'ta que hayas traído a eh\'tas criatura\'. Me ha ordenado que venga a buh\'carte.', '', 28153),
(149807, 'esMX', 'Me aseguré mi victoria, pase lo pase. El general Jakra\'zet ya tiene mi llave... Y supongo que ahora también tiene la tuya.', '', 28153),
(149806, 'esMX', '¿Qué has hecho, Korthek?', '', 28153),
(149805, 'esMX', 'Me pregunto algo, Vorrik... Si tú estás aquí, ¿quién cuida las llaves en tu templo?', '', 28153),
(149804, 'esMX', '', 'Existo para defender a mi pueblo. ¡Esta escoria te matará!', 28153),
(149803, 'esMX', '¡Escoria vulpera, existes para servir a mi imperio!', '', 28153),
(149802, 'esMX', '', '', 28153),
(149801, 'esMX', '¡Me compraré una dentadura nueva, hecha de oro!', '¡Me compraré una dentadura nueva, hecha de oro!', 28153),
(149800, 'esMX', 'Mantendremos sellada la prisión de Mythrax y uniré a nuestro pueblo.', '', 28153),
(149799, 'esMX', 'Estamos haciendo todo el trabajo, deberíamos quedarnos con todo el oro.', 'Estamos haciendo todo el trabajo, deberíamos quedarnos con todo el oro.', 28153),
(149798, 'esMX', 'No. Tú eres nuestro fracaso. Sethraliss se sacrificó para que pudiésemos vivir en paz.', '', 28153),
(149797, 'esMX', '¡Yo soy el verdadero poder de los sethrak!', '', 28153),
(149796, 'esMX', 'Más vale que nadie intente robarme mi parte.', 'Más vale que nadie intente robarme mi parte.', 28153),
(149795, 'esMX', 'Si lo encuentro, ¡me largo con el tesoro!', 'Si lo encuentro, ¡me largo con el tesoro!', 28153),
(149794, 'esMX', '¡Le darán una parte extra al primero que lo encuentre!', '¡Le darán una parte extra al primero que lo encuentre!', 28153),
(149793, 'esMX', 'Tres millones en monedas de oro, ¡seremos ricos!', 'Tres millones en monedas de oro, ¡seremos ricos!', 28153),
(149792, 'esMX', '¿Quizás estamos excavando en el lugar equivocado?', '¿Quizás estamos excavando en el lugar equivocado?', 28153),
(149791, 'esMX', 'Me compraré un castillo con baños calientes y sirvientes.', 'Me compraré un castillo con baños calientes y sirvientes.', 28153),
(149790, 'esMX', 'Nedly dice que nos estamos acercando, ya falta poco.', 'Nedly dice que nos estamos acercando, ya falta poco.', 28153),
(149789, 'esMX', '¡Compraré un bote más grande que todos los de la flota!', '¡Compraré un bote más grande que todos los de la flota!', 28153),
(149788, 'esMX', '¿Cuánto es la doscientosesentaisieteava parte de tres millones?', '¿Cuánto es la doscientosesentaisieteava parte de tres millones?', 28153),
(149787, 'esMX', '¡Es tanto que Jaina Valiente se casará conmigo por dinero!', '¡Es tanto que Jaina Valiente se casará conmigo por dinero!', 28153),
(149786, 'esMX', '', '...Bueno, a veces pasa eso, sí.', 28153),
(149785, 'esMX', '', 'Por primera vez, sentirá el viento bajo sus alas. ¡El placer de volar! El...', 28153),
(149784, 'esMX', '', 'Ah... ¡alguien más que responde al llamado de los cielos!', 28153),
(149783, 'esMX', 'Vuelve pronto. Debemos atacar al emperador Korthek cuanto antes.', '', 28153),
(149782, 'esMX', 'Me quedaré preparando el asalto mientras siembras el caos entre los infieles.', '', 28153),
(149781, 'esMX', '<Empuja a la cría fuera del nido.>', '<Empuja a la cría fuera del nido.>', 28153),
(149779, 'esMX', '[Escena de cliente: Taelia acusa a Lady Aspafresno de estar detrás del ataque. ¿No lo ves,, Katherine? Su plan siempre fue reemplazarte. Katherine se vuelve hacia Priscilla: ¿Es cierto? Priscilla deja de fingir suavidad y compasión, y le habla con dureza a Katherine: ¡Eres débil! ¡Indigna de gobernar! ¡Aspafresno CREÓ esta ciudad! Le dispara a Katherine con su pistola. Los guardias entran en acción. Priscilla les dispara a los barriles colocados sobre un carro cerca de la multitud y se genera una nube de humo que rápidamente envuelve la plaza. Se desata el caos.]', '[Escena de cliente: Taelia acusa a Lady Aspafresno de estar detrás del ataque. ¿No lo ves,, Katherine? Su plan siempre fue reemplazarte. Katherine se vuelve hacia Priscilla: ¿Es cierto? Priscilla deja de fingir suavidad y compasión, y le habla con dureza a Katherine: ¡Eres débil! ¡Indigna de gobernar! ¡Aspafresno CREÓ esta ciudad! Le dispara a Katherine con su pistola. Los guardias entran en acción. Priscilla les dispara a los barriles colocados sobre un carro cerca de la multitud y se genera una nube de humo que rápidamente envuelve la plaza. Se desata el caos.]', 28153),
(149778, 'esMX', 'Vorrik, estoy listo para enfrentar al emperador Korthek.', 'Vorrik, estoy lista para enfrentar al emperador Korthek.', 28153),
(149777, 'esMX', '', 'Mi botín... noooo...', 28153),
(149776, 'esMX', '¡Destroza este navío maldito y libera a nuestro pueblo!', '', 28153),
(149775, 'esMX', '', 'Qué arma más brillante que tiene\'. ¡Más tesoro\' para mí!', 28153),
(149774, 'esMX', '¡Tormentas del mar, escuchen mi llamado!', '', 28153),
(149772, 'esMX', 'Me impresionas, \"viejo amigo\". ¡Pero eso no bastará para detenerme!', '', 28153),
(149771, 'esMX', 'La llave está oculta dentro de mi fortaleza, Vorrik. ¿Creías que la llevaría encima como un tonto?', '', 28153),
(149770, 'esMX', 'Debo decir que en algo tienes razón. ¡Ya no es hora de hablar!', '', 28153),
(149769, 'esMX', 'Basta de hablar, viejo amigo. Entrega tu llave de la prisión de Mythrax. ¡Nos destruirás a todos!', '', 28153),
(149768, 'esMX', '¡Enfrentas el poder de Korthek, el emperador eterno!', '', 28153),
(149767, 'esMX', 'Ya está, ahora puedo robar el poder de este pináculo. A la puerta, ¡deprisa!', '', 28153),
(149766, 'esMX', '', '¡Por la arena del desierto, qué alegría verte, $p! No entiendo nada de nada...', 28153),
(149765, 'esMX', '', 'Es difícil seguirle el paso a Kiro. Siempre está en movimiento, siempre trabajando en algún plan importante.\n\nPartió junto a Nisha. Pero lo último que supe es que se dirigía al barranco a robar algunos suministros, sabotear los cañones o algo así.', 28153),
(149764, 'esMX', '', 'Nisha ha estado causando un gran alboroto en el campamento de esclavos. Dirígete al oeste al salir de la cueva y sigue por la primera rampa que encuentres a la derecha.\n\nSi tienes dudas, escucha los sonidos de los sethrak que agonizan y ve hacia ellos. Ella estará cerca.', 28153),
(149763, 'esMX', '', '¡Oh, esa es la mejor parte! Seguro que no los viste mientras venías aquí, ¿verdad?\n\n¡Los escurridizos vulperas están ocultos por toda la ruta de escape, para vigilar a los infieles!\n\nCuando me informan que no hay peligro en el camino, yo guío a algunos de los vulperas y nos reunimos con las caravanas que los llevan a un lugar seguro.\n\nLuego me escondo de nuevo y me preparo para llevar otro grupo. Es muy emocionante, ¡y solo he llorado de miedo tres veces hasta ahora!\n\nSi tienes que marcharte, sal de la cueva y dirígete al oeste. Cruza el puente en ruinas y podrás ir a dónde quieras.', 28153),
(149762, 'esMX', '', 'Igual que tú, supongo. Mira a los vulperas aquí... Están heridos y necesitan a alguien que los ayude.\n\nLos infieles han esclavizado a muchos de nosotros y nos han obligado a trabajar y pelear por ellos.\n\nNunca antes habíamos podido detenerlos. Pero Nisha y Kiro nos han demostrado que podemos defendernos.\n\nPor las noches, Kiro y los demás se escabullen en el campamento de esclavos y rescatan a los vulperas más vulnerables.\n\nLos traen hasta aquí y luego yo los guío a través de las dunas, donde las caravanas los esperan para llevarlos a un lugar seguro.\n\nEs peligroso, y preferiría estar en el campamento, escuchando las canciones de Ahna junto a una fogata. ¿Pero cómo podría hacer eso sabiendo que mis amigos necesitan mi ayuda?', 28153),
(149761, 'esMX', 'Me gustaría saber algo más.', 'Me gustaría saber algo más.', 28153),
(149760, 'esMX', '¿Dónde está Nisha?', '¿Dónde está Nisha?', 28153),
(149759, 'esMX', '¿Dónde está Kiro?', '¿Dónde está Kiro?', 28153),
(149758, 'esMX', '¿Cómo haces para sacar a los esclavos?', '¿Cómo haces para sacar a los esclavos?', 28153),
(149757, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(149756, 'esMX', '', '¡$p! ¡Sabía que vendrías! Les dije: \"$p se preocupa por los vulperas y no nos abandonará\".\n\n¡Yo también vine a ayudar! Kiro y Nisha están rescatando esclavos vulperas, y yo estoy a cargo de organizar caravanas para sacarlos de allí.\n\nEs un poco intimidante estar tan cerca de los sethrak. Pero sé que es lo correcto. Nisha lo dijo.\n\nOh, y $ubienvenido:bienvenida; a nuestro pequeño escondite.', 28153),
(149755, 'esMX', 'Muéstrame el camino.', 'Muéstrame el camino.', 28153),
(149754, 'esMX', 'Si estás mintiendo, te colgaré', 'Si estás mintiendo, te colgaré', 28153),
(149753, 'esMX', 'Estoy contigo.', 'Estoy contigo.', 28153),
(149752, 'esMX', '', 'Nuestras fuerzas le darán un buen uso a esto\' suministros. ¡Bien hecho!', 28153),
(149751, 'esMX', '', 'Hemos ubicado un naufragio saqueado por lo\' trols de sangre. ¡Apodérate de su cargamento ante\' de que los trols de sangre lo hagan!', 28153),
(149750, 'esMX', 'Será mejor que valga la pena.', 'Será mejor que valga la pena.', 28153),
(149749, 'esMX', 'Mmm... De acuerdo, vamos.', 'Mmm... De acuerdo, vamos.', 28153),
(149748, 'esMX', '¡¿Qué?! Será mejor que estés en lo cierto...', '¡¿Qué?! Será mejor que estés en lo cierto...', 28153),
(149747, 'esMX', 'Bueno, mi fiel $gescudero:escudera;, parece que nuestro trabajo aquí terminó. Si me disculpas, tengo un ettin que derribar.', '', 28153),
(149746, 'esMX', '¡Un bandido! ¡No temas, doncella, yo seré tu escudo!', '', 28153),
(149745, 'esMX', '¿Demonio astral? ¡No permitiré que insulten a Segismundo el Segundo así! Prepárate para probar la grandeza de Johnny— ¿Acabo de ver un ettin?', '', 28153),
(149744, 'esMX', '¡Veo que has tenido un encuentro desafortunado con este demonio astral! ¡Te congratulo por avasallarlo por tu cuenta! ¿Te han herido?', '', 28153),
(149743, 'esMX', '', 'El pueblo está perdiendo la fe en Katherine...', 28153),
(149742, 'esMX', '', 'Perfecto... Quizás tengamos que armar un alboroto.', 28153),
(149741, 'esMX', '', 'Primer paso: iniciar una revuelta.', 28153),
(149740, 'esMX', 'Es suficiente. ¡Mythrax se alzará y ustedes, traidores, perecerán!', '', 28153),
(149739, 'esMX', 'Las llaves serán nuestras... ¡Y Mythrax se alzará!', '', 28153),
(149738, 'esMX', 'Segismundo el Segundo... ¿Por qué no volaste?', '', 28153),
(149737, 'esMX', 'Comenzaré y... ¡Ahí están! ¡Las fuerzas de Korthek!', '', 28153),
(149736, 'esMX', 'Estoy listo para defenderte de los sethrak, inicia la armonización.', 'Estoy lista para defenderte de los sethrak, inicia la armonización.', 28153),
(149735, 'esMX', '¿Estás $Ulisto:lista;? Debemos apresurarnos, las fuerzas de Korthek tratarán de impedir que obtenga el poder de este pináculo. Deberás cubrirme mientras lanzo mi hechizo.', '', 28153),
(149730, 'esMX', '¿De dónde salieron todos estos fuegos fatuos?', '', 28153),
(149729, 'esMX', '¡Auch! ¡Estos malditos fuegos fatuos sí que lastiman!', '', 28153),
(149726, 'esMX', 'Han eliminado una gran amenaza contra Boralus, héroes, pero apostaría mi peso en grog a que la ciudad aún no está fuera de peligro.', '', 28153),
(149725, 'esMX', 'Sin ese cobarde traidor y sus capitanes, este ejército de piratas no será más que una bola de inútiles con barba y aliento a pescado.', '', 28153),
(149724, 'esMX', 'Harlan debería haber sabido que su traición terminaría así.', '', 28153),
(149723, 'esMX', 'Pero eso a ti no te preocupa, ¿verdad?', '', 28153),
(149722, 'esMX', 'Por supuesto, a excepción de su temible guardia de asesinos y degolladores maliciosos.', '', 28153),
(149720, 'esMX', 'Me dirigiré al pináculo. Te veré allí. Sin duda, las fuerzas de Korthek intentarán impedir que robe su poder.', '', 28153),
(149719, 'esMX', 'Bella doncella, ¿qué es lo que te aflige? ¡Maximillian de Villanorte ha venido a socorrerte!', '', 28153),
(149717, 'esMX', '', 'No habríamos encontrado a Rakera sin tu ayuda, pequeña.', 28153),
(149716, 'esMX', 'Creo haber oído a una doncella en peligro. ¡Acompáñame, $gescudero:escudera;!', '', 28153),
(149715, 'esMX', 'Verás, $gescudero:escudera;, lo único que logré con mis intentos de vencer a ese ettin fue atascar mis lanzas en su cuerpo. Así que, tu primera tarea...', '', 28153),
(149714, 'esMX', '', 'Somos camaradas, ¿verdad?', 28153),
(149713, 'esMX', '', 'Las ruinas están de camino a Zem\'lan. ¡Con gusto puedo llevarte! Dolly y Dot son buena compañía, pero siempre es bueno tener amigos para conversar.', 28153),
(149712, 'esMX', 'Esa burbuja... ¡Ah! ¿No puedes nadar en agua salada? Eso sí que es extraño...', '', 28153),
(149711, 'esMX', '¡¡¡NOOOOOO!!! ¡¡¡¡IMPOSIBLE!!!!', '', 28153),
(149710, 'esMX', 'Un momento... ¿Qué hacen aquí los vulperas?', '', 28153),
(149709, 'esMX', 'Está abandonado desde hace años, pero será ideal para lanzar nuestro...', '', 28153),
(149708, 'esMX', 'Mi sagrario personal estaba oculto en las colinas. Un santuario pequeño en honor a Sethraliss donde podía meditar.', '', 28153),
(149707, 'esMX', 'En aquellos tiempos, Korthek y yo liderábamos a nuestro pueblo en el culto a Sethraliss.', '', 28153),
(149706, 'esMX', '¡El sueño ahogado me consume!', '¡El sueño ahogado me consume!', 28153),
(149705, 'esMX', 'También viví aquí, hace mucho tiempo. Antes de que Korthek nos traicionara por su locura y su ansia de poder.', '', 28153),
(149704, 'esMX', 'Es un nido cruel hecho de piedras y rocas, plagado de los sethrak que han renegado de nuestra loa.', '', 28153),
(149703, 'esMX', 'Bebo del Vacío infinito.', 'Bebo del Vacío infinito.', 28153),
(149702, 'esMX', 'Ya no soy ciego.', 'Ya no soy ciega.', 28153),
(149701, 'esMX', 'Nos dirigimos al corazón del imperio de los infieles, $p.', '', 28153),
(149700, 'esMX', 'El círculo... ¡Veo el círculo!', 'El círculo... ¡Veo el círculo!', 28153),
(149699, 'esMX', '¡Las sombras retorcidas vienen por mí!', 'Oh... ¡Las sombras retorcidas vienen por mí!', 28153),
(149698, 'esMX', '¡Escucho la voz! ¡Las mil verdades!', 'Ah... ¡Escucho la voz! ¡Las mil verdades!', 28153),
(149697, 'esMX', 'Viviré eternamente en el abismo.', 'Viviré eternamente en el abismo.', 28153),
(149696, 'esMX', '¡Al fin! El camino hacia Harlan Sweete está liberado y nada se interpondrá en nuestro camino.', '', 28153),
(149695, 'esMX', '¡Mi alma por el ancestro!', '¡Mi alma por el ancestro!', 28153),
(149694, 'esMX', '', 'Defenderemos a tu pueblo como a los nuestro\'.', 28153),
(149693, 'esMX', '¿Qué dices si aprovechamos tus habilidades de combate?', '', 28153),
(149692, 'esMX', 'Ese percebe maldito ha bloqueado el acceso a la isla hasta que terminen las celebraciones en el foso de pelea.', '', 28153),
(149691, 'esMX', '¡No llevo floreh\' de paz en mi solapa, escoria de la Alianza!', '¡No llevo floreh\' de paz en mi solapa, escoria de la Alianza!', 28153),
(149690, 'esMX', '¡No sé nada sobre un Tranvía Subterráneo!', '¡No sé nada sobre un Tranvía Subterráneo!', 28153),
(149689, 'esMX', 'Ahora solo falta hacerle sentir el filo del acero a la garganta de Harlan. Pero no será sencillo.', '', 28153),
(149688, 'esMX', '¡Los lechúcico\' no vuelan! ¡Vete!', '¡Los lechúcico\' no vuelan! ¡Vete!', 28153),
(149687, 'esMX', '¡No soy un eh\'pía!', '¡No soy un eh\'pía!', 28153),
(149686, 'esMX', '\"¿Que los múrloc qué?\" ¡Tú no está\' bien de la cabeza!', '\"¿Que los múrloc qué?\" ¡Tú no está\' bien de la cabeza!', 28153),
(149685, 'esMX', '\"¿Una botella de sudor de trol?\" ¡No vendemo\' eso aquí!', '\"¿Una botella de sudor de trol?\" ¡No vendemo\' eso aquí!', 28153),
(149684, 'esMX', 'Sí, claro que los árbole\' son bonitos y el fuego e\' malo. ¿A qué quieres llegar?', 'Sí, claro que los árbole\' son bonitos y el fuego e\' malo. ¿A qué quieres llegar?', 28153),
(149683, 'esMX', '¡Zandalar por siempre!', '¡Zandalar por siempre!', 28153),
(149682, 'esMX', '', 'Hay algo extraño en eh\'te templo. Necesitamos encontrar una forma de entrar.', 28153),
(149681, 'esMX', 'Si no fueras adalid, serías $Uun:una, excelente pirata.', '', 28153),
(149680, 'esMX', 'Duermo... solo para despertar...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'esMX', 'Eh... genial, Maximillian. Bueno, me retiro.', 'Eh... genial, Maximillian. Bueno, me retiro.', 28153),
(149678, 'esMX', 'La sombra infinita... me abraza...', '', 28153),
(149677, 'esMX', 'Tu esperanza... se desvanece...', '', 28153),
(149676, 'esMX', 'Eh... ¿qué?', 'Eh... ¿qué?', 28153),
(149675, 'esMX', 'La semilla... echa raíces...', '', 28153),
(149674, 'esMX', 'Soy solo uno... de muchos...', '', 28153),
(149673, 'esMX', 'El ciclo... continúa...', '', 28153),
(149672, 'esMX', 'Incluso la muerte... puede... morir...', '', 28153),
(149671, 'esMX', 'Al final... sabrás la verdad...', '', 28153),
(149670, 'esMX', '¿Ya te enteraste? ¡La Puerta de Daelin ha caído!', '¿Ya te enteraste? ¡La Puerta de Daelin ha caído!', 28153),
(149669, 'esMX', '¿Qué piensas de todo esto?', '¿Qué piensas de todo esto?', 28153),
(149668, 'esMX', 'Las corrientes te arrastrarán al abismo.', '', 28153),
(149667, 'esMX', 'Pues, me hace pensar en volver a mis viejos hábito\'.', '', 28153),
(149666, 'esMX', 'A los Camorristas dientenegro les encanta pelear. Si logras partirles la mandíbula, el capitán Raúl sin duda te invitará a la reunión.', '', 28153),
(149665, 'esMX', '¿Qué son esos chillido\' que salen de tu boca?', '', 28153),
(149664, 'esMX', '¡Ni siquiera los peces beben tanto como las ratas de sentina! Si puedes seguirles el ritmo a estos animales, la capitana Eudora no podrá resistirse a invitarte a la reunión.', '', 28153),
(149663, 'esMX', '¿Qué sabes sobre el ataque?', '¿Qué sabes sobre el ataque?', 28153),
(149662, 'esMX', 'Nadie podrá decir que no lo di todo por esta guerra. Aquí tienes mi informe.', 'Nadie podrá decir que no lo di todo por esta guerra. Aquí tienes mi informe.', 28153),
(149661, 'esMX', '', 'Muy bien. Dolly y Dot son mis amigas. ¡Llevan mi carreta por todas las dunas!', 28153),
(149660, 'esMX', 'No lo sé... Todo empeora día a día. Quizás sea hora de que Katherine dé un paso al costado.', 'No lo sé... Todo empeora día a día. Quizás sea hora de que Katherine dé un paso al costado.', 28153),
(149659, 'esMX', 'No le fallaré a la Alianza. Aunque tenga que dormir en el lodo tres días seguidos. Aquí tienes mi informe.', 'No le fallaré a la Alianza. Aunque tenga que dormir en el lodo tres días seguidos. Aquí tienes mi informe.', 28153),
(149658, 'esMX', '', 'A Dot y a Dolly les gusta que les cante. Las calma.', 28153),
(149657, 'esMX', '¿Puedes creer que algunos piensan que los trols y los elfos de la noche están relacionados? Ha sido una experiencia espantosa. Este es mi informe.', '¿Puedes creer que algunos piensan que los trols y los elfos de la noche están relacionados? Ha sido una experiencia espantosa. Este es mi informe.', 28153),
(149656, 'esMX', 'Conseguir una invitación te facilitará las cosas. O simplemente puedes entrar corriendo e intentar matar a los más temibles capitanes piratas de una vez. Tú eliges, colega.', '', 28153),
(149655, 'esMX', '', 'Dolly y Dot son mis amigas. ¡Llevan mi carreta por todas las dunas! Sus dientes son pequeños y les gusta comer…', 28153),
(149654, 'esMX', 'Dije que haría lo que sea para vengar a Teldrassil. Y según parece, fingir ser un trol es parte de las posibilidades. Este es mi informe.', 'Dije que haría lo que sea para vengar a Teldrassil. Y según parece, fingir ser un trol es parte de las posibilidades. Este es mi informe.', 28153),
(149653, 'esMX', 'Sé por una fuente confiable que habrá una reunión de capitanes. Si logramos entrar, ¡podrás cortar todas las cabezas de esta hidra de una vez!', '', 28153),
(149652, 'esMX', '¿Dónde está mi pterrordáctilo?', '¿Dónde está mi pterrordáctilo?', 28153),
(149651, 'esMX', '¿Qué le sucede a mi cría?', '¿Qué le sucede a mi cría?', 28153),
(149650, 'esMX', '\"Es solo un pequeño viaje a la jungla\", dijeron. \"Será fácil\", dijeron. En fin. Este es mi informe.', '\"Es solo un pequeño viaje a la jungla\", dijeron. \"Será agradable\", dijeron. En fin. Este es mi informe.', 28153),
(149649, 'esMX', '¡¿Por qué hace tanto ruido?!', '¡¿Por qué hace tanto ruido?!', 28153),
(149648, 'esMX', 'Salvajes. Completa y absolutamente salvajes. Ten, este es mi informe.', 'Salvajes. Completa y absolutamente salvajes. Ten, este es mi informe.', 28153),
(149647, 'esMX', 'No me preguntes dónde tuve que dormir anoche. Aquí tienes tu informe.', 'No me preguntes dónde tuve que dormir anoche. Aquí tienes tu informe.', 28153),
(149646, 'esMX', 'Gracias.', 'Gracias.', 28153),
(149645, 'esMX', 'Yo me encargo de organizar el plan, los detalles te los dejo a ti.', '', 28153),
(149644, 'esMX', 'Entonces, le daremos a Harlan su merecido.', '', 28153),
(149643, 'esMX', 'Ahógate en la sangre de lo infinito.', '', 28153),
(149642, 'esMX', 'Este es el plan. Expulsa a los surcamar, purga a las ratas de sentina, destroza a los dientenegro y desbarata a los mareaférrea.', '', 28153),
(149641, 'esMX', 'Si lo logra, controlará una flota que será una amenaza contra toda la región.', '', 28153),
(149640, 'esMX', 'Creo haber oído un chillido, pero no puedo dejar los nido\' solos para ir a ver.$b$bSerá mejor que te apresure\' o no tendrás ningún pterrordáctilo para cuidar. No todo\' llegan a la adultez.', '', 28153),
(149639, 'esMX', 'Harlan Sweete usa a los mareaférrea para convocar al resto de las tripulaciones pirata bajo su estandarte.', '', 28153),
(149638, 'esMX', 'Ah, se escapó. Quizás estaba aburrido.$b$bSerá mejor que vayas a buh\'carlo antes de que se lah\'time. Aún no puede defenderse por sí solo.', '', 28153),
(149637, 'esMX', 'Parece un poco deprimido, ¿verdad?$b$bSeguro extraña a su madre. Eh, que sería\' tú, ¿no?', '', 28153),
(149636, 'esMX', 'Tu alma solo conocerá el ansia.', '', 28153),
(149635, 'esMX', 'Las estrellas temen nuestra ascensión.', '', 28153),
(149634, 'esMX', 'Ese sonido que hace es una clara señal de que tiene hambre.$b$bSerá mejor que lo alimentes ante\' de que te coma un dedo.$b$bSi no tienes comida, puede\' conseguir un poco en el Redil de Bestias de Guerra.', '', 28153),
(149633, 'esMX', 'Conoce el abrazo de la nada misma.', '', 28153),
(149632, 'esMX', 'Duerme por siempre en Ny\'alotha.', '', 28153),
(149631, 'esMX', 'La Luz muere en las profundidades insondables.', '', 28153),
(149630, 'esMX', 'Yo soy el Guardaalas Goja. Pa\'ku es mi loa. Sirvo a la señora del viento cuidando a sus pequeño\'.$b$bElla me dijo que necesitabas un poco de ayuda.$b$b<El Guardaalas Goja se ríe.>$b$b¿Qué necesitas?', '', 28153),
(149629, 'esMX', 'Observa la sombra de tu muerte.', '', 28153),
(149628, 'esMX', 'Oí que fueron piratas. ¿Puedes creerlo? ¡Infames y pulgosos PIRATAS! ¿Acaso los Valiente pueden seguir protegiéndonos?', 'Oí que fueron piratas. ¿Puedes creerlo? ¡Infames y pulgosos PIRATAS! ¿Acaso los Valiente pueden seguir protegiéndonos?', 28153),
(149627, 'esMX', '¡Ah! ¡Mi fiel $Gescudero:escudera;! Siempre a mi lado cuando lo necesito.\n\nHe venido a Kul Tiras con la esperanza de ayudar a los ciudadanos en peligro. Ahora mi tarea es salvar a los pobres pescadores de esta aldea pintoresca de los ettins que han decidido aterrorizarlos.\n\nSu pellejo es extraordinariamente grueso.', '', 28153),
(149626, 'esMX', 'Sí, tú y todos los demás. Mantengan la fila y no causen alboroto. La gente ya está bastante nerviosa.', 'Sí, tú y todos los demás. Mantengan la fila y no causen alboroto. La gente ya está bastante nerviosa.', 28153),
(149625, 'esMX', 'Necesito hablar con Katherine Valiente de inmediato.', 'Necesito hablar con Katherine Valiente de inmediato.', 28153),
(149624, 'esMX', 'Lady almirante Valiente se está preparando para hablar en público. Mantén la calma.', 'Lady almirante Valiente se está preparando para hablar en público. Mantén la calma.', 28153),
(149623, 'esMX', 'Nuestra lady almirante está en peligro. ¡Vamos!', 'Nuestra lady almirante está en peligro. ¡Vamos!', 28153),
(149622, 'esMX', 'Mantén la calma. Todo está bajo control.', 'Mantén la calma. Todo está bajo control.', 28153),
(149621, 'esMX', 'A Nedly Sornas no le gusta que se aprovechen de él. ¡Nadie encontrará ese tesoro antes que yo!', '', 28153),
(149620, 'esMX', 'No me atraparás distraído.\n\nSi tratas de engañarme, te venderé a los Partidarios.', '', 28153),
(149619, 'esMX', 'La corrupción de esta mareasangre es reciente. Debería poder purificarla.', '', 28153),
(149618, 'esMX', '¡Ah! Es más volátil de lo que pensaba.', '', 28153),
(149617, 'esMX', '¡Saludos, $gviajero:viajera;!\n\n¿Has venido tras la huella de mis historias heroicas con la esperanza de convertirte en $Gel escudero:la escudera; de Maximillian de Villanorte?\n\nPues es tu día de suerte. Necesito a alguien que me asista mientras enfrento enemigos peligrosos.', '', 28153),
(149616, 'esMX', '', 'La encontraré o moriré en el intento.', 28153),
(149615, 'esMX', '', 'El puerto de Zem\'lan está hacia el sur. Hace años que los barcos no entran en su astillero, pero es la mejor posibilidad de conseguir lo que Kiro y Nisha necesitan para atacar a los sethrak.', 28153),
(149614, 'esMX', '', 'Tú vigila a tu amiga. Yo vigilaré el camino.', 28153),
(149613, 'esMX', '', 'Esto es posterior a la batalla, pero... Tul no aparece muerto. Herido, lastimado, ¡pero con vida!', 28153),
(149612, 'esMX', '', 'Según los relatos sobre este suceso, Lord Arom mató a Gorak Tul y su ejército se desintegró tiempo después. Pero aquí se ve que todos sus ensamblajes se resquebrajan cuando lo apuñalan y le quitan todo su poder. Había una conexión.', 28153),
(149611, 'esMX', '', 'Ese es Lord Arom Tarjasenda en su rol de coronel, al frente del último ataque. Y ese de ahí... ese es Gorak Tul, Tarjasenda lo está apuñalando.', 28153),
(149610, 'esMX', '', 'Esto no es drust. Es un grabado kultirano sobre un monolito drust.', 28153),
(149609, 'esMX', '', 'Interesante. No había notado que los ensamblajes aparecen después, solo por su desesperación de ganar.', 28153),
(149608, 'esMX', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz', '', 28153),
(149607, 'esMX', 'Fhssh zzof og far\'al awtgsshu', '', 28153),
(149606, 'esMX', '', '¡Muy bien! Le has dado un poco de respiro al linaje de Krag\'wa. Gracia\', $Uhéroe:heroína;.', 28153),
(149605, 'esMX', 'Kua\'fon chilla de alegría y devora la comida que le ofrecen.', '', 28153),
(149604, 'esMX', 'Kua\'fon huele la comida antes de devorarla con entusiasmo.', '', 28153),
(149603, 'esMX', 'Kua\'fon atrapa la comida en el aire.', '', 28153),
(149602, 'esMX', 'Kua\'fon se abalanza sobre la comida que le ofrecen y la traga de un bocado.', '', 28153),
(149601, 'esMX', '', 'Una vez más, lo\' trols de sangre salen a cazar al linaje de Krag\'wa. El corazón del señor de las rana\' arde con furia. ¡Ayúdalo en su búh\'queda de venganza!', 28153),
(149600, 'esMX', '¡Por Canto Tormenta!', '¡Por Canto Tormenta!', 28153),
(149599, 'esMX', 'El valle es nuestro, ¡rata de sentina!', 'El valle es nuestro, ¡rata de sentina!', 28153),
(149598, 'esMX', '¡Kul Tiras se hundiría sin nosotros!', '¡Kul Tiras se hundiría sin nosotros!', 28153),
(149597, 'esMX', '¡Nuestra flota te aplastará!', '¡Nuestra flota te aplastará!', 28153),
(149596, 'esMX', '¡Todos los que se nos opongan morirán!', '¡Todos los que se nos opongan morirán!', 28153),
(149595, 'esMX', '¡Somos incansables como el mar!', '¡Somos incansables como el mar!', 28153),
(149594, 'esMX', '¡Cómo te atreves a desafiar a Canto Tormenta!', '¡Cómo te atreves a desafiar a Canto Tormenta!', 28153),
(149593, 'esMX', '¡Kul Tiras le pertenece al mar!', '¡Kul Tiras le pertenece al mar!', 28153),
(149592, 'esMX', 'Mi vida... por el mar....', 'Mi vida... por el mar....', 28153),
(149591, 'esMX', 'Maresabios... protéjanme...', 'Maresabios... protéjanme...', 28153),
(149590, 'esMX', 'Solo... cumplía órdenes...', 'Solo... cumplía órdenes...', 28153),
(149589, 'esMX', 'Ya... hemos ganado...', 'Ya... hemos ganado...', 28153),
(149588, 'esMX', 'Mi muerte... no cambia nada...', 'Mi muerte... no cambia nada...', 28153),
(149587, 'esMX', 'Jamás... descansaremos...', 'Jamás... descansaremos...', 28153),
(149586, 'esMX', 'Tengo agua salada... en las venas...', 'Tengo agua salada... en las venas...', 28153),
(149585, 'esMX', 'Vi la verdad... en el fondo del mar.', 'Vi la verdad... en el fondo del mar.', 28153),
(149584, 'esMX', 'No sabes qué humillante es esto. Aquí tienes tu informe.', 'No tienes idea de lo humillante que es esto. Aquí tienes tu informe.', 28153),
(149583, 'esMX', '', 'Tontos... Al menos ya sabemos lo peligrosos que pueden ser los fuegos fatuos.', 28153),
(149582, 'esMX', '', '¡No tendrás a dónde correr la próxima vez que nos veamos, Malfurion!', 28153),
(149581, 'esMX', '¡Hasta aquí has llegado, Reina alma en pena!', '', 28153),
(149580, 'esMX', '<Kua\'fon descansa con la cabeza entre las alas y emite suaves gemidos.>', '', 28153),
(149579, 'esMX', '', '¡Hora de apuñalar!', 28153),
(149577, 'esMX', 'Dales su merecido, $p.', '', 28153),
(149575, 'esMX', '', '¿Qué esperabas? Acaba de eclosionar. Debe alimentarse. Ve y pide un poco de carne en el redil.', 28153),
(149574, 'esMX', '¡Tú invocaste el trueno!', '', 28153),
(149573, 'esMX', '', 'La oigo muy bien. La cría tiene buenos pulmones.\n\n¿Por qué esa cara de temor?', 28153),
(149571, 'esMX', '<Te mira inexpresivamente.>', '<Te mira inexpresivamente.>', 28153),
(149570, 'esMX', 'No diré nada.', 'No diré nada.', 28153),
(149569, 'esMX', '¿Tienes una moneda de oro para caridad?', '¿Tienes una moneda de oro para caridad?', 28153),
(149568, 'esMX', 'Eres $Uun:una; trol muy $Upintoreh\'co:pintoreh\'ca;.', 'Eres $Uun:una; trol muy $Upintoreh\'co:pintoreh\'ca;.', 28153),
(149567, 'esMX', '... ¿Qué?', '... ¿Qué?', 28153),
(149566, 'esMX', 'Me eh\'tás tapando la vista.', 'Me eh\'tás tapando la vista.', 28153),
(149565, 'esMX', '<Eructa.>', '<Eructa.>', 28153),
(149564, 'esMX', '<Pronuncia la frase codificada>.', '<Pronuncia la frase codificada>.', 28153),
(149563, 'esMX', '¿Qué quieres?', '¿Qué quieres?', 28153),
(149562, 'esMX', 'La sopa de tortuga no se compara con la sopa de $r.\n\nConsigue carne de gusano fangoso y deja a las tortuguitas en paz.\n\n¡Vuelve a visitarme algún día y podemos explorar otras opciones de sopa!', '', 28153),
(149561, 'esMX', '¿Sopa de tortuga?', '¿Sopa de tortuga?', 28153),
(149560, 'esMX', '¡POR SETHRALISS!', '', 28153),
(149559, 'esMX', 'Los infieles están bloqueando el camino que lleva al emperador Korthek. ¡Debemos destruir esa barrera!', '', 28153),
(149558, 'esMX', '¡Atención! Margie está buscando ayuda para el Taller... me dijo algo sobre unas piezas para un... bueno, algo. En fin, no me especializo en estas cosas.', '', 28153),
(149557, 'esMX', 'Excelente. Esta información será vital para nuestro esfuerzo de guerra. Y no, no sé quién inventó la frase secreta esta vez.', '', 28153),
(149556, 'esMX', 'Nuestros espías se han infiltrado en la capital zandalari, pero necesitamos que recuperes sus informes. Habla con los vagantes. Nuestro espía responderá a la frase secreta.', '', 28153),
(149555, 'esMX', 'Hay, eh, algunos ogros cerca de nuestra base y no lucen muy alegres. Damas y caballeros, ¡desenfunden sus armas!', '', 28153),
(149554, 'esMX', 'Aquí solo encontrarán a Akunda. En esta sala solo pueden entrar lo\' que comparten su nombre.', '', 28153),
(149553, 'esMX', '¿Buscan redención? Akunda recibe a todos con beneplácito.', '', 28153),
(149552, 'esMX', '', 'Estamo\' buscando a una exiliada llamada Rakera. Creemos que puede eh\'tar en este templo.', 28153),
(149551, 'esMX', '', 'Iré primero por si hay oro.', 28153),
(149550, 'esMX', '', 'Llegamos a este lugar en son de paz, pero los drust optaron por la guerra de inmediato. Solo unos pocos toleraron a sus nuevos vecinos.', 28153),
(149549, 'esMX', '', 'Espera, aquí se muestra uno de los primeros asentamientos kultiranos. Uno de los asentamientos perdidos.', 28153),
(149548, 'esMX', 'Hablaré con Maokka.', 'Hablaré con Maokka.', 28153),
(149547, 'esMX', 'Bien, ya estamos todos.', '', 28153),
(149545, 'esMX', 'Eh, colega.', '', 28153),
(149544, 'esMX', '', 'Nos volveremos a ver, $uamigo:amiga;.', 28153),
(149543, 'esMX', '', 'Este mundo no puede soportar la destrucción que acarreará Mythrax.', 28153),
(149542, 'esMX', '¡Déjalo, Taelia!', '', 28153),
(149541, 'esMX', '', '¡Sam, no!', 28153),
(149540, 'esMX', '¡Por Addington! ¡Por el Valle Canto Tormenta!', '', 28153),
(149539, 'esMX', 'Esos bastardos pagarán por lo que han hecho.', '', 28153),
(149538, 'esMX', '', 'Jakra\'zet merecía su suerte.', 28153),
(149537, 'esMX', 'Estamos a su lado. ¡Por la Estela de la Tormenta!', '', 28153),
(149535, 'esMX', '', 'Me tomé la libertad de reunir un equipo para ti. Tráiganme mi premio.', 28153),
(149533, 'esMX', 'Más que han abandonado mi orden. Bien, quizás aún haya esperanza.', '', 28153),
(149532, 'esMX', 'Si están entre nosotros, la flota corre grave peligro.', '', 28153),
(149531, 'esMX', 'La mayoría creía que eran solo leyendas. Historias para advertir de los peligros de hurgar demasiado en nuestra magia.', '', 28153),
(149530, 'esMX', 'Esas... cosas... son k\'thir. Provienen de los rincones más oscuros bajo las mareas.', '', 28153),
(149529, 'esMX', '', '', 28153),
(149528, 'esMX', '¿Qué quieres de mí, Jefa de Guerra?', '¿Qué quieres de mí, Jefa de Guerra?', 28153),
(149527, 'esMX', '', '¡Baine, expúlsalos de aquí!', 28153),
(149526, 'esMX', '', 'Usa el designador remoto para que Madrug-A se desplace. ¡Envíalo a explorar los movimientos en la tierra y extraerá gusanos!', 28153),
(149525, 'esMX', 'Tratamos de protegernos de ellos, resistirlos, pero me temo que hemos fallado.', '', 28153),
(149523, 'esMX', 'Con el tiempo, los susurros... cambiaron. A veces eran exigentes, hasta violentos.', '', 28153),
(149522, 'esMX', 'Mi orden ha escuchado al mar para guiar a nuestros barcos y a nuestro pueblo por mucho tiempo. Susurros suaves, casi imperceptibles.', '', 28153),
(149521, 'esMX', 'Hay un puente cerca desde donde puede verse el Santuario de la Tormenta. El augurio viene de allí.', '', 28153),
(149520, 'esMX', 'Será un placer de\'truirte.', '', 28153),
(149519, 'esMX', '', 'Ten cuidado con esa cosa, a menos que vayas a pelear contra esos buenos para nada. En ese caso, ¡que arda!', 28153),
(149518, 'esMX', '$GTonto:Tonta;. Morirás.', '', 28153),
(149517, 'esMX', '¡Eh\'tos prisioneros les pertenecen a loh\' zandalari!', '', 28153),
(149516, 'esMX', '¡Ja, ja, ja!', '', 28153),
(149515, 'esMX', '¡Ahora morirás!', '', 28153),
(149514, 'esMX', 'Alianza patética.', '', 28153),
(149513, 'esMX', '¡Te aplah\'taré!', '', 28153),
(149512, 'esMX', '¿Quieres ir con el interrogador?', '', 28153),
(149511, 'esMX', '¡Carne freh\'ca!', '', 28153),
(149510, 'esMX', '¿Esa cosa... es segura? ¡Me arriesgaré!', '¿Esa cosa... es segura? ¡Me arriesgaré!', 28153),
(149509, 'esMX', '¡Sácame de aquí!', '¡Sácame de aquí!', 28153),
(149508, 'esMX', 'Madre de las mareas... ¿en qué nos hemos convertido?', '', 28153),
(149507, 'esMX', '¡Sabes llegar en el momento justo!', '¡Sabes llegar en el momento justo!', 28153),
(149506, 'esMX', '¿Eso es... una máquina topo?', '¿Eso es... una máquina topo?', 28153),
(149505, 'esMX', 'Me da miedo ir bajo tierra... ¡Pero estos trols son peores!', 'Me da miedo ir bajo tierra... ¡Pero estos trols son peores!', 28153),
(149504, 'esMX', '¡Gracias! ¡Gracias!', '¡Gracias! ¡Gracias!', 28153),
(149503, 'esMX', '¡Llegaste justo a tiempo!', '¡Llegaste justo a tiempo!', 28153),
(149502, 'esMX', '¡Pensé que iban a comerme!', '¡Pensé que iban a comerme!', 28153),
(149501, 'esMX', 'Comandante, la jefa de guerra pide que prepare su puesto de avanzada para la llegada de un ejército.', 'Comandante, la jefa de guerra pide que prepare su puesto de avanzada para la llegada de un ejército.', 28153),
(149500, 'esMX', 'Tenemos que hacer lugar para la llegada de la flota de la jefa de guerra. ¿Puedes despejar los muelles?', 'Tenemos que hacer lugar para la llegada de la flota de la jefa de guerra. ¿Puedes despejar los muelles?', 28153),
(149499, 'esMX', 'La jefa de guerra necesita raciones y albergue para un ejército que se acerca.', 'La jefa de guerra necesita raciones y albergue para un ejército que se acerca.', 28153),
(149498, 'esMX', '¿Doscientos soldados con la jefa de guerra, dices? Prepararé el puesto de avanzada para su llegada.', '', 28153),
(149497, 'esMX', 'Lo que sea por la jefa de guerra. Reuniré a los guardias para despejar los muelles de inmediato. Lok\'tar, $Uamigo:amiga;.', '', 28153),
(149496, 'esMX', '', '¿La jefa de guerra necesita albergue y comida para su ejército? Nuestras reservas deberían alcanzar, la temporada pasada tuvimos una primavera muy generosa y un invierno bastante templado.', 28153),
(149495, 'esMX', 'Está matando a sus propias tropas...', '', 28153),
(149494, 'esMX', 'Déjame ayudar. Sé lo que lo aqueja.', '', 28153),
(149493, 'esMX', 'Envíame de regreso a Ventormenta. (Volver a/Restablecer gesta)', 'Envíame de regreso a Ventormenta. (Volver a/Restablecer gesta)', 28153),
(149492, 'esMX', 'Envíame a Zuldazar. (Omitir gesta introductoria.)', 'Envíame a Zuldazar. (Omitir gesta introductoria.)', 28153),
(149491, 'esMX', '', 'Son demasiadas las naves de nuestra flota que fueron destruidas por la Legión o por la Alianza. Nuestros maestros de embarcadero han trabajado toda la noche, pero necesitamos más.', 28153),
(149490, 'esMX', 'Alto.', '', 28153),
(149489, 'esMX', 'Hablo... por G\'huun. Él... guiará. Tú... servirás... o morirás.', '', 28153),
(149488, 'esMX', 'Ven.', '', 28153),
(149487, 'esMX', 'El cadáver de este loa... me alimenta. Alimenta... a G\'huun.', '', 28153),
(149486, 'esMX', 'Tú... tratarás... de detener a G\'huun. Pero... fallarás... y sufrirás.', '', 28153),
(149485, 'esMX', 'Sí... lucha... resiste... G\'huun tiene sed... por tu... sufrimiento.', '', 28153),
(149484, 'esMX', 'Tus esfuerzos... son en vano. Soy... intocable.', '', 28153),
(149483, 'esMX', 'Tus esfuerzos... son inútiles... Soy... into... ¿Qué? No. ¡NO!', '', 28153),
(149482, 'esMX', 'Esto... no prueba... ¡NADA! Él... encontrará... otro conducto. Los sellos... se romperán... G\'huun... será... ¡libre!', '', 28153),
(149481, 'esMX', 'Espera... ¿Esto estaba en el sótano?', '', 28153),
(149480, 'esMX', '', 'Buena suerte.', 28153),
(149479, 'esMX', '', 'La patrulla acaba de pasar. Ahora podrás cruzar sin problemas.', 28153),
(149478, 'esMX', '', '', 28153),
(149477, 'esMX', '', 'Los infieles no sabrán qué fue lo que los golpeó.', 28153),
(149476, 'esMX', '', '', 28153),
(149475, 'esMX', 'El pequeño se aleja corriendo entre risas mientrah\' lo persigues.', 'La pequeña se aleja corriendo entre risas mientrah\' la persigues.', 28153),
(149474, 'esMX', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t¡%s apunta a |cFFFF0000$n|r con |cFFFF0000|Hspell:257617|h[Levantamiento]|h|r! ¡Dispérsense!', '', 28153),
(149473, 'esMX', 'Estaba pensando en eliminar a los pterrordáctilo\' para poder usar ese punto de observación en la colina, pero nos matarán uno a uno muy fácilmente.', 'Estaba pensando en eliminar a los pterrordáctilo\' para poder usar ese punto de observación en la colina, pero nos matarán uno a uno muy fácilmente.', 28153),
(149472, 'esMX', 'No hay problema, señora.', '', 28153),
(149471, 'esMX', '', 'No me gustan los discursos, así que seré breve. Gracias. Siempre tendrás aliados en el Valle Canto Tormenta.', 28153),
(149470, 'esMX', '', 'Sin ofender, Calvin.', 28153),
(149469, 'esMX', '', 'Echaste a los jabaespines del pueblo y de las granjas, y los hiciste volver al horado mismo. Rescataste a los ciudadanos y a los granjeros... Has hecho más por nosotros que la milicia, que jamás pudo ni quiso hacer demasiado.', 28153),
(149468, 'esMX', '', 'Puedes dejar de lado las demostraciones de afecto, $Gamigo:amiga;. Nunca me gustaron demasiado.', 28153),
(149466, 'esMX', 'Los zandalari transportan a los prisioneros de guerra en barco. ¡Tenemos que detenerlos! Usa la máquina topo de los Hierro Negro para rescatarlos del interrogatorio y de la muerte.', '', 28153),
(149465, 'esMX', '', 'Debemos llevarle esos planes de ataque a Kiro. No hay tiempo que perder. ¡Vamos!', 28153),
(149464, 'esMX', '', 'Tiene razón, Arom Tarjasenda se convirtió en Lord después de su victoria en este lugar.', 28153),
(149463, 'esMX', '', 'Bueno, si obedecemos órdenes, ninguno de estos monstruos llegará hasta Alto de Arom. Vamos a ayudar.', 28153),
(149462, 'esMX', '', 'Cree que somos parte de su milicia...', 28153),
(149461, 'esMX', '', 'El sacrificio de sangre debe parar. Al meno\' será un paso para detener a ese dios de la sangre.', 28153),
(149460, 'esMX', '', '¡Los rituales oh\'curos de Zul\'nazman han diseminado la corrupción y han traído a los espíritu\' del otro lado! ¡Purifica sus resto\' y haz que los demás deh\'cansen en paz!', 28153),
(149459, 'esMX', 'Dió\' de la... sangre... ¡Aargh!', 'Dió\' de la... sangre... ¡Aargh!', 28153),
(149458, 'esMX', 'Te veré en Atul\'Aman. ¡Los demás nos esperan allí!', '', 28153),
(149457, 'esMX', 'Nos está llamando...', 'Nos está llamando...', 28153),
(149456, 'esMX', 'Parece que algunos de nuestros jinetes del viento están en aprietos. ¡Busca sobrevivientes en el campo de batalla!', '', 28153),
(149455, 'esMX', '¡Déjame en paz!', '¡Déjame en paz!', 28153),
(149454, 'esMX', '¡No, no, no, no!', '¡No, no, no, no!', 28153),
(149453, 'esMX', '¡Sal de mi cabeza!', '¡Sal de mi cabeza!', 28153),
(149452, 'esMX', '¡Aagh!', '¡Aagh!', 28153),
(149451, 'esMX', '¡Bah\'ta!', '¡Bah\'ta!', 28153),
(149450, 'esMX', 'Ojalá los infieles se hubieran contentado con la paz. Como nosotros.\n\nPero su agresión constante al fin nos ha obligado a actuar.\n\nDerrocaremos al emperador Korthek... y nos quedaremos con cualquier objeto útil que encontremos en el camino.', '', 28153),
(149449, 'esMX', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t¡Quita rápidamente los Barriles de municiones del fuego para evitar que %s los haga explotar!', 28153),
(149448, 'esMX', '¡Soldados de vanguardia! ¡Prepárense para apoyar al coronel Tarjasenda!', '¡Soldados de vanguardia! ¡Prepárense para apoyar al coronel Arom!', 28153),
(149447, 'esMX', '¡Por Drustvar y Kul Tiras!', '¡Por Drustvar y Kul Tiras!', 28153),
(149446, 'esMX', '¡Se llevaron a nuestros hijos e hijas! ¡Haremos que paguen por eso!', '¡Se llevaron a nuestros hijos e hijas! ¡Haremos que paguen por eso!', 28153),
(149445, 'esMX', '¡Es hora de llenar de orgullo a sus ancestros!', '¡Es hora de llenar de orgullo a sus ancestros!', 28153),
(149444, 'esMX', '¡Los hemos repelido! ¡Adelante!', '¡Los hemos repelido! ¡Adelante!', 28153),
(149443, 'esMX', '¡Firmes!', '¡Firmes!', 28153),
(149442, 'esMX', '¡Repelimos al enemigo!\n\nNo se queden ahí parados, ¡a pelear!', '¡Repelimos al enemigo!\n\nNo se queden ahí parados, ¡a pelear!', 28153),
(149441, 'esMX', '¡La Nube agorera comienza a hervir al entrar en contacto con %s!', '¡La Nube agorera comienza a hervir al entrar en contacto con %s!', 28153),
(149440, 'esMX', 'Gracias...', 'Gracias...', 28153),
(149439, 'esMX', 'Por fin... puedo descansar...', 'Por fin... puedo descansar...', 28153),
(149438, 'esMX', 'Mi guardia ha terminado...', 'Mi guardia ha terminado...', 28153),
(149437, 'esMX', 'Vuelvo... a descansar...', 'Vuelvo... a descansar...', 28153),
(149436, 'esMX', 'He cumplido mi misión.', 'He cumplido mi misión.', 28153),
(149435, 'esMX', 'Conseguiré la carne.', 'Conseguiré la carne.', 28153),
(149434, 'esMX', 'La caja es mía, $r $gentrometido:entrometida;.\n\nNecesito gusanos fangosos para preparar mi sopa de gusano fangoso, ¡pero se esconden! Soy paciente, puedo esperar aquí unos días, quizás pueda encontrar más cajas...\n\nConsígueme carne de gusano fangoso y te la cambiaré por esta caja.', '¡No, la caja es mía!\n\nVine hasta aquí en busca de gusanos para hacer sopa. Algunos tortollanos dicen que con la carne de reptador se hace una sopa deliciosa, pero no estoy segura. La sopa de reptador no es motivo para hacerme amigo de $Gun extraño:una extraña;. \n\nPero la sopa de carne de gusano fangoso construye amistades de por vida, y los tortollanos vivimos mucho tiempo. \n\nSi encuentras un poco de carne de gusano fangoso, quizás te dé esta caja.', 28153),
(149433, 'esMX', '¿Esa caja?', '¿Esa caja?', 28153),
(149432, 'esMX', 'Estuve parado aquí un buen rato. Y luego encontré esta interesante caja en el lodo.', 'Estuve parado aquí un buen rato. Y luego encontré esta interesante caja en el lodo.', 28153),
(149431, 'esMX', 'Buen trabajo, colega. Eh\'taba... enloqueciendo. ¡Vagaba lento como una caravana tortollana!', 'Buen trabajo, colega. Eh\'taba... enloqueciendo. ¡Vagaba lento como una caravana tortollana!', 28153),
(149430, 'esMX', 'Te doy las gracia\', $Uforastero:forastera;.', 'Te doy las gracia\', $Uforastero:forastera;.', 28153),
(149429, 'esMX', 'Al fin se acabó. Gracias.', 'Al fin se acabó. Gracias.', 28153),
(149428, 'esMX', 'Puedo volver a descansar. Gracia\', $Uforastero:forastera;.', 'Puedo volver a descansar. Gracia\', $Uforastero:forastera;.', 28153),
(149427, 'esMX', 'Eh\'... el fin...', 'Eh\'... el fin...', 28153),
(149426, 'esMX', '¿Cuál es el plan?', '¿Cuál es el plan?', 28153),
(149425, 'esMX', '', 'Pensaba en descargas eléctricas... o fuego, ¡o tal vez solo lo volamos por los aires! \n\nPero es mala suerte matar a un tortollano, y si hay algo que no necesito es más mala suerte. \n\nAsí que, ¿por qué no piensas tú en una forma de encargarte de este tortollano?', 28153),
(149424, 'esMX', '', 'Tenemos problemas, $p. El tortollano encontró una caja, ¡y nosotros la queremos!', 28153),
(149423, 'esMX', '¡Maldito pantano! La humedad destruye todo.\n\nBueno, ¿qué necesitas? Terminemo\' con esto para que pueda volver a mis reparacione\'.', '¡Maldito pantano! La humedad destruye todo.\n\nBueno, ¿qué necesitas? Terminemo\' con esto para que pueda volver a mis reparacione\'.', 28153),
(149422, 'esMX', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'esMX', 'Hay que ser un tonto muy arrogante para creer que es una buena idea refugiar a los amani. Has hecho un excelente trabajo hoy, adalid.', '', 28153),
(149420, 'esMX', 'El único amani bueno es un amani muerto, pero los zandalari les dieron refugio en la ciudad. Derroten a sus discípulos, ¡por la Alianza!', '', 28153),
(149419, 'esMX', '¡La bestia ha muerto! ¡Aspafresno, aseguren los pisos superiores! Yo me encargaré de $Geste ladrón:esta ladrona;...', '¡La bestia ha muerto! ¡Aspafresno, aseguren los pisos superiores! Yo me encargaré de $Geste ladrón:esta ladrona;...', 28153),
(149418, 'esMX', '¡Mientras yo esté de pie, no dejaré que este bastión caiga!', '', 28153),
(149417, 'esMX', 'Eso debería ponerlos en su lugar.', '', 28153),
(149416, 'esMX', '<Mostrar la piedracanto a Kellam.>', '<Mostrar la piedracanto a Kellam.>', 28153),
(149415, 'esMX', 'A la tribu amani le convendría recordar que la Horda es fuerte en Zuldazar. ¿Por qué no les refrescas la memoria? Golpea el gong y derrota a sus discípulos.', '', 28153),
(149414, 'esMX', 'Me adelantaré y buscaré a los granjeros. ¡Hagas lo que hagas, no deben capturarte!', '', 28153),
(149413, 'esMX', '', '¡Taz\'dingo!', 28153),
(149411, 'esMX', 'Hay muchos tesoros en el fango. ¡Tú y Moxie van a encontrarlos $ujuntos:juntas;!', '', 28153),
(149410, 'esMX', '¡Auch! ¡No! Los crustájeos... no deben ser liberados...', '', 28153),
(149409, 'esMX', '¡A la batalla!', '¡A la batalla!', 28153),
(149408, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(149407, 'esMX', 'Luchamos juntos.', 'Luchamos juntos.', 28153),
(149406, 'esMX', 'Lucho a tu lado.', 'Lucho a tu lado.', 28153),
(149405, 'esMX', 'Estoy en deuda contigo, $n.', 'Estoy en deuda contigo, $n.', 28153),
(149404, 'esMX', 'El ritual aún no está completo. ¡Hay que someter a los crustájeos!', '', 28153),
(149403, 'esMX', '¡Sigan atacando! Yo puedo cuidarme solo.', '', 28153),
(149402, 'esMX', '', 'Mi fuerza... ¿Qué...? ¿Qué es eh\'to?', 28153),
(149401, 'esMX', '', 'Mi cuerpo... No puedo... ¡Arghh!', 28153),
(149400, 'esMX', 'De acuerdo.', 'De acuerdo.', 28153),
(149399, 'esMX', '', 'Los trabajadores dicen que oyen voces en el lodo. ¡Algunos hasta han enloquecido!\n\n¡No las escuches!', 28153),
(149398, 'esMX', '', 'Algunos kultiranos me vinculan con ciertos robos... de los que yo no sé nada, por supuesto.', 28153),
(149397, 'esMX', '', 'Navego hacia... aguas inexploradas...', 28153),
(149396, 'esMX', '', '¡Este actúa como si nunca hubiera visto a una gnoma!', 28153),
(149395, 'esMX', '', '¡Estoy cansada de esto!', 28153),
(149394, 'esMX', '', 'Proyectiles exterminadores... ¡FUEGO!', 28153),
(149393, 'esMX', '', '¡Traga plomo!', 28153),
(149392, 'esMX', '', '¡Te haré pedazos!', 28153),
(149391, 'esMX', '', '¡Despejen la cubierta!', 28153),
(149390, 'esMX', 'Lo\' zandalari... están llenos de promesa\' falsas.', 'Lo\' zandalari... están llenos de promesa\' falsas.', 28153),
(149389, 'esMX', 'Tendrá\' noticias de mi loa por esto...', 'Tendrá\' noticias de mi loa por esto...', 28153),
(149388, 'esMX', 'Ya no hay lugar seguro para nosotro\'.', 'Ya no hay lugar seguro para nosotro\'.', 28153),
(149387, 'esMX', 'En su propia ciudad... nos abandonan a la muerte.', 'En su propia ciudad... nos abandonan a la muerte.', 28153),
(149386, 'esMX', '¿Qué será de nosotro\' ahora?', '¿Qué será de nosotro\' ahora?', 28153),
(149385, 'esMX', 'El imperio... realmente ha caído.', 'El imperio... realmente ha caído.', 28153),
(149384, 'esMX', '¿Cómo pueden permitir que suceda... eh\'to?', '¿Cómo pueden permitir que suceda... eh\'to?', 28153),
(149383, 'esMX', 'Los zandalari... prometieron que estaríamo\' a salvo...', 'Los zandalari... prometieron que estaríamo\' a salvo...', 28153),
(149382, 'esMX', '¡Por fin! Alguien encontró mi ofrenda para Bwonsamdi. ¡Úsala bien!', '¡Por fin! Alguien encontró mi ofrenda para Bwonsamdi. ¡Úsala bien!', 28153),
(149381, 'esMX', '', '¡Tráiganme sus pulgares! Diviértanse con el resto.', 28153),
(149380, 'esMX', '', '¡Si mueres, me quedo con tu parte!', 28153),
(149379, 'esMX', '', 'Tu cabeza lucirá muy bien en mi colección.', 28153),
(149378, 'esMX', '', 'Tú y yo ya somos $ubuenos amigos:buenas amigas;. ¿Me prestas un poco de oro?', 28153),
(149377, 'esMX', '', 'He visto a alguien igual a ti en Tol Dagor.', 28153),
(149376, 'esMX', '¡Eh\'tás cometiendo un grave error!', '¡Eh\'tás cometiendo un grave error!', 28153),
(149375, 'esMX', '¡Ayuda! ¡Eh\'tán atacando la terraza!', '¡Ayuda! ¡Eh\'tán atacando la terraza!', 28153),
(149374, 'esMX', '¡A ello\'!', '¡A ello\'!', 28153),
(149373, 'esMX', '¡No tiene\' nada que hacer aquí, colega!', '¡No tiene\' nada que hacer aquí, colega!', 28153),
(149372, 'esMX', '¡Largo! ¡Zandalar les pertenece a los trols!', '¡Largo! ¡Zandalar les pertenece a los trols!', 28153),
(149371, 'esMX', 'Sabía que algo olía mal...', 'Sabía que algo olía mal...', 28153),
(149370, 'esMX', '¡Ayuda! ¡Me eh\'tán atacando!', '¡Ayuda! ¡Me eh\'tán atacando!', 28153),
(149369, 'esMX', '¡Escoria maldita!', '¡Escoria maldita!', 28153),
(149368, 'esMX', 'Coda conversa y mira hacia el barranco.', '', 28153),
(149367, 'esMX', '', 'Yo también estoy preocupada, Coda.', 28153),
(149366, 'esMX', 'Necesito viajar a la Estación Oriental.', 'Necesito viajar a la Estación Oriental.', 28153),
(149365, 'esMX', '', '¿A dónde vas?', 28153),
(149364, 'esMX', '', '¡Gracias! ¡Y por favor dale muchos abrazos a Poda!', 28153),
(149363, 'esMX', '', 'Todos los cañones... ¡FUEGO!', 28153),
(149362, 'esMX', 'Los astilleros serán su nuevo hogar.', '', 28153),
(149361, 'esMX', 'Todos ustedes prestarán servicio a Lord Canto Tormenta en los astilleros.', '', 28153),
(149360, 'esMX', 'Todos a los vagones.', '', 28153),
(149359, 'esMX', '¡Una vez más, los trols de sangre amenazan a mis criaturas!$B$BVen, $Gpequeño:pequeña;, ¡juntos les recordaremos lo que sucede cuando hacen enfadar a Krag\'wa!', '', 28153),
(149358, 'esMX', '', '¡La ciudad es nuestra, camaradas!', 28153),
(149357, 'esMX', '', '¡Tus entrañas decorarán mi mástil!', 28153),
(149356, 'esMX', '', '¡Una gota más de sangre en mi espada!', 28153),
(149355, 'esMX', '', 'Todos... ¡ATAQUEN!', 28153),
(149354, 'esMX', '', '¡Ni un sobreviviente!', 28153),
(149353, 'esMX', 'Su espera ya casi ha terminado.', '', 28153),
(149352, 'esMX', '¿Cuánto falta?', '¿Cuánto falta?', 28153),
(149351, 'esMX', 'Los Mareaférrea nos atacan todos los días, y hay un ejército de la Horda en camino. En poco tiempo todo el pueblo tendrá que huir de aquí.', '', 28153),
(149348, 'esMX', 'Completaré el ritual... ¡con tu sangre!', '', 28153),
(149347, 'esMX', 'De acuerdo.', 'De acuerdo.', 28153),
(149346, 'esMX', '¿Fracasado? No…', '', 28153),
(149345, 'esMX', 'Las riquezas de todo un reino están en el fondo de ese lago fangoso. ¡Un barco del tesoro de la Segunda Guerra!\n\n¡Todo el pueblo está trabajando para encontrar el tesoro primero! No hay tiempo que perder, ¡debemos apresurarnos!', '', 28153),
(149344, 'esMX', 'Lith qul\'shoth wshh... yzsh uovssh qvask.', '', 28153),
(149343, 'esMX', '', 'Es el fin, Jakra\'zet. ¡Tu plan ha fracasado!', 28153),
(149341, 'esMX', 'Aunque luches en la superficie, él te espera en las profundidades.', '', 28153),
(149340, 'esMX', '', '¡Juh\'to a tiempo para detenerte!', 28153),
(149339, 'esMX', 'Llegaste juh\'to a tiempo...', '', 28153),
(149338, 'esMX', '', '¡Sí! ¡Todos regresaron a su hogar!', 28153),
(149337, 'esMX', '¡El ritual de sangre eh\'tá casi completo!', '', 28153),
(149336, 'esMX', '', '¡Por favor, apresúrate y encuéntralos! Coda estará muy triste si pierde a su familia.', 28153),
(149335, 'esMX', '¿Tesoro?', '¿Tesoro?', 28153),
(149334, 'esMX', 'Los Mareaférrea están llevándose a todos como prisioneros. ¡Quieren impedir que encontremos el tesoro primero!', '', 28153),
(149333, 'esMX', '', '¡Vuelvan, pequeños! ¡Podemos ayudarlos!', 28153),
(149332, 'esMX', '', '¡Si entramos ahí, esos aguijones también nos alcanzarán!', 28153),
(149331, 'esMX', '', '¡No puedo verlos, Coda!', 28153),
(149330, 'esMX', 'Zaix lal sk\'woth\'gl Zaix lal uulwi', '', 28153),
(149329, 'esMX', 'Los Mareaférrea están capturando gente, ¡necesitamos tu ayuda!', '', 28153),
(149328, 'esMX', 'Son la redención. Son la verdad.', '', 28153),
(149327, 'esMX', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg', '', 28153),
(149326, 'esMX', 'Todos se ahogarán en el abismo de sombras.', '', 28153),
(149325, 'esMX', '', 'Si no explota, inténtalo de nuevo.', 28153),
(149323, 'esMX', 'No lo creo. Tengo órdenes de llevarla directamente ante la jefa de guerra.', '', 28153),
(149322, 'esMX', '', 'Eh\'te es mi barco, así que creo que deberás cambiar tus plane\'.', 28153),
(149321, 'esMX', 'Podemos hablar de eh\'to en el camino, su alteza.', '', 28153),
(149320, 'esMX', '', 'Vamos. Partiremo\' rumbo a Zuldazar.', 28153),
(149319, 'esMX', 'Creo que lo que quieres decir e\' \"gracias\".', '', 28153),
(149318, 'esMX', 'Parece que una maga con tus... talentos... sería muy útil en eh\'te momento, ¿no?', '', 28153),
(149317, 'esMX', '', 'No... No puede ser.', 28153),
(149315, 'esMX', 'Puedes enfrentarno\'... y tal vez ganes.', '', 28153),
(149314, 'esMX', 'Sé que ves las llama\' que devoran la ciudad.', '', 28153),
(149313, 'esMX', 'No seas tan impaciente.', '', 28153),
(149312, 'esMX', '', 'Entonces, morirán.', 28153),
(149311, 'esMX', 'Con todo respeto, tenemos que tomar un barco.', '', 28153),
(149310, 'esMX', '', 'Ríndanse y los devolveré a las mazmorras, que es el lugar al que pertenecen. Allí esperarán la sentencia del rey.', 28153),
(149309, 'esMX', 'Eh\'peren aquí.', '', 28153),
(149307, 'esMX', 'Ya pensé en eso. Miren.', '', 28153),
(149306, 'esMX', '¡No se queden mirando y atraviesen el hielo!', '', 28153),
(149305, 'esMX', 'No sé quién será ese Rezan, pero eh\'toy en deuda con él.', '', 28153),
(149303, 'esMX', '', '¡Mueran, escoria de la Horda!', 28153),
(149302, 'esMX', '', '¡Nos cerró el paso!', 28153),
(149300, 'esMX', '', 'Necesito veinte de esas ave\'.', 28153),
(149299, 'esMX', '¡Ajá! ¡Lasan, ah\'tuto alce del demonio!', '', 28153),
(149298, 'esMX', 'No... Pero creo saber por qué. Miren.', '', 28153),
(149297, 'esMX', 'Eh... Que los loa se apiaden de tus enemigo\', Zul.', '', 28153),
(149296, 'esMX', '', 'Han matado a muchos inocentes para llegar hasta aquí. Pero su estúpida fuga se acabó.', 28153),
(149295, 'esMX', '', '¿No nos persiguen?', 28153),
(149294, 'esMX', '¡Jajajajajaja!', '', 28153),
(149292, 'esMX', '', 'Sus fuerzas deben haber regresado de Lordaeron. ¿Cómo vamos a pasar?', 28153),
(149291, 'esMX', '¡En marcha!', '', 28153),
(149290, 'esMX', '', 'Mi loa nos eh\'cucha. Poderoso Rezan, ¡dame tu fuerza!', 28153),
(149289, 'esMX', '', '¡No lastimarán a ninguna otra alma en esta ciudad!', 28153),
(149288, 'esMX', '', '¡Ya es suficiente!', 28153),
(149287, 'esMX', 'Vayan con cuidado. Parece que la laureada diplomática de la Alianza no tomará prisioneros esta vez.', '', 28153),
(149286, 'esMX', '¡Oh, pffff! ¡Puaj!', '', 28153),
(149285, 'esMX', '', '¡Encontraste a mi mamá! ¡Muchas gracias por salvarla de esos monstruos horribles!', 28153),
(149284, 'esMX', '', 'Gracias por traerme mi juguete. Si ves a mi mamá, ¿podrías decirle que vuelva a casa?\n\nHace mucho que no la veo.', 28153),
(149283, 'esMX', 'Ahora. Destruye el último sello.', '', 28153),
(149282, 'esMX', '', 'Talanji, persigue a Zul junto con tu adalid. Yo reuniré las tropa\' que pueda para detener al Desenredador. Necesitaré un ejército para derribarlo.', 28153),
(149281, 'esMX', 'Mythrax está a sus órdenes. Debemos detener al sirviente del Imperio Negro.', '', 28153),
(149280, 'esMX', '', 'Adalid, los loa y yo contendremo\' a Mythrax todo lo que podamo\'. ¡Encuentra a mi padre y acaben con Zul!', 28153),
(149279, 'esMX', 'Ven, Mythrax. Ven, Revelador. Debemo\' romper el sello final.', '', 28153),
(149278, 'esMX', 'El camino está despejado, pequeños. Muévanse. Mythrax se acerca.', '', 28153),
(149277, 'esMX', '', 'Hermanos y hermanas de Zandalar, ¡recuperemo\' nuestra ciudad! ¡Adelante!', 28153),
(149276, 'esMX', '', 'Adalid, buh\'ca a todos los civile\' que queden en el Zócalo y envíalos aquí. Seguiremo\' como podamos.', 28153),
(149275, 'esMX', '', 'Pésimo. Estamos rodeado\'. Los loa hacen lo que pueden, pero necesitamo\' convocar a cualquier trol capaz de blandir una lanza.', 28153),
(149274, 'esMX', '', 'Tiempos oh\'curos requieren grandes acto\'. ¿Cuál es la situación?', 28153),
(149273, 'esMX', '', 'Talanji, veo que llegas a la batalla en un loa.', 28153),
(149272, 'esMX', '', 'Rakera ha asumido el control de nueh\'tras fuerzas, qué raro.', 28153),
(149271, 'esMX', '', '¡Formen fila\'! Arcos de guerra, prepárense.', 28153),
(149270, 'esMX', '', 'Eso no es muy... conveniente.', 28153),
(149269, 'esMX', '', '$UEste adalid:Esta adalid; dice que Mythrax el Revelador ha regresado.', 28153),
(149268, 'esMX', '', 'Algo impulsa a los sethrak a atacar. Se están diseminando como nunca antes.', 28153),
(149267, 'esMX', '', 'Cuidado, padre. Eh\'to ha sido planeado durante mucho tiempo por un enemigo que no comprendemo\'.', 28153),
(149266, 'esMX', 'Talanji, llévate $Ual:a la; adalid de la Horda y reúnan a nuestras fuerza\' ahí. Yo trabajaré con Krag\'wa para asegurar la Esquirla.', '', 28153),
(149265, 'esMX', '', '¡Rastakhan! Las víboras de Vol\'dun asedian tu frontera occidental. Haz algo.', 28153),
(149264, 'esMX', 'Están pasando demasiado\'. Vayan al puente de Dazar\'alor. Podemo\' crear un cuello de botella.', '', 28153),
(149263, 'esMX', 'Un regalo para el viejo Bwonsamdi.', '', 28153),
(149262, 'esMX', '¡Mueran, invasore\'!', '', 28153),
(149261, 'esMX', 'Son demasiado\'...', '', 28153),
(149260, 'esMX', 'La Puerta de Sangre ha caído. Rápido, debemos aplastar a todo\' los invasore\' que podamo\' antes de que lleguen a la ciudad.', '', 28153),
(149259, 'esMX', '', 'No puedes detener... la tormenta...', 28153),
(149258, 'esMX', '', '¡El imperio de los infieles es implacable!', 28153),
(149257, 'esMX', 'Saldré de aquí. ¡Ten cuidado!', '', 28153),
(149256, 'esMX', 'Muchas gracias... Creí que era mi fin.', '', 28153),
(149255, 'esMX', 'Con eso bastará. ¿Cómo se siente saquear una ciudad entera sin ayuda, $n?', '', 28153),
(149254, 'esMX', 'Corre...¡¡CORRE!!', '', 28153),
(149253, 'esMX', 'Es demasiado pronto. ¡Aún no se ha ahogado con la gloria del maestro!', '', 28153),
(149252, 'esMX', '¡No, no, no! ¡La ciudad es un griterío! Encontraré la forma de salir de aquí.', '', 28153),
(149250, 'esMX', 'Prueba con la daga que puse en tu bolsillo. Creo que te gustará.', '', 28153),
(149249, 'esMX', 'Después de ti, $n. Tú marca los objetivos aislados y yo los derribaré.', '', 28153),
(149248, 'esMX', 'Una vez rota, la confianza es casi imposible de reparar. Esto será letal para los señoriales zandalari. Bien hecho, adalid.', '', 28153),
(149247, 'esMX', 'Los representantes de las tribus trol menores se han reunido bajo el ala de los zandalari, pero son débiles. Maten a los portavoces y siembren la discordia entre nuestros enemigos.', '', 28153),
(149246, 'esMX', '¡Quemen sus carretas y rómpanles los huesos!', '¡Quemen sus carretas y rómpanles los huesos!', 28153),
(149245, 'esMX', 'Si estas alimañas están ocultando la llave, ¡la encontraremos!', 'Si estas alimañas están ocultando la llave, ¡la encontraremos!', 28153),
(149244, 'esMX', 'Conserva a los más fuertes. Se venderán bien en el mercado.', 'Conserva a los más fuertes. Se venderán bien en el mercado.', 28153),
(149243, 'esMX', '¿Está por terminar? ¡Díganme que está por terminar!', '', 28153),
(149242, 'esMX', '¡Vuelve aquí!', '¡Vuelve aquí!', 28153),
(149241, 'esMX', '', 'Vayamos al risco que está al noroeste. Desde ahí, en Alto de Arom podrán ver claramente nuestra señal.', 28153),
(149240, 'esMX', '', '¡Pero antes de irnos, aprovechemos la situación y hagamos añicos al enemigo!', 28153),
(149239, 'esMX', '', 'Podemos enviar una señal de extracción en el terreno elevado del noroeste.', 28153),
(149238, 'esMX', '¡Esto es demencial! ¡No tan rápido!', '', 28153),
(149237, 'esMX', '¡Jajajaja! ¡Me gustan mucho estos pisotones que hacen temblar la tierra!', '', 28153),
(149236, 'esMX', '', 'Usar la mismísima arma del aquelarre en su contra genera cierta satisfacción.', 28153),
(149235, 'esMX', 'El fuego despide un humo púrpura. Pronto deberían verlo por encima de los árboles.', '', 28153),
(149234, 'esMX', 'Primero deja que les dé la señal a los otros para que inicien el asalto.', '', 28153),
(149233, 'esMX', 'No. Con el tiempo, vendrán a nosotro\'.', '', 28153),
(149232, 'esMX', '', '¿Deberíamos ir tras ello\'?', 28153),
(149231, 'esMX', 'Basta de pacto\' con forasteros... Basta de tratos con lo\' loa. Ahora seguimos el camino de la sangre... ¡El camino de G\'HUUN!', '', 28153),
(149230, 'esMX', 'No tengo hambre ahora. Regresa má\' tarde...', '', 28153),
(149229, 'esMX', '¿Me creerías si te dijera que todo marcha de acuerdo al plan? Ya me parecía.', '', 28153),
(149228, 'esMX', '¡Buenas noticias! Descubrí la posición del enemigo. Nos tienen rodeados.', '', 28153),
(149227, 'esMX', 'Mmm... ¿podríamos no contarle a Roz sobre esto?', '', 28153),
(149226, 'esMX', 'Este no es mi mejor momento.', '', 28153),
(149225, 'esMX', 'Te ofrezco eh\'ta profecía: el imperio trol dominará el mundo, tal como en el principio de los tiempo\'. Y un rey ocupará eh\'te trono, tal como en el principio de los tiempo\', aunque ni tú ni yo viviremos para verlo. Esa es la visión que me otorga MI dios...', '', 28153),
(149224, 'esMX', 'Te has dejado eh\'tar, viejo amigo. Dejaste que nueh\'tro reino se pudriera lentamente. Pero yo he vaticinado que el imperio trol recuperará su esplendor.', '', 28153),
(149223, 'esMX', 'Tendrías que haber eh\'cuchado a Talanji.', '', 28153),
(149221, 'esMX', 'No! Habutu!', '', 28153),
(149220, 'esMX', '¡Jajaja! ¡Qué audaz!', '', 28153),
(149219, 'esMX', 'Se acerca la hora de la sangre.', '', 28153),
(149218, 'esMX', 'El tiempo de lo\' loa... ha llegado a su fin.', '', 28153),
(149217, 'esMX', 'No soy tu súbdito,', '', 28153),
(149216, 'esMX', 'Rezan, Rezan...', '', 28153),
(149215, 'esMX', 'Cuida tu lengua, traidor.', '', 28153),
(149214, 'esMX', 'Ah, aquí llega. El loa de... Mmm...', '', 28153),
(149212, 'esMX', '', 'Espero que tus visione\' sean ciertas.', 28153),
(149211, 'esMX', '¡Hereje!', '', 28153),
(149210, 'esMX', '', '¡Anticipen los movimientos de sus compañeros!', 28153),
(149209, 'esMX', '', '¡Ataquen como el viento! ¡Bloqueen!', 28153),
(149208, 'esMX', '', '¡Nadie descansa hasta que terminen sus ejercicios!', 28153),
(149207, 'esMX', '', '¡Concéntrense en su compañero! ¡Ataquen con decisión!', 28153),
(149206, 'esMX', '¡Comandante! ¿Me parece a mí o... colapsó?', '¡Comandante! ¿Me parece a mí o... colapsó?', 28153),
(149205, 'esMX', 'Hermana, ¿estás bien? ¡No fue mi intención golpearte tan fuerte!', 'Hermana, ¿estás bien? ¡No fue mi intención golpearte tan fuerte!', 28153),
(149204, 'esMX', 'Ay, no... ¿Acaso te...? ¡¿Estás bien?!', 'Ay, no... ¿Acaso te...? ¡¿Estás bien?!', 28153),
(149200, 'esMX', 'Nada tan satisfactorio como eliminar a un comandante de la Alianza. Y tan fácilmente...', '', 28153),
(149199, 'esMX', '', 'Buenos vientos, $n.', 28153),
(149198, 'esMX', '', 'La Orden de las Ascuas ha prevalecido contra Gorak Tul una vez más. Continuaremos resistiendo junto a nuestros aliados.', 28153),
(149197, 'esMX', '', 'Gracias por ayudarme, $n. Informaré sobre el éxito de nuestra misión a Lady Lucille.', 28153),
(149196, 'esMX', 'Me estremezco de solo pensar en lo que habría pasado con nosotros si tú y la Inquisidora no hubieran intervenido.', '', 28153),
(149195, 'esMX', 'Agradezco no estar muerto.', '', 28153),
(149194, 'esMX', '', 'Ya es seguro volar hacia el bosque. Espero que lleguemos rápido.', 28153),
(149193, 'esMX', '', 'Los jinetes de grifos aguardan esta señal.', 28153),
(149192, 'esMX', 'Muy, muy, muy desprolijo. ¡No hagas tanto ruido la próxima vez!', '', 28153),
(149191, 'esMX', '¡Maldición! Se suponía que esto tenía que ser rápido y discreto. ¡Concéntrate!', '', 28153),
(149190, 'esMX', '¡Maten a este rápido, antes de que alerte a los otros!', '', 28153),
(149189, 'esMX', '¡Trata de que no te vean! No podemos llamar demasiado la atención...', '', 28153),
(149187, 'esMX', 'Ah, no, no. ¡Déjenme este a mí!', '', 28153),
(149186, 'esMX', 'Voy a hacer la vista gorda con ese. No puedo decir que nunca maté a un hombre mientras dormía.', '', 28153),
(149185, 'esMX', 'Ey, ey... No te entusiasmes con los civiles. Podríamos llamar la atención de los guardias.', '', 28153),
(149184, 'esMX', 'En realidad eso no era un guardia, pero jamás impediría que matemos a alguien de la Alianza.', '', 28153),
(149183, 'esMX', 'Técnicamente no es necesario que matemos civiles... pero me gusta tu estilo.', '', 28153),
(149182, 'esMX', 'Eres más $gfrío:fría; que el hielo... me gusta.', '', 28153),
(149181, 'esMX', 'Una de nuestras ingenieras dijo haber visto a algunos tontos de la Alianza cerca de nuestra mina mientras buscaba repuestos. Ve a ver a Margie en el Taller para informarte más y para... eh... prepararte.', '', 28153),
(149180, 'esMX', '¡El pecho se me...! ¡No puedo respirar!', '¡El pecho se me...! ¡No puedo respirar!', 28153),
(149179, 'esMX', '¡Se me cierra... la garganta!', '¡Se me cierra... la garganta!', 28153),
(149178, 'esMX', 'Creo que tengo náuseas...', 'Creo que tengo náuseas...', 28153),
(149177, 'esMX', 'Solo necesito... descansar...', 'Solo necesito... descansar...', 28153),
(149176, 'esMX', 'Todo está tan... oscuro...', 'Todo está tan... oscuro...', 28153),
(149175, 'esMX', 'Me siento... raro.', 'Me siento... rara.', 28153),
(149174, 'esMX', '¡No! ¡¡Noooo!!', '', 28153),
(149173, 'esMX', '¡¿Q-qué?!', '', 28153),
(149172, 'esMX', '¡Ey, tú! ¡Alto ahí!', '', 28153),
(149171, 'esMX', '', 'E\' como si desearan morir... eh\'pero que su sangre no fortalezca a G\'huun.', 28153),
(149170, 'esMX', '', 'Aún desafían a Bwonsamdi. Tendrán un final poco grato. Adalid, nueh\'tro pacto con Bwomsamdi sigue en pie. ¡Devuelve eh\'tas alma\' perdidas!', 28153),
(149169, 'esMX', 'Espera, no. Era mi otra pierna. Está bien.', '', 28153),
(149168, 'esMX', '¡Algo me tocó la pierna!', '', 28153),
(149167, 'esMX', 'El premio mayor está sano y salvo. ¡Ven a tomar tu parte!', '', 28153),
(149166, 'esMX', '¡Parece que nuestros mineros dieron con el premio mayor! Tráelo a nuestra base sin un rasguño y tendremos enormes beneficios.', '', 28153),
(149165, 'esMX', '', '¡Vamos! Yo estaré vigilándote bien de cerca.', 28153),
(149164, 'esMX', '', '¡Los explosivos nunca están de más!', 28153),
(149163, 'esMX', '', '¿Conoces a algún noble kultirano con mucho oro y poca seguridad?', 28153),
(149162, 'esMX', '', 'Estoy buscando personas inteligentes como tú, $p, que quieran invertir mucho oro en el negocio que abriré.', 28153),
(149161, 'esMX', '', 'Una gnoma deben andar con cuidado entre los kultiranos.', 28153),
(149160, 'esMX', '', 'Si tienes dudas, que vuele por las alturas.', 28153),
(149159, 'esMX', '', 'Tol Barad, Tol Dagor, Mazmorras de Ventormenta, ¡las conozco todas!', 28153),
(149158, 'esMX', 'Envía la señal. ¡Salgamos de aquí!', 'Envía la señal. ¡Salgamos de aquí!', 28153),
(149157, 'esMX', '', 'Por favor, Rakera, ¡no lo hagas! ¡Solo conseguirás matarte!', 28153),
(149156, 'esMX', '', '¡Gracias a las arenas que estás con vida!', 28153),
(149155, 'esMX', '', '¡Eh\'ta intrusión termina aquí! ¡Nadie interrumpirá a la maestra!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'esMX', 'Eh\'tos pequeños no parecen una amenaza, $r.', '', 28153),
(149151, 'esMX', '', '¡Sigues con vida, $p! Tienes suerte como yo.', 28153),
(149150, 'esMX', 'Nos veremo\' luego.', '', 28153),
(149149, 'esMX', '¿Eso es todo?', '', 28153),
(149148, 'esMX', 'Tómatelo con calma.', '', 28153),
(149147, 'esMX', 'No hay problema, colega.', '', 28153),
(149146, 'esMX', '¿Necesitah\' vudú?', '', 28153),
(149145, 'esMX', '¿Qué necesita\'?', '', 28153),
(149144, 'esMX', '', 'Los trols de sangre no nos volverán a engañar, no mientras eh\'té viva.', 28153),
(149143, 'esMX', '', 'Los trols de sangre intentan sorprenderno\', pero tengo algo que te ayudará a verlo\'. ¡Usa eh\'te objeto y mata a eso\' trols de sangre!', 28153),
(149142, 'esMX', 'Recuperen fuerzas. No nos detendremos hasta llegar al barco.', '', 28153),
(149141, 'esMX', '¡Adiós, eh\'to no es para mí!', '¡Adiós, eh\'to no es para mí!', 28153),
(149140, 'esMX', 'Zul nos matará a todoh\'.', 'Zul nos matará a todoh\'.', 28153),
(149139, 'esMX', '¡Es el fin de loh\' tiempos!', '¡Es el fin de loh\' tiempos!', 28153),
(149138, 'esMX', 'Eh\'to es terrible para el negocio.', 'Eh\'to es terrible para el negocio.', 28153),
(149137, 'esMX', 'Me largo de aquí.', 'Me largo de aquí.', 28153),
(149136, 'esMX', '¡Ey! ¡¿Qué pasa aquí?!', '', 28153),
(149135, 'esMX', '¡GUARDIA! ¡GUARDIA! ¡AYUDA! ¡¡OOOHHH!!', '', 28153),
(149134, 'esMX', '¡AUCH! ¡ANIMAL!', '', 28153),
(149133, 'esMX', '¡No seas $Utímido:tímida;! Dame tu mejor golpe.', '', 28153),
(149132, 'esMX', '¡Vamos, golpéame!', '', 28153),
(149131, 'esMX', 'Golpéame.', '', 28153),
(149130, 'esMX', 'Bien, este es el plan:', '', 28153),
(149129, 'esMX', 'Entrada 3: ¡Ya casi lo logro! Las abejas están creciendo y la productividad aumenta exponencialmente. Sin embargo, debo controlar de cerca a la reina.', '', 28153),
(149128, 'esMX', 'Entrada 2: La hidromiel reanimada ha comenzado a mostrar señales agresivas. Quizá cometí un pequeño error de cálculo.', '', 28153),
(149127, 'esMX', 'Entrada 1: La miel está viva, pero se reproduce a una velocidad que jamás había imaginado. ¡Debo hacer más pruebas!', '', 28153),
(149126, 'esMX', '¡Apaguen las llamas! ¡Intercéptenlos!', '', 28153),
(149125, 'esMX', '¡Miren cómo huyen, con el rabo entre las patas!', '', 28153),
(149124, 'esMX', '¡Huyan, como las ratas que son!', '', 28153),
(149123, 'esMX', '', 'Esto es una locura. Morirán aquí y solo tendrán como premio una tumba sin nombre.', 28153),
(149122, 'esMX', '', 'Sabía que los de la Horda eran crueles y sin corazón. Despiadados para lograr la victoria. ¿Pero esto...?', 28153),
(149121, 'esMX', '¡Los encontré, mi rey! ¡Traeré sus pellejos como trofeo!', '', 28153),
(149120, 'esMX', 'Oh... No finjas que no te alegras de verno\'.', '', 28153),
(149119, 'esMX', 'Maravilloso. De verdad. Ahora, vámonos. ¿Listos?', '', 28153),
(149118, 'esMX', '', 'Eres un enemigo cruel, Zul.', 28153),
(149117, 'esMX', '', 'No podemos contra ella. ¡Corran!', 28153),
(149116, 'esMX', '', '¿Qué ocurre ahora?', 28153),
(149115, 'esMX', 'Vaya, este sí que es un lindo problema.', '', 28153),
(149114, 'esMX', '', '¡El puerto! ¡Debemos continuar!', 28153),
(149113, 'esMX', 'Cualquiera creería que una ciudad de piedra sería menos... inflamable.', '', 28153),
(149112, 'esMX', 'Tratan de atraparno\'. ¡No dejen que nos acorralen!', '', 28153),
(149111, 'esMX', 'Será mejor eh\'perar aquí, créanme.', '', 28153),
(149110, 'esMX', 'Tenemo\' que regresar a los canale\'. ¡Síganme!', '', 28153),
(149109, 'esMX', 'Bueno, eh\'to sí será útil.', '', 28153),
(149108, 'esMX', '', '¡Debemos escondernos!', 28153),
(149107, 'esMX', '', '¡Cuidado!', 28153),
(149106, 'esMX', 'El viejo lobo huele nueh\'tra presencia. ¡Salgamo\' de aquí!', '', 28153),
(149105, 'esMX', '', 'Son demasiados... ¡la barrera no resistirá!', 28153),
(149104, 'esMX', '¡Ahí está! ¡Deténgalos antes de que lleguen a las puertas!', '¡Ahí está! ¡Deténgalos antes de que lleguen a las puertas!', 28153),
(149103, 'esMX', '¿Pensaste que te habías salido con la tuya? ¡Pensaste mal!', '¿Pensaste que te habías salido con la tuya? ¡Pensaste mal!', 28153),
(149102, 'esMX', '¡Ahí abajo! ¡Traigan esos recursos!', '¡Ahí abajo! ¡Traigan esos recursos!', 28153),
(149101, 'esMX', '', 'Los trols de sangre son criaturas enferma\'. Nunca jamás cambiarán.', 28153),
(149100, 'esMX', '', '¡Los trols de sangre devoran a mi pueblo! Detenlo\'!', 28153),
(149099, 'esMX', '¡La conmoción ha atraído al picoatroz!', '¡La conmoción ha atraído al picoatroz!', 28153),
(149098, 'esMX', '¡El olor del cebo en el agua atrae a los pico de hacha!', '¡El olor del cebo en el agua atrae a los pico de hacha!', 28153),
(149097, 'esMX', '¡Gracias, $c! No me entusiasmaba mucho la idea de terminar en la punta de una pica.', '', 28153),
(149096, 'esMX', '¡Allí estás! ¿Te molestaría darme una mano?', '', 28153),
(149095, 'esMX', 'Se agradece tu entusiasmo, $c. Nos reuniremos con la señorita Tarjasenda.', '', 28153),
(149094, 'esMX', '', '¿Me ayudas?', 28153),
(149093, 'esMX', 'Gracias por la ayuda.', '', 28153),
(149092, 'esMX', '¡Malditas brujas con sus barreras!', '', 28153),
(149091, 'esMX', '', 'Estas crías jóvene\' se ven muy bien. Algún día serán buenas bestia\' de guerra.', 28153),
(149090, 'esMX', '', 'Las bestia\' de guerra jóvenes requieren atención y afecto constantes. Deben aprender a interactuar con nosotro\', así como nosotros debemo\' aprender a interactuar con ellas.', 28153),
(149089, 'esMX', '¡Oigo lo\' llamamiento\'!', '', 28153),
(149088, 'esMX', 'Perdí todas mis arma\', pero al menos conservé la vida.', '', 28153),
(149087, 'esMX', 'Me sorprendieron mientra\' exploraba... No volverá a suceder.', '', 28153),
(149086, 'esMX', '¡Volveré y haré que eso\' trols de sangre paguen por lo que hicieron!', '', 28153),
(149085, 'esMX', 'Gracia\', volveré a Zul\'jan.', '', 28153),
(149084, 'esMX', '', 'Gracias. ¡Eh\'pero que esos goblins empiecen a preocuparse por salvar mi ciudad en lugar de hacer negocio\'!', 28153),
(149083, 'esMX', '', 'Un grupo de prospectore\' goblin ha quedado atrapado en mano\' de los no-muertos. ¡Debemos liberarlos!', 28153),
(149082, 'esMX', '¿Sabes para qué puede servir este alquitrán? Yo tampoco, ¡pero dicen que es VALIOSÍSIMO!', '', 28153),
(149081, 'esMX', 'Esto sí que es caer bajo. Literalmente. ¡Yo me voy!', '', 28153),
(149080, 'esMX', 'Bueno, de todos modos ya me iba. ¡Este alquitrán valdrá una fortuna!', '', 28153),
(149079, 'esMX', '¡Estuvo cerca! Eh, recoge un poco de alquitrán para mí, ¿sí? Podremos venderlo por mucho dinero cuando regresemos.', '', 28153),
(149078, 'esMX', 'Gracias. ¿Quién diría que sería peligroso buscar alquitrán en un pantano prohibido?', '', 28153),
(149076, 'esMX', 'Korthek ha ido demasiado lejos. Yo mismo me encargaré de esto. Protege las llaves en mi ausencia.', '', 28153),
(149075, 'esMX', '', 'Eso les demoh\'trará a lo\' trols de sangre que se acerca el fin de sus días.', 28153),
(149074, 'esMX', '', 'El escuadrón goblin tiene un plan para vencer a los trols de sangre. Fíjate qué puedes hacer para reh\'catarlos.', 28153),
(149073, 'esMX', 'Subamos al M.I.D.A.S.-V y detengamos a ese ejército de trols de sangre.', 'Subamos al M.I.D.A.S.-V y detengamos a ese ejército de trols de sangre.', 28153),
(149072, 'esMX', '¡Hola! Algunos horribles trols de sangre se dirigen a Zuldazar. Por suerte para nosotros, hemos perfeccionado el M.I.D.A.S.\n\n¡Contempla al M.I.D.A.S.-V! ¡Esta belleza puede VOLAR! ¡Muerte desde el cielo!\n\nClaro que tuvimos que deshacernos del escudo, esta cosa no puede volar con eso.\n\n¿Quieres hacer un vuelo de prueba? ¡Hagamos pedazos a ese ejército!', '', 28153),
(149071, 'esMX', 'Eres inservible... como los demás...', '', 28153),
(149070, 'esMX', '¿$GOtro exiliado:Otra exiliada; para degollar? Hoy es un buen día, jajajaja…', '', 28153),
(149066, 'esMX', 'Ve, pequeño rey. Me tragaré a todos los que intenten seguirte.', '', 28153),
(149065, 'esMX', 'Quizá sea algo.', '', 28153),
(149064, 'esMX', '', 'Zul eh\'tá muy tranquilo. Quizá no sea nada.', 28153),
(149063, 'esMX', 'No pueden haber ido muy lejos. Tu vigilancia nos protege a todos.', '', 28153),
(149062, 'esMX', '¡Se han infiltrado intrusos de la Horda en las Mazmorras! ¡Los civiles deben permanecer en sus hogares hasta que eliminemos la amenaza!', '', 28153),
(149061, 'esMX', '¡Por orden del rey!', '', 28153),
(149060, 'esMX', 'Yo nos mantendré oculto\', siempre y cuando nadie haga estupidece\'.', '', 28153),
(149059, 'esMX', '¡Ja, ja! No te preocupes, mi querido Ancel, ¡no es más que un contratiempo! Pronto estaremos encaminados nuevamente.', '¡Ja, ja! No te preocupes, mi querido Ancel, ¡no es más que un contratiempo! Pronto estaremos encaminados nuevamente.', 28153),
(149058, 'esMX', '¿Qué? ¿Qué dices? ¡Estuviste a punto de ser asesinado y de arruinar toda la granja!', '', 28153),
(149057, 'esMX', '¡Que depende de nosotros seguir adelante con el arte de producir miel, sin importar el costo!', '¡Que depende de nosotros seguir adelante con el arte de producir miel, sin importar el costo!', 28153),
(149056, 'esMX', 'Claramente no era necesario.', '', 28153),
(149055, 'esMX', 'AHORA.', '', 28153),
(149054, 'esMX', '¿Eh?', '', 28153),
(149053, 'esMX', '', 'No te preocupes, sabremo\' si su vida eh\'tá en peligro.', 28153),
(149052, 'esMX', 'Continuemos.', '', 28153),
(149051, 'esMX', '', 'Un momento... ¿Dónde están los guardias?', 28153),
(149050, 'esMX', 'Vamos. Permaneh\'can junto\'.', '', 28153),
(149049, 'esMX', 'La próxima vez podrías advertirnos ante\'...', '', 28153),
(149048, 'esMX', 'Mantente alerta. La IV:7 nos ha informado que el enemigo apareció cerca de la fortaleza.', '', 28153),
(149047, 'esMX', 'Salten del puente. Ahora.', '', 28153),
(149046, 'esMX', 'Crucemos el puente. A meno\' que tu profeta tenga algún problema.', '', 28153),
(149045, 'esMX', '¡Ey! Rápido, fuera del camino.', '', 28153),
(149044, 'esMX', 'Eh\'peren aquí.', '', 28153),
(149043, 'esMX', '¡Atención, ciudadanos de Ventormenta!', '', 28153),
(149042, 'esMX', 'Muy bien. Manténganse cerca. Ahora somo\' todos amigo\'.', '', 28153),
(149041, 'esMX', '', 'La ciudad es un caos. No podemos quedarnos aquí.', 28153),
(149040, 'esMX', '¡Todo listo para zarpar!', '¡Todo listo para zarpar!', 28153),
(149039, 'esMX', '', '¿Estás $glisto:lista; para viajar a Kul Tiras?', 28153),
(149038, 'esMX', '', 'Gracias a tu trabajo, hemos ganado tiempo y Krag\'wa puede fortalecer sus defensa\'. Gracias.', 28153),
(149037, 'esMX', '¡No pueden impedirme que recupere lo que me pertenece!', '', 28153),
(149036, 'esMX', '', '¡Los trols de sangre continúan sus ataque\' contra Krag\'wa! Corta su línea de suministros, ¡que paguen por su agresión!', 28153),
(149035, 'esMX', 'Sethraliss... he olvidado tu voz...', '', 28153),
(149034, 'esMX', 'No nos sometemos a los loa. ¡Tenemos fuerza propia!', '', 28153),
(149033, 'esMX', '¡Intrusos! Se meten en asuntos que no pueden comprender.', '', 28153),
(149031, 'esMX', 'PLACEHOLDER SCENE - Talanji asks if things are really over, Rokhan says evil has a way of surviving and he doubts this will be the last we see of this place.\nShot: Close ups of Talanji and Rokhan, then ominous shot of the now revealed pit.', 'PLACEHOLDER SCENE - Talanji asks if things are really over, Rokhan says evil has a way of surviving and he doubts this will be the last we see of this place.\nShot: Close ups of Talanji and Rokhan, then ominous shot of the now revealed pit.', 28153),
(149030, 'esMX', '', 'Amo... he... he fallado...', 28153),
(149029, 'esMX', '', 'Gorak Tul... está llegando...', 28153),
(149028, 'esMX', '', 'Gorak Tul... me prometió poder...', 28153),
(149027, 'esMX', '', 'Quizás yo no sea una guerrera muy hábil, pero mi madre debe responder por sus actos... Y debo encargarme de eso.', 28153),
(149026, 'esMX', '', '¡Por mi padre! ¡Por Drustvar!', 28153),
(149025, 'esMX', '', 'Nos veremos adentro, inquisidora.', 28153),
(149024, 'esMX', '', '¡Inquisidores, síganme! ¡Gloria a la casa Tarjasenda!', 28153),
(149023, 'esMX', '', 'Sí, señora. No dejaremos rastro del aquelarre.', 28153),
(149022, 'esMX', '', 'Inquisidores, la batalla final está en sus manos. Que el viento sople a su favor.', 28153),
(149021, 'esMX', '', 'Madre... ¿qué has hecho?', 28153),
(149020, 'esMX', '', 'No, Mariscal. No...', 28153),
(149019, 'esMX', 'Lo... siento...', '', 28153),
(149018, 'esMX', 'Querida Lucy... Te he... fallado...', '', 28153),
(149017, 'esMX', '', '¡Resista, mariscal!', 28153),
(149016, 'esMX', 'No... esto... ¡no puede ser!', '', 28153),
(149015, 'esMX', 'Yo... obedezco...', '', 28153),
(149014, 'esMX', 'Cubriremos los flancos. ¡$n, quédate con Lucille y el mariscal!', '', 28153),
(149013, 'esMX', '', '¡Le has chillado a la mujer incorrecta, bruja!', 28153),
(149012, 'esMX', '¡No se detengan, casi lo logramos! ¡A los ojos, Winston!', '', 28153),
(149011, 'esMX', 'Estaré detrás de ti.', 'Estaré detrás de ti.', 28153),
(149010, 'esMX', '¡Por la casa Tarjasenda!', '', 28153),
(149009, 'esMX', '¡Manténgase juntos, y no dejen de avanzar hasta que hayamos atravesado las puertas de la mansión!', '', 28153),
(149008, 'esMX', 'No duraremo\' mucho más a este paso. Debemo\' correr hacia los muelles.\n\nAvisen cuando estén listo\'.', '', 28153),
(149007, 'esMX', '¡Inquisidores! ¡Esta es nuestra oportunidad de salvar a Lord y Lady Tarjasenda... y poner fin a este insufrible aquelarre!', '', 28153),
(149005, 'esMX', '', 'Veo cómo tiemblan. ¿Tienen miedo, Alianza?', 28153),
(149004, 'esMX', '', '¿Estás $umareado:mareada;?', 28153),
(149003, 'esMX', '', '¿De verdad pensaste que podías vencerme?', 28153),
(149002, 'esMX', '', 'Muerta... por una escoria...', 28153),
(149001, 'esMX', '¡La victoria está fuera de su alcance!', '', 28153),
(149000, 'esMX', '¡Estás en el lugar equivocado!', '', 28153),
(148999, 'esMX', '¡Que arda en las llamas!', '', 28153),
(148998, 'esMX', 'Eso es... trampa...', '', 28153),
(148997, 'esMX', '¡Yo te cubro!', '', 28153),
(148996, 'esMX', '¡Posiciones defensivas!', '', 28153),
(148995, 'esMX', 'La Luz... me guiará de regreso.', '', 28153),
(148994, 'esMX', '', '¡Sáquenle\' el corazón!', 28153),
(148993, 'esMX', '', '¡Le enviaré tu alma a Gorak Tul!', 28153),
(148991, 'esMX', '¡Prepárense! Nos atacan.', '¡Prepárense! Nos atacan.', 28153),
(148990, 'esMX', '¡Protejan los recursos!', '¡Protejan los recursos!', 28153),
(148989, 'esMX', '¡Este bosque nos pertenece!', '¡Este bosque nos pertenece!', 28153),
(148988, 'esMX', '¡No se acerquen más!', '¡No se acerquen más!', 28153),
(148987, 'esMX', '¡Atrás!', '¡Atrás!', 28153),
(148986, 'esMX', 'Los Guardianes eran los más poderosos entre nosotros. Estaban a cargo de sellar el cadáver de Mythrax en el interior de la gran pirámide.\n\nSulthis fue el fundador, pero no podía sellar la tumba por sí solo.\n\nLes pidió ayuda a Vorrik y a Korthek y juntos formaron una barrera alrededor de la gran pirámide para sellar en el interior el cadáver de Mythrax.', 'Los Guardianes eran los más poderosos entre nosotros. Estaban a cargo de sellar el cadáver de Mythrax en el interior de la gran pirámide.\n\nSulthis fue el fundador, pero no podía sellar la tumba por sí solo.\n\nLes pidió ayuda a Vorrik y a Korthek y juntos formaron una barrera alrededor de la gran pirámide para sellar en el interior el cadáver de Mythrax.', 28153),
(148985, 'esMX', 'Se hace llamar \"emperador Korthek\", pero mucho tiempo atrás fue uno de los Guardianes, que tenían la tarea de proteger la tumba.\n\nSus ansias de guerra se oponen a todo lo que representa nuestra loa. Aún así, osa condenarla y desafiarla, y está reuniendo un ejército que cuyo único fin es conquistar Zuldazar.', 'Se hace llamar \"emperador Korthek\", pero mucho tiempo atrás fue uno de los Guardianes, que tenían la tarea de proteger la tumba.\n\nSus ansias de guerra se oponen a todo lo que representa nuestra loa. Aún así, osa condenarla y desafiarla, y está reuniendo un ejército cuyo único fin es conquistar Zuldazar.', 28153),
(148984, 'esMX', 'Los infieles son una fuerza de la milicia sethrak al mando del emperador Korthek.\n\nMucho tiempo atrás, todos vivíamos en unidad, como Sethraliss hubiera querido. \n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras. \n\nNo se detendrán hasta haber conquistado el mundo.', 'Los infieles son una fuerza de la milicia sethrak al mando del emperador Korthek.\n\nMucho tiempo atrás, todos vivíamos en unidad, como Sethraliss hubiera querido. \n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras. \n\nNo se detendrán hasta haber conquistado el mundo.', 28153),
(148983, 'esMX', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax devastaba nuestras tierras y amenazaba nuestra existencia, fue ella quien lo detuvo y dio su vida para salvarnos.\n\nA diferencia de los infieles, nosotros aún sentimos su presencia y creemos que un día regresará.', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax devastaba nuestras tierras y amenazaba nuestra existencia, fue ella quien lo detuvo y dio su vida para salvarnos.\n\nA diferencia de los infieles, nosotros aún sentimos su presencia y creemos que un día regresará.', 28153),
(148982, 'esMX', 'Los Guardianes eran los más poderosos entre nosotros. Estaban a cargo de sellar el cadáver de Mythrax en el interior de la gran pirámide.\n\nSulthis fue el fundador, pero no podía sellar la tumba por sí solo.\n\nLes pidió ayuda a Vorrik y a Korthek y juntos formaron una barrera alrededor de la gran pirámide para sellar en el interior el cadáver de Mythrax.', '', 28153),
(148981, 'esMX', 'Se hace llamar \"emperador Korthek\", pero mucho tiempo atrás fue uno de los Guardianes, que tenían la tarea de proteger la tumba.\n\nSus ansias de guerra se oponen a todo lo que representa nuestra loa. Aún así, osa condenarla y desafiarla, y está reuniendo un ejército que cuyo único fin es conquistar Zuldazar.', '', 28153),
(148980, 'esMX', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax devastaba nuestras tierras y amenazaba nuestra existencia, fue ella quien lo detuvo y dio su vida para salvarnos.\n\nA diferencia de los infieles, nosotros aún sentimos su presencia y creemos que un día regresará.', '', 28153),
(148979, 'esMX', '', 'Exijo tu presencia inmediata en Orgrimmar para liderar una misión de suma urgencia. No me hagas esperar.', 28153),
(148978, 'esMX', '', 'Es posible que la victoria dependa de tus habilidades.', 28153),
(148977, 'esMX', 'Los infieles son una fuerza de la milicia sethrak al mando del emperador Korthek.\n\nMucho tiempo atrás, todos vivíamos en unidad, como Sethraliss hubiera querido. \n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras. \n\nNo se detendrán hasta haber conquistado el mundo.', '', 28153),
(148976, 'esMX', '', 'Adalid, la Horda está en plena guerra con la Alianza.', 28153),
(148975, 'esMX', 'Esta isla está expulsando una enorme cantidad de azerita. Debe haber un cúmulo bastante grande cerca.', '', 28153),
(148974, 'esMX', '¡El detector de azerita está activo! Deberíamos poder ver toda la isla ahora.', '', 28153),
(148973, 'esMX', 'Sethraliss es nuestra amada loa.\n\nCuando Mythrax devastaba nuestras tierras y amenazaba nuestra existencia, fue ella quien lo detuvo y dio su vida para salvarnos.\n\nA diferencia de los infieles, nosotros aún sentimos su presencia y creemos que un día regresará.', '', 28153),
(148972, 'esMX', 'Se hace llamar \"emperador Korthek\", pero mucho tiempo atrás fue uno de los Guardianes, que tenían la tarea de proteger la tumba.\n\nSus ansias de guerra se oponen a todo lo que representa nuestra loa. Aún así, osa condenarla y desafiarla, y está reuniendo un ejército que cuyo único fin es conquistar Zuldazar.', '', 28153),
(148971, 'esMX', 'Jamás olvidaremos lo que nuestra loa hizo por nosotros.', 'Jamás olvidaremos lo que nuestra loa hizo por nosotros.', 28153),
(148970, 'esMX', '', 'Gracias, adalid. Mis ayudantes eh\'tán ansiosos por analizar los texto\'. Ojalá descifren algo que pueda ayudarnos a derrotar al dios de sangre.', 28153),
(148969, 'esMX', '', 'Quizá eh\'ta instalación contenga información sobre cómo contener o deh\'truir a G\'huun. Buh\'sca reliquias y textos que puedan servirnos.', 28153),
(148968, 'esMX', 'Nuestra fe nos mantiene fuertes.', 'Nuestra fe nos mantiene fuertes.', 28153),
(148966, 'esMX', 'Defenderemos el templo a toda costa.', 'Defenderemos el templo a toda costa.', 28153),
(148965, 'esMX', 'No abandonaremos el templo.', 'No abandonaremos el templo.', 28153),
(148962, 'esMX', 'Un barco entra al calabozo. Pike expresa su preocupación al ver que un barco con aldeanos entra en el sagrario de su orden.', 'Un barco entra al calabozo. Pike expresa su preocupación al ver que un barco con aldeanos entra en el sagrario de su orden.', 28153),
(148959, 'esMX', '¿Qué sucede?', '¿Qué sucede?', 28153),
(148958, 'esMX', 'Puedo sentirlo con fuerza aquí. Algo oscuro se alza.', '', 28153),
(148955, 'esMX', 'Me pregunto en qué estaba trabajando mi padre aquí abajo...', '', 28153),
(148954, 'esMX', 'Tenemo\' que irnos de aquí. Puedo hacer que nos escabullamo\' de los guardias.\n\nAvísenme cuando estén listo\'.', '', 28153),
(148953, 'esMX', '¡Abran paso!', '', 28153),
(148952, 'esMX', '¡Mantente a la derecha! ¡Creo que vi una salida!', '', 28153),
(148946, 'esMX', '¡Excelente! Eh\'tos materiales servirán de remates para flechas y fundas para armadura\'.', '', 28153),
(148945, 'esMX', 'Nazmir es letal, pero eh\'conde muchos recursos, si sabes dónde buh\'car. Buh\'ca recursos en la coh\'ta, necesitamo\' suministros para las tropa\'.', '', 28153),
(148944, 'esMX', '¡¿Qué hacemos ahora, $p?!', '', 28153),
(148943, 'esMX', '', '¡Mala suerte!', 28153),
(148942, 'esMX', '', '¡Debes presentarte ante Theock! Estará feliz de saber que la mina está bajo control.', 28153),
(148941, 'esMX', '', '¡Lo logramos!', 28153),
(148940, 'esMX', '', '¿Moriré... tan lejo\'... de G\'huun...?', 28153),
(148939, 'esMX', '', '¡SANGRE PARA G\'HUUN!', 28153),
(148938, 'esMX', '¡Te veré en el laboratorio!', '¡Te veré en el laboratorio!', 28153),
(148936, 'esMX', 'El templo está allá adelante.', '', 28153),
(148935, 'esMX', 'Haremos lo que sea para detenerlo.', '', 28153),
(148934, 'esMX', 'Los lidera en su lucha mientras busca las llaves restantes que le permitirán romper la barrera que rodea Atul\'Aman y usar lo que haya dentro para conquistar Zuldazar.', '', 28153),
(148933, 'esMX', 'Desde la traición de Korthek, los infieles han traído la guerra a estas tierras.', '', 28153),
(148932, 'esMX', 'Hace mucho tiempo vivíamos en unidad, como nuestra loa hubiera querido.', '', 28153),
(148931, 'esMX', 'Nuestro templo es el último bastión contra los infieles.', '', 28153),
(148930, 'esMX', 'Guerreros de la Horda: ¡acudan al llamado de la batalla! Den una muerte rápida a nuestros enemigos.', '', 28153),
(148929, 'esMX', 'Creo que quieres un tortollano, ¿verdad?', 'Creo que quieres un tortollano, ¿verdad?', 28153),
(148928, 'esMX', '¡No se queden sin su tortollano! Pueden mantenerlos vivos o usar su caparazón para guardar cosas.', '¡No se queden sin su tortollano! Pueden mantenerlos vivos o usar su caparazón para guardar cosas.', 28153),
(148927, 'esMX', '¿Alguna oferta más alta? ¡Tortollanos recién capturados en su peregrinaje de Nazmir!', '¿Alguna otra oferta? ¡Tortollanos recién capturados en su peregrinaje de Nazmir!', 28153),
(148925, 'esMX', '¡No tendrán una oportunidad mejor para conseguir un vulpera como estos!', '¡No tendrán una oportunidad mejor para conseguir un vulpera como estos!', 28153),
(148924, 'esMX', 'Compren su propio vulpera, ¡rebosante de energía!', 'Compren su propio vulpera, ¡rebosante de energía!', 28153),
(148923, 'esMX', '¿Más ofertas para los vulperas? ¡Son de mucha utilidad!', '¿Más ofertas para los vulperas? ¡Son de mucha utilidad!', 28153),
(148922, 'esMX', '¡Hay que detener a los infieles!', '¡Hay que detener a los infieles!', 28153),
(148921, 'esMX', 'Creo que ya puedo regresar sin problemas.', 'Creo que ya puedo regresar sin problemas.', 28153),
(148920, 'esMX', 'Gracias. Puedo seguir desde aquí.', 'Gracias. Puedo seguir desde aquí.', 28153),
(148919, 'esMX', 'Venga a los que no pudieron ser salvados.', 'Venga a los que no pudieron ser salvados.', 28153),
(148918, 'esMX', 'No tienes idea de lo que nos hicieron sufrir...', 'No tienes idea de lo que nos hicieron sufrir...', 28153),
(148917, 'esMX', 'Ten cuidado, $p. Te diriges directamente a su nido.', '', 28153),
(148916, 'esMX', 'Reúnete con nosotros cuando hayas recuperado la piedra de Korthek.', '', 28153),
(148910, 'esMX', '¡Cómo te atreves a pisar eh\'tos terrenos de caza!', '¡Cómo te atreves a pisar eh\'tos terrenos de caza!', 28153),
(148909, 'esMX', '¡Pagarás por eso!', '¡Pagarás por eso!', 28153),
(148908, 'esMX', '¡La Alianza no tiene nada que hacer aquí!', '¡La Alianza no tiene nada que hacer aquí!', 28153),
(148907, 'esMX', '¡La Reserva les pertenece a loh\' zandalari!', '¡La Reserva les pertenece a loh\' zandalari!', 28153),
(148906, 'esMX', 'Sí, adelante, pierdan más tiempo dih\'cutiendo.', '', 28153),
(148905, 'esMX', '', 'Afuera, si el trol no nos ha engañado.', 28153),
(148904, 'esMX', '¿A dónde lleva eh\'to?', '', 28153),
(148903, 'esMX', '', 'Huele... desagradable.', 28153),
(148902, 'esMX', '', 'Los trols de sangre sabrán que ya no nos esconderemo\'. Bien hecho.', 28153),
(148901, 'esMX', '', 'Que alguien... los detenga...', 28153),
(148900, 'esMX', '', 'Nadie sorprende a la Séptima Legión. ¡Mueran, escoria de la Horda!', 28153),
(148899, 'esMX', '', 'Mis exploradores afirman que lo\' trols de sangre reúnen sus fuerzas cerca de aquí. ¡Enséñales a no meterse con lo\' zandalari!', 28153),
(148898, 'esMX', '', '¡Hasta aquí llegaron!', 28153),
(148897, 'esMX', '', 'Es un campo de anulación. ¡He perdido mi magia!', 28153),
(148896, 'esMX', 'Qué vudú más despreciable. ¿Thalyssra?', '', 28153),
(148895, 'esMX', '', 'Necesito un minuto. Hace horas que intento romper esta jaula.', 28153),
(148894, 'esMX', '', '¡Nunca destruirás mi maldición!', 28153),
(148893, 'esMX', 'Todas estas bestias algún día servirán a la Horda. No podemos permitir que eso suceda.', '', 28153),
(148892, 'esMX', 'Quizá las bestias se recuperen rápido, pero a la Horda le llevará mucho más tiempo reemplazar a sus guardabestias. ¡Bien hecho!', '', 28153),
(148891, 'esMX', 'La Reserva Zandalari está repleta de bestias de guerra, pero sin entrenamiento no son nada. Envenénalas para provocar a los guardabestias. Ellos son tu verdadero objetivo.', '', 28153),
(148890, 'esMX', '', 'Eh\'pero que tengas razón, Zul.', 28153),
(148889, 'esMX', 'Eso sería un error. E\' por el otro lado.', '', 28153),
(148888, 'esMX', '¡Por aquí!', '', 28153),
(148887, 'esMX', '', '¿Cómo saldremo\'?', 28153),
(148886, 'esMX', '', 'Gracias a ti, eh\'tamos un paso más cerca de ponerle fin a lo\' trols de sangre de una vez por todas.', 28153),
(148885, 'esMX', '', 'Siento un mojo oh\'curo en algún lugar cerca. ¡Deben ser los trols de sangre! ¡Encuéntralo\' y detén lo que eh\'tén haciendo!', 28153),
(148884, 'esMX', '', '¡Tenemos que movernos!', 28153),
(148883, 'esMX', '', '¡Cierren todo!', 28153),
(148879, 'esMX', 'Las nubes se despejan... La tormenta se disipa...', '', 28153),
(148878, 'esMX', '¡Soy el presagista de las tormentas!', '', 28153),
(148877, 'esMX', 'Las cortesías deberán esperar.', '', 28153),
(148876, 'esMX', '', 'Venimos en nombre de la Horda. Soy Thalyssra, y él es Rokhan.', 28153),
(148875, 'esMX', '', 'Hmm... Gracias. Mi profeta dice que son aliados.', 28153),
(148874, 'esMX', 'Oh, no, no, no. Te conozco. Eres esa serpiente que...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'esMX', 'Ah, nueh\'tra escolta llegó. Tal como dije, princesa.', '', 28153),
(148871, 'esMX', '$n, ven. Por aquí.', '', 28153),
(148870, 'esMX', 'Necesito descansar un momento.', '', 28153),
(148868, 'esMX', '¿Korthek cree que puede esconderse detrás de una pared? Siempre ha sido un idiota.', '', 28153),
(148867, 'esMX', 'Sigue el plan. Te alcanzo luego.', '', 28153),
(148858, 'esMX', '', 'Entiendo... Si estás seguro, alto señor supremo.', 28153),
(148857, 'esMX', 'Claro que sí. Lok\'tar.', '', 28153),
(148856, 'esMX', 'Tú... no vendrás con nosotro\'.', '', 28153),
(148855, 'esMX', 'Los dos sabemos que no han venido por mí. Su objetivo está al final del pasillo.', '', 28153),
(148854, 'esMX', 'A juzgar por los informes, parece que el momento de mayor vulnerabilidad del emperador es durante sus visitas al mercado, que está aquí cerca.', '', 28153),
(148853, 'esMX', 'Te conviene llevarte eh\'to.', '', 28153),
(148852, 'esMX', '', 'Los mantendremos ocupados. Ten cuidado.', 28153),
(148851, 'esMX', 'Me adelantaré para buscar a los prisionero\'. Protéjanme.', '', 28153),
(148850, 'esMX', '¡La Séptima Legión! No sé a quién vamo\' a liberar, pero los humano\' no quieren correr riesgos.', '', 28153),
(148849, 'esMX', 'Los encontraré luego. Buena suerte.', '', 28153),
(148848, 'esMX', 'Esa es nuestra salida. Vayan a ese barco después de liberar a los prisioneros.', '', 28153),
(148847, 'esMX', 'Les he entregado los medios para una muerte sencilla. Si no les quedan opciones, úsenlos.', '', 28153),
(148846, 'esMX', 'Si los capturan, la jefa de guerra y la Horda negarán todo conocimiento sobre la misión.', '', 28153),
(148845, 'esMX', 'Nuestros exploradores han encontrado una entrada oculta. El tauren y yo cubriremos su escape.', '', 28153),
(148844, 'esMX', 'Tú, Thalyssra y Rokhan se infiltrarán en las Mazmorras y liberarán a los prisioneros.', '', 28153),
(148843, 'esMX', 'Escuchen bien. Estaremos incomunicados una vez que entremos a Ventormenta.', '', 28153),
(148842, 'esMX', '', 'Nos aseguraremos de que los jabespines no puedan librar una guerra de esta escala otra vez.', 28153),
(148841, 'esMX', 'Tu fin... se acerca...', 'Tu fin... se acerca...', 28153),
(148840, 'esMX', 'Cómo es... posible...', 'Cómo es... posible...', 28153),
(148839, 'esMX', 'Te enfrentarás... al ojo... de la tormenta...', 'Te enfrentarás... al ojo... de la tormenta...', 28153),
(148838, 'esMX', 'Tú... caerás...', 'Tú... caerás...', 28153),
(148837, 'esMX', 'Mi alma... fluye... hacia el mar...', 'Mi alma... fluye... hacia el mar...', 28153),
(148836, 'esMX', 'Me dirijo... a... las profundidades...', 'Me dirijo... a... las profundidades...', 28153),
(148835, 'esMX', 'Regreso... a las profundidades...', 'Regreso... a las profundidades...', 28153),
(148834, 'esMX', 'Incluso la marea... retrocede...', 'Incluso la marea... retrocede...', 28153),
(148833, 'esMX', '¡Su poder corre por mis venas!', '¡Su poder corre por mis venas!', 28153),
(148832, 'esMX', '¡Acepta tu fin!', '¡Acepta tu fin!', 28153),
(148831, 'esMX', '¡Los tentáculos del destino te atraparán!', '¡Los tentáculos del destino te atraparán!', 28153),
(148830, 'esMX', '¡Yacerás inerte en el fondo del mar!', '¡Yacerás inerte en el fondo del mar!', 28153),
(148829, 'esMX', '¡Tú luz se desvanecerá en las profundidades!', '¡Tú luz se desvanecerá en las profundidades!', 28153),
(148828, 'esMX', '¡Nadie puede detener la marea!', '¡Nadie puede detener la marea!', 28153),
(148827, 'esMX', '¡Escucha la llamada de las profundidades!', '¡Escucha la llamada de las profundidades!', 28153),
(148826, 'esMX', '¡El mar se llevará tus restos!', '¡El mar se llevará tus restos!', 28153),
(148825, 'esMX', 'Tanta... oscuridad...', 'Tanta... oscuridad...', 28153),
(148824, 'esMX', 'Que las mareas... me lleven...', 'Que las mareas... me lleven...', 28153),
(148823, 'esMX', 'Muero... como un verdadero kultirano...', 'Muero... como una verdadera kultirana...', 28153),
(148822, 'esMX', 'Cómo... puede ser...', 'Cómo... puede ser...', 28153),
(148821, 'esMX', 'Así... no...', 'Así... no...', 28153),
(148820, 'esMX', '¡Me darán una recompensa por tu pellejo!', '¡Ja! ¡Me darán una recompensa por tu pellejo!', 28153),
(148819, 'esMX', '¡Fregaré la cubierta con tu cara!', '¡Fregaré la cubierta con tu cara!', 28153),
(148818, 'esMX', '¡Enfréntame!', '¡Enfréntame!', 28153),
(148817, 'esMX', '¡Les contaré a todos cómo te derroté!', '¡ja! ¡Les contaré a todos cómo te derroté!', 28153),
(148816, 'esMX', '¡Te arrepentirás!', '¡Te arrepentirás!', 28153),
(148815, 'esMX', 'El barquero... me llama...', 'El mar... me llama...', 28153),
(148814, 'esMX', 'Que las mareas... me lleven...', 'Que las mareas... me lleven...', 28153),
(148813, 'esMX', 'Muero... como un verdadero kultirano...', 'Muero… como una verdadera kultirana…', 28153),
(148812, 'esMX', 'El mar... cobrará... venganza...', 'El mar... cobrará... venganza...', 28153),
(148811, 'esMX', 'Bajo cinco brazas de agua... hallaré la calma…', 'Bajo cinco brazas de agua... hallaré la calma…', 28153),
(148810, 'esMX', '¡Otro trofeo para el manto!', '¡Otro trofeo para el manto!', 28153),
(148809, 'esMX', '', 'Aquí podemos hablar libremente. No puedo decir lo mismo de Orgrimmar.', 28153),
(148808, 'esMX', '¡Serás carnada para los peces!', '¡Serás comida para los peces!', 28153),
(148807, 'esMX', '¡Enfréntame!', '¡Enfréntame!', 28153),
(148806, 'esMX', '', 'Lamento el melodrama. Matthias Shaw ha enviado una enorme cantidad de espías.', 28153),
(148805, 'esMX', '¡Brindaré por tu muerte en el bar!', '¡Brindaré por tu muerte!', 28153),
(148804, 'esMX', 'Te arrepentirás.', 'Te arrepentirás.', 28153),
(148803, 'esMX', '', '¡Ey! ¡Déjame salir de aquí!', 28153),
(148802, 'esMX', '¡Vuelve a trabajar, insecto!', '¡Vuelve a trabajar, insecto!', 28153),
(148801, 'esMX', 'Te darán... tu merecido...', 'Te darán... tu merecido...', 28153),
(148800, 'esMX', 'Eso es... insubor... dinación...', 'Eso es... insubor... dinación...', 28153),
(148799, 'esMX', 'Puedes... retirarte...', 'Puedes... retirarte...', 28153),
(148798, 'esMX', 'Es tan difícil... encontrar... un ayudante digno...', 'Es tan difícil... encontrar... un ayudante digno...', 28153),
(148797, 'esMX', 'Esto... te saldrá... muy caro...', 'Esto... te saldrá... muy caro...', 28153),
(148796, 'esMX', 'Ahhh... maldición...', 'Ahhh... maldición...', 28153),
(148795, 'esMX', '¿Eso es... lo mejor... que tienes...?', '¿Eso es... lo mejor... que tienes...?', 28153),
(148794, 'esMX', 'Rata... asquerosa...', 'Rata... asquerosa...', 28153),
(148793, 'esMX', '¿Yo dije que podías descansar?', '¿Yo dije que podías descansar?', 28153),
(148792, 'esMX', '¡Servirás como ejemplo para los demás!', '¡Servirás como ejemplo para los demás!', 28153),
(148791, 'esMX', '¡Se acabó el descanso, canalla!', '¡Se acabó el descanso, canalla!', 28153),
(148790, 'esMX', '¡Te arrepentirás de esto!', '¡Te arrepentirás de esto!', 28153),
(148789, 'esMX', '¡Regresa a tu lugar!', '¡Regresa a tu lugar!', 28153),
(148788, 'esMX', '¡Pagarás por tu desobediencia!', '¡Pagarás por tu desobediencia!', 28153),
(148787, 'esMX', '¡Ponte en fila!', '¡Ponte en fila!', 28153),
(148786, 'esMX', '¡Salgamos de aquí!', '', 28153),
(148785, 'esMX', '', '¡Serrik, qué bueno que regresaste! ¡Los infieles han capturado a Vorrik!', 28153),
(148783, 'esMX', '', 'Déjennos $Gsolos:solas;.', 28153),
(148782, 'esMX', '', 'Ahhh, $n. Gracias por responder tan rápido.', 28153),
(148781, 'esMX', '', '¡Algerson está arrasando con los bosques! ¡No podemos permitir que continúe explotando la naturaleza de esta forma!', 28153),
(148780, 'esMX', 'Debes reunirte con el loa. ¿Estás $Glisto:lista;?', '', 28153),
(148779, 'esMX', 'La estatua se encuentra en algún lugar de las ruinas del templo...', '', 28153),
(148778, 'esMX', 'Necesitamos eliminar a las arañas antes de que nuestra tribu se pueda refugiar aquí.', '', 28153),
(148775, 'esMX', '¡Debemos informarle a la tribu lo que hemos descubierto!', '', 28153),
(148774, 'esMX', 'Me temo que nuestra tribu pronto perecerá sin alimento...', '', 28153),
(148773, 'esMX', 'Debemos averiguar qué es lo que buscan los nagas...', '', 28153),
(148772, 'esMX', 'Mis cálculos... No entiendo.', 'Mis cálculos... No entiendo.', 28153),
(148771, 'esMX', '<Suspira> Jamás saldré de aquí.', '<Suspira> Jamás saldré de aquí.', 28153),
