(148275, 'esMX', '', '', 28153),
(148274, 'esMX', '', 'No me importa lo que quiera tu jefa de guerra. Debo regresar con mi pueblo. Iremos a Zuldazar porque eh\'ta es mi nave y es tu única forma de salir de Ventormenta.\n\n¿Tiene\' alguna objeción?', 28153),
(148273, 'esMX', 'No, en absoluto.', 'No, en absoluto.', 28153),
(148272, 'esMX', '¡Te haré pedazos!', '¡Te haré pedazos!', 28153),
(148271, 'esMX', '¡Enfréntate al poder de la montaña!', '¡Enfréntate al poder de la montaña!', 28153),
(148270, 'esMX', '¡Te enseñaré a no desafiar a un Hierro Negro!', '¡Te enseñaré a no desafiar a un Hierro Negro!', 28153),
(148269, 'esMX', '¡Este no es tu lugar!', '¡Este no es tu lugar!', 28153),
(148267, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(148266, 'esMX', '¡He visto a la bruja del bosque con mis propios ojos! ¡Me largo de aquí antes de que me encuentre otra vez!', '', 28153),
(148265, 'esMX', '¿Cómo se supone que trabajemos en estas condiciones?', '', 28153),
(148264, 'esMX', 'Lo único que le importa a Algerson es el dinero, pero aquí tenemos problemas más grandes.', '', 28153),
(148263, 'esMX', 'Hay una bruja en este bosque, ¡y está furiosa! ¡Renuncio!', '', 28153),
(148262, 'esMX', '¡Esas bestias no son naturales! ¡Esto es obra de la bruja!', '', 28153),
(148261, 'esMX', 'Tenemo\' que pensar cómo matar a Zulajin.', '', 28153),
(148260, 'esMX', '¡La infección ha desaparecido! Y todo... gracia\' a ti y a $n.', '', 28153),
(148259, 'esMX', 'Tiene\' razón. Debería estar muerto. Pero eso no significa que vaya a dejarte morir. Ahora, ¡quieto!', '', 28153),
(148258, 'esMX', '¡Agh! ¡Me estás matando! ¡Mereces mucho má\' que el exilio!', '', 28153),
(148257, 'esMX', 'El vudú que te ha infectado e\' muy fuerte... Quédate quieto, ¡ya casi termino!', '', 28153),
(148256, 'esMX', 'Quieto, Zaluto. Te curaremos la infección.', 'Quieto, Zaluto. Te curaremos la infección.', 28153),
(148255, 'esMX', 'Su \"profeta\" era un farsante.', '', 28153),
(148254, 'esMX', 'Dicen que Rastakhan no tiene poder aquí. Muéstrale\' que esh\'tán equivocado\'. Libera a Tal\'gurub de su herejía.', '', 28153),
(148253, 'esMX', '', 'Gracia\' por tu ayuda para recuperar estos artefactos.', 28153),
(148252, 'esMX', '', 'El mar devoró Atal\'Gral, pero no todo esta perdido. Debemo\' recuperar lo que podamo\' del templo del loa.', 28153),
(148251, 'esMX', '¡Que la naturaleza te bendiga, $Uamigo:amiga;! ¡Buena suerte!', '¡Que la naturaleza te bendiga, $Uamigo:amiga;! ¡Buena suerte!', 28153),
(148250, 'esMX', '¡Gracias por liberarme!', '¡Gracias por liberarme!', 28153),
(148249, 'esMX', 'Al menos... morí luchando...', 'Al menos... morí luchando...', 28153),
(148248, 'esMX', 'Ah... derrotado al fin...', 'Ah... derrotada al fin...', 28153),
(148247, 'esMX', 'Así que.... esto es lo que se siente...', 'Así que.... esto es lo que se siente...', 28153),
(148246, 'esMX', 'Sepúltenme... junto a mi ron...', 'Sepúltenme... junto a mi ron...', 28153),
(148245, 'esMX', '¡Te atravesaré!', '¡Te atravesaré!', 28153),
(148244, 'esMX', 'El océano será tu tumba.', 'El océano será tu tumba.', 28153),
(148243, 'esMX', '¡Muéstrame tu acero!', '¡Muéstrame tu acero!', 28153),
(148242, 'esMX', 'A quien lea esto: ¡no confíe en la magia de la hermandad!\n\nNo sé de dónde salieron, pero el círculo creció en secreto en los lugares oscuros de Corlain. ¡Ahora han tomado las calles, mataron a todos los que se interponían en su camino y persiguieron a los demás con sus abominaciones de mimbre!\n\nNadie sabe lo que quieren. Solo hablan de vengar a su maestro y llevar la gloria a su pérfida líder, \"La Madre\".\n\nNo creo que llegue a Corlain con vida. Mi única esperanza es que estas palabras lleguen a alguien que pueda hacer algo. ¡No dejes entrar a estas \"hermanas\" a tu pueblo! Su corrupción los consumirá desde adentro, ¡como consumió a Corlain!', 'A quien lea esto: ¡no confíe en la magia de la hermandad!\n\nNo sé de dónde salieron, pero el círculo creció en secreto en los lugares oscuros de Corlain. ¡Ahora han tomado las calles, mataron a todos los que se interponían en su camino y persiguieron a los demás con sus abominaciones de mimbre!\n\nNadie sabe lo que quieren. Solo hablan de vengar a su maestro y llevar la gloria a su pérfida líder, \"La Madre\".\n\nNo creo que llegue a Corlain con vida. Mi única esperanza es que estas palabras lleguen a alguien que pueda hacer algo. ¡No dejes entrar a estas \"hermanas\" a tu pueblo! Su corrupción los consumirá desde adentro, ¡como consumió a Corlain!', 28153),
(148241, 'esMX', 'Esta semana hubo una tercera desaparición. Los guardias insisten en que no hay nada de qué preocuparse, pero yo no soy tonta.\n\nJusto anoche hablé con el señor Sabelotón: él vio el cuerpo de Jon, el mozo de cuadra, que fue el primero en desaparecer. Me dijo que la imagen quedó marcada a fuego en su mente: había señales profanas en la pared de la choza de su sirviente, cuyo cuerpo yacía sobre su carreta, con un agujero en el pecho, en el lugar donde debía estar su corazón.\n\nAhora Sabelotón ha desaparecido, y los guardias no dicen palabra alguna.\n\nSiento que Corlain ya no es un lugar seguro para mí y para mi familia. En cuanto podamos, nos iremos a Alto de Arom.', 'Esta semana hubo una tercera desaparición. Los guardias insisten en que no hay nada de qué preocuparse, pero yo no soy tonta.\n\nJusto anoche hablé con el señor Sabelotón: él vio el cuerpo de Jon, el mozo de cuadra, que fue el primero en desaparecer. Me dijo que la imagen quedó marcada a fuego en su mente: había señales profanas en la pared de la choza de su sirviente, cuyo cuerpo yacía sobre su carreta, con un agujero en el pecho, en el lugar donde debía estar su corazón.\n\nAhora Sabelotón ha desaparecido, y los guardias no dicen palabra alguna.\n\nSiento que Corlain ya no es un lugar seguro para mí y para mi familia. En cuanto podamos, nos iremos a Alto de Arom.', 28153),
(148240, 'esMX', 'Ceridwen sigue tratando de convencerme de que me una a su \"círculo de hermanas\".\n\nA mí no me gusta. Cada día que pasa veo más y más chicas del pueblo llevando el talismán de mimbre. A este ritmo, todo el pueblo se habrá unido antes de que me dé cuenta.\n\nY los hombres no parecen advertirlo... ignoran lo que ocurre, más que de costumbre. Parece que estuvieran bajo algún tipo de hechizo.', 'Ceridwen sigue tratando de convencerme de que me una a su \"círculo de hermanas\".\n\nA mí no me gusta. Cada día que pasa veo más y más chicas del pueblo llevando el talismán de mimbre. A este ritmo, todo el pueblo se habrá unido antes de que me dé cuenta.\n\nY los hombres no parecen advertirlo... ignoran lo que ocurre, más que de costumbre. Parece que estuvieran bajo algún tipo de hechizo.', 28153),
(148239, 'esMX', 'Por fin hay una luz de esperanza para Drustvar. Lady Tarjasenda salió hoy de la mansión para calmar los temores que la ausencia de Lord Tarjasenda despertó en los habitantes del pueblo.\n\nNos aseguró que el señor goza de buena salud, pero el modo en que daba órdenes a los guardias era bastante peculiar. Nunca había ejercido semejante autoridad.\n\nSeguro estoy sobreinterpretando. Después de las dificultades de las últimas semanas, todas las bendiciones son bienvenidas.', 'Por fin hay una luz de esperanza para Drustvar. Lady Tarjasenda salió hoy de la mansión para calmar los temores que la ausencia de Lord Tarjasenda despertó en los habitantes del pueblo.\n\nNos aseguró que el señor goza de buena salud, pero el modo en que daba órdenes a los guardias era bastante peculiar. Nunca había ejercido semejante autoridad.\n\nSeguro estoy sobreinterpretando. Después de las dificultades de las últimas semanas, todas las bendiciones son bienvenidas.', 28153),
(148238, 'esMX', 'Esta es la tercera noche que nuestra Maggie escapa pensando que su padre y yo dormíamos. Traté se seguirla, pero le perdí el rastro en el patio hacia Mansión Tarjasenda.\n\nLos Davey dijeron que su hija también desapareció algunas noches, tras las cuales apareció de modo tan misterioso como desapareció, como si no hubiera pasado nada.\n\nSu padre jura que la vio entrar a la mansión, pero eso es ridículo. ¡Nadie ha entrado ni salido de la mansión en semanas!', 'Esta es la tercera noche que nuestra Maggie escapa pensando que su padre y yo dormíamos. Intenté seguirla, pero le perdí el rastro en el patio hacia la Mansión Tarjasenda.\n\nLos Davey dijeron que su hija también desapareció algunas noches, tras las cuales apareció de modo tan misterioso como desapareció, como si no hubiera pasado nada.\n\nSu padre jura que la vio entrar a la mansión, pero eso es ridículo. ¡Nadie ha entrado ni salido de la mansión en semanas!', 28153),
(148236, 'esMX', 'No podemos sobrevivir sin la ayuda del loa.', '', 28153),
(148235, 'esMX', '¡Levántate y pelea!', '¡Levántate y pelea!', 28153),
(148234, 'esMX', 'Han pasado dos semanas desde la última vez que alguien vio a Lord y Lady Tarjasenda u oyó algo sobre ellos. Los guardias de las puertas echan a quienes se acercan a preguntar sin revelar nada sobre su estado.\n\nSe corre el rumor de que el señor sufre una enfermedad desgastante y que la señora está tan afligida por la pena que se ha encerrado junto a él en su recámara.\n\nEstos son días verdaderamente oscuros para Drustvar.', 'Han pasado dos semanas desde la última vez que alguien vio a Lord y Lady Tarjasenda u oyó algo sobre ellos. Los guardias de las puertas echan a quienes se acercan a preguntar sin revelar nada sobre su estado.\n\nSe corre el rumor de que el señor sufre una enfermedad desgastante y que la señora está tan afligida por la pena que se ha encerrado junto a él en su recámara.\n\nEstos son días verdaderamente oscuros para Drustvar.', 28153),
(148233, 'esMX', '¡Te sacaré las tripas!', '¡Te sacaré las tripas!', 28153),
(148232, 'esMX', 'Pagarás por esto...', 'Pagarás por esto...', 28153),
(148231, 'esMX', 'Aspafresno... prevalecerá...', 'Aspafresno... prevalecerá...', 28153),
(148230, 'esMX', 'Maldita sea...', 'Maldita sea...', 28153),
(148229, 'esMX', 'Ratas...', 'Maldición...', 28153),
(148228, 'esMX', '¡Así hacemos negocios en Boralus!', '¡Así hacemos negocios en Boralus!', 28153),
(148227, 'esMX', '¡Esta ciudad le pertenece a Aspafresno!', '¡Esta ciudad le pertenece a Aspafresno!', 28153),
(148226, 'esMX', 'Nunca debiste venir aquí.', 'Nunca debiste venir aquí.', 28153),
(148225, 'esMX', 'Este será tu último error.', 'Este será tu último error.', 28153),
(148224, 'esMX', 'Lugar equivocado, momento equivocado.', 'Lugar equivocado, momento equivocado.', 28153),
(148223, 'esMX', '¡El castigo por entrar aquí es la muerte!', '¡El castigo por entrar aquí es la muerte!', 28153),
(148222, 'esMX', 'Jefe, ¡los árboles han venido a buscar venganza! ¡Nos atacan de todos lados!', '', 28153),
(148221, 'esMX', 'No debiste entrometerte, $uforastero:forastera;.', 'No debiste entrometerte, $uforastero:forastera;.', 28153),
(148220, 'esMX', '¡Este no es tu lugar!', '¡Este no es tu lugar!', 28153),
(148219, 'esMX', '¡Tu ejército está derrotado! ¡Es solo cuestión de tiempo para que nuestras torres de asedio derriben tus murallas! ¡Ríndete ahora, y ponle fin a esta masacre!', '', 28153),
(148218, 'esMX', '¡Mis máquinas están a tu servicio!', '', 28153),
(148217, 'esMX', '', 'Como ordenes. ¡Campeones, síganme!', 28153),
(148216, 'esMX', 'Jaina, Genn, ayúdenme con Clamañublo y Lor\'themar.', '', 28153),
(148215, 'esMX', '¡Por supuesto! Traje unas máquinas adicionales como respaldo. ¡Pruébenlas!', '', 28153),
(148214, 'esMX', '', 'Soy famosa por mi puntualidad, majestad. Mekkatorque, ¿estás listo para pelear?', 28153),
(148213, 'esMX', '¡Alleria! ¡Gracias a la Luz que llegaste!', '', 28153),
(148212, 'esMX', '', '¡G\'huun eh\'tá en todos lados!', 28153),
(148211, 'esMX', '', '¡Púdrete!', 28153),
(148209, 'esMX', '', '¡No! ¡No deben escapar!', 28153),
(148208, 'esMX', '¡RETIRADA!', '', 28153),
(148207, 'esMX', '', '¡DESTRÚYANLOS!', 28153),
(148206, 'esMX', '¿Ahora les tienen miedo a unas arañitas? ¡Aplástenlas con las botas!', '', 28153),
(148205, 'esMX', '¡Ahora las arañas nos atacan en el bosque! ¡No podemos talar árboles mientras nos asesinan, jefe!', '', 28153),
(148204, 'esMX', 'Parece que tendremos que encargarnos nosotros, $n. Veamos qué tan grave es realmente este problema de las arañas.', '', 28153),
(148203, 'esMX', 'Los nagas nos han exiliado en nuestra propia tierra.', '', 28153),
(148202, 'esMX', '', '¡Basta de tonterías! ¡Las torres, las torres!', 28153),
(148201, 'esMX', '', '¡No me cuestiones, Colmillosauro! Debemos desviar su atención de mi máquina de guerra para poder destruir sus torres. Las bajas son inevitables.', 28153),
(148200, 'esMX', '¡Estás enviando a nuestras tropas a la muerte! Necesitamos soldados en el campo de batalla para reforzar...', '', 28153),
(148199, 'esMX', '', 'Olvida el ejército. Más tarde nos encargaremos de ellos. ¡Derriben las torres de asedio!', 28153),
(148197, 'esMX', 'Llévame lo más cerca que puedas de Nazmir.', 'Llévame lo más cerca que puedas de Nazmir.', 28153),
(148196, 'esMX', '', '¿A dónde vas?', 28153),
(148195, 'esMX', '¡No teman sus viles creaciones, se pueden destruir! ¡Genn, sígueme!', '', 28153),
(148194, 'esMX', 'Jamás había visto algo así.. ', '', 28153),
(148193, 'esMX', '', 'No sabes a qué te enfrentas, niño rey. ¡Esto es solo el comienzo!', 28153),
(148192, 'esMX', '¡Se acabó, Sylvanas! Los muros de Lordaeron pronto se desplomarán a tu alrededor.', '', 28153),
(148190, 'esMX', '¡No me convertiré en alimento de los bebé\' de pterrordáctilo!', '¡No me convertiré en alimento de los bebé\' de pterrordáctilo!', 28153),
(148189, 'esMX', 'Rokhan me dará una golpiza cuando sepa que me atrapó la fauna.', 'Rokhan me dará una golpiza cuando sepa que me atrapó la fauna.', 28153),
(148188, 'esMX', 'Iré a ver a los trabajadores que están en el bosque. ¡Si estamos en peligro aquí, temo por su seguridad allá!', '', 28153),
(148187, 'esMX', 'Ten cuidado, colega. Pensé que era cuidadoso, pero otra bestia se me abalanzó por el coh\'tado. Muy astuta.', 'Ten cuidado, colega. Pensé que era cuidadosa, pero otra bestia se me abalanzó por el coh\'tado. Muy astuta.', 28153),
(148186, 'esMX', '¿Y qué piensa\' hacer? ¿Desterrarme a Vol\'dun otra vez? ¡Quédate quieto!', '', 28153),
(148185, 'esMX', '¡Déjame morir, criminal! Ahora tu deh\'tino está en Vol\'dun. Así lo dicta la ley, y la estás violando al quedarte aquí.', '', 28153),
(148184, 'esMX', 'Ahh, eso sí que dolió.', 'Ahh, eso sí que dolió.', 28153),
(148183, 'esMX', 'Graciah\', colega. ¡Pero tú y yo deberíamos marcharnos de aquí!', 'Graciah\', colega. ¡Pero tú y yo deberíamos marcharnos de aquí!', 28153),
(148182, 'esMX', 'Quieto, Zaluto. Curaremo\' esta infección y te dejaremo\' como nuevo.', '', 28153),
(148181, 'esMX', 'Deja de moverte. Curaremo\' esta infección y te recuperarás pronto.', '', 28153),
(148180, 'esMX', '', '¡Cae ante el poder de G\'huun!', 28153),
(148179, 'esMX', '', 'G\'huun, acepta eh\'ta ofrenda de carne y hueso\'.', 28153),
(148178, 'esMX', 'Ve, criminal... Te han exiliado a Vol\'dun. Si te quedas aquí, ¡eh\'tarás violando la ley zandalari!', '', 28153),
(148177, 'esMX', '', '¡Alabado sea G\'huun!', 28153),
(148176, 'esMX', '', '¡Mi poder crece!', 28153),
(148175, 'esMX', '', 'Mi sangre para G\'huun...', 28153),
(148174, 'esMX', '', '¡Hora del sacrificio!', 28153),
(148173, 'esMX', '', '¡Por la gloria de G\'huun!', 28153),
(148172, 'esMX', 'Necesito un dardo.', 'Necesito un dardo.', 28153),
(148171, 'esMX', '', 'Las beh\'tias de La Reserva están activa\' hoy.', 28153),
(148170, 'esMX', '', 'Pasará un tiempo hasta que se reagrupen. Muchas gracia\'.', 28153),
(148169, 'esMX', '', 'Los discípulo\' de Zul y los mogu eh\'tán reuniendo fuerzas en el Templo del Profeta. Ya sabes qué hacer.', 28153),
(148168, 'esMX', '¡No los dejaré pasar!', '', 28153),
(148167, 'esMX', 'Tampoco tenemos noticias de Alleria todavía. Iba a buscar refuerzos a Gnomeregan.', '', 28153),
(148166, 'esMX', '', 'Bien hecho. Con eso las bestia\' se mantendrán saludable\' por un tiempo.', 28153),
(148165, 'esMX', '', 'Un veneno extraño ha enfermado a las bestia\' de la Reserva. Ten, aplícales esto. Pero cuidado, alguna\' ya no tienen salvación y podrían atacarte.', 28153),
(148164, 'esMX', '', '¡Y quema esta nota después de leerla, imbécil!', 28153),
(148163, 'esMX', '', 'No toleren la insolencia de la chusma bañada en hollín. Enséñenles una lección si es necesario. Lo único que importa es abastecer a nuestros clientes a tiempo.', 28153),
(148162, 'esMX', '', 'Los químicos están produciendo una pólvora excelente. Deben abastecerlos SIN FALTA con azerita refinada o encontraré otros que lo hagan.', 28153),
(148161, 'esMX', '', 'No me interesa cómo, ¡quiero ver esas forjas trabajando día y noche!', 28153),
(148160, 'esMX', '', 'Les solicito amablemente que dirijan sus consultas al señor Farthing o al señor Williams.', 28153),
(148159, 'esMX', '', 'Respecto de la creciente presencia de compañía en el lugar: no se preocupe, todo es por su seguridad.', 28153),
(148158, 'esMX', '', 'A partir de este momento, todas las jornadas durarán el doble. Nos pesa pedirles esto, ¡pero sus esfuerzos garantizan la seguridad de Kul Tiras en estos tiempos de incertidumbre!', 28153),
(148157, 'esMX', '¡Témele a mi poder!', '¡Témele a mi poder!', 28153),
(148156, 'esMX', 'A vece\' siento que todo el pantano intenta echarnos. ¡Qué bueno que eh\'tés a la altura del desafío!', '', 28153),
(148155, 'esMX', 'Tengo un mal presentimiento... Nueh\'tros exploradore\' ya deberían haber vuelto. Averigua dónde están.', '', 28153),
(148154, 'esMX', '', 'No solo eso... ¡Lo usaremos para destruirlos! ¡Vamos! ¡Todos a bordo!', 28153),
(148153, 'esMX', '¡Sacaremos a ese monstruo de aquí! ¡Jajaja!', '', 28153),
(148152, 'esMX', 'He fabricado un talismán de control superior a partir de los otros que adquirimos. ¡Úsalo contra el demoledor!', '', 28153),
(148151, 'esMX', '', '¡Eso les enseñará a no abandonar Nazmir! Agradeh\'co que puedo contar contigo, adalid.', 28153),
(148150, 'esMX', '', '¡Los trols de sangre han atravesado el Riodazal! ¡Adalid! Mata a su vanguardia y quema todos los cuerpo\' que puedan resucitar.', 28153),
(148147, 'esMX', '¡Basta ya!', '', 28153),
(148146, 'esMX', 'Estoy harto de estas excusas. ¡Los árboles no cobran vida! ¡Vuelvan a trabajar!', '', 28153),
(148145, 'esMX', 'Debo regresar a la arena. Ten cuidado. Jakra\'zet ofrece una gran recompensa por tu cabeza.', 'Debo regresar a la arena. Ten cuidado. Jakra\'zet ofrece una gran recompensa por tu cabeza.', 28153),
(148144, 'esMX', 'El templo está en ruinas, pero quizás estemos a salvo ahí si el loa nos acepta...', '', 28153),
(148143, 'esMX', 'No estaremos a salvo aquí por mucho tiempo más.', '', 28153),
(148142, 'esMX', 'Jamás había oído hablar del Anillo de las mareas, pero debe ser un artefacto muy poderoso si Azshara ha enviado un ejército para recuperarlo.', '', 28153),
(148141, 'esMX', 'Se recuperan en número rápidamente. Bah... siempre fue así. Seguramente volvamo\' a enfrentarlas.', '', 28153),
(148140, 'esMX', 'Eh\'tas víboras emplumadas son conocidas por sus infeh\'taciones excesivas, ¡pero eh\'to es demasiado! Destruye sus huevo\' para controlar la población.', '', 28153),
(148139, 'esMX', '', '', 28153),
(148138, 'esMX', '¡Korthek el Valiente! \n\nEn los campamentos de jóvenes guerreros cuentan historias sobre su fuerza y su agilidad estratégica. Cuando todo parece perdido, las historias de Korthek reavivan la llama de los guerreros.\n\n¡Es capaz de cambiar el rumbo de la batalla por su cuenta! ¡Lucha por su pueblo con pasión y ferocidad!\n\nEs un hermano muy querido.\n\nGracias a él, ninguna raza se comparará con los sethrak. Somos los mejores. Somos los más sabios. Somos los más poderosos.\n\nCon él de nuestro lado, ¡ningún forastero será capaz de dañar a nuestra poderosa nación!', '', 28153),
(148137, 'esMX', 'Imparcial, justo, fiel, firme... Esas son las palabras que resuenan con el nombre de Vorrik.\n\nSu lealtad hacia Sethraliss es profunda e inquebrantable. Su sabiduría y su claridad para ver las cosas son incuestionables. \n\nNada distrae a Vorrik de su deber como Guardián. \n\nCon la ayuda de sus honorables hermanos, mantendrá los ojos en el horizonte. \n\nNingún enemigo logrará jamás acercarse lo suficiente como para despertar a nuestro gigante aletargado.', '', 28153),
(148136, 'esMX', 'Sulthis es quien tiene la conexión más estrecha con Sethraliss. El amor que profesa por su loa, y por el desierto, lo inspiraron a adoptar a la cobra como su guía espiritual. \n\nCon frecuencia se lo considera el primer Guardián. Si bien su poder era inmenso, sabía que no bastaría para sellar la tumba por su cuenta. Buscó a otros con los que compartir esa responsabilidad. Vorrik y Korthek aceptaron, y así se formaron los Guardianes.\n\nLos sethrak viajan desde todas partes para dejar muestras de afecto en las estatuas de los Guardianes. Estas muestras encarnan todo lo que representa Sulthis.\n\nNo podemos darles a los C\'Thraxxi otra oportunidad de destruir todo lo que amamos.', '', 28153),
(148133, 'esMX', '', '¡Ahí! ¡Una puerta en el árbol!', 28153),
(148132, 'esMX', '¿Nadie piensa mencionar al gólem de mimbre gigante? Porque creo que es importante.', '', 28153),
(148131, 'esMX', '¡Una crisis a la vez, mmmuchacho!', '', 28153),
(148130, 'esMX', 'Azeroth está un poco más segura gracias a ti.', '', 28153),
(148129, 'esMX', 'Cuidado. Hay algo poderoso por aquí, ¡y está potenciado con azerita!', '', 28153),
(148128, 'esMX', 'Buen trabajo, colega. ¡Bien hecho!', '', 28153),
(148127, 'esMX', 'Parece que hay un tortollano por ahí. Ve a ver si necesita ayuda.', '', 28153),
(148126, 'esMX', '¡Ja, esa fue una buena pelea! Ya tengo una buena anécdota para contarles a los demás.', '', 28153),
(148125, 'esMX', 'De acuerdo, Lucille. Muéstrales de qué estás hecha.', '', 28153),
(148124, 'esMX', 'Espero que lo hagas interesante. ¡No quiero otra pelea aburrida!', '', 28153),
(148123, 'esMX', 'Lucharé contra la criatura que invocaste.', 'Lucharé contra la criatura que invocaste.', 28153),
(148122, 'esMX', '¡Oye, tú! Eres $Gun:una; $c, ¿verdad? Quizás puedas ayudarme, estoy en busca de una historia interesante.\n\nUn amigo me acaba de entregar este pergamino, se supone que invoca a un ser poderoso.\n\n¿Estás dispuesto a luchar con él? Quiero ver a esta cosa en acción.', '', 28153),
(148121, 'esMX', '', 'Esta será una historia fantástica para contarles a los demás. Ten, acepta esto por tu esfuerzo. Sigue así.', 28153),
(148120, 'esMX', '', '¿Mmm? Algo extraño ocurre aquí cerca. Hazme el favor y ve a echar un vistazo. Quizás encuentres algo interesante.', 28153),
(148119, 'esMX', 'Un problema menos por el que preocuparnos.', '', 28153),
(148118, 'esMX', 'Hay una monstruosidad poderosa cerca, ¡potenciada por la propia sangre de Azeroth! Debes destruirla antes de que cause un desastre.', '', 28153),
(148117, 'esMX', 'Torka me pidió que te entregara esto.', 'Torka me pidió que te entregara esto.', 28153),
(148116, 'esMX', '¡Lo lograste! ¡Rápido, por aquí!', '', 28153),
(148115, 'esMX', 'He vivido muchos años y he visto muchas cosas. La tribu Tortaka existe desde mucho antes de que yo naciera y continuará existiendo aun mucho después de que abandone este mundo.', '', 28153),
(148114, 'esMX', 'Mmm... Esa mano sí que habla mucho a pesar de no tener boca. Los espíritu\' son realmente misterioso\'.', '', 28153),
(148113, 'esMX', 'Toma el nuevo Pergamino de la Mano del destino.', 'Toma el nuevo Pergamino de la Mano del destino.', 28153),
(148112, 'esMX', 'El Pergamino de la Mano del destino e\' misterioso, pero útil. Los no-muerto\' vuelven a reunirse en la costa. Ve y pon a prueba el poder del pergamino.', '', 28153),
(148111, 'esMX', 'Mamá quiere que vuelva pronto a casa.', '', 28153),
(148110, 'esMX', '¡Hay mucho\' monstruo\' por allí!', '', 28153),
(148109, 'esMX', 'Vete de una vez. ¡Necesito carne!', '', 28153),
(148107, 'esMX', '|cffffff00ID de objeto $1i|r', '|cffffff00ID de objeto $1i|r', 28153),
(148106, 'esMX', 'Vamos.', 'Vamos.', 28153),
(148104, 'esMX', 'Necesito un silbato para convocar a los defensores rastari.', 'Necesito un silbato para convocar a los defensores rastari.', 28153),
(148103, 'esMX', 'Los rastari reconocerán el sonido del silbato.', '', 28153),
(148102, 'esMX', 'Vorrik, si recibes este mensaje, temo que he llegado demasiado tarde. Korthek ha traicionado a nuestro pueblo y planea romper la barrera que pusimos en la tumba hace tanto tiempo.', '', 28153),
(148101, 'esMX', 'Sus huesos pavimentarán los caminos de nuestro imperio.', '', 28153),
(148100, 'esMX', 'Te faltó fuerza.', '', 28153),
(148099, 'esMX', '|cffffff00ID de nodo $1i|r', '|cffffff00ID de nodo $1i|r', 28153),
(148098, 'esMX', 'Todo lo que ves tiene un precio.', 'Todo lo que ves tiene un precio.', 28153),
(148097, 'esMX', '¿Visitando a mih\' competidores? Ya regresarás.', '¿Visitando a mis competidore\'? Ya regresarás.', 28153),
(148096, 'esMX', 'No te vayas con las manoh\' vacías.', 'No te vaya\' con las manos vacías.', 28153),
(148095, 'esMX', 'Me especializo en importacioneh\' de calidad.', 'Me especializo en importaciones de calidá\'.', 28153),
(148094, 'esMX', '|TInterface\\Icons\\SPELL_NATURE_LIGHTNINGOVERLOAD.BLP:20|t¡Aspix te afecta con |cFFFF0000|Hspell:263371|h[Conducción]|h|r!', '|TInterface\\Icons\\SPELL_NATURE_LIGHTNINGOVERLOAD.BLP:20|t¡Aspix te afecta con |cFFFF0000|Hspell:263371|h[Conducción]|h|r!', 28153),
(148093, 'esMX', '¡Trueno ensordecedor!', '', 28153),
(148092, 'esMX', '¡Acábalos, Culebris!', '', 28153),
(148091, 'esMX', '¡Ya regresarás por eh\'tos artículos!', '¡Ya regresarás por eh\'tos artículos!', 28153),
(148090, 'esMX', 'Vamos, seguro puedeh\' comprar alguna baratija más.', 'Vamos, seguro puedeh\' comprar alguna baratija más.', 28153),
(148089, 'esMX', 'Oye, regresa con máh\' de esah\' monedas, ¿sí?', 'Regresa con máh\' de esah\' monedas.', 28153),
(148088, 'esMX', 'Envíame a Granovel.', 'Envíame a Granovel.', 28153),
(148087, 'esMX', 'Envíame al Círculo de Elementos.', 'Envíame al Círculo de Elementos.', 28153),
(148086, 'esMX', 'Informaré a Vorrik sobre mis inquietudes, pero antes debo poner a salvo mi llave. Tengo el presentimiento de que pronto sucederá algo terrible...', '', 28153),
(148085, 'esMX', 'Se oyen voces en el interior del templo. Korthek está ansioso por atacar a los trols. Son una raza formidable que no caerá fácilmente. Hemos vivido en paz durante mucho tiempo... ¿Por qué ahora quiere iniciar una lucha que no puede ganar?', '', 28153),
(148084, 'esMX', 'Con Vorrik y Korthek sellamos la tumba con la esperanza de que nadie jamás despertara al gigante enterrado en su interior. No nos condenaremos a repetir los errores que cometieron nuestros vecinos hace tanto tiempo.', '', 28153),
(148083, 'esMX', 'La ciudad ha caído. No quedó nada tras la batalla entre Sethraliss y Mythrax. Nuestra loa dio su vida para mantenernos a salvo y no dejaremos que su sacrificio sea en vano.', '', 28153),
(148082, 'esMX', '|TInterface\\Icons\\Ability_Socererking_arcanewrath.blp:20|t¡Culebris comienza su |cFFFF0000|Hspell:263389|h[Carrerilla en arco]|h|r!', '|TInterface\\Icons\\Ability_Socererking_arcanewrath.blp:20|t¡Culebris comienza su |cFFFF0000|Hspell:263389|h[Carrerilla en arco]|h|r!', 28153),
(148081, 'esMX', 'Qué será... del imperio...', '', 28153),
(148080, 'esMX', 'Las arenas... me llevan...', '', 28153),
(148079, 'esMX', '¡Por el imperio!', '', 28153),
(148078, 'esMX', '¡Mi poder los quebrará!', '', 28153),
(148077, 'esMX', 'Necesito un tótem para romper el hechizo que aflige a los esclavos mentales.', 'Necesito un tótem para romper el hechizo que aflige a los esclavos mentales.', 28153),
(148076, 'esMX', '', 'Necesitarás eh\'to.', 28153),
(148075, 'esMX', 'Tu aldea corre peligro.', 'Tu aldea corre peligro.', 28153),
(148074, 'esMX', 'Eso les enseñará a no atacar aldeano\' deh\'de las sombras. Bien hecho.', '', 28153),
(148073, 'esMX', 'Los aldeanos de Zeb\'ahari aún viven amenazado\' por los asesinos de Zul. Sálvalos y asesina a todos los que atacan inocentes deh\'de las sombra\'.', '', 28153),
(148072, 'esMX', 'Mejoraste.', 'Mejoraste.', 28153),
(148071, 'esMX', '¡Ja! Siempre puedo contar contigo para estas tarea\'.', '', 28153),
(148070, 'esMX', 'El olor de la sangre se siente en el aire. Haz tu gracia y siembra el caos en Zal\'amak.', '', 28153),
(148069, 'esMX', '¡Detente! Solo quiero que mi familia esté a salvo.', '¡Detente! Solo quiero que mi familia esté a salvo.', 28153),
(148068, 'esMX', '¡Fuera de nuestro valle!', '¡Fuera de nuestro valle!', 28153),
(148067, 'esMX', '¡Me niego a recibir órdenes de alguien como tú!', '¡Me niego a recibir órdenes de alguien como tú!', 28153),
(148066, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"Eres $Gdigno:digna;.\n\nRecibe la bendición de Eraka no Kimbul. El loa de los tigres te aguarda\".', '', 28153),
(148065, 'esMX', '', 'Somos los prelado\' de Rezan, nunca hubo una orden de guerrero\' más alta al servicio de un loa.\n\nSeguimo\' la senda de la élite. Adoptamos solo a aquello\' que nacen con el don de la destreza en batalla y la bendición de los loa, y forjamos campeone\' de la luz para que defiendan a nuestro imperio.\n\nY no, no tenemos posicione\' vacantes ni folletos informativo\'.', 28153),
(148064, 'esMX', '<El teniente Akaro mira el filo de su espada y te dedica una sonrisa de superioridad.>', '', 28153),
(148063, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"No eres $Gdigno:digna;.\n\nReflexiona sobre las palabras del gran loa, Eraka no Kimbul, y regresa cuando estés $Glisto:lista;\".', '', 28153),
(148062, 'esMX', 'Buen día, señor.', '', 28153),
(148061, 'esMX', 'Te sigo. Recuerda: la clave para evitar problemas en lugares desconocidos es entrar como si fueras el dueño.', '', 28153),
(148060, 'esMX', 'Ven el futuro.', 'Ven el futuro.', 28153),
(148059, 'esMX', 'Ven el rostro de su enemigo.', 'Ven el rostro de su enemigo.', 28153),
(148058, 'esMX', 'Vamos.', 'Vamos.', 28153),
(148057, 'esMX', 'Ven las formas y los colores.', 'Ven las formas y los colores.', 28153),
(148056, 'esMX', 'Ven la verdad.', 'Ven la verdad.', 28153),
(148055, 'esMX', 'Ven que le pertenecen a la naturaleza.', 'Ven que le pertenecen a la naturaleza.', 28153),
(148054, 'esMX', 'Ven que el mundo gira a su alrededor.', 'Ven que el mundo gira a su alrededor.', 28153),
(148053, 'esMX', 'Una vida repleta de placer.', 'Una vida repleta de placer.', 28153),
(148052, 'esMX', 'Una vida de logros.', 'Una vida de logros.', 28153),
(148051, 'esMX', 'Una vida honorable.', 'Una vida honorable.', 28153),
(148050, 'esMX', 'Una vida en paz.', 'Una vida en paz.', 28153),
(148049, 'esMX', 'Una vida repleta de gloria.', 'Una vida repleta de gloria.', 28153),
(148048, 'esMX', 'Una vida de lujos.', 'Una vida de lujos.', 28153),
(148047, 'esMX', 'Dinero. Mucho dinero.', 'Dinero. Mucho dinero.', 28153),
(148046, 'esMX', 'Una mente aguda.', 'Una mente aguda.', 28153),
(148045, 'esMX', 'Una gran fortaleza.', 'Una gran fortaleza.', 28153),
(148044, 'esMX', 'Un rostro atractivo.', 'Un rostro atractivo.', 28153),
(148043, 'esMX', 'Seguidores fieles.', 'Seguidores fieles.', 28153),
(148042, 'esMX', 'Una voluntad irrefrenable.', 'Una voluntad irrefrenable.', 28153),
(148041, 'esMX', 'Siempre debes cuidarte el pellejo.', 'Siempre debes cuidarte el pellejo.', 28153),
(148040, 'esMX', 'Actúa con valentía frente a todo.', 'Actúa con valentía frente a todo.', 28153),
(148039, 'esMX', 'El orgullo es caída.', 'El orgullo es caída.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148038, 'esMX', 'Mira bien antes de saltar.', 'Mira bien antes de saltar.', 28153),
(148037, 'esMX', 'Solo los débiles sienten temor.', 'Solo los débiles sienten temor.', 28153),
(148036, 'esMX', 'Solo los fuertes sobreviven.', 'Solo los fuertes sobreviven.', 28153),
(148035, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"¿Qué ven los iluminados?\"', '', 28153),
(148034, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"¿Qué consideras una vida plena?\"', '', 28153),
(148033, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"¿Cuál es la fuente de poder?\"', '', 28153),
(148032, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"¿Cuál es la enseñanza del tigre cazador?\"', '', 28153),
(148031, 'esMX', '', 'Se acercan a las puerta\' de Atal\'Dazar. Rápido, tenemo\' que alcanzarlos.', 28153),
(148030, 'esMX', '¿$GListo:Lista; para subirte a ese barco y ver a dónde se dirige?', '', 28153),
(148029, 'esMX', '¿Qué? ¿Dónde?', '', 28153),
(148028, 'esMX', 'Intenta no llamar la atención.', '', 28153),
(148027, 'esMX', '', '¡Eh\'pera, Raal! ¡Te marchas sin Rezan y Rastakhan!', 28153),
(148026, 'esMX', 'No busco nada.', 'No busco nada.', 28153),
(148025, 'esMX', 'Busco gloria y prestigio sin igual.', 'Busco gloria y prestigio sin igual.', 28153),
(148024, 'esMX', 'Busco el conocimiento de reinos antiguos.', 'Busco el conocimiento de reinos antiguos.', 28153),
(148023, 'esMX', 'Busco la riqueza y la fortuna de los reyes.', 'Busco la riqueza y la fortuna de los reyes.', 28153),
(148022, 'esMX', 'Busco el poder para matar a mis enemigos.', 'Busco el poder para matar a mis enemigos.', 28153),
(148021, 'esMX', 'Si tienes algún asunto pendiente en el pueblo, ahora es el momento para resolverlo. Avísame cuando puedas abordar el barco y zapar hacia donde nos lleve el viento.', '', 28153),
(148020, 'esMX', 'Busco la bendición del loa.', 'Busco la bendición del loa.', 28153),
(148019, 'esMX', '<Una voz misteriosa resuena en tu mente.>\n\n\"¿Qué es lo que buscas?\"', '', 28153),
(148018, 'esMX', '', 'La marea... retrocede...', 28153),
(148017, 'esMX', '', 'Mi reina... He fallado...', 28153),
(148016, 'esMX', '', 'El abismo te tragará…', 28153),
(148015, 'esMX', '', 'Mi vida... por... Azshara...', 28153),
(148014, 'esMX', '¡Lo logramos! Volveré a Roz con el informe. ¡Has salvado la ciudad, $uhéroe:heroína;!', '', 28153),
(148013, 'esMX', 'No te preocupes por mí. Los tengo justo donde quería.', '', 28153),
(148012, 'esMX', 'Solo quiero desearte buena suerte. Todos contamos contigo.', '', 28153),
(148011, 'esMX', '¡Por aquí!', '', 28153),
(148009, 'esMX', 'Promesas, promesas.', '', 28153),
(148008, 'esMX', '', 'Te apuñalaré con tus propio\' colmillos.', 28153),
(148007, 'esMX', 'Loti, ¿por qué tardah\'te tanto?', '', 28153),
(148006, 'esMX', '¡Vaya! ¡Ahora tienes su atención! ¡Se acerca una horda enorme!', '', 28153),
(148005, 'esMX', 'Así no golpearás al monstruo, ¡apunta mejor!', '', 28153),
(148004, 'esMX', 'El resto de estos tipo\' es todo tuyo. Diviértete, y no olvide\' que aún estás en deuda conmigo. ¡Envíame sus alma\'!', '', 28153),
(148003, 'esMX', '¿Cree\' que te dejaré morir cuando aún tiene\' una deuda conmigo? ¡Jaja!', '', 28153),
(148002, 'esMX', '¡Eso retrasará a esos lagartos escamoso\' por un rato! Nuestros mago\' querrán echarle un vistazo a esta gema.', '', 28153),
(148001, 'esMX', 'Estos sethrak llevan gemas rebosante\' de poder. Destrózalo\' y consíguenos una gema.', '', 28153),
(148000, 'esMX', 'Ah, eso servirá. Espero que esas criaturitas tan resbaladizas no te hayan dado mucho trabajo.', '', 28153),
(147999, 'esMX', '¿Un enjambre de calapinosos? ¡Qué curioso que aparecieran justo cuando se me acabó la tinta! ¡Tengo justo lo que necesitamos! Ahora zambúllete y succiona esa preciada tinta.', '', 28153),
(147998, 'esMX', '', '¡Tenemos un GRAN problema!', 28153),
(147997, 'esMX', 'Eso les dará un respiro a los rastari. Los has hecho bien, adalid.', '', 28153),
(147996, 'esMX', 'Los rastari han eh\'tado intentando expulsar a los mogu del puerto de guerra sin éxito. Reúnelos y aplah\'ta a todos lo\' mogu que se interpongan.', '', 28153),
(147994, 'esMX', '¡No te acerques! ¡No queremos participar en esto!', '', 28153),
(147993, 'esMX', '¡SÍ! ¡BOLA CURVA!', '', 28153),
(147992, 'esMX', 'Camarada, nos veremos más adelante.', '', 28153),
(147991, 'esMX', 'Cagney, lleva a estos niños al ferry y regrésalos al pueblo. Taelia se encargará de que les asignen un refugio.', '', 28153),
(147990, 'esMX', '¡Bola curva! ¡Bola curva!', '', 28153),
(147989, 'esMX', 'Pao-me te entrega su informe.', '', 28153),
(147988, 'esMX', 'Eh\'ta bestia no es un problema, ¡solo tenemo\' que usar la vieja bola curva!', '', 28153),
(147987, 'esMX', 'Feng te entrega su informe.', '', 28153),
(147986, 'esMX', '¡Lucho una vez más!', '', 28153),
(147985, 'esMX', '¡No tienes mi permiso para morir! ¡Levántate!', '', 28153),
(147983, 'esMX', '', 'Tiene\'h la fuerza del propio Rezan.', 28153),
(147982, 'esMX', '', '¡Estos viles seguidore\' de Zul corrompen el Templo de Rezan! Enséñales a respetar a los loa.', 28153),
(147981, 'esMX', '¡Debemos detener a estos goblins! ¡Concéntrense en la trituradora!', '', 28153),
(147980, 'esMX', 'El humo... es tan denso...', '', 28153),
(147979, 'esMX', '', 'Mi pueblo merece cruzar al otro lado en paz. Te lo agradezco, adalid.', 28153),
(147978, 'esMX', '', 'Le debes almas a Bwonsamdi, y creo que e\' hora de cumplir con tu palabra. Libera las almas atrapada\' en esos horrore\' y guíalas hacia el tempo de Bwonsamdi.', 28153),
(147977, 'esMX', '', 'Vamo\', adalid. ¡Será mejor que te sujetes bien!', 28153),
(147975, 'esMX', 'Mejor encargarse de las amenaza\' ahora que lamentarlo deh\'pué\'.', '', 28153),
(147974, 'esMX', 'Los múrlocs invaden nueh\'tras coh\'tas. Si no los masacramos de inmediato, sus número\' nos superarán ampliamente.', '', 28153),
(147973, 'esMX', '', 'Que el desierto se lleve tu alma.', 28153),
(147972, 'esMX', '', 'Sé que estás ahí, $r. Siento tu aroma en la lengua.', 28153),
(147970, 'esMX', '', 'Primero, debemos reunir a mi\' fuerzas. ¡Ah! $n, ese gong debería bah\'tar.', 28153),
(147969, 'esMX', '', 'Caven. Busquen. Encuentren. ¡La última llave debe estar aquí!', 28153),
(147968, 'esMX', '', 'Esos malditos zandalari se acercan. ¡Tenemos que encontrarla antes que ellos!', 28153),
(147967, 'esMX', '', '¡Korthek nos recompensará si encontramos la llave primero!', 28153),
(147966, 'esMX', '', '¡Tenemos la llave, $c! ¡Los demás guardianes no cumplieron con su tarea! ¡Juro por Korthek que yo no fallaré!', 28153),
(147965, 'esMX', 'Chao te entrega su informe.', '', 28153),
(147964, 'esMX', '¿Qué información has obtenido?', '¿Qué información has obtenido?', 28153),
(147963, 'esMX', 'Shh. Hay oídos por todas partes. Son de piedra, pero igual pueden oírte.', 'Shh. Hay oídos por todas partes. Son de piedra, pero igual pueden oírte.', 28153),
(147962, 'esMX', '¡Lo siento! ¡No soy guerrero!', '¡Lo siento! ¡No soy guerrera!', 28153),
(147961, 'esMX', '¡Piedad! ¡Piedad, por favor!', '¡Piedad! ¡Piedad, por favor!', 28153),
(147960, 'esMX', '¡Me obligaron a hacerlo!', '¡Me obligaron a hacerlo!', 28153),
(147959, 'esMX', '¡Lo siento! ¡No me lastimes por favor!', '¡Lo siento! ¡No me lastimes por favor!', 28153),
(147958, 'esMX', 'Si tú lo dices...', 'Si tú lo dices...', 28153),
(147957, 'esMX', '¡¿Estás $gseguro:segura; de esto?!', '¡¿Estás $gseguro:segura; de esto?!', 28153),
(147956, 'esMX', '¡No estoy hecho para esto!', '¡No estoy hecha para esto!', 28153),
(147955, 'esMX', '¡No te quedes ahí! ¡Ayúdame!', '¡No te quedes ahí! ¡Ayúdame!', 28153),
(147954, 'esMX', '¡Ey, tú! ¡Ayúdame con este $gintruso:intrusa;!', '¡Ey, tú! ¡Ayúdame con este $gintruso:intrusa;!', 28153),
(147953, 'esMX', 'Esta información será invaluable en el enfrentamiento con la Horda. Bien hecho, adalid.', '', 28153),
(147952, 'esMX', 'Nuestros aliados del Shado-Pan se han infiltrado entre los mogu en el puerto de guerra trol. Averigua lo que saben, ¡y no dudes en eliminar a cualquier mogu que veas!', '', 28153),
(147951, 'esMX', 'Destrozando', 'Destrozando', 28153),
(147950, 'esMX', '', 'Creo que te dejaré el misterio a ti... ¡Y mientras iré a destrozar más cráneos del aquelarre!', 28153),
(147949, 'esMX', '', 'Ahora que los gorila\' están controlado\', podemo\' relajarnos un poco. Hasta el próximo desastre inevitable.', 28153),
(147948, 'esMX', '', '¡Estos gorilas aspiraron kaja\'mita otra vez! Encárgate de ponerlos en su lugar ante\' de que causen estragos en Zuldazar.', 28153),
(147947, 'esMX', 'Los sethrak me persiguen hace días. Estas dunas son la muerte.\n\nCreí que habías muerto cuando chocamos... ¿Alguien más sobrevivió?', '', 28153),
(147946, 'esMX', 'Ah, sí... Los manuales de usuario son para ineptos. Salamandra, ¡hora de improvisar!', '', 28153),
(147945, 'esMX', '', 'Eh, jefe, definitivamente faltan algunos tornillos en lugares que según el manual necesitan tornillos.', 28153),
(147944, 'esMX', 'Entendido, princesa. ¡Está a punto de presenciar lo mejor y lo más nuevo de la tecnología goblin en primera fila!', '', 28153),
(147943, 'esMX', '¡¿MÁS?! ¡Que vengan!', '', 28153),
(147942, 'esMX', 'Cielos. Nunca antes hice explotar a un dios antiguo. ¡Quizá debería haber traído más explosivos!', '', 28153),
(147941, 'esMX', '', '¿Cuántos más de estos matones tengo que hacer volar para que entiendan el mensaje?', 28153),
(147940, 'esMX', 'Princesa, no soy un experto, pero creo que están teniendo un problemita con los trols de sangre.', '', 28153),
(147939, 'esMX', '', 'Em, jefe, creo que el término correcto es \"Renegados\".', 28153),
(147938, 'esMX', '¡TRABAJAMOS con no-muertos todo el tiempo, imbécil!', '', 28153),
(147937, 'esMX', '¡Ey, ey, EY! ¡Nadie dijo que tendríamos que lidiar con no-muertos!', '', 28153),
(147936, 'esMX', '', '¿Julwaba, eh\'tás herida?', 28153),
(147935, 'esMX', '¡Ese es el estilo de los goblins de Kezan!', '', 28153),
(147934, 'esMX', 'Despierten, ¡hora de MORIR!', '', 28153),
(147933, 'esMX', '', '¡Aw! ¡Explotan tan rápido que no llego a disfrutarlo! Bueno, en realidad sí lo disfruto un poco.', 28153),
(147932, 'esMX', '¡El desayuno está servido!', '', 28153),
(147931, 'esMX', '¿Dónde está su dios de la sangre ahora, eh? ¡Ja, idiotas!', '', 28153),
(147930, 'esMX', '¡Apuesto a que podríamos hacer explotar un sinfín de gnomos con esta preciosura!', '', 28153),
(147929, 'esMX', '', '¡Y el malo vuela por los aires!', 28153),
(147928, 'esMX', '', '¡Pues lo sieeeeeeento, princesa!', 28153),
(147927, 'esMX', '', '<Suspiro> ¿Realmente creí que trabajar con goblins podía terminar de otra forma?', 28153),
(147926, 'esMX', 'Este pantano es realmente terrible. ¡Sería fantástico que le sucediera algo!', '', 28153),
(147925, 'esMX', '', '¡Esta noche dormirás con los peces del pantano!', 28153),
(147924, 'esMX', '¡Volaremos en mil pedazos a tu dios antiguo al mejor estilo goblin!', '', 28153),
(147923, 'esMX', 'Ahora, si no te importa, tengo algunas cuentas más que saldar.', '', 28153),
(147922, 'esMX', 'Así es, pequeñín, ¡vete a dar un paseo!', '', 28153),
(147921, 'esMX', '', '¡Por aquí! ¡La encontré!', 28153),
(147920, 'esMX', '¡Ahora todo\' sabrán que esta es la Posada Colmilloáureo!', '', 28153),
(147919, 'esMX', '¡Tenemo\' que inventar algunas historia\' impresionantes sobre el trol temible y gigantesco al que le arrancamo\' este colmillo!', '', 28153),
(147918, 'esMX', 'Rokhan lleva mucho tiempo aquí, princesa. ¡No va a morir por unos pocos trols de sangre!', '', 28153),
(147917, 'esMX', 'Yo pilotearé esta cosa. Tú dime a dónde y yo disparo. ¡Montemos un buen espectáculo!', '', 28153),
(147916, 'esMX', 'Bueno, puede que no sea de oro, pero puedo tallarlo para darle forma de colmillo.', '', 28153),
(147915, 'esMX', '', 'Nazmir alberga demasiadas amenaza\'. Gracias a ti, ahora hay una menos.', 28153),
(147914, 'esMX', '', 'Jamás había vih\'to un brote así... Rápido, toma una vara de fuego y reduce sus números ante\' de que se propaguen.', 28153),
(147913, 'esMX', '$UBienvenido:Bienvenida; a la pandilla, $p. Estamoh\' juntos en eh\'to.', '', 28153),
(147912, 'esMX', 'Cargaremos esta cosa, navegaremos por el río y haremos pedazos a unos cuantos trols. ¿Quién se quiere sumar a la diversión?', '', 28153),
(147911, 'esMX', 'Estoy listo, subamos a esta barcaza y volvamos a Zul\'jan.', 'Estoy lista, subamos a esta barcaza y volvamos a Zul\'jan.', 28153),
(147910, 'esMX', 'Viniste por el M.I.D.A.S., ¿verdad? Bueno, andando. Cuanto antes salgamos de aquí mejor. \n\nYo voy a pilotear esta cosa. Si ves algo malo, avísame y disparo.\n\n¿$UListo:Lista; para partir?', '', 28153),
(147909, 'esMX', '¡Más sáuridos se reúnen para proteger el huevo!', '¡Más sáuridos se reúnen para proteger el huevo!', 28153),
(147908, 'esMX', '¡Vukuba rompe el cascarón!', '¡Vukuba rompe el cascarón!', 28153),
(147907, 'esMX', 'Ahora que lo pienso...', 'Ahora que lo pienso...', 28153),
(147906, 'esMX', '¡Los sáuridos fascinados se reúnen para proteger el huevo!', '¡Los sáuridos fascinados se reúnen para proteger el huevo!', 28153),
(147905, 'esMX', '', 'Los espíritus nos protegen.', 28153),
(147904, 'esMX', '¡Conoce a tuh\' nuevos hermanos y hermanas de la pandilla Colmilloáureo!', '', 28153),
(147903, 'esMX', '¡Ey, tú! ¿Qué crees que estás haciendo?', '', 28153),
(147902, 'esMX', '¡El camino a la victoria está despejado! ¡Ataquen la base del enemigo!', '', 28153),
(147901, 'esMX', 'Escuchen, brutos. ¡Paso Valeroso es todo lo que nos separa de Stromgarde!', '', 28153),
(147900, 'esMX', '¡Si capturamos el Círculo de Elementos, la victoria será nuestra!', '', 28153),
(147899, 'esMX', 'Su misión: saquear Granovel. ¡No podemos dejar que la Alianza nos rodee!', '', 28153),
(147898, 'esMX', 'El camino más rápido hasta Stromgarde atraviesa el Alto Pedestal. ¡Capturen esa colina!', '', 28153),
(147897, 'esMX', 'Nuestro próximo objetivo es Cruce Redilnorte. ¡El enemigo está justo en nuestras puertas!', '', 28153),
(147896, 'esMX', '', 'No se alejen, caballeros, y atravesaremos el territorio de las brujas sin que nos vean.', 28153),
(147895, 'esMX', '', 'Entonces nos encontraremos allí. Buena suerte, adalid.', 28153),
(147894, 'esMX', '', 'Maestro Ashton, ¿se quedará hasta el final?', 28153),
(147893, 'esMX', 'Parece que hay muchísima actividad en las ruinas que están cerca del árbol gigante.', '', 28153),
(147892, 'esMX', 'Desde luego. Marten y yo nos quedaremos.', '', 28153),
(147891, 'esMX', 'Fantástico.', '', 28153),
(147890, 'esMX', 'Tendría que haberme dedicado a la pesca.', 'Tendría que haberme dedicado a la pesca.', 28153),
(147889, 'esMX', '¡¿Por qué tardaste tanto?!', '¡¿Por qué tardaste tanto?!', 28153),
(147888, 'esMX', '', 'Eh\'pero que sea suficiente para saciar su apetito por el momento.', 28153),
(147887, 'esMX', '', 'Krag\'wa es un loa impulsivo que siempre ansía comida... y ofrendas. Quizá puedas recoger una ofrenda de la\' criaturas cercana\'.', 28153),
(147886, 'esMX', 'Eso solo existe en la mente, no en las duna\'.', '', 28153),
(147885, 'esMX', '', '¿Esto eh\' obra de Jakra\'zet?', 28153),
(147884, 'esMX', 'Investiga el huevo.', 'Investiga el huevo.', 28153),
(147883, 'esMX', 'Este huevo es demasiado grande para este nido. Pero parece que el sáurido cercano lo está cuidando...', 'Este huevo es demasiado grande para este nido. Pero parece que el sáurido cercano lo está cuidando...', 28153),
(147882, 'esMX', '¡Grenja! ¡Volni! ¡Man\'zul! ¡Regresaron! ¡Toda la pandilla eh\'tá aquí!', '', 28153),
(147881, 'esMX', '¡Me marcho de aquí!', '¡Me marcho de aquí!', 28153),
(147880, 'esMX', 'Hoy cumpliste con la voluntá de Bwonsamdi, $c.', 'Hoy cumpliste con la voluntá de Bwonsamdi, $c.', 28153),
(147879, 'esMX', 'Sentí que mi propio ser se desvanecía...', 'Sentí que mi propio ser se desvanecía...', 28153),
(147878, 'esMX', '¡No tienes por qué entrar aquí, Furiarena! Solo hay banana\'.', '', 28153),
(147877, 'esMX', 'Ahí estás, Zulsan. ¡La pandilla eh\'tá en problemas!', '', 28153),
(147876, 'esMX', '¡Atrás, bruto\'! ¡No volverán a atormentar a nuestro pueblo!', '', 28153),
(147875, 'esMX', '', '¡Muy bien! ¡Ninguna amenaza atentará contra la vida de mi pueblo!', 28153),
(147874, 'esMX', '', 'Los eh\'píritus me advierten de una presencia poderosa cerca. No bajes la guardia.', 28153),
(147873, 'esMX', '¡Lo sabía! ¡Sabía que unos seres extraños del océano no eran una base sólida para un sistema gubernamental!', '¡Lo sabía! ¡Sabía que unos seres extraños del océano no eran una base sólida para un sistema gubernamental!', 28153),
(147872, 'esMX', '¿Dónde está la milicia? ¿Dónde están los Canto Tormenta?', '¿Dónde está la milicia? ¿Dónde están los Canto Tormenta?', 28153),
(147871, 'esMX', 'Yo me largo de aquí, ¡no me importa cuántas espinas me claven!', 'Yo me largo de aquí, ¡no me importa cuántas espinas me claven!', 28153),
(147870, 'esMX', 'Qué bueno que estás aquí. Esas ollas estaban casi vacías...', 'Qué bueno que estás aquí. Esas ollas estaban casi vacías...', 28153),
(147869, 'esMX', '¡No quiero ser comida para jabaespines!', '¡No quiero ser comida para jabaespines!', 28153),
(147868, 'esMX', 'Necesito más municiones para Matabrujas.', 'Necesito más municiones para Matabrujas.', 28153),
(147867, 'esMX', 'Cuídate, $p, que los espíritu\' te acompañen.', 'Cuídate, $p, que los espíritu\' te acompañen.', 28153),
(147866, 'esMX', 'Libre al fin...', 'Libre al fin...', 28153),
(147865, 'esMX', 'Me iré con Bwonsamdi.', 'Me iré con Bwonsamdi.', 28153),
(147864, 'esMX', 'Gracia\', colega. Jamás olvidaré esto.', 'Gracia\', colega. Jamás olvidaré esto.', 28153),
(147863, 'esMX', '¡Atrápalos, $p! Nos reuniremo\' con Zulsan en la posada.', '', 28153),
(147862, 'esMX', '¡La barrera ha caído! ¡La Mansión Tarjasenda está frente a nosotros!', '', 28153),
(147861, 'esMX', 'Parece que este está disponible.', '', 28153),
(147860, 'esMX', 'El mariscal me envió para que te consiguiera un cañón.', '', 28153),
(147859, 'esMX', 'Es... imposible...', '', 28153),
(147858, 'esMX', '¡El aquelarre Hiel de corazón me ha concedido un poder inigualable! ¡Ahora caerás!', '', 28153),
(147857, 'esMX', '¡Muerte a los enemigos del aquelarre!', '', 28153),
(147856, 'esMX', 'Algo sobre uno de sus viejos guardias.', '', 28153),
(147855, 'esMX', 'Ah, continental... El mariscal pidió que hablaras con él antes de ir al campamento.', '', 28153),
(147854, 'esMX', 'Un momento, ¿cómo pudiste...? Oye, no serás $Uuno:una; de ellos, ¿no?', '', 28153),
(147853, 'esMX', '', '¿Holaaa? ¿Hay alguien ahí?', 28153),
(147852, 'esMX', '', 'Ya es tarde... para detenernos...', 28153),
(147851, 'esMX', '', '¡Mis creaciones dejarán este lugar yermo!', 28153),
(147850, 'esMX', '', 'Mi maldición... persiste...', 28153),
(147849, 'esMX', '', '¡Tus huesos serán una efigie excelente!', 28153),
(147848, 'esMX', '', 'Yo muero... pero nuestro maestro... es eterno...', 28153),
(147846, 'esMX', '', '¡Serás un tributo ideal!', 28153),
(147845, 'esMX', '', '¡Tú y todo Kul Tiras conocerán el dolor!', 28153),
(147844, 'esMX', '', '¡Gorak Tul les mostrará lo que es el tormento eterno!', 28153),
(147843, 'esMX', '', '¡Solo encontrarán desesperación en las Tierras Plagadas!', 28153),
(147842, 'esMX', '', '¡Tu agonía alimentará a nuestro amo ancestral!', 28153),
(147839, 'esMX', 'Esta es mi parte favorita. Te va a gustar, hace cosquillas.', '', 28153),
(147833, 'esMX', 'Ah, sí. Tal como pensé.', '', 28153),
(147830, 'esMX', 'Puede que parezca inofensivo, pero te aseguro que es una mente maestra del caos y los engaños. Solo quedarás $gimplicado:implicada; en sus felonías.', '', 28153),
(147829, 'esMX', 'Te lo ruego, no ayudes a Hank sin pensarlo antes.', '', 28153),
(147828, 'esMX', '', 'Ahora los eh\'píritus marchan camino a Bwonsamdi. Gracias por salvarlos de una eternidad de servidumbre.', 28153),
(147827, 'esMX', '', '¡Esos nigromante\' nefastos han capturado eh\'píritus para sus rituales! Mata a esos no-muerto\' para liberar a los eh\'píritus de su tormento.', 28153),
(147826, 'esMX', '¡Los matoneh\' furiarena atacaron la posada!\n\nApenas logré escapar con eh\'ta banana... parecía importante en el momento.', '', 28153),
(147825, 'esMX', '¡Ayuda! ¿Sigues ahí, $n? ¡No vuelvas a la posada! ¡Lo\' furiarena nos encontraron!', '', 28153),
(147824, 'esMX', '', 'Te esperaremo\' afuera, $n. Será mejor que nos pongamo\' en marcha.', 28153),
(147823, 'esMX', 'Por cada beh\'tia maldita que derribamo\', otras dos toman su lugar. ¡Nunca bajes la guardia, colega!', '', 28153),
(147822, 'esMX', 'Una abominación corrompida ha brotado de la tierra. Mátala... ¡ante\' de que venga por nosotros!', '', 28153),
(147821, 'esMX', '¿Qué estás haciendo, bestia del demonio? ¡Esa es mi bota!', '', 28153),
(147820, 'esMX', '¡$gIntruso:Intrusa;! ¡Rompeespinas!', '¡$UIntruso:Intrusa;! ¡Rompeespinas!', 28153),
(147819, 'esMX', '¡Avisen al horado!', '¡Avisen al horado!', 28153),
(147818, 'esMX', '¡Guardias! ¡A mí!', '¡Guardias! ¡A mí!', 28153),
(147817, 'esMX', '¡Pica como abeja!', '¡Pica como abeja!', 28153),
(147816, 'esMX', 'Somos un buen equipo.', 'Somos un buen equipo.', 28153),
(147815, 'esMX', '¡Expulsémoslos a las montañas!', '¡Expulsémoslos a las montañas!', 28153),
(147814, 'esMX', 'Olvídalo. Arrójaselo a Pinky, siempre e\'tá de humor para un bocado. ¡Ja ja ja!', '', 28153),
(147813, 'esMX', '¡No te llevarás mi granja!', '¡No te llevarás mi granja!', 28153),
(147812, 'esMX', 'Dale una buena patada. ¡Así aprenderá a eh\'cuchar!', '', 28153),
(147811, 'esMX', 'No tenía oportunidad.', 'No tenía oportunidad.', 28153),
(147810, 'esMX', 'Tiene\' que ser más duro con él o no te respetará.', '', 28153),
(147809, 'esMX', 'Ja ja. ¡Toma eso!', 'Ja ja. ¡Toma eso!', 28153),
(147808, 'esMX', '¡No sirves para nada! ¡Te haré salchicha si sigues así!', '¡No sirves para nada! ¡Te haré salchicha si sigues así!', 28153),
(147807, 'esMX', '¡Ahora lo entenderás!', '¡Ahora lo entenderás!', 28153),
(147806, 'esMX', '¿A dónde vas? ¡Atrápenlo!', '¿A dónde vas? ¡Atrápenlo!', 28153),
(147801, 'esMX', '¡Yo me largo!', '', 28153),
(147800, 'esMX', '¡No voy a morir por estos idiotas!', '', 28153),
(147799, 'esMX', '¡No me pagan lo suficiente como para hacer esto!', '', 28153),
(147798, 'esMX', '¡Bzzzt!', '', 28153),
(147796, 'esMX', '', 'Te maldigo...', 28153),
(147795, 'esMX', '', 'Le llevaré el Ojo a Moira. ¡Junto con tu cabeza!', 28153),
(147794, 'esMX', 'Me obligaron a matar a esos comerciantes... No pude evitarlo.', 'Me obligaron a matar a esos comerciantes... No pude evitarlo.', 28153),
(147793, 'esMX', '¿Dónde estoy?', '¿Dónde estoy?', 28153),
(147792, 'esMX', '¡Los Furiarena pagarán por esto!', '¡Los Furiarena pagarán por esto!', 28153),
(147791, 'esMX', '¡Al fin libre!', '¡Al fin libre!', 28153),
(147789, 'esMX', '', '<En el tobillo, descubres un trozo de soga que alguien ha cortado a la perfección.$B$BLe atravesaron el corazón, pero no ves rastro alguno de un arma.$B$BTampoco descubres huellas alrededor del cuerpo.>', 28153),
(147788, 'esMX', 'Vamos, aplah\'ta a esa alimaña, ¡AHORA!', 'Vamos, aplah\'ta a esa alimaña, ¡AHORA!', 28153),
(147787, 'esMX', 'Vamoh\', amiguito. ¡A la cargaaa!', 'Vamoh\', amiguito. ¡A la cargaaa!', 28153),
(147786, 'esMX', 'Bien, cuando ese minirraptor caiga en la trampa, ¡tú lo ataca\'! ¿Entendido?', 'Bien, cuando ese minirraptor caiga en la trampa, ¡tú lo ataca\'! ¿Entendido?', 28153),
(147785, 'esMX', '¡Esclavos! ¡Maten a estos forasteros!', '¡Esclavos! ¡Maten a estos forasteros!', 28153),
(147784, 'esMX', '¡Aaaaauch!', '¡Aaaaauch!', 28153),
(147783, 'esMX', '', 'Tienes mi agradecimiento. Ahora las alma\' de los muerto\' pueden viajar en paz.', 28153),
(147782, 'esMX', '', 'Eh\'te monstruo solía ser un guardián de lo\' fieles. Ahora se alimenta de las almas de lo\' muertos. ¡Destrúyelo!', 28153),
(147781, 'esMX', 'Nunca me deh\'truirás, $pr...', '', 28153),
(147780, 'esMX', 'Primero loh\' subyugaré, luego loh\' venderé.', '', 28153),
(147779, 'esMX', '', '¡Lo logramos, muchachos! ¡En marcha!', 28153),
(147778, 'esMX', '', '¡Bien hecho! No podemo\' permitir que estas abominaciones corran libres por nueh\'tras tierras.', 28153),
(147777, 'esMX', '', '¡La tierra mih\'ma ha producido un horror! ¡Rápido, acábalo antes de que se abra paso hasta Zuldazar!', 28153),
(147775, 'esMX', 'Me pregunto si esto está relacionado con esas cosas que destruyeron la granja.', '', 28153),
(147774, 'esMX', 'Aquí debe ser adonde iba por las noches.', '', 28153),
(147773, 'esMX', 'No puedo creer que todas estas cosas estaban aquí.', '', 28153),
(147772, 'esMX', 'Mi papá me debe unas respuestas...', '', 28153),
(147771, 'esMX', '¿Qué está pasando ahí abajo?', '', 28153),
(147770, 'esMX', 'Qué extraño.', '', 28153),
(147769, 'esMX', '¿Qué es esto?', '', 28153),
(147768, 'esMX', 'Mmm...', '', 28153),
(147767, 'esMX', '¡Nos vemos!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(147766, 'esMX', '¡Toma, muchacho! ¡Come!', '¡Toma, muchacho! ¡Come!', 28153),
(147765, 'esMX', 'Compilaré las lecturah\' mientras regresas al campamento. ¡Prácticamente puedo oler el Ojo!', '', 28153),
(147764, 'esMX', 'Fah\'cinante. Creo que tenemos algo interesante, $n.', '', 28153),
(147763, 'esMX', 'Detecto una leve señal arcana! Nos eh\'tamos acercando.', '', 28153),
(147762, 'esMX', 'Bueno, eh\'ta lectura no es muy prometedora.', '', 28153),
(147761, 'esMX', '', '¡G\'huun se vengará!', 28153),
(147760, 'esMX', '', '¡Mis mascota\' se harán un festín contigo!', 28153),
(147758, 'esMX', '', '¿Qué? Déjame intentarlo.', 28153),
(147757, 'esMX', '', '<suspiro> Nunca pasa nada interesante en esta\' patrullas.', 28153),
(147756, 'esMX', '', '¡Ja, ja, ja!', 28153),
(147755, 'esMX', '', 'Lloraban y suplicaban como si con eso fueran a lograr algo. Murieron igual.', 28153),
(147754, 'esMX', '', 'Oh, oh.', 28153),
(147753, 'esMX', '', 'Oye, ¿qué fue eso?', 28153),
(147752, 'esMX', '', '¿Has vih\'to cómo se retorcían?', 28153),
(147751, 'esMX', '(Decirle a Yash que si quiere vivir una historia alocada debería ir a Hondonada Penumbrosa para ayudar a detener a los trols de sangre y su dios.)', '(Decirle a Yash que si quiere vivir una historia alocada debería ir a Hondonada Penumbrosa para ayudar a detener a los trols de sangre y su dios.)', 28153),
(147750, 'esMX', 'No creo que muchos tortollanos quieran escuchar la historia de un loa muerto y destripado... ¿Qué les diré a los demás cuando regrese?', '', 28153),
(147749, 'esMX', '(Decirle a Korkush que tendrá una gran historia para contar si ayuda a la Horda a pelear contra los trols de sangre y salvar a los zandalari.)', '(Decirle a Korkush que tendrá una gran historia para contar si ayuda a la Horda a pelear contra los trols de sangre y salvar a los zandalari.)', 28153),
(147748, 'esMX', 'Bah, Torga está muerto, los trols de sangre han arrasado con este lugar... ¡el peregrinaje está arruinado! No tiene sentido que me quede aquí.', '', 28153),
(147747, 'esMX', '(Decirle a Crez sobre lo que le sucedió a Torga, y la probabilidad de que se cuenten nuevas historias si va a Hondonada Penumbrosa.)', '(Decirle a Crez sobre lo que le sucedió a Torga, y la probabilidad de que se cuenten nuevas historias si va a Hondonada Penumbrosa.)', 28153),
(147744, 'esMX', '¿Un espíritu de hace miles de años que anhela venganza y quiere matarnos a todos? Encantador.', '', 28153),
(147743, 'esMX', '¿Su amo?', '', 28153),
(147742, 'esMX', 'Según lo que oí mientras me tenían como prisionero, sospecho que esta entidad tiene alguna relación con los drust.', '', 28153),
(147741, 'esMX', 'Su amo odia a los kultiranos con cada fibra de su ser. Incluso las brujas son simples peones de su deseo por regresar a nuestro reino.', '', 28153),
(147740, 'esMX', 'Un ser malévolo que les da poder. He oído que su ira resonaba en la oscuridad.', '', 28153),
(147739, 'esMX', 'Las brujas mencionaron un \"gran rito\" para invocar a su amo.', '', 28153),
(147738, 'esMX', '¡Hay asuntos más urgentes, Inquisidora!', '', 28153),
(147737, 'esMX', 'Ah... Eso creo. Gracias, Marten… $n.', '', 28153),
(147736, 'esMX', '', 'Debemos detener este \"gran rito\" a toda costa.', 28153),
(147735, 'esMX', '', 'No era un simple drust... Creo que era su líder. El ser contra el que peleó Arom Tarjasenda hace muchos años.', 28153),
(147734, 'esMX', '', 'Deberíamos llevarlo de regreso a Halcónida, maestro Ashton.', 28153),
(147733, 'esMX', '', 'Maestro Ashton, ¿ya ha recuperado la razón?', 28153),
(147732, 'esMX', '¡Aaaahhh!!! ¡El bru!', '', 28153),
(147731, 'esMX', '¡Mantengan la posición! ¡Si algo se mueve, mátenlo!', '', 28153),
(147730, 'esMX', '¿Eh? ¿Que quieres? Ya me voy a casa, no queda nada interesante aquí.', '', 28153),
(147729, 'esMX', 'Plantando moneda maldita', 'Plantando moneda maldita', 28153),
(147728, 'esMX', 'Muy bien, colega. Esas... cosas ahora deh\'cansarán en el lugar donde pertenecen, bajo tierra.', '', 28153),
(147727, 'esMX', 'Esos trols natha\'vor eh\'tán regando las planta\' con sacrificios. ¡Detenlos antes de que nos arrasen las plantas carnívora\'!', '', 28153),
(147726, 'esMX', 'Entendido.', '', 28153),
(147725, 'esMX', 'Que así sea. Campeones, conmigo. Mekkatorque, vuelve a la fortaleza con el resto de nuestras fuerzas y organízalas en Rémol. Prepárense: atacarán cuando lo ordene.', '', 28153),
(147724, 'esMX', 'Ve. Recorre el camino y buh\'ca el mejor lugar para plantar esta moneda. Pero cuidado, no dejes que los depredadores hambriento\' te vean...', '', 28153),
(147723, 'esMX', 'Oye, $n, ¿para qué crees que sirve todo esto?', '', 28153),
(147722, 'esMX', 'Esto parece un fragmento pequeño de esas cosas de ahí afuera...', '', 28153),
(147721, 'esMX', '¿Eso es un mapa? Mmm.... Hay una marca roja cerca del campo de flores.', '', 28153),
(147720, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo antiguo y deslustrado al Sagrario de los Carroñeros?', '', 28153),
(147719, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo feo y escamoso al Sagrario de los Carroñeros?', '', 28153),
(147718, 'esMX', '<Olfatea> Puaj... eso definitivamente no es miel.', '', 28153),
(147717, 'esMX', 'Tengo miel recién recolectada, por si te interesa.', '', 28153),
(147716, 'esMX', '¡$gBienvenido:Bienvenida; a Los Cuatro Aguijones, $pr, hogar de la única colmena de miel de Vol\'dun!', '', 28153),
(147715, 'esMX', 'Saludo\', $Uricachón:ricachona;. ¿Has traído algo hermoso y resplandeciente al Sagrario de los Carroñeros?', '', 28153),
(147714, 'esMX', '', '¡Busca y destruye a nuestros enemigos!', 28153),
(147713, 'esMX', '', '¡Levántate, espíritu de agua! ¡Necesitamos tu ayuda!', 28153),
(147712, 'esMX', '', 'Puede que la lentitud y la perseverancia ganen aquí abajo, pero en los cielos la historia es muy diferente.', 28153),
(147711, 'esMX', 'Encárgate del otro loa. Yo buscaré más invasores en los jardines y los mataré.', '', 28153),
(147710, 'esMX', '¡Herejes! ¿Cómo osan entrar a MI guarida? ¡Esta será su tumba!', '', 28153),
(147709, 'esMX', '¡Saludos, joven adalid! ¿Has venido a acompañarme a masacrar a estos herejes?', '', 28153),
(147708, 'esMX', 'Libérame...', '', 28153),
(147707, 'esMX', '', 'Espíritu de fuego. ¡Que los elementos guíen tu camino! ¡Solicitamos tu ayuda para la batalla que se avecina!', 28153),
(147706, 'esMX', 'Las cosas que he visto.... el horror.... el horror...', '', 28153),
(147705, 'esMX', 'Las cosas que he visto...', '', 28153),
(147704, 'esMX', 'Saludos, $Uricachón:ricachona;. ¿Has traído algo brillante y reluciente al Sagrario de los Carroñero\'?', '', 28153),
(147703, 'esMX', 'Mira... la miel... ¡Se está moviendo sola!', '', 28153),
(147702, 'esMX', '<Entregar la poción al maestro Ashton>', '<Entregar la poción al maestro Ashton>', 28153),
(147701, 'esMX', 'Saludos, $Uricachón:ricachona;. ¿Has traído algo suave y brillante al Sagrario de los Carroñero\'?', '', 28153),
(147700, 'esMX', '¡Increíble! Quiero ser $Gun:una; $pc como tú cuando crezca.', '', 28153),
(147699, 'esMX', '¡No tenía oportunidad!', '', 28153),
(147698, 'esMX', '¡Tomen eso!', '', 28153),
(147697, 'esMX', '¡Vaya! ¡Sí que eres fuerte!', '', 28153),
(147696, 'esMX', 'Muy bien, $Umuchacho:muchacha;, reunámonos en Caída de Alamuerte. Usaremos la lava del lugar para fundir los materiales. También llevaré algunos suministros adicionales.', '', 28153),
(147695, 'esMX', '¡Mpf mpf mpf!', '¡Mpf, mpf, mpf!', 28153),
(147694, 'esMX', 'Mira, agradezco mucho lo que has hecho por mí. Después de todo el trabajo que hiciste, no sabía si ese yunque te importaba más que yo.$b$bPor fortuna, Therazane tuvo la amabilidad de entregártelo de todos modos.$b$bPero yo escucharía su advertencia. No le digas a nadie más cómo lo logramos.', '', 28153),
(147693, 'esMX', 'Mpf mpf mpf mpf. Mpf mpf mpf.', 'Mpf mpf mpf mpf. Mpf mpf mpf.', 28153),
(147692, 'esMX', 'Mpf mpf mpf. Mpf.', '', 28153),
(147691, 'esMX', '¡Ah, y Cebo tiene su propia historia!', '¡Ah, y Cebo tiene su propia historia!', 28153),
(147690, 'esMX', '¡Mpf mpf, mpf mpf mpf!', '¡Mpf mpf, mpf mpf mpf!', 28153),
(147689, 'esMX', 'Sí, Cebo tiene razón. ¡Nadie ha visto a Ozumat desde el Cataclismo!', 'Sí, Cebo tiene razón. ¡Nadie ha visto a Ozumat desde el Cataclismo!', 28153),
(147688, 'esMX', '¡Y así fue como até al incomparable demonio de las profundidades a este mismísimo mástil!', '¡Y así fue como amarré al incomparable demonio de las profundidades a este mismísimo mástil!', 28153),
(147687, 'esMX', '¡Cerremos el trato!', '¡Cerremos el trato!', 28153),
(147686, 'esMX', 'Con los tentáculos de la bestia fuera del camino, era hora de terminar el trabajo.', 'Con los tentáculos de la bestia fuera del camino, era hora de terminar el trabajo.', 28153),
(147685, 'esMX', '¡¿Ozumat?! ¡No en mi muelle!', '¡¿Ozumat?! ¡No en mi muelle!', 28153),
(147684, 'esMX', '¡Tanto pescar y pescar ha llamado la atención del mismísimo leviatán Ozumat!', '¡Tanto pescar y pescar ha llamado la atención del mismísimo leviatán Ozumat!', 28153),
(147683, 'esMX', 'Yyyy ya que estamos en el tema, ¡es hora de que esta gallina vuele del gallinero! ¡Buena suerte, $gamigo mío:amiga mía;!', '', 28153),
(147682, 'esMX', 'No te preocupes, Pam, ¡no perderás ni una sola pluma!', '', 28153),
(147681, 'esMX', '', 'Buena suerte. Recuerda: esto no tiene absolutamente nada que ver conmigo.', 28153),
(147680, 'esMX', 'Esta isla tiene una gran actividad termal. Si un géiser entra en erupción, seguramente empezará a brotar azerita por sus fisuras. ¡Esto debe valer una fortuna!', 'Esta isla tiene una gran actividad termal. Si un géiser entra en erupción, seguramente empezará a brotar azerita por sus fisuras. ¡Esto debe valer una fortuna!', 28153),
(147679, 'esMX', 'Una vez más. ¡Con ganas, mi elegante $gamigo:amiga;! ¡Subamos estas gallinas al bote!', '', 28153),
(147678, 'esMX', 'Con gusto.', '', 28153),
(147677, 'esMX', 'Y yo traje a un amigo mío, Hank. Verick, muéstrale lo que sabes hacer.', '', 28153),
(147676, 'esMX', '¡Greer-y, mi buen amigo! ¿Cómo te trata este hermoso día? ¡Tenemos unos magníficos ejemplares plumíferos listos para enviar!', '', 28153),
(147675, 'esMX', 'Vaya, vaya, mira a quién tenemos aquí.', '', 28153),
(147674, 'esMX', 'Mi pueblo está cercado por distintas amenazas, pero la más peligrosa es la corrupción a la que se han entregado los trols de sangre.\n\nSiento su apestoso hedor cerca. Cuando estés $glisto:lista;, buscaremos la fuente juntos.', '', 28153),
(147673, 'esMX', 'Una victoria menor... pero aun así una victoria.', '', 28153),
(147672, 'esMX', '¡Aprovechemos el momento!', '', 28153),
(147671, 'esMX', 'No encuentras nada en estos salones empapados de sal...', 'No encuentras nada en estos salones empapados de sal...', 28153),
(147670, 'esMX', '¡La mortalidad evidenciada en un solo golpe!', '', 28153),
(147669, 'esMX', '¡Una paliza contundente!', '', 28153),
(147668, 'esMX', '¡Sus campeones malditos caen!', '', 28153),
(147667, 'esMX', 'Cuando el enemigo cae, una tenue esperanza florece.', '', 28153),
(147666, 'esMX', 'Destrúyelos. A. Todos.', '', 28153),
(147665, 'esMX', 'Ahora descansa, $Uadventurero:adventurera;. Tienes la mente demasiado fracturada por este lugar. Regresa en tres días y quizá tengas voluntad para enfrentar otra vez a estos horrores.', '', 28153),
(147664, 'esMX', 'Estoy listo para cazar con la manada.', 'Estoy lista para cazar con la manada.', 28153),
(147663, 'esMX', '', '$UBienvenido:Bienvenida; a la manada, $p. Lo hicih\'te bien.', 28153),
(147662, 'esMX', '¡La Horda quedará reducida a cenizas!', '¡La Horda quedará reducida a cenizas!', 28153),
(147661, 'esMX', '¡Juu-ah!', '¡Juu-ah!', 28153),
(147660, 'esMX', '¡Nuestros enemigos caerán!', '¡Nuestros enemigos caerán!', 28153),
(147659, 'esMX', '¡Por Stromgarde!', '¡Por Stromgarde!', 28153),
(147658, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(147657, 'esMX', '¡Por la gloria de la Alianza!', '', 28153),
(147656, 'esMX', '¡Al ataque!', '', 28153),
(147655, 'esMX', '¡Estocada!', '', 28153),
(147654, 'esMX', 'Excelente.', '', 28153),
(147653, 'esMX', 'Recuerda tu entrenamiento.', '', 28153),
(147652, 'esMX', 'Mantente fuerte.', '', 28153),
(147651, 'esMX', 'Buena forma.', '', 28153),
(147650, 'esMX', 'Bien hecho.', '', 28153),
(147649, 'esMX', '¡Espadas preparadas!', '', 28153),
(147648, 'esMX', 'No te olvides de honrarme, $p. Te estaré observando.', '', 28153),
(147647, 'esMX', 'Hiciste lo correcto al enviarme a $geste:esta;, Loti. $p fortalece la manada.', '', 28153),
(147646, 'esMX', 'Atravesaremos las sombras una vez más para acelerar nuestro viaje. Sujétate.', '', 28153),
(147645, 'esMX', 'Erige una estatua mía en la ciudad, $p. Cuéntale al pueblo de las hazañas de la manada. Nuestras hazañas.', '', 28153),
(147644, 'esMX', 'Estoy listo para regresar a Dazar\'alor como tu campeón.', 'Estoy lista para regresar a Dazar\'alor como tu campeona.', 28153),
(147643, 'esMX', 'Hoy guiaste bien a la manada, $p.\n\nJuntos, somos fuertes.', '', 28153),
(147642, 'esMX', '¡Esto es lo que yo llamo pescar!', '¡Esto es lo que yo llamo pescar!', 28153),
(147641, 'esMX', 'Pescando', 'Pescando', 28153),
(147640, 'esMX', 'Súbete a mi espalda una vez más y te llevaré a Dazar\'alor.', '', 28153),
(147639, 'esMX', 'Guiaste bien a la manada, $p. Sería un honor darte la bienvenida como mi $Gcampeón:campeona;.', '', 28153),
(147638, 'esMX', 'Tu sangre todavía estará fresca cuando caiga en el olvido.', '', 28153),
(147637, 'esMX', '$n, ¡¿quién era esa?! Lucha con tanta fiereza...', '', 28153),
(147636, 'esMX', '$p guiará a la manada por el momento... Demuestra que eres $Gdigno:digna; de cargar con ese honor.', '', 28153),
(147635, 'esMX', 'Los trols de sangre están cerca. Nuestra manada ya ha encontrado a algunos de ellos.', '', 28153),
(147634, 'esMX', '¡Arriba, manada! Despiértense y prepárense mientras no estoy. ¡Saldremos de cacería pronto!', '', 28153),
(147633, 'esMX', 'Súbete a mi espalda, $p. Ni siquiera tú eres capaz de seguirle el paso a un loa en apuros.', '', 28153),
(147632, 'esMX', 'Sentí que estaba por perder la cabeza. Te debo la vida, continental.', 'Sentí que estaba por perder la cabeza. Te debo la vida, continental.', 28153),
(147631, 'esMX', '', 'Mi sangre envenenará eh\'ta tierra durante generaciones.', 28153),
(147630, 'esMX', '', '¡Esclavos arrogante\' y débiles de los loa! ¡G\'huun es supremo!', 28153),
(147629, 'esMX', '', 'Ah, no te preocupes. Es un fusil especial que diseñé yo misma. Se activa solamente cuando una conversación me aburre.\n\nAsí que... Bum.', 28153),
(147628, 'esMX', '¿Estás sosteniendo una barra de dinamita prendida?', '¿Estás sosteniendo una barra de dinamita prendida?', 28153),
(147627, 'esMX', '', 'Algunos dicen que manipular explosivos es un trabajo peligroso, pero yo la paso bomba.', 28153),
(147625, 'esMX', '', 'Toma una decisión.', 28153),
(147624, 'esMX', '', 'O puedes elegir llevarte el yunque que has creado, el premio que estuviste buscando todo este tiempo.', 28153),
(147623, 'esMX', '', 'Toma una caja, tenemos que sacar todo esto de aquí mientras podamos.', 28153),
(147622, 'esMX', '', 'Puedes elegir liberar a tu aliado, aquel que traicionó a su pueblo al compartir nuestro preciado conocimiento contigo...', 28153),
(147621, 'esMX', '', 'Bien hecho, ser de carne. Ahora, te ofrezco tu premio. Una elección.', 28153),
(147620, 'esMX', '<Recoger a la cría.>', '<Recoger a la cría.>', 28153),
(147618, 'esMX', '<Kua\'fon te saluda con un suave chillido.>\n\n¡Riiii!', '', 28153),
(147617, 'esMX', '<Kua\'fon tuerce la cabeza cuando te ve llegar.>', '', 28153),
(147616, 'esMX', '<Kua\'fon se emociona al ver que le prestas atención.>\n\n¿Rii?', '', 28153),
(147615, 'esMX', '<Kua\'fon te observa con curiosidad.>', '', 28153),
(147614, 'esMX', 'Su líder espera adelante, $p. Continúen avanzando y juntos, la mataremos.', '', 28153),
(147613, 'esMX', '¡Ja! Eso fue divertido...', '', 28153),
(147612, 'esMX', '¡A la carga, hermanos y hermanas! ¡Que nada los detenga!', '', 28153),
(147611, 'esMX', 'Ven conmigo, $p. Te mostraré cómo lucha un loa.', '', 28153),
(147610, 'esMX', 'A mí, manada. ¡Es hora de ponerle fin a esto!', '', 28153),
(147609, 'esMX', '', 'Muy bien, ser de carne. Derrota a mi coloso y te ganarás mi favor.', 28153),
(147608, 'esMX', '', 'No hay tiempo que perder. ¡Muere, bestia!', 28153),
(147607, 'esMX', 'Estoy listo para realizar tu prueba, Therazane.', 'Estoy lista para realizar tu prueba, Therazane.', 28153),
(147606, 'esMX', '', '¡Eres la peste de esta tierra!', 28153),
(147605, 'esMX', '', '¡Mi sable no descansará!', 28153),
(147604, 'esMX', '', '¡Tu tribu es débil!', 28153),
(147603, 'esMX', '', '¡Te mataré con mis propias manos!', 28153),
(147600, 'esMX', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_09.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Bocaditos para dinosaurios bebés]|h|r>', '<Ofrecer |TINTERFACE\\ICONS\\INV_MISC_BAG_09.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Bocaditos para dinosaurios bebés]|h|r>', 28153),
(147599, 'esMX', '<Kua\'fon te observa fijamente y abre las fauces.>\n\n¡RIIIII! ¡RIIIIRRR!', '', 28153),
(147596, 'esMX', 'Ayuda.', 'Ayuda.', 28153),
(147595, 'esMX', '', '¿Qué quieres?', 28153),
(147593, 'esMX', '¿Riiii?', '', 28153),
(147592, 'esMX', 'Riiii...', '', 28153),
(147591, 'esMX', '¡RIIIIII!', '', 28153),
(147590, 'esMX', '¡Riiii!', '', 28153),
(147589, 'esMX', 'Ah, hola, Willow.', '', 28153),
(147588, 'esMX', 'Sí, así es. Veamos qué tienes.', '', 28153),
(147587, 'esMX', 'Tiene un poco de vergüenza. Nos enteramos que necesitabas suministros.', '', 28153),
(147586, 'esMX', '¡Ajá! ¡Me pareció oírte llegar!', '', 28153),
(147585, 'esMX', 'Esta tierra está maldita.', 'Esta tierra está maldita.', 28153),
(147584, 'esMX', 'Que la peste caiga sobre el aquelarre.', 'Que la peste caiga sobre el aquelarre.', 28153),
(147583, 'esMX', 'Incluso los cultivos podridos vuelven a crecer.', 'Incluso los cultivos podridos vuelven a crecer.', 28153),
(147582, 'esMX', 'Ocúpate de tus asuntos, yo me ocupo de los míos.', 'Ocúpate de tus asuntos, yo me ocupo de los míos.', 28153),
(147581, 'esMX', '$gUn:Una; continental, ¿eh?', '$gUn:Una; continental, ¿eh?', 28153),
(147580, 'esMX', 'No vemos muchos viajeros por aquí.', 'No vemos muchos viajeros por aquí.', 28153),
(147579, 'esMX', '¿Alguna vez viste la panza de un kraken? Sigue así y la verás.', '¿Alguna vez viste la panza de un kraken? Sigue así y la verás.', 28153),
(147578, 'esMX', 'Empiezo a pensar que no tienes los dos remos en el agua.', 'Empiezo a pensar que no tienes los dos remos en el agua.', 28153),
(147577, 'esMX', '¡Aj! Ese olor a agua estancada eres tú, ¿verdad?', '¡Agh! Ese olor a agua estancada eres tú, ¿verdad?', 28153),
(147576, 'esMX', 'El aquelarre caerá.', 'El aquelarre caerá.', 28153),
(147575, 'esMX', 'Una verdadera bruja buena es una bruja muerta.', 'La única bruja buena es una bruja muerta.', 28153),
(147574, 'esMX', 'Gloria a la casa Tarjasenda.', 'Gloria a la casa Tarjasenda.', 28153),
(147573, 'esMX', 'No dejes que el lastre te golpee. ', 'No dejes que el lastre te golpee.    ', 28153),
(147572, 'esMX', 'La marea no espera a nadie.', 'La marea no espera a nadie.', 28153),
(147571, 'esMX', 'Se acerca una tormenta. Las aguas no mienten.', 'Se acerca una tormenta. Las aguas no mienten.', 28153),
(147570, 'esMX', 'Vientos fuertes y ancla firme.', 'Vientos fuertes y ancla firme.', 28153),
(147569, 'esMX', 'Nunca pierdas de vista el clima.', 'Nunca pierdas de vista el clima.', 28153),
(147568, 'esMX', 'Vientos favorables y mares calmos.', 'Vientos favorables y mares calmos.', 28153),
(147567, 'esMX', '¡Por Kul Tiras!', '¡Por Kul Tiras!', 28153),
(147566, 'esMX', 'Mi espada está lista.', 'Mi espada está lista.', 28153),
(147565, 'esMX', '¿Amigo o enemigo?', '¿Amigo o enemigo?', 28153),
(147564, 'esMX', 'Drustvar se alza imponente.', 'Drustvar se alza imponente.', 28153),
(147563, 'esMX', 'Habla de una vez.', 'Habla de una vez.', 28153),
(147562, 'esMX', 'Mantén el rumbo.', 'Firme el timón.', 28153),
(147561, 'esMX', 'Más de lo que crees, pequeña.', '', 28153),
(147560, 'esMX', '', '¿Y yo también ayudo, papá?', 28153),
(147559, 'esMX', 'Bueno, nosotros, por ejemplo, entregamos nuestra comida en las tiendas para que los trabajadores puedan comer y reconstruir. Así colaboramos.', '', 28153),
(147558, 'esMX', 'Manos a la obra.', 'Manos a la obra.', 28153),
(147557, 'esMX', '¿Órdenes?', '¿Órdenes?', 28153),
(147556, 'esMX', 'En marcha.', 'En marcha.', 28153),
(147555, 'esMX', 'Listo para la acción.', 'Lista para la acción.', 28153),
(147554, 'esMX', '¿Sí?', '¿Sí?', 28153),
(147553, 'esMX', '', '¿Como qué?', 28153),
(147552, 'esMX', 'Bueno, es que hay mucho por hacer.', '', 28153),
(147551, 'esMX', '', '¿Por qué?', 28153),
(147550, 'esMX', 'Pues sí, supongo que hay mucha actividad hoy.', '', 28153),
(147549, 'esMX', '', 'Papá, ¿siempre hay tanta gente en este lugar?', 28153),
(147548, 'esMX', '¡Hacia la victoria!', '¡Hacia la victoria!', 28153),
(147547, 'esMX', '¡Iiija!', '¡Iiija!', 28153),
(147546, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(147545, 'esMX', '¡Que se oiga!', '', 28153),
(147544, 'esMX', '¡Posiciones defensivas!', '', 28153),
(147543, 'esMX', 'Vamos por buen camino.', '', 28153),
(147542, 'esMX', 'Necesita trabajo.', '', 28153),
(147541, 'esMX', 'Con eso basta.', '', 28153),
(147540, 'esMX', 'Bien hecho.', '', 28153),
(147539, 'esMX', 'Bien.', '', 28153),
(147538, 'esMX', '¡Preparados!', '', 28153),
(147537, 'esMX', '', 'Gonk... vino por... mí.', 28153),
(147535, 'esMX', '', 'La manada... protege.', 28153),
(147534, 'esMX', 'La manada está aquí, Zajera. No estás sola.', '', 28153),
(147533, 'esMX', '', 'Gonk... me dejaron... sola...', 28153),
(147531, 'esMX', '', '¡Recuperaremos la mina, muchachos! ¡Tomen toda la dinamita que puedan y salgamos de aquí! Reúnanse con nosotros en el depósito fuera de la mina. ¡Hablaremos allí!', 28153),
(147530, 'esMX', '', 'Por todah\' partes...', 28153),
(147529, 'esMX', '', '<Zajera está cubierta de sangre y ha sufrido muchas heridas. Hace un esfuerzo por hablar.>\n\nLa manada protege... al más débil...', 28153),
(147528, 'esMX', 'Solo, eh, quería disfrutar de la vista un segundo más.', 'Solo, eh, quería disfrutar de la vista un segundo más.', 28153),
(147527, 'esMX', 'En fin, como decía, necesitábamos pescado para el festival, y mucho, así que me puse en marcha.', 'En fin, como decía, necesitábamos pescado para el festival, y mucho, así que me puse en marcha.', 28153),
(147526, 'esMX', 'Gonk está aquí, Zajera. ¿Dónde están los trols de sangre que hicieron esto?', 'Gonk está aquí, Zajera. ¿Dónde están los trols de sangre que hicieron esto?', 28153),
(147525, 'esMX', '', '<Zajera está cubierta de sangre y ha sufrido muchas heridas. Hace un esfuerzo por hablar.>\n\nGonk... plegarias... tú...', 28153),
(147524, 'esMX', 'Es hora de pescar algunos... eh... ¡peces!', 'Es hora de pescar algunos... eh... ¡peces!', 28153),
(147523, 'esMX', 'Tengo otros asuntos que atender.', 'Tengo otros asuntos que atender.', 28153),
(147522, 'esMX', 'Si juegas con fuego, saldrás quemado.', 'Si juegas con fuego, saldrás quemado.', 28153),
(147521, 'esMX', 'Que el Yunquenegro te bendiga.', 'Que el Yunquenegro te bendiga.', 28153),
(147520, 'esMX', 'Que el brillo de la forja te proteja.', 'Que el brillo de la forja te proteja.', 28153),
(147519, 'esMX', 'Secretos infinitos aguardan en las profundidades.', 'Secretos infinitos aguardan en las profundidades.', 28153),
(147518, 'esMX', 'El clan Hierro Negro forjará un nuevo futuro.', 'El clan Hierro Negro forjará un nuevo futuro.', 28153),
(147517, 'esMX', 'La montaña nos guía a casa.', 'La montaña nos guía a casa.', 28153),
(147516, 'esMX', '¿Hasta dónde estás $gdispuesto:dispuesta; a excavar?', '¿Hasta dónde estás $gdispuesto:dispuesta; a excavar?', 28153),
(147515, 'esMX', 'El fuego arde en nuestros corazones.', 'El fuego arde en nuestros corazones.', 28153),
(147514, 'esMX', 'Respondo a la voz de la montaña.', 'Respondo a la voz de la montaña.', 28153),
(147513, 'esMX', 'Vamos, di lo que tengas que decir.', 'Vamos, di lo que tengas que decir.', 28153),
(147512, 'esMX', '¿Tienes lava en las venas?', '¿Tienes lava en las venas?', 28153),
(147511, 'esMX', '¿Cómo puedo ayudarte?', '¿Cómo puedo ayudarte?', 28153),
(147510, 'esMX', 'Nuestro poder fluye desde la montaña.', 'Nuestro poder fluye desde la montaña.', 28153),
(147509, 'esMX', '¡Ey, ese e\' mi sombrero favorito! Agh... estoy demasiado mareado, colega...', '', 28153),
(147508, 'esMX', 'Recordando', 'Recordando', 28153),
(147507, 'esMX', 'A menos que los callos de tus manos sean tan duros como tu cabeza, ¡no malgastes el aliento!', 'A menos que los callos de tus manos sean tan duros como tu cabeza, ¡no malgastes el aliento!', 28153),
(147506, 'esMX', 'Donde hay humo, hay fuego. Y donde hay fuego, ¡hay un Hierro Negro listo para darte una paliza!', 'Donde hay humo, hay fuego. Y donde hay fuego, ¡hay un Hierro Negro listo para darte una paliza!', 28153),
(147505, 'esMX', '¡La Montaña Roca Negra no es lo único que está por hacer erupción!', '¡La Montaña Roca Negra no es lo único que está por hacer erupción!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(147504, 'esMX', 'Tengo una política para la tierra calcinada. Si me sigues presionando, ¡sabrás qué se siente ser tierra!', 'Tengo una política para la tierra calcinada. Si me sigues presionando, ¡sabrás qué se siente ser tierra!', 28153),
