(147499, 'esMX', 'Nunca has visto artículos como estos.', 'Nunca has visto artículos como estos.', 28153),
(147498, 'esMX', 'Ofrezco maravillas de zonas profundas.', 'Ofrezco maravillas de zonas profundas.', 28153),
(147497, 'esMX', '¡Que las mareas me lleven, olvidé mi caña!', '¡Que las mareas me lleven, olvidé mi caña!', 28153),
(147496, 'esMX', '¡Entonces me di cuenta de que había olvidado mi caña de pescar! Si quieres mi opinión, un pescador no vale nada sin su caña de pescar.', '¡Entonces me di cuenta de que había olvidado mi caña de pescar! Si quieres mi opinión, un pescador no vale nada sin su caña de pescar.', 28153),
(147495, 'esMX', 'Habla de una vez. Estoy trabajando.', 'Habla de una vez. Estoy trabajando.', 28153),
(147494, 'esMX', 'Protegemos lo que nos pertenece.', 'Protegemos lo que nos pertenece.', 28153),
(147493, 'esMX', 'No me gusta la cháchara.', 'No me gusta la cháchara.', 28153),
(147492, 'esMX', 'Vamos, di lo que tengas que decir.', 'Vamos, di lo que tengas que decir.', 28153),
(147491, 'esMX', 'Prefiero pelear que hablar.', 'Prefiero pelear que hablar.', 28153),
(147490, 'esMX', '¿Qué puedo hacer por ti?', '¿Qué puedo hacer por ti?', 28153),
(147489, 'esMX', '¿Viniste a ayudar? Toma un arma y demuéstralo.', '¿Viniste a ayudar? Toma un arma y demuéstralo.', 28153),
(147488, 'esMX', 'Mira dónde pisas.', 'Mira dónde pisas.', 28153),
