(147474, 'esMX', 'Obedece las órdenes de la reina Moira.', 'Obedece las órdenes de la reina Moira.', 28153),
(147473, 'esMX', 'Es un orgullo servir a la Alianza.', 'Es un orgullo servir a la Alianza.', 28153),
(147472, 'esMX', 'Resistimos con la Alianza.', 'Resistimos con la Alianza.', 28153),
(147471, 'esMX', 'Sí, lo recuerdo perfectamente. Era vísperas de Generosidad del Peregrino y estaba pescando el platillo principal para el banquete.', 'Sí, lo recuerdo perfectamente. Era vísperas de Generosidad del Peregrino y estaba pescando el platillo principal para el banquete.', 28153),
(147470, 'esMX', 'Que las profundidades te otorguen salud.', 'Que las profundidades te otorguen salud.', 28153),
(147469, 'esMX', 'Tu compra te resultará muy útil.', 'Tu compra te resultará muy útil.', 28153),
