(145227, 'esMX', '', 'Mm. Te debo una.', 28153),
(145226, 'esMX', '', '¡Por el Yunquenegro!', 28153),
(145225, 'esMX', '', 'Como... ¡DIEZ pájaros!', 28153),
(145224, 'esMX', '', '¿Eso es lo mejor que tienes?', 28153),
(145222, 'esMX', '', '¡Te haré pedazos!', 28153),
(145221, 'esMX', '', 'Me pregunto cuántos pájaros viven en ese árbol. ¡Debe haber muchísimos!', 28153),
(145220, 'esMX', 'Reh\'póndeme esto.\n\nSoy alta cuando soy joven y pequeña cuando soy vieja. ¿Qué soy?', '', 28153),
(145219, 'esMX', '', 'Fue un placer.', 28153),
(145218, 'esMX', '', '¡Mira, $Gamigo:amiga;! ¡Estamos debajo de un árbol gigante!', 28153),
(145217, 'esMX', '', 'Me alegra ayudar.', 28153),
(145216, 'esMX', '', '¡Ja! No hay de qué.', 28153),
(145215, 'esMX', 'Juguemoh\'.', 'Juguemoh\'.', 28153),
(145214, 'esMX', '¿Estás $Glih\'to:lih\'ta; para poner a prueba tu mente?', '', 28153),
(145213, 'esMX', '', '¿Puedo tener uno como mascota?', 28153),
(145212, 'esMX', '', 'Pero para pájaros lagarto.', 28153),
(145211, 'esMX', '', 'Qué torre más alta. Es como... ¡una pajarera gigante!', 28153),
(145210, 'esMX', '', 'Ey, ¿qué son esas cosas que vuelan? ¡Son muy bonitas!', 28153),
(145209, 'esMX', '', 'Ahora que lo pienso... ¿acaso vives en algún lado?', 28153),
(145208, 'esMX', '', '¿Vives aquí?', 28153),
(145207, 'esMX', '', '¿Cómo es posible?', 28153),
(145206, 'esMX', '', 'Guau... ¡una ciudad que vuela! ¡¿De verdad?!', 28153),
(145205, 'esMX', '', '¿Quieres jugar a las princesas conmigo?', 28153),
(145204, 'esMX', '', '¿Sabes quién vive ahí? Seguramente es una princesa.', 28153),
(145203, 'esMX', '', '¡Guau! ¡Pero qué casa más preciosa!', 28153),
(145202, 'esMX', '', '¡Qué asco!', 28153),
(145201, 'esMX', '', '¿Insectos? Apuesto que sí. ¡Puaj! ¡Odio los insectos!', 28153),
(145200, 'esMX', '', '¿Qué crees que querían alejar?', 28153),
(145199, 'esMX', '', '¡Guau! ¡Jamás había visto un muro tan grande!', 28153),
(145197, 'esMX', '', 'Uuna te abraza.', 28153),
(145196, 'esMX', '¡Tú no llevarte bota!', '', 28153),
(145195, 'esMX', '', '¡Bien, $Gamigo:amiga;, salgamos de aquí! ¡Tenemos muchos lugares que explorar!', 28153),
(145194, 'esMX', '', 'Dile a mamá y a papá que los extraño, y... ¡y que pronto nos veremos!', 28153),
(145193, 'esMX', '', '¡$GAmigo:Amiga;! ¡La Luz dice que puedo quedarme! ¡Yupi!', 28153),
(145192, 'esMX', '', '¿Puedo quedarme con mi $Gamigo:amiga;? ¿Solo un ratito más?', 28153),
(145191, 'esMX', '', 'Hay tantas cosas que no pude hacer. Tantos lugares que no pude visitar...', 28153),
(145190, 'esMX', '', 'Un momento...', 28153),
(145189, 'esMX', '', '¡Mamá! ¡Papá! ¡Me están esperando!', 28153),
(145188, 'esMX', '', 'La luz... me dice que la siga...', 28153),
(145187, 'esMX', '', 'Qué... ¿qué sucede?', 28153),
(145186, 'esMX', '', '¡Ah, $Gamigo:amiga;! ¡Lo logramos! ¡Los vencimos!', 28153),
(145185, 'esMX', '', '¡La oscuridad ha desparecido! ¡Puedo ver!', 28153),
(145184, 'esMX', '', '¡Pagará\' por lo que ha\' hecho!', 28153),
(145183, 'esMX', '$GMaldito:Maldita;. ¡$GMaldito:Maldita;! Aún no había terminado...', '', 28153),
(145182, 'esMX', '¡Tu muerte complacerá a la Reina alma en pena!', '', 28153),
(145181, 'esMX', '¡Escoria de la Alianza! ¡Le llevaré tu cabeza a la Dama oscura!', '', 28153),
(145180, 'esMX', '', '¡Te cortaré la garganta, $n!', 28153),
(145179, 'esMX', 'Oyes un ruido frenético de pezuñas a la distancia. Algo se acerca.', 'Oyes un ruido frenético de pezuñas a la distancia. Algo se acerca.', 28153),
(145178, 'esMX', '', '¿Cómo te atreve\' a interrumpirme? ¡Pagará\' con tu vida, $n!', 28153),
(145177, 'esMX', '', 'Te he eh\'tado observando, $n.', 28153),
(145176, 'esMX', '¡Está\' $Gfrito:frita;, al igual que tu asqueroso rey! ¡Por la Horda!', '', 28153),
(145175, 'esMX', 'Sientes olor a ozono a medida que el aire comienza a crepitar.', 'Sientes olor a ozono a medida que el aire comienza a crepitar.', 28153),
(145173, 'esMX', '', 'Ere\' audaz, pero no necesito mi magia para derrotarte.', 28153),
(145172, 'esMX', 'Estoy listo. Que comience el ritual.', 'Estoy lista. Que comience el ritual.', 28153),
(145171, 'esMX', 'Oigo los gritos del mundo bajo mis pies. ¡Azeroth tiembla de dolor! Debo encontrar una forma de calmar su sufrimiento...', '', 28153),
