(145169, 'esMX', '', 'Por fin te he encontrado, $n.', 28153),
(145168, 'esMX', '¡Te aplastaré el cráneo!', '', 28153),
(145167, 'esMX', '¡Te arrancaré la carne de los huesos!', '', 28153),
(145166, 'esMX', 'Pisaré tu tumba por toda la eternidad.', '', 28153),
(145165, 'esMX', 'Me han quitado toda la esperanza.', '', 28153),
(145164, 'esMX', 'Rayos. No de nuevo.', '', 28153),
(145163, 'esMX', 'Sufrirás por lo que me has hecho.', '', 28153),
(145162, 'esMX', 'Te drenaré la fuerza vital.', '', 28153),
(145161, 'esMX', 'Me encanta el sonido del choque de espadas y el aroma del miedo.', '', 28153),
(145160, 'esMX', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Eres objetivo de |cFFF00000|Hspell:260953|h[Mirada férrea]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Estás |cFFF00000|Hspell:257459|h[Engarfiado]|h|r!', 28153),
(145159, 'esMX', '', '¡YA NO VOLVERÉ A SENTIR MIEDO!', 28153),
(145158, 'esMX', '', '¡Mi luz es súper fuerte!', 28153),
(145157, 'esMX', 'Yo querer irme a casa.', '', 28153),
(145156, 'esMX', '', 'Y mientras la luz me acompañe, ¡la oscuridad nunca vencerá!', 28153),
(145155, 'esMX', '', 'Mamá me dijo que la Luz siempre me encontraría. Tú eres la Luz, $Gamigo:amiga;. ¡Eres mi luz!', 28153),
(145154, 'esMX', '', '¡A... $Gamigo:amiga, estás aquí! ¡No me dejaste sola!', 28153),
(145153, 'esMX', 'No... no...', 'No... no...', 28153),
(145152, 'esMX', 'Dama oscura... Te fallé...', 'Dama oscura... Te fallé...', 28153),
(145151, 'esMX', 'Soy apena\' el primer escalón, colega.', '', 28153),
(145150, 'esMX', 'Por fin...', 'Por fin...', 28153),
(145149, 'esMX', 'Ay... no de nuevo...', 'Oh... no de nuevo...', 28153),
(145148, 'esMX', '¡Por la Dama oscura!', '¡Por la Dama oscura!', 28153),
(145147, 'esMX', '¡Abandona toda esperanza!', '¡Abandona toda esperanza!', 28153),
(145146, 'esMX', '¡Únetenos en la muerte!', '¡Únetenos en la muerte!', 28153),
(145145, 'esMX', '¡Devoraré tus huesos!', '¡Devoraré tus huesos!', 28153),
(145144, 'esMX', '¡Muerte a los vivos!', '¡Muerte a los vivos!', 28153),
(145143, 'esMX', '¡Por Sylvanas!', '¡Por Sylvanas!', 28153),
(145142, 'esMX', '', 'Uuna se cubre con los brazos y rompe en llanto.', 28153),
(145141, 'esMX', '', '¡No, no puedo hacerlo! ¡Quiero ir a casa!', 28153),
(145140, 'esMX', '', '¿$GAmigo:Amiga;? ¿Sigues ahí? ¡Tengo miedo!', 28153),
(145139, 'esMX', '¡Las mala\' vibra\' te seguirán a donde vaya\'!', '', 28153),
(145137, 'esMX', 'Tus ancestro\' te llaman para que los acompañe\'.', '', 28153),
(145136, 'esMX', 'Te maldigo para que sea\' tan $Gfeo:fea; como mis hermano\'.', '', 28153),
(145135, 'esMX', '¿Qué tipo de vudú hace\' tú, colega?', '', 28153),
(145133, 'esMX', 'Que los hueso\' caigan donde tengan que caer.', '', 28153),
(145130, 'esMX', '¡Las espinas ansían sus almas!', '', 28153),
(145129, 'esMX', 'Entonces, se volteó y desapareció en la espesura. Desde entonces, los honestos y los valientes han encontrado protección en el venado blanco del bosque.', 'Entonces, se volteó y desapareció en la espesura. Desde entonces, los honestos y los valientes han encontrado protección en el venado blanco del bosque.', 28153),
(145128, 'esMX', '\"Soy Athair, el corazón de este bosque. Mientras exista, te protegeré a ti y a los tuyos siempre que acudan a mí\", dijo el venado.', '\"Soy Athair, el corazón de este bosque. Mientras exista, te protegeré a ti y a los tuyos siempre que acudan a mí\", dijo el venado.', 28153),
(145127, 'esMX', '\"¡Por la Luz! ¡Puedes hablar!\", exclamó Arom.', '\"¡Por la Luz! ¡Puedes hablar!\", exclamó Arom.', 28153),
(145126, 'esMX', '', '<Sonidos de aplausos>', 28153),
(145125, 'esMX', '', '<Sonido de bostezo>', 28153),
(145124, 'esMX', '', '<Vitoreo corto. ¡Yujuuuu!>', 28153),
(145123, 'esMX', '', '<Vitoreo un poco más largo. ¡Yujuuu!>', 28153),
(145122, 'esMX', '¡El fuego será su perdición!', '', 28153),
(145121, 'esMX', '', '<Sonidos de gallina>', 28153),
(145120, 'esMX', '', '<Sonidos de llanto>', 28153),
(145119, 'esMX', '\"De nada. Simplemente te devolví la amabilidad con la que me trataste\".', '\"De nada. Simplemente te devolví la amabilidad con la que me trataste\".', 28153),
(145118, 'esMX', '', '<Sonidos de llanto. Variante>', 28153),
(145117, 'esMX', '', '<Sonidos de llanto. Variante>', 28153),
(145116, 'esMX', '', '<Sonido de beso>', 28153),
(145115, 'esMX', '\"Gracias, amigo mío\", le dijo Arom al venado.', '\"Gracias, amigo mío\", le dijo Arom al venado.', 28153),
(145114, 'esMX', '', '<Sonidos de risa>', 28153),
(145113, 'esMX', '', '<Risas>', 28153),
(145112, 'esMX', '', '<Sonido de trompetilla. ¡Pfffthblth!>', 28153),
(145111, 'esMX', 'Juntos, Arom y el venado blanco se enfrentaron a los guerreros y los derrotaron.', 'Juntos, Arom y el venado blanco se enfrentaron a los guerreros y los derrotaron.', 28153),
(145110, 'esMX', '', '<Rugido para demostrar dominio>', 28153),
(145109, 'esMX', '', '<Variante de rugido>', 28153),
(145108, 'esMX', '', '<Sonido de suspiro>', 28153),
(145107, 'esMX', '', '<Ruidos de tren. ¡Chucu chu chucu chu!>', 28153),
(145106, 'esMX', '¡El venado blanco regresó y aplastó a algunos de los drust!', '¡El venado blanco regresó y aplastó a algunos de los drust!', 28153),
(145105, 'esMX', '¡Un bramido poderoso se oyó en el bosque!', '¡Un bramido poderoso se oyó en el bosque!', 28153),
(145104, 'esMX', 'Decidido a derribar a cuantos guerreros pudiera, mantuvo su posición.', 'Decidido a derribar a cuantos guerreros pudiera, mantuvo su posición.', 28153),
(145103, 'esMX', '¡Lord Arom se enfrentó solo contra diez guerreros! Luchó con valor y con astucia, ¡pero estaba rodeado y lo superaban en número!', '¡Lord Arom se enfrentó solo contra diez guerreros! Luchó con valor y con astucia, ¡pero estaba rodeado y lo superaban en número!', 28153),
(145102, 'esMX', 'Qué curioso.', 'Qué curioso.', 28153),
(145101, 'esMX', 'Por la noche, ¡los drust atacaron!', 'Por la noche, ¡los drust atacaron!', 28153),
(145100, 'esMX', 'El venado partió dando saltos por el bosque y Arom montó campamento.', 'El venado partió dando saltos por el bosque y Arom montó campamento.', 28153),
(145099, 'esMX', '\"Prefiero que una criatura capaz de derrotar a tantos drust habite mis bosques\", pensó. Así que Lord Arom curó las heridas del venado.', '\"Una criatura capaz de derrotar a tantos drust prefiero que merodee por mis bosques\", pensó. Así que Lord Arom curó las heridas del venado', 28153),
(145098, 'esMX', '¡Cuidado con las espinas!', '', 28153),
(145097, 'esMX', 'Aunque su pueblo necesitaba comida y el venado enorme alimentaría muchas bocas, Lord Arom no quiso atacarlo.', 'Aunque su pueblo necesitaba comida y el venado enorme alimentaría muchas bocas, Lord Arom no quiso atacarlo.', 28153),
(145096, 'esMX', 'El venado había sido atacado por los drust, y aunque había matado a muchos, estaba herido.', 'El venado había sido atacado por los drust, y aunque había matado a muchos, estaba herido.', 28153),
(145095, 'esMX', 'Un día, mientras Lord Arom estaba de cacería en el bosque, se cruzó con un venado blanco enorme.', 'Un día, mientras Lord Arom estaba de cacería en el bosque, se cruzó con un venado blanco enorme.', 28153),
(145094, 'esMX', '¡Sí! ¡Libérennos!', '', 28153),
(145093, 'esMX', 'Nos han... liberado...', '', 28153),
(145092, 'esMX', 'Libres... al fin...', '', 28153),
(145091, 'esMX', 'Muchas... gracias...', '', 28153),
