(144511, 'esMX', 'Los espírituh\' susurran tu nombre.', 'Los eh\'píritus susurran tu nombre.', 28153),
(144510, 'esMX', '¿Qué loa rige tu deh\'tino?', '¿Qué loa rige tu deh\'tino?', 28153),
(144509, 'esMX', '', '¡Muévanse! ¡Por el futuro de Zandalar!', 28153),
(144508, 'esMX', 'Qué presentación más incómoda... si no me apresuro a regresar, Kugro se enfadará.', '', 28153),
(144498, 'esMX', 'Zandalar resistirá.', 'Zandalar resistirá.', 28153),
(144497, 'esMX', 'No te acobardes ante los débiles.', '', 28153),
(144496, 'esMX', 'Abre heridas en tus enemigos.', '', 28153),
(144495, 'esMX', 'Saborea la carne de tus enemigos.', '', 28153),
(144494, 'esMX', '¿Qué quieres, criatura de la Horda?', '', 28153),
(144493, 'esMX', 'Caminas por mis tierras.', '', 28153),
(144492, 'esMX', '¿Eres el depredador... o la presa?', '', 28153),
(144491, 'esMX', '¿Viniste a negociar?', '', 28153),
(144490, 'esMX', 'Cuéntale al mundo sobre mí.', '', 28153),
(144489, 'esMX', 'Que tus enemigos nunca capten tu esencia.', '', 28153),
(144488, 'esMX', 'Fortalece a tu manada.', '', 28153),
(144486, 'esMX', 'Si estás pensando en correr, recuerda que puedo abrir puertas.', '', 28153),
(144484, 'esMX', 'Sigue así y serás mi próxima presa.', '', 28153),
(144481, 'esMX', 'Soy el maestro de formas, trotamanadas y señor de la cacería.', '', 28153),
(144480, 'esMX', '¿Qué te trae ante el señor de la cacería?', '', 28153),
(144479, 'esMX', '¿Viniste a negociar?', '', 28153),
(144478, 'esMX', '', 'Que los vientos estén a tu favor... Y te alejen de mí.', 28153),
(144477, 'esMX', '', 'Recuerda, los cielos son míos.', 28153),
(144476, 'esMX', '', 'Que tus enemigos sientan la furia de los cielos.', 28153),
(144475, 'esMX', '', 'El viento responde a mi voluntad.', 28153),
(144474, 'esMX', '', 'Te elevaré... ¡y te dejaré caer sobre una roca!', 28153),
(144473, 'esMX', '', '¿Quieres invocar mi cólera?', 28153),
(144472, 'esMX', '', 'Pones a prueba mi paciencia, joven.', 28153),
(144471, 'esMX', '', '¿Por qué debo respirar el mismo aire que tú?', 28153),
(144470, 'esMX', '', '¿Qué ocurre?', 28153),
(144469, 'esMX', '', '¿Viniste a negociar?', 28153),
(144468, 'esMX', '', 'Psst, $pr... ¿Está\' $ucansado:cansada; de verte como un sáurido? ¡Con mi mojo te verás como un demosaurio!', 28153),
(144462, 'esMX', '', 'Elige a tu loa con sabiduría.', 28153),
(144461, 'esMX', '', 'Que siempre encuentres las huellas de tus enemigo\'.', 28153),
(144460, 'esMX', '', 'Por la manada.', 28153),
(144459, 'esMX', '', 'Nunca domestiques tu beh\'tia interior.', 28153),
(144458, 'esMX', '', 'Por el lado más beh\'tia de la vida.', 28153),
(144457, 'esMX', '', 'Quédate cerca, quizás te necesite para má\' de eso luego.', 28153),
(144456, 'esMX', '', 'Yyyy me cansé.', 28153),
(144455, 'esMX', '', 'Así que sigue.', 28153),
(144454, 'esMX', '', 'Si sigues haciendo eso mi eh\'poso se pondrá celoso.', 28153),
(144453, 'esMX', '', '¿Has andado por el lado beh\'tia de la vida?', 28153),
(144452, 'esMX', 'Es hora de tomar cartas en el asunto. ¡No permitiré que arruinen la misión!', '', 28153),
(144451, 'esMX', 'Gracias, $n. Parece que Kugro ha estado ocupado. Entonces... ¿qué hacemos con todos estos pergaminos?', '', 28153),
(144450, 'esMX', '', 'Los loa son fuerte\' aquí.', 28153),
(144449, 'esMX', '', '¿Esa e\' la forma que eh\'cogiste para andar?', 28153),
(144448, 'esMX', '¡No eres mi contacto! ¡Vengan aquí, todos, tenemos carne fresca!', '', 28153),
(144447, 'esMX', '', 'Sirvo a Gonk, maestro de las formas.', 28153),
(144446, 'esMX', '<Entregar los pergaminos a Itokka.>', '<Entregar los pergaminos a Itokka.>', 28153),
(144445, 'esMX', '', 'Ojalá Nuu estuviera aquí. Él sabría qué hacer.', 28153),
(144444, 'esMX', '', '¡Ah, hola! ¿Quién eres? Soy Uuna. ¿Quieres ser mi $Gamigo:amiga;? Quizás $Gjuntos:juntas; podamos salir de aquí.', 28153),
(144443, 'esMX', '¡Ey! Tengo justo lo que necesita\'. ¡El resguardo personal de Zul contra sáuridos! ¡Mantén a esos ladrone\' carroñeros bien lejos!', '', 28153),
(144442, 'esMX', '', '¡Brilla demasiado! ¡Demasiado! ¡Ahhh!', 28153),
(144441, 'esMX', 'Que las bendiciones te acompañen, viajer$go:a;. \n\nSuelta tu arma y descansa un rato.\n\nLa guerra puede esperar.', '', 28153),
(144440, 'esMX', '¡Saludo\', pakura\'ai!', '', 28153),
(144439, 'esMX', 'Elige a tu loa con sabiduría.', '', 28153),
(144438, 'esMX', 'Como siempre dice mi loa... Lárgate.', '', 28153),
(144437, 'esMX', 'Que Pa\'ku revele a tus enemigos ante\' de que ello\' te deh\'cubran.', '', 28153),
(144436, 'esMX', 'Que los viento\' de guerra siempre te acompañen.', '', 28153),
(144435, 'esMX', '¡Ah, perfecto! ¡Ese es el lugar!', '', 28153),
(144434, 'esMX', 'Oh, sí, sigue así... solo un poco más a la derecha...', '', 28153),
(144433, 'esMX', 'Si tan solo mi eh\'posa me prestara toda eh\'ta atención.', '', 28153),
(144432, 'esMX', 'Como siempre dice mi loa... ¡No toque\' eso!', '', 28153),
(144431, 'esMX', 'Como siempre dice mi loa... ¡Agáchate! ¡Jajajajaja!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'esMX', '¿Quieres surcar los cielo\' con los sáuridos?', '', 28153),
(144429, 'esMX', 'Los cielo\' son mis ojo\'.', '', 28153),
(144428, 'esMX', 'Sirvo a Pa\'ku, uno de los loa más anciano\'.', '', 28153),
(144427, 'esMX', '', 'Lucho para ayudar a lo\' que no pueden protegerse.', 28153),
(144425, 'esMX', 'Todos jugamo\' un papel, incluso tú.', '', 28153),
(144424, 'esMX', 'He visto muchos evento\' importantes de nueh\'tro tiempo y en todos estabas tú. Qué curioso.', '', 28153),
(144423, 'esMX', 'Se acercan días aciago\'.', '', 28153),
(144422, 'esMX', 'Eh\'to se pondrá feo, colega. Muy feo.', '', 28153),
(144421, 'esMX', 'El imperio trol volverá a ascender. Le he vih\'to.', '', 28153),
(144420, 'esMX', 'Los trols fuimos los primero\' en gobernar eh\'te mundo, y seremos los últimos.', '', 28153),
(144419, 'esMX', 'La fortuna no eh\'tá de tu lado.', '', 28153),
(144418, 'esMX', 'Ya sé lo que dirás, así que apresúrate, por favor.', '', 28153),
(144417, 'esMX', 'He vih\'to cómo termina el mundo y no te guh\'tará.', '', 28153),
(144416, 'esMX', '', 'Zandalar resistirá.', 28153),
(144415, 'esMX', '', 'Venganza para lo\' caídos.', 28153),
(144414, 'esMX', '', 'Que tus vestimentas luzcan las calavera\' de tus enemigos.', 28153),
(144413, 'esMX', '', 'Los tiempo\' cambian y los zandalari deben adaptarse.', 28153),
(144412, 'esMX', '', 'Hay mucho por hacer. Habla rápido.', 28153),
(144411, 'esMX', 'Que tus enemigo\' tiemblen ante tu presencia.', '', 28153),
(144410, 'esMX', 'Zandalar por siempre.', '', 28153),
(144409, 'esMX', 'Que Rezan te conceda fuerza.', '', 28153),
(144408, 'esMX', 'E\' bueno ser el rey.', '', 28153),
(144407, 'esMX', 'Eh\'tás ante el Rey Rastakhan.', '', 28153),
(144406, 'esMX', '$GBienvenido:Bienvenida; a Zuldazar.', '', 28153),
(144405, 'esMX', '¿Eres el depredador... o la presa?', '', 28153),
(144404, 'esMX', '', 'Ojalá pudiera ver mejor. ¡Siempre está tan oscuro aquí!', 28153),
(144403, 'esMX', '', 'Pero somos $Gamigos:amigas;, así que todo va a estar bien.', 28153),
(144402, 'esMX', '', 'Al menos ahora estamos $Gjuntos:juntas;. Simplemente... no sabemos dónde estamos.', 28153),
(144401, 'esMX', '', '¡Ayuda! ¡AYUDA!', 28153),
(144400, 'esMX', '', '¿Quién eres? ¿Puedes ayudarme?', 28153),
(144399, 'esMX', '', '¡Está tan oscuro! ¡No veo nada!', 28153),
(144397, 'esMX', '', 'Todo este asunto con Elisande ha terminado, pero aún queda mucho por hacer en la ciudad.', 28153),
(144396, 'esMX', '', 'Los Natonocturno son verdaderamente libres. Ya no necesitamos la Fuente de la Noche ni su poder.$B$BPodemos forjar nuestro propio destino.', 28153),
(144395, 'esMX', 'Traje algunas muestras para desmentir los rumores infundados de que nuestro vino sabe a pata sucia... ¡digo pura fruta!', '', 28153),
(144394, 'esMX', 'Algunos de nuestros viticultores han abandonado la viticultura para dedicarse a otras formas de botánica.', '', 28153),
(144393, 'esMX', 'Sí, los trols de sangre estaban luchando contra los guardia\' cuando llegamo\'. No esperaban que los atacáramo\' por la retaguardia, jeje.', '', 28153),
(144392, 'esMX', 'Vaya, ese es grande. ¡Necesitaré tu ayuda para derribarlo!', '', 28153),
(144391, 'esMX', 'Si los ves en grupo, ¡arrójales uno de esos bombaespines para darles un poco de su propia medicina!', '', 28153),
(144390, 'esMX', '¡Eso seguro les dolió! ¡Fuera de mi tierra!', '', 28153),
(144389, 'esMX', '¡Ja, les di justo entre los ojos!', '', 28153),
(144388, 'esMX', 'Puedes regresar y decirle a Roz que estoy bien, pero yo jamás dejaré mi granja. Nunca los dejaré.', '', 28153),
(144387, 'esMX', 'Sí, así está bien. Siempre les encantó este lugar...', '', 28153),
(144386, 'esMX', 'Puedes usar el portal de Orgrimmar para reunirte con nuestros aliados de la Horda en su ciudad capital de Kalimdor.', '', 28153),
(144385, 'esMX', '', '¡Rokhan! ¿Eh\'tás bien? Parece que aquí hubo una batalla.', 28153),
(144384, 'esMX', 'Oí que Dalaran tiene un piso entero dedicado al transporte mágico. $B$B¡Imagina las posibilidades!', '', 28153),
(144383, 'esMX', 'Estos portales son increíblemente difíciles de conservar; y, lo que es más importante, ¡nos distraen de otras investigaciones valiosas!$B$BEstoy seguro de que con la telemancia podemos lograr una solución más estable.', '', 28153),
(144382, 'esMX', '¿Quién dice que los goblins no tienen cultura?', '', 28153),
(144381, 'esMX', '¡Incluso tienen uno de nuestros tambores!', '', 28153),
(144380, 'esMX', '...¡y buh\'ca un tambor disponible!', '', 28153),
(144379, 'esMX', '¡$UBienvenido:Bienvenida; al Batero Borracho, $pr! Toma un trago...', '', 28153),
(144378, 'esMX', '¡Argh! ¡Creía que mi plan era infalible, colega!', '', 28153),
(144377, 'esMX', '¡Eh\'túpido! ¡Pagarás por pasar por debajo de mi puente!', '', 28153),
(144376, 'esMX', '¡Ey, colega! Eh\'tás cruzando mi puente, colega. Paga el peaje trol, colega, ¡o pagarás con tu sangre, colega!', '', 28153),
(144375, 'esMX', 'Estoy listo para comenzar la prueba.', 'Estoy lista para comenzar la prueba.', 28153),
(144374, 'esMX', '', '¿Y si les atamos algunos explosivos? Sería graciosísimo... ¡Dinosaurios que explotan!', 28153),
(144373, 'esMX', '', 'Aprecio tu entusiasmo, Shuga. Pero seguro que los zandalari prefieren que sus armas estén encantadas con magias poderosas, no con esas aberraciones grasosas.', 28153),
(144372, 'esMX', 'Qué... ¿en qué nos hemos convertido?', '', 28153),
(144371, 'esMX', '', '¡No! ¡Suéltame! ¡Ayuda, $Gamigo:amiga;! ¡AYUDA!', 28153),
(144370, 'esMX', '', '¡Está oscuro otra vez! ¿A dónde te fuiste? ¡No me dejes!', 28153),
(144369, 'esMX', '', '¡Yo tenía una varita como esa! La perdí hace mucho tiempo.', 28153),
(144368, 'esMX', '', '¡Una corona! ¡Qué bonita!', 28153),
(144367, 'esMX', '', '¡Nuu, Nuu! ¡Creí que jamás volvería a verte! ¿Cómo llegaste hasta aquí?', 28153),
(144366, 'esMX', '', '¡Hay un poco más de luz! Ahora veo... algo.', 28153),
(144365, 'esMX', '', '¿Qué es eso? ¡Una luz en la oscuridad! Brilla mucho...', 28153),
(144364, 'esMX', 'Ella... prometió...', '', 28153),
(144363, 'esMX', '¡Me prometieron que así estaríamos juntos!', '', 28153),
(144362, 'esMX', '', 'Con el apoyo de los loa y la ferocidad de nuestro\' corazones, ¡nos alzaremo\' con la victoria!', 28153),
(144361, 'esMX', '', 'Venceremo\' a los trols de sangre. ¡Nos aseguraremos de que nunca puedan usar esa abominación que intentan invocar contra nosotro\'!', 28153),
(144360, 'esMX', '', 'Nuestros enemigo\' quieren deh\'truir todo lo que adoramos. ¡No debemos permitirles que tengan éxito! ¡El futuro de Zandalar depende de lo que hagamos hoy!', 28153),
(144359, 'esMX', '', 'Soldados... amigos. Hemos atravesado muchas dificultade\', pero nos acercamos al final de nueh\'tra lucha.', 28153),
(144358, 'esMX', 'Muéstrame adónde puedo ir con el ferry.', 'Muéstrame adónde puedo ir con el ferry.', 28153),
(144357, 'esMX', '¿Buscas un ferry?', '¿Buscas un ferry?', 28153),
(144356, 'esMX', '', '¡Qué bueno que llevo mis botas!', 28153),
(144355, 'esMX', 'Me llevaré a alguno\' de los tortollanos, iremo\' a Zul\'jan a pie. Mucha suerte.', '', 28153),
(144354, 'esMX', 'Vivo y muero... ¡por la Horda!', 'Vivo y muero... ¡por la Horda!', 28153),
(144353, 'esMX', '¡Sangre y honor!', '¡Sangre y honor!', 28153),
(144352, 'esMX', '¡Arathi le pertenece a la Horda!', '¡Arathi le pertenece a la Horda!', 28153),
(144351, 'esMX', '¡Síganme!', '¡Síganme!', 28153),
(144350, 'esMX', '¡Muerte a la Alianza!', '¡Muerte a la Alianza!', 28153),
(144349, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(144348, 'esMX', '¡Por aquí! ¡A la batalla!', '¡Por aquí! ¡A la batalla!', 28153),
(144347, 'esMX', '¡Adelante, brutos! ¡Tenemos una guerra que ganar!', '¡Adelante, brutos! ¡Tenemos una guerra que ganar!', 28153),
(144346, 'esMX', '¡Yo soy Gral!', '', 28153),
(144345, 'esMX', 'En el sur encontrarás los restos de mi templo. ¡Reunámonos allí y yo les mostraré a los nagas la furia de un loa tiburón!', '', 28153),
(144344, 'esMX', 'Oh... estaban deliciosos.', '', 28153),
(144343, 'esMX', '¡No hay profundidad suficientemente oscuras para ti!', '', 28153),
(144342, 'esMX', '¡Los nagas no son bienvenidos en Atal\'Gral!', '', 28153),
(144341, 'esMX', 'El delicioso aroma penetrante de la sangre naga hirviendo por la ira... esos dulces bocados tiernos... Yo me encargaré de esto.', '', 28153),
(144340, 'esMX', '', 'Madre, Benjamin me contó todo.\n\nNo podías oírme antes, ¿pero quizás ahora sí? Lo único que quería era una explicación.', 28153),
(144339, 'esMX', '', 'Madre, sé que no estas aquí. Pero si puedes oírme...', 28153),
(144338, 'esMX', 'Quizás yo no sea el mejor administrador, pero mi madre era increíble. Verla caer tan bajo...$b$bEstamos haciendo frente a la situación, $n. Gracias por tu ayuda.', '', 28153),
(144337, 'esMX', '', '¿A dónde vas?', 28153),
(144336, 'esMX', '', 'Por favor, no me dejes.', 28153),
(144335, 'esMX', '¡Nuestra maestra bajo las olas nos guiará a la victoria!', '¡Nuestra maestra bajo las olas nos guiará a la victoria!', 28153),
(144334, 'esMX', '¡Qué bien! Todos volvieron sanos y salvos gracias a... ¡Eh, aquí está $Unuestro héroe:nuestra heroína;!', '', 28153),
(144333, 'esMX', '¿Te quedas o te vas?', '', 28153),
(144332, 'esMX', 'Disculpa. Debo encontrar a mi hermana.', '', 28153),
(144331, 'esMX', 'Cuando mi padre murió, mi madre desapareció. Pero jamás pensé que...', '', 28153),
(144330, 'esMX', 'Ella y mi padre trabajaron durante toda su vida para construir esta empresa y mantenernos a mí hermana y a mí.', '', 28153),
(144329, 'esMX', 'Esa bruja... era mi madre.', '', 28153),
(144328, 'esMX', 'Parece que sabes manejar a las bestias. ¿Qué necesitas?', '', 28153),
(144327, 'esMX', '¿Qué sucede? ¿Perdiste algo?', '', 28153),
(144326, 'esMX', '¡Excelente! Una vez más, desde el principio.', '', 28153),
(144325, 'esMX', 'Es peligroso gastar demasiada energía de una sola vez. Con calma, alumnos.', '', 28153),
(144324, 'esMX', 'El chi concentrado es extremadamente poderoso. El maestro Tau Li te guiará cuando estés $Glisto:lista;.', '', 28153),
(144323, 'esMX', 'Cuando sanas, debes reunir tu fortaleza interior y transmitirla al otro.', '', 28153),
(144322, 'esMX', 'Me alegra no haber tenido que entregarlo TODO.', 'Me alegra no haber tenido que entregarlo TODO.', 28153),
(144321, 'esMX', 'Nuestros hermanos corruptos aún vagan por la naturaleza.', 'Nuestros hermanos corruptos aún vagan por la naturaleza.', 28153),
(144320, 'esMX', '', 'Mi vida... por la Horda.', 28153),
(144319, 'esMX', '', 'Nos veremo\' pronto, colega.', 28153),
(144318, 'esMX', '', '¡Sangre y truenos!', 28153),
(144317, 'esMX', '', 'Te cortaré en dos.', 28153),
(144316, 'esMX', '', 'Mis espadas ansían tu carne.', 28153),
(144315, 'esMX', '', '¡Tu fuerza no se compara a la de un orco!', 28153),
(144314, 'esMX', '', '¡Tus huesos no resistirán ante mis espadas!', 28153),
(144313, 'esMX', '', '¡No retrocedan! ¡Que nadie pase!', 28153),
(144312, 'esMX', 'Graciah\', camarada.', '', 28153),
(144311, 'esMX', 'Si no te recuerdo la próxima vez que nos veamoh\', lo siento.', '', 28153),
(144310, 'esMX', 'Gracias por encargarte de Torok. Se negaba a ver los peligros que se ocultaban tras el poder que quería alcanzar.', 'Gracias por encargarte de Torok. Se negaba a ver los peligros que se ocultaban tras el poder que quería alcanzar.', 28153),
(144309, 'esMX', '<El tauren dormido ronca sonoramente y se da vuelta.>', '<El tauren dormido ronca sonoramente y se da vuelta.>', 28153),
(144308, 'esMX', 'ZZZzzz...', 'ZZZzzz...', 28153),
(144307, 'esMX', 'La seguiré, princesa. Hasta el final.', '', 28153),
(144306, 'esMX', '', 'Eh\'ta es la única forma de salvar a mi gente, Rokhan. Eh\'toy lista para renunciar a todo en pos de su seguridad. ¿Eh\'tás conmigo?', 28153),
(144305, 'esMX', 'Aún no puedo creer que mis hermanos hayan sucumbido ante las energías viles.', 'Aún no puedo creer que mis hermanos hayan sucumbido ante las energías viles.', 28153),
(144304, 'esMX', '', '¡Hijas mías, así deben tratar a los invitado\'!', 28153),
(144303, 'esMX', '', 'La sangre... me vengará...', 28153),
(144302, 'esMX', '', '¡Por las madreguerra!', 28153),
(144301, 'esMX', 'Ahora, concentra tu chi. Empuja la energía fuera de ti.', '', 28153),
(144300, 'esMX', '', '¡Tu esencia será útil fuera de tu cuerpo!', 28153),
(144299, 'esMX', '', 'Será divertido drenarte.', 28153),
(144298, 'esMX', '', '¡Tu sangre nos alimentará!', 28153),
(144297, 'esMX', '', 'Me llevaré tu sangre. ¡El resto, que se pudra!', 28153),
(144296, 'esMX', '', 'Tu sangré manchará mi espada.', 28153),
(144295, 'esMX', '¡Si necesitas un aventón, sabes dónde encontrarme!', '', 28153),
(144294, 'esMX', '', '¡Sangre para los hiervesangre!', 28153),
(144293, 'esMX', '', '¡Haré un arnés fantástico con tu pellejo!', 28153),
(144292, 'esMX', '', 'Los cielos... me llaman.', 28153),
(144291, 'esMX', '', 'Un gran día para una batalla.', 28153),
(144290, 'esMX', '', '¡Los crustájeo\' se darán un festín esta noche!', 28153),
(144289, 'esMX', '¡Resiste! Iré a ver a Satao.', '', 28153),
(144288, 'esMX', 'ENTRADA: El experimento de babas\n\nHe logrado darles vida a las babas. En lugar de disolver materia orgánica, como carne o vegetación, subsisten a base de miel pura. Los desechos abundantes que producen pueden fermentarse en barriles para crear hidromiel deliciosa y de efecto fuerte.\n\nSin embargo, si no se las contiene de forma adecuada, eventualmente las babas buscarán colmenas y las devorarán por completo. Tienen una tendencia a ponerse más agresivas y a crecer de forma incontrolable en el proceso.\n\nNaturalmente, las abejas reaccionan volviéndose más defensivas, y eso dificulta la experimentación. Sin duda tendré que buscar una solución para este problema, porque las abejas no son fáciles de reemplazar.', '', 28153),
(144287, 'esMX', '', 'Pohkiza...', 28153),
(144286, 'esMX', '', 'El dios de la sangre... no... perdona...', 28153),
(144285, 'esMX', '', '¡Jajaja!', 28153),
(144284, 'esMX', '', 'Zuldazar... caerá...', 28153),
(144283, 'esMX', '', '¡Gachaga!', 28153),
(144282, 'esMX', '', 'Mis hermana\'... me... vengarán...', 28153),
(144281, 'esMX', '', '¡Mi sangre... para... G\'huun!', 28153),
(144280, 'esMX', '', '¡G\'huun!', 28153),
(144279, 'esMX', '<Tsanga te dedica un gruñido afectuoso.>', '', 28153),
(144278, 'esMX', 'Vine de las nieblah\' para advertir al pueblo de Zandalar. La azerita les ha otorgado una gran inteligencia a los gorilas. Y con la inteligencia llega la guerra.', '', 28153),
(144277, 'esMX', 'Pohkiza...', '', 28153),
(144276, 'esMX', 'El dios de la sangre... no... perdona...', '', 28153),
(144275, 'esMX', 'Ya... has... perdido... ja, ja, ja.', '', 28153),
(144274, 'esMX', 'Zuldazar... caerá...', '', 28153),
(144273, 'esMX', '¡Gachaga!', '', 28153),
(144272, 'esMX', '¡Mi vida por las madre\'!', '', 28153),
(144271, 'esMX', '¡Mi sangre... para... G\'huun!', '', 28153),
(144270, 'esMX', '¡G\'huun!', '', 28153),
(144269, 'esMX', 'Bien. ¡Muy bien! ¡Otra vez!', '', 28153),
(144268, 'esMX', 'Deja de moverte.', '', 28153),
(144266, 'esMX', '', 'Ayudaré a reforzar las defensas de la aldea. ¡Te veré allí!', 28153),
(144265, 'esMX', '', 'Los hemos destruido. ¡Vamos! Debemos hablar con el alcalde Royston.', 28153),
(144264, 'esMX', '', 'Alleria suspira con el ceño fruncido.', 28153),
(144263, 'esMX', '<Quédate un rato y escucha.>', '<Quédate un rato y escucha.>', 28153),
(144262, 'esMX', '', '<Los ojos de Alleria se dirigen vagamente desde la frialdad de la estatua de piedra hacia la placa grabada con su epitafio.>', 28153),
(144261, 'esMX', '¡Firmes! ¡No retrocedan!', '¡Firmes! ¡No retrocedan!', 28153),
(144260, 'esMX', 'Oyes un gemido en la reh\'piración agonizante de Rohn\'kor.', '', 28153),
(144259, 'esMX', '', '¡Usaré tu estómago para hacerme un sombrero!', 28153),
(144258, 'esMX', '', '¡No! ¡Mi bebé!', 28153),
(144257, 'esMX', '', '¡Ya deja de lastimar a mi criaturita preciosa! ¡No saldrás de eh\'te foso con vida!', 28153),
(144256, 'esMX', '', '¡Quieren matarno\'! ¡Hazlos pedazo\', mi mascota!', 28153),
(144255, 'esMX', 'Bwonsamdi... ¡ten piedad!', 'Bwonsamdi... ¡ten piedad!', 28153),
(144254, 'esMX', 'Zandalar... por siempre...', 'Zandalar... por siempre...', 28153),
(144253, 'esMX', '¡Te devolveremo\' la paz, Urok! ¡Lamento que sea de esta forma!', '', 28153),
(144252, 'esMX', '¿Pero qué...? ¿Qué hacen estas cosa\' dentro de Urok?', '', 28153),
(144251, 'esMX', '¡Estamo\' tan cerca! Solo tengo que conseguir mi equipo...', '', 28153),
(144250, 'esMX', 'Así no...', 'Así no...', 28153),
(144249, 'esMX', 'Bwonsamdi... viene... por mí...', 'Bwonsamdi... viene... por mí...', 28153),
(144248, 'esMX', '¡Resistan! ¡Se acercan más fuerzas hostiles!', '¡Resistan! ¡Se acercan más fuerzas hostiles!', 28153),
(144247, 'esMX', 'Mi... vida... por Zandalar...', 'Mi... vida... por Zandalar...', 28153),
(144245, 'esMX', '¡Di chuka Zandalar!', '¡Di chuka Zandalar!', 28153),
(144243, 'esMX', '¡Mátenlos a todo\'!', '¡Mátenlos a todos!', 28153),
(144242, 'esMX', '¡Por el verdadero Zandalar!', '¡Por el verdadero Zandalar!', 28153),
(144240, 'esMX', '¡Tu sangre bañará nuestrah\' tierras!', '¡Tu sangre bañará nuestras tierra\'!', 28153),
(144239, 'esMX', '¡Te enterraremo\'!', '¡Te enterraremo\'!', 28153),
(144238, 'esMX', '¡Morirás aquí afuera!', '¡Morirás aquí afuera!', 28153),
(144237, 'esMX', '¡Zandalar por siempre!', '¡Zandalar por siempre!', 28153),
(144236, 'esMX', 'La princesa dijo que busquemos a los monstruo\'. ¡Pero todos son monstruo\'!', '', 28153),
(144235, 'esMX', '¿Dónde eh\'tá el sol? No veo nada en este pantano asqueroso.', '', 28153),
(144234, 'esMX', '¡No tiene sentido! Veo un enorme agujero. ¡Y no hay agujero\' en este mapa!', '', 28153),
(144233, 'esMX', '¡Oh! Eh\'to es... es... nada... Qué desilusión.', '', 28153),
(144232, 'esMX', '¡Taz\'okun! ¡Esto puede ser un trozo de azerita!', '', 28153),
(144231, 'esMX', '¿Eh\'to tiene agujas? ¡Guácala! ¿Por qué es pegajoso?', '', 28153),
(144230, 'esMX', 'Oh, qué hermoso. A Talanji le encantaría.', '', 28153),
(144229, 'esMX', '¡Un ballestero aojado te tiene en la mira! ¡Esquívalo!', '', 28153),
(144228, 'esMX', 'Por aquí casi no tengo ocasión de fabricar espadas, aunque me encanta. ¡Lo que odio es el motivo por el que debo hacerlas!', '', 28153),
(144227, 'esMX', 'Ya entiendo por qué le temen a este pantano.', '', 28153),
(144226, 'esMX', 'Qué extraño.', '', 28153),
(144225, 'esMX', 'Creo que jamás conseguiré limpiarme las mano\'. Mis pobres pergaminos.', '', 28153),
(144224, 'esMX', 'Qué roca más extraña... ¡Vaya! ¡Se movió!', '', 28153),
(144223, 'esMX', 'Fah\'cinante.', '', 28153),
(144222, 'esMX', 'Que Gonk guíe tu camino.', 'Que Gonk guíe tu camino.', 28153),
(144221, 'esMX', 'Que Pa\'ku cuide de ti.', 'Que Pa\'ku cuide de ti.', 28153),
(144220, 'esMX', 'Que Rezan te conceda fuerza.', 'Que Rezan te conceda fuerza.', 28153),
(144219, 'esMX', 'Ve con cuidado.', 'Ve con cuidado.', 28153),
(144218, 'esMX', 'Cuidado con lo que haces en nuestra ciudá\'.', 'Cuidado con lo que haces en nuestra ciudá\'.', 28153),
(144217, 'esMX', '¡Zandalar por siempre!', '¡Zandalar por siempre!', 28153),
(144216, 'esMX', '¿Necesitas protección?', '¿Necesitas protección?', 28153),
(144215, 'esMX', 'No encontrarás mejores precio\'.', 'No encontrarás mejores precios.', 28153),
(144214, 'esMX', '¿Qué te trae por aquí?', '¿Qué te trae por aquí?', 28153),
(144213, 'esMX', 'Saludo\'.', 'Saludo\'.', 28153),
(144209, 'esMX', 'Mi deber e\' defender a la familia real.', 'Mi deber e\' defender a la familia real.', 28153),
(144208, 'esMX', 'Defenderemoh\' nuestro reino.', 'Defenderemo\' nuestro reino.', 28153),
(144201, 'esMX', 'Empecemos.', 'Empecemos.', 28153),
(144200, 'esMX', 'Ya eh\'tamos muy cerca, $n.$b$bPuedo invocar las visioneh\' en cuanto me lo pidas.$b$bOh, olvidé mencionarlo. Nueh\'tros enemigos han establecido un campamento justo al otro lado del camino, en la playa. Creo que deberías vigilar los alrededoreh\' para que no nos embosquen.$b$b¡Confío en ti para defenderme si nos vemos en problemas!', '', 28153),
(144199, 'esMX', '¡Sigan así! ¡Expulsaremos a estos bastardos!', '', 28153),
(144198, 'esMX', '¡Se avecina la noche! ¡Mantengan el fuego en las hogueras! ¡Avisen si necesitan más combustible!', '', 28153),
(144197, 'esMX', '¡No dejen pasar a esas bestias! Asesinamos a esa monstruosidad pero perdimos demasiados botes.', '', 28153),
(144196, 'esMX', '¡Si ya han descansado, reemplacen a otra persona en la barricada! ¡Estos malditos no nos ganarán!', '', 28153),
(144195, 'esMX', '¡Necesito voluntarios para ir a ver a Ashton! Quizás él pueda improvisar algunos explosivos para nosotros.', '', 28153),
(144194, 'esMX', '¡Alimenten a los niños primero y luego a los heridos!', '', 28153),
(144193, 'esMX', '¡Los sanadores deben rotar para poder descansar! ¡Eso te incluye también a ti, Kyrstin!', '', 28153),
(144192, 'esMX', '¡Refuercen la barricada! Usen cualquier cosa suelta. Y si no hay nada más, ¡desarmen lo que haga falta!', '', 28153),
(144191, 'esMX', 'El crustajezno emite algunos graznidos extraños y rasca el nenúfar con su pata.', '', 28153),
(144190, 'esMX', 'Esos marineros deberían vigilar a la Horda, y no a nosotros.', 'Esos marineros deberían vigilar a la Horda, y no a nosotros.', 28153),
(144189, 'esMX', 'Cuando antes encontremos lo que buscamos y zarpemos, mejor.', 'Cuando antes encontremos lo que buscamos y zarpemos, mejor.', 28153),
(144188, 'esMX', '¡La Horda se acerca! ¡Cuidado!', '¡La Horda se acerca! ¡Cuidado!', 28153),
(144187, 'esMX', 'Ojalá la Liga de Expedicionarios hubiera asignado más gente a esta expedición.', 'Ojalá la Liga de Expedicionarios hubiera asignado más gente a esta expedición.', 28153),
(144186, 'esMX', 'Si no estuviéramos vigilando a los Hierro Negro, ¿quién sabe qué harían?', 'Si no estuviéramos vigilando a los Hierro Negro, ¿quién sabe qué harían?', 28153),
(144185, 'esMX', '', '¡Y a sus hijos también! Puedo montar una cabina fotográfica y algunos peluches de dinosaurios. Te daría una parte a ti, Jangalar, por supuesto. Sería un 70 para mí y un 30 para ti porque yo fui la de la idea.', 28153),
(144184, 'esMX', 'Hay alguien más que necesita ayuda, si eh\'tás $Udispuesto: dispuesta;.', '', 28153),
(144183, 'esMX', '', 'RESUSE ME: Es hora de usar el inyector para enfurecer a Ben\'jin, seguirlo y ayudarlo a destruir las especies invasoras.', 28153),
(144182, 'esMX', '¡Cuando terminemos de cavar, la Horda estará a punto de llegar a Forjaz!', '¡Cuando terminemos de cavar, la Horda estará a punto de llegar a Forjaz!', 28153),
(144181, 'esMX', 'A los Hierro Negro no les molesta el calor. Pero esta humedad...', 'A los Hierro Negro no les molesta el calor. Pero esta humedad...', 28153),
(144180, 'esMX', 'A la Liga de Expedicionarios le encanta perder el tiempo cavando, sobre todo cuando hay una guerra por ganar.', 'A la Liga de Expedicionarios le encanta perder el tiempo cavando, sobre todo cuando hay una guerra por ganar.', 28153),
(144179, 'esMX', '¿Para esto dejamos nuestra montaña?', '¿Para esto dejamos nuestra montaña?', 28153),
(144178, 'esMX', 'No hace falta hacer un drama.', '', 28153),
(144177, 'esMX', '', 'Las marcas en el suelo... La tierra removida... ¿Cómo lo mostraremos ahora?', 28153),
(144176, 'esMX', '¿Fue tan terrible?', '', 28153),
(144175, 'esMX', '', '¡Espera!', 28153),
(144174, 'esMX', '$gEh\'timado amigo:Eh\'timada amiga;, por favor no tengas miedo de acelerar el procedimiento. Este dispositivo te será útil.', '', 28153),
(144173, 'esMX', '¿Satih\'factorio? A este ritmo, tardaremos un año, Madame.', '', 28153),
(144172, 'esMX', '', '¡Aaahhhh! Perfecto. Muy satisfactorio.', 28153),
(144171, 'esMX', '', 'Trata de no dañar el fósil. Excelente.', 28153),
(144170, 'esMX', '', 'Muy bien. Sigue firme.', 28153),
(144169, 'esMX', '', '¡Cuidado, druidas! ¡Este lugar es una trampa mortal!', 28153),
(144168, 'esMX', '¡Excelente! Esto nos tiene que servir contra esas criaturas monstruosas de madera. ¡Pero cuidado! ¡Que no se derrame!', '', 28153),
(144167, 'esMX', 'Gracias por traerla de vuelta.', '', 28153),
(144166, 'esMX', '', 'RESUSE ME: Aquí está la caja del artilugio inyector. Instálalo por favor.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'esMX', '', '¡Hola, papi!', 28153),
(144164, 'esMX', '¡Penny! ¡Oh, mi niña querida!', '', 28153),
(144163, 'esMX', '¡Su victoria en el aserradero es temporal! ¡Volveremos a conquistarlo!', '', 28153),
(144162, 'esMX', 'Vayamos a buscar a tu papá.', 'Vayamos a buscar a tu papá.', 28153),
(144161, 'esMX', '', '¡Hola! ¿Cómo te llamas?', 28153),
(144160, 'esMX', '¿No ves el peligro al que te enfrentas?', '¿No ves el peligro al que te enfrentas?', 28153),
(144159, 'esMX', '¡No pueden detenernos a todos!', '¡No pueden detenernos a todos!', 28153),
(144158, 'esMX', '¡Nunca nos encontrarán a todos!', '¡Nunca nos encontrarán a todos!', 28153),
(144157, 'esMX', '¡Mi ubicación está en riesgo!', '¡Mi ubicación está en riesgo!', 28153),
(144156, 'esMX', '¡Mira! ¡También tocan nuestros tambores!\n\n¿Quién dijo que los goblins no tenían cultura?', '', 28153),
(144153, 'esMX', 'Ahora debemos agregar unas gotas de savia volátil. ¡No muevas mucho el frasco!', '', 28153),
(144152, 'esMX', 'Agrega un poco de azufre. ¡Cuidado con los gases!', '', 28153),
(144151, 'esMX', 'Ahora agrega con mucho cuidado un poco de calídea.', '', 28153),
(144150, 'esMX', '¡Necesitamos un poco de salpetra para darle más fuerza!', '', 28153),
(144148, 'esMX', 'Krag\'wa hace un gesto de aprobación a tu compañero.', '', 28153),
(144147, 'esMX', 'Krag\'wa y el joven crustajezno parecen comunicarse.', '', 28153),
(144146, 'esMX', '¡No! ¡Nunca regresaré a esa celda! ¡NUNCA!', '', 28153),
(144145, 'esMX', '', '¡Protejan el santuario! ¡No podemos perder el control!', 28153),
(144144, 'esMX', '¡Excelente! Te diré qué debes agregar al caldero. Sigue mis instrucciones o el resultado podría ser... explosivo.', '', 28153),
(144142, 'esMX', '¡Adiós, Penny!', '', 28153),
(144141, 'esMX', '', '¡Sí! ¡Nos vemos!', 28153),
(144140, 'esMX', '', '¡Hola, Joe!', 28153),
(144139, 'esMX', 'Hola, Penny. ¿Vas a ver a tu papá?', '', 28153),
(144138, 'esMX', '¡¿Qué sucede con todos ustedes?!', '', 28153),
(144137, 'esMX', '', '¡Necesito que me sanen!', 28153),
(144136, 'esMX', '', '¡Ríndanse ante los elementos!', 28153),
(144135, 'esMX', '$n, no puedo hacer nada para regresarlo a su estado anterior. Tendrá una mejor vida contigo. Llévalo y mantenlo a salvo.', '', 28153),
(144134, 'esMX', 'Entiendo.', '', 28153),
(144133, 'esMX', 'Acércate, joven.', '', 28153),
(144132, 'esMX', 'Pesadilla...', '', 28153),
(144131, 'esMX', 'La luna... aparece en el cielo...', '', 28153),
(144130, 'esMX', 'Costas distanteh\'...', '', 28153),
(144129, 'esMX', 'No revuelva\'... el caldero...', '', 28153),
(144128, 'esMX', 'Dos trago\' más... y el pimiento más grande que haya...', '', 28153),
(144127, 'esMX', 'La montaña central... se derrumba...', '', 28153),
(144126, 'esMX', 'Diez minutoh\' más...', '', 28153),
(144125, 'esMX', 'Aún no...', '', 28153),
(144124, 'esMX', 'Slinky gruñe en tono de protección.', '', 28153),
(144123, 'esMX', '¡Este es tu fin!', '¡Este es tu fin!', 28153),
(144122, 'esMX', 'Contempla la verdad... de tu perdición...', '', 28153),
(144121, 'esMX', 'No te espera... la victoria... solo... la muerte...', '', 28153),
(144120, 'esMX', 'Insignificante... contra... el ... Vacío...', '', 28153),
(144119, 'esMX', 'No has... ganado... nada...', '', 28153),
(144118, 'esMX', 'Los amos... no descansan...', '', 28153),
(144117, 'esMX', 'El Vacío reclamará... a todos...', '', 28153),
(144116, 'esMX', 'Es inútil... todo caerá... en la oscuridad...', '', 28153),
(144115, 'esMX', '¡Encontrarán tu cuerpo en el puerto!', '¡Encontrarán tu cuerpo en el puerto!', 28153),
(144114, 'esMX', '¡Kul Tiras no necesita a la Alianza!', '¡Kul Tiras no necesita a la Alianza!', 28153),
(144113, 'esMX', '¡Te arrojaré al mar!', '¡Te arrojaré al mar!', 28153),
(144112, 'esMX', '<Cola para la Batalla de Stromgarde>', '<Cola para la Batalla de Stromgarde>', 28153),
(144111, 'esMX', 'En esta mesa, podrás hacer cola para luchar en un frente de batalla.', '', 28153),
(144110, 'esMX', '¡Katherine nos quiere ahogar a todos!', '¡Katherine nos quiere ahogar a todos!', 28153),
(144109, 'esMX', 'Azeroth nos pertenece.', '', 28153),
(144108, 'esMX', '¡El imperio renacerá!', '', 28153),
(144107, 'esMX', '¡Encuéntrenlos!', '', 28153),
(144106, 'esMX', 'Todo estará perdido.', '', 28153),
(144105, 'esMX', 'Todos caerán.', '', 28153),
(144104, 'esMX', 'No hay esperanza... ni vida.', '', 28153),
(144103, 'esMX', 'Todo será consumido.', '', 28153),
(144102, 'esMX', 'Todo será parte de las sombras.', '', 28153),
(144101, 'esMX', 'El Vacío consume todo.', '', 28153),
(144100, 'esMX', '', '¡Druidas de la Zarpa, ATAQUEN!', 28153),
(144099, 'esMX', '<silba>', '', 28153),
(144097, 'esMX', '', 'Entonces pasemos al \"plan B\"...', 28153),
(144096, 'esMX', 'Tengo la información. ¡Ahora solo tenemos que escapar de aquí!', '', 28153),
(144095, 'esMX', '', '¡Nos descubrieron!', 28153),
(144094, 'esMX', 'S-s-s... <estática> se ha detectado sangre de Azeroth. Solicitud: instalación de núcleo de da-da-da-da... <estática> faltante.', '', 28153),
(144093, 'esMX', 'Uff... ¡Eso e\' horrible!', '', 28153),
(144092, 'esMX', 'Jabari, tiene\' la memoria de un elekk y el ingenio de Gonk.', '', 28153),
(144091, 'esMX', 'Sí, claro, las inyecciones de veneno letal son \"picantes\"... Qué comparación...', '', 28153),
(144090, 'esMX', '¡No necesito que me cuides, Jabari! ¡Sobreviví al chili de Haw\'li!', '', 28153),
(144089, 'esMX', 'Ya basta. Pareces una beh\'tia con dolor de garganta.', '', 28153),
(144088, 'esMX', 'Rápido, hermano. Toma esto.', '', 28153),
(144087, 'esMX', '¡Deja de molestar con eso!', '', 28153),
(144086, 'esMX', '¡Precisamente! Ahora veamos qué más...', '', 28153),
(144085, 'esMX', '¡Se nota que has practicado la alquimia antes!', '', 28153),
(144084, 'esMX', '¡Bien hecho! Ahora necesitamos...', '', 28153),
(144082, 'esMX', 'La primera bala esta cargada. Cuando empiece a disparar, sabrán que estamos aquí.$b$b¿Estás $Ulisto:lista;?', '', 28153),
(144081, 'esMX', 'Vendrán hasta aquí. Es solo cuestión de tiempo...', '', 28153),
(144080, 'esMX', '', '¡Muy bien! ¡Vamos!', 28153),
(144079, 'esMX', '', '¡Espera! ¡Tenemos que tomarnos de las manos!', 28153),
(144078, 'esMX', '¡Valiente caerá!', '¡Valiente caerá!', 28153),
(144077, 'esMX', 'Mi muerte no detendrá el cambio en la marea.', 'Mi muerte no detendrá el cambio en la marea.', 28153),
(144076, 'esMX', '¡Te arrepentirás de esto!', '¡Te arrepentirás de esto!', 28153),
(144075, 'esMX', '¡Este no es tu lugar, $gintruso:intrusa;!', '¡Este no es tu lugar, $gintruso:intrusa;!', 28153),
(144074, 'esMX', '¡Boralus nos pertenece!', '¡Boralus nos pertenece!', 28153),
(144073, 'esMX', '', 'Hay muchísimas fuerza\' de Zul entre este lugar y Atal\'Dazar. Tenemo\' que eliminarlas.', 28153),
(144072, 'esMX', 'Elfos...', 'Elfos...', 28153),
(144071, 'esMX', 'El agente rastali eh\'cupe en el suelo.', 'La agente rah\'tali lanza un suspiro.', 28153),
(144070, 'esMX', 'Por supuesto. Es tan primitivo. Muy bien, 3... 2... 1...', '', 28153),
(144069, 'esMX', '', 'Que se vea ese templo grande y feo del fondo.', 28153),
(144068, 'esMX', '', 'Todos nuestros amigos de Lunargenta se pondrán celosos cuando vean esta foto.', 28153),
(144067, 'esMX', 'Con la prueba completa, di el último trazo a mi relato y regresé al reino material.', 'Con la prueba completa, di el último trazo a mi relato y regresé al reino material.', 28153),
(144066, 'esMX', 'Me observó e inspeccionó mi mente. Y me dio los conocimientos para invocarla siempre.', 'Me observó e inspeccionó mi mente. Y me dio los conocimientos para invocarla siempre.', 28153),
(144065, 'esMX', 'Al terminar de formarse, la monstruosidad soltó un grito de enojo.', 'Al terminar de formarse, la monstruosidad soltó un grito de enojo.', 28153),
(144064, 'esMX', 'Al terminar el ritual, vi una criatura que se engendró ante mis ojos.', 'Al terminar el ritual, vi una criatura que se engendró ante mis ojos.', 28153),
(144063, 'esMX', 'Al entrar en el lugar vi cuatro runas en el suelo esparcidas. Comprendí que para esto necesitaba la tinta.', 'Al entrar en el lugar vi cuatro runas en el suelo esparcidas. Comprendí que para esto necesitaba la tinta.', 28153),
(144062, 'esMX', 'Ya con la tinta que necesitaba, me atrajo un confín de los salones y tuve que avanzar.', 'Ya con la tinta que necesitaba, me atrajo un confín de los salones y tuve que avanzar.', 28153),
(144061, 'esMX', 'Un esqueleto en el suelo me hizo pensar en mi propia mortalidad. Me pregunté si otros habían fracasado con anterioridad.', 'Un esqueleto en el suelo me hizo pensar en mi propia mortalidad. Me pregunté si otros habían fracasado con anterioridad.', 28153),
(144060, 'esMX', 'Estos seres viscosos empezaban a ser un verdadero problema.', 'Estos seres viscosos empezaban a ser un verdadero problema.', 28153),
(144059, 'esMX', 'Las babosas eran la clave del acertijo que enfrentaba. Y así fui encontrando lo que necesitaba.', 'Las babosas eran la clave del acertijo que enfrentaba. Y así fui encontrando lo que necesitaba.', 28153),
(144058, 'esMX', 'De alguna forma, supe lo que debía hacer y decidí continuar.', 'De alguna forma, supe lo que debía hacer y decidí continuar.', 28153),
(144057, 'esMX', 'Del púrpura y el negro combinados surge un destripador con sangre vinculado\".', 'Del púrpura y el negro combinados surge un destripador con sangre vinculado\".', 28153),
(144056, 'esMX', '\"La tinta de la pluma y la sangre de las venas se entremezclan y encadenan.', '\"La tinta de la pluma y la sangre de las venas se entremezclan y encadenan.', 28153),
(144055, 'esMX', 'Desperté en una recámara. Una voz en mi mente recitaba un poema.', 'Desperté en una recámara. Una voz en mi mente recitaba un poema.', 28153),
(144054, 'esMX', 'Comienzas a escribir en el libro: \"Cuando mi pluma tocó la hoja, sentí que una fuerza me atraía\".', 'Comienzas a escribir en el libro: \"Cuando mi pluma tocó la hoja, sentí que una fuerza me atraía\".', 28153),
(144053, 'esMX', 'Al recorrer el libro, observas que todas las páginas están en blanco. Vuelves a mirar a Kronah con frustración y te preguntas si conoce el truco para superar esta prueba.', '', 28153),
(144052, 'esMX', 'No puedo esperar a leer sobre los evento\' a los que te has enfrentado.', '', 28153),
(144051, 'esMX', 'Toma una de las pluma\' y comienza a escribir. No te preocupes, el libro hará el resto.', '', 28153),
(144050, 'esMX', 'Es muy simple, cariño. Tiene\' que escribir tu propia historia en el libro.', '', 28153),
(144049, 'esMX', 'Ay, no, ahí viene…', '', 28153),
(144048, 'esMX', 'Me gustaría cambiar algunas de mis púas.', 'Me gustaría cambiar algunas de mis púas.', 28153),
(144047, 'esMX', 'Vaya... Eso no salió como lo planeamos... ¡Hay que intentarlo otra vez!', '', 28153),
(144046, 'esMX', '¡La alquimia es una ciencia exacta! Debes prestar más atención.', '', 28153),
(144045, 'esMX', 'Mmm, eso no salió bien. ¡Tendremos que empezar todo de nuevo!', '', 28153),
(144044, 'esMX', '¡La mezcla se ha encendido! ¡Debemos empezar de nuevo!', '¡La mezcla se ha encendido! ¡Debemos empezar de nuevo!', 28153),
(144043, 'esMX', 'Zul previó este día. ¡Su lucha por cambiar el destino solo sirve como prueba de lo inevitable!', '', 28153),
(144042, 'esMX', 'Zul... jamás dijo... que perdería…', '', 28153),
(144041, 'esMX', '¡Jamás llegarás al precipicio a tiempo!', '', 28153),
(144040, 'esMX', '¡Estoy listo para empezar!', '¡Estoy lista para empezar!', 28153),
(144039, 'esMX', '¡Espera! ¡Me siento mejor! Uggg...', '¡Espera! ¡Me siento mejor! Uggg...', 28153),
(144038, 'esMX', '¡Fui un tonto!', '¡Fui una tonta!', 28153),
(144037, 'esMX', 'Ya no puedo escuchar su canción...', 'Ya no puedo escuchar su canción...', 28153),
(144036, 'esMX', '¡Ella nunca te amará!', '¡Ella nunca te amará!', 28153),
(144035, 'esMX', '¡Noooo! ¡Mi amor!', '¡Noooo! ¡Mi amor!', 28153),
(144034, 'esMX', 'El amor duele.', 'El amor duele.', 28153),
(144033, 'esMX', '¡Valió la pena!', '¡Valió la pena!', 28153),
(144032, 'esMX', 'El dulce dolor de la despedida.', 'El dulce dolor de la despedida.', 28153),
(144031, 'esMX', 'Eh, amor. Mira cómo golpeo a este tipo.', 'Ey, amor. Mira cómo golpeo a este tipo.', 28153),
(144030, 'esMX', '¡¿Estás mirando a mi chica?!', '¡¿Estás mirando a mi chica?!', 28153),
(144029, 'esMX', '¡El amor todo lo puede!', '¡El amor todo lo puede!', 28153),
(144028, 'esMX', '¡Es mía! ¡MÍA!', '¡Es mía! ¡MÍA!', 28153),
(144027, 'esMX', 'Gracias, $Galiado:aliada;. Has salvado a este poblado y me has infundido valor. Alby y Therold: asegúrense de que Puntanzuelo se recupere. Pronto tendrán noticias mías.', '', 28153),
(144026, 'esMX', '¡No la toques!', '¡No la toques!', 28153),
(144025, 'esMX', '¡¿Zul quiere despertar a Dazar?! No me quedaré de brazos cruzados mientras este \"profeta\" profana los huesos del primer rey. Ven, adalid, reunámonos en las puertas que están al sur de este lugar.', '', 28153),
(144024, 'esMX', 'Debo regresar a mi hogar. Es posible que mi tío y sus maresabios en Valle Canto Tormenta tengan más información sobre esta magia oscura.', '', 28153),
(144023, 'esMX', 'Celaoscuro... siempre fue astuto, pero jamás imaginé que se involucraría con una magia como esta, que canalizaría un poder capaz de causarle tanto desorden al mar...', '', 28153),
(144022, 'esMX', '¡Apártate! ¡Ella me quiere a mí!', '¡Apártate! ¡Ella me quiere a mí!', 28153),
(144021, 'esMX', '', '¡Sí! Sus matacielos se desmoronan. ¡Vuelen, mis criaturas! ¡Maten a esos herejes!', 28153),
(144020, 'esMX', 'Puntanzuelo está a salvo, pero aún siento temor. Aunque era un hombre inteligente, Celaoscuro nunca antes tuvo semejante poder.', '', 28153),
(144019, 'esMX', '¡Te protegeré, amor mío!', '¡Te protegeré, amor mío!', 28153),
(144018, 'esMX', '¡La amo tanto!', '¡La amo tanto!', 28153),
(144017, 'esMX', 'LA MANO DEL DESTINO SE HA SACIADO. TE LLEVARÉ A UN LUGAR SEGURO. EL DESTINO PUEDE SER AMABLE.', '', 28153),
(144016, 'esMX', '¡Vete de nuestra ciudá\', $p! ¡Nos condenarás a todos!', '', 28153),
(144015, 'esMX', '¡Abran paso a $p, $Gel bendecido:la bendecida; de lo\' loa!', '', 28153),
(144013, 'esMX', '', 'Augurios bueno\' y malo\'...Enfrentarás desafíos enormes pero lo\' superarás. Los loa no te abandonarán.', 28153),
(144012, 'esMX', '', 'Me temo que estos son malos augurio\'... Habrá conflictos sin fin en tu futuro. Lo lamento.', 28153),
(144011, 'esMX', '', 'Evita las aguas hoy. Son peligrosa\'.', 28153),
(144010, 'esMX', '', '¿Vacío? No... Debes cambiar esto.', 28153),
(144009, 'esMX', '', 'Enfrentarás adversidade\' y traiciones. Elige con cuidado a tus compañeros.', 28153),
(144008, 'esMX', '', 'Hacía mucho, mucho tiempo que no oía este augurio... Debe\' cambiar tu destino.', 28153),
(144007, 'esMX', '', 'No tome\' atajos para alcanzar tu\' metas hoy. Cualquier riesgo o descuido te llevará hacia un final macabro.', 28153),
(144006, 'esMX', '', 'Una advertencia del otro lado. Cuidado.', 28153),
(144005, 'esMX', '', 'Cuidado con la Ciudad de Oro. No vale la pena correr ese riesgo.', 28153),
(144004, 'esMX', '', 'Me temo que debe\' caminar hacia el futuro a ciegas.', 28153),
(144003, 'esMX', '', 'Gral es arrastrado hasta las profundidade\' por una mano invisible.', 28153),
(144002, 'esMX', '', 'El nido de Shadra eh\'tá vacío.', 28153),
(144001, 'esMX', '', 'Torcali duerme.', 28153),
(144000, 'esMX', '', 'Rezan cae a tierra... muerto.', 28153),
(143999, 'esMX', '', 'Bwonsamdi ofrece un trato con una sonrisa de superioridá\'.', 28153),
(143998, 'esMX', '', 'Kra\'gwa se traga un rebaño de cuernoatroces azules.', 28153),
(143997, 'esMX', '', 'Gonk eh\'tá solo y cruza a nado un río de oro.', 28153),
(143996, 'esMX', '', 'Pa\'ku cierra los ojo\' en la oscuridad.', 28153),
(143995, 'esMX', '', 'No hay peor augurio que eh\'te. Ten mucho cuidado.', 28153),
(143994, 'esMX', '', 'Un augurio oscuro para todo\' nosotros... ¿Qué has traído a nuestra\' costas?', 28153),
(143993, 'esMX', '', 'Eh\'tás desperdiciando tu potencial. Aprovecha las oportunidades o caerás en el olvido eterno.', 28153),
(143992, 'esMX', '', 'La división entre ustede\' y sus aliado\' es una amenaza para todos. Zandalar debe unirse.', 28153),
(143991, 'esMX', '', 'Una augurio poco grato, pero puede\' superarlo con fuerza y determinación.', 28153),
(143990, 'esMX', '', 'Los líderes que se dividen no son lídere\'. Debes trabajar con tus rivale\' o sufrir las consecuencias.', 28153),
(143989, 'esMX', '', 'Se alza una oscurida\' que consumirá hasta al más fuerte de nosotro\'. Y a ti también.', 28153),
(143988, 'esMX', '', 'Un augurio oscuro para todo\' nosotros...', 28153),
(143987, 'esMX', '', 'La muerte de un nuevo amigo.', 28153),
(143986, 'esMX', '', 'Un atardecer en los pantanos oscuroh\' de Nazmir.', 28153),
(143985, 'esMX', '', 'Una vasija con grieta\' que dejan salir el vino.', 28153),
(143984, 'esMX', '', 'Dos sacerdote\' asesinándose entre sí.', 28153),
(143983, 'esMX', '', 'Una nave humana que llega a nueh\'tras costas...', 28153),
(143982, 'esMX', '', 'Un trono quebrado de fuego y hielo...', 28153),
(143981, 'esMX', '', 'Un brutosaurio que se ahoga en sangre.', 28153),
(143980, 'esMX', '', 'Un río de sangre, con cadávere\' flotando...', 28153),
(143979, 'esMX', '¡Vamos, Uñitas! ¡Baja!', '¡Vamos, Uñitas! ¡Baja!', 28153),
(143978, 'esMX', '¡Sí! ¡Gracias!', '¡Sí! ¡Gracias!', 28153),
(143977, 'esMX', 'Vaya. ¡Eso e\'tá mejor!', '', 28153),
(143976, 'esMX', 'Les dije que se fueran, pero insistían en ver uno más... Me salvé por un pelo... Y eso gracia\' a ti. De lo contrario, no lo hubiera logrado.', '', 28153),
(143975, 'esMX', '', '¡Habla a través de tu oráculo, Zetoa!', 28153),
(143974, 'esMX', '', '¡Habla a través de tu oráculo, Iluna!', 28153),
(143973, 'esMX', '', 'Eh\'tamos listos. Preséntate en mis oráculos y revélano\' el futuro.', 28153),
(143972, 'esMX', '', 'Espíritu\' de los muertos, espíritu\' de los loa, espíritu\' de los perdidos y confundidos, ¡oigan mi voz!', 28153),
(143971, 'esMX', '¡Regresaré a la línea de defensa!', '¡Regresaré a la línea de defensa!', 28153),
(143970, 'esMX', '¡No podía moverme!', '¡No podía moverme!', 28153),
(143969, 'esMX', '¡Creí que me arrastrarían al bosque!', '¡Creí que me arrastrarían al bosque!', 28153),
(143968, 'esMX', '¡Ya han llevado gente a los bosques!', '¡Ya han llevado gente a los bosques!', 28153),
(143967, 'esMX', '¡Volveré a la barricada!', '¡Volveré a la barricada!', 28153),
(143966, 'esMX', '', 'Estos son buenos augurio\' para ti... ¡Actúa con astucia!', 28153),
(143965, 'esMX', '¡Creí que sería el fin!', '¡Creí que sería el fin!', 28153),
(143964, 'esMX', '¡Gracias!', '¡Gracias!', 28153),
(143963, 'esMX', '', 'Una eh\'tampida...', 28153),
(143962, 'esMX', '', 'Un augurio de felicidad. No deje\' que la ansiedad te desborde. La alegría y el buen humor te guiarán hasta el éxito.', 28153),
(143961, 'esMX', '¡La peste avanza!', '', 28153),
(143960, 'esMX', 'Todo... decae...', '', 28153),
(143959, 'esMX', '', 'La bendición má\' común de Shadra, con un agregado insólito. Sigue siendo algo bueno, pero no lo comprendo bien.', 28153),
(143958, 'esMX', '', 'La bendición de lo\' defensores... Salvarás muchas vida\', quizás a costa de la tuya.', 28153),
(143957, 'esMX', '', 'El loa de reyes e\' un augurio poco común. Fuerte y poderoso. Destruirás a los adversario\' del rey.', 28153),
(143956, 'esMX', '', 'Un buen augurio de vida larga y muerte serena.', 28153),
(143955, 'esMX', '¡Debo alimentarme!', '', 28153),
(143954, 'esMX', '¡Marchítense!', '', 28153),
(143953, 'esMX', '¡La corrupción florece!', '', 28153),
(143952, 'esMX', '', 'Si esa isla no e\' tu tierra natal, eh\'te es un buen augurio.', 28153),
(143951, 'esMX', '¡Crezcan!', '', 28153),
(143950, 'esMX', '', 'Siempre tendrás aliado\' en la lucha. Gonk no te abandonará cuando lo necesite\'.', 28153),
(143949, 'esMX', '', 'Pa\'ku guiará tu camino y lo mantendrá libre de enemigo\'...', 28153),
(143948, 'esMX', 'Qué suelo más fértil.', '', 28153),
(143947, 'esMX', '', 'Gral salta por encima de la flota del rey...', 28153),
(143946, 'esMX', '', 'Los huevoh\' de Shadra eclosionan. Mile\' de ojos se adelantan...', 28153),
(143945, 'esMX', '', 'Torcali se alza en lo alto de una montaña, solo...', 28153),
(143944, 'esMX', '', 'Rezan golpea contra el suelo y los trol\' de sangre salen corriendo...', 28153),
(143943, 'esMX', '', 'Bwonsamdi aparta la mirada...', 28153),
(143942, 'esMX', '', 'Krah\'gwa se traga una ih\'la...', 28153),
(143941, 'esMX', '¡Peste!', '', 28153),
(143940, 'esMX', '', 'Gonk corre junto a su manada...', 28153),
(143939, 'esMX', '¡A cosechar!', '', 28153),
(143938, 'esMX', '¡La infección debe propagarse!', '', 28153),
(143937, 'esMX', '', 'Casi siempre e\' un augurio bueno, pero eso dependerá de quien te acompañe...', 28153),
(143936, 'esMX', '', 'Un buen augurio para todo\' nosotros. Tu presencia será bienvenida en Zandalar.', 28153),
(143935, 'esMX', '', 'A pesar de lo que mucho\' creen, aún no has alcanzado todo tu potencial. Tu poder crecerá y serás mucho más $Upoderoso:poderosa; de lo que imagina\'.', 28153),
(143934, 'esMX', '', 'Un augurio... asombroso para $Gun forah\'tero:una forastera;. ¿Qué significa?', 28153),
(143933, 'esMX', '', '¡Un augurio de mucho poder! Te anticipa cosa\' buenas...', 28153),
(143932, 'esMX', '', 'Un buen augurio de expansión y crecimiento para nuestro pueblo. Y decidieron que lo reciba\' tú...', 28153),
(143931, 'esMX', '', 'Un buen augurio de prosperidad y legado.', 28153),
(143930, 'esMX', '', 'Un buen augurio de fuerza, poder y éxito.', 28153),
(143929, 'esMX', '', 'La resurrección de un viejo amigo...', 28153),
(143928, 'esMX', '', 'El sol que nace sobre las agua\' doradas...', 28153),
(143927, 'esMX', '', 'Un huevo enorme, que se sacude pero no se rompe...', 28153),
(143926, 'esMX', '', 'Toda\' las tribus de trols, reunidas bajo el estandarte zandalari...', 28153),
(143925, 'esMX', '', 'La cabeza amputada de un elfo...', 28153),
(143924, 'esMX', '', 'Aguas ancestrale\', inmutables durante generaciones...', 28153),
(143923, 'esMX', '', 'Máh\'caras de oro...', 28153),
(143922, 'esMX', '', 'La sombra de Pa\'ku cruza un camino de piedra...', 28153),
(143921, 'esMX', '', 'Muy bien, veamo\' qué te dicen los espíritus...', 28153),
(143920, 'esMX', '', '¿Estás $Useguro:segura; de querer saber, $p?\n\nNo siempre se vislumbran grande\' hazañas y finale\' felices...', 28153),
(143919, 'esMX', 'No siento temor. Dime qué ves en mi futuro.', 'No siento temor. Dime qué ves en mi futuro.', 28153),
(143918, 'esMX', '¿Qué ves en mi futuro?', '¿Qué ves en mi futuro?', 28153),
(143917, 'esMX', '', 'Escuchen mi voz, eh\'píritus anciano\' y perdidos. Preséntense en mis oráculo\' y revelen el futuro.', 28153),
(143916, 'esMX', 'No importa. Estamos en todas partes... bajo tus pies.', '', 28153),
(143915, 'esMX', 'Eres débil... Nuestra tribu... es fuerte.', 'Eres débil... Nuestra tribu... es fuerte.', 28153),
(143914, 'esMX', '', '$UBienvenido:Bienvenida; al Salón de los Espíritus Perdidos, $p.\n\nE\' tarde, pensé que nunca llegaría\'.\n\nDime, ¿qué puede hacer por ti Madame Konawla?', 28153),
(143913, 'esMX', 'Muero con honor...', 'Muero con honor...', 28153),
(143912, 'esMX', 'Nuestras espinas... cubrirán la tierra...', 'Nuestras espinas... cubrirán la tierra...', 28153),
(143911, 'esMX', 'Los zarzalomo... se fortalecerán...', 'Los zarzalomo... se fortalecerán...', 28153),
(143910, 'esMX', 'Mi camino... termina.', 'Mi camino... termina.', 28153),
(143909, 'esMX', 'Tu muerte me traerá gloria.', 'Tu muerte me traerá gloria.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'esMX', 'Tu sangre regará las espinas.', 'Tu sangre regará las espinas.', 28153),
(143907, 'esMX', '¡Retroceder nunca, rendirse jamás!', '¡No cederemos, no nos rendiremos!', 28153),
(143906, 'esMX', '¿Por qué está en blanco el Compendio de sangre?', '¿Por qué está en blanco el Compendio de sangre?', 28153),
(143905, 'esMX', 'Serás alimento para nuestros jabalíes.', 'Serás alimento para nuestros jabalíes.', 28153),
(143904, 'esMX', '¡No puedes detenernos!', '¡No puedes detenernos!', 28153),
(143903, 'esMX', '¡Esta tierra es nuestra!', '¡Esta tierra es nuestra!', 28153),
(143902, 'esMX', 'Comienza a escribir en el libro.', 'Comienza a escribir en el libro.', 28153),
(143901, 'esMX', 'Hojea todo el libro.', 'Hojea todo el libro.', 28153),
(143900, 'esMX', '¡Uñitaaaas! ¿Sigues ahí arriba? ¡Maúlla dos veces si puedes oírme!', '¡Uñitaaaas! ¿Sigues ahí arriba? ¡Maúlla dos veces si puedes oírme!', 28153),
(143899, 'esMX', 'Las siguientes páginas también parecen estar en blanco.', '', 28153),
(143898, 'esMX', '¡Te bajaremos, Uñitas! ¡Solo pórtate bien!', '¡Te bajaremos, Uñitas! ¡Solo pórtate bien!', 28153),
(143897, 'esMX', '¡Todo estará bien, Uñitas! ¡Espera ahí!', '¡Todo estará bien, Uñitas! ¡Espera ahí!', 28153),
(143896, 'esMX', 'Pasa algunas páginas más.', 'Pasa algunas páginas más.', 28153),
(143895, 'esMX', 'Las páginas del libro parecen estar en blanco.', '', 28153),
(143894, 'esMX', 'Mrrrriauuuuu...', '', 28153),
(143893, 'esMX', '¡Aguanta, Uñitas! ¡La ayuda está en camino!', '¡Aguanta, Uñitas! ¡La ayuda está en camino!', 28153),
(143892, 'esMX', '¡Baja de una vez, Uñitas! ¡No es seguro ahí arriba!', '¡Baja de una vez, Uñitas! ¡No es seguro ahí arriba!', 28153),
(143891, 'esMX', '¡Salta, Uñitas! ¡Te atraparé!', '¡Salta, Uñitas! ¡Te atraparé!', 28153),
(143890, 'esMX', '¡Uñitaaaaaaaas! ¡¡Bajaaaaa!!', '¡Uñitaaaaaaaas! ¡¡Bajaaaaa!!', 28153),
(143889, 'esMX', '', '¡Serás alimento para mis mascota\', $r!', 28153),
(143888, 'esMX', 'Adalid. Por aquí.', '', 28153),
(143887, 'esMX', '¡Por aquí!', '', 28153),
(143886, 'esMX', '¡Cuidado!', '', 28153),
(143885, 'esMX', 'Por aquí.', '', 28153),
(143884, 'esMX', 'Por aquí.', '', 28153),
(143883, 'esMX', '¡Cuidado!', '', 28153),
(143882, 'esMX', '¡Por aquí!', '', 28153),
(143881, 'esMX', 'Tú. Por aquí.', '', 28153),
(143879, 'esMX', '¡Purifícate!', '', 28153),
(143876, 'esMX', 'Listo.', '', 28153),
(143875, 'esMX', '¡Sangre! ¡Sangre! ¡Sangre!', '', 28153),
(143874, 'esMX', '¡Zuldazar caerá!', '', 28153),
(143873, 'esMX', '¡Carne fresca!', '', 28153),
(143872, 'esMX', '¡Quiero tu sangre!', '', 28153),
(143871, 'esMX', '¡Tus huesos nos servirán!', '', 28153),
(143870, 'esMX', '¡Tu sangre para G\'huun! ', '', 28153),
(143869, 'esMX', '¡No puedes ocultarte del dió\' de la sangre!', '', 28153),
(143868, 'esMX', '¡Guzincha!', '', 28153),
(143867, 'esMX', '¡Kachago!', '', 28153),
(143865, 'esMX', '¿No has leído la letra chica?\n\nNo hay reembolsos, sin excepciones. Aunque llores.\n\nYa sé cómo levantarte el ánimo... ¡con el Vueloalegre de Piesligeros!', '', 28153),
(143864, 'esMX', '¡Un Vueloalegre de Piesligeros, por favor!', '¡Un Vueloalegre de Piesligeros, por favor!', 28153),
(143863, 'esMX', 'Quiero un reembolso.', 'Quiero un reembolso.', 28153),
(143862, 'esMX', '¡$GBienvenido:Bienvenida; otra vez, $p!\n\nVeo que has disfrutado del Vueloalegre de Piesligeros.\n\nComo miembro pleno, tienes acceso a una cantidad ilimitada de caídas desde lo alto de este divertido zigurat. ¡Avísame cuando quieras más!\n\nNo hay reembolsos, de ninguna manera.', '', 28153),
(143861, 'esMX', '¡Participa en el Vueloalegre de Piesligeros!\n\nPor una mínima tarifa, tendrás acceso a suaves caídas ilimitadas desde lo alto de este zigurat. ¡Te garantizamos tu supervivencia!\n\nNo hay reembolsos.', '', 28153),
(143860, 'esMX', 'Los vientos aquí son más fuertes que en Altamontaña. Nuestra decisión de unirnos a la Horda ya se ve recompensada.', '', 28153),
(143859, 'esMX', 'Regresa a la tormenta y ve en paz. Fluye en el santuario para que compartamos tu fuerza.', '', 28153),
(143858, 'esMX', '', '¡Qué ciudad maravillosa! ¡Es tan divertido explorar el mundo!', 28153),
(143857, 'esMX', 'Oye nuestro llamado, hermano caído. Tus obras malignas están perdonadas.', '', 28153),
(143856, 'esMX', 'Cuando estés $ulisto:lista;, libera las almas de la campana.', '', 28153),
(143855, 'esMX', 'Rosalina, lo siento, pero tienes que esperar. Hoy tenemos asuntos más urgentes que la cacería.', '', 28153),
(143854, 'esMX', '', '¡Therold! Ya deja de perder el tiempo. ¡Necesitamos tu bendición para salir de caza!', 28153),
(143853, 'esMX', '¡Vuelve pronto, $p!', '', 28153),
(143852, 'esMX', '¡Diez puntos por escupir a cualquier trol de sangre que encuentres!', '', 28153),
(143851, 'esMX', '¡Vueloalegre de Piesligeros! ¡Cuéntales a tus amigos!', '', 28153),
(143850, 'esMX', 'Me alegra volver a verte, $p. ¡Buena caída!', '', 28153),
(143849, 'esMX', '¡Intenta caer sobre el brutosaurio!', '', 28153),
(143848, 'esMX', '¡Intenta caer sobre una cascada!', '', 28153),
(143847, 'esMX', '¡Cuidado con los pterrordáctilos!', '', 28153),
(143846, 'esMX', 'Buen viaje, $p.', '', 28153),
(143845, 'esMX', '¡Aaaaaaaaaugh!', '', 28153),
(143844, 'esMX', 'Por la Alianza.', '', 28153),
(143843, 'esMX', '¡Por la Horda!', '', 28153),
(143842, 'esMX', 'Stromgarde ha caído. Ríndete ahora, Rogers, si quiereh\' salvar tu pellejo.', '', 28153),
(143841, 'esMX', '¡Sí! ¡Mi martillo y yo!', '', 28153),
(143840, 'esMX', 'Toc, toc, pequeño Barbabronce. ¿Hay alguien aquí?', '', 28153),
(143839, 'esMX', 'La Luz sigue de mi lado. ¡No caeré tan fácilmente!', '', 28153),
(143838, 'esMX', '¡Almirante Rogers! Hemos acabado con tu fortaleza, ¿Dónde quedaron tus promesas de venganza?', '', 28153),
(143837, 'esMX', '¿Piensan que uno\' soldados a caballo nos detendrán? ¡Ja! ¡Que sientan la fuerza de la Horda!', '', 28153),
(143836, 'esMX', 'El bah\'tión necesita refuerzos. ¡Destruyan esos tanques antes de que se acerquen demasiado!', '', 28153),
(143835, 'esMX', 'Nuestras defensas aún son débiles. ¡Tropas de la Horda, vuelvan a la base y defiendan nuestra posición!', '', 28153),
(143834, 'esMX', 'Muy bien. Si quieren guerra, tendrán guerra. ¡Envíen a un batallón montado para acabar con ellos!', '', 28153),
(143833, 'esMX', 'La Horda ahora controla el Círculo de Elementos.', '', 28153),
(143832, 'esMX', 'Granovel nos pertenece... Y con él, los jinetes de lobos.', '', 28153),
(143831, 'esMX', 'La Armería eh\'tá lista, colega.', '', 28153),
(143830, 'esMX', 'El Taller está listo. ¡Nuestros demoledore\' acabarán rápidamente con los muro\' de la Alianza!', '', 28153),
(143829, 'esMX', '¡Máquinas de asedio, destrúyanlos!', '', 28153),
(143828, 'esMX', 'Se los advertí, escorias de la Horda. Ahora prepárense para la aniquilación.', '', 28153),
(143827, 'esMX', 'Estas tierra\' eran de los trols mucho ante\' de que llegara la Alianza, Turalyon.', '', 28153),
(143826, 'esMX', 'Sí, encajarás de inmediato.', '', 28153),
(143825, 'esMX', 'Tendrás que conformarte con esa ropa.', '', 28153),
(143824, 'esMX', 'Primero lo primero. Necesitaremo\' madera y hierro para construir una base de la Horda aquí. Debería haber suficiente en los alrededore\'.', '', 28153),
(143823, 'esMX', 'He estado eh\'perando lo mismo, Muradin.', '', 28153),
(143822, 'esMX', 'Quizás esa ropa te ayude con tus tareas.', '', 28153),
(143821, 'esMX', '¡Bah! ¡Te tragarás las palabras, Turalyon!', '', 28153),
(143820, 'esMX', '¡Estas son tierras de la Alianza! ¡Nos vengaremos de todos los invasores de la Horda!', '', 28153),
(143819, 'esMX', '¡Y ahora le pertenecen a la Horda!', '', 28153),
(143818, 'esMX', 'Hace años, toda eh\'ta tierra pertenecía a los trols.', '', 28153),
(143817, 'esMX', '¡Con gusto! Te has metido con el enano equivocado.', '', 28153),
(143816, 'esMX', '¡Muradin! ¡Da la cara, cobarde!', '', 28153),
(143815, 'esMX', 'Nuestras defensas aún están débiles. ¡Detengan a esos tanques antes de que lleguen a nuestra base!', '', 28153),
(143814, 'esMX', '¡No tan horribles como la tuya, Barbabronce!', '', 28153),
(143813, 'esMX', 'Perdóname, Examinadora.', '', 28153),
(143812, 'esMX', 'Es un honor servirte, Examinadora.', '', 28153),
(143811, 'esMX', '', 'La batalla ha terminado... y hemo\' sobrevivido. ¡Ateena pagará por su locura!', 28153),
(143810, 'esMX', '', '¡Contemplen al destructor de Zuldazar! Eh\'pero que traten de detenerno\'... ¡su sufrimiento será glorioso!', 28153),
(143809, 'esMX', '', 'Llegaste tan lejo\', ¡solo para caer ante la furia del amo!', 28153),
(143808, 'esMX', 'Trabajar para el Relicario es agotador...', '', 28153),
(143807, 'esMX', 'Je, ¡es muy fácil! Pon a prueba tu brazo. Siempre hace falta más madera.', '', 28153),
(143806, 'esMX', 'Como digas, Examinadora.', '', 28153),
(143805, 'esMX', 'Como pueda servirte, Examinadora.', '', 28153),
(143804, 'esMX', 'Me da gusto ayudar, Examinadora.', '', 28153),
(143803, 'esMX', '', '¡Tu piel será un excelente conducto para mi amo!', 28153),
(143802, 'esMX', '', 'La Horda caerá despué\'. ¡Pagarás por matar a Hir\'eek! No tienes a dónde huir.', 28153),
(143801, 'esMX', '', 'Zuldazar caerá... ¡y mi amo pronto será libre! ¡Tus débile\' loa no podrán detenerlo!', 28153),
(143800, 'esMX', 'Por supuesto, Examinadora.', '', 28153),
(143799, 'esMX', 'Allí estaré, Examinador.', '', 28153),
(143798, 'esMX', '', 'Interesante... Baeloth, ven a ver esto y dime qué piensas.', 28153),
(143797, 'esMX', '', '¿A dónde has ido, Baeloth? Tengo más conocimientos valiosos que debes escribir.', 28153),
(143796, 'esMX', '', 'Mi querido Baeloth, ven a ver esto.', 28153),
(143795, 'esMX', '', 'No hay tiempo para descansar en el Relicario, Baeloth.', 28153),
(143794, 'esMX', '', 'Baeloth, ¡no toques los artefactos!', 28153),
(143793, 'esMX', '', 'Es maravilloso... Baeloth, ¡ven a ver esta maravilla!', 28153),
(143792, 'esMX', '', '¡Hezrel ha alzado su escudo! ¡Cúbrete con él!', 28153),
(143791, 'esMX', '', 'Baeloth, ¿estás soñando otra vez? Necesito un poco de ayuda.', 28153),
(143790, 'esMX', '', 'Baeloth, por favor transcribe todo lo que digo.', 28153),
(143789, 'esMX', 'Los Firmemares necesitan muchos suministros para alcanzar su máximo nivel. Mi tarea consiste en rastrear y reabastecer las tiendas, además de reparar dispositivos y aparatos rotos.$b$b...$b$bRompen muchos dispositivos y aparatos por día.$b$bNo son tipos muy cuidadosos.', '', 28153),
(143788, 'esMX', '', '$n, ¿puedo hablar contigo? Necesito ayuda.', 28153),
(143787, 'esMX', '<< Se desarrolla un evento en el que yo y los trabajadores marchamos hacia la calzada con cañones. >>', '', 28153),
(143786, 'esMX', 'Todo alrededor es espanto... Todo... derredor es... espanto... Todorr... espanto... Torr panto... ¡Tor\'paantos!', '', 28153),
(143785, 'esMX', '¡Parece que se han creído mi actuación! Me resulta extraordinario que se pensaran que yo podía ser tan ingenuo como para... Espera, ¿dices que me están escuchando? Yo, eh... ¡Tor\'paantos!', '', 28153),
(143784, 'esMX', 'Lista de cosas que espantan a Tor\'paantos: serpientes, niños malos, serpientes, cuevas oscuras, serpientes... y los debiluchos que fastidian a Tor\'paantos.', '', 28153),
(143783, 'esMX', 'Claro que Tor\'paantos ha leído libros. Libros con pocas palabras y muchos dibujos... pero libros al fin, ¿no?', '', 28153),
(143782, 'esMX', '¿$GEl debilucho:La debilucha; no estará tratando de aprovecharse de la naturaleza bondadosa de Tor\'paantos, no?', '', 28153),
(143781, 'esMX', 'Tor\'paantos teme un poco a las serpientes.', '', 28153),
(143780, 'esMX', '¡Tor\'paantos está orgulloso de ser templeluz!', '', 28153),
(143779, 'esMX', 'Ven a ver a Tor\'paantos cuando quieras.', '', 28153),
(143778, 'esMX', 'Ahora Tor\'paantos debe volver al trabajo.', '', 28153),
(143777, 'esMX', 'Tor\'paantos tiene mucho que hacer.', '', 28153),
(143776, 'esMX', 'Tor\'paantos te verá pronto.', '', 28153),
(143775, 'esMX', 'Tor\'paantos.', '', 28153),
(143774, 'esMX', 'Rápido, $n. Hay vidas que dependen de esto.', '', 28153),
(143773, 'esMX', '¡Tor\'paantos está listo!', '', 28153),
(143772, 'esMX', 'Que la Luz te acompañe, colega.', '', 28153),
(143771, 'esMX', '¿Peligro? ¡Tor\'paantos se ríe del peligro!', '', 28153),
(143770, 'esMX', '¿$GEl debilucho:La debilucha; necesita algo de Tor\'paantos?', '', 28153),
(143769, 'esMX', 'Tor\'paantos saluda $Gal debilucho:a la debilucha;.', '', 28153),
(143768, 'esMX', '¿Tor\'paantos?', '', 28153),
(143767, 'esMX', '¡Tor\'paantos!', '', 28153),
(143766, 'esMX', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t¡%s comienza a lanzar |cFFFF0000|Hspell:259610|h[Apocalipsis sangriento]|h|r! ¡Cúbrete!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t¡%s comienza a lanzar |cFFFF0000|Hspell:259610|h[Apocalipsis sangriento]|h|r! ¡Cúbrete!', 28153),
(143765, 'esMX', '', '¡Lucha! ¡pelea! ¡Tu sufrimiento alimenta a mi amo!', 28153),
(143764, 'esMX', '¿Jaina? Se sale de la vaina. ¿Modera? Eh... bueno, no puedo ser brillante todo el tiempo.', '', 28153),
(143763, 'esMX', '¿Qué dijiste? ¿Gagag? ¿Dagag? ¿Bagag? Ah... ¡Khadgar!', '', 28153),
(143762, 'esMX', '¿Magos del Kirin Tor? Yo diría vagos del Kirin Tor.', '', 28153),
(143761, 'esMX', 'Si todos ustedes hicieran lo que yo digo en lugar de intentar pensar, Azeroth estaría muchísimo mejor.', '', 28153),
(143760, 'esMX', 'Sería insensato oponerse a nosotros.', '', 28153),
(143759, 'esMX', 'Por Quel\'Thalas.', '', 28153),
(143758, 'esMX', 'Hemos atravesado mucho.', '', 28153),
(143757, 'esMX', 'Construimos nuestro futuro sobre los cimientos de la tradición.', '', 28153),
(143756, 'esMX', 'Ponte a trabajar.', '', 28153),
(143755, 'esMX', 'Ningún intruso debe interferir.', '', 28153),
(143754, 'esMX', 'Respeta nuestras costumbres.', '', 28153),
(143753, 'esMX', 'El sol eterno todavía nos guía.', '', 28153),
(143752, 'esMX', '¿Qué quieres de mí?', '', 28153),
(143751, 'esMX', 'Sirvo a Lunargenta.', '', 28153),
(143750, 'esMX', 'Estoy bastante ocupado.', '', 28153),
(143749, 'esMX', 'No malgastes los recursos.', '', 28153),
(143748, 'esMX', '¿Qué ocurre?', '', 28153),
(143747, 'esMX', 'Debemos proteger a la Fuente del Sol.', '', 28153),
(143746, 'esMX', 'Ten, toma esto como una muestra de agradecimiento.', '', 28153),
(143745, 'esMX', '', '¿Planes? Pobre de mí. ¿Te parece que puedo hacer planes?', 28153),
(143744, 'esMX', '', '¿Creíste que no iba a darme cuenta del modo en que miras a mis forestales? Te sugiero que te guardes las miradas —y los pensamientos— para ti.', 28153),
(143743, 'esMX', '', 'He tomado nota de tu progreso. Tal vez tenga que enviarte con Nathanos para que recibas un entrenamiento correctivo.', 28153),
(143742, 'esMX', '', 'Sin duda soy tu preferida de las hermanas Brisaveloz... ¿no? ¿No?', 28153),
(143741, 'esMX', '', 'La fuerza vital de Azeroth le pertenece a la Horda.', 28153),
(143740, 'esMX', '¡Comencé a cuestionarme la existencia de una criatura así!', '', 28153),
(143739, 'esMX', '', 'Tomaremos lo que es nuestro.', 28153),
(143738, 'esMX', '', 'Habrá un tiempo en que todos servirán a la Horda.', 28153),
(143737, 'esMX', '', 'Engrosaré las filas de los Renegados. Lo haré... como sea.', 28153),
(143736, 'esMX', '', 'La Alianza se arrodillará ante nosotros.', 28153),
(143735, 'esMX', '', 'Sirve a la Horda. Sírveme.', 28153),
(143734, 'esMX', '¡Es hermoso!', '', 28153),
(143733, 'esMX', '', 'Vete. Tengo mucho que hacer.', 28153),
(143732, 'esMX', '', 'Si me sirves bien, recibirás una recompensa.', 28153),
(143731, 'esMX', '', 'La Horda tendrá un futuro nuevo.', 28153),
(143730, 'esMX', '', 'Nuestro verdadero trabajo recién empieza.', 28153),
(143729, 'esMX', '', 'Saludos, $gcampeón:campeona;.', 28153),
(143728, 'esMX', '', 'Adelante.', 28153),
(143727, 'esMX', '', 'Espero que no me hagas perder el tiempo.', 28153),
(143726, 'esMX', '', 'Dile a tu jefa de guerra a qué vienes.', 28153),
(143725, 'esMX', '', 'Los elementos de Zandalar han tolerado mucho. Hay que detener a los chamanes oscuros que abusan de su poder con fines egoístas.', 28153),
(143724, 'esMX', 'Mi apellido es Berthold, y soy un fanático de los caballos.\n\nSegún los rumores, hay una criatura majestuosa, similar a un caballo, al oeste de este lugar, en cierta montaña. Tomé un empleo por aquí para tener la oportunidad de verla en mi tiempo libre.\n\nOh, lo que daría por ver algo así...', '', 28153),
(143721, 'esMX', 'Afirmativo. Se solicita no preocuparse por la posición del guardián titánico Hezrel. Partiré hacia el área designada como Zul\'nazman.', '', 28153),
(143720, 'esMX', '', 'Hezrel, lo\' trols de sangre se congregan en Zul\'nazman. Si vas a ayudarno\', debes ir allí.', 28153),
(143719, 'esMX', 'Invítame un trago, $pr.\n\nMi pueblo salvó este mundo mientras ustede\' huían como cobardes y se ocultaban en la niebla.\n\nMe debe\' un trago.', '', 28153),
(143718, 'esMX', 'Sistemas del guardián titánico Hezrel operando al 50 por ciento. Es imperativo conservar la energía restante para purgar a los trols de sangre.', '', 28153),
(143717, 'esMX', 'Este era mi salón de mezclas. La familia real recibía a la nobleza de todo el mundo y yo le\' preparaba deliciosa\' bebidas.\n\nAhora es la guarida de los forasteros inmundos y sus horrible\' amigos. Qué desgracia.', '', 28153),
(143716, 'esMX', 'Respeto a algunos de los cárteles goblin. Son neutrales y fuertes, y están dispuesto\' a todo. Como los Zandalari, aunque peores, claro.\n\nPero ustede\' los Pantoque dan vergüenza. Confabulados con los elfos y la Horda. No son más que traidores.', '', 28153),
(143715, 'esMX', '¡Siente mi poder!', '', 28153),
(143714, 'esMX', 'Me gusta cómo opera la Horda, $p. Liderazgo, unidad, líneas de suministro\' estables...\n\n¿Buscan gente?', '', 28153),
(143713, 'esMX', 'Estoy listo para buscar a nuestro próximo aliado.', 'Estoy lista para buscar a nuestro próximo aliado.', 28153),
(143712, 'esMX', '', 'Finalmente, las incesantes treguas entre la Horda y la Alianza han llegado a su fin.$b$bUna guerra está por comenzar.', 28153),
(143711, 'esMX', 'Siempre me sorprendió que los Lanza Negra se aliaran con la Horda. Supongo que eran muy débile\' para luchar sin ayuda.\n\n¿Cómo está Vol\'jin?', '', 28153),
(143710, 'esMX', 'Mira $Uelfo:elfa;, Ya no atiendo este bar, así que no tengo que simular que me cae\' bien.\n\nFuera de mi vista, $Uelfo asqueroso:elfa asquerosa;.', '', 28153),
(143709, 'esMX', 'Te ves $Usediento:sedienta;. Bebe un poco. Quédate y conversemo\' un rato. \n\nZuldazar existe desde tiempos remotos. No desaparecerá tan fácilmente.', '', 28153),
(143708, 'esMX', 'Oí que alguno\' de ustedes irán a Nazmir. Eviten ese lugar si pueden. Nada bueno ha salido de eso\' pantanos en mucho tiempo.', '', 28153),
(143707, 'esMX', 'Oí que hay más problema\' que de costumbre en la\' arenas de Vol\'dun. Ten cuidado si vas en esa dirección.', '', 28153),
(143706, 'esMX', 'Mi pueblo fundó la civilización al principio de lo\' tiempos, y hemos cargado con ustede\' desde entonces.\n\nDime, $pr, ¿acaso tu gente ha hecho algo digno de recordar?\n\nA mí no se me ocurre nada.', '', 28153),
(143705, 'esMX', '(Salta al hombro de Hezrel para volver a Hondonada Penumbrosa).', '(Salta al hombro de Hezrel para volver a Hondonada Penumbrosa).', 28153),
(143704, 'esMX', 'Imposible reparar la contención de G\'huun. Debemos evitar que unidades designadas como trols de sangre destruyan Zuldazar para impedir la liberación de G\'huun.\n\nEstructura rodeada por trols de sangre. Guardián titánico Hezrel protegerá a $n y la princesa Talanji.\n\nSuban a hombros. Mantengan la cabeza baja.', '', 28153),
(143703, 'esMX', 'Qué asco. Huele\' peor que un trol de sangre.\n\nSi aún fuera el dueño de este bar, te sacaría a la calle junto con la basura.', '', 28153),
(143702, 'esMX', '¿Qué ha\' oído sobre lo que sucede fuera de la ciudad?', '', 28153),
(143700, 'esMX', 'Gallywix tiene operaciones en marcha en Silithus. Dirígete allí de inmediato. Y si ves a alguno de la Alianza dando vueltas por ahí, encárgate rápido de él.', '', 28153),
(143699, 'esMX', 'Establecimos una base provisoria en Silithus. Habla con nuestros operarios allí... y mantén los ojos abiertos ante cualquier ataque de la Horda.', '', 28153),
(143698, 'esMX', 'Ustede\' los orcos saben beber, lo admito.\n\nPero diles a tu\' presumidos amigos elfo\' que no aparezcan por aquí.', '', 28153),
(143697, 'esMX', '¿Alleria y Turalyon? Ni en sueños. Es decir... no es que esté en contra de ellos ni nada semejante, pero... Eh... ¿podemos cambiar de tema?', '', 28153),
(143696, 'esMX', 'Bueno, puedo perdonarte por no admirar a los elfos. Después de todo, la mitad de nosotros odia a la otra mitad con bastante intensidad.', '', 28153),
(143695, 'esMX', 'Admito que el violeta nunca fue mi color favorito. Pero ha empezado a cautivarme. Literalmente.', '', 28153),
(143694, 'esMX', '¿Elfo noble? Paso. ¿Por qué querría ser un elfo noble cuando puedo andar por ahí con mi aspecto trágico y melancólico?', '', 28153),
(143693, 'esMX', 'Concéntrate y no pierdas el control.', '', 28153),
(143692, 'esMX', 'No te rindas a los susurros.', '', 28153),
(143691, 'esMX', 'No te cierres a las posibilidades.', '', 28153),
(143690, 'esMX', 'Las sombras te vigilan.', '', 28153),
(143689, 'esMX', 'Servimos a la Alianza.', '', 28153),
(143688, 'esMX', 'La Luz no es el único camino.', '', 28153),
(143687, 'esMX', 'Los ren\'dorei demostraremos nuestro valor.', '', 28153),
(143686, 'esMX', 'Tengo mucho que enseñarte.', '', 28153),
(143685, 'esMX', 'Ven con la mente abierta.', '', 28153),
(143684, 'esMX', 'Todos los caminos son posibles.', '', 28153),
(143683, 'esMX', 'Abrazamos el poder. No le tememos.', '', 28153),
(143682, 'esMX', 'Nosotros controlamos a las sombras.', '', 28153),
(143681, 'esMX', 'Bal\'a dash, malanore.', '', 28153),
(143680, 'esMX', '¡Saludos, $gviajero:viajera;!', '', 28153),
(143679, 'esMX', '¡Mi parche nunca cambió de lugar! Por favor... ¿quién se equivocaría con algo así?', '', 28153),
(143678, 'esMX', 'Trabajar para Sylvanas tiene sus... desafíos. La muerte la ha hecho todavía más mandona. Pero... eh... no le cuentes que te dije esto.', '', 28153),
(143677, 'esMX', 'Nathanos será el campeón de la reina, pero yo puedo vencerlo cuando me plazca.', '', 28153),
(143676, 'esMX', 'Esta cabellera sedosa y tupida no es casualidad. Exige un cuidado constante.', '', 28153),
(143675, 'esMX', 'Lunargenta jamás volverá a ser gobernada por un rey.', '', 28153),
(143674, 'esMX', 'Somos una nación en ascenso.', '', 28153),
(143673, 'esMX', 'Al diel shala.', '', 28153),
(143672, 'esMX', 'Encontramos fortaleza en la Horda.', '', 28153),
(143671, 'esMX', 'Todo lo que hago lo hago por Quel\'Thalas.', '', 28153),
(143670, 'esMX', 'Que la Luz de la Fuente del Sol te acompañe.', '', 28153),
(143669, 'esMX', 'Lunargenta volverá a tener tiempos de prosperidad.', '', 28153),
(143668, 'esMX', 'La belleza de Canción Eterna resiste.', '', 28153),
(143667, 'esMX', 'El sol eterno todavía nos guía.', '', 28153),
(143666, 'esMX', 'La reconstrucción prosigue.', '', 28153),
(143665, 'esMX', 'Hemos hecho muchos sacrificios.', '', 28153),
(143664, 'esMX', 'Sirvo con orgullo como Señor regente.', '', 28153),
(143663, 'esMX', 'Bal\'a dash, malanore.', '', 28153),
(143662, 'esMX', 'Saludos en nombre de Lunargenta.', '', 28153),
(143651, 'esMX', '¡Creo que atrapé uno grande!', '', 28153),
(143650, 'esMX', 'PLACEHOLDER SCENE - Hezrel reveals G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike.', 'PLACEHOLDER SCENE - Hezrel talks about G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike', 28153),
(143649, 'esMX', '', '¡Atrás, $r! ¡Su voz me pertenece!', 28153),
(143648, 'esMX', '', 'Hay... tanto poder... aquí...', 28153),
(143647, 'esMX', '', 'Cuidado, Umbric. Las respuestas a estos misterios tienen un costo.', 28153),
(143646, 'esMX', 'Este cubo, por ejemplo. Es un dispositivo antiguo, quizás hasta sea anterior al surgimiento de la vida en Azeroth. Parece que está bloqueado, aún no hemos podido abrirlo.', '', 28153),
(143645, 'esMX', '¡Así es! Al igual que tú, creemos que el Vacío puede utilizarse para defender la vida en lugar de consumirla. Hemos hecho grandes progresos, Lady Brisaveloz, pero aún quedan muchos misterios.', '', 28153),
(143644, 'esMX', '', 'Tal vez en otro momento. $GEste adalid:Esta adalid; y yo hemos venido a buscarlo. Nos enteramos sobre su exilio de Lunargenta y sentimos que tenemos cosas en común.', 28153),
(143643, 'esMX', 'Mi pueblo y yo hemos oído historias sobre los acontecimientos de Argus. Como se imaginará, estamos muy interesados en saber más sobre su interacción con la naaru oscura.', '', 28153),
(143642, 'esMX', '¡¿Alleria Brisaveloz?! ¿Cómo...? ¡Qué sorpresa inesperada! Es un honor.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'esMX', '', '¡Magíster Umbric! Soy Alleria Brisaveloz.', 28153),
(143640, 'esMX', '', 'Allí, más adelante. Ese debe ser Umbric.', 28153),
(143639, 'esMX', '', 'Creo que, según estas notas, puedo reabrir el portal hacia el mundo que mencionó él. Veamos...', 28153),
(143638, 'esMX', '', '<Aterrizaje del salto: Total 3>', 28153),
(143637, 'esMX', 'Drathir creía que esta falla albergaba un objeto ancestral con un poder inconcebible. Quizás esta sea la clave que nos permita controlar las sombras.', '', 28153),
(143636, 'esMX', 'Sus notas dicen que existía dentro de una falla en el tejido de la realidad misma. Él nunca encontró este lugar... pero yo sí. ¡Pronto, el camino se abrirá ante nosotros!', '', 28153),
(143635, 'esMX', 'La búsqueda de poder de Drathir lo llevó a buscar fragmentos de un mundo ancestral, un mundo que estaba en el borde del Vacío mismo.', '', 28153),
(143634, 'esMX', '<Aterrizaje del salto: Total 3>', '', 28153),
(143633, 'esMX', '', 'Vamos. Debemos dirigirnos a Aguja de la Estrella del Alba.', 28153),
(143632, 'esMX', 'Sin embargo, creo que se puede usar este conocimiento para hacer el bien. Drathir llevó a cabo la mayor parte de su investigación en Aguja de la Estrella del Alba. Debemos ir allí.', '', 28153),
(143631, 'esMX', 'Fue la traición de Drathir lo que le permitió a Arthas corromper la Fuente del Sol... y dejar en ruinas a nuestro reino. Por primera vez, entiendo por qué Rommath se oponía a nuestra investigación.', '', 28153),
(143630, 'esMX', 'Parece que no somos los primeros de nuestro pueblo en involucrarse con el Vacío. He encontrado notas de aquel cuyo nombre está maldito... Dar\'Khan Drathir.', '', 28153),
(143629, 'esMX', '<Aterrizaje del salto: Total 3>', '', 28153),
(143628, 'esMX', '', 'Parece que hemos encontrado unas notas.', 28153),
(143627, 'esMX', '', '<Aterrizaje del salto: Total 3>', 28153),
(143626, 'esMX', 'Por desgracia, parece que nuestra investigación está estancada. Creo que en los Dominios Andilien podemos encontrar algo de conocimiento que nos ayude a impulsarla nuevamente.', '', 28153),
(143625, 'esMX', 'El gran magíster tiene que comprender que este poder es crucial para defender a Lunargenta. ¡Los sin\'dorei no volverán a ser presas de sus enemigos!', '', 28153),
(143624, 'esMX', 'Los experimentos con el Vacío están dando sus frutos. Estoy seguro de que estamos cerca de un descubrimiento clave... a pesar de las protestas de Rommath y su mente cerrada.', '', 28153),
(143623, 'esMX', '<Aterrizaje del salto: Total 3>', '', 28153),
(143622, 'esMX', '', '<Aterrizaje del salto: Total 3>', 28153),
(143621, 'esMX', '<Grito de temor: Total 3>', '', 28153),
(143620, 'esMX', '<Aterrizaje del salto: Total 3>', '', 28153),
(143619, 'esMX', 'Hezrel, comienza tus exploraciones para encontrar una solución a la corrupción de los dioses antiguos en Nazmir.', 'Hezrel, comienza tus exploraciones para encontrar una solución a la corrupción de los dioses antiguos en Nazmir.', 28153),
(143618, 'esMX', '¡Veamos si estos peces están listos para morder!', '', 28153),
(143617, 'esMX', '', '<Aterrizaje del salto: Total 3>', 28153),
(143616, 'esMX', '', 'Este bosque nos dio tantas alegrías a mis hermanas y a mí... Verlo así... me llena el corazón de tristeza.', 28153),
(143615, 'esMX', 'Juntos, les mostraremos que están equivocados.', '', 28153),
(143614, 'esMX', 'Nos llevará cierto tiempo acostumbrarnos a nuestras formas nuevas. Esperamos tu regreso con ansias, Lady Brisaveloz. Y a ti, $p... te agradecemos profundamente.', '', 28153),
(143613, 'esMX', '', 'A cambio, yo me comprometo a ayudarlos en su recorrido. $p y yo le transmitiremos las novedades al Alto Rey Wrynn. Entonces, regresaré para dar inicio a nuestro entrenamiento.', 28153),
(143612, 'esMX', 'Lunargenta nos dio la espalda hace mucho tiempo. Hoy renacemos... y parece apropiado emprender un nuevo camino. A partir de hoy, depositamos nuestra lealtad en la Alianza.', '', 28153),
(143611, 'esMX', '', 'Puedo sentir los poderes que controlan. Son... considerables. Ustedes serían aliados valiosos para la Alianza.', 28153),
(143610, 'esMX', 'Mi arrogancia casi nos conduce a la perdición. Me involucré con poderes que estaban más allá de mi control. Alleria, si nos entrenas, te seguiremos a dónde tú nos lleves.', '', 28153),
(143609, 'esMX', '', 'He autorizado la construcción de una embajada en Orgrimmar. Con ella ganaremos más aliados para nuestra causa. Encontrémonos allí de inmediato.', 28153),
(143608, 'esMX', '', 'Por el liderazgo altruista de la Horda en la guerra contra la Legión, nuestras filas quedaron diezmadas. Nuestros enemigos se regocijan ante la idea de robarnos lo que es nuestro. No lo permitiremos.', 28153),
(143607, 'esMX', '', 'Has observado nuestras operaciones en Silithus, $p. Es evidente que la Alianza está haciendo todo lo que tiene a su alcance para socavar nuestro avance.', 28153),
(143606, 'esMX', 'Es hora de que la Alianza incorpore miembros nuevos a nuestra causa. Hemos establecido una embajada en Ventormenta para impulsar esta iniciativa. Nos reuniremos allí.', '', 28153),
(143605, 'esMX', 'La Horda no se detendrá ante nada en su afán por robar la fuerza vital de Azeroth. Me temo que después de la guerra contra la Legión, nuestras filas se redujeron demasiado para resistir su ataque.', '', 28153),
(143604, 'esMX', 'Has visto la destrucción de Silithus con tus propios ojos, $p. Sabes todo lo que hay en juego.', '', 28153),
(143603, 'esMX', 'Te espero afuera del Fuerte Grommash. No digas nada acerca de esto... o sufrirás las consecuencias sin piedad y de inmediato.', '', 28153),
(143602, 'esMX', 'Ha llegado información crucial para los intereses de la Horda. Es imperioso que estemos un paso adelante de nuestros rivales.', '', 28153),
(143601, 'esMX', '¡$p! La Dama Oscura ordena que te encuentres conmigo en Orgrimmar.', '', 28153),
(143600, 'esMX', 'Encuéntrate conmigo en el Reposo del León. No hace falta que te diga que no debes revelar nada acerca de esta reunión.', '', 28153),
(143599, 'esMX', 'Hemos descubierto cierta... información sensible que insiste en que debes saber.', '', 28153),
(143598, 'esMX', '$p, el Alto Rey Wrynn ordena que te encuentres conmigo en Ventormenta.', '', 28153),
(143597, 'esMX', 'Me acompaña $Geh\'te forastero:eh\'ta forastera; que desea hablar contigo, poderoso loa.', '', 28153),
(143596, 'esMX', '', 'Los Natonocturno son un pueblo sabio y poderoso. Tus conocimientos ancestrales serán de gran utilidad para nuestra causa.', 28153),
(143595, 'esMX', '', 'Ya basta de cortesías. Tienes que demostrar tu valor, adalid. Sin importar a dónde te lleve tu camino, siempre pelearás... ¡por la Horda!', 28153),
(143594, 'esMX', '', 'Puedes tener la tranquilidad de que estaré atenta a tu progreso. Como jefa de guerra, tengo muchas expectativas en ti... y soy generosa con quienes me sirven bien.', 28153),
(143593, 'esMX', '', 'La Horda tiene muchos rivales en este mundo. Algunos nos consideran enemigos... otros, desterrados. Pero hallamos la fuerza en la unión... así como en rebelarnos contra los que desafían nuestra libertad.', 28153),
(143592, 'esMX', '', 'Los tauren de Altamontaña son fuertes y valientes. Son atributos que seguramente necesitaremos en los días que se avecinan.', 28153),
(143591, 'esMX', '', 'Ah, $Gel:la; joven adalid $p se presenta ante mí. He oído que tienes un gran potencial. Espero que los rumores sean ciertos.', 28153),
(143590, 'esMX', 'Buen viaje, $p. Que la Luz te acompañe siempre.', '', 28153),
(143589, 'esMX', 'Es posible que los elfos del Vacío se hayan incorporado recientemente a nuestras filas, pero Alleria Brisaveloz es una de nuestras más grandes heroínas. Bajo su tutela, los poderes que tú controles ayudarán a nuestra causa.', '', 28153),
(143588, 'esMX', '¡Los expulsaremos de estas tierras!', '', 28153),
(143587, 'esMX', 'Buen viaje, $p. Aunque camines entre las sombras, eres un faro de esperanza para todos nosotros.', '', 28153),
(143586, 'esMX', 'Estoy ansioso por saber de tu progreso. Tengo el presentimiento de que volveremos a hablar muy pronto.', '', 28153),
(143585, 'esMX', 'Corren tiempos difíciles en Azeroth. Te enfrentarás a grandes desafíos en los días por venir... y a muchos adversarios. Pero debes saber que nunca estarás $Gsolo:sola; contra la oscuridad... La Alianza luchará a tu lado.', '', 28153),
(143584, 'esMX', 'Es posible que los templeluz se hayan incorporado recientemente a nuestras filas, pero conozco muy bien a los draenei. Estoy seguro de que encarnarán la dedicación y la valentía del Ejército de la Luz.', '', 28153),
(143583, 'esMX', 'Hola, $p. Soy el rey Anduin Wrynn. Quería saludarte personalmente y darte la bienvenida a la Alianza.', '', 28153),
(143582, 'esMX', '¡Necesito que me sanen!', '', 28153),
(143581, 'esMX', '¡Consigan su propio aserradero!', '', 28153),
(143580, 'esMX', 'A qué rincón del mundo más interesante y desconocido nos trajo la Horda.\n\nEspero que los establecimientos de mi nueva facción sean mucho más elegantes que este.', '', 28153),
(143579, 'esMX', 'Discúlpame, $p.\n\nMe encantaría conversar contigo, pero me temo que estoy a punto de enfermarme.\n\nNo pruebes el vino.', '', 28153),
(143578, 'esMX', '<El viticultor Thesnala mira fijamente al camarero mientras sostiene la botella y derrama el vino al piso.>', '', 28153),
(143577, 'esMX', '¿Ya has probado el vino de este lugar?\n\nTienes que probarlo. Es increíblemente espantoso.\n\nLos bardos podrían componer canciones sobre su legendaria textura vomitiva.\n\nSin duda alguna, es un logro entre los peores productos de la peor calidad, un desperdicio de alcohol, con el potencial de arruinar cualquier fiesta.', '', 28153),
(143576, 'esMX', 'Hasta ahora, confío en los zandalari para construir edificios enormes y repulsivos.\n\nNO confío en que hagan buen vino.', '', 28153),
(143575, 'esMX', 'Si no sabes hacer buen vino, no hagas vino.', '', 28153),
(143574, 'esMX', 'Cómprame otra copa de este vino, quiero volver a escupir esa asquerosidad al piso.', '', 28153),
(143573, 'esMX', '¿A esto llaman vino? Con razón los trols abandonan la ciudad.', '', 28153),
(143572, 'esMX', '¡Libres al fin! ¡Rápido, salgamos de aquí!', '¡Libres al fin! ¡Rápido, salgamos de aquí!', 28153),
(143571, 'esMX', '¡Estas abominaciones de madera parecen salidas de una pesadilla!', '', 28153),
(143569, 'esMX', 'Más vale que... me paguen un adicional... por peligro.', 'Más vale que... me paguen un adicional... por peligro.', 28153),
(143568, 'esMX', '', 'Aunque eh\'tá devastado, eh\'te lugar parece familiar...', 28153),
(143567, 'esMX', '¡Pónganse a trabajar, sacos de carne perezosos!', '¡Pónganse a trabajar, sacos de carne perezosos!', 28153),
(143566, 'esMX', 'Interior de la estructura despejado. El ser llamado \"princesa Talanji\" se ha unido.', '', 28153),
(143565, 'esMX', 'Todos saben qué hacer. ¡A Corlain!', '', 28153),
(143562, 'esMX', 'Demasiado tarde. Nada puede contener a G\'huun. Todo se derrumbará. Y todos morirán.', '', 28153),
(143561, 'esMX', 'Tu final está cerca. G\'huun quedará libre. Y Azeroth será nuestro.', '', 28153),
(143560, 'esMX', 'Deja tus objeto\' de valor en la bóveda y no te detenga\', $p.\n\nTe eh\'toy vigilando...', '', 28153),
(143559, 'esMX', 'Son tiempos oscuros para Drustvar, ¡pero recuperaremos nuestra tierra!', '', 28153),
(143558, 'esMX', '¡Por Zandalar!', '', 28153),
(143557, 'esMX', 'Rezan, vamo\' de caza.', '', 28153),
(143556, 'esMX', 'Sí. Cabalgamos cuando lo ordene $Gel:la; continental.', '', 28153),
(143555, 'esMX', 'Pa\'ku, loa de los viento\', vuela y busca a los hereje\'. Descubre sus objetivos y encuéntranos en el templo.', '', 28153),
(143554, 'esMX', 'Gonk, loa de la cacería, lleva a tus seguidore\' al Templo del Profeta y asesina a los enemigo\' que encuentres. Saca a todos nuestros enemigo\' a la luz.', '', 28153),
(143553, 'esMX', 'Hermanos y hermana\' de Zandalar, ha llegado la hora de cortarles la cabeza a eh\'tos traidores que han jurado lealtad a Zul.', '', 28153),
(143552, 'esMX', '', 'El resto de nosotros tendrá que preparar el viaje a Corlain. Tiene un plan de ataque, ¿no es cierto, mariscal?', 28153),
(143551, 'esMX', '', '¡Sí, señora!', 28153),
(143550, 'esMX', '', 'Llévale esta receta de fuego alquímico al maestro Ashton, en Halcónida. Él sabrá qué hacer con ella.', 28153),
(143549, 'esMX', '', 'Por suerte, conozco a un alquimista experto en Halcónida, al sur. Los bosques son traicioneros, así que tendrás que llegar hasta allí por los viejos senderos de la montaña.', 28153),
(143548, 'esMX', '', 'El tomo tiene una receta para hacer fuego alquímico, pero no tenemos a nadie con las capacidades para crearlo.', 28153),
(143547, 'esMX', '', 'Si queremos derrotar al aquelarre de una vez y para siempre, no bastará con la plata. Necesitaremos fuego.', 28153),
(143546, 'esMX', '', '¡Gracias, señor! ¿Cómo puedo ayudarla, milady?', 28153),
(143545, 'esMX', 'La capitana Alborada... Perdón. La inquisidora Alborada es de mi absoluta confianza. Estoy seguro de que podrá cumplir con lo que le pida.', '', 28153),
(143544, 'esMX', '', '¿Alguna recomendación, mariscal?', 28153),
(143543, 'esMX', '', 'Antes de partir, necesito que alguien se encargue de una misión especial para la Orden.', 28153),
(143542, 'esMX', '¿Puedes creer que la Horda nunca fundó una agencia oficial de telemancia? Es decir, no sé cómo hacían sus ciudadanos para sentirse seguros durante sus viajes. El solo pensar en todos esos portales descontrolados abriendo agujeros en la realidad...\n\nBueno, no importa... Me alegra poder ofrecer una red de teletransportación estabilizada para la Horda. Sigue tu camino, por favor.', '', 28153),
(143540, 'esMX', 'En mi pueblo sabemos dar batalla, pero esto es un verdadero desafío.', '', 28153),
(143539, 'esMX', '', 'Ahoguen a estos insectos, hijos míos. Llénenme de orgullo.', 28153),
(143537, 'esMX', '¡Brgl! ¡Brglrgl!', '', 28153),
(143536, 'esMX', '¡¡Mrgl, mrglrglrgl! ¡Mrrrg! ¡¡Mrrrg!!', '', 28153),
(143531, 'esMX', 'Espiando', 'Espiando', 28153),
(143530, 'esMX', '¡Eh\'te es tu momento, muchacho! ¡Sube a bordo!', '', 28153),
(143529, 'esMX', 'Algo anda mal en el Zarpa de Rezan. Establecimos un explorador volador cerca del campamento.', '', 28153),
(143523, 'esMX', '¡Dame tu oro, debo presentar el informe de ganancias en cinco minutos!', '', 28153),
(143520, 'esMX', 'Estoy listo para que me apliques la esencia sintética de G\'huun.', 'Estoy lista para que me apliques la esencia sintética de G\'huun.', 28153),
(143519, 'esMX', '¡El rey Da\'ka! ¡Nos encontró! ¡Ayuda!', '', 28153),
(143518, 'esMX', '¿Perdieron? ¿Contra ellos? ¡Patético! Preséntense en Entrañas para empezar con su entrenamiento. Parece que con ustedes tengo que empezar de cero...', '', 28153),
(143517, 'esMX', 'Eso estuvo lejos de ser una victoria elegante, pero por lo menos pusieron a esos tontos de la Alianza en su lugar. ¡Por la Horda!', '', 28153),
(143516, 'esMX', 'Acaso eso que huelo... ¿es huargen? Con el penetrante hedor de la superioridad moral de la Alianza es difícil discernir.', '', 28153),
(143515, 'esMX', '¡Derríbenlos! ¡Les aseguro que NO QUIEREN decepcionar a su jefa de guerra!', '', 28153),
(143514, 'esMX', '¿A eso llama soldado la Alianza? ¡Patético! ¡Ese apenas puede blandir una espada!', '', 28153),
(143513, 'esMX', '¡Fuego! ¡Que no quede ni uno de esos bastardos con vida!', '', 28153),
(143512, 'esMX', '¡No! Hay más azerita por recolectar. ¡Sigan su mapa y protejan esas áreas!', '', 28153),
(143511, 'esMX', '¡Hay más erupciones de azerita en esta isla maldita! Miren su mapa para encontrarlas.', '', 28153),
(143510, 'esMX', 'Ya casi lo logramos. No se detengan. ¡Más azerita!', '', 28153),
(143509, 'esMX', '¡Ja! ¡Se la quitamos de las manos a la Alianza! ¡Bien hecho!', '', 28153),
(143508, 'esMX', 'Un esfuerzo decente, ¡pero necesitamos más azerita!', '', 28153),
(143507, 'esMX', 'Tomen estos suministros si los necesitan. ¡Pero no pierdan de vista el premio de la Reina alma en pena!', '', 28153),
(143506, 'esMX', 'Suministros en camino. ¡Será mejor que no vea que la Alianza llega a ellos antes que ustedes!', '', 28153),
(143505, 'esMX', 'Ahí abajo... ¡hay azerita! Tómenla para nuestra jefa de guerra. Si la Alianza se interpone, ¡desparramen sus cadáveres por toda la costa! ¡Muévanse!', '', 28153),
(143504, 'esMX', 'Déjenme echarles un vistazo. Aj... ¡Patético! ¿Por qué no tenemos forestales oscuras en nuestras filas? Bueno, tendremos que conformarnos con ustedes.', '', 28153),
(143503, 'esMX', '¡Se acerca un navío de la Alianza! Esos mugrientos nos pisan los talones. ¿Qué esperan? ¡A sus puestos!', '', 28153),
(143502, 'esMX', 'Su misión aquí es sencilla. Recojan todos los fragmentos de azerita y no dejen nada para la Alianza. No es tan difícil de comprender, ¿no?', '', 28153),
(143501, 'esMX', '¡Campeones de la Horda! Hemos encontrado depósitos de azerita en una condenada isla más allá de la costa de Feralas. ¡Su misión es apoderarse de ella en nombre de la Dama Oscura!', '', 28153),
(143500, 'esMX', '¡Expúlsenlos! ¡Esta isla nos pertenece!', '', 28153),
(143499, 'esMX', '¡Luchen por el rey! ¡Por la Alianza!', '', 28153),
(143498, 'esMX', 'La Horda se cree muy lista. ¡Enséñenles una lección!', '', 28153),
(143497, 'esMX', '¡Fuego! ¡Asesinen a los sanadores!', '', 28153),
(143496, 'esMX', 'Parecen un grupo sólido. Mmm... Tal vez nos vendrían bien uno o dos pícaros más... ¡pero con ustedes bastará!', '', 28153),
(143495, 'esMX', '¡Demonios! La Horda se quedó con esta victoria. ¡Pero juro por el Reposo del León que ganaremos la guerra!', '', 28153),
(143494, 'esMX', '¡Bien hecho, adalides! El rey Wrynn estará complacido cuando se entere de su victoria. ¡Por la Alianza!', '', 28153),
(143493, 'esMX', '¡Suministros en camino! ¡Campeones, tómenlos!', '', 28153),
(143492, 'esMX', '¡Más erupciones de azerita! ¡Ubíquenlas en sus mapas y aseguren las áreas!', '', 28153),
(143491, 'esMX', 'Están haciendo un buen trabajo. ¡Un poco más de azerita y la victoria será nuestra!', '', 28153),
(143490, 'esMX', 'Mantuvieron la azerita fuera del alcance de la Horda. ¡Bien hecho!', '', 28153),
(143489, 'esMX', 'Lo están haciendo bien, héroes. ¡Pero necesitamos más azerita!', '', 28153),
(143488, 'esMX', '¡Héroes! Estamos enviándoles suministros. ¡No permitan que la Horda se apodere de ellos!', '', 28153),
(143487, 'esMX', '¡Hemos divisado más erupciones de azerita alrededor de la isla! Las ubicaciones están marcadas en el mapa.', '', 28153),
(143486, 'esMX', 'Hay un depósito repleto de azerita debajo de nosotros, héroes. Bajen y recojan toda la que puedan. Si esos saqueadores de la Horda se interponen en su camino... ¡aniquílenlos!', '', 28153),
(143485, 'esMX', '¡Se acerca un navío de la Horda! Los malditos nos siguieron hasta aquí. ¡A sus puestos!', '', 28153),
(143484, 'esMX', 'Hemos traído nuestra nave hasta el centro de la isla. Recojan toda la azerita que puedan, ¡es la clave para la victoria!', '', 28153),
(143483, 'esMX', 'Adalides, se han encontrado depósitos de azerita en una isla más allá de la costa de Feralas. Debemos apoderarnos de ellos antes que la Horda.', '', 28153),
(143482, 'esMX', '', 'Sería un honor, Lady Liadrin. Oculeth tiene las coordenadas de tu capital. Reuniré a Silgryn y a Valtrois y nos encontraremos en Lunargenta.', 28153),
(143481, 'esMX', '', 'Estoy segura de que el señor regente estará complacido con tu interés. ¿Estás lista para partir?', 28153),
(143480, 'esMX', '', 'Es por eso que estoy sumamente agradecida por tu invitación a Lunargenta. Me gustaría saber si hay un lugar para los Natonocturno en la Horda.', 28153),
(143479, 'esMX', '', 'La Alianza parece demasiado recelosa... demasiado cerrada. Mi pueblo no volverá a sufrir el aislamiento.', 28153),
(143478, 'esMX', '', 'Tyrande y su raza orgullosa también miran con desdén a los sin\'dorei. Sin embargo, durante muchos años, mientras mi pueblo luchaba por salvar el mundo, el suyo descansaba en sus guaridas o se ocultaba en los árboles.', 28153),
(143477, 'esMX', '', 'Parece que el \"conocimiento de Elune\" la alejó del vínculo que alguna vez compartimos. Que así sea.', 28153),
(143476, 'esMX', '', 'Los kaldorei pelearán para ver que la Legión sea derrotada y la Fuente de la Noche sea destruida. Después de eso... debemos ver dónde nos guiará el conocimiento de Elune.', 28153),
(143475, 'esMX', '', 'No pretendemos ser esclavos de la Fuente de la Noche. Buscamos alejar a la Legión de Suramar y poner fin a la opresión de Elisande.', 28153),
(143474, 'esMX', '', 'Arcanista Thalyssra. Recuerdo el bando de tu orden en la Guerra de los ancestros. ¿Cómo saber que no nos traicionarás para convertirte en la próxima Elisande... la próxima Azshara?', 28153),
(143473, 'esMX', '', 'Pensé que forjaríamos una alianza con nuestros hermanos de Kalimdor. Pero su arrogancia y desconfianza pronto demostraron que eso no sería posible.', 28153),
(143472, 'esMX', '', 'Debo admitir que la primera vez que oí hablar de la Horda no creí que tuviéramos algo en común.', 28153),
(143471, 'esMX', '', 'Fue un orgullo para la Horda luchar a tu lado contra la Legión Ardiente, milady.', 28153),
(143470, 'esMX', '', 'Y eso te lo debemos a ti. Tuviste un rol fundamental en nuestra causa.', 28153),
(143469, 'esMX', '', 'Es bueno ver que tu ciudad está en libertad, Primera Arcanista.', 28153),
(143468, 'esMX', '', 'Saludos, Lady Liadrin, $p. Bienvenidos de regreso a Suramar. Me alegra $Grecibirlos:recibirlas; en circunstancias más amenas.', 28153),
(143467, 'esMX', '', 'Qué decepción, aunque no me sorprende... Los loa no te han bendecido, $Uhijo:hija;. No nos acompañará\' en el Bancal de los Elegidos.', 28153),
(143466, 'esMX', 'Vaya, sí que has viajado mucho para visitarme, joven.$b$bTengo varias novelas sobre la historia de los cangrejos... Digo, por si te interesa.', '', 28153),
(143465, 'esMX', '', 'Resih\'tente y orgullos$go:a;, puedes durar más que tus enemigos y capear cualquier tempestad. Necesitaremos tu fuerza para defender la ciudad.', 28153),
(143464, 'esMX', '', 'Eh\'to es... muy inusual. Necesitaremos tu fuerza para los tiempos por venir.', 28153),
(143463, 'esMX', '', 'Egoíh\'ta y sin honor... Harías bien en buscar otro camino, pequeñ$go:a;.', 28153),
(143462, 'esMX', '', 'Interesante... $USigiloso y astuto:Sigilosa y astuta;, atacas desde las sombra\'. Tu mejor arma serán los ataques inesperados.', 28153),
(143461, 'esMX', '', 'Entiendo. Ereh\' veloz y $gobservador:observadora;, asestas golpes con prudencia. Tu paciencia será recompensada.', 28153),
(143460, 'esMX', '', 'Mira en tu interior, hij$go:a;. Muéh\'trame cómo cazarás a tu presa. ¿Con sabiduría, fuerza o con algo completamente distinto?', 28153),
(143459, 'esMX', '', 'El grupo te llama con determinación. Acepta los lazo\' de hermandad y caza con tus hermanos y hermanas.', 28153),
(143458, 'esMX', '¿Huele\' eso? Hay olor a repollo.$b$b<Kronah se acerca y te olfatea.>$b$bNo ere\' tú, pero es algo por aquí. $b$bDime, ¿qué tal es tu caligrafía? ¿Quiere\' que te dé una clase? Aunque no lo crea\', soy maestra escriba.', '', 28153),
(143457, 'esMX', '¡Nos atacan!', '¡Nos atacan!', 28153),
(143456, 'esMX', '¡Preparen su acero, hermanos y hermanas!', '¡Preparen su acero, hermanos y hermanas!', 28153),
(143455, 'esMX', '¡Hay enemigos entre nosotros!', '¡Hay enemigos entre nosotros!', 28153),
(143454, 'esMX', '¡Intruso! ¡A las armas!', '¡Intruso! ¡A las armas!', 28153),
(143452, 'esMX', 'Encantado.', '', 28153),
(143451, 'esMX', '¡Muévanse!', '', 28153),
(143450, 'esMX', '¡Tenemos órdenes que cumplir!', '', 28153),
(143449, 'esMX', '', 'Por favor, no distraigas a $Ueste niño:esta niña;.\n\nEh\'toy buscando conexiones de los niños con los loa. Los que hayan recibido la bendición de un loa recibirán el entrenamiento completo para convertirse en sacerdote\', junto con todo el honor y privilegio del título.\n\nLos que no hayan recibido la bendición tendrán la oportunidad de demoh\'trar que se convertirán en guerreros fuertes.\n\nLos que fracasen en ambas pruebah\' no nos sirven. Seguramente acaben robando en los puertos o mendigando en el Zócalo.', 28153),
(143448, 'esMX', 'Puedo hacerlo.', '', 28153),
(143447, 'esMX', 'Okey McKey.', '', 28153),
(143446, 'esMX', 'Trabajo, trabajo.', '', 28153),
(143445, 'esMX', '¡Necesitamos más madera!', '', 28153),
(143444, 'esMX', 'Ya descansarán cuando estén muertos. ¡Ahora tenemos órdenes que cumplir!', '', 28153),
(143443, 'esMX', 'Regresaré a la aldea lo máh\' rápido posible, antes de que todo desaparezca. Quizá no me hayan olvidado.', '', 28153),
(143442, 'esMX', 'No creo que pueda regresar a mi vieja vida. Como un simio ignorante. No despuéh\' de lo que he visto y experimentado, por breve que haya sido.', '', 28153),
(143441, 'esMX', 'Da\'ka eh\'taba en lo cierto. Ya siento que mi mente vuelve a su estado primitivo.', '', 28153),
(143440, 'esMX', 'Hola, $gviajero:viajera;. ¿Puedo interesarte en unos pergaminos?$b$b¿O quizás unas tintas exóticas fabricadas con las hierbas más extrañas?', '', 28153),
(143439, 'esMX', 'Estos goblins tienen cerebros minúsculos, probablemente tendrás que aplastar a unos cientos más para que aprendan.', '', 28153),
(143438, 'esMX', '¡Has hecho un gran trabajo al enseñarle a estos goblins a no meterse con los enanos Hierro Negro!', '', 28153),
(143437, 'esMX', '¡Acaba con sus máquinas! ¡Destruye sus herramientas! ¡Aplasta a todos los patanes verdes que te cruces!', '', 28153),
(143436, 'esMX', '¡Estos goblins están corrompiendo la azerita a gran escala! ¡No podemos permitirlo!', '', 28153),
(143435, 'esMX', 'Ferromazo por fin está a nuestro alcance. ¡Enséñales a estos goblins lo que sucede cuando les robas a los Hierro Negro!', '', 28153),
(143434, 'esMX', '¿Quién anda ahí? ¿Quién detiene la niebla? ¡El rey Da\'ka te matará!', '', 28153),
(143433, 'esMX', '¡Por la Horda!', '¡Por la Horda!', 28153),
(143432, 'esMX', 'Tikita mira a los cerdos con hambre.', '', 28153),
(143431, 'esMX', 'Tikita se contonea y juega.', '', 28153),
(143430, 'esMX', '', '¿Quién es la pequeña raptor devoradora de cabeza\'? ¡Tú! ¡Sí, tú, tú!', 28153),
(143429, 'esMX', '', '¡Ah, qué bueno que esté\' aquí, pequeña! $n... gracias.', 28153),
(143428, 'esMX', '', '¡¿Esa e\' Tikita?!', 28153),
(143427, 'esMX', 'Tikita trina con alegría.', '', 28153),
(143426, 'esMX', '', 'Habrá... más...', 28153),
(143425, 'esMX', '', 'El sol se pone en el Imperio zandalari. ¡Los infieles tomarán lo que queda!', 28153),
(143424, 'esMX', '¡Haré que te arrastren y te descuarticen por eso!', '¡Haré que te arrastren y te descuarticen por eso!', 28153),
(143423, 'esMX', 'Tikita levanta el hocico para oler el viento. Luego, lanza un grito de entusiasmo.', '', 28153),
(143422, 'esMX', '¡Te arrodillarás ante tu reina, $Gcampesino:campesina;!', '¡Te arrodillarás ante tu reina, $Ucampesino:campesina;!', 28153),
(143421, 'esMX', 'Ella... también... te atrapará...', 'Ella... también... te atrapará...', 28153),
(143420, 'esMX', '¡La casa Canto Tormenta dominará estas tierras!', '¡La casa Canto Tormenta dominará estas tierras!', 28153),
(143419, 'esMX', '', '¡Gracias a los dos por su ayuda! $n, prepárate para ir a la cueva de Colatriste a ayudar a Ben\'jin cuando esto funcione.', 28153),
(143418, 'esMX', '', 'Podría haber creado un dispositivo para leer los patrones mentales de los brutosaurios y realizar un análisis. Es solo un comentario.', 28153),
(143417, 'esMX', '', 'La ciencia es la única respuesta, Jangalar. No quiero faltar el respeto a tus poderes, pero la superstición no puede contra la lógica y la fuerza de la alquimia.', 28153),
(143416, 'esMX', '¡Esos humanos débiles conocerán la fuerza de la Horda!', '', 28153),
(143415, 'esMX', '¡Más les vale a esos humanos que nos teman, o conocerán nuestras espadas!', '', 28153),
(143414, 'esMX', '¡Por la Horda!', '', 28153),
(143413, 'esMX', 'Regresaré a Zuldazar... No te preocupe\' por mí, puedo volver por mi cuenta. Ven a verme la próxima vez que estés en la ciudad.', '', 28153),
(143412, 'esMX', 'Espera, Jin\'Tiki. Llévate el raptor. Despué\' de todo, parece que tú... le agradas más que yo.', '', 28153),
(143411, 'esMX', '¡Estén atentos! ¡Que ningún humano se acerque a nuestro aserradero!', '', 28153),
(143410, 'esMX', '¡Más rápido!', '', 28153),
(143409, 'esMX', 'Parece que nuestro trabajo aquí ha terminado. Hora de volver a Vol\'dun y pagar por mis fechoría\'.', '', 28153),
(143408, 'esMX', 'Si veo a alguien holgazaneando, ¡yo mismo lo arrojaré a los lobos!', '', 28153),
(143407, 'esMX', '¡Sigan así, consigan más recursos!', '', 28153),
(143404, 'esMX', 'Tu fin... se acerca...', 'Tu fin... se acerca...', 28153),
(143403, 'esMX', 'Cómo es... posible...', 'Cómo es... posible...', 28153),
(143402, 'esMX', '', 'Reúne a tu\' bestias y ve a la ciudad. Cuando terminemos, ¡te daré una cesta llena de cabeza\' de serpientes!', 28153),
(143401, 'esMX', 'Te enfrentarás... al ojo... de la tormenta...', 'Te enfrentarás... al ojo... de la tormenta...', 28153),
(143400, 'esMX', 'Tú... caerás...', 'Tú... caerás...', 28153),
(143399, 'esMX', 'Allí. Desde allí se alzan la\' nieblas.', '', 28153),
(143398, 'esMX', 'Mi alma... fluye... hacia el mar...', 'Mi alma... fluye... hacia el mar...', 28153),
(143397, 'esMX', 'Me dirijo... a... las profundidades...', 'Me dirijo... a... las profundidades...', 28153),
(143396, 'esMX', '¡Mataron a nuestro jefe! ¡Toda la aldea eh\'tá perdida!', '', 28153),
(143395, 'esMX', 'El reh\'piradero principal ehtá dentro. ¡Rápido!', '', 28153),
(143394, 'esMX', 'Regreso... a las profundidades...', 'Regreso... a las profundidades...', 28153),
(143391, 'esMX', 'Incluso la marea... retrocede...', 'Incluso la marea... retrocede...', 28153),
(143390, 'esMX', '¡Su poder corre por mis venas!', '¡Su poder corre por mis venas!', 28153),
(143389, 'esMX', '¡Acepta tu fin!', '¡Acepta tu fin!', 28153),
(143388, 'esMX', '¡Los tentáculos del destino te atraparán!', '¡Los tentáculos del destino te atraparán!', 28153),
(143387, 'esMX', '¡Yacerás inerte en el fondo del mar!', '¡Yacerás inerte en el fondo del mar!', 28153),
(143386, 'esMX', '¡Tú luz se desvanecerá en las profundidades!', '¡Tú luz se desvanecerá en las profundidades!', 28153),
(143385, 'esMX', '¡Nadie puede detener la marea!', '¡Nadie puede detener la marea!', 28153),
(143384, 'esMX', '¡Escucha el llamado de las profundidades!', '¡Escucha la llamada de las profundidades!', 28153),
(143383, 'esMX', '¡El mar se llevará tus restos!', '¡El mar se llevará tus restos!', 28153),
(143382, 'esMX', 'Y así cae... el rey Da\'ka.', '', 28153),
(143381, 'esMX', '', 'Pero... me prometieron... grandeza...', 28153),
(143380, 'esMX', '¡$GVillano:Villana;! ¡Vete, no aparezcas delante de mí, so pena de mi ira!', '', 28153),
(143379, 'esMX', '', 'Eres fuerte, ¡pero caerás ante el aquelarre como todos los demás!', 28153),
(143378, 'esMX', '', 'No importa. Tu descubrimiento pronto morirá contigo. ¡Ataquen, mis mascotas! ¡Jajajajaja!', 28153),
(143377, 'esMX', '', 'Así que nos encontraste. Debes creerte muy $glisto:lista;.', 28153),
(143376, 'esMX', '¡Ja! ¿Para qué sirve la inteligencia si no da poder? Seré rey de Zandalar. ¡Lo verás con tus propios ojos o morirás!', '', 28153),
(143375, 'esMX', 'No puedes seguir con eh\'to, Da\'ka. Esta inteligencia no era nuestro destino, ¡ni tampoco marchar a la guerra!', '', 28153),
(143374, 'esMX', 'Tsanga... ha\' traído un ser inferior a este lugar, hacia las niebla\' sagradas. ¿A qué has venido?', '', 28153),
(143373, 'esMX', '¿Qué está pasando aquí?', '¿Qué está pasando aquí?', 28153),
(143372, 'esMX', 'Vi la verdad... en el fondo del mar...', 'Vi la verdad... en el fondo del mar...', 28153),
(143371, 'esMX', 'Tengo agua salada... en las venas...', 'Tengo agua salada... en las venas...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'esMX', 'Ve. El origen de las niebla\' está en esta cueva. No sé dónde estará el rey Da\'ka. ¡Apresúrate!', '', 28153),
(143369, 'esMX', 'La magia de sangre es fuerte aquí. No hace falta ser médico brujo para sentirla en el aire... está en todas parte\'...', '', 28153),
(143368, 'esMX', '', 'Ah... ¿qué estás haciendo aquí, continental?\n\n¿Puedo ayudarte con algo?', 28153),
(143367, 'esMX', '¿A quién quieres que mate?', '', 28153),
(143366, 'esMX', '¡Taz\'dingo!', '', 28153),
(143365, 'esMX', '¡Por la Horda!', '', 28153),
(143364, 'esMX', '¡Es hora de matar!', '', 28153),
(143363, 'esMX', 'Matar e\' fácil.', '', 28153),
(143362, 'esMX', '¡Sin piedad!', '', 28153),
(143361, 'esMX', '¡Van a rodar alguna\' cabezas!', '', 28153),
(143360, 'esMX', '¡Gloria a la Horda!', '', 28153),
(143359, 'esMX', '', '¡Gloria a la Horda!', 28153),
(143358, 'esMX', '', '¡Van a rodar alguna\' cabezas!', 28153),
(143357, 'esMX', '', '¡Sin piedad!', 28153),
(143356, 'esMX', 'Jamás... descansaremos...', 'Jamás... descansaremos...', 28153),
(143355, 'esMX', 'Mi muerte... no cambia nada...', 'Mi muerte... no cambia nada...', 28153),
(143354, 'esMX', 'Ya... hemos ganado...', 'Ya... hemos ganado...', 28153),
(143353, 'esMX', '', 'Matar e\' fácil.', 28153),
(143352, 'esMX', 'Solo... cumplía órdenes...', 'Solo... cumplía órdenes...', 28153),
(143351, 'esMX', 'Maresabios... protéjanme...', 'Maresabios... protéjanme...', 28153),
(143350, 'esMX', 'Mi vida... por el mar....', 'Mi vida... por el mar....', 28153),
(143349, 'esMX', '¡Kul Tiras le pertenece al mar!', '¡Kul Tiras le pertenece al mar!', 28153),
(143348, 'esMX', '¡Cómo te atreves a desafiar a Canto Tormenta!', '¡Cómo te atreves a desafiar a Canto Tormenta!', 28153),
(143347, 'esMX', '¡Somos incansables como el mar!', '¡Somos incansables como el mar!', 28153),
(143346, 'esMX', '¡Todos los que se nos opongan morirán!', '¡Todos los que se nos opongan morirán!', 28153),
(143345, 'esMX', '¡Nuestra flota te aplastará!', '¡Nuestra flota te aplastará!', 28153),
(143344, 'esMX', '', '¡Es hora de matar!', 28153),
(143343, 'esMX', '', '¡Ven conmigo, hermana!', 28153),
(143342, 'esMX', '¡Kul Tiras se hundiría sin nosotros!', '¡Kul Tiras se hundiría sin nosotros!', 28153),
(143341, 'esMX', '', '¡Ven conmigo, hermano!', 28153),
(143340, 'esMX', 'El valle es nuestro, ¡rata de sentina!', 'El valle es nuestro, ¡rata de sentina!', 28153),
(143339, 'esMX', '¡Por Canto Tormenta!', '¡Por Canto Tormenta!', 28153),
(143338, 'esMX', '', 'Cuánto\' saurios muertos... Lo\' crié desde que eran solo un huevo. E\' como ver morir a mis hijos.$b$bLo\' hombres serpiente van a pagar.', 28153),
(143337, 'esMX', 'Una corrupción gigante envuelve la estructura cercana. Se requiere acción inmediata.', '', 28153),
(143336, 'esMX', 'Restauración parcial finalizada. Se debe continuar para reparar la contención de la corrupción.', '', 28153),
(143335, 'esMX', 'Mejorando sistemas auxiliares. Un momento...', '', 28153),
(143334, 'esMX', '¿Puedes reparar mi equipo?', '¿Puedes reparar mi equipo?', 28153),
(143333, 'esMX', 'La aldea ya no existe más, pero tendrán que arrancarme la forja de mi\' manos frías y muertas.', '', 28153),
(143332, 'esMX', '', '¡Por la Horda!', 28153),
(143331, 'esMX', '', '¡Taz\'dingo!', 28153),
(143330, 'esMX', '', '¿A quién quieres que mate?', 28153),
(143329, 'esMX', 'Me alegra que los inocentes estén a salvo, pero queda mucho por hacer.', '', 28153),
(143328, 'esMX', '', 'Solo había oído historias de Ventormenta hasta ahora. Exploraré sus calles y las maravillas que esconden. Que las sombras te guíen, $n.', 28153),
(143327, 'esMX', 'Que la Luz te acompañe, $n. Planeo buscar a la Legión en Azeroth para continuar nuestra eterna batalla.', '', 28153),
(143326, 'esMX', 'No voy a hacerlo, claro... pero lo pensé. ¡Casi durante un segundo entero!', '', 28153),
(143325, 'esMX', 'Debo admitirlo, cuando los veo trabajar casi me convenzo de separar una parte de las ganancias para ustedes.', '', 28153),
(143324, 'esMX', '¡Excelente! Pero aún faltan las labores más heroicas... Firmar todos estos formularios de titularidad de la mina. Que todo parezca prolijo y oficial.', '', 28153),
(143323, 'esMX', 'Hablando en serio, será mejor destruirlos antes de que dañen mis ganancias.', '', 28153),
(143322, 'esMX', 'Objetivo completado. Avanzando a la posición delantera. Acercarse a la nueva ubicación.', '', 28153),
(143321, 'esMX', '¡Ja! Miren a esos pobres tontos, los están matando. Esos elementales sí que saben dar una paliza.', '', 28153),
(143320, 'esMX', 'Los gruñidos de Tikita son suaves pero amenazantes.', '', 28153),
(143319, 'esMX', '¡Tikita pía llena de anguh\'tia!', '', 28153),
(143318, 'esMX', '¡¿El mundo sangra y ustedes abren la herida?! ¡Mueran!', '', 28153),
(143317, 'esMX', 'Quiero ver explosiones, caos, ¡y violencia desmedida! Ya saben... eso que les sale tan bien.', '', 28153),
(143316, 'esMX', 'Muéstrenles a estos emprendedores de Ventura y Cía. que nada de lo que tienen está a salvo de mis garras.', '', 28153),
(143315, 'esMX', 'Pero hay un problema... ¡no me pertenece! Y por eso los necesito.', '', 28153),
(143314, 'esMX', 'Así que de aquí venía toda la azerita del mercado negro, ¿eh? No está nada mal.', '', 28153),
(143313, 'esMX', '', 'No sé qué será \"pesadilla de huargen\" pero... Un momento... ¿Qué es esto?', 28153),
(143312, 'esMX', 'Eras demasiado bueno para este mundo, hermano. Me aseguraré de que recibas un entierro digno.', '', 28153),
(143311, 'esMX', '¡Me encanta el olor del mojo por la mañana!', '', 28153),
(143310, 'esMX', '', 'Rokhan dijo que tenías experiencia con eh\'te tipo de cosa\'. Haz lo que puedas. Yo eh\'taré aquí, eh\'perando al escuadrón goblin.', 28153),
(143308, 'esMX', '', '$n, necesitamo\' toda la ayuda que podamo\' conseguir. Ayuda a eh\'te guardián... lo más rápido que pueda\'.', 28153),
(143307, 'esMX', 'Se requiere asistencia. Reparar a Hezrel. Ingresar en la estructura cercana. Contener la corrupción dentro de Nazmir.', '', 28153),
(143306, 'esMX', 'Gran corrupción detectada en Nazmir. Se debe efectuar una contención.', '', 28153),
(143305, 'esMX', 'He peleado en muchas batalla\'... pero no había visto un monstruo como eh\'te... nunca...', '', 28153),
(143304, 'esMX', '¡Nunca me atraparás con vida!', '', 28153),
(143303, 'esMX', 'Bien, ¡Vol\'dun debe ser má\' seguro que este lugar!', '', 28153),
(143302, 'esMX', '¡No! ¡Eso no! Los raptore\'... ¡me comerán!', '', 28153),
(143301, 'esMX', 'Gracias, Zaluto... Quizá en otra vida fuimos hermanos.', '', 28153),
(143300, 'esMX', '¡Usa el fetiche sangriento sobre Zulajin para absorber su poder y enviarlo de regreso a la tumba!', '', 28153),
(143299, 'esMX', '¡No te preocupe\', colega! ¡Me encargaré del capitán aquí mientras tú despejas las ruina\'!', '', 28153),
(143298, 'esMX', '¡Bien! ¡Ahora nos ponemo\' el camuflaje y nos apoderamo\' de la llave!', '', 28153),
(143297, 'esMX', 'Necesitarás un disfraz para burlar a Zulajin. ¡Regresa rápido en cuanto tenga\' los suministro\'!', '', 28153),
(143296, 'esMX', 'Seré un criminal, pero no soy cruel. ¡No te abandonaré aquí para que muera\'!', '', 28153),
(143295, 'esMX', 'Gracia\' a ti, si muero... muero con mi honor intacto...', '', 28153),
(143294, 'esMX', '¡Atención, atención! ¡Un brindis por $Gel valiente:la valiente; <hic> $Gcampeón:campeona; que nos salvará a todos!', '', 28153),
(143293, 'esMX', '', 'Ve a Orgrimmar. Únete a nuestros aliados y forjemos un nuevo futuro juntos.', 28153),
(143292, 'esMX', '', 'Recorre los caminos de Azeroth y cuenta la orgullosa historia de los Natonocturno a todos... Que sepan que ya no vivimos aislados.', 28153),
(143291, 'esMX', '¿Qué sabemos acerca de los Natonocturno?', '¿Qué sabemos acerca de los Natonocturno?', 28153),
(143290, 'esMX', '', '$n, me alegra que vinieras. Debemos convencer a la Jefa de Guerra de buscar la lealtad de los Natonocturno.', 28153),
(143289, 'esMX', '¿Qué sabemos acerca de los tauren de Altamontaña?', '¿Qué sabemos acerca de los tauren de Altamontaña?', 28153),
(143288, 'esMX', '', 'Ahora es nuestro momento de demostrar la fuerza y el honor que aportamos a la Horda.', 28153),
(143287, 'esMX', 'Compartimos muchas cosas con los tauren de Altamontaña. Creo que serían aliados ideales para los tiempos que se avecinan.', '', 28153),
(143286, 'esMX', '', 'No te preocupe\' por Tsanga. Nosotro\' nos encargaremo\' de él, aunque ya no recuerde ni su propio nombre...', 28153),
(143285, 'esMX', '', 'Vaya que era grande, ¿no crees? ¡Buen trabajo, $gamigo:amiga;!', 28153),
(143284, 'esMX', '', 'Que las estrellas te guíen, $p. He oído cosas intrigantes sobre las Laderas de Trabalomas. Es muy probable que viaje allí.', 28153),
(143283, 'esMX', '', '¿Estás seguro de eh\'to, Tsanga? ¿Sabes lo que perderás si $Ueste:esta; adalid disipa las niebla\'?', 28153),
(143282, 'esMX', 'Prepararé el ritual para liberar estas almas. Veámonos en la costa al norte de aquí.', '', 28153),
(143281, 'esMX', 'Comprendo las consecuenciah\'. Sin embargo, aunque cuesta perder algunas cosas, a veces está bien que así sea.', '', 28153),
(143280, 'esMX', 'Tomaré otro camino hah\'ta el Cañón y te veré allí.', '', 28153),
(143279, 'esMX', '¡No rompan filas! Los refuerzos están en camino. ¡No podemos dejar que los nagas destruyan el dique!', '', 28153),
(143278, 'esMX', 'Que tu corazón olvide el odio.', '', 28153),
(143277, 'esMX', '', 'Pero los sin\'dorei, los elfos de sangre, nos trataron con respeto y comprensión. Los de su clase nos demostraron que había otros en Azeroth que compartían nuestros valores.', 28153),
(143276, 'esMX', '', 'Cuando nuestra ciudad estaba en su peor momento, los héroes de Azeroth lucharon junto a nosotros para expulsar a la Legión. Algunos, contra su propia voluntad.', 28153),
(143275, 'esMX', '', 'Te entrego el atuendo tradicional de Suramar. Que te sirva como recordatorio de nuestro pasado... y del futuro que forjaremos junto a nuestros aliados.', 28153),
(143274, 'esMX', '¡No tienes que repetirlo!', '', 28153),
(143273, 'esMX', '', 'Le has demostrado a la Horda, y a todos los habitantes de Azeroth, que los Natonocturno poseen voluntad y valor para defender nuestro mundo.', 28153),
(143272, 'esMX', 'Ábrete paso hasta la costa al otro lado del patio. Busca a una joven cadete de los Valiente: Taelia. ¡Ve!', '', 28153),
(143271, 'esMX', '', 'Regresa a Suramar para que podamos agradecerte por ayudarnos a recuperar un lugar en este mundo.', 28153),
(143270, 'esMX', '', 'Estás entre los primeros shal\'dorei que salen a explorar el mundo salvaje de Azeroth. Pero ya es hora de regresar a casa.', 28153),
(143269, 'esMX', 'Estos obreros... ¡son prisioneros de la magia de los maresabios! Debemos ayudarlos.', '', 28153),
(143268, 'esMX', 'Gracias a las mareas que no todos perdieron la cordura. ¡La mitad de la casa ha enloquecido!', '', 28153),
(143267, 'esMX', 'Esta camisa a cuadros está de más.', 'Esta camisa a cuadros está de más.', 28153),
(143266, 'esMX', '', 'Yo me adelantaré. ¡Nos vemos en la costa!', 28153),
(143265, 'esMX', 'Luces bien, $n.', '', 28153),
(143264, 'esMX', 'Tenemos trabajo que hacer.', '', 28153),
(143263, 'esMX', 'Me vendría bien una camisa a cuadros.', 'Me vendría bien una camisa a cuadros.', 28153),
(143262, 'esMX', '', '¡A las armas!', 28153),
(143261, 'esMX', '', '¡Por el rey!', 28153),
(143260, 'esMX', '', '¡Toma esto!', 28153),
(143259, 'esMX', '', '¡Hasta la muerte!', 28153),
(143258, 'esMX', '', '¡Por Ventormenta!', 28153),
(143257, 'esMX', '', '¡Por la Alianza!', 28153),
(143256, 'esMX', '', '¡Nadie retrocede!', 28153),
(143255, 'esMX', '', '¡Déjenmelos a mí!', 28153),
(143254, 'esMX', '', '¿Qué quieres decir con \"corrupción\"? $n, quizás eh\'ta cosa ve a los trols de sangre como \"corrupción\".', 28153),
(143253, 'esMX', '', '$n, ¿sabes que es eh\'ta cosa? ¿Crees que querrá ayudarno\'?', 28153),
(143252, 'esMX', '', '¡¿Pero qué vudú es eh\'te?! Quizá sirva para detener a lo\' trols de sangre y a G\'huun...', 28153),
(143251, 'esMX', '¡Déjenmelos a mí!', '', 28153),
(143250, 'esMX', '¡Nadie retrocede!', '', 28153),
(143249, 'esMX', '¡Por la Alianza!', '', 28153),
(143248, 'esMX', '¡Por Ventormenta!', '', 28153),
(143247, 'esMX', '¡Hasta la muerte!', '', 28153),
(143246, 'esMX', '¡Toma esto!', '', 28153),
(143245, 'esMX', '¡Por el rey!', '', 28153),
(143244, 'esMX', '¡A las armas!', '', 28153),
(143243, 'esMX', 'Uooh, el detector ha enloquecido. Seguramente hubo una explosión enorme de azerita en algún lugar de la isla.', '', 28153),
(143242, 'esMX', 'Tenemos que descubrir la fuente de esta profanación.', '', 28153),
(143241, 'esMX', '', 'Que esta armadura te recuerde todos los logros que has alcanzado, $p. Acepta esto como muestra de mi gratitud.', 28153),
(143240, 'esMX', 'Desde luego.', '', 28153),
(143239, 'esMX', 'Eh... Di... Dime...¿crees que las criaturas marinas también han sido afectadas?', '', 28153),
(143238, 'esMX', 'Y aquí hay otro \"mal presagio\". La bahía está llena de presas de los Firmemares.', '', 28153),
(143237, 'esMX', 'Tsanga mira la entrada de la cueva, preocupado.', '', 28153),
(143236, 'esMX', '', 'Muchos dudaban de la capacidad de los ren\'dorei para canalizar el poder del Vacío sin caer presos de su influencia. Tú les has demostrado que estaban equivocados.', 28153),
(143235, 'esMX', 'Los gritos del agua se hacen más fuertes a medida que ingresamos en la bahía. Siento el tormento de las mareas. Esto es un mal presagio.', '', 28153),
(143234, 'esMX', '', 'Te has convertido en un arma formidable para la Alianza, $p. Regresa a la falla del Vacío para que honremos tus logros.', 28153),
(143233, 'esMX', 'Terminemos este trabajo.', '', 28153),
(143230, 'esMX', 'Comenzaré a trabajar en el entrenamiento. Tú ve a ver a Tagart, tiene más trabajo para ti.', '', 28153),
(143229, 'esMX', 'Guardián titánico Hezrel reiniciado. Protocolo: contener la corrupción dentro de Nazmir. Tarea imposible de completar debido a daños en los sistemas.', '', 28153),
(143228, 'esMX', '', 'En tus viajes por todo Azeroth, lograste dominar a las fuerzas que constantemente buscan controlarte.', 28153),
(143227, 'esMX', 'Qué buen ejemplar, $gamigo mío:amiga mía;. Veamos cómo vuela. ¡Vamos!', '', 28153),
(143226, 'esMX', '¡Jo, jo! ¡Mira lo que trajo la marea! ¡Increíble!', '', 28153),
(143224, 'esMX', 'Le avisaré al rey Rastakhan que cuando la\' torres ardan, habremos recuperado nuestros navío\'. ¡Esa será la señal para que la tripulación sepa que puede volver a casa!', '', 28153),
(143223, 'esMX', 'La temática necesaria no se nota con claridad en esta imagen. A Wulferd no le gustará esto.', 'La temática necesaria no se nota con claridad en esta imagen. A Wulferd no le gustará esto.', 28153),
(143222, 'esMX', '¡Ayúdame, por favor, $gamigo:amiga;!', '', 28153),
(143221, 'esMX', 'Oh... Mis trabajadores... les fallé.', '', 28153),
(143220, 'esMX', '', '¡Ayuda! ¡Han herido al comandante!', 28153),
(143219, 'esMX', '¡Ayuda! ¡Me atacan!', '', 28153),
(143218, 'esMX', '¡Pagarán por eso!', '', 28153),
(143217, 'esMX', '¡Este sujeto sí que me hace enfadar!', '', 28153),
(143216, 'esMX', '¡No! ¡Las primas de mi seguro!', '', 28153),
(143215, 'esMX', '¡¿Para qué les pago, idiotas?! ¡Vengan a arreglar esto!', '', 28153),
(143214, 'esMX', '¿Qué tal una masacre de alto calibre?', '', 28153),
(143213, 'esMX', '¡Prueben la fuerza de 300 disparos por minuto!', '', 28153),
(143212, 'esMX', 'Este es tu lugar: ¡justo bajo mis pies!', '', 28153),
(143211, 'esMX', '¡Come tierra!', '', 28153),
(143210, 'esMX', '', 'Exploraré un poco y nos reuniremos más adelante en el camino.', 28153),
(143209, 'esMX', '¡Nunca me atraparán con vida! ¡Ja, ja, ja, ja!', '', 28153),
(143208, 'esMX', 'Debí... incluir... un... asiento eyector...', '', 28153),
(143207, 'esMX', 'Le cobraré las municiones gastadas a tu familia.', '', 28153),
(143206, 'esMX', '', 'Usa las lecciones que te he enseñado para mantener el control. Conviértete en un arma para la Alianza... aún desde el filo de la oscuridad.', 28153),
(143205, 'esMX', 'Muchos te cuestionarán... cuestionarán tu entereza y tu habilidad de dominar un poder que llevó a la locura a otros cuya fuerza de voluntad era más débil.', '', 28153),
(143204, 'esMX', '', 'Pero vemos alternativas. Vemos muchos caminos... muchas posibilidades se abren ante nosotros.', 28153),
(143203, 'esMX', '', 'Algunos te dirán que la Luz es el único camino, la única arma capaz de detener a los enemigos de Azeroth.', 28153),
(143202, 'esMX', '¡¿Son conscientes del daño que han causado, imbéciles!?', '', 28153),
(143201, 'esMX', '¡$GBienvenido:Bienvenida; a los Rabaleros!', '', 28153),
(143200, 'esMX', 'E\' como dijo esa vieja serpiente. Sube. El rey espera.', '', 28153),
(143199, 'esMX', '¡Machacar! ¡Sí!', '', 28153),
(143198, 'esMX', '¡Aplastar!', '', 28153),
(143197, 'esMX', '¡Pulverizar!', '', 28153),
(143196, 'esMX', 'E\' un pena que no haya podido enseñarle la lección más importante de toda\'.', '', 28153),
(143195, 'esMX', 'Avísale al viejo Rastakhan que volveré cuando sea el momento. Oh... y gracia\' por tu ayuda.', '', 28153),
(143193, 'esMX', 'Cuando atrape a Yazma y Zul, ¡los lanzaré contra las rocas!', '', 28153),
(143192, 'esMX', 'Nuestra presa está cerca. Pronto derramaremos la sangre de Zul, Yazma y sus herejes. Será una gran cacería.', '', 28153),
(143191, 'esMX', '¡Gloria a Pa\'ku!', '¡Gloria a Pa\'ku!', 28153),
(143190, 'esMX', '¡La nave será nueh\'tra!', '¡La nave será nueh\'tra!', 28153),
(143189, 'esMX', '¡Taz\'okun!', '¡Taz\'okun!', 28153),
(143188, 'esMX', 'Es una herida superficial. Creo que estaré bien.', '', 28153),
(143185, 'esMX', '', '¡Las llamas los reclamarán!', 28153),
(143184, 'esMX', '', '¡Ardan! ¡Sí! ¡Ardan!', 28153),
(143183, 'esMX', '', '¿Buscaban azerita? ¿Qué tal una muestra?', 28153),
(143182, 'esMX', '', '¡Oh, oh! Parece que tendré que poner el marcador de \"días sin muertes truculentas\" en cero.', 28153),
(143181, 'esMX', '¡Nada vale la pena esto!', '', 28153),
(143180, 'esMX', '', '¡La falta de experiencia es mortal!', 28153),
(143179, 'esMX', '¡Por la Alianza!', '', 28153),
(143178, 'esMX', '', 'Es un honor servirlo una vez más, Alto Rey. ¡Por la Alianza!', 28153),
(143177, 'esMX', '', '¡$uOtro:Otra; aspirante sin calificaciones!', 28153),
(143176, 'esMX', 'Han hecho un gran trabajo por la Alianza, Lady Brisaveloz, $p. Se los agradezco.', '', 28153),
(143175, 'esMX', 'Quizá lleve un poco de tiempo que los elfos del Vacío se ganen la confianza de algunas de nuestras tropas. Pero mientras cumplan con tus enseñanzas, serán bienvenidos a la Alianza.', '', 28153),
(143174, 'esMX', '', 'Debí exigir... pago adicional... por los riesgos...', 28153),
(143173, 'esMX', '', 'Seré su guía. Los entrenaré para que controlen los susurros de las sombras. A cambio, lucharán por la Alianza contra todos sus enemigos.', 28153),
(143172, 'esMX', '', 'Alto Rey Wrynn, $p y yo hemos encontrado a los sin\'dorei exiliados. Al igual que a mí, el Vacío los ha cambiado, pero no los despojó de sus corazones y sus mentes.', 28153),
(143171, 'esMX', '', 'Si quieres un trabajo bien hecho... ¡usa explosivos más grandes!', 28153),
(143170, 'esMX', '', '¿Tú provocaste que mi fuerza laboral se dispersara?', 28153),
(143169, 'esMX', '', '¡Oigan! ¿A dónde creen que van?', 28153),
(143168, 'esMX', '¡¿Intrusos?! ¡Corran!', '¡¿Intrusos?! ¡Corran!', 28153),
(143167, 'esMX', 'No sé qué oscuridad se apoderó de tu mente, hermana, pero ya no atormentará a nuestro pueblo.', '', 28153),
(143166, 'esMX', '¡Tú puedes!', '', 28153),
(143165, 'esMX', '¡A correr!', '', 28153),
(143164, 'esMX', '', '¡No quiero más quejas sobre condiciones laborales peligrosas!', 28153),
(143163, 'esMX', 'Este lugar no es seguro. Deben marcharse.', '', 28153),
(143162, 'esMX', '¡De todas formas, no es una gran isla!', '', 28153),
(143161, 'esMX', '¡Estamos condenados!', '', 28153),
(143160, 'esMX', '¡Lárguense! Ya cumplieron con su trabajo.', '', 28153),
(143159, 'esMX', '¡Se ha liberado! ¡Regresa!', '', 28153),
(143158, 'esMX', 'Ya son libres, hermanos y hermanas.', '', 28153),
(143157, 'esMX', '', '¡Si se quejan, es que no están conteniendo la respiración! Así que es su culpa si inhalan las emanaciones tóxicas.', 28153),
(143156, 'esMX', 'Vayan con sus familias. Nosotros nos encargaremos de esto.', '', 28153),
(143155, 'esMX', '¡Huyan, idiotas!', '', 28153),
(143154, 'esMX', 'Que tu alma abandone su forma mortal y fluya hacia las aguas.', '', 28153),
(143153, 'esMX', 'Escucha el canto de la tormenta, y conoce la paz.', '', 28153),
(143152, 'esMX', 'Nunca preguntes por quién brilla el faro. Brilla por ti.', '', 28153),
(143151, 'esMX', '', '¡Por la Horda!', 28153),
(143150, 'esMX', '', '¡Por la Horda!', 28153),
(143149, 'esMX', '', '¡Suramar luchará con la Horda!', 28153),
(143148, 'esMX', '', 'Durante miles de años, Suramar resistió en soledad. A partir de hoy, se convierten en parte de algo más grande. Acepto tu juramento, Thalyssra.', 28153),
(143147, 'esMX', '', 'Es hora de que los Natonocturno encuentren aliados en los reinos de Azeroth. Si nos aceptas, será un honor para nosotros jurar lealtad a tu causa.', 28153),
(143146, 'esMX', '', 'La Horda representa la fuerza. La determinación. La individualidad. Valores que los shal\'dorei también compartimos.', 28153),
(143145, 'esMX', '', 'Ciertamente, Primera Arcanista.', 28153),
(143144, 'esMX', '', 'Es un honor, jefa de guerra. He luchado junto a Lady Liadrin y el Señor regente. La valentía de ellos es un motivo de orgullo para la Horda.', 28153),
(143143, 'esMX', 'No temas, hermano. Las olas no juzgan tu superficie.', '', 28153),
(143142, 'esMX', 'Braman las olas, limpian sonoras, las penas de tu alma rota.', '', 28153),
(143141, 'esMX', 'Tu espíritu intrépido descansará por toda la eternidad.', '', 28153),
(143140, 'esMX', 'Que las profundidades abisales reciban tu alma agobiada.', '', 28153),
(143139, 'esMX', 'Que la Madre de las mareas purifique tu carne corrupta.', '', 28153),
(143138, 'esMX', 'Las corrientes te llevarán, hermano caído.', '', 28153),
(143137, 'esMX', '¡La tierra los consumirá!', '', 28153),
(143136, 'esMX', 'Mar al mar, cenizas a las cenizas, mareas a las mareas.', '', 28153),
(143135, 'esMX', '¡Tiemblen!', '', 28153),
(143134, 'esMX', '¡La sangre de Azeroth fluye por tus venas!', '', 28153),
(143133, 'esMX', 'No podemos permitir que estas almas perdidas sigan vagando. Debo hablar contigo, $p.', '', 28153),
(143132, 'esMX', '¡Libera tu poder!', '', 28153),
(143131, 'esMX', 'Quedó empapado, pero aún es legible. Estos encantamientos nos serán útiles.', '', 28153),
(143130, 'esMX', 'Las brumas del océano ocultan mucho, pero este faro nos servirá de guía.', '', 28153),
(143129, 'esMX', '¡Levántense!', '', 28153),
(143128, 'esMX', '', '$UBienvenido, pequeño:Bienvenida, pequeña;. Es posible que mis ojos me hayan abandonado, pero Pa\'ku no.\n\nSiéntate conmigo y hazme toda\' las pregunta\' que quieras sobre los grandiosos loa; trataré de responderla\' de la mejor forma posible.', 28153),
(143127, 'esMX', 'Bien, la hoja aún tiene filo. Una hoja afilada es una hoja segura.', '', 28153),
(143126, 'esMX', 'Ya no causarás más daño.', '', 28153),
(143125, 'esMX', '¿Para qué sirve tu sangre?', '', 28153),
(143124, 'esMX', '', 'Jefa de guerra Sylvanas Brisaveloz, le presento a la Primera Arcanista Thalyssra de Suramar.', 28153),
(143123, 'esMX', '', 'Me uniré a los demás y esperaré tus órdenes, $c.', 28153),
(143122, 'esMX', '', 'Yo tengo mis dudas... pero haré lo que me ordenen.', 28153),
(143121, 'esMX', '', '¿Así que el mariscal Reade cree que eres la clave para derrotar al aquelarre?', 28153),
(143120, 'esMX', '¡Golpeen con fuerza!', '', 28153),
(143119, 'esMX', 'Ya era hora.', '', 28153),
(143118, 'esMX', '¡Vamos, con fuerza!', '', 28153),
(143117, 'esMX', '¡Tiren!', '', 28153),
(143116, 'esMX', 'Ven, Winston. Parece que tenemos que luchar contra algunas brujas.', '', 28153),
(143115, 'esMX', 'Un par de cortes profundos más y será nuestro.', '', 28153),
(143114, 'esMX', '¡Ya casi! Solo un poco más.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'esMX', '¿Hay nuevas órdenes?', '', 28153),
(143112, 'esMX', 'Gracias por traer estas órdenes, $c. Me presentaré ante la señorita Tarjasenda de inmediato.', '', 28153),
(143111, 'esMX', 'Y yo que creía que las historias solo eran fruto de la imaginación febril de un historiador.', '', 28153),
(143110, 'esMX', 'No eran más que parásitos.', '', 28153),
(143109, 'esMX', '¿Así que los rumores son ciertos? ¿Han reformado la Orden de las Ascuas?', '', 28153),
(143108, 'esMX', 'Las heridas... deben sanar...', '', 28153),
(143107, 'esMX', '', 'Mi arma está a tu servicio, $c.', 28153),
(143106, 'esMX', '¡Se han metido en mis dominios!', '', 28153),
(143105, 'esMX', '', 'No me creo esas brujerías, pero cualquier cosa es mejor que quedarnos sentados esperando a que el aquelarre nos mate a todos.', 28153),
(143104, 'esMX', '', 'Así que eres tú quien está comandando esta famosa Orden de las Ascuas.', 28153),
(143103, 'esMX', '<Entrega las órdenes del mariscal Reade.>', '<Entrega las órdenes del mariscal Reade.>', 28153),
(143102, 'esMX', '', 'Los ensamblajes comienzan a entrar en la batalla. Se había quedado sin guerreros vivos y creó un ejército nuevo. Pero ¿cómo les dio vida a las piedras?', 28153),
(143101, 'esMX', '', '¿Qué puedo hacer por ti, $c?', 28153),
(143100, 'esMX', '', 'Claramente este es Gorak Tul, su líder más famoso. ¡Ah! ¡Dirige un ritual para crear los ensamblajes de piedra!', 28153),
(143099, 'esMX', '<El teniente Severola asiente levemente con la cabeza para indicar que te ha visto.>', '', 28153),
(143098, 'esMX', 'Un lindo espécimen, ¿no? Se sabe que la casa Tarjasenda es experta en cetrería.\n\nLamentablemente, casi todas nuestras mejores aves han caído bajo la maldición del aquelarre. Este es Winston, uno de los pocos halcones de Tarjasenda que no ha caído en el embrujo.\n\nEs una situación muy triste.', '', 28153),
(143097, 'esMX', '', 'Qué es esto... ¡Han glorificado la matanza! ¡Los kultiranos ni siquiera tienen armas!', 28153),
(143096, 'esMX', 'Algo maligno se agita en los bosques, continental. En sus entrañas, hay un monumento drust que brilla con poder profano por las noches.\n\nSi fuera tú, evitaría ese lugar en tus viajes.', '', 28153),
(143095, 'esMX', '', '¿Qué quieres, continental?\n\nPor si no te has dado cuenta, estoy un poco ocupada.', 28153),
(143094, 'esMX', 'ELIMINAR INTRUSO. P-PURIFICAR. PURIFICAR.', '', 28153),
(143093, 'esMX', 'LIBERACIÓN INMINENTE DE CORRUPCIÓN. ACT-ACTIVANDO PROTOCOLOS DE SEG-SEG-SEGURIDAD. INTR-INTRUSO DETECTADO.', '', 28153),
(143092, 'esMX', 'ERROR... INTRUSO...DET-DETECTADO... ANALIZANDO PRESENCIA DE... CORRUPCIÓN.', '', 28153),
(143091, 'esMX', 'Uso de gas nocivo aprobado.', '', 28153),
(143090, 'esMX', 'Voltaje aumentado.', '', 28153),
(143089, 'esMX', 'Sistemas en línea. Iniciar aporreo.', '', 28153),
(143088, 'esMX', '', 'Parece que los kultiranos que se ven en esta estela son... civiles, marineros y algunos granjeros.', 28153),
(143087, 'esMX', '', 'Hasta su líder se retira del campo de batalla.', 28153),
(143086, 'esMX', '', '¡JA! ¡Y aquí estamos contraatacando!', 28153),
(143085, 'esMX', '', 'Es interesante que no veamos ninguno de sus ensamblajes en el campo de batalla.', 28153),
(143084, 'esMX', 'Ventura y Cía. agradece su confianza. Disfrute de su compra del paquete de aporreo de élite.', '', 28153),
(143083, 'esMX', '', 'Es una victoria sobre otro asentamiento kultirano. Creo que la figura grande del centro es su líder legendario.', 28153),
(143082, 'esMX', 'Ventura y Cía. agradece su confianza. Disfrute de su compra del paquete de aporreo básico.', '', 28153),
(143081, 'esMX', '¡Dame unos meses y convertiré este lugar en un hotel de lujo seis estrellas!', '', 28153),
(143080, 'esMX', '¡Idiota! ¡NUNCA compres la extensión de garantía!', '¡Idiota! ¡NUNCA compres la extensión de garantía!', 28153),
(143079, 'esMX', '¡Bueno, bueno! Espera... ¿debería comprar la extensión de garantía?', '¡Bueno, bueno! Espera... ¿debería comprar la extensión de garantía?', 28153),
(143078, 'esMX', '', '', 28153),
(143077, 'esMX', '¡Nos van a matar!', '¡Nos van a matar!', 28153),
(143076, 'esMX', '¡No me presiones! ¡Estoy leyendo el contrato de licencia!', '¡No me presiones! ¡Estoy leyendo el contrato de licencia!', 28153),
(143075, 'esMX', '¡Rápido! ¡Aquí vienen!', '¡Rápido! ¡Aquí vienen!', 28153),
(143074, 'esMX', 'Necesitaba descansar un poco.', '', 28153),
(143073, 'esMX', 'Tranquila, chica. Tranquila.', '', 28153),
(143072, 'esMX', 'Sistemas... fallando. Devolución de moneda… fuera de línea...', '', 28153),
(143071, 'esMX', '¿Quién quiere volar un poco? ¿Tú quieres salir a volar? ¡Vamos a volar!', '', 28153),
(143070, 'esMX', '¡No muerdas!', '', 28153),
(143069, 'esMX', 'Rutina de control de daños activada.', '', 28153),
(143068, 'esMX', 'Dañar esta unidad viola las condiciones de uso.', '', 28153),
(143067, 'esMX', '¡Fuera bombas!', '¡Fuera bombas!', 28153),
(143066, 'esMX', '¡Cuidado abajo, escorias!', '¡Cuidado abajo, escorias!', 28153),
(143065, 'esMX', '¡Ey, tú! ¡Vuelve al trabajo!', '¡Ey, tú! ¡Vuelve al trabajo!', 28153),
(143064, 'esMX', 'Fuerza letal autorizada.', '', 28153),
(143063, 'esMX', 'La multitud supera el máximo permitido. Dispérsense.', '', 28153),
(143062, 'esMX', 'Servicios fúnebres a precios accesibles.', '', 28153),
(143061, 'esMX', 'Otro cliente satisfecho.', '', 28153),
(143060, 'esMX', 'Ventura y Cía. no se responsabiliza por la devolución de extremidades perdidas.', '', 28153),
(143059, 'esMX', '¡La Horda se ha defendido de un asalto!', '¡La Horda se ha defendido de un asalto!', 28153),
(143058, 'esMX', '¡Y dispérsense! Esos cerdos de la Alianza enviarán refuerzos a nuestra posición.', '', 28153),
(143057, 'esMX', '', 'Cuando esta nave llegue al puerto, ¡yo me convertiré en capitán! ¡Será mejor que te prepare\' y que aprendas a remar duro!', 28153),
(143056, 'esMX', '', '¡Esto\' prisioneros no tienen idea de la suerte que tienen! En poco tiempo se van a encontrar con Zul.', 28153),
(143055, 'esMX', '', 'Si vamos a tomar eh\'te puerto, ¡debes esforzarte un poco más!', 28153),
(143054, 'esMX', 'No puedo... evitar... ¡AAAAAAAUUURGH!', '', 28153),
(143050, 'esMX', '¡No! ¡No moriré aquí! ¡Aún no me ha llegado la hora!', '', 28153),
(143049, 'esMX', 'Cómo... lo supo...', '', 28153),
(143048, 'esMX', 'Esto... ¡Esto no está sucediendo!', '', 28153),
(143047, 'esMX', 'Ere\' fuerte, ¡pero mi Visión es más fuerte!', '', 28153),
(143046, 'esMX', '¡Aléjense! ¡Es una orden!', '', 28153),
(143045, 'esMX', '¡Mis elegido\'! ¡Su maestro los necesita!', '', 28153),
(143044, 'esMX', '¡El único que morirá aquí seráh\' tú!', '', 28153),
(143043, 'esMX', '¡No corre\' con ventaja sobre mí, viejo engreído!', '', 28153),
(143042, 'esMX', 'Tienes razón. Pero mi amigo se encargará.', '', 28153),
(143041, 'esMX', 'Los dos sabemo\' que no me matarás. No puede\' detenerme.', '', 28153),
(143040, 'esMX', 'Buena chica. ¡Ya casi es hora de un bocadillo!', '', 28153),
(143039, 'esMX', 'Me cansé de eh\'te juego. Has dado tu mensaje. Ahora es tiempo de enfrentar tu destino.', '', 28153),
(143038, 'esMX', 'Zul bebe la poción de un solo trago y se eh\'tremece por su sabor.', '', 28153),
(143037, 'esMX', 'Será la primera en la que poses los ojo\'. No puedes dudar.', '', 28153),
(143036, 'esMX', 'Sus esbirro\' tratarán de detenerte. No bajes la guardia.', '', 28153),
(143035, 'esMX', 'Mmm.', '', 28153),
(143034, 'esMX', 'Ven aquí. Ya e\' hora.', '', 28153),
(143033, 'esMX', 'Bien, ahora cambia una de las pocione\' de Vol\'jamba por la que te he dado.', '', 28153),
(143032, 'esMX', 'Ahora que lo pienso... muévela un poco a la ih\'quierda.', '', 28153),
(143031, 'esMX', 'Ahora prepara la urna cerca del arco.', '', 28153),
(143030, 'esMX', 'Espera fuera de la embajada con las armas listas, $p. Los zandalari no tienen la fuerza necesaria para mantener el control. Necesitan a una jefa de guerra fuerte como la nuestra.\n\nBien, ¿en qué puedo ayudarte?', 'Espera fuera de la embajada con las armas listas, $p. Los zandalari no tienen la fuerza necesaria para mantener el control. Necesitan a una jefa de guerra fuerte como la nuestra.\n\nBien, ¿en qué puedo ayudarte?', 28153),
(143029, 'esMX', 'Si ves a algún miembro de la Alianza merodeando, avísame. Me encargaré de él.\n\nMientras tanto, ¿qué necesitas?', 'Si ves a algún miembro de la Alianza merodeando, avísame. Me encargaré de él.\n\nMientras tanto, ¿qué necesitas?', 28153),
(143028, 'esMX', 'Si hay algo que puedo decir de los zandalari es que saben construir embajadas. ¡Y esta ciudad es enorme!\n\n¿Estás $Uperdido:perdida;?', 'Si hay algo que puedo decir de los zandalari es que saben construir embajadas. ¡Y esta ciudad es enorme!\n\n¿Estás $Uperdido:perdida;?', 28153),
(143027, 'esMX', 'Estoy ocupado. Que sea rápido.', 'Estoy ocupada. Que sea rápido.', 28153),
(143026, 'esMX', '¿Qué necesitas, $pr?', '¿Qué necesitas, $pr?', 28153),
(143025, 'esMX', '¡Gloria a la jefa de guerra! ¿Buscas algo?', '¡Gloria a la jefa de guerra! ¿Buscas algo?', 28153),
(143024, 'esMX', 'Esta embajada enorme demuestra que los zandalari respetan a nuestra jefa de guerra. También deberían temerle.\n\nBien, ¿en qué puedo ayudarte?', 'Esta embajada enorme demuestra que los zandalari respetan a nuestra jefa de guerra. También deberían temerle.\n\nBien, ¿en qué puedo ayudarte?', 28153),
(143023, 'esMX', 'Esta humedad hace que me suden los huesos. ¿En qué puedo ayudarte?', 'Esta humedad hace que me suden los huesos. ¿En qué puedo ayudarte?', 28153),
(143022, 'esMX', 'Nos vamos, grandote. Algún día, toda esta tierra será nuestra.', '', 28153),
(143021, 'esMX', '¿Para qué te pagamos? ¿Para holgazanear?', '', 28153),
(143020, 'esMX', '', 'Tal vez la muerte sea el verdadero legado de los Brisaveloz.', 28153),
(143019, 'esMX', '', 'Sí. A veces siento que ya he muerto dos veces. Primero, cuando nos creyeron perdidos en Draenor, y luego cuando la sombra de los naaru caídos se apoderó de mí.', 28153),
(143018, 'esMX', 'Ver nuestros propios monumentos conmemorativos es perturbador.', '', 28153),
(143017, 'esMX', '', 'Es hora, Turalyon. Debo volver a ver mi hogar con mis propios ojos... y preguntarle a Sylvanas cómo pudo tomar el cargo de jefa de guerra.', 28153),
(143016, 'esMX', 'Cada una tiene un camino que seguir. Si la Luz dicta que esos caminos se crucen, así será. No es necesario forzar la mano del destino.', '', 28153),
(143015, 'esMX', 'No hace falta que vayas. No hace falta que la veas.', '', 28153),
(143014, 'esMX', '', 'Como nadie, mi amor.', 28153),
(143013, 'esMX', 'Estás nerviosa. Lo escondes bien... pero te conozco.', '', 28153),
(143012, 'esMX', 'Sé que nos esperan muchos desafíos en los días que se avecinan. Pero, pase lo que pase... ¡nunca olviden nuestro deber con Azeroth!', '', 28153),
(143011, 'esMX', 'La energía que fluye por tu arma... ¡jamás había visto algo así! Pero recuerda: todo poder tiene un precio.', '', 28153),
(143010, 'esMX', '¡Lo lograron! La espada de Sargeras está aletargada. Azeroth aún no ha sanado... pero, gracias a ustedes, hemos ganado mucho tiempo.', '', 28153),
(143009, 'esMX', '¡Juntos, adalides! ¡Por Azeroth!', '', 28153),
(143008, 'esMX', 'Álcenlas a la vez... ¡extraigan la corrupción de la espada del Titán oscuro!', '', 28153),
(143007, 'esMX', 'Lo único que puede contener semejante poder... son las armas poderosas que ustedes blanden.', '', 28153),
(143006, 'esMX', 'La espada de Sargeras está envenenando la fuerza vital del mundo.', '', 28153),
(143005, 'esMX', 'Vengan a Silithus... ¡mientras aún tenemos un mundo por el que luchar!', '', 28153),
(143004, 'esMX', 'Sé que las tensiones son cada vez mayores... pero les pido que nos unamos una vez más.', '', 28153),
(143003, 'esMX', 'Adalides, una vez unieron sus órdenes y lucharon juntos para expulsar a la Legión de Azeroth.', '', 28153),
(143002, 'esMX', 'La tempestad se avecina, $p. Si no encontramos una forma de curar a Azeroth... ya nada importará.', '', 28153),
(143001, 'esMX', 'No sé cómo arreglar esto. No creo que nadie sepa. Pero tenemos que seguir intentando.', '', 28153),
(143000, 'esMX', 'Desde que regresé de Argus, los llantos de Azeroth han sido... abrumadores. Cuánto dolor...', '', 28153),
(142999, 'esMX', 'Adalid... es bueno ver una cara conocida en estos tiempos oscuros.', '', 28153),
(142998, 'esMX', 'Aún los estamo\' esperando, princesa. Pero conseguimo\' una pista sobre el loa, Krag\'wa.', '', 28153),
(142997, 'esMX', '', '... y ese es el destino de Torga. ¿Qué noticia\' hay sobre lo\' refuerzo\' de la Horda?', 28153),
(142996, 'esMX', 'Ya casi terminamos, $n. Solo avanzaremo\' un poco más.', '', 28153),
(142995, 'esMX', 'No puedo creer que esos monstruos destriparan a Torga...', '', 28153),
(142994, 'esMX', 'Torga está muerto y ahora no tengo nada que contarles a los demás cuando regrese.', '', 28153),
(142993, 'esMX', '¿Dónde está Kisha? Creí que estaría aquí para darnos indicaciones...', '', 28153),
(142992, 'esMX', 'De acuerdo, iré a Hondonada Penumbrosa para saber hasta dónde llegará esto.', '', 28153),
(142991, 'esMX', 'Vaya... Bueno, supongo que la lucha contra una horda de trols de sangre puede ser una historia interesante. De acuerdo, iré a Hondonada Penumbrosa.', '', 28153),
(142990, 'esMX', '¿Que ustedes hicieron... QUÉ? No pienso perderme esta historia. Me dirigiré a las ruinas de Hondonada Penumbrosa.', '', 28153),
(142989, 'esMX', 'Bueno, Kisha. Vayamos a Hondonada Penumbrosa y reunamos a cuantos podamos de nuestro pueblo. $n, ocúpate tú de los que queden.', '', 28153),
(142988, 'esMX', '', 'Iré a Hondonada Penumbrosa mientras tú te encarga\' de los tortollano\' en el camino.', 28153),
(142987, 'esMX', '¡$n, encárgate de esos cañones!', '', 28153),
(142986, 'esMX', 'Buena suerte, $p. Por mi parte, voy a probar mi destreza en Vallefresno. ¡Por la Horda!', '', 28153),
(142985, 'esMX', 'El Aliento de Pa\'ku y la Zarpa de Rezan dieron la vuelta al mundo. Ayúdalas a que lleguen a su hogar.', '', 28153),
(142984, 'esMX', 'Cuando las nave\' regresaron, una oscuridad las acompañaba. Luego, un sentimiento horrible se apoderó de mi estómago.', '', 28153),
(142983, 'esMX', 'El Aliento de Pa\'ku fue mi hogar durante muchos años. Mi corazón, al igual que eh\'te puerto, quedó vacío cuando zarpó.', '', 28153),
(142982, 'esMX', 'El rugido de Anji la Eh\'truendosa te llena de vigor.', '', 28153),
(142981, 'esMX', '¡Eh! ¡Súbete al bote! ¡El capitán dice que el Aliento de Pa\'ku eh\'tá en problemas!', '', 28153),
(142980, 'esMX', '', 'Comandante, vinimos a ayudar. ¡El dique no caerá hoy!', 28153),
(142979, 'esMX', '', 'Vayamos hacia el dique. ¡Al comandante Reed no le gusta esperar!', 28153),
(142977, 'esMX', '¡Tú no eres $Gdigno:digna; de este lugar!', '', 28153),
(142976, 'esMX', '¡Eres $Gun necio:una necia; y $Gun:una; cobarde!', '', 28153),
(142975, 'esMX', '¡Te desprecio, infame compañía!', '', 28153),
(142974, 'esMX', '¡Lárgate de aquí, $Gbribón:bribona;!', '', 28153),
(142973, 'esMX', '¡Te daré una paliza majestuosa!', '', 28153),
(142972, 'esMX', '¡Vete de mi presencia, monstruo de naturaleza!', '', 28153),
(142971, 'esMX', '¡Cuidado! ¡En mucho más se ha de estimar un diente que un diamante!', '', 28153),
(142970, 'esMX', '¡Atención!', '', 28153),
(142969, 'esMX', '', 'Por la autoridad investida en mí por la casa Tarjasenda, los nombro inquisidores de la Orden de las Ascuas.', 28153),
(142968, 'esMX', '', 'Hoy serán la luz de la esperanza contra el enemigo eterno.', 28153),
(142967, 'esMX', '', 'Hoy serán la espada resplandeciente que atraviesa a los viles.', 28153),
(142966, 'esMX', '', 'Hermanos y hermanas, hoy serán el fuego ardiente que abrasa la oscuridad.', 28153),
(142965, 'esMX', '', 'Ah, es esto.', 28153),
(142964, 'esMX', '', 'Había algunas palabras de iniciación en el tomo. Veamos...', 28153),
(142963, 'esMX', '', 'Gracias por cedernos a sus hombres, mariscal. ¡Ya empezamos a parecer una verdadera orden!', 28153),
(142962, 'esMX', 'Llevo días eh\'perando una audiencia con el rey. Cualquiera creería que eh\'tá más interesado en lo que están haciendo los goblins aquí.', '', 28153),
(142961, 'esMX', 'Tenemos muchos soldados posicionados aquí, milady. Serán excelentes reclutas para su Orden de las Ascuas.', '', 28153),
(142960, 'esMX', '', 'Mariscal, puede que hayamos encontrado armas para usar contra el aquelarre. Necesitamos soldados aptos para empuñarlas.', 28153),
(142959, 'esMX', '¡Jamá\' traicionaría a los loa ni a la ciudad!', '', 28153),
(142958, 'esMX', 'Yo adoro a Pa\'ku. ¡La magia de sangre eh\'tá prohibida!', '', 28153),
(142957, 'esMX', 'Les digo la verdá\'. ¡No sé nada sobre reliquias de sangre!', '', 28153),
(142956, 'esMX', '¡Soy inocente! Por favor, piedá\'.', '', 28153),
(142955, 'esMX', 'Nunca trafiqué con reliquia\' de sangre. ¡La magia de sangre e\' maléfica!', '', 28153),
(142954, 'esMX', '¡Nunca vi una reliquia de sangre!', '', 28153),
(142953, 'esMX', '¡No sé de qué hablan!', '', 28153),
(142952, 'esMX', '¡No hice nada malo!', '', 28153),
(142951, 'esMX', 'No me haga\' apuñalarte otra vez...', '', 28153),
(142950, 'esMX', '¿A quién le vendiste reliquia\' de sangre?', '', 28153),
(142949, 'esMX', 'Me da\' asco, traidor.', '', 28153),
(142948, 'esMX', 'Te haré sufrir, Pro\'ditor. Y luego te usaremo\' como ejemplo para los demá\'.', '', 28153),
(142947, 'esMX', 'Si confiesa\', prometo que te mataré rápido.', '', 28153),
(142946, 'esMX', 'Ere\' una basura de la peor clase, Pro\'ditor. ¡La magia de sangre mata a nuestra gente!', '', 28153),
(142945, 'esMX', 'Sabemo\' que has estado contrabandeando reliquias de sangre en la ciudad.', '', 28153),
(142944, 'esMX', '¡Dinos cómo conseguiste las reliquia\' de sangre, Pro\'ditor!', '', 28153),
(142943, 'esMX', 'Esta eh\'coria ha estado traficando reliquia\' de sangre y las ha metido en nuestra ciudad.\n\nPrimero lo haremo\' confesar, y luego lo usaremo\' de ejemplo para todos los demás.', '', 28153),
(142942, 'esMX', '¡No hice nada malo! ¡Diles!', '', 28153),
(142941, 'esMX', '(Marcharse)', '(Marcharse)', 28153),
(142940, 'esMX', '<Es casi imposible reconocer a Teshyambi, el prófugo, en esos restos hechos jirones y cubiertos de sangre. Parece que esto es obra de los raptores de las cercanías.>', '<Es casi imposible reconocer a Teshyambi, el prófugo, en esos restos hechos jirones y cubiertos de sangre. Parece que esto es obra de los raptores de las cercanías.>', 28153),
(142939, 'esMX', 'Sé quién eres, Mojoba. Dirígete a Vol\'dun y vive en paz en tu exilio.', 'Sé quién eres, Mojoba. Dirígete a Vol\'dun y vive en paz en tu exilio.', 28153),
(142938, 'esMX', '¿Quién eres? ¿Qué quieres, eh?', '', 28153),
(142937, 'esMX', 'Lo siento, pero te han exiliado a Vol\'dun por los delitos que cometiste.', 'Lo siento, pero te han exiliado a Vol\'dun por los delitos que cometiste.', 28153),
(142936, 'esMX', '¡Shh! Me estoy ocultando de los raptore\' y de Zulajin. Tengo que regresar a Zuldazar.', '', 28153),
(142935, 'esMX', '', 'Trabajas bien... para ser $Gun fugitivo:una fugitiva;.', 28153),
(142934, 'esMX', '', 'Ahora que controlamos la prisión y tenemos las llaves, podemos empezar a recuperar la azerita y liberar a los rehenes.', 28153),
(142933, 'esMX', '', 'Parece que lady Aspafresno tendrá una vacante para un nuevo sobrestante después de todo.', 28153),
(142932, 'esMX', '¡Vigila tu fuego! Te hablo a ti, lanzallamas. ¡Si alguna de estas municiones de azerita explota, quedaremos hechos polvo!', '', 28153),
(142931, 'esMX', '¡Firmes, hombres! ¡Ahí vienen!', '', 28153),
(142930, 'esMX', '', 'Terminaremos de asegurar los niveles inferiores mientras ustedes se dirigen al sobrestante.', 28153),
(142929, 'esMX', '', 'Buen trabajo. Parece que ya tienen todo bajo control.', 28153),
(142928, 'esMX', 'Después de apoderarnos de los rehenes del sobrestante, ¡estaremos hasta los hocicos en dinero de rescate!', '', 28153),
(142927, 'esMX', '¡Vamos, muchachos! ¡Derriben esas puertas!', '', 28153),
(142926, 'esMX', '', 'Espero que tengas razón, o el primer trabajo de tu reemplazo será observar cómo te ahogas con el resto de esta escoria.', 28153),
(142925, 'esMX', 'Lo siento, Lady Aspafresno. Mis hombres no tardarán en restaurar el orden.', '', 28153),
(142924, 'esMX', '', '¡Korgus! ¿¡Dime por qué no inundaste los niveles inferiores y ahogaste a estas ratas apestosas!?', 28153),
(142923, 'esMX', '', '¡Uuf! ¿Tuvieron que arrastrarse por aquí para escapar? No se paren delante del viento.', 28153),
(142922, 'esMX', '', 'Esa criatura explica por qué el sobrestante no envió muchas patrullas a este lado de la isla. Hicieron bien en derrotarla.', 28153),
(142921, 'esMX', '', 'Nos encargaremos de los guardias del perímetro mientras ustedes van a la rejilla de la cloaca. Así podremos acceder a la prisión.', 28153),
(142920, 'esMX', '', 'Nuestro informe de inteligencia indica que las llaves para abrir los depósitos de azerita y el ala de rehenes están en posesión del sobrestante... las tiene colgadas del cuello.', 28153),
(142919, 'esMX', '', '¡Abajo! Aún no nos han visto.', 28153),
(142918, 'esMX', '¿Es necesario?', '', 28153),
(142917, 'esMX', '¿Qué quieres?', '', 28153),
(142916, 'esMX', 'Listo para la acción.', '', 28153),
(142915, 'esMX', '¡Han destruido nuestro cuartel!', '', 28153),
(142914, 'esMX', 'Vamos a necesitar refuerzos para ganar esta guerra.', '', 28153),
(142913, 'esMX', '¡De vuelta al trabajo!', '', 28153),
(142912, 'esMX', '¡Este edificio no se construirá solo!', '', 28153),
(142911, 'esMX', '¡Quiero oír esos martillos!', '', 28153),
(142910, 'esMX', '', 'Alleria adopta una postura desafiante.', 28153),
(142909, 'esMX', '¡Me salvaste la vida!', '¡Me salvaste la vida!', 28153),
(142908, 'esMX', 'Creo que ya puedo regresar sin problemas. Gracias.', 'Creo que ya puedo regresar sin problemas. Gracias.', 28153),
(142907, 'esMX', 'Sus ataques son implacables. Gracias por tu ayuda.', 'Sus ataques son implacables. Gracias por tu ayuda.', 28153),
(142906, 'esMX', 'No olvidaré tu valentía.', 'No olvidaré tu valentía.', 28153),
(142905, 'esMX', '¡Creí que iba a morir aquí!', '¡Creí que iba a morir aquí!', 28153),
(142904, 'esMX', '¡A nuestra aldea le vendrían bien más héroes como tú!', '¡A nuestra aldea le vendrían bien más héroes como tú!', 28153),
(142903, 'esMX', 'Venga a los que no pudieron ser salvados.', 'Venga a los que no pudieron ser salvados.', 28153),
(142902, 'esMX', '¡Estos nagas son monstruos!', '¡Estos nagas son monstruos!', 28153),
(142901, 'esMX', '¡Les clavaré este puñal justo en las costillas!', '', 28153),
(142900, 'esMX', '¡Están llegando intrusos a través de las cloacas!', '', 28153),
(142898, 'esMX', 'Esta piedra canta una canción silenciosa y potente. Hay solo una persona que puede oír su melodía, y por nuestro bien, esperemos que nunca encuentre el camino a estas costas.', '', 28153),
(142897, 'esMX', 'He visto todo lo que necesitaba. Esta piedra es maléfica y hay que destruirla.', '', 28153),
(142894, 'esMX', 'No creo que se rinda por las buenas, así que deberán arrancarle esa arma de las manos frías.', '', 28153),
(142893, 'esMX', 'He visto a nuestra próxima presa en el sur. Deben moverse rápido.', '', 28153),
(142892, 'esMX', 'Qué lástima que destruir ese navío les permita a los kultiranos reagruparse.', '', 28153),
(142891, 'esMX', 'Seguramente la Dama Oscura apreciará su servicio.', '', 28153),
(142890, 'esMX', '', 'Será un placer, Señor regente. Nos veremos en Lunargenta, adalid.', 28153),
(142889, 'esMX', '¡Excelente! Lady Liadrin, te ruego que vuelvas a Orgrimmar y le lleves la buena nueva a la jefa de guerra.', '', 28153),
(142888, 'esMX', '', 'En nombre de los Natonocturno, acepto tu propuesta. A partir de este día, Suramar luchará por la Horda.', 28153),
(142887, 'esMX', 'La Horda te ofrece eso, Primera Arcanista. Únete a nosotros. Las puertas de Lunargenta siempre están abiertas para ti.', '', 28153),
(142886, 'esMX', '', 'Suramar siempre será nuestro hogar. Pero algunos de los nuestros desean aventurarse en el mundo y reclamar nuevamente nuestro lugar en Azeroth. Para lograrlo, necesitamos aliados.', 28153),
(142885, 'esMX', '', 'Obtenemos fuerza de nuestros aliados, pero no hemos olvidado quiénes somos.', 28153),
(142884, 'esMX', '', 'En absoluto. Este conflicto ha demostrado tu dedicación por tu pueblo. Puedo ver que la Horda te ha permitido mantener tus tradiciones, algo que es muy importante para nosotros.', 28153),
(142883, 'esMX', 'Lamento que hayas tenido que presenciar ese intercambio, Thalyssra. Tenía otros planes para tu visita.', '', 28153),
(142882, 'esMX', '', 'Como lo ordenes, Señor regente. Por ahora.', 28153),
(142881, 'esMX', '¡Ya basta! Márchate de inmediato, Alleria. Aunque haya sido un accidente, tu presencia es un peligro para Quel\'Thalas. Regresa a Ventormenta... Lunargenta ya no es tu hogar.', '', 28153),
(142880, 'esMX', '', '¡No seré prisionera en mi propia tierra!', 28153),
(142879, 'esMX', '¡Guardias! ¡Atrapen a esta saboteadora!', '', 28153),
(142878, 'esMX', 'La Fuente del Sol está a salvo. Tu ayuda ha sido invaluable, Thalyssra. Igual que la tuya, adalid.', '', 28153),
(142877, 'esMX', '¡Solo retrasas lo inevitable! De todas formas tendré mi premio.', '', 28153),
(142876, 'esMX', '', '¡Ahora! ¡Une tu poder al mío!', 28153),
(142875, 'esMX', 'La puerta se abre. Sí... Esto se ajusta a nuestras necesidades.', '', 28153),
(142874, 'esMX', '', 'Dinos qué debemos hacer y aportaremos nuestra fuerza.', 28153),
(142873, 'esMX', '', 'Puedo cerrar la falla, pero necesitaré ayuda.', 28153),
(142872, 'esMX', 'Algo está tratando de abrir una falla en la cámara. Si lo logra, quizá perdamos la Fuente del Sol.', '', 28153),
(142871, 'esMX', 'Comienza a lanzar el hechizo, Rikal.', 'Comienza a lanzar el hechizo, Rikal.', 28153),
(142870, 'esMX', 'Tarde o temprano la marea cambiará. Como siempre.', '', 28153),
(142869, 'esMX', '¡Tu Agarre está fallando!', '', 28153),
(142868, 'esMX', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t¡%s se prepara para lanzar |cFFFF0000|Hspell:257785|h[Dagas voladoras]|h|r! ¡Ocúltate!', '', 28153),
(142867, 'esMX', 'Bal\'a dash, malanore.', '', 28153),
(142866, 'esMX', 'Cada uno debe seguir su propio camino.', '', 28153),
(142865, 'esMX', 'Nuestro pueblo representa un nuevo futuro.', '', 28153),
(142864, 'esMX', 'No hay verdades incuestionables.', '', 28153),
(142863, 'esMX', 'El universo está lleno de misterios.', '', 28153),
(142862, 'esMX', 'Hay oportunidades ante nuestros ojos.', '', 28153),
(142861, 'esMX', 'El pasado está escrito. El futuro no.', '', 28153),
(142860, 'esMX', 'Shorel\'aran.', '', 28153),
(142859, 'esMX', 'Nuestro pueblo no le teme a las sombras.', '', 28153),
(142858, 'esMX', 'No hay una sola verdad.', '', 28153),
(142857, 'esMX', 'Los susurros no nos controlan.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'esMX', 'Hay que contener los impulsos.', '', 28153),
(142855, 'esMX', 'No le temas al poder. Contrólalo.', '', 28153),
(142854, 'esMX', 'Ten en cuenta todas las posibilidades.', '', 28153),
(142853, 'esMX', 'No lograrás provocarme con tu comportamiento infantil.', '', 28153),
(142852, 'esMX', '¿\"Recuerda la Fuente del Sol\"? Por favor. Eso quedó atrás hace mucho tiempo.', '', 28153),
(142851, 'esMX', 'Si bajo tus pies se abriera un portal hacia la nada infinita y te consumiera en mi presencia, te aseguro que sería pura casualidad. Los accidentes existen.', '', 28153),
(142850, 'esMX', 'Ah, claro. Una fuerza cósmica conocida por inducir locura me transforma, y de pronto todos me consideran \"sospechoso\". Y después dicen que el aspecto físico no importa...', '', 28153),
(142849, 'esMX', '¿Qué buscas?', '', 28153),
(142848, 'esMX', 'Ofrezco artículos extraordinarios de reinos lejanos.', '', 28153),
(142847, 'esMX', 'Todo tiene un precio... Si alguien está dispuesto a pagarlo.', '', 28153),
(142846, 'esMX', 'Espero que tu compra sea satisfactoria.', '', 28153),
(142845, 'esMX', 'Gracias por venir.', '', 28153),
(142844, 'esMX', 'Vuelve cuando quieras.', '', 28153),
