(142820, 'esMX', '', 'Bal\'a dash, malanore.', 28153),
(142819, 'esMX', 'Esa criatura bloquea su ruta de escape. Tendrán que matarla para llegar a nuestros botes del otro lado.', '', 28153),
(142818, 'esMX', '¡¿Lady Aspafresno tiene un kraken?!', '', 28153),
(142817, 'esMX', 'Parece que Aspafresno nos ofreció una salida conveniente. Es hora de irnos y dejar que Boralus arda.', '', 28153),
(142816, 'esMX', 'Esta bestia está usando armas potenciadas con azerita.', '', 28153),
(142815, 'esMX', 'Bal\'a dash, malanore.', '', 28153),
(142814, 'esMX', 'Se hace camino al andar.', '', 28153),
(142813, 'esMX', 'Peleamos por un futuro nuevo.', '', 28153),
(142812, 'esMX', 'No dejes nada sin cuestionar.', '', 28153),
(142811, 'esMX', 'El universo está lleno de misterios.', '', 28153),
(142810, 'esMX', 'Te saludo.', '', 28153),
(142809, 'esMX', 'Se nos han abierto nuevos caminos.', '', 28153),
(142808, 'esMX', 'Shorel\'aran.', '', 28153),
(142807, 'esMX', 'Hay fuerza en la sombra.', '', 28153),
(142806, 'esMX', 'Escribimos nuestro propio destino.', '', 28153),
(142805, 'esMX', 'Los susurros no me controlan.', '', 28153),
(142804, 'esMX', 'Mantén el control. Siempre.', '', 28153),
(142803, 'esMX', 'No hay que temerle al poder. Hay que usarlo.', '', 28153),
(142802, 'esMX', 'Ese barco está repleto de reservas de azerita. Masacren a la tripulación y yo me llevaré el cargamento.', '', 28153),
(142801, 'esMX', 'El Vacío ofrece posibilidades infinitas.', '', 28153),
