(141244, 'esMX', '', '¡Indecorosa! ¡Débil! ¡¿Yo?!', 28153),
(141243, 'esMX', '', '¡Se retorcerán y gritarán mientras les abro las tripas y los devoro!', 28153),
(141238, 'esMX', '', 'Entendido. No te dejaremos ir sin ayuda.', 28153),
(141235, 'esMX', 'Se oye un ruido áspero contra la piedra.', 'Se oye un ruido áspero contra la piedra.', 28153),
(141233, 'esMX', 'Ese maldito añublo nos bloquea el camino. Nuestras fuerzas no pueden seguirla.', '', 28153),
(141232, 'esMX', 'Creando bálsamo', 'Creando bálsamo', 28153),
(141221, 'esMX', 'Dicen que al rey Rastakhan no le está yendo muy bien estos día\'. Es solo cuestión de tiempo ante\' de que todo Zandalar se derrumbe. ¿Y entonce\'? ¿Dónde iremo\' nosotro\'?', 'Dicen que al rey Rastakhan no le está yendo muy bien estos día\'. Es solo cuestión de tiempo ante\' de que todo Zandalar se derrumbe. ¿Y entonce\'? ¿Dónde iremo\' nosotro\'?', 28153),
(141213, 'esMX', 'Las bestias salvajes de Vol\'dun deben conservar su libertad.', '', 28153),
(141212, 'esMX', '', '¡Deja que me coma tu corazón!', 28153),
(141211, 'esMX', '¿Qué sucede?', '¿Qué sucede?', 28153),
(141210, 'esMX', '¿Puedo hacer algo para ayudar?', '¿Puedo hacer algo para ayudar?', 28153),
(141209, 'esMX', '¿Qué pasó?', '¿Qué pasó?', 28153),
(141208, 'esMX', '¿Por qué lloras?', '¿Por qué lloras?', 28153),
(141207, 'esMX', '¡A la orden! ¡La carta llegará prontísimo! ¡A volar, mis bellezas!', '', 28153),
(141206, 'esMX', '¿Puedes enviarle esta carta a Taelia, en Boralus?', '¿Puedes enviarle esta carta a Taelia, en Boralus?', 28153),
(141205, 'esMX', 'Continuará...\n\n¡Gracias por acompañarnos en la BlizzCon!', '', 28153),
(141204, 'esMX', '¿Viene\' a burlarte? ¿Vienes a reírte del orador de un imperio caído?$b$bTodos lo\' trols de Zul\'Drak que no fueron dominados por la Plaga terminaron destruidos. Allí la muerte hace de las suyas, mi gente asesinó a nuestro\' loa, robó el poder de esos dioses para usarlo contra la Plaga y luego ellos también murieron.$b$bAhora, yo estoy aquí casi como una mascota de estos zandalari. Una rareza que usan para mostrarles a su\' hijos algo exótico.$b$bDéjame en paz.', '', 28153),
(141202, 'esMX', '', 'El rechazo del aquelarre me arrancó el alma. ¡Ahora me quedaré con la tuya!', 28153),
(141201, 'esMX', '', 'Bueno, hay una cosa que podría ayudar...', 28153),
(141200, 'esMX', '', 'Pu-pudimos haber tenido un futuro tan maravilloso juntos, pero nos lo arrancaron de las manos.', 28153),
(141199, 'esMX', '', 'Cuando llamaron a mi puerta, tendría que haber sabido... nunca aparecen por cosas buenas.\n\nEn ese momento supe que el sueño había terminado.', 28153),
(141198, 'esMX', '', 'Una pérdida tan... grande... \n\nNo tenía idea de que podía doler tanto...', 28153),
(141197, 'esMX', '¡Eh, tú! ¡Aquí!', '', 28153),
(141196, 'esMX', '<La mujer está sollozando. Estiras tu mano para consolarla.>', '<La mujer está sollozando. Estiras tu mano para consolarla.>', 28153),
(141194, 'esMX', '¿Seguro que quieres teletransportarte al calabozo Atal\'Dazar?', '¿Segura que quieres teletransportarte al calabozo Atal\'Dazar?', 28153),
(141193, 'esMX', '¿Seguro que quieres teletransportarte al calabozo Puerto Libre?', '¿Segura que quieres teletransportarte al calabozo Puerto Libre?', 28153),
(141192, 'esMX', 'Teletransportarse a calabozo: Atal\'Dazar', 'Teletransportarse a Atal\'Dazar', 28153),
(141191, 'esMX', 'Teletransportarse a calabozo: Puerto Libre', 'Teletransportarse a Puerto Libre', 28153),
(141190, 'esMX', '¡Bienvenido a la BlizzCon 2017! Si quieres teletransportarte al calabozo de tu facción, haz clic abajo.', '¡Bienvenida a la BlizzCon 2017! ¡Si quieres teletransportarte al calabozo de tu facción, haz clic abajo!', 28153),
(141189, 'esMX', '', '¡Fuera de mi vih\'ta! ¡No vuelvas hasta que puedas demostrar que ere\' $Gdigno:digna; de estar en mi presencia!', 28153),
(141188, 'esMX', '¡Lo siento! ¡Traté de ayudarlo, pero no soy un guerrero!', '', 28153),
(141187, 'esMX', '', '¡No puedes detener lo que se avecina! Zuldazar no tiene eh\'peranza. Y tú tampoco. ¡G\'huun despierta! ¡G\'huun se alza!', 28153),
(141186, 'esMX', '', '¿Te atreves a matar a NUESTRO loa?... Te perseguiremo\'... te torturaremo\'... ¡te desangraremo\'!', 28153),
(141185, 'esMX', '', '¡Hir\'eek era sirviente de G\'huun! Pagarás por este insulto. Despué\' de Zuldazar... ¡será el turno de la Horda!', 28153),
(141184, 'esMX', '<Rakjan baja la cabeza en señal de respeto.>', '', 28153),
(141183, 'esMX', 'Andando.', 'Andando.', 28153),
(141182, 'esMX', '<Rakjan baja la cabeza en señal de respeto.>', '', 28153),
(141180, 'esMX', '¡Adiós, idiota!', '', 28153),
(141178, 'esMX', 'Supongo que debería mantener un perfil bajo por un tiempo...', '', 28153),
(141177, 'esMX', 'Es una lástima que el hombre tortuga no viniera en persona. Su caparazón podría cotizarse muy bien.', '', 28153),
(141176, 'esMX', 'Estoy formando un grupo de cazadores de demonios tauren. Se llama los Vaca-dari.', '', 28153),
(141175, 'esMX', 'El Vindicaar es una nave veloz. Podría decirse que viaja a la velocidad de la Luz...', '', 28153),
(141174, 'esMX', '', 'Venimos de Bajomontaña, pero con tenacidad llegamos a la cima.', 28153),
(141173, 'esMX', '', '¿Has visto el nuevo baile del Profeta Velen? ¡Lo llama la \"Mac\'Areena\"!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141172, 'esMX', '', 'Bah. Debe <hic> haberse marchado con el rabo entre las patas.', 28153),
(141171, 'esMX', '', '¿Dónde está la escoria sin agallas que está insultando <hic> a los Asaltantes mareaférrea?', 28153),
(141170, 'esMX', '', '¡¿Qué?! <hic!> ¡Ya verán lo que les pasa a los que difaman a MI tripulación!', 28153),
(141169, 'esMX', '¡Yarr! ¡Algún cerebro en salmuera anduvo ensuciando el buen nombre de los Asaltantes mareaférrea! ¡Por allá, detrás de esa construcción!', '¡Yarr! ¡Algún cerebro en salmuera anduvo ensuciando el buen nombre de los Asaltantes mareaférrea! ¡Por allá, detrás de esa construcción!', 28153),
(141168, 'esMX', '¿Qué? ¡Esa vieja urraca debería haber muerto y haberme entregado su alma! Ve, mátala mejor. Tomaré lo que me pertenece.', '', 28153),
(141167, 'esMX', '', '<hic>$B$B¿Sí? ¿Qué quieres?', 28153),
(141166, 'esMX', '¡¿Que hiciste QUÉ?! No está permitido... ¡Se supone que NO matas a lo\' loa!', '', 28153),
(141165, 'esMX', 'Jo\'chunga está con vida, pero el loa Hir\'eek...', 'Jo\'chunga está con vida, pero el loa Hir\'eek...', 28153),
(141164, 'esMX', '¡Conque ahí eh\'tabas! Ya empezaba a preocuparme. ¿Qué sucedió?', '', 28153),
(141163, 'esMX', 'De día soy draenei... de noche soy un eredar.', '', 28153),
(141162, 'esMX', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t ¡Acaban de lanzar una |cFFF00000|Hspell:257585|h[Tromba de cañón]|h|r!', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t ¡Acaban de lanzar una |cFFF00000|Hspell:257585|h[Tromba de cañón]|h|r!', 28153),
(141161, 'esMX', '<Recordar el encarcelamiento de Sargeras>', '<Recordar el encarcelamiento de Sargeras>', 28153),
(141160, 'esMX', '<Recordar la llegada al Trono del Panteón>', '<Recordar la llegada al Trono del Panteón>', 28153),
(141159, 'esMX', 'Soy heraldo de la Luz... y del calor.', '', 28153),
(141158, 'esMX', '¡¿Caminaespíritus?!', '', 28153),
(141157, 'esMX', '¿Tentáculos en la cara? ¡NO TENEMOS tentáculos en la cara! Si los tuviéramos, significaría que los draenei somos emisarios secretos del Vacío que queremos ganarnos su confianza e infiltrarnos en su sociedad para aniquilarlos. No creo que estés insinuando eso, ¿o sí?', '', 28153),
(141156, 'esMX', 'Perdón, mis tatuajes están un poco apagados. Anoche olvidé cargar mi batería.', '', 28153),
(141155, 'esMX', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan usa su |cFFFF0000|Hspell:255371|h[Rostro aterrador]|h|r, ¡escóndanse!', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan usa su |cFFFF0000|Hspell:255371|h[Rostro aterrador]|h|r, ¡escóndanse!', 28153),
(141154, 'esMX', '', 'Amo... concédeme tu don...', 28153),
(141153, 'esMX', '', '¡Te daré un piedrazo en la cabeza! ¡Vamos, atrévete!', 28153),
(141152, 'esMX', '', '¡Aléjense troggs apestosos!', 28153),
(141151, 'esMX', '<Ver la bendición de la Corona.>', '<Ver la bendición de la Corona.>', 28153),
(141150, 'esMX', '<Ver la visión de Brisaveloz.>', '<Ver la visión de Brisaveloz.>', 28153),
(141149, 'esMX', '', '¡Protege a las crías de Rakjan!', 28153),
(141148, 'esMX', '<Ver la sentencia de la Luz.>', '<Ver la sentencia de la Luz.>', 28153),
(141147, 'esMX', '', '¡Disculpa! ¿Puedes darme una mano?', 28153),
(141146, 'esMX', '<Ver la decisión del Triunvirato.>', '<Ver la decisión del Triunvirato.>', 28153),
(141145, 'esMX', '<Ver el escape de Argus.>', '<Ver el escape de Argus.>', 28153),
(141144, 'esMX', '', '¡No dejes que escapen las crías!', 28153),
(141143, 'esMX', '¡Ey! ¡Por aquí! ¡Ey! ¡Eeeeeeeey!', '', 28153),
(141142, 'esMX', 'Un pterrordáctilo herido se detiene para recuperarse de sus heridas.', '', 28153),
(141141, 'esMX', '<Ver la llegada de Aggramar.>', '<Ver la llegada de Aggramar.>', 28153),
(141140, 'esMX', '', '¡Mira! ¡Listo! Ooohhh, es tan hermosa y letal...', 28153),
(141139, 'esMX', '', 'Todo este... ¡PODER! ¡JA JA JA JAAAA!', 28153),
(141138, 'esMX', 'Interesante... Así que usan los pináculos para viajar. He aprendido mucho en este día.', '', 28153),
(141137, 'esMX', 'Eh, ¿jefe? ¿$n? Creo que tenemos un nuevo problema relacionado con las víboras...', '', 28153),
(141136, 'esMX', '<Rakjan levanta la cabeza con orgullo.>', '', 28153),
(141135, 'esMX', '', 'Puede que me hayan templado en la luz, pero sé cómo divertirme en la oscuridad.', 28153),
(141134, 'esMX', '', 'Enciendo con los ojos, con los tatuajes, con la armadura... ¿Te enciendo?', 28153),
(141133, 'esMX', '', 'No necesitas ir de noche a la Tribu Cuerno del Cielo para que te haga ver las estrellas...', 28153),
(141132, 'esMX', '', 'No sé si lo sabías, pero vivir en la altura te da mucho vigor. Si quieres, te lo puedo demostrar...', 28153),
(141131, 'esMX', '', 'Conozco a Ethel. En realidad es maratonista, pero dice que le divierte molestar a los turistas.', 28153),
(141130, 'esMX', '¡Los huesos sin sosiego vuelven a la vida como un Raptor reanimado!', '¡Los huesos sin sosiego vuelven a la vida como un Raptor reanimado!', 28153),
(141129, 'esMX', 'Una pila cercana de huesos antiguos comienza a moverse.', 'Una pila cercana de huesos antiguos comienza a moverse.', 28153),
(141128, 'esMX', 'Dalaran por encima de las Islas Quebradas', 'Dalaran por encima de las Islas Quebradas', 28153),
(141127, 'esMX', 'La princesa es el futuro de Zandalar. Debe eh\'tar a salvo.', 'La princesa es el futuro de Zandalar. Debe eh\'tar a salvo.', 28153),
(141126, 'esMX', 'Cuando el Alto Exarca me ordenó viajar a Azeroth, no me convencía la idea de abandonarlo. Sentía que había otras personas que eran más idóneas para esa tarea.\n\nSin embargo, ahora comprendo por qué lo hizo. Quería que viera de cerca los motivos por los que Alleria y él habían estado luchando.\n\nPuede que nuestra guerra se haya acabado, pero aún nos esperan muchas batallas. Que hayamos derrotado a la Legión no significa que todos los demonios que existen se hayan dado por vencidos.\n\n<Lothraxion aprieta el puño y sonríe.>\n\nAl menos, no por ahora.', '', 28153),
(141125, 'esMX', 'Eh\'tamos a las órdenes de la princesa.', 'Estamo\' a las órdene\' de la princesa.', 28153),
(141124, 'esMX', '¿Qué necesitas de mí?', '¿Qué necesitas de mí?', 28153),
(141123, 'esMX', '¡Los árboles han cobrado vida! ¡Busquen sus hachas!', '', 28153),
(141122, 'esMX', '¡Tor\'paantos!', '', 28153),
(141121, 'esMX', '', '¡Que comience la prueba! Y que la Luz los acompañe.', 28153),
(141120, 'esMX', '', 'No es una elección muy ortodoxa, pero técnicamente cumple con las reglas. Hasta donde sé, $p jamás ha evitado un desafío.', 28153),
(141119, 'esMX', '¡Que así sea! Tor\'paantos elegirá... ¡a $Geste debilucho:esta debilucha;!', '', 28153),
(141118, 'esMX', '', 'El último iniciado que intentó hacer la prueba solo volvió hecho pedazos. Elige un acompañante o vuelve al cuartel.', 28153),
(141117, 'esMX', '¡Tor\'paantos no necesita a nadie que lo ayude!', '', 28153),
(141116, 'esMX', '', 'Tor\'paantos... Ya hablamos de esto. Cada iniciado debe estar secundado por un compañero. ¿Dónde está tu compañero?', 28153),
(141115, 'esMX', '', 'Quienes realmente estén listos, den un paso adelante y acepten su destino.', 28153),
(141114, 'esMX', '', 'Quienes tengan la más mínima duda, márchense ahora. No serán considerados cobardes sino sensatos.', 28153),
(141113, 'esMX', '', 'Muchos draenei de grandes virtudes salieron de esta prueba quebrados... o peor.', 28153),
(141112, 'esMX', '', 'Esta prueba los obligará a examinar nada más ni nada menos que su propia esencia. Lo que creen ser.', 28153),
(141111, 'esMX', '', 'Queda una última prueba... La más difícil de todas.', 28153),
(141110, 'esMX', '', 'Camaradas, las pruebas que han soportado demuestran que llevan la Luz en sus corazones.', 28153),
(141109, 'esMX', '<Parece que los troggs la vaciaron.>', '', 28153),
(141108, 'esMX', '<Sigue buscando a los niños>', '<Sigue buscando a los niños>', 28153),
(141107, 'esMX', 'Creo que $n tiene más experiencia que tú en este tipo de cosas, Ingrid.', '', 28153),
(141106, 'esMX', '', '¡No es justo, yo quería hacerlo!', 28153),
(141105, 'esMX', 'Puede que el Vindicaar no haya atravesado ninguna prueba cuando nos embarcamos en esta campaña, pero nos trajo de regreso a casa sanos y salvos.\n\nTodas esas mejoras a la nave valieron la pena, ¿verdad?\n\nNo respondas. Solo me romperías el corazón.\n\nNadie valora como corresponde el trabajo del ingeniero de una nave.', '', 28153),
(141104, 'esMX', '¡Los he encontrado! Por fin, los he encontrado.\n\n<La sonrisa de Arator pronto se convierte en un gesto de incertidumbre.>\n\nLas dos personas que me dieron la vida... no estuvieron presentes en ella. Sé que lucharon por mantenerme a salvo, y que realizaron sacrificios enormes, pero...\n\nNo podemos pretender convertirnos en una familia feliz de un día para otro. Ellos no saben casi nada de mí, y yo solo he oído leyendas sobre ellos. Tenemos muchas cosas que contarnos y muchas heridas que sanar.\n\nPero, al menos, lo haremos juntos.', '', 28153),
(141103, 'esMX', '', 'Alleria ha cambiado. Ahora, controla poderes que no logro entender por completo. Sin embargo, su corazón permanece intacto y sigue siendo mi querida hermana. Estoy segura.\n\nLas novedades de Sylvanas la atormentan. Hay asuntos pendientes que debemos solucionar... frente a frente.\n\nLas hermanas Brisaveloz deben reunirse, y ese encuentro solo puede suceder en un lugar.', 28153),
(141102, 'esMX', '', '¿Sigues aquí?\n\n<Ishanah te observa intrigada.>\n\nTodo ha terminado. Vete a tu casa.\n\n<Ishanah hace un gesto para que te marches.>\n\n¡Vete!', 28153),
(141101, 'esMX', 'La campaña contra la Legión ha sido extensa y agotadora. Hemos atravesado mundos enteros, recorrido el propio Vacío Abisal para finalmente alcanzar la victoria.\n\nEstoy exhausto, $n. Pero no podemos descansar.\n\nLas visiones fatídicas de Magni me afligen profundamente. Solo queda una titán, adalid, y debemos defenderla.', '', 28153),
(141100, 'esMX', '', '¡Mira! ¡Listo! Ooohhh, es tan hermosa y letal...', 28153),
(141099, 'esMX', 'Soñé con regresar a Argus infinitas veces; con ver en qué se había convertido mi hogar... y salvarlo.\n\n<Velen permanece en silencio durante un tiempo.>\n\nNo había salvación posible, pero sí alcanzamos la victoria.\n\nNo sé qué nos deparará el futuro, pero no esperaré a que las visiones me guíen. Haré todo lo posible por apoyar al rey Anduin y asegurarme de que esté preparado para enfrentarse a la amenaza que acecha en la oscuridad.', '', 28153),
(141098, 'esMX', '', 'Mi corazón se estremece de alegría de solo pensar en regresar a Azeroth junto a Arator y Turalyon. Volver a ver los bosques de mi tierra natal.\n\nY sin embargo...\n\nVereesa me ha contado lo que sucedió con Sylvanas. Aunque me aterra el encuentro, debo ver con mis propios ojos en qué se ha convertido.\n\n¿Sigue siendo mi hermana...? ¿O es un monstruo a quien la Luz ha abandonado?\n\nClaro que yo también he cambiado. Los poderes que controlo pueden levantar algunas sospechas sobre mi lealtad.\n\n<Alleria suspira profundamente.>\n\nDebo conservar la calma y la concentración. Hay mucho para reflexionar...', 28153),
(141097, 'esMX', 'Al fin, la guerra se ha terminado.\n\nUna parte de mí no esperaba sobrevivir para ver este día. Hemos luchado tantas batallas y perdido tanto.\n\n<Turalyon suspira, tiene los ojos húmedos de emoción.>\n\nAhora, regresamos a nuestro hogar, a un mundo que no he pisado en mil años.\n\nMi vieja vida ya es parte del pasado. Es hora de construir una vida nueva y conocer a mi hijo, la persona que representa todo por lo que he luchado.', '', 28153),
(141096, 'esMX', 'Muy buen trabajo, Ingrid... Un poco desconcertante.', '', 28153),
(141095, 'esMX', 'Yo me encargo.', '', 28153),
(141094, 'esMX', '', 'Eh... ¡Creo que necesitaremos alguna protección contra ese relámpago!', 28153),
(141093, 'esMX', '', 'Ohhh, hace mucho que quiero hacer esto. ¡Apártate!', 28153),
(141092, 'esMX', 'Si un nativo más vuelve a llamarme \"candelabro con patas\", les juro que...', '', 28153),
(141091, 'esMX', '', 'Nunca me gustaron los drogbar, pero cuando los veo entrenando en su gimnasio... Bueno, digamos que, a veces, las profundidades de la tierra se ponen un poco candentes.', 28153),
(141090, 'esMX', 'Ingrid, usaré mi propia magia para potenciar la Gema clamacielos. Atrás.', 'Ingrid, usaré mi propia magia para potenciar la Gema clamacielos. Atrás.', 28153),
(141089, 'esMX', 'Necesito que potencies la Gema clamacielos.', 'Necesito que potencies la Gema clamacielos.', 28153),
(141088, 'esMX', 'No puedo creerlo... ¡$n! ¡Por aquí!', '', 28153),
(141087, 'esMX', '', 'Je... ¡SABÍA que nos rescatarían! Bueno, realmente deseaba que lo hicieran... ¡Por aquí!', 28153),
(141086, 'esMX', '', '¡Tú! ¡$n! ¡He oído hablar mucho de ti, sácame de aquí!', 28153),
(141085, 'esMX', 'No puede ser. Es imposible que $n realmente haya venido aquí a rescatarme.', '', 28153),
(141084, 'esMX', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Estás |cFFF00000|Hspell:257459|h[Engarfiado]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t ¡Estás |cFFF00000|Hspell:257459|h[Engarfiado]|h|r!', 28153),
(141083, 'esMX', 'Su victoria está más cerca de lo que crees.', '', 28153),
(141082, 'esMX', 'Sus susurros resuenan más fuerte que los demás.', '', 28153),
(141081, 'esMX', 'Los ardientes conservaron el equilibrio. Ahora está perdido... perdido.', '', 28153),
(141080, 'esMX', 'Tu orgullo es la causa de todo esto.', '', 28153),
(141079, 'esMX', 'La noche cae. Su canción concluirá.', '', 28153),
(141078, 'esMX', 'Acepta tu destino. Todos se ahogarán.', '', 28153),
(141077, 'esMX', 'Las grietas se agrandan.', '', 28153),
(141075, 'esMX', '¡$n despierta una pila de huesos!', '¡$n despierta una pila de huesos!', 28153),
(141074, 'esMX', '¡Hola! Si se te perdió algún compañero, puedo ayudarte a encontrarlo.', '', 28153),
(141073, 'esMX', 'En vida, yo cuidaba a los animale\'. Si quieres, aún puedo ayudarte con ello\'.', '', 28153),
(141072, 'esMX', 'Vinimos apenah\' pudimos.', '', 28153),
(141071, 'esMX', '', '¡Preparen el añublo! ¡Vacíenlo sobre nuestros enemigos!', 28153),
(141070, 'esMX', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|t¡Estás $Gafectado:afectada; con |cFFFF0000|Hspell:251570|h[Bomba de ánima]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|t¡Estás $Gafectado:afectada; con |cFFFF0000|Hspell:251570|h[Bomba de ánima]|h|r!', 28153),
(141069, 'esMX', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|t¡Estás $gafectado:afectada; con |cFFFF0000|Hspell:250669|h[Estallido de ánima]|h|r!', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|t¡Estás $gafectado:afectada; con |cFFFF0000|Hspell:250669|h[Estallido de ánima]|h|r!', 28153),
(141068, 'esMX', '', 'Pero su destino aún les pertenece, Umbric. Puedo enseñarles a silenciar los susurros... a someter a las sombras a su voluntad, en lugar de someterse a la voluntad de ellas.', 28153),
(141067, 'esMX', '', 'Durzaan intentó arrancarles la mortalidad y convertirlos en esclavos del ansia... como él.', 28153),
(141066, 'esMX', 'Alleria... $p... Mi pueblo es libre, pero hemos... cambiado. Y las voces...', '', 28153),
(141065, 'esMX', '', 'No. Esta gente no te pertenece. Aún no están perdidos.', 28153),
(141064, 'esMX', 'Nooooooooooo...', '', 28153),
(141063, 'esMX', '', 'Puedo discernir tus mentiras, Durzaan. Los otros también.', 28153),
(141062, 'esMX', '¿Por qué te resistes? ¡Estás en el umbral de un destino grandioso!', '', 28153),
(141061, 'esMX', '', 'Esta tormenta del Vacío es un conducto... un portal que debemos sellar.', 28153),
(141060, 'esMX', '', 'Tus maestros no me esclavizarán, etéreo... ¡y tampoco a mis hermanos y hermanas!', 28153),
(141059, 'esMX', 'Estamos del mismo lado, Brisaveloz... no importa lo que ese traidor te ha enseñado.', '', 28153),
(141058, 'esMX', '', 'Calma, calma... Nada de entrelazar cuernos en la primera cita.', 28153),
(141057, 'esMX', 'Los nombres no tienen importancia. La pregunta interesante es... ¿en qué se convertirán?', '', 28153),
(141056, 'esMX', '', 'Ven, $p. ¡Debemos detener esta transformación antes de que mi pueblo esté perdido!', 28153),
(141055, 'esMX', '¡Rrrrurgaaghh! Siento el poder... me llama... me transforma...', '', 28153),
(141054, 'esMX', '', '¡Ignora los susurros, Umbric! Este \"don\" que te ofrecen no es más que esclavitud.', 28153),
(141053, 'esMX', '', '¡Muéstrate! ¿Quién eres?', 28153),
(141052, 'esMX', 'Por fin... el futuro que predije se hizo realidad. Gracias por abrir el camino.', '', 28153),
(141051, 'esMX', '', 'El otro día me dijeron que tengo ojos \"lechosos\". ¿Se les ocurre algo menos estimulante?', 28153),
(141050, 'esMX', '¿Para qué quieres cuernos con un tótem como este?', '', 28153),
(141049, 'esMX', '¡Ja, ja! Contempla mi poder, mortal. Recuerda que puede\' tener una parte...', '', 28153),
(141048, 'esMX', 'La zona que espera adelante es peligrosa. ¡Regresa!', 'La zona que espera adelante es peligrosa. ¡Regresa!', 28153),
(141047, 'esMX', '', 'Dejaste que Zul atravesara nuestrah\' fuerzah\' como si fueran de papel. Y ahora marcha hacia Atal\'Dazar sin que nadie se le oponga. ¿Tienes un plan para eso, rey?', 28153),
(141046, 'esMX', '', 'Rastakhan, te has tomado demasiado tiempo para encargarte de eh\'to.', 28153),
(141045, 'esMX', 'Es difícil decir si Zul es un buen eh\'tratega o un buen profeta. De cualquier forma, siempre está un paso por delante de nosotros.$b$bSu plan es reemplazarme con los huesos de nuestro primer rey, Dazar.$b$bYo estoy dispueh\'to a volver a ver a los trols dominando el mundo, pero no quiero pagar el costo de las herejías oscuras a las que Zul se ha convertido.', '', 28153),
(141044, 'esMX', '', 'Incluso el viejo Bwonsamdi quedará atormentado con todo lo que planeo hacer contigo.', 28153),
(141043, 'esMX', '', 'Le haré cosas horrible\' a tu alma.', 28153),
(141042, 'esMX', '', 'Tu sufrimiento no terminará con la muerte.', 28153),
(141041, 'esMX', '', 'Primero te mataré, y luego me pondré a jugar contigo.', 28153),
(141040, 'esMX', '', '¿Quiere\' invadir mi templo? Morirás por eso.', 28153),
(141039, 'esMX', '', '¿Rastakhan eh\'tá aquí? Bien. Llévame a ver a ese impuntual.', 28153),
(141038, 'esMX', 'Solo quería ayudar.', '', 28153),
(141037, 'esMX', 'La belleza que se acerca hará arder al mundo.', '', 28153),
(141036, 'esMX', '¡Vaya, mírate nada má\'! Qué adalid más imponente... ¡ja!', '', 28153),
(141035, 'esMX', '', '¿Sabes cómo ganarte el corazón de una mujer? Masajes en las pezuñas. Yo sé lo que te digo, cariño.', 28153),
(141034, 'esMX', '', 'Los tauren son los mejores poetas de todo Azeroth. Sus versos son muuuuuuuuuuuuy conmovedores.', 28153),
(141033, 'esMX', '', 'Brrrrr, aquí sí que hace frío. ¿Alguien quiere muuuucho helado?', 28153),
(141032, 'esMX', '', '¿Sabes por qué los Crin de Río siempre están tan tranquilos? Porque se dejan llevar por la corriente.', 28153),
(141031, 'esMX', '', '¿Qué sale si le das de comer cacao a un tauren de Altamontaña? ¡Muuuuuuuuuuuse de chocolate!', 28153),
(141030, 'esMX', '¿Acabas de colgar tu sombrero en mis cuernos? ¿Tengo cara de perchero o qué?', '', 28153),
(141029, 'esMX', '¿Qué huele peor que un drogbar? Dos drogbar. ¿Qué huele peor que dos drogbar? Nadie lo sabe, porque el olor te mata.', '', 28153),
(141028, 'esMX', 'Un tauren, un yaungol y un taunka entran a un bar. ¿Qué? No, no es un chiste, así son mis reuniones familiares.', '', 28153),
(141027, 'esMX', '¡Ja! No me lo vas a creer. ¡Un amigo mío convenció a un aventurero poderoso de que pateara pescados para devolverlos al agua! Un momento... no eras tú, ¿cierto?', '', 28153),
(141026, 'esMX', 'Seré un simple tauren de las montañas, pero al menos no tengo que meter las manos en estiércol de gusano para buscar un botín.', '', 28153),
(141025, 'esMX', 'Juguemos un juego. Cada vez que una arpía empieza a gritar sobre tierra y rocas, bebemos un trago.', '', 28153),
(141024, 'esMX', '¿Por qué esa pareja de draenei me pregunta todo el tiempo dónde está Rodolfo?', '', 28153),
(141023, 'esMX', '', 'Lo que importa no es el tamaño de los cuernos; es el movimiento del tótem.', 28153),
(141022, 'esMX', '', '¿Estás pensando en ponerle los cuernos a alguien?', 28153),
(141020, 'esMX', '', 'Bueno... ¿chocamos cuernos?', 28153),
(141018, 'esMX', '¿Eres alquimista? Porque siento mucha química entre nosotros.', '', 28153),
(141017, 'esMX', 'No temas lastimarme. Tengo la piel dura.', '', 28153),
(141016, 'esMX', 'Cuídate de los lugares profundos... de mi corazón.', '', 28153),
(141015, 'esMX', 'Mi tótem siempre está erguido. SIEMPRE.', '', 28153),
(141014, 'esMX', 'Confía en mí... Soy experto en explorar las profundidades.', '', 28153),
(141013, 'esMX', '¿Has visto los camarotes del Vindicaar? Puedo hacer una visita guiada solo para ti.', '', 28153),
(141012, 'esMX', '', 'Deberías venir a las fiestas que hacemos en Corte de Estrellas. Nunca conocí a nadie que necesitara una máscara con tanta urgencia...', 28153),
(141011, 'esMX', '', '¿Elfos de la noche? ¡Elfos del campo, diría yo! Viven en árboles, duermen en cuevas... algunos hasta tienen cuernos. Esos tipos no están preparados para vivir en una ciudad REAL.', 28153),
(141010, 'esMX', '', 'Me encontré con un kal\'dorei que me dijo que mi vestido era la cumbre de la moda... ¡hace 10 000 años! ¡A estos elfos de la noche les encanta ensombrecerte el día!', 28153),
(141009, 'esMX', '', 'A pesar de los años, Tyrande está más linda que nunca. ¿Sabes si está soltera?', 28153),
(141008, 'esMX', '', '¿Quieres un vaso de arcavino? Yo misma aplasté las bayas.', 28153),
(141007, 'esMX', '', 'Las rosas son rojas en la ciudad donde nací. ¿Es eso un disfraz? ¿QUIÉN ANDA AHÍ?', 28153),
(141006, 'esMX', '', '¡Una alusión! ¿Qué insinúas?', 28153),
(141005, 'esMX', 'Seamos honestos: tener un dinosaurio furioso y gigante encerrado en una jaula era el preludio de una tragedia.', '', 28153),
(141004, 'esMX', 'No sé por qué la siguen llamando Corte de Estrellas. Yo me paso la vida ahí dentro y jamás he visto a ningún famoso.', '', 28153),
(141003, 'esMX', 'En mi época, había una sola clase de elfo. UNA.', '', 28153),
(141002, 'esMX', 'Esa es mi especialidad. Bebo arcavino... y sé cosas.', '', 28153),
(141001, 'esMX', 'Hola. Me llamo Roy y soy adicto al maná.', '', 28153),
(141000, 'esMX', '¿Por qué TODO EL MUNDO me pide que diga lo mismo? Ahhhhh... está bien. ¡Una ilusión! ¿Qué ocultas?', '', 28153),
(140999, 'esMX', 'Para ser honesto, todo andaba bien...', '', 28153),
(140998, 'esMX', '', 'En esta banda no hay nada prohibido.', 28153),
(140997, 'esMX', '', 'Estuve atrapada en una burbuja con los mismos tipos durante 10 000 años. Te imaginarás que ansío un poco de... variedad.', 28153),
(140996, 'esMX', '', 'Si me muestras tus líneas Ley, yo te mostraré las mías.', 28153),
(140995, 'esMX', '', '¿Animación? ¿Detonación? Sugiero que directamente pasemos a la reproducción.', 28153),
(140994, 'esMX', '', 'Nadie se puede resistir a mi Fuente de la Noche.', 28153),
(140992, 'esMX', '', 'No hay nada ilusorio aquí. Todo lo que ves es real... muy real.', 28153),
(140991, 'esMX', '', '¿Eso que veo en tu bolsillo es una ilusión o estás feliz de verme?', 28153),
(140990, 'esMX', '¿Acaso te arrancaron de un arcan\'dor? Pareces una fruta prohibida.', '', 28153),
(140989, 'esMX', '\"Las estrellas te han juzgado y te declararon... muy sexy.\n\"', '', 28153),
(140988, 'esMX', 'De la noche venimos y hacia la noche vamos.', '', 28153),
(140987, 'esMX', 'Tus ojos son estrellas caídas de la noche.', '', 28153),
(140986, 'esMX', 'Mmm, me encantaría ver tu línea ley.', '', 28153),
(140985, 'esMX', 'Has atravesado El Arco que conduce a mi corazón.', '', 28153),
(140984, 'esMX', 'Veo que sabes de magia. Acabas de hacer que todo lo que había en esta habitación desaparezca de mi vista.', '', 28153),
(140983, 'esMX', '¿Eres una fuente de magia? Porque no puedo dejar de pensar en sumergirme en ella.', '', 28153),
(140982, 'esMX', '', 'En mil años, solo conocí a un humano: Turalyon. Por eso siempre creí que todos eran viejos maltrechos.', 28153),
(140981, 'esMX', '', 'El problema de ser templeluz es que mis S.E.L.F.I.E.S. siempre salen con demasiado brillo.', 28153),
(140980, 'esMX', '', 'Todavía no hemos chocado el Vindicaar... pero por nuestro historial, es solo cuestión de tiempo.', 28153),
(140979, 'esMX', '', 'No te recomiendo caminar descalzo en el Vindicaar. Constantemente encontramos esquirlas de vidrio que nadie limpió.', 28153),
(140978, 'esMX', '', 'Los pies están sobrestimados. ¡No hay nada como tener pezuñas cuando vas a la pedicura!', 28153),
(140977, 'esMX', '', '¿Conoces a mi perro? Se llama Dinamita.', 28153),
(140976, 'esMX', '', 'No, no tengo un tatuaje brillante sobre la cola.', 28153),
(140975, 'esMX', 'Mi vida por Aiur... <tos> Argus. ¡Mi vida por ARGUS!', '', 28153),
(140974, 'esMX', 'Es bueno volver a pisar tierra firme después de tanto tiempo abordo de una nave. ¡El piso de metal me estaba destruyendo las pezuñas!', '', 28153),
(140973, 'esMX', 'Su mundo es sumamente extraño. ¿Osos parlanchines que practican kung-fu? En Argus, estarían en un circo.', '', 28153),
(140972, 'esMX', 'Creí que mi tatuaje significaba \"Defensor de la Luz\" en naaru. El otro día me enteré de que significa \"cabra brillante\"...', '', 28153),
(140971, 'esMX', '', 'Ante la duda, si ves algo que brilla... tócalo.', 28153),
(140970, 'esMX', '¿Subió la temperatura? Porque siento cada vez más calor...', '', 28153),
(140969, 'esMX', 'Su sangre lo está fortaleciendo. La tuya también lo hará.', '', 28153),
(140968, 'esMX', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t ¡Tu mente está por sucumbir al |cFFFF0000|Hspell:244172|h[Asalto psíquico]|h|r!', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t ¡Tu mente está por sucumbir al |cFFFF0000|Hspell:244172|h[Asalto psíquico]|h|r!', 28153),
(140967, 'esMX', 'Hay que seguir adelante, no debemos permanecer aquí.', 'Hay que seguir adelante, no debemos permanecer aquí.', 28153),
(140966, 'esMX', '', '¡Malditos sean los cobardes de Zuldazar que no detuvieron antes eh\'ta amenaza! Mi padre fue un necio al creer que simplemente \"se esfumaría\".\n\nNo alcanza con matar a Ateena para terminar con eh\'to... Es peor de lo que había imaginado.', 28153),
(140965, 'esMX', 'Mi guardia... ha... terminado...', '', 28153),
(140964, 'esMX', 'Lo siento, mi reina.', '', 28153),
(140963, 'esMX', 'Mi reina... ¡Te he fallado!', '', 28153),
(140962, 'esMX', '¡Nadie se acercará a la reina!', '', 28153),
(140961, 'esMX', '¡No interrumpirán el deh\'canso de la reina!', '', 28153),
(140960, 'esMX', '¡Soy el protector eterno de la reina! ¡Lárgate!', '', 28153),
(140959, 'esMX', '', 'Por los loa... ¡No! Ahora vemo\' el verdadero poder de los trols de sangre. Padre... ¡¿por qué los ignoraste durante tanto tiempo?!', 28153),
(140958, 'esMX', '', 'Prepárate, $n. No sabemos con qué nos encontraremo\'.', 28153),
(140957, 'esMX', '<Ya sabes lo que dicen... perro que ladra no muerde. Y este no parece ladrar mucho.>', '', 28153),
(140954, 'esMX', 'Me gusta con la luz prendida. Aunque la verdad es que no tengo alternativa...', '', 28153),
(140953, 'esMX', '', 'Volvamos a mi nave y unámonos en el abismo.', 28153),
(140952, 'esMX', '', 'Apuesto a que desciendes de los naaru, porque tienes un cuerpo celestial.', 28153),
(140950, 'esMX', '', 'Debe eh\'tar cerca. No me rendiré, no cuando estamo\' tan cerca de matar a la líder de eh\'tos monstruos.', 28153),
(140949, 'esMX', '', '¡No eh\'caparás de mí, Ateena! ¡No importa qué clase de vudú oh\'curo controlas!', 28153),
(140945, 'esMX', '¡El general Erodus sale de su cápsula de mando!', '¡El general Erodus sale de su cápsula de mando!', 28153),
(140944, 'esMX', '¡El ingeniero jefe Ishkar sale de su cápsula de mando!', '¡El ingeniero jefe Ishkar sale de su cápsula de mando!', 28153),
(140942, 'esMX', '¡La almirante Svirax sale de su cápsula de mando!', '¡La almirante Svirax sale de su cápsula de mando!', 28153),
(140939, 'esMX', '', '¡Te enfrentas al poder de G\'huun! Es inútil tratar de detenerno\'. Te moh\'traré...', 28153),
(140938, 'esMX', '', '¡Pobre Talanji! Somos hijo\' de un loa poderoso. ¡Así nunca ganarás, criatura insignificante!', 28153),
(140937, 'esMX', '', '¡No intentes intimidarme, Ateena! Te haré pedazo\', ¡y también a tu maestro!', 28153),
(140936, 'esMX', '', 'Será mejor que me oculte hah\'ta que sea el momento de atacar. ¡Derribaremo\' a Ateena $Ujuntos:juntas;!', 28153),
(140930, 'esMX', '¡He eh\'capado!', '¡Atrapada aquí para siempre!', 28153),
(140929, 'esMX', '¡Vas a sufrir!', '¡Zak\'rajan nos traicionó a todo\'!', 28153),
(140928, 'esMX', '¡Muerte a Zak\'rajan!', '¡Nadie eh\'capa de Zak\'rajan!', 28153),
(140927, 'esMX', 'Creo que vi movimiento\' hacia el noroeste.', '', 28153),
(140926, 'esMX', 'Saludos, madre. Todo está tranquilo por aquí.', '', 28153),
(140925, 'esMX', 'Ey, hay malas noticia\', madre. Les perdimos el rastro a los intruso\' que mataron al grupo de trabajo de Najima.', '', 28153),
(140924, 'esMX', '', '¡Haz que los trols de sangre sufran por eh\'te sacrilegio, $n! Reúnete conmigo cuando hayas vengado a los caído\'.', 28153),
(140923, 'esMX', '', '¡No abandonaré aquí los cadáveres de mi pueblo... para que los profanen eso\' monstruos!', 28153),
(140922, 'esMX', '¡Mi hacha se fabricó para talar árboles, pero esto es bastante parecido!', '', 28153),
(140921, 'esMX', '¡Esta hacha se hizo para cortar, y eso es lo que hará!', '', 28153),
(140920, 'esMX', 'Arañas... bestia de madera... ¡Acabaré con todos!', '', 28153),
(140919, 'esMX', '', '|TInterface\\Icons\\ABILITY_CREATURE_POISON_02:20|t¡Se abre un portal vil a Rancora!', 28153),
(140918, 'esMX', '', '|TInterface\\Icons\\SPELL_HOLY_CONSUMEMAGIC:20|t¡Se abre un portal sombrío a Nathreza!', 28153),
(140917, 'esMX', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t¡Se abre un portal ardiente a Xoroth!', 28153),
(140916, 'esMX', '¡No me encerrarás de nuevo!', '¡Me haré un festín con tu alma!', 28153),
(140915, 'esMX', '|cffffff00Investigación realizada|r', '|cffffff00Investigación realizada|r', 28153),
(140914, 'esMX', '', 'Solo unos tótems más... ¡Bien, estoy lista!', 28153),
(140912, 'esMX', 'Una cosa son las arañas, ¿pero hombres árbol? ¡NO cuenten conmigo!', '', 28153),
(140911, 'esMX', 'Estoy acostumbrado a talar madera, ¡pero la madera no suele contraatacar!', '', 28153),
(140910, 'esMX', '¡Los árboles han cobrado vida! ¡Sálvese quien pueda!', '', 28153),
(140909, 'esMX', '', 'Síganme. Nos mantendré ocultos mientras escapamos.', 28153),
(140907, 'esMX', '', 'Apresúrate. No sabemos si esa cosa permanecerá muerta.', 28153),
(140906, 'esMX', '', '¡Mira cuántos artefactos! ¡Necesito una bolsa más grande!', 28153),
(140905, 'esMX', '¡Buen trabajo, equipo! Tomen lo que puedan, mientras puedan.', '', 28153),
(140904, 'esMX', '', 'Y quizás algunos abalorios para mí.', 28153),
(140903, 'esMX', '', '¡Ah, y será mejor que no me olvide del ojo de gólem lleno de almas! Tacha los convierte en bombas pequeñas y muy divertidas.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140902, 'esMX', '', '¡Ídolos malditos! A Tacha le encantan... Y mira todos estos componentes.', 28153),
(140901, 'esMX', '', 'Muy bien, veamos qué es lo que vale la pena transportar entre todas estas cosas mágicas.', 28153),
(140900, 'esMX', '', 'Este es un buen botín, $p. Me llevaré lo mejor para el grupo, por supuesto.', 28153),
(140899, 'esMX', '', 'Casi todas son armas zandalari comunes... ¡Uuuh, esas parecen encantadas!', 28153),
(140898, 'esMX', '', 'Buena pelea. Ahora veamos las reservas que tienen aquí.', 28153),
(140897, 'esMX', '¡Protejan a la sacerdotisa! ¡Que no pase nadie!', '¡Protejan a la sacerdotisa! ¡Que no pase nadie!', 28153),
(140896, 'esMX', 'Estamo\' montando una base en las ruina\' cercana\'. Tengan cuidado... Esto me da mala espina.', '', 28153),
(140895, 'esMX', '¿Loti te tuvo juntando paquetes? Yo te habría mandado a lanzar un maleficio a la bestia y lih\'to, pero los mercadere\' siempre se quejan cuando hago eso.', '', 28153),
(140894, 'esMX', '', 'Algo ha asustado a uno de los brutosaurio\' y se ha vuelto loco. Este caos es lo último que necesita la ciudad ahora. ¡Ayuda a los mercadere\' y recupera el cargamento ante\' de que te aplasten!', 28153),
(140893, 'esMX', '', 'Te doy las gracias. Los niños de hoy en día no respetan a sus ancianos ni a sus pertenencias. Cuando yo era joven...', 28153),
(140892, 'esMX', '', '¡Ayuda! Estos pequeños se han robado nuestros pergaminos y se han convertido en bestias. Tenemos pergaminos de disipación, pero tendrás que acercarte mucho para poder usarlos. ¡Ten cuidado!', 28153),
(140891, 'esMX', 'Ante\' de morir, ¡debes saber que encadenaremo\' y convertiremo\' en siervos a lo\' de tu calaña!', '', 28153),
(140890, 'esMX', 'Tu miserable clase se pondrá de rodillas.', '', 28153),
(140889, 'esMX', 'Los de tu calaña caerán ante nuestra\' espadas.', '', 28153),
(140888, 'esMX', '¡La Horda y la Alianza caerán!', '', 28153),
(140887, 'esMX', '¡Venganza por el emperador!', '', 28153),
(140886, 'esMX', '¡Venganza por Lei Shen!', '', 28153),
(140885, 'esMX', 'Zul nos prometió venganza contra lo\' de tu clase.', '', 28153),
(140880, 'esMX', '¡La dinomántica Kish\'o pide ayuda!', '¡La dinomántica Kish\'o pide ayuda!', 28153),
(140869, 'esMX', 'Vamos, construyan este cuartel rápido.', '', 28153),
(140860, 'esMX', '¡Eh, disculpa! ¡Por aquí! ¿Podrías ayudarnos con algo?', '', 28153),
(140859, 'esMX', '', 'Gracias por la ayuda, $p. Cuando estés listo para matar algunos sethrak, búscanos adentro.', 28153),
(140858, 'esMX', '', 'Estoy de acuerdo. Esta pelea no nos atañe. Hora de irnos.', 28153),
(140857, 'esMX', 'Esto está saliéndose de control muy rápido. Ya contamos con todos los suministros que necesitamos para atacar a los sethrak.', '', 28153),
(140856, 'esMX', 'Envíame a Mina Mostacho Seco.', 'Envíame a Mina Mostacho Seco.', 28153),
(140855, 'esMX', 'Recluta a un Bombardero goblin.', 'Recluta a un Bombardero goblin.', 28153),
(140854, 'esMX', 'Me adelantaré para explorar el área. Elimina a esos espectros y yo tomaré los suministros.', 'Me adelantaré para explorar el área. Elimina a esos espectros y yo tomaré los suministros.', 28153),
(140853, 'esMX', '', 'Primero, tendrás que matar a los gólems. Después, usa el tótem para succionar las almas de los cadáveres.', 28153),
(140852, 'esMX', 'Cuando estés adentro, avanza rápido. El próximo punto de encuentro está detrás de las ruinas, cerca de la cámara subterránea.', '', 28153),
(140851, 'esMX', '¡No hay esperanza! ¡Las promesa\' del falsario son mentiras!', '', 28153),
(140850, 'esMX', '¡Mentiras! ¡Son todas mentiras!', '', 28153),
(140849, 'esMX', '¿Por qué me has dejado ver? ¡¿POR QUÉ?!', '', 28153),
(140848, 'esMX', 'No eres más que una marioneta. ¡Ni siquiera la muerte te traerá alivio!', '', 28153),
(140847, 'esMX', '¡Ríndete ante G\'huun!', '', 28153),
(140846, 'esMX', '', 'La muerte no me detendrá...', 28153),
(140845, 'esMX', '', 'La Madre... te atrapará...', 28153),
(140844, 'esMX', '¡Lih\'to! Tienes el espíritu de una trol de sangre en tu interior. La magia te trah\'formará cuando te acerques a su aldea.', '', 28153),
(140843, 'esMX', '', 'Esto no ha terminado...', 28153),
(140842, 'esMX', '', 'El aquelarre es... omnipresente...', 28153),
(140841, 'esMX', '', '¡Drustvar nos pertenece, $Gforastero:forastera;!', 28153),
(140840, 'esMX', '', '¡Es inútil resistirse!', 28153),
(140839, 'esMX', '', '¡Caerás ante la Madre!', 28153),
(140838, 'esMX', '', '¡El aquelarre se quedará con tu pueblo inmundo!', 28153),
(140837, 'esMX', '', 'Ahí viene Omi con su informe de exploración.', 28153),
(140836, 'esMX', '', 'Malas noticias, equipo. Encontré espectros ahí dentro. El nivel de amenaza sube a naranja.', 28153),
(140834, 'esMX', '', 'Mientras tú te encargas de eso, yo me adelantaré para explorar el interior de las ruinas. Te veré en el punto de encuentro cuando hayas terminado.', 28153),
(140833, 'esMX', '', 'No pierdas tiempo en gólems sin vida. Busca uno que aún tenga energía.', 28153),
(140832, 'esMX', 'Envíame a Cresta Hachazo.', 'Envíame a Cresta Hachazo.', 28153),
(140831, 'esMX', 'Nos reuniremos en el punto de encuentro del puente destruido antes de asaltar las ruinas directamente.', '', 28153),
(140830, 'esMX', 'Bien, ya todos tienen una tarea. ¡Que sea una buena caza!', '', 28153),
(140829, 'esMX', 'Sígueme. El rey Rastakhan está cerca.', 'Sígueme. El rey Rastakhan está cerca.', 28153),
(140828, 'esMX', '', 'Saquen sus armas. Alguien se acerca...', 28153),
(140827, 'esMX', '', 'Cuando Zul nos exigió loh\' restos de Dazar, el primer rey, pensamos que era una broma.$b$bLo despreciamos.$b$bNo sabíamos que tenía un ejército listo para tomar nuestro templo por la fuerza.', 28153),
(140826, 'esMX', 'Estas ruinas están llenas de tesoros. Tomémonos el tiempo que haga falta para hacer las cosas bien.', '', 28153),
(140825, 'esMX', '', '¡Mamá! ¿Dónde estáh\'?', 28153),
(140824, 'esMX', '<Winstone está abriendo un paquete de cartas. ¿De dónde sacó tanto oro?>', '', 28153),
(140823, 'esMX', '<Winstone mira con furia su mano de cartas.>', '', 28153),
(140822, 'esMX', '<Winstone está acurrucado sobre su colección de cartas, mientras juguetea con la idea para armar un mazo nuevo.$b$bCuando inspeccionas un poco más, te percatas de que está eligiendo una gran cantidad de bestias...>', '', 28153),
(140821, 'esMX', 'Envíame a Ar\'gorok.', 'Envíame a Ar\'gorok.', 28153),
(140820, 'esMX', 'Para encontrar a Xal\'zaix, primero tenemos que encontrar a Sethraliss.', '', 28153),
(140818, 'esMX', 'Zak\'rajan blande nuestras almas como armas. Están condenados.', '', 28153),
(140817, 'esMX', 'Tus armas son inútiles. Nuestros espíritus lo protegen.', '', 28153),
(140816, 'esMX', '¡Otro cuerpo para destruir para Zak\'rajan!', '', 28153),
(140815, 'esMX', '¡Tu alma se unirá a las otras en este gólem!', '', 28153),
(140814, 'esMX', 'Libéranos...', '', 28153),
(140813, 'esMX', 'Zak\'rajan reina...', '', 28153),
(140812, 'esMX', 'Debemos purgar a los forasteros.', '', 28153),
(140811, 'esMX', 'Nada de reyes. Solo Zak\'rajan.', '', 28153),
(140810, 'esMX', 'De acuerdo, ve. ¡Encuentra a esa madre perdida y reúnelas otra ve\'!', '', 28153),
(140809, 'esMX', 'Jeje... La pequeñita tiene razón. Su madre no eh\'tá en el Otro Lado.', '', 28153),
(140808, 'esMX', 'Ningún loa. Solo Zak\'rajan.', '', 28153),
(140807, 'esMX', 'Defiende la corte, cueh\'te lo que cueh\'te.', '', 28153),
(140806, 'esMX', 'Ayúdanos...', '', 28153),
(140805, 'esMX', 'Sacrificio... para Zak\'rajan...', '', 28153),
(140804, 'esMX', 'Uuh... ¡$Uun sacerdote:una sacerdotisa;! Si alguna ve\' piensas en cambiar de fe, ven a ver al viejo Bwonsamdi, ¿de acuerdo?', '', 28153),
(140803, 'esMX', 'Vaya, la picadura de las sangriposas duele cada vez más.', 'Vaya, la picadura de las sangriposas duele cada vez más.', 28153),
(140802, 'esMX', '¡Au!', '¡Ay!', 28153),
(140801, 'esMX', 'Zoquete.', 'Agh, zoquete.', 28153),
(140800, 'esMX', '¡Oye! ¡Fíjate a dónde apuntas esa cosa!', '¡Oye! ¡Fíjate a dónde apuntas esa cosa!', 28153),
(140799, 'esMX', 'Malditos continentales...', 'Agh, malditos continentales...', 28153),
(140798, 'esMX', '¡Auch! ¡¿Por qué hiciste eso?!', '¡Auch! ¡¿Por qué hiciste eso?!', 28153),
(140797, 'esMX', 'Nuestra causa está perdida. La Cruzada Ardiente nos consumirá a todos.', '', 28153),
(140796, 'esMX', '¡Carroñeros inmundos! ¡Aquí mando yo!', '', 28153),
(140795, 'esMX', 'Nuestros adalides han caído. Nada puede detener el fin de todas las cosas.', '', 28153),
(140794, 'esMX', 'Los elementos responden al llamado de la Horda. Como corresponde.', '', 28153),
(140793, 'esMX', '', 'El recinto de los espíritu\' está listo. ¿Qué necesita\'?', 28153),
(140792, 'esMX', 'Incluso loh\' loa nos han abandonado.', 'Incluso loh\' loa nos han abandonado.', 28153),
(140791, 'esMX', 'Zak\'rajan nos ha esclavizado durante eras incontables. Libéranos...', 'Zak\'rajan nos ha esclavizado durante eras incontables. Libéranos...', 28153),
(140790, 'esMX', 'Los eh\'píritus son armas poderosa\'... si sabes cómo controlarla\'.', 'Los eh\'píritus son armas poderosa\'... si sabes cómo controlarla\'.', 28153),
(140789, 'esMX', 'Utiliza nuestras almas para protegerse. No puedes atravesar su escudo con armas.', 'Utiliza nuestras almas para protegerse. No puedes atravesar su escudo con armas.', 28153),
(140788, 'esMX', 'Nos prometieron tesoros y riquezas sin fin. En lugar de eso, nos esclavizaron.', 'Nos prometieron tesoros y riquezas sin fin. En lugar de eso, nos esclavizaron.', 28153),
(140787, 'esMX', 'Zak\'rajan nos prohibió venerar a los loa. Solo podemo\' adorarlo a él.', 'Zak\'rajan nos prohibió venerar a los loa. Solo podemo\' adorarlo a él.', 28153),
(140786, 'esMX', '¿Por qué Bwonsamdi se niega a dejarnoh\' pasar al Otro Lado?', '¿Por qué Bwonsamdi se niega a dejarnoh\' pasar al Otro Lado?', 28153),
(140785, 'esMX', 'Zak\'rajan encerró nuestros espíritus en estos gólems. Nos obliga a servirlo.', 'Zak\'rajan encerró nuestros espíritus en estos gólems. Nos obliga a servirlo.', 28153),
(140784, 'esMX', 'Espero que los canes estén hambrientos. Con los estandartes de la Horda sobre Granovel, podemos entrenar jinetes de lobos.', '', 28153),
(140783, 'esMX', 'La Armería está completa. ¡Pongan a trabajar esas forjas!', '', 28153),
(140781, 'esMX', 'Se ha construido la armería. ¿Cuáles son tus órdenes?', '', 28153),
(140780, 'esMX', '¡Zak\'rajan pagará por habernos encarcelado!', '¡Zak\'rajan pagará por habernos encarcelado!', 28153),
(140779, 'esMX', 'Sethraliss nos protegerá.', 'Sethraliss nos protegerá.', 28153),
(140778, 'esMX', '', 'Deh\'cansa, dulce Kaja. No te olvidaremos.', 28153),
(140777, 'esMX', 'Sulthis fue el primer Guardián. Nos necesitaba a mí y a Korthek para ayudarlo a sellar el cadáver de Mythrax en el interior de la gran pirámide.\n\nJuntos formamos una barrera y encerramos el cadáver de Mythrax.\n\nCada uno de nosotros forjó una llave imbuida con nuestro poder para asegurarnos de que nadie pudiera profanar la tumba.', '', 28153),
(140776, 'esMX', 'Vamos, vamos, que no hay necesidad de pelear. ¿Por qué no bebemos algo y contamos acertijos sin cesar?', '', 28153),
(140775, 'esMX', 'Si crees que Winstone es presa fácil, espera y verás. ¡Dará vuelta las mesas y serás TÚ quien se lamentará!', '', 28153),
(140774, 'esMX', 'Conozco a Rastakhan, el rey eterno, poderoso y lleno de valía; mas debería tener cuidado de la gente en la que confía.', '', 28153),
(140773, 'esMX', 'Oh, así que crees que continuaré mi aventura. ¿Por qué no te relajas, bebes un trago y me acompañas sin premura?', '', 28153),
(140772, 'esMX', '$GBienvenido:Bienvenida al bar tiki El Trono Hozen. ¡No encontrarás mejores bebidas en todo Zandalar!', '', 28153),
(140771, 'esMX', 'Podemos utilizar la conexión entre el corazón y Sethraliss para rastrearla.', '', 28153),
(140770, 'esMX', 'El corazón está vinculado con la fuerza vital de nuestra loa. El resplandor rojo indica que está en apuros. Pero lo más importante...¡es que indica que está viva!', '', 28153),
(140769, 'esMX', '¡Si lo que dices es cierto, debemos apresurarnos!', '', 28153),
(140768, 'esMX', 'Interesante...', '', 28153),
(140767, 'esMX', 'No, no, no. $GMuerto:Muerta; no me sirves para nada. Puedo devolverte la vida... por un precio.', '', 28153),
(140766, 'esMX', '¡Aah! ¿Qué hace\' aquí, colega? A ti no te ha llegado la hora... todavía.', '', 28153),
(140764, 'esMX', '', 'Ella no puede haber sabido que convertiría la jungla en arena...', 28153),
(140762, 'esMX', '¡Raaaaaaagh!', '', 28153),
(140761, 'esMX', 'Los infieles no tomarán este templo.', '', 28153),
(140760, 'esMX', 'Usaré su poder para manipular los hilos del tiempo a favor de nuestra causa.', '', 28153),
(140759, 'esMX', 'Y el resto de ustede\', no vuelvan a interferir en mis asuntos aquí. Los que rompen mis trato\' pagarán el precio.', '', 28153),
(140758, 'esMX', 'Ahora regresa a tu prisión y sufre.', '', 28153),
(140757, 'esMX', 'No hago tratos con traidores.', '', 28153),
(140756, 'esMX', '¡Por favor, Bwonsamdi, hagamos otro trato! ¡Tocaré tus tambores todos los días! ¡Mi pueblo te venerará para siempre!', '', 28153),
(140755, 'esMX', 'Yo también estuve buscando a Rakera. Estas serpiente\' dijeron que la habías encontrado. \n\nQué bueno que podamo\' estar todos juntos, siempre y cuando me dejen salir de esta jaula.', '', 28153),
(140754, 'esMX', 'Nunca pasará\' al Otro Lado. Nunca verá\' a tus ancestros. Estarás encerrado aquí para toda la eternidad.', '', 28153),
(140753, 'esMX', 'Yo sí. Bwonsamdi no olvida sus rencores.', '', 28153),
(140752, 'esMX', 'Pero te volviste arrogante. Prohibiste que veneraran a cualquiera que no fuera tú. ¿Lo recuerda\'?', '', 28153),
(140751, 'esMX', 'cámbiame', 'cámbiame', 28153),
(140750, 'esMX', 'Teníamo\' un trato. Tú recibías poder, y tu gente me veneraba.', '', 28153),
(140749, 'esMX', 'Si eso crees, entonce\' eres tan estúpido como deshonesto, Zak\'rajan.', '', 28153),
(140748, 'esMX', 'Zandalar guarda muchos secretos. Quizá nos topamos con uno que no estábamos destinados a revelar.', '', 28153),
(140747, 'esMX', '', 'Expondremo\' a Jakra\'zet como el traidor que es.', 28153),
(140746, 'esMX', '¡Bwonsamdi, vieja escoria, por fin te vencí!', '', 28153),
(140745, 'esMX', '¡Sí! ¡Por fin me reuniré con mis ancestros en las Tierras de las Sombras!', '', 28153),
(140743, 'esMX', '¿Quiénes son los Guardianes?', '¿Quiénes son los Guardianes?', 28153),
(140742, 'esMX', '¿Qué está sucediendo? ¿Acaso mi alma es libre por fin de esa prisión?', '', 28153),
(140740, 'esMX', '¿Quién es Sethraliss?', '¿Quién es Sethraliss?', 28153),
(140739, 'esMX', 'Los infieles son una fuerza de la milicia sethrak al mando del emperador Korthek.\n\nMucho tiempo atrás, todos vivíamos en unidad, como Sethraliss hubiera querido. \n\nDesde la traición de Korthek, los infieles han traído la guerra a estas tierras. \n\nNo se detendrán hasta haber conquistado el mundo.', '', 28153),
(140738, 'esMX', '¿Quién es Korthek?', '¿Quién es Korthek?', 28153),
(140737, 'esMX', 'Los infieles no tomarán este templo.', '', 28153),
(140736, 'esMX', '¡Khaz\'goroth! ¡Forja a estos héroes a nuestra imagen!', '', 28153),
(140735, 'esMX', '', '¡Levántense, adalides! ¡Luchen para salvar su mundo!', 28153),
(140734, 'esMX', '', 'Aún hay esperanza, Gran Padre. La chispa de la vida todavía arde en estos mortales.', 28153),
(140733, 'esMX', '¡No! Después de todo lo que padecimos... ¡No puede terminar así!', '', 28153),
(140732, 'esMX', '¡El tiempo responde ante mí, Asolador! ¡La única fuerza que puede contener tu furia implacable!', '', 28153),
(140731, 'esMX', 'Los mortales han caído. El último titán... no es posible salvarlo.', '', 28153),
(140730, 'esMX', '¡La ira del Asolador se alza! ¡Rápido, héroes! ¡Destruyan estos ensamblajes!', '', 28153),
(140729, 'esMX', '', '¡Bien hecho, camarada! Ven a cazar cuando quieras. Ahora, toma un grifo y ve a Puntanzuelo. Nosotros limpiaremos esto.', 28153),
(140727, 'esMX', '', '¿Podemo\' confiar en Serrik? ¿Crees que el sethrak podrá ayudarnos a encontrar a Xal\'zaix?', 28153),
(140725, 'esMX', '', '¿Eh\'to es obra de Jakra\'zet? ¿Ya tiene a Xal\'zaix en su poder?', 28153),
(140724, 'esMX', '¡Gloria! ¡Gloria al mar!', '', 28153),
(140723, 'esMX', 'No puedes detener la marea...', '', 28153),
(140722, 'esMX', 'Ifis yahf an\'zig...', '', 28153),
(140721, 'esMX', '¡Tiembla ante la mirada de nuestro amo!', '', 28153),
(140720, 'esMX', '¡Uothk w\'shh!', '', 28153),
(140719, 'esMX', 'El mar te llama, $r.', '', 28153),
(140718, 'esMX', '¡Regresen a sus gólems, espíritus! ¡Son mis siervos, me pertenecen!', '', 28153),
(140717, 'esMX', 'Examinando', 'Examinando', 28153),
(140716, 'esMX', '', 'Su escudo ya no lo protege. ¡Ataca, ahora!', 28153),
(140715, 'esMX', '', 'Si te las ingenias, puedes obligar a los espíritus a que hagan el trabajo arduo por ti.', 28153),
(140714, 'esMX', '', 'Por eso mantengo a los viejos tótems atiborrados de espíritus furiosos, $p...', 28153),
(140713, 'esMX', '', '¡Ahí está! Me encargaré de ese molesto escudo espiritual.', 28153),
(140712, 'esMX', '¡Norgannon! ¡Que tu mente sagaz revele la debilidad de nuestro enemigo!', '', 28153),
(140711, 'esMX', 'Uno de ellos será el depositario de mi poder, Gran Padre.', '', 28153),
(140710, 'esMX', '¡Aggramar! Ofrece tu fuerza a estos mortales, hermano.', '', 28153),
(140709, 'esMX', '¡Que la furia del mar se lleve esta corrupción!', '', 28153),
(140708, 'esMX', '¡Las fuerzas de los mares y los cielos deben ayudar a nuestros adalides, Golganneth!', '', 28153),
(140707, 'esMX', '¡Tenemo\' lo\' mejore\' brebaje\' de este lado del bravo mar! ¡Métetelo\' en el garguero!', '', 28153),
(140706, 'esMX', '¿Quieres beber, makaku?', '', 28153),
(140705, 'esMX', '', 'No sé si eh\'te hombre viperino dice la verdad, pero no tenemos muchas opcione\'.', 28153),
(140704, 'esMX', '¿A kién tengo ke jeringar para konseguir un trago por akí?', '¿A kién tengo ke jeringar para konseguir un trago por akí?', 28153),
(140703, 'esMX', '¿Vendes... algo?', '¿Vendes... algo?', 28153),
(140702, 'esMX', '', 'Debemos encontrar el arma ante\' de que llegue a manos de Jakra\'zet.', 28153),
(140701, 'esMX', '', '<El jabaespín refunfuña un poco, y de vez en cuando lanza un chillido.>', 28153),
(140700, 'esMX', '¡Esos firmemares son tan valientes! ¡Yo nunca podría enfrentarme a esos monstruos! Soy bueno para transportar cargamentos.', '¡Esos firmemares son tan valientes! ¡Yo nunca podría enfrentarme a esos monstruos! Soy buena para transportar cargamentos.', 28153),
(140699, 'esMX', '', 'Vamos, Okri. Los Firmemares esperan.', 28153),
(140698, 'esMX', '', 'Ya no esperaremos tu bendición, Therold. Tenemos monstruos que matar.', 28153),
(140697, 'esMX', 'Después de encargarnos de Zak\'rajan, podremos saquear sin problemas. Todo lo que tomes será tuyo.', '', 28153),
(140696, 'esMX', '¡¿POR QUÉ?!', '¡¿POR QUÉ?!', 28153),
(140695, 'esMX', '¡AAAAAAHHHHHH!', '¡AAAAAAHHHHHH!', 28153),
(140694, 'esMX', '¡QUEMA! ¡QUEMA! ¡QUEMA!', '¡QUEMA! ¡QUEMA! ¡QUEMA!', 28153),
(140693, 'esMX', '', 'Tengo todo lo que necesitamos para destruir la barrera de Zak\'rajan. Muéstrame dónde está.', 28153),
(140692, 'esMX', '¡Así no!', '¡Así no!', 28153),
(140691, 'esMX', '¡No, no, no, NO!', '¡No, no, no, NO!', 28153),
(140690, 'esMX', '¡No, no, ESPERA!', '¡No, no, ESPERA!', 28153),
(140689, 'esMX', '', 'Yo los guiaré. No se alejen.', 28153),
(140688, 'esMX', '', 'No creas que no lo intentaron, pero gracia\' a $n, aún no he conocido a Bwonsamdi.', 28153),
(140687, 'esMX', '', 'No empieces a saquear sin mí.', 28153),
(140686, 'esMX', '', 'Me da gusto ver que las arena\' aún no te han devorado, Rakera.', 28153),
(140685, 'esMX', '', 'Mis exploradores y yo te encontraremos allí.', 28153),
(140684, 'esMX', '', 'Gracias por tu ayuda. No sé cuáles serán las consecuencias de nuestro descubrimiento, pero me alegra que al menos pudiéramos salvar a una parte del pueblo.', 28153),
(140683, 'esMX', '', 'Lord Brannon y los demás han partido del Valle Canto Tormenta para advertir sobre la corrupción entre los sacerdotes. Llevaré la información a Boralus.', 28153),
(140682, 'esMX', 'Nos veremos allí, $n. A los asuntos espirituales hay que tratarlos con delicadeza.', '', 28153),
(140681, 'esMX', '', 'Tengo justo lo que necesito para tratar esta herida...', 28153),
(140680, 'esMX', '', 'Nos hemos encontrado con algo que nos supera, $gamigo mío:amiga mía;.', 28153),
(140678, 'esMX', '', 'Eh\'peraremos aquí. Será mejor que no llamemo\' la atención de los asesinos de Jakra\'zet.', 28153),
(140677, 'esMX', 'Espera un momento...', '', 28153),
(140675, 'esMX', '', '¡Y allí va la bestia! Una pelea para el recuerdo, Firmemares.', 28153),
(140673, 'esMX', '', '¡Allí está! ¡Muéstrenle la fuerza de los Firmemares!', 28153),
(140672, 'esMX', 'El asesino furiarena desaparece en lah\' sombras.', 'La asesina furiarena desaparece en lah\' sombras.', 28153),
(140671, 'esMX', '', '¡Valor, Firmemares! ¡Denle con todo lo que tengan!', 28153),
(140670, 'esMX', '', '¡Acaben con esos tentáculos! ¡Obliguen a la bestia a salir a la superficie!', 28153),
(140669, 'esMX', '', 'Ten cuidado con los asesino\'. Jakra\'zet le ha pueh\'to un precio generoso a mi cabeza.', 28153),
(140667, 'esMX', 'Eh\'te mundo será nuestro. ¡Zul ya lo ha visto!', 'Eh\'te mundo será nuestro. ¡Zul ya lo ha visto!', 28153),
(140666, 'esMX', 'No puede\' detener lo que se avecina. Zul lo ha visto todo.', 'No puede\' detener lo que se avecina. Zul lo ha visto todo.', 28153),
(140665, 'esMX', '¿Traes a nuestro fracaso de rey? Morirá, y tú no puede\' hacer nada para impedirlo.', '¿Traes a nuestro fracaso de rey? Morirá, y tú no puede\' hacer nada para impedirlo.', 28153),
(140664, 'esMX', 'Llega\' tarde. Zul ya está en marcha hacia la cima.', 'Llega\' tarde. Zul ya está en marcha hacia la cima.', 28153),
(140663, 'esMX', 'La Horda caerá. La Alianza caerá. ¡Y Zandalar se alzará!', 'La Horda caerá. La Alianza caerá. ¡Y Zandalar se alzará!', 28153),
(140662, 'esMX', '¡Zandalar gobernará eh\'te mundo!', '¡Zandalar gobernará eh\'te mundo!', 28153),
(140661, 'esMX', '¡Nosotro\' luchamo\' por un verdadero imperio trol!', '¡Nosotro\' luchamo\' por un verdadero imperio trol!', 28153),
(140660, 'esMX', '¡Mi vida por Zul!', '¡Mi vida por Zul!', 28153),
(140659, 'esMX', '¡El terror del mar, bajo la influencia del maestro sombrío de Celaoscuro! Quizá sea un monstruo demasiado grande, incluso para los Firmemares.', '', 28153),
(140656, 'esMX', 'Me he enfrentado a hombres más altos que tú, y todos terminaron en el piso.', '', 28153),
(140655, 'esMX', 'Que nadie toque... mi botín...', '', 28153),
(140654, 'esMX', 'No puede ser…', '', 28153),
(140653, 'esMX', '¡Hombres! Muéstrenles nuestra artillería a estos bribones.', '', 28153),
(140652, 'esMX', '¡Cañones! ¡Vuelen en pedazos a estos perros despreciables!', '', 28153),
(140651, 'esMX', 'Revisen si tiene oro en los dientes, muchachos. El resto, a los tiburones.', '', 28153),
(140650, 'esMX', 'Me encanta el ruido de un cadáver cuando cae a cubierta.', '', 28153),
(140649, 'esMX', '', '¡G\'huun quedará en libertad y los seguidore\' de Hir\'eek recibirán su recompensa!', 28153),
(140648, 'esMX', 'Vamos, muchachos, arrebátenles sus tesoros. Yo elijo primero, y ustedes pueden pelearse por las sobras.', '', 28153),
(140647, 'esMX', 'Cometieron el error más viejo de la historia. ¡Nunca te enfrentes a Sweete si hay un botín en juego!', '', 28153),
(140646, 'esMX', '¡Frieguen la cubierta con sus pellejos!', '', 28153),
(140645, 'esMX', '¡Todos a cubierta!', '', 28153),
(140644, 'esMX', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:255594|h[Cielo y mar]|h|r!', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:255594|h[Cielo y mar]|h|r!', 28153),
(140643, 'esMX', '', 'Impresionante. Llegaron más lejo\' de lo que esperaba... Pero igual beberé su sangre.', 28153),
(140642, 'esMX', '', 'Rezan era un loa poderoso. Quizá ustede\' sean un sacrificio digno para Zul.', 28153),
(140641, 'esMX', '', 'Les agradeh\'co por asesinar a la sacerdotisa. ¡No han hecho má\' que afianzar mi dominio sobre el templo!', 28153),
(140640, 'esMX', '¡Esto me complace! Lleven más a mi guarida... ¡Debo comunicarme con el amo!', '', 28153),
(140639, 'esMX', '', 'La amenaza de los ignotos eh\'tá contenida por ahora, pero yo seguiré vigilando Atul\'Aman para asegurarme de que nada cambie.', 28153),
(140638, 'esMX', '', '¿Otra vez despedazaron a Vol\'kaal? No importa... puedo reconstruirlo. ¡Pero cuando USTEDE\' mueran, no podrán regresar!', 28153),
(140637, 'esMX', '¡A volar!', '¡A volar!', 28153),
(140636, 'esMX', '¡Estamos bajo asedio! ¡Sígueme y ayúdame a detener el embate del monstruo!', '', 28153),
(140635, 'esMX', '¡Avísame cuando estés $glisto:lista; para ir! ¡Tenemos poco tiempo y el monstruo no dudará!', '', 28153),
(140634, 'esMX', '', '¡Muy pronto Zul deh\'pertará a Dazar! ¡Y el imperio trol se alzará otra vez!', 28153),
(140633, 'esMX', '', '¡Llegan demasiado tarde, forasteros! Ahora eh\'te templo le pertenece a mi amo.', 28153),
(140632, 'esMX', '¡JA! ¡Funciona! ¡Sigue apuñalándolo! ¡No te detengas!', '', 28153),
(140631, 'esMX', 'Como no superamos a los sethrak en número, tenemos que superarlos en inteligencia.', '', 28153),
(140630, 'esMX', '', 'Toma lo que puedas, cuando puedas y de quien puedas.', 28153),
(140629, 'esMX', '', 'Cualquier cosa puede tener un propósito si te aferras a eso el tiempo suficiente.', 28153),
(140628, 'esMX', '|TInterface\\Icons\\ABILITY_MOUNT_EPICBATMOUNT.BLP:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:256497|h[Horror sangriento]|h|r! ¡Cúbrete!', '', 28153),
(140627, 'esMX', 'Bien... Cree que estamos muertos. Necesitamo\'... un nuevo plan.', '', 28153),
(140626, 'esMX', 'Tanta bravuconería... para terminar muriendo en mi guarida. Consumiré los restos... cuando me recupere.', '', 28153),
(140625, 'esMX', '', 'Los vientos te guiarán a Atul\'Aman ahora... ¡prepárate!', 28153),
(140624, 'esMX', '', 'Depende de nosotroh\' encontrar la fuente de la perturbación y ponerle fin.', 28153),
(140623, 'esMX', '', 'Desde hace siglos, crece un poder oscuro en Atul\'Aman. Presiento que los elementos están cada vez más inquietos...', 28153),
(140622, 'esMX', '¡Equipos de morteros! ¡Derriben la fortaleza! ¡Que no quede nada!', '', 28153),
(140621, 'esMX', '', 'Los ecoh\' del estallido siguen resonando en los elementoh\'. ¿Qué clase de poder puede haber causado semejante devastación?', 28153),
(140620, 'esMX', '', 'Atul\'Aman, que supo ser una construcción magnífica, quedó destruido deh\'pués de una catah\'trófica explosión hace miles de años.', 28153),
(140619, 'esMX', 'Cúbrete, ¡Hir\'eek se acerca!', '', 28153),
(140618, 'esMX', '', 'Coloca las manos sobre la piedra de chamán y yo invocaré un ciclón que te lleve a Atul\'Aman.', 28153),
(140617, 'esMX', '', 'Hay que lidiar con los eh\'córpidos colavítrea, pero me temo que nos espera una amenaza aún peor.', 28153),
(140616, 'esMX', '¡¡Aaahhh!!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140615, 'esMX', 'Eres fuerte... ¡Pero nada se compara con el poder de un loa!', '', 28153),
(140614, 'esMX', '¡YA BASTA! ¡Me daré un festín con tus huesos rotos!', '', 28153),
(140613, 'esMX', 'El poder de mi amo fluye por mi ser... ¡Y me salvará de esta infección!', '', 28153),
(140612, 'esMX', 'Voy a... ¡Auugghh! ¿Qué?... ¿Veneno? ¡¿Qué me hiciste?!', '', 28153),
(140611, 'esMX', '¡Ja! ¿Pero qué pretendes hacer? ¡Soy el señor de los cielos!', '', 28153),
(140610, 'esMX', '', '¿Qué otra opción tenemo\'?', 28153),
(140609, 'esMX', '', '¡Rakera! ¿Realmente creeh\' en lo que dice?', 28153),
(140608, 'esMX', '', 'Entonceh\' tendrás nuestra ayuda, Serrik.', 28153),
(140607, 'esMX', 'Reúne los componentes del ritual y te ayudaremos a buscar tu artefacto perdido.', '', 28153),
(140606, 'esMX', 'Esa visión fue más útil de lo que me imaginaba. Xal\'zaix está a nuestro alcance.', '', 28153),
(140605, 'esMX', '¿Qué es lo que nos indicará este ritual, exactamente? ¿Ya estamo\' cerca de encontrar a Xal\'zaix?', '', 28153),
(140604, 'esMX', '¿Realmente confías en esta\' serpiente\'? Creo que saben más de lo que dicen...', '', 28153),
(140603, 'esMX', 'Mi gente puede ayudarte a encontrar a este Xal... ¿Cómo se llamaba? ¿Xal\'zaix?', '', 28153),
(140602, 'esMX', '¿Permitirá\' que me dejen encerrado aquí?', '', 28153),
(140601, 'esMX', 'La búsqueda de Rakera es inútil. Su destino quedó sellado cuando la enviaron a las arena\'.', '', 28153),
(140600, 'esMX', '', '¡La bóveda fue sellada! ¡No puede eh\'tar vacía! No tiene sentido...', 28153),
(140599, 'esMX', '', 'Lo que ha hecho Jakra\'zet...', 28153),
(140596, 'esMX', 'No puedes detener... a la arena...', '', 28153),
(140595, 'esMX', '¡El templo debe caer! Masacraremos a todos los que se interpongan en nuestro camino.', '', 28153),
(140594, 'esMX', 'Fue un placer hacer negocios con ustedes. Pero si no les importa, me marcharé antes de que noten mi ausencia.', '', 28153),
(140593, 'esMX', 'Como prometí, aquí hay algunas vestimentas de los Corsarios surcamar. Ahora sí se ven como verdaderos criminales.', '', 28153),
(140592, 'esMX', '¡Estallarás como el vidrio!', '¡Te quebrarás como el vidrio!', 28153),
(140591, 'esMX', '¡Por el emperador!', '¡Por el emperador!', 28153),
(140590, 'esMX', '¡Lo lograron! Sabía que mi perrito ayudaría. El mejor amigo del hombre, ese mismo.', '', 28153),
(140589, 'esMX', '¡Los erradicaremos como insectos!', '¡Los erradicaremos como insectos!', 28153),
(140588, 'esMX', 'Como la arena, ¡te dispersarás y te olvidarán!', 'Como la arena, ¡te dispersarás y te olvidarán!', 28153),
(140587, 'esMX', '¡Las arenas te devorarán!', '¡Las arenas te devorarán!', 28153),
(140586, 'esMX', '¡Lo dominaremos todo!', '¡Lo dominaremos todo!', 28153),
(140585, 'esMX', '¡No puedes evitar que las arenas se esparzan!', '¡No puedes evitar que las arenas se esparzan!', 28153),
(140584, 'esMX', '¡Tus tierras serán las próximas en caer!', '¡Tus tierras serán las próximas en caer!', 28153),
(140583, 'esMX', 'Así que... si me hacen un favor, tal vez pueda corresponderles. ¿Qué dicen?', '', 28153),
(140582, 'esMX', 'Pero antes, tengo un problema. Esta cerradura no cede. Ese perro sarnoso tiene la llave, pero es un demonio muy escurridizo.', '', 28153),
(140581, 'esMX', '¡Voy a disfrutar eh\'to!', '¡Eh\'to va a estar bueno!', 28153),
(140580, 'esMX', '¡Jakra\'zet reclama una muerte!', '¡Jakra\'zet quiere tu cadáver!', 28153),
(140579, 'esMX', '¡Le han pueh\'to precio a tu cabeza!', '¡Le han pueh\'to precio a tu cabeza!', 28153),
(140578, 'esMX', 'Si están ansiosos por causar estragos, tendrán que presentarse ante el consejo de capitanes. Y yo puedo ayudarlos.', '', 28153),
(140576, 'esMX', '¡Ah! ¡Te cortaré a la mitad!', '¡Te haré pedazos!', 28153),
(140575, 'esMX', '¡Jakra\'zet te manda saludos!', '¡Jakra\'zet te manda saludos!', 28153),
(140574, 'esMX', '¡Ah, del barco! Ustedes parecen ser unos degolladores de ley. No como la escoria de aquí que se hace pasar por piratas.', '', 28153),
(140573, 'esMX', '¡Furia de acero!', '', 28153),
(140572, 'esMX', '¡En guardia!', '', 28153),
(140571, 'esMX', '', 'Yo nunca fallo.', 28153),
(140570, 'esMX', '', '¡Me encanta ver a mi enemigo retorcerse!', 28153),
(140569, 'esMX', '¡Cuidado!', '', 28153),
(140568, 'esMX', '¡Este barril está gastado! ¡Tomen!', '', 28153),
(140567, 'esMX', 'Buh\'ca a Krag\'wa, el pequeño te encontrará ahí.', '', 28153),
(140566, 'esMX', '¿Creen que pueden conmigo, cerdos? Es hora de darles una lección.', '', 28153),
(140565, 'esMX', '', 'Nunca antes había vih\'to a un sethrak suplicar piedad. Quizá diga la verdad.', 28153),
(140564, 'esMX', '', 'No tenemoh\' tiempo para tomar prisioneros. ¡Hay que ejecutarlo y terminar con eh\'to!', 28153),
(140563, 'esMX', '', '¡Mientes! ¡Lo\' sethrak asesinan y saquean todo lo que encuentran a su paso!', 28153),
(140562, 'esMX', '¡Siente la furia del mar!', '', 28153),
(140561, 'esMX', 'Cuidado con el entorno.', '', 28153),
(140560, 'esMX', '¡No soy tu enemigo! ¡Debes creerme!', '', 28153),
(140559, 'esMX', 'Sepúltenme con mi espada...', '', 28153),
(140558, 'esMX', '¡No quiero hacerte daño! ¡Por favor... no me mates!', '', 28153),
(140557, 'esMX', '¡Eh\'te es mío!', '¡Yo me encargo de $ueh\'te:eh\'ta;!', 28153),
(140556, 'esMX', '¡Te arrepentirás de haber pueh\'to un pie en esta tierra!', '¡Te arrepentirás de haber pisado esta tierra!', 28153),
(140555, 'esMX', 'Tenemo\' órdenes de matar a $Ueste:esta;.', 'Tenemo\' órdenes de matar a $Ueste:esta;.', 28153),
(140554, 'esMX', '¡Lo que tenga\' pronto será mío!', '¡Lo que tenga\' pronto será mío!', 28153),
(140553, 'esMX', 'Ah... ¿Alguna vez encontraré un rival que esté a mi altura?', '', 28153),
(140552, 'esMX', '¡Esta no e\' tu pelea!', '¡Esta no e\' tu pelea!', 28153),
(140551, 'esMX', '¡Has vih\'to demasiado para vivir!', '¡Has vih\'to demasiado!', 28153),
(140550, 'esMX', '¡No tiene\' nada que hacer aquí!', '¡No tiene\' nada que hacer aquí!', 28153),
(140549, 'esMX', '¡Primera sangre!', '', 28153),
(140548, 'esMX', 'Un gran golpe de gracia.', '', 28153),
(140546, 'esMX', '¡Pongamos a prueba tu temple!', '', 28153),
(140545, 'esMX', '', '¡Coman metralla, perros sarnosos!', 28153),
(140544, 'esMX', '', '¡Las cosas están por ponerse divertidas!', 28153),
(140542, 'esMX', '', '¡Pueden correr, pero no pueden esconderse!', 28153),
(140541, 'esMX', '', '¡Te tengo en la mira!', 28153),
(140540, 'esMX', '', 'Buen... disparo...', 28153),
(140539, 'esMX', '', 'Ohh, todavía me quedaban balas.', 28153),
(140538, 'esMX', '', 'Deja que ello\' se preocupen por los sethrak por ahora. Tú y yo debemo\' abrir la bóveda y encontrar a Xal\'zaix.', 28153),
(140537, 'esMX', '', 'Entre ceja y ceja.', 28153),
(140536, 'esMX', '', '¡Otra marca en mi cañón!', 28153),
(140535, 'esMX', '', 'Sus calaveras serán excelentes para practicar tiro al blanco.', 28153),
(140534, 'esMX', '¡Hora de caminar por la plancha!', '', 28153),
(140533, 'esMX', '¡Yo invito esta ronda!', '', 28153),
(140532, 'esMX', '¡Beban, perros de agua dulce!', '', 28153),
(140531, 'esMX', 'Jamás funcionará. Somo\' leales a Rastakhan, no a eh\'te falso profeta.', '', 28153),
(140530, 'esMX', '¡Déjame darte una mano!', '', 28153),
(140529, 'esMX', '¡Hasta el fondo, ratas de sentina!', '', 28153),
(140528, 'esMX', 'Lo único que conseguirá será una visita a Bwonsamdi si e\' por mí.', '', 28153),
(140527, 'esMX', '', 'Ve y armoniza esa esfera. Los demá\' iremos a las Ruina\' de Atul\'Aman para buscar la bóveda de Xal\'zaix.', 28153),
(140526, 'esMX', '', 'No solo se llevó la flota a Pandaria, ¡sino que ahora intenta quedarse con todo Zuldazar!', 28153),
(140525, 'esMX', '', 'Jamá\' confié en Zul, ¡maldito demonio traicionero!', 28153),
(140524, 'esMX', 'Volveré cuando haya terminado, madre.', '', 28153),
(140523, 'esMX', '¿Fue la... última ronda...?', '', 28153),
(140522, 'esMX', '¡Ya voy, madre! Haré lo que sea.', '', 28153),
(140521, 'esMX', '¡Creo que no habrá más ron para ti!', '', 28153),
(140520, 'esMX', '¡Deberías aprender a beber, camarada!', '', 28153),
(140519, 'esMX', '¡Lo que usté diga!', '', 28153),
(140518, 'esMX', 'El campamento necesita más roca. Ve a buh\'car solo las rocas de mayor pureza de Nazmir. Trae exactamente sesenta.', 'El campamento necesita más roca. Ve a buh\'car solo las rocas de mayor pureza de Nazmir. Trae exactamente sesenta.', 28153),
(140517, 'esMX', 'Necesitaré otro trago antes de ver sus horribles caras otra vez.', '', 28153),
(140516, 'esMX', 'El campamento necesita más madera. ¡Ve a buh\'car treinta piezas de la madera más prístina! ¡Nada inferior!', 'El campamento necesita más madera. ¡Ve a buh\'car treinta piezas de la madera más prístina! ¡Nada inferior!', 28153),
(140515, 'esMX', '¡Sí, madre! Eh\'peraré aquí, tal como me dijeron.', '', 28153),
(140514, 'esMX', 'Necesitaremo\' cincuenta pellejo\' de crocolisco prístinos. Ve a buscarlos y no vuelvas hasta que tengas todo.', 'Necesitaremo\' cincuenta pellejo\' de crocolisco prístinos. Ve a buscarlos y no vuelvas hasta que tengas todo.', 28153),
(140513, 'esMX', '¿Qué puedo hacer por usté\'?', '', 28153),
(140512, 'esMX', '¿Te gustan mis lindas aves?', '', 28153),
(140511, 'esMX', 'Muéstrame adónde puedo ir volando.', 'Muéstrame adónde puedo ir volando.', 28153),
(140510, 'esMX', '', '¡Sus alma\' son mías!', 28153),
(140509, 'esMX', '', '¡Ahora eh\'tás bajo mi poder!', 28153),
(140508, 'esMX', '', '¡Sus almas quedarán destrozada\'!', 28153),
(140507, 'esMX', '', '¡Despedazaré sus alma\'!', 28153),
(140506, 'esMX', '', '¡Por la Horda!', 28153),
(140505, 'esMX', '¡Por la Horda!', '', 28153),
(140504, 'esMX', '', '¡Por la Horda!', 28153),
(140503, 'esMX', '', 'A partir de este día, Altamontaña jura luchar junto a ti contra cualquier enemigo.', 28153),
(140502, 'esMX', '', 'Acepto tu juramento de lealtad. La Horda te ofrece su protección... y espera tu obediencia.', 28153),
(140501, 'esMX', '', 'Jefa de guerra, la fortaleza y la valentía de la Horda han quedado demostradas por Baine Pezuña de Sangre y por tu adalid.', 28153),
(140500, 'esMX', '', '¿Qué tienes para decir, jefa?', 28153),
(140499, 'esMX', '¡La Horda se enorgullece en darles la bienvenida! Viajemos a Orgrimmar para llevarle la buena noticia a nuestra Jefa de Guerra.', '', 28153),
(140498, 'esMX', '', 'Si nos aceptas, para los tauren de Altamontaña será un honor unirse a la Horda.', 28153),
(140497, 'esMX', '', 'Baine Pezuña de Sangre, has demostrado valentía, honor y lealtad. Es hora de que tu pueblo y el mío renueven su vínculo.', 28153),
(140496, 'esMX', 'Me estremezco de solo pensarlo, Mayla. Sin la rápida intervención de Baine y $Geste adalid:esta adalid;, habría sido el fin.', '', 28153),
(140495, 'esMX', '', 'Si los planes de Uul\'gyneth se hubieran hecho realidad, todos nos habríamos convertido en sirvientes de los dioses antiguos... También Ebacuerno.', 28153),
(140494, 'esMX', '', 'Estuvo cerca de ser un día muy oscuro para Azeroth.', 28153),
(140493, 'esMX', '', '¡Tontos! Zul hará pedazos... sus alma\'...', 28153),
(140492, 'esMX', 'Los susurros... se han silenciado. Adalid, Cielo Gris, les doy las gracias.', '', 28153),
(140491, 'esMX', '', 'Ebacuerno no está bien. Debemos encontrar la manera de hacerlo volver en sí. Habla con el caminaespíritus Cielo Gris. Creo que puede ayudarnos.', 28153),
(140490, 'esMX', 'Mulgore jamás estará a salvo hasta que descubramos qué se oculta detrás de este ataque. Iré contigo, Mayla. Enfrentemos juntos la oscuridad.', '', 28153),
(140489, 'esMX', '', '¡Debo llevar a Ebacuerno de vuelta a Altamontaña! ¡De inmediato!', 28153),
(140488, 'esMX', 'Conozco demasiado bien ese poder. ¡Adalid! ¡Necesitamos tu ayuda!', '', 28153),
(140487, 'esMX', '', '¡Ebacuerno! ¿Qué fuerza oscura nubla tu mente?', 28153),
(140486, 'esMX', 'Nunca debí... abandonar... la montaña...', '', 28153),
(140485, 'esMX', 'Justamente de vínculos quiero hablar. Espero que...', '', 28153),
(140484, 'esMX', '', 'Has sido muy amable en invitarme, Baine. Ya es hora de que nuestros pueblos renueven su vínculo.', 28153),
(140483, 'esMX', 'Gracias por venir, Mayla. Es un honor darte la bienvenida a Mulgore.', '', 28153),
(140482, 'esMX', '', '¡Tu sangre me pertenece!', 28153),
(140481, 'esMX', '', 'Le daré un buen uso a su sangre... ahora que no la necesitan.', 28153),
(140480, 'esMX', '', 'Dazar despertará pronto, ¡pero ustede\' no vivirán para verlo!', 28153),
(140479, 'esMX', '¡Nuestras fuerzas ahora tienen armaduras de acero!', '¡Nuestras fuerzas ahora tienen armaduras de acero!', 28153),
(140478, 'esMX', '$gUn traidor:Una traidora;, ¿eh? ¡$GAtrápenlo:Atrápenla;!', '$gUn traidor:Una traidora;, ¿eh? ¡$GAtrápenlo:Atrápenla;!', 28153),
(140477, 'esMX', '¡Quita las manos de ahí!', '¡Quita las manos de ahí!', 28153),
(140476, 'esMX', '¡¿Qué crees que estás haciendo?!', '¡¿Qué crees que estás haciendo?!', 28153),
(140475, 'esMX', 'Cuando hayan escuchado mis palabras, deja el cristal en la cima del Monte Hyjal, en las orillas del Pozo de la Eternidad.', '', 28153),
(140474, 'esMX', 'Este cristal guarda dos mensajes. Uno es para mi hermano, Malfurion, y el otro es para Tyrande. Te encargo la misión de entregarlos por mí, adalid.', '', 28153),
(140473, 'esMX', 'Enfrentaré mi destino, sin importar cuál sea. Sin embargo... tengo ciertos asuntos pendientes... viejas heridas que preferiría curar.', '', 28153),
(140472, 'esMX', 'En el momento en que se abrió el camino a Argus... en el instante en que avisté el mundo natal de la Legión... supe que no regresaría.', '', 28153),
(140471, 'esMX', '¡Nuestras fuerzas ahora tienen armas de acero!', '¡Nuestras fuerzas ahora tienen armas de acero!', 28153),
(140470, 'esMX', 'Yo soportar dolor, ¡yo lih\'to para pelear!', '', 28153),
(140469, 'esMX', 'No seré débil, ¡no sentiré dolor! ¡Estoy listo para matar!', '', 28153),
(140468, 'esMX', '¡Puedo soportar más dolor! ¡Mataré todo lo que se cruce en mi camino!', '', 28153),
(140467, 'esMX', '¡Soy fuerte! ¡Puedo recibir un golpe más duro, mamá!', '', 28153),
(140464, 'esMX', '$n, dile a esa criatura que me conoces. ¡No puede dejarme así enjaulado!', '', 28153),
(140463, 'esMX', 'Arrancando.', 'Arrancando.', 28153),
(140462, 'esMX', 'Ahh... Así está mejor.', '', 28153),
(140461, 'esMX', 'Ahí tienes. Y ahora, ¡brindemos por días mejores!', '', 28153),
(140460, 'esMX', '¿Sí?', '', 28153),
(140459, 'esMX', '', '¡Un sacrificio digno!', 28153),
(140458, 'esMX', '', '¡Súbete! ¡Puede que ya sea tarde!', 28153),
(140457, 'esMX', 'Mi ama me reconh\'truirá...', '', 28153),
(140456, 'esMX', 'Jajajaja... Mi ama usará sus partes. ¡Y me hará má\' fuerte!', '', 28153),
(140455, 'esMX', '¡Carne para mi ama!', '', 28153),
(140454, 'esMX', 'Eh\'tás $ghecho:hecha; pedazos.', '', 28153),
(140453, 'esMX', '¡Ustede\' mueren conmigo!', '', 28153),
(140452, 'esMX', '¡No romper!', '', 28153),
(140451, 'esMX', '¡El poder se deh\'vanece!', '', 28153),
(140450, 'esMX', '¡No destruir tótem!', '', 28153),
(140449, 'esMX', '¡Noooo!', '', 28153),
(140448, 'esMX', '¡Aplah\'tar!', '', 28153),
(140447, 'esMX', '¡Deh\'truir!', '', 28153),
(140446, 'esMX', '¡¿Ustedes?! ¡Los haré pedazo\'!', '', 28153),
(140445, 'esMX', '', 'Por fin llegah\'te. Los elementoh\' susurraban sobre tu llegada...', 28153),
(140444, 'esMX', 'Zissiah y yo nos adelantaremos para avisarle a Vorrik de tu llegada.', '', 28153),
(140441, 'esMX', '¿Qué más puedes decirme?', '¿Qué más puedes decirme?', 28153),
(140439, 'esMX', '¿Quiénes son los infieles?', '¿Quiénes son los infieles?', 28153),
(140438, 'esMX', 'Los infieles jamás detendrán su asedio, pero gracias a tus esfuerzos, hemos ganado mucho tiempo. Encontraremos a nuestra loa y pondremos fin a esta batalla.', '', 28153),
(140437, 'esMX', 'Los infieles asedian nuestro hogar. ¡Debemos repelerlos! No podemos permitir que se apoderen del templo.', '', 28153),
(140436, 'esMX', '¡Ahh, ere\' muy $gaburrido, hermano:aburrida, hermana;!', '¡Ahh, ere\' muy $gaburrido, hermano:aburrida, hermana;!', 28153),
(140435, 'esMX', '¡Eso e\' una tontería de acá a la Luna! Supongo que no me queda má\' remedio que irme a casa.', '¡Eso e\' una tontería de acá a la Luna! Supongo que no me queda má\' remedio que irme a casa.', 28153),
(140434, 'esMX', '¡Rawr! Rawr rawr ra... oh.', '¡Rawr! Rawr rawr ra... oh.', 28153),
(140433, 'esMX', 'Ere\' $Gun auténtico aguafiesta\':una auténtica aguafiesta\';, colega.', 'Ere\' $Gun auténtico aguafiesta\':una auténtica aguafiesta\';, colega.', 28153),
(140432, 'esMX', '¡Sí! ¡Ser más grande e\' mucho más divertido!', '¡Sí! ¡Ser más grande e\' mucho más divertido!', 28153),
(140431, 'esMX', '¡Iujuuu! Eh\'to es divertido... Emm... ¡Grrrr!', '¡Iujuuu! Eh\'to es divertido... Emm... ¡Grrrr!', 28153),
(140430, 'esMX', '¡Ups, cuidado! ¡No veo por dónde voy!', '¡Ups, cuidado! ¡No veo por dónde voy!', 28153),
(140429, 'esMX', '¡Soy un raptor poderoso, igual que Gonk! ¡Ja, ja!', '¡Soy un raptor poderoso, igual que Gonk! ¡Ja, ja!', 28153),
(140428, 'esMX', '', '¡Ahh, ereh\' muy $gaburrido, hermano:aburrida, hermana;!', 28153),
(140427, 'esMX', '', '¡Eso es una tontería de acá a la Luna! Supongo que no me queda má\' remedio que irme a casa.', 28153),
(140426, 'esMX', '', '¡Rawr! Rawr rawr ra... oh.', 28153),
(140425, 'esMX', '', 'Ere\' $Uun auténtico aguafiesta\':una auténtica aguafiesta\';, colega.', 28153),
(140424, 'esMX', 'Desháganse de ellos. ¡Nueh\'tro trabajo está a punto de terminar!', '', 28153),
(140423, 'esMX', '', '¡Sí! ¡Ser más grande es mucho máh\' divertido!', 28153),
(140422, 'esMX', '', '¡Iujuuu! Eh\'to es divertido... Emm... ¡Grrrr!', 28153),
(140421, 'esMX', '', '¡Ups, cuidado! ¡No veo por dónde voy!', 28153),
(140420, 'esMX', '', '¡Soy un raptor poderoso, igual que Gonk! ¡Ja, ja!', 28153),
(140419, 'esMX', 'Eres $Gun auténtico:una auténtica; aguafiestas, colega.', '', 28153),
(140418, 'esMX', '¡Rawr! Rawr rawr ra... oh.', '', 28153),
(140417, 'esMX', '¡Eso es una tontería de acá a la Luna! Supongo que no me queda máh\' remedio que irme a casa.', '', 28153),
(140416, 'esMX', '¡Ahh, ereh\' muy $gaburrido, hermano:aburrida, hermana;!', '', 28153),
(140415, 'esMX', '¡Soy un ravasaurio poderoso, igual que Gonk! ¡Ja, ja!', '', 28153),
(140414, 'esMX', '¡Ups, cuidado! ¡No veo por dónde voy!', '', 28153),
(140413, 'esMX', '¡Iujuuu! Eh\'to es muy divertido... Emm... ¡Grrrr!', '', 28153),
(140412, 'esMX', '¡Sí! ¡Ser más grande es mucho máh\' divertido!', '', 28153),
(140411, 'esMX', '¡Mi ama quiere sus hueso\'!', '', 28153),
(140410, 'esMX', '¡Rawk! ¡Percebes! ¡Rawk!', '', 28153),
(140409, 'esMX', '¡Rawk! ¡Dispárales una andanada! ¡Rawk!', '', 28153),
(140408, 'esMX', '¡Rawk! ¡Al armario! ¡Rawk!', '', 28153),
(140407, 'esMX', '¡Rawk! ¡Vaciar mi cargamento! ¡Rawk!', '', 28153),
(140406, 'esMX', '¡Rawk! ¡Cerdos! ¡Rawk!', '', 28153),
(140405, 'esMX', '¡Ja! ¡No es hora de tomar sol en la cubierta!', '', 28153),
(140404, 'esMX', 'Creo.. que me iré... al armario…', '', 28153),
(140403, 'esMX', '¡No eras más que carnada!', '', 28153),
(140402, 'esMX', '¡Los muertos no cuentan cuentos!', '', 28153),
(140401, 'esMX', '¡Parece que a alguien le cuesta mantener el equilibrio!', '', 28153),
(140400, 'esMX', '¡Ajá! No olvidarás ese sabor fácilmente.', '', 28153),
(140399, 'esMX', '¡Esto entrará justo por la portilla!', '', 28153),
(140398, 'esMX', '¡Los voy a despellejar!', '', 28153),
(140397, 'esMX', '¡Aquí les va una descarga en cubierta!', '', 28153),
(140396, 'esMX', 'Derramar la bebida de un hombre es de mala suerte.', '', 28153),
(140395, 'esMX', '¡No! Un minuto de silencio para mi grog caído.', '', 28153),
(140394, 'esMX', '¡Ah! ¡Se me derramó sobre el ancla!', '', 28153),
(140393, 'esMX', '¡Sin piedad!', '', 28153),
(140392, 'esMX', '¡A toda velocidad!', '', 28153),
(140391, 'esMX', '¡Lo\' zandalari nunca mueren!', '', 28153),
(140390, 'esMX', 'Hora de que corra sangre.', '', 28153),
(140389, 'esMX', '¡Que los eh\'píritu\' te acompañen!', '', 28153),
(140388, 'esMX', '¡Oigo los llamamiento\'!', '', 28153),
(140387, 'esMX', 'Jo, jo, jo... Bueno, muy bien... ¡Ahora, $n!', '', 28153),
(140386, 'esMX', '¿Piedad? ¡Insecto patético! ¡Te destruiremos junto con Zuldazar!', '', 28153),
(140385, 'esMX', '¡Gran Hir\'eek! Te suplicamos piedad, oh, poderoso loa. ¡Sálvanos!', '', 28153),
(140384, 'esMX', '¡Carrrrrrrrrga!', '', 28153),
(140383, 'esMX', 'Jo\'chunga, estoy listo. Pongamos en marcha nuestro plan para detener a Hir\'eek.', 'Jo\'chunga, estoy lista. Pongamos en marcha nuestro plan para detener a Hir\'eek.', 28153),
(140382, 'esMX', 'Oh, es una locura... No pensé que me eh\'taba metiendo en una misión para matar a un LOA cuando todo eh\'to empezó.', '', 28153),
(140381, 'esMX', '¡Aaargh! ¡Ceburón, vuelve aquí y dispárales una andanada!', '', 28153),
(140380, 'esMX', 'Mis fieles... apártense. Vengan, profanadores, y enfrenten la muerte. ¡Su sangre alimentará a G\'huun!', '', 28153),
(140379, 'esMX', '¡Cuidado abajo, cerdos con cola de percebe!', '', 28153),
(140378, 'esMX', '¡Explosión final!', '', 28153),
(140377, 'esMX', '¡Ya me cansé de ti!', '', 28153),
(140376, 'esMX', '¡Muere y calla para siempre!', '', 28153),
(140375, 'esMX', 'Hay muchos trols aquí, pero no quieren pelear.$b$bNo llegarán a los Salones del Valor con esa actitud. ¡Debemos buscar la gloria en el campo de batalla!$b$b¿Dónde está su rey? El comprenderá. ¡Quizás incluso presente una batalla digna!', '', 28153),
(140374, 'esMX', '¿Viniste a pelear? Me vendría bien un enfrentamiento de práctica.', '', 28153),
(140373, 'esMX', '', 'Queremos mejorar a través de la batalla y encontrar la gloria que nos permitirá alcanzar los Salones del Valor.$b$bEl rey de este sitio es fuerte y ha reinado durante cientos de años. Será un digno rival. ¡Lo único que tenemos que hacer es encontrarnos con el rey y desafiarlo a un combate glorioso!', 28153),
(140372, 'esMX', '', '¡Asalto divino!', 28153),
(140371, 'esMX', '', '¡Grabaré mi victoria en tu alma!', 28153),
(140370, 'esMX', '', '¡Ven, $Gguerrero:guerrera;! ¡La batalla nos espera!', 28153),
(140369, 'esMX', '¡Fuera bombas!', '', 28153),
(140368, 'esMX', '', 'Busco guerreros nobles para que se me unan en la batalla.', 28153),
(140367, 'esMX', 'No se preocupen por Ceburón. Solo tiene que... ¡vaciar su cargamento!', '', 28153),
(140366, 'esMX', '¡Su perdición se acerca!', '', 28153),
(140364, 'esMX', '¡Ceburón, leva el ancla y mueve tus malditas plumas! Tenemos que lidiar con unos mequetrefes.', '', 28153),
(140363, 'esMX', '¡Intrusos!', '', 28153),
(140362, 'esMX', '¡Espero que hayan preparado sus testamentos!', '', 28153),
(140361, 'esMX', '¡Atrás, percebes descerebrados!', '', 28153),
(140360, 'esMX', '¿A quién quiere\' que mate?', '', 28153),
(140359, 'esMX', '', '¡Tomaremos posición en la isla y te avisaremos si hay alguna novedad!', 28153),
(140358, 'esMX', '¡Larga vida al rey!', '', 28153),
(140357, 'esMX', '¡Bwonsamdi me ha dado otra oportunidad!', '', 28153),
(140356, 'esMX', '¡Taz\'dingo!', '', 28153),
(140355, 'esMX', '', '¡Eh\'te oro es mío!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140354, 'esMX', '', '¡No pueden entrar aquí!', 28153),
(140353, 'esMX', '', 'Mis garra\' llegarán a sus corazone\'.', 28153),
(140352, 'esMX', '', 'No hay tiempo que perder. ¡Nos veremos cerca de la cueva!', 28153),
(140335, 'esMX', 'Es el momento. O el plan funciona... o estamo\' fritos.', '', 28153),
(140334, 'esMX', 'Oh, no... ¡es Hir\'eek!', '', 28153),
(140333, 'esMX', 'La princesa Talanji tiene mucha curiosidad por saber qué pasa aquí en lo\' pantano\'.', '', 28153),
(140332, 'esMX', '', 'El oro acude a mi llamado.', 28153),
(140331, 'esMX', '', '¡Purificaremo\' la corrupción!', 28153),
(140330, 'esMX', '', '¡El poder de Atal\'Dazar fluye por mis vena\'!', 28153),
(140329, 'esMX', '', '¡Ya eh\'tás $upurificado:purificada;!', 28153),
(140328, 'esMX', '', 'La muerte te sienta mucho mejor.', 28153),
(140327, 'esMX', '', 'Hay que... purificar... los charco\'.', 28153),
(140326, 'esMX', '', 'Aquí solo se entierra a los dignos. ¡Sus cuerpo\' alimentarán a los raptores!', 28153),
(140325, 'esMX', '', 'Nunca debieron venir aquí.', 28153),
(140324, 'esMX', '', 'Vinieron en busca de oro, ¡pero ahora pagarán con sus hueso\'!', 28153),
(140323, 'esMX', '', '¡Los sirviente\' de Yazma no son bienvenido\' aquí!', 28153),
(140322, 'esMX', 'Da la cara. Me encargaré de ti yo solo.', '', 28153),
(140321, 'esMX', 'Talanji nos envió para investigar los rumore\' de que hay monstruos en el pantano. Encontramo\' algo mucho peor... ¡Los están creando!', '', 28153),
(140320, 'esMX', '¡Creí que habías muerto! ¡No me digas que realmente estás trabajando para esos lamebotas!', '', 28153),
(140319, 'esMX', 'Es... una larga historia. ¿Qué tal un trago?', '', 28153),
(140318, 'esMX', 'Malditos ladrones mareaférrea, les dije que... Un momento... ¡¿Flynn?!', '', 28153),
(140317, 'esMX', 'Ejem... ¡ATRÁS, percebe hinchado! ¡Entréganos tu botín!', '', 28153),
(140316, 'esMX', '', '¿Qué? ¡No! Qué esss esssto... Poder...', 28153),
(140315, 'esMX', 'Te doy la bienvenida a la pandilla Colmilloáureo, $p. ¡Ahora somos familia!', '', 28153),
(140314, 'esMX', '', '¿Alguna vez golpeaste a un sethrak tan fuerte que se le cayó la cola?', 28153),
(140313, 'esMX', 'Tú tiene\' la fuerza, yo la inteligencia.\n\nSomos un buen equipo.', '', 28153),
(140312, 'esMX', '', 'No te preocupes, repararé el tambor de inmediato.', 28153),
(140311, 'esMX', '', '...¡como la bandada auguró!', 28153),
(140310, 'esMX', '', '...quedo yo con mis juguetes...', 28153),
(140309, 'esMX', '', 'El ruido ya no se siente...', 28153),
(140308, 'esMX', '', 'El pueblo huyó o se paralizó.', 28153),
(140307, 'esMX', 'Recolectando', 'Recolectando', 28153),
(140306, 'esMX', '', 'Azshara... te he fallado...', 28153),
(140305, 'esMX', '', 'Mi reina estará encantada con tu muerte. ¡Nazjatar se alzará!', 28153),
(140303, 'esMX', '¡Bebe un trago conmigo, Flynn! ¡La casa invita!$B$B¿Qué quieres?', '', 28153),
(140302, 'esMX', 'Leche... en una taza de calavera.', 'Leche... en una taza de calavera.', 28153),
(140301, 'esMX', 'Leche.', 'Leche.', 28153),
(140300, 'esMX', 'Cerveza.', 'Cerveza.', 28153),
(140299, 'esMX', '|TInterface\\Icons\\INV_AMMO_BULLET_03:20|t¡%s te marca con una bala de |cFFFF0000|Hspell:256044|h[Mortojo]|h|r!', '', 28153),
(140298, 'esMX', 'Ten cuidado. Algo grande está por suceder.', '', 28153),
(140297, 'esMX', 'Siempre serás $Ubienvenido:bienvenida;, $p. Ere\' miembro vitalicio de la pandilla Colmilloáureo.', '', 28153),
(140296, 'esMX', '¡Inauguramos oficialmente la posada Colmilloáureo!', '', 28153),
(140295, 'esMX', 'Gracias por salvarme...', '', 28153),
(140294, 'esMX', 'Creo que me voy a quedar aquí un rato. Ayudaré en lo que pueda.', '', 28153),
(140293, 'esMX', 'No puedo creer que he vuelto a encontrarte, $p. Pero estoy agotado...', '', 28153),
(140292, 'esMX', 'Diría que estás demente, pero acabas de salvarme la vida. Así que... gracias.', '', 28153),
(140291, 'esMX', '¿Tú ayudaste a eh\'tos exiliados a construir una posada aquí en el medio de la nada?', '', 28153),
(140290, 'esMX', 'Los infiele\' me persiguieron por todo el desierto, eh\'quivando bestias y monstruos. Sobreviví por poco.', '', 28153),
(140289, 'esMX', 'Los trols de sangre eh\'tán locos, ¡usan a nuestro pueblo como alimento para los murciélagos!', 'Los trols de sangre eh\'tán locos, ¡usan a nuestro pueblo como alimento para los murciélagos!', 28153),
(140288, 'esMX', '¡Estas cosa\' querían dar mi sangre a los murciélago\'!', '¡Estas cosa\' querían dar mi sangre a los murciélago\'!', 28153),
(140287, 'esMX', '¡Gracias! ¡Me querían sacrificar a los murciélago\'!', '¡Gracias! ¡Me querían sacrificar a los murciélago\'!', 28153),
(140286, 'esMX', '¡Me iban a arrojar a los murciélago\'!', '¡Me iban a arrojar a los murciélago\'!', 28153),
(140285, 'esMX', 'La reina Azshara parece estar desesperada. Al menos podemos estar seguros de que le arruinaremos el día.$B$BEso ya me entusiasma.', '', 28153),
(140283, 'esMX', '¡Tu disfraz ha desaparecido! ¿Pero por qué el mío aún funciona? Mmm... Eh\'to cambia todo.', '', 28153),
(140282, 'esMX', '¡$n! ¿Qué haces?', '', 28153),
(140281, 'esMX', 'Argh, me siento mareado... Bwonsamdi me estaba invocando.', '', 28153),
(140280, 'esMX', '', 'Sé lo que estás pensando: \"¿Los trol zandalari no habían esclavizado a los goblin para obligarlos a excavar minas?\".$b$bMira, si nosotros no nos encargamos de nuestros enemigos, con el tiempo ellos mismos lo resolverán entre sí. Y eso es malo para el negocio.', 28153),
(140279, 'esMX', '', 'No hace falta que me des las gracias.', 28153),
(140278, 'esMX', 'No hace falta que me des las gracias.', '', 28153),
(140277, 'esMX', 'De nada.', '', 28153),
(140276, 'esMX', '', 'De nada.', 28153),
(140275, 'esMX', 'Es un honor servirte.', '', 28153),
(140274, 'esMX', '', 'Es un honor servirte.', 28153),
(140273, 'esMX', '', 'No te preocupes.', 28153),
(140272, 'esMX', 'No te preocupes.', '', 28153),
(140271, 'esMX', '', 'Fue un placer.', 28153),
(140270, 'esMX', 'Fue un placer.', '', 28153),
(140269, 'esMX', 'El placer fue mío.', '', 28153),
(140268, 'esMX', '', 'El placer fue mío.', 28153),
(140267, 'esMX', '', 'Sin dudas.', 28153),
(140266, 'esMX', 'Sin dudas.', '', 28153),
(140265, 'esMX', 'Correcto.', '', 28153),
(140264, 'esMX', 'Mi primer trago en Vol\'Dun. ¡He eh\'tado perdido en las dunas desde que nos atacaron!', '', 28153),
(140263, 'esMX', '', 'Correcto.', 28153),
(140262, 'esMX', '¿Qué haces aquí, $p? ¡Pensé que habías muerto!', '', 28153),
(140261, 'esMX', 'Afirmativo.', '', 28153),
(140260, 'esMX', '', 'Afirmativo.', 28153),
(140259, 'esMX', '', 'Sin dudarlo.', 28153),
(140258, 'esMX', 'Sin dudarlo.', '', 28153),
(140257, 'esMX', 'Espera aquí.', '', 28153),
(140256, 'esMX', '', 'Espera aquí.', 28153),
(140255, 'esMX', '', 'Mantén esta posición.', 28153),
(140254, 'esMX', 'Mantén esta posición.', '', 28153),
(140253, 'esMX', 'Quédate en este lugar.', '', 28153),
(140252, 'esMX', '', 'Quédate en este lugar.', 28153),
(140251, 'esMX', '', 'Quédate aquí.', 28153),
(140250, 'esMX', 'Quédate aquí.', '', 28153),
(140249, 'esMX', 'Admiro tu generosidad.', '', 28153),
(140248, 'esMX', '', 'Admiro tu generosidad.', 28153),
(140247, 'esMX', '', 'Si piensas que mis puños son rápidos, espera a ver a mi hermana Noxie. ¡Si te da un golpe, te dejará viendo estrellas de por vida!', 28153),
(140246, 'esMX', '', 'Estoy en deuda contigo.', 28153),
(140245, 'esMX', 'Estoy en deuda contigo.', '', 28153),
(140244, 'esMX', 'Gracias, adalid.', '', 28153),
(140243, 'esMX', '', 'Gracias, adalid.', 28153),
(140242, 'esMX', '', 'Te lo agradezco.', 28153),
(140241, 'esMX', 'Te lo agradezco.', '', 28153),
(140240, 'esMX', '', 'La Luz te lo agradece.', 28153),
(140239, 'esMX', 'La Luz te lo agradece.', '', 28153),
(140238, 'esMX', 'Te doy las gracias.', '', 28153),
(140237, 'esMX', '', 'Te doy las gracias.', 28153),
(140236, 'esMX', '', 'Necesito maná.', 28153),
(140235, 'esMX', 'Necesito maná.', '', 28153),
(140234, 'esMX', 'Necesito más maná.', '', 28153),
(140233, 'esMX', '', 'Necesito maná.', 28153),
(140232, 'esMX', '', 'Me falta maná.', 28153),
(140231, 'esMX', 'Me falta maná.', '', 28153),
(140230, 'esMX', 'Me queda poco maná.', '', 28153),
(140229, 'esMX', '', 'Tengo que obtener maná.', 28153),
(140228, 'esMX', '', 'Moxie te verá cuando $gestés listo, amigo:estés lista, amiga;.$b$bNo te preocupes por mí; yo soy la fuerte. Y ni sueñes con tocarle un pelo; te tengo entre ceja y ceja.', 28153),
(140227, 'esMX', '', '¡Bombardeen al enemigo!', 28153),
(140226, 'esMX', '¡Bombardeen al enemigo!', '', 28153),
(140225, 'esMX', '¡Comiencen con el bombardeo!', '', 28153),
(140224, 'esMX', '', '¡Comiencen con el bombardeo!', 28153),
(140223, 'esMX', '', 'Si piensas que yo soy peligrosa, deberías ver a mi hermana Boxie. Pica como un silítido, pero vuela como un dragón nimbo. ¡Pim! ¡Pum! ¡Pam!', 28153),
(140222, 'esMX', '', 'Si quieres hablar, habla con Moxie. Ella es la que se encarga de las negociaciones.$b$b<Noxie levanta su maza y la deja caer sobre la otra mano.>$b$bSi haces algo estúpido, yo me encargaré de que te arrepientas. Dudo que quieras hablar conmigo.', 28153),
(140221, 'esMX', '¡Liberen la furia!', '', 28153),
(140220, 'esMX', '', '¡Liberen la furia!', 28153),
(140219, 'esMX', '', '¡Disparen todas las armas!', 28153),
(140218, 'esMX', '', 'Puedes hablar con el jefe, pero te estaré prestando mucha atención.', 28153),
(140217, 'esMX', '', 'En el puerto no se permite realizar ningún negocio extraño. Mírame bien; no estoy sonriendo, ¿verdad?', 28153),
(140216, 'esMX', '', '¡Abran fuego!', 28153),
(140215, 'esMX', '', 'De acuerdo.', 28153),
(140214, 'esMX', 'De acuerdo.', '', 28153),
(140213, 'esMX', 'Si tienes que hablar con el jefe, habla con el jefe.$b$¿Tienes que hablar conmigo? No. Entonces, vete de aquí, canalla.', '', 28153),
(140212, 'esMX', 'Sin dudas.', '', 28153),
(140211, 'esMX', '', 'Sin dudas.', 28153),
(140210, 'esMX', '¿$p...?', '', 28153),
(140209, 'esMX', 'Que así sea.', '', 28153),
(140208, 'esMX', '', 'Que así sea.', 28153),
(140207, 'esMX', '', 'Sí, veo a Gazrix y a los suyos allí, planeando y elucubrando. Tanto pensar no les servirá de nada. Cuando consigamos una audiencia con el rey, el primer tema que trataremos será el de la eliminación de la competencia.$b$bOferta y demanda, ¿no es cierto? Si nosotros tenemos toda la oferta, ¡podemos demandar lo que más nos guste!', 28153),
(140206, 'esMX', '', 'Correcto.', 28153),
(140205, 'esMX', 'Correcto.', '', 28153),
(140204, 'esMX', 'Correcto.', '', 28153),
(140203, 'esMX', '', 'Correcto.', 28153),
(140202, 'esMX', '', 'Denegado.', 28153),
(140201, 'esMX', 'Denegado.', '', 28153),
(140200, 'esMX', 'Por favor, estoy herido... ¡Ten piedad de este hermano zandalari!', '', 28153),
(140199, 'esMX', 'Inaceptable.', '', 28153),
(140198, 'esMX', '', 'Inaceptable.', 28153),
(140197, 'esMX', '¿Hola? ¿Hay alguien ahí?', '', 28153),
(140196, 'esMX', '', 'Creo que no.', 28153),
(140195, 'esMX', 'Creo que no.', '', 28153),
(140194, 'esMX', '¡Jamás!', '', 28153),
(140193, 'esMX', '', 'Por supuesto que no.', 28153),
(140192, 'esMX', 'No.', '', 28153),
(140191, 'esMX', '', 'No.', 28153),
(140190, 'esMX', '', 'No.', 28153),
(140189, 'esMX', 'No.', '', 28153),
(140188, 'esMX', 'Prepárense. Tenemo\' la primera visita del día. ¡Qué emocionante! ¡No $Ulo:la; maten!', '', 28153),
(140187, 'esMX', '', 'Representamos los intereseh\' de la organización del Pantoque. Nada nos detendrá; ni siquiera el hecho de eh\'tar varados en este puerto con esos principiantes Bonvapor.$b$bNueh\'tros negociantes se están manejando con mucha pericia. Pronto estaré charlando con el rey, que cambiará de parecer y se dará cuenta de que una relación comercial podría beneficiar a ambas partes.', 28153),
(140186, 'esMX', '', 'La organización del Pantoque emplea a algunos de los mejores negociadores del momento. No hay nada que no puedan comprar o venderte. Sin dudas generamos mucha inspiración.$b$bCuando los demás miembros de la organización no pueden hacer el trabajo, me envían a mí. Mis chicas y yo nos encargaremos de todo. Observa.', 28153),
(140185, 'esMX', '¿El Pantoque? Sí, los veo. Allí, creyéndose los reye\' del universo porque enviaron a Moxie y a sus chicas a que \"nos mantengan vigilados\". Como si tuviéramo\' algo que ocultar, ¿no es cierto?$b$bYo no me preocuparía por ello\'. He tratado con muchos príncipes mercantes; esto será pan comido.', '', 28153),
(140184, 'esMX', 'Es bueno verte por aquí. ¿Cree\' que podrías enviarle un mensaje al rey? Estoy seguro de que le encantará oír sobre los negocio\' que podríamos hacer en esta gran ciudad.', '', 28153),
(140183, 'esMX', '¡El enemigo se acerca!', '', 28153),
(140182, 'esMX', '', 'El peligro está cerca.', 28153),
(140181, 'esMX', 'Te garantizo que estamo\' aquí para llevar a cabo alguno\' negocios con lo\' Bonvapor.$b$bEl jefe sabe que el Imperio zandalari es gigante, y donde hay imperios gigantes, hay oportunidades del mismo tamaño, ¿no crees?$b$bNo nos dejarán entrar a la ciudad por la\' buenas, pero tengo el presentimiento de que eso pronto cambiará.', '', 28153),
(140180, 'esMX', '', '¡El peligro se aproxima!', 28153),
(140179, 'esMX', '¡El peligro se aproxima!', '', 28153),
(140178, 'esMX', '¡Ayuda, por favor!', '', 28153),
(140177, 'esMX', '', '¡Ayuda, por favor!', 28153),
(140176, 'esMX', '¡Necesito ayuda!', '', 28153),
(140175, 'esMX', '', '¡Necesito ayuda!', 28153),
(140174, 'esMX', '', '¡Ayúdame!', 28153),
(140173, 'esMX', '¡Ayúdame!', '', 28153),
(140172, 'esMX', '¡Ayúdenme!', '', 28153),
(140171, 'esMX', '', '¡Ayúdenme!', 28153),
(140170, 'esMX', 'Suramar se alza orgullosa... y libre.', '', 28153),
(140169, 'esMX', '', 'Suramar se alza orgullosa... y libre.', 28153),
(140168, 'esMX', '', 'Luchamos contra la oscuridad.', 28153),
(140167, 'esMX', 'Luchamos contra la oscuridad.', '', 28153),
(140166, 'esMX', 'Hola.', '', 28153),
(140165, 'esMX', '', 'Hola.', 28153),
(140163, 'esMX', '¡Con esto impresionaremos a todos los huéspedes que lleguen!', '', 28153),
(140161, 'esMX', 'Sígueme, sé exactamente dónde colocar ese... colmillo para que todo\' lo vean.', '', 28153),
(140160, 'esMX', 'DO NOT TRANSLATE', '', 28153),
(140159, 'esMX', '¡Grozztok, encárgate de eh\'tos intrusos! No vuelvas a fallarme.', '', 28153),
(140158, 'esMX', '¡Silencio! No eh\'tamos solos...', '', 28153),
(140157, 'esMX', 'No podemo\' pasar. La puerta eh\'tá sellada con magia que jamás hemo\' visto.', '', 28153),
(140156, 'esMX', 'Cometiste un error cuando decidih\'te venir a las dunas. La princesa no puede salvarte aquí.', '', 28153),
(140155, 'esMX', 'Acheon kor.', '', 28153),
(140154, 'esMX', '', 'Acheon kor.', 28153),
(140153, 'esMX', '', 'Archenon poros.', 28153),
(140152, 'esMX', 'Archenon poros.', '', 28153),
(140151, 'esMX', '', 'Tenu\'balah.', 28153),
(140150, 'esMX', 'Tenu\'balah.', '', 28153),
(140149, 'esMX', 'Saludos.', '', 28153),
(140148, 'esMX', '', 'Saludos.', 28153),
(140147, 'esMX', 'Saludos.', '', 28153),
(140146, 'esMX', '', 'Saludos.', 28153),
(140145, 'esMX', '', '¡Necesito recuperar mi salud!', 28153),
(140144, 'esMX', '¡Necesito recuperar mi salud!', '', 28153),
(140143, 'esMX', '', '¡Necesito que me sanen!', 28153),
(140142, 'esMX', '¡Necesito que me sanen!', '', 28153),
(140141, 'esMX', '¡Sáname!', '', 28153),
(140140, 'esMX', '', '¡Sáname!', 28153),
(140139, 'esMX', '¡Sáname!', '', 28153),
(140138, 'esMX', '', '¡Sáname!', 28153),
(140137, 'esMX', '', 'Adiós.', 28153),
(140136, 'esMX', 'Adiós.', '', 28153),
(140135, 'esMX', '', 'Busca la paz, pero prepárate para la guerra.', 28153),
(140134, 'esMX', 'Busca la paz, pero prepárate para la guerra.', '', 28153),
(140133, 'esMX', 'Sirve con valor y humildad.', '', 28153),
(140132, 'esMX', '', 'Sirve con valor y humildad.', 28153),
(140131, 'esMX', 'Dejaremos nuestra marca en este mundo.', '', 28153),
(140130, 'esMX', '', 'Dejaremos nuestra marca en este mundo.', 28153),
(140129, 'esMX', 'Que el obsequio del arcan\'dor te mantenga en pie.', '', 28153),
(140128, 'esMX', '', 'Que el obsequio del arcan\'dor te mantenga en pie.', 28153),
(140127, 'esMX', '', 'Suramar recuerda a sus campeones.', 28153),
(140126, 'esMX', 'Suramar recuerda a sus campeones.', '', 28153),
(140125, 'esMX', '', 'Que siempre te acompañe la Luz.', 28153),
(140124, 'esMX', 'Que siempre te acompañe la Luz.', '', 28153),
(140123, 'esMX', 'Adiós.', '', 28153),
(140122, 'esMX', '', 'Adiós.', 28153),
(140121, 'esMX', 'Iremos por aquí.', '', 28153),
(140120, 'esMX', 'Tú vienes conmigo.', '', 28153),
(140119, 'esMX', '', 'Ven.', 28153),
(140118, 'esMX', '', 'Ven.', 28153),
(140117, 'esMX', '', 'Sígueme.', 28153),
(140116, 'esMX', '', 'Yo tomaré la posta.', 28153),
(140115, 'esMX', 'Sígueme.', '', 28153),
(140114, 'esMX', 'Déjame guiarte.', '', 28153),
(140113, 'esMX', '', 'Por aquí.', 28153),
(140112, 'esMX', '', 'Por aquí.', 28153),
(140111, 'esMX', 'Sígueme.', '', 28153),
(140110, 'esMX', 'Sígueme.', '', 28153),
(140109, 'esMX', 'Que esto quede entre nosotros, ¿eh, $p? Un secreto Colmilloáureo.', '', 28153),
(140108, 'esMX', '¡Mmm, esta fruta se ve deliciosa! Llevémosla a la mesa del bufé.', '', 28153),
(140107, 'esMX', '¡Mientras nos buscas unas frutas, prepararé el desayuno: brochetas de escórpidos!', '', 28153),
(140106, 'esMX', '¡Las escamas de $n están imbuidas con electricidad estática!', '¡Las escamas de $n están imbuidas con electricidad estática!', 28153),
(140105, 'esMX', '', 'Si lo deseas, el primer vuelo es gratis, $p. Si necesitas volar a algún lado, solo pídemelo.', 28153),
(140104, 'esMX', '', 'Cuidado con los sauroliscos que rondan por la cresta de arriba... les gusta abalanzarse.', 28153),
(140103, 'esMX', '¡Huye!', '', 28153),
(140102, 'esMX', '', '¡Huye!', 28153),
(140101, 'esMX', '¡Huye!', '', 28153),
(140100, 'esMX', '', '¡Salgamos de aquí!', 28153),
(140099, 'esMX', '', '¡Cúbrete!', 28153),
(140098, 'esMX', '¡Cúbrete!', '', 28153),
(140097, 'esMX', '', '¡Cúbrete!', 28153),
(140096, 'esMX', '¡Cúbrete!', '', 28153),
(140095, 'esMX', '¡Retirada!', '', 28153),
(140094, 'esMX', '', '¡Retirada!', 28153),
(140093, 'esMX', '¡Retirada!', '', 28153),
(140092, 'esMX', '', '¡Retirada!', 28153),
(140091, 'esMX', 'Que lo\' loa guien tus paso\'. ¡Debe\' advertir al rey antes de que sea demasiado tarde!', '', 28153),
(140090, 'esMX', 'Nos encontraremo\' en la nave de guerra de Kao cuando el camino esté despejado. Que los espíritu\' te acompañen.', '', 28153),
(140089, 'esMX', 'Sí', '', 28153),
(140088, 'esMX', '', 'Sí', 28153),
(140087, 'esMX', 'Sí', '', 28153),
(140086, 'esMX', '', 'Sí', 28153),
(140085, 'esMX', 'Encontrarás a nuestros guerrero\' en el bancal superior. ¡Por Zuldazar!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140080, 'esMX', '<Ruidos de tren. ¡Chucu chucu chu chu!>', '', 28153),
(140079, 'esMX', '', '<Ruidos de tren. ¡Chucu chucu chu chu!>', 28153),
(140078, 'esMX', '<Ruidos de tren. ¡Chucu chucu chu chu!>', '', 28153),
(140077, 'esMX', '', '<Ruidos de tren. ¡Chucu chucu chu chu!>', 28153),
