(140073, 'esMX', '<Sonido de suspiro>', '', 28153),
(140072, 'esMX', '<Sonido de trompetilla. ¡Pfffthblth!>', '', 28153),
(140071, 'esMX', '', '<Sonido de trompetilla. ¡Pfffthblth!>', 28153),
(140070, 'esMX', '<Sonido de trompetilla. ¡Pfffthblth!>', '', 28153),
(140069, 'esMX', '', '<Sonido de trompetilla. ¡Pfffthblth!>', 28153),
(140068, 'esMX', '', '<Risas>', 28153),
(140067, 'esMX', '<Risas>', '', 28153),
(140066, 'esMX', '', '<Risas>', 28153),
(140065, 'esMX', '<Risas>', '', 28153),
(140064, 'esMX', '<Sonidos de risa>', '', 28153),
(140063, 'esMX', '', '<Sonidos de risa>', 28153),
(140062, 'esMX', '<Sonidos de risa>', '', 28153),
(140061, 'esMX', '', '<Sonidos de risa>', 28153),
(140060, 'esMX', '', '<Sonido de beso>', 28153),
(140059, 'esMX', '<Sonido de beso>', '', 28153),
(140058, 'esMX', '', '<Sonido de beso>', 28153),
(140057, 'esMX', '<Sonido de beso>', '', 28153),
(140056, 'esMX', 'No le temeremos a la oscuridad.', '', 28153),
(140055, 'esMX', 'Te damos la bienvenida.', '', 28153),
(140054, 'esMX', 'Te ofrezco mis saludos.', '', 28153),
(140053, 'esMX', 'Hola.', '', 28153),
(140052, 'esMX', '¡Alguien tiene que curar mis heridas!', '', 28153),
(140051, 'esMX', '¡Sáname!', '', 28153),
(140050, 'esMX', 'Que la montaña te dé sombra y cobijo.', '', 28153),
(140049, 'esMX', 'Que tu aventura te ilumine.', '', 28153),
(140048, 'esMX', 'La Madre Tierra guiará tu camino.', '', 28153),
(140047, 'esMX', 'Adiós.', '', 28153),
(140046, 'esMX', '¡Por la Horda!', '', 28153),
(140045, 'esMX', '', '¡Por la Horda!', 28153),
(140044, 'esMX', '¡Por la Alianza!', '', 28153),
(140043, 'esMX', '', '¡Por la Alianza!', 28153),
(140042, 'esMX', '¡Por la Horda!', '', 28153),
(140041, 'esMX', '', 'Ven.', 28153),
(140040, 'esMX', '¡Ayúdenme!', '', 28153),
(140039, 'esMX', '¡Necesito ayuda!', '', 28153),
(140038, 'esMX', '¡Una amenaza se aproxima!', '', 28153),
(140037, 'esMX', '<Sonido de beso>', '', 28153),
(140036, 'esMX', '<Sonidos de risa>', '', 28153),
(140035, 'esMX', '<Risas>', '', 28153),
(140034, 'esMX', 'Inadmisible.', '', 28153),
(140033, 'esMX', 'Creo que no.', '', 28153),
(140032, 'esMX', 'No.', '', 28153),
(140031, 'esMX', 'Muy bien... ¡Jo\'chunga! Necesito que vaya\' a esa choza de allí para preparar un ritual de sangre.', 'Muy bien... ¡Jo\'chunga! Necesito que vaya\' a esa choza de allí para preparar un ritual de sangre.', 28153),
(140030, 'esMX', 'Rápido. ¡Se no\' acaba el tiempo!', '', 28153),
(140029, 'esMX', 'Ciertamente.', '', 28153),
(140028, 'esMX', 'Exacto.', '', 28153),
(140027, 'esMX', '¡Shh! Mira, debemos eh\'cabullirnos. En los trols de sangre, lah\' mujeres son las líderes.$B$BOrdéname que entre a esa choza... Di que tengo que preparar un ritual de sangre.$B$B¡A nadie le extrañará que me des órdenes!', '', 28153),
(140026, 'esMX', 'Correcto.', '', 28153),
(140025, 'esMX', '¡Abran fuego!', '', 28153),
(140024, 'esMX', '¡Bombardéenlos!', '', 28153),
(140023, 'esMX', 'Me falta maná.', '', 28153),
(140022, 'esMX', 'Necesito maná.', '', 28153),
(140021, 'esMX', '<Sonido de trompetilla. ¡Pfffthblth!>', '', 28153),
(140020, 'esMX', '<Sonido de suspiro>', '', 28153),
(140019, 'esMX', 'Desde luego.', '', 28153),
(140018, 'esMX', 'Un placer.', '', 28153),
(140017, 'esMX', 'De nada.', '', 28153),
(140016, 'esMX', 'Mil gracias.', '', 28153),
(140015, 'esMX', 'No sé cómo agradecértelo.', '', 28153),
(140014, 'esMX', 'Tienes mi gratitud.', '', 28153),
(140013, 'esMX', '<Ruidos de tren. ¡Chucu chucu chu chu!>', '', 28153),
(140012, 'esMX', 'Mantén la posición.', '', 28153),
(140011, 'esMX', 'No te vayas.', '', 28153),
(140010, 'esMX', 'Así es.', '', 28153),
(140009, 'esMX', 'Correcto.', '', 28153),
(140008, 'esMX', 'Sí.', '', 28153),
(140004, 'esMX', 'Te envidio... ere\' testigo\' del nacimiento de un nuevo imperio trol. Es una pena que Rastakhan no pueda experimentar el mismo placer.', '', 28153),
(140003, 'esMX', 'Lo\' mogu hicieron su parte... alejaron a lo\' guardaespaldas del rey de su lado...', '', 28153),
(140002, 'esMX', 'La profecía está sobre nosotro\'. Eh\'to no es más que una distracción mientras Zul hace su jugada.', '', 28153),
(140001, 'esMX', '¡Vilnak\'dor! ¡Será mejor que Kao esté mintiendo o tú será\' el siguiente!', '', 28153),
(140000, 'esMX', '', '¿El rey?', 28153),
(139999, 'esMX', 'No importa... El fin de tu rey... se acerca...', '', 28153),
(139998, 'esMX', '¡Sabía que esa sabandija no era digna de confianza! ¡Pagará por eh\'to!', '', 28153),
(139997, 'esMX', 'Zul nos prometió un imperio nuevo, ¡y eso es lo que TENDREMOS!', '', 28153),
(139996, 'esMX', 'Observa a tu alrededor, Kao. ¡Ya ha\' perdido! ¡Suelta las arma\'!', '', 28153),
(139995, 'esMX', 'Soy la fuerza del trueno. El terror de las estepas. ¡No puedo perder!', '', 28153),
(139994, 'esMX', '', '¡Somos zandalari! ¡Jamás nos rendiremo\'!', 28153),
(139993, 'esMX', 'Zuldazar es nuestro derecho de nacimiento. Si te rindes, te mataré de la forma más piadosa.', '', 28153),
(139992, 'esMX', 'Hmm. Esperaba un desafío mayor.', '', 28153),
(139991, 'esMX', '¡Taz\'dingo! ¡Por el rey Rastakhan!', '', 28153),
(139990, 'esMX', '', 'Habutu, debes contarle al rey Rastakhan sobre la traición de Zul. $p y yo nos encargaremo\' de este bruto.', 28153),
(139989, 'esMX', 'La llegada de la flota zandalari', 'La llegada de la flota zandalari', 28153),
(139988, 'esMX', 'Déjame ver qué sombreros tienes.', 'Déjame ver qué sombreros tienes.', 28153),
(139987, 'esMX', '¿Regresaste?\n\nDigo...¡regresaste!\n\nAntes de que tus paso\' me asustaran, eh\'taba limpiando la posada con Zulsan, tal como dije.. ¿Se nota?', '', 28153),
(139986, 'esMX', '¡A ver esas rocas!', '¡A ver esas rocas!', 28153),
(139985, 'esMX', 'Tengo buena idea: compras dos sombreros, usas un sombrero. El otro sombrero para un amigo, compañero o familiar. Yo no digo nada.', '', 28153),
(139984, 'esMX', 'Claro que vendo dos sombreros al mismo tiempo... ¡Tengo dos cabezas!$b$bTú tienes solo una cabeza. Lo lamento mucho. ¡Pero llévate un sombrero de más!', '', 28153),
(139983, 'esMX', '¿Quieres comprar sombreros? ¡Tengo sombreros! ¡Dos por el precio de dos!', '', 28153),
(139982, 'esMX', '¿Quieres ser grande y fuerte como Bol\'dar? Compra una de mis rocas, luego levántala y rompe cosas con ella todos los días. Así, tal vez te vuelvas grande y fuerte.$b$bAunque quizás no tan grande y fuerte como yo.', '', 28153),
(139981, 'esMX', '¡Compren las rocas de Bol\'dar! ¡Tengo las más mejores, y a buen precio!', '', 28153),
(139980, 'esMX', '¡Ey, tú! ¿Quiereh\' comprar una roca? Tengo las mejores rocas.', '', 28153),
(139979, 'esMX', 'El Corazón de Sethraliss está rojo brillante. ¿Qué significa?', 'El Corazón de Sethraliss está rojo brillante. ¿Qué significa?', 28153),
(139978, 'esMX', 'No debemos flaquear.', 'No debemos flaquear.', 28153),
(139977, 'esMX', 'Es fácil reconocer el Paso del Muerto. Solo tiene\' que buscar las oscuras e imponentes formacione\' rocosas al noroeste. ¡Será divertido!', '', 28153),
(139976, 'esMX', 'Una veh\' que te acerques a su campamento, te transformarás en una de ellas. ¡Pero ten cuidado! El disfrah\' no es infalible.', '', 28153),
(139975, 'esMX', 'Las trols de sangre eh\'tán a cargo de los grupos de guerra, así que tendráh\' que lucir como una de ellas. ¡Confía en mí, eh\'to funcionará!', '', 28153),
(139974, 'esMX', 'Te advierto que eh\'to puede doler un poco. Bueno... ¡quizás mucho!', '', 28153),
(139727, 'esMX', 'Estoy listo para comenzar el ritual para disfrazarme como una trol de sangre.', 'Estoy lista para comenzar el ritual para disfrazarme como una trol de sangre.', 28153),
(139726, 'esMX', 'Hay un vudú muy malo por eh\'te lugar...', '', 28153),
(139592, 'esMX', 'Si me necesita\', estaré en algún lugar lejo\' de Izarn.', '', 28153),
(139567, 'esMX', 'Veo que hiciste amigo\' mientra\' no estaba.', '', 28153),
(139482, 'esMX', '', '¡Defiendan este cruce! Tenemo\' que impedir que lo\' mogu sigan avanzando.', 28153),
(139443, 'esMX', 'Tu amigo es libre de irse, pero yo no le quitaría los ojos de encima.', '', 28153),
(139410, 'esMX', 'Enseguida.', '', 28153),
(139408, 'esMX', 'Hay disturbios en la ciudad. ¡Debemo\' mantenerlo a salvo!', '', 28153),
(139406, 'esMX', 'Mi rey, no podemos abandonarlo.', '', 28153),
(139401, 'esMX', 'Tuviste tu oportunidad. Los zandalari nunca temerán a tus mah\'cotas mientra\' yo sea el rey.', '', 28153),
(139397, 'esMX', 'Mis soldado\' registrarán toda la ciudad por si quedan má\'.', '', 28153),
(139391, 'esMX', 'Te debo la vida, $p. Vamos al templo. Este lugar no es seguro.', '', 28153),
(139390, 'esMX', '', '¡Ey! ¿Vas a hablar o vas a ayudar? ¡Sigamos con esta cacería en el agua!', 28153),
(139389, 'esMX', '¡Hermano Therold! ¡Lord Canto Tormenta! ¡Llegaron en el momento más oportuno! ¡Necesitamos su ayuda!', '', 28153),
(139388, 'esMX', 'Vuelve a encontrarte conmigo y los demás cuando tengas mis cosas. Debemo\' prepararnos.', '', 28153),
(139387, 'esMX', '¡Oye, tú! Ven, antes de que los bruto\' vuelvan a rematarme.', '', 28153),
(139386, 'esMX', 'Podrán apoderarse de nuestra tierra, pero jamás se llevarán nueh\'tras almas eterna\'.', '', 28153),
(139385, 'esMX', 'Gracias. Ya puedo seguir por mi cuenta desde aquí.', 'Gracias. Ya puedo seguir por mi cuenta desde aquí.', 28153),
(139384, 'esMX', '¡Por aquí! Protegeremo\' las preseas de Kaza\'jin con nueh\'tras vidas.', '¡Por aquí! Protegeremo\' las preseas de Kaza\'jin con nuestras vidas.', 28153),
(139383, 'esMX', '', '¡Prepárense, Firmemares! ¡Estas criaturas no se parecen a nada que hayamos enfrentado antes!', 28153),
(139375, 'esMX', 'Cuidado dónde pisas. Los ranishu comen todo lo que encuentren... y no eh\'toy hablando metafóricamente.', '', 28153),
(139374, 'esMX', '', 'Si tú también buscas a Taji, debe estar en lo alto de la colina del sur.', 28153),
(139372, 'esMX', 'Reúnete conmigo detráh\' de la caravana cuando termines tu trabajo aquí. Empezaré con las reparaciones.', '', 28153),
(139371, 'esMX', 'Felicitaciones, $p. Sobreviviste a un encuentro con los ranishu. Poco\'  tienen esa suerte.', '', 28153),
(139370, 'esMX', 'Fuerte y resistente... Eh\'ta madera es ideal para reparar nuestra caravana.', '', 28153),
(139369, 'esMX', 'Las reparacione\' de la caravana van muy bien, todo graciah\' a la madera que nos ayudaste a conseguir.', '', 28153),
(139368, 'esMX', '', 'Bueno... Mmm... ¡Aquí está! Pergamino de invisibilidad... Tiene que ser este.', 28153),
(139367, 'esMX', '', '¡Concéntrense! ¡No es hora de contar historia\'!', 28153),
(139366, 'esMX', '¿Nunca te conté esa historia? Ah, ¡fue sorprendente! Por dónde empiezo...', '', 28153),
(139365, 'esMX', '', 'Oh, cielos... parece que este está escrito en el idioma de los dioses antiguos. ¿Dónde lo encontraste?', 28153),
(139364, 'esMX', '¡No! ¿Te molestaste en leerlo siquiera? Pero, eh, déjalo a mano. Lo necesitaremos cuando terminemos con esto.', '', 28153),
(139363, 'esMX', '', 'Veamos... ¿Pergamino del regreso eterno te parece bien?', 28153),
(139362, 'esMX', 'Por favor, ¿puedes ayudarme a regresar con Alby? Debe estar muy preocupado.', '', 28153),
(139361, 'esMX', 'Cuando hayas salvado al resto, ¡ven a verme a la parte este y nos enfrentaremos a la ama de las mareas!', '', 28153),
(139360, 'esMX', '', 'Bah, ¡esto podría llevar todo el día! Princesa, no te imaginas cuántos pergaminos tiene este anciano.', 28153),
(139358, 'esMX', '¡Debemos unirnos a los demáh\'!', '¡Debemo\' unirno\' a los demás!', 28153),
(139357, 'esMX', '¡Protejan la flota!', '¡Protejan la flota!', 28153),
(139356, 'esMX', '¡El Puerto de Guerra no debe caer!', '¡El Puerto de Guerra no debe caer!', 28153),
(139355, 'esMX', '¡En nombre del rey Rastakhan!', '¡En nombre del rey Rastakhan!', 28153),
(139354, 'esMX', 'Sabía que lo tenía en algún lado. Esto nos mantendrá ocultos lo suficiente para infiltrarnos entre los trols de sangre. No te alejes de mí.', '', 28153),
(139353, 'esMX', 'En otras épocas me habría encargado sin problemas de estos gusanos. Me atacaron en medio de la oscuridad. ¡No pude hacer nada! En resumen, sus órdenes parecen ser: \"¡Rápido! ¡Azshara quiere su premio!\".', '', 28153),
(139351, 'esMX', 'Todo lo que sepa es útil, milord. Necesitamos toda la información que podamos reunir.', '', 28153),
(139350, 'esMX', 'Los nagas buscan algo aquí. Es para Azshara. Debemos detenerlos o desbaratar sus planes.', '', 28153),
(139348, 'esMX', 'Un... culto se ha apoderado de este poblado por culpa de mi incom... incompetencia.', '', 28153),
(139347, 'esMX', '¿Lo oyes? ¡Es el llamado de Bwonsamdi! ¡La eternidad eh\'tá cerca!', '¿Lo oyes? ¡Es el llamado de Bwonsamdi! ¡La eternidad eh\'tá cerca!', 28153),
(139346, 'esMX', '¡Milord! ¿Está a salvo? ¿Qué información tiene?', '', 28153),
(139345, 'esMX', '¡Brannon!', '', 28153),
(139344, 'esMX', 'La voz... nos llama... ¡tenemo\' que obedecer!', 'La voz... nos llama... ¡tenemo\' que obedecer!', 28153),
(139343, 'esMX', '¿Qué eh\'tá sucediendo? Me sentía mal... Estaba en la cama... ¿Dónde estoy ahora?', '¿Qué eh\'tá sucediendo? Me sentía mal... Estaba en la cama... ¿Dónde estoy ahora?', 28153),
(139341, 'esMX', 'Mi vida... por el emperador…', '', 28153),
(139339, 'esMX', 'Les fallé a mis súbditos. No me veían como un símbolo de autoridad, y por eso buscaron liderazgo en otras personas.', '', 28153),
(139338, 'esMX', 'Mi tío me puso a cargo de esta aldea para que diera mis primeros pasos en el arte del liderazgo. Pero... ¿un culto? ¡¿Cómo se lidia con un culto?!', '', 28153),
(139336, 'esMX', 'Mil batallas... Mil victorias…', '', 28153),
(139335, 'esMX', 'Es imposible... silenciar... al trueno…', '', 28153),
(139334, 'esMX', 'Gracias por salvarme, $gextraño:extraña;. Conway y sus hombres se apoderaron de la aldea tan rápido... No me lo esperaba.', '', 28153),
(139333, 'esMX', 'La tormenta... desaparece…', '', 28153),
(139329, 'esMX', 'Cumplimos la voluntad... de los dioses…', '', 28153),
(139328, 'esMX', 'Incluso la piedra... se rompe…', '', 28153),
(139327, 'esMX', 'La carne es... débil…', '', 28153),
(139326, 'esMX', 'El Imperio... nunca... caerá.', '', 28153),
(139317, 'esMX', '¡Serás $Uun buen esclavo:una buena esclava;!', '', 28153),
(139316, 'esMX', '¡Siente la furia de la tormenta!', '', 28153),
(139315, 'esMX', '¡Inclínate ante mí!', '', 28153),
(139314, 'esMX', '¡Soy la manifestación del poder!', '', 28153),
(139312, 'esMX', 'Los zandalari respetarán su pacto... ¡o morirán!', '', 28153),
(139311, 'esMX', '¡Te aplastaré el cráneo con mis propias manos!', '', 28153),
(139309, 'esMX', '¡Volveremos a alzar nuestro imperio con tus huesos!', '', 28153),
(139308, 'esMX', '¡Te arrodillarás!', '', 28153),
(139307, 'esMX', 'Brannon, no eres más que un niño tonto. Hice un trato, ¡y guiaré a esta aldea al progreso sin ti!', 'Brannon, no eres más que un niño tonto. Hice un trato, ¡y guiaré a esta aldea al progreso sin ti!', 28153),
(139306, 'esMX', 'Necesitamos recursos para detenerlos. ¡Dispérsense y tráiganme hierro y madera!', '', 28153),
(139305, 'esMX', '', '¿Qué sabesss de losss secretosss de la isssla? ¡Dime!', 28153),
(139304, 'esMX', '¡Siempre gobernaremos los maresss!', '', 28153),
(139303, 'esMX', '¡Te ahogaremos bajo las olas!', '', 28153),
(139298, 'esMX', '', 'Listo, iré a la caravana. ¡Nos vemos luego, $p!', 28153),
(139295, 'esMX', 'Sí, gracias por su ayuda hoy, Kona y $p. Estoy en deuda con ustedes.', '', 28153),
(139294, 'esMX', '', 'Habríamos luchado contigo hasta el final, Sumber.', 28153),
(139293, 'esMX', 'También me alegra escuchar que Thun\'ka el Marchitador ha escapado de su vinculación. Un elemental de tanto poder... sería un problema para nosotros.', '', 28153),
(139292, 'esMX', '¿Así que era un chamán el que estaba causando todo este caos? Gracias por matarlo.', '', 28153),
(139291, 'esMX', '¡Ja, ja! ¡Tomen eso, escorias de la Horda!', '', 28153),
(139290, 'esMX', '¡Mi ritual eh\'tá casi terminado! ¡Te vincularé, Thun\'ka el Marchitador!', '', 28153),
(139288, 'esMX', '', '¡Adelante, no me importa! Tss... Él actúa como si hubiera construido este lugar.', 28153),
(139287, 'esMX', '¡Meh, ustedes qué saben! Quédense si quieren. Nosotros nos adelantaremos. Conozco esta área como la palma de mi mano.', '', 28153),
(139286, 'esMX', '¡Esas cosas acabarán contigo! Son más feroces que los trols de sangre que encontramos en el último peregrinaje.', '', 28153),
(139285, 'esMX', '¡Bah! Ustedes no nos dan órdenes. ¡Tenemos que enseñarles una lección a esos carniceros!', '', 28153),
(139284, 'esMX', '', 'Deberías quedarte y ayudarnos a idear un plan. Los trols de sangre son demasiado para ti.', 28153),
(139283, 'esMX', 'Kisha, Lashk. Nos encargaremos de estas lacras que despedazan a Torga.', '', 28153),
(139282, 'esMX', '', '¡Ya era hora! Creí que éramos los únicos que se preocupaban por la muerte de Torga.', 28153),
(139281, 'esMX', 'Vaya, mira eso. Los demás por fin se decidieron a abandonar sus caparazones para acercarse.', '', 28153),
(139250, 'esMX', '|cffffff00+$1i de hierro|r', '|cffffff00+$1i de hierro|r', 28153),
(139241, 'esMX', '¡Sigan peleando!', '', 28153),
(139240, 'esMX', '', 'Somos un buen equipo, ¿no?', 28153),
(139204, 'esMX', '', '¡Maté otro, Sumber! ¡Ya van veintisiete!', 28153),
(139198, 'esMX', '|cffffff00+$1i de madera|r', '|cffffff00+$1i de madera|r', 28153),
(139168, 'esMX', 'Sí… luchen… resistan… G\'huun tiene sed… por su… sufrimiento.', '', 28153),
(139167, 'esMX', 'Tratarán… de detener a G\'huun. Pero… fallarán… y sufrirán.', '', 28153),
(139165, 'esMX', 'Ven.', '', 28153),
(139164, 'esMX', 'Alto.', '', 28153),
(139163, 'esMX', '¡El Taller está listo para la acción!', '', 28153),
(139162, 'esMX', 'El Taller está listo. Construye algunos demoledores y muéstrale a la Alianza la fragilidad de sus muros.', '', 28153),
(139097, 'esMX', '¡$n cubre de veneno sus garras!', '¡$n cubre de veneno sus garras!', 28153),
(139080, 'esMX', 'No comprendes... lo que yace dentro...', '', 28153),
(139079, 'esMX', '¡Nuestra fuerza te partirá en dos!', '', 28153),
(139078, 'esMX', '¡Inclínate ante tus nuevos amos!', '', 28153),
(139077, 'esMX', 'Nosotros... debemos... gobernar...', '', 28153),
(139073, 'esMX', '¡Las tormentas acuden a mi llamado!', '', 28153),
(139072, 'esMX', '¡Te arrepentirás de eso!', '', 28153),
(139071, 'esMX', '¡Tengo más poder del que tendrás en toda tu vida!', '', 28153),
(139070, 'esMX', '¡Te lo advertí!', '', 28153),
(139065, 'esMX', 'El poder está en nuestra sangre. ¡Esta tierra será nuestra!', '', 28153),
(138870, 'esMX', '', 'El pueblo de Hondonada Fletcher está en deuda contigo, $c. \n\nVe y encárgate de la señorita Tarjasenda. Nosotros despejaremos los restos del aquelarre.', 28153),
(138865, 'esMX', '', '¡Regresaste! Dime que lograste acabar con esa matrona.', 28153),
(138864, 'esMX', '', 'No hemos logrado entrar a la mina desde que comenzó a emanar esa energía. \n\nEs posible que ese ensamblaje de mimbre que lograste dominar sea nuestra única esperanza.', 28153),
(138859, 'esMX', '', 'Te agradecemos la ayuda, $c. La situación era bastante desalentadora antes de que llegaras.', 28153),
(138853, 'esMX', 'Avanzaré para explorar más el pueblo. ¡Ruego por que los aldeanos estén a salvo!', '', 28153),
(138852, 'esMX', '¡Excelente! ¡Has logrado controlar al cautivo anatémico!', '', 28153),
(138849, 'esMX', '¡Fuera!', '', 28153),
(138848, 'esMX', '', '¿Estás contento ahora? ¿Me estoy moviendo lo suficiente?', 28153),
(138847, 'esMX', '', '¿Que solo estoy aquí parada? Bueno... ¿qué tal ahora? ¿Esto cuenta como peregrinaje?', 28153),
(138841, 'esMX', 'Acércate, pequeñ$go:a; $pr. Tengo que hablar contigo.', '', 28153),
(138837, 'esMX', '', 'Voy a hacer algunas averiguaciones por mi cuenta. ¡Nos vemos en el pueblo!', 28153),
(138836, 'esMX', '', 'Eres de primera, $p. Espero que volvamos a vernos pronto.', 28153),
(138833, 'esMX', 'No debemos flaquear.', '', 28153),
(138832, 'esMX', '¡Adelante, $n! ¡Protege a los habitantes de Drustvar!', '', 28153),
(138831, 'esMX', 'Tranquilas, criaturas del mar. Debemos depositar nuestra fe en las aguas para hallar una cura.', '', 28153),
(138830, 'esMX', '', 'Si te cruzas con más de estas brujas despreciables, ¡dales un buen puñetazo en la cara de mi parte, $Gcampeón:campeona;!', 28153),
(138829, 'esMX', '', 'Nos alegra ver que aún quedan $Gcampeones:campeonas; como tú, $n.', 28153),
(138824, 'esMX', '', 'Taji y Kona ya tendrían que haber regresado. Deben estar en problemas.', 28153),
(138823, 'esMX', 'Nuestra máxima prioridad debería ser recuperar nuestros suministros. Tenemos que comer.', '', 28153),
(138822, 'esMX', '¡Oh, mar! Alivia a los enfermos y los oprimidos de Muelle Puntanzuelo. ¡Ojalá descubramos la fuente de este mal que nos persigue!', '', 28153),
(138821, 'esMX', 'Tienen suerte de que $n estaba cerca y pudo salvarlos.', '', 28153),
(138820, 'esMX', '¡Sigan así y serán tres!', '', 28153),
(138819, 'esMX', '¡Pero somos exploradores!', '', 28153),
(138818, 'esMX', '', '¡Awwwww!', 28153),
(138817, 'esMX', '¡Aww! ¡Abuelo, por favor!', '', 28153),
(138816, 'esMX', '¡Están todos castigados por dos meses!', '', 28153),
(138815, 'esMX', '', 'Sí, señor.', 28153),
(138814, 'esMX', 'Sí, abuelo.', '', 28153),
(138813, 'esMX', 'Sí, abuelo.', '', 28153),
(138812, 'esMX', 'Niños, ¡saben que no deben escaparse!', '', 28153),
(138811, 'esMX', '¡No quiero volver a oír ese cántico nunca más!', '¡No quiero volver a oír ese cántico nunca más!', 28153),
(138810, 'esMX', '¡Al fin! ¡Libre!', '¡Al fin! ¡Libre!', 28153),
(138809, 'esMX', 'Uf, ahora esa canción me dará vueltas por la cabeza todo el día.', 'Uf, ahora esa canción me dará vueltas por la cabeza todo el día.', 28153),
(138808, 'esMX', '¡Gracias, $ghéroe:heroína;!', '¡Gracias, $ghéroe:heroína;!', 28153),
(138807, 'esMX', 'Muerte... Al fin... Ahora e\' tu turno... de detener a G\'huun...', '', 28153),
(138804, 'esMX', '¿Te crees lo suficientemente fuerte para detener a G\'huun? ¡Lo averiguaremos en mi arena!', '', 28153),
(138803, 'esMX', 'Nazesh ha sido muy grosera. Tus lecciones de modales deberán ser firmes... y definitivas, me temo. Usa este pergamino ahora, ¡te será de ayuda!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138802, 'esMX', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t¡$n tiene la sangre |cFFFF0000|Hspell:255582|h[mácula]|h|r!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|t¡$n tiene la sangre |cFFFF0000|Hspell:255582|h[mácula]|h|r!', 28153),
(138801, 'esMX', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t¡$n lanza |cFFFF0000|Hspell:255577|h[Transfusión]|h|r!', 28153),
(138800, 'esMX', '', '$n cubre sus manos con oro.', 28153),
(138799, 'esMX', 'Primero hubo muchos múrlocs pequeños, luego sobrevino una tormenta y los nagas aparecieron en la playa. Me capturaron primero a mí, es muy vergonzoso.', '', 28153),
(138798, 'esMX', '¡Libera mi eh\'píritu!', '', 28153),
(138797, 'esMX', '¡No lo soporto má\', termina con mi dolor!', '', 28153),
(138796, 'esMX', '¡Deja que vaya con Bwonsamdi, por favor!', '', 28153),
(138795, 'esMX', '¡Duele! ¡Haz que se detenga!', '', 28153),
(138794, 'esMX', '¡Haz que pare eh\'te dolor!', '', 28153),
(138793, 'esMX', '¡No puedo controlarme!', '', 28153),
(138792, 'esMX', 'Por favor, ¡acaba con mi sufrimiento!', '', 28153),
(138791, 'esMX', '', '¡Libera mi eh\'píritu!', 28153),
(138790, 'esMX', '', '¡No lo soporto má\', termina con mi dolor!', 28153),
(138789, 'esMX', '', '¡Deja que vaya con Bwonsamdi, por favor!', 28153),
(138788, 'esMX', '', '¡Duele! ¡Haz que se detenga!', 28153),
(138787, 'esMX', '', '¡Haz que pare eh\'te dolor!', 28153),
(138786, 'esMX', '', '¡No puedo controlarme!', 28153),
(138785, 'esMX', '', 'Por favor, ¡acaba con mi sufrimiento!', 28153),
(138784, 'esMX', '', 'Oigo el llamado de los elemento\' y voy a donde el viento guía.', 28153),
(138783, 'esMX', '¡¿Cómo llegaron esas cosas a mi estómago?!', '¡¿Cómo llegaron esas cosas a mi estómago?!', 28153),
(138782, 'esMX', 'No... No me siento tan bien...', 'No... No me siento tan bien...', 28153),
(138781, 'esMX', '¡Hacía días que me dolía el estómago!', '¡Hacía días que me dolía el estómago!', 28153),
(138779, 'esMX', '¿E...eso estaba dentro de mí?', '¿E...eso estaba dentro de mí?', 28153),
(138776, 'esMX', '', 'A menos que estés $Udispuesto:dispuesta; a ayudar, te sugiero que sigas tu camino.', 28153),
(138775, 'esMX', '', 'Te doy la bienvenida a Hondonada Fletcher, continental. Perdón por el desorden, pero tenemos un problema un tanto... \"embrujado\".', 28153),
(138774, 'esMX', '¡Creí que los espíritus me matarían! ¡Gracias!', '¡Creí que los espíritus me matarían! ¡Gracias!', 28153),
(138773, 'esMX', 'Gracias. ¡Buscaré a mi mascota y me largaré de este lugar maldito!', 'Gracias. ¡Buscaré a mi mascota y me largaré de este lugar maldito!', 28153),
(138772, 'esMX', '¡Gracias!', '¡Gracias!', 28153),
(138771, 'esMX', 'Jamás había visto espíritus como estos. ¡Yo me largo de aquí!', 'Jamás había visto espíritus como estos. ¡Yo me largo de aquí!', 28153),
(138770, 'esMX', 'Gracias por salvarme.', 'Gracias por salvarme.', 28153),
(138769, 'esMX', 'Gracias, $Gforastero:forastera;. Creí que era mi fin.', 'Gracias, $Gforastero:forastera;. Creí que era mi fin.', 28153),
(138768, 'esMX', 'Perdona la intromisión, amigo mío. He venido con un pedido urgente para $n.', '', 28153),
(138767, 'esMX', '¿Quién eres, forah\'tero? No eres un trol de sangre... o los espírituh\' te habrían derribado.', '', 28153),
(138766, 'esMX', 'Un momento... Algo se aproxima por aquí.', '', 28153),
(138765, 'esMX', 'Estas ruinas son sagrada\' para Bwonsamdi. Los trols de sangre no nos seguirán hasta aquí.', '', 28153),
(138762, 'esMX', 'No tengo muchas, pero todas están a tu disposición.', '', 28153),
(138760, 'esMX', '', '¿La Horda retrocede de nuevo? ¿Cuál es su estrategia?', 28153),
(138759, 'esMX', 'La jefa de guerra no debe escapar. Solo podemos ganar si la capturamos.', '', 28153),
(138758, 'esMX', 'Insignificante...', '', 28153),
(138757, 'esMX', '¡Esta cala le pertenece a la Ama de las mareas Nazesh! ¡Revelaremos lo que se ha estado ocultando en Zuldazar!', '', 28153),
(138756, 'esMX', 'Je. Carne fresca.', 'Je. Carne fresca.', 28153),
(138755, 'esMX', 'No te preocupes, omitiremos esa parte. Conozco un lugar para escondernos mientras conseguimos información.', '', 28153),
(138754, 'esMX', 'Creo que se refiere a una iniciación poco amistosa.', '', 28153),
(138753, 'esMX', 'Muy bien, entren y preséntense en... \"orientación\". Je.', '', 28153),
(138752, 'esMX', 'Mmm... Bueno, AL MENOS trajeron sus propios sombreros...', '', 28153),
(138751, 'esMX', 'Queremos unirnos a los Asaltantes mareaférrea. Trajimos nuestros propios sombreros.', 'Queremos unirnos a los Asaltantes mareaférrea. Trajimos nuestros propios sombreros.', 28153),
(138749, 'esMX', 'Eh\'te lugar es sagrado. Es mi misión protegerlo por toda la eternidad.', '', 28153),
(138748, 'esMX', 'Muchos peregrino\' solían albergarse aquí en su camino hacia la Necrópolis.\n\nÚltimamente hay demasiada tranquilidad... Eso no es bueno. Para nada.', '', 28153),
(138747, 'esMX', 'He protegido eh\'te santuario desde que se construyó. Y lo protegeré hasta que quede reducido a polvo.', '', 28153),
(138746, 'esMX', 'Todos los que se dirijan hacia la Necrópolis son bienvenido\'.', '', 28153),
(138745, 'esMX', 'Por la voluntad de Bwonsamdi, ofrezco deh\'canso a los viajeros que recorren eh\'te templo.', '', 28153),
(138744, 'esMX', 'Te ves bien. Vamos a decirle al reclutador que queremos formar parte de la tripulación.', '', 28153),
(138743, 'esMX', 'Ponte el sombrero. ¡No puedes ser un lobo de mar si no tienes sombrero!', '', 28153),
(138742, 'esMX', 'Solo necesito unos minutos más, Rosalina. Con la ayuda de los arpones mejorados, ¡vencerás a tu presa!', '', 28153),
(138741, 'esMX', '', 'Okri, ¿qué pasa con nuestros suministros? Quiero zarpar lo antes posible. ¡Estamos perdiendo el tiempo!', 28153),
(138740, 'esMX', '¿Sí? ¿Qué quieres?', '¿Sí? ¿Qué quieres?', 28153),
(138739, 'esMX', 'Supongo que regresaré a Boralus con las manos vacías por ahora. Ve a verme allí con el pergamino y hablaremos sobre tu recompensa.', '', 28153),
(138738, 'esMX', 'Esto es importante: el pergamino que vas a buscar está sellado con cera verde. ¡DEBE ser verde!', '', 28153),
(138737, 'esMX', 'El hombre que buscas se llama Carentan. Su tienda está subiendo las escaleras, en el extremo sur del pueblo.', '', 28153),
(138734, 'esMX', '¿Por qué me muerdes? No tengo carne en los hueso\'.', '', 28153),
(138733, 'esMX', '¡Cómete a la bestia, serpiente loca!', '', 28153),
(138732, 'esMX', 'Me gusta tu espíritu belicoso. ¡Guárdalo para los sethrak!', '', 28153),
(138731, 'esMX', '¡Ja! Por poco me da esta vez.', '', 28153),
(138730, 'esMX', '¡Rezan selecciona a $n como objetivo de |TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[Devorar]|h|r!', '', 28153),
(138729, 'esMX', 'El capitán Gulnaku pagará por lo que ha hecho.', '', 28153),
(138728, 'esMX', 'Gracias por liberarme... A cambio, te dejaré vivir.', '', 28153),
(138725, 'esMX', '¡Ten cuidado dónde excavas! ¡Yo eh\'taré durmiendo por allí!', '¡Ten cuidado dónde excavas! ¡Yo eh\'taré durmiendo por allí!', 28153),
(138724, 'esMX', 'Es probable que los espíritus de esta área no se queden de brazos cruzados mientras tú destruyes su tierra...', '', 28153),
(138723, 'esMX', '¡Creo que no es buena idea lanzar bombas sobre esos huesos!', '', 28153),
(138722, 'esMX', 'Les pedí a muchísimos trols que me contaran sobre Xibala, y escuché muchísimas historias diferentes, sin importar mis métodos de interrogación.\n\nAlgunos dijeron que Xibala dejaba a los cuerpo hinchados de putrefacción.\n\nOtros decían que quien se atrevía a mirarlo se convertía en un esqueleto viviente.\n\nO que merodeaba entre las sombras y que salía a la noche para devorar a la gente mientras dormía.\n\nO que esperaba cerca de los caminos para hacer que los pasantes murieran atragantados por su propia sangre.\n\n¡No me sorprende que los locales se mantuvieran alejados!', '', 28153),
(138721, 'esMX', 'Hace una era que no poso los ojos sobre este lugar. Incluso entonces, los locales le temían y evitaban pasar por aquí...\n\nEs que hay espíritus malignos, $n. Lo mejor es no molestarlos.', '', 28153),
(138717, 'esMX', 'No deberías vagar por los callejones de Zem\'lan, rata. ¡Ataca, Kiffa!', 'No deberías vagar por los callejones de Zem\'lan, rata. ¡Ataca, Kiffa!', 28153),
(138716, 'esMX', 'La Horda... me vengará...', '', 28153),
(138715, 'esMX', 'Este sitio pertenece al Relicario. ¡La Alianza no es bienvenida!', '', 28153),
(138709, 'esMX', '', 'Quizá haya algunos daños colaterales, pero estoy segura de que con el tiempo pondremos todo en su lugar. Probablemente tengamos que llamar a algunos asistentes más...', 28153),
(138707, 'esMX', 'Ey, Zalnon\'mak, tu sombrero parece muy cómodo. ¡Creo que me lo quedaré!', '', 28153),
(138706, 'esMX', '¿Quién quiere beber algo conmigo?', '', 28153),
(138705, 'esMX', '¿Para qué trabajan tanto? Saben que somos inmortales, ¿no?', '', 28153),
(138704, 'esMX', '¡Ey, Senjilak! ¡Xunanji se roba tus cosas cada vez que les das la espalda!', '', 28153),
(138703, 'esMX', 'Ey, Segazea, tus esbirros están apestando el lugar. ¡Sácalos de aquí!', '', 28153),
(138702, 'esMX', 'Xulai, ¡eres el bobo más lento que he visto!', '', 28153),
(138701, 'esMX', '¿Tienes sed? ¡Qué mal!', '', 28153),
(138700, 'esMX', 'Apresúrense, vagos. ¡Necesito más grog!', '', 28153),
(138699, 'esMX', '¡$n ha capturado la Mina Mostacho Seco!', '¡$n ha capturado la Mina Mostacho Seco!', 28153),
(138698, 'esMX', '', 'Nunca más te escapes así. ¿Me oyes? Ahora, vamos.Tenemos trabajo por hacer.', 28153),
(138691, 'esMX', 'Yo... ¡Calma! ¡Calma, por favor! Estamos haciendo todo lo que podemos. Encontraremos una cura, ¡y la causa!', '', 28153),
(138690, 'esMX', '', '¡Tienes que ayudarnos, Therold! ¡Necesitamos respuestas! ¡Necesitamos una cura!', 28153),
(138689, 'esMX', '¡¿Cuál será la causa de esta enfermedad?!', '', 28153),
(138688, 'esMX', '', '¡Nuestros niños se están enfermando!', 28153),
(138687, 'esMX', 'Regresa para la revancha...', 'Regresa para la revancha...', 28153),
(138686, 'esMX', 'Llevo todo el día bebiendo para eh\'to...', 'Llevo todo el día bebiendo para esto...', 28153),
(138679, 'esMX', 'Esto no le gustará nada a Gulnaku.', 'Esto no le gustará nada a Gulnaku.', 28153),
(138678, 'esMX', '¡No te acerque\' a mi mapa del tesoro!', '¡No te acerques a mi mapa del tesoro!', 28153),
(138676, 'esMX', '¡Si trae una cabeza de vulpera, tendrá un descuento en la primera compra!', '', 28153),
(138675, 'esMX', '¡Un poco de grog alivia todo dolor!', '', 28153),
(138674, 'esMX', '¡Los parches nunca están de más!', '', 28153),
(138673, 'esMX', '¡Véase como el mismísimo Zem\'lan con las últimas prendas de Parches!', '', 28153),
(138672, 'esMX', '¡Yoksa conoce el mojo mejor que nadie! ¡Llévese sus últimas pociones hoy mismo!', '', 28153),
(138671, 'esMX', '¡Tenemos alfanjes nuevos! ¡Superfilosos!', '', 28153),
(138670, 'esMX', '¡Luche junto a un temible tigre hoy!', '', 28153),
(138669, 'esMX', '¡Llévese filetes de vulpera recién hechos!', '', 28153),
(138668, 'esMX', 'Oggo vende todo a mitad de precio por el reh\'to del día...', 'Oggo vende todo a mitad de precio por el reh\'to del día...', 28153),
(138666, 'esMX', '', 'Yo puedo salir de aquí por mi cuenta. Ten cuidado.', 28153),
(138664, 'esMX', 'Limpia este desastre... antes de irte.', 'Limpia este desah\'tre... antes de irte.', 28153),
(138663, 'esMX', 'Hagamos de esta posada tu hogar... ¡para siempre!', 'Hagamos de eh\'ta posada tu hogar... ¡para siempre!', 28153),
(138662, 'esMX', 'Aquí estás, $c. Necesitamo\' tu ayuda con un problemita.', '', 28153),
(138661, 'esMX', 'Eh\'tamos unidos a Zem\'lan, para toda la eternidad.', 'Eh\'tamos unidos a Zem\'lan, para toda la eternidad.', 28153),
(138660, 'esMX', 'Me he sacrificado para proteger a mi tripulación incontable\' vece\'. ¡De aquí no pasas!', 'Me he sacrificado para proteger a mi tripulación incontable\' vece\'. ¡De aquí no pasas!', 28153),
(138659, 'esMX', 'Regresamo\' desde la tumba, lih\'tos para luchar.', 'Regresamo\' desde la tumba, lih\'tos para luchar.', 28153),
(138658, 'esMX', '¿Acaso yo no te había matado? ¿O tú me había\' matado a mí?', '¿Acaso yo no te había matado? ¿O tú me había\' matado a mí?', 28153),
(138655, 'esMX', '¡Me alimentaré de tu carne y le ofreceré tu alma a mi amo!', '', 28153),
(138652, 'esMX', '¡Te arrancaré la carne de los huesos!', '', 28153),
(138651, 'esMX', 'Peleas bien para ser $Uun patético:una patética; habitante de la tierra... ¡pero esto termina aquí!', '', 28153),
(138650, 'esMX', 'Corre rápido, $Udesarrapado:desarrapada;. Tengo toda la eternidad para perseguirte.', 'Corre rápido, $Udesarrapado:desarrapada;. Tengo toda la eternidad para perseguirte.', 28153),
(138649, 'esMX', '¡Nadie me quitará eh\'te tesoro! ¡Ni tú, ni Zem\'lan, ni nadie!', '¡Nadie me quitará eh\'te tesoro! ¡Ni tú, ni Zem\'lan, ni nadie!', 28153),
(138644, 'esMX', '¡El alba de nuestro imperio es tu extinción!', '¡El alba de nuestro imperio es tu extinción!', 28153),
(138641, 'esMX', '¡Que tu muerte sea una lección para los demás!', '¡Que tu muerte sea una lección para los demás!', 28153),
(138634, 'esMX', 'No te preocupe\', $pr. No voy a pelear contigo.\n\nZem\'lan me hizo esto. Nos hizo esto a todo\', quisiéramos o no.\n\nMírame...\n\n<Guntha el Gentil suspira con pesadumbre.>\n\n¿Quiere\' beber algo?', '', 28153),
(138633, 'esMX', 'Si quieres sobrevivir en Vol\'dun, tiene\' que mirar a la muerte a los ojo\' todo el tiempo... y nunca pestañear.', '', 28153),
(138631, 'esMX', 'Sin presa no hay recompensa.', 'Tu tesoro... ahora e\' mío.', 28153),
(138628, 'esMX', '¡La maldición nos fortalece!', 'He sacrificado todo por Zem\'lan.', 28153),
(138627, 'esMX', 'Zem\'lan ya no debe lidiar con los vivo\'.', '¡Si no ere\' de la tripulación, estás muerto!', 28153),
(138625, 'esMX', 'He defendido eh\'te puerto por un sinfín de año\'.', '¡Eh\'te es nuestro puerto!', 28153),
(138624, 'esMX', '¡Debes andar con cuidado! Jamáh\' subestimes a los sethrak...', '', 28153),
(138623, 'esMX', '', '¡Y listo! Gracias por la ayuda.', 28153),
(138622, 'esMX', '', 'Casi termino....', 28153),
(138621, 'esMX', '', 'Al fin he llegado a las verdaderas reliquias, ahora que todas las baratijas quedaron descartadas. No debe faltar mucho.', 28153),
(138620, 'esMX', '', 'Y esta colección de huesos debe ser cortesía de Birch, a juzgar por las marcas de dientes.', 28153),
(138619, 'esMX', '', 'Un \"prototipo Girafusible auténtico\". Es un desperdicio de metal, pero no hay lugar para la basura.', 28153),
(138618, 'esMX', '', 'Algunos de nuestros hallazgos más valiosos quedaron en este cajón. Protégeme, $c, mientras trato de recuperar la mayor cantidad de cosas posibles.', 28153),
(138615, 'esMX', 'No abandonaremos el templo.', '', 28153),
(138589, 'esMX', 'Siempre que este templo siga en pie, sus paredes te servirán como refugio.', '', 28153),
(138568, 'esMX', '', '¡Oooh! ¡Cuando recupere el aliento te voy a dar una buena patada en la espinilla!', 28153),
(138567, 'esMX', '¡Oye! ¡No soy un perro! Y me sorprende que puedas siquiera correr con esas piernas retaconas. Estaba seguro de que rodarías en la primera pendiente.', '', 28153),
(138566, 'esMX', '', '¡Una apertura! ¡Te juego una carrera, Birch! ¡A que no me atrapas! ¡Aunque seas parte perro!', 28153),
(138556, 'esMX', '¡La Alianza se ha apoderado del Patio de Stromgarde!', '¡La Alianza se ha apoderado del Patio de Stromgarde!', 28153),
(138555, 'esMX', '¡$n ha capturado el Patio de Stromgarde!', '¡$n ha capturado el Patio de Stromgarde!', 28153),
(138553, 'esMX', '', '¡Es una emboscada! ¡Debemos proteger a los aldeanos!', 28153),
(138552, 'esMX', '', 'Ven, $n. ¡Cabalgaremos hacia Paso Alto!', 28153),
(138551, 'esMX', 'Espero que tenga razón, milady. Formen filas, hombres. ¡A cabalgar!', '', 28153),
(138550, 'esMX', '', 'Lo he decidido, mariscal. $UEste:Esta; $c me escoltará y cuidará de mí.', 28153),
(138549, 'esMX', 'Pero milady, sería más seguro si...', '', 28153),
(138548, 'esMX', '', 'Mariscal, usted y sus hombres viajarán a Alto de Arom. Los veré allí después de tomar un pequeño desvío.', 28153),
(138547, 'esMX', '¡La Alianza se ha apoderado de Paso Valeroso!', '¡La Alianza se ha apoderado de Paso Valeroso!', 28153),
(138546, 'esMX', '¡$n ha capturado Paso Valeroso!', '¡$n ha capturado Paso Valeroso!', 28153),
(138545, 'esMX', '¿Quién sigue?', '', 28153),
(138544, 'esMX', 'Bienvenido a la tripulación eterna de lo\' condenados, contramaestre.', '', 28153),
(138543, 'esMX', '¡Raaagh!', '', 28153),
(138542, 'esMX', '¡Contramaestre Jamboya, renace!', '', 28153),
(138540, 'esMX', 'Acércate y recibe mi don. ¡Únete a mi tripulación para toda la eternidad!', '', 28153),
(138539, 'esMX', 'Este e\' nuestro hogar. Haremo\' lo que haga falta para conservar eh\'te puerto... ¡para siempre!', '', 28153),
(138538, 'esMX', '¡NO!', '¡NO!', 28153),
(138537, 'esMX', 'Lo\' sethrak piensan que vamos a someternos y morir. ¿Será así?', '', 28153),
(138535, 'esMX', 'Me niego a morir... Te veré pronto, Jamboya...', '', 28153),
(138534, 'esMX', '¿Un motín organizado por mi contramaestre? ¡Te arrah\'traré por la quilla!', '', 28153),
(138533, 'esMX', '¡Jo! ¿Qué rata\' de mar intentan desafiarme?', '', 28153),
(138532, 'esMX', '', 'La Madre... te atrapará...', 28153),
(138531, 'esMX', '', 'Es inútil resistirse. ¡El Aquelarre Hiel de corazón conquistará Kul Tiras!', 28153),
(138530, 'esMX', 'Protegeremos a Lady Lucille, continental. ¡Acaba con su líder!', '', 28153),
(138529, 'esMX', '', '¡La Madre acabará contigo, Lucille Tarjasenda!', 28153),
(138528, 'esMX', '¿Qué diablos es eso?', '', 28153),
(138527, 'esMX', 'Las trampas ya no los demoran. ¡Se acercan más!', '', 28153),
(138526, 'esMX', 'Cálmate, Kal\'dran. Aún podemos derrotar a Zardrax.', 'Cálmate, Kal\'dran. Aún podemos derrotar a Zardrax.', 28153),
(138521, 'esMX', '', 'Gracias, oficial. ¿Vamos, $c?', 28153),
(138520, 'esMX', 'Señorita Tarjasenda, puede usted marcharse... Lamento los inconvenientes...', '', 28153),
(138519, 'esMX', '¡Atención! Se ha determinado que otra bruja fue la responsable de la maldición en Hondonada Fletcher.', '', 28153),
(138518, 'esMX', '', 'Así está mejor. Ahora, vamos a...', 28153),
(138517, 'esMX', '...solo debo conseguir otro trol de sangre. Son infinitos, ¡y tú estás $ucondenado:condenada;!', '', 28153),
(138516, 'esMX', '¡No! ¡Nana\'kwug! Ahora tengo que...', '', 28153),
(138515, 'esMX', 'Ja, ja... tus esfuerzos son inútiles. ¡Nunca detendrán mi poder!', '', 28153),
(138514, 'esMX', '¿Crees que esto marcará alguna diferencia? El poder del dios de la sangre fluye por mis venas, ¡tú no puedes detenerlo!', '', 28153),
(138513, 'esMX', 'Mi poder... ¡se disipa! Ja, ja... ¡Debes estar $udesesperado:desesperada; para creer que esto funcionará!', '', 28153),
(138509, 'esMX', '¡Cuidado! ¡Enemigos en el bosque!', '', 28153),
(138502, 'esMX', '¡Listo! Eso e\' todo lo que puedo darte sin lastimarme demasiado. Ve y quema esas pila\' de esqueletos.', '', 28153),
(138501, 'esMX', 'Tú concéntrate mientra\' te entrego una parte de mi mojo de fuego...', '', 28153),
(138500, 'esMX', 'Estoy listo para recibir tu mojo de fuego y destruir los túmulos fúnebres.', 'Estoy lista para recibir tu mojo de fuego y destruir los túmulos fúnebres.', 28153),
(138499, 'esMX', '', 'Bien, entonces parece que tendremos que atacar nosotros. Creo que conozco la manera perfecta de hacerlo.', 28153),
(138498, 'esMX', 'Ellas... lo han atrapado, milady. Estábamos planeando una manera de rescatarlo cuando nos enteramos de este... juicio.', '', 28153),
(138497, 'esMX', '', '¿Y mi padre? ¿Qué está haciendo él para combatir esta incursión?', 28153),
(138496, 'esMX', 'Han arrasado con gran parte de las tierras que están detrás de las montañas. Apenas conservamos algunas en Alto de Arom.', '', 28153),
(138495, 'esMX', 'Es peor de lo que cree, milady. El aquelarre se ha estado esparciendo sin control por todo Drustvar.', '', 28153),
(138494, 'esMX', '', '¡Mariscal! ¿Qué sabe sobre este aquelarre? ¡Dígame qué le sucede a nuestra tierra!', 28153),
(138449, 'esMX', '', '¡Guau! ¡Miren cómo se veía el viejo Zem\'lan!', 28153),
(138448, 'esMX', '', 'Así que Zem\'lan era un cretino, ¿eh?', 28153),
(138439, 'esMX', 'Buh\'ca los ídolos y reúne a la tripulación.', '', 28153),
(138438, 'esMX', 'Lo\' sethrak no nos robarán nueh\'tro hogar. Ni hoy, ni nunca.', '', 28153),
(138437, 'esMX', 'Yo, eh. Ti... tiene que haber otra forma, capitán. La tripulación...', '', 28153),
(138436, 'esMX', '¿Esto es un truco? Sí, ¿no?', 'Me has salvado la vida. ¡Habría muerto aquí!', 28153),
(138435, 'esMX', 'No hay tiempo para presentaciones. No quiero pasar ni un minuto más en esta mina.', 'No hay tiempo para presentaciones. No quiero pasar ni un minuto más en esta mina.', 28153),
(138434, 'esMX', '¡No me cueh\'tiones! Lleva a todos al altar. ¡Ahora!', '', 28153),
(138433, 'esMX', 'Sí que me alegra verte.', 'Sí que me alegra verte.', 28153),
(138432, 'esMX', 'No sé quién eres ni qué quieres, pero te agradezco.', 'No sé quién eres ni qué quieres, pero te agradezco.', 28153),
(138431, 'esMX', 'Me salvaste la vida, en serio. ¡Me habría muerto aquí!', 'Me salvaste la vida, en serio. ¡Me habría muerto aquí!', 28153),
(138430, 'esMX', 'Puede que mis brazos estén cansados, ¡pero mis pies están listos para correr lejos de aquí!', 'No sé quién eres ni qué quieres, pero gracias.', 28153),
(138429, 'esMX', '¡Maldita arena! ¡Malditas serpiente\'! ¡El Puerto de Zem\'lan es MÍO!', '', 28153),
(138428, 'esMX', 'Te debo una, $Gextraño:extraña;.', 'Te debo una, $Gextraño:extraña;.', 28153),
(138427, 'esMX', '¡Son demasiado\', capitán! Tenemo\' que retirarnos o toda la tripulación morirá.', '', 28153),
(138426, 'esMX', '¡Corten a esas serpiente\' en pedazo\'! ¡Sin piedad!', '', 28153),
(138373, 'esMX', '¡Espero poder correr más rápido que estos forajidos!', '', 28153),
(138316, 'esMX', 'Gracias, $c. Hablaremos en un lugar más seguro.', '', 28153),
(138288, 'esMX', '¡Nadie se retira! O mueren a mano de lo\' sethrak, o mueren en las mía\'.', '', 28153),
(138282, 'esMX', 'Reúne a la tripulación. Quiero a todoh\' los filibusteros ebrio\' en la puerta frontal.', '', 28153),
(138281, 'esMX', 'Nadie me lo robará. ¡Jamás!', '', 28153),
(138280, 'esMX', 'Entonce\' son tan estúpidos como todos los demás. ¡Eh\'te es el Puerto de Zem\'lan! ¡MI puerto!', '', 28153),
(138279, 'esMX', '¡Capitán Zem\'lan, el ejército sethrak se acerca! ¡Son demasiado\'!', '', 28153),
(138264, 'esMX', '¡Ingeniero de vuelo Krazzle a la orden!', '', 28153),
(138247, 'esMX', '¡Así que fuera de mi puerto! Mueran en la\' dunas, donde pertenecen.', '', 28153),
(138242, 'esMX', 'Y como ninguno de ustede\' tiene algo más que sus inmundas vestimentas, ya están muerto\' para mí.', '', 28153),
(138240, 'esMX', 'Ninguno de ustede\' se acercará a mis barcos, a meno\' que me paguen con oro.', '', 28153),
(138238, 'esMX', 'Entonces mueran, basuras inútiles.', '', 28153),
(138235, 'esMX', '¡Si no nos dejas subir, todo\' moriremos!', '¡Si no nos dejas subir, todo\' moriremos!', 28153),
(138234, 'esMX', '¡Apártense, refugiados! ¡Primero lo\' piratas!', '', 28153),
(138233, 'esMX', 'Por favor, Zem\'lan. ¡Déjanos subir a lo\' botes! ¡Los sethrak van a matarnos!', 'Por favor, Zem\'lan. ¡Déjanos subir a lo\' botes! ¡Los sethrak van a matarnos!', 28153),
(138232, 'esMX', 'Con el eh\'pacio que nos sobre subiremos a todos lo\' que podamos.', '', 28153),
(138224, 'esMX', '', 'Has llegado en un momento complicado, continental. \n\n¿Qué te trae por aquí?', 28153),
(138214, 'esMX', 'Bien, soy el único entonces.', '', 28153),
(138213, 'esMX', '', 'En lo más mínimo.', 28153),
(138212, 'esMX', 'Nop.', '', 28153),
(138211, 'esMX', '', 'No.', 28153),
(138210, 'esMX', '¿A nadie le parece excesivo que hayamos aniquilado cientos y cientos de sethrak solo porque mataron a algunos de los nuestros?', '', 28153),
(138209, 'esMX', 'Es un alivio, aunque creo que eso fue un poco escandaloso para mi gusto.', '', 28153),
(138208, 'esMX', '', '¡Ja, ja, ja, eso fue fantástico! ¡Y aún sigues con vida!', 28153),
(138203, 'esMX', '¡Zepelín a la vista!', '', 28153),
(138202, 'esMX', '¡Lo has hecho de nuevo, mi $gamigo:amiga;! ¡Buen trabajo!', '', 28153),
(138200, 'esMX', 'Los troggs me siguieron hasta aquí. ¡Todo esto es mi culpa! ¡Por favor ayúdame, $n!', '', 28153),
(138123, 'esMX', '¡¿Quién diría que un tortollano podía sentirse tan libre?!', '', 28153),
(138122, 'esMX', '¡Puedo sentir cómo el viento me acaricia las escamas!', '', 28153),
(138121, 'esMX', '¡Ey! ¡Soy libre como las aves! Jaja.', '', 28153),
(138120, 'esMX', '¡Vas muy bien, papá!', '', 28153),
(138118, 'esMX', 'NO LO SUELTES, NO LO SUELTES, NO LO SUELTES', '', 28153),
(138075, 'esMX', '$uQuerido amigo:Querida amiga;, ¿podrías ayudarme a inspeccionar estos caballos? ¡Tiene que ser el caballo perfecto!', '', 28153),
(138074, 'esMX', 'Los trabajadores holgazanes siempre roban de ahí. Si no encuentras grog, revisa a los trabajadores.', '', 28153),
(138073, 'esMX', 'Siempre tengo una reserva oculta bajo del agua. Así está siempre fría.', '', 28153),
(138072, 'esMX', 'Muy bien, $pr carnosito. Dime si necesitas algo para beber.', '', 28153),
(138071, 'esMX', '', '¡Iiiiaaa!', 28153),
(138070, 'esMX', '', '¡Tienes suerte de que no pueda patear más alto! ¡No lo niegues! ¡Tú activaste la trampa!', 28153),
(138069, 'esMX', '¡Au! ¡Esa era mi espinilla!', '', 28153),
(138068, 'esMX', '¿Mis problemas? ¿MIS PROBLEMAS? Creo que TÚ fuiste la que la activó, enana insoportable..', '', 28153),
(138067, 'esMX', '', '-¡para arreglar tus problemas!', 28153),
(138066, 'esMX', '', 'Entonces salgamos de aquí y encontremos alguien para comerciar. Me muero de hambre.', 28153),
(138065, 'esMX', '', 'Además, en el camino recogí suficientes gemas y dijes para cubrir los costos de un mes entero.', 28153),
(138064, 'esMX', '', 'Sí, sí, yo también los quiero.', 28153),
(138061, 'esMX', '', 'Aquí ya no hay nada para nosotros. Recojamos nuestras cosas y salgamos de aquí.', 28153),
(138060, 'esMX', '', 'No me sorprende. Era casi imposible que disipáramos la maldición.', 28153),
(138059, 'esMX', '¿Quieres ver cómo se preparan las salchichas?', '', 28153),
(138058, 'esMX', '¿Quién quiere más tocino? ¡Yo, yo! ¡Je, je!', '', 28153),
(138057, 'esMX', '¡Te convertiré en tocino!', '', 28153),
(138056, 'esMX', 'Te cortaré... en pedacitos...', '', 28153),
(138055, 'esMX', 'Estás... $Gcondenado:condenada;...', '', 28153),
(138054, 'esMX', '', 'Que los vientos te amparen, $p.... y no te vuelvas $guno:una; de ellos, ¿sí?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138053, 'esMX', '', 'Voy a escabullirme en la caravana para preparar a todos y saquear este lugar cuando deshagas la maldición.', 28153),
(138052, 'esMX', '', 'Estas son las notas que encontré. Solo faltan un par de cosas más para realizar el ritual.', 28153),
(138051, 'esMX', 'Realmente estamos muy agradecidos de que nos salvaras el pellejo, $c. Tanto luchar contra las maldiciones debe haberte dejado $Gfamélico:famélica;.\n\n¿Te apetecen unas salchichas?', '', 28153),
(138050, 'esMX', 'Por favor, disfruta la fiesta. ¡Cabalga! ¡Come! ¡Bebe! Eres mi $Uinvitado:invitada; de honor.', '', 28153),
(138049, 'esMX', '$GAmigo mío:Amiga mía;, no solo salvaste a mi hijo, ¡también salvaste mi festival! ¡La gente contará esta historia durante años!', '', 28153),
(138048, 'esMX', '', '¿Estás aquí por comida o por algo más?', 28153),
(138047, 'esMX', 'Revitalizando', 'Revitalizando', 28153),
(138046, 'esMX', '', 'Me quedaré aquí mientras buscas el resto de los ídolos. Tráelos de vuelta cuando tengas todos.', 28153),
(138045, 'esMX', '', 'También hay uno de los ídolos. ¿Lo tomarías por mí?', 28153),
(138044, 'esMX', '', 'Creo que esta es la sala del trono de Zem\'lan. ¡Hay tesoros por doquier!', 28153),
(138042, 'esMX', '¡Regresen a su posición! ¡No rompan filas!', '', 28153),
(138040, 'esMX', '', 'Lo más probable es que Meeki esté muerto. Huye de Zem\'lan mientras puedas.', 28153),
(138039, 'esMX', '', '¡Eres un ángel $pr grande y rechoncho! ¡Mi $Ghéroe:heroína;!', 28153),
(138038, 'esMX', 'Se llevaron a Ahna hacia al sur, ¡pero yo me largo de aquí!', '', 28153),
(138037, 'esMX', 'Debo regresar a mi templo para recuperar la fuerza. Te eh\'peraré allí.', '', 28153),
(138036, 'esMX', 'Por fin libre.', '', 28153),
(138035, 'esMX', 'Vuelve a mí pronto, Norah.', '', 28153),
(138034, 'esMX', '', 'Si nos vamos ahora, moriremos de hambre en las dunas.', 28153),
(138033, 'esMX', '', 'No, no podemos. Y lo sabes.', 28153),
(138032, 'esMX', 'No tienes que hacer esto, Norah. Podemos levantar campamento y abandonar Zem\'lan.', '', 28153),
(138031, 'esMX', '', 'Cuida la caravana mientras no estoy, Viggy.', 28153),
(138029, 'esMX', 'Hace mucho tiempo que no vengo por aquí. Espero tener algunos amigos todavía.', '', 28153),
(138028, 'esMX', 'Cuando tengas pruebas de que la Compañía Aspafresno ha estado vendiendo armas a estas ratas, ven a verme en la colina, en la puerta principal.', '', 28153),
(138026, 'esMX', 'Muy bien, ya tengo tus... piernas. ¿Y ahora, qué?', 'Muy bien, ya tengo... tus piernas. ¿Y ahora, qué?', 28153),
(138025, 'esMX', '¡Este será el festival más emocionante en años! Súbete a Arión y dales su merecido a los troggs. ¡Te será muy útil en combate!', '', 28153),
(138024, 'esMX', 'Sin duda Amparo del Ocaso está en deuda contigo, $c. \n\nSolo espero que podamos pagarla de alguna manera.', '', 28153),
(138023, 'esMX', '¡Arión y tú forman un equipo maravilloso! Puedes recorrer la finca con él todo el tiempo que quieras.', '', 28153),
(138021, 'esMX', 'Quizás mucho\' no sepan lo que hiciste por ellos, pero yo jamás lo olvidaré.', '', 28153),
(138020, 'esMX', '', '¡$UForastero:Forastera; imbécil! ¡¿Cómo te atreves a desafiarme en mi propia tierra?!', 28153),
(138019, 'esMX', '', 'Ja, ja, ja, ja... ¡Nadie escuchará tus gritos!', 28153),
(138018, 'esMX', '¡Una gran bienvenida para $Gnuestro estimado invitado:nuestra estimada invitada;: $gLord:Lady; $n!', '', 28153),
(138017, 'esMX', '¡Permítanme anunciarles la llegada de $gLord:Lady; $n!', '', 28153),
(138016, 'esMX', '¡Es un verdadero placer para mí darte la bienvenida, $gLord:Lady; $n, a la Finca Norwington!', '', 28153),
(138015, 'esMX', '', 'Soy Jane. Era una mercenaria que servía en un navío mercante antes de que las sirenas nos arrastraran hasta aquí.$B$BEstos sujetos me salvaron de la marea, me pusieron un apodo y han sido como mi familia desde entonces.$B$BPuede que parezcan un poco extraños, pero son personas buenas y honestas. Para algunos de ellos, haber naufragado hasta aquí fue un cambio en su vida más que bienvenido. Una oportunidad para empezar de nuevo. Otros solo quieren sobrevivir hasta poder volver a casa.', 28153),
(138014, 'esMX', 'Xenxuju me hizo beber del cáliz de trueno. Gracias a Xenxuju, ¡pronto todos seremo\' uno con Akunda!', '', 28153),
(138013, 'esMX', '', 'Kel\'vax recibió... mucha\' ofrendas... para que tú murieras...', 28153),
(138012, 'esMX', '', '¡Creo que te agregaré a las ofrenda\' de cadávere\' para Kel\'vax!', 28153),
(138009, 'esMX', 'N-n-no lo ahuyentes, Norah. N-n-necesitamos su ayuda.', 'N-n-no lo ahuyentes, Norah. N-n-necesitamos su ayuda.', 28153),
(138008, 'esMX', 'Dime, $Uforastero:forastera;, ¿conoces la leyenda de Zem\'lan?', 'Dime, $Uforastero:forastera;, ¿conoces la leyenda de Zem\'lan?', 28153),
(137999, 'esMX', 'Creo que me quedaré por ahí atrás. Es que... eeh... Hay... más luz para leer ahí. ¡Buena suerte!', '', 28153),
(137997, 'esMX', '<Inspecciona la mochila>', '<Inspecciona la mochila>', 28153),
(137993, 'esMX', '<Es la mochila de un niño. Tiene un broche de \"Joven expedicionario\" en la parte trasera.>', '', 28153),
(137988, 'esMX', 'Solo tomaré un tesoro más antes de irme...', 'Solo tomaré un tesoro más antes de irme...', 28153),
(137987, 'esMX', 'Gracias. No miraré hacia atrás.', 'Gracias. No miraré hacia atrás.', 28153),
(137986, 'esMX', 'He cometido un error terrible.', 'He cometido un error terrible.', 28153),
(137985, 'esMX', '¿Has visto los monstruos que tienen de mascota? Este lugar es una pesadilla.', '¿Has visto los monstruos que tienen de mascota? Este lugar es una pesadilla.', 28153),
(137984, 'esMX', 'Gracias, $pr. No habría durado mucho más.', 'Gracias, $pr. No habría durado mucho más.', 28153),
(137983, 'esMX', 'Estoy en deuda contigo.', 'Estoy en deuda contigo.', 28153),
(137982, 'esMX', 'Soy el último de mi caravana...', 'Soy la última de mi caravana...', 28153),
(137981, 'esMX', 'He visto tantos horrores...', 'He visto tantos horrores...', 28153),
(137926, 'esMX', 'Tu amigo eh\'tá muerto, $pr. Este no e\' lugar para mortales.', '', 28153),
(137925, 'esMX', '', '¿Así que un trol llamado Zem\'lan gobernaba este puerto? Entonces aquí debía estar su trono.', 28153),
(137924, 'esMX', 'Bueno... Esto iba a ser un peregrinaje para que los tortollanos escucharan las historias de Torga. Pero... supongo que puedes acompañarnos.', '', 28153),
(137913, 'esMX', '¡Tengo el remedio perfecto para los intruso\' entrometidos como tú!', '', 28153),
(137912, 'esMX', 'Siempre me gustó ese pequeñín. El robot, claro.', '', 28153),
(137911, 'esMX', 'Yo tenía un robot de juguete. Un bonito compañero a cuerda que le compré a un gnomo en Boralus.', '', 28153),
(137909, 'esMX', 'Conseguir los componentes para tu comunión es el primer paso hacia la redención.', '', 28153),
(137908, 'esMX', 'No hagas esperar a Xenxuju... ¡pero ten cuidado! Te aseguro que no quiere\' meterte con él.', '', 28153),
(137907, 'esMX', '%s sigue hablando sobre asumir la responsabilidad por los actos propios durante varios minutos.', '', 28153),
(137906, 'esMX', 'Mmm... Probablemente mi brújula. ¡Nunca me hizo perder el rumbo! Bueno, hasta que terminamos aquí. Pero eso no es culpa de la brújula. Digo, es un objeto inanimado, no puedes echarle la culpa...', '', 28153),
(137905, 'esMX', 'Bueno, puedes venir... ¡pero no hagas ruido! Es un peregrinaje, no una fiesta.', '', 28153),
(137903, 'esMX', '', 'Fascinante... pero tenemo\' trabajo que hacer. Con esto quedan dos loa. Debemos acompañar a los tortollano\' en su peregrinaje hacia Torga, el loa tortuga.', 28153),
(137902, 'esMX', '', 'Dices que conseguiste la ayuda de Bwonsamdi... ¡¿y MATASTE a Hir\'eek?!', 28153),
(137901, 'esMX', '¡Oh, eso es fácil! Mi confiable lonchera. Nunca me cayó mal una cena de esa lonchera. La extraño mucho.', '', 28153),
(137900, 'esMX', '', '¡Al fin libre!', 28153),
(137899, 'esMX', '¡La Maestra condenará tu alma!', '', 28153),
(137898, 'esMX', '(Habla con Talanji sobre la posibilidad de obtener la ayuda de Bwonsamdi y la idea de matar a Hi\'reek.)', '(Habla con Talanji sobre la posibilidad de obtener la ayuda de Bwonsamdi y la idea de matar a Hi\'reek.)', 28153),
(137897, 'esMX', '¡La Maestra usará tu alma!', '', 28153),
(137896, 'esMX', '¡Muere y alimenta su gloria!', '', 28153),
(137895, 'esMX', '¡Muere! ¡Por la Maestra!', '', 28153),
(137894, 'esMX', '', 'Debe\' irte ahora. Pronto me transformaré y no quiero que vea\' en qué me convierto...', 28153),
(137893, 'esMX', 'Me llamo Bill. Si tienes algo que necesita reparaciones, soy el indicado.', '', 28153),
(137892, 'esMX', '', 'Ya e\' muy tarde para mí... Pero aún hay esperanza para los demás.', 28153),
(137891, 'esMX', '¡Saludos, $gviajero:viajera;! ¿Tú también has llegado aquí a merced de las mareas?$B$BSé que no es mucho, pero eres más que $gbienvenido:bienvenida; en nuestro humilde campamento durante todo el tiempo que quieras.', '', 28153),
(137890, 'esMX', 'Busca a los iniciados perdido\' en el desierto. Estaré aquí esperándote.', '', 28153),
(137889, 'esMX', '¿Cuál es el objeto más preciado que perdiste en el naufragio?', '¿Cuál es el objeto más preciado que perdiste en el naufragio?', 28153),
(137888, 'esMX', '¿Tienes algo para comer?', '', 28153),
(137887, 'esMX', '', 'Oh, esto no es bueno. Para nada. ¡Salgan todos de la carreta, rápido!', 28153),
(137886, 'esMX', '', '¡Son tropa\' de Jakra\'zet!', 28153),
(137885, 'esMX', '', 'No creo que esos trols sean tus amigos.', 28153),
(137869, 'esMX', '¡Idiota! ¡Debih\'te escapar mientra\' podías! ¡El poder de Akunda será mío!', '', 28153),
(137860, 'esMX', '', '¡Dolly! ¡Dot! ¡Esperen! ¡Ese lugar no es seguro!', 28153),
(137857, 'esMX', 'Miren nada más... ¡Regresah\'te con vida, $n!', '', 28153),
(137851, 'esMX', '¡Por la gloria del imperio sethrak!', '¡Por la gloria del imperio sethrak!', 28153),
(137810, 'esMX', '¡Auch! Creo que me rompí la pierna.', '', 28153),
(137807, 'esMX', 'Hagámoslo.', 'Hagámoslo.', 28153),
(137806, 'esMX', 'El ritual está en marcha. Hir\'eek aparecerá en cualquier momento. ¿Estás $Glisto:lista;?', '', 28153),
(137805, 'esMX', 'Reúnete conmigo en el círculo ritual.', '', 28153),
(137789, 'esMX', 'Ten cuidado, $c.', 'Ten cuidado, $c.', 28153),
(137788, 'esMX', '<Unos lazos mágicos han inmovilizado el cuerpo del loa.>', '', 28153),
(137787, 'esMX', 'Te doy la bienvenida a mi templo. Por tus valientes hazañas, siempre te recibiremos con hospitalidad aquí.', '', 28153),
(137785, 'esMX', '', 'Gracias a los do\'. Su lealtad significa mucho para mí... y todos los zandalari.', 28153),
(137784, 'esMX', '', 'Seguramente puedo convencer a los demás tortollanos que siguen en Nazmir para que nos ayuden. ¡Tal vez Shoak y Kajosh también vengan!', 28153),
(137783, 'esMX', 'Bueno, está bien. Pelearemos a tu lado contra este dios de la sangre, princesa. ¡Pero deja de molestarme!', '', 28153),
(137782, 'esMX', '', 'Cuida bien de ese loa, Lashk. $n y yo tenemo\' que buh\'car más ayuda.', 28153),
(137781, 'esMX', '¡Ja! Esa tortuga vieja y astuta... No estaba lista para descansar. ¡Quería reencarnar!', '', 28153),
(137780, 'esMX', '', 'En el nombre de...', 28153),
(137779, 'esMX', '', 'No descansaré hah\'ta que G\'huun y los trols de sangre no sean má\' que un recuerdo. Te lo juro, Torga.', 28153),
(137778, 'esMX', '', 'Y yo me aseguraré de que todo nuestro pueblo sepa de tu valentía contra G\'huun.', 28153),
(137777, 'esMX', 'Adiós, Torga. Recordaré las historias que me contaste... y las compartiré con los demás.', '', 28153),
(137776, 'esMX', '', 'Ere\' fuerte, pero no podrás hacer nada contra los podere\' que controlo.', 28153),
(137764, 'esMX', '', 'En efecto. Regresemos al santuario.', 28153),
(137763, 'esMX', '¡Fiu! Me vendría bien un descanso.', '', 28153),
(137762, 'esMX', '', 'Jaja... sorprendente. ¡De verdad lo hicimos!', 28153),
(137758, 'esMX', '', 'El adalid de la Horda y yo... vendremos por ti... ¡y te destrozaremos en mil pedazos!', 28153),
(137757, 'esMX', '', 'Esto termina... ¡ahora! Mi pueblo ya no vivirá... con temor a ti... ¡y a tu\' trols de sangre!', 28153),
(137755, 'esMX', 'Esto... no prueba... ¡NADA! Él... encontrará... otro conducto. Los sellos... se romperán... G\'huun... será... ¡libre!', '', 28153),
(137754, 'esMX', '¡Rápido! ¡Mátalo antes de que se dé cuenta de que yo soy la verdadera amenaza!', '', 28153),
(137753, 'esMX', '¡Enfréntate a mi fiel ballesta, ser maligno!', '', 28153),
(137752, 'esMX', '¡Quédate quieto! ¡No puedo acertarle un disparo si no deja de moverse!}', '', 28153),
(137751, 'esMX', '', '¿Qué hace\'? ¡Guardia\', a mí!', 28153),
(137750, 'esMX', '¡GRAAAGH! ¡No son NADA contra G\'huun! ¡Sufran y MUERAN!', '', 28153),
(137749, 'esMX', '', '¡POR TORGA!', 28153),
(137748, 'esMX', '', '¡Todos! ¡AHORA!', 28153),
(137747, 'esMX', 'Tus esfuerzos... son inútiles... Soy... into... ¿Qué? No. ¡NO!', '', 28153),
(137746, 'esMX', '', '¡Tu exceso de confianza será tu fin! ¡Tu poder no puede protegerte!', 28153),
(137745, 'esMX', 'Tus esfuerzos... son en vano. Soy... intocable.', '', 28153),
(137744, 'esMX', '', '¡Espera a que los demás conozcan la historia de cómo matamos al heraldo de G\'huun!', 28153),
(137743, 'esMX', 'Hace muchos años que no siento una pasión semejante. ¡Por Torga!', '', 28153),
(137742, 'esMX', '', 'Comencemos. Por Zandalar... ¡y por Torga!', 28153),
(137736, 'esMX', '', 'Gran Hir\'eek, ¡te ofrecemos un sacrificio de sangre y carne!', 28153),
(137734, 'esMX', 'Sí, sí. ¡Ya vamos!', '', 28153),
(137733, 'esMX', '', '¡Vamos! ¡Debemo\' estar preparados para deh\'truir al heraldo del dio\' de la sangre!', 28153),
(137732, 'esMX', 'Ten cuidado con las araña\', mi pequeño sáurido. Quizá yo sea el dios de los secreto\', pero Yazma es la dama de los espía\'. Le encanta que sus plagas huidiza\' espíen dentro de mis dominios y cacen a mis criatura\'.', '', 28153),
(137731, 'esMX', 'Estoy listo para entrar.', 'Estoy lista para entrar.', 28153),
(137730, 'esMX', '', 'Jamás creí que pisaría estas ruinas. ¿No son fascinantes?', 28153),
(137728, 'esMX', '¿Ahora no ere\' tan grande ni tan fuerte, eh? Vamos, esbirro. Encuentra a esa rata de Nokano que te dijo que mataras a los mío\'. Muérdelo y adopta tu forma real otra vez.', '', 28153),
(137721, 'esMX', '', 'Esta podría ser la mejor historia que haya vivido un tortollano. ¡Vengar la muerte de un loa y matar al avatar de un monstruo!', 28153),
(137720, 'esMX', '¿Sabes? Creo que es posible que matemos al heraldo de G\'huun.', '', 28153),
(137719, 'esMX', '', 'Será mejor que nos adelantemo\' y veamos qué hacen los trols de sangre.', 28153),
(137718, 'esMX', '', 'Nuestro trabajo aquí terminó, continental. Nos veremos en Alto de Arom.', 28153),
(137716, 'esMX', '', 'La bruja fue demasiado fuerte para mí y quedé atrapada.', 28153),
(137715, 'esMX', '', 'Gracias por liberarme de ese ensamblaje maldito.', 28153),
(137710, 'esMX', '', '¡Bien! Hora de moverse. Recuerden, ¡no hagan ruido! Lo último que necesitamo\' es que los atrapen.', 28153),
(137709, 'esMX', 'Por supuesto. ¡Tengo pergaminos más viejos que tú! Kisha, fíjate entre mis cosas.', '', 28153),
(137708, 'esMX', '', 'Necesitamo\' averiguar qué más traman eh\'tos trols de sangre. Lashk, Kisha, ¿tienen algo que pueda ayudarno\' a... ocultar nueh\'tro plan?', 28153),
(137707, 'esMX', '', 'Al final, fueron nuestros eruditos quienes cambiaron el curso de...', 28153),
(137706, 'esMX', 'Ya estoy grande para esto.', '', 28153),
(137705, 'esMX', '¡Magia de sangre! ¿Quién sería capaz de practicarla?', '', 28153),
(137704, 'esMX', 'Les contaré relatos sobre esto a los demás.', '', 28153),
(137703, 'esMX', 'Primero matan a Torga, ¡y ahora nos matan a nosotros! ¿Qué les sucede a estos trols?', '', 28153),
(137702, 'esMX', '¡También me han robado todos los pergaminos! Recupéralos, por favor.', '', 28153),
(137701, 'esMX', '¡Finalmente, mi suerte ha empezado a cambiar!', '', 28153),
(137700, 'esMX', '', '¡No impedirás que devoremo\' a los tortollanos!', 28153),
(137699, 'esMX', '', 'No comemo\' loa... ¡pero comemo\' tortollanos!', 28153),
(137697, 'esMX', '', '¡Kachago!', 28153),
(137696, 'esMX', 'No creas las mentiras de este vendedor de podredumbre fanfarrón.\n\nMe vendió muchísimos manuscritos, y todos terminaron siendo mentiras absurdas.\n\nSi piensa que me iré antes de que me reembolse mi dinero, se llevará una gran sorpresa. Después de todo, los trols no viven \"tanto\" tiempo.', '', 28153),
(137695, 'esMX', 'No me iré de aquí hasta no recibir un reembolso.', '', 28153),
(137694, 'esMX', 'Tu prosa es confusa y pobre.', '', 28153),
(137693, 'esMX', 'Tus libros hablan de lugares que no existen.', '', 28153),
(137692, 'esMX', 'Que la suerte los acompañe, mortales. Y... gracias.', '', 28153),
(137691, 'esMX', 'Vendes mentiras, Tella.', '', 28153),
(137690, 'esMX', 'Destruye los campamentos que rodean mi cadáver para debilitar a Jungo.', '', 28153),
(137689, 'esMX', 'Princesa Talanji. Los trols de sangre potencian a Jungo con mis restos.', '', 28153),
(137678, 'esMX', '', 'Necesitamo\' tu conocimiento, gran Torga. Dinos cómo podemos detener a eh\'tos trols de sangre.', 28153),
(137677, 'esMX', 'Aquí estoy. ¿Qué buscas?', '', 28153),
(137676, 'esMX', '¡Torga! Eh\'tán buscando tu espíritu. ¡Saca la cabeza de tu caparazón!', '', 28153),
(137675, 'esMX', '', '¡Guzincha!', 28153),
(137674, 'esMX', 'Rgggh...', '', 28153),
(137673, 'esMX', '¡Graaaagh!', '', 28153),
(137672, 'esMX', '', '¡No puede\' ocultarte del dios de la sangre!', 28153),
(137671, 'esMX', '\"Cabra tonta. Larguémonos de aquí antes de que te conviertas en la cena de los monstruos\".', '\"Cabra tonta. Larguémonos de aquí antes de que te conviertas en la cena de los monstruos\".', 28153),
(137670, 'esMX', '', '¡Tu sangre para G\'huun!', 28153),
(137669, 'esMX', '\"Hola, Mazapán. ¡Pareces perdida! Ven, acompáñame y te llevaré hasta tu hogar, ¿sí?\"', '\"Hola, Mazapán. ¡Pareces perdida! Ven, acompáñame y te llevaré hasta tu hogar, ¿sí?\"', 28153),
(137668, 'esMX', '', '¡Tus huesos nos servirán!', 28153),
(137667, 'esMX', '', '¡Quiero tu sangre!', 28153),
(137666, 'esMX', '', '¡Carne fresca!', 28153),
(137665, 'esMX', '', '¡Zuldazar caerá!', 28153),
(137664, 'esMX', 'No eh\'toy aquí para defenderte a ti ni a los mercadere\'. No. Mi trabajo es luchar contra las pesadilla\' que pueden llegar deh\'de el Norte. Trols de sangre, viperinos, Alianza, lo que sea.\n\nTambién tengo que luchar contra el aburrimiento, pero más que nada contra todos ello\'. ¿Qué buscas aquí?', 'No eh\'toy aquí para defenderte a ti ni a los mercadere\'. No. Mi trabajo es luchar contra las pesadilla\' que pueden llegar deh\'de el Norte. Trols de sangre, viperinos, Alianza, lo que sea.\n\nTambién tengo que luchar contra el aburrimiento, pero más que nada contra todos ello\'. ¿Qué buscas aquí?', 28153),
(137663, 'esMX', '<La pequeña cabra parece estar perdida.\n\nTiene un collar que dice \"Mazapán\".>', '', 28153),
(137662, 'esMX', '', '¡Sangre! ¡Sangre! ¡Sangre!', 28153),
(137661, 'esMX', 'He oído que tú ere\' quien trajo a la princesa Talanji. Déjame decirte que te has ganado mi agradecimiento.\n\nPero también dicen que ere\' el que trajo a Zul. Déjame decirte que te has ganado mi ira.\n\n¿Qué necesitas?', 'He oído que tú ere\' quien trajo a la princesa Talanji. Déjame decirte que te has ganado mi agradecimiento.\n\nPero también dicen que ere\' el que trajo a Zul. Déjame decirte que te has ganado mi ira.\n\n¿Qué necesitas?', 28153),
(137660, 'esMX', '¿Me tomas por uno de tus mercadere\'? ¡Soy guerrero! De la casta más alta, colega.\n\n¿Qué necesitas?', '¿Me tomas por uno de tus mercadere\'? ¡Soy guerrera! De la casta más alta, colega.\n\n¿Qué necesitas?', 28153),
(137659, 'esMX', '¿Tienes algo que necesites? Si no, sigue tu camino.', '¿Tienes algo que necesites? Si no, sigue tu camino.', 28153),
(137658, 'esMX', 'No llevas ningún vudú de lo\' trols de sangre contigo, ¿verdad? ¿No? Bien.\n\n¿Qué te trae por aquí?', 'No llevas ningún vudú de lo\' trols de sangre contigo, ¿verdad? ¿No? Bien.\n\n¿Qué te trae por aquí?', 28153),
(137657, 'esMX', 'Dicen que los trols de sangre se meterán en nueh\'tra sociedad. Si no pueden invadirno\', comenzarán a convertirno\'.\n\nSeguramente hagan las dos cosa\', pero no importa. ¿Qué necesitas?', 'Dicen que los trols de sangre se meterán en nueh\'tra sociedad. Si no pueden invadirno\', comenzarán a convertirno\'.\n\nSeguramente hagan las dos cosa\', pero no importa. ¿Qué necesitas?', 28153),
(137656, 'esMX', 'Mi primo está en las Puertas de Sangre luchando de verdad. ¿Yo? A mí me asignaron a cuidar a los sáurido\'. Bah.\n\nBien, ¿qué necesitas?', 'Mi primo está en las Puertas de Sangre luchando de verdad. ¿Yo? A mí me asignaron a cuidar a los sáurido\'. Bah.\n\nBien, ¿qué necesitas?', 28153),
(137655, 'esMX', 'Bwonsamdi, estamos listos para que invoques al espíritu de Torga.', 'Bwonsamdi, estamos listos para que invoques al espíritu de Torga.', 28153),
(137654, 'esMX', '\"Ve a Nazmir\", decían. ¡\"Oye las historias de Torga, será divertido\", decían!', '', 28153),
(137652, 'esMX', 'El cadáver de este loa... me alimenta. Alimenta... a G\'huun.', '', 28153),
(137651, 'esMX', 'Hablo... por G\'huun. Él... guiará. Ustedes… servirán... o morirán.', '', 28153),
(137643, 'esMX', 'Me encantaría oír sus grito\', pero será mejor que mantengas un perfil bajo. No queremo\' que te atrapen a ti también.', '', 28153),
(137642, 'esMX', '¡Ah! ¡Libertad!', '', 28153),
(137641, 'esMX', '¡Ah, y si alguna vez ves a un trol llamado Sur\'jan, apuñálalo en el corazón con mi garra! ¡Se lo merece!', '', 28153),
(137640, 'esMX', '¡Gracia\' por todo, colega!', '', 28153),
(137639, 'esMX', '', 'Ahora que podemo\' volar gracias al engendro de Hir\'eek y contamo\' con el poder del dios de la sangre, ¡los zandalari caerán!', 28153),
(137638, 'esMX', 'Graciah\' por encargarte de los preparativo\', $p. Cuando salgas, ¿podrías decirle a Kreepi que me envíe un poco de agua?', '', 28153),
(137637, 'esMX', '¡Ten cuidado! Lo\' antárboles se pusieron rabiosos y están matando a cualquiera que se les acerque.', '', 28153),
(137620, 'esMX', 'El tamaño no importa. Tu espíritu es el más grande que encontré en estas colinas.', '', 28153),
(137619, 'esMX', '', '¡Gracias, Sumber! Quiero aprender todo lo que puedas enseñarle a una pequeña vulpera como yo.', 28153),
(137618, 'esMX', 'Imbuí una parte de mi poder en este tótem para ti. Úsalo bien.', '', 28153),
(137616, 'esMX', '', 'De nada, Sumber. Mi amig$go:a; y yo estamos felices de ayudarte como podamos.', 28153),
(137615, 'esMX', 'Estoy impresionado. Hiciste bien en traerme esta esencia.', '', 28153),
(137614, 'esMX', '', '¡Ah! El agua se mueve muy rápido. ¡No puedo controlarla!', 28153),
(137610, 'esMX', '', 'Busca los charcos de agua grandes. No hay muchos en Vol\'dun. No deberías tener problemas para encontrarlos.', 28153),
(137609, 'esMX', '', 'Que sea bien llamativo, si puedes. Hay que impresionar mucho a Sumber.', 28153),
(137608, 'esMX', '', 'Pase lo que pase ahí abajo, tú solo toma el agua y vete. No te metas.', 28153),
(137607, 'esMX', 'Por aquí abajo rondan entidades poderosas, $p. Que la sabiduría guíe tus golpes y tus decisiones.', '', 28153),
(137606, 'esMX', 'Gloria y honor para ti, $p.', '', 28153),
(137605, 'esMX', '', 'Una jornada de trabajo merece su pago, sin importar quién seas.', 28153),
(137604, 'esMX', 'Un verdadero vencedor del mal como $p no lucha contra monstruos por dinero, Maiya. ¡Nosotros luchamos por la gloria!', '', 28153),
(137603, 'esMX', '', 'Todo puede arreglarse si uno se lo propone, Heiro.', 28153),
(137602, 'esMX', '¿Estás segura de que podemos arreglar esta carreta? Los ranishu la devoraron casi toda.', '', 28153),
(137601, 'esMX', 'Y ahora viene lo mejor. ¡Matar y matar, para conseguirme más almas!', '', 28153),
(137597, 'esMX', 'Siento el fuego en tu interior, Talanji. Aún así, mi ayuda tiene un precio.', '', 28153),
(137594, 'esMX', '', 'No jugaremo\' este juego, Bwonsamdi. ¿Quieres el espíritu de un loa? Ya asesinaron a Hir\'eek. Ve y busca ese espíritu.', 28153),
(137590, 'esMX', 'Ja... ¿Qué dicen si... hacemo\' un trato, mm? Tráiganme el alma de otro loa, y les permitiré hablar con el espíritu de Torga.', '', 28153),
(137588, 'esMX', 'Déjenme adivinar... Mmm... Quieren hablar con el alma del pobre Torga.', '', 28153),
(137587, 'esMX', 'Estoy listo para tratar de invocar a Bwonsamdi.', 'Estoy lista para tratar de invocar a Bwonsamdi.', 28153),
(137586, 'esMX', 'Y hablar no funciona. Debemos encontrar otra forma de detenerloh\'. O por lo menos huir, como hiciste tú.', '', 28153),
(137585, 'esMX', 'Informaré a Kreepi y a lo\' demás. Los ranishu comen carne de $pr... y todo lo demás.', '', 28153),
(137584, 'esMX', '¡Jaja, miren cómo se mueven esos pie\' de $pr! ¡No te tropieces!', '', 28153),
(137583, 'esMX', '¡Ñami-Ñami grande! ¡Comer máscara! ¡Todos comer $pr!', '', 28153),
(137582, 'esMX', '', 'Los trols de sangre desearán no haberse cruzado nunca con nosotros.', 28153),
(137581, 'esMX', '<Tira de la antorcha>', '<Tira de la antorcha>', 28153),
(137580, 'esMX', '<Cuando la inspeccionas más de cerca, adviertes que la antorcha parece estar conectada a un mecanismo extraño que está incrustado en la pared.>', '', 28153),
(137579, 'esMX', '<Solo un par de botas viejas.\n\n¿Qué esperabas?>', '', 28153),
(137578, 'esMX', '<No encuentras ninguna entrada secreta debajo de la alfombra\n\nPero qué bien que combina con la habitación.>', '', 28153),
(137577, 'esMX', '<Sorpresivamente, el libro que sobresale no es un mecanismo secreto para abrir la entrada secreta.>', '', 28153),
(137576, 'esMX', '<El ancla está agarrada con fuerza a la pared.>', '', 28153),
(137575, 'esMX', '', 'Te diré quién... Los trols de sangre. Sígueme... ¡Los haremo\' pagar!', 28153),
(137574, 'esMX', '', '¿Quién le haría esto a Torga? ¡Él solo quería contar sus historias!', 28153),
(137573, 'esMX', '¡Torga! ¡NO!', '', 28153),
(137572, 'esMX', '¡Mataron a Torga como si fuera un simple animal!', '', 28153),
(137571, 'esMX', 'Las historias de Torga... ¡desaparecerán para siempre!', '', 28153),
(137570, 'esMX', 'Un loa... ¿muerto?', '', 28153),
(137569, 'esMX', '¿Cómo pudo suceder esto?', '', 28153),
(137568, 'esMX', '', 'Mantuvieron ese conocimiento oculto aquí, a salvo de manos indebidas.', 28153),
(137563, 'esMX', 'Estoy buscando trabajo.', 'Estoy buscando trabajo.', 28153),
(137561, 'esMX', '', '¡Ja! ¿Qué crees que soy, una guía de turismo? Yo solo vine a escuchar las historias de Torga.', 28153),
(137560, 'esMX', '', 'Creo que será mejor que me marche antes de que venga alguien más a pedir indicaciones.', 28153),
(137559, 'esMX', '', 'Mira, sigue este camino, no te desvíes, y encontrarás a Torga. Es una tortuga gigante... es imposible no verla.', 28153),
(137558, 'esMX', '', '¡Bah! ¡Qué te importa lo que haga! No critiques mi forma de peregrinar.', 28153),
(137557, 'esMX', '¿Una \"peregrinación\"? ¡Pero si estás ahí parado sin hacer nada! Lashk dijo que tú sabías dónde está Torga.', '¿Una \"peregrinación\"? ¡Pero si estás ahí parado sin hacer nada! Lashk dijo que tú sabías dónde está Torga.', 28153),
(137556, 'esMX', 'Lashk me dijo que tú podrías indicarme dónde encontrar a Torga.', 'Lashk me dijo que tú podrías indicarme dónde encontrar a Torga.', 28153),
(137555, 'esMX', '¿Qué quieres? ¿No ves que estoy en medio de una peregrinación?', '', 28153),
(137554, 'esMX', 'Bien, creo que nos llevaremos bien, princesa.', '', 28153),
(137553, 'esMX', '', 'No es la primera vez que tengo que lidiar con uh\'tedes, viejos tortollanos... y sus hih\'torias interminables. ¡Concéntrense y caminen!', 28153),
(137552, 'esMX', 'Bueno, vayamos a ver a Torga. Pero recuerda no hacer ruido. ¡No quiero perderme ninguna de sus historias!', '', 28153),
(137551, 'esMX', 'Ah... Sí, bueno, no vamos a unirnos a ninguna causa, pero no les prohibiremos acompañarnos.', '', 28153),
(137550, 'esMX', '¿Qué quieres?', '', 28153),
(137549, 'esMX', 'Quizá te convendría reconsiderar tu reh\'puesta.', '', 28153),
(137548, 'esMX', 'Solo conozco a Akunda.', '', 28153),
(137547, 'esMX', 'Te pregunto tu nombre, ¿y me cuentas historiah\'?', '', 28153),
(137546, 'esMX', '¿Alamuerte? ¿Qué clase de criatura inerme llevaría un nombre como ese?', '', 28153),
(137545, 'esMX', 'You will be granted access to this loa\'s buff. This system is a WIP.', 'You will be granted access to this loa\'s buff. This system is a WIP.', 28153),
(137544, 'esMX', 'Me encargaré de inmediato.', 'Me encargaré de inmediato.', 28153),
(137543, 'esMX', '', 'La flora de este barranco pelea por sobrevivir, como el resto de nosotros.', 28153),
(137542, 'esMX', 'No tengo palabras para agradecerte, continental. Me iré lo más lejos que pueda de este lugar.', 'No tengo palabras para agradecerte, continental. Me iré lo más lejos que pueda de este lugar.', 28153),
(137541, 'esMX', '', '¡Hola! ¿Te gusta el fuego? ¿Los cohetes? ¿Y qué me dices de los cohetes prendidos fuego? ¡Tengo tantas cosas increíbles para mostrarte que no veo la hora!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137540, 'esMX', '¡Santo cielo! ¡¿Qué era esa... esa cosa?!', '¡Santo cielo! ¡¿Qué era esa... esa cosa?!', 28153),
(137537, 'esMX', '', 'Sí, claro. Pero no creo que quieras atravesar el cañón. Está repleto de pesadillas.', 28153),
(137536, 'esMX', '', 'Sujétate si puedes. ¡Será un viaje movido!', 28153),
(137535, 'esMX', 'Tiene que haber otro camino...', '', 28153),
(137534, 'esMX', '', 'Bien, vamos al sur. Pero debes saber que las montañas están malditas. Los que entran nunca salen.', 28153),
(137533, 'esMX', 'Eh\'te debe ser el lugar. Veo la estructura adelante.', '', 28153),
(137531, 'esMX', 'Deberíamos dirigirno\' al sur. El templo se encuentra en algún lugar de esas colina\'.', '', 28153),
(137530, 'esMX', 'Mis aposentos son rústicos pero cómodos, te lo garantizo.', '', 28153),
(137529, 'esMX', 'Akunda nos ha dado la oportunidad de abandonar nueh\'tro pasado y volver a empezar.', '', 28153),
(137528, 'esMX', '', 'Hay que erradicar a la Horda. ¡Zuldazar se inclinará ante la Alianza!', 28153),
(137526, 'esMX', 'Bah. Este lugar no está tan mal. Estamos en un peregrinaje. Y presiento que ustedes van a hacerlo más difícil.', '', 28153),
(137525, 'esMX', '', '¡Tortollanos! ¿Qué los trae a eh\'te lugar maldito?', 28153),
(137523, 'esMX', 'Quizá no te agrade la reh\'puesta a esa pregunta, $n. No te equivoque\'. Merezco la sentencia a las arenas.', '', 28153),
(137517, 'esMX', '¿Qué hiciste para terminar aquí?', '¿Qué hiciste para terminar aquí?', 28153),
(137516, 'esMX', 'No me parece nada mal tener la oportunidad de dejar atrás mi pasado y volver a empezar. Quizá esto\' trols no están tan locos deh\'pués de todo.', '', 28153),
(137515, 'esMX', 'Le debo mi vida a Rakera. Los exiliados no habríamo\' sobrevivido en las arena\' sin su guía.', '', 28153),
(137509, 'esMX', '¡Eh\'tá bien, tómalo! ¡Pero déjame ir!', '', 28153),
(137508, 'esMX', 'Rupert, ¡baila!', '', 28153),
(137505, 'esMX', 'He vih\'to a la que buscas. Superó las pruebas fácilmente, pero no parecía interesada en quedarse mucho tiempo. \n\nEh\'taba buscando algo. Hacía preguntas, igual que tú, pero se marchó tan rápido como llegó. Deberías ir al sur, como ella.\n\nEste templo no es seguro.', '', 28153),
(137504, 'esMX', '', 'Todoh\' somos Akunda.', 28153),
(137502, 'esMX', '¡Rupert, ven aquí!', '', 28153),
(137501, 'esMX', '¿Has visto a la guardiana bélica Rakera?', '¿Has visto a la guardiana bélica Rakera?', 28153),
(137500, 'esMX', 'Akunda nos da fortaleza.', 'Akunda nos da fortaleza.', 28153),
(137499, 'esMX', 'Sin Akunda, no somoh\' nada.', 'Sin Akunda, no somo\' nada.', 28153),
(137498, 'esMX', 'Akunda comparte su poder.', 'Akunda comparte su poder.', 28153),
(137497, 'esMX', 'Todos somo\' Akunda.', 'Todoh\' somos Akunda.', 28153),
(137496, 'esMX', 'Ella no e\' Akunda.', '', 28153),
(137495, 'esMX', '', 'Si ella no e\' Akunda, tiene la entrada prohibida.', 28153),
(137494, 'esMX', 'Solo Akunda puede caminar dentro de eh\'te templo.', '', 28153),
(137493, 'esMX', 'Aquí no vive nadie con ese nombre.', '', 28153),
(137492, 'esMX', '', 'Solo tengo ojos para quieneh\' son dignos del poder de Akunda.', 28153),
(137491, 'esMX', '¿Por qué te preocupah\' por los que no son Akunda?', '', 28153),
(137490, 'esMX', '', '¿Rakera? Que nombre máh\' raro.', 28153),
(137489, 'esMX', '¡Jugoso por dentro! ¡Ñam! ¡Ñam!', '', 28153),
(137488, 'esMX', 'Baja la voz... no queremo\' que esos cultistas maniático\' sepan que estamo\' hablando así.', '', 28153),
(137487, 'esMX', '¿Quieres ser uno con Akunda, $gniño:niña;? Sírveme y te concederé tu deseo...', '', 28153),
(137486, 'esMX', '¡Ey, tú! No beba\' de ese cáliz.', '', 28153),
(137485, 'esMX', '¡Ñam! ¡Ñam! ¡Ñam!', '', 28153),
(137484, 'esMX', '¿No me oíh\'te la primera vez? Si bebes de ese cáliz, te arrepentirá\'.', '', 28153),
(137483, 'esMX', 'Salja pasa el tiempo durmiendo en la torre norte. Una gota de mi veneno y nunca volverá a deh\'pertarse. ¡Asegúrate de traer de vuelta la llave!', '', 28153),
(137482, 'esMX', '', '¿Ya nos conocíamos? Te veo familiar...', 28153),
(137480, 'esMX', 'Cuando salga de aquí, ¡te haré pagar!', '', 28153),
(137479, 'esMX', 'Déjame salir, ¡o juro que te arrepentirás!', '', 28153),
(137478, 'esMX', '¡Sácame de esta jaula ante\' de que te muestre lo que es una verdadera pesadilla!', '', 28153),
(137477, 'esMX', 'Jamáh\' había visto algo así... La carne no hizo más que avivar el hambre de los ranishu. ¡El viejo Bajoleño no tenía ninguna oportunidad!', '', 28153),
(137476, 'esMX', '¡Ja! Me hacen cosquillas... ¡Auch! ¡Me dolió! ¡Basta!', '', 28153),
(137475, 'esMX', '¡NO les concedo permiso para devorarme, criaturas viles!', '', 28153),
(137472, 'esMX', '<Los ojos del viejo Bajoleño se ven fríos, como si no tuvieran vida.>', '', 28153),
(137466, 'esMX', 'Busca a la Devoradora Ni-Ni en el norte. Eh\'tá rodeada de insectos enormes y cosas muertas. ¡Aplástala para robar su máscara!', '', 28153),
(137465, 'esMX', '', '¡La sangre de Torga alimenta nuestro poder!', 28153),
(137464, 'esMX', '', '¡Sangre de Torga es nuestra ahora!', 28153),
(137463, 'esMX', 'Ah, ya no siento la comezón. La soledad es tan placentera.', '', 28153),
(137462, 'esMX', 'Ignora a $gese sucio cazador:esa sucia cazadora;, Rupert. Tú serás el compañero perfecto.', '', 28153),
(137461, 'esMX', 'Eso es un oso. Mira, deshazte de él antes de que lo vea alguno de los Holton.', 'Eso es un oso. Mira, deshazte de él antes de que lo vea alguno de los Holton.', 28153),
(137460, 'esMX', 'Qué tonto, rescaté a este pobre perrito cuando estaba cazando. Decidí enseñarle algunos trucos.', '', 28153),
(137459, 'esMX', '¡¿E-Eso es un oso?!', '¡¿E-Eso es un oso?!', 28153),
(137458, 'esMX', 'Rupert, $geste:esta: amable $c nos trajo un regalo. ¡Muéstrale tu aprecio! ¡Baila!', '', 28153),
(137457, 'esMX', 'Te doy la bienvenida, Akunda $Uel Valiente:la Valiente;.', '', 28153),
(137456, 'esMX', 'Te doy la bienvenida, Akunda $Uel Sereno:la Serena;.', '', 28153),
(137455, 'esMX', 'Te doy la bienvenida, Akunda $Uel Ligero:la Ligera;.', '', 28153),
(137454, 'esMX', 'Destruí a Alamuerte. Seguramente has oído hablar de mí.', 'Destruí a Alamuerte. Seguramente has oído hablar de mí.', 28153),
(137453, 'esMX', '¿Acaso no te llegaron los relatos sobre mi victoria contra el Rey Exánime?', '¿Acaso no te llegaron los relatos sobre mi victoria contra el Rey Exánime?', 28153),
(137452, 'esMX', 'Vencí a la Legión Ardiente. ¿Hablas en serio? ¿Realmente no sabes quién soy?', 'Vencí a la Legión Ardiente. ¿Hablas en serio? ¿Realmente no sabes quién soy?', 28153),
(137451, 'esMX', '¡Quítenseme de encima, plagas cobardes! ¡Vayan a devorar su tan ansiada carne y dejen en paz a estos árboles!', '', 28153),
(137450, 'esMX', 'Mi nombre e\' Akunda el Ligero.', 'Mi nombre e\' Akunda la Ligera.', 28153),
(137449, 'esMX', 'Mi nombre e\' Akunda el Sereno.', 'Mi nombre e\' Akunda la Serena.', 28153),
(137448, 'esMX', 'Mi nombre e\' Akunda el Valiente.', 'Mi nombre e\' Akunda la Valiente.', 28153),
(137447, 'esMX', 'Mi nombre sigue siendo el mismo.', 'Mi nombre sigue siendo el mismo.', 28153),
(137446, 'esMX', 'Has vivido una vida sin sentido hah\'ta ahora. \n\nDebes olvidar todo lo que has hecho y lo que has sido. \n\n¡Di tu verdadero nombre para que todo\' lo oigan!', '', 28153),
(137444, 'esMX', 'Muchos buscan refugio en nueh\'tro templo, pero solo se permite la entrada a los dignos.', '', 28153),
(137438, 'esMX', '¡Ja! ¡Juntos, acabaremos con esta bestia!', '', 28153),
(137437, 'esMX', '¡Colmilargo ataca con una fuerza renovada ahora que tiene aliados!', '', 28153),
(137436, 'esMX', 'Colmilargo aúlla triunfante en gesto de agradecimiento y finalmente se acuesta para descansar.', '', 28153),
(137435, 'esMX', 'Gracias. Ahora, puedo descansar.', '', 28153),
(137434, 'esMX', 'Te doy la bienvenida a mi arbolada, $p... o a lo que queda de ella.', '', 28153),
(137432, 'esMX', '¡No puedo soportarlo! ¡Ya no lo soporto más!', '', 28153),
(137431, 'esMX', '¡Olvídalo, compa! ¡Quizás Hir\'eek me dé a MÍ su poder si te sacrifico a TI!', '', 28153),
(137430, 'esMX', '¡Basta de ser usados para sacrificio\'! ¡Hermano\', es momento de levantarse!', '', 28153),
(137429, 'esMX', '¡Púdranse, tú y la Suma sacerdotisa!', '', 28153),
(137428, 'esMX', '¡No viviré como un animal!', '', 28153),
(137427, 'esMX', 'La Suma sacerdotisa exige que ofrezcas una muestra de tu sumisión.\n[Libera al esclavo.]', 'La Suma sacerdotisa exige que ofrezcas una muestra de tu sumisión.\n[Libera al esclavo.]', 28153),
(137426, 'esMX', '¡Tú traer comida o yo comerte!', '', 28153),
(137425, 'esMX', 'En Vol\'dun todo e\' siempre más difícil de lo que debería ser.\n\nSolo necesito un poco de madera para arreglar mi caravana.', '', 28153),
(137424, 'esMX', '', 'Ja, ja... Es demasiado tarde... El dio\' de la sangre... ¡está aquí!', 28153),
(137423, 'esMX', '', 'El heraldo se materializará nuevamente. ¡No podrás detenerno\'!', 28153),
(137422, 'esMX', 'Puede que esto le parezca gracioso a un $pr, pero los ranishu son una aflicción muy grave.\n\nAunque dan un poco de cosquillas, la verdad.', '', 28153),
(137421, 'esMX', '¡Nada nos detendrá! ¡Los hombre\' se rebelarán!', '', 28153),
(137420, 'esMX', 'Será mejor que cuides tus espaldas, colega. ¡Las mujere\' no regirán mucho tiempo más!', '', 28153),
(137419, 'esMX', 'Ya lo verás, colega. ¡Mis hermano\' y yo saldremo\' de este lugar y tendremo\' todo el poder!', '', 28153),
(137418, 'esMX', '¿Has venido a cah\'tigarme otra vez? ¡No huiré de ti!', '', 28153),
(137417, 'esMX', '¡La sangre de Torga alimenta nuestro poder!', '', 28153),
(137416, 'esMX', '¡Sangre de Torga es nuestra ahora!', '', 28153),
(137414, 'esMX', 'Nosotros llevamo\' carne de loa a los demás. ¡No nos detendrás!', '', 28153),
(137413, 'esMX', '¡La carne de loa nos pertenece! ¡Y la tuya también!', '', 28153),
(137412, 'esMX', '', 'Muy bien, creo que tenemos algunas brujas que matar.', 28153),
(137411, 'esMX', '', 'Y así renace la Orden de las Ascuas.', 28153),
(137410, 'esMX', '', 'Sus conocimientos les otorgarán a ti y a nuestras fuerzas la ventaja que necesitamos para destruir a este vil aquelarre que profana nuestra tierra.', 28153),
(137409, 'esMX', '', 'Si te dispones a emprender el camino de la Orden, toma el libro.', 28153),
(137408, 'esMX', '', 'Aquí está... La tumba de la Orden de las Ascuas. ¿Quieres revivir la historia antigua?', 28153),
(137407, 'esMX', '', '¡Vamos, el libro debería estar aquí dentro!', 28153),
(137406, 'esMX', '', 'Pero qué digo... Claro que estás bien. ¡Veo que se necesitará mucho más que unas piedras para derribarte!', 28153),
(137405, 'esMX', '', '¡Jamás había visto un ensamblaje tan grande! ¿Estás bien?', 28153),
(137404, 'esMX', '', 'Hir\'eek me... vengará...', 28153),
(137403, 'esMX', '', '¡Mi alma por G\'huun!', 28153),
(137402, 'esMX', '<Ayuda a Henry Arrecife y acaba con la disputa.>', '<Ayuda a Henry Arrecife y acaba con la disputa.>', 28153),
(137401, 'esMX', '', '¡La carne de loa nos pertenece!', 28153),
(137400, 'esMX', '', '¡$C, detrás de ti!', 28153),
(137399, 'esMX', '', 'Gloria... a... Hir\'eek...', 28153),
(137398, 'esMX', '', 'Nosotros arrancamos carne de loa, ¡nosotros COMEMOS carne de loa!', 28153),
(137397, 'esMX', '', 'Espera... Algo no anda bien.', 28153),
(137396, 'esMX', '', 'Mmm... Parece que algunos escombros nos bloquean el paso. ¿Puedes despejar el camino?', 28153),
(137395, 'esMX', '', 'Armados con ese conocimiento, nuestros hombres empezaron a expulsar a los drust y a devolverlos a sus fortalezas en la montaña.', 28153),
(137394, 'esMX', '', 'Compilaron sus descubrimientos en un tratado sobre las armas y las tácticas que podían utilizarse para derrotar a los bárbaros.', 28153),
(137393, 'esMX', '', 'Como decía, nuestros eruditos cambiaron el rumbo de la guerra cuando empezaron a descubrir ciertas falencias en la magia de los drust.', 28153),
(137392, 'esMX', '', 'Gracias, $c. Por un momento creí que me atraparía.', 28153),
(137391, 'esMX', '', 'Un momento... ¡Cuidado!', 28153),
(137390, 'esMX', '', 'Los Tarjasenda siempre fuimos vigorosos, pero la magia de los drust era fuerte. Estábamos perdiendo la guerra...', 28153),
(137389, 'esMX', '', 'Mis ancestros lucharon contra ensamblajes de piedra como estos en su guerra contra los drust.', 28153),
(137388, 'esMX', '', 'Lo siento, $c. La magia del aquelarre debe estar alterando a los espíritus de los drust antiguos. Debemos tener cuidado.', 28153),
(137387, 'esMX', '', '¡Cuidado!', 28153),
(137386, 'esMX', '', 'Un momento... ¿Qué fue eso?', 28153),
(137385, 'esMX', '', 'Esta situación se prolongó muchísimos años, hasta que los ancestros de la casa Tarjasenda decidieron que había que hacer algo para detenerlos.', 28153),
(137384, 'esMX', '', 'Drustvar fue su hogar ancestral. Desde aquí emprendían sus asaltos interminables hacia nuestras aldeas incipientes.', 28153),
(137383, 'esMX', '', 'Hace mucho tiempo, durante el primer asentamiento de Kul Tiras, nuestro pueblo se encontró con un grupo de bárbaros salvajes belicosos que se hacían llamar drust.', 28153),
(137382, 'esMX', '', '¡Eso es! ¡El camino se está abriendo!', 28153),
(137381, 'esMX', '', '¡Solo tenemos que encontrar la entrada!', 28153),
(137380, 'esMX', '', 'Contiene un secreto antiguo de nuestra casa, de cuando los Tarjasenda llegaron por primera vez a estas tierras.', 28153),
(137379, 'esMX', '', '¡No puedo creer que estemos aquí! Mi padre solía contarme historias de este lugar.', 28153),
(137378, 'esMX', '', '¡Arre! ¡Cabalga hacia Alto de Arom, Bella!', 28153),
(137377, 'esMX', '', 'Bella, necesito que sigas a esta persona y cargues con los suministros que encuentre, ¿sí?', 28153),
(137376, 'esMX', '<Ayuda a Colmilargo y acaba con la disputa.>', '<Ayuda a Colmilargo y acaba con la disputa.>', 28153),
(137375, 'esMX', '<El espíritu del cazador Henry Arrecife está demasiado concentrado en su combate eterno para advertir tu presencia.\n\nSe encuentra enzarzado en un combate contra el espíritu de la loba Colmilargo. Ninguno de los dos cederá: están atrapados en una situación sin salida, incluso en la muerte.>', '', 28153),
(137374, 'esMX', '<El espíritu de la poderosa loba Colmilargo sigue luchando aún después de morir.\n\nSe encuentra atrapada en un combate eterno contra el cazador Henry Arrecife.>', '', 28153),
(137296, 'esMX', '', '¡Má\' sangre para Hir\'eek!', 28153),
(137295, 'esMX', '', '¡Hora de recoger cabezas!', 28153),
(137294, 'esMX', '', '¡Morirás en este lugar!', 28153),
(137292, 'esMX', '', '¡Hir\'eek beberá tu sangre!', 28153),
(137290, 'esMX', '', '¡Mi murciélago se dará un festín contigo!', 28153),
(137289, 'esMX', '', '¡Alimentaré a Hir\'eek con tu carne!', 28153),
(137287, 'esMX', '', '¡El dio\' de la sangre me advirtió acerca de ti!', 28153),
(137284, 'esMX', '¿Intentan construir una fortaleza? ¡Ja! ¡No me hagan reír! ¡Ja, ja!', '', 28153),
(137282, 'esMX', '¡Envíen la artillería pesada! Haremos pedazos su base.', '', 28153),
(137281, 'esMX', '¡Vaya! ¡Parece que los tontos de la Horda finalmente decidieron mostrar sus asquerosas caras!', '', 28153),
(137280, 'esMX', 'Cada minuto que pasa me debilito. Debes... debes ayudarme antes de que sea tarde.', '', 28153),
(137279, 'esMX', '¡Tienes un talento natural, $gamigo mío:amiga mía;!', '', 28153),
(137278, 'esMX', 'Y por supuesto, mi parte favorita, ¡el salto! Salta las vallas para demostrar tu habilidad en la equitación. ¡Cuanto más saltes, más impresionante será el resto de tus acciones!', '', 28153),
(137277, 'esMX', 'Los Rabaleros ya te han presentado su herramienta favorita: ¡las boleadoras! Practica lanzarlas mientras cabalgas y trata de derribar a los zepelines voladores. ¡No son muy comunes, pero valen muchos puntos!', '', 28153),
(137276, 'esMX', 'La habilidad en combate es un requisito importante para los jinetes kultiranos. ¡Demuestra tus habilidades con el arpón con esos gnolls!', '', 28153),
(137275, 'esMX', '¿Será una combinación de los dos? ¿Un hombre-oso? ¿Un oso-hombre?', '', 28153),
(137274, 'esMX', 'Más heridas de oso. ¿Habrán sido un forajido y su oso mascota?', '', 28153),
(137271, 'esMX', 'O tal vez no es un oso. Parece que tuvo un encuentro desafortunado con un forajido, o algo así.', '', 28153),
(137270, 'esMX', 'Qué heridas más peculiares. Casi que me recuerdan a un oso. ¿Te parecen heridas de oso?', '', 28153),
(137269, 'esMX', 'Todo se convertirá... en desierto... ¡Incluso Nazmir...!', '', 28153),
(137268, 'esMX', '¡Nazmir le pertenece al imperio sethrak!', '', 28153),
(137267, 'esMX', 'Sobreviví a los trols de sangre. ¿Y esto es lo que recibo a cambio? ¡Bah!', 'Sobreviví a los trols de sangre. ¿Y esto es lo que recibo a cambio? ¡Bah!', 28153),
(137266, 'esMX', '¡Bah! Torga está muerto y yo me he quedado sin historias.', '¡Bah! Torga está muerto y yo me he quedado sin historias.', 28153),
(137265, 'esMX', '¿Pero qué...? Odio este lugar... ¡No pienso quedarme aquí!', '¿Pero qué...? Odio este lugar... ¡No pienso quedarme aquí!', 28153),
(137264, 'esMX', 'Torga... ¡¿está muerto?! ¿Qué fue todo esto?', 'Torga... ¡¿está muerto?! ¿Qué fue todo esto?', 28153),
(137263, 'esMX', '', '¿Qué clase de traición es eh\'ta? ¡Pondré tu cabeza en una pica!', 28153),
(137262, 'esMX', '', 'Al fin desapareció. Tendré que duplicar la paga del guardián del terreno esta semana.', 28153),
(137261, 'esMX', '¡Excelente! ¡Cazar alces es mucho más civilizado que atrapar osos!', '', 28153),
(137260, 'esMX', '', 'Hay un pequeño campamento en el oeste que podríamos usar...', 28153),
(137259, 'esMX', '¡Ja, ja! ¡Qué buen espectáculo! ¡Sigue así!', '', 28153),
(137258, 'esMX', '¡Ya!', '', 28153),
(137257, 'esMX', 'Junji siempre se está metiendo en problema\'. ¡No le irá nada bien si los lagarto\' lo encuentran anteh\' que tú!', '', 28153),
(137256, 'esMX', '$gPreparados, listos:Preparadas, listas;...', '', 28153),
(137255, 'esMX', 'Quizás esto\' no sean los ingrediente\' más delicioso\' del mundo, pero nos alimentan.', '', 28153),
(137254, 'esMX', 'Gruñediente eh\'ta muerto y nueh\'tras alpacas faltante\' han regresado. Ahora nueh\'tra única preocupación es que Mojambo nos mate a todo\'...', '', 28153),
(137253, 'esMX', 'Las alpaca\' no sobrevivirán sola\' en el desierto. ¡Debemos traerlas de regreso!', '', 28153),
(137252, 'esMX', 'Nuestro rebaño de alpaca\' desapareció. ¡Debemos encontrarla\' antes de que sea demasiado tarde!', '', 28153),
(137251, 'esMX', 'El desierto e\' un lugar desolado, ¡pero se puede encontrar comida si se sabe dónde buscar!', '', 28153),
(137250, 'esMX', 'No sobreviviremo\' mucho tiempo sin comida ni suminih\'tros...', '', 28153),
(137249, 'esMX', 'No habrá paz mientras los sethrak arrasen con eh\'tas tierras.', '', 28153),
(137248, 'esMX', 'Continuaremo\' cuando eh\'tés $ulisto:lista;.', '', 28153),
(137247, 'esMX', '¡$n ha capturado Granovel!', '¡$n ha capturado Granovel!', 28153),
(137246, 'esMX', 'La Alianza se ha apoderado de Granovel.', 'La Alianza se ha apoderado de Granovel.', 28153),
(137245, 'esMX', '¡La Alianza se ha apoderado de Cresta Hachazo!', '¡La Alianza se ha apoderado de Cresta Hachazo!', 28153),
(137244, 'esMX', '', 'Por favor... No tengo... mucho tiempo.', 28153),
(137243, 'esMX', '<La trol tiene una enorme herida dentada al costado, rodeada de una espuma verdosa.>', '', 28153),
(137242, 'esMX', '', 'Estoy muy preocupada por mi sobrina.', 28153),
(137241, 'esMX', '', '¡Me alegra que estés a salvo, $p! A Dolly y Dot también.', 28153),
(137240, 'esMX', '', 'Dolly y Dot han desarrollado un buen apetito. ¡No es sencillo empujar una carreta llena de trols!', 28153),
(137239, 'esMX', '', 'Dolly y Dot son fuertes y confiables. Nos llevarán a donde tengamos que ir.', 28153),
(137235, 'esMX', 'Tenemos un trato.', 'Tenemos un trato.', 28153),
(137234, 'esMX', 'Níquel guarda el halcón en su bolsa.', '', 28153),
(137233, 'esMX', 'Ah, $uun:una; $c entra en mi guarida. Dime, $upequeño:pequeña; $r, ¿has venido a hacer un trato?\n\nHace mucho decidí dejar que mis seguidores eligieran seguir también a cualquier loa. Pero por una bendición... Por una bendición necesito que tú seas un símbolo de mi poder para la gente de Zuldazar.\n\nSi quieres mi bendición, regresa a las escaleras de Dazar\'alor y construye un sagrario digno de los dioses a mi nombre.\n\nSi haces lo que te pido, te consideraré uno de los míos. ¿Tenemos un trato?', '', 28153),
(137226, 'esMX', 'Libérame.', 'Libérame.', 28153),
(137223, 'esMX', 'Saludos, ricachón. ¿Qué te trae por el Sagrario de los Carroñero\' hoy?', '', 28153),
(137212, 'esMX', 'Día uno: Deberíamos llegar hasta los troggs de las cavernas del norte a la hora del almuerzo. ¡Estoy seguro de que encontraremos algo antes de la cena! ¡Hacia la aventura!', '', 28153),
(137175, 'esMX', '¡$n ha capturado Cruce Redilnorte!', '¡$n ha capturado Cruce Redilnorte!', 28153),
(137174, 'esMX', '¡La Alianza se ha apoderado de Cruce Redilnorte!', '¡La Alianza se ha apoderado de Cruce Redilnorte!', 28153),
(137162, 'esMX', 'Ah, ¡otra alma para enviar a G\'huun!', '', 28153),
(137161, 'esMX', 'Sáurido tonto, has vuelto a morir.', '', 28153),
(137157, 'esMX', '¡Jek, jek, jek, jek!', '', 28153),
(137156, 'esMX', '¡$n ha capturado Alto Pedestal!', '¡$n ha capturado Alto Pedestal!', 28153),
(137155, 'esMX', '¡La Alianza se ha apoderado de Alto Pedestal!', '¡La Alianza se ha apoderado de Alto Pedestal!', 28153),
(137154, 'esMX', 'Esto es... ja, ¡es muy liberador! Ja, ja.', '', 28153),
(137153, 'esMX', 'Espera... ¡Joma! ¡Joma, lo estoy haciendo!', '', 28153),
(137152, 'esMX', '¡La Alianza se ha apoderado del Círculo de los Elementos!', '¡La Alianza se ha apoderado del Círculo de los Elementos!', 28153),
(137151, 'esMX', '¡$n ha capturado el Círculo de Elementos!', '¡$n ha capturado el Círculo de Elementos!', 28153),
(137148, 'esMX', '¡Vamos, papá!', '', 28153),
(137144, 'esMX', '¡NO! ¡ME EQUIVOQUÉ! ¡ES MUY RÁPIDO!', '', 28153),
(137143, 'esMX', 'Bien, creo que puedo... controlarlo...', '', 28153),
(137142, 'esMX', '¡Aaaaraaargh!', '', 28153),
(137141, 'esMX', '¡Rarrargh! ¡Destrozar! ¡Matar!', '', 28153),
(137140, 'esMX', '¡Matar! ¡Matar! ¡Matar!', '', 28153),
(137139, 'esMX', 'Grrr... ¡Aplastar!', '', 28153),
(137138, 'esMX', '¡Yo romperte!', '', 28153),
(137137, 'esMX', '¡Gaaaarrrrgh!', '', 28153),
(137135, 'esMX', 'Yo... matarte...', '', 28153),
(137134, 'esMX', 'Se derrumba...', '', 28153),
(137133, 'esMX', 'Yo... roto...', '', 28153),
(137132, 'esMX', '¡Tú ahora ser mi comida!', '', 28153),
(137131, 'esMX', '¡No llevar carne fresca!', '', 28153),
(137130, 'esMX', '¡Tierra romperte!', '', 28153),
(137129, 'esMX', '¡Yo comerte!', '', 28153),
(137128, 'esMX', 'Bien, Joma, guíame hasta el campo de entrenamiento, por favor. Creo que será el mejor lugar para... aprender a llevar las riendas, por así decirlo. Je, ejem, je.', '', 28153),
(137127, 'esMX', '¡Lo lograste, papá! ¡Sujétate bien!', '', 28153),
(137122, 'esMX', 'Mío...', '', 28153),
(137121, 'esMX', 'Yo... matarte...', '', 28153),
(137120, 'esMX', 'Yo... rompo...', '', 28153),
(137119, 'esMX', '¡Yo rompo!', '', 28153),
(137118, 'esMX', '¡Yo como!', '', 28153),
(137117, 'esMX', '¡Mato!', '', 28153),
(137116, 'esMX', '¡Este mi tesoro!', '', 28153),
(137113, 'esMX', '¡Harrison Jones es mi héroe! Pero Brann Barbabronce también me agrada.', '', 28153),
(137110, 'esMX', '¡Atrapaste uno!', '', 28153),
(137109, 'esMX', '¡Ups! ¡Atrapaste un cangrejo furioso!', '', 28153),
(137108, 'esMX', '¡El sedal se rompió!', '', 28153),
(137107, 'esMX', '¡Poz\'ga!', '', 28153),
(137106, 'esMX', '¡Poz\'ga te devorará!', '', 28153),
(137105, 'esMX', '¡Poz\'ga, vamos! ¡A correr!', '', 28153),
(137104, 'esMX', '', '¡Yo mih\'ma alimentaré a Hir\'eek con tu carne!', 28153),
(137101, 'esMX', '¿Crees que haya cosas de los titanes por aquí? Yo creo que sí. Por eso hay tantos troggs. Voy a encontrar las cosas que dejaron los titanes.', '', 28153),
(137100, 'esMX', '¡Estos niños quedarán castigados de por vida!', '', 28153),
(137099, 'esMX', 'Mi nieto siempre está metiéndose en problemas, ¡pero esto es otra cosa!', '', 28153),
(137098, 'esMX', 'Destripando', 'Destripando', 28153),
(137097, 'esMX', 'Bue… Bueno, hijo. Creo que ya es hora. ¿Podrías ayudarme, $uamigo:amiga;?', '', 28153),
(137096, 'esMX', '¡Vamos! ¡Salgamos de aquí!', '', 28153),
(137095, 'esMX', '¡Bueno, papá, basta de excusas! Tienes que subirte a este caballo.', '', 28153),
(137094, 'esMX', 'Este caballo no es para mí, hijo. Mira el brillo en sus ojos cuando me mira. ¡Quiere devorar mi caparazón!', '', 28153),
(137093, 'esMX', 'Esta me gusta. ¡Creo que es la más bonita! ¿Papá?', '', 28153),
(137092, 'esMX', 'No, no, hijo. No, no puedo subirme a este. Se ve... ¡muy inquieto! Mira su andar. ¡Mis viejos huesos nunca resistirían ese movimiento!', '', 28153),
(137091, 'esMX', '¡Este parece bonito!', '', 28153),
(137090, 'esMX', 'No, no, Joma. Este no servirá. Es demasiado... eh... nervioso. ¡Sí! ¡Nervioso! Creo que se espantará ante cualquier movimiento brusco.', '', 28153),
(137089, 'esMX', '¿Qué me dices de este, papá?', '', 28153),
(137088, 'esMX', 'Muy bien, ya basta de perder el tiempo. ¡Es hora de identificar el caballo perfecto!', '', 28153),
(137087, 'esMX', 'Antes de empezar, deja que me prepare. Solo un momento...', '', 28153),
(137086, 'esMX', '¡Tus entraña\' serán nuestro alimento!', '', 28153),
(137085, 'esMX', '¡Los maestro\' se darán un festín contigo!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137084, 'esMX', '¡Mi papá se la pasa hablando de caballos! Quiere montar uno, pero creo que les tiene miedo.$b$b¡Sé perfectamente cómo ayudarlo!', '', 28153),
(137083, 'esMX', '¡Esto debe ser lo que buscaban los sethrak!', '', 28153),
(137082, 'esMX', 'Así que las historias grabadas en las piedras rúnicas eran verdaderas... ¡La esfera existe realmente!', '', 28153),
(137080, 'esMX', '', '¡No me engañará\' con tu magia!', 28153),
(137079, 'esMX', '', 'Las pocione\' aún no están listas. ¡Vete de aquí!', 28153),
(137078, 'esMX', '', 'Habla. ¿Por qué interrumpe\' mi meditación?', 28153),
(137077, 'esMX', 'Thun\'ka... el Marchitador...', '', 28153),
(137076, 'esMX', 'Thun\'ka... el Marchitador...', '', 28153),
(137075, 'esMX', '', 'Gracias por la ayuda, visitante. Recuerda mantener limpios los pantalones.', 28153),
(137074, 'esMX', 'Prepárate, $gamigo:amiga;. ¡Esta fiesta está por ponerse mucho más interesante!', '', 28153),
(137073, 'esMX', '¡$ULadrón:Ladrona;! ¡Pagarás por esto!', '¡$ULadrón:Ladrona;! ¡Pagarás por esto!', 28153),
(137071, 'esMX', '¡No eres rival para nuestro imperio!', '¡No eres rival para nuestro imperio!', 28153),
(137068, 'esMX', '¡El poder de estas ruinas nos pertenece!', '¡El poder de estas ruinas nos pertenece!', 28153),
(137067, 'esMX', '¡No te quedarás con el poder! ¡Será nuestro!', '¡No te quedarás con el poder! ¡Será nuestro!', 28153),
(137066, 'esMX', '', 'No todos los días se tiene la oportunidad de ganarse el favor de un elemental de agua.', 28153),
(137065, 'esMX', '', 'Jaja. Admiro tu pasión. Ve, levanta una estatua en mi honor ante las escaleras de Dazar\'alor para que los trols de esta tierra sepan con quién has tratado.', 28153),
(137063, 'esMX', '', '¡Ja, ja! Era una forma de decir.', 28153),
(137062, 'esMX', '<Activa el Coloso>', '<Activa el Coloso>', 28153),
(137061, 'esMX', 'Este ensamblaje antiguo brilla cuando te acercas.', 'Este ensamblaje antiguo brilla cuando te acercas.', 28153),
(137056, 'esMX', 'No intentes vincularme una segunda vez, chamán. ¡Te desintegraré!', '', 28153),
(137055, 'esMX', '¡Ey! Tú no pareces ser uno de esos nobles remilgados. ¡Ven a tomar un trago con nosotros! Lord Norwington nos ha invitado a los montañeses para empezar a festejar, ¡y eso es justo lo que haremos!', '', 28153),
(137054, 'esMX', 'No ere\' $Ubienvenido:bienvenida; aquí... ¡Este es el puente trol!', '', 28153),
(137053, 'esMX', 'Mira estos equinos majestuosos, joven. Viajamos por todo el continente para venir a este festival. Estoy decidido a aprender acerca de estos animales singulares.$b$bNobles, poderosos... Mi viejo corazón siente temor y fascinación en su presencia.', '', 28153),
(137052, 'esMX', '¡El Marchitador consumirá este valle!', '', 28153),
(137051, 'esMX', '¡La Horda ha recuperado Ar\'gorok!', '¡La Horda ha recuperado Ar\'gorok!', 28153),
(137050, 'esMX', '', 'Hay un poder nuevo en mi hogar. Da un paso adelante, $p de la Horda, así podré verte como realmente eres.$b$b$UUn:Una; $c $r, y $uun campeón:una campeona;, nada menos.$b$bMi señor aojador me dice que deseas obtener mi bendición, pero yo primero tendré que pedirte algo, como hago con todos los que buscan un trato conmigo.$b$BNecesito que realices un salto de fe...', 28153),
(137049, 'esMX', '¡Vamos, pongamos fin a este culto!', '', 28153),
(137048, 'esMX', '¿Es... Estás hablando en serio? ¡Creo que debemo\' aceptar su oferta!', '', 28153),
(137047, 'esMX', '¡Bah! He sobrevivido a mucha\' cosas. No ganarás.', '', 28153),
(137046, 'esMX', '¡Tu gente eh\'tá condenada! Únete a mí... y te salvarás.', '', 28153),
(137045, 'esMX', 'De acuerdo.', 'De acuerdo.', 28153),
(137041, 'esMX', 'Ah, ¡$Unuestro estimado héroe:nuestra estimada heroína;! $UBienvenido, bienvenido:Bienvenida, bienvenida;. Sírvete algo de comida y bebida. Si necesitas algo más, solo tienes que avisarme. Estaré encantado de ayudarte.', '', 28153),
(137040, 'esMX', 'Aquí es donde cuidamos de todos nuestros caballos. ¡Los jinetes y los mozos de cuadra los mantienen acicalados y bien alimentados!', '', 28153),
(137039, 'esMX', '', '¿Qué les preguntarías a los loa de los cielos?', 28153),
(137038, 'esMX', '', '¡Iré a esconderme con Marcus!', 28153),
(137037, 'esMX', '', '¡Gracias! ¡Ya me estaba por quedar sin piedras!', 28153),
(137036, 'esMX', '¡Muere, $Gentrometido:entrometida;!', '', 28153),
(137035, 'esMX', '', '¡El poder de Zardrax fluye por mis vena\'!', 28153),
(137034, 'esMX', '', '¡El poder de Zardrax te destruirá!', 28153),
(137033, 'esMX', 'Yo regresaré a Zul\'jan. Veremo\' si alguien más tuvo la loca idea de unirse a los trols de sangre.', '', 28153),
(137032, 'esMX', 'Qué lástima que Kal\'dran sea demasiado débil para ver que ganaríamos...', '', 28153),
(137031, 'esMX', 'Buena suerte, $n. Mata a Zardrax ante\' de que su corrupción agregue más adepto\' a sus fila\'.', '', 28153),
(137030, 'esMX', 'Deja que $n se encargue de eh\'to. Matará a ese aojador del que estás hablando.', '', 28153),
(137029, 'esMX', 'No estoy seguro de esto, Da\'jul... ¡$n no es capaz de detener esto! ¡Todos vamo\' a morir!', '', 28153),
(137028, 'esMX', '', '¡Iré a buscar a Marcus! ¡Nos vemos ahí!', 28153),
(137027, 'esMX', '', 'Ah, ¡gracias! Estaba bastante incómoda ahí adentro.', 28153),
(137026, 'esMX', '', 'Esto es demasiado para mí. ¡Me voy!', 28153),
(137025, 'esMX', '¡La Alianza ha asaltado la Mina!', '', 28153),
(137024, 'esMX', '¡$n ha asaltado la Mina!', '', 28153),
(137023, 'esMX', 'Volveré a llenar el lago de inmediato.', '', 28153),
(137022, 'esMX', 'Qué esencia tan fuerte. Esto debe ser obra de Sumber.', '', 28153),
(137021, 'esMX', 'Iré a buscar a Marcus y esperaré con él. ¡Nos vemos ahí!', '', 28153),
(137020, 'esMX', '¡Gracias! No sabía que los troggs podían lanzar hechizos.', '', 28153),
(137019, 'esMX', 'Regreso a Sumber.', '', 28153),
(137018, 'esMX', 'He renacido.', '', 28153),
(137017, 'esMX', 'Crecí oyendo historiah\' de trols de sangre salvajes. Pero eh\'to es peor que cualquier cosa que me hayan dicho.', '', 28153),
(137016, 'esMX', '¡Kal\'dran! ¡$n, debes ir tras él...! Aunque eso signifique que tengas que matarlo...', '', 28153),
(137015, 'esMX', '¡Estamo\' CONDENADOS! ¡Zardrax nos salvará y puede\' considerarte $Umuerto:muerta; si trata\' de hacerme enojar!', '', 28153),
(137013, 'esMX', 'No... resisto...', '', 28153),
(137012, 'esMX', '¡$UBienvenido:Bienvenida; al Festival ecuestre Norwington! Aún nos estamos preparando, pero tienes que participar en las celebraciones. ¡No aceptaré un \"no\" como respuesta!', '', 28153),
(137011, 'esMX', '¡Váyanse! ¡Ya no queda nada para ustedes en este lugar!', '', 28153),
(137010, 'esMX', '¡Ahora, $c!', '', 28153),
(137009, 'esMX', '¡No hagas caso de sus mentiras huecas o también te condenarás!', '', 28153),
(137008, 'esMX', '¡Lord Valletoño ha muerto! ¡Sus ansias de poder fueron su condena!', '', 28153),
(137007, 'esMX', 'He visto... la cara de G\'huun... no hay... esperanza...', '', 28153),
(137006, 'esMX', '¡La eh\'peranza ya no existe! ¿Por qué no te unes a Zardrax?', '', 28153),
(137005, 'esMX', 'Vuelvo a darte las gracias, $c. ¡Llegaste justo a tiempo!', '', 28153),
(137003, 'esMX', 'Has condenado... a esta tierra...', '', 28153),
(137002, 'esMX', '¡No debes interferir con nuestro trabajo, a menos que también quieras que te sacrifiquemos!', '', 28153),
(137001, 'esMX', '¡Están todos locos! ¡Ayúdame, $c!', '', 28153),
(137000, 'esMX', '¡Debemos apaciguar al Hombre de mimbre o nuestras desgracias no tendrán fin!', '', 28153),
(136999, 'esMX', '¡¿Puedes calmarte?! ¡Tu muerte servirá a una causa superior!', '', 28153),
(136998, 'esMX', '¡No puedes hacer esto! ¡Es asesinato! ¡Asesinato!', '', 28153),
(136997, 'esMX', 'Parece que has eliminado a unas cuantas. Creo que ya puedo regresar.', '', 28153),
(136996, 'esMX', '¡Gracias, $Gforastero:forastera;! Pensé que esas abejas acabarían con mi vida.', '', 28153),
(136995, 'esMX', '¡Mis ojos! ¡Mis ojos!', '', 28153),
(136994, 'esMX', '¡No! ¡Las abejas nooooooo!', '', 28153),
(136993, 'esMX', '¡$C! Siempre es bueno ver a alguien... Espera, ¿qué es eso?', '', 28153),
(136992, 'esMX', '¡Salve, Hombre de mimbre!', '¡Salve, Hombre de mimbre!', 28153),
(136991, 'esMX', '¡Mira, $n! Este es Magoo, ni nuevo caballo. ¿No es genial?$b$bExtraño a Relámpago, era muy bueno. ¡Pero a veces se emocionaba demasiado! Voy a pasar mucho tiempo con Magoo para conocerlo bien y saber cuándo está nervioso.$b$bQuiero ser un jinete muy bueno, así que seguiré entrenando con Melissa para que Magoo y yo seamos un gran equipo. ¡El mejor de los mejores!', '', 28153),
(136990, 'esMX', 'Reúnanse ante el Hombre de mimbre, iniciados. Su gracia nos protegerá de las maldiciones que caen sobre nuestras tierras.', '', 28153),
(136989, 'esMX', '', 'No tengo palabras suficientes para agradecerte por salvar a Eddie. Es un buen chico, y aprenderá a ser un buen jinete también.$b$bPero creo que por ahora las lecciones solo serán en la finca.', 28153),
(136988, 'esMX', 'Muy... débil...', '', 28153),
(136987, 'esMX', 'Te oigo, madre. ¡Estoy en camino!', '', 28153),
(136986, 'esMX', 'Kejabu me ha enviado.', 'Kejabu me ha enviado.', 28153),
(136985, 'esMX', 'Pero si te unes a mí, ¡recibirás más poder del que te habrías imaginado en mil vidas!', '', 28153),
(136984, 'esMX', 'Si tratas de luchar, nuestras fuerzas te aplastarán.', '', 28153),
(136983, 'esMX', 'No tienes opción. Zuldazar está condenado. ¡G\'huun será liberado!', '', 28153),
(136982, 'esMX', 'Si me sirves, te perdonaré la vida. Es una promesa de G\'huun.', '', 28153),
(136981, 'esMX', 'G\'huun lo consumirá todo. No hay esperanza.', '', 28153),
(136980, 'esMX', 'Jaja... ¡eres fuerte! Pero todo\' caerán ante G\'huun. Mi oferta sigue disponible para los que deseen aceptarla...', '', 28153),
(136979, 'esMX', 'Es... Espera. ¡Tal vez deberíamo\' trabajar para Zardrax! ¿Cómo podemos impedir todo eh\'to?', '', 28153),
(136978, 'esMX', '¡$n jamás se aliará contigo! ¡Muéh\'trale a este exánime lo que piensas de su \"oferta\"!', '', 28153),
(136977, 'esMX', 'Sírveme y te salvarás... Y te daré una parte del poder de G\'huun.', '', 28153),
(136976, 'esMX', 'Zuldazar caerá ante lo\' trols de sangre y G\'huun. Pero tú no tienes que compartir ese destino.', '', 28153),
(136975, 'esMX', 'Está bien, exánime. Dime cuál es tu oferta.', 'Está bien, exánime. Dime cuál es tu oferta.', 28153),
(136974, 'esMX', '¡Únete a mí, y te salvarás de la deh\'trucción de Zuldazar!', '', 28153),
(136973, 'esMX', '¡Estamo\' condenados! ¿Cómo podemo\' tener la esperanza de detener algo así?', '', 28153),
(136972, 'esMX', '¿Pero cuántas fuente\' de poder tienen esto\' trols de sangre?', '', 28153),
(136969, 'esMX', '', '¡Excelente! Has eh\'cogido bien. Ven, te presentaré a tu patrón.', 28153),
(136968, 'esMX', '¡Ja! Sabía que tomaría\' la decisión correcta. Ven a verme y te enviaré a ver a Pa\'ku cara a cara.', '', 28153),
(136967, 'esMX', 'Me gustaría elegir un loa diferente.', 'Me gustaría elegir un loa diferente.', 28153),
(136966, 'esMX', '¡Nooooo! ¡Gusano entrometido de la Horda! Te arrancaré la vida del cuerpo.', '', 28153),
(136965, 'esMX', '¡No te detenga\'! ¡Por favor no te detenga\'!', '', 28153),
(136964, 'esMX', '¡Dame más! ¡Dámelo todo!', '', 28153),
(136963, 'esMX', '¡Más! ¡Dame más!', '', 28153),
(136962, 'esMX', 'Síííí... sííí... ¡¡¡SÍÍÍÍ!!!', '', 28153),
(136961, 'esMX', '', '¡Llegah\' tarde! Si mi murciélago se muere por tu culpa, ¡te cortaré la cabeza y la usaré para decorar mi cabaña!', 28153),
(136960, 'esMX', 'Eres $gun aliado de los más inesperados:una aliada de las más inesperadas; en esta batalla.', '', 28153),
(136959, 'esMX', 'Cre...Creo que eso es justo.', '', 28153),
(136958, 'esMX', '', 'Bueno, Eddie. Creo que las lecciones de equitación continuarán en la finca por ahora.', 28153),
(136957, 'esMX', '', '¡No es momento para sentimientos, alto señor supremo!', 28153),
(136956, 'esMX', '¡Debe haber otra forma, jefa de guerra!', '', 28153),
(136954, 'esMX', '', '¡Raal, idiota presumido! Nos dejah\'te indefensos. Tenemo\' una cultista de sangre haciendo un ritual en nuestro propio pináculo.', 28153),
(136953, 'esMX', 'La última barrera... caerá... y G\'huun... ¡será libre!', '', 28153),
(136952, 'esMX', 'No... Mi vínculo con G\'huun se... deh\'vanece.', '', 28153),
(136951, 'esMX', '¡Estoy propagando el poder de G\'huun! ¡No me detendrás!', '', 28153),
(136950, 'esMX', '¡Imbécil! ¡El poder de G\'huun está en mí! ¡No caeré!', '', 28153),
(136949, 'esMX', 'Pequeñ$go:a; $pr insolente. Acércate, tengo que hablar contigo.', '', 28153),
(136948, 'esMX', '', 'Ja... Jamá\' detendrán a Zardrax... Su poder... nos ayudará a destruir... Zuldazar...', 28153),
(136947, 'esMX', '', 'Con el poder de Zardrax y de G\'huun, ¡seremo\' imparables!', 28153),
(136945, 'esMX', 'Bien hecho, $c. Te has ganado mi confianza. Te ayudaré con tu tarea.', '', 28153),
(136944, 'esMX', '', 'Se siente más su presencia, eso sí.', 28153),
(136943, 'esMX', '¡Creo que se movió! No... Espera. ¿Fue el viento?', '', 28153),
(136942, 'esMX', 'Listo. ¡Recibe nuestras ofrendas, Hombre de mimbre, y otórganos tu gracia!', '', 28153),
(136941, 'esMX', '¿Has traído los huesos? ¡Perfecto! Se nota que a esta cosa le gustan los huesos.', '', 28153),
(136940, 'esMX', '¡Ah, las entrañas! Algo haremos con eso... seguramente', '', 28153),
(136939, 'esMX', 'Veo que has traído el mimbre. Una opción obvia pero correcta.', '', 28153),
(136938, 'esMX', '', '¡No, no, no! Esas hierbas son para cocinar, no para hacer ritos. ¿No ves la diferencia?', 28153),
(136937, 'esMX', '', '¿Qué haces con eso? ¡No estamos construyendo un espantapájaros!', 28153),
(136936, 'esMX', 'Oh, has traído los pergaminos... Es cierto, quizás sean esenciales para despertar al Hombre de mimbre, pero... ninguno de nosotros puede leerlos.', '', 28153),
(136935, 'esMX', '¡¿Frutas?! ¿Hablas en serio? Ya veo que sí.', '', 28153),
(136934, 'esMX', 'Lo logramos. Al fin Sylvanas responderá por sus crímenes. Campeones, a mi lado...', '', 28153),
(136929, 'esMX', '<Heiro da unos golpecitos espontáneos a la pandereta y te guiña un ojo.>', '', 28153),
(136927, 'esMX', 'No creo que volvamos a vernos, $n. Gracias.', '', 28153),
(136925, 'esMX', '', 'Vol\'dun nos ha atacado con cosas mucho peores. Estaremos bien.', 28153),
(136919, 'esMX', 'Creo que puedo llegar hasta Melissa si despejas el camino. ¡Muchas gracias por salvarme!', '', 28153),
(136918, 'esMX', '¿Ya... puedo salir? ¡Los troggs me dan mucho miedo!', '', 28153),
(136917, 'esMX', '¡$n ha capturado Cresta Hachazo!', '¡$n ha capturado Cresta Hachazo!', 28153),
(136916, 'esMX', 'Te dejaré con Loti. Cuéntale que la causa de todo eh\'te alboroto puede encontrarse dentro del propio Zanchul.', '', 28153),
(136915, 'esMX', 'Mmm... algo parece... diferente. Siento que un gran poder resuena dentro de Zanchul.', '', 28153),
(136914, 'esMX', 'No pasa ni una semana sin que un zandalari se entregue a las magia\' de sangre que aprenden de esos hereje\' de Nazmir.', '', 28153),
(136913, 'esMX', 'Nueh\'tras defensa\' se debilitan. La princesa Talanji cada vez nos pide más tropa\'. Pero su padre no actuó con rapidez y ella acudió a la Horda.', '', 28153),
(136912, 'esMX', 'En ese momento tuvimo\' nueh\'tro primer encuentro con la verdadera magia de sangre. No ese sinsentido que practican las tribu\' más débile\'.', '', 28153),
(136911, 'esMX', 'Hace unos años, toda esta tierra se eh\'tremeció a merced del Cataclismo. Nueh\'tras puerta\' del norte cayeron, y hordas de trols de sangre invadieron nueh\'tro hogar.', '', 28153),
(136910, 'esMX', 'Yo te marcaré los lugare\' y tú tendrás el honor de arrojar un tótem avizor.', '', 28153),
(136909, 'esMX', 'Una pequeña bolsa con bocadillos para caballos yace esparcida en el suelo. Cuando inspeccionas la bolsa, notas el nombre de Eddie bordado en la tela.$b$bDebe haber pasado por aquí, aunque no parece haber sido por voluntad propia. Notas algunos bocadillos más que llevan a la colina.', 'Una pequeña bolsa con bocadillos para caballos yace esparcida en el suelo. Cuando inspeccionas la bolsa, notas el nombre de Eddie bordado en la tela.$b$bDebe haber pasado por aquí, aunque no parece haber sido por voluntad propia. Notas algunos bocadillos más que llevan a la colina.', 28153),
(136908, 'esMX', 'No sé cuánto tiempo más podremo\' sobrevivir contra los sethrak...', '', 28153),
(136907, 'esMX', 'Es evidente que no ereh\' de Zuldazar, si no sabrías exactamente quién soy. ¡Yo era el cocinero personal del general Jakra\'zet!$b$bMe exiliaron cuando el general enfermó deh\'pués de comer uno de mis platos... ¡pero no fue mi culpa!$b$b¡Loh\' demás cocineros me envidiaban! ¡Uno de ellos debe haber envenenado la comida cuando no eh\'taba mirando!$b$bAlgún día encontraré la forma de demoh\'trar mi inocencia, pero ahora tengo que cocinar escarabajos pelotero\' para sobrevivir.', '', 28153),
(136906, 'esMX', '¡ALIANZA, MANTENGAN LA POSICIÓN!', '', 28153),
(136905, 'esMX', '¿Cómo terminaste en Vol\'dun?', '¿Cómo terminaste en Vol\'dun?', 28153),
(136904, 'esMX', 'Haces preguntas peligrosas, $c.\n\nNo tengo intención de esconder mi pasado, pero hay otros aquí que no son como yo...\n\nMe exiliaron con mi familia cuando era apenas un niño. Mi padre tenía muchas deudas y en esa época los niños iban al exilio con sus padres.\n\nEstaba solo y muriendo de sed cuando Razgaji me encontró. Me alimentó, me devolvió la salud y me crió como a un hijo. He permanecido con él desde entonces.', '', 28153),
(136903, 'esMX', '¿Cómo terminaste en Vol\'dun?', '¿Cómo terminaste en Vol\'dun?', 28153),
(136902, 'esMX', '', 'A ti no te había visto por aquí ante\'. Ven, hablemos.', 28153),
(136901, 'esMX', '', 'Hemos complacido a Hir\'eek... ¡pero necesitamos má\' sangre! ¡Trae otra víctima para el sacrificio!', 28153),
(136900, 'esMX', '', 'Gran Hir\'eek, loa de los murciélago\' y sirviente de G\'huun. ¡Te ofrezco este sacrificio!', 28153),
(136899, 'esMX', '', 'Encontrarás al Señor aojador Raal al final del Bancal. Dedícale un par de insulto\' en mi nombre.', 28153),
(136895, 'esMX', '¡Se te acabó el tiempo, rey Anduin!', '', 28153),
(136894, 'esMX', 'Si nos retiramos ahora, seremos la presa. No. Pelearemos, y moriremos de ser necesario... por nuestras convicciones.', '', 28153),
(136889, 'esMX', '', 'Habla o te arrancaré la lengua en el próximo ritual.', 28153),
(136888, 'esMX', '', 'Hir\'eek nos da a sus hijos. El dio\' de la sangre nos da su poder. Juntos, ¡somos imparables!', 28153),
(136887, 'esMX', '', '¿Qué sucede? Habla ya o será\' la próxima ofrenda de sacrificio.', 28153),
(136882, 'esMX', 'Recogiendo línea', 'Recogiendo línea', 28153),
(136878, 'esMX', '', 'La guerra nos exige un enfoque más directo.', 28153),
(136876, 'esMX', '', '¡Serpientes! ¡Cuidado!', 28153),
(136874, 'esMX', '¿Has hablado con Gonk? Él es el jefe de la manada. Habló con algunos de los Lanza Negra y los guio hasta los druida\'.$b$bPero para nosotro\', él es más que una voz. Podemo\' escucharlo en persona. No un fragmento o un trozo, sino él en su totalidad, en carne y hueso.', '¿Has hablado con Gonk? Él es el jefe de la manada. Habló con algunos de los Lanza Negra y los guio hasta los druida\'.$b$bPero para nosotro\', él es más que una voz. Podemo\' escucharlo en persona. No un fragmento o un trozo, sino él en su totalidad, en carne y hueso.', 28153),
(136872, 'esMX', 'Gonk es el loa que les enseñó a todo\' los trols a expandir su influencia a los otro\' loa y a convertirse en druidas. Y nosotro\' estamo\' por siempre agradecidos.', 'Gonk es el loa que les enseñó a todo\' los trols a expandir su influencia a los otro\' loa y a convertirse en druidas. Y nosotro\' estamo\' por siempre agradecidos.', 28153),
(136871, 'esMX', 'Los seguidore\' de Pa\'ku aún están enojado\' porque la druida guerrera Loti dejó a su señor aojador Raal. Muy triste. Muy poco profesional.', 'Los seguidore\' de Pa\'ku aún están enojado\' porque la druida guerrera Loti dejó a su señor aojador Raal. Muy triste. Muy poco profesional.', 28153),
(136870, 'esMX', 'Los seguidore\' de Gonk aún están enojado\' porque el señor aojador Raal dejó a nueh\'tra druida guerrera Loti. Muy triste. Muy poco profesional.', 'Los seguidore\' de Gonk aún están enojado\' porque el señor aojador Raal dejó a nueh\'tra druida guerrera Loti. Muy triste. Muy poco profesional.', 28153),
(136869, 'esMX', 'Hagas lo que hagas, no escuches las mentira\' de los seguidore\' de Gonk. Están celosos de lo grandiosa que es nuestra loa Pa\'ku.', 'Hagas lo que hagas, no escuches las mentira\' de los seguidore\' de Gonk. Están celosos de lo grandiosa que es nuestra loa Pa\'ku.', 28153),
(136868, 'esMX', 'Yo respondo a Pa\'ku, la señora de los viento\' y la maestra de nuestras nave\'. Es una loa como ninguna otra. Sería muy sensato que trataras con ella en vez de tratar con otro\' loa. Los demá\' no son confiables.', 'Yo respondo a Pa\'ku, la señora de los viento\' y la maestra de nuestras nave\'. Es una loa como ninguna otra. Sería muy sensato que trataras con ella en vez de tratar con otro\' loa. Los demá\' no son confiables.', 28153),
(136867, 'esMX', 'Mmm, $p. Lo\' loa susurran tu nombre. Tu llegada a Zuldazar será muy interesante.', 'Mmm, $p. Lo\' loa susurran tu nombre. Tu llegada a Zuldazar será muy interesante.', 28153),
(136866, 'esMX', 'Pa\'ku es la loa de los viento\' y la maestra de nuestros exploradore\' y de nuestra flota. Es una loa impulsiva que adora su libertad. Habla con su campeón, el señor aojador Raal, si quiere\' saber más.', 'Pa\'ku es la loa de los viento\' y la maestra de nuestros exploradore\' y de nuestra flota. Es una loa impulsiva que adora su libertad. Habla con su campeón, el señor aojador Raal, si quiere\' saber más.', 28153),
(136865, 'esMX', '¡Ah! $UEl héroe:La heroína; de la Horda. El señor aojador Raal estará impresionado contigo. Si tú le cae\' bien a él, le cae\' bien a Pa\'ku y me cae\' bien a mí.', '¡Ah! $UEl héroe:La heroína; de la Horda. El señor aojador Raal estará impresionado contigo. Si tú le cae\' bien a él, le cae\' bien a Pa\'ku y me cae\' bien a mí.', 28153),
(136864, 'esMX', 'Tu presencia no es bienvenida aquí.', 'Tu presencia no es bienvenida aquí.', 28153),
(136863, 'esMX', 'No tengo nada para decirte.', 'No tengo nada para decirte.', 28153),
(136862, 'esMX', 'Te debe\' haber perdido. No deberías estar aquí.', 'Te debe\' haber perdido. No deberías estar aquí.', 28153),
(136861, 'esMX', 'Sin linaje. ¡Bah!', 'Sin linaje. ¡Bah!', 28153),
(136860, 'esMX', 'No me hableh\', $Gcampesino:campesina;.', 'No me hableh\', $Gcampesino:campesina;.', 28153),
(136859, 'esMX', '', 'Como era de esperarse, mi trabajo es perfecto. Algo debe estar atascando la fuente. ¿Podrías echarle un vistazo?', 28153),
(136858, 'esMX', '', 'Investiguemos esta fuente.', 28153),
(136857, 'esMX', 'Mi próximo ritual lo haré con tu sangre.', 'Mi próximo ritual lo haré con tu sangre.', 28153),
(136856, 'esMX', '¡Basura entrometida de la Horda!', '¡Basura entrometida de la Horda!', 28153),
(136855, 'esMX', '¡No puedes detenerno\' a todos!', '¡No puedes detenerno\' a todos!', 28153),
(136854, 'esMX', '¿Cree\' que soy el único que usa magia de sangre aquí? Te espera una sorpresa horrible.', '¿Cree\' que soy el único que usa magia de sangre aquí? Te espera una sorpresa horrible.', 28153),
(136853, 'esMX', '¡Bah! ¡Un eh\'birro entrometido de la Horda no me matará!', '¡Bah! ¡Un eh\'birro entrometido de la Horda no me matará!', 28153),
(136852, 'esMX', 'Voladores necio\', pensé que ustede\' iban a buscar a los trols de sangre. ¿Por qué nosotro\' tenemos que hacer su trabajo?', 'Voladores necio\', pensé que ustede\' iban a buscar a los trols de sangre. ¿Por qué nosotro\' tenemos que hacer su trabajo?', 28153),
(136851, 'esMX', 'No se interpondrán en nueh\'tro día ritualístico. Loti es garantía de lo que digo.', 'No se interpondrán en nueh\'tro día ritualístico. Loti es garantía de lo que digo.', 28153),
(136850, 'esMX', 'Ustede\', fanático\' voladore\', serán la perdición de Zandalar.', 'Ustede\', fanático\' voladore\', serán la perdición de Zandalar.', 28153),
(136849, 'esMX', 'Raal va a entregarlo\' a todos como alimento para los loa del rey si nos sigue molestando.', 'Raal va a entregarlo\' a todos como alimento para los loa del rey si nos sigue molestando.', 28153),
(136848, 'esMX', '', 'Ese ejército es enorme... Da la orden y nos teletransportaré a un lugar seguro.', 28153),
(136846, 'esMX', '¿Aún sigues a Loti? ¡Ja! Eres má\' $utonto:tonta; que estiércol de bruto.', '¿Aún sigues a Loti? ¡Ja! Eres má\' $utonto:tonta; que estiércol de bruto.', 28153),
(136845, 'esMX', 'Ahora ustedes están en desventaja.', '', 28153),
(136844, 'esMX', 'En algún momento, Raal gobernará este lugar, sacará a patadas a todos los fanático\' del raptor y los mandará a la selva de la que salieron.', 'En algún momento, Raal gobernará este lugar, sacará a patadas a todos los fanático\' del raptor y los mandará a la selva de la que salieron.', 28153),
(136843, 'esMX', 'El nombre de tu loa es Gonk. Debería\' sentirte mal por eso.', 'El nombre de tu loa es Gonk. Debería\' sentirte mal por eso.', 28153),
(136842, 'esMX', 'Druidas sucio\', se conforman con los resto\'. No son mejores que los gubarashi.', 'Druidas sucio\', se conforman con los resto\'. No son mejores que los gubarashi.', 28153),
(136841, 'esMX', 'No ere\' mejor que yo. Mi sangre... mancha tus mano\'.', '', 28153),
(136840, 'esMX', 'La supervivencia del trol má\' fuerte. ¡Matar o morir!', '', 28153),
(136838, 'esMX', '<Encuentras el cadáver aún tibio del poni de Eddie, Relámpago.>$b$b<Las migajas llegan hasta la colina. Parece que Eddie dejó un rastro.>', 'Encuentras el cadáver aún tibio del poni de Eddie, Relámpago$b$b Esperas que no sea tarde para Eddie también.', 28153),
(136837, 'esMX', '¡Niño será golosina deliciosa!', '', 28153),
(136836, 'esMX', '¡Estoy aquí! ¡Él tiene la llave! ¡Ayúdame por favor!', '', 28153),
(136835, 'esMX', '', 'En marcha, $n. ¡Lord Norwington me cortará la cabeza si algo le pasa a su hijo!', 28153),
(136832, 'esMX', 'Somo\' una tribu de desterrados, nos exiliaron de Zuldazar al desierto para morir.\n\nAlguno\' recibieron este castigo por acusaciones falsas de crímenes no cometidos. El resto tiene un deh\'tino bien merecido.\n\nAhora solo nos preocupa la supervivencia.\n\nSi obedece\' las leyes de la tribu, tendrás un lugar asegurado entre nosotros. Pero si las infringes, verá\' que nuestra justicia es todavía más ágil que la del rey Rastakhan.', '', 28153),
(136831, 'esMX', '¿Qué necesitas?', '', 28153),
(136830, 'esMX', '¿Qué sucede? No... no seráh\' tú el próximo sacrificio, ¿verdad?', '', 28153),
(136829, 'esMX', 'Lah\' sacerdotisas... ¡nos matarán a todos!', '', 28153),
(136828, 'esMX', 'Esto se pondrá mucho má\' violento sin tu disfraz.', '', 28153),
(136827, 'esMX', 'Cuéntame sobre tu tribu.', 'Cuéntame sobre tu tribu.', 28153),
(136825, 'esMX', '', 'Es el eh\'cudo de Rakera... ¿Dónde está? ¿Qué le han hecho?', 28153),
(136824, 'esMX', 'Eh\'to es culpa de Jakra\'zet, no mía. Rakera es la única razón por la que eh\'toy vivo.', '', 28153),
(136823, 'esMX', '', '¡Meerah, detén la caravana! Veo algo más adelante.', 28153),
(136822, 'esMX', '', '¿Cómo pudo sobrevivir Rakera en eh\'te lugar?', 28153),
(136820, 'esMX', '', '¿Puedes creer que estos páramos en algún momento fueron la joya del imperio trol? Una jungla que rebosaba de vida... Ahora sus restos están enterrados bajo la arena.', 28153),
(136819, 'esMX', '', 'Kiro no tiene motivos para preocuparse. ¡Tengo suficiente práctica! Aunque quizá sea mejor que te sujetes, por las dudas.', 28153),
(136818, 'esMX', '', '¡Siempre estoy lista!', 28153),
(136816, 'esMX', '... pero solo con la ayuda de $Ueste:esta; $c. Puedo oler su enorme mojo.', '', 28153),
(136815, 'esMX', 'Eres igual a todos los loco\' que van a Naz... ¿Qué?', 'Eres igual a todos los loco\' que van a Naz... ¿Qué?', 28153),
(136814, 'esMX', '¡Bah! Mira, iré allí y te mostraré que eh\'te tipo está loco.', '¡Bah! Mira, iré allí y te mostraré que eh\'te tipo está loco.', 28153),
(136813, 'esMX', '¡Les contaré a todo\' en el campamento cómo me salvaste!', '', 28153),
(136812, 'esMX', '¡Soy libre! ¡No puedo creerlo!', '', 28153),
(136811, 'esMX', 'Si recuperara mis fuerza\', podría vencerlo...', '', 28153),
(136810, 'esMX', '...y ese es Urok, una monstruosidad no-muerta que lo\' matará a todos.', '', 28153),
(136809, 'esMX', '¡Idiota! ¡Te convertiráh\' en alimento para Urok!', '', 28153),
(136808, 'esMX', 'Shhh... Urok está cerca... Puedo OLER su\' DIENTES.', '', 28153),
(136807, 'esMX', 'Muéstrame a Urok, el terror de los humedales.', 'Muéstrame a Urok, el terror de los humedales.', 28153),
(136806, 'esMX', '', '¡Eddie!', 28153),
(136805, 'esMX', 'Pa\'ku, Pa\'ku, Pa\'ku, ella es la loa para ti.', 'Pa\'ku, Pa\'ku, Pa\'ku, ella es la loa para ti.', 28153),
(136804, 'esMX', '¿Te gusta el cielo? A mí también. Únete a Pa\'ku, tu loa ideal.', '¿Te gusta el cielo? A mí también. Únete a Pa\'ku, tu loa ideal.', 28153),
(136803, 'esMX', '¡No te demore\' más y sigue a Pa\'ku!', '¡No te demore\' más y sigue a Pa\'ku!', 28153),
(136800, 'esMX', '¡Está bien, está bien! No hay por qué... ¡AAH!', '', 28153),
(136799, 'esMX', '', 'Bien, Eddie, mantén a Relámpago tranquilo.', 28153),
(136798, 'esMX', '', '¡Miserable imbécil! Hir\'eek ni siquiera te aceptará como sacrificio.', 28153),
(136797, 'esMX', '', 'Vamoh\'. Ya es hora.', 28153),
(136789, 'esMX', 'Adiós, $n. Nos veremoh\' pronto.', '', 28153),
(136788, 'esMX', 'Tengo que regresar a Zo\'bal. Aún quedan muchas alma\' por recoger para pagar mi deuda.', '', 28153),
(136780, 'esMX', 'El cazador nocturno poseído emite un gemido leve.', '', 28153),
(136779, 'esMX', '¡El cazador nocturno poseído ha oído algo en las cercanía\'!', '', 28153),
(136778, 'esMX', 'El cazador nocturno poseído olfatea el aire.', '', 28153),
(136769, 'esMX', '', 'Meeki merecía un destino mejor, pero sé que no es tu culpa.\n\nGracias por encontrarlo por nosotros. Es mejor conocer el dolor que vivir con arrepentimiento.\n\nRecorremos las dunas como familia, y ahora tú eres $uun:una; integrante más. Siempre te recibiremos en la caravana.', 28153),
(136768, 'esMX', 'Tienes que tener la mente má\' clara si no quiere\' que tus enemigo\' sientan tu debilidad.', '', 28153),
(136767, 'esMX', '¡Basta ya!', '', 28153),
(136766, 'esMX', 'N-n-no puedo esperar para escuchar la canción de Ahna sobre tus aventuras.\n\nA-a-ahna escribe canciones muy buenas. ¡Cu-cu-cuéntale tu historia!\n\nTo-to-todos los viajeros que conozcamos escucharán la historia de $p.', '', 28153),
(136764, 'esMX', '', 'Tragedia, piratas no-muertos, tesoros malditos y un motín... esta aventura es legendaria.\n\nYa tengo un par de ideas fantásticas para el primer verso de mi canción: Balada de los valientes $p.\n\nSerás leyenda durante generaciones, al menos en esta caravana\n\nPero primero, necesito una siesta.', 28153),
(136763, 'esMX', '¡Lucha como si fuera lo último que hará\' en tu vida! ¡Todo está en juego!', '', 28153),
(136762, 'esMX', 'No solo luchamos para proteger a la gente, sino también para proteger el futuro de lo\' zandalari. No te lo tomes a la ligera.', '', 28153),
(136761, 'esMX', 'Ataca con velocidad, pero nunca olvides a lo\' soldados que tienes a tu alrededor.', '', 28153),
(136760, 'esMX', 'Debe\' golpear al objetivo con fuerza... pero también con aplomo.', '', 28153),
(136759, 'esMX', 'He cabalgado muchas veces en la arena. ¡No creo que sea tan diferente aquí!', '', 28153),
(136758, 'esMX', '', 'Sujeta las riendas con fuerza, Eddie.', 28153),
(136757, 'esMX', '', 'Lord Norwington me confió la tarea de enseñarle equitación a su hijo. Lo ha hecho muy bien en la arena, pero me preocupa llevarlo a otro lugar. No sé si podrá detener a su poni si lo asustan.$b$b¡Pero esperemos que eso no suceda!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136756, 'esMX', 'Relámpago nunca se asustaría. ¡Es un buen chico!', '', 28153),
(136755, 'esMX', '¡Creo que está escuchando, mira sus orejas!', '', 28153),
(136754, 'esMX', '¡Eso hago, eso hago!', '', 28153),
(136753, 'esMX', '', 'Tranquilo, despacio. Cualquier cosa podría asustarlo.', 28153),
(136752, 'esMX', '', 'Trata de que se concentre en ti, ¡que no se distraiga con el entorno!', 28153),
(136751, 'esMX', '', 'Eddie, usa las piernas para girar, no las manos.', 28153),
(136750, 'esMX', 'Hmmm... ¿Un desierto en medio de un pantano? ¿Qué es lo que planean los sethrak?', '', 28153),
(136747, 'esMX', 'Gracias por salvarme de esos despreciables sauroliscos. Nunca más iré al lecho del río solo... ¡hasta que sea mayor al menos!', '', 28153),
(136746, 'esMX', '¿Hola? ¿Hay alguien ahí?', '', 28153),
(136745, 'esMX', 'La Alianza no está a la altura de nuestro poder. ¡Por la Horda!', '', 28153),
(136744, 'esMX', '¡El Puerto de Zem\'lan e\' mío!', '', 28153),
(136741, 'esMX', 'Sur\'jan, ¡no digas locura\'! No nos iremo\' de Nazmir después de esto. Jamá\' regresaré a Zuldazar.', '', 28153),
(136740, 'esMX', 'Con tu ayuda, me volveré lo suficientemente fuerte para que podamo\' vencer a Urok otra vez. Estaré aquí esperando para preparar el próximo ritual.', '', 28153),
(136738, 'esMX', '¡Esos monstruos iban a comerme!', '', 28153),
(136732, 'esMX', '¿Qué dices, Sur\'jan? ... Hmm, de acuerdo, tiene\' razón.', '', 28153),
(136731, 'esMX', 'Sur\'jan, yo debería ser el que se encargue de todo eh\'to. No me gusta quedarme de brazos cruzado\' y ver cómo los demás trabajan.', '', 28153),
(136730, 'esMX', '¡Me adelantaré! Prepara todo para luchar contra Urok.', '', 28153),
(136729, 'esMX', 'Papá dice que puedo participar en las celebraciones de este año. ¡Al fin me enseñarán a cabalgar!', '', 28153),
(136728, 'esMX', 'Yo me ocupo de conservar el equilibrio de la naturaleza.\n\nCállate, Sur\'jan, claro que me importa el equilibrio de la naturaleza. ... un poco. $UÉl:Ella; no necesita saberlo.', '', 28153),
(136727, 'esMX', 'Ese pantano eh\'tá lleno de horrores. Si quieres sobrevivir en ese lugar debes convertirte en parte de ese horror.', '', 28153),
(136726, 'esMX', 'La maldición... ¿ha terminado? Al fin soy... ¿libre?', '', 28153),
(136725, 'esMX', 'Tú estás en tierra maldita... Nadie sale... ¡jamás!', '', 28153),
(136724, 'esMX', '', 'En las sombras de Zem\'lan hay monstruos ocultos.\n\nTen cuidado, no te conviertas en uno de ellos.', 28153),
(136723, 'esMX', 'La fa-fa-familia siempre está unida, en las buenas y en las malas.', '', 28153),
(136722, 'esMX', 'Y no eh\'toy bromeando. Quiero ver muerto a ese trol, al igual que a Urok. Buena cacería.', '', 28153),
(136721, 'esMX', 'No sea\' estúpido, Sur\'jan. $UÉl:Ella; no cree que es una broma. Bueno, de acuerdo, solo déjame asegurarme.', '', 28153),
(136720, 'esMX', 'Fue un honor trabajar contigo. Si ve\' a un trol llamado Krugah, asegúrate de matarlo. ¡Ja!', '', 28153),
(136719, 'esMX', 'No perdamo\' más tiempo. ¡Debemos acabar con Urok!', '', 28153),
(136718, 'esMX', '¡SÍ! Ha llegado la hora... ¡Acabaremo\' con Urok!', '', 28153),
(136717, 'esMX', 'Puedo sentir... ¡el poder que regresa a mí!', '', 28153),
(136713, 'esMX', '¡Ja, JA! Ya casi estoy listo... ¡Ya casi estamo\' listo para matar a Urok!', '', 28153),
(136712, 'esMX', 'Sí... ¡Siento que el poder regresa a mi cuerpo!', '', 28153),
(136711, 'esMX', 'Ah... ¡MÁS! ¡Necesitaremo\' más poder si queremos matar a Urok!', '', 28153),
(136710, 'esMX', 'Eso eh\' todo lo que necesito... ¡Ahora, es tiempo de aumentar mi poder!', '', 28153),
(136698, 'esMX', 'Nosotros somos los afortunados. Tú no. Todavía no.', '', 28153),
(136697, 'esMX', 'Ella busca eso que solo puede obtenerse por medio del sacrificio.', '', 28153),
(136696, 'esMX', '', 'Detrás de este pequeño mar de estrellas no hay más que oscuridad eterna.', 28153),
(136695, 'esMX', '', 'Dile a mi papá que lo perdono.', 28153),
(136694, 'esMX', '', '¿Aún no te ha traicionado? Lo hará...', 28153),
(136693, 'esMX', '', 'Morirás en soledad.', 28153),
(136692, 'esMX', '', 'El maestro espera a que te unas a él...', 28153),
(136691, 'esMX', '', 'Se ha despertado. Y ha notado tu presencia.', 28153),
(136690, 'esMX', '', 'Pronto te unirás a nosotros.', 28153),
(136689, 'esMX', '', 'Sé lo que has hecho.', 28153),
(136688, 'esMX', '', 'Oyes una risa apagada.', 28153),
(136687, 'esMX', '', 'Sientes que te observan.', 28153),
(136686, 'esMX', '', 'Te están observando.', 28153),
(136685, 'esMX', '', 'La Seguidora fantasmal se ríe y sale corriendo.', 28153),
(136684, 'esMX', 'Nuestra próxima reunión será la última...', '', 28153),
(136683, 'esMX', '¡Tu alma será mía, $gintruso:intrusa;!', '', 28153),
(136681, 'esMX', 'Tu presencia e\' profana. ¡Ten cuidado de la ira de Xibala!', 'Tu presencia e\' profana. ¡Ten cuidado de la ira de Xibala!', 28153),
(136680, 'esMX', '', '¡Si quiere\' el mejor mojo y los mejore\' abalorios robados del sur, ven a ver a Wunja!', 28153),
(136679, 'esMX', '$gEh\'túpido:Eh\'túpida; mortal. ¡Xibala te destruirá!', '$gEh\'túpido:Eh\'túpida; mortal. ¡Xibala te destruirá!', 28153),
(136678, 'esMX', 'Volaremos sobre Ata el Señor Alado para eh\'te viaje. Sube y mantén los ojos abierto\'.', '', 28153),
(136677, 'esMX', 'Como dice siempre mi loa: si no encuentras la fuente de corrupción, sigue subiendo.', '', 28153),
(136676, 'esMX', 'La filosofía de Loti me parece muy terrenal. Yo analizo las cosa\' a vuelo de pterrordáctilo.', '', 28153),
(136674, 'esMX', 'Listo para patrullar.', 'Lista para patrullar.', 28153),
(136673, 'esMX', '', '¡Soy la druida guerrera Loti! Soy el conducto de Gonk, loa de las forma\' y maeh\'tra de la cacería.$b$bTambién soy miembro del Concilio zanchuli, pero eh\'toy segura de que eso ya lo sabías.', 28153),
(136672, 'esMX', 'El portador le hace un gesto al guardia zandalari.', '', 28153),
(136671, 'esMX', 'El guardia te examina de pies a cabeza.', '', 28153),
(136670, 'esMX', 'El guardia se percata de tu presencia.', '', 28153),
(136669, 'esMX', '¡Será mejor que haya\' aprendido la lección!', '¡Será mejor que haya\' aprendido la lección!', 28153),
(136668, 'esMX', 'El guardia te saluda mientras pasas a su lado.', '', 28153),
(136667, 'esMX', 'El guardia hace un gesto con la cabeza en tu dirección.', '', 28153),
(136662, 'esMX', 'Estás delante del señor aojador Raal, sumo sacerdote de la gran loa Pa\'ku, maestra de los viento\' y de nueh\'tras naves, y miembro del Concilio zanchuli.\n\n¿Qué quieres?', '', 28153),
(136657, 'esMX', 'Trabajo, trabajo.', '', 28153),
(136655, 'esMX', '', 'Que la Luz te conceda paz, $c.', 28153),
(136654, 'esMX', '¡Estúpido Sur\'jan! ¿Por qué abre\' la bocota en frente de todos? ¡Creerán que estás loco!', '', 28153),
(136653, 'esMX', 'Saldré a preparar todo para el ritual. Podremo\' matar a Urok una vez que recupere mi poder.', '', 28153),
(136652, 'esMX', 'Ya sé, creen que estoy loco porque vivo en Nazmir, ¡pero tienen que escucharme! ¡Todo\' morirán si no me ayudan!', '', 28153),
(136651, 'esMX', '¡Ya sé que cree\' que estoy loco, pero necesito que me ayudes!', '', 28153),
(136650, 'esMX', '¡Deja de ignorarme! ¡Necesito tu ayuda!', '', 28153),
(136649, 'esMX', 'Listo, ya no tiene su protección. ¡Acabemo\' con él!', '', 28153),
(136648, 'esMX', '', '¡Renazco gracias a G\'huun!', 28153),
(136647, 'esMX', 'Las cosa\' complicadas te las dejo a ti. Estaré afuera de la guarida de Urok.', '', 28153),
(136646, 'esMX', '¡JA! ¡Lo hicimo\'! Te lo dije, Sur\'jan. ¡Lo vencimos!', '', 28153),
(136645, 'esMX', '¡Adalid! ¡Encárgate de esa bruja! ¡Esas pilas de hueso\' a las que llama\' \"esbirros\" caerán ante el verdadero amo de la muerte!', '', 28153),
(136644, 'esMX', '¡Lo\' tótems protegen a Urok! ¡Usa mi antorcha para quemarlos!', '', 28153),
(136643, 'esMX', '<La mochila medio enterrada está cubierta con arena, pero su contenido parece estar en buenas condiciones.>', '', 28153),
(136642, 'esMX', '', '¿Acaso no te advertí que te alejaras de ese lugar? ¡Apenas te sacamos con vida!', 28153),
(136641, 'esMX', '¡La muerte viene por ti!', '¡La muerte viene por ti!', 28153),
(136640, 'esMX', '¡$GIntruso:Intrusa;!', '¡$GIntruso:Intrusa;!', 28153),
(136639, 'esMX', '¡Únete a nosotros!', '¡Únete a nosotros!', 28153),
(136638, 'esMX', '', '¡No permitiré que interrumpan mi trabajo! ¡Destruyan a este insecto!', 28153),
(136637, 'esMX', '¡Vamoh\', vamoh\', vamoh\'!', '¡Vamoh\', vamoh\', vamoh\'!', 28153),
(136632, 'esMX', 'Jaja, ¡acabaré con este!', '', 28153),
(136615, 'esMX', '', '¡De pie, esbirros! ¡Levántense y deh\'truyan a este loa imprudente!', 28153),
(136614, 'esMX', 'Necesito tu ayuda... Algo malo se acerca, ¡y no puedo matarlo solo!', '', 28153),
(136613, 'esMX', '', 'Palabras osada\', ¡pero sufrirás el mismo destino que los que rechazan a G\'huun!', 28153),
(136611, 'esMX', '¡Nadie le dice a Bwonsamdi lo que tiene que hacer! ¿Crees que puede\' conmigo, infeliz?', '', 28153),
(136610, 'esMX', 'Mmmm... Pareces inteligente, mujer. Sin embargo, te atreve\' a interrumpirme en mi propio templo.', '', 28153),
(136609, 'esMX', '', 'Te ofrezco una oportunidad para someterte al dios de la sangre. Ríndete... ¡o serás deh\'truido!', 28153),
(136608, 'esMX', '', '¡Bwonsamdi! Por fin abandonah\'te la seguridad de esa ruina.', 28153),
(136607, 'esMX', '¿Qué hace\' ahí, holgazaneando? ¡Empecemos!', '', 28153),
(136605, 'esMX', 'Empecemos.', 'Empecemos.', 28153),
(136604, 'esMX', 'El rito vinculante es un mojo antiguo, muy antiguo. Tan viejo como el mundo. Con este mojo, Bwonsamdi se apoderará del alma de todo lo que mates. Si aceptas eh\'te rito, tenemos un trato.$b$b¿Estás $Ulisto:lista;? Yo sí.', '', 28153),
(136603, 'esMX', '', '¿Qué sucede, continental?', 28153),
(136602, 'esMX', '', 'Mis conscriptos están listos para defender a los aldeanos. ¿Comenzamos la evacuación?', 28153),
(136601, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(136600, 'esMX', 'Ese truco no me gustó nada, Pinky. ¡Demosaurio malo! ¡Malo!', 'Ese truco no me gustó nada, Pinky. ¡Demosaurio malo! ¡Malo!', 28153),
(136599, 'esMX', 'Ven a la Corte de Eh\'píritus. Es hora de cumplir nuestro... contrato.', '', 28153),
(136591, 'esMX', 'Eh\'to no es un debate, hermana. $n y yo tenemos órdene\' de la princesa.', '', 28153),
(136590, 'esMX', '', 'Y luego me ordenó que me asegurara de que $n y \"el bonito\", según dijo, llegaran a Nazmir lo ante\' posible.', 28153),
(136589, 'esMX', '¡El arrastrapiés se ha rebelado contra sus amos!', '', 28153),
(136588, 'esMX', 'El cautivo parece incapaz de moverse por unos instantes.', '', 28153),
(136587, 'esMX', '¡El cautivo entra en frenesí!', '', 28153),
(136581, 'esMX', 'Encárgate de $geste intruso:esta intrusa;, Guardamar. Que se haga mi voluntad.', '', 28153),
(136578, 'esMX', 'Presentando respetos', '', 28153),
(136577, 'esMX', 'Apuesto mis botas a que encontraremos más armas de Aspafresno en los muelles. Debemos saber quién las está comprando.', '', 28153),
(136576, 'esMX', '', 'Somos muchas hermanas... Kul Tiras caerá...', 28153),
(136575, 'esMX', '', '¡No puedes vencer! ¡El aquelarre no se detendrá hasta que todos se arrodillen!', 28153),
(136574, 'esMX', '', '¡Enfréntate a mi ira!', 28153),
(136573, 'esMX', '', 'Impresionante... ¡pero necesitarás más que eso para vencer a una matriarca del aquelarre Hiel de corazón!', 28153),
(136572, 'esMX', '', 'No importa. ¡Ahora sabrás lo que les sucede a los enemigos del aquelarre! ¡Acólitos, destruyan al peón rebelde!', 28153),
(136571, 'esMX', '', 'Así que $Gun iluso entrometido:una ilusa entrometida; logró ponernos a una de nuestras creaciones en contra. Debes creerte tan $Gastuto:astuta;.', 28153),
(136570, 'esMX', 'Nunca había visto tanto movimiento por aquí. Debe estar pasando algo importante.', '', 28153),
(136569, 'esMX', 'Corsarios, mercenarios... Hasta los piratas son bienvenidos. Y por eso es una ciudad... colorida.', '', 28153),
(136568, 'esMX', 'Puerto Libre es un \"puerto de gente libre\". A diferencia de Boralus, no tiene leyes ni reglas para los barcos que quieren atracar en el puerto.', '', 28153),
(136567, 'esMX', '', 'Lo siento, $c. No nos quedan más algas. Todos están demasiado enfermos para ir al agua a cosecharlas. Pídele disculpas a Therold de mi parte.', 28153),
(136566, 'esMX', '', 'Mis hermanas me vengarán...', 28153),
(136565, 'esMX', '', '¡No deberías... haber... interferido!', 28153),
(136564, 'esMX', '¿Tienes algunas algas? Therold las necesita para un antídoto.', '¿Tienes algunas algas? Therold las necesita para un antídoto.', 28153),
(136563, 'esMX', '', 'Caerás... ante... la matrona...', 28153),
(136562, 'esMX', '', '¡Este pueblo pertenece al aquelarre!', 28153),
(136561, 'esMX', '', '¡Tanto por hacer y tan poco tiempo!$b$bDebo bendecir a los pescadores y su equipamiento, leer las mareas en busca de presagios, rezar por el regreso de los marineros...', 28153),
(136560, 'esMX', '', 'El aquelarre te consumirá...', 28153),
(136559, 'esMX', '', '¡El aquelarre infestará todo!', 28153),
(136558, 'esMX', 'Las sirenas están muy activas hoy, pero no abandonan el terreno. Mantente $galejado:alejada; de las islas y no tendremos inconvenientes.', 'Las sirenas están muy activas hoy, pero no abandonan el terreno. Mantente $galejado:alejada; de las islas y no tendremos inconvenientes.', 28153),
(136557, 'esMX', 'Las mareas se agitan con fuerza en el este, pero las aguas están calmas en el oeste.', 'Las mareas se agitan con fuerza en el este, pero las aguas están calmas en el oeste.', 28153),
(136556, 'esMX', 'Mi bendición te mantendrá a salvo incluso en el agua.', 'Mi bendición te mantendrá a salvo incluso en el agua.', 28153),
(136555, 'esMX', 'Envía a los pescadores al muelle cerca del mercado. Habrá muchos peces allí hoy.', 'Envía a los pescadores al muelle cerca del mercado. Habrá muchos peces allí hoy.', 28153),
(136554, 'esMX', 'Todos nos sentiremos a salvo si tú nos guías.', 'Todos nos sentiremos a salvo si tú nos guías.', 28153),
(136553, 'esMX', 'Debemos realizar una excursión a las aguas más profundas. ¿Cuál será el mejor camino?', 'Debemos realizar una excursión en las aguas más profundas. ¿Cuál será el mejor camino?', 28153),
(136552, 'esMX', 'Entonces no tenemos de qué preocuparnos. ¡Gracias!', 'Entonces no tenemos de qué preocuparnos. ¡Gracias!', 28153),
(136551, 'esMX', 'Planeamos una excursión a las aguas más profundas. ¿Cómo se mueven las mareas?', 'Planeamos una excursión a las aguas más profundas. ¿Cómo se mueven las mareas?', 28153),
(136550, 'esMX', 'Siento que tu bendición recorre todo mi cuerpo. Te agradezco profundamente.', 'Siento que tu bendición recorre todo mi cuerpo. Te agradezco profundamente.', 28153),
(136549, 'esMX', 'Estoy preparándome para dirigirme al territorio de los monstruos. Por favor, ¡concédeme tu bendición!', 'Estoy preparándome para dirigirme al territorio de los monstruos. Por favor, ¡concédeme tu bendición!', 28153),
(136548, 'esMX', 'Les informaré a los pescadores.', 'Les informaré a los pescadores.', 28153),
(136547, 'esMX', '¿Dónde habrá más peces hoy?', '¿Dónde habrá más peces hoy?', 28153),
(136546, 'esMX', '¡Eh! Todo el redil habla sobre ti, $uforastero:forastera;. ¡Dicen que ere\' excepcionalmente valiente!', '', 28153),
(136545, 'esMX', '', 'Tú está\' entre lo\' que caminan con lo\' loa. Camina con cuidado, lo\' loa no siempre se tratan bien entre sí.', 28153),
(136538, 'esMX', '¡Guerreros de la Horda! Hoy levantamos nuestras hachas y espadas con sed de sangre enemiga.', '', 28153),
(136533, 'esMX', 'Mekkatorque, ¿podemos eludir el añublo con tus máquinas voladoras?', '', 28153),
(136532, 'esMX', '', '¡Pelearemos a tu lado, rey Wrynn!', 28153),
(136528, 'esMX', '¡Jaina! Bloquea las salidas. ¡No dejes que llamen refuerzos!', '', 28153),
(136527, 'esMX', '¡Eh\'te templo caerá! ¡La sacerdotisa lo predijo!', '', 28153),
(136526, 'esMX', '¡Protejan a la sacerdotisa!', '', 28153),
(136525, 'esMX', 'La sacerdotisa necesita sangre para el ritual. La tuya bastará.', '', 28153),
(136524, 'esMX', '¡Por la sacerdotisa! ¡Por G\'huun!', '', 28153),
(136523, 'esMX', '¡Bwonsamdi no tiene poder sobre nosotros! ¡Por el dio\' de la sangre!', '', 28153),
(136522, 'esMX', '¡Por la Señora de la guerra!', '', 28153),
(136521, 'esMX', '¡$gIntruso:Intrusa;! ¡Te aplasto!', '', 28153),
(136520, 'esMX', '¡Por la Señora de la guerra Malaka! ¡Por el dio\' de la sangre!', '', 28153),
(136519, 'esMX', '¡Será\' $Uun esclavo:una esclava; excelente para la Señora de la guerra!', '', 28153),
(136518, 'esMX', '', '¿Cómo te atreves a interrumpir mi ritual?', 28153),
(136517, 'esMX', '', '¡Bah\'ta! ¡Dije que lo iba a pensar!', 28153),
(136516, 'esMX', 'Pero podrían duplicar... ¡¿qué digo?! ¡Triplicar su producción! Mis elíxires son cien por ciento naturales, te lo garantizo...', '', 28153),
(136515, 'esMX', '', 'No sé... Nueh\'tros métodos funcionan bien y...', 28153),
(136514, 'esMX', '¡Déjame decirte que te estás perdiendo una oportunidad enoooooooooorme! ¡Acepta mi recomendación y no la dejes pasar!', '', 28153),
(136513, 'esMX', '', '¡Te arrepentirá\' de esto!', 28153),
(136512, 'esMX', '', '¡Que comience el ritual! ¡Abandonaré eh\'ta forma frágil y ascenderé!', 28153),
(136511, 'esMX', 'No hay nada que ver aquí. ¡Sigan su camino!', '', 28153),
(136510, 'esMX', 'No me obligues a lastimarte, $gamiguito:amiguita;.', '', 28153),
(136509, 'esMX', '¡Ey! ¿Qué crees que estás haciendo aquí?', '', 28153),
(136508, 'esMX', '', 'Todos se someterán... a la voluntad del dio\' de la sangre...', 28153),
(136507, 'esMX', '', '¡Más sangre para el dio\' de la sangre!', 28153),
(136498, 'esMX', '¡Todos están locos! ¡Yo mejor me marcho mientras pueda!', '', 28153),
(136497, 'esMX', '', 'Se ha terminado.\n\nYo... Era necesario. La corrupción se había apoderado de ella.\n\n<Rebecca solloza.>\n\nLo siento. Necesito... un poco de tiempo.', 28153),
(136495, 'esMX', '', 'Al principio, creí que lo que mi hermana estaba haciendo era divertido, ¡pero esto es una locura!\n\n¡En su grimorio habla sobre crear un ejército con estos ensamblajes antiguos! ¡Si no la detenemos, esclavizará todo Drustvar!', 28153),
(136494, 'esMX', '¡Fuera!', '¡Fuera!', 28153),
(136493, 'esMX', '', 'Espero que mi mamá y yo volvamo\' a verte.', 28153),
(136492, 'esMX', '', 'Es cierto... mi mamá cometió errores. Pero la perdono. Ahora podemoh\' pasar el resto de la eternidad juntas en el Otro Lado.', 28153),
(136491, 'esMX', '', 'Ahora mi mamá y yo estaremoh\' juntas... ¡para siempre!', 28153),
(136490, 'esMX', '', '¡Noooo...! Yo debía vivir... para siempre...', 28153),
(136489, 'esMX', 'Ten cuidado. Hay unas criaturas muy malvadas aquí.', '', 28153),
(136488, 'esMX', '', '¿Qué es eh\'to? ¡No! ¡Cómo te atreves a traer a esa COSA a este lugar!', 28153),
(136487, 'esMX', '', '¡Te encontramo\', mamá!', 28153),
(136486, 'esMX', '', '¿Quién osa perturbar mi descanso?', 28153),
(136485, 'esMX', '<Intenta abrir el sarcófago.>', '<Intenta abrir el sarcófago.>', 28153),
(136484, 'esMX', '<El sarcófago está cerrado firmemente, pero podrás abrirlo con un poco de esfuerzo.>', '', 28153),
(136483, 'esMX', '', '¡Creo que eh\'tamos cerca! ¡Mamá! ¿Dónde estáh\'?', 28153),
(136482, 'esMX', '', '¡Está muy oh\'curo! Ve adelante, yo te seguiré.', 28153),
(136481, 'esMX', '', 'No, no, esa eh\' la cripta de la gran reina. Mamá se metería en problemas si entrara ahí.', 28153),
(136480, 'esMX', '', 'Agh... Ese sacerdote huele a gusanoh\' viejos. No, mamá no se habría metido ahí.', 28153),
(136479, 'esMX', '', 'Mamá y yo conocimos a los sacerdoteh\' de este lugar. También me dieron eh\'tas ropas. ¡Fueron muy amables!', 28153),
(136478, 'esMX', '¡Sabía que no estabas a mi altura!', '¡Sabía que no estabas a mi altura!', 28153),
(136477, 'esMX', '', 'No, creo que no eh\' aquí. Nunca dejan entrar a nadie al templo principal.', 28153),
(136476, 'esMX', 'Tengo que entrenar más...', 'Tengo que entrenar más...', 28153),
(136475, 'esMX', 'Arggh... eres más fuerte de lo que esperaba.', 'Arggh... eres más fuerte de lo que esperaba.', 28153),
(136474, 'esMX', '¡Ya basta! ¡Me rindo!', '¡Ya basta! ¡Me rindo!', 28153),
(136473, 'esMX', 'Ganaste. Esta vez...', 'Ganaste. Esta vez...', 28153),
(136472, 'esMX', '¡Basta! ¡Me rindo!', '¡Basta! ¡Me rindo!', 28153),
(136471, 'esMX', '¡Trata de no mancharme con tu sangre!', '¡Trata de no mancharme con tu sangre!', 28153),
(136470, 'esMX', '¡Fuiste $gun necio:una necia; al desafiarme!', '¡Fuiste $gun necio:una necia; al desafiarme!', 28153),
(136469, 'esMX', '¡Veamos si tu espada está tan afilada como tu lengua!', '¡Veamos si tu espada está tan afilada como tu lengua!', 28153),
(136468, 'esMX', '¿Te atreves a desafiarme? ¡Te haré sangrar toda tu sangre!', '¿Te atreves a desafiarme? ¡Te haré sangrar toda tu sangre!', 28153),
(136467, 'esMX', '¡Pelear contra mí será tu último error!', '¡Pelear contra mí será tu último error!', 28153),
(136466, 'esMX', 'Si lo que quieres es una paliza... ¡pues tendrás una paliza!', 'Si lo que quieres es una paliza... ¡pues tendrás una paliza!', 28153),
(136465, 'esMX', '', 'Dijo que iría a un lugar oscuro y tenebroso. Me pregunto qué lugar será. Aj... ¡Odio los lugare\' oscuros!', 28153),
(136464, 'esMX', '', '¡Sí! Mamá mencionó un trato con Bwonsamdi. Seguramente sigue en el templo.', 28153),
(136463, 'esMX', 'Razgaji me dijo que te retara a duelo.', 'Razgaji me dijo que te retara a duelo.', 28153),
(136462, 'esMX', 'Será mejor que te cuides... No me agradan los extraños.', 'Será mejor que te cuides... No me agradan los extraños.', 28153),
(136461, 'esMX', 'Pregúntame cómo terminé en Vol\'dun y te daré una lista de cementerios para que visites...', 'Pregúntame cómo terminé en Vol\'dun y te daré una lista de cementerios para que visites...', 28153),
(136460, 'esMX', 'Tienes hasta la cuenta de tres para dar la vuelta y marcharte... ¡Tres!', 'Tienes hasta la cuenta de tres para dar la vuelta y marcharte... ¡Tres!', 28153),
(136459, 'esMX', '¿No ves que estoy entrenando? ¡Lárgate!', '¿No ves que estoy entrenando? ¡Lárgate!', 28153),
(136458, 'esMX', 'Rokhan, estoy aquí para ayudarte a ti y a la princesa Talanji a investigar en Nazmir.', 'Rokhan, estoy aquí para ayudarte a ti y a la princesa Talanji a investigar en Nazmir.', 28153),
(136457, 'esMX', 'La princesa Talanji nos ordenó ir a Nazmir. Necesitaremo\' que sus pterrordáctilo\' nos lleven.', '', 28153),
(136453, 'esMX', '', 'Hagan todo lo que sea necesario para adueñarse del pueblo. Yo misma iré allí para investigar las ruinas.', 28153),
(136451, 'esMX', '', 'Es posible que la tumba que tiene dentro contenga reliquias poderosas que podemos aprovechar para nuestros rituales.', 28153),
(136450, 'esMX', '', 'Los mineros de Hondonada Fletcher se han topado con una ruina que nadie había pisado, oculta en las profundidades de la Mina Rocantigua.', 28153),
(136449, 'esMX', '', 'Hermanas del aquelarre, presten atención.', 28153),
(136448, 'esMX', '', 'He perdido a dos de mis mejores hombres ahí dentro. No te conviertas en $Uel tercero:la tercera;.', 28153),
(136447, 'esMX', '', 'No sé qué estarán planeando, pero la magia que emana de ese lugar parece drenarte la vida.', 28153),
(136446, 'esMX', '', 'Un consejo, continental: evita la mina a cualquier costo.', 28153),
(136445, 'esMX', '', 'Ese era el último de los aldeanos. Si tienen suerte, llegarán a Amparo del Ocaso a salvo.', 28153),
(136444, 'esMX', '', '¡Parece que están enviando la artillería pesada! ¡Prepárense, muchachos!', 28153),
(136443, 'esMX', '', '¡Más atacantes del pueblo! ¡Mantengan la posición!', 28153),
(136442, 'esMX', '', 'Parece que nos descubrieron. ¡Protejan a los civiles!', 28153),
(136441, 'esMX', '', '¡$C, ocupa una posición y repele todos los ataques que vengan del pueblo!', 28153),
(136440, 'esMX', '', 'De acuerdo, muchachos, aseguremos este camino para poner a salvo a los espectadores.', 28153),
(136439, 'esMX', '', 'Espero que hayas traído un ejército en esa mochila que traes.', 28153),
(136438, 'esMX', '', '¿Oyeron eso, muchachos? ¡$GEl:La; continental nos ayudará a recuperar nuestro pueblo!', 28153),
(136437, 'esMX', '', 'Bien, digamos que esas personas de mimbre espeluznantes no son tan indefensas como parecen.\n\nTodo empezó hace algunas semanas con la desaparición de algunos de los mineros. Después, de repente, aparecieron esas criaturas y empezaron a expulsarnos de la ciudad. Estos eventos coincidieron con la llegada de esa muchacha Tarjasenda que anduvo husmeando por aquí, pero aun después de su partida los problemas empeoraron.\n\nAhora, esas cosas no solo han tomado el control sino que también han capturado a la mayoría de nuestros aldeanos. Logré conservar este punto con un puñado de voluntarios, pero no tengo idea de cómo haré para recuperar mi pueblo.\n\nAsí que a menos que quieras quedarte a ayudar, te sugiero que te marches.', 28153),
(136436, 'esMX', 'Estoy aquí para ayudar.', 'Estoy aquí para ayudar.', 28153),
(136435, 'esMX', '¿Qué ocurre aquí?', '¿Qué ocurre aquí?', 28153),
(136434, 'esMX', '', 'Desde que estas horribles criaturas empezaron a salir en masa de las minas, nuestra aldea ha quedado sumida en el caos. \n\nEspero que tengas más suerte que nosotros para encontrar la fuente de este desastre.', 28153),
(136432, 'esMX', 'Te ayudaré a encontrar a tu madre.', 'Te ayudaré a encontrar a tu madre.', 28153),
(136431, 'esMX', 'Has sido muy paciente.', 'Has sido muy paciente.', 28153),
(136430, 'esMX', '', 'Estoy taaan sola aquí sin mi mamá...$b$b¿Me ayudarías a buscarla? ¡Por favor! Te prometo que no moleh\'taré.', 28153),
(136429, 'esMX', '', 'Mamá me dijo que la eh\'perara aquí. ¡He eh\'perado años y mamá no vuelve!$b$bEstoy cansada de eh\'perar. ¡Quiero a mi mamá!', 28153),
(136428, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(136427, 'esMX', '', '¿Dónde eh\'tá mamá? ¡Quiero ir a casa!', 28153),
(136426, 'esMX', '', '¿A dónde fue mamá? Se fue hace mucho.', 28153),
(136425, 'esMX', '', 'Hace mucho frío... ¿Dónde eh\'tá mamá?', 28153),
(136422, 'esMX', '¿Alguien ma\' quiere ir a Nazmir? No volverás, créeme.', '', 28153),
(136421, 'esMX', '', 'Hmm... No digas más. Me dirigiré a Nazmir. Espero que podamos reunirno\' con la princesa.', 28153),
(136420, 'esMX', '¿Talanji ya está en Nazmir? Entonce\' será mejor que me apresure. Nos vemo\' ahí.', '', 28153),
(136419, 'esMX', '', 'No hay tiempo que perder. Hace días que no tenemos noticias de Halcónida.', 28153),
(136418, 'esMX', '', 'Cre-creo que puedo es-escabullirme hasta la cueva donde está mi hermana. Nos veremos ahí.', 28153),
(136417, 'esMX', '', 'Me dirigiré a Nazmir. Nos vemo\' ahí.', 28153),
(136415, 'esMX', 'No es fácil encontrar ingrediente\' de calidad en Vol\'dun, pero si come\' rápido y cierras los ojo\' la comida no es tan horrible como parece.', '', 28153),
(136414, 'esMX', '¡Si quiere\' aprender acerca de las alpaca\', has venido al lugar indicado! Sé todo lo que hay que saber, y mucho má\'.', '', 28153),
(136413, 'esMX', 'Puede que Vol\'dun sea un páramo traicionero, pero es el único hogar que tengo.', '', 28153),
(136407, 'esMX', 'Iremo\' a un lugar que ningún habitante de Zuldazar quiere pisar. Prepárate.', '', 28153),
(136406, 'esMX', '¡MACHACAR!', '', 28153),
(136405, 'esMX', 'Me acompaña $Geh\'te forastero:eh\'ta forastera; que desea hablar contigo, poderoso loa.', '', 28153),
(136404, 'esMX', 'Ven. E\' por aquí.', '', 28153),
(136403, 'esMX', '¡Ah, jajaja! Conozco esa voz! Y estos obsequio\', muy bonitos. ¡Pasen, pasen!', '', 28153),
(136402, 'esMX', '¡El premio mayor está en camino! ¡Traigan refuerzos!', '', 28153),
(136398, 'esMX', '¡Mi piel! ¡Me quemo!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136397, 'esMX', '¡Ahhhhh!', '', 28153),
(136396, 'esMX', 'Gran Bwonsamdi, ¡el tambor suena en tu nombre! ¡Recibe eh\'tas ofrendas!', '', 28153),
(136395, 'esMX', '¡Doba quzhu ta tawbo! ¡Metah bo chu!', '', 28153),
(136394, 'esMX', 'Muy bien. ¡Ahora toca el tambor!', '', 28153),
(136393, 'esMX', 'Deja que la visión guíe tus paso\' para formar el círculo ritual. ¡Pero cuidado! Bwonsamdi no estará feliz si el ritual no eh\' perfecto.', '', 28153),
(136388, 'esMX', '¿Ya terminaste con tu otro trabajito? ¿Qué tal si mostramos <hic> un poco de profesionalismo?', '', 28153),
(136387, 'esMX', '¿Aguijones tóxicos? Seguramente son para un propósito totalmente legítimo.', '', 28153),
(136386, 'esMX', '¡Ey, es peligroso allí afuera! <hic> ¡Realmente deberías quedarte conmigo!', '', 28153),
(136385, 'esMX', 'Yo, uh... Creo que solo voy a esperar.', '', 28153),
(136384, 'esMX', '<hic> ¡Por aquí!', '', 28153),
(136383, 'esMX', '¡Oye! ¿Q-Qué estás esperando?', '', 28153),
(136382, 'esMX', '<hic> Hola, lagarto.', '', 28153),
(136380, 'esMX', '¡Preparen sus espadas! ¡Lok\'tar ogar!', '', 28153),
(136379, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Cavar túnel', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Cavar túnel', 28153),
(136378, 'esMX', 'Ey, colega. Te contaré sobre la tecnología de punta para el frente de batalla:\n\nlos túneles.\n\nAsí es. Por tan solo UNA pila enorme de oro, mi socio y yo cavaremos un túnel hasta las líneas del frente para ti y tus camaradas. ¿Qué dices?', '', 28153),
(136377, 'esMX', 'Este es un pueblo rudo. Deja <hic> que yo me encargue de hablar.', '', 28153),
(136376, 'esMX', 'Aquí estamos. Puerto Libre.', '', 28153),
(136375, 'esMX', 'Hmmm... Fuimos a la derecha la última vez... ¡así que DEBE ser a la izquierda! Creo que al fin se me está despejando la cabeza.', '', 28153),
(136374, 'esMX', '', '¡Debemo\' llevar la esfera de regreso al campamento ante\' de que los sethrak noten su ausencia! ¡Rápido!', 28153),
(136373, 'esMX', 'Ahh... Estamos cerca, lo presiento.', '', 28153),
(136372, 'esMX', 'Uff, qué paseo. Solo necesito otro sorbo...', '', 28153),
(136371, 'esMX', '¿Q... Qué? ¿Quién eres? ¿Y eso?', '¿Q... Qué? ¿Quién eres? ¿Y eso?', 28153),
(136370, 'esMX', '¡¿Esa cosa estaba controlando mi mente?!', '¡¿Esa cosa estaba controlando mi mente?!', 28153),
(136369, 'esMX', '¡Ajá! Esto me parece familiar. Creo que, ejem, estamos en el camino correcto.', '', 28153),
(136368, 'esMX', '¿Qué... qué pasó?', '¿Qué... qué pasó?', 28153),
(136367, 'esMX', 'Uq naggwa... Nuestro amo... viene a buscarte...', 'Uq naggwa... Nuestro amo... viene a buscarte...', 28153),
(136366, 'esMX', '¡Llegas demasiado tarde! ¡No puedes detener la marea que se alza frente a ti!', '¡Llegas demasiado tarde! ¡No puedes detener la marea que se alza frente a ti!', 28153),
(136365, 'esMX', 'Ahh, así está mejor. Vamos.', '', 28153),
(136364, 'esMX', 'Ugh, todavía no recuerdo bien. Solo necesito un trago para despejar la cabeza.', '', 28153),
(136363, 'esMX', 'No, no. DEFINITIVAMENTE era por la derecha.', '', 28153),
(136362, 'esMX', '<hic> A ver, ¿por dónde era? ¿A la izquierda?', '', 28153),
(136361, 'esMX', 'Los susurros... se apoderan de mis pensamientos...', 'Los susurros... se apoderan de mis pensamientos...', 28153),
(136360, 'esMX', 'Mi alma por el mar...', 'Mi alma por el mar...', 28153),
(136359, 'esMX', 'Y\'za qam yyqzz...', 'Y\'za qam yyqzz...', 28153),
(136358, 'esMX', 'Oye, $gintruso:intrusa;. ¡No deberías entrar a lugares a los que no perteneces!', 'Oye, $gintruso:intrusa;. ¡No deberías entrar a lugares a los que no perteneces!', 28153),
(136357, 'esMX', '¡Tu corazón será un sacrificio adecuado!', '¡Tu corazón será un sacrificio adecuado!', 28153),
(136356, 'esMX', '¡Me entrego por completo a cambio de este poder!', '¡Me entrego por completo a cambio de este poder!', 28153),
(136350, 'esMX', '%s te sigue.', '', 28153),
(136349, 'esMX', '%s se cansa de seguirte y huye.', '', 28153),
(136348, 'esMX', '', 'Ahora que las aguas están apaciguadas de nuevo, es hora de concentrarnos en la caverna.', 28153),
(136347, 'esMX', 'Las velas eh\'tán en posición, y las ofrendas, listas. Ahora debemoh\' dibujar el círculo...', '', 28153),
(136346, 'esMX', '¡La Gema clamacielos se está sobrecargando! Quién sabe lo que puede suceder si la usas ahora...', '¡La Gema clamacielos se está sobrecargando! Quién sabe lo que puede suceder si la usas ahora...', 28153),
(136345, 'esMX', '¡Por la Horda!', '', 28153),
(136341, 'esMX', 'Empecemos.', 'Empecemos.', 28153),
(136340, 'esMX', 'Estas llanuras florecerán regadas con la sangre de nuestros enemigos.', '', 28153),
(136327, 'esMX', '', '¡Cuidado!', 28153),
(136326, 'esMX', '', '¡Cuidado!', 28153),
(136325, 'esMX', 'Bien... Creo que estoy listo para partir. Todavía podemos arreglar esto.', '', 28153),
(136324, 'esMX', 'Pídele a Fozruk que ataque Alto Pedestal.', 'Pídele a Fozruk que ataque Alto Pedestal.', 28153),
(136323, 'esMX', 'Pídele a Fozruk que ataque Paso Valeroso.', 'Pídele a Fozruk que ataque Paso Valeroso.', 28153),
(136322, 'esMX', 'Pídele a Fozruk que ataque Stromgarde.', 'Pídele a Fozruk que ataque Stromgarde.', 28153),
(136321, 'esMX', '<Fozruk te mira con desdén.>', '', 28153),
(136320, 'esMX', 'Con gusto.', '', 28153),
(136319, 'esMX', '¡Te arrancaré las extremidades!', '', 28153),
(136318, 'esMX', 'Ineptos... Los demás vendrán... y recuperarán la gema...', '', 28153),
(136317, 'esMX', '¡No impedirás que encontremos el verdadero poder de la gema clamacielos!', '', 28153),
(136316, 'esMX', '¡El desierto lo cubrirá todo!', '', 28153),
(136315, 'esMX', '¡Nazmir le pertenece a los sethrak!', '', 28153),
(136314, 'esMX', '¡Esta tierra se convertirá en arena!', '', 28153),
(136313, 'esMX', '¡La próxima les tocará a tus tierras!', '', 28153),
(136312, 'esMX', '¡No puedes impedir nuestro dominio!', '', 28153),
(136311, 'esMX', '¡Arrasaremos con los pantanos!', '', 28153),
(136310, 'esMX', '¡Lo dominaremos todo!', '', 28153),
(136309, 'esMX', '¡Esta tierra quedará desierta!', '', 28153),
(136297, 'esMX', '¡¿CÓMO PUDISTE?!', '', 28153),
(136296, 'esMX', 'Tú... ¡mataste al amor de mi vida!', '', 28153),
(136295, 'esMX', 'Ufff... Mira esto... Cortado a la mitad por los sethrak... No es justo.', '', 28153),
(136292, 'esMX', '¡Te concedo la bendición del mar! Siente su dulce abrazo ahora que te acepta como aliado.', '', 28153),
(136291, 'esMX', 'Xibala... te hará sufrir...', '', 28153),
(136290, 'esMX', 'Este e\' el templo sagrado de Xibala. ¡Estará feli\' de tener un alma nueva en su colección!', '', 28153),
(136278, 'esMX', 'El mundo... se hundirá... ak yar qi\'lwhuk h\'iwn...', 'El mundo... se hundirá... ak yar qi\'lwhuk h\'iwn...', 28153),
(136277, 'esMX', '¡Es demasiado tarde! ¡No puedes detener nuestro avance!', '¡Es demasiado tarde! ¡No puedes detener nuestro avance!', 28153),
(136276, 'esMX', 'Ifis shuul qi\'nuq yyqzz...', '', 28153),
(136275, 'esMX', 'Brannon Canto Tormenta es un debilucho. ¡El verdadero poder le pertenece al mar!', '', 28153),
(136274, 'esMX', '¿Alby? ¿Qué sucede? ¿Dónde está Lord Canto Tormenta?', '', 28153),
(136273, 'esMX', 'No me lo creerías si te lo dijera, Therold. Es un desastre.', '', 28153),
(136272, 'esMX', '¡Bajen la voz! Lady Sylvanas no estará muy complacida si fracasamos en nuestra misión.', '', 28153),
(136271, 'esMX', '¡Tucker! Debí haberlo imaginado. Al menos pagó un precio por su incompetencia.', '', 28153),
(136270, 'esMX', 'Tucker. Fue el primero al que mataron los sethrak.', '', 28153),
(136269, 'esMX', 'Debimos haber anticipado el ataque. ¿Quién estaba a cargo de la vigilancia?', '', 28153),
(136268, 'esMX', '', 'No es culpa nuestra, jefe. Fuimos atacados por un grupo que se suponía que no estaba en estos lugares.', 28153),
(136267, 'esMX', 'Estará feliz si hacemos bien nuestro trabajo, Ingrid.', '', 28153),
(136266, 'esMX', '', '¿Alguna vez estará satisfecha, jefe?', 28153),
(136265, 'esMX', 'Muy bien, ¡a moverse! Debemos seguir explorando este lugar, no podemos volver a caer en una emboscada.', '', 28153),
(136264, 'esMX', '<El Fetiche Oscuro parece moverse cuando lo ves por el rabillo del ojo, pero permanece inmóvil cuando te vuelves a mirarlo. Tal vez es solo un efecto de la luz. O no.>', '', 28153),
(136263, 'esMX', '', '¡Ah, por favor!', 28153),
(136262, 'esMX', 'Esa es información clasificada...', '', 28153),
(136261, 'esMX', '', '¿Cuándo fue la PRIMERA vez que te cortaron al medio?', 28153),
(136260, 'esMX', 'No es la primera vez que me cortan al medio. Pero sí espero que sea la última.', '', 28153),
(136259, 'esMX', 'A veces.', '', 28153),
(136258, 'esMX', '', 'Ugh, Clayton, somos no-muertos... Desde luego que podemos seguir viviendo si nos parten por la mitad.', 28153),
(136257, 'esMX', '¿Jefe, cómo logró sobrevivir? Vi cómo lo cortaron al medio.', '', 28153),
(136256, 'esMX', '', '¡Espero que te diviertas con la gema! Creo que después del ritual se mantuvo... bastante intacta.', 28153),
(136255, 'esMX', '¿Gusanos que devoran rostros? ¡Yo me largo de aquí!', '¿Gusanos que devoran rostros? ¡Yo me largo de aquí!', 28153),
(136254, 'esMX', '¿Cómo se le escapó esto a la administración? Se acabó, necesitamos un sindicato.', '¿Cómo se le escapó esto a la administración? Se acabó, necesitamos un sindicato.', 28153),
(136253, 'esMX', 'De todas formas ya es hora de mi descanso. Yo me largo.', 'De todas formas ya es hora de mi descanso. Yo me largo.', 28153),
(136252, 'esMX', 'Me adelantaré a los terrenos más altos. Avisa al escuadrón que nos encontraremos en mi ubicación.', '', 28153),
(136251, 'esMX', 'Estoy acostumbrado a encontrar partes de monstruos en los cargamentos, ¿pero monstruos vivos? No cuenten conmigo.', 'Estoy acostumbrada a encontrar partes de monstruos en los cargamentos, ¿pero monstruos vivos? No cuenten conmigo.', 28153),
(136250, 'esMX', 'Empuja con fuerza esa parte...', '', 28153),
(136249, 'esMX', '', 'Te veré al otro lado del área de empaque. Voy a averiguar qué sucede en el interior del pueblo.', 28153),
(136248, 'esMX', '', '¿Qué está pasando aquí? ¿Qué...? ¿Qué es ESO?', 28153),
(136243, 'esMX', '', '\"No experimentes con la magia de las sombras\", decían.$B$B\"Condenarás a todo Azeroth si sigues profundizando en eso\", me advirtieron.$B$B\"Devuélveme el brazo, ¡no puedes usarlo como ingrediente!\", gritó mientras le arrancaba el brazo.$B$BAh, lo siento, ¡estaba recordando buenos momentos!', 28153),
(136242, 'esMX', 'Hay más votos a favor. Parece que seremos testigos de un espectáculo de luces.', '', 28153),
(136241, 'esMX', 'No.', '', 28153),
(136240, 'esMX', 'No.', '', 28153),
(136239, 'esMX', '¿Quiénes votan en contra?', '', 28153),
(136238, 'esMX', 'Sí.', '', 28153),
(136237, 'esMX', 'Será mejor que me encargue de que eh\'to se haga como corresponde.', '', 28153),
(136236, 'esMX', '', 'Sí.', 28153),
(136235, 'esMX', '', 'Sí.', 28153),
(136234, 'esMX', 'Lo someteremos a votación. ¿Están a favor de quedarse en un pantano peligroso para ver cómo siguen matando a los viperinos con una gema?', '', 28153),
(136233, 'esMX', '', '¡Vamos, Chadwick! ¡Podemos FREÍRLOS gracias a la gema clamacielos que conseguirá $n!', 28153),
(136232, 'esMX', 'Mis mago\' y yo te encontraremos allí.', '', 28153),
(136231, 'esMX', 'Jamás creí que vería una cara amigable en este lugar. Gracias por rescatarme. ¿Ya te has enterado de los planes de Ingrid?', '', 28153),
(136230, 'esMX', 'No sé que estábamos pensando cuando decidimos venir a un lugar así sin prepararnos...', '', 28153),
(136229, 'esMX', '', 'Me iré de este lugar mientras tú te encargas de ciertas cosas... Y luego veremos qué puede hacer esta gema.', 28153),
(136228, 'esMX', 'Gracias por el rescate, estos sethrak buscan una especie de magia de las sombras en Nazmir, pero nadie sabe bien con qué propósito.', '', 28153),
(136227, 'esMX', '', 'Es un alivio. Estos sethrak buscan una especie de magia para desatar el poder de uno de sus artefactos.', 28153),
(136226, 'esMX', '¿Has estado recibiendo tus cargamentos?', '¿Has estado recibiendo tus cargamentos?', 28153),
(136225, 'esMX', '¡AAHH! ¡QUÍTENME ESTA COSA!', '', 28153),
(136224, 'esMX', '¡$gMaldito:Maldita;!', '¡$gMaldito:Maldita;!', 28153),
(136223, 'esMX', '¡Por todos los cielos! ¡Mató a Ken\'nai!', '¡Por todos los cielos! ¡Mató a Ken\'nai!', 28153),
(136222, 'esMX', 'Esto podría ser un problema. ¡Cuidado!', '', 28153),
(136221, 'esMX', '¡De hecho, acabo de recibir un cargamento hace solo unos minutos! ¡Quieres echar un vistazo?', '', 28153),
(136220, 'esMX', '', '¿Sabes? Hace días que no veo a ese niño Canto Tormenta. Ojalá pusieran a alguien más competente a cargo de este lugar, pero ¿qué importa mi opinión?', 28153),
(136219, 'esMX', '¿Has notado algo extraño?', '¿Has notado algo extraño?', 28153),
(136218, 'esMX', '¡Hace días que no recibo ingredientes frescos! ¿Cómo voy a preparar mi famoso trillanodonte frito sin aletas de trillanodonte?', '', 28153),
(136215, 'esMX', 'Creo que ya es hora de demostrarles a estos sethrak en qué consiste el verdadero dolor.', '', 28153),
(136212, 'esMX', '¡Eso! No estuvo nada mal. ¿Habías hecho esto antes?', '', 28153),
(136211, 'esMX', '¡Auuuch! No, sigue, sigue. Eso siempre duele. Gírala un poco...', '', 28153),
(136210, 'esMX', 'Intenta tratar a mis piernas con suavidad... Tienden a contonearse cuando se desprenden.', '', 28153),
(136207, 'esMX', '¡Eh! ¡Devuélvemelo!', '', 28153),
(136206, 'esMX', '', '¡Saca a eh\'tos sáuridos de mi posada!', 28153),
(136205, 'esMX', '', '¿Qué? ¿Qué quiere\'?', 28153),
(136200, 'esMX', 'De acuerdo. Cubriré el flanco trasero.', '', 28153),
(136199, 'esMX', 'Genn, necesito que cubras la retaguardia. Es demasiado arriesgado enviar a todos en fila alrededor de la fortaleza. Seguramente habrá trampas.', '', 28153),
(136198, 'esMX', '', 'En marcha.', 28153),
(136197, 'esMX', 'Todos a sus posiciones. ¡Atacamos cuando yo dé la señal!', '', 28153),
(136196, 'esMX', 'Buen consejo. Sylvanas no tuvo mucho tiempo para prepararse para el ataque, pero no podemos subestimarla.', '', 28153),
(136194, 'esMX', '¿Has notado algo fuera de lo común?', '¿Has notado algo fuera de lo común?', 28153),
(136193, 'esMX', '¿Necesitas algo?', '', 28153),
(136192, 'esMX', '', '¿Sí? ¿Puedo ayudarte?', 28153),
(136191, 'esMX', '¡$gBienvenido:Bienvenida;, $gbienvenido:bienvenida;! ¿Quieres comer algo?', '', 28153),
(136187, 'esMX', '¿Me darías una mano? Bueno, en realidad necesitaría una pierna, mis manos están bien.', '', 28153),
(136179, 'esMX', '¡Hora de mostrarle a la escoria de la Alianza el poder de la Horda!', '', 28153),
(136178, 'esMX', 'Desde que son cachorros, nuestros lobos están entrenados y listos para la batalla.', '', 28153),
(136177, 'esMX', 'No perdamos el tiempo charlando. Hay trabajo que hacer.', '', 28153),
(136176, 'esMX', '', '¿Sí? ¿En qué puedo ayudarte, cariño?', 28153),
(136170, 'esMX', '¡Jaina! ¡Gracias a la Luz! No sabes cómo te necesitábamos para esta pelea.', '', 28153),
(136169, 'esMX', '', 'Kel\'vax fue nuestro hijo en vida, pero ahora es un monstruo más. Destrúyelo para que podamo\' enviar su alma a Bwonsamdi.', 28153),
(136167, 'esMX', '', 'Kel\'vax quiere mancillar todo lo que se relaciona con Bwonsamdi. Encuentra las filacteria\' para que podamos poner fin a eh\'ta afrenta.', 28153),
(136166, 'esMX', '', 'Ayuda a purificar ese viejo lugar sagrado de Bwonsamdi. Y pensar que ante\' era glorioso...', 28153),
(136165, 'esMX', '', 'Espera, hay alguien ahí... ¡Y no e\' un trol de sangre! ¡Eh, tú!', 28153),
(136164, 'esMX', '', 'Mis creaciones... son invencibles...', 28153),
(136163, 'esMX', '', '¡Estas almas me pertenecen!', 28153),
(136162, 'esMX', 'A este paso, jamás lograremo\' limpiar este lugar para Bwonsamdi.', '', 28153),
(136161, 'esMX', '', '¡Ah, ahí estás! Acabo de eh\'cuchar el informe de Mutumba. Parece que tuvieron una gran aventura.', 28153),
(136160, 'esMX', '', 'Yo hice de estos bosques un lugar seguro mientras viví. ¡No me convertiré en una herramienta de estas brujas!', 28153),
(136159, 'esMX', 'Qué... hermosa...', '', 28153),
(136156, 'esMX', '', 'Ten cuidado. Tus herida\' son profunda\'.', 28153),
(136153, 'esMX', 'Estamos listos para partir.', 'Estamos listos para partir.', 28153),
(136152, 'esMX', '', 'Nunca es seguro atravesar estas dunas sin compañía.', 28153),
(136151, 'esMX', 'Dediqué mi vida a proteger esta tierra.\n\nEn la muerte, juro que haré lo mismo.', '', 28153),
(136150, 'esMX', '', 'Te veré al otro lado.', 28153),
(136149, 'esMX', '... Bwonsamdi estará satisfecho. Es hora de que todos descansemo\'.', '', 28153),
(136148, 'esMX', '¡No! No puedo ver a Bwomsamdi, no quiero... ¡Por favor! ¡BASTA!', '', 28153),
(136147, 'esMX', '', 'Tu destino ahora eh\'tá en manos de Bwonsamdi. Si tiene\' suerte, será más piadoso que nosotros.', 28153),
(136146, 'esMX', '¡No! ¡Madre, haz algo!', '', 28153),
(136145, 'esMX', 'Ya es muy tarde, hijo mío. Has elegido traicionar a Bwonsamdi. Debe\' pagar por eso.', '', 28153),
(136144, 'esMX', 'Madre... Padre... Lo siento... ¡Por favor, perdónenme! ¡Hablen con Bwonsamdi por mí!', '', 28153),
(136141, 'esMX', 'Me ocupo de los muertos.$b$b<Allen se encoge de hombros.>$b$b Así me gano la vida.', '', 28153),
(136140, 'esMX', '', '¡Pobre de ti, loa! ¡Solo encontrará\' la muerte en este lugar!', 28153),
(136116, 'esMX', 'Ven, regresemos a la guarida.', '', 28153),
(136115, 'esMX', 'Oh, jojojojo... ¡Los enemigos huyen ante nosotros!', '', 28153),
(136114, 'esMX', '¡Bwonsamdi! No... ¡G\'huun prometió que nunca me derrotarían!', '', 28153),
(136113, 'esMX', '¡Deja de preocuparte tanto! Con el tiempo me di cuenta de que las criaturas fantásticas nunca son tan terribles como las pintan las historias.', '', 28153),
(136112, 'esMX', 'Tengo un mal presentimiento sobre eh\'to... ¡Cuidado, $n!', '', 28153),
(136111, 'esMX', '¡Bien! Con la muerte de su líder, estos esbirros pronto caerán. ¡Alimentémonos con ellos!', '', 28153),
(136110, 'esMX', '¡BAH! ¡Te maldigo a ti y maldigo a Bwonsamdi! ¡NO TENDRÁ MI ALMA!', '', 28153),
(136109, 'esMX', '¡Tus espíritus serán el alimento del dios de la sangre!', '', 28153),
(136108, 'esMX', 'Kel\'vax e\' vulnerable otra vez... ¡Ahora tú decide\'!', '', 28153),
(136107, 'esMX', '¿Qué...? ¡Imposible! ¡No me encadenarán! ¡Ni tú ni Bwonsamdi!', '', 28153),
(136106, 'esMX', 'Es hora de enfrentar el juicio de Bwonsamdi. Tenemo\' las filacterias, y $n me ha conseguido lo\' huesos para contrarrestar tu vudú.', '', 28153),
(136105, 'esMX', 'Madre, padre...', '', 28153),
(136104, 'esMX', '', '¡Kel\'vax, esto e\' suficiente!', 28153),
(136103, 'esMX', '¡Te unirás a los sirvientes de Bwonsamdi y sufrirás por toda la eternidad!', '', 28153),
(136102, 'esMX', '¡SUFICIENTE! El dios de la sangre exige tu destrucción... Y yo cumpliré con sus demandas. ¡Maldito sea Bwonsamdi!', '', 28153),
(136101, 'esMX', 'No importa. He vih\'to el auge y la caída de esta civilización... ¡No me detendrás!', '', 28153),
(136100, 'esMX', '¿Qué? ¿Dónde están mis zombi\'... mis esqueleto\'? ¿Qué sucede?', '', 28153),
(136099, 'esMX', 'Mortal ignorante... Mis ejércitos te destruirán. ¡Sirvientes, a mí!', '', 28153),
(136096, 'esMX', '¡Oye! No pareces $gconocido:conocida;. ¿Has venido a ayudar o qué?', '', 28153),
(136095, 'esMX', '¡Basta de esta farsa!', '¡Ya basta de parloteo!', 28153),
(136094, 'esMX', '', 'No deberías meterte en los asuntos de Aspafresno. Son tan sucios...', 28153),
(136093, 'esMX', 'Nada mal para $Uun náufrago pulgoso:una náufraga pulgosa;. Tienes suerte de que no te haya encontrado antes de llegar a tierra firme, si no estaría limpiándome tu sangre de las botas.', 'Nada mal para $Uun náufrago pulgoso:una náufraga pulgosa;. Tienes suerte de que no te haya encontrado antes de llegar a tierra firme; si no, estaría limpiándome tu sangre de las botas.', 28153),
(136092, 'esMX', '¡Enfréntenme, brujas escamosas! ¡Las despellejaré y usaré su piel como bandera!', '¡Vengan aquí, brujas escamosas! ¡Las despellejaré y usaré su piel como bandera!', 28153),
(136086, 'esMX', '', 'Mi padre alguna vez gobernó con puño de hierro, y nadie osaba violar sus leye\'. Pero también era justo y ayudaba a los más necesitado\', y por eso ellos lo amaban.$b$b¿Y ahora? Ahora el puño de hierro quedó en el olvido. Y aquellos en los que deposita su confianza lo llenan de veneno mientra\' complotan a sus espalda\'.$b$bNo sé qué están tramando, pero sí sé que nueh\'tro pueblo no puede quedarse de brazos cruzado\'.', 28153),
(136085, 'esMX', '', '¡Niños, asesinen a eh\'ta criatura!', 28153),
(136072, 'esMX', 'La marea de sangre los arrollará deh\'de el norte, y todos tendrán que arrodillarse.', 'La marea de sangre los arrollará deh\'de el norte, y todos tendrán que arrodillarse.', 28153),
(136071, 'esMX', 'Pronto vendrán desde Nazmir, y todo\' verán lo que hemos vih\'to.', 'Pronto vendrán desde Nazmir, y todo\' verán lo que hemos vih\'to.', 28153),
(136070, 'esMX', '¡No! ¡No! No puedes detenerno\'. Él nos prometió que no podías detenernos.', '¡No! ¡No! No puedes detenerno\'. Él nos prometió que no podías detenernos.', 28153),
(136069, 'esMX', 'La sangre de héroe se vende a buen precio.', 'La sangre de héroe se vende a buen precio.', 28153),
(136068, 'esMX', 'No les podrás decir nada de mí a los guardia\' si te mato ', 'No les podrás decir nada de mí a los guardia\' si te mato ', 28153),
(136067, 'esMX', '¿Quién ere\' tú para interponerte en nuestro camino?', '¿Quién ere\' tú para interponerte en nuestro camino?', 28153),
(136039, 'esMX', '¿Qué es esto? Nuestros enemigos nos siguen de cerca. Si no quieres enfrentarlos conmigo, lo haré solo.', '', 28153),
(136015, 'esMX', 'Parece que los cargamentos del barril están compuestos por partes de monstruos comunes e intactas.', '', 28153),
(136003, 'esMX', '¡Es hora de terminar con esto! Veámonos en la ribera del río.', '', 28153),
(135928, 'esMX', '', 'Estos no-muerto\' son una afrenta a Bwonsamdi. No descansaremo\' hasta encargarnos de ellos.', 28153),
(135927, 'esMX', 'Debemo\' cumplir con la voluntad de Bwonsamdi. No descansaremo\' hasta lograrlo.', '', 28153),
(135904, 'esMX', 'Ven a mi madriguera. Tenemos mucho por hacer.', '', 28153),
(135903, 'esMX', '', '¡No! Lo siento, Krag\'wa.', 28153),
(135901, 'esMX', '¿Eres tan orgullosa como para cuestionar a quién le concedo mi bendición?', '', 28153),
(135900, 'esMX', '', '¡Krag\'wa! Es un honor, pero no lo merezco... No pude detener a los naga\'.', 28153),
(135898, 'esMX', 'Narez. Has demostrado ser digna de convertirte en mi seguidora.', '', 28153),
(135875, 'esMX', '', 'Me quedaré aquí para vigilar a los nagas y le probaré mi valor a Krag\'wa. Nos vemo\'.', 28153),
(135874, 'esMX', '¡No, ni lo sueñes, $gforastero:forastera;! ¡No me separarás de loh\' que me dan dinero!', '', 28153),
(135869, 'esMX', 'Te sigo.', 'Te sigo.', 28153),
(135868, 'esMX', '¿Ere\' $gnuevo:nueva;? ¿Quién eres?$b$bEl Sr. Sonrisa se enojará porque no lo has ido a ver. Será mejor que venga\' conmigo.', '', 28153),
(135865, 'esMX', '', 'Y decían que fui un tonto por guardar un pergamino tan \"superespecializado\". ¡Bah!', 28153),
(135861, 'esMX', '%s muere a causa de sus heridas.', '%s muere a causa de sus heridas.', 28153),
(135843, 'esMX', '', 'Solo quería... crear...un faucemaligna... Máh\'...', 28153),
(135842, 'esMX', '', '¡Tienes buen poder para lo\' tótems!', 28153),
(135795, 'esMX', '<La rana gigante yace sin vida en el lodo.>', '', 28153),
(135777, 'esMX', '¡Dispérsense!', '', 28153),
(135776, 'esMX', '¡Aaaah!', '', 28153),
(135774, 'esMX', '¡Corran!', '', 28153),
(135772, 'esMX', '¡Ay!', '', 28153),
(135771, 'esMX', '¡Te voy a acusar con el Sr. Sonrisa!', '', 28153),
(135770, 'esMX', '¡Necesitaba eso!', '', 28153),
(135769, 'esMX', '¡Ah! ¡Forastero! ¡Mal agüero!', '', 28153),
(135768, 'esMX', '¡Al Sr. Sonrisa no le gustará esto!', '', 28153),
(135741, 'esMX', '¿Qué?', '¿Qué?', 28153),
(135740, 'esMX', '¿Qué le dijo $uel:la; $r al médico brujo?', '', 28153),
(135733, 'esMX', 'Y se equivocó. Claro que hubo daños, pero Zul huyó con nuestra flota, e inició alguna\' guerras. Lo\' que nos quedamos, resistimos. Y reconstruimos el lugar. Porque ESO es lo que significa ser un zandalari.', '', 28153),
(135732, 'esMX', '¡Las visione\' de Zul, bah! ¿Te contó sobre aquella vez que predijo que Zandalar se hundiría bajo la\' olas?', '', 28153),
(135726, 'esMX', 'En estos muelles veo cientos de navío\' que atracan y se van, y yo garantizo que todos ellos tengan lo que necesitan en tiempo y forma.$b$bHabla rápido que mi tiempo vale oro.', '', 28153),
(135719, 'esMX', '', 'Adelante.', 28153),
(135701, 'esMX', 'Se oyen muchas historia\' sobre Xibala, pero no sé cuáles son cierta\'. Los ancestro\' le tenían miedo, eso sí e\' seguro.\n\nSe decía que Xibala dejaba a los cuerpo hinchados de putrefacción.\n\nO que quien se atrevía a mirarlo se convertía en un esqueleto viviente.\n\nO que merodeaba entre las sombra\' y que salía a la noche para devorar a la gente mientras dormía.\n\nO que esperaba cerca de los camino\' para hacer que los pasantes murieran atragantados por su propia sangre.\n\nIncluso los guerrero\' más valientes saben que es mejor mantenerse lejos de este lugar.', '', 28153),
(135699, 'esMX', '¿Quién era Xibala?', '¿Quién era Xibala?', 28153),
(135694, 'esMX', '', 'Cre-creo que puedo es-escabullirme hasta la cueva donde está mi hermana. Nos veremos ahí.', 28153),
(135683, 'esMX', '¿Qué te trae por aquí, $c?', '', 28153),
(135680, 'esMX', 'Estamos listos para comenzar el juicio.', 'Estamos listos para comenzar el juicio.', 28153),
(135679, 'esMX', 'Las excusas no servirán de nada. ¡Descubriremos la verdad sobre la señorita Tarjasenda tarde o temprano!', '', 28153),
(135674, 'esMX', '¡Puede que nuestros jinetes del viento hayan caído, pero el verdadero poder está en la empuñadura del hacha!', '', 28153),
(135673, 'esMX', 'Con o sin artillería, ¡nadie supera nuestra fuerza!', '', 28153),
(135670, 'esMX', '¡Mis hojas desgarrarán tu carne!', '', 28153),
(135638, 'esMX', 'Esos monstruos acabaron con mi último seguidor. ¡Los castigaré con la furia de diez mil años!', '', 28153),
(135610, 'esMX', '', 'Este elevador te llevará a la cámara donde la princesa Talanji te eh\'tá esperando. Ten cuidado dónde pisas.', 28153),
(135604, 'esMX', '', 'Sígueme. Puedo llevarte por el camino más fácil.', 28153),
(135586, 'esMX', '', 'Ven a visitarme cuando puedas. ¡Estoy ansiosa por compartir contigo todo lo que aprendí de estos grabados!', 28153),
(135579, 'esMX', '', 'No te preocupes por mí... puedo volver a la arena sola.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135578, 'esMX', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t ¡Yazma comienza a lanzarle |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r a |cFFFF0000$n|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t ¡Yazma comienza a lanzarle |cFFFF0404|Hspell:249924|h[Desgarre de alma]|h|r a $n!', 28153),
(135577, 'esMX', 'Siento que recupero la fuerza... Parece que el antídoto funciona.', '', 28153),
(135576, 'esMX', 'No sé cuánto tiempo le queda a Julwaba... El antídoto es su única esperanza.', '', 28153),
(135574, 'esMX', 'Hace día\' que Julwaba y Taz\'jin están desaparecido\'. Estoy empezando a preocuparme por ello\'...', '', 28153),
(135565, 'esMX', '¡Ve, rápido! Debemos asesinar a los nagas para salvar a los seguidores de Kra\'gwa.', '', 28153),
(135555, 'esMX', '', 'Que Krag\'wa te bendiga. Demuéstrale a Zaldraxia que se metió con el loa equivocado.', 28153),
(135539, 'esMX', 'Debemos detener a los nagas, no te preocupes por mi bienestar.', '', 28153),
(135511, 'esMX', 'Llévame ante el rey Rastakhan.', 'Llévame ante el rey Rastakhan.', 28153),
(135496, 'esMX', '¡Están atacando nuestra ciudad!', '¡Están atacando nuestra ciudad!', 28153),
(135492, 'esMX', 'Estoy enviando a algunos trabajadores para que excaven esa veta.', '', 28153),
(135486, 'esMX', '¡Están atacando la mina!', '¡Están atacando la mina!', 28153),
(135469, 'esMX', '', '¿Qué sucede, $c?', 28153),
(135466, 'esMX', 'Este pergamino bueno para nada... ¡Ponte a trabajar y ENCUENTRA A SHOAK!', '', 28153),
(135465, 'esMX', '¡Vamos! Necesito que encuentres a Shoak, ¡NO QUE SALTES ENCIMA DE ESE TÓTEM!', '', 28153),
(135464, 'esMX', '¡Ponte a TRABAJAR! ¡Encuentra a Shoak de una vez por todas!', '', 28153),
(135457, 'esMX', '', 'Quizá haya algunos daños colaterales, pero estoy segura de que con el tiempo pondremos todo en su lugar. Probablemente tengamos que llamar a algunos asistentes más...', 28153),
(135456, 'esMX', 'Los espíritu\' no estarán contento\' sobre esta situación. ¡No digas que no te advertí!', '', 28153),
(135455, 'esMX', '¡Eh! ¡Será mejor que no tire\' ninguna bomba sobre eso\' huesos!', '', 28153),
(135446, 'esMX', '', '¡Muere, $Gentrometido:entrometida;!', 28153),
(135445, 'esMX', '', '¡Nos servirás!', 28153),
(135444, 'esMX', '', 'No... ¡No puedo fallar!', 28153),
(135443, 'esMX', '', 'No... Me prometieron... poder...', 28153),
(135442, 'esMX', '', '¡Me suplicarás que te mate!', 28153),
(135441, 'esMX', '', '¡Te convertirás en un sirviente más!', 28153),
(135440, 'esMX', '', '¡No podrás detenerme!', 28153),
(135439, 'esMX', '¡Le llevaré tu corazón a la Maestra!', '', 28153),
(135432, 'esMX', '¡La Alianza se ha adueñado de una veta de azerita!', '', 28153),
(135431, 'esMX', '¡$n ha defendido una veta de azerita!', '', 28153),
(135430, 'esMX', '¡La Horda se ha adueñado de una veta de azerita!', '', 28153),
(135429, 'esMX', '¡$n ha asaltado una veta de azerita!', '', 28153),
(135405, 'esMX', 'Muy bien. Pero debe\' saber que le enviaré una petición al rey para quedarme con la cabeza de esta criatura.', '', 28153),
(135400, 'esMX', 'Suficiente. General, hágase a un lado. Eh\'te esbirro de la Horda ha superado los desafío\' de dos tribus. La ley exige que le permitas pasar.', '', 28153),
(135399, 'esMX', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 'I\'m placeholder text. If you see this, Josh has made a mistake.', 28153),
(135388, 'esMX', 'Dicen que el rey no ha abandonado su trono desde el día en que murió su esposa.', 'Dicen que el rey no ha abandonado su trono desde el día en que murió su esposa.', 28153),
(135387, 'esMX', '¿La Horda? ¿En Zuldazar? Eso no está nada bien... nada bien.', '¿La Horda? ¿En Zuldazar? Eso no está nada bien... nada bien.', 28153),
(135386, 'esMX', 'Cuando Zul se fue, se llevó a muchos de nosotros. Y ahora dicen que los trol de sangre atacan la frontera norte.', 'Cuando Zul se fue, se llevó a muchos de nosotros. Y ahora dicen que los trol de sangre atacan la frontera norte.', 28153),
(135385, 'esMX', '', 'Oh... Lo siento, continental, pero debo pedirte otro favor.', 28153),
(135384, 'esMX', 'Pues supongo que habrá que tener paciencia.', '', 28153),
(135383, 'esMX', '', '¡Pero eso puede llevar siglos!', 28153),
(135382, 'esMX', 'Más allá de las pruebas, ¡solo serás absuelta cuando descubramos la verdad sobre lo que pasó con nuestra aldea!', '', 28153),
(135381, 'esMX', '', '¡¿Cómo?! ¿Después de todo lo que tuve que sufrir?', 28153),
(135380, 'esMX', 'Aún no estoy convencido. Lo que ha sucedido en la Hondonada Fletcher sigue sin tener explicación.', '', 28153),
(135379, 'esMX', '¡Silencio! Seré yo quien dicte sentencia.', '', 28153),
(135378, 'esMX', 'Parece que no es una bruja. ¿Entonces qué sucede con nuestro poblado?', 'Después de todo, parece que no es una bruja. ¿Pero entonces qué sucede con nuestro poblado?', 28153),
(135377, 'esMX', '¡Se siente mal! ¡Es imposible!', '', 28153),
(135376, 'esMX', '', 'Oh... No me siento muy...', 28153),
(135375, 'esMX', '', 'Por supuesto que sí. El veneno, continental.', 28153),
(135374, 'esMX', '¿Está preparada para demostrar lo contrario, señorita Tarjasenda?', '', 28153),
(135373, 'esMX', 'Es bien sabido que el poder de una bruja no se alimenta de comida, sino de las almas de sus víctimas. No hay nada en sus tripas.', '', 28153),
(135372, 'esMX', 'Es interesante, pero no significa nada. Pasemos a la última prueba: las vísceras purgadas.', '', 28153),
(135371, 'esMX', 'No parecen evitarla. En realidad, la están picando como nunca.', 'No parecen evitarla. En realidad, la están picando como nunca.', 28153),
(135370, 'esMX', '', '¡Auch! ¡Uf! ¡Uh! ¡Me duele!', 28153),
(135369, 'esMX', '', 'No te preocupes por mí. ¿Qué me harán unas cuantas picaduras?', 28153),
(135368, 'esMX', '¡Liberen a las sangriposas y observen cómo huyen ante la presencia maligna!', '', 28153),
(135367, 'esMX', 'La segunda prueba será la picadura de los insectos. ¡Es de conocimiento público que ni siquiera las voraces sangriposas se atreven a probar la sangre vil de una bruja!', '', 28153),
(135366, 'esMX', 'Calma, calma. Puede que todo sea una artimaña. Continuaremos con el juicio.', '', 28153),
(135365, 'esMX', '¡Está llorando! Las brujas no pueden llorar, ¡¿o sí?!', '¡Está llorando! Las brujas no pueden llorar, ¡¿o sí?!', 28153),
(135364, 'esMX', '', 'Adelante, continental. Muéstrales.', 28153),
(135363, 'esMX', '¿Será la acusada capaz de llorar? Que lo demuestre, para que podamos emitir nuestro juicio.', '', 28153),
(135362, 'esMX', 'La primera prueba será el derramamiento de lágrimas. Que conste que la señorita Tarjasenda no derramó ni una sola durante todo el proceso.', '', 28153),
(135361, 'esMX', 'Ha elegido a $Geste:esta; continental para que realice las pruebas. Una decisión inusual... Pero como prueba de buena fe, lo permitiré.', '', 28153),
(135360, 'esMX', 'Como se acostumbra, Lady Tarjasenda ha elegido las pruebas que hará para probar su inocencia ante las acusaciones de brujería.', '', 28153),
(135359, 'esMX', '¡Por fin! ¡El juicio puede comenzar!', '', 28153),
(135358, 'esMX', '¿Ya terminaste? ¡Me estoy impacientando!', '', 28153),
(135357, 'esMX', 'Hace tiempo me hablaron de una bruja que vivía en un pantano. Los aldeanos la descubrieron porque las sangriposas no se le acercaban. \n\n¡Picaban a todo el mundo menos a ella! \n\nDicen que la sangre de una bruja es tan maligna que ni siquiera las sangriposas se atreven a tocarla.', '', 28153),
(135356, 'esMX', 'Nunca antes había visto a una bruja de verdad. ¿No es emocionante?', '', 28153),
(135355, 'esMX', 'En los viejos tiempos, las arrojábamos al río. Si volvían a salir a la superficie, significaba que habían celebrado un pacto profano y entonces las ahorcábamos. \n\nEn mi opinión, esa es la única forma de absolver a una bruja.', '', 28153),
(135354, 'esMX', '¡La maldición de la bruja se llevó a mi hijo! ¡Hoy se hará justicia!', '', 28153),
(135353, 'esMX', '', 'No... No lo sé... \n\nSe dice que una bruja nunca vomita porque los espíritus oscuros que la habitan mantienen vacío su estómago. \n\nPero no sé cómo podemos comprobarlo...', 28153),
(135352, 'esMX', '', 'Algo debemos hacer para terminar con la maldición que se cierne sobre nuestra aldea. \n\nSi matamos a la bruja que lanzó este hechizo, sin dudas romperemos esa maldición.', 28153),
(135351, 'esMX', 'Dicen que las brujas son inmunes al fuego. Por eso las ahorcamos cuando las declaramos culpables. \n\nSi quieres convencerme, ¡acércale una antorcha!', '', 28153),
(135350, 'esMX', 'Esa mujer trajo la maldad a nuestra aldea. ¡Debe pagar por eso!', '', 28153),
(135349, 'esMX', '', 'Mi madre siempre me decía que las brujas no pueden llorar, por mucho que se lastimen o se entristezcan. \n\nY la señorita Tarjasenda no soltó ni una lágrima cuando supo que sería juzgada. ¡Debe ser una bruja!', 28153),
(135348, 'esMX', '¿Cómo se puede probar que alguien no es una bruja?', '¿Cómo se puede probar que alguien no es una bruja?', 28153),
(135347, 'esMX', '', '¡Este juicio es horrible, pero hay que hacer justicia por Hondonada Fletcher!', 28153),
(135346, 'esMX', '¿La señorita Tarjasenda ha decidido qué pruebas prefiere realizar?', '', 28153),
(135345, 'esMX', '¡Por fin! ¡Prosigamos!', '', 28153),
(135344, 'esMX', '¡Oficial! Continúe con este... juicio.', '', 28153),
(135343, 'esMX', 'Nos has conseguido algo de tiempo, continental. Esperemos que estos aldeanos no tengan intención de hacerle daño a Lady Tarjasenda.', '', 28153),
(135342, 'esMX', '', '¿Rescatarme? ¿Y piensas asesinar a todas estas personas para darme la libertad? \n\nNo. Si quieres ayudarme, debes intervenir ante el mariscal.\n\nAunque sus acusaciones sean injustas, esta es mi gente y no les causaré un daño solo para ahorrarme algunas molestias. Dejaré que lleven adelante el juicio y les demostraré mi inocencia.\n\nSin embargo, temo que el mariscal tome cartas en el asunto. Y no puedo hacer mucho para evitarlo. Intenta convencerlo para que no intervenga en el juicio.', 28153),
(135341, 'esMX', 'He venido a rescatarte.', 'He venido a rescatarte.', 28153),
(135340, 'esMX', '', 'Lamento que hayas quedado en medio de todo esto. Son buenas personas, pero últimamente han vivido tiempos difíciles.', 28153),
(135339, 'esMX', '', '¡No hará tal cosa, mariscal! ¡Le ordeno que se detenga!', 28153),
(135338, 'esMX', 'No hay tiempo para discutir. Si no se hace a un lado, ¡la tomaremos por la fuerza!', '', 28153),
(135337, 'esMX', '¡La señorita Tarjasenda está acusada de brujería! ¡No permitiremos que se la lleven a menos que se la absuelva de este delito!', '', 28153),
(135336, 'esMX', '¡Oficial Framer! Le ordeno que me entregue a Lady Tarjasenda.', '', 28153),
(135335, 'esMX', '¡¿Más interrupciones?! ¡¿Qué sucede ahora?!', '', 28153),
(135334, 'esMX', '¡Miren! ¡Se acercan unos jinetes desde el bosque!', '¡Miren! ¡Se acercan unos jinetes desde el bosque!', 28153),
(135333, 'esMX', 'Ah, ¡detesto las interrupciones! ¿Qué vienes a hacer aquí, continental?', '', 28153),
(135332, 'esMX', '¡Oficial! ¡Se aproxima $Gun extraño:una extraña;!', '¡Oficial! ¡Se aproxima $Gun extraño:una extraña;!', 28153),
(135331, 'esMX', 'Serás juzgada por los cargos de...', '', 28153),
(135330, 'esMX', '¡Lucille Tarjasenda! Se te acusa de practicar la brujería y de lanzar una maldición sobre la aldea de Hondonada Fletcher.', '', 28153),
(135301, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Invocar Triciclo de guerra', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Invocar Triciclo de guerra', 28153),
(135286, 'esMX', '', 'Fui muy imprudente al salir sola en busca de reliquias ancestrales...', 28153),
(135281, 'esMX', 'Qué... <hipo> ... ¿qué mira\', colega?', '', 28153),
(135272, 'esMX', 'Analicemos nuestras opciones para luchar contra los trols de sangre.', 'Analicemos nuestras opciones para luchar contra los trols de sangre.', 28153),
(135265, 'esMX', '', '¡Hay uno má\'... ¡por aquí!', 28153),
(135263, 'esMX', '', '¡Eso es! Torga, el loa tortuga. Es benevolente y sabio. ¡Sé que nos ayudará! Veamos quién más eh\'tá aquí...', 28153),
(135261, 'esMX', '', 'Nazmir es un lugar maldito... pero es donde deh\'cansan los loa. Atrás... Averiguaré cuáles de ellos eh\'tán aquí.', 28153),
(135226, 'esMX', '¡Gracias! Estaba viviendo una pesadilla.', '', 28153),
(135225, 'esMX', '¡Tienes que detenerla!', '', 28153),
(135224, 'esMX', '¿Qué sucedió?', '', 28153),
(135221, 'esMX', '¡Te mataré!', '', 28153),
(135220, 'esMX', '¡¿Cómo te atreves a interrumpir el trabajo de la Maestra?!', '', 28153),
(135209, 'esMX', '', 'Veamos qué más hay ahí afuera...', 28153),
(135190, 'esMX', '¡Aquí, Pinky! ¡Tengo un delicioso bocado para ti!', '¡Aquí, Pinky! ¡Tengo un delicioso bocado para ti!', 28153),
(135189, 'esMX', 'La Alianza ha capturado la Mina.', 'La Alianza ha capturado la mina.', 28153),
(135188, 'esMX', 'Bueno, eso fue bah\'tante extraño, eh. Bien está lo que bien termina, ¿verdad? Ja, ja.', '', 28153),
(135187, 'esMX', 'Quien ssssssostenga este másssstil... esssstará al frente de mi tripulación...', '', 28153),
(135185, 'esMX', 'Algunos eh\'peran el regreso de la flota. Pero yo me acuerdo muy bien de los trols que se embarcaron con Zul. Eran una banda muy agresiva.', 'Algunos eh\'peran el regreso de la flota. Pero yo me acuerdo muy bien de los trols que se embarcaron con Zul. Eran una banda muy agresiva.', 28153),
(135184, 'esMX', '¿Es verdad que traerán a Zul de vuelta a Zandalar? Apueh\'to a que no estará muy contento con esas noticias.', '¿Es verdad que traerán a Zul de vuelta a Zandalar? Apueh\'to a que no estará muy contento con esas noticias.', 28153),
(135179, 'esMX', 'Tú no sigues a la Horda, pero has matado a mucha eh\'coria de la Alianza, así que está bien.', 'Tú no sigues a la Horda, pero has matado a mucha eh\'coria de la Alianza, así que eh\'tá bien.', 28153),
(135178, 'esMX', '¿Eh\' verdad que luchaste junto a la princesa Talanji? ¿Le derritió la cara a alguien? ¿Le arrancó la mente a alguno? ¿Cómo eran sus embrujos?', '¿Eh\' verdad que luchaste junto a la princesa Talanji? ¿Le derritió la cara a alguien? ¿Le arrancó la mente a alguno? ¿Cómo eran sus embrujos?', 28153),
(135177, 'esMX', 'Oí que los de tu clase siguen a un líder no-muerto. Al viejo Bwonsamdi no le guh\'tará eso.', 'Oí que los de tu clase siguen a un líder no-muerto. Al viejo Bwonsamdi no le guh\'tará eso.', 28153),
(135176, 'esMX', '¿Ereh\' de la Horda? ¿Es verdad que Vol\'jin ha muerto?', '¿Ereh\' de la Horda? ¿Es verdad que Vol\'jin ha muerto?', 28153),
(135175, 'esMX', 'Les doy gracias a los loa por el regreso de la princesa Talanji. No estuvo lejos mucho tiempo, pero los que buh\'can hacerle daño tampoco necesitaban demasiado.', 'Les doy gracias a los loa por el regreso de la princesa Talanji. No estuvo lejos mucho tiempo, pero los que buh\'can hacerle daño tampoco necesitaban demasiado.', 28153),
(135174, 'esMX', 'Primero gente que no eh\' trol, ¿y ahora la Horda? ¿A quién máh\' dejará entrar en nuestra ciudad Talanji?', 'Primero gente que no eh\' trol, ¿y ahora la Horda? ¿A quién máh\' dejará entrar en nuestra ciudad Talanji?', 28153),
(135173, 'esMX', '¿La Horda está aquí? Eh\'tos son tiempos oscuros.', '¿La Horda está aquí? Eh\'tos son tiempos oscuros.', 28153),
(135147, 'esMX', 'Yo... ¿Qué sucedió? ¡Mejor me largo de aquí!', '', 28153),
(135140, 'esMX', 'Padre, ayúdame. Necesito tu guía. Necesito....', '', 28153),
(135138, 'esMX', '¡Mi rey, hemos perdido nuestras torres de asedio! Nuestras filas se reducen...', '', 28153),
(135002, 'esMX', 'No puedo dejar esta cosa aquí. ¡Llévatela o me la quedaré yo!', '', 28153),
(135001, 'esMX', '¡Si nadie abre el cofre pronto, tendré que lidiar con la matriz de recolección!', '', 28153),
(134991, 'esMX', 'Bueno, no siempre se puede ganar. ¡Vámonos de aquí!', '', 28153),
(134989, 'esMX', '¿En serio? ¿Nadie lo quiere?¡Como quieran...!', '', 28153),
(134976, 'esMX', '¡Yo lo vi primero!', '¡Yo lo vi primero!', 28153),
(134975, 'esMX', '¿Te importa si tiro por necesidad?', '¿Te importa si tiro por necesidad?', 28153),
(134877, 'esMX', '¡Bien, empecemos de una vez! ¡El primero en abrirlo se lleva todo!', '', 28153),
(134876, 'esMX', 'Solo faltan quince segundos. ¡Prepárate para un verdadero caos!', '', 28153),
(134875, 'esMX', '¡Apertura en curso! ¿Podrías esperarme treinta segundos?', '', 28153),
(134869, 'esMX', '¡Carga en camino! ¡Cúbranse la cabeza!', '', 28153),
(134867, 'esMX', 'Escuchen bien: ¡tenemos un cargamento de suministros en camino a los Bajíos!', '', 28153),
(134811, 'esMX', '¡Ya está abierto! ¡El vencedor se lleva todo!', '', 28153),
(134810, 'esMX', '¡Quince segundos hasta completar la apertura!', '', 28153),
(134809, 'esMX', '¡Secuencia de apertura activada! T menos treinta segundos.', '', 28153),
(134790, 'esMX', '¡Carga liberada! ¡Cuidado abajo!', '', 28153),
(134789, 'esMX', '¡Cargamento de suministros en camino a los Bajíos!', '', 28153),
(134699, 'esMX', '', 'Adelántate. Yo tengo un par de cosas más para decirle a esta serpiente de arena.', 28153),
(134678, 'esMX', 'No mataremos a los sapos, ¡pero a ti te masacraremos!', '', 28153),
(134676, 'esMX', '¡Encerraremos y drenaremos a tus amiguitos ranas!', '', 28153),
(134675, 'esMX', '¡Debo proteger su nueva fuente de maná!', '', 28153),
(134674, 'esMX', '¡$USucio:Sucia; $r, no nos privarás de nuestra nueva fuente de maná!', '', 28153),
(134673, 'esMX', '¡Conseguiremos más de estos sapos después de matarte!', '', 28153),
(134672, 'esMX', 'Tenemos órdenes de no matar a los sapos, ¡pero podemos hacer lo que queramos contigo!', '', 28153),
(134671, 'esMX', 'No nos detendrás, ¡los sapos nos alimentarán durante años!', '', 28153),
(134670, 'esMX', '', '¡Los sapos les pertenecen a los nagas!', 28153),
(134669, 'esMX', '', '¡No dejaremos que te lleves nuestro sapos!', 28153),
(134668, 'esMX', '', '¡Muerte $Gal ladrón de maná:a la ladrona de maná;!', 28153),
(134667, 'esMX', '', '¡Ahora estos sapos nos pertenecen!', 28153),
(134666, 'esMX', '', '¡Los sapos nos pertenecen, $Gtonto:tonta;!', 28153),
(134665, 'esMX', '', '¡Estos sapos nos mantendrán durante años!', 28153),
(134664, 'esMX', '', '¡Usaremos estos sapos para salvar a nuestro pueblo!', 28153),
(134663, 'esMX', '', '¡Estos sapos nos alimentarán!', 28153),
(134661, 'esMX', 'El ataque cobarde de la Horda sobre Teldrassil nos llevó a la guerra... y dejó en claro lo que hay en juego.', '', 28153),
(134656, 'esMX', 'Krag\'wa recompensará tu fe. Vamos.', '', 28153),
(134652, 'esMX', '', 'Mi ancestro me contó historia\' sobre Krag\'wa. Nadie le creía... Excepto yo. Quería que fuera verdad.', 28153),
(134651, 'esMX', 'Conozco tus intenciones, Narez. Le has sido fiel a Krag\'wa todo este tiempo.', '', 28153),
(134650, 'esMX', '', '¡Eh\'pera! Antes de que te vayas...', 28153),
(134649, 'esMX', 'Es hora de que regrese al túmulo. Gracias de nuevo por tu ayuda.', '', 28153),
(134648, 'esMX', 'Hasta se dice que tu padre decidió sucumbir a la debilidad y envió a su única hija a rogarle a Zul que regresara con la flota. ¿Es cierto eso, su alteza?', '', 28153),
(134647, 'esMX', '', 'Cómo te atreve\' a hablarme...', 28153),
(134646, 'esMX', 'Podremos repeler a los nagas una vez que nos encarguemos de Zaldraxia. Buena suerte.', '', 28153),
(134639, 'esMX', '¡Han aparecido Demoledores enemigos en la estructura del sur de la Horda!', '¡Han aparecido Demoledores enemigos en la estructura del sur de la Horda!', 28153),
(134638, 'esMX', '', 'En todos los años que pasé en estas colinas, ¡jamás había visto monstruos así!', 28153),
(134637, 'esMX', '<Mostrarle la Palabra de Zul.>', '<Mostrarle la Palabra de Zul.>', 28153),
(134630, 'esMX', '', 'N-no sé qué estarán planeando mi hermana y su-sus amigas, pero seguramente no es nada bueno. ¡Las cosas buenas no exigen sa-sacrificios de sangre!', 28153),
(134629, 'esMX', '', '¡Ta-tantas patas! ¡Tantos ojos! ¡Me buscan!', 28153),
(134620, 'esMX', '', '¡Necesitamos un líder de verdad, no un rey enfermizo!', 28153),
(134618, 'esMX', '', 'Nuestra\' fronteras son débiles. Nuestra gente es débil. Necesitamo\' la fuerza que solo Zul puede darno\'.', 28153),
(134617, 'esMX', '', 'Recuerda las palabra\' de Zul, nuestro profeta. Recuerda que vio la fatalidad que azotaría a nuestra gente.', 28153),
(134616, 'esMX', '', 'El rey Rastakhan se pudre en su trono, y es demasiado débil o cobarde para visitar a su gente. ¡Necesitamos un líder fuerte!', 28153),
(134615, 'esMX', '', 'Zul previó el Cataclismo, y nosotro\' no hicimos nada. Miramos cómo nuestro rey lo desterraba. Miramos cómo Zul se fue con nuestros hermano\' y nuestras hermana\' al exilio. ¡Y fuimos testigo\' de la destrucción que sembró el Cataclismo!', 28153),
(134613, 'esMX', '', 'Zul volverá y levantará a nuestro imperio de las ceniza\'.', 28153),
(134610, 'esMX', '', '¡Ha llegado el momento! Tengo que avisarle\' a los demás. Quiene\' aún le son fiele\' deben enterarse de esto.', 28153),
(134599, 'esMX', '', '¡No te fallaré, reina Azshara! Nos apoderaremos de los sapos. ¡Yo misma me encargaré!', 28153),
(134598, 'esMX', '', '¡Todos sus preciosos sapos serán encerrados y vivirán para servir a nuestros fines!', 28153),
(134597, 'esMX', '', '¡ESCORIA insignificante! ¡Al fin nuestro pueblo satisfará su necesidad de magia! ¡Basta de sed, basta de anhelos!', 28153),
(134596, 'esMX', '', 'No... Estábamos tan cerca... de nunca más... sufrir por sed de magia...', 28153),
(134595, 'esMX', '', '¡Tú! Arruinaste todo... ¡esos sapos iban a alimentar nuestra magia durante años!', 28153),
(134594, 'esMX', 'Los nagas pagarán por sus crímenes.', '', 28153),
(134593, 'esMX', 'Haz que Zaldraxia pague por lo que nos ha hecho.', '', 28153),
(134592, 'esMX', '¡Ja! Mi poder fluye... Gracias. Krag\'wa se enterará de la ayuda que nos brindaste.', '', 28153),
(134591, 'esMX', 'Ah... ¡siento el poder nuevamente! Lo has hecho bien. Krag\'wa se enterará de tus hazañas.', '', 28153),
(134590, 'esMX', 'Me siento... ¡poderoso! Te lo agradezco, pero debo regresar con Krag\'wa.', '', 28153),
(134589, 'esMX', '', 'Hace muchos año\', regresó con nuestra flota del exilio.$b$bY describió su visión de este día en que el mundo sangraría. Y te describió a ti con mucho\' detalles.', 28153),
(134588, 'esMX', '¿Cuándo fue la última vez que hablaste con Zul?', '¿Cuándo fue la última vez que hablaste con Zul?', 28153),
(134587, 'esMX', '', '¡Tú! ¡Eres tú!$b$bUna vez, Zul te describió. Hasta el má\' mínimo detalle. Incluso tienes esa... cosa... en la cara. Tal cual dijo él.$b$bDime, ¿es cierto? ¿Me has traído su palabra?', 28153),
(134584, 'esMX', 'Al fin, ha llegado el momento. He guardado eh\'ta bestia mensajera desde el ascenso del Rey del Trueno. Parece que por fin ha llegado su día.', '', 28153),
(134583, 'esMX', 'La magia de las ranas alimentará a nuestro pueblo. ¡No volveremos a estar sedientos!', '', 28153),
(134581, 'esMX', '<Mostrarle la Palabra de Zul.>', '<Mostrarle la Palabra de Zul.>', 28153),
(134580, 'esMX', '¿Qué quieres, $gforastero:forastera;?', '', 28153),
(134492, 'esMX', '', '¡Al fin un poco de ayuda! La suerte favoreció a los nagas en nuestro enfrentamiento. Tenemo\' que salvar a los sapo\'.', 28153),
(134471, 'esMX', '', 'Ahhhh, ¿qué tenemos aquí? ¿El león de Ventormenta al fin salió a jugar? No sabes a qué te enfrentas, niño rey. ¡Esto es solo el comienzo!', 28153),
(134465, 'esMX', '', 'Pff... Aquí estoy eh\'perando y ocultándome, las dos cosas que más odio. ¡Averigua por qué los nagas quieren eh\'tos sapos!', 28153),
(134464, 'esMX', '¡¿Eso es todo lo que tienes, Brisaveloz?!', '', 28153),
(134463, 'esMX', '¡Todas las unidades a las puertas! ¡Victoria para la Alianza!', '', 28153),
(134460, 'esMX', '', 'Eh\'tos nagas no lograrán profanar a eh\'tos sapos.', 28153),
(134453, 'esMX', 'La princesa no eh\'tá aquí para salvarte.', 'La princesa no eh\'tá aquí para salvarte.', 28153),
(134451, 'esMX', 'Ja, ja. Nadie te salvará excepto yo.', 'Ja, ja. Nadie te salvará excepto yo.', 28153),
(134450, 'esMX', 'A los guardia\' no les importa un bledo tu cuero podrido de $uforastero:forastera;.', 'A los guardia\' no les importa un bledo tu cuero podrido de $uforastero:forastera;.', 28153),
(134449, 'esMX', 'Mi cuchillo dice que me harás un gran deh\'cuento.', 'Mi cuchillo dice que me harás un gran deh\'cuento.', 28153),
(134448, 'esMX', 'Otra vez te demorah\' con el pago de la protección.', 'Otra vez te demorah\' con el pago de la protección.', 28153),
(134447, 'esMX', 'Alteza, ¿acaso no huele el miedo que se ha apoderado de eh\'ta ciudad?', '', 28153),
(134442, 'esMX', 'Je... Je... Los envíos ya partieron...', '', 28153),
(134439, 'esMX', '¡Ah! ¡Más carne para hacer salchichas!', '', 28153),
(134438, 'esMX', '¡Ja! Aún tienes fuerzas para pelear. Déjame mostrarte de lo que es capaz la Horda.', '', 28153),
(134330, 'esMX', '¡Sálvese quien pueda!', '¡Sálvese quien pueda!', 28153),
(134329, 'esMX', '¡Esto es un caos! Debo buscar un lugar seguro.', '¡Esto es un caos! Debo buscar un lugar seguro.', 28153),
(134328, 'esMX', '¡Estos troggs salieron de la nada!', '¡Estos troggs salieron de la nada!', 28153),
(134310, 'esMX', 'El templo está en ruinas. Es peor de lo que temía...', '', 28153),
(134309, 'esMX', 'Antes de ser asesinado, yo era el cuidador de este templo. Temo pensar en qué se habrá convertido en las décadas que siguieron a mi muerte...', '', 28153),
(134300, 'esMX', '¡Auch! Dino malo. ¡Malo!', '¡Auch! Dino malo. ¡Malo!', 28153),
(134299, 'esMX', '¡Esto se te da muy bien!', '¡Esto se te da muy bien!', 28153),
(134298, 'esMX', '¡Ahhhh! ¡Los dedo\' no!', '¡Ahhhh! ¡Los dedo\' no!', 28153),
(134297, 'esMX', '¡Si te vuelve\' muy travieso, te daré un par de golpe\'!', '¡Si te vuelve\' muy travieso, te daré un par de golpe\'!', 28153),
(134296, 'esMX', '¡Auch! ¡No muerdah\'!', '¡Auch! ¡No muerdah\'!', 28153),
(134295, 'esMX', 'Con cuidado... ¡Con cuidado!', 'Con cuidado... ¡Con cuidado!', 28153),
(134292, 'esMX', '%s tiembla y se queja.', '', 28153),
(134291, 'esMX', '%s lanza un chillido de advertencia.', '', 28153),
(134290, 'esMX', '%s lanza un chillido de miedo.', '', 28153),
(134289, 'esMX', 'Te guiaré por las ruinas del templo.', 'Te guiaré por las ruinas del templo.', 28153),
(134288, 'esMX', 'Níquel ladra en dirección a un armiño.', '', 28153),
(134279, 'esMX', '¡Se alimentan con mi magia!', '', 28153),
(134278, 'esMX', '¡Están robando nuestra magia!', '', 28153),
(134277, 'esMX', 'Ohh... Mi magia se desvanece...', '', 28153),
(134276, 'esMX', 'Me siento... sin fuerzas... ¡Me quitaron mi poder!', '', 28153),
(134275, 'esMX', '¡Esos malignos secuestraron a mis amigos!', '', 28153),
(134274, 'esMX', '¡Esos canallas estaban drenando mi magia!', '', 28153),
(134272, 'esMX', 'No esta vez...', '', 28153),
(134271, 'esMX', '¡La Alianza no abandona a sus soldados!', '', 28153),
(134270, 'esMX', '¡Está reviviendo a los muertos! ¡Debemos retirar a los heridos!', '', 28153),
(134266, 'esMX', '¡VICTORIA PARA LOS RENEGADOS!', '', 28153),
(134263, 'esMX', '¡Mi rey, el añublo es demasiado peligroso! No podemos salvar...', '', 28153),
(134252, 'esMX', 'Que la Luz los bendiga a todos. ¡Tráiganme a los heridos!', '', 28153),
(134233, 'esMX', '', 'Gracias a todos. A partir de ahora, ¡yo me encargo!', 28153),
(134230, 'esMX', '¡Malditos... salvajes!', '¡Malditos... salvajes!', 28153),
(134229, 'esMX', 'Muero... por mi rey... por Lordaer...', 'Muero... por mi rey... por Lordaer...', 28153),
(134227, 'esMX', 'No termina nunca... ¡Siguen llegando! ¡Héroes, ayuden a rechazarlos!', 'Esto no tiene fin... ¡siguen apareciendo! Héroes, ¡ayuden a combatirlos!', 28153),
(134226, 'esMX', '', 'Ehhhh... ¿Me ayudan por favor?', 28153),
(134224, 'esMX', '', '¡Arqueros, preparen sus flechas! ¡Avancen!', 28153),
(134223, 'esMX', '¡Héroes! ¡No podremos resistir! No puedo... mantenerlos con vida mucho más tiempo...', '', 28153),
(134211, 'esMX', 'Qué liiindaaaa...', '', 28153),
(134209, 'esMX', 'Espera, ¿oyes eso?', '', 28153),
(134208, 'esMX', '¡Timonel, sáquenos de aquí!', '¡Timonel, sáquenos de aquí!', 28153),
(134186, 'esMX', '¡Tiene\' razón! Es hora de que $p reciba la bienvenida oficial de la pandilla. ¡Preparen el ritual!', '', 28153),
(134164, 'esMX', '', 'Ven, Drekal. Sigamos con nueh\'tra búsqueda.', 28153),
(134163, 'esMX', '', 'No veo nada de interéh\' aquí.', 28153),
(134162, 'esMX', '', '¿Por qué nos llamah\'te?', 28153),
(134161, 'esMX', '', '¿Sabes lo que le sucedió a ese $r que fingía necesitar ayuda?', 28153),
(134159, 'esMX', '', '¿Cree\' que esto es un juego?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134158, 'esMX', 'Ay, no... Creo que mi barril tiene orina...', '', 28153),
(134157, 'esMX', '¡Los clientes quieren su mercadería de inmediato! ¡Nos vamos!', '¡Los clientes quieren su mercadería de inmediato! ¡Nos vamos!', 28153),
(134156, 'esMX', '', '¡Ha habido un cambio de horario, muchachos! ¡Llévense sus grogs para el camino!', 28153),
(134155, 'esMX', '', '¿Por qué nos haces perder el tiempo?', 28153),
(134151, 'esMX', '', 'Esa bengala de señalización no e\' un juguete.', 28153),
(134150, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Defender estructura del sur de la Alianza', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Defender estructura del sur de la Alianza', 28153),
(134149, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Defender estructura del norte de la Alianza', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Defender estructura del norte de la Alianza', 28153),
(134125, 'esMX', '', 'No importa, no podemos eh\'perarlo. He encontrado a alguien que dice saber dónde está Rakera. ¡Vamos, por aquí!', 28153),
(134123, 'esMX', '', 'No nos quedemo\' aquí más tiempo del necesario. Lanza una bengala si encuentras algo de interés.', 28153),
(134116, 'esMX', '¡Estas tierras son nuestras, perros! ¡Pagarán con sus vidas!', '', 28153),
(134115, 'esMX', '¡Soldados! ¡A sus posiciones! ¡Formen filas!', '', 28153),
(134111, 'esMX', 'No echaré de menos este lugar ni un poco.', '', 28153),
(134109, 'esMX', '', 'Exiges mucho para estar tan cerca de mi eh\'pada.', 28153),
(134101, 'esMX', '¡Este no es tu lugar!', '¡Este no es tu lugar!', 28153),
(134100, 'esMX', 'Ooh, ¡yo quiero el barril vacío! Tú puedes quedarte con el otro.', '', 28153),
(134099, 'esMX', '¡Escóndete, rápido!', '', 28153),
(134096, 'esMX', 'El secreto sucio de Aspafresno.', '', 28153),
(134095, 'esMX', '¡¿Qué fue ESO?!', '', 28153),
(134094, 'esMX', '¿Seguro que quieres construir una Torre de observación por 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de batalla?', '¿Seguro que quieres construir una Torre de observación por 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de batalla?', 28153),
(134093, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Construir Torre de observación', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Construir Torre de observación', 28153),
(134092, 'esMX', 'Sí, sí, Man\'zul. Tendríamo\' que haberte escuchado. No merecías eh\'te destino. Tendríamos que haber seguido tu plan. Ere\' tan inteligente. Lo recuerdo. ¡Ahora, cállate o volveré a pellizcarte la nariz!', '', 28153),
(134091, 'esMX', '¡Man\'zul! Eh\'ta es una posada familiar. Eso\' días quedaron atrás.', '', 28153),
(134090, 'esMX', '¡Ja! Me gusta tu eh\'tilo, $p, pero yo te supero. Lo único que le queda es ese parche feo y esa sonrisa arrebatadora.', '', 28153),
(134089, 'esMX', '¡Volni, deja de desafiar a duelo a nuestro\' invitados! Los últimos dos que mataste no habían pagado la cuenta.', '', 28153),
(134088, 'esMX', '¡Hablen en voz alta! ¡No puedo escuchar si se ponen a murmurar como jerbo\' por allá!', '', 28153),
(134087, 'esMX', 'No engaña\' a nadie, Volni. Sé que te encanta ese sombrero que te regalé, ¡y no pienso dejarte quitarlo hasta que lo reconoh\'cas!', '', 28153),
(134086, 'esMX', 'Eh\'pera, con los golpes incesantes de su tambor no te oye. ¡Detente, Grenja! $p quiere saludarte. Grenja es nueh\'tra trovadora, pero a veces se olvida que las persona\' tienen que hablar aquí.', '', 28153),
(134085, 'esMX', '...¿Eh\'tás bien, $p? Estás asustando a Grenja... ¿Te dio un golpe de calor?', '', 28153),
(134084, 'esMX', '¡Qué buen ojo, $p! Cuando vivíamos en Zuldazar, Grenja nos sacó de muchas situaciones embarazosa\'. Mantuvo muchísimah\' puertas abiertas y derribó otras tantas... También derribó personas.', '', 28153),
(134079, 'esMX', 'Muy bien, ¡es hora de trabajar!', '', 28153),
(134078, 'esMX', 'Sin embargo... le hiciste un gran favor a nuestro pueblo, por lo que estoy sumamente agradecido. Veré qué puedo hacer...', '', 28153),
(134077, 'esMX', 'Dudo que estén dispuestos a abrirle las puertas a un continental.', '', 28153),
(134076, 'esMX', 'Una maldición ha caído sobre esta tierra, y cuando se manifestó, los Tarjasenda salieron corriendo como unos cobardes. Se ocultan en su mansión, mientras su pueblo sucumbe ante un mal oculto.', '', 28153),
(134075, 'esMX', '¿Quieres reunirte con los cobardes de Tarjasenda? Nada bueno puede salir de eso.', '', 28153),
(134074, 'esMX', 'Deseo conocer al señor de la casa Tarjasenda.', 'Deseo conocer al señor de la casa Tarjasenda.', 28153),
(134073, 'esMX', 'Las palabras no me alcanzan para agradecerte lo que hiciste por nuestro pueblo, continental. \n\nAmparo del Ocaso está en deuda contigo.', '', 28153),
(134072, 'esMX', '¿En qué puedo ayudarte, $c?', '', 28153),
(134070, 'esMX', '', 'Ah, ¡has regresado! Te ausentah\'te más de lo que eh\'peraba. ¿Algún problema?', 28153),
(134069, 'esMX', '', 'Puedes usar mi cohete para regresar a tu base. Es un viaje de ida, así que no lo pongas en marcha hasta que estés $Ulisto:lista; para partir.', 28153),
(134068, 'esMX', '', 'Oye, eh... Lo has hecho muy bien, sí, pero nosotros nos podemos encargar del resto.', 28153),
(134067, 'esMX', 'Salgamos de aquí.', 'Salgamos de aquí.', 28153),
(134066, 'esMX', 'Salamandra asegura que su cohete es un vehículo seguro. La construcción endeble no reafirma sus aseveraciones.', '', 28153),
(134065, 'esMX', '¡Aplassssten todo lo que se ressssista! ¡Por la gloria de la reina!', '', 28153),
(134064, 'esMX', '¡Desssstruyan todo lo que salga del templo!', '', 28153),
(134063, 'esMX', '¡Protejan lassss reliquiassss para la reina!', '', 28153),
(134062, 'esMX', '¡La reina reclama esassss reliquiassss! ¡Guárdenlasssss, rápido!', '', 28153),
(134061, 'esMX', '¡Qué bien! Todos volvieron sanos y salvos gracias a... ¡Ah, aquí está $Unuestro héroe:nuestra heroína;!', '', 28153),
(134060, 'esMX', 'Mis... Tesoro\'...', '', 28153),
(134059, 'esMX', '¡¿Cómo te atreve\' a tocar mi tesoro?!', '', 28153),
(134018, 'esMX', '<Intenta abrir el cofre.>', '<Intenta abrir el cofre.>', 28153),
(134017, 'esMX', 'El cofre está sellado, pero tras forcejear un poco lograrás abrirlo.', '', 28153),
(134016, 'esMX', '', 'Parece que ya ha anclado otra nave de la Alianza. Espero que reciban una bienvenida más cálida que Jaina...', 28153),
(134015, 'esMX', '¡Eres mi salvación!', '', 28153),
(134014, 'esMX', 'No me olvidaré de esto. ¡Gracias!', '', 28153),
(134013, 'esMX', '¡Te debo una pinta!', '', 28153),
(134012, 'esMX', 'Gracias, no podría haber resistido mucho más.', '', 28153),
(134011, 'esMX', 'Los nagas se llevaron al resto en cadenas. ¡Por favor, libéralos a ellos también!', '', 28153),
(134010, 'esMX', '¡Sangre y honor! ¡La próxima vez que nos veamos, yo invitaré los tragos!', '', 28153),
(134009, 'esMX', '', 'No sé qué acaba de sucederte, ¡pero parece que funcionó! ¿Estás... bien?', 28153),
(134007, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(134003, 'esMX', '¡Luchen unidos! ¡POR LA ALIANZA!', '', 28153),
(134001, 'esMX', 'Para asegurar nuestro futuro, la Reina alma en pena debe responder por sus crímenes. ¡Su reinado oscuro termina hoy!', '', 28153),
(134000, 'esMX', 'Su jefa de guerra no quería capturar una ciudad, sino acabar con nuestro estilo de vida... y extinguir la esperanza de las generaciones venideras.', '', 28153),
(133999, 'esMX', 'Juntos, expulsaremos el mal de esta tierra... ¡y Lordaeron lucirá nuestros estandartes una vez más!', '', 28153),
(133998, 'esMX', 'Hermanos y hermanas de la Alianza, ¡escuchen!', '', 28153),
(133996, 'esMX', '¡El rey Anduin dirige el asalto! ¡Crucen las reservas y aseguren el campo de batalla!', '', 28153),
(133990, 'esMX', '¡Máquina de asedio lista para la acción!', '', 28153),
(133989, 'esMX', '¡Una Máquina de asedio para $gun muchacho bonito:una muchacha bonita;!', '', 28153),
(133988, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Construir Máquina de asedio', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Construir Máquina de asedio', 28153),
(133986, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Entrenar Especialista en morteros - Atacar el norte', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Entrenar Especialista en morteros - Atacar el norte', 28153),
(133985, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Entrenar Caballeros - Atacar el norte', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Entrenar Caballeros - Atacar el norte', 28153),
(133984, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Entrenar Fusileros - Atacar el norte', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Entrenar Fusileros - Atacar el norte', 28153),
(133983, 'esMX', 'Necesito más recursos para cumplir mis órdenes.', '', 28153),
(133982, 'esMX', '¡Bienvenid$go:a; a mi tienda!', '', 28153),
(133981, 'esMX', '', '¡Maestra de establos Lucia Farondale, a su servicio!', 28153),
(133980, 'esMX', '', 'Entrenar a nuestros jinetes es costoso, $n.', 28153),
(133979, 'esMX', '', '¡Me alegra volver a verte, $n! ¿En qué puedo ayudarte?', 28153),
(133974, 'esMX', '', '¡No podemos entrenar sin oro!$B$B¡Recoge un poco más de oro y vuelve a verme!', 28153),
(133971, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Entrenar Caballeros - Atacar el sur', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Entrenar Caballeros - Atacar el sur', 28153),
(133970, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Entrenar Especialista en morteros - Atacar el sur', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Entrenar Especialista en morteros - Atacar el sur', 28153),
(133969, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Entrenar Fusileros - Atacar el sur', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Entrenar Fusileros - Atacar el sur', 28153),
(133968, 'esMX', '', '¿Por qué tardaste tanto? ¡Ponte a trabajar!', 28153),
(133960, 'esMX', '<Presentarte amablemente.>', '<Presentarte amablemente.>', 28153),
(133959, 'esMX', '<Presentarte amablemente.>', '<Presentarte amablemente.>', 28153),
(133958, 'esMX', '', '¿Está a salvo? Le dije a Kaja que no viniera a buh\'carme.', 28153),
(133953, 'esMX', 'Antaño, esta ciudad hundida fue un templo hermoso dedicado al loa del mar, Gral.$b$bPero los nagas llegaron y destruyeron el templo. Todos sus seguidores fueron asesinados.$B$BSi Gral sobrevive, no tendrá fuerza.', '', 28153),
(133952, 'esMX', '¿Qué e\' lo que sucede, colega? ¿Estamo\' bajo ataque?', '', 28153),
(133951, 'esMX', '¡Algo cayó del cielo! ¡Eh\'tá por aquí!', '', 28153),
(133950, 'esMX', 'Mis hermanos permiten que su odio por los nagas les nuble el juicio. Esta no es la primera vez que la señora Ssin y sus nagas enroscamiedos nos han seguido hasta un hallazgo tan valioso.$b$bEstán al tanto de que nosotros sabemos algo que ellos no saben.', '', 28153),
(133947, 'esMX', '', '¡Pedirás piedad!', 28153),
(133946, 'esMX', 'Necesito viajar a Hondonada Penumbrosa.', 'Necesito viajar a Hondonada Penumbrosa.', 28153),
(133945, 'esMX', '¡Morirás al filo de mi espada!', '¡Morirás al filo de mi espada!', 28153),
(133944, 'esMX', '¿Necesita\' transporte?', '', 28153),
(133943, 'esMX', '¡No me llevo prisioneros!', '¡No me llevo prisioneros!', 28153),
(133942, 'esMX', '', '¡Pagarás por esta interrupción con tu vida!', 28153),
(133941, 'esMX', '', 'Destruyan este campamento. Quiero que me traigan todo lo que tenga que ver con lo que Goji y los de su clase estaban haciendo aquí.', 28153),
(133939, 'esMX', '¡La reina pirata vengará mi muerte!', '', 28153),
(133938, 'esMX', '¿Quién dejó subir a este idiota a mi barco?', '', 28153),
(133936, 'esMX', '¡Muere, gusano!', '¡Muere, gusano!', 28153),
(133935, 'esMX', 'Conque te crees valiente, ¿eh?', 'Conque te crees valiente, ¿eh?', 28153),
(133934, 'esMX', '¡Todo lo que tengas ahora es mío!', '¡Todo lo que tienes ahora es mío!', 28153),
(133933, 'esMX', '¡Esta tierra pertenece a Compañía Aspafresno!', '¡Esta tierra pertenece a la Compañía Aspafresno!', 28153),
(133929, 'esMX', '¡Nadie te quiere aquí!', '¡Aquí nadie te quiere!', 28153),
(133928, 'esMX', '¡No saldrás de aquí con vida!', '¡No saldrás de aquí con vida!', 28153),
(133926, 'esMX', 'No olvidaré tu amabilidad...', 'No olvidaré tu amabilidad...', 28153),
(133925, 'esMX', 'Por fin, el tormento ha terminado...', 'Por fin, el tormento ha terminado...', 28153),
(133924, 'esMX', 'Te lo agradezco, visitante...', 'Te lo agradezco, $Gforastero:forastera;...', 28153),
(133923, 'esMX', 'Sabía que Eraka no Kimbul nos enviaría ayuda...', 'Sabía que Eraka no Kimbul nos enviaría ayuda...', 28153),
(133919, 'esMX', 'Por fin puedo descansar en paz...', 'Por fin puedo descansar en paz...', 28153),
(133918, 'esMX', 'Sabía que los loa no nos olvidarían...', 'Sabía que los loa no nos olvidarían...', 28153),
(133917, 'esMX', 'Salta sobre el obstáculo designado. ¡Puede que el juez no lo considere válido si no saltas por el centro!', 'Salta sobre el obstáculo designado. ¡Puede que el juez no lo considere válido si no saltas por el centro!', 28153),
(133916, 'esMX', 'Si saltas antes o después de tiempo, tu caballo podría arrojarte al suelo.', 'Si saltas antes o después de tiempo, tu caballo podría arrojarte al suelo.', 28153),
(133915, 'esMX', '¡No te preocupes, no me perderé! De todos modos, si me pierdo sé que me buscarías.', '', 28153),
(133913, 'esMX', '¡Cuando vayas a medio galope puedes usar Galope para aumentar la velocidad!', '¡Cuando vayas a medio galope puedes usar Galope para aumentar la velocidad!', 28153),
(133912, 'esMX', 'Usa Medio galope para moverte más rápido. ¡Esta es la mejor velocidad para saltar!', 'Usa Medio galope para moverte más rápido. ¡Esta es la mejor velocidad para saltar!', 28153),
(133911, 'esMX', 'Usa Caminar para avanzar y Frenar para detenerte en cualquier momento.', 'Usa Caminar para avanzar y Frenar para detenerte en cualquier momento.', 28153),
(133904, 'esMX', 'Los gilgoblins son unas criaturas espantosas. Esos pequeños impostores del mar estarán felices de cumplir los deseos de sus amos nagas aunque parezcan desdeñosos.', '', 28153),
(133899, 'esMX', 'Hmm... Quizás Shoak comprenda que este no es un lugar para explorar. ¡Es un lugar del que debemos marcharnos!', '', 28153),
(133893, 'esMX', 'Hmm... De nada, idiota. ¡No se te ocurra escaparte de nuevo!', '', 28153),
(133883, 'esMX', '¡Han aparecido Demoledores enemigos en la estructura del norte de la Horda!', '¡Han aparecido Demoledores enemigos en la estructura del norte de la Horda!', 28153),
(133835, 'esMX', 'Lamentablemente, armar un ejército no es nada barato, $n. Tenemos que alimentarlos, entrenarlos y forjar sus armaduras a mano.\n\nRegresa cuando tus bolsillos pesen un poco más.', '', 28153),
(133834, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Entrenar Lacayos - Atacar el sur', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Entrenar Lacayos - Atacar el sur', 28153),
(133833, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Entrenar Lacayos - Atacar el norte', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Entrenar Lacayos - Atacar el norte', 28153),
(133832, 'esMX', '', '¿Cuánto\' cuerpos... has comido... para conseguir este poder?', 28153),
(133831, 'esMX', '', 'Hemos oído susurro\' sobre ti... ¡Me daré un festín contigo!', 28153),
(133830, 'esMX', '', 'Será mejor... que no me coma\'... para quedarte... con mi poder...', 28153),
(133829, 'esMX', '', '¡Creo que me comeré tu brazo ante\' de lanzarte al tótem!', 28153),
(133828, 'esMX', '', 'Los susurro\'... dicen que la carne... nos fortalecerá...', 28153),
(133827, 'esMX', '', '¡Los susurro\' dicen que tu carne nos dará poder!', 28153),
(133820, 'esMX', 'No tienes suficiente oro del frente de guerra para construir una edificación.', 'No tienes suficiente oro del frente de guerra para construir una edificación.', 28153),
(133819, 'esMX', 'No podemos construir una edificación si ya hay una en curso.', 'No podemos construir una edificación si ya hay una en curso.', 28153),
(133806, 'esMX', 'Si regresas a este templo, serás $utratado:tratada; como $uamigo e invitado de honor:amiga e invitada de honor;.', '', 28153),
(133805, 'esMX', 'En reconocimiento de tu valor, te ofrezco una bendición de poder. Que te sea útil en las batallas venideras.', '', 28153),
(133804, 'esMX', 'Además, has rescatado los espíritus de mis seguidores de la destrucción y has brindado tu ayuda a este templo.', '', 28153),
(133803, 'esMX', 'Kuppaka finalmente ha sido asesinado, y los artefactos de poder robados fueron arrancados de las manos de los Tortaka.', '', 28153),
(133801, 'esMX', 'Los Tortaka están más allá de la redención. Kuppaka y los de su tribu deben morir. Y las fuentes de su poder oscuro deben ser destruidas.', '', 28153),
(133799, 'esMX', 'Nunca imaginé que su deseo de poder los llevaría a un extremo de tanta maldad... ¿Qué se puede hacer?', '', 28153),
(133798, 'esMX', 'La tribu Tortaka no se detendrá hasta haber succionado la energía de cada espíritu del templo.', '', 28153),
(133794, 'esMX', '¿Seguro que quieres construir una Herrería por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de batalla?', '¿Seguro que quieres construir una Herrería por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de batalla?', 28153),
(133793, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150Construir Herrería', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construir Herrería', 28153),
(133790, 'esMX', '¿Seguro que quieres construir un taller por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de guerra?', '¿Segura que quieres construir un taller por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de guerra?', 28153),
(133788, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construir taller', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construir taller', 28153),
(133786, 'esMX', '¿Seguro que quieres construir unos establos por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de guerra?', '¿Segura que quieres construir unos establos por 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t de oro del frente de guerra?', 28153),
(133785, 'esMX', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construir establos', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construir establos', 28153),
(133784, 'esMX', 'Elige la edificación que deseas construir en esta ubicación:', 'Elige la edificación que deseas construir en esta ubicación:', 28153),
(133775, 'esMX', 'Shoak se metió en problemas... ¡otra vez! No puedo creer que a ese idiota lo capturaran los trols de sangre.', '', 28153),
(133769, 'esMX', '¡SHOAK! ¿Dónde estás? ¡SHOAK!', '', 28153),
(133768, 'esMX', 'Conozco un buen lugar donde podemos arriarlos a todos. ¡Vamos!', '', 28153),
(133765, 'esMX', '¡Tu alma está perdida!', '', 28153),
(133764, 'esMX', '¡Tu loa no tiene poder aquí!', '', 28153),
(133763, 'esMX', '¡Tu alma será nuestra!', '', 28153),
(133760, 'esMX', '¡Los tortaka no toleramos a los forasteros!', '', 28153),
(133759, 'esMX', '¡No eres $gbienvenido:bienvenida; aquí!', '', 28153),
(133758, 'esMX', '¡Eraka no Kimbul no tiene poder aquí!', '', 28153),
(133757, 'esMX', '¡El poder de este reino es nuestro!', '', 28153),
(133756, 'esMX', '¡Ni siquiera el loa puede detenernos!', '', 28153),
(133755, 'esMX', '¡Te mostraré mi verdadero poder!', '', 28153),
(133754, 'esMX', '¡El poder será nuestro!', '', 28153),
(133752, 'esMX', '¡Nos alimentaremos con tu alma!', '', 28153),
(133745, 'esMX', '', '¿Qué sabesss de nuestros planessss? ¡Dímelo ya!', 28153),
(133742, 'esMX', '', '¡Habla! ¿Qué secretosss conocesssss sobre el templo?', 28153),
(133741, 'esMX', '', '¡Hablarásssss o te ahogaré!', 28153),
(133732, 'esMX', 'Tú rescata a Shoak, yo iré a algún lugar más seguro. No tiene sentido que tengas que rescatarnos a los dos.', '', 28153),
(133731, 'esMX', '[Después de un corto viaje en ferry...]', '[Después de un corto viaje en ferry...]', 28153),
(133730, 'esMX', 'Gracias por el aventón, Tae. Informaré al viejo.', '', 28153),
(133729, 'esMX', 'Ese idiota... ¿Por qué dejó que lo capturaran los trols de sangre?', '', 28153),
(133728, 'esMX', 'Los trols natha\'vor han capturado a Shoak...', '', 28153),
(133727, 'esMX', '¡No... no, no!', '', 28153),
(133726, 'esMX', 'Ay, no...', '', 28153),
(133725, 'esMX', '¡Ya deja de andar en círculos y encuentra a Shoak...!', '', 28153),
(133724, 'esMX', 'Ey. ¿Qué fue ese ruido? Yo cuidaré a la princesa. Ve a inveh\'tigar.', '', 28153),
(133723, 'esMX', 'Amparo del Ocaso está en deuda contigo. ¿Cómo podemos recompensarte?', '', 28153),
(133722, 'esMX', 'Supongo que debo agradecerte a ti... Creí que jamás despertaría de esa maldición...', '', 28153),
(133721, 'esMX', 'Qué... ¿Qué sucede?', '', 28153),
(133720, 'esMX', '', '¡Has regresado! ¡Y parece que los aldeanos están recuperando la conciencia!', 28153),
(133719, 'esMX', '', 'No puedes detener... mi maldición...', 28153),
(133718, 'esMX', '', 'Tenemos un poder ancestral. ¡Este será tu fin!', 28153),
(133717, 'esMX', '', '¡Te mostraré el poder del aquelarre!', 28153),
(133716, 'esMX', '', 'Será mejor que te marches, a menos que quieras compartir su destino.', 28153),
(133715, 'esMX', '', '¡$UForastero insípido:Forastera insípida;! Esta aldea me pertenece. ¡Así lo ha dispuesto la Madre!', 28153),
(133714, 'esMX', 'Es una mujer peligrosa... ¡pero no tan peligrosa como puedo llegar a ser yo si me entero que estás portándote mal!', 'Es una mujer peligrosa... ¡pero no tan peligrosa como puedo llegar a ser yo si me entero que te estás portando mal!', 28153),
(133713, 'esMX', 'No sé qué tramas, pero será mejor que esa maniática del bosque no esté involucrada.', 'No sé qué tramas, pero espero que esa maniática del bosque no esté involucrada.', 28153),
(133712, 'esMX', 'Querido esposo: No sé a quién crees que engañas. He visto cómo te escabulles hacia las laderas cuando piensas que duermo.', 'Querido esposo: No sé a quién crees que engañas. He visto cómo te escabulles hacia las laderas mientras crees que duermo.', 28153),
(133711, 'esMX', 'Intentaré hacer otro envío al final de la semana.', 'Intentaré realizar otro envío al final de la semana.', 28153),
(133710, 'esMX', 'Mis puercos contrajeron una enfermedad que los ha vuelto inusualmente agresivos. Se me ha hecho difícil encorralarlos.', 'Mis puercos contrajeron una enfermedad que los ha vuelto inusualmente agresivos. Se me ha hecho difícil encorralarlos para transportarlos.', 28153),
(133709, 'esMX', 'Una anciana amable que está al final del camino me dio unas plantas para alimentar a los cerdos, pero me temo que estaban contaminadas.', 'Una anciana amable que está al final del camino me dio unas plantas para alimentar a los cerdos, pero me temo que estaban contaminadas.', 28153),
(133708, 'esMX', 'Estimado supervisor Staughton: Lamento la demora en el último envío de carne.', 'Estimado supervisor Staughton: Lamento la demora en el último envío de carne.', 28153),
(133707, 'esMX', 'Por favor, denuncien cualquier actividad o persona sospechosa al alcalde White de inmediato.', '', 28153),
(133706, 'esMX', 'Además, hemos recibido informes sobre la presencia de criaturas peligrosas en las laderas. Recomendamos extrema cautela a quienes tengan asuntos fuera de la ciudad.', '', 28153),
(133705, 'esMX', 'Por su propia seguridad, todos los aldeanos deben estar de regreso en su hogar antes de la puesta del sol.', '', 28153),
(133704, 'esMX', 'Debido a una serie de desapariciones recientes, se impondrá un nuevo toque de queda estricto en Amparo del Ocaso.', '', 28153),
(133703, 'esMX', '¡Apostaría mi última antorcha a que esa bruja decrépita está involucrada!', '¡Apostaría mi última antorcha a que esa bruja decrépita está involucrada!', 28153),
(133702, 'esMX', 'A este paso, nos quedaremos sin alimento para los cerdos en un mes. ¿Qué clase de maldición ha caído sobre este lugar?', 'A este paso, nos quedaremos sin alimento para los cerdos en un mes. ¿Qué clase de maldición ha caído sobre este lugar?', 28153),
(133701, 'esMX', 'No sé de dónde salieron estas moscas malditas, pero desde hace dos semanas aparecen todas las mañanas.', 'No sé de dónde salieron estas moscas malditas, pero desde hace dos semanas aparecen todas las mañanas.', 28153),
(133700, 'esMX', '', 'Busca entre las escrituras recientes de los aldeanos. Puede que nos ayuden a encontrar quién está detrás de esto.', 28153),
(133699, 'esMX', '', 'Veré si puedo encontrar información en los registros de la ciudad. Si los aldeanos vieron algo sospechoso, es posible que lo hayan asentado en algún lugar.', 28153),
(133698, 'esMX', '', 'Ay no... ¡Este lugar no!', 28153),
(133693, 'esMX', '', 'Tú no entiendes. Nadie eh\'tará a salvo si Jakra\'zet triunfa.', 28153),
(133692, 'esMX', '', '¡No podía dejar que murieras! Podemos eh\'capar de todo esto. Comenzar una nueva vida en algún lugar seguro.', 28153),
(133691, 'esMX', '', 'No deberías haber venido a buh\'carme, Kaja.', 28153),
(133690, 'esMX', '', 'Pensé que no volvería a verte nunca máh\'...', 28153),
(133689, 'esMX', 'Al menos destruimos algunos de los tótems. Veamos si podemos encontrar a ese patán...', '', 28153),
(133688, 'esMX', '¡SHOAK! ¡Esto no es gracioso, estoy demasiado cerca del puesto de avanzada de los trols de sangre!', '', 28153),
(133686, 'esMX', '', '¡Rakera! ¡Eh\'tás viva!', 28153),
(133685, 'esMX', 'Zolani, mi espada. Tenemo\' que defender el templo. ¡Vamo\'!', '', 28153),
(133672, 'esMX', '¡Cumpliré con la voluntad de mi ama!', '', 28153),
(133670, 'esMX', '¡Hora de aplah\'tar!', '', 28153),
(133669, 'esMX', 'Ven, pequeño rey. ¡Estos herejes conocerán la ruina!', '', 28153),
(133668, 'esMX', 'Pero te juro, y le juro a $Ueste campeón:esta campeona; de la Horda que no deh\'cansaré hasta tener la cabeza de Zul.', '', 28153),
(133667, 'esMX', 'Perdí fuerza\'. Mucho\' trataron de advertirme... incluso mi propia hija. No los escuché.', '', 28153),
(133666, 'esMX', 'Es momento de preguntarte: ¿eres el rey o eres la presa?', '', 28153),
(133665, 'esMX', 'Ahora hay sangre en las aguas.', '', 28153),
(133664, 'esMX', 'Tu consejo desafía tu autoridad. Tus amigos intentan quitarte la vida.', '', 28153),
(133663, 'esMX', 'Rastakhan, tus enemigos amenazan tus fronteras.', '', 28153),
(133648, 'esMX', 'Magno, ¿reh\'piras? Deja que te libere de esas cadena\'.', '', 28153),
(133646, 'esMX', 'Zul predijo tu llegada. Todo sucede tal como lo anunció.', '', 28153),
(133645, 'esMX', '', '¡Tonto! Si tuviera tiempo, te aplah\'taría por lo que le hiciste a Vol\'kaal.', 28153),
(133644, 'esMX', '', 'Muere, Shadra. ¡Muere para siempre! Por las antiguas tradicione\', ¡tu poder ahora me pertenece!', 28153),
(133643, 'esMX', 'Me adelantaré mientras tú destruyes esos tótems. Espero que podamos encontrar a ese tonto después de acabar con los tótems.', '', 28153),
(133638, 'esMX', '', '¡Vol\'kaal! Deshazte de estos intrusos mientra\' me encargo de Shadra.', 28153),
(133633, 'esMX', '', '¡Shadra! Durante años fuih\'te mi guía. Pero a partir de hoy, ¡sirvo a un nuevo amo!', 28153),
(133632, 'esMX', '', 'Llegan demasiado tarde. ¡La sangre de eh\'ta loa ya se ha derramado!', 28153),
(133610, 'esMX', '¡Gonk enloquecido! ¡Gonk aplasta Yazma!', '', 28153),
(133606, 'esMX', 'Tus acciones no han pasado desapercibidas. Tienes mis bendiciones.', '', 28153),
(133605, 'esMX', 'Graciah\', $n. Te has ganado mi bendición.', '', 28153),
(133591, 'esMX', '<Un mensaje breve aparece garabateado a un costado del cohete.>$b$bATENCIÓN: Mensaje oficial.$B$BNO LEA ESTO si no pertenece al rango de comandante de la Horda.$b$bDe: Parche, escuadrón goblin$b$bHan enviado a mi equipo para desplegar artillería y ayudar a que se concreten nuestros planes en Nazmir. Llevamos un cañón que se encargará enseguida de cualquier cosa que se nos oponga.$B$BEstamos en el Libación y buscamos una zona de anclaje en la costa oriental. Solicitamos un guía que nos conduzca a un punto de despliegue.', '', 28153),
(133582, 'esMX', '*Gruñido* Me quedaré por ahora, al menos para ayudar a los espíritus de mis mejores seguidores, que fueron asesinados por tu estupidez.', '', 28153),
(133581, 'esMX', 'Fue un pequeño error... ¡Pero mira a tu alrededor! ¿Acaso este lugar no te trae buenos recuerdos? ¡Quédate y déjanos reconstruir este templo en tu honor!', '', 28153),
(133580, 'esMX', 'Los tortollanos tienen costumbres extrañas, mi señor. ¿Cómo iba a saber que rechazar una propuesta de matrimonio podía considerarse un acto de guerra?', '', 28153),
(133579, 'esMX', 'Tenías una tarea muy simple: celebrar la paz con los Tortaka y cuidar mi templo mientras yo no estaba. ¡Y mira lo que este lugar!', '', 28153),
(133578, 'esMX', '*Ejem* Soy yo, gran loa. Tu fiel y leal servidor, Vunanju.', '', 28153),
(133576, 'esMX', '', 'Hay un viejo dicho aquí en Kul Tiras.$B$BCuando algo sale mal, los marineros simplemente lo ignoran y dicen: \"No puedes cambiar los vientos\".$B$BOdio ese dicho.', 28153),
(133575, 'esMX', '', 'Cyrus me crio desde pequeña. Me enseñó a luchar, a cabalgar y a navegar.$B$BCuando ingresé en la guardia, estaba mejor entrenada que algunos de mis instructores.$B$BEso no les gustó nada.', 28153),
(133574, 'esMX', '', 'Todo aquí cambió cuando Daelin Valiente fue derrotado.$B$BJaina debe haber tenido sus motivos... ¿verdad?', 28153),
(133573, 'esMX', '', 'Crecí escuchando historias sobre el gran reino de Lordaeron.$B$BY sobre su caída.$B$BLa Plaga se llevó a mi madre, a mi padre y a mi tierra natal antes de tuviera edad para comprender qué ocurría.', 28153),
(133572, 'esMX', 'Estoy listo para tomar mi decisión.', 'Estoy lista para tomar mi decisión.', 28153),
(133571, 'esMX', '¡ESTA BESTIA ESTÁ FUERA DE CONTROL!', '', 28153),
(133570, 'esMX', '', '¿Ya sabes qué harás a continuación?', 28153),
(133569, 'esMX', '', 'Te lo agradeh\'co, $n.', 28153),
(133568, 'esMX', 'Si te pierdes antes de que regresemos, ¡NO volveré a buscarte!', '', 28153),
(133567, 'esMX', 'Regresemos con los demás. ¡Tengo tantas historias para contarles!', '', 28153),
(133566, 'esMX', 'Ten cuidado, estos trols no están bien de la cabeza. ¿Qué clase de pueblo se come a su propia gente?', '', 28153),
(133565, 'esMX', 'Mmm... ¡Sabe bien! Podría comer un poco más. Tal vez la próxima.', '', 28153),
(133564, 'esMX', 'Tengo tanta hambre... Un trozo de carne de raptor no estaría nada mal en este momento.', '', 28153),
(133563, 'esMX', '¡Prepárate, mortal! ¡El señor de las bestias ha regresado al fin!', '', 28153),
(133562, 'esMX', 'La guardia de espadas Kaja me envió.', 'La guardia de espadas Kaja me envió.', 28153),
(133561, 'esMX', '', 'Me alegra ver que Julwaba aún vive.', 28153),
(133560, 'esMX', '', 'Eh\'toy en deuda contigo, $n.', 28153),
(133559, 'esMX', '', 'Creo que lo mejor e\' que te pongas el traje y vayas al campamento. No creo que pueda contenerme de clavarle mi eh\'pada a cualquiera que haya puesto una mano sobre Rakera.', 28153),
(133558, 'esMX', 'Nuestros... tesoros...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133557, 'esMX', '¡Estos tesoros pertenecen a los escamavil!', '', 28153),
(133556, 'esMX', '¡Solo somos unos humildes productores de salchichas! ¿Por qué alguien querría hacernos daño?', '', 28153),
(133555, 'esMX', '', 'Vigilaré al humano. Si trata de escapar, mi eh\'pada se lo impedirá.', 28153),
(133554, 'esMX', 'Yo iré a la playa. Encuéntrame allí cuando tengas lo que te he pedido.', '', 28153),
(133553, 'esMX', 'Ahora que las ofrendas están listas, tenemos todo lo que necesitamos para invocar al loa.', '', 28153),
(133551, 'esMX', 'Los zandalari necesitarán de toda la ayuda posible para luchar contra e\'te mal. Por suerte, la Horda ha venido a prestar su apoyo.', '', 28153),
(133548, 'esMX', '', 'Me quedaré vigilando y me aseguraré de que no se vaya a ninguna parte.', 28153),
(133547, 'esMX', '', 'Se aproxima un tsunami de sangre. ¿Estamos condenados, $n?', 28153),
(133540, 'esMX', 'Ve, $n. Siembra mi cólera. Debo llegar a la guarida de mi loa ante\' de que sea demasiado tarde.', '', 28153),
(133539, 'esMX', '', 'Cómo puede ser... La carne... debía otorgarme... poder...', 28153),
(133538, 'esMX', '', 'No puede ser... Tú no me comerás. ¡No te quedará\' con mi poder!', 28153),
(133537, 'esMX', '', '¿Eh? Dijo que me fortalecería comiendo carne. ¡¿Por qué no te muere\'?!', 28153),
(133536, 'esMX', '', 'Tienes buen aroma. ¡Me volveré fuerte despué\' de comerte!', 28153),
(133534, 'esMX', '', '¡Tú no conseguirás eh\'te artefacto!', 28153),
(133532, 'esMX', 'Ahh... Sí... Qué tonto. ¡Olvidé las ofrendas! ¡No podemos invocar al loa con las manos vacías!', '', 28153),
(133527, 'esMX', 'Mmm... Algo anda mal. El ídolo está en su lugar en el altar, ¿por qué no aparece el loa?', '', 28153),
(133526, 'esMX', '', 'Este es el medallón de Rakera. Se otorga a todos los guardianeh\' bélicos en reconocimiento por los servicios prestado\' al rey. Al menos no lo entregó sin luchar.', 28153),
(133516, 'esMX', 'Zul y todos sus seguidore\' pronto aprenderán que no es gratuito desafiar a un loa.\n\nCon cada minuto que pasa, el precio es mayor.', '', 28153),
(133515, 'esMX', '', '¡Aquí eh\'tamos! ¿Qué has encontrado?', 28153),
(133514, 'esMX', '', 'Sigamos adelante. Debemos eh\'tar cerca.', 28153),
(133505, 'esMX', '', 'Lucharé a tu lado, mi rey. La Horda pagará por sus crímenes. Bloquearé la entrada para que nuestras fuerzas puedan reagruparse.', 28153),
(133503, 'esMX', 'Por lo menos eran dos, ¡y de las grandes! Ah, por cierto, gracias por sanarme.', '', 28153),
(133502, 'esMX', 'Casi te comen y... ¿Cuántas lanzas tenías en el estómago?', '', 28153),
(133501, 'esMX', '¡Aww! ¡Kajosh, deberías haber eh\'tado ahí para verlo! Magia oscura por todos lados, los trols haciendo cosas raras, ¡hasta tenía lanzas en mi estómago!', '', 28153),
(133500, 'esMX', '¡Idiota! ¡¿Sabes cuánto me preocupé por ti?!', '', 28153),
(133499, 'esMX', '¡Eso estuvo cerca! Me recuperaré en un abrir y cerrar de ojos, este viejo caparazón no irá a ningún lado.', '', 28153),
(133498, 'esMX', '¡Bueno, bueno, ya estoy despierto! ¿Era necesario que hicieras eso?', '', 28153),
(133497, 'esMX', '', '¡Muy bien, viste mi bengala! ¿Dónde eh\'tá Drekal?', 28153),
(133496, 'esMX', 'Aghh... Estoy bien, puedo caminar. Me reuniré con Kajosh... Apuesto a que debe estar... aghh... bastante enfadado.', '', 28153),
(133495, 'esMX', '', 'Ja... Jal\'aya... aún... tiene... tu... artefacto...', 28153),
(133494, 'esMX', '', '¡Creo que te comeremo\' a ti después de la tortuga!', 28153),
(133492, 'esMX', '', 'Por el mercado transitan viajeros de todos los rincones de Azeroth. ¡Hay muchas tabernas, pero esta es mi favorita!', 28153),
(133490, 'esMX', '', 'Las visiones que presencié... ¡Hay que detener a Zul y a Yazma, $n!', 28153),
(133489, 'esMX', 'Kajosh me envió. Yo me encargaré de los faucemaligna.', 'Kajosh me envió. Yo me encargaré de los faucemaligna.', 28153),
(133488, 'esMX', 'Aghh... Si no has venido a comerme, vete de aquí. ¡Sálvate! \n\nEsos faucemaligna llegarán... en cualquier momento... en busca de su \"comida\".', '', 28153),
(133487, 'esMX', '¡Agggh! Ahí vienen... ¡Cuidado!', '', 28153),
(133481, 'esMX', 'Eh\'to no es natural de Shadra. ¿Qué le ha pasado?', 'Eh\'to no es natural de Shadra. ¿Qué le ha pasado?', 28153),
(133480, 'esMX', 'Zul y Yazma son los responsable\' de esta traición. ¡Hay que detenerlos!', 'Zul y Yazma son los responsable\' de esta traición. ¡Hay que detenerlos!', 28153),
(133479, 'esMX', 'Esta no es una buena forma de morir. ¡Gracia\' por salvarme!', 'Esta no es una buena forma de morir. ¡Gracia\' por salvarme!', 28153),
(133478, 'esMX', '¡Hablaré con el loa sobre esto!', '¡Hablaré con el loa sobre esto!', 28153),
(133477, 'esMX', 'Hoy es un buen día para luchar.', '', 28153),
(133476, 'esMX', '¡La magia de sangre está prohibida! ¡Hay que detener a los traidore\'!', '', 28153),
(133475, 'esMX', 'Estoy... ¡completo! ¡Es hora de mi venganza!', '', 28153),
(133474, 'esMX', '¡Esta vez, Shadra y sus esbirro\' fueron demasiado lejos!', '', 28153),
(133473, 'esMX', '¡Bien! ¡Mi poder crece! Libera el poder del último tótem.', '', 28153),
(133472, 'esMX', 'Ve tras Shoak. Te esperaré aquí.', '', 28153),
(133471, 'esMX', '... dentro del templo, a nuestras espaldas. Eso sí que fue fácil.', '', 28153),
(133470, 'esMX', '¡Ajá! Está...', '', 28153),
(133469, 'esMX', '¡Zul pagará por eh\'to!', '', 28153),
(133468, 'esMX', '¡Ah, mi fuerza regresa! Rápido, libera la magia de otro tótem.', '', 28153),
(133467, 'esMX', '¡Que lo\' loa te bendigan, $gamigo:amiga;!', '', 28153),
(133466, 'esMX', 'Shoak puede estar en cualquier lugar de Nazmir...', '', 28153),
(133465, 'esMX', 'Listo, puedes lanzar el hechizo para encontrar a Shoak.', 'Listo, puedes lanzar el hechizo para encontrar a Shoak.', 28153),
(133463, 'esMX', '', 'Créeme, sé cómo te sientes. Pronto volaremos, ¿sí?', 28153),
(133461, 'esMX', '(Atrás)', '(Atrás)', 28153),
(133460, 'esMX', 'Supongo que puedo comer lo de siempre, pero nunca antes probé la carne de raptor. ¿Por qué dejar pasar la oportunidad de probar algo nuevo?', '', 28153),
(133459, 'esMX', 'Algunos de los tótems están destruidos. ¿Ahora tu hechizo surtirá efecto?', 'Algunos de los tótems están destruidos. ¿Ahora tu hechizo surtirá efecto?', 28153),
(133455, 'esMX', '', 'Ah, esa es mi niña. Debes estar inquieta, has estado todo el día encerrada.', 28153),
(133450, 'esMX', 'Morirás ahora.', 'Morirás ahora.', 28153),
(133449, 'esMX', 'Zul prometió poder para quien le llevara tu cabeza.', 'Zul prometió poder para quien le llevara tu cabeza.', 28153),
(133448, 'esMX', 'Le llevaré tu cabeza a Zul.', 'Le llevaré tu cabeza a Zul.', 28153),
(133447, 'esMX', 'Te desgarraré la mente.', 'Te desgarraré la mente.', 28153),
(133446, 'esMX', 'Te haremo\' sangrar.', 'Te haremo\' sangrar.', 28153),
(133445, 'esMX', '¿Dónde eh\'ta el rey?', '¿Dónde eh\'ta el rey?', 28153),
(133444, 'esMX', '¡Pondremo\' tu cabeza en una pica!', '¡Pondremo\' tu cabeza en una pica!', 28153),
(133443, 'esMX', '¡Mi vida por Zul!', '¡Mi vida por Zul!', 28153),
(133438, 'esMX', '<La superficie de la cúspide del altar es levemente cóncava y tiene surcos visibles en cada esquina.$b$bPareciera que en algún momento hubo un objeto grande y pesado sobre el altar.$b$bFuera lo que fuera, ya no está.>', '', 28153),
(133432, 'esMX', 'Examinar el altar.', 'Examinar el altar.', 28153),
(133430, 'esMX', '<La habitación parece vacía.$b$El altar que está frente a ti tiene grabados de antiguos glifos zandalari e imágenes del loa Eraka no Kimbul.$b$bParece que solía haber algo sobre el altar, ¿una estatua tal vez?>', '', 28153),
(133428, 'esMX', '', 'La contaduría cuenta con muchos guardias de día y de noche. Puedes guardar tus objetos valiosos aquí.', 28153),
(133412, 'esMX', '¡Los zanchuli lo vemo\' todo!', '¡Los zanchuli lo vemo\' todo!', 28153),
(133411, 'esMX', '¡No puede\' esconderte de mí!', '¡No puede\' esconderte de mí!', 28153),
(133410, 'esMX', '¡Zul conocerá tu\' secretos!', '¡Zul conocerá tu\' secretos!', 28153),
(133409, 'esMX', '¡Tu vida se acaba!', '¡Tu vida se acaba!', 28153),
(133407, 'esMX', '¡No te interpondrá\' en mi camino, $Uintruso:intrusa;!', '¡No te interpondrá\' en mi camino, $Uintruso:intrusa;!', 28153),
(133406, 'esMX', '¡Zandalar ahora pertenece a lo\' zanchuli!', '¡Zandalar ahora pertenece a lo\' zanchuli!', 28153),
(133405, 'esMX', '¡Por Zul! ¡Por lo\' zanchuli!', '¡Por Zul! ¡Por lo\' zanchuli!', 28153),
(133404, 'esMX', '¡Los Zanchuli nos apropiamo\' de lo que queremos!', '¡Los Zanchuli nos apropiamo\' de lo que queremos!', 28153),
(133403, 'esMX', '¡Tu poder será mío!', '¡Tu poder será mío!', 28153),
(133402, 'esMX', '¡Sus muerte\' me harán más fuerte!', '¡Sus muerte\' me harán más fuerte!', 28153),
(133401, 'esMX', '¡Máh\' sangre para Zul!', '¡Máh\' sangre para Zul!', 28153),
(133392, 'esMX', '', 'Este ferry recorre distintas estaciones de la costa interior del canal.', 28153),
(133389, 'esMX', '', 'Necesitarás un boleto de ferry del supervisor de puerto. No habrá problema.', 28153),
(133387, 'esMX', '', 'No te preocupes por la fuga de la prisión, aquí en el mercado eres $Uun viajero:una viajera; más. ¡Busquemos un hogar para ti!', 28153),
(133380, 'esMX', '', '¡Guardaré tu cabeza para despué\'!', 28153),
(133379, 'esMX', '', '¡Me alimentarás por un buen tiempo!', 28153),
(133374, 'esMX', '', '¡Masticaré tus hueso\'!', 28153),
(133372, 'esMX', '', '¡Prepárense! ¡Vamoh\' a comer!', 28153),
(133371, 'esMX', '', '¡Ahh! ¡Má\' comida para mí!', 28153),
(133370, 'esMX', '', '¡Tus pierna\' serán un buen plato!', 28153),
(133369, 'esMX', '', '¡Parece que llegó la comida!', 28153),
(133368, 'esMX', '', '¡Pero qué $Uapetitoso:apetitosa; te ves!', 28153),
(133359, 'esMX', 'No es la primera vez que Shoak se pierde. Más le vale que se trate de algo serio, con todo el esfuerzo que estamos haciendo.', '', 28153),
(133357, 'esMX', '¡Vamos! ¡Esta azerita no se extraerá sola!', '¡Vamos! ¡Esta azerita no se extraerá sola!', 28153),
(133356, 'esMX', 'Estoy listo para acompañarte al templo.', 'Estoy lista para acompañarte al templo.', 28153),
(133355, 'esMX', '¡Debí haber sabido que no se podía confiar en esos Tortaka traidores! No puedo creer que me mataron y me atraparon en esa vasija durante cien años... ¿o fueron doscientos? ¡Ya ni siquiera me acuerdo!', '', 28153),
(133354, 'esMX', '<Un espantoso rugido de agonía resuena sobre Zeb\'ahari.>', '<Un espantoso rugido de agonía resuena sobre Zeb\'ahari.>', 28153),
(133351, 'esMX', 'Buscaré al loa. Cuando hayas terminado aquí, nos encontraremos en el interior del templo.', '', 28153),
(133350, 'esMX', 'Libre al fin... ¡Gracias por sacarme de ese jarrón maldito! ¡Había muy poco espacio, incluso para un fantasma!', '', 28153),
(133349, 'esMX', '', 'Estos muros no resistirán mucho más. Tenemos que salir de aquí.', 28153),
(133348, 'esMX', '', '¡Excelente, colega! Regresa a hablarme cuando estés $Ulisto:lista;. Tenemo\' que volver a la guerra.', 28153),
(133346, 'esMX', '', 'Dio\' de la sangre... ¡llévame! Que este... no sea... el fin...', 28153),
(133345, 'esMX', '', 'El dio\' de la sangre logrará su objetivo tarde o temprano. ¡Nadie puede detenerno\'!', 28153),
(133344, 'esMX', '', 'La princesa quiere escuchar nuestros informe\' de inmediato. No la hagamos esperar.', 28153),
(133343, 'esMX', 'Camina, se te pasará.', '', 28153),
(133342, 'esMX', 'Nada de morir todavía. Nos queda mucho por hacer.', '', 28153),
(133341, 'esMX', 'Arriba. Todavía no has cumplido con tu deber.', '', 28153),
(133340, 'esMX', '¡Levántate! Te necesitamos.', '', 28153),
(133339, 'esMX', '¡Levántate!', '', 28153),
(133338, 'esMX', '¡Levántate! Tu rey te necesita.', '', 28153),
(133337, 'esMX', 'Estoy listo para pelear contra los trols de sangre.', 'Estoy lista para pelear contra los trols de sangre.', 28153),
(133336, 'esMX', 'Los trols de sangre están reuniendo fuerzas para otro ataque contra mí y mis hijos.$b$b¡Esta vez, seré yo quien siembre la muerte!$b$b¿Estás $Glisto:lista;?', '', 28153),
(133325, 'esMX', '¡Los atacantes de la Horda se dirigen al Cuartel!', '¡Los atacantes de la Horda se dirigen al Cuartel!', 28153),
(133305, 'esMX', '', 'Te sentirás como en casa en un abrir y cerrar de ojos. Ahora, ¡vamos a ver a Cyrus!', 28153),
(133304, 'esMX', '', 'Preciosa, ¿verdad? Cyrus me la regaló cuando era apenas una cría.', 28153),
(133303, 'esMX', 'Me uniré a la cruzada contra los trols de sangre invasores, pero antes debo recuperar mi fuerza. ¿Me ayudarás?', '', 28153),
(133302, 'esMX', 'Zentimo ha sido un buen servidor. Su espíritu vivirá entre mis hijos.', '', 28153),
(133300, 'esMX', 'Randall Redmond escupe en la arena.', '', 28153),
(133298, 'esMX', '¡Ayuda! ¡Sáquenme estas cosas de encima!', '', 28153),
(133297, 'esMX', '', 'Sus herida\' eran demasiado severas... Lo siento.', 28153),
(133295, 'esMX', '¿Vunanju? *Gruñido* Debí haberlo sabido...', '', 28153),
(133294, 'esMX', '¿Quién osa invocarme en este templo decrépito?', '', 28153),
(133274, 'esMX', 'Yo me adelantaré para preparar el ritual. Reúnete conmigo allí cuando eh\'tés $Glisto:lista;.', '', 28153),
(133265, 'esMX', '¡Prepárate para contemplar la gloria de Eraka no Kimbul, loa de los tigres, señor de las bestias, rey de los felinos y perdición de las presas!', '', 28153),
(133264, 'esMX', '¡Has encontrado el ídolo! Ahora que está en su lugar, podemos invocar al loa...', '', 28153),
(133263, 'esMX', '', 'Lo llevaré de vuelta a su loa y mataré a cualquiera que se interponga.', 28153),
(133261, 'esMX', '¡Han destruido el Cuartel! ¡Reconstrúyelo!', '¡Han destruido el Cuartel! ¡Reconstrúyelo!', 28153),
(133260, 'esMX', '¡Han destruido la Herrería! ¡Reconstrúyela!', '¡Han destruido la Herrería! ¡Reconstrúyela!', 28153),
(133259, 'esMX', '¡Han destruido los Establos! ¡Reconstrúyelos!', '¡Han destruido los Establos! ¡Reconstrúyelos!', 28153),
(133258, 'esMX', '¡Han destruido el Taller! ¡Reconstrúyelo!', '¡Han destruido el Taller! ¡Reconstrúyelo!', 28153),
(133254, 'esMX', '¡Ni siquiera tengo un arma!', '', 28153),
(133253, 'esMX', '¡No quiero morir!', '', 28153),
(133252, 'esMX', '¡No puedo trabajar en estas condiciones!', '', 28153),
(133251, 'esMX', '¡Está funcionando! ¡Prepárate!', '', 28153),
(133250, 'esMX', 'Probaremos un hechizo de fosilización invertida. ¡Atrás!', '', 28153),
(133249, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(133248, 'esMX', 'Si esto funciona, no esperes un buen trato de parte de Xibala.\n\nEspero que estés $gpreparado:preparada; para hacer lo que sea necesario para subyugarlo.', '', 28153),
(133247, 'esMX', '', '¡Por aquí! ¡Tenemo\' un herido!', 28153),
(133240, 'esMX', '', 'Ofrezco el resguardo que esta tierra hostil me permite.', 28153),
(133239, 'esMX', 'Este era mi lugar antes de que los zandalari decidieran construir una casa a mi alrededor.', '', 28153),
(133224, 'esMX', 'El ídolo debe regresar al Templo de Kimbul. ¡En tus manos está la llave para el regreso del loa!', '', 28153),
(133223, 'esMX', 'Mi espíritu se ha debilitado y no tengo mucho tiempo, $Gviajero:viajera;. Escucha con atención mis palabras...', '', 28153),
(133214, 'esMX', 'Ahora vámonoh\' de aquí. Hay un santuario más adelante llamado Zo\'bal. Encontrémonos allí.', '', 28153),
(133213, 'esMX', '¡Hemos derrotado al Comandante de la Horda! ¡Has vencido!', '¡Hemos derrotado al Comandante de la Horda! ¡Has vencido!', 28153),
(133212, 'esMX', '¡Brillante! Parece que los miserables orcos olvidaron algunos explosivos muy bonitos. Me pregunto qué sucedería si las arrojáramos cerca de sus estructuras apestosas que están por allí.', '', 28153),
(133207, 'esMX', 'Esta área ha sido abandonada para que lo\' espíritus del pasado se apoderaran de ella, y con razón...\n\nLa Horda es más que bienvenida si quiere develar sus misterio\'... Si se atreven...', '', 28153),
(133204, 'esMX', 'Incluso en la muerte, los espíritu\' de mi gente siguen siendo leale\' al gran loa, Eraka no Kimbul. Los lazo\' de nuestra fe son eterno\' y más fuertes que el puño de la muerte misma.', '', 28153),
(133201, 'esMX', 'Necesitamos esa mina, pero los malditos orcos están en nuestro camino. Vayamos allí para deshacernos de ellos y que nuestros obreros puedan construirnos un cuartel.', '', 28153),
(133200, 'esMX', 'Y hasta aquí llegó esa bestia asquerosa. Ahora, deshazte del estandarte y pongámonos a trabajar.', '', 28153),
(133199, 'esMX', 'Bueno, chicos, tendremos que establecer una base aquí si planeamos acabar con ese comandante orco y destruir su base de una vez por todas.', '', 28153),
(133198, 'esMX', '', '¡Esto no cambia nada! Pronto... Todo\'... morirán...', 28153),
(133197, 'esMX', 'Eres $Gel primer:la primera; mortal en pisar mi templo en muchos años. Es agradable volver a tener seguidores del reino de los vivos.', '', 28153),
(133158, 'esMX', '', 'Lo logramos. Solo imagina lo que sucederá cuando ese ensamblaje enorme derribe los muro\' de Zuldazar y los deje entrar a todo\'. Sería ideal contar con más ayuda de los loa.', 28153),
(133157, 'esMX', '', '¡Míralos! Todo\' esos van camino a Zuldazar... ¡Cuidado! ¡Agáchate!', 28153),
(133156, 'esMX', '', 'La isla está al sur de este lugar. Te estaré esperando allí.', 28153),
(133155, 'esMX', '', 'Por aquí. El bote está listo, solo avísame cuando quiera\' partir. Espero que no nos crucemo\' con ninguna monstruosidad en el río.', 28153),
(133154, 'esMX', '¡AQUÍ VAMOS!', '', 28153),
(133153, 'esMX', '¡PERO NO HAGAS QUE EXPLOTE!', '', 28153),
(133152, 'esMX', '¡SIGUE GOLPEANDO!', '', 28153),
(133151, 'esMX', '¿En qué puedo ayudarte, muchach$Go:a;?', '', 28153),
(133150, 'esMX', 'Toma lo que encuentres en esa cosa. ¡Es mi forma de darte las gracias!', '', 28153),
(133149, 'esMX', '¡Aaaaa....aahhhh...!', '', 28153),
(133143, 'esMX', '¡Tu presencia en este lugar es profana! ¡Ten cuidado de Xibala!', '', 28153),
(133141, 'esMX', 'Ahora es posible reclutar Granaderos enanos en el Taller.', 'Ahora es posible reclutar Granaderos enanos en el Taller.', 28153),
(133140, 'esMX', 'Ahora es posible reclutar Fusileros en la Herrería.', 'Ahora es posible reclutar Fusileros en la Herrería.', 28153),
(133139, 'esMX', 'Ahora es posible reclutar Caballeros en los Establos.', 'Ahora es posible reclutar Caballeros en los Establos.', 28153),
(133138, 'esMX', 'Ahora es posible reclutar Lacayos en el Cuartel.', 'Ahora es posible reclutar Lacayos en el Cuartel.', 28153),
(133136, 'esMX', '', 'Te eh\'tás acercando. La primera presencia que siento eh\'tá en algún lugar junto al agua.', 28153),
(133133, 'esMX', '', 'Mmm... Esa ofrenda parece reciente. Parece que Bwonsamdi tiene un adorador en el pantano.', 28153),
(133131, 'esMX', 'Son demasiados trols de sangre. Ya no seguiré luchando.', '', 28153),
(133126, 'esMX', 'La Horda ha perdido una edificación. La Herrería ya puede construirse.', 'La Horda ha perdido una edificación. La Herrería ya puede construirse.', 28153),
(133125, 'esMX', 'La Horda ha perdido una edificación. El Taller ya puede construirse.', 'La Horda ha perdido una edificación. El Taller ya puede construirse.', 28153),
(133124, 'esMX', 'La Horda ha perdido una edificación. Los Establos ya pueden construirse.', 'La Horda ha perdido una edificación. Los Establos ya pueden construirse.', 28153),
(133123, 'esMX', '', 'Lih\'to... Sigue al fantasma y veamo\' a dónde se ha dirigido el adorador de Bwonsamdi.', 28153),
(133122, 'esMX', '', 'Una trol de sangre. Parece que la sacrificaron. Ah, el asesino olvidó una daga. Con solo un hechizo...', 28153),
(133114, 'esMX', '¡SÁQUENME DE AQUÍ!', '', 28153),
(133113, 'esMX', '¡Han arrojado la bomba!', '¡Han arrojado la bomba!', 28153),
(133112, 'esMX', '¡Han recogido la bomba!', '¡Han recogido la bomba!', 28153),
(133111, 'esMX', '¡La bomba está por explotar! ¡Aléjate!', '¡La bomba está por explotar! ¡Aléjate!', 28153),
(133108, 'esMX', 'Lacayo [25 de oro del frente de guerra] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 'Lacayo [25 de oro del frente de guerra] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'esMX', 'Empecemos.', 'Empecemos.', 28153),
(133103, 'esMX', 'REUSEME', 'REUSEME', 28153),
(133102, 'esMX', '¡Nuestro trabajo aquí avanza a paso de tortuga por culpa de la molesta Alianza!', '¡Nuestro trabajo aquí avanza a paso de tortuga por culpa de la molesta Alianza!', 28153),
(133101, 'esMX', 'Podría trabajar mucho más si no tuviera que darme vuelta a cada segundo para comprobar que no haya saboteadores de la Alianza...', 'Podría trabajar mucho más si no tuviera que darme vuelta a cada segundo para comprobar que no haya saboteadores de la Alianza...', 28153),
(133100, 'esMX', 'La Alianza no tiene derecho a reclamar esta tierra, ¡Zuldazar es territorio de la Horda!', 'La Alianza no tiene derecho a reclamar esta tierra, ¡Zuldazar es territorio de la Horda!', 28153),
(133099, 'esMX', 'Hasta que esos desgraciados enanos desaparezcan de nuestras tierras, ¡no podremos avanzar mucho!', '', 28153),
(133085, 'esMX', '', 'La Alianza... prevalecerá...', 28153),
(133084, 'esMX', '', 'Este es un sitio de excavación oficial de la Liga de Expedicionarios. ¡Estás pasando todos los límites!', 28153),
(133069, 'esMX', '¡Por la Alianza!', '¡Por la Alianza!', 28153),
(133066, 'esMX', '¡Vete de aquí, $Gintruso:intrusa;!', '¡Vete de aquí, $Gintruso:intrusa;!', 28153),
(133065, 'esMX', '¡Estos artefactos serán nuestros!', '¡Estos artefactos serán nuestros!', 28153),
(133064, 'esMX', '¡Muerte al Relicario!', '¡Muerte al Relicario!', 28153),
(133055, 'esMX', '', '¡Hola! ¿Alguna vez encendiste un cohete que tenías pegado a la espalda con los ojos vendados? ¡Yo sí!', 28153),
(133054, 'esMX', 'Tenemo\' que erradicar a la Alianza. ¡Zuldazar pertenece a la Horda!', '', 28153),
(133053, 'esMX', 'Eso fue increíble. ¡Qué hallazgo!', '', 28153),
(133048, 'esMX', '', 'Paso mucho tiempo aquí molestando a los viajeros para que me cuenten sus historias. ¡Sobre todo a los de los Reinos del Este!', 28153),
(133047, 'esMX', '', 'Hemos llegado: Puerto Boralus. Sin contar la Fortaleza Valiente, es la parte de la ciudad con más guardias. Y el único lugar que visita la mayoría de los viajeros.', 28153),
(133045, 'esMX', '', 'Tienes suerte de que te pague. ¡Ahora, a remar!', 28153),
(133044, 'esMX', '¿$UEmisario:Emisaria; de la Alianza?! Cyrus nunca mencionó eso... ¡Le habría cobrado el doble!', '', 28153),
(133043, 'esMX', '', '¡Has llegado con Jaina Valiente! ¡Eres $Uel emisario:la emisaria; de la Alianza!', 28153),
(133042, 'esMX', '', 'Espera... Te conozco...', 28153),
(133041, 'esMX', 'AH, y también rescaté al objetivo, por supuesto. Mi cómplice, Taelia. Taelia, mi cómplice.', '', 28153),
(133040, 'esMX', '', '¿Qué pasa allí? ¡Parece que comenzaron una revuelta!', 28153),
(133039, 'esMX', 'No tengo idea de qué hablas... Pero creo que por fin encontramos los trapos sucios de los Aspafresno.', '', 28153),
(133038, 'esMX', '¡Allí está! Sube.', '', 28153),
(133037, 'esMX', 'Bajemos a los niveles inferiores y busquemos una salida.', '', 28153),
(133036, 'esMX', 'Ah, así está mejor. ¡Me sentía desnudo sin esto! Andando.', '', 28153),
(133013, 'esMX', '', 'Si necesitan una alfombra o un abrigo, ¡tenemos la piel indicada!', 28153),
(133012, 'esMX', '', '¡Pieles que dan calor, pieles para toda función, y pieles que brindan la comodidad mejor!', 28153),
(133011, 'esMX', '', '¡Pieles de calidad de todo Kul Tiras!', 28153),
(133009, 'esMX', '', '¡Los inventos más confiables de todo Tiragarde! ¡Es un hecho comprobado!', 28153),
(133008, 'esMX', '', '¡No confíen en los inventos gnomos de ningún otro lugar! ¡Mis competidores son un fraude!', 28153),
(133007, 'esMX', '', '¡No encontrarán artilugios y accesorios mejor fabricados que estos!', 28153),
(133001, 'esMX', '¡Vaya! Está... ¿creciendo? ¡Ay!', '¡Vaya! Está... ¿creciendo? ¡Ay!', 28153),
(132999, 'esMX', 'Alzándose', 'Alzándose', 28153),
(132994, 'esMX', 'Magos, regresemos al campamento. ¡Tenemos mucho que estudiar!', '', 28153),
(132993, 'esMX', '¡No! Las llaves están arruinadas. ¡Eso sí que fue una explosión!', '', 28153),
(132992, 'esMX', 'Toma tu equipo y visitemos al celador del bloque. Necesitaremos sus llaves.', '', 28153),
(132991, 'esMX', 'Supongo que no escaparemos por ese camino. Probemos por el otro lado.', '', 28153),
(132990, 'esMX', 'Cuartel disponible', 'Cuartel disponible', 28153),
(132989, 'esMX', '¡Motín, muchachos! ¡Provoquemos un caos!', '', 28153),
(132988, 'esMX', '[Las puertas de las celdas se abren. Los prisioneros salen en masa y se apoderan de los pasillos.]', '[Las puertas de las celdas se abren. Los prisioneros salen en masa y se apoderan de los pasillos.]', 28153),
(132987, 'esMX', '¡Los atacantes de la Horda se dirigen al Taller!', '¡Los atacantes de la Horda se dirigen al Taller!', 28153),
(132986, 'esMX', 'Engendrando soldados', 'Engendrando soldados', 28153),
(132985, 'esMX', 'El cuartel ha sido capturado y esta reconstruyéndose.', 'El cuartel ha sido capturado y esta reconstruyéndose.', 28153),
(132981, 'esMX', '¡Los atacantes de la Horda se dirigen a los Establos!', '¡Los atacantes de la Horda se dirigen a los Establos!', 28153),
(132980, 'esMX', '¡Los atacantes de la Horda se dirigen a la Herrería!', '¡Los atacantes de la Horda se dirigen a la Herrería!', 28153),
(132969, 'esMX', '', 'Mamá, ¡todos mis amigos están jugando sin mí! ¿Puedo ir porfaaa?', 28153),
(132968, 'esMX', '', '¡Estoy aburrida! ¿Puedo ir a jugar?', 28153),
(132967, 'esMX', '', '¿Ya terminamos con las tareas por hoy?', 28153),
(132966, 'esMX', 'Por lo menos, esto debería hacer que se ponga de pie.', '', 28153),
(132957, 'esMX', '', '¿Esta cosa vieja?$B$B<Lanza una carcajada sincera.>$B$BMira a tu alrededor. ¿Dónde crees que lo conseguí?', 28153),
(132955, 'esMX', 'Qué escudo más interesante. ¿Dónde lo conseguiste?', 'Qué escudo más interesante. ¿Dónde lo conseguiste?', 28153),
(132954, 'esMX', '', 'Puede que sea una niña, pero martilleo mejor que cualquier escoria de la Horda de aquí.', 28153),
(132945, 'esMX', '¿Qué haces aquí?', '¿Qué haces aquí?', 28153),
(132944, 'esMX', 'Tengo justo lo que necesitamos para derribarlos. ¡Sin piedad!', '', 28153),
(132943, 'esMX', '¡Se acerca un gigante! ¡Ey, es el que destrozó nuestra nave! ¡Hora de ajustar cuentas!', '', 28153),
(132941, 'esMX', 'Escucha, muchach$Go:a;... Me, eh... me olvidé de qué iba a decirte, pero mejor no te metas en lo que no te incumbe en este lugar.$B$BNo me gustaría ver tu sangre en mi equipamiento.', '', 28153),
(132940, 'esMX', 'Como soy alto, mis emociones tardan más en alcanzar su máximo potencial.$B$BTen paciencia.', '', 28153),
(132939, 'esMX', 'Tenemos que comprobar la precisión del arma antes de proseguir. ¿Por qué no aprovechamos y nos deshacemos de esos nagas al mismo tiempo?', '', 28153),
(132938, 'esMX', '¡Uoo! ¡Cuidado! ¡Nos disparan con cañones! ¡Derríbalos con ráfagas de disparos!', '', 28153),
(132935, 'esMX', '¡Abajo! ¡Cuidado!', '', 28153),
(132932, 'esMX', '', 'Así es... Vayamo\' al oeste para evitar conflictos innecesario\'.', 28153),
(132931, 'esMX', 'Veo que su presencia ha aumentado.', '', 28153),
(132928, 'esMX', '¿Vienes a buscar refugio o a comerciar?', '¿Vienes a buscar refugio o a comerciar?', 28153),
(132926, 'esMX', 'Estamos listos para partir. Sube.', '', 28153),
(132924, 'esMX', '¡Rápido! ¡La palanca!', '', 28153),
(132923, 'esMX', 'Vamos, nuestro transporte nos espera en la playa.', '', 28153),
(132922, 'esMX', '', '¡Fuera de mi camino! ¡Ese oro tiene mi nombre!', 28153),
(132920, 'esMX', '¡Cincuenta mil piezas de oro para el primero que llegue al punto de despliegue!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132918, 'esMX', 'Pero acabo de construir un montón de minas para proteger este lugar...', '', 28153),
(132917, 'esMX', 'He visto suficiente. Quiero largarme de aquí en este instante.', '', 28153),
(132916, 'esMX', 'Ugh... huele a hamaca de filibustero.', '', 28153),
(132915, 'esMX', '¡Muy bien, equipo! ¡A moverse!', '', 28153),
(132912, 'esMX', '¡No hay emoción sin un poco de riesgo! Vaya, necesitas apostar un poco más.', '', 28153),
(132911, 'esMX', '', 'Vamos, con 80 por ciento estamos bien. ¿Para qué pedir más y arriesgarse a perder la oportunidad?', 28153),
(132910, 'esMX', '¿Solo el 80 por ciento? ¡Podrías haber pedido MUCHO más! ¿Dónde quedó tu avaricia?', '', 28153),
(132909, 'esMX', 'Bienvenida a la Posada Colmilloaúreo, hermana. Siempre estarás como en casa aquí.\n\nRelájate y descansa, ¡luego ven a beber unos tragos!', '', 28153),
(132908, 'esMX', 'Bienvenido a la Posada Colmilloaúreo, hermano. Siempre estarás como en casa aquí.\n\nRelájate y descansa, ¡luego ven a beber unos tragos!', '', 28153),
(132907, 'esMX', '¿Qué haces? ¡Ese equipo es mío!', '¿Qué haces? ¡Ese equipo es mío!', 28153),
(132906, 'esMX', '¡Ayuda! ¡Hay $Gun saboteador:una saboteadora; aquí!', '¡Ayuda! ¡Hay $Gun saboteador:una saboteadora; aquí!', 28153),
(132905, 'esMX', '¡Ese equipo es muy delicado!', '¡Ese equipo es muy delicado!', 28153),
(132904, 'esMX', '¡Eh! ¡Aléjate de mi equipo!', '¡Eh! ¡Aléjate de mi equipo!', 28153),
(132897, 'esMX', '¡Sáquenme de eh\'ta jaula! ¡Soy inocente, lo juro!', '¡Sáquenme de eh\'ta jaula! ¡Soy inocente, lo juro!', 28153),
(132893, 'esMX', 'Estoy de acuerdo, Grenja. $p es una buena opción si Zulsan no regresa.', '', 28153),
(132891, 'esMX', '¿A quién se le ocurrió navegar por esta gruta del demonio?', '¿Quién tuvo la idea de navegar por esta gruta del demonio?', 28153),
(132890, 'esMX', '¡Al fin se terminaron los cantos!', '¡Al fin se terminaron los cantos!', 28153),
(132889, 'esMX', '¿Eso es... cerveza?', '¿Eso es... cerveza?', 28153),
(132880, 'esMX', 'Nunca me canso de esa parte, je.', '', 28153),
(132879, 'esMX', 'Herví la sangre y los aguijone\' que recolectaste y los mezclé en nuestro cáliz colmilloáureo ceremonial... Es una piña. No te la coma\'. Solo tenemos una.', '', 28153),
(132877, 'esMX', '¡Gracias por salvarme el pellejo!', '', 28153),
(132876, 'esMX', '¡Gracias! ¡Te veré en el encuentro!', '', 28153),
(132849, 'esMX', 'Ahora me doy cuenta de que estuve a punto de caer en una trampa maléfica... ¡gracias!', 'Ahora me doy cuenta de que estuve a punto de caer en una trampa maléfica... ¡gracias!', 28153),
(132848, 'esMX', 'No sé qué se apoderó de mí...', 'No sé qué se apoderó de mí...', 28153),
(132847, 'esMX', 'Salva a los demás... Yo iré a Kimbul de inmediato.', 'Salva a los demás... Yo iré a Kimbul de inmediato.', 28153),
(132846, 'esMX', 'Casi me aniquila... ¡Gracias, $gforastero:forastera;!', 'Casi me aniquila... ¡Gracias, $gforastero:forastera;!', 28153),
(132845, 'esMX', 'El engaño casi me cuesta la vida...', 'El engaño casi me cuesta la vida...', 28153),
(132844, 'esMX', 'Ahora veo que solo era un encantamiento. Iré a Kimbul...', 'Ahora veo que solo era un encantamiento. Iré a Kimbul...', 28153),
(132843, 'esMX', 'Me sedujo la luz devoradora. Gracias por salvarme...', 'Me sedujo la luz devoradora. Gracias por salvarme...', 28153),
(132841, 'esMX', '', 'No sobreviviré mucho tiempo sin agua ni alimentos. Despué\' de andar en círculos casi todo el día, decidí que mi única opción era seguir el consejo de un loco incoherente e ir hacia el sur, con la eh\'peranza de conseguir refugio.', 28153),
(132840, 'esMX', '', 'A medianoche, unos asesinos enviado\' por Jakra\'zet atacaron nueh\'tro campamento. Desarmados y atontado\' por el sueño, fuimos incapaces de defendernos. Expulsé a los traidore\', pero ya era tarde. Los sobreviviente\' se dispersaron, y ahora cada uno debe deambular por eh\'te territorio inclemente en soledad.', 28153),
(132839, 'esMX', '', 'El sol se ha ocultado tras las duna\', y eso nos ha dado un descanso del calor que ha enloquecido a tanto\'. En el delirio de la insolación, uno de nosotro\' comenzó a hablar sobre un templo que recibe exiliado\'. Dudo que sobreviva a esta noche.', 28153),
(132838, 'esMX', '', 'Escribo estas línea\' mientras espero en una jaula junto a una decena de exiliado\', camino a las arena\' donde viviremo\' el resto de nuestro\' días, por poco\' que sean. El intenso calor del aire me indica que estamo\' cerca.', 28153),
(132830, 'esMX', '', 'Tú... Demasiado tarde... Lo\' loa... Todos serán alimento... para el dios de la sangre.', 28153),
(132827, 'esMX', '¡Los nagas pagarán por esto!', '', 28153),
(132826, 'esMX', '¡No sé cómo agradecértelo!', '', 28153),
(132825, 'esMX', '¡Te debo una!', '', 28153),
(132824, 'esMX', '¡Libertad!', '', 28153),
(132823, 'esMX', 'Te debo la vida. Estos hombres serpiente pagarán por lo que le hicieron a nuestro hogar...', 'Te debo la vida. Estos hombres serpiente pagarán por lo que le hicieron a nuestro hogar...', 28153),
(132821, 'esMX', '<Toma la carta.>', '<Toma la carta.>', 28153),
(132752, 'esMX', '¡Nisha, gracias a las arenas que estás viva!', '', 28153),
(132737, 'esMX', '', 'Realmente es el hombre más amable que he conocido.', 28153),
(132736, 'esMX', '%se mueve hacia ti como para detenerte, pero se arrepiente y simplemente te observa desde la distancia una vez más.', '', 28153),
(132735, 'esMX', 'Je, la primera vez que bebes sangre de escórpido ritual siempre e\' difícil. Escupe, la próxima vez será más fácil.', '', 28153),
(132734, 'esMX', 'Zuldazar nos traicionó. Nos exilió como si fuéramos forasteros. Pero nunca nos traicionamos entre nosotros. Los Colmilloáureo somos leales.', '', 28153),
(132733, 'esMX', 'Ah, la sangre e\' dulce... Bebe y verás lo mismo que yo, $p.', '', 28153),
(132714, 'esMX', '¡Armas profesionales para cazadores expertos y novatos!', '', 28153),
(132713, 'esMX', '¿Vas a salir de cacería? ¡Este es el mejor lugar para comprar suministros!', '', 28153),
(132712, 'esMX', '¡Armas, municiones y explosivos para cazadores de todos los niveles!', '', 28153),
(132711, 'esMX', 'El cuernoatroz joven bosteza.', '', 28153),
(132710, 'esMX', '¿Eso? Ah, solo algo que les doy de comer a mis guardaespaldas. Tengo mucho más, ¡así que si quieres puedes hacerme una oferta!', '', 28153),
(132696, 'esMX', '¿Ya e\' seguro salir?', '', 28153),
(132692, 'esMX', '¡Ja! Sí, ya sé que $p no puede verte. Seguro cree que eh\'toy loco. ¡Ja!', '', 28153),
(132691, 'esMX', 'No te sientas mal. $p ni siquiera puede verte. Seguro cree que eh\'toy loco. ¡Ja!', '', 28153),
(132690, 'esMX', '¡$p te rescató, Zulsan! ¡Eh\'toy tan feliz!', '', 28153),
(132688, 'esMX', '¡Hola, $n! El príncipe mercante dice que tenemos que empezar a generar ganancias. Si te enteras de algún negocio interesante, avísame, ¿de acuerdo?', '', 28153),
(132684, 'esMX', '', '¡La novia está aquí, la novia está aquí!', 28153),
(132683, 'esMX', '¡Por aquí!', '¡Por aquí!', 28153),
(132682, 'esMX', '¡Cargaaaaaaaaaa! ¡Tú puede\'!', '¡Cargaaaaaaaaaa! ¡Tú puede\'!', 28153),
(132681, 'esMX', '<Decir por lo bajo que su parche te parece estúpido.>', '<Decir por lo bajo que su parche te parece estúpido.>', 28153),
(132680, 'esMX', '¿Me das tus cosas?', '¿Me das tus cosas?', 28153),
(132679, 'esMX', 'Tu parche es muy intimidante.', 'Tu parche es muy intimidante.', 28153),
(132678, 'esMX', '<El parche de Man\'zul se crispa con magia.>', '', 28153),
(132677, 'esMX', '<Desafiar a Grenja a un concurso de miradas.>', '<Desafiar a Grenja a un concurso de miradas.>', 28153),
(132676, 'esMX', '¡Creo que serías un buen tope de puerta!', '¡Creo que serías un buen tope de puerta!', 28153),
(132675, 'esMX', '¡Un gusto!', '¡Un gusto!', 28153),
(132674, 'esMX', '<Grenja se ve extrañamente alegre para una calavera.>', '', 28153),
(132673, 'esMX', '¡Hagan silencio! Tenemos un invitado.', '', 28153),
(132672, 'esMX', '<Presentarte amablemente.>', '<Presentarte amablemente.>', 28153),
(132671, 'esMX', '<Hacer un comentario por lo bajo que señale la extravagancia de la situación.>', '<Hacer un comentario por lo bajo que señale la extravagancia de la situación.>', 28153),
(132670, 'esMX', 'Me gusta tu sombrero', 'Me gusta tu sombrero', 28153),
(132669, 'esMX', 'Emm... ¿Hola?', 'Emm... ¿Hola?', 28153),
(132668, 'esMX', '¡Vaya! ¿Qué fue eso? Me siento muy bien.', '', 28153),
(132667, 'esMX', '', '<Volni parece inmovilizada en el gesto de un grito eterno.>', 28153),
(132663, 'esMX', '', '¡Les encantará el color y el sabor que nuestras especias le aportan a cualquier plato!', 28153),
(132662, 'esMX', '', '¡Especias de calidad de todo Azeroth!', 28153),
(132661, 'esMX', '', '¡No volverán a comer nunca una cena insípida! ¡Vengan a ver nuestras especias!', 28153),
(132657, 'esMX', '¡Aaaah! ¡Intenta dih\'traerlo con un juguete!', '¡Aaaah! ¡Intenta dih\'traerlo con un juguete!', 28153),
(132656, 'esMX', 'El mejor pescado del mercado. ¡Si huele mal, no es nuestro!', 'El mejor pescado del mercado. ¡Si huele mal, no es nuestro!', 28153),
(132655, 'esMX', '¡No hay nada mejor que el pescado fresco para una buena comida!', '¡No hay nada mejor que el pescado fresco para una buena comida!', 28153),
(132654, 'esMX', '¡Pescado fresco de los botes colmillarr!', '¡Pescado fresco de los botes colmillarr!', 28153),
(132653, 'esMX', '¡Señor! Parece que las fuerzas de la Horda acuden a los campamentos en masa. Deben estar preparándose para moverse, señor.', '', 28153),
(132651, 'esMX', '¡No les pierdas el rastro! Si ves algún movimiento sospechoso, ya sabes qué hacer.', '', 28153),
(132650, 'esMX', '¡Acacia! ¿Alguna novedad?', '', 28153),
(132648, 'esMX', 'Rescate', 'Rescate', 28153),
(132646, 'esMX', '¡Fuego!', '¡Fuego!', 28153),
(132645, 'esMX', 'Tú debe\' ser parte de esa Horda de la que tanto he oído. ¿Y has conseguido una prole de cuernoatroz? La señora de las bestia\' deseará ver esto. Adelante.', 'Tú debes ser parte de esa Horda de la que tanto he oído. ¿Y has conseguido una prole de cuernoatroz? La Señora de las bestias deseará ver esto. Adelante.', 28153),
(132636, 'esMX', '', 'Qué interesante...', 28153),
(132635, 'esMX', '', 'Veamos qué tenemos aquí.', 28153),
(132634, 'esMX', '', 'Ten cuidado.', 28153),
(132629, 'esMX', '¡Usa Sprint para correr más rápido!', '¡Usa Sprint para correr más rápido!', 28153),
(132628, 'esMX', '', 'Mataremo\' a los cazadore\' y recuperaremo\' los tótem\' perdido\'.', 28153),
(132626, 'esMX', '', 'Cuando los Zandalari vean que luchas con ellos, volverás a tener seguidore\'.', 28153),
(132624, 'esMX', '', '¡Ere\' un loa poderoso! ¡Con ese poder de nuestro lado, aplastaremo\' al enemigo!', 28153),
(132622, 'esMX', '', '¡Gran Krah\'gwa! ¡Necesitamo\' tu ayuda contra los trols de sangre!', 28153),
(132620, 'esMX', '¡Te atrapé! ¡TÚ la traes!', '', 28153),
(132619, 'esMX', '¡Te tengo! ¡Tú la traes!', '', 28153),
(132613, 'esMX', 'Te bendigo con una fracción de mi poder. Úsalo para que Zentimo se una a mis hijos.', '', 28153),
(132611, 'esMX', 'Debug Testing', 'Debug Testing', 28153),
(132609, 'esMX', 'El ataque sucedió tan rápido que... no hubiéramos podido detenerlos.', 'El ataque sucedió tan rápido que... no hubiéramos podido detenerlos.', 28153),
(132608, 'esMX', 'El gigante... nos hizo trizas...', 'El gigante... nos hizo trizas...', 28153),
(132607, 'esMX', 'El arma... destruida...', 'El arma... destruida...', 28153),
(132606, 'esMX', 'Na... nagas... ¡por todas partes!', 'Na... nagas... ¡por todas partes!', 28153),
(132605, 'esMX', 'Gr... Gracias...', 'Gr... Gracias...', 28153),
(132604, 'esMX', 'Así que todo se resume a esto.', 'Así que todo se resume a esto.', 28153),
(132603, 'esMX', '¡Cobarde!', '¡Cobarde!', 28153),
(132602, 'esMX', '¡Nunca me atraparás con vida!', '¡Nunca me atraparás con vida!', 28153),
(132601, 'esMX', '¡$GDesdichado:Desdichada; sin honra!', '¡$GDesdichado:Desdichada; sin honra!', 28153),
(132600, 'esMX', '¡Tú! ¡Basura patética!', '¡Tú! ¡Basura patética!', 28153),
(132599, 'esMX', 'Debe\' ser muy valiente para venir a la Gran Cacería. Presiento que hoy va a ser un día muy interesante.', '', 28153),
(132581, 'esMX', 'Ya me harté de estos insectos. ¡Vamos por su líder!', '', 28153),
(132580, 'esMX', '¡Ya no toleraré estos ataques! ¡Aplástalos! ¡Soy Krag\'wa, y no soy el festín de nadie!', '', 28153),
(132579, 'esMX', 'Bien hecho, $n. Has probado tu fuerza y tu valor con creces. Regresa al templo y recibe tu recompensa.', '', 28153),
(132573, 'esMX', 'En la última invasión de ranishu se devoraron cuatro caravanas. Gracias por impedir que se repitiera.', '', 28153),
(132572, 'esMX', 'Una manada de brutosaurios estuvo merodeando en Vol\'dun, y los ranishu entraron en un frenesí voraz. Reduce su cantidad antes de que se conviertan en una amenaza mortal.', '', 28153),
(132571, 'esMX', 'Demuestra tu valía. Regresa a salvo con las ofrendas y el loa te concederá una audiencia.', '', 28153),
(132566, 'esMX', 'Has servido a este templo y probado tu valía, $n. A cambio, te daré mi bendición si quieres recibirla.', '', 28153),
(132565, 'esMX', 'Debes encontrar la guarida del clamacolmillos y asesinarlo sin demora. La integridad del templo depende de ello.', '', 28153),
(132564, 'esMX', 'Si no expulsamos a los sethrak del cañón, este templo correrá peligro.', '', 28153),
(132563, 'esMX', 'Acepto tu ofrenda, $Gforah\'tero:forah\'tera;. Acércate un poco. Estos ojos gastados ya no ven como antes.', '', 28153),
(132562, 'esMX', 'Parece que tenemoh\' visitas, Jal\'nanji. Atiende a $Gnuestro invitado:nuestra invitada;.', '', 28153),
(132560, 'esMX', '$gBienvenido:Bienvenida; a una cacería de verdad.', '', 28153),
(132550, 'esMX', 'El gran truenagarto nos ha permitido refugiarnos aquí en el templo. Puedes quedarte todo el tiempo que quieras, mientras el loa lo permita.', '', 28153),
(132549, 'esMX', '¡NOOOO! ¡Se roban nuestro M.I.D.A.S.! ¡Nos bajarán el sueldo por el resto de nuestras VIDAS si no lo recuperamos!', '', 28153),
(132547, 'esMX', '¿Has conseguido lo que necesitábamos?', '', 28153),
(132545, 'esMX', '<Ves cientos de fusibles conectados a pequeños recipientes de pólvora brillante.>', '', 28153),
(132544, 'esMX', '<Los alfanjes guardados en esta caja exhiben un brillo familiar en sus hojas.>', '', 28153),
(132541, 'esMX', '<Hay miles de perdigones de mosquete empacados en la caja.>', '', 28153),
(132537, 'esMX', '<De la caja emana el inconfundible aroma de la pólvora.>', '', 28153),
(132536, 'esMX', '<Después de rasgar la envoltura ves el brillo metálico de las armas en la caja.>', '', 28153),
(132534, 'esMX', 'Nunca creí que arriesgaría el pellejo de nuevo por Cyrus.$B$B¡Claro que tampoco creí que viviríamos tanto tiempo!', '', 28153),
(132533, 'esMX', 'Te veré allí cuando tengas información sobre esos cargamentos.', '', 28153),
(132532, 'esMX', 'Envía a esos niños al lado oeste de la fundición. Te esperaré allí y los protegeré para que nadie los secuestre.', '', 28153),
(132531, 'esMX', 'Cagney logró sacar a esta niña del agua con su ferry, dijo que intentaba escapar de la fundición.$B$BNo me sorprende ni un poco que la Compañía Aspafresno ponga a trabajar a los niños. Yo era apenas más grande que ella cuando las pandillas de Boralus me hacían hurgar en bolsillos ajenos y distraer a los guardias por ellos.$B$BEn este mundo, cuanto más débil eres, más expuesto estás a que las personas se aprovechen de ti.', '', 28153),
(132495, 'esMX', '', 'G\'huun... eh\'to no es... lo que prometiste...', 28153),
(132494, 'esMX', '', '¡Idiota! ¡Tu alma le pertenece a G\'huun!', 28153),
(132493, 'esMX', '', '¡No! No estoy lista... para... esto...', 28153),
(132492, 'esMX', '', '¿Cómo te atreve\' a interrumpir mi lamento? ¡Te arrepentirás!', 28153),
(132453, 'esMX', '', '¡Ah! ¡Pensé que me sofocaría ahí dentro! ¡Gracias!', 28153),
(132450, 'esMX', '', 'Salamandra resuella.', 28153),
(132444, 'esMX', '¡Por aquí!', '¡Por aquí!', 28153),
(132416, 'esMX', '¡Quédate cerca!', '', 28153),
(132415, 'esMX', 'Tenemo\' que llegar al jardín de los loa antes de que sea demasiado tarde. ¡Apresúrate, por favor!', '', 28153),
(132408, 'esMX', '', 'Gracias por limpiar ese desastre. Zem\'lan es todavía más peligroso de lo que cuenta la leyenda.', 28153),
(132406, 'esMX', 'Debe haber sido el momento más incómodo de lo\' últimos años. ¡Gracias, $n!', '', 28153),
(132404, 'esMX', '', 'Cuando ponga mis garra\' sobre Yazma y su culto arácnido... Ah, correrá sangre.', 28153),
(132403, 'esMX', 'Gracias, $ct. ¡Por la Horda!', 'Gracias, $ct. ¡Por la Horda!', 28153),
(132398, 'esMX', 'Tengo poco tiempo para charla\' sin sentido.', '', 28153),
(132396, 'esMX', '¿Por qué me haces esta\' preguntas? ¿Quiere\' que te manden a las arena\'?', '', 28153),
(132376, 'esMX', '', 'Pagarás por eso...', 28153),
(132374, 'esMX', '¡Aaaaaaagh!', '¡Aaaaaaagh!', 28153),
(132365, 'esMX', 'El loa ha regresado al templo.', 'El loa ha regresado al templo.', 28153),
(132364, 'esMX', 'Este lugar es muy peligroso, deberías irte antes de que sea demasiado tarde.', 'Este lugar es muy peligroso, deberías irte antes de que sea demasiado tarde.', 28153),
(132343, 'esMX', 'Hay un lugar escondido al otro lado de estas ruinas que sería una base de operaciones perfecta. Dile al equipo que se reúna allí.', '', 28153),
(132342, 'esMX', 'Krah\'gwa observa brevemente a las alebrillas, encantado con su luz.', '', 28153),
(132340, 'esMX', '¡Krah\'gwa engulle la carne de un solo bocado!', '', 28153),
(132325, 'esMX', '¡¿Me insultas?! ¡Largo!', '', 28153),
(132324, 'esMX', '¡Krah\'gwa se enfurece! ¡Debiste actuar más rápido!', '', 28153),
(132323, 'esMX', 'Acepto tus ofrendas. Ahora, muéstrame lo que puedes hacer.', '', 28153),
(132322, 'esMX', 'Krah\'gwa observa alrededor irritado. Parece estar aburrido. ¡Distráelo!', '', 28153),
(132321, 'esMX', 'Krah\'gwa se relame los labios y te observa, hambriento. ¡Aliméntalo!', '', 28153),
(132320, 'esMX', '¡Trajiste regalos! ¡Qué bueno! Vivirás unos momentos más.', '', 28153),
(132310, 'esMX', 'Usando la máscara espiritual', 'Usando la máscara espiritual', 28153),
(132308, 'esMX', 'Poderoso Krah\'gwa, te traigo una ofrenda de carne y moscas.', 'Poderoso Krah\'gwa, te traigo una ofrenda de carne y moscas.', 28153),
(132307, 'esMX', 'Eres $Gamigo:amiga; de las ranas. No te comeré.', '', 28153),
(132306, 'esMX', '¡$GInvasor:Invasora;! ¿Has venido a llevarte a mis hijos? Te comeré.', '', 28153),
(132297, 'esMX', 'Parece que hay un camino que conduce por aquí...', '', 28153),
(132296, 'esMX', '¿Qué sucede, Notley?', '', 28153),
(132294, 'esMX', 'Ten, toma estas piedras que he conseguido. Con estos huesos viejos ya no puedo cargar tantos tesoros como antes. ¡Jo, jo, jo!', '', 28153),
(132293, 'esMX', 'Eh, hola. ¿Podrías ayudar a un anciano? Parece que me he metido en un gran lío.', '', 28153),
(132289, 'esMX', 'Estoy trabajando en un plan para poner todo en orden, no te preocupes.', '', 28153),
(132288, 'esMX', '¡Barbamugre te da las gracias! Eh, toma estos brillantes. Traen mala suerte.', '', 28153),
(132287, 'esMX', '', '¡Eh, tú! ¡Me vendría bien un poco de ayuda!', 28153),
(132279, 'esMX', '', 'Tenemo\' que fortalecer nuestra posición. Somo\' lo único que se interpone entre mi patria y la destrucción.', 28153),
(132275, 'esMX', '', '¡Cómo osas profanar nuestro lugar de descanso!', 28153),
(132274, 'esMX', '', '¡Fuera! ¡Déjanos con nuestro tormento!', 28153),
(132267, 'esMX', 'Eso fue bastante vergonzoso. Por lo menos encontraste mi rifle.', '', 28153),
(132266, 'esMX', 'Ere\' un cambio má\' que bienvenido, siempre estoy cazando trols de sangre.', '', 28153),
(132265, 'esMX', 'No te mueva\'. Tengo que cortarte la cabeza de la mejor forma posible.', '', 28153),
(132264, 'esMX', 'Saluda a Bwonsamdi de mi parte.', '', 28153),
(132263, 'esMX', 'Adelante. No sea\' $gtímido:tímida;.', '', 28153),
(132262, 'esMX', 'Mira por dónde caminas...', '', 28153),
(132261, 'esMX', 'Me quedaré con la cabeza que tiene\' sobre los hombro\'.', '', 28153),
(132260, 'esMX', '¡Ven a jugar, $r insignificante!', '', 28153),
(132254, 'esMX', '', '¡Emboh\'cada!', 28153),
(132243, 'esMX', '', 'Decidí mudarme a Guardiaoriente. Espero que no hayan sufrido el mismo destino que en Glenbrook.', 28153),
(132240, 'esMX', '', 'Eh\'te lugar transmite ira y angustia. Lo que sea que haya sucedido aquí, no terminó de una forma agradable.', 28153),
(132237, 'esMX', '<Ves el diente de una trampa brutal clavado en la pierna del cazador caído.$B$BParece que su armadura está perforada por dardos.$B$BEn su rostro, descubres una mirada de sorpresa congelada en el tiempo. Nunca supo qué fue lo que lo mató.>', '', 28153),
(132236, 'esMX', '', 'Perrito, ¡pórtate bien con nuestro invitado! No queremos que se marche hambriento ni... ¡No queremos que se marche!', 28153),
(132221, 'esMX', 'INSERT SHOOTING GALLERY HERE', '', 28153),
(132205, 'esMX', 'Los carceleros de Jaina llegaron hace unos pocos días para llevarla a su exilio. Si nos apuramos, quizá podamos alcanzarla antes de que sea demasiado tarde.', '', 28153),
(132201, 'esMX', '', '¡Intruso! ¡Pagarás por la muerte de mis hermana\'!', 28153),
(132190, 'esMX', 'La señora de las bestia\' dice que tú eres $guno de nosotros:una de nosotros;, así que podrá\' quedarte aquí. Pero no se te ocurra pensar que te dejaremos hacer lo que quiera\', eh.', '', 28153),
(132189, 'esMX', '', '¡Montar pterrordáctilos es emocionante! ¡No te suelte\' por nada del mundo!', 28153),
(132188, 'esMX', 'Muy bien, entonces comenzaremos por ahí.', '', 28153),
(132187, 'esMX', 'Es probable que haya seguido el camino en busca de refugio.', '', 28153),
(132186, 'esMX', 'Encontraremos la forma, Mace, una vez que encontremos a Jaina. ¿Por dónde empezamos, Yorrick?', '', 28153),
(132185, 'esMX', '', 'Tengo la sensación de que no nos abrirán esa puerta cuando regresemos...', 28153),
(132180, 'esMX', '', 'Por aquí, ¡eh\'te es el camino!', 28153),
(132179, 'esMX', '¿Qué quiere\' del viejo Bwonsamdi?', '', 28153),
(132178, 'esMX', '¡Nada mal! ¡Quizás tenga\' un poco de segador de almas en tu espíritu!', '', 28153),
(132177, 'esMX', '¡Cómo te atreve\' a profanar mi cadáver!', '', 28153),
(132169, 'esMX', 'La Alianza está dispuesta a ofrecer una enorme recompensa por el regreso de Jaina.', 'La Alianza está dispuesta a ofrecer una enorme recompensa por el regreso de Jaina.', 28153),
(132168, 'esMX', '¡¿En Drustvar?! ¡Debes estar bromeando!\n\n¡No, mi deber me exige que permanezca en el muro para proveer suministros a estos soldados valientes! ¡Solo un tonto cruzaría esa puerta por voluntad propia!', '', 28153),
(132152, 'esMX', '', 'Eres $Gun luchador digno:una luchadora digna;, eso está claro. El Mariscal contará con mi apoyo.', 28153),
(132149, 'esMX', '', 'Es un poco tarde para regresar, Yorrick. No creo que Denholm perdone a un guardia que atacó a sus compañeros, aunque siguiera órdenes.', 28153),
(132148, 'esMX', '¡¿Jaina?! ¿Ese es el motivo de nuestra expedición? ¡Eso es traición!', '', 28153),
(132146, 'esMX', 'Es un riesgo que debo asumir, capitán. Soldados, ¡marchen!', '', 28153),
(132145, 'esMX', 'Puedes pasar, Reade, ¡pero la reina se enterará de esto! ¡No volverás a poner un pie en Boralus!', '', 28153),
(132144, 'esMX', 'Suficiente, ¡me rindo!', '', 28153),
(132143, 'esMX', '¡No tenemos tiempo para esto! Soldados, ¡a mi lado!', '', 28153),
(132142, 'esMX', 'Por orden de la reina, nadie puede atravesar esta puerta. Ni siquiera usted.', '', 28153),
(132141, 'esMX', 'Capitán Denholm, he reclutado a estos hombres para una misión especial. ¡Le ordeno que se haga a un lado y nos deje pasar!', '', 28153),
(132140, 'esMX', '¡Alto! ¿A dónde cree que se dirige con mis hombres, mariscal?', '', 28153),
(132139, 'esMX', '¡Con eso debería bastar! ¡Infórmale al mariscal Reade que el intendente Notley está a su servicio!', '', 28153),
(132138, 'esMX', 'Yo solo... tomaré prestadas algunas de las cosas que necesitaremos...', '', 28153),
(132137, 'esMX', '¿Una recompensa? Bueno, eso cambia el panorama...', '', 28153),
(132136, 'esMX', 'Baja el arma, parece que hemos logrado que se marchen.', '', 28153),
(132135, 'esMX', '¡Toma una ballesta y ayúdame, continental!', '', 28153),
(132134, 'esMX', 'Si me necesita, seguiré sus órdenes. Sin embargo, sería negligencia irme antes de dispersar un poco a estas bestias.', '', 28153),
(132133, 'esMX', 'Sospechaba que el mariscal había venido hasta aquí por ese motivo. Aunque si fuera tú, bajaría la voz al mencionar ese nombre por aquí...', '', 28153),
(132132, 'esMX', '', 'De acuerdo. Si puedes probar tu entereza, me uniré a esa campaña que Reade tiene preparada. ¡En guardia!', 28153),
(132131, 'esMX', '', 'Estoy preparada para enfrentarme a los peligros de Bosquenterio, pero no estoy dispuesta a cargar con $Gun:una; continental que no me puede seguir el ritmo.', 28153),
(132130, 'esMX', '', '$gBienvenido:Bienvenida;, $r, a la Gran Cacería. En este lugar, todo lo que camina se puede cazar.$b$bAquí honramo\' a quienes traen los mejore\' trofeos.', 28153),
(132129, 'esMX', '¡Ten cuidado! ¡Esa bruja controla un mojo muy poderoso!', '', 28153),
(132128, 'esMX', 'La tablilla es antigua y está desgastada. Contrasta notoriamente contra las ofrendas más recientes que yacen ante ella.', 'La tablilla es antigua y está desgastada. Contrasta notoriamente contra las ofrendas más recientes que yacen ante ella.', 28153),
(132117, 'esMX', '', '¡Tus hueso\' le servirán a la maestra!', 28153),
(132114, 'esMX', '¡La Horda, escoria y basura!', '', 28153),
(132113, 'esMX', '¿Acaso esta guerra no tiene fin?', '', 28153),
(132112, 'esMX', 'Regresaré a las sombras.', '', 28153),
(132111, 'esMX', 'Ten cuidado, soldado.', '', 28153),
(132107, 'esMX', 'Es al norte. Solo sigue el río y crúzalo en un lugar donde no sea muy profundo.', '', 28153),
(132106, 'esMX', '', 'Iré con ellos, me cercioraré de que sea seguro.', 28153),
(132105, 'esMX', '¡$GBienvenido: Bienvenida;! Disculpa el desorden, no estamo\' acostumbrado\' a recibir visitantes vivo\'.', '', 28153),
(132096, 'esMX', 'Mmm, creo en tu historia... por ahora. Hablemo\'.', '', 28153),
(132095, 'esMX', '', '¡Lo juro!', 28153),
(132094, 'esMX', '¡Aguarda, Jhasan! $GÉl:Ella; tiene aptitude\'. Quizás esta pequeña esté diciendo la verdad.', '', 28153),
(132093, 'esMX', 'Ah, ¿nos distrae\' con tus conversacione\' hasta que lleguen tus amigo\'?', '', 28153),
(132092, 'esMX', '', 'Un momento, es amig... ¡$n, cuidado!', 28153),
(132081, 'esMX', 'Lamento que Zulsan no este aquí para conocerte. Le habría gustado tu peinado.', '', 28153),
(132068, 'esMX', 'Sí, eh\'cuché lo que dijo $p, Man\'zul. Pero sigo pensando que tu parche eh\' más feo que trasero de saurolisco.', '', 28153),
(132067, 'esMX', '¡Ja! Volni, no sea\' mala. Tal vez se vistieron en la oscuridad... ¡Aunque tienes razón!', '', 28153),
(132066, 'esMX', 'Grenja e\' la trovadora de la casa. Cantará la canción que le pidas... siempre y cuando tenga percusión. Le encanta golpear cosas. ¡Con suerte no te golpeará la cara! ¡Ja! No, no lo hará... Bueno, tal ve\' sí.', '', 28153),
(132057, 'esMX', 'No, Grenja. ¡No voy a comprarte un tambor dorado! ¡Deja de pedirme o te sacaré tu bonito sombrero nuevo!', '', 28153),
(132055, 'esMX', 'Debemos eh\'tar atentos aquí. Eh\'te pantano es la fuente de un vudú muy poderoso.', '', 28153),
(132054, 'esMX', 'Tiene\' un aroma fresco. La pestilencia del pantano no pasó a través de tu piel. Ahora, hablemo\'.', '', 28153),
(132053, 'esMX', '', 'Las fuerzas oscuras invocaron a Annie, pero del mal se apartó. ¡Y por supuesto encadenada terminó!', 28153),
(132049, 'esMX', '', 'Sam cuidaba su granja con esmero. Era amable con su ganado, pero ahora el bosque lo ha devorado. ¿Quién cuidará de sus cerdos?', 28153),
(132048, 'esMX', '', 'El señor Hayes tenía un alma amable y bondadosa. Es triste que su corazón sirviera de sacrificio para la bruja monstruosa.', 28153),
(132047, 'esMX', '', 'La señorita Mary nos traicionó con sus ansias de poder maligno. Trajo la muerte y convirtió al bosque en un lugar triste e indigno.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132046, 'esMX', 'Por aquí, $gforastero:forastera;. Para ver al Rey, atraviesa esta puerta y sube por el elevador.', '', 28153),
(132045, 'esMX', '', 'Ten cuidado, $uforastero:forastera;, te estamo\' observando. Estás a punto de conocer a uno de los trols más antiguos que aún respiran. Y está vivo porque mi hermano y yo lo mantenemo\' con vida. No se te ocurra hacer ninguna locura.', 28153),
(132044, 'esMX', '¡Venganza para Zul\'jin!', '', 28153),
(132043, 'esMX', '¡Espero que haya comida en el bote!', '¡Espero que haya comida en el bote!', 28153),
(132042, 'esMX', '¡Ahora quiero una cálida fogata!', '¡Ahora quiero una fogata cálida!', 28153),
(132041, 'esMX', '¡Por favor, ayuda a los ancianos también!', '¡Por favor, ayuda a los mayores también!', 28153),
(132040, 'esMX', '¡Gracias!', '¡Gracias!', 28153),
(132039, 'esMX', 'Volveré a la escuela...', 'Volveré a la escuela...', 28153),
(132038, 'esMX', '¡No me atraparán! ¡Soy demasiado rápido!', '¡No me atraparán! ¡Soy demasiado rápida!', 28153),
(132037, 'esMX', '¡Yo me largo!', '¡Yo me largo!', 28153),
(132020, 'esMX', '', 'Cálmate, Drekal. Estas criatura\' nos han dado refugio. Debemos ganarnos su confianza.', 28153),
(132019, 'esMX', 'Ahh, ¡esa e\' un alma poderosa! El viejo Bwonsamdi se siente rejuvenecido. ¡Jaja, sí! ¡Mi poder aumenta!', '', 28153),
(132017, 'esMX', '', 'Has destruido tu oportunidad de obtener poder...', 28153),
(132016, 'esMX', 'Muy bien. Eso sin duda los frenará.', '', 28153),
(132015, 'esMX', 'El imperio sethrak se expande, se están apoderando de las llanuras donde vivía nuestro pueblo. ¡Debemos detener su conquista!', '', 28153),
(132010, 'esMX', 'Ve hacia la costa. Hay un bote esperándote que te llevará a un lugar seguro.', 'Ve hacia la costa. Hay un bote esperándote que te llevará a un lugar seguro.', 28153),
(132009, 'esMX', '', 'Hombre tonto... No sabes en qué te estás metiendo...', 28153),
(132004, 'esMX', 'Vi unos hombres malos. Les gritaban a todos... ¡Incluso a los mayores!', 'Vi unos hombres malos. Les gritaban a todos... ¡Incluso a los mayores!', 28153),
(132003, 'esMX', '¿Eres de los malos?$B$BNo pareces $gmalvado:malvada;.', '¿Eres de los malos?$B$BNo pareces $gmalvado:malvada;.', 28153),
(132002, 'esMX', 'Tengo la nariz congelada, las orejas congeladas y los dedos de los pies congelados...', 'Tengo la nariz congelada, las orejas congeladas y los dedos de los pies congelados...', 28153),
(131999, 'esMX', 'Dijeron que iban a alimentarnos, ¡pero no he visto ni una hogaza de pan desde que llegué!', 'Dijeron que iban a alimentarnos, ¡pero no he visto ni una hogaza de pan desde que llegué!', 28153),
(131998, 'esMX', '', 'Drekal y yo te encontraremos ahí despué\' de inspeccionar el lugar.', 28153),
(131997, 'esMX', '', 'Debes dirigirte al templo allá adelante. Si eh\'te loa tiene tanto poder como dicen, quizás nos pueda ayudar a encontrar a Rakera.', 28153),
(131996, 'esMX', '<cof> <cof>$B$BQuiero irme a casa.', '<cof> <cof>$B$BQuiero irme a casa.', 28153),
(131995, 'esMX', '¡No me grites!', '¡No me grites!', 28153),
(131994, 'esMX', 'Estoy cansado.', 'Estoy cansada.', 28153),
(131939, 'esMX', '', 'Te doy la bienvenida, soldado. ¿Estás $Glisto:lista; para luchar por la Alianza?', 28153),
(131931, 'esMX', '¿Tú crees que tu vida es dura? No tienes la menor idea de lo difícil que es tratar de estar al día con el cronograma de cada guerra en curso y sus períodos.', '', 28153),
(131897, 'esMX', '', 'Sigamo\' volando. Eh\'peremos que no nos encuentren.', 28153),
(131894, 'esMX', '', 'Tendremo\' que atravesar el pantano. Si seguimo\' volando sin que nos vean, no deberíamo\' tener problemas.', 28153),
(131893, 'esMX', '', '¡Kaja, debajo de nosotros! ¿Qué son esas cosa\'?', 28153),
(131888, 'esMX', 'Mamá pide, mamá recibe.', '', 28153),
(131887, 'esMX', '¡Mi vida por la madreguerra!', '', 28153),
(131886, 'esMX', '¡Carne para las madreguerra!', '', 28153),
(131885, 'esMX', '¡Sangre nueva!', '', 28153),
(131884, 'esMX', 'Mamá dijo \"matar\"... no... \"capturar\". ¡Sí! Capturar.', '', 28153),
(131883, 'esMX', '¡Tendones! Cortarlo\'. Mamá dijo que los cortáramo\'.', '', 28153),
(131882, 'esMX', '¡Muere! ¡Muere! ¡Muere!', '', 28153),
(131881, 'esMX', '<Revisas sus bolsillos y encuentras una carta.>\n\nQueridísima Mary:\n\nPor favor, vuelve a casa. Russell no deja de preguntar por ti. ¿Qué puedo decirle? ¿Que su madre huyó al bosque sin motivo aparente? Te extrañamos, amor mío. Nuestro hogar no es el mismo. Por favor, vuelve con nosotros.\n\nCon amor,\nJonathan', '', 28153),
(131880, 'esMX', '-hic- Mmmira por dddónde caminas...', '-hic- Mmmira por dddónde caminas...', 28153),
(131878, 'esMX', '<Investiga el cadáver para identificarlo.>', '<Investiga el cadáver para identificarlo.>', 28153),
(131875, 'esMX', '¿Cuáles son los envíos de hoy?', '¿Cuáles son los envíos de hoy?', 28153),
(131874, 'esMX', '¿Sí?', '¿Sí?', 28153),
(131869, 'esMX', '¡Grog de viuda! Tres barriles.', '¡Grog de viuda! Tres barriles.', 28153),
(131868, 'esMX', '¡Vino especiado! ¡Cinco barriles! ¡Cerveza abisal! ¡Siete barriles! Y...', '¡Vino especiado! ¡Cinco barriles! ¡Cerveza abisal! ¡Siete barriles! Y...', 28153),
(131867, 'esMX', '¡Escuchen bien! ¡Estos son los cargamentos del día!', '¡Escuchen bien! ¡Estos son los cargamentos del día!', 28153),
(131855, 'esMX', 'Gracias de nuevo por tu ayuda. Llevaré esta ofrenda directamente al templo.', 'Gracias de nuevo por tu ayuda. Llevaré esta ofrenda directamente al templo.', 28153),
(131851, 'esMX', '¡Tranquilícense todo\'! $p se acercará y los saludará uno por uno.', '', 28153),
(131845, 'esMX', 'Eso será suficiente por ahora. Ve y busca a la princesa en la gran escalera. Yo seguiré patrullando en busca de cualquier integrante de la Alianza que hayamo\' pasado por alto.', '', 28153),
(131844, 'esMX', 'Separémono\' y rastreemo\' a los de la Alianza. Haré todo lo que esté a mi alcance para ayudarte a encontrarlos.', '', 28153),
(131843, 'esMX', '¡Qué atrevimiento! Un ataque en mi propio templo. ¡Inaudito! Lamentarán haber pensado que era una buena idea. Oh, sí.', '', 28153),
(131842, 'esMX', '', 'He caminado por eh\'te mundo durante mucho tiempo. Finalmente, ¡he alcanzado la paz!', 28153),
(131841, 'esMX', 'Sigue tu camino, colega. Bwonsamdi te eh\'tará observando.', '', 28153),
(131840, 'esMX', 'Muy bien. Sylvanas estará complacida. Ven, \"portavoz\", planeemos nuestra próxima jugada.', '', 28153),
(131839, 'esMX', 'Momento, ¿TODOS tenemos que luchar contra esa cosa? Pensé que tal vez podíamos... ya saben... enviar a nuestro $Gcampeón:campeona; o algo así.', '', 28153),
(131838, 'esMX', 'Para hacer sonar el tambor necesitarás el mazo de Mambu y el mazo de Gee\'dae. Puedes encontrarlos en mi templo.', '', 28153),
(131832, 'esMX', 'Gracias, camarada.', '', 28153),
(131831, 'esMX', 'Necesito viajar a Zul\'jan.', 'Necesito viajar a Zul\'jan.', 28153),
(131830, 'esMX', '', 'Aunque estoy muerta, las criatura\' siguen respondiendo a mi llamado.\n\n¿Quieres que te lleve?', 28153),
(131829, 'esMX', 'Necesito hablar contigo. Hay una situación que tieneh\' que atender.', '', 28153),
(131828, 'esMX', '¡Hola, $gamigo:amiga;! ¡Te eh\'tuve buscando por todah\' partes!', '', 28153),
(131818, 'esMX', 'No olvides nueh\'tro trato. Sigue enviándole almas a Bwonsamdi... si quiere\' conservar mi protección.', '', 28153),
(131816, 'esMX', '¡Tranquila, princesa! Será mejor que lo tomemo\' con calma. Tenemo\' que explorar el resto del área y diseñar un plan.', '', 28153),
(131803, 'esMX', '', 'Tú debeh\' ser $Gel héroe del que:la heroína de la que; ella hablaba. Si puedes ayudar a la princesa, te contaré todo. He ayudado a cuidar a los heridoh\' durante mucho tiempo, pero cada vez es peor.\n\nElla irá a Nazmir. Solo puede llevar una escolta reducida, pero tu amigo Rokhan también será de la partida. Les hemoh\' dado los suministros que podíamos.\n\nSe dirigen a la puerta noroeste. No se han visto trols de sangre por ahí desde que comenzaron a asediar la puerta principal.\n\nLos ojoh\' de mis loa estarán ocultos allí. Ten cuidado.', 28153),
(131777, 'esMX', 'Te pagaré esta deuda. Lo prometo.', 'Oh... Te pagaré esta deuda. Lo prometo.', 28153),
(131776, 'esMX', '¿Soy libre? ¿Sin condiciones ni tratos? No eres como los demás.', '', 28153),
(131774, 'esMX', '', 'Eh\'to es muy grave. Ojalá la princesa no se hubiera marchado jamás. ¡Loh\' trols de sangre eh\'tán en nuestras puertas y el rey sigue sin hacer nada!', 28153),
(131771, 'esMX', '¡Solo hace un día que llegó y ya se marcha!\n\nTalanji se dirige a algún lugar a espaldas de su padre. Solo llevó a algunoh\' de sus guardias personales para salvar las aparienciah\'.\n\nPresiento que irá a Nazmir, aunque no lo diga. Ese lugar no e\' bueno, colega. Si no puedo ir, al menos me sentiría mejor si tú fueras en mi lugar.\n\nLa princesa debe necesitar suministroh\'. Probablemente les pida ayuda a lo\' sacerdotes como retribución por lo que hizo por ellos. Déjame consultar tu mapa.', '', 28153),
(131766, 'esMX', '¿Dónde está Talanji?', '¿Dónde está Talanji?', 28153),
(131765, 'esMX', 'Nunca olvidaré que ayudah\'te a salvar a nuestra princesa. Sé por experiencia que se hace difícil protegerla. Cree que debe salvar a los zandalari por sí sola.', '', 28153),
(131764, 'esMX', 'No esperaba tanta amabilidad.', 'No esperaba tanta amabilidad.', 28153),
(131763, 'esMX', 'No hay tiempo para hablar, soldado, este es el Mando de Vanguardia. Estamos en plena lucha, y el Campamento Taurajo no deja de enviar oleadas de tauren al ataque.\n\nSi perdemos nuestra posición, no tendremos ninguna posibilidad de conquistar las puertas.', '', 28153),
(131761, 'esMX', '¡No puede\' ocultarte del mojo!', '', 28153),
(131752, 'esMX', 'Valjabu, no hay motivo para cruzar al otro lado. ¡Sométete a G\'huun y conseguirá\' la vida eterna!', '', 28153),
(131750, 'esMX', '¿$gOtro triste exiliado:Otra triste exiliada; que viene a morir en las arenas?', '', 28153),
(131745, 'esMX', '', 'Ve a Nazmir con Rokhan. Nos reuniremos allí. Debemo\' ponerle fin a la amenaza de los trols de sangre.', 28153),
(131742, 'esMX', '', 'Que Odín te bendiga. Ah, y toma esto: una buena recompensa.', 28153),
(131741, 'esMX', 'Muy bien, muchachos. Vamos a hacer que esto sea una fiesta. Quiero guardias en las puertas por si deciden sacarnos a patadas, y quiero una barra de servicio completo ya mismo. Ah, y que alguien me traiga otra piedra de teletransporte en caso de emergencia.', '', 28153),
(131709, 'esMX', '¿Qué está pasando? ¿Por qué nos encerraron en jaulas como animales?', '', 28153),
(131706, 'esMX', '', 'Yorrick, trae tu equipo de primeros auxilios aquí. ¡Tenemos un sobreviviente!', 28153),
(131705, 'esMX', '¡Eh... ah! ¡Sí, mi teniente!', '', 28153),
(131703, 'esMX', '', '¡De pie, alférez! ¡Debemos encontrar la manera de salir de aquí!', 28153),
(131690, 'esMX', 'El guardia de espadas Hozzul no responde.', '', 28153),
(131689, 'esMX', '', 'La guardia de espadas Jorana no responde.', 28153),
(131674, 'esMX', '¡$uBienvenido:Bienvenida; a la posada Colmilloáureo!', '', 28153),
(131672, 'esMX', 'Parece que este exiliado está vivo, aunque apenas respira. \n\nTiene heridas muy graves, pero su aspecto enfermizo podría indicar que sufre de algo más que las lesiones obvias.', '', 28153),
(131671, 'esMX', 'Parece haber luz del otro lado de los escombros que bloquean el camino. \n\nSi pudiéramos quitarlos, puede que encontremos una salida de las ruinas.', '', 28153),
(131670, 'esMX', 'A estas criaturas las asesinaron con magia de escarcha. Es una señal clara de que Jaina pasó por aquí.\n\nSin embargo, todavía es un misterio a dónde fue.', '', 28153),
(131668, 'esMX', 'Creería que estas son las huellas de una de las bestias que atacaron a nuestro grupo en el bosque. Parece que venía arrastrando algo.\n\nLo extraño es que no parece haber rastro de las huellas a partir de aquí, como si la bestia se hubiera desvanecido.', '', 28153),
(131667, 'esMX', 'Cuidado. ¡Estoy LOCO del HAMBRE!', '', 28153),
(131666, 'esMX', '', '¡¿Qué FUE eso?!', 28153),
(131665, 'esMX', 'La prole de cuernoatroz lanza un chillido de sorpresa.', '', 28153),
(131664, 'esMX', 'El cuernoatroz joven salta hacia a ti para demostrarte su afecto.', '', 28153),
(131663, 'esMX', 'El cuernoatroz joven te muerde cariñosamente y te lastima sin querer.', '', 28153),
(131662, 'esMX', 'El cuernoatroz joven te tira al piso de la emoción.', '', 28153),
(131661, 'esMX', '¡Tengo tanta hambre que podría comerme un brutosaurio!', '', 28153),
(131659, 'esMX', 'Mamá, ¿me das un poco más de carne por favor?', '', 28153),
(131658, 'esMX', 'Los azotadores son sabrosos, ¡pero yo quiero CARNE!', '', 28153),
(131657, 'esMX', '%s gruñe con ganas de jugar.', '', 28153),
(131656, 'esMX', '%s te observa con una mirada traviesa.', '', 28153),
(131655, 'esMX', '%s brinca alrededor de ti con regocijo.', '', 28153),
(131654, 'esMX', '%s gimotea con mucha emoción.', '', 28153),
(131653, 'esMX', 'Mira, tienes valor, $gniño:niña;, pero no eres $gun buen negociador:una buena negociadora;. Al menos no estás en mi nivel.$b$bConsígueme una audiencia con ese rey de ellos y le diré tantas cosas lindas que me dará su flota, su trono, todo el oro que usaron para decorar el lugar y quizá un par de máscaras en concepto de suvenir.', '', 28153),
(131652, 'esMX', 'Je, je, ¡miren nada má\'! Quizá seas $Udigno:digna; de mi tiempo despué\' de todo, colega. Ven a verme al templo. Puede que el viejo Bwonsamdi tenga una oferta para ti.', '', 28153),
(131651, 'esMX', 'Ah, Salazae... Ya ha vagado lo suficiente entre los vivo\'. Haz lo necesario para traer su alma ante eh\'te loa tan pero tan paciente, ¿sí?', '', 28153),
(131650, 'esMX', '', 'Vete, a menos que puedas ayudarme a reencontrarme con mi amado.', 28153),
(131649, 'esMX', 'Estamos listos para recibir tu bendición.', 'Estamos listos para recibir tu bendición, gran loa.', 28153),
(131648, 'esMX', 'Han pasado muchoh\' años desde la construcción de este templo. Aunque los muros sigan iguales, los rostros de mis seguidores han cambiado.', '', 28153),
(131637, 'esMX', 'Saludos, pequeños, he regresado. Acérquense y reciban mi bendición.', '', 28153),
(131633, 'esMX', '¡Solo los zandalari pueden caminar por esos salones sagrado\'! La ley dice...', '', 28153),
(131632, 'esMX', 'Que corra la voz... A partir de hoy, te nombro portavoz de la Horda.', '', 28153),
(131631, 'esMX', 'Mientra\' yo sea el rey, la ley será lo que yo diga.', '', 28153),
(131630, 'esMX', 'Los ojo\' del reino descansan sobre ti, $Ucampeón:campeona;. En este día, te nombro Portavoz de la Horda.', '', 28153),
(131629, 'esMX', 'Veamos si la Horda puede probar su valía para Zandalar. Se quedarán en el Gran Sello como invitado\'... por ahora.', '', 28153),
(131628, 'esMX', 'A Talanji le preocupa que yo no vea a nuestros verdaderos enemigo\'. Pero no estoy tan ciego como ella teme.', '', 28153),
(131627, 'esMX', 'Pero mi hija también tiene razón. Fue muy valiente de tu parte reh\'catarla... y por eso te admiro.', '', 28153),
(131626, 'esMX', 'Jakra\'zet tiene razón... buscas la fuerza de nuestra flota para enfrentarte a la Alianza.', '', 28153),
(131625, 'esMX', '', '¡Excelente! Siéntate para que podamos empezar la fiesta. ¡Con tu ayuda y la de Besitos, puedo llamar al último invitado!', 28153),
(131624, 'esMX', '', '¡Por aquí! ¡Esta será la mejor merienda de la historia!', 28153),
(131623, 'esMX', '', '¡Vamos! ¡Vamos! ¡Es hora del té!', 28153),
(131620, 'esMX', '', '¡Con tu sacrificio y el de mi esposo, el ritual estará terminado!', 28153),
(131619, 'esMX', '', '¡Únete a nosotras, hermana, y obtendremos un gran poder!', 28153),
(131618, 'esMX', '<Hay una gran herida abierta en el centro del pecho del hombre. Cuando lo observas, notas que le han arrancado el corazón.>', '', 28153),
(131617, 'esMX', 'Hay una inscripción tallada en la madera: \"S. Hawthorne\".', '', 28153),
(131616, 'esMX', '', 'El señor Hawthorne siempre trataba de alejar a los perritos de sus animales. ¡Pero al fin ahora los perritos pueden comer!', 28153),
(131615, 'esMX', '', 'Nuestra pequeña aldea sucumbió.', 28153),
(131609, 'esMX', '', 'Debemoh\' tener cuidado. Nadie regresa de Nazmir.', 28153),
(131608, 'esMX', '', 'Los trols de sangre son unas beh\'tias patéticas. Hace años que no son una amenaza.', 28153),
(131607, 'esMX', 'Basta. Yo decidiré qué hacer con $Ueste forastero:esta forastera;.', '', 28153),
(131606, 'esMX', '', 'Para derrotar a lo\' trols de sangre, necesitamos aliados. Hice lo que había que hacer.', 28153),
(131605, 'esMX', 'Talanji trajo a esos perro\' de la Horda con ella. Eh\'to es traición, alteza.', '', 28153),
(131604, 'esMX', '', '¡Tu alma para mi amo! ¡Tu alma para G\'huun!', 28153),
(131603, 'esMX', 'Eh\'te no... es... el fin...', 'Eh\'te no... es... el fin...', 28153),
(131602, 'esMX', '', 'G\'huun es el amo de eh\'ta tierra. ¡Pronto, hasta ese payaso de Bwonsamdi eh\'tará a su servicio!', 28153),
(131544, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(131543, 'esMX', '', '<Annie te observa con una mirada vacía. Su ropa está manchada de sangre aunque parece intacta. Intenta balbucear algo, pero sus palabras son inentendibles.>', 28153),
(131542, 'esMX', 'Mace, Notley y Yorrick están a tu servicio y listos para partir.', 'Mace, Notley y Yorrick están a tu servicio y listos para partir.', 28153),
(131541, 'esMX', '¿Eres de Glenbrook?', '¿Eres de Glenbrook?', 28153),
(131540, 'esMX', '', '<Annie tiembla frenéticamente y tiene la mirada perdida.>', 28153),
(131539, 'esMX', 'Es hora. ¡Reúnete conmigo en la puerta y marcharemos a Drustvar!', '', 28153),
(131505, 'esMX', 'No lo dejaré así. Ve a decirles a los demás lo que le hicieron. Volveremos a encontrarnos en el templo.', '', 28153),
(131504, 'esMX', '*Snif* Por favor, despierta...', '', 28153),
(131503, 'esMX', 'Ya estás a salvo, Hakasi... ¿Hakasi? Ey... despierta...', '', 28153),
(131497, 'esMX', '¡Demosuario malo! ¡Malo, malo!', '¡Demosuario malo! ¡Malo, malo!', 28153),
(131496, 'esMX', 'Gracias por ayudarme y por transmitirme las órdenes. Me presentaré ante el mariscal Reade.', '', 28153),
(131494, 'esMX', 'Sin embargo, el tiempo es tirano.', '', 28153),
(131493, 'esMX', 'La decisión más sabia sería esperar a que se despeje la tormenta antes de aventurarnos en territorio hostil.', '', 28153),
(131492, 'esMX', 'Muy bien, prepararé los suministros de inmediato.', '', 28153),
(131491, 'esMX', '¡Infórmale al mariscal Reade que el intendente Notley está a su servicio!', '', 28153),
(131490, 'esMX', '', 'Nos veremos en la puerta, continental. Espero que estés $Gpreparado:preparada; para lo que nos espera.', 28153),
(131489, 'esMX', '', '¡Ja! ¿Así que Reade quiere lanzarse hacia los bosques de Drustvar? Ya era hora de que algo interesante sucediera por aquí.', 28153),
(131487, 'esMX', '', 'Espero que tengas un buen motivo para venir a molestarme, continental \n\n¿No es bastante obvio que estoy ocupada?', 28153),
(131486, 'esMX', 'Una tormenta se avecina en Bosquenterio. Dudo que podamos ver a nuestros atacantes antes de tenerlos encima.\n\nComo si Drustvar ya no fuera bastante peligroso sin las inclemencias del clima...', '', 28153),
(131485, 'esMX', 'El mariscal Reade ha enviado órdenes para que te unas a su expedición para encontrar a Jaina.', 'El mariscal Reade ha enviado órdenes para que te unas a su expedición para encontrar a Jaina.', 28153),
(131484, 'esMX', 'Ah, no recibimos a muchos continentales en el muro. \n\n¿Buscas suministros?', '', 28153),
(131479, 'esMX', 'Debo admitir que tu valentía me sorprende, continental. \n\nAunque no pertenezcas a este lugar, eliges poner tu vida en peligro para salvar a uno de los nuestros. Solo espero que tu espada sea tan firme como tu corazón.\n\nPartiremos cuando lo indiques.', '', 28153),
(131478, 'esMX', 'Resiste, Hakasi... te salvaremos, ¡lo prometo!', '', 28153),
(131477, 'esMX', '¡Nunca... te saldrás con la tuya! ¡Monstruo!', '', 28153),
(131476, 'esMX', '¿Qué es esto? ¿Un continental viene de visita al muro? Seguramente quieres echarle un vistazo a la tierra maldita de Drustvar sin ver de cerca sus peligros verdaderos, ¿no?\n\nVete a casa, $Gniño:niña;. Este no es lugar para viajeros.', '', 28153),
(131475, 'esMX', '¿Qué...?\n\nLo siento. Yo... me equivoqué. \n\n¿Así que eres $Galiado:aliada; de la casa Valiente? Imagino que habrás venido en busca de noticias de Jaina. ¿Por qué otro motivo alguien vendría hasta aquí?\n\nBien, puede que hayas llegado justo a tiempo.', '', 28153),
(131472, 'esMX', '<Entrégale a Reade la nota de Taelia>', '<Entrégale a Reade la nota de Taelia>', 28153),
(131471, 'esMX', '¡Ah, hola, Hanzabu! ¿Has venido a pagar tus deuda\'?', '', 28153),
(131470, 'esMX', '¿Qué noticias traes, $Gviajero:viajera;?', '', 28153),
(131469, 'esMX', '¡Tenemos que salvarlo!', '', 28153),
(131468, 'esMX', 'Oí la voz de Hakasi, ¡venía de esa cueva! Parecía que estaba en problemas...', '', 28153),
(131467, 'esMX', '¡$n! ¡Por aquí!', '', 28153),
(131466, 'esMX', '¡Guardias! ¡Aliados! ¡Las fuerzas de la Horda se acercan desde el sudoeste! ¡A las puertas!', '', 28153),
(131465, 'esMX', 'Tú ocúpate del ofidio, yo entraré a buscar a Hakasi...', '', 28153),
(131461, 'esMX', '¡BUA JA JA! Hanzabu, ¡¿de verdad me crees tan incrédulo?! Tú no fuiste quien mató a esos do\'.', '', 28153),
(131460, 'esMX', 'Dos de ellos son eh\'pecialmente poderosos. Estimo que bastarán para cumplir con nuestro acuerdo, ¿verdad?', '', 28153),
(131459, 'esMX', 'Gran Bwonsamdi, me presento con más alma\'... como acordamo\'.', '', 28153),
(131458, 'esMX', '', 'Un momento... Eh\'cucha... Creo que oigo algo.', 28153),
(131457, 'esMX', '', '¡La barrera está desactivada! ¡Salgamo\' de aquí!', 28153),
(131456, 'esMX', 'Era inservible. Los trols de sangre invaden nuestras tierras desde el norte, la Alianza se infiltra en nuestra\' frontera\' al sur y ahora les permites a esto\' perros de la Horda que ingresen a nuestra ciudad.', '', 28153),
(131455, 'esMX', '', 'Lo que sea que hiciste detuvo el flujo de mojo hacia la barrera. Sigamo\' buscando más de esas cosa\'.', 28153),
(131454, 'esMX', '', 'Rakera era una de las más grandes lídere\' de este rein...', 28153),
(131453, 'esMX', 'Tengo noticias sobre Hakasi.', 'Tengo noticias sobre Hakasi.', 28153),
(131452, 'esMX', '', '¡Nos atacan!', 28153),
(131451, 'esMX', '', '¡El camino está cerrado! Echemo\' un vistazo, tiene que haber alguna manera de desactivar la barrera.', 28153),
(131450, 'esMX', '', '¡Sin piedad!', 28153),
(131449, 'esMX', '', '¡Nadie nos detendrá!', 28153),
(131448, 'esMX', '', '¡Machacado!', 28153),
(131447, 'esMX', '', '¡Tayhuwaniwanga!', 28153),
(131446, 'esMX', '<Un monstruo ruge en la distancia.>', '', 28153),
(131445, 'esMX', '¡Tenemos que ir a buscarlo antes de que sea demasiado tarde! Encuéntrame cerca del cañón apenas estés $Glisto:lista;.', '', 28153),
(131444, 'esMX', 'Así que Hakasi fue a investigar algo al cañón y todavía no regresó... esto podría ser malo.', '', 28153),
(131443, 'esMX', '', 'Cuidado, los espíritus están furiosos. Supongo que están atrapado\' aquí hace mucho tiempo.', 28153),
(131442, 'esMX', '', '$UNuestro invitado:Nuestra invitada; se ha despertado.', 28153),
(131440, 'esMX', '', 'A Besitos le encantan los bosques. ¡Me aseguraré de que los perros no lo hayan encontrado!', 28153),
(131439, 'esMX', '¡No me atraparás, bruja!', '', 28153),
(131435, 'esMX', '¡Ayuda a los adiestradores a calmar al demosaurio!', '¡Ayuda a los adiestradores a calmar al demosaurio!', 28153),
(131434, 'esMX', '¡Ataca a la Muerte Roja!', '¡Ataca a la Muerte Roja!', 28153),
(131431, 'esMX', '¡Arroja un juguete para distraer al demosaurio!', '¡Arroja un juguete para distraer al demosaurio!', 28153),
(131430, 'esMX', '¡Carga contra la barrera para romperla!', '¡Carga contra la barrera para romperla!', 28153),
(131429, 'esMX', '¡Escapa por la puerta del norte! ¡Que no te atrape el demosaurio!', '¡Escapa por la puerta del norte! ¡Que no te atrape el demosaurio!', 28153),
(131428, 'esMX', '¡Buena suerte, $gaprendiz:aprendiza;!', '', 28153),
(131427, 'esMX', '¡$UBienvenido:Bienvenida; al campo de entrenamiento! A continuación te enfrentaráh\' a Pinky, nuestro joven y feroz demosaurio.', '', 28153),
(131426, 'esMX', '¡Ese cargamento nos pertenece, escoria de la Alianza!', '¡Ese cargamento nos pertenece, escoria de la Alianza!', 28153),
(131425, 'esMX', 'Inspeccionar el cadáver en detalle.', 'Inspeccionar el cadáver en detalle.', 28153),
(131424, 'esMX', '<Las heridas son profundas. Los cortes evidencian una precisión minuciosa.$B$BEn las áreas afectadas, resplandecen restos de una sustancia líquida cuando les da la luz.>', '', 28153),
(131419, 'esMX', '', 'Nos iremos cuando diga\', pero tenemo\' poco tiempo. Rakera no durará mucho en las arena\'.', 28153),
(131418, 'esMX', '', 'No deh\'cansaré hasta que aparezca Rakera.', 28153),
(131416, 'esMX', '¿Alguna vez has luchado contra un demosaurio? No muerden fuerte... ¡a vece\'!', '¿Alguna vez has luchado contra un demosaurio? No muerden fuerte... ¡a vece\'!', 28153),
(131415, 'esMX', '', '¡Tiene\' razón! ¡Hagámoslo!', 28153),
(131414, 'esMX', '', 'Tus palabra\' son sabias. Ven, busquemo\' una manera de salir de esta cripta.', 28153),
(131413, 'esMX', '', 'Tus palabra\' son cierta\', colega. Echemo\' un vistazo, tiene que haber una manera de salir de aquí.', 28153),
(131408, 'esMX', 'Un soldado nunca se da por vencido, Bwu\'ja. Ahora, recupera la compostura y busquemos una manera de salir de aquí. ¡Por la Horda!', 'Un soldado nunca se da por vencido, Bwu\'ja. Ahora, recupera la compostura y busquemos una manera de salir de aquí. ¡Por la Horda!', 28153),
(131407, 'esMX', 'Tenemos una misión Bwu\'ja, ¡y debemos completarla sin importar el precio!', 'Tenemos una misión Bwu\'ja, ¡y debemos completarla sin importar el precio!', 28153),
(131406, 'esMX', '¿Esta es la actitud que quieres que vea tu Jefa de Guerra? ¡La Horda cuenta con nosotros!', '¿Esta es la actitud que quieres que vea tu Jefa de Guerra? ¡La Horda cuenta con nosotros!', 28153),
(131405, 'esMX', '', 'No tiene sentido luchar, ¡estamo\' perdido!', 28153),
(131404, 'esMX', 'Eres una Cazadora de las sombras, Bwu\'ja. Muéstrales por qué portas ese título.', 'Eres una Cazadora de las sombras, Bwu\'ja. Muéstrales por qué portas ese título.', 28153),
(131403, 'esMX', '¿Permitirás que los sueños y la esperanza de tus ancestros acaben aquí sin luchar por ellos?', '¿Permitirás que los sueños y la esperanza de tus ancestros acaben aquí sin luchar por ellos?', 28153),
(131399, 'esMX', '¡Entonces sigue luchando! ¡Cree en ti misma y hazlos sentir orgullosos!', '¡Entonces sigue luchando! ¡Cree en ti misma y hazlos sentir orgullosos!', 28153),
(131396, 'esMX', '', '¿Qué? ¡Claro que no!', 28153),
(131392, 'esMX', 'No te rindas. Eres fuerte. ¡Eres una Cazadora de las sombras!', 'No te rindas. Eres fuerte. ¡Eres una Cazadora de las sombras!', 28153),
(131391, 'esMX', 'Parece que la princesa Talanji no quiso eh\'perar. Zul y ella ya se dirigen al muelle. Será mejor que te apresure\' si quieres alcanzarlos.', '', 28153),
(131389, 'esMX', '', 'Placeholder World Quest Text', 28153),
(131388, 'esMX', 'Si te invade la desesperación, ¡es porque tu espíritu aún vive y puedes hacer algo para cambiar la situación!', 'Si te invade la desesperación, ¡es porque tu espíritu aún vive y puedes hacer algo para cambiar la situación!', 28153),
(131387, 'esMX', '¡Se está liberando! ¡Corre!', '¡Se está liberando! ¡Corre!', 28153),
(131386, 'esMX', '¡Aún hay esperanza! Si trabajamos en conjunto, podemos encontrar una manera de derrotar esta maldición.', '¡Aún hay esperanza! Si trabajamos en conjunto, podemos encontrar una manera de derrotar esta maldición.', 28153),
(131385, 'esMX', 'Por ahora, dejaré que tú y Rokhan decidan la forma de proseguir porque él conoce a esta gente mejor que yo.$b$bAdemás, estos trols tienen prejuicios contra los que, como yo, se niegan a morir. No quiero que su pobre filosofía de vida se interponga entre nosotros y su flota.$b$bNo podemos fallar. Sylvanas necesita una flota.', '', 28153),
(131384, 'esMX', '', '¿Qué? ¿Y por qué pensarías eso?', 28153),
(131383, 'esMX', '¡No te rindas, aún tenemos fuerzas para luchar!', '¡No te rindas, aún tenemos fuerzas para luchar!', 28153),
(131382, 'esMX', 'Cuando te reúnas con los espíritus de tus ancestros, ¿les dirás que te diste por vencida?', 'Cuando te reúnas con los espíritus de tus ancestros, ¿les dirás que te diste por vencida?', 28153),
(131377, 'esMX', '¡No te des por vencida! Encontraremos la manera de salir de esto.', '¡No te des por vencida! Encontraremos la manera de salir de esto.', 28153),
(131372, 'esMX', 'En marcha.', 'En marcha.', 28153),
(131371, 'esMX', '¡No puedo creer que Hakasi nos dejó con todo el trabajo! ¡Pagará por esto cuando vuelva!', '', 28153),
(131370, 'esMX', '', '¡Ja, ja! ¡Atraviésalo!', 28153),
(131369, 'esMX', '', 'No tiene sentido. ¿Cómo haremo\' para salir de aquí?', 28153),
(131333, 'esMX', 'Mencionó algo acerca de unos disturbios en el cañón. Le dije que seguramente no había nada de qué preocuparse.', '', 28153),
(131332, 'esMX', 'Mmmm... Déjame pensar. ¡Ah, sí! Lo vi entrar al cañón hace poco. Me pregunto qué estaría haciendo ahí.', '', 28153),
(131331, 'esMX', '¿Hakasi? Sí, lo vi hoy más temprano. Andaba cerca de aquí, juntando las ofrendas para el ritual.', '', 28153),
(131329, 'esMX', '', '¡Todos, rompan filas! ¡Vayan a un lugar seguro! ¡Aléjense de las serpiente\' todo lo que puedan!', 28153),
(131327, 'esMX', 'Kaja, debemos ajustar el rumbo. Nos acercamo\' al imperio sethrak.', '', 28153),
(131325, 'esMX', '', '¿Hombres serpiente? Creía que se ocultaban bajo las duna\'...', 28153),
(131322, 'esMX', '', '¡Adelante! ¡Veo el paso! Vuela bajo y buh\'ca signos de Rakera.', 28153),
(131306, 'esMX', '¿Nunca habías visto $Gal:a la; gran Akunda? ¡No podrías haber llegado en mejor momento!', '', 28153),
(131305, 'esMX', '¡Tengo muchísimo trabajo que hacer antes de que llegue Akunda! No queda tiempo... ¡No queda nada de tiempo!', '', 28153),
(131304, 'esMX', '¿Has visto a Hakasi?', '¿Has visto a Hakasi?', 28153),
(131303, 'esMX', 'Ha pasado mucho tiempo desde la última vez que invocamos a Akunda. ¡No puedo esperar para estar de nuevo en su presencia!', '', 28153),
(131302, 'esMX', '¡%s devora todos los bocadillos con mucho entusiasmo y luego eructa llamas!', '', 28153),
(131300, 'esMX', '%s devora la planta de manera ruidosa.', '', 28153),
(131299, 'esMX', '¡Al fin, una batalla de verdad!\n\nEstos necios de la Horda creen que podrán atravesar la sima y llegar al Mando de Vanguardia. ¿Y piensan que será fácil?\n\n¡OH, NO!\n\nVamos, asesinemos a esa escoria juntos.', '', 28153),
(131298, 'esMX', '', '¡Me alegra que hayas llegado, soldado! ¡Apenas podemos resistir!\n\nEl Fuerte Triunfo es un punto crucial en nuestro intento por asaltar las puertas. El ataque constante de los refuerzos de Orgrimmar contra la sima que está al norte es un problema. Si no podemos conservar esta posición, todos los convoys de Theramore estarán en peligro.', 28153),
(131297, 'esMX', 'Como desee, Maestro Higashi...', '', 28153),
(131296, 'esMX', 'Probar toda la comida no e\' preparar el banquete. ¡No te lo volveré a pedir, Rifu!', '', 28153),
(131295, 'esMX', '¡Pero ya estoy ocupado preparando el banquete!', '', 28153),
(131294, 'esMX', 'Hakasi todavía no ha llegado con el resto de las ofrendas. Ve con $gnuestro nuevo amigo:nuestra nueva amiga; a juntar lo que falta.', '', 28153),
(131293, 'esMX', '¡Sí, Maestro Higashi!', '', 28153),
(131292, 'esMX', '¡Rifu! Tenemos $gun visitante:una visitante; que quiero que conozcas.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131291, 'esMX', 'Sin ellas no podremos invocar al loa. Quizá tú puedas ayudarnos...', '', 28153),
(131290, 'esMX', 'Ya casi es hora de comenzar con el ritual, pero muchas de las ofrendas aún no han llegado.', '', 28153),
(131289, 'esMX', 'Busca las tablas antiguas en los salones del templo. La leyenda de Akunda te espera...', '', 28153),
(131255, 'esMX', 'Todos rendiremo\' tributo al gran truenagarto. Y protegerá nuestra selva por siempre.', '', 28153),
(131254, 'esMX', '', 'Bien. Es momento de elegir un huevo, $unovato:novata;. Sabrá\' si tu cría te acepta cuando oiga\' su voz en tu cabeza...', 28153),
(131250, 'esMX', '', '<La matriarca Jaz\'lith te evalúa con muchísimo cuidado>', 28153),
(131249, 'esMX', '', 'Allí la tiene\'. Es la mezcla perfecta entre ferocidad y gracia, ¿no crees? Desafíala si te atreve\'.', 28153),
(131248, 'esMX', '', 'Eh\'te monumento se parece a los santuario\' de Bwonsamdi en Zuldazar, pero es mucho más antiguo.', 28153),
(131247, 'esMX', 'Mi cuernoatroz y yo hemo\' estado juntos desde el día en que rompió el cascarón. Luchamos como uno.', 'Mi cuernoatroz y yo hemo\' estado juntos desde el día en que rompió el cascarón. Luchamos como uno.', 28153),
(131246, 'esMX', 'Para convertirse en clamabestias, se necesita mucha habilidad, sí, pero también una gran dosi\' de paciencia. Los cuernoatroz jóvene\' te pueden dar más de un dolor de cabeza, ¿sabes?', 'Para convertirse en clamabestias, se necesita mucha habilidad, sí, pero también una gran dosi\' de paciencia. Los cuernoatroz jóvene\' te pueden dar más de un dolor de cabeza, ¿sabes?', 28153),
(131245, 'esMX', 'Y así, sobre este mismo suelo, construimo\' el templo en honor a Akunda. Jamás volveremos a olvidar a nueh\'tro loa.', '', 28153),
(131244, 'esMX', 'Cuando el polvo se disipó, escalamos hasta la cima de la montaña. El cadáver de Zul\'khan yacía ante nuestro\' ojos, pero Akunda no estaba por ninguna parte.', '', 28153),
(131243, 'esMX', 'Cuando parecía que la batalla jamáh\' llegaría a su fin, el polvo se disipó y la tierra entró en calma...', '', 28153),
(131242, 'esMX', 'Akunda al fin había regresado. Las do\' bestias entraron en combate. ¡La tierra se estremecía con cada golpe!', '', 28153),
(131241, 'esMX', 'Cuando todo parecía perdido, un rugido estruendoso resonó en todo el cañón. Sobre lo\' riscos emergió una figura que bloqueaba la luz de la luna.', '', 28153),
(131240, 'esMX', 'Atacamos a Zul\'khan con todas nuestras fuerzas, ¡pero no pudimos con su poder! Se liberó... nuestro fin se acercaba.', '', 28153),
(131239, 'esMX', 'Llevamos a Zul\'khan hasta las profundidades del cañón y lo emboscamos. Le arrojamo\' una red enorme desde arriba...', '', 28153),
(131238, 'esMX', 'Los anciano\' de las tribus se reunieron en el corazón de Vol\'Aman. ¿Aunamos fuerzas y luchamos juntos o huimos de la selva con lo que podamo\' recoger? ¡Decidimos luchar!', '', 28153),
(131237, 'esMX', 'Zul\'khan ahora era libre de aterrorizar la tierra. Cazaba y asesinaba a mi pueblo indiscriminadamente. Fueron época\' oscuras...', '', 28153),
(131236, 'esMX', 'Dejamo\' de rendir tributo al gran truenagarto. Finalmente, Akunda desapareció de la selva...', '', 28153),
(131235, 'esMX', 'Akunda nos protegía del terrible Zul\'khan. Pero con los año\', mi pueblo se confió demasiado.', '', 28153),
(131234, 'esMX', 'El demosaurio Zul\'khan envidiaba el poder de lo\' loa. Merodeaba en la selva oscura, cazando por codicia y matando por placer.', '', 28153),
(131233, 'esMX', 'Toda\' las criaturas de la selva reverenciaban su poder y majestuosidad. Todos menos el tiránico Zul\'khan...', '', 28153),
(131232, 'esMX', 'Hace mucho tiempo, mi pueblo contemplaba con admiración al gran truenagarto mientra\' vagaba por la jungla.', '', 28153),
(131231, 'esMX', 'Yo, Zen\'gaji, líder de mi tribu y arquitecto de eh\'te templo, lo dedico al poderoso Akunda.', '', 28153),
(131230, 'esMX', 'He entrenado para ser clamabestias deh\'de que nací. ¿Y tú qué has hecho?', 'He entrenado para ser clamabestias deh\'de que nací. ¿Y tú qué has hecho?', 28153),
(131229, 'esMX', '¡A luchar!', '¡A luchar!', 28153),
(131228, 'esMX', '', '¡Zandalar por siempre!', 28153),
(131227, 'esMX', '', '¡Los loa eh\'tan conmigo!', 28153),
(131226, 'esMX', '', '¡Por Zuldazar!', 28153),
(131224, 'esMX', '', 'La guardiana bélica Rakera era mi comandante. La mejor en la hih\'toria de la ciudad.', 28153),
(131223, 'esMX', 'No hago preguntas. Cumplo órdenes. Si fueras $usensato:sensata;, harías lo mismo.', '', 28153),
(131222, 'esMX', 'Desembucha, $n. No me pagan para charlar.', '', 28153),
(131221, 'esMX', '', '¿Quieres morir? El general tiene ojos y oído\' por todos lado\'.', 28153),
(131220, 'esMX', '', 'No sé qué necesita\', pero que sea rápido.', 28153),
(131218, 'esMX', '', 'Como ves, aún quedan persona\' que comparten nueh\'tra creencia.', 28153),
(131215, 'esMX', '', '¡Ey, tú! Sí, tú. ¿Tú ere\' quien anda preguntando por el general?', 28153),
(131214, 'esMX', '', 'Las duna\' son una sentencia de muerte. ¡No me quedaré de brazos cruzado\' mientra\' las arena\' devoran a Rakera!', 28153),
(131213, 'esMX', '', 'No sé qué deh\'cubrió, pero fue suficiente para ganarse un viaje al desierto.', 28153),
(131212, 'esMX', '', 'Me dijo que eh\'taba cerca de demostrar que el general Jakra\'zet es un traidor a la corona, pero no volví a oír de ella.', 28153),
(131211, 'esMX', '', 'Sígueme, pero evitemo\' llamar la atención.', 28153),
(131210, 'esMX', '¿Qué puedes decirme sobre el general Jakra\'zet?', '¿Qué puedes decirme sobre el general Jakra\'zet?', 28153),
(131209, 'esMX', '', '¿Qué puedo hacer por ti?', 28153),
(131208, 'esMX', 'Lamento mucho que hayan quedado en medio de todo eh\'to, pero al menos conocerán a Bwonsamdi, ¡tal como querían! ¡Je, je, jo!', '', 28153),
(131207, 'esMX', 'Je, je, je. Buen trabajo. ¡Eh\'ta alma será una ofrenda digna para Bwonsamdi!', '', 28153),
(131206, 'esMX', '¡Maldición, me han encontrado! Oye, ayúdame y veré qué puedo hacer por esa bendición que buh\'cas.', '', 28153),
(131205, 'esMX', '¡A las armas!', '', 28153),
(131204, 'esMX', '', '¡Mariscal, no!', 28153),
(131203, 'esMX', '$GSuéltalo:Suéltala;, bestia...', '', 28153),
(131202, 'esMX', '', '¡Cuidado, continental!', 28153),
(131201, 'esMX', 'Mace, Yorrick, dispérsense por el perímetro y busquen...', '', 28153),
(131200, 'esMX', '', '¿Crees que bajó... por ahí?', 28153),
(131199, 'esMX', 'No entiendo. La senda lleva por este camino...', '', 28153),
(131198, 'esMX', 'Es un camino sin salida...', '', 28153),
(131197, 'esMX', '', '¡¿Qué... es este lugar?!', 28153),
(131196, 'esMX', 'Parece haber una estructura a la distancia. ¡Seguramente Jaina iba hacia allí!', '', 28153),
(131195, 'esMX', 'Las bestias bloquean el paso. ¡Ábranse camino!', '', 28153),
(131194, 'esMX', '¡Debemos avanzar hacia las profundidades del bosque! ¡Fórmense!', '', 28153),
(131193, 'esMX', 'Esto parece magia de hielo... ¡Jaina debe haber estado por aquí!', '', 28153),
(131192, 'esMX', '¡Maldición! Tendremos que seguir sin él... Un momento, ¿qué es eso?', '', 28153),
(131191, 'esMX', '¡Señor! ¡No veo señales de Notley y es imposible seguir el rastro con esta tormenta!', '', 28153),
(131190, 'esMX', 'Esto... esto no está nada bien.', '', 28153),
(131189, 'esMX', '', 'Pero qué...', 28153),
(131188, 'esMX', '¡Rápido, se fueron por aquí!', '', 28153),
(131187, 'esMX', '', '¡Es una emboscada!', 28153),
(131186, 'esMX', '¡Aaaaaaahhhh!', '', 28153),
(131185, 'esMX', '¡Notley, no!', '', 28153),
(131184, 'esMX', 'Momento... Creo que veo algo...', '', 28153),
(131183, 'esMX', 'Vamos, tenemos que seguir avanzando.', '', 28153),
(131182, 'esMX', 'Quisiera creerlo. Pero no, creo que esto es obra de algo mucho más oscuro.', '', 28153),
(131181, 'esMX', '', 'Parece que no solo hay bestias en este bosque. ¿Crees que un exiliado hizo esto?', 28153),
(131180, 'esMX', '¡Alto! ¿Qué es esto?', '', 28153),
(131179, 'esMX', 'Esto no está nada bien...', '', 28153),
(131178, 'esMX', 'Las bestias se vuelven cada vez más feroces. No me hubiera imaginado que nos atacarían en campo abierto.', '', 28153),
(131177, 'esMX', '¿Qué fue eso? ¡Hombres, en guardia!', '', 28153),
(131176, 'esMX', '¡Síganme!', '', 28153),
(131175, 'esMX', 'Preparen sus armas y reúnan todo su valor. ¡Esta noche cabalgamos hacia la oscuridad!', '', 28153),
(131174, 'esMX', 'A las bestias de estos bosques no les agrada mucho que... bueno, básicamente no les agrada nada.', '', 28153),
(131173, 'esMX', 'La tormenta limitará nuestra visibilidad, así que no te alejes demasiado ni te desvíes del camino.', '', 28153),
(131172, 'esMX', 'Estoy listo para entrenar.', 'Estoy lista para entrenar.', 28153),
(131171, 'esMX', 'Nosotros entrenamo\' bestia\' de todo tipo y tamaño. ¡Incluso las que están destinada\' a llevar carga tienen que estar lista\' para luchar!', '', 28153),
(131170, 'esMX', 'Seguiremos el camino hacia Límite del Destino, que es hacia donde se debería dirigir la caravana del exilio.', '', 28153),
(131169, 'esMX', '', 'Los espíritu\'... me... abandonan...', 28153),
(131168, 'esMX', '', '¡¡¡Ahhh!!', 28153),
(131167, 'esMX', '', 'No puedo... seguir...', 28153),
(131166, 'esMX', '', '¡Jamáh\' nos derrotarán! ¡Los maldigo a todos con mi último aliento! ¡Nos veremos en el otro lado!', 28153),
(131165, 'esMX', '', 'El vínculo entre bestia y jinete es posible gracia\' a un fetiche. Toca nuestra piedra sáurida cuando estés $ulisto:lista;.', 28153),
(131158, 'esMX', 'En nombre de Akunda, el gran loa, te doy la bienvenida a este templo, $gviajero:viajera;.', '', 28153),
(131148, 'esMX', '', 'Luchas bien. Mis cría\' estarán bien contigo.', 28153),
(131142, 'esMX', '', '¡Mis cría\' solo se merecen lo mejor!', 28153),
(131115, 'esMX', '¡Acábenlos, muchachos!', '', 28153),
(131114, 'esMX', '¡Cobardes! ¡Envíen a su mejor adalid y veremos de qué está hecho!', '', 28153),
(131113, 'esMX', 'Veamos qué tienen estas escorias de la Horda para nosotros.', '', 28153),
(131112, 'esMX', '', '¡Me bañaré en tu sangre!', 28153),
(131111, 'esMX', '', '¡Te he atrapado esta vez, Hanzabu! ¡Pagarás por la muerte de mis hermana\'!', 28153),
(131109, 'esMX', 'Buscamos al loa, Bwonsamdi', 'Buscamos al loa, Bwonsamdi', 28153),
(131108, 'esMX', 'Parece que ya hemos superado lo peor. Descansemos un instante antes de avanzar.', '', 28153),
(131107, 'esMX', 'Bien hecho, estas tropas serán invaluables en la guerra.', '', 28153),
(131106, 'esMX', 'Tropas, descansen. Esperaremos aquí por un minuto y partiremos en breve.', '', 28153),
(131105, 'esMX', '¡Soldados de la Alianza! ¡Defiendan este convoy honorable mientras nos abrimos paso hacia el Mando de Vanguardia!', '', 28153),
(131098, 'esMX', 'Esas garra\'... esos diente\'... Tendré pesadilla\' durante mucho tiempo.', 'Esas garra\'... esos diente\'... Tendré pesadilla\' durante mucho tiempo.', 28153),
(131097, 'esMX', '¡Llegas justo a tiempo!', '¡Llegas justo a tiempo!', 28153),
(131096, 'esMX', 'Pensé que no lo lograría. ¡Graciah\'!', 'Pensé que no lo lograría. ¡Graciah\'!', 28153),
(131094, 'esMX', 'Tus vestimenta\' no están cubiertas de mugre y no hueles mal.$b$b¿Quién ere\'? ¿Qué haces merodeando en el pantano?', '', 28153),
(131093, 'esMX', '¿Quién eres, $uforastero:forastera;? No hueles a trol de sangre...', '', 28153),
(131088, 'esMX', '', '¡Yupi! ¡Esta será la mejor merienda de la historia! Busquemos a los demás invitados.', 28153),
(131087, 'esMX', '¿Qué quiereh\' de Hanzabu?', '', 28153),
(131086, 'esMX', '', '¡Trompitas! ¡Sabes perfectamente que la señorita Mary no te quiere dentro de la casa! ¡Dejas tus huellas por todas partes!', 28153),
(131085, 'esMX', '', '¡Señor Glotoncito! Tenías hambre, ¿no? Vamos. Es la hora del té.', 28153),
(131081, 'esMX', '', '¡Alcalde Striggs malo! Siempre escapas a tus responsabilidades con el pueblo. Bien, ¡ya no puedes seguir huyendo!', 28153),
(131080, 'esMX', '', 'No confío en él. Deberíamo\'...', 28153),
(131079, 'esMX', '¡Silencio! ¡No quiero oír ni una palabra más!', '', 28153),
(131078, 'esMX', '', '¡Aggh!', 28153),
(131077, 'esMX', 'Uh, sí, ¡eh\'te será un excelente premio!', '', 28153),
(131057, 'esMX', '¡$n ha defendido el Aserradero!', '', 28153),
(131056, 'esMX', '¡La Alianza ha tomado los Restos del Naufragio!', '', 28153),
(131055, 'esMX', '¡La Horda ha tomado los Restos del Naufragio!', '', 28153),
(131054, 'esMX', '¡$n ha asaltado los Restos del Naufragio!', '', 28153),
(131049, 'esMX', '¡La Horda ha desplegado un tanque en el camino hacia Fuerte del Norte! ¡Debemos destruirlo!', '¡La Horda ha desplegado un tanque en el camino hacia Fuerte del Norte! ¡Debemos destruirlo!', 28153),
(131048, 'esMX', 'Gesta completa.', 'Gesta completa.', 28153),
(131033, 'esMX', '', '¡Abran camino para la Séptima Flota! Comenzaremos la ofensiva cuando lleguen los refuerzos.', 28153),
(131032, 'esMX', 'Test', '', 28153),
(131030, 'esMX', '', '¡Mira, colega! El rastro del mojo se dirige hacia el norte. Vamo\' a seguirlo.', 28153),
(131025, 'esMX', '', '¿Qué noticias traes del norte?', 28153),
(131010, 'esMX', '', 'Mmm... Un sacrificio. Aún está fresco. El mojo residual del ritual que se realizó aquí ha dejado un rastro. Veamo\' hacia dónde nos lleva.', 28153),
(131009, 'esMX', 'El cuerpo tiene una pequeña daga incrustada en la espalda.', 'El cuerpo tiene una pequeña daga incrustada en la espalda.', 28153),
(131008, 'esMX', '', 'Siento una presencia má\' fuerte al norte. Vayamo\' a echarle un vistazo.', 28153),
(131007, 'esMX', '', 'Esta ofrenda no estaba aquí cuando encontré este lugar. Parece que Bwonsamdi aún tiene algún seguidor por aquí.', 28153),
(131000, 'esMX', 'El clima severo de Nazmir ha erosionado la mayoría de las escrituras de la tablilla. Solo se alcanzan a leer las palabras \"alabar\", \"espíritu\" y \"tumba\".', 'El clima severo de Nazmir ha erosionado la mayoría de las escrituras de la tablilla. Solo se alcanzan a leer las palabras \"alabar\", \"espíritu\" y \"tumba\".', 28153),
(130979, 'esMX', 'Nuestros exploradores han informado que las fuerzas de la Horda se dirigen a Fuerte del Norte al amparo de la noche. ¡Necesitamos tu ayuda de inmediato!', '', 28153),
(130978, 'esMX', '', '¡Soldados de la Alianza! ¡Nuestro momento es ahora! El asalto a las Grandes Puertas de Mulgore comienza aquí y ahora. Cierren filas y peleen con valor.', 28153),
(130977, 'esMX', '', '¡Todos a los muelles!', 28153),
(130969, 'esMX', '', 'Ah, $p. Aquí estáh\', tal como G\'huun susurró. ¡Voy a disfrutarlo!', 28153),
(130967, 'esMX', '', 'Soldados de la séptima flota, ha llegado la hora de atacar. Recojan sus pertenencias y prepárense para marchar.', 28153),
(130947, 'esMX', '¿No ves que me muero de hambre?', '', 28153),
(130946, 'esMX', '¡Mamá, dame de comer!', '', 28153),
(130945, 'esMX', '%s te da cabezazos para demostrar su alegría.', '', 28153),
(130944, 'esMX', '', 'La muerte no es el fin para mí.', 28153),
(130943, 'esMX', '¿Quieres jugar a un juego? ¡Tú corres y yo trato de alcanzarte para comerte!', '', 28153),
(130940, 'esMX', '%s te mira con tristeza en los ojos.', '', 28153),
(130939, 'esMX', '%s se queja porque tiene hambre.', '', 28153),
(130938, 'esMX', '%s se queja y te golpea con fuerza con el hocico.', '', 28153),
(130937, 'esMX', 'El estómago de %s gruñe con fuerza.', '', 28153),
(130936, 'esMX', '%s te acaricia con el hocico con mucho afecto.', '', 28153),
(130935, 'esMX', '', 'No puedes derrotarno\' a todos. ¡Dazar\'alor caerá!', 28153),
(130934, 'esMX', 'Yo me encargaré de mis herido\'. Encontrémono\' en Raz\'lotec cuando hayas terminado y le pondremo\' punto final a este asedio.', '', 28153),
(130932, 'esMX', 'Eclosionando...', 'Eclosionando...', 28153),
(130931, 'esMX', '', '¡Te destriparé!', 28153),
(130930, 'esMX', '', '¡Te despellejaré!', 28153),
(130929, 'esMX', '', '¡Má\' sangre! ¡Má\' sangre!', 28153),
(130928, 'esMX', '', 'Mamá quiere tu sangre.', 28153),
(130927, 'esMX', '', 'Lindo\' huesos.', 28153),
(130926, 'esMX', '', 'Carne fresca y sangrienta.', 28153),
(130925, 'esMX', 'Uf... voy a necesitar una semana para regenerar toda\' estas heridas.', 'Uf... voy a necesitar una semana para regenerar toda\' estas heridas.', 28153),
(130924, 'esMX', '¡Los trols de sangre son uno\' salvajes!', '¡Los trols de sangre son uno\' salvajes!', 28153),
(130923, 'esMX', '¡Ja! No tendrán una gota de mi sangre.', '¡Ja! No tendrán una gota de mi sangre.', 28153),
(130922, 'esMX', 'Dijeron que iban a usar mi sangre.', 'Dijeron que iban a usar mi sangre.', 28153),
(130921, 'esMX', '¡Ja! Hoy no me llevarán a ningún lado, banda de salvajes.', '¡Ja! Hoy no me llevarán a ningún lado, banda de salvajes.', 28153),
(130920, 'esMX', 'Eh\'taban a punto de hacer un ritual. Sentí cómo me temblaban todos los huesos...', 'Eh\'taban a punto de hacer un ritual. Sentí cómo me temblaban todos los huesos...', 28153),
(130919, 'esMX', 'Me eh\'taban tallando símbolos en el brazo. Salvajes...', 'Me eh\'taban tallando símbolos en el brazo. Salvajes...', 28153),
(130918, 'esMX', '¡Eso e\'! Nadie se quedará con este trol.', '¡Eso e\'! Nadie se quedará con este trol.', 28153),
(130917, 'esMX', '¡Gracia\'! Muchísimas gracias.', '¡Gracia\'! Muchísimas gracias.', 28153),
(130915, 'esMX', 'Alto el fuego. ¡Llegaron los refuerzo\'!', '', 28153),
(130914, 'esMX', '', '¡Vamo\', colega! ¡Que comience la cacería!', 28153),
(130913, 'esMX', '', '¡Ven! La eclosión comenzará pronto.', 28153),
(130907, 'esMX', 'Estoy listo.', 'Estoy lista.', 28153),
(130906, 'esMX', '', 'Bienvenido al Redil de Bestias de Guerra, $n.\n\nHe oído sobre tu Horda, y sé que has venido a este sitio para hacer un trato con el viejo Rastakhan.\n\nYa veremo\' si eres útil. Quizá entonce\' hablaremo\' bien de ti en los Peldaños de Dazar, mmm...', 28153),
(130905, 'esMX', 'Si encuentro al que te hizo eh\'to, amigo...', '', 28153),
(130904, 'esMX', 'Lo\' trol de sangre juegan sucio.', '', 28153),
(130903, 'esMX', 'Magias oscuras. Esto no e\' natural.', '', 28153),
(130902, 'esMX', '¿Con qué te han maldecido, amigo?', '', 28153),
(130901, 'esMX', 'Vamo\', amigo. Tú puedes.', '', 28153),
(130900, 'esMX', '¡Mantengan la formación! Traigan a los muerto\' y a los herido\', pero mantengan la formación.', '', 28153),
(130899, 'esMX', '¡Miren los cielo\'! Se acercan mas panzangrienta\'.', '', 28153),
(130898, 'esMX', 'Ustede\' son zandalari. ¡Luchen como tales!', '', 28153),
(130897, 'esMX', '¡Que los herido\' se pongan de pie! No dejen que estos salvaje\' se queden con la vida de nadie.', '', 28153),
(130896, 'esMX', '¡Resistan, hermanos y hermanas! ¡Hoy no caeremo\' ante estos salvaje\'!', '', 28153),
(130842, 'esMX', 'Otórgales una potenciación a todos.', 'Otórgales una potenciación a todos.', 28153),
(130841, 'esMX', '', 'Quizá seas más fuerte de lo que aparenta\'. Mi campeón no te tratará nada bien. Desafíalo cuando esté\' $ulisto:lista; para comenzar.', 28153),
(130840, 'esMX', '', 'No esperaba que una novata fuera un desafío para ti. Veamo\' cómo te va contra un rival má\' fuerte.', 28153),
(130839, 'esMX', 'Puedo proporcionarte potenciaciones y beneficios que te serán de ayuda en el frente de batalla.', '', 28153),
(130838, 'esMX', '', '¿Está\' $Upreparado:preparada; de verdad para aceptar un compromiso tan grande? Aún puede\' reconsiderar.', 28153),
(130822, 'esMX', '¡Están ascendiendo a nuevos generales!', '¡Están ascendiendo a nuevos generales!', 28153),
(130797, 'esMX', '', 'Ere\' persistente, eso tengo que admitirlo. Es hora de conocer a la matriarca Jaz\'lith. Ven.', 28153),
(130796, 'esMX', '', '¿Está\' $ulisto:lista; para poner las necesidade\' de tu cría por delante de las tuya\'? ¿Tiene\' idea de lo mucho que comen?', 28153),
(130795, 'esMX', 'Los lazo\' con nuestras bestias comienzan durante la incubación y duran toda la vida. Son nuestra familia.', 'Los lazo\' con nuestras bestias comienzan durante la incubación y duran toda la vida. Son nuestra familia.', 28153),
(130794, 'esMX', '', 'Lo\' cuernoatroz son herbívoro\', ¡así que no trates de darle\' carne!', 28153),
(130793, 'esMX', 'Las crías son muy particulare\' para elegir con quién crear un vínculo. ¡Es un misterio por qué ha elegido a $uun forastero:una forastera; como tú!', 'Las crías son muy particulare\' para elegir con quién crear un vínculo. ¡Es un misterio por qué ha elegido a $uun forastero:una forastera; como tú!', 28153),
(130732, 'esMX', '', 'Ah, Hir\'eek, el loa murciélago... Debe eh\'tar en algún lugar de Nazmir. Ese loa ah\'tuto sabrá cómo detener eh\'to.', 28153),
(130731, 'esMX', '', 'Puedo sentir su poder... Está cerca. Más cerca que los\' demás loa.', 28153),
(130730, 'esMX', '', 'Bwonsamdi... el loa de la muerte. Un loa poderoso, pero ah\'tuto y peligroso... Se la pasa tramando pactos.', 28153),
(130710, 'esMX', '', 'El loa rana, Krag\'wa... ¡eh\'tá en Nazmir! Krag\'wa es un loa poderoso que no tolerará la maldad de lo\' trols de sangre.', 28153),
(130707, 'esMX', 'Así que haremos un trato con el loa de la muerte, el loa tortuga, el loa murciélago, el loa rana... todo para detener a lo\' trols de sangre.', '', 28153),
(130705, 'esMX', '', 'Necesitamo\' más poder para detener a los trols de sangre. Solo queda una opción: lo\' loa de Nazmir.', 28153),
(130692, 'esMX', '', '<Te observa... de manera sugestiva.>', 28153),
(130625, 'esMX', '', 'Talanji habla sobre conseguir el apoyo limitado de algunos contactoh\' en Zuldazar mientras el jugador busca la ayuda del loa olvidado.', 28153),
(130566, 'esMX', '', 'CINEMÁTICA/VISIÓN AÉREA. ¡Ves el superensamblaje del titán corrupto! La matriarca de sangre nota tu presencia y lanza un hechizo de captura sobre Talanji.', 28153),
(130494, 'esMX', '', '¡Libre! Debemo\' irnos, ¡súbete!', 28153),
(130490, 'esMX', '', 'Más de mis soldado\', pero el camino continúa. Y debemos seguirlo.', 28153),
(130485, 'esMX', '', 'Mi pueblo... ¡ha sido masacrado! Ahora ves el mal al que nos enfrentamo\', $n. ¡Lo\' trols de sangre son monstruos!', 28153),
(130383, 'esMX', '', 'Tus consejo\' son sabios, Rokhan. Pero ahora debemos actuar, no eh\'perar. Hay que detener a los trols de sangre.', 28153),
(130372, 'esMX', '', 'Sé $Urápido:rápida; y letal. Zul y yo te eh\'peraremos en las eh\'caleras de la pirámide. Te aseguro que las verás.', 28153),
(130361, 'esMX', '', 'Si sobrevives, ven a verno\' en la entrada de la Calle Barril. Quizá tenga un encargo para ti.', 28153),
(130353, 'esMX', 'Nunca ante\' había puesto un pie en Zandalar. Zuldazar es más grandiosa que todo lo que había visto hasta el día de hoy.$b$bTen cuidado, colega. Quizá los zandalari parezcan formale\' y correctos, pero no dejan de ser trols. La sociedad de los trols no perdona a lo\' débiles.', '', 28153),
(130352, 'esMX', 'La princesa Talanji te eh\'pera al final de eh\'tos muelles. No pierdas tiempo, no entres a la ciudad antes de que se hayan llevado a cabo los rituale\' si no quiere\' recibir la pena de muerte.\n\nDejarás el cadáver parlanchín aquí hasta el que rey diga lo contrario.', '', 28153),
(130121, 'esMX', '', 'Como desees.', 28153),
(130120, 'esMX', 'Responderás ante ella por tus crímenes contra Kul Tiras.', '', 28153),
(130119, 'esMX', 'Te llevaremos con Katherine, así es.', '', 28153),
(130099, 'esMX', '<Charla breve en la que me río de Zul y lo menosprecio; le digo a mi hija que abandonó su puesto>', '', 28153),
(130096, 'esMX', 'Debería\' saber que nuestro rey ha sobrevivido a ciento veintitré\' intento\' de asesinato.$b$bLas cabeza\' de quienes intentaron asesinarlo ahora adornan la sala del trono.', '', 28153),
(130081, 'esMX', '', '¿Está\' esperando para ver al rey? Bueno, golpea el gong y te enviaremo\' un desafío digno de tu valía.', 28153),
(130079, 'esMX', '', 'Acepta tu bendición y vete. Si vuelves, dejaráh\' de existir.', 28153),
(130075, 'esMX', '', '¿Cómo está el viejo Vol\'jin? Muerto, según me han contado. Qué pena. Alguno\' de nosotro\' habíamos soñado con matarlo con nuestra\' propia\' manos.', 28153),
(130032, 'esMX', 'Habla rápido y vete de aquí, $r. Lo\' Amani no nos olvidamo\' de que fue tu Horda la que mutiló y asesinó a nuestro amado Zul\'jin.\n\nPor respeto a lo\' zandalari, te daré una advertencia: esta embajada es parte de la nación amani. Si te queda\', este lugar será tu tumba.', '', 28153),
(130031, 'esMX', 'Toma mi bendición y vete de aquí. No hay lugar para tu Horda entre lo\' Amani.', '', 28153),
(130030, 'esMX', 'Qué valiente, colega. Creo que no entiende\' lo que te espera. Si derrotas a los discípulo\' que tengo aquí atrá\', saldrás de este lugar con mi bendición.', '', 28153),
(130003, 'esMX', '', '.', 28153),
(129998, 'esMX', '', 'Soy Jaina Valiente. He venido a pedir una audiencia con la Lady almirante Katherine Valiente... mi madre.', 28153),
(129993, 'esMX', '', 'Espero que esto funcione.', 28153),
(129983, 'esMX', '¡Ah! ¡No! ¡Gahz\'ragon! ¡Basura cruel de la Horda! ¡Toma tu bendición y vete de aquí!', '', 28153),
(129980, 'esMX', 'Ha habido grande\' cambios durante su ausencia, alteza. Rakera demostró ser demasiado débil para su puesto, por lo que me encargué de exiliarla a Vol\'dun como corresponde.', '', 28153),
(129979, 'esMX', '', 'Jakra\'zet. ¿Dónde eh\'tá la guardiana bélica Rakera?', 28153),
(129978, 'esMX', 'Eso es suficiente, escoria de la Horda.', '', 28153),
(129969, 'esMX', '[Loading screen -> IGC - Ship on open water, Jaina\'s nightmare, arrival at Boralus gates.]', '[Loading screen -> IGC - Ship on open water, Jaina\'s nightmare, arrival at Boralus gates.]', 28153),
(129968, 'esMX', '¿Quieres un desafío? Lo tendrá\'. Golpea el gong que está allí y te llenaremo\' la cara de desafíos.', '', 28153),
(129967, 'esMX', '<Iniciar el desafío>', '<Iniciar el desafío>', 28153),
(129966, 'esMX', 'Vaya, vaya. Hola, $r. Tu gente nos provocó mucho dolor a mí y a mi pueblo. ¿Qué quiere\'?', '', 28153),
(129965, 'esMX', '¡La Alianza no tolerará eh\'to!', '¡La Alianza no tolerará eh\'to!', 28153),
(129964, 'esMX', '¡Nueh\'tro Rey se enterará de esto!', '¡Nueh\'tro Rey se enterará de esto!', 28153),
(129963, 'esMX', 'Esta vez, ganah\' tú.', 'Esta vez, ganah\' tú.', 28153),
(129962, 'esMX', 'No te quedaráh\' con este lugar.', 'No te quedaráh\' con este lugar.', 28153),
(129961, 'esMX', '¡Volveremos!', '¡Volveremos!', 28153),
(129960, 'esMX', '¡Ya volverá\' a saber de nosotro\', $p!', '¡Ya volverá\' a saber de nosotro\', $p!', 28153),
(129959, 'esMX', '¡$C basura!', '¡$C basura!', 28153),
(129958, 'esMX', '¡Muere!', '¡Muere!', 28153),
(129957, 'esMX', '¡He oído hablar de ti, $p! Si te mato, me convertiré en héroe.', '¡He oído hablar de ti, $p! Si te mato, me convertiré en heroína.', 28153),
(129956, 'esMX', 'No me iré de aquí hasta que dejes de respirar.', 'No me iré de aquí hasta que dejes de respirar.', 28153),
(129955, 'esMX', 'Los zandalari no podrán aliarse contigo si ere\' un cadáver.', 'Los zandalari no podrán aliarse contigo si ere\' un cadáver.', 28153),
(129954, 'esMX', '¡No te librará\' de mí tan fácilmente!', '¡No te librará\' de mí tan fácilmente!', 28153),
(129953, 'esMX', '¡Basura de la Horda!', '¡Basura de la Horda!', 28153),
(129952, 'esMX', 'Ninguna basura de la Horda se unirá con lo\' zandalari.', 'Ninguna basura de la Horda se unirá con lo\' zandalari.', 28153),
(129951, 'esMX', 'Por orden de la princesa, quedas $gdesterrado:desterrada;. Vete o morirás.', 'Por orden de la princesa, quedas $gdesterrado:desterrada;. Vete o morirás.', 28153),
(129950, 'esMX', 'No me toque\', basura de la Horda.', 'No me toque\', basura de la Horda.', 28153),
(129949, 'esMX', 'Vaya, vaya... un miembro de la Horda en Zuldazar. Qué interesante.', 'Vaya, vaya... un miembro de la Horda en Zuldazar. Qué interesante.', 28153),
(129948, 'esMX', '¿Tú también busca\' esto? Porque yo lo vi primero y lo compraré, así que vete de aquí.', '¿Tú también busca\' esto? Porque yo lo vi primero y lo compraré, así que vete de aquí.', 28153),
(129947, 'esMX', '¿Qué quieres? Eh\'toy ocupado.', '¿Qué quieres? Eh\'toy ocupado.', 28153),
(129946, 'esMX', '¿Qué quiere\', basura de la Horda?', '¿Qué quiere\', basura de la Horda?', 28153),
(129944, 'esMX', '', 'Debo preparar mi nave. Adalid, te espero en el muelle cuando quieras partir.', 28153),
(129940, 'esMX', 'Mira, $Gintruso:intrusa;, tengo un regla: si quieres luchar, lucha afuera.\n\nSi respeta\' esa regla, puedes dormir aquí.\n\nAh, y no vayas a hablar de mí si ves algo extraño.', '', 28153),
(129883, 'esMX', '¡Ningún forastero puede entrar a Zuldazar hasta que yo haya probado su carne!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129881, 'esMX', 'Ve, mortal. Dile a la hija de Rastakhan que te doy mi permiso para entrar a la ciudad.', '', 28153),
(129880, 'esMX', 'Quiero entrar a la ciudad.', 'Quiero entrar a la ciudad.', 28153),
(129879, 'esMX', 'Hueles a algo nuevo y a algo que ya ha visto más de una batalla. Eres una presa interesante. ¿Por qué vienes hasta mí?', '', 28153),
(129660, 'esMX', '¡Adalid! El consejo de guerra está por reunirse. Se solicita tu presencia en el Castillo de Ventormenta.', '', 28153),
(128197, 'esMX', '¡He regresado de las profundidades!', '', 28153),
(128196, 'esMX', '¡Parece que hemos llegado! Pondremos a funcionar el detector mientras ustedes conocen la isla.', '', 28153),
(128195, 'esMX', 'Nos detendremos aquí, peones. Esperen, huelo la pestilencia de los HUMANOS. ¿Me oyen, humanos? ¡Esta isla le pertenece a Burgthok!', '', 28153),
(127581, 'esMX', 'Uoo, este clima no es normal en este entorno. Toda esta azerita debe haber captado la atención de un Señor elemental. Ten cuidado. O mátalo. ¡O las dos cosas!', '', 28153),
(127580, 'esMX', '', 'Los trabajadores se dirigen a excavar esa veta de azerita en este momento.', 28153),
(127579, 'esMX', '$n, nuestros exploradores han localizado varias islas ricas en azerita. Necesitamos tu navío de inmediato.', '', 28153),
(127578, 'esMX', '¡Alianza! La Luz nos ha otorgado esta isla. Váyanse, antes de que corra sangre. Esta es la última advertencia.', '', 28153),
(127577, 'esMX', '', '¡Saqueo y pillaje, ja, ja! Dorp, dispárale a todo lo que se mueva. Petey el Escurridizo, agujerea un poco a esas basuras de la Alianza. ¡Y tráiganme esa azerita!', 28153),
(127576, 'esMX', 'Hola, $Uamigo:amiga;. Tengo muchas cosas buenas aquí.', '', 28153),
(127575, 'esMX', '', '¡Tus aliados templeluz han llegado para ayudar!', 28153),
(127574, 'esMX', 'Hay algunas... eh, naves de la Horda cerca. Quizá sea mejor que aceleren un poco el ritmo.', '', 28153),
(127573, 'esMX', '¿Sí? Tenemos las órdenes, la azerita está esperando. Revisa la mesa y avísame cuando estés $Ulisto:lista; para que partamos.\n\nYa sé, es difícil dejar de mirarme, me lo dicen mucho, pero tenemos que concentrarnos.', '', 28153),
(127569, 'esMX', 'Reinicia la isla actual.', 'Reinicia la isla actual.', 28153),
(127568, 'esMX', 'Ya vamos por la mitad, equipo. No me decepcionen.', '', 28153),
(127501, 'esMX', '¡Tú! ¡Salvaste a Barbamugre! ¡Toma tesoros!', '', 28153),
(126508, 'esMX', '|cFF0EA6DC+$1i|r de |cFFFFFF00azerita|r', '|cFF0EA6DC+$1i|r de |cFFFFFF00azerita|r', 28153),
(124726, 'esMX', 'Descifrar las reglas', 'Descifrar las reglas', 28153),
(124724, 'esMX', 'Restablecer el juego', 'Restablecer el juego', 28153),
(124723, 'esMX', 'Comenzar juego', 'Comenzar juego', 28153),
(124717, 'esMX', '------------------------------$bDIFICULTAD MÁXIMA$b------------------------------$b\nLa consola vibra y silba cuando colocas la mano sobre ella. La pantalla central parpadea con una cascada interminable de glifos, la mayoría acompañados por calaveras o rostros con una X sobre los ojos. Hay tiempo adicional en este nivel, pero uno de los temporizadores bonificados tiene una trampa.$b$bSuena una música alegre. ¿Es la forma de la consola de desearte buena suerte con el desafío más difícil? ¿O se está despidiendo?', '', 28153),
(124716, 'esMX', '---------------$b   NIVEL 4$b---------------$b\nLa consola responde a tu toque, que ya conoce, con una serie de patrones lumínicos hexagonales y música alegre.$b$bEs difícil interpretar los símbolos antiguos que atraviesan la pantalla central, pero lo que logras comprender del siguiente nivel de dificultad es que la mayoría de los jugadores que lo intentan sufren una muerte morbosa.$b$bLa buena noticia es que una de las maldiciones contiene tiempo adicional.', '', 28153),
(124715, 'esMX', '---------------$b   NIVEL 3$b---------------$b\nLa consola te da una cálida bienvenida, a pesar de sus repetidos intentos de asesinato.$b$bLos símbolos relacionados con el siguiente nivel de desafío parecen indicar que te esperan menos pistas, menos tiempo y más minas.', '', 28153),
(124714, 'esMX', '---------------$b   NIVEL 2$b---------------$b\nLa consola se ilumina y zumba, y te reconoce en cuanto apoyas la mano. Parece que las reglas han cambiado, y los pictogramas indican que ahora también hay un temporizador.$b$bAhora el castigo por no completar el desafío a tiempo es el dolor en lugar de la muerte. Eso es bueno.', '', 28153),
(124713, 'esMX', 'Haces tu mejor esfuerzo por interpretar los pictogramas e ignoras las advertencias constantes sobre una muerte instantánea.$b$bLa consola del Arcaminas generará una red hexagonal que detecta las pisadas. Varios de los hexágonos están \"minados\" y harán polvo al jugador. En contraposición, pisar un mosaico \"seguro\" revelará la cantidad de minas adyacentes.$b$bEl objetivo es revelar todos los mosaicos seguros y marcar los peligrosos con banderitas blancas para \"despejar\" el campo.$b$bNo queda muy claro por qué el juego tiene la necesidad de matar a los jugadores que pisan el mosaico equivocado.', '', 28153),
(124711, 'esMX', '---------------$b   NIVEL 1$b---------------$b\nEsta misteriosa consola arcana se enciende en cuanto acercas la mano. Páginas y páginas de instrucciones pasan frenéticamente por el panel central. El idioma no es claro, pero la iconografía es evidente:$bMontones de calaveras.$b$bEsto es Arcaminas, un juego de lo más peligroso donde debes atravesar un campo de minas arcanas e identificar todas las áreas con trampas. La muerte instantánea es el precio del menor error.$b$bTe preguntas por qué alguien quería hacer esto por diversión.', '', 28153),
(124677, 'esMX', 'NIVEL 5', '', 28153),
(124676, 'esMX', 'NIVEL 4', '', 28153),
(124675, 'esMX', 'NIVEL 3', '', 28153),
(124674, 'esMX', 'NIVEL 2', '', 28153),
(124673, 'esMX', 'NIVEL 1', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(167308, 'frFR', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'frFR', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'frFR', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
(167305, 'frFR', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 28153),
(167304, 'frFR', 'I want to teleport to Temple of Sethraliss (Dungeon).', 'I want to teleport to Temple of Sethraliss (Dungeon).', 28153),
(167302, 'frFR', 'I want to teleport to Siege of Boralus (Dungeon).', 'I want to teleport to Siege of Boralus (Dungeon).', 28153),
(167301, 'frFR', 'I want to teleport to Shrine of the Storm (Dungeon).', 'I want to teleport to Shrine of the Storm (Dungeon).', 28153),
(167300, 'frFR', 'I want to teleport to Kings\' Rest (Dungeon).', 'I want to teleport to Kings\' Rest (Dungeon).', 28153),
(167299, 'frFR', 'I want to teleport to Freehold (Dungeon).', 'I want to teleport to Freehold (Dungeon).', 28153),
(167298, 'frFR', 'I want to teleport to Atal\'dazar (Dungeon).', 'I want to teleport to Atal\'dazar (Dungeon).', 28153),
(167297, 'frFR', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'frFR', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'frFR', 'Ville des Ombreforge', 'Ville des Ombreforge', 28153),
(162170, 'frFR', 'Vous ne pouvez pas négliger votre devoir, retournez à Darnassus !', 'Vous ne pouvez pas négliger votre devoir, retournez à Darnassus !', 28153),
(162169, 'frFR', '', 'L\’heure est-elle venue d\’en finir une bonne fois pour toutes, $n ?', 28153),
(162168, 'frFR', '<Voler jusqu\’à Dalaran>', '<Voler jusqu\’à Dalaran>', 28153),
(162167, 'frFR', 'Pouvez-vous guider Loh vers toutes les échoppes, puis jusqu\’à l\’auberge, sans emprunter deux fois le même chemin ?', '', 28153),
(162166, 'frFR', '', 'Allez-vous défendre les jeunes tortues qui tentent de rejoindre la mer ?', 28153),
(162165, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(162164, 'frFR', 'Bienvenue, $n. Pensez-vous pouvoir gagner à mon jeu d\’association de paires ?', '', 28153),
(162161, 'frFR', 'Souhaitez-vous vraiment passer le prologue de Sombrivage ?', 'Souhaitez-vous vraiment passer le prologue de Sombrivage ?', 28153),
(162160, 'frFR', 'Oui, $n ? On dirait que quelque chose vous préoccupe…', '', 28153),
(162159, 'frFR', '<Le marin perdu vous regarde sévèrement. Vous n\’avez rien à faire ici.>', '<Le marin perdu vous regarde sévèrement. Vous n\’avez rien à faire ici.>', 28153),
(162158, 'frFR', 'Je connais déjà cette histoire… <Passer les quêtes du prologue et commencer votre périple en Sombrivage.>', 'Je connais déjà cette histoire… <Passer le scénario et commencer votre prochaine mission.>', 28153),
(162157, 'frFR', 'Je vais vous ramener en sécurité, $n. Accrochez-vous !', '', 28153),
(162156, 'frFR', 'Craignez le courroux de la nature !', '', 28153),
(162155, 'frFR', 'Accrochez-vous à mes branches, $c.', '', 28153),
(162152, 'frFR', 'Nous allons nous assurer que cette azérite ne tombe pas entre les mains de l\’Alliance !', 'Nous allons nous assurer que cette azérite ne tombe pas entre les mains de la Horde !', 28153),
(162151, 'frFR', '|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t$n est dans des |cFFF00000|Hspell:260551|h[Épines de l\’âme]|h|r !', '', 28153),
(162150, 'frFR', 'Je souhaite soutenir les efforts de l\’Amirauté en Kul Tiras. <Vous obtenez la réputation amicale auprès de l\’Amirauté des Portvaillant.>', 'Je souhaite soutenir les efforts de l\’Amirauté en Kul Tiras. <Vous obtenez la réputation amicale auprès de l\’Amirauté des Portvaillant.>', 28153),
(162149, 'frFR', 'T\’es le meilleur, $n !', 'T\’es la meilleure, $n !', 28153),
(162148, 'frFR', '$n est en feu !', '$n est en feu !', 28153),
(162147, 'frFR', 'Donnez tout, $n !', 'Donnez tout, $n !', 28153),
(162146, 'frFR', 'You-hou !', 'You-hou !', 28153),
(162145, 'frFR', '$n ! $n ! $n !', '$n ! $n ! $n !', 28153),
(162144, 'frFR', 'C\’est $n ! $n est sur les planches !', 'C\’est $n ! $n est sur les planches !', 28153),
(162143, 'frFR', 'Montrez-leur, $n ! Youhou !', 'Montrez-leur, $n ! Youhou !', 28153),
(162142, 'frFR', 'Allez, $n !', 'Allez, $n !', 28153),
(162141, 'frFR', 'Ma forge est toujours prête, $n.', 'Ma forge est toujours prête, $n.', 28153),
(162140, 'frFR', 'Je vais rassembler toutes nos rations et faire les lits. Lok\’tag ogar !', 'Notre avant-poste n\’est pas bien grand, mais je réunirai tout ce dont nous disposons. Le chef de guerre et son armée ne manqueront de rien. Je vous en donne ma parole ! Lok\’tar ogar !', 28153),
(162139, 'frFR', 'L\’avant-poste de Zoram\’gar se tiendra prêt ! Pour la Horde !', 'L\’avant-poste de Zoram\’gar se tiendra prêt ! Pour la Horde !', 28153),
(162138, 'frFR', 'Le chef de guerre Sylvanas Coursevent a besoin de votre aide pour réparer les armes de ses soldats.', 'Le chef de guerre Sylvanas Coursevent a besoin de votre aide pour réparer les armes de ses soldats.', 28153),
(162137, 'frFR', '', 'Il existe un passage secret qui nous ramènera à l\’entrée du manoir.', 28153),
(162135, 'frFR', 'Retournez à la vallée du Crépuscule !', '', 28153),
(162134, 'frFR', '', 'Ils sont tout feu tout flamme ! Un accueil chaleureux pour les Nains sombrefer !', 28153),
(162133, 'frFR', '', 'Nul ne rivalise avec les Nains sombrefer pour enflammer la piste de danse !', 28153),
(162132, 'frFR', '', 'Quelle chorégraphie ! À croire qu\’ils débarquent d\’une autre planète ! Applaudissez les Mag\’har !', 28153),
(162131, 'frFR', '', 'Faites du bruit pour les Mag\’har !', 28153),
(162130, 'frFR', 'Montrez-moi nos options de recherche.', 'Montrez-moi nos options de recherche.', 28153),
(162129, 'frFR', 'Retournez à la Sinueuse !', '', 28153),
(162128, 'frFR', 'Retournez au Glaive du Maître !', '', 28153),
(162127, 'frFR', '', 'Si vous voulez que le boulot soit bien fait, utilisez de plus gros explosifs !', 28153),
(162123, 'frFR', '$n prépare un festin abondant du capitaine !', '$n prépare un festin abondant du capitaine !', 28153),
(162122, 'frFR', '$n prépare un banquet de galère !', '$n prépare un banquet de galère !', 28153),
(162121, 'frFR', 'Voulez-vous vraiment passer la Bataille de Lordaeron ?', 'Voulez-vous vraiment passer la Bataille de Lordaeron ?', 28153),
(162120, 'frFR', 'Je connais déjà cette histoire… <Passer le scénario et commencer votre prochaine mission.>', 'Je connais déjà cette histoire… <Passer le scénario et commencer votre prochaine mission.>', 28153),
(162119, 'frFR', '', 'Avec moi, mes sœurs ! Il est temps de défendre nos terres contre la Horde !', 28153),
(162118, 'frFR', '', 'Sombrivage est attaquée ! Prévenez la grande prêtresse sur-le-champ !', 28153),
(162117, 'frFR', 'Rassemblez nos alliés des forêts ! L\’Arbre-Monde doit être préservé !', '', 28153),
(162116, 'frFR', 'Sombrivage est attaquée ! Nous n\’avons pas une minute à perdre pour sauver notre forêt !', '', 28153),
(162110, 'frFR', 'Nous devons nous occuper du général Grebo.', 'Nous devons nous occuper du général Grebo.', 28153),
(162109, 'frFR', 'C\’est un plaisir.', '', 28153),
(162108, 'frFR', 'Les troupes de la Horde ont fait halte à la Sinueuse ! Nous devons les repousser sur-le-champ !', 'Les troupes de la Horde ont fait halte à la Sinueuse ! Nous devons les repousser sur-le-champ !', 28153),
(162107, 'frFR', 'J\’entends les tambours de guerre résonner dans la forêt. Les druides de la Griffe sont prêts à défendre cette terre contre tous ceux qui voudraient la détruire !', '', 28153),
(162106, 'frFR', 'Quelle puissance !', '', 28153),
(162105, 'frFR', 'Oui, c\’est parfait. C\’est exactement ce dont j\’avais besoin. Cela ne devrait prendre qu\’un instant.', '', 28153),
(162104, 'frFR', 'Je la sens… La puissance qui parcourt les fragments ! Elle est magnifique… et terrifiante.', '', 28153),
(162103, 'frFR', '', 'Il aura fallu le temps, mais les Sombrefer vont enfin sortir de la montagne et prendre leur juste place au sein de l\’Alliance.', 28153),
(162102, 'frFR', 'Vous croyez qu\’ils me laisseraient conduire mon char dans les rues de Hurlevent ?', '', 28153),
(162101, 'frFR', 'Les autres de l\’Alliance ont intérêt à s\’habituer à leur nouvel allié au tempérament de feu !', '', 28153),
(162100, 'frFR', 'J\’aime pas la façon dont les autres Nains me regardent, à Hurlevent.', 'J\’aime pas la façon dont les autres Nains me regardent, à Hurlevent.', 28153),
(162099, 'frFR', 'Toute cette lumière, là, quand on se retrouve à la surface, ça me plaît pas beaucoup.', 'Toute cette lumière, là, quand on se retrouve à la surface, ça me plaît pas beaucoup.', 28153),
(162098, 'frFR', 'Une maison, c\’est une maison. Une maison avec une fine couche de suie, c\’est un foyer.', 'Une maison, c\’est une maison. Une maison avec une fine couche de suie, c\’est un foyer.', 28153),
(162097, 'frFR', 'La fournaise de Rochenoire brûle pour l\’Alliance !', 'La fournaise de Rochenoire brûle pour l\’Alliance !', 28153),
(162096, 'frFR', 'Presque n\’importe quoi peut être réparé avec une clé à molette et de l\’huile de coude.', 'Presque n\’importe quoi peut être réparé avec une clé à molette et de l\’huile de coude.', 28153),
(162095, 'frFR', 'Les Sombrefer sont les seuls vrais Nains dignes de ce nom. Tous les autres clans ne sont qu\’un ramassis de mauviettes !', 'Les Sombrefer sont les seuls vrais Nains dignes de ce nom. Tous les autres clans ne sont qu\’un ramassis de mauviettes !', 28153),
(162094, 'frFR', 'La vraie force de la montagne, c\’est nous !', 'La vraie force de la montagne, c\’est nous !', 28153),
(162093, 'frFR', 'Pourquoi vous venez me parler ? Faites attention, j\’ai aucune patience !', 'Pourquoi vous venez me parler ? Faites attention, j\’ai aucune patience !', 28153),
(162089, 'frFR', 'Allez-vous-en !', '', 28153),
(162088, 'frFR', 'Ouste ! Vous n\’êtes pas les bienvenus dans notre tanière !', '', 28153),
(162087, 'frFR', 'Vous ne nous volerez pas notre foyer !', '', 28153),
(162086, 'frFR', 'Arrêtez ! De grâce ! Vous avez gagné…', '', 28153),
(162085, 'frFR', 'Vous avez gagné… Laissez-moi rassembler mon peuple et nous partirons.', '', 28153),
(162084, 'frFR', 'Arrêtez ! Je vous en prie ! Je me rends…', '', 28153),
(162082, 'frFR', '', 'L\’Alliance fraternise avec les Draeneï et leurs semblables empreints de Lumière.\n\nCette seule raison justifie de réduire ses villes en cendre.', 28153),
(162081, 'frFR', '', 'Il y a des Draeneï sur ce monde ?\n\n<Geya\’rah plisse les yeux.>\n\nPlus pour longtemps.', 28153),
(162080, 'frFR', '', 'Nous mettons nos lames au service de la Horde !', 28153),
(162079, 'frFR', '', 'Les Mag\’har se trouveront un nouveau foyer ici même, en Azeroth.', 28153),
(162078, 'frFR', '', 'Nous avons peut-être perdu Draenor, mais mon cœur me dit qu\’un jour, je reverrai ses cieux.\n\nAncêtres, faites que ce rêve se réalise !', 28153),
(162077, 'frFR', 'L\’écorchement ? C\’est une pratique barbare venue d\’une époque révolue. Tellement révolue que je ne saurais même pas par où commencer un tel rituel.\n\n<L\’Orc se rapproche de vous et vous murmure à l\’oreille.>\n\nEn fait, je sais exactement par où commencer. Vous êtes là pour une démonstration ?', 'L\’écorchement ? C\’est une pratique barbare venue d\’une époque révolue. Tellement révolue que je ne saurais même pas par où commencer un tel rituel.\n\n<L\’Orque se rapproche de vous et vous murmure à l\’oreille.>\n\nEn fait, je sais exactement par où commencer. Vous êtes là pour une démonstration ?', 28153),
(162076, 'frFR', 'Parfois, en regardant les Draeneï, je me demande s\’il y a des os dans les tentacules qu\’ils ont sur le visage. Parce que s\’ils en avaient, j\’en récolterais tout plein, je les coudrais ensemble et j\’en ferais des guirlandes que je pendrais aux murs de la forteresse, comme ça les visiteurs pourraient les admirer et dire « hé, regardez tous ces os de tentacules, je parie qu\’ils ont été récoltés par un Orc très très intelligent et talentueux », et alors là, moi, je dirais « oui, c\’est ce que ma maman m\’a toujours dit ».\n\nEuh, pardon, vous aviez une question à me poser ?', 'Parfois, en regardant les Draeneï, je me demande s\’il y a des os dans les tentacules qu\’ils ont sur le visage. Parce que s\’ils en avaient, j\’en récolterais tout plein, je les coudrais ensemble et j\’en ferais des guirlandes que je pendrais aux murs de la forteresse, comme ça les visiteurs pourraient les admirer et dire « hé, regardez tous ces os de tentacules, je parie qu\’ils ont été récoltés par un Orc très très intelligent et talentueux », et alors là, moi, je dirais « oui, c\’est ce que ma maman m\’a toujours dit ».\n\nEuh, pardon, vous aviez une question à me poser ?', 28153),
(162075, 'frFR', 'C\’est l\’heure de manger ? J\’espère que c\’est l\’heure de manger !\n\nDans un autre registre… Si vous deviez choisir un de vos membres à sacrifier, ce serait lequel ?', 'C\’est l\’heure de manger ? J\’espère que c\’est l\’heure de manger !\n\nDans un autre registre… Si vous deviez choisir un de vos membres à sacrifier, ce serait lequel ?', 28153),
(162074, 'frFR', '', '<Lasha scrute le sommet de votre crâne.>\n\nVous le trouvez comment, votre crâne ? Il est à votre taille ?\n\nEst-ce que votre esprit est libre… vide… ou partagé ?', 28153),
(162073, 'frFR', '', 'Les botani me manquent.\n\nQuand on les grillait juste à point, ils étaient DÉLICIEUX.\n\n<Lasha essuie un filet de bave de ses lèvres.>', 28153),
(162072, 'frFR', '', 'On va devoir attendre encore longtemps avant d\’embraser les Empreints de Lumière ?', 28153),
(162071, 'frFR', 'Bienvenue dans mon auberge, $gvoyageur épuisé:voyageuse épuisée;. Que puis-je faire pour vous ?', 'Bienvenue dans mon auberge, $gvoyageur épuisé:voyageuse épuisée;. Que puis-je faire pour vous ?', 28153),
(162070, 'frFR', 'Faites de cette auberge votre foyer.', 'Faites de cette auberge votre foyer.', 28153),
(162069, 'frFR', 'Ceux qui critiquent le chef de guerre Hurlenfer le paieront de leur vie !', 'Ceux qui critiquent le chef de guerre Hurlenfer le paieront de leur vie !', 28153),
(162068, 'frFR', 'C\’est le sol de NOTRE monde que vous foulez, pas le vôtre.\n\nSi jamais vous apportez la corruption ici, votre vie s\’achèvera très vite.', 'C\’est le sol de NOTRE monde que vous foulez, pas le vôtre.\n\nSi jamais vous apportez la corruption ici, votre vie s\’achèvera très vite.', 28153),
(162067, 'frFR', 'Si j\’attrape un de ces traîtres d\’Empreints de Lumière, je lui tranche la gorge !', 'Si j\’attrape un de ces traîtres d\’Empreints de Lumière, je lui tranche la gorge !', 28153),
(162066, 'frFR', 'On a vaincu les primordiaux. On fera pareil avec n\’importe quel adversaire.', 'On a vaincu les primordiaux. On fera pareil avec n\’importe quel adversaire.', 28153),
(162065, 'frFR', 'Draenor sera libre !', 'Draenor sera libre !', 28153),
(162064, 'frFR', 'Si vous gagnez la confiance du commandant, vous gagnerez la mienne.', 'Si vous gagnez la confiance du commandant, vous gagnerez la mienne.', 28153),
(162063, 'frFR', 'Le commandant Geya\’rah est le bras droit du chef de guerre. Il n\’y a pas d\’Orc plus brave sur tout Draenor.\n\nEt sur votre monde non plus, d\’ailleurs !', 'Le commandant Geya\’rah est le bras droit du chef de guerre. Il n\’y a pas d\’Orc plus brave sur tout Draenor.\n\nEt sur votre monde non plus, d\’ailleurs !', 28153),
(162062, 'frFR', '', 'Quand j\’étais petite, les professeurs draeneï m\’ont appris à lire et à écrire. Je les aimais bien. Je les respectais.\n\nEt puis, les Naaru sont arrivés, et avec eux, le fanatisme.\n\nLes Draeneï sont ressuscités… non, ils ont un mot pour ça : ils se sont reforgés dans leur précieuse Lumière.\n\nLeurs croyances les aveuglent, elles les asservissent à des maîtres qui veulent contrôler l\’univers tout comme la Légion a voulu le faire.\n\nDraeneï… Eredar… Ils sont tellement prompts à s\’agenouiller et à vénérer. Tellement enclins à la corruption.', 28153),
(162061, 'frFR', '', 'Grommash Hurlenfer nous a bien dirigés. Je le respecte autant que je respectais mon père.\n\nMais si jamais je revois son sale traître de rejeton…\n\n<Geya\’rah crache par terre.>\n\n… je le massacre.', 28153),
(162060, 'frFR', '', 'Draenor doit être débarrassée de l\’emprise des fanatiques et des tyrans.', 28153),
(162059, 'frFR', 'Jadis, des héros venus de votre monde m\’ont libéré du joug d\’un démon dans la citadelle des Flammes infernales. Est-ce que vous en faisiez partie ?\n\n<Grommash vous scrute fixement.>\n\nSi c\’est le cas, j\’ai une grande dette envers vous. Peut-être les esprits me montreront comment vous dédommager.', '', 28153),
(162058, 'frFR', 'Les Mag\’har ne se couchent devant personne. Même pas devant ceux qu\’ils appelaient leurs amis.', '', 28153),
(162057, 'frFR', 'Vous êtes bien loin de chez vous, $c. Vous remarquerez que la violence de notre monde ne s\’est pas apaisée depuis la dernière fois que votre race l\’a contemplé.', '', 28153),
(162047, 'frFR', '', 'Quels souvenirs puis-je vous rappeler aujourd\’hui ?', 28153),
(162046, 'frFR', 'En quoi le vieux T\’omkus il peut vous être utile ?', '', 28153),
(162045, 'frFR', 'Parlez-moi de la bataille de Lordaeron.', 'Parlez-moi de la bataille de Lordaeron.', 28153),
(162044, 'frFR', 'Parlez-moi de la confrontation dans la salle du trône.', 'Parlez-moi de la confrontation dans la salle du trône.', 28153),
(162043, 'frFR', 'Parlez-moi de la trahison de Portvaillant.', 'Parlez-moi de la trahison de Portvaillant.', 28153),
(162042, 'frFR', 'Parlez-moi du jugement de Jaina.', 'Parlez-moi du jugement de Jaina.', 28153),
(162041, 'frFR', 'Parlez-moi du cauchemar de Jaina.', 'Parlez-moi du cauchemar de Jaina.', 28153),
(162040, 'frFR', 'Parlez-moi du retour de Jaina à Theramore.', 'Parlez-moi du retour de Jaina à Theramore.', 28153),
(162039, 'frFR', 'Parlez-moi de la bataille de la pyramide.', 'Parlez-moi de la bataille de la pyramide.', 28153),
(162038, 'frFR', 'Parlez-moi du choix de Rastakhan.', 'Parlez-moi du choix de Rastakhan.', 28153),
(162037, 'frFR', 'Parlez-moi du retour de Talanji à Zuldazar.', 'Parlez-moi du retour de Talanji à Zuldazar.', 28153),
(162035, 'frFR', 'Nul ne devrait mourir ainsi.', 'Nul ne devrait mourir ainsi.', 28153),
(162034, 'frFR', 'Le froid commençait à m\’envahir…', 'Le froid commençait à m\’envahir…', 28153),
(162033, 'frFR', 'Je vous remercie.', 'Je vous remercie.', 28153),
(162032, 'frFR', 'Il vaudrait mieux que ce ne soit pas un piège. Nous avons encore besoin de vos services, $n.', '', 28153),
(162031, 'frFR', 'Je suis prêt à quitter Funesterre.', 'Je suis prête à quitter Funesterre.', 28153),
(162030, 'frFR', 'Je suis prêt à me rendre à Funesterre.', 'Je suis prête à me rendre à Funesterre.', 28153),
(162029, 'frFR', 'Par tous les… Pourquoi Magni Barbe-de-Bronze aurait-il besoin de vous ?', '', 28153),
(162025, 'frFR', 'Tu n\’as pas entendu ? La Horde a laissé le cadavre de Derek Portvaillant au port des Rapines. Dame Portvaillant a pratiquement envoyé toute la flotte pour récupérer la dépouille.', 'Tu n\’as pas entendu ? La Horde a laissé le cadavre de Derek Portvaillant au port des Rapines. Dame Portvaillant a pratiquement envoyé toute la flotte pour récupérer la dépouille.', 28153),
(162024, 'frFR', 'Il fait diablement calme, aujourd\’hui. Où est passé tout le monde ?', 'Il fait diablement calme, aujourd\’hui. Où est passé tout le monde ?', 28153),
(162023, 'frFR', '', 'Laroche semble évoluer de manière encourageante.\n\nLe moment venu, je gage qu\’elle se montrera une alliée des plus loyales.', 28153),
(162021, 'frFR', '', 'C\’était… stimulant de voir ces gens subir le sort qu\’ils méritaient.\n\nEst-ce que c\’est ça, être libre ? On peut fixer ses propres règles ?\n\nSi c\’est ça, je pense que je pourrais m\’y faire.', 28153),
(162020, 'frFR', '', 'Amalia semble réagir relativement bien.\n\nL\’épreuve qu\’elle traverse n\’est pas agréable, mais elle supporte mieux sa transformation que je ne l\’ai pu. À l\’époque, je tuais presque systématiquement ceux qui osaient m\’importuner. Amalia ne fait que se renfermer sur elle-même.\n\nAvec le temps, elle acceptera son état. Faites-moi confiance.', 28153),
(162019, 'frFR', 'L\’ennemi se rapproche ! Faites-lui mordre la poussière !', '', 28153),
(162018, 'frFR', 'Allez, les gars ! On continue d\’envoyer la sauce !', '', 28153),
(162017, 'frFR', 'Vous céderez… Il s\’élève… Il s\’élève…', '', 28153),
(162016, 'frFR', '', 'Fichez-moi la paix. Je n\’ai rien à vous dire.', 28153),
(162015, 'frFR', 'Le maître a faim… Le Cœur nourrira son rêve éveillé…', '', 28153),
(162014, 'frFR', 'Les Zandalari, ils vénèrent ce vieux Bwonsamdi depuis longtemps, tout comme les Sombrelances.\n\nRegardez cette statuette de Bwonsamdi que j\’ai achetée dans le port. Elle est magnifique ! Mieux faite que la plupart de celles que j\’ai vues au pays.\n\nLes Sombrelances et les Zandalari, ils ont beaucoup de différences, mais on a encore plus de ressemblances.\n\nSi un jour, les Zandalari, ils enlèvent le bâton qu\’ils ont dans le derrière, je crois qu\’on pourrait devenir bons amis !', 'C\’est quand, notre prochaine chasse, $p ?\n\nDe toute ma vie en Azeroth, ça a jamais manqué, les monstres à tuer.', 28153),
(162013, 'frFR', '', 'Non ! Notre foyer…', 28153),
(162012, 'frFR', '', 'Vous ne ferez pas un pas de plus, $R ! Tor ilisar\’thera\’nal !', 28153),
(162011, 'frFR', 'Il est trop tard… imbéciles…', '', 28153),
(162010, 'frFR', 'Nous allons raser ce qu\’il reste de ce village et nous débarrasser de vous une bonne fois pour toutes !', '', 28153),
(162009, 'frFR', 'J\’ai appris que les Zandalari adoraient un Loa pterreurdactyle.\n\nUn dieu reptile… qui vole !\n\n<Une étincelle semble s\’allumer dans les yeux de Lasan.>\n\nAviash est prêt à affronter leurs meilleurs chevaucheurs. Dans une course. Ou mieux, dans un combat !\n\nÇa fait pas de différence. On les battra dans les deux cas !\n\nHa ha ha ha ha ha ha !', 'Quand repartons-nous en chasse, $p ?\n\nDe toute ma vie, je n\’ai jamais entendu parler d\’une pénurie de monstres à tuer en Azeroth.', 28153),
(162008, 'frFR', 'Quel est votre plan, Nathanos ?', 'Quel est votre plan, Nathanos ?', 28153),
(162007, 'frFR', 'Très bien. $n, dites à Voguenille que nous sommes prêts à partir.', '', 28153),
(162006, 'frFR', 'Et la Horde va s\’emparer de ce sceptre.', '', 28153),
(162005, 'frFR', 'Cet artéfact est maintenu sous bonne garde en plein cœur de Boralus, la capitale de Kul Tiras.', '', 28153),
(162004, 'frFR', 'Détenir le sceptre abyssal, c\’est pouvoir commander à la puissance même de la mer et des tempêtes.', '', 28153),
(162003, 'frFR', 'Le sceptre abyssal.', '', 28153),
(162002, 'frFR', 'La maison Chantorage — autrefois, mes frères eaugures — possède un puissant artéfact.', '', 28153),
(162001, 'frFR', 'Oui, Flétrisseur.', '', 28153),
(162000, 'frFR', 'Zelling, auriez-vous l\’amabilité de répondre pour moi ?', '', 28153),
(161999, 'frFR', 'Regardez la taille de ces dinosaures !\n\n<Ji soupire mélancoliquement.>\n\nJ\’ai hâte d\’en cogner un.', 'Quand aura lieu notre prochaine chasse, $p ?\n\nDe ma vie, je n\’ai vu de pénurie de monstres à terrasser en Azeroth.', 28153),
(161998, 'frFR', 'Rivage Brisé', 'Rivage Brisé', 28153),
(161997, 'frFR', 'Caveau de Neltharion', 'Caveau de Neltharion', 28153),
(161996, 'frFR', 'Plateau Élémentaire', 'Plateau Élémentaire', 28153),
(161995, 'frFR', 'Surplomb de la fonderie des Rochenoires', 'Surplomb de la fonderie des Rochenoires', 28153),
(161994, 'frFR', 'Brasserie Brune d\’Orage', 'Brasserie Brune d\’Orage', 28153),
(161993, 'frFR', 'Monofu', 'Monofu', 28153),
(161992, 'frFR', 'J\’ai pris part à de nombreuses guerres. J\’ai vu des héros et des lâches se vider de leur sang sur le champ de bataille.\n\nMais cette guerre s\’annonce… différente.\n\nElle ne met pas seulement nos bras et notre intelligence du combat à l\’épreuve. Elle teste notre âme. Notre foi les uns envers les autres.\n\nQuoi qu\’il arrive, la Horde survivra.\n\nElle le doit.', 'Quand repartons-nous en chasse, $p ?\n\nDe toute ma vie, je n\’ai jamais entendu parler d\’une pénurie de monstres à exterminer en Azeroth.', 28153),
(161991, 'frFR', 'Sanctuaire draconique Rubis', 'Sanctuaire draconique Rubis', 28153),
(161990, 'frFR', 'Enceinte du tournoi d\’Argent', 'Enceinte du tournoi d\’Argent', 28153),
(161989, 'frFR', 'Skald', 'Skald', 28153),
(161988, 'frFR', 'Les Gangrefosses', 'Les Gangrefosses', 28153),
(161987, 'frFR', 'Bastion de l\’Honneur', 'Bastion de l\’Honneur', 28153),
(161986, 'frFR', 'La Grande division', 'La Grande division', 28153),
(161985, 'frFR', 'Le Trône des Flammes', 'Le Trône des Flammes', 28153),
(161984, 'frFR', 'Crête de la Fournaise', 'Crête de la Fournaise', 28153),
(161983, 'frFR', 'La Maçonnerie', 'La Maçonnerie', 28153),
(161982, 'frFR', 'Nid-de-l\’Aigle', 'Nid-de-l\’Aigle', 28153),
(161981, 'frFR', 'Rempart-du-Néant', 'Rempart-du-Néant', 28153),
(161980, 'frFR', 'Hurlevent', 'Hurlevent', 28153),
(161979, 'frFR', 'Forgefer', 'Forgefer', 28153),
(161978, 'frFR', 'Zandalar', 'Zandalar', 28153),
(161977, 'frFR', 'Kul Tiras', 'Kul Tiras', 28153),
(161976, 'frFR', 'Îles Brisées', 'Îles Brisées', 28153),
(161975, 'frFR', 'Norfendre', 'Norfendre', 28153),
(161974, 'frFR', 'Pandarie', 'Pandarie', 28153),
(161973, 'frFR', 'Draenor', 'Draenor', 28153),
(161972, 'frFR', 'Outreterre', 'Outreterre', 28153),
(161971, 'frFR', 'Kalimdor', 'Kalimdor', 28153),
(161970, 'frFR', 'Royaumes de l\’Est', 'Royaumes de l\’Est', 28153),
(161969, 'frFR', 'Quelque chose n\’est digne de valeur que si ça peut rentrer dans une boîte.\n\nÀ part les gens, bien sûr ! Essayez de mettre $p dans une boîte, pour voir. Hah !\n\n<Hobart se perd dans ses pensées pendant un moment.>\n\nOù en étais-je ? Ah, oui, Il me reste quelques petits ajustements à faire sur cette combinaison. Bientôt, elle sera de nouveau opérationnelle… avec quelques surprises explosives en bonus !', 'Quand est-ce qu\’on se remet en chasse, $p ?\n\nJ\’ai pas mal bourlingué en Azeroth et je n\’ai jamais vu de pénurie de monstres à zigouiller.', 28153),
(161968, 'frFR', 'Cette colline ne me verra pas mourir, George.', '', 28153),
(161967, 'frFR', 'Battez-vous avec Jeph et préparez-vous à mourir !', '', 28153),
(161966, 'frFR', 'Votre fille a été emmenée à Funesterre.', 'Votre fille a été emmenée à Funesterre.', 28153),
(161965, 'frFR', 'Et voilà ! On l\’a pas raté, ce sac de tentacules !', '', 28153),
(161964, 'frFR', 'Un désert ? Comme c\’est… cocasse.', '', 28153),
(161963, 'frFR', 'Vous m\’avez fait mander, je suis là, Verroctone.', '', 28153),
(161962, 'frFR', 'C\’est parti pour…', '', 28153),
(161961, 'frFR', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t Placez-vous dans l\’|cFFFF0000|Hspell:267334|h[Orbe de corruption]|h|r pour le renvoyer dans les airs !', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t Placez-vous dans l\’|cFFFF0000|Hspell:267334|h[Orbe de corruption]|h|r pour le renvoyer dans les airs !', 28153),
(161960, 'frFR', 'Feu !', 'Feu !', 28153),
(161959, 'frFR', 'Canon armé ! C\’est quand vous voulez !', '', 28153),
(161958, 'frFR', 'Maintenez ce bestiau à distance pendant que j\’arme le canon !', '', 28153),
(161957, 'frFR', '|cFF0000FF(Quête)|r Je suis prêt à me rendre sur Draenor.', '|cFF0000FF(Quête)|r Je suis prête à me rendre sur Draenor.', 28153),
(161956, 'frFR', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s vous cible avec |cFFFF0000|Hspell:259720|h[Soulèvementl]|h|r !', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s vous cible avec |cFFFF0000|Hspell:259720|h[Soulèvement]|h|r !', 28153),
(161955, 'frFR', 'Voilà la dernière clé !', 'Voilà la dernière clé !', 28153),
(161954, 'frFR', 'Je suis prêt à partir à la recherche de l\’écho de Garrosh.', 'Je suis prête à partir à la recherche de l\’écho de Garrosh.', 28153),
(161953, 'frFR', 'Je ne vous aiderais pas à accomplir cette tâche si je ne l\’estimais pas importante.', '', 28153),
(161952, 'frFR', 'Taisez-vous, à la fin ! Inutile de le crier sur tous les toits !', 'Nous aurions dû partir hier.', 28153),
(161950, 'frFR', 'C\’est pas comme ça que je voyais les choses se passer !', '', 28153),
(161949, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t Le disperseur de foule automatique utilise |cFFFF0000|Hspell:256214|h[Lancement de bomballe]|h|r !', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t Le disperseur de foule automatique utilise |cFFFF0000|Hspell:256214|h[Lancement de bomballe]|h|r !', 28153),
(161948, 'frFR', 'Votre éclat gagne en puissance, $p.', '', 28153),
(161947, 'frFR', 'Ces lieux sont encore souillés par son odeur pestilentielle. Finissez-en au plus vite.', '', 28153),
(161946, 'frFR', 'Notre mission est terminée, $p. Oculeth, votre télémancien en chef, vous attend à Zuldazar.', '', 28153),
(161945, 'frFR', '', 'Tant que tu remplis ta part du contrat…', 28153),
(161944, 'frFR', 'D\’accord ! Nous avons un marché ! Sans rancune ?', '', 28153),
(161943, 'frFR', '', 'Cinquante. À moins que tu préfères perdre la moitié de tes dents.', 28153),
(161942, 'frFR', 'Écoute, pose cette pioche et je te céderai une part des profits sur l\’argent. Vingt pour cent et on n\’en parle plus.', '', 28153),
(161941, 'frFR', 'Je ne vois pas de quoi tu parles…', '', 28153),
(161940, 'frFR', '', 'Tu es parti avec les gardes alors qu\’on te criait après !', 28153),
(161939, 'frFR', 'Houlà, du calme ! Comment aurais-je pu savoir qu\’il y avait des survivants ?', '', 28153),
(161938, 'frFR', '', 'Espèce de lâche ! Tu nous as abandonnés à notre sort !', 28153),
(161937, 'frFR', 'Mon prochain passage sera gagnant !', 'Mon prochain passage sera gagnant !', 28153),
(161936, 'frFR', 'J\’espère que vous êtes $gprêt:prête; à monter !', '', 28153),
(161935, 'frFR', '', 'Si vous voulez bien m\’excuser, ma pioche et moi avons des comptes à régler avec Salpiège…', 28153),
(161934, 'frFR', '', 'Merci encore pour votre aide, $gétranger:étrangère;.', 28153),
(161933, 'frFR', 'Expéditions débloquées', '', 28153),
(161932, 'frFR', 'Ils ont essayé de revendre ces horreurs en les faisant passer pour de la nourriture !', 'Refermez bien ces caisses, qu\’on puisse nettoyer tout ce bazar !', 28153),
(161931, 'frFR', 'Bataille de Stromgarde débloquée', '', 28153),
(161930, 'frFR', 'Je hais ces moutards !', 'Débarrassez-nous de ces saletés !', 28153),
(161929, 'frFR', 'Ce sont ces sales petits morveux qui ont ramené ces choses au village !', 'Encore une riche idée de ces gamins qui a mal tourné !', 28153),
(161928, 'frFR', '|TInterface\\ICONS\\INV_Misc_Bell_Green:20|t Raal le Bâfreur commence à lancer |cFFFF0404|Hspell:264931|h[Appel de serviteur]|h|r !', '', 28153),
(161927, 'frFR', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dame Malvoie commence à lancer |cFFFF0404|Hspell:268306|h[Cadence discordante]|h|r !', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dame Malvoie commence à lancer |cFFFF0404|Hspell:268306|h[Cadence discordante]|h|r !', 28153),
(161926, 'frFR', 'Vous avez réussi ! Azeroth a gagné en force… et vous aussi !', '', 28153),
(161925, 'frFR', 'Un serviteur des Dieux très anciens ! Le Cœur d\’Azeroth est assez fort pour l\’expulser ! Utilisez le Cœur, $n !', '', 28153),
(161924, 'frFR', 'Exploration des îles débloquée', '', 28153),
(161923, 'frFR', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Utilisez |cFFFF0404|Hspell:263235|h[Festin sanglant]|h|r pour vous débarrasser de vos charges de |cFFFF0404|Hspell:263227|h[Sanie]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Utilisez |cFFFF0404|Hspell:263235|h[Festin sanglant]|h|r pour vous débarrasser de vos charges de |cFFFF0404|Hspell:263227|h[Sanie]|h|r.', 28153),
(161922, 'frFR', 'Élevez-vous au-dessus de la tempête. Laissez les autres se faire tremper.', '', 28153),
(161921, 'frFR', '', 'Nous avons réussi ! Allons annoncer la bonne nouvelle au roi à Hurlevent.', 28153),
(161920, 'frFR', '', 'Vu qu\’on réparait l\’Enclume noire, on s\’est dit que c\’était l\’occasion d\’améliorer deux, trois trucs.', 28153),
(161919, 'frFR', '', 'Je continuerai à traquer l\’ennemi jusqu\’à ce que nous ayons gagné cette guerre, $n.\n\nC\’est le vœu que je fais en mémoire de tous ceux qui sont tombés à Teldrassil.\n\n<Shandris courbe la tête et se met en prière.>', 28153),
(161918, 'frFR', '', 'Chevauchez les courants ! Bravez la tempête !', 28153),
(161917, 'frFR', 'Retourner à la porte de Sang.', 'Retourner à la porte de Sang.', 28153),
(161916, 'frFR', 'Je peux pas dire que j\’aime beaucoup les bateaux en général, mais j\’admire ce que vous avez en réserve ici.\n\nSi vous trouvez d\’autres vieilles reliques dignes d\’intérêt, je serai ravi d\’y jeter un coup d\’œil.\n\nEt des portes. Des portes mystérieuses. Les portes mystérieuses des titans, c\’est mon dada !', '', 28153),
(161915, 'frFR', '', 'Halford garde des notes assez intéressantes, ici. Des rapports de guerre, des mouvements de troupes…\n\n<Kelsey jette un coup d\’œil à l\’encadrement de la porte et s\’approche pour murmurer à votre oreille.>\n\nEt je crois même que je sais où il cache son journal intime !\n\n<Kelsey vous fait un clin d\’œil entendu.>', 28153),
(161914, 'frFR', '', 'Vous ne songez tout de même pas à partir sans vos camarades ?', 28153),
(161913, 'frFR', 'Quel plaisir de se battre à nouveau aux côtés de solides et honnêtes guerriers de l\’Alliance. Ça me rappelle le bon vieux temps de la compagnie Bravo.\n\n<Les yeux de Keeshan semblent se perdre très loin dans le vague.>\n\nGardez toujours votre arme à portée de main, $n. Et cachez-en une autre sur vous au cas où vous vous feriez capturer. Dans un endroit qu\’ils ne fouilleront pas, de préférence.', '', 28153),
(161912, 'frFR', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Fluxifuge lance |cFFFF0000|Hspell:259940|h[Déflagration de propulseur]|h|r !', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Fluxifuge lance |cFFFF0000|Hspell:259940|h[Déflagration de propulseur]|h|r !', 28153),
(161911, 'frFR', 'Les miens se sont entraînés à la maîtrise de leurs capacités.\n\n<Umbric plisse les yeux.>\n\nLes murmures évoquent une foule de possibilités. Quoi qu\’il arrive, nous serons prêts.', '', 28153),
(161910, 'frFR', 'J\’étais un peu sceptique au début, mais tout semble fonctionner à merveille.', '', 28153),
(161909, 'frFR', 'Y a pas meilleur jour pour être Sombrefer !', '', 28153),
(161908, 'frFR', '', 'À vous l\’honneur de donner le dernier coup, $P.', 28153),
(161907, 'frFR', '', 'Être à nouveau sur le front est un vrai plaisir, $n. Mais je dois bien avouer que jouer les infirmières commence à m\’ennuyer. Mes talents pourraient être bien mieux employés.\n\nNombre de techniques que nous autres Sancteforge avons employées contre la Légion seraient aussi efficaces contre la Horde.\n\nVeuillez informer le haut-commandant que je serais ravie de veiller à ce que tout prisonnier que nous capturons soit… « purifié » en bonne et due forme.', 28153),
(161906, 'frFR', '', 'Que Jaina Portvaillant soit retournée dans son foyer ne me surprend pas.\n\nUne plaie vive ne se referme jamais si elle n\’est pas traitée. Et la sienne est grave et profonde.', 28153),
(161905, 'frFR', 'Le gardien du cœur se positionne pour vous attaquer !', 'Le gardien du cœur se positionne pour vous attaquer !', 28153),
(161904, 'frFR', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerekpha s\’apprête à vous jeter du |cFFFF0000|Hspell:263914|h[Sable aveuglant]|h|r, détournez le regard !', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerekpha s\’apprête à vous jeter du |cFFFF0000|Hspell:263914|h[Sable aveuglant]|h|r, détournez le regard !', 28153),
(161903, 'frFR', '', 'Prévenez-moi quand vous voudrez rejoindre les profondeurs de Rochenoire, $n.', 28153),
(161902, 'frFR', '', 'Vous savez ce qu\’il nous reste à faire, $n. En route.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161901, 'frFR', '|cFF0000FF(Quête)|r Je suis prêt à me rendre dans les terres de Feu.', '|cFF0000FF(Quête)|r Je suis prête à me rendre dans les terres de Feu.', 28153),
(161900, 'frFR', '', 'Venez, $n. Réglons-lui son compte.', 28153),
(161899, 'frFR', 'Elle ne s\’attend pas à nous trouver en Vol\’dun, mais ne tardera pas à se demander qui liquide ses agents.', '', 28153),
(161898, 'frFR', 'Nous devons agir au plus vite, $n. La Horde ignore encore que nous avons débarqué.', '', 28153),
(161897, 'frFR', 'Il va poser les bombes et revenir ici en un rien de temps.', '', 28153),
(161896, 'frFR', 'Il n\’en a peut-être pas l\’air, mais il sait se battre et son expérience en matière d\’explosifs est sans égale.', '', 28153),
(161895, 'frFR', 'Ne vous en faites pas. J\’ai déjà travaillé avec Fuzbert. C\’est un professionnel.', '', 28153),
(161894, 'frFR', 'Si la Lumière le veut, nous allons mettre un terme à leurs agissements.', '', 28153),
(161893, 'frFR', 'Et ils vendent celles dont ils n\’ont pas l\’usage, finançant ainsi l\’effort de guerre de la Horde.', '', 28153),
(161892, 'frFR', 'Mais ce serait commettre une grave erreur. Ces aigrefins n\’hésitent pas à utiliser les reliques qu\’ils déterrent contre leurs ennemis.', '', 28153),
(161891, 'frFR', 'Il pourrait être tentant de faire abstraction de Guette-soleil et du Reliquaire. Ce ne sont que des archéologues, après tout.', '', 28153),
(161890, 'frFR', '|cFF0000FF(Quête)|r Je suis prêt à me rendre dans les profondeurs de Rochenoire.', '|cFF0000FF(Quête)|r Je suis prête à me rendre dans les profondeurs de Rochenoire.', 28153),
(161889, 'frFR', '', 'Vous ne pouvez pas vous aventurer en Arathi pour l\’instant. C\’est bien trop dangereux.$B$BLe portail sera rétabli dès que nous aurons repris le contrôle de Stromgarde.', 28153),
(161888, 'frFR', 'Que savons-nous au sujet des Orcs mag\’har ?', 'Que savons-nous au sujet des Orcs mag\’har ?', 28153),
(161887, 'frFR', 'Que pouvez-vous me dire sur les Nains sombrefer ?', 'Que pouvez-vous me dire sur les Nains sombrefer ?', 28153),
(161886, 'frFR', 'Quand je serai grand, je voudrais être comme Nisha ! C\’est la meilleure !\n\nOu alors comme Kiro ! Il est super intelligent…\n\nOu comme Meera, peut-être ! Elle est tellement gentille…\n\nOu bien Jena ! Elle a plein de choses…\n\nOu encore…\n\n<Rudo continue à lister les noms des autres Vulpérins.>', '', 28153),
(161885, 'frFR', '', 'Vous ne pouvez pas vous aventurer en Arathi pour l\’instant. C\’est bien trop dangereux.$B$BLe portail sera rétabli dès que nous aurons repris le contrôle d\’Ar\’gorok.', 28153),
(161884, 'frFR', '', 'Laissez-vous tenter par une bière bien fraîche !', 28153),
(161883, 'frFR', 'C\’est votre jour de chance ! J\’ai de quoi assurer la victoire en toutes circonstances !', '', 28153),
(161882, 'frFR', 'Hé, y a du bon matos qui vous attend ici.', 'Oh, j\’espère que mes inventions vous plaisent !', 28153),
(161881, 'frFR', 'Mes armes et mes armures sortent tout juste de la forge !', '', 28153),
(161880, 'frFR', '', 'Approchez voir mes marchandises en provenance directe de Hurlevent !', 28153),
(161879, 'frFR', 'J\’ai déniché quelques instruments ténébreux.', '', 28153),
(161878, 'frFR', 'J\’ai des objets magiques susceptibles de vous intéresser.', 'Y a du bon matos ici, et pas de questions indiscrètes.', 28153),
(161877, 'frFR', 'Bières à la pinte !', 'Y a du bon matos ici, et pas de questions indiscrètes.', 28153),
(161876, 'frFR', 'Les Mag\’har sont avec vous. Sang et tonnerre !', 'Y a du bon matos ici, et pas de questions indiscrètes.', 28153),
(161875, 'frFR', 'Hé, vous cherchez des explosifs ? J\’ai pile-poil ce qu\’il vous faut.', 'Y a du bon matos ici, et pas de questions indiscrètes.', 28153),
(161874, 'frFR', 'Lok\’tar ! J\’ai reçu une livraison d\’Orgrimmar.', 'Y a du bon matos ici, et pas de questions indiscrètes.', 28153),
(161873, 'frFR', 'Venez faire vos emplettes ici ! Mes marchandises vous porteront chance !', 'Venez faire vos emplettes ici ! Mes marchandises vous porteront chance !', 28153),
(161872, 'frFR', 'On raconte qu\’Élisande maîtrisait des incantations connues seulement des dragons de bronze. Peut-être pourraient-ils vous venir en aide ?', '', 28153),
(161871, 'frFR', 'La magie du temps était le domaine de prédilection de notre ancienne chef, la grande magistrice Élisande. La majeure partie de son savoir a disparu avec elle.', '', 28153),
(161870, 'frFR', 'Il faut que je m\’infiltre dans l\’académie Portvaillant.', 'Il faut que je m\’infiltre dans l\’académie Portvaillant.', 28153),
(161869, 'frFR', 'Il faut que je m\’infiltre dans la caserne des Portvaillant.', 'Il faut que je m\’infiltre dans la caserne des Portvaillant.', 28153),
(161868, 'frFR', '', 'Pour l\’Alliance !', 28153),
(161867, 'frFR', 'On va tenir nos positions. Vous, partez devant. Pour l\’Alliance !', '', 28153),
(161866, 'frFR', 'On a le dos au mur et toute une flotte ennemie qui nous guette au tournant.', '', 28153),
(161865, 'frFR', 'J\’ai bien peur que notre Gnome ait raison, $p.', '', 28153),
(161864, 'frFR', '', 'Salut !', 28153),
(161863, 'frFR', '%s se dépêche de regagner la Raine-Mare.', '%s se dépêche de regagner la Raine-Mare.', 28153),
(161862, 'frFR', 'Contrairement à ces Réprouvés puants, celui-là, il a encore sa langue. On va pouvoir le faire parler.', '', 28153),
(161861, 'frFR', '', 'Allons-y, $p ! Dites au capitaine du navire qu\’on peut lever l\’ancre !', 28153),
(161860, 'frFR', '', 'Parfois, j\’aimerais bien être une machine…', 28153),
(161859, 'frFR', '', 'Ah, les machines… <soupir>', 28153),
(161858, 'frFR', 'Vous savez ce qu\’il vous reste à faire. Rompez !', '', 28153),
(161857, 'frFR', 'Évaluez-moi ces camps et revenez me faire le topo.', '', 28153),
(161856, 'frFR', '', 'Roooh ! Des Nains sombrefer ! J\’adore les Nains sombrefer ! Surtout leurs MACHINES.', 28153),
(161855, 'frFR', 'Vous allez rejoindre le thane-enclume Thurgaden sur la côte sud-est de Zuldazar.', '', 28153),
(161854, 'frFR', '', 'Oui, chef !', 28153),
(161853, 'frFR', 'Kelsey !', '', 28153),
(161852, 'frFR', 'Ses hommes ont rencontré quelques difficultés en mer, mais ils ont réussi à établir un camp de fortune sur la côte est.', '', 28153),
(161851, 'frFR', 'Allez trouver le général de brigade Thom, l\’un de nos officiers de la 7e Légion.', '', 28153),
(161850, 'frFR', '$p !', '', 28153),
(161849, 'frFR', '', 'Il y a plein de nourriture fraîche à l\’intérieur.', 28153),
(161848, 'frFR', 'Nous avons déjà pris pied à Zuldazar. Et en deux lieux différents, qui plus est.', '', 28153),
(161847, 'frFR', 'Écoutez bien, vous tous. Voici le plan.', '', 28153),
(161846, 'frFR', 'Vous croupirez… dans les geôles de Portvaillant…', '', 28153),
(161845, 'frFR', '', 'Racaille… de la Horde…', 28153),
(161844, 'frFR', 'Nous récupérerons le corps de Derek… d\’une façon ou d\’une autre…', '', 28153),
(161843, 'frFR', '', 'Jamais vous ne maîtriserez la puissance de nos enseignements…', 28153),
(161842, 'frFR', 'Les marées vous emportent…', '', 28153),
(161841, 'frFR', 'Retournez voir Oculeth. Maintenant que le fragment a été restauré, il va pouvoir vous envoyer où vous le souhaitez.', '', 28153),
(161840, 'frFR', 'S\’il y avait eu le moindre doute, je n\’aurais jamais laissé le fragment tomber entre de mauvaises mains. Pas une nouvelle fois.', '', 28153),
(161839, 'frFR', 'Je sens les fils du destin se tisser autour de vous. Vous semblez, en effet, être digne ce qui vous attend.', '', 28153),
(161838, 'frFR', 'Même en tant que réverbération du passé, Garrosh était un ennemi puissant.', '', 28153),
(161837, 'frFR', 'Ce que vous avez vu ici était l\’une de ses pires incarnations. Un pur gâchis.', '', 28153),
(161836, 'frFR', 'Dans les innombrables lignes temporelles qui auraient pu être, il était considéré comme un grand héros. Certains l\’appelaient même le plus grand chef de guerre de la Horde.', '', 28153),
(161835, 'frFR', 'Garrosh Hurlenfer… Il est regrettable que les choses aient pris cette tournure.', '', 28153),
(161834, 'frFR', 'Vous croyez que vous me faites peur ?', '', 28153),
(161833, 'frFR', 'Dites-nous tout, Zandalari.', 'Dites-nous tout, Zandalari.', 28153),
(161832, 'frFR', 'Vous voulez entendre mon histoire ?\n\nJ\’étais à bord du vaisseau amiral, j\’ai tout vu.\n\nTrès bien. Je vais vous dire ce qui s\’est passé. Comme ça, vous saurez et vous aussi, vous tremblerez de peur.', '', 28153),
(161831, 'frFR', 'Venez, nous devons nous rendre au temple du Tigre blanc.', '', 28153),
(161830, 'frFR', 'Gul\’dan ne manquera à personne… ni ici, ni dans aucune autre ligne temporelle.', '', 28153),
(161829, 'frFR', 'Même s\’il ne s\’agit là que d\’un écho de cet ennemi d\’Azeroth, sachez qu\’une mort infligée par cette entité se révélerait bien réelle.', '', 28153),
(161828, 'frFR', 'C\’est d\’ici que Gul\’dan a voyagé jadis entre les mondes à l\’aide de la Vision du temps.', '', 28153),
(161827, 'frFR', 'L\’écho de la magie d\’ici se propage à travers les voies temporelles.', '', 28153),
(161826, 'frFR', 'Je le sens déjà qui… Une minute, qu\’est-ce que c\’est que ça ?', '', 28153),
(161825, 'frFR', 'Dans cette chambre, le Cœur d\’Azeroth que vous détenez pourra devenir encore plus puissant !', '', 28153),
(161824, 'frFR', 'La chambre du Cœur a bien meilleure mine que la dernière fois que vous l\’avez vue, pas vrai ?', '', 28153),
(161823, 'frFR', 'Mais on peut pas s\’permettre de céder au désespoir. Je sais que vous repousserez cette marée de ténèbres !', '', 28153),
(161822, 'frFR', 'J\’ai bien peur qu\’on soit pas encore tirés d\’affaire, $n. La situation semble s\’aggraver d\’heure en heure.', '', 28153),
(161821, 'frFR', 'Vous sentez ça ? La puissance du Cœur continue de s\’éveiller.', '', 28153),
(161820, 'frFR', 'Retenez bien mes paroles… le seigneur du Feu retrouvera son dû. Au revoir… vieil ami.', '', 28153),
(161819, 'frFR', 'Ah, c\’est bon, ça… l\’odeur du feu d\’bon matin… et l\’après-midi, et le soir, aussi… Il faut qu\’on aille dans l\’antre du seigneur du Feu pour charger l\’Cœur du Magma.', '', 28153),
(161818, 'frFR', 'J\’vais envoyer nos meilleurs éclaireurs retrouver Mornepierre. Faut qu\’on empêche ce fou furieux de convertir d\’autres fanatiques.', '', 28153),
(161817, 'frFR', 'Voulez-vous vraiment passer les quêtes du prologue de Kul Tiras ?', 'Voulez-vous vraiment passer les quêtes du prologue de Kul Tiras ?', 28153),
(161816, 'frFR', 'Je connais déjà cette histoire… <Passer les quêtes du prologue de Kul Tiras et commencer votre périple à Boralus.>', 'Je connais déjà cette histoire… <Passer les quêtes du prologue de Kul Tiras et commencer votre périple à Boralus.>', 28153),
(161815, 'frFR', 'Faites-en bon usage, $n. Et méfiez-vous… Certains sont prêts à tout pour vous faire échouer dans votre devoir envers notre monde !', '', 28153),
(161814, 'frFR', 'Au fur et à mesure qu\’elle reprend des forces, le Cœur d\’Azeroth que vous portez autour du cou en reprend aussi !', '', 28153),
(161813, 'frFR', 'Azeroth est encore moribonde, mais grâce à votre aide, elle tient bon.', '', 28153),
(161812, 'frFR', 'Bon, occupons-nous du pont. J\’ai justement un sort de derrière les fagots…', '', 28153),
(161811, 'frFR', 'Voilà qui devrait faire l\’affaire ! Allez, filons d\’ici.', '', 28153),
(161810, 'frFR', 'Mais chaque chose en son temps. Allons charger le Cœur du Magma pour réparer l\’Enclume noire.', '', 28153),
(161809, 'frFR', 'L\’heure est grave, $p. Mornepierre et ses fanatiques qui cherchent à ressusciter Ragnaros… Je pensais pas qu\’il en arriverait là.', '', 28153),
(161808, 'frFR', 'Montrez-moi les évènements qui ont conduit l\’Alliance en Silithus.', 'Montrez-moi les évènements qui ont conduit l\’Alliance en Silithus.', 28153),
(161807, 'frFR', 'Montrez-moi les évènements qui ont conduit la Horde en Silithus.', 'Montrez-moi les évènements qui ont conduit la Horde en Silithus.', 28153),
(161806, 'frFR', 'Continuez comme ça !', '', 28153),
(161805, 'frFR', 'J\’ai toujours soif !', '', 28153),
(161804, 'frFR', 'Un autre !', '', 28153),
(161803, 'frFR', 'Encore !', '', 28153),
(161802, 'frFR', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t Hadal crée une |cFFFF0000|Hspell:276068|h[Vague de marée]|h|r !', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t Hadal crée une |cFFFF0000|Hspell:276068|h[Vague de marée]|h|r !', 28153),
(161801, 'frFR', 'Très bien. Dans ce cas, je propose qu\’on mette fin à ces civilités.', '', 28153),
(161800, 'frFR', 'Et plutôt deux fois qu\’une !', '', 28153),
(161799, 'frFR', 'Lorsque le véritable seigneur du Feu renaîtra de ses cendres, tous les fidèles Sombrefer répondront à son appel. Vous comptez vraiment vous opposer à nous ?', '', 28153),
(161798, 'frFR', 'Vous pensez vraiment que vot\’ petit groupe de recrues va l\’impressionner ? Je crois bien qu\’on a éliminé la majeure partie de vos pathétiques sectateurs en venant ici.', '', 28153),
(161797, 'frFR', 'Thaurissan a fait preuve de clairvoyance, certes, mais tenter de contrôler le seigneur du Feu… C\’était de la pure folie. Non, ce qu\’il faut faire, c\’est le servir comme il l\’entend.', '', 28153),
(161796, 'frFR', 'Ragnaros ? Vous voulez vraiment rappeler ce tyran ? Le thane-sorcier a essayé et…', '', 28153),
(161795, 'frFR', 'Légitime ? Moira n\’a pas de feu dans les veines. Notre régent légitime, c\’est le véritable seigneur du Feu. Pas cette demi-portion de Barbe-de-Bronze… ni aucun prétendant au trône, d\’ailleurs.', '', 28153),
(161794, 'frFR', 'Très bien. Attention à c\’que vous insinuez, héraut. Vous êtes à la limite du blasphème à l\’égard d\’notre régente légitime.', '', 28153),
(161793, 'frFR', 'Je vous prie de faire preuve de respect ! Vous allez vous adresser à moi par mon titre.', '', 28153),
(161792, 'frFR', 'Attention à c\’que vous insinuez, Harrold. Vous courez des risques en tenant des propos pareils.', '', 28153),
(161791, 'frFR', 'Chaque chose en son temps, thane-enclume. Vous savez comme moi que la régente est faible. Influençable.', '', 28153),
(161790, 'frFR', 'Mornepierre… Qu\’est-ce qui se passe ici ? Il est où, Fumeron ?', '', 28153),
(161789, 'frFR', 'Hé… chef !', '', 28153),
(161788, 'frFR', 'LE THANE-ENCLUME THURGADEN EST LÀ ! ALERTEZ LE JUGE SUPÉRIEUR MORNEPIERRE !', 'LE THANE-ENCLUME THURGADEN EST LÀ ! ALERTEZ LE JUGE SUPÉRIEUR MORNEPIERRE !', 28153),
(161786, 'frFR', 'Arrête de tourner autour du pot. Crache le morceau, gamin !', '', 28153),
(161785, 'frFR', 'Euh… c\’est-à-dire que…', 'Euh… c\’est-à-dire que…', 28153),
(161784, 'frFR', 'Qui a ordonné la fermeture du pont ? C\’est qui le chef, ici ?', '', 28153),
(161783, 'frFR', 'Thane-enclume ?!', 'Thane-enclume ?!', 28153),
(161782, 'frFR', 'Mais qu\’est-ce que ça veut dire ?', '', 28153),
(161781, 'frFR', 'Dites bonjour à mon petit camarade !', '', 28153),
(161780, 'frFR', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\’T a--dreadlord, really?', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\’T a--dreadlord, really?', 28153),
(161779, 'frFR', '<Les causes de la mort de ce marchand ne sont pas claires, mais son corps a été abandonné aux corbeaux depuis un certain temps.>', '', 28153),
(161774, 'frFR', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t Le kraken déchaîne une |cFFFF0000|Hspell:279897|h[Terreur des abysses]|h|r !', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t Le kraken déchaîne une |cFFFF0000|Hspell:279897|h[Terreur des abysses]|h|r !', 28153),
(161773, 'frFR', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t Les requins sentent |cFFFF0000|Hspell:279893|h[Du sang dans l\’eau]|h|r !', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t Les requins sentent |cFFFF0000|Hspell:279893|h[Du sang dans l\’eau]|h|r !', 28153),
(161772, 'frFR', 'Il admirait votre droiture… tout comme moi.', '', 28153),
(161771, 'frFR', 'C\’était trop demander que d\’espérer qu\’ils aient pardonné à Jaina, apparemment. Nous sommes tous inquiets pour elle, mais nous devons rester concentrés sur la mission.\n\nKul Tiras doit rejoindre l\’Alliance. Si Katherine Portvaillant refuse de nous entendre, ces sympathisants sont notre meilleur espoir.', '', 28153),
(161770, 'frFR', 'Hrkk…', '', 28153),
(161769, 'frFR', 'L\’Alliance ? Ici ?', '', 28153),
(161768, 'frFR', '', 'Ma vie pour l\’archéologie…', 28153),
(161767, 'frFR', '', 'Empêchez-les d\’approcher du site de fouilles !', 28153),
(161766, 'frFR', 'Le Reliquaire me vengera…', '', 28153),
(161765, 'frFR', '', 'Faut prévenir… Guette-Soleil…', 28153),
(161764, 'frFR', '', 'Hé ! Ce territoire appartient à la Horde ! Vous n\’avez rien à faire ici !', 28153),
(161763, 'frFR', 'Continuez à vous battre, chef ! Moi, j\’vais… j\’vais vous attendre ici.', '', 28153),
(161762, 'frFR', 'Nous offrirons la victoire à la Horde !', 'Nous offrirons la victoire à la Horde !', 28153),
(161761, 'frFR', 'On se retrouve en première ligne.', 'On se retrouve en première ligne.', 28153),
(161760, 'frFR', 'On va bientôt lever l\’ancre.', 'On va bientôt lever l\’ancre.', 28153),
(161759, 'frFR', 'Nos ennemis trembleront devant nous.', 'Nos ennemis trembleront devant nous.', 28153),
(161758, 'frFR', 'La bataille nous attend !', 'La bataille nous attend !', 28153),
(161757, 'frFR', 'Cette guerre de territoire n\’a que trop duré !', 'Cette guerre de territoire n\’a que trop duré !', 28153),
(161756, 'frFR', 'Pouvez-vous me porter dans vos branches, ô noble ancien ?', 'Pouvez-vous me porter dans vos branches, ô noble ancien ?', 28153),
(161755, 'frFR', 'Pourquoi la Horde ne nous laisse-t-elle pas en paix ?', 'Pourquoi la Horde ne nous laisse-t-elle pas en paix ?', 28153),
(161754, 'frFR', 'Citoyens de Boralus ! Tournez les yeux vers la marée et regardez bien !', '', 28153),
(161753, 'frFR', 'Mes Marteaux-Hardis vont attirer l\’attention de la Horde sur ce rafiot pendant qu\’on se charge de Dreven sur l\’autre.', '', 28153),
(161752, 'frFR', 'Je suis prêt à retourner à Boralus.', 'Je suis prête à retourner à Boralus.', 28153),
(161751, 'frFR', '', 'La chasse est terminée et le monde plus sûr.\n\nBelle journée, en vérité.', 28153),
(161750, 'frFR', 'À l\’assaut !', 'À l\’assaut !', 28153),
(161749, 'frFR', 'Passez devant.', 'Passez devant.', 28153),
(161748, 'frFR', 'C\’est ça ! Allez, au boulot.', 'C\’est ça ! Allez, au boulot.', 28153),
(161747, 'frFR', 'Je me battrai à vos côtés.', 'Je me battrai à vos côtés.', 28153),
(161746, 'frFR', 'J\’ai une dette envers vous, $n.', 'J\’ai une dette envers vous, $n.', 28153),
(161745, 'frFR', 'Ça alors ! Merci infiniment, $p !', '', 28153),
(161744, 'frFR', 'Donner la lettre de Rosaline à Ancel Mildenhall ?', 'Donner la lettre de Rosaline à Ancel Mildenhall ?', 28153),
(161743, 'frFR', 'Nous sommes face à une attaque de Troggs ! Sautez sur Cooper et donnez une bonne tripotée à ces Troggs.', '', 28153),
(161742, 'frFR', 'Au revoir !', 'Au revoir !', 28153),
(161741, 'frFR', '', 'En effet. Ils me manquent terriblement et j\’espère pouvoir rentrer chez moi très bientôt. Je suis sûre que Raimond fait de son mieux pour que tout se passe bien, même s\’il a la fâcheuse tendance à provoquer des catastrophes !', 28153),
(161740, 'frFR', 'Voilà qui devrait vous tenir chaud.', '', 28153),
(161739, 'frFR', 'Cette tenue fera l\’affaire.', '', 28153),
(161738, 'frFR', 'Vous récolterez peut-être mieux dans cette tenue.', '', 28153),
(161737, 'frFR', 'Ça vous va bien, $n.', '', 28153),
(161736, 'frFR', 'Je lance un Éclair de givre dans les ténèbres !', 'Je lance un Éclair de givre dans les ténèbres !', 28153),
(161735, 'frFR', 'Merci. Je vous promets de la remettre à son destinataire cette fois !', 'Merci. Je vous promets de la remettre à son destinataire cette fois !', 28153),
(161734, 'frFR', 'Hé, va pas renverser ta bière sur ma feuille de personnage !', 'Hé, va pas renverser ta bière sur ma feuille de personnage !', 28153),
(161733, 'frFR', 'Je prendre bougie.', 'Je prendre bougie.', 28153),
(161732, 'frFR', 'Hum ?', '', 28153),
(161731, 'frFR', 'Te soigner serait bien plus facile si tu arrêtais de marcher tout le temps dans le feu.', 'Te soigner serait bien plus facile si tu arrêtais de marcher tout le temps dans le feu.', 28153),
(161730, 'frFR', 'Je l\’ai…heu… égarée. Est-ce que je pourrais en avoir une autre copie, s\’il vous plaît ?', 'Je l\’ai…heu… égarée. Est-ce que je pourrais en avoir une copie, s\’il vous plaît ?', 28153),
(161729, 'frFR', 'Est-ce que le garde peut me voir fouiller ce corps ?', 'Est-ce que le garde peut me voir fouiller ce corps ?', 28153),
(161728, 'frFR', 'C\’est pas une bonne idée de se mettre le donner de quête à dos !', 'C\’est pas une bonne idée de se mettre le donner de quête à dos !', 28153),
(161727, 'frFR', 'Non, l\’arbre n\’est pas vulnérable aux attaques de feu.', 'Non, l\’arbre n\’est pas vulnérable aux attaques de feu.', 28153),
(161726, 'frFR', 'Je t\’ai déjà expliqué que barde n\’est pas une classe !', 'Je t\’ai déjà expliqué que barde n\’est pas une classe !', 28153),
(161725, 'frFR', '', 'Bonjour, $p. Je ne pensais pas déjà vous revoir. Alors, comment a réagi Ancel à ma lettre ?', 28153),
(161724, 'frFR', '', 'Nom de nom… $p, j\’espère sincèrement qu\’il n\’est pas dans vos habitudes de perdre ce qu\’on vous confie. Attendez, je vous en donne un autre exemplaire.', 28153),
(161723, 'frFR', 'Donner l\’amulette en miel recuite à Rosaline ?', 'Donner l\’amulette en miel recuite à Rosaline ?', 28153),
(161722, 'frFR', '', 'Ah… à chaque jour suffit sa proie.', 28153),
(161721, 'frFR', '', 'Attendez… Vous avez rencontré Ancel et Raimond ?', 28153),
(161720, 'frFR', 'Eh bien… c\’est une longue histoire, mais elle se trouvait à l\’intérieur d\’une abomination vivante faite de miel. Je l\’ai trouvée en aidant Ancel et Raimond à remettre de l\’ordre à la ferme.', 'Eh bien… c\’est une longue histoire, mais elle se trouvait à l\’intérieur d\’une abomination vivante faite de miel. Je l\’ai trouvée en aidant Ancel et Raimond à remettre de l\’ordre à la ferme.', 28153),
(161719, 'frFR', 'J\’ai trouvé cette amulette. Est-ce qu\’elle vous appartient ?', 'J\’ai trouvé cette amulette. Est-ce qu\’elle vous appartient ?', 28153),
(161718, 'frFR', '', 'Comment puis-je vous aider ? Avez-vous des instruments arcaniques nécessitant une identification ?', 28153),
(161717, 'frFR', 'On va bientôt pouvoir réparer l\’Enclume noire. Reste plus qu\’à charger le cœur avec l\’essence de Ragnaros.', '', 28153),
(161716, 'frFR', '|cFF0000FF(Quête)|r Je suis prêt à me rendre au Cœur du Magma.', '|cFF0000FF(Quête)|r Je suis prête à me rendre au Cœur du Magma.', 28153),
(161715, 'frFR', 'Regardez-moi ce petit bijou ! Filons d\’ici. La taupe mécanique devrait nous permettre de retourner à Hurlevent sans encombre.', '', 28153),
(161714, 'frFR', 'Je pourrais en dire de même de toi, mon mycofrère.', '', 28153),
(161713, 'frFR', 'Tu n\’as jamais été notre égal !', '', 28153),
(161712, 'frFR', 'Difficile de dire par lequel il serait le plus déçu.', '', 28153),
(161711, 'frFR', 'Qu\’est ce que notre fongipère penserait de ce qu\’on est devenus ?', '', 28153),
(161710, 'frFR', 'C\’est ce qu\’on verra, mon mycofrère.', '', 28153),
(161709, 'frFR', 'Tu ne vaudras jamais rien.', '', 28153),
(161708, 'frFR', 'On dirait qu\’on va devoir terminer la route à pied.', '', 28153),
(161707, 'frFR', 'Oups… Heureusement que j\’ai pris mes précautions.', '', 28153),
(161706, 'frFR', 'À GAUCHE ! À DROITE ! DE LA… LAVE !', '', 28153),
(161705, 'frFR', 'Pff ! Je ne sais pas comment je vais faire pour me débarrasser de tout ce sable dans mes vêtements.', '', 28153),
(161704, 'frFR', 'Aïe ! Attention !', '', 28153),
(161703, 'frFR', 'Encore un peu pour remplir la cale, et ensuite, nous pourrons quitter ce maudit littoral… et oublier cette odeur pestilentielle…', '', 28153),
(161702, 'frFR', 'Mais bon, mon tank devrait nous faciliter un peu la tâche. Essayez d\’pas rayer la peinture pendant que je m\’occupe des derniers préparatifs.', '', 28153),
(161701, 'frFR', 'Et pis, il va falloir se farcir le vieux Gezzrok avant de pouvoir mettre la main sur un morceau de cœur.', '', 28153),
(161700, 'frFR', 'Est-ce qu\’ils pourraient peut-être augmenter un tout petit peu la cadence ?', '', 28153),
(161699, 'frFR', 'Sauf qu\’on va d\’voir se débarrasser d\’un paquet de créatures ardentes avant de pouvoir pénétrer dans l\’ancien antre de Ragnaros.', '', 28153),
(161698, 'frFR', 'Bon, $n, vous croyez peut-être que c\’est un ramassage express tout c\’qu\’il y a de plus classique, et vous avez pas complètement tort.', '', 28153),
(161697, 'frFR', 'Si vos hommes parviennent ne serait-ce qu\’à dépasser le stade de la médiocrité, je serai vraiment très impressionné.', '', 28153),
(161696, 'frFR', 'Je vous conseille de rester concentré sur votre travail.', '', 28153),
(161695, 'frFR', 'Très sincèrement, les opinions politiques de votre… chef… n\’intéressent ni moi, ni les personnes que je représente.', '', 28153),
(161694, 'frFR', 'Ouais, ouais… J\’ai pigé.', '', 28153),
(161693, 'frFR', 'Personne ne veut voir ça !', '', 28153),
(161692, 'frFR', 'On perd des hommes à tour de bras et notre équipement n\’arrête pas de nous lâcher. Je vous préviens, les sacs à fric, si ça continue comme ça, vous allez devoir transporter l\’azérite vous-mêmes avec vos petites gambettes d\’Elfes.', '', 28153),
(161691, 'frFR', 'Donc, vous vous en moquez.', '', 28153),
(161690, 'frFR', 'C\’est vrai, ma p\’tite. C\’est vrai. Excusez-moi, $n.', '', 28153),
(161689, 'frFR', '', 'Nous savons tous les deux que vous disposez d\’une quantité incommensurable de minerai dans la Voûte noire.', 28153),
(161688, 'frFR', '', 'Ne jouez pas les égoïstes, Thaelin. $n a des tâches importantes à accomplir.', 28153),
(161687, 'frFR', 'L\’Enclume noire est forgée exclusivement à partir du sombrefer le plus pur, fondu et raffiné à l\’aide de techniques secrètes que je ne peux révéler qu\’à nos mineurs et forgerons les plus loyaux.', '', 28153),
(161686, 'frFR', 'Il va nous falloir une montagne de sombrefer pour réparer ça !', '', 28153),
(161685, 'frFR', '', 'Il ne fait aucun doute que c\’est à Volrath que nous devons une telle présence de la Horde en Kul Tiras.\n\nD\’abord A\’shran, puis cette maudite île au large de Féralas, et maintenant ici… Il est comme ces mauvais rhumes dont on n\’arrive pas à se défaire de tout l\’hiver.', 28153),
(161684, 'frFR', 'J\’imagine que les duels sont une façon comme une autre de s\’améliorer au combat…\n\nMais moi, ce que je préfère, c\’est utiliser les laquais de l\’Alliance comme mannequins d\’entraînement.', 'J\’imagine que les duels sont une façon comme une autre de s\’améliorer au combat…\n\nMais moi, ce que je préfère, c\’est utiliser les laquais de l\’Alliance comme mannequins d\’entraînement.', 28153),
(161683, 'frFR', 'Retrouvez-moi à bord de la Complainte de la Banshee, au port de Zandalar.', '', 28153),
(161682, 'frFR', 'Rentrez dans le rang, soldat !', 'Rentrez dans le rang, soldat !', 28153),
(161681, 'frFR', 'Une nouvelle escouade de renforts s\’apprête à lever l\’ancre.', 'Une nouvelle escouade de renforts s\’apprête à lever l\’ancre.', 28153),
(161680, 'frFR', 'Le combat vous appelle.', 'Le combat vous appelle.', 28153),
(161679, 'frFR', 'C\’est pour ça qu\’on s\’est entraînés !', 'C\’est pour ça qu\’on s\’est entraînés !', 28153),
(161678, 'frFR', 'La bataille nous attend !', 'La bataille nous attend !', 28153),
(161677, 'frFR', 'Bien, $n. Prenez un fragment du cœur et on pourra retourner dans les grottes supérieures. Je vais faire préparer une taupe mécanique.', '', 28153),
(161676, 'frFR', 'Nous aurions bien besoin de vous dans nos rangs, $c.', 'Nous aurions bien besoin de vous dans nos rangs, $c.', 28153),
(161675, 'frFR', 'Préparez-vous à livrer bataille.', 'Préparez-vous à livrer bataille.', 28153),
(161674, 'frFR', 'C\’est parti !', '', 28153),
(161673, 'frFR', 'Très bien. Dans ce cas, battez-moi et vous pourrez repartir avec.', '', 28153),
(161672, 'frFR', 'Nous avons besoin d\’un morceau du Cœur du Magma pour réparer l\’Enclume noire.', '', 28153),
(161671, 'frFR', 'Et qu\’est-ce qui vous amène ici, petit brandon ?', '', 28153),
(161670, 'frFR', 'Thaelin Sombrenclume du clan Sombrefer.', '', 28153),
(161669, 'frFR', 'Qui va là ?', '', 28153),
(161668, 'frFR', 'Très bien. Vous avez mérité ce morceau du Cœur du Magma. Faites-en bon usage.', '', 28153),
(161667, 'frFR', 'Tremblelame s\’imagine qu\’elle peut se jouer de nous avec sa bande d\’imbéciles de l\’Alliance.\n\nSon arrogance scellera sa perte.', '', 28153),
(161666, 'frFR', '', 'Ne le dites pas aux autres, mais je ne suis pas mécontente que les éperviers se fassent oublier ces derniers temps. \n\nJe n\’ai rien contre les oiseaux, mais j\’ai fini par m\’attacher à mes petites boules de poils.\n\nL\’absence des rapaces améliore considérablement leur espérance de vie.', 28153),
(161665, 'frFR', 'Pour l\’Alliance !', 'Et pour nos défunts frères… Élune-adore.', 28153),
(161664, 'frFR', 'Ah, Falstad ! Vous voilà.', '', 28153),
(161663, 'frFR', 'Quittez cet endroit !', 'Quittez cet endroit !', 28153),
(161662, 'frFR', 'Vous ne toucherez pas à ces terres !', 'Vous ne toucherez pas à ces terres !', 28153),
(161661, 'frFR', 'Les esprits… ils vont m\’accueillir…', 'Les esprits… ils vont m\’accueillir…', 28153),
(161660, 'frFR', 'Vous pourrez jamais tous… nous trucider…', 'Vous pourrez jamais tous… nous trucider…', 28153),
(161659, 'frFR', 'Je m\’en vais rejoindre les esprits…', 'Je m\’en vais rejoindre les esprits…', 28153),
(161658, 'frFR', 'Mes visions m\’avaient pas… montré ça…', 'Mes visions m\’avaient pas… montré ça…', 28153),
(161657, 'frFR', 'La Horde… survivra…', 'La Horde… survivra…', 28153),
(161656, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(161655, 'frFR', 'Plus un geste !', 'Plus un geste !', 28153),
(161654, 'frFR', 'Y a du mauvais juju dans l\’air !', 'Y a du mauvais juju dans l\’air !', 28153),
(161653, 'frFR', 'Nul ne peut nous arrêter…', 'Nul ne peut nous arrêter…', 28153),
(161652, 'frFR', '', 'Retrouvez-moi dans mes quartiers à Fossoyeuse. Nous pourrons y planifier nos prochaines étapes… discrètement.', 28153),
(161651, 'frFR', 'Du whisky ? Très peu pour moi.\n\nTout ce qui m\’intéresse, c\’est les bretzels.', '', 28153),
(161650, 'frFR', 'Merci, magistère. Tout ce que vous pourrez nous dire nous sera très utile.', '', 28153),
(161649, 'frFR', 'Je serai ravi d\’apporter mon témoignage si cela peut servir.', '', 28153),
(161648, 'frFR', 'Il n\’y a qu\’un seul vrai Gallywix, et nous le trouverons. Je vais prévenir Shaw, pour les leurres.', '', 28153),
(161647, 'frFR', '', 'Comme si un seul Gallywix sur Azeroth n\’était pas déjà de trop, voilà que nous en avons… Combien à votre avis, Halford ? Plusieurs dizaines ?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161645, 'frFR', 'On va s\’occuper de vous, $PR ! Et qu\’on m\’apporte mon beurre de cacao sur le balcon !', '', 28153),
(161644, 'frFR', 'Je suis prêt à partir.', 'Je suis prête à partir.', 28153),
(161643, 'frFR', 'Content de vous voir ici, $n ! Dites-moi quand vous voudrez que je vous conduise auprès d\’Ulfar.', '', 28153),
(161642, 'frFR', 'Je ne comprendrai jamais les fêtes gobelines.', '', 28153),
(161641, 'frFR', 'Ne parlons plus jamais de cet endroit.', '', 28153),
(161640, 'frFR', 'Quel gâchis, quand on pense à tous les Gobelins qui meurent de faim.', '', 28153),
(161639, 'frFR', 'Pouah, d\’où vient cette odeur insoutenable ?', '', 28153),
(161638, 'frFR', 'Je me sens sale. Il faut que je prenne une douche, et vite.', '', 28153),
(161637, 'frFR', 'Je ne tremperais pas un orteil dans ce bassin répugnant. Qui sait ce qu\’ils ont fabriqué, là-dedans ?', '', 28153),
(161636, 'frFR', 'Comme par hasard, ils se contentent de jeter leurs ordures dans l\’eau. Quelle vulgarité.', '', 28153),
(161635, 'frFR', 'Un joli coin de nature… défiguré par des parterres d\’herbe artificielle d\’un goût douteux.', '', 28153),
(161634, 'frFR', 'Votre corps devient lourd tandis que vos poumons se remplissent de fumée…', 'Votre corps devient lourd tandis que vos poumons se remplissent de fumée…', 28153),
(161633, 'frFR', '', 'Je suis… soulagée… d\’avoir pu… vous sauver…', 28153),
(161632, 'frFR', '', 'Héraut… héraut ? Est-ce que vous m\’entendez ?', 28153),
(161631, 'frFR', 'Les flammes se sont éteintes ! Rejoignez le temple de la Lune !', 'Les flammes se sont éteintes ! Rejoignez le temple de la Lune !', 28153),
(161630, 'frFR', 'Ishala ! Ishala ! Es-tu là ? Je t\’en prie, Ishala, réponds-moi !', 'Ishala ! Ishala ! Es-tu là ? Je t\’en prie, Ishala, réponds-moi !', 28153),
(161629, 'frFR', 'Je ne peux pas partir sans mon enfant ! Je vous en prie, aidez-moi !', 'Je ne peux pas partir sans mon enfant ! Je vous en prie, aidez-moi !', 28153),
(161628, 'frFR', 'Je vous en supplie ! Retrouvez ma famille !', 'Je vous en supplie ! Retrouvez ma famille !', 28153),
(161627, 'frFR', 'S\’il vous plaît, aidez-moi ! J\’ai perdu ma fille !', 'S\’il vous plaît, aidez-moi ! J\’ai perdu ma fille !', 28153),
(161626, 'frFR', 'Ne la laissez pas passer. Ramenez Jaina chez elle.', '', 28153),
(161625, 'frFR', 'Vous avez encore une chance.', '', 28153),
(161624, 'frFR', 'Je donnerais tout pour revoir mon fils.', '', 28153),
(161623, 'frFR', 'Si vous l\’entendez… c\’est qu\’il y a encore un espoir.', '', 28153),
(161622, 'frFR', '', 'Il est trop tard pour cela.', 28153),
(161621, 'frFR', 'Katherine, elle vous appelle… Vous devez la retrouver.', '', 28153),
(161620, 'frFR', '', 'Genn… Elle brûle.', 28153),
(161619, 'frFR', '', 'Je la vois… dans mes rêves.', 28153),
(161618, 'frFR', '… Mais elle souffre bien plus aujourd\’hui, n\’est-ce pas ?', '', 28153),
(161617, 'frFR', 'Jaina n\’a fait que suivre son cœur… Et elle en a profondément souffert.', '', 28153),
(161616, 'frFR', '', 'Jaina a trahi notre nation.', 28153),
(161615, 'frFR', 'Il vous reste Jaina.', '', 28153),
(161614, 'frFR', '', 'Il ne me reste plus rien… plus personne…', 28153),
(161613, 'frFR', '', 'Priscilla, mon amie la plus chère… m\’a abandonnée.', 28153),
(161612, 'frFR', '', 'Je ne sais plus que faire, Daelin. Que croire ? À qui faire confiance ?', 28153),
(161611, 'frFR', 'Elle. Les Kultirassiens. Toute l\’Alliance, s\’il le faut.\n\nJ\’aime la Horde. J\’ai juré à Thrall de la défendre.\n\nPeu importe qui a déclenché cette guerre, je me battrai jusqu\’à la fin.', '', 28153),
(161610, 'frFR', 'Darnassus ne peut pas tomber… Ça ne peut pas finir ainsi !', 'Darnassus ne peut pas tomber… Ça ne peut pas finir ainsi !', 28153),
(161609, 'frFR', 'Maudite soit la Horde ! Maudits, tous autant qu\’ils sont !', 'Maudite soit la Horde ! Maudits, tous autant qu\’ils sont !', 28153),
(161608, 'frFR', 'Je ne… comprends pas…', 'Je ne… comprends pas…', 28153),
(161607, 'frFR', 'Merci ! J\’espère que les autres s\’en sont sortis…', 'Merci ! J\’espère que les autres s\’en sont sortis…', 28153),
(161606, 'frFR', 'Vous allez affronter Jaina Portvaillant ?', 'Vous allez affronter Jaina Portvaillant ?', 28153),
(161605, 'frFR', 'Jaina Portvaillant.\n\nElle a jadis choisi de nous épargner la tyrannie de son père. Et j\’ai respecté sa décision, ainsi que sa détermination.\n\nMais elle n\’a jamais pardonné à Hurlenfer pour ce qu\’il a fait à Theramore et elle a déchaîné sa haine contre toute la Horde.\n\nElle est allée trop loin. Il faut arrêter ce massacre et mettre un terme à sa quête de vengeance.', '', 28153),
(161604, 'frFR', 'Merci… J\’ai bien cru que j\’allais mourir.', 'Merci… J\’ai bien cru que j\’allais mourir.', 28153),
(161603, 'frFR', 'Tout est en train de brûler… Il ne reste rien…', 'Tout est en train de brûler… Il ne reste rien…', 28153),
(161602, 'frFR', 'Qu\’Élune vous bénisse…', 'Qu\’Élune vous bénisse…', 28153),
(161601, 'frFR', 'Louée soit Élune pour vous avoir $Uenvoyé:envoyée;, $n.', 'Louée soit Élune pour vous avoir $Uenvoyé:envoyée;, $n.', 28153),
(161600, 'frFR', 'Envoyez-moi à Boralus !', 'Envoyez-moi à Boralus !', 28153),
(161599, 'frFR', '', 'Salutations, $c. Vous voulez retourner à Boralus ?', 28153),
(161598, 'frFR', '', 'Salutations, $c. Vous vous rendez au front ?', 28153),
(161597, 'frFR', '« Elle » ? De qui parlez-vous ?', '« Elle » ? De qui parlez-vous ?', 28153),
(161596, 'frFR', 'Je ne peux… plus… respirer…', 'Je ne peux… plus… respirer…', 28153),
(161595, 'frFR', 'J\’avais tissé des liens avec d\’autres chasseurs du Sentier invisible. Nous nous sommes battus pour défendre des terres brisées.\n\nMais à présent, le cor de guerre retentit à nouveau.\n\nQuand j\’ai su qu\’elle était revenue… je n\’ai eu d\’autre choix que de répondre à l\’appel.', '', 28153),
(161594, 'frFR', 'Qu\’avez-vous à voir avec ce conflit, Rexxar ?', 'Qu\’avez-vous à voir avec ce conflit, Rexxar ?', 28153),
(161593, 'frFR', 'S\’il vous plaît, aidez-moi !', 'S\’il vous plaît, aidez-moi !', 28153),
(161592, 'frFR', 'Par pitié, que quelqu\’un éteigne ce brasier !', 'Par pitié, que quelqu\’un éteigne ce brasier !', 28153),
(161591, 'frFR', 'Pas le temps de bavarder.\n\nIl semble qu\’une autre guerre nous attende.', '', 28153),
(161590, 'frFR', 'Quelle… chaleur…', 'Quelle… chaleur…', 28153),
(161589, 'frFR', 'Qu\’avons-nous fait pour mériter ça ?', 'Qu\’avons-nous fait pour mériter ça ?', 28153),
(161588, 'frFR', 'AAAHHH !', 'AAAHHH !', 28153),
(161587, 'frFR', 'De l\’eau ! Je vous en prie ! Par pitié !', 'De l\’eau ! Je vous en prie ! Par pitié !', 28153),
(161586, 'frFR', 'Puisse Élune sauver nos âmes !', 'Puisse Élune sauver nos âmes !', 28153),
(161585, 'frFR', 'Oui, concentrons-nous. Le devoir avant tout. Satisfaire le Flétrisseur et protéger les miens.\n\nIl faut que j\’y retourne, $n.', '', 28153),
(161584, 'frFR', 'Concentrez-vous, frère Zelling !', 'Concentrez-vous, frère Zelling !', 28153),
(161583, 'frFR', 'Ils sont tout pour moi, TOUT !\n\nJe… je sais bien qu\’ils ne veulent plus de moi dans leur vie, mais ça pourrait changer !\n\nQuand ils s\’apercevront que c\’est bien moi, que je les aime toujours, je sais qu\’ils… ils…\n\nJe… je…', '', 28153),
(161582, 'frFR', 'Ils occupent toujours vos pensées.', 'Ils occupent toujours vos pensées.', 28153),
(161581, 'frFR', 'Je ne sais pas trop… Je n\’ai pas encore…\n\nCe n\’est pas facile, $n.\n\nMademoiselle Voss m\’a conseillé de me concentrer sur ma tâche. Selon elle, prouver ma valeur au Flétrisseur est le meilleur moyen de protéger mes proches.\n\nMes proches…', '', 28153),
(161580, 'frFR', 'Comment se passe la transition, Zelling ?', 'Comment se passe la transition, Zelling ?', 28153),
(161579, 'frFR', 'Je ferai ce que je peux pour servir la cause des Réprouvés.', '', 28153),
(161578, 'frFR', 'Envoyez-moi à Zuldazar !', 'Envoyez-moi à Zuldazar !', 28153),
(161577, 'frFR', '', 'Throm-ka, $c. Voulez-vous retourner à Zuldazar ?', 28153),
(161576, 'frFR', '', 'De mon vivant, on m\’a appris à haïr les Morts-vivants. Et à les détruire.\n\nQuand je suis devenue Réprouvée, j\’ai eu bien du mal à m\’accepter.\n\nMais à présent, j\’ai compris que c\’est l\’Alliance qui entretient cette animosité. Les royaumes humains rejettent leurs défunts frères et sœurs parce que nous leur rappelons ce qui se cache derrière la façade éphémère de l\’enveloppe charnelle.\n\nIl est temps de mettre fin au cycle de la haine. L\’Alliance doit tomber.', 28153),
(161575, 'frFR', '', 'Les ténèbres ne peuvent résister à la Lumière !', 28153),
(161574, 'frFR', 'Ça, c\’est du méchant vaudou.', '', 28153),
(161573, 'frFR', 'Tout va bien.', 'Tout va bien.', 28153),
(161572, 'frFR', 'La Horde, personne peut l\’arrêter !', '', 28153),
(161571, 'frFR', 'Et qu\’en est-il de l\’Alliance ?', 'Et qu\’en est-il de l\’Alliance ?', 28153),
(161570, 'frFR', '', 'Pas besoin d\’être prophète pour savoir que Sylvanas va profiter de cette guerre pour grossir les rangs des Réprouvés.\n\nLe processus de transformation s\’est avéré… difficile. J\’ai dû faire un long travail sur moi-même pour trouver la paix et faire table rase du passé.\n\nEt ce n\’est pas terminé, mais je me sens obligée d\’aider les nouveaux venus à s\’adapter. Peut-être pourrai-je leur épargner les tourments que j\’ai endurés.', 28153),
(161569, 'frFR', 'C\’est pas de refus.', 'C\’est pas de refus.', 28153),
(161568, 'frFR', 'Nous avons la situation en main. Détendez-vous et dégustez votre bière.', 'Nous avons la situation en main. Détendez-vous et dégustez votre bière.', 28153),
(161567, 'frFR', 'Je vous remercie, camarade, mais nous irons plus vite seuls.', 'Je vous remercie, camarade, mais nous irons plus vite seuls.', 28153),
(161566, 'frFR', 'Vous faut un coup de main pour votre mission, mes petits Elfes ? Les Sombrefer s\’occupent de tout !', 'Vous faut un coup de main pour votre mission, mes petits Elfes ? Les Sombrefer s\’occupent de tout !', 28153),
(161565, 'frFR', 'Quel genre d\’opportunité ?', 'Quel genre d\’opportunité ?', 28153),
(161564, 'frFR', '', 'Apparemment, mes talents ont attiré l\’attention des autorités en place. Et elles ont aussitôt… « requis » mes services.\n\nVous avez compris le sous-entendu ? Désolée. Malgré ma profession, la subtilité n\’est pas mon fort.\n\nEnfin, quoi qu\’il en soit, je sais reconnaître une opportunité quand j\’en vois une.', 28153),
(161563, 'frFR', 'Vous semblez avoir épousé la cause de la Horde.', 'Vous semblez avoir épousé la cause de la Horde.', 28153),
(161562, 'frFR', 'Halford, mettons-nous au travail et faisons sauter ce navire.', 'Halford, mettons-nous au travail et faisons sauter ce navire.', 28153),
(161561, 'frFR', 'Je vous emmène ?', '', 28153),
(161560, 'frFR', 'Je vous emmène ?', '', 28153),
(161559, 'frFR', 'Le capitaine Brasston a dit que vous me feriez faire le tour du secteur.', 'Le capitaine Brasston a dit que vous me feriez faire le tour du secteur.', 28153),
(161558, 'frFR', 'Merci.', 'Merci.', 28153),
(161557, 'frFR', 'Wistel a dit que vous me feriez faire le tour du propriétaire.', 'Wistel a dit que vous me feriez faire le tour du propriétaire.', 28153),
(161556, 'frFR', 'Merci.', 'Merci.', 28153),
(161555, 'frFR', 'Ça y est, on a fait le tour. Redescendons.', '', 28153),
(161554, 'frFR', 'Droit devant, c\’est Haut-Perchoir, et au-delà, Ar\’gorok, $Umon grand:ma grande;. Le bastion de l\’ennemi et notre objectif principal.', '', 28153),
(161553, 'frFR', 'Là, c\’est Grangeneuve. Des fermes et des pâtures à perte de vue. Rien qui sorte de l\’ordinaire.', '', 28153),
(161552, 'frFR', 'Là-bas, vers l\’est, c\’est le cercle des Éléments, avec ses grands totems de pierre, ses élémentaires de feu géants et ses énormes cercles tracés à même le sol. Les chamans en raffolent.', '', 28153),
(161551, 'frFR', 'Ne vous en faites pas, ce ne sera pas long. Je veux juste vous faire faire le tour des sites d\’attaque de la Horde. Vous savez, au cas où on aurait besoin de vous pour… pour les tuer.', '', 28153),
(161550, 'frFR', 'Bienvenue à la scierie des Hautes-Terres. C\’est ici qu\’est produit tout le bois de Stromgarde… en temps normal, du moins. Depuis la dernière attaque de la Horde, on a dû évacuer les lieux et la nature a repris ses droits.\n\nMais rassurez-vous, tout rentrera bientôt dans l\’ordre. Dès qu\’on aura recruté quelques fantassins, les affaires reprendront.', '', 28153),
(161549, 'frFR', 'Bienvenue à la scierie des Hautes-Terres. C\’est ici qu\’est produit tout le bois de Stromgarde.\n\nLes forêts sont plutôt calmes aujourd\’hui. Rien à signaler, à part ce paysan qui s\’est bagarré avec un ours. Vous savez ce que c\’est, avec les pécores.', '', 28153),
(161548, 'frFR', '', '$n, c\’est bien ça ? Moi, c\’est Tully.\n\n<Le contremaître Tully vous tend une main calleuse.>\n\nÇa, c\’est le filon de Galson. En temps normal, mes employés travaillent d\’arrache-pied pour extraire le minerai nécessaire à l\’effort de guerre, mais depuis la dernière attaque de la Horde, on a dû évacuer les lieux.\n\nDites à Brasston qu\’on aurait bien besoin de soutien militaire, par ici. On est prêts à travailler, mais il va falloir se battre pour reprendre cette mine.', 28153),
(161547, 'frFR', '', '$n, c\’est bien ça ? Moi, c\’est Tully.\n\n<Le contremaître Tully vous tend une main calleuse.>\n\nRien à signaler dans le coin. La Horde continue à nous mettre des bâtons dans les roues et les Kobolds sont toujours aussi… casse-pieds, mais on a l\’habitude, à la longue.', 28153),
(161546, 'frFR', 'Ça y est, on a fait le tour. Redescendons.', '', 28153),
(161545, 'frFR', 'Droit devant, c\’est Haut-Perchoir, et au-delà, Stromgarde, $Umon grand:ma grande;. Le bastion de l\’ennemi et notre objectif principal.', '', 28153),
(161544, 'frFR', 'Là, c\’est Grangeneuve. Des fermes et des pâtures à perte de vue. Rien qui sorte de l\’ordinaire.', '', 28153),
(161543, 'frFR', 'Là-bas, vers l\’est, c\’est le cercle des Éléments, avec ses grands totems de pierre, ses élémentaires de feu géants et ses énormes cercles tracés à même le sol. Les chamans en raffolent.', '', 28153),
(161542, 'frFR', 'Vous en faites pas, ce sera pas long. Je veux juste vous faire faire le tour des sites d\’attaque de l\’Alliance. Vous savez, au cas où on aurait besoin de vous pour… pour les tuer.', '', 28153),
(161541, 'frFR', 'Bienvenue à la crête de la Cognée. C\’est ici qu\’est produit tout le bois d\’Ar\’gorok… en temps normal, du moins. Depuis la dernière attaque de l\’Alliance, on a dû évacuer les lieux et la nature a repris ses droits.\n\nMais rassurez-vous, tout rentrera bientôt dans l\’ordre. Dès qu\’on aura recruté quelques grunts, les affaires reprendront.', '', 28153),
(161540, 'frFR', 'Bienvenue à la crête de la Cognée. C\’est ici qu\’est produit tout le bois d\’Ar\’gorok.\n\nLes forêts sont plutôt calmes aujourd\’hui. Rien à signaler, à part ce péon qui s\’est bagarré avec un ours. Vous savez ce que c\’est, avec les pécores.', '', 28153),
(161539, 'frFR', '$n, c\’est bien ça ? Moi, c\’est Drogg.\n\n<Drogg vous tend une main calleuse.>\n\nÇa, c\’est la mine des Sèches-Moustaches. En temps normal, mes péons travaillent d\’arrache-pied pour extraire le minerai nécessaire à l\’effort de guerre, mais depuis la dernière attaque de l\’Alliance, on a dû évacuer les lieux.\n\nDites à Wistel qu\’on aurait bien besoin de soutien militaire, par ici. On est prêts à travailler, mais il va falloir se battre pour reprendre cette mine.', '', 28153),
(161538, 'frFR', '', '$n, c\’est bien ça ? Moi, c\’est Drogg.\n\n<Drogg vous tend une main calleuse.>\n\nRien à signaler dans le coin. L\’Alliance continue à nous mettre des bâtons dans les roues et les Kobolds sont toujours aussi… casse-pieds, mais on a l\’habitude, à la longue.', 28153),
(161537, 'frFR', 'Tant que Lune-d\’Argent soutiendra la Horde, certains refuseront de nous faire confiance.\n\nMais la place de notre peuple est ici, avec l\’Alliance. J\’en ai acquis la certitude.\n\nGardez le cap, $n. Montrons à nos frères d\’armes que nous luttons pour la même cause.\n\nUn jour, la Horde perdra son emprise sur nos terres et les enfants de Quel\’Thalas seront de nouveau réunis sous la même bannière.\n\nJe le sais.', '', 28153),
(161536, 'frFR', 'Croyez-vous que nous ayons gagné la confiance de l\’Alliance ?', 'Croyez-vous que nous ayons gagné la confiance de l\’Alliance ?', 28153),
(161535, 'frFR', 'Je lutte contre les murmures, tout comme vous. Heureusement, Alleria Coursevent est toujours là pour nous soutenir dans l\’épreuve.\n\nSi elle n\’était pas intervenue… nous serions tous perdus, à l\’heure qu\’il est.\n\nEt malgré ma réticence initiale, l\’Arpenteur des ombres m\’a beaucoup appris. Il faut juste garder à l\’esprit que quoi qu\’il fasse, il y trouve toujours son compte.', '', 28153),
(161534, 'frFR', 'Comment allez-vous, magistère Umbric ?', 'Comment allez-vous, magistère Umbric ?', 28153),
(161533, 'frFR', 'Nous n\’avons pas adhéré à l\’Alliance par intérêt, ni même par reconnaissance envers Alleria.\n\nAu cours de notre calvaire, nous avons appris que les puissances supérieures ne sont pas à mettre entre toutes les mains. La Horde ne doit surtout pas bénéficier de nos connaissances, ni se servir de nous comme d\’une arme.\n\nNous combattons pour l\’Alliance, car nous partageons ses valeurs. Et j\’espère qu\’un jour, l\’ensemble de Lune-d\’Argent nous rejoindra.', '', 28153),
(161532, 'frFR', 'Et maintenant, vous combattez pour l\’Alliance.', 'Et maintenant, vous combattez pour l\’Alliance.', 28153),
(161531, 'frFR', 'Je nous ai conduits droit dans le piège des éthériens. Si Alleria Coursevent n\’était pas intervenue, nous n\’en serions jamais revenus.\n\nQuoi qu\’il en soit, les énergies de l\’ombre nous ont transformés… elles ont ouvert nos esprits aux murmures du Vide. Sans Alleria, nous aurions tous basculé dans la folie.\n\nElle nous a aidés à trouver la paix, à atténuer les murmures. C\’est un combat de chaque instant.', '', 28153),
(161530, 'frFR', 'Le Vide a failli vous engloutir ?', 'Le Vide a failli vous engloutir ?', 28153),
(161529, 'frFR', 'Mes disciples et moi-même n\’avions pas juré fidélité à la Horde. Quand le grand magistère Rommath nous a interdit d\’étudier le Vide, nous n\’avons pas hésité à partir pour suivre notre propre voie.\n\nMais j\’ai péché par excès d\’orgueil. Je croyais pouvoir maîtriser n\’importe quelle force.\n\nGrossière erreur…', '', 28153),
(161528, 'frFR', 'Vous vous êtes donc tourné vers le pouvoir de l\’ombre ?', 'Vous vous êtes donc tourné vers le pouvoir de l\’ombre ?', 28153),
(161527, 'frFR', 'En tant que magistère, je sers depuis toujours Lune-d\’Argent et ses habitants. Quand Arthas le dément a dévasté nos terres, j\’ai compris qu\’il nous faudrait employer les grands moyens pour survivre.\n\nLe prince Kael\’thas avait sa vision des choses, et j\’avais la mienne.', '', 28153),
(161526, 'frFR', 'Quel rôle jouez-vous dans cette campagne, magistère ?', 'Quel rôle jouez-vous dans cette campagne, magistère ?', 28153),
(161525, 'frFR', '', 'Partons, $n.', 28153),
(161524, 'frFR', 'Déjà de retour ?', '', 28153),
(161523, 'frFR', 'J\’ai égaré la flûte.', 'J\’ai égaré la flûte.', 28153),
(161521, 'frFR', 'Impressionnant. Merci, magistère.', '', 28153),
(161520, 'frFR', 'Je vous accompagne. Nous profiterons de la traversée pour échafauder notre stratégie.', '', 28153),
(161519, 'frFR', 'Ils nous attendront sur le rivage à notre arrivée, avec un rapport de reconnaissance à l\’appui.', '', 28153),
(161518, 'frFR', 'Merci, magistère Umbric. Combien de temps avant qu\’ils n\’arrivent sur place ?', '', 28153),
(161517, 'frFR', 'Haut-commandant, j\’ai ordonné à mes meilleurs éclaireurs et assassins de nous rejoindre à Xibala.', '', 28153),
(161516, 'frFR', '', 'Un témoin… Excellent ! Plus un geste, pantin de l\’Alliance. Contemplez la chute de l\’un de vos plus illustres héros !', 28153),
(161515, 'frFR', 'Envoyez-moi aux hautes-terres Arathies !', 'Envoyez-moi aux hautes-terres Arathies !', 28153),
(161514, 'frFR', '', 'Throm-ka, $c. Vous vous rendez au front ?', 28153),
(161513, 'frFR', '', 'Bien le bonjour ! Cet endroit est vraiment incroyable, n\’est-ce pas ? Je n\’arrive pas à décider quel bar est mon préféré, mais celui-ci est dans les dix meilleurs, au bas mot !', 28153),
(161512, 'frFR', 'Aucun vaisseau ne peut rivaliser avec le nôtre.', 'Aucun vaisseau ne peut rivaliser avec le nôtre.', 28153),
(161511, 'frFR', 'Louée soit la mère des marées.', 'Louée soit la mère des marées.', 28153),
(161510, 'frFR', 'Écoutez les profondeurs. Elles seules nous montreront la vérité.', 'Écoutez les profondeurs. Elles seules nous montreront la vérité.', 28153),
(161509, 'frFR', '', 'Oh ! Hé, encore un artéfact drust. Je devrais l\’apporter à Jane.', 28153),
(161508, 'frFR', 'Que les courants vous guident.', 'Que les courants vous guident.', 28153),
(161507, 'frFR', '', 'Hrm, ma pioche de mineur commence à avoir du jeu. Je devrais demander à Grix d\’y jeter un œil.', 28153),
(161506, 'frFR', '', 'Je commence à avoir faim. Je vais passer chercher Alan et aller chez Byron.', 28153),
(161505, 'frFR', '', 'Ça me fait mal de l\’admettre, mais c\’était bien plus facile de transporter les matériaux quand Franklin était là.', 28153),
(161504, 'frFR', '', 'Bienvenue dans notre modeste établissement. En quoi puis-je vous aider ?', 28153),
(161503, 'frFR', '', 'Vous avez besoin d\’aide pour regagner Boralus ?', 28153),
(161502, 'frFR', 'Vous avez prouvé votre valeur en tant qu\’$Uallié:alliée;, $P.\n\nPeu importe où les sables nous conduiront, vous aurez toujours une place parmi nous.', '', 28153),
(161501, 'frFR', '', 'La vie ne sera jamais simple à Vol\’dun. Néanmoins, elle sera plus supportable après notre victoire contre les infidèles.\n\nMerci, $P.\n\nPrenez donc un verre et détendez-vous. Les miens se feront une joie de vous accueillir et d\’échanger quelques mots.\n\nAprès tout, nous nous battons pour les moments de paix comme celui-ci.', 28153),
(161500, 'frFR', '', 'Quelle aventure palpitante, $P. Je ne l\’oublierai pas de sitôt.\n\nOh et, pensez à aller voir Dolly. Vous lui manquez !', 28153),
(161499, 'frFR', 'Les problèmes rencontrés au dépôt de bois Algerson ont été résolus. Toutes les commandes de bois seront honorées dans les plus brefs délais.', '', 28153),
(161498, 'frFR', '', 'Arf, les poils de ces peaux de sanglier émoussent sans arrêt mon rasoir. Il faut que je demande à Grix de me fabriquer quelque chose de plus robuste.', 28153),
(161497, 'frFR', 'La garde des Malvoie vient de nous informer que la route de Drustvar est à nouveau sûre. Néanmoins, elle recommande aux voyageurs aventureux de ne pas s\’éloigner des sentiers battus.', '', 28153),
(161496, 'frFR', 'Qui c\’est qui accompagne Talanji ? On dirait… un membre de la Horde ?', '', 28153),
(161495, 'frFR', 'Est-ce qu\’elle a de nouveaux crânes ? Laissez-moi voir !', '', 28153),
(161494, 'frFR', 'La princesse est de retour !', '', 28153),
(161493, 'frFR', 'Talanji ! Talanji !', 'Talanji ! Talanji !', 28153),
(161492, 'frFR', 'Ramenez-moi à Zuldazar.', 'Ramenez-moi à Zuldazar.', 28153),
(161491, 'frFR', 'Le seigneur Norwington souhaite convier les intrépides cavaliers et chasseurs de gibier au 15e festival de chasse et d\’équitation de Norwington, qui se déroulera sur ses terres !', '', 28153),
(161490, 'frFR', '', 'La civilisation c\’est tellement rasoir… Je préférerais être à la chasse…', 28153),
(161489, 'frFR', 'Je… débauche… une dernière fois…', 'Je… débauche… une dernière fois…', 28153),
(161488, 'frFR', 'Je vais vous écraser !', 'Je vais vous écraser !', 28153),
(161487, 'frFR', 'La garde des Portvaillant déconseille vivement toute expédition en Drustvar jusqu\’à nouvel ordre. Elle attend une réponse de la garde des Malvoie. Nous ne pouvons vous fournir davantage d\’informations pour l\’instant.', '', 28153),
(161486, 'frFR', 'Ne vous inquiétez pas, tout ira pour le mieux. Tenez, elle m\’a demandé de vous donner cette lettre !', 'Ne vous inquiétez pas, tout ira pour le mieux. Tenez, elle m\’a demandé de vous donner cette lettre !', 28153),
(161485, 'frFR', '', 'Hé, Cass ! J\’ai égaré mon couteau à dépecer préféré, tu ne l\’as… laisse tomber ! Je l\’ai trouvé.', 28153),
(161484, 'frFR', 'Maynard souhaite informer les personnes préoccupées par les étranges rumeurs qui courent sur le dépôt de bois Algerson que celles-ci ont été exagérées afin de produire un effet dramatique, et que le dépôt rencontre simplement quelques légers contretemps.', '', 28153),
(161483, 'frFR', 'Priscilla… vous fera trancher la tête pour ça…', 'Priscilla… vous fera trancher la tête pour ça…', 28153),
(161482, 'frFR', 'À votre place, j\’éviterais de fouiner partout. C\’est pas bon pour votre santé !', 'À votre place, j\’éviterais de fouiner partout. C\’est pas bon pour votre santé !', 28153),
(161481, 'frFR', 'Par décret du grand amiral, je rappelle à tous les citoyens se rendant sur le territoire des Chantorage de se présenter au point de contrôle de la vallée, afin d\’être soumis à une fouille au corps par les gardes du seigneur Chantorage.', '', 28153),
(161480, 'frFR', 'Ahhh, ma maman me manque ! J\’espère qu\’elle reviendra vite à la maison.', '', 28153),
(161479, 'frFR', 'Les vents sont par nature éternellement changeants. Leurs revirements sont parfois à notre avantage, et parfois à notre détriment. Mais Pa\’ku nous enseigne de nous laisser porter par eux, car ils nous conduisent toujours là où l\’on a besoin de nous.\n\nVous et votre Horde avez rendu un fier service à mon roi et mon peuple. Nous ne l\’oublierons jamais.\n\nLoti ne nous le permettrait pas de toute façon. Je devrais peut-être lui pardonner. Ou m\’excuser. Je ne sais plus. C\’est peut-être vraiment la fin, après tout.', '', 28153),
(161478, 'frFR', '', 'Hé, bonjour !$b$bEnvie d\’en savoir plus sur l\’ingénierie ?', 28153),
(161477, 'frFR', 'Papa essaye de tout réparer dans la ferme. Il travaille jour et nuit !', '', 28153),
(161476, 'frFR', 'Ma maman me manque vraiment beaucoup… Elle est partie depuis très longtemps.', '', 28153),
(161475, 'frFR', 'Vous savez quoi… J\’aimerais bien devenir un aventurier moi aussi, quand je serai grand.', '', 28153),
(161474, 'frFR', 'J\’arrive pas à y croire ! Vous avez vaincu des wendigos !', '', 28153),
(161473, 'frFR', 'Ohhhh, j\’espère que vous avez de chouettes histoires à raconter !', '', 28153),
(161472, 'frFR', 'Salut, $p !', '', 28153),
(161471, 'frFR', 'Sans vous, je ne serais plus de ce monde. Merci.', 'Sans vous, je ne serais plus de ce monde. Merci.', 28153),
(161470, 'frFR', 'Par mon Loa, tout ça va mal finir !', 'Par mon Loa, tout ça va mal finir !', 28153),
(161469, 'frFR', 'Maudite soit la Horde ! Lor\’danel n\’a rien fait pour mériter ça !', 'Maudite soit la Horde ! Lor\’danel n\’a rien fait pour mériter ça !', 28153),
(161468, 'frFR', 'Bien le bonjour ! N\’êtes-vous pas tout bonnement… effroyable ?$b$bNe vous inquiétez pas, mon trésor. Daniel a justement ce qu\’il vous faut en stock !', '', 28153),
(161467, 'frFR', 'Que les Loas, ils soient avec vous deux.', '', 28153),
(161466, 'frFR', 'Entre les Trolls de sang, la mort des Loas et les trahisons qui nous frappent, Zandalar traverse des heures parmi les plus sombres de son histoire. Les ténèbres ont envahi nos cieux et les vents nous avertissent de l\’arrivée d\’autres périls.\n\nMême Loti est anormalement aimable avec moi. Je n\’aime pas ça.\n\nJe ne peux donc que me réjouir de votre présence ici, $n. Et de celle de votre Horde.', '', 28153),
(161465, 'frFR', 'Élune, aide-nous !', 'Élune, aide-nous !', 28153),
(161464, 'frFR', 'Attendez… Vous voulez faire QUOI ?', 'Attendez… Vous voulez faire QUOI ?', 28153),
(161463, 'frFR', 'Qui a pu penser une seule seconde que c\’était une bonne idée ?', 'Qui a pu penser une seule seconde que c\’était une bonne idée ?', 28153),
(161462, 'frFR', 'La ferme a été saccagée ! Je ne sais pas ce qui s\’est passé !', '', 28153),
(161461, 'frFR', 'Tout s\’est passé si vite…', 'Tout s\’est passé si vite…', 28153),
(161460, 'frFR', 'Louée soit Élune !', 'Louée soit Élune !', 28153),
(161459, 'frFR', 'Vous allez quelque part ?', 'Vous allez quelque part ?', 28153),
(161458, 'frFR', 'J\’ai cru que c\’était la fin. Merci !', 'J\’ai cru que c\’était la fin. Merci !', 28153),
(161457, 'frFR', 'Trop d\’arbres ici.', 'Trop d\’arbres ici.', 28153),
(161456, 'frFR', 'Y a trop de triangles dans les parages.', 'Y a trop de triangles dans les parages.', 28153),
(161455, 'frFR', 'Lor\’danel n\’avait pas la moindre chance…', 'Lor\’danel n\’avait pas la moindre chance…', 28153),
(161454, 'frFR', 'Le k\’liyant, il va ramer sévère.', 'Le k\’liyant, il va ramer sévère.', 28153),
(161453, 'frFR', 'J\’ai croisé votre mère. Elle vous passe le bonjour !', 'J\’ai croisé votre mère. Elle vous passe le bonjour !', 28153),
(161452, 'frFR', 'Le comportement de ces navrecornes me déconcerte grandement.', 'Le comportement de ces navrecornes me déconcerte grandement.', 28153),
(161451, 'frFR', 'Aïe ! Je suis allergique à la douleur !', 'Aïe ! Je suis allergique à la douleur !', 28153),
(161450, 'frFR', 'Qu\’est-ce qui se passera si j\’abandonne et que je reste ici ?', 'Qu\’est-ce qui se passera si j\’abandonne et que je reste ici ?', 28153),
(161449, 'frFR', 'Ne me laisse pas tomber, Gonk !', 'Ne me laisse pas tomber, Gonk !', 28153),
(161448, 'frFR', 'Taillez-vous !', 'Taillez-vous !', 28153),
(161447, 'frFR', 'Pourquoi est-ce qu\’ils nous attaquent ?', 'Pourquoi est-ce qu\’ils nous attaquent ?', 28153),
(161446, 'frFR', 'Non ! Noooooon ! Noooooooooooooon !', 'Non ! Noooooon ! Noooooooooooooon !', 28153),
(161445, 'frFR', 'Vous avez beau être rapide, vous m\’attraperez jamais !', 'Vous avez beau être rapide, vous m\’attraperez jamais !', 28153),
(161444, 'frFR', 'Courez !', 'Courez !', 28153),
(161443, 'frFR', '<Le journal est ouvert sur une page relatant l\’attaque de la Horde sur la place de Brennadam.>', '<Le journal est ouvert sur une page relatant l\’attaque de la Horde sur la place de Brennadam.>', 28153),
(161442, 'frFR', '', 'Je ne savais même pas à quoi servait ce sceau !\n\nNous devons plus que jamais unir nos forces pour surmonter les dangers qui menacent Zandalar. Quant à vous, veillez sur votre meute et soulagez vos compagnons des fardeaux qui les accablent.\n\nCe sale traître de Zul est mort. Je rappellerais bien à Raal que j\’avais raison, mais comme nous sommes si peu nombreux, je devrais peut-être faire la paix avec lui… Bah.', 28153),
(161441, 'frFR', '', 'Bienvenue chez Peaux et cuirs de Kul Tiras !$b$bPfff… il faut vraiment qu\’on trouve un meilleur nom.$b$bJe suis Cass, et j\’enseigne le travail du cuir. Mon associé Cami est un poil bourru, mais vous ne trouverez pas meilleur dépeceur.$b$bAlors, de quoi avez-vous besoin ?', 28153),
(161440, 'frFR', '', 'Tous ces Loas morts… Que Gonk protège les égarés. Je partage la souffrance de mon roi et de la princesse. Ils ont dû vivre la perte de Rezan comme un coup de poignard en plein cœur.\n\nBah. Je suis tellement triste que je pourrais même être polie avec Raal… mais pas plus de quelques jours.\n\nMerci, $n. La force de votre Horde décuple celle de notre meute. Nous aurons besoin de vous.', 28153),
(161439, 'frFR', '', 'La victoire contre les Trolls de sang, la menace des Sephraks et même le faux prophète... On peut dire que vous avez prouvé à maintes reprises votre valeur aux yeux de l\’empire zandalari.\n\nC\’est un honneur d\’être à vos côtés, $n.', 28153),
(161438, 'frFR', 'Je suppose que vous cherchez un nouveau familier ?\n\n<Ulfar ricane.>\n\nLa magie de cet endroit est si profonde que certains des animaux de la région en sont imprégnés. Ce sont de puissantes manifestations de la nature qu\’il convient de respecter.', '', 28153),
(161437, 'frFR', 'Quelle perspicacité !\n\n<Ulfar vous regarde en riant.>\n\nEn effet, je suis bien un Drust. Mais nous n\’étions pas tous favorables à ce conflit, vous savez. Votre peuple n\’a-t-il jamais connu pareilles divergences de vues ?\n\nLes Parlépines ont rejoint la société kultirassienne, où nous enseignons les anciennes coutumes à ceux de vos descendants qui ont entendu l\’appel de la nature. Peut-être entendez-vous cet appel, vous aussi ? Non ?', '', 28153),
(161436, 'frFR', 'Zul est mort, mais à quel prix ?\n\nLe Grand Sceau est brisé et Mythrax le Disloqueur hante à nouveau ce monde. Une force maléfique plus grande que tout ce qu\’ont jamais affronté les Zandalari obscurcit l\’horizon, une force qui a pour nom G\’huun.\n\nLa responsabilité de tout ceci repose sur mes seules épaules, $n. J\’aurais dû écouter Talanji ou ne pas laisser impunis les innombrables écarts de Zul. Mon Loa serait peut-être toujours vivant et je ne serais pas contraint de rallier celui de la mort.\n\nJ\’ai honte de mes actes.\n\nMais vous ne m\’avez jamais abandonné, $n. Votre Horde a combattu à nos côtés contre nos plus anciens ennemis. Les Zandalari sauront s\’en souvenir.\n\nJ\’y veillerai personnellement.', '', 28153),
(161435, 'frFR', 'En effet, je suis bien un Drust. Mais nous n\’étions pas tous favorables à ce conflit, vous savez. Votre peuple n\’a-t-il jamais connu pareilles divergences de vues ?\n\nLes Parlépines ont rejoint la société kultirassienne, où nous enseignons les anciennes coutumes à ceux de vos descendants qui ont entendu l\’appel de la nature.', '', 28153),
(161434, 'frFR', 'Je suis Ulfar, le dernier des Parlépines drust et le maître de ces étudiants. Un jour ma tâche sera achevée et je retournerai à la terre. Alors, un nouveau haut parlépine me remplacera à la tête de notre peuple, ainsi qu\’il est d\’usage.\n\nMais ce jour n\’est pas encore venu.', '', 28153),
(161433, 'frFR', 'Ah ! Vous m\’avez surpris !$b$bAlors… vous êtes là pour apprendre à pêcher ? Parce qu\’entre nous, je ne sais rien faire d\’autre.', '', 28153),
(161432, 'frFR', 'J\’ai vu des créatures qui semblaient mi-animales mi-végétales. Pouvez-vous m\’en dire plus à leur sujet ?', 'J\’ai vu des créatures qui semblaient mi-animales mi-végétales. Pouvez-vous m\’en dire plus à leur sujet ?', 28153),
(161431, 'frFR', 'Vous êtes un Drust ! Nous vous avons fait la guerre !', 'Vous êtes un Drust ! Nous vous avons fait la guerre !', 28153),
(161430, 'frFR', 'Vous êtes un Drust ? Il n\’y avait pas une guerre contre les Drust ?', 'Vous êtes un Drust ? Il n\’y avait pas une guerre contre les Drust ?', 28153),
(161429, 'frFR', 'Pourriez-vous nous raconter votre histoire encore une fois ?', 'Pourriez-vous nous raconter votre histoire encore une fois ?', 28153),
(161428, 'frFR', 'Qui êtes-vous ?', 'Qui êtes-vous ?', 28153),
(161427, 'frFR', '', 'Il ne faut pas oublier de s\’occuper de soi, $p. Aider ses proches est impossible si on est soi-même au fond du trou.', 28153),
(161426, 'frFR', 'Vous êtes vous-même un druide ?', 'Vous êtes vous-même un druide ?', 28153),
(161425, 'frFR', 'Vous êtes des druides ?', 'Vous êtes des druides ?', 28153),
(161424, 'frFR', '', 'J\’espère que tout se passe bien pour vous, $p !', 28153),
(161423, 'frFR', 'C\’est exact, $n. Nous sommes les gardiens de l\’équilibre, les protecteurs du cycle. La vie fait partie de la nature, tout comme la mort.', '', 28153),
(161422, 'frFR', 'Nous ne sommes pas si différents de vous, $n. Nous sommes les gardiens de l\’équilibre, les protecteurs du cycle. La vie fait partie de la nature, tout comme la mort. Mais en tant que druide, vous savez déjà tout cela.\n\nBienvenue dans notre bosquet.', '', 28153),
(161421, 'frFR', '', 'Ancel et son père me manquent terriblement. J\’espère pouvoir rentrer à la maison très prochainement.', 28153),
(161420, 'frFR', '', 'Il est bon de vous revoir, $p. J\’espère que vous allez bien.', 28153),
(161419, 'frFR', '<Lire la page du journal.>', '<Lire la page du journal.>', 28153),
(161418, 'frFR', 'Ce sera fait !', 'Ce sera fait !', 28153),
(161417, 'frFR', 'Lire le récit relatant votre découverte du Cœur des ténèbres aux côtés de Talanji.', 'Lire le récit relatant votre découverte du Cœur des ténèbres aux côtés de Talanji.', 28153),
(161416, 'frFR', '', 'En effet. Ils me manquent terriblement et j\’espère pouvoir rentrer chez moi très bientôt. Je suis sûre que Raimond fait de son mieux pour que tout se passe bien, même s\’il a la fâcheuse tendance à provoquer des catastrophes !\n\nSi vous les revoyez, pouvez-vous donner cette lettre à mon cher Ancel ?', 28153),
(161414, 'frFR', 'Vaza le Fou a pris note de tous les évènements qui se sont produits en Nazmir. Malgré son sobriquet, ses notes semblent soigneusement rédigées et parfaitement organisées.', '', 28153),
(161413, 'frFR', '', 'Zul a causé de tels ravages…\n\nJe vous suis reconnaissante, à vous et votre Horde, d\’être restés à nos côtés, $n. C\’est un vrai soulagement pour moi de ne pas m\’être trompée en vous faisant confiance. Imaginer que les Zandalari auraient pu affronter seuls toutes ces choses me donne des sueurs froides.\n\nJ\’espère que nous pourrons vous rendre la pareille si nous survivons à tout ceci. Quoi qu\’il en soit, les Zandalari vous seront à jamais redevables.', 28153),
(161412, 'frFR', '« Eh bien, mon frère, dit Koralynn, tu es le pire marin que je connaisse, mais je crois que tu feras un excellent eaugure. »', '« Eh bien, mon frère, dit Koralynn, tu es le pire marin que je connaisse, mais je crois que tu feras un excellent eaugure. »', 28153),
(161411, 'frFR', '', 'Je vous accompagne, Eitrigg, et je m\’entretiendrai avec votre chef de guerre. Est-ce toujours le Troll dont parlait ma mère ?', 28153),
(161410, 'frFR', '', 'Mon Loa… Rezan… est mort.\n\nMon cœur saigne et mon père semble écrasé sous un fardeau trop lourd pour lui. La trahison de Zul a ouvert une blessure plus profonde qu\’aucun de nous n\’aurait pu imaginer… y compris ceux qui le soupçonnaient depuis le début.\n\nUne telle hérésie ne peut rester impunie, $n. Nous devons rallier notre peuple, nos Loas, nos alliés ! C\’est notre seule chance de déjouer les ignobles machinations de Zul.', 28153),
(161409, 'frFR', '', 'Très bien. Au revoir, alors.', 28153),
(161408, 'frFR', 'Bien le bonjour !$b$bEt bienvenue au Barbecue boraléen Byron Frères ! Nous proposons la viande fumée la plus savoureuse de ce côté-ci de Forgefer !$b$bQu\’est-ce qui vous ferait plaisir ?', '', 28153),
(161407, 'frFR', 'Parlez-moi du marché entre Rastakhan et Bwonsamdi.', 'Parlez-moi du marché entre Rastakhan et Bwonsamdi.', 28153),
(161406, 'frFR', 'Devant nous se dressent les murs d\’Orgrimmar, capitale de la Horde.', '', 28153),
(161405, 'frFR', 'J\’ai ressenti la même chose il y a bien longtemps. Ça peut être… déconcertant. Je ferai tout mon possible pour vous aider, vous et votre peuple.', '', 28153),
(161404, 'frFR', 'Eh bien… ça pour une histoire…', 'Eh bien… ça pour une histoire…', 28153),
(161403, 'frFR', '', 'Mythrax le Disloqueur a recouvré la liberté ! Nous pensions qu\’il n\’était qu\’une légende, une histoire tragique destinée à nous mettre en garde contre l\’orgueil et les ravages du temps. Mais voilà qu\’il est ressuscité grâce au serpent Jakra\’zet et ses infidèles.\n\nTout n\’est pas perdu. Jakra\’zet n\’est plus, et nous avons gagné de nouveaux alliés en la personne des Vulpérins et des partisans du Loa Sephraliss. Hélas… je crains que même leur aide ne nous permette pas de l\’emporter contre un tel adversaire.\n\nNous vivons des heures sombres… J\’espère que ce ne sont pas les dernières de Zandalar.', 28153),
(161402, 'frFR', '', 'Il y a quelques instants encore, nous défendions nos vies sur Draenor. Je n\’aurais jamais pensé voir un autre monde de mes yeux.', 28153),
(161401, 'frFR', 'Parlez-moi de la semonce de Talanji.', 'Parlez-moi de la semonce de Talanji.', 28153),
(161400, 'frFR', 'Parlez-moi de l\’attaque de Mythrax.', 'Parlez-moi de l\’attaque de Mythrax.', 28153),
(161399, 'frFR', 'C\’est fait. Commandant, voici… Azeroth.', '', 28153),
(161398, 'frFR', 'Parlez-moi de la trahison de Zul.', 'Parlez-moi de la trahison de Zul.', 28153),
(161397, 'frFR', '', 'Le conflit qui oppose les Zandalari aux Nazmani fait rage depuis des générations. Nos frontières étaient déjà assiégées bien avant ma naissance, et mon père lui-même n\’a jamais connu que la guerre contre les Trolls de sang. Hélas, il les considérait comme de simples nuisibles, ce qui leur a permis d\’acquérir une force nouvelle. Et nous savons à présent d\’où ils tirent cette puissance.\n\nIls vénèrent G\’huun, le Dieu du sang.\n\nNous devons tenir quoi qu\’il en coûte. Si Zuldazar tombe, le monde entier tombera avec nous. Ils ne s\’arrêteront qu\’une fois tous les peuples asservis par leur dieu sanguinaire.', 28153),
(161396, 'frFR', '', 'Bienvenue dans ma boutique.$b$bN\’hésitez pas à jeter un œil à mes produits. Si vous avez la moindre question, je serais ravie de vous répondre.', 28153),
(161395, 'frFR', '', 'Bip-bip !', 28153),
(161394, 'frFR', 'Ces spécimens zandalari nécessitent une nouvelle taxonomie !', 'Ces spécimens zandalari nécessitent une nouvelle taxonomie !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161393, 'frFR', '', 'Bienvenue aux Enchantements Distingués de Beautemps !\n\nSi vous avez des questions d\’ordre mystique, n\’hésitez pas à demander !', 28153),
(161391, 'frFR', '', 'Rââh, j\’ai encore cassé ma plume…', 28153),
(161390, 'frFR', 'La clé… se tourne une nouvelle fois.', '', 28153),
(161389, 'frFR', 'Pauvre amas de chair ! À son réveil, l\’éternité vous submergera et vous tremblerez !', '', 28153),
(161388, 'frFR', '', 'Ahh ! J\’ai une crampe à la main !', 28153),
(161387, 'frFR', 'De grandes et terribles vérités se trouvent à l\’origine de toute chose. J\’en suis le héraut. Écoutez mon sermon et réalisez à quel point votre existence est futile.', '', 28153),
(161386, 'frFR', 'Mais j\’ai pas paniqué. J\’ai juste continué à nager en buvant sans jamais m\’arrêter !', '', 28153),
(161385, 'frFR', 'J\’étais là, pris au piège dans une énorme cuve de bière Brune d\’Orage !', '', 28153),
(161384, 'frFR', 'Vous avez vu l\’au-delà. Vous allez à présent percevoir les choses telles qu\’elles sont réellement.', '', 28153),
(161383, 'frFR', '', 'Une minute, était-ce une tache ou un glyphe ?', 28153),
(161382, 'frFR', 'Sylvanas désire m\’affronter et je ne compte pas la décevoir.', '', 28153),
(161381, 'frFR', 'Une ou deux brasseries naines ne seraient vraiment pas de trop à Reflet-de-Lune.', '', 28153),
(161380, 'frFR', '', 'Allons-y ! Le sous-marin doit déjà être déployé.', 28153),
(161379, 'frFR', 'Une autre tournée pour mes amis !', '', 28153),
(161378, 'frFR', 'Livraison spéciale pour vous, monsieur !', '', 28153),
(161377, 'frFR', 'Bon, d\’accord, elle était nulle. Enfin, bref, nous y sommes !', '', 28153),
(161376, 'frFR', 'Ça aurait été un vrai… déracinement pour moi. Vous pigez ?', '', 28153),
(161375, 'frFR', 'Mes parents voulaient que je m\’engage dans la marine. Vous imaginez un peu ?', '', 28153),
(161374, 'frFR', 'Lui et les autres me guident depuis que j\’ai entendu l\’appel. Je n\’étais encore qu\’un enfant, à l\’époque.', '', 28153),
(161373, 'frFR', 'Ulfar est sévère, mais juste.', '', 28153),
(161372, 'frFR', 'Accrochez-vous !', '', 28153),
(161371, 'frFR', 'Hé ! $n ! Par ici !', '', 28153),
(161370, 'frFR', 'La voie qui mène au bosquet d\’Ulfar peut se révéler périlleuse. Va donc retrouver nos amis au début du chemin, Arthur.', '', 28153),
(161369, 'frFR', 'C\’est entendu. Je vous retrouverai là-bas, $n !', '', 28153),
(161368, 'frFR', 'Vos exploits sont sur toutes les lèvres à la faille de Telogrus, $p.\n\nJe me félicite de vous avoir à mes côtés dans cette mission. Ensemble, rien ni personne ne peut nous arrêter.', '', 28153),
(161367, 'frFR', 'Je fais tout mon possible pour sécuriser la zone.', 'Je fais tout mon possible pour sécuriser la zone.', 28153),
(161366, 'frFR', 'La zone devrait être un poil plus sûre maintenant que ces appareils ont été désactivés… enfin, pour l\’instant.', 'La zone devrait être un poil plus sûre maintenant que ces appareils ont été désactivés… enfin, pour l\’instant.', 28153),
(161365, 'frFR', 'Regardez où vous mettez les pieds.', 'Regardez où vous mettez les pieds.', 28153),
(161364, 'frFR', 'J\’ai désamorcé tous les appareils que j\’ai pu trouver, mais restez tout de même sur vos gardes !', 'J\’ai désamorcé tous les appareils que j\’ai pu trouver, mais restez tout de même sur vos gardes !', 28153),
(161363, 'frFR', '', 'Ouais, il est comme neuf ! Mais j\’y pense… Et si on examinait les registres découverts par $n ?', 28153),
(161362, 'frFR', 'Je vois. Une chance que vous l\’ayez réparé.', '', 28153),
(161361, 'frFR', 'Quelle fleur ravissante !', '', 28153),
(161360, 'frFR', '', 'Oh ! Eh bien… c\’est que le champ de confinement miniaturisé ne fonctionnait pas encore il y a dix minutes de ça.', 28153),
(161359, 'frFR', 'Kelsey, pourquoi n\’a-t-on pas emprunté ce sous-marin pour rallier l\’île du Croc ?', '', 28153),
(161358, 'frFR', '', 'Détendez-vous. On sera au port de guerre en moins de deux !', 28153),
(161357, 'frFR', 'Votre saute-vagues prend peur. Faites demi-tour !', 'Votre saute-vagues prend peur. Faites demi-tour !', 28153),
(161356, 'frFR', 'Hum… des pucerons… Je m\’occuperai de VOUS plus tard.', '', 28153),
(161355, 'frFR', 'Allez, mon petit. Pousse !', '', 28153),
(161354, 'frFR', 'Ahh, rien ne me fait davantage apprécier ce travail que le délicat parfum de l\’aethril.', '', 28153),
(161353, 'frFR', 'Yojamba est une île de la vallée de Strangleronce où nous avons mené une expédition il y a de nombreuses années. J\’ai fait partie des troupes qui ont empêché le retour du Loa Hakkar en ce monde. Nous avons fourni de glorieuses armes aux héros qui ont combattu cette abomination.\n\nMais quand nous sommes rentrés victorieux en Zandalar, j\’ai fait l\’erreur de me vanter de ma victoire auprès du prophète Zul. J\’aurais sans doute mieux fait de la boucler.\n\nDésormais, je distribue des friandises.', '', 28153),
(161352, 'frFR', 'Vous êtes en train de perdre le fil de l\’histoire. Faites demi-tour !', 'Vous êtes en train de perdre le fil de l\’histoire. Faites demi-tour !', 28153),
(161351, 'frFR', '', 'Ravie de vous revoir, $p. Votre ascension fulgurante au sein de l\’Alliance est proprement admirable.\n\nMieux encore, vous faites preuve d\’une remarquable résistance aux murmures.\n\nLa guerre est un terreau propice au chaos et à la sauvagerie. Quoi qu\’il arrive, quelles que soient les épreuves que vous traverserez, il ne faut jamais perdre le contrôle. Ne laissez pas les ombres vous dicter votre conduite.\n\nL\’Alliance compte sur vous.\n\nJe compte sur vous.', 28153),
(161350, 'frFR', 'Expliquez-moi ce qu\’est Yojamba.', 'Expliquez-moi ce qu\’est Yojamba.', 28153),
(161349, 'frFR', 'L\’Alliance, elle nous attaque. Il faut prévenir le roi !', 'L\’Alliance, elle nous attaque. Il faut prévenir le roi !', 28153),
(161348, 'frFR', 'L\’Alliance, elle est là. Qu\’on avertisse le continent !', 'L\’Alliance, elle est là. Qu\’on avertisse le continent !', 28153),
(161347, 'frFR', 'On se fait attaquer par l\’Alliance. Le continent, il faut que je le prévienne !', 'On se fait attaquer par l\’Alliance. Le continent, il faut que je le prévienne !', 28153),
(161346, 'frFR', 'L\’Alliance, elle nous attaque. Il faut prévenir les autres !', 'L\’Alliance, elle nous attaque. Il faut prévenir les autres !', 28153),
(161345, 'frFR', '', 'Restez sur vos gardes, Umbric. C\’est un plan audacieux. À la moindre erreur, de nombreuses vies seront perdues.', 28153),
(161344, 'frFR', 'Réflexion faite, cette opération n\’est pas aussi suicidaire que je le pensais.', '', 28153),
(161343, 'frFR', 'Sauf votre respect, Halford, c\’est du suicide. Les Zandalari ont balayé la dernière flotte qui s\’est présentée sur leurs côtes.', '', 28153),
(161342, 'frFR', 'Oui, en l\’état actuel des choses, nos pertes seraient catastrophiques si nous tentions de débarquer ici.', '', 28153),
(161341, 'frFR', 'Leurs défenses navales ont anéanti la dernière flotte qui a osé s\’approcher de l\’île, et encore, ils étaient juste à la recherche d\’une princesse quelconque.', '', 28153),
(161340, 'frFR', 'Des marchandises enterrées ?', 'Des marchandises enterrées ?', 28153),
(161339, 'frFR', 'Je vous remercie. Enfin, je crois…', 'Je vous remercie. Enfin, je crois…', 28153),
(161338, 'frFR', 'Vous vouliez me parler de quelque chose ?', 'Vous vouliez me parler de quelque chose ?', 28153),
(161337, 'frFR', 'Il fait chaud ici.', 'Il fait chaud ici.', 28153),
(161336, 'frFR', '<Vous désignez silencieusement la zone.>', '<Vous désignez silencieusement la zone.>', 28153),
(161335, 'frFR', 'Vous disiez ?', 'Vous disiez ?', 28153),
(161334, 'frFR', 'C\’est ça que vous aviez en tête ?', 'C\’est ça que vous aviez en tête ?', 28153),
(161333, 'frFR', 'Bonjour, l\’$Uami:amie;. N\’ayez crainte.', '', 28153),
(161332, 'frFR', 'Voilà, et y a même assez pour le pourboire !', '', 28153),
(161331, 'frFR', 'Ouaip, je les ai mises de côté avant qu\’on me chope. Tout ce que vous avez à faire, c\’est trouver la tour aux abords de la Nouée, près de la rivière qui coule en Nazmir. C\’est caché juste au pied.', '', 28153),
(161330, 'frFR', 'Je vous dois bien un p\’tit quelque chose pour le coup de pouce de la dernière fois. Alors, je vais vous mettre au parfum pour les marchandises que j\’ai enterrées.', '', 28153),
(161329, 'frFR', 'Faut admettre qu\’il y a de quoi crâner. Comme guide, vous êtes plutôt $Udoué:douée; !', '', 28153),
(161328, 'frFR', 'Hé, c\’est pas mal, ici. L\’endroit a l\’air plutôt douillet.', '', 28153),
(161327, 'frFR', 'Je vous ai pas dit ? J\’ai entendu une de ces demi-portions noirâtres se vanter d\’habiter dans un volcan.', '', 28153),
(161326, 'frFR', 'OK, donc c\’est possible… Vous bleuissez… Vous avisez pas de m\’abandonner ici.', '', 28153),
(161325, 'frFR', 'Savez, j\’ai failli monter une piste de course en Vol\’dun, mais mon associé, il craignait qu\’un autre cataclysme nous fasse plonger, alors il a laissé tomber. De toute façon, on avait pas d\’argent, ils ont tout pris quand on a été exilés.', '', 28153),
(161324, 'frFR', 'Ça, c\’est pas un vrai reptile… Lui dites pas que j\’ai dit ça.', '', 28153),
(161323, 'frFR', 'Les reptiles de Zandalar, ils sont énormes. C\’est les plus balèzes de tous les temps.', '', 28153),
(161322, 'frFR', 'Je crois qu\’il fait encore plus froid. C\’est possible, ça ?', '', 28153),
(161321, 'frFR', 'Vous avez déjà vu un sabre dans la neige ? Ce serait dingue… De voir de la neige, je veux dire.', '', 28153),
(161320, 'frFR', 'C\’est pas mal, comme coin. Je pourrais m\’y installer.', '', 28153),
(161319, 'frFR', 'Quand est-ce qu\’on va enfin aller dans un endroit sympa ?', '', 28153),
(161318, 'frFR', '', 'Nous avons emménagé dans cette ferme avec l\’espoir de repartir de zéro. Tout n\’était pas rose pour nous en ville et Ancel avait des difficultés à l\’école. Son père et moi avons pensé qu\’il serait préférable de quitter ce tourbillon urbain au profit d\’une vie à la campagne plus sereine.\n\nJ\’ai dû arrêter mes études arcaniques et me consacrer à l\’agriculture, un métier difficile et éreintant. Nous avions du mal à joindre les deux bouts. À chaque fois que Raimond pensait que la chance allait enfin nous sourire, une catastrophe survenait.\n\nC\’est alors que j\’ai décidé de reprendre mes études. Je voyage, je parfais mes connaissances et je surviens aux besoins de ma famille en proposant mes talents aux plus offrants.', 28153),
(161317, 'frFR', 'Fait un peu froid ici, vous trouvez pas ?', '', 28153),
(161316, 'frFR', 'Cet endroit à l\’air intéressant.', '', 28153),
(161315, 'frFR', 'Ooh, où on est aujourd\’hui ?', '', 28153),
(161314, 'frFR', 'Merci… ?', 'Merci… ?', 28153),
(161313, 'frFR', 'Nous en parlerons une autre fois.', 'Nous en parlerons une autre fois.', 28153),
(161312, 'frFR', 'Peut-être. Mais je ne suis pas druide.', 'Peut-être. Mais je ne suis pas druide.', 28153),
(161311, 'frFR', 'Bien sûr.', 'Bien sûr.', 28153),
(161310, 'frFR', 'Ça doit être contrariant.', 'Ça doit être contrariant.', 28153),
(161309, 'frFR', 'Je parie que vous en êtes capable.', 'Je parie que vous en êtes capable.', 28153),
(161308, 'frFR', 'Mais ces formes ne vous permettent pas de voler plus vite ?', 'Mais ces formes ne vous permettent pas de voler plus vite ?', 28153),
(161307, 'frFR', 'Tout bien réfléchi, je préfère ne pas savoir.', 'Tout bien réfléchi, je préfère ne pas savoir.', 28153),
(161306, 'frFR', 'Qu\’est-ce qui vous met dans cet état ?', 'Qu\’est-ce qui vous met dans cet état ?', 28153),
(161305, 'frFR', 'Vous avez l\’air d\’avoir une histoire intéressante à raconter.', 'Vous avez l\’air d\’avoir une histoire intéressante à raconter.', 28153),
(161304, 'frFR', '', 'Eh bien… C\’est une longue histoire, mais je serais heureuse de vous la raconter. Avez-vous un peu de temps à me consacrer ?', 28153),
(161303, 'frFR', 'Je ne vous en voudrai pas. Je vais même tout vous écrire noir sur blanc, en grosses lettres, pour vous faciliter la lecture.', '', 28153),
(161302, 'frFR', 'Mais j\’ai une idée ! Si je vous disais comment leur donner une apparence respectable, sans leur faire perdre en vitesse, ils écouteraient peut-être.', '', 28153),
(161301, 'frFR', 'Évidemment ! Mais personne ne me croit. Tous me jugent en secouant leur crinière, euh, fourrure ou plutôt, feuilles. Bref ! Peu importe.', '', 28153),
(161300, 'frFR', 'En effet… mais si je puis me permettre, pourquoi n\’êtes-vous pas avec eux ? Ils n\’y sont pas allés de main morte à la ferme !', 'En effet… mais si je puis me permettre, pourquoi n\’êtes-vous pas avec eux ? Ils n\’y sont pas allés de main morte à la ferme !', 28153),
(161299, 'frFR', 'Et voilà, une autre preuve d\’ignorance ! Et pourquoi un vieux hibou comme moi ne serait-il pas capable de voler aussi vite que ces nouvelles formes tape-à-l\’œil ? Les anciennes nous ont suffi pendant des millénaires.', '', 28153),
(161298, 'frFR', 'Voyez-vous, ces jeunes druides n\’ont plus aucun respect pour les puristes comme nous. Ce n\’est pas moi qui irais voler avec des froufrous ou des armures tape-à-l\’œil.', '', 28153),
(161297, 'frFR', '', 'Où avez-vous trouvé ça ? Je croyais que c\’était perdu à jamais !', 28153),
(161296, 'frFR', 'Vous êtes scribe ? Pouvez-vous me prêter l\’oreille un instant ?', '', 28153),
(161295, 'frFR', 'La mode est tellement tape-à-l\’œil de nos jours.', '', 28153),
(161294, 'frFR', 'De mon temps, les gens avaient du respect pour les anciens.', '', 28153),
(161293, 'frFR', 'Je suis venu en Kul Tiras pour échapper à la guerre, et voilà où j\’en suis.', '', 28153),
(161292, 'frFR', 'Ah, ces jeunes druides, de nos jours…', '', 28153),
(161291, 'frFR', 'Vous ne voyez pas que je prends un bain de soleil ?', '', 28153),
(161290, 'frFR', 'Allez-vous-en.', '', 28153),
(161289, 'frFR', 'La voie est libre. Vous devez vous enfuir sans attendre !', 'La voie est libre. Vous devez vous enfuir sans attendre !', 28153),
(161288, 'frFR', 'Laissez-moi tranquille.', '', 28153),
(161287, 'frFR', '', 'Quelle épopée vous amène donc dans ce coin du monde ?', 28153),
(161286, 'frFR', '', 'Il n\’est jamais facile de faire des sacrifices, même pour le bien commun…', 28153),
(161285, 'frFR', '', 'J\’espère revenir un jour chez moi douée des aptitudes qui me permettront de remédier à nos malheurs récurrents.', 28153),
(161284, 'frFR', '', 'Les études arcaniques ne me laissent aucun temps libre. Il m\’arrive de me sentir dépassée par tout ce travail.', 28153),
(161283, 'frFR', '', 'Vous avez des enfants ? Je me demande comment va mon petit Ancel… Je devrais lui écrire.', 28153),
(161282, 'frFR', '', 'Vous ne vendriez pas de rares instruments magiques, par hasard ?', 28153),
(161281, 'frFR', '', 'Salut, ravie de faire votre connaissance.', 28153),
(161280, 'frFR', 'Peuh ! J\’avais la bouche ouverte !', 'Peuh ! J\’avais la bouche ouverte !', 28153),
(161279, 'frFR', 'Le bandeau ! Il sert à rien !', 'Le bandeau ! Il sert à rien !', 28153),
(161278, 'frFR', 'Yaaargh ! Je vais t\’arracher les ailes, espèce de rat volant !', 'Yaaargh ! Je vais t\’arracher les ailes, espèce de rat volant !', 28153),
(161277, 'frFR', 'Argh ! Cette saleté attaque mon œil valide !', 'Argh ! Cette saleté attaque mon œil valide !', 28153),
(161276, 'frFR', 'Soit maudit, démon à plumes !', 'Soit maudit, démon à plumes !', 28153),
(161275, 'frFR', 'Arrghhh…', 'Arrghhh…', 28153),
(161274, 'frFR', 'Pas encore !!', 'Pas encore !!', 28153),
(161273, 'frFR', 'Berk ! Dégoûtant !', 'Berk ! Dégoûtant !', 28153),
(161272, 'frFR', 'Vous allez pas flancher, hein ? J\’ai parié une belle somme sur vous… et ça ne plairait pas à mon père, si je perdais de l\’argent.', '', 28153),
(161271, 'frFR', 'T\’en fais pas, mon précieux or. Je reviendrai bientôt te chercher !', 'T\’en fais pas, mon précieux or. Je reviendrai bientôt te chercher !', 28153),
(161270, 'frFR', 'Regardez devant vous, soldat ! C\’est une zone de guerre !', '', 28153),
(161269, 'frFR', 'Vous avez vu tout cet or, sergent ? Regardez comme il brille !', '', 28153),
(161268, 'frFR', 'Bonjour ! Je divertis les enfants. Vous avez envie d\’entendre quelque chose en particulier ?', 'Bonjour ! Je divertis les enfants. Vous avez envie d\’entendre quelque chose en particulier ?', 28153),
(161267, 'frFR', '', 'Vous, là-bas ! Ça vous dirait de résoudre des énigmes en sachant que tout échec peut entraîner votre mort ou vous transformer en poulet ? Si oui, vous devriez envisager de vous former au métier d\’ingénieur !', 28153),
(161266, 'frFR', '', 'Vous savez… Je dois toujours terminer ce golem céleste sur lequel je travaillais.', 28153),
(161265, 'frFR', 'J\’aimerais entendre une chanson grave.', 'J\’aimerais entendre une chanson grave.', 28153),
(161264, 'frFR', 'J\’aimerais entendre une histoire à propos des eaugures.', 'J\’aimerais entendre une histoire à propos des eaugures.', 28153),
(161263, 'frFR', 'J\’aimerais entendre une chanson un peu folle.', 'J\’aimerais entendre une chanson un peu folle.', 28153),
(161262, 'frFR', 'Parlez-moi d\’Athair.', 'Parlez-moi d\’Athair.', 28153),
(161261, 'frFR', 'Argenterie ! Bouilloires à thé ! Vaisselle raffinée ! Qualité Corsandre garantie !', 'Argenterie ! Bouilloires à thé ! Vaisselle raffinée ! Qualité Corsandre garantie !', 28153),
(161260, 'frFR', '', 'Si j\’augmente la puissance explosive initiale, ça pourrait bien accroître le rendement de la charge utile… et quelles seraient alors les chances d\’enrayement ?', 28153),
(161259, 'frFR', 'N\’ayez crainte, braves gens, tout le monde trouvera son bonheur !', 'N\’ayez crainte, braves gens, tout le monde trouvera son bonheur !', 28153),
(161258, 'frFR', 'Montres à gousset de marinier ! Certains modèles ne sont déjà plus fabriqués !', 'Montres à gousset de marinier ! Certains modèles ne sont déjà plus fabriqués !', 28153),
(161257, 'frFR', '… douze pièces d\’argent moins chères que chez n\’importe quel autre marchand des Alizés !', '… douze pièces d\’argent moins chères que chez n\’importe quel autre marchand des Alizés !', 28153),
(161256, 'frFR', 'Boussoles plaquées or ! En provenance directe du fournisseur officiel de l\’amirauté !', 'Boussoles plaquées or ! En provenance directe du fournisseur officiel de l\’amirauté !', 28153),
(161255, 'frFR', '', 'Où est-ce que j\’ai mis cette clé ?', 28153),
(161254, 'frFR', 'Regardez-les détaler, cette bande de rats de cale. Bombardez-les de grenades sous-marines, $p !', 'Regardez-les détaler, cette bande de rats de cale. Bombardez-les de grenades sous-marines, $p !', 28153),
(161253, 'frFR', 'Regardez, $p ! Ils ont des entrepôts entiers sous l\’eau. Larguez des grenades sous-marines dessus !', '', 28153),
(161252, 'frFR', '', 'Besoin d\’argent ? Essayez l\’enchantement !', 28153),
(161251, 'frFR', '', 'Mais où est passé cet anneau ? Je l\’avais au doigt quand j\’étais… bon sang… pas encore.', 28153),
(161250, 'frFR', '', 'Même le plus redoutable des guerriers n\’est rien sans son armure et ses armes magiques. Découvrez l\’enchantement !', 28153),
(161249, 'frFR', '', 'Vous voulez vous essayer aux arts arcaniques ? Découvrez comment enchanter des objets pour leur conférer des propriétés magiques !', 28153),
(161248, 'frFR', 'Et pointez-moi ces canons vers les murs !', '', 28153),
(161247, 'frFR', 'Lancez vos torches sur les canoës qui ont des drapeaux rouges !', '', 28153),
(161246, 'frFR', 'Et pointez les canons vers les murs ! J\’ai pas envie de dormir avec les poissons ce soir !', '', 28153),
(161245, 'frFR', 'Incendiez les canoës qui ont sorti le drapeau rouge !', '', 28153),
(161244, 'frFR', 'Apprenez à maîtriser épices et grillades !', '', 28153),
(161243, 'frFR', 'Vous avez les crocs ? Alors qu\’attendez-vous ? Venez donc vous préparer un bon repas !', '', 28153),
(161242, 'frFR', 'Viandes fumées tendres et exquises ! Elles ne sont pas à vendre, mais vous pouvez apprendre à les préparer vous-même !', '', 28153),
(161241, 'frFR', '', 'Si je mets la main sur le petit malin qui laisse ces reliques se briser pendant le transport, je lui broie tous les os du corps.', 28153),
(161240, 'frFR', '', 'Vous avez fait preuve d\’un grand courage et d\’un certain sens de l\’honneur. J\’ai fait savoir au roi Rastakhan que vous êtes digne d\’assumer des missions plus importantes.\n\nMais restez sur vos gardes, car des yeux hostiles épient à coup sûr le moindre de vos mouvements.', 28153),
(161239, 'frFR', '', 'Un collectionneur serait prêt à payer une somme rondelette pour cet objet.', 28153),
(161238, 'frFR', 'Et c\’est ainsi que nos navires devinrent les meilleurs du monde connu !', 'Et c\’est ainsi que nos navires devinrent les meilleurs du monde connu !', 28153),
(161237, 'frFR', 'Et Domenic, les mains tremblantes et les yeux exorbités, réalisa que la mer avait répondu à son appel.', 'Et Domenic, les mains tremblantes et les yeux exorbités, réalisa que la mer avait répondu à son appel.', 28153),
(161236, 'frFR', 'Mais les eaux se retirèrent sous lui et la créature vint s\’empaler sur les rochers.', 'Mais les eaux se retirèrent sous lui et la créature vint s\’empaler sur les rochers.', 28153),
(161234, 'frFR', 'Il fit franchir les dangereux récifs aux navires en fuite, tandis que leur poursuivant nageait de plus belle pour rattraper ses proies !', 'Il fit franchir les dangereux récifs aux navires en fuite, tandis que leur poursuivant nageait de plus belle pour rattraper ses proies !', 28153),
(161233, 'frFR', '', 'Il faut vraiment que je calibre mon équipement topographique avant mon prochain levé.', 28153),
(161231, 'frFR', 'C\’est à ce moment précis qu\’un kraken, trois fois plus grand que celui qui les pourchassait, émergea des flots !', 'C\’est à ce moment précis qu\’un kraken, trois fois plus grand que celui qui les pourchassait, émergea des flots !', 28153),
(161229, 'frFR', '« Nous sommes perdus ! », se lamenta l\’équipage.', '« Nous sommes perdus ! », se lamenta l\’équipage.', 28153),
(161228, 'frFR', 'D\’énormes rocs apparurent alors devant eux dans les eaux bouillonnantes.', 'D\’énormes rocs apparurent alors devant eux dans les eaux bouillonnantes.', 28153),
(161227, 'frFR', 'La flotte se faufila entre les rochers grâce aux conseils avisés de Domenic, suivie par un kraken gagnant toujours plus de terrain !', 'La flotte se faufila entre les rochers grâce aux conseils avisés de Domenic, suivie par un kraken gagnant toujours plus de terrain !', 28153),
(161226, 'frFR', '« À tribord toute ! Cap sur le port ! » cria un Domenic en proie à la panique, mais attiré dans cette direction par une force pareille à un courant irrésistible. Le navire vira et sa sœur le suivit une fois de plus.', '« À tribord toute ! Cap sur le port ! » cria un Domenic en proie à la panique, mais attiré dans cette direction par une force pareille à un courant irrésistible. Le navire vira et sa sœur le suivit une fois de plus.', 28153),
(161225, 'frFR', 'Des tréfonds de l\’océan jaillit un immense kraken, plus imposant que le plus grand de leurs navires !', 'Des tréfonds de l\’océan jaillit un immense kraken, plus imposant que le plus grand de leurs navires !', 28153),
(161224, 'frFR', 'Mais lorsqu\’ils arrivèrent à destination, les marins découvrirent que de chasseurs, ils étaient devenus des proies.', 'Mais lorsqu\’ils arrivèrent à destination, les marins découvrirent que de chasseurs, ils étaient devenus des proies.', 28153),
(161223, 'frFR', '« La mer sera calme et les vents favorables », répondit Domenic d\’un ton assuré. Et après un voyage rapide et sans encombre, la petite flotte ne put que s\’émerveiller de la justesse de sa prédiction.', '« La mer sera calme et les vents favorables », répondit Domenic d\’un ton assuré. Et après un voyage rapide et sans encombre, la petite flotte ne put que s\’émerveiller de la justesse de sa prédiction.', 28153),
(161222, 'frFR', '« C\’est un endroit dangereux !, s\’écria l\’équipage. Notre navire se brisera sur les récifs ! »', '« C\’est un endroit dangereux !, s\’écria l\’équipage. Notre navire se brisera sur les récifs ! »', 28153),
(161221, 'frFR', 'Son frère réfléchit longuement à la question, comme s\’il écoutait un air qu\’il était le seul à pouvoir entendre. Puis il désigna une direction. « Je sens que nous trouverons ce que nous cherchons près des brisants au large de Kalimdor. »', 'Son frère réfléchit longuement à la question, comme s\’il écoutait un air qu\’il était le seul à pouvoir entendre. Puis il désigna une direction. « Je sens que nous trouverons ce que nous cherchons près des brisants au large de Kalimdor. »', 28153),
(161220, 'frFR', '« Où penses-tu que nous trouverons des proies ? » demanda-t-elle à son frère dont l\’intuition ne l\’avait jamais égarée.', '« Où penses-tu que nous trouverons des proies ? » demanda-t-elle à son frère dont l\’intuition ne l\’avait jamais égarée.', 28153),
(161219, 'frFR', 'Korralyn finit par se décider à changer de zone de chasse.', 'Korralyn finit par se décider à changer de zone de chasse.', 28153),
(161218, 'frFR', 'Un jour, ils levèrent l\’ancre pour partir à la chasse au kraken afin de nourrir la flotte, mais ils n\’en trouvèrent aucun aux endroits habituels. Des semaines durant ils cherchèrent en vain de la nourriture, tandis que la situation ne faisait qu\’empirer.', 'Un jour, ils levèrent l\’ancre pour partir à la chasse au kraken afin de nourrir la flotte, mais ils n\’en trouvèrent aucun aux endroits habituels. Des semaines durant ils cherchèrent en vain de la nourriture, tandis que la situation ne faisait qu\’empirer.', 28153),
(161217, 'frFR', 'Un jour, ils levèrent l\’ancre pour partir à la chasse au kraken afin de nourrir la flotte, mais ils n\’en trouvèrent aucun aux endroits habituels.', 'Un jour, ils levèrent l\’ancre pour partir à la chasse au kraken afin de nourrir la flotte, mais ils n\’en trouvèrent aucun aux endroits habituels.', 28153),
(161215, 'frFR', 'Il semblait comprendre la mer comme personne. Il sentait l\’approche des tempêtes, pouvait prédire les changements de marée et savait où jeter les filets.', 'Il semblait comprendre la mer comme personne. Il sentait l\’approche des tempêtes, pouvait prédire les changements de marée et savait où jeter les filets.', 28153),
(161214, 'frFR', 'Mais pendant que Koralynn observait et apprenait de ses pairs, elle gardait aussi un œil sur son frère.', 'Mais pendant que Koralynn observait et apprenait de ses pairs, elle gardait aussi un œil sur son frère.', 28153),
(161213, 'frFR', 'Étrange ! Ça n\’avait jamais fait ÇA auparavant…', '', 28153),
(161212, 'frFR', 'Nota bene : tu es presque à court d\’extraits de mousse étoilée. Refaire le plein dès que possible.', '', 28153),
(161211, 'frFR', 'Tout le monde a été surpris lorsque Koralynn l\’a choisi pour faire partie du premier équipage dont elle eut la charge… même Domenic ne s\’y attendait pas !', 'Tout le monde a été surpris lorsque Koralynn l\’a choisi pour faire partie du premier équipage dont elle eut la charge… même Domenic ne s\’y attendait pas !', 28153),
(161210, 'frFR', 'Et mieux vaut passer sous silence ses tentatives à la barre d\’une galère.', 'Et mieux vaut passer sous silence ses tentatives à la barre d\’une galère.', 28153),
(161209, 'frFR', 'Ahh, voilà. Ça mijote juste comme il faut.', '', 28153),
(161208, 'frFR', 'Il a souvent manqué de tomber d\’un gréement et n\’a jamais appris à faire des nœuds corrects ou à régler des voiles.', 'Il a souvent manqué de tomber d\’un gréement et n\’a jamais appris à faire des nœuds corrects ou à régler des voiles.', 28153),
(161207, 'frFR', 'Domenic était… bizarre. Même lorsqu\’il marchait sur le pont d\’un navire, le plus souvent en chantonnant, il avait l\’air dans la Lune.', 'Domenic était… bizarre. Même lorsqu\’il marchait sur le pont d\’un navire, le plus souvent en chantonnant, il avait l\’air dans la Lune.', 28153),
(161206, 'frFR', 'Il suffit de réduire légèrement le feu…', '', 28153),
(161205, 'frFR', 'Koralynn était tout ce qu\’une Kultirassienne se doit d\’être. Son frère était quant à lui tout l\’inverse.', 'Koralynn était tout ce qu\’une Kultirassienne se doit d\’être. Son frère était quant à lui tout l\’inverse.', 28153),
(161203, 'frFR', 'Elle s\’intéressait aux cartes célestes, aux courants et aux zones de chasse. L\’observation des marins lui prodiguait de riches enseignements.', 'Elle s\’intéressait aux cartes célestes, aux courants et aux zones de chasse. L\’observation des marins lui prodiguait de riches enseignements.', 28153),
(161202, 'frFR', 'Hmmm… Il va peut-être falloir que je commande plus de fjarnskaggl à Enges.', '', 28153),
(161201, 'frFR', 'Koralynn était forte et dégourdie.', 'Koralynn était forte et dégourdie.', 28153),
(161200, 'frFR', 'Il y a fort longtemps de cela vivaient deux enfants, Koralynn et Domenic.', 'Il y a fort longtemps de cela vivaient deux enfants, Koralynn et Domenic.', 28153),
(161199, 'frFR', '', 'Merci, commandant. Sans vous, nous ne serions plus de ce monde ! Nous regagnons notre poste immédiatement !', 28153),
(161198, 'frFR', 'Miimii décide de vous suivre.', 'Miimii décide de vous suivre.', 28153),
(161197, 'frFR', 'Un bruit étrange se fait entendre. Il semble provenir d\’un sarcophage à proximité…', 'Un bruit étrange se fait entendre. Il semble provenir d\’un sarcophage à proximité…', 28153),
(161196, 'frFR', 'Miimii la momie lève les yeux vers vous avec intérêt.', 'Miimii la momie lève les yeux vers vous avec intérêt.', 28153),
(161195, 'frFR', 'Pas un poisson ? C\’est sans espoir.', '', 28153),
(161194, 'frFR', 'Je sais même plus à quand remonte mon dernier repas.', '', 28153),
(161193, 'frFR', 'Pas la moindre touche ? Ça vient la POISCAILLE ?!', '', 28153),
(161192, 'frFR', 'J\’ai été témoin de nombreux évènements importants. J\’ai vu l\’histoire s\’écrire sous mes yeux, des conflits être résolus avant de se rallumer, des trahisons précéder de grandes victoires.\n\nMais cette défaite est totale. Zul nous a battus à plates coutures et il a réussi à atteindre le but qu\’il poursuivait depuis le début. Nous ne pouvons pas en rester là.\n\nLe conflit qui se prépare avec l\’ennemi que ces gens affrontent depuis l\’aube de leur race décidera du sort de la Horde et des Zandalari. Nous répondrons à leur appel. Nous réparerons les méfaits de Zul.\n\nNe relâchez pas votre vigilance, $n.', '', 28153),
(161191, 'frFR', '', 'J\’ai bien cru que ces fournitures n\’arriveraient jamais jusqu\’à votre armée. Merci, veuillez accepter ces ressources pour votre peine.', 28153),
(161190, 'frFR', 'J\’ignore à quoi pense le roi zandalari en ce moment, mais nous ne pouvons pas laisser ces évènements nous détourner de notre but. Les Zandalari doivent survivre à ce conflit. La Horde a juré de prendre les armes pour défendre ces gens. Et nous pourrions bien être les seuls à les secourir si leurs dieux ne se décident pas à les sauver.\n\nIls vont avoir plus que jamais besoin de vous. Représentez-nous honorablement, porte-parole de la Horde.', '', 28153),
(161189, 'frFR', '', 'Bon sang, j\’ai bien cru que c\’était la fin. Heureusement que vous étiez là ! Je vais améliorer les armures de votre armée, pour la peine. Merci !', 28153),
(161188, 'frFR', 'Vous rêvez de magie et de contrées lointaines ? Ou peut-être nous quittez-vous pour aller livrer bataille ?\n\nSi vous cherchez les portails vers Hurlevent, Forgefer et l\’Exodar, vous les trouverez au niveau inférieur du marché des Alizés, côté sud. Recherchez la salle située à côté de cet étrange transmogrificateur éthérien.', 'Vous rêvez de magie et de contrées lointaines ? Ou peut-être nous quittez-vous pour aller livrer bataille ?\n\nSi vous cherchez les portails vers Hurlevent, Forgefer et l\’Exodar, vous les trouverez au niveau inférieur du marché des Alizés, côté sud. Recherchez la salle située à côté de cet étrange transmogrificateur éthérien.', 28153),
(161187, 'frFR', '', 'Je dois garder espoir. Jaina est peut-être encore en vie.', 28153),
(161186, 'frFR', 'Je vois les ténèbres qui obscurcissent votre regard. Vous allez perdre l\’esprit et rejoindre les autres fantômes qui me hantent.$b$bC\’est encore trop tôt pour vous. Revenez lorsque vous serez en mesure d\’accomplir cette tâche. La corruption a mis une éternité à s\’insinuer et à grandir. Quelques jours de plus ne feront aucune différence.', '', 28153),
(161185, 'frFR', 'J\’ai trouvé cet indice dans les locaux Corsandre.', 'J\’ai trouvé cet indice dans les locaux Corsandre.', 28153),
(161184, 'frFR', 'Alors, vous avez fini par vous décider à me sauver, hein ? J\’imagine que je vous suis redevable. En échange, je peux améliorer l\’arsenal de votre armée.', '', 28153),
(161183, 'frFR', '', 'Je refuse de croire de Jaina est morte.', 28153),
(161181, 'frFR', 'Ah, j\’adore cette kölsch du marché des Alizés ! Ça se boit comme du petit lait !\n\nJe crois bien que je vais siffler celle-ci et en recommander une autre !', '', 28153),
(161180, 'frFR', 'J\’adore les bières d\’ici. Elles comptent parmi mes préférées !\n\nÀ la bonne vôtre !', '', 28153),
(161179, 'frFR', 'Bienvenue dans notre brasserie !\n\nJ\’espère que notre sélection de bières vous plaira. Si vous souhaitez acheter des tonneaux pour un évènement, n\’hésitez pas à me faire signe.\n\nEn attendant, que diriez-vous d\’une petite chopine ?', '', 28153),
(161178, 'frFR', 'Vous voilà ! Les troupes de Zul ont tenté de nous déloger, mais la Horde a fait la preuve de sa force. Le calme est revenu, du moins pour le moment.\n\nNous avions des raisons de penser que Zul œuvrait contre nous, mais je ne pensais pas qu\’il agirait aussi rapidement ou de façon si décisive. Ses dons de prophète n\’étaient pas exagérés.\n\nNous devons à présent défendre nos nouveaux alliés. Allez faire tout ce qui est en votre pouvoir pour restaurer l\’autorité du roi Rastakhan. La Horde se chargera de faire régner l\’ordre ici.', '', 28153),
(161177, 'frFR', 'Le premier roi à monter sur ce trône régnait sur tous les peuples civilisés de ce monde.\n\nMais aujourd\’hui, notre influence se limite à une île à peine. Même les Trolls inférieurs défient notre autorité.\n\nCette situation changera, il le faut.', '', 28153),
(161176, 'frFR', 'Vous étiez à bord de ce nouveau navire ? Dites-moi tout sur ses innovations structurelles en sirotant une bonne bière !', '', 28153),
(161175, 'frFR', 'À chaque jour suffit sa mousse !\n\nQuel genre de bière préférez-vous ?', '', 28153),
(161174, 'frFR', 'Vous avez quelque chose à réparer ?', '', 28153),
(161173, 'frFR', 'À la vôtre !', '', 28153),
(161172, 'frFR', 'Ma fille affirme que les menaces qui pèsent sur Nazmir exigent de dépêcher toute l\’armée sur notre frontière nord.\n\nElle est jeune et impatiente. Elle n\’arrive pas à se mettre dans la tête que les Trolls de sang harcèlent notre peuple depuis des générations.\n\nMais puisqu\’elle est convaincue que la Horde peut nous aider, je demande aussi à vous voir à l\’œuvre. Sans compter que traiter avec des puissances étrangères ne peut que lui être profitable.\n\nPar contre, s\’il lui arrive malheur, je réduirai votre Horde en cendres et je transformerai le pitoyable ramassis de chaloupes que vous appelez une flotte en débris flottants.\n\nBonne chance.', '', 28153),
(161171, 'frFR', 'Santé à tous !', '', 28153),
(161170, 'frFR', 'Le temps de finir mon verre et j\’irai leur donner un coup de main.', '', 28153),
(161169, 'frFR', 'Malfurion nous a fait savoir que la Légion ardente attaque le rivage Brisé !', '', 28153),
(161168, 'frFR', 'Tyrande et moi étions en couple avant que je rencontre Mildred ici.', '', 28153),
(161167, 'frFR', 'Alors, j\’ai fait ni une ni deux, et j\’ai sauvé tous les tonneaux de rhum jusqu\’au dernier !', '', 28153),
(161166, 'frFR', 'Le bateau a coulé, noyant tous ses passagers et envoyant par le fond trente tonneaux de rhum de Tiragarde.', '', 28153),
(161165, 'frFR', 'Pas moyen de se taper une bonne bière brune dans la Sylverêve. Voilà pourquoi je n\’y mets jamais les pieds.', '', 28153),
(161164, 'frFR', 'Pour Zuldazar, tout le monde à bord !', '', 28153),
(161163, 'frFR', 'Pour les îles de l\’Écho, tout le monde à bord !', '', 28153),
(161162, 'frFR', 'Ne craignez pas la marée montante de la guerre, $p. C\’est dans l\’adversité que nos forces les plus insoupçonnées émergent.', '', 28153),
(161161, 'frFR', 'Faut que vous persuadiez le roi de m\’envoyer dans un endroit où le climat est plus clément !', '', 28153),
(161160, 'frFR', 'Ce conflit ne fait que commencer, $p. J\’espère que les épreuves de la guerre ne vous font pas peur.', '', 28153),
(161159, 'frFR', 'Je crois bien qu\’il me faut une augmentation pour bosser ici. Les risques, ça se paie, $R !', '', 28153),
(161158, 'frFR', 'Si je me fais encore piquer à l\’entrejambe par une bestiole, je vais vraiment m\’énerver. Je hais cet endroit !', '', 28153),
(161157, 'frFR', 'La Horde peut bien envoyer ses meilleurs soldats nous affronter. Rien ne me ferait plus plaisir que de tester ma lame contre un ennemi digne de ce nom.', '', 28153),
(161156, 'frFR', 'Ah ! Saleté de chaleur ! Regardez, ma barbe est trempée de sueur !', '', 28153),
(161155, 'frFR', 'Si vous avez l\’occasion de donner un coup de main, n\’hésitez pas. L\’heure est bien trop grave pour attendre une autorisation.', '', 28153),
(161154, 'frFR', 'Ce bateau, c\’est l\’un des plus rapides de tout Zandalar. On va vous conduire à destination, vous en faites pas.', '', 28153),
(161153, 'frFR', 'Pour éliminer la Horde, nous devons faire preuve de ruse et de précision. Nous n\’avons pas droit à l\’erreur.', '', 28153),
(161152, 'frFR', 'Nous arrivons aux îles de l\’Écho !', '', 28153),
(161151, 'frFR', 'Nous arrivons à Zuldazar !', '', 28153),
(161150, 'frFR', 'Je viens de réagencer les tonneaux de la blonde à la brune.\n\nMais peut-être devrais-je les classer par ordre alphabétique ? Par date ? Ou encore par malt ?', '', 28153),
(161149, 'frFR', '', 'Bien le bonjour. Êtes-vous à la recherche d\’un loyal compagnon ? D\’une créature pour vous réconforter quand la tempête fait rage ? D\’un meilleur ami pour partager vos joies et vos peines ?', 28153),
(161148, 'frFR', 'Hum… ça me rappelle ma jeunesse… quand j\’apprenais le métier de mineur… Secott me disait toujours… le truc, c\’est de donner des coups de pioche en biais… pour éviter que… le minerai…', 'Beurk ! J\’ai abusé des fruits solaires…', 28153),
(161147, 'frFR', 'Merci, commandant. Sans vous, nous ne serions plus de ce monde ! Nous regagnons notre poste immédiatement !', '', 28153),
(161146, 'frFR', 'Y\’a pas à dire, ça avait vraiment un goût de « mule ».', 'Y\’a pas à dire, ça avait vraiment un goût de « mule ».', 28153),
(161145, 'frFR', 'J\’aperçois notre victoire.', 'J\’aperçois notre victoire.', 28153),
(161144, 'frFR', 'J\’ai toujours détesté cette forêt.', 'J\’ai toujours détesté cette forêt.', 28153),
(161143, 'frFR', 'Hé… c\’était un seau d\’eau sale ou quoi ?', 'Hé… c\’était un seau d\’eau sale ou quoi ?', 28153),
(161142, 'frFR', 'Nous nous emparerons de l\’arbre.', 'Nous nous emparerons de l\’arbre.', 28153),
(161141, 'frFR', 'Mmruf ! Rhaa, je déteste le gin !', 'Mmruf ! Rhaa, je déteste le gin !', 28153),
(161140, 'frFR', '', 'Le navire, il doit avoir quitté Zandalar. Il devrait plus tarder à arriver.', 28153),
(161139, 'frFR', 'Au moins, je suis mort au combat.', 'Au moins, je suis morte au combat.', 28153),
(161138, 'frFR', '', 'Il est de l\’autre côté de l\’océan, en Zandalar. Il reviendra bientôt, vous en faites pas.', 28153),
(161137, 'frFR', 'Un léger contretemps, c\’est tout ce que vous êtes.', 'Un léger contretemps, c\’est tout ce que vous êtes.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161136, 'frFR', 'J\’ai jamais rien bu d\’aussi dégueu !', 'J\’ai jamais rien bu d\’aussi dégueu !', 28153),
(161135, 'frFR', '', 'Le navire, il vient de partir pour Zandalar. Il sera bientôt de retour.', 28153),
(161134, 'frFR', '', 'Il est là, juste devant vous. Montez à bord !', 28153),
(161133, 'frFR', 'Ugh, c\’est quoi, ça ? Du vin tortollan ?', 'Ugh, c\’est quoi, ça ? Du vin tortollan ?', 28153),
(161132, 'frFR', 'Je recommande d\’associer notre brune de la pointe du Crochet aux délicieuses graines de flagellant grillées.\n\nN\’ayez crainte, combinées à la robe riche et maltée de la bière, les saveurs torréfiées des graines de flagellant feront chanter vos papilles. Cette alliance peut sembler saugrenue, mais par les marées, c\’est l\’une de mes préférées.', '', 28153),
(161131, 'frFR', 'Beurk ! J\’ai abusé des fruits solaires…', 'Beurk ! J\’ai abusé des fruits solaires…', 28153),
(161130, 'frFR', 'Je recommande d\’associer notre ambre-patine à mon péché mignon : le poulet aux épices du colonel Pilons.\n\nLes notes d\’hydromel de la bière compensent à merveille les épices du poulet. Ce délicat mariage purifie divinement les palais lorsque les épices dégagent toutes leurs saveurs !', '', 28153),
(161129, 'frFR', 'Bonjour ! Vous venez admirer ma collection ?', '', 28153),
(161128, 'frFR', 'Je vous implore de suivre son exemple. Pliez pour ne pas rompre. Et abandonnez vos ennemis sur un récif quand vous en avez fini avec eux !', 'Je vous implore de suivre son exemple. Pliez pour ne pas rompre. Et abandonnez vos ennemis sur un récif quand vous en avez fini avec eux !', 28153),
(161127, 'frFR', '', 'J\’en suis pas sûre, mais on dirait qu\’une tempête se prépare à l\’horizon.', 28153),
(161126, 'frFR', 'Les vents nous apportent bien plus que des tempêtes et la possibilité de commercer avec le reste du monde. Ils nous apportent le changement. Un changement que Pa\’ku nous a appris à supporter.', 'Les vents nous apportent bien plus que des tempêtes et la possibilité de commercer avec le reste du monde. Ils nous apportent le changement. Un changement que Pa\’ku nous a appris à supporter.', 28153),
(161125, 'frFR', 'J\’étais justement *hic !* en train de me dire que je reprendrais bien un verre…', 'J\’étais justement *hic !* en train de me dire que je reprendrais bien un verre…', 28153),
(161124, 'frFR', 'Vous avez déjà perdu !', 'Vous avez déjà perdu !', 28153),
(161123, 'frFR', 'Nous prendrons ce qui nous revient de droit !', 'Nous prendrons ce qui nous revient de droit !', 28153),
(161122, 'frFR', 'Ne vous laissez pas aveugler par les paroles malveillantes de ceux que la tempête a brisés. Écoutez plutôt ceux qui ont su plier avec le vent.', 'Ne vous laissez pas aveugler par les paroles malveillantes de ceux que la tempête a brisés. Écoutez plutôt ceux qui ont su plier avec le vent.', 28153),
(161121, 'frFR', 'Qu\’est-ce que vous avez ?', 'Qu\’est-ce que vous avez ?', 28153),
(161120, 'frFR', 'On dit qu\’elle est exigeante, capricieuse et prompte à la colère. Mais je vous défie d\’y regarder de plus près.', 'On dit qu\’elle est exigeante, capricieuse et prompte à la colère. Mais je vous défie d\’y regarder de plus près.', 28153),
(161119, 'frFR', 'Vous avez l\’honneur de périr de ma main !', 'Vous avez l\’honneur de périr de ma main !', 28153),
(161118, 'frFR', 'De la bibine gratuite ?', 'De la bibine gratuite ?', 28153),
(161117, 'frFR', 'J\’espère que ça en vaut la peine…', 'J\’espère que ça en vaut la peine…', 28153),
(161116, 'frFR', 'Ses vents, ils nous apportent la pluie, gonflent nos voiles et permettent à nos bateaux de traverser les mers. C\’est sa puissance qui fait de nous ce que nous sommes !', 'Ses vents, ils nous apportent la pluie, gonflent nos voiles et permettent à nos bateaux de traverser les mers. C\’est sa puissance qui fait de nous ce que nous sommes !', 28153),
(161115, 'frFR', 'Je recommande d\’associer notre pilsner du ponton aux saveurs acidulées de notre morue de l\’estuaire salée.\n\nLa délicate amertume de la bière contraste singulièrement avec la douceur de la morue, tandis que le houblon ajoute une touche épicée à la salinité distinctive du poisson.', '', 28153),
(161114, 'frFR', '', 'Vous allez en Zandalar ? Le navire qui accoste ici, c\’est aussi sa destination.', 28153),
(161113, 'frFR', 'J\’arrive, mon amour…', 'J\’arrive, mon amour…', 28153),
(161112, 'frFR', 'Offrir de l\’Amani Mule.', 'Offrir de l\’Amani Mule.', 28153),
(161111, 'frFR', 'Offrir du jus de Jani.', 'Offrir du jus de Jani.', 28153),
(161110, 'frFR', 'Offrir du mojo\’ito.', 'Offrir du mojo\’ito.', 28153),
(161109, 'frFR', 'Offrir du gin de Zul.', 'Offrir du gin de Zul.', 28153),
(161108, 'frFR', 'Offrir du bwonzombie.', 'Offrir du bwonzombie.', 28153),
(161107, 'frFR', 'Offrir du punch des cavernes.', 'Offrir du punch des cavernes.', 28153),
(161106, 'frFR', 'Je recommande d\’agrémenter notre dunkel jette-l\’ancre d\’un bon brunost de Hatherford.\n\nJ\’aime allier bières et fromages de qualité, et ces deux-là se marient à la perfection. Ils dégagent tous deux une douce saveur caramélisée et cet assemblage révèle leurs plus subtils arômes.', '', 28153),
(161105, 'frFR', 'Offrir du fouette-troll.', 'Offrir du fouette-troll.', 28153),
(161104, 'frFR', 'Que la mort vous emporte…', 'Que la mort vous emporte…', 28153),
(161103, 'frFR', '', 'La mort d\’un allié au combat ne fait que rendre mes mascottes plus fortes.', 28153),
(161102, 'frFR', 'Pourquoi les oiseaux sont-ils si silencieux ?', 'Pourquoi les oiseaux sont-ils si silencieux ?', 28153),
(161101, 'frFR', 'Dame Tyrande vous arrêtera.', 'Dame Tyrande vous arrêtera.', 28153),
(161100, 'frFR', '', 'Les espèces de Zandalar sont très puissantes. Vos autres mascottes n\’ont aucune chance.', 28153),
(161099, 'frFR', 'N\’acculez jamais un sabre-de-nuit blessé…', 'N\’acculez jamais un sabre-de-nuit blessé…', 28153),
(161098, 'frFR', 'Cette terre est à nous !', 'Cette terre est à nous !', 28153),
(161097, 'frFR', '', 'Je ne m\’attendais pas à ça. Mais je compte bien prendre ma revanche.', 28153),
(161096, 'frFR', '', 'On dirait que me battre à domicile m\’a avantagée.', 28153),
(161095, 'frFR', 'Bonjour l\’honneur !', 'Bonjour l\’honneur !', 28153),
(161094, 'frFR', '', 'Vous venez m\’affronter sur mon propre territoire ? Je vous souhaite bonne chance.', 28153),
(161093, 'frFR', 'Je ne veux pas vous tuer, mais je n\’hésiterai pas.', 'Je ne veux pas vous tuer, mais je n\’hésiterai pas.', 28153),
(161092, 'frFR', '', 'Je n\’ai peut-être pas capturé la créature la plus coriace de la région. Je devrais continuer à chercher.', 28153),
(161091, 'frFR', 'Je recommande d\’agrémenter notre bière à la symphorine d\’une touche de crème à la symphorine !\n\nCe subtil mariage dévoilera tous les arômes de cette plante dans une singulière dichotomie : l\’acidité de la bière et la douceur délicate de la crème. L\’onctuosité de la crème compense l\’amertume de la bière dans une sublime aventure gustative.', '', 28153),
(161090, 'frFR', '', 'Ça va sûrement laisser une cicatrice.', 28153),
(161089, 'frFR', '', 'Je vais continuer à entraîner ces nouvelles espèces et je serai prête pour notre prochain combat.', 28153),
(161088, 'frFR', '', 'Comme je le disais, les créatures de cette région sont féroces. Cela dit, ce fut un beau combat.', 28153),
(161087, 'frFR', '', 'Les créatures de cette région sont féroces. J\’espère que vous êtes d\’attaque.', 28153),
(161086, 'frFR', '', 'Ne t\’en fais pas, je vais prendre soin de toi.', 28153),
(161085, 'frFR', 'Rien n\’échappe à la mort.', 'Rien n\’échappe à la mort.', 28153),
(161084, 'frFR', '', 'Ne soyez pas triste d\’avoir perdu ! Vos autres mascottes ont l\’air drôlement fortiches !', 28153),
(161083, 'frFR', 'Je voulais seulement protéger mon foyer.', 'Je voulais seulement protéger mon foyer.', 28153),
(161082, 'frFR', '', 'Je manque peut-être d\’entraînement.', 28153),
(161081, 'frFR', 'J\’espère rêver…', 'J\’espère rêver…', 28153),
(161080, 'frFR', '', 'Ça alors ! Mon équipe est bien plus forte que ce que je pensais.', 28153),
(161079, 'frFR', 'Les feuilles tombent…', 'Les feuilles tombent…', 28153),
(161078, 'frFR', 'J\’aurais aimé avoir le temps de vous tuer lentement.', 'J\’aurais aimé avoir le temps de vous tuer lentement.', 28153),
(161077, 'frFR', '', 'Mon dernier combat date un peu. J\’espère que je serai à la hauteur !', 28153),
(161076, 'frFR', 'Sortez vos griffes !', 'Sortez vos griffes !', 28153),
(161075, 'frFR', 'Que les épines vous transpercent !', 'Que les épines vous transpercent !', 28153),
(161074, 'frFR', '', 'Je n\’étais pas prête, ça ne compte pas !', 28153),
(161073, 'frFR', 'Je vengerai la forêt !', 'Je vengerai la forêt !', 28153),
(161072, 'frFR', '', 'Ma série de victoires ne va pas s\’arrêter de sitôt, semble-t-il !', 28153),
(161071, 'frFR', 'Je recommande d\’agrémenter notre kölsch du marché des Alizés de mon pain de seigle au cumin maison.\n\nL\’onctuosité de la bière s\’allie parfaitement au robuste parfum du seigle, tout en purifiant le palais grâce à sa gazéification.', '', 28153),
(161070, 'frFR', '', 'Ça ne compte pas vraiment comme une défaite. Ma série de victoires reste intacte.', 28153),
(161069, 'frFR', '', 'Et une victoire de plus à ma série, une !', 28153),
(161068, 'frFR', '', 'J\’enchaîne les victoires en ce moment, vous n\’avez aucune chance contre moi et mon équipe !', 28153),
(161067, 'frFR', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|tL\’avatar n\’est plus |cFFFF0000|Hspell:274148|h[Corrompu]|h|r, l\’efficacité de vos soins est à présent totale !', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|tL\’avatar n\’est plus |cFFFF0000|Hspell:274148|h[Corrompu]|h|r, l\’efficacité de vos soins est à présent totale !', 28153),
(161066, 'frFR', 'Face à la défaite, il ne faut pas battre en retraite, mais au contraire aller de l\’avant pour relever le défi.', '', 28153),
(161065, 'frFR', 'J\’aimerais commander à manger.', 'J\’aimerais commander à manger.', 28153),
(161064, 'frFR', 'La victoire est à ma portée, je le sens !', '', 28153),
(161063, 'frFR', 'Rendez grâce à Gonk, unissez-vous à sa meute, mais sachez que les autres voies, elles vous restent ouvertes. Tel est son présent aux Zandalari.', 'Rendez grâce à Gonk, unissez-vous à sa meute, mais sachez que les autres voies, elles vous restent ouvertes. Tel est son présent aux Zandalari.', 28153),
(161062, 'frFR', 'Mais grande est la sagesse de Gonk. Il sait que l\’union fait la force. Il n\’exige pas que son idole soit la seule à orner votre autel.', 'Mais grande est la sagesse de Gonk. Il sait que l\’union fait la force. Il n\’exige pas que son idole soit la seule à orner votre autel.', 28153),
(161061, 'frFR', 'Que recommandez-vous pour agrémenter la brune de la pointe du Crochet ?', 'Que recommandez-vous pour agrémenter la brune de la pointe du Crochet ?', 28153),
(161060, 'frFR', 'Incroyable, je n\’avais pas perdu de match depuis des années. Bravo !', '', 28153),
(161059, 'frFR', 'Continuez à vous entraîner et vous pourrez bientôt vous mesurer à moi !', '', 28153),
(161058, 'frFR', 'Que recommandez-vous pour agrémenter l\’ambre-patine ?', 'Que recommandez-vous pour agrémenter l\’ambre-patine ?', 28153),
(161057, 'frFR', 'Que recommandez-vous pour agrémenter la pilsner du ponton ?', 'Que recommandez-vous pour agrémenter la pilsner du ponton ?', 28153),
(161056, 'frFR', 'Que recommandez-vous pour agrémenter la dunkel jette-l\’ancre ?', 'Que recommandez-vous pour agrémenter la dunkel jette-l\’ancre ?', 28153),
(161055, 'frFR', 'Que recommandez-vous pour agrémenter la bière à la symphorine ?', 'Que recommandez-vous pour agrémenter la bière à la symphorine ?', 28153),
(161054, 'frFR', 'Que recommandez-vous pour agrémenter la kölsch du marché des Alizés ?', 'Que recommandez-vous pour agrémenter la kölsch du marché des Alizés ?', 28153),
(161053, 'frFR', 'Les autres Loas, ils furent d\’abord courroucés. Ils lui crachèrent dessus, le traitèrent de faible pour avoir accepté moins que son dû.', 'Les autres Loas, ils furent d\’abord courroucés. Ils lui crachèrent dessus, le traitèrent de faible pour avoir accepté moins que son dû.', 28153),
(161052, 'frFR', 'Il dit alors à ses fidèles, « Choisissez librement la voie qui vous convient. Nous ne formons qu\’une seule et même meute à mes yeux. »', 'Il dit alors à ses fidèles, « Choisissez librement la voie qui vous convient. Nous ne formons qu\’une seule et même meute à mes yeux. »', 28153),
(161051, 'frFR', 'Vous cherchez un mets raffiné pour accompagner votre bière ?\n\nJ\’ai précisément ce qu\’il vous faut.', '', 28153),
(161050, 'frFR', 'Lorsqu\’il tourna son regard sur son peuple, le Loa de la métamorphose découvrit ses innombrables besoins. Des besoins qu\’il ne pouvait satisfaire.', 'Lorsqu\’il tourna son regard sur son peuple, le Loa de la métamorphose découvrit ses innombrables besoins. Des besoins qu\’il ne pouvait satisfaire.', 28153),
(161049, 'frFR', 'Pensez-y, ô mes frères et mes sœurs. Et que la sagesse guide vos choix.', 'Pensez-y, ô mes frères et mes sœurs. Et que la sagesse guide vos choix.', 28153),
(161048, 'frFR', 'Ou serez-vous tourmenté jusqu\’à ce que le soleil s\’éteigne dans le ciel ?', 'Ou serez-vous tourmenté jusqu\’à ce que le soleil s\’éteigne dans le ciel ?', 28153),
(161047, 'frFR', 'Rirez-vous avec lui ? Danserez-vous avec les autres morts reconnaissants ?', 'Rirez-vous avec lui ? Danserez-vous avec les autres morts reconnaissants ?', 28153),
(161046, 'frFR', 'Bwonsamdi, est-ce qu\’il vous accueillera en ami quand il sera temps pour votre esprit de passer de l\’Autre côté ?', 'Bwonsamdi, est-ce qu\’il vous accueillera en ami quand il sera temps pour votre esprit de passer de l\’Autre côté ?', 28153),
(161045, 'frFR', 'Mais je suis ici pour vous rappeler que Bwonsamdi, il s\’intéresse aussi à notre monde. Il observe. Il évalue sans cesse.', 'Mais je suis ici pour vous rappeler que Bwonsamdi, il s\’intéresse aussi à notre monde. Il observe. Il évalue sans cesse.', 28153),
(161044, 'frFR', 'Certains se disent même qu\’un tel Loa, il n\’a pas sa place sur l\’autel d\’un vivant.', 'Certains se disent même qu\’un tel Loa, il n\’a pas sa place sur l\’autel d\’un vivant.', 28153),
(161043, 'frFR', 'Krag\’wa, il est revenu, et voici les leçons qu\’il apporte aux Zandalari.', 'Krag\’wa, il est revenu, et voici les leçons qu\’il apporte aux Zandalari.', 28153),
(161042, 'frFR', 'À tous ceux qui cherchent le courage et la force de protéger autrui, ou la volonté de poursuivre ce qu\’ils ont entrepris, je dis : ne cherchez plus.', 'À tous ceux qui cherchent le courage et la force de protéger autrui, ou la volonté de poursuivre ce qu\’ils ont entrepris, je dis : ne cherchez plus.', 28153),
(161041, 'frFR', 'Mes frères, mes sœurs, je ne peux que vous encourager à suivre fidèlement son exemple. Cultivez comme lui la force de protéger ce qui vous appartient.', 'Mes frères, mes sœurs, je ne peux que vous encourager à suivre fidèlement son exemple. Cultivez comme lui la force de protéger ce qui vous appartient.', 28153),
(161040, 'frFR', 'Il a prouvé que même la menace de l\’anéantissement, elle ne pouvait l\’empêcher de défendre les siens.', 'Il a prouvé que même la menace de l\’anéantissement, elle ne pouvait l\’empêcher de défendre les siens.', 28153),
(161039, 'frFR', 'Mais je suis ici pour vous annoncer que le gardien nous est revenu et que sa force est intacte.', 'Mais je suis ici pour vous annoncer que le gardien nous est revenu et que sa force est intacte.', 28153),
(161038, 'frFR', 'C\’est toujours un plaisir de combattre un nouvel adversaire.', '', 28153),
(161037, 'frFR', 'C\’est l\’heure d\’aller récupérer des bandages de mascottes.', '', 28153),
(161036, 'frFR', 'Beau combat. Il faudra juste s\’entraîner pour s\’améliorer !', '', 28153),
(161035, 'frFR', 'Zut, je déteste perdre. Mais vous avez bien combattu.', '', 28153),
(161034, 'frFR', 'Et quand les nouvelles tempêtes, elles viendront, vous verrez en elles la chance d\’un nouveau départ. Vous ne craindrez plus les nuages qui s\’amoncellent à l\’horizon.', 'Et quand les nouvelles tempêtes, elles viendront, vous verrez en elles la chance d\’un nouveau départ. Vous ne craindrez plus les nuages qui s\’amoncellent à l\’horizon.', 28153),
(161033, 'frFR', 'J\’ai gagné ? Génial, je vais le dire à tous mes amis !', '', 28153),
(161032, 'frFR', 'C\’est parti pour la grande aventure !', '', 28153),
(161031, 'frFR', 'Notre force et notre détermination, elles seront mises à rude épreuve. Ceux qui seront encore debout une fois les nuages dispersés n\’en seront que plus forts.', 'Notre force et notre détermination, elles seront mises à rude épreuve. Ceux qui seront encore debout une fois les nuages dispersés n\’en seront que plus forts.', 28153),
(161030, 'frFR', 'Cette mascotte me mettait mal à l\’aise, de toute façon. Ce n\’est pas une grosse perte.', '', 28153),
(161029, 'frFR', 'Oui, il y a de la fureur dans ses éclairs et de la colère dans le tonnerre. Mais ainsi va le changement.', 'Oui, il y a de la fureur dans ses éclairs et de la colère dans le tonnerre. Mais ainsi va le changement.', 28153),
(161028, 'frFR', 'Ses vents, ils ravageront la terre pour lui permettre de renaître.', 'Ses vents, ils ravageront la terre pour lui permettre de renaître.', 28153),
(161027, 'frFR', 'Vous feriez bien de vous en occuper avant qu\’elle ne finisse en sacrifice pour un rituel de sang.', '', 28153),
(161026, 'frFR', 'Akunda, il nous apprend à ne pas craindre la tempête qui se lève à l\’horizon, car ses pluies emporteront les souffrances du passé.', 'Akunda, il nous apprend à ne pas craindre la tempête qui se lève à l\’horizon, car ses pluies emporteront les souffrances du passé.', 28153),
(161025, 'frFR', 'Cet endroit est maudit, je n\’ai jamais essuyé de défaite aussi cuisante.', '', 28153),
(161024, 'frFR', 'C\’était un combat intéressant, mais nous ne jouons clairement pas dans la même catégorie.', '', 28153),
(161023, 'frFR', 'Cet endroit me file les jetons, terminons-en au plus vite.', '', 28153),
(161022, 'frFR', 'Espèce de monstre ! C\’était ma mascotte préférée !', '', 28153),
(161021, 'frFR', 'Un autre adversaire qui mord la poussière.', '', 28153),
(161020, 'frFR', 'Si c\’est une chope que vous voulez, vous avez frappé à la bonne porte !\n\nDans le cas contraire, adressez-vous ailleurs, ça vaudra mieux pour tout le monde.', '', 28153),
(161019, 'frFR', '', 'Tout à fait ! Voilà !', 28153),
(161018, 'frFR', 'Je déteste perdre ! Je vais m\’entraîner pour la prochaine fois, comptez sur moi !', '', 28153),
(161017, 'frFR', 'Auriez-vous un seau de lait sous la main ?', 'Auriez-vous un seau de lait sous la main ?', 28153),
(161016, 'frFR', 'Une nouvelle victoire pour la meilleure équipe : moi !', '', 28153),
(161015, 'frFR', 'C\’est l\’heure de se jeter au cœur du combat ! Allons-y !', '', 28153),
(161014, 'frFR', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|tUne |cFFFF0000|Hspell:269688|h[Pluie]|h|r de crapauds s\’abat !', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|tUne |cFFFF0000|Hspell:269688|h[Pluie]|h|r de crapauds s\’abat !', 28153),
(161013, 'frFR', '', 'Vous savez, vous êtes plutôt pas mal.', 28153),
(161012, 'frFR', '', 'Si vous avez besoin de quoi que ce soit, n\’hésitez pas à me demander !', 28153),
(161011, 'frFR', '', 'Une mascotte perdue en combat inspire les autres à se battre encore plus férocement.', 28153),
(161010, 'frFR', '', 'Je ne sais comment vous remercier d\’avoir sauvé Millie.', 28153),
(161009, 'frFR', '', 'Salutations, $p. C\’est toujours un plaisir de vous voir.', 28153),
(161008, 'frFR', '', 'Ha ha ! Une mascotte de moins !', 28153),
(161007, 'frFR', '', 'Je vais m\’entraîner afin d\’être prête pour notre prochain combat.', 28153),
(161006, 'frFR', '', 'Ne laissez pas cette défaite vous attrister. Apprenez de vos erreurs et montrez-vous à la hauteur du défi.', 28153),
(161005, 'frFR', '', 'Bon sang, il était temps qu\’on reçoive des renforts musclés !', 28153),
(161004, 'frFR', '', 'Combattons avec honneur.', 28153),
(161003, 'frFR', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tUn fragment d\’énergie se forme à proximité, utilisez-le pour |cFFFF0000|Hspell:274149|h[dynamiser]|h|r l\’avatar !', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tUn fragment d\’énergie se forme à proximité, utilisez-le pour |cFFFF0000|Hspell:274149|h[dynamiser]|h|r l\’avatar !', 28153),
(161002, 'frFR', '<Laisser un moment à Genn pour qu\’il s\’entretienne avec Katherine.>', '<Laisser un moment à Genn pour qu\’il s\’entretienne avec Katherine.>', 28153),
(161001, 'frFR', 'C\’est l\’occasion ou jamais !', 'C\’est l\’occasion ou jamais !', 28153),
(161000, 'frFR', 'Prenez vos affaires, vite !', 'Prenez vos affaires, vite !', 28153),
(160999, 'frFR', 'Allons-y !', 'Allons-y !', 28153),
(160998, 'frFR', 'Dépêchez-vous, sortons d\’ici !', 'Dépêchez-vous, sortons d\’ici !', 28153),
(160997, 'frFR', 'Un gardien prend forme à proximité pour protéger le cœur de Sephraliss.', 'Un gardien prend forme à proximité pour protéger le cœur de Sephraliss.', 28153),
(160996, 'frFR', 'Les disciples de Jakra\’zet se ruent sur le cœur de Sephraliss.', 'Les disciples de Jakra\’zet se ruent sur le cœur de Sephraliss.', 28153),
(160995, 'frFR', 'En pleine nature, il est fréquent de croiser des ours, des loups, et des chèvres voraces !', '', 28153),
(160994, 'frFR', 'Je pense que vous êtes réglo, mais je préfère garder mes distances.', '', 28153),
(160993, 'frFR', 'Je ne veux pas faire de mal à l\’animal, je veux simplement le mettre en garde.', '', 28153),
(160992, 'frFR', 'Néanmoins, il faut également rester sur ses gardes, c\’est pourquoi je ne sors jamais sans prendre mes précautions.', '', 28153),
(160991, 'frFR', 'Ça peut paraître étonnant, mais se promener en pleine nature fait partie des meilleures choses de la vie.', '', 28153),
(160990, 'frFR', 'Et voici un pin. Il est aisément reconnaissable à sa forme arboricole !', '', 28153),
(160989, 'frFR', 'Saviez-vous qu\’on les appelle chutes d\’eau en raison de l\’eau qui chute ?', '', 28153),
(160988, 'frFR', 'Les chutes d\’eau sont majestueuses… elles subjuguent par leur majesté.', '', 28153),
(160987, 'frFR', 'Ce que nous voyons ici s\’appelle une chute d\’eau.', '', 28153),
(160986, 'frFR', 'Alors là, impressionnant !', '', 28153),
(160985, 'frFR', 'Wahou, c\’est magnifique !', '', 28153),
(160984, 'frFR', 'Et c\’est ainsi que le seigneur des bêtes, il enseigna à ses fidèles les vertus que sont le courage et la conviction.', 'Et c\’est ainsi que le seigneur des bêtes, il enseigna à ses fidèles les vertus que sont le courage et la conviction.', 28153),
(160983, 'frFR', 'La puissance prend sa source non dans la force brute, mais dans la volonté indomptable qui, par nature, est insensible aux outrages du temps.', 'La puissance prend sa source non dans la force brute, mais dans la volonté indomptable qui, par nature, est insensible aux outrages du temps.', 28153),
(160982, 'frFR', 'À l\’instar de la flétrissure qui ronge peu à peu les fleurs de la jungle, l\’âge sape l\’énergie de la jeunesse.', 'À l\’instar de la flétrissure qui ronge peu à peu les fleurs de la jungle, l\’âge sape l\’énergie de la jeunesse.', 28153),
(160981, 'frFR', 'Faites preuve de courage en toutes circonstances et jamais votre proie ne vous échappera.', 'Faites preuve de courage en toutes circonstances et jamais votre proie ne vous échappera.', 28153),
(160980, 'frFR', 'À l\’image du tigre qui traque son gibier sans relâche par monts et par vaux, le brave ne cède pas une seule seconde face à la peur.', 'À l\’image du tigre qui traque son gibier sans relâche par monts et par vaux, le brave ne cède pas une seule seconde face à la peur.', 28153),
(160979, 'frFR', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 28153),
(160978, 'frFR', 'Et c\’est ainsi que le roi des félins, il enseigna à ses fidèles la vertu du dévouement.', 'Et c\’est ainsi que le roi des félins, il enseigna à ses fidèles la vertu du dévouement.', 28153),
(160977, 'frFR', 'Vivez votre vie avec détermination, et l\’échec n\’aura jamais raison de vous.', 'Vivez votre vie avec détermination, et l\’échec n\’aura jamais raison de vous.', 28153),
(160976, 'frFR', 'À l\’instar de l\’eau vive qui creuse inlassablement ses sillons dans la pierre, tous les hauts faits sont le fruit de la persévérance.', 'À l\’instar de l\’eau vive qui creuse inlassablement ses sillons dans la pierre, tous les hauts faits sont le fruit de la persévérance.', 28153),
(160975, 'frFR', 'Vivez votre vie dans l\’honneur, et vous aurez bien vécu.', 'Vivez votre vie dans l\’honneur, et vous aurez bien vécu.', 28153),
(160974, 'frFR', 'À l\’image du roi qui jamais n\’échangerait son plus précieux trésor contre une vulgaire poignée de terre, l\’homme d\’honneur ne brade pas son intégrité sur l\’autel de la gloire ou de la richesse.', 'À l\’image du roi qui jamais n\’échangerait son plus précieux trésor contre une vulgaire poignée de terre, l\’homme d\’honneur ne brade pas son intégrité sur l\’autel de la gloire ou de la richesse.', 28153),
(160973, 'frFR', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 28153),
(160972, 'frFR', 'Et c\’est ainsi que la malédiction des proies, elle enseigna à ses fidèles les vertus que sont la patience et le respect.', 'Et c\’est ainsi que la malédiction des proies, elle enseigna à ses fidèles les vertus que sont la patience et le respect.', 28153),
(160971, 'frFR', 'Partant, il respecte l\’ordre naturel et ne prend que le strict nécessaire pour survivre.', 'Partant, il respecte l\’ordre naturel et ne prend que le strict nécessaire pour survivre.', 28153),
(160970, 'frFR', 'L\’homme clairvoyant voit bien que la nature ne lui appartient pas, mais que c\’est lui qui appartient à la nature.', 'L\’homme clairvoyant voit bien que la nature ne lui appartient pas, mais que c\’est lui qui appartient à la nature.', 28153),
(160969, 'frFR', 'En outre, si la jungle fait naître la vie, elle donne aussi la mort.', 'En outre, si la jungle fait naître la vie, elle donne aussi la mort.', 28153),
(160968, 'frFR', 'Seuls les insensés se laissent gouverner par leurs passions et leurs émotions, mais ceux-là ne survivent guère dans la jungle.', 'Seuls les insensés se laissent gouverner par leurs passions et leurs émotions, mais ceux-là ne survivent guère dans la jungle.', 28153),
(160967, 'frFR', 'À l\’image du jaguar qui traque sa proie des jours durant, le sage cultive la patience en toutes circonstances.', 'À l\’image du jaguar qui traque sa proie des jours durant, le sage cultive la patience en toutes circonstances.', 28153),
(160966, 'frFR', 'Et pas seulement survivre, mais prospérer ! Alors, soyez fiers de vivre dans le caniveau ! Car là est le royaume de Jani.', 'Et pas seulement survivre, mais prospérer ! Alors, soyez fiers de vivre dans le caniveau ! Car là est le royaume de Jani.', 28153),
(160965, 'frFR', 'Jani, il n\’exige ni prières compliquées ni sacrifices coûteux, mais seulement de survivre au nez et à la barbe de ceux qui oppriment les exclus.', 'Jani, il n\’exige ni prières compliquées ni sacrifices coûteux, mais seulement de survivre au nez et à la barbe de ceux qui oppriment les exclus.', 28153),
(160964, 'frFR', 'Là où les autres, ils prennent, Jani donne ! Il donne à ceux qui se débrouillent par eux-mêmes. Ceux que méprisent les puissants et les cossus.', 'Là où les autres, ils prennent, Jani donne ! Il donne à ceux qui se débrouillent par eux-mêmes. Ceux que méprisent les puissants et les cossus.', 28153),
(160963, 'frFR', 'Jani, il est plus grand que tous les autres et moi, je vais vous expliquer pourquoi !', 'Jani, il est plus grand que tous les autres et moi, je vais vous expliquer pourquoi !', 28153),
(160962, 'frFR', 'Mais ces Loas, ils quémandent les louanges de leurs fidèles.', 'Mais ces Loas, ils quémandent les louanges de leurs fidèles.', 28153),
(160961, 'frFR', 'Les Ulterres… dévorent tout…', '', 28153),
(160960, 'frFR', 'Il n\’existe… aucune échappatoire…', '', 28153),
(160959, 'frFR', 'Il n\’y a plus d\’espoir…', '', 28153),
(160958, 'frFR', 'Je vais vous réduire en charpie !', '', 28153),
(160957, 'frFR', 'Vous vous tordrez de douleur !', '', 28153),
(160956, 'frFR', 'Je crache sur votre Loa de cossu !', 'Je crache sur votre Loa de cossu !', 28153),
(160955, 'frFR', 'Souffrez !', '', 28153),
(160954, 'frFR', 'On se disperse !', 'On se disperse !', 28153),
(160953, 'frFR', 'Jani, c\’est le Loa qu\’il me faut ! Ha ha ha !', 'Jani, c\’est le Loa qu\’il me faut ! Ha ha ha !', 28153),
(160952, 'frFR', 'On va être riches grâce à Jani !', 'On va être riches grâce à Jani !', 28153),
(160951, 'frFR', 'Ces célébrations stupides commencent à bien faire ! Disparaissez !', 'Ces célébrations stupides commencent à bien faire ! Disparaissez !', 28153),
(160950, 'frFR', 'Vous vous moquez de nous ? Allez-vous-en !', 'Vous vous moquez de nous ? Allez-vous-en !', 28153),
(160949, 'frFR', 'Vous offensez les véritables Loas ! Fichez le camp avec ces détritus !', 'Vous offensez les véritables Loas ! Fichez le camp avec ces détritus !', 28153),
(160948, 'frFR', 'Ce bon à rien de Jani sème toujours la pagaille ! Allez, ouste ! Du vent !', 'Ce bon à rien de Jani sème toujours la pagaille ! Allez, ouste ! Du vent !', 28153),
(160947, 'frFR', 'Ça ne fera pas l\’affaire ! Partageons la bénédiction de mon Loa !', 'Ça ne fera pas l\’affaire ! Partageons la bénédiction de mon Loa !', 28153),
(160946, 'frFR', 'Je crains d\’être arrivé en retard…', 'Je crains d\’être arrivée en retard…', 28153),
(160945, 'frFR', 'Une telle dévotion me fait monter les larmes aux yeux. Vous avez vu la générosité du Loa ?', 'Une telle dévotion me fait monter les larmes aux yeux. Vous avez vu la générosité du Loa ?', 28153),
(160944, 'frFR', 'Le rituel, il va bientôt commencer, $n.\n\nDes gens de tous horizons viennent des quatre coins de Zandalar pour écouter les enseignements de leurs Loas. Et bon nombre d\’entre eux espèrent recevoir une bénédiction. Peut-être que les Loas, ils vous en accorderont une à vous aussi !\n\nRestez pour honorer les Loa aux côtés des Zandalari.', 'Le rituel va bientôt commencer, $n.\n\nDes gens de tous horizons viennent des quatre coins de Zandalar pour écouter les enseignements de leurs Loas. Et bon nombre d\’entre eux espèrent recevoir une bénédiction. Peut-être les Loas vous en accorderont-ils une à vous aussi !\n\nRestez pour honorer les Loa aux côtés des Zandalari.', 28153),
(160943, 'frFR', 'Vous allez regretter… d\’être en vie…', '', 28153),
(160942, 'frFR', 'Vos cris retentiront pour l\’éternité !', '', 28153),
(160941, 'frFR', 'Nous assouvirons… notre vengeance…', '', 28153),
(160940, 'frFR', 'Elle appartient à Gorak Tul !', '', 28153),
(160939, 'frFR', 'Vous ne prendrez jamais ce qui est à nous !', '', 28153),
(160938, 'frFR', 'Tu étais à mes côtés à Fossoyeuse. Nous les tenions ! J\’aurais pu rendre justice !', '', 28153),
(160937, 'frFR', 'Hé, vous semblez avoir besoin d\’un verre. Que diriez-vous d\’une petite bière ?', '', 28153),
(160936, 'frFR', 'Je commence à brasser une nouvelle bière avec du miel Chantorage de premier choix.\n\nIl n\’était franchement pas donné, mais je suis convaincu que ça en vaut la peine !', '', 28153),
(160935, 'frFR', '', 'Que diriez-vous d\’une petite pinte ? Si vous avez besoin d\’un coup de fouet, j\’ai également préparé du café !', 28153),
(160934, 'frFR', 'Je vais me faire un tas d\’oseille ! Youhou !', 'Je vais me faire un tas d\’oseille ! Youhou !', 28153),
(160933, 'frFR', 'Votre Loa n\’est pas le bienvenu ici ! Disparaissez !', 'Votre Loa n\’est pas le bienvenu ici ! Disparaissez !', 28153),
(160932, 'frFR', 'Le Dieu des ordures, il vous accorde sa bénédiction ! Ha ha ha !', 'Le Dieu des ordures, il vous accorde sa bénédiction ! Ha ha ha !', 28153),
(160931, 'frFR', 'Les autres, ils vous diront que leur Loa est le plus généreux, ou le plus fort, ou le plus enclin à la colère.', 'Les autres, ils vous diront que leur Loa est le plus généreux, ou le plus fort, ou le plus enclin à la colère.', 28153),
(160930, 'frFR', 'Ha ha ha ! Il est temps de faire l\’éloge du Loa du peuple. Approchez des marches de Dazar\’alor pour rendre hommage à Jani !', 'Ha ha ha ! Il est temps de faire l\’éloge du Loa du peuple. Approchez des marches de Dazar\’alor pour rendre hommage à Jani !', 28153),
(160929, 'frFR', 'Sauf un retard imprévu, le bateau devrait avoir quitté les îles de l\’Écho. Il va plus tarder.', '', 28153),
(160928, 'frFR', 'Peuple de Zandalar ! L\’heure, elle est venue de louer la divinité des vents, la reine des cieux, la matrone des mers ! Venez au pied des marches rendre hommage à Pa\’ku.', 'Peuple de Zandalar ! L\’heure, elle est venue de louer la divinité des vents, la reine des cieux, la matrone des mers ! Venez au pied des marches rendre hommage à Pa\’ku.', 28153),
(160927, 'frFR', 'Tous ceux qui se tiennent devant moi, ils ont un jour ressenti la bénédiction de mon Loa, Pa\’ku.', 'Tous ceux qui se tiennent devant moi, ils ont un jour ressenti la bénédiction de mon Loa, Pa\’ku.', 28153),
(160926, 'frFR', 'Louée soit Pa\’ku ! Puissent ses vents gonfler vos voiles !', 'Louée soit Pa\’ku ! Puissent ses vents gonfler vos voiles !', 28153),
(160925, 'frFR', 'Gonk, il nous accorde sa bénédiction ! Puisse la meute être toujours avec vous !', 'Gonk, il nous accorde sa bénédiction ! Puisse la meute être toujours avec vous !', 28153),
(160924, 'frFR', 'Soyez les bienvenus, ô mes frères et mes sœurs. L\’esprit de Gonk, il est avec nous aujourd\’hui.', 'Soyez les bienvenus, ô mes frères et mes sœurs. L\’esprit de Gonk, il est avec nous aujourd\’hui.', 28153),
(160923, 'frFR', 'Peuple de Zandalar ! Le Loa de la métamorphose, il attend les louanges de ses fidèles. Élevons nos voix vers le seigneur de la meute, le plus généreux des Loas ! Loué soit Gonk !', 'Peuple de Zandalar ! Le Loa de la métamorphose, il attend les louanges de ses fidèles. Élevons nos voix vers le seigneur de la meute, le plus généreux des Loas ! Loué soit Gonk !', 28153),
(160922, 'frFR', 'Frères et sœurs zandalari ! Le puissant Krag\’wa est revenu ! Venez rendre hommage au grand gardien sur les marches de Dazar\’alor !', 'Frères et sœurs zandalari ! Le puissant Krag\’wa est revenu ! Venez rendre hommage au grand gardien sur les marches de Dazar\’alor !', 28153),
(160921, 'frFR', 'On m\’a souvent dit que Krag\’wa, le grand crapaud, il ne serait qu\’un mythe, qu\’une légende.', 'On m\’a souvent dit que Krag\’wa, le grand crapaud, il ne serait qu\’un mythe, qu\’une légende.', 28153),
(160920, 'frFR', 'Le grand gardien, il nous offre sa protection ! Loué soit Krag\’wa !', 'Le grand gardien, il nous offre sa protection ! Loué soit Krag\’wa !', 28153),
(160919, 'frFR', 'Bwonsamdi, il observe chacun d\’entre nous. Montrez-vous dignes de sa bénédiction !', 'Bwonsamdi, il observe chacun d\’entre nous. Montrez-vous dignes de sa bénédiction !', 28153),
(160918, 'frFR', 'Vous connaissez tous Bwonsamdi. « Pour sûr ! C\’est le Loa de la mort ! », pensez-vous.', 'Vous connaissez tous Bwonsamdi. « Pour sûr ! C\’est le Loa de la mort ! », pensez-vous.', 28153),
(160917, 'frFR', 'Que les esprits, ils soient avec nous ! Approchez des marches de Dazar\’alor et venez louer celui qui veille sur nos morts. Rendez grâce à Bwonsamdi !', 'Que les esprits, ils soient avec nous ! Approchez des marches de Dazar\’alor et venez louer celui qui veille sur nos morts. Rendez grâce à Bwonsamdi !', 28153),
(160916, 'frFR', 'Le bateau a jeté l\’ancre dans les îles de l\’Écho. Mais il devrait plus tarder à reprendre la mer. Il sera ici sous peu.', '', 28153),
(160915, 'frFR', '', 'Ne faites pas attention à l\’ardoise. Elle n\’est pas terminée.', 28153),
(160914, 'frFR', 'Vous venez juste de louper le bateau. Il fait voile vers les îles de l\’Écho, mais il repassera bientôt ici.', '', 28153),
(160913, 'frFR', 'Frères et sœurs zandalari ! Approchez des marches de Dazar\’alor pour recevoir les enseignements de celui qu\’on nomme le roi des félins, la malédiction des proies et le seigneur des bêtes. Loué soit Kimbul !', 'Frères et sœurs zandalari ! Approchez des marches de Dazar\’alor pour recevoir les enseignements de celui qu\’on nomme le roi des félins, la malédiction des proies et le seigneur des bêtes. Loué soit Kimbul !', 28153),
(160912, 'frFR', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 'Venez écouter en quels termes mon Loa, il s\’est adressé à ses disciples.', 28153),
(160911, 'frFR', 'Que la malédiction des proies bénisse vos chasses !', 'Que la malédiction des proies bénisse vos chasses !', 28153),
(160910, 'frFR', 'Recevez la bénédiction d\’Akunda !', 'Recevez la bénédiction d\’Akunda !', 28153),
(160909, 'frFR', 'Approchez tous, venez écouter les enseignements d\’Akunda, le Loa des tempêtes et des nouveaux départs.', 'Approchez tous, venez écouter les enseignements d\’Akunda, le Loa des tempêtes et des nouveaux départs.', 28153),
(160908, 'frFR', 'Une tempête approche ! Mes frères, mes sœurs, laissez la pluie laver vos soucis. Venez louer Akunda sur les marches de Dazar\’alor !', 'Une tempête approche ! Mes frères, mes sœurs, laissez la pluie laver vos soucis. Venez louer Akunda sur les marches de Dazar\’alor !', 28153),
(160907, 'frFR', 'Le bateau se prépare à lever l\’ancre. Dépêchez-vous d\’embarquer.', '', 28153),
(160906, 'frFR', '$UUn admirateur:Une admiratrice; ! Quelle allégresse ! Cette rencontre doit vous mettre en état de choc. Ne vous laissez pas bouleverser ainsi, je ne suis qu\’un aventurier sans prétention, tout comme vous. Excepté que je suis un auteur à succès immensément riche et que mes admirateurs traversent les océans dans l\’espoir d\’avoir la chance de m\’apercevoir.\n\nVoici votre livre. Je suis certain que vous en prendrez grand soin.', '', 28153),
(160905, 'frFR', 'Le houblon, ça a du bon ! Avez-vous déjà goûté nos succulentes bières ?', '', 28153),
(160904, 'frFR', 'Vous êtes chevalier de la mort ? J\’ai toujours rêvé de rencontrer quelqu\’un comme vous !\n\nC\’est comment la non-mort ? Et c\’est une vocation, pour vous ? Je peux en être moi aussi ? Où est-ce qu\’on doit s\’inscrire ?', '', 28153),
(160903, 'frFR', 'Vous voulez bien dédicacer mon livre ?', 'Vous voulez bien dédicacer mon livre ?', 28153),
(160902, 'frFR', 'Mon dernier ouvrage est un véritable chef-d\’œuvre. Un pur bijou littéraire, tiré du fond des océans pour éblouir et séduire le lecteur. Êtes-vous ici pour chanter mes louanges ?', '', 28153),
(160901, 'frFR', 'Je vais pas vous mentir, j\’en sais trop rien pour l\’instant. Espérons que l\’Alliance les a pas chopés.', '', 28153),
(160900, 'frFR', 'Nous ne pourrons pas contenir Mythrax bien longtemps. Tuez Zul avant qu\’il ne soit trop tard.', '', 28153),
(160899, 'frFR', 'Vous m\’avez sauvé ! Merci infiniment ! J\’ai une récompense pour vous, quelque part dans ce sac.', '', 28153),
(160898, 'frFR', 'Occupez-vous de votre ville. Je veillerai à ce que ces misérables Sephraks ne s\’emparent pas de la route du nord.', '', 28153),
(160897, 'frFR', '', 'Je n\’avais jamais imaginé voir un jour des ennemis dans les rues de Zuldazar…', 28153),
(160896, 'frFR', '', 'Où qu\’elles sont, les défenses ? La trahison de Zul a-t-elle affaibli Zuldazar au point qu\’elle ne peut plus se défendre elle-même ?\n\nMeera, elle a fait l\’impossible pour qu\’on arrive à temps, histoire de prévenir la garde royale, mais on peut pas dire qu\’il reste grand monde. Alors, c\’est à nous qu\’incombe de défendre ce qu\’il reste.', 28153),
(160895, 'frFR', '', 'Vous n\’imaginez pas le chemin que nous avons dû emprunter pour arriver ici avant les Sephraks. Sans mon aide, vos amis n\’auraient jamais réussi à franchir ces montagnes à temps.\n\nOh, et nous avons amené avec nous Akunda et Kimbul. Le premier couvre nos arrières et j\’ignore où est passé le second. Il a juste parlé de « faire rendre gorge à l\’ennemi » ou quelque chose du genre.\n\nTout ce que je peux vous dire, c\’est que nous avons croisé des TAS de Sephraks en chemin.', 28153),
(160894, 'frFR', 'Pouvez-vous nous renseigner sur les agissements de la Horde dans cette région ?', 'Pouvez-vous nous renseigner sur les agissements de la Horde dans cette région ?', 28153),
(160893, 'frFR', 'Cette fois, j\’ai bien cru que c\’en était fini de moi. Merci infiniment, $R. C\’est toujours ainsi que l\’on appelle ceux de votre espèce, n\’est-ce pas ?', 'Cette fois, j\’ai bien cru que c\’en était fini de moi. Merci infiniment, $R. C\’est toujours ainsi que l\’on appelle ceux de votre espèce, n\’est-ce pas ?', 28153),
(160892, 'frFR', '', 'Vous semblez avoir soif d\’aventure ! Que diriez-vous d\’une bonne bière exotique ?', 28153),
(160891, 'frFR', 'Voyons votre carte des bières.', 'Voyons votre carte des bières.', 28153),
(160890, 'frFR', '', 'Une petite bière, ça vous tente ? Il y en a pour tous les goûts !', 28153),
(160889, 'frFR', 'Vous les avez écrabouillés, ma parole ! Si vous voulez, je peux fournir de nouvelles armures à vos soldats. À titre gracieux, bien sûr !', '', 28153),
(160888, 'frFR', '', 'Utiliser Tir acéré réduit également l\’attente avant de pouvoir lancer Courroux bestial à nouveau.', 28153),
(160887, 'frFR', 'Je fais aussi vite que possible.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160886, 'frFR', '', 'Coupe plus vite, Colton ! On a des clients à nourrir !', 28153),
(160885, 'frFR', 'Utiliser Tir acéré réduit également l\’attente avant de pouvoir lancer Courroux bestial à nouveau.', '', 28153),
(160884, 'frFR', 'Alors, allons-y, ma fille !', '', 28153),
(160883, 'frFR', 'Tu es prête ?', '', 28153),
(160882, 'frFR', 'Alors, Luna, tu as envie de jouer ?', '', 28153),
(160881, 'frFR', 'Heureusement que j\’ai une femme brillante.', '', 28153),
(160880, 'frFR', '', 'J\’ai une surprise pour vous !', 28153),
(160879, 'frFR', '', 'Vous avez vu ça ? Fascinant !', 28153),
(160878, 'frFR', 'Eh bien, je ne sais pas trop, peut-être me trouver une gentille compagne et m\’installer dans une jolie petite ferme des environs…\n\nNon mais franchement, qu\’est-ce que vous croyez que je vais faire ?\n\nJe vais aller récupérer mon argent auprès de Cirrus, payer une tournée générale au Nid douillet, et me mettre en quête de la prochaine aventure.\n\nC\’est comme ça que je vois la vie, moi.', '', 28153),
(160877, 'frFR', 'Que comptez-vous faire, à présent ?', 'Que comptez-vous faire, à présent ?', 28153),
(160876, 'frFR', 'Invasions, révolutions, réveil des Dieux très anciens… Tout cela n\’est rien ! Je ne quitterai pas ce Zocalo avant que le vieux Fabul m\’ait remboursé.', '', 28153),
(160875, 'frFR', 'C\’est rien du tout à côté de la grande danse des os de la Nouée que j\’ai vue pendant la Troisième guerre. C\’était le truc le plus troublant que j\’aie jamais vu.', '', 28153),
(160874, 'frFR', 'Si je m\’en tire, je jure de n\’escroquer aucun de mes clients pendant au moins deux semaines… voire même trois.', '', 28153),
(160873, 'frFR', 'Où se trouve le navire en ce moment ?', 'Où se trouve le navire en ce moment ?', 28153),
(160872, 'frFR', '', 'Je vous enverrai toute l\’aide possible, $n.', 28153),
(160871, 'frFR', '', 'J\’étais dans le sillage du Fléau lorsqu\’il a pris d\’assaut Zul\’Drak, mais je ne me remets pas de cette attaque contre notre patrie par ceux que nous considérions comme nos amis…\n\nÉcoutez, je suis pas un Troll violent, mais tout ça, ça me donne une furieuse envie de zigouiller quelqu\’un.', 28153),
(160870, 'frFR', 'Archidruidesse, Malfurion a besoin de vous en Sombrivage !', 'Archidruidesse, Malfurion a besoin de vous en Sombrivage !', 28153),
(160869, 'frFR', 'Prêtresse, nous avons besoin de votre aide pour repousser la Horde à la Sinueuse.', 'Prêtresse, nous avons besoin de votre aide pour repousser la Horde à la Sinueuse.', 28153),
(160868, 'frFR', 'Vous aidez la princesse ? Continuez comme ça. Éliminez les Trolls de sang avant qu\’ils nous massacrent tous.\n\nFaut que vous alliez aux ruines de Zul\’jan pour parler avec l\’approvisionneuse Lija. Elle aura tout ce qu\’il vous faut.', 'Vous aidez la princesse ? Continuez comme ça. Éliminez les Trolls de sang avant qu\’ils nous massacrent tous.\n\nFaut que vous alliez aux ruines de Zul\’jan pour parler avec l\’approvisionneuse Lija. Elle aura tout ce qu\’il vous faut.', 28153),
(160867, 'frFR', 'Il serait dans l\’intérêt du chef de guerre que vous fassiez tout votre possible pour convaincre les Zandalari de rejoindre la Horde avec leur flotte. Pour ce faire, vous allez devoir continuer à soutenir Talanji, même s\’il faut pour cela massacrer tous les Trolls de sang.\n\nElle a dépêché une émissaire en Nazmir en la personne de l\’approvisionneuse Lija. Vous la trouverez près des ruines de Zul\’jan. Que la Dame noire vous protège.', 'Il serait dans l\’intérêt du chef de guerre que vous fassiez tout votre possible pour convaincre les Zandalari de rejoindre la Horde avec leur flotte. Pour ce faire, vous allez devoir continuer à soutenir Talanji, même s\’il faut pour cela massacrer tous les Trolls de sang.\n\nElle a dépêché une émissaire en Nazmir en la personne de l\’approvisionneuse Lija. Vous la trouverez près des ruines de Zul\’jan. Que la Dame noire vous protège.', 28153),
(160866, 'frFR', 'Émissaire de l\’Expédition de Talanji', 'Émissaire de l\’Expédition de Talanji', 28153),
(160865, 'frFR', 'Ces Kultirassiens brassent une bière des plus délicates !\n\nElle est bien plus savoureuse que celles que j\’ai pu goûter sur le continent. Leur savoir-faire est assurément remarquable.', '', 28153),
(160864, 'frFR', 'Allez voir la princesse Talanji et le garde de guerre Rakera.', 'Allez voir la princesse Talanji et le garde de guerre Rakera.', 28153),
(160863, 'frFR', '', 'Des sectateurs sanguinaires, des Sephraks, des Mogu et même notre propre Zul ? Je regrette l\’époque où nous cherchions juste à conquérir le monde. Tout était plus simple.', 28153),
(160862, 'frFR', '', 'Notre longue guerre contre la Légion est certes terminée, mais la Horde ne peut se permettre de rester inactive.', 28153),
(160861, 'frFR', 'La Légion est tombée, mais une nouvelle menace semble déjà s\’éveiller. Nous avons reçu d\’inquiétantes nouvelles de nos agents à Orgrimmar. Retrouvez-moi au donjon de Hurlevent pour en discuter.', '', 28153),
(160860, 'frFR', 'Bienvenue à Vivesource ! Vous cherchez des fournitures pour votre trésor adoré ?', '', 28153),
(160859, 'frFR', '', 'Au début, je n\’avais que trois chats. Trois chats ! Ça semblait raisonnable !\n\nMais une amie a déménagé et m\’a confié le sien. Et puis, j\’ai recueilli cet animal errant au regard si triste. Ah oui, et j\’ai adopté celui de ma voisine décédée. Et un beau jour, une de mes minettes a mis bas. Après ça, deux autres matous ont… simplement décidé de rejoindre ma ménagerie !\n\nJe les aime tous autant qu\’ils sont et ne m\’en séparerais pour rien au monde.', 28153),
(160858, 'frFR', 'Ouais ! Encore !', '', 28153),
(160857, 'frFR', 'Aucun de ces chiots ne m\’appartient. J\’ai perdu mon cher Ozie il y a de nombreuses années. Alors je viens ici tous les jours pour rendre visite au plus délaissé d\’entre eux. Je le caresse et lui dis quel bon chien il fait.', '', 28153),
(160856, 'frFR', 'Je ferais n\’importe quoi pour mon chien.', '', 28153),
(160855, 'frFR', 'Lui, c\’est mon chien, Tonneau. Pour creuser des trous, c\’est un véritable champion !\n\nJe l\’ai mis là-haut pour qu\’il ne se sente pas seul. Je pense vraiment qu\’il est heureux ici.', '', 28153),
(160854, 'frFR', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Assurez-vous qu\’au moins un personnage-joueur se trouve dans chaque zone ciblée par |cFFFF0000|Hspell:266948|h[Bombe de peste]|h|r !', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Assurez-vous qu\’au moins un personnage-joueur se trouve dans chaque zone ciblée par |cFFFF0000|Hspell:266948|h[Bombe de peste]|h|r !', 28153),
(160853, 'frFR', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t Vous avez cumulé plus de 50 charges d\’|cFFFF0000|Hspell:272146|h[Annihilation]|h|r ! Trouvez des fragments d\’essence pour récupérer votre maximum de points de vie !', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t Vous avez cumulé plus de 50 charges d\’|cFFFF0000|Hspell:272146|h[Annihilation]|h|r ! Trouvez des fragments d\’essence pour récupérer votre maximum de points de vie !', 28153),
(160852, 'frFR', 'J\’ai entendu dire que vous aviez besoin d\’aide avec les Ettins.', 'J\’ai entendu dire que vous aviez besoin d\’aide avec les Ettins.', 28153),
(160851, 'frFR', 'Pour l\’Alliance !', '', 28153),
(160850, 'frFR', 'Je veillerai à ce que le roi Anduin en personne sache que vous vous êtes conduits en héros. Excellent travail, tout le monde.', '', 28153),
(160849, 'frFR', 'J\’accorde une mention spéciale au grand thane Falstad et à l\’ensemble du clan des Marteaux-Hardis.', '', 28153),
(160848, 'frFR', 'Vous êtes très loin de chez vous, $R.$b$bLes esprits, je les implorerai de veiller sur vous en Vol\’dun. Malheureusement, ils ne semblent plus écouter mes prières.', 'Vous êtes très loin de chez vous, $R.$b$bLes esprits, je les implorerai de veiller sur vous en Vol\’dun. Malheureusement, ils ne semblent plus écouter mes prières.', 28153),
(160847, 'frFR', 'Cette maudite chaleur, elle aura notre peau.', 'Cette maudite chaleur, elle aura notre peau.', 28153),
(160846, 'frFR', 'Sale vermine décérébrée ! J\’aurai ta tête pour ça !', 'Sale vermine décérébrée ! J\’aurai ta tête pour ça !', 28153),
(160845, 'frFR', 'Encore vous ? Je me suis montré clément la dernière fois ; je ne referai pas la même erreur !', 'Encore vous ? Je me suis montrée clémente la dernière fois ; je ne referai pas la même erreur !', 28153),
(160844, 'frFR', 'Merci de m\’avoir secouru. En échange, je vais équiper l\’ensemble de vos troupes des meilleures armes fabriquées par les industries Tarque. Vive la paix !', '', 28153),
(160843, 'frFR', 'Et moi… qui craignais… les requins…', 'Et moi… qui craignais… les requins…', 28153),
(160842, 'frFR', 'J\’aurai ma revanche… sur la terre ferme…', 'J\’aurai ma revanche… sur la terre ferme…', 28153),
(160841, 'frFR', 'Pour… la Horde…', 'Pour… la Horde…', 28153),
(160840, 'frFR', 'Où… comptez-vous… fuir… ?', 'Où… comptez-vous… fuir… ?', 28153),
(160839, 'frFR', 'Pas comme ça…', 'Pas comme ça…', 28153),
(160838, 'frFR', 'Ramenez-moi… au bateau…', 'Ramenez-moi… au bateau…', 28153),
(160837, 'frFR', 'Laissez-moi… couler…', 'Laissez-moi… couler…', 28153),
(160836, 'frFR', 'Ma vie pour… des vieilleries…', 'Ma vie pour… des vieilleries…', 28153),
(160835, 'frFR', 'Je vous aurai, même à demi nu !', 'Je vous aurai, même à demi nue !', 28153),
(160834, 'frFR', 'C\’est comme la pêche au harpon !', 'C\’est comme la pêche au harpon !', 28153),
(160833, 'frFR', 'La plongée commence enfin à devenir intéressante !', 'La plongée commence enfin à devenir intéressante !', 28153),
(160832, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(160831, 'frFR', 'La tuile ! Mon matos est resté à bord !', 'La tuile ! Mon matos est resté à bord !', 28153),
(160830, 'frFR', 'L\’Alliance, ici ? Qu\’est-ce qui s\’est passé pendant que j\’étais là-dessous ?', 'L\’Alliance, ici ? Qu\’est-ce qui s\’est passé pendant que j\’étais là-dessous ?', 28153),
(160829, 'frFR', 'L\’Alliance est là aussi ?', 'L\’Alliance est là aussi ?', 28153),
(160828, 'frFR', 'Hé, qu\’est-ce que vous faites là ?', 'Hé, qu\’est-ce que vous faites là ?', 28153),
(160827, 'frFR', 'Pas touche !', 'Pas touche !', 28153),
(160826, 'frFR', 'Je vais briquer le pont avec votre sang !', 'Je vais briquer le pont avec votre sang !', 28153),
(160825, 'frFR', 'Ça se passe entre vous et moi, $PR !', 'Ça se passe entre vous et moi, $PR !', 28153),
(160824, 'frFR', 'Plus un geste, vous m\’entendez ?', 'Plus un geste, vous m\’entendez ?', 28153),
(160823, 'frFR', 'Qu\’est-ce que le Loa m\’a apporté aujourd\’hui ?', 'Qu\’est-ce que le Loa m\’a apporté aujourd\’hui ?', 28153),
(160822, 'frFR', 'On ne touche pas au matériel !', 'On ne touche pas au matériel !', 28153),
(160821, 'frFR', 'Que personne n\’approche des canons !', 'Que personne n\’approche des canons !', 28153),
(160820, 'frFR', 'Ne touchez pas à ça !', 'Ne touchez pas à ça !', 28153),
(160819, 'frFR', 'Écartez-vous de là !', 'Écartez-vous de là !', 28153),
(160818, 'frFR', 'Jetez-moi… par-dessus bord…', 'Jetez-moi… par-dessus bord…', 28153),
(160817, 'frFR', 'Je vous maudis… vous et votre roi…', 'Je vous maudis… vous et votre roi…', 28153),
(160816, 'frFR', 'Vous êtes $Ucoincé:coincée; ici… avec nous…', 'Vous êtes $Ucoincé:coincée; ici… avec nous…', 28153),
(160815, 'frFR', 'Pour… mon chef de guerre…', 'Pour… mon chef de guerre…', 28153),
(160814, 'frFR', 'Charogne de l\’Alliance…', 'Charogne de l\’Alliance…', 28153),
(160813, 'frFR', 'On nous avait dit… que c\’était… gagné d\’avance…', 'On nous avait dit… que c\’était… gagné d\’avance…', 28153),
(160812, 'frFR', 'Nathanos… vous… achèvera…', 'Nathanos… vous… achèvera…', 28153),
(160811, 'frFR', 'Pour… la reine… banshee…', 'Pour… la reine… banshee…', 28153),
(160810, 'frFR', 'On vous sent arriver de loin, sale $PR.', 'On vous sent arriver de loin, sale $PR.', 28153),
(160809, 'frFR', 'Je vais vous vider comme un poisson !', 'Je vais vous vider comme un poisson !', 28153),
(160808, 'frFR', 'Qu\’on avertisse Nathanos !', 'Qu\’on avertisse Nathanos !', 28153),
(160807, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(160806, 'frFR', 'Pour la Dame noire !', 'Pour la Dame noire !', 28153),
(160805, 'frFR', 'Chopez-les !', 'Chopez-les !', 28153),
(160804, 'frFR', 'Dégagez de notre bateau !', 'Dégagez de notre bateau !', 28153),
(160803, 'frFR', 'L\’Alliance est là !', 'L\’Alliance est là !', 28153),
(160802, 'frFR', 'Dreven… vous tuera…', 'Dreven… vous tuera…', 28153),
(160801, 'frFR', 'Encore… un peu… de puissance…', 'Encore… un peu… de puissance…', 28153),
(160800, 'frFR', 'Je suis… invincible…', 'Je suis… invincible…', 28153),
(160799, 'frFR', 'Je vous maudis…', 'Je vous maudis…', 28153),
(160798, 'frFR', 'Le prince de sang… vous… videra de toute substance…', 'Le prince de sang… vous… videra de toute substance…', 28153),
(160797, 'frFR', 'Non !', 'Non !', 28153),
(160796, 'frFR', 'Continuez comme ça ! On touche au but…', '', 28153),
(160795, 'frFR', 'Une… dernière… goutte…', 'Une… dernière… goutte…', 28153),
(160794, 'frFR', 'Encore… un… peu…', 'Encore… un… peu…', 28153),
(160793, 'frFR', 'Vous n\’allez pas tarder à me supplier.', 'Vous n\’allez pas tarder à me supplier.', 28153),
(160792, 'frFR', 'Vous alimenterez les San\’layn !', 'Vous alimenterez les San\’layn !', 28153),
(160791, 'frFR', 'Oui ! Ça a l\’air de marcher !', '', 28153),
(160790, 'frFR', '$gUn:Une:r; $PR... Voilà qui est inattendu.', '$gUn:Une:r; $PR... Voilà qui est inattendu.', 28153),
(160789, 'frFR', 'Je vais vous ronger jusqu\’aux os !', 'Je vais vous ronger jusqu\’aux os !', 28153),
(160788, 'frFR', 'Regardez donc qui s\’aventure sur notre navire.', 'Regardez donc qui s\’aventure sur notre navire.', 28153),
(160787, 'frFR', 'Ça va faire mal, délicieusement mal.', 'Ça va faire mal, délicieusement mal.', 28153),
(160786, 'frFR', 'Je veux vous entendre hurler.', 'Je veux vous entendre hurler.', 28153),
(160785, 'frFR', 'Approchez, $PR…', 'Approchez, $PR…', 28153),
(160784, 'frFR', 'Hm ? Qu\’est-ce qui vous amène dans le coin, $c ?\n\nAh, vous devez être ici pour la bataille qui se prépare. Bien, cette petite discussion m\’a donné soif.\n\nSi vous voulez bien m\’excuser, je dois poursuivre mes préparatifs.', '', 28153),
(160783, 'frFR', 'L\’heure du combat est proche, $c. Nous aurions bien besoin d\’une pointure telle que vous dans nos rangs !', '', 28153),
(160782, 'frFR', 'Suivez-nous, nous vous conduirons en lieu sûr.', 'Suivez-nous, nous vous conduirons en lieu sûr.', 28153),
(160781, 'frFR', 'Pitié, ne m\’emmenez pas !', 'Pitié, ne m\’emmenez pas !', 28153),
(160780, 'frFR', 'La Horde… ici ?', 'La Horde… ici ?', 28153),
(160779, 'frFR', 'Partez, il est trop tard…', 'Partez, il est trop tard…', 28153),
(160778, 'frFR', 'L\’heure devrait être aux réjouissances ! Toutefois, les changements qui s\’opèrent en ce monde ne facilitent pas les choses. Je peux vous aider, si vous voulez bien vous joindre aux festivités !', '', 28153),
(160777, 'frFR', '<Lui mettre un coup de poing.>', '<Lui mettre un coup de poing.>', 28153),
(160776, 'frFR', 'Roko vous transmet ses amitiés.', 'Roko vous transmet ses amitiés.', 28153),
(160775, 'frFR', 'Vous vous souvenez de moi ?', 'Vous vous souvenez de moi ?', 28153),
(160774, 'frFR', 'Pourquoi vous vous intéressez aux exilés et aux exclus du désert ? Vol\’dun, c\’est juste l\’endroit où on envoie mourir ceux qui posent problème.\n\nMais bon, vous avez l\’air digne de confiance. Alors, la Vulpérine que vous cherchez, c\’est l\’amasseuse Jena. Elle devrait se trouver du côté du repaire des Vulpérins.', 'Pourquoi vous vous intéressez aux exilés et aux exclus du désert ? Vol\’dun, c\’est juste l\’endroit où on envoie mourir ceux qui posent problème.\n\nMais bon, vous avez l\’air digne de confiance. Alors, la Vulpérine que vous cherchez, c\’est l\’amasseuse Jena. Elle devrait se trouver du côté du repaire des Vulpérins.', 28153),
(160773, 'frFR', 'Vous êtes ici pour mendier comme la plèbe puante qui infeste les rues ?$B$BNe perdez pas votre temps. Je suis ici pour affaires.', 'Vous êtes ici pour mendier comme la plèbe puante qui infeste les rues ?$B$BNe perdez pas votre temps. Je suis ici pour affaires.', 28153),
(160772, 'frFR', 'Qu\’attendez-vous de cette bande de miséreux et d\’exilés ? La Dame noire vous a-t-elle demandé de les rallier à notre cause ?\n\nBah, quelles que soient vos raisons, vous pouvez tenter votre chance au repaire des Vulpérins en Vol\’dun. Il y a là-bas une petite renarde qui se fait appeler l\’amasseuse Jena. Elle pourra peut-être vous aider.', 'Qu\’attendez-vous de cette bande de miséreux et d\’exilés ? La Dame noire vous a-t-elle demandé de les rallier à notre cause ?\n\nBah, quelles que soient vos raisons, vous pouvez tenter votre chance au repaire des Vulpérins en Vol\’dun. Il y a là-bas une petite renarde qui se fait appeler l\’amasseuse Jena. Elle pourra peut-être vous aider.', 28153),
(160771, 'frFR', 'Émissaire des Volduni', 'Émissaire des Volduni', 28153),
(160770, 'frFR', 'Ce n\’est que mon humble avis, mais je suis convaincu que les membres du Sillage des tempêtes sont dignes de confiance. Si vous voulez parler à un de leurs chefs, rendez-vous à Brennadam dans la vallée Chantorage.\n\nUne fois sur place, allez trouver sœur Lilyana, elle pourra vous aider quelle que soit la nature de votre requête.', 'Ce n\’est que mon humble avis, mais je suis convaincue que les membres du Sillage des tempêtes sont dignes de confiance. Si vous voulez parler à un de leurs chefs, rendez-vous à Brennadam dans la vallée Chantorage.\n\nUne fois sur place, allez trouver sœur Lilyana, elle pourra vous aider quelle que soit la nature de votre requête.', 28153),
(160769, 'frFR', 'Émissaire du Sillage des tempêtes', 'Émissaire du Sillage des tempêtes', 28153),
(160768, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 28153),
(160767, 'frFR', 'Ça alors, même la tempête a pris peur en nous voyant.', '', 28153),
(160766, 'frFR', 'Cette guerre aurait dû avoir lieu il y a bien longtemps.\n\nL\’Alliance se drape dans une vertu et une piété de pure forme. Balivernes ! Elle rejette quiconque ne rentre pas dans le moule étriqué de sa vision du monde.', '', 28153),
(160765, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 28153),
(160764, 'frFR', '', 'Eh bien, je vais devoir reprendre du service pour accomplir la volonté d\’un nouveau maître.\n\nJe ferai et je dirai le nécessaire pour survivre jusqu\’à des jours meilleurs.\n\nMais tôt ou tard, cette guerre prendra fin. Nous devons aussi préparer l\’avenir.', 28153),
(160763, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 28153),
(160762, 'frFR', 'Ruse et finesse sont nos meilleures armes dans cette guerre, $n.', '', 28153),
(160761, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 28153),
(160759, 'frFR', 'Quand on a les Marteaux-Hardis dans la poche, suffit de se tourner vers le ciel chaque fois que ça dérape !', '', 28153),
(160758, 'frFR', 'La campagne progresse rapidement, $n. Et vous y avez beaucoup contribué.', '', 28153),
(160757, 'frFR', 'La Dame noire sera ravie… quand je lui annoncerai que vous avez fini dans une cage comme un misérable corniaud !', '', 28153),
(160756, 'frFR', 'Cela fait un moment déjà que je songe à vous faire un sort, sale fouine.', '', 28153),
(160755, 'frFR', 'Réglons cette affaire une fois pour toutes.', '', 28153),
(160754, 'frFR', 'L\’Ordre des Braises ? C\’est quoi ? Ça a l\’air drôlement mystérieux, dites-moi.\n\nJ\’ai entendu parler d\’un certain Alcorn, intendant à la Ferté-d\’Arom en Drustvar, loin à l\’ouest. Vous devez savoir comment vous y rendre puisque vous posez la question. Passez-moi votre carte, que je vous indique l\’endroit exact.', 'L\’Ordre des Braises ? C\’est quoi ? Ça a l\’air drôlement mystérieux, dites-moi.\n\nJ\’ai entendu parler d\’un certain Alcorn, intendant à la Ferté-d\’Arom en Drustvar, loin à l\’ouest. Vous devez savoir comment vous y rendre puisque vous posez la question. Passez-moi votre carte, que je vous indique l\’endroit exact.', 28153),
(160753, 'frFR', 'Les sœurs Fenlow m\’ont demandé de l\’aide. Le monde a tellement changé. Mais ça ne doit pas nous empêcher de nous amuser !', '', 28153),
(160752, 'frFR', 'Que vient faire un membre du Vol de bronze par ici ?', 'Que vient faire un membre du Vol de bronze par ici ?', 28153),
(160751, 'frFR', 'Est-ce que vous profitez de la fête ?', '', 28153),
(160750, 'frFR', 'Émissaire de l\’Ordre des Braises', 'Émissaire de l\’Ordre des Braises', 28153),
(160749, 'frFR', 'Pigé. Marteaux-Hardis, rangez vos marteaux-tempêtes et t\’nez-vous prêts en attendant mon signal.', '', 28153),
(160748, 'frFR', '', 'Observons-les à distance pour l\’instant. Il faut réfléchir à un plan avant qu\’ils nous repèrent.', 28153),
(160747, 'frFR', 'Les voilà, général. Deux cuirassés droit devant. Réprouvés.', '', 28153),
(160746, 'frFR', 'Ximo, il m\’a interdit de parler à la clientèle.', '', 28153),
(160745, 'frFR', '', 'Au revoir, Grommash Hurlenfer.', 28153),
(160744, 'frFR', 'Et risquer que son sacrifice n\’ait servi à rien ? Il faut partir ! MAINTENANT !', '', 28153),
(160743, 'frFR', '', 'Non ! Je resterai aux côtés de mon chef de guerre !', 28153),
(160742, 'frFR', 'Venez vite, par ici ! Cette occasion ne se représentera pas !', '', 28153),
(160741, 'frFR', 'Pour les Mag\’har ! Pour Draenor ! Lok-tar ogar !', '', 28153),
(160740, 'frFR', '', 'J\’ai réussi à rafler quelques caisses de provisions avant de partir. N\’hésitez pas à vous servir. Vous allez avoir besoin de forces !', 28153),
(160739, 'frFR', '', 'Mes frères et sœurs sont allés trop loin. Il nous incombe de réparer cette injustice.', 28153),
(160738, 'frFR', '', 'On a des paillasses si vous voulez vous reposer un peu. C\’est pas grand-chose, mais c\’est tout ce qu\’on a.', 28153),
(160737, 'frFR', 'Geya\’rah, faites évacuer tout le monde. Maintenant. Ne discutez pas.', '', 28153),
(160736, 'frFR', '<Grommash baisse la voix de façon à ce que seule la Mag\’har puisse l\’entendre.>', '', 28153),
(160735, 'frFR', '', 'Le cœur me saigne à l\’idée de perdre un vieil ami de cette façon, Grommash. Mais… Entendu. Nous allons régler cette affaire à votre manière.', 28153),
(160734, 'frFR', 'Comment pouvez-vous être aussi aveugle, Yrel ? C\’est la Lumière qui a damné ce monde.', '', 28153),
(160733, 'frFR', '', 'Les vôtres ont condamné ce monde à une lente agonie… cette terre est vouée à se tarir.', 28153),
(160732, 'frFR', '', 'Je viens vous offrir une dernière chance de vous ouvrir à la Lumière.', 28153),
(160731, 'frFR', 'Grande exarque ? C\’est… un honneur.', '', 28153),
(160730, 'frFR', '', 'Grommash Hurlenfer. Cela faisait bien longtemps.', 28153),
(160729, 'frFR', '', 'Il le faut ! Le destin ne veut PAS que nous succombions à cette corruption !', 28153),
(160728, 'frFR', 'Le navire pour Kul Tiras est à quai. Pour Boralus, tout le monde à bord !', 'Le navire pour Kul Tiras est à quai. Pour Boralus, tout le monde à bord !', 28153),
(160727, 'frFR', 'Ils sont trop nombreux ! On ne pourra pas tenir éternellement !', '', 28153),
(160726, 'frFR', '$n, rendez-vous au sommet de la tour et faites pleuvoir la mort sur les empreints de Lumière !', '', 28153),
(160725, 'frFR', 'Commandant, Eitrigg, aidez-moi à tenir notre position !', '', 28153),
(160724, 'frFR', 'Lantresor, chevauchez le plus vite possible ! Battez le rappel de nos Orcs au grand complet !', '', 28153),
(160723, 'frFR', '…', '', 28153),
(160722, 'frFR', 'Tous ?', '', 28153),
(160721, 'frFR', 'Ils sont tous là.', '', 28153),
(160720, 'frFR', 'Combien sont-ils, Lantresor ?', '', 28153),
(160719, 'frFR', 'Chef de guerre Hurlenfer ! Une armée marche sur nous !', '', 28153),
(160718, 'frFR', '<Voler jusqu\’à Hurlevent>', '<Voler jusqu\’à Hurlevent>', 28153),
(160717, 'frFR', '', 'L\’Implacable est à quai ! Pour Hurlevent, tout le monde à bord !', 28153),
(160716, 'frFR', 'Commandant ! Cognepierre veut pas d\’ennuis avec les Orcs. Kor\’gall est dans cette grotte.', '', 28153),
(160715, 'frFR', 'Vous rentrez déjà ? Une chance pour vous que les rares navires de l\’Alliance encore présents desservent régulièrement Hurlevent. Rendez-vous sur le petit embarcadère en bois, au sud du marché des Alizés.\n\nÀ un de ces quatre !', 'Vous rentrez déjà ? Une chance pour vous que les rares navires de l\’Alliance encore présents desservent régulièrement Hurlevent. Rendez-vous sur le petit embarcadère en bois, au sud du marché des Alizés.\n\nÀ un de ces quatre !', 28153),
(160714, 'frFR', 'Navire pour Hurlevent', 'Navire pour Hurlevent', 28153),
(160713, 'frFR', 'Vous n\’imaginez pas le nombre de réparations que j\’ai à faire ici. Ça fait de la magie à tout va et c\’est pas capable d\’utiliser des matériaux résistants à l\’eau !', '', 28153),
(160712, 'frFR', '<Voler jusqu\’à Orgrimmar>', '<Voler jusqu\’à Orgrimmar>', 28153),
(160711, 'frFR', 'Pour être tout à fait franc, je ne les aime pas beaucoup. Leurs bannières n\’inspirent pas la confiance.', '', 28153),
(160710, 'frFR', 'Les eaugures ont perdu la tête !', '', 28153),
(160709, 'frFR', 'Vous avez déjà été dans un de nos rades ? Ils valent le détour, ça oui !', '', 28153),
(160708, 'frFR', 'Quand le bateau est vide, j\’en profite pour me détendre en me trempant les arpions dans l\’eau.', '', 28153),
(160707, 'frFR', 'L\’odeur de la brise marine, il n\’y a que ça de vrai.', '', 28153),
(160706, 'frFR', 'Si on vit sur une île, c\’est parce qu\’on tient à notre tranquillité. Ils peuvent pas rentrer chez eux, tous ces touristes ? Je parle pas de vous, hein.', '', 28153),
(160705, 'frFR', 'Le bruit des rames qui fendent les eaux, il n\’y a rien de plus reposant.', '', 28153),
(160704, 'frFR', 'Zeb\’ahari, ça a toujours été mon village préféré. Un vrai havre de paix. Loin de l\’agitation de Dazar\’alor, c\’est là qu\’on apprécie vraiment la beauté de Zuldazar.', '', 28153),
(160703, 'frFR', 'Je me rappelle quand j\’étais petit, j\’adorais partir en vadrouille sur la côte.', '', 28153),
(160702, 'frFR', 'Plus vite ils nettoieront nos plages, mieux ce sera !', '', 28153),
(160701, 'frFR', 'Envoyez-moi au filon de Galson.', 'Envoyez-moi au filon de Galson.', 28153),
(160700, 'frFR', 'Envoyez-moi à la scierie des Hautes-Terres.', 'Envoyez-moi à la scierie des Hautes-Terres.', 28153),
(160699, 'frFR', 'Envoyez-moi au donjon de Stromgarde.', 'Envoyez-moi au donjon de Stromgarde.', 28153),
(160698, 'frFR', 'Je vous emmène ?', '', 28153),
(160697, 'frFR', 'On va vous retaper tout ça en moins de deux si on travaille tous ensemble !', '', 28153),
(160696, 'frFR', 'Vous pouvez toujours compter sur la compagnie des Ingénieurs Tout Risque !', '', 28153),
(160695, 'frFR', 'Je m\’occupe de tous vos besoins en réparation !', '', 28153),
(160694, 'frFR', '<Prendre les notes.>', '<Prendre les notes.>', 28153),
(160693, 'frFR', '', '« Après avoir enfin découvert une base adéquate, nous avons réussi à produire un composé stable.$B$BSous cette forme, il peut être stocké, transporté ou intégré au mélange afin de fabriquer une poudre noire à la puissance dévastatrice !$B$BSa stabilité est telle que nous avons envoyé les premiers échantillons à Boralus dans le pendentif d\’un collier.$B$BLes chaudrons à poudre bouillonnent jour et nuit, et nous cherchons d\’ores et déjà d\’autres applications. Notre prototype le plus prometteur est un pistolet dont nous espérons faire cadeau à notre estimée présidente. »$B$B<Les notes décousues décrivent en détail divers projets en cours et à venir.>', 28153),
(160692, 'frFR', 'Renforcement', 'Renforcement', 28153),
(160691, 'frFR', '', 'Une fois que Zandalar sera en ruines, l\’empire des Dieux très anciens renaîtra de ses cendres !', 28153),
(160690, 'frFR', '', 'Ton combat, il est sans espoir… G\’huun sera bientôt libre !', 28153),
(160689, 'frFR', '', 'Lorsque le dernier sceau sera détruit, ce monstre sèmera le chaos en Azeroth !', 28153),
(160688, 'frFR', 'Les analyses indiquent que ceux de Nazmir et Vol\’dun sont actuellement hors service. Seul sceau opérationnel : Zuldazar.', '', 28153),
(160687, 'frFR', 'Désignation : G\’huun.', '', 28153),
(160686, 'frFR', '', 'Préparez-vous à mourir.', 28153),
(160685, 'frFR', '', 'Vous ne pouvez plus échapper à vos crimes.', 28153),
(160684, 'frFR', 'Et ta place, elle n\’est pas parmi les rois.', '', 28153),
(160683, 'frFR', 'Tu ne comprends rien.', '', 28153),
(160682, 'frFR', 'De quoi, déjà ?', '', 28153),
(160681, 'frFR', 'Ces terres sont sacrées.', '', 28153),
(160680, 'frFR', 'Je suis prêt à vous aider.', 'Je suis prête à vous aider.', 28153),
(160679, 'frFR', '', 'Nous avons beaucoup perdu ces derniers jours, mais nous continuons d\’avancer.', 28153),
(160678, 'frFR', 'Souvenez-vous, la partie mouillée reste en bas !', '', 28153),
(160677, 'frFR', 'Ciel carmin dans la nuit, les marins sont ravis. Ciel carmin du matin, les marins se méfient !', '', 28153),
(160676, 'frFR', 'Le navire, il est à l\’abri au port… mais ça n\’a rien de palpitant !', '', 28153),
(160675, 'frFR', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t Mythrax commence à lancer |cFFFF0000|Hspell:274113|h[Rayon d\’oblitération]|h|r !', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t Mythrax commence à lancer |cFFFF0000|Hspell:274113|h[Rayon d\’oblitération]|h|r !', 28153),
(160674, 'frFR', 'Beau travail, $p. Beau travail, Shandris.', '', 28153),
(160673, 'frFR', 'Xibala', 'Xibala', 28153),
(160672, 'frFR', 'Si vous souhaitez apprendre à fabriquer de l\’équipement plus efficacement, ne cherchez pas plus loin. J\’ai ici ce qu\’il vous faut.', '', 28153),
(160671, 'frFR', 'C\’te mission va rester dans les annales des Marteaux-Hardis… mais j\’boirais bien un coup, là tout de suite.', '', 28153),
(160670, 'frFR', '', 'Vous pouvez compter sur nous pour garder un œil sur les mouvements des Sephraks en contrebas !', 28153),
(160669, 'frFR', 'Vous êtes super !', 'Vous êtes super !', 28153),
(160668, 'frFR', 'Faites tout sauter, encore !', 'Faites tout sauter, encore !', 28153),
(160667, 'frFR', 'Quand je serai grand, je veux être comme vous !', 'Quand je serai grande, je veux être comme vous !', 28153),
(160666, 'frFR', 'Vous êtes $gun vrai héros:une vraie héroïne; !', 'Vous êtes $gun vrai héros:une vraie héroïne; !', 28153),
(160665, 'frFR', 'Si vous souhaitez apprendre à fabriquer de l\’équipement plus efficacement, ne cherchez pas plus loin. J\’ai ici ce qu\’il vous faut.', '', 28153),
(160664, 'frFR', '|TInterface\\Icons\\70_inscription_vantus_rune_light:20|t%s crée un |cFFFF0000|Hspell:267905|h[Espace de renforcement]|h|r !', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t%s crée un |cFFFF0000|Hspell:267891|h[Espace de rapidité]|h|r !', 28153),
(160663, 'frFR', '', 'Maudite soit cette vile Lumière !', 28153),
(160662, 'frFR', '', 'Non… un Naaru… pas encore !', 28153),
(160661, 'frFR', '', 'Et du sort de mes frères et sœurs au fort de l\’Aube-Éternelle. Je crains que nous ne puissions plus faire grand-chose pour les sauver, à présent.', 28153),
(160660, 'frFR', 'En route, héros ! On ne me paye pas pour rester les bras croisés !', 'En route, héros ! On ne me paye pas pour rester les bras croisés !', 28153),
(160659, 'frFR', 'Magni Barbe-de-Bronze vous attend en Silithus. Hâtez-vous, la terre elle-même se retourne contre nous !', '', 28153),
(160658, 'frFR', 'Magni Barbe-de-Bronze a besoin de votre aide. Accordez-moi un instant.', '', 28153),
(160657, 'frFR', 'J\’ai à vous parler toutes affaires cessantes !', '', 28153),
(160656, 'frFR', 'Nous avons à parler. Magni Barbe-de-Bronze a besoin de votre aide !', '', 28153),
(160655, 'frFR', 'J\’ai un message urgent de la part de Magni Barbe-de-Bronze, l\’orateur d\’Azeroth.', '', 28153),
(160654, 'frFR', 'Je suis prêt à partir.', 'Je suis prête à partir.', 28153),
(160653, 'frFR', 'Prêt à partir ?', 'Prête à partir ?', 28153),
(160652, 'frFR', '', 'Avec cette brèche percée dans le mur, la douleur devient… supportable. Accordez-moi… un instant.', 28153),
(160650, 'frFR', '', 'Tenez-vous prêts…', 28153),
(160649, 'frFR', '', 'Nous franchirons le mur à mon signal !', 28153),
(160648, 'frFR', 'Autodestruction activée !', 'Autodestruction activée !', 28153),
(160647, 'frFR', 'Non, je pense que vous avez commis une erreur. Réessayons.', '', 28153),
(160646, 'frFR', '', 'Nul ne viendra à bout de mon peuple.', 28153),
(160645, 'frFR', 'Je suis prêt à partir.', 'Je suis prête à partir.', 28153),
(160644, 'frFR', '', 'La Horde paiera pour cette incursion !', 28153),
(160643, 'frFR', '', 'Élune ait pitié de nous.', 28153),
(160642, 'frFR', '', 'Je sers les Kaldorei.', 28153),
(160641, 'frFR', '', 'Je suis ravie de vous compter parmi nous.', 28153),
(160640, 'frFR', '', 'Il y a tant à faire.', 28153),
(160639, 'frFR', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Force vitale]|h|r de l\’avatar est renforcée, soignez-la !', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|tLa |cFFFF0000|Hspell:274149|h[Force vitale]|h|r de l\’avatar est renforcée, soignez-la !', 28153),
(160638, 'frFR', 'Chevaucheurs de griffons, repliez-vous en formation. On en a terminé ici !', '', 28153),
(160637, 'frFR', 'T\’as entendu le général, Vol-au-Vent. Ramène-nous à Boralus !', '', 28153),
(160636, 'frFR', '', 'Nous pouvons y aller, Falstad.', 28153),
(160635, 'frFR', 'La Horde est ici ?! Je préfère tenter ma chance avec les requins !', 'La Horde est ici ?! Je préfère tenter ma chance avec les requins !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160634, 'frFR', 'Ben qu\’ils partent ! Un melon, ça se coupe dans les règles. Tout est dans la délicate violence du coup de poignet.', '', 28153),
(160633, 'frFR', 'Les melons, je devrais p\’têt les couper avec ta langue acérée, Grozzak.', '', 28153),
(160632, 'frFR', 'Je coupe aussi vite que je peux, je te signale !', '', 28153),
(160631, 'frFR', 'Fendre les melons, ça prend du temps. Laisse faire le chef.', '', 28153),
(160630, 'frFR', 'Si les melons arrivent pas fissa, les clients, ils vont partir.', '', 28153),
(160629, 'frFR', 'C\’est peut-être le fendoir qu\’est émoussé, mon ami.', '', 28153),
(160628, 'frFR', 'Ça paraît bien long pour couper quelques melons, Ka\’ro.', '', 28153),
(160627, 'frFR', 'Les clients, ils sont à bout de patience. Y en a encore pour longtemps ?', '', 28153),
(160626, 'frFR', 'Mes Marteaux-Hardis pourront pas occuper Nathanos et l\’reste de la Horde bien longtemps. On peut y aller ?', '', 28153),
(160625, 'frFR', 'Azeroth se portera mieux sans ce prince de sang. Vous avez bien fait, $p.', '', 28153),
(160624, 'frFR', 'Achevez le combat.', 'Achevez le combat.', 28153),
(160623, 'frFR', 'Vous avez beaucoup fait pour Boralus aujourd\’hui, héros. À présent, c\’est à moi de jouer.', 'Vous avez beaucoup fait pour Boralus aujourd\’hui, héros. À présent, c\’est à moi de jouer.', 28153),
(160622, 'frFR', 'Préparez-vous à sauter, $p. J\’vais vous conduire juste au-dessus de la Risée écarlate.', '', 28153),
(160621, 'frFR', '', 'À l\’effigie de quel Loa dois-je créer une statue ?', 28153),
(160620, 'frFR', 'J\’vous emmène sur la Risée écarlate, $p ? Shandris vous y attend.', '', 28153),
(160619, 'frFR', 'Jamais… elle ne reviendra des confins Corrompus…', '', 28153),
(160618, 'frFR', 'Les Ulterres dévorent tout ! Elle est à nous !', '', 28153),
(160617, 'frFR', 'Je voudrais changer le Loa de Vol\’dun représenté ici.', 'Je voudrais changer le Loa de Vol\’dun représenté ici.', 28153),
(160616, 'frFR', 'Je voudrais changer le Loa de Nazmir représenté ici.', 'Je voudrais changer le Loa de Nazmir représenté ici.', 28153),
(160615, 'frFR', '', 'Je dois prévenir les habitants. Gagnez directement les quais. Je vous rejoindrai là-bas !', 28153),
(160614, 'frFR', '', 'Entendu… amiral suprême.', 28153),
(160613, 'frFR', '', 'Malheureusement, les retrouvailles devront attendre.', 28153),
(160612, 'frFR', '$n ! Vous voilà enfin ! Que s\’est-il passé ?', '', 28153),
(160611, 'frFR', '$n ! Les brumes semblent vous eng…', '', 28153),
(160609, 'frFR', 'Bonne chance à vous.', '', 28153),
(160608, 'frFR', 'J\’attendrai avec nos guides sur la grève et vous aiderai à retrouver le chemin du retour.', '', 28153),
(160607, 'frFR', 'Je prie pour que vous retrouviez Jaina. Mais restez sur vos gardes. Cette île empeste le mal.', '', 28153),
(160606, 'frFR', 'J\’ignore ce qui nous attend à Funesterre, $p.', '', 28153),
(160605, 'frFR', 'Quoi, vous vous inquiétiez pour moi ? Ha ha !\n\n<Tousse>\n\nArgh… je ne suis pas au mieux de ma forme, mais ça va passer.\n\nEn tout cas, mon travail est terminé.\n\nÀ charge pour Taelia et vous d\’aller jouer les héros à Boralus !', '', 28153),
(160604, 'frFR', '', 'Venez, Amalia. Poursuivons notre leçon sur la condition de Réprouvé.', 28153),
(160603, 'frFR', 'Montrez-moi vos marchandises.', 'Montrez-moi vos marchandises.', 28153),
(160602, 'frFR', 'J\’étais en mission de ravitaillement quand les moteurs m\’ont lâché. J\’ai dû atterrir en urgence ici, puis attendre des jours l\’arrivée des secours.$b$bAvez-vous déjà survécu dans un marais en mangeant des brindilles et de la mousse ? Moi si !', '', 28153),
(160601, 'frFR', '', 'Appelez Falstad et rejoignez-moi dans les cieux. Nous allons rentrer ensemble à Boralus.', 28153),
(160600, 'frFR', '', 'Le prince de sang Dreven est mort. Nous devons filer avant que Nathanos et les autres se remettent de la diversion des Marteaux-Hardis.', 28153),
(160599, 'frFR', '', 'Anu\’dorini talah… monstre.', 28153),
(160598, 'frFR', 'Gorak Tul… vous réduira… en poussière…', '', 28153),
(160597, 'frFR', 'Vous allez le payer !', '', 28153),
(160596, 'frFR', 'Comment osez-vous profaner ces ossements ?', '', 28153),
(160595, 'frFR', 'Nom d\’une pomme ! Vous me rappelez la tarte que préparait ma mère.\n\nTrès bien, je vais vous montrer… l\’œuvre de ma vie !\n\nElle se trouve dans le coffre à l\’arrière de la maison. Je vous l\’offre !\n\nJ\’espère que le jeu en valait la chandelle !', 'Nom d\’une pomme ! Vous me rappelez la tarte que préparait ma mère.\n\nTrès bien, je vais vous montrer… l\’œuvre de ma vie !\n\nElle se trouve dans le coffre à l\’arrière de la maison. Je vous l\’offre !\n\nJ\’espère que le jeu en valait la chandelle !', 28153),
(160594, 'frFR', 'Quelle odeur est-ce que je sens ?', 'Quelle odeur est-ce que je sens ?', 28153),
(160593, 'frFR', 'Oh, excellent. Mais je… euh…', 'Oh, excellent. Mais je… euh…', 28153),
(160592, 'frFR', 'J\’ai envoyé un message à vos ennemis. Qu\’en est-il de ces secrets ?', 'J\’ai envoyé un message à vos ennemis. Qu\’en est-il de ces secrets ?', 28153),
(160591, 'frFR', 'Me revoilà. Avez-vous quelque secret à me révéler ?', 'Me revoilà. Avez-vous quelque secret à me révéler ?', 28153),
(160590, 'frFR', 'Je ne vois pas de quoi vous voulez parler !', 'Je ne vois pas de quoi vous voulez parler !', 28153),
(160589, 'frFR', 'Salutations ! Les visiteurs ne sont pas légion par ici, veuillez excuser le désordre.', 'Salutations ! Les visiteurs ne sont pas légion par ici, veuillez excuser le désordre.', 28153),
(160588, 'frFR', '', 'Déesse, donne-moi la force !', 28153),
(160587, 'frFR', '', 'Non ! Finis, les tours de passe-passe. Vous ne m\’échapperez pas. L\’heure de rendre justice a sonné.', 28153),
(160586, 'frFR', 'Le prince de sang Dreven commence à lancer un sort pour s\’échapper !', '', 28153),
(160585, 'frFR', 'Je commence à en avoir assez de votre guéguerre stérile. Le petit jeu est terminé.', '', 28153),
(160584, 'frFR', 'N\’hésitez pas à vous mettre à l\’aise.', 'N\’hésitez pas à vous mettre à l\’aise.', 28153),
(160583, 'frFR', 'J\’aurais bien souri et levé un verre en votre nom, hélas je n\’ai ni lèvres ni boisson.', 'J\’aurais bien souri et levé un verre en votre nom, hélas je n\’ai ni lèvres ni boisson.', 28153),
(160582, 'frFR', 'Misère ! Voilà que j\’ai des visiteurs et rien à me mettre…', 'Misère ! Voilà que j\’ai des visiteurs et rien à me mettre…', 28153),
(160581, 'frFR', '', 'L\’Alliance nous a attaqués. Vous avez loupé le spectacle, $p.', 28153),
(160580, 'frFR', 'Ravi de vous revoir ! On n\’a pas eu le temps de s\’ennuyer en votre absence.', '', 28153),
(160579, 'frFR', 'D\’ailleurs, je me suis régalé !', '', 28153),
(160578, 'frFR', 'Petite sotte. J\’ai déjà emporté leur nom quand je les ai vidées de leur force vitale.', '', 28153),
(160577, 'frFR', 'Vol-au-Vent et moi, on vous couvre, $p ! Ça va marteler sec, c\’est moi qui vous l\’dis !', '', 28153),
(160576, 'frFR', '', 'Je crains qu\’il ne soit un peu tard pour ça, Amalia. Nous avons de la visite.', 28153),
(160575, 'frFR', '', 'Les troupes de dame Portvaillant sont infatigables, Nathanos. Nous devrions filer dès que possible.', 28153),
(160574, 'frFR', 'Fort bien. Ce sera un atout considérable pour l\’armada zandalari… et une épine dans le flanc des Kultirassiens.', '', 28153),
(160573, 'frFR', 'Nous avons récupéré le sceptre abyssal, Nathanos.', '', 28153),
(160572, 'frFR', 'Nous avons réussi ! La chambre n\’est plus menacée !', '', 28153),
(160571, 'frFR', 'Non ! Le sceau faiblit ! Tenez bon !', '', 28153),
(160570, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t N\’oubliez pas de regarder G\’huun lorsqu\’il lance |cFFFF0404|Hspell:267700|h[Regard de G\’huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t N\’oubliez pas de regarder G\’huun lorsqu\’il lance |cFFFF0404|Hspell:267700|h[Regard de G\’huun]|h|r.', 28153),
(160569, 'frFR', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Récupérez la |cFFFF0404|Hspell:263420|h[Matrice de puissance]|h|r pour déclencher une |cFFFF0404|Hspell:263482|h[Explosion de réorigination]|h|r !', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Récupérez la |cFFFF0404|Hspell:263420|h[Matrice de puissance]|h|r pour déclencher une |cFFFF0404|Hspell:263482|h[Explosion de réorigination]|h|r !', 28153),
(160568, 'frFR', 'Zeb\’ahari', 'Zeb\’ahari', 28153),
(160567, 'frFR', 'Faites-moi signe quand vous voudrez vous rendre sur le site du rituel, $n.', '', 28153),
(160566, 'frFR', '', 'Cela ne me dit rien qui vaille.', 28153),
(160565, 'frFR', '', 'Attendez ! Que se passe-t-il en bas ?', 28153),
(160564, 'frFR', '', 'Cherchait-elle à éprouver son nouvel arsenal… ou cette manœuvre cache-t-elle autre chose ?', 28153),
(160563, 'frFR', '', 'Je ne comprends pas… Pourquoi dame Corsandre lancerait-elle des pirates à l\’assaut de la porte de Daelin ?', 28153),
(160562, 'frFR', 'Allez dans l\’honneur. Pour la Horde.', '', 28153),
(160561, 'frFR', 'La prochaine fois que je ferai appel à vous, ce sera pour attaquer Boralus, la capitale de Kul Tiras.', '', 28153),
(160560, 'frFR', 'Nous avons rassemblé tout ce dont nous avions besoin.', '', 28153),
(160558, 'frFR', 'Partons, dans ce cas. Dites à Voguenille que nous en avons terminé ici.', '', 28153),
(160557, 'frFR', 'Il faut partir avant qu\’ils reviennent à la charge. Ils ne doivent surtout pas découvrir le pot aux roses.', '', 28153),
(160556, 'frFR', 'L\’Alliance nous a attaqués quand vous étiez sous l\’eau, $p. Nous les avons repoussés, mais ils ont détruit notre second bateau.', '', 28153),
(160555, 'frFR', '', 'Oui, même moi.', 28153),
(160554, 'frFR', '', 'Même vous ?', 28153),
(160553, 'frFR', '', 'Patience, Laroche. Nous avons tous besoin de temps pour nous habituer à la vie après la mort.', 28153),
(160552, 'frFR', '', 'Je sais qu\’ils ne m\’accepteront jamais telle… telle que je suis, mais je ne peux pas trahir les miens.', 28153),
(160551, 'frFR', '', 'Je n\’y arriverai pas, Lilian.', 28153),
(160550, 'frFR', 'À vos ordres.', '', 28153),
(160549, 'frFR', 'Excellent. Vous et $p, allez voir Hobart. Il se chargera d\’équiper $p et de lui expliquer les techniques de base de la plongée.', '', 28153),
(160548, 'frFR', 'Sans l\’ombre d\’un doute. Les marées ne mentent pas : Valentine est là, au fond.', '', 28153),
(160547, 'frFR', 'C\’est ici ?', '', 28153),
(160546, 'frFR', 'Oui, seigneur.', '', 28153),
(160545, 'frFR', 'Indiquez les coordonnées à Voguenille. Nous levons l\’ancre immédiatement.', '', 28153),
(160544, 'frFR', 'C\’est un tabou dont vous n\’avez plus à vous soucier.', '', 28153),
(160543, 'frFR', 'Je crois, oui. Encore que, utiliser le pouvoir des eaugures pour récupérer un cadavre en mer… c\’est…', '', 28153),
(160542, 'frFR', 'Zelling. Vous êtes sûr de pouvoir repérer le corps du maréchal Valentine ?', '', 28153),
(160541, 'frFR', 'Vous voulez vous entraîner ? Bonne idée. Faut garder la forme, si on veut pas y rester. Bon, alors va falloir vous rendre sur les remparts qui surplombent le port de Boralus.\n\nLe mieux, c\’est de rejoindre Joan Weber, le maître de vol du marché des Alizés. Descendez ensuite les escaliers sa gauche puis passez le poste de contrôle au sud. Vous verrez une petite clairière où s\’entraînent les gardes.', 'Vous voulez vous entraîner ? Bonne idée. Faut garder la forme, si on veut pas y rester. Bon, alors va falloir vous rendre sur les remparts qui surplombent le port de Boralus.\n\nLe mieux, c\’est de rejoindre Joan Weber, le maître de vol du marché des Alizés. Descendez ensuite les escaliers à gauche puis passez le poste de contrôle au sud. Vous verrez une petite clairière où s\’entraînent les gardes.', 28153),
(160540, 'frFR', '', 'Nous devons nous rendre à Boralus pour prévenir l\’amiral suprême !', 28153),
(160539, 'frFR', '', 'Je vais faire mon rapport au lieutenant. Retrouvez-moi à la colline de la Vigie quand vous en aurez fini.', 28153),
(160538, 'frFR', '', 'Il n\’est pas exclu qu\’ils reviennent. Imaginez qu\’il leur prenne de pointer ces canons sur Boralus…', 28153),
(160537, 'frFR', '', 'Dépêchons-nous !', 28153),
(160536, 'frFR', '', 'Message urgent de la part de Nathanos. Les Portvaillant ont débarqué au port des Rapines.', 28153),
(160535, 'frFR', '', 'Utilisez Tir acéré pendant que vous attaquez le mannequin d\’entraînement.', 28153),
(160534, 'frFR', 'Utilisez Tir acéré pendant que vous attaquez le mannequin d\’entraînement.', '', 28153),
(160533, 'frFR', '', 'L\’odeur du sang attise la fureur de votre familier, vous permettant de vous concentrer sur vos autres techniques.', 28153),
(160532, 'frFR', 'L\’odeur du sang attise la fureur de votre familier, vous permettant de vous concentrer sur vos autres techniques.', '', 28153),
(160531, 'frFR', '', 'Vous pouvez aussi décocher un Tir acéré sur vos ennemis. Cela leur infligera des dégâts de saignement sur la durée.', 28153),
(160530, 'frFR', 'Votre lampe frontale a attiré un requin-baleine !', 'Votre lampe frontale a attiré un requin-baleine !', 28153),
(160529, 'frFR', '', 'Ça a fonctionné… Nous avons réussi !', 28153),
(160528, 'frFR', 'Voulez-vous vraiment invoquer à nouveau une gargouille au lieu d\’une Val\’kyr ?', 'Voulez-vous vraiment invoquer à nouveau une gargouille au lieu d\’une Val\’kyr ?', 28153),
(160527, 'frFR', 'Voulez-vous vraiment apprendre à invoquer une Val\’kyr au lieu d\’une gargouille ?', 'Voulez-vous vraiment apprendre à invoquer une Val\’kyr au lieu d\’une gargouille ?', 28153),
(160526, 'frFR', 'Apparemment, la créature s\’est éloignée.', 'Apparemment, la créature s\’est éloignée.', 28153),
(160525, 'frFR', 'Peu importe, je dirai à Sylvanas que c\’est vous qui les avez tués… et que je vous ai tués pour les venger !', '', 28153),
(160524, 'frFR', 'Les Morts-vivants sont si décharnés qu\’ils vous laissent sur votre faim. J\’ai dû en vider trois pour obtenir l\’équivalent d\’un Elfe de la nuit.', '', 28153),
(160523, 'frFR', 'Vous sentez qu\’une grande créature rôde dans l\’eau, à proximité…', 'Vous sentez qu\’une grande créature rôde dans l\’eau, à proximité…', 28153),
(160522, 'frFR', '', 'Tu ne nous échapperas pas, abomination. Pas cette fois. Tu aurais dû mourir il y a bien longtemps.', 28153),
(160521, 'frFR', '', 'Vous allez emporter le nom de mes sœurs dans la tombe, monstre.', 28153),
(160520, 'frFR', '', 'Sentinelle Falia. Sentinelle Aeolyn. Sentinelle Lyrias.', 28153),
(160519, 'frFR', 'Restez sur vos gardes, $n. Ce n\’est pas un souterrain ordinaire, nous sommes dans les entrailles de Boralus.', '', 28153),
(160518, 'frFR', '', 'N\’oubliez pas que vous allez débarquer dans les entrailles de Boralus. Ouvrez l\’œil.', 28153),
(160517, 'frFR', 'Rentrons à Zuldazar.', 'Rentrons à Zuldazar.', 28153),
(160516, 'frFR', 'Nous avons tout perdu !', 'Nous avons tout perdu !', 28153),
(160515, 'frFR', 'Regardez ! C\’est l\’intrépide qui nous a aidés à fuir.', 'Regardez ! C\’est l\’intrépide qui nous a aidés à fuir.', 28153),
(160514, 'frFR', 'Ils ne vont certainement pas nous garder ici indéfiniment.', 'Ils ne vont certainement pas nous garder ici indéfiniment.', 28153),
(160513, 'frFR', 'Argh ! Il y a BEAUCOUP trop de lumière ici !', 'Argh ! Il y a BEAUCOUP trop de lumière ici !', 28153),
(160512, 'frFR', 'L\’entrée de la chambre est par là. Venez !', '', 28153),
(160511, 'frFR', 'Lordaeron appartient aux Réprouvés !', 'Lordaeron appartient aux Réprouvés !', 28153),
(160510, 'frFR', '', 'Notre arrivée est tombée à pic. Thorgen n\’aurait pas survécu longtemps sans renforts… quoi qu\’en dise le Nain.', 28153),
(160509, 'frFR', 'Vous êtes de retour. On y retourne ?', '', 28153),
(160508, 'frFR', 'Je veux à nouveau invoquer une gargouille au lieu d\’une Val\’kyr avec mon sort d\’invocation d\’une gargouille.', 'Je veux à nouveau invoquer une gargouille au lieu d\’une Val\’kyr avec mon sort d\’invocation d\’une gargouille.', 28153),
(160507, 'frFR', 'Je veux apprendre à invoquer une Val\’kyr au lieu d\’une gargouille avec mon sort d\’invocation d\’une gargouille.', 'Je veux apprendre à invoquer une Val\’kyr au lieu d\’une gargouille avec mon sort d\’invocation d\’une gargouille.', 28153),
(160506, 'frFR', 'La Horde ? Prenez ce que vous voulez, mais laissez-moi la vie sauve !', '', 28153),
(160505, 'frFR', 'Hé, rendez-moi ça !', '', 28153),
(160504, 'frFR', '<Récupérer le corps de Derek Portvaillant.>', '<Récupérer le corps de Derek Portvaillant.>', 28153),
(160503, 'frFR', '<Récupérer le corps du maréchal Valentine.>', '<Récupérer le corps du maréchal Valentine.>', 28153),
(160502, 'frFR', 'Des âmEs se rePAissent dEs huRlemEnTs inceSsAnts Qui déchiRent les téNèbrEs. Vous-mÊme, voUs les rejOindreZ bIenTôt.', 'Des âmEs se rePAissent dEs huRlemEnTs inceSsAnts Qui déchiRent les téNèbrEs. Vous-mÊme, voUs les rejOindreZ bIenTôt.', 28153),
(160501, 'frFR', '', 'La Horde marche sur Lor\’danel ! Héraut, avec moi !', 28153),
(160500, 'frFR', '', 'À vous de jouer ! Ordonnez à votre mascotte d\’attaquer !', 28153),
(160499, 'frFR', '', 'Prends ça, vieille bique !', 28153),
(160498, 'frFR', '', 'Ah ! Même pas peur ! Je vais t\’envoyer des étoiles dans la tête !', 28153),
(160497, 'frFR', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Portvaillant\n\nPrince héritier de Kul Tiras', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Portvaillant\n\nPrince héritier de Kul Tiras', 28153),
(160496, 'frFR', '', 'Votre magie impie ne peut pas vous protéger, Dreven !', 28153),
(160495, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMaréchal M. Valentine\n\nCapitaine de la Fierté de Tiragarde\nMaréchal de la troisième flotte kultirassienne', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMaréchal M. Valentine\n\nCapitaine de la Fierté de Tiragarde\nMaréchal de la troisième flotte kultirassienne', 28153),
(160494, 'frFR', 'Il va sans dire que cette mission est de la plus haute importance, $n. La Dame noire s\’en remet à nous pour accomplir sa volonté.', '', 28153),
(160493, 'frFR', '', 'Nous allons attaquer le prince de sang Dreven ensemble. Pas de quartier. Il ne doit pas s\’échapper.', 28153),
(160492, 'frFR', 'Prévenez-moi quand nous pourrons commencer.', '', 28153),
(160491, 'frFR', 'Oui ! C\’est le vaisseau amir… Ah non. C\’est juste une saleté sur la lunette.', 'Oui ! C\’est le vaisseau amir… Ah non. C\’est juste une saleté sur la lunette.', 28153),
(160490, 'frFR', 'Vous avez les Kultirassiens en vue ?', 'Vous avez les Kultirassiens en vue ?', 28153),
(160489, 'frFR', 'La boîte à secret réagit à la projection de Yogg-Saron !', 'La boîte à secret réagit à la projection de Yogg-Saron !', 28153),
(160488, 'frFR', 'Votre clan est condamné, Geya\’rah. Mais moi, j\’ai fait en sorte que le mien survive longtemps après la chute du vôtre.', '', 28153),
(160487, 'frFR', '', '|TInterface\\Icons\\Ability_Mage_RayofFrost:20|t%s active les |cFFFF0000|Hspell:268253|h[Rayons défensifs d\’Uldir]|h|r !', 28153),
(160486, 'frFR', '', 'Silence ! Si vous ne vous calmez pas tout de suite, c\’est moi qui vous calmerai.', 28153),
(160485, 'frFR', 'Aidez-moi avec ces cordes !', 'Aidez-moi avec ces cordes !', 28153),
(160484, 'frFR', 'Ne les laissez pas me manger !', 'Ne les laissez pas me manger !', 28153),
(160483, 'frFR', 'À l\’aide !', 'À l\’aide !', 28153),
(160482, 'frFR', 'Vous êtes incapable de protéger votre propre peuple, fille des loups. Pourquoi devrions-nous vous suivre ?', '', 28153),
(160481, 'frFR', '', 'Que signifie ce soulèvement, Kor\’gall ? Vous savez pourtant que nous devons plus que jamais faire front commun.', 28153),
(160480, 'frFR', 'Akunda, le Loa des tempêtes.', 'Akunda, le Loa des tempêtes.', 28153),
(160479, 'frFR', 'Kimbul, le seigneur des bêtes.', 'Kimbul, le seigneur des bêtes.', 28153),
(160478, 'frFR', 'Bwonsamdi, le Loa de la mort.', 'Bwonsamdi, le Loa de la mort.', 28153),
(160477, 'frFR', 'Krag\’wa le Colossal.', 'Krag\’wa le Colossal.', 28153),
(160476, 'frFR', '', 'On dirait que le maréchal Valentine a livré notre message. La flotte des Portvaillant a mordu à l\’hameçon.', 28153),
(160475, 'frFR', '', 'Cet avant-poste est dangereusement près de la ville, mais il est bien caché et nous offre une vue imprenable sur le Trône doré.\n\nNos espions pourront y observer les moindres faits et gestes du roi Rastakhan et de la Horde.', 28153),
(160474, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(160473, 'frFR', 'Le rituel de passage exige une coopération pleine et entière.\n\nPeut-on commencer ?', '', 28153),
(160472, 'frFR', 'Cela… fait froid dans le dos, n\’est-ce pas ? J\’imagine que si nous voulions attirer l\’attention de dame Portvaillant…', '', 28153),
(160471, 'frFR', 'Au Feu !', 'Au Feu !', 28153),
(160470, 'frFR', 'Appelez les pompiers !', 'Appelez les pompiers !', 28153),
(160469, 'frFR', 'Au feu ! Au feu !', 'Au feu ! Au feu !', 28153),
(160468, 'frFR', 'Ça n\’a pas dû être simple. Faut ouvrir l\’œil.', 'Ça n\’a pas dû être simple. Faut ouvrir l\’œil.', 28153),
(160467, 'frFR', 'Comment est-ce qu\’ils ont fait pour s\’introduire dans la prison ?', 'Comment est-ce qu\’ils ont fait pour s\’introduire dans la prison ?', 28153),
(160466, 'frFR', 'Décidément, cette maudite Coursevent est prête à tout.', 'Décidément, cette maudite Coursevent est prête à tout.', 28153),
(160465, 'frFR', 'J\’ai entendu dire qu\’ils essayaient d\’assassiner le roi.', 'J\’ai entendu dire qu\’ils essayaient d\’assassiner le roi.', 28153),
(160464, 'frFR', 'Ils ne comptent tout de même pas attaquer la ville avec si peu d\’hommes ?', 'Ils ne comptent tout de même pas attaquer la ville avec si peu d\’hommes ?', 28153),
(160463, 'frFR', 'Je ne peux laisser passer personne. Ordres du roi.', 'Je ne peux laisser passer personne. Ordres du roi.', 28153),
(160462, 'frFR', 'Il ne vous sera fait aucun mal, ni à vous ni à votre famille. Rentrez immédiatement chez vous.', 'Il ne vous sera fait aucun mal, ni à vous ni à votre famille. Rentrez immédiatement chez vous.', 28153),
(160461, 'frFR', 'Je vous ai déjà dit tout ce que je savais. À présent, rentrez chez vous.', 'Je vous ai déjà dit tout ce que je savais. À présent, rentrez chez vous.', 28153),
(160460, 'frFR', 'Je vous en prie, ma fille vit dans le quartier commerçant. Je dois la rejoindre !', 'Je vous en prie, ma fille vit dans le quartier commerçant. Je dois la rejoindre !', 28153),
(160459, 'frFR', 'Laissez-moi passer sur-le-champ ! J\’exige de parler à votre supérieur.', 'Laissez-moi passer sur-le-champ ! J\’exige de parler à votre supérieur.', 28153),
(160458, 'frFR', 'Qu\’est-ce que c\’est que ce raffut ? Avez-vous la moindre idée de l\’heure qu\’il est ?', 'Qu\’est-ce que c\’est que ce raffut ? Avez-vous la moindre idée de l\’heure qu\’il est ?', 28153),
(160457, 'frFR', 'Combien sont-ils ? Est-ce qu\’on est attaqués ?', 'Combien sont-ils ? Est-ce qu\’on est attaqués ?', 28153),
(160456, 'frFR', 'D\’après vous, le roi est en danger ?', 'D\’après vous, le roi est en danger ?', 28153),
(160455, 'frFR', 'Chut. Va te cacher à l\’intérieur, comme je t\’ai montré.', 'Chut. Va te cacher à l\’intérieur, comme je t\’ai montré.', 28153),
(160454, 'frFR', 'J\’ai peur…', 'J\’ai peur…', 28153),
(160453, 'frFR', 'Que se passe-t-il ? Pourquoi le portail est-il fermé ?', 'Que se passe-t-il ? Pourquoi le portail est-il fermé ?', 28153),
(160452, 'frFR', 'Je veux pas de problème, moi, $r.', 'Je veux pas de problème, moi, $r.', 28153),
(160451, 'frFR', 'Hein ? Heu, et c\’est normal, qu\’ils soient là… ?', 'Hein ? Heu, et c\’est normal, qu\’ils soient là… ?', 28153),
(160450, 'frFR', 'C\’est donc ainsi que Hurlevent va disparaître ? Hah. Et je suis aux premières loges !', 'C\’est donc ainsi que Hurlevent va disparaître ? Hah. Et je suis aux premières loges !', 28153),
(160449, 'frFR', 'Gardes ! Gardes ?!', 'Gardes ! Gardes ?!', 28153),
(160448, 'frFR', 'Ne vous approchez pas. Je n\’ai pas l\’intention de mourir ici.', 'Ne vous approchez pas. Je n\’ai pas l\’intention de mourir ici.', 28153),
(160447, 'frFR', 'Oui ! Vous êtes mon ticket de sortie, $r !', 'Oui ! Vous êtes mon ticket de sortie, $r !', 28153),
(160446, 'frFR', 'Hé ! Venez par ici et sortez-moi de là !', 'Hé ! Venez par ici et sortez-moi de là !', 28153),
(160445, 'frFR', 'Que se passe-t-il ? Que fait la Horde ici ?!', 'Que se passe-t-il ? Que fait la Horde ici ?!', 28153),
(160444, 'frFR', 'Une fois le plus fort des gardes neutralisé, notre ami Oculeth ouvrira un portail pour $n et Zelling, qui se chargeront alors de récupérer le sceptre.', '', 28153),
(160443, 'frFR', 'Les troupes d\’élite des Portvaillant devraient débarquer d\’une minute à l\’autre pour tenter de récupérer le corps de Derek.', '', 28153),
(160442, 'frFR', 'Ça, c\’est Hannibal. C\’est le faucon messager le plus rapide de Kul Tiras.', '', 28153),
(160441, 'frFR', 'Une unité de traitement des déchets s\’ouvre, formant une masse mutée.', 'Une unité de traitement des déchets s\’ouvre, formant une masse mutée.', 28153),
(160440, 'frFR', 'Héraut ! Azeroth a besoin de vous ! Rejoignez-moi en Silithus. J\’ai quelque chose à vous montrer.', '', 28153),
(160439, 'frFR', 'C\’est pas comme ça que ça doit se passer. C\’est moi qui suis censé gagner !', '', 28153),
(160438, 'frFR', 'Le centre d\’entraînement de mascottes de combat de Mastoc, ça sonne drôlement bien, dis donc. Et maintenant, la victoire est quasiment à ma portée !', '', 28153),
(160437, 'frFR', 'Maintenant que j\’y pense, je devrais diversifier mon équipe de familiers. Trois de la même espèce, quelle drôle d\’idée.', '', 28153),
(160436, 'frFR', 'Avec tous ces aiguillons acérés et leur petit air vicieux, vous pensiez vraiment pouvoir les battre ?', '', 28153),
(160435, 'frFR', 'Ces petits gars sont peut-être étranges, mais ils sont plutôt costauds. Vous tenez vraiment à ce que le combat ait lieu ?', '', 28153),
(160434, 'frFR', '', 'Inattendu.', 28153),
(160433, 'frFR', '', 'Annihilé !', 28153),
(160432, 'frFR', '', 'Eh bien, je ne m\’attendais pas à ça. Comptez sur moi pour vous donner une leçon la prochaine fois.', 28153),
(160431, 'frFR', '', 'Je vous l\’avais pourtant bien dit, mon équipe est tout simplement la meilleure.', 28153),
(160430, 'frFR', '', 'Avant de commencer, je voulais juste vous rappeler de ne pas trop vous en vouloir quand mon équipe balayera la vôtre.', 28153),
(160429, 'frFR', 'L\’odeur du sang dans l\’eau ne fera qu\’attirer plus de requins.', '', 28153),
(160428, 'frFR', 'C\’est l\’heure du repas, les gars !', '', 28153),
(160427, 'frFR', 'Vous m\’avez battu, la belle affaire ! Je suis toujours coincé ici pour l\’éternité. Au moins, j\’aurai parlé à quelqu\’un aujourd\’hui.', '', 28153),
(160426, 'frFR', 'Une personne contre un requin, ça peut être un combat équilibré. Mais une personne contre trois ? C\’est du délire.', '', 28153),
(160425, 'frFR', 'Si vous tenez à vaincre ceux de mon espèce, il va vous falloir un plus gros bateau.', '', 28153),
(160424, 'frFR', '', 'Votre détermination est admirable, mais votre sort est déjà scellé.', 28153),
(160423, 'frFR', '', 'Retournez d\’où vous venez !', 28153),
(160422, 'frFR', '', 'Cela n\’était pas censé se produire, pas selon la prophétie.', 28153),
(160421, 'frFR', '', 'Il va vous falloir des années d\’entraînement avant de pouvoir vous mesurer à une pointure comme moi.', 28153),
(160420, 'frFR', '', 'Avec toutes les créatures étranges qui rôdent sur cette île, le combat promet d\’être des plus surprenants.', 28153),
(160419, 'frFR', '', 'Vous seriez plus à votre place comme appât sur un bateau de pêche qu\’en tant qu\’adversaire pour mon équipe.', 28153),
(160418, 'frFR', '', 'En tout cas, on dirait que celui-là dort avec les poissons maintenant !', 28153),
(160417, 'frFR', '', 'Un de perdu dix de retrouvés, hein ? Finalement, je me demande si j\’ai bien compris le sens de ce proverbe…', 28153),
(160416, 'frFR', '', 'Je suis plus que confiante.', 28153),
(160415, 'frFR', '', 'J\’ai trouvé la plus impitoyable des créatures marines pour compléter mon équipe. Vous n\’avez pas la moindre chance !', 28153),
(160414, 'frFR', 'À chaque fois que j\’entraîne mes abeilles, c\’est la même rengaine. Elles gagnent en taille, en puissance et semblent imbattables, et puis elles piquent quelque chose et elles meurent.', '', 28153),
(160413, 'frFR', 'Un point pour les abeilles !', '', 28153),
(160412, 'frFR', 'Non, pas mes abeilles ! Non !', '', 28153),
(160411, 'frFR', 'Les abeilles sont nettement supérieures. En voici la preuve.', '', 28153),
(160410, 'frFR', 'Avant de commencer le combat, n\’oubliez pas que c\’est vous qui l\’avez cherché.', '', 28153),
(160409, 'frFR', '', 'C\’était celui que je préférais le moins dans le lot. L\’heure est venue de sortir l\’artillerie lourde. Préparez-vous !', 28153),
(160408, 'frFR', '', 'Et un point pour l\’équipe Fizzie !', 28153),
(160407, 'frFR', '', 'Mais mes familiers sont imprégnés d\’azérite ! Toutes les créatures en raffolent !', 28153),
(160406, 'frFR', '', 'Ça ne me surprend pas vraiment, mon équipe est tout simplement la meilleure.', 28153),
(160405, 'frFR', '', 'Vous croyez vraiment que vos familiers ont la moindre chance contre mon équipe imprégnée d\’azérite ? Dans vos rêves !', 28153),
(160404, 'frFR', '', 'Il y a beaucoup de créatures à Zuldazar, certaines sont minuscules, d\’autres immenses. J\’ai entrepris de capturer et d\’entraîner les plus petites d\’entre elles, car je suis persuadée que les petits ruisseaux font les grandes rivières.', 28153),
(160403, 'frFR', '', 'Retrouvez-moi sous le pont quand vous aurez terminé. Je vais trouver un moyen de détruire la barrière qui protège le prince de sang Dreven.', 28153),
(160402, 'frFR', 'Le dévoreur fétide est parvenu à |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t utiliser |cFFFF0000|Hspell:262370|h[Consommer la corruption]|h|r ! Tuez les corpuscules de corruption dès qu\’ils apparaissent !', 'Le dévoreur fétide est parvenu à |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t utiliser |cFFFF0000|Hspell:262370|h[Consommer la corruption]|h|r ! Tuez les corpuscules de corruption dès qu\’ils apparaissent !', 28153),
(160401, 'frFR', 'Shandris vous attend à bord. Bonne chance.', '', 28153),
(160400, 'frFR', 'Joli coup d\’poignet ! Allez, en route pour la Risée écarlate !', '', 28153),
(160399, 'frFR', '', 'Aaaaargh !', 28153),
(160398, 'frFR', '', 'OUUIIII ! Le sang de G\’huun coule dans nos veines !', 28153),
(160397, 'frFR', '', 'Le sang de notre maître… notre chair, nos vies pour G\’huun !', 28153),
(160396, 'frFR', 'T\’inquiète pas, Vol-au-Vent. Les canons d\’la Horde nous auront pas.', '', 28153),
(160395, 'frFR', 'Wahou ! C\’est trop génial ! Merci beaucoup !', 'Wahou ! C\’est trop génial ! Merci beaucoup !', 28153),
(160394, 'frFR', 'Vous… vous nous avez apporté d\’autres bonbons ? Encore meilleurs ?', 'Vous… vous nous avez apporté d\’autres bonbons ? Encore meilleurs ?', 28153),
(160393, 'frFR', 'Hé, $r ! C\’est vous qui avez pris nos bonbons !', 'Hé, $r ! C\’est vous qui avez pris nos bonbons !', 28153),
(160392, 'frFR', '<Seuls quelques emballages de bonbons témoignent de votre rafle sur ce coffre… Les emballages, et votre propre honte.>', '<Seuls quelques emballages de bonbons témoignent de votre rafle sur ce coffre… Les emballages, et votre propre honte.>', 28153),
(160391, 'frFR', '<Placer de meilleurs bonbons dans le coffre.>', '<Placer de meilleurs bonbons dans le coffre.>', 28153),
(160390, 'frFR', 'J\’ai hâte d\’exhumer les secrets de Xibala. Cet endroit soulève tant de questions !\n\nQui est Xibala ? De quoi s\’agit-il ? Pourquoi les Zandalari ont-ils déserté ces lieux ? À quoi sert l\’Œil de Xibala ?\n\nSous la supervision de l\’examinatrice Tae\’shara, je suis sûr que nous le découvrirons !', 'J\’ai hâte d\’exhumer les secrets de Xibala. Cet endroit soulève tant de questions !\n\nQui est Xibala ? De quoi s\’agit-il ? Pourquoi les Zandalari ont-ils déserté ces lieux ? À quoi sert l\’Œil de Xibala ?\n\nSous la supervision de l\’examinatrice Tae\’shara, je suis sûre que nous le découvrirons !', 28153),
(160389, 'frFR', 'Vous croyez qu\’Astrandis accepterait de me présenter au télémancien en chef Oculeth… ?\n\nJ\’ai lu tant de choses à son sujet. À votre avis, il signerait mon tabard ?', 'Vous croyez qu\’Astrandis accepterait de me présenter au télémancien en chef Oculeth… ?\n\nJ\’ai lu tant de choses à son sujet. À votre avis, il signerait mon tabard ?', 28153),
(160388, 'frFR', 'Force m\’est de reconnaître qu\’après avoir passé des lustres cloîtrés dans un petit paradis où le vin coule à flots, ces Sacrenuit s\’adaptent remarquablement bien aux rigueurs du monde extérieur.\n\nJ\’ai même réussi à inculquer à l\’un d\’entre eux l\’art de manier une pelle !', 'Force m\’est de reconnaître qu\’après avoir passé des lustres cloîtrés dans un petit paradis où le vin coule à flots, ces Sacrenuit s\’adaptent remarquablement bien aux rigueurs du monde extérieur.\n\nJ\’ai même réussi à inculquer à l\’un d\’entre eux l\’art de manier une pelle !', 28153),
(160387, 'frFR', 'L\’examinatrice Tae\’shara a une patience d\’ange. Elle a toutes les qualités requises pour succéder à son père s\’il renonçait à son poste.\n\nCela dit, je me demande si cet Astrandis ne chercherait pas à la pousser à bout.', 'L\’examinatrice Tae\’shara a une patience d\’ange. Elle a toutes les qualités requises pour succéder à son père s\’il renonçait à son poste.\n\nCela dit, je me demande si cet Astrandis ne chercherait pas à la pousser à bout.', 28153),
(160386, 'frFR', 'Le Reliquaire a sauté sur l\’occasion de fouiller ce site. Nous avons de la chance que les Trolls qui vivent dans le coin ne s\’y soient pas opposés.', 'Le Reliquaire a sauté sur l\’occasion de fouiller ce site. Nous avons de la chance que les Trolls qui vivent dans le coin ne s\’y soient pas opposés.', 28153),
(160385, 'frFR', 'J\’ai donné une pioche à un Sacrenuit et il m\’a regardé d\’un air ahuri.\n\n« À quoi ça sert ? » m\’a-t-il demandé, comme s\’il n\’en avait pas la moindre idée.\n\nLeurs prouesses magiques en disent long sur les talents de leur race, mais ils ont encore beaucoup à apprendre du monde extérieur. Par chance, nous autres Sin\’dorei, nous avons tout le nécessaire pour les instruire.', 'J\’ai donné une pioche à un Sacrenuit et il m\’a regardée d\’un air ahuri.\n\n« À quoi ça sert ? » m\’a-t-il demandé, comme s\’il n\’en avait pas la moindre idée.\n\nLeurs prouesses magiques en disent long sur les talents de leur race, mais ils ont encore beaucoup à apprendre du monde extérieur. Par chance, nous autres Sin\’dorei, nous avons tout le nécessaire pour les instruire.', 28153),
(160384, 'frFR', 'Les Sacrenuit se sont avérés incroyablement utiles au cours de cette expédition, mais pas de la façon dont je m\’y attendais.\n\nLe moins qu\’on puisse dire, c\’est qu\’ils aiment voyager dans le confort, et c\’est un plus non négligeable par rapport à la rigueur habituelle d\’un bivouac.\n\n<Il sirote un verre de vin.>', 'Les Sacrenuit se sont avérés incroyablement utiles au cours de cette expédition, mais pas de la façon dont je m\’y attendais.\n\nLe moins qu\’on puisse dire, c\’est qu\’ils aiment voyager dans le confort, et c\’est un plus non négligeable par rapport à la rigueur habituelle d\’un bivouac.\n\n<Elle sirote un verre de vin.>', 28153),
(160383, 'frFR', 'Ne vous retournez pas, mais je crois bien que ce Shal\’dorei tient son outil d\’analyse à l\’envers.', 'Ne vous retournez pas, mais je crois bien que ce Shal\’dorei tient son outil d\’analyse à l\’envers.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160382, 'frFR', 'Je dois admettre que je ne savais pas dans quoi je m\’embarquais quand j\’ai accepté de m\’aventurer dans cette étrange contrée.\n\nIl y fait plus chaud que je m\’y attendais. Bien plus chaud. Mais c\’est une occasion inestimable de servir la cause de la Première arcaniste et de nous faire bien voir de nos nouveaux alliés.\n\nAutant de bonnes raisons pour serrer les dents et garder le sourire.\n\n<Sur ce, il accroche tant bien que mal un sourire forcé à sa face.>', 'Je dois admettre que je ne savais pas dans quoi je m\’embarquais quand j\’ai accepté de m\’aventurer dans cette étrange contrée.\n\nIl y fait plus chaud que je m\’y attendais. Bien plus chaud. Mais c\’est une occasion inestimable de servir la cause de la Première arcaniste et de nous faire bien voir de nos nouveaux alliés.\n\nAutant de bonnes raisons pour serrer les dents et garder le sourire.\n\n<Sur ce, elle accroche tant bien que mal un sourire forcé à sa face.>', 28153),
(160381, 'frFR', 'J\’espère que nous faisons bonne impression aux Zandalari. C\’était très gentil de leur part de nous laisser étudier ce site, même si ce n\’était pas de gaieté de cœur.', 'J\’espère que nous faisons bonne impression aux Zandalari. C\’était très gentil de leur part de nous laisser étudier ce site, même si ce n\’était pas de gaieté de cœur.', 28153),
(160380, 'frFR', 'Vous croyez que nos alliés du Reliquaire me laisseront utiliser un de ces minuscules pinceaux ?', 'Vous croyez que nos alliés du Reliquaire me laisseront utiliser un de ces minuscules pinceaux ?', 28153),
(160379, 'frFR', 'Nos alliés sin\’dorei m\’ont raconté des anecdotes de leurs précédentes expéditions. Le moins qu\’on puisse dire, c\’est qu\’ils sont obnubilés par leurs escarmouches avec les Nains.', 'Nos alliés sin\’dorei m\’ont raconté des anecdotes de leurs précédentes expéditions. Le moins qu\’on puisse dire, c\’est qu\’ils sont obnubilés par leurs escarmouches avec les Nains.', 28153),
(160378, 'frFR', 'Vous croyez que les Trolls nous laisseront ramener une de ces étranges créatures au long cou à Suramar… ? Su\’esh aurait bien besoin d\’un compagnon !\n\nAllez leur demander, pour voir !', 'Vous croyez que les Trolls nous laisseront ramener une de ces étranges créatures au long cou à Suramar… ?\n\nAllez leur demander, pour voir !', 28153),
(160377, 'frFR', '<Il écrase un moustique à la volée.>\n\nQu\’est-ce qu\’il ne faut pas faire pour prouver notre valeur à la Horde ! Vous parlez de conditions de travail !', '<Elle écrase un moustique à la volée.>\n\nQu\’est-ce qu\’il ne faut pas faire pour prouver notre valeur à la Horde ! Vous parlez de conditions de travail !', 28153),
(160376, 'frFR', '<Il s\’évente vigoureusement de la main.>\n\nJusqu\’à présent, je ne m\’étais jamais rendu compte à quel point le climat de Suramar était agréable. Je serai bien content de rentrer quand ces fouilles seront terminées.', '<Elle s\’évente vigoureusement de la main.>\n\nJusqu\’à présent, je ne m\’étais jamais rendu compte à quel point le climat de Suramar était agréable. Je serai bien contente de rentrer quand ces fouilles seront terminées.', 28153),
(160375, 'frFR', 'J\’ai lu des tas d\’articles sur la jungle dans notre bibliothèque, mais aucun ne faisait mention de cette chaleur écrasante !\n\nMes vêtements me collent à la peau, et en plus, c\’est bourré d\’insectes ! Vous imaginez un peu ?\n\nQui peut vouloir vivre dans un endroit pareil ?', 'J\’ai lu des tas d\’articles sur la jungle dans notre bibliothèque, mais aucun ne faisait mention de cette chaleur écrasante !\n\nMes vêtements me collent à la peau, et en plus, c\’est bourré d\’insectes ! Vous imaginez un peu ?\n\nQui peut vouloir vivre dans un endroit pareil ?', 28153),
(160374, 'frFR', 'Oh, ces deux-là. Oui, ils arrêtent pas de se crêper le chignon. Vous les trouverez à l\’intérieur du Grand Sceau, sur le balcon du côté est.\n\nAvec tout ce raffut, je préfère passer au large. Même si je suis d\’accord avec la Taurène. Ou presque.', 'Oh, ces deux-là. Oui, ils arrêtent pas de se crêper le chignon. Vous les trouverez à l\’intérieur du Grand Sceau, sur le balcon du côté est.\n\nAvec tout ce raffut, je préfère passer au large. Même si je suis d\’accord avec la Taurène. Ou presque.', 28153),
(160373, 'frFR', 'Vous devriez vous adresser à Lagêne et Ulla. Ces deux-là n\’arrêtent pas de se disputer au sujet de la politique du chef de guerre. De toute évidence, c\’est Lagêne qui a raison, mais cette Ulla, bénie soit-elle, elle est têtue comme une mule.\n\nRendez-vous dans le Grand Sceau. Vous ne pouvez pas les rater, ils sont sur le balcon est, au-dessus de la galerie.', 'Vous devriez vous adresser à Lagêne et Ulla. Ces deux-là n\’arrêtent pas de se disputer au sujet de la politique du chef de guerre. De toute évidence, c\’est Lagêne qui a raison, mais cette Ulla, bénie soit-elle, elle est têtue comme une mule.\n\nRendez-vous dans le Grand Sceau. Vous ne pouvez pas les rater, ils sont sur le balcon est, au-dessus de la galerie.', 28153),
(160372, 'frFR', 'Elle est belle, ma morue ! Vidée et prête à déguster !', '', 28153),
(160371, 'frFR', 'La prise du jour ! Du requin tout frais harponné ce matin !', '', 28153),
(160370, 'frFR', 'Et guidez nos navires jusqu\’à l\’autre côté.', '', 28153),
(160369, 'frFR', 'Ouvrez pour nous la voie lors de la traversée.', '', 28153),
(160368, 'frFR', 'Traversez le brouillard et regagnez les terres.', '', 28153),
(160367, 'frFR', 'Ô, revenez à nous, vous qui courez les mers.', '', 28153),
(160366, 'frFR', 'Sur les eaux éclairées, voguez jusqu\’au rivage.', '', 28153),
(160365, 'frFR', 'Nos lanternes brillent et invitent au voyage.', '', 28153),
(160364, 'frFR', 'Leurs chants vous appellent à rejoindre le rivage.', '', 28153),
(160363, 'frFR', 'Entendez donc les cloches qui tintent sur la mer.', '', 28153),
(160362, 'frFR', 'Fendez le bleu des eaux sous un ciel sans nuage.', '', 28153),
(160361, 'frFR', 'Bien du sang a coulé pour dissiper l\’orage.', '', 28153),
(160360, 'frFR', 'Quittez les profondeurs et rejoignez vos frères.', '', 28153),
(160359, 'frFR', 'Vous, esprits harassés, qui errez sous les flots.', '', 28153),
(160358, 'frFR', 'Ô, courants et marées, livrez ces humbles mots :', '', 28153),
(160357, 'frFR', '', 'Avec le meilleur jambon des royaumes de l\’Est ! Arrivage direct de Havrebrune !', 28153),
(160356, 'frFR', '', 'Saucisses pour tous ! Dernier arrivage de Drustvar et de Hurlevent !', 28153),
(160355, 'frFR', '', 'Rien de tel qu\’une petite bière exotique en faisant son marché ! Et si vous n\’aimez pas la bière, j\’ai aussi de nombreuses variétés de thé !', 28153),
(160354, 'frFR', '', 'Elle est bonne, ma bière, elle est bonne ! Importée directement de Pandarie !', 28153),
(160353, 'frFR', 'Hé ! Vous, là-bas ! Oui, vous ! J\’ai ici quelque chose qui pourrait vous intéresser.', '', 28153),
(160352, 'frFR', 'Aujourd\’hui plus que jamais, le chef de guerre a besoin de pouvoir compter sur une armée bien huilée. Votre guilde, quel sacrifice est-elle prête à consentir pour servir la cause de la Horde ?', '', 28153),
(160351, 'frFR', '', 'Choux frais du pays !', 28153),
(160350, 'frFR', '', 'Légumes frais en provenance des fermes de Chantorage ! Venez goûter le meilleur maïs au monde !', 28153),
(160349, 'frFR', 'Je ne sais pas où est le navire, à l\’heure qu\’il est.', 'Je ne sais pas où est le navire, à l\’heure qu\’il est.', 28153),
(160348, 'frFR', 'À l\’heure qu\’il est, l\’Implacable vient juste de quitter les quais de Hurlevent.', 'À l\’heure qu\’il est, l\’Implacable vient juste de quitter les quais de Hurlevent.', 28153),
(160347, 'frFR', 'À l\’heure qu\’il est, l\’Implacable vient juste de quitter Boralus.', 'À l\’heure qu\’il est, l\’Implacable vient juste de quitter Boralus.', 28153),
(160346, 'frFR', 'Si jamais vous avez un problème de chaussures, revenez me voir. D\’ici là, profitez bien de votre nouveau cirage !', '', 28153),
(160345, 'frFR', 'Et un cirage de pompes, un !', '', 28153),
(160344, 'frFR', 'Vous êtes du métier ? Bien, on a toujours besoin de spécialistes. Si vous cherchez du matériel spécialisé, il faut vous adresser au Tauren Hanul Vive-Rafale. Vous le trouverez dans le hall des Voies antiques, du côté est du Grand Sceau.', 'Vous êtes du métier ? Bien, on a toujours besoin de spécialistes. Si vous cherchez du matériel spécialisé, il faut vous adresser au Tauren Hanul Vive-Rafale. Vous le trouverez dans le hall des Voies antiques, du côté est du Grand Sceau.', 28153),
(160343, 'frFR', 'Si vous cherchez des marchandises, vous devriez vous rendre au Grand Sceau. Une fois à l\’intérieur, allez dans le hall des Voies antiques, côté est, et adressez-vous au Tauren Hanul Vent-Agile. Vous devriez trouver votre bonheur.', 'Si vous cherchez des marchandises, vous devriez vous rendre au Grand Sceau. Une fois à l\’intérieur, allez dans le hall des Voies antiques, côté est, et adressez-vous au Tauren Hanul Vent-Agile. Vous devriez trouver votre bonheur.', 28153),
(160342, 'frFR', 'Des fournitures générales ? La Horde, elle a tout prévu. Allez voir l\’Orque Araka, dans le hall des Voies antiques. C\’est du côté est du Grand Sceau. Vous verrez, elle a tout le matériel qu\’il vous faut.', 'Des fournitures générales ? La Horde, elle a tout prévu. Allez voir l\’Orque Araka, dans le hall des Voies antiques. C\’est du côté est du Grand Sceau. Vous verrez, elle a tout le matériel qu\’il vous faut.', 28153),
(160341, 'frFR', 'Akara peut vous aider. Elle est dans le hall des Voies antiques, à l\’est du Grand Sceau.', 'Akara peut vous aider. Elle est dans le hall des Voies antiques, à l\’est du Grand Sceau.', 28153),
(160340, 'frFR', 'Vous voulez fonder une nouvelle guilde ? Il faut voir ça avec le gardien des quais Finnson et Perry Charlton. Ils forment un drôle de couple, ces deux-là, mais ils vous montreront les ficelles du métier.\n\nVous les trouverez dans le bâtiment qui se dresse juste à côté de l\’entrée du port, côté ville.', 'Vous voulez fonder une nouvelle guilde ? Il faut voir ça avec le gardien des quais Finnson et Perry Charlton. Ils forment un drôle de couple, ces deux-là, mais ils vous montreront les ficelles du métier.\n\nVous les trouverez dans le bâtiment qui se dresse juste à côté de l\’entrée du port, côté ville.', 28153),
(160339, 'frFR', 'Leila Stafford est la meilleure. Elle m\’a aidé plus d\’une fois quand ma petite Roudoudou était malade.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté ouest.', 'Leila Stafford est la meilleure. Elle m\’a aidé plus d\’une fois quand ma petite Roudoudou était malade.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté ouest.', 28153),
(160338, 'frFR', 'On avait un coiffeur avant, mais il a disparu récemment et personne ne sait ce qui lui est arrivé. Quand la nouvelle est tombée, la ville ne parlait plus que de ça.\n\nDepuis, c\’est un Gnome qui le remplace. Je ne dis pas ça pour vous, mais si vous avez besoin d\’une coupe ou d\’une couleur, allez voir Teri Champclos, à la pointe du Crochet. Par contre, évitez de lui tourner le dos.', 'On avait un coiffeur avant, mais il a disparu récemment et personne ne sait ce qui lui est arrivé. Quand la nouvelle est tombée, la ville ne parlait plus que de ça.\n\nDepuis, c\’est un Gnome qui le remplace. Je ne dis pas ça pour vous, mais si vous avez besoin d\’une coupe ou d\’une couleur, allez voir Teri Champclos, à la pointe du Crochet. Par contre, évitez de lui tourner le dos.', 28153),
(160337, 'frFR', '', 'Les nobles du coin raffolent du fjarnskaggl. D\’ailleurs, je suis de nouveau à court.\n\nRevenez la semaine prochaine, j\’en aurai peut-être reçu davantage.', 28153),
(160336, 'frFR', 'Vous avez déjà acheté tous les sceaux disponibles cette semaine. Ne me faites plus perdre mon temps.\n\nJ\’en recevrai d\’autres la semaine prochaine.', '', 28153),
(160335, 'frFR', 'Henrick Wyther vend du matériel de toute sorte pour les professionnels comme vous. Vous le trouverez au niveau supérieur du marché des Alizés.\n\nVous ne pouvez pas le rater, il est obsédé par les théories du complot. Surtout, n\’allez pas vous moquer de ses cartes et de ses notes. C\’est un brave type, et il prend toutes ces histoires très au sérieux.', 'Henrick Wyther vend du matériel de toute sorte pour les professionnels comme vous. Vous le trouverez au niveau supérieur du marché des Alizés.\n\nVous ne pouvez pas le rater, il est obsédé par les théories du complot. Surtout, n\’allez pas vous moquer de ses cartes et de ses notes. C\’est un brave type, et il prend toutes ces histoires très au sérieux.', 28153),
(160334, 'frFR', 'Fournitures d\’artisanat', 'Fournitures d\’artisanat', 28153),
(160333, 'frFR', 'Ne m\’en parlez pas, j\’ai dépensé une petite fortune en réparations. Heureusement, l\’amirauté a sa propre forge pour l\’entretien de notre équipement. Mais en ce qui concerne vos effets personnels, je vous recommande Patrick Markson. Oui, je sais qu\’il vend des armes à feu. Mais c\’est aussi un réparateur hors pair.\n\nVous trouverez son étal devant la fontaine, au niveau inférieur du marché des Alizés. C\’est juste en bas des escaliers qui mènent à l\’auberge.', 'Ne m\’en parlez pas, j\’ai dépensé une petite fortune en réparations. Heureusement, l\’amirauté a sa propre forge pour l\’entretien de notre équipement. Mais en ce qui concerne vos effets personnels, je vous recommande Patrick Markson. Oui, je sais qu\’il vend des armes à feu. Mais c\’est aussi un réparateur hors pair.\n\nVous trouverez son étal devant la fontaine, au niveau inférieur du marché des Alizés. C\’est juste en bas des escaliers qui mènent à l\’auberge.', 28153),
(160332, 'frFR', 'N\’avez-vous jamais rêvé d\’avoir une seconde chance ? Peut-être pour obtenir une pièce d\’armure spéciale, une arme ou encore un bijou surpuissant ?\n\nJe peux vous proposer un sceau qui vous permettra d\’infléchir le destin en vous offrant une deuxième chance d\’obtenir un objet.\n\nUne fois en votre possession, il s\’activera après une victoire sur de puissants ennemis dans de périlleux donjons et lors de dangereux raids.\n\nBientôt, je serai en mesure de vous fournir des sceaux du destin érodé contre de l\’or, des ressources de guerre ou des marques d\’honneur.\n\nMais je n\’en possède aucun pour l\’instant.', '', 28153),
(160331, 'frFR', 'Je vous propose d\’acquérir un sceau du destin érodé de diverses manières.\n\nÀ quoi préférez-vous renoncer pour avoir la chance d\’infléchir le sort ?', '', 28153),
(160330, 'frFR', 'Vous détenez déjà le nombre maximum de sceaux !\n\nUtilisez-les avant de m\’en réclamer d\’autres.', '', 28153),
(160329, 'frFR', 'Pour les fournitures générales, allez voir Ninette Shoames. Elle tient son étal tous les jours devant la fontaine, au niveau inférieur du marché des Alizés.', 'Pour les fournitures générales, allez voir Ninette Shoames. Elle tient son étal tous les jours devant la fontaine, au niveau inférieur du marché des Alizés.', 28153),
(160328, 'frFR', 'Ce quai sert désormais de débarcadère pour l\’Implacable.\n\nIl a été affrété par l\’Alliance comme principal moyen de transport pour les diplomates qui font la navette entre Hurlevent et Kul Tiras. Il vous emmènera tout droit au port de Boralus.', 'Ce quai sert désormais de débarcadère pour l\’Implacable.\n\nIl a été affrété par l\’Alliance comme principal moyen de transport pour les diplomates qui font la navette entre Hurlevent et Kul Tiras. Il vous emmènera tout droit au port de Boralus.', 28153),
(160327, 'frFR', 'Fournitures générales', 'Fournitures générales', 28153),
(160326, 'frFR', 'L\’Implacable vient régulièrement mettre à quai ici pour remmener les passagers sur le continent. Si vous allez à Hurlevent, ne cherchez pas plus loin. Il vous conduira tout droit au port de la ville.', 'L\’Implacable vient régulièrement mettre à quai ici pour remmener les passagers sur le continent. Si vous allez à Hurlevent, ne cherchez pas plus loin. Il vous conduira tout droit au port de la ville.', 28153),
(160325, 'frFR', 'Des marchands ? Je vois. Quel genre de marchandises, au juste ?', 'Des marchands ? Je vois. Quel genre de marchandises, au juste ?', 28153),
(160324, 'frFR', 'Un nouveau style ? Effectivement, ce serait pas du luxe. Aussi étrange que ça puisse paraître, c\’est au tisse-dimensions Ezil qu\’il faut vous adresser. Je sais, on ne dirait pas, à voir la façon dont il est fagoté. Et pourtant, vous pouvez me croire, il fait des miracles. Le plus dur, c\’est d\’avoir un rendez-vous.\n\nSa boutique est à côté de l\’auberge du Nid douillet.', 'Un nouveau style ? Effectivement, ce serait pas du luxe. Aussi étrange que ça puisse paraître, c\’est au tisse-dimensions Ezil qu\’il faut vous adresser. Je sais, on ne dirait pas, à voir la façon dont il est fagoté. Et pourtant, vous pouvez me croire, il fait des miracles. Le plus dur, c\’est d\’avoir un rendez-vous.\n\nSa boutique est à côté de l\’auberge du Nid douillet.', 28153),
(160323, 'frFR', 'Que vous vouliez apprendre une nouvelle technique de broderie ou l\’art de suturer une plaie ouverte, et même la confection de sacs, Daniel Tisse-Sel est l\’homme de la situation. Allez le voir au niveau supérieur du marché des Alizés, côté nord.\n\nC\’est un brave type, quoiqu\’un peu tristounet. D\’ailleurs, il m\’a recousu plus d\’une fois. Et il se fait toujours un plaisir de transmettre son savoir.', 'Que vous vouliez apprendre une nouvelle technique de broderie ou l\’art de suturer une plaie ouverte, et même la confection de sacs, Daniel Tisse-Sel est l\’homme de la situation. Allez le voir au niveau supérieur du marché des Alizés, côté nord.\n\nC\’est un brave type, quoiqu\’un peu tristounet. D\’ailleurs, il m\’a recousue plus d\’une fois. Et il se fait toujours un plaisir de transmettre son savoir.', 28153),
(160322, 'frFR', 'Vous faites dans la chasse au gros gibier ? Alors tenez-vous bien. Ces bestiaux, là-bas… ils ont la peau la plus dure que vous ayez jamais vue. Ouais, on plaisante pas avec ça, en Kul Tiras.\n\nSi vous voulez apprendre, il faut vous adresser aux meilleurs. Allez voir Camilla Sombre-Ciel, au niveau supérieur du marché des Alizés, côté nord.', 'Vous faites dans la chasse au gros gibier ? Alors tenez-vous bien. Ces bestiaux, là-bas… ils ont la peau la plus dure que vous ayez jamais vue. Ouais, on plaisante pas avec ça, en Kul Tiras.\n\nSi vous voulez apprendre, il faut vous adresser aux meilleurs. Allez voir Camilla Sombre-Ciel, au niveau supérieur du marché des Alizés, côté nord.', 28153),
(160321, 'frFR', 'En sécurité ? Vous avez vu les monstres qui rôdent dans les parages ?\n\nMerci bien, mais j\’aime autant garder mon arme… Histoire de ne pas la passer à gauche, justement.', '', 28153),
(160320, 'frFR', 'Votre arme ne vous sera d\’aucune utilité. Vous êtes en sécurité, ici.', 'Votre arme ne vous sera d\’aucune utilité. Vous êtes en sécurité, ici.', 28153),
(160319, 'frFR', 'Attendez-vous à tout.', '', 28153),
(160318, 'frFR', 'Les combats ne vont pas tarder à éclater. Nous aurions bien besoin de vous dans nos rangs, $r.', '', 28153),
(160317, 'frFR', 'Je le vois dans vos yeux : votre esprit est rongé par la folie. Le répit se trouve pourtant à votre portée.$b$bJadis, des sages ont combattu les ténèbres en ce lieu. Ils ont érigé des chapelles, ces remparts de foi et de détermination, mais également une taverne, pour noyer les murmures dans un océan d\’hydromel. Il ne reste plus que des gravats…$b$bDirigez-vous vers le nord-ouest et vous tomberez sur une relique de leur présence, une grande idole abyssale. Trouvez l\’effigie et vous parviendrez peut-être à chasser les horreurs qui envahissent ces lieux. Mais attention, vous devrez boire tout votre soûl et la mer le fait payer très cher.', '', 28153),
(160316, 'frFR', 'Je n\’ai pas les idées claires. Pouvez-vous m\’aider ?', 'Je n\’ai pas les idées claires. Pouvez-vous m\’aider ?', 28153),
(160315, 'frFR', 'Vous le sentez ? Les barrières… Elles sont en train de s\’effondrer. Ils arrivent, murmure terrifiant par murmure terrifiant.', '', 28153),
(160314, 'frFR', 'Il fut une époque où ces ruines étaient le fleuron de la vallée.', '', 28153),
(160313, 'frFR', 'Je dois vous avouer ne pas me rappeler à quelle époque cette lettre a été envoyée…', '', 28153),
(160312, 'frFR', 'N\’oubliez pas que l\’arrogance détruit tout, lentement et insidieusement.', '', 28153),
(160311, 'frFR', 'Vous cherchez à vous remplir les poches d\’or, de platine ou de foudrargent ? Si vous voulez apprendre les dernières techniques en matière de minage, il faut vous adresser à Myra Cabot. Elle a un sixième sens pour flairer les bons filons.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté nord. Pensez à moi si vous faites fortune…', 'Vous cherchez à vous remplir les poches d\’or, de platine ou de foudrargent ? Si vous voulez apprendre les dernières techniques en matière de minage, il faut vous adresser à Myra Cabot. Elle a un sixième sens pour flairer les bons filons.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté nord. Pensez à moi si vous faites fortune…', 28153),
(160310, 'frFR', 'D\’accord, on r\’viendra les achever plus tard.', '', 28153),
(160309, 'frFR', 'Ce n\’est pas mon truc, mais si vous voulez apprendre le travail du cuir, je connais la Kultirassienne qu\’il vous faut. Elle s\’appelle Cassandra Brennor et elle fait des miracles avec ses outils.\n\nElle passe le plus clair de son temps à travailler avec Camilla Sombre-Ciel. Elles partagent un emplacement au niveau supérieur du marché des Alizés, côté nord.', 'Ce n\’est pas mon truc, mais si vous voulez apprendre le travail du cuir, je connais la Kultirassienne qu\’il vous faut. Elle s\’appelle Cassandra Brennor et elle fait des miracles avec ses outils.\n\nElle passe le plus clair de son temps à travailler avec Camilla Sombre-Ciel. Elles partagent un emplacement au niveau supérieur du marché des Alizés, côté nord.', 28153),
(160308, 'frFR', 'Faites-moi signe quand vous voudrez lancer la mission de bombardement.', '', 28153),
(160307, 'frFR', 'Samuel D. Colton III est l\’homme de la situation. Il n\’est pas peu fier de lui, et je m\’étonne qu\’il ne se soit pas affublé de titres ronflants. Cela dit, il faut reconnaître que ses ouvrages sont exquis. Si vous voulez vous former, c\’est le meilleur des professeurs.\n\nVous le trouverez en train de trôner fièrement derrière sa vitrine, au centre du niveau supérieur du marché des Alizés, côté nord.', 'Samuel D. Colton III est l\’homme de la situation. Il n\’est pas peu fier de lui, et je m\’étonne qu\’il ne se soit pas affublé de titres ronflants. Cela dit, il faut reconnaître que ses ouvrages sont exquis. Si vous voulez vous former, c\’est le meilleur des professeurs.\n\nVous le trouverez en train de trôner fièrement derrière sa vitrine, au centre du niveau supérieur du marché des Alizés, côté nord.', 28153),
(160306, 'frFR', 'Il faut voir ça avec Zoé Encrenage. Depuis quelque temps, elle loue un emplacement au niveau supérieur du marché des Alizés, côté nord.\n\nOn a du mal à croire qu\’une si petite bonne femme puisse avoir autant d\’énergie et de savoir-faire.', 'Il faut voir ça avec Zoé Encrenage. Depuis quelque temps, elle loue un emplacement au niveau supérieur du marché des Alizés, côté nord.\n\nOn a du mal à croire qu\’une si petite bonne femme puisse avoir autant d\’énergie et de savoir-faire.', 28153),
(160305, 'frFR', 'Si nous voulons avoir la moindre chance de rallier les Zandalari à la cause de la Horde, nous devons nous serrer les coudes.', '', 28153),
(160304, 'frFR', 'Vous aimez les fleurs ? Moi aussi. Elles sentent si bon. Enfin, la plupart d\’entre elles, du moins.\n\nSi vous voulez apprendre les secrets de l\’horticulture telle qu\’on la pratique dans cette partie du monde, il faut vous adresser à Declan Senal. Vous le trouverez dans son jardin, au niveau supérieur du marché des Alizés, côté nord.', 'Vous aimez les fleurs ? Moi aussi. Elles sentent si bon. Enfin, la plupart d\’entre elles, du moins.\n\nSi vous voulez apprendre les secrets de l\’horticulture telle qu\’on la pratique dans cette partie du monde, il faut vous adresser à Declan Senal. Vous le trouverez dans son jardin, au niveau supérieur du marché des Alizés, côté nord.', 28153),
(160303, 'frFR', 'Quelqu\’un protège la Complainte de la Banshee avec une magie qui sent les eaugures !', '', 28153),
(160302, 'frFR', 'Alan Goyle tient une cabane de pêche au-dessus du marché des Alizés. Il passe ses journées à taquiner le fretin dans son plan d\’eau. Il faut croire que les poissons tombent directement des cascades, car il n\’est jamais à court.\n\nBref, pour y accéder, vous devez emprunter les escaliers nichés entre les maîtres des tailleurs et des joailliers.', 'Alan Goyle tient une cabane de pêche au-dessus du marché des Alizés. Il passe ses journées à taquiner le fretin dans son plan d\’eau. Il faut croire que les poissons tombent directement des cascades, car il n\’est jamais à court.\n\nBref, pour y accéder, vous devez emprunter les escaliers nichés entre les maîtres des tailleurs et des joailliers.', 28153),
(160301, 'frFR', 'Prenez mes marteaux, $p, et lancez-les de toutes vos forces !', '', 28153),
(160300, 'frFR', 'Marteaux-Hardis, concentrez-vous sur la Complainte de la Banshee ! Empêchez-les d\’intervenir !', '', 28153),
(160299, 'frFR', 'Vous faites dans l\’artillerie ou dans les inventions farfelues ? Les deux à la fois, peut-être ?\n\nBref, quoi qu\’il en soit, il faut voir ça avec Layla Tirando. Vous la trouverez en train de trafiquer ses engins au niveau supérieur du marché des Alizés, côté nord.', 'Vous faites dans l\’artillerie ou dans les inventions farfelues ? Les deux à la fois, peut-être ?\n\nBref, quoi qu\’il en soit, il faut voir ça avec Layla Tirando. Vous la trouverez en train de trafiquer ses engins au niveau supérieur du marché des Alizés, côté nord.', 28153),
(160298, 'frFR', '', 'Les Mag\’har… survivront…', 28153),
(160297, 'frFR', '', 'Votre heure est venue !', 28153),
(160296, 'frFR', 'Votre victoire… ne signifie rien…', '', 28153),
(160295, 'frFR', '', 'Vous mourrez !', 28153),
(160294, 'frFR', '', 'Regardez ! Ils mettent les voiles !', 28153),
(160293, 'frFR', '', 'Ha ha ! On fait moins les malins, maintenant !', 28153),
(160292, 'frFR', '', 'Lok\’tar ogar !', 28153),
(160291, 'frFR', '', 'Dranosh\’ek mag\’har !', 28153),
(160290, 'frFR', 'Je vous attends… dans les confins Corrompus…', '', 28153),
(160289, 'frFR', '', 'Nous ne céderons jamais !', 28153),
(160288, 'frFR', 'Notre combat n\’est pas… terminé… intrus…', '', 28153),
(160287, 'frFR', '', 'Pour les Mag\’har !', 28153),
(160286, 'frFR', 'Je… reviendrai…', '', 28153),
(160285, 'frFR', 'Imbéciles… vous n\’avez vaincu… qu\’un réceptacle…', '', 28153),
(160284, 'frFR', 'Vous pensez avoir gagné ? Et pourtant… Celle que vous cherchez ne se trouve pas ici.', '', 28153),
(160283, 'frFR', 'La fillette égarée est entre mes mains. Oh, elle ne cesse de pleurer. Ses souffrances seront éternelles !', '', 28153),
(160282, 'frFR', '', 'Si l\’azérite est capable de produire de tels ravages, je doute que la grande porte de Boralus résiste bien longtemps.', 28153),
(160281, 'frFR', '', 'Quel désastre… La porte de Daelin ne pouvait que céder.', 28153),
(160280, 'frFR', '', 'Visez les barils de poudre !', 28153),
(160279, 'frFR', 'Émilie Beautemps, voilà la personne qu\’il vous faut. Vous la trouverez tout en haut du marché des Alizés, côté nord.\n\nJ\’ai eu recours à ses services pour enchanter des brassards, une fois. Je vous la recommande chaudement.', 'Émilie Beautemps, voilà la personne qu\’il vous faut. Vous la trouverez tout en haut du marché des Alizés, côté nord.\n\nJ\’ai eu recours à ses services pour enchanter des brassards, une fois. Je vous la recommande chaudement.', 28153),
(160278, 'frFR', '', 'Les créatures du coin sont plutôt hargneuses, mais j\’ai la peau dure et j\’ai bien l\’intention de toutes les capturer. Il manque encore pas mal de spécimens à ma collection, mais les bestioles que j\’ai déjà prises envoient du lourd. Un petit combat, ça vous tente ?', 28153),
(160277, 'frFR', 'De la visite ? Comme c\’est étrange.', '', 28153),
(160276, 'frFR', 'Quand le dernier feu sera allumé, la ville saura que c\’est bon ! Et mon équipage, il pourra rentrer !', '', 28153),
(160275, 'frFR', 'Il est vulnérable au sein de son propre royaume. Il ne reculera devant rien pour vous empêcher d\’entrer.', '', 28153),
(160274, 'frFR', 'Bonne chance pour votre voyage. Restez sur vos gardes, les yeux de Gorak Tul épieront vos moindres faits et gestes.', '', 28153),
(160273, 'frFR', 'Le creux Verdoyant est une position de choix pour établir un avant-poste. La zone regorge d\’azérite et pas un Troll à l\’horizon ! Que demander de plus ?', '', 28153),
(160272, 'frFR', '', 'Nous connaissons bien les variétés d\’insectes qui pullulent sur ces terres. Certaines sont très dociles, d\’autres très dangereuses. Nous avons collecté bon nombre d\’espèces au fil des décennies, et nous adorons nous mesurer aux autres passionnés de combats de mascottes. Ça vous tente ?', 28153),
(160271, 'frFR', '', 'Essayons de lancer la prochaine depuis les airs, vous voulez bien ?', 28153),
(160270, 'frFR', '', 'Oulà ! Je dirais que nous étions un peu trop près…', 28153),
(160269, 'frFR', 'Déterrer', 'Déterrer', 28153),
(160268, 'frFR', 'Oh, vous cherchez le « cap\’taine » ? Il tient un estaminet entre l\’enclos et la fosse du forgeron, au niveau supérieur du marché des Alizés, côté nord.\n\nIl faut absolument que vous goûtiez le poisson-frites du marais. Rien que d\’y penser, j\’en ai l\’eau à la bouche !', 'Oh, vous cherchez le « cap\’taine » ? Il tient un estaminet entre l\’enclos et la fosse du forgeron, au niveau supérieur du marché des Alizés, côté nord.\n\nIl faut absolument que vous goûtiez le poisson-frites du marais. Rien que d\’y penser, j\’en ai l\’eau à la bouche !', 28153),
(160267, 'frFR', 'Si je sais où trouver le maître des forgerons ? Évidemment que je le sais. Je suis garde, non ?\n\nRendez-vous au niveau supérieur du marché des Alizés. Vous trouverez une fosse, côté nord. C\’est là que travaille le meilleur forgeron que je connaisse, Grix « Poings de fer » Barlow. Vous ne pouvez pas le rater.', 'Si je sais où trouver le maître des forgerons ? Évidemment que je le sais. Je suis garde, non ?\n\nRendez-vous au niveau supérieur du marché des Alizés. Vous trouverez une fosse, côté nord. C\’est là que travaille le meilleur forgeron que je connaisse, Grix « Poings de fer » Barlow. Vous ne pouvez pas le rater.', 28153),
(160266, 'frFR', 'Je vais commencer les préparatifs. Rejoignez-moi quand vous aurez tout réuni.', '', 28153),
(160265, 'frFR', 'Ce n\’est pas passé loin. Merci pour ce sauvetage in extremis !', 'Ce n\’est pas passé loin. Merci pour ce sauvetage in extremis !', 28153),
(160263, 'frFR', 'Je supervise toutes les formalités liées aux guildes et autres compagnies marchandes au sein du port. En quoi puis-je vous aider ?', '', 28153),
(160262, 'frFR', 'Vous cherchez à exhumer des trésors enfouis ? Vous avez bien raison. Pensez à investir dans un de ces engins d\’analyse, à l\’occasion.\n\nLa personne qu\’il vous faut, c\’est Jane Hudson, au niveau supérieur du marché des Alizés. Une fois là-haut, vous la trouverez dans son échoppe, côté ouest de la terrasse, près de l\’enclos.', 'Vous cherchez à exhumer des trésors enfouis ? Vous avez bien raison. Pensez à investir dans un de ces engins d\’analyse, à l\’occasion.\n\nLa personne qu\’il vous faut, c\’est Jane Hudson, au niveau supérieur du marché des Alizés. Une fois là-haut, vous la trouverez dans son échoppe, côté ouest de la terrasse, près de l\’enclos.', 28153),
(160261, 'frFR', '', 'Attention… Feu !', 28153),
(160260, 'frFR', 'Un maître des potions. Je vois. Ouaip, c\’est Elric Whalgrene qu\’il vous faut. Vous le trouverez à l\’extrémité nord du marché des Alizés, au niveau supérieur, au-dessus de la fosse du forgeron.\n\nNe vous fiez pas à son apparence, ce type-là est un grand sorcier, même s\’il a parfois de drôles d\’idées. Comme cette potion qui vous transforme en nuage, par exemple… Bizarre, pas vrai ? Par contre, je vous recommande chaudement sa potion de pied léger. Ce truc-là, ça vous donne des ailes.', 'Un maître des potions. Je vois. Ouaip, c\’est Elric Whalgrene qu\’il vous faut. Vous le trouverez à l\’extrémité nord du marché des Alizés, au niveau supérieur, au-dessus de la fosse du forgeron.\n\nNe vous fiez pas à son apparence, ce type-là est un grand sorcier, même s\’il a parfois de drôles d\’idées. Comme cette potion qui vous transforme en nuage, par exemple… Bizarre, pas vrai ? Par contre, je vous recommande chaudement sa potion de pied léger. Ce truc-là, ça vous donne des ailes.', 28153),
(160259, 'frFR', 'Si nous voulons panser les plaies de nos terres, nous devons garantir à tous la possibilité d\’expier ses fautes.', '', 28153),
(160258, 'frFR', 'Je ne peux qu\’imaginer les remords qui la rongent. Et combien elle doit, elle aussi, aspirer à la rédemption.', '', 28153),
(160257, 'frFR', 'En leur tournant le dos, dame Jaina a causé la mort de son père et des siens.', '', 28153),
(160256, 'frFR', 'Je ne cesse de me demander ce que j\’aurais pu faire de plus. Ces pensées hantent mes nuits.', '', 28153),
(160255, 'frFR', 'Je les ai certes arrachés aux griffes de la folie, mais je n\’en éprouve pas moins de culpabilité.', '', 28153),
(160254, 'frFR', 'J\’ai dû combattre et, parfois même tuer les miens. Ce fut une décision difficile mais inévitable.', '', 28153),
(160253, 'frFR', 'Nombre de mes compatriotes considèrent Jaina Portvaillant comme une traîtresse. Et beaucoup remettront en cause mon choix de lui venir en aide.', '', 28153),
(160252, 'frFR', 'Vous êtes du métier ? Vous cherchez à vous améliorer, c\’est ça ? Ne cherchez pas plus loin. Vous êtes à Boralus, le joyau de la civilisation.', 'Vous êtes du métier ? Vous cherchez à vous améliorer, c\’est ça ? Ne cherchez pas plus loin. Vous êtes à Boralus, le joyau de la civilisation.', 28153),
(160251, 'frFR', '$pr en vue ! Liquidez-moi ça !', '', 28153),
(160250, 'frFR', '', 'J\’ai arpenté ces dunes de long en large et j\’y ai trouvé les créatures les plus impressionnantes qu\’il m\’ait été donné de rencontrer. Comme nous, elles subsistent en se nourrissant de tout ce qu\’elles peuvent trouver. Leur instinct de survie est très développé, ce qui en fait des bêtes extrêmement robustes. Vous voulez les voir ?', 28153),
(160249, 'frFR', 'Ne me mange pas, Milden, on est amis.', '', 28153),
(160248, 'frFR', 'Tu ne dois avaler que les gens méchants !', '', 28153),
(160247, 'frFR', 'Ils ont essayé de lui faire peur, mais Milden s\’est mis en colère !', '', 28153),
(160246, 'frFR', 'Il a avalé m\’sieur Anderson !', '', 28153),
(160245, 'frFR', 'Dépêchez-vous, là-dedans !', 'Dépêchez-vous, là-dedans !', 28153),
(160244, 'frFR', 'Rassemblez ce dont j\’ai besoin au plus vite. Une vie est en jeu.', '', 28153),
(160242, 'frFR', 'Mais nous sommes loin d\’avoir éradiqué toute trace de corruption.', '', 28153),
(160241, 'frFR', 'Accompagné de mes frères et sœurs les plus dévoués, j\’ai lutté contre vents et marées… Littéralement.', '', 28153),
(160240, 'frFR', 'Même si le seigneur Chantorage n\’est plus, les ténèbres qui l\’ont emporté demeurent présentes.', '', 28153),
(160239, 'frFR', 'Poser un simple pied sur cette île revient à signer son propre arrêt de mort.', '', 28153),
(160238, 'frFR', 'Nous, les eaugures, sommes les seuls à pouvoir nous en approcher sans danger, mais jamais nous ne foulons son sol.', '', 28153),
(160237, 'frFR', 'Je n\’ai encore jamais eu à assumer la lourde tâche de conduire quelqu\’un jusqu\’à Funesterre.', '', 28153),
(160236, 'frFR', 'Désolé, mon enfant… Je ne peux pas vous laisser passer. Prenez ce que vous veniez chercher et partez.', '', 28153),
(160235, 'frFR', 'Si dame Jaina a été envoyée sur ces rivages maudits, le temps nous est compté. Suivez-moi.', '', 28153),
(160234, 'frFR', 'Elle a condamné sa fille à l\’exil ? À Funesterre ! Par les abysses !', '', 28153),
(160233, 'frFR', 'Dame Katherine est revenue sur l\’ordre d\’exécution de sa fille. Nous savons que Jaina a été emmenée à Funesterre et je cherche un moyen de m\’y rendre.', 'Dame Katherine est revenue sur l\’ordre d\’exécution de sa fille. Nous savons que Jaina a été emmenée à Funesterre et je cherche un moyen de m\’y rendre.', 28153),
(160232, 'frFR', 'Le temps nous est compté. Nous devons agir sans tarder pour avoir une chance de sauver Jaina.', '', 28153),
(160230, 'frFR', 'Votre tête irait à ravir sur ma prochaine création !', '', 28153),
(160229, 'frFR', 'C\’est l\’une de mes plus belles œuvres. Tous les éléments y sont en harmonie.', '', 28153),
(160228, 'frFR', 'Ah, $n. Ravi de vous revoir. Quel bon vent vous amène à Chantorage ?', '', 28153),
(160227, 'frFR', 'Dame Katherine voudra certainement entendre ce que vous avez découvert.', '', 28153),
(160226, 'frFR', '', 'Il vient d\’un temps immémorial… et il est bien plus terrifiant que vous ne l\’imaginez…', 28153),
(160225, 'frFR', '', 'Unissons-nous. Pour l\’éternité.', 28153),
(160224, 'frFR', '', 'Salut, trésor. Voulez-vous que je chante pour vous ?', 28153),
(160223, 'frFR', 'La confiance… causera votre perte… comme elle a causé la nôtre.', '', 28153),
(160222, 'frFR', 'Vous n\’aurez pas ces reliques !', '', 28153),
(160221, 'frFR', 'Les livraisons ne doivent pas être retardées !', '', 28153),
(160220, 'frFR', 'Qu\’est-ce que vous lui voulez, à ce taré de Gnome ? Son étal est un vrai capharnaüm.\n\nEnfin, puisque vous insistez, c\’est à Crenzo Brisétincelle qu\’il faut vous adresser. Vous le trouverez au niveau supérieur du marché des Alizés, côté est. Il passe son temps à bricoler, perché au sommet de son tas d\’immondices. Bonne chance.', 'Qu\’est-ce que vous lui voulez, à ce taré de Gnome ? Son étal est un vrai capharnaüm.\n\nEnfin, puisque vous insistez, c\’est à Crenzo Brisétincelle qu\’il faut vous adresser. Vous le trouverez au niveau supérieur du marché des Alizés, côté est. Il passe son temps à bricoler, perché au sommet de son tas d\’immondices. Bonne chance.', 28153),
(160219, 'frFR', 'Laissez-moi vous dire que le réseau de bacs de la ville est l\’une des plus belles merveilles au monde. Non seulement il peut vous emmener en balade sur les nombreux canaux de Boralus elle-même, mais les bateliers desservent également la périphérie et le reste de la rade de Tiragarde.\n\nSi vous avez envie de faire une petite croisière, ne cherchez pas plus loin et adressez-vous à Will Melborne. Vous le trouverez avec sa fille Sally du côté sud du marché des Alizés, près de l\’eau.', 'Laissez-moi vous dire que le réseau de bacs de la ville est l\’une des plus belles merveilles au monde. Non seulement il peut vous emmener en balade sur les nombreux canaux de Boralus elle-même, mais les bateliers desservent également la périphérie et le reste de la rade de Tiragarde.\n\nSi vous avez envie de faire une petite croisière, ne cherchez pas plus loin et adressez-vous à Will Melborne. Vous le trouverez avec sa fille Sally du côté sud du marché des Alizés, près de l\’eau.', 28153),
(160218, 'frFR', 'Batelier', 'Batelier', 28153),
(160217, 'frFR', 'Ce ne sont pas les attractions qui manquent, à Boralus. Que recherchez-vous ?', 'Ce ne sont pas les attractions qui manquent, à Boralus. Que recherchez-vous ?', 28153),
(160216, 'frFR', 'Si vous cherchez un endroit où vous reposer, puis-je vous suggérer l\’auberge du Nid douillet ? Vous la trouverez au niveau supérieur, au-dessus de la fontaine.\n\nAdressez-vous à Wesley Rocheporte. Il vous dénichera une chambre confortable. Avec un vrai matelas, pas une vulgaire paillasse. Et s\’il a préparé son célèbre ragoût, vous pouvez y aller les yeux fermés.', 'Si vous cherchez un endroit où vous reposer, puis-je vous suggérer l\’auberge du Nid douillet ? Vous la trouverez au niveau supérieur, au-dessus de la fontaine.\n\nAdressez-vous à Wesley Rocheporte. Il vous dénichera une chambre confortable. Avec un vrai matelas, pas une vulgaire paillasse. Et s\’il a préparé son célèbre ragoût, vous pouvez y aller les yeux fermés.', 28153),
(160215, 'frFR', 'Wgullll naq xizzuoog', '', 28153),
(160214, 'frFR', 'Wgul naq zzigla ouug anagih', '', 28153),
(160213, 'frFR', 'Pas la peine de me le dire deux fois !', '', 28153),
(160212, 'frFR', 'Vous avez envie de voir du pays ? Je comprends. Rien ne vaut l\’ivresse qu\’on ressent lorsqu\’on s\’envole vers des contrées lointaines et exotiques. L\’exaltation des dangers inconnus qui vous attendent à destination. La promesse de fabuleux trésors arrachés de haute lutte à de redoutables adversaires.\n\nNon ? Euh… vous avez juste besoin d\’un vol ? Il fallait le dire tout de suite ! Rendez-vous au niveau supérieur du marché des Alizés, côté ouest. Vous y trouverez Joan Weber, près du perchoir des griffons.', 'Vous avez envie de voir du pays ? Je comprends. Rien ne vaut l\’ivresse qu\’on ressent lorsqu\’on s\’envole vers des contrées lointaines et exotiques. L\’exaltation des dangers inconnus qui vous attendent à destination. La promesse de fabuleux trésors arrachés de haute lutte à de redoutables adversaires.\n\nNon ? Euh… vous avez juste besoin d\’un vol ? Il fallait le dire tout de suite ! Rendez-vous au niveau supérieur du marché des Alizés, côté ouest. Vous y trouverez Joan Weber, près du perchoir des griffons.', 28153),
(160211, 'frFR', '', 'Circulez.', 28153),
(160210, 'frFR', '', 'Quant à vous, porte-parole de la Horde, je m\’occuperai de votre cas en temps voulu.', 28153),
(160209, 'frFR', '', 'Vous là, le nabot verdâtre, dehors ! Vous n\’êtes plus le bienvenu au kraal des Bêtes de guerre.', 28153),
(160208, 'frFR', '', 'Bien. Ce vaudou contre nature est neutralisé.', 28153),
(160207, 'frFR', '', 'Ça ne faisait pas partie des clauses de mon… contrat…', 28153),
(160206, 'frFR', '', 'Vous êtes sur la propriété privée de la compagnie Corsandre !', 28153),
(160205, 'frFR', 'Le navrecorne juvénile grogne avant de s\’effondrer.', '', 28153),
(160204, 'frFR', 'Le navrecorne juvénile a un mouvement de recul en goûtant.', '', 28153),
(160203, 'frFR', '', 'Il nous faut une embarcation pour atteindre le prochain navire.', 28153),
(160202, 'frFR', 'Ne me demandez pas comment, je le sais, c\’est tout. Si vous voulez vous faire bien voir de ces mystérieuses tortues, vous devez vous adresser à leur émissaire, le collectionneur Kojo.\n\nLe problème, c\’est qu\’il n\’est pas tout près. Vous le trouverez dans la vallée Chantorage, au panorama des Chercheurs. Il va falloir vous débrouiller sans aide pour y aller. Mais à vous regarder, je parie que vous avez déjà tout prévu.', 'Ne me demandez pas comment, je le sais, c\’est tout. Si vous voulez vous faire bien voir de ces mystérieuses tortues, vous devez vous adresser à leur émissaire, le collectionneur Kojo.\n\nLe problème, c\’est qu\’il n\’est pas tout près. Vous le trouverez dans la vallée Chantorage, au panorama des Chercheurs. Il va falloir vous débrouiller sans aide pour y aller. Mais à vous regarder, je parie que vous avez déjà tout prévu.', 28153),
(160201, 'frFR', 'Sortez les marteaux !', '', 28153),
(160200, 'frFR', 'Les marteaux sont imbattables et les griffons imparables !', '', 28153),
(160199, 'frFR', '', 'Maintenant ! Bombardez-les !', 28153),
(160198, 'frFR', 'On cherche à se faire bien voir de l\’amirauté ? Pas bête.\n\nOuais, je sais où elle est. C\’est l\’approvisionneuse Fray que vous cherchez. Vous la trouverez dans le bureau du maître du port, avec tous les gros bonnets.', 'On cherche à se faire bien voir de l\’amirauté ? Pas bête.\n\nOuais, je sais où elle est. C\’est l\’approvisionneuse Fray que vous cherchez. Vous la trouverez dans le bureau du maître du port, avec tous les gros bonnets.', 28153),
(160197, 'frFR', 'Émissaire de l\’Amirauté des Portvaillant', 'Émissaire de l\’Amirauté des Portvaillant', 28153),
(160196, 'frFR', 'Des émissaires, hein ? Lequel cherchez-vous, au juste ?', 'Des émissaires, hein ? Lequel cherchez-vous, au juste ?', 28153),
(160195, 'frFR', 'La banque ? Je vois. Vous la trouverez dans le secteur nord-ouest de la ville, au marché des Alizés. Elle est installée au niveau inférieur, côté est.\n\nD\’ailleurs, il faut que j\’aille consulter mon compte après le service. Ils font pas de découvert autorisé.', 'La banque ? Je vois. Vous la trouverez dans le secteur nord-ouest de la ville, au marché des Alizés. Elle est installée au niveau inférieur, côté est.\n\nD\’ailleurs, il faut que j\’aille consulter mon compte après le service. Ils font pas de découvert autorisé.', 28153),
(160194, 'frFR', 'Oh, salut, $c. Ça gaze ?', '', 28153),
(160193, 'frFR', 'Allons-y !', 'Allons-y !', 28153),
(160192, 'frFR', 'Parfait. Voyons voir…\n\n<Hobart feuillette un manuel détrempé.>\n\nBah, on va faire l\’impasse sur les règles de sécurité trois à sept. Rien de passionnant. On y va ?', '', 28153),
(160191, 'frFR', 'Ne pas laisser la lampe allumée trop longtemps. Compris.', 'Ne pas laisser la lampe allumée trop longtemps. Compris.', 28153),
(160190, 'frFR', 'Bien. Règle numéro deux : NE GARDEZ PAS VOTRE LAMPE ALLUMÉE.\n\nJe ne plaisante pas. Si vous la laissez allumée plus de euh… disons vingt secondes, les requins viendront vous becqueter. Si vous en voyez un, vous l\’éteignez fissa. Compris ?', '', 28153),
(160189, 'frFR', 'Ne jamais enlever le casque. Compris.', 'Ne jamais enlever le casque. Compris.', 28153),
(160188, 'frFR', 'Parfait ! Règle numéro un : on n\’enlève jamais son casque.\n\nVos histoires de respiration aquatique magique et tout le barnum, je ne veux pas en entendre parler. Il y a assez de pression là en bas pour vous broyer le crâne, $R. En plus, on utilisera une oreillette pour communiquer pendant la mission. Pigé ?', '', 28153),
(160187, 'frFR', 'Oui, je suis tout ouïe.', 'Oui, je suis tout ouïe.', 28153),
(160186, 'frFR', 'Ha ha ! C\’est parti pour une petite séance de plongée !\n\nVous tombez à pic, je viens juste de colmater les trous du tuyau d\’air.\n\nAvant d\’y aller, voici quelques règles de sécurité. Vous m\’écoutez ?', '', 28153),
(160185, 'frFR', '', 'À votre place, je la bouclerais.', 28153),
(160184, 'frFR', 'On peut peut-être trouver un terrain d\’entente ? C\’est vrai, ces effets secondaires ne sont pas si terrib…', '', 28153),
(160183, 'frFR', 'Oh… c\’est VOUS. Ma foi, rien ne pourrait me faire plus plaisir !', '', 28153),
(160182, 'frFR', '', 'Comment ces monstres ont-ils pu faire une chose pareille ?', 28153),
(160181, 'frFR', 'Holà ! On se calme. Ça vous embêterait de remballer votre quincaillerie, là ?', '', 28153),
(160180, 'frFR', '', 'Nous devons trouver un moyen de survivre.', 28153),
(160179, 'frFR', '', 'Expliquez-vous !', 28153),
(160178, 'frFR', '', 'Je vous attendrai dans les ombres, $n. N\’hésitez pas à m\’appeler en cas de besoin.', 28153),
(160177, 'frFR', '', 'Un conseil : évitez les puits d\’énergie magique. Vous risquez non seulement de développer une accoutumance, mais surtout de vous muer en une pâle imitation d\’Elfe.', 28153),
(160176, 'frFR', '', 'Non, avoir les yeux bandés ne me tente pas du tout. Enfin… tout dépend du contexte.', 28153),
(160175, 'frFR', '', 'Je vous aime bien, vous savez… Vous n\’auriez pas un frère jumeau, par hasard ?', 28153),
(160174, 'frFR', '', 'Essayez de m\’arrêter et vous mourrez… ou restez ici, genou en terre, et vous survivrez.', 28153),
(160173, 'frFR', '', 'Le roi Anduin m\’a confié une pierre de foyer permettant de regagner Hurlevent. J\’y soignerai les blessures de mon bien aimé… et ferai tout pour soulager les miens.', 28153),
(160172, 'frFR', 'Allons-nous-en d\’ici.', 'Allons-nous-en d\’ici.', 28153),
(160171, 'frFR', 'La garde d\’honneur va remettre de l\’ordre dans tout ce bazar. C\’est bon pour vous ?', '', 28153),
(160170, 'frFR', '', 'Soyez sur vos gardes.', 28153),
(160169, 'frFR', '', 'Vous !', 28153),
(160168, 'frFR', '', 'Attention !', 28153),
(160167, 'frFR', '|cFF0000FF(Quête)|r Conduisez-nous au navire naufragé du maréchal Valentine, au milieu de la Grande mer.', '|cFF0000FF(Quête)|r Conduisez-nous au navire naufragé du maréchal Valentine, au milieu de la Grande mer.', 28153),
(160166, 'frFR', '', 'Par là.', 28153),
(160165, 'frFR', 'Salutations. Que puis-je faire pour vous aujourd\’hui ?', 'Salutations. Que puis-je faire pour vous aujourd\’hui ?', 28153),
(160164, 'frFR', '', 'Par ici !', 28153),
(160163, 'frFR', '', 'Par sa lumière, la vérité est toujours dévoilée.', 28153),
(160162, 'frFR', 'L\’azérite… n\’est pas… ce que Zul avait promis…', '', 28153),
(160161, 'frFR', 'Vos efforts sont vains ! La puissance de l\’azérite coule dans mes veines !', '', 28153),
(160160, 'frFR', 'En retrait ! On les rattrapera de l\’autre côté !', 'En retrait ! On les rattrapera de l\’autre côté !', 28153),
(160159, 'frFR', 'On est là, $p !', '', 28153),
(160158, 'frFR', 'J\’aimerais faire affaire avec vous.', 'J\’aimerais faire affaire avec vous.', 28153),
(160157, 'frFR', 'Retournons au portail.', '', 28153),
(160156, 'frFR', '', 'C\’est un honneur de servir Élune.', 28153),
(160155, 'frFR', '', 'Je parle au nom de mon peuple.', 28153),
(160154, 'frFR', '', 'Notre fureur s\’abattra sur nos ennemis.', 28153),
(160153, 'frFR', 'Tu as le cœur de ta mère.', '', 28153),
(160152, 'frFR', 'Je crois que personne ne devrait perdre son foyer. Pas si ça rend les gens tristes.', '', 28153),
(160151, 'frFR', 'Maman en parlait parfois… Je crois que ça la faisait pleurer.', '', 28153),
(160150, 'frFR', '', 'Les Kaldorei survivront.', 28153),
(160149, 'frFR', 'Nous… Nous n\’étions pas nous-mêmes. C\’est difficile à expliquer, mon garçon.', '', 28153),
(160148, 'frFR', 'Ça a dû rendre tout le monde très triste…', '', 28153),
(160147, 'frFR', 'C\’était il y a très longtemps.', '', 28153),
(160146, 'frFR', 'Tu m\’as dit qu\’un jour, les Orcs avaient perdu leur foyer.', '', 28153),
(160145, 'frFR', '', 'Il y a un temps pour patienter… et un autre pour agir.', 28153),
(160144, 'frFR', 'Pourquoi ?', '', 28153),
(160143, 'frFR', 'Je suis triste que les Elfes aient perdu leur arbre.', '', 28153),
(160142, 'frFR', 'Et votre faveur sera rendue aux forces des abysses !', '', 28153),
(160141, 'frFR', 'Donnez-moi le pouvoir d\’abattre nos némésis…', '', 28153),
(160140, 'frFR', 'Et gare à nous si nous abusons de votre bienveillance.', '', 28153),
(160139, 'frFR', '', 'Nous nous battrons pour notre avenir.', 28153),
(160138, 'frFR', 'Mais pour l\’heure, accordez-nous votre puissance…', '', 28153),
(160137, 'frFR', '', 'Entendez la voix d\’Élune.', 28153),
(160136, 'frFR', 'Nous verrons, mon garçon. Nous verrons.', '', 28153),
(160135, 'frFR', 'Et cette guerre, est-ce qu\’elle va changer la Horde ?', '', 28153),
(160134, 'frFR', 'Les océans survivront à notre humanité fuyante.', '', 28153),
(160133, 'frFR', 'Les guerres restent les mêmes, seuls les guerriers changent.', '', 28153),
(160132, 'frFR', 'Est-ce que c\’est une mauvaise guerre ? Je veux dire… pire que les autres ?', '', 28153),
(160131, 'frFR', 'Ô marées déferlantes, ô marées captivantes…', '', 28153),
(160130, 'frFR', 'Qu\’y a-t-il, mon garçon ?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160129, 'frFR', 'Papa ?', '', 28153),
(160128, 'frFR', '', 'Le mont Mugamba est un endroit sauvage et impitoyable gardé par une tribu de gorilles géants et bordé de falaises escarpées. Il y a peu de chances que la Horde vienne nous chercher jusqu\’ici.', 28153),
(160127, 'frFR', '', 'Quand vous souhaiterez retourner en Sombrivage comme il apparaît dans le présent, il suffira de demander.', 28153),
(160126, 'frFR', 'Je ne l\’oublierai pas, papa.', '', 28153),
(160125, 'frFR', 'N\’oublie jamais ça, mon garçon.', '', 28153),
(160124, 'frFR', 'La guerre est une épreuve d\’honneur. S\’il est perdu, le récupérer n\’est pas facile.', '', 28153),
(160123, 'frFR', 'Les guerres révèlent ce qu\’il y a de pire en chacun.', '', 28153),
(160122, 'frFR', 'J\’ai entendu les autres enfants parler de la guerre. Est-ce que… Est-ce que la Horde a fait quelque chose de mal ?', '', 28153),
(160121, 'frFR', 'Tu es bien plus calme qu\’à ton habitude.', '', 28153),
(160120, 'frFR', 'Oui, papa ?', '', 28153),
(160119, 'frFR', 'Mon garçon.', '', 28153),
(160118, 'frFR', 'Ces terres hébergent des myriades de créatures aussi merveilleuses que passionnantes. À l\’instar des défenseurs de notre temple qui s\’efforcent d\’être loyaux et compétents au combat, je tâche d\’entraîner mes familiers à devenir aussi forts que possible. Les vôtres sont-ils de taille à affronter les miens ?', '', 28153),
(160117, 'frFR', 'Pouvez-vous me montrer le monde tel qu\’il était avant l\’incendie de Teldrassil ?', 'Pouvez-vous me montrer le monde tel qu\’il était avant l\’incendie de Teldrassil ?', 28153),
(160116, 'frFR', 'Attends, une seconde… C\’est moi le lourd fardeau ? Je te rappelle que je transportais un coffre de la plus haute importance !', '', 28153),
(160115, 'frFR', 'C\’est fait. Prenez le sceptre et fichons le camp d\’ici !', '', 28153),
(160114, 'frFR', 'Écartez-vous de là !', '', 28153),
(160113, 'frFR', '', 'Tu aurais pu te débarrasser de l\’horrible pelure mitée qui te sert de manteau, Flynn.', 28153),
(160112, 'frFR', 'Blasphème !', '', 28153),
(160111, 'frFR', 'D\’accord, d\’accord. Apportons du poisson à l\’héroïne du jour et laissons-lui le temps de souffler.', '', 28153),
(160110, 'frFR', '', 'Je préfère ne pas trop lui en demander. Elle a déjà eu à porter un lourd fardeau, aujourd\’hui.', 28153),
(160109, 'frFR', '', 'Trombecœur doit se reposer un peu avant que nous regagnions la ville.', 28153),
(160108, 'frFR', 'Pousse-toi un peu, Taelia. J\’aimerais bien voyager À DOS de griffon pour une fois !', '', 28153),
(160107, 'frFR', 'Parfait. Pendant que notre $Uami:amie; se rendra à Tol Dagor, nous emporterons ce coffre à Boralus.', '', 28153),
(160106, 'frFR', 'Ce monde est pas digne d\’une âme aussi charitable que la vôtre, $n. Bref, où j\’en étais, déjà ? Ah, oui. Notre fugue avortée.', '', 28153),
(160105, 'frFR', 'Bien mieux. Pour en revenir à mon histoire…', '', 28153),
(160104, 'frFR', 'Ah, ça va mieux.', '', 28153),
(160103, 'frFR', 'Nooon ! Pas… encore…', '', 28153),
(160102, 'frFR', 'La vie, elle me revient, je le sens ! Mes pouvoirs, ils s\’en trouvent grandis !', '', 28153),
(160101, 'frFR', 'Malheureusement, le navire est actuellement en réparation. Ses inébranlables états de service en ont pris un sérieux coup dans l\’aile. Toutefois, je suis ici pour vous offrir un autre moyen de rallier votre destination.\n\nUn simple portail ne vous prodiguera sans doute pas l\’exaltation de fendre les flots cheveux au vent, mais vous pourrez poursuivre votre quête sans encombre.\n\nN\’hésitez pas à utiliser ce portail à chaque fois que vous en aurez besoin. Je suis à votre service.', 'Malheureusement, le navire est actuellement en réparation. Ses inébranlables états de service en ont pris un sérieux coup dans l\’aile. Toutefois, je suis ici pour vous offrir un autre moyen de rallier votre destination.\n\nUn simple portail ne vous prodiguera sans doute pas l\’exaltation de fendre les flots cheveux au vent, mais vous pourrez poursuivre votre quête sans encombre.\n\nN\’hésitez pas à utiliser ce portail à chaque fois que vous en aurez besoin. Je suis à votre service.', 28153),
(160100, 'frFR', 'Pouah !', 'Pouah !', 28153),
(160099, 'frFR', 'Celui qu\’a fait ça, je vais l\’étriper !', 'Celui qu\’a fait ça, je vais l\’étriper !', 28153),
(160098, 'frFR', 'Ah non, pas encore !', 'Ah non, pas encore !', 28153),
(160097, 'frFR', 'Qui c\’est qu\’a fait ça ?!', 'Qui c\’est qu\’a fait ça ?!', 28153),
(160096, 'frFR', '', 'Port-du-Pont est droit devant ! On va se poser là-bas.', 28153),
(160095, 'frFR', 'Les Ulterres se réveillent !', '', 28153),
(160094, 'frFR', 'Vous savez que vous ne pouvez me vaincre, Ulfar. Mais si c\’est un combat que vous cherchez, vous l\’aurez !', '', 28153),
(160093, 'frFR', 'Ma… puissance…', 'Ma… puissance…', 28153),
(160092, 'frFR', 'Cette puissance… Elle est bien supérieure à tout ce que j\’ai connu ! Il m\’en faut plus !', 'Cette puissance… Elle est bien supérieure à tout ce que j\’ai connu ! Il m\’en faut plus !', 28153),
(160091, 'frFR', 'C\’est ici que vous trouverez le bateau qui relie le port de Zandalar aux îles de l\’Écho.\n\nC\’est là que vous allez ?', '', 28153),
(160090, 'frFR', '', 'Cela devrait faire l\’affaire. Quittons ce navire et allons voir ces petites merveilles à l\’œuvre !', 28153),
(160089, 'frFR', 'Occupez-vous de cet importun, $n.', '', 28153),
(160088, 'frFR', 'Vous avez craché à la face de mon Loa, je vais vous arracher la langue !', 'Vous avez craché à la face de mon Loa, je vais vous arracher la langue !', 28153),
(160087, 'frFR', 'Je vais vous apprendre à insulter mon Loa !', 'Je vais vous apprendre à insulter mon Loa !', 28153),
(160086, 'frFR', 'Vous allez me le payer cher !', 'Vous allez me le payer cher !', 28153),
(160085, 'frFR', 'À quoi ça rime, cette histoire ?', 'À quoi ça rime, cette histoire ?', 28153),
(160084, 'frFR', 'À quoi vous jouez, par tous les Loas ?', 'À quoi vous jouez, par tous les Loas ?', 28153),
(160083, 'frFR', 'Ça suffit !', 'Ça suffit !', 28153),
(160082, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(160081, 'frFR', 'Tiens donc, nous avons de la visite. Allons l\’accueillir ensemble, voulez-vous ?', '', 28153),
(160080, 'frFR', 'Katherine est prête à tout pour récupérer le corps de son fils.\n\nNous allons utiliser ses émotions à notre avantage pour supplanter sa flotte.', '', 28153),
(160079, 'frFR', 'Encore un plan hasardeux de l\’Alliance contrecarré. Les félicitations me semblent malgré tout de rigueur.', '', 28153),
(160078, 'frFR', 'L\’Alliance a assemblé sa propre machine de guerre alimentée par l\’azérite. Bien qu\’elle soit sans doute moitié moins puissante que la nôtre, nous devons la détruire… sur-le-champ !', '', 28153),
(160077, 'frFR', '« Héraut du malheur », un nom bien trouvé. Ha !', '', 28153),
(160076, 'frFR', 'Les troupes de la Horde ont mis sur pied une nouvelle machine de guerre alimentée par l\’azérite. Détruisez-la, avant qu\’elles l\’utilisent contre Stromgarde !', '', 28153),
(160075, 'frFR', '', 'Combattons le feu par le feu. Allons fouiller un de leurs navires, et emparons-nous de ces bombes d\’azérite.', 28153),
(160074, 'frFR', '', 'Justice sera rendue. Je veillerai à ce que tous paient, les pirates comme la compagnie Corsandre.', 28153),
(160073, 'frFR', '', 'Tiens bon, Flynn. Je… je t\’interdis de mourir.', 28153),
(160072, 'frFR', 'Notre position surplombe la route de l\’Or, et nous offre ainsi un excellent point d\’observation duquel surveiller le trafic ennemi vers et depuis la capitale zandalari.', '', 28153),
(160071, 'frFR', 'Appâter', 'Appâter', 28153),
(160070, 'frFR', 'Vous l\’aurez voulu, vile charogne. Je vous passerai sur le corps s\’il le faut.', '', 28153),
(160069, 'frFR', 'Mais pour être franc, vous pouvez garder Valentine. Nous n\’avons que faire de lui.', '', 28153),
(160068, 'frFR', 'Ah, mon brave, c\’est une tactique qui aurait sans doute fonctionné avec un autre que moi…', '', 28153),
(160067, 'frFR', 'Rendez-nous le corps de Derek Portvaillant et nous vous remettrons celui de votre homme.', '', 28153),
(160066, 'frFR', 'Inverser', 'Inverser', 28153),
(160065, 'frFR', 'Quand j\’ai entendu les Trolls parler d\’ombres, j\’ai cru qu\’il s\’agissait de véritables ombres. Qui aurait pu imaginer qu\’ils étaient si doués pour les métaphores ?', 'Quand j\’ai entendu les Trolls parler d\’ombres, j\’ai cru qu\’il s\’agissait de véritables ombres. Qui aurait pu imaginer qu\’ils étaient si doués pour les métaphores ?', 28153),
(160064, 'frFR', 'Vous savez ce qu\’il faudrait à cet endroit ? Une bonne dose de vase verte.', 'Vous savez ce qu\’il faudrait à cet endroit ? Une bonne dose de vase verte.', 28153),
(160063, 'frFR', 'C\’est intolérable ! L\’eau de cette région est bien trop bleue à mon goût.', 'C\’est intolérable ! L\’eau de cette région est bien trop bleue à mon goût.', 28153),
(160062, 'frFR', 'Maintenant que vous le dites, j\’aurais bien besoin de changer de style, moi aussi. La personne qu\’il vous faut, c\’est le tisse-dimensions Hayri, près des quais.\n\nPour vous y rendre, descendez dans le Grand bazar, sur la terrasse qui surplombe le port. Il tient une boutique nommée le Maelström marchand, côté est.', 'Maintenant que vous le dites, j\’aurais bien besoin de changer de style, moi aussi. La personne qu\’il vous faut, c\’est le tisse-dimensions Hayri, près des quais.\n\nPour vous y rendre, descendez dans le Grand bazar, sur la terrasse qui surplombe le port. Il tient une boutique nommée le Maelström marchand, côté est.', 28153),
(160061, 'frFR', 'Je suis sûr que nous pouvons récupérer quelques membres sur le champ de bataille sans que personne ne s\’en rende compte.', 'Je suis sûre que nous pouvons récupérer quelques membres sur le champ de bataille sans que personne ne s\’en rende compte.', 28153),
(160060, 'frFR', 'Voulez changer de style, c\’est ça ? Il y a un tisse-dimensions éthérien près des quais. Hayri, qu\’il s\’appelle.\n\nPour le trouver, il faut d\’abord aller au Grand bazar, sur la terrasse qui surplombe le port. Ensuite, rendez-vous au Maelström marchand, côté est.', 'Voulez changer de style, c\’est ça ? Il y a un tisse-dimensions éthérien près des quais. Hayri, qu\’il s\’appelle.\n\nPour le trouver, il faut d\’abord aller au Grand bazar, sur la terrasse qui surplombe le port. Ensuite, rendez-vous au Maelström marchand, côté est.', 28153),
(160059, 'frFR', 'Ce n\’est pas l\’Apothicarium, mais il faudra faire avec.', 'Ce n\’est pas l\’Apothicarium, mais il faudra faire avec.', 28153),
(160058, 'frFR', 'Vous, là ! Vous semblez vous y connaître en combats de mascottes. Alors, j\’vais pas tourner autour du pot. Ça vous dit, un petit combat ?', '', 28153),
(160057, 'frFR', 'Cette ville est bien trop exposée à mon goût. J\’ai besoin d\’endroits sombres comme celui-ci pour terminer mon travail.', 'Cette ville est bien trop exposée à mon goût. J\’ai besoin d\’endroits sombres comme celui-ci pour terminer mon travail.', 28153),
(160056, 'frFR', 'Excellent ! Je sens qu\’Azeroth reprend déjà des forces.', '', 28153),
(160055, 'frFR', 'Transmogrifieur', 'Transmogrifieur', 28153),
(160054, 'frFR', 'Je perçois de l\’azérite à proximité. Quelque chose semble en drainer une terrible puissance. Vous devez l\’arrêter !', '', 28153),
(160053, 'frFR', 'Il m\’a fallu plusieurs jours pour comprendre ce qui s\’était passé…\n\nKaiani, elle était morte. Son père l\’avait tuée et on me faisait porter le chapeau.\n\n<Zenbaro tousse violemment.>\n\nJe crois bien que j\’en ai plus pour très longtemps.\n\nÇa vous embêterait d\’apporter une dernière gorgée d\’eau de source à un mourant ?', '', 28153),
(160052, 'frFR', 'Au bout d\’un an, j\’avais amassé assez d\’argent pour qu\’on puisse s\’enfuir, Kaiani et moi.\n\nOn avait prévu de partir le soir même. Je lui ai donné rendez-vous près de l\’Ancienne route marchande, à la nuit tombée.\n\nDès que le soleil, il s\’est couché derrière les montagnes, j\’ai foncé tête baissée vers ma nouvelle vie.\n\nQuand j\’ai atteint la route, y avait des gardes armés qui m\’attendaient.\n\nIls m\’ont embarqué sans décrocher un mot.', '', 28153),
(160051, 'frFR', 'Quelle honte… faire passer sa propre cupidité avant la santé d\’Azeroth. Merci !', '', 28153),
(160050, 'frFR', 'Elle et moi, on s\’est rapprochés pendant que je travaillais pour son père.\n\nElle m\’a supplié de quitter ma bande et la ville avec, mais j\’étais coincé.\n\nJ\’avais pas un sou en poche et tout ce que je volais, je le donnais à Rajin. Jusqu\’au jour où j\’ai mis au point ma petite combine…\n\nÀ partir de là, chaque fois que je fauchais deux pièces, j\’en mettais une à gauche.\n\n<Zenbaro tousse violemment.>\n\nIl me faut de l\’eau, $n. S\’il vous plaît…', '', 28153),
(160049, 'frFR', 'J\’avais gagné la confiance et le respect de Rajin. Autant que faire se peut.\n\nBref, le rêve pour une petite canaille, mais moi, j\’avais d\’autres projets en tête…\n\nRajin, il avait une fille, Kaiani. Honnête, gentille, belle… Son exacte opposée, en gros.', '', 28153),
(160048, 'frFR', 'Le patron, il a pas tardé à remarquer mes talents.\n\nEn peu de temps, je suis devenu le messager personnel du grand Rajin.\n\nSi quelqu\’un avait besoin de se faire remonter les bretelles, c\’était à moi de m\’en charger.\n\nSauf que je remontais bien plus que des bretelles.\n\n<Zenbaro tousse.>\n\nJe boirais bien un peu d\’eau, $n.', '', 28153),
(160047, 'frFR', 'Quelqu\’un extrait de l\’azérite dans les plaies ouvertes du monde. Arrêtez ce saccage !', '', 28153),
(160046, 'frFR', 'Dites-m\’en plus.', 'Dites-m\’en plus.', 28153),
(160045, 'frFR', 'Il est malavisé de provoquer un ours.', '', 28153),
(160044, 'frFR', 'La mort fait partie intégrante du cycle de la nature. Peut-être une démonstration s\’impose-t-elle…', '', 28153),
(160043, 'frFR', 'Je vous prierais de cesser. Je suis âgé mais pas sénile.', '', 28153),
(160042, 'frFR', 'Ne faiblissez pas.', '', 28153),
(160041, 'frFR', 'Le pouvoir de la forêt vous accompagne.', '', 28153),
(160040, 'frFR', 'Frappez vite et juste.', '', 28153),
(160039, 'frFR', 'Méfiez-vous des bois.', '', 28153),
(160038, 'frFR', 'Préservez l\’équilibre.', '', 28153),
(160037, 'frFR', 'Salutations.', '', 28153),
(160036, 'frFR', 'Ici, nos racines s\’étendent en tout lieu.', '', 28153),
(160035, 'frFR', 'Nous luttons contre les ténèbres.', '', 28153),
(160034, 'frFR', 'Percevez-vous le battement de la vie ?', '', 28153),
(160033, 'frFR', 'Êtes-vous en quête de savoir ?', '', 28153),
(160032, 'frFR', '', 'Étouffez-vous avec ce chou-fleur !', 28153),
(160031, 'frFR', 'Je ne livre pas ma sagesse aux pusillanimes.', '', 28153),
(160030, 'frFR', 'Qu\’attendez-vous des Parlépines ?', '', 28153),
(160029, 'frFR', 'Comment faire une offre si nous n\’avons pas d\’argent ?', 'Comment faire une offre si nous n\’avons pas d\’argent ?', 28153),
(160028, 'frFR', 'Nous n\’avons pas grand-chose de précieux à vendre.', 'Nous n\’avons pas grand-chose de précieux à vendre.', 28153),
(160027, 'frFR', 'Ça devrait suffire à couvrir les achats de base… enfin, j\’espère.', 'Ça devrait suffire à couvrir les achats de base… enfin, j\’espère.', 28153),
(160026, 'frFR', 'Combien d\’or nous reste-t-il ?', 'Combien d\’or nous reste-t-il ?', 28153),
(160025, 'frFR', 'Nous reste-t-il des objets de valeur à vendre ?', 'Nous reste-t-il des objets de valeur à vendre ?', 28153),
(160024, 'frFR', 'Je ne suis pas sûr que les banquiers gobelins soient plus philanthropes que ces radins de Montague.', 'Je ne suis pas sûre que les banquiers gobelins soient plus philanthropes que ces radins de Montague.', 28153),
(160023, 'frFR', 'Accélère ! Oulà, pas si vite !', '', 28153),
(160022, 'frFR', '', 'Il est tenace, celui-là !', 28153),
(160021, 'frFR', 'Nous sommes partis si précipitamment que j\’ai dû tout abandonner sur place !', 'Nous sommes partis si précipitamment que j\’ai dû tout abandonner sur place !', 28153),
(160020, 'frFR', '', 'Partez d\’ici, $R !', 28153),
(160019, 'frFR', '', 'Ils vous traqueront, $R !', 28153),
(160018, 'frFR', '', 'Vous n\’avez rien à faire dans Hurlevent, $R !', 28153),
(160017, 'frFR', 'Voyons qui Portvaillant nous envoie, cette fois-ci.', '', 28153),
(160016, 'frFR', 'Stop !', 'Stop !', 28153),
(160015, 'frFR', 'Vous pensiez pouvoir nous gruger, c\’est ça ?', 'Vous pensiez pouvoir nous gruger, c\’est ça ?', 28153),
(160014, 'frFR', 'Ha ! Comme je vous y prends, à fouiner dans le coin.', 'Ha ! Comme je vous y prends, à fouiner dans le coin.', 28153),
(160013, 'frFR', 'Dégagez de là, sale vermine de la Horde !', 'Dégagez de là, sale vermine de la Horde !', 28153),
(160012, 'frFR', '', 'BARGES, À MON SIGNAL ! FEU !', 28153),
(160011, 'frFR', 'Puissance restaurée. Poursuite de l\’objectif principal. Extermination !', 'Puissance restaurée. Poursuite de l\’objectif principal. Extermination !', 28153),
(160010, 'frFR', 'Je vais arracher ce marteau aux mains de votre cadavre !', 'Je vais arracher ce marteau aux mains de votre cadavre !', 28153),
(160009, 'frFR', '', 'On en a pour tous les goûts ici !', 28153),
(160008, 'frFR', '', 'Vous avez l\’air d\’$gun:une:r; $R en carence de vitamines !', 28153),
(160007, 'frFR', '', 'Vous, vous avez une tête à avoir besoin d\’un navet bien mûr !', 28153),
(160006, 'frFR', '', 'On ne manque pas d\’offres spéciales ici !', 28153),
(160005, 'frFR', 'Dégagez de là !', '', 28153),
(160004, 'frFR', 'Halte !', '', 28153),
(160003, 'frFR', 'Que faites-vous ici ?', '', 28153),
(160002, 'frFR', 'Halte-là !', '', 28153),
(160001, 'frFR', 'Montrez-vous, vermines de la Horde ! Nous avons un ami à vous.', '', 28153),
(160000, 'frFR', 'Je file dès que la route est libre. On se retrouve à la maison de ma grand-mère, bonne chance !', '', 28153),
(159999, 'frFR', 'Et maintenant, chef de guerre, où allons-nous ?', 'Et maintenant, chef de guerre, où allons-nous ?', 28153),
(159998, 'frFR', 'C\’est vraiment du gâteau de préparer une jolie tarte !', '', 28153),
(159997, 'frFR', 'La majeure partie de nos troupes fait appel à un Sombrelance, le contremaître Al\’jibo. Vous le trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.', 'La majeure partie de nos troupes fait appel à un Sombrelance, le contremaître Al\’jibo. Vous le trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.', 28153),
(159996, 'frFR', 'Vous avez de l\’argent mal acquis à refourguer, c\’est ça ? Je comprends. À quoi bon partir en campagne si on se remplit pas les poches au passage, pas vrai ? À moins que vous ayez juste quelque chose à réparer ?\n\nDites-moi, quel genre de marchand cherchez-vous ?', 'Vous avez de l\’argent mal acquis à refourguer, c\’est ça ? Je comprends. À quoi bon partir en campagne si on se remplit pas les poches au passage, pas vrai ? À moins que vous ayez juste quelque chose à réparer ?\n\nDites-moi, quel genre de marchand cherchez-vous ?', 28153),
(159995, 'frFR', 'Pin\’jin le Patient, voilà l\’homme qu\’il vous faut pour approfondir vos connaissances en matière de couture. Un véritable maître ès broderies et, en plus, il fait les sutures comme personne. C\’est lui qui m\’a recousu le bras, l\’autre jour.\n\nSes talents attirent tous les nobliaux endimanchés à des lieues à la ronde sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 'Pin\’jin le Patient, voilà l\’homme qu\’il vous faut pour approfondir vos connaissances en matière de couture. Un véritable maître ès broderies et, en plus, il fait les sutures comme personne. C\’est lui qui m\’a recousu le bras, l\’autre jour.\n\nSes talents attirent tous les nobliaux endimanchés à des lieues à la ronde sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 28153),
(159994, 'frFR', 'Hésitez pas à l\’essayer, vous serez pas $Udéçu:déçue; !', '', 28153),
(159993, 'frFR', 'Tout le monde le sait, mais… Rana la Coupeuse est une des meilleures dépeceuses au monde. Il suffit de regarder les créatures qui rôdent dans le coin.\n\nVous la trouverez sur la terrasse de l\’Artisanat, au pied de la pyramide de Dazar\’alor, côté ouest.', 'Tout le monde le sait, mais… Rana la Coupeuse est une des meilleures dépeceuses au monde. Il suffit de regarder les créatures qui rôdent dans le coin.\n\nVous la trouverez sur la terrasse de l\’Artisanat, au pied de la pyramide de Dazar\’alor, côté ouest.', 28153),
(159992, 'frFR', 'Le minage ? Je vous vois venir. Moi-même, si j\’étais mineur, j\’irais bien fouiller Atal\’Dazar, leur célèbre « cité d\’or ». Faites attention à ne pas vous faire prendre la main dans le sac, $n.\n\nSi vous voulez en apprendre plus, adressez-vous à Secott l\’Orfèvre. Vous le trouverez sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.', 'Le minage ? Je vous vois venir. Moi-même, si j\’étais mineuse, j\’irais bien fouiller Atal\’Dazar, leur célèbre « cité d\’or ». Faites attention à ne pas vous faire prendre la main dans le sac, $n.\n\nSi vous voulez en apprendre plus, adressez-vous à Secott l\’Orfèvre. Vous le trouverez sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.', 28153),
(159991, 'frFR', '', 'Quand vous souhaiterez retourner aux clairières de Tirisfal comme elles apparaissent dans le présent, il suffira de demander.', 28153),
(159990, 'frFR', 'Cet engin, c\’est de la bombe ! Sérieusement, il pourrait faire sauter le chapeau du palais des plaisirs de Gallywix !', '', 28153),
(159989, 'frFR', 'C\’est ma plus grande fierté, vous savez ?', '', 28153),
(159987, 'frFR', 'Une larmichette de mon ingrédient secret… et hop ! Le tour est joué !', '', 28153),
(159986, 'frFR', 'Une pincée de poudre… quelques amorces, des copeaux de cuivre…', '', 28153),
(159985, 'frFR', 'Manque deux trois trucs, mais le résultat va détonner !', '', 28153),
(159984, 'frFR', 'Y a plus qu\’à… une seconde, d\’accord ?', '', 28153),
(159983, 'frFR', 'Oooh, vous m\’avez apporté de l\’azérite ? C\’est de la bonne…', '', 28153),
(159982, 'frFR', 'Des explosions ? J\’ai ce qu\’y vous faut ! Prenez l\’une de ces merveilles et emmenez-la faire un tour.', '', 28153),
(159981, 'frFR', 'Pas touche à ma potion !', 'Pas touche à ma potion !', 28153),
(159980, 'frFR', 'Le Bon Corleone, y m\’interdit de parler aux adultes.', '', 28153),
(159979, 'frFR', 'Des engrenages et câbles endommagés pendent de ce moissonneur hors d\’usage.', 'Des engrenages et câbles endommagés pendent de ce moissonneur hors d\’usage.', 28153),
(159978, 'frFR', 'Un marteau usé est posé sur la table.', 'Un marteau usé est posé sur la table.', 28153),
(159977, 'frFR', 'Réparer le moissonneur.', 'Réparer le moissonneur.', 28153),
(159976, 'frFR', 'Vous avez vu les armures de cuir que confectionnent les Zandalari ? Si vous désirez apprendre leurs secrets, rendez-vous sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nUne fois là-bas, adressez-vous au dénommé Xanjo. C\’est l\’expert local en matière de travail du cuir.', 'Vous avez vu les armures de cuir que confectionnent les Zandalari ? Si vous désirez apprendre leurs secrets, rendez-vous sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nUne fois là-bas, adressez-vous au dénommé Xanjo. C\’est l\’expert local en matière de travail du cuir.', 28153),
(159975, 'frFR', 'Récupérer le marteau.', 'Récupérer le marteau.', 28153),
(159974, 'frFR', 'Analyser la potion.', 'Analyser la potion.', 28153),
(159973, 'frFR', 'Derek nous sera rendu… d\’une façon ou d\’une autre.', '', 28153),
(159972, 'frFR', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aNouvelle construction disponible !', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aNouvelle construction disponible !', 28153),
(159971, 'frFR', 'La bouteille est remplie d\’un étrange liquide tourbillonnant.', 'La bouteille est remplie d\’un étrange liquide tourbillonnant.', 28153),
(159970, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nChevalier-champion Dirk Longpair\n\nCapitaine du Drustvaria', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nChevalier-champion Dirk Longpair\n\nCapitaine du Drustvaria', 28153),
(159969, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nCommandant Priscilla Hawes\n\nCapitaine de l\’Œil du cyclone', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nCommandant Priscilla Hawes\n\nCapitaine de l\’Œil du cyclone', 28153),
(159968, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nLieutenant-chef Andrew Avrinn\n\nCapitaine de la Nirondelle', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nLieutenant-chef Andrew Avrinn\n\nCapitaine de la Nirondelle', 28153),
(159967, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Aloysius Valmeunier', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Aloysius Valmeunier', 28153),
(159966, 'frFR', 'Vous montez à bord d\’un bateau et vous retrouvez sur des terres inconnues à chasser les insectes et la faune locale, tout ça pour finir dans un épouvantable endroit comme ici. En tout cas, c\’est ce qui m\’est arrivé à moi. Mais j\’ai tout de même réussi à capturer de braves petites bêtes, des créatures que je n\’avais jamais vues avant d\’arriver ici. Vous voulez voir ce qu\’elles ont dans le ventre ?', '', 28153),
(159965, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Ava MacArthur', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Ava MacArthur', 28153),
(159964, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent Chris Lee', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent Chris Lee', 28153),
(159963, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent Evan Morris', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent Evan Morris', 28153),
(159962, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nChevalier-lieutenant Samuel Robertson', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nChevalier-lieutenant Samuel Robertson', 28153),
(159961, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Eloïse Astrechamp', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Eloïse Astrechamp', 28153),
(159960, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Sarah Potence', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Sarah Potence', 28153),
(159959, 'frFR', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendant O\’Keefe', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nIntendant O\’Keefe', 28153),
(159958, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent J. Dumoulin', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergent J. Dumoulin', 28153),
(159957, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSergent-chef Murgatroyd Smith', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSergent-chef Murgatroyd Smith', 28153),
(159956, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Geoffrey Van Houten', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Geoffrey Van Houten', 28153),
(159955, 'frFR', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nApprovisionneur Jarrod', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nApprovisionneur Jarrod', 28153),
(159954, 'frFR', 'Vous avez une armure à réparer ? Ma forge, c\’est la meilleure du désert… et surtout la seule.', 'Vous avez une armure à réparer ? Ma forge, c\’est la meilleure du désert… et surtout la seule.', 28153),
(159953, 'frFR', 'La mer va vous engloutir !', '', 28153),
(159952, 'frFR', '', 'Que peuvent faire les Kaldorei pour vous ?', 28153),
(159951, 'frFR', '', 'Ne touchez pas à nos archives ! Ces travaux ne vous appartiennent pas !', 28153),
(159950, 'frFR', '', 'Qu\’Élune éclaire votre route.', 28153),
(159949, 'frFR', '', 'Ne perdez pas la foi.', 28153),
(159948, 'frFR', 'Avec tous les Elfes de sang qui nous ont suivis jusqu\’ici, on aurait pu penser à prendre un joaillier avec nous. Ce sont quand même eux qui ont inventé la profession. Bah, il faut croire que les Zandalari n\’ont pas assez confiance pour nous confier leurs bijoux.\n\nBref, si vous voulez approfondir vos connaissances, vous allez devoir vous adresser à Seshuli, dans la salle des Scintillements. Pour vous y rendre, descendez jusqu\’à la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor. Ensuite, tournez-vous face à la pyramide et empruntez l\’un des tunnels. Ils vous conduiront jusqu\’à elle.', 'Avec tous les Elfes de sang qui nous ont suivis jusqu\’ici, on aurait pu penser à prendre un joaillier avec nous. Ce sont quand même eux qui ont inventé la profession. Bah, il faut croire que les Zandalari n\’ont pas assez confiance pour nous confier leurs bijoux.\n\nBref, si vous voulez approfondir vos connaissances, vous allez devoir vous adresser à Seshuli, dans la salle des Scintillements. Pour vous y rendre, descendez jusqu\’à la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor. Ensuite, tournez-vous face à la pyramide et empruntez l\’un des tunnels. Ils vous conduiront jusqu\’à elle.', 28153),
(159947, 'frFR', 'Si vous cherchez quelqu\’un pour vous enseigner les mystères de la calligraphie, c\’est au Grand Sceau que ça se passe.\n\nUne fois là-bas, montez les escaliers côté est et ils vous conduiront tout droit au hall des Chroniqueurs, où vous trouverez Kizani.', 'Si vous cherchez quelqu\’un pour vous enseigner les mystères de la calligraphie, c\’est au Grand Sceau que ça se passe.\n\nUne fois là-bas, montez les escaliers côté est et ils vous conduiront tout droit au hall des Chroniqueurs, où vous trouverez Kizani.', 28153),
(159946, 'frFR', 'L\’herboristerie, hein ? Entendu, je connais le type qu\’il vous faut. Jahden Fla, qu\’il se fait appeler. Vous le trouverez dans son jardin sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.', 'L\’herboristerie, hein ? Entendu, je connais le type qu\’il vous faut. Jahden Fla, qu\’il se fait appeler. Vous le trouverez dans son jardin sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.', 28153),
(159945, 'frFR', '', 'Nous sommes les enfants d\’Élune.', 28153),
(159944, 'frFR', '', 'Ishnu-alah.', 28153),
(159943, 'frFR', '', 'La déesse me donne sa force.', 28153),
(159942, 'frFR', 'Il y a une Zandalari sur les berges du Défilé, au nord de Dazar\’alor. Tali la Silencieuse, tel est son nom, et on raconte qu\’elle peut pêcher n\’importe quoi dans n\’importe quelles conditions.\n\nLe moins qu\’on puisse dire, c\’est qu\’elle porte bien son nom : comme elle n\’est pas du genre à se vanter, vous devrez vous faire votre propre opinion à son sujet.', 'Il y a une Zandalari sur les berges du Défilé, au nord de Dazar\’alor. Tali la Silencieuse, tel est son nom, et on raconte qu\’elle peut pêcher n\’importe quoi dans n\’importe quelles conditions.\n\nLe moins qu\’on puisse dire, c\’est qu\’elle porte bien son nom : comme elle n\’est pas du genre à se vanter, vous devrez vous faire votre propre opinion à son sujet.', 28153),
(159941, 'frFR', 'Repos.', 'Repos.', 28153),
(159940, 'frFR', 'Trop lent ! Continuez à vous entraîner !', 'Trop lent ! Continuez à vous entraîner !', 28153),
(159939, 'frFR', 'Ouvrez les yeux, bon sang ! Comment vous allez viser, sans ça, hein ?', 'Ouvrez les yeux, bon sang ! Comment vous allez viser, sans ça, hein ?', 28153),
(159938, 'frFR', 'N\’importe quoi ! On va recommencer jusqu\’à ce que vous y arriviez !', 'N\’importe quoi ! On va recommencer jusqu\’à ce que vous y arriviez !', 28153),
(159937, 'frFR', 'Vous avez perdu vos munitions, Kelada ! <soupir> Que je vous y reprenne plus !', 'Vous avez perdu vos munitions, Kelada ! <soupir> Que je vous y reprenne plus !', 28153),
(159936, 'frFR', 'Ça fait combien de temps qu\’ce fusil a pas été nettoyé, soldat ? Vous attendez qu\’on le fasse à vot\’ place ?', 'Ça fait combien de temps qu\’ce fusil a pas été nettoyé, soldat ? Vous attendez qu\’on le fasse à vot\’ place ?', 28153),
(159935, 'frFR', 'PRÉSENTEZ !', 'PRÉSENTEZ !', 28153),
(159934, 'frFR', 'Armes à l\’épaule… DROITE !', 'Armes à l\’épaule… DROITE !', 28153),
(159933, 'frFR', 'Pas étonnant que les hommes de Corsandre aient refusé d\’y aller. Cet endroit est terrifiant !', '', 28153),
(159932, 'frFR', 'Vous là-bas, vous savez de quoi ces bêtes sont capables ? Elles chassent en meute, traquent leur proie et détournent son attention avant de leur asséner le coup fatal. Ce sont de viles petites créatures. Sauf qu\’ici, c\’est moi qui commande ! Et ça, elles le savent ! Envie de voir comment vos petits amis s\’en sortent contre les miens ?', '', 28153),
(159931, 'frFR', '$n mâche une poignée de popcorn.', '$n mâche une poignée de popcorn.', 28153),
(159930, 'frFR', 'Oui, la personne qu\’il vous faut, c\’est Shuga Splosamorce, sur la terrasse des Artisans. Vous la trouverez avec son copain Myxle, au pied de la pyramide de Dazar\’alor, côté ouest.\n\nOn peut savoir ce que vous comptez faire sauter ?', 'Oui, la personne qu\’il vous faut, c\’est Shuga Splosamorce, sur la terrasse des Artisans. Vous la trouverez avec son copain Myxle, au pied de la pyramide de Dazar\’alor, côté ouest.\n\nOn peut savoir ce que vous comptez faire sauter ?', 28153),
(159929, 'frFR', 'Oh, non… C\’est pire encore que nous le redoutions… Ils l\’ont envoyée à Funesterre.', '', 28153),
(159928, 'frFR', 'Ah ! Voilà ce qu\’on cherchait.', '', 28153),
(159927, 'frFR', 'Il y a largement de quoi l\’envoyer à l\’ombre. Mais, bon, maintenant qu\’il est mort, la question ne se pose plus vraiment…', '', 28153),
(159926, 'frFR', 'L\’enchanteresse elfe de sang Quinni est arrivée en même temps que nous. Ouvrez grand vos oreilles : pour la trouver, rendez-vous sur la terrasse de l\’Artisanat, au pied de Dazar\’alor, côté ouest. Ensuite, tournez-vous face à la pyramide et cherchez un passage pour descendre. Il y a un tunnel qui vous conduira jusqu\’à la salle des Scintillements.\n\nC\’est qu\’on en a amené un bon paquet, de ces Elfes de sang. Forcément, on est en droit de se poser des questions…', 'L\’enchanteresse elfe de sang Quinni est arrivée en même temps que nous. Ouvrez grand vos oreilles : pour la trouver, rendez-vous sur la terrasse de l\’Artisanat, au pied de Dazar\’alor, côté ouest. Ensuite, tournez-vous face à la pyramide et cherchez un passage pour descendre. Il y a un tunnel qui vous conduira jusqu\’à la salle des Scintillements.\n\nC\’est qu\’on en a amené un bon paquet, de ces Elfes de sang. Forcément, on est en droit de se poser des questions…', 28153),
(159925, 'frFR', 'Pièces d\’or, gemmes, cartes au trésor, demandes de rançon, et… Ça alors ! Quel petit cachottier, cet Harlan !', '', 28153),
(159924, 'frFR', 'Je dois reconnaître que votre éthique professionnelle est admirable. Joli travail.', '', 28153),
(159923, 'frFR', '', 'Encore heureux… Alors, qu\’y-a-t\’il dedans ?', 28153),
(159922, 'frFR', 'Ça alors… il n\’a même pas explosé !', '', 28153),
(159921, 'frFR', 'Le cartel Baille-Fonds doit veiller à nourrir les ranishu pour qu\’ils alimentent ses mécas. Apportez votre aide aux Gobelins. Plus tôt ils auront fini, plus vite ils seront partis.', '', 28153),
(159920, 'frFR', 'Plus qu\’un verrou. Espérons qu\’il ne soit pas piégé.', '', 28153),
(159919, 'frFR', 'Bon. Il est temps d\’ouvrir ce coffre.', '', 28153),
(159918, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nChevalier-capitaine Ellis R. Ladimore\n\nCapitaine du Va-t-en-mer', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nChevalier-capitaine Ellis R. Ladimore\n\nCapitaine du Va-t-en-mer', 28153),
(159917, 'frFR', 'Présentez… armes !', 'Présentez… armes !', 28153),
(159916, 'frFR', 'La famille royale zandalari nous a offert les services de sa propre cuisinière. T\’sarah, tel est son nom. Vous la trouverez à l\’intérieur du Grand Sceau, à l\’étage, côté ouest.\n\nPar contre, je ne peux pas me porter garant de ses talents. Je ne mange jamais d\’aliments cuits.', 'La famille royale zandalari nous a offert les services de sa propre cuisinière. T\’sarah, tel est son nom. Vous la trouverez à l\’intérieur du Grand Sceau, à l\’étage, côté ouest.\n\nPar contre, je ne peux pas me porter garante de ses talents. Je ne mange jamais d\’aliments cuits.', 28153),
(159915, 'frFR', 'Dans la partie basse de Dazar\’alor, côté ouest, vous trouverez la terrasse de l\’Artisanat. Il y a là-bas un énorme Troll redoutable zandalari qui se fait appeler le maître-forge Zak-machin-truc. Vous ne pouvez pas le louper, il tape comme un sourd sur son enclume à longueur de journée.', 'Dans la partie basse de Dazar\’alor, côté ouest, vous trouverez la terrasse de l\’Artisanat. Il y a là-bas un énorme Troll redoutable zandalari qui se fait appeler le maître-forge Zak-machin-truc. Vous ne pouvez pas le louper, il tape comme un sourd sur son enclume à longueur de journée.', 28153),
(159914, 'frFR', 'Nous avons amené l\’examinatrice Alerinda avec nous. Elle est à l\’intérieur du Grand Sceau, dans une salle de l\’aile ouest.\n\nSauf erreur de ma part, elle supervise l\’exhumation d\’un dinosaure géant loin au sud-ouest. Vous devriez lui proposer votre aide.', 'Nous avons amené l\’examinatrice Alerinda avec nous. Elle est à l\’intérieur du Grand Sceau, dans une salle de l\’aile ouest.\n\nSauf erreur de ma part, elle supervise l\’exhumation d\’un dinosaure géant loin au sud-ouest. Vous devriez lui proposer votre aide.', 28153),
(159913, 'frFR', 'Fusiliers ! À vos rangs !', 'Fusiliers ! À vos rangs !', 28153),
(159912, 'frFR', '', 'Nous sommes heureux de vous revoir, $n.', 28153),
(159911, 'frFR', '', 'Une seconde ! Ce n\’est pas moi qui… <soupire>', 28153),
(159910, 'frFR', 'Regardez qui voilà ! Tu vois, Taelia, je t\’avais bien dit qu\’il n\’y avait aucune raison de s\’inquiéter pour notre camarade !', '', 28153),
(159909, 'frFR', '', 'Je me fais du souci chaque fois que ma famille doit aller dans ces collines.', 28153),
(159908, 'frFR', 'Eh ! Faites attention avec ces trucs !', '', 28153),
(159907, 'frFR', '', 'Il nous reste quelques grenades, $n ! C\’est le moment de s\’en servir !', 28153),
(159906, 'frFR', 'C\’est Kumali l\’Astucieuse qu\’il vous faut. Vous la trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor, près du rez-de-chaussée.\n\nMéfiez-vous, les Sombrelances n\’arrêtent pas de nous mettre en garde contre les féticheurs et leur vaudou de malheur.', 'C\’est Kumali l\’Astucieuse qu\’il vous faut. Vous la trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor, près du rez-de-chaussée.\n\nMéfiez-vous, les Sombrelances n\’arrêtent pas de nous mettre en garde contre les féticheurs et leur vaudou de malheur.', 28153),
(159905, 'frFR', 'Si vous voyez un type louche, faites-moi signe. Je lui arracherai la vérité à coups de latte.', '', 28153),
(159904, 'frFR', 'Ce coffre, il est sous la surveillance de Blaise le Balèze. Personne mettra la main sur son contenu !', '', 28153),
(159903, 'frFR', 'Vous et moi, il faudra qu\’on parle de nos intérêts communs, après ça.', '', 28153),
(159902, 'frFR', '', 'Place à ma partie préférée !', 28153),
(159901, 'frFR', 'Place à ma partie préférée.', '', 28153),
(159900, 'frFR', 'Nous en reviendrons tous… et le prisonnier aussi.', '', 28153),
(159899, 'frFR', 'Depuis le temps, j\’ai vu toutes sortes de trésors. D\’ailleurs, les affaires que les gens viennent déposer dans ces coffres m\’étonneront toujours.', '', 28153),
(159898, 'frFR', '', 'Compris.', 28153),
(159897, 'frFR', 'Vos affaires, elles sont en lieu sûr, $p.\n\nJ\’ai gardé les trésors des rois, les entrepôts des marchands, les bijoux d\’un bon nombre de tarés et même la becquetance des hors-caste.\n\nQuoi que ce soit, je veille dessus.', '', 28153),
(159896, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nSergent-major Alison Silex', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nSergent-major Alison Silex', 28153),
(159895, 'frFR', 'Les derniers criminels qui ont essayé de dévaliser ce coffre, ils sont en Vol\’dun, maintenant… comme tous les autres avant eux.', '', 28153),
(159894, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Jameson Keefe', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporal Jameson Keefe', 28153),
(159893, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Lorelai Lameule', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat Lorelai Lameule', 28153),
(159892, 'frFR', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat James Simmons', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldat James Simmons', 28153),
(159891, 'frFR', 'Ce coffre, c\’est le plus sûr de Zandalar. Rien ne sort ou ne rentre sans mon autorisation.\n\nDéposez vos affaires ici, et vous pourrez dormir tranquille. C\’est aussi simple que ça.', '', 28153),
(159890, 'frFR', 'On m\’a chargé de garder le coffre et je prends mon travail très au sérieux, $p.\n\nTenez-vous à carreau, et tout ira bien.\n\nMais au moindre geste déplacé, je vous emballe dans la plus petite caisse que je trouverai et je vous expédie en Vol\’dun. Ensuite, les Sephraks, ils auront plus qu\’à vous jeter en pâture à leurs vautours.\n\nC\’est clair ?', '', 28153),
(159889, 'frFR', 'J\’ai passé un accord avec les Zandalari. Ils m\’autorisent à rester et moi, je les invite et je les divertis.', '', 28153),
(159888, 'frFR', 'Un membre de l\’Alliance en Zandalar ? Surveillez vos arrières.\n\nS\’ils vous voient, ils n\’hésiteront pas à vous attaquer.', '', 28153),
(159887, 'frFR', 'On est bien loin de chez nous, vous et moi. Et si on allait plutôt boire un pot au Grand bazar ?', '', 28153),
(159886, 'frFR', '', 'Astarii… Évacuez la ville… avant qu\’elle ne brûle…', 28153),
(159885, 'frFR', 'Oh, bien sûr. Si vous avez besoin des services d\’un professionnel, vous devriez trouver votre bonheur sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nQuel genre d\’instructeur recherchez-vous ?', 'Oh, bien sûr. Si vous avez besoin des services d\’un professionnel, vous devriez trouver votre bonheur sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nQuel genre d\’instructeur recherchez-vous ?', 28153),
(159884, 'frFR', 'Un saurolisque a renversé le chariot et toutes les fournitures ont été projetées aux alentours.', '', 28153),
(159883, 'frFR', '', 'Genn a beau être un « vieux loup », avec moi, il ronronne comme un chaton.', 28153),
(159882, 'frFR', '', 'Les Elfes de la nuit ont sauvé mon peuple. Je ferai tout pour les aider.', 28153),
(159881, 'frFR', 'Je vais rester ici pour m\’occuper des chevaux.', '', 28153),
(159880, 'frFR', '', 'Les Kaldorei ont besoin de notre aide.', 28153),
(159879, 'frFR', '', 'Le temps presse.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159878, 'frFR', '', 'Merci ! Je pense pouvoir rentrer par mes propres moyens.', 28153),
(159877, 'frFR', '', 'Faites-leur payer cette infamie.', 28153),
(159876, 'frFR', '', 'Tant de sang d\’innocents versé…', 28153),
(159875, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(159874, 'frFR', 'La trogne hideuse, j\’en fais mon affaire !', 'La trogne hideuse, j\’en fais mon affaire !', 28153),
(159873, 'frFR', 'Pas de prisonniers !', 'Pas de prisonniers !', 28153),
(159872, 'frFR', 'Propriété de l\’Alliance ! Dégagez !', 'Propriété de l\’Alliance ! Dégagez !', 28153),
(159871, 'frFR', 'Vous avez fait une erreur, vermine de la Horde !', 'Vous avez fait une erreur, vermine de la Horde !', 28153),
(159870, 'frFR', '', 'Sauvez autant de monde que possible !', 28153),
(159869, 'frFR', '', 'Les coupables paieront pour leurs crimes.', 28153),
(159868, 'frFR', 'Quant à nous, nous vous rejoindrons là-bas pour faire le point quand nous en aurons terminé.', '', 28153),
(159867, 'frFR', '', 'Pour l\’Alliance.', 28153),
(159866, 'frFR', '', 'Mon foyer m\’appelle.', 28153),
(159865, 'frFR', '', 'Merci pour tous vos efforts.', 28153),
(159864, 'frFR', '', 'En quoi puis-je vous aider ?', 28153),
(159863, 'frFR', '', 'Un royaume ne repose pas sur des terres, mais sur son peuple.', 28153),
(159862, 'frFR', '', 'Gilnéas vous est reconnaissante.', 28153),
(159861, 'frFR', '', 'Salutations.', 28153),
(159860, 'frFR', 'Lame. Gorge. Je ne vois pas ce qu\’il y a de compliqué.', '', 28153),
(159859, 'frFR', 'Tuer est déjà une récompense. Mais j\’accepte aussi l\’argent.', '', 28153),
(159858, 'frFR', '$n, faites-nous savoir quand vous voudrez qu\’on lance les préparatifs pour saborder ce navire. Quand on l\’aura fait exploser, je veux que vous alliez informer le roi Wrynn de notre réussite.', '', 28153),
(159857, 'frFR', 'Impressionnons le chef de guerre… nous aurons peut-être une belle récompense.', '', 28153),
(159856, 'frFR', 'Donnons une bonne leçon à ces sauvages, d\’accord ?', '', 28153),
(159855, 'frFR', 'Keeshan, Kelsey, faites en sorte qu\’il explose une fois que tout le monde aura quitté le bord.', '', 28153),
(159854, 'frFR', 'Ne perdons pas de temps.', '', 28153),
(159853, 'frFR', 'La guerre est toujours un moment si particulier.', '', 28153),
(159852, 'frFR', 'Umbric, nous allons avoir besoin d\’une dernière faille du Vide pour évacuer nos troupes.', '', 28153),
(159851, 'frFR', 'Nous devons saborder ce navire. Shandris, aidez nos hommes à se préparer en vue du départ.', '', 28153),
(159848, 'frFR', 'J\’aime vraiment mon travail.', '', 28153),
(159847, 'frFR', 'On se met au travail ?', '', 28153),
(159845, 'frFR', 'Les miens viendront me délivrer, comme ils l\’ont fait pour la princesse Talanji et Zul !', '', 28153),
(159844, 'frFR', 'J\’ai hâte de voir ça. En attendant, le devoir m\’appelle.', '', 28153),
(159843, 'frFR', 'Vous pouvez nous résister ou coopérer, c\’est à vous de choisir.', '', 28153),
(159842, 'frFR', 'Je m\’en occupe.', 'Je m\’en occupe.', 28153),
(159841, 'frFR', 'Non. Le sang a assez coulé pour aujourd\’hui, capitaine. Vous êtes notre prisonnier et nous vous emmenons à Hurlevent.', '', 28153),
(159840, 'frFR', 'Maudits chiens de l\’Alliance ! Tuez-moi et qu\’on en finisse !', '', 28153),
(159839, 'frFR', '', 'Le capitaine Zalkran tentait de fuir vers Zuldazar, mais Falstad et moi l\’avons épinglé.', 28153),
(159838, 'frFR', 'Pouvez-vous me faire un rapport circonstancié, Shandris ?', 'Pouvez-vous me faire un rapport circonstancié, Shandris ?', 28153),
(159837, 'frFR', 'Pouvez-vous me renvoyer dans le présent ?', 'Pouvez-vous me renvoyer dans le présent ?', 28153),
(159836, 'frFR', 'Pouvez-vous me montrer à quoi ressemblaient les clairières de Tirisfal avant la bataille de Lordaeron ?', 'Pouvez-vous me montrer à quoi ressemblaient les clairières de Tirisfal avant la bataille de Lordaeron ?', 28153),
(159835, 'frFR', '', 'Oh, et si vous voyez mon petit-fils Charles, vérifiez bien qu\’il n\’est pas en train de se cacher sous un arbre quelque part.', 28153),
(159834, 'frFR', 'Est-ce que vous avez commencé à apprivoiser les créatures qui vivent sur ces terres exotiques ? Pour ma part, je m\’intéresse de très près aux masques de sang tiki, mais je ne sais pas si les autochtones verront ça d\’un bon œil.\n\nSi vous cherchez un maître des écuries, il y a un éleveur de bêtes qui se fait appeler Kalatak, près de la base nord-ouest de Dazar\’alor.', 'Est-ce que vous avez commencé à apprivoiser les créatures qui vivent sur ces terres exotiques ? Pour ma part, je m\’intéresse de très près aux masques de sang tiki, mais je ne sais pas si les autochtones verront ça d\’un bon œil.\n\nSi vous cherchez un maître des écuries, il y a un éleveur de bêtes qui se fait appeler Kalatak, près de la base nord-ouest de Dazar\’alor.', 28153),
(159833, 'frFR', 'L\’équipage de la Princesse violette est en grève. Une histoire de salaires non payés pendant onze ans ? Je ne suis pas sûr, je n\’ai pas trop écouté.', 'L\’équipage de la Princesse violette est en grève. Une histoire de salaires non payés pendant onze ans ? Je ne suis pas sûre, je n\’ai pas trop écouté.', 28153),
(159832, 'frFR', 'Comment puis-je me rendre dans la vallée de Strangleronce ?', 'Comment puis-je me rendre dans la vallée de Strangleronce ?', 28153),
(159831, 'frFR', '', 'On dirait que j\’ai à nouveau besoin de votre aide !', 28153),
(159830, 'frFR', '', 'Et vous, je vous remercie encore. Même si nous ne sommes pas encore tirés d\’affaire.', 28153),
(159829, 'frFR', '', 'Bien sûr, mère. Je serais de retour très vite.', 28153),
(159828, 'frFR', '', 'Taelia ! Rassemblez les troupes avec l\’émissaire. Jaina et moi allons organiser nos défenses.', 28153),
(159827, 'frFR', '', '$n ! Je vais une fois encore avoir besoin de votre aide.', 28153),
(159826, 'frFR', '', 'Priscilla veut s\’emparer de la ville…', 28153),
(159825, 'frFR', '', 'Ou est-il déjà… trop tard ?', 28153),
(159824, 'frFR', '', 'Racontez-moi. Avez-vous découvert quelque chose ?', 28153),
(159823, 'frFR', '', '$n ! Oh, Jaina n\’est pas avec vous…', 28153),
(159822, 'frFR', '', 'Le chariot est fichu et on a bien failli se faire tuer.\n\nLa bête qui nous a attaqués s\’est réfugiée dans cette grotte. Je ne repartirai pas tant qu\’elle ne sera pas morte !', 28153),
(159821, 'frFR', '', 'Amiral suprême ! Des voiles à l\’horizon ! Elles battent le pavillon corsandre !', 28153),
(159820, 'frFR', '', 'Mère… je…', 28153),
(159819, 'frFR', '', 'Jaina, laisse-moi t\’offrir enfin un accueil digne de ce nom. Bienvenue chez toi, ma fille.', 28153),
(159818, 'frFR', '', 'Qu\’il est bon de sentir de nouveau l\’air marin. Merci, $n. Sans vous, je n\’aurais peut-être jamais eu cette chance…', 28153),
(159817, 'frFR', 'Salutations !\n\nDame Malvoie m\’a ordonné de préparer mon faucon le plus rapide pour transporter votre message.', '', 28153),
(159816, 'frFR', 'Dites à Katherine Portvaillant qu\’elle doit me retrouver à Gol Inath.', 'Dites à Katherine Portvaillant qu\’elle doit me retrouver à Gol Inath.', 28153),
(159815, 'frFR', 'Je cherche un moyen de pénétrer dans les confins Corrompus.', 'Je cherche un moyen de pénétrer dans les confins Corrompus.', 28153),
(159814, 'frFR', '', 'Protégez-la au péril de votre vie. Kul Tiras a déjà perdu bien trop de Portvaillant.', 28153),
(159813, 'frFR', '', 'Vous avez réussi ! L\’effigie a fonctionné !', 28153),
(159812, 'frFR', '', 'Mais bien sûr ! Les gravures au mur indiquent la séquence à suivre !', 28153),
(159811, 'frFR', '', 'Les runes ont peut-être besoin d\’être activées dans un certain ordre…', 28153),
(159810, 'frFR', '', 'Ça n\’a pas dû être très agréable…', 28153),
(159809, 'frFR', '', 'Essayez d\’en activer une autre.', 28153),
(159808, 'frFR', '', 'Plus rien ! Se pourrait-il que ces runes agissent comme des protections ?', 28153),
(159807, 'frFR', '', 'Il doit bien y avoir un indice sur la manière dont tout cela fonctionne.', 28153),
(159806, 'frFR', '', 'Eh bien, il s\’est passé… quelque chose…', 28153),
(159805, 'frFR', '', 'Cela ressemble à une porte. Peut-être faut-il y placer l\’effigie ?', 28153),
(159804, 'frFR', '', 'Allons, je dois me ressaisir. Jaina a dû faire face à bien pire, par ma faute…', 28153),
(159803, 'frFR', '', 'Cet endroit me glace le sang. J\’ai presque l\’impression de marcher sur ma propre tombe…', 28153),
(159802, 'frFR', '', 'Nous allons donc voyager en petit comité. Je vous suis.', 28153),
(159801, 'frFR', '', 'Ces… monstres nous ont attaqué par surprise dans les bois. Ma garde d\’honneur a donné sa vie pour moi.', 28153),
(159800, 'frFR', '', '$n ! Ah ! Je suis heureuse de vous voir !\n', 28153),
(159799, 'frFR', 'À vos ordres ! Hannibal, ici présent, portera votre message au donjon Portvaillant sans délai !', '', 28153),
(159798, 'frFR', 'Vous êtes en sécurité, maintenant.', 'Vous êtes en sécurité, maintenant.', 28153),
(159797, 'frFR', '', 'Je sais que Katherine prévoit de se joindre à vous dans cette folle entreprise.', 28153),
(159796, 'frFR', 'Cet affreux Sacrenuit d\’Oculeth nous a ouvert des portails vers Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre. Vous les trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.\n\nMalheureusement, nous n\’avons aucun portail pour Fossoyeuse. Bientôt, on se vengera de ces fumiers de l\’Alliance ! Genn, Jaina et le roi Anduin paieront pour leurs crimes !\n\nVictoire au chef de guerre Sylvanas ! Puisse son règne durer mille ans !', 'Cet affreux Sacrenuit d\’Oculeth nous a ouvert des portails vers Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre. Vous les trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.\n\nMalheureusement, nous n\’avons aucun portail pour Fossoyeuse. Bientôt, on se vengera de ces fumiers de l\’Alliance ! Genn, Jaina et le roi Anduin paieront pour leurs crimes !\n\nVictoire au chef de guerre Sylvanas ! Puisse son règne durer mille ans !', 28153),
(159795, 'frFR', 'Le chemin vers les Ulterres est périlleux. Pour autant, ces dangers ne sont rien en comparaison de ce qui vous attend dans les confins Corrompus.\n\nArmez-vous d\’une volonté d\’acier, car les abominations des Ulterres retourneront contre vous vos plus grands remords et terreurs.', '', 28153),
(159794, 'frFR', 'L\’entrée des Ulterres se trouve à l\’intérieur du grand arbre, Gol Inath. Mais franchir ce seuil ne sera pas sans difficulté.\n\nPour ouvrir la voie, il vous faudra une effigie d\’une grande puissance. Non pas une babiole du Sabbat, mais une relique chargée de la vieille magie drust.', '', 28153),
(159793, 'frFR', '', 'Le chariot s\’est retourné d\’un seul coup. C\’était terrifiant !\n\nJ\’étais censée retourner en ville chercher de l\’aide, mais j\’ai eu peur.', 28153),
(159792, 'frFR', 'Ah, qu\’il est bon de rencontrer une âme qui suit le même chemin.\n\nQue venez vous chercher auprès des Parlépines ?', '', 28153),
(159791, 'frFR', 'Vous voilà de retour ?\n\nIl me semble pourtant que notre dette a été payée. Venez-vous demander de nouvelles faveurs aux Parlépines ?', '', 28153),
(159790, 'frFR', 'Cela fait bien longtemps qu\’aucun natif du continent n\’avait mis les pieds ici.\n\nDésirez-vous puiser à la source du savoir des Parlépines ? Ou venez-vous revendiquer ces terres que votre espèce aspire tant à contrôler ?', '', 28153),
(159789, 'frFR', 'Voilà qui change tout.', '', 28153),
(159788, 'frFR', 'Les faits me donnent tort. Ce sont les Ulterres qui viennent à nous.', '', 28153),
(159787, 'frFR', 'Nous sommes loin d\’en avoir fini, vieil ours.', '', 28153),
(159786, 'frFR', 'Je veillerai à leur sécurité.', 'Je veillerai à leur sécurité.', 28153),
(159785, 'frFR', 'Vous n\’êtes pas en position de juger la valeur de quiconque. Vos agissements souillent notre honneur, Tul !', '', 28153),
(159784, 'frFR', 'Vous partageriez nos dons avec ces larves, Ulfar ? Vous méritez de finir sur le même bûcher !', '', 28153),
(159783, 'frFR', 'Comment puis-je me rendre au fjord Hurlant ?', 'Comment puis-je me rendre au fjord Hurlant ?', 28153),
(159782, 'frFR', 'Parlépines ! Aux armes !', '', 28153),
(159781, 'frFR', 'Nous avons perdu le contact avec le Frôle-nuage au-dessus de la Grande mer. On était à deux doigts de battre le record : huit cent quinze vols successifs sans ravitaillement ! Bah, je suis certain que tout va bien.', 'Nous avons perdu le contact avec le Frôle-nuage au-dessus de la Grande mer. On était à deux doigts de battre le record : huit cent quinze vols successifs sans ravitaillement ! Bah, je suis certain que tout va bien.', 28153),
(159780, 'frFR', 'Gorak Tul ! Impossible !', '', 28153),
(159779, 'frFR', 'Il est trop tard pour se préoccuper d\’attirer l\’attention, vieil ours.', '', 28153),
(159778, 'frFR', 'Certains passages doivent restés scellés, ne serait-ce que pour éviter d\’attirer ceux qui se trouvent de l\’autre côté.', '', 28153),
(159777, 'frFR', 'J\’ai bien peur de ne pas pouvoir vous aider.', '', 28153),
(159776, 'frFR', 'Vous souhaitez pénétrer dans les Ulterres ? Je crains de ne pouvoir vous aider.', '', 28153),
(159775, 'frFR', '', 'Dites-moi, vous ne songez pas sérieusement à vous aventurer dans les confins Corrompus ?', 28153),
(159774, 'frFR', '', 'Ah ! J\’ai reçu des nouvelles de Katherine !', 28153),
(159773, 'frFR', '', 'Je suis responsable de son sort. C\’est à moi de réparer le tort causé.', 28153),
(159772, 'frFR', '', 'Si… Quand vous trouverez Jaina, je veux être présente. Je suis prête à affronter tous les dangers.', 28153),
(159771, 'frFR', '', 'Un dernier mot, $n.', 28153),
(159770, 'frFR', 'Un saurolisque a effrayé les chevaux, le chariot s\’est renversé et nous avons perdu notre matériel.\n\nMes deux filles, Lorraine et Mallory, sont toujours là-bas. Elles auraient bien besoin de votre aide.', '', 28153),
(159769, 'frFR', 'Avec les gars, c\’est là-bas qu\’on va tous les jours après le service. Faut bien qu\’on s\’entraîne.\n\nÇa se passe à l\’Armurerie royale, du côté nord de Dazar\’alor, près de la base de la pyramide. Vous devriez vous joindre à nous.', 'Avec les gars, c\’est là-bas qu\’on va tous les jours après le service. Faut bien qu\’on s\’entraîne.\n\nÇa se passe à l\’Armurerie royale, du côté nord de Dazar\’alor, près de la base de la pyramide. Vous devriez vous joindre à nous.', 28153),
(159768, 'frFR', '', 'Trouvez le frère Pike ! Il s\’est toujours montré loyal et dévoué. Je sais qu\’il nous aidera.', 28153),
(159767, 'frFR', '', 'Après tout, elle ne faisait qu\’obéir à mes ordres.', 28153),
(159766, 'frFR', '', 'Seuls les eaugures peuvent l\’approcher sans crainte. Corsandre n\’aura eu aucun mal à les contraindre d\’y emmener Jaina.', 28153),
(159765, 'frFR', '', 'Dites-moi qu\’il n\’est pas trop tard.', 28153),
(159764, 'frFR', '', 'Où ont-ils emmené Jaina ?', 28153),
(159763, 'frFR', 'Oui. Moi aussi.', '', 28153),
(159762, 'frFR', '', 'Flynn, arrête de jouer les idiots. J\’espère sincèrement que tu te trompes.', 28153),
(159761, 'frFR', 'Tu paries maintenant ? Quelle honte ! Que dirait Cirrus s\’il l\’apprenait ?', '', 28153),
(159760, 'frFR', 'Je présume que vous avez une affaire à régler avec les Sombrelances. Vous savez que le bateau va aux îles de l\’Écho, n\’est-ce pas ? Vous avez envie de faire une petite excursion avant de rentrer à Orgrimmar, ou quoi ?\n\nQuoi qu\’il en soit, vous trouverez le bateau au bout du quai sud, au port de Zandalar.', 'Je présume que vous avez une affaire à régler avec les Sombrelances. Vous savez que le bateau va aux îles de l\’Écho, n\’est-ce pas ? Vous avez envie de faire une petite excursion avant de rentrer à Orgrimmar, ou quoi ?\n\nQuoi qu\’il en soit, vous trouverez le bateau au bout du quai sud, au port de Zandalar.', 28153),
(159759, 'frFR', '', 'Si je devais désigner quelqu\’un capable de la ramener, je parierais sur notre $uami:amie;.', 28153),
(159758, 'frFR', 'Cette île ne porte pas le nom de Funesterre pour rien, Taelia.', '', 28153),
(159757, 'frFR', 'Beau travail. Regroupons-nous.', '', 28153),
(159756, 'frFR', 'Je peux vous déposer à la Complainte de la Banshee, $p. Mais vous allez devoir vous accrocher !', '', 28153),
(159755, 'frFR', 'Marteaux-Hardis, déployez-vous et dégagez l\’espace aérien, mais évitez de vous faire repérer pour l\’instant.', '', 28153),
(159750, 'frFR', '', 'Ha… le capitaine… va tous vous tuer…', 28153),
(159749, 'frFR', '', 'Vous arrivez trop tard ! Le capitaine a déjà signalé votre position à la princesse Talanji.', 28153),
(159748, 'frFR', 'J\’ai le Gobelin qu\’il vous faut. Il s\’appelle Myxle Canevrille et vous le trouverez sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, secteur sud-ouest.\n\nÀ l\’en croire, son Déchiket-tout Mod. I vous démonte n\’importe quel équipement en moins de deux pour obtenir des pièces à recycler ou à revendre. J\’aurais bien accepté son offre, mais cette armure m\’a été fournie par la Horde.', 'J\’ai le Gobelin qu\’il vous faut. Il s\’appelle Myxle Canevrille et vous le trouverez sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, secteur sud-ouest.\n\nÀ l\’en croire, son Ferraill-o-matic 1000 vous démonte n\’importe quel équipement en moins de deux pour obtenir des pièces à recycler ou à revendre. J\’aurais bien accepté son offre, mais cette armure m\’a été fournie par la Horde.', 28153),
(159747, 'frFR', 'Pour atteindre le Trône doré, vous devez prendre les ascenseurs prévus pour ça, à l\’intérieur du Grand Sceau.\n\nVous vous entendez bien avec la famille royale ? Entre vous et moi, qu\’est-ce que vous pensez de leurs coiffes ? Ils ont des cous de taureau, ma parole !', 'Pour atteindre le Trône doré, vous devez prendre les ascenseurs prévus pour ça, à l\’intérieur du Grand Sceau.\n\nVous vous entendez bien avec la famille royale ? Entre vous et moi, qu\’est-ce que vous pensez de leurs coiffes ? Ils ont des cous de taureau, ma parole !', 28153),
(159746, 'frFR', 'Il faut bien reconnaître que la cité est vaste. Je connais quelques endroits qui valent le détour, si ça vous intéresse.', 'Il faut bien reconnaître que la cité est vaste. Je connais quelques endroits qui valent le détour, si ça vous intéresse.', 28153),
(159745, 'frFR', 'Brillin la Belle est au centre du Grand Sceau. Admirable danseuse, n\’est-ce pas ?', 'Brillin la Belle est au centre du Grand Sceau. Admirable danseuse, n\’est-ce pas ?', 28153),
(159744, 'frFR', 'Il y a une Zandalari nommée Paku\’ai qui gère un service de vol. Si vous cherchez un pterreurdactyle, allez la voir sur la corniche, devant le Grand Sceau, côté est.', 'Il y a une Zandalari nommée Paku\’ai qui gère un service de vol. Si vous cherchez un pterreurdactyle, allez la voir sur la corniche, devant le Grand Sceau, côté est.', 28153),
(159743, 'frFR', 'Ça dépend de l\’émissaire que vous cherchez, $n.', 'Ça dépend de l\’émissaire que vous cherchez, $n.', 28153),
(159742, 'frFR', 'Alors, on fait ami-ami avec les Zandalari ? Pas bête. C\’est exactement ce qu\’attend le chef de guerre.\n\nVous trouverez leur émissaire, Natal\’hakata, à l\’intérieur du Grand Sceau.', 'Alors, on fait ami-ami avec les Zandalari ? Pas bête. C\’est exactement ce qu\’attend le chef de guerre.\n\nVous trouverez leur émissaire, Natal\’hakata, à l\’intérieur du Grand Sceau.', 28153),
(159741, 'frFR', 'Vous cherchez à percer les secrets des Tortollans ? On raconte qu\’ils vivent des siècles. C\’est toujours moins que ce qui m\’attend, mais tout de même…\n\nEnfin bref, allez voir le collectionneur Kojo au poste de Troc-Écailles, au nord-est de Dazar\’alor.', 'Vous cherchez à percer les secrets des Tortollans ? On raconte qu\’ils vivent des siècles. C\’est toujours moins que ce qui m\’attend, mais tout de même…\n\nEnfin bref, allez voir le collectionneur Kojo au poste de Troc-Écailles, au nord-est de Dazar\’alor.', 28153),
(159740, 'frFR', 'Je vois. Une petite coupe et une couleur, peut-être ? Conner Toutausabot, voilà l\’homme qu\’il vous faut. Vous le trouverez au Grand bazar du port.', 'Je vois. Une petite coupe et une couleur, peut-être ? Conner Toutausabot, voilà l\’homme qu\’il vous faut. Vous le trouverez au Grand bazar du port.', 28153),
(159739, 'frFR', 'Pourquoi faut-il que ça se termine toujours comme ça ?', '', 28153),
(159738, 'frFR', 'Pas si bas ! Pas si bas !', '', 28153),
(159737, 'frFR', '', 'Nous allons voler plus bas pour les semer ! En avant, Trombecœur !', 28153),
(159736, 'frFR', 'M\’accrocher ! Comme si j\’avais le choix !', '', 28153),
(159735, 'frFR', '', 'Accrochez-vous ! Ils nous tirent dessus !', 28153),
(159734, 'frFR', 'Le Trésor royal est à l\’intérieur de la pyramide, à l\’ouest du Grand Sceau. On comptait y affecter du personnel gobelin, mais les Zandalari ont refusé.\n\nIls ne sont pas bêtes.', 'Le Trésor royal est à l\’intérieur de la pyramide, à l\’ouest du Grand Sceau. On comptait y affecter du personnel gobelin, mais les Zandalari ont refusé.\n\nIls ne sont pas bêtes.', 28153),
(159733, 'frFR', 'Les îles de l\’Écho ? Pourquoi vous voulez aller là-bas ? C\’est le fief des Sombrelances. C\’est tout petit, en plus. Vous feriez mieux de rester en Zandalar, c\’est plus grand.\n\nNon ? Bon, vous avez de la chance, on leur a prêté un de nos petits navires de guerre. Il est amarré au bout du quai sud, dans le port de Zandalar.', 'Les îles de l\’Écho ? Pourquoi vous voulez aller là-bas ? C\’est le fief des Sombrelances. C\’est tout petit, en plus. Vous feriez mieux de rester en Zandalar, c\’est plus grand.\n\nNon ? Bon, vous avez de la chance, on leur a prêté un de nos petits navires de guerre. Il est amarré au bout du quai sud, dans le port de Zandalar.', 28153),
(159732, 'frFR', 'Navire pour les îles de l\’Écho', 'Navire pour les îles de l\’Écho', 28153),
(159731, 'frFR', 'Le contremaître Al\’jibo, il est dans le hall des Voies antiques, du côté est du Grand Sceau. Je ne peux rien vous garantir vu qu\’il a débarqué avec la Horde, mais je parie qu\’il saura réparer et affûter vos armes comme il faut.\n\nSinon, ben… vous irez rejoindre Bwonsamdi plus tôt que prévu.', 'Le contremaître Al\’jibo, il est dans le hall des Voies antiques, du côté est du Grand Sceau. Je ne peux rien vous garantir vu qu\’il a débarqué avec la Horde, mais je parie qu\’il saura réparer et affûter vos armes comme il faut.\n\nSinon, ben… vous irez rejoindre Bwonsamdi plus tôt que prévu.', 28153),
(159730, 'frFR', 'Si vous avez b\’soin de nous, évacuez le bateau et envoyez un signal. Vol-au-Vent et moi, on vous trouvera.', '', 28153),
(159729, 'frFR', 'Ha ! C\’est c\’que je préfère dans tout ça !', '', 28153),
(159728, 'frFR', 'On y est, Vol-au-Vent. Fais-nous descendre discrètement, qu\’on nous voie pas. File comme le vent.', '', 28153),
(159727, 'frFR', 'Réparations', 'Réparations', 28153),
(159726, 'frFR', 'Pour sûr que vous avez de l\’or à dépenser. On est en Zandalar ! Même les Gobelins, ils sont pas aussi riches que nous.\n\nAlors, vous cherchez quoi, au juste ?', 'Pour sûr que vous avez de l\’or à dépenser. On est en Zandalar ! Même les Gobelins, ils sont pas aussi riches que nous.\n\nAlors, vous cherchez quoi, au juste ?', 28153),
(159725, 'frFR', 'Marchands', 'Marchands', 28153),
(159724, 'frFR', '', 'Je vais aller reconnaître la Risée écarlate pendant que vous espionnez la Complainte de la Banshee. Tor ilisar\’thera\’nal !', 28153),
(159723, 'frFR', '', 'On se rapproche. Je sens d\’ici la pestilence de la non-mort.', 28153),
(159722, 'frFR', 'Votre Sacrenuit, il trafique avec son vaudou dans le hall des Voies antiques. C\’est du côté est, à l\’intérieur du Grand Sceau.\n\nIl vous a bricolé un moyen de retourner dans vos petites villes. Comment elles s\’appellent, déjà ? Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre, c\’est ça ?', 'Votre Sacrenuit, il trafique avec son vaudou dans le hall des Voies antiques. C\’est du côté est, à l\’intérieur du Grand Sceau.\n\nIl vous a bricolé un moyen de retourner dans vos petites villes. Comment elles s\’appellent, déjà ? Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre, c\’est ça ?', 28153),
(159721, 'frFR', 'Portails', 'Portails', 28153),
(159720, 'frFR', 'Comment avez-vous atterri ici ?', 'Comment avez-vous atterri ici ?', 28153),
(159719, 'frFR', 'Nous y voilà ! Je parie que les informations qu\’il nous faut pour trouver Jaina sont là-dedans.\n\n<Flynn désigne le coffre.>\n\nC\’est vous qui avez les clés, alors à vous l\’honneur.', '', 28153),
(159718, 'frFR', '', 'Il est trop tard !', 28153),
(159717, 'frFR', '', 'J\’aurai... réussi...', 28153),
(159716, 'frFR', 'Alors comme ça, vous voulez vous entraîner ? Ça tombe bien, c\’est ici à Dazar\’alor qu\’on trouve les meilleurs mannequins. Allez voir à l\’Armurerie royale.\n\nC\’est du côté nord de la pyramide de Dazar\’alor.', 'Alors comme ça, vous voulez vous entraîner ? Ça tombe bien, c\’est ici à Dazar\’alor qu\’on trouve les meilleurs mannequins. Allez voir à l\’Armurerie royale.\n\nC\’est du côté nord de la pyramide de Dazar\’alor.', 28153),
(159715, 'frFR', '<Zenbaro tousse.>', '', 28153),
(159714, 'frFR', 'Mannequins d\’entraînement', 'Mannequins d\’entraînement', 28153),
(159713, 'frFR', '', 'Quand vous souhaiterez retourner dans les hautes-terres Arathies comme elles apparaissent dans le présent, il suffira de demander.', 28153),
(159712, 'frFR', 'Vous allez devoir me protéger pendant que j\’accomplis ce rituel. Je n\’en ai pas pour longtemps.', '', 28153),
(159711, 'frFR', 'Pouvez-vous me renvoyer dans le présent ?', 'Pouvez-vous me renvoyer dans le présent ?', 28153),
(159710, 'frFR', '<Donner la gourde à Zenbaro.>', '<Donner la gourde à Zenbaro.>', 28153),
(159709, 'frFR', 'Allez, $n. Finissons-en.', '', 28153),
(159708, 'frFR', 'Pouvez-vous me montrer à quoi ressemblaient les hautes-terres Arathies avant que le conflit n\’éclate ?', 'Pouvez-vous me montrer à quoi ressemblaient les hautes-terres Arathies avant que le conflit n\’éclate ?', 28153),
(159707, 'frFR', '', 'Effectivement, vous êtes bien sur la liste ! Montez, c\’est la dernière porte au bout du couloir. Monsieur Camden va vous recevoir immédiatement.', 28153),
(159706, 'frFR', '', 'La guerre fait rage sur ces terres, reproduisant les schémas d\’un lointain passé. Les cycles du temps sont inexorables.\n\nVeuillez m\’excuser. J\’oublie parfois que la vision de votre peuple est… linéaire.\n\nEn quoi puis-je vous aider ?', 28153),
(159705, 'frFR', '', 'Je regrette, mais nous recevons uniquement sur rendez-vous. Gardes !', 28153),
(159704, 'frFR', 'Oui, j\’ai rendez-vous. Au nom de monsieur Bosc.', 'Oui, j\’ai rendez-vous. Au nom de madame Bosc.', 28153),
(159703, 'frFR', 'Vous ne me reconnaissez pas ? C\’est moi, $n, champion de l\’Alliance ! Je dois consulter vos dossiers séance tenante !', 'Vous ne me reconnaissez pas ? C\’est moi, $n, championne de l\’Alliance ! Je dois consulter vos dossiers séance tenante !', 28153),
(159702, 'frFR', 'J\’ai rendez-vous avec votre patron. Je dois lui parler immédiatement, c\’est très important !', 'J\’ai rendez-vous avec votre patron. Je dois lui parler immédiatement, c\’est très important !', 28153),
(159701, 'frFR', '', 'En quoi puis-je vous aider, aujourd\’hui ?', 28153),
(159700, 'frFR', '', 'Bienvenue dans les locaux de la compagnie marchande Corsandre. Vous avez rendez-vous ?', 28153),
(159699, 'frFR', 'Ah, vous voilà, $p. Montez !', '', 28153),
(159698, 'frFR', 'Ouais… Allez, débarrassons-nous de ça.', '', 28153),
(159697, 'frFR', '', 'Ces terres sont chargées d\’histoire. Je me dois de vous montrer à quoi elles ressemblaient à l\’apogée de l\’empire arathorien.\n\nToutefois, le moment est mal choisi.\n\nEn avez-vous terminé avec le passé ?', 28153),
(159696, 'frFR', 'En effet. Je ne prétends pas que c\’est la meilleure solution, mais nous devons faire avec les cartes que nous avons en main.', '', 28153),
(159695, 'frFR', 'Sale boulot, de devoir tuer tous les Zandalari à bord du navire. Pas vrai, Halford ?', '', 28153),
(159694, 'frFR', 'Placez la clé de la mer dans le bol quand vous souhaiterez commencer le rituel.', '', 28153),
(159693, 'frFR', 'J\’attendais votre retour avec impatience, $n.', '', 28153),
(159692, 'frFR', 'Je commençais à croire que vous ne revendriez pas…', '', 28153),
(159691, 'frFR', 'Content de vous revoir, $n. J\’avoue que je ne pensais pas que vous reviendriez.', '', 28153),
(159689, 'frFR', 'Bon, commençons par le commencement.\n\nMes plus anciens souvenirs, et aussi les meilleurs, ils remontent à l\’époque où je faisais les quatre cents coups avec les canailles de Zuldazar.\n\nOn avait le chic pour se mettre dans le pétrin, mais on ne savait rien faire d\’autre.\n\nRajin, c\’était notre chef. Il nous a offert un toit et en échange, on faisait tout ce qu\’il nous demandait.\n\nGénéralement, il s\’agissait d\’arnaquer les gens de la ville ou de piller des coffres dans le temple du Loa.', '', 28153),
(159688, 'frFR', '', 'Du nerf ! On est en territoire hostile, pas à Hurlevent ! Déchargeons tout ce bazar et évacuons les blessés en vitesse !', 28153),
(159687, 'frFR', 'Ce n\’est pas la question qu\’on finit tous par se poser ?\n\n<Zenbaro tousse.>\n\nLes sables, ils n\’ont pas été tendres avec moi, $n. Ma fin approche.\n\nJ\’ai la gorge tout enflée par la chaleur du désert.\n\nAllez me chercher de l\’eau fraîche à la source tout près d\’ici, et je vous raconterai mon histoire.', '', 28153),
(159686, 'frFR', 'Vous parlez de l\’autre Gobelin avec son engin bizarre, sur la terrasse de l\’Artisanat ? Il paraît que son Ferraill-o-matic, il vous démonte n\’importe quel équipement pour tout recycler.\n\nIl est dans la partie basse de Dazar\’alor, côté ouest.', 'Vous parlez de l\’autre Gobelin avec son engin bizarre, sur la terrasse de l\’Artisanat ? Il paraît que son Ferraill-o-matic, il vous démonte n\’importe quel équipement pour tout recycler.\n\nIl est dans la partie basse de Dazar\’alor, côté ouest.', 28153),
(159685, 'frFR', 'Je n\’avais jamais imaginé finir ainsi. Tout seul, au milieu de ces dunes…', '', 28153),
(159684, 'frFR', 'Ferrailleur', 'Ferrailleur', 28153),
(159683, 'frFR', 'Nous y sommes. Descendons au sous-sol.', '', 28153),
(159682, 'frFR', 'Qu\’est-ce que vous lui voulez, au Trône doré ? Une audience ?\n\nPour monter, il faut prendre les ascenseurs, dans le Grand Sceau.', 'Qu\’est-ce que vous lui voulez, au Trône doré ? Une audience ?\n\nPour monter, il faut prendre les ascenseurs, dans le Grand Sceau.', 28153),
(159681, 'frFR', 'Le sous-sol en question doit être dans les parages. Ne perdons pas de temps.', '', 28153),
(159680, 'frFR', 'Le Trône doré', 'Le Trône doré', 28153),
(159679, 'frFR', 'Pouvons-nous commencer ?', '', 28153),
(159678, 'frFR', 'Dépêchons-nous. On entre et on ressort avant de se faire repérer.', '', 28153),
(159677, 'frFR', 'On y va !', '', 28153),
(159676, 'frFR', '', 'Immédiatement.', 28153),
(159675, 'frFR', 'Shandris, allez patrouiller les plages et assurez-vous qu\’aucun survivant ne s\’échappe. Falstad vous rejoindra une fois qu\’il nous aura déposés.', '', 28153),
(159674, 'frFR', '', 'Ils ne comprendront pas ce qui leur arrive.', 28153),
(159673, 'frFR', 'Pigé.', '', 28153),
(159672, 'frFR', 'Keeshan, Kelsey, utilisez le portail d\’Umbric et établissez une zone d\’atterrissage sur le pont supérieur du bateau.', '', 28153),
(159671, 'frFR', 'À vos ordres.', '', 28153),
(159670, 'frFR', 'Umbric, ouvrez un portail du Vide pour permettre aux Nains sombrefer de rejoindre l\’Appel de Gral.', '', 28153),
(159669, 'frFR', 'Nous devons veiller à ce qu\’aucun passager de ce navire ne retourne à Zuldazar, ou c\’en est fini de nous et de notre mission.', '', 28153),
(159668, 'frFR', 'Je suis prêt à y aller.', 'Je suis prête à y aller.', 28153),
(159667, 'frFR', '', 'Tout le monde va bien se payer ma tête, à l\’académie. Oh, Yuké, quelle maladresse, alors !', 28153),
(159666, 'frFR', '', 'Merci ! En fait, j\’appartiens aux Pandashan. C\’est juste que je prends un jour de repos, voilà tout. Tenez, un peu d\’azérite, et pas un mot de toute cette histoire, d\’accord ?', 28153),
(159665, 'frFR', 'Par les vagues, si je m\’attendais… Vais-je périr ici ?', '', 28153),
(159664, 'frFR', 'Vous avez toute ma gratitude. Il faudra que je me montre plus prudent à l\’avenir. Tenez, voilà un cadeau pour vous remercier de votre bienveillance.', '', 28153),
(159663, 'frFR', 'Allons bon, voilà un cartographe coincé dans l\’exercice de ses fonctions !', '', 28153),
(159662, 'frFR', 'Ha ha ! Que serait la cartographie sans une pointe de frisson et de danger ? Je vois bien dans votre regard hagard que vous êtes tout à fait d\’accord avec moi. Tenez, c\’est pour vous. Quant à moi, je retourne à mes cartes !', '', 28153),
(159661, 'frFR', 'Il est très gênant pour un dragon de faire ce genre de requête, mais… vous pourriez m\’apporter un peu d\’aide ?', '', 28153),
(159660, 'frFR', 'Merci. Ces îles regorgent d\’objets magiques dignes de mon temps et de mon attention. Mais je préférerais qu\’il y ait moins de pièges…', '', 28153),
(159659, 'frFR', 'Aidez Chaussettes, et la chance vous sourira !', '', 28153),
(159658, 'frFR', 'Chaussettes est libre ! Votre chance va vous sourire comme jamais, aujourd\’hui ! C\’est votre destin, maintenant !', '', 28153),
(159657, 'frFR', '', 'Oh, Péppi, encore un pépin ! Va falloir trouver un moyen de te sortir de là…', 28153),
(159656, 'frFR', '', 'Vous êtes super ! Je vais pouvoir reprendre mes explorations ! Bon sang, je ne serais plus Péppi Finrouage si je devais renoncer à l\’aventure !', 28153),
(159655, 'frFR', 'Activation des processus de gratitude. Gratitude en cours d\’expression. Gratitude exprimée.', '', 28153),
(159654, 'frFR', 'Détection d\’un obstacle. Activation du mode Aide. À L\’AIDE À L\’AIDE À L\’AIDE À L\’AIDE À L\’AIDE À L\’AIDE À L\’AIDE À L\’AIDE. Répétition en cours.', '', 28153),
(159653, 'frFR', '', 'Hé, vous faites quoi ici ? Vous voulez bien m\’aider ? Il m\’arrive une tuile.', 28153),
(159652, 'frFR', '', 'C\’est beaucoup mieux. Z\’êtes quelqu\’un de bien. Alors voilà un petit quelque chose pour votre peine.', 28153),
(159651, 'frFR', 'Vous ! Ça vous dirait d\’aider un pauvre hère ? Je vous promets que je ne suis plus avec la Légion ! C\’est fini, cette époque. Je suis un électron libre, maintenant. Sylvester, le diablotin honnête.', '', 28153),
(159650, 'frFR', 'Waouh, merci, vraiment. Je vous suis très reconnaissant. Bon allez, je file. Et ne me suivez pas.', '', 28153),
(159649, 'frFR', '', 'Hé ! Bonjour ? Ah, oui, bonjour. Vous pouvez m\’aider ? Je ne sais pas trop quoi faire là, je suis un peu perdue.', 28153),
(159648, 'frFR', '', 'Merci ! Du fond du cœur, vraiment. Vous savez où nous sommes ? Je n\’ai aucune idée de ce que je fais ici. Où est mon embarcation ? J\’avais une embarcation ?', 28153),
(159647, 'frFR', 'J\’aurais besoin d\’un coup de main ? Il y a quelqu\’un ?', '', 28153),
(159646, 'frFR', 'Ah, je vous remercie du coup de main. Et comment avez-vous atterri ici, vous ? Peu importe, je vois bien qu\’il vous tarde de reprendre la route.', '', 28153),
(159645, 'frFR', 'La grande cité de Dazar\’alor, c\’est la plus puissante du monde entier. Ses quartiers vous réservent bien des merveilles, et ses habitants brillent par leur force et leur sagesse.\n\nPar contre, le vaudou, il faut s\’en méfier !', 'La grande cité de Dazar\’alor, c\’est la plus puissante du monde entier. Ses quartiers vous réservent bien des merveilles, et ses habitants brillent par leur force et leur sagesse.\n\nPar contre, le vaudou, il faut s\’en méfier !', 28153),
(159644, 'frFR', 'Ouh là là, j\’ai peur d\’être un peu dépassé par les évènements, là. Hum… Réfléchissons…', '', 28153),
(159643, 'frFR', 'Ah, merci infiniment. Si vous saviez le nombre de fois que cela m\’est arrivé… Je finirai bien par retenir la leçon un jour ! Mais pas aujourd\’hui en tout cas, ah ! Tenez, c\’est tout ce que j\’ai, mais je suis heureux de le partager avec vous.', '', 28153),
(159642, 'frFR', 'Gregg besoin aide ! Devoir aider Gregg !', '', 28153),
(159641, 'frFR', 'Vous aider Gregg ! Gregg tellement heureux ! Gregg donner cailloux ! Gregg adorer cailloux.', '', 28153),
(159640, 'frFR', 'Hé, vous là ! Vous pourriez peut-être aider le bon vieux Frankie ? Et peut-être qu\’il vous donnera quelque chose d\’intéressant en retour ? Alors, z\’en dites quoi ?', '', 28153),
(159639, 'frFR', 'Ouf, c\’est mieux comme ça. Si j\’avais su que quelqu\’un comme vous me sauverait la mise un jour… Comme quoi, la vie réserve parfois des surprises. Tenez, prenez cette azérite pour la peine. Et pas la peine de raconter que vous avez vu le vieux Frankie ici.', '', 28153),
(159638, 'frFR', 'Oui ! Lumèche vous remercie ! Tenez, prenez les gemmes !', '', 28153),
(159637, 'frFR', 'Vous ! À l\’aide ! Donnez-moi un coup de main, je vous dis !', '', 28153),
(159636, 'frFR', 'Hé, brouf, j\’ai besoin d\’aide, là !', '', 28153),
(159635, 'frFR', 'J\’ai eu un peu la main lourde sur les pierres de lest. Ouf, merci, brouf.', '', 28153),
(159634, 'frFR', 'Émissaire de l\’Empire zandalari', 'Émissaire de l\’Empire zandalari', 28153),
(159633, 'frFR', '', 'Oh, waouh, merci ! Vous êtes super. Et j\’essaierai de ne pas recommencer.', 28153),
(159632, 'frFR', '', 'Regarde le pétrin dans lequel tu t\’es fourrée cette fois, Karyn. Oh, et comment est-ce que je vais me sortir de là, moi ?', 28153),
(159631, 'frFR', 'Le collectionneur Kojo, vous le trouverez au poste de Troc-Écailles, au nord-est de la cité.\n\nFaites attention, le mojo tortollan, il est vraiment étrange.', 'Le collectionneur Kojo, vous le trouverez au poste de Troc-Écailles, au nord-est de la cité.\n\nFaites attention, le mojo tortollan, il est vraiment étrange.', 28153),
(159630, 'frFR', 'Émissaire des Chercheurs tortollans', 'Émissaire des Chercheurs tortollans', 28153),
(159629, 'frFR', 'J\’en connais plusieurs. Vous cherchez quoi au juste ?', 'J\’en connais plusieurs. Vous cherchez quoi au juste ?', 28153),
(159628, 'frFR', 'Points d\’intérêt', 'Points d\’intérêt', 28153),
(159627, 'frFR', 'Bienvenue dans mon humble demeure, $c. J\’espère que votre repos sera… paisible.', '', 28153),
(159626, 'frFR', 'Non. Je vous expliquerai…', '', 28153),
(159625, 'frFR', '', 'L\’heure n\’est pas aux lamentations. Les Mag\’har rebâtiront leur foyer. Ici même.', 28153),
(159624, 'frFR', 'Le portail vers Azeroth restera ouvert assez longtemps pour que vos guerriers puissent faire leurs préparatifs avant de partir.', '', 28153),
(159623, 'frFR', 'Aka\’Magosh, Geya\’rah. Je ferai avertir votre mère de votre décision. Je vous souhaite un bon voyage, Eitrigg. Et à vous aussi, $n.', '', 28153),
(159622, 'frFR', '', 'Bienvenue, $n ! Cet avant-poste, il est sous votre commandement.', 28153),
(159621, 'frFR', 'Sentir une fois de plus les pierres de Draenor sous mes semelles en combat… Ce fut une journée mémorable.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159620, 'frFR', '', 'Vous avez déjà réussi à ouvrir le passage vers Draenor. Au fond de mon cœur, je sais que nous reviendrons.', 28153),
(159619, 'frFR', 'La magie permettant de rejoindre Azeroth est instable. Vous ne pourrez peut-être pas rentrer chez vous.', '', 28153),
(159618, 'frFR', 'Vous avez toute notre gratitude. $n, préparez-vous à rallier…', '', 28153),
(159617, 'frFR', 'Je soupçonnais bien que les liens tissés au combat vous pousseraient à accompagner ces héros, Geya\’rah. Vous avez ma bénédiction.', '', 28153),
(159616, 'frFR', '', 'Le chef de guerre tiendra à distance les Draeneï et les traîtres empreints de Lumière. Avec l\’aide des Mag\’har, vous remporterez la victoire, et cette vieille dette sera enfin réglée.', 28153),
(159615, 'frFR', 'Vous, commandant ? Pourtant le combat se poursuit ici ?', '', 28153),
(159614, 'frFR', '', 'J\’irai. Avec un bataillon de volontaires. Si vous m\’y autorisez, chef de guerre.', 28153),
(159613, 'frFR', 'Alors, pour en revenir à la dette que nous avons envers votre Horde, nous allons envoyer…', '', 28153),
(159612, 'frFR', '', 'Ils ont lutté avec courage. Je dois admettre que… je vous ai mal jugé, Eitrigg. Et vous aussi, $n.', 28153),
(159611, 'frFR', 'Nous nous tiendrons prêts. Et ces héros d\’Azeroth ? Leur aide vous a-t-elle été précieuse ?', '', 28153),
(159610, 'frFR', '', 'L\’attaque draeneï a été repoussée, chef de guerre. Pour autant, la grande exarque reviendra certainement à la charge. Les fanatiques n\’abandonnent jamais.', 28153),
(159609, 'frFR', 'Les pirates ont pris le large à Port-Liberté, nous en apprendrons davantage en nous y rendant. Je connais justement quelqu\’un qui pourra nous aider.', '', 28153),
(159608, 'frFR', '', 'Je… Vous avez raison, Genn. Mais, même si c\’est le cas, nous n\’avons aucun indice.', 28153),
(159607, 'frFR', 'Il est probable qu\’ils n\’aient pas encore atteint leur destination. Il n\’est peut-être pas trop tard.', '', 28153),
(159606, 'frFR', 'Le contrat indique que Jaina devait être enlevée, pas exécutée.', '', 28153),
(159605, 'frFR', '', 'Comment pouvez-vous dire une chose pareille ?', 28153),
(159604, 'frFR', '', 'On se retrouve au camp, $n.', 28153),
(159603, 'frFR', '', 'Elle a engagé des pirates pour exécuter ma fille, Genn ! Des pirates ! La lie du monde marin !', 28153),
(159602, 'frFR', '', 'Chaque minute compte, et le seul indice dont nous disposons est un contrat conclu entre Priscilla et des brigands de Port-Liberté !', 28153),
(159601, 'frFR', 'Réfléchissez, Katherine. Ce pourrait en réalité être une bonne nouvelle.', '', 28153),
(159600, 'frFR', '', 'Attendez… vous êtes vraiment… ?', 28153),
(159599, 'frFR', '', 'Nul ne consultera ces plans de l\’Alliance hormis nous. Préparez-vous à mourir !', 28153),
(159598, 'frFR', 'Vous ne pouvez pas… être… des nôtres…', '', 28153),
(159597, 'frFR', 'Ha, les Trolls de sang sont trop bêtes pour comprendre les secrets de l\’Alliance.', '', 28153),
(159596, 'frFR', '', 'Vous… n\’êtes pas… des nôtres…', 28153),
(159595, 'frFR', '', 'Vous appartenez aux Trolls de sang ? Je m\’en vais régler ça rapidement avant d\’apporter ces plans aux Zandalari.', 28153),
(159594, 'frFR', 'Je sens bizarre, maintenant !', 'J\’ai plus envie de jouer !', 28153),
(159593, 'frFR', 'C\’est un bonhomme tout vert qui nous les a vendus, sur la côte !', 'C\’est un bonhomme tout vert qui nous les a vendus, sur la côte !', 28153),
(159592, 'frFR', 'Les miliciens sont toujours là pour nous protéger ! Enfin, sauf maintenant. Ils avaient une réunion importante avec les eaugures. Ils font un peu peur des fois, sauf frère Pike. Lui, il est toujours gentil avec moi.', 'Les miliciens sont toujours là pour nous protéger ! Enfin, sauf maintenant. Ils avaient une réunion importante avec les eaugures. Ils font un peu peur des fois, sauf frère Pike. Lui, il est toujours gentil avec moi.', 28153),
(159591, 'frFR', 'Tout ça, c\’était l\’idée de Grettle !', 'Ça vous dirait, un nouveau familier ?', 28153),
(159590, 'frFR', 'Pourquoi Chantorage, d\’ailleurs ? Je les ai jamais entendus chanter.$b$bLes adultes sont bizarres, pas vrai ?', 'Pourquoi Chantorage, d\’ailleurs ? Je les ai jamais entendus chanter.$b$bLes adultes sont bizarres, pas vrai ?', 28153),
(159589, 'frFR', 'Vous avez déjà goûté les palourdes à la vapeur ? C\’est la spécialité de Chantorage !', 'Vous avez déjà goûté les palourdes à la vapeur ? C\’est la spécialité de Chantorage !', 28153),
(159588, 'frFR', 'J\’adore aller à l\’hydromellerie Mildenhall ! Mes parents, ils disent que je suis trop petit pour boire de l\’hydromel, mais ils me donnent toujours un rayon de miel.', 'J\’adore aller à l\’hydromellerie Mildenhall ! Mes parents, ils disent que je suis trop petite pour boire de l\’hydromel, mais ils me donnent toujours un rayon de miel.', 28153),
(159587, 'frFR', 'Je me demande si je serai aussi grand que maman et papa, un jour. Ils finissent toujours leurs légumes, peut-être que je devrais aussi…', 'Je me demande si je serai aussi grande que maman et papa, un jour. Ils finissent toujours leurs légumes, peut-être que je devrais aussi…', 28153),
(159586, 'frFR', 'Ma maman et mon papa, ils travaillent dur pour nous donner à manger. J\’aime vraiment bien manger, moi !', 'Ma maman et mon papa, ils travaillent dur pour nous donner à manger. J\’aime vraiment bien manger, moi !', 28153),
(159585, 'frFR', 'Bonjour ! C\’est la première fois que vous venez dans la vallée ?', 'Bonjour ! C\’est la première fois que vous venez dans la vallée ?', 28153),
(159584, 'frFR', 'J\’espère qu\’il n\’y a pas eu de témoin.', 'On va faire comme s\’il ne s\’était rien passé !', 28153),
(159583, 'frFR', 'Cela fait des générations que nous nous en remettons aux eaugures. La mer leur accorde sa sagesse, ça ne fait pas l\’ombre d\’un doute.', 'Cela fait des générations que nous nous en remettons aux eaugures. La mer leur accorde sa sagesse, ça ne fait pas l\’ombre d\’un doute.', 28153),
(159582, 'frFR', 'J\’ai connu des jours meilleurs.', 'Tout ça reste entre nous, hein.', 28153),
(159581, 'frFR', 'Avez-vous goûté les spécialités de la vallée ? Je vous conseille notre pain frais avec de la saucisse de Drustvar, le tout accompagné d\’une bonne chope d\’hydromel… J\’en salive rien que d\’y penser !', 'Avez-vous goûté les spécialités de la vallée ? Je vous conseille notre pain frais avec de la saucisse de Drustvar, le tout accompagné d\’une bonne chope d\’hydromel… J\’en salive rien que d\’y penser !', 28153),
(159580, 'frFR', 'Avant, les miliciens veillaient sur nous en permanence. Je me demande ce qui les a poussés à partir.', 'Avant, les miliciens veillaient sur nous en permanence. Je me demande ce qui les a poussés à partir.', 28153),
(159579, 'frFR', 'Nous travaillons la terre pour nourrir les habitants de Kul Tiras. C\’est dur, mais si gratifiant !', 'Nous travaillons la terre pour nourrir les habitants de Kul Tiras. C\’est dur, mais si gratifiant !', 28153),
(159578, 'frFR', 'Nous vivons de la terre, mais nous restons les enfants de la mer.', 'Nous vivons de la terre, mais nous restons les enfants de la mer.', 28153),
(159577, 'frFR', 'Les mers vous guident.', 'Les mers vous guident.', 28153),
(159576, 'frFR', 'Bienvenue dans la vallée !', 'Bienvenue dans la vallée !', 28153),
(159575, 'frFR', 'Ah $n, vous voilà. Certains Portvaillant ont réussi à passer. Éliminez-les.', '', 28153),
(159574, 'frFR', '', 'Je ne tiens plus en place. Laissez-moi apporter mon aide depuis les ombres.', 28153),
(159573, 'frFR', '', 'Maman, il est où papa ?', 28153),
(159572, 'frFR', 'Salutations, $r. Vous avez quelque chose à retoucher ?\n\nLa puissance de l\’azérite ne connaît pas de limite. Ce qui n\’est pas le cas de mes tarifs, je vous rassure.', '', 28153),
(159571, 'frFR', '', 'Venez, champions d\’Azeroth. Nous devons informer le chef de guerre de cette victoire…', 28153),
(159570, 'frFR', '', 'Votre grande exarque ne vous sauvera pas ! Nous poursuivrons le combat tant que Draenor ne sera pas libérée !', 28153),
(159569, 'frFR', 'Yrel… J\’ai échoué…', '', 28153),
(159568, 'frFR', 'Cette terre autrefois fertile n\’est plus que poussière sans vie. Voilà le fruit de votre haine !', '', 28153),
(159567, 'frFR', '', 'Laissez nos cicatrices tranquilles !', 28153),
(159566, 'frFR', 'Renoncez à cette haine ! La Lumière guérit les cicatrices de la guerre !', '', 28153),
(159565, 'frFR', '', 'L\’asservissement, oui !', 28153),
(159564, 'frFR', 'Les Naaru offrent la paix et l\’ordre !', '', 28153),
(159563, 'frFR', 'Pour Draenor ! Pour les Mag\’har !', '', 28153),
(159562, 'frFR', '', 'Trêve de bavardages ! Laissons le champ de bataille livrer son jugement !', 28153),
(159561, 'frFR', 'La grande exarque exige votre soumission… ou votre châtiment !', '', 28153),
(159560, 'frFR', '', 'Battez en retraite tant que vous le pouvez ! Vous ne nous convertirez pas de force, Draeneï !', 28153),
(159559, 'frFR', 'Inutile de résister, Mag\’har ! Déposez les armes et tendez les bras à la Lumière !', '', 28153),
(159558, 'frFR', 'Nous vous suivons, Geya\’rah !', '', 28153),
(159557, 'frFR', '', 'Ils attaquent le bastion du Deuil éternel ! Avec moi, héros !', 28153),
(159556, 'frFR', 'La grande exarque n\’aspire qu\’à notre bonheur !', 'La grande exarque n\’aspire qu\’à notre bonheur !', 28153),
(159555, 'frFR', 'La Lumière nous a sauvés. Elle peut vous sauver, vous aussi !', 'La Lumière nous a sauvés. Elle peut vous sauver, vous aussi !', 28153),
(159554, 'frFR', 'Grommash appartient au passé, offrez-vous un nouvel avenir !', 'Grommash appartient au passé, offrez-vous un nouvel avenir !', 28153),
(159553, 'frFR', 'Marchez avec nous dans la Lumière, mes frères et sœurs !', 'Marchez avec nous dans la Lumière, mes frères et sœurs !', 28153),
(159552, 'frFR', 'Ensemble, nous pouvons sauver Draenor !', 'Ensemble, nous pouvons sauver Draenor !', 28153),
(159551, 'frFR', 'Vous avez ravagé ces terres, mais il est encore temps de les sauver !', 'Vous avez ravagé ces terres, mais il est encore temps de les sauver !', 28153),
(159550, 'frFR', 'Prêtez foi aux visions de la grande exarque !', 'Prêtez foi aux visions de la grande exarque !', 28153),
(159549, 'frFR', 'Nous sommes venus vous sauver de votre sauvagerie !', 'Nous sommes venus vous sauver de votre sauvagerie !', 28153),
(159548, 'frFR', 'Rendez-vous, Mag\’har ! Acceptez la Lumière !', 'Rendez-vous, Mag\’har ! Acceptez la Lumière !', 28153),
(159547, 'frFR', 'Bienvenue.', '', 28153),
(159546, 'frFR', '', 'Éradiquez la corruption de la Lumière !', 28153),
(159545, 'frFR', '', 'Arrière, Draeneï ! Votre Lumière ne brillera pas ici !', 28153),
(159544, 'frFR', '', 'Tenez bon, ne reculez pas d\’un pouce ! Ces terres appartiennent aux Mag\’har !', 28153),
(159543, 'frFR', 'Akunda vous salue.', '', 28153),
(159542, 'frFR', '', 'Détruisez les engins de siège !', 28153),
(159541, 'frFR', '', 'Dans ce cas, nous combattrons ensemble pour le sang et l\’honneur ! Avec moi, héros !', 28153),
(159540, 'frFR', 'Je n\’ai encore jamais tourné le dos à un combat. Je ne vais pas commencer aujourd\’hui.', '', 28153),
(159539, 'frFR', '', 'Ce combat n\’est pas le vôtre, étrangers. Vous êtes libres de retourner sur Azeroth.', 28153),
(159538, 'frFR', 'Nous tenons le front, commandant, mais l\’ennemi semble se préparer à lancer un assaut massif.', '', 28153),
(159537, 'frFR', '', 'Lantresor ! Au rapport !', 28153),
(159536, 'frFR', 'Vous pouvez aussi décocher un Tir acéré sur vos ennemis. Cela les fera saigner quelque temps.', '', 28153),
(159535, 'frFR', 'Nous combattrons à vos côtés, commandant !', '', 28153),
(159534, 'frFR', '', 'Je ne laisserai pas la grande exarque mener impunément sa croisade contre la liberté des Mag\’har ! Il faut mettre un terme à la tyrannie de la Lumière !', 28153),
(159533, 'frFR', '', 'Certains allèrent même jusqu\’à trahir leur propre famille en prenant fait et cause pour les Draeneï… Jusqu\’au fils du chef de guerre lui-même ! Ces traîtres, nous les appelons les empreints de Lumière.', 28153),
(159532, 'frFR', '', 'Leurs maîtres, les Naaru, les appelèrent à étendre leur influence sur les Orcs. Certains s\’abandonnèrent à la Lumière de plein gré, mais d\’autres y furent contraints.', 28153),
(159531, 'frFR', '', 'Mais une fois la guerre contre les démons terminée, les Draeneï développèrent une obsession malsaine pour leur précieuse Lumière.', 28153),
(159530, 'frFR', '', 'Après la chute d\’Archimonde, les Orcs et les Draeneï unirent leurs forces pour chasser la Légion de Draenor. Ce fut une glorieuse époque.', 28153),
(159529, 'frFR', '', 'Vous méritez de le savoir, oui.', 28153),
(159528, 'frFR', 'Nous aimerions en savoir plus sur ces empreints de Lumière, commandant.', '', 28153),
(159527, 'frFR', '', 'Parfait ! Je voulais justement accrocher une deuxième tête d\’exarque à mon mur. Venez, étrangers !', 28153),
(159526, 'frFR', 'Une exarque est à leur tête. Ils arrivent… en très grand nombre.', 'Une exarque est à leur tête. Ils arrivent… en très grand nombre.', 28153),
(159525, 'frFR', '', 'Que ces traîtres soient maudits ! Combien sont-ils ?', 28153),
(159524, 'frFR', 'Commandant Geya\’rah ! Les empreints de Lumière attaquent le guet des Bêtes !', 'Commandant Geya\’rah ! Les empreints de Lumière attaquent le guet des Bêtes !', 28153),
(159523, 'frFR', 'Et voilà. Vous ressemblez à présent à n\’importe lequel de ces Trolls de sang. Temporairement, je vous rassure.', '', 28153),
(159522, 'frFR', 'Mais nous ne pouvons pas prendre le risque de laisser un seul membre de l\’Alliance se faire repérer dans le port de guerre Rastari.', '', 28153),
(159521, 'frFR', 'Je m\’excuse pour l\’inconvenance de ce rituel, $n.', '', 28153),
(159520, 'frFR', 'Je suis prêt à me transformer en Troll de sang, Umbric.', 'Je suis prête à me transformer en Trollesse de sang, Umbric.', 28153),
(159519, 'frFR', 'Il paraît que Pin\’jin, c\’est le Troll le plus patient que Zandalar ait jamais porté. Pas étonnant, vous me direz. C\’est qu\’il faut se les cogner, tous ces snobs avec leurs frusques.\n\nSi vous avez la patience qu\’il faut, allez le voir sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 'Il paraît que Pin\’jin, c\’est le Troll le plus patient que Zandalar ait jamais porté. Pas étonnant, vous me direz. C\’est qu\’il faut se les cogner, tous ces snobs avec leurs frusques.\n\nSi vous avez la patience qu\’il faut, allez le voir sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 28153),
(159517, 'frFR', 'Vous croyez peut-être que c\’est facile de dépecer un ankylodon ? Ben non, figurez-vous ! Si vous voulez apprendre, il faut aller voir Rana.\n\nAux dernières nouvelles, elle vient juste de rentrer. Vous la trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.\n\nTenez-vous bien, sinon elle risque de vous écorcher, vous aussi !', 'Vous croyez peut-être que c\’est facile de dépecer un ankylodon ? Ben non, figurez-vous ! Si vous voulez apprendre, il faut aller voir Rana.\n\nAux dernières nouvelles, elle vient juste de rentrer. Vous la trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.\n\nTenez-vous bien, sinon elle risque de vous écorcher, vous aussi !', 28153),
(159515, 'frFR', 'Qu\’est-ce que vous lui voulez, à ce voleur de Secott ? On ne l\’a pas encore attrapé, mais on sait qu\’il vole l\’or d\’Atal\’Dazar ! Les Loas, ils vont lui faire payer cher, et si c\’est pas eux, ce sera moi.\n\nVotre copain, vous le trouverez sur la terrasse de l\’Artisanat. On vous a à l\’œil, tous les deux.', 'Qu\’est-ce que vous lui voulez, à ce voleur de Secott ? On ne l\’a pas encore attrapé, mais on sait qu\’il vole l\’or d\’Atal\’Dazar ! Les Loas, ils vont lui faire payer cher, et si c\’est pas eux, ce sera moi.\n\nVotre copain, vous le trouverez sur la terrasse de l\’Artisanat. On vous a à l\’œil, tous les deux.', 28153),
(159513, 'frFR', 'Xanjo, il prend les peaux que Rana veut bien lui donner et il en fait des armures vraiment jolies.\n\nVous le trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 'Xanjo, il prend les peaux que Rana veut bien lui donner et il en fait des armures vraiment jolies.\n\nVous le trouverez sur la terrasse de l\’Artisanat, du côté ouest de Dazar\’alor.', 28153),
(159511, 'frFR', 'Notre Seshuli, elle fabrique les plus beaux bijoux des mers du Sud. Si vous voulez qu\’elle vous apprenne, il faut aller dans la salle des Scintillements.\n\nPassez par la terrasse de l\’Artisanat, tout en bas de la pyramide, côté ouest, puis prenez vers l\’est et suivez le tunnel qui s\’enfonce dans Dazar\’alor. Vous ne pouvez pas la rater, avec tous ces bijoux. Ça brille de partout, là-bas.', 'Notre Seshuli, elle fabrique les plus beaux bijoux des mers du Sud. Si vous voulez qu\’elle vous apprenne, il faut aller dans la salle des Scintillements.\n\nPassez par la terrasse de l\’Artisanat, tout en bas de la pyramide, côté ouest, puis prenez vers l\’est et suivez le tunnel qui s\’enfonce dans Dazar\’alor. Vous ne pouvez pas la rater, avec tous ces bijoux. Ça brille de partout, là-bas.', 28153),
(159509, 'frFR', '', 'Prenez mon hippogriffe et ralliez Darnassus. Assurez-vous que l\’occupation de la Horde est… supportable.', 28153),
(159506, 'frFR', 'Les chroniqueurs, ils roulent leur bosse pour percer à jour les mystères de notre monde. Kizani, c\’est elle qu\’il vous faut.\n\nVous la trouverez là-haut, au Grand Sceau, dans le hall des Chroniqueurs.', 'Les chroniqueurs, ils roulent leur bosse pour percer à jour les mystères de notre monde. Kizani, c\’est elle qu\’il vous faut.\n\nVous la trouverez là-haut, au Grand Sceau, dans le hall des Chroniqueurs.', 28153),
(159504, 'frFR', 'Jahden Fla, il s\’éloigne jamais de ses fleurs, sur la terrasse de l\’Artisanat. C\’est du côté ouest de Dazar\’alor.\n\nLui, quand il dit qu\’il a la main verte, il ne plaisante pas.', 'Jahden Fla, il s\’éloigne jamais de ses fleurs, sur la terrasse de l\’Artisanat. C\’est du côté ouest de Dazar\’alor.\n\nLui, quand il dit qu\’il a la main verte, il ne plaisante pas.', 28153),
(159503, 'frFR', 'La guerre met nos convictions et notre honneur à rude épreuve.\n\nJe suis venu à Zuldazar pour faire en sorte que ce conflit ne fasse pas perdre de vue à la Horde ce qui la définit. Ce qui fait sa force.\n\nJe sais que vous ne l\’oublierez pas ou vous ne seriez pas notre porte-parole.', '', 28153),
(159502, 'frFR', 'Je dois gagner en force !', '', 28153),
(159500, 'frFR', 'J\’espère que tout va bien pour vous, $p.', '', 28153),
(159499, 'frFR', 'Grâce à vous, je vais m\’entraîner dur pour devenir guerrier. Je tiens à être capable de défendre notre ville !', '', 28153),
(159498, 'frFR', 'Mamie me répète sans arrêt que je devrais suivre votre exemple…', '', 28153),
(159497, 'frFR', 'Je… je suis bien content que vous passiez par là.', '', 28153),
(159496, 'frFR', 'Vous voulez apprendre à pêcher ? Il faut voir ça avec Tali la Silencieuse. Elle pêche au Défilé, au nord de Dazar\’alor.\n\nTâchez de ne pas faire de bruit, vous risqueriez d\’effrayer le poisson.', 'Vous voulez apprendre à pêcher ? Il faut voir ça avec Tali la Silencieuse. Elle pêche au Défilé, au nord de Dazar\’alor.\n\nTâchez de ne pas faire de bruit, vous risqueriez d\’effrayer le poisson.', 28153),
(159495, 'frFR', 'Je ne veux pas décevoir ma grand-mère, mais je ne suis pas taillé pour tout ça… Je veux seulement que tout redevienne comme avant.', '', 28153),
(159494, 'frFR', 'Attention à la tête, il y a des pierres qui tombent du ciel !', '', 28153),
(159492, 'frFR', 'Il y a une Gobeline appelée Shuga qui enseigne ce genre de choses sur la terrasse de l\’Artisanat. C\’est du côté ouest, à l\’extérieur de Dazar\’alor.\n\nVous avez pas intérêt à faire sauter n\’importe quoi. Zuldazar, on l\’aime telle qu\’elle est.', 'Il y a une Gobeline appelée Shuga qui enseigne ce genre de choses sur la terrasse de l\’Artisanat. C\’est du côté ouest, à l\’extérieur de Dazar\’alor.\n\nVous avez pas intérêt à faire sauter n\’importe quoi. Zuldazar, on l\’aime telle qu\’elle est.', 28153),
(159491, 'frFR', 'Ils ont tué ma vache !', 'Ils ont tué ma vache !', 28153),
(159489, 'frFR', 'C\’est pas ma première bataille !', 'C\’est pas ma première bataille !', 28153),
(159488, 'frFR', 'Je ferai de mon mieux pour aider !', 'Je ferai de mon mieux pour aider !', 28153),
(159487, 'frFR', 'Laissez-moi les étriper !', 'Laissez-moi les étriper !', 28153),
(159486, 'frFR', 'Je vais leur donner une bonne raclée !', 'Je vais leur donner une bonne raclée !', 28153),
(159485, 'frFR', 'Ouais ! Ils vont le payer cher !', 'Ouais ! Ils vont le payer cher !', 28153),
(159484, 'frFR', 'Il faut voir ça avec l\’enchanteresse elfe de sang, Quinni. Rendez-vous du côté ouest, au pied de Dazar\’alor, sur la terrasse de l\’Artisanat. Une fois là-bas, mettez-vous face à la pyramide et descendez dans la salle des Scintillements.', 'Il faut voir ça avec l\’enchanteresse elfe de sang, Quinni. Rendez-vous du côté ouest, au pied de Dazar\’alor, sur la terrasse de l\’Artisanat. Une fois là-bas, mettez-vous face à la pyramide et descendez dans la salle des Scintillements.', 28153),
(159482, 'frFR', '', 'La succession d\’échecs dus aux Portvaillant prend fin ici !', 28153),
(159481, 'frFR', '', 'Ta famille a toujours été trop faible.', 28153),
(159480, 'frFR', '', 'J\’ai des preuves !', 28153),
(159479, 'frFR', '', 'J\’endosserai ce lourd fardeau. Je ne peux qu\’espérer être digne de vous succéder.', 28153),
(159478, 'frFR', 'La personne qu\’il vous faut, c\’est T\’sarah, la cuisinière du roi. Vous la trouverez dans Dazar\’alor, aux Grillades du Roi près du Grand Sceau.', 'La personne qu\’il vous faut, c\’est T\’sarah, la cuisinière du roi. Vous la trouverez dans Dazar\’alor, aux Grillades du Roi près du Grand Sceau.', 28153),
(159476, 'frFR', '', 'Ma chère amie Priscilla et moi en avons discuté. Je pense que le mieux pour Kul Tiras est que je cède ma place d\’amiral suprême…', 28153),
(159475, 'frFR', '', 'Katherine Portvaillant a dédié sa vie au bien de Kul Tiras.', 28153),
(159473, 'frFR', 'Crève, charogne de la Horde !', 'Crève, charogne de la Horde !', 28153),
(159472, 'frFR', 'Je vous renverrai à votre chef de guerre en mille morceaux !', 'Je vous renverrai à votre chef de guerre en mille morceaux !', 28153),
(159471, 'frFR', 'Vous ne nous vaincrez jamais !', 'Vous ne nous vaincrez jamais !', 28153),
(159470, 'frFR', 'Boralus ne tombera pas !', 'Boralus ne tombera pas !', 28153),
(159469, 'frFR', 'Pour Boralus !', 'Pour Boralus !', 28153),
(159468, 'frFR', 'Tenez-vous bien, $p. Vol-au-Vent va nous conduire à destination en un rien de temps.', '', 28153),
(159467, 'frFR', '', 'Le frisson de la chasse… Il n\’y a que ça de vrai.', 28153),
(159466, 'frFR', '', 'Pa\’ku regarde Kua\’fon en soupirant.', 28153),
(159465, 'frFR', 'C\’est reparti, Vol-au-Vent ! Le ciel nous appelle !', '', 28153),
(159464, 'frFR', 'Fermeture', 'Fermeture', 28153),
(159463, 'frFR', 'Nous devons IMPÉRATIVEMENT envoyer la commande de tir depuis une position ayant une vue directe sur l\’ensemble des explosifs. Malheureusement, j\’ai besoin de vérifier manuellement tous les paramètres, et cela ne peut se faire ailleurs qu\’ici.\n\nVous préférez la version courte ? Soit : montez à bord de la machine volante et appuyez sur le gros bouton rouge quand je vous le dirai.', '', 28153),
(159462, 'frFR', '', 'Vous posez trop de questions. En avant !', 28153),
(159461, 'frFR', 'Empreints de Lumière ?', '', 28153),
(159460, 'frFR', '', 'Ma mère dirige une garnison en Nagrand. Mon père est tombé au combat contre les empreints de Lumière.', 28153),
(159459, 'frFR', 'Vous êtes la fille de Durotan et de Draka. Je vois leurs traits en vous. Vos parents sont-ils…', '', 28153),
(159458, 'frFR', '', 'Je n\’ai nul besoin de leur aide… mais j\’obéirai à vos ordres. Venez !', 28153),
(159457, 'frFR', 'Eitrigg et $n vous aideront à juguler la menace ogre, Geya\’rah.', '', 28153),
(159456, 'frFR', 'Durotan avait une dette envers ces héros, Geya\’rah, et moi aussi. Par cette explosion de colère, c\’est l\’esprit de votre père que vous déshonorez. Toutefois… cela me donne une idée…', '', 28153),
(159455, 'frFR', '', 'Vous nous prenez pour des imbéciles ? Chef de guerre, nous ne pouvons pas confier nos soldats à ces étrangers. Nous devons faire face à nos propres ennemis !', 28153),
(159454, 'frFR', 'Des héros venus de mon monde ont jadis libéré le vôtre d\’un joug tyrannique. Aujourd\’hui, une menace similaire plane sur Azeroth. Nous sommes venus demander le remboursement d\’une vieille dette.', '', 28153),
(159453, 'frFR', 'Ainsi nous voilà… deux revenants. Pourquoi avoir fait tout ce chemin jusque sur Draenor après tout ce temps ?', '', 28153),
(159452, 'frFR', 'Quant au Grommash Hurlenfer que j\’ai connu, il a donné sa vie pour nous libérer de l\’emprise des démons. Une mort honorable, s\’il en est.', '', 28153),
(159451, 'frFR', 'Eitrigg… J\’ai connu un Eitrigg au service de Main-Noire. Un Orc honorable tombé au champ d\’honneur.', '', 28153),
(159450, 'frFR', 'Oui. Je suis Eitrigg et voici $n. La Horde lui porte une grande estime.', '', 28153),
(159449, 'frFR', 'Voilà bien longtemps que je n\’avais plus revu un Orc à la peau verte. Et cette personne à vos côtés… son visage m\’est familier. Vous venez d\’Azeroth.', '', 28153),
(159448, 'frFR', 'Ça suffit ! Je déciderai moi-même du sort des prisonniers, Geya\’rah.', '', 28153),
(159447, 'frFR', '', 'Vos paroles ont fait mouche, vieil Orc. Même unis sous la bannière des Mag\’har, nous continuons à honorer l\’histoire de nos clans. Mais il vous reste à prouver…', 28153),
(159446, 'frFR', 'Durotan était à la tête des Loups-de-Givre. Je n\’ai jamais connu d\’Orc plus honorable. C\’était un meneur dans l\’âme, prêt à tout sacrifier pour les siens. Sa sagesse me manque.', '', 28153),
(159445, 'frFR', 'Le clan Chanteguerre a lutté contre les Ogres des générations durant. Grommash Hurlenfer est parvenu à mener les siens à une grande victoire, malgré la supériorité numérique des brutes de Cognefort.', '', 28153),
(159444, 'frFR', 'Les Rochenoires… mon propre clan. Nous étions des Orcs fiers, de redoutables guerriers. Mais la magie gangrenée de Gul\’dan nous a trompés et poussés à commettre… des atrocités.', '', 28153),
(159443, 'frFR', '', 'Tout Orc qui se respecte connaît les trois bannières de ce camp. Donnez-m\’en la signification, ou je fais trancher vos deux têtes !', 28153),
(159442, 'frFR', '', 'Il n\’existe qu\’un seul chef de guerre… et vous n\’êtes pas des Rochenoires ! Je vais d\’ailleurs le prouver.', 28153),
(159441, 'frFR', 'Je suis Eitrigg, du clan Rochenoire. Nous venons d\’Azeroth, au nom de notre chef de guerre.', '', 28153),
(159440, 'frFR', '', 'Nous verrons cela. Parlez, intrus. Qui êtes-vous ?', 28153),
(159439, 'frFR', 'Ce sont des espions empreints de Lumière ! De sales traîtres !', 'Ce sont des espions empreints de Lumière ! De sales traîtres !', 28153),
(159438, 'frFR', '', 'Amenez-les-moi.', 28153),
(159437, 'frFR', 'Commandant Geya\’rah ! Nous avons des prisonniers !', '', 28153),
(159436, 'frFR', 'Le commandant saura quoi faire.', 'Le commandant saura quoi faire.', 28153),
(159435, 'frFR', 'Méfiez-vous. Pour ce que nous en savons, ils pourraient être des espions à la solde des Draeneï.', '', 28153),
(159434, 'frFR', 'Cette peau verte… c\’est écœurant ! J\’avais entendu parler de cette corruption, mais c\’est la première fois que je la vois de mes propres yeux.', 'Cette peau verte… c\’est écœurant ! J\’avais entendu parler de cette corruption, mais c\’est la première fois que je la vois de mes propres yeux.', 28153),
(159433, 'frFR', 'Silence ! Le commandant décidera de votre sort. Enchaînez-les !', '', 28153),
(159432, 'frFR', 'Calmez-vous ! Nous venons en paix. Nous souhaitons parler à votre chef de guerre.', '', 28153),
(159431, 'frFR', 'Des intrus !', 'Des intrus !', 28153),
(159430, 'frFR', 'Pourquoi vous voulez fouiner dans nos terres ? Enfin, si vous y tenez, c\’est l\’examinatrice Alerinda qu\’il vous faut. Vous la trouverez dans le Grand Sceau.', 'Pourquoi vous voulez fouiner dans nos terres ? Enfin, si vous y tenez, c\’est l\’examinatrice Alerinda qu\’il vous faut. Vous la trouverez dans le Grand Sceau.', 28153),
(159429, 'frFR', 'Archéologie', 'Archéologie', 28153),
(159428, 'frFR', 'Qu\’est-ce que ce vaudou du Vide fait ici ?', 'Qu\’est-ce que ce vaudou du Vide fait ici ?', 28153),
(159427, 'frFR', 'Quel est donc ce vaudou ?', 'Quel est donc ce vaudou ?', 28153),
(159426, 'frFR', 'Qu\’est-ce que c\’est que ce vaudou noir ?', 'Qu\’est-ce que c\’est que ce vaudou noir ?', 28153),
(159425, 'frFR', 'Allez-y. Mais veillez à ne pas vous égarer dans les entrelacs des fils du destin.', '', 28153),
(159424, 'frFR', 'L\’éclat vous accompagnera. Le moment venu, il vous permettra d\’emprunter le chemin du retour.', '', 28153),
(159423, 'frFR', 'Vous pouvez garder le passage ouvert suffisamment longtemps pour qu\’on fasse passer les Orcs de Draenor ?', '', 28153),
(159422, 'frFR', 'Les flots du temps et de la réalité changent en permanence. Le lien avec le monde que vous recherchez sera ténu.', '', 28153),
(159421, 'frFR', 'Comment puis-je me rendre à Orgrimmar ?', 'Comment puis-je me rendre à Orgrimmar ?', 28153),
(159420, 'frFR', 'Notre combat ici est terminé, mais la guerre, elle continue.', '', 28153),
(159419, 'frFR', 'Le chef de guerre ne voudra entendre aucune excuse. $p va devoir se rendre en Tanaris. Moi, mes vieux os ont besoin de repos.', '', 28153),
(159418, 'frFR', 'Ce serait possible si ce fragment n\’était pas appauvri. Mais ma spécialité, c\’est la téléportation, pas la chronomancie.', '', 28153),
(159417, 'frFR', 'Il faut que vous alliez à la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nLe maître-forge Zak\’aal, c\’est le meilleur forgeron d\’Azeroth !', 'Il faut que vous alliez à la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nLe maître-forge Zak\’aal, c\’est le meilleur forgeron d\’Azeroth !', 28153),
(159416, 'frFR', '', 'Les animaux sauvages sont incroyables par ici. Krag\’wa n\’étant pas loin, je me demande si c\’est la présence d\’un Loa qui les renforce. Qu\’est-ce que vous diriez d\’un petit combat de mascottes ?', 28153),
(159415, 'frFR', '', 'Pa\’ku pousse un petit rire inquiétant.', 28153),
(159414, 'frFR', 'Quel soulagement !', 'Quel soulagement !', 28153),
(159413, 'frFR', 'La douleur a disparu !', 'La douleur a disparu !', 28153),
(159412, 'frFR', 'Je me sens tellement mieux !', 'Je me sens tellement mieux !', 28153),
(159411, 'frFR', 'C\’est un honneur pour moi, général. $p, montez sur Vol-au-Vent dès que vous voudrez y aller.', '', 28153),
(159410, 'frFR', '', 'Partez devant avec $p, Falstad. Je monterai Jai\’alator.', 28153),
(159409, 'frFR', 'Ah… je vois. Même s\’il peut pas s\’élever parmi les nuages, je sais qu\’avec vous, $n, il vivra heureux.', '', 28153),
(159408, 'frFR', 'On va ouvrir la voie. Faites-lui confiance et tout se passera bien. Allez, on décolle !', '', 28153),
(159407, 'frFR', 'Vous inquiétez pas ! Il s\’en sortira. J\’ai un plan.', '', 28153),
(159405, 'frFR', 'Kumali l\’Astucieuse, elle concocte toutes sortes de mojos sur la terrasse de l\’Artisanat. Au pied de Dazar\’alor, côté ouest, c\’est là-bas que vous la trouverez.', 'Kumali l\’Astucieuse, elle concocte toutes sortes de mojos sur la terrasse de l\’Artisanat. Au pied de Dazar\’alor, côté ouest, c\’est là-bas que vous la trouverez.', 28153),
(159404, 'frFR', 'Étant donné que les membres de la Horde font appel à nos irréprochables services depuis si longtemps, nous avons décidé de proposer des portails de mage aux personnalités éminentes comme vous-même. Je vous garantis que le voyage sera presque indolore.', 'Étant donné que les membres de la Horde font appel à nos irréprochables services depuis si longtemps, nous avons décidé de proposer des portails de mage aux personnalités éminentes comme vous-même. Je vous garantis que le voyage sera presque indolore.', 28153),
(159403, 'frFR', '', 'Ha ha ha ha !', 28153),
(159402, 'frFR', '', 'Que les vents vous portent !', 28153),
(159401, 'frFR', 'Comment puis-je me rendre aux clairières de Tirisfal ?', 'Comment puis-je me rendre aux clairières de Tirisfal ?', 28153),
(159399, 'frFR', 'Le Mande-Tonnerre a connu un énième incendie et est en cours de maintenance. C\’est vraiment regrettable.', '', 28153),
(159398, 'frFR', 'Oui, Pa\’ku.', 'Oui, Pa\’ku.', 28153),
(159397, 'frFR', 'Les meilleurs maîtres de métier, ils sont ici, à Zuldazar. Vous les trouverez sur la terrasse de l\’Artisanat, dans la partie inférieure de Dazar\’alor, côté ouest.\n\nVous cherchez quelqu\’un en particulier ?', 'Les meilleurs maîtres de métier, ils sont ici, à Zuldazar. Vous les trouverez sur la terrasse de l\’Artisanat, dans la partie inférieure de Dazar\’alor, côté ouest.\n\nVous cherchez quelqu\’un en particulier ?', 28153),
(159396, 'frFR', '', 'Aaah, je vous attendais. La dernière leçon de votre jeune compagnon ne date pas d\’hier.\n\nVenez, voyons ce qu\’il a appris, depuis le temps.', 28153),
(159395, 'frFR', 'Maîtres', 'Maîtres', 28153),
(159394, 'frFR', 'Des familiers ? Les seuls compagnons qui vaillent le coup, c\’est les enfants d\’un Loa.\n\nAllez plutôt voir l\’éleveur de bêtes Kalatak, tout en bas de Dazar\’alor, au nord-ouest.', 'Des familiers ? Les seuls compagnons qui vaillent le coup, c\’est les enfants d\’un Loa.\n\nAllez plutôt voir l\’éleveur de bêtes Kalatak, tout en bas de Dazar\’alor, au nord-ouest.', 28153),
(159392, 'frFR', 'Si vous obéissez au roi Rastakhan, Natal\’hakata aura peut-être quelque chose pour vous dans le Grand Sceau.', 'Si vous obéissez au roi Rastakhan, Natal\’hakata aura peut-être quelque chose pour vous dans le Grand Sceau.', 28153),
(159391, 'frFR', 'Émissaires', 'Émissaires', 28153),
(159390, 'frFR', '', 'Tirisfal a vu de grandes puissances s\’ériger puis s\’effondrer. Pensez-vous que… ceux de votre espèce tireront un jour les leçons de leur histoire ?\n\nMais je m\’égare.\n\nEn avez-vous terminé avec le passé ?', 28153),
(159389, 'frFR', '', 'Teldrassil… Une splendeur, n\’est-ce pas ? Mais la beauté est éphémère.\n\nEn particulier lorsque des mortels décident d\’y mettre le feu.\n\nEn avez-vous fini de votre mission dans le passé ?', 28153),
(159388, 'frFR', 'Un cadavre qui se trémousse, moi, ça me reste sur l\’estomac. Enfin, si ça vous intéresse, elle est dans le Grand Sceau.', 'Un cadavre qui se trémousse, moi, ça me reste sur l\’estomac. Enfin, si ça vous intéresse, elle est dans le Grand Sceau.', 28153),
(159386, 'frFR', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis commence à lancer |cFFFF0000|Hspell:267242|h[Contagion]|h|r !', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis commence à lancer |cFFFF0000|Hspell:267242|h[Contagion]|h|r !', 28153),
(159385, 'frFR', 'Toutes les demandes de logement seront traitées au cas par cas.', '', 28153),
(159384, 'frFR', '', 'Depuis ces rivages, vous pouvez admirer Teldrassil. Autrefois berceau de la vie, ce n\’est plus aujourd\’hui qu\’une désolation de flammes et de cendres.\n\nMême les Arbres-Mondes n\’échappent pas au cycle de la vie. Tout ce qui naît meurt un jour.\n\nNul n\’en a plus conscience que le Vol draconique de bronze.\n\nVoulez-vous voir l\’arbre dans toute sa splendeur ?', 28153),
(159383, 'frFR', 'Malheureusement, nos ressources sont limitées pour l\’instant.', '', 28153),
(159382, 'frFR', 'Paku\’ai, vous la trouverez sur la corniche, devant le Grand Sceau. Où est-ce que vous allez ?', 'Paku\’ai, vous la trouverez sur la corniche, devant le Grand Sceau. Où est-ce que vous allez ?', 28153),
(159381, 'frFR', 'Soyez patients. Nous faisons tout ce que nous pouvons, étant donné les circonstances.', '', 28153),
(159379, 'frFR', '', 'Tirisfal… une contrée de splendeur et de ténèbres. Aujourd\’hui accablée par le désespoir… et les esprits défunts.\n\nCeux de votre espèce ont, me semble-t-il, tenté de s\’en emparer à maintes reprises.\n\nSouhaitez-vous voir cette région telle qu\’elle était avant la dernière guerre ?', 28153),
(159378, 'frFR', 'Je commençais à en avoir assez de la chèvre.', '', 28153),
(159377, 'frFR', 'Des volontaires ?', '', 28153),
(159376, 'frFR', 'On peut vous conduire là-bas avec une petite escouade en un rien de temps.', '', 28153),
(159375, 'frFR', '<Falstad Marteau-Hardi siffle, et des chevaucheurs de griffons se posent sur le pont quelques instants plus tard.>', '', 28153),
(159374, 'frFR', 'Votre navire se traîne trop pour arriver là-bas à temps. Heureusement, la vitesse a jamais été un problème pour les Marteaux-Hardis.', '', 28153),
(159373, 'frFR', 'Si Dreven se trouve à bord de ce bateau, il n\’a aucune chance de nous échapper… pour peu que nous frappions avant qu\’ils n\’atteignent la terre ferme.', '', 28153),
(159372, 'frFR', '', 'J\’ai appris au cours de ma chasse que le prince de sang Dreven voyage à bord d\’un bateau en compagnie d\’un méprisable eaurage.', 28153),
(159371, 'frFR', '', 'Au contraire, je crois que cette affaire est une priorité absolue. Merci Mathias.', 28153),
(159370, 'frFR', '', 'Shandris Pennelune vient se poser le pont à dos d\’hippogriffe.', 28153),
(159369, 'frFR', 'Nous n\’en sommes pas sûrs, mais je peux envoyer des agents voir ce qu\’ils manigancent. Inutile de nous focaliser là-dessus.', '', 28153),
(159368, 'frFR', 'Qu\’est-ce que la Horde peut bien chercher à bord de vieilles épaves ?', '', 28153),
(159367, 'frFR', 'Merci, Mathias.', '', 28153),
(159366, 'frFR', 'Nous avons bien sûr fait en sorte que le document original arrive apparemment intact à destination, mais nous en avons réalisé une copie à votre intention.', '', 28153),
(159365, 'frFR', 'Haut-commandant, mes agents ont intercepté des ordres en provenance de Sylvanas.', '', 28153),
(159364, 'frFR', 'Mon peuple ne fera pas la même erreur en utilisant le Vide, je vous le promets.', '', 28153),
(159363, 'frFR', '', 'Comme vous l\’avez dit, Umbric, je vis depuis bien longtemps. J\’ai vu le pouvoir corrompre la plus noble des races… Rares sont ceux qui ont fait preuve de retenue.', 28153),
(159362, 'frFR', 'Pourquoi cet air surpris ? Vous imaginiez que mon peuple utilisait la magie du Vide comme un simple jouet ?', '', 28153),
(159361, 'frFR', '', 'Des fins défensives ? Voilà qui est intéressant, Umbric.', 28153),
(159360, 'frFR', 'Le Vide peut être employé à des fins défensives, tant qu\’on ne succombe pas à son pouvoir.', '', 28153),
(159359, 'frFR', '', 'Et vous ne semblez pas hésiter à utiliser les pouvoirs du Vide contre eux.', 28153),
(159358, 'frFR', 'Vous et moi avons vu le jour il y a fort longtemps, Shandris. Je connais beaucoup de gens qui ont dû subir la barbarie des Zandalari.', '', 28153),
(159357, 'frFR', '', 'On dirait que vous avez déjà eu affaire aux Zandalari par le passé.', 28153),
(159356, 'frFR', 'Mon peuple et moi ne laisserons pas ces ignobles Trolls anéantir l\’Alliance. Je vous en donne ma parole.', '', 28153),
(159355, 'frFR', '', 'Je ne m\’attendais pas à trouver autant de gardes dans ce port. La flotte doit se préparer à lever l\’ancre.', 28153),
(159354, 'frFR', '', 'Il va falloir en informer Halford dès qu\’on aura déposé $n.', 28153),
(159353, 'frFR', 'Ça pourrait le devenir, vu qu\’il va passer à quelques encablures de notre avant-poste à Xibala.', '', 28153),
(159352, 'frFR', '', 'Un seul navire ? Ça n\’a pas l\’air si grave.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159351, 'frFR', 'On a un problème. Il y a un navire de plus que prévu. Il était peut-être stationné en Pandarie.', '', 28153),
(159350, 'frFR', 'Voyons. Il semble que les renseignements de Halford sur la position de la plupart des navires, ainsi que sur leurs routes de navigation, étaient bons. Cependant…', '', 28153),
(159349, 'frFR', '', 'Je n\’aime pas fouiner, d\’habitude… mais je peux faire une exception pour cette fois. Voyons voir…', 28153),
(159348, 'frFR', 'Les documents récupérés par $n ont-ils livré de nouveaux renseignements ?', '', 28153),
(159347, 'frFR', '', 'Bonne chance ! Le port de guerre Rastari va grouiller de Zandalari. Mais je suis sûre que Shandris a un plan.', 28153),
(159346, 'frFR', 'Si vous avez envie de changer de tête, il faut aller voir les Gobelins bizarres au Grand bazar, près du port.', 'Si vous avez envie de changer de tête, il faut aller voir les Gobelins bizarres au Grand bazar, près du port.', 28153),
(159343, 'frFR', 'Par ici, ça grouille de toutes sortes de bestioles étranges. Sûr, on trouve des lapins, des écureuils ou des castors tout à fait normaux, mais il y a aussi ces drôles de créatures… un genre de fagots de branches ambulants. Il m\’a fallu des jours, mais j\’ai fini par en capturer un pour le dresser. Et du coup, c\’est devenu un bon compagnon. Bon, ça vous empêchera pas de crier quand il vous enfoncera ses extrémités pointues dans le lard, mais je le trouve plutôt sympa. Vous voulez le voir à l\’œuvre ?', '', 28153),
(159342, 'frFR', 'Le Trésor royal, il est au milieu de la pyramide, près du Grand Sceau.', 'Le Trésor royal, il est au milieu de la pyramide, près du Grand Sceau.', 28153),
(159340, 'frFR', 'Il est temps d\’aller poser des bombes… sans les faire exploser. Pour l\’instant, du moins.', '', 28153),
(159339, 'frFR', '', 'Tais-toi, Flynn. Nous ne pouvons pas perdre espoir. Jaina est sûrement en vie !', 28153),
(159338, 'frFR', '$n, veuillez faire part de mes sincères condoléances à dame Katherine.', '', 28153),
(159337, 'frFR', 'Funesterre… Il n\’y a pas pire endroit pour mourir.', '', 28153),
(159336, 'frFR', 'Allez, on joue !', 'Allez, on joue !', 28153),
(159335, 'frFR', 'Prenez leurs trésors tout brillants !', 'Prenez leurs trésors tout brillants !', 28153),
(159334, 'frFR', 'Ooh, vous avez de jolies choses toutes brillantes !', 'Ooh, vous avez de jolies choses toutes brillantes !', 28153),
(159333, 'frFR', 'Venez jouer avec nous !', 'Venez jouer avec nous !', 28153),
(159332, 'frFR', 'Ha ha ha !', 'Ha ha ha !', 28153),
(159331, 'frFR', 'Tout droit dans le piège !', 'Tout droit dans le piège !', 28153),
(159330, 'frFR', 'Je vous tiens !', 'Je vous tiens !', 28153),
(159329, 'frFR', 'Hé hé hé !', 'Hé hé hé !', 28153),
(159228, 'frFR', '', 'Soyez prudents. J\’attendrai votre signal !', 28153),
(159227, 'frFR', 'Quand vous aurez fini, retrouvez-moi à Port-Liberté.', '', 28153),
(159226, 'frFR', 'Trouvez des grenades. Je vais aller parler de son oiseau à un cadet…', '', 28153),
(159225, 'frFR', 'Même en lisant entre les lignes, je ne vois rien qui indiquerait sa destination. Mais je pense savoir où dénicher cette information.', '', 28153),
(159224, 'frFR', 'Règle numéro un : toujours bien lire les clauses…', '', 28153),
(159223, 'frFR', 'Dame Katherine vous a demandé de retrouver sa fille, hein ? Eh bien, voyons si ce contrat indique où elle a été envoyée.', '', 28153),
(159222, 'frFR', 'Bon sang ! Où Jaina devait-elle être « expédiée » ?', '', 28153),
(159221, 'frFR', 'Des définitions, des conditions d\’application, du charabia juridique qui ne tromperait jamais un juge intègre…', '', 28153),
(159220, 'frFR', 'Dix pages de mesures de sécurité… Vingt pages de dénonciation de responsabilité…', '', 28153),
(159219, 'frFR', 'La mission du prestataire de services, dit « le transporteur », consiste à… Blah, blah, blah…', '', 28153),
(159218, 'frFR', 'Le présent contrat est conclu entre la compagnie Corsandre et… Pouah, qui a écrit ce truc ?', '', 28153),
(159217, 'frFR', '', 'Franchissez le mur, vite ! Je ne tiendrai plus très longtemps !', 28153),
(159216, 'frFR', 'Dame Katherine m\’a demandé de chercher sa fille. Voici le seul indice que j\’ai trouvé jusqu\’à présent.', 'Dame Katherine m\’a demandé de chercher sa fille. Voici le seul indice que j\’ai trouvé jusqu\’à présent.', 28153),
(159215, 'frFR', 'Salut, $n. Content de vous revoir.', '', 28153),
(159214, 'frFR', '', 'Revenez me voir dès que vous saurez où se trouve Jaina, $n.', 28153),
(159213, 'frFR', '', 'J\’espère que vous avez raison, Genn.', 28153),
(159212, 'frFR', 'Ce héraut est l\’un des plus fiers combattants de l\’Alliance, Katherine. Personne n\’est plus à même de retrouver Jaina.', '', 28153),
(159211, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Vous subissez |cFFFF0000|Hspell:265129|h[Vecteur Oméga]|h|r !', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Vous subissez |cFFFF0000|Hspell:265129|h[Vecteur Oméga]|h|r !', 28153),
(159210, 'frFR', 'Attendez ! Utilisez le charme de contrôle !', '', 28153),
(159209, 'frFR', 'C\’est ici que vous descendez. Restez sur vos gardes pendant que vous poserez les bombes, et ne les laissez pas avertir le continent de votre présence !', '', 28153),
(159208, 'frFR', 'Voilà qui marque peut-être le début d\’une belle amitié.', '', 28153),
(159207, 'frFR', '', 'Une ? Non, non, j\’ai PLUSIEURS collections de couteaux.', 28153),
(159206, 'frFR', 'Vous avez une collection de couteaux ?', '', 28153),
(159205, 'frFR', '', 'Enfin un homme comme je les aime. Il faudra qu\’on compare nos collections de couteaux après ça, Keeshan.', 28153),
(159204, 'frFR', 'Je vais aider $n en posant les bombes de Kelsey sur les plus petits bateaux… et éventrer les Zandalari qui me repéreront.', '', 28153),
(159203, 'frFR', '', 'De mon côté, je vais bricoler un appareil qui permettra à $n de marcher sur l\’eau pour la prochaine étape de ce plan.', 28153),
(159202, 'frFR', 'Assurez-vous juste qu\’ils ne vous voient pas poser ces bombes sur leurs vaisseaux.', '', 28153),
(159201, 'frFR', 'Inutile de me le dire deux fois. Je vais tous vous déposer sur l\’île du Croc. C\’est assez loin de la ville pour vous permettre d\’agir en toute impunité contre les Zandalari.', '', 28153),
(159200, 'frFR', 'J\’ai failli me faire manger, une fois. C\’est une expérience que je ne recommande pas.', '', 28153),
(159199, 'frFR', '', 'Ils nous donneraient à manger à leurs dinosaures de compagnie. On finirait réduits en bouillie.', 28153),
(159198, 'frFR', 'Ouais. Repérer une poignée de soldats, comme $n par exemple, c\’est une chose. Mais tout le foutu campement ?', '', 28153),
(159197, 'frFR', '', 'Pourquoi pensez-vous que Halford se démène autant ? Il sait que nous sommes condamnés si les Zandalari nous surprennent sur leur territoire.', 28153),
(159196, 'frFR', 'Ce camp de l\’Alliance se voit comme le nez au milieu de la figure. Les Zandalari nous découvriront tôt ou tard, alors préparons-nous à les recevoir.', '', 28153),
(159195, 'frFR', 'Voilà ! On devrait être assez haut pour échapper à la surveillance des Zandalari.', '', 28153),
(159194, 'frFR', 'Accrochez-vous bien. On va devoir voler vraiment haut pour éviter de se faire repérer !', '', 28153),
(159193, 'frFR', '', 'Ma porte vous est toujours ouverte, $p.', 28153),
(159192, 'frFR', '', 'Vous devriez mettre une petite laine. Vous allez finir par attraper la mort, si ça continue !', 28153),
(159191, 'frFR', '', 'Pensez à vous reposer, de temps en temps. Les monstres attendront !', 28153),
(159190, 'frFR', 'Parlons de notre plan pour affaiblir la flotte zandalari.', 'Parlons de notre plan pour affaiblir la flotte zandalari.', 28153),
(159189, 'frFR', 'Comment osez-vous ?!', 'Comment osez-vous ?!', 28153),
(159188, 'frFR', 'La marée écrasante… approche…', 'La marée écrasante… approche…', 28153),
(159187, 'frFR', 'Les ténèbres… se lèveront…', 'Les ténèbres… se lèveront…', 28153),
(159186, 'frFR', 'Quelle… impertinence…', 'Quelle… impertinence…', 28153),
(159185, 'frFR', 'Nous avons des milliers d\’assemblages… vous ne pouvez pas gagner…', 'Nous avons des milliers d\’assemblages… vous ne pouvez pas gagner…', 28153),
(159184, 'frFR', 'Mon esprit… reviendra…', 'Mon esprit… reviendra…', 28153),
(159183, 'frFR', 'Ma mort n\’arrêtera rien…', 'Ma mort n\’arrêtera rien…', 28153),
(159182, 'frFR', 'Nous… reconstruirons.', 'Nous… reconstruirons.', 28153),
(159181, 'frFR', 'La mort n\’est que le début de votre châtiment !', 'La mort n\’est que le début de votre châtiment !', 28153),
(159180, 'frFR', '', 'Oh, bien le bonjour ! Pourriez-vous me rendre un ou deux petits services ? Du moment que cela ne vous dérange pas, bien sûr !', 28153),
(159179, 'frFR', 'Votre destin est scellé, imbécile !', 'Votre destin est scellé, imbécile !', 28153),
(159178, 'frFR', 'Soumettez-vous !', 'Soumettez-vous !', 28153),
(159177, 'frFR', 'Vous allez connaître une mort lente !', 'Vous allez connaître une mort lente !', 28153),
(159176, 'frFR', 'Nous étions là bien avant votre espèce, et nous vous survivrons !', 'Nous étions là bien avant votre espèce, et nous vous survivrons !', 28153),
(159175, 'frFR', 'Insolente créature de chair !', 'Insolente créature de chair !', 28153),
(159174, 'frFR', 'Vous apprendrez à respecter ceux qui vous sont supérieurs !', 'Vous apprendrez à respecter ceux qui vous sont supérieurs !', 28153),
(159173, 'frFR', 'Les faibles n\’ont pas de place en ce monde !', 'Les faibles n\’ont pas de place en ce monde !', 28153),
(159172, 'frFR', 'Ce qui est mort… ne peut mourir…', 'Ce qui est mort… ne peut mourir…', 28153),
(159171, 'frFR', 'Je lui reviens, ne serait-ce que pour un bref instant…', 'Je lui reviens, ne serait-ce que pour un bref instant…', 28153),
(159170, 'frFR', 'Nous ne serons pas submergés par l\’oubli…', 'Nous ne serons pas submergés par l\’oubli…', 28153),
(159169, 'frFR', 'Elle nous libérera de ce tourment…', 'Elle nous libérera de ce tourment…', 28153),
(159168, 'frFR', 'Le liquide est à elle… vous ne pouvez pas tous nous arrêter…', 'Le liquide est à elle… vous ne pouvez pas tous nous arrêter…', 28153),
(159167, 'frFR', 'Nous sommes éternels… votre victoire est vaine…', 'Nous sommes éternels… votre victoire est vaine…', 28153),
(159166, 'frFR', 'Elle me relèvera…', 'Elle me relèvera…', 28153),
(159165, 'frFR', 'De simples mortels… ne peuvent nous tuer…', 'De simples mortels… ne peuvent nous tuer…', 28153),
(159164, 'frFR', 'Je vais ravir le souffle de vos poumons !', 'Je vais ravir le souffle de vos poumons !', 28153),
(159163, 'frFR', 'Ces eaux nous appartiennent !', 'Ces eaux nous appartiennent !', 28153),
(159162, 'frFR', 'Vos os fragiles éclateront sous le poids des abysses !', 'Vos os fragiles éclateront sous le poids des abysses !', 28153),
(159161, 'frFR', 'Les marées vous prendront !', 'Les marées vous prendront !', 28153),
(159160, 'frFR', 'Helya vous appelle !', 'Helya vous appelle !', 28153),
(159159, 'frFR', 'Vos âmes seront bientôt à nous !', 'Vos âmes seront bientôt à nous !', 28153),
(159158, 'frFR', 'À votre mort, vous rejoindrez nos rangs et son armée !', 'À votre mort, vous rejoindrez nos rangs et son armée !', 28153),
(159157, 'frFR', 'Les brumes vous emporteront !', 'Les brumes vous emporteront !', 28153),
(159156, 'frFR', 'Vous ne dominerez jamais les mers…', 'Vous ne dominerez jamais les mers…', 28153),
(159155, 'frFR', 'L\’un tombe, des milliers demeurent…', 'L\’une tombe, des milliers demeurent…', 28153),
(159154, 'frFR', 'N\’allez pas vous imaginer avoir gagné…', 'N\’allez pas vous imaginer avoir gagné…', 28153),
(159153, 'frFR', 'Votre destin… est scellé…', 'Votre destin… est scellé…', 28153),
(159152, 'frFR', 'La mort vous attend…', 'La mort vous attend…', 28153),
(159151, 'frFR', 'Azshara… est tout…', 'Azshara… est tout…', 28153),
(159150, 'frFR', 'Ô Azshara… je reviens aux vagues…', 'Ô Azshara… je reviens aux vagues…', 28153),
(159149, 'frFR', 'Ma reine…', 'Ma reine…', 28153),
(159148, 'frFR', 'Le dieu des profondeurs vous attend et frémit d\’anticipation !', 'Le dieu des profondeurs vous attend et frémit d\’anticipation !', 28153),
(159147, 'frFR', 'Les yeux des profondeurs vous conduiront à la folie !', 'Les yeux des profondeurs vous conduiront à la folie !', 28153),
(159146, 'frFR', 'Vous sentez la peur vous submerger ? La terreur sans fond des profondeurs ?', 'Vous sentez la peur vous submerger ? La terreur sans fond des profondeurs ?', 28153),
(159145, 'frFR', 'L\’Empire noir illuminera à nouveau ce monde, son âme nourrira les puissances !', 'L\’Empire noir illuminera à nouveau ce monde, son âme nourrira les puissances !', 28153),
(159144, 'frFR', 'Nous attendons depuis trop longtemps, l\’ère des Nagas est arrivée !', 'Nous attendons depuis trop longtemps, l\’ère des Nagas est arrivée !', 28153),
(159143, 'frFR', 'La cité engloutie se relèvera, le signe de votre perte !', 'La cité engloutie se relèvera, le signe de votre perte !', 28153),
(159142, 'frFR', 'N\’zoth nous appelle tous, vous ne l\’entendez pas ?', 'N\’zoth nous appelle tous, vous ne l\’entendez pas ?', 28153),
(159141, 'frFR', 'Au nom de la grande reine Azshara ! Puisse son règne être long et prospère !', 'Au nom de la grande reine Azshara ! Puisse son règne être long et prospère !', 28153),
(159140, 'frFR', 'Votre vie touche à sa fin !', 'Votre vie touche à sa fin !', 28153),
(159139, 'frFR', 'Des profondeurs, nous jaillissons !', 'Des profondeurs, nous jaillissons !', 28153),
(159138, 'frFR', 'Tuez-les tous !', 'Tuez-les tous !', 28153),
(159137, 'frFR', 'Vous vous noierez dans le malheur !', 'Vous vous noierez dans le malheur !', 28153),
(159136, 'frFR', 'Le frémissant chante pour nous !', 'Le frémissant chante pour nous !', 28153),
(159135, 'frFR', 'Les profondeurs murmurent votre nom !', 'Les profondeurs murmurent votre nom !', 28153),
(159134, 'frFR', 'Pour Azshara !', 'Pour Azshara !', 28153),
(159133, 'frFR', 'Retournez ramper dans votre antre, vermine !', 'Retournez ramper dans votre antre, vermine !', 28153),
(159132, 'frFR', 'Détection de la malédiction de la chair, lancement des protocoles de désinfection.', 'Détection de la malédiction de la chair, lancement des protocoles de désinfection.', 28153),
(159131, 'frFR', 'Votre corps est faible et malléable. Laissez-moi vous façonner.', 'Votre corps est faible et malléable. Laissez-moi vous façonner.', 28153),
(159130, 'frFR', 'Vous voulez blesser l\’âme-monde et dérober son sang, votre reconstitution est nécessaire.', 'Vous voulez blesser l\’âme-monde et dérober son sang, votre reconstitution est nécessaire.', 28153),
(159129, 'frFR', 'Nous sommes les défenseurs de l\’âme-monde, vous n\’avez pas l\’autorisation de poursuivre.', 'Nous sommes les défenseurs de l\’âme-monde, vous n\’avez pas l\’autorisation de poursuivre.', 28153),
(159128, 'frFR', 'Vous interférez avec notre devoir sacré. Votre purification est nécessaire.', 'Vous interférez avec notre devoir sacré. Votre purification est nécessaire.', 28153),
(159127, 'frFR', 'Les victimes de la malédiction de la chair doivent être réinitialisées. Tel est notre devoir.', 'Les victimes de la malédiction de la chair doivent être réinitialisées. Tel est notre devoir.', 28153),
(159126, 'frFR', 'Nous avons été façonnés pour protéger ce monde de la malédiction de la chair !', 'Nous avons été façonnés pour protéger ce monde de la malédiction de la chair !', 28153),
(159125, 'frFR', 'Nous avons pour fonction de purifier votre maladie. Veuillez vous tenir immobile.', 'Nous avons pour fonction de purifier votre maladie. Veuillez vous tenir immobile.', 28153),
(159124, 'frFR', 'Vous n\’interférerez pas avec notre directive…', 'Vous n\’interférerez pas avec notre directive…', 28153),
(159123, 'frFR', 'Nous reconstruirons… encore et encore…', 'Nous reconstruirons… encore et encore…', 28153),
(159122, 'frFR', 'Notre mission… est vitale…', 'Notre mission… est vitale…', 28153),
