(159120, 'frFR', 'Nous devons protéger… l\’âme-monde…', 'Nous devons protéger… l\’âme-monde…', 28153),
(159119, 'frFR', 'Vous ne… comprenez pas…', 'Vous ne… comprenez pas…', 28153),
(159118, 'frFR', 'Ce destin… n\’est pas le nôtre…', 'Ce destin… n\’est pas le nôtre…', 28153),
(159117, 'frFR', 'Les créateurs… reviendront…', 'Les créateurs… reviendront…', 28153),
(159116, 'frFR', 'Nous avons pour mission d\’assister les égarés. Laissez-moi vous réorienter.', 'Nous avons pour mission d\’assister les égarés. Laissez-moi vous réorienter.', 28153),
(159115, 'frFR', 'Notre devoir sacré ne doit pas être perturbé.', 'Notre devoir sacré ne doit pas être perturbé.', 28153),
(159114, 'frFR', 'Les créateurs nous ont confié la responsabilité de veiller sur ce monde, écartez-vous !', 'Les créateurs nous ont confié la responsabilité de veiller sur ce monde, écartez-vous !', 28153),
(159113, 'frFR', 'La malédiction de la chair échappe à tout contrôle !', 'La malédiction de la chair échappe à tout contrôle !', 28153),
(159112, 'frFR', 'Réorigination imminente, veuillez rester immobile.', 'Réorigination imminente, veuillez rester immobile.', 28153),
(159111, 'frFR', 'Votre maladie doit être guérie.', 'Votre maladie doit être guérie.', 28153),
(159110, 'frFR', 'La malédiction de la chair vous entrave, laissez-nous vous aider.', 'La malédiction de la chair vous entrave, laissez-nous vous aider.', 28153),
(159109, 'frFR', 'C\’est à nous de veiller sur le sang de la planète.', 'C\’est à nous de veiller sur le sang de la planète.', 28153),
(159108, 'frFR', 'Au moins, je meurs riche…', 'Au moins, je meurs riche…', 28153),
(159107, 'frFR', 'Dites à mes gamins… qu\’ils auront pas un rond…', 'Dites à mes gamins… qu\’ils auront pas un rond…', 28153),
(159106, 'frFR', 'Faudra pas oublier… ma prime de participation…', 'Faudra pas oublier… ma prime de participation…', 28153),
(159105, 'frFR', 'Attendez, je suis prêt à vous payer pour que vous me ressuscitiez ! Allez !', 'Attendez, je suis prête à vous payer pour que vous me ressuscitiez ! Allez !', 28153),
(159104, 'frFR', 'Aïe ! Victime d\’un redressement… fatal…', 'Aïe ! Victime d\’un redressement… fatal…', 28153),
(159103, 'frFR', 'J\’espère… que ça n\’affectera pas… mon plan retraite…', 'J\’espère… que ça n\’affectera pas… mon plan retraite…', 28153),
(159102, 'frFR', 'On passe dans le rouge !', 'On passe dans le rouge !', 28153),
(159101, 'frFR', 'Le cours de l\’action… va s\’effondrer…', 'Le cours de l\’action… va s\’effondrer…', 28153),
(159100, 'frFR', 'Préparez-vous à encaisser sévère !', 'Préparez-vous à encaisser sévère !', 28153),
(159099, 'frFR', 'Si on ne gère pas la crise, c\’est le budget café qui va y passer !', 'Si on ne gère pas la crise, c\’est le budget café qui va y passer !', 28153),
(159098, 'frFR', 'Votre tête va me permettre de toucher une jolie prime !', 'Votre tête va me permettre de toucher une jolie prime !', 28153),
(159097, 'frFR', 'J\’avais calé une réunion rien que pour vous régler votre compte !', 'J\’avais calé une réunion rien que pour vous régler votre compte !', 28153),
(159096, 'frFR', 'Les investisseurs ne vont pas être ravis de vous voir fourrer votre nez dans nos affaires !', 'Les investisseurs ne vont pas être ravis de vous voir fourrer votre nez dans nos affaires !', 28153),
(159095, 'frFR', 'Puisque c\’est comme ça, c\’est l\’heure de votre évaluation trimestrielle !', 'Puisque c\’est comme ça, c\’est l\’heure de votre évaluation trimestrielle !', 28153),
(159094, 'frFR', 'Vous, vous êtes de juteux bénéfices sur pattes !', 'Vous, vous êtes de juteux bénéfices sur pattes !', 28153),
(159093, 'frFR', 'Excellent, les profits vont dépasser les projections !', 'Excellent, les profits vont dépasser les projections !', 28153),
(159092, 'frFR', 'Félicitations, vous êtes désormais la propriété de la KapitalRisk !', 'Félicitations, vous êtes désormais la propriété de la KapitalRisk !', 28153),
(159091, 'frFR', 'On a affaire à une Opération de Prise Agressive !', 'On a affaire à une Opération de Prise Agressive !', 28153),
(159090, 'frFR', 'Déployez le kit d\’urgence, on a de la compagnie !', 'Déployez le kit d\’urgence, on a de la compagnie !', 28153),
(159089, 'frFR', 'Merci ! Tout le plaisir était pour moi.', 'Merci ! Tout le plaisir était pour moi.', 28153),
(159088, 'frFR', 'Vous allez rogner sur ma marge !', 'Vous allez rogner sur ma marge !', 28153),
(159087, 'frFR', 'On ne peut pas se permettre d\’interrompre l\’activité pour ça !', 'On ne peut pas se permettre d\’interrompre l\’activité pour ça !', 28153),
(159086, 'frFR', 'Qu\’est-ce que vous faites là ? Ces terres appartiennent à la KapitalRisk, vous n\’êtes pas au courant ?', 'Qu\’est-ce que vous faites là ? Ces terres appartiennent à la KapitalRisk, vous n\’êtes pas au courant ?', 28153),
(159085, 'frFR', 'Ack ! Alerte, une intrusion ! À moi, à l\’aide !', 'Ack ! Alerte, une intrusion ! À moi, à l\’aide !', 28153),
(159084, 'frFR', 'Éliminez la menace, mais n\’abîmez pas les armes, ça coûte cher !', 'Éliminez la menace, mais n\’abîmez pas les armes, ça coûte cher !', 28153),
(159083, 'frFR', 'N\’oubliez pas que notre objectif principal est de neutraliser leurs défenses sans révéler notre présence dans cette région. Si l\’ennemi nous repère, tout est perdu. Pour l\’Alliance !', '', 28153),
(159082, 'frFR', 'Donner 20 portions de glace à la fraise d\’Aguilor et Dagharn à Marie Havreport ?', 'Donner 20 portions de glace à la fraise d\’Aguilor et Dagharn à Marie Havreport ?', 28153),
(159081, 'frFR', '', 'Umbric et moi allons partir devant pour préparer une attaque surprise contre le port de guerre.', 28153),
(159080, 'frFR', 'Votre chemin conduit votre mondre vers sa fin… l\’arrogance vous aveugle…', 'Votre chemin conduit votre mondre vers sa fin… l\’arrogance vous aveugle…', 28153),
(159079, 'frFR', 'Nous ne voulions… que ce qui nous revenait…', 'Nous ne voulions… que ce qui nous revenait…', 28153),
(159078, 'frFR', 'Vous ne faites que retarder… l\’inévitable…', 'Vous ne faites que retarder… l\’inévitable…', 28153),
(159077, 'frFR', 'La couvée grandira… sans moi…', 'La couvée grandira… sans moi…', 28153),
(159076, 'frFR', 'Les cieux s\’assombrissent…', 'Les cieux s\’assombrissent…', 28153),
(159075, 'frFR', 'Effectivement. $n, c\’est vous qui vous chargerez d\’affaiblir les défenses portuaires des Zandalari. Kelsey, Falstad et Keeshan vous aideront pour la première cible.', '', 28153),
(159074, 'frFR', 'Nous n\’avons pas choisi… notre destin…', 'Nous n\’avons pas choisi… notre destin…', 28153),
(159073, 'frFR', 'Nous n\’avons jamais eu… la moindre chance…', 'Nous n\’avons jamais eu… la moindre chance…', 28153),
(159072, 'frFR', 'Un échec… de plus…', 'Un échec… de plus…', 28153),
(159071, 'frFR', 'Votre espèce nous a vaincus jadis, mais cette fois, nous n\’échouerons pas ! Voici venue l\’aube du Crépuscule !', 'Votre espèce nous a vaincus jadis, mais cette fois, nous n\’échouerons pas ! Voici venue l\’aube du Crépuscule !', 28153),
(159070, 'frFR', 'Nous avons besoin du minerai éclatant. Notre survie en dépend, vous ne comprenez pas ?', 'Nous avons besoin du minerai éclatant. Notre survie en dépend, vous ne comprenez pas ?', 28153),
(159069, 'frFR', '', 'Ah… Autrement dit, on attend l\’arrivée de notre flotte pour les faire sauter. La ville sera sens dessus dessous et on en profitera pour débarquer !', 28153),
(159068, 'frFR', 'Ce que nous cherchons nous a été promis il y a si longtemps !', 'Ce que nous cherchons nous a été promis il y a si longtemps !', 28153),
(159067, 'frFR', 'Le liquide doré annonce votre chute et le retour de notre Vol !', 'Le liquide doré annonce votre chute et le retour de notre Vol !', 28153),
(159066, 'frFR', 'Si on fait bien le boulot, les Zandalari sauront même pas qu\’on a truffé leurs défenses d\’explosifs.', '', 28153),
(159065, 'frFR', 'Nous sommes nos propres maîtres aujourd\’hui, laissez-nous tranquilles !', 'Nous sommes nos propres maîtres aujourd\’hui, laissez-nous tranquilles !', 28153),
(159064, 'frFR', 'Je suis d\’accord. Shandris, Falstad et moi-même avons échafaudé un plan et obtenu l\’approbation du roi Wrynn. Si nous réussissons, nos troupes auront une chance.', '', 28153),
(159063, 'frFR', 'Nous sommes libres et plus personne ne nous soumettra, vous encore moins que quiconque !', 'Nous sommes libres et plus personne ne nous soumettra, vous encore moins que quiconque !', 28153),
(159062, 'frFR', 'Le Vol du Crépuscule prend son essor à nouveau et juste sous votre nez ! Votre arrogance vous aveugle !', 'Le Vol du Crépuscule prend son essor à nouveau et juste sous votre nez ! Votre arrogance vous aveugle !', 28153),
(159061, 'frFR', '', 'C\’est donc pour ça que vous teniez tant à ces explosifs !', 28153),
(159060, 'frFR', 'Ceux qui prétendent régner sur le monde nous ont rejetés, mais l\’histoire nous appartient !', 'Ceux qui prétendent régner sur le monde nous ont rejetés, mais l\’histoire nous appartient !', 28153),
(159059, 'frFR', '', 'Les Zandalari sont coriaces, mais pas invincibles. Nous allons saboter des positions clés de leurs défenses portuaires à l\’aide de bombes télécommandées.', 28153),
(159058, 'frFR', 'Cette fois, vous ne pouvez pas nous arrêter !', 'Cette fois, vous ne pouvez pas nous arrêter !', 28153),
(159057, 'frFR', 'Gloire au Crépuscule !', 'Gloire au Crépuscule !', 28153),
(159056, 'frFR', 'Plus personne ne règne sur nous, à présent !', 'Plus personne ne règne sur nous, à présent !', 28153),
(159055, 'frFR', 'Réglons la question une fois pour toutes. L\’Alliance a besoin de nous pour préparer son invasion à grande échelle de Zuldazar.', '', 28153),
(159054, 'frFR', 'Nous ne serons plus jamais bafoués !', 'Nous ne serons plus jamais bafoués !', 28153),
(159053, 'frFR', 'L\’heure du Vol oublié est venue !', 'L\’heure du Vol oublié est venue !', 28153),
(159052, 'frFR', 'Nous surgissons des ténèbres pour régner sur ce monde.', 'Nous surgissons des ténèbres pour régner sur ce monde.', 28153),
(159051, 'frFR', 'Le règne du Vol du Crépuscule sera absolu !', 'Le règne du Vol du Crépuscule sera absolu !', 28153),
(159050, 'frFR', 'Pour le Crépuscule !', 'Pour le Crépuscule !', 28153),
(159049, 'frFR', 'Nous sommes les Gardeterres, et vous dérobez ce qui ne vous appartient pas, chair molle !', 'Nous sommes les Gardeterres, et vous dérobez ce qui ne vous appartient pas, chair molle !', 28153),
(159048, 'frFR', 'Vous ignorez où se trouve notre nid, vous n\’avez aucune chance de triompher ! Abandonnez tout espoir !', 'Vous ignorez où se trouve notre nid, vous n\’avez aucune chance de triompher ! Abandonnez tout espoir !', 28153),
(159047, 'frFR', 'Le Vol noir assouvira sa vengeance une bonne fois pour toutes !', 'Le Vol noir assouvira sa vengeance une bonne fois pour toutes !', 28153),
(159046, 'frFR', 'Nous protégeons les pierres de ce monde de la vermine de votre espèce !', 'Nous protégeons les pierres de ce monde de la vermine de votre espèce !', 28153),
(159045, 'frFR', 'Pitoyables créatures de chair, le sang du monde doré nous protège !', 'Pitoyables créatures de chair, le sang du monde doré nous protège !', 28153),
(159044, 'frFR', 'Le monde a été offert aux dragons, votre espèce n\’est qu\’une infection !', 'Le monde a été offert aux dragons, votre espèce n\’est qu\’une infection !', 28153),
(159043, 'frFR', 'Comment osez-vous vous emparer de ce qui nous appartient de droit ?', 'Comment osez-vous vous emparer de ce qui nous appartient de droit ?', 28153),
(159042, 'frFR', 'C\’est nous qui veillons sur le sang du monde ! Nous sommes les gardiens !', 'C\’est nous qui veillons sur le sang du monde ! Nous sommes les gardiens !', 28153),
(159041, 'frFR', 'Vous volez… ce qui ne vous appartient pas…', 'Vous volez… ce qui ne vous appartient pas…', 28153),
(159040, 'frFR', 'Nous ne serons pas oubliés par l\’histoire…', 'Nous ne serons pas oubliés par l\’histoire…', 28153),
(159039, 'frFR', 'Vous n\’échapperez pas au Vol noir…', 'Vous n\’échapperez pas au Vol noir…', 28153),
(159038, 'frFR', 'Vous ne pouvez pas remporter cette guerre…', 'Vous ne pouvez pas remporter cette guerre…', 28153),
(159037, 'frFR', 'Ce monde… appartient aux dragons…', 'Ce monde… appartient aux dragons…', 28153),
(159036, 'frFR', 'Votre espèce n\’a… pas sa place sur ces terres…', 'Votre espèce n\’a… pas sa place sur ces terres…', 28153),
(159035, 'frFR', 'Le Vol noir ne peut être vaincu…', 'Le Vol noir ne peut être vaincu…', 28153),
(159034, 'frFR', 'Nous… reviendrons…', 'Nous… reviendrons…', 28153),
(159033, 'frFR', 'Le Vol noir renaîtra !', 'Le Vol noir renaîtra !', 28153),
(159032, 'frFR', 'Votre espèce va être purifiée !', 'Votre espèce va être purifiée !', 28153),
(159031, 'frFR', 'Nous sommes le feu et la destruction !', 'Nous sommes le feu et la destruction !', 28153),
(159030, 'frFR', 'Vous osez affronter un Vol draconique ?', 'Vous osez affronter un Vol draconique ?', 28153),
(159029, 'frFR', 'Le Vol noir dominera à nouveau les cieux !', 'Le Vol noir dominera à nouveau les cieux !', 28153),
(159028, 'frFR', 'Gloire au Vol noir !', 'Gloire au Vol noir !', 28153),
(159027, 'frFR', 'Au nom des Gardeterres !', 'Au nom des Gardeterres !', 28153),
(159026, 'frFR', 'Je défendrai le Vol !', 'Je défendrai le Vol !', 28153),
(159025, 'frFR', 'Pour toi… ô impératrice…', 'Pour toi… ô impératrice…', 28153),
(159024, 'frFR', 'Vous en écrasez un… mais bien d\’autres approchent…', 'Vous en écrasez une… mais bien d\’autres approchent…', 28153),
(159023, 'frFR', 'Apportez le minerai… à l\’impératrice…', 'Apportez le minerai… à l\’impératrice…', 28153),
(159022, 'frFR', 'Son appel… est une mélopée…', 'Son appel… est une mélopée…', 28153),
(159021, 'frFR', 'Je l\’entends… même au seuil de la mort…', 'Je l\’entends… même au seuil de la mort…', 28153),
(159020, 'frFR', 'Le chant de l\’impératrice… s\’estompe…', 'Le chant de l\’impératrice… s\’estompe…', 28153),
(159019, 'frFR', 'Nous sommes… des milliers… vous ne pouvez pas nous arrêter…', 'Nous sommes… des milliers… vous ne pouvez pas nous arrêter…', 28153),
(159018, 'frFR', 'Kshh… Je tombe…', 'Kshh… Je tombe…', 28153),
(159017, 'frFR', 'Je vais vous tuer, votre corps nourrira l\’essaim !', 'Je vais vous tuer, votre corps nourrira l\’essaim !', 28153),
(159016, 'frFR', 'Vous vous précipitez ainsi vers votre destin ?', 'Vous vous précipitez ainsi vers votre destin ?', 28153),
(159015, 'frFR', 'Le minerai doré est à nous ! Un don pour l\’impératrice !', 'Le minerai doré est à nous ! Un don pour l\’impératrice !', 28153),
(159014, 'frFR', 'L\’essaim obéit à l\’impératrice !', 'L\’essaim obéit à l\’impératrice !', 28153),
(159013, 'frFR', 'L\’essaim ne peut être arrêté !', 'L\’essaim ne peut être arrêté !', 28153),
(159012, 'frFR', 'Le doux chant de notre impératrice exige votre mort !', 'Le doux chant de notre impératrice exige votre mort !', 28153),
(159011, 'frFR', 'L\’impératrice l\’ordonne !', 'L\’impératrice l\’ordonne !', 28153),
(159010, 'frFR', 'Pour l\’impératrice !', 'Pour l\’impératrice !', 28153),
(159009, 'frFR', 'L\’Alliance triomphera… et le règne insidieux de la reine banshee prendra fin.', '', 28153),
(159008, 'frFR', 'En commettant pareille atrocité, elle pense nous accabler. Briser notre unité. Mais je vous le jure…', '', 28153),
(159007, 'frFR', 'Rargh ! Terrassé par un coup honorable…', 'Rargh ! Terrassée par un coup honorable…', 28153),
(159006, 'frFR', 'Yargh ! Une mort rêvée !', 'Yargh ! Une mort rêvée !', 28153),
(159005, 'frFR', 'Mais tant que Sylvanas dirigera la Horde, ce rêve ne pourra devenir réalité.', '', 28153),
(159004, 'frFR', 'J\’appareille… pour le couchant…', 'J\’appareille… pour le couchant…', 28153),
(159003, 'frFR', 'Toute ma vie, j\’ai prié pour la paix en Azeroth.', '', 28153),
(159002, 'frFR', 'Je vais prendre ma place parmi les guerriers du temps jadis…', 'Je vais prendre ma place parmi les guerriers du temps jadis…', 28153),
(159001, 'frFR', 'En ce sombre jour pour l\’Alliance, vous avez fait preuve d\’un grand courage, héraut.', '', 28153),
(159000, 'frFR', 'Les esprits bénissent ma fin…', 'Les esprits bénissent ma fin…', 28153),
(158999, 'frFR', '', 'Reposez-vous et préparez-vous pour les prochaines batailles. Je compte sur vous.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'frFR', 'Je tombe en combat glorieux !', 'Je tombe en combat glorieux !', 28153),
(158997, 'frFR', 'Le clan me vengera…', 'Le clan me vengera…', 28153),
(158996, 'frFR', '', 'Toutefois, nous l\’avons blessée. Et sa colère sera sa plus grande faiblesse pendant cette guerre.', 28153),
(158995, 'frFR', 'La mort vous attend…', 'La mort vous attend…', 28153),
(158994, 'frFR', 'Une mauviette de plus à soumettre !', 'Une mauviette de plus à soumettre !', 28153),
(158993, 'frFR', 'Une bataille glorieuse de plus !', 'Une bataille glorieuse de plus !', 28153),
(158992, 'frFR', 'Je vous arracherai les yeux !', 'Je vous arracherai les yeux !', 28153),
(158991, 'frFR', '', 'Notre victoire est loin d\’être totale. L\’Alliance ripostera. Elle s\’en prendra à nous. À moi. À vous.', 28153),
(158990, 'frFR', '', 'Notre attaque visait à mettre fin à la guerre avant même son commencement… Nous devions priver nos ennemis de leur foyer, porter un coup décisif à leurs chefs… et saigner l\’Alliance à blanc.', 28153),
(158989, 'frFR', '', 'Quand je vous ai confié cette mission, jamais je n\’aurais imaginé tel dénouement.', 28153),
(158988, 'frFR', 'Les mille vaisseaux scelleront votre destin !', 'Les mille vaisseaux scelleront votre destin !', 28153),
(158987, 'frFR', 'Ma vie pour Jorun !', 'Ma vie pour Jorun !', 28153),
(158986, 'frFR', 'Pour les Sillage-de-sang !', 'Pour les Sillage-de-sang !', 28153),
(158985, 'frFR', 'Mourez avec honneur !', 'Mourez avec honneur !', 28153),
(158984, 'frFR', 'Je vais manger votre cœur !', 'Je vais manger votre cœur !', 28153),
(158983, 'frFR', 'Mrglrggg…', 'Mrglrggg…', 28153),
(158982, 'frFR', 'Mrrg mrgl ?', 'Mrrg mrgl ?', 28153),
(158981, 'frFR', 'Rgll mgrgl… rgl…', 'Rgll mgrgl… rgl…', 28153),
(158980, 'frFR', 'Grgl…', 'Grgl…', 28153),
(158979, 'frFR', 'Mrg !', 'Mrg !', 28153),
(158978, 'frFR', 'Rgl… mrg…', 'Rgl… mrg…', 28153),
(158977, 'frFR', 'Mrrrmgrl !', 'Mrrrmgrl !', 28153),
(158976, 'frFR', 'Mrglrgl ? Mrg ! Rgl !', 'Mrglrgl ? Mrg ! Rgl !', 28153),
(158975, 'frFR', 'Rgrml grml grml !', 'Rgrml grml grml !', 28153),
(158974, 'frFR', '', 'Bonté divine, mais c\’est parfait ! Merci infiniment, $p, vous êtes un ange. Tenez, prenez donc quelques biscuits.', 28153),
(158973, 'frFR', 'Mrg ? Grml ?!', 'Mrg ? Grml ?!', 28153),
(158972, 'frFR', 'Mrgl ? Rgl !', 'Mrgl ? Rgl !', 28153),
(158971, 'frFR', 'Mrglrglrgl !', 'Mrglrglrgl !', 28153),
(158970, 'frFR', 'La mort n\’est rien pour le Vide infini…', 'La mort n\’est rien pour le Vide infini…', 28153),
(158969, 'frFR', 'Son second avènement approche…', 'Son second avènement approche…', 28153),
(158968, 'frFR', 'Votre fin remonte des profondeurs…', 'Votre fin remonte des profondeurs…', 28153),
(158967, 'frFR', 'Vous ne pouvez pas nous détruire… nous sommes innombrables…', 'Vous ne pouvez pas nous détruire… nous sommes innombrables…', 28153),
(158966, 'frFR', 'Vous tomberez… vos amis vous abandonneront…', 'Vous tomberez… vos amis vous abandonneront…', 28153),
(158965, 'frFR', 'Entendez-vous l\’appel des ténèbres, dans les abysses ?', 'Entendez-vous l\’appel des ténèbres, dans les abysses ?', 28153),
(158964, 'frFR', 'Les profondeurs aliénantes ne peuvent être contenues !', 'Les profondeurs aliénantes ne peuvent être contenues !', 28153),
(158963, 'frFR', 'Ma dépouille donnera naissance à des milliers de rejetons.', 'Ma dépouille donnera naissance à des milliers de rejetons.', 28153),
(158962, 'frFR', 'Les ténèbres grouillantes sonnent le glas final.', 'Les ténèbres grouillantes sonnent le glas final.', 28153),
(158961, 'frFR', 'Le dévoreur des profondeurs a faim de votre monde !', 'Le dévoreur des profondeurs a faim de votre monde !', 28153),
(158960, 'frFR', 'Personne ne peut combattre l\’objet de ses terreurs !', 'Personne ne peut combattre l\’objet de ses terreurs !', 28153),
