(158764, 'frFR', 'J\’vais me faire un fétiche avec vos os et maudire toute vot\’ famille !', 'J\’vais me faire un fétiche avec vos os et maudire toute vot\’ famille !', 28153),
(158763, 'frFR', 'Vous sentez mauvais et vous avez rien à faire ici !', 'Vous sentez mauvais et vous avez rien à faire ici !', 28153),
(158762, 'frFR', '', 'C\’est fou ce que ça pousse vite, à cet âge-là ! Regardez comme il a grandi !', 28153),
(158761, 'frFR', 'Hé, vous êtes qui, vous ? Z\’avez rien à faire ici !', 'Hé, vous êtes qui, vous ? Z\’avez rien à faire ici !', 28153),
(158760, 'frFR', 'On va voir ce que vous avez dans le ventre, alors…', 'On va voir ce que vous avez dans le ventre, alors…', 28153),
(158759, 'frFR', 'Avec ces gemmes, mon clan, il va devenir le plus puissant de tous !', 'Avec ces gemmes, mon clan, il va devenir le plus puissant de tous !', 28153),
(158758, 'frFR', 'Vous allez voir, j\’suis un sacré morceau !', 'Vous allez voir, j\’suis un sacré morceau !', 28153),
(158757, 'frFR', 'Cette île et ces gemmes, elles sont à moi. Vous trouverez que la mort, ici.', 'Cette île et ces gemmes, elles sont à moi. Vous trouverez que la mort, ici.', 28153),
(158756, 'frFR', 'Cet endroit, on l\’a trouvé les premiers ! Vous nous le prendrez pas comme ça !', 'Cet endroit, on l\’a trouvé les premiers ! Vous nous le prendrez pas comme ça !', 28153),
(158755, 'frFR', 'C\’est notre île, ça !', 'C\’est notre île, ça !', 28153),
(158754, 'frFR', 'Hé, vous faites quoi sur cette île ?', 'Hé, vous faites quoi sur cette île ?', 28153),
(158753, 'frFR', 'On nous attaque ! Rappliquez vite fait !', 'On nous attaque ! Rappliquez vite fait !', 28153),
(158752, 'frFR', 'Allez, on découpe tout ça en tranches !', 'Allez, on découpe tout ça en tranches !', 28153),
(158751, 'frFR', 'J\’vais bouffer ça d\’une bouchée !', 'J\’vais bouffer ça d\’une bouchée !', 28153),
(158750, 'frFR', 'On va vous écorcher !', 'On va vous écorcher !', 28153),
(158749, 'frFR', 'J\’vais me faire un chouette collier avec vos os !', 'J\’vais me faire un chouette collier avec vos os !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'frFR', 'J\’vais vous ouvrir en deux et boire vot\’ sang !', 'J\’vais vous ouvrir en deux et boire vot\’ sang !', 28153),
(158747, 'frFR', 'Rargh ! Je tombe avec honneur !', '', 28153),
(158746, 'frFR', 'C\’est vous qui n\’avez rien à faire ici… nous sommes à notre place…', '', 28153),
(158745, 'frFR', 'Les gemmes… n\’ont pas pu nous sauver…', '', 28153),
(158744, 'frFR', 'Nous reviendrons… en plus grand nombre…', '', 28153),
(158743, 'frFR', 'Les étoiles… ont menti…', '', 28153),
(158742, 'frFR', 'J\’entends l\’appel… des anciens…', '', 28153),
(158741, 'frFR', 'Les esprits me saluent…', '', 28153),
(158740, 'frFR', 'Je rejoins… mes ancêtres…', '', 28153),
(158739, 'frFR', 'Les étoiles guident mes poings, l\’avenir s\’inscrira dans votre sang !', '', 28153),
(158738, 'frFR', 'Les vents m\’ont révélé que ce jour est celui de votre fin.', '', 28153),
(158737, 'frFR', 'Esprits, accordez-moi la fureur et la force d\’un brasier insatiable !', '', 28153),
(158736, 'frFR', 'Vous vous lancez dans un combat que vous ne pouvez remporter, mauviette !', '', 28153),
(158735, 'frFR', 'Les richesses de cette île nous appartiennent, imbéciles !', '', 28153),
(158734, 'frFR', 'Les ancêtres me donnent force et sagesse !', '', 28153),
(158733, 'frFR', 'Mes cornes baigneront dans votre sang, imbéciles !', '', 28153),
(158732, 'frFR', 'Je défendrai mon clan contre tous les étrangers !', '', 28153),
(158731, 'frFR', 'Guerriers, à l\’aide !', '', 28153),
(158730, 'frFR', 'Reprenez-vous, nous sommes attaqués !', '', 28153),
(158729, 'frFR', 'Vous êtes sur notre île, vous n\’avez aucun droit ici !', '', 28153),
(158728, 'frFR', 'Les gemmes brillantes sont à nous, vous n\’avez aucune chance !', '', 28153),
(158727, 'frFR', 'Nous ne vous laisserons pas vous emparer de cet endroit !', '', 28153),
(158726, 'frFR', 'Des envahisseurs ! Repoussez-les !', '', 28153),
(158725, 'frFR', 'Que les esprits guident mon arme !', '', 28153),
(158724, 'frFR', 'Pour les ancêtres !', '', 28153),
(158723, 'frFR', 'Ça… faire mal…', '', 28153),
(158722, 'frFR', 'Pourquoi… vous venir ici ?', '', 28153),
(158721, 'frFR', 'Argh ! En plein dans le bide…', '', 28153),
(158720, 'frFR', 'Pas le droit… de voler…', '', 28153),
(158719, 'frFR', 'Non ! Mes gemmes…', '', 28153),
(158718, 'frFR', 'Pourquoi vous… faire ça ?', '', 28153),
(158717, 'frFR', 'Ouille… ça pas bon…', '', 28153),
(158716, 'frFR', 'Pourquoi tout noir maintenant ?', '', 28153),
(158715, 'frFR', '', 'Y en a qui s\’imaginent qu\’un marché, c\’est juste une formalité. De fausses promesses et des simagrées. Les fruits du présent en échange des mystères de l\’avenir.\n\nMais j\’vais vous dire une bonne chose, moi : Bwonsamdi, il finit toujours par réclamer son dû.', 28153),
(158714, 'frFR', 'Nom d\’un Ogre, c\’est l\’heure de la baston !', '', 28153),
(158713, 'frFR', 'Non ! Gemmes à moi ! Pas à vous ! Moi avoir besoin !', '', 28153),
(158712, 'frFR', 'Gemmes nous donner de la force, vermine. Nous plus forts que vous !', '', 28153),
(158711, 'frFR', 'Moi garder votre tête en souvenir, après.', '', 28153),
(158710, 'frFR', 'Choper vermine ! Casser vertèbres !', '', 28153),
(158709, 'frFR', 'Ça mon île, minus ! Île rien qu\’à moi !', '', 28153),
(158708, 'frFR', 'Moi presser vous comme raisin, boire votre sang !', '', 28153),
(158707, 'frFR', 'Moi écrabouiller vous ! Rrargh !', '', 28153),
(158706, 'frFR', 'Ça mes gemmes ! Rrrargh !', '', 28153),
(158705, 'frFR', 'Pas toucher nos choses !', '', 28153),
(158704, 'frFR', 'Attraper vermine !', '', 28153),
(158703, 'frFR', 'Vous pas prendre gemmes !', '', 28153),
(158702, 'frFR', 'Ça être mon île ! Vous partir !', '', 28153),
(158701, 'frFR', 'Tuer tous les méchants !', '', 28153),
(158700, 'frFR', 'Frapper, écraser, tuer !', '', 28153),
(158699, 'frFR', 'Moi broyer vous !', '', 28153),
(158698, 'frFR', 'P\’têt que si je promets de me tenir à carreau, cette fois-ci… pas comme la dernière fois !', 'P\’têt que si je promets de me tenir à carreau, cette fois-ci… pas comme la dernière fois !', 28153),
(158697, 'frFR', 'À votre avis, qu\’est-ce qu\’il pourrait me demander, Bwonsamdi ?', 'À votre avis, qu\’est-ce qu\’il pourrait me demander, Bwonsamdi ?', 28153),
(158696, 'frFR', 'Qu\’est-ce que je dois faire… Faut que je réfléchisse… Y a forcément un moyen de m\’en sortir !', 'Qu\’est-ce que je dois faire… Faut que je réfléchisse… Y a forcément un moyen de m\’en sortir !', 28153),
(158695, 'frFR', 'Si j\’passe un marché avec Bwonsamdi, tout rentrera dans l\’ordre, pas vrai ?', 'Si j\’passe un marché avec Bwonsamdi, tout rentrera dans l\’ordre, pas vrai ?', 28153),
(158694, 'frFR', 'J\’ai les nerfs, là ! Y a rien qui va !', 'J\’ai les nerfs, là ! Y a rien qui va !', 28153),
(158693, 'frFR', 'C\’est inacceptable ! Ils savent pas qui je suis, ou quoi ?', 'C\’est inacceptable ! Ils savent pas qui je suis, ou quoi ?', 28153),
(158692, 'frFR', 'Celui qui m\’a fait ça, il va avoir affaire à moi ! Même si je dois y passer !', 'Celui qui m\’a fait ça, il va avoir affaire à moi ! Même si je dois y passer !', 28153),
(158691, 'frFR', 'Comment ça a pu se produire ? C\’est pas juste !', 'Comment ça a pu se produire ? C\’est pas juste !', 28153),
(158690, 'frFR', 'Ça ne va pas s\’arranger. Pas la peine de me soutenir le contraire.', 'Ça ne va pas s\’arranger. Pas la peine de me soutenir le contraire.', 28153),
(158689, 'frFR', 'Tout baignait pour moi et maintenant, regardez un peu… je ne suis plus rien.', 'Tout baignait pour moi et maintenant, regardez un peu… je ne suis plus rien.', 28153),
(158688, 'frFR', 'Plus jamais je sentirai la chaleur du soleil.', 'Plus jamais je sentirai la chaleur du soleil.', 28153),
(158687, 'frFR', 'Si seulement j\’avais eu quelques jours de plus devant moi… J\’aurais pu faire des tas de choses.', 'Si seulement j\’avais eu quelques jours de plus devant moi… J\’aurais pu faire des tas de choses.', 28153),
(158686, 'frFR', 'Mort, moi ? Non, je pique un somme, c\’est tout.', 'Morte, moi ? Non, je pique un somme, c\’est tout.', 28153),
(158685, 'frFR', 'Vous êtes qui ? Bah, laissez tomber, c\’est pas important…', 'Vous êtes qui ? Bah, laissez tomber, c\’est pas important…', 28153),
(158684, 'frFR', 'Si j\’ai les yeux fermés je vois pas, et si je vois pas c\’est pas vraiment en train d\’arriver. C\’est aussi simple que ça.', 'Si j\’ai les yeux fermés je vois pas, et si je vois pas c\’est pas vraiment en train d\’arriver. C\’est aussi simple que ça.', 28153),
(158683, 'frFR', 'Faut continuer… sans s\’arrêter… Tout finira par s\’arranger…', 'Faut continuer… sans s\’arrêter… Tout finira par s\’arranger…', 28153),
(158682, 'frFR', 'Comment osez-vous mettre les pieds ici ! Fini de rigoler !', '', 28153),
(158681, 'frFR', 'Affrontez-moi plutôt en combat singulier, mauviette !', '', 28153),
(158680, 'frFR', 'Vous croyez vraiment que votre engin ridicule peut me résister ?!', '', 28153),
(158679, 'frFR', 'Ha ha, un défi, ça va barder ! En garde !', '', 28153),
(158678, 'frFR', 'Mais… je suis trop mignon pour mourir…', '', 28153),
(158677, 'frFR', '', 'Je vais… vous étriper…', 28153),
(158676, 'frFR', '', 'Je vais vous tailler en charpie !', 28153),
(158675, 'frFR', 'Jetez mon corps à la mer…', '', 28153),
(158674, 'frFR', 'Vous allez boire la tasse !', '', 28153),
(158673, 'frFR', 'Lui, c\’est un sacré numéro… Il abuse de produits capillaires et compose des poèmes à l\’eau de rose. Mais ne vous méprenez pas, Reed est meilleur combattant que séducteur.', '', 28153),
(158672, 'frFR', 'Beckett est persuadé d\’être une sorte une légende…', '', 28153),
(158671, 'frFR', 'Luna a une langue… acérée, si je puis dire.', '', 28153),
(158670, 'frFR', 'Bah… La seule certitude en ce bas monde, c\’est les impôts et…', '', 28153),
(158669, 'frFR', 'Qu\’avons-nous là ? Tiens tiens, on dirait que nous avons un compte à régler !', '', 28153),
(158668, 'frFR', '', 'J\’ose espérer qu\’il n\’est pas trop tard. Hâtez-vous, $n. Trouvez ma fille.', 28153),
(158666, 'frFR', '', 'Funesterre est une île au large de Chantorage. On y envoie les pires criminels et les traîtres. Ils n\’en reviennent jamais.', 28153),
(158665, 'frFR', '', '$n ! Qu\’avez-vous découvert ?', 28153),
(158661, 'frFR', 'Je m\’arrache ! Merci pour votre aide, $p !', '', 28153),
(158660, 'frFR', 'Kua\’fon pousse un cri strident et bat de la queue d\’un air excité.', '', 28153),
(158659, 'frFR', 'Kua\’fon dépose le crâne dans votre main.', '', 28153),
(158658, 'frFR', 'Kua\’fon dépose le crâne à ses pieds et vous adresse un cri enjoué.', '', 28153),
(158657, 'frFR', '', 'La guerre est perdue. Teldrassil tombera bientôt.', 28153),
(158656, 'frFR', 'Que les marées vous engloutissent !', '', 28153),
(158655, 'frFR', 'Venez, héraut. Le chef de guerre nous attend pour revendiquer notre… victoire.', '', 28153),
(158654, 'frFR', '', 'Ça a marché. Montez !', 28153),
(158653, 'frFR', 'À mon tour de vous laisser le choix. Emmenez-le à Darnassus et vous périrez quand nous prendrons la ville… ou fuyez tous les deux loin d\’ici, et vous survivrez.', '', 28153),
(158652, 'frFR', '', 'Pour avoir épargné la vie de Malfurion, je suis prête à vous offrir un choix.', 28153),
(158651, 'frFR', '', 'Tenez vos positions !', 28153),
(158650, 'frFR', 'Pas sans raison. Nous versons le sang pour assurer la survie de la Horde.', '', 28153),
(158649, 'frFR', '', 'Rien dans cette guerre n\’est honorable. Vous avez massacré tant d\’innocents, sans la moindre raison…', 28153),
(158648, 'frFR', 'J\’ai agi sans honneur. Je ne méritais pas de mettre un terme à sa vie.', '', 28153),
(158647, 'frFR', '', 'Pourquoi l\’avoir épargné, Orc ?', 28153),
(158646, 'frFR', '', 'Malfurion ! Non !', 28153),
(158645, 'frFR', 'Vous avez guidé… votre Horde… aux seuls ordres de la mort. Vous le regretterez…', '', 28153),
(158642, 'frFR', '', 'Reposez-vous et occupez-vous de vos blessures. Vous êtes ici en sécurité.', 28153),
(158641, 'frFR', 'Je suis mort en cherchant des crosses à plus fort que moi. Vous voyez de qui je veux parler.', 'Je suis morte en cherchant des crosses à plus fort que moi. Vous voyez de qui je veux parler.', 28153),
(158640, 'frFR', 'Moi, vous savez, je suis aussi paumé que vous.', 'Moi, vous savez, je suis aussi paumée que vous.', 28153),
(158639, 'frFR', 'C\’est le chili de Haw\’li qui m\’a liquéfié les tripes.', 'C\’est le chili de Haw\’li qui m\’a liquéfié les tripes.', 28153),
(158638, 'frFR', 'Je suis mort en participant à la Torcanata. Et si c\’était à refaire, je recommencerais !', 'Je suis morte en participant à la Torcanata. Et si c\’était à refaire, je recommencerais !', 28153),
(158637, 'frFR', 'Vous avez laissé votre corps à la porte, pas vrai ?', 'Vous avez laissé votre corps à la porte, pas vrai ?', 28153),
(158636, 'frFR', 'La foudre, elle m\’est tombée dessus alors que je me baladais au Zocalo.', 'La foudre, elle m\’est tombée dessus alors que je me baladais au Zocalo.', 28153),
(158635, 'frFR', 'Je suis mort en tombant du haut de la pyramide, et je ne me souviens même plus comment je suis arrivé là.', 'Je suis morte en tombant du haut de la pyramide, et je ne me souviens même plus comment je suis arrivée là.', 28153),
(158634, 'frFR', 'Je suis sur mon trente-et-un et je n\’ai nulle part où aller.', 'Je suis sur mon trente-et-un et je n\’ai nulle part où aller.', 28153),
(158633, 'frFR', 'Calculer le bon emplacement pour ce portail dans Boralus n\’a pas été chose facile, mais c\’était un défi bienvenu ! Faites-moi savoir si tout s\’est bien passé, d\’accord ?', '', 28153),
(158632, 'frFR', 'Comme vous voulez, Nathanos.', '', 28153),
(158631, 'frFR', 'Zelling, accompagnez $n à Boralus. Oculeth vous attend avec un portail.', '', 28153),
(158630, 'frFR', 'Regardez qui voilà. Il faut qu\’on parle, vous et moi.', '', 28153),
(158629, 'frFR', 'Ça, c\’est la meilleure place de la maison… Je vous la laisserai en partant.', '', 28153),
(158628, 'frFR', '', '$p ? Peuh, jamais entendu parler.', 28153),
(158627, 'frFR', 'Hobart vous attend dehors pour vous aider à rejoindre les navires quand vous le souhaiterez.', '', 28153),
(158626, 'frFR', 'Vous pourrez pas dire que vous saviez pas !', 'Vous pourrez pas dire que vous saviez pas !', 28153),
(158625, 'frFR', 'Arrière ! C\’est pour votre propre bien !', 'Arrière ! C\’est pour votre propre bien !', 28153),
(158624, 'frFR', 'Kua\’fon tremble de terreur.', '', 28153),
(158623, 'frFR', 'Les vents ont vraiment tourné en notre faveur, vous n\’êtes pas d\’accord, $n ?', '', 28153),
(158622, 'frFR', 'Nos avenirs s\’annoncent radieux, le vôtre comme le mien.', '', 28153),
(158621, 'frFR', 'Vous pouvez pas me laisser pourrir ici. J\’suis bien trop vieux pour la mine.', 'Vous pouvez pas me laisser pourrir ici. J\’suis bien trop vieille pour la mine.', 28153),
(158620, 'frFR', 'Je crois avoir cerné notre erreur lors de l\’étape de fermentation.', '', 28153),
(158619, 'frFR', 'Conclusion, l\’introduction de contaminants invisibles pourrait avoir un impact sur le processus de réduction initial.', '', 28153),
(158618, 'frFR', 'C\’est comme si c\’était fait.', '', 28153),
(158617, 'frFR', 'J\’en suis.', '', 28153),
(158616, 'frFR', 'Au boulot, alors.', '', 28153),
(158615, 'frFR', 'Oui, je veux bien aider.', '', 28153),
(158614, 'frFR', 'Je suppose que je peux donner un coup de main.', '', 28153),
(158612, 'frFR', '', 'Prudence. Les arbres qui nous entourent ont des yeux. Privez-les-en.', 28153),
(158611, 'frFR', 'Nous devrions d\’abord nous concentrer sur la stabilisation des composants clés.', '', 28153),
(158610, 'frFR', 'Ooooh ! Voilà qui explique bien des choses ! « Première loi de l\’alchimie : pour obtenir un quelconque bénéfice, une substitution réciproque est de rigueur. »', '', 28153),
(158609, 'frFR', 'Allons-y !', 'Allons-y !', 28153),
(158608, 'frFR', 'Curieux… La température de chauffe revêt un rôle capital.', '', 28153),
(158607, 'frFR', 'Aaah ! Je crois comprendre en quoi le catalyseur a échoué.', '', 28153),
(158606, 'frFR', 'Bizarre… Jamais je ne me serais attendu à un tel résultat.', '', 28153),
(158605, 'frFR', 'Hmmm… voilà qui est intéressant.', '', 28153),
(158604, 'frFR', 'Certains de nos soldats se sont fait choper. Ça vous dit, de leur filer un coup de main ?', '', 28153),
(158603, 'frFR', 'Hé ! On nous a subtilisé une partie de nos fournitures ! Faut qu\’on les récupère fissa. Et n\’oubliez pas les intérêts !', '', 28153),
(158602, 'frFR', 'Aïe aïe aïe, il y a des blessés partout. Nous devons leur porter secours !', '', 28153),
(158601, 'frFR', 'Avis aux voleurs les plus discrets ! J\’ai un boulot fait pour vous !', '', 28153),
(158600, 'frFR', 'Bon, si vous trouvez des pièces détachées de triklo de guerre dans le coin, faites-moi signe. Vous aurez le droit de faire une virée sur la bête, dès qu\’elle roulera de nouveau.', '', 28153),
(158599, 'frFR', 'J\’ai repéré une cible qui aurait bien besoin d\’une bonne dérouillée à l\’ancienne.', '', 28153),
(158598, 'frFR', 'Non mais regardez-moi la taille de ce truc ! Des volontaires pour aller le dégommer ?', '', 28153),
(158597, 'frFR', 'Plusieurs de nos soldats ont été capturés. Une petite mission de sauvetage, ça vous tente ?', '', 28153),
(158596, 'frFR', 'Des troupes ennemies se sont enfuies avec des fournitures d\’une importance cruciale. Que diriez-vous de leur faire goûter à la justice de l\’Alliance ?', '', 28153),
(158595, 'frFR', 'Nous avons des soldats blessés sur le terrain. Y a-t-il un soigneur dans la zone ?', '', 28153),
(158594, 'frFR', 'Oui, mon enfant. Élune a donné à nos druides la force d\’invoquer des vents favorables.', '', 28153),
(158593, 'frFR', '', 'La mer Voilée s\’est-elle montrée clémente, shan\’do ?', 28153),
(158592, 'frFR', 'Renvoyez-moi au port.', 'Renvoyez-moi au port.', 28153),
(158591, 'frFR', 'Envoyez-moi au plus petit des bateaux.', 'Envoyez-moi au plus petit des bateaux.', 28153),
(158590, 'frFR', 'Nous cherchons des volontaires pour une opération d\’infiltration périlleuse. Furtivité et sournoiserie exigées.', '', 28153),
(158589, 'frFR', 'Nous tentons de réhabiliter une machine de guerre ennemie. Rapportez-moi toutes les pièces détachées que vous trouverez.', '', 28153),
(158588, 'frFR', 'Ah, une cible de choix s\’offre à nous.', '', 28153),
(158587, 'frFR', 'Une créature particulièrement imposante et hostile hante le champ de bataille. Traquez-la !', '', 28153),
(158586, 'frFR', 'Vous voulez faire connaissance avec mon ami ?', '', 28153),
(158585, 'frFR', 'Vous êtes vraiment pénible, vous savez.', '', 28153),
(158584, 'frFR', 'Hé, on se calme.', '', 28153),
(158583, 'frFR', 'Revenez en un seul morceau, d\’accord ?', '', 28153),
(158582, 'frFR', 'Gardez les yeux ouverts.', '', 28153),
(158581, 'frFR', 'Faites attention à vous.', '', 28153),
(158580, 'frFR', 'Quoi de neuf ?', '', 28153),
(158579, 'frFR', 'Comment ça va ?', '', 28153),
(158578, 'frFR', 'Vous avez l\’air en forme.', '', 28153),
(158577, 'frFR', 'Par la Lumière, j\’aurais bien besoin d\’un verre.', '', 28153),
(158576, 'frFR', 'Tout ça pour une simple paie d\’officier…', '', 28153),
(158575, 'frFR', 'Oui, oui…', '', 28153),
(158574, 'frFR', 'Circulez.', '', 28153),
(158573, 'frFR', 'Rompez.', '', 28153),
(158572, 'frFR', 'Ne perdez jamais l\’ennemi de vue.', '', 28153),
(158571, 'frFR', 'Oui ?', '', 28153),
(158570, 'frFR', 'Vous avez toute mon attention.', '', 28153),
(158569, 'frFR', 'Gloire à l\’Alliance.', '', 28153),
(158568, 'frFR', '', 'Non… c\’est impossible.', 28153),
(158565, 'frFR', '', 'Vous allez m\’aider à éprouver l\’étendue de mes pouvoirs !', 28153),
(158564, 'frFR', '', 'D\’aucuns taxent ma magie de cruauté, mais je ne cherche qu\’à explorer les frontières du possible.', 28153),
(158563, 'frFR', 'Extraction', 'Extraction', 28153),
(158562, 'frFR', 'Mia… MIA ! Ouvrez les yeux, je vous en supplie… mon amour !', '', 28153),
(158561, 'frFR', 'Que votre déesse veille sur vous.', '', 28153),
(158560, 'frFR', 'Cette banshee m\’a déjà arraché mon fils et mon royaume. Mais elle n\’aura pas ma reine !', '', 28153),
(158559, 'frFR', '', 'Ils… ils ne viendront pas…', 28153),
(158558, 'frFR', 'Astarii, vous avez fait ce que vous pouviez ! Ordonnez aux prêtres de venir avec nous !', '', 28153),
(158557, 'frFR', 'Non ! Jamais je ne vous abandonnerai !', '', 28153),
(158555, 'frFR', '', 'L\’arbre… il brûle ! Sauvez… notre enfant. Ne vous souciez pas… de moi.', 28153),
(158554, 'frFR', 'Ne vous attardez pas ici ! Traversons le portail et fuyons !', '', 28153),
(158553, 'frFR', '', 'Astarii, il n\’y a pas une minute à perdre. Nous devons évacuer la ville avant qu\’elle soit réduite en cendres !', 28153),
(158551, 'frFR', '', 'Mettez un terme à cela. Prenez le temps qu\’il vous faudra… mais apportez-moi sa tête. Retrouvez-moi ensuite à l\’Arbre-Monde.', 28153),
(158550, 'frFR', '', 'Ma victoire était inévitable. Il me faisait seulement perdre mon temps.', 28153),
(158549, 'frFR', 'Je n\’avais aucun droit d\’intervenir.', '', 28153),
(158548, 'frFR', '', 'L\’heure n\’est pas aux regrets. Vous avez fait ce qu\’il fallait.', 28153),
(158547, 'frFR', 'J\’ai agi avec lâcheté. Je… je regrette…', '', 28153),
(158546, 'frFR', 'Argh ! Saur… croc ?', '', 28153),
(158545, 'frFR', 'Le chef de guerre est seul face à Hurlorage ! Je dois…', '', 28153),
(158544, 'frFR', 'Par le nord ? Comment… Les montagnes de Gangrebois, bien sûr.', '', 28153),
(158543, 'frFR', 'Hérault, Delaryn, interceptez-les à Auberdine. Je me chargerai du nord.', '', 28153),
(158542, 'frFR', 'Les troupes de la Horde ne tarderont pas à franchir nos lignes. Nous risquons d\’être pris en tenaille.', '', 28153),
(158541, 'frFR', 'Les feux follets… ils s\’agitent ! Le mur va bientôt céder !', '', 28153),
(158540, 'frFR', '', 'Ce bruit… serait-ce… ? Shan\’do ! La Horde approche par le nord !', 28153),
(158539, 'frFR', '', 'Enfin ! L\’Arbre-Monde n\’attend plus que nous ! Trouvez Saurcroc. Il est temps d\’en finir une bonne fois pour toutes.', 28153),
(158537, 'frFR', '', 'Quel charmant spectacle, vous ne trouvez pas ? Les feux follets se dispersent un par un. Le mur commence à céder.', 28153),
(158536, 'frFR', '', 'Saurcroc ! Il était temps.', 28153),
(158535, 'frFR', 'POUR LA HORDE !', '', 28153),
(158534, 'frFR', '', 'Où êtes-vous donc passé, maudit oiseau ?', 28153),
(158533, 'frFR', '', 'Ah ! Mes yeux ! Ils brûlent !', 28153),
(158532, 'frFR', 'Taisez-vous, sorcière !', '', 28153),
(158531, 'frFR', '', 'Vous n\’avez pas pu vous empêcher de voler au secours de votre précieux arbre ridicule.', 28153),
(158530, 'frFR', '', 'Malfurion, quelle joie de vous compter parmi nous…', 28153),
(158529, 'frFR', 'Sylvanas ! Vos infamies déshonorent ce lieu sacré ! Andu-falah-dor !', '', 28153),
(158528, 'frFR', '', 'Nous ne leur laisserons aucun répit. Telles sont les lois de la guerre.', 28153),
(158527, 'frFR', '', 'Nous devons tout faire pour que pèse sur les Kaldorei une pression maximale.', 28153),
(158526, 'frFR', '', 'En attendant des nouvelles de Saurcroc, je vais continuer à aider nos soldats à franchir le mur.', 28153),
(158525, 'frFR', '', 'Nous devons poursuivre nos efforts.', 28153),
(158524, 'frFR', '', 'La Sinueuse se trouve dans une impasse, et Malfurion le sait.', 28153),
(158523, 'frFR', '', 'Champions de la Horde, votre aide est requise à la Sinueuse ! Revendiquons notre victoire !', 28153),
(158522, 'frFR', '', '… Que la chasse au corbeau est ouverte.', 28153),
(158521, 'frFR', '', 'Faites vite. Récoltez autant d\’azérite que possible et apportez-la à nos ingénieurs.', 28153),
(158520, 'frFR', '', 'Ce navire arrive certainement de Darnassus… Ce qui signifie…', 28153),
(158519, 'frFR', '', 'Agissez avec prudence. Il semblerait que l\’Alliance nous ait devancés.', 28153),
(158518, 'frFR', '', 'Une fois l\’azérite en notre possession, tous ceux qui s\’opposeront à la Horde périront.', 28153),
(158517, 'frFR', '', 'Sapeurs ! Rassemblez vos affaires et suivez-moi ! Amenez aussi les déchiqueteurs.', 28153),
(158516, 'frFR', '', 'Mettez fin à leur existence ou c\’est de notre sang qu\’ils maculeront la forêt.', 28153),
(158515, 'frFR', '', 'Seriez-vous $Ucontrarié:contrariée; que les anciens se soient retournés contre vous ? Qu\’ils aient renoncé à leur devoir sacré ?', 28153),
(158514, 'frFR', 'Taelia ! On a besoin de toi !', '', 28153),
(158513, 'frFR', 'En clair, on se jette de la falaise pour sauver notre peau. Venez !', '', 28153),
(158512, 'frFR', 'Et on tente une sortie spectaculaire !', '', 28153),
(158511, 'frFR', 'On s\’empare du coffre…', '', 28153),
(158510, 'frFR', 'Je n\’avais jamais réalisé que le soleil pouvait être aussi néfaste pour les résidus de peau.', 'Je n\’avais jamais réalisé que le soleil pouvait être aussi néfaste pour les résidus de peau.', 28153),
(158509, 'frFR', 'Bon, j\’ai un plan infaillible.', '', 28153),
(158508, 'frFR', 'Je présume que vous avez un plan pour le faire sortir en douce d\’ici ?', 'Je présume que vous avez un plan pour le faire sortir en douce d\’ici ?', 28153),
(158507, 'frFR', 'Harlan a renforcé son système de sécurité en ajoutant un cadenas supplémentaire à son coffre.\n\n<Flynn se frotte le menton.>\n\nOuais, pour l\’instant, on est coincés… Il va falloir embarquer le tout.', '', 28153),
(158506, 'frFR', 'Bravo, Harlan. Bien vu.', '', 28153),
(158505, 'frFR', 'Ceux que j\’attrape, je vais leur faire faire une centaine de fois le tour de l\’académie.', '', 28153),
(158504, 'frFR', 'Ils sont forcément quelque part…', '', 28153),
(158503, 'frFR', 'On n\’a pas demandé à revenir… ni à endurer ça.', 'On n\’a pas demandé à revenir… ni à endurer ça.', 28153),
(158502, 'frFR', 'Quatre verrous ? Vraiment ?', '', 28153),
(158501, 'frFR', 'L\’Alliance ose nous considérer comme des MONSTRES ?', 'L\’Alliance ose nous considérer comme des MONSTRES ?', 28153),
(158500, 'frFR', 'Où ces cadets sont-ils passés…', '', 28153),
(158499, 'frFR', 'Aaah, le voilà… le fameux coffre-fort d\’Harlan Sweete.', '', 28153),
(158498, 'frFR', 'Avec tous les évènements récents, je ne peux pas dire que je l\’envie. Toutefois, l\’heure est peut-être venue pour elle de céder sa place et de confier Kul Tiras à des mains plus compétentes.', 'Avec tous les évènements récents, je ne peux pas dire que je l\’envie. Toutefois, l\’heure est peut-être venue pour elle de céder sa place et de confier Kul Tiras à des mains plus compétentes.', 28153),
(158497, 'frFR', 'Chaque jour qui passe, il devient de plus en plus évident que Katherine ne fait que profiter de la position de son défunt époux.', 'Chaque jour qui passe, il devient de plus en plus évident que Katherine ne fait que profiter de la position de son défunt époux.', 28153),
(158496, 'frFR', 'Une semaine de plus sans rencontre entre les maisons.', 'Une semaine de plus sans rencontre entre les maisons.', 28153),
(158495, 'frFR', 'Absolument. N\’importe quel noble de Tiragarde digne de ce nom aurait eu le bon sens d\’éviter une mise en scène aussi mélodramatique. Il est bien trop facile de se poser en victime éplorée.', 'Absolument. N\’importe quel noble de Tiragarde digne de ce nom aurait eu le bon sens d\’éviter une mise en scène aussi mélodramatique. Il est bien trop facile de se poser en victime éplorée.', 28153),
(158494, 'frFR', 'Assassiné en plein jour, au matin de ses noces. Du travail d\’amateur.', 'Assassiné en plein jour, au matin de ses noces. Du travail d\’amateur.', 28153),
(158493, 'frFR', 'Vous voulez parler de son fiancé ? Bien sûr. Quel gâchis…', 'Vous voulez parler de son fiancé ? Bien sûr. Quel gâchis…', 28153),
(158492, 'frFR', 'Avez-vous entendu ce qui est arrivé à la fille des Malvoie ?', 'Avez-vous entendu ce qui est arrivé à la fille des Malvoie ?', 28153),
(158491, 'frFR', 'C\’est une honte. Comment imaginer un Chantorage incapable de dompter la mer ? Si j\’étais de la famille, il y a belle lurette que j\’aurais renié ce garçon.', 'C\’est une honte. Comment imaginer un Chantorage incapable de dompter la mer ? Si j\’étais de la famille, il y a belle lurette que j\’aurais renié ce garçon.', 28153),
(158490, 'frFR', 'Son oncle l\’envoie donc ici pour se défausser de ses responsabilités ?', 'Son oncle l\’envoie donc ici pour se défausser de ses responsabilités ?', 28153),
(158489, 'frFR', 'On m\’a raconté que Brannon était revenu travailler à la rade.', 'On m\’a raconté que Brannon était revenu travailler à la rade.', 28153),
(158488, 'frFR', 'Je suis soulagé de voir que Jaina tient plutôt de sa mère. On ne peut pas dire que Daelin était particulièrement beau garçon.', 'Je suis soulagée de voir que Jaina tient plutôt de sa mère. On ne peut pas dire que Daelin était particulièrement beau garçon.', 28153),
(158487, 'frFR', '', '<Une dague est fichée dans son dos, mais toutes ses affaires ont été volées.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'frFR', '', '<Ce cadavre zandalari a l\’air très récent.>', 28153),
(158485, 'frFR', '<Examiner le corps.>', '<Examiner le corps.>', 28153),
(158484, 'frFR', 'Cela fait bien longtemps que les Malvoie n\’ont pas remis les pieds à Boralus. Mérédith aurait-elle fini par comprendre qu\’elle n\’est pas à sa place ici ?', 'Cela fait bien longtemps que les Malvoie n\’ont pas remis les pieds à Boralus. Mérédith aurait-elle fini par comprendre qu\’elle n\’est pas à sa place ici ?', 28153),
(158483, 'frFR', 'Vous avez vu la tenue du seigneur Chantorage, lors de sa dernière visite ? Un chapeau à tentacules, c\’est quand même un peu vieux jeu, si vous voulez mon avis.', 'Vous avez vu la tenue du seigneur Chantorage, lors de sa dernière visite ? Un chapeau à tentacules, c\’est quand même un peu vieux jeu, si vous voulez mon avis.', 28153),
(158482, 'frFR', '<Simon regarde Kunga.>\n\nHummm, oui… Ha ha ! Vous avez le sens de l\’humour, dites-moi !\n\nHa ha ! Qu\’est-ce qu\’on rigole !\n\nVous devriez partir, avant que ça dérape. Ha ha !\n\nAllez plutôt voir les combats pendant que je… fais le plein.', '', 28153),
(158481, 'frFR', 'J\’ai découvert un cadavre derrière la tente.', 'J\’ai découvert un cadavre derrière la tente.', 28153),
(158480, 'frFR', 'Bonjour, hum, oui.\n\nBienvenue dans ma boutique. La… boutique… de, euh, de trucs à vendre… de Simon.\n\nJe vends…\n\n<Simon jette un bref coup d\’œil derrière lui.>\n\nDes armes. Toutes sortes d\’armes. Mais je n\’ai plus rien en stock, pour l\’instant.\n\nRepassez plus tard, quand j\’aurai… fait le plein.', '', 28153),
(158479, 'frFR', 'Je vais vous massacrer, pourriture de la Horde !', '', 28153),
(158478, 'frFR', 'L\’Alliance n\’a aucun droit sur nos terres !', 'L\’Alliance n\’a aucun droit sur nos terres !', 28153),
(158477, 'frFR', 'Tout est préférable au pain de marche.', '', 28153),
(158476, 'frFR', 'Toutes nos ressources s\’emploient à maintenir la Horde à distance et à gagner du temps afin de permettre aux nôtres d\’évacuer. Trouvez des provisions pour nos sentinelles.', '', 28153),
(158475, 'frFR', '', 'Je vais vous envoyer au fond de l\’océan !', 28153),
(158474, 'frFR', 'C\’est pas du mojo que j\’ai dans la poche.', '', 28153),
(158473, 'frFR', 'Vous allez pas aimer, quand je vais me venger !', '', 28153),
(158472, 'frFR', 'Me forcez pas à vous transformer en crapaud !', '', 28153),
(158471, 'frFR', 'Vous devriez arrêter. Je suis peut-être vieux, mais ça veut aussi dire que je connais les maléfices les plus efficaces.', '', 28153),
(158470, 'frFR', 'Tout doux. Aucune raison d\’être aussi tactile avec moi.', '', 28153),
(158469, 'frFR', 'Les Sombrelances, c\’est moi qui les entraîne depuis des générations.', '', 28153),
(158468, 'frFR', 'Bonne chance, et gardez un bon mojo toujours avec vous.', '', 28153),
(158467, 'frFR', '', 'Tout est préférable aux rations de combat.', 28153),
(158466, 'frFR', '', 'On dit qu\’une armée est incapable d\’avancer quand elle a l\’estomac dans les talons. Il doit bien y avoir quelque chose à grignoter dans cette forêt.', 28153),
(158465, 'frFR', 'Oubliez pas, tout régénère pas forcément.', '', 28153),
(158464, 'frFR', 'Attention !', '', 28153),
(158463, 'frFR', 'J\’y suis presque ! Encore un peu de patience…', '', 28153),
(158462, 'frFR', 'Décidément, ces fleurs sont moins dociles que je ne l\’aurais cru… mais je devrais y arriver.', '', 28153),
(158461, 'frFR', 'Cela risque de prendre du temps. La récolte des pétales est une opération délicate.', '', 28153),
(158460, 'frFR', 'Mon corps, il est trop vieux pour ça.', '', 28153),
(158459, 'frFR', 'Que les esprits, ils soient avec vous !', '', 28153),
(158458, 'frFR', 'Eekum bokum.', '', 28153),
(158457, 'frFR', 'Qui demande le docteur ?', '', 28153),
(158456, 'frFR', 'Besoin de mon aide ?', '', 28153),
(158455, 'frFR', 'Salut, toi.', '', 28153),
(158454, 'frFR', 'J\’aimerais que les esprits me guident.', 'J\’aimerais que les esprits me guident.', 28153),
(158453, 'frFR', 'Les esprits, ils peuvent vous guider ici.', '', 28153),
(158452, 'frFR', 'Una\’fe, $n ! L\’avant-poste est sous votre commandement.', '', 28153),
(158451, 'frFR', '', 'Vous les avez désarmés… pour le moment. Tant que nous n\’aurons pas arrêté leurs fournisseurs, nous devrons rester vigilants.', 28153),
(158450, 'frFR', '', 'Remplissez-vous la panse et reposez-vous donc un peu !', 28153),
(158449, 'frFR', 'Le sceau de cette salle protège l\’âme du monde. Mais avec toute cette azérite qui jaillit, il est sur le point de se briser !', '', 28153),
(158448, 'frFR', 'Si vous utilisez l\’amulette pour absorber l\’azérite, son pouvoir devrait réparer le sceau de la chambre !', '', 28153),
(158447, 'frFR', '', 'Selon la rumeur, les gangs ont mis la main sur des explosifs d\’azérite. Tant que cet armement n\’aura pas été récupéré, c\’est tout Boralus qui sera en danger !', 28153),
(158446, 'frFR', 'Mon navire a coulé, et des centaines de malheureux se sont retrouvés à l\’eau. Les requins ont débarqué en moins d\’une heure. Des petits, des gros, des affamés. On a lutté, mais je vous assure que vous n\’en menez pas large quand un requin darde sur vous ses yeux noirs avant de vous foncer dessus pour vous déchiqueter ! Puis l\’océan vire au rouge, on n\’y voit plus rien et un gars se fait bouffer… J\’ai perdu la moitié de l\’équipage au cours de cette première nuit. Difficile de dire s\’il y en avait dix ou mille autour de nous. Les secours sont arrivés au bout de cinq jours, au dernier moment. Sur trois cent seize hommes, sept s\’en sont sortis. Les requins ont dévoré le reste.\n\nBon, assez causé. Vous voulez taper du requin ?', '', 28153),
(158445, 'frFR', 'Merci. Je veux bien courir le risque. Je vais vous emprunter ces bottes.', 'Merci. Je veux bien courir le risque. Je vais vous emprunter ces bottes.', 28153),
(158444, 'frFR', '', 'Aïe ! Je cherchais juste à déplacer quelques caisses… heu… tombées d\’un chariot.\n\nAu moins, Coda n\’est pas blessé. Mon petit gars est invincible !\n\nJ\’ai une autre paire de bottes si vous avez besoin de refaire un saut dans le nord. Par contre, je vous préviens… j\’ai pas encore eu le temps de les tester.', 28153),
(158443, 'frFR', '', 'Nous arrivons trop tard.', 28153),
(158442, 'frFR', '', 'Voyez si quelqu\’un a besoin d\’aide. Je pars devant !', 28153),
(158441, 'frFR', '', 'Mais, avant toute chose, nous devons défendre la porte !', 28153),
(158440, 'frFR', '', 'Oh, non…', 28153),
(158439, 'frFR', '', 'Du calme, nous sommes au courant. Il ne s\’en tirera pas à si bon compte.', 28153),
(158438, 'frFR', 'Harlan… cette pourriture travaille pour Corsandre… il… Argh !', '', 28153),
(158437, 'frFR', 'J\’ai… mal partout… <tousse>', '', 28153),
(158436, 'frFR', '', 'Flynn ! Tout va bien, je suis là ! Comment te sens-tu ? Rien de cassé ?', 28153),
(158435, 'frFR', 'Que… ah… wouaaah !', '', 28153),
(158434, 'frFR', '', 'Très bien. Venez, mère. Il est temps de rentrer.', 28153),
(158433, 'frFR', '', 'Accrochez-vous !', 28153),
(158432, 'frFR', 'Je suis prêt à partir.', 'Je suis prête à partir.', 28153),
(158431, 'frFR', '', 'Je nous téléporterai hors d\’ici à votre signal, $c.\n\nDe grâce, faites vite. J\’ai grand-hâte de quitter cet endroit.', 28153),
(158430, 'frFR', 'SCÈNE DE TRANSITION !', 'SCÈNE DE TRANSITION !', 28153),
(158429, 'frFR', 'Nous entretenons des relations de bon voisinage avec les Elfes de la nuit. Mais… euh… je ne peux pas en dire autant de ces feux follets.', '', 28153),
(158428, 'frFR', 'Occuper la terre et la travailler. C\’était ça, notre accord.', '', 28153),
(158427, 'frFR', 'C\’est bien triste, ce qui est arrivé à leur arbre.', '', 28153),
(158426, 'frFR', 'Croyez vraiment qu\’vous allez nous empêcher d\’récupérer le corps de Derek ? Z\’allez pas être $Udéçu:déçue; du voyage !', '', 28153),
(158425, 'frFR', 'Cette fois, il n\’a qu\’à atteindre l\’objectif. Mais prenez garde aux dangers qui rôdent.', '', 28153),
(158424, 'frFR', 'Maintenant, pouvez-vous guider Loh jusqu\’au trésor, puis jusqu\’à l\’objectif, sans emprunter deux fois le même chemin ?', '', 28153),
(158423, 'frFR', 'Facile, non ?', '', 28153),
(158422, 'frFR', 'Commençons par un défi simple : conduire Loh jusqu\’à l\’objectif.', '', 28153),
(158421, 'frFR', 'Quand nous relatons ces histoires, nous demandons aux jeunes Tortollans d\’aider Loh à traverser différents labyrinthes.', '', 28153),
(158420, 'frFR', 'Peut-on commencer votre entraînement au combat ?', 'Peut-on commencer votre entraînement au combat ?', 28153),
(158419, 'frFR', 'En piste, $p, ça va butiner sec !', 'En piste, $p, ça va butiner sec !', 28153),
(158418, 'frFR', 'Fort de ses premières réussites, Loh prit confiance en lui et partit à la découverte de nouvelles contrées.', '', 28153),
(158416, 'frFR', 'Pouvez-vous guider Loh jusqu\’aux trésors et l\’aider à trouver la sortie sans emprunter deux fois le même chemin ?', '', 28153),
(158415, 'frFR', 'Il se mit en quête de ruines antiques encore inexplorées et y découvrit souvent d\’incroyables trésors.', '', 28153),
(158414, 'frFR', '« Loh l\’Explorateur. » Au fil des années, la curiosité de Loh pour le monde ne cessa de croître.', '', 28153),
(158413, 'frFR', 'Les efforts de Loh portèrent leurs fruits, et la terre lui offrit des récoltes abondantes et délicieuses.', '', 28153),
(158412, 'frFR', 'Pouvez-vous aider Loh à faire le tour de chaque plante du jardin au moins une fois ?', '', 28153),
(158411, 'frFR', 'Chaque matin, il rendait visite à toutes les plantes de son jardin, afin de s\’assurer qu\’elles ne manquaient de rien.', '', 28153),
(158410, 'frFR', '', 'Manifestement, les Drust ne se soucient guère de maintenir leurs prisonniers en vie. Nous ne pouvons abandonner Jaina à un tel destin.', 28153),
(158409, 'frFR', '« La récolte de Loh. » Loh adorait regarder pousser la verdure.', '', 28153),
(158408, 'frFR', 'Ce jour-là, Loh a vu la mort de près, alors il a décidé de se ranger.', '', 28153),
(158407, 'frFR', 'Pouvez-vous aider Loh à désactiver le piège en éteignant toutes les dalles lumineuses ?', '', 28153),
(158406, 'frFR', '« La curiosité des Tortollans ». La curiosité a bien failli avoir raison de Loh le jour où il a déclenché un ancien piège zandalari !', '', 28153),
(158405, 'frFR', '', 'Implorez ma pitié !', 28153),
(158404, 'frFR', 'La vie de citadin n\’était pas faite pour Loh. Il décida alors de retourner à une vie plus simple.', '', 28153),
(158403, 'frFR', 'Mais il n\’arrêtait pas de se perdre. Pouvez-vous guider Loh vers toutes les échoppes, puis jusqu\’à l\’auberge, sans emprunter deux fois le même chemin ?', '', 28153),
(158402, 'frFR', '« Un Tortollan dans la ville. » Une fois, Loh visita une grande ville, un peu comme Boralus, là-bas.', '', 28153),
(158401, 'frFR', 'Loh vécut une vie simple et paisible… avec le ventre bien rempli.', '', 28153),
(158399, 'frFR', '', 'J\’ai réussi à capturer quelques élémentaires inférieurs tout à fait fascinants, près de ces sanctuaires. Vous voulez voir de quoi ils sont capables ?', 28153),
(158398, 'frFR', 'Invités s\’enfuir… $PR imbattable…', '', 28153),
(158397, 'frFR', 'Encore faim…', '', 28153),
(158396, 'frFR', 'Qui a éteint la lumière ?', '', 28153),
(158395, 'frFR', 'Au revoir, Gallywix…', '', 28153),
(158394, 'frFR', 'Pas de bagarres !', '', 28153),
(158393, 'frFR', 'Premier jour de service ! Bonne chance !', '', 28153),
(158392, 'frFR', 'Dégagez, $PR ! Vous n\’êtes pas $Utoléré:tolérée; ici !', '', 28153),
(158391, 'frFR', 'Par-tee privée !', '', 28153),
(158390, 'frFR', 'Vous n\’êtes même pas mon pire client… du jour.', 'Vous n\’êtes même pas mon pire client… du jour.', 28153),
(158389, 'frFR', 'Et un Gobelin… on the rocks…', 'Et un Gobelin… on the rocks…', 28153),
(158388, 'frFR', 'Dernière chance… pour le Kaja\’Cola…', 'Dernière chance… pour le Kaja\’Cola…', 28153),
(158387, 'frFR', 'Vous feriez mieux… de laisser un gros pourboire…', 'Vous feriez mieux… de laisser un gros pourboire…', 28153),
(158386, 'frFR', 'Je n\’ai jamais appris… à jouer au… golf…', 'Je n\’ai jamais appris… à jouer au… golf…', 28153),
(158385, 'frFR', 'Vous n\’êtes qu\’une… nullité…', 'Vous n\’êtes qu\’une… nullité…', 28153),
(158384, 'frFR', 'Ne m\’enterrez pas dans cet uniforme… C\’est ridicule…', 'Ne m\’enterrez pas dans cet uniforme… C\’est ridicule…', 28153),
(158383, 'frFR', 'Hors de question que je porte ces clubs une seconde de plus…', 'Hors de question que je porte ces clubs une seconde de plus…', 28153),
(158382, 'frFR', 'Le Grand Gally… va vous le faire payer très cher…', 'Le Grand Gally… va vous le faire payer très cher…', 28153),
(158381, 'frFR', 'Attendez, je commençais tout juste à… m\’amuser…', 'Attendez, je commençais tout juste à… m\’amuser…', 28153),
(158380, 'frFR', 'Attendez… J\’ai pas eu le temps de pointer…', 'Attendez… J\’ai pas eu le temps de pointer…', 28153),
(158379, 'frFR', 'Dites à Gallywix de continuer à… me payer.', 'Dites à Gallywix de continuer à… me payer.', 28153),
(158378, 'frFR', 'Je parie que vous ne laissez pas de pourboire, sale pingre.', 'Je parie que vous ne laissez pas de pourboire, sale pingre.', 28153),
(158377, 'frFR', 'Pas touche à mon Kaja\’Cola !', 'Pas touche à mon Kaja\’Cola !', 28153),
(158376, 'frFR', 'Je vais préparer un martini avec votre rate… un ratini !', 'Je vais préparer un martini avec votre rate… un ratini !', 28153),
(158375, 'frFR', 'J\’entends quelque chose…', 'J\’entends quelque chose…', 28153),
(158374, 'frFR', 'C\’est votre tournée, $Ucher ami:chère amie;.', 'C\’est votre tournée, $Ucher ami:chère amie;.', 28153),
(158373, 'frFR', 'Que diriez-vous d\’un trou d\’un coup… dans la rotule ?', 'Que diriez-vous d\’un trou d\’un coup… dans la rotule ?', 28153),
(158372, 'frFR', '<Le médecin se tourne vers vous et vous parler à voix basse.>$b$bIls sont mal en point. On ne peut pas les déplacer, pas dans cet état. Le mieux qu\’on puisse faire, c\’est de les rafistoler et de tenter notre chance.$b$bC\’est de la folie, là-haut…', 'n/a', 28153),
(158371, 'frFR', 'Rien n\’est plus barbant que de regarder ces abrutis frapper des balles à longueur de journée.', 'Rien n\’est plus barbant que de regarder ces abrutis frapper des balles à longueur de journée.', 28153),
(158370, 'frFR', 'Pour ce genre d\’affaires, je pencherais pour un grand coup de club en pleine face !', 'Pour ce genre d\’affaires, je pencherais pour un grand coup de club en pleine face !', 28153),
(158369, 'frFR', 'Ah, c\’est enfin à moi de cogner !', 'Ah, c\’est enfin à moi de cogner !', 28153),
(158368, 'frFR', 'Ha ! Je vous ai bien $Ueu:eue; ! J\’étais un agent de sécurité infiltré depuis le début.', 'Ha ! Je vous ai bien $Ueu:eue; ! J\’étais un agent de sécurité infiltré depuis le début.', 28153),
(158367, 'frFR', 'Ne vous inquiétez pas. J\’ai la situation bien en main.', 'Ne vous inquiétez pas. J\’ai la situation bien en main.', 28153),
(158366, 'frFR', 'Ne vous approchez pas des invités !', 'Ne vous approchez pas des invités !', 28153),
(158365, 'frFR', 'Je ne suis pas assez payé pour ça.', 'Je ne suis pas assez payée pour ça.', 28153),
(158364, 'frFR', 'Il faut que je grille… une dernière… fois…', 'Il faut que je grille… une dernière… fois…', 28153),
(158363, 'frFR', 'Laissez-moi prendre le soleil… et retournez-moi avant que je sente le roussi.', 'Laissez-moi prendre le soleil… et retournez-moi avant que je sente le roussi.', 28153),
(158362, 'frFR', 'Ha ! Et eux qui disaient que… le soleil aurait ma peau…', 'Ha ! Et eux qui disaient que… le soleil aurait ma peau…', 28153),
(158361, 'frFR', 'Non, mon magnifique corps tout bronzé…', 'Non, mon magnifique corps tout bronzé…', 28153),
(158360, 'frFR', 'Je vais en toucher deux mots… à Gallywix…', 'Je vais en toucher deux mots… à Gallywix…', 28153),
(158359, 'frFR', 'Je voulais juste faire la fête…', 'Je voulais juste faire la fête…', 28153),
(158358, 'frFR', 'Ça n\’a rien de plaisant… et ce n\’est pas un palais…', 'Ça n\’a rien de plaisant… et ce n\’est pas un palais…', 28153),
(158357, 'frFR', 'Mais je suis… très important…', 'Mais je suis… très importante…', 28153),
(158356, 'frFR', 'Caddy, emmenez-moi… jusqu\’au trou.', 'Caddy, emmenez-moi… jusqu\’au trou.', 28153),
(158355, 'frFR', 'Au moins, je meurs… avec un coup d\’avance.', 'Au moins, je meurs… avec un coup d\’avance.', 28153),
(158354, 'frFR', 'Enterrez-moi… dans la fosse de sable.', 'Enterrez-moi… dans la fosse de sable.', 28153),
(158353, 'frFR', 'Dites-leur… que j\’avais un coup d\’avance.', 'Dites-leur… que j\’avais un coup d\’avance.', 28153),
(158352, 'frFR', 'C\’est la meilleure soirée… de ma vie.', 'C\’est la meilleure soirée… de ma vie.', 28153),
(158351, 'frFR', 'C\’est la pire soirée… de ma vie.', 'C\’est la pire soirée… de ma vie.', 28153),
(158350, 'frFR', 'Je veux… être remboursé.', 'Je veux… être remboursée.', 28153),
(158349, 'frFR', 'Juste un… dernier… verre…', 'Juste un… dernier… verre…', 28153),
(158348, 'frFR', 'On est au max. Allez piquer une tête ailleurs !', 'On est au max. Allez piquer une tête ailleurs !', 28153),
(158347, 'frFR', 'Halte, $PR ! Ceux de votre espèce ne sont pas admis dans cette piscine !', 'Halte, $PR ! Ceux de votre espèce ne sont pas admis dans cette piscine !', 28153),
(158346, 'frFR', 'Avez-vous assisté à mon grand plongeon ? Dix étoiles sur dix, c\’est la classe !', 'Avez-vous assisté à mon grand plongeon ? Dix étoiles sur dix, c\’est la classe !', 28153),
(158345, 'frFR', 'Hé, $PR. Votre sale face de rat me gâche le paysage !', 'Hé, $PR. Votre sale face de rat me gâche le paysage !', 28153),
(158344, 'frFR', 'Je vous le dis, la sécurité de Gallywix empire à chaque week-end.', 'Je vous le dis, la sécurité de Gallywix empire à chaque week-end.', 28153),
(158343, 'frFR', 'Je n\’ai pas payé un supplément pour avoir à vous supporter, sale $PR !', 'Je n\’ai pas payé un supplément pour avoir à vous supporter, sale $PR !', 28153),
(158342, 'frFR', 'Dégagez, $p. Allez donc importuner la foule près de la piscine.', 'Dégagez, $p. Allez donc importuner la foule près de la piscine.', 28153),
(158341, 'frFR', 'Tenez mon Kaja\’Cola. Je m\’en occupe.', 'Tenez mon Kaja\’Cola. Je m\’en occupe.', 28153),
(158340, 'frFR', 'Sortez du terrain ! Vos chaussures vont labourer le gazon.', 'Sortez du terrain ! Vos chaussures vont labourer le gazon.', 28153),
(158339, 'frFR', 'Caddy, appelez mon chauffeur ! Celle-ci va partir loin.', 'Caddy, appelez mon chauffeur ! Celle-ci va partir loin.', 28153),
(158338, 'frFR', 'Je vais exécuter mon prochain trou d\’un coup avec votre œil !', 'Je vais exécuter mon prochain trou d\’un coup avec votre œil !', 28153),
(158337, 'frFR', 'Perturbations sur le terrain ! J\’ai le droit de rejouer mon coup !', 'Perturbations sur le terrain ! J\’ai le droit de rejouer mon coup !', 28153),
(158336, 'frFR', 'Dégagez, $PR. Vous ne voyez pas qu\’on est occupés à boire, à manger et à reboire !', 'Dégagez, $PR. Vous ne voyez pas qu\’on est occupés à boire, à manger et à reboire !', 28153),
(158335, 'frFR', 'Je ne suis pas contre un petit supplément d\’action.', 'Je ne suis pas contre un petit supplément d\’action.', 28153),
(158334, 'frFR', 'Hors de ma vue, $PR ! Sécurité ! Emparez-vous de cet énergumène.', 'Hors de ma vue, $PR ! Sécurité ! Emparez-vous de cet énergumène.', 28153),
(158333, 'frFR', 'Je n\’ai pas acheté le forfait fastoche de l\’Alliance !', 'Je n\’ai pas acheté le forfait fastoche de l\’Alliance !', 28153),
(158332, 'frFR', 'Aïeuh…', '', 28153),
(158331, 'frFR', 'Gobelins… courez !', '', 28153),
(158330, 'frFR', 'Voulais juste… le qui-brille…', '', 28153),
(158329, 'frFR', 'J\’ai tout donné…', '', 28153),
(158328, 'frFR', 'Dire à Gally G… moi désolé…', '', 28153),
(158327, 'frFR', 'Travail continue…', '', 28153),
(158326, 'frFR', 'Moi sommeil…', '', 28153),
(158325, 'frFR', 'Non… pas l\’or.', '', 28153),
(158324, 'frFR', 'Pas touche !', '', 28153),
(158323, 'frFR', 'Notre or à nous !', '', 28153),
(158322, 'frFR', 'Gally G, il dit écrabouiller $PR.', '', 28153),
(158321, 'frFR', 'Pas touche aux Gobelins !', '', 28153),
(158320, 'frFR', 'Donnez l\’or !', '', 28153),
(158319, 'frFR', 'Gallawick, c\’est l\’meilleur !', '', 28153),
(158318, 'frFR', 'On s\’arrête pas !', '', 28153),
(158317, 'frFR', 'Assez perdu de temps !', '', 28153),
(158316, 'frFR', 'Ils fuiront de terreur devant le Vide.', 'Ils fuiront de terreur devant le Vide.', 28153),
(158315, 'frFR', 'Je les ai vus à travers le voile. Suivez-moi.', 'Je les ai vus à travers le voile. Suivez-moi.', 28153),
(158314, 'frFR', 'Venez donc par ici, mes petits Gobelins…', 'Venez donc par ici, mes petits Gobelins…', 28153),
(158313, 'frFR', '', 'Nos troupes sont rassemblées à Ar\’gorok. Mobilisez vos alliés et emparez-vous de Stromgarde pour la Horde !', 28153),
(158312, 'frFR', '<Partir et rejoindre le combat à Lordaeron.>', '<Partir et rejoindre le combat à Lordaeron.>', 28153),
(158311, 'frFR', 'Les surprises se poursuivront jusqu\’à ce que le moral s\’améliore.', '', 28153),
(158310, 'frFR', 'Voilà une histoire hilarante que vous pourrez raconter à vos amis.', '', 28153),
(158309, 'frFR', 'Préparez vos appareils photos. Dans 3… 2… 1…', '', 28153),
(158308, 'frFR', 'Activation de l\’éclate totale.', '', 28153),
(158307, 'frFR', 'Demande de surprise reçue. Mode grosse fiesta activé.', '', 28153),
(158306, 'frFR', 'Le seuil de divertissement maximal doit être surpassé.', '', 28153),
(158305, 'frFR', 'Les invités ennuyeux ne seront pas tolérés.', '', 28153),
(158304, 'frFR', 'Manque de divertissement détecté. Correction en cours.', '', 28153),
(158303, 'frFR', '', '… Je vous le dirai quand la guerre sera terminée.', 28153),
(158302, 'frFR', 'N\’en parlons plus.', 'N\’en parlons plus.', 28153),
(158301, 'frFR', 'Oui.', 'Oui.', 28153),
(158300, 'frFR', '', 'Nous sommes à un jet de pierre d\’un lieu de rassemblement majeur de la Horde et vous me demandez pourquoi j\’ai une potion qui peut vous rendre invisible ?', 28153),
(158299, 'frFR', 'Que fabriquez-vous avec un flacon d\’invisibilité ?', 'Que fabriquez-vous avec un flacon d\’invisibilité ?', 28153),
(158298, 'frFR', 'Oust, du balai. Vous allez me faire repérer.', '', 28153),
(158297, 'frFR', 'Envoyez-moi au vaisseau amiral.', 'Envoyez-moi au vaisseau amiral.', 28153),
(158296, 'frFR', 'Si vous avez besoin d\’utiliser l\’un de ces navires, je suis votre homme !', '', 28153),
(158295, 'frFR', 'C\’est quelque chose, ce gros arbre ambulant !', '', 28153),
(158294, 'frFR', 'Vog\’rish pas content, vous payer !', '', 28153),
(158293, 'frFR', 'Ça jamais arriver à Vog\’rish avant !', '', 28153),
(158292, 'frFR', 'Raaaaah ! Vog\’rish mal, mal, mal !', '', 28153),
(158291, 'frFR', 'Les Elfes ont vraiment la main verte.', '', 28153),
(158290, 'frFR', 'Vog\’rish montrer son vrai pouvoir !', '', 28153),
(158289, 'frFR', 'Gare à la fournaise, avortons !', '', 28153),
(158288, 'frFR', 'Grand méchant Ogre, rhoooo !', '', 28153),
(158287, 'frFR', 'Un petit coup de main, ça ne se refuse pas.', '', 28153),
(158286, 'frFR', '', 'Shandris… vous devez… survivre…', 28153),
(158285, 'frFR', '', 'Pour… mon… peuple…', 28153),
(158284, 'frFR', 'Vog\’rish brûler vos pieds !', '', 28153),
(158283, 'frFR', 'Vog\’rish déchaîner sa magie !', '', 28153),
(158282, 'frFR', '', 'Accompagnez-moi dans la mort !', 28153),
(158281, 'frFR', 'Gare à ma super puissance !', '', 28153),
(158280, 'frFR', 'Ah, juste à l\’heure !', '', 28153),
(158279, 'frFR', '', 'Il semble que vous n\’ayez plus à attendre bien longtemps, Nathanos.', 28153),
(158278, 'frFR', '', 'Qu\’est-ce qu\’ils brillent ! Le gros, là, je ferai croire aux clients qu\’il a été béni par les eaugures. Et celui-là, en spirale, qu\’il vient d\’un trésor de pirate !', 28153),
(158277, 'frFR', '', 'Le mur de feux follets est affaibli, ils seront moins à harceler nos soldats. Bien joué.', 28153),
(158276, 'frFR', '', 'Cette zone doit être nettoyée pour assurer le passage sécurisé de nos troupes. Ne sous-estimez pas les feux follets. En nombre, ils représentent un danger mortel.', 28153),
(158275, 'frFR', '', 'Vous n\’imaginez pas toutes les bizarreries qu\’on peut attraper quand on pêche ici. D\’ailleurs, j\’ai ferré quelques créatures exotiques, ces derniers jours. Un combat, ça vous tente ?', 28153),
(158274, 'frFR', 'Lilian ne cesse de me dire que la Horde est une grande famille.\n\nMaintenant que je sais que ma véritable famille ne m\’acceptera jamais… j\’avoue que j\’aurais bien besoin de son soutien.\n\nMais en retour, Lilian m\’a promis que les miens resteraient en sécurité. Et si je peux en avoir la garantie en apportant mon aide à la Horde…\n\nAlors c\’est ce que je ferai.', '', 28153),
(158273, 'frFR', '', 'On s\’en va d\’ici !', 28153),
(158272, 'frFR', '', 'Coquillages à vendre ! Les plus jolis de Kul Tiras ! D\’Azeroth, pardon ! Les plus jolis d\’Azeroth !', 28153),
(158271, 'frFR', '', 'Je commence à reprendre mes esprits, $n.\n\nAvec l\’aide de Lilian, je pourrai peut-être accepter ce nouveau destin.\n\nNéanmoins… plus loin je serai de Kul Tiras… mieux ce sera.', 28153),
(158270, 'frFR', 'Je saisirai volontiers cette occasion de prouver la valeur des Ren\’dorei dans cette croisade.\n\nNous sommes prêts à tout pour assurer le succès de l\’Alliance.', '', 28153),
(158269, 'frFR', '', 'Je dois dire que les talents du haut-commandant Verroctone ne cessent de m\’impressionner.\n\nIl maîtrise un grand nombre de tactiques et ses capacités d\’adaptation stratégique sont remarquables.\n\nL\’effort de guerre de l\’Alliance est entre de bonnes mains. Tout comme vous, je suis fière d\’y contribuer.', 28153),
(158268, 'frFR', '', 'Les San\’layn doivent être éradiqués. L\’imprudence de la Horde nous met tous en danger.', 28153),
(158267, 'frFR', 'Vous voir bientôt. Feu ! Oui, grand feu !', '', 28153),
(158266, 'frFR', 'Je vous ferai signe quand nous aurons besoin de vous. Pour l\’Alliance.', '', 28153),
(158265, 'frFR', 'Il faut immédiatement en informer le roi Anduin. Notre tâche ici est terminée, mais notre mission ne fait que commencer.', '', 28153),
(158264, 'frFR', 'La Horde a-t-elle vraiment recours à ces Elfes vampiriques ? Elle est tombée bien bas.', '', 28153),
(158263, 'frFR', 'Attention, ça va fumer !', '', 28153),
(158262, 'frFR', 'Ce que vous décrivez ressemble à l\’un des San\’layn… un prince de sang.', '', 28153),
(158261, 'frFR', '', 'F-Fuzbert est mort ?', 28153),
(158260, 'frFR', 'Vous croire Vog\’rish… Pas de fumée sans feu !', '', 28153),
(158259, 'frFR', 'Le moment est venu de passer à la prochaine phase de notre plan.', '', 28153),
(158258, 'frFR', 'Nous avons le corps de Derek Portvaillant. Inutile de réanimer d\’autres cadavres kultirassiens. Pour le moment.', '', 28153),
(158257, 'frFR', 'Espérons que vos efforts n\’auront pas été vains.', '', 28153),
(158256, 'frFR', 'La guerre s\’est invitée en Sombrivage, et nous devons faire tout ce qui est en notre pouvoir pour protéger notre peuple. Envoyez les feux follets que vous trouverez en première ligne et éliminez toutes les menaces.', '', 28153),
(158255, 'frFR', '', 'Ha ! J\’ai entendu crier un traître pris au piège !', 28153),
(158254, 'frFR', '', 'Du repos pour les braves épuisés et des vivres pour les bouches affamées.', 28153),
(158253, 'frFR', '', 'Je n\’étais pas d\’accord pour attirer la flotte kultirassienne dans mon port.\n\nVous feriez bien d\’avoir un plan qui tient la route. Je refuse de perdre ma liberté.', 28153),
(158252, 'frFR', 'Commencez le rituel.', 'Commencez le rituel.', 28153),
(158251, 'frFR', 'D\’où venez-vous ?', 'D\’où venez-vous ?', 28153),
(158250, 'frFR', 'Vous êtes ici depuis combien de temps ?', 'Vous êtes ici depuis combien de temps ?', 28153),
(158249, 'frFR', 'Ce désert est le seul foyer que j\’aie jamais connu.\n\nNous allons là où les sables nous mènent.', 'Ce désert est le seul foyer que j\’aie jamais connu.\n\nNous allons là où les sables nous mènent.', 28153),
(158248, 'frFR', 'Ma caravane a élu domicile dans ce désert bien avant ma naissance.\n\nIl y en a d\’autres, par-delà les mers, mais je n\’ai jamais eu l\’occasion de les voir.', 'Ma caravane a élu domicile dans ce désert bien avant ma naissance.\n\nIl y en a d\’autres, par-delà les mers, mais je n\’ai jamais eu l\’occasion de les voir.', 28153),
(158247, 'frFR', 'Ne dites pas de bêtises. Vous et votre peuple avez été admirables, magistère. Vous êtes un précieux atout pour l\’Alliance.', '', 28153),
(158246, 'frFR', 'Au nom de tous les Elfes du Vide, je vous présente mes excuses pour cet échec.', '', 28153),
(158245, 'frFR', '', 'Allons à la colline de la Vigie. Vite, grimpez !', 28153),
(158244, 'frFR', 'Kua\’fon gazouille d\’un air satisfait et se roule en boule pour faire la sieste.', '', 28153),
(158243, 'frFR', 'Le villageois gémit de douleur.', 'La villageoise gémit de douleur.', 28153),
(158242, 'frFR', 'Mok\’rah, $n ! L\’avant-poste est sous votre commandement.', '', 28153),
(158241, 'frFR', '', 'Umpf.', 28153),
(158240, 'frFR', 'Vous serez grassement $Udédommagé:dédommagée; pour votre peine.', '', 28153),
(158239, 'frFR', '', 'Nathanos, je vous ai dit que votre Horde pouvait établir sa base dans mon port. Je ne vous ai pas autorisé à mener la flotte des Portvaillant jusqu\’à mon perron !', 28153),
(158238, 'frFR', 'Le sceptre est un puissant artéfact permettant de commander aux mers. C\’est précisément ce qu\’il nous faut pour prendre l\’avantage sur la marine kultirassienne.', '', 28153),
(158237, 'frFR', '', 'Vous avez un plan pour entrer discrètement ? Boralus est bien gardée…', 28153),
(158236, 'frFR', 'J\’ai envoyé Valentine à Boralus pour informer dame Portvaillant que le corps de son fils est en notre possession.', '', 28153),
(158235, 'frFR', 'Du calme, mes amis. Soyez assurés que ce pirate paiera le prix fort pour ses crimes. Néanmoins, il nous faut attendre le verdict de la cour pour connaître la sentence finale.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'frFR', 'Notre mission consiste à récupérer le sceptre abyssal qui se trouve dans les profondeurs du monastère Chantorage, à Boralus.', '', 28153),
(158233, 'frFR', '', 'Venez, $n. Nathanos vous expliquera l\’essentiel.', 28153),
(158232, 'frFR', 'Pour le crime d\’usure dont on vous accuse, la cour vous déclare coupable. Vos crédits crapuleux ont englouti les économies des honnêtes gens de la pointe du Crochet. À cause de vos méfaits, bon nombre d\’entre eux vivent aujourd\’hui dans les rues.', '', 28153),
(158231, 'frFR', 'La cour vous reconnaît coupable des chefs d\’accusation suivants : piraterie, vol et meurtre. La piraterie est l\’un des crimes les plus abominables reconnus par la loi kultirassienne, et justice sera rendue.', '', 28153),
(158230, 'frFR', 'Extorsion et racket ! Bon nombre des familles présentes aujourd\’hui ont été victimes de vos arnaques. Vous avez escroqué les braves gens de Kul Tiras, et à présent, c\’est à vous de passer à la caisse.', '', 28153),
(158229, 'frFR', 'Suivez-moi. Je vais vous mener directement jusqu\’à Alleria et au haut-commandant.', '', 28153),
(158228, 'frFR', 'Ce n\’est pas la victoire totale que j\’espérais remporter pour l\’Alliance, mais le retard ne comptera pas parmi mes échecs ici.', '', 28153),
(158227, 'frFR', 'Alors on poursuivait un leurre de Gallywix pendant tout ce temps ? Les Gobelins sont vraiment les pires adversaires.', '', 28153),
(158226, 'frFR', 'À plus, bande de nases !', '', 28153),
(158225, 'frFR', 'Vous savez, ces mécano-armures ne sont pas données, $p. Je vous enverrai la facture pour celle-ci !', '', 28153),
(158224, 'frFR', 'Des travailleurs qualifiés et sous-payés : c\’est le plus vieil attrape-nigaud de Baille-Fonds.', '', 28153),
(158223, 'frFR', 'Ha ! Vous devriez voir la tête que vous faites !', '', 28153),
(158222, 'frFR', '', 'La seule idée qu\’un esprit puisse échapper à Bwonsamdi est hallucinante. J\’espère que son lien avec ses amis suffira à entrer en contact avec lui de l\’autre côté.', 28153),
(158221, 'frFR', '$n, il y a un télescope à l\’ouest du camp. Peut-être pourriez-vous l\’utiliser pour essayer de le retrouver ?', '', 28153),
(158220, 'frFR', 'Hmm… c\’est vrai, où est Fuzbert ? Il devrait arriver d\’une minute à l\’autre.', '', 28153),
(158219, 'frFR', '', 'Je suis la première à rentrer ? Où est Fuz ?', 28153),
(158218, 'frFR', 'C\’est un plaisir de vous revoir, mademoiselle Étinçacier.', '', 28153),
(158217, 'frFR', '', 'Hé chef ! Vous avez entendu cette détonation ? Je crois que je viens de mettre un Gobelin en orbite.', 28153),
(158216, 'frFR', 'Fuzbert et Kelsey devraient arriver d\’une seconde à l\’autre.', '', 28153),
(158215, 'frFR', 'Hé, qu\’est-ce qu\’il a fait pour moi, le monde ?', '', 28153),
(158214, 'frFR', 'Votre ego est aussi boursouflé que votre corps. Pensez à tout le bien que vous auriez pu faire en ce monde !', '', 28153),
(158213, 'frFR', 'Avec toutes les richesses que vous avez amassées, c\’est ça que vous avez décidé de construire, Gallywix ? Un havre de décadence ?', '', 28153),
(158212, 'frFR', '', 'Utilisez Vivifier pour restaurer tous vos points de vie.', 28153),
(158211, 'frFR', 'Utilisez Vivifier pour restaurer tous vos points de vie.', '', 28153),
(158210, 'frFR', '', 'Qui se bat subit des dégâts, mais vous pouvez vous soigner ou soigner un allié en puisant dans les brumes spirituelles en utilisant Vivifier.', 28153),
(158209, 'frFR', 'Qui se bat subit des dégâts, mais vous pouvez vous soigner ou soigner un allié en puisant dans les brumes spirituelles en utilisant Vivifier.', '', 28153),
(158208, 'frFR', 'L\’Alliance a été vaincue !', '', 28153),
(158207, 'frFR', '|A:Warfront-HordeWave3:25:23:0:0|aUne troupe d\’invasion de la Horde a été déployée !', '|A:Warfront-HordeWave3:25:23:0:0|aUne troupe d\’invasion de la Horde a été déployée !', 28153),
(158206, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLa passe de Vaillehuche a été perdue !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLa passe de Vaillehuche a été perdue !', 28153),
(158205, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aGrangeneuve a été perdue !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aGrangeneuve a été perdue !', 28153),
(158204, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLe cercle des Éléments a été perdu !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLe cercle des Éléments a été perdu !', 28153),
(158203, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aHaut-Perchoir a été perdu !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aHaut-Perchoir a été perdu !', 28153),
(158202, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLa croisée de Nordclos a été perdue !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aLa croisée de Nordclos a été perdue !', 28153),
(158201, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aLe filon de Galson a été perdu !', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aLe filon de Galson a été perdu !', 28153),
(158200, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aLa scierie des Hautes-Terres a été perdue !', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aLa scierie des Hautes-Terres a été perdue !', 28153),
(158199, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aLe filon de Galson est attaqué !', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aLe filon de Galson est attaqué !', 28153),
(158198, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aLa scierie des Hautes-Terres est attaquée !', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aLa scierie des Hautes-Terres est attaquée !', 28153),
(158197, 'frFR', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|aVotre commandant est attaqué !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aVotre commandant est attaqué !', 28153),
(158196, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLa passe de Vaillehuche est attaquée !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLa passe de Vaillehuche est attaquée !', 28153),
(158195, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aGrangeneuve est attaquée !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aGrangeneuve est attaquée !', 28153),
(158194, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLe cercle des Éléments est attaqué !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLe cercle des Éléments est attaqué !', 28153),
(158193, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLa croisée de Nordclos est attaquée !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLa croisée de Nordclos est attaquée !', 28153),
(158192, 'frFR', 'Actionner le gros bouton rouge à votre signal. Compris.', 'Actionner le gros bouton rouge à votre signal. Compris.', 28153),
(158191, 'frFR', 'Montrez-moi où je peux voler.', 'Montrez-moi où je peux voler.', 28153),
(158190, 'frFR', 'Vous allez quelque part ?', '', 28153),
(158189, 'frFR', 'Et voilà, encore une offre qui tombe à l\’eau ! Il y a toujours quelqu\’un pour profiter de la misère des autres !', 'Et voilà, encore une offre qui tombe à l\’eau ! Il y a toujours quelqu\’un pour profiter de la misère des autres !', 28153),
(158188, 'frFR', 'Nous n\’avons plus rien de valeur à vendre.', 'Nous n\’avons plus rien de valeur à vendre.', 28153),
(158187, 'frFR', 'J\’espère que ça suffira pour acheter les provisions dont nous avons besoin.', 'J\’espère que ça suffira pour acheter les provisions dont nous avons besoin.', 28153),
(158186, 'frFR', 'Combien nous reste-t-il d\’or ?', 'Combien nous reste-t-il d\’or ?', 28153),
(158185, 'frFR', 'Les rations sont insuffisantes…', 'Les rations sont insuffisantes…', 28153),
(158183, 'frFR', 'Prudence sur les routes. Des choses étranges se cachent dans les ombres, en Drustvar.', 'Prudence sur les routes. Des choses étranges se cachent dans les ombres, en Drustvar.', 28153),
(158182, 'frFR', 'Oooh… Ooh… Cette armure disjoncte !', '', 28153),
(158181, 'frFR', 'Les corbeaux nous observent ! Ce rire me poursuit où que j\’aille ! Ils finiront par venir me chercher !', '', 28153),
(158180, 'frFR', '', 'À cause de vous… j\’ai renversé… ma bibine…', 28153),
(158179, 'frFR', '', 'Vous cherchez à m\’arnaquer, MOI ? Approchez un peu, que je vous… <Hips !>… embroche, pour voir !', 28153),
(158178, 'frFR', '', 'Beau travail. On se retrouve de l\’autre côté du camp.', 28153),
(158177, 'frFR', 'Regardez ça, Gallywix !', 'Regardez ça, Gallywix !', 28153),
(158176, 'frFR', 'L\’Alliance ? Ici en Zandalar ?', '', 28153),
(158175, 'frFR', 'Nous suivons la voie des sables.', 'Nous suivons la voie des sables.', 28153),
(158174, 'frFR', 'Les dunes grouillent de trésors qui n\’attendent qu\’une chose : qu\’on les découvre.', 'Les dunes grouillent de trésors qui n\’attendent qu\’une chose : qu\’on les découvre.', 28153),
(158173, 'frFR', 'La caravane est mon foyer.', 'La caravane est mon foyer.', 28153),
(158171, 'frFR', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t%s vous cible avec |cFFFF0000|Hspell:271296|h[Broyeur de sang]|h|r !', '', 28153),
(158170, 'frFR', '', 'Ces pauvres âmes… Personne ne mérite un tel sort. Quand Jaina sera hors de danger, nous devrons trouver un moyen de les sauver.', 28153),
(158169, 'frFR', 'Une chose est sûre, Drustvar a sombré dans la folie.', 'Une chose est sûre, Drustvar a sombré dans la folie.', 28153),
(158168, 'frFR', 'Il était question de cerfs se nourrissant de chair humaine.', 'Il était question de cerfs se nourrissant de chair humaine.', 28153),
(158167, 'frFR', 'Cette histoire d\’hommes-bêtes et de démons de bois ? Ouais, je les ai entendus en parler.', 'Cette histoire d\’hommes-bêtes et de démons de bois ? Ouais, je les ai entendus en parler.', 28153),
(158166, 'frFR', 'Vous avez entendu ce qu\’ils disaient ? À propos de ce qui a obligé ces gens à se réfugier ici ?', 'Vous avez entendu ce qu\’ils disaient ? À propos de ce qui a obligé ces gens à se réfugier ici ?', 28153),
(158165, 'frFR', 'Parfois, j\’ai l\’impression de pouvoir communiquer avec mes abeilles en bourdonnant, mais ça ne fonctionnera probablement pas tant que je n\’aurai pas terminé mon costume d\’abeille. Au fait, rien à voir, mais mes petites chéries sont les plus redoutables du coin. Ça vous dirait de les affronter, ou vous préférez jouer les faux bourdons ?', '', 28153),
(158164, 'frFR', '', 'Puisse notre volonté être plus forte que leurs machines de guerre.', 28153),
(158163, 'frFR', 'Les Kaldorei sauront se souvenir de vos actes, $n. En ces temps troublés, votre appui pourrait faire toute la différence.', '', 28153),
(158162, 'frFR', 'L\’heure est grave, mais nous ne pouvons céder au désespoir. La déesse nous donne la force, nous devons nous y accrocher.', '', 28153),
(158161, 'frFR', 'Une bataille seule ne saurait déterminer l\’issue de la guerre. Nous finirons par l\’emporter.', '', 28153),
(158160, 'frFR', 'Le roi Anduin va dépêcher des soldats à notre soutien. Nous devons tenir jusqu\’à leur arrivée.', '', 28153),
(158159, 'frFR', 'Notre flotte est revenue de Silithus. Louée soit Élune ! Nos navires nous fourniront un soutien indispensable.', '', 28153),
(158158, 'frFR', 'Le mur de feux follets résiste, mais les troupes de la Horde gagnent du terrain.', '', 28153),
(158157, 'frFR', 'Voilà qui leur a mis un coup au moral. Ne jamais sous-estimer l\’efficacité de la guerre psychologique.', '', 28153),
(158156, 'frFR', 'Vous avez eu des paroles très dures envers Nathanos.', 'Vous avez eu des paroles très dures envers Nathanos.', 28153),
(158155, 'frFR', 'Les pirates de Port-Liberté s\’enhardissent chaque jour. Nous devons semer le chaos dans leurs rangs. Utilisez l\’une de leurs montures pour les ramener à leur condition de rebuts.', '', 28153),
(158154, 'frFR', '', 'Tous les marins craignent le chant des sirènes. Mais certains ne le craignent pas assez.', 28153),
(158153, 'frFR', '', 'Des sirènes ont pris au piège un autre navire de ravitaillement kultirassien. Cherchez dans les débris tout ce qui pourrait nous être utile. Mais ne vous laissez pas charmer comme l\’équipage !', 28153),
(158152, 'frFR', 'Le destin qui vous attend est bien pire que la mort…', '', 28153),
(158151, 'frFR', 'Ne criez pas victoire ! Ma mort n\’est que le début de votre déchéance !', '', 28153),
(158150, 'frFR', 'Bien joué. L\’équipement de nos ennemis ne fera pas le poids face au nôtre.', '', 28153),
(158149, 'frFR', 'Nous ne pouvons permettre aux Kultirassiens de produire plus de munitions en azérite. Vous devez mettre cette fonderie hors d\’état de fonctionner !', '', 28153),
(158148, 'frFR', '', 'Quand des fanatiques remettent en cause votre loyauté, votre temps en ce monde est compté.\n\nJ\’ai été enrôlée de force dans cette campagne. Peut-être est-ce également votre cas. Nous devons faire tout ce qui est en notre pouvoir et dire tout ce que nous avons à dire pour survivre.\n\nMais sachez une chose : une seule guerre importe. Et ce n\’est pas celle-ci.', 28153),
(158147, 'frFR', 'Vous partagerez… son funeste sort…', '', 28153),
(158146, 'frFR', 'Vous arrivez… trop tard… pour la sauver…', '', 28153),
(158145, 'frFR', 'Vous êtes tous promis… aux pires tourments…', '', 28153),
(158144, 'frFR', 'Elle est déjà… condamnée…', '', 28153),
(158143, 'frFR', 'Notre vengeance est proche !', '', 28153),
(158142, 'frFR', 'La fille est à nous !', '', 28153),
(158141, 'frFR', 'Je vous consumerai, vous aussi !', '', 28153),
(158140, 'frFR', 'Vous partagerez ses souffrances !', '', 28153),
(158139, 'frFR', '', 'Depuis le temps que je travaille dans le secteur, j\’ai découvert des manifestations d\’azérite très intéressantes. Ça vous dit de vous mesurer aux élémentaires d\’azérite errants que j\’ai ramassés en chemin ?', 28153),
(158138, 'frFR', 'PAUVRES FOUS ! Vous vous exposez à des pouvoirs qui vous dépassent !', '', 28153),
(158137, 'frFR', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aHaut-Perchoir est attaqué !', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aHaut-Perchoir est attaqué !', 28153),
(158136, 'frFR', '', 'Pas exactement. Quand une opportunité s\’offre à vous, il faut la saisir.\n\nJ\’ai toujours eu des projets d\’avenir. Il est temps de me donner les moyens de les concrétiser.', 28153),
(158135, 'frFR', 'Je vous croyais au service des Sans-Couronne. Vous avez changé de camp ?', 'Je vous croyais au service des Sans-Couronne. Vous avez changé de camp ?', 28153),
(158134, 'frFR', 'Je suis LIBRE ! Merci… Et maintenant, vos âmes vont combler mon appétit insondable !', '', 28153),
(158133, 'frFR', 'Par quelle région souhaitez-vous que nous commencions ? Dès que vous aurez choisi, nous larguerons les amarres.', '', 28153),
(158132, 'frFR', '', 'Joli travail. Les gardes se chargeront des derniers spécimens. Nous veillerons désormais à toujours garder un œil sur le manoir.', 28153),
(158131, 'frFR', '', 'Des abominations s\’échappent du manoir Malvoie ! Nous devons les intercepter avant qu\’elles atteignent la Ferté-d\’Arom !', 28153),
(158129, 'frFR', 'Nous gagnerons cette guerre, $n. Pour l\’Alliance !', '', 28153),
(158128, 'frFR', 'Cherchez un moyen de contrecarrer les plans du chef de guerre en territoire troll.', '', 28153),
(158127, 'frFR', 'Les avant-postes que vous avez établis en Zandalar sont un premier pas décisif. Nous allons les utiliser pour affronter la Horde sur son terrain !', '', 28153),
(158126, 'frFR', 'Mais le cours de la guerre n\’est jamais paisible. Il est temps de recentrer l\’objectif de notre campagne.', '', 28153),
(158125, 'frFR', 'Je n\’ai jamais eu aussi faim de ma vie…', 'Je n\’ai jamais eu aussi faim de ma vie…', 28153),
(158124, 'frFR', 'Ce que vous avez accompli en Kul Tiras est primordial pour notre cause. Ce n\’est qu\’en nous unissant que l\’Alliance sera plus forte.', '', 28153),
(158123, 'frFR', 'Pour l\’Alliance !', '', 28153),
(158122, 'frFR', 'Quoi qu\’il en soit, sachez que vous êtes une source d\’inspiration pour tous ceux qui vous entourent. Je vous en remercie vivement.', '', 28153),
(158121, 'frFR', 'L\’Alliance a encore besoin de votre aide, $n. Nous ne pourrons mettre un terme au règne du chef de guerre que lorsque nous aurons brisé les liens qui l\’unissent aux Zandalari. Ce jour viendra… bientôt.', '', 28153),
(158120, 'frFR', 'J\’aimerais pouvoir dire que notre tâche est accomplie, mais il y a encore fort à faire. Je crains que les prochains jours s\’assombrissent encore… avant que l\’horizon s\’éclaircisse enfin.', '', 28153),
(158119, 'frFR', 'Vous avez mené une longue campagne contre un ennemi implacable. De plus, vous avez affronté la Horde avec courage… et honneur.', '', 28153),
(158118, 'frFR', '', 'Pour la Horde !', 28153),
(158117, 'frFR', '', 'Vous incarnez ce que la Horde a de meilleur, $n. Je sais que vous serez l\’étincelle qui embrasera Boralus.', 28153),
(158116, 'frFR', '', 'Kul Tiras est devenu un point de ralliement pour l\’Alliance. Le retour de sa célèbre flotte a enhardi les troupes ennemies. Mais ces chiens galeux paieront bientôt le prix de leur insolence.', 28153),
(158115, 'frFR', '', 'La victoire n\’est peut-être pas encore à notre portée, mais elle se rapproche. Nous n\’aurons de repos que lorsque la dernière étincelle d\’espoir aura abandonné l\’enfant-roi.', 28153),
(158114, 'frFR', '', 'Le monde est rempli de soldats. Mais peu sont réellement faits pour la guerre. Vous, en revanche, semblez vraiment être dans votre élément.', 28153),
(158113, 'frFR', '', 'Anéantissez leurs espoirs et vous vaincrez, $n. Pour la Horde !', 28153),
(158112, 'frFR', '', 'Utilisez les avant-postes gagnés en Kul Tiras pour affaiblir les troupes de l\’enfant-roi. Ébranlez leur foi en leur cause futile.', 28153),
(158111, 'frFR', '', 'Mais pour vaincre, renforcer notre puissance ne suffira pas. Nous devons aussi épuiser les forces de l\’ennemi jusqu\’à ce qu\’il rampe à nos pieds.', 28153),
(158110, 'frFR', '', 'Je savais que personne d\’autre n\’était plus à même que vous de gagner les Zandalari à notre cause.', 28153),
(158109, 'frFR', '', 'Quand la princesse Talanji nous a demandé de l\’aide, j\’y ai tout de suite vu la possibilité d\’unir les forces de son royaume aux nôtres.', 28153),
(158108, 'frFR', 'Ici, la terre elle-même, elle est morte. C\’est un cauchemar. Un affreux cauchemar.', '', 28153),
(158107, 'frFR', '', 'Réchauffez-vous les mains et reposez-vous, $c.', 28153),
(158106, 'frFR', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s commence à lancer |cFFFF0000|Hspell:273361|h[Nappe de ténèbres]|h|r !', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s commence à lancer |cFFFF0000|Hspell:273361|h[Nappe de ténèbres]|h|r !', 28153),
(158105, 'frFR', 'Bienvenue à Vent-Vif, $n. L\’avant-poste est sous votre commandement.', '', 28153),
(158104, 'frFR', 'J\’aurais dû… prendre… une extension de garantie…', '', 28153),
(158103, 'frFR', 'Bienvenue au palais de la SOUFFRANCE de Gallywix, sale kleptomane.', '', 28153),
(158102, 'frFR', 'Demander à Fozruk d\’attaquer Ar\’gorok.', 'Demander à Fozruk d\’attaquer Ar\’gorok.', 28153),
(158101, 'frFR', 'La corruption se répand bien plus vite que ce que j\’avais imaginé…', '', 28153),
(158100, 'frFR', 'Ces spores sont tout sauf naturelles. Il faut qu\’on en trouve la source.', '', 28153),
(158099, 'frFR', 'On a fait ce qu\’on pouvait. J\’espère qu\’ils trouveront la paix dans leur prochaine vie.', '', 28153),
(158098, 'frFR', 'Les esprits sont agités, par ici. On doit mettre un terme à leurs tourments.', '', 28153),
(158097, 'frFR', '', 'Vous avez bien agi. À présent, ils sont apaisés.', 28153),
(158096, 'frFR', '', 'Les esprits sont agités. Aidez-les à trouver la paix.', 28153),
(158095, 'frFR', '', 'Avec les spores, on peut trouver la source de la pourriture et la détruire.', 28153),
(158094, 'frFR', '', 'La pourriture se répand vite. Nous devons l\’arrêter. Récupérez des spores pour qu\’on en apprenne plus.', 28153),
(158093, 'frFR', 'Frères et sœurs ! La Horde marche sur Sombrivage ! Rassemblons-nous à la Sinueuse !', '', 28153),
(158092, 'frFR', 'Vous avez été imprégné du pouvoir du vent !', 'Vous avez été imprégnée du pouvoir du vent !', 28153),
(158091, 'frFR', 'Je veux que cet or retourne au palais sur-le-champ et ensuite…', '', 28153),
(158090, 'frFR', 'Pas de retards ! Pas d\’excuses ! Pas de promotions !', '', 28153),
(158089, 'frFR', 'Hors de mon chemin ! L\’Alliance envahit le palais !', '', 28153),
(158088, 'frFR', 'Je refuse de mourir… de la main d\’un Gobelin.', '', 28153),
(158087, 'frFR', 'L\’Alliance compte sur les Elfes du Vide. Nous ne la décevrons pas.', '', 28153),
(158086, 'frFR', 'Gallywiiiiix !', 'Gallywiiiiix !', 28153),
(158085, 'frFR', 'Dégagez ! L\’Alliance nous attaque !', 'Dégagez ! L\’Alliance nous attaque !', 28153),
(158084, 'frFR', '', 'La Horde n\’a eu aucun scrupule à chasser les Furbolgs de leurs terres.', 28153),
(158083, 'frFR', '', 'La Horde… je n\’ai jamais vu autant de soldats…', 28153),
(158082, 'frFR', 'Par le trésor sacré ! D\’où sort cet Elfe ?', 'Par le trésor sacré ! D\’où sort cet Elfe ?', 28153),
(158081, 'frFR', '', 'Bien que les Furbolgs soient d\’ordinaire pacifiques, se faire bouter hors de chez eux a dû les mettre dans une colère noire.', 28153),
(158078, 'frFR', '', 'J\’avance dans les ombres.', 28153),
(158077, 'frFR', '', 'Tout de suite !', 28153),
(158076, 'frFR', '', 'Attention ! Nous devons agir discrètement !', 28153),
(158075, 'frFR', '', 'Tuez-le ! Vite, avant qu\’il n\’alerte les autres !', 28153),
(158074, 'frFR', '', 'Ne vous faites pas repérer ! Nous devons éviter d\’attirer l\’attention…', 28153),
(158073, 'frFR', 'J\’arrive tout de suite, Lanfa !', '', 28153),
(158072, 'frFR', '', 'Après vous, $n. Si vous souhaitez que j\’en neutralise un, prévenez-moi… discrètement.', 28153),
(158071, 'frFR', 'Harli, il va vous y conduire avant de revenir me chercher. Je dois aller voir mon second !', '', 28153),
(158070, 'frFR', 'Ça, c\’était une bonne leçon. On va voir si elle leur reste dans le crâne cette fois-ci.', '', 28153),
(158069, 'frFR', 'Ces petits Nains, ils n\’ont pas l\’air de comprendre qu\’ils sont pas les bienvenus ici ! Montrez-leur comment les Zandalari, ils traitent les intrus.', '', 28153),
(158068, 'frFR', 'Tuez quiconque essaiera de gravir cette colline !', '', 28153),
(158067, 'frFR', 'Une fois la flotte démantelée, Zandalar sera nôtre !', '', 28153),
(158066, 'frFR', 'Qu\’on dresse les piliers !', '', 28153),
(158065, 'frFR', '<Patienter le temps que Genn persuade Katherine au cours d\’une scène de transition époustouflante.>', '<Patienter le temps que Genn persuade Katherine au cours d\’une scène de transition époustouflante.>', 28153),
(158064, 'frFR', 'Les habitants de Kul Tiras sont à nouveau réunis, mais leur maison régnante reste divisée, et cela prive l\’Alliance d\’un de nos dirigeants les plus puissants.\n\nJe garde espoir que l\’on parvienne à combler le fossé qui les sépare.', '', 28153),
(158063, 'frFR', 'Je vous attendrai près du monument familial, au donjon Portvaillant. Avec un peu de chance, nous réussirons à convaincre l\’amiral suprême Portvaillant d\’accorder un sursis à sa fille.', '', 28153),
(158062, 'frFR', 'Héraut, vous avez aidé à l\’unification de Kul Tiras et rallié son soutien à la cause de l\’Alliance. Peut-être serez-vous en mesure de réunir une mère et sa fille.', '', 28153),
(158061, 'frFR', 'Votre intervention a contrarié les desseins de la Horde. Nous vous devons une fière chandelle.', '', 28153),
(158060, 'frFR', 'Ces ignobles gobelins s\’emparent de ressources visant à alimenter leurs machines de guerre ! Mettez un terme à leur forfait !', '', 28153),
(158059, 'frFR', '', 'Nul ne peut arrêter notre progression.', 28153),
(158058, 'frFR', '', 'Ces élémentaires nous serviront à alimenter nos démolisseurs. Abattez-les, ainsi que tous les Kaldorei qui se dresseront sur votre route.', 28153),
(158057, 'frFR', 'Nous pouvons traverser le Vide pour gagner du temps. Suivez-moi.', '', 28153),
(158056, 'frFR', 'Gallywix est une véritable couleuvre. Il ne restera pas longtemps à découvert.', '', 28153),
(158055, 'frFR', 'J\’aurais dû me douter qu\’un Gobelin comme Gallywix ne pourrait pas s\’empêcher de piller une cité entièrement faite d\’or.', '', 28153),
(158054, 'frFR', '', 'Ils nous ont repérés ! Récoltez autant d\’azérite que possible. Chaque minute compte !', 28153),
(158053, 'frFR', '', 'Par la déesse… Je n\’ai jamais vu autant d\’azérite !', 28153),
(158052, 'frFR', 'Des gisements d\’azérite surgissent un peu partout.', 'Des gisements d\’azérite surgissent un peu partout.', 28153),
(158051, 'frFR', '<Placer votre main sur le gisement d\’azérite.>', '<Placer votre main sur le gisement d\’azérite.>', 28153),
(158050, 'frFR', '<Le gisement d\’azérite vibre de puissance contenue.>', '', 28153),
(158049, 'frFR', '', 'Occupez-vous du déchiqueteur. Je vais déloger les envahisseurs du bosquet !', 28153),
(158048, 'frFR', 'Le bosquet des Anciens ! Misère…', 'Le bosquet des Anciens ! Misère…', 28153),
(158047, 'frFR', 'Je m\’en charge !', 'Je m\’en charge !', 28153),
(158046, 'frFR', 'Attention aux Furbolgs. Ils ont subitement débarqué en masse.', 'Attention aux Furbolgs. Ils ont subitement débarqué en masse.', 28153),
(158045, 'frFR', 'J\’y vais !', 'J\’y vais !', 28153),
(158044, 'frFR', 'Les Furbolgs font preuve d\’une agressivité inhabituelle…', 'Les Furbolgs font preuve d\’une agressivité inhabituelle…', 28153),
(158043, 'frFR', '|TInterface\\Icons\\INV_misc_boilingblood:20|t%s vous cible avec |cFFFF0000|Hspell:271224|h[Décharge de plasma]|h|r !', '', 28153),
(158042, 'frFR', 'Ne sous-estimez pas la valeur de vos actes. Le temps que la Horde se remette de cette défaite, nous allons pouvoir étendre notre influence dans la région.', '', 28153),
(158041, 'frFR', 'La Horde cherche à consolider sa présence ici. Empêchez-la d\’agir, héraut !', '', 28153),
(158040, 'frFR', '', 'La meute subsiste. Beau travail.', 28153),
(158039, 'frFR', '', 'Une jeune meute plutôt singulière a besoin d\’aide. Aidez-la pour vous assurer les faveurs de Gonk.', 28153),
(158038, 'frFR', 'Voilà un détachement dont nous n\’entendrons plus parler. Excellent travail.', '', 28153),
(158037, 'frFR', '', 'Zandalar pour toujours !', 28153),
(158036, 'frFR', '', 'Sans $Ucet allié:cette alliée; de la Horde, nos pertes auraient été encore plus grandes.$bTelle est la preuve que, plus que jamais, nous devons nous adapter et faire de nouveau partie de ce monde.', 28153),
(158035, 'frFR', '', 'Que ce glaive rappelle à tous que, quels que soient le prix que nous payons ou les pertes que nous essuyons, nous sommes des Zandalari !$bNous nous adaptons, et nous survivons !', 28153),
(158034, 'frFR', '', 'À lui aussi que nous devons la mort de nombre de nos frères et sœurs.', 28153),
(158033, 'frFR', '', 'Regardez le sang de G\’huun. C\’est à lui que nous devons les morts de Shadra, d\’Hir\’eek, de Torga et de… Rezan.', 28153),
(158032, 'frFR', 'Nos éclaireurs nous ont indiqué la présence d\’un navire de guerre de la Horde au large des côtes. Assurez-vous que les renforts ne touchent jamais terre.', '', 28153),
(158031, 'frFR', '', 'Cet honneur ne me revient pas.', 28153),
(158030, 'frFR', 'Dans ces contrées, nous ne devons rien tenir pour acquis. Merci, héraut. Grâce à vous nos espions vont pouvoir poursuivre leur mission.', '', 28153),
(158029, 'frFR', 'Montre-leur la lame. Deviens le symbole dont il a besoin.', '', 28153),
(158028, 'frFR', 'C\’est toi qui as fait ce qu\’il fallait pour que ton peuple, il soit sauvé. Aujourd\’hui, plus que jamais, il a besoin d\’un chef qu\’il peut croire et aduler.', '', 28153),
(158027, 'frFR', 'Tu as mené notre $Uallié:alliée; sur ces rives contre la volonté même de ton père. Tu as appris les secrets de G\’huun quand tout le monde refusait d\’écouter.', '', 28153),
(158026, 'frFR', 'Plusieurs agents du SI:7 ont été déployés dans cette région, mais nous tardons à recevoir leurs rapports. Découvrez la cause de ce retard et réglez le problème.', '', 28153),
(158025, 'frFR', 'Montre-leur, chef de Zandalar. Montre la lame à ceux qui en ont besoin. Apporte-leur la paix.', '', 28153),
(158024, 'frFR', '', 'Vol\’jin, est-ce que tu nous entends ? Esprit, montre-toi.', 28153),
(158023, 'frFR', 'La Horde paiera de son sang pour chaque parcelle de terrain qu\’elle s\’approprie. Même la plus infime victoire peut faire pencher la balance en notre faveur.', '', 28153),
(158022, 'frFR', 'Sacrifice… Tant de sacrifices. Tant d\’âmes perdues. Tant de vengeance inassouvie. Tant d\’espoir volé par G\’huun.', '', 28153),
(158021, 'frFR', 'Ainsi la Horde pense pouvoir occuper cette région en toute impunité. Prouvez-lui le contraire.', '', 28153),
(158020, 'frFR', '', 'Silence.', 28153),
(158019, 'frFR', 'Je l\’entends !', '', 28153),
(158018, 'frFR', 'Sacrifice…', '', 28153),
(158017, 'frFR', '', 'Vol\’jin, fils de Sen\’jin, entends les voix de ta famille, de tes amis. Tous se demandent où tu es.', 28153),
(158016, 'frFR', 'Placement de l\’azérite', 'Placement de l\’azérite', 28153),
(158015, 'frFR', 'Vous devez défendre le bosquet des Anciens !', 'Vous devez défendre le bosquet des Anciens !', 28153),
(158014, 'frFR', 'Je reste sur mes gardes.', 'Je reste sur mes gardes.', 28153),
(158013, 'frFR', '<L\’aider à se relever.>', '<L\’aider à se relever.>', 28153),
(158012, 'frFR', 'Je vais être franc avec vous. Je n\’ai pas encore touché le fond…\n\nMais je n\’en suis pas loin.', '', 28153),
(158011, 'frFR', '', 'Héraut, les anciens nous appellent ! Trouvez les druides de la Griffe dans la forêt et rejoignez-moi au bosquet des Anciens !', 28153),
(158009, 'frFR', '', 'Vous venez de nous offrir un précieux répit. Sentinelles, tenez la position !', 28153),
(158008, 'frFR', '', 'Ça me dit rien. J\’ai bien peur que votre ami ait succombé à l\’appel des sirènes.', 28153),
(158007, 'frFR', '<Lui demander si elle a vu Flynn.>', '<Lui demander si elle a vu Flynn.>', 28153),
(158006, 'frFR', 'Plus rien ? Comment ça, il n\’y a plus rien ? J\’exige un remboursement !', 'Plus rien ? Comment ça, il n\’y a plus rien ? J\’exige un remboursement !', 28153),
(158005, 'frFR', '', 'Vous n\’êtes pas le seul à consulter les dossiers du SI:7.', 28153),
(158004, 'frFR', 'Comment ça se fait qu\’un général elfe décoré a entendu parler de moi ?', '', 28153),
(158003, 'frFR', '', 'Vous êtes un héros à votre manière, Keeshan. Vous avez servi dans les trois premières guerres et vous avez prouvé votre bravoure dans les Carmines.', 28153),
(158002, 'frFR', 'En ce qui me concerne, je suis à peine digne de servir à vos côtés. Le moins que je puisse faire, c\’est de me taire et de faire preuve de respect.', '', 28153),
(158001, 'frFR', 'Madame, c\’est que j\’ai lu votre dossier du SI:7. Vous avez dix mille ans passés et vous avez livré plus de guerres que je peux en imaginer.', '', 28153),
(158000, 'frFR', '', 'Au repos, Keeshan. Nous sommes entre nous.', 28153),
(157999, 'frFR', 'Elle a dit qu\’elle devrait être en train de massacrer les sbires de l\’Alliance au lieu de perdre son temps avec des bêtises. Après ça, j\’ai compris que j\’avais tout intérêt à filer avant de marchander à nouveau pour recueillir des histoires.', '', 28153),
(157998, 'frFR', 'Cette Areiel que vous cherchez se trouve dans la Nécropole avec une armée de la Horde ! Elle a reçu une missive qui l\’a beaucoup contrariée.', '', 28153),
(157997, 'frFR', 'On va bien s\’amuser ! Je vous dis ce que vous voulez savoir, et en échange, vous me racontez les guerres que vous avez livrées.', '', 28153),
(157996, 'frFR', '', 'J\’ai plus de 10 000 ans et j\’ai participé à toutes les guerres depuis ma naissance. J\’ai même vu de mes propres yeux le Puits d\’éternité originel.', 28153),
(157995, 'frFR', 'Et j\’ai servi au cours des trois premières guerres, je me suis fait capturer par des Orcs particulièrement barbares et j\’ai même aidé à tuer un dragon noir.', '', 28153),
(157994, 'frFR', 'Une bonne histoire ! J\’espérais consigner les récits légendaires de Torga, mais il n\’est plus de ce monde. Connaissez-vous quelques fabuleuses histoires ?', '', 28153),
(157993, 'frFR', 'On vient de vous sauver la vie. Qu\’est-ce qu\’il vous faut de plus ?', '', 28153),
(157992, 'frFR', 'Je veux bien vous renseigner sur la Horde, à condition d\’avoir un petit quelque chose en retour.', '', 28153),
(157991, 'frFR', 'Merci, madame.', '', 28153),
(157990, 'frFR', '', 'Merci pour votre aide, $n, Keeshan. Je vous laisse. Dreven ne doit surtout pas m\’échapper. Élune vous bénisse.', 28153),
(157989, 'frFR', 'Allez-y ! Je vais surveiller le flanc !', '', 28153),
(157988, 'frFR', '', '$n, Keeshan, venez. Regagnons Fort-Victoire… et organisons des funérailles en bonne et due forme pour mes amis.', 28153),
(157987, 'frFR', '', 'Elfes, Humains… Nous sommes tous égaux, Keeshan. Aucun d\’entre nous ne vaut mieux que l\’autre.', 28153),
(157986, 'frFR', 'Je serai… sur pied en moins de deux… mais c\’est injuste. Vos amis, ce sont eux qui auraient dû s\’en tirer, pas moi.', '', 28153),
(157985, 'frFR', '', 'Keeshan ! Louée soit Élune, au moins une personne a survécu à ce massacre.', 28153),
(157984, 'frFR', '<tousse> Madame… je suis pas encore… tout à fait mort. On dirait que son pouvoir… n\’est pas si grand que ça… sans larbins.', '', 28153),
(157983, 'frFR', '', 'Falia… Lyrias… Aeolyn… Keeshan… J\’en fais le serment, $n, Dreven va payer !', 28153),
(157982, 'frFR', 'Rhaaaah !', '', 28153),
(157981, 'frFR', 'Jamais je ne renoncerai, Shandris Pennelune. Voyez comme vos alliés sont faibles !', '', 28153),
(157980, 'frFR', 'Partons. Les esprits, ils peuvent bien rejoindre Bwonsamdi sans nous.', '', 28153),
(157979, 'frFR', 'Les Trolls de sang, ils reviendront. J\’en suis sûr. Mais comme ils savent qu\’on peut frapper leurs villages, ils hésiteront avant de nous attaquer encore.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'frFR', '', 'Shandris, continuez… sans moi…', 28153),
(157977, 'frFR', 'Je vais passer devant pour trouver un point de ralliement sûr. Retrouvez-moi à l\’extérieur du village quand vous aurez fini.', '', 28153),
(157976, 'frFR', 'Abandonnez-vous à la mort, Elfe de la nuit !', '', 28153),
(157975, 'frFR', 'Elle va vous montrer ce qu\’elle a dans le ventre, la larve humaine !', '', 28153),
(157974, 'frFR', '', 'Baissez le bouclier ! C\’est le moment ou jamais ! Stromgarde sera bientôt nôtre !', 28153),
(157973, 'frFR', '', 'À tous les canons : FEU !', 28153),
(157972, 'frFR', '', 'Ouais ?', 28153),
(157971, 'frFR', 'Ils vont certainement nous laisser récupérer nos affaires une fois la fumée dissipée, non ?', 'Ils vont certainement nous laisser récupérer nos affaires une fois la fumée dissipée, non ?', 28153),
(157970, 'frFR', 'Toutes nos possessions étaient au scion des Éternels !', 'Toutes nos possessions étaient au scion des Éternels !', 28153),
(157969, 'frFR', 'Vous allez regretter de ne pas avoir péri dans le brasier de Darnassus !', '', 28153),
(157968, 'frFR', 'Shandris Pennelune, en embuscade ? Quelle audace !', '', 28153),
(157967, 'frFR', 'Peut-être devrais-je faire un exemple de cette larve humaine…', '', 28153),
(157966, 'frFR', '', 'Le massacre prend fin aujourd\’hui, Dreven.', 28153),
(157965, 'frFR', 'Combien de vos compagnons me faudra-t-il tuer pour que vous cessiez enfin de vous mettre en travers de notre route ?', '', 28153),
(157964, 'frFR', 'L\’Alliance. Je savais bien que vous n\’auriez pas l\’intelligence de tirer les leçons de notre dernière rencontre.', '', 28153),
(157963, 'frFR', 'Bon, il est temps pour moi d\’évincer les plus faibles au profit de véritables araignées de combat.', '', 28153),
(157962, 'frFR', 'Un homme, trois araignées, 26 pattes au total… La partie était jouée d\’avance.', '', 28153),
(157961, 'frFR', 'Quand l\’une d\’entre elles tombe, une autre vient prendre sa place !', '', 28153),
(157960, 'frFR', 'Là, là, du calme. Tu veux bien nous aider ?', 'Là, là, du calme. Tu veux bien nous aider ?', 28153),
(157959, 'frFR', '<Flicka vous regarde d\’un air circonspect.>\n\nFlicka ?', '', 28153),
(157958, 'frFR', 'Ouais, c\’est ça. On va faire un malheur ! En avant la musique !', '', 28153),
(157957, 'frFR', 'Je suis prêt à tuer Dreven et ses partisans.', 'Je suis prête à tuer Dreven et ses partisans.', 28153),
(157956, 'frFR', 'Salut à vous. Moi, c\’est Dilbert McClint, expert en désinsectisation. C\’est toujours un plaisir d\’affronter des confrères amateurs d\’araignées.', '', 28153),
(157955, 'frFR', 'Apparemment, on va servir d\’appât pour un groupe d\’Elfes assoiffés de sang. Il faut s\’attendre à tout. Vous êtes d\’attaque ?', '', 28153),
(157954, 'frFR', '', 'Je vais prévenir les autres. Keeshan vous rejoindra dans les tunnels.', 28153),
(157953, 'frFR', '', 'Excellent travail. Nous allons prendre le relais !', 28153),
(157952, 'frFR', '', 'La Horde a franchi nos lignes et tente d\’établir une base ! Prenez votre dragon-faë et mettez leurs troupes en déroute !', 28153),
(157951, 'frFR', 'Vous vous imaginez peut-être que les araignées ne savent pas apprécier le grand air… Détrompez-vous, dans ce domaine, ces créatures sont exactement comme nous. Sans compter que toutes ces toiles sont un signe indéniable d\’une présence arachnéenne dans le bosquet.', '', 28153),
(157950, 'frFR', '', 'Je vous retrouverai près des ruines de Zo\’bal. Ne baissez pas votre garde.', 28153),
(157949, 'frFR', 'Ah, le frisson de la chasse. Savourez-le… Moi, je ne m\’en lasse pas.', '', 28153),
(157948, 'frFR', '', 'Du repos pour les braves épuisés et des vivres pour les bouches affamées.', 28153),
(157947, 'frFR', 'Toujours, princesse.', '', 28153),
(157946, 'frFR', '', 'Je vois. Je rentre à Zuldazar. Tenez-moi informée des opérations de la Horde en Nazmir. Faites attention à vous, Rokhan.', 28153),
(157945, 'frFR', 'Sylvanas, elle veut leur donner une chance. Ils ont nulle part où aller. S\’ils acceptent de bosser pour nous, la Horde, elle les accueillera. Sinon, ils sont cuits.', '', 28153),
(157944, 'frFR', 'Cette créature hante les mers, prenant pour proie chacun des navires que nous envoyons contre Kul Tiras. Mettez un terme à son existence.', '', 28153),
(157943, 'frFR', '', 'Ce Dreven ne m\’inspire aucune confiance, Rokhan. Ce n\’est pas une bonne idée d\’impliquer les San\’layn dans ce conflit.', 28153),
(157942, 'frFR', 'Dans ce cas, c\’est entendu… jusqu\’à nouvel ordre. Nous allons déblayer ce tunnel et nous vous ferons savoir quand la voie sera libre.', '', 28153),
(157941, 'frFR', 'Parce que de par votre accord avec Sylvanas, vous vous êtes engagé à respecter la hiérarchie de la Horde et moi, j\’suis votre supérieur, mon gars.', '', 28153),
(157940, 'frFR', 'Vous voulez que nous nous servions de nos talents pour… déplacer des pierres. Et pourquoi devrais-je vous obéir, Troll ?', '', 28153),
(157939, 'frFR', 'Y a un tunnel effondré entre Nazmir et Vol\’dun. Emmenez vos hommes, utilisez vos pouvoirs pour déblayer l\’chemin et ensuite, on attaquera l\’armée principale de l\’Alliance.', '', 28153),
(157938, 'frFR', '', 'Il y a un tunnel effondré entre Nazmir et Vol\’dun, au sud. Déblayez-le, et la Horde aura le champ libre pour frapper la base principale de l\’Alliance en Vol\’dun.', 28153),
(157937, 'frFR', 'Sylvanas, elle va pas apprécier. Faut qu\’on accélère la manœuvre si on veut arrêter l\’Alliance, prince Dreven.', '', 28153),
(157936, 'frFR', 'Disons que c\’est l\’un de mes talents cachés. L\’Alliance est tombée sur la Horde dans la Nécropole et Areiel a été tuée dans l\’escarmouche.', '', 28153),
(157935, 'frFR', '', 'C\’est princesse Talanji pour vous, prince Dreven. Vos informations, d\’où les tenez-vous ?', 28153),
(157934, 'frFR', 'Le capitaine Areiel ne viendra pas, Talanji. Elle est morte.', '', 28153),
(157933, 'frFR', '', 'Et pourtant, elle manque à l\’appel. Serait-elle trop occupée pour venir faire son rapport ?', 28153),
(157932, 'frFR', 'Areiel, elle a fait un carnage dans les rangs de l\’Alliance et des Trolls de sang. Et elle nous a aidés à établir notre base dans la Nécropole.', '', 28153),
(157931, 'frFR', '', 'Veuillez pardonner mon retard, Rokhan. Dites-moi où vous en êtes. Ce capitaine Areiel… s\’est-elle avérée utile ?', 28153),
(157930, 'frFR', 'Princesse, merci d\’avoir fait tout ce chemin depuis Zandalar. Les Trolls de sang et les envahisseurs de l\’Alliance, on s\’démène pour les repousser.', '', 28153),
(157929, 'frFR', '', 'Bienvenue, $n. L\’avant-poste est placé sous votre autorité.', 28153),
(157927, 'frFR', 'Je suis à votre service.', '', 28153),
(157926, 'frFR', '(Prendre le flacon d\’invisibilité.)', '(Prendre le flacon d\’invisibilité.)', 28153),
(157925, 'frFR', '', 'Restons discrets. Un seul d\’entre nous suffira. Je vais rester là pour m\’assurer que personne ne nous surprenne.\n\nJ\’ai ici un flacon d\’invisibilité qui vous permettra d\’entrer à l\’insu de tous. La potion vous rendra totalement invisible… mais ses effets sont éphémères.\n\nBuvez-la et introduisez-vous dans les ruines. Découvrez ce que trame la Horde et filez dès que possible.', 28153),
(157924, 'frFR', 'Je crains que même nos petites victoires ne fassent que retarder l\’inéluctable.', '', 28153),
(157923, 'frFR', 'Nous tenons les troupes de la Horde en respect, mais une éruption d\’azérite sur la côte vient d\’attirer leur attention. Nous devons les arrêter.', '', 28153),
(157920, 'frFR', 'Approchez, trésor. La vieille Wunja, elle est aveugle, mais pas sourde. Ké hé hé ! Vous venez pour une potion ?', 'Approchez, trésor. La vieille Wunja, elle est aveugle, mais pas sourde. Ké hé hé ! Vous venez pour une potion ?', 28153),
(157919, 'frFR', '', 'Ça ne va pas plaire au Grand Gally…', 28153),
(157918, 'frFR', '', 'J\’vais vous exploser la tronche, littéralement !', 28153),
(157917, 'frFR', 'Mon peuple est prêt, $p. Pour l\’Alliance.', '', 28153),
(157916, 'frFR', '', 'J\’en déduis que vous venez avec moi, $p. On se retrouve au camp du Reliquaire.', 28153),
(157915, 'frFR', 'En avant, Méchazoïd.', '', 28153),
(157914, 'frFR', 'J\’ai participé aux trois guerres, et je croyais avoir vu le pire qu\’Azeroth ait à offrir.\n\nJe me trompais.', '', 28153),
(157913, 'frFR', '', 'J\’ai quelque chose qui peut nous aider.', 28153),
(157912, 'frFR', '', 'Quant à vous, allez voir le capitaine Lune-d\’Été. Il faut consolider ce front !', 28153),
(157911, 'frFR', '', 'Archers à hippogriffe, avec moi. Nous allons nous regrouper à Lor\’danel et nous tenir prêts à réagir en tant qu\’unité d\’intervention mobile !', 28153),
(157910, 'frFR', '', 'Sentinelles, vous allez créer une ligne de front à la Sinueuse ! Alertez nos alliés au bosquet des Anciens !', 28153),
(157909, 'frFR', '', 'Chasseresses, vous partez en renfort à la frontière sud de Sombrivage ! Emmenez les lanceurs de glaives !', 28153),
(157908, 'frFR', '', 'Nous devons réagir ! Sentinelles, en avant !', 28153),
(157907, 'frFR', 'Capitaine, la Horde a atteint la Sinueuse ! Nous ne pourrons pas les retenir très longtemps !', 'Capitaine, la Horde a atteint la Sinueuse ! Nous ne pourrons pas les retenir très longtemps !', 28153),
(157906, 'frFR', 'Un alpaga ! Ouais !', '', 28153),
(157905, 'frFR', 'Vous n\’allez pas changer d\’avis ?', 'Vous n\’allez pas changer d\’avis ?', 28153),
(157904, 'frFR', '', 'À vos ordres !', 28153),
(157903, 'frFR', '<Attaquer sans autre forme de procès.>', '<Attaquer sans autre forme de procès.>', 28153),
(157902, 'frFR', 'Que diriez-vous de quelques pièces d\’or ?', 'Que diriez-vous de quelques pièces d\’or ?', 28153),
(157900, 'frFR', 'Sylvanas désire m\’affronter et je ne compte pas la décevoir. Notre flotte a été informée. Elle devrait bientôt revenir, si telle est la volonté d\’Élune.', '', 28153),
(157899, 'frFR', '$n, je vous charge de défendre Darnassus.', '', 28153),
(157898, 'frFR', 'Delaryn, faites le tour de nos avant-postes, battez le rappel de nos soldats puis revenez ici.', '', 28153),
(157897, 'frFR', '', 'Qu\’allez-vous faire, shan\’do ?', 28153),
(157896, 'frFR', 'La reine banshee projette de soumettre l\’Arbre-Monde.', '', 28153),
(157895, 'frFR', '', 'Malfurion ! Des troupes de la Horde se sont réunies à l\’avant-poste de Zoram\’gar.', 28153),
(157894, 'frFR', 'Vous pouvez franchir le mur, $n. Les feux follets ne vous feront aucun mal.', '', 28153),
(157893, 'frFR', '', 'Même aux portes de la mort, vous ne voyez pas le vrai potentiel des Humains.', 28153),
(157892, 'frFR', '', 'Et vous vous raccrochez encore et toujours à vos clichés obsolètes sur les Humains. J\’aurais dû vous tuer il y a bien longtemps.', 28153),
(157891, 'frFR', '', 'Le destin a jugé bon de m\’accorder la vie éternelle, je refuse de mourir ici !', 28153),
(157890, 'frFR', '', 'Vous perdez votre temps à vous battre aux côtés de ce sale Humain, Shandris ! Leur vie est si brève, si insignifiante.', 28153),
(157889, 'frFR', '', 'Shandris, ça doit bien faire, quoi… deux, trois mille ans ? Si on m\’avait dit que nous nous retrouverions en pareilles circonstances, et que vous aideriez un Humain, par-dessus le marché…', 28153),
(157888, 'frFR', '', 'Les ténèbres… Sylvanas… C\’est donc ça que vous aviez vu ? Ce que vous cherchiez à nous épargner ?', 28153),
(157887, 'frFR', '', 'Et moi qui m\’attendais à une simple mission de reconnaissance. On va bien s\’amuser !', 28153),
(157886, 'frFR', '', '… C\’est terminé. Trouvez ses plans et regagnez le guet de Rougechamp quand vous en aurez fini.', 28153),
(157885, 'frFR', '|cFF0000FF(Quête)|r Cap sur Xibala, à Zuldazar.', '|cFF0000FF(Quête)|r Cap sur Xibala, à Zuldazar.', 28153),
(157884, 'frFR', 'Excellent travail ! Nos troupes vont désormais pouvoir traverser la zone sans risque.', '', 28153),
(157883, 'frFR', 'Le rhum, c\’est pour les vrais Lamineurs. Bas les pattes !', 'Le rhum, c\’est pour les vrais Lamineurs. Bas les pattes !', 28153),
(157882, 'frFR', 'Il est déjà assez compliqué d\’établir des voies de ravitaillement à travers les marais sans que des créatures magiques s\’en mêlent. Abattez celle-ci, que nous puissions poursuivre notre avancée.', '', 28153),
(157881, 'frFR', '', 'Beau travail ! Cette créature ne nous posera plus de problème.', 28153),
(157880, 'frFR', '', 'Cette créature est animée par un mojo obscur ! Envoyez son âme chez Bwonsamdi.', 28153),
(157879, 'frFR', '', 'Une nouvelle victoire.', 28153),
(157878, 'frFR', 'Bwonsamdi, on l\’interrompt pas sans en payer le prix. Va falloir vous mettre ça dans le crâne ! Ouste, dégagez !', '', 28153),
(157877, 'frFR', '', 'Mes éclaireurs signalent une soudaine éruption d\’azérite dans les environs, en Sombrivage. Aidez nos alliés gobelins à récupérer le précieux minerai.', 28153),
(157876, 'frFR', 'Ne vous approchez pas trop de Bwonsamdi !', 'Ne vous approchez pas trop de Bwonsamdi !', 28153),
(157875, 'frFR', 'Pourquoi les oreilles ?$B$BHm, c\’est tout simplement ce qu\’on appelle la CLASSE.', '', 28153),
(157874, 'frFR', 'Tous des voleurs, ces Hozen ! Si y en a un qu\’a touché à mon rhum, je fais un massacre.', 'Tous des voleurs, ces Hozen ! Si y en a un qu\’a touché à mon rhum, je fais un massacre.', 28153),
(157873, 'frFR', 'Pas touche à mon rhum, bande de rats !', 'Pas touche à mon rhum, bande de rats !', 28153),
(157872, 'frFR', 'Interrompre le pacte entre la Horde et les Zandalari est notre priorité. Et pour y arriver, nous allons devoir établir des avant-postes en territoire ennemi.', '', 28153),
(157871, 'frFR', 'Il est temps de montrer à la Horde que la 7e Légion doit être prise au sérieux, $n.', '', 28153),
(157870, 'frFR', '', 'Soldats… Non ! Ne faites pas ça… !', 28153),
(157869, 'frFR', 'Ça marche ce truc ? Un, deux, un deux. OK.', '', 28153),
(157868, 'frFR', 'Haha, vous les avez proprement envoyés promener ! Ils vont mettre du temps pour remobiliser leurs troupes. Beau travail.', '', 28153),
(157867, 'frFR', 'Nous avons réussi à nous emparer d\’une autre arme de siège de la Horde. Il est temps de la retourner contre leur propriétaire !', '', 28153),
(157866, 'frFR', 'Non ! C\’est impossible ! Le boss va être furieux. Le bon vieux Bwonsamdi peut pas perdre un esprit comme ça… Oh, c\’est pas bon du tout.', '', 28153),
(157865, 'frFR', 'Allons, Vol\’jin, fais pas le timide, sors de ton urne. Une seconde… Non ! Où est son esprit ? Où est Vol\’jin ?', '', 28153),
(157864, 'frFR', 'Du vent, héraut. J\’ai rien pour vous.', '', 28153),
(157863, 'frFR', 'Par chance, les ouvriers se fichent éperdument qu\’on fouine dans les parages, contrairement aux gros bras de la compagnie.\n\nVous avez trouvé notre bonheur ?', '', 28153),
(157862, 'frFR', 'Nous avons fait du bon travail, aujourd\’hui. Regroupons-nous à l\’extérieur.', 'Nous avons fait du bon travail, aujourd\’hui. Regroupons-nous à l\’extérieur.', 28153),
(157861, 'frFR', '', 'Il faut à tout prix arrêter Jakra\’zet.', 28153),
(157860, 'frFR', 'Et le roi, qu\’est-ce qu\’il fait pour nos terres ?', 'Et le roi, qu\’est-ce qu\’il fait pour nos terres ?', 28153),
(157859, 'frFR', 'Les ressources de Hurlevent commencent à manquer. Il n\’y en aura pas assez pour tout le monde.', 'Les ressources de Hurlevent commencent à manquer. Il n\’y en aura pas assez pour tout le monde.', 28153),
(157858, 'frFR', 'Non, non, non. Faut pas laisser traîner ça ici.', '', 28153),
(157857, 'frFR', 'Joli travail ! Mes hommes n\’auront plus à craindre ce prédateur.', '', 28153),
(157856, 'frFR', 'Au lieu de se battre pour des ruines, l\’Alliance ferait mieux de reprendre notre patrie !', 'Au lieu de se battre pour des ruines, l\’Alliance ferait mieux de reprendre notre patrie !', 28153),
(157855, 'frFR', 'C\’est le deuxième foyer que nous perdons.', 'C\’est le deuxième foyer que nous perdons.', 28153),
(157854, 'frFR', 'Où allons-nous nous réfugier, à présent ?', 'Où allons-nous nous réfugier, à présent ?', 28153),
(157853, 'frFR', 'Beau travail. Sa mort va permettre aux prochaines générations de prospérer.', '', 28153),
(157852, 'frFR', 'La donne a changé et les enjeux n\’en sont que plus grands, général. Il faut nous adapter.', '', 28153),
(157851, 'frFR', '', 'Nous ne pouvons pas laisser ce monstre nous échapper, Verroctone.', 28153),
(157850, 'frFR', 'Dehors, les Sombrelances ! C\’est endroit que pour Trolls raffinés, ici !', '', 28153),
(157849, 'frFR', 'La vermine de la Horde, elle est pas digne de cet endroit. Nous les Furie-des-sables, on vous défie !', 'La vermine de la Horde, elle est pas digne de cet endroit. Nous les Furie-des-sables, on vous défie !', 28153),
(157848, 'frFR', '', 'Merci, Alleria. Votre aide est la bienvenue.', 28153),
(157847, 'frFR', 'Sage stratégie. Ça me va.', '', 28153),
(157846, 'frFR', '', 'Nous le traquerons et nous vous rapporterons sa tête. Pendant ce temps, Shandris pourra se concentrer sur la chasse de ce prince de sang.', 28153),
(157845, 'frFR', '', 'Mes Elfes du Vide peuvent se charger de mener l\’attaque contre Gallywix.', 28153),
(157844, 'frFR', '', 'Alleria ouvre un portail du Vide derrière elle.', 28153),
(157843, 'frFR', '', 'Nous avons là deux cibles prioritaires que nous ne pouvons pas laisser filer… D\’ailleurs, ce n\’est pas nécessaire.', 28153),
(157842, 'frFR', '', 'Désolée de vous interrompre, mais je crois que vous avez raison tous les deux.', 28153),
(157841, 'frFR', '', 'J\’ai vu de quoi Dreven est capable, Verroctone. Et s\’il y en avait d\’autres comme lui ?', 28153),
(157840, 'frFR', 'Stratégiquement parlant, c\’est lui, leur point faible, et il s\’expose rarement. Il faut frapper sur-le-champ.', '', 28153),
(157839, 'frFR', 'Gallywix finance la campagne de guerre de la Horde et comprend l\’azérite mieux que n\’importe lequel de ses autres chefs.', '', 28153),
(157838, 'frFR', '', 'Nous pourrons toujours tuer ce grippe-sou de Gobelin une autre fois ! Si Dreven nous échappe, nous ne le reverrons peut-être jamais.', 28153),
(157837, 'frFR', 'Nous nous occuperons bientôt du prince de sang Dreven, général. Mais nous avons là une occasion unique d\’estropier l\’armée de la Horde. Le reste peut attendre.', '', 28153),
(157836, 'frFR', 'Une bête volante donne mes troupes en pâture à sa progéniture ! Faites-lui découvrir le goût de l\’acier.', '', 28153),
(157835, 'frFR', 'Les suppôts de la Horde, ils sont pas les bienvenus dans cet endroit sacré !', '', 28153),
(157834, 'frFR', '', 'Nos alliés attendent vos instructions.', 28153),
(157833, 'frFR', 'La grande Pa\’ku, elle a décidé que Ji\’arak avait passé bien assez de temps parmi nous. Rassemblez vos forces et tuez cette créature.', '', 28153),
(157832, 'frFR', 'Bienvenue, $n. Nous avons beaucoup à faire.', '', 28153),
(157831, 'frFR', 'C\’est… du sang ? Pour de vrai ? Vous êtes en train de me dire que cette chose est protégée par un bouclier de sang ?\n\nDécidément… on aura tout vu.', '', 28153),
(157830, 'frFR', '', 'À nous le cercle ! Tout le monde à son poste !', 28153),
(157829, 'frFR', 'La guerre suivante. Et celle encore après.', '', 28153),
(157828, 'frFR', 'La Lumière perdurera bien après notre mort. Quand cette guerre sera terminée, que vous restera-t-il, Shaw ?', '', 28153),
(157827, 'frFR', 'Votre foi en la Lumière ou en Turalyon ?', '', 28153),
(157826, 'frFR', 'Bien au contraire. Assister au retour de Turalyon, et voir que la Lumière l\’avait tenu en vie, l\’avait transformé, cela n\’a fait que renforcer ma détermination. Je sais que ma foi n\’était pas vaine.', '', 28153),
(157825, 'frFR', 'Quand vous avez appris que Turalyon était toujours vivant, cela a-t-il remis en cause vos choix et votre dévotion ?', '', 28153),
(157824, 'frFR', 'La Lumière m\’a ouvert les yeux quand il disparut en Outreterre avec l\’expédition de l\’Alliance. J\’ai compris que je pouvais être à la fois soldat et paladin. J\’ai alors juré d\’honorer son sacrifice.', '', 28153),
(157823, 'frFR', 'Mais parmi ces premiers paladins, un m\’a particulièrement inspiré… Turalyon. Sa foi lui donnait sa force, nourrissait son dévouement, et faisait de lui un meneur extraordinaire.', '', 28153),
(157822, 'frFR', 'Drukan pique un somme.', '', 28153),
(157821, 'frFR', 'J\’ai servi en tant que chevalier lorsque la Main d\’argent fut fondée. J\’avais des doutes sur ma capacité à allier compétences martiales et prêtrise. Aussi, j\’ai préféré privilégier l\’entraînement au combat.', '', 28153),
(157820, 'frFR', 'Comment se fait-il qu\’un paladin se retrouve à la tête de soldats d\’élite, Verroctone ? Ne devriez-vous pas consacrer des temples, ou quelque chose dans ce genre ?', '', 28153),
(157819, 'frFR', 'Oh, bien sûr.', '', 28153),
(157818, 'frFR', 'C\’est très aimable à vous, mais si je devais choisir entre l\’honneur et le devoir qui m\’incombe, je choisirais le dernier sans hésiter. Pour l\’Alliance, évidemment.', '', 28153),
(157817, 'frFR', 'Je dois admettre qu\’en tant que paladin, je me suis posé la question du bien-fondé des espions et des assassins dans les rangs de l\’Alliance. Mais l\’honneur et la loyauté dont vous avez fait montre envers notre roi sont indiscutables.', '', 28153),
(157816, 'frFR', 'Le SI:7 a été créé pour œuvrer en coulisse. Je préfère rester dans l\’ombre, où je ne suis pas aussi… exposé.', '', 28153),
(157815, 'frFR', 'J\’ai arrêté de compter. Je vais là où l\’Alliance me l\’ordonne… et où la Lumière m\’appelle. Mais vous n\’êtes pas étranger au combat non plus.', '', 28153),
(157814, 'frFR', 'Ça vous fait combien de campagnes contre la Horde, Verroctone ?', '', 28153),
(157813, 'frFR', 'Faites attention avec ce truc, $n.', '', 28153),
(157812, 'frFR', 'Je m\’suis dit que ça vous intéresserait.', '', 28153),
(157811, 'frFR', 'L\’atelier a ouvert ses portes ! Si vous avez b\’soin de quoi que ce soit, on a de l\’huile de coude à r\’vendre !', '', 28153),
(157810, 'frFR', 'Les dégâts infligés à Croc-de-Guerre seront rendus au centuple !', '', 28153),
(157809, 'frFR', 'Je n\’ai plus peur de la mort, c\’est la mort qui a peur de moi…', '', 28153),
(157808, 'frFR', 'Le chef de guerre ne laissera pas cet affront impuni.', '', 28153),
(157807, 'frFR', 'La mort est trop douce pour vous.', '', 28153),
(157806, 'frFR', 'Je vais me repaître de votre cadavre !', '', 28153),
(157805, 'frFR', 'Je vais vous fendre en deux !', '', 28153),
(157804, 'frFR', '', 'Bien joué, mais quelque chose me dit qu\’ils essaieront de nouveau.', 28153),
(157803, 'frFR', '', 'Des pirates pillent à nouveau la colline de la Vigie ! Quand retiendront-ils la leçon ? Aidez les soldats de la marine à les repousser !', 28153),
(157802, 'frFR', 'Merci ! Je file rejoindre ma famille.', 'Merci ! Je file rejoindre ma famille.', 28153),
(157801, 'frFR', 'Haha, vous avez vu leur tête ? Ça valait son pesant d\’or ! Ils vont passer des jours à nettoyer !', '', 28153),
(157800, 'frFR', 'La Horde, c\’est rien que des barbares !', 'La Horde, c\’est rien que des barbares !', 28153),
(157799, 'frFR', 'Mieux vaut éradiquer une telle abjection… avant qu\’elle infecte la Horde.', '', 28153),
(157798, 'frFR', 'Bien joué. Nous ne pouvons rester les bras croisés pendant que les abysses corrompent nos terres !', '', 28153),
(157797, 'frFR', 'Avec Venrik, on avait l\’habitude de se prendre une biture et de faire une petite balade à dos de perroquet ensuite. Essayez donc, et écrasez ces brigands de votre « justice céleste » !', '', 28153),
(157796, 'frFR', 'Un concassage dans les règles…', '', 28153),
(157795, 'frFR', 'J\’ai mal… calculé mon coup.', '', 28153),
(157794, 'frFR', 'Cette abomination n\’est que folie et corruption faites chair. Détruisez-la immédiatement !', '', 28153),
(157793, 'frFR', 'J\’espère seulement que ma famille a pu s\’échapper à temps.', 'J\’espère seulement que ma famille a pu s\’échapper à temps.', 28153),
(157792, 'frFR', 'La fumée était si dense qu\’on s\’y serait perdus si la reine Grisetête n\’avait pas été là.', 'La fumée était si dense qu\’on s\’y serait perdus si la reine Grisetête n\’avait pas été là.', 28153),
(157791, 'frFR', 'Nous devons renvoyer cette créature dans les abysses. Détruisez-la !', '', 28153),
(157790, 'frFR', 'Nous en avons réchappé de justesse.', 'Nous en avons réchappé de justesse.', 28153),
(157789, 'frFR', 'Pourquoi faire une chose pareille ?', 'Pourquoi faire une chose pareille ?', 28153),
(157788, 'frFR', 'Vous me tapez sérieusement sur les engrenages !', '', 28153),
(157787, 'frFR', 'Tout ça est à moiiiii !', '', 28153),
(157786, 'frFR', 'Je vais vous perforer façon gruyère !', '', 28153),
(157785, 'frFR', '', 'Cela aurait été une perte terrible pour la garde des Portvaillant. Grâce à vous, ça n\’a été qu\’un léger contretemps.', 28153),
(157784, 'frFR', '', 'Un de nos navires de ravitaillement s\’est échoué dans l\’estuaire au sud. L\’équipage a réussi à s\’en tirer, mais il a dû laisser des biens de valeur sur place.', 28153),
(157783, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Le porteguerre Yenajz commence à lancer |cFFF00000|Hspell:274932|h[Abysses infinis]|h|r !', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t Le porteguerre Yenajz commence à lancer |cFFF00000|Hspell:274932|h[Abysses infinis]|h|r !', 28153),
(157782, 'frFR', 'C\’est… de l\’alcool ?! Moi qui espérais trouver un trésor… pour m\’ACHETER de l\’alcool !', '', 28153),
(157781, 'frFR', 'Le bruit court à Port-Liberté qu\’un de ces pirates a un joli pactole planqué dans l\’eau, près des quais. Essayez de le trouver !', '', 28153),
(157780, 'frFR', 'Beau travail. Voilà qui devrait limiter le nombre d\’armes à azérite à Boralus, le temps que la mutinerie des Corsandre soit matée.', '', 28153),
(157779, 'frFR', 'La compagnie marchande Corsandre poursuit sa production d\’armes, malgré les ordres. Saccagez cette fonderie, mais évitez de blesser des civils.', '', 28153),
(157778, 'frFR', 'Hé, ne vous inquiétez pas. Nous leur trouverons de nouveaux foyers. Ce qui compte, c\’est qu\’ils soient hors de danger.', '', 28153),
(157777, 'frFR', 'La compagnie marchande Corsandre attire des orphelins avec la promesse d\’un repas chaud et les exploite jusqu\’à la moëlle. Sortez-les de ce pétrin !', '', 28153),
(157776, 'frFR', 'On raconte qu\’Azuréthos pouvait emporter un kraken dans ses griffes. Ce combat aurait pu vous être fatal. Vous allez entrer dans la légende par cet exploit.', '', 28153),
(157775, 'frFR', 'Dans les chants des marins, le mythique Azuréthos peut faire chavirer un galion d\’un coup de vent. Eh bien, les légendes disent vraies ! Tuez-le, et c\’est vous dont on chantera le nom.', '', 28153),
(157774, 'frFR', '', 'Présentez-vous au haut seigneur Saurcroc. Faites-les payer leur folie ! Pour la Horde !', 28153),
(157773, 'frFR', 'Chaque fois que je ferme les yeux, je revois ce brasier infernal.', 'Chaque fois que je ferme les yeux, je revois ce brasier infernal.', 28153),
(157772, 'frFR', 'J\’espère que nos amis sont sains et saufs.', 'J\’espère que nos amis sont sains et saufs.', 28153),
(157771, 'frFR', 'Nous ne pouvons pas abandonner Kalmidor.', 'Nous ne pouvons pas abandonner Kalmidor.', 28153),
(157770, 'frFR', 'Je n\’arrive pas à croire que l\’Arbre-Monde ait… disparu…', 'Je n\’arrive pas à croire que l\’Arbre-Monde ait… disparu…', 28153),
(157769, 'frFR', 'Ces monstres de la Horde ont détruit notre foyer !', 'Ces monstres de la Horde ont détruit notre foyer !', 28153),
(157768, 'frFR', 'Que voulez-vous ? Hmm, vous m\’avez tout l\’air d\’être ingénieur, vous aussi…', '', 28153),
(157767, 'frFR', 'J\’ai une autre question à vous poser.', 'J\’ai une autre question à vous poser.', 28153),
(157766, 'frFR', 'Ce cuisinier dégénéré ? Je crois que c\’est un cousin éloigné. C\’est triste, il est obnubilé par les explosifs en tout genre, avec une nette préférence pour les gros calibres. Le véritable génie, ce serait d\’inventer une source de puissance capable d\’alimenter en continu tout un tas de machines à déchiqueter, à forer ou à exploser tout ce qui bouge.', '', 28153),
(157765, 'frFR', 'Bonjour, docteur. J\’aimerais vous acheter l\’un de vos réacteurs. Et je suis prêt à y mettre le prix.', 'Bonjour, docteur. J\’aimerais vous acheter l\’un de vos réacteurs. Et je suis prête à y mettre le prix.', 28153),
(157764, 'frFR', 'C\’est vous, le docteur Boum ?', 'C\’est vous, le docteur Boum ?', 28153),
(157763, 'frFR', 'À qui le dites-vous ! Je vois que vous êtes bel et bien un petit génie de l\’ingénierie ! Pas autant que moi, mais ce n\’est pas donné à tout le monde.', '', 28153),
(157762, 'frFR', '', 'Je sais pas qui c\’est, mais j\’peux vous dire qu\’on doit s\’débarrasser d\’elle !', 28153),
(157761, 'frFR', 'Docteur, la conception de cet engin est admirable !', 'Docteur, la conception de cet engin est admirable !', 28153),
(157760, 'frFR', '', 'Tout le monde à l\’Enclume noire ! On doit évaluer les dégâts !', 28153),
(157759, 'frFR', 'Hé, vous voyez pas que je travaille, là ? Revenez quand vous aurez un minimum d\’expérience en ingénierie.', '', 28153),
(157758, 'frFR', '', 'Bien, vous les avez r\’mis à leur place comme il faut ! Allez, ouvrons la porte. J\’peux déjà vous dire qu\’ils sont nombreux de l\’autre côté. Faites gaffe à vous !', 28153),
(157757, 'frFR', 'J\’ai passé les cinq dernières années à retaper et à bricoler l\’équipe de robots la plus meurtrière jamais imaginée. Vous voulez voir comment vos vulgaires familiers de bas étage s\’en sortent contre les créations du plus brillant technicien trafico-réparateur de l\’univers ?', '', 28153),
(157756, 'frFR', 'Comment ça, une panne ?! Ce n\’était pas prévu au programme, ça !', '', 28153),
(157755, 'frFR', 'Mon génie prodigieux au service de machines encore plus prodigieuses, voilà la combinaison gagnante.', '', 28153),
(157754, 'frFR', '', 'Bon débarras ! En réduisant cet assemblage en poussière, vous avez épargné bien des malheurs à Drustvar.', 28153),
(157753, 'frFR', '', 'Un immense assemblage de pierre s\’est réveillé dans les montagnes non loin ! Nous devons l\’abattre avant qu\’il s\’en prenne aux habitants de Drustvar !', 28153),
(157752, 'frFR', 'Impensable ! La prochaine fois, je les ferai deux fois plus grands.', '', 28153),
(157751, 'frFR', 'Rien ni personne ne peut rivaliser avec mon équipe, je suis imbattable !', '', 28153),
(157750, 'frFR', 'Préparez-vous à affronter mon équipe invaincue de robots ultra sophistiqués !', '', 28153),
(157749, 'frFR', 'Je suis prêt à y aller, Krag\’wa.', 'Je suis prête à y aller, Krag\’wa.', 28153),
(157748, 'frFR', 'En ce moment même, les Trolls de sang continuent à massacrer mes enfants.$b$bJe vais vous aider à atteindre leur chef, mais il me faut regagner le marais en toute hâte pour protéger mes petits.', '', 28153),
(157747, 'frFR', 'Krag\’wa, le chef des Trolls de sang, s\’est retranché dans ce vaste bâtiment, au loin. De grâce, prêtez-nous main-forte.', 'Krag\’wa, le chef des Trolls de sang, s\’est retranché dans ce vaste bâtiment, au loin. De grâce, prêtez-nous main-forte.', 28153),
(157746, 'frFR', 'Euh… Hmm. Pas maintenant, Venrik. On est là pour parler affaires.', '', 28153),
(157745, 'frFR', '', 'Je suis ici pour vous aider. Aux armes !', 28153),
(157744, 'frFR', '', 'Je lutte pour mon peuple.', 28153),
(157743, 'frFR', '', 'Une proie facile. Éliminez-moi ça en vitesse !', 28153),
(157742, 'frFR', 'Tu sais, celle qui avait les « cheveux noir corbeau ». Hahaha !', '', 28153),
(157741, 'frFR', '', 'À la mémoire de Darnassus !', 28153),
(157740, 'frFR', '', 'Oui, il me tarde de quitter cet endroit maudit.', 28153),
(157739, 'frFR', '', 'Sortons d\’ici avant que ces… choses… ne reviennent à la charge.', 28153),
(157738, 'frFR', '', 'Oui… ne t\’inquiète pas.', 28153),
(157737, 'frFR', 'Alors raconte, Flynn. Qu\’est devenue cette femme dont tu parlais à tout bout de champ ?', '', 28153),
(157736, 'frFR', '', 'Mère ! Tout va bien ?', 28153),
(157735, 'frFR', '', 'Vous voulez bien aller r\’prendre le marteau ? Il est drôlement puissant et si les Gobelins apprennent à s\’en servir, ce sera un sale coup pour nous.', 28153),
(157734, 'frFR', '', '$n, j\’ai une aut\’ mission pour vous. Ces sauvages sont de la KapitalRisk. Autrement dit, ils vont se rendre à Kezan pour livrer Hostefer aux sales pattes du nabab Razzbam.', 28153),
(157733, 'frFR', '', 'Thane-enclume, Sombrenclume, trouvez un moyen d\’réparer l\’Enclume noire.', 28153),
(157732, 'frFR', '', 'Argh, Hostefer a disparu et ils ont cassé l\’Enclume noire en deux !', 28153),
(157731, 'frFR', '', 'Et jamais Kul Tiras ne capitulera.', 28153),
(157730, 'frFR', 'Les Drust… n\’abandonneront… jamais…', '', 28153),
(157729, 'frFR', 'Bon sang de bois !', '', 28153),
(157728, 'frFR', 'Ouvrez les yeux, vous deux ! Visez plutôt l\’Enclume noire !', '', 28153),
(157727, 'frFR', '', 'Nom d\’une barbe en magma ! Ça doit être ce gros méca qui m\’est rentré dedans !', 28153),
(157726, 'frFR', 'Y a un gros balèze qui m\’est tombé dessus et qu\’a volé Hostefer !', '', 28153),
(157725, 'frFR', '', 'Ça va, merci. Toi, par contre, c\’est pas la grande forme.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'frFR', 'Reine régente ! Tout va bien, ma grande ?!', '', 28153),
(157723, 'frFR', '', 'Allez, les enfants, on remballe !', 28153),
(157722, 'frFR', '', 'Mon peuple a déjà battu ton engeance de malheur par le passé, monstre. Et nous recommencerons !', 28153),
(157721, 'frFR', 'Les Ulterres vous dévoreront tous ! J\’aurai enfin ma vengeance !', '', 28153),
(157720, 'frFR', '', 'Juste au moment où la chance commençait à nous sourire.', 28153),
(157719, 'frFR', '', '<Moira marmonne tout bas.>', 28153),
(157718, 'frFR', '', 'Thaelin, à la Chambre de l\’artisanat ! Ils s\’dirigent peut-être vers la Voûte noire.', 28153),
(157717, 'frFR', '', 'Vous, occupez-vous d\’sécuriser la grand-route des Sombrefer !', 28153),
(157716, 'frFR', '', 'Thane-enclume, prépare tes ensorceleurs pour la contre-attaque !', 28153),
(157715, 'frFR', '', 'Ces raclures verdâtres osent nous attaquer chez nous ?!', 28153),
(157714, 'frFR', 'Des Gobelins ! Dans les tunnels !', '', 28153),
(157713, 'frFR', '', 'Aux armes, $n !', 28153),
(157712, 'frFR', '', 'Tu t\’en es pris à la mauvaise famille, démon !', 28153),
(157711, 'frFR', '', 'Mère !', 28153),
(157710, 'frFR', '', 'Mère, attention !', 28153),
(157709, 'frFR', '', 'Ouah, c\’est un costaud, çui-là !', 28153),
(157708, 'frFR', 'Vous ne m\’échapperez pas !', '', 28153),
(157707, 'frFR', '', 'Viens vite, nous devons sortir d\’ici.', 28153),
(157706, 'frFR', '', 'En v\’là d\’autres !', 28153),
(157705, 'frFR', '', 'Élémentaires en approche !', 28153),
(157704, 'frFR', '', 'On a découvert qu\’en appliquant une puissante magie à l\’azérite, on pouvait obtenir des résultats inattendus.', 28153),
(157703, 'frFR', '', 'Jaina ? C\’est bien toi ?', 28153),
(157702, 'frFR', 'Ce que ce ronchon je-sais-tout essaie d\’vous dire, c\’est qu\’il va falloir nous couvrir quand les élémentaires vont rappliquer.', '', 28153),
(157701, 'frFR', 'Vous arrivez… trop tard…', '', 28153),
(157700, 'frFR', 'Quand on travaille l\’azérite, on tombe forcément sur des anomalies spontanées, $c. Vous pensez que vous pourrez gérer ça ?', '', 28153),
(157699, 'frFR', 'Posez-moi encore d\’l\’azérite sur l\’enclume, vous voulez bien, $n ?', '', 28153),
(157698, 'frFR', 'Ce sera bientôt votre tour !', '', 28153),
(157697, 'frFR', 'Imbéciles ! Elle est brisée, vous ne pouvez plus rien pour elle !', '', 28153),
(157696, 'frFR', 'Oui, reine régente.', '', 28153),
(157695, 'frFR', '', 'Thaelin, Thurgaden, un peu de nerf !', 28153),
(157694, 'frFR', '', 'Assez ! Montre-nous ton vrai visage, monstre !', 28153),
(157693, 'frFR', '', 'C\’est en bonne voie. Anduin arrête pas d\’nous tanner pour avoir des nouvelles, alors autant vous montrer ce qu\’on a découvert.', 28153),
(157692, 'frFR', '', 'Mes meilleurs gars travaillent au raffinage de l\’azérite depuis qu\’elle est apparue dans nos galeries.', 28153),
(157691, 'frFR', '', 'Merci d\’être là, $n.', 28153),
(157690, 'frFR', '', 'Père… s\’il vous plaît…', 28153),
(157689, 'frFR', '', 'Je vous retrouverai près de la statue sur la colline.', 28153),
(157688, 'frFR', '', 'Grand Krag\’wa, nous avons besoin de ton aide !', 28153),
(157687, 'frFR', 'Exactement comme la Troisième guerre.', '', 28153),
(157686, 'frFR', 'Pour la compagnie Bravo !', '', 28153),
(157685, 'frFR', 'Exactement comme sur Draenor !', '', 28153),
(157684, 'frFR', 'Ça me rappelle la Deuxième guerre.', '', 28153),
(157683, 'frFR', 'Mph, mph mph mph.', 'Mff mff mff mff mff.', 28153),
(157682, 'frFR', 'Récapitulons notre plan pour tuer le capitaine Areiel.', 'Récapitulons notre plan pour tuer le capitaine Areiel.', 28153),
(157681, 'frFR', 'Général.', '', 28153),
(157680, 'frFR', '', 'Il faut agir dès maintenant. $n va prendre la tête des opérations ; le reste d\’entre nous sera là pour l\’aider et partir en reconnaissance. Vous êtes du voyage, Keeshan.', 28153),
(157679, 'frFR', '', 'Nous devons sauver les Tortollans pour qu\’ils nous renseignent sur les déplacements de la Horde. Ça devrait nous mener tout droit au capitaine Areiel.', 28153),
(157678, 'frFR', 'Madame. D\’après nos renseignements, il y a des Tortollans de Nazmir qui pourraient nous en dire plus sur les agissements de la Horde. Les Trolls de sang en ont capturé plusieurs.', '', 28153),
(157677, 'frFR', 'J\’aime la pêche sans hameçon !', 'J\’aime la pêche sans hameçon !', 28153),
(157676, 'frFR', 'J\’ai l\’œil du poisson-tigre !', 'J\’ai l\’œil du poisson-tigre !', 28153),
(157675, 'frFR', '', 'Nous avons besoin d\’informations et d\’alliés en Nazmir pour parvenir à nos fins. Par chance, une occasion s\’offre à nous. Keeshan ?', 28153),
(157674, 'frFR', '', 'La mort du capitaine Areiel va compromettre les opérations de la Horde en Nazmir et affaiblir les forestiers-sombres de Sylvanas.', 28153),
(157673, 'frFR', 'Ces Trolls s\’en prennent à mes enfants depuis trop longtemps ! Aujourd\’hui, c\’est moi qui pars à la chasse.', '', 28153),
(157672, 'frFR', 'J\’ai toujours cru que le Reflux mort, c\’était dans l\’autre direction.', '', 28153),
(157671, 'frFR', '', 'C\’est agréablement calme depuis la disparition de Nedly.', 28153),
(157670, 'frFR', 'Nous ne pouvons pas laisser cela se produire. Rassemblez vos alliés. Stromgarde appartient à l\’Alliance !', '', 28153),
(157669, 'frFR', 'Mais la Horde rassemble ses troupes pour nous arracher le contrôle du fort. Si elle y parvient, elle s\’arrogera une position stratégique cruciale dans les royaumes de l\’Est.', '', 28153),
(157668, 'frFR', 'Stromgarde était une place forte essentielle du temps de l\’Alliance de Lordaeron. Nous avons l\’intention de lui rendre sa grandeur.', '', 28153),
(157667, 'frFR', 'Organisez une expédition et emparez-vous de cette azérite… avant la Horde.', '', 28153),
(157666, 'frFR', 'Les éclaireurs de Shaw ont découvert des gisements d\’azérite sur de nombreuses îles à la surface du globe. L\’Alliance a besoin de ces ressources.', '', 28153),
(157665, 'frFR', 'Les agents que vous recruterez seront chargés de saper les efforts de la Horde… et de nous assurer la victoire.', '', 28153),
(157664, 'frFR', 'Montez une équipe d\’agents infiltrés avec Mathias Shaw. Nul n\’est mieux qualifié pour cette tâche que le maître-espion de Hurlevent.', '', 28153),
(157663, 'frFR', 'En temps de guerre, la victoire repose sur la puissance des armes. Mais parfois, la situation requiert une approche plus… subtile.', '', 28153),
(157662, 'frFR', 'Je suis prêt à invoquer Krag\’wa.', 'Je suis prête à invoquer Krag\’wa.', 28153),
(157661, 'frFR', '', 'Zelling discute avec sa famille. Ne vous en mêlez pas, j\’interviendrai si c\’est nécessaire.', 28153),
(157660, 'frFR', '', 'Mettez leur discrétion et leur ruse à profit pour dévoiler les faiblesses des défenses ennemies… et les exploiter.', 28153),
(157659, 'frFR', '', 'À l\’aide de Garona Miorque, assemblez une unité d\’agents parmi les plus rusés et retors de la Horde. Vous les enverrez en missions d\’infiltration dans tout Kul Tiras et Zandalar.', 28153),
(157658, 'frFR', '', 'Pour mettre toutes les chances de notre côté, j\’envoie également un agent aux compétences… uniques. Ses talents seront précieux pour cette mission.', 28153),
(157657, 'frFR', '', 'Vous devez agir rapidement. Profitez de la nuit pour chercher discrètement les débris. Les patrouilles de l\’Alliance se multiplient dans ces eaux.', 28153),
(157656, 'frFR', '', 'Nathanos, la conversion de frère Zelling porte déjà ses fruits. Il a révélé l\’emplacement de l\’épave que nous recherchons.', 28153),
(157655, 'frFR', '', 'L\’enfant-roi envoie maintenant ses sous-fifres pour le reconquérir. Nous ne devons pas les laisser y parvenir.', 28153),
(157654, 'frFR', '', 'Stromgarde était un haut lieu de pouvoir de l\’Alliance au cœur des royaumes de l\’Est… avant que le bastion tombe en ruine.', 28153),
(157653, 'frFR', '', 'Nous devons profiter de cet avantage. Explorez ces îles et revendiquez-les… avant que l\’Alliance s\’en charge.', 28153),
(157652, 'frFR', '', 'Nos alliés gobelins prouvent une fois encore leur valeur. Ils ont repéré des gisements d\’azérite sur des îles partout sur Azeroth.', 28153),
(157651, 'frFR', '', 'En temps de guerre, une lame bien placée entre deux côtes fait parfois plus de dégâts qu\’un millier d\’épées sur le champ de bataille.', 28153),
(157650, 'frFR', '', 'Mildenhall a vraiment perdu la tête ! On dirait que l\’hydromellerie est envahie par ses expériences. Allez y jeter un œil, avant que les choses dérapent.', 28153),
(157649, 'frFR', '', 'Je vous remercie, votre Horde et vous, pour m\’avoir aidée à libérer mon équipage.\n\nTant que je serai à la barre, les Voiles-de-Brume continueront à sillonner les mers librement !', 28153),
(157648, 'frFR', '', 'Le sacrifice final, c\’était lui… On a échoué.', 28153),
(157647, 'frFR', 'Non… C\’est impossible !', '', 28153),
(157646, 'frFR', 'Mais ça ne saurait tarder !', '', 28153),
(157645, 'frFR', 'Souffrance ? Vous n\’avez encore rien vu de la vraie souffrance…', '', 28153),
(157644, 'frFR', 'Taelia, quand vous aurez le temps, rendez-moi visite à Hurlevent. J\’ai de nombreuses anecdotes à partager sur votre père.', '', 28153),
(157643, 'frFR', '', 'Un jour, je n\’ai plus reçu de lettres. J\’ai… j\’ai tellement de questions sur lui.', 28153),
(157642, 'frFR', '', 'Offrez-lui une mort rapide. On a vu assez de souffrance pour aujourd\’hui.', 28153),
(157641, 'frFR', '', '« Mon étoile scintillante ».', 28153),
(157640, 'frFR', 'Je me souviens maintenant… il vous écrivait. Il vous donnait même un surnom…', '', 28153),
(157639, 'frFR', 'Le généralissime Bolvar était un grand homme. Un véritable héros pour l\’Alliance… et pour moi.', '', 28153),
(157638, 'frFR', '', 'Vous connaissiez mon père ?', 28153),
(157637, 'frFR', '<Jakra\’zet grogne.>', '', 28153),
(157636, 'frFR', 'Taelia… relevez-vous. Tout l\’honneur est pour moi.', '', 28153),
(157635, 'frFR', '', 'La fille de Bolvar, placée sous notre protection depuis la Troisième guerre.', 28153),
(157634, 'frFR', 'Fordragon ?!', '', 28153),
(157633, 'frFR', '', 'Taelia Fordragon.', 28153),
(157632, 'frFR', '', 'C\’est un honneur de vous rencontrer, roi Wrynn. Je m\’appelle Taelia.', 28153),
(157631, 'frFR', '', 'Votre émissaire et elle ont joué un grand rôle dans la protection du royaume… et de ma propre personne.', 28153),
(157630, 'frFR', '', 'Roi Wrynn, j\’aimerais vous présenter quelqu\’un.', 28153),
(157629, 'frFR', 'Je suis heureux et honoré d\’accueillir à nouveau Kul Tiras au sein de l\’Alliance. Que la Lumière nous mène à la victoire.', '', 28153),
(157628, 'frFR', '', 'Merci… à vous tous. Je ferai tout mon possible pour me montrer digne de votre confiance.', 28153),
(157627, 'frFR', '', 'Qu\’en dites-vous ?', 28153),
(157626, 'frFR', '', 'C\’est la fin, général. Les complots, les mensonges, les meurtres.', 28153),
(157625, 'frFR', '', 'Sam ! Non !', 28153),
(157624, 'frFR', 'CHANTORAGE !', '', 28153),
(157623, 'frFR', 'Vous avez œuvré à votre propre perte, Pike. Je dois livrer la flotte à notre rédemptrice… Azshara.', '', 28153),
(157622, 'frFR', 'Je ne vois que des âmes errantes, suppliant qu\’on les libère.', '', 28153),
(157621, 'frFR', 'C\’est fini, Chantorage ! Regardez autour de vous… Vous êtes encerclé !', '', 28153),
(157620, 'frFR', 'Vous étiez vraiment dans votre élément. Je sais que je peux compter sur vous pour mettre le chaos !', '', 28153),
(157619, 'frFR', 'Nous n\’avons pas grand-chose qui peut servir d\’arme, alors il faut être inventif. Trouvez un moyen de leur infliger de lourds dégâts et revenez avant qu\’ils aient compris ce qui leur arrive.', '', 28153),
(157618, 'frFR', '', 'Qui sait les dégâts que cette chose aurait pu infliger à la flotte ? Grâce à vous, nous n\’aurons pas à le découvrir.', 28153),
(157617, 'frFR', '', 'Tu es trop faible pour régner, Katherine.', 28153),
(157616, 'frFR', '', 'Et moi qui ai presque… Priscilla… comment avez-vous pu trahir le royaume ? … Et me trahir, moi ?', 28153),
(157615, 'frFR', '', 'Ce golem pourrait couper un navire en deux ! Ne laissons pas une telle arme entre les mains du seigneur Chantorage.', 28153),
(157614, 'frFR', '', 'Vous avez engagé la flotte pirate, vous l\’avez armée et vous l\’avez envoyée tuer votre propre peuple.', 28153),
(157613, 'frFR', '', 'Ça s\’appelle de l\’azérite… L\’Alliance et la Horde se la disputent déjà.', 28153),
(157612, 'frFR', '', 'Votre société a FABRIQUÉ les armes qui ont détruit la porte de Daelin, avec ceci !', 28153),
(157611, 'frFR', '', 'Dame Priscilla Corsandre, vous êtes en état d\’arrestation pour trafic d\’armes, conspiration avec des pirates et haute trahison contre l\’amirauté de Kul Tiras.', 28153),
(157610, 'frFR', 'L\’océan nous donne beaucoup, mais sous sa surface ne subsiste que le désespoir.', '', 28153),
(157609, 'frFR', '', 'Que signifie ceci, jeune fille ?!', 28153),
(157608, 'frFR', '', 'Alors, c\’était donc votre plan depuis le début. C\’est abject.\n', 28153),
(157607, 'frFR', '', 'Une menteuse !', 28153),
(157606, 'frFR', 'Une horreur du fond des âges a pris corps. Renvoyez-la dans les abysses.', '', 28153),
(157605, 'frFR', '', 'Dame Corsandre est mon roc depuis ces jours sombres où nous avons toutes deux perdu notre mari. À compter de ce jour, elle sera le roc de ce royaume. Désormais… elle est…', 28153),
(157603, 'frFR', '', 'Mais cela n\’a pas suffi.', 28153),
(157602, 'frFR', '', 'Une bonne opération ! Nos troupes combattront sur la terre ferme encore quelque temps.', 28153),
(157601, 'frFR', 'La dernière fois que j\’ai vu autant de fumée, la grand-mère Havreport tentait d\’apprendre à son dadais de petit-fils à cuisiner. Excellent travail !', '', 28153),
(157600, 'frFR', '', 'Honte à vous !', 28153),
(157599, 'frFR', '', 'Les Nagas ont fait venir un engin de siège vivant pour détruire la digue ! Aux armes !', 28153),
(157598, 'frFR', 'Des pirates ?! Les Portvaillant ne sont même plus capables de nous protéger des pirates !', '', 28153),
(157597, 'frFR', '', 'Une flotte pirate a employé une force de feu écrasante…', 28153),
(157596, 'frFR', 'La fureur de la tempête est imprévisible et dangereuse, mais vous la surpassez mille fois.', '', 28153),
(157595, 'frFR', 'Voilà qui porte la marque des eaugures. Faites le nécessaire pour endiguer leur magie !', '', 28153),
(157594, 'frFR', 'À chaque fois qu\’on pense leur avoir porté un coup sérieux, ils reconstruisent encore plus vite. Nous devons couper leur approvisionnement en bois ! Brûlez tout !', '', 28153),
(157593, 'frFR', '', 'Les rumeurs étaient vraies. La porte de Daelin… est tombée.', 28153),
(157592, 'frFR', 'J\’ai entendu de sacrées explosions. Vous avez laissé autre chose que des ruines derrière vous ?', '', 28153),
(157591, 'frFR', '', 'La récolte est sauvée, grâce à vous ! Nous allons tenter de réimplanter ces petits monstres loin des terres agraires.', 28153),
(157590, 'frFR', '', 'Je savais que l\’effort en vaudrait la peine ! Nous avons de la chance qu\’elle soit parmi nous !', 28153),
(157589, 'frFR', '', 'Quelque chose mange les graines des fermiers avant qu\’elles aient le temps de germer. Débarrassez-nous-en !', 28153),
(157588, 'frFR', '', 'Mademoiselle Havreport nous a demandé quelques articles pour contribuer à l\’effort de guerre. Cette vieille dame est un sacré personnage. Nous serions fous de refuser !', 28153),
(157587, 'frFR', 'Nous éradiquerons leur corruption encore et encore, jusqu\’à ce que le sanctuaire des Tempêtes soit purifié.', '', 28153),
(157586, 'frFR', 'Les démons veulent souiller nos terres les plus sacrées. Nous ne pouvons le tolérer !', '', 28153),
(157585, 'frFR', '', 'Je sais bien que chasser les nuisibles n\’est pas très gratifiant, mais je suis sûre que les habitants du hameau du Meunier vous sont reconnaissants.', 28153),
(157584, 'frFR', '', 'Les habitants du hameau du Meunier n\’ont vraiment pas de chance. Leurs greniers sont infestés de nuisibles. Aidez-les à faire le ménage.', 28153),
(157583, 'frFR', 'Un jour prochain, le son joyeux des eaugures lançant leurs premiers sorts retentira à nouveau dans ces terres… mais ce n\’est pas pour aujourd\’hui.', '', 28153),
(157582, 'frFR', '', 'Espérons que cela incitera les derniers de ces géants de malheur à retourner chez eux, dans les montagnes !', 28153),
(157581, 'frFR', 'L\’emprise de mon ancien maître est toujours très forte. Éradiquez-en toute trace.', '', 28153),
(157580, 'frFR', 'Merci. Les habitants de la vallée n\’oublieront jamais vos exploits.', '', 28153),
(157579, 'frFR', '', 'Les Ettins terrorisent le hameau du Meunier, et les civils n\’ont aucun moyen de les combattre. Nous sommes leur seul espoir !', 28153),
(157578, 'frFR', 'Nous avons besoin de vous à Brennadam. Nous n\’avons toujours pas assez de soldats pour organiser une contre-attaque.', '', 28153),
(157577, 'frFR', 'Parlez au capitaine Angelica quand vous voudrez embarquer.', '', 28153),
(157576, 'frFR', '', 'Désolée, j\’aurais dû vous demander si vous étiez allergique aux abeilles avant de vous envoyer là-bas. Mais vous vous portez bien, je sais à qui faire appel la prochaine fois !', 28153),
(157575, 'frFR', 'Merci d\’avoir répondu si vite, $n. Vous prendrez le large avec la Troisième flotte.', '', 28153),
(157574, 'frFR', 'Une telle cruauté ne devrait jamais avoir l\’occasion de s\’épanouir dans notre monde.', '', 28153),
(157573, 'frFR', '', 'Les abeilles de l\’hydromellerie terrorisent à nouveau les habitants, et devinez quoi, les fermiers ont perdu le contrôle de la situation. Quelle surprise !', 28153),
(157572, 'frFR', 'C\’est le roi Anduin qui m\’envoie, maître-espion.', 'C\’est le roi Anduin qui m\’envoie, maître-espion.', 28153),
(157571, 'frFR', '', 'Il se passe quelque chose dans cette ferme qui a affolé les wendigos. Ils restaient sagement dans leur coin, avant que les Mildenhall s\’installent.', 28153),
(157570, 'frFR', '', 'Nous avons appris que l\’hydromellerie Mildenhall a des soucis de wendigos. Vous pourriez y aller pour offrir votre aide ?', 28153),
(157569, 'frFR', 'Les K\’thir pratiquent librement leur magie noire à bord de la Mélodie abyssale. Purifiez ce navire de leur souillure.', '', 28153),
(157568, 'frFR', 'Nous sommes peut-être surpassés en nombre, mais grâce à vous, nous ne nous décourageons pas.', '', 28153),
(157567, 'frFR', 'Les eaugures déchus ont asservi des marins perdus et menacent d\’envahir le croisement des Marées ! Arrêtez-les !', '', 28153),
(157566, 'frFR', '', 'Cette créature devait être autrefois un vénérable fongicien. Quel tragique destin pour un si noble guerrier.', 28153),
(157565, 'frFR', '', 'Nous avons été informés de la présence d\’une créature de grande puissance dans une grotte au sud. Faites attention… Ce qu\’on en dit me fait froid dans le dos…', 28153),
(157564, 'frFR', '', 'Bon travail, mais je crains que ce ne soit pas la dernière fois que nous devions l\’aider…', 28153),
(157563, 'frFR', 'Nous n\’avons pas encore réussi à déloger la Horde d\’ici. Ruinez sa production, quoi qu\’il en coûte. Faites sauter la zone entière, s\’il le faut !', '', 28153),
(157562, 'frFR', '', 'Toutes les armes qui sortent des fonderies de Chantorage devraient protéger le peuple, pas l\’oppresser.', 28153),
(157561, 'frFR', 'C\’était peut-être une tâche simple pour une personne de votre expérience, mais cela devait être fait.', '', 28153),
(157560, 'frFR', 'Le pavillon Kennings tarde à exécuter les ordres de l\’amirauté suite à certaines… complications. Quelqu\’un comme vous devrait pouvoir y remédier sans problème.', '', 28153),
(157559, 'frFR', '', 'Ce serait vraiment dommage de laisser perdre toutes ces munitions. Vous savez ce qu\’il vous reste à faire.', 28153),
(157558, 'frFR', 'C\’est à nous de les tenir en échec, maintenant que la milice est partie.', '', 28153),
(157557, 'frFR', 'Une fois de plus, les Hurans préparent quelque chose dans leur kraal. Sabotez leurs plans avant qu\’ils reprennent des forces !', '', 28153),
(157556, 'frFR', 'Nura, je suis là pour vous aider.', 'Nura, je suis là pour vous aider.', 28153),
(157555, 'frFR', '', 'Qu\’est-ce qui vous amène jusqu\’ici ?', 28153),
(157554, 'frFR', 'Retrouvons-nous en ville pour se partager tout ça !', '', 28153),
(157553, 'frFR', 'Pouvez-vous me rapprocher de la Haute-route des Tarides du Sud ?', 'Pouvez-vous me rapprocher de la Haute-route des Tarides du Sud ?', 28153),
(157552, 'frFR', 'Un navire sans voiles, c\’est comme une cavalerie sans chevaux. Il ne vaut rien, tout simplement.', '', 28153),
(157551, 'frFR', 'Une terrifiante tempête menace nos stocks de gréements. Apaisez-la tant que c\’est encore possible !', '', 28153),
(157550, 'frFR', 'Vous avez rendu hommage au legs d\’Addington. Je vous en remercie.', '', 28153),
(157549, 'frFR', 'Frère Addington aurait été indigné par tant de dépravation. Reconquérez les chantiers en son nom !', '', 28153),
(157548, 'frFR', '', 'Tout commence par des matériaux bruts. Le reste provient d\’un travail acharné et d\’un cœur droit.', 28153),
(157547, 'frFR', '', 'Les charpentiers de Chantorage sont légendaires, mais ils ne sont rien sans bois. Rétablissez l\’ordre !', 28153),
(157546, 'frFR', '', 'J\’espère qu\’ils comprendront la leçon. Chantorage restera ouverte à tous !', 28153),
(157545, 'frFR', '', 'Les troupes du seigneur Chantorage ont décrété un nouveau blocus ! Brisez-le, que les marchands puissent à nouveau passer !', 28153),
(157544, 'frFR', 'Allons, dépêchez-vous !', '', 28153),
(157543, 'frFR', 'Parlez à Isabella. Elle vous fera rejoindre notre point de ralliement à Fossoyeuse.', '', 28153),
(157542, 'frFR', 'Une fois que nous aurons rassemblé les renforts, je vous exposerai la situation.', '', 28153),
(157541, 'frFR', 'Merci d\’être $Uvenu:venue; si vite, $n. Il n\’y a pas une minute à perdre.', '', 28153),
(157540, 'frFR', 'Protéger, nourrir, guider. C\’est là, la véritable mission des eaugures.', '', 28153),
(157539, 'frFR', 'Les eaugures prêtent le serment sacré de protéger notre peuple. Aidez-nous à le respecter, sauvez ces pauvres âmes !', '', 28153),
(157538, 'frFR', 'Nos ennemis sont impitoyables. Mais grâce à vous, nous pourrons continuer de nous battre.', '', 28153),
(157537, 'frFR', 'On dirait que le rituel a échoué. La magie des Nagas ne doit surtout pas corrompre les mers plus avant.', '', 28153),
(157536, 'frFR', 'Les sujets d\’Azshara accomplissent un nouveau rituel, suite à leur récente défaite. Faites-leur donc goûter aux abysses auxquels ils se raccrochent si désespérément.', '', 28153),
(157535, 'frFR', '', 'Les Nagas deviennent de plus en plus agressifs. Je m\’inquiète de ce que cela peut vouloir dire pour nous.', 28153),
(157534, 'frFR', '', 'Le Sillage des tempêtes ne s\’est pas encore remis de l\’attaque des Nagas. Aidez-les à sortir de ce mauvais pas, le temps qu\’ils se rétablissent !', 28153),
(157533, 'frFR', 'Nos troupes auraient grand besoin de ces ressources. Emparez-vous-en pour notre cause !', '', 28153),
(157532, 'frFR', 'Que les marées vous bénissent. Ils ne s\’empareront pas de cette vallée tant que nous serons debout !', '', 28153),
(157531, 'frFR', 'Il faut une première fois pour tout… espérons qu\’il n\’y en ait pas de seconde, en ce qui nous concerne.', '', 28153),
(157530, 'frFR', 'Hmm, je ne sais trop qu\’en penser, mais il se passe quelque chose d\’étrange en ville. Essayez de tirer ça au clair.', '', 28153),
(157529, 'frFR', '', 'Si tu renonces à tes sentiments, tu te perdras dans les ténèbres.', 28153),
(157528, 'frFR', '', 'Jaina, ma chérie… La raison seule ne peut guider tous nos choix.', 28153),
(157527, 'frFR', '', 'C\’est une illusion, Jaina ! Rien de tout cela n\’est réel !', 28153),
(157526, 'frFR', '', 'Mais… ils m\’ont menti…', 28153),
(157525, 'frFR', 'J\’ai commis une erreur en te croyant digne de nous guider !', '', 28153),
(157524, 'frFR', 'Tu as laissé tes préjugés corrompre le Kirin Tor !', '', 28153),
(157523, 'frFR', '', 'J\’aurais tant souhaité que ton père comprenne cette leçon.', 28153),
(157522, 'frFR', '', 'Chercher à enrayer la spirale de la violence est une noble intention, Jaina.', 28153),
(157521, 'frFR', 'Les armées du seigneur Chantorage menacent de reprendre cette zone. Assurez-vous qu\’elle ne tombe pas entre leurs mains !', '', 28153),
(157520, 'frFR', '', 'Ne la touchez pas !', 28153),
(157519, 'frFR', 'Hir\’eek, c\’est le Loa de la nuit. C\’est tout ce que vous avez besoin de savoir.', 'Hir\’eek, c\’est le Loa de la nuit. C\’est tout ce que vous avez besoin de savoir.', 28153),
(157518, 'frFR', '', 'Tout est ma faute…', 28153),
(157517, 'frFR', 'Mais… Tu as retenu ma lame. Sais-tu combien de soldats de l\’Alliance ont péri ce jour-là ? Combien sont morts dans les batailles qui ont suivi ?', '', 28153),
(157516, 'frFR', 'J\’aurais pu les anéantir ! Sylvanas… Thrall… Pense à ce que notre monde aurait pu devenir sans eux et leur maudite Horde !', '', 28153),
(157515, 'frFR', '', 'Non ! Encore une de ces créatures qui tourmentent Jaina. Vite !', 28153),
(157514, 'frFR', '', 'Cette voix… Daelin ?', 28153),
(157513, 'frFR', '', 'Encore une illusion ? Jaina ne doit plus être très loin.', 28153),
(157512, 'frFR', '', 'Nous devons la trouver… et l\’arracher à cet endroit maudit.', 28153),
(157511, 'frFR', '', 'Ma fille est là, quelque part. Elle se cache. Rongée par la douleur.', 28153),
(157510, 'frFR', 'Quelle bataille ! Les courants porteront le récit de vos exploits pendant de nombreuses années.', '', 28153),
(157509, 'frFR', '', 'Poursuivons les recherches.', 28153),
(157508, 'frFR', '', 'Elle a disparu. Il s\’agissait d\’une illusion… Un écho de la souffrance de Jaina.', 28153),
(157507, 'frFR', '', '… Mais même les meilleurs ne peuvent sauver le monde à eux seuls.', 28153),
(157506, 'frFR', '', 'Jaina… tu étais… tu es… la fierté de Kul Tiras, sa force, sa fureur…', 28153),
(157505, 'frFR', '', 'Non ! Ne les écoute pas, Jaina !', 28153),
(157504, 'frFR', '', 'Je les ai trahis… tous…', 28153),
(157503, 'frFR', '', 'Vous auriez pu l\’arrêter ! Vous auriez pu nous sauver !', 28153),
(157502, 'frFR', 'Je viens au rapport, haut seigneur.', 'Je viens au rapport, haut seigneur.', 28153),
(157501, 'frFR', 'Le Sillage des tempêtes a de nouveau besoin de vous. Que les marées vous mènent à la victoire.', '', 28153),
(157500, 'frFR', 'Vous nous avez livrés à la mort !', '', 28153),
(157499, 'frFR', '', 'Je vous suis, $p.', 28153),
(157498, 'frFR', '', 'Je finissais toujours par la retrouver… et cette fois ne fera pas exception.', 28153),
(157497, 'frFR', '', 'Enfant, Jaina se cachait quand elle avait peur ou qu\’elle était contrariée.', 28153),
(157496, 'frFR', '', 'Attends !', 28153),
(157495, 'frFR', '', 'Non ! Vous pouvez pas m\’aider ! Personne peut m\’aider !', 28153),
(157494, 'frFR', '', 'Calme-toi, ma chérie…', 28153),
(157493, 'frFR', '', 'Jaina n\’est plus très loin. Pressons !', 28153),
(157492, 'frFR', 'Les Ulterres… vous dévoreront…', '', 28153),
(157491, 'frFR', '', 'Pas si j\’ai mon mot à dire !', 28153),
(157490, 'frFR', 'L\’héritière des Portvaillant est à nous !', '', 28153),
(157489, 'frFR', '', '$n, nous devons la suivre !', 28153),
(157488, 'frFR', '', 'Jaina, attends !', 28153),
(157487, 'frFR', '', 'Non ! N\’approchez pas !', 28153),
(157486, 'frFR', '', 'Jaina ?!', 28153),
(157485, 'frFR', '', 'Tout est… ma faute…', 28153),
(157484, 'frFR', '', 'Les confins Corrompus… Ces lieux portent bien leur nom…', 28153),
(157483, 'frFR', 'Que les marées vous bénissent. Notre vallée est à nouveau sûre.', '', 28153),
(157482, 'frFR', 'Par les profondeurs abyssales… Cette aberration doit cesser de menacer notre peuple !', '', 28153),
(157481, 'frFR', 'Que cela serve de leçon à quiconque dénature les dons de la mère des marées.', '', 28153),
(157480, 'frFR', 'Un tel outrage à la puissance de la mer doit être détruit.', '', 28153),
(157479, 'frFR', 'Torga a beau avoir faibli, nous autres Tortollans perpétuons la mémoire de sa puissance.', '', 28153),
(157478, 'frFR', 'Arrêtons-nous ici un moment, $p.', '', 28153),
(157477, 'frFR', 'Gral, c\’est un sage parmi les Loas. Il a toujours une longueur d\’avance. Le grand large, c\’est son royaume et les abysses, sa chasse gardée.', 'Gral, c\’est un sage parmi les Loas. Il a toujours une longueur d\’avance. Le grand large, c\’est son royaume et les abysses, sa chasse gardée.', 28153),
(157476, 'frFR', 'Puisse la marée les rejeter, comme ils ont rejeté leur peuple.', '', 28153),
(157475, 'frFR', 'Ça nous ôte un certain nombre d\’épines du pied ! Beau travail.', '', 28153),
(157474, 'frFR', 'Les Hurans préparent quelque chose dans la ferme proche de leur kraal. Vous ne pourriez pas y faire un tour et mettre un terme à leurs manigances ?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'frFR', 'Une autre âme corrompue a répondu à l\’appel du seigneur Chantorage. Il ne faut pas la laisser ruiner nos efforts !', '', 28153),
(157472, 'frFR', 'Trouve le repos, âme tourmentée. Tes souffrances sont finies.', '', 28153),
(157471, 'frFR', 'Mes frères ont créé de telles horreurs… Mettez un terme au calvaire de cette créature.', '', 28153),
(157470, 'frFR', 'J\’y vais...', 'J\’y vais...', 28153),
(157469, 'frFR', 'Oui... messire.', 'Oui... messire.', 28153),
(157468, 'frFR', 'Qu\’est-che que ch\’est ?', 'Qu\’est-che que ch\’est ?', 28153),
(157467, 'frFR', 'Bon, je file !', 'Bon, je file !', 28153),
(157466, 'frFR', 'Encore du travail ?', 'Encore du travail ?', 28153),
(157465, 'frFR', '', 'Je vais voir, chef !', 28153),
(157464, 'frFR', 'J\’aperçois un autre petit site de fouilles à l\’ouest d\’ici. Kelsey ?', '', 28153),
(157463, 'frFR', 'Restons groupés. Nous ne pouvons pas échouer maintenant !', '', 28153),
(157462, 'frFR', 'Comme je le soupçonnais, les principaux sites de fouilles du Reliquaire se trouvent plus au sud.', '', 28153),
(157461, 'frFR', 'La Horde a mis le feu aux bâtiments ! Éteignez les flammes avant que toute la vallée ne parte en fumée !', '', 28153),
(157460, 'frFR', 'Beau travail ! L\’incendie est maîtrisé, et nos maisons tiennent toujours debout. Merci.', '', 28153),
(157459, 'frFR', 'Comptez sur moi pour veiller à ce que les Sephraks repartent les mains vides.', 'Comptez sur moi pour veiller à ce que les Sephraks repartent les mains vides.', 28153),
(157458, 'frFR', 'Je ne peux pas rappeler nos marins à bon port, mais au moins, nous savons que les navires sont là… quelque part. Le destin de la flotte repose sur les Portvaillant, désormais.', '', 28153),
(157457, 'frFR', 'Jani, c\’est le Loa des rebuts, des traîne-misère et des laissés pour compte. Les orphelins comme moi, les damnés de la terre, il veille sur eux en permanence.', '', 28153),
(157456, 'frFR', 'Ma magie est ici à son paroxysme. S\’il existe une chance de retrouver la flotte, c\’est maintenant ou jamais.', '', 28153),
(157455, 'frFR', 'Euh... Du balai... <Hips !> J\’ai à faire.', '', 28153),
(157454, 'frFR', 'On est les disciples de Torcali, la montagne ambulante, le rempart errant. Si notre Loa le veut, rien ni personne ne franchira nos boucliers.', '', 28153),
(157453, 'frFR', '', 'C\’est une menace en moins qui pèse sur la vallée ! Bien joué !', 28153),
(157452, 'frFR', '', 'Waouh… Je suis sans voix. Quel combat incroyable !', 28153),
(157451, 'frFR', 'Attendez. Je crois que je vois quelque chose.', '', 28153),
(157450, 'frFR', 'Je ne pensais vraiment pas que ça marcherait, mais cet or va aider de nombreuses personnes à reconstruire leur vie !', '', 28153),
(157449, 'frFR', 'Oui… je perçois les navires… notre flotte ! Les brumes sombres qui les enserrent se dissipent !', '', 28153),
(157448, 'frFR', 'Je suis là pour résoudre vos problèmes, Krog.', 'Je suis là pour résoudre vos problèmes, Krog.', 28153),
(157447, 'frFR', '', 'Le Sillage des tempêtes a signalé une bête agressive dans les environs. Mais je parie que vous pourrez nous en débarrasser !', 28153),
(157446, 'frFR', '', 'Une créature dangereuse rôde dans ces collines. Trouvez-la avant qu\’il n\’y ait des blessés !', 28153),
(157445, 'frFR', 'Les chasseurs de trésors du Reflux mort veulent nous faire un don d\’or pour la reconstruction de Brennadam. L\’inconvénient, c\’est qu\’il faut récupérer l\’or nous-mêmes !', '', 28153),
(157444, 'frFR', 'Arthur…', '', 28153),
(157443, 'frFR', 'Doras, j\’ai besoin d\’un coursier du vent pour rallier Mur-de-Fougères.', 'Doras, j\’ai besoin d\’un coursier du vent pour rallier Mur-de-Fougères.', 28153),
(157442, 'frFR', '', 'Bien joué. En sauvant Ai\’twen, vous avez aidé les Tortollans… et comblé les Loas, je crois.', 28153),
(157441, 'frFR', 'C\’est bien ce que j\’ai fait, renverser des pierres. Et pas des plus commodes, par-dessus le marché.', '', 28153),
(157440, 'frFR', 'Tu étais censé renverser des cairns.', '', 28153),
(157439, 'frFR', 'Oh, ça va ! Tout est bien qui finit bien. À nous deux, on a éliminé ce monstre de pierre et on a survécu ! Où est le problème ?', '', 28153),
(157438, 'frFR', 'Arthur ! Je t\’ai dit mille fois de ne pas foncer tête baissée comme ça !', '', 28153),
(157437, 'frFR', '', 'Les Tortollans vénèrent la grande tortue Ai\’twen, une alliée puissante de leur passé. Aidez à la nourrir et à la protéger, pour qu\’elle nous aide une fois encore.', 28153),
(157436, 'frFR', 'Quittez cet endroit !', '', 28153),
(157435, 'frFR', 'Des vents favorables vous guident ! Vos actions sont un exemple pour nous tous.', '', 28153),
(157434, 'frFR', 'Continuons vers le sud, dans ce cas. Nous vous recontacterons, Fuzbert.', '', 28153),
(157433, 'frFR', 'Fais-toi plaisir, Fuz !', '', 28153),
(157432, 'frFR', '', 'Disperse-les aux quatre coins du pays, Fuzbert !', 28153),
(157431, 'frFR', '... ET SA CARGAISON DE BOMBES !', '', 28153),
(157430, 'frFR', 'Un petit site de fouilles, hein ? Voilà un boulot taillé sur mesure pour un Gnome...', '', 28153),
(157429, 'frFR', 'Il y a un petit site de fouilles du Reliquaire à environ un demi-kilomètre à l\’est d\’ici.', '', 28153),
(157428, 'frFR', '$n, derrière vous ! Aidez-moi à nous débarrasser de ces indésirables !', '', 28153),
(157427, 'frFR', 'L\’antique tortue Ai\’twen est un mystère marin que nous devons préserver. Aidez les Tortollans à la protéger et à la nourrir.', '', 28153),
(157426, 'frFR', 'Nous irons jusqu\’au bout pour que le seigneur Chantorage paie pour ses fautes…', '', 28153),
(157425, 'frFR', 'Les habitants de Chantorage ont le droit de se sentir en sécurité. Ne montrez aucune pitié envers ceux qui menacent leur quiétude.', '', 28153),
(157424, 'frFR', 'Nous devons agir vite si nous voulons protéger la flotte de l\’emprise d\’Azshara.', '', 28153),
(157423, 'frFR', 'L\’endroit n\’est pas sûr. Venez, un ancien poste de garde surplombe le sanctuaire non loin.', '', 28153),
(157422, 'frFR', 'Mais nous ne l\’oublierons pas. Il continuera de vivre à travers nous.', '', 28153),
(157421, 'frFR', 'La voix résonne en écho avec la vôtre. Vous sentez qu\’elle cherche une réponse, tout comme vous.\n\n« À quelle fin ? »', '', 28153),
(157420, 'frFR', 'Vous grimacez de douleur alors que la voix hurle en votre for intérieur.\n\n« Où cela a-t-il commencé ? »', '', 28153),
(157419, 'frFR', 'Je vous remercie. Les fermiers devraient pouvoir retourner aux champs rapidement.', '', 28153),
(157418, 'frFR', 'Des rapports inquiétants nous parviennent des fermes éloignées. Vous devez nous aider à maintenir l\’ordre dans la vallée !', '', 28153),
(157417, 'frFR', 'La voix se fait plus forte et plus pressante.\n\n« Encore ! Encore ! Encore ! »', '', 28153),
(157416, 'frFR', 'La voix ancestrale n\’est plus qu\’un lointain écho qui résonne dans les profondeurs de votre esprit.\n\n« Que voulez-vous ? »', '', 28153),
(157415, 'frFR', 'Vous réservez de sacrées surprises ! Il faudra que vous m\’enseigniez quelques-uns de vos trucs.', '', 28153),
(157414, 'frFR', 'Bien joué. Si vous avez besoin d\’une extraction, nos agents vous attendent, non loin.', '', 28153),
(157413, 'frFR', 'Je repars discrètement pour en informer Boulaie ! On se retrouve là-bas !', '', 28153),
(157412, 'frFR', 'HA ! Tout s\’efface devant notre puissance !', '', 28153),
(157411, 'frFR', '', 'Sam… il est… il est parti…', 28153),
(157410, 'frFR', 'Une fois le dernier de ses sujets tué et devenu Réprouvé, le petit roi s\’inclinera devant la Dame noire. Et alors restera une reine pour les gouverner tous.', '', 28153),
(157409, 'frFR', 'Vengeance. Mépris. Appelez cela comme vous voulez.', '', 28153),
(157408, 'frFR', '', 'C\’est donc la vengeance qui vous anime. Je comprends.', 28153),
(157407, 'frFR', 'Une fois l\’emprise du roi-liche brisée, Sylvanas s\’est mise en quête d\’alliés. Au lieu de tendre la main à leurs proches tombés à Lordaeron, les Humains les ont rejetés. Depuis lors, j\’œuvre à leur déchéance.', '', 28153),
(157406, 'frFR', '', 'Tourné le dos ? Comment ça ?', 28153),
(157405, 'frFR', 'J\’ai combattu pour l\’Alliance autrefois. Mais son insoutenable arrogance n\’a fait que décupler depuis qu\’elle nous a tourné le dos.', '', 28153),
(157404, 'frFR', '', 'Votre zèle contre l\’Alliance ne semble pas seulement motivé par le respect que vous portez à votre reine, Flétrisseur.', 28153),
(157403, 'frFR', '', 'J\’ai causé la perte d\’un roi. Je n\’hésiterai pas à mettre fin au règne d\’un autre.', 28153),
(157402, 'frFR', 'Très bien. L\’Alliance ne mérite aucune pitié. Faites souffrir nos ennemis, et la Dame noire vous récompensera.', '', 28153),
(157401, 'frFR', '', 'C\’est vrai. Mais vous savez aussi que ma collaboration avec l\’Alliance avait pour seul but de servir mes objectifs. Nous sommes quittes. Mon cœur est avec la Horde.', 28153),
(157400, 'frFR', 'Fous que vous êtes...', '', 28153),
(157399, 'frFR', 'Au nom de Kul Tiras, je vous exhorte à quitter ces lieux !', '', 28153),
(157398, 'frFR', 'Inutile, je connais l\’histoire. Je sais que vous n\’aviez aucune intention de tuer Llane Wrynn.', '', 28153),
(157397, 'frFR', '', 'Parce que le grand-père du jeune roi m\’a autrefois offert son amitié ? Dois-je vous rappeler que je l\’ai assassiné ?', 28153),
(157396, 'frFR', 'Les coups que vous avez portés à l\’Alliance m\’ont fait forte impression, Garona. J\’avoue avoir envisagé un éventuel… conflit de loyauté.', '', 28153),
(157395, 'frFR', 'Hé hé... de la viande fraîche !', '', 28153),
(157394, 'frFR', 'Par la fureur de la nature !', '', 28153),
(157393, 'frFR', 'Je vais vous laminer !', '', 28153),
(157392, 'frFR', 'Voulez-vous vraiment continuer ?', 'Voulez-vous vraiment continuer ?', 28153),
(157391, 'frFR', 'Beau travail, $p. La vallée Chantorage a une énorme dette envers vous.', '', 28153),
(157390, 'frFR', 'Rêver, rêver de la cité engloutie.', 'Rêver, rêver de la cité engloutie.', 28153),
(157389, 'frFR', 'À l\’ombre de Son regard...', 'À l\’ombre de Son regard...', 28153),
(157388, 'frFR', 'Dans l\’abandon de Son étreinte implacable...', 'Dans l\’abandon de Son étreinte implacable...', 28153),
(157387, 'frFR', 'Respirer la sagesse des noyés...', 'Respirer la sagesse des noyés...', 28153),
(157386, 'frFR', 'Les survivants de la chaumine des Gris-Coteaux combattent depuis des jours. Essayez de les aider, afin qu\’ils puissent souffler un peu.', '', 28153),
(157383, 'frFR', 'Le nombre d\’explosions était impressionnant ! Content de voir que ni Toki ni vous n\’en avez fait les frais.', '', 28153),
(157382, 'frFR', 'Se gorger de la marée chatoyante...', 'Se gorger de la marée chatoyante...', 28153),
(157381, 'frFR', 'La KapitalRisk continue de détruire le paysage côtier. Retrouvez Toki et essayez de l\’aider au mieux.', '', 28153),
(157380, 'frFR', 'Euh...', 'Euh...', 28153),
(157379, 'frFR', 'Vous trouvez un autel sinistre. Lorsque vous posez la main dessus, des paroles se mettent à affluer dans votre esprit.\n\n« Par quoi allez-vous commencer ? »', '', 28153),
(157378, 'frFR', 'Beau travail. Je vous dois un coup à boire.', '', 28153),
(157377, 'frFR', 'Attendez que je vous mette les griffes dessus !', '', 28153),
(157376, 'frFR', 'Je vais vous tailler en pièces !', '', 28153),
(157375, 'frFR', 'Je ne veux plus voir les Lamineurs dans le coin. Voyons s\’ils voudront encore rester quand nous leur aurons rendu la vie encore moins facile.', '', 28153),
(157374, 'frFR', 'Pour Drustvar !', '', 28153),
(157373, 'frFR', 'Allons-y ! Pulvérisons ce monstre !', '', 28153),
(157372, 'frFR', '', 'Les Tortollans vous remercient pour votre aide, tout comme moi.', 28153),
(157371, 'frFR', '', 'Ces brutes de la KapitalRisk continuent de harceler les Tortollans ! Allez voir Toki et apportez-lui votre aide.', 28153),
(157370, 'frFR', '', 'Nos ennemis sauront que c\’est vous, héraut de la Horde, qui a déjoué leurs plans. Bien joué.', 28153),
(157369, 'frFR', '', 'Nos ennemis sont de plus en plus téméraires ! Privez-les de leurs ressources… et ôtez-leur la vie, si nécessaire.', 28153),
(157368, 'frFR', '', 'Nous gagnons en force alors que l\’ennemi faiblit. Parfois, les petites victoires mènent à un plus grand triomphe.', 28153),
(157367, 'frFR', '', 'Nos soldats ne peuvent pas gagner la guerre le ventre vide. Il nous faut de la viande d\’ours pour les nourrir. Et ne laissez pas l\’ennemi s\’en mêler.', 28153),
(157362, 'frFR', 'Des choses anciennes dont l\’existence même est une offense se réveillent. Restez sur vos gardes.', 'Des choses anciennes dont l\’existence même est une offense se réveillent. Restez sur vos gardes.', 28153),
(157361, 'frFR', 'Voir les morts sortir de leurs tombes nous a pris par surprise !', 'Nous ne nous attendions pas à voir les morts se relever !', 28153),
(157360, 'frFR', 'Nous ne nous attendions pas à une telle puissance. Faites preuve de prudence.', 'Nous ne nous attendions pas à une telle puissance. Faites preuve de prudence.', 28153),
(157359, 'frFR', 'Les assemblages doivent être détruits. De grâce, aidez-nous !', 'Les assemblages doivent être détruits. De grâce, aidez-nous !', 28153),
(157358, 'frFR', 'Vous arrivez à point nommé.', 'Vous arrivez à point nommé.', 28153),
(157357, 'frFR', 'Arrêtez, $p. Vous voyez ça ?', '', 28153),
(157356, 'frFR', 'La Horde a été repoussée pour le moment, et la ville est toujours debout. Nous vous devons la vie.', '', 28153),
(157355, 'frFR', 'La Horde est revenue en force pour tenter de finir le travail. Arrêtez-la par tous les moyens nécessaires !', '', 28153),
(157354, 'frFR', 'Il est assez solitaire, mais il sait reconnaître quand il est dans la panade. Merci de l\’avoir aidé !', '', 28153),
(157353, 'frFR', 'Orchamp aurait bien besoin de votre aide. Sa ferme est la cible constante de pillages, et il commence à manquer de ressources. Aidez-le du mieux que vous le pourrez.', '', 28153),
(157352, 'frFR', 'Ils y réfléchiront à deux fois avant de se remettre à creuser ! Faites une grattouille à ce chien pour moi.', '', 28153),
(157351, 'frFR', 'Les Hurans essayent d\’étendre leur réseau de tunnels, aux dépens de la stabilité de toute la vallée. Nos limiers pourront les flairer et les forcer à sortir, s\’ils savent où chercher.', '', 28153),
(157350, 'frFR', 'En avant, $p.', '', 28153),
(157349, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Vous êtes victime de |cFFFF0000|Hspell:272536|h[Ruine imminente]|h|r !', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Vous êtes victime de |cFFFF0000|Hspell:272536|h[Ruine imminente]|h|r !', 28153),
(157348, 'frFR', 'Cette chambre, elle serait parfaite pour exposer la collection royale d\’antiquités. Peut-être qu\’on devrait…', '', 28153),
(157347, 'frFR', '', 'Je ne serai jamais loin !', 28153),
(157346, 'frFR', 'Shandris, faites profil bas. Restez dans les ombres... pour peu que vous parveniez à en trouver.', '', 28153),
(157345, 'frFR', '', 'Reçu cinq sur cinq, haut-commandant ! Je décolle !', 28153),
(157344, 'frFR', 'Kelsey, vous êtes en charge de la reconnaissance aérienne. Signalez-nous tout ce qui sort de l\’ordinaire.', '', 28153),
(157343, 'frFR', 'Pouvez-vous récapituler le plan ?', 'Pouvez-vous récapituler le plan ?', 28153),
(157342, 'frFR', 'Mes parents disaient toujours que j\’avais une imagination débordante.', '', 28153),
(157341, 'frFR', 'Parfois, on dévalait les collines de la vallée dans un chariot ! On faisait semblant que Hobbs était un tigre !', '', 28153),
(157340, 'frFR', 'Hobbs et moi, on vivait plein d\’aventures, quand on était petits.', '', 28153),
(157339, 'frFR', 'Montrez-moi.', 'Montrez-moi.', 28153),
(157338, 'frFR', 'Les visions peuvent nous aider à observer le massacre, $r.', 'Les visions peuvent nous aider à observer le massacre, $r.', 28153),
(157337, 'frFR', 'Bientôt, la flotte aussi sera baignée dans sa lumière, et tout Kul Tiras s\’agenouillera devant l\’éclat des profondeurs.', '', 28153),
(157336, 'frFR', 'Vous êtes aveugles. Les dons de la mère des marées nous ont rendu notre grandeur.', '', 28153),
(157335, 'frFR', 'Âmes des déchus, il est temps de tenir votre serment. Brisez ces portes !', '', 28153),
(157334, 'frFR', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t Leaxa l\’Aînée commence à lancer |cFFF00000|Hspell:264603|h[Miroir de sang]|h|r !', 28153),
(157333, 'frFR', '', 'Je la sens bien, cette grotte. J\’imagine déjà les montagnes d\’or qui m\’attendent à l\’intérieur.', 28153),
(157332, 'frFR', 'J\’en arrivais au moment où j\’ai plongé la tête la première dans sa gueule pour l\’ouvrir de l\’intérieur !', 'J\’en arrivais au moment où j\’ai plongé la tête la première dans sa gueule pour l\’ouvrir de l\’intérieur !', 28153),
(157331, 'frFR', 'D\’accord, c\’est vrai, Ligne et Plomb m\’ont un petit peu aidé. Mais tout le reste est vrai, juré craché !', 'D\’accord, c\’est vrai, Ligne et Plomb m\’ont un petit peu aidée. Mais tout le reste est vrai, juré craché !', 28153),
(157330, 'frFR', 'Mph mph mph mph, mph mph !', 'Mff mff mff mff, mff mff !', 28153),
(157329, 'frFR', 'Boucle-la. Chacun son tour.', 'Boucle-la. Chacun son tour.', 28153),
(157328, 'frFR', '', 'Pas d\’or, mais des litres de rhum !', 28153),
(157327, 'frFR', 'Ouais, avec mes dons innés de pêcheur !', 'Ouais, avec mes dons innés de pêcheur !', 28153),
(157326, 'frFR', 'Grâce à mon intuition légendaire, j\’ai tout de suite su comment lui régler son compte.', 'Grâce à mon intuition légendaire, j\’ai tout de suite su comment lui régler son compte.', 28153),
(157325, 'frFR', '… Quand je l\’ai vue se pointer à l\’horizon. Une bête comme j\’en avais encore jamais vue !', '… Quand je l\’ai vue se pointer à l\’horizon. Une bête comme jamais j\’en avais encore vue !', 28153),
(157324, 'frFR', 'Je me tapais le premier tour de garde, histoire de pas nous laisser surprendre par ces fichus Nagas…', 'Je me tapais le premier tour de garde, histoire de pas nous laisser surprendre par ces fichus Nagas…', 28153),
(157323, 'frFR', 'Laissez-moi vous raconter comment j\’ai rencontré ces deux marins à la petite semaine.', 'Laissez-moi vous raconter comment j\’ai rencontré ces deux marins à la petite semaine.', 28153),
(157322, 'frFR', 'Ouais, je suis bien d\’ac… Euh, une seconde !', 'Ouais, je suis bien d\’ac… Euh, une seconde !', 28153),
(157321, 'frFR', 'C\’est ce casque qui te monte à la tête. Je préfère encore croire que Ligne a réussi à prendre un poisson !', 'C\’est ce casque qui te monte à la tête. Je préfère encore croire que Ligne a réussi à prendre un poisson !', 28153),
(157320, 'frFR', 'Mph, mph mph mph mph. Mph.', 'Mff, mff mff mff mff. Mff.', 28153),
(157319, 'frFR', 'MPH !!!', 'MFF !!!', 28153),
(157318, 'frFR', 'Mph mph… mph.', 'Mph mph… mph.', 28153),
(157317, 'frFR', 'Heureusement que j\’avais le calibre spécial que j\’porte toujours autour du cou pour ce genre d\’occasion.', 'Heureusement que j\’avais le calibre spécial que j\’porte toujours autour du cou pour ce genre d\’occasion.', 28153),
(157316, 'frFR', 'Je garde le rhum jusqu\’au retour du capitaine.', '', 28153),
(157315, 'frFR', 'Capitaine… je n\’en ai pas bu une goutte.', '', 28153),
(157314, 'frFR', '', 'Et qui dit pirate, dit généralement trésor !', 28153),
(157313, 'frFR', '', 'Certains ouvriers disent avoir vu le fantôme d\’un pirate dans cette grotte.', 28153),
(157312, 'frFR', '', 'Brennadam est droit devant. Allons-y !', 28153),
(157311, 'frFR', '', 'Sans elle, Kul Tiras est sans défense. Ce n\’est qu\’une question de temps avant que nous soyons attaqués.', 28153),
(157310, 'frFR', '', 'Nous devons trouver frère Pike immédiatement. Peut-être pourra-t-il nous aider à retrouver la flotte.', 28153),
(157309, 'frFR', '', 'Cette vallée n\’est-elle pas majestueuse ? Pas étonnant qu\’elle attire autant de nouvelles âmes.', 28153),
(157308, 'frFR', '', 'Il s\’agit de la seule voie terrestre vers la vallée. La maison Chantorage prépare quelque chose.', 28153),
(157307, 'frFR', '', 'Brennadam est le plus gros centre marchand de Kul Tiras, après Boralus.', 28153),
(157306, 'frFR', 'Mettez-y un peu de cœur, bande de moules !', 'Mettez-y un peu de cœur, bande de moules !', 28153),
(157305, 'frFR', 'Il est là-haut. Lui et ses deux grosses têtes !', 'Là-haut ! Il se prépare à attaquer !', 28153),
(157304, 'frFR', 'Mêlez-vous de vos oignons. Je suis en mission officielle !', 'Mêlez-vous de vos oignons. Je suis en mission officielle !', 28153),
(157303, 'frFR', 'Qu\’est-ce que vous faites ? Vous devez évacuer avec les autres !', 'Qu\’est-ce que vous faites ? Vous devez évacuer avec les autres !', 28153),
(157302, 'frFR', 'Gare à la massue !', 'Tu ferais mieux de dégager, Tom. On est plus nombreux !', 28153),
(157301, 'frFR', 'On vous en veut à mort, nous deux… Tout ça, c\’est votre faute.', 'On vous en veut à mort, nous deux… Tout ça, c\’est votre faute.', 28153),
(157300, 'frFR', 'Approchez… On va se battre, tous les trois !', 'Approchez… On va se battre, tous les trois !', 28153),
(157299, 'frFR', 'Je me charge de la tête de droite.', 'Il est plus imposant que je l\’imaginais.', 28153),
(157298, 'frFR', 'Inspection', 'Inspection', 28153),
(157296, 'frFR', 'Bon retour parmi nous, les amis. J\’ai une nouvelle chanson pour vous !', '', 28153),
(157294, 'frFR', 'D\’abord, je vous tue, et ensuite, j\’écrabouille tous les habitants !', 'D\’abord, je vous tue, et ensuite, j\’écrabouille tous les habitants !', 28153),
(157293, 'frFR', 'Le Sillage des tempêtes guidera la flotte vers la victoire pour l\’Alliance, comme par le passé.', '', 28153),
(157292, 'frFR', '', 'La maison Malvoie se tient à vos côtés, amiral suprême, et aux côtés de l\’Alliance.', 28153),
(157291, 'frFR', '', 'Nous devons rétablir nos liens avec l\’Alliance, dont les héros nous ont sauvés de la destruction.', 28153),
(157290, 'frFR', '', 'Je vous demande aujourd\’hui d\’avoir foi en ma fille, Jaina, le véritable amiral suprême de Kul Tiras.', 28153),
(157289, 'frFR', '', 'De plus, la Horde a fait clairement état de ses intentions. Ces sauvages veulent nous éradiquer.', 28153),
(157288, 'frFR', '', 'Les dissensions nous ont rendus vulnérables. Les ennemis ont infiltré nos rangs.', 28153),
(157287, 'frFR', '', 'Merci à tous d\’être venus. Je serai brève.', 28153),
(157286, 'frFR', 'Je parie que nous pourrions tuer ces monstres à nous deux !', '', 28153),
(157285, 'frFR', 'Quand Daelin m\’a demandé de quitter sa garde pour élever cette enfant des royaumes de l\’Est, je n\’ai pas compris sa démarche.\n\nPourquoi m\’imposer ce fardeau, à moi ? Pourquoi me priver de l\’honneur de combattre à ses côtés ? J\’ai cru que c\’était une punition pour avoir trahi sa confiance.\n\nLes années ont passé et j\’ai fini par comprendre que c\’était tout le contraire. Il voulait que Taelia soit instruite dans le maniement des armes et dans la noblesse de l\’âme. Et il m\’a fait l\’honneur de me confier ce qu\’il avait de plus cher au monde.', '', 28153),
(157284, 'frFR', '', 'Est-il vrai qu\’il existe un tunnel entre Hurlevent et Forgefer ?$B$BC\’est incroyable ! J\’aimerais beaucoup voir ça, un jour.', 28153),
(157283, 'frFR', 'Et ce n\’était qu\’une pincée ! Imaginez quels dégâts ils pourraient faire avec une plus grande quantité.', '', 28153),
(157282, 'frFR', '', 'Merci. Maintenant, les habitants peuvent reprendre leur travail dans les champs.', 28153),
(157281, 'frFR', '', 'Une créature menace les fermiers, non loin. Nous devons les aider !', 28153),
(157280, 'frFR', '', 'Excellent ! Je ne doute pas qu\’ils feront vite bon usage de ces fournitures.', 28153),
(157279, 'frFR', '', 'J\’espère qu\’un jour, les habitants de Kul Tiras pourront à nouveau faire confiance aux eaugures. En attendant, nous devons trouver notre propre voie.', 28153),
(157278, 'frFR', '', 'Cela devrait nous laisser le temps de souffler un peu. Merci.', 28153),
(157277, 'frFR', '', 'Les habitants de la vallée n\’oublieront pas vos bienfaits. Bon travail !', 28153),
(157276, 'frFR', '', 'Ces collines regorgent de ressources importantes pour le Sillage des tempêtes. Peut-être pourriez-vous lui prêter votre aide ?', 28153),
(157275, 'frFR', '', 'Les fidèles de Chantorage nous causent encore des problèmes. Nous ne pouvons pas les laisser poursuivre leurs sombres rituels !', 28153),
(157274, 'frFR', '', 'Nous avons perdu le contrôle de la zone ! Allez-y et repoussez l\’ennemi !', 28153),
(157273, 'frFR', '', 'Le Sillage des tempêtes a besoin d\’aide. Faites de votre mieux pour apporter un peu de paix à la vallée !', 28153),
(157272, 'frFR', '', 'Canonniers ! Préparez-vous au bombardement final !', 28153),
(157271, 'frFR', '', 'Maintenez le bouclier ! C\’est déjà bien assez difficile comme ça !', 28153),
(157270, 'frFR', 'Une autre Réprouvée ? Je ne pensais pas que… <Tousse> Dites-moi, mademoiselle… ?', '', 28153),
(157269, 'frFR', '<Tousse.> La Horde. Et moi qui croyais mourir en paix.\n\nAlors comme ça, vous faites partie des Réprouvés ? Intéressant, mais c\’est trop tard.\n\nEh bien, qu\’est-ce que vous attendez ?', '', 28153),
(157268, 'frFR', 'On se retrouve au chariot, $p !', '', 28153),
(157267, 'frFR', '', 'Hou-hou ! C\’est l\’heure de s\’en mettre plein les poches !', 28153),
(157266, 'frFR', 'Ramenez-moi, s\’il vous plaît.', 'Ramenez-moi, s\’il vous plaît.', 28153),
(157265, 'frFR', 'Merci pour votre aide. Nous devrions rentrer, à présent.', 'Merci pour votre aide. Nous devrions rentrer, à présent.', 28153),
(157264, 'frFR', 'Assister à la rencontre de Zelling avec sa famille.', 'Assister à la rencontre de Zelling avec sa famille.', 28153),
(157263, 'frFR', 'Quelle exécution parfaite, comme toujours. Si tous les membres de l\’Alliance sont d\’aussi bons cavaliers que vous, ils sont les bienvenus sur mon domaine !', '', 28153),
(157262, 'frFR', 'Quelle belle journée pour une représentation ! En selle, mon $uami:amie;, et montrez votre prouesse dans le manège !', '', 28153),
(157261, 'frFR', '', 'Comme vous voudrez. Venez, $n.', 28153),
(157260, 'frFR', 'Je retourne à la base. Je sais comment tout cela va finir. Je n\’ai nul besoin d\’y assister.', '', 28153),
(157259, 'frFR', 'Tenez-vous à carreau en présence de vos supérieurs. Bouclez-la et laissez-moi parler avec le seigneur des maléfices.', '', 28153),
(157258, 'frFR', '', 'Fantastique ! Voilà qui devrait ralentir les Nagas.', 28153),
(157257, 'frFR', '', 'Je vous donne ma parole. Venez. $n, allez informer Nathanos que nous avons tout ce qu\’il nous faut.', 28153),
(157256, 'frFR', 'Je vais me joindre à vous… et vous aider à trouver le maréchal Valentine. Tant que vous me promettez qu\’il n\’arrivera rien à ma famille.', '', 28153),
(157255, 'frFR', '', 'Les Nagas attaquent à nouveau le fort ! Occupez-vous d\’eux à la façon des Tortollans !', 28153),
(157254, 'frFR', '', 'Rejoignez les Réprouvés et tracez votre propre voie parmi ceux qui vous acceptent pour ce que vous êtes devenu.', 28153),
(157253, 'frFR', 'Et que me reste-t-il dans ce cas ? Devenir un serviteur décérébré de la reine banshee ?', '', 28153),
(157252, 'frFR', '', 'Il s\’agit d\’un honneur rarement accordé à ceux qui ne sont pas Zandalari. Venez, parlez-moi des accomplissements de Vol\’jin.', 28153),
(157250, 'frFR', '', 'J\’ai pourtant essayé de vous prévenir, Zelling. La transformation est un changement profond. Les vivants vous tourneront le dos désormais.', 28153),
(157249, 'frFR', 'Non… Julia… Matthew… Hannah… Qu\’ai-je fait ? Que suis-je devenu ?', '', 28153),
(157248, 'frFR', '', 'Fais partir le méchant monstre, maman !', 28153),
(157247, 'frFR', '', 'Laissez-nous tranquilles !', 28153),
(157246, 'frFR', 'Faites que ça cesse !', '', 28153),
(157245, 'frFR', 'Taisez-vous !', '', 28153),
(157244, 'frFR', '', 'J\’ignore qui vous êtes, mais mon mari n\’a JAMAIS levé la main sur ses enfants ou sur moi. Nous partons… Ne nous suivez pas !', 28153),
(157243, 'frFR', 'JE… JE…', '', 28153),
(157242, 'frFR', 'Ça SUFFIT !', '', 28153),
(157241, 'frFR', 'Maman ! Au secours !', '', 28153),
(157240, 'frFR', '', 'N\’approchez pas !', 28153),
(157239, 'frFR', 'Mais c\’est papa ! Vous m\’écoutez ? Est-ce si difficile à comprendre ?', '', 28153),
(157238, 'frFR', '', 'Fichez-moi la paix !', 28153),
(157237, 'frFR', 'Maman, j\’ai peur du monstre !', '', 28153),
(157236, 'frFR', 'Pourquoi refuses-tu de comprendre ? C\’est moi, ton mari… Les enfants, c\’est papa !', '', 28153),
(157235, 'frFR', '', 'Je vous le dis pour la dernière fois, FICHEZ-MOI LA PAIX ! Vous n\’êtes PAS mon mari !', 28153),
(157234, 'frFR', 'Ma force ne vacille pas… même dans la mort…', '', 28153),
(157233, 'frFR', 'Vous auriez dû mieux vous préparer avant de venir m\’affronter !', '', 28153),
(157232, 'frFR', 'Zelling, nous avons besoin de vous pour trouver le cadavre du maréchal Valentine.', 'Zelling, nous avons besoin de vous pour trouver le cadavre du maréchal Valentine.', 28153),
(157231, 'frFR', 'Ma famille… me vengera.', '', 28153),
(157230, 'frFR', 'Ma rage va s\’abattre sur vous !', '', 28153),
(157229, 'frFR', '', 'Les dés sont jetés. Voyons ce qu\’il va se passer…', 28153),
(157228, 'frFR', 'Je… je suis vivant ! Ha ha ! Il faut que je retourne auprès de Julia et des enfants. Ils seront fous de joie de me revoir !', '', 28153),
(157227, 'frFR', '', 'Rares sont les esprits si… puissants. Maître Gadrin, pouvez-vous apporter les cendres du chef à Atal\’Dazar ? Si son esprit est digne d\’un tel honneur, il rejoindra nos plus grands rois.', 28153),
(157226, 'frFR', 'Zalazane, il reviendra plus. Même dans la mort, Vol\’jin veille sur nous.', '', 28153),
(157225, 'frFR', 'Les morts, ils tombent…', '', 28153),
(157224, 'frFR', 'Nos renforts attendent vos ordres.', '', 28153),
(157223, 'frFR', 'Puisque la Horde veut la guerre, on va sortir le grand jeu !', '', 28153),
(157222, 'frFR', 'J\’espère que vous apportez de bonnes nouvelles.', '', 28153),
(157221, 'frFR', 'Les Chantorage perdureront.', '', 28153),
(157220, 'frFR', 'Bon voyage.', '', 28153),
(157219, 'frFR', 'Les marées vous guident.', '', 28153),
(157218, 'frFR', 'Excellent ! Nous ferons bon usage de ces fournitures. Et de ces porcelets également.', '', 28153),
(157217, 'frFR', 'Les Hurans ont encore pillé nos réserves. Ils l\’auront cherché : récupérez nos fournitures, mais aussi tout ce qui peut nous être utile !', '', 28153),
(157216, 'frFR', 'C\’est comme si c\’était fait.', '', 28153),
(157215, 'frFR', '', 'À vos ordres !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'frFR', '', 'Ô, douce Élune, puisses-tu accorder tes grâces à ceux qui sont tombés.', 28153),
(157213, 'frFR', 'Taelia, prépare-toi à organiser des rondes. Dis aux gardes d\’être attentifs aux armes de contrebande qui sortent de l\’ordinaire à Boralus.', '', 28153),
(157212, 'frFR', '', 'Vol\’jin, fils de Sen\’jin, est digne de ces tombeaux sacrés. Cependant, pour entrer dans Atal\’Dazar, vous devrez peut-être vous battre. Je suggère que notre héraut se charge de porter ces cendres à leur dernière demeure.', 28153),
(157211, 'frFR', '', 'Il est difficile de faire ce que nos chefs, eux, refusent.', 28153),
(157210, 'frFR', 'Quand Vol\’jin a compris que Garrosh, notre chef de guerre, refusait de diriger avec honneur, il a mené la rébellion pour le faire tomber.', '', 28153),
(157209, 'frFR', '', 'À l\’époque, le grand empire troll des visions de Zul était fort séduisant pour mon père. Votre chef a été admirable de sagesse.', 28153),
(157208, 'frFR', 'Quand Zandalar a tenté d\’unir les tribus trolles, Vol\’jin a préféré la sécurité de son peuple aux sombres pouvoirs du prophète.', '', 28153),
(157207, 'frFR', 'Vol\’jin a passé un marché avec Bwonsamdi pour vaincre le puissant Zalazane.', '', 28153),
(157206, 'frFR', '', 'Les feux follets sont innombrables. Tant de vies perdues…', 28153),
(157205, 'frFR', 'Nous portons les cendres de Vol\’jin, fils de Sen\’jin, pour qu\’elles soient honorées dans ce lieu sacré.', '', 28153),
(157204, 'frFR', 'Flynn, j\’ai une autre tâche pour toi : aide notre $unouvel allié:nouvelle alliée; à découvrir d\’où vient cette poudre.', '', 28153),
(157203, 'frFR', 'Prenez garde. D\’anciennes menaces planent à nouveau sur ces terres.', '', 28153),
(157202, 'frFR', 'Imploratrice céleste, je suis ici sur ordre du chef de guerre.', 'Imploratrice céleste, je suis ici sur ordre du chef de guerre.', 28153),
(157201, 'frFR', 'Oui, je dois me rendre en Silithus.', 'Oui, je dois me rendre en Silithus.', 28153),
(157200, 'frFR', 'Pourquoi suis-je ici ?', 'Pourquoi suis-je ici ?', 28153),
(157199, 'frFR', 'Émissaire ! Vous voulez bien faire une petite démonstration pour les sceptiques ?', '', 28153),
(157198, 'frFR', 'Pas comme celle-là, non.', '', 28153),
(157197, 'frFR', 'En quoi est-ce nouveau ? Ils conçoivent de nouvelles armes en permanence.', '', 28153),
(157196, 'frFR', '', 'Bon, Flynn, quelle est cette piste si intéressante ? Tu parlais d\’une nouvelle poudre à canon Corsandre ?', 28153),
(157195, 'frFR', 'Il me faut un coursier du vent pour le refuge des Marshal, dans le cratère d\’Un\’Goro.', 'Il me faut un coursier du vent pour le refuge des Marshal, dans le cratère d\’Un\’Goro.', 28153),
(157194, 'frFR', 'Vous voilà… Bien ! J\’aurais pas aimé dire à la princesse que son héraut avait été volé par un Nain en diamant !', '', 28153),
(157193, 'frFR', 'Waouh ! On a fait du bon travail !', '', 28153),
(157192, 'frFR', 'On doit récupérer une cargaison perdue. Et quand je dis « on », je veux bien évidemment dire « vous ».', '', 28153),
(157191, 'frFR', 'Je sais pas où vous allez, mais ne traînez pas. La princesse a besoin de votre aide !', 'Je ne sais pas où vous allez, mais ne traînez pas. La princesse, elle a besoin de votre aide !', 28153),
(157190, 'frFR', 'Voilà qui est extraordinaire ! Je devrais prendre des notes.', 'Voilà qui est extraordinaire ! Je devrais prendre des notes.', 28153),
(157189, 'frFR', 'Protéger notre chaîne d\’approvisionnement est un aspect crucial de la guerre… tout autant que détruire celle de l\’ennemi.', '', 28153),
(157188, 'frFR', 'Des épaves de l\’Alliance… c\’est toujours un spectacle plaisant. Ramassez tout ce qui pourrait être utile à la Horde dans les environs.', '', 28153),
(157187, 'frFR', 'Et c\’est comme ça tous les jours.', '', 28153),
(157186, 'frFR', 'L\’extracteur est attaqué ! Protégez-le !', '', 28153),
(157185, 'frFR', 'Ces ressources sont vitales pour les activités de la Horde. Bon travail.', '', 28153),
(157184, 'frFR', 'Protégez notre extracteur ! Il nous faut cette azérite !', '', 28153),
(157183, 'frFR', 'Quelle stratégie préconisez-vous, Shandris ?', 'Quelle stratégie préconisez-vous, Shandris ?', 28153),
(157182, 'frFR', '', '<Les yeux perçants de Shandris balayent l\’horizon, puis elle hoche la tête.>', 28153),
(157181, 'frFR', 'Trouver Guette-Soleil et le cribler de flèches.', '', 28153),
(157180, 'frFR', 'Mon plan ?', '', 28153),
(157179, 'frFR', 'Les membres des opérations spéciales de Gnomeregan vont poser des bombes pour débusquer Guette-Soleil et nous profiterons du chaos ambiant pour l\’attaquer.', '', 28153),
(157178, 'frFR', '', 'Bonjour !', 28153),
(157177, 'frFR', 'Affirmatif ! C\’est pourquoi j\’ai recruté une équipe de commandos de choc spécialisés dans ce genre de missions.', '', 28153),
(157176, 'frFR', '', 'Concrètement… vous voulez déclencher une série d\’explosions synchronisées.', 28153),
(157175, 'frFR', 'J\’aimerais incendier simultanément tous leurs sites de fouilles.', '', 28153),
(157174, 'frFR', 'Oui. Nos renseignements mentionnent au moins trois chantiers de fouilles.', '', 28153),
(157173, 'frFR', '', 'Une mission archéologique ?', 28153),
(157172, 'frFR', 'En tant que membre du Reliquaire, Guette-Soleil est ici en mission archéologique.', '', 28153),
(157171, 'frFR', 'Je… Je m\’rappelle de rien. Mais c\’est mieux comme ça.', '', 28153),
(157170, 'frFR', '', 'Excusez-moi, qui êtes-vous, déjà ? C\’est vous dont parlait Malfurion ?', 28153),
(157168, 'frFR', 'J\’ai remis votre note à B\’wizati.', 'J\’ai remis votre note à B\’wizati.', 28153),
(157167, 'frFR', '', 'Personne n\’a été épargné… Pas même les civils ! J\’espère que certains ont réussi à fuir…', 28153),
(157166, 'frFR', '', 'Les gardes ont été empoisonnés et nos avant-postes sont tombés l\’un après l\’autre. Nous n\’avons rien vu venir…', 28153),
(157165, 'frFR', '', '%s essuie une larme et se redresse.', 28153),
(157164, 'frFR', '', 'Notre tentative d\’embuscade s\’est soldée par un échec… Nous n\’avons rien pu faire pour arrêter la Horde.', 28153),
(157163, 'frFR', 'Content d\’voir que vous allez bien, $n.\n\nMoi aussi j\’vais bien.\n\nAkunda, il m\’a donné la chance de recommencer à zéro.', '', 28153),
(157162, 'frFR', 'Quel est votre plan, haut-commandant ?', 'Quel est votre plan, haut-commandant ?', 28153),
(157161, 'frFR', 'La 7e Légion représente l\’élite d\’Azeroth.\n\nPour l\’Alliance !', '', 28153),
(157160, 'frFR', 'Qui ça ? Je connais pas de Troll qui porte ce nom, moi.', '', 28153),
(157159, 'frFR', '', 'Il y a… tant de cadavres…', 28153),
(157158, 'frFR', 'Je dois montrer quelque chose à notre $Uami:amie;. Un présent qui pourrait bénéficier à tous les habitants de ces terres.', '', 28153),
(157157, 'frFR', 'Un Nain… en diamant… au beau milieu de Zuldazar ! Qui… ?', '', 28153),
(157156, 'frFR', '', 'J\’ai vu des tas de choses étranges dans les bois, mais jamais rien de tel.', 28153),
(157155, 'frFR', 'Vous sentez ça ? Le sol… il tremble !', '', 28153),
(157153, 'frFR', 'Le chef de guerre m\’a ordonné de vous venir en aide.', 'Le chef de guerre m\’a ordonné de vous venir en aide.', 28153),
(157152, 'frFR', 'Je dois rallier Gadgetzan, en Tanaris, par la voie des airs.', 'Je dois rallier Gadgetzan, en Tanaris, par la voie des airs.', 28153),
(157151, 'frFR', 'Vous... devez...', '', 28153),
(157150, 'frFR', 'Je suis prêt... à me damner... pour l\’éternité... si cela peut garantir le bonheur de ma famille... Je vous en prie ! Vous devez...', '', 28153),
(157149, 'frFR', '', 'Je me pose chaque jour la question, Zelling.', 28153),
(157148, 'frFR', 'Cible en vue.', '', 28153),
(157147, 'frFR', '', 'Nous devenons tous un peu fous en rejoignant les Réprouvés. Mais certains plus que d\’autres.', 28153),
(157146, 'frFR', 'Vous connaissez Akunda ?', 'Vous connaissez Akunda ?', 28153),
(157145, 'frFR', 'Laissez Akunda vous débarrasser du fardeau qui pèse sur vos épaules.', 'Laissez Akunda vous débarrasser du fardeau qui pèse sur vos épaules.', 28153),
(157144, 'frFR', 'Akunda nous offre une chance de prendre un nouveau départ.', 'Akunda nous offre une chance de prendre un nouveau départ.', 28153),
(157143, 'frFR', 'Bienvenue en ces lieux.', 'Bienvenue en ces lieux.', 28153),
(157142, 'frFR', 'Tout le monde est le bienvenu dans le temple du Loa.', 'Tout le monde est le bienvenu dans le temple du Loa.', 28153),
(157141, 'frFR', 'Vous connaissez Akunda ?', 'Vous connaissez Akunda ?', 28153),
(157140, 'frFR', 'Laissez Akunda vous débarrasser du fardeau qui pèse sur vos épaules.', 'Laissez Akunda vous débarrasser du fardeau qui pèse sur vos épaules.', 28153),
(157139, 'frFR', 'Akunda nous offre une chance de prendre un nouveau départ.', 'Akunda nous offre une chance de prendre un nouveau départ.', 28153),
(157138, 'frFR', 'Bienvenue en ces lieux.', 'Bienvenue en ces lieux.', 28153),
(157137, 'frFR', 'Tout le monde est le bienvenu dans le temple du Loa.', 'Tout le monde est le bienvenu dans le temple du Loa.', 28153),
(157136, 'frFR', 'Je suis là pour vous aider, Nyse.', 'Je suis là pour vous aider, Nyse.', 28153),
(157135, 'frFR', 'Ah, le cauchemar est enfin fini.', 'Ah, le cauchemar est enfin fini.', 28153),
(157134, 'frFR', 'Prêt à tirer ! Renvoyons ce kraken dans les abysses !', 'Prêt à tirer ! Renvoyons ce kraken dans les abysses !', 28153),
(157133, 'frFR', 'Paré à faire feu !', 'Parée à faire feu !', 28153),
(157132, 'frFR', 'Doras, je cherche un vol pour Bourbe-à-Brac, dans le marécage d\’Âprefange.', 'Doras, je cherche un vol pour Bourbe-à-Brac, dans le marécage d\’Âprefange.', 28153),
(157131, 'frFR', 'Canon prêt à tirer ! Réduisez-moi cette saleté en bouillie !', 'Canon prêt à tirer ! Réduisez-moi cette saleté en bouillie !', 28153),
(157130, 'frFR', 'Non… NON !', 'Non… NON !', 28153),
(157129, 'frFR', 'Je vous remercie ! Je vais préparer ce canon pour la riposte !', 'Je vous remercie ! Je vais préparer ce canon pour la riposte !', 28153),
(157128, 'frFR', 'Zabanji ronfle.', 'Zabanji ronfle.', 28153),
(157127, 'frFR', 'Vous m\’avez sauvé ! Laissez-moi une minute pour remettre ce canon en état de marche !', 'Vous m\’avez sauvée ! Laissez-moi une minute pour remettre ce canon en état de marche !', 28153),
(157126, 'frFR', 'S\’agissait-il d\’un rêve ?', 'S\’agissait-il d\’un rêve ?', 28153),
(157125, 'frFR', 'Ne laissez pas cette sale bête me manger !', 'Ne laissez pas cette sale bête me manger !', 28153),
(157124, 'frFR', 'Faites-les griller comme des saucisses !', '', 28153),
(157123, 'frFR', 'Débarrassez-moi de cette chose !', 'Débarrassez-moi de cette chose !', 28153),
(157122, 'frFR', 'Prenez une torche et tapez sur tout ce qui bouge, $p. Ces horreurs de morts-vivants ne méritent pas la moindre pitié !', '', 28153),
(157121, 'frFR', 'Exact, soldat. Et ce port impie abrite d\’innombrables monstres à passer au fil de l\’épée !', '', 28153),
(157120, 'frFR', 'À l\’aide !', 'À l\’aide !', 28153),
(157119, 'frFR', 'Mais personne ne viendra nous voler nos victimes, chef.', '', 28153),
(157118, 'frFR', 'Qui êtes-vous ? Où sommes-nous ?', 'Qui êtes-vous ? Où sommes-nous ?', 28153),
(157117, 'frFR', 'Si ça tourne mal, nous ne recevrons ni renforts ni secours.', '', 28153),
(157116, 'frFR', 'Écoutez-moi bien, soldats. Cette mission n\’a pas d\’existence officielle.', '', 28153),
(157115, 'frFR', 'Qu\’est-ce que vous attendez, $p ?\n\nOn a des armes et un ennemi. Montez à bord !', 'Qu\’est-ce que vous attendez, $p ?\n\nOn a des armes et un ennemi. Montez à bord !', 28153),
(157114, 'frFR', 'Akunda le Fatigué ronfle.', 'Akunda la Fatiguée ronfle.', 28153),
(157113, 'frFR', 'Nous sommes tous… Akunda.', 'Nous sommes tous… Akunda.', 28153),
(157112, 'frFR', 'Encore du travail ?', '', 28153),
(157111, 'frFR', 'Ça marche.', '', 28153),
(157110, 'frFR', 'Très bien.', '', 28153),
(157109, 'frFR', 'Oui, messire.', '', 28153),
(157108, 'frFR', '', 'Oui, monsieur.', 28153),
(157107, 'frFR', 'Bien. Nous allons nous débrouiller sans elle. Gardez vos lames à portée de main, au cas où elle tarde à reprendre ses esprits.', '', 28153),
(157106, 'frFR', '', 'Elle a du mal à... s\’adapter à son nouvel état.', 28153),
(157105, 'frFR', '', 'Hnn... gh...', 28153),
(157104, 'frFR', 'Laroche, soyez assez aimable pour nous révéler le nom du plus grand héros de guerre enseveli dans ce cimetière.', '', 28153),
(157103, 'frFR', 'Maintenant que vous êtes là, nous pouvons commencer.', '', 28153),
(157102, 'frFR', 'Battez-vous pour vos frères et sœurs !', 'Battez-vous pour vos frères et sœurs !', 28153),
(157101, 'frFR', 'Victoire pour l\’Alliance !', 'Victoire pour l\’Alliance !', 28153),
(157100, 'frFR', 'À l\’assaut !', 'À l\’assaut !', 28153),
(157099, 'frFR', 'Vous êtes $udoué:douée; pour remettre de l\’ordre, $p. Tout le monde sera à l\’abri cette nuit.', '', 28153),
(157098, 'frFR', 'Arathi est à nous !', 'Arathi est à nous !', 28153),
(157097, 'frFR', 'Mort à la Horde !', 'Mort à la Horde !', 28153),
(157096, 'frFR', 'Suivez-moi !', 'Suivez-moi !', 28153),
(157095, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(157094, 'frFR', 'En avant ! On a une guerre à gagner !', 'En avant ! On a une guerre à gagner !', 28153),
(157093, 'frFR', 'La Horde a fait fuir la faune vers les plaines. Aidez les chasseurs à gérer tous ces ours.', '', 28153),
(157092, 'frFR', 'Vous… vous m\’avez forcé à tuer mon meilleur ami ! Préparez-vous à le rejoindre !', '', 28153),
(157091, 'frFR', 'Mes frères et sœurs, contemplez votre glorieux destin !', '', 28153),
(157090, 'frFR', 'Merci. Toute la vallée est derrière vous.', 'C\’est un tel soulagement de vous voir, $p. Je saurai me souvenir de ce geste.', 28153),
(157089, 'frFR', 'Je devrais pouvoir me débrouiller seul à présent. Faites attention à vous.', 'Je suis heureuse de vous voir !', 28153),
(157088, 'frFR', 'J\’ai vraiment cru que j\’allais y passer !', 'Merci. Je n\’oublierai jamais ce que vous avez fait pour moi.', 28153),
(157087, 'frFR', 'Ha ! Faut reconnaître que ces sangliers sont utiles. Je me demande s\’ils aiment les palourdes à la vapeur…', '', 28153),
(157086, 'frFR', 'Des sangliers laissés sans surveillance ont été repérés à l\’extérieur du kraal. Si ça vous dit de grimper sur l\’un d\’eux, on peut s\’attaquer aux Hurans !', '', 28153),
(157085, 'frFR', 'Venge-moi… Taptaf…', '', 28153),
(157084, 'frFR', '', 'Mon tourment… prend fin…', 28153),
(157083, 'frFR', '', 'Enfin… délivrée…', 28153),
(157082, 'frFR', '', 'C\’était… un piège…', 28153),
(157081, 'frFR', '', 'Hé hé… Le chasseur devient la proie…', 28153),
(157080, 'frFR', '', 'Il vient pour nous tous…', 28153),
(157079, 'frFR', 'Un instant, votre majesté ! De nouvelles informations nous sont parvenues.', '', 28153),
(157078, 'frFR', '', 'Ce n\’était pas… censé… se passer comme ça…', 28153),
(157077, 'frFR', '', 'C\’est tellement plus facile quand la proie se jette d\’elle-même dans le piège !', 28153),
(157076, 'frFR', '', 'Regardez ce qui vient de tomber dans mon piège !', 28153),
(157075, 'frFR', '', 'Vous êtes un peu minus, mais votre peau rejoindra quand même les autres !', 28153),
(157074, 'frFR', '', 'Ils m\’ont promis tout le gibier de la forêt !', 28153),
(157073, 'frFR', '', 'Votre peau se revendra à bon prix !', 28153),
(157072, 'frFR', '', 'Et une peau de plus, une !', 28153),
(157071, 'frFR', 'Vous… tomberez…', '', 28153),
(157070, 'frFR', 'Je retourne à la terre…', '', 28153),
(157069, 'frFR', 'La fin… est proche…', '', 28153),
(157068, 'frFR', 'Qu\’est-ce que vous voulez ? Allez, ouste, fichez le camp !', '', 28153),
(157067, 'frFR', 'Mon âme… est corrompue…', '', 28153),
(157066, 'frFR', 'Le voile est tombé…', '', 28153),
(157065, 'frFR', 'Les Ulterres nous dévoreront tous !', '', 28153),
(157064, 'frFR', 'Sa voix nous parvient de l\’au-delà !', '', 28153),
(157063, 'frFR', 'Vengez-vous et empochez le trésor !', '', 28153),
(157062, 'frFR', 'Ouais ! Chopez une torche et au boulot, $p !', 'Ouais ! Chopez une torche et au boulot, $p !', 28153),
(157061, 'frFR', 'Ouais. On va leur faire manger leurs dents et les envoyer dormir avec les poissons !', '', 28153),
(157060, 'frFR', 'Alors, on va les cramer, pas vrai ?', 'Alors, on va les cramer, pas vrai ?', 28153),
(157059, 'frFR', 'Notre ancien équipage maudit du port de Zem\’lan, il va envoyer des écumeurs tous azimuts. Et on sera l\’une de leurs cibles.', '', 28153),
(157058, 'frFR', 'Content d\’reprendre le large avec vous, les gars !', '', 28153),
(157057, 'frFR', 'Du nerf, matelots !', 'Du nerf, matelots !', 28153),
(157056, 'frFR', 'Ils accepteront peut-être de me reprendre une fois que j\’aurais retrouvé ce sort. Essayons… Lainég tse leinad !', '', 28153),
(157055, 'frFR', 'Je ne sais pas si tu me comprends, Taptaf, mais sache que je regrette de t\’avoir métamorphosé… définitivement.', '', 28153),
(157054, 'frFR', 'Et si j\’essayais tout simplement ton nom, Taptaf ? Voyons voir… Nolem nu tse Taptaf !', '', 28153),
(157053, 'frFR', 'La décision de m\’expulser était vraiment injuste, Taptaf. Ils vont goûter à mon sort le plus puissant… Enfin, dès que je me souviendrai de la formule.', '', 28153),
(157052, 'frFR', 'Hum… Non, ça n\’a pas l\’air d\’être ça.', '', 28153),
(157051, 'frFR', 'Je n\’arrive pas à me souvenir de ce fichu sort. C\’était quoi, déjà, Taptaf ? Leinad quelque chose… Noss fatsug ?', '', 28153),
(157050, 'frFR', 'J\’y vois clair désormais !', '', 28153),
(157049, 'frFR', 'Votre sang arrosera le sol de la forêt.', '', 28153),
(157048, 'frFR', 'Rrrraaaaagh !', '', 28153),
(157047, 'frFR', 'Excellent travail. Peut-être qu\’un jour, cet endroit pourra à nouveau être un lieu de culte.', '', 28153),
(157046, 'frFR', 'Cette magie va contaminer les eaux environnantes si nous ne faisons rien. Retardez les eaugures autant que possible.', '', 28153),
(157045, 'frFR', 'Que leurs âmes dévoyées soient emportées par les flots, jusqu\’au repos ultime.', '', 28153),
(157044, 'frFR', 'L\’influence néfaste de la maison Chantorage est le fait de certains individus particuliers. Éliminez-les avant qu\’ils aient l\’occasion de causer davantage de dégâts.', '', 28153),
(157043, 'frFR', 'Bien joué ! J\’aperçois la fumée d\’ici ! Nous frapperons à nouveau dès que nous le pourrons.', '', 28153),
(157042, 'frFR', 'J\’espère que vous vous entendez bien avec les griffons ! Allez voir Bernadette Robels, elle a établi un plan pour frapper la Horde au camp Croc-de-Guerre.', '', 28153),
(157041, 'frFR', '', 'Harr ?', 28153),
(157040, 'frFR', 'Tu es rien sans le Loa ! Achevez-le !', '', 28153),
(157039, 'frFR', 'Ce monstre se cache derrière le pouvoir de Rezan ! Je vais le lui reprendre !', '', 28153),
(157038, 'frFR', 'N\’oubliez jamais : il faut craindre ce qui rôde dans les profondeurs. Rien de bon ne vit dans les ténèbres les plus impénétrables.', '', 28153),
(157037, 'frFR', 'Certains de ces eaugures tentent d\’invoquer une puissance qui pourrait raser Boralus. Il faut les arrêter !', '', 28153),
(157036, 'frFR', '', 'Laissez-la faire, elle vous conduira à bon port et elle vous ramènera en un seul morceau.', 28153),
(157035, 'frFR', '', 'Elle est prête à y aller !', 28153),
(157034, 'frFR', '', 'C\’est le griffon le plus rapide de toute la vallée. Quiconque vous dira le contraire n\’est qu\’un sale menteur.', 28153),
(157033, 'frFR', 'C\’est bientôt votre tour !', 'C\’est bientôt votre tour !', 28153),
(157032, 'frFR', 'Vous êtes pas sympas, vous et l\’oiseau.', 'Vous êtes pas sympas, vous et l\’oiseau.', 28153),
(157031, 'frFR', 'Moi aussi, veux voler !', 'Moi aussi, veux voler !', 28153),
(157030, 'frFR', 'Je déteste l\’Alliance.', 'Je déteste l\’Alliance.', 28153),
(157029, 'frFR', 'Regardez ! Joli, l\’oiseau.', 'Regardez ! Joli, l\’oiseau.', 28153),
(157028, 'frFR', '', 'Le propulseur de réorigination est prêt. À nous de mettre un terme à la peste de G\’huun une bonne fois pour toutes.', 28153),
(157027, 'frFR', 'Le propulseur de réorigination est amorcé. Enclenchons-le et éradiquons-le comme le furoncle purulent qu\’il est.', '', 28153),
(157026, 'frFR', 'C\’est moi qui suis… pulvérisé ?', 'C\’est moi qui suis… pulvérisée ?', 28153),
(157025, 'frFR', 'Misérable avorton ! Je vous écrase comme un cafard !', 'Misérable avorton ! Je vous écrase comme un cafard !', 28153),
(157024, 'frFR', 'Sortez-moi de là !', 'Sortez-moi de là !', 28153),
(157023, 'frFR', 'Le jeune navrecorne beugle et court se réfugier auprès de sa mère !', 'Le jeune navrecorne beugle et court se réfugier auprès de sa mère !', 28153),
(157022, 'frFR', 'En route !', 'En route !', 28153),
(157021, 'frFR', 'Je vous emmène ?', 'Je vous emmène ?', 28153),
(157020, 'frFR', '', 'Votre entraînement a porté ses fruits. Everit serait fier de vous.', 28153),
(157019, 'frFR', '', 'Merci, madame. Je ne vous décevrai pas.', 28153),
(157018, 'frFR', '', 'C\’est pourquoi je vous nomme maréchal et chef de la garde des Malvoie.', 28153),
(157017, 'frFR', '', 'Mais Drustvar a plus que jamais besoin de vos services, et de votre présence.', 28153),
(157016, 'frFR', '', 'Inquisitrice Aubeclaire, vous avez dépassé nos espérances par vos qualités de meneuse, votre compassion, votre bravoure et votre ingéniosité.', 28153),
(157015, 'frFR', '', 'Nous déplorons tous des pertes, et pourtant, la flamme de l\’espoir resplendit.', 28153),
(157014, 'frFR', 'Rien de personnel.', 'Rien de personnel.', 28153),
(157013, 'frFR', 'L\’ennemi contrôle le cercle des Éléments… pour le moment.', 'L\’ennemi contrôle le cercle des Éléments… pour le moment.', 28153),
(157012, 'frFR', 'Je vois les bannières de la Horde flotter sur le cercle des Éléments !', 'Je vois les bannières de la Horde flotter sur le cercle des Éléments !', 28153),
(157011, 'frFR', 'La Horde contrôle le cercle des Éléments !', 'La Horde contrôle le cercle des Éléments !', 28153),
(157010, 'frFR', 'Nos bannières flottent sur le cercle des Éléments !', 'Nos bannières flottent sur le cercle des Éléments !', 28153),
(157009, 'frFR', 'Nos troupes contrôlent le cercle des Éléments.', 'Nos troupes contrôlent le cercle des Éléments.', 28153),
(157008, 'frFR', 'Le cercle des Éléments reste sous notre contrôle.', 'Le cercle des Éléments reste sous notre contrôle.', 28153),
(157007, 'frFR', 'Les bannières de la Horde flottent sur Grangeneuve… pour le moment.', 'Les bannières de la Horde flottent sur Grangeneuve… pour le moment.', 28153),
(157006, 'frFR', 'Ces monstres croient qu\’ils contrôlent Grangeneuve ? On va leur montrer…', 'Ces monstres croient qu\’ils contrôlent Grangeneuve ? On va leur montrer…', 28153),
(157005, 'frFR', 'Ces démons ne tiendront pas Grangeneuve éternellement.', 'Ces démons ne tiendront pas Grangeneuve éternellement.', 28153),
(157004, 'frFR', 'Nos troupes ont pris le contrôle de Grangeneuve.', 'Nos troupes ont pris le contrôle de Grangeneuve.', 28153),
(157003, 'frFR', 'Grangeneuve est sous notre contrôle.', 'Grangeneuve est sous notre contrôle.', 28153),
(157002, 'frFR', 'Il semble que Grangeneuve soit sous notre contrôle. Faisons en sorte que ça dure.', 'Il semble que Grangeneuve soit sous notre contrôle. Faisons en sorte que ça dure.', 28153),
(157001, 'frFR', 'Le Loa des rois est tombé. Nous devrons redoubler de prudence lors de notre prochaine chasse.\n\nRastakhan est grièvement blessé, et il vieillit à vue d\’œil. Seul le pouvoir de Rezan peut tenir en respect Bwonsamdi. Je lui prêterais bien mes forces, mais ce n\’est pas mon rôle de défier le Loa de la mort.', '', 28153),
(157000, 'frFR', 'Oui, madame ?', '', 28153),
(156999, 'frFR', '', 'L\’air suspicieux, la dresseuse de bêtes L\’kala dévisage le Gobelin à ses côtés.', 28153),
(156998, 'frFR', '', 'Votre petit gars, il a l\’air claqué à force de se battre. Il sera en sécurité, ici. Je veillerai sur lui personnellement.', 28153),
(156996, 'frFR', 'Le jeune navrecorne bâille et ferme les yeux.', 'Le jeune navrecorne bâille et ferme les yeux.', 28153),
(156995, 'frFR', 'Il est temps de partir !', 'Il est temps de partir !', 28153),
(156994, 'frFR', 'C\’est comme si on m\’avait arraché l\’âme du corps.', '', 28153),
(156993, 'frFR', 'C\’était moins une ! Merci pour votre aide !', 'C\’était moins une ! Merci pour votre aide !', 28153),
(156992, 'frFR', 'Merci pour votre aide ! J\’ignore pourquoi, mes mules anti-glaires n\’ont pas fonctionné correctement.', 'Merci pour votre aide ! J\’ignore pourquoi, mes mules anti-glaires n\’ont pas fonctionné correctement.', 28153),
(156991, 'frFR', 'Merci infiniment ! Je déposerai une réclamation dès mon retour. Les obstacles logistiques que rencontre cette expédition dépassent de loin ce que les instructions avaient couvert.', 'Merci infiniment ! Je déposerai une réclamation dès mon retour. Les obstacles logistiques que rencontre cette expédition dépassent de loin ce que les instructions avaient couvert.', 28153),
(156990, 'frFR', 'Bon sang, je vais devoir passer une semaine dans le Sanitron après ça !', 'Bon sang, je vais devoir passer une semaine dans le Sanitron après ça !', 28153),
(156989, 'frFR', 'Cette situation était pour le moins poisseuse ! Vous avez toute ma gratitude !', 'Cette situation était pour le moins poisseuse ! Vous avez toute ma gratitude !', 28153),
(156988, 'frFR', 'Les mers, puissent-elles bénir ce minerai et ne jamais chercher à reprendre ce qu\’elles ont consacré.', 'Les mers, puissent-elles bénir ce minerai et ne jamais chercher à reprendre ce qu\’elles ont consacré.', 28153),
(156987, 'frFR', 'Pourriez-vous bénir ces lingots de foudrargent ?', 'Pourriez-vous bénir ces lingots de foudrargent ?', 28153),
(156986, 'frFR', 'Nul ne peut voir dans l\’état de Réprouvé une seconde chance.', '', 28153),
(156985, 'frFR', 'Je n\’aime guère ce que vous insinuez, Zelling.', '', 28153),
(156984, 'frFR', 'Oui ! Les crustacés vaincront !', '', 28153),
(156983, 'frFR', 'Il semble que vous ayez besoin de vous carapater. Vous pigez ? Carapaces ? Crabes ! La victoire m\’appartient !', '', 28153),
(156982, 'frFR', 'Ça ne se passera pas comme ça ! Le capitaine Hermès et son trio d\’impitoyables crabes n\’ont pas dit leur dernier mot !', '', 28153),
(156981, 'frFR', 'Comment est-ce possible ?!', '', 28153),
(156980, 'frFR', 'Enfin quelqu\’un qui n\’a pas froid aux yeux !', '', 28153),
(156979, 'frFR', 'Cap sur la vallée Chantorage.', 'Cap sur la vallée Chantorage.', 28153),
(156978, 'frFR', 'Cap sur la rade de Tiragarde.', 'Cap sur la rade de Tiragarde.', 28153),
(156977, 'frFR', 'Cap sur Drustvar.', 'Cap sur Drustvar.', 28153),
(156976, 'frFR', '… Quoi ?', '', 28153),
(156974, 'frFR', 'Les rumeurs les plus folles ont circulé à mon sujet. Certains ont même été jusqu\’ à remettre en cause mon existence.', '', 28153),
(156973, 'frFR', 'Pouvez-vous me refaire le topo sur Kul Tiras ?', 'Pouvez-vous me refaire le topo sur Kul Tiras ?', 28153),
(156972, 'frFR', 'Nous remettrons les choses en ordres.', '', 28153),
(156971, 'frFR', '', 'Hé, qu\’est-ce que j\’peux faire pour vous ?', 28153),
(156970, 'frFR', 'Beau travail ! Vous avez étouffé leurs plans dans l\’œuf.', '', 28153),
(156969, 'frFR', 'Entendez-vous, comme moi, l\’appel de la mer ?', '', 28153),
(156968, 'frFR', 'Je veux être sûr que ma famille est en sécurité ! <Tousse>', '', 28153),
(156967, 'frFR', '', 'Je vous ai dit de ne pas abuser de ma…', 28153),
(156966, 'frFR', 'Des rapports font état de la présence d\’une espèce d\’horreur végétale près du kraal. Nos valets de ferme mécaniques ne devraient en faire qu\’une bouchée.', '', 28153),
(156965, 'frFR', 'Puissent les mers vous conduire à bon port.', '', 28153),
(156964, 'frFR', 'Qu\’attendez-vous de la maison Portvaillant ?', '', 28153),
(156963, 'frFR', 'Cap sur Zuldazar.', 'Cap sur Zuldazar.', 28153),
(156962, 'frFR', 'Cap sur Nazmir.', 'Cap sur Nazmir.', 28153),
(156961, 'frFR', 'Ensemble, nous sommes plus forts.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'frFR', 'Je ferai honneur à l\’héritage de mon père.', '', 28153),
(156959, 'frFR', 'J\’ai sillonné les mers pendant des années à la recherche des bernard-l\’hermite les plus redoutables que ce monde ait jamais portés. Un combat, ça vous tente, ou vous avez trop peur de vous faire balayer ?', '', 28153),
(156958, 'frFR', 'Beau travail. Ces écrits seront examinés par nos meilleurs chercheurs. Merci.', '', 28153),
(156957, 'frFR', 'Nos mages de bataille ont repéré des parchemins magiques tortollans auprès des morts. Nous devons mettre la main dessus avant la Horde. Je compte sur vous.', '', 28153),
(156956, 'frFR', 'L\’Alliance a repris Stromgarde !', 'L\’Alliance a repris Stromgarde !', 28153),
(156955, 'frFR', 'Hé, $n ! Par ici !', '', 28153),
(156954, 'frFR', 'Ohé, $p ! Paraît que vous avez fait ami-ami avec ce bon vieux Kiro et les Vulpérins.\n\nOn a pas de temps à perdre en jacasseries, alors je me contenterai de sa parole.\n\nSi vous êtes d\’attaque pour une campagne de pillage en haute mer, notre équipage, il vous accueillera à bras ouverts.\n\nGrimpez à bord et on mettra les voiles !', '', 28153),
(156953, 'frFR', 'Intéressant… Je vais demander à nos mages d\’approfondir les recherches sur ce parchemin. Merci !', '', 28153),
(156952, 'frFR', 'Ohé, $p ! Ça fait plaisir de vous revoir.\n\nUne petite bagarre au grand large, ça vous botte ? Zem\’lan, il a ordonné à ses équipages d\’appareiller et ça fait d\’eux des cibles faciles... à condition que vous sachiez viser.\n\nJe vous ai déjà $Uvu:vue; à l\’œuvre, et je parie que vous pouvez faire un carton sur ces squelettes de malheur.\n\nMontez à bord quand vous vous sentirez d\’attaque.', '', 28153),
(156951, 'frFR', 'Je vais regagner la Rédemption du vent. Le grand amiral pourra vous ramener à Boralus quand vous voudrez rentrer.', '', 28153),
(156950, 'frFR', 'J\’ai sillonné les mers pendant des années à la recherche des crabes les plus impitoyables qu\’il vous sera donné d\’affronter. Vous voulez voir à quelle vitesse vos misérables créatures vont être balayées ?', '', 28153),
(156949, 'frFR', '$n ! Qu\’est-ce que je peux faire pour vous ?', '', 28153),
(156948, 'frFR', 'Ch\’est quoi, cha ?', 'Ch\’est quoi, cha ?', 28153),
(156947, 'frFR', '$n ! C\’est bon de vous revoir. De l\’eau a coulé sous les ponts depuis que j\’ai servi sous vos ordres sur Draenor.', '', 28153),
(156946, 'frFR', 'Les Kultirassiens connaîtront la peur !', '', 28153),
(156945, 'frFR', 'Ah non... Pas ça...', 'Ah non... Pas ça...', 28153),
(156944, 'frFR', 'Pouah ! Trop amer !', 'Pouah ! Trop amer !', 28153),
(156943, 'frFR', 'Ça sent... le poisson pas frais...', 'Ça sent... le poisson pas frais...', 28153),
(156942, 'frFR', 'Vous me prenez pour qui ? Un Vrykul ? <Hips !>', 'Vous me prenez pour qui ? Un Vrykul ? <Hips !>', 28153),
(156941, 'frFR', 'Je... déteste... <Hips !> la bière ambrée...', 'Je... déteste... <Hips !> la bière ambrée...', 28153),
(156940, 'frFR', 'Ouvrez un portail pour acheminer nos troupes jusqu\’ici.', 'Ouvrez un portail pour acheminer nos troupes jusqu\’ici.', 28153),
(156939, 'frFR', 'C\’est pour moi un honneur de servir la Horde dans le cadre de mes recherches en télémancie pour Oculeth.\n\nCe sera également un honneur de quitter cet endroit à la seconde où ma tâche sera accomplie.', '', 28153),
(156938, 'frFR', 'Mes chiens… aboient plus fort… qu\’ils ne mordent…', 'Mes chiens… aboient plus fort… qu\’ils ne mordent…', 28153),
(156937, 'frFR', 'Parfait, notre proie est venue jusqu\’à nous !', 'Parfait, notre proie est venue jusqu\’à nous !', 28153),
(156936, 'frFR', 'Imprégnez cette amulette de puissance… Ce pourrait être le seul moyen de la sauver !', '', 28153),
(156935, 'frFR', 'Vous sentez ça ? Comme… un tremblement…', '', 28153),
(156934, 'frFR', '', 'Objet : Azeroth. Arythmie majeure détectée.\n\nConstantes vitales au-dessus du seuil acceptable.\n\nTentative de mise à jour des rapports d\’incident…\n\nERREUR. ERREUR. ERREUR. ERREUR.', 28153),
(156933, 'frFR', 'C\’est pas de la tisane, votre truc !', '', 28153),
(156932, 'frFR', 'Mmmmm… ça me rappelle… quand j\’étais mineur… le truc c\’était de frapper en inclinant légèrement la pioche… pour préserver le… minerai…', '', 28153),
(156931, 'frFR', '', 'ALERTE : multiples brèches détectées dans la structure de confinement.\n\nÉvacuation des installations suivantes recommandée :\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld… Uld… Uld… Uld…', 28153),
(156930, 'frFR', 'Eurgh... Ça me donne la nausée...', '', 28153),
(156929, 'frFR', 'Selon mes calculs, notre indice de réussite a chuté de deux virgule cinq cent trente-neuf pour cent, progressifs bien sûr. Il faut accélérer ces réparations !', 'Selon mes calculs, notre indice de réussite a chuté de deux virgule cinq cent trente-neuf pour cent, progressifs bien sûr. Il faut accélérer ces réparations !', 28153),
(156928, 'frFR', 'Du nerf ! Réparez-moi ces chars ! Le temps joue contre nous !', 'Du nerf ! Réparez-moi ces chars ! Le temps joue contre nous !', 28153),
(156927, 'frFR', 'Hâtez-vous ! Il ne nous reste que peu de temps pour déployer ces chars de siège avant que la Horde ne découvre notre position.', 'Hâtez-vous ! Il ne nous reste que peu de temps pour déployer ces chars de siège avant que la Horde ne découvre notre position.', 28153),
(156926, 'frFR', 'Donner du café mousseux du major', 'Donner du café mousseux du major', 28153),
(156925, 'frFR', 'Donner de l\’« Aurora Borealis »', 'Donner de l\’« Aurora Borealis »', 28153),
(156924, 'frFR', 'Donner de la vodka de sombracine amère', 'Donner de la vodka de sombracine amère', 28153),
(156923, 'frFR', 'Donner de l\’eau-de-vie de pomme de Brennadam', 'Donner de l\’eau-de-vie de pomme de Brennadam', 28153),
(156922, 'frFR', 'Donner du schnaps de la pointe du Crochet', 'Donner du schnaps de la pointe du Crochet', 28153),
(156921, 'frFR', 'Donner de l\’hydromel de Mildenhall', 'Donner de l\’hydromel de Mildenhall', 28153),
(156920, 'frFR', 'Donner de la bière ambrée des Bois-Blancs', 'Donner de la bière ambrée des Bois-Blancs', 28153),
(156919, 'frFR', 'Donner du vin de sang des Mort-aux-Dents', 'Donner du vin de sang des Mort-aux-Dents', 28153),
(156918, 'frFR', 'Ramenez-nous à Boralus.', 'Ramenez-nous à Boralus.', 28153),
(156917, 'frFR', '', 'Génial ! Je ne vous décevrai pas, $n, juré !', 28153),
(156916, 'frFR', '', 'Euh, excusez-moi ? $n ? Par ici !', 28153),
(156915, 'frFR', 'Oh, je peux faire quelque chose pour vous ?', '', 28153),
(156914, 'frFR', 'Où devrions-nous concentrer nos efforts ?', '', 28153),
(156913, 'frFR', 'Ramenez-nous à Zuldazar.', 'Ramenez-nous à Zuldazar.', 28153),
(156912, 'frFR', '', 'Vous avez besoin d\’un bateau ? D\’envoyer un message ?\n\nOU PEUT-ÊTRE D\’UN COUP DE MAIN POUR POIGNARDER QUELQU\’UN ?', 28153),
(156911, 'frFR', 'Du balai… Voyez pas… <Hips !> que chuis occupé, là ?', '', 28153),
(156910, 'frFR', '', 'Objet : Azeroth\n\nDANGER : défaillance désastreuse du système en cours.\n\nIntégrité de la planète à…\n\nCalcul en cours… Calcul en cours… Calcul en cours…', 28153),
(156909, 'frFR', 'Je n\’avais pas pris ça en compte dans mes calculs…', 'Je n\’avais pas pris ça en compte dans mes calculs…', 28153),
(156908, 'frFR', 'Selon mes calculs, vos chances de réussite sont… nulles !', 'Selon mes calculs, vos chances de réussite sont… nulles !', 28153),
(156907, 'frFR', '', 'Le mojo était puissant chez ce Huran, mais pas assez pour vous résister.', 28153),
(156906, 'frFR', '', 'La terre obéit aux ordres d\’un chaman huran. Éliminez cette menace avant qu\’elle mette nos plans en péril.', 28153),
(156905, 'frFR', 'Je dormirai mieux cette nuit en sachant que Chantorage compte quelques rochers ambulants en moins.', '', 28153),
(156904, 'frFR', 'Le petit pterreurdactyle sauvage pousse un hurlement affolé !', 'Le petit pterreurdactyle sauvage pousse un hurlement affolé !', 28153),
(156903, 'frFR', 'Un implorateur de la terre huran invoque sa propre armée d\’élémentaires. Débarrassez-nous-en, puis réglez-lui son compte !', '', 28153),
(156902, 'frFR', 'Merci. Je pensais que mon heure était venue.', 'Merci. Je pensais que mon heure était venue.', 28153),
(156901, 'frFR', 'Grâce au ciel, il existe encore de braves gens en ce monde.', 'Grâce au ciel, il existe encore de braves gens en ce monde.', 28153),
(156900, 'frFR', 'Merci ! Je peux continuer tout seul, maintenant.', 'Merci ! Je peux continuer toute seule, maintenant.', 28153),
(156899, 'frFR', 'Vengez ceux d\’entre nous qui n\’ont pas eu la chance d\’être sauvés.', 'Vengez ceux d\’entre nous qui n\’ont pas eu la chance d\’être sauvés.', 28153),
(156898, 'frFR', 'Vous ne pouvez pas imaginer ce qu\’ils nous ont fait subir…', 'Vous ne pouvez pas imaginer ce qu\’ils nous ont fait subir…', 28153),
(156897, 'frFR', 'Vous m\’avez sauvé la vie !', 'Vous m\’avez sauvé la vie !', 28153),
(156896, 'frFR', 'Je vous remercie.', 'Je vous remercie.', 28153),
(156895, 'frFR', 'J\’ai une dette envers vous.', 'J\’ai une dette envers vous.', 28153),
(156894, 'frFR', 'Votre bravoure est sans égale.', 'Votre bravoure est sans égale.', 28153),
(156893, 'frFR', 'Je n\’oublierai pas votre bonté.', 'Je n\’oublierai pas votre bonté.', 28153),
(156892, 'frFR', 'Vous arrivez à point nommé !', 'Vous arrivez à point nommé !', 28153),
(156891, 'frFR', 'Je n\’oublierai pas votre sollicitude.', 'Je n\’oublierai pas votre sollicitude.', 28153),
(156890, 'frFR', 'Je vous dois la vie.', 'Je vous dois la vie.', 28153),
(156889, 'frFR', 'Je ferais mieux de retourner me battre.', 'Je ferais mieux de retourner me battre.', 28153),
(156888, 'frFR', 'Il faut mélanger jusqu\’à obtenir une pâte onctueuse !', '', 28153),
(156887, 'frFR', 'Mélangez bien !', '', 28153),
(156886, 'frFR', 'Et enfin, la cuisson !', '', 28153),
(156885, 'frFR', 'Un petit plus pour les papilles !', '', 28153),
(156884, 'frFR', 'Un à la fois !', '', 28153),
(156883, 'frFR', 'Cette vallée mérite d\’être sauvée.', '', 28153),
(156882, 'frFR', 'Vous avez des provisions supplémentaires ?', 'Vous avez des provisions supplémentaires ?', 28153),
(156881, 'frFR', 'Rezan… il… il est parti. Cette… chose n\’est pas un Loa.', '', 28153),
(156880, 'frFR', 'Ah ! La chambre est en ruine, $n. Elle ne résistera plus très longtemps !', '', 28153),
(156879, 'frFR', 'Kul Tiras est en grand danger, Magni. Mais j\’imagine que vous n\’êtes pas là pour ça…', '', 28153),
(156878, 'frFR', '', 'Ma canne à pêche, où est-ce qu\’elle est encore passée ? Je jurerais qu\’elle était juste là...', 28153),
(156877, 'frFR', '', 'Y a des bons coins de chasse et de pêche, dans les parages, à condition de savoir où chercher.', 28153),
(156876, 'frFR', '<La brise qui caresse le côté du chariot fait craquer et gémir le bois délabré.\n\nIl semble qu\’une des roues soit bloquée.>', '', 28153),
(156875, 'frFR', '<Donner un petit coup de coude au chariot.>', '<Donner un petit coup de coude au chariot.>', 28153),
(156874, 'frFR', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVous approchez du vaisseau de la Horde. Prenez garde !', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVous approchez du vaisseau de la Horde. Prenez garde !', 28153),
(156873, 'frFR', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVous approchez du vaisseau de l\’Alliance. Prenez garde !', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|tVous approchez du vaisseau de l\’Alliance. Prenez garde !', 28153),
(156872, 'frFR', '', 'La muraille doit céder pour que la mer reprenne ses droits.', 28153),
(156871, 'frFR', '$n... Allez vous rendre utile ailleurs. Je vous ferai quérir quand nous aurons de nouveau besoin de vous.', '', 28153),
(156870, 'frFR', 'Lilian. Laroche. Venez avec moi. Vous allez m\’aider à trouver l\’un de ces... eaugures.', '', 28153),
(156869, 'frFR', 'J\’en ai plus qu\’assez de ces difficultés à répétition.', '', 28153),
(156868, 'frFR', 'Eh bien, $n ? Faites-moi voir ce que vous avez trouvé.', '', 28153),
(156867, 'frFR', 'En attendant, à vous d\’agir ! Utilisez la plate-forme de téléportation pour retourner auprès de vos alliés. Bonne chance… On en aura tous besoin.', '', 28153),
(156866, 'frFR', 'Il faut que je trouve un moyen de soigner les blessures d\’Azeroth. L\’amulette me permettra de vous contacter en cas de besoin.', '', 28153),
(156865, 'frFR', 'Gardez cette amulette près de votre cœur, $n. Elle vous aidera aux heures les plus sombres.', '', 28153),
(156864, 'frFR', 'Il nous faut donc quelque chose qui nous permette de remonter jusqu\’à lui.', '', 28153),
(156863, 'frFR', '', 'Les murailles de la forteresse s\’effondreront sous vos coups.', 28153),
(156862, 'frFR', '', 'Attendez le signal pour attaquer les murailles, Skoloth.', 28153),
(156861, 'frFR', '', 'Vous recevrez la récompense qui vous est due.', 28153),
(156860, 'frFR', '', 'Amalia, dites à Nathanos ce que vous savez au sujet des eaugures.', 28153),
(156859, 'frFR', '', 'Avec de l\’aide... peut localiser... épaves...', 28153),
(156858, 'frFR', '', 'Eaugures... prêtres... de la mer...', 28153),
(156857, 'frFR', '', 'Ah, je crois que nous avons déjà réglé la question.', 28153),
(156856, 'frFR', 'Perdu en mer ? Il nous faut son corps !', '', 28153),
(156855, 'frFR', '', 'Le maréchal M. Valentine... héros de la Deuxième guerre... perdu en mer...', 28153),
(156854, 'frFR', 'Je veux retourner à la rade de Tiragarde.', 'Je veux retourner à la rade de Tiragarde.', 28153),
(156853, 'frFR', 'Je garderai les voiles déployées pendant que vous allez régler votre affaire.', '', 28153),
(156851, 'frFR', 'OÙ EST LE CORPS ?!', '', 28153),
(156850, 'frFR', 'Attendez un peu !', '', 28153),
(156849, 'frFR', 'Valentine… Nous sommes à votre recherche depuis trop longtemps…', '', 28153),
(156848, 'frFR', 'Ne faisons pas attendre Valentine.', '', 28153),
(156847, 'frFR', 'Activation du smilotr… arg !', '', 28153),
(156846, 'frFR', 'Qu\’est-ce qu… nous ne sommes pas prêts !', '', 28153),
(156845, 'frFR', 'Nul n\’est assez fort contre le smilotron !', '', 28153),
(156844, 'frFR', 'Cinq mini-chats se rassemblent pour former un super-chat !', '', 28153),
(156843, 'frFR', 'Votre emprise ne protégera plus ce réceptacle très longtemps.', '', 28153),
(156842, 'frFR', 'Reculez, viles ténèbres.', '', 28153),
(156841, 'frFR', 'Que la marée engloutisse votre chair déformée.', '', 28153),
(156840, 'frFR', '', 'Ne les laissez pas faire du mal à Dingo !', 28153),
(156839, 'frFR', '', 'À l\’aiiiide !', 28153),
(156838, 'frFR', 'Cap sur Vol\’dun.', 'Cap sur Vol\’dun.', 28153),
(156837, 'frFR', 'Ce truc est peut-être mort, mais je vais faire de sacrés cauchemars.', '', 28153),
(156836, 'frFR', 'Mais qu\’est-ce que… qu\’est-ce que c\’est que ce machin ? Tuez-le ! Cramez-le !', '', 28153),
(156835, 'frFR', '|A:Warfront-AllianceWave3:25:23:0:0|aUne troupe d\’invasion de l\’Alliance a été déployée !', '|A:Warfront-AllianceWave3:25:23:0:0|aUne troupe d\’invasion de l\’Alliance a été déployée !', 28153),
(156834, 'frFR', 'Les Sephraks ont repéré le chariot de Meera dans les dunes. Elle est toute seule et aura besoin d\’aide pour les repousser, si jamais ils décident d\’attaquer.', '', 28153),
(156833, 'frFR', '', 'À vos ordres, conformément aux instructions de dame Sylvanas.', 28153),
(156832, 'frFR', '', 'Ramenez cet homme. Il a été choisi pour devenir un Réprouvé.', 28153),
(156831, 'frFR', 'Lilian. Nous trouverons d\’autres eaugures. Vous savez pertinemment que sa famille ne l\’acceptera jamais.', '', 28153),
(156830, 'frFR', '', 'Lilian Voss. Pourquoi avez-vous fait appel à moi ?', 28153),
(156829, 'frFR', 'Un simple contretemps. Prouvez-moi qu\’il n\’aura aucune incidence sur notre plan.', '', 28153),
(156828, 'frFR', 'C\’est un bien grand mot. Disons que c\’est quelque chose que je suis prêt à... endurer pour le bien de ma famille.', '', 28153),
(156827, 'frFR', '', 'Péniblement.', 28153),
(156826, 'frFR', 'Mais une partie de vous a survécu, n\’est-ce pas ?', '', 28153),
(156825, 'frFR', '', 'Espérons que vous viviez assez longtemps pour nous aider à trouver Valentine.', 28153),
(156824, 'frFR', 'Allons-y !', 'Allons-y !', 28153),
(156823, 'frFR', '', 'Nous pouvons demander des renforts à la Horde immédiatement. Il vous suffit d\’en donner l\’ordre.', 28153),
(156822, 'frFR', 'Humph. Ne me décevez pas.', '', 28153),
(156821, 'frFR', '', 'Je vais la chercher, Nathanos. Continuez sans nous.', 28153),
(156820, 'frFR', '', 'Stop !', 28153),
(156819, 'frFR', '', 'AAHHHH !!', 28153),
(156818, 'frFR', '', 'Je... J\’arrive pas...', 28153),
(156817, 'frFR', '', 'C\’est un bon début. Voyons ce que vous savez faire d\’autre.', 28153),
(156816, 'frFR', 'Le séminaire des Eaugures abrite en ce moment des forces de l\’Alliance et de Kul Tiras en attente de renforts. C\’est le moment ou jamais de les attaquer.', '', 28153),
(156815, 'frFR', 'Ma famille va bien ?', '', 28153),
(156814, 'frFR', '', 'Bien. Prouvez-nous que vous pouvez servir la Horde et nous verrons combien de temps encore nous vous laisserons vivre cette vie.', 28153),
(156813, 'frFR', 'Ils sont en sécurité. Aidez-nous et nous ferons en sorte qu\’ils le restent.', '', 28153),
(156812, 'frFR', '<Tousse>Je… je ferai de mon mieux, mademoiselle Voss. Vous voulez que je trouve quelqu\’un ou quelque chose, c\’est bien ça ? Voyons voir ce que je peux faire sans mon livre…', '', 28153),
(156811, 'frFR', '', 'N\’abusez pas de ma patience ou vous regretterez de ne pas avoir succombé au mal dont vous souffrez. Avant toute chose, je veux m\’assurer de la puissance de votre magie.', 28153),
(156810, 'frFR', 'Mademoiselle Voss. Après votre résurrection, avez-vous continué à subir les effets d\’une maladie qui vous affectait de votre vivant ?', '', 28153),
(156809, 'frFR', '', 'Lilian Voss. Et c\’est moi qui pose les questions. Avez-vous le pouvoir de trouver des gens ? Ou des objets ?', 28153),
(156808, 'frFR', 'L\’une des Réprouvées. Peut-être est-ce un <tousse> signe. Dites-moi, mademoiselle… ?', '', 28153),
(156807, 'frFR', '', '$n a en partie raison. Il ne vous sera fait aucun mal si vous nous aidez, de préférence avant votre mort.', 28153),
(156806, 'frFR', 'Que la Dame noire vous protège.', '', 28153),
(156805, 'frFR', 'J\’ai besoin de renforts.', 'J\’ai besoin de renforts.', 28153),
(156804, 'frFR', 'Besoin de renforts ? Donnez l\’ordre et j\’organiserai leur transport depuis Hurlevent.', '', 28153),
(156803, 'frFR', 'Il n\’y a pas une minute à perdre. De quoi avons-nous besoin ?', '', 28153),
(156802, 'frFR', 'Vous vendez chèrement votre vie… bien plus que cet adversaire, en tout cas.', '', 28153),
(156801, 'frFR', 'Nous n\’avons pour ainsi dire pas de plan, alors éliminez cette menace sans vous faire tuer.', '', 28153),
(156799, 'frFR', '%s croque gaiement la nourriture fraîche.', '', 28153),
(156798, 'frFR', '%s engloutit la verdure avec enthousiasme.', '', 28153),
(156797, 'frFR', '%s enfouit son museau dans la nourriture.', '', 28153),
(156796, 'frFR', 'Je vais vous aplatir le crâne !', 'Je vais vous aplatir le crâne !', 28153),
(156795, 'frFR', 'Qui veut être ma prochaine victime ?', 'Qui veut être ma prochaine victime ?', 28153),
(156794, 'frFR', 'Allons-y !', 'Allons-y !', 28153),
(156793, 'frFR', '[SCÈNE DE TRANSITION] - Jaina arrive ! Son armée est parvenue à percer les murs du donjon de Lordaeron ! Et, franchement, c\’était *trop* classe.', '[SCÈNE DE TRANSITION] - Jaina arrive ! Son armée est parvenue à percer les murs du donjon de Lordaeron ! Et, franchement, c\’était *trop* classe.', 28153),
(156792, 'frFR', '[SCÈNE DE TRANSITION] - Sylvanas attend dans la salle du trône quand Anduin arrive. Anduin lui offre une chance de reddition, mais elle préfère détruire toute la ville. À quoi vous attendiez-vous ?', '[SCÈNE DE TRANSITION] - Sylvanas attend dans la salle du trône quand Anduin arrive. Anduin lui offre une chance de reddition, mais elle préfère détruire toute la ville. À quoi vous attendiez-vous ?', 28153),
(156791, 'frFR', '', 'Si je pouvais ramener Kul Tiras sous le giron de l\’Alliance…', 28153),
(156790, 'frFR', '', 'Mon peuple est à la tête de la marine la plus puissante de tout Azeroth.', 28153),
(156789, 'frFR', '', 'C\’est un sort assez simple, tant que le sujet coopère.', 28153),
(156788, 'frFR', '', 'Tenez. Buvez ceci.', 28153),
(156787, 'frFR', '', 'Très bien, Amalia. Donnez-moi une seconde...', 28153),
(156786, 'frFR', 'Je suis ici pour vous demander de l\’aide, pas pour vous tuer.', 'Je suis ici pour vous demander de l\’aide, pas pour vous tuer.', 28153),
(156785, 'frFR', '<tousse> La Horde. Et moi qui pensais pouvoir mourir en paix.\n\nEh bien ? Qu\’attendez-vous ?', '', 28153),
(156784, 'frFR', '', 'Hé, $n… par ici… À côté du déchiqueteur.', 28153),
(156783, 'frFR', 'Hâtons-nous si nous voulons pouvoir profiter de l\’aide de cet eaugure.', '', 28153),
(156782, 'frFR', '', 'Quoi que vous fassiez, ça ne peut pas être pire que la maladie… Il est parti vers l\’est pour mourir en paix, loin des enfants. Je vous en prie, laissez-nous tranquilles.', 28153),
(156781, 'frFR', 'Je veux juste savoir où se trouve votre mari. Je vous promets qu\’il ne vous sera fait aucun mal, ni à vous, ni à votre famille !', '', 28153),
(156780, 'frFR', '', 'La Horde trouve qu\’elle ne m\’a pas assez fait souffrir ? Mon mari se meurt, je suis sans le sou... Laissez mes enfants en paix, par pitié.', 28153),
(156779, 'frFR', 'Cela n\’a rien d\’honorable. Il suffit de demander. Une mère éplorée n\’est pas une ennemie.', '', 28153),
(156778, 'frFR', 'Vous feriez bien de reculer, ça va barder !', '', 28153),
(156777, 'frFR', 'Place à l\’artillerie lourde.', '', 28153),
(156776, 'frFR', 'Et moi, je balance la purée !', '', 28153),
(156775, 'frFR', 'Vous désignez la cible...', '', 28153),
(156774, 'frFR', 'J\’adore mon boulot.', '', 28153),
(156773, 'frFR', 'Ha ! En voilà un qui s\’est cassé les dents !', '', 28153),
(156772, 'frFR', 'Le molosse est lâché.', '', 28153),
(156771, 'frFR', 'Ils verront rien venir.', '', 28153),
(156770, 'frFR', 'Quelqu\’un a demandé un reconfigulateur ?', '', 28153),
(156769, 'frFR', 'Je pense que ça va vous plaire !', '', 28153),
(156768, 'frFR', 'AR-8 en approche.', '', 28153),
(156767, 'frFR', 'Ça vient ! On taille dans le gras.', '', 28153),
(156766, 'frFR', 'Reçu cinq sur cinq.', '', 28153),
(156765, 'frFR', '', 'Hnngh...', 28153),
(156764, 'frFR', '', 'Plus vite vous récupérerez ces fleurs, plus vite je pourrai aider Amalia à se rendre utile.', 28153),
(156763, 'frFR', 'J\’ai entendu parler de vers géants qui se gorgent de matière en décomposition et sèment la panique à la surface. Si on en croise un, profitons-en pour l\’abattre !', '', 28153),
(156762, 'frFR', 'Vous avez fait du bon boulot. Je vous parie que ces gosses rêvent à présent de marcher dans vos pas !', '', 28153),
(156761, 'frFR', 'De jeunes fugueurs du Reflux mort qui s\’étaient mis en tête de rejoindre les pirates ont été faits prisonniers par les Lamineurs ! Vous devez sauver ces gamins.', '', 28153),
(156760, 'frFR', '', 'Pssst… $n ! Par ici !', 28153),
(156759, 'frFR', '', 'Ce monstre ne terrorisera plus jamais mon peuple. Les Loas vous sont reconnaissants.', 28153),
(156758, 'frFR', '', 'On m\’a dit que des vers se gavent de matière en décomposition et sèment le chaos à la surface. S\’ils croisent notre route, nous les exterminerons !', 28153),
(156757, 'frFR', 'Où qu\’ils sont, les bonbons qu\’on nous a promis ?', 'Est-ce que je suis une pirate, maintenant ?', 28153),
(156756, 'frFR', 'Écoutez, je sais que vous financez cette expédition, mais Gallywix va vouloir s\’assurer que la Dame noire reçoit sa part du gâteau.', '', 28153),
(156755, 'frFR', 'Je dois me rendre au cimetière de Tertrebois.', 'Je dois me rendre au cimetière de Tertrebois.', 28153),
(156754, 'frFR', '', 'Ne vous laissez pas abuser par mon nom.$b$bMes fusées sont les plus sûres de tout Kul Tiras !', 28153),
(156753, 'frFR', 'Repliez-vous ! On reprendra le combat un autre jour.', '', 28153),
(156752, 'frFR', 'Zandalari, regroupez-vous ! On peut se retirer et les laisser vivre un jour de plus.', '', 28153),
(156751, 'frFR', 'Éliminez ces envahisseurs !', '', 28153),
(156750, 'frFR', 'Vous êtes faibles !', '', 28153),
(156749, 'frFR', 'Votre fin est proche !', '', 28153),
(156748, 'frFR', 'Je suis le terrible pirate Beuford et je ne fais pas de prisonnier !', 'Je crois que je vois mon chat !', 28153),
(156747, 'frFR', 'Entrez dans la tempête, que nous puissions en finir.', '', 28153),
(156746, 'frFR', 'Vous avez même pas de jambe de bois ou de bandeau !', 'Ils m\’ont dit qu\’ils me donneraient un chapeau de pirate !', 28153),
(156745, 'frFR', 'Harr ! Donnez-moi du rhum !', 'J\’ai besoin de faire poupe-poupe !', 28153),
(156744, 'frFR', '', 'Très bien, ne vous salissez pas les mains.', 28153),
(156743, 'frFR', 'Je veux retourner à Zuldazar.', 'Je veux retourner à Zuldazar.', 28153),
(156742, 'frFR', 'Je vais garder toutes voiles dehors pour préparer notre fuite. Allez chercher l\’azérite !', '', 28153),
(156741, 'frFR', '', 'Je m\’occupe du corps, $n. Quant à vous, retournez auprès de Nathanos et dites-lui que tout se déroule conformément au plan.', 28153),
(156740, 'frFR', 'Ne comptez pas sur moi pour faire de cet homme un Réprouvé, faites-le vous-même.', 'Ne comptez pas sur moi pour faire de cet homme un Réprouvé, faites-le vous-même.', 28153),
(156739, 'frFR', '', 'Vous allez vous y faire. Et je vais vous aider.', 28153),
(156738, 'frFR', 'J\’ai pas besoin qu\’on me sauve !', 'Je suis une pirate maintenant. J\’ai plus besoin de vous écouter.', 28153),
(156737, 'frFR', '', 'Vous êtes l\’une des nôtres désormais. Ils ne vous accepteront pas.', 28153),
(156736, 'frFR', 'Lilian, débarrassez-nous de Zelling.', 'Lilian, débarrassez-nous de Zelling.', 28153),
(156735, 'frFR', '', 'Je sais ce que vous endurez, Laroche. Mais ne laissez pas ce changement l\’emporter sur votre raison, comme je l\’ai fait.', 28153),
(156734, 'frFR', 'C\’est pas juste ! J\’allais devenir un pirate !', 'Grettly m\’a vendue aux pirates !', 28153),
(156733, 'frFR', 'Lilian, occupez-vous de Zelling.', 'Lilian, occupez-vous de Zelling.', 28153),
(156732, 'frFR', '', 'Nous verrons bien. Peut-être que cette fois, les choses seront différentes.', 28153),
(156731, 'frFR', '', 'C\’est une vie horrible. Ceux qui ne se détourneront pas complètement ne vous traiteront tout de même jamais plus de la même manière, et les miroirs vous renverront l\’image d\’un monstre que vous n\’êtes pas.', 28153),
(156730, 'frFR', 'Je vous en supplie… je dois… m\’occuper de… ma famille… coûte que coûte.', '', 28153),
(156729, 'frFR', '', 'Si vous nous rejoignez, vous serez fui comme la peste. En vous regardant dans un miroir, vous ne verrez plus qu\’un monstre.', 28153),
(156728, 'frFR', 'Mademoiselle Voss, <tousse> je vous en prie… ramenez-moi… je dois venir en aide à ma famille… je ferai n\’importe quoi… n\’importe quoi…', '', 28153),
(156727, 'frFR', '', 'Quoi ? Votre famille pensera que vous êtes un monstre, ne soyez pas ridicule !', 28153),
(156726, 'frFR', '', 'Parfait. J\’ai une question à vous poser de toute façon.', 28153),
(156725, 'frFR', '<Respire difficilement> Je suis… désolé. Je… ne peux… Il ne reste plus rien… de moi…', '', 28153),
(156724, 'frFR', '', 'Zelling ! Bon sang, il faut que vous restiez en vie !', 28153),
(156723, 'frFR', 'Oui ! La vie éternelle va enfin m\’être accordée ! Je suis prêt !', '', 28153),
(156722, 'frFR', '', 'Bon, Zelling. Comprenez-vous ce qui vous attend ? Le comprenez-vous vraiment ?', 28153),
(156721, 'frFR', 'Bien joué. Vous leur avez montré de quel bois on se chauffe dans la vallée.', '', 28153),
(156720, 'frFR', 'Des éclaireurs signalent une nouvelle menace dans cette zone. Tuez-la avant qu\’elle ne devienne un problème ingérable.', '', 28153),
(156719, 'frFR', 'Soyez prudente, Jaina. Que la Lumière soit avec vous.', '', 28153),
(156718, 'frFR', '', 'Je reviendrai avec la flotte… ou je ne reviendrai jamais.', 28153),
(156717, 'frFR', 'Mais ce sera une tâche difficile… et dangereuse.', '', 28153),
(156716, 'frFR', 'En effet… et je sais que vous y parviendrez.', '', 28153),
(156715, 'frFR', '', 'Mettre un terme à ces dissensions est notre seul espoir de rapprochement.', 28153),
(156714, 'frFR', 'Jaina… vous êtes la raison de son retrait de l\’Alliance.', '', 28153),
(156713, 'frFR', '', 'Nous aussi nous devons trouver des alliés.', 28153),
(156710, 'frFR', '', 'Montrez-nous… Visualisez ce qui s\’est passé…', 28153),
(156709, 'frFR', 'Si la Horde s\’associe aux Zandalari, nous ne serons pas assez puissants pour les arrêter.', '', 28153),
(156708, 'frFR', 'Impossible ! C\’est l\’un des tours de Sylvanas. Il ne peut en être autrement…', '', 28153),
(156707, 'frFR', 'Ainsi qu\’une gigantesque flotte zandalari.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'frFR', 'Les survivants rapportent avoir affronté une magie étrange et terrifiante.', '', 28153),
(156705, 'frFR', 'Un seul est revenu.', '', 28153),
(156704, 'frFR', 'J\’en ai été informé. Et les huit navires de guerre que nous avions envoyés ?', '', 28153),
(156703, 'frFR', 'Une princesse et un prophète.', '', 28153),
(156702, 'frFR', 'Des agents de la Horde se sont récemment introduits dans la prison et ont libéré deux prisonniers zandalari.', '', 28153),
(156701, 'frFR', 'Jaina, peut-être pourriez-vous nous aider à voir ce dont a été témoin notre ami ?', '', 28153),
(156700, 'frFR', 'De nombreux voyageurs ont été tués dans cette zone. Faites le nécessaire pour éliminer le responsable de ces attaques.', '', 28153),
(156699, 'frFR', 'Tout le monde est là. Quelles sont les nouvelles, maître-espion ?', '', 28153),
(156698, 'frFR', 'Excellent travail ! Je savais que nous pouvions compter sur vous pour nous protéger.', '', 28153),
(156697, 'frFR', 'Maintenant, faut qu\’je trouve un d\’ces vaisseaux volants qu\’ils ont, là. J\’y donnerai le nom de mon fils !', '', 28153),
(156696, 'frFR', 'Alors, j\’ai fauché celui-là moi-même ! J\’vous présente la Fortune de Mala... du nom d\’ma propre fille !', '', 28153),
(156695, 'frFR', 'Quand on m\’a dit qu\’on allait avoir affaire à des pirates, j\’ai tout d\’suite pigé qu\’il me faudrait un d\’leurs bateaux !', '', 28153),
(156694, 'frFR', 'Les Nagas trament quelque chose.', '', 28153),
(156693, 'frFR', 'L\’éternité... enfin... !', '', 28153),
(156692, 'frFR', 'Quand vous voudrez y aller, utilisez la corde pour descendre jusqu\’à mon rafiot. J\’ai hâte de vous l\’montrer !', '', 28153),
(156691, 'frFR', '', 'Le prochain qui se plaint est un homme mort !', 28153),
(156690, 'frFR', '', 'Accélérez, misérables vermisseaux !', 28153),
(156689, 'frFR', '', 'Bouclez-la et mettez-vous au travail ! Cette azérite ne va pas s\’extraire toute seule !', 28153),
(156688, 'frFR', '', 'Et vous appelez ça du travail ? Vous avez de la chance qu\’on ne vous paie pas, bande de chiens !', 28153),
(156687, 'frFR', '', 'Remettez-vous au travail, bande de chiens ! Du nerf !', 28153),
(156686, 'frFR', 'Je vous en supplie, tuez-moi ! Ouvrez-moi les portes de l\’éternité en faisant de moi un Réprouvé !', '', 28153),
(156685, 'frFR', 'Je sais que vous avez volé la compagnie. Je suis là pour veiller à ce que ça ne se reproduise pas…', 'Je sais que vous avez volé la compagnie. Je suis là pour veiller à ce que ça ne se reproduise pas…', 28153),
(156684, 'frFR', 'Vous cherchez les noises ? Occupez-vous de ce qui vous regarde !', 'Vous cherchez les noises ? Occupez-vous de ce qui vous regarde !', 28153),
(156683, 'frFR', 'Circulez, matelot. Y a rien à voir ici…', 'Circulez, matelot. Y a rien à voir ici…', 28153),
(156682, 'frFR', 'Qu\’est-ce que vous regardez, matelot ?', 'Qu\’est-ce que vous regardez, matelot ?', 28153),
(156681, 'frFR', '<Tousse> Mademoiselle Voss, comment avez-vous rejoint les Réprouvés ?', '', 28153),
(156680, 'frFR', 'Ces voyous de la Horde se servent dans les réserves d\’azérite de la compagnie marchande Corsandre. Écrasez-les et récupérez ces ressources pour la 7e Légion !', '', 28153),
(156679, 'frFR', 'Si j\’ai volé, c\’était pour réchauffer un cœur qui n\’a jamais connu l\’amour !', 'Si j\’ai volé, c\’était pour réchauffer un cœur qui n\’a jamais connu l\’amour !', 28153),
(156678, 'frFR', 'Si j\’ai fait ça, c\’est parce que j\’ai reçu une éducation déplorable !', 'Si j\’ai fait ça, c\’est parce que j\’ai reçu une éducation déplorable !', 28153),
(156677, 'frFR', 'Je le referai plus, c\’est promis !', 'Je le referai plus, c\’est promis !', 28153),
(156676, 'frFR', 'Ce loup de mer de Harrington a sorti l\’artillerie lourde !', 'Ce loup de mer de Harrington a sorti l\’artillerie lourde !', 28153),
(156675, 'frFR', 'J\’arrête de voler ! C\’est fini !', 'J\’arrête de voler ! C\’est fini !', 28153),
(156674, 'frFR', 'Par pitié, ne me tuez pas ! Je vous promets de ne plus jamais voler !', 'Par pitié, ne me tuez pas ! Je vous promets de ne plus jamais voler !', 28153),
(156673, 'frFR', 'Les exilés de Zuldazar demandent une rançon en échange de nos soldats. Hors de question que nous cédions à leur chantage. Montrez-leur de quoi l\’Alliance est capable !', '', 28153),
(156672, 'frFR', 'Je vois que vous n\’avez eu aucune difficulté à les éliminer. Bien joué.', '', 28153),
(156671, 'frFR', 'Nos espions ont localisé un petit campement de la Horde sur les dunes. Frappez et décimez les troupes ennemies !', '', 28153),
(156670, 'frFR', 'Ce fut un réel plaisir de traiter avec vous. Si la piraterie vous intéresse, je serai ravi de vous compter parmi les membres de mon équipage !', '', 28153),
(156669, 'frFR', 'Je suis un homme de parole, $c. Le coffret du capitaine est à vous !', '', 28153),
(156668, 'frFR', 'Je vous retrouverai dans les quartiers du capitaine une fois Hartford mort. Ne vous en faites pas pour le coffret, tout son contenu vous reviendra !', '', 28153),
(156667, 'frFR', '', 'Nous n\’en avons pas encore fini. Vos informations sont bonnes, mais il nous faut encore jauger votre puissance.', 28153),
(156666, 'frFR', 'De grâce, dites-moi que cela suffit. Vous avez semé le chaos et la destruction dans le fort des Sages. Faites de moi un Réprouvé !', '', 28153),
(156665, 'frFR', '', 'Avons-nous eu… tort… de soutenir l\’Alliance ?', 28153),
(156664, 'frFR', '', 'Kul Tiras ne baissera jamais les bras face à la Horde !', 28153),
(156663, 'frFR', 'Le livre… devrait être jeté… à la mer…', '', 28153),
(156662, 'frFR', 'Je ne vous laisserai pas prendre ce livre, il est trop dangereux !', '', 28153),
(156661, 'frFR', '', 'Vous seriez mort avant d\’en avoir fini avec votre prochaine quinte de toux, Zelling. Vous voulez essayer ?', 28153),
(156660, 'frFR', '<Respire difficilement> Vous ne craignez pas que je vous attaque ? Ou que je tente de m\’enfuir ?', '', 28153),
(156659, 'frFR', 'Le capitaine Laroche a-t-elle perdu la raison lors de sa transformation ? Je sais parfaitement ce qui lui est arrivé.', '', 28153),
(156658, 'frFR', '', 'Devenir un Réprouvé n\’est pas une science exacte. Votre corps et votre esprit sont appelés à changer, mais dans quelle mesure… nul ne saurait le dire. Pas plus qu\’on ne peut prédire comment vous vivrez cette métamorphose.', 28153),
(156657, 'frFR', 'Non, mais pouvez-vous répondre à ma question ? Guérit-on de ses maladies lorsqu\’on devient un Réprouvé ?', '', 28153),
(156656, 'frFR', 'Avec vous à mes côtés, j\’ai toutes les chances de sortir de ce maudit désert en vie !', '', 28153),
(156655, 'frFR', 'Retrouvez-moi au port Rocherouge une fois la mission accomplie.', '', 28153),
(156654, 'frFR', 'Voilà qui ne manquait pas… d\’originalité.', '', 28153),
(156653, 'frFR', 'Tant que la Horde rôde dans ces ruines, nos alliés ne pourront pas accomplir leur mission. Les Sombrefer ont une idée pour régler le problème.', '', 28153),
(156652, 'frFR', 'La bataille de Stromgarde commence dans 2 minutes.', '', 28153),
(156651, 'frFR', 'Je crois que j\’ai perdu mon magnifique chapeau.', 'Je crois que j\’ai perdu mon magnifique chapeau.', 28153),
(156650, 'frFR', 'Conduisez-nous dans la vallée Chantorage.', 'Conduisez-nous dans la vallée Chantorage.', 28153),
(156649, 'frFR', 'Excellent travail. Voyons si quelque chose pourrait se révéler utile.', '', 28153),
(156648, 'frFR', 'Ces ruines sont celles d\’un temple englouti. Prenez garde aux Nagas qui rôdent, et bonne chance pour votre mission de reconnaissance.', '', 28153),
(156647, 'frFR', 'Je suis prêt à parlementer, Ty\’jin.', 'Je suis prête à parlementer, Ty\’jin.', 28153),
(156646, 'frFR', 'Faites-moi signe quand vous voudrez vous y mettre, chef.', '', 28153),
(156645, 'frFR', 'Bien joué. Mieux vaut éradiquer la menace avant qu\’elle ne prenne trop d\’ampleur.', '', 28153),
(156644, 'frFR', 'Nos éclaireurs font état d\’un nombre alarmant de Murlocs dans la zone. S\’ils se multiplient, nous courrons le risque d\’une attaque.', '', 28153),
(156643, 'frFR', '', 'Vous avez fait du bon travail. Les Loas sourient aujourd\’hui.', 28153),
(156642, 'frFR', '', 'La KapitalRisk détruit les terres d\’un allié précieux. Les Loas n\’apprécieraient pas. Mettez fin à ce saccage et aidez-nous à réparer les dégâts.', 28153),
(156641, 'frFR', '', 'Bien joué ! Ces Tortollans n\’oublieront jamais qui les a sauvés.', 28153),
(156640, 'frFR', '', 'Les Nagas de la côte retiennent des Tortollans pour des raisons inconnues. C\’est intolérable ! Tuez les Nagas et libérez-les.', 28153),
(156639, 'frFR', 'Les eaugures guident les âmes perdues vers la mer… mais ça, c\’est une infamie.', '', 28153),
(156637, 'frFR', 'Beau travail. Espérons que les Tortollans s\’en souviendront quand nous aurons besoin de leur aide !', '', 28153),
(156636, 'frFR', 'Je suis prêt à partir pour Lordaeron.', 'Je suis prête à partir pour Lordaeron.', 28153),
(156635, 'frFR', 'La KapitalRisk détruit le paysage côtier. Faisons un peu de ménage et peut-être que nous obtiendrons les bonnes grâces des Tortollans.', '', 28153),
(156634, 'frFR', '', 'L\’école est finie… pour toujours…', 28153),
(156633, 'frFR', '', 'Je vais vous donner une bonne leçon !', 28153),
(156632, 'frFR', 'Beau travail. Je refuse d\’imaginer ce que les Nagas avaient en tête.', '', 28153),
(156631, 'frFR', 'Des éclaireurs signalent que les Nagas des environs emprisonnent des Tortollans. Quoi qu\’ils préparent, nous devons les arrêter.', '', 28153),
(156630, 'frFR', '', 'Je connais des éleveurs de poules qui se battent mieux que ça !', 28153),
(156629, 'frFR', 'Bien joué, $p ! Nous nous rapprochons de la victoire !', '', 28153),
(156628, 'frFR', 'Leur population devrait rester sous contrôle un moment. Bien joué.', '', 28153),
(156627, 'frFR', 'Ces vipères à plumes se répandent comme la peste et la situation échappe à notre contrôle ! Détruisez leurs œufs sans tarder.', '', 28153),
(156626, 'frFR', 'Parfait. Nos soldats blessés apprécieront votre aide.', '', 28153),
(156625, 'frFR', 'Nous ferions bien d\’utiliser les ressources locales. Récupérez des glandes salivaires de pterreurdactyle pour nos blessés. Elles ont des propriétés revitalisantes.', '', 28153),
(156624, 'frFR', 'Pas étonnant que ces ravasaures puissent engloutir n\’importe quoi ! Nous ferons bon usage de ces panses. Merci.', '', 28153),
(156623, 'frFR', 'Nous avons un grand besoin de matériaux résistants. Les ravasaures de ces contrées sont réputés pour leur estomac à toute épreuve. Récupérez-en, vous voulez bien ?', '', 28153),
(156622, 'frFR', 'Argh… Neptulon… vous emporte…', '', 28153),
(156621, 'frFR', 'Qu\’est-ce que c\’est... une mutinerie ?! En garde, pourceau !', '', 28153),
(156620, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(156619, 'frFR', '', 'Mes recherches sont terminées pour l\’instant. Merci pour votre aide.', 28153),
(156618, 'frFR', '', 'La Horde mérite une bonne leçon ! Cette magie ne doit jamais tomber entre leurs mains…', 28153),
(156617, 'frFR', '', 'Grand merci pour votre aide. Cette barrière est sacrément robuste…', 28153),
(156616, 'frFR', 'L\’immortalité est à ma portée ! J\’ai hâte de devenir un Réprouvé. Imaginez toutes les possibilités !\n\nLorsque vous aurez un moment, venez partager avec moi votre expérience de la non-mort, de l\’éternité et du monde qui s\’offre à vous !', '', 28153),
(156615, 'frFR', 'Je refuse de me laisser emporter par quelque… vile maladie. Ma famille a besoin de moi.', '', 28153),
(156614, 'frFR', 'Ne dérangez pas les morts, $R.', '', 28153),
(156613, 'frFR', '', 'J\’aurais bien besoin d\’un coup de main !', 28153),
(156612, 'frFR', 'Si on ne va pas de l\’avant, on reste à la traîne. C\’est ce que je dis toujours !', '', 28153),
(156611, 'frFR', '', 'Je vais devoir procéder à des essais et rassembler des données. Couvrez mes arrières, que personne ne vienne m\’interrompre.', 28153),
(156610, 'frFR', '', 'On pourrait peut-être apprendre à se servir de cette magie, ou à la reproduire.', 28153),
(156609, 'frFR', '', 'La magie employée ici est fascinante ! Elle ne ressemble à rien de ce que j\’ai vu jusqu\’ici.', 28153),
(156608, 'frFR', '', 'Ce n\’est pas terminé !', 28153),
(156607, 'frFR', 'Mais avez-vous du temps à perdre ?', '', 28153),
(156606, 'frFR', 'J\’ai besoin d\’un nouveau déguisement.', 'J\’ai besoin d\’un nouveau déguisement.', 28153),
(156605, 'frFR', 'La Horde est là, fuyez ! On n\’est donc à l\’abri nulle part ?!', 'La Horde est là, fuyez ! On n\’est donc à l\’abri nulle part ?!', 28153),
(156604, 'frFR', 'Formidable… Maintenant que l\’Alliance est là, nos problèmes avec la Horde vont redoubler !', 'Formidable… Maintenant que l\’Alliance est là, nos problèmes avec la Horde vont redoubler !', 28153),
(156603, 'frFR', 'Je ne vais pas risquer ma vie si la Horde est déjà là !', 'Je ne vais pas risquer ma vie si la Horde est déjà là !', 28153),
(156602, 'frFR', 'Fuyez ! Voilà ce qu\’on récolte à vouloir aider l\’Alliance !', 'Fuyez ! Voilà ce qu\’on récolte à vouloir aider l\’Alliance !', 28153),
(156601, 'frFR', 'Je pensais que la Horde ne viendrait jamais jusqu\’ici !', 'Je pensais que la Horde ne viendrait jamais jusqu\’ici !', 28153),
(156600, 'frFR', 'La Horde, ici ? Mais comment ?', 'La Horde, ici ? Mais comment ?', 28153),
(156599, 'frFR', 'La Horde, fuyez !', 'La Horde, fuyez !', 28153),
(156598, 'frFR', 'This is test text, I say things in it.', '', 28153),
(156597, 'frFR', '', 'Adieu, Nathanos.', 28153),
(156596, 'frFR', '', '<Sylvanas s\’apprête à partir puis, hésitante, regarde par-dessus de son épaule.>', 28153),
(156595, 'frFR', 'Nous ne vous décevrons pas. Faites bon voyage, madame.', '', 28153),
(156594, 'frFR', '', 'Je compte sur vous. Tenez-moi informée de votre progression.', 28153),
(156593, 'frFR', 'À vos ordres, chef de guerre.', '', 28153),
(156592, 'frFR', '', 'Parfait. Voyez avec $n, notre héraut pour déterminer où établir notre première tête de pont.', 28153),
(156591, 'frFR', 'Oui, madame. La Complainte de la Banshee est prête à lever l\’ancre à tout moment.', '', 28153),
(156590, 'frFR', '', 'Les préparatifs sont-ils terminés ?', 28153),
(156589, 'frFR', '<Nathanos s\’incline.>', '', 28153),
(156588, 'frFR', 'Ma reine.', '', 28153),
(156587, 'frFR', '$n, votre présence est requise sur la Complainte de la Banshee. La Dame noire ordonne que nous lancions notre campagne sur les côtes de Kul Tiras.', '', 28153),
(156586, 'frFR', '', 'Suivez-moi.', 28153),
(156585, 'frFR', '', '$n.', 28153),
(156584, 'frFR', 'Il est placé sous la responsabilité de Garona Miorque, qui comptera sur votre aide pour orchestrer ces missions.', '', 28153),
(156583, 'frFR', 'Nous avons constitué un groupe d\’élite pour exécuter les ordres de la Dame noire.', '', 28153),
(156582, 'frFR', 'Beau travail, $p.', '', 28153),
(156581, 'frFR', 'La Horde a été alertée de notre présence et envoie des troupes. Intervenez pour permettre aux prospecteurs d\’accomplir leur mission !', '', 28153),
(156580, 'frFR', '', 'Eh bien, je dois pouvoir exaucer votre souhait, Zelling. Mais seulement si vous prouvez votre valeur aux yeux de la Horde.', 28153),
(156579, 'frFR', 'Je suis Thomas Zelling, un eaugure, un eaugure ILLUMINÉ ! Je ferai tout ce que vous me demanderez. Je suis même prêt à vous aider à attaquer l\’Alliance, mais je vous en prie, faites de moi un Réprouvé !', '', 28153),
(156578, 'frFR', 'On dirait bien que le chariot est arrivé à bon port. Votre récompense vous attend dans le donjon.', '', 28153),
(156577, 'frFR', '', 'Qui êtes-vous ? Et qu\’est-ce qui vous fait croire que vous méritez un tel honneur ?', 28153),
(156576, 'frFR', '$UUn Réprouvé;Une Réprouvée:, enfin ! Je vous en prie, tuez-moi. Faites de moi un Réprouvé… offrez-moi le don de l\’immortalité !', '', 28153),
(156575, 'frFR', '', 'Eh bien, je pourrais aller menacer la femme, afin de l\’inciter à nous donner quelques détails...', 28153),
(156574, 'frFR', 'Le Vide, les éléments <tousse>... rien n\’arrêtera donc la progression de cette maudite maladie ? Pourquoi a-t-il fallu que cela s\’achève ainsi ?', '', 28153),
(156573, 'frFR', 'Hum, l\’eaugure est passé ici il y a quelque temps. Il était aux petits soins pour sa famille.', '', 28153),
(156572, 'frFR', 'Une idée de l\’endroit où nous pourrions trouver un eaugure ?', 'Une idée de l\’endroit où nous pourrions trouver un eaugure ?', 28153),
(156571, 'frFR', 'Nous avons identifié une ligne d\’approvisionnement pour la Horde sur le champ de bataille. Belinda cherche des volontaires pour nous aider à… renflouer les réserves.', '', 28153),
(156570, 'frFR', 'Nos rapports nous indiquent que la Horde rôde près des mines. Allez voir Genny à l\’atelier pour plus d\’informations.', '', 28153),
(156569, 'frFR', 'Genny aurait bien besoin d\’un coup de main à l\’atelier. On commence à manquer de ressources.', '', 28153),
(156568, 'frFR', 'Des bénefs en veux-tu en voilà, de nouvelles terres à exploiter…$B$BQuelle époque formidable !', '', 28153),
(156567, 'frFR', 'Non, je n\’y tiens pas.', '', 28153),
(156566, 'frFR', 'Misha, tu restes ici. De notre côté, nous allons trouver cet eaugure, et vous, Lilian, vous lui ferez… ce que vous avez prévu de faire.', '', 28153),
(156565, 'frFR', '', 'Vous ne voulez pas en savoir plus, Rexxar ?', 28153),
(156564, 'frFR', 'Je suis prêt à me rendre à Fossoyeuse.', 'Je suis prête à me rendre à Fossoyeuse.', 28153),
(156563, 'frFR', '', 'Le Glas n\’existe plus. Je vous conduirai au quartier des Mages pour y rencontrer le haut seigneur dès que vous le souhaiterez.', 28153),
(156562, 'frFR', '', 'Champions, l\’heure est proche. L\’Alliance veut nous arracher le donjon de Lordaeron, mais elle tombera sous les coups de nos lames.', 28153),
(156560, 'frFR', 'Champions de l\’Alliance, l\’heure est venue de reprendre ce qui nous revient de droit ! La reconquête de Lordaeron commencera à l\’aube. La Horde et son chef de guerre doivent répondre de leurs crimes !', '', 28153),
(156559, 'frFR', '', 'Votre camarade sacrenuit se trouve dans le hall des Voies antiques. Venez me retrouver quand vous aurez fini votre tour.', 28153),
(156558, 'frFR', '', 'Mon père a amoncelé de nombreux trésors ici.', 28153),
(156557, 'frFR', '', 'On dit que le Grand Sceau est l\’une des rares choses plus anciennes que l\’empire zandalari.', 28153),
(156556, 'frFR', '', 'Venez, héraut. Laissez-moi vous faire visiter.', 28153),
(156555, 'frFR', 'Mieux vaut que vous vous chargiez de ça.', '', 28153),
(156554, 'frFR', 'J\’ai perdu la notion du temps à croupir dans cette cellule. Mais au bout du compte, peu importe.', '', 28153),
(156553, 'frFR', 'Je m\’appelle Sam, Sam Williams. Content que les gros bras soient de notre côté, pour une fois.', '', 28153),
(156552, 'frFR', 'Ces pirates sont de vrais dégénérés. Tuez-les, vous rendrez service à la société.', 'Ces pirates sont de vrais dégénérés. Tuez-les, vous rendrez service à la société.', 28153),
(156551, 'frFR', 'Dans quel pétrin on est encore allés se fourrer, hein ?', 'Dans quel pétrin on est encore allés se fourrer, hein ?', 28153),
(156550, 'frFR', 'Vous n\’avez pas fini d\’entendre parler de moi, monstres !', 'Vous n\’avez pas fini d\’entendre parler de moi, monstres !', 28153),
(156549, 'frFR', 'J\’ai tué une douzaine de ces saletés de monstres avant qu\’ils n\’arrivent à me maîtriser !', 'J\’ai tué une douzaine de ces saletés de monstres avant qu\’ils n\’arrivent à me maîtriser !', 28153),
(156548, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(156547, 'frFR', 'On n\’abandonne personne !', 'On n\’abandonne personne !', 28153),
(156546, 'frFR', 'Je savais bien que Verroctone nous abandonnerait pas ici !', 'Je savais bien que Verroctone nous abandonnerait pas ici !', 28153),
(156545, 'frFR', 'Je vous paierai un verre quand on aura regagné le bateau.', 'Je vous paierai un verre quand on aura regagné le bateau.', 28153),
(156544, 'frFR', 'J\’étais loin d\’imaginer qu\’ils avaient un tel appétit…', '', 28153),
(156543, 'frFR', 'Les ranishu ont un appétit insatiable, mais ne brillent pas par leur intelligence. Ils mangeraient même les leurs ! Tirons parti de leur faiblesse.', '', 28153),
(156542, 'frFR', '', '<Garona fait tournoyer ses lames, qui semblent disparaître.>', 28153),
(156541, 'frFR', 'Ces aigles de guerre nous mèneront à destination. On peut y aller ? Alors en selle !', '', 28153),
(156540, 'frFR', 'Partons.', '', 28153),
(156539, 'frFR', 'Ma reine a tout prévu. Notre moyen de transport nous attend sur les remparts.', '', 28153),
(156538, 'frFR', 'Moi, je voulais juste ma part de leur précieux trésor.', 'Moi, je voulais juste ma part de leur précieux trésor.', 28153),
(156537, 'frFR', 'Je reviendrai, pirates ! J\’en ai pas terminé avec vous !', 'Je reviendrai, pirates ! J\’en ai pas terminé avec vous !', 28153),
(156536, 'frFR', 'Tuez-moi ce ramassis de poltrons !', 'Tuez-moi ce ramassis de poltrons !', 28153),
(156535, 'frFR', 'Zuldazar me manque… Je vis un calvaire, ici ! Vivement la quille !', 'Zuldazar me manque… Je vis un calvaire, ici ! Vivement la quille !', 28153),
(156534, 'frFR', 'Je vois pas l\’ombre d\’un trésor, ici. Tout ça, c\’était du pipeau !', 'Je vois pas l\’ombre d\’un trésor, ici. Tout ça, c\’était du pipeau !', 28153),
(156533, 'frFR', 'Ils veulent pas de moi dans leur équipage ! C\’est pas juste.', 'Ils veulent pas de moi dans leur équipage ! C\’est pas juste.', 28153),
(156532, 'frFR', 'Un tel dévouement, c\’est rare dans le désert.', 'Un tel dévouement, c\’est rare dans le désert.', 28153),
(156531, 'frFR', 'Je ne m\’attendais pas à ce qu\’on vienne me sauver. Merci !', 'Je ne m\’attendais pas à ce qu\’on vienne me sauver. Merci !', 28153),
(156530, 'frFR', 'Quelque chose s\’est ouvert.', '', 28153),
(156529, 'frFR', 'Il en reste encore…', '', 28153),
(156528, 'frFR', 'Le compte est bon. Beau travail, $p. Je savais que je pouvais vous faire confiance.', '', 28153),
(156527, 'frFR', 'De nombreux Vulpérins sont encore piégés dans les terriers. Puis-je compter sur vous pour les secourir ?', '', 28153),
(156526, 'frFR', 'Le détecteur soigneusement calibré ne parvient à localiser aucun fossile à proximité et émet une courte note.', 'Le détecteur soigneusement calibré ne parvient à localiser aucun fossile à proximité et émet une courte note.', 28153),
(156525, 'frFR', 'L\’élémentaire d\’excavation ne parvient à localiser aucun fossile à proximité et grogne d\’agacement.', 'L\’élémentaire d\’excavation ne parvient à localiser aucun fossile à proximité et grogne d\’agacement.', 28153),
(156524, 'frFR', '', 'Pour Gilnéas !', 28153),
(156523, 'frFR', '', 'Gardes, rapportez-moi leurs têtes !', 28153),
(156522, 'frFR', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t Le gardien des Titans Hezrel commence à lancer |cFFF00000|Hspell:269310|h[Lumière purifiante]|h|r !', '', 28153),
(156521, 'frFR', '', 'La Horde a décidé de nous attaquer ici ? Ça m\’évite de devoir les traquer moi-même ! Gilnéens, à l\’attaque !', 28153),
(156520, 'frFR', 'Ces divisions sont plus compliquées que je l\’imaginais. Repassez plus tard pour récupérer votre part du trésor.', '', 28153),
(156519, 'frFR', '', 'Exactement comme la banque de Forgefer. Faut être cinq pour ce boulot.', 28153),
(156518, 'frFR', 'La gloire nous attend… et la richesse !', '', 28153),
(156517, 'frFR', 'Rendez-moi riche, $p. Je veux me payer des ratiches en or !', '', 28153),
(156516, 'frFR', '', 'T\’as encore une dent contre les Lamineurs, Eddard ?', 28153),
(156514, 'frFR', '', 'J\’ai fait le même genre de rêve, mais j\’étais dans la banque de Forgefer.', 28153),
(156513, 'frFR', '', 'Une fois qu\’on aura chopé l\’or, je prendrai un bain dans un baquet rempli de parfum.', 28153),
(156512, 'frFR', 'Peut-être nous reverrons-nous un jour. Au revoir !', '', 28153),
(156511, 'frFR', 'Libres enfin…', '', 28153),
(156510, 'frFR', 'Nous devons… fuir…', '', 28153),
(156509, 'frFR', '', 'Merci pour votre aide, $n. J\’ai à faire ailleurs.', 28153),
(156508, 'frFR', '', 'Vos intentions m\’échappent, $n, mais vous avez choisi de vous retourner contre un autre chevalier de la mort et je vous en remercie.', 28153),
(156507, 'frFR', '', 'Observez bien les cieux, $n ! Je sens que quelqu\’un approche !', 28153),
(156506, 'frFR', 'Quoi de neuf, $p ?', 'S\’il y a de l\’or à la clé, j\’en suis !', 28153),
(156505, 'frFR', 'J\’ai besoin de votre aide !', 'J\’ai besoin de votre aide !', 28153),
(156504, 'frFR', 'J\’ai survécu au roi-liche pour périr de vos mains… Argh…', '', 28153),
(156503, 'frFR', 'Quel gâchis…', '', 28153),
(156502, 'frFR', 'J\’ai besoin de votre aide.', 'J\’ai besoin de votre aide.', 28153),
(156501, 'frFR', 'Tu as gagné… dragon…', '', 28153),
(156500, 'frFR', 'Une mort… irrévocable…', '', 28153),
(156499, 'frFR', 'Vraiment… injuste…', '', 28153),
(156498, 'frFR', 'Dans ce cas, je vais devoir prendre mon dû… de force !', '', 28153),
(156497, 'frFR', 'Ah, je vois, $n ! Vous souhaitez être l\’unique chevalier de la mort à chevaucher une monture aussi splendide !', '', 28153),
(156496, 'frFR', 'Mais j\’avais jeté mon dévolu sur cette antique créature squelettique derrière vous. Si vous n\’y voyez pas d\’inconvénient, je vais donc prendre ce qui me revient.', '', 28153),
(156495, 'frFR', 'Ce drake n\’est pas bien gros… et il est encore en vie. Rien d\’insurmontable.', '', 28153),
(156494, 'frFR', 'Je ne fais que suivre votre exemple. Vous allez m\’aider ? Je vois que vous n\’êtes pas $Uvenu:venue; les mains vides !', '', 28153),
(156493, 'frFR', '$n ! Quelle surprise !', '', 28153),
(156492, 'frFR', 'Vous préférez la manière forte ? Très bien !', '', 28153),
(156491, 'frFR', '', '$n, protégez-moi ! Je n\’ai pas encore fini le rituel !', 28153),
(156490, 'frFR', 'Écarte-toi, petit drake, ce tas d\’ossements est à moi.', '', 28153),
(156489, 'frFR', 'Je vais suivre mon plan d\’origine et asservir cette créature ancestrale.', '', 28153),
(156488, 'frFR', 'Fichons le camp d\’ici !', 'Fichons le camp d\’ici !', 28153),
(156487, 'frFR', 'Un chevalier de mon envergure mérite la meilleure des montures.', '', 28153),
(156486, 'frFR', 'Deux dragons ! Quelle surprise ! Mais celui qui respire… ne m\’impressionne guère.', '', 28153),
(156485, 'frFR', '', 'Vous n\’êtes pas le bienvenu ici, chevalier de la mort.', 28153),
(156484, 'frFR', 'Tiens, tiens, qu\’est-ce que c\’est que ça ?', '', 28153),
(156483, 'frFR', 'Les disciples de Zul ne laisseront pas Rezan échapper à son sort si facilement. Nous allons devoir nous battre pour sortir d\’ici.\n\nÀ votre signal.', '', 28153),
(156482, 'frFR', 'Pourquoi tant de précipitation ? Ralentissez. Reprenez votre souffle… Faites une sieste ! Vous ne craignez rien avec nous.', '', 28153),
(156481, 'frFR', 'Mon père nous a enseigné l\’art de la forge… Ce marteau, c\’est le premier qu\’on a fabriqué ensemble.', '', 28153),
(156480, 'frFR', 'Mon marteau ! Vous l\’avez récupéré !', '', 28153),
(156479, 'frFR', '', 'Pour moi, ces exilés, c\’est ce qui se rapproche le plus d\’une famille.', 28153),
(156478, 'frFR', '', 'Bienvenue dans la bande, $p.', 28153),
(156477, 'frFR', 'Bienvenue dans la bande, $p.', '', 28153),
(156476, 'frFR', '', 'Bienvenue dans la bande, $p.', 28153),
(156475, 'frFR', 'Bienvenue dans la bande, $p.', '', 28153),
(156474, 'frFR', 'Vous voulez un petit verre de gnôle ? Ou quelque chose à manger ?', 'Vous voulez un petit verre de gnôle ? Ou quelque chose à manger ?', 28153),
(156473, 'frFR', 'Oh, c\’est vous, $p ? Dites, les Furie-des-sables vous ont pas $Usuivi:suivie;, au moins ?', '', 28153),
(156472, 'frFR', 'Encore quelques caravanes et on ira piller l\’arène, histoire de se remplir les poches !', '', 28153),
(156471, 'frFR', 'J\’ai soif ! Allez me chaparder un autre fût de cette bibine zandalari !', '', 28153),
(156470, 'frFR', 'On a plus de bois pour le feu. Trouvez-moi une autre caravane vulpérine à piller !', '', 28153),
(156469, 'frFR', 'Le désert, c\’est le fief des Furie-des-sables ! Les autres, ils sont pas les bienvenus !', '', 28153),
(156468, 'frFR', 'Amenez-moi d\’autres esclaves. J\’ai les lances qui me démangent.', '', 28153),
(156467, 'frFR', 'Brisez-les ! Brisez-les comme des chiens !', '', 28153),
(156466, 'frFR', 'Alors, on a fini de se la péter, hein ? Pour qui ils se prennent, ces Zandalari ?', '', 28153),
(156465, 'frFR', 'Ha ! Pan, en plein dans la poitrine ! Mochetés de Vulpérins…', '', 28153),
(156464, 'frFR', 'Vous voulez récupérer votre marteau, espèce de patate gratte-poussière ? EH BIEN, VENEZ LE CHERCHER !', '', 28153),
(156463, 'frFR', 'On va faire déguerpir ces saletés de Kultirassiens de nos terres ! $n, appelez la Horde et qu\’on en finisse !', '', 28153),
(156462, 'frFR', 'Votre langue, vous feriez bien de la tenir. Yazma, c\’est la grande prêtresse de ma Loa, et elle a les faveurs du roi Rastakhan.$b$bEt à en croire les rumeurs, elle est dans les petits papiers du prophète Zul.', 'Votre langue, vous feriez bien de la tenir. Yazma, c\’est la grande prêtresse de ma Loa, et elle a les faveurs du roi Rastakhan.$b$bEt à en croire les rumeurs, elle est dans les petits papiers du prophète Zul.', 28153),
(156461, 'frFR', 'Shadra est une Loa privilégiée au sein du conseil zanchuli. Ainsi, ses disciples, dont j\’ai l\’honneur de faire partie, bénéficient de nombreux avantages, parmi lesquels le droit de n\’avoir aucun compte à rendre à ceux de votre espèce.', 'Shadra est une Loa privilégiée au sein du conseil zanchuli. Ainsi, ses disciples, dont j\’ai l\’honneur de faire partie, bénéficient de nombreux avantages, parmi lesquels le droit de n\’avoir aucun compte à rendre à ceux de votre espèce.', 28153),
(156460, 'frFR', 'Allez au diable…', 'Allez au diable…', 28153),
(156459, 'frFR', 'Vous ne l\’emporterez pas…', 'Vous ne l\’emporterez pas…', 28153),
(156458, 'frFR', 'Mon roi… Pardonnez-moi…', 'Mon roi… Pardonnez-moi…', 28153),
(156457, 'frFR', 'Vous… le paierez…', 'Vous… allez le payer…', 28153),
(156456, 'frFR', 'Pour… l\’Alliance…', 'Pour… l\’Alliance…', 28153),
(156455, 'frFR', 'Les disciples de Shadra ont suivi votre espèce avec grand intérêt.$b$BNous regardons votre Horde s\’enfoncer de plus en plus profondément dans un dédale de mensonges. Bientôt, le piège se refermera, et quand vous ouvrirez les yeux, il sera trop tard.', 'Les disciples de Shadra ont suivi votre espèce avec grand intérêt.$b$BNous regardons votre Horde s\’enfoncer de plus en plus profondément dans un dédale de mensonges. Bientôt, le piège se refermera, et quand vous ouvrirez les yeux, il sera trop tard.', 28153),
(156454, 'frFR', 'À mort !', 'À mort !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'frFR', 'Je vais te renvoyer à Orgrimmar en mille morceaux !', 'Je vais te renvoyer à Orgrimmar en mille morceaux !', 28153),
(156452, 'frFR', 'Tu vas payer pour tes crimes contre l\’Alliance !', 'Tu vas payer pour tes crimes contre l\’Alliance !', 28153),
(156451, 'frFR', 'Je sers Shadra, maîtresse des espions et Loa des poisons. Qui servez-vous réellement ?', 'Je sers Shadra, maîtresse des espions et Loa des poisons. Qui servez-vous réellement ?', 28153),
(156450, 'frFR', 'Meurs, pourriture de la Horde !', 'Meurs, pourriture de la Horde !', 28153),
(156449, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(156448, 'frFR', 'Sa Seigneurie a remarqué votre présence sur son domaine. Faites preuve de prudence.', 'Sa Seigneurie a remarqué votre présence sur son domaine. Faites preuve de prudence.', 28153),
(156447, 'frFR', 'Que la Terre-Mère soit avec vous, $n.', 'Que la Terre-Mère soit avec vous, $n.', 28153),
(156446, 'frFR', 'Notre traque ne fait que commencer.', '', 28153),
(156445, 'frFR', 'Rhan\’ka se terre toujours dans son oasis ? Faudrait que j\’aille lui rendre visite un de ces quatre…', '', 28153),
(156444, 'frFR', 'Je savais bien que vous deviendriez accro ! Justement, j\’ai une fournée toute fraîche rien que pour vous !', '', 28153),
(156443, 'frFR', '[SCÈNE MONTRANT LE GÉNÉRAL JAKRA\’ZET EN TRAIN DE CONSPIRER AVEC L\’EMPEREUR KORPHEK.]', '', 28153),
(156442, 'frFR', 'Les profondeurs… me… vengeront…', 'Les profondeurs… me… vengeront…', 28153),
(156441, 'frFR', 'Je jetterai votre carcasse sanglante à la mer !', 'Je jetterai votre carcasse sanglante à la mer !', 28153),
(156440, 'frFR', '', 'J\’aurais dû naître gobeline. Eux, au moins, ils apprécient mes talents.', 28153),
(156439, 'frFR', 'J\’aurais dû faire affaire avec les Lamineurs, ils sont encore plus idiots.', '', 28153),
(156438, 'frFR', 'Faites ce qu\’il faut pendant que nous cherchons Zul. Mais préparez-vous, nous aurons bientôt besoin de votre férocité.', '', 28153),
(156437, 'frFR', '', 'Nous pourchasserons ces hérétiques jusqu\’aux confins d\’Azeroth. Je vais rassembler les miens et nous ferons s\’abattre la mort et les rochers sur la tête des viles créatures qui ont osé nous trahir.\n\nPour l\’heure, mon vol va sillonner l\’horizon afin de découvrir ce que préparent Zul et ses félons.', 28153),
(156436, 'frFR', 'Cette fois, c\’était… le coup de grâce…', '', 28153),
(156435, 'frFR', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en JcJ.>', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en JcJ.>', 28153),
(156434, 'frFR', '<File d\’attente pour l\’exploration d\’une île en JcJ.>', '<File d\’attente pour l\’exploration d\’une île en JcJ.>', 28153),
(156433, 'frFR', 'Utilisez le fétiche de Jin\’Tiki pour tuer Zulajin !', 'Utilisez le fétiche de Jin\’Tiki pour tuer Zulajin !', 28153),
(156432, 'frFR', 'J\’espère seulement avoir assez bien caché ma clé pour que personne d\’autre que toi ne la trouve.', '', 28153),
(156431, 'frFR', 'Votre valeur est indiscutable, Kaga, mais vous n\’êtes pas en état de vous battre. $n, je vais l\’accompagner. Rejoignez-nous à la tour de guerre.', '', 28153),
(156430, 'frFR', 'Merci. Je vais sécuriser la tour de guerre. Il va nous falloir rappeler le reste des troupes.', 'Merci. Je vais sécuriser la tour de guerre. Il va nous falloir rappeler le reste des troupes.', 28153),
(156429, 'frFR', '', 'Mes sœurs… vous tueront…', 28153),
(156428, 'frFR', 'La Horde tombera…', 'La Horde tombera…', 28153),
(156427, 'frFR', 'Votre chef est folle à lier…', 'Votre chef est folle à lier…', 28153),
(156426, 'frFR', 'Espèce de monstres…', 'Espèce de monstres…', 28153),
(156425, 'frFR', 'Je… vous… tuerai…', 'Je… vous… tuerai…', 28153),
(156424, 'frFR', 'La Horde paiera…', 'La Horde paiera…', 28153),
(156423, 'frFR', 'Pour Teldrassil…', 'Pour Teldrassil…', 28153),
(156422, 'frFR', 'Mes sœurs… J\’ai failli…', 'Mes sœurs… J\’ai failli…', 28153),
(156421, 'frFR', '', 'Ma famille est morte à Teldrassil ! Je vais vous tuer !', 28153),
(156420, 'frFR', '', 'Nous vengerons Teldrassil !', 28153),
(156419, 'frFR', 'Faisons en sorte que les Kultirassiens y réfléchissent désormais à deux fois avant de miser contre la Horde.', '', 28153),
(156418, 'frFR', 'Pour Teldrassil et pour l\’Alliance !', 'Pour Teldrassil et pour l\’Alliance !', 28153),
(156417, 'frFR', 'Souffrez et mourez, pourriture de la Horde !', 'Souffrez et mourez, pourriture de la Horde !', 28153),
(156416, 'frFR', '', 'Assassins ! Comment osez-vous venir ici ?', 28153),
(156415, 'frFR', 'On va par là !', '', 28153),
(156414, 'frFR', 'Maintenant, c\’est moi qui marche !', '', 28153),
(156413, 'frFR', 'C\’est moi qui décide où on va !', '', 28153),
(156412, 'frFR', 'Maintenant, c\’est moi les jambes !', '', 28153),
(156411, 'frFR', 'C\’est moi qui conduis !', '', 28153),
(156410, 'frFR', 'Que les flammes sacrées vous purifient !', '', 28153),
(156409, 'frFR', 'Non… Je dois… trouver l\’anneau…', '', 28153),
(156408, 'frFR', 'Bande de monstres ! J\’enverrai vos têtes à votre chef de guerre !', 'Bande de monstres ! J\’enverrai vos têtes à votre chef de guerre !', 28153),
(156407, 'frFR', 'Votre tête sera un trophée pour ma reine !', '', 28153),
(156406, 'frFR', '', 'La Horde va payer pour ses méfaits à Teldrassil !', 28153),
(156405, 'frFR', '', 'Je vais vous en donner, des corps en feu !', 28153),
(156404, 'frFR', '', 'On dirait que nous en avons terminé ici ! Faites attention à vous, $p.', 28153),
(156403, 'frFR', 'Mes hommes seront vengés, je le jure.', 'Mes hommes seront vengés, je le jure.', 28153),
(156402, 'frFR', 'Pitoyables mortels ! Vous ne pouvez empêcher mon retour.', '', 28153),
(156401, 'frFR', '', 'Vous ! Membres de la Horde. J\’ai besoin de vos compétences.', 28153),
(156400, 'frFR', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Une nouvelle |cFFFF0404|Hspell:263420|h[Matrice de puissance]|h|r est disponible.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Une nouvelle |cFFFF0404|Hspell:263420|h[Matrice de puissance]|h|r est disponible.', 28153),
(156399, 'frFR', 'Ce Troll, il pédale dans la gelée royale.', '', 28153),
(156398, 'frFR', 'Rikati lève les yeux au ciel.', '', 28153),
(156397, 'frFR', 'Compris, mon pote ! Compte sur moi ! Merci !', '', 28153),
(156396, 'frFR', 'Pas le temps de causer, Rikati ! Les Furie-des-sables, ils saccagent tout ! Planque ton miel !', '', 28153),
(156395, 'frFR', 'L\’anneau des marées sera nôtre ! La reine Azshara l\’exige !', 'L\’anneau des marées sera nôtre ! La reine Azshara l\’exige !', 28153),
(156394, 'frFR', 'Nous ne reculerons devant rien pour nous emparer de l\’anneau !', 'Nous ne reculerons devant rien pour nous emparer de l\’anneau !', 28153),
(156393, 'frFR', 'Mais c\’est quoi que vous baragouinez ? Compter ? Moi ? Jamais de la vie. C\’est votre boulot, ça.\n\nVous savez quoi, on va tout reprendre à zéro.', '', 28153),
(156392, 'frFR', 'Où est l\’anneau des marées ? Inutile de chercher à le cacher !', 'Où est l\’anneau des marées ? Inutile de chercher à le cacher !', 28153),
(156391, 'frFR', 'L\’anneau des marées a été perdu par ici. La reine doit à tout prix le récupérer !', 'L\’anneau des marées a été perdu par ici. La reine doit à tout prix le récupérer !', 28153),
(156390, 'frFR', 'L\’influence du Sillage des tempêtes ne cesse de croître. Vous êtes avec nous ?', 'L\’influence du Sillage des tempêtes ne cesse de croître. Vous êtes avec nous ?', 28153),
(156389, 'frFR', 'Alors, j\’ai atteint le million d\’âmes ?', 'Alors, j\’ai atteint le million d\’âmes ?', 28153),
(156388, 'frFR', 'Nul ne s\’opposera à notre reine !', 'Nul ne s\’opposera à notre reine !', 28153),
(156387, 'frFR', 'L\’anneau des marées nous revient de droit !', 'L\’anneau des marées nous revient de droit !', 28153),
(156386, 'frFR', 'Nous pouvons encore arrêter le seigneur Chantorage.', 'Nous pouvons encore arrêter le seigneur Chantorage.', 28153),
(156385, 'frFR', 'L\’anneau sera nôtre !', 'L\’anneau sera nôtre !', 28153),
(156384, 'frFR', 'La reine Azshara veut l\’anneau des marées et elle l\’aura !', 'La reine Azshara veut l\’anneau des marées et elle l\’aura !', 28153),
(156383, 'frFR', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t Le serpent doré absorbe de l\’or animé et bénéficie de |cFFFF0000|Hspell:265991|h[Lustre]|h|r !', 'Le serpent doré absorbe de l\’or animé et bénéficie de |TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t optional text here |cFFFF0000|Hspell:265991|h[Lustre]|h|r!', 28153),
(156382, 'frFR', '', 'Oh oh ! C\’est pas bon, ça ! PAS BON DU TOUT !', 28153),
(156381, 'frFR', 'Utilisez l\’une de ces cordes pour rejoindre une embarcation… à moins que vous ne préfériez y aller à la nage.', '', 28153),
(156380, 'frFR', 'Je refuse de continuer à laver les sous-vêtements de ces cochons d\’Humains !', '', 28153),
(156379, 'frFR', '', 'Mes chaussettes sont trempées ! Merci.', 28153),
(156378, 'frFR', '', 'Je commence à en avoir assez !', 28153),
(156377, 'frFR', 'Vous m\’avez sauvé d\’un horrible sort.', '', 28153),
(156375, 'frFR', 'Pendant que vous couriez l\’aventure, je me suis entraîné.', 'Pendant que vous couriez l\’aventure, je me suis entraînée.', 28153),
(156374, 'frFR', '<Le maître-espion Shaw acquiesce d\’un signe de tête.>', '', 28153),
(156373, 'frFR', 'Nous voilà, maître-espion.', '', 28153),
(156372, 'frFR', 'Je vais travailler avec le maître-espion Shaw. À défaut d\’être le type le plus aimable qui soit, il connaît son affaire.', '', 28153),
(156371, 'frFR', 'Le roi a mobilisé la crème des héros pour cette campagne.', '', 28153),
(156370, 'frFR', 'Vol-au-Vent, va donc te trouver de quoi casser une graine.', '', 28153),
(156369, 'frFR', 'Suivez-moi, $Ujeune homme:jeune fille;.', '', 28153),
(156368, 'frFR', 'En plein dans le genou !', 'Oh… Ça doit faire mal !', 28153),
(156367, 'frFR', 'On ne baisse pas les bras aussi facilement.', 'Ils auraient dû fuir tant qu\’ils le pouvaient encore.', 28153),
(156366, 'frFR', 'Encore un de moins !', 'Ils ne sont pas aussi coriaces qu\’ils l\’imaginaient !', 28153),
(156365, 'frFR', 'Bonjour, capitaine Laroche. Je suis impatient de faire votre connaissance.', '', 28153),
(156364, 'frFR', 'Alors, chargez-le dans le chariot. Je ne m\’attendais pas à ce que vous me fussiez aussi utile, mademoiselle Voss.', '', 28153),
(156363, 'frFR', '', 'Suffisamment.', 28153),
(156362, 'frFR', 'À peu près intact ?', '', 28153),
(156361, 'frFR', '', 'Ici, Nathanos. J\’ai récupéré le corps.', 28153),
(156360, 'frFR', 'Beau travail, $p. Et Lilian, où est-elle ?', '', 28153),
(156359, 'frFR', 'Il faut faire vite… Ils vont s\’en prendre à Rezan !', '', 28153),
(156358, 'frFR', 'Ils… ils m\’ont forcé à leur dire comment les Drakkari, ils avaient fait.', '', 28153),
(156357, 'frFR', 'Excellent. $p, Taelia va vous expliquer où nous en sommes.', '', 28153),
(156356, 'frFR', '', 'Le rapport de situation est prêt !', 28153),
(156355, 'frFR', '', 'Vous avez réduit leur armée en pièces ! Beau travail.', 28153),
(156354, 'frFR', '', 'Les sorcières commencent à reconstituer leurs troupes. Prenez le contrôle d\’un démolisseur et sapez leur armée !', 28153),
(156353, 'frFR', '', 'Nous devons montrer aux Kultirassiens ce qu\’il en coûte de se faire un ennemi de la Horde.', 28153),
(156352, 'frFR', 'N\’oubliez pas que Port-du-Pont est une importante bourgade bien défendue. Essayez de rester à sa périphérie… du moins pour l\’instant.', '', 28153),
(156351, 'frFR', 'Nous avons fait notre part du travail, $p. Je suis fier de ce que nous avons accompli ici.\n\nMais l\’heure est venue de veiller sur les miens et leur sécurité.\n\nJe suis sûr que nous nous reverrons. C\’est un honneur de vous avoir pour $Uami et allié:amie et alliée;.', '', 28153),
(156350, 'frFR', 'Les infidèles se montrent cruels avec leurs bêtes. Ce n\’est pas sorcier de les retourner contre leurs maîtres.', '', 28153),
(156349, 'frFR', 'Je refuse d\’endurer ça. J\’ai été nommé à ce poste par Zul le prophète en personne !', '', 28153),
(156348, 'frFR', '', 'Alors ÇA, c\’était un combat digne des légendes !\n\nC\’est un honneur de me battre à vos côtés, à vous et Vorrik. J\’ai hâte de remettre ça.\n\nAprès tout, ce ne sont pas les infidèles à abattre qui manquent.', 28153),
(156347, 'frFR', 'Mettons un terme à cette folie, ensemble.', '', 28153),
(156346, 'frFR', '', 'Allons donner une bonne leçon à ces Sephraks.', 28153),
(156345, 'frFR', '', 'Ceci va nous permettre de poursuivre le combat contre le Sabbat. Merci.', 28153),
(156344, 'frFR', 'Suivez-moi. Le camp n\’est pas loin d\’ici.', '', 28153),
(156343, 'frFR', 'Bien. Elle fera une cible parfaite.', '', 28153),
(156342, 'frFR', '', 'La ville près de laquelle nous sommes passés, Port-du-Pont, semble être la plus importante de la région.', 28153),
(156341, 'frFR', 'Rexxar ! <Tousse.> Les autres résistent encore. Mais… le temps presse.', 'Rexxar ! <Tousse.> Les autres résistent encore. Mais… le temps presse.', 28153),
(156340, 'frFR', 'Quel soulagement ! Cette bête ne mangera plus les soldats de la Horde. Une mort méritée.', '', 28153),
(156339, 'frFR', '', 'Nous avons besoin d\’argent pour affronter les sorcières, mais nos réserves commencent à se tarir. Allez en chercher dans les mines.', 28153),
(156338, 'frFR', 'Rakjan semble prêt à nous aider, et on comprend aisément pourquoi.\n\nLes infidèles se sont montrés cruels envers lui et sa couvée. La preuve, regardez plutôt son corps couturé de cicatrices et tous ces perchoirs vides, sur son sommet.\n\nIl mérite de prendre sa revanche au moins autant que nous. Nous allons rendre justice ensemble.', '', 28153),
(156337, 'frFR', 'Oui, Samuel. Restez fort.', '', 28153),
(156336, 'frFR', 'J\’ai si froid. Les voix vont-elles bientôt se taire ?', '', 28153),
(156335, 'frFR', '$n, remuez un peu cette potion, sinon elle va brûler.', '', 28153),
(156334, 'frFR', 'Joli travail. Tâchons de faire en sorte que cette petite sauterie soit la dernière du conseil.', '', 28153),
(156333, 'frFR', 'Joli travail. Y a plus qu\’à ruiner la petite fête du conseil.', '', 28153),
(156332, 'frFR', 'Du calme. Les herbes vont apaiser vos souffrances. Que pouvez-vous nous dire sur la situation dans le camp ? Reste-t-il des survivants ?', '', 28153),
(156331, 'frFR', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t Chaque charge de |cFFFF0404|Hspell:260512|h[Récolte d\’âmes]|h|r augmente les dégâts du goliath des âmes !', '', 28153),
(156330, 'frFR', 'Regardez ! Celui-là respire encore !', '', 28153),
(156329, 'frFR', 'Nombre de guerriers courageux ont succombé au cours de cette bataille. Votre arrivée nous a sauvé la mise.', '', 28153),
(156328, 'frFR', 'Les Kultirassiens ont attaqué pendant que nous tentions de secourir les équipages. Hélas, nous n\’étions pas assez nombreux pour tenir les deux positions et nous avons dû nous replier sur le rivage.', '', 28153),
(156327, 'frFR', 'L\’attaque s\’est produite tôt ce matin. Les mages kultirassiens ont utilisé un objet étrange pour invoquer ces horreurs que vous avez vues autour de nos bateaux.', '', 28153),
(156326, 'frFR', 'Résultat confirmé. La mission est un succès. La perfection incarnée ! J\’adore quand un plan se déroule sans accroc. Terminé.', '', 28153),
(156325, 'frFR', 'Suite des instructions : vous voyez le gros bouton rouge ? Évacuez la zone et PRESSEZ ce bouton. Exécution à votre convenance. Terminé.', '', 28153),
(156324, 'frFR', 'Code de déverrouillage : un, neuf, neuf. L\’alignement ne répond pas aux paramètres… Correction… Je peux y arriver. Maintenez votre position. Terminé.', '', 28153),
(156323, 'frFR', 'Reçu. Calibrage terminé. Vous devez aligner les instruments avec précision. Contactez-moi quand ils seront en place. Terminé.', '', 28153),
(156322, 'frFR', 'Test radio. Ici, Alpha 1. Destinataire : escouade alpha. Est-ce que vous me recevez ? À vous.', '', 28153),
(156321, 'frFR', 'Un glorieux combat ! Et une fin heureuse, $p !', '', 28153),
(156320, 'frFR', '', 'La flamme ne meurt jamais…', 28153),
(156319, 'frFR', '', 'Poussière, tu redeviendras poussière…', 28153),
(156318, 'frFR', 'Vos actions nous touchent énormément, $p. Merci mille fois.', '', 28153),
(156317, 'frFR', '', 'Vos os feront un excellent combustible.', 28153),
(156316, 'frFR', '', 'Je ne laisserai personne pour pleurer sur vos cendres.', 28153),
(156315, 'frFR', 'Notre longue histoire n\’a connu que peu de jours aussi glorieux que celui-ci !', '', 28153),
(156314, 'frFR', 'Je vais créer une nouvelle soupe en votre honneur !', '', 28153),
(156313, 'frFR', 'La soupe de tortue est loin d\’être aussi bonne que la soupe |2 $R.\n\nConcentrez-vous sur les vers de boue et laissez les petites tortues tranquilles.\n\nNous nous intéresserons aux autres recettes une prochaine fois !', '', 28153),
(156312, 'frFR', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t La %s commence à lancer |cFFFF0000|Hspell:267334|h[Orbe de corruption]|h|r !', 'Une projection apparaît au loin…', 28153),
(156311, 'frFR', '', 'Il est si simple de s\’égarer.', 28153),
(156310, 'frFR', 'Faites-moi signe si vous avez besoin d\’aide !', '', 28153),
(156309, 'frFR', 'Maintenant que tout est réglé, je vais pouvoir rentrer au bercail.', '', 28153),
(156308, 'frFR', '|cFF0000FF(Quête)|r Cap sur la rade de Tiragarde.', '|cFF0000FF(Quête)|r Cap sur la rade de Tiragarde.', 28153),
(156307, 'frFR', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t La %s commence à lancer |cFFFF0000|Hspell:265360|h[Tromperie frémissante]|h|r !', 'Une projection apparaît au loin…', 28153),
(156306, 'frFR', '', 'Je vous suis reconnaissante de votre aide.', 28153),
(156305, 'frFR', '', 'Les ombres du passé nous entourent.', 28153),
(156304, 'frFR', 'Arrêtez donc de me prendre pour une enclume, vous allez me rendre marteau… Hahahahaha !', '', 28153),
(156303, 'frFR', 'Vous voudriez pas vous retrouver entre le marteau et l\’enclume ?', '', 28153),
(156302, 'frFR', 'Attention ou je me sers de mon marteau !', '', 28153),
(156301, 'frFR', 'Que votre flamme brûle fort.', '', 28153),
(156300, 'frFR', 'Je crois en vous, dur comme fer.', '', 28153),
(156299, 'frFR', 'Amusez-vous bien !', '', 28153),
(156298, 'frFR', 'Vous auriez pas vu ma clé à molette dans le coin ?', '', 28153),
(156297, 'frFR', 'Je peux faire quelque chose pour vous ?', '', 28153),
(156296, 'frFR', 'Allez-y, parlez !', '', 28153),
(156286, 'frFR', '', 'Tant de chagrin et tant de pertes.', 28153),
(156285, 'frFR', '', 'Quelle voie suivre ?', 28153),
(156284, 'frFR', '', 'Je dois traverser cette épreuve.', 28153),
(156283, 'frFR', 'Le sable est rouge.', 'Le sable est rouge.', 28153),
(156282, 'frFR', 'Comment je suis arrivé ici ?', 'Comment je suis arrivée ici ?', 28153),
(156281, 'frFR', 'Mes amis me vengeront.', 'Mes amis me vengeront.', 28153),
(156280, 'frFR', 'Résumons : Turalyon est tout brillant et Alleria devient toute sombre… Hmm… J\’imagine que maintenant que je suis de retour, moi aussi je vais devoir trouver mon truc en plus !', '', 28153),
(156279, 'frFR', 'Alors, comment j\’étais ?', 'Alors, comment j\’étais ?', 28153),
(156278, 'frFR', 'Je vais vous massacrer !', 'Je vais vous massacrer !', 28153),
(156277, 'frFR', 'C\’est fini pour vous !', 'C\’est fini pour vous !', 28153),
(156276, 'frFR', 'Vous ne pouvez pas nous arrêter !', 'Vous ne pouvez pas nous arrêter !', 28153),
(156275, 'frFR', 'Louée soit la Lumière, je me suis enfin extirpé du bastion de l\’Honneur. Ça devenait étouffant, là-bas.', '', 28153),
(156274, 'frFR', 'Pas aujourd\’hui, monstre !', 'Pas aujourd\’hui, monstre !', 28153),
(156273, 'frFR', 'Khadgar et moi nous retrouvons une fois par semaine pour jouer aux dames. (Et entre nous… il triche.)', '', 28153),
(156272, 'frFR', 'Nous devons tous accomplir notre devoir.', '', 28153),
(156271, 'frFR', 'Pour Stromgarde !', '', 28153),
(156270, 'frFR', 'Je vais pas vous mentir, chef.\n\nJ\’ai toujours rêvé de participer à une mutinerie.', '', 28153),
(156269, 'frFR', 'Pour l\’Alliance !', '', 28153),
(156268, 'frFR', 'L\’Alliance vaincra.', '', 28153),
(156267, 'frFR', 'Combattez avec vaillance, mon $uami:amie;.', '', 28153),
(156266, 'frFR', 'Azeroth appelle, et nous devons lui répondre.', '', 28153),
(156265, 'frFR', 'Nous nous battrons pour ce qui est à nous.', '', 28153),
(156264, 'frFR', 'Quoi qu\’il arrive, nous ferons front ensemble.', '', 28153),
(156263, 'frFR', 'Ma vie pour l\’Alliance.', '', 28153),
(156262, 'frFR', 'Stromgarde sera fière à nouveau.', '', 28153),
(156261, 'frFR', 'Vous pouvez bien lever les yeux au ciel, mais je vais quand même le dire… LE MARTEAU VA FRAPPER !!', '', 28153),
(156260, 'frFR', 'On pourrait dire que je souffre d\’être le cadet. Mais entre un aîné entièrement fait de diamant et un benjamin célèbre explorateur, difficile de me trouver une place à part entière !', '', 28153),
(156259, 'frFR', 'Qu\’est-ce que… ?! Quelqu\’un vient de m\’appeler le « roi des bonbons » et m\’a demandé une sucette !', '', 28153),
(156258, 'frFR', 'Nous n\’abandonnons jamais le combat !', '', 28153),
(156257, 'frFR', 'Le clan Barbe-de-Bronze vous remercie.', '', 28153),
(156256, 'frFR', 'Forgefer triomphera.', '', 28153),
(156255, 'frFR', 'Que votre voie vous apporte la gloire.', '', 28153),
(156254, 'frFR', 'Que votre marteau frappe juste.', '', 28153),
(156253, 'frFR', 'Que la forge soit avec vous, mon $uami:amie;.', '', 28153),
(156252, 'frFR', 'J\’ai mon marteau, ma hache… il est temps de se mettre au travail !', '', 28153),
(156251, 'frFR', 'Vous venez aider l\’Alliance ?', '', 28153),
(156250, 'frFR', 'Les Trois marteaux ne font qu\’un.', '', 28153),
(156249, 'frFR', 'Forgefer apportera sa pierre à l\’édifice.', '', 28153),
(156248, 'frFR', 'Vous savez ce qui est arrivé aux six premières légions ? Vous voulez le découvrir ?', '', 28153),
(156247, 'frFR', 'Soldat, continuez ainsi et vous irez au cachot !', '', 28153),
(156246, 'frFR', 'Vous mettez ma patience à rude épreuve.', '', 28153),
(156245, 'frFR', 'Notre travail ne fait que commencer.', '', 28153),
(156244, 'frFR', 'À notre prochaine rencontre.', '', 28153),
(156243, 'frFR', 'Que la Lumière soit avec vous.', '', 28153),
(156242, 'frFR', 'Par la puissance de l\’Alliance, nos ennemis ne connaissent que défaite.', '', 28153),
(156241, 'frFR', 'Par la Lumière, soyons les premiers à frapper.', '', 28153),
(156240, 'frFR', 'Vous commencez à faire parler de vous.', '', 28153),
(156239, 'frFR', 'Le destin nous sourit, aujourd\’hui.', '', 28153),
(156238, 'frFR', 'La Horde sombrera.', '', 28153),
(156237, 'frFR', 'Soldat.', '', 28153),
(156236, 'frFR', 'Nous sommes tous les fils et les filles de l\’Alliance.', '', 28153),
(156235, 'frFR', '', 'Ce monde doit être défendu. En avant, Sombrefer ! Allons au combat !', 28153),
(156234, 'frFR', '', 'Le sang qui coule dans nos veines… coule aussi dans tout Azeroth.', 28153),
(156233, 'frFR', '', 'Notre histoire a été forgée par le marteau et l\’enclume. Notre cœur est de feu et notre volonté de fer.', 28153),
(156232, 'frFR', '', 'La montagne nous donne la vie. Elle nous donne la force.', 28153),
(156231, 'frFR', '', 'Thurgaden et Thaelin ont confectionné un ensemble d\’armure digne de vos exploits. Portez-le avec fierté, $n.', 28153),
(156230, 'frFR', '', 'L\’Alliance sait maintenant de quoi les Sombrefer sont capables. Nous sommes fiers que vous nous représentiez.', 28153),
(156229, 'frFR', '', 'Revenez à la montagne. Nous avons quelque chose pour vous.', 28153),
(156228, 'frFR', '', 'Vous nous avez rendus fiers, $n. J\’ai eu vent de vos actes de bravoure à la surface d\’Azeroth.', 28153),
(156227, 'frFR', '', 'Nous sommes forgés dans le feu de la montagne, $n. Montrez votre flamme au monde.', 28153),
(156226, 'frFR', '', 'Azeroth vous attend. Hurlevent sera la première étincelle à jaillir du fer.', 28153),
(156225, 'frFR', '', 'Il est temps que les Sombrefer émergent de l\’ombre.', 28153),
(156224, 'frFR', '', 'Nombre des nôtres nous ont dissuadés de remonter à la surface. Mais les braves n\’ont pas écouté.', 28153),
(156223, 'frFR', 'Pour l\’Alliance !', '', 28153),
(156222, 'frFR', '', 'Les Sombrefer acceptent votre invitation. Pour l\’Alliance !', 28153),
(156221, 'frFR', '', 'Ce n\’est qu\’une formalité, votre altesse ! Il n\’y a pas de mal.', 28153),
(156220, 'frFR', 'Pour autant, je n\’ai, à ce jour, jamais formellement invité votre clan à rejoindre l\’Alliance… Permettez-moi de rectifier ce manque avec mes plus sincères excuses.', '', 28153),
(156219, 'frFR', '', 'C\’est juste.', 28153),
(156218, 'frFR', 'Et, bien que votre peuple soit connu pour son… indépendance d\’esprit, nul ne peut contester sa loyauté et sa détermination.', '', 28153),
(156217, 'frFR', 'Votre œuvre au conseil des Trois marteaux a permis le maintien de l\’ordre et de la stabilité à Forgefer.', '', 28153),
(156216, 'frFR', '', 'Roi Wrynn, tout le plaisir est pour moi.', 28153),
(156215, 'frFR', 'Je suis heureux de vous revoir, reine régente Thaurissan.', '', 28153),
(156214, 'frFR', 'Hé ! Je travaille, moi.', '', 28153),
(156213, 'frFR', '', 'Merci. Nous devons tout faire pour préserver ce qu\’il reste des fermes de Drustvar.', 28153),
(156212, 'frFR', '', 'Un fermier se plaint d\’avoir perdu ses cochons au plus profond des bois. Sauvez-les avant que les spores les affectent !', 28153),
(156211, 'frFR', '', 'Les sorcières sont démasquées et mon peuple à nouveau en sécurité. Merci.', 28153),
(156210, 'frFR', '', 'Le Sabbat tente d\’infiltrer la Ferté-d\’Arom. Levez-le voile sur sa traîtrise et détruisez toute trace de corruption avant qu\’il n\’ait le temps d\’agir.', 28153),
(156209, 'frFR', '<Donner la poudre coagulante : |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Donner la poudre coagulante : |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'frFR', '<Donner le parchemin tortollan ancien : |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Donner le parchemin tortollan ancien : |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'frFR', '<Donner la lie d\’oursin : |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Donner la lie d\’oursin : |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'frFR', '<Donner les épices astringentes : |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Donner les épices astringentes : |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'frFR', 'Préparez-vous, $n. Je vous dirai quoi faire dès qu\’il me faudra d\’autres ingrédients.', '', 28153),
(156204, 'frFR', 'Ça nous dépasse tous, mon ami. Il est aux mains du Loa des morts !', '', 28153),
(156203, 'frFR', 'Hum… Je crains que… ce soit légèrement au-delà de mes compétences.', '', 28153),
(156202, 'frFR', 'Jamil Abul\’housin tremble de peur !', '', 28153),
(156201, 'frFR', '… Jemal ?', '', 28153),
(156200, 'frFR', 'D\’une seconde à l\’autre.', '', 28153),
(156199, 'frFR', 'Voilà… Le roi devrait se réveiller maintenant.', '', 28153),
(156198, 'frFR', 'Je n\’arrive pas à arrêter l\’hémorragie. $n, apportez-moi vite la poudre coagulante !', '', 28153),
(156196, 'frFR', 'Le chant de Jamil Abul\’housin se fait plus sonore, et plus désespéré.', '', 28153),
(156195, 'frFR', 'C\’est prêt ! Je vais administrer la potion.', '', 28153),
(156194, 'frFR', 'Jamil Abul\’housin commence à entonner une prière à voix basse.', '', 28153),
(156193, 'frFR', 'Ah oui, TROIS pincées.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'frFR', 'La dernière fois que je l\’ai préparée, c\’était il y a sept cents ans. J\’aimerais bien vous voir vous souvenir d\’une chose plus vieille que vos ancêtres.', '', 28153),
(156191, 'frFR', 'Vous avez oublié la recette ?', '', 28153),
(156190, 'frFR', 'Était-ce une ou deux pincées ? … $n, apportez-moi mon parchemin.', '', 28153),
(156188, 'frFR', 'Merci. Je prépare le mélange aussi vite que possible. Un peu de patience.', '', 28153),
(156187, 'frFR', 'Rien ? Jol, vous avez intérêt à vous dépêcher avec ce médicament…', '', 28153),
(156186, 'frFR', 'Et maintenant la saumure. Dans le garde-manger.', '', 28153),
(156185, 'frFR', 'Ne laissez pas les croggs s\’échapper !', 'Ne laissez pas les croggs s\’échapper !', 28153),
(156184, 'frFR', 'Je suis prêt, Jol.', 'Je suis prête, Jol.', 28153),
(156183, 'frFR', 'Ces ingrédients sont délicats et en tant que tels, ils nécessitent toute mon attention. Suivez attentivement mes instructions pour concocter cette mixture. N\’oubliez pas que la vie du roi est en jeu.\n\nPouvons-nous commencer ?', '', 28153),
(156182, 'frFR', '', 'Si ce qui s\’est dit est vrai, vous devez enquêter. Mais attention, Jakra\’zet est peut-être encore dans le coin.', 28153),
(156181, 'frFR', 'Eh bien, moi qui pensais que tout cela ne vous importait guère ! Voyons, par où commencer ?\n\nNous effectuons ce pèlerinage en Nazmir toutes les quelques années. Parfois, cinq printemps s\’écoulent. D\’autres fois, c\’est plus proche de vingt. En fait, tout dépend de Torga et de ses histoires.\n\nLorsqu\’il se murmure que Torga a des récits à nous confier, nous nous mettons en route. Nous venons nous asseoir ici et nous n\’en perdons pas une miette. Ensuite, nous partageons ces histoires avec tous ceux qui croisent notre route.\n\nVous avez beaucoup de chance, vous savez. Il est rare de voir un rassemblement de cette ampleur. C\’est là un récit à part entière, même si j\’ignore s\’il passionnerait vraiment vos amis, $R.', '', 28153),
(156180, 'frFR', 'Il faudra me… passer sur le corps…', 'Il faudra me… passer sur le corps…', 28153),
(156179, 'frFR', 'Parlez-moi de votre pèlerinage.', 'Parlez-moi de votre pèlerinage.', 28153),
(156178, 'frFR', 'Je ne laisserai personne s\’échapper !', 'Je ne laisserai personne s\’échapper !', 28153),
(156177, 'frFR', 'Disons que nous sommes ex æquo.', '', 28153),
(156176, 'frFR', 'Une nouvelle poudre à canon, comme je n\’en ai jamais vu.', '', 28153),
(156175, 'frFR', 'Boralus m\’appartient.', '', 28153),
(156174, 'frFR', 'Que se passe-t-il ?', 'Que se passe-t-il ?', 28153),
(156173, 'frFR', '', 'Pour la Horde !', 28153),
(156172, 'frFR', '', 'Parfait ! À présent, emmenez-nous au-delà des explosifs, après le pont.', 28153),
(156171, 'frFR', '', 'Du nerf ! Réunissez tous les gardes de la ville… sans oublier leur chef !', 28153),
(156170, 'frFR', '', 'Venez nous chercher, bande de lâches !', 28153),
(156169, 'frFR', '', 'La Horde va vous tailler en pièces !', 28153),
(156168, 'frFR', '', 'Kultirassiens ! Votre traité avec l\’Alliance signe votre arrêt de mort !', 28153),
(156167, 'frFR', '', 'Allez en ville et rassemblez autant de gardes que possible !', 28153),
(156166, 'frFR', '', 'Flynn ! Par ici !', 28153),
(156165, 'frFR', 'Comment ai-je pu échouer ?', 'Comment ai-je pu échouer ?', 28153),
(156164, 'frFR', '', 'Allons-y. Éliminez le capitaine et les Voiles-de-Brume resteront des hommes et des femmes libres !', 28153),
(156163, 'frFR', '', 'Après toutes ces années, vous cherchez ENCORE à m\’agacer ? Certaines choses ne changent jamais…', 28153),
(156162, 'frFR', '', 'C\’est drôle… je n\’avais jamais remarqué que j\’avais perdu mon accent kultirassien.', 28153),
(156161, 'frFR', '', 'Bien sûr que j\’ai mon bâton à tête de mouton. Qui a déposé le terme « mérinomancien », à votre avis ?', 28153),
(156160, 'frFR', 'Chapardons quelques armes avant de partir.', 'Chapardons quelques armes avant de partir.', 28153),
(156159, 'frFR', 'Le trafic d\’êtres vivants… ça devrait pas exister.', 'Le trafic d\’êtres vivants… ça devrait pas exister.', 28153),
(156158, 'frFR', 'Mélange', 'Mélange', 28153),
(156157, 'frFR', 'Nous autres Vulpérins, on a fini de se laisser faire !', 'Nous autres Vulpérins, on a fini de se laisser faire !', 28153),
(156156, 'frFR', 'Ils n\’ont pas fini d\’entendre parler de nous !', '', 28153),
(156155, 'frFR', 'Je ne veux plus jamais revoir de Sephrak.', 'Je ne veux plus jamais revoir de Sephrak.', 28153),
(156154, 'frFR', 'C\’est pour ça qu\’il ne faut pas embêter les tortues !', '', 28153),
(156153, 'frFR', 'Je crois bien qu\’ils comptaient me manger !', 'Je crois bien qu\’ils comptaient me manger !', 28153),
(156152, 'frFR', 'Nom d\’un sablier, heureusement que vous étiez là !', 'Nom d\’un sablier, heureusement que vous étiez là !', 28153),
(156151, 'frFR', '', 'Après toutes ces années, vous cherchez ENCORE à m\’agacer ? Certaines choses ne changent jamais…', 28153),
(156150, 'frFR', '', 'Le véritable combat nous attend.', 28153),
(156149, 'frFR', '', 'Je ferai de mon mieux.', 28153),
(156148, 'frFR', '', 'La route qui nous attend sera difficile.', 28153),
(156147, 'frFR', 'C\’est plus douloureux que ce que je croyais.', 'C\’est plus douloureux que ce que je croyais.', 28153),
(156146, 'frFR', 'Je leur ai pris une partie de leurs cristaux… C\’est moi qui rirai le dernier ! Ha !', '', 28153),
(156145, 'frFR', 'Cette carapace n\’est pas à vendre !', '', 28153),
(156144, 'frFR', 'Aucun de ces Sephraks n\’avait les moyens de m\’acheter, de toute façon.', '', 28153),
(156143, 'frFR', 'Les infidèles n\’ont aucun respect pour leurs aînés et la sagesse des anciens.', '', 28153),
(156142, 'frFR', 'Je vais crier cette histoire sur tous les toits de Zuldazar !', '', 28153),
(156141, 'frFR', '', 'Nous ne pouvons pas laisser ce monde succomber aux ténèbres.', 28153),
(156140, 'frFR', 'La chance a fini par tourner !', '', 28153),
(156139, 'frFR', 'Le chef de guerre a ordonné d\’éliminer toute présence de l\’Alliance dans la région. Occupez-vous-en. Et vite !', '', 28153),
(156138, 'frFR', '', 'Le temps des rêves est révolu.', 28153),
(156137, 'frFR', 'Ces idiots de l\’Alliance se sont postés près d\’ici. Rendez-leur une petite visite… et montrez-leur que leurs ambitions sont vaines.', '', 28153),
(156136, 'frFR', 'L\’Alliance prépare quelque chose, près de votre position. Assurez-vous que ses plans tombent à l\’eau.', '', 28153),
(156135, 'frFR', '', 'Que peut faire la fille du vent salé pour vous aider ?', 28153),
(156134, 'frFR', 'L\’Alliance vacille face à nous ! La Dame noire en sera ravie.', '', 28153),
(156133, 'frFR', 'Impitoyable ! J\’aime ça. L\’Alliance a pu goûter à notre courroux dans toute sa splendeur.', '', 28153),
(156132, 'frFR', 'Ouvrez le feu !', '', 28153),
(156131, 'frFR', 'Pathétiques… Ils y penseront à deux fois avant d\’interférer à nouveau dans nos plans.', '', 28153),
(156130, 'frFR', '', 'Une longue route nous attend.', 28153),
(156129, 'frFR', 'Retenez votre souffle, $p !', '', 28153),
(156128, 'frFR', '', 'L\’Alliance survivra.', 28153),
(156127, 'frFR', '', 'Je sais ce qui doit être fait.', 28153),
(156126, 'frFR', '', 'La moindre étincelle peut embraser le monde.', 28153),
(156125, 'frFR', '', 'Contrôlez votre pouvoir… ou c\’est lui qui vous contrôlera.', 28153),
(156124, 'frFR', 'Pour Lordaeron.', 'Pour Lordaeron.', 28153),
(156123, 'frFR', '', 'Je n\’oublierai rien.', 28153),
(156122, 'frFR', '', 'Nous traînons tous nos fantômes.', 28153),
(156121, 'frFR', 'Enfin un peu d\’action !', 'Enfin un peu d\’action !', 28153),
(156120, 'frFR', '', 'Ne faites pas confiance à n\’importe qui.', 28153),
(156119, 'frFR', 'Mon âme est assoiffée.', 'Mon âme est assoiffée.', 28153),
(156118, 'frFR', 'C\’est l\’heure de saigner !', 'C\’est l\’heure de saigner !', 28153),
(156117, 'frFR', 'J\’apprécie les éliminations efficaces, surtout celles qui favorisent notre effort de guerre.', '', 28153),
(156116, 'frFR', 'Classique… Encore un ennemi qui affronte la puissance de la Horde… en vain.', '', 28153),
(156115, 'frFR', 'La Dame noire a le don pour choisir ses champions.', '', 28153),
(156114, 'frFR', 'Un travail parfaitement exécuté… même si vous n\’avez pas fait dans la dentelle. Vous pouvez retourner à vos tâches.', '', 28153),
(156113, 'frFR', 'Ah… Quel délice de découper un adversaire en petits morceaux. Il n\’est pas interdit de mélanger devoir et plaisir !', '', 28153),
(156112, 'frFR', 'Beau travail. Nos opérations vont se poursuivre comme prévu.', '', 28153),
(156111, 'frFR', 'La Horde s\’emparera bientôt de cette zone, mais un ennemi puissant nous barre la route. Faites place pour nos troupes.', '', 28153),
(156110, 'frFR', 'Les projets du chef de guerre dans la région ne s\’accommodent pas de ce… monstre. Éliminez-le !', '', 28153),
(156109, 'frFR', '', 'Vous ne vous êtes jamais dit que VOTRE ligne du temps est l\’histoire alternative et que la MIENNE est la VRAIE ? Eh… vous n\’y aviez pas pensé, pas vrai ?', 28153),
(156108, 'frFR', 'Vous n\’êtes pas loin d\’un ennemi plus puissant que les autres. Apportez-nous un cadavre à étudier.', '', 28153),
(156107, 'frFR', 'Un ennemi proche ne fait qu\’une bouchée de nos recrues les plus fraîches. Mais une personne aussi chevronnée que vous ne peut que faire mieux.', '', 28153),
(156106, 'frFR', '', 'Vous avez combattu la Légion… mais vous n\’avez pas pensé à faire appel à nous ? Sérieusement ? Le sort de l\’univers entier était en jeu, mais vous n\’avez pas voulu vous embêter à… bah, peu importe !', 28153),
(156105, 'frFR', 'Des rapports indiquent qu\’un puissant ennemi se trouve non loin de votre position. Éliminez-le… et prenez-y du plaisir !', '', 28153),
(156104, 'frFR', 'Le chef de guerre exige que vous éliminiez une cible, dans cette zone. Ne la décevez pas.', '', 28153),
(156103, 'frFR', '', 'Depuis que je suis arrivée en ville, les Orcs d\’Orgrimmar me semblent plus grands.', 28153),
(156102, 'frFR', '', 'Un Orc vert m\’a dit qu\’il adorait mes yeux bleu ausTHRALL… Je lui ai explosé la colonne vertébrale.', 28153),
(156101, 'frFR', 'Je commençais à avoir faim…', 'Je commençais à avoir faim…', 28153),
(156100, 'frFR', '', 'Parlez vite. Nous avons des batailles à gagner !', 28153),
(156099, 'frFR', '', 'Le cœur des Mag\’har est pur et fort.', 28153),
(156098, 'frFR', '', 'Nous sommes là pour gagner la guerre.', 28153),
(156097, 'frFR', '', 'J\’entendrai vos paroles… mais je jugerai vos actes.', 28153),
(156096, 'frFR', '', 'Je n\’ose imaginer quelles auraient été les conséquences si ce rituel avait abouti. Merci pour votre aide.', 28153),
(156095, 'frFR', '', 'Parlez.', 28153),
(156094, 'frFR', '', 'Je contemplerai à nouveau le ciel de Draenor.', 28153),
(156093, 'frFR', '', 'La guerre est notre quotidien.', 28153),
(156092, 'frFR', '', 'Que vos ennemis rampent devant vous.', 28153),
(156091, 'frFR', '', 'Les sorcières de Corlain tentent d\’accomplir un rituel d\’un nouveau genre. Arrêtez-les avant qu\’il ne soit trop tard !', 28153),
(156090, 'frFR', '', 'Combattez avec honneur. Mourez dans la gloire !', 28153),
(156089, 'frFR', '', 'Les Mag\’har obtiendront la victoire.', 28153),
(156088, 'frFR', '', 'Mourez vaillamment.', 28153),
(156087, 'frFR', '', 'Allez dans l\’honneur.', 28153),
(156086, 'frFR', '', 'Throm-ka !', 28153),
(156085, 'frFR', '', 'Lok-tar !', 28153),
(156084, 'frFR', 'Pauvres oiseaux… Puissent leurs esprits voler pour l\’éternité.', '', 28153),
(156083, 'frFR', 'Les sorcières ont maudit les éperviers de la région. J\’aurais aimé pouvoir les sauver, mais il est trop tard. Servez-vous de ces oignons pour les abattre.', '', 28153),
(156082, 'frFR', '', 'Beau travail. Quand l\’Alliance se rendra-t-elle compte que rien ne peut arrêter les Zandalari ?', 28153),
(156081, 'frFR', '', 'Vous avez bien travaillé. L\’Alliance craindra bientôt la puissance des Zandalari.', 28153),
(156080, 'frFR', '', 'L\’Alliance se rendra vite compte que les Zandalari ne seront pas conquis.', 28153),
(156079, 'frFR', '', 'On m\’a informée que l\’Alliance regroupe des troupes près d\’ici. Mettez un terme à leur plan, quel qu\’il soit.', 28153),
(156078, 'frFR', '', 'L\’Alliance croit qu\’elle peut défier l\’empire zandalari. Montrez-lui qu\’elle a tort.', 28153),
(156077, 'frFR', '', 'Allez, les gars ! L\’heure de la mutinerie a sonné ! Les Voiles-de-Brume ne laisseront pas vendre leur liberté !', 28153),
(156076, 'frFR', '', 'Comment ça, toute l\’étiquette induite par mon statut de reine est ridicule… Bien sûr que vous devez continuer de m\’appeler « votre altesse » !', 28153),
(156075, 'frFR', '', 'L\’Alliance prépare quelque chose, pas loin. Éliminez ces vauriens. Ils craindront l\’empire zandalari.', 28153),
(156074, 'frFR', 'Nous pouvons nous reposer un peu, maintenant que ce problème est réglé.', '', 28153),
(156073, 'frFR', 'Les soldats de l\’Alliance n\’oublieront pas vos exploits du jour.', '', 28153),
(156072, 'frFR', 'Bien joué. Il faudra que je vous raconte des anecdotes de la Troisième guerre. Tout cela m\’y fait penser.', '', 28153),
(156071, 'frFR', 'Beau travail. Ces ressources nous aideront sur le long terme.', '', 28153),
(156070, 'frFR', 'Cette zone donne du fil à retordre à nos troupes. Ça me rappelle la Deuxième guerre. Vous pouvez nous aider ?', '', 28153),
(156069, 'frFR', 'Nous avons quelques problèmes à régler dans le coin. Vous pouvez vous en charger ?', '', 28153),
(156068, 'frFR', '', 'Évidemment que j\’ai une relation compliquée avec mon père. C\’est toujours difficile de s\’entendre avec ses parents, alors imaginez quand ils sont faits de diamant !', 28153),
(156067, 'frFR', 'Une zone proche de votre position pourrait nous être utile. Nous devons la sécuriser.', '', 28153),
(156066, 'frFR', 'Nous avons été informés de la présence de ressources vitales non loin. Elles nous aideront à faire pencher la balance. Récupérez-les.', '', 28153),
(156065, 'frFR', '', 'Allez-y… faites votre blague sur les personnes de petite taille. On verra comment vous vous en sortez sans vos rotules !', 28153),
(156064, 'frFR', 'Hé, ne venez pas casser mon tempo.', '', 28153),
(156063, 'frFR', 'Qu\’est-ce que vous faites ici ?', 'Qu\’est-ce que vous faites ici ?', 28153),
(156062, 'frFR', '', 'Kiro et moi, on ne fait que passer. Prochaine étape : l\’empire infidèle.\n\nMon plan est fin prêt.\n\nCes Sephraks ne verront rien venir.', 28153),
(156061, 'frFR', '', 'Comme on se retrouve.', 28153),
(156060, 'frFR', 'Vous honorez les soldats de la 7e Légion tombés au combat. Nous tirerons bientôt parti de cette conquête.', '', 28153),
(156059, 'frFR', 'Bien joué. Mes soldats se chargeront de la suite.', '', 28153),
(156058, 'frFR', '', 'Mon peuple vit dans un volcan. Continuez et vous verrez que la colère d\’une Sombrefer monte comme la lave !', 28153),
(156057, 'frFR', 'Une excellente mise en œuvre. Nous pourrons bientôt mettre cette zone à profit.', '', 28153),
(156056, 'frFR', 'Joli travail. Ces ressources alimenteront la 7e Légion pour une bonne durée.', '', 28153),
(156055, 'frFR', 'Nous avons besoin de votre aide pour sécuriser cette zone. Mes troupes seules en sont incapables.', '', 28153),
(156054, 'frFR', 'Plusieurs de mes soldats sont tombés en tentant de s\’emparer de la zone. Éliminez la menace présente.', '', 28153),
(156053, 'frFR', 'Les éclaireurs de la 7e Légion ont signalé que cette zone est d\’une extrême importance. Sécurisez-la, nous devons l\’exploiter.', '', 28153),
(156052, 'frFR', '', 'Les Trois marteaux ne font qu\’un.', 28153),
(156051, 'frFR', 'La 7e Légion a besoin des ressources des environs. Emparez-vous-en par tous les moyens nécessaires.', '', 28153),
(156050, 'frFR', '', 'Que votre marteau frappe juste.', 28153),
(156049, 'frFR', '', 'Que l\’Enclume noire veille sur vous.', 28153),
(156048, 'frFR', '', 'Les Sombrefer regagneront la place qui leur revient de droit dans ce monde.', 28153),
(156047, 'frFR', '', 'Partez, maintenant. J\’ai à faire !', 28153),
(156046, 'frFR', '', 'Je vous autorise à partir.', 28153),
(156045, 'frFR', '', 'Je vous donne la permission de partir.', 28153),
(156044, 'frFR', 'Bombardez ma cible !', 'Bombardez ma cible !', 28153),
(156043, 'frFR', 'Canons ! Feu !', 'Canons ! Feu !', 28153),
(156042, 'frFR', 'Cible marquée pour destruction !', 'Cible marquée pour destruction !', 28153),
(156041, 'frFR', 'Artillerie ! Feu sur ma cible !', 'Artillerie ! Feu sur ma cible !', 28153),
(156040, 'frFR', '', 'Venons-en au fait.', 28153),
(156039, 'frFR', '', 'Eh bien ? J\’écoute.', 28153),
(156038, 'frFR', '', 'Surveillez vos manières en présence d\’une reine.', 28153),
(156037, 'frFR', 'Ravi de voir que le désert n\’a pas encore eu raison de vous.', '', 28153),
(156036, 'frFR', '', 'La montagne nous donne sa force.', 28153),
(156035, 'frFR', '', 'Vous vous adressez à la reine régente du clan sombrefer.', 28153),
(156034, 'frFR', '', 'Le clan Sombrefer obtiendra le respect qui lui est dû.', 28153),
(156033, 'frFR', '', 'L\’Alliance a grand besoin de notre sorcellerie et de notre force.', 28153),
(156032, 'frFR', 'Habillage', 'Habillage', 28153),
(156031, 'frFR', 'Nettoyage', 'Nettoyage', 28153),
(156030, 'frFR', '', 'Excellent. Ces ressources aideront beaucoup les Zandalari.', 28153),
(156029, 'frFR', '', 'Un succès impressionnant. Bientôt, personne n\’osera plus affronter l\’empire zandalari.', 28153),
(156028, 'frFR', '', 'Une nouvelle victoire pour vous et pour la Horde. Je ne vois pas comment me passer de vos services.', 28153),
(156027, 'frFR', '', 'Les Zandalari vous remercient de vos efforts.', 28153),
(156026, 'frFR', '', 'Nathanos nous croit incapable de nous emparer de cette zone. Prouvez-lui qu\’il a tort.', 28153),
(156025, 'frFR', '', 'Cette zone doit être sécurisée pour le bien de notre campagne. Faites ce que vous savez faire de mieux.', 28153),
(156024, 'frFR', '', 'Nous devons sécuriser cette zone pour nos alliés. Ne montrez aucune pitié à ceux qui voudraient vous arrêter.', 28153),
(156023, 'frFR', '', 'Certaines ressources de la région seront utiles pour notre campagne. Récupérez-les pour nous.', 28153),
(156022, 'frFR', 'Dingo et Dolly vont engloutir ça en un rien de temps.', '', 28153),
(156021, 'frFR', 'Dingo et Dolly sont des bêtes capricieuses. Ils ne travailleront pas l\’estomac vide. Trouvez de quoi satisfaire leur faim.', '', 28153),
(156020, 'frFR', 'Ouste !', 'Ouste !', 28153),
(156019, 'frFR', 'Vous partir !', 'Vous partir !', 28153),
(156018, 'frFR', 'Pas toucher !', 'Pas toucher !', 28153),
(156017, 'frFR', 'Vous pas approcher ou moi fracasser tête avec pierre !', 'Vous pas approcher ou moi fracasser tête avec pierre !', 28153),
(156016, 'frFR', 'Vous partir ou moi tuer vous !', 'Vous partir ou moi tuer vous !', 28153),
(156015, 'frFR', '', 'Allez. Rassemblez ce qu\’il faut pour soigner cet homme-serpent. Je vais tout raconter à Julwaba.', 28153),
(156014, 'frFR', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNouvelle construction disponible !', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|aNouvelle construction disponible !', 28153),
(156013, 'frFR', 'J\’ai servi de nombreux chefs de guerre. Parcourez le monde, je suis sûr que vous en croiserez un ou deux.', '', 28153),
(156012, 'frFR', 'Pourquoi continuez-vous de m\’importuner ? Y a-t-il une autre guerre à mener ? Que dis-je… il y a TOUJOURS une autre guerre à mener.', '', 28153),
(156011, 'frFR', 'Si vous saviez combien de sang a versé cette hache, vous auriez moins envie de me harceler !', '', 28153),
(156010, 'frFR', 'Je suis trop vieux pour ces bêtises.', '', 28153),
(156009, 'frFR', 'Je sers la Horde !', '', 28153),
(156008, 'frFR', 'Parlez vite… et parlez vrai.', '', 28153),
(156007, 'frFR', 'L\’heure n\’est pas aux politesses.', '', 28153),
(156006, 'frFR', 'Que voulez-vous ?', '', 28153),
(156005, 'frFR', 'Throm-ka !', '', 28153),
(156004, 'frFR', 'Lok-tar !', '', 28153),
(156003, 'frFR', 'Je suis Saurcroc, frère de Broxigar.', '', 28153),
(156002, 'frFR', 'La Horde survivra.', '', 28153),
(156001, 'frFR', 'Moi plus aimer ça. Moi fuir !', 'Moi plus aimer ça. Moi fuir !', 28153),
(156000, 'frFR', 'Au combat, la tactique est aussi importante que la force.', '', 28153),
(155999, 'frFR', 'Hourra ! Moi libre !', 'Hourra ! Moi libre !', 28153),
(155998, 'frFR', 'Moi me tailler fissa !', 'Moi me tailler fissa !', 28153),
(155997, 'frFR', 'Nous sommes la véritable puissance de Kalimdor.', '', 28153),
(155996, 'frFR', 'Pourquoi qu\’ils font ça ?', 'Pourquoi qu\’ils font ça ?', 28153),
(155995, 'frFR', 'Moi pas mourir ! Vous couvrir moi !', 'Moi pas mourir ! Vous couvrir moi !', 28153),
(155994, 'frFR', 'Quoi qui se passe ?!', 'Quoi qui se passe ?!', 28153),
(155993, 'frFR', 'Vous faire gaffe, barjots d\’Humains partout !', 'Vous faire gaffe, barjots d\’Humains partout !', 28153),
(155992, 'frFR', 'Ne faites pas de vieux os, si vous pouvez l\’éviter.', '', 28153),
(155991, 'frFR', 'Sans honneur, nous ne sommes rien.', '', 28153),
(155990, 'frFR', 'Mourir aujourd\’hui sur le champ de bataille. C\’est ça, une mort d\’Orc.', '', 28153),
(155989, 'frFR', 'Puissiez-vous mourir face à un grand ennemi.', '', 28153),
(155988, 'frFR', 'Conduisez Loh en sécurité dans le varech.', '', 28153),
(155987, 'frFR', '« Loh et la mer », l\’histoire d\’un jeune Tortollan qui doit quitter les sables pour gagner le refuge offert par les eaux.', '', 28153),
(155986, 'frFR', '', 'Les troupes des sorcières en déroute, nos hommes vont pouvoir reprendre le travail. Merci de les avoir secourus.', 28153),
(155985, 'frFR', 'Je vais juste m\’essuyer là-dessus…', '', 28153),
(155984, 'frFR', '', 'Les serviteurs des sorcières tentent de prendre le contrôle de nos exploitations forestières. Ralliez les bûcherons et réduisez les intrus en cendres !', 28153),
(155983, 'frFR', '', 'Val-Archer est une nouvelle fois libre de l\’influence du Sabbat. Merci.', 28153),
(155982, 'frFR', '', 'Les troupes du Sabbat s\’en prennent à Val-Archer ! Libérez les habitants et reprenez la ville !', 28153),
(155981, 'frFR', 'Psst… Par ici, $n !', '', 28153),
(155980, 'frFR', '', 'Nous devons nous battre pour ce qui est juste.', 28153),
(155979, 'frFR', '', 'Quand l\’heure sera venue, je serai là.', 28153),
(155978, 'frFR', '', 'Exécution.', 28153),
(155977, 'frFR', '', 'Nous devons aider ceux qui ne peuvent s\’aider eux-même.', 28153),
(155976, 'frFR', '', 'Sans honneur, nous ne sommes rien.', 28153),
(155975, 'frFR', '', 'Si vous racontez ça à qui que ce soit, je vous jette en pâture à mon griffon, c\’est compris ?', 28153),
(155974, 'frFR', '', 'Je combattrai jusqu\’à la fin.', 28153),
(155973, 'frFR', '', 'Oups… Euh ! Oh non, vous n\’avez rien entendu.', 28153),
(155972, 'frFR', '', 'Je suis… une écuyère… à la discipline d\’acier… et à la volonté de fer…', 28153),
(155971, 'frFR', '', 'Mais ça chatouille ! Arrêtez, j\’vous dis !', 28153),
(155970, 'frFR', '', 'Hé ! Arrêtez ça !', 28153),
(155969, 'frFR', '', 'Nous atteindrons notre but.', 28153),
(155968, 'frFR', '', 'Servez avec honneur.', 28153),
(155967, 'frFR', '', 'Gardez le cap.', 28153),
(155966, 'frFR', '', 'Que les vents vous poussent, mes amis. Je dois combattre ici, aux côtés des Vulpérins.', 28153),
(155965, 'frFR', '', 'Revenez me raconter d\’autres histoires !', 28153),
(155964, 'frFR', '', 'Pour Kul Tiras !', 28153),
(155963, 'frFR', '', 'Le devoir nous appelle.', 28153),
(155962, 'frFR', '', 'Au revoir.', 28153),
(155961, 'frFR', '', 'Quelle est la situation ?', 28153),
(155960, 'frFR', '', 'Enfin un peu d\’action !', 28153),
(155959, 'frFR', '', 'Je me suis entraînée toute ma vie pour ça.', 28153),
(155956, 'frFR', '', 'Ensemble, nous pouvons unifier Kul Tiras.', 28153),
(155955, 'frFR', '', 'J\’ai toujours rêvé d\’aventure.', 28153),
(155953, 'frFR', 'La vallée est mon foyer.', '', 28153),
(155952, 'frFR', 'Je couvrirai vos arrières si vous couvrez les miens.', '', 28153),
(155950, 'frFR', 'Prenez soin de vous.', '', 28153),
(155947, 'frFR', 'Nous sommes dans le même bateau.', '', 28153),
(155946, 'frFR', '', 'Mise à jour. Explosion de réorigination proche de sa puissance maximale.', 28153),
(155945, 'frFR', '', 'Attention. Puissance maximale d\’Explosion de réorigination bientôt atteinte.', 28153),
(155944, 'frFR', '', 'Attention. Puissance maximale imminente.', 28153),
(155943, 'frFR', '', 'Mise à jour. Puissance proche du maximum.', 28153),
(155942, 'frFR', 'Une bonne journée de travail vient à bout de tous les problèmes.', '', 28153),
(155941, 'frFR', 'Mon cœur appartient à cette vallée.', '', 28153),
(155939, 'frFR', '', 'Je peux vous aider ?', 28153),
(155938, 'frFR', 'Entendez-vous ça ? Les abysses me murmurent quelque chose. C\’est… c\’est à votre sujet ! Comment ? Hum hum. Je vois. Ils disent : « Arrêtez de cliquer sur Pike, espèce de monstre. » Étonnant, non ?', '', 28153),
(155937, 'frFR', 'Ils servent à bien des choses !$b$bEt pas seulement à faire des trous ! Les piquants ont de nombreuses propriétés très utiles. Broyés en poudre, ils constituent un agent liant très efficace. Vous pouvez également les faire bouillir et utiliser leurs huiles comme détergent, sans oublier qu\’ils font de très bons cure-dents quand vous n\’avez rien d\’autre sous la main !', '', 28153),
(155936, 'frFR', 'Je vais devoir vous tuer de mes mains, vous et vos crétins d\’amis !', '', 28153),
(155935, 'frFR', 'Tongo… tué par une pièce rapportée ? Faut croire que je l\’ai surestimé !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'frFR', 'Pas comme ça… non… aaaargh…', '', 28153),
(155933, 'frFR', 'J\’ai fait le vœu de maintenir la paix sur ces terres. Mais pour vous, je ferai une exception.', '', 28153),
(155932, 'frFR', 'Harcelez-moi autant que vous le voulez. La patience des eaugures est légendaire.', '', 28153),
(155931, 'frFR', '', 'Bien le bonjour !', 28153),
(155930, 'frFR', 'À quoi vous servent ces piquants ?', 'À quoi vous servent ces piquants ?', 28153),
(155929, 'frFR', 'Offrande', 'Offrande', 28153),
(155928, 'frFR', 'Je crois que je commence à comprendre. Vous avez bu ! Et vous n\’avez même pas partagé ! je n\’apprécie pas.', '', 28153),
(155927, 'frFR', 'Tout doux, matelot. Je sais que je suis canon, mais on a du pain sur la planche.', '', 28153),
(155926, 'frFR', 'Enfin, sauf si vous avez été enrôlé de force dans la marine… Ou capturé par des pirates… et ensuite re-capturé par la marine…', '', 28153),
(155925, 'frFR', 'Ah, le grand large, un chant de marins aux lèvres, la brise qui joue dans les poils de votre torse. Voilà la liberté.', '', 28153),
(155924, 'frFR', 'Les regrets, ça ne sert à rien.', '', 28153),
(155923, 'frFR', 'Fixez l\’horizon.', '', 28153),
(155922, 'frFR', 'La prochaine est pour moi.', '', 28153),
(155921, 'frFR', 'À nous le pactole.', '', 28153),
(155920, 'frFR', 'À bientôt.', '', 28153),
(155919, 'frFR', '<Le roi Rastakhan a le souffle court et respire à grand-peine. Les bandages autour de son torse sont trempés de sang.>', '', 28153),
(155918, 'frFR', 'Protégez vos arrières.', '', 28153),
(155917, 'frFR', 'Bon pied, bon œil et poudre sèche.', '', 28153),
(155916, 'frFR', 'Racontez-moi tout.', '', 28153),
(155915, 'frFR', 'Excellent ! Je vais commencer le brassage de ce pas. Je suis certain que les pêcheurs locaux apprécieront que vous ayez réduit la population de mouettes.', '', 28153),
(155914, 'frFR', 'Je suis Jamil Abul\’housin, médecin personnel du roi. Ce n\’est pas la première fois que je soigne le roi, et par les Loas, ce ne sera pas la dernière !', '', 28153),
(155913, 'frFR', 'J\’ai besoin d\’ingrédients issus des crabes et poissons de la région. Malheureusement, ils font le repas des mouettes. Apportez-moi les composants, et profitez-en pour éliminer quelques volatiles !', '', 28153),
(155912, 'frFR', 'Comment va le roi ?', 'Comment va le roi ?', 28153),
(155911, 'frFR', 'Oui… oui ! Que cette terre tremble devant la puissance de la Horde !', '', 28153),
(155910, 'frFR', 'Nous avons surmonté bien des épreuves, le vieux Rastakhan et moi. Mais ça…\n\n<Jemal désigne le corps meurtri du roi.>\n\nC\’est très mauvais signe.', '', 28153),
(155909, 'frFR', '<Jol ne quitte pas ses décoctions des yeux.>\n\nLes heures du roi sont comptées.', '', 28153),
(155908, 'frFR', 'Un contrat est un contrat.', '', 28153),
(155907, 'frFR', 'C\’est parfait. Dommage que nous n\’ayons pu transformer cette menace en arme contre nos ennemis.', '', 28153),
(155906, 'frFR', 'Un ennemi puissant s\’est révélé… insurmontable pour nos troupes, près d\’ici. Je vous fais confiance pour faire ce qui doit être fait.', '', 28153),
(155905, 'frFR', 'Le chef de guerre sera enchanté de votre succès !', '', 28153),
(155904, 'frFR', 'Un ennemi dangereux rôde non loin. Éliminez-le avant qu\’il déjoue nos plans.', '', 28153),
(155903, 'frFR', 'Les troupes ennemies mettent notre plan à rude épreuve. Le chef de guerre veut que le problème soit réglé. Ne lui faites pas faux bond.', '', 28153),
(155902, 'frFR', 'Comment Rhenik a pu laisser faire ça ?', 'Comment Rhenik a pu laisser faire ça ?', 28153),
(155901, 'frFR', 'Ah non, pas encore !', 'Ah non, pas encore !', 28153),
(155900, 'frFR', 'Le coupable va le payer cher !', 'Le coupable va le payer cher !', 28153),
(155899, 'frFR', 'Pourquoi c\’est toujours le grog qui trinque ?', 'Pourquoi c\’est toujours le grog qui trinque ?', 28153),
(155898, 'frFR', 'Pas le grog !', 'Pas le grog !', 28153),
(155897, 'frFR', 'Le sang, l\’or, tout a un coût.', '', 28153),
(155896, 'frFR', 'Hmm, ça ne devait pas se passer ainsi. Vous devriez peut-être réessayer.', '', 28153),
(155895, 'frFR', 'Vous avez soif ? Parce que moi, oui.', '', 28153),
(155894, 'frFR', 'Je suis tout ouïe.', '', 28153),
(155893, 'frFR', 'Quoi de neuf ?', '', 28153),
(155892, 'frFR', 'Salut, matelot.', '', 28153),
(155891, 'frFR', 'Faites attention à vous.', '', 28153),
(155890, 'frFR', 'À la revoyure.', '', 28153),
(155889, 'frFR', 'À plus tard !', '', 28153),
(155888, 'frFR', 'Un grog ou une bière ? Ou bien les deux ?', '', 28153),
(155887, 'frFR', 'Qu\’est-ce que je vous sers ?', '', 28153),
(155886, 'frFR', 'Bien joué, $n !', '', 28153),
(155885, 'frFR', 'Qu\’est-ce que je peux vous offrir ?', '', 28153),
(155884, 'frFR', 'Pouvez-vous guider Loh jusqu\’aux sources de nourriture, puis jusqu\’à sa hutte, sans emprunter deux fois le même chemin ?', '', 28153),
(155883, 'frFR', '« Une vie simple. » Un beau jour, Loh décida de vivre une vie paisible sur une île déserte.', '', 28153),
(155882, 'frFR', 'Vous savez comment on appelait les cadets dans votre genre, lors de la Deuxième guerre ? Des bernicles… Impossible de les décoller !', '', 28153),
(155881, 'frFR', 'Au cours de ses voyages, Loh a dû affronter de grands dangers. Une fois, par exemple…', '', 28153),
(155880, 'frFR', 'Mon peuple ne se lasse jamais d\’écouter l\’histoire de Loh, un jeune Tortollan qui parcourait le monde.', '', 28153),
(155879, 'frFR', 'Qu\’est-ce que vous voulez ? Une histoire de guerre ?', '', 28153),
(155878, 'frFR', 'De mon temps, on savait quand une conversation était finie.', '', 28153),
(155877, 'frFR', '', 'Le cycle de la vie est parfois cruel…', 28153),
(155876, 'frFR', '', 'Une tortue a atteint l\’océan !', 28153),
(155875, 'frFR', '', 'Merci, $n !', 28153),
(155874, 'frFR', '', 'Les premiers instants de la vie d\’un Tortollan sont périlleux. Tout comme pour ces tortues. Protégez-les jusqu\’à ce qu\’elles rejoignent l\’océan.', 28153),
(155873, 'frFR', '', 'Beau travail ! Voilà un parfait exemple d\’utilisation détournée mais rudement efficace !', 28153),
(155872, 'frFR', '', 'Liquidez tous ceux qui ne portent pas de badge d\’identification !', 28153),
(155871, 'frFR', '', 'Qui est l\’imbécile qui a perdu plusieurs caisses de bombes ?', 28153),
(155870, 'frFR', '', 'Un groupe d\’hommes à la Ferté-d\’Arom a réussi à mettre cet engin d\’extraction en marche. Retournez-le contre la Horde !', 28153),
(155869, 'frFR', '', 'Nous allons devoir nous… séparer de vous… pour compenser les dépassements de coûts !', 28153),
(155868, 'frFR', '', 'Je vais sans doute devoir procéder à des coupes drastiques pour réduire nos dépenses.', 28153),
(155867, 'frFR', 'La fonderie est attaquée ! Je répète, la FOND...', 'La fonderie est attaquée ! Je répète, la FOND...', 28153),
(155866, 'frFR', 'Que l\’honneur vous guide.', '', 28153),
(155865, 'frFR', 'Pour l\’amiral suprême.', '', 28153),
(155864, 'frFR', 'Pour Kul Tiras.', '', 28153),
(155863, 'frFR', 'Qu\’ils ne vous voient jamais trembler !', '', 28153),
(155862, 'frFR', 'Restez alerte.', '', 28153),
(155861, 'frFR', 'Bons vents et marées.', '', 28153),
(155860, 'frFR', 'Rompez !', '', 28153),
(155859, 'frFR', '', '', 28153),
(155858, 'frFR', '', '', 28153),
(155857, 'frFR', 'Parlez !', '', 28153),
(155856, 'frFR', '', '', 28153),
(155855, 'frFR', 'J\’ai vu assez de guerres pour nous deux.', '', 28153),
(155854, 'frFR', 'Des nouvelles du front ?', '', 28153),
(155853, 'frFR', 'De quoi avez-vous besoin ?', '', 28153),
(155852, 'frFR', 'La bataille démange toujours mes vieux os.', '', 28153),
(155851, 'frFR', 'Quelque chose à signaler ?', '', 28153),
(155850, 'frFR', 'Bien le bonjour !', '', 28153),
(155849, 'frFR', '', 'Ne demandez jamais de faveurs.', 28153),
(155848, 'frFR', '', 'Par les vents et par les mers, liberté, tu nous es chère.', 28153),
(155847, 'frFR', '', 'Kul Tiras franchira toutes les tempêtes.', 28153),
(155846, 'frFR', '', 'Je vous accorde audience.', 28153),
(155845, 'frFR', '', 'Parlez, puisque je vous y invite.', 28153),
(155844, 'frFR', 'Nous devons persévérer.', '', 28153),
(155843, 'frFR', 'Ne craignez pas la marée.', '', 28153),
(155842, 'frFR', 'Que les courants vous guident.', '', 28153),
(155841, 'frFR', 'N\’oubliez pas les défunts.', '', 28153),
(155840, 'frFR', 'Gardez toujours un œil sur l\’horizon.', '', 28153),
(155839, 'frFR', '', 'Bavarder ne m\’intéresse pas.', 28153),
(155838, 'frFR', 'La tempête gronde en chacun de nous.', '', 28153),
(155837, 'frFR', 'Je suis ici pour me battre en duel.', 'Je suis ici pour me battre en duel.', 28153),
(155836, 'frFR', 'Pas tout à fait. Réessayez.', '', 28153),
(155835, 'frFR', 'Ooh, une paire !', '', 28153),
(155834, 'frFR', 'Bien joué, $n !', '', 28153),
(155833, 'frFR', 'J\’ai accumulé bien des choses au fil du temps. Voyez si vous trouvez des paires.', '', 28153),
(155832, 'frFR', 'C\’est pratique si vous aimez courir. Mais si vous préférez voler, il y a Pa\’ku, le Loa des vents. Ses totems sont plus rares, mais ils permettent de prendre des raccourcis en survolant la ville.', '', 28153),
(155831, 'frFR', '', 'Gonk, le maître de la métamorphose et seigneur de la chasse, est un puissant Loa. Il peut vous donner accès à ses nombreux totems, dans la cité, qui permettent d\’aller plus vite.', 28153),
(155830, 'frFR', 'Les abysses avaient annoncé votre venue.', '', 28153),
(155829, 'frFR', 'Je vous écoute.', '', 28153),
(155828, 'frFR', 'En quoi puis-je vous aider ?', '', 28153),
(155827, 'frFR', 'Que les marées vous bénissent.', '', 28153),
(155826, 'frFR', 'Relevez la passerelle, nous levons l\’ancre. Pas la peine d\’attendre qu\’ils fassent des trous dans ma coque.', '', 28153),
(155825, 'frFR', 'Je note qu\’ils veulent récolter l\’azérite, eux aussi. Hmm, pas bête, mais on est trop rapides pour eux. Fonçons avant d\’attirer leur attention.', '', 28153),
(155824, 'frFR', 'Le filon semble épuisé. On a pressé cette île comme un citron, et c\’est pas trop tôt. Il y a un navire zandalari à l\’horizon.', '', 28153),
(155823, 'frFR', 'Et comme par hasard, ils veulent l\’azérite aussi. Youpiii… Bon, eh bien tuez-les et pillez leurs cadavres.', '', 28153),
(155822, 'frFR', 'Des Hozen ? Ici ? Oh, on ne sait jamais ce qui peut débarquer sur ces îles.', '', 28153),
(155821, 'frFR', 'On vient de détecter un énorme gisement d\’azérite dans les parages. Ça va payer !', '', 28153),
(155820, 'frFR', 'Joli. Enfin, sanglant et répugnant, plutôt, mais que vous voulez-vous que je vous dise ? L\’azérite, c\’est l\’azérite.', '', 28153),
(155819, 'frFR', 'Oh, mais c\’est un gentil monstre ça, et tout couvert de résidu d\’azérite. Dégommez-le et on en extraira tout ça.', '', 28153),
(155818, 'frFR', 'Attention, le détecteur indique un autre gisement d\’azérite pas loin d\’où vous êtes. Allez jeter un coup d\’œil.', '', 28153),
(155817, 'frFR', 'Ouaaah ! Jolie récolte. Beau boulot !', '', 28153),
(155816, 'frFR', 'Holà, ça, c\’est un sacré morceau d\’azérite. Fractionnez ce caillou et on rapportera les éclats à bord en moins de deux.', '', 28153),
(155815, 'frFR', 'Notre détecteur d\’azérite a détecté une source, euh… d\’azérite, pas loin. Pourquoi vous n\’iriez pas voir ce qu\’il en est ? Moi, je vais rester ici.', '', 28153),
(155814, 'frFR', 'Rapportez l\’azérite et ne touchez à rien d\’autre. Et merci de remonter la passerelle derrière vous.', '', 28153),
(155813, 'frFR', 'Mais il pourrait tout aussi bien y avoir des araignées géantes, l\’un n\’empêche pas l\’autre, vous savez. Bon, je vais me taire.', '', 28153),
(155812, 'frFR', 'Je suis à peu près sûr que c\’est le bon endroit. Il est censé y avoir des tonnes d\’azérite, par ici.', '', 28153),
(155811, 'frFR', 'Louée soit la Dame noire pour votre présence ici, $n ! Rexxar a attiré quelques-uns de ces Kultirassiens dans les bâtiments que vous voyez là. Il a besoin d\’aide !', 'Louée soit la Dame noire pour votre présence ici, $n ! Rexxar a attiré quelques-uns de ces Kultirassiens dans les bâtiments que vous voyez là. Il a besoin d\’aide !', 28153),
(155810, 'frFR', 'Vite ! Descendez sur le pont-batterie et postez-vous à un canon ! Nos troupes ont besoin de nous !', '', 28153),
(155809, 'frFR', 'C\’est tout ce qu\’il reste de Vadekius, autrefois un puissant dragon.', 'C\’est tout ce qu\’il reste de Vadekius, autrefois un puissant dragon.', 28153),
(155808, 'frFR', 'N\’allez pas imaginer des choses.', 'N\’allez pas imaginer des choses.', 28153),
(155807, 'frFR', 'Seule une force aussi malveillante que surpuissante a pu en venir à bout.', 'Seule une force aussi malveillante que surpuissante a pu en venir à bout.', 28153),
(155806, 'frFR', 'C\’est tout ce qu\’il reste de Vadekius, autrefois un puissant dragon.', 'C\’est tout ce qu\’il reste de Vadekius, autrefois un puissant dragon.', 28153),
(155805, 'frFR', 'Mais c\’est un début.', 'Mais c\’est un début.', 28153),
(155804, 'frFR', 'Je suis bien moins magnanime que ma reine.', 'Je suis bien moins magnanime que ma reine.', 28153),
(155803, 'frFR', 'Je ne pardonnerai pas de sitôt ce que vous avez fait à Kyranastrasz.', 'Je ne pardonnerai pas de sitôt ce que vous avez fait à Kyranastrasz.', 28153),
(155802, 'frFR', 'J\’imagine que je dois vous remercier.', 'J\’imagine que je dois vous remercier.', 28153),
(155801, 'frFR', 'Je vous remercie pour votre aide, $n.', 'Je vous remercie pour votre aide, $n.', 28153),
(155800, 'frFR', 'Nous ne voulons pas qu\’une telle abomination se reproduise.', 'Nous ne voulons pas qu\’une telle abomination se reproduise.', 28153),
(155799, 'frFR', 'Pour trouver son lieu de repos éternel, le seigneur de la mort a envahi le sanctum Rubis.', 'Pour trouver son lieu de repos éternel, le seigneur de la mort a envahi le sanctum Rubis.', 28153),
(155798, 'frFR', 'Durant la récente guerre contre la Légion, l\’un des nôtres a été ressuscité et transformé en créature morte-vivante.', 'Durant la récente guerre contre la Légion, l\’un des nôtres a été ressuscité et transformé en créature morte-vivante.', 28153),
(155797, 'frFR', 'Dans ce cas, $n et moi allons nous atteler à cette tâche. Suivez-moi, $c, rendons-nous sur le site du rituel.', 'Dans ce cas, $n et moi allons nous atteler à cette tâche. Suivez-moi, $c, rendons-nous sur le site du rituel.', 28153),
(155796, 'frFR', '', '$n est de retour et pourra peut-être vous aider, Zallestrasza.', 28153),
(155795, 'frFR', 'Vous vous faites du mouron pour rien, je me sens beaucoup mieux.', 'Vous vous faites du mouron pour rien, je me sens beaucoup mieux.', 28153),
(155794, 'frFR', 'Je peux aider si vous restez tranquille.', 'Je peux aider si vous restez tranquille.', 28153),
(155793, 'frFR', 'Tu tiens à peine debout, Théo !', 'Tu tiens à peine debout, Théo !', 28153),
(155792, 'frFR', '', 'Beau travail, $n ! Venez donc dans mon nouveau bureau.', 28153),
(155791, 'frFR', '', 'Ces cibles étaient les miennes. Elles sont à mon compteur !', 28153),
(155790, 'frFR', 'Il va me falloir un immense pouvoir pour affronter Korphek. Il a toujours été meilleur combattant que moi.\n\nJe vais absorber un maximum d\’énergie de ces cristaux. Prions pour que cela suffise.', '', 28153),
(155789, 'frFR', '', 'Les araignées n\’étant plus un problème, nos chasseurs vont pouvoir retourner dans les bois sans crainte de se retrouver prisonniers d\’une toile.', 28153),
(155788, 'frFR', '', 'De dangereuses araignées ont envahi les bois et menacent les chasseurs de Drustvar. Réduisez-les en cendres !', 28153),
(155787, 'frFR', 'Échange', 'Échange', 28153),
(155786, 'frFR', '', 'Beau travail. Ces fournitures nous aideront à affronter le mauvais temps de la région.', 28153),
(155785, 'frFR', '', 'D\’après nos éclaireurs, ces Humains ont trouvé un moyen de collecter la fourrure de ces créatures sans les blesser. C\’est étrange… mais très efficace.', 28153),
(155784, 'frFR', 'Une créature pernicieuse rôde dans le dépôt de bois. Elle est bien trop près de Boralus à mon goût.', '', 28153),
(155783, 'frFR', 'Une élimination propre ! Les jours du monstre étaient comptés dès qu\’il est apparu sur les rivages de Kul Tiras.', '', 28153),
(155782, 'frFR', 'Les Barges ont appâté une grosse proie. Ils vont avoir besoin de votre aide.', '', 28153),
(155781, 'frFR', 'Combustion', 'Combustion', 28153),
(155780, 'frFR', 'Faut qu\’on se serre les coudes. Je baisserai pas les bras !', 'Faut qu\’on se serre les coudes. Je baisserai pas les bras !', 28153),
(155779, 'frFR', 'Si je dois mourir aujourd\’hui... ce sera l\’arme au poing !', 'Si je dois mourir aujourd\’hui... ce sera l\’arme au poing !', 28153),
(155778, 'frFR', 'Mojambo, il me prendra pas vivant !', 'Mojambo, il me prendra pas vivante !', 28153),
(155777, 'frFR', 'Jamais je ramperai devant Mojambo et sa bande !', 'Jamais je ramperai devant Mojambo et sa bande !', 28153),
(155776, 'frFR', 'Je me battrai jusqu\’à mon dernier souffle !', 'Je me battrai jusqu\’à mon dernier souffle !', 28153),
(155775, 'frFR', 'Mojambo, il va avoir affaire à nous !', 'Mojambo, il va avoir affaire à nous !', 28153),
(155774, 'frFR', 'L\’heure du combat approche. Prenez cette épée et restez sur vos gardes.', 'L\’heure du combat approche. Prenez cette épée et restez sur vos gardes.', 28153),
(155773, 'frFR', 'Nous sommes ici chez nous. Nous ne partirons pas sans combattre.', 'Nous sommes ici chez nous. Nous ne partirons pas sans combattre.', 28153),
(155772, 'frFR', '', 'Bon boulot ! C\’est une épine en moins dans le pied de la marine.', 28153),
(155771, 'frFR', '', 'Quel exploit ! J\’ai beaucoup à apprendre en vous regardant vous battre.', 28153),
(155770, 'frFR', '', 'Aujourd\’hui, vous avez rendu les routes de Kul Tiras plus sûres.', 28153),
(155769, 'frFR', '', 'Depuis quelque temps, l\’armée a affaire à une bête sauvage de la région. Réglons le problème pour elle !', 28153),
(155768, 'frFR', '', 'Une ignoble bête rôde dans les parages. Pour le bien de Kul Tiras, je vous demande de la neutraliser !', 28153),
(155767, 'frFR', '', 'On ne peut pas laisser une telle abomination continuer à terroriser des civils innocents. Éliminez-la !', 28153),
(155766, 'frFR', 'Vous avez pas autre chose à faire ?', 'Vous avez pas autre chose à faire ?', 28153),
(155765, 'frFR', 'Hé, j\’aime pas qu\’on me regarde de travers !', 'Hé, j\’aime pas qu\’on me regarde de travers !', 28153),
(155764, 'frFR', 'Vous êtes très, très loin de chez vous. Trop !', 'Vous êtes très, très loin de chez vous. Trop !', 28153),
(155763, 'frFR', 'Ciel carmin dans la nuit, les marins sont ravis. Ciel carmin du matin, les marins se méfient !', '', 28153),
(155762, 'frFR', 'Téléportez-moi jusqu\’à G\’huun.', 'Téléportez-moi jusqu\’à G\’huun.', 28153),
(155761, 'frFR', 'Téléportez-moi jusqu\’à Mythrax.', 'Téléportez-moi jusqu\’à Mythrax.', 28153),
(155760, 'frFR', 'Téléportez-moi jusqu\’à Zul.', 'Téléportez-moi jusqu\’à Zul.', 28153),
(155759, 'frFR', 'Téléportez-moi jusqu\’à l\’élémentaire de sang.', 'Téléportez-moi jusqu\’à l\’élémentaire de sang.', 28153),
(155758, 'frFR', 'Téléportez-moi jusqu\’à Zek\’voz.', 'Téléportez-moi jusqu\’à Zek\’voz.', 28153),
(155757, 'frFR', 'Téléportez-moi jusqu\’au dévoreur fétide.', 'Téléportez-moi jusqu\’au dévoreur fétide.', 28153),
(155756, 'frFR', 'Téléportez-moi jusqu\’à DAME.', 'Téléportez-moi jusqu\’à DAME.', 28153),
(155755, 'frFR', 'Salutations, et merci de participer aux tests d\’Uldir !\n\nJe peux vous téléporter auprès de tous les boss actuellement disponibles.', 'Salutations, et merci de participer aux tests d\’Uldir !\n\nJe peux vous téléporter auprès de tous les boss actuellement disponibles.', 28153),
(155754, 'frFR', '', 'Mon chat a disparu.', 28153),
(155753, 'frFR', 'Affrontez les tempêtes que vous pouvez pas éviter, évitez celles que vous pouvez pas affronter !', '', 28153),
(155752, 'frFR', 'Souvenez-vous, la partie mouillée reste en bas !', '', 28153),
(155750, 'frFR', 'Continuez comme ça et je vous envoie chez Bwonsamdi !', '', 28153),
(155749, 'frFR', 'Vivre sur terre, quelle tristesse !', '', 28153),
(155748, 'frFR', 'Chaque fois que vous verrez les flammes bleues sacrées dans la baie des Rois, vous saurez que c\’est vous qui avez endigué le raz-de-marée ! C\’est une glorieuse victoire, $n. La flotte est à Zandalar, pour toujours !', '', 28153),
(155747, 'frFR', 'J\’hésiterai pas à vous faire passer sous la quille.', '', 28153),
(155746, 'frFR', 'Que le vent gonfle vos voiles et vous guide vers votre destin !', '', 28153),
(155745, 'frFR', 'À la revoyure !', '', 28153),
(155744, 'frFR', 'Portez-vous bien ! La mer m\’appelle !', '', 28153),
(155743, 'frFR', 'Si la mer reste étale, vous apprendrez que dalle !', '', 28153),
(155742, 'frFR', 'Que le vent et la mer vous soient favorables !', '', 28153),
(155741, 'frFR', 'Que les marées nous rassemblent vite !', '', 28153),
(155740, 'frFR', 'Suivez le vent et percez l\’horizon !', '', 28153),
(155739, 'frFR', 'Vous sentez les embruns ? Ça veut dire que nous sommes chez nous.', '', 28153),
(155738, 'frFR', 'Taz\’okun ! Bienvenue, matelot !', '', 28153),
(155737, 'frFR', 'Vous avez accompli votre tâche… mais vous auriez pu le faire moins proprement. Essayez de faire mieux, la prochaine fois.', '', 28153),
(155736, 'frFR', 'Ah ! C\’est vous !', '', 28153),
(155735, 'frFR', 'Le chef de guerre ordonne que vous preniez le contrôle de cette zone au nom de la Horde. Utilisez tous les moyens nécessaires… seule importe la victoire.', '', 28153),
(155734, 'frFR', 'Un jour passé au large est un bon jour !', '', 28153),
(155733, 'frFR', '$uParé:Parée; pour un voyage inoubliable ?', '', 28153),
(155732, 'frFR', 'Je veux me rendre à Uldir (raid).', 'Je veux me rendre à Uldir (raid).', 28153),
(155731, 'frFR', 'Bien joué ! Nous voilà débarrassés de quelques ennemis et nos oiseaux vont retrouver un perchoir plus sûr.', '', 28153),
(155730, 'frFR', 'J\’attendrai votre retour avec impatience !', '', 28153),
(155729, 'frFR', 'Revenez vite !', '', 28153),
(155728, 'frFR', 'Visez !', 'Visez !', 28153),
(155727, 'frFR', 'Je vois. À croire que vous le faites exprès...', '', 28153),
(155726, 'frFR', 'Je parie que vous avez cassé quelque chose...', '', 28153),
(155725, 'frFR', 'Je peux vous aider ?', '', 28153),
(155724, 'frFR', 'Qu\’est-ce que je peux faire pour vous ?', '', 28153),
(155723, 'frFR', 'À couvert !!', 'À couvert !!', 28153),
(155722, 'frFR', 'Vous avez de la chance que je vous aime bien. Je vais réparer ça... encore une fois.', '', 28153),
(155721, 'frFR', 'Oh non, vraiment ? Ça a cassé quand vous avez entassé tout le poids sur un minuscule appui ? Ben mince alors, qui l\’eût cru ?', '', 28153),
(155720, 'frFR', 'Vous êtes pas plus intelligents que mon marteau.', '', 28153),
(155719, 'frFR', 'Je suis sûr d\’avoir déjà réparé ce truc la dernière fois.', '', 28153),
(155718, 'frFR', 'Si seulement ces abrutis pouvaient arrêter de tout casser !', '', 28153),
(155717, 'frFR', 'Je veux me rendre au manoir Malvoie (donjon).', 'Je veux me rendre au manoir Malvoie (donjon).', 28153),
(155716, 'frFR', 'Je veux me rendre à Tol Dagor (donjon).', 'Je veux me rendre à Tol Dagor (donjon).', 28153),
(155715, 'frFR', 'Je veux me rendre au siège de Boralus (donjon).', 'Je veux me rendre au siège de Boralus (donjon).', 28153),
(155714, 'frFR', 'Je veux me rendre au sanctuaire des Tempêtes (donjon).', 'Je veux me rendre à Port-Liberté (donjon).', 28153),
(155713, 'frFR', 'Je veux me rendre à Port-Liberté (donjon).', 'Je veux me rendre à Port-Liberté (donjon).', 28153),
(155712, 'frFR', 'Par les plumes de Plumeria ! Vous m\’avez fait peur !', '', 28153),
(155711, 'frFR', 'Des fauconniers ensorcelés ont volé nos oiseaux ! Libérez les éperviers et abattez les serviteurs des sorcières !', '', 28153),
(155710, 'frFR', 'Besoin d\’un truc en particulier ? Un machin ? Un bidule, peut-être ?', '', 28153),
(155709, 'frFR', 'Je veux me rendre aux tréfonds Putrides (donjon).', 'Je veux me rendre aux tréfonds Putrides (donjon).', 28153),
(155708, 'frFR', 'Je veux me rendre au Filon (donjon).', 'Je veux me rendre au Filon (donjon).', 28153),
(155707, 'frFR', 'Je veux me rendre au temple de Sephraliss (donjon).', 'Je veux me rendre au temple de Sephraliss (donjon).', 28153),
(155706, 'frFR', 'Je veux me rendre au Repos des rois (donjon).', 'Je veux me rendre au Repos des rois (donjon).', 28153),
(155705, 'frFR', 'Les Barges sont parés à toute éventualité !', '', 28153),
(155704, 'frFR', 'Nos amis à plumes sont maintenant à l\’abri des sorcières.', '', 28153),
(155703, 'frFR', 'Les sorcières se servent de charmes pour maudire nos oiseaux à la sortie de l\’œuf ! Détruisez-les et éliminez les fauconniers envoûtés avant que la malédiction ne se propage !', '', 28153),
(155702, 'frFR', '', 'Fichez le camp !', 28153),
(155701, 'frFR', '', 'J\’ai une arme et je n\’ai pas peur de m\’en servir.', 28153),
(155700, 'frFR', '', 'J\’en ai vraiment assez de vous voir.', 28153),
(155699, 'frFR', '', 'Montrez-moi n\’importe quelle bête, les Barges et moi on vous en débarrasse.', 28153),
(155698, 'frFR', '', 'Touffie, vilain chat. Viens ici tout de suite !', 28153),
(155697, 'frFR', '', 'Par ici, minou minou !', 28153),
(155696, 'frFR', 'Je veux me rendre à Atal\’Dazar (donjon).', 'Je veux me rendre à Atal\’Dazar (donjon).', 28153),
(155695, 'frFR', '', 'Faites-moi signe quand vous voudrez jouer dans la cour des grands.', 28153),
(155694, 'frFR', '', 'J\’ai des monstres à tuer.', 28153),
(155693, 'frFR', '', 'Qu\’y a-t-il, cette fois ?', 28153),
(155692, 'frFR', 'Mission accomplie, je présume ? Bien. Je ferai part de votre succès au chef de guerre.', '', 28153),
(155691, 'frFR', 'Bonjour, et merci à vous de nous aider à tester Battle for Azeroth !\n\nJe peux vous téléporter vers un certain nombre d\’instances de raid ou de donjons accessibles aux testeurs. Mais attention, on parle juste de téléportation, pas d\’un service de recherche de groupe, alors j\’espère que vous disposez déjà de compagnons pour surmonter les défis qui vous y attendent. Si ce n\’est pas le cas, vous devriez peut-être essayer notre outil de recherche de groupe pour vous trouver des alliés.\n\nVeillez à sélectionner le niveau de difficulté souhaité avant de vous téléporter ; une fois sur place, il ne vous sera pas forcément simple de quitter l\’instance pour changer de niveau !', 'Bonjour, et merci à vous de nous aider à tester Battle for Azeroth !\n\nJe peux vous téléporter vers un certain nombre d\’instances de raid ou de donjons accessibles aux testeurs. Mais attention, on parle juste de téléportation, pas d\’un service de recherche de groupe, alors j\’espère que vous disposez déjà de compagnons pour surmonter les défis qui vous y attendent. Si ce n\’est pas le cas, vous devriez peut-être essayer notre outil de recherche de groupe pour vous trouver des alliés.\n\nVeillez à sélectionner le niveau de difficulté souhaité avant de vous téléporter ; une fois sur place, il ne vous sera pas forcément simple de quitter l\’instance pour changer de niveau !', 28153),
(155690, 'frFR', '$n (Horde) apparaît sur votre carte comme |c00FFFF00|Hspell:272296|h[Assassin]|h|r ! Faites-lui mordre la poussière pour rafler la prime.', '$n (Horde) apparaît sur votre carte comme |c00FFFF00|Hspell:272296|h[Assassin]|h|r ! Faites-lui mordre la poussière pour rafler la prime.', 28153),
(155689, 'frFR', '$n (Alliance) apparaît sur votre carte comme |c00FFFF00|Hspell:272295|h[Assassin]|h|r ! Faites-lui mordre la poussière pour rafler la prime.', '$n (Alliance) apparaît sur votre carte comme |c00FFFF00|Hspell:272295|h[Assassin]|h|r ! Faites-lui mordre la poussière pour rafler la prime.', 28153),
(155688, 'frFR', 'Nous devons freiner l\’avancée des troupes ennemies dans cette zone. C\’est dans vos cordes, non ?', '', 28153),
(155687, 'frFR', '', 'Aucune créature n\’est impossible à abattre.', 28153),
(155686, 'frFR', 'Ça a pris un peu plus de temps que j\’escomptais… mais le résultat est acceptable. Notre campagne peut se poursuivre.', '', 28153),
(155685, 'frFR', 'Le chef de guerre a revendiqué les ressources de cette zone. Prenez ce qui nous appartient.', '', 28153),
(155684, 'frFR', 'Je t\’ai déjà dit que je ne voulais plus entendre parler d\’elle.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'frFR', '', 'Nous ferons bon usage de ces ressources ! Excellent travail.', 28153),
(155682, 'frFR', '', 'Tu te bats comme ta sœur.', 28153),
(155681, 'frFR', '', 'Cette région dispose de ressources qui profiteraient à l\’ordre. Prenez le contrôle de la zone et récupérez-les.', 28153),
(155680, 'frFR', 'Selon vos désirs, mère…', '', 28153),
(155679, 'frFR', '', 'Minou, tu es où ?', 28153),
(155678, 'frFR', '', 'Viens, Arthur.', 28153),
(155677, 'frFR', '', 'Je vous saurais gré d\’escorter Lucille jusqu\’à mes quartiers, après avoir exterminé la vermine…', 28153),
(155676, 'frFR', '', 'Vous avez vu mon chat ?', 28153),
(155675, 'frFR', '', 'En voilà des façons de parler à une dame, maréchal ! Vous feriez bien de soigner vos manières.', 28153),
(155674, 'frFR', '', 'Vous pensez pouvoir garder le rythme ?', 28153),
(155673, 'frFR', 'Ne l\’approchez pas, sorcière !', '', 28153),
(155672, 'frFR', '', 'Un peu de tenue, Lucille ! Ton père se porte comme un charme et sera bientôt seigneur de tout Kul Tiras ! Joins-toi à nous…', 28153),
(155671, 'frFR', '', 'Que… Que lui avez-vous fait ?', 28153),
(155670, 'frFR', '', 'Ma douce enfant, ta présence m\’emplit de joie. Tu as beaucoup manqué à ton père.', 28153),
(155669, 'frFR', '', 'Mère ? Est-ce… vous ?', 28153),
(155668, 'frFR', '', 'Vous n\’irez pas plus loin.', 28153),
(155667, 'frFR', 'Il paraît que c\’est en rapport avec toutes ces caisses que nous recevons des Corsandre.', 'Il paraît que c\’est en rapport avec toutes ces caisses que nous recevons des Corsandre.', 28153),
(155666, 'frFR', 'Le capitaine Laroche a l\’air furax.', 'Le capitaine Laroche a l\’air furax.', 28153),
(155665, 'frFR', 'Je suis bien content que nous ayons été affectés ici aujourd\’hui.', 'Je suis bien contente que nous ayons été affectés ici aujourd\’hui.', 28153),
(155664, 'frFR', 'Quoi ? C\’est une BOMBE ? Je pensais que c\’était un avocat.', '', 28153),
(155663, 'frFR', '', 'Fais gaffe avec cette poudre à canon, John, ou tu pourras dire adieu à tes mains.', 28153),
(155662, 'frFR', 'Relevez la passerelle ! On lève l\’ancre ! Vous avez fait un sacré boulot sur cette île.', '', 28153),
(155661, 'frFR', 'On dirait qu\’ils veulent aussi l\’azérite. Filons avant qu\’ils nous repèrent. Faut qu\’on rentre pour signaler ça.', '', 28153),
(155660, 'frFR', 'On a fini. Tous les filons de l\’île semblent épuisés, et c\’est pas trop tôt. Y a des voiles de Kul Tiras qui viennent d\’apparaître à l\’horizon.', '', 28153),
(155659, 'frFR', 'On dirait qu\’eux aussi ils veulent récolter l\’azérite. Tant mieux… Ils vont tout rassembler au même endroit ! On aura plus qu\’à la leur voler, ha !', '', 28153),
(155658, 'frFR', 'Des Hozen ! Ha ! On trouve vraiment n\’importe quoi sur ces îles.', '', 28153),
(155657, 'frFR', 'On a repéré un énorme filon d\’azérite à deux pas d\’où vous vous trouvez. Vous devriez aller jeter un coup d\’œil.', '', 28153),
(155656, 'frFR', 'Vous faites ça très bien. La soute sera pleine en moins de deux.', '', 28153),
(155655, 'frFR', 'Voilà un sacré monstre, et il est couvert de poussière d\’azérite. Tuez-le et on extraira tout de son cadavre.', '', 28153),
(155654, 'frFR', 'On dirait qu\’y a une autre source d\’azérite pas loin d\’où vous êtes. Vous devriez aller voir ça de plus près.', '', 28153),
(155653, 'frFR', 'En voilà, une jolie récolte. Beau boulot.', '', 28153),
(155652, 'frFR', 'Ah ouais, ça, c\’est un gros morceau. Allez, extirpez-le. On chargera l\’azérite dans la cale en moins de deux.', '', 28153),
(155651, 'frFR', 'La machine dit qu\’il y a de l\’azérite tout près d\’ici. Descendez à terre et jetez un coup d\’œil.', '', 28153),
(155650, 'frFR', 'Abaissez la passerelle. On est arrivés.', '', 28153),
(155649, 'frFR', 'Mais par contre, on ne sait pas ce qui s\’y trouve d\’autre. Vous allez devoir faire très attention à vous.', '', 28153),
(155648, 'frFR', 'On y est presque. Voilà l\’île sur laquelle nos éclaireurs ont repéré un tas d\’azérite.', '', 28153),
(155647, 'frFR', 'À vos ordres, capitaine.', 'À vos ordres, capitaine.', 28153),
(155646, 'frFR', '', 'Eh bien, dépêchez-vous de charger le tout à bord ! La moindre étincelle et on y passe tous !', 28153),
(155645, 'frFR', 'O-oui, capitaine Laroche.', 'O-oui, capitaine Laroche.', 28153),
(155644, 'frFR', '', 'C\’est la poudre à canon de la fonderie Corsandre, tout ça ?', 28153),
(155643, 'frFR', 'Sang et tonnerre, quelle est cette sorcellerie ? Nos navires coulent et nos troupes sont acculées sur le rivage !', '', 28153),
(155642, 'frFR', 'Vous savez, le premier qui vendra des bouchons d\’oreille à Port-Liberté se fera une petite fortune.', '', 28153),
(155641, 'frFR', 'Vous… Vous entendez ça ? Attendez… Oh non, pas encore ! Tuez-moi ça, vite !', '', 28153),
(155640, 'frFR', 'Joli ! Peut-être que Port-Liberté sera plus sûr, maintenant. Rhah, à qui je vais faire croire ça ?', '', 28153),
(155639, 'frFR', 'Ha ! Prends ça, vieux perroquet déplumé !', '', 28153),
(155638, 'frFR', 'Bravo ! Ça me fait une dette en moins à rembourser.', '', 28153),
(155637, 'frFR', 'Qu\’est-ce qui sent le grog et a un beau chapeau rouge ? Un pirate. Un méchant pirate, même.', '', 28153),
(155636, 'frFR', 'Des amis à moi ont vu un type recherché, pas loin d\’ici. Allons collecter cette jolie prime !', '', 28153),
(155635, 'frFR', 'Un hors-la-loi particulièrement retors se balade dans la zone. Vous devriez sans doute le refroidir.', '', 28153),
(155634, 'frFR', 'Tiens, si ce n\’est pas nos amis de la KapitalRisk ! Comme c\’est aimable, ils sont venus nous décharger de notre azérite. Allez leur souhaiter la bienvenue.', '', 28153),
(155633, 'frFR', 'La KapitalRisk s\’est mise à exploiter plusieurs sites sur l\’île. Vous devriez liquider tous ses avoirs, ressources gobelines comprises.', '', 28153),
(155632, 'frFR', 'La KapitalRisk vient de débarquer. J\’imagine qu\’elle veut profiter de cette source d\’azérite. Typique des Gobelins.', '', 28153),
(155631, 'frFR', 'On a repéré des sbires de la KapitalRisk un peu partout sur l\’île. On dirait qu\’une offre publique d\’achat hostile se prépare.', '', 28153),
(155630, 'frFR', 'Un grand nombre de chaloupes de facture vrykule approche. On dirait qu\’un clan a pris la mer en quête d\’azérite.', '', 28153),
(155629, 'frFR', 'Des Vrykuls viennent de débarquer de leurs chaloupes, ils doivent en avoir après notre cargaison. Je vous propose de les arrêter !', '', 28153),
(155628, 'frFR', 'Une flottille vrykule vient d\’arriver. Toute une bande de guerriers féroces se met à camper sur l\’île. Désolé, c\’est tout ce que je vois de derrière ce tonneau.', '', 28153),
(155627, 'frFR', 'Des navires vrykuls en approche. On dirait une flotte d\’écumeurs. Ils ne peuvent pas s\’empêcher d\’écumer des trucs, c\’est plus fort qu\’eux.', '', 28153),
(155626, 'frFR', 'Des Trolls des îles hargneux ont décidé de gâcher notre petite fête. Ils installent des campements partout sur l\’île.', '', 28153),
(155625, 'frFR', 'Canoës trolls à l\’horizon, ils seront sur nous incessamment sous peu. L\’azérite attire mes pires ennemis, on dirait.', '', 28153),
(155624, 'frFR', 'Une poignée de Trolls des îles vient d\’apparaître, sans doute pour piller l\’azérite. On ne peut pas leur en vouloir, mais j\’apprécierais que vous les teniez à bonne distance du bateau.', '', 28153),
(155623, 'frFR', 'Regardez, tout un tas de navires trolls viennent de débarquer. On n\’avait pas assez d\’ennuis comme ça, apparemment ! Un raid de Trolls, c\’est toujours la fête !', '', 28153),
(155622, 'frFR', 'Et voilà qu\’un ÉNORME dragon vient de surgir de nulle part, parce que ça manquait à ma journée, hein, pas vrai ? Dure semaine, j\’vous jure. Bref, y a un dragon.', '', 28153),
(155621, 'frFR', 'Ohé, les amis ? Un gros dragon vient de se joindre à la fête, et il a l\’air intéressé par votre azérite. Je dis ça, je dis rien.', '', 28153),
(155620, 'frFR', 'Dragons à l\’horizon, et ils ont l\’air très intéressés par notre navire. Je crois qu\’ils m\’ont vu. Euh… un petit coup de main ?', '', 28153),
(155619, 'frFR', 'Un vol entier de dragons vient d\’atterrir, et je pense savoir après quoi ils en ont. Bonne chance !', '', 28153),
(155618, 'frFR', 'Qu\’est-ce qui se passe encore ? Pourquoi est-ce que le ciel s\’est assombri ? Et POURQUOI l\’île est envahie de cadavres ? Oh, misère…', '', 28153),
(155617, 'frFR', 'Beurk, c\’est la PIRE puanteur que j\’ai jamais sentie. Qui n\’a pas pu se retenir ? Oh, ce sont des Morts-vivants. Hé, tout le monde, les Morts-vivants sont là et ils en ont après l\’azérite !', '', 28153),
(155616, 'frFR', 'Et pour pimenter le tout, on dirait que les Morts-vivants envahissent l\’île. Je veux même pas voir ça, c\’est trop horrible.', '', 28153),
(155615, 'frFR', 'Des Morts-vivants ? Ici ? Je n\’ai pas la moindre idée de ce qui se passe, mais quelque chose me dit que ce n\’est rien de bon.', '', 28153),
(155614, 'frFR', 'Réveillez-vous, des bâtiments tol\’vir apparaissent à l\’horizon et ils n\’ont pas l\’air de vouloir nous acheter de la verroterie. Donc dépêchez-vous, d\’accord ?', '', 28153),
(155613, 'frFR', 'Tiens, des Tol\’vir ! Ça faisait un sacré bail que je n\’avais pas vu la poupe de leurs navires. Ils sont bel et bien là, et ils ont une dent contre nous.', '', 28153),
(155612, 'frFR', 'Des vaisseaux tol\’vir viennent de toucher terre. Mais comment font tous les gêneurs pour trouver l\’azérite ? Ça m\’énerve ! Vous pouvez vous occuper d\’eux ?', '', 28153),
(155611, 'frFR', 'C\’est quoi, ça ? Des centaures ? Des hommes-taures ? Je crois qu\’il y a des… Tol\’vir, qui viennent de se pointer.', '', 28153),
(155610, 'frFR', 'Bateau pirate à l\’horizon. Son équipage veut sans doute aussi piller cet endroit. C\’est bien les pirates, ça…', '', 28153),
(155609, 'frFR', 'Un équipage de pirates a posé pied sur l\’île. Parce que quand il y a un trésor sur une île, doit forcément y avoir aussi des pirates, pas vrai ?', '', 28153),
(155608, 'frFR', 'Et voilà un TROISIÈME navire, parce que sinon, ce ne serait pas drôle ! Ce sont des pirates, au fait, si vous voulez tout savoir.', '', 28153),
(155607, 'frFR', 'Ouah ! On a failli se prendre un tir de canon. Et une armée de pirates s\’apprête à débarquer.', '', 28153),
(155606, 'frFR', 'Des sauroks viennent de montrer le bout de leur nez… Ils doivent avoir flairé l\’azérite. Ils ont vraiment un nez ? C\’est pas moi qui leur poserai la question.', '', 28153),
(155605, 'frFR', 'Il semblerait qu\’une bande entière de guerriers sauroks vienne de surgir de l\’océan. Voilà, voilà…', '', 28153),
(155604, 'frFR', 'C\’est quoi, ces trucs dans les vagues ? Oh, un banc entier de sauroks vient d\’émerger des profondeurs. Eh bien, je vous laisse gérer tout ça.', '', 28153),
(155603, 'frFR', 'Des lézards à l\’air patibulaire semblent très intéressés par notre navire et son azérite. Ce serait peut-être bien de les faire déguerpir, non ?', '', 28153),
(155602, 'frFR', 'On a des invités-surprises. Je n\’ai jamais vu ces types de ma vie, mais j\’imagine qu\’ils ne sont pas là pour nous aider.', '', 28153),
(155601, 'frFR', 'On a de la compagnie, je viens de repérer de nouveaux arrivants. Ils collectent l\’azérite, eux aussi, mais… y a quelque chose de bizarre chez eux.', '', 28153),
(155600, 'frFR', 'Ah ! D\’où ils sortent, ceux-là ? Ils ont surgi de nulle part ! Hé, les héros ? On a de la compagnie.', '', 28153),
(155599, 'frFR', 'Mais qui sont ces intrus ? Je n\’arrive pas à les reconnaître. Et ils seraient avec nous ? Hum, ouais. Moi non plus, j\’y crois pas.', '', 28153),
(155598, 'frFR', 'On dirait qu\’on a attiré l\’attention d\’un Dieu très ancien et de ses serviteurs, rien que ça. Vous pourriez, euh… régler ce problème ?', '', 28153),
(155597, 'frFR', 'Allons bon, c\’est au tour des abominations au visage tentaculaire de faire leur apparition. Bien, je vais me mettre à l\’abri, moi.', '', 28153),
(155596, 'frFR', 'Quelqu\’un d\’autre entend des murmures ? Soit je deviens fou, soit il y a des Sans-Visage sur l\’île. Oh, et ils en ont après l\’azérite.', '', 28153),
(155595, 'frFR', 'C\’est une tempête de ténèbres insondables ou je m\’y connais pas. Splendide. Les Dieux très anciens, à coup sûr. Faites attention aux tentacules.', '', 28153),
(155594, 'frFR', 'Et maintenant, on se paie un sacré paquet de Mogu qui voudraient bien piller notre azérite.', '', 28153),
(155593, 'frFR', 'On vient de repérer des Mogu un peu partout sur l\’île. Faites attention, on n\’est pas… très amis.', '', 28153),
(155592, 'frFR', 'Des Momo… Des Mogu viennent d\’accoster sur l\’île. Je suis pas sûr de ce qu\’ils viennent faire là. Vous vous en chargerez.', '', 28153),
(155591, 'frFR', 'Les serpents mogu préparent un raid. Attirés par l\’azérite, sans doute. Ça ne rate jamais.', '', 28153),
(155590, 'frFR', 'Ah, les Nagas sont de la fête. Manquait plus que ça, tiens. N\’y laissez pas votre peau, d\’accord ?', '', 28153),
(155589, 'frFR', 'J\’ai repéré des Nagas au loin, qui seront bientôt sur nous. Donnez-leur un accueil digne de ce nom, vous voulez bien ?', '', 28153),
(155588, 'frFR', 'Des Nagas viennent de débarquer sur l\’île. Ils sont à la recherche d\’azérite, sans doute sur les ordres de notre amie Azshara. C\’est quoi, son problème, à la fin ?', '', 28153),
(155587, 'frFR', 'Des Nagas sont remontés des profondeurs. Ils veulent mettre la main sur notre butin. Je vais prendre les devants et faire charger les canons dès maintenant.', '', 28153),
(155586, 'frFR', 'C\’est du brouillard qui arrive ? Non, attendez, je vois du bois vermoulu… Ce sont des Kvaldirs. Merveilleux.', '', 28153),
(155585, 'frFR', 'Euh, je voulais vous dire, on a repéré des navires kvaldirs qui seront là d\’un instant à l\’autre. Ils doivent vouloir l\’azérite. Mais pourquoi j\’ai accepté ce boulot ?', '', 28153),
(155584, 'frFR', 'Ça devient sacrément brumeux, par ici. Les Kvaldirs doivent être derrière tout ça, alors ouvrez l\’œil ! Euh, réflexion faite, ouvrez les deux.', '', 28153),
(155583, 'frFR', 'D\’où ça vient, cette odeur d\’algue ? Ah, d\’accord, on a de la compagnie. Des Kvaldirs.', '', 28153),
(155582, 'frFR', 'On va bientôt être submergés d\’insectes. Un énorme essaim de mantides est en approche. Si on me cherche, je serai dans ma cabine. Amusez-vous bien, les enfants !', '', 28153),
(155581, 'frFR', 'J\’ai entendu parler de ces créatures… les Mantides. Vous… vous en chargez ? Moi, j\’y suis allergique.', '', 28153),
(155580, 'frFR', 'C\’est un essaim d\’abeilles que j\’aperçois ? Non, trop gros. Ce sont des Mantides. Qui foncent droit sur nous…', '', 28153),
(155579, 'frFR', 'Vous allez adorer : les mantides débarquent. Naturellement, ils veulent la même azérite que vous. Sinon, ce serait pas drôle.', '', 28153),
(155578, 'frFR', 'Hé ! C\’était quoi, ce qui vient de nous survoler ? Vous avez vu ça ? Maintenant, il y a un gros dragon qui vous attend sur cette île. Faites attention.', '', 28153),
(155577, 'frFR', 'Ça alors, un gros dragon a fait son apparition, accompagné de tout un tas de petits dragons. Et ils n\’ont pas l\’air d\’apprécier qu\’on embarque de l\’azérite.', '', 28153),
(155576, 'frFR', 'Manquait plus que ça… Un dragon noir ! Avec la moitié de son vol ! Ici ! Non, vraiment, c\’est parfait…', '', 28153),
(155575, 'frFR', 'Hem, un gros dragon vient de se poser sur l\’île. Mon navire est inflammable, vous savez ? Alors tenez le dragon à distance.', '', 28153),
(155574, 'frFR', 'Les Tol\’vir donnent tout ce qu\’ils ont pour chasser l\’azérite. Faites attention à vous, sur l\’île.', '', 28153),
(155573, 'frFR', 'Hé, les Tol\’vir nous ont rejoints. C\’est drôle, ils cherchent la même azérite que nous.', '', 28153),
(155572, 'frFR', 'J\’aurais jamais cru revoir un navire tol\’vir un jour. Y en a plusieurs qui viennent de débarquer, et ils ont l\’air en rogne.', '', 28153),
(155571, 'frFR', 'Des navires viennent d\’arriver. J\’en ai vu qu\’une fois dans ma vie, mais j\’crois que c\’est des Tol\’vir. Z\’ont pas l\’air contents de nous voir.', '', 28153),
(155570, 'frFR', '', 'Essayez de rapporter la relique en un seul morceau, $n. Astrandis... Disons qu\’il a tendance à s\’emballer, parfois.', 28153),
(155569, 'frFR', '', 'Il est dans notre intérêt d\’empêcher ces pirates de prendre la mer. Je vous remercie.', 28153),
(155568, 'frFR', 'Je vais vous jeter dans la baie.', '', 28153),
(155567, 'frFR', 'Il n\’y a pas que la mer qui gronde.', '', 28153),
(155566, 'frFR', 'Vous ne savez pas qui vous importunez.', '', 28153),
(155565, 'frFR', '', 'Nous devons découvrir ce que trament ces pirates. Interceptez leurs ordres… quoi qu\’il en coûte.', 28153),
(155564, 'frFR', 'La marée remonte toujours.', '', 28153),
(155561, 'frFR', 'Puisse la mer vous être clémente.', '', 28153),
(155560, 'frFR', 'Ayez toujours la mer en vue.', '', 28153),
(155558, 'frFR', 'J\’ai horreur des oiseaux. Des animaux infects qui crient. Bon, passons à autre chose.', '', 28153),
(155557, 'frFR', 'Un de nos contacts à Port-Liberté a besoin de votre aide pour… calmer ses oiseaux. Je suppose que vous pouvez vous en charger.', '', 28153),
(155556, 'frFR', 'Je sers les marées.', '', 28153),
(155554, 'frFR', 'Ne sentez-vous pas… la puissance de cette… pierre ?', '', 28153),
(155553, 'frFR', 'Cette pierre nous rendra RICHES ! Bas les pattes !', '', 28153),
(155552, 'frFR', 'Les marées vous guident.', '', 28153),
(155551, 'frFR', 'Si vous écoutez les marées, vous en apprendrez beaucoup sur le monde.', '', 28153),
(155550, 'frFR', 'J\’ai mes soupçons...', '', 28153),
(155549, 'frFR', 'Ne m\’obligez pas à appeler la garde !', '', 28153),
(155548, 'frFR', 'Si vous avez quelque chose à dire, parlez !', '', 28153),
(155547, 'frFR', 'Je vous en prie… Épargnez mon chat.', '', 28153),
(155546, 'frFR', 'S\’il vous plaît, je suis très occupé.', '', 28153),
(155545, 'frFR', 'Revenez avec d\’autres récits de vos aventures !', '', 28153),
(155543, 'frFR', 'D\’autres larbins de Nedly ! Ils vont aller bouffer la boue, comme les autres !', '', 28153),
(155540, 'frFR', 'Épatant !', '', 28153),
(155539, 'frFR', 'Passez un moment fantastique !', '', 28153),
(155538, 'frFR', 'Faites comme chez vous. Mon domaine est votre domaine.', '', 28153),
(155536, 'frFR', 'Mangez, buvez et passez un bon moment !', '', 28153),
(155535, 'frFR', 'Bienvenue au festival de chasse et d\’équitation de Norwington !', '', 28153),
(155534, 'frFR', '', 'Et enfin, 500 milliards de norgaoctets sont consacrés à des images de mignons petits chats.', 28153),
(155533, 'frFR', 'Vous tombez à point nommé, mon $uami:amie;. Nous sommes face à une attaque de Troggs !', '', 28153),
(155532, 'frFR', '', 'Ils jouent avec des forces que personne ne devrait réveiller. Nous protégerons ces eaux !', 28153),
(155531, 'frFR', 'Guerriers de la Horde ! Montrez à l\’Alliance pourquoi on se bat ! Avancez jusqu\’au donjon !', '', 28153),
(155530, 'frFR', '', 'Regroupez-vous ! Chargez de plus belle ! Les hautes-terres seront à nous !', 28153),
(155529, 'frFR', '', 'Les humains tentent de tirer une effroyable puissance des profondeurs. Vous devez les arrêter !', 28153),
(155528, 'frFR', 'Un… Tortollan ?', 'Un… Tortollan ?', 28153),
(155527, 'frFR', '', 'Oui, la carapace avec des bras et des jambes, là-bas.\n\nMéfiez-vous, il est malin et fouinard comme c\’est pas permis ! Toujours en train de récupérer des reliques, des parchemins et d\’autres cochonneries.\n\nIl ne doit surtout pas trouver le trésor avant nous.', 28153),
(155526, 'frFR', 'Mon oncle en entendra parler !', '', 28153),
(155525, 'frFR', 'Je vous prie de respecter mon espace vital… S\’il vous plaît.', '', 28153),
(155524, 'frFR', 'Excusez-moi, pourriez-vous me laisser en paix ?', '', 28153),
(155522, 'frFR', 'Nous en avons terminé.', '', 28153),
(155521, 'frFR', 'Personne ne m\’avait prévenu… c\’est difficile, de diriger.', '', 28153),
(155520, 'frFR', 'Je fais de mon mieux.', '', 28153),
(155516, 'frFR', 'Le Trident est sous ma protection !', '', 28153),
(155515, 'frFR', 'Je dois faire mes preuves auprès de mon oncle.', '', 28153),
(155514, 'frFR', 'La marée vous accueille.', '', 28153),
(155513, 'frFR', 'Très bien.', '', 28153),
(155512, 'frFR', 'Si vous n\’avez besoin de rien, veuillez me laisser.', '', 28153),
(155511, 'frFR', 'De retour à mon poste.', '', 28153),
(155510, 'frFR', 'J\’ai un devoir à accomplir.', '', 28153),
(155509, 'frFR', 'Umpf.', '', 28153),
(155508, 'frFR', 'Splendide ! Je vais pouvoir concocter des potions… intéressantes avec ces ingrédients.', '', 28153),
(155507, 'frFR', 'La zone est riche en ressources naturelles et réactifs prisés en alchimie ! Récupérez quelques-uns de ces précieux composants pour moi.', '', 28153),
(155506, 'frFR', '', 'Nos fermiers vous sont reconnaissants de les avoir aidés à chasser les bêtes.', 28153),
(155505, 'frFR', '', 'Des bêtes sauvages empiètent sur les fermes le long de la côte. Aidez les fermiers à résoudre ce problème.', 28153),
(155504, 'frFR', 'Touchez-nous encore une fois et vous serez victime d\’une grave allergie pouvant entraîner la mort.', '', 28153),
(155503, 'frFR', 'Faites cela encore une fois, et vous vous rendrez compte que nous ne sommes pas toujours drôles.', '', 28153),
(155502, 'frFR', 'Si nous perdons notre chapeau, vous le regretterez.', '', 28153),
(155501, 'frFR', 'Avons-nous terminé ?', '', 28153),
(155500, 'frFR', 'Proliférez avec honneur. Notre esprit est sain.', '', 28153),
(155499, 'frFR', 'Que les spores vous enveloppent.', '', 28153),
(155498, 'frFR', 'Nous vous voyons.', '', 28153),
(155497, 'frFR', 'Nous vous saluons !', '', 28153),
(155496, 'frFR', 'Le monde a besoin… d\’un roi-lichen.', '', 28153),
(155495, 'frFR', 'Deuillemousse a faim…', '', 28153),
(155494, 'frFR', 'Rhaaaah !', '', 28153),
(155493, 'frFR', 'Les spores nous trouvent…', '', 28153),
(155492, 'frFR', 'Nous… n\’entendons… plus rien…', '', 28153),
(155491, 'frFR', 'Je vais vous tuer ! Tuer, tuer !', '', 28153),
(155490, 'frFR', 'Rejoignez-nous !', '', 28153),
(155489, 'frFR', 'Mourez, mourez, mourez !', '', 28153),
(155488, 'frFR', '', 'Ha ! C\’est le genre de trophée à rendre les Barges verts de jalousie.', 28153),
(155487, 'frFR', 'Une monstruosité maudite se nourrit des entrailles de nos recrues. Tuez-la… avant que je sois forcé d\’enrôler un nouveau contingent de conscrits inexpérimentés.', '', 28153),
(155486, 'frFR', '', 'Des gardes kultirassiens ont dit avoir vu une grosse bête dans les environs. C\’est une menace pour tous ceux qui prennent la mer.', 28153),
(155485, 'frFR', 'Des histoires de pirates parlent d\’un démon squelette qui hanterait la rade. Je préfère de loin cette explication.', '', 28153),
(155484, 'frFR', 'Une bête monstrueuse s\’est hissée sur le rivage. Je ne sais pas d\’où elle vient, mais elle a l\’air dangereuse.', '', 28153),
(155483, 'frFR', 'Beau boulot ! Certains des détenus de Tol Dagor y étaient pour une bonne raison. Il faisait partie de ceux-là.', '', 28153),
(155482, 'frFR', '', 'En mettant à cette folie, vous avez sauvé de nombreuses vies. Merci.', 28153),
(155481, 'frFR', 'Je pars…', 'Je pars…', 28153),
(155480, 'frFR', 'Je suis en sécurité à présent.', 'Je suis en sécurité à présent.', 28153),
(155479, 'frFR', 'Merci.', 'Merci.', 28153),
(155478, 'frFR', 'Je veux reposer…', 'Je veux reposer…', 28153),
(155477, 'frFR', 'J\’étais perdu…', 'J\’étais perdue…', 28153),
(155476, 'frFR', 'J\’avais tellement peur… Je suis rassuré à présent…', 'J\’avais tellement peur… Je suis rassurée à présent…', 28153),
(155475, 'frFR', 'Vous portez-vous bien ?', '', 28153),
(155474, 'frFR', 'La Lumière est si chaleureuse…', 'La Lumière est si chaleureuse…', 28153),
(155473, 'frFR', '', 'Merci pour votre aide. Nous ne l\’oublierons pas.', 28153),
(155471, 'frFR', 'Par ici.', 'Par ici.', 28153),
(155470, 'frFR', 'Rechargez !!', 'Rechargez !!', 28153),
(155469, 'frFR', '', 'Vous n\’avez rien à faire ici, hérétique !', 28153),
(155468, 'frFR', 'Feu !!', 'Feu !!', 28153),
(155467, 'frFR', '', 'Zandalar est entièrement faite d\’or. Il doit bien y avoir un moyen de voler toute la ville !', 28153),
(155466, 'frFR', '', 'Un évadé de la prison des Humains s\’est échoué près du port de la Horde. Il représente un danger pour nous tous.', 28153),
(155465, 'frFR', 'Son visage me dit quelque chose ! Attendez… Oui, je l\’ai déjà vu quelque part. C\’est pas bon signe.', '', 28153),
(155464, 'frFR', 'Les profondeurs… nous en donneront… plus !', '', 28153),
(155463, 'frFR', 'Cette puissance est un don des profondeurs !', '', 28153),
(155462, 'frFR', 'Je pensais que les Kultirassiens seraient de vaillants adversaires… mais ils sont aussi fragiles que n\’importe quel pantin de l\’Alliance.', '', 28153),
(155461, 'frFR', 'Un forestier sombre a débusqué l\’un des conseillers du grand amiral. Le piège est posé… À vous les honneurs de le déclencher.', '', 28153),
(155460, 'frFR', '', 'Les esprits vont pouvoir retrouver le repos.', 28153),
(155459, 'frFR', 'D\’accord… Mais vous reviendrez, hein ?', '', 28153),
(155458, 'frFR', 'D\’accord, à plus tard !', '', 28153),
(155457, 'frFR', 'Ça apprendra à la Horde à se frotter à nos soldats ! Beau travail.', '', 28153),
(155456, 'frFR', 'Un officier des Portvaillant a acculé un forestier-sombre ! Allez aider notre homme !', '', 28153),
(155455, 'frFR', 'Mon papa il est trop fort !', '', 28153),
(155454, 'frFR', 'Je sens que ça va être une bonne journée !', '', 28153),
(155453, 'frFR', 'Mon papa m\’a dit que les grands ont peur des fois. Ça vous arrive d\’avoir peur ?', '', 28153),
(155452, 'frFR', 'Oh, les jolis petits poneys !', '', 28153),
(155451, 'frFR', 'On n\’est jamais trop vieux pour apprendre !', '', 28153),
(155450, 'frFR', 'À une prochaine fois !', '', 28153),
(155449, 'frFR', '', 'Les serviteurs des sorcières ont provoqué la colère des esprits. Éliminez toute trace de corruption et apaisez les âmes égarées.', 28153),
(155448, 'frFR', 'Ah, tant pis… Au moins, j\’aurai pu déguster un cru de zanchuli grande réserve une… <hic !>… dernière fois avant de mourir !', '', 28153),
(155447, 'frFR', 'Je les ai entendus dire que Mojambo, il avait recruté des renforts pour le combat. L\’équipe de Tongo, elle a rallié ses rangs…', '', 28153),
(155446, 'frFR', 'La bande de Mojambo, je l\’ai aperçue en train d\’observer l\’arène…', '', 28153),
(155445, 'frFR', 'Votre part du marché, vous l\’avez respectée, et j\’en ferai autant…', '', 28153),
(155444, 'frFR', 'Ahhh ! La zanchuli grande réserve, voilà des années que je n\’avais pas dégusté un de ces crus…<hic !>', '', 28153),
(155443, 'frFR', 'Voilà le rhum. Dites-moi ce que vous savez.', 'Voilà le rhum. Dites-moi ce que vous savez.', 28153),
(155442, 'frFR', 'Très bien, au revoir ! Je serai… ici.', '', 28153),
(155441, 'frFR', 'Je cherche la connaissance. Et vous, que recherchez-vous ?', '', 28153),
(155440, 'frFR', 'Nous avons voyagé par monts et par vaux, mais nous voilà arrivés !', '', 28153),
(155439, 'frFR', 'Bonne chasse.', '', 28153),
(155438, 'frFR', 'Pour la Horde !', '', 28153),
(155437, 'frFR', 'Vous avez une proie à traquer ?', '', 28153),
(155436, 'frFR', 'Par la griffe et le croc.', '', 28153),
(155435, 'frFR', 'D\’accord, vous serez ma prochaine proie !', '', 28153),
(155434, 'frFR', 'Arrêtez, je ne plaisante pas !', '', 28153),
(155433, 'frFR', 'Je… euh… Je chasse seul.', '', 28153),
(155432, 'frFR', 'Que la chasse commence.', '', 28153),
(155431, 'frFR', 'Il en va ainsi.', '', 28153),
(155430, 'frFR', 'Je suis à l\’affût.', '', 28153),
(155429, 'frFR', 'La traque commence.', '', 28153),
(155428, 'frFR', 'Ma proie est proche.', '', 28153),
(155427, 'frFR', 'J\’entends l\’appel de la nature.', '', 28153),
(155426, 'frFR', 'Vous voyez ces chevaux ? Quelles bêtes majestueuses !', '', 28153),
(155425, 'frFR', 'Au plaisir de vous revoir !', '', 28153),
(155424, 'frFR', 'Rappelez-vous, on ne nourrit pas les animaux !', '', 28153),
(155423, 'frFR', 'Passez un bon séjour dans la station !', '', 28153),
(155422, 'frFR', '…', '', 28153),
(155421, 'frFR', 'Que faisons-nous ici ?', 'Que faisons-nous ici ?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'frFR', 'Qu\’alliez-vous me dire ?', 'Qu\’alliez-vous me dire ?', 28153),
(155419, 'frFR', 'Il faut nous hâter. Le temps presse.', 'Il faut nous hâter. Le temps presse.', 28153),
(155418, 'frFR', 'Comment vous portez-vous ?', '', 28153),
(155417, 'frFR', 'Salut !', '', 28153),
(155416, 'frFR', 'Bienvenue aux sources Thermorelax !', '', 28153),
(155415, 'frFR', '', 'Mes sœurs… vont s\’approprier… la puissance de cette pierre !', 28153),
(155414, 'frFR', '', 'Mère sera satisfaite de la puissance de cette pierre !', 28153),
(155413, 'frFR', 'Indiquez-nous notre première destination et nous ferons voile immédiatement.', '', 28153),
(155412, 'frFR', 'Rien de tel que le moment présent pour se mettre au travail, $n. L\’un de nos agents se tient prêt pour une mission importante.', '', 28153),
(155411, 'frFR', 'Que la Lumière soit avec vous, roi Wrynn.', '', 28153),
(155410, 'frFR', 'Faites bon voyage, mon roi.', '', 28153),
(155409, 'frFR', 'Le devoir m\’appelle à Hurlevent, mais j\’ai hâte de recevoir de vos nouvelles. Je sais que cette campagne se trouve entre les meilleures mains. Bonne chance à vous.', '', 28153),
(155408, 'frFR', 'Héraut.', '', 28153),
(155407, 'frFR', 'Pour les situations requérant une approche plus… subtile, maître Mathias Shaw et ses agents du SI:7 se tiendront à votre disposition.', '', 28153),
(155406, 'frFR', 'C\’est un honneur de travailler avec vous, $n.', '', 28153),
(155405, 'frFR', 'Pour poursuivre nos efforts, nous aurons le soutien des meilleurs soldats d\’Azeroth, la 7e Légion, sous la houlette du haut-commandant Halford Verroctone.', '', 28153),
(155404, 'frFR', 'En tant que héraut de l\’Alliance, vous jouerez un rôle crucial dans cette guerre. Nous devons à tout prix empêcher la Horde de rallier les Zandalari à leur cause.', '', 28153),
(155403, 'frFR', '$n, il est temps de mener le combat en Zandalar. Je vous attendrai à Boralus, à bord de la Rédemption du vent.', '', 28153),
(155402, 'frFR', 'Ces bois sont maudits ! Fichez le camp ! Fuyez tant que vous le pouvez !', 'Ces bois sont maudits ! Fichez le camp ! Fuyez tant que vous le pouvez !', 28153),
(155401, 'frFR', 'Je n\’ai jamais rien vu d\’aussi dément !', 'Je n\’ai jamais rien vu d\’aussi dément !', 28153),
(155400, 'frFR', 'Ils ont bouffé mon chien ! Et j\’ai bien failli y passer moi aussi !', 'Ils ont bouffé mon chien ! Et j\’ai bien failli y passer moi aussi !', 28153),
(155399, 'frFR', 'Par toutes les balanes de la chaloupe à papy, qu\’est-ce qui se passe ici ?', 'Par toutes les balanes de la chaloupe à papy, qu\’est-ce qui se passe ici ?', 28153),
(155398, 'frFR', 'J\’ai été poursuivi par une meute de lapins. Des lapins !', 'J\’ai été poursuivie par une meute de lapins. Des lapins !', 28153),
(155397, 'frFR', 'Ahhhhhhhhhhhhhhhhhhhhhh !', 'Ahhhhhhhhhhhhhhhhhhhhhh !', 28153),
(155396, 'frFR', 'Les animaux sont devenus fous !', 'Les animaux sont devenus fous !', 28153),
(155395, 'frFR', 'Merci à vous !', 'Merci à vous !', 28153),
(155394, 'frFR', 'Des Nagas ont débarqué sur la plage. Y en a tout un paquet qui veut aussi piller cette île.', '', 28153),
(155393, 'frFR', 'On a repéré des Nagas. Ils doivent avoir senti toute l\’azérite que vous avez récoltée. Faites gaffe.', '', 28153),
(155392, 'frFR', 'Les troupes nagas, elles sont de la fête aussi. Montrez-leur qu\’on sait rigoler.', '', 28153),
(155391, 'frFR', 'Y a des Nagas qui sortent des profondeurs à la recherche des mêmes trésors que nous. Faites gaffe.', '', 28153),
(155390, 'frFR', 'Surveillez vos arrières, y a un gros dragon et son vol qui viennent de surgir et ils se dirigent droit sur nous.', '', 28153),
(155389, 'frFR', 'Un groupe de dragons vient de se pointer et ils ont déjà commencé à récupérer de l\’azérite. Va falloir les arrêter.', '', 28153),
(155388, 'frFR', 'Ohé, du héros ! On a des visiteurs. Un vol de dragons vient d\’arriver, et j\’aime pas la façon dont ils regardent mon bateau.', '', 28153),
(155387, 'frFR', 'Je vois des trucs volants qui arrivent… Des dragons, à vue de nez. Ils doivent vouloir l\’azérite. Faites gaffe à vous.', '', 28153),
(155386, 'frFR', 'Des dragons noirs ici ? Ils doivent vouloir l\’azérite comme nous. Faites attention à vous.', '', 28153),
(155385, 'frFR', 'Des dragons… J\’aurais jamais cru en voir un de taille adulte ! Ils en ont après l\’azérite, notre azérite.', '', 28153),
(155384, 'frFR', 'Hé, y a des dragons qui ont atterri ici. On dirait que l\’azérite leur fait de l\’œil.', '', 28153),
(155383, 'frFR', 'Le ciel, il s\’assombrit… C\’est un dragon noir ! Il est venu avec toute sa famille pour piller l\’île. À l\’aide !', '', 28153),
(155382, 'frFR', 'Des types de la KapitalRisk viennent d\’arriver avec de l\’équipement. Ils cherchent l\’azérite, c\’est sûr.', '', 28153),
(155381, 'frFR', 'La KapitalRisk cherche à monter une exploitation sur cette île. Si j\’étais vous, je l\’arrêterais.', '', 28153),
(155380, 'frFR', 'On a des investisseurs de la KapitalRisk sur le dos, et ils cherchent à nous piquer notre pactole. Allez donc discuter affaires avec eux.', '', 28153),
(155379, 'frFR', 'Hé, les amis, la KapitalRisk a débarqué sur l\’île. Ils ont l\’air d\’établir leur campement en ce moment même.', '', 28153),
(155378, 'frFR', 'Regardez, là-bas, des embarcations trolles. Ils en ont après l\’azérite. Faut pas les laisser faire !', '', 28153),
(155377, 'frFR', 'Des Trolls des îles viennent d\’arriver. Ils veulent tout piller, j\’en suis sûr. Restez sur vos gardes.', '', 28153),
(155376, 'frFR', 'Canoës trolls à l\’horizon. Je les porte pas dans mon cœur, ceux-là. Tuez-en quelques-uns pour moi, d\’accord ?', '', 28153),
(155375, 'frFR', 'Y a des Trolls des îles qui viennent de débarquer et ils ont pas l\’air content.', '', 28153),
(155374, 'frFR', 'On se prend des tirs de canon ! Un navire pirate vient de jeter l\’ancre, ils sont là pour l\’azérite !', '', 28153),
(155373, 'frFR', 'Et maintenant, c\’est au tour des pirates. Ils viennent de débarquer, allez donc leur souhaiter la bienvenue.', '', 28153),
(155372, 'frFR', 'Y a un bateau pirate qui vient d\’accoster sur l\’île. Son équipage cherche la même chose que nous. Faites attention.', '', 28153),
(155371, 'frFR', 'Vous, j\’vous aime pas…', 'Vous devriez vraiment partir…', 28153),
(155370, 'frFR', 'Je vois une autre voile à l\’horizon, on dirait des pirates. Vaudrait mieux vous occuper d\’eux avant qu\’ils nous volent notre cargaison.', '', 28153),
(155369, 'frFR', 'Je reconnaîtrais ces silhouettes entre mille. On a un raid de Sauroks sur les bras, soyez prudents.', '', 28153),
(155368, 'frFR', 'Y a des mouvements bizarres dans les vagues. Ouais, c\’est bien des sauroks qui font surface… Un paquet de sauroks.', '', 28153),
(155367, 'frFR', 'Y a une bande de lézards hargneux qui zieutent notre navire. Débarrassez-nous d\’eux, et vite !', '', 28153),
(155366, 'frFR', 'Une bande de sauroks vient de surgir de l\’eau. Ils veulent aussi mettre les griffes sur l\’azérite.', '', 28153),
(155365, 'frFR', 'Non… pas le visage !', 'Vous pouvez arrêter, maintenant…', 28153),
(155364, 'frFR', 'Je vais louper mon échéance !', 'Je suis pas assuré pour ça !', 28153),
(155363, 'frFR', 'Vous entendez ça ? Les mantides sont là et ils cherchent aussi de l\’azérite. Vous faites pas piquer, hein ! Ha ha !', '', 28153),
(155362, 'frFR', 'Y a un gros essaim d\’insectes qui arrive. Faites gaffe à vous… Ils sont là pour la même raison que nous.', '', 28153),
(155361, 'frFR', 'Y a des bestioles qui viennent de se pointer. Des Mantides, qui doivent vouloir mettre la main sur l\’azérite, eux aussi.', '', 28153),
(155360, 'frFR', 'Ce bourdonnement… Il vient du ciel. M\’est avis qu\’un sacré paquet d\’insectes s\’apprêtent à envahir cette île.', '', 28153),
(155359, 'frFR', 'Mon assurance paye rubis sur l\’ongle quand ça arrive…', 'Ça, c\’est embarrassant !', 28153),
(155358, 'frFR', 'Les esprits… ils m\’emportent…', 'Les esprits… ils m\’emportent…', 28153),
(155357, 'frFR', 'Qu\’est-ce qui sent l\’algue comme ça ? Là-bas ! Des chaloupes kvaldirs viennent de débarquer !', '', 28153),
(155356, 'frFR', 'J\’y vois rien dans cette purée de pois. Y a sûrement des Kvaldirs dans le coin. Faites gaffe.', '', 28153),
(155355, 'frFR', 'Des bateaux tout pourris font voile sur l\’île et ils empestent le Kvaldir. Ils sont là pour notre azérite.', '', 28153),
(155354, 'frFR', 'Il fait de plus en plus brumeux, ici, mais c\’est pas une brume normale. Les Kvaldirs seront bientôt là.', '', 28153),
(155353, 'frFR', 'Ça, c\’est pas… ce que j\’avais prévu…', 'Ça, c\’est pas… ce que j\’avais prévu…', 28153),
(155352, 'frFR', 'Moi, j\’ai toujours voulu avoir un bateau pirate, chef. J\’lui ai donné le nom de ma fille, Mala !\n\nSi j\’ai un vaisseau un jour, j\’l\’appellerai comme mon fils !', '', 28153),
(155351, 'frFR', 'Comment avez-vous trouvé le nom ?', 'Comment avez-vous trouvé le nom ?', 28153),
(155350, 'frFR', 'Hé hé hé hé…\n\nÇa, j\’vous le raconterai une autre fois, chef.', '', 28153),
(155349, 'frFR', 'D\’où vient votre navire ?', 'D\’où vient votre navire ?', 28153),
(155348, 'frFR', 'Garona m\’a envoyé chercher un bateau. Alors, j\’en ai trouvé un.', '', 28153),
(155347, 'frFR', 'Pourquoi avez-vous un bateau pirate ?', 'Pourquoi avez-vous un bateau pirate ?', 28153),
(155346, 'frFR', 'De nouveaux amis qui sont de la partie ! Des guerriers vrykuls, je crois bien.', '', 28153),
(155345, 'frFR', 'Hé, ho, des gêneurs viennent d\’arriver. On dirait des écumeurs vrykuls. Surveillez vos arrières.', '', 28153),
(155344, 'frFR', 'Des chaloupes vrykules sont en train d\’accoster sur l\’île. Des écumeurs des mers… Ils en veulent à notre cargaison.', '', 28153),
(155343, 'frFR', 'Hé, chef, ça vous dit, une p\’tite mutinerie de derrière les fagots ?', '', 28153),
(155342, 'frFR', 'Chaloupes à l\’horizon. C\’est forcément des Vrykuls qui veulent mettre la main sur les pierres.', '', 28153),
(155341, 'frFR', 'Y a quelque chose qui envoie les morts à nos trousses. Quelque chose qui n\’est pas de ce monde. Prudence, d\’accord ?', '', 28153),
(155340, 'frFR', 'Les esprits, ils me disent que les morts sont là et qu\’ils veulent votre azérite.', '', 28153),
(155339, 'frFR', 'Ça sent mauvais ! Je parie que c\’est des Morts-vivants qui veulent nous détrousser. Faites gaffe.', '', 28153),
(155338, 'frFR', 'Y a rien de naturel à cette obscurité. C\’est une force maléfique qui en a après l\’azérite.', '', 28153),
(155337, 'frFR', 'Voilà des visiteurs bizarres qui ont l\’air de s\’intéresser à l\’azérite. On dirait un genre de secte.', '', 28153),
(155336, 'frFR', 'Ben mince, je les ai même pas vus venir ! On a de la compagnie !', '', 28153),
(155335, 'frFR', 'Hé, c\’est qui, ceux-là ? On dirait qu\’ils veulent aussi l\’azérite. Vous feriez bien de les arrêter.', '', 28153),
(155334, 'frFR', 'On a de nouveaux amis. Je les avais jamais vus avant. Ils doivent être là pour l\’azérite.', '', 28153),
(155333, 'frFR', 'Je vois des serpents mogu à l\’horizon, ils seront là d\’une minute à l\’autre.', '', 28153),
(155332, 'frFR', 'Des Mogu viennent de débouler et ils en ont après notre pactole. Allez donc les accueillir.', '', 28153),
(155331, 'frFR', 'Un des Mogu vient nous disputer notre azérite. Faites attention, ils attaquent en bande.', '', 28153),
(155330, 'frFR', 'J\’ai vu des serpents volants arriver pas loin d\’ici. Les Mogu vont pas tarder.', '', 28153),
(155329, 'frFR', 'Une tempête de ténèbres s\’est levée… Il doit y avoir des Sans-Visage dans le coin.', '', 28153),
(155328, 'frFR', 'Dites, vous entendez ces murmures ? C\’est sûrement un Dieu très ancien qui envoie ses gars nous attaquer. Faites gaffe.', '', 28153),
(155327, 'frFR', 'Y a des types avec des tentacules plein la face qui sont venus voler votre azérite. Je… Je crois que je vais aller me planquer.', '', 28153),
(155326, 'frFR', 'L\’azérite a attiré l\’attention des Sans-Visage. Y a tout un groupe qui vient de débarquer de nulle part.', '', 28153),
(155325, 'frFR', 'Méchant oiseau ! Pas de sang.', 'Méchant oiseau ! Pas de sang.', 28153),
(155324, 'frFR', 'Ouste !', 'Ouste !', 28153),
(155323, 'frFR', '', 'Le bois de Ruisseval est à nouveau sûr. Merci.', 28153),
(155322, 'frFR', '', 'Les animaux sont tombés sous l\’emprise des sorcières et s\’attaquent à nos chasseurs ! Sauvez-les et abattez ces bêtes sauvages !', 28153),
(155321, 'frFR', '', 'Heureusement que vous êtes là pour nous faire rire un peu, $p.', 28153),
(155320, 'frFR', '', 'Votre tête ne m\’est pas inconnue… Vous n\’auriez pas fait un séjour forcé à Tol Dagor, par hasard ?', 28153),
(155319, 'frFR', '', 'Bien joué. La faune des collines ne menacera plus les communautés environnantes.', 28153),
(155318, 'frFR', '', 'Les sorcières ont jeté un sort à la faune dans les collines ! Levez la malédiction avant que les bêtes atteignent la ville.', 28153),
(155317, 'frFR', 'Je commence à avoir du mal à respirer !', 'Je commence à avoir du mal à respirer !', 28153),
(155312, 'frFR', 'Se remettre de cette attaque leur prendra du temps. Pour la Dame noire !', '', 28153),
(155311, 'frFR', 'Les troupes de notre chef de guerre ont établi une base dans l\’académie militaire. Soutenez leurs efforts !', '', 28153),
(155310, 'frFR', '', 'J\’ai fait mes classes avec certains d\’eux ! La Horde va payer pour les dégâts qu\’elle a causés !', 28153),
(155309, 'frFR', '', 'Un contingent d\’élite de la Horde a réussi à pénétrer dans l\’académie Portvaillant. Les soldats qui la défendent ne refuseraient pas un peu d\’aide !', 28153),
(155308, 'frFR', '', 'Havrebrune est maintenant en sécurité, mais nous devons rester sur nos gardes.', 28153),
(155307, 'frFR', '', 'Les sorcières ont jeté un mauvais sort sur Havrebrune. Levez cette malédiction avant qu\’il soit trop tard !', 28153),
(155306, 'frFR', '', 'Hah… la puissance des pierres… revient aux… Chantorage !', 28153),
(155305, 'frFR', '', 'Cette pierre est un don des grands fonds. Vous ne l\’aurez pas !', 28153),
(155304, 'frFR', 'Quand la fleur est morte, j\’ai tout de suite su qu\’il ne reviendrait pas. Alors, j\’ai trouvé un travail ici, sur les quais. Cette fleur, elle m\’a évité de finir à la rue comme tant d\’autres.', 'Quand la fleur est morte, j\’ai tout de suite su qu\’il ne reviendrait pas. Alors, j\’ai trouvé un travail ici, sur les quais. Cette fleur, elle m\’a évité de finir à la rue comme tant d\’autres.', 28153),
(155303, 'frFR', 'Les habitants de cette vallée ne courberont l\’échine ni devant les Hurans, ni devant les envahisseurs de la Horde.', '', 28153),
(155302, 'frFR', 'Vous pas prendre… cailloux de Trogg…', '', 28153),
(155301, 'frFR', 'Cailloux… de moi…', '', 28153),
(155300, 'frFR', 'Fracasser… vous…', '', 28153),
(155299, 'frFR', 'Trogg… cassé…', '', 28153),
(155298, 'frFR', 'Trogg tomber…', '', 28153),
(155297, 'frFR', 'Trogg… tuer…', '', 28153),
(155296, 'frFR', 'Arrraagh !', '', 28153),
(155295, 'frFR', 'Garouuu…', '', 28153),
(155294, 'frFR', 'Ici, c\’est chez Trogg ! Vous partir !', '', 28153),
(155293, 'frFR', 'Aaaraauuh ! Trogg tuer vous !', '', 28153),
(155292, 'frFR', 'Moi casser vous en petits bouts !', '', 28153),
(155291, 'frFR', '', 'Je fais en sorte que tout se passe bien en Kul Tiras. En quoi puis-je vous aider ?', 28153),
(155290, 'frFR', 'Cailloux brillants de Trogg ! Ouste !', '', 28153),
(155289, 'frFR', 'Graaaaraah ! Détruire !', '', 28153),
(155288, 'frFR', 'Trogg démolir tête !', '', 28153),
(155287, 'frFR', 'Trogg défoncer crâne !', '', 28153),
(155286, 'frFR', 'Ici, c\’est chez Trogg !', '', 28153),
(155285, 'frFR', 'Troggzor !', '', 28153),
(155284, 'frFR', 'Cailloux de moi ! Pas vous !', '', 28153),
(155283, 'frFR', 'Mon trésor ! À moi !', '', 28153),
(155282, 'frFR', 'Rarrragh !', '', 28153),
(155281, 'frFR', 'Aaaaaraaagh !', '', 28153),
(155280, 'frFR', 'Écraser ! Détruire ! TUER !', '', 28153),
(155279, 'frFR', 'Trogg fracasser !', '', 28153),
(155278, 'frFR', 'Trogg pas bête !', '', 28153),
(155277, 'frFR', 'Hé ! Z\’avez vu ce que la princesse, elle a fait à l\’Alliance ? Regardez les décombres, sur votre gauche ! Le Loa a pas fait dans la dentelle !', '', 28153),
(155276, 'frFR', 'Après ça, les Nagas, ils ont disparu quelque temps. On a envisagé de reconstruire, mais Gral s\’était volatilisé ou il était trop faible pour participer, alors c\’est pas allé plus loin.', '', 28153),
(155275, 'frFR', 'Gral était furax, et pour cause ! Tous ses disciples ont été tués. Tous ceux qui passaient près de l\’eau cette nuit-là ont perçu sa souffrance à chaque nouvelle victime.', '', 28153),
(155274, 'frFR', 'Ho ho ! On s\’est sentis soulagés tout d\’un coup ! On a tout de suite compris qu\’elle était morte, cette sale sorcière !', '', 28153),
(155273, 'frFR', 'Passez une excellente journée.', '', 28153),
(155272, 'frFR', 'Faites attention. Ces terres ne sont plus sûres.', '', 28153),
(155271, 'frFR', 'Chantorage regorge de trésors.', '', 28153),
(155270, 'frFR', 'Bienvenue dans la vallée.', '', 28153),
(155269, 'frFR', 'Salutations !', '', 28153),
(155268, 'frFR', 'Brennadam est mon foyer. Je le protégerai coûte que coûte.', '', 28153),
(155267, 'frFR', '', 'Je suis une femme de parole. Vous et votre Horde êtes les bienvenus dans mon port.', 28153),
(155266, 'frFR', 'Ouais, capitaine. On va soutenir votre cause. Et on espère que vous soutiendrez la nôtre aussi.', '', 28153),
(155265, 'frFR', '', 'Enfin libre... Il semble que vous teniez parole.', 28153),
(155264, 'frFR', 'Pourquoi… êtes-vous ici… ?', '', 28153),
(155263, 'frFR', 'Vous n\’avez détruit qu\’une épine… La liane reste…', '', 28153),
(155262, 'frFR', 'Grah !', '', 28153),
(155261, 'frFR', 'Non… pas les gemmes…', '', 28153),
(155260, 'frFR', 'Vous ne pourrez pas… tous nous tuer…', '', 28153),
(155259, 'frFR', 'Je flétris…', '', 28153),
(155258, 'frFR', 'Brisé…', '', 28153),
(155257, 'frFR', 'Épines… brisées…', '', 28153),
(155256, 'frFR', 'Les gemmes brillantes de cette île nous appartiennent, $Uintrus:intruse; !', '', 28153),
(155255, 'frFR', 'Le minerai renforce nos épines !', '', 28153),
(155254, 'frFR', 'Cette île est à nous, et son pouvoir avec !', '', 28153),
(155253, 'frFR', 'Nos lances d\’épines transperceront votre chair.', '', 28153),
(155252, 'frFR', 'Je vais épingler votre peau à mon mur !', '', 28153),
(155251, 'frFR', 'Nous avons fait le bon choix.', '', 28153),
(155250, 'frFR', 'Nos lianes vont s\’emparer de cette île et de votre chair !', '', 28153),
(155249, 'frFR', 'Brise-épine, vous n\’avez rien à faire ici.', '', 28153),
(155248, 'frFR', 'Serviteurs, défendez-moi !', '', 28153),
(155247, 'frFR', 'Rendez-leur la monnaie de leur pièce !', '', 28153),
(155246, 'frFR', 'Nul ne peut arrêter les lianes sauvages !', '', 28153),
(155245, 'frFR', 'Les épines boiront votre sang.', '', 28153),
(155244, 'frFR', 'Lâchez tout !', '', 28153),
(155243, 'frFR', 'Faites-vous plaisir !', '', 28153),
(155242, 'frFR', 'Vous allez flétrir, $Uennemi des épines:ennemie des épines;.', '', 28153),
(155241, 'frFR', 'Cet endroit nous appartient !', '', 28153),
(155240, 'frFR', 'On n\’aurait pas servi à grand-chose, enfermés dans une cage.', '', 28153),
(155239, 'frFR', 'Transpercez leur chair !', '', 28153),
(155238, 'frFR', 'Encornez ces intrus !', '', 28153),
(155237, 'frFR', '', 'Une mer agitée nous attend.', 28153),
(155236, 'frFR', 'Des intrus !', '', 28153),
(155235, 'frFR', 'Mourez, brise-épine !', '', 28153),
(155234, 'frFR', '', 'La marée vous guide.', 28153),
(155233, 'frFR', 'Les reliques sont en sûreté. Gral n\’est pas encore perdu.', '', 28153),
(155232, 'frFR', 'Sang et tonnerre, mon $Uami:amie;.', '', 28153),
(155231, 'frFR', 'D\’ailleurs, j\’ai aussi trouvé ce curieux bijou.', '', 28153),
(155230, 'frFR', 'On a peut-être un peu précipité les choses en quittant l\’avant-poste.', '', 28153),
(155229, 'frFR', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|tLe %s vous marque avec une mèche allumée. Ne vous approchez pas des barils de munitions !', 28153),
(155228, 'frFR', 'Profite du temps qu\’il te reste à vivre, Razgaji. La prochaine fois qu\’on se verra... ce sera la dernière !', '', 28153),
(155227, 'frFR', 'Notre périple nous a conduits jusqu\’ici. Les découvertes que nous avons faites sont une nouvelle pièce du puzzle.', '', 28153),
(155226, 'frFR', '', 'Faites attention à vous.', 28153),
(155225, 'frFR', '', 'Maire Roz, pour vous servir.', 28153),
(155224, 'frFR', '', 'Je dois protéger les citoyens de Chantorage.', 28153),
(155223, 'frFR', '', 'Vous venez donner un coup de main ?', 28153),
(155222, 'frFR', 'Pour la Horde !', '', 28153),
(155221, 'frFR', 'Inutile de te débattre comme ça ! Je vais te vider comme un vulgaire poisson !', 'Inutile de te débattre comme ça ! Je vais te vider comme un vulgaire poisson !', 28153),
(155220, 'frFR', 'Ha ! Encore une prise !', 'Ha ! Encore une prise !', 28153),
(155219, 'frFR', 'J\’veux bien. Z\’êtes pas près d\’oublier les histoires que je vais vous raconter.', '', 28153),
(155218, 'frFR', '', 'Parlons peu, parlons bien, Ty\’jin. Si vous voulez qu\’on travaille ensemble, vous allez devoir m\’en dire un peu plus sur la Horde.', 28153),
(155217, 'frFR', 'Toute l\’azérite… sera… à… nous…', '', 28153),
(155216, 'frFR', 'Cette azérite appartient à la compagnie Corsandre !', '', 28153),
(155215, 'frFR', '', 'Des troupes ennemies se sont mises en marche. Repoussez-les !', 28153),
(155214, 'frFR', '', 'Vous avez offert un peu de répit à nos troupes.', 28153),
(155213, 'frFR', '', 'Les sorcières ont battu en retraite ! Beau travail !', 28153),
(155212, 'frFR', '', 'Le Sabbat a lancé une attaque ici. Mettez-y fin !', 28153),
(155211, 'frFR', '', 'Vous nous avez offert un peu de répit. Merci.', 28153),
(155210, 'frFR', '', 'Le Sabbat s\’en prend aux habitants de Drustvar ! Repoussez les sorcières !', 28153),
(155209, 'frFR', '', 'Au nom de mon peuple, je vous remercie pour votre aide.', 28153),
(155208, 'frFR', '', 'Mon peuple a besoin de votre aide. Je vous en prie, prêtez-lui main forte.', 28153),
(155207, 'frFR', 'Non ! On lâche l\’affaire pour l\’instant. Mais quand on reviendra... on leur fera pas de cadeau !', '', 28153),
(155206, 'frFR', 'J\’en fais mon affaire, patron ! En garde, $R !', 'J\’en fais mon affaire, patron ! En garde, $R !', 28153),
(155205, 'frFR', 'Je reviendrai pas. Tu crois vraiment que tes larbins sont de taille face à mon acolyte ? Cherche pas la bagarre, tu peux pas gagner.', '', 28153),
(155204, 'frFR', 'Fini ? C\’est moi qui décide quand c\’est fini, ici ! Tu sais ce qui arrive aux déserteurs !', '', 28153),
(155203, 'frFR', 'C\’est fini, Mojambo. J\’en ai ma claque de vivre comme un brigand. Je vais suivre mon petit bonhomme de chemin, maintenant...', '', 28153),
(155202, 'frFR', 'Hé hé hé...', 'Hé hé hé...', 28153),
(155201, 'frFR', 'Tu chercherais pas à fausser compagnie à tes vieux compères, dis-moi ?', '', 28153),
(155200, 'frFR', 'Regardez un peu qui voilà... Razgaji ! Je vous avais bien dit qu\’on le trouverait ici...', '', 28153),
(155199, 'frFR', 'Restez sur vos gardes. Mojambo, on peut pas lui faire confiance...', '', 28153),
(155198, 'frFR', 'Je suis prêt. Allons-y !', 'Je suis prête. Allons-y !', 28153),
(155197, 'frFR', 'Puisse la mer bénir ces lingots et ne jamais chercher à les reprendre.', 'Puisse la mer bénir ces lingots et ne jamais chercher à les reprendre.', 28153),
(155196, 'frFR', '', 'Nous reviendrons, forts du pouvoir de notre maître !', 28153),
(155195, 'frFR', 'Pourriez-vous bénir ces lingots de foudrargent ?', 'Pourriez-vous bénir ces lingots de foudrargent ?', 28153),
(155194, 'frFR', 'Bon vent, $r.', 'Bon vent, $r.', 28153),
(155193, 'frFR', '', 'Tous se prosterneront devant la reine Azshara !', 28153),
(155192, 'frFR', '', 'Le pouvoir de sa volonté vous brûlera les yeux !', 28153),
(155191, 'frFR', 'Arracher le harpon.', 'Arracher le harpon.', 28153),
(155190, 'frFR', '<À bout de force, la créature vous observe brièvement avant de reporter son attention sur le harpon fiché dans son flanc.>', '<À bout de force, la créature vous observe brièvement avant de reporter son attention sur le harpon fiché dans son flanc.>', 28153),
(155189, 'frFR', 'Vous allez où ?', '', 28153),
(155188, 'frFR', 'Mouga magoudou ! Écrasez !', '', 28153),
(155187, 'frFR', 'Ugafa ! Moi je gros bobo !', '', 28153),
(155186, 'frFR', 'Ooooh, méchants ! Ouste !', '', 28153),
(155185, 'frFR', 'C\’est quoi ça maguda ?', '', 28153),
(155184, 'frFR', 'Gouaargh ! Cailloux… à moi !', '', 28153),
(155183, 'frFR', 'Ouaaah ! Vous pas prendre trésor !', '', 28153),
(155182, 'frFR', 'Gouaaah ? Qui que c\’est que ça ?', '', 28153),
(155181, 'frFR', 'Bwagauugh ! À manger pour poissons !', '', 28153),
(155180, 'frFR', 'Agou… ?', '', 28153),
(155179, 'frFR', 'Hurg !', '', 28153),
(155178, 'frFR', 'Gafu… mogo…', '', 28153),
(155177, 'frFR', 'Ooug…', '', 28153),
(155176, 'frFR', 'Moug ?', '', 28153),
(155175, 'frFR', 'Matoufa…', '', 28153),
(155174, 'frFR', 'Gurk !', '', 28153),
(155173, 'frFR', 'A-bou-bou-bou-bou !', '', 28153),
(155172, 'frFR', 'Urga magou ?', '', 28153),
(155171, 'frFR', 'Krip !', '', 28153),
(155170, 'frFR', 'Bouga bouga !', '', 28153),
(155169, 'frFR', 'Augh !', '', 28153),
(155168, 'frFR', 'Oka magodo !', '', 28153),
(155167, 'frFR', 'Bokum ?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'frFR', 'Bouga mabugu !', '', 28153),
(155165, 'frFR', 'Ah gah mah gahma !', '', 28153),
(155164, 'frFR', 'Son cœur faiblit... À part abréger ses souffrances, je ne peux plus rien pour lui.', '', 28153),
(155163, 'frFR', 'Les Corsandre ont mis votre tête à prix !', 'Les Corsandre ont mis votre tête à prix !', 28153),
(155162, 'frFR', 'Je prendrai mon trophée sur votre cadavre !', 'Je prendrai mon trophée sur votre cadavre !', 28153),
(155161, 'frFR', 'Vous ne pouvez rien contre les Corsandre !', 'Vous ne pouvez rien contre les Corsandre !', 28153),
(155160, 'frFR', 'La ville est à nous !', 'La ville est à nous !', 28153),
(155159, 'frFR', 'Boralus va brûler !', 'Boralus va brûler !', 28153),
(155158, 'frFR', 'Je vous retrouverai dans un lieu plus sûr !', 'Je vous retrouverai dans un lieu plus sûr !', 28153),
(155157, 'frFR', 'Il me faut un bac pour Drustvar.', 'Il me faut un bac pour Drustvar.', 28153),
(155156, 'frFR', 'Pourquoi… venez ici… ?', '', 28153),
(155155, 'frFR', 'Cailloux qui brillent… à moi…', '', 28153),
(155154, 'frFR', 'Bougie de moi !', '', 28153),
(155153, 'frFR', 'Ouille, ouille, ouille !', '', 28153),
(155152, 'frFR', 'Grah !', '', 28153),
(155151, 'frFR', 'Bougie… éteint…', '', 28153),
(155150, 'frFR', 'Aaaaaaaaaaaaaaaaaaah !', '', 28153),
(155149, 'frFR', 'Non !', '', 28153),
(155148, 'frFR', 'Vous brûler comme bougie géante !', '', 28153),
(155147, 'frFR', 'Moi prendre bougie de vous maintenant !', '', 28153),
(155146, 'frFR', 'Écrabouiller et voler les trucs !', '', 28153),
(155145, 'frFR', 'Percer tunnel dans crâne !', '', 28153),
(155144, 'frFR', 'Vous pas prendre cailloux qui brillent !', '', 28153),
(155143, 'frFR', 'Mon île ! Je suis roi !', '', 28153),
(155142, 'frFR', 'Cailloux qui brillent à moi ! Moi !', '', 28153),
(155141, 'frFR', 'Nous a trouvé ici, pas vous !', '', 28153),
(155140, 'frFR', 'Ici à moi !', '', 28153),
(155139, 'frFR', 'Mordre ! Prendre leurs bougies !', '', 28153),
(155138, 'frFR', 'Grah ! Intrus !', '', 28153),
(155135, 'frFR', 'Pas prendre bougie !', '', 28153),
(155134, 'frFR', 'Bishibosh !', '', 28153),
(155133, 'frFR', 'Cailloux qui brillent à nous !', '', 28153),
(155132, 'frFR', 'Cailloux qui brillent font bien brûler bougie !', '', 28153),
(155131, 'frFR', 'Bonne chance. Si vous avez des dieux, j\’espère qu\’ils vous protégeront.', 'Bonne chance. Si vous avez des dieux, j\’espère qu\’ils vous protégeront.', 28153),
(155130, 'frFR', 'Nous y voilà. J\’irai pas plus loin.', 'Nous y voilà. J\’irai pas plus loin.', 28153),
(155129, 'frFR', 'La dernière fois que j\’y ai jeté l\’ancre, un loup a failli me dévorer la jambe…', 'La dernière fois que j\’y ai jeté l\’ancre, un loup a failli me dévorer la jambe…', 28153),
(155128, 'frFR', 'On va mouiller un peu plus loin. Le port du Désosseur n\’est pas très fréquentable en ce moment.', 'On va mouiller un peu plus loin. Le port du Désosseur n\’est pas très fréquentable en ce moment.', 28153),
(155127, 'frFR', 'Je ne sais pas ce que vous devez y faire, mais j\’vous conseille de le faire vite.', 'Je sais pas ce que vous devez y faire, mais j\’vous conseille de le faire vite.', 28153),
(155126, 'frFR', 'Je suis pas du genre superstitieux, mais j\’dois dire que ce qui se passe en Drustvar me fiche une sacrée frousse.', 'J\’suis pas du genre superstitieux, mais j\’dois dire que ce qui se passe en Drustvar me fiche une sacrée frousse.', 28153),
(155125, 'frFR', 'Mais depuis récemment, les mines semblent à sec et les bouchers ont tout bonnement disparu !', 'Mais depuis récemment, les mines semblent à sec et les bouchers ont tout bonnement disparu !', 28153),
(155124, 'frFR', 'Y a pas si longtemps, on avait plein de marchands sur ce bac, qui s\’approvisionnaient chez les fermiers et les mineurs là-bas.', 'Y a pas si longtemps, on avait plein de marchands sur ce bac, qui s\’approvisionnaient chez les fermiers et les mineurs là-bas.', 28153),
(155123, 'frFR', 'La plupart des passeurs refusent d\’y j\’ter l\’ancre, avec toutes ces horribles rumeurs qui circulent.', 'La plupart des passeurs refusent d\’y j\’ter l\’ancre, avec toutes ces horribles rumeurs qui circulent.', 28153),
(155122, 'frFR', 'Alors, comme ça, vous allez en Drustvar ? Z\’avez de la veine que j\’sois à la barre.', 'Alors, comme ça, vous allez en Drustvar ? Z\’avez de la veine que j\’sois à la barre.', 28153),
(155121, 'frFR', 'Ooh ahh ! Ahhhh !', '', 28153),
(155120, 'frFR', 'Argh…', '', 28153),
(155119, 'frFR', 'Allez… vous faire… grouk…', '', 28153),
(155118, 'frFR', 'Aïe ! En plein dans les pucs !', '', 28153),
(155117, 'frFR', 'Bah !', '', 28153),
(155116, 'frFR', 'Méchants… lokdus…', '', 28153),
(155115, 'frFR', 'Oukard…de doukacque…', '', 28153),
(155114, 'frFR', 'Non, mon qui-brille !', '', 28153),
(155113, 'frFR', 'La flore et la faune sont abondantes, en Zandalar. Il faut les étudier et en dresser l\’inventaire.', 'La flore et la faune sont abondantes, en Zandalar. Il faut les étudier et en dresser l\’inventaire.', 28153),
(155112, 'frFR', 'D\’où qu\’ils sortent, ces doukacques ?', '', 28153),
(155111, 'frFR', 'Je vais te coller un ouk là où que ça fait mal !', '', 28153),
(155110, 'frFR', 'Groukez-les, que ça doukacque !', '', 28153),
(155109, 'frFR', 'Un travail admirable ! On pourra très bientôt recommencer à concocter de puissantes potions !', '', 28153),
(155108, 'frFR', 'Désolé, l\’$Uami:amie;, mais je ne peux rien accepter de plus. Le planning est complètement p… Hé, vous avez des sous ? Oubliez ce que je viens de dire. Qu\’est-ce que je peux faire pour vous ?', 'Désolé, l\’$Uami:amie;, mais je ne peux rien accepter de plus. Le planning est complètement p… Hé, vous avez des sous ? Oubliez ce que je viens de dire. Qu\’est-ce que je peux faire pour vous ?', 28153),
(155107, 'frFR', 'Nos troupes ont besoin de plus de composants alchimiques ! Je vous prie de récupérer les réactifs nécessaires dans la zone. Oh, et, attention aux ours.', '', 28153),
(155106, 'frFR', '', 'Les sorcières attaquent Butte-du-Faucon ! Déjouez leurs maléfices et restaurez l\’ordre dans la ville !', 28153),
(155105, 'frFR', '', 'Grâce à vous, les sorcières ne reviendront pas de sitôt ! Merci d\’avoir sauvé les habitants de Butte-du-Faucon.', 28153),
(155104, 'frFR', 'Bienvenue. Tout ce que vous voyez ici a été récemment fauché aux gens du cru. Exotisme garanti !', 'Bienvenue. Tout ce que vous voyez ici a été récemment fauché aux gens du cru. Exotisme garanti !', 28153),
(155103, 'frFR', 'Ouke d\’ici, qui-brille est à moi !', '', 28153),
(155102, 'frFR', 'Groukards de lokdus, c\’est mon île !', '', 28153),
(155101, 'frFR', 'Je vais t\’écrabouiller, doukacque !', '', 28153),
(155100, 'frFR', 'Cassez-les à coup de clé à molette !', 'À mort !', 28153),
(155099, 'frFR', 'Ça sent l\’accident du travail !', 'Tu parles d\’un environnement de travail protégé !', 28153),
(155098, 'frFR', 'Je sais reconnaître les perdants quand j\’en croise !', 'Attrapez vos clés plates ! Des « réparations » s\’imposent !', 28153),
(155097, 'frFR', 'Nous mourons… au fil d\’une lame…', '', 28153),
(155096, 'frFR', 'Vous nous défaites… mais sans gagner…', '', 28153),
(155095, 'frFR', 'Les spores vous envelopperont…', '', 28153),
(155094, 'frFR', 'Nous persistons… par-delà la mort…', '', 28153),
(155093, 'frFR', 'Nous abandonnons cette dépouille…', '', 28153),
(155092, 'frFR', 'Au moins… mourons-nous… dans l\’honneur…', '', 28153),
(155091, 'frFR', 'Ainsi prend fin notre vie.', '', 28153),
(155090, 'frFR', 'Nous croîtrons… et nous nous battrons…', '', 28153),
(155089, 'frFR', 'Pour les spores !', '', 28153),
(155088, 'frFR', 'Notre volonté est une !', '', 28153),
(155087, 'frFR', 'Hé ! On a des règles, ici. Et vous les enfreignez toutes !', 'Vous, là… vous êtes $Uviré:virée; !', 28153),
(155086, 'frFR', 'Vous avez failli ! Nous avons gagné !', '', 28153),
(155085, 'frFR', 'Sentez la morsure de nos lames !', '', 28153),
(155084, 'frFR', 'Notre volonté nous protège !', '', 28153),
(155083, 'frFR', 'C\’est une bataille que vous avez déjà perdue !', '', 28153),
(155082, 'frFR', 'Vous auriez dû vous entraîner !', '', 28153),
(155081, 'frFR', 'On va vous pourrir de bas en haut !', '', 28153),
(155080, 'frFR', 'Je vous en prie, sauvez Boralus !', 'Je vous en prie, sauvez Boralus !', 28153),
(155079, 'frFR', 'Ces pirates sont en train de dévaster Boralus !', 'Ces pirates sont en train de dévaster Boralus !', 28153),
(155078, 'frFR', 'Merci !', 'Merci !', 28153),
(155077, 'frFR', 'Faites-en des pucs, de ces lokdus !', '', 28153),
(155076, 'frFR', 'C\’est moi le roi ici, lokdus !', '', 28153),
(155075, 'frFR', 'Tuez-les ! Chouravez leurs pucs !', '', 28153),
(155074, 'frFR', 'Lokdus padici !', '', 28153),
(155073, 'frFR', 'Tuez le lokdu !', '', 28153),
(155072, 'frFR', 'Qui-brille rend nous plus fort !', '', 28153),
(155071, 'frFR', 'Île est à nous ! Pas à vous !', '', 28153),
(155070, 'frFR', 'Va te faire ouker !', '', 28153),
(155069, 'frFR', 'Pas touche au qui-brille !', '', 28153),
(155068, 'frFR', 'Lokdus intrus !', '', 28153),
(155067, 'frFR', 'Il y a des années, Zalazane et Vol\’jin, je les ai entraînés à la maîtrise de leur art. Je n\’aurais jamais pu imaginer à quel point leur destin, il bouleverserait le monde.', '', 28153),
(155066, 'frFR', 'Je faisais que mon boulot !', 'Je faisais que mon boulot !', 28153),
(155065, 'frFR', 'C\’est pour vous que j\’aurais dû bosser…', 'C\’est pour vous que j\’aurais dû bosser…', 28153),
(155064, 'frFR', '', 'Oui ? Que puis-je faire pour vous aider ?', 28153),
(155063, 'frFR', 'Ce qui va le plus me manquer, c\’est la bière…', 'Ce qui va le plus me manquer, c\’est la bière…', 28153),
(155062, 'frFR', 'Je savais bien que c\’était un boulot ingrat !', 'Je savais bien que c\’était un boulot ingrat !', 28153),
(155061, 'frFR', 'Les esprits… je les rejoins…', 'Les esprits… je les rejoins…', 28153),
(155060, 'frFR', 'Je vais me reposer… un moment…', 'Je vais me reposer… un moment…', 28153),
(155059, 'frFR', 'Je vais… le dire…', '', 28153),
(155058, 'frFR', 'Prochaine fois, vous laisser gagner moi…', '', 28153),
(155057, 'frFR', 'Haha ! Moi gagner… euh…', '', 28153),
(155056, 'frFR', 'Non… moi pas perdre…', '', 28153),
(155055, 'frFR', 'Vous problème… moi corriger problèmes.', '', 28153),
(155054, 'frFR', 'Moi technicien thermique. Moi intelligent. Moi faire du feu !', '', 28153),
(155053, 'frFR', 'Vous asseoir dans huile… moi avoir allumette !', 'Vous asseoir dans huile… moi avoir allumette !', 28153),
(155052, 'frFR', 'Moi pas aimer feu… Vous prendre feu. Tenez !', 'Moi pas aimer feu… Vous prendre feu. Tenez !', 28153),
(155051, 'frFR', 'J\’vais t\’faire rôtir à la broche.', 'J\’vais t\’faire rôtir à la broche.', 28153),
(155050, 'frFR', 'Venir ici, c\’était pas très malin.', 'Venir ici, c\’était pas très malin.', 28153),
(155049, 'frFR', 'Le feu, ça brûle. Il fallait pas s\’approcher.', 'Le feu, ça brûle. Il fallait pas s\’approcher.', 28153),
(155048, 'frFR', 'Je sens déjà votre odeur de viande grillée.', 'Je sens déjà votre odeur de viande grillée.', 28153),
(155047, 'frFR', 'Quelqu\’un a demandé du feu ?', 'Quelqu\’un a demandé du feu ?', 28153),
(155046, 'frFR', 'Elle est retournée dans ses abysses.', '', 28153),
(155045, 'frFR', 'La bête est de retour ! Pourchassez-la avant qu\’elle cause plus de dégâts au mur !', '', 28153),
(155044, 'frFR', 'Quoi ? Vol\’jin… On peut pas acquérir une telle puissance sans devenir… un…', '', 28153),
(155043, 'frFR', 'Vous croyez vraiment que… détruire mon corps m\’empêchera… de vous tailler en pièces ?', '', 28153),
(155042, 'frFR', 'Vous croyez avoir une chance de gagner ? Vous faites que retarder l\’inévitable.', '', 28153),
(155041, 'frFR', 'J\’ai beaucoup appris de Bwonsamdi pendant qu\’il torturait mon âme. J\’vais vous montrer un peu son vaudou.', '', 28153),
(155040, 'frFR', 'Personne peut m\’échapper ! Tôt ou tard, j\’aurai ma revanche sur Vol\’jin et sur tous les Sombrelances !', '', 28153),
(155039, 'frFR', 'Serviteurs ! Tuez leur fidèle et apportez-moi les cendres de Vol\’jin. MAINTENANT !', '', 28153),
(155038, 'frFR', 'Où il est ? Où est-ce que vous cachez Vol\’jin ? Et surtout… comment ?', '', 28153),
(155037, 'frFR', 'Où est-ce que vous le cachez, Sombrelances ? Où est mon vieil ami ?', '', 28153),
(155036, 'frFR', 'Écrasez les Sombrelances et trouvez-moi ces cendres !', '', 28153),
(155035, 'frFR', 'Oui, mes serviteurs. Cherchez les cendres de Vol\’jin et rapportez-les-moi.', '', 28153),
(155034, 'frFR', 'Ces saletés d\’insectes mangeraient n\’importe quoi. C\’est répugnant.', '', 28153),
(155033, 'frFR', 'Les ranishu se regroupent en meute ! Pulvérisez-les avant qu\’ils deviennent un problème impossible à gérer.', '', 28153),
(155032, 'frFR', 'Tout ira bien, ne vous inquiétez pas. Que les vents vous portent.', 'Tout ira bien, ne vous inquiétez pas. Que les vents vous portent.', 28153),
(155031, 'frFR', 'Vous avez su m\’indiquer la bonne voie. Que va-t-il advenir de vous ?', 'Vous avez su m\’indiquer la bonne voie. Que va-t-il advenir de vous ?', 28153),
(155030, 'frFR', 'J\’aurais aimé pouvoir vous aider davantage.', 'Mon frère et moi aurions aimé pouvoir vous aider davantage.', 28153),
(155029, 'frFR', '', 'Bon boulot ! Vous avoir dans notre camp, c\’est un grand honneur.', 28153),
(155028, 'frFR', '', 'Y a un nid d\’araignées filesable pas loin de l\’arène. Allez les exterminer !', 28153),
(155027, 'frFR', 'Il semble que cette arme soit d\’origine gnome. Elle devrait quand même être efficace au combat.', '', 28153),
(155026, 'frFR', 'Nos soldats ont mis la main sur des armes… intéressantes, qui pourraient nous être utiles si nous arrivons à nous en servir. Allez les tester sur la faune locale.', '', 28153),
(155025, 'frFR', '', 'La compagnie Corsandre, elle va mettre des semaines à compenser cette perte. Bien joué !', 28153),
(155024, 'frFR', '', 'La compagnie Corsandre fait des siennes pas loin d\’ici. Allez semer le bazar dans leurs affaires.', 28153),
(155023, 'frFR', 'Une centaine de crétins largués sur une île bourrée d\’armes en tous genres ! Et on vend des billets de zeppelin pour assister au spectacle depuis le ciel !', 'Une centaine de crétins largués sur une île bourrée d\’armes en tous genres ! Et on vend des billets de zeppelin pour assister au spectacle depuis le ciel !', 28153),
(155022, 'frFR', 'On impose une taxe sur les robots, et après, on fabrique des robots percepteurs ! Argent facile !', 'On impose une taxe sur les robots, et après, on fabrique des robots percepteurs ! Argent facile !', 28153),
(155021, 'frFR', 'Une ampoule noire ! Produit l\’effet inverse d\’une ampoule.', 'Une ampoule noire ! Produit l\’effet inverse d\’une ampoule.', 28153),
(155020, 'frFR', 'Des mini chapeaux de cérémonie à placer sur les chapeaux décontractés pour les grandes occasions !', 'Des mini chapeaux de cérémonie à placer sur les chapeaux décontractés pour les grandes occasions !', 28153),
(155019, 'frFR', 'Des flotems : des totems qui vont sur l\’eau !', 'Des flotems : des totems qui vont sur l\’eau !', 28153),
(155018, 'frFR', 'Des chaussures-pistolets ! Une seconde, non… déjà fait. Des CHAUSSETTES-pistolets !', 'Des chaussures-pistolets ! Une seconde, non… déjà fait. Des CHAUSSETTES-pistolets !', 28153),
(155017, 'frFR', 'Des fusées recyclables !', 'Des fusées recyclables !', 28153),
(155016, 'frFR', 'Une équipe de bombsleigh gobeline !', 'Une équipe de bombsleigh gobeline !', 28153),
(155015, 'frFR', 'Du fromage de catégorie militaire.', 'Du fromage de catégorie militaire.', 28153),
(155014, 'frFR', 'Des glaives de guerre ambidextres à lames tronçonneuses ! Vendez-les aux Illidari !', 'Des glaives de guerre ambidextres à lames tronçonneuses ! Vendez-les aux Illidari !', 28153),
(155013, 'frFR', 'Le Rêve de plastique, pour les siestes de très courte durée !', 'Le Rêve de plastique, pour les siestes de très courte durée !', 28153),
(155012, 'frFR', 'Des pinces de barbecue tactiques !', 'Des pinces de barbecue tactiques !', 28153),
(155011, 'frFR', 'Une histoire d\’amour… entre un Humain et, euh, un Jinyu !', 'Une histoire d\’amour… entre un Humain et, euh, un Jinyu !', 28153),
(155010, 'frFR', 'Une tâche rondement menée ! Il est bon de vous savoir avec nous.', '', 28153),
(155009, 'frFR', 'Un pilier, non pas pour soutenir le toit, mais pour maintenir le plancher au sol !', 'Un pilier, non pas pour soutenir le toit, mais pour maintenir le plancher au sol !', 28153),
(155008, 'frFR', 'Il y a tout près un nid d\’araignées filesable qui bloquent l\’accès au canyon. Il faut ouvrir le passage pour nos troupes !', '', 28153),
(155007, 'frFR', 'Une boule de cristal en azérite ! Votre destin est entre vos mains !', 'Une boule de cristal en azérite ! Votre destin est entre vos mains !', 28153),
(155006, 'frFR', 'Des briquettes de charbon de Teldrassil ! Un savoureux goût de fumé !', 'Des briquettes de charbon de Teldrassil ! Un savoureux goût de fumé !', 28153),
(155005, 'frFR', 'Des véhicules qui roulent sur l\’eau, mais pas sur terre !', 'Des véhicules qui roulent sur l\’eau, mais pas sur terre !', 28153),
(155004, 'frFR', 'Des bardes !', 'Des bardes !', 28153),
(155003, 'frFR', 'Un sifflet pour attirer les maîtres de vol !', 'Un sifflet pour attirer les maîtres de vol !', 28153),
(155002, 'frFR', 'Beau travail, soldat ! Voilà un monstre en moins dans ce piège mortel qu\’on appelle Vol\’dun.', '', 28153),
(155001, 'frFR', 'Une sorte de cristal arcanique qui vous améliore en tous points ! Légèrement instable, sans doute, mais ce n\’est pas bien grave !', 'Une sorte de cristal arcanique qui vous améliore en tous points ! Légèrement instable, sans doute, mais ce n\’est pas bien grave !', 28153),
(155000, 'frFR', 'Un ranishu géant terrorise le goulet, mais il est trop dangereux pour être attaqué de front. Il va falloir trouver une autre approche pour l\’arrêter !', '', 28153),
(154999, 'frFR', 'Des fusils à papier toilette ! Pensez à tout le temps que vous pourriez gagner !', 'Des fusils à papier toilette ! Pensez à tout le temps que vous pourriez gagner !', 28153),
(154998, 'frFR', 'Des bateaux superposés ! Pensez à toute cette surface libérée pour d\’autres activités. Je prends celui du dessus !', 'Des bateaux superposés ! Pensez à toute cette surface libérée pour d\’autres activités. Je prends celui du dessus !', 28153),
(154997, 'frFR', 'Du chewing-gum réutilisable ! Partagez-le avec vos amis, vos familiers, voire des inconnus !', 'Du chewing-gum réutilisable ! Partagez-le avec vos amis, vos familiers, voire des inconnus !', 28153),
(154996, 'frFR', 'C\’était une basse besogne, mais quelqu\’un devait bien s\’en charger ! J\’aimais autant que ce soit vous, soldat !', '', 28153),
(154995, 'frFR', 'Nous devons faire pousser quelque chose dans ce désert si nous voulons espérer survivre. Et donc, il nous faut de l\’engrais… Voyez ce que vous pouvez dénicher.', '', 28153),
(154994, 'frFR', 'J\’étais sceptique, je l\’avoue, mais ce totem va se révéler extrêmement utile contre les infidèles.', '', 28153),
(154993, 'frFR', 'Tacha a découvert un autre totem zandalari dans l\’une des ruines. Essayez-le pour voir ce qu\’il fait.', '', 28153),
(154992, 'frFR', 'Ça, ça me plaît ! Je vais le mettre de côté en attendant de l\’utiliser sur des Orcs !', '', 28153),
(154991, 'frFR', 'La compagnie Corsandre mettra des semaines à compenser une telle perte. Bon travail !', '', 28153),
(154990, 'frFR', 'Nos éclaireurs ont trouvé cet antique totem zandalari dans les ruines. Voyons voir ce qu\’il fait.', '', 28153),
(154989, 'frFR', 'La compagnie Corsandre exploite une mine clandestine près d\’ici. Je veux que vous mettiez un terme à cette activité.', '', 28153),
(154988, 'frFR', 'Les sables s\’étendent, mais la vie persiste. Merci.', '', 28153),
(154987, 'frFR', 'Les oasis de Vol\’dun sont une ressource précieuse. Nous devons les entretenir avec soin.', '', 28153),
(154986, 'frFR', 'Les victoires ne sont pas toutes le fruit d\’un combat glorieux. Les ravitaillements nous maintiendront en vie.', '', 28153),
(154985, 'frFR', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\’kafh anagg.', '', 28153),
(154984, 'frFR', 'Cette oasis nous offrira un avantage tactique non négligeable et servira notre expansion sur le continent.', '', 28153),
(154983, 'frFR', 'Ma défaite n\’est qu\’un battement du cœur des abysses infinis.', '', 28153),
(154982, 'frFR', 'Je dois admettre que ça a fonctionné bien mieux que je l\’attendais.', '', 28153),
(154981, 'frFR', 'Nos alliés, euh… peu ordinaires du port de Zem\’lan ont échafaudé un nouveau plan. Allez les aider, si vous avez confiance en eux.', '', 28153),
(154980, 'frFR', 'Hah ! Ça leur apprendra à se frotter à l\’Alliance !', '', 28153),
(154979, 'frFR', 'Des hommes à nous ont volé un bateau et en ont fait une machine de guerre. Allons dire deux mots à ces monstres de morts-vivants !', '', 28153),
(154978, 'frFR', 'Beau travail ! Ces diables y réfléchiront maintenant à deux fois avant de s\’attaquer à l\’Alliance !', '', 28153),
(154977, 'frFR', 'D\’infâmes pirates morts-vivants ont capturé une partie de nos soldats. Libérez-les. On n\’abandonne personne !', '', 28153),
(154976, 'frFR', '', 'Merci. Même les exilés ne méritaient pas un tel sort.', 28153),
(154975, 'frFR', '', 'Les pirates de Zem\’lan retiennent des exilés zandalari prisonniers. Allez les libérer !', 28153),
(154974, 'frFR', 'L\’attention des infidèles est détournée. Faites pleuvoir la mort sur eux !', '', 28153),
(154973, 'frFR', 'Nul doute qu\’ils s\’en remettront, mais pour le moment, nous pouvons savourer la paix.', '', 28153),
(154972, 'frFR', 'Les infidèles sont proprement innombrables. Il faut les contenir ici.', '', 28153),
(154971, 'frFR', 'Gloire à Sephraliss ! Puissent tous les Sephraks se souvenir d\’elle un jour…', '', 28153),
(154970, 'frFR', 'Prenez une fraction de mon pouvoir et purgez ces terres des infidèles.', '', 28153),
(154969, 'frFR', '', 'Mes forces… Que m\’arrive-t-il ?', 28153),
(154968, 'frFR', '', 'Ce pouvoir… m\’empêche de… bouger…', 28153),
(154967, 'frFR', 'La vie… me quitte…', '', 28153),
(154966, 'frFR', 'Je ne peux plus… bouger… Aidez-moi…', '', 28153),
(154965, 'frFR', 'Uuurrgh…', '', 28153),
(154964, 'frFR', 'Pensez-vous vraiment avoir la moindre chance face à un dieu ? MOUREZ !', '', 28153),
(154963, 'frFR', 'Plus de sang pour étancher ma soif !', '', 28153),
(154962, 'frFR', 'Votre sang me rend plus puissant !', '', 28153),
(154961, 'frFR', 'Marre de boulot pourri ! Moi m\’entraîner dur pour devenir quelqu\’un !', 'Marre de boulot pourri ! Moi m\’entraîner dur pour devenir quelqu\’un !', 28153),
(154960, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk s\’apprête à lancer |cFFFF0000|Hspell:258622|h[Impulsion résonante]|h|r !', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk s\’apprête à lancer |cFFFF0000|Hspell:258622|h[Impulsion résonante]|h|r !', 28153),
(154959, 'frFR', 'Ne venez pas vous plaindre si ce griffon finit par vous manger une main.', 'Ne venez pas vous plaindre si ce griffon finit par vous manger une main.', 28153),
(154956, 'frFR', 'Les ombres s\’épaississent. Les élus se rassemblent. Notre heure approche.', '', 28153),
(154955, 'frFR', 'Je vais donner une finalité à votre chair.', '', 28153),
(154954, 'frFR', '', 'Mon pouvoir... ma malédiction... c\’est impossible...', 28153),
(154953, 'frFR', 'Si vous revenez…', '', 28153),
(154952, 'frFR', 'À mon retour, nous parlerons de l\’honneur… et des moyens de le restaurer.', '', 28153),
(154951, 'frFR', 'Conduisez-le à la prison.', '', 28153),
(154950, 'frFR', 'Votre espèce n\’existe que pour alimenter ma croissance.', '', 28153),
(154949, 'frFR', 'Aujourd\’hui, si.', '', 28153),
(154948, 'frFR', 'Ce n\’est pas à un roi de l\’Alliance d\’en décider !', '', 28153),
(154947, 'frFR', 'Entendez-moi. Il n\’y a point d\’honneur à cela.', '', 28153),
(154946, 'frFR', 'Un jour, mon père m\’a dit que Varok Saurcroc incarnait le meilleur de la Horde : le sens de l\’honneur.', '', 28153),
(154945, 'frFR', 'Non ! J\’exige une mort honorable !', '', 28153),
(154944, 'frFR', 'Soldats… arrêtez !', '', 28153),
(154940, 'frFR', '', 'Quelle ténacité ! Vous pouvez vous féliciter d\’avoir tenu jusqu\’à offenser ma fierté.', 28153),
(154939, 'frFR', 'Concentrez tous les tirs sur cette monstruosité ! Les Nagas ne franchiront pas ce mur aujourd\’hui !', '', 28153),
(154937, 'frFR', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en mode mythique.>', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en mode mythique.>', 28153),
(154936, 'frFR', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en mode héroïque.>', '<Ajouter mon groupe à la file d\’attente pour l\’exploration d\’une île en mode héroïque.>', 28153),
(154935, 'frFR', '<File d\’attente pour l\’exploration d\’une île en mode mythique.>', '<File d\’attente pour l\’exploration d\’une île en mode mythique.>', 28153),
(154934, 'frFR', '<File d\’attente pour l\’exploration d\’une île en mode héroïque.>', '<File d\’attente pour l\’exploration d\’une île en mode héroïque.>', 28153),
(154933, 'frFR', 'Partez, membre de la meute. Érigez une statue à mon honneur sur les marches de Dazar\’alor. Faites connaître la force de la meute et je vous accorderai ma faveur.', '', 28153),
(154932, 'frFR', '', 'Ces trois parchemins devraient vous aider à vous déplacer dans la région.', 28153),
(154931, 'frFR', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s affronte |cFFFF0000$n|r et prépare une |cFFFF0000|Hspell:268403|h[Bourrasque tranchante]|h|r !', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s s\’apprête à se propulser vers |cFFFF0000$n|r d\’un |cFFFF0000|Hspell:268932|h[Bond sismique]|h|r !', 28153),
(154930, 'frFR', 'Au moins je serai mort… les deux pieds… au sol.', '', 28153),
(154929, 'frFR', 'Joli lancer ! Vous avez toute mon attention.', '', 28153),
(154928, 'frFR', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s s\’est fait |cFFFF0000|Hspell:267702|h[Enfermer]|h|r ! Repérez des signes de lutte pour découvrir où !', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t%s s\’est fait |cFFFF0000|Hspell:267702|h[Enfermer]|h|r ! Repérez des signes de lutte pour découvrir où !', 28153),
(154927, 'frFR', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Vous vous êtes fait piéger dans une tombe ! Tentez de vous |cFFFF0000|Hspell:267764|h[Débattre]|h|r pour indiquer laquelle à vos compagnons !', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Vous vous êtes fait piéger dans une tombe ! Tentez de vous |cFFFF0000|Hspell:267764|h[Débattre]|h|r pour indiquer laquelle à vos compagnons !', 28153),
(154926, 'frFR', 'Nous devons vite retourner au sanctuaire des Dévoués et empêcher le général Jakra\’zet de libérer Mythrax !', '', 28153),
(154925, 'frFR', 'Sombre inconscient ! Mythrax est incontrôlable !', '', 28153),
(154924, 'frFR', 'Il va libérer Mythrax et, ensemble, nous conquerrons tout Azeroth !', '', 28153),
(154923, 'frFR', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s attaque |cFFFF0000$n|r et se prépare à l\’|cFFFF0000|Hspell:267702|h[Enfermer]|h|r !', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s attaque |cFFFF0000$n|r et se prépare à l\’|cFFFF0000|Hspell:267702|h[Enfermer]|h|r !', 28153),
(154922, 'frFR', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s s\’apprête à se propulser vers |cFFFF0000$n|r d\’un |cFFFF0000|Hspell:268932|h[Bond sismique]|h|r !', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s s\’apprête à se propulser vers |cFFFF0000$n|r d\’un |cFFFF0000|Hspell:268932|h[Bond sismique]|h|r !', 28153),
(154921, 'frFR', 'Rhaaah ! Korphek, sors de ton trou et viens répondre de tes crimes !', '', 28153),
(154920, 'frFR', '', 'Je suis ici en observatrice. Nous autres Zandalari, nous nous intéressons de près à ces Réprouvés.', 28153),
(154919, 'frFR', '', 'Tout le plaisir est pour moi, Flétrisseur.', 28153),
(154918, 'frFR', '', 'Je vais tenter de découvrir pourquoi la route est fermée. Essayez de convaincre les soldats de nous laisser passer !', 28153),
(154917, 'frFR', 'Bougez-vous, bande de moules. On a d\’autres chats à fouetter.', 'Bougez-vous, bande de moules. On a d\’autres chats à fouetter.', 28153),
(154916, 'frFR', 'Fichez le camp !', 'Fichez le camp !', 28153),
(154915, 'frFR', 'Hors de ma vue.', 'Hors de ma vue.', 28153),
(154914, 'frFR', 'Je vous ai laissé gagner.', 'Je vous ai laissé gagner.', 28153),
(154913, 'frFR', 'J\’en avais plus qu\’assez de vous.', 'J\’en avais plus qu\’assez de vous.', 28153),
(154912, 'frFR', '', 'Ne cherchez pas la petite bête ! Je trouverai bien une solution !', 28153),
(154911, 'frFR', '', 'Tout a un prix, et ces scarabouhs vont me rapporter une petite fortune... à condition que je les rapporte en Kalimdor !', 28153),
(154910, 'frFR', '', 'Ils ont besoin de sang pour survivre. Vous comptez les nourrir comment ?', 28153),
(154909, 'frFR', '', 'À quoi bon entasser de la vermine dans une boîte ?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'frFR', 'Rouvrez immédiatement ce col.', 'Rouvrez immédiatement ce col.', 28153),
(154907, 'frFR', 'Je vois que l\’âge n\’a fait qu\’affûter ta sagesse et ta férocité, Rakjan. Nous allons châtier ces infidèles pour la façon dont ils vous ont traités, toi et tes semblables.', '', 28153),
(154906, 'frFR', 'Faudra me passer sur le corps si vous voulez entrer.', 'Faudra me passer sur le corps si vous voulez entrer.', 28153),
(154905, 'frFR', 'Vous avez les oreilles bouchées, ou quoi ? L\’accès à la vallée est fermé.', 'Vous avez les oreilles bouchées, ou quoi ? L\’accès à la vallée est fermé.', 28153),
(154904, 'frFR', 'Un masque à gaz et une bonbonne de peste, s\’il vous plaît. Voyons un peu ce qu\’on peut faire avec ça.', 'Un masque à gaz et une bonbonne de peste, s\’il vous plaît. Voyons un peu ce qu\’on peut faire avec ça.', 28153),
(154903, 'frFR', 'Juste un masque à gaz, s\’il vous plaît.', 'Juste un masque à gaz, s\’il vous plaît.', 28153),
(154902, 'frFR', 'Faites la queue si vous ne voulez pas d\’ennuis, marin d\’eau douce.', 'Faites la queue si vous ne voulez pas d\’ennuis, marin d\’eau douce.', 28153),
(154901, 'frFR', 'Personne ne passe sans autorisation écrite. C\’est le règlement.', 'Personne ne passe sans autorisation écrite. C\’est le règlement.', 28153),
(154899, 'frFR', 'Entre la force d\’Ai\’twen, ma stratégie audacieuse et votre détermination inflexible, notre victoire est assurée.', '', 28153),
(154898, 'frFR', 'Pour ma part, je vais me rendre au sommet de la montagne et m\’assurer que Rakjan ne m\’a pas oublié après tant d\’années.', '', 28153),
(154897, 'frFR', '', 'Je me reposerai dès que les blessés auront cessé d\’affluer.', 28153),
(154896, 'frFR', '', 'Ça ira. Les marins ont besoin de moi.', 28153),
(154895, 'frFR', 'À ce rythme, vous aurez bientôt b\’soin d\’un guérisseur, vous aussi. Une fois alitée, vous n\’aiderez plus personne.', '', 28153),
(154894, 'frFR', 'Vous m\’avez l\’air épuisée, Féoréa. Vous devriez vous reposer.', '', 28153),
(154893, 'frFR', 'Prenez mon bâton et chargez-le en drainant la puissance des flèches incapacitantes des infidèles.', '', 28153),
(154892, 'frFR', 'Ai\’twen et moi vous attendrons près du champ de mines de la KapitalRisk.', '', 28153),
(154891, 'frFR', 'Maman ! Meera et $p nous ont sauvés !', 'Maman ! Meera et $p nous ont sauvés !', 28153),
(154890, 'frFR', 'Je t\’avais bien dit que Meera nous laisserait pas tomber ! C\’est la meilleure !', 'Je t\’avais bien dit que Meera nous laisserait pas tomber ! C\’est la meilleure !', 28153),
(154889, 'frFR', '', 'Kiro ! Quel bonheur de te revoir ! C\’était effrayant ? Comment tu as eu ce krolusk ? Il a un nom ? Je peux lui en donner un ? Est-ce qu\’il est gentil ?', 28153),
(154888, 'frFR', 'Je te raconterai tout plus tard, Meera. Nous devons d\’abord mettre les nôtres en sécurité.', '', 28153),
(154887, 'frFR', 'C\’était… amusant, je dois l\’admettre !', '', 28153),
(154886, 'frFR', 'Montez sur ce krolusk et filons d\’ici avant que les infidèles envoient des renforts !', '', 28153),
(154885, 'frFR', '', 'Qu\’est-ce qui se passe en bas ? Trombecœur, descends !', 28153),
(154884, 'frFR', '', 'Nous allons commencer nos recherches à Brennadam. Faute de mieux, nous devrions y trouver ce fameux frère Pike.', 28153),
(154883, 'frFR', '', 'Outre sa maison, le seigneur Chantorage régit pour ainsi dire toute la vallée. C\’est lui que nous devons convaincre, mais il n\’est pas venu à Boralus depuis des mois.', 28153),
(154882, 'frFR', '', 'Pour cela, nous devons remettre la maison Chantorage dans le rang. Elle contrôle les eaugures… qui contrôlent la flotte.', 28153),
(154881, 'frFR', '', 'Tremblez face à la bannière des Vulpérins, vermine d\’infidèles !', 28153),
(154880, 'frFR', 'Vous aurez besoin d\’un masque à gaz pour survivre à la peste. Et prenez aussi une bonbonne de peste pour filer un coup de main.', 'Vous aurez besoin d\’un masque à gaz pour survivre à la peste. Et prenez aussi une bonbonne de peste pour filer un coup de main.', 28153),
(154879, 'frFR', '', 'Kul Tiras ne sera guère d\’une grande aide pour l\’Alliance tant que la flotte ne sera pas revenue.', 28153),
(154878, 'frFR', '', 'Et les nôtres qui sont enchaînés là en bas sauront que nous ne les avons pas abandonnés.', 28153),
(154877, 'frFR', '', 'Tant mieux. Ils pourront mettre un visage sur leurs meurtriers.', 28153),
(154876, 'frFR', 'C\’est risqué, Nisha. Les infidèles vont nous repérer si nous restons là.', '', 28153),
(154875, 'frFR', 'Beau travail. Cette liche attaquait nos éclaireurs avec ses troupes. Désormais, nous devrions pouvoir nous concentrer sur la Horde.', '', 28153),
(154874, 'frFR', 'Drustvar a ses sorcières et, apparemment, Nazmir a ses liches. Débarrassez-nous de cette armée de démons et de sa source de puissance.', '', 28153),
(154873, 'frFR', '', 'Nisha sera heureuse de vous voir ! Elle tue des Sephraks dans le cratère… comme à son habitude.', 28153),
(154872, 'frFR', 'Impressionnant, même si j\’ai appris que les Gnomes refusent de manipuler la technologie gobeline. Au moins, nous savons de quoi cette machine est capable.', '', 28153),
(154871, 'frFR', 'Nos troupes ont capturé une machine expérimentale gobeline. Testez-la sur l\’armée de Trolls de sang à proximité pour nous donner un aperçu de sa puissance.', '', 28153),
(154870, 'frFR', 'J\’ai le sentiment que les Nagas manigancent autre chose. Gardez l\’œil ouvert.', '', 28153),
(154869, 'frFR', 'Des Nagas ! Ils sèment la terreur depuis trop longtemps. Mettez un terme à leurs agissements.', '', 28153),
(154866, 'frFR', 'Je n\’ai jamais vu une telle hargne chez un soldat depuis la Troisième guerre. Beau combat.', '', 28153),
(154864, 'frFR', 'Vous avez livré un beau combat contre la Horde. Le peuple de Kul Tiras entendra parler de votre bravoure.', '', 28153),
(154863, 'frFR', 'Excellent travail. Espérons que ce conflit ait une fin plus heureuse que la Deuxième guerre.', '', 28153),
(154861, 'frFR', '', 'Les enfants sont retenus dans le cratère en bas. Faites attention à vous !', 28153),
(154859, 'frFR', 'Bien joué ! La Horde, personne peut l\’arrêter !', '', 28153),
(154858, 'frFR', 'La Horde a massacré plusieurs de nos éclaireurs dans la zone. Mettez un terme à ses agissements.', '', 28153),
(154857, 'frFR', 'Bien joué ! Je crois que vous auriez deux ou trois trucs à m\’apprendre.', '', 28153),
(154856, 'frFR', 'Un ennemi de moins. Bientôt, un autre prendra sa place. Mais pour le moment, vous avez mérité un peu de repos.', '', 28153),
(154855, 'frFR', '', 'Je vais appeler Trombecœur. Il y a un perchoir sur le quai est, où elle pourra nous retrouver.', 28153),
(154854, 'frFR', 'Ah, victoire ! Ça fait plaisir !', '', 28153),
(154853, 'frFR', 'Pendant la Troisième guerre, j\’ai appris à reconnaître les tactiques de la Horde, et celle-ci nous met gravement en danger. Arrêtez-les.', '', 28153),
(154852, 'frFR', 'Ha ha ! Il savait pas à qui il avait affaire, pas vrai ?', '', 28153),
(154851, 'frFR', 'Les opérations de la Horde à proximité me rappellent leurs manœuvres pendant la Deuxième guerre. Nous devons les arrêter avant qu\’ils réussissent.', '', 28153),
(154850, 'frFR', 'Ça, c\’est impressionnant !', '', 28153),
(154848, 'frFR', 'Il y a une âme puissante dans le coin, abattez-la !', '', 28153),
(154846, 'frFR', 'Un ennemi se cache pas loin. Tuons-le !', '', 28153),
(154845, 'frFR', 'Au nom de la 7e Légion, je tiens à vous remercier pour vos efforts contre la Horde.', '', 28153),
(154843, 'frFR', 'La défaite de la Horde va permettre l\’avancée de la 7e Légion. Beau travail !', '', 28153),
(154842, 'frFR', 'Le roi Anduin entendra parler de vos faits d\’armes contre la Horde.', '', 28153),
(154838, 'frFR', 'Les rapports de mes éclaireurs indiquent que la Horde se dirige vers vous. C\’est l\’occasion de tendre une embuscade !', '', 28153),
(154836, 'frFR', 'D\’après nos rapports, un gros contingent de la Horde se forme non loin. C\’est notre chance de frapper !', '', 28153),
(154833, 'frFR', 'Une cible est à proximité, frappez vite !', '', 28153),
(154832, 'frFR', 'La 7e Légion a découvert que les troupes de la Horde s\’activent dans la zone. Arrêtez-les et mettez fin à leur opération !', '', 28153),
(154831, 'frFR', 'Il y a encore une menace qui rôde. Vous savez quoi faire.', '', 28153),
(154830, 'frFR', 'Les esprits, ils me disent qu\’il y a une puissante menace par ici. Faut qu\’on l\’élimine avant qu\’elle pose problème.', '', 28153),
(154829, 'frFR', 'Une menace puissante rôde dans le coin. Éliminez-la !', '', 28153),
(154828, 'frFR', 'Beau travail ! Avez-vous déjà envisagé de rejoindre la 7e Légion de façon permanente ? Votre aide nous serait précieuse !', '', 28153),
(154827, 'frFR', 'Excellent travail. Pour le roi Anduin ! Pour l\’Alliance !', '', 28153),
(154826, 'frFR', 'Vous avez rendu un fier service à la 7e Légion et à l\’Alliance, aujourd\’hui.', '', 28153),
(154825, 'frFR', 'Avec mes remerciements et ceux de tous les soldats de la 7e Légion.', '', 28153),
(154824, 'frFR', 'Je m\’assurerai que le roi Anduin ait vent de votre bravoure.', '', 28153),
(154823, 'frFR', 'Nos éclaireurs ont signalé un puissant ennemi qui rôde près de votre position. Abattez-le.', '', 28153),
(154822, 'frFR', 'La 7e Légion a reçu l\’ordre d\’éliminer une cible proche de votre position.', '', 28153),
(154821, 'frFR', 'Ils devraient être plus prudents. Nous ne serons pas toujours là pour les aider. Merci à vous.', '', 28153),
(154820, 'frFR', 'Les Morts-vivants ont pris une équipe de géomètres au piège ! Aidez-les avant qu\’il ne soit trop tard !', '', 28153),
(154819, 'frFR', 'On se charge de la suite. Il est temps d\’anéantir G\’huun.', '', 28153),
(154818, 'frFR', 'Alors comme ça, c\’est un cadavre ambulant ? On n\’a qu\’à le renvoyer six pieds sous terre.', '', 28153),
(154817, 'frFR', 'Ce Troll est la malveillance incarnée. Que manigance-t-il encore ?', '', 28153),
(154816, 'frFR', '…', '', 28153),
(154815, 'frFR', '…', '', 28153),
(154814, 'frFR', '…', '', 28153),
(154813, 'frFR', '…', '', 28153),
(154812, 'frFR', '…', '', 28153),
(154811, 'frFR', '…', '', 28153),
(154810, 'frFR', '…', '', 28153),
(154809, 'frFR', '…', '', 28153),
(154808, 'frFR', 'Vous en avez oublié un !', '', 28153),
(154807, 'frFR', '', 'De nombreuses expériences ont été menées sur diverses formes de vie pour trouver une solution à la corruption du Dieu très ancien.', 28153),
(154806, 'frFR', 'Bon sang d\’bois ! Qu\’est-ce que c\’est que ce machin ?!', '', 28153),
(154805, 'frFR', '…', '', 28153),
(154804, 'frFR', 'J\’avais déjà entendu des histoires sur les serviteurs de N\’zoth, mais je m\’attendais pas du tout à en voir un en vrai. J\’espère que c\’était une dernière.', '', 28153),
(154803, 'frFR', 'C\’est pas passé loin. Si cette chose nous avait vaincus, qui sait combien auraient été infectés à la surface.', '', 28153),
(154802, 'frFR', 'J\’approuve ce plan. Et tant que j\’y suis, j\’essaierai de découvrir d\’autres secrets que les Titans pourraient avoir laissés ici.', '', 28153),
(154801, 'frFR', '…', '', 28153),
(154800, 'frFR', 'Rhah ! On ne peut pas attendre aussi longtemps. Le mieux, c\’est de se débarrasser de G\’huun avant que tout ça dégénère.', '', 28153),
(154799, 'frFR', 'Et vous l\’avez trouvée, cette réponse ?', '', 28153),
(154798, 'frFR', 'Ah, ça explique pourquoi les Trolls de sang traînent dans les parages, mais pas pourquoi les Titans garderaient en vie un Dieu très ancien.', '', 28153),
(154797, 'frFR', 'Bon sang, que je suis content de vous voir. Pour autant que je sache, on se trouve dans un genre de laboratoire de recherche.', '', 28153),
(154796, 'frFR', 'Ouais ! On a réussi ! Cette technologie n\’est pas si complexe quand on a le coup de main.', '', 28153),
(154795, 'frFR', 'Pour la douzième fois !', '', 28153),
(154794, 'frFR', 'Quoi ?! Non ! Ces fichues portes sont scellées ! Tapez dans tout ce que vous pouvez jusqu\’à ce que ça s\’ouvre !', '', 28153),
(154793, 'frFR', 'Encore un instant. Je vais ouvrir ces portes.', '', 28153),
(154792, 'frFR', 'Vous avez réussi ! Donnez-moi une seconde. J\’ai accès à une sorte de gardien qui semble gérer cette installation.', '', 28153),
(154791, 'frFR', 'J\’ai atteint le rang Légende.', '', 28153),
(154789, 'frFR', 'La bataille fait rage. Poursuivez le combat contre nos ennemis !', '', 28153),
(154788, 'frFR', 'Une cible importante a été repérée près d\’ici. Vous devez l\’anéantir immédiatement.', '', 28153),
(154787, 'frFR', 'Un ennemi puissant rôde dans les environs. Éliminez-le. Soyez sans pitié !', '', 28153),
(154780, 'frFR', 'Prêt pour la bagarre.', 'Prête pour la bagarre.', 28153),
(154779, 'frFR', '', 'Torcanata ! Ha ! Ha !', 28153),
(154777, 'frFR', '', 'Aujourd\’hui, c\’est le jour de la Torcanata ! Si vous voulez participer, prenez une torche et préparez-vous à courir.', 28153),
(154774, 'frFR', '', 'Héraut, vous devriez bientôt gagner la confiance des Zandalari, continuez ainsi. Le devoir m\’appelle. Bonne chance.', 28153),
(154772, 'frFR', '', 'Oculeth, voyez ce que vous pouvez faire. Il nous faudra établir des lignes de soutien vers les capitales de la Horde.', 28153),
(154770, 'frFR', 'Retrouvez-moi dès que possible à la chute de Bwoljin, $p. Nous nous glisserons ensemble dans la forteresse de Korphek.', '', 28153),
(154769, 'frFR', '', 'La princesse Talanji a eu l\’amabilité de nous indiquer un ancien réseau de portails que nous pourrions réactiver.', 28153),
(154768, 'frFR', '', 'Venez me parler quand vous voudrez porter le coup final à la flotte de Corsandre.', 28153),
(154767, 'frFR', '', 'Excellent travail, héros, mais Boralus est loin d\’être hors de danger.', 28153),
(154766, 'frFR', 'Reprenez votre travail. Je les accompagne.', 'Reprenez votre travail. Je les accompagne.', 28153),
(154765, 'frFR', 'Les étrangers ne sont pas admis dans les archives, mon frère.', 'Les étrangers ne sont pas admis dans les archives, mon frère.', 28153),
(154764, 'frFR', 'J\’étais là, sur la plage, cerné par ces saletés de Gloubelins, quand soudain... une aide providentielle est arrivée ! Oh, vous revoilà, $n !', '', 28153),
(154763, 'frFR', 'Trouvez les parchemins ! Je vais regagner le camp par... la route touristique, et je dirai à tous ce que vous avez découvert.', '', 28153),
(154762, 'frFR', 'Quoi qu\’elle nous envoie, l\’Alliance ne goûtera qu\’à la défaite.', '', 28153),
(154761, 'frFR', 'Des champions de l\’Alliance viennent au secours de la ville. Réduisez leurs efforts à néant.', '', 28153),
(154760, 'frFR', 'Ces munitions nous permettront de semer le chaos dans les rangs de l\’Alliance.', '', 28153),
(154759, 'frFR', 'Les troupes de Corsandre attaquent la ville avec des armes alimentées en azérite. Récupérez-les pour la Horde !', '', 28153),
(154758, 'frFR', 'Privés de leurs officiers, les Kultirassiens sombreront dans les flots.', '', 28153),
(154757, 'frFR', 'Un officier kultirassien tente de rallier des troupes. Éradiquez-les du champ de bataille.', '', 28153),
(154756, 'frFR', '', 'Beau travail. Vous avez prouvé à la Horde qu\’aucun ennemi ne peut prendre Boralus !', 28153),
(154755, 'frFR', '', 'On dirait que la Horde profite du siège pour mettre Boralus à sac ! Mettez un terme à leurs méfaits !', 28153),
(154754, 'frFR', '', 'Bien joué. Vous avez montré aux Corsandre qu\’il faut plus que des muscles pour se frotter à vous !', 28153),
(154753, 'frFR', '', 'Un mercenaire de Corsandre sème le chaos dans la ville. Arrêtez-le !', 28153),
(154752, 'frFR', '', 'Bien joué. Les seuls qui méritent les fers sont ces forbans.', 28153),
(154751, 'frFR', '', 'Les pirates enlèvent des civils pour en faire leurs esclaves ! Arrêtez-les !', 28153),
(154750, 'frFR', 'Gorak Tul… arrive…', '', 28153),
(154749, 'frFR', 'Tous souffriront, à commencer par vous !', '', 28153),
(154748, 'frFR', 'Imbécile ! Votre mort sera un supplice !', '', 28153),
(154747, 'frFR', 'Oou ph\’magg an\’qov nuq.', '', 28153),
(154746, 'frFR', 'Ywaq ongg uul\’gwa no AN\’zig !', '', 28153),
(154745, 'frFR', 'Arwi ryiu yrr oou qam !', '', 28153),
(154744, 'frFR', 'AN\’zig wgah qam za zyqtahg…', '', 28153),
(154743, 'frFR', 'AN\’zig wgah zzof !', '', 28153),
(154742, 'frFR', 'Ywaq fhssh wgah qam !', '', 28153),
(154741, 'frFR', 'Uulg\’ma zyqtahg yrr !', '', 28153),
(154740, 'frFR', 'Hnakf ywaq shuul\’wah yawifk yrr uull zz thyzz !', '', 28153),
(154739, 'frFR', 'À présent, partez, pendant qu\’il en est encore temps ! Les autres doivent se douter de quelque chose.', 'À présent, partez, pendant qu\’il en est encore temps ! Les autres doivent se douter de quelque chose.', 28153),
(154738, 'frFR', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Vous êtes la cible de |cFFFF0000|Hspell:260838|h[Coup de foreuse]|h|r !', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Vous êtes la cible de |cFFFF0000|Hspell:260838|h[Coup de foreuse]|h|r !', 28153),
(154737, 'frFR', 'Og qam shfk wgah iiqaah halahs ma !', '', 28153),
(154736, 'frFR', 'Allez trouver frère Pike à Brennadam. Remettez-lui ce pendentif. Notre travail ne fait que commencer et il aura besoin de votre aide.', 'Allez trouver frère Pike à Brennadam. Remettez-lui ce pendentif. Notre travail ne fait que commencer et il aura besoin de votre aide.', 28153),
(154735, 'frFR', 'Maq oou kaaxth zz ak\’uq yrr sk\’yahf ma !', '', 28153),
(154734, 'frFR', 'Notre peuple a emprunté la voie des ténèbres. Mais certains d\’entre nous ont semé les graines de la résistance.', 'Notre peuple a emprunté la voie des ténèbres. Mais certains d\’entre nous ont semé les graines de la résistance.', 28153),
(154733, 'frFR', 'Zuq ag\’xig ka\’ar za wgah !', '', 28153),
(154732, 'frFR', 'Puul qi\’plahf ni oou bormax !', '', 28153),
(154731, 'frFR', 'Xith wgah !', '', 28153),
(154729, 'frFR', 'Naz raqul !', '', 28153),
(154728, 'frFR', 'I wgah far\’al zuq ni shn !', '', 28153),
(154727, 'frFR', 'La flotte n\’est pas perdue. Elle est prisonnière d\’une tempête surnaturelle.', 'La flotte n\’est pas perdue. Elle est prisonnière d\’une tempête surnaturelle.', 28153),
(154726, 'frFR', 'Zuq wgah qam n\’lyeth !', '', 28153),
(154725, 'frFR', 'Zuq ag\’xig gag wgah naggwa\’fssh !', '', 28153),
(154724, 'frFR', 'Zuq ag\’xig bormax oou iiqitaath !', '', 28153),
(154723, 'frFR', 'Tout va bien ? J\’aurais dû me douter que Wade était, elle aussi, corrompue par les ténèbres qui ont emporté la maison Chantorage.', 'Tout va bien ? J\’aurais dû me douter que Wade était, elle aussi, corrompue par les ténèbres qui ont emporté la maison Chantorage.', 28153),
(154722, 'frFR', '', 'Quel danger ?', 28153),
(154721, 'frFR', 'Oui, mon frère.', 'Oui, mon frère.', 28153),
(154720, 'frFR', 'N\’acceptez aucun visiteur. J\’ai des $Uinvités:invitées;.', 'N\’acceptez aucun visiteur. J\’ai des $Uinvités:invitées;.', 28153),
(154719, 'frFR', 'Vous n\’avez pas idée du danger auquel vous faites face.', '', 28153),
(154718, 'frFR', 'Suivez-moi. Les yeux baissés.', '', 28153),
(154717, 'frFR', 'Nos fortifications sont encore fragiles. Vite, arrêtez la Horde avant qu\’elle approche !', '', 28153),
(154716, 'frFR', 'Stromgarde est encore faible et ne survivra pas à une charge frontale. Écrasez l\’avant-garde de la Horde avant qu\’elle approche !', '', 28153),
(154715, 'frFR', 'Ah ! Voilà une belle preuve de respect envers Pa\’ku !', '', 28153),
(154714, 'frFR', 'Envoyez nos troupes ! Il faut écraser ces insectes de l\’Alliance avant qu\’ils puissent se disperser !', '', 28153),
(154713, 'frFR', '', 'On y est ! Montez les marches de Zanchul et rendez hommage à notre Loa. Avec sa faveur, Zandalar perdurera ! Faites honneur à Gonk !', 28153),
(154712, 'frFR', '', 'Déployez les démolisseurs ! Pas question de laisser l\’Alliance établir une tête de pont !', 28153),
(154711, 'frFR', 'Aux armes ! Le combat nous appelle !', '', 28153),
(154710, 'frFR', 'Envoyez nos troupes ! Les murs de Stromgarde crouleront sous la puissance de la Horde !', '', 28153),
(154709, 'frFR', 'Le bastion a besoin de renforts. Repoussez les troupes avant qu\’elles soient trop près !', '', 28153),
(154708, 'frFR', 'Ne traînez pas. Le seigneur Chantorage a besoin de ces cartes au sanctuaire des Tempêtes au plus vite !', '', 28153),
(154707, 'frFR', 'Envoyez nos troupes ! On va réduire leur base miteuse en ruines.', '', 28153),
(154706, 'frFR', '', 'Les bibliothèques des eaugures sont parmi les plus fournies au monde. Je parie qu\’on y trouvera notre archiviste.', 28153),
(154705, 'frFR', '', 'L\’Alliance se dirige vers Ar\’gorok ! Nous devons la mettre en déroute avant qu\’elle atteigne le bastion !', 28153),
(154704, 'frFR', 'Soldats de l\’Alliance ! Terrassez-les !', '', 28153),
(154703, 'frFR', 'Soldats de la ligue, chargez !', '', 28153),
(154702, 'frFR', 'Horde, au combat ! Écrasez ces lâches avant qu\’ils ne détruisent nos portes !', '', 28153),
(154701, 'frFR', '', 'Le canon ! Le canon !', 28153),
(154700, 'frFR', 'Le canon ! Le canon !', '', 28153),
(154699, 'frFR', '', 'Ça ne me dit rien qui vaille. Partons d\’ici.', 28153),
(154698, 'frFR', 'Allez rejoindre cet imbécile d\’Alen aux archives, ou je me sers de vous pour stabiliser la faille !', '', 28153),
(154697, 'frFR', 'Redoublez d\’efforts, imbéciles, sinon on perdra le contrôle !', '', 28153),
(154696, 'frFR', '', 'Très bien. On va faire ça !', 28153),
(154695, 'frFR', '', 'Si vous avez du temps à perdre, allez plutôt importuner Alen.', 28153),
(154694, 'frFR', '', 'Livrez vos âmes aux marées. Leurs murmures révèlent la vérité !', 28153),
(154693, 'frFR', 'Plantation de graines', 'Plantation de graines', 28153),
(154692, 'frFR', '', 'Gilnéens, chargez vos canons ! En avant !', 28153),
(154691, 'frFR', 'Mesdames et messieurs, faites rugir les moteurs ! À l\’attaque !', '', 28153),
(154690, 'frFR', 'Fusiliers ! Préparez-vous à tirer ! En avant !', 'Fusiliers ! Préparez-vous à tirer ! En avant !', 28153),
(154689, 'frFR', '', 'On peut assurer la sécurité de votre navire, si vous y mettez le prix.', 28153),
(154688, 'frFR', '', 'Quelle tragédie… On devrait peut-être arrêter de célébrer les mariages ici.', 28153),
(154687, 'frFR', '', 'Les réjouissances ont tourné au cauchemar ! Éliminez les monstres responsables de tout ça et sauvez les invités !', 28153),
(154686, 'frFR', '', 'J\’imagine que ça veut dire non ?', 28153),
(154685, 'frFR', '', 'Vous m\’insupportez presque autant que Frère Alen.', 28153),
(154684, 'frFR', '', 'Vous là, qui commande ici ?', 28153),
(154683, 'frFR', 'Umpf.', 'Umpf.', 28153),
(154682, 'frFR', 'Faites s\’épancher vos plaies purulentes et chantez de douleur !', '', 28153),
(154681, 'frFR', 'Ne tournez pas le dos à la folie ! Basculez dedans !', '', 28153),
(154680, 'frFR', 'Appréhendez la beauté de la décomposition et étreignez-la !', '', 28153),
(154679, 'frFR', 'Je vous réduirai en cendres !', '', 28153),
(154678, 'frFR', 'Xalzaix a soif d\’annihilation !', '', 28153),
(154677, 'frFR', 'Vous ne survivrez pas !', '', 28153),
(154676, 'frFR', 'Vous n\’échapperez pas à la destruction !', '', 28153),
(154675, 'frFR', 'Vous ne pouvez pas échapper aux ombres !', '', 28153),
(154674, 'frFR', 'Extermination !', '', 28153),
(154673, 'frFR', 'Anéantissement !', '', 28153),
(154672, 'frFR', 'Vous ne pouvez résister à mon appel.', '', 28153),
(154671, 'frFR', 'Abandonnez-vous à la peste !', '', 28153),
(154670, 'frFR', 'Nul ne peut arrêter G\’huun…', '', 28153),
(154669, 'frFR', 'La pourriture n\’épargne rien.', '', 28153),
(154668, 'frFR', 'Votre carcasse appartient à G\’huun.', '', 28153),
(154667, 'frFR', 'Un terrain fertile pour la pourriture !', '', 28153),
(154666, 'frFR', 'G\’huun s\’élèvera !', '', 28153),
(154665, 'frFR', 'Votre monde disparaîtra !', '', 28153),
(154664, 'frFR', 'Votre déliquescence est inévitable.', '', 28153),
(154663, 'frFR', 'Ce serrement dans votre gorge. Cette arrière-pensée dans votre esprit. J\’ai toujours été en vous.', '', 28153),
(154662, 'frFR', 'Toute vie se flétrit. Acceptez cela et soyez transfigurés.', '', 28153),
(154661, 'frFR', '', 'Propulseur de réorigination réactivé. Accès à la chambre autorisé.', 28153),
(154660, 'frFR', '', 'Console activée. Redémarrage des protections du complexe.', 28153),
(154659, 'frFR', 'Euh ! Encore une chose. Deux, même.', '', 28153),
(154658, 'frFR', '', 'Première console activée. Rétablissement de la matrice énergétique.', 28153),
(154657, 'frFR', '', 'Spécimen G\’huun éliminé. Aucun échantillon de tissu viable ne subsiste.', 28153),
(154656, 'frFR', '', 'Chute de la corruption sous le seuil d\’alerte. Intégrité du système rétablie.', 28153),
(154655, 'frFR', 'Enfin, quand la planète entière explosera tel un gigantesque abcès, l\’infection se répandra à travers le cosmos.', '', 28153),
(154654, 'frFR', 'Vous colporterez ma pestilence et un vaste kyste recouvrira le monde de sa purulence.', '', 28153),
(154653, 'frFR', 'Quels hôtes zélés vous faites. Vous serez les premiers à recevoir mon don.', '', 28153),
(154652, 'frFR', 'Les sceaux brisés, les Titans absents. L\’ère de la pourriture peut commencer.', '', 28153),
(154651, 'frFR', '', 'Ça, c\’était pour la destruction de Dazar\’alor, vile créature !', 28153),
(154650, 'frFR', '', 'Nous nous chargerons du reste. Nous allons en finir avec G\’huun et sa corruption.', 28153),
(154649, 'frFR', '', 'Attention, risque accru de contamination au-delà de ce point. Le protocole de quarantaine m\’empêche de poursuivre.', 28153),
(154648, 'frFR', 'Parfait, $p ! Nous avons largement assez de mines pour frapper un coup décisif contre la KapitalRisk.', '', 28153),
(154647, 'frFR', '', 'Peu importe comment il est revenu. Mon couteau va le renvoyer dans l\’abîme.', 28153),
(154646, 'frFR', 'Ce ne sont pas les mines qui manquent par ici.', '', 28153),
(154645, 'frFR', '', 'L\’analyse indique un haut degré de corruption. Hypothèse : G\’huun a réanimé ce spécimen et l\’a amélioré. Tests supplémentaires requis.', 28153),
(154644, 'frFR', '', 'Zul ? Comment peut-il être en vie ? Je l\’ai vu mourir de la main de mon père !', 28153),
(154643, 'frFR', 'Ces mines n\’ont pas été conçues pour détecter les tortues ! Nous pouvons les récupérer sans risque.', '', 28153),
(154642, 'frFR', '', 'Apparemment, vous en avez oublié un.', 28153),
(154641, 'frFR', '', 'Les tests concernaient la capacité de la corruption de G\’huun à réanimer des tissus morts. Les résultats des recherches n\’étant pas concluants, les spécimens furent détruits.', 28153),
(154640, 'frFR', '', 'Observation correcte. Cette installation a abrité de nombreuses expériences sur les Loas afin de trouver une solution à la corruption du Dieu très ancien.', 28153),
(154639, 'frFR', '', 'Quelle est cette créature ?! On dirait que c\’était un Loa autrefois.', 28153),
(154638, 'frFR', '', 'Si cette chose était l\’un des serviteurs de G\’huun, nous devons l\’arrêter avant qu\’une armée de ces créatures atteigne la surface.', 28153),
(154637, 'frFR', '', 'Erreur. Dysfonctionnement du disque. Flux de données corrompues déployé.', 28153),
(154636, 'frFR', '', 'Séquence de démarrage lancée.', 28153),
(154635, 'frFR', '', 'Veuillez vous rendre au bloc opératoire pour une extraction neurale et le prélèvement du tissu cérébral.', 28153),
(154634, 'frFR', '', 'L\’analyse des cortex cérébraux indique que tous les individus présents ont déjà eu des interactions avec des spécimens des Dieux très anciens.', 28153),
(154633, 'frFR', '', 'Toute donnée relative à vos expériences précédentes pourrait faire avancer les recherches effectuées ici.', 28153),
(154632, 'frFR', '', 'L\’analyse des cortex cérébraux indique que certains individus présents ont déjà eu des interactions avec des spécimens des Dieux très anciens.', 28153),
(154631, 'frFR', '', '950 milliards de norgaoctets sont alloués à la musique et aux autoportraits.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'frFR', '', '75 norgaoctets sont consacrés à tous les composants chimiques existants.', 28153),
(154629, 'frFR', '', 'Ces disques contiennent actuellement 50 norgaoctets de données biologiques concernant les formes de vie du cosmos.', 28153),
(154628, 'frFR', '', 'Accès à la chambre des données. Il s\’agit d\’un recueil exhaustif du savoir des Titans.', 28153),
(154627, 'frFR', 'Vous combattez l\’inévitable. Ma peste ne peut être arrêtée. Elle s\’insinue déjà en vous.', '', 28153),
(154626, 'frFR', '', 'Si nous n\’avions pas arrêté cette chose, elle aurait infecté toute forme de vie à la surface.', 28153),
(154625, 'frFR', 'Ah, bienvenue. Les visiteurs se font plutôt rares ces temps-ci, en particulier aux archives.\n\nQue puis-je faire pour vous ?', 'Ah, bienvenue. Les visiteurs se font plutôt rares ces temps-ci, en particulier aux archives.\n\nQue puis-je faire pour vous ?', 28153),
(154624, 'frFR', '', 'Alerte. Brèche du confinement viral. Spécimen contaminé en approche. Risque d\’infection imminent.', 28153),
(154623, 'frFR', '', 'Ce laboratoire renferme des milliers de souches virales parmi les plus dangereuses de tout le cosmos, triées par ordre alphabétique pour un accès simplifié.', 28153),
(154622, 'frFR', '', 'Accès à l\’aile d\’écologie virale.', 28153),
(154621, 'frFR', '', 'Assurez-vous que Mot de pouvoir : Bouclier est actif en permanence pour bénéficier d\’Expiation.', 28153),
(154620, 'frFR', 'Assurez-vous que Mot de pouvoir : Bouclier est actif en permanence pour bénéficier d\’Expiation.', '', 28153),
(154619, 'frFR', '', 'Lancez Mot de pouvoir : Bouclier sur vous-même, puis infligez des dégâts au mannequin d\’entraînement pour soigner vos blessures.', 28153),
(154618, 'frFR', 'Lancez Mot de pouvoir : Bouclier sur vous-même, puis attaquez le mannequin d\’entraînement pour vous soigner.', '', 28153),
(154617, 'frFR', '', 'Lorsque vous infligez des dégâts à un ennemi, tous les porteurs de votre Expiation sont soignés.', 28153),
(154616, 'frFR', 'Lorsque vous infligez des dégâts à un ennemi, tous les porteurs de votre Expiation sont soignés.', '', 28153),
(154615, 'frFR', '', 'Certains sorts, comme Mot de pouvoir : Bouclier, appliquent Expiation sur votre cible.', 28153),
(154614, 'frFR', 'Pouvez-vous me parler de la flotte disparue ?', 'Pouvez-vous me parler de la flotte disparue ?', 28153),
(154613, 'frFR', 'Certains sorts, comme Mot de pouvoir : Bouclier, appliquent Expiation sur votre cible.', '', 28153),
(154612, 'frFR', 'Il faudra convaincre notre chef de guerre. Et pour ça, j\’ai besoin de votre aide. Venez.', '', 28153),
(154611, 'frFR', 'Il est peut-être temps de recouvrer une vieille dette. Ainsi, nous pourrions renforcer les rangs de la Horde avec des soldats loyaux.', '', 28153),
(154610, 'frFR', '$n, je suis persuadé que vous aimez la Horde autant que moi. Mais si nous n\’agissons pas, je crains qu\’elle ne survive pas à cette guerre.', '', 28153),
(154609, 'frFR', '', 'Nous avons un plan : activer les consoles et faire cesser la malfaisance de G\’huun une fois pour toutes.', 28153),
(154608, 'frFR', '', 'L\’activation des consoles donnera accès à la chambre de G\’huun, où le spécimen pourra être purgé en activant le propulseur de réorigination.', 28153),
(154607, 'frFR', '', 'Pour détruire le spécimen, vous devez réactiver les consoles de la chambre de confinement réparties dans cette aile.', 28153),
(154606, 'frFR', '', 'Mais nous n\’avons pas tout ce temps ! Il faut arrêter G\’huun tout de suite !', 28153),
(154605, 'frFR', '', 'Négatif. Données inexploitables. Des protocoles de recherche alternatifs sont en développement et leur mise en œuvre est prévue dans 2 364 cycles.', 28153),
(154604, 'frFR', 'Wouah ! C\’est du brutal !', '', 28153),
(154603, 'frFR', '', 'Et vous l\’avez trouvée, cette réponse ?', 28153),
(154602, 'frFR', 'Et maintenant, la petite étincelle… Vous devriez reculer.', '', 28153),
(154601, 'frFR', 'On peut peut-être exploser la serrure. Versez un peu de poudre dessus.', '', 28153),
(154600, 'frFR', '', 'La collecte de données est cruciale pour combattre les Dieux très anciens. Le métabolisme unique de G\’huun détient potentiellement la réponse qui nous permettra d\’éliminer cette menace.', 28153),
(154599, 'frFR', '', 'Vous avez gardé cette abomination en vie ? Pourquoi ?', 28153),
(154598, 'frFR', '', 'Dénomination : Uldir. Cette station de recherche a été conçue pour confiner et étudier l\’entité appelée G\’huun.', 28153),
(154597, 'frFR', '', 'Quel est cet endroit ?', 28153),
(154596, 'frFR', '', 'Systèmes du centre compromis. Procédez avec précaution.', 28153),
(154595, 'frFR', '', 'Les portes sont verrouillées ! Éteignez vite cette machine… avant qu\’on soit réduits en cendres !', 28153),
(154594, 'frFR', '', 'Alerte. Formes de vie contaminées détectées. Mise en route des incinérateurs.', 28153),
(154593, 'frFR', '', 'Elle a probablement évité la propagation de la corruption dans tout le système.', 28153),
(154592, 'frFR', '', 'Je suis la Damoiselle anti-mal expérimentale. Nom de code : D.A.M.E.', 28153),
(154591, 'frFR', '', 'Pour la Horde !', 28153),
(154590, 'frFR', '', 'C\’était quoi, cette voix ?', 28153),
(154589, 'frFR', '', 'Pour la Horde !', 28153),
(154588, 'frFR', 'Lok-tar ogar ! Pour la Horde !', '', 28153),
(154587, 'frFR', '', 'Spécimen virulent supprimé. Ouverture de la chambre de décontamination.', 28153),
(154586, 'frFR', '', 'J\’accepte votre loyauté, commandant. Votre peuple est le bienvenu au sein d\’Orgrimmar.', 28153),
(154585, 'frFR', '', 'Draenor est tombée, mais Azeroth est maintenant notre foyer. Vos ennemis sont désormais les nôtres !', 28153),
(154584, 'frFR', 'Application de poudre', 'Application de poudre', 28153),
(154583, 'frFR', '', 'Eitrigg et votre héraut ont montré leur courage. C\’est avec fierté que nous combattrons aux côtés de ceux qui incarnent les valeurs de la Horde.', 28153),
(154582, 'frFR', '', 'Taloc a survécu à la frappe du M.E.C.H. ? Nous ne pouvons pas laisser ce monstre se dresser entre G\’huun et nous !', 28153),
(154581, 'frFR', 'Bwonsamdi…', 'Si loin de chez moi…', 28153),
(154580, 'frFR', 'Je comprends que tu sois en colère, mais ce sont de vrais monstres, tu sais. On ne peut pas rester ici.', 'Je comprends que tu sois en colère, mais ce sont de vrais monstres, tu sais. On ne peut pas rester ici.', 28153),
(154578, 'frFR', '', 'L\’honneur est tout pour nous ! Nous ne faisons pas ce serment à la légère, chef de guerre.', 28153),
(154577, 'frFR', 'On pourra toujours commander une autre pièce montée. Allez, il faut partir maintenant.', 'On pourra toujours commander une autre pièce montée. Allez, il faut partir maintenant.', 28153),
(154576, 'frFR', 'Je sais que tu leur en veux, mais on ne peut pas rester, mon cœur.', 'Je sais que tu leur en veux, mais on ne peut pas rester, mon cœur.', 28153),
(154575, 'frFR', 'Mon cœur, il faut y aller.', 'Mon cœur, il faut y aller.', 28153),
(154574, 'frFR', '', 'Eitrigg m\’a parlé de la force de votre peuple. Je crois que l\’honneur signifie autant pour vous que pour lui.', 28153),
(154572, 'frFR', 'Vous avez déchiré la robe de mes rêves ! J\’avais fait venir la soie de Quel\’Thalas ! Le voile était à ma mère ! Comment osez-vous ?', 'Vous avez déchiré la robe de mes rêves ! J\’avais fait venir la soie de Quel\’Thalas ! Le voile était à ma mère ! Comment osez-vous ?', 28153),
(154570, 'frFR', 'Notre mission est un succès, chef de guerre. Le commandant Geya\’rah a mis ses guerriers à disposition de la Horde.', '', 28153),
(154569, 'frFR', 'Vous avez tué le traiteur ! Il n\’avait même pas encore servi les canapés !', 'Vous avez tué le traiteur ! Il n\’avait même pas encore servi les canapés !', 28153),
(154568, 'frFR', 'Mon corps livré aux sables.', 'Enfin, une vraie mort !', 28153),
(154567, 'frFR', 'Vous n\’auriez pas dû gâcher mon mariage ! J\’ignore qui vous êtes, mais je vous garantis que vous allez le regretter amèrement !', 'Vous n\’auriez pas dû gâcher mon mariage ! J\’ignore qui vous êtes, mais je vous garantis que vous allez le regretter amèrement !', 28153),
(154566, 'frFR', 'Avez-vous la moindre idée des sacrifices que j\’ai dû faire pour que tout soit parfait ?', 'Avez-vous la moindre idée des sacrifices que j\’ai dû faire pour que tout soit parfait ?', 28153),
(154565, 'frFR', 'Comment osez-vous gâcher mon mariage ?!', 'Comment osez-vous gâcher mon mariage ?!', 28153),
(154564, 'frFR', 'La fin… tant attendue.', 'Ça peut pas finir… pas comme ça.', 28153),
(154563, 'frFR', 'Ça fait quatre mois que je n\’ai pas touché à une seule miette de pain !', 'Ça fait quatre mois que je n\’ai pas touché à une seule miette de pain !', 28153),
(154562, 'frFR', 'Les sables vont tous nous engloutir.', 'La mort est la seule issue.', 28153),
(154561, 'frFR', 'Vous savez combien m\’a coûté cette pièce montée ?', 'Vous savez combien m\’a coûté cette pièce montée ?', 28153),
(154560, 'frFR', 'J\’ai dû attendre deux ans avant de décrocher une réservation !', 'J\’ai dû attendre deux ans avant de décrocher une réservation ! DEUX ANS !', 28153),
(154559, 'frFR', 'La mort n\’a jamais réussi à m\’arrêter...', '', 28153),
(154558, 'frFR', 'Je pourrais vous tuer rien qu\’en levant le petit doigt !', '', 28153),
(154557, 'frFR', '', 'Une nouvelle matrice de puissance peut être collectée.', 28153),
(154556, 'frFR', '', 'Une matrice de puissance est prête à être récupérée.', 28153),
(154555, 'frFR', '', 'Attention. Une nouvelle matrice de puissance est disponible.', 28153),
(154554, 'frFR', '', 'Attention. Explosion de réorigination imminente. Veuillez évacuer la zone.', 28153),
(154553, 'frFR', '', 'Alerte. Séquence d\’explosion de réorigination initialisée. Veuillez quitter la zone.', 28153),
(154551, 'frFR', 'La Horde est vaincue !', '', 28153),
(154550, 'frFR', 'Vous comprendrez bientôt l\’absurdité de votre résistance !', 'Vous comprendrez bientôt l\’absurdité de votre résistance !', 28153),
(154549, 'frFR', 'Sortez ! Venez faire face à votre destin !', 'Sortez ! Venez faire face à votre destin !', 28153),
(154548, 'frFR', 'Celui qui rôde dans les abysses se fera un manteau de votre peau !', 'Celui qui rôde dans les abysses se fera un manteau de votre peau !', 28153),
(154547, 'frFR', 'Défendez votre pathétique existence ! Les flots infinis finiront tôt ou tard par vous submerger !', 'Défendez votre pathétique existence ! Les flots infinis finiront tôt ou tard par vous submerger !', 28153),
(154546, 'frFR', '', 'Utilisez Pénitence pour soigner vos blessures.', 28153),
(154545, 'frFR', 'Qu\’est-ce que c\’est que cette poudre ? Hé, aidez-moi à en récupérer un peu.', '', 28153),
(154544, 'frFR', 'Utilisez Pénitence pour soigner vos blessures.', '', 28153),
(154543, 'frFR', '', 'Lancer Pénitence sur un allié ou sur vous-même vous soignera au lieu d\’infliger des dégâts.', 28153),
(154542, 'frFR', 'Lancer Pénitence sur un allié ou sur vous-même vous soignera au lieu d\’infliger des dégâts.', '', 28153),
(154541, 'frFR', 'Tuez-moi ces monstres !', 'Tuez-moi ces monstres !', 28153),
(154540, 'frFR', 'Ça devait être un jour mémorable, mais pas de cette façon !', 'Ça devait être un jour mémorable, mais pas de cette façon !', 28153),
(154539, 'frFR', 'Mais enfin, qu\’est-ce qui se passe ? Qui sont ces monstres ?', 'Mais enfin, qu\’est-ce qui se passe ? Qui sont ces monstres ?', 28153),
(154538, 'frFR', 'J\’aurais encore préféré voir mes beaux-parents ronds comme des barriques !', 'J\’aurais encore préféré voir mes beaux-parents ronds comme des barriques !', 28153),
(154537, 'frFR', 'Qu\’est-ce que j\’ai fait pour mériter ça ?!', 'Qu\’est-ce que j\’ai fait pour mériter ça ?!', 28153),
(154536, 'frFR', 'On n\’a même pas eu le temps de faire la danse des Drogbars !', 'On n\’a même pas eu le temps de faire la danse des Drogbars !', 28153),
(154535, 'frFR', 'C\’était censé être le plus beau jour de ma vie !', 'C\’était censé être le plus beau jour de ma vie !', 28153),
(154534, 'frFR', 'Ahhhhhhhhh !', 'Ahhhhhhhhh !', 28153),
(154533, 'frFR', 'Avec votre permission, chef de guerre. Venez, $n.', '', 28153),
(154532, 'frFR', '', 'Nos alliés sacrenuit ont une affinité particulière pour la téléportation. Leur savoir pourrait profiter à votre voyage.', 28153),
(154531, 'frFR', 'Je me suis procuré un fragment de la relique utilisée par Garrosh pour voyager vers ce monde. Je pense pouvoir rouvrir la voie… Mais j\’aurai besoin d\’aide pour y parvenir.', '', 28153),
(154530, 'frFR', '', 'Ce plan présente de nombreux intérêts, mais je croyais que le portail vers cet autre Draenor avait été fermé.', 28153),
(154529, 'frFR', 'Je vais aller voir O\’toiles. J\’aime mon boulot et je tiens à le conserver. Mais pas à n\’importe quelle condition.', '', 28153),
(154528, 'frFR', 'Est-ce que cela veut dire que... Je vois.', '', 28153),
(154527, 'frFR', 'Hum... J\’ai du mal à croire que le capitaine refuse de s\’associer aux Corsandre. Il semblait pourtant bien décidé.', '', 28153),
(154526, 'frFR', '', 'Qu\’en dites-vous, $n ? Souhaitez-vous solliciter un nouvel allié ?', 28153),
(154525, 'frFR', '', 'Les prouesses au combat des Mag\’har sont légendaires. J\’aurai besoin de soldats courageux comme eux dans un avenir proche.', 28153),
(154524, 'frFR', '', 'Une armée d\’Orcs d\’un autre monde ? Des soldats éprouvés… De nouvelles armes à déchaîner contre l\’Alliance. Intéressant…', 28153),
(154523, 'frFR', 'En sauvant Draenor de l\’empire de Garrosh et de la Légion ardente, notre héraut a gagné la confiance des Orcs qui y vivent. Il est temps qu\’ils s\’acquittent de leur dette envers nous.', '', 28153),
(154522, 'frFR', 'Chef de guerre, il y a bien longtemps, la Horde a poursuivi le fugitif Garrosh Hurlenfer jusqu\’à un écho du Draenor que j\’ai connu.', '', 28153),
(154521, 'frFR', 'Nous refusons la proposition des Corsandre. Voici les ordres du capitaine.', 'Nous refusons la proposition des Corsandre. Voici les ordres du capitaine.', 28153),
(154520, 'frFR', 'Vous avez sorti la tenue du dimanche, l\’$Uami:amie; ? Dites-moi donc ce qui vous amène.', '', 28153),
(154519, 'frFR', 'Buvez, compagnons ! Vous m\’avez l\’air à sec... Ha !', 'Buvez, compagnons ! Vous m\’avez l\’air à sec... Ha !', 28153),
(154518, 'frFR', 'Destruction', 'Destruction', 28153),
(154516, 'frFR', 'Vous n\’avez rien à faire ici. J\’espère que vous avez une bonne raison d\’interrompre mon cours.', 'Vous n\’avez rien à faire ici. J\’espère que vous avez une bonne raison d\’interrompre mon cours.', 28153),
(154515, 'frFR', '<Darrel ne semble pas avoir remarqué votre présence.>', '<Darrel ne semble pas avoir remarqué votre présence.>', 28153),
(154514, 'frFR', 'C\’est très impoli d\’interrompre les gens, vous savez !', 'C\’est très impoli d\’interrompre les gens, vous savez !', 28153),
(154513, 'frFR', 'À première vue, rien ici n\’indique où sont partis mes semblables. Laissez-moi jeter un coup d\’œil aux informations que vous avez recueillies, je vous recontacterai si je trouve quelque chose d\’intéressant.', '', 28153),
(154512, 'frFR', '|cFF0000FF(Quête)|r Cap sur la vallée Chantorage.', '|cFF0000FF(Quête)|r Cap sur la vallée Chantorage.', 28153),
(154511, 'frFR', 'Attention ! Attention ! Intrus ! Intrus !', '', 28153),
(154510, 'frFR', '', 'Acceptez ce cadeau… l\’armure traditionnelle de notre peuple. Portez-la avec fierté en souvenir de notre patrie. Dranosh\’ek mag\’har !', 28153),
(154509, 'frFR', '', 'En défendant la Horde contre ses ennemis, vous avez apporté gloire et honneur aux Mag\’har.', 28153),
(154508, 'frFR', '', 'Retournez à Orgrimmar afin que je puisse honorer votre dévouement envers notre peuple.', 28153),
(154507, 'frFR', '', 'Vous avez mené des milliers de batailles sur tout Azeroth. Vous avez montré à nos alliés comme à nos ennemis ce que veut dire être mag\’har !', 28153),
(154506, 'frFR', '', 'Peu importe où vous mène votre voyage, n\’oubliez pas que le cœur de Draenor bat en vous. Lok-tar ogar !', 28153),
(154505, 'frFR', '', 'Chaque victoire montrera aux peuples d\’Azeroth que nous sommes les maîtres de la guerre !', 28153),
(154504, 'frFR', '', 'La Horde a besoin de notre force pour contrer l\’Alliance. Et nous avons répondu à leur appel.', 28153),
(154503, 'frFR', '', 'Notre peuple était uni sous la bannière de Grommash Hurlenfer. Il n\’y avait qu\’un clan : les Mag\’har.', 28153),
(154502, 'frFR', '', 'Il y a des années, les héros de ce monde se sont rendus sur Draenor et ont combattu à nos côtés contre la Légion ardente.', 28153),
(154501, 'frFR', '', 'Mon cher Rokhan, la tribu Sombrelance a bien mérité le soutien des Zandalari. Je vais me joindre à vous et vous aider autant que possible.', 28153),
(154500, 'frFR', 'Je dois vous emprunter notre héraut un instant. Un vieil ennemi a réussi à échapper à Bwonsamdi et menace mon foyer.', '', 28153),
(154499, 'frFR', 'Je suis prêt. Commencez votre rituel.', 'Je suis prête. Commencez votre rituel.', 28153),
(154498, 'frFR', '', 'Quelqu\’un doit bien savoir quelque chose. Une flotte, ça disparaît pas comme ça !', 28153),
(154497, 'frFR', 'Au lieu de ça, nous allons… ouvrir notre port à la Horde ?', '', 28153),
(154496, 'frFR', 'Nous ne céderons pas aux Corsandre…', '', 28153),
(154495, 'frFR', 'Et je suis censé vous croire, $r ? Donnez-moi ça.', '', 28153),
(154494, 'frFR', 'Voici les ordres du capitaine. Il a décidé de ne pas s\’associer aux Corsandre !', 'Voici les ordres du capitaine. Il a décidé de ne pas s\’associer aux Corsandre !', 28153),
(154493, 'frFR', 'D\’où venez-vous au juste ? Vous n\’êtes manifestement pas du coin.', '', 28153),
(154492, 'frFR', '', 'Quoi ? Faites-moi voir ça.', 28153),
(154491, 'frFR', 'Je vous apporte de nouveaux ordres du capitaine, maître d\’équipage.', 'Je vous apporte de nouveaux ordres du capitaine, maître d\’équipage.', 28153),
(154490, 'frFR', '', 'Non seulement pour ramener la flotte à bon port mais aussi pour rétablir Kul Tiras… ou « soigner l\’infection », comme dit Cirrus.', 28153),
(154489, 'frFR', '', 'Qui êtes-vous ? Et que voulez-vous au juste ?', 28153),
(154488, 'frFR', '', 'Ils bénissent aussi chacun des navires kultirassiens. C\’est ce qui les distingue vraiment des bateaux de passage.', 28153),
(154487, 'frFR', '', 'Je n\’avais jamais vu autant d\’azérite à la fois. Cela m\’inquiète et me ravit tout autant.', 28153),
(154486, 'frFR', '', 'Un élémentaire… d\’azérite pure. Tuez-le, mais ne le détruisez pas. Récupérez autant de résine que possible !', 28153),
(154485, 'frFR', '', 'Cela devrait les rassasier… pour le moment, en tout cas.', 28153),
(154484, 'frFR', '', 'Les Orcs font de bons soldats, mais chacun d\’eux mange comme dix Gobelins ! Nos magasins sont bien vides. Pendant que vous combattrez les Kaldorei, abattez donc quelques bêtes au passage, d\’accord ?', 28153),
(154483, 'frFR', '', 'Comme je le dis toujours, coupez la rose avant que ne poussent les épines.', 28153),
(154482, 'frFR', '', 'Un autre commandant kaldorei au mauvais endroit au mauvais moment. Débarrassez-vous d\’elle. Nous ne pouvons lui permettre d\’appeler des renforts.', 28153),
(154481, 'frFR', '', 'Vous étiez l\’arme parfaite pour cette tâche.', 28153),
(154480, 'frFR', '', 'Saurcroc a franchi les montagnes entre Sombrivage et Gangrebois. Retrouvez-le dans la vallée des Briselances et assurez-vous qu\’il progresse sans encombre.', 28153),
(154479, 'frFR', 'On y est arrivés, matelots ! Le roi-pirate Zem\’lan est mort pour de bon et le trésor est à nous !', '', 28153),
(154478, 'frFR', '', 'Je n\’ai jamais douté de vous.', 28153),
(154477, 'frFR', '', 'Les Kaldorei semblent avoir mobilisé des renforts. Et celui-là risque d\’être coriace. J\’attends de vous que vous triomphiez.', 28153),
(154476, 'frFR', '', 'Vous combattez avec intelligence et passion. De tels efforts inspirent tous mes soldats.', 28153),
(154475, 'frFR', '', 'L\’Alliance écume Sombrivage pour démanteler nos avant-postes. Nous ne devons pas céder de terrain ! Défendez le fruit de nos conquêtes !', 28153),
(154474, 'frFR', '', 'En temps de guerre, c\’est tuer ou être tué. Il n\’y a rien à ajouter.', 28153),
(154473, 'frFR', '', 'Ne fléchissez pas ! Ces monstres d\’elfes ne vous montreront aucune pitié.', 28153),
(154472, 'frFR', '', 'Nous avons sévèrement réduit leurs troupes de réserve. Beau travail.', 28153),
(154471, 'frFR', '', 'C\’est dans l\’ombre que les Kaldorei sont le plus redoutable. Attaquez et éliminez-les avant la tombée de la nuit !', 28153),
(154470, 'frFR', '', 'Ma confiance en vous n\’était pas vaine. Les Kaldorei auront bientôt perdu toute volonté de se battre.', 28153),
(154469, 'frFR', '', 'Les soldats de Malfurion talonnent notre armée ! Nous devons nous enfoncer plus loin en Sombrivage tant que nous avons l\’avantage !', 28153),
(154468, 'frFR', '', 'Pauvre petite chose… Elle a à peine eu le temps de bouger le petit doigt.', 28153),
(154467, 'frFR', '', 'Ce commandant met ma patience à rude épreuve. Brisez-la.', 28153),
(154466, 'frFR', '', 'Imaginez… dormir des milliers d\’années et ne se réveiller que pour être vaincu… C\’est pathétique !', 28153),
(154465, 'frFR', '', 'Alors comme ça, les anciens ont décidé de prendre l\’air, hein ? On va leur faire regretter de s\’être réveillés.', 28153),
(154464, 'frFR', 'J\’imagine que ça aurait pu être pire. Assurez-vous que sa résine ne tombe pas entre les mains de la Horde.', '', 28153),
(154463, 'frFR', '', 'Un élémentaire d\’azérite pure ! J\’ignore à quel point il est dangereux… Mais faites attention à vous !', 28153),
(154462, 'frFR', 'Les Elfes de la nuit combattront jusqu\’au bout.', 'Les Elfes de la nuit combattront jusqu\’au bout.', 28153),
(154461, 'frFR', '', 'Vous avez déjà utilisé une bombe d\’azérite ? Vous voulez voir ce qu\’est la vraie puissance ? Accrochez-vous, alors. Vous aurez une excellente surprise.', 28153),
(154460, 'frFR', 'Quel magnifique spécimen ! Cette créature va me permette d\’élaborer de multiples recettes alchimiques.', '', 28153),
(154459, 'frFR', 'C\’est toujours un choc pour les nouveaux cadets. Ne vous inquiétez pas, ça forge le caractère !', '', 28153),
(154458, 'frFR', '', 'Les Kaldorei ne se rendront jamais… à moins que nous les brisions.\n\nNous devons leur porter un coup dont ils ne se relèveront pas… leur arracher quelque chose… ou quelqu\’un… en qui ils ont une foi et une confiance absolues. Un symbole d\’espoir.\n\n<La Dame noire plisse les yeux.>\n\nMalfurion Hurlorage doit mourir.', 28153),
(154457, 'frFR', 'Les pêcheurs racontent qu\’une créature énorme et étrange rôderait sous la surface. Récupérer un échantillon pourrait s\’avérer utile.', '', 28153),
(154456, 'frFR', '', 'L\’Alliance veut utiliser des armes de siège contre nous ? Quelle drôle d\’idée ! Montrez-leur de quoi la Horde est capable.', 28153),
(154455, 'frFR', 'Avec la pénurie actuelle de fer, nous ne pouvons pas gaspiller les moindres munitions, même d\’entraînement. Nos soldats ont conçu le moyen idéal pour les récupérer.', '', 28153),
(154454, 'frFR', '', 'Ces ruines sont riches en ressources naturelles… Il ne tient qu\’à nous de nous en emparer ! Ne laissez pas les Kaldorei nous en empêcher.', 28153),
(154453, 'frFR', '', 'Nous avons quelques coursiers du vent à disposition. Rassemblez nos explosifs et semez le chaos sur le mur de feux follets de Malfurion. Faites-lui comprendre le message.', 28153),
(154452, 'frFR', '', 'Vous êtes $Udoué:douée;, ma parole ! Mais je plains les pauvres ramasseurs de boulets.', 28153),
(154451, 'frFR', 'Une chamane de la KapitalRisk contrôle des élémentaires bourrés d\’azérite ! Cette bande de voyous ne devrait pas avoir accès à une telle puissance. Abattez-la !', '', 28153),
(154450, 'frFR', '', 'Au bruit, je dirais qu\’il y a une leçon de tir dans la zone d\’entraînement. Je parie que vous pourriez apprendre une chose ou deux sur les canons aux autres cadets.', 28153),
(154449, 'frFR', '', 'Les armes que vous avez récupérées seront utiles à notre effort de guerre. Bel effort.', 28153),
(154448, 'frFR', '', 'De gré ou de force, nous avons plus que jamais besoin de l\’aide des eaugures.', 28153),
(154447, 'frFR', 'Beau boulot ! M\’est avis que vous avez délesté quelques poches, y compris les miennes.', '', 28153),
(154446, 'frFR', '', 'Bon, personne ne semble savoir pourquoi la flotte n\’est pas encore revenue.', 28153),
(154445, 'frFR', '', 'La rumeur dit qu\’ils ont perdu leurs pouvoirs, mais il doit s\’agir de luttes internes, comme pour les Corsandre.', 28153),
(154444, 'frFR', '', 'Cette cargaison appartient à la Horde ! Ne laissez pas l\’Alliance mettre la main dessus.', 28153),
(154443, 'frFR', 'De temps en temps, des Éperonneurs organisent ici un tournoi de duels entre pirates et ils ne sont pas trop regardants niveau participants.', '', 28153),
(154442, 'frFR', '', 'Malgré leur entraînement, ces forestiers semblent avoir mal calculé leur attaque. Le Flétrisseur aura quelques mots à leur dire…', 28153),
(154441, 'frFR', '', 'Les plus grands navires transportent toujours un eaugure pour les guider à travers les mers agitées, et pour faire souffler le vent dans leurs voiles.', 28153),
(154440, 'frFR', '', 'Mes forestiers-sombres ont besoin de votre aide. Aidez tous ceux que vous trouverez !', 28153),
(154439, 'frFR', '', 'Vos talents seront plus utiles ailleurs, maintenant. J\’ai une équipe de Gobelins prête à récupérer le reste.', 28153),
(154438, 'frFR', 'Elle est bonne, celle-là : gaver un Ogre avec le sang de la planète pour le rendre moins crétin ! Comme si ça pouvait marcher… Réglez-lui son compte, au cas où.', '', 28153),
(154437, 'frFR', 'Remarquable ! Voilà qui attirera forcément le regard !', '', 28153),
(154436, 'frFR', '', 'Des barils de poudre d\’azérite ont été jetés par-dessus bord ! Récupérez-les rapidement, avant qu\’ils ne coulent !', 28153),
(154435, 'frFR', 'J\’ai utilisé tous les clichés que vous m\’aviez donnés. Si vous avez un peu de temps libre, de nouvelles photos me seraient bien utiles.', '', 28153),
(154434, 'frFR', '', 'Le campement est en sécurité à présent, mais ne relâchez pas votre vigilance.', 28153),
(154433, 'frFR', 'Le responsable des recherches en armement est ici ! Depuis le temps qu\’on essaie de le coincer. Allez-lui donner une leçon qu\’il n\’oubliera pas.', '', 28153),
(154432, 'frFR', '', 'Quel dommage que vous ne puissiez voir la flotte. Elle impressionnerait même quelqu\’un ayant autant voyagé que vous !', 28153),
(154431, 'frFR', 'Ah, Boralus ! Ses gangs de rue, ses nobles querelleurs… Vous savez, Gnomeregan n\’a jamais connu de tels problèmes.', '', 28153),
(154430, 'frFR', 'J\’ai décidé d\’ajouter quelques images des autres attractions locales dans ma publicité. La ville est un bon endroit où commencer.', '', 28153),
(154429, 'frFR', '', 'Des saboteurs de l\’Alliance se sont infiltrés dans notre avant-poste ! Éliminez-les ! Et qu\’ils souffrent !', 28153),
(154428, 'frFR', '', 'Bref, il est temps de faire bon usage de ce bac !', 28153),
(154427, 'frFR', 'Mon responsable des recherches en armement a accepté de rejoindre la KapitalRisk. Qui refuserait un si joli pactole, hein ? Dommage qu\’il ne puisse en profiter, vu que vous allez le tuer pour moi.', '', 28153),
(154426, 'frFR', 'Magnifique ! Vous savez, ce qui est bien avec les photos, c\’est que ça ne sent pas le poney.', '', 28153),
(154425, 'frFR', 'Le seigneur Norwington veut que son domaine figure en bonne place dans la prochaine brochure des sources Thermorelax. Quoi de plus naturel que de lui rendre ce service.', '', 28153),
(154424, 'frFR', 'La KapitalRisk fait ingurgiter des quantités astronomiques d\’azérite à ses Ogres dans l\’espoir de les rendre plus intelligents. Les chances de réussite sont minces… mais ne prenons pas de risques.', '', 28153),
(154423, 'frFR', '', 'L\’essence de puits de Lune devrait vous être utile au combat. Faites de même avec tous les puits que les Kaldorei béniront à l\’avenir.', 28153),
(154422, 'frFR', '', 'Les Kaldorei utilisent les puits de Lune pour reprendre des forces au combat. Puisez dedans autant que vous voudrez, puis rendez-les inutilisables. C\’est compris ?', 28153),
(154421, 'frFR', 'Vous tombez à pic ! Un instant de plus et ma réputation de gérant de station balnéaire en aurait souffert.', '', 28153),
(154420, 'frFR', 'Soyez prudente là-bas, Taelia. Je n\’ai pas du tout confiance en ces encapuchonnés.', '', 28153),
(154419, 'frFR', 'Mon petit doigt m\’a dit que la KapitalRisk a trouvé le moyen de dompter des élémentaires en azérite pure. Nous devons intervenir ! Et quand je dis « nous », je parle de vous, bien sûr.', '', 28153),
(154418, 'frFR', '', 'Je vais donner l\’ordre à nos enchanteurs d\’imprégner ces pierres de lune d\’azérite. Leur puissance sert désormais la Horde !', 28153),
(154417, 'frFR', '', 'Les Kaldorei tirent leur puissance de pendentifs fabriqués en pierre de lune. Faites ce qu\’il faut pour les priver de leurs babioles.', 28153),
(154416, 'frFR', '', 'Bien joué. Je vais ordonner que cette cargaison d\’azérite soit ajoutée à nos réserves.', 28153),
(154415, 'frFR', '', 'De l\’azérite affleure dans les ruines de Sombrivage. Ne laissons pas l\’Alliance en grappiller le moindre éclat !', 28153),
(154414, 'frFR', '', 'C\’est exactement le genre de message que je voulais envoyer à Malfurion. Excellent travail.', 28153),
(154413, 'frFR', '', 'Ces feux follets ne sont que des insectes nuisibles. Éteignez leur lumière une à une, et bientôt, les cieux baigneront de nouveau dans les ténèbres.', 28153),
(154412, 'frFR', 'Quel désastre ! Les sources sont devenues folles et attaquent mes clients !', '', 28153),
(154411, 'frFR', '', 'Imbéciles ! G\’huun, il échouera pas ! Votre pouvoir est inutile !', 28153),
(154410, 'frFR', '', 'Nos cuisiniers devraient pouvoir nous préparer de bons petits plats avec ça. Merci à vous.', 28153),
(154409, 'frFR', '', 'Mes confrères druides, eh bien… ont un appétit d\’ours. C\’est une tâche ingrate, mais il faut bien remplir le garde-manger. Pouvons-nous compter sur vous ?', 28153),
(154408, 'frFR', 'C\’est l\’heure de gagner not\’ croûte, feu à volonté !', '', 28153),
(154407, 'frFR', 'Ha ha ! Pas mal.', 'Ha ha ! Pas mal.', 28153),
(154406, 'frFR', 'Ça va pas, non ?', 'Ça va pas, non ?', 28153),
(154405, 'frFR', 'À quoi ça rime, cette histoire ?', 'À quoi ça rime, cette histoire ?', 28153),
(154404, 'frFR', 'À quoi vous jouez, par tous les Loas ?', 'À quoi vous jouez, par tous les Loas ?', 28153),
(154403, 'frFR', 'Arrêtez votre char !', 'Arrêtez votre char !', 28153),
(154402, 'frFR', 'Écartez-vous ! Me v\’là avec l\’artillerie lourde !', '', 28153),
(154401, 'frFR', 'Voilà le huitième morceau. Vous avez réussi, $Ucossu:cossue; !\n', '', 28153),
(154400, 'frFR', 'Les pirates ont pour habitude de diviser leurs pièces en huit. Vous auriez une sacrée veine si vous mettiez la main sur huit morceaux ! Fouillez Port-Liberté, la ville regorge de petite monnaie.', '', 28153),
(154399, 'frFR', 'Complètement maso, l\’animal. Quelqu\’un veut du calmar ? Ha ha.', '', 28153),
(154398, 'frFR', 'Une espèce de méduse géante s\’est installée dans les eaux de Port-Liberté. On a beau la transpercer avec nos harpons, impossible de la déloger !', '', 28153),
(154397, 'frFR', 'Z\’avez tué le capitaine de l\’effroi Vandermort et offert le repos à son âme ! Imaginez tous les trésors que vous avez libérés de la malédiction !', '', 28153),
(154396, 'frFR', 'Le capitaine Vandermort était un boucanier craint dans toute la région. On dit qu\’il était si cupide qu\’il est revenu d\’entre les morts pour continuer de piller ses côtes.', '', 28153),
(154395, 'frFR', 'Iggksh ywaq ag\’rr ni ky !', '', 28153),
(154394, 'frFR', 'Ah\’shel ywaq qam yrr woth\’gl !', '', 28153),
(154393, 'frFR', 'Voilà le huitième morceau. Vous avez réussi !', '', 28153),
(154392, 'frFR', 'Za ag\’rr wgah thyzz zuq !', '', 28153),
(154391, 'frFR', 'Les pirates ont pour habitude de diviser leurs pièces en huit. Vous auriez d\’la veine si vous mettiez la main sur huit morceaux ! Fouillez Port-Liberté, la ville regorge de petite monnaie.', '', 28153),
(154390, 'frFR', 'Une vraie masochiste, cette bête-là. Qui veut déguster un peu de calmar ?', '', 28153),
(154389, 'frFR', 'Une sorte de méduse géante a élu domicile dans les eaux de Port-Liberté. Peu importe le nombre de harpons qu\’on lui décoche, elle revient toujours à la charge !', '', 28153),
(154388, 'frFR', 'Ga ag\’rr ez AN\’zig wgha kyth zuq !', '', 28153),
(154387, 'frFR', 'Vous avez tué Vandermort et accordé le repos à son âme ! Pensez à tous les trésors que vous avez libérés de la malédiction !', '', 28153),
(154386, 'frFR', 'Le capitaine Vandermort était un boucanier craint dans toute la région. La rumeur dit qu\’il était si cupide qu\’il continue d\’en piller les côtes même dans la mort.', '', 28153),
(154385, 'frFR', 'Mais… Ce n\’est pas l\’avenir qu\’on m\’avait promis…', '', 28153),
(154384, 'frFR', 'Le sang de G\’huun coule dans mes veines ! Tremblez devant ma puissance !', '', 28153),
(154383, 'frFR', 'J\’ai vu tant d\’horreurs…', 'Votre gentillesse est étonnante.', 28153),
(154382, 'frFR', 'Ma puissance va vous écraser !', '', 28153),
(154381, 'frFR', 'Merci. Je n\’aurais pas tenu encore longtemps.', 'Merci. Je ne regretterai pas cet endroit !', 28153),
(154380, 'frFR', 'La puissance de G\’huun sera votre perte !', '', 28153),
(154379, 'frFR', 'Contemplez votre fin et plongez dans le désespoir !', '', 28153),
(154378, 'frFR', 'Levez-vous, serviteurs ! Le sang fera de nous des conquérants !', '', 28153),
(154377, 'frFR', 'Par mon sang, levez-vous et écrasez les faibles !', '', 28153),
(154376, 'frFR', 'Venez, mes frères ! Nourrissez-vous des infidèles !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'frFR', 'Que votre sang me revienne !', '', 28153),
(154374, 'frFR', 'G\’huun, accepte cette offrande de sang !', '', 28153),
(154373, 'frFR', 'Son avenir était vide.', '', 28153),
(154372, 'frFR', 'Faible. Comme je l\’avais prédit.', '', 28153),
(154371, 'frFR', 'Tout se passe comme je l\’avais prédit !', '', 28153),
(154370, 'frFR', 'Venez, imbéciles ! Je connais déjà votre fin.', '', 28153),
(154369, 'frFR', 'Ma mère est morte quand j\’étais très jeune, et c\’est mon père qui m\’a élevé. Il était marin et il me donnait toujours une fleur de brin-de-mer avant d\’appareiller.', 'Ma mère est morte quand j\’étais très jeune, et c\’est mon père qui m\’a élevée. Il était marin et il me donnait toujours une fleur de brin-de-mer avant d\’appareiller.', 28153),
(154368, 'frFR', '', 'Alerte. Manifestation d\’une projection sombre.', 28153),
(154367, 'frFR', '', 'Alerte. Protocole de sécurité de confinement du Vide compromis.', 28153),
(154366, 'frFR', '', 'Vous avez agi avec noblesse.', 28153),
(154365, 'frFR', '', 'Alerte. Niveau dangereux d\’énergie du Vide détecté.', 28153),
(154363, 'frFR', '', 'Attention. Réplication de Nérubiens supplémentaires.', 28153),
(154362, 'frFR', 'L\’équilibre a été restauré. Anu\’dorini talah !', '', 28153),
(154361, 'frFR', 'Cette cible se cache dans les ombres. Mais nul ne peut se dérober à la lumière bénie d\’Élune. Abattez-la.', '', 28153),
(154360, 'frFR', '', 'Attention. Réplication de silithides supplémentaires.', 28153),
(154359, 'frFR', 'Bah, saleté de fleur de malheur ! Pour moi, elle est synonyme de braves marins disparus en mer et de cargaisons passées par le fond.', 'Bah, saleté de fleur de malheur ! Pour moi, elle est synonyme de braves marins disparus en mer et de cargaisons passées par le fond.', 28153),
(154358, 'frFR', '', 'Mythrax n\’a pas sa place en ce monde.', 28153),
(154357, 'frFR', '', 'Qu\’Élune vous bénisse. Vous rayonnez tel un astre.', 28153),
(154356, 'frFR', '', 'Mes archers auraient bien besoin de vous. Aidez tous ceux que vous pourrez trouver !', 28153),
(154355, 'frFR', '', 'Cette guerre doit cesser.', 28153),
(154354, 'frFR', '', 'Je veillerai sur vous.', 28153),
(154353, 'frFR', '', 'Chargement terminé. Déconnexion du disque.', 28153),
(154352, 'frFR', '', 'Vous avez éliminé la menace et vous m\’avez rapporté mon arme de siège en un seul morceau. Je vous en suis d\’autant plus reconnaissante.', 28153),
(154351, 'frFR', '', 'L\’ordre doit être rétabli.', 28153),
(154350, 'frFR', '', 'Nous avons tous notre place. La mienne est ici.', 28153),
(154349, 'frFR', '', 'Je suis affaiblie, mais je suis là.', 28153),
(154348, 'frFR', '', 'Vous en avez déjà utilisé, avant ? Accrochez-vous bien, une petite surprise vous attend.', 28153),
(154347, 'frFR', '', 'Accès au disque. Données corrompues en cours de chargement.', 28153),
(154346, 'frFR', 'Je vais envoyer autant de soldats que je pouvais. J\’espère qu\’ils arriveront à repousser l\’assaut. Nous ne tiendrons pas sur deux fronts à la fois.', '', 28153),
(154345, 'frFR', 'J\’ai ressenti un grand bouleversement au nord. La Horde nous aurait-elle déjà attaqués par-delà les montagnes ? Partez enquêter. Et vite !', '', 28153),
(154344, 'frFR', '', 'Vous avez le poil roussi. Tout ne s\’est pas passé comme prévu ?', 28153),
(154343, 'frFR', '', 'Même sous l\’eau, ces barils de poudre d\’azérite représentent un danger. Je veux que vous les fassiez exploser avant qu\’ils remontent à la surface. Mais essayez de rester en un seul morceau, d\’accord ?', 28153),
(154342, 'frFR', '', 'Surcharge de la matrice de données. Accès à plusieurs disques à la fois.', 28153),
(154341, 'frFR', 'Le brin-de-mer ? Certains de mes matelots lèvent jamais l\’ancre sans en laisser un à leur moitié. On peut pas leur en vouloir de chercher à éviter de longs mois d\’angoisse à leurs proches si jamais il leur arrivait malheur.', 'Le brin-de-mer ? Certains de mes matelots lèvent jamais l\’ancre sans en laisser un à leur moitié. On peut pas leur en vouloir de chercher à éviter de longs mois d\’angoisse à leurs proches si jamais il leur arrivait malheur.', 28153),
(154340, 'frFR', '', 'Je n\’ai jamais douté de vous.', 28153),
(154339, 'frFR', '', 'La Horde est arrivée en nombre, mais aucun de ses membres ne doit être sous-estimé. Celui-ci semble particulièrement… résistant. Approchez-le avec prudence.', 28153),
(154338, 'frFR', '', 'Accès au disque. Données sur Yogg-Saron en cours de chargement.', 28153),
(154337, 'frFR', '', 'Accès au disque. Données sur C\’Thun en cours de chargement.', 28153),
(154335, 'frFR', '', 'Des saboteurs de la Horde se sont infiltrés dans nos rangs ! Débusquez-les. Et ne faites preuve d\’aucune pitié !', 28153),
(154334, 'frFR', '', 'Vous m\’impressionnez. Même mes sentinelles auraient des choses à apprendre à vos côtés.', 28153),
(154333, 'frFR', '', 'Il est temps de combattre le feu par le feu ! Nous devons débarrasser la Horde de ses démolisseurs et repousser l\’envahisseur vers les Tarides, là où est leur place !', 28153),
(154332, 'frFR', '', 'Élune vous sourit. Avec tous mes remerciements.', 28153),
(154331, 'frFR', '', 'La Horde tente de nous voler de l\’essence de puits de lune ! Ne laissez pas cette vermine souiller nos sources bénies !', 28153),
(154330, 'frFR', '', 'Que ces chacals de la Horde restent dans leur désert. Nous allons leur apprendre qu\’on ne touche pas à nos forêts.', 28153),
(154329, 'frFR', '', 'La Horde a établi une base à la frontière d\’Orneval. Ralliez les druides qui veillent sur la forêt !', 28153),
(154328, 'frFR', '', 'Bien joué. Et vous avez mis tant de cœur à l\’ouvrage…', 28153),
(154327, 'frFR', '', 'Les soldats de la Horde pillent nos terres ! Arrêtez-les… avant qu\’ils épuisent les ressources de notre forêt sacrée.', 28153),
(154326, 'frFR', '', 'Des milliers d\’années de mort n\’ont rien altéré de leurs capacités, mais vous les avez brillamment combattus !', 28153),
(154325, 'frFR', '', 'C\’est… C\’est la garde personnelle du roi Dazar ! Ils ne céderont pas facilement !', 28153),
(154324, 'frFR', 'Ha ! Ces Morts-vivants sont plus si vivants tout à coup ! Bien joué.', '', 28153),
(154323, 'frFR', 'Ces Trolls morts-vivants ont l\’air plus costauds que les autres. Faites attention !', '', 28153),
(154322, 'frFR', 'Que pouvez-vous me dire au sujet du brin-de-mer ?', 'Que pouvez-vous me dire au sujet du brin-de-mer ?', 28153),
(154321, 'frFR', '', 'Ce sera parfait ! Nous apprécions votre contribution à sa juste valeur.', 28153),
(154320, 'frFR', '', 'La Horde dispose déjà d\’armes à azérite. Que diriez-vous de les lui confisquer ?', 28153),
(154319, 'frFR', 'Enfin… si on oublie les salles de Pierre…', '', 28153),
(154318, 'frFR', 'Pfff. Les assemblages nains se détraqueraient jamais comme ça.', '', 28153),
(154317, 'frFR', '', 'Excellent travail ! Mes alchimistes placeront l\’azérite en un lieu sûr, hors de portée de la Horde.', 28153),
(154316, 'frFR', 'Peuh, de la conception trolle de bas étage. Ce golem est complètement détraqué. Forcez-le à se calmer !', '', 28153),
(154315, 'frFR', '', 'Nous devons trouver Julwaba avant que Jakra\’zet ne le fasse.', 28153),
(154314, 'frFR', '', 'La magie noire de Zul, elle a corrompu ce gardien. Arrêtez-le, qu\’on puisse réparer les dégâts.', 28153),
(154313, 'frFR', '', 'Zul… ce que tu as fait à ce lieu sacré, c\’est impardonnable.', 28153),
(154312, 'frFR', '', 'Au revoir, Halu. Repose en paix.', 28153),
(154311, 'frFR', '', 'Ahh, Halu, le maître d\’armes… Il a formé mon père, et son père avant lui, mais sa tâche est maintenant terminée. Apportez le repos à son esprit troublé.', 28153),
(154310, 'frFR', 'Ha ! On dirait que vous lui avez montré qui commande, ici !', '', 28153),
(154309, 'frFR', 'Un guerrier qui entraînait les membres de la royauté zandalari hante toujours cette tombe. Accordez-lui le repos éternel !', '', 28153),
(154308, 'frFR', '', 'Mes archers devraient pouvoir prendre le relais. Votre action a permis de renverser le cours de la bataille. Je vous remercie mille fois.', 28153),
(154307, 'frFR', '', 'L\’ennemi nous attaque depuis le nord. Il est temps d\’aller le combattre sur son propre terrain !', 28153),
(154306, 'frFR', 'Laissez-les passer !', '', 28153),
(154305, 'frFR', '', 'J\’y suis presque ! J\’entends la voix d\’Akunda entrer dans mon esprit.', 28153),
(154304, 'frFR', '', 'Je vais faire de mon mieux pour réparer l\’esprit d\’Akunda, mais vous devrez être $upréparé:préparée; à supprimer tout souvenir qui pourrait en jaillir.', 28153),
(154303, 'frFR', 'Ywaq ongg an\’qov i lal halahs nuq.', '', 28153),
(154302, 'frFR', 'Ywaq mh\’naus wgah zaix zyqtahg.', '', 28153),
(154301, 'frFR', 'Mojambo va vous faire… payer…', '', 28153),
(154300, 'frFR', '', 'Où… où je suis ? Qu\’est-ce que je fais ici ?', 28153),
(154299, 'frFR', 'Oou thyzz lal ak\’uq qwaz Zuq shkul ma sk\’tek…', '', 28153),
(154298, 'frFR', '', 'Ils sont mystérieux mais très importants pour Kul Tiras. Ils aident à remplir les filets de poissons et font pleuvoir dans les champs de la vallée.', 28153),
(154297, 'frFR', '', 'Ici, les gens font appel à la mer pour les guider, comme d\’autres à la Lumière, mais les eaugures ont une plus forte connexion avec les eaux.', 28153),
(154296, 'frFR', '', 'Je vous proposerais bien de monter Trombecœur, mais les eaugures n\’acceptent que des arrivées par bateau.', 28153),
(154295, 'frFR', '', 'Tout ira bien, Cirrus. Je sais me défendre. En plus, l\’émissaire de l\’Alliance est à mes côtés !', 28153),
(154294, 'frFR', 'Oou yyqzz ez thyzz phquathi zuq !', '', 28153),
(154293, 'frFR', 'Oou gul\’kafh lal lwhuk !', '', 28153),
(154292, 'frFR', 'Qam oou iilth ez i awtgsshu amun on\’ma !', '', 28153),
(154291, 'frFR', 'Log\’loth w\’oq Ongg !', '', 28153),
(154290, 'frFR', '', 'De l\’azérite a été mise au jour dans les ruines de Sombrivage. Nous ne pouvons pas laisser la Horde s\’en emparer !', 28153),
(154289, 'frFR', 'W\’oq uhn\’agth ez qam Shandai !', '', 28153),
(154288, 'frFR', 'Awtgssh shn ongg shg\’ullwaq !', '', 28153),
(154287, 'frFR', 'Zuq ag\’xig bormaz ag\’thyzak !', '', 28153),
(154286, 'frFR', 'Merci !', 'Merci !', 28153),
(154285, 'frFR', 'Za qualar ag\’xig za al\’tha !', '', 28153),
(154284, 'frFR', 'Je ne suis pas assez payé pour ça !', 'Je ne suis pas assez payée pour ça !', 28153),
(154283, 'frFR', 'AHHHHHHHHHHHHHHHHHHHHHHHH !', 'AHHHHHHHHHHHHHHHHHHHHHHHH !', 28153),
(154282, 'frFR', 'Merci de m\’avoir secouru !', 'Merci de m\’avoir secourue !', 28153),
(154281, 'frFR', 'J\’ai vraiment cru que j\’allais finir en chair à saucisse !', 'J\’ai vraiment cru que j\’allais finir en chair à saucisse !', 28153),
(154280, 'frFR', 'Oou vwahuHn ag\’xig shfk zuq !', '', 28153),
(154279, 'frFR', 'Merci à vous !', 'Merci à vous !', 28153),
(154278, 'frFR', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'frFR', 'Vwah oou kaaxth zz ywaq iiyoq Ag\’xlg fhssh I on\’ma.', '', 28153),
(154276, 'frFR', 'Za awtgsshu wgah uulg\’ma ywaq zaix.', '', 28153),
(154275, 'frFR', 'Qam oou uhnish kyth zuq Ongg za fhssh as\’rr.', '', 28153),
(154274, 'frFR', 'Ywaq zuq ywag shn\’ma Bo\’al za qwor.', '', 28153),
(154273, 'frFR', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\’ma.', '', 28153),
(154272, 'frFR', 'Oou shath\’yar lwhuk shn\’ma yrr shandi agth fhssh.', '', 28153),
(154271, 'frFR', 'Quand les esprits sont en paix, la forêt l\’est également. Je vous remercie.', '', 28153),
(154270, 'frFR', 'Ces esprits ne sont que l\’ombre de ce qu\’ils étaient autrefois. Ils ont besoin de votre aide, héraut. Apportez-leur la paix.', '', 28153),
(154269, 'frFR', 'On m\’appelle pas seigneur des maléfices pour rien.', '', 28153),
(154268, 'frFR', 'Prenez mon bâton maléficiant et transformez quelques prêtres en trucs plus intéressants.', '', 28153),
(154267, 'frFR', 'Si vous pensez que c\’était méchant, c\’est que vous avez jamais vu ce que les autres Loas font faire à leurs disciples.', '', 28153),
(154266, 'frFR', 'Si nous n\’arrêtons pas cette corruption, qui le fera ?', 'Si nous n\’arrêtons pas cette corruption, qui le fera ?', 28153),
(154265, 'frFR', 'Les druides de Gonk, ils se prennent trop au sérieux. Jouez-leur un tour pour les décoincer un peu. Oh, et faites attention, y pourraient vous tuer pour ça.', '', 28153),
(154264, 'frFR', 'Si cela prend de l\’ampleur… Azeroth est condamnée.', 'Si cela prend de l\’ampleur… Azeroth est condamnée.', 28153),
(154263, 'frFR', 'La nature souffre… Comment pouvons-nous mettre un terme à cette folie ?', 'La nature souffre… Comment pouvons-nous mettre un terme à cette folie ?', 28153),
(154262, 'frFR', 'Nos pouvoirs sont sans effet… Comment pouvons-nous guérir la planète ?', 'Nos pouvoirs sont sans effet… Comment pouvons-nous guérir la planète ?', 28153),
(154261, 'frFR', '', 'C\’était une sacrée chevauchée ! Vous avez accompli un excellent travail !', 28153),
(154260, 'frFR', '', 'Nos dragons-faë ne sont pas habitués à porter une selle. Attendez-vous à une chevauchée chaotique. Grimpez sur l\’un d\’eux et guidez leur attaque.', 28153),
(154259, 'frFR', 'Je me nourris de votre terreur !', '', 28153),
(154258, 'frFR', 'Renforts de Forgefer ! Marchez sur la base ennemie !', '', 28153),
(154257, 'frFR', 'Écrasez Ar\’gorok, pour Arathor ! Pour Stromgarde ! POUR L\’ALLIANCE !', '', 28153),
(154256, 'frFR', '', 'Vous combattez comme les légendaires Zandalari. Impressionnant.', 28153),
(154255, 'frFR', '', 'Vous continuez à prouver votre valeur. Bien joué.', 28153),
(154252, 'frFR', '', 'Grâce à vous, nos peuples sont maintenant en sécurité.', 28153),
(154251, 'frFR', '', 'Maintenant que cet ennemi est mort, notre effort peut reprendre.', 28153),
(154246, 'frFR', '', 'Le refuge devrait se trouver un peu plus loin. On y sera en sécurité pour un temps.', 28153),
(154245, 'frFR', '', 'Espérons que nous n\’aurons plus à en entendre parler.', 28153),
(154244, 'frFR', '', 'Les Loas avaient prédit votre victoire. Ravie de voir qu\’ils avaient vu juste.', 28153),
(154243, 'frFR', '', 'Ceux de votre Horde seront ravis d\’apprendre que vous avez éradiqué cette menace.', 28153),
(154242, 'frFR', '', 'Je savais que cet adversaire ne pourrait rien contre vous.', 28153),
(154240, 'frFR', 'Vous sentez ce picotement dans votre dos ? C\’est là que j\’existe.', '', 28153),
(154239, 'frFR', '', 'Nos troupes me rapportent qu\’un puissant ennemi à proximité veut votre mort. Soyez sans pitié.', 28153),
(154238, 'frFR', '', 'Les guerriers de la Horde me signalent la présence d\’un dangereux ennemi à proximité. Soulagez-les en éliminant cette menace.', 28153),
(154237, 'frFR', '', 'Vos éclaireurs de la Horde ont repéré un redoutable ennemi dans la zone. Ils suggèrent de le tuer, et je suis d\’accord avec eux.', 28153),
(154234, 'frFR', 'On dirait que Nazmir abrite une armée infinie de ces sauvages. Merci d\’avoir réduit leur nombre.', '', 28153),
(154232, 'frFR', 'Ah ! C\’est sûr, vous avez un don ! Ça faisait belle lurette que j\’avais pas vu quelqu\’un dévaler les pistes comme ça !', '', 28153),
(154230, 'frFR', 'Les Trolls de sang, ils se pressent à nos portes. Chevauchez les cornes de guerre et empalez ces sauvages !', '', 28153),
(154228, 'frFR', 'J\’ai pas de travail pour vous aujourd\’hui. La plupart des Baroudeurs sont partis faire quelques descentes pour se détendre un peu. Prenez un pingoulin et lancez-vous !', '', 28153),
(154225, 'frFR', '', 'Prenez garde. Un dangereux adversaire rôde par ici. Il faut l\’abattre avant qu\’il sème le chaos.', 28153),
(154224, 'frFR', 'Élune admire votre bravoure.', '', 28153),
(154223, 'frFR', '', 'Les Loas nous ont révélé qu\’un puissant ennemi se trouve à proximité. Ils exigent qu\’il soit éradiqué de la surface d\’Azeroth.', 28153),
(154222, 'frFR', 'La reine banshee ne nous laisse aucun répit. Fouillez la forêt et purgez-la de sa sinistre présence !', '', 28153),
(154221, 'frFR', '', 'Mes éclaireurs signalent un redoutable adversaire dans la zone. Éliminez-le avant qu\’il devienne une menace.', 28153),
(154220, 'frFR', 'Mes troupes, elles sont prêtes à prendre le relai. Merci de leur avoir laissé le temps de se regrouper.', '', 28153),
(154219, 'frFR', '', 'Soyez sur vos gardes, je perçois une menace par ici. Occupez-vous-en avant qu\’elle s\’occupe de vous !', 28153),
(154218, 'frFR', 'Vous avez fait reculer la menace. Merci d\’avoir restauré le repos des anciens.', '', 28153),
(154217, 'frFR', '', 'Un terrible adversaire rôde dans les parages. Abattez-le avant qu\’il s\’en prenne à nos alliés.', 28153),
(154216, 'frFR', 'Tuez tout ce qui n\’est pas un Zandalari !', '', 28153),
(154215, 'frFR', 'Les anciens s\’agitent à l\’aube d\’une nouvelle menace. Repoussez la Horde pour préserver la forêt.', '', 28153),
(154213, 'frFR', 'Grâce à vous, nous disposons d\’un précieux répit pour poursuivre nos efforts.', '', 28153),
(154212, 'frFR', 'Les arbres de cette majestueuse forêt ploient et se rompent sous les assauts de la Horde, toujours plus loin sur nos terres. Nous ne pouvons pas la laisser continuer !', '', 28153),
(154211, 'frFR', 'Faites attention à vous.', 'Faites attention à vous.', 28153),
(154210, 'frFR', 'Les sables, ils avalent les faibles.', 'Les sables, ils avalent les faibles.', 28153),
(154209, 'frFR', 'Ne faites confiance à personne.', 'Surveillez vos arrières.', 28153),
(154208, 'frFR', 'Personne mérite ce destin.', 'Personne mérite ce destin.', 28153),
(154207, 'frFR', 'Vous voulez quoi ?', 'Tous sont les bienvenus ici.', 28153),
(154205, 'frFR', 'Salut.', 'Salut.', 28153),
(154204, 'frFR', '', 'Je vous entends toujours... maître...', 28153),
(154203, 'frFR', 'Mes murmures vont liquéfier votre esprit.', '', 28153),
(154202, 'frFR', 'Laissez la soif vous envahir. Buvez leur sang.', '', 28153),
(154201, 'frFR', 'Rejoignez vos alliés. Partagez mon don.', '', 28153),
(154200, 'frFR', 'Une excellente acquisition. Maintenant, faites disparaître le reste de cette vermine infidèle !', '', 28153),
(154199, 'frFR', 'La pourriture s\’infiltre dans vos veines. Laissez-la se répandre.', '', 28153),
(154198, 'frFR', 'Arrachez son canalisateur à l\’un des ensorceleurs infidèles et chargez-le. Je vous récompenserai pour vos efforts.', '', 28153),
(154197, 'frFR', 'Nos ensorceleurs ont perçu des courants électriques anormalement puissants à l\’intérieur du temple.', '', 28153),
(154196, 'frFR', 'Que le festin des mille gueules commence !', '', 28153),
(154195, 'frFR', 'Excellent travail ! Maintenant, chargez-vous du cœur de Sephraliss.', '', 28153),
(154194, 'frFR', 'Apportez-moi ces reliques et je vous récompenserai.', '', 28153),
(154193, 'frFR', 'Mes enfants, venez et nourrissez-vous !', '', 28153),
(154192, 'frFR', 'Il semble que les infidèles ont caché des artéfacts de notre peuple quelque part dans le bazar, en face du cœur du temple.', '', 28153),
(154191, 'frFR', 'Venez vous repaître, serviteurs de la pourriture.', '', 28153),
(154190, 'frFR', 'Quel splendide spécimen ! Maintenant, débarrassez le temple de cette vermine infidèle !', '', 28153),
(154189, 'frFR', 'On m\’a dit qu\’une espèce rare de krolusk nichait dans le temple. Apportez-moi un de leurs jeunes spécimens et je vous récompenserai.', '', 28153),
(154188, 'frFR', 'Rien n\’arrête ma pestilence !', '', 28153),
(154187, 'frFR', 'Mon fléau ne peut être repoussé !', '', 28153),
(154186, 'frFR', 'Les Titans ne peuvent pas vous sauver !', '', 28153),
(154185, 'frFR', 'Vous n\’échapperez pas à l\’infection !', '', 28153),
(154184, 'frFR', 'Les sceaux sont brisés. La fin est proche. Venez et soyez les premiers à recevoir mon don.', '', 28153),
(154183, 'frFR', 'Les ouvriers vous sont vraiment reconnaissants de les avoir secourus. Vous leur avez sauvé la couenne.', '', 28153),
(154182, 'frFR', 'La contagion… a pris racine en vous…', '', 28153),
(154181, 'frFR', 'Des sorcières ont de nouveau envahi le port du Désosseur. Sauvez les ouvriers avant qu\’ils finissent tous en chair à saucisse !', '', 28153),
(154180, 'frFR', '', 'Les Drust éliminés, les esprits des anciens vont pouvoir reposer en paix. Bien joué.', 28153),
(154179, 'frFR', '', 'Les combats incessants menacent les réfugiés à la Ferté-d\’Arom. Réduisez les effectifs de l\’ennemi !', 28153),
(154178, 'frFR', 'Faites appel à la tempête, $n. Châtiez l\’usurpateur !', '', 28153),
(154177, 'frFR', 'Vous faites honneur à mon pouvoir, $n.', '', 28153),
(154176, 'frFR', 'Mon enfant, enfin vous pouvez m\’entendre. Un traître se cache au sein du temple.', '', 28153),
(154175, 'frFR', '', 'Une créature maléfique menace mon peuple. Éliminez-la.', 28153),
(154174, 'frFR', '', 'Les sorcières ont lâché une redoutable créature dans cette zone. Abattez-la !', 28153),
(154173, 'frFR', '', 'Bien joué ! Les habitants de Drustvar seront plus en sûreté grâce à vous.', 28153),
(154172, 'frFR', '', 'Beau travail ! Les sorcières y réfléchiront à deux fois avant de s\’en prendre à Drustvar !', 28153),
(154171, 'frFR', 'Enfin, je suis libre. Merci, $p.', '', 28153),
(154170, 'frFR', '', 'Les éclaireurs nous ont indiqué la présence d\’un ennemi dangereux dans les parages. Éliminez-le !', 28153),
(154169, 'frFR', '', 'Une puissante présence ennemie menace mes concitoyens dans cette zone. Neutralisez-la !', 28153),
(154168, 'frFR', 'Comment ai-je pu perdre ?', '', 28153),
(154167, 'frFR', '', 'Mes concitoyens vous remercient du fond du cœur. Nous allons pouvoir dormir sur nos deux oreilles ce soir.', 28153),
(154166, 'frFR', '', 'Les habitants de Drustvar vous sont reconnaissants.', 28153),
(154165, 'frFR', 'Ce n\’était pas très malin.', '', 28153),
(154164, 'frFR', '', 'Des rapports font état d\’une présence ennemie dans ce secteur. Débarrassez-vous-en.', 28153),
(154163, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t G\’huun vous lance |cFFFF0404|Hspell:272506|h[Corruption explosive]|h|r !', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t G\’huun vous lance |cFFFF0404|Hspell:272506|h[Corruption explosive]|h|r !', 28153),
(154162, 'frFR', 'Enfin, le repos...', '', 28153),
(154161, 'frFR', '', 'Un redoutable ennemi menace les habitants de Drustvar. Occupez-vous-en !', 28153),
(154160, 'frFR', 'Si même l\’océan n\’a pas pu avoir ma peau, ce n\’est pas vous qui allez m\’abattre.', '', 28153),
(154159, 'frFR', 'Je me répandrai et consumerai votre monde.', '', 28153),
(154158, 'frFR', 'Nous avons besoin d\’un bac pour le monastère Chantorage.', 'Nous avons besoin d\’un bac pour le monastère Chantorage.', 28153),
(154157, 'frFR', 'Votre carcasse sert un nouveau maître, désormais.', '', 28153),
(154155, 'frFR', 'Il y a tant que je n\’ai pas dit...', '', 28153),
(154154, 'frFR', 'Je n\’ai pas dit mon dernier mot !', '', 28153),
(154153, 'frFR', 'Vos hurlements retentiront à tout jamais !', '', 28153),
(154152, 'frFR', 'Que la malédiction de la chair vous consume !', '', 28153),
(154151, 'frFR', 'L\’épidémie a commencé !', '', 28153),
(154150, 'frFR', '', 'Tu sais que je dois le faire, Kaja. Le devoir avant tout.', 28153),
(154149, 'frFR', '', 'Jakra\’zet est un traître, mais le roi n\’agira pas sans preuves.', 28153),
(154148, 'frFR', 'Je crois… que je peux trouver le repos à présent…', 'Je crois… que je peux trouver le repos à présent…', 28153),
(154147, 'frFR', 'On a essayé de vous prévenir !', 'On a essayé de vous prévenir !', 28153),
(154146, 'frFR', '', 'Allez-y. Voyez ce que vous pouvez découvrir. Je vais rester avec Rakera.', 28153),
(154145, 'frFR', 'Vous pouvez désormais entendre les mots d\’Akunda. Rejoignez l\’autel $Useul:seule; et priez quand vous voudrez commencer.', '', 28153),
(154144, 'frFR', 'Akunda ne pénétrera dans votre esprit que si vous êtes $upurifié:purifiée;.', '', 28153),
(154143, 'frFR', 'Je voudrais revenir ici.', 'Je voudrais revenir ici.', 28153),
(154142, 'frFR', 'Niveau maximal atteint. Reprise de la collecte.', '', 28153),
(154141, 'frFR', '<Athair vous regarde avec bienveillance.>', '<Athair vous regarde avec bienveillance.>', 28153),
(154140, 'frFR', '<Althair vous observe de manière égale.>', '<Althair vous observe de manière égale.>', 28153),
(154139, 'frFR', 'Évacuation des fluides en cours. Mise en veille…', '', 28153),
(154138, 'frFR', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\’huun commence à lancer |cFFFF0404|Hspell:267700|h[Regard de G\’huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\’huun commence à lancer |cFFFF0404|Hspell:267700|h[Regard de G\’huun]|h|r.', 28153),
(154133, 'frFR', 'Spécimen pris pour cible. Destruction imminente.', '', 28153),
(154132, 'frFR', 'Initialisation de la dispersion du sang de la cible.', '', 28153),
(154131, 'frFR', 'Récupération du broyeur imminente.', '', 28153),
(154130, 'frFR', 'Déploiement du broyeur.', '', 28153),
(154129, 'frFR', 'Ressources épuisées. Mise en veille… prolongée…', '', 28153),
(154128, 'frFR', '', 'Dranosh\’ek mag\’har !', 28153),
(154127, 'frFR', 'Sujets prêts pour la contamination.', '', 28153),
(154126, 'frFR', '', 'La guerre étreint ces terres. <Rires> Bien ! Nous nous délecterons du carnage… et remporterons la victoire !', 28153),
(154125, 'frFR', '', 'Nous sommes les derniers survivants d\’une fière tribu. Nul ne peut nous corrompre ou nous briser. Nous sommes les Mag\’har !', 28153),
(154124, 'frFR', '', 'De simples mots pour certains… une vraie philosophie pour nous.', 28153),
(154123, 'frFR', '', 'Force et honneur. Sang et tonnerre.', 28153),
(154122, 'frFR', 'Accroissement des ressources disponibles.', '', 28153),
(154121, 'frFR', 'Nouveau candidat corruptible détecté.', '', 28153),
(154120, 'frFR', 'Hôtes détectés. Début de la contamination.', '', 28153),
(154119, 'frFR', '', 'Je vous assure qu\’ils sont réels. Et dangereux. Même les Sephraks n\’osent pas se rendre dans le canyon.', 28153),
(154118, 'frFR', 'Lancement de la collecte de plasma.', '', 28153),
(154117, 'frFR', 'Plus vite, bande de fainéants ! Vous ne serez pas payés tant qu\’il ne sera pas réparé !', '', 28153),
(154116, 'frFR', 'Quelle île magnifique...', 'Quelle île magnifique...', 28153),
(154115, 'frFR', 'Est-ce au moins... une mort grandiose ?', 'Est-ce au moins... une mort grandiose ?', 28153),
(154114, 'frFR', '', 'Continuons. Rakera survivra pas longtemps dans ce désert.', 28153),
(154113, 'frFR', 'Ça ne fait pas aussi mal que ce que je...', 'Ça ne fait pas aussi mal que ce que je...', 28153),
(154112, 'frFR', 'Pourquoi ai-je échoué ?', 'Pourquoi ai-je échoué ?', 28153),
(154111, 'frFR', 'Crevez, bande de vautours !', 'Crevez, bande de vautours !', 28153),
(154110, 'frFR', 'Vous ne me battrez jamais !', 'Vous ne me battrez jamais !', 28153),
(154109, 'frFR', 'Elle est où, votre reine banshee, hein ?', 'Elle est où, votre reine banshee, hein ?', 28153),
(154108, 'frFR', 'Je n\’ai pas survécu à l\’océan pour tomber face à vous, vermine !', 'Je n\’ai pas survécu à l\’océan pour tomber face à vous, vermine !', 28153),
(154107, 'frFR', '', 'Je ne crois pas, non.', 28153),
(154106, 'frFR', 'Il est temps d\’appliquer le plan de Nisha. Les Sephraks ne nous verront pas venir.', '', 28153),
(154105, 'frFR', '', 'J\’aurais dû investir plus dans la sécurité.', 28153),
(154104, 'frFR', '', 'Je n\’ai pas le temps pour ces bêtises !', 28153),
(154103, 'frFR', '', 'Fouettez-les s\’il le faut ! Je veux que le brise-récifs soit opérationnel.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'frFR', 'Elle n\’en a peut-être plus pour très longtemps. Ses blessures sont graves.', '', 28153),
(154101, 'frFR', '', 'Je m\’en sors toujours. C\’est une autre survivante ?', 28153),
(154100, 'frFR', 'Prenez tout ce que vous pourrez avant que tout ne soit détruit.', 'Prenez tout ce que vous pourrez avant que tout ne soit détruit.', 28153),
(154099, 'frFR', 'Cet endroit est rempli de choses fascinantes.', 'Cet endroit est rempli de choses fascinantes.', 28153),
(154098, 'frFR', 'L\’Ancienne route marchande sera pas aussi sûre qu\’avant de sitôt. Merci pour votre aide.', '', 28153),
(154097, 'frFR', 'Merci...', 'Merci...', 28153),
(154096, 'frFR', 'Oh non... Pas encore.', 'Oh non... Pas encore.', 28153),
(154095, 'frFR', 'Ne les laissez pas me manger...', 'Ne les laissez pas me manger...', 28153),
(154094, 'frFR', 'Ils m\’ont dit... que ce serait facile...', 'Ils m\’ont dit... que ce serait facile...', 28153),
(154093, 'frFR', 'Votre crâne fera un magnifique trophée.', 'Votre crâne fera un magnifique trophée.', 28153),
(154092, 'frFR', 'Des marchands ont besoin d\’une escorte pour leurs caravanes. Ça vous dit ?', '', 28153),
(154091, 'frFR', 'Le chancre vous emportera !', 'Le chancre vous emportera !', 28153),
(154090, 'frFR', 'Si vous avez échappé à l\’océan, c\’est pour mieux périr de ma main !', 'Si vous avez échappé à l\’océan, c\’est pour mieux périr de ma main !', 28153),
(154089, 'frFR', 'Vous allez mourir ici !', 'Vous allez mourir ici !', 28153),
(154088, 'frFR', 'VOUS MONTREZ ENFIN VOTRE VRAI VISAGE ! QUITTEZ CE LIEU SACRÉ !', 'VOUS MONTREZ ENFIN VOTRE VRAI VISAGE ! QUITTEZ CE LIEU SACRÉ !', 28153),
(154087, 'frFR', 'Le pas le plus important est toujours celui à venir, $n. Continuez sur cette voie.', 'Le pas le plus important est toujours celui à venir, $n. Continuez sur cette voie.', 28153),
(154086, 'frFR', 'Vous êtes un monstre du même acabit qu\’Arthas, $n. Je souhaite que votre mort soit lente et que la souffrance et les tortures que vous avez fait subir à d\’autres vous soient infligées au centuple.\n\nAlors que de graves dangers pesaient sur le monde entier, vous avez écumé la planète, condamnant ses morts à la servitude dans la non-vie. Vous pensiez agir pour le bien de tous, mais croyez-moi, les conséquences seront lourdes.\n\n<Zallestrasza s\’ébroue.>\n\nEn attendant, je crois que vous pourriez nous être utile.', 'Vous êtes un monstre du même acabit qu\’Arthas, $n. Je souhaite que votre mort soit lente et que la souffrance et les tortures que vous avez fait subir à d\’autres vous soient infligées au centuple.\n\nAlors que de graves dangers pesaient sur le monde entier, vous avez écumé la planète, condamnant ses morts à la servitude dans la non-vie. Vous pensiez agir pour le bien de tous, mais croyez-moi, les conséquences seront lourdes.\n\n<Zallestrasza s\’ébroue.>\n\nEn attendant, je crois que vous pourriez nous être utile.', 28153),
(154085, 'frFR', '<Ses traits se détendent légèrement.>\n\nCet acte n\’est pas passé inaperçu, $n. Nous ne sommes plus que quelques représentants de mon peuple et chaque vie est sacrée.\n\nCela n\’excuse en rien votre crime contre mon vol, mais nous vous sommes reconnaissants de la… retenue dont vous avez fait preuve. Compte tenu de votre nature, cela n\’a pas dû être aisé.', '<Ses traits se détendent légèrement.>\n\nCet acte n\’est pas passé inaperçu, $n. Nous ne sommes plus que quelques représentants de mon peuple et chaque vie est sacrée.\n\nCela n\’excuse en rien votre crime contre mon vol, mais nous vous sommes reconnaissants de la… retenue dont vous avez fait preuve. Compte tenu de votre nature, cela n\’a pas dû être aisé.', 28153),
(154084, 'frFR', 'En effet, $n.\n\nNous savons que c\’est vous qui avez profané notre sanctum. Nous savons que vous avez corrompu et asservi Kyranastrasz.\n\nEt un jour viendra où vous devrez répondre de ces crimes contre la vie.', 'En effet, $n.\n\nNous savons que c\’est vous qui avez profané notre sanctum. Nous savons que vous avez corrompu et asservi Kyranastrasz.\n\nEt un jour viendra où vous devrez répondre de ces crimes contre la vie.', 28153),
(154083, 'frFR', 'Vos méfaits sont parvenus à nos oreilles, chevalier de la mort. Vous avez peut-être défendu Azeroth contre la Légion ardente, mais vous n\’avez plus notre confiance.\n\nN\’agissez pas inconsidérément.', 'Vos méfaits sont parvenus à nos oreilles, chevalier de la mort. Vous avez peut-être défendu Azeroth contre la Légion ardente, mais vous n\’avez plus notre confiance.\n\nN\’agissez pas inconsidérément.', 28153),
(154082, 'frFR', 'Je n\’ai apparemment pas exterminé tous les dragons du sanctuaire Rubis. <Essayer de la tuer.>', 'Je n\’ai apparemment pas exterminé tous les dragons du sanctuaire Rubis. <Essayer de la tuer.>', 28153),
(154081, 'frFR', 'J\’espère au moins que mes actes m\’auront valu votre confiance.', 'J\’espère au moins que mes actes me vaudront de gagner votre confiance.', 28153),
(154080, 'frFR', 'Votre peuple est faible et sera bientôt éteint. Je n\’ai fait qu\’abréger vos souffrances.', 'Votre peuple est faible et sera bientôt éteint. Je n\’ai fait qu\’abréger vos souffrances.', 28153),
(154079, 'frFR', 'J\’ai épargné les vies que j\’ai pu.', 'J\’ai épargné les vies que j\’ai pu.', 28153),
(154078, 'frFR', 'Vous savez qui je suis ?', 'Vous savez qui je suis ?', 28153),
(154077, 'frFR', 'Non ! Non ! Nooooooon !', 'Non ! Non ! Nooooooon !', 28153),
(154076, 'frFR', '', 'Pour l\’Alliance.', 28153),
(154075, 'frFR', 'Fuyez ! Sauvez votre peau !', 'Fuyez ! Sauvez votre peau !', 28153),
(154074, 'frFR', 'Je… je crois que je me suis souillé…', 'Je… je crois que je me suis souillée…', 28153),
(154073, 'frFR', 'Sortez-moi de là !', 'Sortez-moi de là !', 28153),
(154072, 'frFR', 'Merci ! J\’ai bien failli y passer.', 'Merci ! J\’ai bien failli y passer.', 28153),
(154071, 'frFR', 'C\’est quoi, ces monstres ? Moi, je me taille !', 'C\’est quoi, ces monstres ? Moi, je me taille !', 28153),
(154070, 'frFR', 'Je suis sauvé ! J\’étais à deux doigts de me faire dévorer !', 'Je suis sauvée ! J\’étais à deux doigts de me faire dévorer !', 28153),
(154069, 'frFR', 'Humpf ! Je m\’attendais à un vrai défi.', '', 28153),
(154068, 'frFR', 'Inconcevable… Avec quelles autres terreurs le seigneur Chantorage a-t-il pactisé ?', '', 28153),
(154067, 'frFR', 'Une horreur redoutable nous attend dans le sanctuaire. Venez, nous devons l\’affronter !', '', 28153),
(154066, 'frFR', 'Prudence ! Je perçois une terrible corruption à l\’intérieur du sanctuaire. Nous ne devons pas la laisser se propager !', '', 28153),
(154065, 'frFR', 'Je n\’y vois aucune différence. Humpf. Quoi qu\’il en soit, la traque nous attend.', '', 28153),
(154064, 'frFR', 'Ressentez-vous cette sensation d\’apaisement ? Votre résolution n\’est-elle pas renforcée ? Continuons et accomplissons notre devoir.', '', 28153),
(154063, 'frFR', 'On dit que les eaugures tirent une partie de leur puissance de leurs fontaines purifiantes. Voyons si c\’est vrai avant de pénétrer au cœur du sanctuaire.', '', 28153),
(154062, 'frFR', 'Mmmh ! Suivez-moi alors !', '', 28153),
(154061, 'frFR', 'Tous doivent se purifier avant d\’entrer dans notre lieu le plus sacré. Je vous prie de bien vouloir obtenir la bénédiction de chacune des fontaines purifiantes avant de pénétrer au cœur du sanctuaire.', '', 28153),
(154060, 'frFR', 'Toute aide est la bienvenue. Pour la Horde !', '', 28153),
(154059, 'frFR', 'Je suis soulagé de savoir que tout ne tombe pas sous la coupe du seigneur Chantorage. Merci.', '', 28153),
(154058, 'frFR', 'Ces bassins regorgent de puissance. Récupérez des particules d\’eau pure, elles nous permettront de devenir plus forts !', '', 28153),
(154057, 'frFR', 'Il y a encore du bien dans ce lieu sacré, je le sens. Récupérez des particules d\’eau pure afin que nous redonnions à ce sanctuaire sa gloire passée.', '', 28153),
(154056, 'frFR', 'Ils allaient me tuer. Merci, $c.', 'Ils allaient me tuer. Merci, $c.', 28153),
(154055, 'frFR', '', 'Extension de la contagion.', 28153),
(154054, 'frFR', '', 'Augmentation de la charge virale.', 28153),
(154053, 'frFR', '', 'Nouvelle souche détectée.', 28153),
(154052, 'frFR', '', 'Exécution du champ opératoire. Préparation des échantillons pour étude.', 28153),
(154051, 'frFR', '', 'Niveau d\’infection critique. Purge totale initialisée.', 28153),
(154050, 'frFR', '', 'Ventilation de la chambre de confinement.', 28153),
(154049, 'frFR', '', 'Test de résistance bactériologique aux chaleurs extrêmes.', 28153),
(154048, 'frFR', '', 'Protocole de dissection activé.', 28153),
(154047, 'frFR', '', 'Sys… Sys… Système restauré. Niveau d\’alerte revenu à un seuil convenable.', 28153),
(154046, 'frFR', 'Cette opération a été efficace, bien que peu discrète.', '', 28153),
(154045, 'frFR', '', 'C\’était les dernières. Yazma ne pourra plus nous espionner !', 28153),
(154044, 'frFR', '', 'Yazma a des espions partout. Elle voit à travers les yeux de ses araignées. Écrasez-les.', 28153),
(154043, 'frFR', '', 'Désinfection terminée.', 28153),
(154042, 'frFR', 'Il s\’agit d\’une mission de sauvetage. Trouvez et libérez les soldats capturés, puis rejoignez le point d\’extraction. Je vous autorise à exécuter vos ennemis. Je vous y encourage, même.', '', 28153),
(154041, 'frFR', '', 'Niveau de contagion réduit.', 28153),
(154040, 'frFR', 'Parfait. La seconde équipe ne devrait avoir aucune difficulté à exfiltrer nos soldats.', '', 28153),
(154039, 'frFR', '', 'La lame-de-l\’ombre ne s\’en prendra plus à mon peuple. Merci.', 28153),
(154038, 'frFR', '', 'Infection traitée.', 28153),
(154037, 'frFR', 'Votre rôle est on ne peut plus simple : semer le chaos. Une seconde équipe est prête à récupérer nos soldats capturés. Tout ce que je vous demande, c\’est de vous occuper de ces gardes, d\’entrer, de tuer tous ceux que vous croiserez, puis de ressortir.', '', 28153),
(154036, 'frFR', '', 'Un des fidèles assassins de Yazma a été aperçu dans la zone. Prudence !', 28153),
(154035, 'frFR', '', 'Souche virulente détectée. Neutralisation complète et définitive requise.', 28153),
(154034, 'frFR', '', 'Ça apprendra à Yazma et ses semblables à jouer avec le vaudou noir.', 28153),
(154033, 'frFR', '', 'Protocole de purification activé.', 28153),
(154032, 'frFR', '', 'Le vaudou maléfique de Yazma a animé ces masques tiki ! Détruisez-les tous.', 28153),
(154031, 'frFR', 'Vous avez réussi ! Les gars de la Ligue peuvent maintenant explorer le temple sans être dérangés.', '', 28153),
(154030, 'frFR', 'Il y a quelqu\’un qui tue les Trolls zandalari dans le coin. Ça serait trop dangereux pour la Ligue d\’arpenter le temple dans ces conditions. Rendez-vous sur place et trouvez le responsable !', '', 28153),
(154029, 'frFR', 'Fantastique ! On va immédiatement mettre sur pied une expédition.', '', 28153),
(154028, 'frFR', 'J\’peux pas envoyer mes gars dans le temple avec ces masques tiki dans le coin. Leur magie est trop puissante !', '', 28153),
(154027, 'frFR', 'Bien joué ! Même si j\’ai encore l\’impression qu\’elles se baladent dans ma barbe !', '', 28153),
(154026, 'frFR', 'Rah, des araignées ! De fichues araignées ! Yazma en a mis vraiment partout. Écrasez-en quelques-unes, qu\’on puisse bosser en paix !', '', 28153),
(154025, 'frFR', 'Sancteforge, abattez ces démolisseurs !', '', 28153),
(154024, 'frFR', 'Chevaucheurs de griffons, envolez-vous !', '', 28153),
(154023, 'frFR', 'Sombrefer, maintenant ! Attaquez-les par en dessous !', '', 28153),
(154022, 'frFR', '', 'Nous l\’avons, notre preuve. Mais vous n\’en avez pas laissé beaucoup en vie pour exécuter le plan ! En tout cas, beau travail.', 28153),
(154021, 'frFR', 'Gloire... à l\’Alliance...', '', 28153),
(154020, 'frFR', 'Je suis désormais au service des Voiles-de-Brume, mais m\’acoquiner avec la Horde serait une insulte à mes origines de l\’Alliance... Comment osez-vous ?!', '', 28153),
(154019, 'frFR', '', 'Les pirates de Port-Liberté manigancent toujours quelque chose. Découvrez de quoi il s\’agit cette fois.', 28153),
(154018, 'frFR', 'Grâce à vous, la 7e Légion a une menace de moins sur les bras.', '', 28153),
(154017, 'frFR', 'Beau combat ! Nous aurons vite fait de contrôler toute la zone au nom de l\’Alliance !', '', 28153),
(154016, 'frFR', 'Ce n\’était pas gagné d\’avance, mais votre vaillance a fini par triompher. Continuez comme ça !', '', 28153),
(154015, 'frFR', 'L\’ennemi est en déroute. Il est regrettable de devoir en arriver là, mais vous avez fait votre devoir.', '', 28153),
(154014, 'frFR', 'Ah, si seulement j\’avais eu des alliés comme vous pendant la Troisième guerre. Excellent travail.', '', 28153),
(154013, 'frFR', 'Vous auriez fait des merveilles pendant la Deuxième guerre. Beau boulot.', '', 28153),
(154012, 'frFR', 'Beau travail. Une menace de moins, c\’est toujours ça de pris !', '', 28153),
(154011, 'frFR', 'Merci de nous avoir prêté main-forte. Vous avez l\’étoffe des vrais champions des Dévoués !', '', 28153),
(154010, 'frFR', '', 'Frappez là où ça fait mal ! Au porte-monnaie !', 28153),
(154009, 'frFR', '', 'Si on mettait la main sur le livre de comptes du gang, on pourrait perturber ses opérations financières !', 28153),
(154008, 'frFR', 'Merci. Les blessés vont devoir attendre, mais vous nous avez fait gagner un temps précieux.', 'Merci. Les blessés vont devoir attendre, mais vous nous avez fait gagner un temps précieux.', 28153),
(154007, 'frFR', 'Voilà, ça devrait arrêter l\’hémorragie pour le moment…', 'Voilà, ça devrait arrêter l\’hémorragie pour le moment…', 28153),
(154006, 'frFR', 'Ça fait mal, je sais, mais essayez de rester tranquille…', 'Ça fait mal, je sais, mais essayez de rester tranquille…', 28153),
(154005, 'frFR', 'Chut ! Ils vont nous entendre…', 'Chut ! Ils vont nous entendre…', 28153),
(154004, 'frFR', 'Allez chercher de l\’aide ! J\’vais voir c\’que j\’peux faire à l\’intérieur pour endiguer la corruption !', '', 28153),
(154003, 'frFR', '', 'Je reconnaîtrais l\’écriture d\’O\’toiles entre mille. Je vais vous tuer, et cette traîtresse y passera ensuite !', 28153),
(154002, 'frFR', 'Arg, le passage se referme ! J\’peux pas laisser passer cette chance !', '', 28153),
(154001, 'frFR', '', 'Pile où je l\’avais laissé !', 28153),
(154000, 'frFR', '', 'Capitaine ! On a une mutinerie sur les bras...', 28153),
(153999, 'frFR', 'C\’est moi ou cette machine a parlé de G\’huun ? Suivons-la !', '', 28153),
(153997, 'frFR', 'C\’est peut-être lié à Uldir. Allons vite le découvrir !', '', 28153),
(153996, 'frFR', 'J\’avais encore jamais vu une telle corruption.', '', 28153),
(153995, 'frFR', '', 'Salut, $c. Ça vous dit d\’apprendre quelques trucs en alchimie ?$b$bJ\’suis le meilleur maître de la région, ça j\’vous le garantis.', 28153),
(153994, 'frFR', 'Qui sait quels secrets elle renferme ! Nous pourrions peut-être même y découvrir comment vaincre les Dieux très anciens !', '', 28153),
(153993, 'frFR', 'Les Titans ont construit ce complexe après la chute de l\’Empire noir pour mener des expériences sur toutes sortes de créatures.', '', 28153),
(153992, 'frFR', 'Argh ! C\’est quoi cette créature ?', '', 28153),
(153991, 'frFR', 'Ces grottes doivent mener à la légendaire Uldir !', '', 28153),
(153990, 'frFR', 'Merci pour votre aide. Grâce à vous, le désert est plus sûr, désormais.', '', 28153),
(153989, 'frFR', '', 'C\’était pas gagné d\’avance, mais vous avez bien combattu. Continuez comme ça !', 28153),
(153988, 'frFR', '', 'Une épine de moins dans le pied. Beau travail !', 28153),
(153987, 'frFR', '', 'Beau travail. Notre ennemi n\’oubliera pas de sitôt la leçon que vous lui avez administrée.', 28153),
(153986, 'frFR', 'Passez devant.', 'Passez devant.', 28153),
(153985, 'frFR', '', 'Cette maison regorge de secrets habilement dissimulés. Maintenant que les étages sont sous contrôle, je vais vous montrer un passage dérobé vers le sous-sol.', 28153),
(153984, 'frFR', 'Merci pour le coup de main. Vol\’dun a bien besoin de héros de votre trempe !', '', 28153),
(153983, 'frFR', 'Beau travail. Grâce à votre aide, le désert est un peu plus sûr.', '', 28153),
(153982, 'frFR', 'Un danger de moins en Vol\’dun. Beau travail !', '', 28153),
(153981, 'frFR', 'Mais pensez à… tout cet or…', '', 28153),
(153980, 'frFR', 'Vous vous mêlez de sujets qui vous dépassent ! La compagnie Corsandre va nous offrir une puissance qui dépasse nos rêves les plus fous !', '', 28153),
(153979, 'frFR', 'Je ne vous laisserai pas faire de mal à mon peuple !', '', 28153),
(153978, 'frFR', 'Les pierres sont... partout... les Mogu les auront toutes !', '', 28153),
(153977, 'frFR', 'Là ! À l\’attaque !', '', 28153),
(153976, 'frFR', '', 'Je crois qu\’on est $utirés:tirées; d\’affaire. Vous avez fait du bon boulot.', 28153),
(153975, 'frFR', 'Grâce à ces pierres, rien n\’arrêtera les Mogu !', '', 28153),
(153974, 'frFR', 'Vous vous montrez enfin ! Disparaissez !', '', 28153),
(153973, 'frFR', '', 'On dirait qu\’on a de la compagnie. Occupez-vous d\’eux, $p !', 28153),
(153972, 'frFR', '', 'Accrochez-vous ! Ça va pas mal secouer.', 28153),
(153971, 'frFR', 'Ce vieux loup a encore les crocs bien aiguisés !', '', 28153),
(153970, 'frFR', 'Vous êtes à moi !', '', 28153),
(153969, 'frFR', 'On s\’enhardit, hein ? Hah !', '', 28153),
(153968, 'frFR', '', 'Je ne crois pas.', 28153),
(153967, 'frFR', '', 'Pitoyable.', 28153),
(153966, 'frFR', '', 'Pas aujourd\’hui.', 28153),
(153965, 'frFR', 'Mes éclaireurs signalent un dangereux ennemi dans les parages. Neutralisez-le.', '', 28153),
(153962, 'frFR', 'J\’ai perdu certains de mes soldats face à un ennemi, non loin. Vengez leur mort !', '', 28153),
(153959, 'frFR', 'La 7e Légion a reçu des informations sur un puissant ennemi, à proximité. Abattez-le immédiatement.', '', 28153),
(153958, 'frFR', 'Pas de trésor… que les ténèbres.', 'De l\’or, aussi loin que le regard, il porte…', 28153),
(153957, 'frFR', 'Libérez-moi…', 'Je suis… libre ?', 28153),
(153956, 'frFR', 'Trésor maudit… Or maudit…', 'Maudits soient les voleurs…', 28153),
(153955, 'frFR', 'Rajoutez-moi sur la pile…', 'Des os dorés…', 28153),
(153954, 'frFR', 'On signale la présence d\’un redoutable ennemi à proximité. Abattez-le, mais restez bien sur vos gardes.', '', 28153),
(153953, 'frFR', 'Un redoutable ennemi a tué une troupe d\’éclaireurs. Vengez nos hommes en mettant un terme à cette menace.', '', 28153),
(153952, 'frFR', 'Une menace a fait irruption à proximité. Ne paniquez pas, et ne lui laissez aucune chance de s\’en tirer.', '', 28153),
(153951, 'frFR', 'Vous avez la grande classe, chef. Mais vous pouvez continuer à farfouiller, si vous préférez.', '', 28153),
(153950, 'frFR', 'J\’ai une potion pour chacun d\’entre vous, mais ne la buvez pas tout de suite.', '', 28153),
(153949, 'frFR', 'Bravo, vous avez réussi à exaspérer une ville endormie.\n\nNe perdons pas de temps à rejeter la faute sur les autres, d\’accord ?', '', 28153),
(153948, 'frFR', 'Je connais déjà cette histoire. (Passer le scénario et se téléporter au port de Zuldazar en Zandalar.)', 'Je connais déjà cette histoire. (Passer le scénario et se téléporter au port de Zuldazar en Zandalar.)', 28153),
(153947, 'frFR', 'Que cela serve de message à vos sombres maîtres. Le Sillage des tempêtes ne fléchira jamais !', '', 28153),
(153946, 'frFR', 'Ne le laissez pas s\’insinuer dans votre esprit. Tenez bon !', '', 28153),
(153945, 'frFR', '', 'Toute cette souffrance est de votre faute. MONSTRE !', 28153),
(153944, 'frFR', 'Je nous protégerai de ses coups !', '', 28153),
(153943, 'frFR', 'Ni plahf Ni bormaz Oou sshoq\’meg vwyq yyg\’far.', '', 28153),
(153942, 'frFR', 'De l\’or. De l\’or. De l\’or.', 'Un peu plus d\’or pour notre butin.', 28153),
(153941, 'frFR', 'Aucune lumière. Aucune issue. Le roi oublié revient.', '', 28153),
(153940, 'frFR', 'Pas d\’équipage ici…', 'Courez…', 28153),
(153939, 'frFR', 'Tous les trésors pour Zem\’lan.', 'Le trésor, il est que pour Zem\’lan.', 28153),
(153938, 'frFR', 'C\’est le moment de faire connaissance. Second O\’toiles, $n. $n, O\’toiles. Bon, et si on causait affaires, maintenant ?', '', 28153),
(153937, 'frFR', '', 'J\’avais dit à Kiro que les Sephraks ne tarderaient pas à nous attaquer. Nous aurions pu nous y préparer… Peut-être qu\’il va enfin m\’écouter, maintenant.', 28153),
(153936, 'frFR', '', 'Ils nous ont attaqués par surprise. Les Sephraks massacrent et oppriment sans aucune pitié.', 28153),
(153935, 'frFR', 'De l\’or…', 'Ça brille…', 28153),
(153934, 'frFR', 'Une dangereuse menace rôde dans les parages. Détruisez-la avant qu\’elle fasse davantage de victimes.', '', 28153),
(153933, 'frFR', 'Certains de nos alliés se sont fait attaquer ici même. Vous devez éradiquer cette menace immédiatement.', '', 28153),
(153930, 'frFR', 'Une dangereuse créature rôde dans les parages. Vous devez l\’éliminer avant qu\’elle ne tue des innocents.', '', 28153),
(153929, 'frFR', '', 'On m\’a signalé une menace toute proche. Éliminez-la au plus vite !', 28153),
(153928, 'frFR', '', 'Certains de nos alliés se sont fait attaquer non loin d\’ici. Éliminez la menace avant que ça se reproduise !', 28153),
(153927, 'frFR', '', 'Un horrible monstre rôde dans le coin. Vous devez le tuer avant qu\’il vous réduise en charpie.', 28153),
(153926, 'frFR', 'On m\’a signalé plusieurs fois la présence d\’une dangereuse créature dans le secteur. Il faut que vous l\’éliminiez au plus vite.', '', 28153),
(153925, 'frFR', 'Vite, aidez-moi !', '', 28153),
(153924, 'frFR', 'L\’une de nos caravanes a été attaquée non loin d\’ici. Éradiquez la menace avant que cela se reproduise !', '', 28153),
(153923, 'frFR', 'Bah oui, c\’est une Humaine, mais faut pas la juger trop vite, quoi.', '', 28153),
(153922, 'frFR', 'Notre but, il est simple. On soutient sa mutinerie, et en échange, on aura le droit de s\’installer ici pour préparer notre attaque.', '', 28153),
(153921, 'frFR', 'O\’toiles refuse d\’abandonner sa liberté, comme le reste des pirates du coin.', '', 28153),
(153920, 'frFR', 'Il y a une dangereuse créature dans les parages. Je compte sur vous pour l\’éliminer avant qu\’il ne soit trop tard !', '', 28153),
(153919, 'frFR', 'J\’ai entendu parler de notre contact en éclusant Tiragarde à la recherche de coins où jeter l\’ancre.', '', 28153),
(153918, 'frFR', 'Ohé, pirate !', '', 28153),
(153917, 'frFR', 'Le monde englouti accueille vos âmes béantes.', '', 28153),
(153916, 'frFR', 'Oou c\’toth shuul phquathi ywaq uulg\’ma on\’ma', '', 28153),
(153915, 'frFR', 'Il est perdu ! Seules les ténèbres subsistent.', '', 28153),
(153914, 'frFR', '', 'Sam, je sais que tu es encore là. Tu dois résister !', 28153),
(153913, 'frFR', 'Rien ni aucune créature ne vous résiste bien longtemps.', '', 28153),
(153912, 'frFR', '', 'Excellent. Maintenant, la voie est libre.', 28153),
(153911, 'frFR', 'Ce n\’était qu\’une réplique. Ne parlons plus de cela.', '', 28153),
(153910, 'frFR', '', 'Parfait ! Emportons-le avec nous et découvrons ce qui s\’y cache.', 28153),
(153909, 'frFR', 'Cela fera l\’affaire. Le chef de guerre vous salue.', '', 28153),
(153908, 'frFR', '', 'Fantastique ! Cela contribuera à l\’effort de guerre.', 28153),
(153907, 'frFR', 'Très bien, chef. On va aller causer à ce second. Tâchez de jouer les vieux loups de mer.', '', 28153),
(153906, 'frFR', 'Je suis la grande classe, pas vrai ? À l\’abordage !', '', 28153),
(153905, 'frFR', 'Une bête belliqueuse bloque notre route vers la sortie de cette prison. Tuez-la.', '', 28153),
(153904, 'frFR', '', 'Une bête puissante nous empêche d\’établir un avant-poste sur cette plage. Débarrassez-vous-en afin que nous puissions nous dégager une voie.', 28153),
(153903, 'frFR', 'Moi aussi, je vais me déguiser, chef.', '', 28153),
(153902, 'frFR', 'Nos éclaireurs affirment que la Fierté de Kul Tiras est amarrée à Tol Dagor. Si leurs rapports sont exacts, vous allez devoir voler ce navire pour nous.', '', 28153),
(153901, 'frFR', '', 'Le surveillant a caché un objet de famille dans une maquette de navire. J\’aimerais que vous le récupériez.', 28153),
(153900, 'frFR', 'La machine de guerre de la Horde a besoin d\’armes et d\’un blindage. Récupérez ce que vous pouvez puis retrouvez-moi.', '', 28153),
(153899, 'frFR', '', 'Avec le chaos ambiant, il doit bien rester un peu de ravitaillement par ici. Voyons si nous pouvons récupérer quelques caisses sous leur nez.', 28153),
(153898, 'frFR', 'Ils ont assassiné ton père… trahi ton roi… et tu n\’as rien fait ! Vas-tu donc livrer tous tes alliés à la Horde ?', '', 28153),
(153897, 'frFR', 'Il n\’y a que des monstres dans la Horde. Il fallait s\’attendre à ce qu\’ils se retournent contre toi !', '', 28153),
(153896, 'frFR', 'Tu as accordé ta confiance à ces monstres, plus qu\’à ton propre sang !', '', 28153),
(153895, 'frFR', 'Tu as regardé ces animaux me mettre en pièces sans rien dire. Mais que t\’as rapporté ta trahison ?', '', 28153),
(153894, 'frFR', 'Une importante troupe de Trolls fanécorces approche de Stromgarde par l\’est. Renvoyez-en quelques-uns dans leurs pénates - et au pas de course - mais tuez le reste.', '', 28153),
(153893, 'frFR', 'Brûlez pas celui-là, matelot. On en aura besoin pour fuir cette île.', '', 28153),
(153892, 'frFR', 'Nombre de nos chevaucheurs de griffon ont été abattus. Aidez les survivants que vous rencontrerez sur le terrain.', '', 28153),
(153891, 'frFR', '', 'Maintenant, tu vois ! Maintenant, tu comprends ! G\’huun vous emportera tous !', 28153),
(153890, 'frFR', '', 'S\’ils libèrent ce monstre, c\’est la fin de Zuldazar !', 28153),
(153889, 'frFR', '', 'Je savais que les Trolls de sang représentaient une menace, mais je n\’aurais jamais imaginé… ça…', 28153),
(153888, 'frFR', 'Qui êtes-vous ?', 'Qui êtes-vous ?', 28153),
(153886, 'frFR', 'Salutations, $n. Le récit de vos exploits sur Azeroth nous est parvenu.', 'Salutations, $n. Le récit de vos exploits sur Azeroth nous est parvenu.', 28153),
(153885, 'frFR', 'Retournez aux profondeurs, infâmes abominations !', '', 28153),
(153884, 'frFR', 'Je crains que des fanatiques de la maison Chantorage tentent d\’étendre leur influence à Boralus. Dévoilez leur véritable visage.', '', 28153),
(153883, 'frFR', '', 'Alors la rumeur disait vrai. Au moins, les rues sont un peu plus sûres, maintenant.', 28153),
(153882, 'frFR', 'Venez, chers frères et sœurs. Nous combattrons ensemble !', '', 28153),
(153881, 'frFR', 'Ne vous arrêtez pas. Les ténèbres envahissent son esprit !', '', 28153),
(153880, 'frFR', '', 'Tiens bon, Sam, on y est presque !', 28153),
(153879, 'frFR', 'MARÉES DE SANG ! MONTEZ ! MONTEZ !', '', 28153),
(153878, 'frFR', '', 'Le bruit court que la garde de Boralus est à la solde des gangs. Vous pourriez enquêter ?', 28153),
(153877, 'frFR', 'Pfiou. Ça devrait les occuper pendant au moins… cinq bonnes minutes…', '', 28153),
(153876, 'frFR', 'Ho ! Ces oiseaux sont devenus fous ! Donnez-leur vite une friandise ou autre chose !', '', 28153),
(153875, 'frFR', 'Bon. Aucun de ces portefeuilles n\’est le mien mais… je vais les garder jusqu\’à ce qu\’on retrouve leurs propriétaires.', '', 28153),
(153874, 'frFR', 'Hein ? Mais… Où est mon portefeuille ? Minute ! C\’est ce morveux qui me l\’a piqué ? Attrapez-le !', '', 28153),
(153873, 'frFR', '', 'J\’espère que les autres ont pu trouver refuge.', 28153),
(153872, 'frFR', '', 'Les Vulpérins sont un peuple assez paisible. Nous nous déplaçons en caravane et glanons les fournitures que nous trouvons pour les revendre.', 28153),
(153871, 'frFR', 'Vous avez réussi, $p. Ai\’twen s\’éveille !', '', 28153),
(153870, 'frFR', '', 'Regardez ce que les Sephraks ont fait à notre foyer…', 28153),
(153869, 'frFR', '', 'Bon choix. Je peux me débrouiller avec ça.', 28153),
(153868, 'frFR', 'Des Rochepoings se préparent à attaquer Stromgarde. Montrez à ces ventres-à-bière ce qui est arrivé aux derniers Ogres qui ont tenté de souiller notre belle cité.', '', 28153),
(153867, 'frFR', 'Patience, Taelia. Ils viendront.', '', 28153),
(153866, 'frFR', '', 'Le reste de l\’équipage du Sillage des tempêtes arrivera-t-il ici à temps ?', 28153),
(153865, 'frFR', 'Vous obtiendrez certainement une récompense en reconduisant ces créatures dans leur village, près du lac, au sud-ouest. Mais si j\’étais vous, j\’éviterais l\’eau… Vous savez d\’où viennent les têtards, n\’est-ce pas ?', '', 28153),
(153864, 'frFR', 'Des têtards murlocs ont été aperçus en train de gambader dans le coin.', '', 28153),
(153863, 'frFR', 'Nos éclaireurs ont aperçu un chariot de minerai volé près de la mine nord-est. Reprenez-le par la force, si nécessaire.', '', 28153),
(153862, 'frFR', 'Nous avons repéré des bûcherons de la Horde sans escorte. Débitez-les en rondins !', '', 28153),
(153861, 'frFR', 'N\’oubliez pas que même s\’il est conscient, un arbre agressif a besoin d\’être taillé.', '', 28153),
(153860, 'frFR', 'Le seigneur-branche Aldrus a été aperçu près du bois.', '', 28153),
(153859, 'frFR', 'Le géant de pierre Fozruk arpente les routes au sud-est. Attention de ne pas vous faire piétiner.', '', 28153),
(153858, 'frFR', 'Que diriez-vous de le mettre à notre service et de le lâcher sur les lignes de la Horde ?', '', 28153),
(153857, 'frFR', 'Un énorme élémentaire de terre a été repéré sur la colline à l\’est.', '', 28153),
(153856, 'frFR', 'Courageux soldats de la ligue, c\’est le moment.', '', 28153),
(153855, 'frFR', 'Croisés, attaquez Ar\’gorok ! C\’est la volonté de la Lumière !', '', 28153),
(153854, 'frFR', 'La Horde tente de s\’emparer du filon de Galson. Montrons-lui qu\’elle est en train de creuser… sa tombe.', '', 28153),
(153853, 'frFR', 'La Horde attaque nos alliés à la scierie des Hautes-Terres. Montrez-lui de quel bois on se chauffe.', '', 28153),
(153852, 'frFR', 'Des troupes de la Horde sont entrées dans Stromgarde. Protégez votre commandant et montrez-leur la sortie, je vous prie.', '', 28153),
(153851, 'frFR', 'Haut-Perchoir est attaqué. Je vous suggère de voler dans les plumes de la Horde.', '', 28153),
(153850, 'frFR', '', 'Vous n\’avez qu\’un mot à dire pour qu\’on commence !', 28153),
(153849, 'frFR', '', 'Le chef de guerre attend de chaque héros de la Horde qu\’il soit paré au combat. Le moment me semble bien choisi pour un petit entraînement.', 28153),
(153848, 'frFR', '', 'Salutations et bienvenue en Silithus ! Notre mission est de tenir l\’Alliance à l\’écart des opérations d\’extraction d\’azérite.', 28153),
(153847, 'frFR', 'Tordu… déformé… Les murmures…', '', 28153),
(153846, 'frFR', 'Faites-moi signe quand vous voudrez commencer.', '', 28153),
(153845, 'frFR', 'Pendant que nous patrouillons en Silithus, révisons un peu vos techniques de combat.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'frFR', 'Bienvenue à bord ! Le roi Wrynn a besoin que tous les héros de l\’Alliance soient au mieux de leur forme pour affronter la Horde.', '', 28153),
(153843, 'frFR', 'Avancez prudemment. Cet endroit porte bien son nom.', '', 28153),
(153842, 'frFR', '', 'Impressionnant ! Ensuite, nous… Minute, qu\’est-ce que… ? Préparez-vous à combattre ! L\’Alliance nous attaque !', 28153),
(153841, 'frFR', 'La marée se lève… aucune échappatoire…', '', 28153),
(153840, 'frFR', 'Occupez les terrasses ! Donnez à Zul le temps nécessaire pour écraser ces pitoyables créatures.', '', 28153),
(153839, 'frFR', 'Des troupes de la Horde approchent du Cercle des Éléments. Que diriez-vous de leur donner une leçon primordiale ?', '', 28153),
(153838, 'frFR', '', 'Pour mon père !', 28153),
(153837, 'frFR', '', 'Je ne vais pas vous ménager !', 28153),
(153836, 'frFR', 'Très bien ! Ensuite, nous allons voir… Une minute, qu\’est-ce que… ? Aux armes ! La Horde nous attaque !', '', 28153),
(153835, 'frFR', '', 'Finissons-en !', 28153),
(153834, 'frFR', '', 'Pour Kul Tiras !', 28153),
(153833, 'frFR', 'La Horde attaque notre position à la croisée de Nordclos. Remettons-la sur le droit chemin.', '', 28153),
(153832, 'frFR', '', 'Métamorphose vous transforme en démon, ce qui renforce Frappe du chaos et Danse des lames.', 28153),
(153831, 'frFR', '', 'Nous sommes à vos côtés !', 28153),
(153830, 'frFR', 'La Horde est en route vers la passe de Vaillehuche. L\’ennemi est à nos portes. Accueillez-le chaleureusement.', '', 28153),
(153829, 'frFR', 'Métamorphose vous transforme en démon, ce qui renforce Frappe du chaos et Danse des lames.', '', 28153),
(153828, 'frFR', 'La Horde attaque Grangeneuve. Faites-la dégager, et au trot !', '', 28153),
(153827, 'frFR', '', 'Danse des lames est une série d\’attaques rapides qui frappent tous les ennemis proches.', 28153),
(153826, 'frFR', 'Danse des lames est une série d\’attaques rapides qui frappent tous les ennemis proches.', '', 28153),
(153825, 'frFR', '', 'Bien que coûteuse, c\’est votre attaque la plus puissante, vous devriez donc l\’utiliser aussi souvent que possible.', 28153),
(153824, 'frFR', 'Bien que coûteuse, c\’est votre attaque la plus puissante, vous devriez donc l\’utiliser aussi souvent que possible.', '', 28153),
(153823, 'frFR', '', 'Rayon accablant dissout vos ennemis en canalisant le chaos démoniaque qui brûle en vous.', 28153),
(153822, 'frFR', 'Rayon accablant dissout vos ennemis en canalisant le chaos démoniaque qui brûle en vous.', '', 28153),
(153821, 'frFR', '', 'C\’est une de vos attaques les plus puissantes. Utilisez-la souvent pour ne pas gâcher votre fureur.', 28153),
(153820, 'frFR', 'C\’est une de vos attaques les plus puissantes. Utilisez-la souvent pour ne pas gâcher votre fureur.', '', 28153),
(153819, 'frFR', 'Vous tombez à pic, j\’allais justement chercher des secours ! Ça m\’évite le déplacement.', '', 28153),
(153818, 'frFR', 'Soldats de la Horde en approche. Faites de votre mieux pour les repousser, d\’accord ?', '', 28153),
(153817, 'frFR', '', 'Utilisez Fulgurance sur le mannequin d\’entraînement.', 28153),
(153816, 'frFR', 'Utilisez Fulgurance sur le mannequin d\’entraînement.', '', 28153),
(153815, 'frFR', 'On dirait que nous avons mis le feu aux poudres. La Horde nous envoie tout ce qu\’elle a.', '', 28153),
(153814, 'frFR', '', 'Cette attaque dévastatrice renforce également votre prochaine Frappe mortelle. Pensez donc à l\’utiliser tôt et régulièrement.', 28153),
(153813, 'frFR', 'Cette attaque dévastatrice renforce votre prochaine Frappe mortelle, alors utilisez-la autant que possible.', '', 28153),
(153812, 'frFR', '', 'Fulgurance tire parti de votre force considérable pour porter un coup critique à l\’ennemi.', 28153),
(153811, 'frFR', 'Fulgurance tire parti de votre force considérable pour porter un coup dévastateur à l\’ennemi.', '', 28153),
(153810, 'frFR', '', 'Vous avez subi des dégâts, mais ce n\’est pas un problème pour vous.', 28153),
(153809, 'frFR', 'Vous avez subi des dégâts, mais ce n\’est pas un problème.', '', 28153),
(153804, 'frFR', 'Utilisez Drain de vie pour récupérer la totalité de vos points de vie.', '', 28153),
(153803, 'frFR', '', 'Utilisez Drain de vie pour récupérer la totalité de vos points de vie.', 28153),
(153802, 'frFR', '', 'Drain de vie consume l\’énergie vitale de votre cible, vous soignant à mesure qu\’il lui inflige des dégâts.', 28153),
(153801, 'frFR', 'Drain de vie consume l\’énergie vitale de votre cible, vous soignant à mesure qu\’il lui inflige des dégâts.', '', 28153),
(153798, 'frFR', '', 'Utilisez Trait de l\’ombre sur le mannequin d\’entraînement.', 28153),
(153797, 'frFR', 'Utilisez Trait de l\’ombre sur le mannequin d\’entraînement.', '', 28153),
(153796, 'frFR', '', 'Utilisez Trait de l\’ombre quand vous tourmentez déjà votre victime avec d\’autres sorts.', 28153),
(153795, 'frFR', 'Utilisez Trait de l\’ombre quand vous tourmentez déjà votre victime avec d\’autres sorts.', '', 28153),
