(153773, 'frFR', 'Morsure de serpent décoche une flèche enduite de poison, qui inflige des dégâts de Nature sur la durée.', '', 28153),
(153772, 'frFR', '', 'Vos aptitudes pour la survie vous fournissent de puissants outils pour infliger des dégâts aux ennemis.', 28153),
(153771, 'frFR', 'Vos aptitudes pour la survie vous fournissent de puissants outils pour infliger des dégâts aux ennemis.', '', 28153),
