(151114, 'frFR', '', '<Dying sounds: Total 5>', 28153),
(151113, 'frFR', 'Vous parliez de ces vermines, Reid ? Finissez-en. Maintenant.', '', 28153),
(151112, 'frFR', '', 'C\’est une arme à deux mains.', 28153),
(151111, 'frFR', '', 'Cette technique n\’est pas prête.', 28153),
(151110, 'frFR', '', 'Je ne peux pas encore m\’en servir.', 28153),
(151109, 'frFR', '', 'Ce n\’est pas prêt.', 28153),
(151108, 'frFR', '', 'Je peux pas mettre ça là.', 28153),
(151107, 'frFR', '', 'Ce sac est plein.', 28153),
(151106, 'frFR', '', 'Impossible de faire ça ici.', 28153),
(151105, 'frFR', '', 'Je ne peux pas m\’en débarrasser.', 28153),
(151104, 'frFR', '', 'Cet objet m\’est lié.', 28153),
(151103, 'frFR', '', 'Je ne peux pas m\’en équiper.', 28153),
(151102, 'frFR', '', 'Je n\’ai pas le niveau pour ça.', 28153),
(151101, 'frFR', 'Retournez au sanctuaire. La renaissance de la flotte est proche.', '', 28153),
(151100, 'frFR', '', 'Je ne peux pas encore utiliser ça.', 28153),
(151099, 'frFR', '', 'Ma compétence est trop basse pour ça.', 28153),
(151098, 'frFR', '', 'Ce n\’est pas fait pour moi.', 28153),
(151097, 'frFR', '', 'Je ne peux pas apprendre ce sort.', 28153),
(151096, 'frFR', '', 'Je ne peux pas le prendre.', 28153),
(151095, 'frFR', '', 'Ce n\’est pas à moi.', 28153),
(151094, 'frFR', '', 'Je dois m\’en approcher.', 28153),
(151093, 'frFR', '', 'Je suis trop loin.', 28153),
(151092, 'frFR', '', 'Je ne peux pas l\’atteindre.', 28153),
