(148626, 'frFR', 'Ohé !', 'Ohé !', 28153),
(148625, 'frFR', 'Bon vent !', 'Bon vent !', 28153),
(148624, 'frFR', 'Ne baissez jamais votre garde.', 'Ne baissez jamais votre garde.', 28153),
(148623, 'frFR', 'La loyauté avant tout.', 'La loyauté avant tout.', 28153),
(148622, 'frFR', 'Des problèmes à l\’horizon ?', 'Des problèmes à l\’horizon ?', 28153),
(148621, 'frFR', 'Nous touchons au but.', '', 28153),
(148620, 'frFR', 'La fine fleur des Portvaillant, pour vous servir.', 'La fine fleur des Portvaillant, pour vous servir.', 28153),
(148619, 'frFR', 'Bonne traversée !', 'Bonne traversée !', 28153),
(148618, 'frFR', 'Puissiez-vous avoir le vent en poupe.', 'Puissiez-vous avoir le vent en poupe.', 28153),
(148617, 'frFR', 'Gardez toujours un œil sur l\’horizon.', 'Gardez toujours un œil sur l\’horizon.', 28153),
(148616, 'frFR', 'Faites bon voyage.', 'Faites bon voyage.', 28153),
(148615, 'frFR', 'Les panses de ravasaure ont bien des utilités ! On peut les faire mijoter, frire, revenir… Hmm. Rien que d\’en parler, j\’en ai l\’estomac qui gargouille !', '', 28153),
(148614, 'frFR', 'Je vous souhaite bon voyage.', 'Je vous souhaite bon voyage.', 28153),
(148613, 'frFR', 'Merci de votre visite.', 'Merci de votre visite.', 28153),
(148612, 'frFR', 'N\’hésitez pas à repasser !', 'N\’hésitez pas à repasser !', 28153),
(148611, 'frFR', 'Ma femme, elle prétend que les ravasaures peuvent avaler n\’importe quoi ! Si c\’est vrai, leur panse, elle doit être comme l\’acier ! Rapportez-m\’en… sans qu\’elle s\’en rende compte.', '', 28153),
(148610, 'frFR', 'Besoin de quelque chose ?', 'Besoin de quelque chose ?', 28153),
(148609, 'frFR', 'Quelque chose à signaler ?', 'Quelque chose à signaler ?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'frFR', 'Les meilleurs produits de tout Kul Tiras.', 'Les meilleurs produits de tout Kul Tiras.', 28153),
(148607, 'frFR', 'Ici, on vend que du premier choix.', 'Ici, on vend que du premier choix.', 28153),
(148606, 'frFR', 'Que puis-je faire pour vous ?', 'Que puis-je faire pour vous ?', 28153),
(148605, 'frFR', 'Loué soit l\’amiral suprême !', 'Loué soit l\’amiral suprême !', 28153),
(148604, 'frFR', 'Que la tempête vous épargne.', 'Que la tempête vous épargne.', 28153),
(148603, 'frFR', 'Bien le bonjour.', 'Bien le bonjour.', 28153),
(148602, 'frFR', 'Un verre, ça vous dit ?', 'Un verre, ça vous dit ?', 28153),
(148601, 'frFR', 'Évitez les ruelles sombres.', 'Évitez les ruelles sombres.', 28153),
(148600, 'frFR', 'Tenez bon la barre.', 'Tenez bon la barre.', 28153),
(148599, 'frFR', 'La ville n\’est plus sûre de nos jours.', 'La ville n\’est plus sûre de nos jours.', 28153),
(148598, 'frFR', 'Si vous découvrez quoi que ce soit, criez ! Votre nom passera à la postérité.', '', 28153),
(148597, 'frFR', 'Si nous la trouvons, l\’empereur soumettra le monde entier pour la gloire de la civilisation sephrak ! J\’ai toujours rêvé de voyager.', '', 28153),
(148596, 'frFR', 'Le dormeur finira par se réveiller.', '', 28153),
(148595, 'frFR', 'S\’il se réveille vraiment, qui sera à l\’abri ?', '', 28153),
(148594, 'frFR', 'Vous croyez vraiment qu\’elle existe, cette clé ?', '', 28153),
(148593, 'frFR', 'L\’empereur Korphek croit qu\’en trouvant la clé, on pourra unir à nouveau les Sephraks.', '', 28153),
(148592, 'frFR', 'Vous avez entendu quelque chose ?', '', 28153),
(148591, 'frFR', 'Je sers les intérêts de l\’empire, chef.', '', 28153),
(148590, 'frFR', 'Ces mauviettes de « Dévoués » courberont bientôt l\’échine.', '', 28153),
(148589, 'frFR', 'Il y a un sacré vent aujourd\’hui.', 'Il y a un sacré vent aujourd\’hui.', 28153),
(148588, 'frFR', 'Quel bon vent vous amène ?', 'Quel bon vent vous amène ?', 28153),
(148587, 'frFR', 'Le Surveillant dit que la clé est ici. Plus vite on la trouvera, plus vite on lèvera le camp. Cet endroit me file la frousse.', '', 28153),
(148586, 'frFR', 'Que la tempête vous épargne.', 'Que la tempête vous épargne.', 28153),
(148585, 'frFR', 'Les Portvaillant nous protégeront, comme ils l\’ont toujours fait.', 'Les Portvaillant nous protégeront, comme ils l\’ont toujours fait.', 28153),
(148584, 'frFR', 'Que les vents vous soient favorables.', 'Les vents vous soient favorables.', 28153),
(148583, 'frFR', 'Je crains que nous ne connaissions jamais la paix.', 'Je crains que nous ne connaissions jamais la paix.', 28153),
(148582, 'frFR', 'Quelles sont les nouvelles du continent ?', 'Quelles sont les nouvelles du continent ?', 28153),
(148581, 'frFR', 'Nous vivons des heures bien troubles.', 'Nous vivons des heures bien troubles.', 28153),
(148580, 'frFR', 'Revenez nous voir, nos stocks changent tous les jours.', 'Revenez nous voir, nos stocks changent tous les jours.', 28153),
(148579, 'frFR', 'On reçoit régulièrement des produits exotiques.', 'On reçoit régulièrement des produits exotiques.', 28153),
(148578, 'frFR', 'N\’hésitez pas à revenir.', 'N\’hésitez pas à revenir.', 28153),
(148577, 'frFR', 'Une envie particulière ?', 'Une envie particulière ?', 28153),
(148576, 'frFR', 'Parlons peu, mais parlons bien.', 'Parlons peu, mais parlons bien.', 28153),
(148575, 'frFR', 'Ce n\’est… pas fini…', '', 28153),
(148574, 'frFR', 'Vous arrivez trop tard…', '', 28153),
(148573, 'frFR', 'Nul ne peut nous arrêter…', '', 28153),
(148572, 'frFR', 'Ces terres… nous appartiendront…', '', 28153),
(148571, 'frFR', 'Je retourne… aux Ulterres…', '', 28153),
(148570, 'frFR', 'Parlons affaires.', 'Parlons affaires.', 28153),
(148569, 'frFR', 'La vengeance sera nôtre !', '', 28153),
(148568, 'frFR', 'Aucune pitié !', '', 28153),
(148567, 'frFR', 'Les Drust reprendront ces terres !', '', 28153),
(148566, 'frFR', 'À genoux devant Gorak Tul !', '', 28153),
(148565, 'frFR', 'Je suis réveillé !', '', 28153),
(148564, 'frFR', 'Vous n\’avez donc rien de plus important à faire ? Quoi que ce soit !', 'N\’avez-vous donc rien de plus important à faire ? Quoi que ce soit !', 28153),
(148563, 'frFR', 'Là-bas, quelqu\’un vous appelle ! Vous entendez ? Cela m\’a l\’air de la plus haute importance !', 'Là-bas, quelqu\’un vous appelle ! Vous entendez ? Cela m\’a l\’air de la plus haute importance !', 28153),
(148562, 'frFR', 'Ciel ! Il se fait tard. Vous vous apprêtiez à partir, je suppose ?', 'Ciel ! Il se fait tard. Vous vous apprêtiez à partir, je suppose ?', 28153),
(148561, 'frFR', 'Voguez à pleines voiles.', 'Voguez à pleines voiles.', 28153),
(148560, 'frFR', 'Portez-vous bien.', 'Portez-vous bien.', 28153),
(148559, 'frFR', 'Maintenez le cap.', 'Maintenez le cap.', 28153),
(148553, 'frFR', 'Réduisons cet endroit en cendres !', 'Tuez-les comme le ferait Nisha !', 28153),
(148552, 'frFR', 'Bonne chance à vous.', 'Bonne chance à vous.', 28153),
(148551, 'frFR', 'Le prochain infidèle est pour moi !', 'J\’en ferai bon usage !', 28153),
(148550, 'frFR', 'C\’est bon d\’avoir de nouveau une arme entre les mains.', 'Je vais leur apprendre à craindre les Vulpérins !', 28153),
(148549, 'frFR', 'Enchanté.', 'Enchantée.', 28153),
(148548, 'frFR', 'Que me vaut ce plaisir ?', 'Que me vaut ce plaisir ?', 28153),
(148547, 'frFR', '', 'Oh, ce sera parfait ! Ne vous inquiétez pas pour Raal, il s\’en remettra.', 28153),
(148546, 'frFR', '', 'Mon mari, il rechigne à récupérer la salive de pterreurdactyle pour nos potions. Il est trop gentil. Allez-y, vous, et rapportez toutes les glandes que vous pourrez !', 28153),
(148545, 'frFR', 'Beau travail. Ces parchemins vont occuper nos sages un moment.', '', 28153),
(148544, 'frFR', 'Avez-vous eu vent de quelque rumeur ?', 'Avez-vous eu vent de quelque rumeur ?', 28153),
(148543, 'frFR', 'Ravi de faire votre connaissance !', 'Ravie de faire votre connaissance !', 28153),
(148542, 'frFR', 'Les ignobles Trolls de sang, ils ont massacré de nombreux Tortollans. Tentons de sauver leurs découvertes. Rapportez tous les parchemins que vous trouverez !', '', 28153),
(148541, 'frFR', 'Ne vous avisez pas de me mener en bateau !', 'Ne vous avisez pas de me mener en bateau !', 28153),
(148540, 'frFR', '', 'Ce n\’est pas… possible…', 28153),
(148539, 'frFR', 'Ah, voilà la violence qu\’engendre le système !', 'Ah, voilà la violence qu\’engendre le système !', 28153),
(148538, 'frFR', '', 'Ma magie a… échoué ?', 28153),
(148537, 'frFR', '', 'J\’étais promise à… de grandes choses…', 28153),
(148536, 'frFR', 'Tant qu\’elles seront prisonnières, je ne pourrai accepter de nouveaux disciples. Ce serait contraire à l\’honneur.', '', 28153),
(148535, 'frFR', 'Je rêve ou vous venez de me lancer un cimeterre à la tête ?', 'Je rêve ou vous venez de me lancer un cimeterre à la tête ?', 28153),
(148534, 'frFR', '', 'La puissance… elle m\’échappe…', 28153),
(148533, 'frFR', '', 'Mes sœurs s\’occuperont de vous…', 28153),
(148532, 'frFR', '', 'Du sang frais pour mes rituels !', 28153),
(148531, 'frFR', '', 'Vous ferez un digne sacrifice !', 28153),
(148530, 'frFR', '', 'Tous serviront le Sabbat malecarde !', 28153),
(148529, 'frFR', '', 'Mère, accorde-moi ta puissance !', 28153),
(148528, 'frFR', 'Mais, à l\’instant où je plantais mes crocs dans le cœur de la sorcière qui les commandait, elle condamna les âmes de mes disciples à d\’éternels tourments.', '', 28153),
(148527, 'frFR', '', 'Ma vie pour le Sabbat !', 28153),
(148526, 'frFR', 'Je me moque qu\’elle soit morte. Ça en fera une de moins en travers de mon chemin.', '', 28153),
(148525, 'frFR', 'Tout de même, avoir recours à la sorcellerie pour se venger de moi…', '', 28153),
(148524, 'frFR', 'J\’ai traqué les Nagas restants jusqu\’au dernier. Aucun n\’a échappé à mon courroux…', '', 28153),
(148523, 'frFR', 'Au diable Petula et Benjamin. Mon travail, c\’est ce que j\’ai de plus précieux, c\’est l\’œuvre de toute ma vie.', '', 28153),
(148522, 'frFR', 'Je suis parti de rien ! J\’ai fondé cette entreprise pour subvenir aux besoins de ma femme et de notre famille.', '', 28153),
(148521, 'frFR', 'Gloire à la maison Malvoie !', 'Gloire à la maison Malvoie !', 28153),
(148520, 'frFR', 'Je n\’ai pas toujours été directeur d\’un chantier de bois prospère, vous savez.', '', 28153),
(148519, 'frFR', 'Ne trempez pas dans les affaires des sorcières.', 'Ne trempez pas dans les affaires des sorcières.', 28153),
(148518, 'frFR', 'Méfiez-vous de l\’eau qui dort.', 'Méfiez-vous de l\’eau qui dort.', 28153),
(148517, 'frFR', 'Je vous prierai de garder vos distances.', 'Je vous prierai de garder vos distances.', 28153),
(148516, 'frFR', 'Dans quel camp êtes-vous ?', 'Dans quel camp êtes-vous ?', 28153),
(148515, 'frFR', 'Que puis-je pour vous ?', 'Que puis-je pour vous ?', 28153),
(148514, 'frFR', 'Il y a des siècles, les Nagas ont attaqué ce temple. Je suis arrivé trop tard pour sauver mes serviteurs.', '', 28153),
(148513, 'frFR', 'Je compatis avec les Tortaka et je comprends leur détresse face aux Nagas, mais je ne peux les protéger.', '', 28153),
(148512, 'frFR', 'Puisse la mer vous accorder ses faveurs.', 'Puisse la mer vous accorder ses faveurs.', 28153),
(148511, 'frFR', 'Mieux vaut flotter sans grâce que couler en beauté.', 'Mieux vaut flotter sans grâce que couler en beauté.', 28153),
(148510, 'frFR', 'Nous reprendrons ce qui nous appartient.', 'Nous reprendrons ce qui nous appartient.', 28153),
(148509, 'frFR', 'Les choses étaient plus simples autrefois.', 'Les choses étaient plus simples autrefois.', 28153),
(148508, 'frFR', 'Toute aide est la bienvenue.', 'Toute aide est la bienvenue.', 28153),
(148507, 'frFR', 'Vous n\’êtes pas d\’ici, je me trompe ?', 'Vous n\’êtes pas d\’ici, je me trompe ?', 28153),
(148506, 'frFR', 'La vallée Chantorage retrouvera sa pureté.', 'La vallée Chantorage retrouvera sa pureté.', 28153),
(148505, 'frFR', 'Méfiez-vous des menaces tapies dans les profondeurs.', 'Méfiez-vous des menaces tapies dans les profondeurs.', 28153),
(148504, 'frFR', 'Puisse la mer vous être clémente.', 'Puisse la mer vous être clémente.', 28153),
(148503, 'frFR', 'Nous devons surmonter cette épreuve.', 'Nous devons surmonter cette épreuve.', 28153),
(148502, 'frFR', 'Ceux qui honorent la mer seront toujours les bienvenus.', 'Ceux qui honorent la mer seront toujours les bienvenus.', 28153),
(148501, 'frFR', 'Les enfants de la mer sont toujours les bienvenus.', 'Les enfants de la mer sont toujours les bienvenus.', 28153),
(148500, 'frFR', 'Nous restaurerons l\’unité de notre vallée.', 'Nous restaurerons l\’unité de notre vallée.', 28153),
(148499, 'frFR', 'Ouvrez l\’œil, et le bon.', 'Ouvrez l\’œil, et le bon.', 28153),
(148498, 'frFR', 'N\’oubliez jamais le chant de l\’orage.', 'N\’oubliez jamais le chant de l\’orage.', 28153),
(148497, 'frFR', 'Notre détermination ne fléchira jamais.', 'Notre détermination ne fléchira jamais.', 28153),
(148496, 'frFR', 'Les Chantorage perdureront.', 'Les Chantorage perdureront.', 28153),
(148495, 'frFR', 'Vous venez de loin, on dirait.', 'Vous venez de loin, on dirait.', 28153),
(148493, 'frFR', 'Pareil pour vous. Quant à vous, $n, vous avez un sacré mojo. Si vous passez en Vol\’dun, faites-moi signe, d\’accord ?', '', 28153),
(148492, 'frFR', 'Au revoir, Jin\’Tiki. Restez en vie.', '', 28153),
(148491, 'frFR', 'Je m\’en occupe.', '', 28153),
(148490, 'frFR', 'La chose est entendue. Allons-y.', '', 28153),
(148489, 'frFR', 'Ha ! Je n\’avais jamais fait quelque chose d\’aussi fou.', '', 28153),
(148488, 'frFR', 'Zulajin, il est mort ! Ne restons pas ici.', '', 28153),
(148487, 'frFR', 'Beau travail ! Continuez comme ça !', '', 28153),
(148486, 'frFR', 'Iiiiiik !', 'Iiiiiik !', 28153),
(148485, 'frFR', 'Ne me mangez pas !', 'Ne me mangez pas !', 28153),
(148484, 'frFR', 'Argh !', 'Argh !', 28153),
(148483, 'frFR', 'Sur quoi travaillait papa pour qu\’on en arrive là ?', '', 28153),
(148482, 'frFR', 'Comment ça se fait que le miel se déplace tout seul, hein ?', '', 28153),
(148481, 'frFR', '<S\’étrangle.> Dites, $p… c\’est moi ou… ou le miel est… v-vivant ?', '', 28153),
(148480, 'frFR', 'Merci !', 'Merci !', 28153),
(148479, 'frFR', 'Comptez sur moi pour veiller à ce que les Sephraks repartent les mains vides.', 'Comptez sur moi pour veiller à ce que les Sephraks repartent les mains vides.', 28153),
(148478, 'frFR', 'On va jouer à un petit jeu. Je l\’appelle « le Serpent et le Renard »…', 'On va jouer à un petit jeu. Je l\’appelle « le Serpent et le Renard »…', 28153),
(148477, 'frFR', 'Wouhou ! Je suis libre ! Vous ne m\’avez pas mangé !', 'Wouhou ! Je suis libre ! Vous ne m\’avez pas mangé !', 28153),
(148476, 'frFR', 'Cette fois, c\’en est trop. J\’exige une augmentation.', 'Cette fois, c\’en est trop. J\’exige une augmentation.', 28153),
(148475, 'frFR', '', 'Ravie de voir que le désert n\’a pas encore eu raison de vous, $n !', 28153),
(148473, 'frFR', 'Ô noble Loa, accepte cette offrande de la tribu Tortaka.', 'Ô noble Loa, accepte cette offrande de la tribu Tortaka.', 28153),
(148472, 'frFR', 'Lâchez ça !', '', 28153),
(148471, 'frFR', 'Hé là, pas si vite !', '', 28153),
(148470, 'frFR', 'Vous allez le regretter.', '', 28153),
(148469, 'frFR', 'Je ne ferais pas ça à votre place.', '', 28153),
(148468, 'frFR', 'Rendez-moi ça !', '', 28153),
(148467, 'frFR', 'Je ne crois pas, non ! C\’est à moi, ça.', '', 28153),
(148466, 'frFR', 'On touche avec les yeux !', '', 28153),
(148463, 'frFR', 'Mauvaise décision.', '', 28153),
(148462, 'frFR', 'Je ne dis jamais non à un bon combat.', '', 28153),
(148461, 'frFR', 'Vous allez payer cher vos méfaits !', '', 28153),
(148460, 'frFR', 'Vous, là-bas !', '', 28153),
(148459, 'frFR', 'Vous allez le regretter !', '', 28153),
(148458, 'frFR', 'Hors de question !', '', 28153),
(148456, 'frFR', 'Faites attention.', '', 28153),
(148455, 'frFR', 'Ma longue-vue est sur la corniche inférieure qui surplombe le cratère, au nord.', '', 28153),
(148454, 'frFR', '', 'De la dinomancie navrecorne ! C\’est extra. Maintenant, rangeons-les hors de portée de Kojo.', 28153),
(148453, 'frFR', '', 'J\’ai déterré un ensemble de vieux parchemins, mais quant à ce qu\’ils font, c\’est mystère et boule de gomme. Essayez-les pour voir quels effets ils ont, ça pourrait être marrant !', 28153),
(148452, 'frFR', 'Le fétiche, utilisez-le ! Taillez-moi ça en pièces !', '', 28153),
(148451, 'frFR', 'FUYEZ !', '', 28153),
(148450, 'frFR', 'AAAAHHH !', '', 28153),
(148449, 'frFR', 'Euh… il y a quelque chose qui cloche. Ça sent la magie du sang à plein nez, par là…', '', 28153),
(148448, 'frFR', 'Vous avez réussi ! Zulajin, sa dernière heure a sonné.', '', 28153),
(148447, 'frFR', 'Haha ! Il faut que je raconte ça à Pa\’ku !', '', 28153),
(148446, 'frFR', 'Les Sacrenuit ont une idée pour se débarrasser des envahisseurs à Xibala. Je sens que ça va être drôle.', '', 28153),
(148420, 'frFR', '', 'Bien joué. Peut-être qu\’un jour, ces eaux seront de nouveau sûres.', 28153),
(148419, 'frFR', '', 'Bouclez-la, vous deux ! Vous nous avez assez cassé les oreilles !', 28153),
(148418, 'frFR', '', 'Bien, nous voilà au complet. Il n\’y a pas une minute à perdre.', 28153),
(148416, 'frFR', 'Merci. Ces satanés Trolls de sang, ils méritaient pas meilleur sort.', '', 28153),
(148415, 'frFR', 'Ces dégénérés profanent le cadavre d\’un Loa… Ça va pas se passer comme ça ! Massacrez-les !', '', 28153),
(148414, 'frFR', '', 'C\’est qui, le gentil petit prédateur mortel, c\’est qui ?', 28153),
(148413, 'frFR', '', 'Nos puissants alliés doivent apprendre à combattre l\’ennemi. Montrez à ce petit gars à quoi ressemble une bataille.', 28153),
(148412, 'frFR', 'Ainsi va la parabole :\n\nUn jour, l\’auguste Loa s\’adressa à un groupe de fidèles :\n\n« À l\’image du jaguar qui traque sa proie des jours durant, le sage cultive la patience en toutes circonstances. Seuls les insensés se laissent gouverner par leurs passions et leurs émotions, mais ceux-là ne survivent guère dans la jungle.\n\nEn outre, si la jungle fait naître la vie, elle donne aussi la mort. L\’homme clairvoyant voit bien que la nature ne lui appartient pas, mais que c\’est lui qui appartient à la nature. Partant, il respecte l\’ordre naturel et ne prend que le strict nécessaire pour survivre. »\n\nEn entendant ces paroles, le cœur des disciples d\’Eraka no Kimbul se gonfla de patience et de respect.', '', 28153),
(148411, 'frFR', 'Ainsi va la parabole :\n\nUn jour, l\’auguste Loa s\’adressa à un groupe de fidèles :\n\n« À l\’image du roi qui jamais n\’échangerait son plus précieux trésor contre une vulgaire poignée de terre, l\’homme d\’honneur ne brade pas son intégrité sur l\’autel de la gloire ou de la richesse. Vivez votre vie dans l\’honneur, et vous aurez bien vécu.\n\nÀ l\’instar de l\’eau vive qui creuse inlassablement ses sillons dans la pierre, tous les hauts faits sont le fruit de la persévérance. Vivez votre vie avec détermination, et l\’échec n\’aura jamais raison de vous. »\n\nEn entendant ces paroles, le cœur des disciples d\’Eraka no Kimbul se gonfla de vertu et de ténacité.', '', 28153),
(148410, 'frFR', 'Ainsi va la parabole :\n\nUn jour, l\’auguste Loa s\’adressa à un groupe de fidèles :\n\n« À l\’image du tigre qui traque son gibier sans relâche par monts et par vaux, le brave ne cède pas une seule seconde face à la peur. Faites preuve de courage en toutes circonstances et jamais votre proie ne vous échappera.\n\nÀ l\’instar de la flétrissure qui ronge peu à peu les fleurs de la jungle, l\’âge sape l\’énergie de la jeunesse. La puissance prend sa source non dans la force brute, mais dans la volonté indomptable qui, par nature, est insensible aux outrages du temps. »\n\nEn entendant ces paroles, le cœur des disciples d\’Eraka no Kimbul se gonfla de courage et de conviction.', '', 28153),
(148408, 'frFR', 'Eraka no Kimbul, Loa des tigres, seigneur des bêtes, roi des félins et malédiction des proies.', '', 28153),
(148400, 'frFR', 'Nombre de mes cicatrices sont plus vieilles que votre… dialecte.', '', 28153),
(148399, 'frFR', 'Je cherche quelqu\’un de jeune et vif, qui ne craint pas d\’endosser un rôle majeur face aux forces du mal… ce dans un but lucratif.', '', 28153),
(148398, 'frFR', '', 'Que puis-je pour vous, mon enfant ?', 28153),
(148397, 'frFR', 'Ça bosse ici, tête d\’écaille !', 'Ça bosse ici, tête d\’écaille !', 28153),
(148396, 'frFR', 'Vous rirez moins quand nous serons libres.', 'Vous rirez moins quand nous serons libres.', 28153),
(148395, 'frFR', 'D\’accord ! D\’accord !', 'D\’accord ! D\’accord !', 28153),
(148394, 'frFR', 'Hé ! Lâchez-moi !', 'Hé ! Lâchez-moi !', 28153),
(148393, 'frFR', '<La statue est ornée de gravures, mais leur signification, si tant est qu\’elles en aient une, s\’est perdue dans les limbes de l\’histoire.>', '', 28153),
(148392, 'frFR', '<La statue est ornée de gravures, mais leur signification, si tant est qu\’elles en aient une, s\’est perdue dans les limbes de l\’histoire.>', '<La statue est ornée de gravures, mais leur signification, si tant est qu\’elles en aient une, s\’est perdue dans les limbes de l\’histoire.>', 28153),
(148391, 'frFR', '<La statue est ornée de gravures, mais leur signification, si tant est qu\’elles en aient une, s\’est perdue dans les limbes de l\’histoire.>', '', 28153),
(148389, 'frFR', 'Quand Sulphis fut assassiné, il avait déjà mis sa clé en lieu sûr. Les disciples de Sephraliss furent contraints de fuir et de vivre cachés. Depuis ce jour, nous combattons les infidèles sans relâche.', '', 28153),
(148388, 'frFR', 'Korphek leva une armée de partisans sephraks à laquelle il ordonna de massacrer tous ses opposants.', '', 28153),
(148387, 'frFR', '', 'Il faut prévenir la princesse.', 28153),
(148386, 'frFR', '', 'Une arme… c\’est ce que doit rechercher Jakra\’zet ! Un C\’Thrax…', 28153),
(148385, 'frFR', 'Il complotait pour exhumer le général c\’thraxxi, résolu à se servir de lui pour conquérir le continent.', '', 28153),
(148384, 'frFR', 'Au fil du temps, Korphek se lassa de ce statu quo. Nous entretenions des relations pacifiques avec nos voisins trolls, mais c\’est la guerre qu\’il désirait.', '', 28153),
(148383, 'frFR', 'Nous connûmes une longue période de paix, comme Sephraliss l\’aurait souhaité, malgré la perte de nos terres et de notre Loa. Nous savions qu\’un jour, Sephraliss reviendrait.', '', 28153),
(148382, 'frFR', 'Souhaitant renforcer la barrière encore davantage, chacun d\’entre nous créa une clé, les trois devant être réunies pour venir à bout de la magie protectrice. Ainsi naquirent les Gardes.', '', 28153),
(148381, 'frFR', 'Tous ceux qui restèrent loyaux à Sephraliss furent forcés de fuir et de se cacher. Nous affrontons les infidèles depuis lors.', '', 28153),
(148380, 'frFR', 'Korphek leva une armée de Sephraks à la même idéologie, et ils commencèrent à massacrer tous leurs opposants… Sulphis fut le premier à tomber, mais pas avant d\’avoir mis sa clé en sécurité.', '', 28153),
(148379, 'frFR', 'Alors que les sables continuaient de s\’étendre, Korphek prit goût à la guerre. Il complota le retour du C\’Thrax afin de l\’utiliser comme arme pour conquérir le continent.', '', 28153),
(148378, 'frFR', 'Malgré son immense pouvoir, Sulphis ne pouvait créer la barrière seul. Korphek et moi lui apportâmes notre aide, et ensemble, nous enfermâmes Mythrax dans la grande pyramide.', '', 28153),
(148377, 'frFR', 'Après avoir été témoins de sa puissance destructrice, nous fîmes en sorte que nul ne puisse plus jamais relever Mythrax.', '', 28153),
(148376, 'frFR', 'Notre Loa se sacrifia pour nous sauver de cette monstruosité. Elle vint à bout du C\’Thrax, mais ce dernier avait déjà détruit le disque caché au cœur d\’Atul\’Aman.', '', 28153),
(148375, 'frFR', 'Il y a bien longtemps, Mythrax le Disloqueur s\’en prit à nos terres, massacrant Trolls et Sephraks sans distinction.', '', 28153),
(148374, 'frFR', 'Cette clé appartient au premier Garde. Il s\’appelait Sulphis, et fut tué par Korphek.', '', 28153),
(148365, 'frFR', '', 'Alors, ça, c\’est du Maynard tout craché. Cet incapable se cache toujours derrière ses gros bras. Approchez, je vais m\’occuper de votre cas comme je l\’ai fait avec les autres !', 28153),
(148364, 'frFR', 'Une sorcière… pourquoi une sorcière s\’en prendrait-elle à notre exploitation ?! Il faut que je sorte d\’ici. Je vais en informer mon père.', '', 28153),
(148361, 'frFR', 'François remarque votre bourse bien garnie et vous juge digne de son intérêt.', '', 28153),
(148360, 'frFR', 'Vous faites tinter le contenu de votre bourse.', 'Vous faites tinter le contenu de votre bourse.', 28153),
(148359, 'frFR', 'Si vous parvenez à éliminer cette araignée... vous rendrez service à beaucoup de gens.', '', 28153),
(148358, 'frFR', 'Parfait... On dirait que vous avez dégagé la voie. Je devrais pouvoir sortir d\’ici par mes propres moyens.', '', 28153),
(148357, 'frFR', 'François vous picore les pieds d\’un air dédaigneux.', '', 28153),
(148356, 'frFR', 'L\’empereur vous réglera votre compte.', '', 28153),
(148355, 'frFR', 'Vous troublez mon repas, $pr. J\’en ai tué pour moins que ça.', '', 28153),
(148354, 'frFR', '<Donner la pierre de Sulphis à Vorrik.>', '<Donner la pierre de Sulphis à Vorrik.>', 28153),
(148353, 'frFR', 'La voie, elle est libre ! Qui aurait cru que le mojo de grenouille, c\’était aussi fort ?', '', 28153),
(148352, 'frFR', 'Les Nagas, ils siphonnent la puissance du Loa grenouille ! Arrêtez-les et détruisez leur camp !', '', 28153),
(148351, 'frFR', 'Mes compagnons ailés, ils sont prêts à vous emmener où vous voulez, avec ma bénédiction en prime.', 'Mes compagnons ailés, ils sont prêts à vous emmener où vous voulez, avec ma bénédiction en prime.', 28153),
(148350, 'frFR', 'Je revis ! Merci. Si vous avez besoin de mes services, n\’hésitez pas.', 'Je revis ! Merci. Si vous avez besoin de mes services, n\’hésitez pas.', 28153),
(148349, 'frFR', 'Que Bwonsamdi vous bénisse !', 'Que Bwonsamdi vous bénisse !', 28153),
(148348, 'frFR', 'Jolie pierre à moi ! Pas vous !', '', 28153),
(148347, 'frFR', '', 'Nous devons parler à Vorrik.', 28153),
(148345, 'frFR', 'Baissez vos armes. S\’ils cherchent Vorrik, ils peuvent peut-être nous aider…', '', 28153),
(148344, 'frFR', 'Je renais ! Merci !', 'Je renais ! Merci !', 28153),
(148342, 'frFR', '', 'Je vois que vous avez amené des renforts.', 28153),
(148340, 'frFR', '', 'Du calme, tout le monde. Cette personne est dans notre camp.', 28153),
(148339, 'frFR', 'Eh oui ! Le truc, c\’est les coquillages, Nimmo. Faut savoir les apprécier…', '', 28153),
(148338, 'frFR', 'L\’espace d\’une minute, le temps s\’est arrêté. J\’avais froid, j\’avais chaud… et je disais donc…', '', 28153),
(148337, 'frFR', 'Alors, Korl, il a pris cette lame… et ses yeux, c\’est comme si… ils s\’étaient éteints…', '', 28153),
(148336, 'frFR', 'Toutes nageoires dehors, armés jusqu\’aux dents, ça les faisait marrer… Il faisait tout noir… et y avait du sang partout…', '', 28153),
(148335, 'frFR', 'C\’était le coin le plus barbant des mers… et puis, tout a changé… le jour où ils ont débarqué…', '', 28153),
(148334, 'frFR', 'Enfin bref, c\’était épique ! Terrible, même !', '', 28153),
(148333, 'frFR', 'Attendez, vous sortez d\’où, au juste ? Non, parce que ça m\’a déjà joué des tours…', '', 28153),
(148332, 'frFR', 'Nom d\’une matelote au Naga, je rêve… Tout le monde en a entendu parler !', '', 28153),
(148331, 'frFR', 'QUOI ? Vous avez jamais entendu parler de la fosse de Scarvin ?', '', 28153),
(148330, 'frFR', 'Vous savez, la bataille de la fosse de Scarvin ? Dans les profondeurs...', '', 28153),
(148329, 'frFR', 'Bref, Korl et moi, on était en train de parler de cette bataille.', '', 28153),
(148328, 'frFR', 'Vous me plaisez bien, petite tête d\’écaille.', '', 28153),
(148327, 'frFR', 'Je l\’ai vu une fois. C\’était incroyaaaable !', '', 28153),
(148326, 'frFR', 'Vous saviez qu\’un feu brûlait, là, sous les eaux ?', '', 28153),
(148325, 'frFR', 'Bref, c\’est pas là où je voulais en venir. Ce que je veux dire, c\’est que…', '', 28153),
(148324, 'frFR', 'Ben, lui, même pas. Il m\’a regardé comme ça et puis il a écrabouillé un crabe…', '', 28153),
(148323, 'frFR', 'Vous, vous feriez au moins semblant de vous y intéresser, pas vrai ?', '', 28153),
(148322, 'frFR', 'Ça m\’a rendu triste.', '', 28153),
(148321, 'frFR', 'Un jour, j\’ai trouvé un coquillage. Il était drôlement beau. J\’en ai parlé à Korl, mais il en avait rien à cirer.', '', 28153),
(148320, 'frFR', 'Moi, j\’aime pas les bernacles. Korl, il dit qu\’y a que les sales types pour aimer ça.', '', 28153),
(148318, 'frFR', 'Tant de choses ont changé depuis l\’époque où Korphek et moi enseignions ensemble la sagesse de Sephraliss en ces lieux…\n\nÀ présent, les sites sacrés sont en ruines et Sephraliss a sombré dans l\’oubli, quand elle ne fait pas l\’objet d\’une haine farouche.\n\nKorphek… Qu\’as-tu fait à notre peuple, mon vieil ami ?', '', 28153),
(148317, 'frFR', 'Les bernacles, c\’est casse-pieds. Vous aimez ça, vous, m\’sieur Nimmo ?', '', 28153),
(148316, 'frFR', 'J\’aime pas les bernacles, ça me colle de sacrées démangeaisons. D\’ailleurs, Korl non plus, il aime pas ça.', '', 28153),
(148315, 'frFR', 'Les bernacles, c\’est casse-pieds.', '', 28153),
(148314, 'frFR', 'Je disais donc, mon pote Korl… Vous le connaissez, Korl ? Bref, mon pote Korl, il dit que rien ne vaut un petit coup de baliste entre les orteils pour faire sauter les bernacles.', '', 28153),
(148313, 'frFR', 'Vous n\’avez rien à faire ici !', 'Vous n\’avez rien à faire ici !', 28153),
(148312, 'frFR', 'J\’vais vous apprendre à défier un Sombrefer !', 'J\’vais vous apprendre à défier un Sombrefer !', 28153),
(148311, 'frFR', 'Affrontez la puissance écrasante de la montagne !', 'Affrontez la puissance écrasante de la montagne !', 28153),
(148310, 'frFR', 'Je vais vous apprendre à me regarder de haut !', 'Je vais vous apprendre à me regarder de haut !', 28153),
(148309, 'frFR', 'Voyons ce que vous avez dans le ventre.', 'Voyons ce que vous avez dans le ventre.', 28153),
(148308, 'frFR', 'Savourez vos derniers instants !', 'Savourez vos derniers instants !', 28153),
(148307, 'frFR', 'Que ma rage vous consume !', 'Que ma rage vous consume !', 28153),
(148306, 'frFR', 'Mon feu ne… s\’éteindra… jamais…', 'Mon feu ne… s\’éteindra… jamais…', 28153),
(148305, 'frFR', 'Mon clan… me vengera…', 'Mon clan… me vengera…', 28153),
(148304, 'frFR', 'Que mon âme… repose… près de l\’Enclume…', 'Que mon âme… repose… près de l\’Enclume…', 28153),
(148303, 'frFR', 'Je boirais bien… un dernier verre…', 'Je boirais bien… un dernier verre…', 28153),
(148302, 'frFR', 'Je vous… maudis…', 'Je vous… maudis…', 28153),
(148301, 'frFR', 'Ma vie… pour la reine…', 'Ma vie… pour la reine…', 28153),
