(148277, 'frFR', 'Savourez vos derniers instants !', 'Savourez vos derniers instants !', 28153),
(148276, 'frFR', 'Voyons ce que vous avez dans le ventre.', 'Voyons ce que vous avez dans le ventre.', 28153),
(148275, 'frFR', '', '', 28153),
(148274, 'frFR', '', 'N\’en déplaise à votre chef de guerre, je dois retourner auprès des miens. C\’est décidé, nous partons pour Zuldazar. Après tout, ce navire m\’appartient et c\’est votre seule porte de sortie de Hurlevent.\n\nÇa vous pose un problème ?', 28153),
(148273, 'frFR', 'Pas du tout.', 'Pas du tout.', 28153),
(148272, 'frFR', 'Je vais vous apprendre à me regarder de haut !', 'Je vais vous apprendre à me regarder de haut !', 28153),
(148271, 'frFR', 'Affrontez la puissance écrasante de la montagne !', 'Affrontez la puissance écrasante de la montagne !', 28153),
(148270, 'frFR', 'J\’vais vous apprendre à défier un Sombrefer !', 'J\’vais vous apprendre à défier un Sombrefer !', 28153),
(148269, 'frFR', 'Vous n\’avez rien à faire ici !', 'Vous n\’avez rien à faire ici !', 28153),
(148267, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(148266, 'frFR', 'Je l\’ai vue de mes yeux, la sorcière des bois ! Je préfère filer avant qu\’elle me retrouve !', '', 28153),
(148265, 'frFR', 'Comment on est censés continuer à bosser dans ces conditions, hein ?', '', 28153),
(148264, 'frFR', 'Algerson pense qu\’à ses bénefs, mais on est dans un sacré pétrin, nous.', '', 28153),
(148263, 'frFR', 'Y a une sorcière dans ces bois, et elle est furax ! Moi, je rends mon tablier !', '', 28153),
(148262, 'frFR', 'Ces sales bêtes ont rien de naturel ! Encore un coup de la sorcière !', '', 28153),
(148261, 'frFR', 'Il faut qu\’on trouve le moyen de tuer Zulajin.', '', 28153),
(148260, 'frFR', 'L\’infection, elle a disparu ! Et tout ça… c\’est grâce à vous et à $n.', '', 28153),
(148259, 'frFR', 'C\’est vrai, je devrais être mort, mais ça ne veut pas dire que je vais vous laisser y passer. Alors, accrochez-vous !', '', 28153),
(148258, 'frFR', 'Argh ! Assassin ! L\’exil, c\’est encore trop doux pour vous !', '', 28153),
(148257, 'frFR', 'La magie vaudou, elle vous ronge de l\’intérieur… Ne bougez pas, je vais arranger ça !', '', 28153),
(148256, 'frFR', 'Ne bougez pas, Zaluto, nous allons soigner votre infection.', 'Ne bougez pas, Zaluto, nous allons soigner votre infection.', 28153),
(148255, 'frFR', 'Preuve est faite que leur « prophète » n\’était qu\’un imposteur.', '', 28153),
(148254, 'frFR', 'Ils prétendent que Rastakhan a aucun pouvoir ici. Détrompez-les. Chassez l\’hérésie de Tal\’gurub.', '', 28153),
(148253, 'frFR', '', 'Merci d\’avoir récupéré les reliques.', 28153),
(148252, 'frFR', '', 'Atal\’Gral est peut-être sous la mer, mais il est pas perdu. On doit récupérer ce qu\’il reste du temple.', 28153),
(148251, 'frFR', 'Que la nature vous bénisse ! Bonne chance !', 'Que la nature vous bénisse ! Bonne chance !', 28153),
(148250, 'frFR', 'Merci de m\’avoir libéré !', 'Merci de m\’avoir libérée !', 28153),
(148249, 'frFR', 'Au moins, je meurs avec les armes…', 'Au moins, je meurs avec les armes…', 28153),
(148248, 'frFR', 'Arg… je suis vaincu…', 'Arg… je suis vaincue…', 28153),
(148247, 'frFR', 'Alors c\’est ça… qu\’on ressent…', 'Alors c\’est ça… qu\’on ressent…', 28153),
(148246, 'frFR', 'M\’enterrez pas… sans mon rhum…', 'M\’enterrez pas… sans mon rhum…', 28153),
(148245, 'frFR', 'Je vais vous planter ma lame entre les os !', 'Je vais vous planter ma lame entre les os !', 28153),
(148244, 'frFR', 'Je vais vous envoyer par le fond.', 'Je vais vous envoyer par le fond.', 28153),
(148243, 'frFR', 'En garde !', 'En garde !', 28153),
(148242, 'frFR', 'Vous qui lisez ces mots, je vous en conjure, prenez garde à la magie de la sororité !\n\nJ\’ignore d\’où viennent ces sorcières, mais leur cercle s\’est développé en secret dans les recoins sombres de Corlain. Elles sortent désormais au grand jour pour exécuter leurs adversaires et traquer les autres avec leurs abominables maccarbres !\n\nNul ne sait ce qu\’elles veulent. Elles parlent sans cesse de venger leur maître et d\’honorer leur perfide maîtresse, leur « Mère ».\n\nMes chances de quitter Corlain en vie sont bien minces. Tout ce que je souhaite, c\’est que ce message tombe entre des mains capables d\’intervenir. Empêchez ces « sœurs » d\’entrer dans votre ville ! Leur corruption la dévorerait de l\’intérieur, comme elle l\’a fait à Corlain !', 'Vous qui lisez ces mots, je vous en conjure, prenez garde à la magie de la sororité !\n\nJ\’ignore d\’où viennent ces sorcières, mais leur cercle s\’est développé en secret dans les recoins sombres de Corlain. Elles sortent désormais au grand jour pour exécuter leurs adversaires et traquer les autres avec leurs abominables maccarbres !\n\nNul ne sait ce qu\’elles veulent. Elles parlent sans cesse de venger leur maître et d\’honorer leur perfide maîtresse, leur « Mère ».\n\nMes chances de quitter Corlain en vie sont bien minces. Tout ce que je souhaite, c\’est que ce message tombe entre des mains capables d\’intervenir. Empêchez ces « sœurs » d\’entrer dans votre ville ! Leur corruption la dévorerait de l\’intérieur, comme elle l\’a fait à Corlain !', 28153),
(148241, 'frFR', 'Une troisième personne a disparu cette semaine. Les gardes ont beau dire qu\’il n\’y a pas de quoi s\’inquiéter, je n\’y crois pas une seconde.\n\nJ\’ai parlé à monsieur Knowlton pas plus tard qu\’hier soir. Il a vu de ses yeux le corps de Jon le palefrenier, la toute première victime. À l\’en croire, il n\’oubliera jamais cette vision de cauchemar : les murs de la cabane de son domestique étaient couverts d\’inscriptions impies et son cadavre gisait dans son chariot, un trou béant à la place du cœur.\n\nMais aujourd\’hui, Knowlton a disparu et les gardes restent cois.\n\nQuelque chose me dit que ma famille et moi ne sommes plus en sécurité à Corlain. Nous partirons dès que possible pour la Ferté-d\’Arom.', 'Une troisième personne a disparu cette semaine. Les gardes ont beau dire qu\’il n\’y a pas de quoi s\’inquiéter, je n\’y crois pas une seconde.\n\nJ\’ai parlé à monsieur Knowlton pas plus tard qu\’hier soir. Il a vu de ses yeux le corps de Jon le palefrenier, la toute première victime. À l\’en croire, il n\’oubliera jamais cette vision de cauchemar : les murs de la cabane de son domestique étaient couverts d\’inscriptions impies et son cadavre gisait dans son chariot, un trou béant à la place du cœur.\n\nMais aujourd\’hui, Knowlton a disparu et les gardes restent cois.\n\nQuelque chose me dit que ma famille et moi ne sommes plus en sécurité à Corlain. Nous partirons dès que possible pour la Ferté-d\’Arom.', 28153),
(148240, 'frFR', 'Sylvidwen insiste pour que je rejoigne son « cercle des sœurs ».\n\nToute cette histoire ne me dit rien qui vaille. Chaque jour, les jeunes villageoises sont plus nombreuses à porter le charme maccarbre. À ce train-là, tout le village en fera bientôt partie.\n\nLes hommes, eux, n\’y voient que du feu. Ils sont encore plus aveugles que d\’habitude à ce qui les entoure. On croirait presque qu\’on leur a jeté un sort.', 'Sylvidwen insiste pour que je rejoigne son « cercle des sœurs ».\n\nToute cette histoire ne me dit rien qui vaille. Chaque jour, les jeunes villageoises sont plus nombreuses à porter le charme maccarbre. À ce train-là, tout le village en fera bientôt partie.\n\nLes hommes, eux, n\’y voient que du feu. Ils sont encore plus aveugles que d\’habitude à ce qui les entoure. On croirait presque qu\’on leur a jeté un sort.', 28153),
(148239, 'frFR', 'Enfin l\’espoir renaît pour Drustvar. Aujourd\’hui, dame Malvoie est sortie du manoir pour rassurer les habitants quant à l\’absence prolongée de son seigneur.\n\nElle nous a affirmé qu\’il était en bonne santé, mais la façon dont elle régentait les gardes m\’a interpellé. Jamais encore je ne l\’avais vue imposer ainsi son autorité.\n\nAllons, je me fais sûrement des idées. Après les épreuves des semaines passées, la moindre éclaircie est bonne à prendre.', 'Enfin l\’espoir renaît pour Drustvar. Aujourd\’hui, dame Malvoie est sortie du manoir pour rassurer les habitants quant à l\’absence prolongée de son seigneur.\n\nElle nous a affirmé qu\’il était en bonne santé, mais la façon dont elle régentait les gardes m\’a interpellé. Jamais encore je ne l\’avais vue imposer ainsi son autorité.\n\nAllons, je me fais sûrement des idées. Après les épreuves des semaines passées, la moindre éclaircie est bonne à prendre.', 28153),
(148238, 'frFR', 'C\’est la troisième nuit que notre petite Maggie fait le mur dès qu\’elle nous croit endormis, son père et moi. J\’ai essayé de la suivre, mais j\’ai perdu sa trace devant la cour du manoir Malvoie.\n\nLes Davey affirment que leur fille aussi disparaît régulièrement à la faveur de la nuit, avant de revenir mystérieusement comme si de rien n\’était.\n\nSon père prétend l\’avoir vue entrer dans le manoir, mais ça ne tient pas debout. Personne n\’est entré ou sorti de cette demeure depuis des semaines !', 'C\’est la troisième nuit que notre petite Maggie fait le mur dès qu\’elle nous croit endormis, son père et moi. J\’ai essayé de la suivre, mais j\’ai perdu sa trace devant la cour du manoir Malvoie.\n\nLes Davey affirment que leur fille aussi disparaît régulièrement à la faveur de la nuit, avant de revenir mystérieusement comme si de rien n\’était.\n\nSon père prétend l\’avoir vue entrer dans le manoir, mais ça ne tient pas debout. Personne n\’est entré ou sorti de cette demeure depuis des semaines !', 28153),
(148236, 'frFR', 'Nous ne survivrons pas sans l\’aide du Loa.', '', 28153),
(148235, 'frFR', 'La bourse ou la vie !', 'La bourse ou la vie !', 28153),
(148234, 'frFR', 'Cela fait une quinzaine de jours que personne à Corlain n\’a eu de nouvelles des Malvoie. Les gardes du domaine éconduisent les visiteurs sans décrocher le moindre mot.\n\nÀ en croire la rumeur, le seigneur souffre d\’un mal qui le ronge à petit feu et sa dame est si bouleversée qu\’elle reste prostrée auprès de lui, dans ses appartements.\n\nDrustvar vit des heures bien sombres, en vérité.', 'Cela fait une quinzaine de jours que personne à Corlain n\’a eu de nouvelles des Malvoie. Les gardes du domaine éconduisent les visiteurs sans décrocher le moindre mot.\n\nÀ en croire la rumeur, le seigneur souffre d\’un mal qui le ronge à petit feu et sa dame est si bouleversée qu\’elle reste prostrée auprès de lui, dans ses appartements.\n\nDrustvar vit des heures bien sombres, en vérité.', 28153),
(148233, 'frFR', 'Je vais vous réduire en pâté de crabe.', 'Je vais vous réduire en pâté de crabe.', 28153),
(148232, 'frFR', 'Vous le paierez…', 'Vous le paierez…', 28153),
(148231, 'frFR', 'Les Corsandre… triompheront…', 'Les Corsandre… triompheront…', 28153),
(148230, 'frFR', 'Soyez maudits…', 'Soyez maudits…', 28153),
(148229, 'frFR', 'Ordures…', 'Ordures…', 28153),
(148228, 'frFR', 'Vous allez voir comment on règle les problèmes à Boralus !', 'Vous allez voir comment on règle les problèmes à Boralus !', 28153),
(148227, 'frFR', 'Cette ville appartient aux Corsandre !', 'Cette ville appartient aux Corsandre !', 28153),
(148226, 'frFR', 'Fallait pas mettre les pieds ici.', 'Il fallait pas mettre les pieds ici.', 28153),
(148225, 'frFR', 'Ça c\’est l\’erreur de trop !', 'C\’est l\’erreur de trop !', 28153),
(148224, 'frFR', 'Mauvais endroit, mauvais moment !', 'Mauvais endroit, mauvais moment !', 28153),
(148223, 'frFR', 'Toute intrusion en ces lieux est punie de mort !', 'Toute intrusion en ces lieux est punie de mort !', 28153),
(148222, 'frFR', 'Patron, les arbres sont venus pour se venger ! Ils nous prennent en tenaille !', '', 28153),
(148221, 'frFR', 'Vous auriez dû vous tenir à carreau.', 'Vous auriez dû vous tenir à carreau.', 28153),
(148220, 'frFR', 'Vous n\’avez rien à faire ici !', 'Vous n\’avez rien à faire ici !', 28153),
(148219, 'frFR', 'Votre armée est vaincue et nos tours de siège ne tarderont pas à abattre les murs qui vous protègent ! Rendez-vous maintenant, mettons fin à ce massacre !', '', 28153),
(148218, 'frFR', 'Mes machines sont à vos ordres !', '', 28153),
(148217, 'frFR', '', 'À vos ordres. Champions, avec moi !', 28153),
(148216, 'frFR', 'Jaina, Genn, aidez-moi contre Nathanos et Lor\’themar.', '', 28153),
(148215, 'frFR', 'Et comment ! J\’ai apporté quelques machines de plus au cas où. N\’hésitez pas à faire un essai !', '', 28153),
(148214, 'frFR', '', 'La ponctualité est l\’une de mes qualités, votre majesté. Mekkanivelle, vous êtes prêt ?', 28153),
(148213, 'frFR', 'Alleria ! Louée soit la Lumière, vous êtes là !', '', 28153),
(148212, 'frFR', '', 'G\’huun, il est partout !', 28153),
(148211, 'frFR', '', 'Pourrissez tous !', 28153),
(148209, 'frFR', '', 'Non ! Ils ne doivent pas nous échapper !', 28153),
(148208, 'frFR', 'BATTEZ EN RETRAITE !', '', 28153),
(148207, 'frFR', '', 'DÉTRUISEZ-LES !', 28153),
(148206, 'frFR', 'Depuis quand avez-vous peur des araignées, hein ? Écrasez-les, qu\’on n\’en parle plus !', '', 28153),
(148205, 'frFR', 'Et maintenant, y a des araignées qui nous attaquent dans les bois ! On peut pas couper des arbres et se faire massacrer en même temps, patron !', '', 28153),
(148204, 'frFR', 'On dirait que c\’est à nous de nous y coller, $n. Voyons ce que ça donne, cette histoire d\’araignées.', '', 28153),
(148203, 'frFR', 'Les Nagas ont fait de nous des exilés sur nos propres terres.', '', 28153),
(148202, 'frFR', '', 'Assez discuté ! Les tours, abattez les tours !', 28153),
(148201, 'frFR', '', 'Plus un mot, Saurcroc ! Nous devons détourner leur attention de la machine de guerre pour qu\’elle puisse détruire les tours. Des pertes sont inévitables…', 28153),
(148200, 'frFR', 'Vous envoyez nos troupes à la mort ! Nous avons besoin de soldats sur le front pour soutenir le…', '', 28153),
(148199, 'frFR', '', 'Oubliez l\’armée, on s\’en chargera plus tard. Abattez les tours de siège !', 28153),
(148197, 'frFR', 'Rapprochez-moi le plus possible de Nazmir.', 'Rapprochez-moi le plus possible de Nazmir.', 28153),
(148196, 'frFR', '', 'Où est-ce que vous allez ?', 28153),
(148195, 'frFR', 'Tout ce qui est fait peut être défait. Genn, suivez-moi !', '', 28153),
(148194, 'frFR', 'Je n\’ai jamais rien vu de tel…', '', 28153),
(148193, 'frFR', '', 'Vous ne savez pas à qui vous avez affaire, jeune roi. La partie ne fait que commencer !', 28153),
(148192, 'frFR', 'C\’est fini, Sylvanas ! Les murs de Lordaeron s\’effondreront bientôt autour de vous.', '', 28153),
(148190, 'frFR', 'J\’finirai pas dans le bide d\’un jeune pterreurdactyle, ça non !', 'J\’finirai pas dans le bide d\’un jeune pterreurdactyle, ça non !', 28153),
(148189, 'frFR', 'Rokhan, il va me faire la peau quand il saura que je me suis fait choper par des bêtes sauvages.', 'Rokhan, il va me faire la peau quand il saura que je me suis fait choper par des bêtes sauvages.', 28153),
(148188, 'frFR', 'Je vais m\’assurer que tout va bien du côté des ouvriers dans la forêt. Si nous sommes en danger ici, je crains le pire pour ceux qui travaillent là-bas !', '', 28153),
(148187, 'frFR', 'Faites gaffe. Moi, je me méfiais de tout, mais ça n\’a pas empêché une autre bestiole de m\’attaquer de côté. C\’est qu\’elle est maligne, la bougresse.', 'Faites gaffe. Moi, je me méfiais de tout, mais ça n\’a pas empêché une autre bestiole de m\’attaquer de côté. C\’est qu\’elle est maligne, la bougresse.', 28153),
(148186, 'frFR', 'Et alors, qu\’est-ce que vous allez faire ? M\’exiler une deuxième fois ? Ne bougez pas, j\’ai dit !', '', 28153),
(148185, 'frFR', 'Laissez-moi mourir, espèce de criminel ! Votre destin, il vous attend en Vol\’dun maintenant. La loi, c\’est la loi, et vous ne faites qu\’aggraver votre cas en restant ici.', '', 28153),
(148184, 'frFR', 'Bon sang, ça fait un mal de chien.', 'Bon sang, ça fait un mal de chien.', 28153),
(148183, 'frFR', 'Merci, mais vous et moi, on ferait mieux de se tailler en vitesse !', 'Merci, mais vous et moi, on ferait mieux de se tailler en vitesse !', 28153),
(148182, 'frFR', 'Ne bougez pas, Zaluto. On va la soigner, cette infection, et vous remettre d\’aplomb.', '', 28153),
(148181, 'frFR', 'Arrêtez de gigoter, bon sang. On va la soigner, cette infection. Vous serez sur pied en un rien de temps.', '', 28153),
(148180, 'frFR', '', 'Le pouvoir de G\’huun, il vous tuera tous !', 28153),
(148179, 'frFR', '', 'G\’huun, accepte cette offrande de chair et d\’os.', 28153),
(148178, 'frFR', 'Partez… On vous a exilé en Vol\’dun. En restant ici, vous enfreignez la loi zandalari !', '', 28153),
(148177, 'frFR', '', 'G\’huun soit loué !', 28153),
(148176, 'frFR', '', 'Ma puissance, elle s\’accroît !', 28153),
(148175, 'frFR', '', 'Mon sang pour G\’huun…', 28153),
(148174, 'frFR', '', 'C\’est l\’heure du sacrifice !', 28153),
(148173, 'frFR', '', 'Pour la gloire de G\’huun !', 28153),
(148172, 'frFR', 'J\’ai besoin d\’une fléchette.', 'J\’ai besoin d\’une fléchette.', 28153),
(148171, 'frFR', '', 'Les bêtes de la Réserve, elles sont sur les nerfs aujourd\’hui.', 28153),
(148170, 'frFR', '', 'Ça va leur prendre un moment pour se regrouper. Merci.', 28153),
(148169, 'frFR', '', 'Les disciples de Zul et les Mogu, ils rassemblent leurs troupes au temple du Prophète. Vous savez quoi faire.', 28153),
(148168, 'frFR', 'Je ne les laisserai pas passer !', '', 28153),
(148167, 'frFR', 'Nous n\’avons toujours pas de nouvelles d\’Alleria. Elle devait obtenir l\’appui de Gnomeregan.', '', 28153),
(148166, 'frFR', '', 'Beau travail. Ça devrait garder les bêtes en bonne santé pendant un moment.', 28153),
(148165, 'frFR', '', 'Un étrange poison affecte les bêtes de la Réserve. Soignez-les avec ça. Mais faites attention, y en a qui sont trop atteintes et pourraient se retourner contre vous.', 28153),
(148164, 'frFR', '', 'Et brûlez cette note après l\’avoir lue, pauvre imbécile !', 28153),
(148163, 'frFR', '', 'Ne tolérez aucune insolence de la part de ces moins-que-rien. Punissez-en pour l\’exemple s\’il le faut. Tout ce qui compte, c\’est que nos clients obtiennent leur marchandise en temps et en heure.', 28153),
(148162, 'frFR', '', 'Les chimistes produisent une poudre d\’excellente qualité. Continuez de leur fournir de l\’azérite raffinée, ou je trouverai quelqu\’un pour le faire à votre place.', 28153),
(148161, 'frFR', '', 'Je me fiche de savoir comment vous vous y prenez, mais ces forges doivent tourner jour et nuit !', 28153),
(148160, 'frFR', '', 'Messieurs Farthing et Williams se tiennent à votre disposition si vous avez des questions.', 28153),
(148159, 'frFR', '', 'Concernant la présence accrue de la compagnie sur le site, rassurez-vous, nos agents sont là pour assurer votre sécurité.', 28153),
(148158, 'frFR', '', 'Mes chers employés ! À compter de ce jour, votre temps de travail sera doublé. Il s\’agit là d\’un sacrifice indispensable à la sécurité de Kul Tiras en ces temps troublés !', 28153),
(148157, 'frFR', 'Tremblez devant mon pouvoir !', 'Tremblez devant mon pouvoir !', 28153),
(148156, 'frFR', 'Parfois, tout ce marais, on dirait qu\’il veut notre peau ! Heureusement que vous vous laissez pas faire !', '', 28153),
(148155, 'frFR', 'J\’ai un mauvais pressentiment… Nos patrouilles d\’éclaireurs, elles auraient dû rentrer y a longtemps. Trouvez-les et voyez ce qui les retient.', '', 28153),
(148154, 'frFR', '', 'Nous allons faire mieux que ça ! Nous allons tous les anéantir ! Allez, tout le monde à bord !', 28153),
(148153, 'frFR', 'Grimpons sur ce monstre et fichons le camp d\’ici !', '', 28153),
(148152, 'frFR', 'Le charme que j\’ai fabriqué avec ceux que nous avions récupérés ! Utilisez-le sur le démolisseur !', '', 28153),
(148151, 'frFR', '', 'Cela leur apprendra à s\’aventurer hors de Nazmir ! Je suis heureuse de pouvoir compter sur vous.', 28153),
(148150, 'frFR', '', 'Les Trolls de sang sont entrés dans Rive-Mare ! Tuez leur avant-garde et brûlez tous les cadavres qu\’ils pourraient réanimer.', 28153),
(148147, 'frFR', 'Assez !', '', 28153),
(148146, 'frFR', 'Essaie pas de me bourrer le mou ! Les arbres, ça se déplace pas tout seul ! Au travail, tire-au-flanc !', '', 28153),
(148145, 'frFR', 'Je dois regagner l\’arène. Restez sur vos gardes. Jakra\’zet, il a promis une forte récompense pour votre tête.', 'Je dois regagner l\’arène. Restez sur vos gardes. Jakra\’zet, il a promis une forte récompense pour votre tête.', 28153),
(148144, 'frFR', 'Le temple est en ruine, mais nous y serons en sécurité si le Loa accepte de nous accueillir…', '', 28153),
(148143, 'frFR', 'Nous ne serons bientôt plus en sécurité, ici.', '', 28153),
(148142, 'frFR', 'Je n\’ai jamais entendu parler de l\’anneau des marées, mais il doit être puissant pour qu\’Azshara envoie toute une armée le récupérer.', '', 28153),
(148141, 'frFR', 'Elles ne tarderont pas à reprendre du poil de la bête… comme toujours. On aura encore affaire à elles.', '', 28153),
(148140, 'frFR', 'Les vipères à plumes prolifèrent comme des champignons, et la situation commence à dégénérer ! Détruisez leurs œufs pour contenir leur population.', '', 28153),
(148139, 'frFR', '', '', 28153),
(148138, 'frFR', 'Korphek le Brave !\n\nLes récits de sa force et de ses talents de stratège se transmettent de génération en génération parmi les jeunes guerriers et son nom est sur toutes les lèvres. Lorsque la bataille se présente mal, ses exploits attisent la flamme de leur pugnacité.\n\nIl peut à lui seul inverser la tendance d\’un combat ! Il se bat pour son peuple avec passion et férocité !\n\nC\’est un frère pour nous tous.\n\nÀ ses yeux, nul ne peut rivaliser avec les Sephraks. Nous sommes les meilleurs. Nous sommes les plus sages. Nous sommes tout puissants.\n\nForte de son soutien, notre auguste nation ne craint rien ni personne !', '', 28153),
(148137, 'frFR', 'Intègre, juste, pieux, déterminé… Telles sont les caractéristiques associées au nom de Vorrik.\n\nSa dévotion envers Sephraliss est aussi profonde qu\’inébranlable. Sa sagesse et sa clairvoyance sont incontestables.\n\nRien ne saurait détourner Vorrik de son devoir de gardien.\n\nAvec ses vénérables frères à ses côtés, il continue à monter la garde inlassablement.\n\nAinsi, aucun ennemi ne pourra s\’approcher suffisamment pour réveiller notre géant endormi.', '', 28153),
(148136, 'frFR', 'Sulphis est le plus proche disciple de Sephraliss. L\’amour qu\’il porte à son Loa et au désert l\’a incité à adopter le cobra en tant que guide spirituel.\n\nSouvent considéré comme le premier gardien, il détenait un pouvoir immense, mais il savait pertinemment qu\’il ne pourrait sceller la tombe à lui seul. Il se mit donc en quête de compagnons pour l\’aider dans sa mission. Vorrik et Korphek acceptèrent de se joindre à lui, et c\’est ainsi que fut fondé l\’ordre des gardiens.\n\nAujourd\’hui encore, les Sephraks viennent des quatre coins du monde pour déposer des gages d\’affection au pied de leurs statues. Ces offrandes incarnent tout ce que Sulphis représente.\n\nPlus jamais les C\’Thraxxi ne doivent lever la main sur ce qui nous est cher.', '', 28153),
(148133, 'frFR', '', 'Là ! Dans l\’arbre, une porte !', 28153),
(148132, 'frFR', 'Et ce golem maccarbre, personne n\’en parle ? Parce que moi, j\’ai des choses à dire.', '', 28153),
(148131, 'frFR', 'Un problème à la fois, mon garçon !', '', 28153),
(148130, 'frFR', 'Grâce à vous, Azeroth est un peu plus sûre.', '', 28153),
(148129, 'frFR', 'Faites attention. Il y a une créature puissante dans les environs, et l\’azérite la rend plus forte encore !', '', 28153),
(148128, 'frFR', 'Bon travail. Bien joué !', '', 28153),
(148127, 'frFR', 'On dirait qu\’il y a un Tortollan, par là. Allez voir s\’il a besoin d\’aide.', '', 28153),
(148126, 'frFR', 'Ha, joli combat ! Voilà qui fera une belle histoire à raconter aux autres.', '', 28153),
(148125, 'frFR', 'Allez, Lucille, montre-leur de quel bois tu te chauffes.', '', 28153),
(148124, 'frFR', 'Arrangez-vous pour que ça vaille le détour. Du grand spectacle, voilà ce que je veux !', '', 28153),
(148123, 'frFR', 'J\’affronterai la créature que vous invoquerez.', 'J\’affronterai la créature que vous invoquerez.', 28153),
(148122, 'frFR', 'Hé, vous ! Vous êtes $gun:une:c; $c, pas vrai ? Vous pouvez peut-être m\’aider, je suis à la recherche d\’une bonne histoire à raconter.\n\nUn de mes amis vient de me donner ce parchemin. À l\’en croire, il sert à invoquer une créature redoutable.\n\nÇa vous dirait de l\’affronter ? Moi, j\’ai hâte de voir ce que ça donne.', '', 28153),
(148121, 'frFR', '', 'Ça fera une sacrée histoire à raconter aux autres. Voilà un petit quelque chose pour vos efforts. Continuez comme ça.', 28153),
(148120, 'frFR', '', 'Hum ? Il se passe quelque chose d\’étrange dans les parages. Pourriez-vous aller voir de quoi il s\’agit ? Ça pourrait être intéressant.', 28153),
(148119, 'frFR', 'Voilà un fléau dont on n\’aura plus à s\’inquiéter.', '', 28153),
(148118, 'frFR', 'Il y a un puissant monstre qui rôde dans le coin, nourri par le sang même d\’Azeroth ! Vous devez le détruire avant qu\’il n\’arrive malheur.', '', 28153),
(148117, 'frFR', 'Torka m\’a demandé de vous remettre ceci.', 'Torka m\’a demandé de vous remettre ceci.', 28153),
(148116, 'frFR', 'Vous avez réussi ! Vite, par ici !', '', 28153),
(148115, 'frFR', 'J\’ai vu bien des choses au cours de ma longue existence. La tribu Tortaka existait déjà longtemps avant ma naissance, et elle sera encore là longtemps après ma mort.', '', 28153),
(148114, 'frFR', 'Hmm… Cette main, elle a pas de bouche, mais ça l\’empêche pas de jacasser. Les esprits sont vraiment mystérieux.', '', 28153),
(148113, 'frFR', 'Prendre le nouveau parchemin de la main du destin.', 'Prendre le nouveau parchemin de la main du destin.', 28153),
(148112, 'frFR', 'Le parchemin de la main du destin, il est mystérieux mais puissant. Je vois qu\’y a plein de Morts-vivants sur la côte… Vous savez ce qui vous reste à faire.', '', 28153),
(148111, 'frFR', 'Ma\’da, elle veut que je rentre.', '', 28153),
(148110, 'frFR', 'Y a tout plein de monstres ici !', '', 28153),
(148109, 'frFR', 'Partez. Y me faut de la viande !', '', 28153),
(148107, 'frFR', '|cffffff00ID d\’objet $1i|r', '|cffffff00ID d\’objet $1i|r', 28153),
(148106, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(148104, 'frFR', 'J\’ai besoin d\’un sifflet pour rallier les défenseurs rastari.', 'J\’ai besoin d\’un sifflet pour rallier les défenseurs rastari.', 28153),
(148103, 'frFR', 'Les Rastari, ils reconnaîtront le son du sifflet.', '', 28153),
(148102, 'frFR', 'Vorrik, si tu reçois ce message, c\’est que je suis arrivé trop tard. Korphek a trahi notre peuple et projette de détruire la barrière que nous avions placée autour du tombeau.', '', 28153),
(148101, 'frFR', 'Leurs os paveront les routes de notre empire.', '', 28153),
(148100, 'frFR', 'Vous n\’étiez pas de taille.', '', 28153),
(148099, 'frFR', '|cffffff00ID de gisement $1i|r', '|cffffff00ID de gisement $1i|r', 28153),
(148098, 'frFR', 'Ici tout s\’achète, si vous y mettez le prix.', 'Ici tout s\’achète, si vous y mettez le prix.', 28153),
(148097, 'frFR', 'Vous allez jeter un œil à la concurrence ? Mais, vous reviendrez.', 'Vous allez jeter un œil à la concurrence ? Bah, vous reviendrez.', 28153),
(148096, 'frFR', 'Ne partez pas les mains vides.', 'Ne partez pas les mains vides.', 28153),
(148095, 'frFR', 'Ma spécialité : le meilleur des produits étrangers.', 'Ma spécialité : le meilleur des produits étrangers.', 28153),
(148094, 'frFR', '|TInterface\\Icons\\SPELL_NATURE_LIGHTNINGOVERLOAD.BLP:20|tAspis vous inflige |cFFFF0000|Hspell:263371|h[Conduction]|h|r !', '|TInterface\\Icons\\SPELL_NATURE_LIGHTNINGOVERLOAD.BLP:20|tAspis vous inflige |cFFFF0000|Hspell:263371|h[Conduction]|h|r !', 28153),
(148093, 'frFR', 'Goûtez à la puissance de la foudre !', '', 28153),
(148092, 'frFR', 'Foudroie-les sur place, Viperis !', '', 28153),
(148091, 'frFR', 'Je suis sûr que vous reviendrez me voir !', 'Je suis sûre que vous reviendrez me voir !', 28153),
(148090, 'frFR', 'Vous pouvez bien vous offrir encore une petite bricole !', 'Vous pouvez bien vous offrir encore une petite bricole !', 28153),
(148089, 'frFR', 'La prochaine fois, revenez avec plus de pièces, d\’accord ?', 'La prochaine fois, revenez avec plus de pièces, d\’accord ?', 28153),
(148088, 'frFR', 'Envoyez-moi à Grangeneuve.', 'Envoyez-moi à Grangeneuve.', 28153),
(148087, 'frFR', 'Envoyez-moi au cercle des Éléments.', 'Envoyez-moi au cercle des Éléments.', 28153),
(148086, 'frFR', 'Je dois faire part de mes doutes à Vorrik, mais la clé doit d\’abord être mise en lieu sûr. Je crains que de sombres évènements nous attendent…', '', 28153),
(148085, 'frFR', 'Des discussions ont lieu au sein du temple. Korphek désire vivement attaquer les Trolls, mais il oublie que ce sont de formidables adversaires, et qu\’un tel acte mettrait fin à la paix… À quoi bon mener un combat perdu d\’avance ?', '', 28153),
(148084, 'frFR', 'Vorrik, Korphek et moi-même avons scellé la tombe dans l\’espoir que jamais personne ne réveille le géant qui y est enterré. Nous ne commettrons pas les mêmes erreurs que nos voisins autrefois.', '', 28153),
(148083, 'frFR', 'L\’affrontement entre Sephraliss et Mythrax a dévasté la cité. Notre Loa a donné sa vie pour nous protéger et nous ne permettrons pas que son sacrifice reste vain.', '', 28153),
(148082, 'frFR', '|TInterface\\Icons\\Ability_Socererking_arcanewrath.blp:20|tViperis commence à lancer |cFFFF0000|Hspell:263389|h[Ruée arquée]|h|r !', '|TInterface\\Icons\\Ability_Socererking_arcanewrath.blp:20|tViperis commence à lancer |cFFFF0000|Hspell:263389|h[Ruée arquée]|h|r !', 28153),
(148081, 'frFR', 'Qu\’adviendra-t-il… de l\’empire…', '', 28153),
(148080, 'frFR', 'Les sables… m\’emportent…', '', 28153),
(148079, 'frFR', 'Pour l\’empire !', '', 28153),
(148078, 'frFR', 'Ma puissance vous brisera !', '', 28153),
(148077, 'frFR', 'J\’ai besoin d\’un totem pour dissiper le sort qui affecte les esclaves.', 'J\’ai besoin d\’un totem pour dissiper le sort qui affecte les esclaves.', 28153),
(148076, 'frFR', '', 'Prenez ça, vous en aurez besoin.', 28153),
(148075, 'frFR', 'Votre village est en danger.', 'Votre village est en danger.', 28153),
(148074, 'frFR', 'Ça apprendra à ceux qui s\’en prennent aux villageois depuis les ombres. Beau travail.', '', 28153),
(148073, 'frFR', 'Les assassins de Zul guettent les villageois de Zeb\’ahari. Prévenez les habitants du danger et réglez leur compte aux tueurs embusqués.', '', 28153),
(148072, 'frFR', 'Ça va mieux, on dirait.', 'Ça va mieux, on dirait.', 28153),
(148071, 'frFR', 'Quand y faut faire le boulot, je peux toujours compter sur vous !', '', 28153),
(148070, 'frFR', 'L\’odeur du sang est très forte. Faites ce que vous faites le mieux, semez le chaos à Zal\’amak.', '', 28153),
(148069, 'frFR', 'Attendez, non ! Je cherche seulement à protéger ma famille.', 'Attendez, non ! Je cherche juste à protéger ma famille.', 28153),
(148068, 'frFR', 'Hors de notre vallée !', 'Hors de notre vallée !', 28153),
(148067, 'frFR', 'Je n\’ai pas d\’ordres à recevoir de votre part !', 'Je n\’ai pas d\’ordres à recevoir de votre part !', 28153),
(148066, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Vous avez réussi l\’épreuve.\n\nEraka no Kimbul vous accorde sa bénédiction. Le Loa des tigres vous attend. »', '', 28153),
(148065, 'frFR', '', 'Nous sommes les prélats de Rezan, le plus noble ordre de guerriers sacrés au service d\’un Loa.\n\nNotre cercle est réservé à l\’élite et seuls les élus de la Loa qui font preuve d\’un talent inné pour le combat intègrent nos rangs. Nous formons des champions de la Lumière pour défendre notre empire.\n\nEt non, nous n\’avons pas de poste à pourvoir et nous ne faisons pas l\’aumône.', 28153),
(148064, 'frFR', '<Le lieutenant Akaro inspecte le tranchant de sa lame avant de vous adresser un rictus suffisant.>', '', 28153),
(148063, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Vous avez échoué.\n\nMéditez les paroles de l\’auguste Loa, Eraka no Kimbul, et revenez quand vous les aurez comprises. »', '', 28153),
(148062, 'frFR', 'Bonjour, m\’sieur.', '', 28153),
(148061, 'frFR', 'Je vous suis. N\’oubliez pas : la clé pour passer inaperçu quelque part, c\’est de faire comme si vous étiez le maître des lieux.', '', 28153),
(148060, 'frFR', 'Il voit l\’avenir.', 'Il voit l\’avenir.', 28153),
(148059, 'frFR', 'Il voit le visage de son ennemi.', 'Il voit le visage de son ennemi.', 28153),
(148058, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(148057, 'frFR', 'Il voit des formes et des couleurs.', 'Il voit des formes et des couleurs.', 28153),
(148056, 'frFR', 'Il voit la vérité.', 'Il voit la vérité.', 28153),
(148055, 'frFR', 'Il voit qu\’il appartient à la nature.', 'Il voit qu\’il appartient à la nature.', 28153),
(148054, 'frFR', 'Il voit le monde qui l\’entoure.', 'Il voit le monde qui l\’entoure.', 28153),
(148053, 'frFR', 'Une vie consacrée au plaisir.', 'Une vie consacrée au plaisir.', 28153),
(148052, 'frFR', 'Une vie propice à l\’épanouissement.', 'Une vie propice à l\’épanouissement.', 28153),
(148051, 'frFR', 'Une vie vécue dans l\’honneur.', 'Une vie vécue dans l\’honneur.', 28153),
(148050, 'frFR', 'Une vie placée sous le signe de la paix.', 'Une vie placée sous le signe de la paix.', 28153),
(148049, 'frFR', 'Une vie pleine de gloire.', 'Une vie pleine de gloire.', 28153),
(148048, 'frFR', 'Une vie passée dans le luxe.', 'Une vie passée dans le luxe.', 28153),
(148047, 'frFR', 'L\’argent. Des tonnes d\’argent.', 'L\’argent. Des tonnes d\’argent.', 28153),
(148046, 'frFR', 'Un esprit vif.', 'Un esprit vif.', 28153),
(148045, 'frFR', 'Une force supérieure.', 'Une force supérieure.', 28153),
(148044, 'frFR', 'Le charisme.', 'Le charisme.', 28153),
(148043, 'frFR', 'Des disciples fidèles.', 'Des disciples fidèles.', 28153),
(148042, 'frFR', 'Une volonté indomptable.', 'Une volonté indomptable.', 28153),
(148041, 'frFR', 'Qu\’il faut toujours surveiller ses arrières.', 'Qu\’il faut toujours surveiller ses arrières.', 28153),
(148040, 'frFR', 'Qu\’il faut faire preuve de courage en toutes circonstances.', 'Qu\’il faut faire preuve de courage en toutes circonstances.', 28153),
(148039, 'frFR', 'Que l\’orgueil précède la chute.', 'Que l\’orgueil précède la chute.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148038, 'frFR', 'Qu\’il faut réfléchir avant de bondir.', 'Qu\’il faut réfléchir avant de bondir.', 28153),
(148037, 'frFR', 'Que la peur est l\’apanage des faibles.', 'Que la peur est l\’apanage des faibles.', 28153),
(148036, 'frFR', 'Que seuls les plus forts survivent.', 'Que seuls les plus forts survivent.', 28153),
(148035, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Et l\’homme clairvoyant, que voit-il ? »', '', 28153),
(148034, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Qu\’est-ce qu\’une vie bien vécue ? »', '', 28153),
(148033, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Quelle est la source de la puissance ? »', '', 28153),
(148032, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Que nous enseigne le tigre bondissant ? »', '', 28153),
(148031, 'frFR', '', 'Ils sont presque aux portes d\’Atal\’Dazar. Faut qu\’on les rattrape, et vite !', 28153),
(148030, 'frFR', 'Et si on embarquait pour découvrir où va ce bateau ?', '', 28153),
(148029, 'frFR', 'Quoi ? Ah bon ?', '', 28153),
(148028, 'frFR', 'Évitez d\’attirer l\’attention.', '', 28153),
(148027, 'frFR', '', 'Une minute, Raal. Y manque Rezan et Rastakhan.', 28153),
(148026, 'frFR', 'Rien de particulier.', 'Rien de particulier.', 28153),
(148025, 'frFR', 'J\’aspire à la gloire et au prestige.', 'J\’aspire à la gloire et au prestige.', 28153),
(148024, 'frFR', 'J\’aspire à la connaissance de royaumes ancestraux.', 'J\’aspire à la connaissance de royaumes ancestraux.', 28153),
(148023, 'frFR', 'J\’aspire à la richesse des rois.', 'J\’aspire à la richesse des rois.', 28153),
(148022, 'frFR', 'J\’aspire à la puissance nécessaire pour tuer mes ennemis.', 'J\’aspire à la puissance nécessaire pour tuer mes ennemis.', 28153),
(148021, 'frFR', 'Si vous avez encore des trucs à faire en ville, c\’est maintenant. Dites-moi quand vous voudrez monter à bord pour voir où le vent nous mène.', '', 28153),
(148020, 'frFR', 'Je sollicite la bénédiction du Loa.', 'Je sollicite la bénédiction du Loa.', 28153),
(148019, 'frFR', '<Une voix mystérieuse résonne dans votre tête.>\n\n« Que cherchez-vous ici ? »', '', 28153),
(148018, 'frFR', '', 'La marée… se retire…', 28153),
(148017, 'frFR', '', 'Ma reine… J\’ai… échoué…', 28153),
(148016, 'frFR', '', 'Que les abysses vous emportent…', 28153),
(148015, 'frFR', '', 'Ma vie… pour… Azshara !', 28153),
(148014, 'frFR', 'Nous voilà tirés d\’affaire ! Je vais de ce pas faire mon rapport à Roz. La ville vous doit une fière chandelle !', '', 28153),
(148013, 'frFR', 'Ne vous en faites pas pour moi. Ils se trouvent exactement où je voulais qu\’ils soient.', '', 28153),
(148012, 'frFR', 'Je tenais à vous souhaiter bonne chance. Tout le monde compte sur vous.', '', 28153),
(148011, 'frFR', 'Par ici !', '', 28153),
(148009, 'frFR', 'Des menaces, toujours des menaces…', '', 28153),
(148008, 'frFR', '', 'Je vais t\’empaler sur tes propres défenses.', 28153),
(148007, 'frFR', 'Loti, pourquoi t\’as mis autant de temps ?', '', 28153),
(148006, 'frFR', 'Holà ! Maintenant, vous avez attiré leur attention ! Vague de Trolls en approche !', '', 28153),
(148005, 'frFR', 'On touchera jamais le monstre, visez mieux que ça !', '', 28153),
(148004, 'frFR', 'Ceux qui restent, ils sont à vous. Amusez-vous bien, mais n\’oubliez pas que vous avez une dette à me payer. Leurs âmes, vous me les envoyez !', '', 28153),
(148003, 'frFR', 'Ha ha ! Vous croyez que je vais vous laisser mourir alors que vous avez une dette envers moi ?', '', 28153),
(148002, 'frFR', 'Ces lézards ne s\’en remettront pas de sitôt ! Nos mages vont vouloir examiner la gemme, ça c\’est sûr.', '', 28153),
(148001, 'frFR', 'Ces Sephraks ont sur eux des gemmes gorgées d\’énergie. Tuez-les et rapportez-nous une gemme.', '', 28153),
(148000, 'frFR', 'Ah, parfait. J\’imagine qu\’il ne s\’agissait que de menu fretin pour quelqu\’un de votre trempe.', '', 28153),
(147999, 'frFR', 'Un banc de céphalopodes ? Quelle aubaine ! J\’ai épuisé mes réserves d\’encre il y a peu ! En plus, j\’ai exactement ce qu\’il nous faut ! Plongez dans l\’eau et récoltez le précieux liquide de ces créatures.', '', 28153),
(147998, 'frFR', '', 'On a un GROS problème ici !', 28153),
(147997, 'frFR', 'Maintenant, les Rastari vont avoir le temps de souffler un peu. Beau travail.', '', 28153),
(147996, 'frFR', 'Les Rastari ont essayé de déloger les Mogu du port de guerre, mais en vain. Rejoignez-les et massacrez tous ceux qui s\’opposent à vous.', '', 28153),
(147994, 'frFR', 'Reculez ! Nous refusons de prendre part à ça !', '', 28153),
(147993, 'frFR', 'OUAIIIIS ! LE CANON !', '', 28153),
(147992, 'frFR', 'Je vous retrouverai là-bas.', '', 28153),
(147991, 'frFR', 'Cagney, embarquez ces gamins et ramenez-les en ville. Taelia fera en sorte qu\’on leur trouve un abri.', '', 28153),
(147990, 'frFR', 'Le canon ! Le canon !', '', 28153),
(147989, 'frFR', 'Pao Me vous remet son rapport.', '', 28153),
(147988, 'frFR', 'Ça, c\’est pas un problème, c\’est une mission pour notre bon vieux canon parabolique !', '', 28153),
(147987, 'frFR', 'Feng vous remet son rapport.', '', 28153),
(147986, 'frFR', 'Je reprends le combat !', '', 28153),
(147985, 'frFR', 'Je t\’interdis de mourir, Viperis ! Relève-toi !', '', 28153),
(147983, 'frFR', '', 'Votre force égale celle de Rezan lui-même.', 28153),
(147982, 'frFR', '', 'Ces immondes disciples de Zul souillent le temple de Rezan ! Apprenez-leur le respect !', 28153),
(147981, 'frFR', 'Quelqu\’un doit arrêter ces Gobelins ! Visez le déchiqueteur !', '', 28153),
(147980, 'frFR', 'La fumée est… trop épaisse…', '', 28153),
(147979, 'frFR', '', 'Les miens méritent de rejoindre l\’Autre côté en paix. Je vous remercie pour votre aide.', 28153),
(147978, 'frFR', '', 'Il est grand temps d\’honorer votre parole. Libérez les âmes prisonnières de ces horreurs et guidez-les jusqu\’au temple de Bwonsamdi.', 28153),
(147977, 'frFR', '', 'Venez. Je vous préviens, va falloir vous accrocher.', 28153),
(147975, 'frFR', 'Vaut mieux écarter les menaces tout de suite, que le regretter plus tard.', '', 28153),
(147974, 'frFR', 'Les Murlocs, ils envahissent nos rives. Si on ne s\’en débarrasse pas immédiatement, la situation va dégénérer.', '', 28153),
(147973, 'frFR', '', 'Que le désert vous prive de votre âme.', 28153),
(147972, 'frFR', '', 'Je sais que vous êtes là, $R. Votre odeur me chatouille la langue.', 28153),
(147970, 'frFR', '', 'Pour commencer, nous devons rassembler nos troupes. Ah ! $n, ce gong devrait faire l\’affaire. Faites-le retentir.', 28153),
(147969, 'frFR', '', 'Creusez. Cherchez. Et trouvez ! La dernière clé doit se trouver ici !', 28153),
(147968, 'frFR', '', 'Ces maudits Zandalari touchent au but, il faut trouver la clé avant eux !', 28153),
(147967, 'frFR', '', 'Korphek nous récompensera si nous trouvons la clé les premiers !', 28153),
(147966, 'frFR', '', 'La clé nous revient, $c ! Les autres gardiens ont échoué, mais je ne faillirai pas. Pour Korphek !', 28153),
(147965, 'frFR', 'Chao vous remet son rapport.', '', 28153),
(147964, 'frFR', 'Quels renseignements avez-vous glanés ?', 'Quels renseignements avez-vous glanés ?', 28153),
(147963, 'frFR', 'Chuuut ! Les murs ont des oreilles. De pierre, certes, mais des oreilles malgré tout.', 'Chuuut ! Les murs ont des oreilles. De pierre, certes, mais des oreilles malgré tout.', 28153),
(147962, 'frFR', 'Pardonnez-moi ! Je ne suis pas un soldat !', 'Pardonnez-moi ! Je ne suis pas un soldat !', 28153),
(147961, 'frFR', 'J\’implore votre clémence !', 'J\’implore votre clémence !', 28153),
(147960, 'frFR', 'Ils ne m\’ont pas laissé le choix !', 'Ils ne m\’ont pas laissé le choix !', 28153),
(147959, 'frFR', 'Je regrette ! Pitié, ne me faites pas de mal !', 'Je regrette ! Pitié, ne me faites pas de mal !', 28153),
(147958, 'frFR', 'Si vous le dites…', 'Si vous le dites…', 28153),
(147957, 'frFR', 'Vous croyez vraiment que c\’est une bonne idée ?', 'Vous croyez vraiment que c\’est une bonne idée ?', 28153),
(147956, 'frFR', 'Je n\’ai jamais demandé ça !', 'Je n\’ai jamais demandé ça !', 28153),
(147955, 'frFR', 'Aidez-moi au lieu de rester là sans rien faire !', 'Aidez-moi au lieu de rester là sans rien faire !', 28153),
(147954, 'frFR', 'Eh, vous ! Aidez-moi avec cet intrus !', 'Eh, vous ! Aidez-moi avec cet intrus !', 28153),
(147953, 'frFR', 'Ces informations nous seront d\’un grand renfort pour combattre la Horde. Beau travail.', '', 28153),
(147952, 'frFR', 'Nos alliés pandashan ont infiltré les Mogu qui occupent le port de guerre troll. Découvrez ce qu\’ils ont appris et n\’hésitez pas à occire quelques Mogu en chemin !', '', 28153),
(147951, 'frFR', 'Fracas', 'Fracas', 28153),
(147950, 'frFR', '', 'Je vais fracasser quelques crânes de sorcière pendant que vous tentez de résoudre ce mystère.', 28153),
(147949, 'frFR', '', 'Maintenant que vous les avez matés, on va pouvoir souffler… jusqu\’à la prochaine catastrophe.', 28153),
(147948, 'frFR', '', 'Maudits gorilles, ils se sont remis à la kaja\’mite ! Remettez-les à leur place avant qu\’ils sèment le chaos dans tout Zuldazar.', 28153),
(147947, 'frFR', 'Ça fait des jours que les Sephraks me pourchassent. Ces dunes sont un enfer.\n\nJe pensais que tout le monde était mort dans l\’accident… Y a-t-il d\’autres survivants ?', '', 28153),
(147946, 'frFR', 'Ha… euh ! Les manuels, c\’est pour les crétins, Triture ! Les vrais artistes agissent à l\’instinct !', '', 28153),
(147945, 'frFR', '', 'Euh, chef, si on suit le manuel à la lettre, il manque des vis à certains des endroits.', 28153),
(147944, 'frFR', 'Message reçu, princesse. Ça tombe bien, vous vous trouvez en ce moment même sur ce qui se fait de mieux en matière de technologie gobeline !', '', 28153),
(147943, 'frFR', 'Quand y en a plus, y en a encore !', '', 28153),
(147942, 'frFR', 'Bon sang. J\’avais encore jamais dégommé de Dieu très ancien. J\’aurais dû emporter plus d\’explosifs !', '', 28153),
(147941, 'frFR', '', 'On va devoir exploser combien de ces guignols avant qu\’ils comprennent le message ?', 28153),
(147940, 'frFR', 'Princesse, je suis pas un expert, mais j\’ai l\’impression que vous avez un problème de Trolls de sang.', '', 28153),
(147939, 'frFR', '', 'Euh, patron, je crois que le terme politiquement correct, c\’est « Réprouvés ».', 28153),
(147938, 'frFR', 'Mais on TRAVAILLE avec des Morts-vivants en permanence, crétin des îles !', '', 28153),
(147937, 'frFR', 'Ho ho HO ! Personne a précisé qu\’on devrait aussi se farcir des Morts-vivants !', '', 28153),
(147936, 'frFR', '', 'Julwaba, vous êtes blessée ?', 28153),
(147935, 'frFR', 'C\’est comme ça qu\’on se la joue, à Kezan !', '', 28153),
(147934, 'frFR', 'Hé ho ! Réveille-toi, c\’est l\’heure de MOURIR !', '', 28153),
(147933, 'frFR', '', 'On les dégomme trop vite, j\’ai pas le temps d\’en profiter ! Enfin… j\’en profite un peu quand même.', 28153),
(147932, 'frFR', 'Le p\’tit déjeuner est servi !', '', 28153),
(147931, 'frFR', 'Il est où, votre Dieu du sang, hein ? Pauvres taches !', '', 28153),
(147930, 'frFR', 'Je parie qu\’on pourrait dégommer un sacré paquet de Gnomes avec ce joujou !', '', 28153),
(147929, 'frFR', '', 'Et BOUM ! fit le méchant en explosant !', 28153),
(147928, 'frFR', '', 'Oh, excusez-moi, princesse !', 28153),
(147927, 'frFR', '', 'J\’aurais dû me douter que les choses finiraient comme ça en travaillant avec des Gobelins.', 28153),
(147926, 'frFR', 'Il craint sévère, votre marais. La meilleure chose qui pourrait lui arriver, ce serait d\’exploser !', '', 28153),
(147925, 'frFR', '', 'Ce soir, tu vas faire dodo avec les poissons !', 28153),
(147924, 'frFR', 'On va vous l\’exploser, votre Dieu très ancien, avec les compliments de la maison !', '', 28153),
(147923, 'frFR', 'À présent, si vous voulez bien m\’excuser, j\’ai des comptes à régler.', '', 28153),
(147922, 'frFR', 'Ouais, c\’est ça mon pote, va voir au fond de l\’eau si j\’y suis !', '', 28153),
(147921, 'frFR', '', 'Par ici ! Je l\’ai trouvée !', 28153),
(147920, 'frFR', 'Tout le monde saura ce qu\’est la Défense d\’or maintenant !', '', 28153),
(147919, 'frFR', 'Faut qu\’on trouve une histoire épique pour expliquer comment on a arraché cette défense à un Troll sanguinaire !', '', 28153),
(147918, 'frFR', 'Rokhan n\’est pas né de la dernière pluie, princesse. Il est pas du genre à se faire avoir par des Trolls de sang.', '', 28153),
(147917, 'frFR', 'Je vais piloter cet engin, vous n\’aurez qu\’à me dire où tirer, et je tirerai. Montrons à ces sauvages qu\’on sait s\’amuser !', '', 28153),
(147916, 'frFR', 'Bon, c\’est pas de l\’or, mais j\’peux lui donner la forme d\’une défense.', '', 28153),
(147915, 'frFR', '', 'Grâce à vous, cela fait une menace de moins qui pèse sur Nazmir.', 28153),
(147914, 'frFR', '', 'Je n\’avais jamais vu pareille infestation… Vite, prenez une torche et décimez ces choses avant que cela n\’empire.', 28153),
(147913, 'frFR', 'Bienvenue dans la bande, $p. Ici, on se serre les coudes !', '', 28153),
(147912, 'frFR', 'On va charger le rafiot, s\’engager sur cette rivière et dézinguer du Troll de sang. Qui est de la partie ?', '', 28153),
(147911, 'frFR', 'Je suis prêt, montons à bord de la barge et regagnons Zul\’jan.', 'Je suis prête, montons à bord de la barge et regagnons Zul\’jan.', 28153),
(147910, 'frFR', 'Vous êtes là pour le M.E.C.H., c\’est ça ? Excellent ! Mieux vaut se tirer d\’ici le plus vite possible.\n\nJe vais essayer de diriger ce truc. En cas de pépin, vous n\’aurez qu\’à crier et j\’ouvrirai le feu.\n\nOn y va ?', '', 28153),
(147909, 'frFR', 'D\’autres saurides déferlent pour protéger l\’œuf !', 'D\’autres saurides déferlent pour protéger l\’œuf !', 28153),
(147908, 'frFR', 'Vukuba sort de l\’œuf !', 'Vukuba sort de l\’œuf !', 28153),
(147907, 'frFR', 'Tout bien réfléchi…', 'Tout bien réfléchi…', 28153),
(147906, 'frFR', 'Des saurides ensorcelés se ruent sur vous pour protéger l\’œuf !', 'Des saurides ensorcelés se ruent sur vous pour protéger l\’œuf !', 28153),
(147905, 'frFR', '', 'Que les esprits veillent sur nous.', 28153),
(147904, 'frFR', 'Voici vos frères et sœurs de la Défense d\’or !', '', 28153),
(147903, 'frFR', 'Vous, là ! Je peux savoir ce que vous faites ?', '', 28153),
(147902, 'frFR', 'La victoire est à portée de main ! Attaquez la base ennemie !', '', 28153),
(147901, 'frFR', 'La passe de Vaillehuche constitue le dernier obstacle entre nous et Stromgarde !', '', 28153),
(147900, 'frFR', 'On s\’empare du cercle des Éléments, et le tour est joué !', '', 28153),
(147899, 'frFR', 'Votre nouvelle mission : mettre Grangeneuve à sac ! On doit empêcher l\’Alliance de nous contourner !', '', 28153),
(147898, 'frFR', 'Le plus rapide pour rejoindre Stromgarde, c\’est de passer par Haut-Perchoir. Emparez-vous-en !', '', 28153),
(147897, 'frFR', 'Direction la croisée de Nordclos. L\’ennemi se presse à nos portes !', '', 28153),
(147896, 'frFR', '', 'Ne vous éloignez pas, messieurs. Nous franchirons les lignes des sorcières discrètement.', 28153),
(147895, 'frFR', '', 'Nous retrouverons donc notre $Uami:amie; là-bas. Bonne chance.', 28153),
(147894, 'frFR', '', 'Maître Ashton, allez-vous rester jusqu\’à la fin ?', 28153),
(147893, 'frFR', 'Il semblerait qu\’il y ait eu beaucoup d\’activité dans les ruines près du grand arbre.', '', 28153),
(147892, 'frFR', 'Oui. Marten et moi devons être là.', '', 28153),
(147891, 'frFR', 'Fantastique.', '', 28153),
(147890, 'frFR', 'J\’aurais dû consacrer mes talents à la pêche.', 'J\’aurais dû consacrer mes talents à la pêche.', 28153),
(147889, 'frFR', 'Qu\’est-ce qui vous a pris tout ce temps ?', 'Qu\’est-ce qui vous a pris tout ce temps ?', 28153),
(147888, 'frFR', '', 'J\’espère que ça sera assez pour rassasier le Loa.', 28153),
(147887, 'frFR', '', 'Krag\’wa est un Loa impulsif friand de mets et de présents. Vous pourriez peut-être lui apporter en offrande des créatures de la région.', 28153),
(147886, 'frFR', 'Ils existent que dans votre esprit, pas dans les dunes.', '', 28153),
(147885, 'frFR', '', 'Encore un coup de Jakra\’zet ?', 28153),
(147884, 'frFR', 'Examiner l\’œuf.', 'Examiner l\’œuf.', 28153),
(147883, 'frFR', 'Cet œuf est bien trop gros pour le nid. Et pourtant les saurides des environs semblent en prendre soin…', 'Cet œuf est bien trop gros pour le nid. Et pourtant les saurides des environs semblent en prendre soin…', 28153),
(147882, 'frFR', 'Grenja ! Volni ! Man\’zul ! Vous êtes revenus ! La bande est au complet !', '', 28153),
(147881, 'frFR', 'Je largue les amarres !', 'Je largue les amarres !', 28153),
(147880, 'frFR', 'Vous avez fait la volonté de Bwonsamdi, $c.', 'Vous avez fait la volonté de Bwonsamdi, $c.', 28153),
(147879, 'frFR', 'Je sentais mon être se dissiper…', 'Je sentais mon être se dissiper…', 28153),
(147878, 'frFR', 'Inutile de venir ici, Furie-des-Sables ! Vous ne trouverez que des bananes.', '', 28153),
(147877, 'frFR', 'Te voilà enfin, Zulsan. Notre petite bande a de gros ennuis !', '', 28153),
(147876, 'frFR', 'Reculez, espèces de brutes ! Vous ne torturerez plus mon peuple !', '', 28153),
(147875, 'frFR', '', 'Bien joué ! Je ne tolérerai l\’existence d\’aucune menace envers mon peuple !', 28153),
(147874, 'frFR', '', 'Les esprits, ils me parlent d\’une entité très puissante dans les parages. Soyez sur vos gardes.', 28153),
(147873, 'frFR', 'Je le savais ! Des êtres étranges qui vivent au fond de l\’océan ne peuvent pas créer de système politique !', 'Je le savais ! Des êtres étranges qui vivent au fond de l\’océan ne peuvent pas créer de système politique !', 28153),
(147872, 'frFR', 'Où est la milice ? Où sont les Chantorage ?', 'Où est la milice ? Où sont les Chantorage ?', 28153),
(147871, 'frFR', 'Je dois quitter cet endroit ! Ça m\’est égal s\’ils me transpercent avec leurs piquants !', 'Je dois quitter cet endroit ! Ça m\’est égal s\’ils me transpercent avec leurs piquants !', 28153),
(147870, 'frFR', 'Enfin un visage amical ! Les marmites étaient presque vides…', 'Enfin un visage amical ! Les marmites étaient presque vides…', 28153),
(147869, 'frFR', 'Je ne veux pas finir au menu des Hurans !', 'Je ne veux pas finir au menu des Hurans !', 28153),
(147868, 'frFR', 'Il me faut des munitions pour Sorcicide.', 'Il me faut des munitions pour Sorcicide.', 28153),
(147867, 'frFR', 'Les esprits, ils sont avec vous, $p.', 'Les esprits, ils sont avec vous, $p.', 28153),
(147866, 'frFR', 'Enfin libre…', 'Enfin libre…', 28153),
(147865, 'frFR', 'Je vais enfin voir Bwonsamdi.', 'Je vais enfin voir Bwonsamdi.', 28153),
(147864, 'frFR', 'Merci, j\’oublierai jamais ça.', 'Merci, j\’oublierai jamais ça.', 28153),
(147863, 'frFR', 'Faites-leur la peau, $p ! Zulsan et moi, on vous retrouvera à l\’auberge.', '', 28153),
(147862, 'frFR', 'La barrière est tombée ! Le manoir Malvoie nous attend !', '', 28153),
(147861, 'frFR', 'Celui-ci devrait faire l\’affaire.', '', 28153),
(147860, 'frFR', 'Le maréchal m\’a chargé de vous trouver un canon.', '', 28153),
(147859, 'frFR', 'C\’est… impossible…', '', 28153),
(147858, 'frFR', 'Le Sabbat malecarde m\’a accordé une puissance inégalable ! Vous allez mourir !', '', 28153),
(147857, 'frFR', 'Mort aux ennemis du Sabbat !', '', 28153),
(147856, 'frFR', 'C\’est au sujet d\’un de ses anciens soldats.', '', 28153),
(147855, 'frFR', 'Ah, au fait, le maréchal a demandé à vous parler avant votre départ.', '', 28153),
(147854, 'frFR', 'Comment êtes-vous… Attendez, ne m\’dites pas que vous êtes avec le Sabbat, quand même ?', '', 28153),
(147853, 'frFR', '', 'Hé ho ? Il y a quelqu\’un ?', 28153),
(147852, 'frFR', '', 'Vous arrivez trop tard… pour nous arrêter…', 28153),
(147851, 'frFR', '', 'Mes créations réduiront ce lieu à néant !', 28153),
(147850, 'frFR', '', 'La malédiction… subsiste…', 28153),
(147849, 'frFR', '', 'Vos os feront une parfaite effigie !', 28153),
(147848, 'frFR', '', 'Ma mort… n\’a aucune importance… notre maître… est éternel…', 28153),
(147846, 'frFR', '', 'Vous ferez un tribut de choix !', 28153),
(147845, 'frFR', '', 'Tout Kul Tiras sera plongé dans la douleur !', 28153),
(147844, 'frFR', '', 'Gorak Tul vous fera connaître la souffrance éternelle !', 28153),
(147843, 'frFR', '', 'Seul le désespoir vous attend dans les confins Corrompus !', 28153),
(147842, 'frFR', '', 'Le maître se délectera de cette douleur !', 28153),
(147839, 'frFR', 'C\’est la partie que je préfère. Vous allez adorer, ça donne des frissons.', '', 28153),
(147833, 'frFR', 'Ah, oui. C\’est bien ce que je pensais.', '', 28153),
(147830, 'frFR', 'Il a l\’air inoffensif, mais je peux vous assurer qu\’il a l\’art et la manière de duper les gens pour arriver à ses fins. Ce voyou ne vous causera que des ennuis.', '', 28153),
(147829, 'frFR', 'Si j\’étais vous, je n\’accorderais pas mon aide à Hank sans réfléchir.', '', 28153),
(147828, 'frFR', '', 'Les esprits rejoindront bientôt Bwonsamdi. Merci de les avoir libérés d\’une éternité de servitude.', 28153),
(147827, 'frFR', '', 'Ces ignobles nécromanciens retiennent des esprits trolls captifs pour leurs rituels ! Éliminez-les et nous pourrons libérer les esprits.', 28153),
(147826, 'frFR', 'Des criminels furie-des-sables ont attaqué l\’auberge !\n\nMoi et cette banane, on y a échappé de justesse… Bah quoi ? Elle avait l\’air importante sur le moment.', '', 28153),
(147825, 'frFR', 'À l\’aide ! Vous êtes là, $n ? Retournez pas à l\’auberge ! Les Furie-des-Sables nous ont trouvés !', '', 28153),
(147824, 'frFR', '', 'Nous vous attendrons dehors, $n. En route.', 28153),
(147823, 'frFR', 'Pour chaque bête qu\’on tue, y en a deux autres qui prennent sa place. Votre garde, la baissez jamais, d\’accord ?', '', 28153),
(147822, 'frFR', 'Une ignoble abomination a surgi de la terre. Tuez-la… avant qu\’elle nous élimine tous !', '', 28153),
(147821, 'frFR', 'Qu\’est-ce qui te prend donc ? C\’est ma botte, ça !', '', 28153),
(147820, 'frFR', 'Une intrusion ! Qui brise nos ronces ?', 'Une intrusion ! Qui brise nos ronces ?', 28153),
(147819, 'frFR', 'Alertez le kraal !', 'Alertez le kraal !', 28153),
(147818, 'frFR', 'Gardes ! À moi !', 'Gardes ! À moi !', 28153),
(147817, 'frFR', 'Pique comme l\’abeille !', 'Piquez comme l\’abeille !', 28153),
(147816, 'frFR', 'On forme une fine équipe.', 'On forme une fine équipe.', 28153),
(147815, 'frFR', 'Repoussez-les vers les montagnes !', 'Repoussez-les vers les montagnes !', 28153),
(147814, 'frFR', 'Oublie ça. Donne-le à manger à Petit-Doigt. Ha ha ha !', '', 28153),
(147813, 'frFR', 'Vous ne me prendrez pas ma ferme !', 'Vous ne me prendrez pas ma ferme !', 28153),
(147812, 'frFR', 'Donne-lui un gros coup et il t\’écoutera !', '', 28153),
(147811, 'frFR', 'C\’était du tout cuit.', 'C\’était du tout cuit.', 28153),
(147810, 'frFR', 'Tu dois être plus ferme avec lui pour qu\’il te respecte.', '', 28153),
(147809, 'frFR', 'Ha ha. Bien fait !', 'Ha ha ! Bien fait !', 28153),
(147808, 'frFR', 'Espèce de bon à rien ! Tu vas finir en chair à saucisse si tu continues !', 'Espèce de bon à rien ! Tu vas finir en chair à saucisse si tu continues !', 28153),
(147807, 'frFR', 'Ça suffit comme ça ! Tu l\’auras bien cherché !', 'Ça suffit comme ça ! Tu l\’auras bien cherché !', 28153),
(147806, 'frFR', 'Où tu vas ? Attaque-le !', 'Où tu vas ? Attaque-le !', 28153),
(147801, 'frFR', 'J\’me casse !', '', 28153),
(147800, 'frFR', 'Hors de question que je meure pour ces pauvres types !', '', 28153),
(147799, 'frFR', 'Je suis pas assez payé pour ça !', '', 28153),
(147798, 'frFR', 'Bzzzz !', '', 28153),
(147796, 'frFR', '', 'Allez au diable…', 28153),
(147795, 'frFR', '', 'Moira, je vais lui rapporter l\’Œil ET votre tête en prime !', 28153),
(147794, 'frFR', 'On m\’a forcé à tuer ces marchands… Je ne pouvais pas m\’arrêter.', 'On m\’a forcée à tuer ces marchands… Je ne pouvais pas m\’arrêter.', 28153),
(147793, 'frFR', 'Où suis-je ?', 'Où suis-je ?', 28153),
(147792, 'frFR', 'Les Furie-des-Sables paieront pour ça !', 'Les Furie-des-Sables paieront pour ça !', 28153),
(147791, 'frFR', 'Enfin libre !', 'Enfin libre !', 28153),
(147789, 'frFR', '', '<Une longueur de corde coupée avec soin est attachée à sa cheville.$B$BL\’arme qui a transpercé son cœur a disparu.$B$BEt aucune empreinte n\’est visible à proximité du corps.>', 28153),
(147788, 'frFR', 'Écrase ce vaurien, MAINTENANT !', 'Écrase ce vaurien, MAINTENANT !', 28153),
(147787, 'frFR', 'Vas-y, petit. À l\’attaaaaque !', 'Vas-y, petit. À l\’attaaaaque !', 28153),
(147786, 'frFR', 'Bon, alors, quand le dino mord à l\’appât, tu charges ! Compris ?', 'Bon, alors, quand le dino mord à l\’appât, tu charges ! Compris ?', 28153),
(147785, 'frFR', 'Esclaves ! Tuez ces intrus !', 'Esclaves ! Tuez ces intrus !', 28153),
(147784, 'frFR', 'Yiiaa-ouille !', 'Yiiaa-ouille !', 28153),
(147783, 'frFR', '', 'Je vous remercie. Désormais, les âmes des morts pourront s\’en aller en paix.', 28153),
(147782, 'frFR', '', 'Jadis, ce monstre était un gardien des fidèles. Aujourd\’hui, il se nourrit de l\’âme des morts. Détruisez-le !', 28153),
(147781, 'frFR', 'Jamais vous me briserez, $PR…', '', 28153),
(147780, 'frFR', 'D\’abord, je vous brise, et après je vous vends.', '', 28153),
(147779, 'frFR', '', 'On a c\’qu\’on voulait, les gars ! On s\’bouge !', 28153),
(147778, 'frFR', '', 'Bien joué ! On ne peut pas laisser de telles horreurs proliférer sur notre domaine.', 28153),
(147777, 'frFR', '', 'La terre même a donné naissance à une abomination ! Vite, détruisez-la avant qu\’elle ne rampe jusqu\’à Zuldazar !', 28153),
(147775, 'frFR', 'Je me demande si ça a un rapport avec ces choses qui détruisent la ferme.', '', 28153),
(147774, 'frFR', 'C\’est là qu\’il a dû se rendre à la nuit tombée.', '', 28153),
(147773, 'frFR', 'Je savais pas qu\’il y avait tout ça ici.', '', 28153),
(147772, 'frFR', 'Papa a quelques réponses à nous donner…', '', 28153),
(147771, 'frFR', 'Qu\’est-ce qui s\’est passé ici ?', '', 28153),
(147770, 'frFR', 'C\’est bizarre.', '', 28153),
(147769, 'frFR', 'Qu\’est-ce que c\’est ?', '', 28153),
(147768, 'frFR', 'Hmm…', '', 28153),
(147767, 'frFR', 'À une prochaine fois !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(147766, 'frFR', 'Petit, petit ! C\’est l\’heure de manger !', 'Petit, petit ! C\’est l\’heure de manger !', 28153),
(147765, 'frFR', 'Je croiserai les résultats des relevés pendant que vous revenez au camp. Je peux pratiquement sentir l\’Œil !', '', 28153),
(147764, 'frFR', 'Fascinant. Je pense qu\’on tient quelque chose, $n.', '', 28153),
(147763, 'frFR', 'Je détecte une faible signature arcanique ! Nous nous rapprochons.', '', 28153),
(147762, 'frFR', 'Ma foi, ce relevé est loin d\’être prometteur.', '', 28153),
(147761, 'frFR', '', 'G\’huun aura sa vengeance !', 28153),
(147760, 'frFR', '', 'Mes chéris, ils vont vous becqueter !', 28153),
(147758, 'frFR', '', 'Quoi ? Laisse-moi voir.', 28153),
(147757, 'frFR', '', 'Pff… Il se passe jamais rien d\’intéressant pendant ces patrouilles.', 28153),
(147756, 'frFR', '', 'Ha ha ha !', 28153),
(147755, 'frFR', '', 'Ils peuvent pleurer et supplier, mais ça change rien. Ils y passent tous.', 28153),
(147754, 'frFR', '', 'Houla.', 28153),
(147753, 'frFR', '', 'Eh, c\’est quoi ça ?', 28153),
(147752, 'frFR', '', 'T\’as vu comme ils se tortillaient ?', 28153),
(147751, 'frFR', '(Dire à Yash que s\’il veut vivre une folle aventure, il devrait se rendre à Glaucombe et aider à combattre les Trolls de sang et leur dieu.)', '(Dire à Yash que s\’il veut vivre une folle aventure, il devrait se rendre à Glaucombe et aider à combattre les Trolls de sang et leur dieu.)', 28153),
(147750, 'frFR', 'Je ne pense pas que les détails de la mort d\’un Loa éventré intéressent les Tortollans… Que vais-je raconter aux autres en rentrant ?', '', 28153),
(147749, 'frFR', '(Dire à Korkush qu\’il pourrait devenir un héros digne de légendes s\’il aide la Horde à combattre les Trolls de sang et à sauver les Zandalari.)', '(Dire à Korkush qu\’il pourrait devenir un héros digne de légendes s\’il aide la Horde à combattre les Trolls de sang et à sauver les Zandalari.)', 28153),
(147748, 'frFR', 'Bah, Torga est mort, les Trolls de sang ont envahi les lieux… c\’est tout le pélerinage qui tombe à l\’eau ! Je n\’ai aucune raison de rester.', '', 28153),
(147747, 'frFR', '(Raconter à Crez ce qui est arrivé à Torga, et évoquer les histoires qui pourraient naître de son passage à Glaucombe.)', '(Raconter à Crez ce qui est arrivé à Torga, et évoquer les histoires qui pourraient naître de son passage à Glaucombe.)', 28153),
(147744, 'frFR', 'Un esprit millénaire qui cherche à se venger en nous tuant tous ? Charmant.', '', 28153),
(147743, 'frFR', 'Leur maître ?', '', 28153),
(147742, 'frFR', 'D\’après ce que j\’étais entendu quand j\’étais retenu captif, cette entité serait liée aux Drust.', '', 28153),
(147741, 'frFR', 'Il hait les Kultirassiens de tout son être, et les sorcières ne lui servent que de pions pour assurer son retour.', '', 28153),
(147740, 'frFR', 'La force maléfique à l\’origine de leur pouvoir. J\’ai entendu sa rage gronder dans les ténèbres.', '', 28153),
(147739, 'frFR', 'Les sorcières ont parlé d\’un « grand rite » pour accueillir leur maître en ce monde.', '', 28153),
(147738, 'frFR', 'Nous avons plus urgent à faire, inquisitrice !', '', 28153),
(147737, 'frFR', 'Oui, je crois. Merci, Marten. Et à vous aussi, $n.', '', 28153),
(147736, 'frFR', '', 'Nous devons empêcher ce « grand rite » à tout prix.', 28153),
(147735, 'frFR', '', 'Au chef des Drust, je dirais même. Celui contre lequel Arom Malvoie s\’est battu il y a des siècles de ça.', 28153),
(147734, 'frFR', '', 'Nous devrions retourner à Butte-du-Faucon.', 28153),
(147733, 'frFR', '', 'Maître Ashton, êtes-vous de retour parmi nous ?', 28153),
(147732, 'frFR', 'Aaaahhh ! La Gelée royale !', '', 28153),
(147731, 'frFR', 'Tenez vos positions ! Tuez tout ce qui bouge !', '', 28153),
(147730, 'frFR', 'Eh, qu\’est-ce que vous voulez ? Je suis sur le point de rentrer, il ne se passe plus rien d\’intéressant ici, de toute façon.', '', 28153),
(147729, 'frFR', 'Placer la pièce maudite', 'Placer la pièce maudite', 28153),
(147728, 'frFR', 'Bien joué. Ces… choses, elles devraient rester sous la terre et jamais en sortir.', '', 28153),
(147727, 'frFR', 'Ces Trolls natha\’vor, ils arrosent la flore locale avec le sang des sacrifiés. Vous devez les arrêter avant que les plantes carnivores envahissent tout.', '', 28153),
(147726, 'frFR', 'Comptez sur moi !', '', 28153),
(147725, 'frFR', 'Très bien. Champions, avec moi. Mekkanivelle, traversez la forteresse avec le reste de nos troupes et postez-vous à Brill. Tenez-vous prêts à attaquer à mon signal.', '', 28153),
(147724, 'frFR', 'Allez. Descendez la route et trouvez le meilleur emplacement. Cette pièce, placez-la en plein milieu. Mais attention que les prédateurs, ils vous voient pas…', '', 28153),
(147723, 'frFR', 'Hé, $n, à quoi peut bien servir tout ce matériel, selon vous ?', '', 28153),
(147722, 'frFR', 'On dirait un fragment des créatures qui rôdent à l\’extérieur…', '', 28153),
(147721, 'frFR', 'Une carte ? Hum… il y a une marque rouge, près du champ de fleurs.', '', 28153),
(147720, 'frFR', 'Salut. Z\’avez apporté un cadeau tout vieux et tout terni au sanctuaire des Miséreux, au moins ?', '', 28153),
(147719, 'frFR', 'Salut. Z\’avez apporté un cadeau tout moche et tout plein d\’écailles au sanctuaire des Miséreux, au moins ?', '', 28153),
(147718, 'frFR', '<Renifle.> Pouah… Ça, c\’est tout sauf du miel.', '', 28153),
(147717, 'frFR', 'Je viens tout juste de récolter du miel, si ça vous intéresse.', '', 28153),
(147716, 'frFR', 'Bienvenue aux Quatre Dards, $PR, le seul et unique rucher de Vol\’dun !', '', 28153),
(147715, 'frFR', 'Salut. Z\’avez apporté un cadeau tout beau et tout brillant au sanctuaire des Miséreux, au moins ?', '', 28153),
(147714, 'frFR', '', 'Trouvez nos ennemis et éliminez-les !', 28153),
(147713, 'frFR', '', 'Lève-toi, esprit des eaux ! Nous demandons ton aide !', 28153),
(147712, 'frFR', '', 'Les vents ici bas sont lents et constants, dans les cieux cependant il en est autrement.', 28153),
(147711, 'frFR', 'Allez voir l\’autre Loa. Je sillonnerai les jardins à la recherche d\’autres envahisseurs à tuer.', '', 28153),
(147710, 'frFR', 'Hérétiques ! Comment osez-vous pénétrer dans MON antre ? Je vais vous réduire en poussière !', '', 28153),
(147709, 'frFR', 'Ah, qui vient ? Êtes-vous ici pour chasser l\’hérétique avec moi ?', '', 28153),
(147708, 'frFR', 'Libérez-moi…', '', 28153),
(147707, 'frFR', '', 'Esprit de feu, que les éléments te guident ! Nous implorons ton aide dans la bataille qui se présente à nous !', 28153),
(147706, 'frFR', 'Toutes ces choses que j\’ai vues… L\’horreur… L\’horreur…', '', 28153),
(147705, 'frFR', 'Toutes ces choses que j\’ai vues…', '', 28153),
(147704, 'frFR', 'Salut, $Ucossu:cossue;. Z\’avez apporté un cadeau tout luisant et tout brillant au sanctuaire des Miséreux, au moins ?', '', 28153),
(147703, 'frFR', 'Regardez… Le miel, il se déplace tout seul !', '', 28153),
(147702, 'frFR', '<Donner la potion à maître Ashton.>', '<Donner la potion à maître Ashton.>', 28153),
(147701, 'frFR', 'Salut, $Ucossu:cossue;. Z\’avez apporté un cadeau tout lisse et tout doré au sanctuaire des Miséreux, au moins ?', '', 28153),
(147700, 'frFR', 'Trop fort ! Moi, je veux devenir comme vous quand je serai grand.', '', 28153),
(147699, 'frFR', 'C\’était gagné d\’avance !', '', 28153),
(147698, 'frFR', 'Prends ça !', '', 28153),
(147697, 'frFR', 'Wouah, c\’était impressionnant !', '', 28153),
(147696, 'frFR', 'OK, $gmon gars:ma belle;, retrouvez-moi à la Chute d\’Aile de mort. On utilisera la lave pour fondre nos matériaux. J\’apporterai quelques fournitures supplémentaires.', '', 28153),
(147695, 'frFR', 'Mph mph mph !', 'Mff mff mff !', 28153),
(147694, 'frFR', 'J\’apprécie vraiment c\’que vous avez fait pour moi. Après tout le boulot abattu, j\’avais peur que cette enclume vaille plus que moi à vos yeux.$b$bHeureusement que Therazane vous l\’a donnée quand même.$b$bCela dit, si j\’étais vous, j\’prendrais son avertissement au sérieux. N\’allez pas crier sur les toits le secret de not\’ réussite.', '', 28153),
(147693, 'frFR', 'Mph mph mph mph. Mph mph mph.', 'Mff mff mff mff. Mff mff mff.', 28153),
(147692, 'frFR', 'Mph mph mph. Mph.', '', 28153),
(147691, 'frFR', 'Ah, et Plomb a une histoire à raconter !', 'Ah, et Plomb a une histoire à raconter !', 28153),
(147690, 'frFR', 'Mph mph, mph mph mph !', 'Mph mph, mph mph mph !', 28153),
(147689, 'frFR', 'Oui, Plomb a raison. On n\’a pas vu Ozumat depuis le Cataclysme !', 'Oui, Plomb a raison. On n\’a pas vu Ozumat depuis le Cataclysme !', 28153),
(147688, 'frFR', 'Et c\’est comme ça que j\’ai hissé sur ce mât, le monstre des abysses.', 'Et c\’est comme ça que j\’ai hissé sur ce mât, le monstre des abysses.', 28153),
(147687, 'frFR', 'Passons aux choses sérieuses !', 'Passons aux choses sérieuses !', 28153),
(147686, 'frFR', 'Le problème des tentacules réglé, il était temps de finir le boulot.', 'Le problème des tentacules réglé, il était temps de finir le boulot.', 28153),
(147685, 'frFR', 'Ozumat ? J\’ai dû taper dans l\’œil du destin.', 'Ozumat ? J\’ai dû taper dans l\’œil du destin.', 28153),
(147684, 'frFR', 'Mais ça a fini par attirer d\’vinez quoi ? Le léviathan Ozumat, en chair et en tentacules !', 'Mais ça a fini par attirer d\’vinez quoi ? Le léviathan Ozumat, en chair et en tentacules !', 28153),
(147683, 'frFR', 'Et sur ce, il est l\’heure pour ce poulet de quitter le nid ! Bonne chance, mon ami !', '', 28153),
(147682, 'frFR', 'Ne vous inquiétez pas, Pam, vous n\’allez pas y perdre de plumes !', '', 28153),
(147681, 'frFR', '', 'Bonne chance. N\’oubliez pas, on ne doit pas remonter jusqu\’à moi.', 28153),
(147680, 'frFR', 'L\’activité géothermique est intense sur cette île. Quand un geyser entre en éruption, de l\’azérite remonte forcément dans les fissures. Tout ce minerai doit valoir une fortune !', 'L\’activité géothermique est intense sur cette île. Quand un geyser entre en éruption, de l\’azérite remonte forcément dans les fissures. Tout ce minerai doit valoir une fortune !', 28153),
(147679, 'frFR', 'Et on recommence, ma chère amie ! Embarquons ces petits poulets !', '', 28153),
(147678, 'frFR', 'Avec plaisir.', '', 28153),
(147677, 'frFR', 'Je suis aussi venu avec un ami à moi, Hank. Verrick, montrez-leur ce que vous savez faire.', '', 28153),
(147676, 'frFR', 'Greer, mon gars ! Comment ça va, par cette belle journée ? Nous avons quelques amis à plumes à expédier !', '', 28153),
(147675, 'frFR', 'Eh bien, regardez qui va là.', '', 28153),
(147674, 'frFR', 'Les menaces qui pèsent sur mon peuple sont nombreuses, mais la plus préoccupante est celle qui corrompt les Trolls de sang.\n\nLeur odeur nauséabonde empeste jusqu\’ici. Quand vous aurez fait votre choix, nous nous attaquerons à la source du problème ensemble.', '', 28153),
(147673, 'frFR', 'Une victoire minuscule… mais une victoire quand même.', '', 28153),
(147672, 'frFR', 'Saisissez cette occasion !', '', 28153),
(147671, 'frFR', 'Vous ne trouverez rien dans ces galeries gorgées de sel.', 'Vous ne trouverez rien dans ces galeries gorgées de sel.', 28153),
(147670, 'frFR', 'La mortalité expliquée en un coup !', '', 28153),
(147669, 'frFR', 'Une raclée décisive !', '', 28153),
(147668, 'frFR', 'Leurs champions maudits sont tombés !', '', 28153),
(147667, 'frFR', 'Un ennemi s\’éteint, un nouvel espoir émerge.', '', 28153),
(147666, 'frFR', 'Détruisez. Les. Tous.', '', 28153),
(147665, 'frFR', 'Reposez-vous, à présent. Cet endroit accable votre esprit. Revenez dans trois jours, vous aurez peut-être la résolution d\’affronter à nouveau ces horreurs.', '', 28153),
(147664, 'frFR', 'Je suis prêt à chasser avec la meute.', 'Je suis prête à chasser avec la meute.', 28153),
(147663, 'frFR', '', 'Bienvenue dans la meute, $p. Vous avez fait du bon travail.', 28153),
(147662, 'frFR', 'Mettez la Horde à genoux !', 'Mettez la Horde à genoux !', 28153),
(147661, 'frFR', 'Houah !', 'Houah !', 28153),
(147660, 'frFR', 'Mort à nos ennemis !', 'Mort à nos ennemis !', 28153),
(147659, 'frFR', 'Pour Stromgarde !', 'Pour Stromgarde !', 28153),
(147658, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(147657, 'frFR', 'Pour la gloire de l\’Alliance !', '', 28153),
(147656, 'frFR', 'À l\’attaque !', '', 28153),
(147655, 'frFR', 'Frappez !', '', 28153),
(147654, 'frFR', 'Excellent.', '', 28153),
(147653, 'frFR', 'N\’oubliez pas votre entraînement.', '', 28153),
(147652, 'frFR', 'Tenez bien sur vos appuis.', '', 28153),
(147651, 'frFR', 'Joli.', '', 28153),
(147650, 'frFR', 'Bon travail.', '', 28153),
(147649, 'frFR', 'Arme au poing !', '', 28153),
(147648, 'frFR', 'Pensez à me rendre honneur, $p. Je vous garderai à l\’œil.', '', 28153),
(147647, 'frFR', 'Vous avez bien fait de l\’envoyer, Loti. $p renforce la puissance de la meute.', '', 28153),
(147646, 'frFR', 'Une fois encore, nous allons traverser les ténèbres pour accélérer notre voyage. Accrochez-vous.', '', 28153),
(147645, 'frFR', 'Érigez une statue à mon image dans la ville, $p. Chantez les prouesses de la meute. Nos prouesses.', '', 28153),
(147644, 'frFR', 'Je suis prêt à retourner à Dazar\’alor en tant que votre champion.', 'Je suis prête à retourner à Dazar\’alor en tant que votre championne.', 28153),
(147643, 'frFR', 'Vous avez dirigé la meute de manière exemplaire aujourd\’hui, $p.\n\nL\’union fait notre force.', '', 28153),
(147642, 'frFR', 'Ça, c\’est de la pêche à l\’explosif !', 'Ça, c\’est de la pêche à l\’explosif !', 28153),
(147641, 'frFR', 'Pêche', 'Pêche', 28153),
(147640, 'frFR', 'Montez sur mon dos une fois encore et je vous conduirai à Dazar\’alor.', '', 28153),
(147639, 'frFR', 'Vous avez dirigé la meute avec brio, $p. J\’aimerais vous accorder le titre de champion.', '', 28153),
(147638, 'frFR', 'Votre sang n\’aura pas le temps de sécher que ce ne sera déjà plus qu\’un mauvais souvenir.', '', 28153),
(147637, 'frFR', '$n, qui était-ce ? Elle se bat avec une telle fureur…', '', 28153),
(147636, 'frFR', '$p va diriger la meute pour le moment… Tâchez de vous montrer digne de cet honneur.', '', 28153),
(147635, 'frFR', 'Les Trolls de sang sont tout proches. Notre meute en a déjà repéré quelques-uns.', '', 28153),
(147634, 'frFR', 'Debout, membres de la meute ! Réveillez-vous et préparez-vous en mon absence. Nous nous mettrons bientôt en chasse !', '', 28153),
(147633, 'frFR', 'Montez sur mon dos, $p. Vous n\’avez pas idée de la vitesse que peut atteindre un Loa pressé.', '', 28153),
(147632, 'frFR', 'Je sentais mon esprit m\’échapper. Je vous dois la vie.', 'Je sentais mon esprit m\’échapper. Je vous dois la vie.', 28153),
(147631, 'frFR', '', 'Mon sang va empoisonner cette terre pendant des générations.', 28153),
(147630, 'frFR', '', 'Faibles et arrogants esclaves des Loas ! G\’huun est tout-puissant !', 28153),
(147629, 'frFR', '', 'Oh, ne vous inquiétez pas. C\’est une mèche spéciale de ma conception. Elle ne se déclenche que quand une conversation m\’ennuie.\n\nDonc… Boum.', 28153),
(147628, 'frFR', 'Est-ce que c\’est un bâton de dynamite allumé dans votre main ?', 'Est-ce que c\’est un bâton de dynamite allumé dans votre main ?', 28153),
(147627, 'frFR', '', 'Certains pensent que manipuler des explosifs peut être dangereux. Ils sont loin du compte.', 28153),
(147625, 'frFR', '', 'Faites votre choix.', 28153),
(147624, 'frFR', '', 'Ou prendre l\’enclume que vous avez fabriquée, celle que vous convoitiez depuis le début.', 28153),
(147623, 'frFR', '', 'Prenez une caisse, on doit faire sortir ces fournitures d\’ici, tant que c\’est encore possible.', 28153),
(147622, 'frFR', '', 'Vous pouvez décider de libérer votre allié, celui qui a trahi son peuple en partageant avec vous un savoir jalousement gardé…', 28153),
(147621, 'frFR', '', 'Beau travail, créature de chair. Je vais maintenant vous remettre votre récompense : un choix.', 28153),
(147620, 'frFR', '<Prendre le pterreurdactyle dans vos bras.>', '<Prendre le pterreurdactyle dans vos bras.>', 28153),
(147618, 'frFR', '<Kua\’fon vous accueille d\’un petit cri.>\n\nSkriii !', '', 28153),
(147617, 'frFR', '<Kua\’fon dodeline de la tête à votre approche.>', '', 28153),
(147616, 'frFR', '<Kua\’fon cherche à attirer votre attention.>\n\nSkriii ?', '', 28153),
(147615, 'frFR', '<Kua\’fon vous regarde avec curiosité.>', '', 28153),
(147614, 'frFR', 'Leur chef est droit devant, $p. Poursuivez l\’assaut et, ensemble, nous la tuerons.', '', 28153),
(147613, 'frFR', 'Ha ! Voilà qui était amusant…', '', 28153),
(147612, 'frFR', 'Chargez, mes frères et sœurs ! Ne leur laissez aucun répit !', '', 28153),
(147611, 'frFR', 'Suivez-moi, $p. Je vais vous montrer comment se bat un Loa.', '', 28153),
(147610, 'frFR', 'Tous avec moi, membres de la meute ! Il est temps d\’en finir !', '', 28153),
(147609, 'frFR', '', 'Très bien, être de chair. Triomphez de mon colosse, et vous vous attirerez mes bonnes grâces.', 28153),
(147608, 'frFR', '', 'Plus de temps à perdre. Meurs, animal !', 28153),
(147607, 'frFR', 'J\’accepte votre épreuve, Therazane.', 'J\’accepte votre épreuve, Therazane.', 28153),
(147606, 'frFR', '', 'Vous êtes une plaie pour ces terres !', 28153),
(147605, 'frFR', '', 'Ma lame ne prendra jamais de repos !', 28153),
(147604, 'frFR', '', 'Votre tribu est faible !', 28153),
(147603, 'frFR', '', 'Je serai la cause de votre mort !', 28153),
(147600, 'frFR', '<Donner des |TINTERFACE\\ICONS\\INV_MISC_BAG_09.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[croquettes pour jeune dino]|h|r.>', '<Donner des |TINTERFACE\\ICONS\\INV_MISC_BAG_09.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[croquettes pour jeune dino]|h|r.>', 28153),
(147599, 'frFR', '<Kua\’fon vous observe et ouvre sa gueule.>\n\nSKRIII ! SKRIIII !', '', 28153),
(147596, 'frFR', 'À l\’aide.', 'À l\’aide.', 28153),
(147595, 'frFR', '', 'Qu\’est-ce que vous voulez ?', 28153),
(147593, 'frFR', 'Skrii ?', '', 28153),
(147592, 'frFR', 'Skrii…', '', 28153),
(147591, 'frFR', 'SKRIIIIIII !', '', 28153),
(147590, 'frFR', 'Skrii !', '', 28153),
(147589, 'frFR', 'Tiens, bonjour, Willow.', '', 28153),
(147588, 'frFR', 'Oui, oui. Voyons ce que vous avez.', '', 28153),
(147587, 'frFR', 'Encore un peu timide. J\’ai entendu dire que vous auriez besoin de fournitures.', '', 28153),
(147586, 'frFR', 'Haha ! Il m\’avait bien semblé vous entendre arriver !', '', 28153),
(147585, 'frFR', 'Ces terres sont maudites.', 'Ces terres sont maudites.', 28153),
(147584, 'frFR', 'Le malheur s\’abatte sur ces sorcières.', 'Le malheur s\’abatte sur ces sorcières.', 28153),
(147583, 'frFR', 'Même les cultures les plus paresseuses poussent.', 'Même les cultures les plus paresseuses poussent.', 28153),
(147582, 'frFR', 'Mêlez-vous de vos affaires et je ferai de même.', 'Mêlez-vous de vos affaires et je ferai de même.', 28153),
(147581, 'frFR', 'Vous n\’êtes pas du coin, vous !', 'Vous n\’êtes pas du coin, vous !', 28153),
(147580, 'frFR', 'Quel bon vent vous amène ?', 'Quel bon vent vous amène ?', 28153),
(147579, 'frFR', 'Vous avez déjà vu un kraken de près ? Continuez et ça pourrait arriver.', 'Vous avez déjà vu un kraken de près ? Continuez et ça pourrait arriver.', 28153),
(147578, 'frFR', 'Je vais finir par croire que vous avez perdu la boussole.', 'Je vais finir par croire que vous avez perdu la boussole.', 28153),
(147577, 'frFR', 'Ho, commencez pas à me chercher des poulpes !', 'Ho, commencez pas à me chercher des poulpes !', 28153),
(147576, 'frFR', 'Nous vaincrons le Sabbat.', 'Nous vaincrons le Sabbat.', 28153),
(147575, 'frFR', 'Une bonne sorcière est une sorcière morte.', 'Une bonne sorcière est une sorcière morte.', 28153),
(147574, 'frFR', 'Gloire à la maison Malvoie !', 'Gloire à la maison Malvoie !', 28153),
(147573, 'frFR', 'Évitez les écueils avec vos ennemis.', 'Évitez les écueils avec vos ennemis.', 28153),
(147572, 'frFR', 'La marée n\’attend personne.', 'La marée n\’attend personne.', 28153),
(147571, 'frFR', 'Prenez garde, la tempête se lève au large.', 'Prenez garde, la tempête se lève au large.', 28153),
(147570, 'frFR', 'Gardez le cap et voguez à pleines voiles.', 'Gardez le cap et voguez à pleines voiles.', 28153),
(147569, 'frFR', 'Méfiez-vous de l\’eau trop calme.', 'Méfiez-vous de l\’eau trop calme.', 28153),
(147568, 'frFR', 'Puissent le vent et la mer vous être favorables.', 'Puissent le vent et la mer vous être favorables.', 28153),
(147567, 'frFR', 'Pour Kul Tiras !', 'Pour Kul Tiras !', 28153),
(147566, 'frFR', 'Ma lame est prête.', 'Ma lame est prête.', 28153),
(147565, 'frFR', 'Dans quel camp êtes-vous ?', 'Dans quel camp êtes-vous ?', 28153),
(147564, 'frFR', 'Drustvar maintient le cap.', 'Drustvar maintient le cap.', 28153),
(147563, 'frFR', 'Crachez le morceau.', 'Crachez le morceau.', 28153),
(147562, 'frFR', 'Gardez le cap.', 'Gardez le cap.', 28153),
(147561, 'frFR', 'Plus que tu ne le crois, ma puce.', '', 28153),
(147560, 'frFR', '', 'Moi aussi, j\’aide, papa ?', 28153),
(147559, 'frFR', 'Comme… ce que nous faisons, par exemple. Livrer la nourriture aux boutiques, afin que les ouvriers puissent manger et tout reconstruire, c\’est notre façon d\’aider.', '', 28153),
(147558, 'frFR', 'Faites vite.', 'Faites vite.', 28153),
(147557, 'frFR', 'Quels sont les ordres ?', 'Quels sont les ordres ?', 28153),
(147556, 'frFR', 'Prêt à hisser les voiles.', 'Prête à hisser les voiles.', 28153),
(147555, 'frFR', 'Prêt à lever l\’ancre.', 'Prête à lever l\’ancre.', 28153),
(147554, 'frFR', 'Je vous écoute.', 'Je vous écoute.', 28153),
(147553, 'frFR', '', 'Comme quoi ?', 28153),
(147552, 'frFR', 'Parce qu\’il y a beaucoup à faire.', '', 28153),
(147551, 'frFR', '', 'Pourquoi ?', 28153),
(147550, 'frFR', 'Oui, on peut dire que c\’est une journée particulièrement animée.', '', 28153),
(147549, 'frFR', '', 'Papa, c\’est toujours aussi animé, ici ?', 28153),
(147548, 'frFR', 'Pour la victoire !', 'Pour la victoire !', 28153),
(147547, 'frFR', 'Hiiyah !', 'Hiiyah !', 28153),
(147546, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(147545, 'frFR', 'Allons-y !', '', 28153),
(147544, 'frFR', 'En position défensive !', '', 28153),
(147543, 'frFR', 'On y arrive.', '', 28153),
(147542, 'frFR', 'Il va falloir travailler.', '', 28153),
(147541, 'frFR', 'Ça fera l\’affaire.', '', 28153),
(147540, 'frFR', 'Beau travail.', '', 28153),
(147539, 'frFR', 'Bien.', '', 28153),
(147538, 'frFR', 'Prêts !', '', 28153),
(147537, 'frFR', '', 'Gonk… est venu… pour moi.', 28153),
(147535, 'frFR', '', 'La meute… protège.', 28153),
(147534, 'frFR', 'La meute est là, Zajera. Vous n\’êtes pas seule.', '', 28153),
(147533, 'frFR', '', 'Gonk… Je suis… toute seule…', 28153),
(147531, 'frFR', '', 'Nous allons reprendre la mine, les gars ! Attrapez toute la dynamite que vous pouvez transporter et mettez-vous en route ! Retrouvons-nous à l\’entrepôt à l\’extérieur de la mine. On pourra discuter une fois sur place !', 28153),
(147530, 'frFR', '', 'Partout…', 28153),
(147529, 'frFR', '', '<Zajera est couverte de sang et souffre de nombreuses blessures. Elle éprouve des difficultés à s\’exprimer.>\n\nLa meute, elle protège... les plus faibles...', 28153),
(147528, 'frFR', 'Je voulais juste admirer la vue encore un peu.', 'Je voulais juste admirer la vue encore un peu.', 28153),
(147527, 'frFR', 'Bref, comme je disais, il nous fallait du poisson, beaucoup de poisson, pour les Bienfaits. Alors, je suis parti pêcher.', 'Bref, comme je disais, il nous fallait du poisson, beaucoup de poisson, pour les Bienfaits. Alors, je suis parti pêcher.', 28153),
(147526, 'frFR', 'Gonk est ici, Zajera. Où sont les Trolls de sang qui ont fait ça ?', 'Gonk est ici, Zajera. Où sont les Trolls de sang qui ont fait ça ?', 28153),
(147525, 'frFR', '', '<Zajera est couverte de sang et souffre de nombreuses blessures. Elle éprouve des difficultés à s\’exprimer.>\n\nGonk… prières… tu…', 28153),
(147524, 'frFR', 'Il est temps de pêcher du… ben, du poisson !', 'Il est temps de pêcher du… ben, du poisson !', 28153),
(147523, 'frFR', 'J\’ai des affaires à régler.', 'J\’ai des affaires à régler.', 28153),
(147522, 'frFR', 'Jouez avec le feu et vous vous brûlerez.', 'Jouez avec le feu et vous vous brûlerez.', 28153),
(147521, 'frFR', 'L\’Enclume noire puisse-t-elle vous bénir.', 'L\’Enclume noire puisse-t-elle vous bénir.', 28153),
(147520, 'frFR', 'Que la chaleur de la forge vous réconforte.', 'Que la chaleur de la forge vous réconforte.', 28153),
(147519, 'frFR', 'D\’innombrables secrets sont enfouis sous la terre.', 'D\’innombrables secrets sont enfouis sous la terre.', 28153),
(147518, 'frFR', 'Le clan sombrefer forgera l\’avenir du monde.', 'Le clan sombrefer forgera l\’avenir du monde.', 28153),
(147517, 'frFR', 'La montagne nous guide vers notre foyer.', 'La montagne nous guide vers notre foyer.', 28153),
(147516, 'frFR', 'Jusqu\’à quelle profondeur êtes-vous prêt à descendre ?', 'Jusqu\’à quelle profondeur êtes-vous prête à descendre ?', 28153),
(147515, 'frFR', 'Un feu brûle dans nos cœurs.', 'Un feu brûle dans nos cœurs.', 28153),
(147514, 'frFR', 'Je réponds à la voix de la montagne.', 'Je réponds à la voix de la montagne.', 28153),
(147513, 'frFR', 'Parlez, si vous y tenez.', 'Parlez, si vous y tenez.', 28153),
(147512, 'frFR', 'C\’est de la lave qui coule dans vos veines ?', 'C\’est de la lave qui coule dans vos veines ?', 28153),
(147511, 'frFR', 'Je peux faire quelque chose pour vous ?', 'Je peux faire quelque chose pour vous ?', 28153),
(147510, 'frFR', 'Notre puissance découle de la montagne.', 'Notre puissance découle de la montagne.', 28153),
(147509, 'frFR', 'Eh, ça, c\’est mon chapeau préféré ! Arg… J\’ai le tournis…', '', 28153),
(147508, 'frFR', 'Souvenir', 'Souvenir', 28153),
(147507, 'frFR', 'Si vos durillons sont pas aussi épais que votre crâne, j\’ai rien à vous dire !', 'Si vos durillons sont pas aussi épais que votre crâne, j\’ai rien à vous dire !', 28153),
(147506, 'frFR', 'Y a pas de fumée sans feu et y a pas de feu sans un Sombrefer prêt à vous chatouiller les côtes !', 'Y a pas de fumée sans feu et y a pas de feu sans un Sombrefer prêt à vous chatouiller les côtes !', 28153),
(147505, 'frFR', 'Le mont Rochenoire n\’est pas le seul à vouloir entrer en éruption !', 'Le mont Rochenoire est pas le seul à vouloir entrer en éruption !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(147504, 'frFR', 'Ici, on pratique la politique de la terre brûlée. Continuez à me chauffer et vous jouerez le rôle de la terre !', 'Ici, on pratique la politique de la terre brûlée. Continuez à me chauffer et vous jouerez le rôle de la terre !', 28153),
(147503, 'frFR', 'Une vraie trouvaille, que vous avez là.', 'Une vraie trouvaille, que vous avez là.', 28153),
(147502, 'frFR', 'Cet achat vous sera d\’une grande utilité.', 'Cet achat vous sera d\’une grande utilité.', 28153),
(147501, 'frFR', 'Nous nous reverrons.', 'Nous nous reverrons.', 28153),
(147500, 'frFR', 'Regardez mon étalage.', 'Regardez mon étalage.', 28153),
(147499, 'frFR', 'Vous n\’avez jamais rien vu de cette qualité.', 'Vous n\’avez jamais rien vu de cette qualité.', 28153),
(147498, 'frFR', 'J\’offre les merveilles venues des profondeurs.', 'J\’offre les merveilles venues des profondeurs.', 28153),
(147497, 'frFR', 'Que la marée m\’emporte, j\’ai oublié ma canne !', 'Que la marée m\’emporte, j\’ai oublié ma canne !', 28153),
(147496, 'frFR', 'C\’est là que je me suis rendu compte que j\’avais oublié ma canne ! Et sans sa canne, même le meilleur des pêcheurs se retrouve le bec dans l\’eau.', 'C\’est là que je me suis rendu compte que j\’avais oublié ma canne ! Et sans sa canne, même le meilleur des pêcheurs se retrouve le bec dans l\’eau.', 28153),
(147495, 'frFR', 'Grouillez-vous. Je suis en service.', 'Grouillez-vous. Je suis en service.', 28153),
(147494, 'frFR', 'Nous protégeons nos biens.', 'Nous protégeons nos biens.', 28153),
(147493, 'frFR', 'Moi, j\’aime pas bavarder.', 'Moi, j\’aime pas bavarder.', 28153),
(147492, 'frFR', 'Dites ce que vous avez à dire, si vous y tenez.', 'Dites ce que vous avez à dire, si vous y tenez.', 28153),
