(147451, 'frFR', 'Comment je peux vous aider ?', 'Comment je peux vous aider ?', 28153),
(147450, 'frFR', 'Mon confident, c\’est mon marteau, pas vous.', 'Mon confident, c\’est mon marteau, pas vous.', 28153),
