(145875, 'frFR', '<Laughing sounds>', '', 28153),
(145874, 'frFR', '<Laughing>', '', 28153),
(145873, 'frFR', 'Ils attendent… dans les profondeurs…', 'Ils attendent… dans les profondeurs…', 28153),
(145872, 'frFR', '<Making a raspberry sound--Pfffthblth!>', '', 28153),
(145871, 'frFR', '<Roar of dominance>', '', 28153),
