(145869, 'frFR', '<Sighing sound>', '', 28153),
(145868, 'frFR', '<Train noises--chugga chugga choo choo!>', '', 28153),
(145867, 'frFR', 'Je vous en supplie !', '', 28153),
(145866, 'frFR', 'Ouvrez votre cœur à la pitié.', '', 28153),
(145865, 'frFR', 'Que les esprits m\’épargnent !', '', 28153),
(145864, 'frFR', 'C\’est amplement mérité.', '', 28153),
(145863, 'frFR', 'Les Loas vous ont souri.', '', 28153),
(145862, 'frFR', 'Je suis impressionné.', '', 28153),
(145861, 'frFR', 'Ne fâchez pas les esprits.', '', 28153),
(145860, 'frFR', 'Que Bwonsamdi reste loin de vous.', '', 28153),
(145859, 'frFR', 'Que les Loas veillent sur vous.', '', 28153),
(145858, 'frFR', 'Bonne route.', '', 28153),
(145857, 'frFR', 'Les esprits vous saluent.', '', 28153),
