(145855, 'frFR', 'Les Loas nous entourent.', '', 28153),
(145854, 'frFR', 'Ravi de vous voir.', '', 28153),
(145853, 'frFR', 'Non.', '', 28153),
(145852, 'frFR', 'Dans vos rêves.', '', 28153),
(145851, 'frFR', 'Certainement pas.', '', 28153),
(145850, 'frFR', 'Je vois.', '', 28153),
(145849, 'frFR', 'Entendu.', '', 28153),
(145848, 'frFR', 'Très bien.', '', 28153),
(145847, 'frFR', 'J\’ai besoin de mana.', '', 28153),
(145846, 'frFR', 'Attendez que je récupère du mana.', '', 28153),
(145845, 'frFR', 'J\’apprécie énormément.', '', 28153),
(145844, 'frFR', 'Je vous remercie.', '', 28153),
(145843, 'frFR', 'Je vous serai toujours redevable.', '', 28153),
(145842, 'frFR', 'Gloire aux Loas !', '', 28153),
(145841, 'frFR', 'Je ferai un autel avec vos os !', '', 28153),
(145840, 'frFR', 'Vous schlinguez comme un Troll de sang !', '', 28153),
(145839, 'frFR', 'Je vous en prie.', '', 28153),
