(145276, 'frFR', 'Uuna est engloutie par les ténèbres.', 'Uuna est engloutie par les ténèbres.', 28153),
(145275, 'frFR', '', 'Aaaahhh ! Non ! À l\’aide !', 28153),
(145273, 'frFR', '', 'Une voix tonitruante retentit et vous met sur le qui-vive.', 28153),
