(145266, 'frFR', '', 'Mais… pas tout de suite.', 28153),
(145265, 'frFR', '', 'Je sais qu\’un jour, je devrai retrouver maman et papa.', 28153),
(145264, 'frFR', '', 'Que la forge guide vos pas.', 28153),
(145263, 'frFR', '', 'Vous m\’avez fait voir tellement de choses géniales. Vous êtes vraiment trop super !', 28153),
(145262, 'frFR', '', 'J\’ai plus rien à vous dire.', 28153),
(145261, 'frFR', '', 'Z\’allez PAYER pour ce que vous avez fait !', 28153),
(145260, 'frFR', '', 'Du balai !', 28153),
(145259, 'frFR', '', 'Adieu.', 28153),
(145258, 'frFR', '', 'Merci BEAUCOUP de m\’avoir montré ça, mon $gami:amie; !', 28153),
(145257, 'frFR', '', 'Ils ne sont pas tous morts sur Argus ?', 28153),
(145256, 'frFR', '', 'C\’est mon peuple ! Il a survécu !', 28153),
(145255, 'frFR', '', 'C\’est… tellement beau…', 28153),
(145254, 'frFR', '', 'C\’est vraiment idiot.', 28153),
(145253, 'frFR', '', 'Mais ça bouge comme de l\’eau… C\’est un lac lumineux ?', 28153),
(145252, 'frFR', '', 'Vous voulez quoi ?', 28153),
(145251, 'frFR', 'Je vais retenter ma chance.', 'Je vais retenter ma chance.', 28153),
(145250, 'frFR', 'Faux !\n\nOn réessaie ?', '', 28153),
(145249, 'frFR', 'Un Loa.', 'Un Loa.', 28153),
(145248, 'frFR', 'Un cierge.', 'Un cierge.', 28153),
(145247, 'frFR', '', 'Regardez là-bas. C\’est tout brillant !', 28153),
(145246, 'frFR', '', 'Où sommes-nous ? C\’est quoi toute cette fumée ?', 28153),
(145245, 'frFR', '', 'Alors faites attention, d\’accord ?', 28153),
(145244, 'frFR', 'Un arbre.', 'Un arbre.', 28153),
(145243, 'frFR', '', 'Ne tombez pas, surtout ! Si je tombe, c\’est pas grave, mais vous, vous finiriez comme une crêpe !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'frFR', '', 'Salutations.', 28153),
(145241, 'frFR', '', 'Je ne savais pas que des montagnes pouvaient être aussi hautes !', 28153),
(145240, 'frFR', '', 'Je peux tout voir d\’ici !', 28153),
(145239, 'frFR', '', 'Ravie de vous voir.', 28153),
(145238, 'frFR', '', 'Enchantée.', 28153),
(145237, 'frFR', '', 'Piou piou piou piou !', 28153),
(145236, 'frFR', '', 'Non.', 28153),
(145235, 'frFR', '', 'Nan.', 28153),
(145234, 'frFR', '', 'Pas question.', 28153),
(145233, 'frFR', '', 'Carrément.', 28153),
(145232, 'frFR', '', 'Hmm-hmm.', 28153),
(145231, 'frFR', '', 'Ouais.', 28153),
(145230, 'frFR', '', 'Je vous suis très reconnaissante.', 28153),
(145229, 'frFR', '', 'Je vous remercie.', 28153),
(145228, 'frFR', 'Un Gnome.', 'Un Gnome.', 28153),
(145227, 'frFR', '', 'Je vous dois une fière chandelle.', 28153),
(145226, 'frFR', '', 'Par l\’Enclume noire !', 28153),
(145225, 'frFR', '', 'Genre… au moins DIX !', 28153),
(145224, 'frFR', '', 'C\’est tout ce que vous avez dans le ventre ?', 28153),
(145222, 'frFR', '', 'Je vais vous cogner !', 28153),
(145221, 'frFR', '', 'Je me demande combien d\’oiseaux vivent dans cet arbre. Il doit y en avoir des tas !', 28153),
(145220, 'frFR', 'Première question.\n\nJe suis grand dans ma prime jeunesse, et petit dans mon grand âge. Qui suis-je ?', '', 28153),
(145219, 'frFR', '', 'Tout le plaisir était pour moi.', 28153),
(145218, 'frFR', '', 'Regardez ! On est sous un arbre géant !', 28153),
(145217, 'frFR', '', 'Ravie de rendre service.', 28153),
(145216, 'frFR', '', 'Y a vraiment pas de quoi.', 28153),
(145215, 'frFR', 'Soit, jouons un peu.', 'Soit, jouons un peu.', 28153),
(145214, 'frFR', '$UPrêt:Prête; à faire travailler vos méninges ?', '', 28153),
(145213, 'frFR', '', 'Je peux en avoir un comme mascotte ?', 28153),
(145212, 'frFR', '', 'Mais pour des lézards qui volent.', 28153),
(145211, 'frFR', '', 'C\’est une grande tour. On dirait un… nichoir géant !', 28153),
(145210, 'frFR', '', 'Hé, c\’est quoi ces trucs qui volent ? C\’est trop joli !', 28153),
(145209, 'frFR', '', 'Maintenant que j\’y pense… Est-ce que vous habitez quelque part ?', 28153),
(145208, 'frFR', '', 'Est-ce que vous habitez ici ?', 28153),
(145207, 'frFR', '', 'Comment c\’est possible ?', 28153),
(145206, 'frFR', '', 'Ouah… Une ville volante ! Vraiment ?!', 28153),
(145205, 'frFR', '', 'Vous voulez jouer à la princesse avec moi ?', 28153),
(145204, 'frFR', '', 'Vous savez qui habite ici ? Je parie que c\’est une princesse.', 28153),
(145203, 'frFR', '', 'Ouah ! C\’est la plus jolie maison que j\’aie jamais vue !', 28153),
(145202, 'frFR', '', 'Beurk !', 28153),
(145201, 'frFR', '', 'Des insectes ? Je parie que c\’était des insectes. Beurk ! Je déteste les insectes !', 28153),
(145200, 'frFR', '', 'À votre avis, de quoi il les protégeait ?', 28153),
(145199, 'frFR', '', 'Ouh là là ! C\’est le plus grand mur que j\’aie jamais vu !', 28153),
(145197, 'frFR', '', 'Uuna vous serre dans ses bras.', 28153),
(145196, 'frFR', 'Vous pas prendre botte !', '', 28153),
(145195, 'frFR', '', 'Très bien, mon $gami:amie;, partons d\’ici ! Nous avons tellement d\’endroits à visiter !', 28153),
(145194, 'frFR', '', 'Dites à maman et à papa qu\’ils me manquent et… que je les reverrai bientôt !', 28153),
(145193, 'frFR', '', 'La lumière dit que je peux rester ! You-hou !', 28153),
(145192, 'frFR', '', 'Je peux rester avec mon $gami:amie; ? Juste un petit peu ?', 28153),
(145191, 'frFR', '', 'Il y a tellement de choses que je n\’ai jamais pu faire. Tellement d\’endroits où je ne suis jamais allée…', 28153),
(145190, 'frFR', '', 'Une seconde…', 28153),
(145189, 'frFR', '', 'Maman ! Papa ! Ils m\’attendent !', 28153),
(145188, 'frFR', '', 'La lumière… Elle me demande de la suivre…', 28153),
(145187, 'frFR', '', 'Que… qu\’est-ce qui s\’est passé ?', 28153),
(145186, 'frFR', '', 'Oh, mon $gami:amie; ! On a réussi ! On les a battus !', 28153),
(145185, 'frFR', '', 'Les ombres ont disparu ! Je peux voir !', 28153),
(145184, 'frFR', '', 'C\’que vous avez fait, z\’allez payer pour ça !', 28153),
(145183, 'frFR', 'Soyez $gmaudit:maudite; ! Pour l\’éternité ! Ce n\’était pas mon heure…', '', 28153),
(145182, 'frFR', 'Votre mort fera plaisir à la reine banshee !', '', 28153),
(145181, 'frFR', 'Vermine de l\’Alliance ! J\’apporterai votre tête à la Dame noire !', '', 28153),
(145180, 'frFR', '', 'J\’m\’en vais vous égorger, $n !', 28153),
(145179, 'frFR', 'Des bruits de sabots en approche résonnent dans le lointain.', 'Des bruits de sabots en approche résonnent dans le lointain.', 28153),
(145178, 'frFR', '', 'Vous osez m\’interrompre, vous le paierez de vot\’ vie, $n !', 28153),
(145177, 'frFR', '', 'J\’vous ai à l\’œil depuis un moment, $n.', 28153),
(145176, 'frFR', 'J\’vais vous fumer, comme votre chien de roi ! Pour la Horde !', '', 28153),
(145175, 'frFR', 'Une odeur d\’ozone sature l\’air, qui se met à crépiter.', 'Une odeur d\’ozone sature l\’air, qui se met à crépiter.', 28153),
(145173, 'frFR', '', 'Pas sympa, mais j\’ai plus d\’un tour dans mon sac.', 28153),
(145172, 'frFR', 'Je suis prêt. Commençons le rituel.', 'Je suis prête. Commençons le rituel.', 28153),
(145171, 'frFR', 'J\’entends les pleurs du monde sous mes pieds. Azeroth tremble de douleur ! Il faut trouver un moyen d\’apaiser ses souffrances…', '', 28153),
(145170, 'frFR', '', 'Z\’allez pas me tuer aussi facilement, $n. Subissez mon courroux !', 28153),
(145169, 'frFR', '', 'Vous voilà enfin, $n.', 28153),
(145168, 'frFR', 'Je vais vous briser le crâne !', '', 28153),
(145167, 'frFR', 'J\’arracherai la chair de vos os !', '', 28153),
(145166, 'frFR', 'Je ne quitterai jamais votre tombe.', '', 28153),
(145165, 'frFR', 'Je n\’ai plus la moindre lueur d\’espoir.', '', 28153),
(145164, 'frFR', 'Malédiction… Encore ?', '', 28153),
(145163, 'frFR', 'Vous allez payer pour ce que vous m\’avez fait subir.', '', 28153),
(145162, 'frFR', 'Je vais drainer votre force vitale.', '', 28153),
(145161, 'frFR', 'Je me délecte du fracas des lames et de l\’odeur de la peur.', '', 28153),
(145160, 'frFR', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|tVous êtes la cible de |cFFF00000|Hspell:260953|h[Regard de fer]|h|r.', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|tVous êtes |cFFF00000|Hspell:257459|h[Au crochet]|h|r!', 28153),
(145159, 'frFR', '', 'JE N\’AI PLUS PEUR !', 28153),
(145158, 'frFR', '', 'Ma lumière est super forte !', 28153),
(145157, 'frFR', 'J\’veux rentrer chez moiiiii.', '', 28153),
(145156, 'frFR', '', 'Tant que ma lumière est avec moi, les ténèbres ne peuvent pas gagner !', 28153),
(145155, 'frFR', '', 'Maman m\’a dit que la Lumière me retrouverait toujours ! C\’est vous. Vous êtes ma lumière !', 28153),
(145154, 'frFR', '', '$GM-mon ami:M-mon amie;, vous êtes là ! Vous ne m\’avez pas abandonnée !', 28153),
(145153, 'frFR', 'Non… Non…', 'Non… Non…', 28153),
(145152, 'frFR', 'Dame noire… J\’ai échoué…', 'Dame noire… J\’ai échoué…', 28153),
(145151, 'frFR', 'J\’vais me retrouver tout en bas du totem, mec.', '', 28153),
(145150, 'frFR', 'Enfin…', 'Enfin…', 28153),
(145149, 'frFR', 'Oh… C\’est pas vrai…', 'Oh… C\’est pas vrai…', 28153),
(145148, 'frFR', 'Pour la Dame noire !', 'Pour la Dame noire !', 28153),
(145147, 'frFR', 'Abandonnez tout espoir !', 'Abandonnez tout espoir !', 28153),
(145146, 'frFR', 'Rejoignez-nous dans la mort !', 'Rejoignez-nous dans la mort !', 28153),
(145145, 'frFR', 'Je vais me repaître de vos os !', 'Je vais me repaître de vos os !', 28153),
(145144, 'frFR', 'Mort aux vivants !', 'Mort aux vivants !', 28153),
(145143, 'frFR', 'Pour Sylvanas !', 'Pour Sylvanas !', 28153),
(145142, 'frFR', '', 'Uuna entoure ses épaules de ses bras et se met à pleurer.', 28153),
(145141, 'frFR', '', 'Je… Je ne peux pas ! Je veux juste rentrer chez moi !', 28153),
(145140, 'frFR', '', '$GMon ami:Mon amie; ? Vous êtes toujours là ? J\’ai peur !', 28153),
(145139, 'frFR', 'Le mauvais juju, il vous aura !', '', 28153),
(145137, 'frFR', 'Vos ancêtres, ils vous appellent.', '', 28153),
(145136, 'frFR', 'Que la malédiction de la sale trogne de mon frangin, elle s\’abatte sur vous !', '', 28153),
(145135, 'frFR', 'C\’est quoi, ce vaudou, mec ?', '', 28153),
(145133, 'frFR', 'Que les os, ils tombent là où qu\’ils veulent.', '', 28153),
(145130, 'frFR', 'Les épines veulent s\’emparer de votre âme !', '', 28153),
(145129, 'frFR', 'Il fit demi-tour et disparut dans les bois. Depuis, les courageux et les justes ont toujours joui de la protection du cerf blanc dans la forêt.', 'Il fit demi-tour et disparut dans les bois. Depuis, les courageux et les justes ont toujours joui de la protection du cerf blanc dans la forêt.', 28153),
(145128, 'frFR', '« Mon nom est Athair, je suis le Cœur de cette forêt. Aussi longtemps que je vivrai, je vous protégerai vous et les vôtres », jura le cerf.', '« Mon nom est Athair, je suis le Cœur de cette forêt. Aussi longtemps que je vivrai, je vous protégerai vous et les vôtres », jura le cerf.', 28153),
(145127, 'frFR', '« Par la Lumière ! Vous parlez ! » s\’exclama Arom.', '« Par la Lumière ! Vous parlez ! » s\’exclama Arom.', 28153),
(145126, 'frFR', '', '<Applause sounds>', 28153),
(145125, 'frFR', '', '<Yawning sound>', 28153),
(145124, 'frFR', '', '<Short cheer--Wooooo!>', 28153),
(145123, 'frFR', '', '<Slightly longer cheer--Woohoo!>', 28153),
(145122, 'frFR', 'Les flammes causeront sa perte !', '', 28153),
(145121, 'frFR', '', '<Chicken sounds>', 28153),
(145120, 'frFR', '', '<Crying sounds>', 28153),
(145119, 'frFR', '« Je vous en prie. Je n\’ai fait que vous rendre la pareille. »', '« Je vous en prie. Je n\’ai fait que vous rendre la pareille. »', 28153),
(145118, 'frFR', '', '<Crying sounds, variant>', 28153),
(145117, 'frFR', '', '<Crying sounds, variant.>', 28153),
(145116, 'frFR', '', '<Kiss sound>', 28153),
(145115, 'frFR', '« Merci, mon ami », dit Arom au cerf.', '« Merci, mon ami », dit Arom au cerf.', 28153),
(145114, 'frFR', '', '<Laughing sounds>', 28153),
(145113, 'frFR', '', '<Laughing>', 28153),
(145112, 'frFR', '', '<Making a raspberry sound--Pfffthblth!>', 28153),
(145111, 'frFR', 'Ensemble, le seigneur Arom et le cerf blanc vinrent à bout des guerriers.', 'Ensemble, le seigneur Arom et le cerf blanc vinrent à bout des guerriers.', 28153),
(145110, 'frFR', '', '<Roar of dominance>', 28153),
(145109, 'frFR', '', '<Variant roar>', 28153),
(145108, 'frFR', '', '<Sighing sound>', 28153),
(145107, 'frFR', '', '<Train noises--chugga chugga choo choo!>', 28153),
(145106, 'frFR', 'Le cerf blanc était revenu ! Il chargea les Drust et les piétina !', 'Le cerf blanc était revenu ! Il chargea les Drust et les piétina !', 28153),
(145105, 'frFR', 'C\’est alors qu\’un brame féroce se fit entendre en provenance de la forêt.', 'C\’est alors qu\’un brame féroce se fit entendre en provenance de la forêt.', 28153),
(145104, 'frFR', 'Déterminé à tuer le plus d\’ennemis possible, il tenait bon.', 'Déterminé à tuer le plus d\’ennemis possible, il tenait bon.', 28153),
(145103, 'frFR', 'Le seigneur Arom était seul contre dix guerriers ! Il les affronta vaillamment, mais se retrouva encerclé !', 'Le seigneur Arom était seul contre dix guerriers ! Il les affronta vaillamment, mais se retrouva encerclé !', 28153),
(145102, 'frFR', 'Curieux.', 'Curieux.', 28153),
(145101, 'frFR', 'Au milieu de la nuit, les Drust l\’attaquèrent !', 'Au milieu de la nuit, les Drust l\’attaquèrent !', 28153),
(145100, 'frFR', 'Le cerf rejoignit la forêt et Arom établit son campement.', 'Le cerf rejoignit la forêt et Arom établit son campement.', 28153),
(145099, 'frFR', '« Quiconque réussit à tuer autant de Drust mérite de vivre sur mes terres », pensa-t-il. Le seigneur Arom soigna donc les blessures du cerf.', '« Quiconque réussit à tuer autant de Drust mérite de vivre sur mes terres », pensa-t-il. Le seigneur Arom soigna donc les blessures du cerf.', 28153),
(145098, 'frFR', 'Attention aux épines !', '', 28153),
(145097, 'frFR', 'Cet imposant cerf aurait pu rassasier les sujets affamés du seigneur Arom, mais celui-ci préféra épargner l\’animal.', 'Cet imposant cerf aurait pu rassasier les sujets affamés du seigneur Arom, mais celui-ci préféra épargner l\’animal.', 28153),
(145096, 'frFR', 'Attaquée par les Drust, la bête avait tué plusieurs de ses agresseurs avant de fuir, blessée.', 'Attaquée par les Drust, la bête avait tué plusieurs de ses agresseurs avant de fuir, blessée.', 28153),
(145095, 'frFR', 'Alors qu\’il était parti chasser du gibier dans la forêt, le seigneur Arom croisa un cerf blanc majestueux.', 'Alors qu\’il était parti chasser du gibier dans la forêt, le seigneur Arom croisa un cerf blanc majestueux.', 28153),
(145094, 'frFR', 'Oui ! Libérez-nous !', '', 28153),
(145093, 'frFR', 'Vous nous… avez libérés…', '', 28153),
(145092, 'frFR', 'Enfin… libres…', '', 28153),
(145091, 'frFR', 'Mer… ci…', '', 28153),
(145090, 'frFR', 'L\’un des nôtres.', '', 28153),
(145089, 'frFR', 'Il n\’y a pas d\’échappatoire.', '', 28153),
