INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'frFR', '', 'Je peux pas faire ça ici.', 28153),
(144984, 'frFR', '', 'Je suis obligée de garder ça.', 28153),
(144983, 'frFR', '', 'Cet objet m\’est lié.', 28153),
(144982, 'frFR', '', 'Je ne peux pas m\’en équiper.', 28153),
