(144980, 'frFR', '', 'Je ne peux pas encore utiliser ça.', 28153),
(144979, 'frFR', '', 'Ma compétence est trop basse pour que j\’utilise ça.', 28153),
(144978, 'frFR', '', 'Je ne pourrai jamais utiliser ça.', 28153),
(144977, 'frFR', '', 'Je peux pas apprendre ce sort.', 28153),
(144976, 'frFR', '', 'Je n\’ai pas le droit de prendre ce butin.', 28153),
(144975, 'frFR', '', 'C\’est pas à moi que ça appartient.', 28153),
(144974, 'frFR', '', 'Je dois m\’approcher.', 28153),
(144973, 'frFR', '', 'Je suis trop loin.', 28153),
(144972, 'frFR', '', 'C\’est hors de ma portée.', 28153),
(144971, 'frFR', '', 'Je ne peux pas échanger ça.', 28153),
(144970, 'frFR', '', 'Je ne peux pas m\’en servir.', 28153),
(144969, 'frFR', '', 'Je n\’en suis pas encore équipée.', 28153),
(144968, 'frFR', '', 'Je dois d\’abord m\’en équiper.', 28153),
(144967, 'frFR', '', 'Je dois attendre mon tour pour me servir.', 28153),
(144966, 'frFR', '', 'Je n\’ai pas de cible.', 28153),
(144965, 'frFR', '', 'Sans cible, je ne peux rien faire.', 28153),
(144964, 'frFR', '', 'Il me faut une cible.', 28153),
(144963, 'frFR', '', 'Magie toute-puissante et esprits tourmentés, donnez à mes chardons la force de pousser !', 28153),
(144962, 'frFR', '', 'Donne-moi l\’iris, ma sœur !', 28153),
(144961, 'frFR', '', 'Mes épines vont vous mettre en lambeaux !', 28153),
(144960, 'frFR', '', 'Plus vous luttez, plus vous saignez !', 28153),
(144959, 'frFR', '', 'Vous portez la marque noire !', 28153),
(144958, 'frFR', '', 'Vos crânes feront de beaux ornements.', 28153),
(144956, 'frFR', '', 'Mes racines repousseront…', 28153),
(144955, 'frFR', '', 'J\’aime le bruit des os qui se brisent.', 28153),
(144954, 'frFR', 'Je mangerai à ma faim ce soir. Merci mille fois. Soyez $Ubéni:bénie; !', 'Je mangerai à ma faim ce soir. Merci mille fois. Soyez $Ubéni:bénie; !', 28153),
(144953, 'frFR', 'C\’est un beau geste que vous avez fait là. Merci !', 'C\’est un beau geste que vous avez fait là. Merci !', 28153),
(144952, 'frFR', 'Merci, l\’$Uami:amie;.', 'Merci, l\’$Uami:amie;.', 28153),
(144951, 'frFR', '', 'Des os si souples !', 28153),
(144950, 'frFR', '<Donner dix pièces d\’or.>', '<Donner dix pièces d\’or.>', 28153),
(144949, 'frFR', '<Donner une pièce d\’or.>', '<Donner une pièce d\’or.>', 28153),
(144948, 'frFR', '<Donner cinq pièces de cuivre.>', '<Donner cinq pièces de cuivre.>', 28153),
(144947, 'frFR', 'Z\’auriez pas quelques pièces de cuivre, $gl\’ami:l\’amie; ?', 'Z\’auriez pas quelques pièces de cuivre, $gl\’ami:l\’amie; ?', 28153),
(144946, 'frFR', '', 'Chair putride et cris de désarroi, cette douce musique qui me met en joie !', 28153),
(144945, 'frFR', '', 'Votre destruction est proche !', 28153),
(144944, 'frFR', '', 'Tu as eu ta chance !', 28153),
(144943, 'frFR', '', '... Alors Rezan, il rugit triomphalement face aux cadavres de l\’armée des Trolls de sang !', 28153),
(144942, 'frFR', '', 'Vos affres sont loin d\’être terminées.', 28153),
(144941, 'frFR', '', 'Quelle magnifique agonie !', 28153),
(144940, 'frFR', '', 'Mon corps craque… mais ma malédiction… subsistera…', 28153),
(144939, 'frFR', '', 'Vos cris de douleur résonneront au loin !', 28153),
(144938, 'frFR', '', 'Âme noire, au cœur de la nuit, de tous ceux que tu vois, prends la vie !', 28153),
(144937, 'frFR', '', 'Vous m\’appartenez, maintenant !', 28153),
(144936, 'frFR', '', 'Danse, pantin ! Danse !', 28153),
(144935, 'frFR', '', 'Donne-moi cet iris, imbécile ! Je suis la seule à pouvoir canaliser son pouvoir !', 28153),
(144934, 'frFR', '', 'Vos âmes m\’appartiennent… pour toujours.', 28153),
(144933, 'frFR', '', 'La mort ne me réduira pas au silence…', 28153),
(144932, 'frFR', '', 'Une âme si fragile !', 28153),
(144931, 'frFR', '', 'Vous n\’avez aucun pouvoir ici !', 28153),
(144930, 'frFR', '', '$n, suivez-moi. Tous les autres, rejoignez Rokhan sur le front nord.', 28153),
(144929, 'frFR', 'Visez un peu toutes ces troupes de l\’Alliance ! Ils ont mis le paquet !', '', 28153),
(144928, 'frFR', 'Ils nous envoient des tas de soldats ! Empêchez-les de passer !', '', 28153),
(144926, 'frFR', '', 'Salutations, $c.', 28153),
(144925, 'frFR', '', 'N\’oubliez jamais ce que vouer sa vie à la Lumière signifie.', 28153),
(144924, 'frFR', '', '<Fareeya vous accueille avec un sourire chaleureux.>$B$BVous vous avez affronté les épreuves avec brio, $c. J\’ai le sentiment que votre histoire ne fait que commencer.', 28153),
(144923, 'frFR', 'Si c\’est Maela que vous cherchez, elle donne un coup de main sur le front.$B$BIl y a à Hurlevent de nombreux couturiers très compétents qui peuvent vous apprendre une chose ou deux.', '', 28153),
(144921, 'frFR', '', 'Que la Lumière emporte cette table ! Je ne pourrai peut-être plus jamais utiliser cet atelier.$B$BJ\’ai beau récurer cette table encore et encore, la corruption provenant de ces peaux de bêtes d\’Argus subsiste.', 28153),
(144908, 'frFR', 'Le Vindicaar est prêt pour son prochain voyage.\n\nTout comme moi.', '', 28153),
(144907, 'frFR', 'Merci pour votre aide, $gmon gars:ma belle; ! À charge de revanche !', '', 28153),
(144906, 'frFR', 'Très bien, en route pour l\’auberge, maintenant.', '', 28153),
(144905, 'frFR', 'Ahh, je préfère ça. Une armure digne d\’un véritable héros ! Un de ceux dont les actes légendaires font trembler les fondations mêmes d\’Azeroth !', '', 28153),
(144904, 'frFR', 'Un peu que je vais tout reprendre ! J\’ai obtenu cette armure de façon honnête, même si je n\’ai pas encore fini de la payer.', '', 28153),
(144903, 'frFR', '', 'On dirait que vous avez de la chance aujourd\’hui, M. Front-de-Pierre. Vous pouvez reprendre les marchandises.', 28153),
(144902, 'frFR', 'Enlève tes sales pattes de là, boule de poils !', '', 28153),
(144901, 'frFR', '', 'Oui, madame.', 28153),
(144900, 'frFR', '', 'Partez ! Vous ne nous faites pas peur !', 28153),
(144899, 'frFR', '%s hoche la tête.', '', 28153),
(144898, 'frFR', '', 'Monsieur Chu, veuillez raccompagner ce Nain à la sortie. Madame Xiulan, remettez l\’armure en vente.', 28153),
(144897, 'frFR', 'Je vous ai envoyé l\’argent ce matin, je vous le jure ! Vous ne pouvez pas me laisser en plan comme ça !', '', 28153),
(144896, 'frFR', '', 'Vous avez raté l\’échéance de paiement une fois de trop, M. Front-de-Pierre. Je saisis vos biens, comme convenu dans notre contrat.', 28153),
(144895, 'frFR', '', 'Ils sont là…', 28153),
(144894, 'frFR', '', 'Nous y veillerons. Asseyez-vous.', 28153),
(144893, 'frFR', 'Ils ont surgi des bois. Le combat a éclaté. Maître Ashton s\’est interposé et ils l\’ont capturé. Nous devons le retrouver !', '', 28153),
(144892, 'frFR', '', 'J\’en suis persuadée, Marten. Dites-nous ce qui s\’est passé.', 28153),
(144891, 'frFR', 'J\’ai fait tout ce que j\’ai pu pour les repousser !', '', 28153),
(144889, 'frFR', '', 'Pourquoi avoir ramené le Nain ? Pour prouver votre force ? Faire trembler vos ennemis ?', 28153),
(144888, 'frFR', 'Cela a fonctionné exactement comme je l\’imaginais.', '', 28153),
(144887, 'frFR', '… Oui… C\’est tout à fait ça !', '', 28153),
(144886, 'frFR', 'Ne perdons pas de vue notre objectif. Nous devons trouver l\’Œil avant l\’Alliance.', '', 28153),
(144885, 'frFR', '', 'Dire que les Trolls sont peut-être assis depuis des lustres sur la découverte archéologique du millénaire !', 28153),
(144884, 'frFR', '', 'La bataille a commencé ! Menez-nous à la victoire !', 28153),
(144883, 'frFR', 'Vous avez dit à votre père que vous partiez explorer le monde. Pas que vous alliez négocier avec ces chiens de la Horde.', '', 28153),
(144882, 'frFR', 'Princesse.', '', 28153),
(144881, 'frFR', 'Pressons, votre père nous attend.', '', 28153),
(144880, 'frFR', '', 'Princesse... permettez-moi d\’être la première à vous accueillir...', 28153),
(144879, 'frFR', '', 'Mon père est un peu rigide, mais aussi très perspicace. Je suis prête à parier qu\’il est déjà au courant de votre implication dans ma libération de Hurlevent.', 28153),
(144878, 'frFR', '', 'Ce n\’est pas à vous d\’en décider, général.', 28153),
(144877, 'frFR', 'Le meilleur moyen de protéger le royaume serait de débarrasser Vol\’dun de cette… chose. La Horde n\’a pas sa place en Zandalar.', '', 28153),
(144876, 'frFR', '', 'Vous avez juré de protéger ce royaume. Puisque vous manquez à votre devoir, je suis bien obligée de trouver quelqu\’un qui s\’en charge.', 28153),
(144875, 'frFR', '<Toucher la larme.>', '<Toucher la larme.>', 28153),
(144874, 'frFR', '', 'Général.', 28153),
(144873, 'frFR', '<Une larme de dragon vert, cachée dans l\’ombre par des forces inconnues.>', '', 28153),
(144872, 'frFR', '', 'Pendant ce temps, les intrigants et les vieillards séniles du conseil zanchuli, ils minimisent cette menace. Ils ont convaincu mon père de ne rien faire.', 28153),
(144871, 'frFR', '', 'Les Trolls de sang traversent notre frontière nord et emportent les nôtres dans les marais de Nazmir, d\’où ils ne reviennent jamais.', 28153),
(144870, 'frFR', '', 'Zandalar pullule d\’ennemis, autant à l\’extérieur qu\’en son sein. C\’est pour ça que j\’ai fait appel à la Horde… et à vous.', 28153),
(144869, 'frFR', '', 'Nous avons peu de temps, $n. Vous devez absolument savoir certaines choses sur mon royaume.', 28153),
(144868, 'frFR', '', 'Venez, allons rendre une petite visite à mon père. Zul… nous parlerons plus tard.', 28153),
(144867, 'frFR', '', 'Tze\’na ! Salut, toi. Je t\’ai manqué ?', 28153),
(144866, 'frFR', '', 'J\’ai entendu les pleurs de l\’enfant dont vous parlez.\n\nJe vais vous marquer, pour que vous puissiez vous rendre dans ce royaume pour la chercher.\n\nElle se trouve à l\’endroit où la barrière entre le royaume de la vie et de la mort est la plus mince, et où elle déborde dans votre monde.\n\nMais faites attention, vous n\’avez aucun pouvoir dans ce lieu, les mortels ne peuvent pas blesser ses habitants.\n\nVous aurez beau essayer, vous ne pourrez peut-être pas aider votre amie.', 28153),
(144864, 'frFR', 'Que la Lumière soit avec vous.', 'Que la Lumière soit avec vous.', 28153),
(144863, 'frFR', 'Je cherche une petite fille du nom d\’Uuna, est-ce que vous l\’avez vue ?', 'Je cherche une petite fille du nom d\’Uuna, est-ce que vous l\’avez vue ?', 28153),
(144862, 'frFR', '', 'T\’laartos nous a montré comment jouer à Rocher, parchemin, lame mais j\’ai oublié les règles.', 28153),
(144860, 'frFR', 'La porte de l\’Alliance a été détruite !', '', 28153),
(144859, 'frFR', '', 'Griffons ! À l\’attaque !', 28153),
(144853, 'frFR', 'Nos guerriers les plus courageux sont souvent à l\’avant-garde. Le moins que je puisse faire est de protéger leurs familles jusqu\’à leur retour.', 'Nos guerriers les plus courageux sont souvent à l\’avant-garde. Le moins que je puisse faire est de protéger leurs familles jusqu\’à leur retour.', 28153),
(144852, 'frFR', 'Vous osez pénétrer dans mes tunnels ? Quelle erreur !', '', 28153),
(144851, 'frFR', '', 'Sa queue est toute douce !', 28153),
(144850, 'frFR', '', 'Je peux le garder ?', 28153),
(144849, 'frFR', '', 'Non ! Reste et raconte-nous encore des histoires d\’aventure, T\’laartos !', 28153),
(144848, 'frFR', '', 'Il est de retour !', 28153),
(144847, 'frFR', '', ' C\’est T\’laartos !', 28153),
(144846, 'frFR', 'Ne vous inquiétez pas, T\’laartos reviendra bientôt avec de nouvelles histoires et peut-être un autre copain.', '', 28153),
(144845, 'frFR', 'T\’laartos doit ramener ce petit, maintenant. Dites au revoir, les enfants.', '', 28153),
(144842, 'frFR', '', 'Ahh !', 28153),
(144841, 'frFR', 'Racontez-moi ce qui s\’est passé lors du festin.', 'Racontez-moi ce qui s\’est passé lors du festin.', 28153),
(144840, 'frFR', 'La Dame noire a une tâche importante à vous confier, $c. J\’espère que vous êtes $gprêt:prête;…', '', 28153),
(144839, 'frFR', '', 'T\’laartos !', 28153),
(144838, 'frFR', '', 'Promettez-moi que vous ne m\’abandonnerez pas, mon $gami:amie;. Même quand il fera tout sombre…', 28153),
(144837, 'frFR', '', 'Mais maintenant, vous êtes là. Ensemble, on peut les combattre ! Je crois…', 28153),
(144836, 'frFR', '', 'Je n\’arrête pas de courir… mais ils me retrouvent toujours.', 28153),
(144835, 'frFR', '', 'Ils seront bientôt là, mon $gami:amie;.', 28153),
(144834, 'frFR', '', 'Vous voilà ! Je préfère ça.', 28153),
(144833, 'frFR', 'Ha ha ! T\’laartos est content de voir que vous allez bien ! T\’laartos a aussi apporté un cadeau, qu\’il a trouvé en Val\’sharah.', '', 28153),
(144832, 'frFR', 'C\’est une PLAISANTERIE ?!', '', 28153),
(144831, 'frFR', 'Ces globes semblent contenir une sorte de pouvoir. Peut-être qu\’en ôtant la paroi externe…', '', 28153),
(144830, 'frFR', 'Bah !', '', 28153),
(144829, 'frFR', 'Ces yeux m\’ont l\’air de première fraîcheur. Je vais vite en extraire quelques gouttes d\’humeur...', '', 28153),
(144828, 'frFR', '', 'J\’ai si froid et il fait tellement sombre ici. Je ne sais pas quoi faire !', 28153),
(144827, 'frFR', '', 'Je n\’abandonnerai pas ! Je vous le promets !', 28153),
(144826, 'frFR', '', 'Est-ce que c\’est vous ?', 28153),
(144825, 'frFR', 'Nos agents ont déjà infiltré l\’exploitation minière gobeline souterraine. Nous saurons bientôt ce qu\’ils préparent…', '', 28153),
(144824, 'frFR', 'J\’aurais dû... creuser... plus profond...', 'J\’aurais dû... creuser... plus profond...', 28153),
(144823, 'frFR', '$gUn:Une; Elfe... qui creuse... ha !', '$gUn:Une; Elfe... qui creuse... ha !', 28153),
(144822, 'frFR', 'Trop tard. On a trouvé...', 'Trop tard. On a trouvé...', 28153),
(144821, 'frFR', 'Qui trouve, garde...', 'Qui trouve, garde...', 28153),
(144820, 'frFR', 'Vous trouverez jamais c\’que vous cherchez...', 'Vous trouverez jamais c\’que vous cherchez...', 28153),
(144819, 'frFR', 'Votre expédition est finie. Il est temps de mourir !', 'Votre expédition est finie. Il est temps de mourir !', 28153),
(144818, 'frFR', 'J\’vais me faire une joie de vous enterrer.', 'J\’vais me faire une joie de vous enterrer.', 28153),
(144817, 'frFR', 'On va saper le sol sous vos pieds !', 'On va saper le sol sous vos pieds !', 28153),
(144816, 'frFR', 'Vous pensiez pouvoir vous mesurer aux Sombrefer ? Grave erreur.', 'Vous pensiez pouvoir vous mesurer aux Sombrefer ? Grave erreur.', 28153),
(144815, 'frFR', 'Ces ruines appartiennent aux Sombrefer, sale Elfe !', 'Ces ruines appartiennent aux Sombrefer, sale Elfe !', 28153),
(144812, 'frFR', '', 'Des renforts ennemis arrivent !', 28153),
(144811, 'frFR', 'Les relevés sont formels ! Nous devons aller vers l\’ouest !', '', 28153),
(144810, 'frFR', '', 'Le ravin est à nous ! Regroupons-nous, il faut planifier la suite de notre attaque.', 28153),
(144809, 'frFR', '', 'C\’est comme essayer de faire entrer un totem carré dans un support pour totems ronds. Le vaudou, il comprend les humeurs.', 28153),
(144808, 'frFR', 'Ils ont jailli de l\’ombre d\’un seul coup ! Ils sont partout !', 'Ils ont jailli de l\’ombre d\’un seul coup ! Ils sont partout !', 28153),
(144807, 'frFR', '', 'C\’est une qualité remarquable, je l\’apprécie pour ça.', 28153),
(144806, 'frFR', '', 'Oh oui, comme hier, avant-hier, et le jour d\’avant !', 28153),
(144805, 'frFR', 'Les tunnels sont sécurisés. Ouvrez la porte !', '', 28153),
(144804, 'frFR', 'Il est de bonne humeur aujourd\’hui, non ?', '', 28153),
(144803, 'frFR', '', 'L\’ennemi approche ! Bwonsalaka !', 28153),
(144802, 'frFR', 'Je vais retrouver les autres. Nous devons arrêter tout ceci tant que nous le pouvons.', '', 28153),
(144801, 'frFR', 'Merci, $p. Je crains que la situation ne soit bien pire que prévu.', '', 28153),
(144800, 'frFR', 'Dites-moi ce qui s\’est passé au Repos du lion.', 'Dites-moi ce qui s\’est passé au Repos du lion.', 28153),
(144799, 'frFR', 'Mes agents ont sécurisé cette zone. Cela dit, il est toujours plus prudent de parler à voix basse…', '', 28153),
(144798, 'frFR', 'Bwon\’chaga di chuka !', 'Bwon\’chaga di chuka !', 28153),
(144796, 'frFR', '', 'Le vaudou, il touche tous les cœurs, Cala, qu\’ils croient en lui ou non.', 28153),
(144795, 'frFR', '', 'Le vaudou vous permet de lire dans les pensées des dinosaures ? Vraiment ?!', 28153),
(144794, 'frFR', '', 'C\’est parce que c\’est l\’amour, Cala. Le vaudou, ça vient du cœur, pas du cerveau, même pour vous c\’est pareil.', 28153),
(144792, 'frFR', 'Désormais, vous m\’appartenez !', 'Désormais, vous m\’appartenez !', 28153),
(144791, 'frFR', 'La vérité émane des vapeurs !', 'La vérité émane des vapeurs !', 28153),
(144790, 'frFR', 'Inspirez profondément !', 'Inspirez profondément !', 28153),
(144789, 'frFR', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[ranime]|h|r tous les tas d\’os restants !', '||TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|tRezan |cFFFF0000|Hspell:260683|h[ranime]|h|r tous les tas d\’os restants !', 28153),
(144788, 'frFR', '', 'G\’huun…', 28153),
(144787, 'frFR', '', 'Non… Pas comme ça…', 28153),
(144786, 'frFR', '', 'Mes sœurs… elles me… vengeront…', 28153),
(144785, 'frFR', '', 'Gachaga !', 28153),
(144784, 'frFR', '', 'Zuldazar… tombera…', 28153),
(144783, 'frFR', '', 'Ma maîtresse… me vengera…', 28153),
(144782, 'frFR', '', 'Mais la plus forte, ça devait être moi…', 28153),
(144781, 'frFR', '', 'Pohkiza…', 28153),
(144780, 'frFR', 'Eh bien, c\’est parfait.', '', 28153),
(144779, 'frFR', 'Beau travail avec ces potions, $n. À présent, j\’ajoute quelques gouttes de chaque et…', '', 28153),
(144778, 'frFR', '', 'Ça va être facile !', 28153),
(144777, 'frFR', '', 'Ça va être vite réglé !', 28153),
(144776, 'frFR', '', 'Hah ! C\’est bien trop facile !', 28153),
(144775, 'frFR', '', 'Un nouveau crâne pour ma collection !', 28153),
(144774, 'frFR', '', 'C\’est chez nous, ici !', 28153),
(144773, 'frFR', 'Entrez donc ! Par ici ! Nous avons du pain sur la planche !', '', 28153),
(144772, 'frFR', 'Ça fait du bien de se reposer de temps en temps.$B$BEn particulier après des affaires fructueuses !', '', 28153),
(144771, 'frFR', 'Éteignez ces flammes. Moi, je vais préparer le laboratoire ! Oh là là, je sens qu\’on va s\’amuser !', '', 28153),
(144770, 'frFR', 'Je n\’ai plus de matériaux pour le moment. Toutes mes excuses.', '', 28153),
(144769, 'frFR', 'Je vous apporte des globes, Elric.', 'Je vous apporte des globes, Elric.', 28153),
(144768, 'frFR', 'Tenez, ces herbes sont pour vous.', 'Tenez, ces herbes sont pour vous.', 28153),
(144767, 'frFR', 'Voici les yeux que vous avez demandés.', 'Voici les yeux que vous avez demandés.', 28153),
(144766, 'frFR', 'Voici les potions dont vous aviez besoin.', 'Voici les potions dont vous aviez besoin.', 28153),
(144765, 'frFR', 'Ah, $gun confrère:une consœur; alchimiste ! J\’ai ici quelques nouvelles recettes susceptibles de vous intéresser.$b$bMa spécialité, c\’est les potions, mais je m\’adonne aussi à la transmutation de temps à autre.', '', 28153),
(144764, 'frFR', 'Bienvenue dans mon échoppe, $c ! Que diriez-vous d\’un petit rafraîchissement ? À moins que vous ayez envie d\’autre chose ?$b$bLes potions sont ma spécialité, mais je m\’adonne aussi à la transmutation de temps à autre.', '', 28153),
(144763, 'frFR', '', 'De la viande fraîche !', 28153),
(144762, 'frFR', '', 'Ces oreilles, je vais les ajouter à mon collier !', 28153),
(144761, 'frFR', '', 'Du sang pour G\’huun !', 28153),
(144760, 'frFR', 'Chut, ne bougez plus ! Sa vision est basée sur le mouvement.', 'Chut, ne bougez plus ! Sa vision est basée sur le mouvement.', 28153),
(144759, 'frFR', 'Que la Lumière me protège… Il est de retour.', 'Que la Lumière me protège… Il est de retour.', 28153),
(144758, 'frFR', 'Le redresseur de torts sancteforge grogne.', 'La redresseuse de torts sancteforge grogne.', 28153),
(144757, 'frFR', 'Je pensais avoir perdu l\’esprit.', 'Je pensais avoir perdu l\’esprit.', 28153),
(144756, 'frFR', 'Que la Terre-Mère vous bénisse !', 'Que la Terre-Mère vous bénisse !', 28153),
(144755, 'frFR', 'C\’était horrible, $R.', 'C\’était horrible, $R.', 28153),
(144754, 'frFR', 'Je dois… Mon esprit… Il faut que je parte d\’ici !', 'Je dois… Mon esprit… Il faut que je parte d\’ici !', 28153),
(144753, 'frFR', 'Ces murmures… me rendaient fou !', 'Ces murmures… me rendaient folle !', 28153),
(144752, 'frFR', 'Merci, $gchampion:championne;.', 'Merci, $gchampion:championne;.', 28153),
(144751, 'frFR', '', 'Même la meilleure arme s\’use quand elle est utilisée trop souvent. Prenez le temps de bien vous reposer, T\’laartos.', 28153),
(144750, 'frFR', 'T\’laartos est reconnaissant envers Lysara. T\’laartos sent qu\’il est prêt à retourner au combat !', '', 28153),
(144749, 'frFR', 'Pas assez pour arrêter T\’laartos !', '', 28153),
(144748, 'frFR', 'Tenez, mon amulette à effigie, z\’avez qu\’à la prendre. C\’est ce que j\’ai de mieux en stock, je vous le dis.', '', 28153),
(144747, 'frFR', 'Ça, c\’est une belle copie ou je m\’y connais pas ! Qui c\’est qui vous l\’a donnée ? Me dites pas son nom ! Envoyez-le-moi.', '', 28153),
(144746, 'frFR', 'Allez dire à personne où vous avez eu ça, sinon vous allez voir pourquoi qu\’on m\’a donné ce surnom.', '', 28153),
(144745, 'frFR', '', 'Encore, T\’laartos ? Combien de fois il faudra…', 28153),
(144744, 'frFR', 'C\’est pas n\’importe quelle Elfe de la nuit, je vous signale... C\’était une tête couronnée, dans le temps !', '', 28153),
(144743, 'frFR', 'Seul le temps nous le dira. Prenez bien soin de cette fleur centenaire, $p. Elles ne fleurissent qu\’une fois par siècle.', '', 28153),
(144742, 'frFR', '', 'Des graines dorées ! Faut les semer immédiatement pour le roi. C\’est quoi comme plante, Jahden ?', 28153),
(144741, 'frFR', 'Ce piment, il sera parfait pour mon prochain chili extra fort... Et puis ces graines dorées, beurk !', '', 28153),
(144740, 'frFR', '', 'L\’ordre existe bel et bien. Lucille Malvoie est déterminée à reprendre nos terres et à libérer nos habitants.', 28153),
(144739, 'frFR', 'Si elle y parvient, elle aura mon soutien inconditionnel.', '', 28153),
(144738, 'frFR', 'Ah bon ? Je croyais qu\’il s\’agissait d\’une simple légende !', '', 28153),
(144737, 'frFR', '', 'Je suis désormais inquisitrice, cher maire. Lucille Malvoie a réformé l\’ordre des Braises afin de combattre ces sorcières.', 28153),
(144736, 'frFR', 'Mes concitoyens et moi-même vous remercions pour votre intervention opportune, lieutenant.', '', 28153),
(144735, 'frFR', '', 'Merci, $p ! Notre stock de pierres de foyer était au plus bas. Prenez donc un piment, c\’est la maison qui régale.', 28153),
(144734, 'frFR', 'Un petit extra, ça vous dit, $p ? Trouvez un acheteur à qui fourguer ces pierres de foyer. Troquez-les contre quelque chose qu\’ait de la valeur, et je vous revaudrai ça.', '', 28153),
(144733, 'frFR', 'Vous savez ce que ça veut dire… Du bois gratuit !', '', 28153),
(144732, 'frFR', 'Hé, euh… chef ? On m\’a signalé qu\’un énorme monstre qui ressemble à un arbre se balade dans les bois.', '', 28153),
(144731, 'frFR', 'Crôa ! Saleté de rebut de Trogg ! Crôa !', '', 28153),
(144730, 'frFR', 'Marins d\’eau douce à foie jaune ! CRÔA !', '', 28153),
(144729, 'frFR', 'CRÔA !', '', 28153),
(144728, 'frFR', 'Pst, $p ! Z\’avez déjà eu envie de filer un bon coup de poing dans la tronche de quelqu\’un en sachant que c\’était pas possible ? Eh ben, la solution, je l\’ai ici !', '', 28153),
(144727, 'frFR', 'Amulettes exceptionnelles ! Bibelots incroyables ! Offres spéciales uniquement pour les plus intelligents !', '', 28153),
(144726, 'frFR', 'Écoutez les murmures. Ils sont si doux.', 'Écoutez les murmures. Ils sont si doux.', 28153),
(144725, 'frFR', 'Les ténèbres vous dévoreront.', 'Les ténèbres vous dévoreront.', 28153),
(144724, 'frFR', 'Les bénédictions et les cris, c\’est dépassé ! Y a que l\’azérite pour vous donner la force d\’affronter les dangers du monde moderne ! Buvez de l\’azérite en bouteille !', '', 28153),
(144723, 'frFR', 'Votre mort est nécessaire.', 'Votre mort est nécessaire.', 28153),
(144722, 'frFR', 'FAITES QUE ÇA CESSE !', 'FAITES QUE ÇA CESSE !', 28153),
(144721, 'frFR', 'Les Ténèbres approchent…', 'Les Ténèbres approchent…', 28153),
(144720, 'frFR', 'Si Vol\’jin, il avait eu ce totem d\’invulnérabilité au rivage Brisé, il s\’rait encore là aujourd\’hui. Surtout, faites pas la même erreur !', '', 28153),
(144719, 'frFR', 'Espionnez vos ennemis, gardez un œil sur vos amis ou zyeutez dans les quartiers royaux... tout ça grâce à cet incroyable totem aux feux follets murmurants !', '', 28153),
(144718, 'frFR', 'La flamme de ce totem brûle depuis que le roi Rastakhan est monté sur le trône. Ça vous dirait pas de vous offrir ce fragment d\’histoire des Zandalari ?', '', 28153),
(144717, 'frFR', 'Chez Eskrokar, on fait des réducs à ceux qui posent pas de questions !', '', 28153),
(144716, 'frFR', 'T\’laartos est là !', '', 28153),
(144715, 'frFR', '', 'Je me sens beaucoup mieux.', 28153),
(144714, 'frFR', 'T\’LAARTOS !', '', 28153),
(144713, 'frFR', '', 'Personne peut battre les ténèbres sans couronne. C\’est comme ça !', 28153),
(144712, 'frFR', '', 'Elle tire des étoiles ! Les méchants détestent ça.', 28153),
(144711, 'frFR', 'Les miens se chargent de garder et d\’amasser le savoir.\n\nJ\’ai pour devoir de veiller à ce que nos découvertes soient archivées correctement.', '', 28153),
(144706, 'frFR', 'De nombreux préparatifs m\’attendent. Occupe-toi d\’eux.', 'De nombreux préparatifs m\’attendent. Occupe-toi d\’eux.', 28153),
(144705, 'frFR', 'Cette discussion stérile m\’ennuie.', 'Cette discussion stérile m\’ennuie.', 28153),
(144704, 'frFR', 'Ces voix ne sont que tromperies !', '', 28153),
(144703, 'frFR', 'Ne sentez-vous pas la puissance qui émane des profondeurs ? Par sa volonté, nous retrouverons notre plénitude !', 'Ne sentez-vous pas la puissance qui émane des profondeurs ? Par sa volonté, nous retrouverons notre plénitude !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'frFR', 'Nous avions juré de protéger Brennadam et notre peuple ! Qu\’avez-vous fait de nos serments ?', '', 28153),
(144701, 'frFR', 'Vous avez toujours été trop faible pour servir le seigneur Chantorage. Vous n\’êtes bon qu\’à vous morfondre à Brennadam comme un idiot.', 'Vous avez toujours été trop faible pour servir le seigneur Chantorage. Vous n\’êtes bon qu\’à vous morfondre à Brennadam comme un idiot.', 28153),
(144700, 'frFR', 'C\’est vous qui êtes perdu !', '', 28153),
(144699, 'frFR', 'Que les flots… vous engloutissent…', '', 28153),
(144698, 'frFR', 'Ma vie… pour… Azshara !', '', 28153),
(144697, 'frFR', 'Que les abysses vous emportent…', '', 28153),
(144696, 'frFR', 'Ma reine… J\’ai… j\’ai échoué…', '', 28153),
(144695, 'frFR', 'La marée… se retire…', '', 28153),
(144694, 'frFR', '', 'La marée… se retire…', 28153),
(144693, 'frFR', '', 'Ma reine… J\’ai… j\’ai échoué…', 28153),
(144692, 'frFR', '', 'Que les abysses vous emportent…', 28153),
(144691, 'frFR', '', 'Ma vie pour Azshara !', 28153),
(144690, 'frFR', '', 'Que les flots… vous engloutissent…', 28153),
(144689, 'frFR', 'J\’ai une autre question…', 'J\’ai une autre question…', 28153),
(144688, 'frFR', 'J\’ai l\’impression que vous avez besoin d\’un ami.', 'J\’ai l\’impression que vous avez besoin d\’une amie.', 28153),
(144687, 'frFR', 'Que faites-vous ?', 'Que faites-vous ?', 28153),
(144686, 'frFR', 'Je suis là pour vous aider, Kugro !', 'Je suis là pour vous aider, Kugro !', 28153),
(144685, 'frFR', 'Pouvez-vous jeter un coup d\’œil à ce parchemin ?', 'Pouvez-vous jeter un coup d\’œil à ce parchemin ?', 28153),
(144684, 'frFR', 'Gardez votre salive, $gmon jeune ami:ma jeune amie;.\n\nQuelle que soit la raison de votre présence ici, je n\’ai pas de temps à vous consacrer.', '', 28153),
(144683, 'frFR', '$GD\’un ami:D\’une amie; ? Non, mais $gd\’un assistant:d\’une assistante;, oui.', '', 28153),
(144682, 'frFR', 'Laissez-moi plutôt vous dire ce que je ne fais pas : perdre mon temps à bavarder avec $gun:une:r; $r alors que mon travail m\’attend.', '', 28153),
(144681, 'frFR', 'Dans ce cas, j\’espère que vous savez faire plusieurs choses en même temps.', '', 28153),
(144680, 'frFR', 'J\’ai trop de retard dans mon travail pour en accepter davantage. Ces parchemins ne s\’écrivent pas tout seuls, vous savez.', '', 28153),
(144679, 'frFR', 'Je suis dans le rouge.', '', 28153),
(144678, 'frFR', '', '<Arluelle a le regard lointain.>$B$BSi seulement mon frère pouvait voir la ville aujourd\’hui…', 28153),
(144677, 'frFR', '', 'J\’ai le sentiment que notre ville sera bientôt sollicitée. Je serai prête le moment venu.', 28153),
(144676, 'frFR', 'Il est regrettable que les Sancteforge n\’aient pas rallié notre cause. Leurs prouesses martiales sont impressionnantes.', '', 28153),
(144675, 'frFR', 'À combien j\’en étais, déjà ? Argh !', '', 28153),
(144674, 'frFR', 'Que la Garde crépusculaire puisse compter Victoire dans ses rangs à nouveau est une bonne chose.', '', 28153),
(144673, 'frFR', '', 'Allons-y.', 28153),
(144672, 'frFR', 'Je suis heureux de voir qu\’Arluelle continue l\’entraînement, elle m\’a l\’air déjà bien plus forte.$B$BPeut-être devrais-je mesurer ses progrès.', '', 28153),
(144671, 'frFR', 'Les marées sont en train de tourner, mon frère. Si vous n\’êtes pas avec nous, vous êtes perdu.', 'Les marées sont en train de tourner, mon frère. Si vous n\’êtes pas avec nous, vous êtes perdu.', 28153),
(144670, 'frFR', 'Un pour vous, et un pour moi.', '', 28153),
(144669, 'frFR', 'J\’adore trafiquer les chiffres !', '', 28153),
(144668, 'frFR', 'Reid ! La flotte doit être restituée à Kul Tiras sans délai !', '', 28153),
(144667, 'frFR', 'J\’ai déjà compté cette pile-là ou pas ?', '', 28153),
(144666, 'frFR', 'Un... Deux... Sept... Rouge... Deux...', '', 28153),
(144665, 'frFR', '', 'Au fait, j\’ai un don pour faire sauter des trucs… et devinez qui se hissera bientôt au rang de cible prioritaire !', 28153),
(144664, 'frFR', '', 'Continuez comme ça et il va y avoir un petit « accident ».', 28153),
(144663, 'frFR', '', 'Grr ! Ça va vous coûter bonbon !', 28153),
(144662, 'frFR', '', 'À plus, terreur.', 28153),
(144661, 'frFR', '', 'Hein ? Vous aviez fini ?', 28153),
(144660, 'frFR', '', 'À la revoyure !', 28153),
(144659, 'frFR', '', 'Il vous faut quelque chose ?', 28153),
(144658, 'frFR', '', 'Z\’avez attaché votre ceinture ?', 28153),
(144657, 'frFR', '', 'Salut, ça boume ?', 28153),
(144656, 'frFR', 'Qu\’ai-je donc fait pour mériter ÇA ? Dites-le-MOI !', '', 28153),
(144655, 'frFR', 'Sérieusement ? Vous comptez faire ça encore longtemps ? Clic, clic, clic, clic…', '', 28153),
(144654, 'frFR', 'Vous n\’avez vraiment rien de mieux à faire ? Allez donc embrasser des Murlocs ! Ça vous occupera.', '', 28153),
(144653, 'frFR', 'Pincez-moi, je rêve ! Le respect, ça vous parle ?', '', 28153),
(144652, 'frFR', 'C\’est ça, on vous écrira…', '', 28153),
(144651, 'frFR', 'C\’est ça, circulez…', '', 28153),
(144650, 'frFR', 'À plus !', '', 28153),
(144649, 'frFR', 'Je suis chargé à balles de guerre !', '', 28153),
(144648, 'frFR', 'Prêt à décarrer !', '', 28153),
(144647, 'frFR', 'Allez-y, continuez à cliquer si vous voulez perdre un doigt.', '', 28153),
(144646, 'frFR', '<Soupirs> Et moi qui passais une si belle journée…', '', 28153),
(144645, 'frFR', 'Salut, je m\’appelle Rustine, mais vous pouvez m\’appeler « chef ».', '', 28153),
(144644, 'frFR', 'Mieux vaut trop que pas assez !', '', 28153),
(144643, 'frFR', 'J\’adore quand un plan se déroule sans accroc.', '', 28153),
(144642, 'frFR', 'À plus.', '', 28153),
(144641, 'frFR', 'C\’est quoi, le plan ?', '', 28153),
(144640, 'frFR', 'Salut, quoi de neuf ?', '', 28153),
(144639, 'frFR', 'Yo !', '', 28153),
(144638, 'frFR', 'C\’est me cliquer dessus qui vous branche ? Vous croyez que ça fait de vous quelqu\’un de spécial ?', '', 28153),
(144637, 'frFR', 'Ces crânes, vous voulez que je vous montre comment je les ai eus, c\’est ça ?', '', 28153),
(144636, 'frFR', 'Faites voir votre tête. Hum… Elle irait bien dans ma collection.', '', 28153),
(144635, 'frFR', 'J\’ai perdu ma tête ! Elle est comme ça… à peu près. Si vous la retrouvez, je vous donnerai une récompense.', '', 28153),
(144634, 'frFR', 'Revenez me voir si vous avez besoin d\’aide.', '', 28153),
(144633, 'frFR', 'Restez à l\’écart du vaudou.', '', 28153),
(144632, 'frFR', 'Surveillez vos arrières.', '', 28153),
(144631, 'frFR', 'Qu\’est-ce que vous avez à me dire ?', '', 28153),
(144630, 'frFR', 'Pour les Sombrelances !', '', 28153),
(144629, 'frFR', 'Je vous écoute.', '', 28153),
(144628, 'frFR', 'Très bien… vous l\’aurez cherché. Réorigination de l\’univers tout entier initiée.', '', 28153),
(144627, 'frFR', 'Des sollicitations continuelles n\’amélioreront pas les performances du système.', '', 28153),
(144626, 'frFR', 'Cible potentielle de confinement détectée.', '', 28153),
(144625, 'frFR', 'Erreur. Veuillez ne pas recommencer.', '', 28153),
(144624, 'frFR', 'Interaction terminée.', '', 28153),
(144623, 'frFR', 'Reprise du protocole de confinement.', '', 28153),
(144622, 'frFR', 'Réitération des analyses.', '', 28153),
(144621, 'frFR', '', 'Salutations, $p ! De nouvelles contrées et rencontres nous attendent sur Azeroth.$B$BOculeth a préparé des portails en bas qui n\’attendent plus que vous.', 28153),
(144620, 'frFR', 'Corruption détectée. Confinement impératif.', '', 28153),
(144619, 'frFR', 'Protocole prioritaire : confiner la corruption.', '', 28153),
(144618, 'frFR', 'Unité Herzel connectée. Fonction : confinement de la corruption.', '', 28153),
(144617, 'frFR', '', 'J\’en ai plein le dos… et je ne dis pas ça parce que je porte une carapace.', 28153),
(144616, 'frFR', '', 'Vous connaissez l\’histoire de la Tortollane excédée qui agresse violemment celui qui la dérange ?', 28153),
(144614, 'frFR', '', 'Vous me donnez envie de cogner.', 28153),
(144613, 'frFR', '', 'C\’est bon, vous avez fini ?', 28153),
(144612, 'frFR', '', 'La prochaine fois, dérangez quelqu\’un d\’autre.', 28153),
(144611, 'frFR', '', 'Vous en mettez du temps, à partir.', 28153),
(144610, 'frFR', '', 'Rhah. Quoi encore ?', 28153),
(144609, 'frFR', '', 'Vous avez vraiment besoin de me parler ?', 28153),
(144608, 'frFR', '', 'Qu\’est-ce que vous voulez ?', 28153),
(144605, 'frFR', 'Circulez… avant que j\’utilise votre âme pour payer ma dette !', '', 28153),
(144604, 'frFR', 'Un conseil d\’ami : faites jamais de marché avec un loa mort !', '', 28153),
(144603, 'frFR', 'Votre âme, ne la perdez pas.', '', 28153),
(144602, 'frFR', 'Restez sur vos gardes.', '', 28153),
(144601, 'frFR', 'Faites gaffe à vous.', '', 28153),
(144600, 'frFR', 'Salutations.', '', 28153),
(144599, 'frFR', 'Vous lui voulez quoi, à Hanzabu ?', '', 28153),
(144598, 'frFR', 'J\’ai beaucoup à faire.', '', 28153),
(144597, 'frFR', 'Vous connaissez la fable du bœuf qui voulait se faire aussi gros que moi ?', '', 28153),
(144596, 'frFR', 'J\’en ai assez de vos coassements.', '', 28153),
(144595, 'frFR', 'Je peux vous sauter au cou ?', '', 28153),
(144594, 'frFR', 'Vous n\’êtes pas ici pour m\’embrasser, j\’espère !', '', 28153),
(144593, 'frFR', 'À la prochaine fois.', '', 28153),
(144592, 'frFR', 'Réfléchissez avant de sauter.', '', 28153),
(144591, 'frFR', 'Puissiez-vous toujours attraper de grosses mouches.', '', 28153),
(144590, 'frFR', 'Parlez.', '', 28153),
(144589, 'frFR', 'C\’est à Krag\’wa que vous parlez ?', '', 28153),
(144588, 'frFR', 'Oui, petit être ?', '', 28153),
(144587, 'frFR', 'À bientôt… TRÈS bientôt.', '', 28153),
(144586, 'frFR', 'Ouste ! Je veux plus vous voir.', '', 28153),
(144585, 'frFR', 'Tôt ou tard… tout le monde vient à moi.', '', 28153),
(144584, 'frFR', 'Vous avez l\’air d\’avoir soif. Vous voulez un bol de bouillon d\’onze heures ? Ha ha ha !', '', 28153),
(144583, 'frFR', 'Je vois des gens qui sont morts. Mais pour moi, c\’est normal.', '', 28153),
(144582, 'frFR', 'Hmmm… Vous aimez vivre dangereusement.', '', 28153),
(144581, 'frFR', 'Du calme. Oubliez pas à qui vous avez affaire.', '', 28153),
(144580, 'frFR', 'Bonjour, bonjour ! Vous venez faire un marché ?', '', 28153),
(144579, 'frFR', 'Qu\’est-ce que la mort, elle peut faire pour vous ?', '', 28153),
(144578, 'frFR', 'Alors… Quel bon vent vous amène chez ce pauv\’ vieux Bwonsamdi ?', '', 28153),
(144577, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(144576, 'frFR', 'Il faut mettre un terme à cette folie avant qu\’il soit trop tard.', '', 28153),
(144575, 'frFR', '', 'Je le serrerai contre moi, comme ça il ne se perdra plus.', 28153),
(144574, 'frFR', 'Ils l\’ont pris à notre nez et à notre barbe ! Quel culot !', '', 28153),
(144573, 'frFR', 'Non, non, ce n\’est pas possible. D\’après mes calculs, il devrait être…', '', 28153),
(144572, 'frFR', 'Ces résultats sont plus que déroutants. Si seulement ces… hum, quel nom pourrait-on leur donner ? Ces barbus ? pouvaient me laisser me concentrer !', '', 28153),
(144571, 'frFR', 'Je dois réessayer. Vous avez fait du bon travail, même si je voyais nos ennemis plus grands.', '', 28153),
(144570, 'frFR', 'J\’imagine que vous pourrez faire en sorte que rien ne vienne me déranger, n\’est-ce pas ?', '', 28153),
(144569, 'frFR', 'Par ici ! Une fois que j\’aurai commencé la localisation, j\’y consacrerai toute mon attention.', '', 28153),
(144568, 'frFR', 'Argus l\’Annihilateur déploie des modules de réorigination !', 'Argus l\’Annihilateur déploie des modules de réorigination !', 28153),
(144567, 'frFR', '', 'Nuu est là pour nous aider. Je savais que tu nous retrouverais, Nuu !', 28153),
(144566, 'frFR', 'Il y a encore des dégâts structurels et de l\’énergie instable dans les aqueducs. Les portes resteront fermées pour le moment.', 'Il y a encore des dégâts structurels et de l\’énergie instable dans les aqueducs. Les portes resteront fermées pour le moment.', 28153),
(144565, 'frFR', 'Je veillerai sur lui. Il a l\’air ravi de flâner dans les jardins.', 'Je veillerai sur lui. Il a l\’air ravi de flâner dans les jardins.', 28153),
(144564, 'frFR', '', 'Excellent ! Je suis impressionnée !', 28153),
(144563, 'frFR', '', 'Diriger l\’énergie du chi vers une cible peut s\’avérer difficile de prime abord.\n\nVous, là ! Essayez de toucher le mannequin d\’entraînement là-bas.', 28153),
(144562, 'frFR', 'Pst, $pr... Z\’êtes là pour affaire ?', '', 28153),
(144561, 'frFR', 'Qu\’est-ce que vous avez là, $p ? Serait-ce une fleur centenaire ?', '', 28153),
(144560, 'frFR', '', 'Faut qu\’on commence à préparer les prochains semis, Jahden.', 28153),
(144559, 'frFR', 'Hum... Manque un p\’tit quelque chose dans ce chili... L\’est un peu fade.', '', 28153),
(144558, 'frFR', '', 'Zancha ! Tu n\’aurais pas encore oublié de remplir la réserve de pierres de foyer, des fois ?', 28153),
(144557, 'frFR', 'Saluuuuuut !', '', 28153),
(144556, 'frFR', 'Nagez dans le bonheur !', '', 28153),
(144555, 'frFR', 'L\’eau, c\’est trop bien. J\’aime bien l\’eau. Et vous ? C\’est quoi que vous préférez avec l\’eau ? Moi, c\’est quand ça éclabousse ! L\’eau, c\’est trop trop bien, pas vrai ?', '', 28153),
(144554, 'frFR', 'Ma maman, elle dit qu\’on est amphobies… amfourbis… ah… grrr… amphibies. Ouais, ouais. Enfin comme ça, quoi !', '', 28153),
(144553, 'frFR', 'Tortol tortol tortol, je me roule par terre ! Tortol tortol tortol, les quatre pattes en l\’air !', '', 28153),
(144552, 'frFR', 'Quand je serai grand, je lirai TOUS les trucs qui existent !', '', 28153),
(144551, 'frFR', 'Comment vous faites pour transporter vos affaires sans carapace ?', '', 28153),
(144550, 'frFR', 'J\’aime bien faire des roulades !', '', 28153),
(144549, 'frFR', 'Bientôt je serai aussi vieux que vous !', '', 28153),
(144548, 'frFR', 'C\’est ça, partez. J\’en avais fini avec vous de toute façon.', '', 28153),
(144547, 'frFR', 'Vous ne trouverez pas aussi charmant et avenant que moi dans tout l\’océan.', '', 28153),
(144546, 'frFR', 'Si vous trouvez des objets exotiques, apportez-les-moi.', '', 28153),
(144545, 'frFR', 'J\’espère que vous aurez mieux à raconter la prochaine fois.', '', 28153),
(144544, 'frFR', 'J\’ai vu des choses qui feraient pâlir votre carapace.', '', 28153),
(144543, 'frFR', 'Approchez et parlez à voix haute et intelligible.', '', 28153),
(144542, 'frFR', 'Salutations, cher monsieur… ou madame !', '', 28153),
(144541, 'frFR', 'Avez-vous des antiquités à céder ? Je collectionne les objets de plus deux siècles.', '', 28153),
(144540, 'frFR', '', 'Vous voulez me quitter ?', 28153),
(144539, 'frFR', '', 'À plus !', 28153),
(144538, 'frFR', '', 'Une fois, j\’ai volé un alpaga et je l\’ai emmené au temple. Et c\’est là que ma maman, elle m\’a dit de le laisser partir.', 28153),
(144537, 'frFR', '', 'Une fois, j\’ai battu un aventurier et j\’ai gardé son crâne en souvenir. Même qu\’il était plus costaud que vous…', 28153),
(144536, 'frFR', '', 'Une fois, j\’ai attrapé un brutosaure par la queue. Je suis restée sur son dos pendant trente-deux secondes et demie.', 28153),
(144535, 'frFR', 'Un albatros féroce fond sur l\’œuf éclos.', '', 28153),
(144534, 'frFR', '', 'Une fois, j\’ai attrapé un sauride. Il était très très très très très très gros. Et puis des grands m\’ont dit que c\’était un ravasaure, mais j\’suis sûre que c\’était un mensonge.', 28153),
(144533, 'frFR', '', 'Une fois, j\’ai attrapé le plus gros poisson du monde. Mais en fait, c\’était juste un garde transformé.', 28153),
(144532, 'frFR', '', 'Taz\’okun !', 28153),
(144531, 'frFR', '', 'Taz\’dingo !', 28153),
(144530, 'frFR', '', 'Mon Loa, il est plus fort que ton Loa !', 28153),
(144529, 'frFR', '', 'Moi, un jour, je serai un Loa !', 28153),
(144528, 'frFR', 'À plus.', '', 28153),
(144527, 'frFR', 'Où vous allez ?', '', 28153),
(144526, 'frFR', 'Les Loas, y sont trop forts. Y en a plein qui pourraient vous manger en entier !', '', 28153),
(144525, 'frFR', 'Quand j\’serai grand, j\’serai un druide brutosaure. Roaaaar !', '', 28153),
(144524, 'frFR', 'J\’ai dix orteils… mais y en que quatre qui sont à moi.', '', 28153),
(144523, 'frFR', 'C\’est vous qui avez volé ma collection de têtes réduites ?', '', 28153),
(144522, 'frFR', 'Oh, salut.', '', 28153),
(144521, 'frFR', 'Taz\’okun !', '', 28153),
(144520, 'frFR', 'Taz\’dingo !', '', 28153),
(144519, 'frFR', 'Rarrrh !', '', 28153),
(144518, 'frFR', 'Les Loas, ils sont puissants ici.', 'Les Loas, ils sont puissants ici.', 28153),
(144517, 'frFR', 'Les esprits soient avec vous.', 'Les esprits soient avec vous.', 28153),
(144516, 'frFR', 'Les Loas veillent toujours.', 'Les Loas veillent toujours.', 28153),
(144515, 'frFR', 'Bah ! Tenez, prenez ça et repassez demain.', 'Bah ! Tenez, prenez ça et repassez demain.', 28153),
(144513, 'frFR', 'N\’attisez pas les foudres des Loas…', 'N\’attisez pas les foudres des Loas…', 28153),
(144512, 'frFR', 'Vous ne trouverez que du bon juju ici.', 'Vous ne trouverez que du bon juju ici.', 28153),
(144511, 'frFR', 'Les esprits murmurent votre nom.', 'Les esprits murmurent votre nom.', 28153),
(144510, 'frFR', 'Quel Loa servez-vous ?', 'Quel Loa servez-vous ?', 28153),
(144509, 'frFR', '', 'En avant ! Pour l\’avenir de Zandalar !', 28153),
(144508, 'frFR', 'Pour un premier contact, c\’est un peu gênant… J\’ai intérêt à me dépêcher de rentrer avant que Kugro ne me remonte les bretelles.', '', 28153),
(144498, 'frFR', 'Zandalar résistera.', 'Zandalar résistera.', 28153),
(144497, 'frFR', 'Ne vous défilez jamais devant les faibles.', '', 28153),
(144496, 'frFR', 'Que vos ennemis soient lacérés.', '', 28153),
(144495, 'frFR', 'Puissiez-vous savourer la chair de vos ennemis.', '', 28153),
(144494, 'frFR', 'Qu\’y a-t-il, enfant de la Horde ?', '', 28153),
(144493, 'frFR', 'Vous foulez mes terres.', '', 28153),
(144492, 'frFR', 'Êtes-vous le prédateur ou la proie ?', '', 28153),
(144491, 'frFR', 'Êtes-vous ici pour conclure un marché ?', '', 28153),
(144490, 'frFR', 'Que le monde entende parler de moi.', '', 28153),
(144489, 'frFR', 'Que vos ennemis ne vous repèrent jamais.', '', 28153),
(144488, 'frFR', 'Apportez la force à votre meute.', '', 28153),
(144486, 'frFR', 'Si vous comptez fuir, rappelez-vous que… je sais ouvrir les portes.', '', 28153),
(144484, 'frFR', 'Continuez ainsi et vous serez ma prochaine proie.', '', 28153),
(144481, 'frFR', 'Je suis le maître de la métamorphose, le chef de la meute, le seigneur de la chasse.', '', 28153),
(144480, 'frFR', 'Qu\’est-ce qui vous amène devant le seigneur de la chasse ?', '', 28153),
(144479, 'frFR', 'Êtes-vous ici pour conclure un marché ?', '', 28153),
(144478, 'frFR', '', 'Puisse le vent vous porter… aussi loin de moi que possible.', 28153),
(144477, 'frFR', '', 'Les cieux m\’appartiennent, ne l\’oubliez pas.', 28153),
(144476, 'frFR', '', 'Puissiez-vous faire pleuvoir la mort.', 28153),
(144475, 'frFR', '', 'Le vent se plie à ma volonté.', 28153),
(144474, 'frFR', '', 'Je vais vous attraper… et vous lâcher sur un rocher bien dur !', 28153),
(144473, 'frFR', '', 'Cherchez-vous à attiser mon courroux ?', 28153),
(144472, 'frFR', '', 'Vous mettez ma patience à rude épreuve, petit être.', 28153),
(144471, 'frFR', '', 'Pourquoi vous respirez le même air que moi ?', 28153),
(144470, 'frFR', '', 'Qu\’y a-t-il, mon enfant ?', 28153),
(144469, 'frFR', '', 'Êtes-vous ici pour conclure un marché ?', 28153),
(144468, 'frFR', '', 'Pst, $PR… Vous en avez marre de ressembler à un sauride ? Mon mojo, il peut vous donner l\’apparence d\’un diablosaure, rien que ça !', 28153),
(144462, 'frFR', '', 'Choisissez bien votre Loa.', 28153),
(144461, 'frFR', '', 'Perdez jamais la trace de vos ennemis.', 28153),
(144460, 'frFR', '', 'Pour la meute.', 28153),
(144459, 'frFR', '', 'Ne domptez jamais la bête en vous.', 28153),
(144458, 'frFR', '', 'Laissez libre cours à votre côté sauvage.', 28153),
(144457, 'frFR', '', 'Vous éloignez pas trop, je pourrais avoir besoin de vos services.', 28153),
(144456, 'frFR', '', 'Ahhh, je suis vannée.', 28153),
(144455, 'frFR', '', 'Alors, vous arrêtez surtout pas.', 28153),
(144454, 'frFR', '', 'Si vous continuez comme ça, mon mari, il va voir rouge.', 28153),
(144453, 'frFR', '', 'Vous avez déjà laissé parler votre côté sauvage ?', 28153),
(144452, 'frFR', 'Il est temps pour moi de prendre les choses en main. Moi vivant, vous ne saboterez pas cette opération !', '', 28153),
(144451, 'frFR', 'Merci, $n. Kugro n\’a pas chômé, à ce que je vois. Alors… que faire de tous ces parchemins ?', '', 28153),
(144450, 'frFR', '', 'Le Loa, il est puissant ici.', 28153),
(144449, 'frFR', '', 'C\’est ça la forme que vous avez choisie pour vous promener ?', 28153),
(144448, 'frFR', 'C\’est pas vous, mon contact ! Par ici, les gars ! On a un arrivage de chair fraîche !', '', 28153),
(144447, 'frFR', '', 'Je sers Gonk, le maître de la métamorphose.', 28153),
(144446, 'frFR', '<Donner les parchemins à Itokka.>', '<Donner les parchemins à Itokka.>', 28153),
(144445, 'frFR', '', 'Si seulement Nuu était là, il saurait quoi faire.', 28153),
(144444, 'frFR', '', 'Oh, bonjour ! Qui êtes-vous ? Moi, c\’est Uuna. Vous voulez être mon $gami:amie; ? Ensemble, on parviendra à sortir d\’ici.', 28153),
(144443, 'frFR', 'Hé ! J\’ai exactement c\’qu\’y vous faut ! La protection personnelle anti-sauride de Zul ! Avec ça, ces sales voleurs, ils vous approcheront plus !', '', 28153),
(144442, 'frFR', '', 'Il y a trop de lumière ! Trop de lumière ! Aaaah !', 28153),
(144441, 'frFR', 'Soyez $gbéni:bénie;, $gvoyageur:voyageuse;.\n\nDéposez votre arme et reposez-vous un instant.\n\nLa guerre attendra.', '', 28153),
(144440, 'frFR', 'Bonjour, pakura\’ai !', '', 28153),
(144439, 'frFR', 'Choisissez le bon Loa.', '', 28153),
(144438, 'frFR', 'Mon Loa dit toujours : « Partez ! »', '', 28153),
(144437, 'frFR', 'Que Pa\’ku voie vos ennemis avant qu\’ils vous voient.', '', 28153),
(144436, 'frFR', 'Que les vents de la guerre vous soient favorables.', '', 28153),
(144435, 'frFR', 'Oui ! Là, c\’est parfait ! Oh, c\’est bon !', '', 28153),
(144434, 'frFR', 'Oui, continuez… Juste un peu plus à droite… Oui c\’est bon, c\’est ça !', '', 28153),
(144433, 'frFR', 'Ma femme ne me donne pas autant d\’attention que vous.', '', 28153),
(144432, 'frFR', 'Mon Loa dit toujours : « Touchez pas à ça ! »', '', 28153),
(144431, 'frFR', 'Mon Loa dit toujours : « Aloha ! » Ha ha ha !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144430, 'frFR', 'Ne volez pas dans les plumes de Pa\’ku.', '', 28153),
(144429, 'frFR', 'Les cieux sont mes yeux.', '', 28153),
(144428, 'frFR', 'Je sers Pa\’ku, un des plus anciens Loas.', '', 28153),
(144427, 'frFR', '', 'Je me bats pour ceux qui n\’ont pas de protecteurs.', 28153),
(144425, 'frFR', 'On a tous à un rôle à jouer, même vous.', '', 28153),
(144424, 'frFR', 'J\’ai assisté à plein d\’évènements majeurs de notre époque, et vous étiez là à chaque fois. Étrange.', '', 28153),
(144423, 'frFR', 'Les jours de terreur, ils approchent à grands pas.', '', 28153),
(144422, 'frFR', 'C\’est ça la terreur. La véritable terreur.', '', 28153),
(144421, 'frFR', 'L\’empire des Trolls, il retrouvera sa gloire d\’antan. Je l\’ai vu.', '', 28153),
(144420, 'frFR', 'Les Trolls, c\’était les premiers à régner sur ce monde, et ce sera aussi les derniers.', '', 28153),
(144419, 'frFR', 'Le destin n\’est pas de votre côté, je vous le garantis.', '', 28153),
(144418, 'frFR', 'Je sais déjà ce que vous allez dire, alors abrégez.', '', 28153),
(144417, 'frFR', 'J\’ai vu comment ce monde allait finir, et vous allez pas aimer ça.', '', 28153),
(144416, 'frFR', '', 'Zandalar résistera.', 28153),
(144415, 'frFR', '', 'Vengeance pour nos morts.', 28153),
(144414, 'frFR', '', 'Puissent les crânes de vos ennemis orner vos habits.', 28153),
(144413, 'frFR', '', 'Les temps changent et les Zandalari devraient suivre le mouvement.', 28153),
(144412, 'frFR', '', 'Il y a beaucoup à faire. Allez à l\’essentiel.', 28153),
(144411, 'frFR', 'Que l\’ennemi tremble en vous voyant.', '', 28153),
(144410, 'frFR', 'Zandalar pour toujours.', '', 28153),
(144409, 'frFR', 'Rezan vous donne la force.', '', 28153),
(144408, 'frFR', 'C\’est bon d\’être le roi.', '', 28153),
(144407, 'frFR', 'Vous vous tenez devant le roi Rastakhan.', '', 28153),
(144406, 'frFR', 'Bienvenue à Zuldazar.', '', 28153),
(144405, 'frFR', 'Prédateur… ou proie ?', '', 28153),
(144404, 'frFR', '', 'Si seulement on pouvait y voir plus clair. Il fait si sombre ici !', 28153),
(144403, 'frFR', '', 'Mais on est $gamis:amies;, alors je suis certaine que ça va aller.', 28153),
(144402, 'frFR', '', 'Au moins maintenant on est ensemble. Même si on ne sait pas où.', 28153),
(144401, 'frFR', '', 'À l\’aide ! À L\’AIDE !', 28153),
(144400, 'frFR', '', 'Qui êtes-vous ? Vous pouvez m\’aider ?', 28153),
(144399, 'frFR', '', 'Il fait trop sombre ! Je ne vois rien !', 28153),
(144397, 'frFR', '', 'On en a fini avec Élisande, mais il reste encore beaucoup à faire pour la ville.', 28153),
(144396, 'frFR', '', 'Les Sacrenuit sont véritablement libres. Nous n\’avons plus besoin du Puits de la nuit, ni de sa puissance.$B$BIl nous faut à présent forger notre propre destin.', 28153),
(144395, 'frFR', 'J\’ai apporté des échantillons pour dissiper les rumeurs qui veulent que notre vin ait un arôme de pieds… de vigne, il va sans dire !', '', 28153),
(144394, 'frFR', 'Certains de nos vignerons ont cessé de travailler dans leurs vignobles pour s\’adonner à d\’autres activités botaniques.', '', 28153),
(144393, 'frFR', 'Ouais, les Trolls de sang, ils se battaient avec les gardes quand on est arrivés. Ils s\’attendaient pas à ce qu\’on les attaque par derrière.', '', 28153),
(144392, 'frFR', 'Oh, en v\’là un gros. Je vais avoir besoin de votre aide pour lui faire la peau !', '', 28153),
(144391, 'frFR', 'Si vous voyez un groupe de ces vermines, balancez-leur l\’une de ces bombes de piquants pour leur rendre la monnaie de leur pièce !', '', 28153),
(144390, 'frFR', 'Je parie que vous l\’avez senti passer ! Fichez le camp de mes terres !', '', 28153),
(144389, 'frFR', 'Ha, pile entre les deux yeux !', '', 28153),
(144388, 'frFR', 'Vous pouvez retourner dire à Roz que je vais bien, mais que je ne quitterai jamais ma ferme. Je resterai avec eux.', '', 28153),
(144387, 'frFR', 'Oui, c\’est très bien comme ça. Ils adoraient cet endroit…', '', 28153),
(144386, 'frFR', 'Vous pouvez emprunter le portail d\’Orgrimmar pour rejoindre la capitale de nos nouveaux alliés de la Horde en Kalimdor.', '', 28153),
(144385, 'frFR', '', 'Rokhan ! Tout va bien ? On dirait qu\’on s\’est battu ici.', 28153),
(144384, 'frFR', 'J\’ai entendu dire que Dalaran a tout un espace dédié aux déplacements magiques.$B$BImaginez les possibilités !', '', 28153),
(144383, 'frFR', 'Ces portails sont extrêmement difficiles à maintenir et, qui plus est, ils détournent notre attention de nos précieuses recherches.$B$BLa télémancie devrait pouvoir nous apporter une solution durable.', '', 28153),
(144382, 'frFR', 'Qui a dit que les Gobelins avaient pas de culture ?', '', 28153),
(144381, 'frFR', 'Ils ont même un de nos tambours !', '', 28153),
(144380, 'frFR', '... et trouvez-vous un tonneau en perce !', '', 28153),
(144379, 'frFR', 'Bienvenue au Tambour ivre, $pr ! Prenez donc un verre…', '', 28153),
(144378, 'frFR', 'Argh ! Faut croire que mon plan, il était pas infaillible, mec !', '', 28153),
(144377, 'frFR', 'Pôv\’ naze ! Z\’allez regretter d\’avoir mis les pieds sous mon pont !', '', 28153),
(144376, 'frFR', 'Hé, mec ! C\’est mon pont qu\’vous traversez, là. Va falloir raquer. Ouais, le péage ou la vie, mec !', '', 28153),
(144375, 'frFR', 'Je suis prêt à commencer l\’épreuve.', 'Je suis prête à commencer l\’épreuve.', 28153),
(144374, 'frFR', '', 'Et si on y ajoutait quelques explosifs, hein ? Imaginez un peu le spectacle... Des dinosaures à retardement !', 28153),
(144373, 'frFR', '', 'J\’apprécie votre enthousiasme, Shuga, mais je suis prête à parier que les Zandalari préfèrent de loin les armes enchantées par une puissante magie à un vulgaire bricolage dégoulinant de graisse.', 28153),
(144372, 'frFR', 'Que… que sommes-nous devenus ?', '', 28153),
(144371, 'frFR', '', 'Non ! Lâchez-moi ! Au secours ! À L\’AIDE !', 28153),
(144370, 'frFR', '', 'Les ténèbres sont revenues ! Où êtes-vous ? Ne me laissez pas !', 28153),
(144369, 'frFR', '', 'J\’avais une baguette magique comme ça avant ! Mais je l\’ai perdue il y a longtemps.', 28153),
(144368, 'frFR', '', 'Une couronne ! Trop jolie !', 28153),
(144367, 'frFR', '', 'Nuu-Nuu ! J\’ai eu peur de ne jamais te revoir ! Comment as-tu atterri ici ?', 28153),
(144366, 'frFR', '', 'Il fait un peu plus clair ! Je vois ! Un peu.', 28153),
(144365, 'frFR', '', 'Qu\’est-ce que c\’est que ça ? De la lumière dans les ténèbres ! C\’est trop lumineux…', 28153),
(144364, 'frFR', 'Elle avait… promis…', '', 28153),
(144363, 'frFR', 'Mais on m\’avait dit que c\’était le moyen d\’être enfin réunis !', '', 28153),
(144362, 'frFR', '', 'Avec l\’aide des Loas et forts du courage qui nous anime, nous allons triompher !', 28153),
(144361, 'frFR', '', 'Nous allons anéantir les Trolls de sang, et nous assurer que leur abomination ne nous frappe plus jamais !', 28153),
(144360, 'frFR', '', 'Nos ennemis cherchent à détruire tout ce qui nous est cher. Nous ne pouvons pas les laisser y parvenir ! L\’avenir de Zandalar repose entièrement sur nous !', 28153),
(144359, 'frFR', '', 'Soldats… amis. Nous avons traversé bien des difficultés, mais notre combat touche à son but.', 28153),
(144358, 'frFR', 'Montrez-moi où je peux me rendre.', 'Montrez-moi où je peux me rendre.', 28153),
(144357, 'frFR', 'Vous voulez faire un voyage en bac ?', 'Vous voulez faire un voyage en bac ?', 28153),
(144356, 'frFR', '', 'Heureusement que j\’ai mis mes bottes !', 28153),
(144355, 'frFR', 'Je vais prendre quelques Tortollans avec moi et aller à pied jusqu\’à Zul\’jan. Bonne chance à vous deux.', '', 28153),
(144354, 'frFR', 'Je vis et meurs… pour la Horde !', 'Je vis et meurs… pour la Horde !', 28153),
(144353, 'frFR', 'Sang et honneur !', 'Sang et honneur !', 28153),
(144352, 'frFR', 'Arathi appartient à la Horde !', 'Arathi appartient à la Horde !', 28153),
(144351, 'frFR', 'Suivez-moi !', 'Suivez-moi !', 28153),
(144350, 'frFR', 'Mort à l\’Alliance !', 'Mort à l\’Alliance !', 28153),
(144349, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(144348, 'frFR', 'Par ici ! À l\’attaque !', 'Par ici ! À l\’attaque !', 28153),
(144347, 'frFR', 'En avant, les grunts ! On a une guerre à gagner !', 'En avant, les grunts ! On a une guerre à gagner !', 28153),
(144346, 'frFR', 'Je suis Gral !', '', 28153),
(144345, 'frFR', 'Au sud d\’ici se dresse ce qu\’il reste de mon temple. Retrouvez-moi sur place et nous apprendrons à ces Nagas ce qu\’est la fureur d\’un Loa requin !', '', 28153),
(144344, 'frFR', 'Oh… Voilà qui était délicieux.', '', 28153),
(144343, 'frFR', 'Il n\’existe pas de profondeurs assez ténébreuses pour vous !', '', 28153),
(144342, 'frFR', 'Les Nagas ne sont pas les bienvenus à Atal\’Gral !', '', 28153),
(144341, 'frFR', 'L\’odeur délicieuse du sang de Naga enragé... l\’attrait irrésistible des morceaux de choix... je ne peux que répondre à cet appel.', '', 28153),
(144340, 'frFR', '', 'Mère... Benjamin m\’a tout raconté.\n\nVous ne pouviez pas m\’entendre auparavant, mais peut-être le pouvez-vous à présent ? Tout ce que je demande, c\’est une explication.', 28153),
(144339, 'frFR', '', 'Mère, je sais que vous n\’êtes pas là. Mais si vous m\’entendez...', 28153),
(144338, 'frFR', 'Contrairement à notre mère, je suis loin d\’être un as de la gestion. Quand je pense qu\’elle est tombée si bas…$b$bEnfin, merci pour votre aide, $n. On va s\’en sortir.', '', 28153),
(144337, 'frFR', '', 'Où est-ce que vous allez ?', 28153),
(144336, 'frFR', '', 'S\’il vous plaît, me laissez pas.', 28153),
(144335, 'frFR', 'La maîtresse des profondeurs nous mènera tous à la victoire !', 'La maîtresse des profondeurs nous mènera tous à la victoire !', 28153),
(144334, 'frFR', 'Ravi de vous voir tous en un seul morceau grâce à… Hé, justement voilà notre vedette !', '', 28153),
(144333, 'frFR', 'Vous restez ou vous partez ?', '', 28153),
(144332, 'frFR', 'Veuillez m\’excuser. Je dois aller trouver ma sœur.', '', 28153),
(144331, 'frFR', 'Quand mon père est mort, ma mère s\’est volatilisée. Je n\’aurais jamais cru que…', '', 28153),
(144330, 'frFR', 'Mon père et elle ont travaillé toute leur vie pour monter cette entreprise et pourvoir à nos besoins, à ma sœur et moi.', '', 28153),
(144329, 'frFR', 'Cette sorcière… c\’était ma mère.', '', 28153),
(144328, 'frFR', 'On dirait que vous savez vous y prendre avec les bêtes. De quoi avez-vous besoin ?', '', 28153),
(144327, 'frFR', 'Quoi encore ? Vous avez perdu quelque chose ?', '', 28153),
(144326, 'frFR', 'Excellent ! Recommencez encore une fois.', '', 28153),
(144325, 'frFR', 'Il est dangereux de dépenser une importante quantité d\’énergie d\’une traite. Dosez votre effort.', '', 28153),
(144324, 'frFR', 'Le chi, une fois focalisé, devient extrêmement puissant. Maître Tau Li vous guidera dès que vous serez $gprêt:prête;.', '', 28153),
(144323, 'frFR', 'Lorsque vous prodiguez des soins, vous devez concentrer votre force intérieure afin de la transmettre à un autre.', '', 28153),
(144322, 'frFR', 'Heureusement, je n\’ai pas eu à TOUT donner.', 'Heureusement, je n\’ai pas eu à TOUT donner.', 28153),
(144321, 'frFR', 'Nos frères et sœurs corrompus errent encore dans la nature.', 'Nos frères et sœurs corrompus errent encore dans la nature.', 28153),
(144320, 'frFR', '', 'Ma vie… pour la Horde…', 28153),
(144319, 'frFR', '', 'À la prochaine, camarade.', 28153),
(144318, 'frFR', '', 'Sang et tonnerre !', 28153),
(144317, 'frFR', '', 'Je vais vous massacrer.', 28153),
(144316, 'frFR', '', 'Mes lames réclament votre chair.', 28153),
(144315, 'frFR', '', 'Votre force ne fait pas le poids face à celle d\’un Orc !', 28153),
(144314, 'frFR', '', 'Vos os ne résisteront pas à mes lames !', 28153),
(144313, 'frFR', '', 'Tenez la formation ! Personne ne passe !', 28153),
(144312, 'frFR', 'Merci à vous.', '', 28153),
(144311, 'frFR', 'Si je ne vous reconnais pas la prochaine fois que nous nous verrons, ne m\’en tenez pas rigueur.', '', 28153),
(144310, 'frFR', 'Merci pour votre intervention auprès de Torok. Il refusait d\’ouvrir les yeux sur le dangereux pouvoir qu\’il convoitait.', 'Merci pour votre intervention auprès de Torok. Il refusait d\’ouvrir les yeux sur le dangereux pouvoir qu\’il convoitait.', 28153),
(144309, 'frFR', '<Le Tauren endormi ronfle et se retourne.>', '<La Taurène endormie ronfle et se retourne.>', 28153),
(144308, 'frFR', 'ZZzzzz…', 'ZZzzzz…', 28153),
(144307, 'frFR', 'Je le suis, princesse. Jusqu\’au bout.', '', 28153),
(144306, 'frFR', '', 'C\’est le seul moyen de sauver mon peuple, Rokhan. Je ferais n\’importe quoi pour le mettre en sécurité. Tu es avec moi ?', 28153),
(144305, 'frFR', 'Je n\’arrive toujours pas à croire que mes frères et mes sœurs aient succombé à la corruption.', 'Je n\’arrive toujours pas à croire que mes frères et mes sœurs aient succombé à la corruption.', 28153),
(144304, 'frFR', '', 'Mes filles, voilà comment on accueille les invités !', 28153),
(144303, 'frFR', '', 'Le sang… il me vengera.', 28153),
(144302, 'frFR', '', 'Pour les mères de la guerre !', 28153),
(144301, 'frFR', 'À présent, concentrez votre chi et expulsez l\’énergie.', '', 28153),
(144300, 'frFR', '', 'Votre essence, elle sera plus utile dehors que dedans !', 28153),
(144299, 'frFR', '', 'On va bien se marrer en vous saignant.', 28153),
(144298, 'frFR', '', 'Tout ce sang, il va nous alimenter !', 28153),
(144297, 'frFR', '', 'Je vais tous vous saigner et vos restes, ils vont pourrir !', 28153),
(144296, 'frFR', '', 'Ma lame, elle va se nourrir de sang.', 28153),
(144295, 'frFR', 'Si vous avez besoin d\’un moyen de transport, vous savez où me trouver !', '', 28153),
(144294, 'frFR', '', 'Du sang pour les chantres !', 28153),
(144293, 'frFR', '', 'Plus de peau pour mes harnais !', 28153),
(144292, 'frFR', '', 'Le ciel… m\’appelle.', 28153),
(144291, 'frFR', '', 'Belle journée pour un combat.', 28153),
(144290, 'frFR', '', 'Les croggs, ils vont bien manger, ce soir !', 28153),
(144289, 'frFR', 'Tenez bon ! Je vais voir comment se porte Sa\’tao.', '', 28153),
(144288, 'frFR', 'ENTRÉE - Expérience sur les gelées\n\nJ\’ai réussi à animer les gelées. Au lieu de dissoudre des matières organiques comme la viande ou les végétaux, elles peuvent subsister en se nourrissant uniquement de miel. En faisant fermenter leurs abondantes déjections dans des tonneaux, on obtient un hydromel très puissant au goût délicieux.\n\nCependant, si elles ne sont pas correctement confinées, elles finissent par se mettre en quête de ruches à dévorer. Elles ont alors tendance à devenir plus agressives et impossibles à contrôler.\n\nEn conséquence, les abeilles ont adopté une attitude défensive qui rend leur élevage plus difficile. Il me faudra trouver une solution, car les abeilles ne sont pas facilement remplaçables.', '', 28153),
(144287, 'frFR', '', 'Pohkiza…', 28153),
(144286, 'frFR', '', 'Le Dieu du sang… obtient tout…', 28153),
(144285, 'frFR', '', 'Hahaha !', 28153),
(144284, 'frFR', '', 'Zuldazar… va… tomber…', 28153),
(144283, 'frFR', '', 'Gachaga !', 28153),
(144282, 'frFR', '', 'Mes sœurs… elles me… vengeront…', 28153),
(144281, 'frFR', '', 'Mon sang… pour… G\’huun !', 28153),
(144280, 'frFR', '', 'G\’huun !', 28153),
(144279, 'frFR', '<Tsunga vous adresse un grognement amical.>', '', 28153),
(144278, 'frFR', 'Je viens des brumes pour avertir le peuple de Zandalar. L\’azérite a donné une grande intelligence aux gorilles. Et de cette intelligence viendra la guerre.', '', 28153),
(144277, 'frFR', 'Pohkiza…', '', 28153),
(144276, 'frFR', 'Le Dieu du sang… obtient tout…', '', 28153),
(144275, 'frFR', 'Vous avez… tous… déjà perdu…', '', 28153),
(144274, 'frFR', 'Zuldazar… va… tomber…', '', 28153),
(144273, 'frFR', 'Gachaga !', '', 28153),
(144272, 'frFR', 'Ma vie pour les ma\’das !', '', 28153),
(144271, 'frFR', 'Mon sang… pour… G\’huun !', '', 28153),
(144270, 'frFR', 'G\’huun !', '', 28153),
(144269, 'frFR', 'Excellent. Encore une fois !', '', 28153),
(144268, 'frFR', 'Arrête de gigoter.', '', 28153),
(144266, 'frFR', '', 'Je vais aider à renforcer les défenses du village. Je vous retrouve sur place !', 28153),
(144265, 'frFR', '', 'Nous avons mis fin à leurs attaques ! Venez ! Allons parler au maire Royston.', 28153),
(144264, 'frFR', '', 'Alleria soupire et fronce les sourcils.', 28153),
(144263, 'frFR', '<Rester un instant pour écouter.>', '<Rester un instant pour écouter.>', 28153),
(144262, 'frFR', '', '<Alleria observe le froid visage de pierre de la statue avant de porter son attention sur la plaque où a été gravée son épitaphe.>', 28153),
(144261, 'frFR', 'Tenez vos positions ! Nous nous occupons du front !', 'Tenez vos positions ! Nous nous occupons du front !', 28153),
(144260, 'frFR', 'Vous entendez un gémissement ténu alors que Rohn\’kor rend son dernier soupir.', '', 28153),
(144259, 'frFR', '', 'J\’vais vous arracher les tripes pour me tricoter un nouveau chapeau !', 28153),
(144258, 'frFR', '', 'Non ! Mon bébé !', 28153),
(144257, 'frFR', '', 'Pas touche à mon p\’tit trésor ! Vous sortirez pas de cette fosse en vie !', 28153),
(144256, 'frFR', '', 'On va pas se laisser faire, ça non ! Attaque, mon gars !', 28153),
(144255, 'frFR', 'Bwonsamdi… sois clément !', 'Bwonsamdi… sois clément !', 28153),
(144254, 'frFR', 'Zandalar… pour toujours…', 'Zandalar… pour toujours…', 28153),
(144253, 'frFR', 'On va abréger tes souffrances, Urok ! Désolé que ça se passe comme ça !', '', 28153),
(144252, 'frFR', 'Mais que… qu\’est-ce que c\’est que ces choses qui grouillent à l\’intérieur d\’Urok ?', '', 28153),
(144251, 'frFR', 'On y est presque ! Juste le temps de choper mon équipement…', '', 28153),
(144250, 'frFR', 'Pas comme ça…', 'Pas comme ça…', 28153),
(144249, 'frFR', 'Bwonsamdi… il vient… pour moi…', 'Bwonsamdi… il vient… pour moi…', 28153),
(144248, 'frFR', 'Tenez bon, nouvelle vague d\’ennemis en approche !', 'Tenez bon, nouvelle vague d\’ennemis en approche !', 28153),
(144247, 'frFR', 'Ma… vie… pour Zandalar…', 'Ma… vie… pour Zandalar…', 28153),
(144245, 'frFR', 'Di chuka Zandalar !', 'Di chuka Zandalar !', 28153),
(144243, 'frFR', 'Tuez-les tous !', 'Tuez-les tous !', 28153),
(144242, 'frFR', 'Pour le véritable Zandalar !', 'Pour le véritable Zandalar !', 28153),
(144240, 'frFR', 'Votre sang n\’est bon qu\’à souiller nos terres !', 'Votre sang n\’est bon qu\’à souiller nos terres !', 28153),
(144239, 'frFR', 'Vous allez finir six pieds sous terre !', 'Vous allez finir six pieds sous terre !', 28153),
(144238, 'frFR', 'Vous allez mourir ici !', 'Vous allez mourir ici !', 28153),
(144237, 'frFR', 'Zandalar pour toujours !', 'Zandalar pour toujours !', 28153),
(144236, 'frFR', 'La princesse, elle a dit qu\’on devait trouver les monstres, mais c\’est tous des monstres !', '', 28153),
(144235, 'frFR', 'Le soleil, où est-ce qu\’il est ? On n\’y voit rien dans ce marais de malheur.', '', 28153),
(144234, 'frFR', 'Ça n\’a pas de sens ! Je vois un grand trou. Mais il n\’y a pas de trou sur cette carte !', '', 28153),
(144233, 'frFR', 'Oh ! Ce… ce… ce n\’est rien… Enfin, c\’est décevant.', '', 28153),
(144232, 'frFR', 'Taz\’okun ! Ça pourrait bien être un morceau d\’azérite !', '', 28153),
(144231, 'frFR', 'Qu\’est-ce que c\’est, une sorte d\’aiguille ? Erk. Pourquoi est-ce qu\’elle colle ?', '', 28153),
(144230, 'frFR', 'Oh, comme c\’est beau. Voilà qui plaira sans doute à Talanji.', '', 28153),
(144229, 'frFR', 'Un arbalétrier serficié vous a dans sa ligne de mire ! Esquivez ses tirs !', '', 28153),
(144228, 'frFR', 'On me commande rarement des épées dans ce coin, mais c\’est toujours un plaisir d\’en fabriquer. Même si la raison pour laquelle il nous en faut tant ne m\’enchante guère…', '', 28153),
(144227, 'frFR', 'Je comprends pourquoi les gens ont peur de ce marais.', '', 28153),
(144226, 'frFR', 'Comme c\’est étrange.', '', 28153),
(144225, 'frFR', 'Je ne crois pas que je pourrai un jour débarrasser mes mains de cette saleté. Mes pauvres parchemins.', '', 28153),
(144224, 'frFR', 'Il est étrange, ce rocher… Oh ! Il a bougé !', '', 28153),
(144223, 'frFR', 'C\’est fascinant.', '', 28153),
(144222, 'frFR', 'Que Gonk guide vos pas.', 'Que Gonk guide vos pas.', 28153),
(144221, 'frFR', 'Que Pa\’ku veille sur vous.', 'Que Pa\’ku veille sur vous.', 28153),
(144220, 'frFR', 'Que Rezan vous donne la force.', 'Que Rezan vous donne la force.', 28153),
(144219, 'frFR', 'Attention à vous.', 'Attention à vous.', 28153),
(144218, 'frFR', 'Il faut faire attention dans notre cité.', 'Faites attention dans notre cité.', 28153),
(144217, 'frFR', 'Zandalar pour toujours !', 'Zandalar pour toujours !', 28153),
(144216, 'frFR', 'Vous avez besoin de protection ?', 'Vous avez besoin de protection ?', 28153),
(144215, 'frFR', 'Vous ne trouverez pas mieux ailleurs !', 'Vous trouverez pas mieux ailleurs !', 28153),
(144214, 'frFR', 'Qu\’est-ce qui vous amène ?', 'Qu\’est-ce qui vous amène ?', 28153),
(144213, 'frFR', 'Salutations.', 'Salutations.', 28153),
(144209, 'frFR', 'J\’ai juré de défendre la famille royale.', 'J\’ai juré de défendre la famille royale.', 28153),
(144208, 'frFR', 'Je protège notre royaume.', 'Je protège notre royaume.', 28153),
(144201, 'frFR', 'Commençons.', 'Commençons.', 28153),
(144200, 'frFR', 'Nous y sommes presque, $n.$b$bVous n\’avez qu\’un mot à dire et je procéderai à la localisation.$b$bOh, j\’allais oublier. Nos adversaires ont dressé leurs tentes de l\’autre côté, le long de la plage, alors restez sur vos gardes. Ils pourraient nous tendre une embuscade.$b$bJe compte sur vous pour me défendre si on nous accoste !', '', 28153),
(144199, 'frFR', 'Continuez comme ça ! Nous ne les laisserons pas passer !', '', 28153),
(144198, 'frFR', 'La nuit approche ! Les feux ne doivent en aucun cas s\’éteindre ! Prévenez si vous avez besoin de combustible.', '', 28153),
(144197, 'frFR', 'Ne laissez pas passer une seule de ces monstruosités ! Nous avons vaincu leur mastodonte, mais nous avons aussi perdu de nombreux navires.', '', 28153),
(144196, 'frFR', 'Quand vous aurez pris un peu de repos, allez remplacer quelqu\’un à la barricade ! Nous devons tenir plus longtemps que ces monstres !', '', 28153),
(144195, 'frFR', 'J\’ai besoin de volontaires pour aller chez Ashton ! Il devrait être capable de bricoler quelques fusées éclairantes.', '', 28153),
(144194, 'frFR', 'Assurez-vous de nourrir les enfants en premier, ensuite, passez aux blessés !', '', 28153),
(144193, 'frFR', 'Les soigneurs doivent se relayer pour pouvoir se reposer ! Et c\’est valable pour vous aussi, Krystin !', '', 28153),
(144192, 'frFR', 'Renforcez la barricade ! Commencez par utiliser tout ce qui n\’est pas fixé et quand vous serez à court, démontez tout le reste !', '', 28153),
(144191, 'frFR', 'Le jeune crogg émet une série de couinements étranges et frotte ses pattes contre le nénuphar.', '', 28153),
(144190, 'frFR', 'Les marins feraient mieux de garder un œil sur la Horde plutôt que sur nous.', 'Les marins feraient mieux de garder un œil sur la Horde plutôt que sur nous.', 28153),
(144189, 'frFR', 'Plus vite on lèvera l\’ancre après avoir trouvé ce qu\’on cherche, mieux ça vaudra.', 'Plus vite on lèvera l\’ancre après avoir trouvé ce qu\’on cherche, mieux ça vaudra.', 28153),
(144188, 'frFR', 'La Horde n\’est pas loin. Restez sur vos gardes !', 'La Horde n\’est pas loin. Restez sur vos gardes !', 28153),
(144187, 'frFR', 'J\’aurais aimé que la Ligue des explorateurs assigne plus de monde à cette expédition.', 'J\’aurais aimé que la Ligue des explorateurs assigne plus de monde à cette expédition.', 28153),
(144186, 'frFR', 'Allez savoir ce que maniganceraient les Sombrefer si on n\’était pas là pour garder un œil sur eux...', 'Allez savoir ce que maniganceraient les Sombrefer si on n\’était pas là pour garder un œil sur eux...', 28153),
(144185, 'frFR', '', 'Sans oublier leur progéniture ! Je pourrais même bricoler une cabine photo et des peluches de dino. Bien sûr, vous auriez droit à votre part du gâteau, Jangalar. Disons, 70-30 en ma faveur. C\’est mon idée, après tout.', 28153),
(144184, 'frFR', 'Il y en a un autre qui a besoin d\’aide, par là, si vous voulez bien.', '', 28153),
(144183, 'frFR', '', 'RÉUTILISER : Il est temps d\’utiliser l\’injecteur pour enrager Ben\’jin. Ensuite, nous le suivrons et nous l\’aiderons à détruire les espèces envahissantes.', 28153),
(144182, 'frFR', 'D\’ici à ce qu\’on ait fini de creuser, la Horde sera à mi-chemin de Forgefer !', 'D\’ici à ce qu\’on ait fini de creuser, la Horde sera à mi-chemin de Forgefer !', 28153),
(144181, 'frFR', 'Les Sombrefer ne craignent pas la chaleur. Mais cette humidité...', 'Les Sombrefer ne craignent pas la chaleur. Mais cette humidité...', 28153),
(144180, 'frFR', 'Dès qu\’il s\’agit de creuser, la Ligue des explorateurs aime prendre son temps. Mais on a une guerre à gagner.', 'Dès qu\’il s\’agit de creuser, la Ligue des explorateurs aime prendre son temps. Mais on a une guerre à gagner.', 28153),
(144179, 'frFR', 'On a quitté nos montagnes pour ça ?', 'On a quitté nos montagnes pour ça ?', 28153),
(144178, 'frFR', 'Inutile de faire tant d\’histoires pour ça.', '', 28153),
(144177, 'frFR', '', 'Les éraflures... Les traces de terre mal nettoyées... Il est tout sauf présentable !', 28153),
(144176, 'frFR', 'Allons, ce n\’est quand même pas si grave, si ?', '', 28153),
(144175, 'frFR', '', 'Attendez !', 28153),
(144174, 'frFR', '$gMon ami:Mon amie;, si vous voulez bien passer à la vitesse supérieure. Voilà qui vous sera sans doute utile.', '', 28153),
(144173, 'frFR', 'Gratifiant ? Madame, à ce rythme-là, on y sera encore l\’an prochain.', '', 28153),
(144172, 'frFR', '', 'Aaah, merveilleux. N\’est-ce pas gratifiant ?', 28153),
(144171, 'frFR', '', 'Surtout, n\’abîmez pas le fossile... Excellent.', 28153),
(144170, 'frFR', '', 'Très bien. Tout en douceur et en délicatesse.', 28153),
(144169, 'frFR', '', 'Attention où vous mettez les pieds, druides ! Cet endroit est un vrai piège à rats !', 28153),
(144168, 'frFR', 'Excellent travail ! Nous devrions pouvoir l\’utiliser contre ces horribles créatures de bois. Mais faites très attention à ne pas en renverser.', '', 28153),
(144167, 'frFR', 'Merci de me l\’avoir ramenée.', '', 28153),
(144166, 'frFR', '', 'RÉUTILISER : Voici le boîtier de l\’engin à injection. Veuillez l\’installer, s\’il vous plaît.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144165, 'frFR', '', 'Salut, papa !', 28153),
(144164, 'frFR', 'Penny ! Oh, mon petit ange !', '', 28153),
(144163, 'frFR', 'Votre victoire à la scierie n\’est que temporaire ! Nous ne tarderons pas à la reprendre !', '', 28153),
(144162, 'frFR', 'Allons trouver ton papa.', 'Allons trouver ton papa.', 28153),
(144161, 'frFR', '', 'Salut ! C\’est quoi, votre nom ?', 28153),
(144160, 'frFR', 'Vous n\’avez pas conscience du danger que vous courez ?', 'Vous n\’avez pas conscience du danger que vous courez ?', 28153),
(144159, 'frFR', 'Vous ne pouvez pas tous nous arrêter !', 'Vous ne pouvez pas tous nous arrêter !', 28153),
(144158, 'frFR', 'Vous n\’arriverez jamais à tous nous trouver !', 'Vous n\’arriverez jamais à tous nous trouver !', 28153),
(144157, 'frFR', 'Ma position est compromise !', 'Ma position est compromise !', 28153),
(144156, 'frFR', 'Regardez ! Ils ont même un de nos tambours !\n\nQui a dit que les Gobelins avaient pas de culture ?', '', 28153),
(144153, 'frFR', 'Ensuite, il nous faut quelques gouttes de sève instable. Surtout, n\’agitez pas trop la fiole !', '', 28153),
(144152, 'frFR', 'Ajoutez du soufre. Attention aux vapeurs !', '', 28153),
(144151, 'frFR', 'À présent, ajoutez de l\’âtreflore avec précaution.', '', 28153),
(144150, 'frFR', 'Il faut saupoudrer de salpêtre pour lui donner un peu de piquant !', '', 28153),
(144148, 'frFR', 'Krag\’wa fait un signe de tête à votre petit compagnon.', '', 28153),
(144147, 'frFR', 'Krag\’wa et le jeune crogg semblent communiquer.', '', 28153),
(144146, 'frFR', 'Non ! Je retournerai jamais dans cette cellule ! JAMAIS !', '', 28153),
(144145, 'frFR', '', 'Défendez le sanctuaire ! On peut pas se permettre de le perdre.', 28153),
(144144, 'frFR', 'Parfait. Je vous dirai ce qu\’il faut ajouter au chaudron. Surtout, suivez mes instructions à la lettre ou le résultat final risque d\’être… explosif.', '', 28153),
(144142, 'frFR', 'Au revoir, Penny !', '', 28153),
(144141, 'frFR', '', 'Ouaip ! À plus, Joe !', 28153),
(144140, 'frFR', '', 'Salut, Joe !', 28153),
(144139, 'frFR', 'Tiens, salut, Penny. Tu vas voir ton papa ?', '', 28153),
(144138, 'frFR', 'Le monde entier est tombé sur la tête, ma parole !', '', 28153),
(144137, 'frFR', '', 'J\’ai besoin de soins !', 28153),
(144136, 'frFR', '', 'Inclinez-vous devant les éléments !', 28153),
(144135, 'frFR', '$n, je ne peux pas défaire ce qui a été fait. Il sera entre de bonnes mains avec vous. Gardez-le. Protégez-le.', '', 28153),
(144134, 'frFR', 'Je vois.', '', 28153),
(144133, 'frFR', 'Approche, mon petit.', '', 28153),
(144132, 'frFR', 'Cauchemar...', '', 28153),
(144131, 'frFR', 'La lune... elle se lève...', '', 28153),
(144130, 'frFR', 'Des rivages lointains...', '', 28153),
(144129, 'frFR', 'Ne mélangez pas... le chaudron...', '', 28153),
(144128, 'frFR', 'Deux autres verres... et votre plus gros piment...', '', 28153),
(144127, 'frFR', 'La montagne centrale... elle s\’effondre...', '', 28153),
(144126, 'frFR', 'Encore dix minutes...', '', 28153),
(144125, 'frFR', 'Pas encore...', '', 28153),
(144124, 'frFR', 'Fugace grogne comme pour protéger son maître.', '', 28153),
(144123, 'frFR', 'Affrontez votre mort !', 'Affrontez votre mort !', 28153),
(144122, 'frFR', 'Voyez la certitude… de votre mort…', '', 28153),
(144121, 'frFR', 'Pas de victoire… pour vous… Que la mort…', '', 28153),
(144120, 'frFR', 'Quelconque… face au… Vide…', '', 28153),
(144119, 'frFR', 'Vous… n\’avez rien… gagné…', '', 28153),
(144118, 'frFR', 'Le maître… s\’agite…', '', 28153),
(144117, 'frFR', 'Le Vide… recouvre tout…', '', 28153),
(144116, 'frFR', 'Futile… Tout ne sera… que ténèbres…', '', 28153),
(144115, 'frFR', 'On repêchera votre cadavre dans le port !', 'On repêchera votre cadavre dans le port !', 28153),
(144114, 'frFR', 'Kul Tiras n\’a pas besoin de l\’Alliance !', 'Kul Tiras n\’a pas besoin de l\’Alliance !', 28153),
(144113, 'frFR', 'Je vais vous jeter par-dessus bord !', 'Je vais vous jeter par-dessus bord !', 28153),
(144112, 'frFR', '<File d\’attente pour la bataille de Stromgarde>', '<File d\’attente pour la bataille de Stromgarde>', 28153),
(144111, 'frFR', 'Depuis cette table, vous pouvez accéder à la file d\’attente des fronts de guerre.', '', 28153),
(144110, 'frFR', 'Katherine veut notre mort à tous !', 'Katherine veut notre mort à tous !', 28153),
(144109, 'frFR', 'Azeroth est à nous.', '', 28153),
(144108, 'frFR', 'L\’empire renaîtra !', '', 28153),
(144107, 'frFR', 'Trouvez-les !', '', 28153),
(144106, 'frFR', 'Tous disparaîtront.', '', 28153),
(144105, 'frFR', 'Tous mourront.', '', 28153),
(144104, 'frFR', 'Pas d\’espoir… pas de vie.', '', 28153),
(144103, 'frFR', 'Tout sera consumé.', '', 28153),
(144102, 'frFR', 'Tout ne sera plus qu\’ombre.', '', 28153),
(144101, 'frFR', 'Le Vide consume tout.', '', 28153),
(144100, 'frFR', '', 'Druides de la Griffe, À L\’ATTAQUE !', 28153),
(144099, 'frFR', '<siffle>', '', 28153),
(144097, 'frFR', '', 'On passe au plan B…', 28153),
(144096, 'frFR', 'J\’ai l\’information. Il nous reste plus qu\’à sortir d\’ici !', '', 28153),
(144095, 'frFR', '', 'On a été repérés !', 28153),
(144094, 'frFR', 'S-s-s-s-*krzzzz* Sang d\’Azeroth détecté. Formulation de demande : installation du n-n-n-n-*krzzzz* noyau manquant.', '', 28153),
(144093, 'frFR', 'Pouah, c\’est dégueu !', '', 28153),
(144092, 'frFR', 'Jabari, t\’as la mémoire d\’un elekk et l\’esprit de Gonk.', '', 28153),
(144091, 'frFR', 'Bien sûr, quelques épices et un poison mortel, c\’est rigoureusement la même chose…', '', 28153),
(144090, 'frFR', 'Je n\’ai pas besoin qu\’on me pouponne, Jabari ! J\’ai survécu au chili de Haw\’li, je te ferai dire !', '', 28153),
(144089, 'frFR', 'Tais-toi. On dirait un brutosaure enroué.', '', 28153),
(144088, 'frFR', 'Silence, mon frère. Prends ça.', '', 28153),
(144087, 'frFR', 'Lâche-moi la grappe !', '', 28153),
(144086, 'frFR', 'C\’est ça ! Voyons pour le reste…', '', 28153),
(144085, 'frFR', 'Vous ne débutez pas en alchimie, ça se voit !', '', 28153),
(144084, 'frFR', 'Parfait ! À présent, il nous faut…', '', 28153),
(144082, 'frFR', 'Le canon est chargé, mais la première détonation trahira notre présence ici.$b$bAlors ? On y va ?', '', 28153),
(144081, 'frFR', 'Ils finiront tôt ou tard par venir voir ici…', '', 28153),
(144080, 'frFR', '', 'Allez, on y va !', 28153),
(144079, 'frFR', '', 'Attendez ! Il faut qu\’on se tienne la main !', 28153),
(144078, 'frFR', 'Portvaillant tombera !', 'Portvaillant tombera !', 28153),
(144077, 'frFR', 'Ma mort n\’inversera pas le courant des marées.', 'Ma mort n\’inversera pas le courant des marées.', 28153),
(144076, 'frFR', 'Vous allez le regretter !', 'Vous allez le regretter !', 28153),
(144075, 'frFR', 'Vous n\’avez pas votre place ici, $gétranger:étrangère; !', 'Vous n\’avez pas votre place ici, $gétranger:étrangère; !', 28153),
(144074, 'frFR', 'Boralus nous appartient !', 'Boralus nous appartient !', 28153),
(144073, 'frFR', '', 'Les troupes de Zul, elles doivent être nombreuses entre ici et Atal\’Dazar. Il faut qu\’on leur règle leur compte.', 28153),
(144072, 'frFR', 'Fichus Elfes...', 'Fichus Elfes...', 28153),
(144071, 'frFR', 'Le massacreur rastali crache au sol.', 'La massacreuse rastali soupire.', 28153),
(144070, 'frFR', 'Évidemment ! Il est délicieusement primitif. Bon, j\’y suis. 3... 2... 1...', '', 28153),
(144069, 'frFR', '', 'Débrouille-toi pour avoir ce gros temple tout moche en arrière-plan.', 28153),
(144068, 'frFR', '', 'Tous nos amis de Lune-d\’Argent seront verts de jalousie quand ils verront cette photo.', 28153),
(144067, 'frFR', 'Mon épreuve terminée, je conclus mon histoire et rejoignis le royaume matériel. »', 'Mon épreuve terminée, je conclus mon histoire et rejoignis le royaume matériel. »', 28153),
(144066, 'frFR', 'Son regard croisa le mien et plongea dans mon esprit, l\’abreuvant du savoir nécessaire pour l\’invoquer.', 'Son regard croisa le mien et plongea dans mon esprit, l\’abreuvant du savoir nécessaire pour l\’invoquer.', 28153),
(144065, 'frFR', 'Elle poussa un cri à sa venue au monde.', 'Elle poussa un cri à sa venue au monde.', 28153),
(144064, 'frFR', 'Une fois le rituel terminé, je vis une créature se matérialiser sous mes yeux.', 'Une fois le rituel terminé, je vis une créature se matérialiser sous mes yeux.', 28153),
(144063, 'frFR', 'Je remarquai quatre runes au sol. L\’encre devait forcément leur être destinée.', 'Je remarquai quatre runes au sol. L\’encre devait forcément leur être destinée.', 28153),
(144062, 'frFR', 'Une fois l\’encre recueillie en quantité suffisante, une étrange énergie m\’attira vers l\’extrémité de l\’une des salles.', 'Une fois l\’encre recueillie en quantité suffisante, une étrange énergie m\’attira vers l\’extrémité de l\’une des salles.', 28153),
(144061, 'frFR', 'Un squelette jonchant le sol me rappela ma propre mortalité et je songeai à ceux qui avaient peut-être échoué avant moi.', 'Un squelette jonchant le sol me rappela ma propre mortalité et je songeai à ceux qui avaient peut-être échoué avant moi.', 28153),
(144060, 'frFR', 'Ces créatures visqueuses commençaient par me causer bien des désagréments.', 'Ces créatures visqueuses commençaient par me causer bien des désagréments.', 28153),
(144059, 'frFR', 'Les vases étaient la clé de l\’énigme. Jusque-là, je n\’avais aucune peine à trouver ce dont j\’avais besoin.', 'Les vases étaient la clé de l\’énigme. Jusque-là, je n\’avais aucune peine à trouver ce dont j\’avais besoin.', 28153),
(144058, 'frFR', 'Je devinai ce qu\’il me restait à faire et décidai de poursuivre.', 'Je devinai ce qu\’il me restait à faire et décidai de poursuivre.', 28153),
(144057, 'frFR', 'Prenez garde au flot, recueillez l\’incarnat et votre pourfendeur assoiffé de sang enfin se lèvera. »', 'Prenez garde au flot, recueillez l\’incarnat et votre pourfendeur assoiffé de sang enfin se lèvera. »', 28153),
(144056, 'frFR', 'Ce qui coule de la plume et des veines s\’entremêle ici même.', 'Ce qui coule de la plume et des veines s\’entremêle ici même.', 28153),
(144055, 'frFR', 'Je me réveillai dans une chambre, une voix étrange récitant un poème dans mon esprit :', 'Je me réveillai dans une chambre, une voix étrange récitant un poème dans mon esprit :', 28153),
(144054, 'frFR', 'Vous écrivez la première ligne du livre : « Alors que ma plume se posait sur la page, je sentis quelque chose m\’attirer. »', 'Vous écrivez la première ligne du livre : « Alors que ma plume se posait sur la page, je sentis quelque chose m\’attirer. »', 28153),
(144053, 'frFR', 'Vous feuilletez le livre entier et toutes les pages sont vierges. Vous jetez un regard agacé à Kronah et vous vous demandez si elle sait comment réussir cette épreuve.', '', 28153),
(144052, 'frFR', 'J\’ai hâte de lire les évènements que vous allez vivre.', '', 28153),
(144051, 'frFR', 'Sortez une plume et écrivez les premières lignes. Le livre se chargera du reste, ne vous en faites pas.', '', 28153),
(144050, 'frFR', 'C\’est simple, très $gcher:chère;. Il vous suffit d\’écrire votre propre histoire dans ce livre.', '', 28153),
(144049, 'frFR', 'Oh non, v\’là que ça recommence…', '', 28153),
(144048, 'frFR', 'J\’aimerais échanger quelques-uns de mes piquants.', 'J\’aimerais échanger quelques-uns de mes piquants.', 28153),
(144047, 'frFR', 'Mince alors, ça ne s\’est pas passé du tout comme prévu. Refaisons un essai !', '', 28153),
(144046, 'frFR', 'L\’alchimie est une science exacte ! Essayez de faire un peu plus attention.', '', 28153),
(144045, 'frFR', 'Non, ce n\’est pas ça. Il faut tout recommencer !', '', 28153),
(144044, 'frFR', 'Le mélange a pris feu ! Il faut recommencer !', 'Le mélange a pris feu ! Il faut recommencer !', 28153),
(144043, 'frFR', 'Zul a prédit ce jour. En cherchant à changer le cours du destin, vous ne faites que confirmer sa réalité !', '', 28153),
(144042, 'frFR', 'Zul… ne m\’avait pas dit… que je perdrais…', '', 28153),
(144041, 'frFR', 'Vous n\’atteindrez jamais le précipice à temps !', '', 28153),
(144040, 'frFR', 'Je suis prêt !', 'Je suis prête !', 28153),
(144039, 'frFR', 'Pas si vite ! Je me sens mieux maintenant ! Argh…', 'Pas si vite ! Je me sens mieux maintenant ! Argh…', 28153),
(144038, 'frFR', 'Quel imbécile j\’ai été !', 'Quel imbécile j\’ai été !', 28153),
(144037, 'frFR', 'Je ne l\’entends plus chanter…', 'Je ne l\’entends plus chanter…', 28153),
(144036, 'frFR', 'Elle ne vous aimera jamais !', 'Elle ne vous aimera jamais !', 28153),
(144035, 'frFR', 'Nooon, mon amour !', 'Nooon, mon amour !', 28153),
(144034, 'frFR', 'Ah, les affres de l\’amour !', 'Ah, les affres de l\’amour !', 28153),
(144033, 'frFR', 'Ça valait le coup !', 'Ça valait le coup !', 28153),
(144032, 'frFR', 'Si douce est la tristesse de nos adieux.', 'Si douce est la tristesse de nos adieux.', 28153),
(144031, 'frFR', 'Regarde, ma chérie. Je vais lui coller sa raclée.', 'Regarde, ma chérie. Je vais lui coller sa raclée.', 28153),
(144030, 'frFR', 'On reluque pas impunément ma dulcinée !', 'On reluque pas impunément ma dulcinée !', 28153),
(144029, 'frFR', 'L\’amour est plus fort que tout !', 'L\’amour est plus fort que tout !', 28153),
(144028, 'frFR', 'Elle est à moi ! À MOI !', 'Elle est à moi ! À MOI !', 28153),
(144027, 'frFR', 'Merci beaucoup. Vous avez sauvé ce village et m\’avez insufflé le courage qui me manquait. Alby, Therold, assurez-vous que le Trident se relève. Je vous recontacterai bientôt.', '', 28153),
(144026, 'frFR', 'Bas les pattes !', 'Bas les pattes !', 28153),
(144025, 'frFR', 'Zul cherche à réveiller Dazar ? Je ne resterai pas là à ne rien faire pendant que ce « prophète » de malheur profane les ossements du premier roi. En route, rejoignez-nous près des portes sud.', '', 28153),
(144024, 'frFR', 'Je dois retourner chez moi. Mon oncle et les eaugures de la vallée Chantorage auront peut-être plus d\’informations sur cette magie noire.', '', 28153),
(144023, 'frFR', 'Austergarde… Il a toujours été un rusé renard, mais j\’ignorais qu\’il s\’adonnait à ce genre de magie… Qu\’il cherchait à s\’approprier le pouvoir de tourmenter ainsi les mers.', '', 28153),
(144022, 'frFR', 'Arrière, pas touche à ma promise !', 'Arrière, pas touche à ma promise !', 28153),
(144021, 'frFR', '', 'Oui ! Voilà notre chance. Volez, mes enfants ! Massacrez ces hérétiques !', 28153),
(144020, 'frFR', 'Le Trident est sauf, mais… je ne suis toujours pas rassuré. Austergarde, aussi intelligent qu\’il puisse être, n\’avait jamais eu un tel pouvoir.', '', 28153),
(144019, 'frFR', 'Je te protégerai, mon amour !', 'Je te protégerai, mon amour !', 28153),
(144018, 'frFR', 'Je l\’aime tellement !', 'Je l\’aime tellement !', 28153),
(144017, 'frFR', 'LA MAIN DU DESTIN EST RASSASIÉE. JE VAIS VOUS RAMENER EN SÉCURITÉ. LE DESTIN FAIT PARFOIS PREUVE DE CLÉMENCE.', '', 28153),
(144016, 'frFR', 'Quittez notre ville sur-le-champ, $p ! Vous allez nous attirer malheur !', '', 28153),
(144015, 'frFR', 'Place à $p, $Unotre invité béni:notre invitée bénie; des Loas !', '', 28153),
(144013, 'frFR', '', 'Le présage est ambigu... Vous allez affronter des défis impossibles, mais vous en viendrez à bout. Les Loas, ils ne vous abandonneront pas.', 28153),
(144012, 'frFR', '', 'Mauvais présages, j\’en ai peur… Votre avenir, ce n\’est rien que des ennuis. Désolée.', 28153),
(144011, 'frFR', '', 'Évitez l\’eau aujourd\’hui. Elle est signe de danger.', 28153),
(144010, 'frFR', '', 'Vide ? Non... Vous devez changer ça.', 28153),
(144009, 'frFR', '', 'Une rude épreuve et une trahison vous attendent. Choisissez bien vos compagnons aujourd\’hui.', 28153),
(144008, 'frFR', '', 'Ce présage, je ne l\’avais pas entendu depuis très, très longtemps... Votre destin, vous devez le changer.', 28153),
(144007, 'frFR', '', 'Prenez aucun raccourci pour atteindre vos buts aujourd\’hui. Tout compromis ou imprudence se solderait par une fin terrible.', 28153),
(144006, 'frFR', '', 'L\’autre côté nous met en garde. Faites attention.', 28153),
(144005, 'frFR', '', 'Méfiez-vous de la cité d\’or. Le jeu, il n\’en vaut pas la chandelle.', 28153),
(144004, 'frFR', '', 'Vous allez devoir avancer vers l\’avenir à l\’aveuglette, j\’en ai peur.', 28153),
(144003, 'frFR', '', 'Gral, il est happé vers les profondeurs par une main invisible.', 28153),
(144002, 'frFR', '', 'Le nid de Shadra est vide.', 28153),
(144001, 'frFR', '', 'Torcali dort.', 28153),
(144000, 'frFR', '', 'Rezan, il s\’effondre au sol... mort.', 28153),
(143999, 'frFR', '', 'Bwonsamdi propose un marché d\’un air narquois.', 28153),
(143998, 'frFR', '', 'Krag\’wa, il avale un troupeau de navrecornes bleus.', 28153),
(143997, 'frFR', '', 'Gonk traverse seul un fleuve d\’or à la nage.', 28153),
(143996, 'frFR', '', 'Pa\’ku, elle ferme les yeux dans les ténèbres.', 28153),
(143995, 'frFR', '', 'Des présages aussi malvenus, ça ne court pas les rues. Faites attention.', 28153),
(143994, 'frFR', '', 'Un sombre présage pour nous tous. Qu\’avez-vous apporté sur nos côtes ?', 28153),
(143993, 'frFR', '', 'Vous gâchez votre potentiel. Sachez sauter sur l\’occasion quand elle se présente ou vous mourrez $Uoublié:oubliée; de tous.', 28153),
(143992, 'frFR', '', 'La division entre vous et vos alliés, elle nous menace tous. Vous allez devoir unir Zandalar.', 28153),
(143991, 'frFR', '', 'Un présage malvenu. Mais avec de la force et de la détermination, vous pourrez le surmonter.', 28153),
(143990, 'frFR', '', 'Des chefs divisés, ça ne sert à rien. Coopérez avec vos rivaux, ou il faudra subir les conséquences.', 28153),
(143989, 'frFR', '', 'Les ténèbres qui se lèvent, elles vont engloutir jusqu\’aux plus forts d\’entre nous. Et vous n\’y couperez pas.', 28153),
(143988, 'frFR', '', 'Un sombre présage pour nous tous...', 28153),
(143987, 'frFR', '', 'La mort d\’une nouvelle connaissance.', 28153),
(143986, 'frFR', '', 'Un soleil qui se couche sur le sombre marais de Nazmir.', 28153),
(143985, 'frFR', '', 'Un vase fêlé d\’où s\’écoule du vin.', 28153),
(143984, 'frFR', '', 'Deux prêtres qui s\’entretuent.', 28153),
(143983, 'frFR', '', 'Un vaisseau humain débarquant sur nos côtes...', 28153),
(143982, 'frFR', '', 'Un trône brisé fait de feu et de glace...', 28153),
(143981, 'frFR', '', 'Un brutosaure qui se noie dans le sang.', 28153),
(143980, 'frFR', '', 'Une rivière de sang avec des cadavres qui remontent son cours...', 28153),
(143979, 'frFR', 'Viens, Gratouille. On y va !', 'Viens, Gratouille. On y va !', 28153),
(143978, 'frFR', 'Génial ! Merci !', 'Génial ! Merci !', 28153),
(143977, 'frFR', 'Ouah. Ça soulage !', '', 28153),
(143976, 'frFR', 'Moi, je voulais qu\’on parte, mais non, ils en avaient pas assez vu… J\’ai eu chaud, très chaud… Sans vous, je ne serais même plus de ce monde.', '', 28153),
(143975, 'frFR', '', 'Utilisez votre vectrice pour nous parler, Zetoa !', 28153),
(143974, 'frFR', '', 'Utilisez votre vectrice pour nous parler, Iluna !', 28153),
(143973, 'frFR', '', 'Tout est prêt. Incarnez-vous dans mes porteuses de vie et révélez-nous l\’avenir.', 28153),
(143972, 'frFR', '', 'Esprits des morts, esprits des Loas, esprits égarés et troublés, écoutez-moi !', 28153),
(143971, 'frFR', 'Je retourne aux lignes de défense !', 'Je retourne aux lignes de défense !', 28153),
(143970, 'frFR', 'Je ne pouvais plus bouger !', 'Je ne pouvais plus bouger !', 28153),
(143969, 'frFR', 'J\’ai cru que j\’allais être emmené dans la forêt !', 'J\’ai cru que j\’allais être emmenée dans la forêt !', 28153),
(143968, 'frFR', 'Ils en ont déjà emporté dans la forêt !', 'Ils en ont déjà emporté dans la forêt !', 28153),
(143967, 'frFR', 'Je retourne à la barricade !', 'Je retourne à la barricade !', 28153),
(143966, 'frFR', '', 'Ce ne sont que de bons présages pour vous, tout ça… N\’hésitez pas à faire preuve d\’audace aujourd\’hui !', 28153),
(143965, 'frFR', 'J\’ai bien cru que mon heure avait sonné !', 'J\’ai bien cru que mon heure avait sonné !', 28153),
(143964, 'frFR', 'Merci !', 'Merci !', 28153),
(143963, 'frFR', '', 'Une ruée...', 28153),
(143962, 'frFR', '', 'Un présage léger... Ne laissez pas l\’anxiété vous submerger. La bonne humeur et l\’humour, voilà les clés de votre succès.', 28153),
(143961, 'frFR', 'La pourriture prolifère !', '', 28153),
(143960, 'frFR', 'Tout finit… par pourrir…', '', 28153),
(143959, 'frFR', '', 'La bénédiction habituelle de Shadra, avec un ajout inattendu. Ça reste un présage positif, mais je ne comprends pas totalement.', 28153),
(143958, 'frFR', '', 'La bénédiction du défenseur... Vous sauverez de nombreuses vies, mais peut-être au prix de la vôtre.', 28153),
(143957, 'frFR', '', 'Le Loa du roi, c\’est un présage rare et puissant. Vous allez anéantir les ennemis du roi.', 28153),
(143956, 'frFR', '', 'Un bon présage qui annonce une longue vie et une mort sans douleur.', 28153),
(143955, 'frFR', 'Vous servirez d\’engrais !', '', 28153),
(143954, 'frFR', 'Flétrissez !', '', 28153),
(143953, 'frFR', 'La corruption se répand !', '', 28153),
(143952, 'frFR', '', 'C\’est un bon présage, pour peu que vous ne soyez pas originaire de cette île.', 28153),
(143951, 'frFR', 'Proliférez !', '', 28153),
(143950, 'frFR', '', 'Vous aurez toujours des alliés qui se battront à vos côtés. Gonk, il ne vous abandonnera pas quand vous aurez besoin d\’aide.', 28153),
(143949, 'frFR', '', 'Pa\’ku, elle vous guidera dans votre voyage et écartera les ennemis...', 28153),
(143948, 'frFR', 'Un terreau fertile.', '', 28153),
(143947, 'frFR', '', 'Gral, il saute par-dessus la flotte royale...', 28153),
(143946, 'frFR', '', 'L\’œuf de Shadra éclot. D\’innombrables yeux en jaillissent...', 28153),
(143945, 'frFR', '', 'Torcali se dresse seul au sommet d\’une montagne...', 28153),
(143944, 'frFR', '', 'Rezan frappe le sol et les Trolls de sang se dispersent...', 28153),
(143943, 'frFR', '', 'Bwonsamdi détourne le regard...', 28153),
(143942, 'frFR', '', 'Krag\’wa, il avale une île...', 28153),
(143941, 'frFR', 'Pourrissez !', '', 28153),
(143940, 'frFR', '', 'Gonk court aux côtés de sa meute...', 28153),
(143939, 'frFR', 'L\’heure de la récolte est venue !', '', 28153),
(143938, 'frFR', 'La putréfaction doit se propager !', '', 28153),
(143937, 'frFR', '', 'C\’est presque toujours un bon présage, mais tout dépendra de votre camarade...', 28153),
(143936, 'frFR', '', 'Un bon présage pour nous tous. Votre présence, elle devrait être la bienvenue en Zandalar.', 28153),
(143935, 'frFR', '', 'Contrairement à ce que beaucoup pensent, vous n\’avez pas encore atteint votre plein potentiel. Votre puissance va encore croître et vous allez dépasser toutes les attentes.', 28153),
(143934, 'frFR', '', 'Un... étonnant présage pour $gun étranger:une étrangère;. Qu\’est-ce que ça peut bien vouloir dire ?', 28153),
(143933, 'frFR', '', 'Un puissant présage ! C\’est bon pour vous, ça...', 28153),
(143932, 'frFR', '', 'Un bon présage d\’expansion et de croissance pour notre peuple. Intéressant que ce soit vous qui le receviez...', 28153),
(143931, 'frFR', '', 'Un bon présage de prospérité et d\’héritage.', 28153),
(143930, 'frFR', '', 'Un bon présage de force, de puissance et de réussite.', 28153),
(143929, 'frFR', '', 'La résurrection d\’un vieil ami...', 28153),
(143928, 'frFR', '', 'Un soleil qui se lève sur une eau dorée...', 28153),
(143927, 'frFR', '', 'Un gros œuf, agité de violents tremblements, mais qui refuse de casser...', 28153),
(143926, 'frFR', '', 'Toutes les tribus trolles, unies sous la bannière zandalari...', 28153),
(143925, 'frFR', '', 'Une tête d\’Elfe tranchée...', 28153),
(143924, 'frFR', '', 'Des eaux ancestrales et dormantes depuis des générations...', 28153),
(143923, 'frFR', '', 'Des masques d\’or...', 28153),
(143922, 'frFR', '', 'L\’ombre de Pa\’ku glisse sur un chemin de pierre...', 28153),
(143921, 'frFR', '', 'Très bien. Voyons ce que les esprits, ils ont à vous raconter...', 28153),
(143920, 'frFR', '', 'Voulez-vous vraiment savoir, $p ?\n\nLes prédictions, elles ne parlent pas toutes d\’exploits et de fins heureuses...', 28153),
(143919, 'frFR', 'Je n\’ai pas peur. Dites-moi ce que l\’avenir me réserve.', 'Je n\’ai pas peur. Dites-moi ce que l\’avenir me réserve.', 28153),
(143918, 'frFR', 'Que me réserve l\’avenir ?', 'Que me réserve l\’avenir ?', 28153),
(143917, 'frFR', '', 'Écoutez-moi, ô esprits perdus des temps anciens. Remplissez mes calices et révélez-nous ce que l\’avenir nous réserve.', 28153),
(143916, 'frFR', 'Peu importe… Nous sommes partout… sous vos pieds.', '', 28153),
(143915, 'frFR', 'Votre faiblesse… renforce notre tribu…', 'Votre faiblesse… renforce notre tribu…', 28153),
(143914, 'frFR', '', 'Bienvenue dans le Salon des Esprits perdus, $p.\n\nVous n\’êtes pas en avance. Je commençais à craindre que vous n\’arriveriez pas jusqu\’ici.\n\nBien, dites à madame Konawla ce qu\’elle peut faire pour vous aujourd\’hui.', 28153),
(143913, 'frFR', 'Je meurs avec honneur…', 'Je meurs avec honneur…', 28153),
(143912, 'frFR', 'Nos épines… recouvriront ces terres…', 'Nos épines… recouvriront ces terres…', 28153),
(143911, 'frFR', 'Nul ne peut… affaiblir les Roncedos…', 'Nul ne peut… affaiblir les Roncedos…', 28153),
(143910, 'frFR', 'Mon combat… prend fin.', 'Mon combat… prend fin.', 28153),
(143909, 'frFR', 'Votre mort servira mon prestige.', 'Votre mort servira mon prestige.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143908, 'frFR', 'La terre se gorgera de votre sang.', 'La terre se gorgera de votre sang.', 28153),
(143907, 'frFR', 'On ne recule pas, on ne se rend pas !', 'On ne recule pas, on ne se rend pas !', 28153),
(143906, 'frFR', 'Pourquoi le Compendium de l\’effusion de sang est-il vierge ?', 'Pourquoi le Compendium de l\’effusion de sang est-il vierge ?', 28153),
(143905, 'frFR', 'Vous ferez un excellent repas pour nos sangliers.', 'Vous ferez un excellent repas pour nos sangliers.', 28153),
(143904, 'frFR', 'Personne ne nous arrête !', 'Personne ne nous arrête !', 28153),
(143903, 'frFR', 'Ces terres sont à nous !', 'Ces terres sont à nous !', 28153),
(143902, 'frFR', 'Commencer à remplir le livre.', 'Commencer à remplir le livre.', 28153),
(143901, 'frFR', 'Feuilleter le livre entier.', 'Feuilleter le livre entier.', 28153),
(143900, 'frFR', 'Graaaatouille ! Tu es toujours là-haut ? Miaule deux fois si tu m\’entends !', 'Graaaatouille ! T\’es toujours là-haut ? Miaule deux fois si tu m\’entends !', 28153),
(143899, 'frFR', 'Les pages suivantes semblent également vierges.', '', 28153),
(143898, 'frFR', 'On va te descendre de là, Gratouille ! Sois sage !', 'On va te descendre de là, Gratouille ! Sois sage !', 28153),
(143897, 'frFR', 'Tout va bien se passer, Gratouille ! Ne bouge pas !', 'Tout va bien se passer, Gratouille ! Bouge pas !', 28153),
(143896, 'frFR', 'Tourner quelques pages supplémentaires.', 'Tourner quelques pages supplémentaires.', 28153),
(143895, 'frFR', 'Les premières pages du livre semblent vierges.', '', 28153),
(143894, 'frFR', 'Miaaaaouu.', '', 28153),
(143893, 'frFR', 'Tiens bon, Gratouille ! Les secours sont en route !', 'Tiens bon, Gratouille ! Les secours sont en route !', 28153),
(143892, 'frFR', 'Descends, Gratouille, descends ! C\’est dangereux là-haut !', 'Descends, Gratouille ! Descends ! C\’est dangereux là-haut !', 28153),
(143891, 'frFR', 'Descends de là, Gratouille ! Je te rattrape !', 'Descends de là, Gratouille ! Je te rattrape !', 28153),
(143890, 'frFR', 'Graaaaatouuuuille ! Descends !', 'Graaaaatouuuuille ! Descends !', 28153),
(143889, 'frFR', '', 'Mes chéris, ils vont vous becqueter, $r !', 28153),
(143888, 'frFR', 'Venez par ici.', '', 28153),
(143887, 'frFR', 'Par ici !', '', 28153),
(143886, 'frFR', 'Attention !', '', 28153),
(143885, 'frFR', 'Par ici.', '', 28153),
(143884, 'frFR', 'Par ici.', '', 28153),
(143883, 'frFR', 'Attention !', '', 28153),
(143882, 'frFR', 'Par ici !', '', 28153),
(143881, 'frFR', 'Eh, vous. Par ici.', '', 28153),
(143879, 'frFR', 'Le feu purgera !', '', 28153),
(143876, 'frFR', 'Ainsi soit-il.', '', 28153),
(143875, 'frFR', 'Du sang ! Du sang ! Du sang !', '', 28153),
(143874, 'frFR', 'Zuldazar disparaîtra !', '', 28153),
(143873, 'frFR', 'De la viande saignante !', '', 28153),
(143872, 'frFR', 'Du sang, je le veux !', '', 28153),
(143871, 'frFR', 'Ces os, ils vont bien nous servir !', '', 28153),
(143870, 'frFR', 'Du sang pour G\’huun !', '', 28153),
(143869, 'frFR', 'Personne n\’échappe au Dieu du sang !', '', 28153),
(143868, 'frFR', 'Guzincha !', '', 28153),
(143867, 'frFR', 'Kachago !', '', 28153),
(143865, 'frFR', 'Vous n\’avez pas bien lu les petites lignes, $ggamin:gamine; ?\n\nPied-Plume ne rembourse personne. Inutile de pleurnicher, ça vaut aussi pour vous.\n\nAllez, oubliez ça avec... une chute en douceur de Pied-Plume !', '', 28153),
(143864, 'frFR', 'Une chute en douceur de Pied-Plume, s\’il vous plaît !', 'Une chute en douceur de Pied-Plume, s\’il vous plaît !', 28153),
(143863, 'frFR', 'Je veux être remboursé.', 'Je veux être remboursée.', 28153),
(143862, 'frFR', 'Content de vous revoir, $p.\n\nJe parie que vous êtes $gravi:ravie; d\’avoir rejoint la famille Pied-Plume, pas vrai ?\n\nVotre statut de membre vous donne droit à un nombre illimité de chutes en douceur depuis le sommet de cette super ziggourat. Faites-moi signe quand il vous en faudra une nouvelle !\n\nEt souvenez-vous : aucun remboursement !', '', 28153),
(143861, 'frFR', 'Rejoignez dès aujourd\’hui la famille Pied-Plume !\n\nProfitez d\’un nombre illimité de chutes en douceur depuis le sommet de cette ziggourat en échange d\’une somme modique. Survie garantie !\n\nAucun remboursement ne sera accordé.', '', 28153),
(143860, 'frFR', 'Les vents d\’ici soufflent plus fort que ceux de Haut-Roc. Notre décision de rejoindre la Horde est déjà payante.', '', 28153),
(143859, 'frFR', 'Retournez à la tempête et goûtez à la paix. Franchissez ce sanctuaire et donnez-nous votre force.', '', 28153),
(143858, 'frFR', '', 'Quelle cité extraordinaire ! Je n\’imaginais pas que découvrir le monde serait aussi amusant !', 28153),
(143857, 'frFR', 'Entendez notre appel, vous qui avez succombé. Vos actes inqualifiables vous sont tous pardonnés.', '', 28153),
(143856, 'frFR', 'Quand vous le voudrez, libérez les âmes contenues dans la cloche.', '', 28153),
(143855, 'frFR', 'Je regrette, Rosaline, mais la chasse devra attendre. Nous avons plus urgent à régler aujourd\’hui.', '', 28153),
(143854, 'frFR', '', 'Hé ! Therold ! Assez lambiné. Nous avons besoin de ta bénédiction pour partir à la chasse !', 28153),
(143853, 'frFR', 'Revenez vite, $p !', '', 28153),
(143852, 'frFR', 'Dix points à chaque fois que vous cracherez sur un Troll de sang !', '', 28153),
(143851, 'frFR', 'Les chutes en douceur de Pied-Plume ! Parlez-en autour de vous !', '', 28153),
(143850, 'frFR', 'Content de vous revoir, $p. Bonne chute !', '', 28153),
(143849, 'frFR', 'Essayez d\’atterrir sur le brutosaure !', '', 28153),
(143848, 'frFR', 'Essayez de vous poser dans une chute d\’eau !', '', 28153),
(143847, 'frFR', 'Faites attention aux pterreurdactyles !', '', 28153),
(143846, 'frFR', 'Bon voyage, $p.', '', 28153),
(143845, 'frFR', 'Aaaaaaaaaugh !', '', 28153),
(143844, 'frFR', 'Pour l\’Alliance.', '', 28153),
(143843, 'frFR', 'Pour la Horde !', '', 28153),
(143842, 'frFR', 'Stromgarde est tombée. Rendez-vous, Rogers, si vous tenez à la vie.', '', 28153),
(143841, 'frFR', 'Mais oui, il y a… mon marteau !', '', 28153),
(143840, 'frFR', 'Toc-toc, petit Barbe-de-Bronze. Y a quelqu\’un ?', '', 28153),
(143839, 'frFR', 'La Lumière est toujours avec moi. Je ne tomberai pas si facilement !', '', 28153),
(143838, 'frFR', 'Amiral Rogers ! Nous avons pris votre forteresse d\’assaut. Où est donc ce châtiment que vous nous aviez promis, paladin ?', '', 28153),
(143837, 'frFR', 'Ils croient qu\’ils peuvent nous arrêter avec leurs petits chevaux ? Ha ! Montrez-leur de quel bois on se chauffe dans la Horde !', '', 28153),
(143836, 'frFR', 'Le bastion a besoin de renforts. Allez détruire ces chars avant qu\’ils soient trop près !', '', 28153),
(143835, 'frFR', 'Nos défenses sont toujours insuffisantes. Troupes de la Horde, retournez à la base et défendez notre position !', '', 28153),
(143834, 'frFR', 'Très bien. Si c\’est la guerre que vous voulez, vous l\’aurez. Envoyez un bataillon de cavalerie les éliminer !', '', 28153),
(143833, 'frFR', 'Le cercle des Éléments, il est sous le contrôle de la Horde.', '', 28153),
(143832, 'frFR', 'On a pris Grangeneuve. À nous les chevaucheurs de loups !', '', 28153),
(143831, 'frFR', 'L\’armurerie, elle est prête.', '', 28153),
(143830, 'frFR', 'L\’atelier est fini. Nos démolisseurs vont réduire en poussière les murs de l\’Alliance en moins de deux !', '', 28153),
(143829, 'frFR', 'Démolissez les engins de siège !', '', 28153),
(143828, 'frFR', 'Vous avez été prévenus. Préparez-vous à mourir, chiens de la Horde !', '', 28153),
(143827, 'frFR', 'Ces terres, elles appartenaient déjà aux Trolls quand l\’Alliance savait même pas qu\’elles existaient, Turalyon.', '', 28153),
(143826, 'frFR', 'Hmph. On dirait $gun vrai:une vraie;.', '', 28153),
(143825, 'frFR', 'Ces vêtements devront faire l\’affaire pour le moment.', '', 28153),
(143824, 'frFR', 'Pour commencer, y nous faut du bois et du fer, pour construire une base pour la Horde. Il devrait y en avoir plein, tout autour d\’ici.', '', 28153),
(143823, 'frFR', 'Je te le fais pas dire, Muradin.', '', 28153),
(143822, 'frFR', 'Vous récolterez peut-être mieux dans cette tenue.', '', 28153),
(143821, 'frFR', 'Bah ! Étouffe-toi avec ta vindicte, Turalyon !', '', 28153),
(143820, 'frFR', 'Ces terres appartiennent à l\’Alliance ! Ces envahisseurs de la Horde recevront bientôt le châtiment qu\’ils méritent !', '', 28153),
(143819, 'frFR', 'Aujourd\’hui, c\’est à la Horde qu\’elles appartiennent !', '', 28153),
(143818, 'frFR', 'Avant, toutes ces terres, elles appartenaient aux Trolls.', '', 28153),
(143817, 'frFR', 'Ah… Avec plaisir. Vous allez regretter d\’avoir cherché des noises à ce Nain-là.', '', 28153),
(143816, 'frFR', 'Muradin ! Montrez-vous, sale lâche !', '', 28153),
(143815, 'frFR', 'Nos défenses sont toujours insuffisantes. Arrêtez ces chars avant qu\’ils atteignent notre base !', '', 28153),
(143814, 'frFR', 'Moins sale que la tienne, Barbe-de-Bronze !', '', 28153),
(143813, 'frFR', 'Pardonnez-moi, examinatrice.', '', 28153),
(143812, 'frFR', 'C\’est un honneur de vous servir, examinatrice.', '', 28153),
(143811, 'frFR', '', 'Le combat est fini… et nous sommes tous en vie. Ateena va payer pour cette folie !', 28153),
(143810, 'frFR', '', 'Tremblez devant le destructeur de Zuldazar ! Essayez de nous arrêter pour voir… Vous allez souffrir comme jamais !', 28153),
(143809, 'frFR', '', 'Vous êtes si près du but, mais vous allez succomber à la fureur du maître !', 28153),
(143808, 'frFR', 'Travailler pour le Reliquaire, c\’est un vrai sacerdoce...', '', 28153),
(143807, 'frFR', 'Ha, c\’était trop facile ! Montrez-moi de quoi vous êtes capable. On n\’a jamais assez de bois.', '', 28153),
(143806, 'frFR', 'À vos ordres, examinatrice.', '', 28153),
(143805, 'frFR', 'Vos désirs sont des ordres, examinatrice.', '', 28153),
(143804, 'frFR', 'À votre service, examinatrice.', '', 28153),
(143803, 'frFR', '', 'Votre peau, elle fera une enveloppe parfaite pour mon maître !', 28153),
(143802, 'frFR', '', 'Après, c\’est la Horde qui tombera. Vous allez payer pour la mort d\’Hir\’eek ! Vous pouvez pas m\’échapper.', 28153),
(143801, 'frFR', '', 'Zuldazar va tomber… et mon maître, il sera bientôt libre ! Vos petits Loas ne l\’arrêteront pas !', 28153),
(143800, 'frFR', 'Bien sûr, examinatrice.', '', 28153),
(143799, 'frFR', 'J\’arrive tout de suite, examinatrice.', '', 28153),
(143798, 'frFR', '', 'Intéressant... Baeloth, viens jeter un coup d\’œil et dis-moi ce que tu vois.', 28153),
(143797, 'frFR', '', 'Où étais-tu passé, Baeloth ? J\’ai encore des tas de précieuses informations à te dicter.', 28153),
(143796, 'frFR', '', 'Viens vite voir ça, mon cher Baeloth.', 28153),
(143795, 'frFR', '', 'Les fainéants n\’ont pas leur place au sein du Reliquaire, Baeloth.', 28153),
(143794, 'frFR', '', 'Baeloth, ne touche pas aux reliques !', 28153),
(143793, 'frFR', '', 'C\’est prodigieux... Baeloth, viens admirer cette petite merveille !', 28153),
(143792, 'frFR', '', 'Le bouclier d\’Hezrel est activé. Abritez-vous dedans !', 28153),
(143791, 'frFR', '', 'Baeloth, tu rêvasses encore ? Rends-toi un peu utile, à la fin !', 28153),
(143790, 'frFR', '', 'Baeloth, sois un ange et consigne par écrit tout ce que je vais dire.', 28153),
(143789, 'frFR', 'Les Barges ont besoin de matériel pour rester au top ! Mon boulot à moi, c\’est de gérer le ravitaillement et de réparer nos engins !$b$b…$b$bVous n\’imaginez pas le nombre d\’appareils qu\’ils me bousillent chaque jour.$b$bÇa, on ne peut pas dire qu\’ils soient très délicats.', '', 28153),
(143788, 'frFR', '', '$n, puis-je m\’entretenir avec vous ? J\’aurais besoin de votre aide.', 28153),
(143787, 'frFR', '<< An event plays out where me and the laborers walk towards the causeway with cannons. >>', '', 28153),
(143786, 'frFR', 'Trois larrons et un tas d\’os. Trois larrons et tas d\’os. T\’larrons\’ et tas d\’os. T\’laar et tos. T\’laartos. T\’laartos !', '', 28153),
(143785, 'frFR', 'Ah, ils sont tous tombés dans le panneau ! C\’est incroyable qu\’ils aient pu croire que je sois assez simple d\’esprit pour… Attendez, vous m\’écoutiez ? Je, euh… T\’laartos !', '', 28153),
(143784, 'frFR', 'Voilà la liste des choses que T\’laartos n\’aime pas : les serpents, les vilains enfants, les grottes sombres, les serpents… et les petits êtres chétifs qui embêtent T\’laartos.', '', 28153),
(143783, 'frFR', 'Oui, T\’laartos sait lire. Surtout des livres avec peu de mots et plein d\’images… mais ça compte quand même.', '', 28153),
(143782, 'frFR', 'Le petit être chétif n\’essaierait jamais d\’abuser la gentillesse de T\’laartos, hein ?', '', 28153),
(143781, 'frFR', 'T\’laartos a toujours un peu peur des serpents.', '', 28153),
(143780, 'frFR', 'T\’laartos est fier d\’être un Sancteforge !', '', 28153),
(143779, 'frFR', 'Revenez voir T\’laartos quand vous voulez.', '', 28153),
(143778, 'frFR', 'T\’laartos doit se remettre au travail.', '', 28153),
(143777, 'frFR', 'T\’laartos a tant à faire.', '', 28153),
(143776, 'frFR', 'T\’laartos vous reverra bientôt.', '', 28153),
(143775, 'frFR', 'T\’laartos.', '', 28153),
(143774, 'frFR', 'Hâtez-vous, $n. Des vies sont en jeu.', '', 28153),
(143773, 'frFR', 'T\’laartos est prêt !', '', 28153),
(143772, 'frFR', 'La Lumière soit avec vous.', '', 28153),
(143771, 'frFR', 'Un danger ? T\’laartos se moque du danger !', '', 28153),
(143770, 'frFR', 'Le petit être chétif a besoin de l\’aide de T\’laartos ?', '', 28153),
(143769, 'frFR', 'T\’laartos salue le petit être chétif.', '', 28153),
(143768, 'frFR', 'T\’laartos ?', '', 28153),
(143767, 'frFR', 'T\’laartos !', '', 28153),
(143766, 'frFR', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s commence à lancer |cFFFF0000|Hspell:259610|h[Apocalypse sanglante]|h|r ! À couvert !', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s commence à lancer |cFFFF0000|Hspell:259610|h[Apocalypse sanglante]|h|r ! À couvert !', 28153),
(143765, 'frFR', '', 'Résistez ! Débattez-vous ! Votre souffrance, elle nourrit mon maître !', 28153),
(143764, 'frFR', 'Jaina ? Vous voulez dire Jain-arde. Et Modera ? Euh… Bon, cette fois aucun de ces excellents jeux de mots ne me vient.', '', 28153),
(143763, 'frFR', 'Khadgar ? Vous voulez dire Rat\’dgar ?', '', 28153),
(143762, 'frFR', 'Le Kirin Tor ? Je dirais plutôt le Kirin Dort.', '', 28153),
(143761, 'frFR', 'Si vous faisiez ce que je dis au lieu de penser par vous-mêmes, Azeroth se porterait bien mieux.', '', 28153),
(143760, 'frFR', 'Mieux vaut ne pas s\’opposer à nous.', '', 28153),
(143759, 'frFR', 'Pour Quel\’thalas !', '', 28153),
(143758, 'frFR', 'Nous avons surmonté tant d\’épreuves.', '', 28153),
(143757, 'frFR', 'Nos traditions sont le fondement de notre avenir.', '', 28153),
(143756, 'frFR', 'Faites ce que vous avez à faire.', '', 28153),
(143755, 'frFR', 'Ne laissez aucun étranger s\’en mêler.', '', 28153),
(143754, 'frFR', 'Respectez nos usages.', '', 28153),
(143753, 'frFR', 'Le soleil éternel nous guide toujours.', '', 28153),
(143752, 'frFR', 'Que voulez-vous ?', '', 28153),
(143751, 'frFR', 'Je sers Lune-d\’Argent.', '', 28153),
(143750, 'frFR', 'Je suis occupé.', '', 28153),
(143749, 'frFR', 'Ne gaspillez pas vos ressources.', '', 28153),
(143748, 'frFR', 'Qu\’y a-t-il ?', '', 28153),
(143747, 'frFR', 'Le Puits de soleil doit être protégé.', '', 28153),
(143746, 'frFR', 'Prenez ceci, en guise de remerciement.', '', 28153),
(143745, 'frFR', '', 'Comploter ? Moi ? Qu\’est-ce que l\’innocente demoiselle que je suis pourrait bien comploter ?', 28153),
(143744, 'frFR', '', 'Vous croyez que je n\’ai pas remarqué la façon dont vous lorgnez mes forestiers-sombres ? Je vous conseille d\’arrêter ça tout de suite.', 28153),
(143743, 'frFR', '', 'J\’ai suivi votre parcours. Je pense que je vais vous envoyer chez Nathanos pour une petite remise à niveau.', 28153),
(143742, 'frFR', '', 'Je suis votre préférée des sœurs Coursevent, n\’est-ce pas ? N\’est-ce pas ?', 28153),
(143741, 'frFR', '', 'L\’essence vitale d\’Azeroth appartient à la Horde.', 28153),
(143740, 'frFR', 'Et moi qui commençais à douter de l\’existence d\’une telle créature !', '', 28153),
(143739, 'frFR', '', 'Nous prendrons ce qui nous revient de droit.', 28153),
(143738, 'frFR', '', 'Tous finiront par servir la Horde.', 28153),
(143737, 'frFR', '', 'Les rangs des Réprouvés grossiront. D\’une manière ou d\’une autre.', 28153),
(143736, 'frFR', '', 'L\’Alliance se soumettra à nous.', 28153),
(143735, 'frFR', '', 'Servez la Horde. Servez-moi.', 28153),
(143734, 'frFR', 'Magnifique !', '', 28153),
(143733, 'frFR', '', 'Partez. J\’ai beaucoup à faire.', 28153),
(143732, 'frFR', '', 'Servez-moi et vos efforts seront récompensés.', 28153),
(143731, 'frFR', '', 'La Horde connaîtra un nouvel avenir.', 28153),
(143730, 'frFR', '', 'Notre ouvrage ne fait que commencer.', 28153),
(143729, 'frFR', '', 'Salutations.', 28153),
(143728, 'frFR', '', 'Approchez.', 28153),
(143727, 'frFR', '', 'Ne me faites pas perdre mon temps.', 28153),
(143726, 'frFR', '', 'Informez votre chef de guerre sans tarder.', 28153),
(143725, 'frFR', '', 'Les éléments de Zandalar ont été durement éprouvés. Nous devons arrêter le sombre chaman qui abuse de son pouvoir à des fins personnelles.', 28153),
(143724, 'frFR', 'Moi, c\’est Berthold, et les chevaux, c\’est mon dada.\n\nJ\’ai entendu dire qu\’une splendide créature équine rôdait dans les montagnes, à l\’ouest de ces lieux de villégiature. Alors, je me suis fait embaucher ici dans l\’espoir d\’aller l\’admirer pendant mon temps libre.\n\nQu\’est-ce que je ne donnerais pas pour voir une bête pareille…', '', 28153),
(143721, 'frFR', 'Affirmatif. Position du gardien des Titans Hezrel confirmée. Départ pour le secteur identifié comme Zul\’Nazman.', '', 28153),
(143720, 'frFR', '', 'Hezrel, les Trolls de sang se rassemblent à Zul\’nazman. Si tu veux nous aider, c\’est là qu\’il faut aller.', 28153),
(143719, 'frFR', 'Payez-moi un verre, $pr.\n\nMon peuple, il a sauvé ce monde pendant que le vôtre se cachait lâchement dans la brume.\n\nVous m\’en devez bien un.', '', 28153),
(143718, 'frFR', 'Systèmes du gardien des Titans Hezrel opérationnels à cinquante pour cent de leur capacité. Conservation de l\’énergie restante pour la purge des Trolls de sang.', '', 28153),
(143717, 'frFR', 'C\’est ici que je les préparais, mes cocktails. La famille royale recevait des nobles du monde entier, et moi, je les ai tous régalés de mes créations.\n\nMais aujourd\’hui, c\’est devenu le repaire de ces sales étrangers avec leurs affreux amis. Quelle tristesse !', '', 28153),
(143716, 'frFR', 'Je respecte certains des cartels gobelins. Neutres, puissants, prêts à faire ce qu\’il faut. Comme les Zandalari… en moins bien, forcément.\n\nMais vous, les Baille-Fonds, vous n\’avez aucune fierté. Comment pouvez-vous pactiser avec les Elfes et la Horde ? Sales traîtres.', '', 28153),
(143715, 'frFR', 'Goûtez à ma puissance !', '', 28153),
(143714, 'frFR', 'J\’admire l\’organisation de votre Horde, $p. Des chefs puissants. Un but commun. Un ravitaillement régulier.\n\nVous recrutez ?', '', 28153),
(143713, 'frFR', 'Je suis prêt à rechercher notre prochain allié.', 'Je suis prête à rechercher notre prochain allié.', 28153),
(143712, 'frFR', '', 'Enfin, la Horde et l\’Alliance arrêtent de nager entre deux eaux.$b$bL\’heure de la guerre est proche.', 28153),
(143711, 'frFR', 'Je n\’ai jamais réussi à me faire à l\’idée que les Sombrelances ont rejoint la Horde. Il faut croire que vous avez toujours été trop faibles pour vous débrouiller seuls.\n\nComment il va, Vol\’jin ?', '', 28153),
(143710, 'frFR', 'Écoutez, l\’Elfe. Ce bar, il n\’est plus à moi, alors je n\’ai plus besoin de faire semblant de vous apprécier.\n\nHors de ma vue.', '', 28153),
(143709, 'frFR', 'Vous avez l\’air d\’avoir soif. Ça vous dirait de discuter autour d\’un verre ?\n\nZuldazar est là depuis la nuit des temps et elle ne va pas disparaître en une nuit.', '', 28153),
(143708, 'frFR', 'On raconte que certains d\’entre vous vont partir pour Nazmir. Évitez de faire partie du voyage, si vous le pouvez. Ce marais, rien de bon n\’en est sorti depuis des générations.', '', 28153),
(143707, 'frFR', 'Il paraît qu\’il y a plus de problèmes que d\’habitude dans le désert de Vol\’dun. Faites attention à vous si vous devez aller dans ce coin.', '', 28153),
(143706, 'frFR', 'Mon peuple, il a fondé la civilisation à l\’aube des temps et il porte les autres sur son dos depuis cette époque.\n\nRappelez-moi ce que vos congénères, ils ont accompli qui soit digne de rester dans les mémoires, $PR ?\n\nJ\’ai beau réfléchir, il n\’y a rien qui me vient.', '', 28153),
(143705, 'frFR', '(Sauter sur l\’épaule d\’Hezrel pour retourner à Glaucombe.)', '(Sauter sur l\’épaule d\’Hezrel pour retourner à Glaucombe.)', 28153),
(143704, 'frFR', 'Échec de la réparation de la structure de confinement de G\’huun. Objectif : empêcher les êtres identifiés comme Trolls de sang de détruire Zuldazar pour éviter la libération de G\’huun.\n\nStructure encerclée par des Trolls de sang. Le gardien des Titans Hezrel assurera la sécurité |2 $n et de la princesse Talanji.\n\nPrière de sauter sur les épaules et garder la tête baissée.', '', 28153),
(143703, 'frFR', 'Je n\’ai jamais rien vu de plus sale ou dégoûtant que vous. Même les Trolls de sang, ils ne puent pas autant.\n\nSi j\’étais encore propriétaire de ce bar, vous auriez déjà fini aux ordures.', '', 28153),
(143702, 'frFR', 'Vous avez des nouvelles de ce qui se passe hors de la ville ?', '', 28153),
(143700, 'frFR', 'Gallywix est actif en Silithus. Allez-y immédiatement. Et si des rats de l\’Alliance rôdent dans les parages, vous savez quoi faire.', '', 28153),
(143699, 'frFR', 'Nous avons établi un campement de fortune en Silithus. Allez voir nos agents sur place… et faites attention à la Horde.', '', 28153),
(143698, 'frFR', 'Vous autres, les Orcs, il faut bien reconnaître que vous savez picoler.\n\nMais dites à vos amis les Elfes de ne jamais mettre les pieds ici, d\’accord ?', '', 28153),
(143697, 'frFR', 'Alleria et Turalyon ? Aucune chance que ça dure. Non pas que je leur souhaite malheur, mais… Bref. Et si on changeait de sujet ?', '', 28153),
(143696, 'frFR', 'Je peux vous pardonner de ne pas aimer les Elfes. Après tout, la moitié de notre peuple déteste cordialement l\’autre.', '', 28153),
(143695, 'frFR', 'Du violet, encore du violet… Je commence à en avoir plein le dos, littéralement !', '', 28153),
(143694, 'frFR', 'Moi, un Haut-Elfe ? Mais qui aurait donc envie d\’être un Haut-Elfe, alors qu\’on peut avoir l\’air sombre et tourmenté ?', '', 28153),
(143693, 'frFR', 'Maîtrise et concentration.', '', 28153),
(143692, 'frFR', 'Ne laissez pas les murmures prendre le dessus.', '', 28153),
(143691, 'frFR', 'Envisagez toutes les possibilités.', '', 28153),
(143690, 'frFR', 'Les ténèbres veillent sur vous.', '', 28153),
(143689, 'frFR', 'Nous servons l\’Alliance.', '', 28153),
(143688, 'frFR', 'La Lumière n\’est pas la seule solution.', '', 28153),
(143687, 'frFR', 'Les Ren\’dorei prouveront leur valeur.', '', 28153),
(143686, 'frFR', 'J\’ai beaucoup à vous enseigner.', '', 28153),
(143685, 'frFR', 'Venez l\’esprit ouvert.', '', 28153),
(143684, 'frFR', 'Toutes les voies sont possibles.', '', 28153),
(143683, 'frFR', 'Nous ne craignons pas le pouvoir.', '', 28153),
(143682, 'frFR', 'Les ténèbres sont à notre service.', '', 28153),
(143681, 'frFR', 'Bal\’a dash, malanore.', '', 28153),
(143680, 'frFR', 'Salutations.', '', 28153),
(143679, 'frFR', 'Mon cache-œil n\’a jamais changé de côté ! Franchement… comme si ce genre d\’erreur pouvait se produire !', '', 28153),
(143678, 'frFR', 'Travailler pour Sylvanas n\’est pas toujours… évident. Elle est encore plus caractérielle depuis qu\’elle est morte. Mais, euh… ne le lui répétez pas.', '', 28153),
(143677, 'frFR', 'Champion de la reine ou non, Nathanos ne m\’arrive pas à la cheville !', '', 28153),
(143676, 'frFR', 'Si je prends autant soin de mes cheveux, c\’est parce que je le vaux bien !', '', 28153),
(143675, 'frFR', 'Plus jamais un roi ne régnera sur Lune-d\’Argent.', '', 28153),
(143674, 'frFR', 'Notre nation est en plein essor.', '', 28153),
(143673, 'frFR', 'Al diel shala.', '', 28153),
(143672, 'frFR', 'La Horde nous donne la force.', '', 28153),
(143671, 'frFR', 'Tout ce que je fais, je le fais pour Quel\’Thalas.', '', 28153),
(143670, 'frFR', 'La lumière du Puits de soleil vous bénisse.', '', 28153),
(143669, 'frFR', 'Lune-d\’Argent retrouvera sa prospérité d\’antan.', '', 28153),
(143668, 'frFR', 'La beauté des Chants éternels demeure.', '', 28153),
(143667, 'frFR', 'Le soleil éternel nous guide toujours.', '', 28153),
(143666, 'frFR', 'La reconstruction se poursuit.', '', 28153),
(143665, 'frFR', 'Nous avons accompli de nombreux sacrifices.', '', 28153),
(143664, 'frFR', 'C\’est un honneur pour moi que d\’être seigneur régent.', '', 28153),
(143663, 'frFR', 'Bal\’a dash, malanore.', '', 28153),
(143662, 'frFR', 'Je vous salue au nom de Lune-d\’Argent.', '', 28153),
(143651, 'frFR', 'Oh, je crois que j\’en ai attrapé un gros !', '', 28153),
(143650, 'frFR', 'SCÈNE TEMPORAIRE - Hezrel décrit G\’huun comme un dieu ancien soumis à des expérimentations et révèle que les Trolls de sang veulent détruire Zuldazar pour le libérer. Échec de la réparation de la structure de confinement actuelle, il faut protéger Zuldazar. Ateena, matriarche des Trolls de sang, arrive, inflige de lourds dégâts à Hezrel, et se prépare à frapper.', 'SCÈNE TEMPORAIRE - Hezrel décrit G\’huun comme un Dieu très ancien soumis à des expérimentations et révèle que les Trolls de sang veulent détruire Zuldazar pour le libérer. Échec de la réparation de la structure de confinement actuelle, il faut protéger Zuldazar. Ateena, matriarche des Trolls de sang, arrive, inflige de lourds dégâts à Hezrel, et se prépare à frapper.', 28153),
(143649, 'frFR', '', 'Reculez, $r ! Sa voix m\’appartient !', 28153),
(143648, 'frFR', '', 'Il y a une telle... puissance... ici.', 28153),
(143647, 'frFR', '', 'Prenez garde, Umbric. Les réponses à de tels mystères ont bien souvent un prix.', 28153),
(143646, 'frFR', 'Prenez ce cube, par exemple. Il s\’agit d\’un ancien dispositif qui existait avant même que la vie n\’apparaisse sur Azeroth. Mais il est verrouillé et nous ne parvenons pas à l\’ouvrir.', '', 28153),
(143645, 'frFR', 'En effet ! Tout comme vous, nous sommes convaincus que le Vide peut être utilisé pour défendre la vie au lieu de la dévorer. Nous avons fait d\’immenses progrès, dame Coursevent, mais de nombreux mystères persistent.', '', 28153),
(143644, 'frFR', '', 'Parlons de cela une autre fois. Nous vous cherchions. Nous avons eu vent de votre exil de Lune-d\’Argent et pensons que nous partageons certaines idées.', 28153),
(143643, 'frFR', 'Les nouvelles d\’Argus nous sont parvenues jusqu\’ici. Et comme vous pouvez l\’imaginer, votre échange avec le Naaru corrompu nous intéresse au plus haut point.', '', 28153),
(143642, 'frFR', 'Alleria Coursevent ? C\’est… C\’est un honneur inespéré !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143641, 'frFR', '', 'Magistère Umbric ! Je suis Alleria Coursevent.', 28153),
(143640, 'frFR', '', 'Là-bas. Ce doit être Umbric.', 28153),
(143639, 'frFR', '', 'Si j\’en crois ces notes, je devrais pouvoir rouvrir le passage vers le monde que mentionnait Dar\’Khan… Voyons voir.', 28153),
(143638, 'frFR', '', '<Landing from jump: Total 3>', 28153),
(143637, 'frFR', 'Dar\’Khan pensait qu\’il y trouverait un objet ancien d\’une puissance indescriptible. Peut-être s\’agit-il de l\’outil qui nous permettra d\’avoir le contrôle face aux ténèbres.', '', 28153),
(143636, 'frFR', 'D\’après ses notes, ce lieu se trouvait au cœur d\’une faille déchirant la trame de la réalité. Il ne l\’a jamais trouvé… mais moi j\’ai réussi ! La voie s\’ouvrira bientôt à nous !', '', 28153),
(143635, 'frFR', 'La quête de puissance de Dar\’Khan l\’a conduit à rechercher les fragments d\’un monde ancien à la lisière même du Vide.', '', 28153),
(143634, 'frFR', '<Landing from jump: Total 3>', '', 28153),
(143633, 'frFR', '', 'Venez. Nous devons nous rendre à la flèche d\’Aubétoile.', 28153),
(143632, 'frFR', 'Quoi qu\’il en soit, je reste convaincu que nous pouvons faire bon usage de ce savoir. Dar\’Khan a principalement conduit ses recherches à la flèche d\’Aubétoile. C\’est là que nous devons aller.', '', 28153),
(143631, 'frFR', 'C\’est la trahison de Dar\’Khan qui a permis à Arthas de corrompre le puits de Soleil… et qui a conduit notre royaume à la ruine. Pour la première fois, je comprends pourquoi Rommath s\’oppose à nos recherches.', '', 28153),
(143630, 'frFR', 'Nous ne sommes pas les premiers à avoir tenté de maîtriser le Vide. J\’ai trouvé des carnets qui appartenaient à un individu dont le nom même est maudit… Dar\’Khan Drathir.', '', 28153),
(143629, 'frFR', '<Landing from jump: Total 3>', '', 28153),
(143628, 'frFR', '', 'On dirait que nous avons trouvé des notes.', 28153),
(143627, 'frFR', '', '<Landing from jump: Total 3>', 28153),
(143626, 'frFR', 'Malheureusement, nos recherches ont débouché sur une impasse. Le savoir que renferme le domaine d\’Andilien devrait toutefois nous permettre de rebondir.', '', 28153),
(143625, 'frFR', 'Le grand magistère Rommath doit comprendre que ce pouvoir est primordial pour la défense de Lune-d\’Argent. Plus jamais les Sin\’dorei ne tomberont aux griffes de l\’ennemi !', '', 28153),
(143624, 'frFR', 'Nos expériences se déroulent sans accroc. Je suis persuadé que nous sommes sur le point de faire une découverte magistrale… malgré les protestations de Rommath.', '', 28153),
(143623, 'frFR', '<Landing from jump: Total 3>', '', 28153),
(143622, 'frFR', '', '<Landing from jump: Total 3>', 28153),
(143621, 'frFR', '<Distressed cry: Total 3>', '', 28153),
(143620, 'frFR', '<Landing from jump: Total 3>', '', 28153),
(143619, 'frFR', 'Hezrel, lancez l\’analyse pour trouver une solution à la corruption de Nazmir par le Dieu très ancien.', 'Hezrel, lancez l\’analyse pour trouver une solution à la corruption de Nazmir par le Dieu très ancien.', 28153),
(143618, 'frFR', 'Voyons si ces poissons sont prêts à mordre !', '', 28153),
(143617, 'frFR', '', '<Landing from jump: Total 3>', 28153),
(143616, 'frFR', '', 'Ces bois ont fait le bonheur des trois sœurs que nous étions. Les voir de la sorte… emplit mon cœur de tristesse.', 28153),
(143615, 'frFR', 'Ensemble, nous leur prouverons qu\’ils ont tort.', '', 28153),
(143614, 'frFR', 'Nous adapter à notre nouvelle forme demandera un certain temps. Nous attendrons votre retour avec impatience, dame Coursevent. Quant à vous, $p… merci infiniment.', '', 28153),
(143613, 'frFR', '', 'En retour, je jure de vous aider à surmonter les épreuves qui vous attendent. Nous devons informer le haut roi Wrynn. Je reviendrai ensuite me charger de votre entraînement.', 28153),
(143612, 'frFR', 'Il y a longtemps que Lune-d\’Argent nous a tourné le dos. Nous avons changé… et devons suivre une nouvelle voie. À partir d\’aujourd\’hui, l\’Alliance peut compter sur notre loyauté.', '', 28153),
(143611, 'frFR', '', 'Je ressens les pouvoirs dont vous disposez. Ils sont… considérables. Vous seriez des alliés de poids pour l\’Alliance.', 28153),
(143610, 'frFR', 'Mon arrogance a bien failli causer notre perte. J\’ai joué avec des pouvoirs qui me dépassaient. Alleria, si vous acceptez de nous entraîner, nous rallierons votre cause.', '', 28153),
(143609, 'frFR', '', 'J\’ai autorisé la construction d\’une ambassade à Orgrimmar. Grâce à elle, nous gagnerons d\’autres appuis à notre cause. Rejoignez-moi là-bas immédiatement.', 28153),
(143608, 'frFR', '', 'L\’altruisme dont a fait preuve le commandement de la Horde pendant la guerre contre la Légion a affaibli nos rangs. Nos ennemis se réjouissent à l\’idée de voler ce qui nous appartient. Nous ne les laisserons pas faire.', 28153),
(143607, 'frFR', '', 'Vous avez été témoin de nos opérations en Silithus, $p. Et comme vous avez pu le constater, l\’Alliance se démène pour saper nos efforts.', 28153),
(143606, 'frFR', 'Il est temps pour l\’Alliance de rallier de nouveaux membres à sa cause. Nous avons établi une ambassade à Hurlevent pour conduire ces efforts. Retrouvez-moi là-bas.', '', 28153),
(143605, 'frFR', 'La Horde ne reculera devant rien pour accaparer le sang d\’Azeroth. Mais je crains que la guerre contre la Légion ait trop affaibli nos rangs pour que nous puissions parer leurs attaques.', '', 28153),
(143604, 'frFR', 'Vous avez vu la dévastation de Silithus de vos propres yeux, $p. Vous connaissez les enjeux.', '', 28153),
(143603, 'frFR', 'Retrouvez-moi à l\’extérieur du fort Grommash. Mais pas un mot de tout ça… ou les conséquences seront immédiates et lourdes.', '', 28153),
(143602, 'frFR', 'Des informations cruciales pour les intérêts de la Horde nous sont parvenues. Il est essentiel que nous gardions une longueur d\’avance sur nos rivaux.', '', 28153),
(143601, 'frFR', '$p ! La Dame noire exige que nous nous entretenions à Orgrimmar.', '', 28153),
(143600, 'frFR', 'Retrouvez-moi au Repos du lion. Inutile de préciser que les détails de cette rencontre restent entre nous.', '', 28153),
(143599, 'frFR', 'Nous avons mis la main sur des informations… sensibles, que Sa Majesté juge important de partager avec vous.', '', 28153),
(143598, 'frFR', '$p, le haut roi Wrynn souhaite que je m\’entretienne avec vous à Hurlevent.', '', 28153),
(143597, 'frFR', 'Je t\’amène aussi cette étrangère qui veut te parler, puissant Loa.', '', 28153),
(143596, 'frFR', '', 'Les Sacrenuit sont sages et puissants. Votre savoir incommensurable sera pour nous un grand atout.', 28153),
(143595, 'frFR', '', 'Trêve de civilités. Vous devez à présent faire vos preuves. Où que vos aventures vous mènent, n\’oubliez pas que vous combattez… pour la Horde !', 28153),
(143594, 'frFR', '', 'Sachez que je surveillerai attentivement vos progrès. En tant que chef de guerre, j\’attends beaucoup de vous… et je récompense toujours mes loyaux serviteurs.', 28153),
(143593, 'frFR', '', 'La Horde compte de nombreux adversaires. Certains nous appellent des ennemis… d\’autres des parias. Mais nous puisons notre force dans l\’union… et dans l\’adversité.', 28153),
(143592, 'frFR', '', 'Les Taurens de Haut-Roc sont reconnus pour leur force et leur courage. De telles qualités nous seront indispensables prochainement.', 28153),
(143591, 'frFR', '', 'Ah, $p, vous voilà enfin. Il paraît que vous avez du potentiel. Espérons que les rumeurs disent vrai.', 28153),
(143590, 'frFR', 'Bon voyage, $p. Que la Lumière soit toujours avec vous.', '', 28153),
(143589, 'frFR', 'Les Elfes du Vide sont certes de récents alliés, mais Alleria Coursevent est l\’une de nos plus grandes héroïnes. Sous sa tutelle, les pouvoirs que vous détenez serviront notre cause.', '', 28153),
(143588, 'frFR', 'Nous vous chasserons de ces terres !', '', 28153),
(143587, 'frFR', 'Bon voyage, $p. Bien que vous marchiez à travers les ombres, vous êtes une flamme d\’espoir pour nous tous.', '', 28153),
(143586, 'frFR', 'Je suivrai votre parcours avec intérêt. Quelque chose me dit que nous nous reverrons bientôt.', '', 28153),
(143585, 'frFR', 'Notre monde vit des heures sombres. Dans les jours qui s\’annoncent, vous devrez faire face à bien des défis… affronter nombre d\’ennemis. Mais sachez que face aux ténèbres, l\’Alliance sera toujours à vos côtés.', '', 28153),
(143584, 'frFR', 'Les Sancteforge sont certes de nouveaux alliés, mais je connais bien les Draeneï. Je suis certain que vous incarnerez les valeurs de dévouement et de courage de l\’armée de la Lumière.', '', 28153),
(143583, 'frFR', 'Bienvenue, $p. Je suis le roi Anduin Wrynn. Comme vous venez de rejoindre l\’Alliance, je tenais à vous saluer personnellement.', '', 28153),
(143582, 'frFR', 'J\’ai besoin de soins !', '', 28153),
(143581, 'frFR', 'C\’est notre scierie ! Allez vous faire voir ailleurs !', '', 28153),
(143580, 'frFR', 'La Horde nous a conduits dans un coin du monde aussi méconnu qu\’intéressant.\n\nJ\’espère que la plupart des établissements de ma nouvelle faction seront plus élégants et propres que celui-ci.', '', 28153),
(143579, 'frFR', 'Pardonnez-moi, $p.\n\nJe serais ravi de discuter avec vous, mais je crois que je vais vomir.\n\nUn conseil : ne goûtez pas à leur vin.', '', 28153),
(143578, 'frFR', '<Le négociant en vin Thesnala dévisage le tavernier tout en renversant lentement le contenu de son verre à ses pieds.>', '', 28153),
(143577, 'frFR', 'Avez-vous déjà goûté le vin du cru ?\n\nNe passez pas à côté ! Il est incroyablement mauvais.\n\nJe vous parie que des bardes composeront un jour des chansons sur son âpreté légendaire.\n\nC\’est véritablement un exploit en termes de médiocrité et de gâchis d\’alcool. Avec ça, on est sûr de gâcher n\’importe quelle fête.', '', 28153),
(143576, 'frFR', 'J\’admets que les Zandalari s\’y entendent pour construire des bâtiments aussi laids qu\’imposants.\n\nOn ne peut hélas pas en dire autant de la viticulture.', '', 28153),
(143575, 'frFR', 'Si vous ne savez pas faire du bon vin, abstenez-vous.', '', 28153),
(143574, 'frFR', 'Payez-moi un autre verre de ce vin, afin que je puisse le cracher à nouveau par terre.', '', 28153),
(143573, 'frFR', 'Ils osent appeler cette piquette du vin ? Pas étonnant que les Trolls abandonnent cette ville.', '', 28153),
(143572, 'frFR', 'Nous sommes enfin libres ! Vite, sortons d\’ici !', 'Nous sommes enfin libres ! Vite, sortons d\’ici !', 28153),
(143571, 'frFR', 'Ces abominations de bois sortent tout droit d\’un cauchemar !', '', 28153),
(143569, 'frFR', 'J\’espère au moins toucher… une prime de risque…', 'J\’espère au moins toucher… une prime de risque…', 28153),
(143568, 'frFR', '', 'Même dévasté, cet endroit me semble familier…', 28153),
(143567, 'frFR', 'Du nerf, bande de moules !', 'Mettez-y un peu de cœur, bande de moules !', 28153),
(143566, 'frFR', 'Intérieur du bâtiment sécurisé. L\’entité désignée comme princesse Talanji est présente.', '', 28153),
(143565, 'frFR', 'Entendu. En route pour Corlain !', '', 28153),
(143562, 'frFR', 'Trop tard. Rien ni personne ne peut plus contenir G\’huun. C\’est la fin. La fin de tout et de tous.', '', 28153),
(143561, 'frFR', 'Votre fin approche. G\’huun sera bientôt libre et alors, à nous Azeroth !', '', 28153),
(143560, 'frFR', 'Déposez vos objets de valeur dans le coffre et circulez, $p.\n\nJe vous ai à l\’œil…', '', 28153),
(143559, 'frFR', 'Drustvar vit des heures bien sombres, mais nous reprendrons le contrôle de nos terres !', '', 28153),
(143558, 'frFR', 'Pour Zandalar !', '', 28153),
(143557, 'frFR', 'Rezan, c\’est l\’heure de partir en chasse !', '', 28153),
(143556, 'frFR', 'Oui. Je propose de suivre les ordres de notre camarade.', '', 28153),
(143555, 'frFR', 'Pa\’ku, Loa des vents, envole-toi et trouve les hérétiques. Découvre ce qu\’ils préparent et rejoins-nous au temple.', '', 28153),
(143554, 'frFR', 'Gonk, Loa de la chasse, conduis tes serviteurs au temple du Prophète. Fais sortir nos ennemis et n\’épargne personne.', '', 28153),
(143553, 'frFR', 'Frères et sœurs de Zandalar, c\’est l\’heure de décapiter les traîtres qui ont juré fidélité à Zul.', '', 28153),
(143552, 'frFR', '', 'Pendant ce temps, nous préparerons notre départ pour Corlain. Maréchal, j\’ai cru comprendre que vous aviez un plan d\’attaque ?', 28153),
(143551, 'frFR', '', 'Oui, madame !', 28153),
(143550, 'frFR', '', 'Trouvez maître Ashton et donnez-lui cette recette de feu alchimique. Il saura quoi en faire.', 28153),
(143549, 'frFR', '', 'Fort heureusement, je connais un excellent alchimiste à Butte-du-Faucon, plus au sud. Évitez les bois et suivez les anciennes routes de montagne pour vous y rendre.', 28153),
(143548, 'frFR', '', 'Le recueil contient une recette de feu alchimique, mais seul un expert peut en fabriquer.', 28153),
(143547, 'frFR', '', 'En plus de l\’argent, nous aurons besoin de feu, si nous voulons éradiquer le Sabbat.', 28153),
(143546, 'frFR', '', 'Merci, monsieur ! En quoi puis-je vous servir, madame ?', 28153),
(143545, 'frFR', 'Je fais entièrement confiance au capitaine Aub… Pardon, à l\’inquisitrice Aubeclaire. Elle saura se montrer à la hauteur, quelle que soit sa tâche.', '', 28153),
(143544, 'frFR', '', 'Qui me recommanderiez-vous, maréchal ?', 28153),
(143543, 'frFR', '', 'Avant de nous mettre en marche, j\’aimerais confier une mission un peu spéciale à l\’un d\’entre vous.', 28153),
(143542, 'frFR', 'Vous le croyez, ça, que la Horde n\’a jamais créé de bureau officiel de télémancie ? J\’ignore comment se débrouillaient ses citoyens pour se déplacer sans risquer leur vie à chaque voyage. Imaginez un peu tous ces portails ouvrant des failles dans la réalité sans être correctement ancrés...\n\nEnfin, bref... Je suis heureux de pouvoir offrir à la Horde un réseau de téléportation stabilisé. Et maintenant, circulez, je vous prie.', '', 28153),
(143540, 'frFR', 'Mes concitoyens sont valeureux, mais leur volonté est mise à rude épreuve !', '', 28153),
(143539, 'frFR', '', 'Noyez ces insectes, mes enfants. Montrez-vous dignes de moi.', 28153),
(143537, 'frFR', 'Brgl ! Brglrgl !', '', 28153),
(143536, 'frFR', 'Mrgl, mrglrglrgl ! Mrrrg ! Mrrrg !!', '', 28153),
(143531, 'frFR', 'Forcer', 'Forcer', 28153),
(143530, 'frFR', 'À vous de jouer ! Grimpez !', '', 28153),
(143529, 'frFR', 'Y a un truc qui cloche sur la Griffe de Rezan. Un éclaireur est posté près du camp.', '', 28153),
(143523, 'frFR', 'Filez-moi votre or, j\’ai une réunion pour un bilan financier dans cinq minutes !', '', 28153),
(143520, 'frFR', 'Je suis prêt, imprégnez-moi de l\’essence synthétique de G\’hunn.', 'Je suis prête, imprégnez-moi de l\’essence synthétique de G\’hunn.', 28153),
(143519, 'frFR', 'Le roi Da\’ka ! Il nous a trouvés ! À l\’aide !', '', 28153),
(143518, 'frFR', 'Vous avez… perdu ? Contre eux ? Vous devriez avoir honte ! Allez tout de suite à Fossoyeuse pour une remise à niveau, puisqu\’il vous manque même les bases !', '', 28153),
(143517, 'frFR', 'Ça n\’avait rien d\’une victoire élégante, mais au moins vous avez remis ces chiens de l\’Alliance à leur place. Pour la Horde !', '', 28153),
(143516, 'frFR', 'Ça sent… le Worgen, non ? Impossible d\’en être certain avec la puanteur de ces hypocrites moralisateurs de l\’Alliance.', '', 28153),
(143515, 'frFR', 'Abattez-les ! Ne décevez pas notre chef de guerre !', '', 28153),
(143514, 'frFR', 'L\’Alliance appelle ça des soldats ? Lamentable ! Ils sont à peine capables de donner un coup d\’épée !', '', 28153),
(143513, 'frFR', 'Tirez ! Je ne veux plus voir un seul de ces lâches en vie !', '', 28153),
(143512, 'frFR', 'Diantre ! Il y a encore plus d\’azérite que je le pensais. Consultez votre carte et prenez le contrôle de ces sites !', '', 28153),
(143511, 'frFR', 'Il y a d\’autres éruptions d\’azérite sur cette maudite île ! Consultez votre carte pour les trouver.', '', 28153),
(143510, 'frFR', 'Nous y sommes presque. Ne fléchissez pas. Il nous faut plus d\’azérite !', '', 28153),
(143509, 'frFR', 'Ha ! Voilà de l\’azérite que l\’Alliance n\’aura pas ! Bien joué !', '', 28153),
(143508, 'frFR', 'C\’est acceptable pour un premier effort, mais il nous faut plus d\’azérite !', '', 28153),
(143507, 'frFR', 'Récupérez ce ravitaillement si vous en avez besoin. Mais ne perdez pas de vue l\’objectif de la reine banshee !', '', 28153),
(143506, 'frFR', 'Ravitaillement en approche. Il vaudrait mieux pour vous que l\’Alliance ne le récupère pas !', '', 28153),
(143505, 'frFR', 'Là-bas, il y a de l\’azérite ! Récupérez-la pour notre chef de guerre. Et si l\’Alliance vous fait obstacle, que les cadavres s\’amoncellent sur le rivage ! En avant !', '', 28153),
(143504, 'frFR', 'Laissez-moi vous regarder. Arg… pitoyable ! Pourquoi n\’avez-vous pas de forestiers-sombres ? Tant pis, il faudra se contenter de vous.', '', 28153),
(143503, 'frFR', 'Vaisseau de l\’Alliance en approche ! Ces rats sont sur nos talons. Ils l\’auront cherché… Rejoignez vos postes de combat !', '', 28153),
(143502, 'frFR', 'Votre mission est simple : récupérer la moindre miette d\’azérite et ne rien laisser à l\’Alliance. Même vous, vous pouvez comprendre cela.', '', 28153),
(143501, 'frFR', 'Champions de la Horde ! Nous avons trouvé des gisements d\’azérite sur une île perdue au large de la côte de Féralas. Emparez-vous-en. Ordre de la Dame noire !', '', 28153),
(143500, 'frFR', 'Renvoyez-les chez eux ! Cette île est à nous !', '', 28153),
(143499, 'frFR', 'Battez-vous pour le roi ! Battez-vous pour l\’Alliance !', '', 28153),
(143498, 'frFR', 'Ces vauriens de la Horde se croient malins. Donnez-leur une bonne leçon !', '', 28153),
(143497, 'frFR', 'Ouvrez le feu et abattez ces soigneurs !', '', 28153),
(143496, 'frFR', 'Vous m\’avez l\’air robustes. Hmm… On aurait bien besoin d\’un voleur ou deux, mais… Non, vous ferez l\’affaire !', '', 28153),
(143495, 'frFR', 'Bon sang ! Cette fois, la Horde a pris le dessus. Mais je jure sur le Repos du lion que la victoire sera nôtre !', '', 28153),
(143494, 'frFR', 'Excellent travail, champions ! Le roi Wrynn sera ravi de cette victoire. Pour l\’Alliance !', '', 28153),
(143493, 'frFR', 'Ravitaillement en approche ! Récupérez-le, champions !', '', 28153),
(143492, 'frFR', 'Encore des éruptions d\’azérite ! Repérez-les sur votre carte et prenez le contrôle des différents sites !', '', 28153),
(143491, 'frFR', 'Beau travail. Encore un peu d\’azérite et la victoire sera à nous !', '', 28153),
(143490, 'frFR', 'Vous avez empêché la Horde de mettre la main sur ce gisement d\’azérite. Bien joué !', '', 28153),
(143489, 'frFR', 'Vous vous en sortez très bien pour l\’instant. Mais il nous faut plus d\’azérite !', '', 28153),
(143488, 'frFR', 'Héros ! On vous envoie du ravitaillement. Ne laissez pas la Horde mettre ses sales pattes dessus !', '', 28153),
(143487, 'frFR', 'Nous avons repéré d\’autres éruptions d\’azérite sur l\’île ! Leurs emplacements sont marqués sur votre carte.', '', 28153),
(143486, 'frFR', 'Il y a un gisement d\’azérite sous nos pieds, héros. Descendez et récupérez ce que vous pourrez. Si ces vautours de la Horde vous barrent la route… abattez-les !', '', 28153),
(143485, 'frFR', 'Vaisseau de la Horde en approche ! J\’aurais dû me douter que ces ordures nous suivraient jusqu\’ici. Tous à vos postes de combat !', '', 28153),
(143484, 'frFR', 'Nous avons rapproché nos bateaux du centre de l\’île. Récoltez autant d\’azérite que possible. C\’est ainsi que nous remporterons la victoire !', '', 28153),
(143483, 'frFR', 'Champions, des gisements d\’azérite ont été repérés sur une île au large de la côte de Féralas. Nous devons nous en emparer avant la Horde.', '', 28153),
(143482, 'frFR', '', 'Ce serait un honneur, dame Liadrin. Oculeth dispose des coordonnées de votre capitale. Je m\’en vais chercher Silgryn et Valtrois, puis je vous retrouverai à Lune-d\’Argent.', 28153),
(143481, 'frFR', '', 'Je suis persuadée que le seigneur régent sera ravi de répondre à cette question. Êtes-vous prête à partir ?', 28153),
(143480, 'frFR', '', 'C\’est pourquoi je suis ravie de votre invitation à Lune-d\’Argent. J\’aimerais savoir s\’il y a une place pour les Sacrenuit dans votre Horde.', 28153),
(143479, 'frFR', '', 'L\’Alliance est trop fermée… trop hermétique. Et mon peuple refuse d\’endurer davantage d\’inertie.', 28153),
(143478, 'frFR', '', 'Tyrande et son peuple plein d\’orgueil méprisent les Sin\’dorei. Ils oublient qu\’ils dormaient dans des tanières et se cachaient dans les arbres à l\’époque où les miens se battaient déjà pour sauver le monde.', 28153),
(143477, 'frFR', '', 'Il semblerait que la « sagesse d\’Élune » ait altéré le lien qui nous unissait autrefois. Qu\’il en soit ainsi.', 28153),
(143476, 'frFR', '', 'Les Kaldorei combattront pour vaincre la Légion et détruire le Puits de la nuit. Ensuite… nous verrons où nous guidera la sagesse d\’Élune.', 28153),
(143475, 'frFR', '', 'Nous ne comptons pas devenir esclaves du Puits de la nuit. Nous voulons seulement chasser la Légion de Suramar et mettre fin à la tyrannie d\’Élisande.', 28153),
(143474, 'frFR', '', 'Arcaniste Thalyssra, je me rappelle la conduite de votre ordre lors de la guerre des Anciens. Qui nous dit que vous ne deviendrez pas une nouvelle Élisande, ou une nouvelle Azshara ?', 28153),
(143473, 'frFR', '', 'Je pensais que nos frères de Kalimdor seraient des alliés naturels. Mais leur arrogance et leur méfiance m\’ont rapidement détrompée.', 28153),
(143472, 'frFR', '', 'Je dois avouer avoir émis des doutes au sujet de la Horde, convaincue que nos intérêts divergeaient.', 28153),
(143471, 'frFR', '', 'Ce fut pour la Horde un honneur de combattre la Légion ardente à vos côtés, madame.', 28153),
(143470, 'frFR', '', 'Nous avons d\’ailleurs une dette envers vous. Vous avez joué un rôle décisif.', 28153),
(143469, 'frFR', '', 'Je suis heureuse de voir votre cité enfin libre, Première arcaniste.', 28153),
(143468, 'frFR', '', 'Salutations, dame Liadrin, $p. C\’est un plaisir de vous revoir et de vous accueillir à Suramar en des circonstances plus favorables.', 28153),
(143467, 'frFR', '', 'Décevant, mais il fallait s\’y attendre... Les Loas, ils ne t\’ont pas accordé leur bénédiction, mon enfant. Tu ne pourras pas nous rejoindre sur la terrasse de l\’Élu.', 28153),
(143466, 'frFR', 'Vous avez parcouru bien des lieues pour venir jusqu\’à moi, $gmon jeune ami:ma jeune amie;.$b$bJ\’ai plusieurs livres sur l\’histoire des crabes, cela vous intéresse ?', '', 28153),
(143465, 'frFR', '', 'Tenace et volontaire, tu sais épuiser tes ennemis et supporter toutes les tempêtes. Nous aurons besoin de ta force pour défendre notre cité.', 28153),
(143464, 'frFR', '', 'Voilà qui est... inhabituel. Ta force, elle sera précieuse dans les épreuves à venir.', 28153),
(143463, 'frFR', '', 'Égoïste et amoral... Tu ferais mieux de chercher une autre voie, mon enfant.', 28153),
(143462, 'frFR', '', 'Intéressant... Tu frappes depuis les ombres en combinant furtivité et ingéniosité. La surprise sera ta meilleure arme.', 28153),
(143461, 'frFR', '', 'Je vois. Tu es à la fois rapide et alerte. Et tu ne frappes pas à la légère. Ta patience sera récompensée.', 28153),
(143460, 'frFR', '', 'Plonge au plus profond de toi, mon enfant. Montre-moi comment tu traqueras ta proie. Utiliseras-tu la sagesse, la force ou autre chose encore ?', 28153),
(143459, 'frFR', '', 'La meute, elle t\’appelle à cor et à cri. Accepte son unité et pars chasser avec tes frères et sœurs.', 28153),
(143458, 'frFR', 'Vous sentez cette odeur ? Ça sent le chou.$b$b<Kronah se rapproche de vous et vous renifle.>$b$bC\’est pas vous, mais ça vient bien d\’ici.$b$bDites, vous vous y connaissez en calligraphie ? Vous voulez des leçons ? Croyez-le ou non, je suis maître scribe.', '', 28153),
(143457, 'frFR', 'Nous sommes attaqués !', 'Nous sommes attaqués !', 28153),
(143456, 'frFR', 'Sortez les armes, mes frères et sœurs !', 'Sortez les armes, mes frères et sœurs !', 28153),
(143455, 'frFR', 'L\’ennemi est parmi nous !', 'L\’ennemi est parmi nous !', 28153),
(143454, 'frFR', 'À l\’intrus ! Aux armes !', 'À l\’intrus ! Aux armes !', 28153),
(143452, 'frFR', 'Avec plaisir.', '', 28153),
(143451, 'frFR', 'Bougez-vous le train !', '', 28153),
(143450, 'frFR', 'On a des commandes à préparer !', '', 28153),
(143449, 'frFR', '', 'Veuillez ne pas distraire ces enfants, je vous prie.\n\nJe cherche à déceler en eux le moindre signe de l\’influence des Loas. Ceux qui portent leur bénédiction suivront la formation de prêtre et obtiendront les honneurs et privilèges dus à ce rang.\n\nLes autres se verront offrir l\’occasion de prouver qu\’ils peuvent devenir de puissants guerriers.\n\nQuant à ceux qui échouent dans l\’une et l\’autre de ces voies, ils ne nous sont d\’aucune utilité. Ils finiront probablement voleurs sur les quais ou mendiants dans le Zocalo.', 28153),
(143448, 'frFR', 'Ça peut se faire.', '', 28153),
(143447, 'frFR', 'D\’accord.', '', 28153),
(143446, 'frFR', 'Du boulot, encore du boulot !', '', 28153),
(143445, 'frFR', 'Il nous faut plus de bois !', '', 28153),
(143444, 'frFR', 'Vous aurez le temps de vous reposer quand vous serez morts. Pour l\’instant, on a des commandes à préparer !', '', 28153),
(143443, 'frFR', 'Je vais me hâter de regagner le village, avant de perdre pied. Avec un peu de chance, ils ne m\’auront pas oublié.', '', 28153),
(143442, 'frFR', 'Jamais je ne pourrai renouer avec ma vie passée, celle d\’un primate décérébré. Pas après tout ce que j\’ai vu et ressenti, si brève cette expérience fut-elle.', '', 28153),
(143441, 'frFR', 'Da\’ka avait raison. Je sens déjà mon esprit retrouver ses instincts primitifs.', '', 28153),
(143440, 'frFR', 'Bien le bonjour, $gvoyageur:voyageuse;. Que diriez-vous de jeter un coup d\’œil à mes parchemins ?$b$bÀ moins que vous ne préfériez des encres exotiques préparées à partir des herbes les plus rares ?', '', 28153),
(143439, 'frFR', 'Enfin, vu la taille de leurs cerveaux, faudra que vous remettiez ça pour qu\’ils impriment la leçon ceux-là.', '', 28153),
(143438, 'frFR', 'Vous avez collé une belle raclée à ces Gobelins ! Ça leur apprendra à chercher des noises aux Nains sombrefer !', '', 28153),
(143437, 'frFR', 'Démolissez leurs machines ! Bousillez leurs outils ! Et surtout, écrasez tous ces microbes !', '', 28153),
(143436, 'frFR', 'Ces maudits Gobelins nous volent de l\’azérite à grande échelle ! Il est grand temps que ça cesse !', '', 28153),
(143435, 'frFR', 'Hostefer est enfin à notre portée. Montrez à ces Gobelins ce qui arrive quand on vole aux Nains sombrefer !', '', 28153),
(143434, 'frFR', 'Qui c\’est qu\’est là ? Qui arrête les brumes ? Le roi Da\’ka va vous tuer !', '', 28153),
(143433, 'frFR', 'Pour la Horde !', 'Pour la Horde !', 28153),
(143432, 'frFR', 'P\’tit Tika jette un regard affamé aux cochons.', '', 28153),
(143431, 'frFR', 'P\’tit Tika se trémousse joyeusement.', '', 28153),
(143430, 'frFR', '', 'Où qu\’il est le gentil petit raptor dévoreur de méchants ? Il est là !', 28153),
(143429, 'frFR', '', 'Oh, ce que c\’est bon de te revoir, mon petit ! Merci, $n.', 28153),
(143428, 'frFR', '', 'C\’est Tika ?!?!', 28153),
(143427, 'frFR', 'P\’tit Tika roucoule gaiement.', '', 28153),
(143426, 'frFR', '', 'D\’autres… viendront…', 28153),
(143425, 'frFR', '', 'Le soleil se couche sur l\’empire zandalari. Les infidèles revendiqueront ce qu\’il en reste !', 28153),
(143424, 'frFR', 'Je vais vous faire écarteler pour avoir osé lever la main sur moi !', 'Je vous ferai noyer et écarteler pour cet affront !', 28153),
(143423, 'frFR', 'P\’tit Tika lève sa truffe et hume le vent avant de lâcher un cri perçant.', '', 28153),
(143422, 'frFR', 'Vous ploierez l\’échine devant votre reine, misérable !', 'Vous ploierez l\’échine devant votre reine, misérable !', 28153),
(143421, 'frFR', 'Elle vous… emportera… aussi…', 'Elle vous emportera… vous aussi…', 28153),
(143420, 'frFR', 'La maison Chantorage régnera sur ces terres !', 'La maison Chantorage régnera sur ces terres !', 28153),
(143419, 'frFR', '', 'Merci à vous deux ! $n, dès que ça fera effet, préparez-vous à pénétrer dans la grotte de Funeste-Venin pour prêter main-forte à Ben\’jin.', 28153),
(143418, 'frFR', '', 'J\’aurais pu fabriquer un appareil capable d\’analyser l\’activité cérébrale des brutosaures. Enfin, je dis ça, je dis rien.', 28153),
(143417, 'frFR', '', 'Seule la science nous apporte des réponses, Jangalar. Je ne veux pas dénigrer vos pouvoirs, mais vos superstitions ne remplaceront jamais un usage ferme et raisonné de l\’alchimie.', 28153),
(143416, 'frFR', 'On va montrer la puissance de la Horde à ces faiblards d\’Humains !', '', 28153),
(143415, 'frFR', 'Ces Humains feraient mieux de nous craindre, leur chair va faire connaissance avec nos haches !', '', 28153),
(143414, 'frFR', 'Pour la Horde !', '', 28153),
(143413, 'frFR', 'Je vais rentrer à Zuldazar… Ne vous en faites pas pour moi, je me débrouillerai tout seul. Passez me voir la prochaine fois que vous serez en ville.', '', 28153),
(143412, 'frFR', 'Attendez, Jin\’Tiki. Le raptor, prenez-le. Il… il a l\’air de vous préférer à moi, de toute façon.', '', 28153),
(143411, 'frFR', 'Ouvrez l\’œil ! Je veux pas voir ces Humains rôder autour de notre scierie !', '', 28153),
(143410, 'frFR', 'Remuez-vous !', '', 28153),
(143409, 'frFR', 'On en a fini ici. L\’heure est venue pour moi d\’achever mon voyage vers Vol\’dun et de payer pour mes crimes.', '', 28153),
(143408, 'frFR', 'Le premier que je surprends à roupiller au lieu de bosser, je le donne à bouffer aux loups de mes mains !', '', 28153),
(143407, 'frFR', 'Continuez à engranger les ressources !', '', 28153),
(143404, 'frFR', 'Votre fin… est proche…', 'Votre fin… est proche…', 28153),
(143403, 'frFR', 'Comment est-ce… possible…', 'Comment est-ce… possible…', 28153),
(143402, 'frFR', '', 'Vos bêtes, rassemblez-les et partez pour la ville. Je vous apporterai un panier de têtes de serpents quand on aura fini !', 28153),
(143401, 'frFR', 'La tempête vous frappera… à votre tour…', 'La tempête vous frappera… à votre tour…', 28153),
(143400, 'frFR', 'Les flots… vous emportent…', 'Les flots… vous emportent…', 28153),
(143399, 'frFR', 'Là. C\’est d\’là qu\’elles sortent, les brumes des profondeurs.', '', 28153),
(143398, 'frFR', 'Mon âme… retourne… à la mer…', 'Mon âme… retourne… à la mer…', 28153),
(143397, 'frFR', 'Mon voyage… se poursuit… sous les flots…', 'Mon voyage… se poursuit… sous les flots…', 28153),
(143396, 'frFR', 'Notre chef, ils l\’ont tué ! Il reste plus rien du village !', '', 28153),
(143395, 'frFR', 'L\’évent principal, il est à l\’intérieur. Venez vite !', '', 28153),
(143394, 'frFR', 'La marée puisse-t-elle m\’accueillir.', 'La marée puisse-t-elle m\’accueillir.', 28153),
(143391, 'frFR', 'Même les flots… se retirent…', 'Même les flots… se retirent…', 28153),
(143390, 'frFR', 'Sa puissance coule dans mes veines !', 'Sa puissance coule dans mes veines !', 28153),
(143389, 'frFR', 'Votre heure est venue !', 'Votre heure est venue !', 28153),
(143388, 'frFR', 'Nul n\’échappe à son destin !', 'Nul n\’échappe à son destin !', 28153),
(143387, 'frFR', 'Vous ne serez plus qu\’une coquille vide !', 'Vous ne serez plus qu\’une coquille vide !', 28153),
(143386, 'frFR', 'Les abysses vous attendent !', 'Les abysses vous attendent !', 28153),
(143385, 'frFR', 'Nul ne peut arrêter les flots infinis !', 'Nul ne peut arrêter les flots infinis !', 28153),
(143384, 'frFR', 'Entendez l\’appel des profondeurs !', 'Entendez l\’appel des profondeurs !', 28153),
(143383, 'frFR', 'La puissance de la mer va vous submerger.', 'La puissance de la mer va vous submerger.', 28153),
(143382, 'frFR', 'Ainsi succombe... le roi Da\’ka.', '', 28153),
(143381, 'frFR', '', 'Non… J\’étais promise à… de grandes choses…', 28153),
(143380, 'frFR', 'Misérable ! Tout comme une chandelle, vous n\’êtes $gbon:bonne; qu\’à brûler.', '', 28153),
(143379, 'frFR', '', 'Vous êtes robuste, mais le Sabbat aura raison de vous comme de tous les autres !', 28153),
(143378, 'frFR', '', 'Peu importe. Votre découverte vous coûtera la vie. À l\’attaque, serviteurs !', 28153),
(143377, 'frFR', '', 'Tiens, vous nous avez trouvés. Cela doit flatter votre ego.', 28153),
(143376, 'frFR', 'Ha ! Et à quoi donc servirait l\’intelligence si ce n\’est à nous conférer le pouvoir ? Bientôt, je régnerai sur Zandalar, tu verras. À moins que tu sois mort avant, bien sûr !', '', 28153),
(143375, 'frFR', 'Je suis venu arrêter cette folie, Da\’ka. Notre intelligence est contre nature, et c\’est la cause première de cette guerre !', '', 28153),
(143374, 'frFR', 'Tsunga... tu as conduit un être inférieur jusqu\’ici, au cœur des brumes sacrées. Pourquoi ?', '', 28153),
(143373, 'frFR', 'Que se passe-t-il ici ?', 'Que se passe-t-il ici ?', 28153),
(143372, 'frFR', 'La vérité réside… dans les abysses…', 'La vérité réside… dans les abysses…', 28153),
(143371, 'frFR', 'Mon sang et la mer ne font plus qu\’un…', 'Mon sang et la mer ne font plus qu\’un…', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143370, 'frFR', 'Allez. La source des brumes, elle est dans cette grotte. Par contre, j\’sais pas où qu\’il est, le roi Da\’ka, alors grouillez-vous !', '', 28153),
(143369, 'frFR', 'La magie du sang, elle est puissante par ici. Pas besoin d\’être féticheur pour la sentir dans l\’air… Il y en a partout…', '', 28153),
(143368, 'frFR', '', 'Oh… Qu\’est-ce qu\’$gun continental:une continentale; vient faire ici ?\n\nEn quoi puis-je vous aider ?', 28153),
(143367, 'frFR', 'Qui je dois tuer ?', '', 28153),
(143366, 'frFR', 'Taz\’dingo !', '', 28153),
(143365, 'frFR', 'Pour la Horde !', '', 28153),
(143364, 'frFR', 'L\’heure du carnage a sonné !', '', 28153),
(143363, 'frFR', 'Tuer, c\’est facile.', '', 28153),
(143362, 'frFR', 'Pas de pitié !', '', 28153),
(143361, 'frFR', 'Des têtes vont tomber !', '', 28153),
(143360, 'frFR', 'Gloire à la Horde !', '', 28153),
(143359, 'frFR', '', 'Gloire à la Horde !', 28153),
(143358, 'frFR', '', 'Des têtes vont tomber !', 28153),
(143357, 'frFR', '', 'Pas de pitié !', 28153),
(143356, 'frFR', 'Rien ne saurait… nous arrêter…', 'Rien ne saurait… nous arrêter…', 28153),
(143355, 'frFR', 'Ma mort ne change… rien…', 'Ma mort ne change… rien…', 28153),
(143354, 'frFR', 'Nous avons déjà… gagné…', 'Nous avons déjà… gagné…', 28153),
(143353, 'frFR', '', 'Tuer, c\’est facile.', 28153),
(143352, 'frFR', 'Je ne faisais que… suivre les ordres…', 'Je ne faisais que… suivre les ordres…', 28153),
(143351, 'frFR', 'Les eaugures… me protègent…', 'Les eaugures… me protègent…', 28153),
(143350, 'frFR', 'Ma vie… pour la mer…', 'Ma vie… pour la mer…', 28153),
(143349, 'frFR', 'Kul Tiras et la mer ne font qu\’un !', 'Kul Tiras et la mer ne font qu\’un !', 28153),
(143348, 'frFR', 'Vous osez vous opposer à la maison Chantorage ?', 'Vous osez vous opposer à la maison Chantorage ?', 28153),
(143347, 'frFR', 'Nous sommes implacables, comme la marée !', 'Nous sommes implacables, comme la marée !', 28153),
(143346, 'frFR', 'Mort à tous ceux qui nous résistent !', 'Mort à tous ceux qui nous résistent !', 28153),
(143345, 'frFR', 'Notre flotte va vous écraser !', 'Notre flotte va vous écraser !', 28153),
(143344, 'frFR', '', 'L\’heure du carnage a sonné !', 28153),
(143343, 'frFR', '', 'Venez vous battre, frangine !', 28153),
(143342, 'frFR', 'Sans nous, Kul Tiras ne serait que menu fretin !', 'Sans nous, Kul Tiras ne serait que menu fretin !', 28153),
(143341, 'frFR', '', 'Venez vous battre, frangin !', 28153),
(143340, 'frFR', 'Cette vallée nous appartient.', 'Cette vallée nous appartient.', 28153),
(143339, 'frFR', 'Au nom des Chantorage !', 'Au nom des Chantorage !', 28153),
(143338, 'frFR', '', 'Tous ces sauriens morts... Dire que je les ai élevés depuis leur naissance. C\’est comme si j\’avais perdu mes propres enfants.$b$bCes fumiers d\’hommes-serpents, ils vont me le payer cher.', 28153),
(143337, 'frFR', 'Corruption généralisée à tous les niveaux du bâtiment proche. Action urgente requise.', '', 28153),
(143336, 'frFR', 'Restauration partielle réussie. Progression impérative pour réparation du confinement de la corruption.', '', 28153),
(143335, 'frFR', 'Mise à niveau des systèmes auxiliaires. Veuillez patienter…', '', 28153),
(143334, 'frFR', 'Faites-vous des réparations ?', 'Faites-vous des réparations ?', 28153),
(143333, 'frFR', 'Le village, il est cuit, mais ma forge, faudra qu\’ils me passent sur le corps pour s\’en emparer.', '', 28153),
(143332, 'frFR', '', 'Pour la Horde !', 28153),
(143331, 'frFR', '', 'Taz\’dingo !', 28153),
(143330, 'frFR', '', 'Qui je dois tuer ?', 28153),
(143329, 'frFR', 'Je suis ravi que les innocents soient sains et saufs, mais il reste beaucoup à faire.', '', 28153),
(143328, 'frFR', '', 'Jusqu\’alors, je ne connaissais Hurlevent que dans les histoires. Je vais enfin pouvoir arpenter les rues et découvrir les merveilles qu\’elles recèlent. Que les ténèbres vous guident, $n.', 28153),
(143327, 'frFR', 'La Lumière soit avec vous, $n. Je compte pourchasser la Légion sur Azeroth afin de poursuivre notre éternel combat.', '', 28153),
(143326, 'frFR', 'Je ne vais pas le faire, évidemment, mais je l\’ai envisagé… pendant une seconde !', '', 28153),
(143325, 'frFR', 'Je dois admettre que j\’ai songé à vous donner une part du gâteau en vous voyant à l\’œuvre.', '', 28153),
(143324, 'frFR', 'Beau boulot ! Maintenant, passons aux choses sérieuses. Une fois que j\’aurai signé tous ces documents, je serai l\’heureux propriétaire de la mine, et ce, en toute légalité.', '', 28153),
(143323, 'frFR', 'Plus sérieusement, mieux vaut les détruire avant qu\’ils nuisent à mes bénéfices.', '', 28153),
(143322, 'frFR', 'Objectif atteint. Repositionnement vers une nouvelle position. Validation de l\’achèvement sur un nouvel emplacement.', '', 28153),
(143321, 'frFR', 'Ha ! Regardez-moi ces crétins se faire écraser. Ces élémentaires savent frapper où ça fait mal.', '', 28153),
(143320, 'frFR', 'P\’tit Tika pousse un minuscule grognement menaçant.', '', 28153),
(143319, 'frFR', 'P\’tit Tika piaille de terreur !', '', 28153),
(143318, 'frFR', 'Le monde saigne et vous aggravez ses blessures ?! C\’est la mort qui vous attend !', '', 28153),
(143317, 'frFR', 'Je veux voir des explosions, du chaos, de la violence brute ! Enfin, vous voyez quoi… ce que vous faites de mieux.', '', 28153),
(143316, 'frFR', 'Allez donc faire comprendre à la KapitalRisk que rien de ce qui leur appartient n\’est hors de ma portée.', '', 28153),
(143315, 'frFR', 'Il n\’y a qu\’un petit problème… elle ne m\’appartient pas ! C\’est là que vous entrez en jeu.', '', 28153),
(143314, 'frFR', 'Alors, c\’est donc d\’ici que vient l\’azérite qu\’on trouve au marché noir ? Ça m\’a l\’air lucratif comme affaire.', '', 28153),
(143313, 'frFR', '', '« Lycanthe », jamais entendu parler, mais… Un instant, qu\’est-ce que c\’est que ça ?', 28153),
(143312, 'frFR', 'Tu étais trop bon pour ce monde, mon frère. Je veillerai à ce que tu reçoives des funérailles dignes de ce nom.', '', 28153),
(143311, 'frFR', 'J\’aime l\’odeur du mojo au petit matin !', '', 28153),
(143310, 'frFR', '', 'Rokhan dit que vous avez l\’habitude de ce genre de choses. Faites votre possible. Je vais rester ici pour attendre la Brigade gob.', 28153),
(143308, 'frFR', '', '$n, nous avons plus que besoin d\’alliés. Aidez ce gardien aussi vite que possible.', 28153),
(143307, 'frFR', 'Assistance requise : réparation de Herzel. Veuillez rejoindre la structure proche. Confinement de la corruption en Nazmir.', '', 28153),
(143306, 'frFR', 'Corruption importante détectée en Nazmir. Activation du confinement requise.', '', 28153),
(143305, 'frFR', 'J\’en ai livré, des batailles… mais je n\’avais jamais vu un monstre pareil…', '', 28153),
(143304, 'frFR', 'Vous ne me prendrez jamais vivant !', '', 28153),
(143303, 'frFR', 'Cet endroit, il est plus dangereux que Vol\’dun, ma parole !', '', 28153),
(143302, 'frFR', 'Non ! Pas ça ! Les raptors… ils vont me manger tout cru !', '', 28153),
(143301, 'frFR', '… Merci, Zaluto. Peut-être que dans une autre vie, on aurait pu être frères.', '', 28153),
(143300, 'frFR', 'Le fétiche de sang, servez-vous-en sur Zulajin pour absorber son pouvoir et le renvoyer six pieds sous terre !', '', 28153),
(143299, 'frFR', 'Aucun problème ! Le capitaine, je vais lui faire son affaire pendant que vous nettoyez les ruines !', '', 28153),
(143298, 'frFR', 'Bien ! Maintenant, enfilez ce camouflage et allez récupérer la clé !', '', 28153),
(143297, 'frFR', 'Vous aurez besoin d\’un déguisement pour que Zulajin, il ne vous repère pas. Revenez dès que vous aurez ce qu\’il faut !', '', 28153),
(143296, 'frFR', 'Je suis peut-être un criminel, mais pas un mauvais bougre. Je ne vais pas vous laisser mourir ici !', '', 28153),
(143295, 'frFR', 'Grâce à vous, si je meurs… mon honneur sera sauf.', '', 28153),
(143294, 'frFR', 'Écoutez tous ! Levons nos verres aux vaillants <hips> champions qui vont tous nous sauver !', '', 28153),
(143293, 'frFR', '', 'Rendez-vous à Orgrimmar. Rejoignez nos alliés et construisez un nouvel avenir à leurs côtés.', 28153),
(143292, 'frFR', '', 'Quand vous sillonnerez les routes d\’Azeroth, racontez l\’histoire des fiers Sacrenuit… Faites savoir que nous sommes enfin sortis de notre isolement.', 28153),
(143291, 'frFR', 'Que savez-vous des Sacrenuit ?', 'Que savez-vous des Sacrenuit ?', 28153),
(143290, 'frFR', '', 'Je suis ravie de vous voir, $n. Nous devons convaincre le chef de guerre de rallier les Sacrenuit à notre cause.', 28153),
(143289, 'frFR', 'Que savez-vous des Taurens de Haut-Roc ?', 'Que savez-vous des Taurens de Haut-Roc ?', 28153),
(143288, 'frFR', '', 'C\’est maintenant à nous de montrer que nous pouvons apporter force et honneur à la Horde.', 28153),
(143287, 'frFR', 'Nous avons beaucoup de points communs avec les Taurens de Haut-Roc. Ils feront d\’excellents alliés le moment venu.', '', 28153),
(143286, 'frFR', '', 'Ne vous en faites pas pour Tsunga. On va s\’occuper de lui. Même s\’il a oublié jusqu\’à son propre nom.', 28153),
(143285, 'frFR', '', 'Mince alors, c\’était un gros, hein ? Beau travail, l\’$gami:amie; !', 28153),
(143284, 'frFR', '', 'Que les étoiles vous guident, $p. Je pense rejoindre les contreforts de Hautebrande. J\’ai eu vent d\’affaires étranges dans la région.', 28153),
(143283, 'frFR', '', 'T\’es bien sûr, Tsunga ? Tu sais c\’que tu perds, si $gce champion:cette championne; condamne la source des brumes ?', 28153),
(143282, 'frFR', 'Je vais préparer le rituel nécessaire à la libération de ces âmes. Rejoignez-moi sur la côte au nord d\’ici.', '', 28153),
(143281, 'frFR', 'Je suis pleinement conscient des conséquences, mais je suis convaincu que, si le renoncement est parfois douloureux, il n\’en reste pas moins légitime.', '', 28153),
(143280, 'frFR', 'Je vais emprunter un chemin détourné pour entrer dans la gorge et je vous retrouverai sur place.', '', 28153),
(143279, 'frFR', 'Restez en formation ! Les renforts sont en route. Nous devons empêcher les Nagas de détruire la digue !', '', 28153),
(143278, 'frFR', 'Puisse votre cœur haineux délaisser son fardeau.', '', 28153),
(143277, 'frFR', '', 'Mais les Sin\’dorei, les Elfes de sang, ont fait preuve de respect et de compréhension à notre égard. Ils nous ont donné la preuve que nos valeurs étaient partagées par d\’autres en Azeroth.', 28153),
(143276, 'frFR', '', 'Quand notre cité a connu ses heures les plus sombres, les héros d\’Azeroth ont repoussé la Légion à nos côtés. Certains à contrecœur…', 28153),
(143275, 'frFR', '', 'Je suis fière de vous remettre les traditionnels atours de Suramar. Portez-les en l\’honneur de notre passé… et de l\’avenir que nous allons façonner avec nos alliés.', 28153),
(143274, 'frFR', 'Entendu !', '', 28153),
(143273, 'frFR', '', 'Vous avez prouvé à la Horde et à tous les peuples d\’Azeroth que les Sacrenuit disposent de la volonté et du courage nécessaires pour défendre notre monde.', 28153),
(143272, 'frFR', 'Rejoignez la côte au nord des chantiers et trouvez Taelia, qui est au service de la garde des Portvaillant. Vite !', '', 28153),
(143271, 'frFR', '', 'Revenez à Suramar. Grâce à vous, notre peuple a retrouvé sa place dans ce monde, et nous tenons à vous remercier.', 28153),
(143270, 'frFR', '', 'Vous faites partie des premiers Shal\’dorei à avoir exploré les étendues d\’Azeroth. Il est temps pour vous de rentrer à la maison.', 28153),
(143269, 'frFR', 'Ces ouvriers… Ils sont retenus par la magie des eaugures ! Il faut les secourir.', '', 28153),
(143268, 'frFR', 'Les flots soient loués, il reste encore des gens sains d\’esprit ici ! Notre maison a perdu la tête !', '', 28153),
(143267, 'frFR', 'Je ne suis pas très flanelle.', 'Je ne suis pas très flanelle.', 28153),
(143266, 'frFR', '', 'Je vais partir en éclaireur. On se retrouve sur la côte !', 28153),
(143265, 'frFR', 'Ça vous va bien, $n.', '', 28153),
(143264, 'frFR', 'On a du boulot.', '', 28153),
(143263, 'frFR', 'Je trouvais justement que ma tenue manquait de flanelle.', 'Je trouvais justement que ma tenue manquait de flanelle.', 28153),
(143262, 'frFR', '', 'Aux armes !', 28153),
(143261, 'frFR', '', 'Pour le roi !', 28153),
(143260, 'frFR', '', 'Venez vous battre !', 28153),
(143259, 'frFR', '', 'Jusqu\’à la mort !', 28153),
(143258, 'frFR', '', 'Pour Hurlevent !', 28153),
(143257, 'frFR', '', 'Pour l\’Alliance !', 28153),
(143256, 'frFR', '', 'Pas de repli !', 28153),
(143255, 'frFR', '', 'Laissez-moi en découdre !', 28153),
(143254, 'frFR', '', 'De quelle corruption s\’agit-il ? $n, peut-être que cette chose considère les Trolls de sang comme une « corruption » ?', 28153),
(143253, 'frFR', '', '$n, vous savez ce que c\’est, cette chose ? Vous croyez qu\’elle voudra nous aider ?', 28153),
(143252, 'frFR', '', 'Quel est ce vaudou ? Il pourra peut-être nous aider à arrêter les Trolls de sang et G\’huun…', 28153),
(143251, 'frFR', 'Laissez-moi en découdre !', '', 28153),
(143250, 'frFR', 'Pas de repli !', '', 28153),
(143249, 'frFR', 'Pour l\’Alliance !', '', 28153),
(143248, 'frFR', 'Pour Hurlevent !', '', 28153),
(143247, 'frFR', 'Jusqu\’à la mort !', '', 28153),
(143246, 'frFR', 'Venez vous battre !', '', 28153),
(143245, 'frFR', 'Pour le roi !', '', 28153),
(143244, 'frFR', 'Aux armes !', '', 28153),
(143243, 'frFR', 'Wouah, le détecteur s\’affole complètement ! Il doit y avoir une sacrée éruption d\’azérite quelque part sur cette île.', '', 28153),
(143242, 'frFR', 'Nous devons découvrir l\’origine de ce sacrilège.', '', 28153),
(143241, 'frFR', '', 'Que cette armure vous rappelle ce que vous avez accompli, $p. Acceptez-la avec toute ma gratitude.', 28153),
(143240, 'frFR', 'Absolument.', '', 28153),
(143239, 'frFR', 'Est-ce que… vous pensez que les créatures marines seront aussi affectées ?', '', 28153),
(143238, 'frFR', 'Si vous aimez les signes de mauvais augure, en voilà un autre : la baie grouille de proies pour les Barges.', '', 28153),
(143237, 'frFR', 'Tsunga observe l\’entrée de la grotte d\’un air inquiet.', '', 28153),
(143236, 'frFR', '', 'Beaucoup doutaient que les Ren\’dorei soient capables de contrôler les pouvoirs du Vide sans y succomber. Vous êtes la preuve que nos détracteurs avaient tort.', 28153),
(143235, 'frFR', 'Le mugissement des vagues s\’intensifie à mesure que nous nous éloignons du bord. Je sens le tourment des marées. Un bien mauvais augure.', '', 28153),
(143234, 'frFR', '', 'Vous êtes désormais une arme redoutable au service de l\’Alliance, $p. Regagnez la faille du Vide et nous célébrerons votre réussite comme il se doit.', 28153),
(143233, 'frFR', 'Bien. Finissons-en.', '', 28153),
(143230, 'frFR', 'Je me charge de l\’entraîner. Vous, allez voir Tagart, il a une mission pour vous.', '', 28153),
(143229, 'frFR', 'Gardien des Titans Hezrel redémarré. Protocole : confinement de la corruption en Nazmir. Systèmes endommagés. Exécution impossible.', '', 28153),
(143228, 'frFR', '', 'Au cours de vos périples sur Azeroth, vous avez appris à maîtriser ces forces qui ne vous laissent aucun répit.', 28153),
(143227, 'frFR', 'Belle prise, $gl\’ami:l\’amie;. Voyons comment il vole. En piste !', '', 28153),
(143226, 'frFR', 'Oh oh ! Visez un peu ce qu\’on a là ! Incroyable !', '', 28153),
(143224, 'frFR', 'Je vais dire au roi Rastakhan qu\’on allumera les tours après avoir repris nos navires ! Comme ça, mon équipage, il saura qu\’il peut rentrer chez lui !', '', 28153),
(143223, 'frFR', 'Le sujet imposé est flou sur ce cliché. Wulfred n\’en voudra pas.', 'Le sujet imposé est flou sur ce cliché. Wulfred n\’en voudra pas.', 28153),
(143222, 'frFR', 'Aidez-moi, je vous en prie !', '', 28153),
(143221, 'frFR', 'Non ! Mes ouvriers… Tout est de ma faute.', '', 28153),
(143220, 'frFR', '', 'À l\’aide ! Le commandant est touché !', 28153),
(143219, 'frFR', 'Au secours ! On m\’attaque !', '', 28153),
(143218, 'frFR', 'Vous allez me le payer !', '', 28153),
(143217, 'frFR', 'Ce type commence à me friser la barbe !', '', 28153),
(143216, 'frFR', 'Noon ! Mon bonus 50 !', '', 28153),
(143215, 'frFR', 'À quoi je vous paye, bande d\’imbéciles ?! Venez ici et réparez-moi ça !', '', 28153),
(143214, 'frFR', 'Goûtez au carnage d\’un gros calibre !', '', 28153),
(143213, 'frFR', 'Admirez la puissance de l\’engin ! 300 balles à la minute !', '', 28153),
(143212, 'frFR', 'À mes pieds ! C\’est là qu\’est ta place !', '', 28153),
(143211, 'frFR', 'Mords la poussière !', '', 28153),
(143210, 'frFR', '', 'Je vais partir en reconnaissance et je vous retrouverai un peu plus loin !', 28153),
(143209, 'frFR', 'Vous ne m\’aurez jamais vivant !', '', 28153),
(143208, 'frFR', 'J\’aurais dû prendre… l\’option siège éjectable…', '', 28153),
(143207, 'frFR', 'Je vais réclamer un dédommagement à vos proches pour ces munitions !', '', 28153),
(143206, 'frFR', '', 'Servez-vous des leçons que je vous ai enseignées pour garder le contrôle. Devenez une arme de l\’Alliance… même si vous devez marcher sur le fil du rasoir.', 28153),
(143205, 'frFR', 'Certains douteront de vous. D\’autres remettront en question votre détermination, votre capacité à manier un pouvoir qui a causé la perte des plus faibles.', '', 28153),
(143204, 'frFR', '', 'Mais nous envisageons des alternatives, explorons d\’autres voies… Nous voyons les infinies possibilités qui s\’offrent à nous.', 28153),
(143203, 'frFR', '', 'Certains essaieront de vous convaincre que seule la Lumière peut nous apporter le salut et venir à bout des ennemis d\’Azeroth.', 28153),
(143202, 'frFR', 'Non mais vous vous rendez compte des dégâts matériels que vous avez provoqués ?!', '', 28153),
(143201, 'frFR', 'Bienvenue chez les Baroudeurs !', '', 28153),
(143200, 'frFR', 'Ce vieux serpent, il mentait pas. Allez, montez à bord. Le roi, il vous attend.', '', 28153),
(143199, 'frFR', 'Je vais vous écraser !', '', 28153),
(143198, 'frFR', 'Vous allez prendre cher !', '', 28153),
(143197, 'frFR', 'Je vais vous pulvériser !', '', 28153),
(143196, 'frFR', 'Si seulement j\’avais pu lui enseigner la leçon la plus importante de toutes.', '', 28153),
(143195, 'frFR', 'Dites au vieux Rastakhan que je reviendrai en temps voulu. Oh, et merci pour tout.', '', 28153),
(143193, 'frFR', 'Quand j\’aurai mis les griffes sur Yazma et Zul, je les lâcherai sur un rocher bien dur !', '', 28153),
(143192, 'frFR', 'Notre proie, elle est pas loin. Le sang de Zul, Yazma et de leurs hérétiques, il sera bientôt versé. Ça va être une grande chasse.', '', 28153),
(143191, 'frFR', 'Gloire à Pa\’ku !', 'Gloire à Pa\’ku !', 28153),
(143190, 'frFR', 'Ce vaisseau, il sera à nous !', 'Ce vaisseau, il sera à nous !', 28153),
(143189, 'frFR', 'Taz\’okun !', 'Taz\’okun !', 28153),
(143188, 'frFR', 'Ce n\’est qu\’une égratignure. Je m\’en remettrai…', '', 28153),
(143185, 'frFR', '', 'Vous allez partir en fumée !', 28153),
(143184, 'frFR', '', 'Brûlez ! Oui, brûlez !', 28153),
(143183, 'frFR', '', 'C\’est de l\’azérite que vous cherchez ? Tenez, prenez donc ça !', 28153),
(143182, 'frFR', '', 'Et une mort atroce de plus au compteur, une !', 28153),
(143181, 'frFR', 'Ça vaut vraiment pas le coup !', '', 28153),
(143180, 'frFR', '', 'Le manque d\’expérience est la première cause de mortalité !', 28153),
(143179, 'frFR', 'Pour l\’Alliance !', '', 28153),
(143178, 'frFR', '', 'C\’est un honneur de vous servir une fois encore, haut roi. Pour l\’Alliance !', 28153),
(143177, 'frFR', '', 'Encore un candidat non qualifié !', 28153),
(143176, 'frFR', 'Vous nous avez rendu un fier service aujourd\’hui. Dame Coursevent, $p, je vous remercie.', '', 28153),
(143175, 'frFR', 'Les Elfes du Vide devront peut-être gagner la confiance de certains des nôtres. Toutefois, tant qu\’ils observent nos préceptes, ils sont les bienvenus dans l\’Alliance.', '', 28153),
(143174, 'frFR', '', 'Et dire que j\’avais… même pas… de prime de risque…', 28153),
(143173, 'frFR', '', 'Je serai leur guide et leur apprendrai à dominer les murmures des ténèbres. En retour, ils combattront les ennemis de l\’Alliance.', 28153),
(143172, 'frFR', '', 'Haut roi Wrynn, nous avons retrouvé les exilés sin\’dorei. Tout comme moi, le Vide les a changés, mais leur cœur et leur esprit restent intacts.', 28153),
(143171, 'frFR', '', 'Si vous voulez que le boulot soit bien fait, utilisez de plus gros explosifs !', 28153),
(143170, 'frFR', '', 'C\’est à cause de vous que mes employés se sont carapatés ?', 28153),
(143169, 'frFR', '', 'Hé, là ! Où croyez-vous aller comme ça ?', 28153),
(143168, 'frFR', 'Des intrus ?! Fuyez !!!', 'Des intrus ?! Fuyez !!!', 28153),
(143167, 'frFR', 'J\’ignore quelles ténèbres t\’ont obscurci l\’esprit, ma sœur, mais elles ne tourmenteront plus les nôtres.', '', 28153),
(143166, 'frFR', 'Vous assurez !', '', 28153),
(143165, 'frFR', 'Fuyez !', '', 28153),
(143164, 'frFR', '', 'Je ne veux plus entendre une seule plainte sur les conditions de travail !', 28153),
(143163, 'frFR', 'Cet endroit est dangereux, vous devez partir.', '', 28153),
(143162, 'frFR', 'Cette île n\’en vaut pas le coup, de toute façon !', '', 28153),
(143161, 'frFR', 'Nous sommes condamnés !', '', 28153),
(143160, 'frFR', 'Partez ! Plus rien ne vous retient ici.', '', 28153),
(143159, 'frFR', 'Il s\’est libéré ! Reculez !', '', 28153),
(143158, 'frFR', 'Vous êtes libres, mes frères et sœurs.', '', 28153),
(143157, 'frFR', '', 'Quand on se plaint, on ne retient pas sa respiration ! C\’est donc votre faute si vous respirez des fumées toxiques.', 28153),
(143156, 'frFR', 'Rentrez chez vous. Nous avons la situation en main.', '', 28153),
(143155, 'frFR', 'Fuyez, pauvres fous !', '', 28153),
(143154, 'frFR', 'Renoncez à la chair, mortels, et dans les eaux.', '', 28153),
(143153, 'frFR', 'Et le chant de l\’orage qui apporte la paix.', '', 28153),
(143152, 'frFR', 'Voyez le phare briller, dans le brouillard épais.', '', 28153),
(143151, 'frFR', '', 'Pour la Horde !', 28153),
(143150, 'frFR', '', 'Pour la Horde !', 28153),
(143149, 'frFR', '', 'Suramar combattra pour la Horde !', 28153),
(143148, 'frFR', '', 'Pendant des millénaires, Suramar a combattu seule. Vous embrassez aujourd\’hui une cause plus grande. J\’accepte votre serment d\’allégeance, Thalyssra.', 28153),
(143147, 'frFR', '', 'L\’heure est venue pour les Sacrenuit de trouver des alliés parmi les royaumes d\’Azeroth. Si vous acceptez notre allégeance, nous serons honorés de rejoindre vos rangs.', 28153),
(143146, 'frFR', '', 'La Horde incarne une puissance irrépressible, une détermination sans faille et une identité forte. Des traits que nous, Shal\’dorei, tenons en haute estime.', 28153),
(143145, 'frFR', '', 'En effet, Première arcaniste.', 28153),
(143144, 'frFR', '', 'C\’est un honneur, chef de guerre. J\’ai combattu aux côtés de dame Liadrin et du seigneur régent. Leur courage fait honneur à votre Horde.', 28153),
(143143, 'frFR', 'Non, jamais une vague ne juge aux faux-semblants.', '', 28153),
(143142, 'frFR', 'Des rivières aux mers, s\’écoulent les tourments,', '', 28153),
(143141, 'frFR', 'Ainsi l\’esprit intrépide repose à jamais.', '', 28153),
(143140, 'frFR', 'Puisse l\’abysse accueillir les âmes harassées.', '', 28153),
(143139, 'frFR', 'Par la mère des marées la chair est purifiée.', '', 28153),
(143138, 'frFR', 'Les courants porteront ceux qui ont succombé.', '', 28153),
(143137, 'frFR', 'Le sol va vous engloutir !', '', 28153),
(143136, 'frFR', 'De la mer à la mer, du sable au sable, des marées aux marées.', '', 28153),
(143135, 'frFR', 'Je vais vous briser !', '', 28153),
(143134, 'frFR', 'Le sang d\’Azeroth coule dans tes veines !', '', 28153),
(143133, 'frFR', 'Nous devons faire quelque chose pour ces âmes égarées. J\’aimerais vous parler, $p.', '', 28153),
(143132, 'frFR', 'Déchaîne ta puissance !', '', 28153),
(143131, 'frFR', 'Un peu détrempé, mais toujours lisible. Ces incantations nous seront bien utiles.', '', 28153),
(143130, 'frFR', 'Les brumes de l\’océan cachent bien des mystères, mais ce fanal nous permettra de les atteindre.', '', 28153),
(143129, 'frFR', 'Debout !', '', 28153),
(143128, 'frFR', '', 'Bienvenue, mon enfant. J\’ai beau avoir perdu la vue, Pa\’ku ne m\’a pas abandonnée pour autant.\n\nAsseyez-vous à mes côtés et posez-moi vos questions sur la grande Loa. Je ferai de mon mieux pour y répondre.', 28153),
(143127, 'frFR', 'Parfait, elle est encore affûtée. Une lame affûtée est une lame sans danger… pour celui qui la manie.', '', 28153),
(143126, 'frFR', 'Vous ne blesserez plus personne.', '', 28153),
(143125, 'frFR', 'C\’est là toute la valeur de votre sang ?', '', 28153),
(143124, 'frFR', '', 'Chef de guerre Sylvanas Coursevent, je vous présente la Première arcaniste Thalyssra de Suramar.', 28153),
(143123, 'frFR', '', 'Je vais rejoindre les autres et attendre vos directives, $c.', 28153),
(143122, 'frFR', '', 'J\’en doute fort… mais j\’obéirai aux ordres.', 28153),
(143121, 'frFR', '', 'Ainsi le maréchal Reade pense que vous pouvez nous aider à repousser le Sabbat ?', 28153),
(143120, 'frFR', 'Mettez-y du vôtre !', '', 28153),
(143119, 'frFR', 'J\’ai failli attendre.', '', 28153),
(143118, 'frFR', 'Du nerf !', '', 28153),
(143117, 'frFR', 'Oh hisse !', '', 28153),
(143116, 'frFR', 'Viens, Winston. On a des sorcières à éliminer.', '', 28153),
(143115, 'frFR', 'Encore quelques entailles et ce sera bon.', '', 28153),
(143114, 'frFR', 'Elle y est presque ! Encore un petit effort.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143113, 'frFR', 'De nouveaux ordres ?', '', 28153),
(143112, 'frFR', 'Merci de m\’avoir fait parvenir ces ordres, $c. Je m\’en vais rendre compte à mademoiselle Malvoie de ce pas.', '', 28153),
(143111, 'frFR', 'Et moi qui croyais qu\’il s\’agissait de fables d\’historiens à l\’imagination trop fertile.', '', 28153),
(143110, 'frFR', 'Vous n\’étiez que des parasites.', '', 28153),
(143109, 'frFR', 'Les rumeurs disaient donc vrai ? L\’ordre des Braises s\’est reformé ?', '', 28153),
(143108, 'frFR', 'Les blessures… doivent être guéries…', '', 28153),
(143107, 'frFR', '', 'Ma lame est à votre service, $c.', 28153),
(143106, 'frFR', 'Vous êtes sur mes terres !', '', 28153),
(143105, 'frFR', '', 'Je ne crois pas un mot de vos histoires à dormir debout, mais je refuse d\’attendre patiemment que le Sabbat nous massacre tous.', 28153),
(143104, 'frFR', '', 'C\’est donc vous qui êtes derrière ce fameux « ordre des Braises » dont tout le monde parle.', 28153),
(143103, 'frFR', '<Tendre les ordres du maréchal Reade.>', '<Tendre les ordres du maréchal Reade.>', 28153),
(143102, 'frFR', '', 'Et là les assemblages prennent part aux affrontements. Il a fondé une nouvelle armée par manque de guerriers de chair et d\’os. Mais d\’où tiraient-ils leur puissance ?', 28153),
(143101, 'frFR', '', 'Que puis-je faire pour vous, $c ?', 28153),
(143100, 'frFR', '', 'Il s\’agit bien de Gorak Tul, leur plus grand chef. Ah ! Il se livre à un rituel pour donner vie aux assemblages de pierre !', 28153),
(143099, 'frFR', '<Le lieutenant Brislame fait un petit signe de tête à votre approche.>', '', 28153),
(143098, 'frFR', 'Magnifique spécimen, n\’est-ce pas ? La fauconnerie est une spécialité ancestrale de la maison Malvoie.\n\nMalheureusement, la plupart de nos plus beaux rapaces ont succombé à la malédiction du Sabbat. Winston est l\’un des derniers à avoir résisté à son sortilège.\n\nQuelle tragédie…', '', 28153),
(143097, 'frFR', '', 'Et voilà qu\’ils célèbrent le massacre ! Les Kultirassiens n\’étaient même pas armés !', 28153),
(143096, 'frFR', 'Quelque chose s\’agite dans la forêt. La nuit venue, l\’antique monument drust brille d\’une puissance impie.\n\nÀ votre place, je ferais un sacré détour pour éviter cet endroit.', '', 28153),
(143095, 'frFR', '', 'Qu\’y a-t-il ?\n\nJe suis très occupée, au cas où vous ne l\’auriez pas remarqué.', 28153),
(143094, 'frFR', 'ÉLIMINER LA SOURCE DE L\’INTRUSION. ÉP… ÉPURATION.', '', 28153),
(143093, 'frFR', 'LIBÉRATION DE LA CORRUPTION IMMINENTE. ACT… ACTIVATION DES PROTOCOLES DE SÉC… SÉCURITÉ. INT… INTRUSION REPÉRÉE.', '', 28153),
(143092, 'frFR', 'ERREUR… INTRUSION… DÉT-DÉTECTÉE… RECHERCHE DE… CORRUPTION EN COURS…', '', 28153),
(143091, 'frFR', 'Utilisation de gaz nocif autorisée.', '', 28153),
(143090, 'frFR', 'Tension augmentée.', '', 28153),
(143089, 'frFR', 'Systèmes enclenchés. Initialisation du combat.', '', 28153),
(143088, 'frFR', '', 'Les Kultirassiens sur cette stèle ont l\’air de… civils. À moins qu\’il ne s\’agisse de marins… ou de fermiers.', 28153),
(143087, 'frFR', '', 'Même leur chef fuit le champ de bataille.', 28153),
(143086, 'frFR', '', 'Ha ! Et là, nous contre-attaquons !', 28153),
(143085, 'frFR', '', 'Intéressant. Je ne vois aucun de leurs assemblages sur le champ de bataille.', 28153),
(143084, 'frFR', 'La KapitalRisk vous remercie de votre confiance et espère que vous apprécierez votre pack de dispersion premium.', '', 28153),
(143083, 'frFR', '', 'Ici, on voit une victoire sur une autre implantation kultirassienne. Le personnage au centre est sans doute leur chef légendaire.', 28153),
(143082, 'frFR', 'La KapitalRisk vous remercie de votre confiance et espère que vous apprécierez votre pack de dispersion de base.', '', 28153),
(143081, 'frFR', 'Laissez-moi quelques mois, et je vous transforme ce lieu en un complexe six étoiles !', '', 28153),
(143080, 'frFR', 'Imbécile ! Faut JAMAIS prendre l\’extension de garantie !', 'Imbécile ! Faut JAMAIS prendre l\’extension de garantie !', 28153),
(143079, 'frFR', 'OK, OK ! Attendez… Vous croyez que ça vaut le coup de prendre une extension de garantie ?', 'OK, OK ! Attendez… Vous croyez que ça vaut le coup de prendre une extension de garantie ?', 28153),
(143078, 'frFR', 'Venez, $p.', '', 28153),
(143077, 'frFR', 'Ils vont nous tuer !', 'Ils vont nous tuer !', 28153),
(143076, 'frFR', 'Me bousculez pas ! Je lis les termes du contrat !', 'Me bousculez pas ! Je lis les termes du contrat !', 28153),
(143075, 'frFR', 'Vite ! Ils arrivent !', 'Vite ! Ils arrivent !', 28153),
(143074, 'frFR', 'J\’avais juste besoin de faire une petite pause.', '', 28153),
(143073, 'frFR', 'Tout doux, bijou. Tout doux.', '', 28153),
(143072, 'frFR', 'Échec des… systèmes. Cet appareil ne rend pas la monnaie…', '', 28153),
(143071, 'frFR', 'Qui veut aller se dégourdir les ailes, hein, qui ? Allez, ma cocotte, en piste !', '', 28153),
(143070, 'frFR', 'On ne mord pas !', '', 28153),
(143069, 'frFR', 'Procédure de contrôle des dégâts enclenchée.', '', 28153),
(143068, 'frFR', 'Infliger des dégâts à la machine enfreint les conditions d\’utilisation.', '', 28153),
(143067, 'frFR', 'Largage !', 'Largage !', 28153),
(143066, 'frFR', 'Chaud devant, ordures !', 'Attention la tête, bande de fumiers !', 28153),
(143065, 'frFR', 'Vous, là ! On se remet au boulot !', 'Vous, là ! On se remet au boulot !', 28153),
(143064, 'frFR', 'Protocole d\’exécution autorisé.', '', 28153),
(143063, 'frFR', 'Niveau maximal d\’occupation atteint. Dispersion de la foule.', '', 28153),
(143062, 'frFR', 'Services funéraires disponibles pour une somme modique.', '', 28153),
(143061, 'frFR', 'Encore un client satisfait.', '', 28153),
(143060, 'frFR', 'La KapitalRisk décline toute responsabilité en cas de perte ou d\’amputation des membres.', '', 28153),
(143059, 'frFR', 'La Horde s\’est défendue contre un assaut !', 'La Horde s\’est défendue contre un assaut !', 28153),
(143058, 'frFR', 'Et dispersez-vous ! Ces chiens de l\’Alliance vont sûrement envoyer des renforts par ici.', '', 28153),
(143057, 'frFR', '', 'Quand ce bateau, il aura capturé le port, je serai capitaine ! Alors z\’avez intérêt à m\’obéir et à travailler vos courbettes !', 28153),
(143056, 'frFR', '', 'Ces prisonniers, ils savent pas la chance qu\’ils ont ! Ils vont bientôt rejoindre Zul.', 28153),
(143055, 'frFR', '', 'Si on veut avoir une chance de le prendre, ce port, va falloir faire mieux que ça !', 28153),
(143054, 'frFR', 'Je ne peux... pas... AAAAARGH !', '', 28153),
(143050, 'frFR', 'Non ! Je ne mourrai pas ici ! Ça ne devait pas se passer comme ça !', '', 28153),
(143049, 'frFR', 'Comment… a-t-il su…', '', 28153),
(143048, 'frFR', 'C\’est… c\’est impossible !', '', 28153),
(143047, 'frFR', 'Je reconnais votre force, mais elle n\’est rien comparée à celle de ma vision !', '', 28153),
(143046, 'frFR', 'Éloignez-vous ! C\’est un ordre !', '', 28153),
(143045, 'frFR', 'Fidèles ! Votre maître a besoin de vous !', '', 28153),
(143044, 'frFR', 'C\’est vous qui allez mourir ici !', '', 28153),
(143043, 'frFR', 'Tu crois avoir une longueur d\’avance, vieux fou ?', '', 28153),
(143042, 'frFR', 'Tu as raison. Je ne peux pas. Mais mon $Uami:amie; le peut.', '', 28153),
(143041, 'frFR', 'On sait tous les deux que tu me tueras pas. Tu ne peux pas m\’arrêter.', '', 28153),
(143040, 'frFR', 'Brave bête. C\’est bientôt l\’heure du goûter !', '', 28153),
(143039, 'frFR', 'Ce petit jeu me fatigue. Maintenant que tu as transmis ton message, tu vas affronter ton destin.', '', 28153),
(143038, 'frFR', 'Zul boit la potion d\’une traite puis frissonne de dégoût.', '', 28153),
(143037, 'frFR', 'Prenez la première qui vous tombe sous la main. Pas besoin de réfléchir.', '', 28153),
(143036, 'frFR', 'Ses serviteurs, ils essaieront de vous arrêter. Restez sur vos gardes.', '', 28153),
(143035, 'frFR', 'Hum.', '', 28153),
(143034, 'frFR', 'Venez ici. L\’heure est venue.', '', 28153),
(143033, 'frFR', 'Parfait. Maintenant, échangez une potion de Vol\’jamba avec celle que je vous ai donnée.', '', 28153),
(143032, 'frFR', 'Tout bien réfléchi, mettez-la un peu plus à gauche.', '', 28153),
(143031, 'frFR', 'Maintenant, placez l\’urne près de l\’arche.', '', 28153),
(143030, 'frFR', 'Gardez toujours vos armes à portée de main hors de l\’ambassade, $p. Les Zandalari n\’ont ni la force ni la volonté de faire régner l\’ordre. Ils auraient bien besoin d\’un chef de guerre aussi strict que le nôtre.\n\nEnfin, qu\’est-ce que je peux faire pour vous ?', 'Gardez toujours vos armes à portée de main hors de l\’ambassade, $p. Les Zandalari n\’ont ni la force ni la volonté de faire régner l\’ordre. Ils auraient bien besoin d\’un chef de guerre aussi strict que le nôtre.\n\nEnfin, qu\’est-ce que je peux faire pour vous ?', 28153),
(143029, 'frFR', 'Si vous repérez des membres de l\’Alliance qui rôdent dans les parages, prévenez-moi. Je m\’en occuperai.\n\nEn attendant, je peux peut-être vous aider ?', 'Si vous repérez des membres de l\’Alliance qui rôdent dans les parages, prévenez-moi. Je m\’en occuperai.\n\nEn attendant, je peux peut-être vous aider ?', 28153),
(143028, 'frFR', 'Le moins qu\’on puisse dire des Zandalari, c\’est qu\’ils savent bâtir des ambassades. Sans compter que cette ville est énorme !\n\nVous cherchez votre chemin ?', 'Le moins qu\’on puisse dire des Zandalari, c\’est qu\’ils savent bâtir des ambassades. Sans compter que cette ville est énorme !\n\nVous cherchez votre chemin ?', 28153),
(143027, 'frFR', 'J\’ai à faire. Alors allez droit au but.', 'J\’ai à faire. Alors allez droit au but.', 28153),
(143026, 'frFR', 'De quoi avez-vous besoin, $pr ?', 'De quoi avez-vous besoin, $pr ?', 28153),
(143025, 'frFR', 'Gloire à notre chef de guerre ! Vous cherchez quelque chose ?', 'Gloire à notre chef de guerre ! Vous cherchez quelque chose ?', 28153),
(143024, 'frFR', 'Cette ambassade monumentale prouve que les Zandalari respectent la force de notre chef de guerre. Ils feraient bien de la craindre, également.\n\nAlors, qu\’est-ce que vous voulez ?', 'Cette ambassade monumentale prouve que les Zandalari respectent la force de notre chef de guerre. Ils feraient bien de la craindre, également.\n\nAlors, qu\’est-ce que vous voulez ?', 28153),
(143023, 'frFR', 'Avec cette humidité, je sue sang et os. Qu\’est-ce que je peux faire pour vous ?', 'Avec cette humidité, je sue sang et os. Qu\’est-ce que je peux faire pour vous ?', 28153),
(143022, 'frFR', 'On grimpe les échelons, mon gaillard. Un de ces quatre, tout ça, ce sera à nous.', '', 28153),
(143021, 'frFR', 'Vous croyez qu\’on vous paie pour vous tourner les pouces ?', '', 28153),
(143020, 'frFR', '', 'Peut-être la mort est-elle le véritable héritage des Coursevent.', 28153),
(143019, 'frFR', '', 'C\’est vrai. Parfois, j\’ai l\’impression d\’avoir déjà perdu deux fois la vie. La première, quand nous avons été portés disparus sur Draenor. La deuxième, quand les ténèbres du Naaru corrompu m\’ont envahie.', 28153),
(143018, 'frFR', 'Ces statues à notre mémoire sont troublantes.', '', 28153),
(143017, 'frFR', '', 'Il est temps, Turalyon. Je dois revoir la terre qui m\’a vue naître… et entendre de la bouche de Sylvanas les raisons qui l\’ont conduite à endosser le rôle de chef de guerre.', 28153),
(143016, 'frFR', 'Chacune de vous suit son propre chemin. Si la Lumière veut qu\’ils se croisent, il en sera ainsi. Inutile de forcer le destin.', '', 28153),
(143015, 'frFR', 'Rien ne t\’oblige à partir. À aller la voir.', '', 28153),
(143014, 'frFR', '', 'Mieux que quiconque, mon amour.', 28153),
(143013, 'frFR', 'Tu es nerveuse… Tu le caches bien… mais je te connais.', '', 28153),
(143012, 'frFR', 'De nombreux combats vous attendent, mais quoi qu\’il arrive… n\’oubliez jamais votre devoir envers Azeroth !', '', 28153),
(143011, 'frFR', 'Cette énergie qui parcourt votre arme… je n\’avais jamais vu rien de tel ! Mais souvenez-vous-en, le pouvoir a toujours un coût.', '', 28153),
(143010, 'frFR', 'Vous avez réussi ! L\’épée de Sargeras est neutralisée. Azeroth est loin d\’être guérie… mais nous avons gagné un temps précieux.', '', 28153),
(143009, 'frFR', 'Tous ensemble, champions ! Pour Azeroth !', '', 28153),
(143008, 'frFR', 'Unissez-vous et brandissez-les… Extirpez la corruption de la lame du Titan noir !', '', 28153),
(143007, 'frFR', 'Seules les armes que vous portez sont capables de contenir un tel pouvoir.', '', 28153),
(143006, 'frFR', 'L\’épée de Sargeras empoisonne l\’essence vitale de notre planète.', '', 28153),
(143005, 'frFR', 'Rejoignez Silithus… tant qu\’il nous reste un monde à défendre !', '', 28153),
(143004, 'frFR', 'Les tensions s\’intensifient, oui… mais je vous demande de mettre vos différends de côté une fois encore.', '', 28153),
(143003, 'frFR', 'Champions, vous avez combattu ensemble et libéré Azeroth de la Légion.', '', 28153),
(143002, 'frFR', 'L\’heure est grave, $p. Si nous ne trouvons pas un moyen de soigner Azeroth… plus rien n\’aura d\’importance.', '', 28153),
(143001, 'frFR', 'Je ne sais pas comment y remédier. Je crois que personne ne le sait. Mais nous devons persévérer.', '', 28153),
(143000, 'frFR', 'Depuis notre retour d\’Argus, les cris d\’Azeroth m\’accablent. Sa souffrance est immense…', '', 28153),
(142999, 'frFR', 'Il est bon de voir un visage familier en ces heures sombres.', '', 28153),
(142998, 'frFR', 'On les attend toujours, princesse. On a aussi des informations sur Krag\’wa, le Loa.', '', 28153),
(142997, 'frFR', '', '… voilà ce qui est arrivé à Torga. Il y a des nouvelles des renforts de la Horde ?', 28153),
(142996, 'frFR', 'On y est presque, $n. Encore un petit effort.', '', 28153),
(142995, 'frFR', 'Je n\’arrive pas à croire que ces monstres aient éventré Torga…', '', 28153),
(142994, 'frFR', 'Misère… Torga est mort et je n\’ai pas l\’ombre d\’une petite histoire à raconter aux autres.', '', 28153),
(142993, 'frFR', 'Où est Kisha ? Je croyais qu\’elle serait là pour nous guider…', '', 28153),
(142992, 'frFR', 'Très bien, je vais me rendre à Glaucombe, histoire d\’assister au clou du spectacle.', '', 28153),
(142991, 'frFR', 'Euh… Un combat acharné contre une horde de Trolls de sang… Ma foi, il y a là matière à une bonne histoire. En route pour Glaucombe.', '', 28153),
(142990, 'frFR', 'Vous avez fait… QUOI ? Hors de question que je loupe cette histoire. Vite, en route pour Glaucombe !', '', 28153),
(142989, 'frFR', 'Allez, Kisha. En route pour Glaucombe, et nous rallierons tous les Tortollans que nous croiserons en chemin. $n s\’occupera de ceux que nous aurons ratés.', '', 28153),
(142988, 'frFR', '', 'Je vais me rendre à Glaucombe et vous vous occuperez des Tortollans en chemin.', 28153),
(142987, 'frFR', '$n, faites tonner ces canons !', '', 28153),
(142986, 'frFR', 'Bonne chance, $p. En ce qui me concerne, je m\’en vais mettre mes talents à l\’épreuve à Orneval. Pour la Horde !', '', 28153),
(142985, 'frFR', 'Le Souffle de Pa\’ku et la Griffe de Rezan, ils ont fait le tour du monde et puis ils sont revenus. Faut les aider à rentrer à bon port.', '', 28153),
(142984, 'frFR', 'Quand les navires, ils sont revenus, ils étaient comme voilés par les ténèbres. J\’ai senti tout de suite que ça allait mal tourner.', '', 28153),
(142983, 'frFR', 'Le Souffle de Pa\’ku, j\’ai vécu à son bord pendant des années. Quand il a levé l\’ancre, mon cœur, il était comme ce port… vide.', '', 28153),
(142982, 'frFR', 'Le rugissement d\’Anji le Fulminant vous emplit de vigueur.', '', 28153),
(142981, 'frFR', 'Hé ! Grimpez vite ! Le capitaine, il dit que le Souffle de Pa\’ku, il a des ennuis !', '', 28153),
(142980, 'frFR', '', 'Commandant, nous venons apporter notre aide. La digue tiendra bon !', 28153),
(142979, 'frFR', '', 'Allons à la digue. Le commandant Reed n\’est pas du genre patient !', 28153),
(142977, 'frFR', 'Vous êtes indigne de ce lieu !', '', 28153),
(142976, 'frFR', 'Vous n\’êtes qu\’$gun:une; veule maroufle !', '', 28153),
(142975, 'frFR', 'Vous ne m\’inspirez que mépris, turpide vermine !', '', 28153),
(142974, 'frFR', 'Hors de ma vue, $gmaraud:maraude; !', '', 28153),
(142973, 'frFR', 'Préparez-vous à subir un châtiment particulièrement musclé !', '', 28153),
(142972, 'frFR', 'Je vous tarauderai jusqu\’à ne plus entendre que vos lamentations !', '', 28153),
(142971, 'frFR', 'Je déchausserai toutes vos dents d\’une main !', '', 28153),
(142970, 'frFR', 'Garde à vous !', '', 28153),
(142969, 'frFR', '', 'En vertu du pouvoir conféré à la maison Malvoie, je vous nomme inquisiteurs de l\’ordre des Braises.', 28153),
(142968, 'frFR', '', 'Vous symbolisez l\’espoir face à l\’adversité.', 28153),
(142967, 'frFR', '', 'Vous personnifiez la lame qui pourfend le mal.', 28153),
(142966, 'frFR', '', 'Mes frères et mes sœurs, à partir de ce jour, vous incarnez le feu qui consume les ténèbres.', 28153),
(142965, 'frFR', '', 'Ah, le voilà.', 28153),
(142964, 'frFR', '', 'Il me semble avoir vu un discours d\’initiation quelque part dans le recueil…', 28153),
(142963, 'frFR', '', 'Merci de m\’avoir confié vos hommes, maréchal. Notre ordre a désormais fière allure !', 28153),
(142962, 'frFR', 'Ça fait des jours que j\’attends de voir le roi. Je pensais qu\’il serait impatient de savoir ce que les Gobelins fabriquent sur ces terres.', '', 28153),
(142961, 'frFR', 'Nombre de mes hommes postés ici feraient d\’excellentes recrues pour votre ordre des Braises.', '', 28153),
(142960, 'frFR', '', 'Maréchal, je pense savoir quelles armes utiliser contre le Sabbat. Mais nous aurons besoin de vos soldats les plus aguerris.', 28153),
(142959, 'frFR', 'Les Loas et la ville, jamais je ne les trahirais !', '', 28153),
(142958, 'frFR', 'Je vénère Pa\’ku. La magie du sang est interdite !', '', 28153),
(142957, 'frFR', 'Je vous dis la vérité ! Je ne sais rien sur les reliques de sang !', '', 28153),
(142956, 'frFR', 'Je suis innocent ! Je vous en supplie, ayez pitié...', '', 28153),
(142955, 'frFR', 'Je ne donne pas dans la contrebande de reliques, moi ! La magie du sang, c\’est le mal !', '', 28153),
(142954, 'frFR', 'Je n\’ai jamais vu de reliques de sang !', '', 28153),
(142953, 'frFR', 'Je ne sais pas de quoi vous parlez !', '', 28153),
(142952, 'frFR', 'Je n\’ai rien fait de mal !', '', 28153),
(142951, 'frFR', 'Me force pas à te planter encore une fois...', '', 28153),
(142950, 'frFR', 'À qui tu les as vendues, tes reliques ?', '', 28153),
(142949, 'frFR', 'Tu me dégoûtes, sale traître.', '', 28153),
(142948, 'frFR', 'Je vais te faire souffrir, Pro\’diteur. Tu vas servir d\’exemple.', '', 28153),
(142947, 'frFR', 'Avoue et je te promets que ta mort, elle sera rapide.', '', 28153),
(142946, 'frFR', 'Tu es la pire vermine qui soit, Pro\’diteur. La magie du sang, elle tue notre peuple !', '', 28153),
(142945, 'frFR', 'On sait que tu fais de la contrebande de reliques de sang.', '', 28153),
(142944, 'frFR', 'Les reliques de sang, dis-nous d\’où elles viennent, Pro\’diteur !', '', 28153),
(142943, 'frFR', 'Ce saligaud, il fait entrer clandestinement des reliques de sang dans notre ville.\n\nIl va se mettre à table et ensuite, il servira d\’exemple.', '', 28153),
(142942, 'frFR', 'Je n\’ai rien fait de mal ! Dites-leur, vous !', '', 28153),
(142941, 'frFR', '(Partir)', '(Partir)', 28153),
(142940, 'frFR', '<Les restes déchiquetés et sanglants de la criminelle évadée Teshyambi sont à peine identifiables. Il semble que ce soit l\’œuvre des raptors qui rôdent dans les parages.>', '<Les restes déchiquetés et sanglants de la criminelle évadée Teshyambi sont à peine identifiables. Il semble que ce soit l\’œuvre des raptors qui rôdent dans les parages.>', 28153),
(142939, 'frFR', 'Je sais qui vous êtes, Mojoba. Rendez-vous à Vol\’dun et vivez votre exil en paix.', 'Je sais qui vous êtes, Mojoba. Rendez-vous à Vol\’dun et vivez votre exil en paix.', 28153),
(142938, 'frFR', 'Vous êtes qui, vous ? Vous voulez quoi, hein ?', '', 28153),
(142937, 'frFR', 'Je suis désolé, mais vous avez été exilé à Vol\’dun pour vos crimes.', 'Je suis désolée, mais vous avez été exilé à Vol\’dun pour vos crimes.', 28153),
(142936, 'frFR', 'Chut ! Je me cache des raptors et de Zulajin. Il faut que je retourne à Zuldazar.', '', 28153),
(142935, 'frFR', '', 'Vous faites du bon travail… pour des prisonniers en fuite.', 28153),
(142934, 'frFR', '', 'Maintenant que la prison est sous contrôle et ses clés en notre possession, nous pouvons commencer à récupérer l\’azérite et à libérer les otages.', 28153),
(142933, 'frFR', '', 'Dame Corsandre va avoir besoin d\’un nouveau surveillant, finalement.', 28153),
(142932, 'frFR', 'Prenez garde avec le feu ! C\’est à vous que je parle, mage. Si ces munitions explosent, nous serons tous réduits en poussière !', '', 28153),
(142931, 'frFR', 'Gardes, tenez-vous prêts ! Ils arrivent !', '', 28153),
(142930, 'frFR', '', 'Nous sécuriserons les niveaux inférieurs pendant que vous vous occuperez du surveillant.', 28153),
(142929, 'frFR', '', 'Bien joué. On dirait que vous contrôlez la situation.', 28153),
(142928, 'frFR', 'Quand on aura mis la main sur les otages du surveillant, on pourra demander une rançon bien rondelette !', '', 28153),
(142927, 'frFR', 'Allez, les gars ! Ouvrez-moi ces portes !', '', 28153),
(142926, 'frFR', '', 'J\’espère pour toi que tu dis vrai. Ou la première tâche de ton remplaçant sera de te noyer avec ces vermines.', 28153),
(142925, 'frFR', 'Toutes mes excuses, dame Corsandre. Tout est sous contrôle. Mes hommes auront rétabli l\’ordre sous peu.', '', 28153),
(142924, 'frFR', '', 'Korgus ! Pourquoi n\’as-tu pas inondé les niveaux inférieurs et noyé ces sales rats ?', 28153),
(142923, 'frFR', '', 'Beurk ! Vous avez dû ramper là-dedans pour vous enfuir ? Euh, marchez plutôt devant, alors.', 28153),
(142922, 'frFR', '', 'Le surveillant envoyait sans doute peu de patrouilles de ce côté de l\’île à cause de cette créature. Et vous l\’avez vaincue, bon travail.', 28153),
(142921, 'frFR', '', 'Nous sécuriserons le périmètre pendant que vous vous rendrez jusqu\’à la grille des égouts. De là, vous devriez parvenir à pénétrer dans la prison.', 28153),
(142920, 'frFR', '', 'D\’après nos informations, le surveillant conserve les clés des caches d\’azérite et des otages… autour de son cou.', 28153),
(142919, 'frFR', '', 'Restez discrets ! Ils ne nous ont pas encore repérés.', 28153),
(142918, 'frFR', 'Je suis obligé ?', '', 28153),
(142917, 'frFR', 'Vous voulez quoi ?', '', 28153),
(142916, 'frFR', 'Prêt à bosser.', '', 28153),
(142915, 'frFR', 'Notre caserne a été détruite !', '', 28153),
(142914, 'frFR', 'On aura besoin de renforts pour remporter cette guerre.', '', 28153),
(142913, 'frFR', 'Au boulot !', '', 28153),
(142912, 'frFR', 'Ce bâtiment ne va pas se construire tout seul !', '', 28153),
(142911, 'frFR', 'Du nerf avec ce marteau !', '', 28153),
(142910, 'frFR', '', 'Alleria se crispe.', 28153),
(142909, 'frFR', 'Vous m\’avez sauvé la vie !', 'Vous m\’avez sauvé la vie !', 28153),
(142908, 'frFR', 'Je devrais pouvoir retourner en lieu sûr par mes propres moyens. Merci.', 'Je devrais pouvoir retourner en lieu sûr par mes propres moyens. Merci.', 28153),
(142907, 'frFR', 'Leurs attaques sont acharnées. Merci pour votre aide.', 'Leurs attaques sont acharnées. Merci pour votre aide.', 28153),
(142906, 'frFR', 'Je n\’oublierai jamais votre courage.', 'Je n\’oublierai jamais votre courage.', 28153),
(142905, 'frFR', 'J\’ai bien cru que ma dernière heure était venue !', 'J\’ai bien cru que ma dernière heure était venue !', 28153),
(142904, 'frFR', 'Notre village aurait bien besoin d\’autres héros de votre trempe !', 'Notre village aurait bien besoin d\’autres héros de votre trempe !', 28153),
(142903, 'frFR', 'Vengez ceux d\’entre nous qui n\’ont pas eu la chance d\’être sauvés.', 'Vengez ceux d\’entre nous qui n\’ont pas eu la chance d\’être sauvés.', 28153),
(142902, 'frFR', 'Ces Nagas sont des monstres !', 'Ces Nagas sont des monstres !', 28153),
(142901, 'frFR', 'Je vais vous planter cette lame dans le cœur !', '', 28153),
(142900, 'frFR', 'Des intrus s\’infiltrent par les égouts !', '', 28153),
(142898, 'frFR', 'Le chant de cette pierre est puissant et silencieux. Espérons que la seule personne capable d\’entendre sa mélodie ne découvre jamais ces lieux.', '', 28153),
(142897, 'frFR', 'J\’en ai assez vu. Cette pierre maléfique doit être détruite.', '', 28153),
(142894, 'frFR', 'Je doute qu\’elle s\’en déleste de son plein gré, alors arrachez-les à son cadavre.', '', 28153),
(142893, 'frFR', 'J\’ai repéré notre cible suivante au sud. Accélérez le pas.', '', 28153),
(142892, 'frFR', 'Il est regrettable que la destruction de ce bateau permette aux Kultirassiens de se regrouper.', '', 28153),
(142891, 'frFR', 'La Dame noire appréciera vos services, sans l\’ombre d\’un doute.', '', 28153),
(142890, 'frFR', '', 'Avec plaisir, seigneur régent. Je vous retrouverai à Lune-d\’Argent, camarade.', 28153),
(142889, 'frFR', 'Parfait ! Dame Liadrin, veuillez retourner à Orgrimmar et annoncer l\’heureuse nouvelle à notre chef de guerre.', '', 28153),
(142888, 'frFR', '', 'Au nom des Sacrenuit, j\’accepte votre proposition. À compter de ce jour, Suramar se battra pour la Horde.', 28153),
(142887, 'frFR', 'La Horde vous les offre, Première arcaniste. Rejoignez-nous. Les portes de Lune-d\’Argent vous sont grand ouvertes.', '', 28153),
(142886, 'frFR', '', 'Suramar sera toujours notre foyer. Mais certains, parmi les miens, aimeraient explorer le monde et regagner leur place en Azeroth. Pour cela, nous avons besoin d\’alliés.', 28153),
(142885, 'frFR', '', 'Nos alliés nous rendent plus forts… mais nous n\’avons pas oublié qui nous sommes.', 28153),
(142884, 'frFR', '', 'Bien au contraire. Cette altercation me montre à quel point vous êtes dévoué à votre peuple. La Horde vous a permis de rester fidèle à vos valeurs, ce qui est très important pour nous.', 28153),
(142883, 'frFR', 'Je regrette que vous ayez dû assister à cet échange, Thalyssra. Je n\’avais pas prévu que votre visite se déroule de la sorte.', '', 28153),
(142882, 'frFR', '', 'Comme vous le voudrez, seigneur régent. Pour le moment…', 28153),
(142881, 'frFR', 'Assez ! Je vous somme de partir, Alleria. Accident ou non, votre présence constitue une menace pour Quel\’Thalas. Retournez à Hurlevent. Vous n\’êtes plus la bienvenue à Lune-d\’Argent.', '', 28153),
(142880, 'frFR', '', 'Je ne permettrai pas qu\’on me fasse prisonnière sur mes propres terres.', 28153),
(142879, 'frFR', 'Gardes ! Saisissez-vous de cette saboteuse !', '', 28153),
(142878, 'frFR', 'Le Puits de soleil est en sécurité. Votre aide nous a été très précieuse, Thalyssra. Tout comme la vôtre, héraut.', '', 28153),
(142877, 'frFR', 'Vous ne faites que retarder l\’inévitable ! J\’obtiendrai ce que je désire.', '', 28153),
(142876, 'frFR', '', 'Maintenant ! Concentrez votre puissance avec moi !', 28153),
(142875, 'frFR', 'Le portail est ouvert. Oui… cela devrait satisfaire nos besoins.', '', 28153),
(142874, 'frFR', '', 'Dites-nous quoi faire et nous vous prêterons main-forte.', 28153),
(142873, 'frFR', '', 'Je peux refermer la faille, mais il me faut de l\’aide.', 28153),
(142872, 'frFR', 'Une faille menace de s\’ouvrir. Si cela devait se produire, nous pourrions perdre le Puits de soleil.', '', 28153),
(142871, 'frFR', 'Commencez l\’incantation, Rikal.', 'Commencez l\’incantation, Rikal.', 28153),
(142870, 'frFR', 'Tôt ou tard, le vent tournera. Comme toujours.', '', 28153),
(142869, 'frFR', 'Votre poigne est en train de lâcher !', '', 28153),
(142868, 'frFR', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t%s s\’apprête à lancer des |cFFFF0000|Hspell:257785|h[Dagues expéditives]|h|r ! Cachez-vous !', '', 28153),
(142867, 'frFR', 'Bal\’a dash, malanore.', '', 28153),
(142866, 'frFR', 'Chacun doit suivre sa propre voie.', '', 28153),
(142865, 'frFR', 'Nous sommes un nouvel avenir.', '', 28153),
(142864, 'frFR', 'Aucune vérité n\’est absolue.', '', 28153),
(142863, 'frFR', 'L\’univers recèle encore tant de mystères.', '', 28153),
(142862, 'frFR', 'De nouvelles possibilités s\’offrent à nous.', '', 28153),
(142861, 'frFR', 'À la différence du passé, l\’avenir n\’est pas écrit ; il peut être modifié.', '', 28153),
(142860, 'frFR', 'Shorel\’aran.', '', 28153),
(142859, 'frFR', 'Les nôtres ne craignent pas les ténèbres.', '', 28153),
(142858, 'frFR', 'Il n\’existe jamais qu\’une seule vérité.', '', 28153),
(142857, 'frFR', 'Les murmures ne nous contrôlent pas.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142856, 'frFR', 'Chaque impulsion doit rester sous contrôle.', '', 28153),
(142855, 'frFR', 'Ne craignez pas le pouvoir. Prenez-le.', '', 28153),
(142854, 'frFR', 'Considérez toutes les possibilités.', '', 28153),
(142853, 'frFR', 'Votre insolence me laisse de marbre.', '', 28153),
(142852, 'frFR', '« Pour le puits de Soleil » ? Allons, il est temps de passer à autre chose.', '', 28153),
(142851, 'frFR', 'Si un portail conduisant vers le néant infini s\’ouvrait soudainement sous vos pieds et vous engloutissait, ce ne serait que pure coïncidence. Après tout, personne n\’est à l\’abri d\’un accident.', '', 28153),
(142850, 'frFR', 'Je me suis fait transformer par une puissance cosmique qui rend complètement dingue et vous me trouvez « suspect ». On peut savoir ce qui vous fait penser ça ?', '', 28153),
(142849, 'frFR', 'Que voulez-vous ?', '', 28153),
(142848, 'frFR', 'Je vends des marchandises provenant de lointains royaumes.', '', 28153),
(142847, 'frFR', 'Tout s\’achète, pourvu qu\’on y mette le prix.', '', 28153),
(142846, 'frFR', 'En espérant que votre achat vous apporte satisfaction.', '', 28153),
(142845, 'frFR', 'Merci de votre visite.', '', 28153),
(142844, 'frFR', 'N\’hésitez pas à revenir.', '', 28153),
(142843, 'frFR', '', 'N\’hésitez pas à revenir.', 28153),
