(142517, 'frFR', '', 'Notre destin nous incombe.', 28153),
(142516, 'frFR', '', 'La puissance des Shal\’dorei prévaut.', 28153),
(142515, 'frFR', 'Pour la reine !', '', 28153),
(142514, 'frFR', '', 'Ash\’thoras denil.', 28153),
(142513, 'frFR', '', 'Unis, nous sommes plus forts.', 28153),
(142512, 'frFR', '', 'Les Shal\’dorei ne seront plus jamais opprimés.', 28153),
(142511, 'frFR', '', 'Ne faiblissez pas. Pour Suramar !', 28153),
(142510, 'frFR', '', 'Kal\’theros maldin.', 28153),
(142509, 'frFR', '', 'Nous trouverons notre place en ce monde.', 28153),
(142508, 'frFR', '', 'Puissiez-vous toujours marcher au clair de lune.', 28153),
(142507, 'frFR', '', 'Les étoiles vous guident.', 28153),
(142506, 'frFR', 'Je vais me repaître de votre chair, pieds-secs !', '', 28153),
(142505, 'frFR', 'Votre chair enrichira les profondeurs !', '', 28153),
(142504, 'frFR', 'Pour la reine Azshara !', '', 28153),
(142503, 'frFR', 'Allons-y, Jo\’chunga. J\’ai un plan pour débusquer Hir\’eek…', '', 28153),
(142502, 'frFR', 'Essayez donc de me suivre, je suis l\’un des plus forts représentants des Zandalari.', '', 28153),
(142501, 'frFR', 'Avec moi, Kal\’dran. On va leur faire leur fête, aux Trolls de sang.', '', 28153),
(142500, 'frFR', '', 'Krag\’wa, je vais le trouver… Je savais que c\’était pas qu\’une légende.', 28153),
(142499, 'frFR', 'Allez dans le marais et faites tout votre possible pour aider la princesse et $n à combattre les Trolls de sang.', '', 28153),
(142498, 'frFR', 'La princesse, vous l\’avez entendue ! On a un objectif : affaiblir les Trolls de sang et gagner la faveur de ces Loas.', '', 28153),
(142497, 'frFR', 'Votre présence me nuit sacrément.', '', 28153),
(142496, 'frFR', 'Ne restez pas là !', '', 28153),
(142495, 'frFR', 'Vous vous obstinez à m\’embêter !', '', 28153),
(142494, 'frFR', 'Écoutez, j\’ai des choses à faire.', '', 28153),
(142493, 'frFR', 'Que puis-je faire pour vous ?', '', 28153),
(142492, 'frFR', 'Les Shal\’dorei sont éternels.', '', 28153),
(142491, 'frFR', 'Tenu\’balah.', '', 28153),
(142490, 'frFR', 'Ishnal to\’reth.', '', 28153),
(142489, 'frFR', 'Salutations.', '', 28153),
(142488, 'frFR', 'Ash\’thoras denil.', '', 28153),
(142487, 'frFR', 'Allez au clair de lune.', '', 28153),
(142486, 'frFR', 'L\’époque nous appartient.', '', 28153),
(142485, 'frFR', 'Les Sacrenuit sont de retour.', '', 28153),
(142484, 'frFR', 'Bon voyage.', '', 28153),
(142483, 'frFR', 'Nor\’bethos Suramar.', '', 28153),
(142482, 'frFR', 'Kal\’theros maldin.', '', 28153),
(142481, 'frFR', 'Gloire à la nuit.', '', 28153),
(142480, 'frFR', '', 'Vous êtes une Sacrénouille.', 28153),
(142479, 'frFR', '', 'Excusez-moi, j\’ai à faire.', 28153),
(142478, 'frFR', '', 'Loin d\’ici, par exemple ?', 28153),
(142477, 'frFR', '', 'Vous n\’auriez pas une quête urgente quelque part ?', 28153),
(142476, 'frFR', '', 'Vous avez une question ?', 28153),
(142475, 'frFR', '', 'Nous sortons de l\’ombre.', 28153),
(142474, 'frFR', '', 'Tenu\’balah.', 28153),
(142473, 'frFR', '', 'Le destin nous sourit.', 28153),
(142472, 'frFR', '', 'Ishnal to\’reth.', 28153),
(142471, 'frFR', '', 'Salutations.', 28153),
(142470, 'frFR', '', 'Ash\’thoras denil.', 28153),
(142469, 'frFR', '', 'Nous survivrons.', 28153),
(142468, 'frFR', '', 'Nous revenons au monde.', 28153),
(142467, 'frFR', '', 'Puisse la lune vous sourire.', 28153),
(142466, 'frFR', '', 'Les temps sont troublés. Faites attention à vous.', 28153),
(142465, 'frFR', '', 'Nor\’bethos Suramar.', 28153),
(142464, 'frFR', '', 'La nuit vous guide.', 28153),
(142463, 'frFR', '', 'Kal\’theros maldin.', 28153),
(142462, 'frFR', 'J\’ai acheté ça à un éclaireur. Il a dit que ça s\’appelait un P.R.O.F.I.L. Vous savez à quoi ça sert ?', '', 28153),
(142461, 'frFR', 'Suramar brille de mille feux au milieu des décombres de la Fracture.', '', 28153),
(142460, 'frFR', 'Nous allons explorer le monde et prouver à tous qu\’il faut compter avec nous !', '', 28153),
(142459, 'frFR', 'Hé, vous êtes jeune ! Vous pouvez m\’apprendre des trucs de jeune ?', '', 28153),
(142455, 'frFR', 'Que puis-je faire pour vous ?', '', 28153),
(142454, 'frFR', 'Jetez donc un œil, je vends de tout.', '', 28153),
(142453, 'frFR', 'J\’ai les plus belles marchandises.', '', 28153),
(142452, 'frFR', 'Vous ne trouverez pas meilleurs prix !', '', 28153),
(142451, 'frFR', 'Ce fut un plaisir.', '', 28153),
(142450, 'frFR', 'Revenez quand vous voulez.', '', 28153),
(142449, 'frFR', 'Qu\’est-ce qu\’il vous fallait ?', '', 28153),
(142448, 'frFR', 'Nous ne nous cacherons plus.', '', 28153),
(142447, 'frFR', 'Tenu\’balah.', '', 28153),
(142446, 'frFR', 'Le destin nous sourit.', '', 28153),
(142445, 'frFR', 'Salutations.', '', 28153),
(142444, 'frFR', 'Ash\’thoras denil.', '', 28153),
(142443, 'frFR', 'Nous revenons au monde.', '', 28153),
(142441, 'frFR', 'Puisse la lune vous sourire.', '', 28153),
(142440, 'frFR', 'Nor\’bethos Suramar.', '', 28153),
(142439, 'frFR', 'Kal\’theros maldin.', '', 28153),
(142438, 'frFR', 'Je sais que je peux compter sur vous.', '', 28153),
(142437, 'frFR', 'Portez-vous bien.', '', 28153),
(142436, 'frFR', '', 'Hé, vous êtes jeune ! Vous pouvez m\’apprendre des trucs de jeune ?', 28153),
(142435, 'frFR', '', 'Nous allons explorer le monde et prouver à tous qu\’il faut compter avec nous !', 28153),
(142434, 'frFR', '', 'Suramar brille de mille feux au milieu des décombres de la Fracture.', 28153),
(142433, 'frFR', '', 'J\’ai acheté ça à un éclaireur. Il a dit que ça s\’appelait un P.R.O.F.I.L. Vous savez à quoi ça sert ?', 28153),
(142432, 'frFR', '', 'Vous ne trouverez pas meilleurs prix !', 28153),
(142431, 'frFR', '', 'Ce fut un plaisir.', 28153),
(142430, 'frFR', '', 'Revenez vite.', 28153),
(142429, 'frFR', '', 'Que puis-je faire pour vous ?', 28153),
(142428, 'frFR', '', 'Jetez donc un œil, je vends de tout.', 28153),
(142427, 'frFR', '', 'J\’ai les plus belles marchandises.', 28153),
(142426, 'frFR', '', 'Les étoiles brillent à nouveau.', 28153),
(142425, 'frFR', '', 'Tenu\’balah.', 28153),
(142424, 'frFR', '', 'Je peux vous aider ?', 28153),
(142423, 'frFR', '', 'Salutations.', 28153),
(142422, 'frFR', '', 'Ash\’thoras denil.', 28153),
(142421, 'frFR', '', 'La nuit vous garde.', 28153),
(142420, 'frFR', '', 'Les étoiles vous guident.', 28153),
(142419, 'frFR', '', 'Notre heure est venue.', 28153),
(142418, 'frFR', '', 'Nor\’bethos Suramar.', 28153),
(142417, 'frFR', '', 'Kal\’theros maldin.', 28153),
(142416, 'frFR', '', 'Portez-vous bien.', 28153),
(142407, 'frFR', 'Les Loas ? Ce sont des êtres anciens et puissants, princesse. Comment vous savez si y en a dans ce marais ?', '', 28153),
(142404, 'frFR', 'Heureusement que je vous avais mis en garde pour l\’urne.', '', 28153),
(142403, 'frFR', 'On bouge pas d\’ici et on attend que la princesse Talanji revienne. J\’abandonnerai pas mon poste, et toi non plus.', 'On bouge pas d\’ici et on attend que la princesse Talanji revienne. J\’abandonnerai pas mon poste, et toi non plus.', 28153),
(142402, 'frFR', 'Moi je dis, il faut qu\’on se tire d\’ici pour rejoindre la flotte. Si les Trolls de sang, ils rappliquent, on est cuits !', 'Moi je dis, il faut qu\’on se tire d\’ici pour rejoindre la flotte. Si les Trolls de sang, ils rappliquent, on est cuits !', 28153),
(142401, 'frFR', 'Et alors ? Elle part pour Nazmir avec les autres tarés. Elle reviendra pas !', 'Et alors ? Elle part pour Nazmir avec les autres tarés. Elle reviendra pas !', 28153),
(142400, 'frFR', 'T\’es malade, ou quoi ? On peut pas abandonner notre poste ! On vient juste de voir la princesse !', 'T\’es malade, ou quoi ? On peut pas abandonner notre poste ! On vient juste de voir la princesse !', 28153),
(142399, 'frFR', '', 'Nos ennemis n\’ont aucune conviction.', 28153),
