INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142041, 'frFR', '', 'Morsure du démon est une attaque infligeant des dégâts et générant de la fureur.', 28153),
(142040, 'frFR', 'Utilisez Morsure du démon sur le mannequin d\’entraînement.', '', 28153),
(142039, 'frFR', 'Morsure du démon inflige des dégâts et génère de la fureur.', '', 28153),
(142038, 'frFR', 'Maintenant que vous êtes à portée, il est temps de violemment attaquer.', '', 28153),
(142036, 'frFR', '', 'Utilisez Ruée fulgurante pour fondre sur le mannequin d\’entraînement.', 28153),
(142035, 'frFR', 'Que nous apporte le vent ?', '', 28153),
(142034, 'frFR', 'La rivière nous nourrit.', '', 28153),
(142033, 'frFR', 'Salutations.', '', 28153),
(142032, 'frFR', '', 'Avec votre agilité sans égale, vous choisissez où et quand attaquer vos ennemis.', 28153),
(142031, 'frFR', '', 'En tant que chasseuse de démons Dévastation, vous avez fait beaucoup de sacrifices pour manier la puissance gangrenée des démons.', 28153),
(142030, 'frFR', '', 'En tant que chasseur de démons Dévastation, vous avez fait beaucoup de sacrifices pour manier la puissance gangrenée des démons.', 28153),
(142029, 'frFR', 'Haut-Roc ne faillira pas !', '', 28153),
(142028, 'frFR', 'Les chasseurs de démons Dévastation ont beaucoup sacrifié pour maîtriser le pouvoir des démons.', '', 28153),
(142027, 'frFR', 'Utilisez Ruée fulgurante pour fondre sur le mannequin d\’entraînement.', '', 28153),
(142026, 'frFR', 'Avec votre agilité sans égale, vous choisissez où et quand attaquer vos ennemis.', '', 28153),
(142025, 'frFR', 'Les chasseurs de démons Dévastation ont beaucoup sacrifié pour maîtriser le pouvoir des démons.', '', 28153),
(142022, 'frFR', 'À vous entendre, vous l\’avez déjà, princesse.', '', 28153),
(142021, 'frFR', '', 'Ce « G\’huun » doit les rendre plus puissants… trop puissants pour nous. Une nouvelle stratégie s\’impose.', 28153),
(142020, 'frFR', 'Ils ont un QUOI ? Mais vous aviez dit que c\’était juste des indigènes !', '', 28153),
(142019, 'frFR', 'Oyez, oyez ! Le seigneur Chantorage a livré sa parole aux fidèles !', 'Oyez, oyez ! Le seigneur Chantorage a livré sa parole aux fidèles !', 28153),
(142018, 'frFR', 'Le contremaître Scripps est devenu fou. Les autres aussi !', 'Le contremaître Scripps est devenu fou. Les autres aussi !', 28153),
(142017, 'frFR', 'J\’étais en train de tourner de l\’œil !', 'J\’étais en train de tourner de l\’œil !', 28153),
(142016, 'frFR', 'Impossible de leur échapper !', 'Impossible de leur échapper !', 28153),
(142015, 'frFR', 'Que les marées vous bénissent !', 'Que les marées vous bénissent !', 28153),
(142014, 'frFR', 'Merci mille fois !', 'Merci mille fois !', 28153),
(142013, 'frFR', 'Les moissonneurs s\’en prennent à nous !', 'Les moissonneurs s\’en prennent à nous !', 28153),
(142012, 'frFR', 'Les marées me viennent en aide !', 'Les marées me viennent en aide !', 28153),
(142011, 'frFR', 'Je savais que la mer ne nous avait pas oubliés !', 'Je savais que la mer ne nous avait pas oubliés !', 28153),
(142007, 'frFR', 'Votre tour… viendra…', 'Votre tour… viendra…', 28153),
(142006, 'frFR', 'C\’est de… l\’insubor… dination…', 'C\’est de… l\’insubor… dination…', 28153),
(142004, 'frFR', 'Je vous relève de vos fonctions…', 'Je vous relève de vos fonctions…', 28153),
(142003, 'frFR', 'Mes familiers ont faim.', '', 28153),
(142002, 'frFR', 'Briser !', '', 28153),
(142001, 'frFR', 'Remettez… mon corps… à la mer…', '', 28153),
(142000, 'frFR', 'On ne peut faire confiance… à personne…', 'On ne peut faire confiance… à personne…', 28153),
(141999, 'frFR', 'Vous aurez… à rendre… des comptes…', 'Vous aurez… à rendre… des comptes…', 28153),
(141998, 'frFR', 'Oooh… morbleu…', 'Oooh… morbleu…', 28153),
(141997, 'frFR', 'Rien ne survit à cette profondeur.', '', 28153),
(141996, 'frFR', 'C\’est… tout… ce que vous avez ?', 'C\’est… tout… ce que vous avez ?', 28153),
(141995, 'frFR', 'Pitoyable… avorton…', 'Pitoyable… avorton…', 28153),
(141994, 'frFR', 'Qui vous a dit d\’arrêter ?', 'Qui vous a dit d\’arrêter ?', 28153),
(141993, 'frFR', 'Pulvérisé !', '', 28153),
(141992, 'frFR', 'Vous allez servir d\’exemple !', 'Vous allez servir d\’exemple !', 28153),
(141991, 'frFR', 'La pause est terminée, insecte !', 'La pause est terminée, insecte !', 28153),
(141990, 'frFR', 'Vous allez regretter votre insubordination !', 'Vous allez regretter votre insubordination !', 28153),
(141989, 'frFR', 'Vous osez sortir du rang ?', 'Vous osez sortir du rang ?', 28153),
(141988, 'frFR', 'Vous allez payer pour votre désobéissance !', 'Vous allez payer pour votre désobéissance !', 28153),
(141987, 'frFR', 'Vous étiez totalement largué.', '', 28153),
(141986, 'frFR', 'Rentrez dans le rang !', 'Rentrez dans le rang !', 28153),
(141985, 'frFR', 'Au boulot, vermine !', 'Au boulot, vermine !', 28153),
(141984, 'frFR', 'Niveau d\’énergie critique.', '', 28153),
(141983, 'frFR', 'Réinitialisation du système requise.', '', 28153),
(141982, 'frFR', 'Les profondeurs seront votre tombeau !', '', 28153),
(141981, 'frFR', 'Entité étrangère détectée dans le port A.', '', 28153),
(141980, 'frFR', 'Unité désactivée.', '', 28153),
(141979, 'frFR', 'Échec du protocole de récolte.', '', 28153),
(141978, 'frFR', 'Sous cinq brassées, vos os gisent !', '', 28153),
(141977, 'frFR', 'Intégrité structurelle : 0%%.', '', 28153),
(141976, 'frFR', 'Fuite détectée.', '', 28153),
(141975, 'frFR', 'Désactivation du système.', '', 28153),
(141974, 'frFR', 'Entité hostile identifiée.', '', 28153),
(141973, 'frFR', 'Activation des contre-mesures.', '', 28153),
(141972, 'frFR', 'Initialisation des servofaucheurs.', '', 28153),
(141971, 'frFR', 'Intrusion détectée.', '', 28153),
(141970, 'frFR', 'Utilisateur non autorisé.', '', 28153),
(141969, 'frFR', 'Séquence d\’attaque enclenchée.', '', 28153),
(141968, 'frFR', 'Combat engagé.', '', 28153),
(141967, 'frFR', 'Menace détectée.', '', 28153),
(141966, 'frFR', 'Artilleurs ! Dégagez-moi cette vermine de mon champ de bataille !', '', 28153),
(141965, 'frFR', 'Canons ! Feu sur ma position !', '', 28153),
(141964, 'frFR', 'Nul ne peut résister à la puissance des marées !', '', 28153),
(141963, 'frFR', 'Préparez-vous à mourir !', '', 28153),
(141962, 'frFR', 'Je vais vous tuer !', '', 28153),
(141961, 'frFR', 'Goûtez à mon acier !', '', 28153),
(141960, 'frFR', 'Ça ne m\’étonne pas de la Horde.', '', 28153),
(141959, 'frFR', 'Quel manque de discipline !', '', 28153),
(141958, 'frFR', 'La mer emportera vos ossements !', '', 28153),
(141957, 'frFR', 'Vous ne… méritez pas… la victoire…', '', 28153),
(141956, 'frFR', 'Ça s\’arrête ici pour vous, vermine de la Horde !', '', 28153),
(141955, 'frFR', 'Pour Boralus !', '', 28153),
(141954, 'frFR', 'L\’ennemi nous encercle !', '', 28153),
(141953, 'frFR', 'Attention !', '', 28153),
(141952, 'frFR', 'Par ici !', '', 28153),
(141951, 'frFR', 'Par là !', '', 28153),
(141950, 'frFR', '', 'Portez ces vêtements avec fierté, $p. C\’est un immense honneur de vous compter dans les rangs de l\’armée de la Lumière.', 28153),
(141949, 'frFR', '', 'Au cours de vos voyages, vous avez apporté la Lumière dans les ténèbres. Vous avez montré à l\’Alliance ce qui fait de nous des Sancteforge.', 28153),
(141948, 'frFR', '', 'Rejoignez-moi à bord du Vindicaar. Vos efforts assidus méritent récompense.', 28153),
(141947, 'frFR', '', 'Vous avez fait preuve d\’une grande dévotion à l\’Alliance, $p. Je n\’aurais fait mieux moi-même. Enfin si… mais de peu.', 28153),
(141946, 'frFR', 'Prenez ça !', '', 28153),
(141945, 'frFR', 'Brûlez !', '', 28153),
(141944, 'frFR', '', 'C\’est pour moi un honneur de vous remettre l\’armure de notre peuple. Où que vos périples vous conduisent, elle vous rappellera vos origines.', 28153),
(141943, 'frFR', '', 'Même aux heures les plus sombres, vous avez fait preuve de force, de courage et de détermination. Grâce à vous, $p, la Horde a entendu la voix du peuple de Haut-Roc.', 28153),
(141942, 'frFR', 'Je vais vous mettre le grappin dessus !', '', 28153),
(141941, 'frFR', '', 'Totem-du-Tonnerre vous appelle à présent. Le moment est venu pour nous de vous récompenser pour tout ce que vous avez accompli.', 28153),
(141940, 'frFR', '', 'Votre voyage à travers Azeroth a été long, $p. À travers toutes vos aventures, vous avez apporté honneur à Haut-Roc.', 28153),
(141939, 'frFR', 'Venez par ici !', '', 28153),
(141938, 'frFR', 'Vous êtes le prochain !', '', 28153),
(141937, 'frFR', 'Vous m\’échapperez pas !', '', 28153),
(141936, 'frFR', 'Je vais vous dévorer les tripes !', '', 28153),
(141935, 'frFR', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Argus !', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Argus !', 28153),
(141934, 'frFR', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Deuillegivre !', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Deuillegivre !', 28153),
(141933, 'frFR', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre sha !', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre sha !', 28153),
(141932, 'frFR', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre terres de Feu !', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre terres de Feu !', 28153),
(141931, 'frFR', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Crépuscule !', 'L\’appareil photo P.R.O.F.I.L. a obtenu le filtre Crépuscule !', 28153),
(141930, 'frFR', 'Faut pas gâcher…', '', 28153),
(141929, 'frFR', 'Des morceaux bien juteux.', '', 28153),
(141928, 'frFR', 'De la nourriture pour les poissons !', '', 28153),
(141927, 'frFR', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tVous êtes victime de |cFFFF0000|Hspell:248396|h[Fléau de l\’âme]|h|r !', '|TInterface\\Icons\\Ability_Argus_WastingPlague:20|tVous êtes victime de |cFFFF0000|Hspell:248396|h[Fléau de l\’âme]|h|r !', 28153),
(141926, 'frFR', 'Ça, c\’est un morceau de choix !', '', 28153),
(141925, 'frFR', 'Je vais vous réduire en pièces !', '', 28153),
(141924, 'frFR', '<Le pêcheur fixe sans répit l\’étendue d\’eau en marmonnant dans sa barbe. Il a les lèvres gercées, les mains qui saignent et le corps couvert de balafres et d\’égratignures, probablement causées par les oiseaux affamés qui affluent sur la côte.\n\nIl semble ne pas avoir quitté cet endroit depuis des jours.\n\nL\’influence du Sabbat ne fait aucun doute, mais contrairement aux autres ensorcelés, il est capable de bouger et de parler. Il ne dit cependant rien à votre approche.>', '', 28153),
(141923, 'frFR', 'Des agneaux à l\’abattoir.', '', 28153),
(141922, 'frFR', '', 'Restez fidèle à vous-même. Et s\’il vous arrive d\’avoir le mal du pays, sachez que Haut-Roc est là pour vous. Pour toujours.', 28153),
(141921, 'frFR', '', 'Rendez-vous à Orgrimmar. Rencontrez nos nouveaux alliés et découvrez ce qui leur est cher… ce pour quoi ils se battent.', 28153),
(141920, 'frFR', '', 'Un nouveau voyage vous attend, $p. Vous serez notre voix par-delà la montagne.', 28153),
(141919, 'frFR', '', 'Il est grand temps de remédier à cela.', 28153),
(141918, 'frFR', '', 'Depuis toujours, les îles Brisées ont constitué notre foyer. Nous n\’en savons que très peu sur l\’Azeroth au-delà de nos rivages.', 28153),
(141917, 'frFR', 'Il paraît qu\’il y a des espions ! Qu\’est-ce que je vais faire ?', 'Il paraît qu\’il y a des espions ! Qu\’est-ce que je vais faire ?', 28153),
(141916, 'frFR', '', 'Allez toujours dans la Lumière, $p.', 28153),
(141915, 'frFR', '', 'Le devoir vous appelle désormais à Hurlevent. Explorez Azeroth, apprenez à connaître ses habitants et les lieux que nous avons juré de défendre.', 28153),
(141914, 'frFR', '', 'Mais nous devons rester sur nos gardes. Une guerre se termine, une autre commence. Telle est la vie d\’un soldat.', 28153),
(141913, 'frFR', '', 'Pour la première fois depuis bien longtemps, nous marchons sous un ciel qui n\’a pas été assombri par la folie de la Légion… et sentons la terre sous nos sabots.', 28153),
(141912, 'frFR', '', 'Pendant des milliers d\’années, les Sancteforge ont affronté des démons dans le Néant distordu. Le Xénédar était notre seul foyer.', 28153),
(141911, 'frFR', 'Ah, vous tombez à pic, héraut ! Vous allez constater de visu ce qu\’un soldat doit accomplir pour devenir un Sancteforge. Continuez, Fareeya.', '', 28153),
(141910, 'frFR', '', 'Vous savez à quel point j\’aime vos discours, mais cela peut-il attendre encore un peu ? Ces initiés sont sur le point de passer les épreuves.', 28153),
(141909, 'frFR', 'En effet. Il est impatient de voir l\’armée de la Lumière combattre aux côtés de l\’Alliance. Rassemblez nos troupes, capitaine, que tous entendent ma proclamation.', '', 28153),
(141908, 'frFR', '', 'Je ne pensais pas vous revoir si tôt, grand exarque. Je présume que votre audience avec le roi s\’est bien passée ?', 28153),
(141905, 'frFR', 'Addington ! Par les abysses…', '', 28153),
(141902, 'frFR', 'Retournez tous au Vide qui vous a engendrés !', '', 28153),
(141901, 'frFR', 'Vous ne nous prendrez pas les Pitons-du-Tonnerre !', '', 28153),
(141900, 'frFR', 'Ha ha ha ! J\’avais presque oublié le plaisir de brandir ma masse !', '', 28153),
(141899, 'frFR', 'Nous chasserons les ténèbres de Mulgore !', '', 28153),
(141898, 'frFR', 'Pour l\’Alliance !', '', 28153),
(141897, 'frFR', 'Pour l\’Alliance !', '', 28153),
(141896, 'frFR', 'Je me demande souvent s\’il n\’a pas raison.', '', 28153),
(141895, 'frFR', 'Nous aurons grand besoin de ces deux qualités dans les jours à venir. $p, merci pour le rôle que vous avez joué.', '', 28153),
(141894, 'frFR', 'J\’ai combattu aux côtés de ces Draeneï dans le Néant distordu pendant un millier d\’années. Vous ne trouverez pas soldats plus éprouvés ou plus dévoués.', '', 28153),
(141893, 'frFR', 'La puissance des Sancteforge est plus que bienvenue à nos côtés, grand exarque.', '', 28153),
(141892, 'frFR', 'Haut roi Wrynn. À compter de ce jour, l\’armée de la Lumière jure de défendre l\’Alliance.', '', 28153),
(141891, 'frFR', 'Le seigneur Chantorage interdit à présent ces rituels. Il préfère se concentrer sur la construction de navires.', '', 28153),
(141890, 'frFR', 'Quand je cherche à observer la surface de l\’eau, ma vue est obscurcie par une sombre tempête.', '', 28153),
(141889, 'frFR', '', 'Savez-vous où se trouve la flotte ?', 28153),
(141888, 'frFR', 'La maison Chantorage a changé après la disparition de la flotte.', '', 28153),
(141887, 'frFR', 'L\’un des frères de mon ordre… et, je l\’espère, des réponses.', '', 28153),
(141886, 'frFR', '', 'Et qu\’allons-nous trouver là-bas, au juste ?', 28153),
(141885, 'frFR', 'Le rivage du Marin n\’est qu\’à quelques lieues. Suivez-moi.', '', 28153),
(141884, 'frFR', 'À terre !', '', 28153),
(141883, 'frFR', '', 'Aucun de vous reviendra de Nazmir. Et notre pauvre roi, il risque de perdre sa fille dans cette croisade stupide !', 28153),
(141882, 'frFR', 'On part pour Nazmir, $n. Accrochez-vous bien, parce que là-bas, y a rien d\’autre que des Trolls de sang et du vaudou noir.', '', 28153),
(141881, 'frFR', '', 'Je veux pas que mes familiers ils finissent en nourriture pour Trolls de sang ! Personne revient jamais de Nazmir.', 28153),
(141880, 'frFR', 'Avant que vous ne partiez, laissez-moi vous indiquer où se trouvent les trois sanctuaires suivants.', '', 28153),
(141879, 'frFR', 'Il s\’agit de l\’île appelée Zandalar. Il vous faudra affréter un navire, elle se trouve pratiquement de l\’autre côté de la planète.', '', 28153),
(141878, 'frFR', 'Je pense avoir déterminé l\’emplacement de certains d\’entre eux, mais hélas ! Ils se trouvent en territoire hostile.', '', 28153),
(141877, 'frFR', 'J\’ai profité de votre absence pour parcourir le journal et tenter de localiser d\’autres sanctuaires.', '', 28153),
(141876, 'frFR', '', 'Avec plaisir, grand exarque.', 28153),
(141875, 'frFR', 'À présent, retournons à Hurlevent. Fareeya, il est temps d\’annoncer que l\’allégeance des Sancteforge va à l\’Alliance.', '', 28153),
(141874, 'frFR', 'T\’laartos est quelque peu… original. Mais il servira notre cause avec honneur.', '', 28153),
(141873, 'frFR', 'T\’laartos !', '', 28153),
(141872, 'frFR', '', 'Pheta thones gamera. Puisse la Lumière éclairer notre chemin !', 28153),
(141871, 'frFR', 'À compter de ce jour, vous faites partie des Sancteforge.', '', 28153),
(141870, 'frFR', 'T\’laartos est désolé.', '', 28153),
(141869, 'frFR', 'Sniff... Wees\’ki pue de la gueule. Pouah !', '', 28153),
(141868, 'frFR', 'On vient de passer la meilleure nuit de toute not\’ vie. C\’est dommage, j\’me souviens de rien.\n\nEnfin, c\’est pas grave, y a des œufs de dino au petit déj\’ !', '', 28153),
(141867, 'frFR', 'Mes chasseurs des ombres et moi, on part en éclaireurs. $n, je vous confie la princesse.', '', 28153),
(141866, 'frFR', 'Vous vous rappelez qu\’est-ce qui s\’est passé la nuit dernière, vous ?\n\nBen moi non plus.', '', 28153),
(141865, 'frFR', 'Princesse, la Horde, elle va bientôt nous envoyer des renforts. Je crois pas qu\’on ait le temps de se laisser distraire.', '', 28153),
(141864, 'frFR', 'Oooh… Faut vraiment… que je fasse plus attention à moi…', '', 28153),
(141863, 'frFR', 'Continuez. Ça va aller, il me faut juste… AÏE ! Un peu de temps.', '', 28153),
(141862, 'frFR', 'Y a pas le temps !\n\nLa Horde, elle va bientôt nous envoyer des renforts, et il faut un port pour les recevoir.', '', 28153),
(141861, 'frFR', '', 'Ils sont trop nombreux cette fois ! Feu !', 28153),
(141860, 'frFR', 'J\’aimerais bien le savoir.', '', 28153),
(141859, 'frFR', '', 'Que se passe-t-il ici, mon frère ?', 28153),
(141858, 'frFR', '', 'Citoyens, dispersez-vous sur-le-champ !', 28153),
(141857, 'frFR', 'Vous ne toucherez pas au trésor de mon maître. Préparez-vous à mourir, $gintrus:intruse; !', '', 28153),
(141856, 'frFR', 'QUI OSE PÉNÉTRER DANS LE CAVEAU ?', '', 28153),
(141855, 'frFR', '', 'Une fois que vous aurez capté leur attention, je les ferai évacuer.', 28153),
(141852, 'frFR', 'La peur… elle suit T\’laartos partout !', '', 28153),
(141851, 'frFR', 'T\’laartos regrette d\’avoir dit « être chétif » à votre sujet.', '', 28153),
(141850, 'frFR', 'T\’laartos ne connaît pas la peur !', '', 28153),
(141849, 'frFR', 'Ici !', '', 28153),
(141848, 'frFR', 'Attention !', '', 28153),
(141847, 'frFR', 'Par ici !', '', 28153),
(141846, 'frFR', 'Par là !', '', 28153),
(141845, 'frFR', 'Nous avons sécurisé la cache d\’azérite et les gardes corsandres restants sont sous notre contrôle. La prison est à nous.', 'Nous avons sécurisé la cache d\’azérite et les gardes corsandres restants sont sous notre contrôle. La prison est à nous.', 28153),
(141844, 'frFR', 'J\’espère que vous avez fait payer sa cruauté à Korgus.', 'J\’espère que vous avez fait payer sa cruauté à Korgus.', 28153),
(141843, 'frFR', 'Merci à vous !', 'Merci à vous !', 28153),
(141842, 'frFR', 'Les prisonniers sont sous contrôle et nous avons établi un périmètre de sécurité. Les niveaux inférieurs sont à nous.', 'Les prisonniers sont sous contrôle et nous avons établi un périmètre de sécurité. Les niveaux inférieurs sont à nous.', 28153),
(141841, 'frFR', '', 'C\’est comme si c\’était fait, grand exarque.', 28153),
(141840, 'frFR', 'Fareeya, j\’ai besoin d\’une balise pour rejoindre le Vindicaar.', '', 28153),
(141839, 'frFR', 'Par ici.', '', 28153),
(141838, 'frFR', 'Ce sera fait, haut roi.', '', 28153),
(141837, 'frFR', 'Je me réjouis à l\’idée que les Sancteforge rejoignent l\’Alliance. Turalyon, notre héraut vous accompagnera à bord du Vindicaar. Vous vous adresserez aux troupes ensemble.', '', 28153),
(141836, 'frFR', '', 'J\’ai toujours eu un faible pour les éternels insatisfaits. C\’est ça, quand on vise la perfection.$B$BJ\’suis pas sûre, vous savez. Ce boîtier minuscule est bourré de technologie gobeline. Y a un potentiel inexploité, là-dedans.$B$BTrouvez une source de grande puissance et… voyez ce qui se passe. Mais je vous garantis rien.', 28153),
(141835, 'frFR', '', 'Niko, y me faut plus de lumière ! Salut, $gmon mignon:beauté; ! Je ne vous avais pas $gvu:vue;. Je peux faire quelque chose pour vous ?', 28153),
(141834, 'frFR', '', 'Je suis pas sûre, vous savez ! Y a de la belle technologie là-dedans… et sans doute une ou deux fonctions cachées.$B$BVous devriez l\’essayer à proximité d\’une source de grande puissance. Ça devrait lui donner l\’impulsion nécessaire !', 28153),
(141833, 'frFR', 'Cet appareil a-t-il d\’autres fonctions ?', 'Cet appareil a-t-il d\’autres fonctions ?', 28153),
(141832, 'frFR', 'J\’ai perdu mon appareil photo. Vous pourriez m\’en fabriquer un autre ?', 'J\’ai perdu mon appareil photo. Vous pourriez m\’en fabriquer un autre ?', 28153),
(141831, 'frFR', '', 'Photographieur Rotatif à Objectif pour Frimousse Impeccable à la Lumière.', 28153),
(141830, 'frFR', 'Que signifie P.R.O.F.I.L. ?', 'Que signifie P.R.O.F.I.L. ?', 28153),
(141829, 'frFR', '', 'Salut ! Vous vouliez prendre une photo avec moi ?', 28153),
(141828, 'frFR', 'On veut des réponses, Pike !', 'On veut des réponses, Pike !', 28153),
(141827, 'frFR', 'Ils sont trop occupés à prendre nos récoltes « pour les soldats » !', 'Ils sont trop occupés à faucher nos récoltes « pour les soldats » !', 28153),
(141826, 'frFR', 'Ça fait des jours que la milice n\’a plus patrouillé !', 'Ça fait des jours que la milice n\’a plus patrouillé !', 28153),
(141825, 'frFR', 'Fossoyeuse est attaquée ! Tous au portail de mage !', 'Fossoyeuse est attaquée ! Tous au portail de mage !', 28153),
(141824, 'frFR', 'On est censés se réfugier à Orgrimmar en abandonnant tout ce qu\’on a ici ?', 'On est censés se réfugier à Orgrimmar en abandonnant tout ce qu\’on a ici ?', 28153),
(141823, 'frFR', 'Ils ont soudain commencé à fermer les portes. Mais qu\’est-ce qui se passe ?', 'Ils ont soudain commencé à fermer les portes. Mais qu\’est-ce qui se passe ?', 28153),
(141822, 'frFR', 'Même si c\’est dangereux, je ne veux pas perdre toutes mes marchandises à cause de cette guerre !', 'Même si c\’est dangereux, je ne veux pas perdre toutes mes marchandises à cause de cette guerre !', 28153),
(141821, 'frFR', 'Je dois trouver mes amis !', 'Je dois trouver mes amis !', 28153),
(141820, 'frFR', 'Maman, elle a dit que les soldats nous protégeaient des méchants. Où est-ce qu\’ils sont partis ?', 'Maman, elle a dit que les soldats nous protégeaient des méchants. Où est-ce qu\’ils sont partis ?', 28153),
(141819, 'frFR', 'J\’ai eu trop peur ! Merci !', 'J\’ai eu trop peur ! Merci !', 28153),
(141818, 'frFR', 'Je veux mon papa !', 'Je veux mon papa !', 28153),
(141817, 'frFR', 'Où est la milice ?', 'Où est la milice ?', 28153),
(141816, 'frFR', 'Je vous dois la vie. Merci !', 'Je vous dois la vie. Merci !', 28153),
(141815, 'frFR', 'Leurs attaques n\’avaient jamais été aussi violentes !', 'Leurs attaques n\’avaient jamais été aussi violentes !', 28153),
(141814, 'frFR', 'Je peux me débrouiller à partir d\’ici. J\’espère que les autres vont bien !', 'Je peux me débrouiller à partir d\’ici. J\’espère que les autres vont bien !', 28153),
(141813, 'frFR', 'Je… je l\’ignore. Mayla, nous devons continuer. Baine, notre camarade et vous devez rassembler les autres. Rejoignez-nous ensuite au sommet.', '', 28153),
(141812, 'frFR', 'Enfant des… De quoi parle-t-il ?', '', 28153),
(141811, 'frFR', 'Oui… Approchez ! Votre force deviendra la nôtre, enfant des ténèbres !', '', 28153),
(141810, 'frFR', 'La dernière protection se trouve à la Cime de Haut-Roc. Et c\’est précisément là que nous allons. Nous devons unir nos forces, comme l\’ont fait Huln et ses alliés avant nous.', '', 28153),
(141809, 'frFR', 'C\’est exact. Quand j\’ai quitté la montagne pour rejoindre Mulgore, les protections se sont suffisamment affaiblies pour laisser les Ténèbres passer à travers.', '', 28153),
(141808, 'frFR', '', 'Et durant tout ce temps, les nécrosombres se sont terrés dans l\’ombre, attendant l\’appel de leur maître.', 28153),
(141807, 'frFR', 'Huln a alors fait ériger des protections pour endiguer l\’influence des Dieux très anciens. Bien que le général ait survécu, l\’essence d\’Uul\’gyneth a été emprisonnée.', '', 28153),
(141806, 'frFR', 'Huln a rallié des héros de toutes les tribus. Ensemble, ils ont combattu les serviteurs d\’Uul\’gyneth, les nécrosombres… mais les partisans des ténèbres étaient trop nombreux.', '', 28153),
(141805, 'frFR', 'Il y a fort longtemps, les Dieux très anciens ont tenté de soumettre Haut-Roc. Leur effort était mené par une terrible créature de cauchemar… Uul\’gyneth les Ténèbres.', '', 28153),
(141804, 'frFR', '', 'Mais nous sommes loin d\’en avoir fini. Corne-d\’Ebène, nous devons savoir ce que manigancent ces Ténèbres.', 28153),
(141803, 'frFR', 'Grisciel m\’a fait part de votre courage.', '', 28153),
(141802, 'frFR', 'J\’ai repris possession de mes esprits. Retournez à Totem-du-Tonnerre. Nous devons nous préparer pour la suite des évènements.', '', 28153),
(141801, 'frFR', '', 'Dépêchez-vous ! Les autres ne sont pas loin.', 28153),
(141800, 'frFR', '', 'Je resterai ici pendant que Grisciel vous assiste. Espérons que le rétablissement des protections suffira à libérer l\’esprit de Corne-d\’Ebène.', 28153),
(141799, 'frFR', '', 'Les eaux ont soulagé Corne-d\’Ebène, mais j\’ai peur qu\’il ne sombre à nouveau.', 28153),
(141798, 'frFR', 'Allez à Haut-Roc et aidez Mayla. Je vous rejoindrai bientôt.', '', 28153),
(141797, 'frFR', 'Je dois m\’assurer que les serviteurs des Dieux très anciens soient tous chassés de Mulgore.', '', 28153),
(141796, 'frFR', 'Les Dieux très anciens ne s\’empareront jamais de ma ville, monstre !', '', 28153),
(141795, 'frFR', 'Éradiquez-les ! Nul ne s\’opposera à mon retour !', '', 28153),
(141794, 'frFR', '', 'Les Trolls de sang seront invincibles s\’ils libèrent ce monstre… Même avec la Horde, vous ne suffirez pas à les arrêter. Il nous faut un nouveau plan.', 28153),
(141793, 'frFR', '', 'Ils ont arrêté de nous suivre… On dirait qu\’on les a semés.', 28153),
(141792, 'frFR', 'Très bien. Nous nous chargerons de débarrasser les Pitons-du-Tonnerre du fiel des Dieux très anciens.', '', 28153),
(141791, 'frFR', '', 'Je comprends. Baine, je dois regagner Haut-Roc avec Corne-d\’Ebène.', 28153),
(141790, 'frFR', 'Mayla… les bassins…', '', 28153),
(141789, 'frFR', '', 'Je n\’ai pas peur de toi ou de tes monstres. Je vous tuerai tous moi-même !', 28153),
(141788, 'frFR', '', 'Cours toujours, princesse ! Rien ne te sauvera de mon maître ! G\’huun, il va t\’avaler toute crue !', 28153),
(141787, 'frFR', '', 'Il faut partir, accrochez-vous !', 28153),
(141786, 'frFR', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tLa Reine des sables se met à |cFFFF0000|Hspell:257609|h[Enrager]|h|r !', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|tLa Reine des sables se met à |cFFFF0000|Hspell:257609|h[Enrager]|h|r !', 28153),
(141784, 'frFR', 'Les protections se sont affaiblies ! Il est à nous !', '', 28153),
(141783, 'frFR', 'Ensemble, nous retournerons aux marées et nous retrouverons notre puissance. Parce que c\’est notre nation !', '', 28153),
(141782, 'frFR', 'Nos puissants eaugures nous mèneront à la victoire avec le concours de la mer elle-même !', '', 28153),
(141781, 'frFR', 'Nous devons rassembler nos forces et agir comme un seul homme. Kul Tiras doit revenir à ses habitants, et pour toujours !', '', 28153),
(141780, 'frFR', 'La maison Chantorage doit prendre les rênes de ce royaume brisé et lui rendre sa gloire passée !', '', 28153),
(141779, 'frFR', 'Nous suons sang et eau, dans les champs et dans les chantiers navals de Boralus, pour une élite arrogante qui ne nous donne rien en retour.', '', 28153),
(141778, 'frFR', 'Enfants de la mer, ce jour marque l\’aube d\’un nouvel âge pour nous tous.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141777, 'frFR', 'Si vous aviez vu ce que j\’ai vu, vous feriez pareil. Venez et je vous montrerai !', '', 28153),
(141776, 'frFR', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tGolganneth vous choisit pour porter le |cFFFF0000|Hspell:257306|h[Don des mers]|h|r !', '|TInterface\\Icons\\ACHIEVEMENT_ZONE_VASHJIR:20|tGolganneth vous choisit pour porter le |cFFFF0000|Hspell:257306|h[Don des mers]|h|r !', 28153),
(141775, 'frFR', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tGolganneth vous choisit pour porter le |cFFFF0000|Hspell:257313|h[Don des cieux]|h|r !', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_AIR:20|tGolganneth vous choisit pour porter le |cFFFF0000|Hspell:257313|h[Don des cieux]|h|r !', 28153),
(141774, 'frFR', 'Énergie du système en baisse.', '', 28153),
(141773, 'frFR', 'Panne du système de visée p-p-principal…', '', 28153),
(141772, 'frFR', 'Perte de vie. Assistance requise.', '', 28153),
(141771, 'frFR', 'Dys-fonc-tion-ne-ment !', '', 28153),
(141770, 'frFR', '', 'Le sanctuaire doré ? Il s\’agit sans doute d\’Atal\’Dazar. C\’est une cité, une cité d\’or. Ou dorée, si vous préférez.$b$bMais pourquoi « sanctuaire », ça... Pour l\’or peut-être. Ou les dinosaures. Ou alors pour les dinosaures plaqués or !$b$bBref, à votre place, je tenterais ma chance là-bas.', 28153),
(141769, 'frFR', 'Apparemment, ils ont été traînés en haut du glacier, vers le nord-ouest.', '', 28153),
(141768, 'frFR', 'Avez-vous entendu parler d\’un endroit appelé le « sanctuaire doré » ?', 'Avez-vous entendu parler d\’un endroit appelé le « sanctuaire doré » ?', 28153),
(141767, 'frFR', 'Débusquez ces rats et éliminez-les, puis assurez-vous que les nôtres soient conduits en sécurité à Orgrimmar.', '', 28153),
(141766, 'frFR', 'Nous avons rassemblé les lâches dans le quartier des Mages et avons bouclé le reste de Fossoyeuse.', '', 28153),
(141765, 'frFR', 'Nos ennemis attaquent Fossoyeuse avec la ferme intention de reconquérir Lordaeron.', '', 28153),
(141764, 'frFR', 'Les civils courent un grave danger. La guerre fait rage à la surface et des dizaines d\’espions ont infiltré notre ville.', '', 28153),
(141762, 'frFR', 'Soldats de la Horde, l\’heure est venue !', '', 28153),
(141761, 'frFR', '', 'Une fois à Orgrimmar, regroupez-vous dans la vallée de l\’Honneur ! Vous êtes en danger ici !', 28153),
(141760, 'frFR', '', 'Mon portail est ouvert, nous devons partir !', 28153),
(141759, 'frFR', '', 'Allez à Orgrimmar ! Vous êtes en danger ici !', 28153),
(141758, 'frFR', 'Joli… tir…', '', 28153),
(141757, 'frFR', 'Vous pouvez toujours courir ! Je ne manque jamais ma cible.', '', 28153),
(141756, 'frFR', 'Vous allez être pris entre deux feux !', '', 28153),
(141755, 'frFR', 'J\’ai hâte d\’essayer ces balles sur des cibles vivantes.', '', 28153),
(141754, 'frFR', 'Une réinsertion réussie.', '', 28153),
(141753, 'frFR', 'Votre dernier repas ? Des balles dans le buffet !', '', 28153),
(141752, 'frFR', 'Votre sentence est la mort !', '', 28153),
(141751, 'frFR', 'C\’est bien aimable à vous de revenir pour votre exécution.', '', 28153),
(141750, 'frFR', 'Plus de bombes en approche !', '', 28153),
(141749, 'frFR', 'Oui, madame !', '', 28153),
(141748, 'frFR', '', 'Je veux que ces flammes brûlent encore plus !', 28153),
(141747, 'frFR', '', 'Du combustible pour les flammes ! Maintenant !', 28153),
(141746, 'frFR', '', 'Je vais vous réduire en cendres !', 28153),
(141745, 'frFR', '', 'Brûlez sur le bûcher !', 28153),
(141744, 'frFR', '', 'Faisons monter la température !', 28153),
(141743, 'frFR', 'Vous avez fait du mal à mon ami !', '', 28153),
(141742, 'frFR', '', 'Les étoiles les plus brillantes… s\’éteignent… en premier.', 28153),
(141741, 'frFR', 'Vous allez payer pour ce que vous avez fait !', '', 28153),
(141740, 'frFR', 'Détourne leur attention, mon gaillard ! Je vais me les faire !', '', 28153),
(141739, 'frFR', '', 'On doit trouver cette arme avant que Jakra\’zet mette la main dessus.', 28153),
(141738, 'frFR', '', 'Je ne sais pas à quoi elle ressemble ni où elle se trouve, mais si Jakra\’zet cache son existence au roi, c\’est que c\’est mauvais signe.', 28153),
(141737, 'frFR', '', 'Ils ratissent les dunes à la recherche d\’une arme capable de détruire la ville, et ils tuent ceux qui s\’opposent à eux.', 28153),
(141736, 'frFR', '', 'C\’est ce qui me semblait. Le général Jakra\’zet a rameuté des troupes dans le désert à l\’insu du roi.', 28153),
(141735, 'frFR', 'Prospection', 'Prospection', 28153),
(141734, 'frFR', 'Un peu, mon neveu ! Par ici, j\’ai du boulot pour vous.', '', 28153),
(141733, 'frFR', 'Hé, Rulf ! Cette demi-portion a de la ressource ! T\’as une mission à lui confier ?', '', 28153),
(141732, 'frFR', '', 'J\’aime bien les bulles. Elles me procurent un sentiment de sécurité.', 28153),
(141731, 'frFR', 'Saviez-vous que certaines villes ne sont protégées d\’aucune bulle magique ? La poussière doit s\’infiltrer partout, c\’est dégoûtant !', '', 28153),
(141730, 'frFR', '', 'J\’ai cru que je la reverrais jamais…', 28153),
(141729, 'frFR', 'La douleur, elle revient en même temps que les souvenirs…', '', 28153),
(141728, 'frFR', '', 'Alors comme ça, on ne supporte pas la chaleur ?', 28153),
(141727, 'frFR', '', 'Oh… J\’aime ce bruit de viande qui grille sur le feu !', 28153),
(141726, 'frFR', '', 'Vos cadavres feront un excellent combustible.', 28153),
(141725, 'frFR', '', 'J\’ai hâte de vous voir fondre.', 28153),
(141724, 'frFR', '', '$p, venez vite ! Rakera a retrouvé la mémoire !', 28153),
(141723, 'frFR', 'C\’est vous… qui étiez censés… saigner.', '', 28153),
(141722, 'frFR', '', 'Ma tête… Kaja, c\’est toi ?', 28153),
(141721, 'frFR', 'C\’est l\’heure de se mettre en chasse !', '', 28153),
(141720, 'frFR', 'Vous avez tué mon frère. Je vais vous réduire en charpie.', '', 28153),
(141719, 'frFR', 'Petit frère !', '', 28153),
(141718, 'frFR', 'Debout, mon frère ! On a des gens à tuer.', '', 28153),
(141717, 'frFR', 'Allez, les gars ! Montrons-leur que c\’est notre quartier ici !', '', 28153),
(141716, 'frFR', 'J\’ai aiguisé ces lames rien que pour vous.', '', 28153),
(141715, 'frFR', 'Mais… j\’avais obtenu… ma libération conditionnelle…', '', 28153),
(141714, 'frFR', 'Vous auriez dû rester dans vos cellules.', '', 28153),
(141713, 'frFR', 'Envoyez-moi à Ulduar (raid des Marcheurs du temps).', 'Envoyez-moi à Ulduar (raid des Marcheurs du temps).', 28153),
(141712, 'frFR', '', 'Salutations, $n. Vous ne vous souvenez sûrement pas de moi, nous avons fait connaissance la semaine prochaine.$b$bVoulez-vous retourner à Ulduar ?', 28153),
(141711, 'frFR', 'Je suis le mâle alpha !', '', 28153),
(141710, 'frFR', 'De la viande froide.', '', 28153),
(141709, 'frFR', 'De la viande fraîche !', '', 28153),
(141708, 'frFR', 'Affaiblissez le griffon mais assurez votre prise avec |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t|cFFFF0000|Hspell:269442|hS\’accrocher|h|r.', '', 28153),
(141707, 'frFR', 'Je suis prêt à y aller.', 'Je suis prête à y aller.', 28153),
(141706, 'frFR', '', 'Mettons-nous au travail.', 28153),
(141705, 'frFR', '', 'La voie est libre, maintenant. Une fois que nous aurons accosté aux ruines de Zul\’jan, il nous faudra aller vite.', 28153),
(141704, 'frFR', '', 'Les Trolls de sang n\’ont aucune pitié et leur détermination, nourrie par la puissance d\’un Dieu très ancien, est infinie.', 28153),
(141703, 'frFR', '', 'Ce n\’est pas faux… Tu es bien plus observateur que mon père.', 28153),
(141701, 'frFR', '', 'Des Morts-vivants ! Ils veulent sûrement atteindre Zuldazar. Il faut les détruire !', 28153),
(141696, 'frFR', 'Le charme ne semble avoir aucun effet. Essayez-le d\’abord sur des esclaves maléformés.', '', 28153),
(141695, 'frFR', 'Ce type a pas l\’air bien malin.', '', 28153),
(141694, 'frFR', 'Queue-du-Bonheur fonce vers les chutes d\’eau !', '', 28153),
(141693, 'frFR', '', '', 28153),
(141692, 'frFR', '|cffffff00+$1i morceaux d\’armure|r', '|cffffff00+$1i morceaux d\’armure|r', 28153),
(141691, 'frFR', 'Queue-du-Bonheur court se mettre à l\’abri !', '', 28153),
(141690, 'frFR', '', 'Ces sectateurs, qu\’est-ce qu\’ils ont fait à Rakera… Elle se souvient même plus de son nom…', 28153),
(141689, 'frFR', 'Vous, là ! Oui, vous, approchez discrètement.', '', 28153),
(141688, 'frFR', '', 'Qu\’est-ce qu\’ils t\’ont fait…', 28153),
(141687, 'frFR', '', 'Nous sommes tous Akunda.', 28153),
(141686, 'frFR', '', 'Rakera ?', 28153),
(141685, 'frFR', '', 'Elle est ici ! Vivante ! Rakera !', 28153),
(141684, 'frFR', '', 'Rakera !', 28153),
(141683, 'frFR', '', 'Il doit bien y avoir quelqu\’un qui sait quelque chose dans ce temple.', 28153),
(141682, 'frFR', 'Je me fiche de ce que vous avez à proposer au roi et à sa fille. Sachez juste qu\’on ne veut pas de vous à Zuldazar.$b$bEt même si la princesse a une grande influence, elle n\’est pas encore reine.$b$bEn attendant, le pouvoir de Zuldazar est entre mes mains et celles du conseil zanchuli.', '', 28153),
(141681, 'frFR', '', 'Il s\’agit d\’une cérémonie officielle. Silence.', 28153),
(141680, 'frFR', 'T\’laartos l\’a enfin compris.', '', 28153),
(141679, 'frFR', 'Nous avons tous une part d\’ombre qu\’il est difficile d\’affronter.', '', 28153),
(141678, 'frFR', '', 'T\’laartos… Vous avez affronté vos peurs… vos échecs… et ainsi vous venez de renaître.', 28153),
(141677, 'frFR', '', 'Bon retour parmi nous, T\’laartos.', 28153),
(141676, 'frFR', '', 'Si Rakera est à l\’intérieur de ce temple, on la trouvera.', 28153),
(141675, 'frFR', 'Vous sentir bizarre ! Coco !', '', 28153),
(141674, 'frFR', 'Désolé, vous sentir guano de perroquet ! Coco !', '', 28153),
(141673, 'frFR', 'Kragg mort ! Jacasse désolé !', '', 28153),
(141672, 'frFR', '', 'Ah, quelqu\’un de la Horde. Bizarre…', 28153),
(141671, 'frFR', '$n a attaqué les troupes de l\’Alliance à la scierie !', '$n a attaqué les troupes de l\’Alliance à la scierie !', 28153),
(141669, 'frFR', '', 'Ici, même le vent, il vibre au diapason du pouvoir des Loas. Pa\’ku est quelque part dans le ciel, j\’sens sa présence.$b$bC\’est ma première fois en Zandalar, mais mon grand-père, il m\’a raconté des tas d\’histoires sur cet endroit.', 28153),
(141668, 'frFR', '', 'Les Loas, ils sont puissants par ici. D\’ailleurs, je sens la présence du mien. Gonk, il rôde derrière chaque arbre et chaque buisson.$b$bOuais, l\’est tout près. On va avoir la chance de le voir en personne.', 28153),
(141667, 'frFR', 'Nous ne nous avouerons pas vaincus si facilement. Soldats, reprenez notre scierie !', '', 28153),
(141666, 'frFR', 'Bienvenue, mon enfant.$b$bJe suis le seigneur des maléfices Raal, le plus grand des intercesseurs du Loa des vents Pa\’ku et membre du conseil zanchuli.$b$bJe suis aussi très important et très occupé. Que voulez-vous ?', '', 28153),
(141665, 'frFR', '', 'Notre temps avec le seigneur des maléfices, il est compté. Taisez-vous. On a beaucoup à voir.', 28153),
(141664, 'frFR', 'Mon ami !', '', 28153),
(141663, 'frFR', '', 'Avec ça, les Sephraks sauront qu\’il faut craindre les Vulpérins !', 28153),
(141662, 'frFR', 'Il semble que le général Jakra\’zet, le parvenu de Furie-des-sables qui commande l\’armée de Zuldazar, ait décidé de retirer ses gardes du port.\n\nTous les Trolls se réjouissent pas du décret de la princesse Talanji qui autorise l\’accès aux quais aux non-Trolls, vous savez.\n\nElle va avoir besoin de l\’appui d\’au moins un membre du conseil zanchuli dans cette affaire. Heureusement, je sais où en trouver deux.', '', 28153),
(141660, 'frFR', '', 'Les Vulpérins ne sont ni faibles, ni lâches ! Ils nous redouteront !', 28153),
(141658, 'frFR', 'Drain en cours…', 'Drain en cours…', 28153),
(141657, 'frFR', '', 'Ces Sephraks paieront pour ce qu\’ils ont fait à notre foyer.', 28153),
(141655, 'frFR', 'Vous en faites pas pour moi, $gm\’chieur:mam\’jelle;… hips ! J\’vais retourner à mes occupations… euh… mais où ch\’est que j\’suis ?$b$bBon, laissez-moi dessaouler, et quand vous… hips… reviendrez, j\’aurai décampé. J\’vous l\’jure.', '', 28153),
(141654, 'frFR', 'Ha ha, c\’est le plus tordant dans c\’te histoire. Il a réussi à se faire ser… hips… rer ! Ch\’t\’idiot a essayé d\’zigouiller quelqu\’un.$b$bIl est en zonzon avec le reste de ses affaires…hips… S\’il les a toujours, j\’parie qu\’eul\’ joyau, y faudra lui arracher des mains…hips… et pas d\’shon vivant !$b$bDites, vous allez pas essayer d\’me tuer moi ausshi, hein ? Hips… J\’vous ai jamais rien fait.$b$bBon, allez, j\’m\’en vais dessaouler dans un coin…hips. L\’honneur des marins, toussa toussa… Ha ha.', '', 28153),
(141653, 'frFR', 'Où se trouve celui qui a volé le joyau ?', 'Où se trouve celui qui a volé le joyau ?', 28153),
(141652, 'frFR', 'Ce vaurien, y sh\’est fait la malle avec notre…hips… joyau. Y nous a fallu des plombes pour récupérer c\’machin et qu\’est-ce qu\’y fait ? Hips…$b$bY s\’barre en pleine… hips… nuit. On allait l\’vendre et sh\’en mettre plein les fouilles !$b$b<Salton boit une nouvelle rasade.>$b$bDites-voir, $gm\’sieur:mam\’zelle;, z\’auriez pas deux-trois piéchettes sur vous, par hasard ?', '', 28153),
(141651, 'frFR', '', 'Je suis prête. Allons traquer des Sephraks.', 28153),
(141649, 'frFR', 'La princesse Talanji dit qu\’elle a besoin de votre aide au sujet de Jakra\’zet.', 'La princesse Talanji dit qu\’elle a besoin de votre aide au sujet de Jakra\’zet.', 28153),
(141648, 'frFR', '', 'Vous avez devant vous la druidesse de guerre Loti, disciple de Gonk, championne de la chasse et maîtresse des sentiers. Qu\’est-ce que vous voulez, $c ?', 28153),
(141647, 'frFR', 'Faites chauffer les scies ! Il nous faut plus de bois.', '', 28153),
(141646, 'frFR', 'C\’est l\’un de nos problèmes du moment. Jakra\’zet refuse d\’obéir à la princesse.$b$bJ\’ai besoin du soutien d\’un autre membre du conseil zanchuli, mais les deux qui se trouvent ici, ils sont pris par le règlement d\’un conflit tribal.$b$bAllez à Tal\’aman ou Tal\’farrak et voyez si vous pouvez convaincre l\’un de ces Zanchuli de nous aider.$b$bJe m\’en chargerais bien moi-même, mais une telle tâche est indigne de moi.', '', 28153),
(141645, 'frFR', 'La princesse Talanji exige de savoir où sont les gardes.', 'La princesse Talanji exige de savoir où sont les gardes.', 28153),
(141644, 'frFR', 'Dès que j\’ai vu votre tête à Hurlevent, j\’ai su que la prophétie se réalisait.$b$bLes esprits, ils m\’ont montré bien des choses. Et dans ces visions, vous étiez au cœur d\’un tas de grands évènements à venir.$b$bLes pièces commencent à bouger, $c. Bientôt, vous et moi, on va secouer ce monde jusqu\’à ses fondations.', '', 28153),
(141643, 'frFR', 'Si j\’étais vous, je ferais la même chose. Bonne chance.', 'Et je vous invite à faire la même chose. Bonne chance !', 28153),
(141642, 'frFR', 'Oui… renonce, T\’laartos. Embrasse la véritable puissance !', '', 28153),
(141641, 'frFR', 'Défais-toi des chaînes avec lesquelles la Lumière te retient captif.', '', 28153),
(141640, 'frFR', 'La Lumière ne t\’apportera pas la véritable puissance.', '', 28153),
(141639, 'frFR', 'Un tel pouvoir nous attend, T\’laartos.', '', 28153),
(141638, 'frFR', 'La Lumière a toujours accompagné T\’laartos ! T\’laartos n\’abandonnera JAMAIS la Lumière !', '', 28153),
(141637, 'frFR', 'ASSEZ !', '', 28153),
(141636, 'frFR', 'Non…', '', 28153),
(141635, 'frFR', 'Non… ce n\’est pas la réalité. Ce n\’est pas le vrai T\’laartos !', '', 28153),
(141634, 'frFR', 'Ah ! $p, faites partir les serpents !', '', 28153),
(141633, 'frFR', 'Voilà qui est… légèrement embarrassant pour T\’laartos.', '', 28153),
(141632, 'frFR', 'T\’laartos peut soulever des montagnes !', '', 28153),
(141631, 'frFR', 'T\’laartos a affronté des monstres semblables au service de l\’armée de la Lumière.', '', 28153),
(141630, 'frFR', 'Ahh, Ika. T\’laartos a élevé cet elekk quand sa mère a été tuée.', '', 28153),
(141629, 'frFR', 'Non ! Les ténèbres n\’emporteront pas T\’laartos !', '', 28153),
(141628, 'frFR', 'T\’laartos était-il destiné à emprunter cette voie ? T\’laartos a-t-il vraiment l\’étoffe d\’un Sancteforge ?', '', 28153),
(141623, 'frFR', 'Vous m\’avez encore sauvé la vie ! Je retourne au camp avant d\’attraper froid.', '', 28153),
(141620, 'frFR', '', 'Laissez m\’en quelques-uns !', 28153),
(141619, 'frFR', '', 'Les Vulpérins sont prêts. On va semer la terreur parmi les infidèles.', 28153),
(141618, 'frFR', 'Mmmm… j\’vous aurais… mmmm…', '', 28153),
(141617, 'frFR', 'J\’voulais m\’servir de l\’or pour me marier. <pleurniche>', '', 28153),
(141616, 'frFR', 'Dès que j\’me s\’rai trouvé un bateau… hips… j\’me vengerai !', '', 28153),
(141615, 'frFR', 'Z\’avez pris not\’… chatané joyau… hips… vermine !', '', 28153),
(141614, 'frFR', 'C\’est vous qu\’avez notre… hips…', '', 28153),
(141613, 'frFR', 'Il faut que j\’arrête de laisser Nisha prendre toutes les décisions...', '', 28153),
(141612, 'frFR', '', 'Je doute qu\’elle le puisse. Votre peuple n\’est pas adapté. Enfin, ne l\’est plus.', 28153),
(141611, 'frFR', 'Sois prudente, Meera. Les anciennes routes trolles ont tendance à malmener nos chariots.', '', 28153),
(141610, 'frFR', '', 'Les Sephraks vont regretter d\’avoir attaqué notre caravane.', 28153),
(141609, 'frFR', 'Tendez-moi ce cordage ! On garde le cap !', '', 28153),
(141608, 'frFR', '', 'Et voilà pour vous, $n. La traduction du journal. Un ouvrage passionnant, si vous voulez mon avis.', 28153),
(141607, 'frFR', '', 'Vraiment ? Oui, c\’est bien ça ! Bon, où sont mes carnets vierges… Ah, en voilà un.', 28153),
(141606, 'frFR', '', 'OH ! Voici donc ce que signifie cette rune ! Intéressant…', 28153),
(141605, 'frFR', '', 'Vous les avez tous ? Beau travail, $n. Je vais pouvoir traduire le journal.', 28153),
(141604, 'frFR', '<Le soldat marmonne des propos incompréhensibles.>', '<Le soldat marmonne des propos incompréhensibles.>', 28153),
(141603, 'frFR', 'Voici les livres que vous aviez demandés.', 'Voici les livres que vous aviez demandés.', 28153),
(141602, 'frFR', 'C\’est la mer qui monte ou nous qui descendons ?\n\nÀ croire qu\’on n\’en verra jamais le fond...', 'C\’est la mer qui monte ou nous qui descendons ?\n\nÀ croire qu\’on n\’en verra jamais le fond...', 28153),
(141601, 'frFR', 'Parfait, tout doit être absolument parfait. C\’est la chose qui l\’a dit...\n\nMais quelle chose, au juste ?', 'Parfait, tout doit être absolument parfait. C\’est la chose qui l\’a dit...\n\nMais quelle chose, au juste ?', 28153),
(141600, 'frFR', 'Les Zandalari, y vont pas tarder à avoir une grosse surprise !', 'Les Zandalari, y vont pas tarder à avoir une grosse surprise !', 28153),
(141599, 'frFR', 'Les croggs, y grandissent bien. On pourra bientôt les monter.', 'Les croggs, y grandissent bien. On pourra bientôt les monter.', 28153),
(141598, 'frFR', 'Pardon, ma\’da, j\’en ai pas pour longtemps.', 'Pardon, ma\’da, j\’en ai pas pour longtemps.', 28153),
(141597, 'frFR', 'Tu devrais aiguiser ta lame. Paraît qu\’on va bientôt se battre contre les Zandalari.', 'Tu devrais aiguiser ta lame. Paraît qu\’on va bientôt se battre contre les Zandalari.', 28153),
(141596, 'frFR', 'Chef de guerre Coursevent, voici le grand chef Mayla Haut-Roc.', '', 28153),
(141595, 'frFR', 'Ce sac à dos porte notre marque. On dirait bien qu\’on est au bon endroit.', '', 28153),
(141594, 'frFR', 'Je reconnais cette hache. On est sur la bonne piste.', '', 28153),
(141593, 'frFR', 'Ce pauvre petit est mort depuis des lustres. Allons voir vers l\’est si nous trouvons le chariot de marchandises.', '', 28153),
(141592, 'frFR', 'Votre tronche, elle me dit rien. Feriez bien d\’entrer fissa, paraît que les membres du groupe de travail de Najima, ils ont été retrouvés raides.', 'Votre tronche, elle me dit rien. Feriez bien d\’entrer fissa, paraît que les membres du groupe de travail de Najima, ils ont été retrouvés raides.', 28153),
(141591, 'frFR', 'La dernière protection se trouve à la Cime de Haut-Roc. Et c\’est précisément là que nous allons. Nous devons unir nos forces, comme l\’ont fait Huln et ses alliés avant nous.', '', 28153),
(141590, 'frFR', 'C\’est exact. Quand j\’ai quitté la montagne pour rejoindre Mulgore, les protections se sont suffisamment affaiblies pour laisser les ténèbres s\’échapper.', '', 28153),
(141589, 'frFR', '', 'Et durant tout ce temps, les nécrosombres se sont terrés dans l\’ombre, attendant l\’appel de leur maître.', 28153),
(141588, 'frFR', 'Huln a alors fait ériger des protections pour endiguer l\’influence des Dieux très anciens. Bien que le général ait survécu, l\’essence d\’Uul\’gyneth a été emprisonnée.', '', 28153),
(141587, 'frFR', 'Huln a rallié des héros de toutes les tribus. Ensemble, ils ont combattu les serviteurs d\’Uul\’gyneth, les nécrosombres… mais les partisans de l\’ombre étaient trop nombreux.', '', 28153),
(141586, 'frFR', 'Il y a fort longtemps, les Dieux très anciens ont tenté de soumettre Haut-Roc. Leur effort était mené par une terrible créature de cauchemar… Uul\’gyneth les Ténèbres.', '', 28153),
(141585, 'frFR', 'Suivez-moi.', '', 28153),
(141584, 'frFR', '<Le maire est dans un état catatonique.>', '', 28153),
(141583, 'frFR', '<Chercher la source du sort.>', '<Chercher la source du sort.>', 28153),
(141582, 'frFR', '<L\’effigie qui se dresse au centre du village vibre d\’une énergie maléfique, similaire à celle qui emprisonne les habitants. Elle sert probablement à maintenir le sort.\n\nSuffirait-il de la détruire pour lever la malédiction ?>', '', 28153),
(141581, 'frFR', '<Cet homme correspond à la description de Cyril Leblanc, maire de Havrebrune. Malheureusement, il n\’est pas en état de vous aider à l\’heure actuelle.\n\nTout comme ses concitoyens, il semble sous l\’effet d\’un étrange sort. Bien qu\’il respire encore, il est incapable de bouger ou d\’ouvrir la bouche.\n\nIl va falloir trouver un moyen de lever cette malédiction si vous voulez qu\’il vous aide à contacter la maison Malvoie.>', '', 28153),
(141580, 'frFR', 'Vous me sauvez la vie ! Je me demande où les Baroudeurs vont m\’envoyer la prochaine fois...', '', 28153),
(141579, 'frFR', 'Les protections se sont affaiblies ! Il est à nous !', '', 28153),
(141578, 'frFR', 'Vous avez échoué ! Les ténèbres se lèvent et annoncent la chute de Haut-Roc !', '', 28153),
(141577, 'frFR', 'La Légion n\’était rien comparée à notre puissance ! Capitulez !', '', 28153),
(141576, 'frFR', 'Les Cornes-Célestes serviront mes maîtres ! Vous deviendrez l\’ombre qui obscurcit les cieux !', '', 28153),
(141575, 'frFR', 'Servez vos véritables maîtres, Drogbar ! Toute résistance causera votre perte !', '', 28153),
(141573, 'frFR', '', 'Bonjour ! Euh… Vous intéresseriez-vous par hasard à l\’histoire de Kul Tiras ? J\’ai plusieurs tomes consacrés aux origines et à la politique de notre grande et belle nation. Je vous assure que le sujet est tout simplement fascinant.$b$bJ\’excelle également en calligraphie et pourrais vous enseigner l\’art de l\’encre et de la plume !', 28153),
(141572, 'frFR', 'Un faux pas et on vous envoie six pieds sous terre.', '', 28153),
(141571, 'frFR', 'Meera, prépare le chariot pour aller récupérer des fournitures au port. Nos nouveaux alliés peuvent vous accompagner et continuer leurs recherches.', '', 28153),
(141570, 'frFR', 'Cette humidité, elle est presque aussi pénible que vot\’ tronche.', 'Cette humidité, elle est presque aussi pénible que vot\’ tronche.', 28153),
(141569, 'frFR', 'Qu\’est-ce que vous matez comme ça ?', 'Qu\’est-ce que vous matez comme ça ?', 28153),
(141568, 'frFR', 'Z\’avez l\’oreille du roi, alors on va pas vous buter. Mais peut-être que ça durera pas...', 'Z\’avez l\’oreille du roi, alors on va pas vous buter. Mais peut-être que ça durera pas...', 28153),
(141567, 'frFR', 'Usurpateurs ! Votre Horde, elle va payer ce qu\’elle a fait aux nôtres en Tanaris.', 'Usurpateurs ! Votre Horde, elle va payer ce qu\’elle a fait aux nôtres en Tanaris.', 28153),
(141566, 'frFR', 'Bien le bonjour, $gnoble sire:gente dame;. Souhaitez-vous en savoir davantage sur l\’exquis métier de lapidaire ?$b$bPlus communément appelé joaillerie ?', '', 28153),
(141565, 'frFR', 'Souriez tant que vous pouvez, $c. Le moindre faux pas ici, et on vous tue nous-mêmes.', 'Souriez tant que vous pouvez, $c. Le moindre faux pas ici, et on vous tue nous-mêmes.', 28153),
(141564, 'frFR', 'La Horde, elle nous a préféré ses précieux Elfes de sang. Et elle a tué notre plus grand chef, Zul\’jin.$b$bVous et les vôtres, z\’avez une sacrée dette de sang envers nous, mec.', '', 28153),
(141563, 'frFR', 'Faites gaffe. Dès que la princesse, elle aura plus besoin de vous, z\’aurez affaire à mon couteau en souvenir de c\’que la Horde, elle a fait à Zul\’jin.', '', 28153),
(141562, 'frFR', 'Z\’avez la marque de la princesse Talanji, alors on peut pas vous tuer. Mais on est pas non plus obligés d\’vous aimer.', '', 28153),
(141561, 'frFR', 'Qu\’est-ce que vous matez comme ça ?', '', 28153),
(141559, 'frFR', 'Le temple est en ruines ! C\’est encore pire que ce que je craignais...', '', 28153),
(141558, 'frFR', 'Faut que je me grouille de retourner au temple. Allez savoir ce qu\’il s\’est passé là-bas en mon absence...', '', 28153),
(141557, 'frFR', '', 'Trop tard, ils m\’appartiennent !', 28153),
(141556, 'frFR', 'Je suis enfin libéré de l\’emprise des Dieux très anciens. Je vous remercie.', '', 28153),
(141555, 'frFR', 'Mayla ! Nous devons faire front ensemble !', '', 28153),
(141554, 'frFR', '', 'Je ne peux laisser les Ténèbres s\’emparer du corps de mon père !', 28153),
(141552, 'frFR', 'Je voulais… voir le…', 'Je voulais… voir le…', 28153),
(141549, 'frFR', 'Allez voir au chaudron si j\’y suis !', 'Allez voir au chaudron si j\’y suis !', 28153),
(141547, 'frFR', 'Ah, merci de m\’avoir libéré ! Je n\’aurais jamais dû faire confiance à ces traîtres de Tortaka !', '', 28153),
(141546, 'frFR', 'Vol\’jamba avait promis…', 'Vol\’jamba avait promis…', 28153),
(141544, 'frFR', 'Alors, il avait… tort ?', 'Alors, il avait… tort ?', 28153),
(141538, 'frFR', 'Seul Vol\’jamba peut nous sauver !', 'Seul Vol\’jamba peut nous sauver !', 28153),
(141536, 'frFR', 'Approchez… et reniflez. On va voir qui a la volonté la plus forte !', '', 28153),
(141535, 'frFR', 'Je… ne me soumettrai… jamais…', 'Je… ne me soumettrai… jamais…', 28153),
(141528, 'frFR', 'Il m\’a dit… qu\’on survivrait…', 'Il m\’a dit… qu\’on survivrait…', 28153),
(141527, 'frFR', 'Pourquoi personne m\’écoute ? La fin approche !', 'Pourquoi personne m\’écoute ? La fin approche !', 28153),
(141524, 'frFR', 'Compris, chef.', '', 28153),
(141523, 'frFR', 'Léo !', '', 28153),
(141522, 'frFR', 'Des voleurs de bois ! Chope-les, Léo !', '', 28153),
(141519, 'frFR', '', '$n, c\’est vous ? Où est-ce qu\’on est ?', 28153),
(141518, 'frFR', 'Ce T\’laartos est dévoué à la Lumière, mais… il pactise avec les ténèbres ? Non ! Ce n\’est pas le destin de T\’laartos !', '', 28153),
(141517, 'frFR', 'Mon prophète, il dit vrai. C\’est pour ça qu\’il est toujours à mes côtés.', '', 28153),
(141512, 'frFR', 'Prenez le sceau que je vous ai donné et frappez-le sur le gong.', '', 28153),
(141510, 'frFR', 'Bah !', '', 28153),
(141509, 'frFR', 'Reculez ! Ne touchez pas à ça !', '', 28153),
(141508, 'frFR', 'Voilà ce que dit la vision : les voiles d\’or consacrent l\’avènement du chaos. Le manipulateur projette de briser le sceau.', '', 28153),
(141507, 'frFR', 'Je suis d\’humeur généreuse, alors je vais t\’écouter. Vous, par contre…', '', 28153),
(141506, 'frFR', 'J\’ai quelques mots à dire à mon ancien élève. Retrouvez-moi quand vous en aurez fini avec les imbéciles qui le suivent.', '', 28153),
(141505, 'frFR', 'Arrête de te cacher derrière ton masque. Tu fais que retarder l\’inévitable.', '', 28153),
(141504, 'frFR', 'Alors emmenez notre porte-parole avec vous et mettez un terme à tout ça.', '', 28153),
(141503, 'frFR', 'Selon vos désirs, mon roi. Mais mes visions, elles m\’ont montré que Vol\’jamba mourra pas de ma main.', '', 28153),
(141502, 'frFR', 'C\’est votre responsabilité, prophète. À vous de régler ça.', '', 28153),
(141501, 'frFR', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|t|cFFFF0000|Hspell:258068|h Le [Regard de Sargeras]|h|r se pose sur le champ de bataille…', '|TInterface\\Icons\\Sha_Ability_Rogue_BloodyEye_nightmare:20|t|cFFFF0000|Hspell:258068|h Le [Regard de Sargeras]|h|r se pose sur le champ de bataille…', 28153),
(141500, 'frFR', 'Nigel ! Te voilà !', '', 28153),
(141499, 'frFR', '', 'Mais bon, que voulez-vous, c\’est la rançon de l\’exploration ! Et puis, je m\’en suis sortie sans une égratignure.', 28153),
(141498, 'frFR', '', 'Hélas, c\’est bien tout ce que j\’ai pu sauver à moi seule.', 28153),
(141497, 'frFR', 'Je suis bien content que vous ayez réussi à vous sauver.', '', 28153),
(141496, 'frFR', 'Le chemin mène-t-il à la grandeur ? À la gloire ? Ou à l\’anéantissement ?', '', 28153),
(141495, 'frFR', 'Une âme est confrontée à bien des vérités. Certaines sont nobles… D\’autres…', '', 28153),
(141494, 'frFR', 'Une offre rejetée… Et pourtant la peur persiste.', '', 28153),
(141493, 'frFR', 'Peut-être faut-il embrasser la peur des ténèbres pour la surmonter.', '', 28153),
(141492, 'frFR', 'La peur est implacable. Impitoyable. C\’est un adversaire à vaincre.', '', 28153),
(141491, 'frFR', 'Sain et sauf. En sécurité. Loin de tout et de tous.', '', 28153),
(141490, 'frFR', 'La solitude est-elle la réponse ? Nul ne peut atteindre celui qui est seul.', '', 28153),
(141489, 'frFR', 'L\’ennemi est tapi dans l\’ombre. Sommes-nous en mesure de vaincre les ténèbres ?', '', 28153),
(141488, 'frFR', 'C\’est injuste ! Tout n\’est qu\’illusion !', '', 28153),
(141487, 'frFR', 'Les distractions offrent une échappatoire.', '', 28153),
(141486, 'frFR', 'S\’enfoncer… trouver refuge… et réconfort…', '', 28153),
(141485, 'frFR', 'N\’y a-t-il aucun réconfort ? Aucun soulagement ?', '', 28153),
(141484, 'frFR', 'Même là où il n\’y a plus d\’espoir, on peut trouver le répit.', '', 28153),
(141483, 'frFR', 'L\’angoisse et la souffrance… la recherche de réconfort.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141482, 'frFR', 'La bonté n\’a pas sa place ici.', '', 28153),
(141481, 'frFR', 'La douleur est l\’architecte des souvenirs.', '', 28153),
(141480, 'frFR', 'Nous pouvons seulement avancer.', '', 28153),
(141479, 'frFR', 'Je me souviens d\’une époque où seuls les Trolls avaient droit de cité en Zandalar. Enfin... les Trolls et les Tortollans, bien sûr.\n\nOh, ils ont bien tenté de se débarrasser de nous, une fois. Il me semble que c\’était sous le règne du roi Tezlekhan le Virulent, l\’arrière-grand-père de Rastakhan. Un Troll orgueilleux, et le mot est faible. Nous l\’avons fait changer d\’avis plus rapidement qu\’un élémentaire lors d\’un rassemblement de chamans.\n\nVous n\’avez pas idée du nombre de secrets inavouables que l\’on peut glaner sur une dynastie royale au fil des siècles.', 'Je me souviens d\’une époque où seuls les Trolls avaient droit de cité en Zandalar. Enfin… les Trolls et les Tortollans, bien sûr.\n\nOh, ils ont bien tenté de se débarrasser de nous, une fois. Il me semble que c\’était sous le règne du roi Tezlekhan le Virulent, l\’arrière-grand-père de Rastakhan. Un Troll orgueilleux, et le mot est faible. Nous l\’avons fait changer d\’avis plus rapidement qu\’un élémentaire lors d\’un rassemblement de chamans.\n\nVous n\’avez pas idée du nombre de secrets inavouables que l\’on peut glaner sur une dynastie royale au fil des siècles.', 28153),
(141478, 'frFR', 'Les Zandalari laissent les nôtres circuler librement sur leurs terres et en échange, nous leur fournissons de précieuses informations.\n\nEt vous, que leur avez-vous promis, au juste ?', 'Les Zandalari laissent les nôtres circuler librement sur leurs terres et en échange, nous leur fournissons de précieuses informations.\n\nEt vous, que leur avez-vous promis, au juste ?', 28153),
(141477, 'frFR', 'Hé, $c ! De quel continent venez-vous ?', 'Hé, $c ! De quel continent venez-vous ?', 28153),
(141476, 'frFR', '', 'Espérons que Rokhan et les autres puissent rentrer indemnes à Zul\’jan… sinon ce voyage va tourner court.', 28153),
(141475, 'frFR', 'Ah, vous semblez être $Utaillé:taillée; pour l\’aventure. Quels sont vos tarifs ? Il se pourrait que j\’aie besoin de votre aide pour récupérer un objet précieux dans le cadre d\’une mission… particulièrement… dangereuse.', 'Ah, vous semblez être $Utaillé:taillée; pour l\’aventure. Quels sont vos tarifs ? Il se pourrait que j\’aie besoin de votre aide pour récupérer un objet précieux dans le cadre d\’une mission… particulièrement… dangereuse.', 28153),
(141474, 'frFR', 'On se connaît ? Ma mémoire n\’est plus ce qu\’elle était il y a encore un siècle de cela.', 'On se connaît ? Ma mémoire n\’est plus ce qu\’elle était il y a encore un siècle de cela.', 28153),
(141473, 'frFR', 'Oh, ils ont laissé la Horde entrer à Zuldazar ? En voilà, une politique progressiste.', 'Oh, ils ont laissé la Horde entrer à Zuldazar ? En voilà, une politique progressiste.', 28153),
(141472, 'frFR', '', '', 28153),
(141471, 'frFR', '', 'Repoussez ces Trolls de sang, nous ne pouvons pas les laisser couler notre barge !', 28153),
(141470, 'frFR', '', 'Regardez ! Des Trolls de sang. Ils se préparent à attaquer ma cité, j\’en suis sûre.', 28153),
(141469, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|t Quittez les baies de construction pendant le |cFFFF0000|Hspell:248061|h[Protocole de purge]|h|r pour éviter d\’être tué !', '|TInterface\\Icons\\SPELL_FIRE_IMMOLATION.BLP:20|t Quittez les baies de construction pendant le |cFFFF0000|Hspell:248061|h[Protocole de purge]|h|r pour éviter d\’être tué !', 28153),
(141468, 'frFR', '|TInterface\\ICONS\\ABILITY_HUNTER_SNIPERSHOT.BLP:20|t Éloignez-vous du boss pendant |cFFF00000|Hspell:246220|h[Bombardement gangrené]|h|r pour éviter de subir des dégâts !', '', 28153),
(141467, 'frFR', '|TInterface\\ICONS\\spell_shadow_shadesofdarkness.blp:20|t Rapprochez-vous de vos alliés pour éviter |cFFF00000|Hspell:243963|h[Seul dans les ténèbres]|h|r !', '', 28153),
(141466, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t Les destructeurs gangrimprégnés blessent Eonar avec leur |cFFFF0000|Hspell:246305|h[Frappe d\’artillerie]|h|r. Éliminez-les au plus vite !', '|TInterface\\Icons\\SPELL_FIRE_FELFLAMESTRIKE.BLP:20|t Les destructeurs gangrimprégnés blessent Eonar avec leur |cFFFF0000|Hspell:246305|h[Frappe d\’artillerie]|h|r. Éliminez-les au plus vite !', 28153),
(141465, 'frFR', 'Cette créature se retournera pour attaquer les personnages-joueurs. Assurez-vous qu\’elle vise un tank avant de vous en prendre à elle !', 'Cette créature se retournera pour attaquer les personnages-joueurs. Assurez-vous qu\’elle vise un tank avant de vous en prendre à elle !', 28153),
(141464, 'frFR', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|t Il est possible d\’éviter la |cFFFF0000|Hspell:248333|h[Tempête de météores]|h|r. Pour ce faire, assurez-vous d\’éviter les zones vertes au sol.', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE.BLP:20|t Il est possible d\’éviter la |cFFFF0000|Hspell:248333|h[Tempête de météores]|h|r. Pour ce faire, assurez-vous d\’éviter les zones vertes au sol.', 28153),
(141463, 'frFR', 'C\’est quoi, ce bruit ?', '', 28153),
(141462, 'frFR', 'Allô ? Y a quelqu\’un ?', '', 28153),
(141461, 'frFR', 'NUB NUB, VIENS UN PEU PAR ICI ET NETTOIE-MOI CETTE DOUKE !', '', 28153),
(141460, 'frFR', 'Bouge de là, saleté de lézard bigleux.', 'Bouge de là, saleté de lézard bigleux.', 28153),
(141459, 'frFR', '', 'Arrêtez donc de négocier comme un petit crotale. Parlons rond : vous voulez quoi ?', 28153),
(141458, 'frFR', '', 'Raal, vot\’ femme, elle a essayé de me tuer pas plus tard que ce matin. Qu\’est-ce qu\’elle va s\’imaginer ?', 28153),
(141457, 'frFR', '', 'Raal, faut régler le problème une fois pour toutes. Les doléances des Amani, il faut qu\’elles cessent.', 28153),
(141456, 'frFR', 'Un yéti ! J\’étais dans le vrai. Une créature humanoïde, mais velue comme un ours.', '', 28153),
(141455, 'frFR', '', 'Beurk... La cheule penchée des algues me file... la naujée... <burp> Oh oh...', 28153),
(141454, 'frFR', '', 'Même qu\’il a parlé de le couvrir d\’algues ou un truc comme cha.', 28153),
(141453, 'frFR', '', '<Burp> Ah, oui. Hips ! Me chouviens de che grand dadais avec chon hichtoire de tréjor.', 28153),
(141452, 'frFR', 'Pourquoi qu\’on doit monter la garde ici ? Sérieux, ça craint.', 'Pourquoi qu\’on doit monter la garde ici ? Sérieux, ça craint.', 28153),
(141451, 'frFR', '', 'Wouhouuuu ! <Hips !>$B$BHein ? Qu\’est-che qui che pache ?', 28153),
(141450, 'frFR', '<Soupir> Nub Nub pas plus avancé en tout cas.', '', 28153),
(141449, 'frFR', 'Tout ce que lui dire, c\’est qu\’il est enfoui dans un « coin sablonneux ». Avec ça, on est bien avancés !', '', 28153),
(141448, 'frFR', 'Nub Nub a entendu parler trésor. Toute la taverne a entendu !', '', 28153),
(141447, 'frFR', 'Y a quelque chose à récurer ?', '', 28153),
(141446, 'frFR', 'TRÉ-SOR EN-FOUI.', 'TRÉ-SOR EN-FOUI.', 28153),
(141445, 'frFR', 'QUOI ? UN TÉNOR DE BOUIBOUI ?!', '', 28153),
(141444, 'frFR', 'Non. Trésor enfoui, j\’ai dit.', 'Non. Trésor enfoui, j\’ai dit.', 28153),
(141443, 'frFR', 'DES PORCS EN MÉCHOUI ?', '', 28153),
(141442, 'frFR', 'SINON, L\’AUTRE JOUR À LA TAVERNE, UN TYPE S\’EST VANTÉ D\’ÊTRE UN CADOR AU LIT. COMME SI ON AVAIT LA MOINDRE ENVIE DE LE SAVOIR.', '', 28153),
(141441, 'frFR', 'NAN, JAMAIS ENTENDU PARLER D\’UN TRÉSOR.', '', 28153),
(141440, 'frFR', 'AH, JE VOIS. LE TRÉSOR ENFOUI.', '', 28153),
(141439, 'frFR', '<Indiquer l\’affiche.> Que savez-vous à propos de ce trésor enfoui ?', '<Indiquer l\’affiche.> Que savez-vous à propos de ce trésor enfoui ?', 28153),
(141438, 'frFR', 'COMMENT ? PARLEZ PLUS FORT. J\’ENTENDS PLUS TRÈS BIEN DEPUIS…$B$BDEPUIS L\’ACCIDENT.', '', 28153),
(141435, 'frFR', 'Pete le Sournois !', '', 28153),
(141434, 'frFR', '', 'Quoi qu\’il arrive, souriez ! Les clients sont des fourbes de première, on ne sait jamais quand ils nous observent !', 28153),
(141433, 'frFR', '', 'Rappelez-vous, si on vous pose une question et que vous ne connaissez pas la réponse, inventez-en une ! Les Gnomes sont des petits malins, mettez ça à profit !', 28153),
(141432, 'frFR', '', 'Faites-moi un joli sourire, recrues ! Montrez-leur à quel point on peut être adorables, nous les Gnomes !', 28153),
(141431, 'frFR', 'Comment ? Ce n\’est pas juste ! CE N\’EST PAS JUSTE !', '', 28153),
(141430, 'frFR', '', 'Flynn ! Tiens bon !', 28153),
(141429, 'frFR', 'Dix mille pièces d\’or à qui m\’apportera leur tête !', '', 28153),
(141428, 'frFR', 'C\’en est fini des Portvaillant ! Et quand dame Corsandre montera sur le trône, je commanderai sa flotte !', '', 28153),
(141427, 'frFR', 'Assez ! Vous arrivez trop tard de toute façon ! L\’attaque sur la porte de Daelin a déjà commencé !', '', 28153),
(141426, 'frFR', 'Rah ! Ces dés sont maudits ! Passons à la suite !', '', 28153),
(141425, 'frFR', 'Harlan lance un plein sac de dés, obtenant une majorité de trésors.', 'Harlan lance un plein sac de dés, obtenant une majorité de trésors.', 28153),
(141424, 'frFR', 'Harlan relance les dés et obtient un canon et deux crânes.', 'Harlan relance les dés et obtient un canon et deux crânes.', 28153),
(141423, 'frFR', 'Harlan lance les dés et obtient deux trésors et une boussole.', 'Harlan lance les dés et obtient deux trésors et une boussole.', 28153),
(141422, 'frFR', 'Harlan lance les dés et obtient un brelan d\’épées.', 'Harlan lance les dés et obtient un brelan d\’épées.', 28153),
(141421, 'frFR', 'Voilà qui est mieux ! Qui a dit que je devais respecter les règles ? Hé hé hé !', '', 28153),
(141420, 'frFR', 'Quoi ? Non, non, non. Ça ne va pas du tout.', '', 28153),
(141419, 'frFR', 'Non ! Soit ! On relance !', '', 28153),
(141418, 'frFR', 'Ah, une nouvelle tête ! J\’espère que vous êtes un peu moins insipide que les gens du coin.', '', 28153),
(141417, 'frFR', 'Ooooh ! C\’est pas de chance, hé hé hé ! Taillez-les en pièces !', '', 28153),
(141416, 'frFR', 'Hum, alors… Qu\’allons-nous faire de nos deux mutins… Pourquoi ne pas laisser les dés décider de leur sort ?', '', 28153),
(141415, 'frFR', 'Ho ho ! Notre nouvelle « recrue » est arrivée ! On va bien s\’amuser !', '', 28153),
(141414, 'frFR', '', 'Jamais mon mari ne cessera d\’exploiter ses employés…', 28153),
(141413, 'frFR', 'Les choses ont changé, Flynn. C\’est moi le capitaine, maintenant. Et dès que les Portvaillant seront hors course, nous pourrons piller tout Kul Tiras !', '', 28153),
(141412, 'frFR', 'Rhhh… Fuyez…', '', 28153),
(141411, 'frFR', 'C\’est ça ! Faites-lui passer un mauvais quart d\’heure.', '', 28153),
(141410, 'frFR', '', 'Il est temps pour vous d\’aller au-delà de nos sommets sacrés.', 28153),
(141409, 'frFR', '', 'Il nous est arrivé de nous déchirer, de nous égarer. Mais les esprits de nos ancêtres veillaient à nous rappeler que nous sommes liés par la terre, la rivière et le ciel. Nous sommes une famille. Et elle vaut la peine d\’être défendue.', 28153),
(141408, 'frFR', '', 'Ces mots en disent beaucoup plus long que la terre et la pierre. Ils portent l\’histoire de notre peuple qui, dans l\’adversité et le conflit, s\’est fédéré contre un ennemi commun.', 28153),
(141407, 'frFR', '', 'Haut-Roc ne faillira pas !', 28153),
(141406, 'frFR', '', 'Imbécile ! Vous avez eu tort de vous interposer !', 28153),
(141405, 'frFR', '', 'Silgryn ! Valtrois ! Venez en aide au seigneur régent !', 28153),
(141404, 'frFR', 'Assez ! Nous devons éradiquer la corruption avant que le Puits soit perdu !', '', 28153),
(141403, 'frFR', '', 'Je n\’avais pas l\’intention de…', 28153),
(141402, 'frFR', 'C\’est pour cela que j\’ai exigé l\’exil d\’Umbric et de ses extrémistes. Tous ceux qui font appel aux pouvoirs du Vide constituent un danger pour le Puits de soleil.', '', 28153),
(141401, 'frFR', 'Que se passe-t-il ?', '', 28153),
(141400, 'frFR', 'Reculez !', '', 28153),
(141399, 'frFR', '', 'Le Puits de soleil a changé… mais sa beauté demeure. Cela faisait si longtemps.', 28153),
(141398, 'frFR', '', 'Nos ennemis ont corrompu le Puits de soleil. Mais un Naaru s\’est sacrifié pour purifier ses eaux. Nous sommes désormais nourris par l\’essence de la Lumière.', 28153),
(141397, 'frFR', '', 'Je ressens sa puissance… Elle est comparable à celle du Puits de la nuit, mais sa nature est différente.', 28153),
(141396, 'frFR', 'Suivez-moi, je vous prie.', '', 28153),
(141395, 'frFR', 'Rommath, ouvrez la voie, si vous le voulez bien.', '', 28153),
(141394, 'frFR', '', 'Ce serait pour nous un immense honneur de voir le Puits de soleil, Lor\’themar. Et je préfère que mes amis m\’appellent Thalyssra.', 28153),
(141393, 'frFR', 'Quoi qu\’elle soit devenue, Alleria reste une enfant de Quel\’Thalas. Je ne lui refuserai pas l\’accès à notre site le plus sacré. Première arcaniste, si vous et votre suite souhaitez vous joindre à nous.', '', 28153),
(141392, 'frFR', 'Je le déconseille. Nous ne savons pas ce qu\’elle pourrait…', '', 28153),
(141391, 'frFR', '', 'Cela fait maintenant mille ans que je n\’ai pas posé les yeux sur le Puits de soleil. Puis-je le revoir ?', 28153),
(141389, 'frFR', '', 'Il semblerait que notre offre ait été escomptée… et rejetée. Qu\’il en soit ainsi. J\’ai une demande à formuler avant de partir.', 28153),
(141388, 'frFR', 'Vous mettez ma parole en doute, mais que suis-je censé penser de vous ? N\’entendez-vous pas les murmures des seigneurs du Vide ? N\’avez-vous pas cédé aux ténèbres sur Argus ?', '', 28153),
(141387, 'frFR', '', 'Votre langue est acérée, Lor\’themar. Le respectueux forestier que j\’ai connu serait-il devenu le porte-parole de son chef de guerre ?', 28153),
(141384, 'frFR', 'J\’espérais que votre présence ait été motivée par votre amour de Lune-d\’Argent. Au lieu de cela, vous venez sur ordre de l\’enfant-roi qui dirige l\’Alliance. Quelle déception.', '', 28153),
(141383, 'frFR', '', 'Si vous insistez. Je viens vous faire part d\’une offre du haut roi Anduin Wr…', 28153),
(141382, 'frFR', 'Ne dites pas de bêtises ! Quelle que soit la raison de votre venue, nos invités peuvent aussi l\’entendre.', '', 28153),
(141381, 'frFR', '', 'Tout l\’honneur est pour moi, Première arcaniste. Mais je ne souhaite pas imposer ma présence. Il serait plus sage que je revienne une autre fois.', 28153),
(141380, 'frFR', '', 'Un honneur inespéré, dame Coursevent. Silgryn a vanté votre courage lors de la campagne sur Argus.', 28153),
(141379, 'frFR', 'Je vous en prie, appelez-moi Lor\’themar. Mais où sont mes manières ? Laissez-moi vous présenter Alleria Coursevent, une ancienne héroïne de Lune-d\’Argent.', '', 28153),
(141376, 'frFR', '', 'C\’est un plaisir d\’admirer enfin votre somptueuse cité. Merci pour cette invitation, seigneur régent.', 28153),
(141375, 'frFR', '', 'Première arcaniste Thalyssra, honorables invités, bienvenue à Lune-d\’Argent.', 28153),
(141374, 'frFR', 'Je ne vois aucune raison d\’écarter nos alliés de la discussion, Alleria. D\’ailleurs, de nouveaux amis viennent tout juste d\’arriver.', '', 28153),
(141373, 'frFR', '', 'Liadrin, héraut, je suis ravie de vous revoir. Lor\’themar, j\’aimerais m\’entretenir avec vous en privé.', 28153),
(141372, 'frFR', 'Dame Liadrin, héraut, soyez les bienvenus. Comme vous pouvez le constater, nous avons reçu une visite… inattendue.', '', 28153),
(141371, 'frFR', '', 'À vos ordres, chef de guerre. $p, je vous retrouverai au domaine de dame Thalyssra à Suramar.', 28153),
(141370, 'frFR', '', 'Je compte sur vous. Ne revenez pas tant que Suramar n\’aura pas rejoint les rangs de la Horde.', 28153),
(141369, 'frFR', '', 'Le seigneur régent Theron a convié les Sacrenuit à Lune-d\’Argent. Je vais me rendre à Suramar, puis conduire dame Thalyssra à ce rassemblement.', 28153),
(141366, 'frFR', '', 'Pour assurer l\’avenir de notre peuple, nous devons regagner notre place sur Azeroth.', 28153),
(141365, 'frFR', '', 'Nos meneurs nous ont trahis, ont passé un pacte avec les démons. Mais nous nous sommes insurgés contre la tyrannie… et avons chassé le mal. Suramar nous appartient à nouveau et nous ne la laisserons plus jamais succomber aux ténèbres.', 28153),
(141364, 'frFR', '', 'Autour de nous, le monde a connu d\’innombrables changements… puis il est tombé aux griffes de la Légion.', 28153),
(141363, 'frFR', '', 'Pendant dix mille ans, Suramar a été le seul monde que nous avons connu.', 28153),
(141362, 'frFR', '', 'Vous faites partie des Sancteforge. Vous symbolisez l\’espoir face aux ténèbres.', 28153),
(141361, 'frFR', '', 'Notre ennemi a enfin été vaincu. La Légion n\’est plus. Mais la guerre est loin d\’être finie. De nouvelles menaces rôdent dans les ténèbres et attendent l\’heure de frapper.', 28153),
(141360, 'frFR', '', 'À travers les millénaires, la Lumière nous a montré la voie.', 28153),
(141359, 'frFR', '', 'Nous sommes des soldats.', 28153),
(141358, 'frFR', '', 'Le Vide nous a façonnés… il nous a à jamais changés. Vous garderez toutefois l\’ascendant.', 28153),
(141357, 'frFR', '', 'Mais nous détenons une vérité qu\’ils ne peuvent concevoir.', 28153),
(141356, 'frFR', '', 'Les sages et les érudits redoutent le Vide.', 28153),
(141355, 'frFR', '', 'Le Vide. Une force dont la faim est insatiable.', 28153),
(141354, 'frFR', '', 'Je vais au bateau. Retrouvez-moi là-bas.', 28153),
(141353, 'frFR', 'La bénédiction de Bwonsamdi vous accompagne.', '', 28153),
(141352, 'frFR', '', 'Les Gobelins, ils m\’ont juré que ce plan fonctionnerait… C\’est pour ça que j\’ai besoin que vous alliez vérifier.$B$BÇa vous dirait de descendre la rivière ?', 28153),
(141351, 'frFR', 'Il garde la pêche en toutes circonstances… Il est le prédateur de Port-Liberté… le champion des compétiteurs… Trothak le cogneur aux requins !', '', 28153),
(141350, 'frFR', 'Incroyable ! Ces marins d\’eau douce ont réussi à vaincre Gryff et Stevin ! Il ne leur reste plus qu\’un adversaire à affronter, qu\’on ne présente plus.', '', 28153),
(141349, 'frFR', 'Les fantastiques frères funestes… La formidable fusion de la finesse et de la force… J\’ai nommé les fabuleux, les effroyables Stevin et Gryff !', '', 28153),
(141348, 'frFR', 'Laissez-moi maintenant vous présenter un duo qui a traversé les mers rien que pour vous. De vraies bêtes de combat, qui instillent la peur dans le cœur des guerriers même les plus courageux.', '', 28153),
(141347, 'frFR', 'Vous allez connaître votre douleur !', '', 28153),
(141345, 'frFR', 'Il n\’y a aucune échappatoire !', '', 28153),
(141344, 'frFR', 'Ludwig est au tapis ! Quel combat ! Ces boucaniers ont du ressort, et ça vaut mieux pour eux… car leur prochain adversaire est la quintessence de la violence.', '', 28153),
(141343, 'frFR', 'Sauvez... vous...', '', 28153),
(141342, 'frFR', '', 'Sale gosse ! Bwonsamdi, il m\’a promis la vie éternelle en échange de ton âme ! Tu vas tout gâcher, tout !', 28153),
(141341, 'frFR', 'Il débarque directement des égouts de Port-Liberté… Celui qu\’on surnomme le « puissant protecteur », le « sergent sauvage » ou encore la « carapace coriace » va vous tor… tuer ! Voici Ludwig !', '', 28153),
(141340, 'frFR', 'Eh bien, incroyable. Ils ont attrapé un cochon. On pourrait peut-être passer à un défi un peu plus… difficile !', '', 28153),
(141334, 'frFR', '', 'Z\’avez jamais entendu parler du clan Crocs-d\’ombre ? Pas étonnant, ils se sont tous fait zigouiller par le Marteau du crépuscule.\n\nReste plus que moi. Les Zandalari, ils me laissent ambassadrice en souvenir du bon vieux temps. Je suis rien qu\’une bête curieuse et pis c\’est tout.\n\nC\’est pas si terrible, r\’marquez. J\’arrête pas de me faire payer des verres.', 28153),
(141332, 'frFR', 'Paraît que le roi Rastakhan, il est pas dans son assiette ces temps-ci. Zandalar finira par tomber, ça fait pas un pli. Et alors, on fera quoi, nous, hein ?', 'Paraît que le roi Rastakhan, il est pas dans son assiette ces temps-ci. Zandalar finira par tomber, ça fait pas un pli. Et alors, on fera quoi, nous, hein ?', 28153),
(141331, 'frFR', 'Les Zandalari, ils régnaient sur tous les Trolls, avant. Aujourd\’hui, ils arrivent même plus à protéger leurs frontières.', 'Les Zandalari, ils régnaient sur tous les Trolls, avant. Aujourd\’hui, ils arrivent même plus à protéger leurs frontières.', 28153),
(141330, 'frFR', 'Les Zandalari, ils laissent la magie du sang s\’infiltrer chez eux. C\’est qu\’une question de temps avant qu\’elle soit leur ruine.', 'Les Zandalari, ils laissent la magie du sang s\’infiltrer chez eux. C\’est qu\’une question de temps avant qu\’elle soit leur ruine.', 28153),
(141329, 'frFR', 'Les Zandalari, les moutons noirs, ils les envoient dans le désert. Et personne en revient jamais.', 'Les Zandalari, les moutons noirs, ils les envoient dans le désert. Et personne en revient jamais.', 28153),
