(141192, 'frFR', 'Se téléporter au donjon d\’Atal\’Dazar', 'Se téléporter à Atal\’Dazar', 28153),
(141191, 'frFR', 'Se téléporter au donjon de Port-Liberté', 'Se téléporter à Port-Liberté', 28153),
(141190, 'frFR', 'Bienvenue à la BlizzCon 2017 ! Pour vous téléporter au donjon de votre faction, cliquez ci-dessous !', 'Bienvenue à la BlizzCon 2017 ! Pour vous téléporter au donjon de votre faction, cliquez ci-dessous !', 28153),
(141189, 'frFR', '', 'Hors de ma vue ! Revenez pas avant de pouvoir prouver votre valeur !', 28153),
(141188, 'frFR', 'Je suis désolé ! J\’ai essayé de l\’aider, et je sais pas me battre !', '', 28153),
(141187, 'frFR', '', 'Pas de retour en arrière ! Pas d\’espoir pour Zuldazar. Pas d\’espoir pour vous. G\’huun s\’éveille ! G\’huun se lève !', 28153),
(141186, 'frFR', '', 'Vous avez osé tuer NOTRE Loa… On va vous traquer… vous torturer… vous saigner à blanc !', 28153),
(141185, 'frFR', '', 'Hir\’eek servait G\’huun ! Cet affront, vous allez le payer. Après Zuldazar… c\’est la Horde qui tombera !', 28153),
(141184, 'frFR', '<Rakjan baisse la tête en signe de respect.>', '', 28153),
(141183, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(141182, 'frFR', '<Rakjan baisse la tête en signe de respect.>', '', 28153),
(141180, 'frFR', 'Adieu, imbécile !', '', 28153),
(141178, 'frFR', 'Il va falloir que je me fasse oublier pendant quelque temps…', '', 28153),
(141177, 'frFR', 'Dommage que le compère tortue ne soit pas venu lui-même. Sa carapace m\’aurait rapporté gros.', '', 28153),
(141176, 'frFR', 'On nous ment, on nous spolie ! Ne soyons plus des vaches à lait !', '', 28153),
(141175, 'frFR', 'Le Vindicaar est un vaisseau extrêmement rapide. Je me permettrais presque de dire qu\’il voyage à la vitesse de la Lumière…', '', 28153),
(141174, 'frFR', '', 'Les Taurens de notre région aiment les aventures rocambolesques.', 28153),
(141173, 'frFR', '', 'Avez-vous déjà eu le plaisir d\’assister à la nouvelle chorégraphie du prophète Velen ? Il l\’a baptisée « la Mac\’Areena ».', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141172, 'frFR', '', 'Humpf. Faut <hips !> croire que cette vermine a filé la queue entre les jambes.', 28153),
(141171, 'frFR', '', 'Il est où, le foie bilieux de flibustier de carnaval qu\’ose insulter <hips> les Lamineurs ?!', 28153),
(141170, 'frFR', '', 'Quoi ?! <Hips !> J\’vais lui apprendre à débiner MON équipage !', 28153),
(141169, 'frFR', 'Y a un rat de cale qui se permet de salir le nom des Lamineurs ! Quelqu\’un doit lui faire payer ! Il se planque là-bas, derrière ce bâtiment !', 'Y a un rat de cale qui se permet de salir le nom des Lamineurs ! Quelqu\’un doit lui faire payer ! Il se planque là-bas, derrière ce bâtiment !', 28153),
(141168, 'frFR', 'Quoi ? Cette vieille chouette devrait être morte et privée de son âme ! Tuez-la, que je reprenne ce qui m\’est dû !', '', 28153),
(141167, 'frFR', '', '<Hips>$B$BOuais ? Vous voulez quoi ?', 28153),
(141166, 'frFR', 'Vous avez fait QUOI ?! C\’est interdit de… vous pouvez PAS tuer les Loas !', '', 28153),
(141165, 'frFR', 'Jo\’chunga est en vie. On ne peut pas en dire autant du Loa Hir\’eek…', 'Jo\’chunga est en vie. On ne peut pas en dire autant du Loa Hir\’eek…', 28153),
(141164, 'frFR', 'Vous voilà ! Je commençais à m\’inquiéter ! Il s\’est passé quoi ?', '', 28153),
(141163, 'frFR', 'Je suis un Draeneï pendant mes quêtes… mais un Érédar sous la couette.', '', 28153),
(141162, 'frFR', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t |cFFF00000|Hspell:257585|h[Barrage au canon]|h|r en préparation !', '|TInterface\\ICONS\\ABILITY_VEHICLE_SIEGEENGINECANNON.BLP:20|t |cFFF00000|Hspell:257585|h[Barrage au canon]|h|r en préparation !', 28153),
(141161, 'frFR', '<Souvenir de l\’emprisonnement de Sargeras.>', '<Souvenir de l\’emprisonnement de Sargeras>', 28153),
(141160, 'frFR', '<Souvenir de votre arrivée au Siège du Panthéon>', '<Souvenir de votre arrivée au Siège du Panthéon.>', 28153),
(141159, 'frFR', 'J\’apporte la Lumière… et l\’ardeur.', '', 28153),
(141158, 'frFR', 'Marcheur des esprits ?', '', 28153),
(141157, 'frFR', 'Des tentacules sur le visage ? Nous n\’avons PAS de tentacules ! Si c\’était le cas, cela supposerait que les Draeneï sont des émissaires du Vide qui tentent de gagner votre confiance pour infiltrer votre société dans l\’ultime but de la détruire. Est-ce LÀ ce que vous insinuez ?', '', 28153),
(141156, 'frFR', 'Mes tatouages manquent d\’éclat aujourd\’hui. J\’ai oublié de recharger mes batteries la nuit dernière.', '', 28153),
(141155, 'frFR', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan revêt son |cFFFF0000|Hspell:255371|h[Visage terrifiant]|h|r. Cachez-vous !', '|TInterface\\Icons\\ABILITY_DEVOUR.BLP:20|tRezan revêt son |cFFFF0000|Hspell:255371|h[Visage terrifiant]|h|r. Cachez-vous !', 28153),
(141154, 'frFR', '', 'Maître… accorde-moi ton don…', 28153),
(141153, 'frFR', '', 'Je vous préviens, je vous assomme avec un caillou ! J\’en suis cap\’ !', 28153),
(141152, 'frFR', '', 'N\’avancez pas, Troggs de malheur !', 28153),
(141151, 'frFR', '<Voir la bénédiction de la Couronne.>', '<Voir la bénédiction de la Couronne.>', 28153),
(141150, 'frFR', '<Voir la vision des Coursevent.>', '<Voir la vision des Coursevent.>', 28153),
(141149, 'frFR', '', 'Empêchez les petits d\’approcher de Rakjan !', 28153),
(141148, 'frFR', '<Voir le jugement de la Lumière.>', '<Voir le jugement de la Lumière.>', 28153),
(141147, 'frFR', '', 'Excusez-moi ! Pourriez-vous m\’aider, s\’il vous plaît ?', 28153),
(141146, 'frFR', '<Voir la décision du triumvirat.>', '<Voir la décision du triumvirat.>', 28153),
(141145, 'frFR', '<Voir l\’échappée d\’Argus.>', '<Voir l\’échappée d\’Argus.>', 28153),
(141144, 'frFR', '', 'Ne laissez pas les petits s\’échapper !', 28153),
(141143, 'frFR', 'Hé ! Vous, là ! Par ici !', '', 28153),
(141142, 'frFR', 'Un pterreurdactyle blessé s\’arrête pour récupérer de ses blessures.', '', 28153),
(141141, 'frFR', '<Voir l\’arrivée d\’Aggramar.>', '<Voir l\’arrivée d\’Aggramar.>', 28153),
(141140, 'frFR', '', 'Regardez ! Ça y est ! Oooh, si belle et si meurtrière à la fois !', 28153),
(141139, 'frFR', '', 'Tant de… POUVOIR ! HA HA HA !', 28153),
(141138, 'frFR', 'Intéressant… Alors comme ça, ils utilisent ces flèches pour se déplacer. Eh bien, on en aura appris, des choses, aujourd\’hui.', '', 28153),
(141137, 'frFR', 'Euh, patron ? $n ? Je crois qu\’on n\’en a pas encore fini avec les serpents.', '', 28153),
(141136, 'frFR', '<Rakjan lève la tête fièrement.>', '', 28153),
(141135, 'frFR', '', 'Éteignez la Lumière et je vous montrerai mon côté sombre.', 28153),
(141134, 'frFR', '', 'Mes yeux, mes tatouages et mon armure illumineront vos nuits. Un véritable spectacle !', 28153),
(141133, 'frFR', '', 'La faculté d\’atteindre le septième ciel n\’est pas l\’apanage des membres de la tribu Corne-Céleste.', 28153),
(141132, 'frFR', '', 'Les peuples vivant à haute altitude aiment les sensations fortes. Permettez-moi d\’étayer mes propos…', 28153),
(141131, 'frFR', '', 'Je connais Ethel. Elle peut marcher très vite quand elle le veut. Je crois simplement qu\’elle aime charrier les touristes.', 28153),
(141130, 'frFR', 'Les ossements sans repos reprennent vie sous forme de raptor réanimé !', 'Les ossements sans repos reprennent vie sous forme de raptor réanimé !', 28153),
(141129, 'frFR', 'Un tas de vieux os se met à remuer à proximité.', 'Un tas de vieux os se met à remuer à proximité.', 28153),
(141128, 'frFR', 'Dalaran, au-dessus des îles Brisées.', 'Dalaran, au-dessus des îles Brisées.', 28153),
(141127, 'frFR', 'La princesse, c\’est l\’avenir de Zandalar. Faut la protéger.', 'La princesse, c\’est l\’avenir de Zandalar. Faut la protéger.', 28153),
(141126, 'frFR', 'Quand le grand exarque m\’a donné l\’ordre de gagner Azeroth, j\’étais réticent à l\’idée de le quitter et persuadé que cette tâche conviendrait mieux à un autre.\n\nAujourd\’hui, je comprends son choix. Il souhaitait que je découvre ce pour quoi dame Alleria et lui se battent.\n\nCertes, la guerre est finie, mais d\’autres combats nous attendent. La défaite de la Légion ne signifie en aucun cas que tous les démons se sont rendus.\n\n<Lothraxion serre le poing et sourit.>\n\nPas encore, en tout cas.', '', 28153),
(141125, 'frFR', 'On est aux ordres de la princesse.', 'On est aux ordres de la princesse.', 28153),
(141124, 'frFR', 'Qu\’est-ce que vous m\’voulez ?', 'Qu\’est-ce que vous me voulez ?', 28153),
(141123, 'frFR', 'Les arbres prennent vie ! Sortez vos haches !', '', 28153),
(141122, 'frFR', 'T\’laartos !', '', 28153),
(141121, 'frFR', '', 'L\’épreuve va commencer. Que la Lumière soit avec vous.', 28153),
(141120, 'frFR', '', 'Un choix peu orthodoxe, mais… techniquement dans les règles. Notre camarade n\’a jamais reculé face au défi.', 28153),
(141119, 'frFR', 'Très bien ! T\’laartos choisit… ce petit être chétif, là !', '', 28153),
(141118, 'frFR', '', 'Le dernier initié qui a tenté de relever le défi seul n\’est pas revenu en entier. Désignez quelqu\’un ou retournez dans vos quartiers !', 28153),
(141117, 'frFR', 'T\’laartos n\’a besoin de l\’aide de personne !', '', 28153),
(141116, 'frFR', '', 'T\’laartos… nous en avons déjà discuté. Chaque initié doit être accompagné. Où est ton partenaire ?', 28153),
(141115, 'frFR', '', 'Toutefois, si vous vous sentez prêts, avancez et embrassez votre destin.', 28153),
(141114, 'frFR', '', 'Si vous avez le moindre doute, faites demi-tour. Votre décision sera considérée comme un acte de sagesse, et non de lâcheté.', 28153),
(141113, 'frFR', '', 'Bien des Draeneï se sont soumis à cette épreuve par le passé et en sont revenus brisés… ou pire.', 28153),
(141112, 'frFR', '', 'Il vous confrontera à l\’essence même de votre existence. À ce que vous pensez être au fond de votre âme.', 28153),
(141111, 'frFR', '', 'Un dernier défi, le plus difficile, vous attend maintenant.', 28153),
(141110, 'frFR', '', 'Camarades, les épreuves que vous avez endurées prouvent que la Lumière resplendit dans vos cœurs.', 28153),
(141109, 'frFR', '<Il semble avoir été vidé par les Troggs.>', '', 28153),
(141108, 'frFR', '<Continuer à chercher les enfants.>', '<Continuer à chercher les enfants.>', 28153),
(141107, 'frFR', 'À mon humble avis, $n a plus d\’expérience que vous dans ce domaine, Ingrid.', '', 28153),
(141106, 'frFR', '', 'C\’est injuste, c\’était à moi de le faire !', 28153),
(141105, 'frFR', 'Le Vindicaar n\’avait pas encore fait ses preuves quand notre campagne a commencé, et pourtant il nous a ramenés chez nous sains et saufs.\n\nToutes les améliorations apportées à ce vaisseau en valaient-elles la peine ?\n\nNon, ne répondez pas. Cela ne ferait que me briser le cœur.\n\nLe travail d\’un ingénieur est trop souvent sous-estimé.', '', 28153),
(141104, 'frFR', 'Je les ai retrouvés ! Je les ai enfin retrouvés.\n\n<Le sourire d\’Arator fait rapidement place au doute.>\n\nLes deux êtres qui m\’ont donné la vie… n\’en ont jusqu\’alors jamais fait partie. Je sais qu\’ils ont combattu pour assurer ma protection, qu\’ils ont tout sacrifié. Et pourtant…\n\nNous ne pouvons pas devenir une famille unie du jour au lendemain. Ils ignorent presque tout de moi, et je n\’ai ouï que les légendes à leur sujet. Nous avons tant de choses à découvrir et tant de blessures à panser.\n\nMais désormais, nous le ferons ensemble.', '', 28153),
(141103, 'frFR', '', 'Alleria a changé. Elle détient un pouvoir qu\’il m\’est difficile d\’appréhender. Mais au plus profond de nos cœurs, je sais que nous sommes toujours sœurs.\n\nLa nouvelle du sort de Sylvanas l\’a profondément marquée. Certaines questions doivent être réglées… de vive voix.\n\nNous devons nous réunir. Et il n\’existe qu\’un lieu pour cela.', 28153),
(141102, 'frFR', '', 'Vous êtes encore là ?\n\n<Ishanah vous regarde, l\’air interrogateur.>\n\nC\’est fini. Rentrez chez vous.\n\n<Ishanah vous chasse.>\n\nAllez !', 28153),
(141101, 'frFR', 'Notre campagne contre la Légion fut longue et éreintante. Nous avons parcouru des mondes entiers, et même traversé le Néant distordu pour remporter la victoire.\n\nJe suis rompu, $n. Mais L\’heure n\’est pas au repos.\n\nLes sinistres visions de Magni m\’ont ébranlé. Il ne reste plus qu\’un Titan et nous devons le défendre.', '', 28153),
(141100, 'frFR', '', 'Regardez ! Ça y est ! Oooh, si belle et si meurtrière à la fois !', 28153),
(141099, 'frFR', 'J\’ai passé tant de nuits à rêver de mon monde. De son sort. De son salut.\n\n<Velen marque une longue pause.>\n\nArgus ne pouvait plus être sauvé, mais nous avons gagné la bataille.\n\nJ\’ignore ce que l\’avenir nous réserve, mais je n\’attendrai pas que mes visions me guident. Je ferai tout mon possible pour soutenir le roi Anduin et m\’assurer qu\’il soit prêt à affronter les menaces tapies dans l\’ombre.', '', 28153),
(141098, 'frFR', '', 'Mon cœur s\’envole à l\’idée de retourner sur Azeroth aux côtés d\’Arator et de Turalyon, de retrouver les forêts de mes terres natales.\n\nToutefois…\n\nVereesa m\’a révélé ce qui est arrivé à Sylvanas. Bien que j\’appréhende nos retrouvailles, je dois constater ce qu\’elle est devenue de mes propres yeux.\n\nEst-elle toujours ma sœur ou seulement un monstre qui s\’est détourné de la Lumière ?\n\nBien entendu, j\’ai moi aussi changé. Et quiconque serait en droit de remettre ma loyauté en question.\n\n<Alleria prend une profonde inspiration.>\n\nJe dois garder mon calme et rester concentrée. Tant de questions m\’assaillent…', 28153),
(141097, 'frFR', 'La guerre est enfin finie.\n\nUne partie de moi était convaincue que je ne vivrais jamais ce jour. Nous avons livré tant de batailles, subi tant de pertes…\n\n<Turalyon soupire, les yeux chargés d\’émotion.>\n\nIl est temps pour moi de retrouver le monde que j\’ai quitté il y a un millier d\’années.\n\nMa vie passée est depuis longtemps révolue. Je dois désormais me tourner vers l\’avenir et apprendre à connaître le fils qui incarne tout ce pour quoi je me suis battu.', '', 28153),
(141096, 'frFR', 'Excellent travail, Ingrid. Excellent, quoiqu\’un peu excessif.', '', 28153),
(141095, 'frFR', 'J\’y travaille.', '', 28153),
(141094, 'frFR', '', 'Euh… patron ? Je crois bien qu\’on va avoir besoin d\’un bouclier pour nous protéger de la foudre, là !', 28153),
(141093, 'frFR', '', 'Oooh, ça fait si longtemps que j\’attends ce moment. Laissez-moi faire !', 28153),
(141092, 'frFR', 'Si un seul de vos indigènes me traite encore de « chandelier mouvant », je vous jure que…', '', 28153),
(141091, 'frFR', '', 'Les Drogbars ne sont pas trop mon type habituellement, mais j\’avoue que lorsqu\’ils font travailler leurs biceps… La température monte d\’un cran, cela même si on se trouve sur des sommets enneigés.', 28153),
(141090, 'frFR', 'Ingrid, je vais utiliser ma propre magie pour activer la gemme de mandeciel. Reculez.', 'Ingrid, je vais utiliser ma propre magie pour activer la gemme de mandeciel. Reculez.', 28153),
(141089, 'frFR', 'Il faut que vous activiez la gemme de mandeciel.', 'Il faut que vous activiez la gemme de mandeciel.', 28153),
(141088, 'frFR', 'J\’y crois pas… $n ! Par ici !', '', 28153),
(141087, 'frFR', '', 'Hé hé… Je savais bien que les secours finiraient par rappliquer ! En tout cas, je l\’espérais de tout cœur. Par ici !', 28153),
(141086, 'frFR', '', 'Vous ! $n ! J\’ai si souvent entendu parler de vous ! Faites-moi sortir d\’ici !', 28153),
(141085, 'frFR', 'L\’illustre $n, ici ? Pour me porter secours, à moi ? Je n\’en crois pas mes yeux.', '', 28153),
(141084, 'frFR', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|tVous êtes |cFFF00000|Hspell:257459|h[Au crochet]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|tVous êtes |cFFF00000|Hspell:257459|h[Au crochet]|h|r!', 28153),
(141083, 'frFR', 'Leur victoire est plus proche que vous ne l\’imaginez.', '', 28153),
(141082, 'frFR', 'Les échos de ses murmures sont plus forts que tous les autres.', '', 28153),
(141081, 'frFR', 'Les enflammés maintenaient l\’équilibre. Tout est perdu…', '', 28153),
(141080, 'frFR', 'Votre orgueil est responsable de tout ceci.', '', 28153),
(141079, 'frFR', 'La nuit tombe. Son chant prendra bientôt fin.', '', 28153),
(141078, 'frFR', 'Acceptez votre destin. Tous finiront engloutis.', '', 28153),
(141077, 'frFR', 'Les fissures s\’élargissent.', '', 28153),
(141075, 'frFR', '$n ranime un tas d\’os !', '$n ranime un tas d\’os !', 28153),
(141074, 'frFR', 'Salut ! Si vous avez perdu vos compagnons, je peux vous aider à les retrouver.', '', 28153),
(141073, 'frFR', 'Toute ma vie, j\’ai pris soin des animaux. Je peux encore vous être utile, si vous voulez.', '', 28153),
(141072, 'frFR', 'On est venus aussi vite qu\’on a pu.', '', 28153),
(141071, 'frFR', '', 'Préparez la peste ! Qu\’elle se répande dans les rangs ennemis !', 28153),
(141070, 'frFR', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|tVous subissez l\’effet de |cFFFF0000|Hspell:251570|h[Bombe d\’âme]|h|r !', '|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW:20|tVous subissez l\’effet de |cFFFF0000|Hspell:251570|h[Bombe d\’âme]|h|r !', 28153),
(141069, 'frFR', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|tVous subissez l\’effet d\’|cFFFF0000|Hspell:250669|h[Explosion d\’âme]|h|r !', '|TInterface\\Icons\\INV_ELEMENTAL_MOTE_SHADOW01:20|tVous subissez l\’effet d\’|cFFFF0000|Hspell:250669|h[Explosion d\’âme]|h|r !', 28153),
(141068, 'frFR', '', 'Mais vous êtes toujours maître de votre destin, Umbric. Je peux vous apprendre à faire taire les murmures. À plier les ténèbres à votre volonté, et non l\’inverse.', 28153),
(141067, 'frFR', '', 'Durzaan a tenté de vous arracher à votre mortalité. De vous rendre comme lui… esclave de sa faim.', 28153),
(141066, 'frFR', 'Alleria… $p… Nous sommes libres, mais nous ne sommes plus les mêmes. Et les voix…', '', 28153),
(141065, 'frFR', '', 'Non. Vous n\’avez aucun droit sur ces personnes. Elles ne sont pas perdues.', 28153),
(141064, 'frFR', 'Nooooooon…', '', 28153),
(141063, 'frFR', '', 'Je vois clair à travers vos mensonges, Durzaan. Il en ira de même pour les autres.', 28153),
(141062, 'frFR', 'Pourquoi résister ? Vous êtes promise à un si grand destin.', '', 28153),
(141061, 'frFR', '', 'Cette tempête du Vide est un conduit… un portail qui doit être fermé.', 28153),
(141060, 'frFR', '', 'Vos maîtres ne m\’asserviront jamais, Éthérien… Ni mes frères et mes sœurs !', 28153),
(141059, 'frFR', 'Nous sommes du même côté, Coursevent… qu\’importe ce que ce traître vous a enseigné.', '', 28153),
(141058, 'frFR', '', 'Allons, allons ! On ne touche pas les bois lors d\’un premier rendez-vous.', 28153),
(141057, 'frFR', 'Cela n\’a guère d\’importance. Votre devenir, en revanche, est un sujet bien plus intéressant.', '', 28153),
(141056, 'frFR', '', 'Venez, $p. Nous devons arrêter la transformation, sans quoi nous les perdrons tous !', 28153),
(141055, 'frFR', 'Rrrrurgaaghh ! La puissance… m\’appelle… elle me change…', '', 28153),
(141054, 'frFR', '', 'Résistez aux murmures, Umbric ! Le « cadeau » qu\’il vous promet ne fera que vous asservir.', 28153),
(141053, 'frFR', '', 'Montrez-vous ! Qui êtes-vous ?', 28153),
(141052, 'frFR', 'Enfin… L\’avenir que j\’avais auguré s\’est concrétisé… Merci d\’avoir ouvert la voie.', '', 28153),
(141051, 'frFR', '', 'Et c\’est à cet instant qu\’il a osé me dire que ma peau était laiteuse… Quelle peau de vache !', 28153),
(141050, 'frFR', 'Pourquoi se satisfaire de cornes quand il est possible de jouir d\’une telle ramure ?', '', 28153),
(141049, 'frFR', 'Ha ha ! Admirez mon pouvoir, $Umortel:mortelle; ! Vous pourriez en profiter, vous aussi…', '', 28153),
(141048, 'frFR', 'La contrée qui s\’étend devant nous est dangereuse, faites demi-tour !', 'La contrée qui s\’étend devant nous est dangereuse, faites demi-tour !', 28153),
(141047, 'frFR', '', 'Z\’avez laissé Zul réduire nos hommes en charpie. Et maintenant, ses troupes, elles marchent droit sur Atal\’Dazar et y a personne pour les arrêter. Z\’avez un plan pour y remédier, ô roi ?', 28153),
(141046, 'frFR', '', 'Rastakhan, on peut dire que z\’avez pris votre temps avant d\’intervenir.', 28153),
(141045, 'frFR', 'Je sais pas si Zul est un bon stratège ou juste un bon prophète. En tout cas, il a toujours une longueur d\’avance.$b$bIl veut me remplacer par les os de notre premier roi, Dazar.$b$bJe serais ravi de voir les Trolls régner à nouveau sur le monde, mais pas grâce à des hérésies obscures.', '', 28153),
(141044, 'frFR', '', 'Même ce bon vieux Bwonsamdi, il sera horrifié par le sort que je vous réserve.', 28153),
(141043, 'frFR', '', 'Votre âme, elle va subir les pires outrages.', 28153),
(141042, 'frFR', '', 'Vous allez continuer à souffrir même dans la mort.', 28153),
(141041, 'frFR', '', 'D\’abord je vais vous tuer, et ensuite, je m\’occuperai de votre cadavre.', 28153),
(141040, 'frFR', '', 'Une intrusion dans mon temple ? Votre arrêt de mort, vous venez de le signer.', 28153),
(141039, 'frFR', '', 'Rastakhan est ici ? Il était temps. Conduisez-moi jusqu\’à lui.', 28153),
(141038, 'frFR', 'Je voulais seulement aider.', '', 28153),
(141037, 'frFR', 'Le monde s\’embrasera de la beauté qui lui est promise.', '', 28153),
(141036, 'frFR', 'Mais regardez-vous ! Au faîte de votre gloire… Hah !', '', 28153),
(141035, 'frFR', '', 'Pour combler une femme, il suffit de lustrer ses sabots. Croyez-moi.', 28153),
(141034, 'frFR', '', 'Nous, Taurens, sommes d\’excellents poètes. Nous avons l\’art de composer des vers émeuuuvants.', 28153),
(141033, 'frFR', '', 'Brrr, il fait froid ici. Ça vous dirait, une crème glacée ?', 28153),
(141032, 'frFR', '', 'Pourquoi les Crins-de-Rive sont-ils si calmes ? Parce que la vie est un long fleuve tranquille.', 28153),
(141031, 'frFR', '', 'Mieux vaut éviter d\’énerver les Totems-de-Sang. Ils peuvent se montrer soupe au lait.', 28153),
(141030, 'frFR', 'Comment appelle-t-on un Tauren qui fait des yeux de merlan frit ? Un encornet !', '', 28153),
(141029, 'frFR', 'Qu\’est-ce qui sent plus mauvais qu\’un Drogbar ? Deux Drogbars ! Et plus mauvais que trois Drogbars ? Personne le sait, une telle puanteur est fatale…', '', 28153),
(141028, 'frFR', 'Un Tauren, un Yaungol et un Taunka entrent dans un bar. Ce n\’est pas une blague, mais un aperçu de mes réunions de famille.', '', 28153),
(141027, 'frFR', 'Ha ! Un de mes amis a réussi à convaincre un aventurier armé jusqu\’aux dents de taper dans des poissons pour les renvoyer dans la rivière ! Euh, attendez, ce n\’était pas vous, j\’espère…', '', 28153),
(141026, 'frFR', 'Je suis peut-être un simple Tauren des montagnes, mais je n\’irai jamais patauger dans la fiente d\’un ver géant pour ramasser du butin.', '', 28153),
(141025, 'frFR', 'Jouons à un jeu. Il suffit de boire un verre chaque fois qu\’une Harpie vous perfore les tympans.', '', 28153),
(141024, 'frFR', 'Comment reconnaît-on un Tauren de Haut-Roc à Tanaris ? C\’est le seul qui déneige son pas de porte.', '', 28153),
(141023, 'frFR', '', 'Ce n\’est pas la taille qui compte, mais le mouvement du totem.', 28153),
(141022, 'frFR', '', 'Qu\’est-ce que vous regardez comme ça ?', 28153),
(141020, 'frFR', '', 'Cela vous dirait de me toucher les bois ? Il paraît que cela porte chance.', 28153),
(141018, 'frFR', 'Vous devez maîtriser le tonnerre, car je viens d\’avoir le coup de foudre.', '', 28153),
(141017, 'frFR', 'Allez-y aussi fort que vous le souhaitez. J\’ai la peau dure.', '', 28153),
(141016, 'frFR', 'Méfiez-vous des profondeurs… de mon cœur.', '', 28153),
(141015, 'frFR', 'Mon totem tonne… jusqu\’au bout de la nuit.', '', 28153),
(141014, 'frFR', 'Croyez-moi, j\’ai déjà exploré bien des profondeurs…', '', 28153),
(141013, 'frFR', 'Avez-vous déjà vu les couchettes du Vindicaar ? Je peux arranger une visite privée si vous le souhaitez.', '', 28153),
(141012, 'frFR', '', 'Vous devriez vraiment assister à l\’une des fêtes données à la cour des Étoiles. Je n\’ai jamais vu quelqu\’un avoir autant besoin d\’un masque.', 28153),
(141011, 'frFR', '', 'Les Elfes de la nuit ? Les Elfes de l\’ennui, oui ! Ils vivent dans les arbres, dorment dans des tanières… Certains ont même des bois ! Ils sont incapables de vivre dans une vraie ville.', 28153),
(141010, 'frFR', '', 'Il y a peu, un kaldorei m\’a fait remarquer que ma tenue était à la pointe de la mode… il y a dix mille ans. Ces Elfes de la nuit ont l\’art et la manière de se montrer odieux !', 28153),
(141009, 'frFR', '', 'Tyrande n\’a pas pris une ride, même après toutes ces années. Vous savez si elle voit quelqu\’un ?', 28153),
(141008, 'frFR', '', 'Je vous sers un verre d\’arquevin ? J\’ai foulé les fruits moi-même.', 28153),
(141007, 'frFR', '', 'Qu\’ils sont enivrants, les parfums de rose et de lilas… Quoi ? Un déguisement ? QUI VA LÀ ?', 28153),
(141006, 'frFR', '', 'Une allusion ! Qu\’avez-vous à conter ?', 28153),
(141005, 'frFR', 'Soyons honnêtes, enfermer un dinosaure sanguinaire dans un zoo ne pouvait que mal finir.', '', 28153),
(141004, 'frFR', 'Je ne comprends pas pourquoi ce lieu se nomme « la cour des Étoiles ». Je n\’y ai encore jamais rencontré de célébrités.', '', 28153),
(141003, 'frFR', 'De mon temps, il n\’y avait qu\’un seul type d\’Elfe. UN SEUL.', '', 28153),
(141002, 'frFR', 'Je bois de l\’arquevin et je sais des choses… c\’est mon truc.', '', 28153),
(141001, 'frFR', 'Vous comprenez désormais pourquoi devenir un bon Suramaritain n\’est pas chose facile !', '', 28153),
(141000, 'frFR', 'Pourquoi tenez-vous tant à m\’entendre dire ça ? Aaaah, très bien. Une illusion. Qu\’avez-vous à cacher ?', '', 28153),
(140999, 'frFR', 'Tiens, comme c\’est bizarre… Tout est complètement normal.', '', 28153),
(140998, 'frFR', '', 'Dans ce raid, aucune zone n\’est inaccessible.', 28153),
(140997, 'frFR', '', 'J\’ai vécu dans une bulle avec les mêmes personnes pendant des millénaires. Il est temps d\’étendre mes horizons…', 28153),
(140996, 'frFR', '', 'Je vous montrerai mes lignes telluriques… si vous me montrez les vôtres.', 28153),
(140995, 'frFR', '', 'Animation ! Détonation ! Ne soyons pas farouches. Passons directement à la duplication !', 28153),
(140994, 'frFR', '', 'Nombreux sont ceux qui rêvent de goûter à mon fruit…', 28153),
(140992, 'frFR', '', 'Vous n\’êtes pas victime d\’une illusion. Tout ce que vous voyez est bien réel…', 28153),
(140991, 'frFR', '', 'À moins qu\’une illusion ne se joue de moi, j\’ai le sentiment que ma présence vous réjouit.', 28153),
(140990, 'frFR', 'Si vous n\’étiez pas déjà la prunelle de mes yeux, vous seriez l\’un des fruits de l\’arcan\’dor.', '', 28153),
(140989, 'frFR', 'Les étoiles ont rendu leur jugement… Vous êtes coupable d\’avoir volé mon cœur.', '', 28153),
(140988, 'frFR', 'Il semblerait que la magie opère entre nous.', '', 28153),
(140987, 'frFR', 'L\’amour que je nourris à votre égard jamais ne flétrira.', '', 28153),
(140986, 'frFR', 'Faisons trembler les lignes telluriques ensemble.', '', 28153),
(140985, 'frFR', 'Vous avez trouvé l\’Arcavia qui mène à mon cœur.', '', 28153),
(140984, 'frFR', 'Je vois que la magie ne vous est pas étrangère… Un simple regard et vous avez figé le temps.', '', 28153),
(140983, 'frFR', 'Vous êtes aussi irrésistible qu\’une source de magie.', '', 28153),
(140982, 'frFR', '', 'Turalyon est le seul être humain que j\’ai côtoyé pendant un millier d\’années. Oui, je pensais que tous étaient grisonnants et balafrés comme lui.', 28153),
(140981, 'frFR', '', 'Être une Sancteforge a aussi ses inconvénients : j\’apparais toujours surexposée sur les photos.', 28153),
(140980, 'frFR', '', 'Le Vindicaar ne s\’est pas encore écrasé… Mais l\’expérience laisse à penser que cela ne saurait tarder.', 28153),
(140979, 'frFR', '', 'Je vous déconseille de marcher sabots nus à bord du Vindicaar. L\’entretien laisse vraiment à désirer ; on y retrouve encore des éclats de cristal au sol.', 28153),
(140978, 'frFR', '', 'Les orteils sont surfaits. Les sabots rendent les pédicures tellement plus rapides !', 28153),
(140977, 'frFR', '', 'Vous-ai déjà présenté mon chien ? Il s\’appelle Chionakai Médor.', 28153),
(140976, 'frFR', '', 'Non, je ne porte pas de tatouage lumineux au-dessus de ma queue !', 28153),
(140975, 'frFR', 'Ma vie pour Aïur… euh, pour Argus. Ma vie pour ARGUS !', '', 28153),
(140974, 'frFR', 'Après avoir passé tant de temps à bord d\’un vaisseau, je suis ravi de pouvoir à nouveau fouler le sol. Ces surfaces métalliques étaient une torture pour mes sabots !', '', 28153),
(140973, 'frFR', 'Votre monde est fort étrange. Des ours qui parlent et pratiquent le kung fu ? Sur Argus, on appelle ça un cirque.', '', 28153),
(140972, 'frFR', 'Je pensais que mon tatouage signifiait « défenseur de la Lumière » en naaru, mais j\’ai découvert qu\’il voulait dire « chèvre incandescente ».', '', 28153),
(140971, 'frFR', '', 'En cas d\’hésitation, touchez tout ce qui brille.', 28153),
(140970, 'frFR', 'Il semblerait que vous m\’ayez allumé. Mon armure est bien plus rayonnante.', '', 28153),
(140969, 'frFR', 'Son sang le rend plus fort. Le vôtre en fera de même.', '', 28153),
(140968, 'frFR', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t Votre esprit est sur le point de succomber à |cFFFF0000|Hspell:244172|h[Assaut psychique]|h|r !', '|TINTERFACE\\ICONS\\SPELL_ARCANE_MINDMASTERY.BLP:20|t Votre esprit est sur le point de succomber à |cFFFF0000|Hspell:244172|h[Assaut psychique]|h|r !', 28153),
(140967, 'frFR', 'Il faut y aller, mieux vaut ne pas traîner dans le coin.', 'Il faut y aller, mieux vaut ne pas traîner dans le coin.', 28153),
(140966, 'frFR', '', 'Ces lâches de Zuldazari, je les maudis ! Pourquoi n\’ont-ils pas éliminé cette menace plus tôt ? Mon père, il a été stupide de croire qu\’elle disparaîtrait comme ça.\n\nNous débarrasser d\’Ateena ne suffira pas… C\’est bien pire que tout ce que j\’ai pu imaginer.', 28153),
(140965, 'frFR', 'Ma veille… s\’achève…', '', 28153),
(140964, 'frFR', 'Pardonne-moi, ma reine.', '', 28153),
(140963, 'frFR', 'Ma reine… j\’ai échoué !', '', 28153),
(140962, 'frFR', 'Personne approchera de la reine !', '', 28153),
(140961, 'frFR', 'Personne doit troubler le repos de la reine !', '', 28153),
(140960, 'frFR', 'Gare ! Gare à l\’éternel protecteur de la reine ! Arrière !', '', 28153),
(140959, 'frFR', '', 'Par tous les Loas… Non ! Voilà la vraie puissance des Trolls de sang… Oh, père… pourquoi les avoir ignorés aussi longtemps ?', 28153),
(140958, 'frFR', '', 'Soyez sur vos gardes, $n, nous n\’avons aucune idée de ce qui nous attend.', 28153),
(140957, 'frFR', '<On dit qu\’on ne réveille pas un chien qui dort. Et c\’est un bon conseil.>', '', 28153),
(140954, 'frFR', 'Je profite davantage de l\’expérience quand les lumières sont allumées… Enfin, ce n\’est pas comme si j\’avais le choix.', '', 28153),
(140953, 'frFR', '', 'Venez à bord de mon vaisseau. Nous ferons bon usage de mon espace et de votre temps.', 28153),
(140952, 'frFR', '', 'Vous devez descendre des Naaru… car vous avez un corps céleste.', 28153),
(140950, 'frFR', '', 'Elle ne doit pas être loin. Je n\’abandonnerai pas, pas aussi près de tuer le chef de ces monstres.', 28153),
(140949, 'frFR', '', 'Tu ne m\’échapperas pas, Ateena, je n\’ai pas peur de ton vaudou noir !', 28153),
(140945, 'frFR', 'Le général Erodus quitte sa cellule de commandement !', 'Le général Erodus quitte sa cellule de commandement !', 28153),
(140944, 'frFR', 'L\’ingénieur en chef Ishkar quitte sa cellule de commandement !', 'L\’ingénieur en chef Ishkar quitte sa cellule de commandement !', 28153),
(140942, 'frFR', 'L\’amiral Svirax quitte sa cellule de commandement !', 'L\’amiral Svirax quitte sa cellule de commandement !', 28153),
(140939, 'frFR', '', 'G\’huun, tu vas voir toute sa puissance ! Tu serais folle d\’essayer de nous arrêter. Laisse-moi te montrer…', 28153),
(140938, 'frFR', '', 'Pauvre Talanji ! Nous, on est les enfants d\’un puissant Loa. Tu gagneras jamais comme ça, petite !', 28153),
(140937, 'frFR', '', 'Ne crois pas que tu m\’intimides, Ateena ! Je vais vous abattre, toi et tes maîtres !', 28153),
(140936, 'frFR', '', 'Je vais rester à l\’écart jusqu\’au moment de frapper. Nous tuerons Ateena ensemble !', 28153),
(140930, 'frFR', 'J\’ai réussi à m\’échapper !', 'Je suis piégée ici à jamais !', 28153),
(140929, 'frFR', 'Vous allez souffrir !', 'Zak\’rajan nous a tous trahis !', 28153),
(140928, 'frFR', 'Mort à Zak\’rajan !', 'Personne échappe à Zak\’rajan !', 28153),
(140927, 'frFR', 'Ma\’da ! J\’ai cru voir quelque chose bouger au nord-ouest.', '', 28153),
(140926, 'frFR', 'Salut, ma\’da. Rien à signaler par ici.', '', 28153),
(140925, 'frFR', 'Salut, ma\’da. Les nouvelles, elles sont pas bonnes. On a perdu la trace des intrus qui ont gâché la petite fête de Najima.', '', 28153),
(140924, 'frFR', '', 'Faites payer les Trolls de sang pour ce sacrilège, $n ! Rejoignez-moi quand vous aurez vengé les défunts.', 28153),
(140923, 'frFR', '', 'Je ne laisserai pas ces monstres odieux profaner la dépouille des miens !', 28153),
(140922, 'frFR', 'Ma hache est faite pour abattre les arbres. Ceux-là feront l\’affaire !', '', 28153),
(140921, 'frFR', 'Cette hache est faite pour tailler dans le vif, et c\’est bien ce que je compte faire !', '', 28153),
(140920, 'frFR', 'Araignées... monstres de bois... J\’en fais mon affaire !', '', 28153),
(140919, 'frFR', '', '|TInterface\\Icons\\ABILITY_CREATURE_POISON_02:20|tUn gangreportail vers Rancora se matérialise !', 28153),
(140918, 'frFR', '', '|TInterface\\Icons\\SPELL_HOLY_CONSUMEMAGIC:20|tUn portail de l\’ombre vers Nathreza se matérialise !', 28153),
(140917, 'frFR', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|tUn portail ardent vers Xoroth se matérialise !', 28153),
(140916, 'frFR', 'Je ne serai plus jamais votre prisonnier !', 'Je vais me repaître de cette âme !', 28153),
(140915, 'frFR', '|cffffff00Recherche effectuée|r', '|cffffff00Recherche effectuée|r', 28153),
(140914, 'frFR', '', 'Encore quelques totems... C\’est bon, je suis prête !', 28153),
(140912, 'frFR', 'Les araignées, passe encore, mais des hommes-arbres ? SANS MOI !', '', 28153),
(140911, 'frFR', 'J\’ai l\’habitude de couper du bois, mais normalement, il ne se défend pas !', '', 28153),
(140910, 'frFR', 'Les arbres prennent vie ! Sauve qui peut !', '', 28153),
(140909, 'frFR', '', 'Par ici. Je vais nous dissimuler pendant notre fuite.', 28153),
(140907, 'frFR', '', 'Dépêchez-vous. Cette chose pourrait ressusciter sans crier gare.', 28153),
(140906, 'frFR', '', 'Visez-moi toutes ces reliques ! Il va me falloir un sac plus grand !', 28153),
(140905, 'frFR', 'Beau travail d\’équipe ! Servez-vous, c\’est l\’occasion ou jamais.', '', 28153),
(140904, 'frFR', '', 'Et peut-être une ou deux bricoles en prime, pour ma peine.', 28153),
(140903, 'frFR', '', 'Et pas question d\’oublier l\’œil de golem empli d\’âmes ! Tacha en fait des petites bombes hilarantes.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140902, 'frFR', '', 'Des idoles maudites ! Tacha les adore… Et regardez tous ces composants.', 28153),
(140901, 'frFR', '', 'Bien, voyons dans tout ce fatras magique ce qui vaut la peine de s\’encombrer.', 28153),
(140900, 'frFR', '', 'Belle prise, $p. Je vais garder les plus belles pièces pour le groupe, bien sûr.', 28153),
(140899, 'frFR', '', 'Ce sont essentiellement des armes zandalari ordinaires... Oh, celles-ci ont l\’air d\’être enchantées !', 28153),
(140898, 'frFR', '', 'Beau combat. À présent, voyons ce qu\’ils ont entreposé là-dedans.', 28153),
(140897, 'frFR', 'La prêtresse, protégez-la ! Laissez passer personne !', 'La prêtresse, protégez-la ! Ne laissez passer personne !', 28153),
(140896, 'frFR', 'On va établir une base dans les ruines d\’à côté. Faites attention à vous deux, hein. J\’ai un mauvais pressentiment.', '', 28153),
(140895, 'frFR', 'Loti vous fait livrer des paquets ? Moi, j\’aurais juste jeté un sort aux bêtes et zou, mais les marchands, ils se plaignent tout le temps quand je fais ça.', '', 28153),
(140894, 'frFR', '', 'Quelque chose a effrayé un des brutosaures. Le pauvre a paniqué et semé la pagaille. Franchement, on n\’avait pas besoin de ça. Aidez les marchands à sauver leur cargaison avant qu\’il vous piétine !', 28153),
(140893, 'frFR', '', 'De nos jours, les jeunes ne respectent ni leurs aînés, ni leurs affaires. Cela ne serait pas arrivé de mon temps…', 28153),
(140892, 'frFR', '', 'À l\’aide ! Ces garnements ont pris nos parchemins pour se métamorphoser en bêtes sauvages. Nous avons des sorts de dissipation, mais ils ne fonctionnent que de près. Faites attention !', 28153),
(140891, 'frFR', 'Avant de mourir, sachez que nous réduirons le reste de votre peuple en esclavage !', '', 28153),
(140890, 'frFR', 'Votre pitoyable espèce sera mise au pas.', '', 28153),
(140889, 'frFR', 'Nos lames auront raison de votre engeance.', '', 28153),
(140888, 'frFR', 'La Horde et l\’Alliance seront vaincues !', '', 28153),
(140887, 'frFR', 'Vengeance pour l\’empereur !', '', 28153),
(140886, 'frFR', 'Vengeance pour Lei Shen !', '', 28153),
(140885, 'frFR', 'Zul nous a promis de nous venger de votre peuple.', '', 28153),
(140880, 'frFR', 'La dinomancienne Kish\’o appelle à l\’aide !', 'La dinomancienne Kish\’o appelle à l\’aide !', 28153),
(140869, 'frFR', 'Mettez cette caserne en état.', '', 28153),
(140860, 'frFR', 'Euh, excusez-moi ! Par ici ! Vous voulez bien nous aider ?', '', 28153),
(140859, 'frFR', '', 'Merci pour le coup de main, $p. Revenez nous trouver à l\’intérieur quand vous serez $gprêt:prête; à tuer d\’autres Sephraks.', 28153),
(140858, 'frFR', '', 'Je suis d\’accord. Ce n\’est pas notre combat. Il est temps de partir.', 28153),
(140857, 'frFR', 'La situation se dégrade trop vite. Et nous avons déjà les fournitures dont nous avons besoin pour attaquer les Sephraks.', '', 28153),
(140856, 'frFR', 'Envoyez-moi à la mine des Sèches-Moustaches.', 'Envoyez-moi à la mine des Sèches-Moustaches.', 28153),
(140855, 'frFR', 'Recruter un bombardier gobelin.', 'Recruter un bombardier gobelin.', 28153),
(140854, 'frFR', 'Je pars devant pour tâter le terrain. Éliminez les spectres et je me chargerai des fournitures.', 'Je pars devant pour tâter le terrain. Éliminez les spectres et je me chargerai des fournitures.', 28153),
(140853, 'frFR', '', 'Vous allez devoir commencer par tuer les golems. Ensuite, vous pourrez utiliser le totem pour retirer les âmes de leurs cadavres.', 28153),
(140852, 'frFR', 'Une fois à l\’intérieur, ne lambinez pas. Le point de rendez-vous suivant se trouve de l\’autre côté des ruines, près de la salle souterraine.', '', 28153),
(140851, 'frFR', 'Il n\’y a plus d\’espoir ! Les promesses du trompeur, c\’est des mensonges !', '', 28153),
(140850, 'frFR', 'Mensonges ! C\’est rien que des mensonges !', '', 28153),
(140849, 'frFR', 'Pourquoi on m\’a imposé ces visions ?! POURQUOI ?!', '', 28153),
(140848, 'frFR', 'Vous êtes qu\’un pantin. Même la mort pourra pas vous délivrer !', '', 28153),
(140847, 'frFR', 'Prosternez-vous devant G\’huun !', '', 28153),
(140846, 'frFR', '', 'Ce n\’est pas la mort qui m\’arrêtera…', 28153),
(140845, 'frFR', '', 'La Matriarche… vous emportera…', 28153),
(140844, 'frFR', 'Voilà ! Z\’avez un esprit troll de sang en vous et vous devriez vous transformer quand vous approcherez de leur village.', '', 28153),
(140843, 'frFR', '', 'C\’est loin d\’être fini…', 28153),
(140842, 'frFR', '', 'Le Sabbat est… partout…', 28153),
(140841, 'frFR', '', 'Drustvar ne vous appartient pas !', 28153),
(140840, 'frFR', '', 'Inutile de résister !', 28153),
(140839, 'frFR', '', 'Tous plieront devant la Matriarche !', 28153),
(140838, 'frFR', '', 'Le Sabbat s\’emparera de votre misérable village !', 28153),
(140837, 'frFR', '', 'Ah, voilà Omi qui vient nous faire son rapport.', 28153),
(140836, 'frFR', '', 'Mauvaise nouvelle, les gars. Ça grouille de spectres là-dedans. Du coup, j\’ai décidé de passer le niveau de menace à orange.', 28153),
(140834, 'frFR', '', 'Je vais fureter dans les ruines pendant que vous vous en chargez. Rejoignez-moi au point de rendez-vous quand vous aurez fini.', 28153),
(140833, 'frFR', '', 'Ne perdez pas votre temps avec les golems inanimés. Trouvez-en un qui fonctionne encore.', 28153),
(140832, 'frFR', 'Envoyez-moi à la crête de la Cognée.', 'Envoyez-moi à la crête de la Cognée.', 28153),
(140831, 'frFR', 'On se retrouve au point de rendez-vous du pont brisé avant d\’attaquer les ruines directement.', '', 28153),
(140830, 'frFR', 'Très bien, tout le monde sait quoi faire. Bonne chasse !', '', 28153),
(140829, 'frFR', 'Suivez-moi. Le roi Rastakhan est à deux pas d\’ici.', 'Suivez-moi. Le roi Rastakhan est à deux pas d\’ici.', 28153),
(140828, 'frFR', '', 'Armes au clair. Quelqu\’un approche…', 28153),
(140827, 'frFR', '', 'Quand Zul, il a exigé qu\’on lui livre la dépouille de Dazar, le premier roi, on a cru à une blague.$b$bEt on lui a dit non.$b$bOn savait pas qu\’il avait une armée à sa disposition pour prendre le temple par la force.', 28153),
(140826, 'frFR', 'Ces ruines regorgent de trésors. Prenons le temps de faire ça bien.', '', 28153),
(140825, 'frFR', '', 'Maman ? Où tu es ?', 28153),
(140824, 'frFR', '<Winstone déballe un nouveau paquet de cartes. D\’où sort-il tout cet or ?>', '', 28153),
(140823, 'frFR', '<Winstone fixe ses cartes avec intensité.>', '', 28153),
(140822, 'frFR', '<Penché sur sa collection de cartes, Winstone réfléchit à un nouveau deck.$b$bÀ y regarder de plus près, on dirait qu\’il sélectionne un bon paquet de bêtes...>', '', 28153),
(140821, 'frFR', 'Envoyez-moi à Ar\’gorok.', 'Envoyez-moi à Ar\’gorok.', 28153),
(140820, 'frFR', 'Pour trouver Xal\’zaix, nous devons d\’abord trouver Sephraliss.', '', 28153),
(140818, 'frFR', 'Zak\’rajan utilise nos âmes comme des armes. Vous êtes condamnés.', '', 28153),
(140817, 'frFR', 'Vos armes ne peuvent rien contre lui. Nos esprits le protègent !', '', 28153),
(140816, 'frFR', 'Un corps de plus à briser pour Zak\’rajan !', '', 28153),
(140815, 'frFR', 'Votre âme rejoindra les autres dans ce golem !', '', 28153),
(140814, 'frFR', 'Libérez-nous…', '', 28153),
(140813, 'frFR', 'Zak\’rajan règne en maître…', '', 28153),
(140812, 'frFR', 'Les étrangers doivent être chassés.', '', 28153),
(140811, 'frFR', 'Pas de rois. Seulement Zak\’rajan.', '', 28153),
(140810, 'frFR', 'Allez, allez, vous retrouvez cette ma\’da égarée et vous lui ramenez la petite !', '', 28153),
(140809, 'frFR', 'Hé hé… la petite a raison. Sa ma\’da est pas encore passée de l\’Autre côté.', '', 28153),
(140808, 'frFR', 'Pas de Loas. Seulement Zak\’rajan.', '', 28153),
(140807, 'frFR', 'Défendez la cour à tout prix.', '', 28153),
(140806, 'frFR', 'Aidez-nous…', '', 28153),
(140805, 'frFR', 'Un sacrifice… pour Zak\’rajan…', '', 28153),
(140804, 'frFR', 'Ahah… ces prêtres ! Si jamais vous voulez changer de culte, ne faites rien sans le dire au vieux Bwonsamdi, d\’accord ?', '', 28153),
(140803, 'frFR', 'Les mouches de sang sont particulièrement agressives ces jours-ci.', 'Les mouches de sang sont particulièrement agressives ces jours-ci.', 28153),
(140802, 'frFR', 'Aïe !', 'Aïe !', 28153),
(140801, 'frFR', 'Qu\’est-ce qui vous prend ?', 'Qu\’est-ce qui vous prend ?', 28153),
(140800, 'frFR', 'Eh ! Faites attention avec ce truc !', 'Eh ! Faites attention avec ce truc !', 28153),
(140799, 'frFR', 'Maudits étrangers…', 'Maudits étrangers…', 28153),
(140798, 'frFR', 'Aïe ! Puis-je savoir ce qui vous prend ?', 'Aïe ! Je peux savoir ce qui vous prend ?', 28153),
(140797, 'frFR', 'Notre cause est perdue. La Légion ardente nous consumera tous.', '', 28153),
(140796, 'frFR', 'Sales charognards ! C\’est chez moi ici !', '', 28153),
(140795, 'frFR', 'Nos champions sont tombés. Plus rien ne pourra arrêter la fin de tout.', '', 28153),
(140794, 'frFR', 'Les éléments répondent à l\’appel de la Horde, comme il se doit.', '', 28153),
(140793, 'frFR', '', 'L\’autel des esprits, il est prêt. De quoi que vous avez besoin ?', 28153),
(140792, 'frFR', 'Même les Loas, ils nous ont abandonnés.', 'Même les Loas, ils nous ont abandonnés.', 28153),
(140791, 'frFR', 'Cela fait une éternité que nous sommes les esclaves de Zak\’rajan. Libérez-nous...', 'Cela fait une éternité que nous sommes les esclaves de Zak\’rajan. Libérez-nous...', 28153),
(140790, 'frFR', 'Les esprits, c\’est des armes redoutables… à condition de savoir les contrôler.', 'Les esprits, c\’est des armes redoutables… à condition de savoir les contrôler.', 28153),
(140789, 'frFR', 'Il utilise nos âmes pour se protéger. Vos armes ne peuvent rien contre son bouclier.', 'Il utilise nos âmes pour se protéger. Vos armes ne peuvent rien contre son bouclier.', 28153),
(140788, 'frFR', 'On nous a fait miroiter une fortune dépassant l\’entendement, mais au lieu de ça, on a été réduits en esclavage.', 'On nous a fait miroiter une fortune dépassant l\’entendement, mais au lieu de ça, on a été réduits en esclavage.', 28153),
(140787, 'frFR', 'Zak\’rajan, il nous avait interdit de vénérer les Loas. Personne d\’autre que lui n\’avait droit à cet honneur.', 'Zak\’rajan, il nous avait interdit de vénérer les Loas. Personne d\’autre que lui n\’avait droit à cet honneur.', 28153),
(140786, 'frFR', 'Pourquoi Bwonsamdi, il refuse de nous laisser rejoindre l\’Autre côté ?', 'Pourquoi Bwonsamdi, il refuse de nous laisser rejoindre l\’Autre côté ?', 28153),
(140785, 'frFR', 'Zak\’rajan a emprisonné nos âmes dans ces golems. Il nous oblige à le servir.', 'Zak\’rajan a emprisonné nos âmes dans ces golems. Il nous oblige à le servir.', 28153),
(140784, 'frFR', 'J\’espère que nos bêtes ont faim. Avec Grangeneuve sous la bannière de la Horde, on va pouvoir entraîner des chevaucheurs de loups.', '', 28153),
(140783, 'frFR', 'L\’armurerie est opérationnelle. Faites-moi chauffer ces forges !', '', 28153),
(140781, 'frFR', 'La construction de l\’armurerie est terminée. Quels sont vos ordres ?', '', 28153),
(140780, 'frFR', 'Zak\’rajan va payer pour nous avoir retenus prisonniers !', 'Zak\’rajan va payer pour nous avoir retenus prisonniers !', 28153),
(140779, 'frFR', 'Sephraliss veillera sur nous.', 'Sephraliss veillera sur nous.', 28153),
(140778, 'frFR', '', 'Repose en paix, douce Kaja. Nous ne t\’oublierons jamais.', 28153),
(140777, 'frFR', 'Sulphis fut le tout premier Gardien. Il nous a demandé notre aide, à Korphek et à moi, pour enfermer le corps de Mythrax dans la grande pyramide.\n\nEnsemble, nous avons érigé une barrière et scellé son cadavre à l\’intérieur.\n\nChacun de nous a ensuite créé une clé, imprégnée de notre pouvoir, pour s\’assurer que rien ne troublerait jamais ce tombeau.', '', 28153),
(140776, 'frFR', 'Allons, allons ! Inutile de se battre. Asseyons-nous plutôt autour d\’un verre et de quelques énigmes bien ficelées, d\’accord ?', '', 28153),
(140775, 'frFR', 'Si vous croyez que Winstone est un pigeon, vous allez être $gdéçu:déçue;. Il finira par retomber sur ses pattes et ce sera VOUS le dindon de la farce !', '', 28153),
(140774, 'frFR', 'Je connais Rastakhan, le puissant roi éternel. Il devrait se méfier, il ne faut pas prendre n\’importe qui sous son aile.', '', 28153),
(140773, 'frFR', 'Pourquoi nous quitter si vite ? Restez au moins le temps de boire un verre et de vous détendre un peu.', '', 28153),
(140772, 'frFR', 'Bienvenue au bar exotique du Trône doukacque. C\’est ici qu\’on trouve la meilleure gnôle de Zandalar !', '', 28153),
(140771, 'frFR', 'Nous pouvons utiliser le lien entre le cœur et Sephraliss pour la retrouver.', '', 28153),
(140770, 'frFR', 'Le cœur est lié à la force vitale de notre Loa. La lueur rouge que vous décrivez indique qu\’elle est perturbée, mais surtout qu\’elle est en vie !', '', 28153),
(140769, 'frFR', 'Si vous dites vrai, nous devons agir au plus vite !', '', 28153),
(140768, 'frFR', 'Intéressant…', '', 28153),
(140767, 'frFR', 'Non, non, non, non. Vous me servez à rien si vous mourez. Je pourrais vous ressusciter… si vous payez.', '', 28153),
(140766, 'frFR', 'Qu\’est… Qu\’est-ce que vous faites là ? C\’est pas l\’heure de mourir pour vous… pas encore.', '', 28153),
(140764, 'frFR', '', 'Elle ne pouvait pas savoir que ça changerait la jungle en désert…', 28153),
(140762, 'frFR', 'Raaaaaaagh !', '', 28153),
(140761, 'frFR', 'Les infidèles ne s\’empareront pas de ce temple.', '', 28153),
(140760, 'frFR', 'En me servant de leur pouvoir, je pourrai courber l\’espace-temps et soutenir notre effort.', '', 28153),
(140759, 'frFR', 'Quant à vous autres, vous mêlez plus jamais d\’mes affaires. Ceux qui honorent pas leurs engagements, ils le paient cher.', '', 28153),
(140758, 'frFR', 'Et maintenant, retournez souffrir dans votre prison.', '', 28153),
(140757, 'frFR', 'Je négocie pas avec les parjures.', '', 28153),
(140756, 'frFR', 'Par pitié, Bwonsamdi, passons un autre marché ! Je battrai vos tambours tous les jours ! Mon peuple vous adorera pour toujours !', '', 28153),
(140755, 'frFR', 'Moi aussi, je cherche Rakera. Et ces serpents, ils racontent que vous l\’avez trouvée.\n\nOn en a de la chance, de pouvoir être tous réunis. Enfin, s\’ils acceptent de m\’laisser sortir de cette cage...', '', 28153),
(140754, 'frFR', 'Vous passerez jamais de l\’Autre côté. Vous verrez jamais vos ancêtres. Z\’êtes piégé ici pour l\’éternité.', '', 28153),
(140753, 'frFR', 'Bwonsamdi, il est pas du genre à oublier ce genre d\’affront.', '', 28153),
(140752, 'frFR', 'Mais z\’êtes devenu arrogant. Z\’avez interdit qu\’on adore quelqu\’un d\’autre que vous. Ça vous revient ?', '', 28153),
(140751, 'frFR', 'transformez-moi', 'transformez-moi', 28153),
(140750, 'frFR', 'On avait un accord. Z\’aviez le pouvoir et votre peuple, il m\’adorait.', '', 28153),
(140749, 'frFR', 'Si c\’est ce que vous croyez, z\’êtes aussi débile que malhonnête, Zak\’rajan.', '', 28153),
(140748, 'frFR', 'Zandalar est truffée de secrets. Peut-être sommes-nous tombés sans le vouloir sur quelque chose que nous n\’étions pas censés découvrir.', '', 28153),
(140747, 'frFR', '', 'On va révéler à tout le monde que Jakra\’zet, c\’est un traître.', 28153),
(140746, 'frFR', 'Bwonsamdi, maudit bâtard ! J\’ai enfin gagné !', '', 28153),
(140745, 'frFR', 'Oui ! Je vais enfin pouvoir rejoindre mes ancêtres dans les terres de l\’Ombre !', '', 28153),
(140743, 'frFR', 'Qui sont les Gardiens ?', 'Qui sont les Gardiens ?', 28153),
(140742, 'frFR', 'Que se passe-t-il ? Mon âme est enfin délivrée de sa prison ?', '', 28153),
(140740, 'frFR', 'Qui est Sephraliss ?', 'Qui est Sephraliss ?', 28153),
(140739, 'frFR', 'Les infidèles sont une troupe de militants sephraks, dirigés par l\’empereur Korphek.\n\nIl y a longtemps de ça, nous vivions tous ensemble, comme Sephraliss l\’aurait souhaité.\n\nDepuis la trahison de Korphek, les infidèles ont jeté ces terres dans la guerre.\n\nIls ne s\’arrêteront pas avant d\’avoir conquis le monde.', '', 28153),
(140738, 'frFR', 'Qui est Korphek ?', 'Qui est Korphek ?', 28153),
(140737, 'frFR', 'Les infidèles ne s\’empareront pas de ce temple.', '', 28153),
(140736, 'frFR', 'Khaz\’goroth ! Façonnez ces héros à notre image !', '', 28153),
(140735, 'frFR', '', 'Champions ! Relevez-vous et combattez pour le salut de votre monde !', 28153),
(140734, 'frFR', '', 'Ne perdons pas espoir, Patriarche. L\’étincelle de vie n\’est pas encore éteinte.', 28153),
(140733, 'frFR', 'Non ! Après tout ce que nous avons enduré… Cela ne peut pas finir ainsi !', '', 28153),
(140732, 'frFR', 'Le temps m\’obéit, Annihilateur ! Et seul son pouvoir est capable de réprimer une telle fureur !', '', 28153),
(140731, 'frFR', 'Les mortels ont échoué. Le dernier titan… ne peut être sauvé.', '', 28153),
(140730, 'frFR', 'La rage de l\’Annihilateur s\’intensifie ! Hâtez-vous, héros ! Abattez ces assemblages !', '', 28153),
(140729, 'frFR', '', 'Bien joué. Revenez quand vous voulez pour une petite chasse maritime ! Prenez donc un griffon pour le Trident. Nous allons finir de nettoyer ici.', 28153),
(140727, 'frFR', '', 'Vous croyez qu\’on peut se fier à Serrik ? Que les Sephraks, ils nous aideront à trouver Xal\’zaix ?', 28153),
(140725, 'frFR', '', 'C\’est l\’œuvre de Jakra\’zet ? Il a déjà mis la main sur Xal\’zaix ?', 28153),
(140724, 'frFR', 'Gloire ! Gloire à la mer !', '', 28153),
(140723, 'frFR', 'Nul ne peut arrêter les marées…', '', 28153),
(140722, 'frFR', 'Ifis yahf an\’zig…', '', 28153),
(140721, 'frFR', 'Tremblez sous le regard de notre maître !', '', 28153),
(140720, 'frFR', 'Uothk w\’shh !', '', 28153),
(140719, 'frFR', 'La mer vous appelle, $r.', '', 28153),
(140718, 'frFR', 'Vous m\’appartenez, esprits ! Retournez dans vos golems !', '', 28153),
(140717, 'frFR', 'Examen', 'Examen', 28153),
(140716, 'frFR', '', 'Son bouclier est tombé. Frappez !', 28153),
(140715, 'frFR', '', 'Quand on sait s\’y prendre, on peut laisser les esprits faire le gros du travail.', 28153),
(140714, 'frFR', '', 'Voilà précisément pourquoi je garde ces vieux totems bourrés d\’esprits en colère, $p…', 28153),
(140713, 'frFR', '', 'Le voilà ! Je vais m\’occuper de ce maudit bouclier d\’âmes.', 28153),
(140712, 'frFR', 'Norgannon ! Que votre finesse d\’esprit révèle les faiblesses de notre ennemi !', '', 28153),
(140711, 'frFR', 'J\’accorderai mon pouvoir à l\’un d\’entre eux, Patriarche.', '', 28153),
(140710, 'frFR', 'Aggramar, mon frère, prêtez votre force à ces mortels !', '', 28153),
(140709, 'frFR', 'Que la fureur de la mer engloutisse la corruption !', '', 28153),
(140708, 'frFR', 'Golganneth, que la puissance du ciel et de la mer appuie nos champions !', '', 28153),
(140707, 'frFR', 'C\’est nous qu\’on a le meilleur slerp de ce côté de la mer pouillotte. Y a pas mieux pour se rincer la glaviotte !', '', 28153),
(140706, 'frFR', 'Voulez un verre, lokdu ?', '', 28153),
(140705, 'frFR', '', 'Je ne sais pas si cet homme-serpent dit la vérité, mais on n\’a pas trop le choix.', 28153),
(140704, 'frFR', 'Faut que je grouke qui pour avoir un fichu slerp par ici ?', 'Faut que je grouke qui pour avoir un fichu slerp par ici ?', 28153),
(140703, 'frFR', 'Vous... vous avez quelque chose à vendre ?', 'Vous... vous avez quelque chose à vendre ?', 28153),
(140702, 'frFR', '', 'Cette arme, il faut qu\’on la trouve avant Jakra\’zet.', 28153),
(140701, 'frFR', '', '<La Hurane émet une série de grognements ponctués de couinements.>', 28153),
(140700, 'frFR', 'Ils ont pas froid aux yeux, ces Barges ! Moi, je n\’aurais jamais le courage d\’affronter ces monstres ! La manutention, c\’est ça, mon créneau.', 'Ils ont pas froid aux yeux, ces Barges ! Moi, je n\’aurais jamais le courage d\’affronter ces monstres ! La manutention, c\’est ça, mon créneau.', 28153),
(140699, 'frFR', '', 'Allons-y, Okri. Les Barges attendent.', 28153),
(140698, 'frFR', '', 'Nous n\’attendrons pas plus longtemps votre bénédiction, Therold. Nous avons des monstres à tuer.', 28153),
(140697, 'frFR', 'Une fois Zak\’rajan hors jeu, ce sera premier arrivé, premier servi. Tout ce que vous prendrez sera à vous.', '', 28153),
(140696, 'frFR', 'POURQUOI ?', 'POURQUOI ?', 28153),
(140695, 'frFR', 'AAAAAAHHHHHH !', 'AAAAAAHHHHHH !', 28153),
(140694, 'frFR', 'ÇA BRÛLE !', 'ÇA BRÛLE !', 28153),
(140693, 'frFR', '', 'J\’ai tout ce qu\’il nous faut pour venir à bout de la barrière de Zak\’rajan. Montrez-moi juste où il se trouve.', 28153),
(140692, 'frFR', 'Pas comme ça !', 'Pas comme ça !', 28153),
(140691, 'frFR', 'Non, non, non, NON !', 'Non, non, non, NON !', 28153),
(140690, 'frFR', 'Attendez, stop, STOP !', 'Attendez, stop, STOP !', 28153),
(140689, 'frFR', '', 'Je passe devant. Ne vous éloignez pas.', 28153),
(140688, 'frFR', '', 'Ils ont tout fait pour, mais grâce à $n, j\’ai pas encore rejoint Bwonsamdi.', 28153),
(140687, 'frFR', '', 'Ne vous servez pas sans moi.', 28153),
(140686, 'frFR', '', 'Ravie de voir que le désert ne t\’a pas encore avalée, Rakera.', 28153),
(140685, 'frFR', '', 'Nous vous retrouverons là-bas, mes éclaireurs et moi.', 28153),
(140684, 'frFR', '', 'Merci de m\’avoir aidée. Je ne sais pas tout ce qu\’implique notre découverte, mais je suis contente que nous ayons réussi à sauver au moins quelques personnes.', 28153),
(140683, 'frFR', '', 'Le seigneur Brannon et les autres sont en route pour prévenir les gens de la vallée Chantorage de la corruption qui gangrène les prêtres. Quant à moi, j\’en informerai Boralus.', 28153),
(140682, 'frFR', 'Je vous retrouve là-bas, $n. Les affaires spirituelles exigent un certain doigté.', '', 28153),
(140681, 'frFR', '', 'J\’ai exactement ce qu\’il faut pour soigner ça...', 28153),
(140680, 'frFR', '', 'Nous sommes tombés sur quelque chose qui nous dépasse.', 28153),
(140678, 'frFR', '', 'On va attendre ici. Les assassins de Jakra\’zet, il vaut mieux ne pas attirer leur attention.', 28153),
(140677, 'frFR', 'Une minute...', '', 28153),
(140675, 'frFR', '', 'Le monstre est mort ! Un combat qui restera dans les annales des Barges.', 28153),
(140673, 'frFR', '', 'Le monstre sort de l\’eau ! Faites-lui sentir toute la puissance des Barges !', 28153),
(140672, 'frFR', 'L\’assassin furie-des-sables se réfugie dans l\’ombre.', 'L\’assassin furie-des-sables se réfugie dans l\’ombre.', 28153),
(140671, 'frFR', '', 'Ne baissez pas les bras ! Faites-lui boire la tasse !', 28153),
(140670, 'frFR', '', 'Détruisez ces tentacules ! Forcez la bête à émerger !', 28153),
(140669, 'frFR', '', 'Prenez garde aux assassins. Jakra\’zet a mis ma tête à prix.', 28153),
(140667, 'frFR', 'Ce monde, il sera à nous. Zul, il l\’a prédit !', 'Ce monde, il sera à nous. Zul, il l\’a prédit !', 28153),
(140666, 'frFR', 'Ce qui se prépare, vous ne pouvez pas l\’empêcher. Zul l\’a prédit.', 'Ce qui se prépare, vous ne pouvez pas l\’empêcher. Zul l\’a prédit.', 28153),
(140665, 'frFR', 'Vous ramenez notre raté de roi ? Il va mourir, et vous ne pouvez rien y faire.', 'Vous ramenez notre raté de roi ? Il va mourir, et vous ne pouvez rien y faire.', 28153),
(140664, 'frFR', 'Vous arrivez trop tard. Zul, il est déjà en route pour la cime.', 'Vous arrivez trop tard. Zul, il est déjà en route pour la cime.', 28153),
(140663, 'frFR', 'La Horde, elle est cuite. L\’Alliance, pareil. Et Zandalar s\’imposera !', 'La Horde, elle est cuite. L\’Alliance, pareil. Et Zandalar s\’imposera !', 28153),
(140662, 'frFR', 'Zandalar dominera le monde !', 'Zandalar dominera le monde !', 28153),
(140661, 'frFR', 'On se bat pour un vrai empire troll !', 'On se bat pour un vrai empire troll !', 28153),
(140660, 'frFR', 'Ma vie pour Zul !', 'Ma vie pour Zul !', 28153),
(140659, 'frFR', 'La terreur de la mer, contrôlée par le sombre maître d\’Austergarde ! Pas sûr que les Barges eux-mêmes soient de taille à l\’affronter.', '', 28153),
(140656, 'frFR', 'J\’en ai affronté des costauds, et je les ai tous ratatinés !', '', 28153),
(140655, 'frFR', 'Personne ne touche à mon butin…', '', 28153),
(140654, 'frFR', 'Inconcevable…', '', 28153),
(140653, 'frFR', 'Les gars ! Faites-leur donc goûter à notre artillerie lourde !', '', 28153),
(140652, 'frFR', 'Canons ! Réduisez ces chiens galeux en charpie !', '', 28153),
(140651, 'frFR', 'Regardez s\’ils ont des dents en or, les gars. Le reste finira aux requins.', '', 28153),
(140650, 'frFR', 'J\’adore le bruit des cadavres qui tombent sur le pont.', '', 28153),
(140649, 'frFR', '', 'G\’huun, il sera bientôt libre et les disciples d\’Hir\’eek seront récompensés !', 28153),
(140648, 'frFR', 'Très bien les gars, rassemblez leurs objets de valeur. Quand j\’aurai pris ma part, vous pourrez vous partager le reste.', '', 28153),
(140647, 'frFR', 'Vous avez oublié la règle d\’or. Faut jamais se mettre entre Sweete et son butin !', '', 28153),
(140646, 'frFR', 'Répandez leurs tripes sur le pont !', '', 28153),
(140645, 'frFR', 'Tout le monde sur le pont !', '', 28153),
(140644, 'frFR', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s commence à lancer |cFFFF0000|Hspell:255594|h[Ciel et mer]|h|r !', '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s commence à lancer |cFFFF0000|Hspell:255594|h[Ciel et mer]|h|r !', 28153),
(140643, 'frFR', '', 'Impressionnant. Vous avez survécu plus longtemps que je ne pensais… mais je boirai quand même votre sang.', 28153),
(140642, 'frFR', '', 'Rezan était un puissant Loa. Vous serez peut-être un sacrifice digne de Zul.', 28153),
(140641, 'frFR', '', 'Merci d\’avoir tué la prêtresse. Vous n\’avez fait que renforcer mon emprise sur le temple.', 28153),
(140640, 'frFR', 'Cela me satisfait ! Amenez-en plus dans mon antre… Je dois communier avec le maître !', '', 28153),
(140639, 'frFR', '', 'La menace des sans-visage est jugulée, du moins pour le moment, mais je continuerai à garder un œil sur Atul\’Aman afin de m\’en assurer.', 28153),
(140638, 'frFR', '', 'Vo\’kaal est à nouveau en pièces ? Peu importe… Je peux le reconstruire. Alors que vous, votre mort sera définitive !', 28153),
(140637, 'frFR', 'Prêt pour une virée aérienne !', 'Prête pour une virée aérienne !', 28153),
(140636, 'frFR', 'Nous sommes assiégés ! Suivez-moi, il faut arrêter ce monstre !', '', 28153),
(140635, 'frFR', 'Faites-moi signe quand vous voudrez y aller ! Le temps file et le monstre n\’hésitera pas, lui !', '', 28153),
(140634, 'frFR', '', 'Bientôt, Zul réveillera Dazar, et l\’empire troll renaitra de ses cendres !', 28153),
(140633, 'frFR', '', 'Vous arrivez trop tard, étrangers ! Le temple, il appartient à mon maître, désormais.', 28153),
(140632, 'frFR', 'HA HA ! Ça marche ! Continuez comme ça ! Continuez !', '', 28153),
(140631, 'frFR', 'On est moins nombreux que les Sephraks, alors on doit se montrer plus malins qu\’eux.', '', 28153),
(140630, 'frFR', '', 'Quand une occasion se présente, il faut la saisir. Tout est bon à prendre.', 28153),
(140629, 'frFR', '', 'Il ne faut jamais rien jeter. Tout finit par servir tôt ou tard.', 28153),
(140628, 'frFR', '|TInterface\\Icons\\ABILITY_MOUNT_EPICBATMOUNT.BLP:20|t%s commence à invoquer |cFFFF0000|Hspell:256497|h[Horreur sanglante]|h|r ! À couvert !', '', 28153),
(140627, 'frFR', 'Bien… on nous croit morts… Il nous faut… un nouveau plan.', '', 28153),
(140626, 'frFR', 'Tant de témérité… pour finir en cadavres dans mon repaire. Je consumerai leurs restes… quand j\’aurai récupéré.', '', 28153),
(140625, 'frFR', '', 'Les vents vous mèneront à l\’intérieur d\’Atul\’Aman... Préparez-vous !', 28153),
(140624, 'frFR', '', 'C\’est à nous qu\’incombe la tâche de découvrir la source de cette perturbation et d\’y mettre un terme.', 28153),
(140623, 'frFR', '', 'Atul\’Aman abrite depuis des siècles une puissance ténébreuse qui ne cesse de croître. Les éléments eux-mêmes en sont perturbés, je le sens...', 28153),
(140622, 'frFR', 'Unités de mortiers ! Rasez leur forteresse ! Qu\’il n\’en reste rien !', '', 28153),
(140621, 'frFR', '', 'Les échos de cette déflagration résonnent encore au niveau élémentaire. Quelle puissance a bien pu causer une telle catastrophe ?', 28153),
(140620, 'frFR', '', 'Atul\’Aman était un lieu magnifique avant d\’être détruit par une gigantesque explosion il y a des milliers d\’années.', 28153),
(140619, 'frFR', 'À terre… Vite ! Hir\’eek arrive !', '', 28153),
(140618, 'frFR', '', 'Posez vos mains sur la pierre chamanique et j\’invoquerai un cyclone qui vous portera jusqu\’à Atul\’Aman.', 28153),
(140617, 'frFR', '', 'Nous devons nous débarrasser des scorpides queue-de-verre, mais je crains fort que des menaces pires encore ne nous attendent ensuite.', 28153),
(140616, 'frFR', 'Aaahhh !!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140615, 'frFR', 'Vous êtes forts… mais nul n\’est assez puissant pour affronter un Loa !', '', 28153),
(140614, 'frFR', 'ASSEZ ! Je vais me repaître de vos os brisés !', '', 28153),
(140613, 'frFR', 'La puissance de mon maître coule dans mes veines… Elle me purifiera de votre infection !', '', 28153),
(140612, 'frFR', 'Je vais… Aaaaargh ! Qu\’est-ce que que… Du poison ? Que m\’avez-vous fait ?', '', 28153),
(140611, 'frFR', 'Ha ! Qu\’est-ce que vous espérez faire au juste ? Je suis le seigneur du ciel !', '', 28153),
(140610, 'frFR', '', 'On a le choix, peut-être ?', 28153),
(140609, 'frFR', '', 'Rakera ! Tu crois vraiment ce qu\’il raconte ?', 28153),
(140608, 'frFR', '', 'Dans ce cas, vous pouvez compter sur nous, Serrik.', 28153),
(140607, 'frFR', 'Rassemblez les ingrédients nécessaires au rituel et nous vous aiderons à chercher votre artéfact perdu.', '', 28153),
(140606, 'frFR', 'Cette vision, elle a été plus utile qu\’on aurait pu l\’imaginer. Xal\’zaix, il est à notre portée.', '', 28153),
(140605, 'frFR', 'Qu\’est-ce qu\’il va nous apprendre au juste, ce rituel, hein ? Qu\’on va bientôt trouver Xal\’zaix ?', '', 28153),
(140604, 'frFR', 'Vous leur faites vraiment confiance, à ces serpents ? Je parie qu\’ils en savent plus que ce qu\’ils veulent bien dire...', '', 28153),
(140603, 'frFR', 'Les miens peuvent vous aider à trouver ce Xal… Comment dites-vous, déjà ? Xal\’zaix ?', '', 28153),
(140602, 'frFR', 'Z\’allez quand même pas me laisser pourrir dans cette cage ?', '', 28153),
(140601, 'frFR', 'Chercher Rakera, c\’est mission impossible. Son sort, il était scellé dès qu\’elle a été envoyée dans le désert.', '', 28153),
(140600, 'frFR', '', 'Le caveau, il était condamné ! Comment est-ce qu\’il peut être vide ? Ça n\’a aucun sens…', 28153),
(140599, 'frFR', '', 'Qu\’est-ce que Jakra\’zet a fait…', 28153),
(140596, 'frFR', 'Nul ne peut… arrêter l\’avancée des sables…', '', 28153),
(140595, 'frFR', 'Le temple doit tomber ! Nous massacrerons tous ceux qui se dressent contre nous.', '', 28153),
(140594, 'frFR', 'J\’aime faire des affaires avec vous. Maintenant, si vous permettez, j\’vais mettre les bouts avant qu\’on remarque ma disparition.', '', 28153),
(140593, 'frFR', 'Chose promise, chose due ! Voici les tenues officielles des Éperonneurs. Maintenant, vous ressemblez à de vrais criminels.', '', 28153),
(140592, 'frFR', 'Vous serez brisés comme du verre !', 'Vous serez brisés comme du verre !', 28153),
(140591, 'frFR', 'Pour l\’empereur !', 'Pour l\’empereur !', 28153),
(140590, 'frFR', 'Z\’avez réussi ! J\’savais que mon cabot nous aiderait. C\’est vraiment le meilleur ami de l\’homme, çui-là.', '', 28153),
(140589, 'frFR', 'Nous éradiquerons les insectes de votre genre !', 'Nous éradiquerons les insectes de votre genre !', 28153),
(140588, 'frFR', 'Tout comme ce sable, vous finirez aux quatre vents !', 'Tout comme ce sable, vous finirez aux quatre vents !', 28153),
(140587, 'frFR', 'Que les sables vous engloutissent !', 'Que les sables vous engloutissent !', 28153),
(140586, 'frFR', 'Nous exerçons notre domination sur tout et tous !', 'Nous exerçons notre domination sur tout et tous !', 28153),
(140585, 'frFR', 'Nul ne peut arrêter la progression des sables !', 'Nul ne peut arrêter la progression des sables !', 28153),
(140584, 'frFR', 'Vos terres seront bientôt nôtres !', 'Vos terres seront bientôt nôtres !', 28153),
(140583, 'frFR', 'Alors… filez-moi un coup d\’main, et j\’vous revaudrai ça. Topez là !', '', 28153),
(140582, 'frFR', 'Mais avant, j\’vais avoir besoin de votre aide. C\’te fichue serrure ne va pas s\’ouvrir toute seule. Ce chien galeux a la clé, mais il est du genre fuyant.', '', 28153),
(140581, 'frFR', 'Je vais bien m\’amuser !', 'Je vais bien m\’amuser !', 28153),
(140580, 'frFR', 'Jakra\’zet veut sa mort !', 'Jakra\’zet veut sa mort !', 28153),
(140579, 'frFR', 'Votre tête est mise à prix !', 'Votre tête est mise à prix !', 28153),
(140578, 'frFR', 'Si vous voulez vraiment mettre la pagaille, va vous falloir rencontrer le conseil des capitaines. Et il se trouve que c\’est justement dans mes cordes.', '', 28153),
(140576, 'frFR', 'Je vais vous massacrer !', 'Je vais vous massacrer !', 28153),
(140575, 'frFR', 'Jakra\’zet vous salue !', 'Jakra\’zet vous salue !', 28153),
(140574, 'frFR', 'Ohé ! Vous m\’avez tout l\’air de vrais pirates, vous. Pas comme la vermine qui traîne dans le coin.', '', 28153),
(140573, 'frFR', 'Vague d\’acier !', '', 28153),
(140572, 'frFR', 'En garde !', '', 28153),
(140571, 'frFR', '', 'Je rate jamais ma cible.', 28153),
(140570, 'frFR', '', 'J\’adore quand mes cibles se débattent !', 28153),
(140569, 'frFR', 'Le voilà !', '', 28153),
(140568, 'frFR', 'Ce tonneau est vide ! Prenez-le donc !', '', 28153),
(140567, 'frFR', 'Partez à la recherche de Krag\’wa. Le jeunot, il vous retrouvera là-bas.', '', 28153),
(140566, 'frFR', 'Vous pensez avoir une chance contre moi, espèces de porcs ? Je vais vous prouver le contraire.', '', 28153),
(140565, 'frFR', '', 'Je n\’avais encore jamais vu un Sephrak demander grâce. Si ça se trouve, il dit la vérité.', 28153),
(140564, 'frFR', '', 'Pas le temps de faire des prisonniers. Qu\’on l\’exécute et qu\’on en finisse !', 28153),
(140563, 'frFR', '', 'Mensonges ! Les Sephraks, ils ne savent que semer la mort et la désolation !', 28153),
(140562, 'frFR', 'Subissez le courroux de la mer !', '', 28153),
(140561, 'frFR', 'Ouvrez l\’œil.', '', 28153),
(140560, 'frFR', 'Je ne suis pas votre ennemi ! Vous devez me croire !', '', 28153),
(140559, 'frFR', 'Qu\’on m\’enterre avec ma lame…', '', 28153),
(140558, 'frFR', 'Je ne vous veux aucun mal ! Pitié… ne me tuez pas !', '', 28153),
(140557, 'frFR', 'C\’est ma proie !', 'C\’est ma proie !', 28153),
(140556, 'frFR', 'Vous allez regretter d\’avoir foulé ces terres !', 'Z\’allez regretter d\’avoir foulé ces terres !', 28153),
(140555, 'frFR', 'On a ordre de l\’assassiner.', 'On a ordre de l\’assassiner.', 28153),
(140554, 'frFR', 'Ce que vous possédez, sera bientôt à moi !', 'Ce que vous possédez, ça sera bientôt à moi !', 28153),
(140553, 'frFR', 'N\’existe-t-il donc aucun adversaire à ma taille ?', '', 28153),
(140552, 'frFR', 'C\’est pas votre combat !', 'C\’est pas votre combat !', 28153),
(140551, 'frFR', 'Vous en avez trop vu pour rester en vie !', 'Vous en avez trop vu pour rester en vie !', 28153),
(140550, 'frFR', 'Vous avez rien à faire ici !', 'Vous avez rien à faire ici !', 28153),
(140549, 'frFR', 'Premier sang !', '', 28153),
(140548, 'frFR', 'Un joli coup de grâce !', '', 28153),
(140546, 'frFR', 'Voyons ce que vous avez dans le ventre !', '', 28153),
(140545, 'frFR', '', 'Vous allez manger du plomb, vermines !', 28153),
(140544, 'frFR', '', 'Il va y avoir du grabuge !', 28153),
(140542, 'frFR', '', 'Vous pouvez toujours courir, vous ne m\’échapperez pas !', 28153),
(140541, 'frFR', '', 'J\’vous ai dans le viseur !', 28153),
(140540, 'frFR', '', 'Joli… coup…', 28153),
(140539, 'frFR', '', 'Ahhh, j\’avais encore des balles dans le barillet.', 28153),
(140538, 'frFR', '', 'On va les laisser s\’occuper des Sephraks pour l\’instant. Vous et moi, on doit ouvrir le caveau et débusquer Xal\’zaix.', 28153),
(140537, 'frFR', '', 'Pile entre les deux yeux.', 28153),
(140536, 'frFR', '', 'Une encoche de plus à mon canon !', 28153),
(140535, 'frFR', '', 'Vos crânes feront d\’excellentes cibles d\’entraînement.', 28153),
(140534, 'frFR', 'Terre en vue !', '', 28153),
(140533, 'frFR', 'C\’est ma tournée !', '', 28153),
(140532, 'frFR', 'Buvez, sales chiens galeux !', '', 28153),
(140531, 'frFR', 'Ça marchera jamais. Notre loyauté, elle va à Rastakhan, pas à ce faux prophète.', '', 28153),
(140530, 'frFR', 'Ho, hisse !', '', 28153),
(140529, 'frFR', 'Cul sec, bande de vauriens !', '', 28153),
(140528, 'frFR', 'Moi je dis, tout ce qu\’il mérite, c\’est un aller simple pour le royaume de Bwonsamdi.', '', 28153),
(140527, 'frFR', '', 'Vous, allez harmoniser cette sphère. Nous autres, on part fouiller les ruines d\’Atul\’Aman à la recherche du caveau de Xal\’zaix.', 28153),
(140526, 'frFR', '', 'Comme si ça suffisait pas d\’avoir emmené la flotte en Pandarie, maintenant, il cherche à s\’emparer de Zuldazar, le sale traître !', 28153),
(140525, 'frFR', '', 'J\’ai jamais eu confiance en Zul. C\’est un bonimenteur !', 28153),
(140524, 'frFR', 'Je reviens dès que j\’ai fini, ma\’da.', '', 28153),
(140523, 'frFR', 'Et ma tournée d\’adieu… ?', '', 28153),
(140522, 'frFR', 'Tout de suite, ma\’da ! Vos désirs, c\’est des ordres.', '', 28153),
(140521, 'frFR', 'Vous avez l\’air d\’avoir du vent dans les voiles !', '', 28153),
(140520, 'frFR', 'Apprenez déjà à tenir l\’alcool, moussaillon !', '', 28153),
(140519, 'frFR', 'Tout ce que vous voudrez, ma\’da !', '', 28153),
(140518, 'frFR', 'Le camp, il a besoin de plus de pierres. Va collecter les plus pures de Nazmir seulement. Soixante, qu\’il en faut.', 'Le camp, il a besoin de plus de pierres. Va collecter les plus pures de Nazmir seulement. Soixante, qu\’il en faut.', 28153),
(140517, 'frFR', 'Jetez l\’ancre, bande de loques. Moi je vais aller m\’en jeter un !', '', 28153),
(140516, 'frFR', 'Il faut plus de bois pour le camp. Va m\’en chercher trente pièces de la meilleure qualité que tu trouveras.', 'Il faut plus de bois pour le camp. Va m\’en chercher trente pièces de la meilleure qualité que tu trouveras.', 28153),
(140515, 'frFR', 'Hé, ma\’da ! J\’attends bien sagement ici, comme on m\’a dit de le faire.', '', 28153),
(140514, 'frFR', 'Il nous faut cinquante peaux de crocilisque en parfait état. Va les chercher et c\’est pas la peine de revenir tant que tu les as pas toutes.', 'Il nous faut cinquante peaux de crocilisque en parfait état. Va les chercher et c\’est pas la peine de revenir tant que tu les as pas toutes.', 28153),
(140513, 'frFR', 'Ma\’da ! Je peux faire quelque chose pour vous ?', '', 28153),
(140512, 'frFR', 'Ils vous plaisent, mes oiseaux ?', '', 28153),
(140511, 'frFR', 'Montrez-moi où je peux voler.', 'Montrez-moi où je peux voler.', 28153),
(140510, 'frFR', '', 'Votre âme m\’appartient !', 28153),
(140509, 'frFR', '', 'Vous êtes sous mon contrôle !', 28153),
(140508, 'frFR', '', 'Votre âme, je vais la déchirer !', 28153),
(140507, 'frFR', '', 'Je vais briser votre âme en mille morceaux !', 28153),
(140506, 'frFR', '', 'Pour la Horde !', 28153),
(140505, 'frFR', 'Pour la Horde !', '', 28153),
(140504, 'frFR', '', 'Pour la Horde !', 28153),
(140503, 'frFR', '', 'À compter de ce jour, Haut-Roc fait serment de toujours combattre vos ennemis à vos côtés.', 28153),
(140502, 'frFR', '', 'J\’accepte votre serment de loyauté. La Horde offre protection… en échange de votre obéissance.', 28153),
(140501, 'frFR', '', 'Chef de guerre, par leurs actes, Baine Sabot-de-Sang et notre héraut ont témoigné de la puissance et du courage qui caractérisent la Horde.', 28153),
(140500, 'frFR', '', 'Quelle est la raison de votre venue, grand chef ?', 28153),
(140499, 'frFR', 'Ce serait pour la Horde un honneur de vous accueillir ! Rendons-nous à Orgrimmar annoncer cette grande nouvelle à notre chef de guerre.', '', 28153),
(140498, 'frFR', '', 'Si vous l\’acceptez, nous, Taurens de Haut-Roc, serons fiers de rejoindre votre Horde.', 28153),
(140497, 'frFR', '', 'Baine Sabot-de-Sang, vous avez fait montre de courage, d\’honneur et de loyauté. Il est grand temps que votre peuple et le mien renouvellent les liens qui les unissent.', 28153),
(140496, 'frFR', 'Je frémis à cette idée, Mayla. Sans l\’intervention rapide de Baine et de notre camarade, c\’en était fini de nous tous.', '', 28153),
(140495, 'frFR', '', 'Si Uul\’gyneth avait atteint son but, nous serions tous devenus des serviteurs des Dieux très anciens… Y compris Corne-d\’Ebène.', 28153),
(140494, 'frFR', '', 'Ce jour a bien failli être très sombre pour Azeroth.', 28153),
(140493, 'frFR', '', 'Imbéciles… Zul, il va… briser… votre esprit.', 28153),
(140492, 'frFR', 'Les murmures… ils ont cessé. Merci… à vous et à Grisciel.', '', 28153),
(140491, 'frFR', '', 'Corne-d\’Ébène est au plus mal. Nous devons trouver un moyen de le faire revenir à lui. Allez parler au marcheur des esprits Grisciel. Je crois qu\’il pourra nous aider.', 28153),
(140490, 'frFR', 'Tant que nous ne saurons pas qui est derrière cette attaque, Mulgore sera en danger. Je vous accompagne, Mayla. Affrontons les ténèbres ensemble.', '', 28153),
(140489, 'frFR', '', 'Je dois immédiatement ramener Corne-d\’Ebène à Haut-Roc !', 28153),
(140488, 'frFR', 'Je ne connais que trop bien ce pouvoir. Héraut ! Nous avons besoin de votre aide !', '', 28153),
(140487, 'frFR', '', 'Corne-d\’Ebène ! Quelles forces obscures vous tourmentent ?', 28153),
(140486, 'frFR', 'Je n\’aurais jamais… dû quitter… la montagne…', '', 28153),
(140485, 'frFR', 'J\’aimerais évoquer nos liens de parenté. J\’espère que…', '', 28153),
(140484, 'frFR', '', 'Tout l\’honneur est pour moi, Baine. Il est temps pour nos deux peuples de renouveler les liens qui les unissent.', 28153),
(140483, 'frFR', 'Merci de votre venue, Mayla. C\’est un honneur de vous accueillir en Mulgore.', '', 28153),
(140482, 'frFR', '', 'Votre sang, il est à moi.', 28153),
(140481, 'frFR', '', 'Je ferai bon usage de votre sang… puisque vous ne vous en servirez plus.', 28153),
(140480, 'frFR', '', 'Dazar va bientôt se réveiller, mais vous vivrez pas assez longtemps pour le voir !', 28153),
(140479, 'frFR', 'Nos troupes disposent désormais d\’armures d\’acier !', 'Nos troupes disposent désormais d\’armures d\’acier !', 28153),
(140478, 'frFR', 'Trahison ! Saisissez-$gle:la; !', 'Trahison ! Saisissez-$gle:la; !', 28153),
(140477, 'frFR', 'Enlevez vos sales pattes de là !', 'Enlevez vos sales pattes de là !', 28153),
(140476, 'frFR', 'Hé, qu\’est-ce que vous fabriquez ?!', 'Hé, qu\’est-ce que vous fabriquez ?!', 28153),
(140475, 'frFR', 'Quand mes mots leur seront parvenus, déposez le cristal au sommet du mont Hyjal, aux abords du Puits d\’éternité.', '', 28153),
(140474, 'frFR', 'Ce cristal renferme deux messages. L\’un est destiné à mon frère, Malfurion, l\’autre à Tyrande. Je compte sur vous pour les leur remettre en mains propres.', '', 28153),
(140473, 'frFR', 'J\’affronterai mon destin, quoi qu\’il me réserve. Mais il me reste certaines affaires à régler… de vieilles blessures qui n\’ont pas encore cicatrisé.', '', 28153),
(140472, 'frFR', 'À l\’instant où la voie vers Argus s\’est ouverte… au moment où j\’ai posé les yeux sur le monde de la Légion… j\’ai su qu\’il n\’y aurait pour moi aucun retour possible.', '', 28153),
(140471, 'frFR', 'Nos troupes disposent désormais d\’armes d\’acier !', 'Nos troupes disposent désormais d\’armes d\’acier !', 28153),
(140470, 'frFR', 'La douleur, ça m\’fait pas peur, ma\’da ! Je suis prêt à me battre !', '', 28153),
(140469, 'frFR', 'Moi, je suis pas une mauviette, je sens pas la douleur ! Je suis prêt à tuer !', '', 28153),
(140468, 'frFR', 'La douleur, je connais pas. Tous ceux qui me résistent, moi, je les tue !', '', 28153),
(140467, 'frFR', 'Moi, je suis balèze ! Je peux encaisser bien pire que ça, ma\’da !', '', 28153),
(140464, 'frFR', '$n, dites à cette créature qu\’on se connaît. Faites-moi sortir de cette cage !', '', 28153),
(140463, 'frFR', 'Arrachage...', 'Arrachage...', 28153),
(140462, 'frFR', 'Ahh. Ça fait du bien par où ça passe !', '', 28153),
(140461, 'frFR', 'Et voilà. Bien, trinquons à des jours meilleurs !', '', 28153),
(140460, 'frFR', 'Ouais ?', '', 28153),
(140459, 'frFR', '', 'Vous faites un beau sacrifice !', 28153),
(140458, 'frFR', '', 'Grimpez ! Il est peut-être déjà trop tard !', 28153),
(140457, 'frFR', 'Maître va me reconstruire…', '', 28153),
(140456, 'frFR', 'Maître utiliser vos morceaux. Rendre moi plus fort !', '', 28153),
(140455, 'frFR', 'Chair pour maître !', '', 28153),
(140454, 'frFR', 'En pièces.', '', 28153),
(140453, 'frFR', 'Vous mourrez avec moi !', '', 28153),
(140452, 'frFR', 'Pas casser !', '', 28153),
(140451, 'frFR', 'Pouvoir faiblir !', '', 28153),
(140450, 'frFR', 'Pas casser totem !', '', 28153),
(140449, 'frFR', 'Noooon !', '', 28153),
(140448, 'frFR', 'Écraser !', '', 28153),
(140447, 'frFR', 'Casser !', '', 28153),
(140446, 'frFR', 'Vous ? Moi vous mettre en pièces !', '', 28153),
(140445, 'frFR', '', 'Vous voilà enfin ! Les éléments bruissaient de la rumeur de votre arrivée...', 28153),
(140444, 'frFR', 'Zissiah et moi partons devant pour avertir Vorrik de votre arrivée.', '', 28153),
(140441, 'frFR', 'Que pouvez-vous me dire d\’autre ?', 'Que pouvez-vous me dire d\’autre ?', 28153),
(140439, 'frFR', 'Qui sont les infidèles ?', 'Qui sont les infidèles ?', 28153),
(140438, 'frFR', 'Les infidèles ne se laisseront pas décourager, mais vos efforts nous ont offert davantage de temps. Il ne nous reste plus qu\’à trouver notre Loa pour mettre fin à cette tuerie.', '', 28153),
(140437, 'frFR', 'Les infidèles assiègent notre foyer. Nous devons impérativement les repousser ! Il faut les empêcher de s\’emparer du temple.', '', 28153),
(140436, 'frFR', 'Pff, z\’êtes vraiment pas drôle, $gm\’sieur:m\’dame; !', 'Pff, z\’êtes vraiment pas drôle, $gm\’sieur:m\’dame; !', 28153),
(140435, 'frFR', 'Oh, et pis zut à la fin ! Je rentre chez moi, pour la peine.', 'Oh, et pis zut à la fin ! Je rentre chez moi, pour la peine.', 28153),
(140434, 'frFR', 'Groaar ! Groooaaar roooooh... oh.', 'Groaar ! Groooaaar roooooh... oh.', 28153),
(140433, 'frFR', 'Pfff, $gquel:quelle; rabat-joie.', 'Pfff, $gquel:quelle; rabat-joie.', 28153),
(140432, 'frFR', 'Ouais ! C\’est plus marrant quand on est grand !', 'Ouais ! C\’est plus marrant quand on est grand !', 28153),
(140431, 'frFR', 'Wouhou ! Qu\’est-ce qu\’on rigole... Je veux dire, graouh !', 'Wouhou ! Qu\’est-ce qu\’on rigole... Je veux dire, graouh !', 28153),
(140430, 'frFR', 'Oups, attention la tête ! Je vois pas où je mets les pieds !', 'Oups, attention la tête ! Je vois pas où je mets les pieds !', 28153),
(140429, 'frFR', 'Je suis un grand méchant raptor, comme Gonk ! Ha ha ha !', 'Je suis un grand méchant raptor, comme Gonk ! Ha ha ha !', 28153),
(140428, 'frFR', '', 'Pff, z\’êtes vraiment pas drôle, $gm\’sieur:m\’dame; !', 28153),
(140427, 'frFR', '', 'Oh, et pis zut à la fin ! Je rentre chez moi, pour la peine.', 28153),
(140426, 'frFR', '', 'Groaar ! Groooaaar roooooh... oh.', 28153),
(140425, 'frFR', '', 'Vous êtes pas drôle, vous le savez, ça ?', 28153),
(140424, 'frFR', 'Débarrasse-toi d\’eux. Notre travail, il est presque fini !', '', 28153),
(140423, 'frFR', '', 'Ouais ! C\’est plus marrant quand on est grand !', 28153),
(140422, 'frFR', '', 'Wouhou ! Qu\’est-ce qu\’on rigole… Je veux dire, graouh !', 28153),
(140421, 'frFR', '', 'Oups, attention la tête ! Je vois pas où je mets les pieds !', 28153),
(140420, 'frFR', '', 'Je suis un grand méchant raptor, comme Gonk ! Ha ha ha !', 28153),
(140419, 'frFR', 'Vous êtes pas drôle, vous le savez, ça ?', '', 28153),
(140418, 'frFR', 'Groaar ! Groooaaar roooooh… oh.', '', 28153),
(140417, 'frFR', 'Oh, et pis zut ! Je rentre chez moi, pour la peine.', '', 28153),
(140416, 'frFR', 'Pff, vous êtes vraiment pas drôle, $gm\’sieur:m\’dame; !', '', 28153),
(140415, 'frFR', 'Je suis un grand méchant ravasaure, comme Gonk ! Ha ha ha !', '', 28153),
(140414, 'frFR', 'Oups, attention la tête ! Je vois pas où je mets les pieds !', '', 28153),
(140413, 'frFR', 'Wouhou ! Qu\’est-ce qu\’on rigole… Je veux dire… graouh !', '', 28153),
(140412, 'frFR', 'Ouais ! C\’est plus marrant quand on est grand !', '', 28153),
(140411, 'frFR', 'Maître veut vos os !', '', 28153),
(140410, 'frFR', 'Coco ! Eau croupie !', '', 28153),
(140409, 'frFR', 'Sur les flancs ! Coco !', '', 28153),
(140408, 'frFR', 'Naufrage ! Coco !', '', 28153),
(140407, 'frFR', 'Coco ! Vider la soute ! Coco !', '', 28153),
(140406, 'frFR', 'Conches avariées ! Coco !', '', 28153),
(140405, 'frFR', 'Ha ha ! Ne cassez pas votre pipe !', '', 28153),
(140404, 'frFR', 'Beau temps… pour un naufrage.', '', 28153),
(140403, 'frFR', 'Vous avez juste servi d\’appât !', '', 28153),
(140402, 'frFR', 'Les morts racontent pas d\’histoires !', '', 28153),
(140401, 'frFR', 'On dirait que vous avez toujours pas le pied marin !', '', 28153),
(140400, 'frFR', 'J\’ai une sacrée descente !', '', 28153),
(140399, 'frFR', 'J\’vais vous ouvrir de nouvelles écoutilles !', '', 28153),
(140398, 'frFR', 'J\’vais vous saborder !', '', 28153),
(140397, 'frFR', 'J\’vais vous trouer la poupe !', '', 28153),
(140396, 'frFR', 'Ça porte malheur de renverser le verre de quelqu\’un.', '', 28153),
(140395, 'frFR', 'Non ! Un instant de silence pour mon breuvage tombé au combat.', '', 28153),
(140394, 'frFR', 'Ah ! À cause de vous, je vois le fond… de mon verre !', '', 28153),
(140393, 'frFR', 'Pas de quartier !', '', 28153),
(140392, 'frFR', 'Je vais vous voler dans les plumes !', '', 28153),
(140391, 'frFR', 'Les Zandalari ne meurent jamais !', '', 28153),
(140390, 'frFR', 'Ça va saigner !', '', 28153),
(140389, 'frFR', 'Les esprits vous accompagnent !', '', 28153),
(140388, 'frFR', 'On m\’appelle !', '', 28153),
(140387, 'frFR', 'Dans ce cas… À vous, $n !', '', 28153),
(140386, 'frFR', 'Pitié ? Insecte pusillanime ! Nous vous détruirons en même temps que Zuldazar !', '', 28153),
(140385, 'frFR', 'Grand Hir\’eek ! Accorde-nous ta pitié, ô tout puissant. Épargne-nous !', '', 28153),
(140384, 'frFR', 'Charrrgez !', '', 28153),
(140383, 'frFR', 'Jo\’chunga, je suis prêt. Exécutons notre plan pour arrêter Hir\’eek.', 'Jo\’chunga, je suis prête. Exécutons notre plan pour arrêter Hir\’eek.', 28153),
(140382, 'frFR', 'Ah, c\’est de la folie… On m\’avait pas dit que je partais trucider un LOA.', '', 28153),
(140381, 'frFR', 'Aaargh ! Jacasse, viens ici et bombarde-les sur les flancs !', '', 28153),
(140380, 'frFR', 'Fidèles… cessez le combat. Avancez, profanateurs, et acceptez votre destin. Votre sang nourrira G\’huun !', '', 28153),
(140379, 'frFR', 'Attention en dessous, bande de conches avariées !', '', 28153),
(140378, 'frFR', 'Ultime attaque !', '', 28153),
(140377, 'frFR', 'Vous commencez à me fatiguer !', '', 28153),
(140376, 'frFR', 'À présent, mourez, que je ne vous entende plus !', '', 28153),
(140375, 'frFR', 'La région grouille de Trolls, mais ils n\’ont pas le cœur de se battre.$b$bCe n\’est pas comme ça qu\’ils entreront dans les salles des Valeureux ! Nous devons rechercher la gloire sur le champ de bataille !$b$bOù est leur roi ? Il comprendrait, lui. Et il devrait savoir se battre !', '', 28153),
(140374, 'frFR', 'Vous êtes $gvenu:venue; vous battre ? Je cherche justement $gun:une; adversaire digne de ce nom.', '', 28153),
(140373, 'frFR', '', 'Nous cherchons à nous améliorer au combat, à nous couvrir de gloire afin de gagner notre place dans les salles des Valeureux.$b$bLe roi de Zandalar est fort, et cela fait des siècles qu\’il règne d\’une main de fer. C\’est pour nous un digne adversaire. Tout ce que nous avons à faire, c\’est de le rencontrer pour lui jeter le gant !', 28153),
(140372, 'frFR', '', 'Assaut divin !', 28153),
(140371, 'frFR', '', 'Ma victoire sera gravée à jamais dans votre âme !', 28153),
(140370, 'frFR', '', 'Venez ! La bataille nous attend !', 28153),
(140369, 'frFR', 'Largage !', '', 28153),
(140368, 'frFR', '', 'Je cherche de nobles guerriers prêts à me rejoindre dans mon combat.', 28153),
(140367, 'frFR', 'Faites pas attention à Jacasse ! Il a juste besoin de se… vider la soute !', '', 28153),
(140366, 'frFR', 'Vot\’ fin est proche !', '', 28153),
(140364, 'frFR', 'Jacasse, lève l\’ancre et déploie-moi tes fichues ailes ! Nous devons nous occuper de ces marins d\’eau douce.', '', 28153),
(140363, 'frFR', 'Des intrus !', '', 28153),
(140362, 'frFR', 'J\’espère que vous avez fait vot\’ testament !', '', 28153),
(140361, 'frFR', 'En avant toutes, bande de buveurs d\’eau croupie !', '', 28153),
(140360, 'frFR', 'Qui je dois tuer ?', '', 28153),
(140359, 'frFR', '', 'Nous allons tenir l\’île et nous vous tiendrons au courant s\’il y a du nouveau !', 28153),
(140358, 'frFR', 'Longue vie au roi !', '', 28153),
(140357, 'frFR', 'Bwonsamdi, il me donne une autre chance !', '', 28153),
(140356, 'frFR', 'Taz\’dingo !', '', 28153),
(140355, 'frFR', '', 'Cet or est en mon pouvoir !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(140354, 'frFR', '', 'Vous n\’avez rien à faire ici !', 28153),
(140353, 'frFR', '', 'Je vous arracherai le cœur.', 28153),
(140352, 'frFR', '', 'Pas de temps à perdre. Nous vous retrouverons près de la grotte !', 28153),
(140335, 'frFR', 'C\’est le moment de vérité… Si le plan marche pas, on est morts…', '', 28153),
(140334, 'frFR', 'Oh non… c\’est Hir\’eek !', '', 28153),
(140333, 'frFR', 'La princesse Talanji, elle est curieuse de savoir ce qui se passe ici, dans les marais.', '', 28153),
(140332, 'frFR', '', 'L\’or, il répond à mon appel.', 28153),
(140331, 'frFR', '', 'La corruption sera lavée !', 28153),
(140330, 'frFR', '', 'La puissance d\’Atal\’Dazar coule dans mes veines !', 28153),
(140329, 'frFR', '', 'Et une purification, une !', 28153),
(140328, 'frFR', '', 'La mort, elle vous va bien.', 28153),
(140327, 'frFR', '', 'Les bassins… doivent être… purifiés.', 28153),
(140326, 'frFR', '', 'Seuls les braves sont enterrés ici. Vos cadavres, ils serviront de nourriture aux raptors.', 28153),
(140325, 'frFR', '', 'Vous auriez jamais dû venir ici.', 28153),
(140324, 'frFR', '', 'Vous cherchez de l\’or, mais vous ne trouverez que la mort.', 28153),
(140323, 'frFR', '', 'Les serviteurs de Yazma ne sont pas les bienvenus ici !', 28153),
(140322, 'frFR', 'Montrez-vous. Je vais m\’occuper de vous personnellement.', '', 28153),
(140321, 'frFR', 'Talanji, elle nous a envoyés ici pour vérifier les rumeurs comme quoi le marais serait infesté de monstres. Au final, on a trouvé bien pire : les monstres, ils les fabriquent…', '', 28153),
(140320, 'frFR', 'Je te croyais mort ! Me dis pas que tu bosses pour ces flagorneurs !', '', 28153),
(140319, 'frFR', 'C\’est… une longue histoire. Et si on s\’en jetait un petit ?', '', 28153),
(140318, 'frFR', 'Encore ces sagouins de Lamineurs… Une minute… Flynn ?', '', 28153),
(140317, 'frFR', 'En garde, mollusque gluant ! On est là pour ton butin !', '', 28153),
(140316, 'frFR', '', 'Quoi ? Non ! Quel est... ce pouvoir...', 28153),
(140315, 'frFR', 'Bienvenue dans la bande de la Défense d\’or, $p. Vous faites partie de la famille maintenant !', '', 28153),
(140314, 'frFR', '', 'Z\’avez déjà cogné un Sephrak tellement fort que sa queue, elle vous est restée entre les mains ?', 28153),
(140313, 'frFR', 'Vous êtes les muscles et moi, j\’suis la tête.\n\nOn forme une équipe d\’enfer, quoi !', '', 28153),
(140312, 'frFR', '', 'Vous inquiétez pas, ce tambour sera réparé en moins de deux.', 28153),
(140311, 'frFR', '', 'Les zozieaux noirs l\’avaient prédit !', 28153),
(140310, 'frFR', '', 'Il n\’y a plus que moi et mes jouets…', 28153),
(140309, 'frFR', '', 'On pourrait entendre une mouche voler…', 28153),
(140308, 'frFR', '', 'Tous les habitants sont figés ou bien ont fui.', 28153),
(140307, 'frFR', 'Collecte', 'Collecte', 28153),
(140306, 'frFR', '', 'Azshara… J\’ai échoué…', 28153),
(140305, 'frFR', '', 'Ma reine sera ravie d\’apprendre votre mort. Gloire à Nazjatar !', 28153),
(140303, 'frFR', 'Buvez-donc un verre avec Flynn et moi ! C\’est la maison qui régale !$b$bQu\’est-ce que vous prendrez ?', '', 28153),
(140302, 'frFR', 'Du lait... dans une chope en crâne.', 'Du lait... dans une chope en crâne.', 28153),
(140301, 'frFR', 'Du lait.', 'Du lait.', 28153),
(140300, 'frFR', 'De la bière.', 'De la bière.', 28153),
(140299, 'frFR', '|TInterface\\Icons\\INV_AMMO_BULLET_03:20|t%s vous cible avec une balle |cFFFF0000|Hspell:256044|h[transperçante]|h|r !', '', 28153),
(140298, 'frFR', 'Faites attention à vous. Y a du grabuge dans le coin.', '', 28153),
(140297, 'frFR', 'On vous accueillera toujours avec joie, $p. Vous faites partie de la bande de la Défense d\’or à vie.', '', 28153),
(140296, 'frFR', 'La Défense d\’or est officiellement ouverte !', '', 28153),
(140295, 'frFR', 'Merci de m\’avoir sauvé…', '', 28153),
(140294, 'frFR', 'Je crois bien que je vais rester ici un moment et me rendre utile.', '', 28153),
(140293, 'frFR', 'Je n\’arrive pas à croire que je vous ai $gretrouvé:retrouvée;, $p. Mais je suis si fatigué…', '', 28153),
(140292, 'frFR', 'Je dirais bien que vous n\’avez plus toute votre tête, mais vous m\’avez sauvé la vie… merci.', '', 28153),
(140291, 'frFR', 'Vous avez aidé ces exilés à établir une auberge au beau milieu de nulle part ?', '', 28153),
(140290, 'frFR', 'Ni le désert, ni les bêtes sauvages n\’ont découragé ceux qui me traquaient. Je m\’en suis tiré de justesse.', '', 28153),
(140289, 'frFR', 'Les Trolls de sang, c\’est des malades. Ils nous prennent pour de la pâtée pour chauve-souris !', 'Les Trolls de sang, c\’est des malades. Ils nous prennent pour de la pâtée pour chauve-souris !', 28153),
(140288, 'frFR', 'Ces fumiers, ils voulaient me saigner pour leurs chauves-souris !', 'Ces fumiers, ils voulaient me saigner pour leurs chauves-souris !', 28153),
(140287, 'frFR', 'Merci ! Ils allaient me sacrifier à leurs chauves-souris !', 'Merci ! Ils allaient me sacrifier à leurs chauves-souris !', 28153),
(140286, 'frFR', 'Un peu plus, et les chauves-souris, elles m\’auraient mangé tout cru !', 'Un peu plus, et les chauves-souris, elles m\’auraient mangée toute crue !', 28153),
(140285, 'frFR', 'La reine Azshara semble pour le moins désespérée. Et nous sommes sur le point de lui faire passer un quart d\’heure encore pire.$B$BJe m\’en réjouis d\’avance.', '', 28153),
(140283, 'frFR', 'Votre déguisement a disparu ! Pourquoi le mien est toujours là ? Hmm… Va falloir faire autrement.', '', 28153),
(140282, 'frFR', '$n ! Qu\’est-ce que vous faites ?', '', 28153),
(140281, 'frFR', 'Argh, j\’ai le tournis… Bwonsamdi, il a bien failli me rappeler à lui.', '', 28153),
(140280, 'frFR', '', 'Je sais ce que vous pensez : les Trolls zandalari n\’avaient pas asservi les Gobelins pour les envoyer à la mine ?$b$bLe truc, c\’est que si on ne fait pas affaire avec nos ennemis, ils feront affaire entre eux. Et ça, c\’est pas bon pour notre chiffre.', 28153),
(140279, 'frFR', '', 'Inutile de me remercier.', 28153),
(140278, 'frFR', 'Inutile de me remercier.', '', 28153),
(140277, 'frFR', 'Je vous en prie.', '', 28153),
(140276, 'frFR', '', 'Je vous en prie.', 28153),
(140275, 'frFR', 'Je suis honoré de servir.', '', 28153),
(140274, 'frFR', '', 'Je suis honorée de servir.', 28153),
(140273, 'frFR', '', 'C\’était tout naturel.', 28153),
(140272, 'frFR', 'C\’était tout naturel.', '', 28153),
(140271, 'frFR', '', 'Ce fut un plaisir.', 28153),
(140270, 'frFR', 'Ce fut un plaisir.', '', 28153),
(140269, 'frFR', 'Tout le plaisir était pour moi.', '', 28153),
(140268, 'frFR', '', 'Tout le plaisir était pour moi.', 28153),
(140267, 'frFR', '', 'Incontestablement.', 28153),
(140266, 'frFR', 'Incontestablement.', '', 28153),
(140265, 'frFR', 'C\’est exact.', '', 28153),
(140264, 'frFR', 'Mon premier verre en Vol\’dun. Je tournais en rond dans les dunes depuis l\’attaque !', '', 28153),
(140263, 'frFR', '', 'C\’est exact.', 28153),
(140262, 'frFR', 'Qu\’est-ce que vous faites ici, $p ? Je vous croyais $uperdu:perdue; à jamais !', '', 28153),
(140261, 'frFR', 'Affirmatif.', '', 28153),
(140260, 'frFR', '', 'Affirmatif.', 28153),
(140259, 'frFR', '', 'Sans hésitation.', 28153),
(140258, 'frFR', 'Sans hésitation.', '', 28153),
(140257, 'frFR', 'Attendez ici.', '', 28153),
(140256, 'frFR', '', 'Attendez ici.', 28153),
(140255, 'frFR', '', 'Maintenez la position.', 28153),
(140254, 'frFR', 'Maintenez la position.', '', 28153),
(140253, 'frFR', 'Restez ici.', '', 28153),
(140252, 'frFR', '', 'Restez ici.', 28153),
(140251, 'frFR', '', 'Restez ici.', 28153),
(140250, 'frFR', 'Restez ici.', '', 28153),
(140249, 'frFR', 'C\’est généreux de votre part.', '', 28153),
(140248, 'frFR', '', 'C\’est généreux de votre part.', 28153),
(140247, 'frFR', '', 'Si vous trouvez que mes poings sont trop rapides, attendez plutôt de faire la connaissance de ma sœur Noxie. Elle vous fera voir trente-six chandelles !', 28153),
(140246, 'frFR', '', 'J\’ai une dette envers vous.', 28153),
(140245, 'frFR', 'J\’ai une dette envers vous.', '', 28153),
(140244, 'frFR', 'Merci à vous.', '', 28153),
(140243, 'frFR', '', 'Merci à vous.', 28153),
(140242, 'frFR', '', 'Je vous remercie.', 28153),
(140241, 'frFR', 'Je vous remercie.', '', 28153),
(140240, 'frFR', '', 'La Lumière vous rend grâce.', 28153),
(140239, 'frFR', 'La Lumière vous rend grâce.', '', 28153),
(140238, 'frFR', 'Vous avez toute ma gratitude.', '', 28153),
(140237, 'frFR', '', 'Vous avez toute ma gratitude.', 28153),
(140236, 'frFR', '', 'J\’ai besoin de mana.', 28153),
(140235, 'frFR', 'J\’ai besoin de mana.', '', 28153),
(140234, 'frFR', 'Il me faut plus de mana.', '', 28153),
(140233, 'frFR', '', 'Il me faut du mana.', 28153),
(140232, 'frFR', '', 'Mana requis.', 28153),
(140231, 'frFR', 'Mana requis.', '', 28153),
(140230, 'frFR', 'Je manque de mana.', '', 28153),
(140229, 'frFR', '', 'Je dois récupérer du mana.', 28153),
(140228, 'frFR', '', 'Moxie vous recevra dès que vous serez $gprêt:prête;, l\’$gami:amie;.$b$bFaites pas attention à moi. Je suis là pour assurer le service de sécurité. Par contre, vous avisez pas de lever le petit doigt contre elle. J\’ai une bonne allonge.', 28153),
(140227, 'frFR', '', 'Bombardez l\’ennemi !', 28153),
(140226, 'frFR', 'Bombardez l\’ennemi !', '', 28153),
(140225, 'frFR', 'Feu à volonté !', '', 28153),
(140224, 'frFR', '', 'Feu à volonté !', 28153),
(140223, 'frFR', '', 'Je vous fais peur ? Vous devriez voir ma sœur, Boxie. Agressive comme un silithide et agile comme un serpent-nuage... Pan, dans les dents !', 28153),
(140222, 'frFR', '', 'Si vous voulez discuter, allez plutôt voir Moxie. C\’est elle, la négociatrice.$b$b<Noxie soupèse sa masse et en tape le fer contre la paume de sa main.>$b$bMa spécialité à moi, c\’est de vous fracasser le crâne au premier geste déplacé. On discute pas avec moi.', 28153),
(140221, 'frFR', 'Déchaînez votre fureur !', '', 28153),
(140220, 'frFR', '', 'Déchaînez votre fureur !', 28153),
(140219, 'frFR', '', 'Feu à volonté !', 28153),
(140218, 'frFR', '', 'Parlez au chef si ça vous chante, mais je vous ai à l\’œil.', 28153),
(140217, 'frFR', '', 'Dans le port, on fait pas de vague, compris ? Et c\’est pas une blague !', 28153),
(140216, 'frFR', '', 'Ouvrez le feu !', 28153),
(140215, 'frFR', '', 'Entendu.', 28153),
(140214, 'frFR', 'Entendu.', '', 28153),
(140213, 'frFR', 'Si vous avez une affaire à régler avec le chef, c\’est au chef qu\’il faut vous adresser.$b$bQuoi, avec moi ? Je crois pas, non. Circulez, et plus vite que ça.', '', 28153),
(140212, 'frFR', 'Assurément.', '', 28153),
(140211, 'frFR', '', 'Assurément.', 28153),
(140210, 'frFR', '$p… ?', '', 28153),
(140209, 'frFR', 'Qu\’il en soit ainsi.', '', 28153),
(140208, 'frFR', '', 'Qu\’il en soit ainsi.', 28153),
(140207, 'frFR', '', 'Gazrix et sa bande ? Un peu que je les vois, ils sont juste là-bas. Mais ils auront beau comploter, ça ne les avancera pas à grand-chose. D\’ailleurs, notre première démarche quand on obtiendra une audience avec le roi, ce sera de nous débarrasser de la concurrence.$b$bC\’est la loi du marché, pas vrai ? Tant qu\’on a le monopole de l\’offre, on peut demander tout ce qu\’on veut !', 28153),
(140206, 'frFR', '', 'Compris.', 28153),
(140205, 'frFR', 'Compris.', '', 28153),
(140204, 'frFR', 'Très bien.', '', 28153),
(140203, 'frFR', '', 'Très bien.', 28153),
(140202, 'frFR', '', 'Certainement pas.', 28153),
(140201, 'frFR', 'Certainement pas.', '', 28153),
(140200, 'frFR', 'Je suis blessé… Ayez pitié d\’un frère Zandalari !', '', 28153),
(140199, 'frFR', 'C\’est inacceptable.', '', 28153),
(140198, 'frFR', '', 'C\’est inacceptable.', 28153),
(140197, 'frFR', 'Ohé ? Il y a quelqu\’un ?', '', 28153),
(140196, 'frFR', '', 'Je ne crois pas.', 28153),
(140195, 'frFR', 'Je ne crois pas.', '', 28153),
(140194, 'frFR', 'Jamais !', '', 28153),
(140193, 'frFR', '', 'Hors de question.', 28153),
(140192, 'frFR', 'Non.', '', 28153),
(140191, 'frFR', '', 'Non.', 28153),
(140190, 'frFR', '', 'Non.', 28153),
(140189, 'frFR', 'Non.', '', 28153),
(140188, 'frFR', 'Préparez-vous, les gars. Voilà notre premier client de la journée… J\’ai hâte ! Et surtout, le tuez pas !', '', 28153),
(140187, 'frFR', '', 'On est ici pour représenter les intérêts du cartel Baille-Fonds. Et on ira jusqu\’au bout, même coincées dans ce port avec ces amateurs de Gentepression !$b$bLes négociations avancent bien. Bientôt, je discuterai avec le roi et il finira par comprendre à quel point un partenariat commercial serait mutuellement avantageux.', 28153),
(140186, 'frFR', '', 'Le cartel Baille-Fonds emploie certains des meilleurs négociateurs sur le marché. Investissements, rachats, acquisitions... Rien ne leur résiste. Ça, on peut dire qu\’ils impressionnent.$b$bEt quand les autres ne sont pas à la hauteur, c\’est moi qu\’ils envoient. Moi et mes filles, on prend le relais, vous allez voir.', 28153),
(140185, 'frFR', 'Les agents de Baille-Fonds ? Un peu que je les vois ! Ils sont juste là, et ils se croient malins en envoyant Moxie et ses greluches « garder un œil » sur nous. Comme si on avait quoi que ce soit à cacher, hein ?$b$bPas de quoi s\’inquiéter. J\’ai déjà eu affaire à des princes marchands, ce sera un jeu d\’enfant.', '', 28153),
(140184, 'frFR', 'Ça alors, je m\’attendais pas à vous trouver ici. Vous pourriez apporter un message au roi, dites ? Je parie qu\’il serait curieux de savoir quelles opportunités commerciales on pourrait offrir à sa belle ville.', '', 28153),
(140183, 'frFR', 'Ennemi en approche !', '', 28153),
(140182, 'frFR', '', 'Le danger menace.', 28153),
(140181, 'frFR', 'Puisque je vous dis qu\’on est ici en mission officielle pour le cartel Gentepression !$b$bLe patron a bien conscience de la grandeur de l\’empire zandalari, et qui dit empire, dit opportunités commerciales, vous me suivez ?$b$bPour l\’instant, ils refusent de nous laisser entrer dans la ville, mais j\’ai le sentiment que ça pourrait bientôt changer.', '', 28153),
(140180, 'frFR', '', 'Danger en approche !', 28153),
(140179, 'frFR', 'Danger en approche !', '', 28153),
(140178, 'frFR', 'À l\’aide !', '', 28153),
(140177, 'frFR', '', 'À l\’aide !', 28153),
(140176, 'frFR', 'J\’ai besoin d\’aide !', '', 28153),
(140175, 'frFR', '', 'J\’ai besoin d\’aide !', 28153),
(140174, 'frFR', '', 'Que quelqu\’un me vienne en aide !', 28153),
(140173, 'frFR', 'Que quelqu\’un me vienne en aide !', '', 28153),
(140172, 'frFR', 'Aidez-moi !', '', 28153),
(140171, 'frFR', '', 'Aidez-moi !', 28153),
(140170, 'frFR', 'Suramar demeure fière… et libre.', '', 28153),
(140169, 'frFR', '', 'Suramar demeure fière… et libre.', 28153),
(140168, 'frFR', '', 'Nous nous dressons contre les ténèbres.', 28153),
(140167, 'frFR', 'Nous nous dressons contre les ténèbres.', '', 28153),
(140166, 'frFR', 'Enchanté.', '', 28153),
(140165, 'frFR', '', 'Enchantée.', 28153),
(140163, 'frFR', 'Ça devrait en boucher un coin à tous les clients qui feront le déplacement !', '', 28153),
(140161, 'frFR', 'Je sais exactement où je vais mettre cette… défense pour que tout le monde la voie.', '', 28153),
(140160, 'frFR', 'DO NOT TRANSLATE', '', 28153),
(140159, 'frFR', 'Grozztok, occupe-toi de ces intrus ! Ne me déçois pas une fois de plus.', '', 28153),
(140158, 'frFR', 'Silence ! Nous ne sommes pas seuls…', '', 28153),
(140157, 'frFR', 'On peut pas entrer. La porte, elle est scellée par une magie inconnue.', '', 28153),
(140156, 'frFR', 'Vous avez eu tort de vous aventurer dans ces dunes. La princesse, elle peut plus vous sauver, maintenant.', '', 28153),
(140155, 'frFR', 'Acheon Kor.', '', 28153),
(140154, 'frFR', '', 'Acheon Kor.', 28153),
(140153, 'frFR', '', 'Archenon poros.', 28153),
(140152, 'frFR', 'Archenon poros.', '', 28153),
(140151, 'frFR', '', 'Tenu\’balah.', 28153),
(140150, 'frFR', 'Tenu\’balah.', '', 28153),
(140149, 'frFR', 'Salutations.', '', 28153),
(140148, 'frFR', '', 'Salutations.', 28153),
(140147, 'frFR', 'Salutations.', '', 28153),
(140146, 'frFR', '', 'Salutations.', 28153),
(140145, 'frFR', '', 'J\’ai besoin de soins !', 28153),
(140144, 'frFR', 'J\’ai besoin de soins !', '', 28153),
(140143, 'frFR', '', 'J\’ai grand besoin de soins !', 28153),
(140142, 'frFR', 'J\’ai grand besoin de soins !', '', 28153),
(140141, 'frFR', 'Soignez-moi !', '', 28153),
(140140, 'frFR', '', 'Soignez-moi !', 28153),
(140139, 'frFR', 'Soignez-moi !', '', 28153),
(140138, 'frFR', '', 'Soignez-moi !', 28153),
(140137, 'frFR', '', 'Mes adieux.', 28153),
(140136, 'frFR', 'Mes adieux.', '', 28153),
(140135, 'frFR', '', 'Désirez la paix, mais préparez-vous à la guerre.', 28153),
(140134, 'frFR', 'Désirez la paix, mais préparez-vous à la guerre.', '', 28153),
(140133, 'frFR', 'Servez avec bravoure et humilité.', '', 28153),
(140132, 'frFR', '', 'Servez avec bravoure et humilité.', 28153),
(140131, 'frFR', 'Nous trouverons notre place en ce monde.', '', 28153),
(140130, 'frFR', '', 'Nous trouverons notre place en ce monde.', 28153),
(140129, 'frFR', 'Puisse le fruit de l\’arcan\’dor vous nourrir.', '', 28153),
(140128, 'frFR', '', 'Puisse le fruit de l\’arcan\’dor vous nourrir.', 28153),
(140127, 'frFR', '', 'Suramar honore toujours ses champions.', 28153),
(140126, 'frFR', 'Suramar honore toujours ses champions.', '', 28153),
