(140124, 'frFR', 'Allez dans la Lumière.', '', 28153),
(140123, 'frFR', 'Adieu.', '', 28153),
(140122, 'frFR', '', 'Adieu.', 28153),
(140121, 'frFR', 'Prenons cette direction.', '', 28153),
(140120, 'frFR', 'Venez avec moi.', '', 28153),
(140119, 'frFR', '', 'Venez.', 28153),
(140118, 'frFR', '', 'Venez donc.', 28153),
(140117, 'frFR', '', 'Avec moi.', 28153),
(140116, 'frFR', '', 'Je m\’occupe de tout.', 28153),
(140115, 'frFR', 'Avec moi.', '', 28153),
(140114, 'frFR', 'Je passe devant.', '', 28153),
(140113, 'frFR', '', 'Par ici.', 28153),
(140112, 'frFR', '', 'Par ici.', 28153),
(140111, 'frFR', 'Suivez-moi.', '', 28153),
(140110, 'frFR', 'Suivez-moi.', '', 28153),
(140109, 'frFR', 'Ça reste entre nous, hein, $p ? Vous me le jurez sur la Défense d\’or ?', '', 28153),
(140108, 'frFR', 'Mmm, ce fruit a l\’air délicieux ! Ajoutons-le au buffet.', '', 28153),
(140107, 'frFR', 'Pendant que vous allez nous chercher des fruits, je vais préparer des brochettes de scorpide pour le petit-déjeuner.', '', 28153),
(140106, 'frFR', 'Les écailles |2 $n sont saturées d\’électricité statique !', 'Les écailles |2 $n sont saturées d\’électricité statique !', 28153),
(140105, 'frFR', '', 'Vous pouvez étrenner nos trajets aériens si vous le souhaitez, $p. N\’hésitez pas à venir me voir si vous avez besoin d\’un vol.', 28153),
(140104, 'frFR', '', 'Attention aux saurolisques qui rôdent sur la crête... ils adorent bondir sur leurs proies.', 28153),
(140103, 'frFR', 'Fuyez !', '', 28153),
(140102, 'frFR', '', 'Fuyez !', 28153),
(140101, 'frFR', 'Fuyez !', '', 28153),
(140100, 'frFR', '', 'Sauvez-vous !', 28153),
(140099, 'frFR', '', 'À couvert !', 28153),
(140098, 'frFR', 'À couvert !', '', 28153),
(140097, 'frFR', '', 'À couvert !', 28153),
(140096, 'frFR', 'À couvert !', '', 28153),
(140095, 'frFR', 'Repliez-vous !', '', 28153),
(140094, 'frFR', '', 'Repliez-vous !', 28153),
(140093, 'frFR', 'Repli !', '', 28153),
(140092, 'frFR', '', 'Repli !', 28153),
(140091, 'frFR', 'Puissent les Loas vous donner des ailes. Vous devez avertir le roi avant qu\’il soit trop tard !', '', 28153),
(140090, 'frFR', 'On vous retrouvera près du navire de guerre de Kao, quand la voie, elle sera libre. Les esprits soient avec vous.', '', 28153),
(140089, 'frFR', 'Oui.', '', 28153),
(140088, 'frFR', '', 'Oui.', 28153),
(140087, 'frFR', 'Oui.', '', 28153),
(140086, 'frFR', '', 'Oui.', 28153),
(140085, 'frFR', 'Nos guerriers, ils sont sur la terrasse du haut. Pour Zuldazar !', '', 28153);
