(140058, 'frFR', '', '<Kiss sound>', 28153),
(140057, 'frFR', '<Kiss sound>', '', 28153),
(140056, 'frFR', 'Nous ne tremblerons pas devant les ténèbres.', '', 28153),
(140055, 'frFR', 'Bienvenue parmi nous.', '', 28153),
(140054, 'frFR', 'Je vous salue.', '', 28153),
(140053, 'frFR', 'Bonjour.', '', 28153),
(140052, 'frFR', 'Mes blessures doivent être soignées !', '', 28153),
(140051, 'frFR', 'Soignez-moi !', '', 28153),
(140050, 'frFR', 'Que la montagne vous apporte ombre et réconfort.', '', 28153),
(140049, 'frFR', 'Puissent vos voyages vous apporter la sagesse.', '', 28153),
(140048, 'frFR', 'La Terre-Mère guide vos pas.', '', 28153),
(140047, 'frFR', 'Au revoir.', '', 28153),
(140046, 'frFR', 'Pour la Horde !', '', 28153),
(140045, 'frFR', '', 'Pour la Horde !', 28153),
(140044, 'frFR', 'Pour l\’Alliance !', '', 28153),
(140043, 'frFR', '', 'Pour l\’Alliance !', 28153),
(140042, 'frFR', 'Pour la Horde !', '', 28153),
(140041, 'frFR', '', 'Venez donc.', 28153),
(140040, 'frFR', 'Aidez-moi !', '', 28153),
(140039, 'frFR', 'Il me faut de l\’aide !', '', 28153),
(140038, 'frFR', 'Une menace nous guette !', '', 28153),
(140037, 'frFR', '<Kiss sound>', '', 28153),
(140036, 'frFR', '<Laughing sounds>', '', 28153),
(140035, 'frFR', '<Laughing>', '', 28153),
(140034, 'frFR', 'C\’est inadmissible.', '', 28153),
(140033, 'frFR', 'Je ne crois pas.', '', 28153),
(140032, 'frFR', 'Non.', '', 28153),
(140031, 'frFR', 'Bon… Jo\’chunga ! Va dans cette hutte et prépare un rituel de sang.', 'Bon… Jo\’chunga ! Va dans cette hutte et prépare un rituel de sang.', 28153),
(140030, 'frFR', 'Vite. Le temps joue contre nous !', '', 28153),
(140029, 'frFR', 'En effet.', '', 28153),
(140028, 'frFR', 'Parfait.', '', 28153),
(140027, 'frFR', 'Chut ! Écoutez, faut se tirer d\’ici sans faire de vagues. Chez les Trolls de sang, c\’est les femmes qui commandent.$B$BOrdonnez-moi d\’aller dans cette hutte, là-bas… Dites que c\’est pour préparer un rituel de sang.$B$BPersonne bronchera si vous me donnez des ordres.', '', 28153),
(140026, 'frFR', 'D\’accord.', '', 28153),
(140025, 'frFR', 'Ouvrez le feu !', '', 28153),
(140024, 'frFR', 'Bombardez-les !', '', 28153),
(140023, 'frFR', 'Il me faut du mana.', '', 28153),
(140022, 'frFR', 'J\’ai grand besoin de mana.', '', 28153),
(140021, 'frFR', '<Making a raspberry sound--Pfffthblth!>', '', 28153),
(140020, 'frFR', '<Sighing sound>', '', 28153),
(140019, 'frFR', 'Il n\’y a pas de quoi.', '', 28153),
(140018, 'frFR', 'C\’est un plaisir.', '', 28153),
(140017, 'frFR', 'Je vous en prie.', '', 28153),
(140016, 'frFR', 'Merci mille fois.', '', 28153),
(140015, 'frFR', 'Je ne vous remercierai jamais assez.', '', 28153),
(140014, 'frFR', 'J\’ai une dette envers vous.', '', 28153),
(140013, 'frFR', '<Train noises--chugga chugga choo choo!>', '', 28153),
(140012, 'frFR', 'Attendez ici.', '', 28153),
(140011, 'frFR', 'Restez ici.', '', 28153),
(140010, 'frFR', 'C\’est cela même.', '', 28153),
(140009, 'frFR', 'Tout à fait.', '', 28153),
(140008, 'frFR', 'Oui.', '', 28153),
(140004, 'frFR', 'Je vous envie… assister à la naissance du nouvel empire troll en personne. Mais le vieux Rastakhan, il aura pas ce plaisir.', '', 28153),
(140003, 'frFR', 'Le Mogu, il a rempli son rôle. Les gardes du corps du roi, ils sont partis plus loin.', '', 28153),
(140002, 'frFR', 'La prophétie, elle va devenir réalité. C\’est juste une diversion pendant que Zul, il met en œuvre ses plans.', '', 28153),
(140001, 'frFR', 'Vilnak\’dor ! J\’espère pour vous que Kao ment, sinon ce sera votre tour !', '', 28153),
(140000, 'frFR', '', 'Le roi ?', 28153),
(139999, 'frFR', 'Peu importe…. La fin de votre roi… est proche…', '', 28153),
(139998, 'frFR', 'J\’savais bien qu\’on pouvait pas lui faire confiance ! Il va payer pour ça !', '', 28153),
(139997, 'frFR', 'Zul m\’a promis un nouvel empire et nous l\’obtiendrons !', '', 28153),
(139996, 'frFR', 'Inutile de se voiler la face, Kao. La partie est perdue d\’avance ! Bas les armes !', '', 28153),
(139995, 'frFR', 'Je suis le grondement de l\’orage. La terreur des steppes. Nul ne peut me vaincre !', '', 28153),
(139994, 'frFR', '', 'On est des Zandalari ! On ne capitule pas !', 28153),
(139993, 'frFR', 'Zuldazar nous revient de droit. Capitulez et je vous offrirai peut-être une mort rapide.', '', 28153),
(139992, 'frFR', 'Hmmm. J\’aspirais à un plus grand défi.', '', 28153),
(139991, 'frFR', 'Taz\’dingo ! Pour le roi Rastakhan !', '', 28153),
(139990, 'frFR', '', 'Habutu, va avertir le roi Rastakhan de la trahison de Zul. $p et moi, on va s\’occuper de cette brute.', 28153),
(139989, 'frFR', 'Arrivée de la flotte zandalari', 'Arrivée de la flotte zandalari', 28153),
(139988, 'frFR', 'Faites-moi voir vos chapeaux.', 'Faites-moi voir vos chapeaux.', 28153),
(139987, 'frFR', 'Ça alors, vous en êtes $Urevenu:revenue; ? J\’en crois pas mes yeux !\n\nAvant de vous entendre et de filer me cacher, j\’étais en train de nettoyer l\’auberge avec Zulsan… On voit la différence, non ?', '', 28153),
(139986, 'frFR', 'Voyons ces pierres !', 'Voyons ces pierres !', 28153),
(139985, 'frFR', 'Moi avoir une idée : vous acheter deux chapeaux. Porter un et donner autre à quelqu\’un. Ami, famille, amour... moi pas là pour juger.', '', 28153),
(139984, 'frFR', 'Sûr, chapeaux vendus par deux. Parce que moi, deux têtes !$b$bMais vous une tête seulement, vrai... Pas de bol. Mais ça fait chapeau de rechange !', '', 28153),
(139983, 'frFR', 'Voulez nouveau chapeau ? Moi avoir plein ! Deux pour le prix de deux !', '', 28153),
(139982, 'frFR', 'Vous voulez être grosse force comme Gal\’ay ? Alors achetez une pierre et tous les jours, soulevez pour cogner dans face des gens. Peut-être vous deviendrez grosse force.$b$bMais peut-être pas autant grosse force que Gal\’ay.', '', 28153),
(139981, 'frFR', 'Achetez vos pierres chez Gal\’ay ! Qualité est super supérieure ! Prix sont gentils !', '', 28153),
(139980, 'frFR', 'Hé, vous ! Vous voulez acheter pierre ? Mes pierres, c\’est meilleures.', '', 28153),
(139979, 'frFR', 'Le cœur de Sephraliss brille d\’une lueur rouge. Qu\’est-ce que cela peut bien signifier ?', 'Le cœur de Sephraliss brille d\’une lueur rouge. Qu\’est-ce que cela peut bien signifier ?', 28153),
(139978, 'frFR', 'Nous devons tenir bon.', 'Nous devons tenir bon.', 28153),
(139977, 'frFR', 'Vous pouvez pas manquer le défilé du Mort. C\’est la formation rocheuse sombre et menaçante au nord-est. Ça va vous plaire !', '', 28153),
(139976, 'frFR', 'Dès que vous serez assez près de leur camp, vous vous transformerez. Mais attention, le déguisement, il est pas parfait.', '', 28153),
(139975, 'frFR', 'Les Trollesses de sang, elles commandent les guerriers, alors vous devez leur ressembler. Croyez-moi, ça va marcher !', '', 28153),
(139974, 'frFR', 'Je vous préviens, ça risque de faire un peu mal ! En fait… beaucoup, même !', '', 28153),
(139727, 'frFR', 'Je suis prêt à commencer le rituel pour me déguiser en Trollesse de sang.', 'Je suis prête à commencer le rituel pour me déguiser en Trollesse de sang.', 28153),
(139726, 'frFR', 'Y a un mauvais vaudou qui se dégage de cet endroit.', '', 28153),
(139592, 'frFR', 'Si vous me cherchez, je serai quelque part loin d\’Izarn.', '', 28153),
(139567, 'frFR', 'Je vois que vous vous êtes fait des amis en mon absence.', '', 28153),
(139482, 'frFR', '', 'Tenez ce carrefour ! Il faut empêcher les Mogu d\’avancer !', 28153),
(139443, 'frFR', 'Votre ami est libre, mais je garderais un œil sur lui à votre place.', '', 28153),
(139410, 'frFR', 'Tout de suite.', '', 28153),
(139408, 'frFR', 'C\’est la pagaille en ville. Faut qu\’on assure votre sécurité.', '', 28153),
(139406, 'frFR', 'Pas question de vous quitter, mon roi.', '', 28153),
(139401, 'frFR', 'Tu as eu ta chance. Les Zandalari, ils ne craindront plus tes serviteurs tant que je serai roi.', '', 28153),
(139397, 'frFR', 'Mes soldats, ils vont ratisser la ville, au cas où y en aurait d\’autres.', '', 28153),
(139391, 'frFR', 'Je vous dois la vie, $p. Venez dans le temple. Ce n\’est pas sûr ici.', '', 28153),
(139390, 'frFR', '', 'Hé ! Ça suffit les parlottes. Il est temps de partir à la chasse marine !', 28153),
(139389, 'frFR', 'Frère Therold ! Seigneur Chantorage ! Vous arrivez à point nommé ! Nous avons besoin de vous !', '', 28153),
(139388, 'frFR', 'Retrouvez-moi là où sont les autres quand vous aurez mes affaires. Je dois m\’occuper des préparatifs.', '', 28153),
(139387, 'frFR', 'Vous, là ! Approchez avant que ces brutes reviennent m\’achever.', '', 28153),
(139386, 'frFR', 'Ils peuvent prendre nos terres, mais jamais ils prendront nos âmes éternelles !', '', 28153),
(139385, 'frFR', 'Je vous remercie. Je trouverai la sortie tout seul.', 'Je vous remercie. Je trouverai la sortie toute seule.', 28153),
(139384, 'frFR', 'Par ici ! On protège les Bijoux de Kaza\’jin !', 'Par ici ! On protège les Bijoux de Kaza\’jin !', 28153),
(139383, 'frFR', '', 'Tenez-vous prêts, les Barges ! Ces créatures ne ressemblent en rien à ce que nous avons déjà affronté !', 28153),
(139375, 'frFR', 'Gare à vos orteils ! Les ranishu boufferaient vraiment n\’importe quoi...', '', 28153),
(139374, 'frFR', '', 'Si vous le cherchez aussi, Taji devrait se trouver dans les collines au sud d\’ici.', 28153),
(139372, 'frFR', 'Retrouvez-moi à la caravane quand vous en aurez fini ici. Je vais commencer les réparations en vous attendant.', '', 28153),
(139371, 'frFR', 'Félicitations, $p. Vous avez survécu à une rencontre avec les ranishu. Rares sont ceux qui peuvent en dire autant.', '', 28153),
(139370, 'frFR', 'Ce bois a l\’air des plus robustes... Il fera parfaitement l\’affaire pour les réparations de la caravane.', '', 28153),
(139369, 'frFR', 'Les réparations de la caravane avancent bien grâce au bois de qualité que vous nous avez déniché.', '', 28153),
(139368, 'frFR', '', 'Bon, bon… Hmmm… Voilà ! Parchemin d\’invisibilité. Celui-là devrait faire l\’affaire.', 28153),
(139367, 'frFR', '', 'Concentrez-vous, on a pas le temps pour ces histoires !', 28153),
(139366, 'frFR', 'Je ne t\’ai jamais raconté cette histoire ? Elle est fabuleuse ! Alors, par où commencer…', '', 28153),
(139365, 'frFR', '', 'Par ma carapace… celui-ci a l\’air d\’être écrit dans la langue des Dieux très anciens. Où as-tu dégoté un truc pareil ?', 28153),
(139364, 'frFR', 'Non ! Est-ce que tu as lu à quoi ça servait, au moins ? Mais, euh, garde-le à portée de main. On en aura besoin quand tout ça sera fini.', '', 28153),
(139363, 'frFR', '', 'Voyons voir… Parchemin d\’éternel retour. Ça m\’a l\’air pas mal.', 28153),
(139362, 'frFR', 'Voulez-vous bien m\’aider à rejoindre Alby ? Je suis sûr qu\’il se ronge les sangs à mon sujet.', '', 28153),
(139361, 'frFR', 'Quand vous aurez sauvé les autres, rejoignez-moi sur le promontoire à l\’est pour affronter la maîtresse des marées !', '', 28153),
(139360, 'frFR', '', 'Pfff, ça pourrait me prendre la journée ! Princesse, vous n\’imaginez pas combien de parchemins ce vieux machin a accumulés.', 28153),
(139358, 'frFR', 'On doit rejoindre les autres !', 'On doit rejoindre les autres !', 28153),
(139357, 'frFR', 'Protégez la flotte !', 'Protégez la flotte !', 28153),
(139356, 'frFR', 'Le port de guerre ne doit pas tomber !', 'Le port de guerre ne doit pas tomber !', 28153),
(139355, 'frFR', 'Au nom du roi Rastakhan !', 'Au nom du roi Rastakhan !', 28153),
(139354, 'frFR', 'Ha ! Je savais que j\’en avais un quelque part. Ça va nous camoufler assez longtemps pour espionner les Trolls de sang. Contentez-vous de rester près de moi.', '', 28153),
(139353, 'frFR', 'À l\’époque, j\’aurais pu balayer une nuée de ces lombrics rampants. Ils m\’ont attaqué dans l\’obscurité. J\’ai été submergé ! Leurs ordres semblaient plutôt simples : « Faites vite ! Azshara veut son trophée ! »', '', 28153),
(139351, 'frFR', 'Le moindre détail peut faire la différence, mon seigneur. Toute information est bonne à prendre.', '', 28153),
(139350, 'frFR', 'Les Nagas cherchent quelque chose ici. Quelque chose pour Azshara. Il faut les arrêter, ou au moins leur mettre des bâtons dans les roues.', '', 28153),
(139348, 'frFR', 'Une… une secte a profité de mon incompétence pour… pour prendre le contrôle de cette ville.', '', 28153),
(139347, 'frFR', 'Vous entendez ? C\’est Bwonsamdi, il nous appelle ! À nous l\’éternité !', 'Vous entendez ? C\’est Bwonsamdi, il nous appelle ! À nous l\’éternité !', 28153),
(139346, 'frFR', 'Mon seigneur ! Tout va bien ? Dites-nous tout !', '', 28153),
(139345, 'frFR', 'Brannon !', '', 28153),
(139344, 'frFR', 'La voix… C\’est lui, il nous appelle… On doit obéir !', 'La voix… C\’est lui, il nous appelle… On doit obéir !', 28153),
(139343, 'frFR', 'Qu\’est-ce qui se passe ? J\’étais malade sur ma couche, et maintenant… Où suis-je ?', 'Qu\’est-ce qui se passe ? J\’étais malade sur ma couche, et maintenant… Où suis-je ?', 28153),
(139341, 'frFR', 'Ma vie… pour l\’empereur…', '', 28153),
(139339, 'frFR', 'J\’ai déçu mes sujets. C\’est en raison de mon manque d\’autorité qu\’ils se sont tournés ailleurs.', '', 28153),
(139338, 'frFR', 'Mon oncle m\’a confié l\’administration de ce village pour que j\’assume de plus grandes responsabilités par la suite. Mais… une secte ? Comment peut-on se débarrasser d\’une secte ?', '', 28153),
(139336, 'frFR', 'Un millier de batailles… autant de victoires…', '', 28153),
(139335, 'frFR', 'Nul ne fait taire… le tonnerre…', '', 28153),
(139334, 'frFR', 'Je vous remercie de m\’avoir secouru. Conway et ses hommes ont pris le contrôle du village si rapidement… Je n\’ai rien vu venir.', '', 28153),
(139333, 'frFR', 'La tempête… se dissipe…', '', 28153),
(139329, 'frFR', 'Notre volonté… est celle des dieux…', '', 28153),
(139328, 'frFR', 'Même la pierre… finit par se briser…', '', 28153),
(139327, 'frFR', 'La chair est… faible…', '', 28153),
(139326, 'frFR', 'L\’empire ne sera… jamais… vaincu…', '', 28153),
(139317, 'frFR', 'Vous allez rejoindre le rang de nos esclaves !', '', 28153),
(139316, 'frFR', 'Subissez le courroux de la tempête !', '', 28153),
(139315, 'frFR', 'Ployez devant moi !', '', 28153),
(139314, 'frFR', 'Je suis la puissance incarnée !', '', 28153),
(139312, 'frFR', 'Les Zandalari honoreront leurs engagements… ou mourront !', '', 28153),
(139311, 'frFR', 'Je vais broyer votre crâne entre mes mains !', '', 28153),
(139309, 'frFR', 'Nous rebâtirons notre empire avec vos os !', '', 28153),
(139308, 'frFR', 'Vous nous servirez !', '', 28153),
(139307, 'frFR', 'Brannon, vous n\’êtes qu\’un gamin écervelé. J\’ai passé un marché, vous n\’êtes plus nécessaire à la prospérité de ce village !', 'Brannon, vous n\’êtes qu\’un gamin écervelé. J\’ai passé un marché, vous n\’êtes plus nécessaire à la prospérité de ce village !', 28153),
(139306, 'frFR', 'Nous avons besoin de ressources pour les repousser. Dispersez-vous et trouvez-moi du fer et du bois !', '', 28153),
(139305, 'frFR', '', 'Que sssavez-vous des sssecrets de l\’île ? Parlez !', 28153),
(139304, 'frFR', 'Les mers sssont à jamais notre royaume !', '', 28153),
(139303, 'frFR', 'Nous vous enverrons par le fond !', '', 28153),
(139298, 'frFR', '', 'Bien, je retourne à la caravane. À bientôt, $p !', 28153),
(139295, 'frFR', 'Oui, merci pour l\’aide que vous m\’avez apportée aujourd\’hui. J\’ai désormais une dette envers vous, Kina et $p.', '', 28153),
(139294, 'frFR', '', 'Nous aurions combattu à vos côtés jusqu\’au bout, Sumber.', 28153),
(139293, 'frFR', 'Je suis également content de savoir que Thun\’ka le Flétrisseur a retrouvé sa liberté. Un élémentaire aussi puissant aurait pu nous causer de graves ennuis.', '', 28153),
(139292, 'frFR', 'C\’était donc un chaman qui était la cause de tout ce chaos ? Merci de l\’avoir tué.', '', 28153),
(139291, 'frFR', 'Ha ha ! Prenez ça, bande de vermines de la Horde !', '', 28153),
(139290, 'frFR', 'Mon rituel est presque achevé ! Tu m\’es désormais lié, Thun\’ka le Flétrisseur !', '', 28153),
(139288, 'frFR', '', 'Je ne vous retiens pas ! Pour ce que j\’en ai à faire ! Pf… Non mais il se prend pour qui ?', 28153),
(139287, 'frFR', 'Peuh, qu\’est-ce que t\’en sais ? Restez ici si vous voulez. Nous, on fonce. Je connais cet endroit mieux que personne.', '', 28153),
(139286, 'frFR', 'Ces monstres auront ta carapace ! Ils sont bien plus méchants que les Trolls de sang qu\’on a affrontés lors du dernier pèlerinage.', '', 28153),
(139285, 'frFR', 'Bah ! C\’est pas toi qui commande. Il faut qu\’on donne une bonne leçon à ces bouchers !', '', 28153),
(139284, 'frFR', '', 'Tu devrais plutôt rester ici et réfléchir à un plan avec nous. Les Trolls de sang sont un trop gros morceau pour vous.', 28153),
(139283, 'frFR', 'Kisha, Lashk. On va s\’occuper de ceux qui font du mal à Torga.', '', 28153),
(139282, 'frFR', '', 'C\’est pas trop tôt ! Je croyais qu\’on était les seuls à s\’émouvoir de la mort de Torga.', 28153),
(139281, 'frFR', 'Voyez-vous ça. Les autres se secouent enfin la carapace et daignent nous rejoindre.', '', 28153),
(139250, 'frFR', '|cffffff00Fer +$1i|r', '|cffffff00Fer +$1i|r', 28153),
(139241, 'frFR', 'Continuez le combat !', '', 28153),
(139240, 'frFR', '', 'On forme une sacrée équipe, pas vrai ?', 28153),
(139204, 'frFR', '', 'J\’en ai tué un autre, Sumber ! Ça fait déjà vingt-sept !', 28153),
(139198, 'frFR', '|cffffff00Bois +$1i|r', '|cffffff00Bois +$1i|r', 28153),
(139168, 'frFR', 'Oui… Débattez-vous… Résistez… G\’huun a faim… de votre… souffrance.', '', 28153),
(139167, 'frFR', 'Vous allez… essayer… d\’arrêter G\’huun. Vous allez… échouer… et souffrir.', '', 28153),
(139165, 'frFR', 'Venez.', '', 28153),
(139164, 'frFR', 'Arrêtez.', '', 28153),
(139163, 'frFR', 'L\’atelier est paré à tourner !', '', 28153),
(139162, 'frFR', 'L\’atelier est prêt. Construisez des démolisseurs et montrez à l\’Alliance que ses murs ne peuvent pas nous résister.', '', 28153),
(139097, 'frFR', '$n enduit ses griffes de venin !', '$n enduit ses griffes de venin !', 28153),
(139080, 'frFR', 'Vous ne savez pas ce qui se cache… sous la surface…', '', 28153),
(139079, 'frFR', 'Notre puissance vous brisera !', '', 28153),
(139078, 'frFR', 'Prosternez-vous devant vos nouveaux maîtres !', '', 28153),
(139077, 'frFR', 'Nous devons… régner en maîtres…', '', 28153),
(139073, 'frFR', 'Les tempêtes elles-mêmes entendent mon appel !', '', 28153),
(139072, 'frFR', 'Vous allez le regretter !', '', 28153),
(139071, 'frFR', 'J\’ai plus de pouvoir que vous en aurez jamais !', '', 28153),
(139070, 'frFR', 'Je vous aurai $gprévenu:prévenue; !', '', 28153),
(139065, 'frFR', 'Nos paroles sont empreintes de pouvoir. Nous conquerrons ces terres !', '', 28153),
(138870, 'frFR', '', 'Les habitants de Val-Archer vous doivent une fière chandelle, $c.\n\nAllez vous occuper de mademoiselle Malvoie, on se charge de nettoyer ce qui reste du Sabbat.', 28153),
(138865, 'frFR', '', 'Vous êtes de retour ! Je vous en prie, dites-moi que vous avez réglé son compte à cette matrone.', 28153),
(138864, 'frFR', '', 'Nous n\’avons pas réussi à pénétrer dans la mine depuis que cette énergie a commencé à en sortir.\n\nL\’assemblage maccarbre que vous contrôlez pourrait bien être notre dernier espoir.', 28153),
(138859, 'frFR', '', 'Votre aide nous est très précieuse, $c. La situation semblait désespérée avant votre arrivée.', 28153),
(138853, 'frFR', 'Je vais aller tâter le terrain en ville. Prions pour que la population soit saine et sauve !', '', 28153),
(138852, 'frFR', 'Vous avez réussi à prendre le contrôle de l\’esclave maléformé !', '', 28153),
(138849, 'frFR', 'Disparaissez !', '', 28153),
(138848, 'frFR', '', 'Ça vous plaît, comme ça ? Je me fatigue assez pour vous ?', 28153),
(138847, 'frFR', '', 'Pas trop fatigant ? D\’accord… Et ça, alors ? C\’est assez fatigant comme pèlerinage, vous croyez ?', 28153),
(138841, 'frFR', 'Approchez, $gpetit:petite:r; $pr. Je souhaite m\’entretenir avec vous.', '', 28153),
(138837, 'frFR', '', 'Moi aussi, je vais interroger quelques personnes dans les environs. Retrouvez-moi en ville !', 28153),
(138836, 'frFR', '', 'On peut vraiment compter sur vous, $p. J\’espère que nos chemins se recroiseront sous peu.', 28153),
(138833, 'frFR', 'Nous devons tenir bon.', '', 28153),
(138832, 'frFR', 'Allez, et protégez les habitants de Drustvar, $n !', '', 28153),
(138831, 'frFR', 'Du calme, enfants des mers. Nous devons nous en remettre aux marées pour trouver un remède.', '', 28153),
(138830, 'frFR', '', 'Si vous deviez croiser d\’autres viles sorcières, donnez-leur un bon coup de poing de ma part, $gchampion:championne; !', 28153),
(138829, 'frFR', '', 'Nous nous réjouissons de savoir qu\’il existe encore des $gchampions:championnes; de votre trempe, $n.', 28153),
(138824, 'frFR', '', 'Taji et Kina devraient être rentrés à l\’heure qu\’il est. Ils ont sûrement eu des ennuis.', 28153),
(138823, 'frFR', 'Nous devons avant tout récupérer nos provisions. Il faut qu\’on mange.', '', 28153),
(138822, 'frFR', 'Ô noble mer, prodigue tes bienfaits aux malades et aux opprimés du quai du Trident. Puissions-nous découvrir la source du mal qui nous ronge !', '', 28153),
(138821, 'frFR', 'Si $n n\’avait pas été là, personne ne serait venu vous sauver.', '', 28153),
(138820, 'frFR', 'Continuez comme ça et on passera à trois mois !', '', 28153),
(138819, 'frFR', 'Mais on est des explorateurs !', '', 28153),
(138818, 'frFR', '', 'Mais euh !', 28153),
(138817, 'frFR', 'Oh ! Allez, papy !', '', 28153),
(138816, 'frFR', 'Vous êtes tous punis pour les deux mois à venir !', '', 28153),
(138815, 'frFR', '', 'Oui, monsieur.', 28153),
(138814, 'frFR', 'Oui, papy.', '', 28153),
(138813, 'frFR', 'Oui, papy.', '', 28153),
(138812, 'frFR', 'Petits chenapans ! Je vous avais interdit de partir sans rien dire !', '', 28153),
(138811, 'frFR', 'J\’espère bien ne plus jamais entendre cette maudite chanson !', 'J\’espère bien ne plus jamais entendre cette maudite chanson !', 28153),
(138810, 'frFR', 'Enfin ! Je suis libre !', 'Enfin ! Je suis libre !', 28153),
(138809, 'frFR', 'Rah, bon sang ! Cette chanson va me rester dans la tête toute la journée.', 'Rah, bon sang ! Cette chanson va me rester dans la tête toute la journée.', 28153),
(138808, 'frFR', 'Merci à vous !', 'Merci à vous !', 28153),
(138807, 'frFR', 'La mort… enfin… C\’est à vous… d\’arrêter G\’huun…', '', 28153),
(138804, 'frFR', 'Vous vous croyez de taille à arrêter G\’huun ? C\’est ce qu\’on va voir… dans mon arène !', '', 28153),
(138803, 'frFR', 'Nazesh s\’est montrée pour le moins grossière. Je crains que vous ne deviez lui apprendre la politesse de manière ferme… et définitive. Utilisez le parchemin, ça vous aidera !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138802, 'frFR', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tLe sang |2 $n est |cFFFF0000|Hspell:255582|h[corrompu]|h|r !', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_EARTH.BLP:20|tLe sang |2 $n est |cFFFF0000|Hspell:255582|h[corrompu]|h|r !', 28153),
(138801, 'frFR', '', '|TInterface\\Icons\\SPELL_HOLY_PURIFY.BLP:20|t$n lance |cFFFF0000|Hspell:255577|h[Transfusion]|h|r !', 28153),
(138800, 'frFR', '', '$n recouvre ses mains d\’or.', 28153),
(138799, 'frFR', 'Autrefois, il n\’y avait que des petits Murlocs ici, puis une tempête est arrivée et les Nagas ont envahi la plage. Ils m\’ont pris en premier, j\’ai vraiment honte.', '', 28153),
(138798, 'frFR', 'Libérez mon esprit, s\’il vous plaît !', '', 28153),
(138797, 'frFR', 'J\’ai pas voulu ça ! Enlevez-moi la douleur !', '', 28153),
(138796, 'frFR', 'Faites-moi rejoindre Bwonsamdi, je vous en supplie !', '', 28153),
(138795, 'frFR', 'J\’ai mal, faites que ça s\’arrête !', '', 28153),
(138794, 'frFR', 'S\’il vous plaît, faites cesser ma douleur !', '', 28153),
(138793, 'frFR', 'Je ne réponds plus de rien !', '', 28153),
(138792, 'frFR', 'Pitié, abrégez mes souffrances !', '', 28153),
(138791, 'frFR', '', 'Libérez mon esprit, s\’il vous plaît !', 28153),
(138790, 'frFR', '', 'J\’ai pas voulu ça ! Enlevez-moi la douleur !', 28153),
(138789, 'frFR', '', 'Faites-moi rejoindre Bwonsamdi, je vous en supplie !', 28153),
(138788, 'frFR', '', 'J\’ai mal, faites que ça s\’arrête !', 28153),
(138787, 'frFR', '', 'S\’il vous plaît, faites cesser ma douleur !', 28153),
(138786, 'frFR', '', 'Je ne réponds plus de rien !', 28153),
(138785, 'frFR', '', 'Pitié, abrégez mes souffrances !', 28153),
(138784, 'frFR', '', 'Les éléments me parlent et je vais là où le vent me mène.', 28153),
(138783, 'frFR', 'Comment ces choses ont-elles pu s\’introduire dans mon estomac ?!', 'Comment ces choses ont-elles pu s\’introduire dans mon estomac ?!', 28153),
(138782, 'frFR', 'Je... je ne me sens pas très bien...', 'Je... je ne me sens pas très bien...', 28153),
(138781, 'frFR', 'Ça fait des jours que j\’ai l\’estomac tout barbouillé !', 'Ça fait des jours que j\’ai l\’estomac tout barbouillé !', 28153),
(138779, 'frFR', 'Ces... ces choses étaient à l\’intérieur de moi ?', 'Ces... ces choses étaient à l\’intérieur de moi ?', 28153),
(138776, 'frFR', '', 'Vous feriez mieux de partir, sauf si vous êtes là pour nous filer un coup de main.', 28153),
(138775, 'frFR', '', 'Bienvenue à Val-Archer, $c. Désolée pour la pagaille, mais on a un problème de sorcières sur les bras !', 28153),
(138774, 'frFR', 'J\’ai bien cru que les esprits allaient me tuer ! Merci !', 'J\’ai bien cru que les esprits allaient me tuer ! Merci !', 28153),
(138773, 'frFR', 'Merci. Dès que j\’ai retrouvé mon familier, je déguerpis de cet endroit maudit !', 'Merci. Dès que j\’ai retrouvé mon familier, je déguerpis de cet endroit maudit !', 28153),
(138772, 'frFR', 'Merci !', 'Merci !', 28153),
(138771, 'frFR', 'Je n\’avais jamais vu d\’esprits comme ceux-là. Je m\’éclipse !', 'Je n\’avais jamais vu d\’esprits comme ceux-là. Je m\’éclipse !', 28153),
(138770, 'frFR', 'Merci de m\’avoir sauvé.', 'Merci de m\’avoir sauvée.', 28153),
(138769, 'frFR', 'Merci, $gétranger:étrangère;. J\’ai bien cru que mon heure avait sonné.', 'Merci, $gétranger:étrangère;. J\’ai bien cru que mon heure avait sonné.', 28153),
(138768, 'frFR', 'Je voudrais pas vous déranger, mais j\’ai une demande urgente pour notre $uami:amie;.', '', 28153),
(138767, 'frFR', 'Qui es-tu ? Pas un Troll de sang… sinon les esprits t\’auraient déjà massacré.', '', 28153),
(138766, 'frFR', 'Attendez… Quelque chose vient vers nous.', '', 28153),
(138765, 'frFR', 'Ces ruines, elles sont sacrées pour Bwonsamdi. Les Trolls de sang, ils ne nous suivront pas ici.', '', 28153),
(138762, 'frFR', 'Les quelques machines qu\’il me reste sont à votre disposition.', '', 28153),
(138760, 'frFR', '', 'La Horde se replie à nouveau ? Qu\’est-ce qu\’ils manigancent ?', 28153),
(138759, 'frFR', 'Sylvanas ne doit pas nous échapper. Il faut la capturer si nous voulons gagner cette guerre.', '', 28153),
(138758, 'frFR', 'Vous n\’êtes rien...', '', 28153),
(138757, 'frFR', 'Cette crique appartient à la maîtresssse des marées Nazesh ! Nous allons découvrir les sssecrets cachés de Zuldazar !', '', 28153),
(138756, 'frFR', 'Hé hé. De la chair fraîche.', 'Hé hé. De la chair fraîche.', 28153),
(138755, 'frFR', 'Ne vous inquiétez pas, on va l\’éviter. Je sais où nous planquer le temps de rassembler des informations.', '', 28153),
(138754, 'frFR', 'Il veut parler du bizutage.', '', 28153),
(138753, 'frFR', 'Allez-y et présentez-vous au rapport pour votre… « orientation ». Hé hé hé.', '', 28153),
(138752, 'frFR', 'Ma foi, c\’est vrai. Vous avez apporté vos chapeaux…', '', 28153),
(138751, 'frFR', 'Nous voulons rejoindre les Lamineurs. Nous avons même apporté nos chapeaux.', 'Nous voulons rejoindre les Lamineurs. Nous avons même apporté nos chapeaux.', 28153),
(138749, 'frFR', 'Cet endroit est sacré. Et moi, ma mission, c\’est de le protéger pour l\’éternité.', '', 28153),
(138748, 'frFR', 'Avant, il y avait de nombreux pèlerins qui faisaient halte ici sur le chemin de la Nécropole.\n\nMais ces jours-ci, c\’est tellement calme… C\’est mauvais signe. Très mauvais signe.', '', 28153),
(138747, 'frFR', 'Ce sanctuaire, je le garde depuis toujours. Et je le défendrai jusqu\’à ce qu\’il tombe en ruines.', '', 28153),
(138746, 'frFR', 'Tous ceux qui vont à la Nécropole, ils sont les bienvenus ici.', '', 28153),
(138745, 'frFR', 'Au nom de Bwonsamdi, j\’offre un répit aux voyageurs qui viennent jusqu\’à son temple.', '', 28153),
(138744, 'frFR', 'Parfait. Allons proposer nos services au recruteur.', '', 28153),
(138743, 'frFR', 'Mettez donc ça sur votre tête. Aucun marin digne de ce nom ne se promène découvert.', '', 28153),
(138742, 'frFR', 'Encore quelques minutes, Rosaline. À l\’aide de mes harpons améliorés, vous ne ferez qu\’une bouchée de vos proies !', '', 28153),
(138741, 'frFR', '', 'Okri, ça en est où, pour le matériel ?! Je veux retourner à la mer dès que possible. On perd du temps !', 28153),
(138740, 'frFR', 'Ouais ? Vous voulez quoi ?', 'Ouais ? Vous voulez quoi ?', 28153),
(138739, 'frFR', 'Je vais donc regagner Boralus les mains vides. Retrouvez-moi là-bas quand vous aurez le parchemin et nous discuterons de vos gages.', '', 28153),
(138738, 'frFR', 'Ouvrez grand vos oreilles, c\’est important : le parchemin que vous cherchez porte un sceau de cire verte. VERTE, c\’est clair ?', '', 28153),
(138737, 'frFR', 'L\’homme que vous cherchez s\’appelle Carentan. Il tient une boutique au premier étage d\’une maison du côté sud de la ville.', '', 28153),
(138734, 'frFR', 'Pourquoi tu me mords, hein ? J\’ai que la peau sur les os, moi.', '', 28153),
(138733, 'frFR', 'C\’est la bête que tu dois bouffer, maudit serpent sans cervelle !', '', 28153),
(138732, 'frFR', 'J\’aime les bestioles combatives, mais vaut mieux garder ça pour les Sephraks !', '', 28153),
(138731, 'frFR', 'Ha ! J\’ai bien failli me faire avoir cette fois.', '', 28153),
(138730, 'frFR', 'Rezan cherche à |TInterface\\Icons\\ABILITY_MOUNT_FOSSILIZEDRAPTOR.BLP:20|t|cFFFF0000|Hspell:255421|h[dévorer]|h|r $n !', '', 28153),
(138729, 'frFR', 'Le capitaine Gulnaku va le payer cher.', '', 28153),
(138728, 'frFR', 'Merci de m\’avoir libéré... En échange, j\’vais vous laisser la vie sauve.', '', 28153),
(138725, 'frFR', 'Regardez où vous creusez ! J\’essaie de roupiller, moi !', 'Regardez où vous creusez ! J\’essaie de roupiller, moi !', 28153),
(138724, 'frFR', 'Les esprits des environs ne resteront pas les bras croisés pendant que vous saccagez leur sanctuaire...', '', 28153),
(138723, 'frFR', 'À mon humble avis, ce serait une erreur de bombarder ces ossements !', '', 28153),
(138722, 'frFR', 'J\’ai interrogé de nombreux Trolls à propos de Xibala, et chaque fois, ils m\’ont raconté une histoire différente, quelle que soit la méthode employée pour les faire parler.\n\nCertains prétendent qu\’il avait le pouvoir de faire pourrir ses victimes de l\’intérieur.\n\nD\’autres qu\’il suffisait de poser les yeux sur lui pour se changer en squelette ambulant.\n\nOu encore qu\’il surgissait des ombres à la faveur de la nuit pour dévorer les gens pendant leur sommeil.\n\nOn dit également qu\’il guettait les voyageurs en bord de route et leur faisait cracher leur sang.\n\nPas étonnant que les autochtones préfèrent se tenir à l\’écart !', '', 28153),
(138721, 'frFR', 'Cela faisait une éternité que je n\’avais pas revu cet endroit. Déjà à l\’époque, les autochtones préféraient passer au large...\n\nLes lieux sont hantés par des esprits malins, $n. Mieux vaut ne pas les déranger.', '', 28153),
(138717, 'frFR', 'C\’est dangereux de se promener dans les allées de Zem\’lan, petit rat. Choppe-moi ça, Kiffa !', 'C\’est dangereux de se promener dans les allées de Zem\’lan, petit rat. Choppe-moi ça, Kiffa !', 28153),
(138716, 'frFR', 'La Horde… me vengera…', '', 28153),
(138715, 'frFR', 'Ce site appartient au Reliquaire. L\’Alliance n\’est pas la bienvenue ici !', '', 28153),
(138709, 'frFR', '', 'Des dommages collatéraux ne sont pas exclus, mais je suis sûre qu\’on arrivera à recoller les morceaux. Par contre, il va falloir songer à recruter d\’autres assistants...', 28153),
(138707, 'frFR', 'Hé, Zalnon\’mak, ton chapeau, il me va comme un gant. J\’crois que je vais le garder !', '', 28153),
(138706, 'frFR', 'Qui veut trinquer avec moi ?', '', 28153),
(138705, 'frFR', 'Pourquoi vous trimez tous si dur ? Vous savez qu\’on est immortels, hein ?', '', 28153),
(138704, 'frFR', 'Hé, Senjilak ! Xunanji te pique des trucs dès que t\’as le dos tourné !', '', 28153),
(138703, 'frFR', 'Hé, Segazea. Ton serviteur pue comme c\’est pas permis. Vire-le-moi d\’ici !', '', 28153),
(138702, 'frFR', 'Xulai, t\’es le porteur le plus lent que je connaisse !', '', 28153),
(138701, 'frFR', 'Z\’avez soif ? Dommage pour vous !', '', 28153),
(138700, 'frFR', 'Secouez-vous, bande de flemmards ! Il me faut plus de grog !', '', 28153),
(138699, 'frFR', '$n a pris la mine des Sèches-Moustaches !', '$n a pris la mine des Sèches-Moustaches !', 28153),
(138698, 'frFR', '', 'Disparais plus jamais comme ça, compris ? Allez, il faut se remuer. On a du pain sur la planche.', 28153),
(138691, 'frFR', 'Je… Du calme, mes amis ! Nous faisons tout ce qui est en notre pouvoir. Nous allons trouver un remède, et la cause du mal !', '', 28153),
(138690, 'frFR', '', 'Vous devez nous aider, Therold ! Il nous faut des réponses ! Il nous faut un remède !', 28153),
(138689, 'frFR', 'Quelle est la cause de cette maladie ?!', '', 28153),
(138688, 'frFR', '', 'Nos enfants tombent tous malades !', 28153),
(138687, 'frFR', 'Revenez. Vous m\’devez une revanche…', 'Revenez. Vous m\’devez une revanche…', 28153),
(138686, 'frFR', 'J\’ai picolé toute la journée en prévision de ça…', 'J\’ai picolé toute la journée en prévision de ça…', 28153),
(138679, 'frFR', 'Gulnaku, il va pas aimer ça.', 'Gulnaku, il va pas aimer ça.', 28153),
(138678, 'frFR', 'Approchez pas de ma carte au trésor !', 'Approchez pas de ma carte au trésor !', 28153),
(138676, 'frFR', 'Bénéficiez d\’une réduction sur votre premier achat en échange d\’une tête de Vulpérin !', '', 28153),
(138675, 'frFR', 'Un grog par jour, ça éloigne les vautours !', '', 28153),
(138674, 'frFR', 'Mieux vaut avoir trop de couvre-œil que pas assez !', '', 28153),
(138673, 'frFR', 'Ressemblez à Zem\’lan en personne avec les nouveaux accessoires de Glok\’om !', '', 28153),
(138672, 'frFR', 'Yoksa, c\’est le roi du mojo ! Potions toutes fraîches du jour !', '', 28153),
(138671, 'frFR', 'Sabres d\’abordage flambant neufs ! Y a pas plus tranchant !', '', 28153),
(138670, 'frFR', 'Offrez-vous un tigre pour terrifier vos ennemis !', '', 28153),
(138669, 'frFR', 'Steaks de Vulpérin ! Cuits à la demande !', '', 28153),
(138668, 'frFR', 'C\’est les soldes sur les baffes jusqu\’à ce soir...', 'C\’est les soldes sur les baffes jusqu\’à ce soir...', 28153),
(138666, 'frFR', '', 'J\’arriverai bien à trouver la sortie toute seule. Faites attention à vous.', 28153),
(138664, 'frFR', 'Oubliez pas de faire le ménage avant de partir.', 'Oubliez pas de faire le ménage avant de partir.', 28153),
(138663, 'frFR', 'Posez-vous donc dans l\’auberge… définitivement !', 'Posez-vous donc dans l\’auberge… définitivement !', 28153),
(138662, 'frFR', '\‘Lut, $c. On a besoin de votre aide pour régler un petit problème.', '', 28153),
(138661, 'frFR', 'On est à jamais liés par la volonté de Zem\’lan.', 'On est à jamais liés par la volonté de Zem\’lan.', 28153),
(138660, 'frFR', 'J\’ai tout donné pour protéger mon équipage. Z\’irez pas plus loin !', 'J\’ai tout donné pour protéger mon équipage. Z\’irez pas plus loin !', 28153),
(138659, 'frFR', 'On revient d\’entre les morts, prêts au combat.', 'On revient d\’entre les morts, prêts au combat.', 28153),
(138658, 'frFR', 'Je vous ai pas déjà réglé votre compte, à vous ? Ou c\’était l\’inverse ?', 'Je vous ai pas déjà réglé votre compte, à vous ? Ou c\’était l\’inverse ?', 28153),
(138655, 'frFR', 'Je vais me repaître de ta chair et offrir ton âme à mon maître !', '', 28153),
(138652, 'frFR', 'J\’arracherai la chair de vos os !', '', 28153),
(138651, 'frFR', 'Vous êtes habile pour une créature terrestre… mais il est temps d\’en finir !', '', 28153),
(138650, 'frFR', 'Vous pouvez bien courir, mauviette. J\’ai toute l\’éternité pour vous retrouver.', 'Vous pouvez bien courir, mauviette. J\’ai toute l\’éternité pour vous retrouver.', 28153),
(138649, 'frFR', 'Ce trésor, personne me le prendra ! Ni vous, ni Zem\’lan, ni personne !', 'Ce trésor, personne me le prendra ! Ni vous, ni Zem\’lan, ni personne !', 28153),
(138644, 'frFR', 'L\’avènement de notre empire marquera votre extinction !', 'L\’avènement de notre empire marquera votre extinction !', 28153),
(138641, 'frFR', 'Votre mort servira d\’exemple aux autres !', 'Votre mort servira d\’exemple aux autres !', 28153),
(138634, 'frFR', 'Vous en faites pas, $PR. Je vous veux pas de mal.\n\nC\’est Zem\’lan qui m\’a fait ça. On y est tous passés, de gré ou de force.\n\nRegardez-moi…\n\n<Guntha l\’Affable pousse un long soupir.>\n\nJe vous sers un verre ?', '', 28153),
(138633, 'frFR', 'Pour survivre en Vol\’dun, faut regarder la mort dans les yeux... sans jamais ciller.', '', 28153),
(138631, 'frFR', 'Pas de corps, pas d\’or…', 'Vot\’ trésor… Il est à moi maintenant.', 28153),
(138628, 'frFR', 'La malédiction, elle nous rend forts !', 'J\’ai tout sacrifié pour Zem\’lan.', 28153),
(138627, 'frFR', 'Les vivants, Zem\’lan, il les supporte plus.', 'Si vous faites pas partie de l\’équipage, votre sort est scellé !', 28153),
(138625, 'frFR', 'Ce port, ça fait d\’innombrables années que je le défends.', 'C\’est not\’ port !', 28153),
(138624, 'frFR', 'Faites attention à vous ! Les Sephraks, il ne faut pas les sous-estimer…', '', 28153),
(138623, 'frFR', '', 'Ça y est ! Merci pour votre aide.', 28153),
(138622, 'frFR', '', 'J\’y suis presque...', 28153),
(138621, 'frFR', '', 'Ah, sans ces cochonneries, je vais enfin pouvoir atteindre les vraies reliques. Ce ne sera plus très long.', 28153),
(138620, 'frFR', '', 'Quant à cette collection d\’ossements, elle doit appartenir à Birch, à en juger par les marques de dents.', 28153),
(138619, 'frFR', '', 'Un « authentique prototype Tournemèche ». Un beau gâchis de métal, oui. Allez, poubelle !', 28153),
(138618, 'frFR', '', 'Cette caisse renferme certaines de nos plus précieuses trouvailles. $c, surveillez mes arrières pendant que je récupère tout ce que je peux.', 28153),
(138615, 'frFR', 'Jamais nous n\’abandonnerons le temple.', '', 28153),
(138589, 'frFR', 'Tant que ce temple résistera, vous trouverez toujours un refuge entre ses murs.', '', 28153),
(138568, 'frFR', '', 'Oooh, toi... Quand j\’aurai repris mon souffle, tu vas en prendre pour ton grade !', 28153),
(138567, 'frFR', 'Hé ! Je ne suis pas un chien, je te signale ! Et d\’abord, comment fais-tu pour courir avec les moignons qui te servent de jambes ? Je pensais que tu te contenterais de rouler dans le sens de la pente.', '', 28153),
(138566, 'frFR', '', 'Une ouverture ! Je vais te semer, Birch ! T\’as beau avoir du sang de chien, tu me rattraperas pas !', 28153),
(138556, 'frFR', 'L\’Alliance a pris le contrôle de la cour de Stromgarde !', 'L\’Alliance a pris le contrôle de la cour de Stromgarde !', 28153),
(138555, 'frFR', '$n a pris la cour de Stromgarde !', '$n a pris la cour de Stromgarde !', 28153),
(138553, 'frFR', '', 'C\’est une embuscade ! Défendez les villageois !', 28153),
(138552, 'frFR', '', 'Venez, $n. Nous partons pour la route du Haut-Col.', 28153),
(138551, 'frFR', 'Comme vous le souhaitez, madame. Soldats, en avant !', '', 28153),
(138550, 'frFR', '', 'Pas un mot de plus, maréchal. Notre camarade m\’accompagnera pour assurer ma sécurité.', 28153),
(138549, 'frFR', 'Mais madame, il serait préférable que…', '', 28153),
(138548, 'frFR', '', 'Maréchal, gagnez la Ferté-d\’Arom avec vos hommes. Je vous y rejoindrai après un bref détour.', 28153),
(138547, 'frFR', 'L\’Alliance a pris le contrôle de la passe de Vaillehuche !', 'L\’Alliance a pris le contrôle de la passe de Vaillehuche !', 28153),
(138546, 'frFR', '$n a pris la passe de Vaillehuche !', '$n a pris la passe de Vaillehuche !', 28153),
(138545, 'frFR', 'À qui le tour ?', '', 28153),
(138544, 'frFR', 'Bienvenue dans l\’équipage des éternels damnés, second.', '', 28153),
(138543, 'frFR', 'Raaagh !', '', 28153),
(138542, 'frFR', 'Second Jamboya, reviens-nous !', '', 28153),
(138540, 'frFR', 'Approchez et acceptez mon présent. Rejoignez mon équipage pour l\’éternité !', '', 28153),
(138539, 'frFR', 'On est chez nous, ici ! On fera tout ce qu\’il faut pour défendre cet endroit.', '', 28153),
(138538, 'frFR', 'JAMAIS !', 'JAMAIS !', 28153),
(138537, 'frFR', 'Les Sephraks croient qu\’on va se laisser tuer. Qu\’est-ce que vous en dites ?', '', 28153),
(138535, 'frFR', 'Je resterai pas mort bien longtemps… On se reverra bientôt, Jamboya…', '', 28153),
(138534, 'frFR', 'Une mutinerie de mon propre second ? Tu vas passer sous la quille !', '', 28153),
(138533, 'frFR', 'Ho ! Y a des marins d\’eau douce qui osent me défier ?', '', 28153),
(138532, 'frFR', '', 'La Matriarche… vous fauchera…', 28153),
(138531, 'frFR', '', 'Toute résistance est futile. Le Sabbat malecarde dominera Kul Tiras !', 28153),
(138530, 'frFR', 'Nous protégerons dame Malvoie ! Éliminez leur chef !', '', 28153),
(138529, 'frFR', '', 'La Matriarche vous aura, Lucille Malvoie !', 28153),
(138528, 'frFR', 'Bon sang, mais qu\’est-ce que c\’est ?', '', 28153),
(138527, 'frFR', 'Les pièges ne les ralentissent plus. Là, il y en a d\’autres !', '', 28153),
(138526, 'frFR', 'Reprenez votre calme, Kal\’dran. Nous pouvons encore vaincre Zardrax.', 'Reprenez votre calme, Kal\’dran. Nous pouvons encore vaincre Zardrax.', 28153),
(138521, 'frFR', '', 'Merci, connétable. Allons-y, $c, voulez-vous ?', 28153),
(138520, 'frFR', 'Mademoiselle Malvoie, vous êtes libre… avec mes plus plates excuses…', '', 28153),
(138519, 'frFR', 'Votre attention s\’il vous plaît ! Il a été établi qu\’une autre sorcière est en réalité à l\’origine de la malédiction qui frappe Val-Archer !', '', 28153),
(138518, 'frFR', '', 'Voilà qui est mieux. Maintenant…', 28153),
(138517, 'frFR', 'Bah, j\’en trouverai une autre ! Les Trolls de sang, c\’est pas ça qui manque et vous, vous êtes $Ufoutu:foutue; !', '', 28153),
(138516, 'frFR', 'Non ! Nana\’kwug ! Je vais devoir…', '', 28153),
(138515, 'frFR', 'Ha ha… Pas la peine de vous fatiguer. Mon pouvoir, il est trop fort pour vous !', '', 28153),
(138514, 'frFR', 'Vous croyez p\’têt que ça va changer quoi que ce soit ? Le pouvoir du Dieu du sang, il coule dans mes veines, et vous pouvez rien contre ça !', '', 28153),
(138513, 'frFR', 'Mon pouvoir… il me quitte ! Ha ha… Vous devez être vraiment $Udésespéré:désespérée; si vous croyez que ça va marcher !', '', 28153),
(138509, 'frFR', 'Attention ! L\’ennemi surgit des bois !', '', 28153),
(138502, 'frFR', 'Là ! C\’est tout ce que j\’peux vous donner sans y laisser un bout de mon âme. Allez vite me cramer ces tas de squelettes !', '', 28153),
(138501, 'frFR', 'Concentrez-vous. J\’vais partager mon mojo de feu avec vous…', '', 28153),
(138500, 'frFR', 'Je suis prêt à recevoir votre mojo de feu pour détruire les tertres funéraires.', 'Je suis prête à recevoir votre mojo de feu pour détruire les tertres funéraires.', 28153),
(138499, 'frFR', '', 'Il ne nous reste donc plus qu\’à affronter le Sabbat nous-mêmes. Et je sais comment nous allons procéder.', 28153),
(138498, 'frFR', 'Il… il a été capturé, madame. Nous cherchions un moyen de le libérer quand nous avons eu vent de… ce procès.', '', 28153),
(138497, 'frFR', '', 'Et mon père ? Que fait-il pour combattre cette incursion ?', 28153),
(138496, 'frFR', 'Son influence prédomine au-delà des montagnes. Nous ne sommes plus qu\’une poignée à défendre la Ferté-d\’Arom.', '', 28153),
(138495, 'frFR', 'L\’heure est grave, madame. Le Sabbat a étendu son emprise sur toute la région de Drustvar.', '', 28153),
(138494, 'frFR', '', 'Maréchal ! Que savez-vous de ce Sabbat ? Qu\’arrive-t-il donc à nos terres ?', 28153),
(138449, 'frFR', '', 'Ouah ! Regardez un peu à quoi ressemblait le vieux Zem\’lan !', 28153),
(138448, 'frFR', '', 'Zem\’lan était un sale type, hein ?', 28153),
(138439, 'frFR', 'Prends les idoles et rassemble l\’équipage.', '', 28153),
(138438, 'frFR', 'Les Sephraks nous chasseront pas de chez nous. Ni aujourd\’hui, ni jamais !', '', 28153),
(138437, 'frFR', 'Je… je… Y doit y avoir un autre moyen, capitaine. L\’équipage…', '', 28153),
(138436, 'frFR', 'C\’est un piège, c\’est ça ?', 'Vous m\’avez sauvé la vie. J\’ai bien failli y rester !', 28153),
(138435, 'frFR', 'On fera les présentations plus tard. Pas question de passer une minute de plus dans cette mine.', 'On fera les présentations plus tard. Pas question de passer une minute de plus dans cette mine.', 28153),
(138434, 'frFR', 'On discute pas ! Tout le monde à l\’autel. Et vite !', '', 28153),
(138433, 'frFR', 'Quelle chance que vous passiez par là !', 'Quelle chance que vous passiez par là !', 28153),
(138432, 'frFR', 'J\’ignore qui vous êtes ou ce que vous voulez, mais merci.', 'J\’ignore qui vous êtes ou ce que vous voulez, mais merci.', 28153),
(138431, 'frFR', 'Vous m\’avez sauvé la vie. J\’ai bien failli y rester !', 'Vous m\’avez sauvé la vie. J\’ai bien failli y rester !', 28153),
(138430, 'frFR', 'Je n\’ai plus la force de soulever une pioche, mais mes jambes peuvent m\’emmener hors d\’ici !', 'J\’ignore qui vous êtes ou ce que vous voulez, mais merci.', 28153),
(138429, 'frFR', 'Maudits sables ! Maudits serpents ! Le port de Zem\’lan est à MOI !', '', 28153),
(138428, 'frFR', 'J\’ai une dette envers vous, $uétranger:étrangère;.', 'J\’ai une dette envers vous, $uétranger:étrangère;.', 28153),
(138427, 'frFR', 'Ils sont trop nombreux, capitaine ! Faut qu\’on se replie ou tout l\’équipage sera tué.', '', 28153),
(138426, 'frFR', 'Taillez ces serpents en rondelles ! Pas de quartier !', '', 28153),
(138373, 'frFR', 'Espérons que je cours plus vite que ces hors-la-loi !', '', 28153),
(138316, 'frFR', 'Merci, $c. Attendons d\’être en sûreté pour discuter.', '', 28153),
(138288, 'frFR', 'Pas de repli ! Ils combattent les Sephraks, ou je les tue.', '', 28153),
(138282, 'frFR', 'Rameutez l\’équipage. Je veux voir tout le monde, même ivre, à la porte principale.', '', 28153),
(138281, 'frFR', 'Personne m\’en chassera, ça jamais !', '', 28153),
(138280, 'frFR', 'Alors, ils sont aussi idiots que les autres ! C\’est le port de Zem\’lan ici ! MON port !', '', 28153),
(138279, 'frFR', 'Capitaine Zem\’lan, l\’armée sephrak approche ! J\’en ai jamais vu autant !', '', 28153),
(138264, 'frFR', 'Ingénieur de vol Krazzle, à votre service !', '', 28153),
(138247, 'frFR', 'Alors, dégagez de mon port ! Allez crever dans les dunes.', '', 28153),
(138242, 'frFR', 'Et comme z\’avez rien que les loques que vous portez sur le dos, z\’êtes déjà morts en ce qui m\’concerne.', '', 28153),
(138240, 'frFR', 'Aucun de vous mettra un pied sur mes bateaux, sauf ceux qui me graisseront la patte avec de l\’or.', '', 28153),
(138238, 'frFR', 'Eh bien, restez-y, bande de crève-la-faim !', '', 28153),
(138235, 'frFR', 'Si vous ne nous laissez pas monter à bord, on va tous y rester !', 'Si vous ne nous laissez pas monter à bord, on va tous y rester !', 28153),
(138234, 'frFR', 'Les réfugiés, dégagez le passage ! Les pirates d\’abord !', '', 28153),
(138233, 'frFR', 'Pitié, Zem\’lan ! Si on embarque pas, les Sephraks, ils vont nous massacrer !', 'Pitié, Zem\’lan ! Si on embarque pas, les Sephraks, ils vont nous massacrer !', 28153),
(138232, 'frFR', 'On vous laissera monter à bord tant qu\’il restera de la place.', '', 28153),
(138224, 'frFR', '', 'Vous tombez vraiment mal.\n\nQue venez-vous faire ici ?', 28153),
(138214, 'frFR', 'Ah. Ça doit venir de moi, alors.', '', 28153),
(138213, 'frFR', '', 'Pas le moins du monde.', 28153),
(138212, 'frFR', 'Nan.', '', 28153),
(138211, 'frFR', '', 'Non.', 28153),
(138210, 'frFR', 'Quand même, vous ne trouvez pas ça un peu exagéré ? Les Sephraks sont morts par dizaines pour avoir tué une poignée d\’entre nous seulement.', '', 28153),
(138209, 'frFR', 'Beau travail, même si vous avez tendance à en faire un peu trop à mon goût.', '', 28153),
(138208, 'frFR', '', 'Ha ha ha, prodigieux ! Et vous avez survécu, avec ça !', 28153),
(138203, 'frFR', 'Sortez le zeppelin !', '', 28153),
(138202, 'frFR', 'Vous avez encore réussi ! Bien joué !', '', 28153),
(138200, 'frFR', 'Les Troggs m\’ont suivi jusqu\’ici. Tout est ma faute ! Je vous en supplie, aidez-moi, $n !', '', 28153),
(138123, 'frFR', 'Qui eût cru qu\’un Tortollan pourrait se sentir aussi libre ?', '', 28153),
(138122, 'frFR', 'Quel plaisir de sentir le vent glisser sur mes écailles !', '', 28153),
(138121, 'frFR', 'Je vooooole !', '', 28153),
(138120, 'frFR', 'Tu t\’en sors très bien, papa !', '', 28153),
(138118, 'frFR', 'RETIENS-LE, RETIENS-LE, RETIENS-LE !', '', 28153),
(138075, 'frFR', 'Est-ce que vous voulez bien m\’aider à examiner les chevaux ? Je n\’accepterai que la monture idéale !', '', 28153),
(138074, 'frFR', 'Certains de ces fainéants n\’hésitent pas à se servir en douce. Si vous ne trouvez pas de grog, fouillez les employés.', '', 28153),
(138073, 'frFR', 'J\’entrepose mes réserves sous l\’eau. Ça permet de les garder au frais.', '', 28153),
(138072, 'frFR', 'Vous êtes plutôt réglo pour un être de chair, $pr. Faites-moi signe si vous avez soif.', '', 28153),
(138071, 'frFR', '', 'HAH !', 28153),
(138070, 'frFR', '', 'Estime-toi heureux que je puisse pas cogner plus haut ! T\’avise pas de nier, c\’est toi qui as déclenché le piège !', 28153),
(138069, 'frFR', 'Aïeuh ! Mon tibia !', '', 28153),
(138068, 'frFR', 'Mes bêtises ? MES BÊTISES ? Il me semble que c\’est TOI qui l\’as déclenché, insupportable nab...', '', 28153),
(138067, 'frFR', '', '... pour réparer tes bêtises !', 28153),
(138066, 'frFR', '', 'Alors, filons d\’ici et trouvons quelqu\’un avec qui faire affaire. Je suis affamée, moi.', 28153),
(138065, 'frFR', '', 'Et puis, bon... j\’ai fauché assez de gemmes et de bijoux en chemin pour couvrir nos frais pendant un mois.', 28153),
(138064, 'frFR', '', 'Ouais, ouais, je vous aime tous, moi aussi.', 28153),
(138061, 'frFR', '', 'Il n\’y a plus rien pour nous ici, les gars. Allez, on remballe et on file d\’ici.', 28153),
(138060, 'frFR', '', 'Je ne peux pas dire que ça me surprenne. Rien ne nous garantissait de lever la malédiction.', 28153),
(138059, 'frFR', 'Vous voulez voir comment on fait nos saucisses ?', '', 28153),
(138058, 'frFR', 'Qui aura votre couenne ? Moi ! Ha ha !', '', 28153),
(138057, 'frFR', 'Vous ferez un délicieux bacon.', '', 28153),
(138056, 'frFR', 'Je vais vous hacher menu…', '', 28153),
(138055, 'frFR', 'Vous êtes tous… perdus…', '', 28153),
(138054, 'frFR', '', 'Puissent les vents vous être favorables, $p... et prenez garde à ne pas devenir comme eux !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(138053, 'frFR', '', 'Je vais retourner discrètement à la caravane et faire en sorte que tout le monde soit prêt à piller cet endroit dès que vous aurez levé la malédiction.', 28153),
(138052, 'frFR', '', 'Voici les notes que j\’ai trouvées. Il vous faut juste quelques bricoles supplémentaires pour accomplir le rituel.', 28153),
(138051, 'frFR', 'Nous vous sommes très reconnaissants d\’avoir sauvé notre peau, $c. Je parie que tous ces conflits contre l\’occulte vous ont ouvert l\’appétit.\n\nVous voulez des saucisses ?', '', 28153),
(138050, 'frFR', 'Profitez de la fête. Chevauchez ! Mangez ! Buvez ! Je ne pourrai jamais assez vous remercier.', '', 28153),
(138049, 'frFR', 'Vous avez non seulement sauvé mon fils, mais aussi mon festival ! Ce jour restera dans les mémoires pendant des années !', '', 28153),
(138048, 'frFR', '', 'Vous cherchez à becqueter ou quoi ?', 28153),
(138047, 'frFR', 'Revitalisation', 'Revitalisation', 28153),
(138046, 'frFR', '', 'Je vais rester ici pendant que vous cherchez les autres idoles. Revenez me voir quand vous les aurez toutes.', 28153),
(138045, 'frFR', '', 'Et là, l\’une des idoles ! Récupérez-la pour moi, vous voulez bien ?', 28153),
(138044, 'frFR', '', 'On dirait que c\’était la salle du trône de Zem\’lan. Visez-moi tous ces trésors !', 28153),
(138042, 'frFR', 'Reprenez vos positions ! Ne faiblissez pas !', '', 28153),
(138040, 'frFR', '', 'Meeki n\’aura sûrement pas survécu. Fuyez Zem\’lan tant que vous le pouvez encore.', 28153),
(138039, 'frFR', '', 'Vous êtes un bon gros ange comme je les aime, $pr ! Merci !', 28153),
(138038, 'frFR', 'Ils ont emmené Ahna vers le sud, mais moi, je me taille d\’ici !', '', 28153),
(138037, 'frFR', 'Je dois regagner mon temple le temps de reprendre des forces. Je vous attendrai là-bas.', '', 28153),
(138036, 'frFR', 'Me voilà enfin libre.', '', 28153),
(138035, 'frFR', 'Reviens-moi vite, Norah.', '', 28153),
(138034, 'frFR', '', 'Si nous partons maintenant, nous mourrons de faim dans les dunes.', 28153),
(138033, 'frFR', '', 'Non, c\’est impossible. Et tu le sais parfaitement.', 28153),
(138032, 'frFR', 'Rien ne t\’oblige à y aller, Norah. Nous pouvons plier bagage et quitter Zem\’lan.', '', 28153),
(138031, 'frFR', '', 'Veille sur cette caravane en mon absence, Viggy.', 28153),
(138029, 'frFR', 'Je suis parti longtemps. J\’espère que j\’ai toujours des amis dans le coin.', '', 28153),
(138028, 'frFR', 'Une fois que vous aurez la preuve que la compagnie Corsandre vend des armes à ces pendards, retrouvez-moi sur la colline près de la porte principale.', '', 28153),
(138026, 'frFR', 'Très bien, j\’ai vos… jambes. Et maintenant ?', 'Très bien, j\’ai vos… jambes. Et maintenant ?', 28153),
(138025, 'frFR', 'Ce festival va être le plus palpitant qu\’on ait vu depuis des années ! Sautez sur Cooper et donnez une bonne tripotée à ces Troggs. Vous verrez, il fait des merveilles au combat !', '', 28153),
(138024, 'frFR', 'Havrebrune vous doit énormément, $c.\n\nJ\’espère sincèrement que nous pourrons vous rendre la pareille.', '', 28153),
(138023, 'frFR', 'Cooper et vous formez une excellente équipe ! N\’hésitez pas à le monter pour vous promener dans le domaine.', '', 28153),
(138021, 'frFR', 'Si la plupart ignorent ce que vous avez fait pour eux, moi, je ne l\’oublierai jamais.', '', 28153),
(138020, 'frFR', '', 'Stupide créature ! Vous osez me défier ici, dans mon domaine ?', 28153),
(138019, 'frFR', '', 'Personne ne vous entendra crier !', 28153),
(138018, 'frFR', 'Place à notre $ginvité:invitée; d\’honneur, $gmonseigneur:dame; $n !', '', 28153),
(138017, 'frFR', 'Permettez-moi d\’annoncer l\’arrivée de $gmonseigneur:dame; $n !', '', 28153),
(138016, 'frFR', 'C\’est un honneur pour moi d\’accueillir $gmonseigneur:dame; $n au domaine Norwington !', '', 28153),
(138015, 'frFR', '', 'Moi, c\’est Jane. J\’étais mercenaire à bord d\’un navire marchand jusqu\’au jour où les sirènes nous ont envoyés par le fond.$B$BCes gens m\’ont repêchée dans l\’estuaire, et m\’ont donné un nouveau nom, et depuis, on forme une famille.$B$BIls peuvent avoir de drôles de manières, mais ils sont braves et honnêtes. Pour certains d\’entre eux, ce naufrage a été l\’occasion de prendre un nouveau départ, tandis que d\’autres se contentent de survivre en attendant de pouvoir rentrer chez eux.', 28153),
(138014, 'frFR', 'Xenxuju, il m\’a fait boire le calice de tonnerre. Bientôt, grâce à lui, on ne fera tous qu\’un avec Akunda !', '', 28153),
(138013, 'frFR', '', 'Kel\’vax, il a suffisamment d\’offrandes… pour vous tuer tous…', 28153),
(138012, 'frFR', '', 'Une nouvelle offrande pour Kel\’vax !', 28153),
(138009, 'frFR', 'N-n-ne les effrayez pas, Norah. N-n-nous avons besoin de leur aide.', 'N-n-ne les effrayez pas, Norah. N-n-nous avons besoin de leur aide.', 28153),
(138008, 'frFR', 'Dites-moi, $uinconnu:inconnue;. Connaissez-vous la légende de Zem\’lan ?', 'Dites-moi, $uinconnu:inconnue;. Connaissez-vous la légende de Zem\’lan ?', 28153),
(137999, 'frFR', 'Je crois que je vais aller par là. Je, euh… verrai mieux pour lire. Bonne chance !', '', 28153),
(137997, 'frFR', '<Fouiller le sac à dos.>', '<Fouiller le sac à dos.>', 28153),
(137993, 'frFR', '<Il s\’agit d\’un sac à dos d\’enfant. Un badge « Explorateur en herbe » est attaché au dos.>', '', 28153),
(137988, 'frFR', 'Je vais juste récupérer un dernier trésor avant de partir…', 'Je vais juste récupérer un dernier trésor avant de partir…', 28153),
(137987, 'frFR', 'Merci. Comptez sur moi pour pas moisir ici.', 'Merci. Comptez sur moi pour pas moisir ici.', 28153),
(137986, 'frFR', 'J\’ai commis une terrible erreur.', 'J\’ai commis une terrible erreur.', 28153),
(137985, 'frFR', 'Vous avez vu leurs monstres de compagnie ? Cet endroit est un cauchemar.', 'Vous avez vu leurs monstres de compagnie ? Cet endroit est un cauchemar.', 28153),
(137984, 'frFR', 'Merci, $pr ! Je n\’aurais pas tenu beaucoup plus longtemps.', 'Merci, $pr ! Je n\’aurais pas tenu beaucoup plus longtemps.', 28153),
(137983, 'frFR', 'J\’ai une dette envers vous.', 'J\’ai une dette envers vous.', 28153),
(137982, 'frFR', 'Je suis le dernier de ma caravane…', 'Je suis la dernière de ma caravane…', 28153),
(137981, 'frFR', 'Si vous saviez ce que j\’ai vu…', 'Si vous saviez ce que j\’ai vu…', 28153),
(137926, 'frFR', 'Vos amis sont morts, $pr. C\’est pas un endroit pour les mortels ici.', '', 28153),
(137925, 'frFR', '', 'Un Troll du nom de Zem\’lan régnait sur ce port ? Alors, j\’imagine qu\’on doit être dans sa salle du trône.', 28153),
(137924, 'frFR', 'Bah… C\’était censé être un pèlerinage entre Tortollans qui allaient écouter les histoires de Torga. Mais… je suppose que vous pouvez nous accompagner.', '', 28153),
(137913, 'frFR', 'J\’ai le remède parfait contre la curiosité !', '', 28153),
(137912, 'frFR', 'J\’y tenais beaucoup, à ce petit gars. Ce robot, je veux dire.', '', 28153),
(137911, 'frFR', 'J\’avais un petit robot mécanique que j\’avais acheté à un Gnome de Boralus.', '', 28153),
(137909, 'frFR', 'Rassembler les réactifs nécessaires à votre communion est le premier pas vers la rédemption.', '', 28153),
(137908, 'frFR', 'Ne faites pas attendre Xenxuju… Mais prudence ! Il n\’est pas à prendre avec des pincettes.', '', 28153),
(137907, 'frFR', '%s continue pendant plusieurs minutes son laïus sur la nécessité d\’assumer la responsabilité de ses actes.', '', 28153),
(137906, 'frFR', 'Hum… Ma boussole, je dirais. Elle m\’a toujours conduit à bon port ! Enfin, jusqu\’à ce qu\’on atterrisse ici. Mais ça, je peux pas lui en vouloir, c\’est qu\’un objet inanimé, après tout…', '', 28153),
(137905, 'frFR', 'Bon, bon, vous pouvez venir… mais ne faites pas un bruit ! C\’est un pèlerinage, pas un banquet au château.', '', 28153),
(137903, 'frFR', '', 'Impressionnant… mais nous avons encore beaucoup à faire. Il ne reste plus que deux Loas. Nous devons partir avec ces Tortollans et aller voir Torga, le Loa tortue.', 28153),
(137902, 'frFR', '', 'Vous dites que vous avez obtenu l\’aide de Bwonsamdi… et TUÉ Hir\’eek ?', 28153),
(137901, 'frFR', 'Oh, c\’est facile ! Mon fidèle panier-repas. Il a toujours été là pour moi quand j\’avais la dalle. Si vous saviez comme il me manque !', '', 28153),
(137900, 'frFR', '', 'Enfin libre !', 28153),
(137899, 'frFR', 'La prochaine âme que la maîtresse liera sera la vôtre !', '', 28153),
(137898, 'frFR', '(Parler à Talanji de l\’aide de Bwonsamdi et de la mort d\’Hir\’eek.)', '(Parler à Talanji de l\’aide de Bwonsamdi et de la mort d\’Hir\’eek.)', 28153),
(137897, 'frFR', 'La prochaine âme que la maîtresse utilisera sera la vôtre !', '', 28153),
(137896, 'frFR', 'Vous allez mourir pour sa gloire !', '', 28153),
(137895, 'frFR', 'Je vous tuerai au nom de la maîtresse !', '', 28153),
(137894, 'frFR', '', 'Vous devez partir… Je vais pas tarder à changer, et je tiens pas à ce que vous soyez là pour voir le résultat…', 28153),
(137893, 'frFR', 'Moi, c\’est Bill. Si vous avez un truc à réparer, je suis votre homme.', '', 28153),
(137892, 'frFR', '', 'C\’est trop tard pour moi… Mais pour les autres, y a encore de l\’espoir.', 28153),
(137891, 'frFR', 'Salut à vous, $gvoyageur:voyageuse; ! Alors, vous aussi, vous vous êtes $géchoué:échouée; ici ?$B$BC\’est pas la panacée, mais vous serez toujours $gle bienvenu:la bienvenue; dans notre camp de fortune.', '', 28153),
(137890, 'frFR', 'Ratissez le désert pour retrouver les initiés disparus. Moi, je ne bouge pas d\’ici.', '', 28153),
(137889, 'frFR', 'De tout ce que vous avez perdu dans le naufrage, que regrettez-vous le plus ?', 'De tout ce que vous avez perdu dans le naufrage, que regrettez-vous le plus ?', 28153),
(137888, 'frFR', 'Z\’auriez pas un truc à manger ?', '', 28153),
(137887, 'frFR', '', 'Ça sent mauvais. Très mauvais. Sortez tous du chariot, vite !', 28153),
(137886, 'frFR', '', 'Ce sont les troupes de Jakra\’zet !', 28153),
(137885, 'frFR', '', 'Je ne pense pas que ces Trolls-là devant soient vos amis.', 28153),
(137869, 'frFR', 'Imbécile ! Vous auriez dû fuir quand vous en aviez l\’occasion ! La puissance d\’Akunda sera bientôt mienne !', '', 28153),
(137860, 'frFR', '', 'Dolly ! Dingo ! Attendez ! C\’est dangereux par là !', 28153),
(137857, 'frFR', 'Ça alors, $n ! Z\’êtes de retour… et en un seul morceau !', '', 28153),
(137851, 'frFR', 'Pour la gloire de l\’empire sephrak !', 'Pour la gloire de l\’empire sephrak !', 28153),
(137810, 'frFR', 'Arrgh ! Ma jambe… je crois qu\’elle est cassée.', '', 28153),
(137807, 'frFR', 'Allez, c\’est parti.', 'Allez, c\’est parti.', 28153),
(137806, 'frFR', 'Le rituel bat son plein. Hir\’eek va pas tarder à arriver. Vous vous sentez d\’attaque ?', '', 28153),
(137805, 'frFR', 'On se rejoint au cercle rituel.', '', 28153),
(137789, 'frFR', 'Restez sur vos gardes, $c.', 'Restez sur vos gardes, $c.', 28153),
(137788, 'frFR', '<Le corps du Loa a été entravé par des liens magiques.>', '', 28153),
(137787, 'frFR', 'Bienvenue dans mon temple, $n. En récompense de vos actes de bravoure, mon hospitalité vous est à jamais acquise.', '', 28153),
(137785, 'frFR', '', 'Merci à vous deux. Votre loyauté me touche beaucoup… Tous les Zandalari vous remercient.', 28153),
(137784, 'frFR', '', 'Je parie que je peux convaincre les autres Tortollans de Nazmir de nous aider. Peut-être que Shoak et Kajosh voudront venir aussi !', 28153),
(137783, 'frFR', 'Bon, bon, nous vous donnerons un coup de main pour affronter ce Dieu du sang, princesse. Du moment que vous arrêtez de me harceler avec ça !', '', 28153),
(137782, 'frFR', '', 'Prends bien soin de ce Loa, Lashk. Nous, nous allons tâcher de trouver de l\’aide.', 28153),
(137781, 'frFR', 'Hah ! Sacrée vieille carapace… Il n\’était pas prêt à s\’en aller. Il a préféré se réincarner !', '', 28153),
(137780, 'frFR', '', 'Mais qu\’est-ce qui se passe…', 28153),
(137779, 'frFR', '', 'Je n\’aurai aucun répit, Torga. Pas tant que G\’huun et ses Trolls de sang seront en vie. Ça, je te le promets.', 28153),
(137778, 'frFR', '', 'Et moi, je veillerai à ce que tous les Tortollans sachent que tu as résisté courageusement à G\’huun.', 28153),
(137777, 'frFR', 'Au revoir, Torga. Je me souviendrai des histoires que tu m\’as contées… et je les conterai à mon tour.', '', 28153),
(137776, 'frFR', '', 'Z\’êtes $gfort:forte;, mais vous faites pas le poids face à mes pouvoirs !', 28153),
(137764, 'frFR', '', 'Accordé… Retournons au sanctuaire.', 28153),
(137763, 'frFR', 'Pfiou ! Je ferais bien une petite pause, moi.', '', 28153),
(137762, 'frFR', '', 'Ouah… Incroyable. On a réussi !', 28153),
(137758, 'frFR', '', 'Nous allons… te régler ton compte… et il ne restera plus rien de toi quand nous aurons fini !', 28153),
(137757, 'frFR', '', 'C\’en est assez ! Plus jamais… mon peuple ne vous craindra… toi et tes infâmes Trolls de sang !', 28153),
(137755, 'frFR', 'Ceci… ne prouve… RIEN ! Il… trouvera… une autre enveloppe. Les sceaux… se briseront… G\’huun… sera… libre !', '', 28153),
(137754, 'frFR', 'Vite ! Tuez-moi ça avant qu\’il voit que je suis le vrai danger !', '', 28153),
(137753, 'frFR', 'Crains ma puissante arbalète, abjecte créature !', '', 28153),
(137752, 'frFR', 'Empêchez cet animal s\’agiter dans tous les sens ! Je ne peux pas faire mouche s\’il bouge autant !', '', 28153),
(137751, 'frFR', '', 'Qu\’est-ce que vous faites ? Gardes, à moi !', 28153),
(137750, 'frFR', 'GRAAAHH ! Vous n\’êtes RIEN face à G\’huun ! Souffrez et MOUREZ !', '', 28153),
(137749, 'frFR', '', 'POUR TORGA !', 28153),
(137748, 'frFR', '', 'Tout le monde ! MAINTENANT !', 28153),
(137747, 'frFR', 'Vos gesticulations… futiles… Je suis… intouch… Quoi ? Non. NON !', '', 28153),
(137746, 'frFR', '', 'Ton arrogance causera ta perte ! Ton pouvoir ne peut pas te protéger !', 28153),
(137745, 'frFR', 'Vos efforts… sont vains. Je suis… intouchable.', '', 28153),
(137744, 'frFR', '', 'Attendez que les autres apprennent comment on a tué le héraut de G\’huun !', 28153),
(137743, 'frFR', 'Ça fait bien longtemps que je ne me suis pas senti aussi jeune. Pour Torga !', '', 28153),
(137742, 'frFR', '', 'En avant, pour Zandalar… et pour Torga !', 28153),
(137736, 'frFR', '', 'Grand Hir\’eek, nous t\’offrons un sacrifice de chair et de sang !', 28153),
(137734, 'frFR', 'Voilà, voilà, il n\’y a pas le feu !', '', 28153),
(137733, 'frFR', '', 'Avec moi ! Allons nous préparer à détruire le héraut du Dieu du sang.', 28153),
(137732, 'frFR', 'Méfiez-vous des araignées, petit sauride. Je suis peut-être le dieu des secrets, mais Yazma, c\’est la maîtresse des espions. Elle adore envoyer ses agents dans mon domaine pour s\’en prendre à mes enfants.', '', 28153),
(137731, 'frFR', 'Je suis prêt à y aller.', 'Je suis prête à y aller.', 28153),
(137730, 'frFR', '', 'Je n\’aurais jamais cru pouvoir entrer dans ces ruines. Ne sont-elles pas fascinantes ?', 28153),
(137728, 'frFR', 'C\’est plus la même chose, hein ? Allez trouver cette crapule de Nokano qui vous a dit de tuer les miens. Mordez-le et vous retrouverez votre forme normale.', '', 28153),
(137721, 'frFR', '', 'Tous les ingrédients sont là pour faire de cette histoire la plus fabuleuse jamais vécue par des Tortollans. Venger un Loa et tuer l\’avatar d\’un ignoble monstre !', 28153),
(137720, 'frFR', 'Vous savez, je crois qu\’on pourrait effectivement tuer ce héraut de G\’huun.', '', 28153),
(137719, 'frFR', '', 'Nous devrions aller voir ce que les Trolls de sang nous réservent encore…', 28153),
(137718, 'frFR', '', 'Nous en avons fini ici, $n. Je vous retrouverai à la Ferté-d\’Arom.', 28153),
(137716, 'frFR', '', 'Je n\’étais pas de taille à affronter la sorcière, elle m\’a emprisonnée.', 28153),
(137715, 'frFR', '', 'Merci de m\’avoir libérée de cet ignoble assemblage.', 28153),
(137710, 'frFR', '', 'Bien. Allons-y et ne faites pas de bruit ! Vous faire capturer tous les deux est la dernière chose dont nous avons besoin.', 28153),
(137709, 'frFR', 'Bien sûr. J\’ai des parchemins plus vieux que vous ! Kisha, fouille donc dans mes affaires.', '', 28153),
(137708, 'frFR', '', 'Nous devons découvrir ce que mijotent les Trolls de sang. Lashk, Kisha, avez-vous quelque chose susceptible de nous aider ?', 28153),
(137707, 'frFR', '', 'Mais nos érudits parvinrent finalement à retourner la situation…', 28153),
(137706, 'frFR', 'J\’ai passé l\’âge pour ces bêtises.', '', 28153),
(137705, 'frFR', 'La magie du sang ! Qui oserait pratiquer une telle infamie ?', '', 28153),
(137704, 'frFR', 'Je raconterai cette histoire à qui veut l\’entendre.', '', 28153),
(137703, 'frFR', 'D\’abord, ils tuent Torga, et voilà qu\’ils s\’en prennent à nous ! Qu\’est-ce qui ne tourne pas rond, chez ces Trolls ?', '', 28153),
(137702, 'frFR', 'Ils m\’ont volé tous mes parchemins, en plus ! Rapportez-les-moi, je vous prie.', '', 28153),
(137701, 'frFR', 'La chance a fini par tourner !', '', 28153),
(137700, 'frFR', '', 'Vous nous empêcherez pas de becqueter nos Tortollans !', 28153),
(137699, 'frFR', '', 'Nous pas manger Loa… mais Tortollans, miam!', 28153),
(137697, 'frFR', '', 'Kachago !', 28153),
(137696, 'frFR', 'Surtout, n\’allez pas croire les mensonges éhontés de ce colporteur bouffi d\’orgueil.\n\nIl m\’a vendu plusieurs manuscrits, et tous se sont avérés truffés de boniments.\n\nS\’il croit que je vais en rester là sans me rembourser, il se fourre le doigt dans l\’œil. Après tout, les Trolls ne vivent pas si longtemps que ça.', '', 28153),
(137695, 'frFR', 'Je ne partirai pas avant que vous m\’ayez remboursé.', '', 28153),
(137694, 'frFR', 'Votre récit est confus, et fort mal tourné qui plus est.', '', 28153),
(137693, 'frFR', 'Vos livres parlent d\’endroits qui n\’ont jamais existé.', '', 28153),
(137692, 'frFR', 'Que la chance vous sourie, mortels. Et… merci.', '', 28153),
(137691, 'frFR', 'C\’est des mensonges que vous nous vendez, Fab.', '', 28153),
(137690, 'frFR', 'Détruisez les campements autour de ma dépouille pour affaiblir Jungo.', '', 28153),
(137689, 'frFR', 'Princesse Talanji, les Trolls de sang renforcent Jungo à l\’aide de mes restes.', '', 28153),
(137678, 'frFR', '', 'Accorde-nous ta sagesse, noble Torga. Dis-nous ce qu\’il faut faire pour arrêter les Trolls de sang.', 28153),
(137677, 'frFR', 'Je suis là. Que désirez-vous ?', '', 28153),
(137676, 'frFR', 'Torga ! Ton esprit, on en a besoin. Sors-toi la tête de la carapace !', '', 28153),
(137675, 'frFR', '', 'Guzincha !', 28153),
(137674, 'frFR', 'Rgggh…', '', 28153),
(137673, 'frFR', 'Graaaagh !', '', 28153),
(137672, 'frFR', '', 'Personne n\’échappe au Dieu du sang !', 28153),
(137671, 'frFR', '« Stupide chèvre. Allons-y avant que tu ne finisses dans l\’estomac d\’un monstre. »', '« Stupide chèvre. Allons-y avant que tu ne finisses dans l\’estomac d\’un monstre. »', 28153),
(137670, 'frFR', '', 'Du sang pour G\’huun !', 28153),
(137669, 'frFR', '« Coucou, Massepain. Tu m\’as l\’air perdue ! Suis-moi et je te conduirai chez toi, d\’accord ? »', '« Coucou, Massepain. Tu m\’as l\’air perdue ! Suis-moi et je te conduirai chez toi, d\’accord ? »', 28153),
(137668, 'frFR', '', 'Ces os vont bien nous servir !', 28153),
(137667, 'frFR', '', 'Du sang, je le veux !', 28153),
(137666, 'frFR', '', 'De la viande fraîche !', 28153),
(137665, 'frFR', '', 'Zuldazar disparaîtra !', 28153),
(137664, 'frFR', 'Je ne suis pas là pour vous défendre, vous et les marchands. Mon boulot à moi, c\’est de combattre les horreurs qui risquent de rappliquer du nord : Trolls de sang, hommes-serpents, Alliance et compagnie.\n\nJe combats aussi l\’ennui, mais ça, c\’est une autre histoire. Qu\’est-ce qui vous amène ?', 'Je ne suis pas là pour vous défendre, vous et les marchands. Mon boulot à moi, c\’est de combattre les horreurs qui risquent de rappliquer du nord : Trolls de sang, hommes-serpents, Alliance et compagnie.\n\nJe combats aussi l\’ennui, mais ça, c\’est une autre histoire. Qu\’est-ce qui vous amène ?', 28153),
(137663, 'frFR', '<La petite chèvre semble s\’être éloignée de sa ferme.\n\nSur le collier est inscrit « Massepain ».>', '', 28153),
(137662, 'frFR', '', 'Du sang ! Du sang ! Du sang !', 28153),
(137661, 'frFR', 'Il paraît que c\’est vous qui avez ramené la princesse Talanji. Merci.\n\nPar contre, on raconte que vous avez aussi ramené Zul. Et là, moins merci.\n\nBref, qu\’est-ce que vous voulez ?', 'Il paraît que c\’est vous qui avez ramené la princesse Talanji. Merci.\n\nPar contre, on raconte que vous avez aussi ramené Zul. Et là, moins merci.\n\nBref, qu\’est-ce que vous voulez ?', 28153),
(137660, 'frFR', 'Vous me prenez pour un marchand ? Je suis un guerrier, moi, un vrai ! Et de la caste supérieure, rien que ça.\n\nQu\’est-ce que vous cherchez ?', 'Vous me prenez pour une marchande ? Je suis une guerrière, moi, une vraie ! Et de la caste supérieure, rien que ça.\n\nQu\’est-ce que vous cherchez ?', 28153),
(137659, 'frFR', 'Vous cherchez quelque chose ? Si ce n\’est pas le cas, circulez.', 'Vous cherchez quelque chose ? Si ce n\’est pas le cas, circulez.', 28153),
(137658, 'frFR', 'Dites donc, vous ne trafiqueriez pas avec le vaudou des Trolls de sang, par hasard ? Non ? Bien.\n\nQu\’est-ce qui vous amène, alors ?', 'Dites donc, vous ne trafiqueriez pas avec le vaudou des Trolls de sang, par hasard ? Non ? Bien.\n\nQu\’est-ce qui vous amène, alors ?', 28153),
(137657, 'frFR', 'Il paraît que les Trolls de sang, ils ont trouvé un moyen de s\’infiltrer dans notre société. Comme ils ne peuvent pas nous envahir, ils essaient de nous convertir.\n\nSûrement un peu des deux à la fois, en fait. Je peux vous aider ?', 'Il paraît que les Trolls de sang, ils ont trouvé un moyen de s\’infiltrer dans notre société. Comme ils ne peuvent pas nous envahir, ils essaient de nous convertir.\n\nSûrement un peu des deux à la fois, en fait. Je peux vous aider ?', 28153),
(137656, 'frFR', 'Mon cousin, il est en train de se battre à la porte de Sang. Et moi ? Moi, on m\’a affecté aux saurides. Peuh.\n\nBon, qu\’est-ce que vous voulez, au juste ?', 'Mon cousin, il est en train de se battre à la porte de Sang. Et moi ? Moi, on m\’a affectée aux saurides. Peuh.\n\nBon, qu\’est-ce que vous voulez, au juste ?', 28153),
(137655, 'frFR', 'Bwonsamdi, nous sommes prêts à ce que vous invoquiez l\’esprit de Torga.', 'Bwonsamdi, nous sommes prêts à ce que vous invoquiez l\’esprit de Torga.', 28153),
(137654, 'frFR', 'Rendez-vous en Nazmir, qu\’ils disaient ! Écoutez les histoires de Torga, vous verrez du pays, qu\’ils disaient !', '', 28153),
(137652, 'frFR', 'L\’enveloppe de ce Loa… me nourrit. Elle nourrit… G\’huun.', '', 28153),
(137651, 'frFR', 'Je parle… pour G\’huun. Il… dirigera. Vous servirez… ou vous mourrez.', '', 28153),
(137643, 'frFR', 'Entendre leurs hurlements, ça me plairait bien, mais vous feriez mieux de rester $gdiscret:discrète;. J\’voudrais pas qu\’ils vous mettent le grappin dessus.', '', 28153),
(137642, 'frFR', 'Ahh, la liberté !', '', 28153),
(137641, 'frFR', 'Oh, et si vous croisez un Troll qui s\’appelle Sur\’jan, plantez-lui ma griffe dans le cœur ! Il l\’aura bien cherché !', '', 28153),
(137640, 'frFR', 'Merci pour tout !', '', 28153),
(137639, 'frFR', '', 'Avec le pouvoir du Dieu du sang et les rejetons d\’Hir\’eek pour nous faire voler, les Zandalari, on va les massacrer !', 28153),
(137638, 'frFR', 'Merci d\’avoir fait le gros du travail, $p. Dites à Kreepi de me faire parvenir de l\’eau en sortant, vous voulez bien ?', '', 28153),
(137637, 'frFR', 'Soyez $gprudent:prudente; ! Les tréants sont devenus fous furieux et tuent tous ceux qui approchent d\’eux.', '', 28153),
(137620, 'frFR', 'Votre taille importe peu. Votre esprit surpasse tous ceux que j\’ai croisés dans ces collines.', '', 28153),
(137619, 'frFR', '', 'Merci, Sumber ! Je veux apprendre tout ce que vous pouvez enseigner à la petite Vulpérine que je suis.', 28153),
(137618, 'frFR', 'J\’ai imprégné ce totem d\’une partie de ma puissance. Faites-en bon usage.', '', 28153),
(137616, 'frFR', '', 'Soyez le bienvenu, Sumber. Mon $gami:amie; et moi serons heureux de vous aider de notre mieux.', 28153),
(137615, 'frFR', 'Je suis impressionné. Vous avez fait preuve de sagesse en m\’apportant cette essence.', '', 28153),
(137614, 'frFR', '', 'Argh ! Cette eau se déplace trop vite pour que je puisse la contrôler !', 28153),
(137610, 'frFR', '', 'Cherchez de grandes mares. Elles ne sont pas nombreuses en Vol\’dun. Vous ne devriez avoir aucun mal à les repérer.', 28153),
(137609, 'frFR', '', 'Débrouillez-vous pour mettre le paquet ! Faut qu\’on en bouche un coin à Sumber.', 28153),
(137608, 'frFR', '', 'Quoi qu\’il se passe en bas, contentez-vous de prendre l\’eau et de ressortir. Ne vous laissez pas embarquer dans une affaire qui ne vous regarde pas.', 28153),
(137607, 'frFR', 'De puissantes entités vous attendent là en bas, $p. Laissez la sagesse guider vos choix et vos armes.', '', 28153),
(137606, 'frFR', 'Gloire et honneur à vous, $p.', '', 28153),
(137605, 'frFR', '', 'Toute peine mérite salaire, qui que vous soyez.', 28153),
(137604, 'frFR', '$gUn puissant:Une puissante; adversaire du mal comme $p ne combat pas les monstres pour l\’argent, Maiya. $gIl:Elle; le fait pour la gloire !', '', 28153),
(137603, 'frFR', '', 'Tout peut être réparé pour peu qu\’on s\’en donne la peine, Heiro.', 28153),
(137602, 'frFR', 'T\’es sûr qu\’on peut réparer ce chariot ? Les ranishu en ont dévoré une bonne partie.', '', 28153),
(137601, 'frFR', 'Que la fête, elle commence ! Place au carnage, et à moi les âmes errantes !', '', 28153),
(137597, 'frFR', 'Vous vous donnez du mal, Talanji, je vous l\’accorde. Mais c\’est pas pour ça que mon aide sera gratuite.', '', 28153),
(137594, 'frFR', '', 'Nous refusons d\’entrer dans ton jeu, Bwonsamdi. Tu veux l\’esprit d\’un Loa ? Hir\’eek a déjà été tué par $n. Tu n\’as qu\’à te servir.', 28153),
(137590, 'frFR', 'Hah… Et si on faisait… un marché, hm ? Vous m\’apportez l\’âme d\’un autre Loa, et là vous pourrez parler à l\’esprit de Torga.', '', 28153),
(137588, 'frFR', 'Laissez-moi deviner… Vous voulez parler à l\’esprit de ce pauvre Torga.', '', 28153),
(137587, 'frFR', 'Je suis prêt à essayer d\’invoquer Bwonsamdi.', 'Je suis prête à essayer d\’invoquer Bwonsamdi.', 28153),
(137586, 'frFR', 'Et les belles paroles ne mènent à rien. Faut qu\’on trouve un autre moyen de les arrêter. Ou au moins, de les semer, comme vous l\’avez fait.', '', 28153),
(137585, 'frFR', 'Je ferai passer le mot à Kreepi et aux autres que même $gun:une:r; $pr n\’est pas à l\’abri de l\’appétit des ranishu...', '', 28153),
(137584, 'frFR', 'Ha ha ! Visez un peu, $gun:une; $pr qui cavale ! Faites gaffe à pas vous casser la figure !', '', 28153),
(137583, 'frFR', 'Gros miam-miam ! Manger masque ! Manger $pr !', '', 28153),
(137582, 'frFR', '', 'Les Trolls de sang, ils vont regretter d\’avoir croisé notre chemin.', 28153),
(137581, 'frFR', '<Tirer sur la torche.>', '<Tirer sur la torche.>', 28153),
(137580, 'frFR', '<En examinant la torche de plus près, vous remarquez qu\’elle est reliée à un mécanisme intégré au mur.>', '', 28153),
(137579, 'frFR', '<Il s\’agit d\’une paire de vieilles bottes.\n\nÀ quoi vous attendiez-vous ?>', '', 28153),
(137578, 'frFR', '<Vous ne trouvez aucune entrée secrète sous le tapis.\n\nIl va très bien dans la pièce, cela dit.>', '', 28153),
(137577, 'frFR', '<Étonnamment, le livre qui dépasse n\’est pas un levier dissimulé ouvrant un passage secret.>', '', 28153),
(137576, 'frFR', '<L\’ancre est solidement fixée au mur.>', '', 28153),
(137575, 'frFR', '', 'Je vais vous dire qui. Les Trolls de sang. Suivez-moi… Ils vont payer pour ça !', 28153),
(137574, 'frFR', '', 'Qui aurait pu faire ça à Torga ? Tout ce qu\’il voulait, c\’était raconter ses histoires !', 28153),
(137573, 'frFR', 'Torga ! NON !', '', 28153),
(137572, 'frFR', 'Torga a été abattu comme un vulgaire mouton !', '', 28153),
(137571, 'frFR', 'Toutes les histoires de Torga… perdues pour toujours !', '', 28153),
(137570, 'frFR', 'Un Loa… mort ?', '', 28153),
(137569, 'frFR', 'Comment une chose pareille a-t-elle pu se produire ?', '', 28153),
(137568, 'frFR', '', 'Depuis, ce précieux savoir est conservé ici, à l\’abri de toutes les convoitises.', 28153),
(137563, 'frFR', 'Je cherche du travail.', 'Je cherche du travail.', 28153),
(137561, 'frFR', '', 'Pfff ! J\’ai l\’air d\’un guide touristique ? Je suis juste ici pour écouter les récits de Torga.', 28153),
(137560, 'frFR', '', 'Je ferais mieux de partir avant que quelqu\’un d\’autre me demande son chemin.', 28153),
(137559, 'frFR', '', 'Continuez à suivre cette route sans vous en écarter et vous finirez par trouver Torga. Vous ne pouvez pas le rater, c\’est une tortue géante…', 28153),
(137558, 'frFR', '', 'Bah ! Mais qu\’est-ce que vous en avez à fiche, de ce que je fais ! Ne venez pas critiquer ma façon de faire ce pèlerinage, hein.', 28153),
(137557, 'frFR', 'En « pèlerinage » ? Ça n\’a pas l\’air trop fatigant ! Lashk a dit que vous saviez où trouver Torga.', 'En « pèlerinage » ? Ça n\’a pas l\’air trop fatigant ! Lashk a dit que vous saviez où trouver Torga.', 28153),
(137556, 'frFR', 'Lashk dit que vous savez où trouver Torga.', 'Lashk dit que vous savez où trouver Torga.', 28153),
(137555, 'frFR', 'Qu\’est-ce que vous voulez ? Vous voyez pas que je suis en plein pèlerinage ?', '', 28153),
(137554, 'frFR', 'Je crois qu\’on va s\’entendre à merveille, princesse.', '', 28153),
(137553, 'frFR', '', 'Ce n\’est pas la première fois que je traite avec de vieux Tortollans qui radotent. Concentrez-vous et avancez !', 28153),
(137552, 'frFR', 'Bon, allons voir Torga. Mais rappelez-vous : ne faites pas trop de bruit. Je ne voudrais pas manquer la moindre de ses histoires !', '', 28153),
(137551, 'frFR', 'Bah… Nous ne cherchons pas à nous rallier à une cause, mais nous ne vous empêcherons pas non plus de vous joindre à nous.', '', 28153),
(137550, 'frFR', 'Que voulez-vous ?', '', 28153),
(137549, 'frFR', 'Vous avez intérêt à revoir votre réponse.', '', 28153),
(137548, 'frFR', 'Je ne connais qu\’Akunda.', '', 28153),
(137547, 'frFR', 'Je vous demande votre nom et vous me racontez des histoires ?', '', 28153),
(137546, 'frFR', 'Aile de mort ? Quelle créature pathétique peut bien porter un tel nom ?', '', 28153),
(137545, 'frFR', 'Vous bénéficierez de l\’amélioration associée à ce Loa. Ce système est encore en développement.', 'Vous bénéficierez de l\’amélioration associée à ce Loa. Ce système est encore en développement.', 28153),
(137544, 'frFR', 'Je m\’en occupe tout de suite.', 'Je m\’en occupe tout de suite.', 28153),
(137543, 'frFR', '', 'La flore lutte pour survivre dans ce goulet, tout comme nous.', 28153),
(137542, 'frFR', 'Je vous suis éternellement reconnaissante. Je vais quitter cet endroit pour toujours.', 'Merci infiniment. Et maintenant, je vais partir aussi loin que possible de ces lieux.', 28153),
(137541, 'frFR', '', 'Salut ! Vous aimez le feu ? Et les fusées ? Et des fusées de feu, ça vous parle ? J\’ai des tas d\’engins canon à vous montrer. On va bien s\’amuser !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137540, 'frFR', 'Bonté divine ! Mais qu\’est-ce que c\’était que ça ?!', 'Bonté divine ! Mais qu\’est-ce que c\’était que ça ?!', 28153),
(137537, 'frFR', '', 'Oh, c\’est pas le cas. Mais je déconseille de traverser le canyon. Il est rempli de cauchemars.', 28153),
(137536, 'frFR', '', 'Accrochez-vous. Ça va secouer !', 28153),
(137535, 'frFR', 'Ça peut pas être la seule route à prendre…', '', 28153),
(137534, 'frFR', '', 'Cap sur le sud. Mais sachez toutefois que ces montagnes sont maudites. Ceux qui s\’y aventurent n\’en reviennent jamais.', 28153),
(137533, 'frFR', 'Ça doit être ici. Je vois un bâtiment, droit devant.', '', 28153),
(137531, 'frFR', 'On devrait aller au sud. Le temple, il est quelque part dans ces collines.', '', 28153),
(137530, 'frFR', 'Elles ont beau être rustiques, mes chambres sont tout ce qu\’il y a de plus confortable, croyez-moi.', '', 28153),
(137529, 'frFR', 'Akunda nous a donné une chance de tirer un trait sur notre passé et de commencer une vie nouvelle.', '', 28153),
(137528, 'frFR', '', 'La Horde doit être éradiquée. Zuldazar finira par se soumettre à l\’Alliance !', 28153),
(137526, 'frFR', 'Bof. Cet endroit n\’est pas si hostile. Nous sommes en pèlerinage. Et j\’ai l\’impression que vous allez nous compliquer les choses.', '', 28153),
(137525, 'frFR', '', 'Des Tortollans ! Qu\’est-ce qui vous amène dans cet endroit maudit ?', 28153),
(137523, 'frFR', 'La réponse, elle ne va pas vous plaire, $n. Je mérite mon exil dans le désert.', '', 28153),
(137517, 'frFR', 'Qu\’avez-vous fait pour échouer ici ?', 'Qu\’avez-vous fait pour échouer ici ?', 28153),
(137516, 'frFR', 'C\’est pas si mal de pouvoir tirer un trait sur mon passé pour tout recommencer. Ces Trolls, ils sont peut-être pas totalement fous, en fin de compte.', '', 28153),
(137515, 'frFR', 'Rakera m\’a sauvé la vie. Aucun des exilés n\’aurait survécu au désert sans ses lumières.', '', 28153),
(137509, 'frFR', 'D\’accord, prenez ça et laissez-moi partir !', '', 28153),
(137508, 'frFR', 'Danse, Rupert !', '', 28153),
(137505, 'frFR', 'Celle que vous cherchez, je l\’ai vue. Elle a passé les épreuves facilement, mais elle avait pas envie de s\’éterniser ici.\n\nElle cherchait quelque chose. Elle posait beaucoup de questions, comme vous, mais d\’un coup, elle a filé vers le sud. Vous devriez faire pareil.\n\nCe temple, il n\’est pas sûr.', '', 28153),
(137504, 'frFR', '', 'Nous ne faisons qu\’un avec Akunda.', 28153),
(137502, 'frFR', 'Rupert, viens ici !', '', 28153),
(137501, 'frFR', 'Avez-vous vu le garde de guerre Rakera ?', 'Avez-vous vu le garde de guerre Rakera ?', 28153),
(137500, 'frFR', 'Akunda nous donne la force.', 'Akunda nous donne la force.', 28153),
(137499, 'frFR', 'Nous ne sommes rien sans Akunda.', 'Nous ne sommes rien sans Akunda.', 28153),
(137498, 'frFR', 'Akunda nous accorde sa puissance.', 'Akunda nous accorde sa puissance.', 28153),
(137497, 'frFR', 'Nous sommes tous Akunda.', 'Nous ne faisons qu\’un avec Akunda.', 28153),
(137496, 'frFR', 'Elle n\’est pas à l\’unisson d\’Akunda.', '', 28153),
(137495, 'frFR', '', 'Si elle n\’est pas à l\’unisson d\’Akunda, elle n\’a pas sa place ici.', 28153),
(137494, 'frFR', 'Seul Akunda arpente dans ce temple.', '', 28153),
(137493, 'frFR', 'Personne de ce nom ne réside ici.', '', 28153),
(137492, 'frFR', '', 'Je ne vois que ceux qui sont dignes de la puissance d\’Akunda.', 28153),
(137491, 'frFR', 'Pourquoi vous préoccupez-vous de ceux qui ne sont pas à l\’unisson d\’Akunda ?', '', 28153),
(137490, 'frFR', '', 'Rakera ? Quel nom étrange...', 28153),
(137489, 'frFR', 'Entrailles gluantes ! Miam ! Miam !', '', 28153),
(137488, 'frFR', 'Baissez le ton… Il ne faudrait pas que ces illuminés, ils nous entendent parler ainsi.', '', 28153),
(137487, 'frFR', 'Vous souhaitez ne faire qu\’un avec Akunda, mon enfant ? Alors, obéissez-moi fidèlement et j\’exaucerai votre vœu...', '', 28153),
(137486, 'frFR', 'Vous, là ! Ce calice, il ne faut pas boire dedans.', '', 28153),
(137485, 'frFR', 'Miam ! Miam ! Miam !', '', 28153),
(137484, 'frFR', 'Vous avez les oreilles bouchées, ou quoi ? Si vous buvez dans ce calice, vous allez le regretter.', '', 28153),
(137483, 'frFR', 'Salja, elle passe son temps à pioncer dans la tour nord. Une goutte de mon poison, et elle se réveillera plus jamais. Et surtout, oubliez pas la clé, quoi !', '', 28153),
(137482, 'frFR', '', 'On se connaît ? Votre tête me dit quelque chose...', 28153),
(137480, 'frFR', 'Dès que je serai sorti de là, vous me le paierez cher !', '', 28153),
(137479, 'frFR', 'Sortez-moi de là ou je vous jure que vous le regretterez !', '', 28153),
(137478, 'frFR', 'Sortez-moi de cette cage fissa, ou je fais de vot\’ vie un vrai cauchemar !', '', 28153),
(137477, 'frFR', 'Je n\’avais jamais rien vu de tel... La viande a rendu les ranishu encore plus affamés. Sousbois l\’Ancien n\’avait aucune chance !', '', 28153),
(137476, 'frFR', 'Ha ha ! Ça chatouille... Aïe ! Hé, ça fait mal, ça ! Assez rigolé !', '', 28153),
(137475, 'frFR', 'Vous n\’avez PAS la permission de me dévorer, ignobles créatures !', '', 28153),
(137472, 'frFR', '<Les yeux de Sousbois l\’Ancien sont froids et sans vie.>', '', 28153),
(137466, 'frFR', 'Dirigez-vous vers le nord et cherchez le dévoreur Ni-Ni. C\’est un gros insecte avec des tas de cadavres autour de lui. Écrasez-le pour prendre son masque !', '', 28153),
(137465, 'frFR', '', 'Le sang de Torga, il alimente notre pouvoir !', 28153),
(137464, 'frFR', '', 'À nous le sang de Torga !', 28153),
(137463, 'frFR', 'Ah, enfin, ça ne me démange plus. La solitude est véritablement un don du ciel.', '', 28153),
(137462, 'frFR', 'Laisse parler les imbéciles, Rupert. Tu feras un compagnon parfait.', '', 28153),
(137461, 'frFR', 'C\’est un ours, pas un chien. Il faut s\’en débarrasser avant que l\’un des Holton le voie.', 'C\’est un ours, pas un chien. Il faut s\’en débarrasser avant que l\’un des Holton le voie.', 28153),
(137460, 'frFR', 'Ne dis pas de bêtises ! C\’est un pauvre petit chien que j\’ai recueilli en chassant. Je lui ai même appris quelques tours.', '', 28153),
(137459, 'frFR', 'C\’est... c\’est un ours ?!', 'C\’est... c\’est un ours ?!', 28153),
(137458, 'frFR', 'Rupert, $gce gentil:cette gentille:c; $c nous a apporté un cadeau. Danse un peu pour $gle:la; remercier !', '', 28153),
(137457, 'frFR', 'Bienvenue, Akunda l\’Intrépide.', '', 28153),
(137456, 'frFR', 'Bienvenue, Akunda l\’Imperturbable.', '', 28153),
(137455, 'frFR', 'Bienvenue, Akunda l\’Agile.', '', 28153),
(137454, 'frFR', 'Vous avez forcément entendu parler de moi. J\’ai tué Aile de mort.', 'Vous avez forcément entendu parler de moi. J\’ai tué Aile de mort.', 28153),
(137453, 'frFR', 'Les récits de ma victoire sur le roi-liche ne sont pas parvenus jusqu\’à vos côtes ?', 'Les récits de ma victoire sur le roi-liche ne sont pas parvenus jusqu\’à vos côtes ?', 28153),
(137452, 'frFR', 'J\’ai vaincu la Légion ardente. N\’allez pas me dire que vous n\’avez jamais entendu parler de moi !', 'J\’ai vaincu la Légion ardente. N\’allez pas me dire que vous n\’avez jamais entendu parler de moi !', 28153),
(137451, 'frFR', 'Fichez-moi la paix, maudites vermines ! Allez dévorer la chair dont vous raffolez et laissez les arbres tranquilles !', '', 28153),
(137450, 'frFR', 'Je me nomme Akunda l\’Agile.', 'Je me nomme Akunda l\’Agile.', 28153),
(137449, 'frFR', 'Je me nomme Akunda l\’Imperturbable.', 'Je me nomme Akunda l\’Imperturbable.', 28153),
(137448, 'frFR', 'Je me nomme Akunda l\’Intrépide.', 'Je me nomme Akunda l\’Intrépide.', 28153),
(137447, 'frFR', 'Mon nom n\’a pas changé.', 'Mon nom n\’a pas changé.', 28153),
(137446, 'frFR', 'La vie que vous avez vécue jusqu\’ici, elle n\’a plus de sens.\n\nTout ce que vous avez fait et la personne que vous étiez doivent à présent être oubliés.\n\nRévélez votre véritable nom afin que tous l\’entendent !', '', 28153),
(137444, 'frFR', 'Ils sont nombreux, ceux qui viennent chercher refuge dans notre temple, mais seuls ceux qui en sont dignes peuvent rentrer.', '', 28153),
(137438, 'frFR', 'Ah ! Ensemble nous réussirons à vaincre cette créature !', '', 28153),
(137437, 'frFR', 'Entourée d\’alliés, Long-Croc retrouve de l\’énergie et attaque de plus belle !', '', 28153),
(137436, 'frFR', 'Long-Croc hurle de joie et vous remercie. Elle peut à présent reposer en paix.', '', 28153),
(137435, 'frFR', 'Merci. Je peux à présent reposer en paix.', '', 28153),
(137434, 'frFR', 'Bienvenue dans mon bosquet, $p... ou du moins, ce qu\’il en reste.', '', 28153),
(137432, 'frFR', 'J\’en peux plus, mec ! Je suis à bout !', '', 28153),
(137431, 'frFR', 'Oubliez ça, mec ! Peut-être qu\’Hir\’eek, il ME filera son pouvoir si je VOUS sacrifie !', '', 28153),
(137430, 'frFR', 'Fini les sacrifices ! Levez-vous, frangins !', '', 28153),
(137429, 'frFR', 'Allez vous faire voir, vous et votre grande prêtresse !', '', 28153),
(137428, 'frFR', 'Y a pas moyen que j\’vive comme un animal !', '', 28153),
(137427, 'frFR', 'La grande prêtresse exige une offrande en gage de votre soumission.\n[Libérer le tâcheron.]', 'La grande prêtresse exige une offrande en gage de votre soumission.\n[Libérer le tâcheron.]', 28153),
(137426, 'frFR', 'Tu donnes manger ou tu deviens le manger !', '', 28153),
(137425, 'frFR', 'Rien n\’est jamais simple en Vol\’dun.\n\nJ\’ai juste besoin de bois pour réparer ma caravane.', '', 28153),
(137424, 'frFR', '', 'Ha ha… Trop tard… Le Dieu du sang… il est là !', 28153),
(137423, 'frFR', '', 'Le héraut, il va revenir ! Vous pouvez rien y faire !', 28153),
(137422, 'frFR', 'Ça peut paraître amusant pour $gun:une:r; $pr, mais les ranishu sont une vraie plaie.\n\nIls chatouillent un peu, cela dit.', '', 28153),
(137421, 'frFR', 'Y a rien qui pourra nous arrêter ! Les hommes, y vont se rebeller !', '', 28153),
(137420, 'frFR', 'Vous feriez bien de surveiller vos arrières. Vous les femmes, vous ne tiendrez plus les rênes bien longtemps !', '', 28153),
(137419, 'frFR', 'Z\’allez voir ça, mec. Mes frangins et moi, on va se tirer d\’ici et c\’est NOUS qu\’on va faire la loi !', '', 28153),
(137418, 'frFR', 'Vous êtes ici pour me punir de nouveau ? J\’vais pas fuir devant vous !', '', 28153),
(137417, 'frFR', 'Le sang de Torga, il alimente notre pouvoir !', '', 28153),
(137416, 'frFR', 'À nous le sang de Torga !', '', 28153),
(137414, 'frFR', 'La viande de Loa, on va l\’apporter aux autres. Vous nous arrêterez pas !', '', 28153),
(137413, 'frFR', 'La viande de Loa, elle est à nous ! Et vous aussi !', '', 28153),
(137412, 'frFR', '', 'L\’heure est venue de partir à la chasse aux sorcières.', 28153),
(137411, 'frFR', '', 'Ainsi renaît l\’ordre des Braises.', 28153),
(137410, 'frFR', '', 'Le savoir qu\’il renferme vous révélera, ainsi qu\’à nos troupes, les secrets permettant d\’éradiquer ce maudit Sabbat qui ravage nos terres.', 28153),
(137409, 'frFR', '', 'Si vous souhaitez suivre la voie de l\’Ordre, ouvrez le livre.', 28153),
(137408, 'frFR', '', 'La voici… la dernière demeure de l\’ordre des Braises. Il est temps de faire renaître l\’histoire ancienne.', 28153),
(137407, 'frFR', '', 'Le recueil devrait se trouver par ici !', 28153),
(137406, 'frFR', '', 'Qu\’est-ce que je raconte… Bien sûr que vous n\’avez rien ! Ce ne sont pas quelques cailloux qui vont avoir raison de vous.', 28153),
(137405, 'frFR', '', 'Je n\’avais jamais vu d\’assemblage aussi grand ! Vous n\’avez rien ?', 28153),
(137404, 'frFR', '', 'Hir\’eek… me… vengera…', 28153),
(137403, 'frFR', '', 'Mon âme pour G\’huun !', 28153),
(137402, 'frFR', '<Choisir d\’aider Henri Brise-Lames et mettre un terme au statu quo.>', '<Choisir d\’aider Henri Brise-Lames et mettre un terme au statu quo.>', 28153),
(137401, 'frFR', '', 'La viande de Loa, elle est à nous !', 28153),
(137400, 'frFR', '', '$C, derrière vous !', 28153),
(137399, 'frFR', '', 'Gloire… à… Hir\’eek…', 28153),
(137398, 'frFR', '', 'On prend la viande de Loa, et on MANGE la viande de Loa !', 28153),
(137397, 'frFR', '', 'Attendez… Il y a quelque chose qui cloche.', 28153),
(137396, 'frFR', '', 'Hmm… Ces décombres nous bloquent le passage. Pouvez-vous dégager la voie ?', 28153),
(137395, 'frFR', '', 'Grâce à ces connaissances, nos hommes repoussèrent les Drust dans leurs montagnes.', 28153),
(137394, 'frFR', '', 'Ils consignèrent leurs découvertes dans un traité sur les armes et tactiques efficaces contre ces barbares.', 28153),
(137393, 'frFR', '', 'Comme je le disais, le rapport de force s\’inversa lorsque nos érudits découvrirent des failles dans la magie des Drust.', 28153),
(137392, 'frFR', '', 'Merci, $c. J\’ai bien cru que j\’allais y rester.', 28153),
(137391, 'frFR', '', 'Un instant… Attention !', 28153),
(137390, 'frFR', '', 'Les Malvoie ont toujours été vaillants, mais la magie des Drust était puissante. Et la guerre tournait à leur avantage…', 28153),
(137389, 'frFR', '', 'Mes ancêtres ont combattu des assemblages de pierre similaires pendant leur guerre contre les Drust.', 28153),
(137388, 'frFR', '', 'Je suis désolée, $c. La magie du Sabbat doit troubler les esprits des anciens Drust. Mieux vaut rester sur nos gardes.', 28153),
(137387, 'frFR', '', 'Attention !', 28153),
(137386, 'frFR', '', 'Attendez… Vous avez entendu ?', 28153),
(137385, 'frFR', '', 'Ces incursions se sont poursuivies pendant de nombreuses années, jusqu\’à ce que les ancêtres de la maison Malvoie décident d\’y mettre un terme.', 28153),
(137384, 'frFR', '', 'Établis depuis toujours en Drustvar, ils multipliaient les assauts contre chacun de nos campements.', 28153),
(137383, 'frFR', '', 'Il y a bien longtemps, lors de la fondation de Kul Tiras, nos ancêtres ont dû faire face à un groupe de redoutables guerriers barbares : les Drust.', 28153),
(137382, 'frFR', '', 'Bravo ! Vous l\’avez trouvée !', 28153),
(137381, 'frFR', '', 'Nous n\’avons plus qu\’à trouver l\’entrée !', 28153),
(137380, 'frFR', '', 'Il renferme un secret familial ancestral qui remonte à l\’époque où les Malvoie ont foulé ces terres pour la première fois.', 28153),
(137379, 'frFR', '', 'Nous y sommes ! C\’est incroyable. Mon père me racontait sans cesse des histoires sur cet endroit.', 28153),
(137378, 'frFR', '', 'Yah ! En route vers la Ferté-d\’Arom !', 28153),
(137377, 'frFR', '', 'Bella, je voudrais que tu suives cette personne et que tu l\’aides à transporter les fournitures qu\’elle trouvera.', 28153),
(137376, 'frFR', '<Choisir d\’aider Long-Croc et mettre un terme au statu quo.>', '<Choisir d\’aider Long-Croc et mettre un terme au statu quo.>', 28153),
(137375, 'frFR', '<L\’esprit du chasseur Henri Brise-Lames est bien trop concentré sur son combat éternel pour remarquer votre présence.\n\nNi Long-Croc, l\’esprit du loup, ni lui ne semblent prendre l\’avantage sur l\’autre. Ils sont emprisonnés sans fin, même dans la mort.>', '', 28153),
(137374, 'frFR', '<L\’esprit de la puissante Long-Croc continue à se battre, même dans la mort.\n\nElle est prisonnière d\’un combat sans fin contre le chasseur Henri Brise-Lames.>', '', 28153),
(137296, 'frFR', '', 'Encore du sang pour Hir\’eek !', 28153),
(137295, 'frFR', '', 'C\’est l\’heure de couper quelques têtes !', 28153),
(137294, 'frFR', '', 'C\’est ici que vous mourez tous !', 28153),
(137292, 'frFR', '', 'Ce sang, Hir\’eek va s\’en délecter !', 28153),
(137290, 'frFR', '', 'De la chair fraîche pour ma chauve-souris !', 28153),
(137289, 'frFR', '', 'C\’est votre tour de finir dans le ventre d\’Hir\’eek !', 28153),
(137287, 'frFR', '', 'Le Dieu du sang, il m\’a mise en garde contre vous !', 28153),
(137284, 'frFR', 'Vous essayez de construire une forteresse ! Ha ! La bonne blague ! Ha ha !', '', 28153),
(137282, 'frFR', 'Sortez l\’artillerie lourde ! On va réduire c\’te base miteuse en miettes.', '', 28153),
(137281, 'frFR', 'Tiens, tiens ! On dirait que les gros bras de la Horde se sont enfin décidés à montrer leur sale trogne !', '', 28153),
(137280, 'frFR', 'Je décline à chaque instant qui passe. Aidez-moi… avant qu\’il ne soit trop tard.', '', 28153),
(137279, 'frFR', 'Vous avez ça dans le sang !', '', 28153),
(137278, 'frFR', 'Et maintenant, mon activité préférée, le saut ! Faites étalage de vos talents de cavalier en franchissant ces obstacles. Plus vous en sauterez, plus votre prestation sera spectaculaire !', '', 28153),
(137277, 'frFR', 'Les Baroudeurs vous ont déjà présenté leur arme favorite, les bolas ! Mettez-vous en selle et tentez d\’atteindre les zeppelins. Ils sont peu nombreux, mais rapportent beaucoup de points !', '', 28153),
(137276, 'frFR', 'Les exploits au combat sont importants pour les cavaliers de Kul Tiras. Démontrez vos talents au harpon sur ces cibles gnolles !', '', 28153),
(137275, 'frFR', 'Est-ce que ça pourrait être un hybride combinant les deux ? Un homme-ours ? Voire un ours-homme ?', '', 28153),
(137274, 'frFR', 'À nouveau des traces de griffes. Un vagabond et son familier ours, peut-être ?', '', 28153),
(137271, 'frFR', 'Peut-être pas. Elle semble avoir eu le malheur de croiser un hors-la-loi ou un vagabond de ce genre.', '', 28153),
(137270, 'frFR', 'Quelles étranges blessures. On dirait presque des griffures d\’ours. Vous croyez qu\’un ours aurait pu faire ça ?', '', 28153),
(137269, 'frFR', 'Tout ne sera plus… que désert… même Nazmir !', '', 28153),
(137268, 'frFR', 'Nazmir appartient désormais à l\’empire sephrak !', '', 28153),
(137267, 'frFR', 'J\’ai survécu aux Trolls de sang… et tout ça pour ça ? Bah !', 'J\’ai survécu aux Trolls de sang… et tout ça pour ça ? Bah !', 28153),
(137266, 'frFR', 'Bah ! Torga est mort et je peux faire une croix sur mes histoires.', 'Bah ! Torga est mort et je peux faire une croix sur mes histoires.', 28153),
(137265, 'frFR', 'Comment… ? Je déteste cet endroit… Je ne resterai pas une seconde de plus !', 'Comment… ? Je déteste cet endroit… Je ne resterai pas une seconde de plus !', 28153),
(137264, 'frFR', 'Torga… Il est mort ?! Que s\’est-il passé ?', 'Torga… Il est mort ?! Que s\’est-il passé ?', 28153),
(137263, 'frFR', '', 'C\’est quoi, ce coup en traître ? J\’aurai votre tête !', 28153),
(137262, 'frFR', '', 'Envolé. Il va falloir que je double les gages du garde-chasse cette semaine.', 28153),
(137261, 'frFR', 'Excellent ! La chasse à l\’orignal est tellement plus civilisée que les pièges à ours !', '', 28153),
(137260, 'frFR', '', 'À l\’ouest d\’ici, il y a un petit camp qui pourrait...', 28153),
(137259, 'frFR', 'Haha ! Quel spectacle ! Continuez comme ça !', '', 28153),
(137258, 'frFR', 'Partez !', '', 28153),
(137257, 'frFR', 'Junji, il a le chic pour se mettre dans le pétrin. Si les lézards le trouvent avant vous, ça va faire du vilain !', '', 28153),
(137256, 'frFR', 'À vos marques, prêts ?', '', 28153),
(137255, 'frFR', 'Ces ingrédients, ils sont peut-être pas très ragoûtants, mais ils n\’en sont pas moins nourrissants.', '', 28153),
(137254, 'frFR', 'Gronde-Gueule, il est mort et on a retrouvé les alpagas disparus. Reste plus qu\’à s\’occuper de Mojambo avant qu\’il vienne nous massacrer…', '', 28153),
(137253, 'frFR', 'Les alpagas, ils survivront pas seuls dans le désert. Il faut les ramener !', '', 28153),
(137252, 'frFR', 'Notre troupeau d\’alpagas a disparu. On doit les retrouver avant qu\’il ne soit trop tard !', '', 28153),
(137251, 'frFR', 'Le désert, il peut paraître rebutant, mais on y trouve quand même de la nourriture, si on sait où chercher !', '', 28153),
(137250, 'frFR', 'On ne survivra pas longtemps sans vivres et sans matériel…', '', 28153),
(137249, 'frFR', 'Nous n\’aurons pas la paix tant que les Sephraks ravageront nos terres.', '', 28153),
(137248, 'frFR', 'Nous commencerons à votre signal.', '', 28153),
(137247, 'frFR', '$n a pris Grangeneuve !', '$n a pris Grangeneuve !', 28153),
(137246, 'frFR', 'L\’Alliance a pris le contrôle de Grangeneuve.', 'L\’Alliance a pris le contrôle de Grangeneuve.', 28153),
(137245, 'frFR', 'L\’Alliance a pris le contrôle de la crête de la Cognée !', 'L\’Alliance a pris le contrôle de la crête de la Cognée !', 28153),
(137244, 'frFR', '', 'Je vous en prie… Mon temps est… compté.', 28153),
(137243, 'frFR', '<La Trollesse a une entaille ciselée au flanc, bordée de mousse verdâtre.>', '', 28153),
(137242, 'frFR', '', 'Je m\’inquiète tellement pour ma nièce.', 28153),
(137241, 'frFR', '', 'Je suis si contente que vous soyez en vie, $p ! Dolly et Dingo aussi, d\’ailleurs.', 28153),
(137240, 'frFR', '', 'Dolly et Dingo ont une faim de loup. Ça creuse, de tirer un chariot plein de Trolls !', 28153),
(137239, 'frFR', '', 'Dolly et Dingo sont aussi robustes que fiables. Ces braves bêtes nous conduiront où nous voulons aller.', 28153),
(137235, 'frFR', 'Ce marché me convient.', 'Ce marché me convient.', 28153),
(137234, 'frFR', 'Nickel range le faucon dans son sac.', '', 28153),
(137233, 'frFR', 'Ah, $gun:une:c; $c s\’aventure dans ma tanière. Dites-moi, $gpetit:petite:r; $r, êtes-vous ici pour passer un marché avec moi ?\n\nJ\’ai décidé il y a fort longtemps de laisser mes adeptes suivre d\’autres Loas. Mais j\’exige de ceux qui veulent s\’attirer mes faveurs d\’être des symboles vivants de ma puissance auprès du peuple de Zuldazar.\n\nSi vous voulez recevoir ma bénédiction, retournez jusqu\’aux marches de Dazar\’alor et érigez un sanctuaire digne des dieux en mon honneur.\n\nEn échange, je vous traiterai comme un membre de ma meute. Ce marché vous convient-il ?', '', 28153),
(137226, 'frFR', 'Libérez-moi.', 'Libérez-moi.', 28153),
(137223, 'frFR', 'Salut, $Ucossu:cossue;. C\’est quoi qui vous amène au sanctuaire des Miséreux ?', '', 28153),
(137212, 'frFR', 'Premier jour : on devrait tomber sur les Troggs des cavernes du nord d\’ici le déjeuner. Je suis sûr qu\’on trouvera un trésor avant le dîner ! C\’est parti pour l\’aventure !', '', 28153),
(137175, 'frFR', '$n a pris la croisée de Nordclos !', '$n a pris la croisée de Nordclos !', 28153),
(137174, 'frFR', 'L\’Alliance a pris le contrôle de la croisée de Nordclos !', 'L\’Alliance a pris le contrôle de la croisée de Nordclos !', 28153),
(137162, 'frFR', 'Ah, une autre âme à briser pour G\’huun !', '', 28153),
(137161, 'frFR', 'Encore ? Stupide sauride.', '', 28153),
(137157, 'frFR', 'Hek hek hek hek !', '', 28153),
(137156, 'frFR', '$n a pris Haut-Perchoir !', '$n a pris Haut-Perchoir !', 28153),
(137155, 'frFR', 'L\’Alliance a pris le contrôle de Haut-Perchoir !', 'L\’Alliance a pris le contrôle de Haut-Perchoir !', 28153),
(137154, 'frFR', 'C\’est… c\’est assez grisant !', '', 28153),
(137153, 'frFR', 'Mais… Joma ! Joma, j\’y arrive !', '', 28153),
(137152, 'frFR', 'L\’Alliance a pris le contrôle du cercle des Éléments !', 'L\’Alliance a pris le contrôle du cercle des Éléments !', 28153),
(137151, 'frFR', '$n a pris le cercle des Éléments !', '$n a pris le cercle des Éléments !', 28153),
(137148, 'frFR', 'Génial, papa !', '', 28153),
(137144, 'frFR', 'NON ! JE N\’Y ARRIVE PAS ! ÇA VA TROP VITE !', '', 28153),
(137143, 'frFR', 'Je crois que… j\’y arrive…', '', 28153),
(137142, 'frFR', 'Aaaaraaargh !', '', 28153),
(137141, 'frFR', 'Rarrargh ! Briser ! Tuer !', '', 28153),
(137140, 'frFR', 'Tuer ! Tuer ! Tuer !', '', 28153),
(137139, 'frFR', 'Grr… Écrase !', '', 28153),
(137138, 'frFR', 'Moi casser vous !', '', 28153),
(137137, 'frFR', 'Grrrooooaaarg !', '', 28153),
(137135, 'frFR', 'Moi… tuer… vous…', '', 28153),
(137134, 'frFR', 'Ça écroule…', '', 28153),
(137133, 'frFR', 'Moi… faible…', '', 28153),
(137132, 'frFR', 'Maintenant, c\’est vous dîner !', '', 28153),
(137131, 'frFR', 'Pas prendre viande fraîche !', '', 28153),
(137130, 'frFR', 'Terre broyer vous !', '', 28153),
(137129, 'frFR', 'Moi manger vous !', '', 28153),
(137128, 'frFR', 'D\’accord, Joma. Guide-moi jusqu\’au manège. Je pense que ce sera l\’endroit parfait pour… pour me mettre le pied à l\’étrier, comme on dit.', '', 28153),
(137127, 'frFR', 'Oui, papa ! Continue comme ça !', '', 28153),
(137122, 'frFR', 'Ça à moi…', '', 28153),
(137121, 'frFR', 'Moi… tuer… vous…', '', 28153),
(137120, 'frFR', 'Moi… casser vous… en deux !', '', 28153),
(137119, 'frFR', 'Moi casser vous en deux !', '', 28153),
(137118, 'frFR', 'Moi manger vous !', '', 28153),
(137117, 'frFR', 'Moi tuer vous !', '', 28153),
(137116, 'frFR', 'Trésor à moi !', '', 28153),
(137113, 'frFR', 'Harrison Jones est mon héros ! Mais j\’aime bien Brann Barbe-de-Bronze aussi.', '', 28153),
(137110, 'frFR', 'Ça mord !', '', 28153),
(137109, 'frFR', 'Oups ! Vous avez attrapé un crabe en colère !', '', 28153),
(137108, 'frFR', 'La ligne a cassé !', '', 28153),
(137107, 'frFR', 'Poz\’ga !', '', 28153),
(137106, 'frFR', 'Poz\’ga va vous dévorer !', '', 28153),
(137105, 'frFR', 'Poz\’ga rapplique, on se taille !', '', 28153),
(137104, 'frFR', '', 'Je vous livrerai moi-même en pâture à Hir\’eek !', 28153),
(137101, 'frFR', 'Vous croyez qu\’il y a des reliques des Titans ici ? Je parie qu\’il y en a plein. C\’est pour ça qu\’il y a tellement de Troggs. Je vais dénicher tout ce que les Titans ont laissé derrière eux !', '', 28153),
(137100, 'frFR', 'Ces gamins vont être punis à vie !', '', 28153),
(137099, 'frFR', 'Mon petit-fils s\’attire toujours des ennuis, mais là, c\’est le pompon !', '', 28153),
(137098, 'frFR', 'Éviscération', 'Éviscération', 28153),
(137097, 'frFR', 'T… très bien. Je suppose qu\’il est temps. Vous voulez bien m\’aider ?', '', 28153),
(137096, 'frFR', 'Suivez-moi, faut sortir d\’ici !', '', 28153),
(137095, 'frFR', 'Allez papa, assez traîné ! Tu dois monter sur ce cheval maintenant.', '', 28153),
(137094, 'frFR', 'Ce cheval n\’est pas fait pour moi. Son regard brille quand il m\’observe. Il ne pense qu\’à manger ma carapace !', '', 28153),
(137093, 'frFR', 'Je l\’aime bien celui-là. C\’est le plus beau ! Hein papa ?', '', 28153),
(137092, 'frFR', 'Non, non. Je ne peux pas monter celui-là. Il a l\’air trop… vigoureux ! Regarde sa démarche. Mes vieux os ne supporteraient pas de tels mouvements.', '', 28153),
(137091, 'frFR', 'Celui-ci a l\’air gentil !', '', 28153),
(137090, 'frFR', 'Non, non, Joma. Celui-là ne convient pas. Il est trop… euh… agité. Oui ! Agité ! Je suis certain que n\’importe quel mouvement brusque lui ferait peur.', '', 28153),
(137089, 'frFR', 'Qu\’est-ce que tu dis de celui-là, papa ?', '', 28153),
(137088, 'frFR', 'Bien. Assez lambiné. Il est temps de trouver le cheval idéal !', '', 28153),
(137087, 'frFR', 'Avant de commencer, laissez-moi me préparer. Ça ne prendra qu\’un instant…', '', 28153),
(137086, 'frFR', 'On vous taille en pièces et ensuite, on vous bouffe !', '', 28153),
(137085, 'frFR', 'Les maîtres, ils vont adorer vous becqueter !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(137084, 'frFR', 'Mon papa, il arrête pas de parler de chevaux ! Il rêve d\’en monter un, mais je crois bien qu\’il en a peur.$b$bHeureusement, je sais exactement quoi faire pour l\’aider !', '', 28153),
(137083, 'frFR', 'C\’est sûrement ça que les Sephraks cherchaient si activement !', '', 28153),
(137082, 'frFR', 'Ainsi, les histoires gravées sur les pierres runiques disaient vrai… La sphère existe bel et bien !', '', 28153),
(137080, 'frFR', '', 'Je me laisserai pas piéger par vot\’ magie !', 28153),
(137079, 'frFR', '', 'Les potions, elles sont pas encore prêtes. Du vent !', 28153),
(137078, 'frFR', '', 'Parlez. Pourquoi vous me dérangez dans ma méditation ?', 28153),
(137077, 'frFR', 'Thun\’ka... le Flétrisseur...', '', 28153),
(137076, 'frFR', 'Thun\’ka... le Flétrisseur...', '', 28153),
(137075, 'frFR', '', 'Merci pour le coup de main, $gétranger:étrangère;. À l\’avenir, gardez les pieds au sec.', 28153),
(137074, 'frFR', 'Soyez sur vos gardes. Cette petite fête est sur le point de devenir beaucoup plus intéressante !', '', 28153),
(137073, 'frFR', 'Ce vol ne sera pas impuni !', 'Ce vol ne sera pas impuni !', 28153),
(137071, 'frFR', 'Vous n\’êtes pas de taille à affronter notre empereur !', 'Vous n\’êtes pas de taille à affronter notre empereur !', 28153),
(137068, 'frFR', 'Le pouvoir de ces ruines nous appartient !', 'Le pouvoir de ces ruines nous appartient !', 28153),
(137067, 'frFR', 'Nous seuls détiendrons le pouvoir !', 'Nous seuls détiendrons le pouvoir !', 28153),
(137066, 'frFR', '', 'Ce n\’est pas tous les jours qu\’on a la chance de s\’attirer les faveurs d\’un élémentaire d\’eau.', 28153),
(137065, 'frFR', '', 'J\’admire votre ferveur. Érigez une statue à mon honneur au pied des marches de Dazar\’alor afin que les Trolls de ces terres sachent à qui vous avez eu affaire.', 28153),
(137063, 'frFR', '', 'Ha ha ! Je ne m\’attendais pas à ce que vous me preniez au mot.', 28153),
(137062, 'frFR', '<Activer le colosse.>', '<Activer le colosse.>', 28153),
(137061, 'frFR', 'L\’assemblage antique se met à briller lorsque vous vous en approchez.', 'L\’assemblage antique se met à briller lorsque vous vous en approchez.', 28153),
(137056, 'frFR', 'N\’essayez pas de me lier à nouveau, chaman, ou je vous désintègre !', '', 28153),
(137055, 'frFR', 'Salut ! Vous, vous faites pas partie de ces nobles bouffis d\’orgueil, ça se voit tout de suite. Venez donc trinquer avec nous ! On est descendus de nos montagnes sur invitation du seigneur Norwington, histoire de mettre un peu d\’ambiance, et c\’est exactement ce qu\’on va faire !', '', 28153),
(137054, 'frFR', 'Z\’avez rien à faire ici... C\’est le pont des Trolls, ça !', '', 28153),
(137053, 'frFR', 'Admire un peu ces bêtes majestueuses, mon enfant. Nous avons traversé le continent pour assister à ce festival, et je compte bien en apprendre plus sur ces splendides montures.$b$bNobles, puissantes... Elles font naître dans mon vieux cœur un sentiment de crainte mêlée de fascination.', '', 28153),
(137052, 'frFR', 'Le Flétrisseur va détruire cette vallée !', '', 28153),
(137051, 'frFR', 'La Horde a repris Ar\’gorok !', 'La Horde a repris Ar\’gorok !', 28153),
(137050, 'frFR', '', 'Un nouveau pouvoir vient d\’émerger au sein de ma maison. Avancez, $p de la Horde, que je puisse vous voir mieux.$b$b$gUn:Une:r; $r, $c de surcroît, et arborant une distinction de champion, rien que ça.$b$bMon seigneur des maléfices me dit que vous briguez ma faveur, mais pour cela, sachez que j\’exige quelque chose en retour, comme pour tous ceux qui souhaitent traiter avec moi.$b$BJe demande à tous un acte de foi…', 28153),
(137049, 'frFR', 'Allez, mettons un terme à cette secte !', '', 28153),
(137048, 'frFR', 'Sérieusement ? Moi, je crois qu\’on devrait accepter son offre !', '', 28153),
(137047, 'frFR', 'Bah ! J\’en ai vu d\’autres. C\’est mort, vous gagnerez pas.', '', 28153),
(137046, 'frFR', 'Votre peuple est condamné ! Rejoignez-moi… et vous serez sauvés.', '', 28153),
(137045, 'frFR', 'Entendu.', 'Entendu.', 28153),
(137041, 'frFR', 'Ah, bienvenue à vous ! Je vous en prie, servez-vous à boire et à manger. Et s\’il vous faut quoi que ce soit d\’autre, vous savez où me trouver.', '', 28153),
(137040, 'frFR', 'C\’est ici qu\’on prend soin de tous nos chevaux. Cavaliers et palefreniers passent leur temps à les bouchonner !', '', 28153),
(137039, 'frFR', '', 'Que souhaiteriez-vous demander au Loa des cieux ?', 28153),
(137038, 'frFR', '', 'Je vais aller me cacher avec Marcus !', 28153),
(137037, 'frFR', '', 'Merci ! J\’allais bientôt plus avoir de cailloux !', 28153),
(137036, 'frFR', 'Meurs pour cette intrusion !', '', 28153),
(137035, 'frFR', '', 'Le pouvoir de Zardrax coule dans mes veines !', 28153),
(137034, 'frFR', '', 'Le pouvoir de Zardrax, il va vous détruire !', 28153),
(137033, 'frFR', 'Je retourne aux ruines de Zul\’jan. On va voir si y a d\’autres tordus qu\’ont eu la bêtise de fuir pour rejoindre les Trolls de sang.', '', 28153),
(137032, 'frFR', 'Dommage que Kal\’dran, il ait été trop faible pour voir qu\’on allait gagner, pas vrai ?', '', 28153),
(137031, 'frFR', 'Bonne chance, $n. Tuez Zardrax avant qu\’il en corrompe d\’autres.', '', 28153),
(137030, 'frFR', 'Laisse faire $n. $GIl:Elle; va lui régler son compte, à ta maléficieuse de malheur.', '', 28153),
(137029, 'frFR', 'Je ne sais pas trop, Da\’jul… Même $n ne peut rien contre ça, on va tous y passer !', '', 28153),
(137028, 'frFR', '', 'Je vais retrouver Marcus ! On se voit là-bas !', 28153),
(137027, 'frFR', '', 'Un grand merci ! Ce n\’était pas très confortable là-dedans.', 28153),
(137026, 'frFR', '', 'C\’en est trop pour moi. Je mets les voiles !', 28153),
(137025, 'frFR', 'L\’Alliance a attaqué la mine !', '', 28153),
(137024, 'frFR', '$n a attaqué la mine !', '', 28153),
(137023, 'frFR', 'Je vais immédiatement commencer à remplir le lac.', '', 28153),
(137022, 'frFR', 'Cette essence est remarquablement puissante. C\’est sans doute l\’œuvre de Sumber.', '', 28153),
(137021, 'frFR', 'Je vais trouver Marcus et attendre avec lui. À tout à l\’heure !', '', 28153),
(137020, 'frFR', 'Oh, merci ! Qui aurait cru que ces Troggs étaient capables d\’utiliser la magie ?', '', 28153),
(137019, 'frFR', 'Je retourne auprès de Sumber.', '', 28153),
(137018, 'frFR', 'Je renais.', '', 28153),
(137017, 'frFR', 'Des sales histoires sur les Trolls de sang, j\’en ai entendu des tas quand j\’étais gosse. Mais ça, c\’est pire que tout ce qu\’on m\’a raconté.', '', 28153),
(137016, 'frFR', 'Kal\’dran ! Faut le rattraper, $n… même si ça veut dire le tuer.', '', 28153),
(137015, 'frFR', 'MAUDITS, on est tous MAUDITS ! Zardrax va nous sauver. N\’essayez pas de m\’arrêter ou je vous tue !', '', 28153),
(137013, 'frFR', 'Impossible... de... résister...', '', 28153),
(137012, 'frFR', 'Bienvenue au festival équestre de Norwington ! Nous sommes en pleins préparatifs, mais vous devez absolument participer aux festivités. Je n\’accepterai aucune réponse négative de votre part !', '', 28153),
(137011, 'frFR', 'Partez ! Il n\’y a plus rien pour vous ici !', '', 28153),
(137010, 'frFR', 'Maintenant, $c !', '', 28153),
(137009, 'frFR', 'N\’écoutez pas ses mensonges, ils ne vous apporteront que des malheurs !', '', 28153),
(137008, 'frFR', 'Le seigneur Valautomne est mort ! Sa soif de pouvoir aura entraîné sa chute !', '', 28153),
(137007, 'frFR', 'Le visage de G\’huun… je l\’ai vu… C\’est sans espoir… Sans espoir…', '', 28153),
(137006, 'frFR', 'C\’est sans espoir ! Pourquoi vous ne rejoignez pas Zardrax ?', '', 28153),
(137005, 'frFR', 'Merci encore, $c. Vous êtes $garrivé:arrivée; juste à temps !', '', 28153),
(137003, 'frFR', 'Vous avez condamné… ces terres…', '', 28153),
(137002, 'frFR', 'Vous ne devriez pas interrompre notre rituel, à moins de vouloir finir comme sacrifice !', '', 28153),
(137001, 'frFR', 'Ces gens ont perdu la tête ! Aidez-moi, $c !', '', 28153),
(137000, 'frFR', 'Le Maccarbre doit être apaisé ou nos malheurs continueront !', '', 28153),
(136999, 'frFR', 'Allez-vous enfin vous taire ? Votre mort servira le bien commun !', '', 28153),
(136998, 'frFR', 'Vous n\’avez pas le droit ! Au meurtre, à l\’assassin !', '', 28153),
(136997, 'frFR', 'On dirait que vous en avez tué un bon paquet. Je crois que je vais pouvoir retourner chez moi.', '', 28153),
(136996, 'frFR', 'Merci, $gétranger:étrangère; ! J\’ai bien cru que ces abeilles auraient ma peau !', '', 28153),
(136995, 'frFR', 'J\’en ai dans les yeux ! Mes yeux !', '', 28153),
(136994, 'frFR', 'Pas les abeilles, noooooooon !', '', 28153),
(136993, 'frFR', '$C ! Ça fait plaisir de voir un visage… une seconde, qu\’est-ce que c\’est que ça ?', '', 28153),
(136992, 'frFR', 'Gloire au Maccarbre !', 'Gloire au Maccarbre !', 28153),
(136991, 'frFR', 'Regardez, $n ! C\’est Magou, mon nouveau cheval. Il est beau, pas vrai ?$b$bCador me manque. C\’était une brave bête, juste un peu agitée par moments ! Cette fois, je vais tisser un lien profond avec Magou pour sentir quand il est nerveux.$b$bEt je vais continuer les leçons avec Melissa pour devenir un cavalier hors pair. Comme ça, Magou et moi, on fera une équipe du tonnerre. La meilleure de toutes !', '', 28153),
(136990, 'frFR', 'Rassemblez-vous devant le Maccarbre, initiés. Sa grâce nous protégera des malédictions qui touchent nos terres.', '', 28153),
(136989, 'frFR', '', 'Je ne vous remercierai jamais assez d\’avoir sauvé Eddie. C\’est un brave garçon et il a l\’étoffe d\’un bon cavalier.$b$bMais pour l\’instant, nous allons poursuivre nos leçons dans l\’enceinte du domaine.', 28153),
(136988, 'frFR', 'Trop... faible...', '', 28153),
(136987, 'frFR', 'Vous parlez et moi, j\’écoute, ma\’da. J\’y vais maintenant !', '', 28153),
(136986, 'frFR', 'C\’est Kejabu qui m\’envoie.', 'C\’est Kejabu qui m\’envoie.', 28153),
(136985, 'frFR', 'Rejoignez-moi, et vous aurez plus de pouvoir que vous en avez jamais rêvé !', '', 28153),
(136984, 'frFR', 'Si vous essayez de résister, nos forces, elles vous écraseront.', '', 28153),
(136983, 'frFR', 'Vous n\’avez pas le choix. Zuldazar est condamnée et G\’huun sera bientôt libre !', '', 28153),
(136982, 'frFR', 'Servez-moi et vous serez $Uépargné:épargnée;. C\’est G\’huun qui l\’a promis.', '', 28153),
(136981, 'frFR', 'G\’huun, il va tout consumer. C\’est sans espoir.', '', 28153),
(136980, 'frFR', 'Ha ha… Quelle puissance ! Mais G\’huun reste trop fort pour vous. Réfléchissez bien à mon offre…', '', 28153),
(136979, 'frFR', 'A… attendez. Peut-être qu\’on devrait rejoindre Zardrax ! Comment on va arrêter tout ça à nous seuls, de toute façon ?', '', 28153),
(136978, 'frFR', 'Jamais ! $n, montrez plutôt à cette liche ce que vous en pensez, de son « offre » !', '', 28153),
(136977, 'frFR', 'Servez-moi, et sauvez votre peau… Je partagerai même le pouvoir de G\’huun avec vous.', '', 28153),
(136976, 'frFR', 'G\’huun et les Trolls de sang, ils vont anéantir Zuldazar. Mais rien ne vous oblige à partager son sort.', '', 28153),
(136975, 'frFR', 'Très bien, liche, énoncez votre offre.', 'Très bien, liche, énoncez votre offre.', 28153),
(136974, 'frFR', 'Si vous voulez survivre à la destruction de Zuldazar, il faut vous joindre à moi !', '', 28153),
(136973, 'frFR', 'On est perdus ! Comment on peut espérer arrêter une chose pareille ?', '', 28153),
(136972, 'frFR', 'Ces Trolls de sang, ils en ont combien, des sources de pouvoir ?', '', 28153),
(136969, 'frFR', '', 'Excellent choix ! Maintenant suivez-moi, on va voir le boss.', 28153),
(136968, 'frFR', 'Ha ! Je le savais, vous avez fait le bon choix. Venez par ici, on va aller voir Pa\’ku.', '', 28153),
(136967, 'frFR', 'J\’aimerais choisir un autre Loa.', 'J\’aimerais choisir un autre Loa.', 28153),
(136966, 'frFR', 'Noooon ! Sale vermine de la Horde ! Je vais arracher la vie de ton corps.', '', 28153),
(136965, 'frFR', 'Arrêtez pas ! Faut pas que ça s\’arrête !', '', 28153),
(136964, 'frFR', 'Donnez-m\’en plus ! Donnez-moi tout !', '', 28153),
(136963, 'frFR', 'Plus ! Donnez-m\’en plus !', '', 28153),
(136962, 'frFR', 'Ouiiii... Ouiiii... OUIIIII !!!', '', 28153),
(136961, 'frFR', '', 'Z\’êtes en retard ! Si ma chauve-souris, elle crève à cause de vous, j\’vais décorer ma hutte avec votre caboche !', 28153),
(136960, 'frFR', 'Je ne m\’attendais pas à vous avoir à mes côtés dans ce combat.', '', 28153),
(136959, 'frFR', 'Ça... ça me va.', '', 28153),
(136958, 'frFR', '', 'À l\’avenir, nous nous en tiendrons à l\’enceinte du domaine pour les leçons d\’équitation, Eddie.', 28153),
(136957, 'frFR', '', 'Il n\’est plus temps de tergiverser, haut seigneur !', 28153),
(136956, 'frFR', 'Chef de guerre, il doit y avoir un autre moyen !', '', 28153),
(136954, 'frFR', '', 'Raal, triple idiot ! T\’as mis tout le monde en danger. Y a un rituel de sectateurs sanguinaires tout en haut.', 28153),
(136953, 'frFR', 'La dernière barrière… elle tombera… et G\’huun… il sera libre… !', '', 28153),
(136952, 'frFR', 'Non… Mon lien avec G\’huun… il se dissipe ?', '', 28153),
(136951, 'frFR', 'Le pouvoir de G\’huun prend de l\’ampleur ! Personne ne peut m\’arrêter !', '', 28153),
(136950, 'frFR', 'Imbécile ! Le pouvoir de G\’huun est en moi ! Je suis invincible !', '', 28153),
(136949, 'frFR', 'Approchez, $gprésomptueux petit:présomptueuse petite:r; $pr. Je souhaite m\’entretenir avec vous.', '', 28153),
(136948, 'frFR', '', 'Ha… Rien ni personne arrêtera Zardrax… Son pouvoir… il va nous aider à détruire… Zuldazar…', 28153),
(136947, 'frFR', '', 'Le pouvoir de Zardrax et de G\’huun, il est avec nous ! On est invincibles !', 28153),
(136945, 'frFR', 'Beau travail, $c. Vous avez gagné ma confiance et je vous aiderai à mon tour.', '', 28153),
(136944, 'frFR', '', 'Il a l\’air plus éveillé, pour sûr.', 28153),
(136943, 'frFR', 'Je crois qu\’il a bougé ! Ou alors… C\’était un coup de vent ?', '', 28153),
(136942, 'frFR', 'Les offrandes sont terminées. Entendez notre appel, Maccarbre, et bénissez-nous !', '', 28153),
(136941, 'frFR', 'Vous avez apporté les os ? Parfait ! Cette chose est friande d\’os, c\’est évident.', '', 28153),
(136940, 'frFR', 'Des entrailles ! Je suis sûr qu\’on pourra… en faire quelque chose.', '', 28153),
(136939, 'frFR', 'Je vois que vous avez apporté de l\’osier. Un choix évident, mais toujours correct.', '', 28153),
(136938, 'frFR', '', 'Non, non, non ! Ce sont des herbes aromatiques, pas rituelles ! Vous ne voyez pas la différence ?', 28153),
(136937, 'frFR', '', 'Que faites-vous avec cette paille ? On n\’est pas là pour rembourrer un épouvantail, bon sang !', 28153),
(136936, 'frFR', 'Oh, vous avez apporté les parchemins… Certes, ils pourraient être indispensables au réveil du Maccarbre, si… nous pouvions les déchiffrer.', '', 28153),
(136935, 'frFR', 'Des fruits ? Vous êtes $gsérieux:sérieuse; ? Mais oui, on dirait bien !', '', 28153),
(136934, 'frFR', 'Nous y sommes. Sylvanas va enfin répondre de ses crimes. Champions, à mes côtés !', '', 28153),
(136929, 'frFR', '<Heiro tapote doucement le tambourin qu\’il porte à la hanche et vous adresse un clin d\’œil.>', '', 28153),
(136927, 'frFR', 'Je doute que nous ayons l\’occasion de vous revoir, $n. Alors, merci.', '', 28153),
(136925, 'frFR', '', 'Vol\’dun nous a habitués à bien pire. Tout se passera bien.', 28153),
(136919, 'frFR', 'Maintenant que la voie est libre, je vais pouvoir rejoindre Melissa. Merci infiniment de m\’avoir sauvé !', '', 28153),
(136918, 'frFR', 'Le... le danger est écarté ? Les Troggs font vraiment peur !', '', 28153),
(136917, 'frFR', '$n a pris la crête de la Cognée !', '$n a pris la crête de la Cognée !', 28153),
(136916, 'frFR', 'Je vous laisse avec Loti. Dites-lui que la source de tous ces ennuis pourrait bien être à Zanchul.', '', 28153),
(136915, 'frFR', 'Hmm, quelque chose est… différent. Je sens une magie puissante à Zanchul.', '', 28153),
(136914, 'frFR', 'Il ne se passe pas une semaine sans que les Zandalari utilisent la magie du sang des hérétiques de Nazmir.', '', 28153),
(136913, 'frFR', 'Nos défenses deviennent faibles. La princesse Talanji a demandé plus de troupes mais, comme son père a pas agi assez vite, elle s\’est tournée vers la Horde.', '', 28153),
(136912, 'frFR', 'C\’est la première fois qu\’on voyait la vraie magie du sang. Pas ces tours de magie ridicules qu\’on fait dans les petites tribus.', '', 28153),
(136911, 'frFR', 'Il y a quelques années, le Cataclysme a fait bouger la terre ici. Nos portes au nord sont tombées et beaucoup de Trolls de sang féroces sont entrés.', '', 28153),
(136910, 'frFR', 'Je vais vous montrer les meilleurs endroits et vous aurez l\’honneur de lancer le totem sentinelle.', '', 28153),
(136909, 'frFR', 'Un petit sac de friandises pour chevaux gît au sol. En l\’inspectant de plus près, vous remarquez le nom Eddie brodé sur le tissu.$b$bIl a dû passer par ici, à son corps défendant, semble-t-il. Vous repérez des friandises éparpillées sur le sentier menant au sommet de la colline.', 'Un petit sac de friandises pour chevaux gît au sol. En l\’inspectant de plus près, vous remarquez le nom Eddie brodé sur le tissu.$b$bIl a dû passer par ici, à son corps défendant, semble-t-il. Vous repérez des friandises éparpillées sur le sentier menant au sommet de la colline.', 28153),
(136908, 'frFR', 'Je ne sais pas combien de temps encore nous survivrons face aux Sephraks…', '', 28153),
(136907, 'frFR', 'Vous venez manifestement pas de Zuldazar, ou vous sauriez que j\’étais le cuisinier attitré du général Jakra\’zet !$b$bJ\’ai été exilé quand il est tombé malade après avoir mangé un de mes plats... mais c\’était un coup monté !$b$bLes autres cuisiniers, ils étaient jaloux de moi ! L\’un d\’eux a forcément empoisonné la nourriture quand j\’avais le dos tourné !$b$bJe compte bien prouver mon innocence un jour, mais en attendant, je suis condamné à cuisiner des bousiers pour survivre.', '', 28153),
(136906, 'frFR', 'SOLDATS DE L\’ALLIANCE, TENEZ BON !', '', 28153),
(136905, 'frFR', 'Comment avez-vous atterri en Vol\’dun ?', 'Comment avez-vous atterri en Vol\’dun ?', 28153),
(136904, 'frFR', 'Vous posez des questions bien dangereuses, $c.\n\nJe n\’ai aucune raison de faire mystère de mon passé, mais d\’autres ici ne voient peut-être pas les choses du même œil.\n\nJ\’ai été condamné à l\’exil avec ma famille alors que je n\’étais qu\’un jeune garçon. Mon père avait contracté de lourdes dettes et à cette époque, les enfants étaient exilés avec leurs parents.\n\nJ\’étais seul et presque mort de soif quand Razgaji m\’a trouvé. Il m\’a soigné et m\’a élevé comme son propre fils. Depuis, je ne l\’ai plus quitté.', '', 28153),
(136903, 'frFR', 'Comment avez-vous atterri en Vol\’dun ?', 'Comment avez-vous atterri en Vol\’dun ?', 28153),
(136902, 'frFR', '', 'Vous, là. Votre visage, il m\’est inconnu. Venez me parler.', 28153),
(136901, 'frFR', '', 'Hir\’eek, ça lui a plu… mais il faut plus de sang ! Préparez un autre sacrifice !', 28153),
(136900, 'frFR', '', 'Grand Hir\’eek, Loa des chauves-souris et serviteur de G\’huun. Ce sacrifice, c\’est à toi qu\’on l\’offre !', 28153),
(136899, 'frFR', '', 'Le seigneur des maléfices Raal, y se trouve à l\’autre bout de la terrasse. Pensez à lui dire du mal de ses ancêtres de ma part.', 28153),
(136895, 'frFR', 'Votre heure a sonné, roi Anduin !', '', 28153),
(136894, 'frFR', 'Non. En tournant les talons, nous deviendrions leurs proies. Nous mourrons l\’arme à la main s\’il le faut !', '', 28153),
(136889, 'frFR', '', 'Parlez, ou je vous fais arracher la langue pour le prochain rituel.', 28153),
(136888, 'frFR', '', 'Hir\’eek nous offre ses enfants et le Dieu du sang nous offre son pouvoir. Ensemble, rien ne peut nous arrêter !', 28153),
(136887, 'frFR', '', 'Qu\’y a-t-il ? Dépêchez-vous de parler, ou vous serez la prochaine offrande.', 28153),
(136882, 'frFR', 'Attraper la corde', 'Attraper la corde', 28153),
(136878, 'frFR', '', 'La guerre exige une approche plus directe.', 28153),
(136876, 'frFR', '', 'Des serpents ! Attention !', 28153),
(136874, 'frFR', 'Vous avez parlé à Gonk ? C\’est le seigneur de la meute. C\’est grâce à lui si certains Sombrelances, ils sont devenus des druides.$b$bPour nous, il est réel. C\’est une voix qu\’on peut vraiment entendre, pas un simple fragment comme pour d\’autres.', 'Vous avez parlé à Gonk ? C\’est le seigneur de la meute. C\’est grâce à lui si certains Sombrelances, ils sont devenus des druides.$b$bPour nous, il est réel. C\’est une voix qu\’on peut vraiment entendre, pas un simple fragment comme pour d\’autres.', 28153),
(136872, 'frFR', 'Gonk, c\’est le Loa qui a enseigné le druidisme aux Trolls et qui leur a montré comment étendre leur influence aux autres Loas. On lui est éternellement reconnaissants.', 'Gonk, c\’est le Loa qui a enseigné le druidisme aux Trolls et qui leur a montré comment étendre leur influence aux autres Loas. On lui est éternellement reconnaissants.', 28153),
(136871, 'frFR', 'Les disciples de Pa\’ku, ils ne se remettent pas de l\’abandon du seigneur des maléfices Raal par la druidesse de guerre Loti. Tout ça, c\’est triste et pas professionnel du tout.', 'Les disciples de Pa\’ku, ils ne se remettent pas de l\’abandon du seigneur des maléfices Raal par la druidesse de guerre Loti. Tout ça, c\’est triste et pas professionnel du tout.', 28153),
(136870, 'frFR', 'Les disciples de Gonk se remettent pas de l\’abandon de la druidesse de guerre Loti par le seigneur des maléfices Raal. Tout ça, c\’est triste et pas professionnel du tout.', 'Les disciples de Gonk se remettent pas de l\’abandon de la druidesse de guerre Loti par le seigneur des maléfices Raal. Tout ça, c\’est triste et pas professionnel du tout.', 28153),
(136869, 'frFR', 'Quoi que vous fassiez, il ne faut pas écouter les mensonges des disciples de Gonk. Ils sont juste jaloux de la grandeur de notre Loa, Pa\’ku.', 'Quoi que vous fassiez, il ne faut pas écouter les mensonges des disciples de Gonk. Ils sont juste jaloux de la grandeur de notre Loa, Pa\’ku.', 28153),
(136868, 'frFR', 'Je sers Pa\’ku, divinité des vents et protectrice de notre marine. Il n\’y en a pas deux, des Loas comme elle. Vous feriez mieux de faire appel à elle plutôt qu\’aux autres. Ils ne sont pas dignes de confiance.', 'Je sers Pa\’ku, divinité des vents et protectrice de notre marine. Il n\’y en a pas deux, des Loas comme elle. Vous feriez mieux de faire appel à elle plutôt qu\’aux autres. Ils ne sont pas dignes de confiance.', 28153),
(136867, 'frFR', 'Hmm, $p. Les Loas, ils murmurent votre nom. Votre arrivée à Zuldazar, elle devrait faire des vagues.', 'Hmm, $p. Les Loas, ils murmurent votre nom. Votre arrivée à Zuldazar, elle devrait faire des vagues.', 28153),
(136866, 'frFR', 'Pa\’ku, c\’est la Loa des vents et la protectrice de nos éclaireurs et de notre flotte. Elle est impulsive et elle tient à sa liberté. Adressez-vous à son champion, le seigneur des maléfices Raal, si vous voulez en savoir plus.', 'Pa\’ku, c\’est la Loa des vents et la protectrice de nos éclaireurs et de notre flotte. Elle est impulsive et elle tient à sa liberté. Adressez-vous à son champion, le seigneur des maléfices Raal, si vous voulez en savoir plus.', 28153),
(136865, 'frFR', 'Ha ! L\’étoile montante de la Horde. Vous allez impressionner le seigneur des maléfices Raal. Ceux qui sont dans ses petits papiers, ils sont aussi dans ceux de Pa\’ku. Et dans les miens.', 'Ha ! L\’étoile montante de la Horde. Vous allez impressionner le seigneur des maléfices Raal. Ceux qui sont dans ses petits papiers, ils sont aussi dans ceux de Pa\’ku. Et dans les miens.', 28153),
(136864, 'frFR', 'On ne veut pas de vous ici.', 'On ne veut pas de vous ici.', 28153),
(136863, 'frFR', 'Je n\’ai rien à vous dire.', 'Je n\’ai rien à vous dire.', 28153),
(136862, 'frFR', 'Vous ne semblez pas trop savoir où vous allez. Sachez que vous n\’avez rien à faire ici.', 'Vous ne semblez pas trop savoir où vous allez. Sachez que vous n\’avez rien à faire ici.', 28153),
(136861, 'frFR', 'Sans caste ? Bah !', 'Sans caste ? Bah !', 28153),
(136860, 'frFR', 'Ne m\’adressez pas la parole, rustre.', 'Ne m\’adressez pas la parole, rustre.', 28153),
(136859, 'frFR', '', 'Comme je m\’y attendais, mon travail est irréprochable. Mais quelque chose doit boucher la fontaine. Vous voulez bien aller voir ?', 28153),
(136858, 'frFR', '', 'Allons jeter un coup d\’œil à cette fontaine.', 28153),
(136857, 'frFR', 'J\’accomplirai mon prochain rituel avec votre sang.', 'J\’accomplirai mon prochain rituel avec votre sang.', 28153),
(136856, 'frFR', 'Sale racaille de la Horde !', 'Sale racaille de la Horde !', 28153),
(136855, 'frFR', 'Vous ne pouvez pas tous nous arrêter !', 'Vous ne pouvez pas tous nous arrêter !', 28153),
(136854, 'frFR', 'Si vous croyez que je suis le seul à utiliser la magie du sang ici, vous allez avoir une mauvaise surprise.', 'Si vous croyez que je suis la seule à utiliser la magie du sang ici, vous allez avoir une mauvaise surprise.', 28153),
(136853, 'frFR', 'Bah ! Ce n\’est pas un larbin de la Horde qui va me damer le pion !', 'Bah ! Ce n\’est pas un larbin de la Horde qui va me damer le pion !', 28153),
(136852, 'frFR', 'Dites donc, les volatiles ! Vous n\’étiez pas censés repérer les Trolls de sang ? Pourquoi est-ce qu\’on doit faire votre boulot à votre place ?', 'Dites donc, les volatiles ! Vous n\’étiez pas censés repérer les Trolls de sang ? Pourquoi est-ce qu\’on doit faire votre boulot à votre place ?', 28153),
(136851, 'frFR', 'Vous ne gâcherez pas notre journée rituelle. Loti, elle ne vous laissera pas faire.', 'Vous ne gâcherez pas notre journée rituelle. Loti, elle ne vous laissera pas faire.', 28153),
(136850, 'frFR', 'Vous, les fanatiques du vol, vous serez la mort de Zandalar.', 'Vous, les fanatiques du vol, vous serez la mort de Zandalar.', 28153),
(136849, 'frFR', 'Raal, il a intérêt à bien se tenir ou vous finirez tous dans l\’estomac du Loa des rois.', 'Raal, il a intérêt à bien se tenir ou vous finirez tous dans l\’estomac du Loa des rois.', 28153),
(136848, 'frFR', '', 'Cette armée est gigantesque… Vous n\’avez qu\’un mot à dire et je nous téléporterai tous à l\’abri.', 28153),
(136846, 'frFR', 'Vous suivez encore Loti ? Ha ! Vous êtes encore plus bête qu\’une bouse de bruto.', 'Vous suivez encore Loti ? Ha ! Vous êtes encore plus bête qu\’une bouse de bruto.', 28153),
(136845, 'frFR', 'À présent, nous avons l\’avantage du nombre.', '', 28153),
(136844, 'frFR', 'Un jour, Raal, c\’est lui qui commandera, et vous, les fanatiques des raptors, il vous renverra dans votre cambrousse fissa !', 'Un jour, Raal, c\’est lui qui commandera, et vous, les fanatiques des raptors, il vous renverra dans votre cambrousse fissa !', 28153),
(136843, 'frFR', 'Votre Loa, c\’est Gonk qu\’il s\’appelle. Honte à vous.', 'Votre Loa, c\’est Gonk qu\’il s\’appelle. Honte à vous.', 28153),
(136842, 'frFR', 'Saletés de druides, vous passez votre temps à racler les fonds de tiroir. Vous ne valez pas mieux que les Gurubashi.', 'Saletés de druides, vous passez votre temps à racler les fonds de tiroir. Vous ne valez pas mieux que les Gurubashi.', 28153),
(136841, 'frFR', 'Vous valez pas mieux que moi. Vous avez mon sang… sur les mains.', '', 28153),
(136840, 'frFR', 'Ici, c\’est tuer ou être tué ! Pour survivre, faut penser qu\’à soi.', '', 28153),
(136838, 'frFR', '<Vous découvrez le cadavre encore tiède de Cador, le cheval d\’Eddie.>$b$b<Des miettes éparses mènent droit au sommet de la colline. Eddie semble avoir laissé une trace de son passage.>', '<Vous découvrez le cadavre encore tiède de Cador, le cheval d\’Eddie.$b$bReste à espérer que vous n\’arrivez pas trop tard pour sauver son maître.>', 28153),
(136837, 'frFR', 'Morveux trop bon !', '', 28153),
(136836, 'frFR', 'Je suis là ! C\’est lui qui a la clé ! Pitié, aidez-moi !', '', 28153),
(136835, 'frFR', '', 'Allons-y, $n. Le seigneur Norwington aura ma tête s\’il arrive malheur à son fils !', 28153),
(136832, 'frFR', 'Nous sommes une tribu de parias de Zuldazar, condamnés à l\’exil dans le désert pour y mourir à petit feu.\n\nQuelques-uns d\’entre nous ont été accusés à tort des crimes qui nous ont conduits ici, mais les autres n\’ont pas volé leur sort.\n\nLa seule chose qui nous importe désormais, c\’est notre survie.\n\nTant que vous obéirez aux règles de la tribu, vous aurez une place parmi nous. Mais transgressez nos lois et vous découvrirez que notre justice est encore plus expéditive que celle du roi Rastakhan.', '', 28153),
(136831, 'frFR', 'Vous faut quoi, ma\’da ?', '', 28153),
(136830, 'frFR', 'Quoi ? Vous… vous êtes pas le prochain sacrifice, si ?', '', 28153),
(136829, 'frFR', 'Les prêtresses… elles vont tous nous tuer !', '', 28153),
(136828, 'frFR', 'Sans votre déguisement, ça va être beaucoup plus sanglant.', '', 28153),
(136827, 'frFR', 'Parlez-moi de votre tribu.', 'Parlez-moi de votre tribu.', 28153),
(136825, 'frFR', '', 'C\’est le bouclier de Rakera… Où elle est ? Qu\’est-ce que vous lui avez fait ?', 28153),
(136824, 'frFR', 'C\’est Jakra\’zet le coupable, pas moi. Je serais plus en vie sans Rakera.', '', 28153),
(136823, 'frFR', '', 'Meera, la caravane ! Stop ! J\’aperçois quelque chose là-devant !', 28153),
(136822, 'frFR', '', 'Comment Rakera pourrait survivre dans un tel endroit ?', 28153),
(136820, 'frFR', '', 'Vous vous rendez compte, ce désert était autrefois le joyau de l\’empire troll ! Toute une jungle luxuriante… engloutie par les dunes.', 28153),
(136819, 'frFR', '', 'Kiro n\’a aucune raison de s\’inquiéter, j\’ai l\’habitude ! Mais vous feriez mieux de vous accrocher, au cas où.', 28153),
(136818, 'frFR', '', 'Je le suis toujours !', 28153),
(136816, 'frFR', 'Mais seulement avec l\’aide de notre $gami:amie; $c, là. Son mojo, c\’est du bon, je le sens d\’ici.', '', 28153),
(136815, 'frFR', 'Vous êtes bien comme tous les autres tarés qui vont en Naz… Quoi ?', 'Vous êtes bien comme tous les autres tarés qui vont en Naz… Quoi ?', 28153),
(136814, 'frFR', 'Bah ! Regardez bien, je vais vous prouver que ce type a perdu la boule.', 'Bah ! Regardez bien, je vais vous prouver que ce type a perdu la boule.', 28153),
(136813, 'frFR', 'Je vais raconter à tout le camp comment vous m\’avez sauvé !', '', 28153),
(136812, 'frFR', 'Je suis libre ! Je le crois pas !', '', 28153),
(136811, 'frFR', 'Si j\’arrive à reprendre des forces, je pourrai peut-être le battre…', '', 28153),
(136810, 'frFR', 'Et ça, c\’est Urok, le monstre mort-vivant qui va tous vous tuer.', '', 28153),
(136809, 'frFR', 'Imbécile ! Il va vous dévorer tout cru !', '', 28153),
(136808, 'frFR', 'Chuuut. Urok, il est tout près… Je sens l\’odeur de ses dents !', '', 28153),
(136807, 'frFR', 'Montrez-moi Urok, la Terreur de la mangrove.', 'Montrez-moi Urok, la Terreur de la mangrove.', 28153),
(136806, 'frFR', '', 'Eddie !!!', 28153),
(136805, 'frFR', 'Pa\’ku, Pa\’ku, Pa\’ku, c\’est la Loa des élus.', 'Pa\’ku, Pa\’ku, Pa\’ku, c\’est la Loa des élus.', 28153),
(136804, 'frFR', 'Vous aimez le ciel ? Moi aussi. Alors rejoignez Pa\’ku. C\’est la Loa des élus.', 'Vous aimez le ciel ? Moi aussi. Alors rejoignez Pa\’ku. C\’est la Loa des élus.', 28153),
(136803, 'frFR', 'N\’hésitez plus, rejoignez Pa\’ku !', 'N\’hésitez plus, rejoignez Pa\’ku !', 28153),
(136800, 'frFR', 'Tout va bien, il est calme ! Pas besoin de... AAAAH !', '', 28153),
(136799, 'frFR', '', 'Allons, Eddie, ne laisse pas Cador s\’agiter.', 28153),
(136798, 'frFR', '', 'Misérable avorton ! Hir\’eek voudrait même pas de vous comme sacrifice !', 28153),
(136797, 'frFR', '', 'Venez. Votre heure, elle a sonné.', 28153),
(136789, 'frFR', 'Salut, $n. On se reverra bientôt.', '', 28153),
(136788, 'frFR', 'Je dois retourner à Zo\’bal. Il me reste des âmes à récupérer pour pouvoir payer ma dette.', '', 28153),
(136780, 'frFR', 'Le chassenuit lié émet un gémissement gargouillant.', '', 28153),
(136779, 'frFR', 'Le chassenuit lié entend quelque chose à proximité !', '', 28153),
(136778, 'frFR', 'Le chassenuit lié hume l\’air.', '', 28153),
(136769, 'frFR', '', 'Meeki ne méritait pas un tel sort, mais je sais bien que vous n\’y êtes pour rien.\n\nMerci de l\’avoir retrouvé. La souffrance reste infiniment préférable à une vie de regrets.\n\nNous sillonnons ces dunes en famille et vous faites désormais partie des nôtres. Notre caravane vous accueillera toujours à bras ouverts.', 28153),
(136768, 'frFR', 'Faut garder la tête froide, ou sinon, vos ennemis, ils sentiront votre faiblesse.', '', 28153),
(136767, 'frFR', 'Arrêtez ça !', '', 28153),
(136766, 'frFR', 'J-j-j\’ai hâte d\’entendre Ahna chanter vos aventures.\n\nC\’est une excellente m-m-musicienne. V-v-vous devriez lui raconter votre histoire !\n\nT-t-tous ceux que nous croiserons entendront la geste |2 $p, vous pouvez me croire !', '', 28153),
(136764, 'frFR', '', 'Une tragédie, des pirates morts-vivants, un trésor maudit, une mutinerie... Cette aventure a tout pour passer à la postérité.\n\nJ\’ai déjà d\’excellentes idées pour le premier couplet de ma « Ballade de l\’intrépide $p ».\n\nVous serez une véritable légende pour les générations à venir, du moins au sein de cette caravane.\n\nJe m\’y mettrai juste après la sieste.', 28153),
(136763, 'frFR', 'Battez-vous comme si votre vie, elle en dépendait !', '', 28153),
(136762, 'frFR', 'Si on se bat, c\’est pour protéger les gens, mais aussi, c\’est pour l\’avenir des Zandalari. Et ça, c\’est pas rien.', '', 28153),
(136761, 'frFR', 'Faut toucher vite, mais faut toujours faire gaffe aux soldats qui vous entourent.', '', 28153),
(136760, 'frFR', 'La cible, faut la frapper de toutes vos forces... mais faut aussi garder la tête froide.', '', 28153),
(136759, 'frFR', 'J\’ai déjà fait des tas de tours de manège, ça ne doit pas être si différent !', '', 28153),
(136758, 'frFR', '', 'Tiens bien les rênes, Eddie.', 28153),
(136757, 'frFR', '', 'Le seigneur Norwington m\’a chargée de donner des leçons d\’équitation à son fils. Il s\’en sort plutôt bien au manège, mais je ne suis pas rassurée à l\’idée de sortir du domaine. Je ne suis pas sûre qu\’il saurait maîtriser sa monture si elle paniquait.$b$bEnfin, espérons que ça ne se produira pas !', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136756, 'frFR', 'Cador n\’est pas du genre à s\’affoler. C\’est un bon cheval !', '', 28153),
(136755, 'frFR', 'Je crois qu\’il m\’écoute, regardez ses oreilles !', '', 28153),
(136754, 'frFR', 'C\’est ce que je fais !', '', 28153),
(136753, 'frFR', '', 'Rien ne presse, vas-y doucement pour éviter qu\’il ne s\’affole.', 28153),
(136752, 'frFR', '', 'Fais en sorte qu\’il se concentre sur toi. Ce ne sont pas les distractions qui manquent par ici !', 28153),
(136751, 'frFR', '', 'Eddie, tourne avec ta jambe, pas avec ta main.', 28153),
(136750, 'frFR', 'Humpf… Un désert au beau milieu des marais ? Qu\’est-ce que ces maudits Sephraks mijotent encore ?', '', 28153),
(136747, 'frFR', 'J\’ai échappé à ces affreux saurolisques grâce à vous, merci ! C\’est la dernière fois que je vais près de la rivière sans personne… au moins pour quelques années !', '', 28153),
(136746, 'frFR', 'Ohé ? Y a quelqu\’un ?', '', 28153),
(136745, 'frFR', 'L\’Alliance n\’est pas de taille face à nous. Pour la Horde !', '', 28153),
(136744, 'frFR', 'Le port de Zem\’lan sera à moi !', '', 28153),
(136741, 'frFR', 'Sur\’jan, ne raconte pas n\’importe quoi ! On ne quittera pas Nazmir après ça. Moi, je ne remettrai jamais les pieds à Zuldazar.', '', 28153),
(136740, 'frFR', 'Grâce à votre aide, je serai bientôt assez fort pour qu\’on se débarrasse d\’Urok. Je vous attends ici, le temps de préparer le prochain rituel.', '', 28153),
(136738, 'frFR', 'Ces monstres allaient me dévorer !', '', 28153),
(136732, 'frFR', 'Qu\’est-ce que tu racontes, Sur\’jan ? Hmm, tu n\’as peut-être pas tort.', '', 28153),
(136731, 'frFR', 'Sur\’jan, c\’est à moi de m\’en occuper, tu sais. Je déteste me tourner les pouces en regardant les autres travailler.', '', 28153),
(136730, 'frFR', 'Je pars devant, histoire de préparer le terrain avant notre combat contre Urok.', '', 28153),
(136729, 'frFR', 'Papa a dit que je pouvais participer aux festivités cette année. Je vais enfin apprendre à monter à cheval !', '', 28153),
(136728, 'frFR', 'On ne plaisante pas avec l\’équilibre naturel.\n\nTais-toi, Sur\’jan. Bien sûr que je m\’en préoccupe, de l\’équilibre naturel… Enfin, si on veut. Mais ça, l\’autre n\’a pas besoin de le savoir.', '', 28153),
(136727, 'frFR', 'Ces marais, ils sont infestés d\’horreurs à pattes. Si vous voulez avoir une chance de survivre, va falloir en devenir une vous aussi.', '', 28153),
(136726, 'frFR', 'La malédiction… elle est levée ? Je suis enfin… libre ?', '', 28153),
(136725, 'frFR', 'Cette contrée, elle est maudite… Personne ne sort d\’ici vivant !', '', 28153),
(136724, 'frFR', '', 'Des monstres se terrent dans les ombres de Zem\’lan.\n\nPrenez garde à ne pas les rejoindre, vous aussi.', 28153),
(136723, 'frFR', 'En f-f-famille, on se serre les coudes quoi qu\’il arrive.', '', 28153),
(136722, 'frFR', 'Et je ne plaisante pas, hein. Ce Troll, je veux le voir mort. Comme Urok. Bonne chasse.', '', 28153),
(136721, 'frFR', 'Ne dis pas n\’importe quoi, Sur\’jan, il n\’y a aucune chance que l\’autre croie que je plaisante. D\’accord, d\’accord, je vais tirer les choses au clair.', '', 28153),
(136720, 'frFR', 'C\’était chouette de faire équipe avec vous. Si vous croisez un Troll qui s\’appelle Krugah, liquidez-le ! Ha !', '', 28153),
(136719, 'frFR', 'Il n\’y a pas une minute à perdre. Dépêchons-nous de nous occuper d\’Urok !', '', 28153),
(136718, 'frFR', 'OUI ! C\’est l\’heure de vérité… Le moment est venu d\’anéantir Urok !', '', 28153),
(136717, 'frFR', 'Je le sens… Mon pouvoir, il me revient !', '', 28153),
(136713, 'frFR', 'Ha ha ! J\’y suis presque… Bientôt, on sera prêts à tuer Urok !', '', 28153),
(136712, 'frFR', 'Excellent… Mon pouvoir, je sens qu\’il me revient !', '', 28153),
(136711, 'frFR', 'Ah… ENCORE ! Du pouvoir, il va nous en falloir encore plus pour tuer Urok !', '', 28153),
(136710, 'frFR', 'Tout le matériel nécessaire, il est là… Maintenant, c\’est l\’heure de gagner en force !', '', 28153),
(136698, 'frFR', 'C\’est nous les chanceux, pas vous. Pas encore.', '', 28153),
(136697, 'frFR', 'Ce qu\’elle cherche doit s\’obtenir par sacrifice.', '', 28153),
(136696, 'frFR', '', 'Au-delà de cette mer d\’étoiles, il n\’y a que d\’infinies ténèbres.', 28153),
(136695, 'frFR', '', 'Dites à mon papa que je lui pardonne.', 28153),
(136694, 'frFR', '', 'Elle vous trahira, si ce n\’est pas déjà fait…', 28153),
(136693, 'frFR', '', 'Vous mourrez dans la solitude.', 28153),
(136692, 'frFR', '', 'Le maître vous attend…', 28153),
(136691, 'frFR', '', 'Il est réveillé. Et il a senti votre présence.', 28153),
(136690, 'frFR', '', 'Vous serez bientôt des nôtres.', 28153),
(136689, 'frFR', '', 'Je sais ce que vous avez fait.', 28153),
(136688, 'frFR', '', 'Vous entendez un rire lointain.', 28153),
(136687, 'frFR', '', 'Vous sentez qu\’on vous observe.', 28153),
(136686, 'frFR', '', 'Une présence vous observe.', 28153),
(136685, 'frFR', '', 'La suivante fantomatique s\’esclaffe et s\’enfuit.', 28153),
(136684, 'frFR', 'Notre prochaine rencontre sera la dernière...', '', 28153),
(136683, 'frFR', 'Votre âme sera mienne !', '', 28153),
(136681, 'frFR', 'Vous ici ? Sacrilège ! Le courroux de Xibala, il va s\’abattre sur vous !', 'Vous ici ? Sacrilège ! Le courroux de Xibala, il va s\’abattre sur vous !', 28153),
(136680, 'frFR', '', 'Les meilleurs mojos et les plus chouettes babioles du sud, c\’est chez Wunja que ça se passe !', 28153),
(136679, 'frFR', 'Pauvre $gmortel:mortelle;. Xibala va vous anéantir !', 'Pauvre $gmortel:mortelle;. Xibala va vous anéantir !', 28153),
(136678, 'frFR', 'On va monter sur le dos d\’Ata le Seigneur ailé pour voyager. Grimpez et gardez bien l\’œil ouvert.', '', 28153),
(136677, 'frFR', 'Mon Loa dit toujours : « Quand on ne voit pas la source de corruption, il faut aller plus haut. »', '', 28153),
(136676, 'frFR', 'L\’approche de Loti est trop terre à terre. Je préfère celle du pterreurdactyle.', '', 28153),
(136674, 'frFR', 'Prêt à patrouiller.', 'Prête à patrouiller.', 28153),
(136673, 'frFR', '', 'Je suis Loti, la druidesse de guerre ! Je suis la porte-parole de Gonk, Loa de la métamorphose et maître de la chasse.$b$bJe suis aussi membre du conseil zanchuli, mais vous deviez déjà le savoir.', 28153),
(136672, 'frFR', 'Le portefaix adresse un signe de tête au garde zandalari.', '', 28153),
(136671, 'frFR', 'Le garde vous examine attentivement.', '', 28153),
(136670, 'frFR', 'Le garde prend acte de votre présence.', '', 28153),
(136669, 'frFR', 'Que ça te serve de leçon !', 'Que ça te serve de leçon !', 28153),
(136668, 'frFR', 'Le garde s\’incline sur votre passage.', '', 28153),
(136667, 'frFR', 'Le garde vous adresse un signe de tête.', '', 28153),
(136662, 'frFR', 'Vous êtes devant le seigneur des maléfices Raal, membre du conseil zanchuli, grand prêtre de l\’auguste Loa Pa\’ku, divinité des vents et protectrice de notre marine.\n\nAlors, qu\’est-ce qui vous amène ?', '', 28153),
(136657, 'frFR', 'Du boulot, encore du boulot !', '', 28153),
(136655, 'frFR', '', 'Que la Lumière vous apaise, $c.', 28153),
(136654, 'frFR', 'Crétin de Sur\’jan ! Pourquoi tu déballes tout devant les gens ? Ils vont te prendre pour un cinglé !', '', 28153),
(136653, 'frFR', 'Je m\’en vais préparer le rituel. Dès que j\’aurai récupéré mon pouvoir, on pourra tuer Urok.', '', 28153),
(136652, 'frFR', 'Je sais, vous me prenez pour un fou parce que je vis en Nazmir, mais il faut quand même m\’écouter ! Vous êtes tous morts si vous ne m\’aidez pas !', '', 28153),
(136651, 'frFR', 'Je sais que vous me prenez pour un fou, mais il faut m\’aider !', '', 28153),
(136650, 'frFR', 'Écoutez-moi au moins, j\’ai besoin de votre aide !', '', 28153),
(136649, 'frFR', 'Ça y est, ses protections sont neutralisées ! Il ne reste plus qu\’à l\’achever !', '', 28153),
(136648, 'frFR', '', 'Par G\’huun, je reviens à la vie !', 28153),
(136647, 'frFR', 'Là, ça se complique. Je vous laisse faire. Moi, je vous attendrai devant l\’antre d\’Urok.', '', 28153),
(136646, 'frFR', 'HA ! C\’est dans la poche ! Je t\’avais bien dit qu\’on pouvait le battre, Sur\’jan !', '', 28153),
(136645, 'frFR', 'Vous, réglez son compte à cette sorcière ! Les tas d\’os qu\’elle appelle ses « serviteurs », ils vont rencontrer le vrai seigneur de la mort !', '', 28153),
(136644, 'frFR', 'Urok, il est protégé par les totems ! Utilisez ma torche pour les brûler !', '', 28153),
(136643, 'frFR', '<Le sac à dos est recouvert de sable, mais son contenu semble être intact.>', '', 28153),
(136642, 'frFR', '', 'Je vous avais pourtant dit de ne pas approcher cet endroit ! On a failli y rester !', 28153),
(136641, 'frFR', 'La mort vous attend !', 'La mort vous attend !', 28153),
(136640, 'frFR', 'Une intrusion !', 'Une intrusion !', 28153),
(136639, 'frFR', 'Rejoignez-nous !', 'Rejoignez-nous !', 28153),
(136638, 'frFR', '', 'Nul ne compromettra mon œuvre ! Écrasez cet insecte !', 28153),
(136637, 'frFR', 'Allez, allez, allez !', 'Allez, allez, allez !', 28153),
(136632, 'frFR', 'Ha ha ! Je vais lui régler son compte !', '', 28153),
(136615, 'frFR', '', 'Debout, serviteurs ! Levez-vous et cet imbécile de Loa, détruisez-le !', 28153),
(136614, 'frFR', 'J\’ai besoin de votre aide… Il y a un horrible monstre qui approche et je n\’arriverai pas à le tuer tout seul !', '', 28153),
(136613, 'frFR', '', 'T\’as du cran, mais tu subiras le même sort que tous ceux qui se refusent à G\’huun !', 28153),
(136611, 'frFR', 'Personne, il dit à Bwonsamdi ce qu\’il doit faire ! Alors comme ça, tu te crois capable de m\’affronter ?', '', 28153),
(136610, 'frFR', 'Hmm… T\’as pas l\’air d\’être bête, Trollesse. Pourtant, tu viens m\’interrompre dans mon propre temple.', '', 28153),
(136609, 'frFR', '', 'C\’est ta dernière chance de te soumettre au Dieu du sang. Soumets-toi… ou meurs !', 28153),
(136608, 'frFR', '', 'Bwonsamdi ! Tu sors enfin de cette ruine qui te sert de cachette.', 28153),
(136607, 'frFR', 'Restez pas là les bras croisés ! Allez, au boulot !', '', 28153),
(136605, 'frFR', 'Commençons.', 'Commençons.', 28153),
(136604, 'frFR', 'Le rite de lien, c\’est un mojo vieux comme le monde. Grâce à lui, l\’âme de tout ce que vous tuerez, elle reviendra à Bwonsamdi. Acceptez ce rite, et notre pacte, il sera scellé.$b$bAlors, marché conclu ?', '', 28153),
(136603, 'frFR', '', 'Que voulez-vous ?', 28153),
(136602, 'frFR', '', 'Mes hommes sont prêts à défendre les villageois. Devrions-nous commencer l\’évacuation ?', 28153),
(136601, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(136600, 'frFR', 'Ça, c\’était pas gentil, Petit-Doigt. Vilain diablosaure, vilain !', 'Ça, c\’était pas gentil, Petit-Doigt. Vilain diablosaure, vilain !', 28153),
(136599, 'frFR', 'Retrouvez-moi à la cour des Esprits. Il est temps de parachever notre… contrat.', '', 28153),
(136591, 'frFR', 'C\’est pas une discussion, ma sœur. On a reçu des ordres de la princesse.', '', 28153),
(136590, 'frFR', '', 'Et ensuite, elle m\’a ordonné de m\’assurer que, je cite, « la belle gueule » et $n rallient Nazmir dès que possible.', 28153),
(136589, 'frFR', 'Le traînard s\’est retourné contre ses maîtres !', '', 28153),
(136588, 'frFR', 'L\’esclave semble être momentanément incapable d\’agir.', '', 28153),
(136587, 'frFR', 'L\’esclave est devenu frénétique !', '', 28153),
(136581, 'frFR', 'Occupez-vous de $gcet intrus:cette intruse;, gardemer. Que ma volonté soit faite.', '', 28153),
(136578, 'frFR', 'Dernier hommage', '', 28153),
(136577, 'frFR', 'Je mettrais ma main à couper que nous trouverons d\’autres armes Corsandre sur les quais. Nous devons savoir qui les achète.', '', 28153),
(136576, 'frFR', '', 'Innombrables sont mes sœurs… Kul Tiras tombera…', 28153),
(136575, 'frFR', '', 'Vous ne triompherez pas ! Tous plieront devant le Sabbat !', 28153),
(136574, 'frFR', '', 'Subissez mon courroux !', 28153),
(136573, 'frFR', '', 'Impressionnant… Mais il en faut plus pour venir à bout d\’une matrone du Sabbat malecarde !', 28153),
(136572, 'frFR', '', 'Mais vous avez fait tout cela en vain. Voyez ce qu\’il advient des ennemis du Sabbat ! Acolytes, éradiquez ce pion inutile !', 28153),
(136571, 'frFR', '', 'Alors, comme ça, vous avez retourné l\’une de nos créations contre nous… Et vous vous gargarisez de votre prouesse, je parie.', 28153),
(136570, 'frFR', 'Je n\’avais jamais vu une telle activité ici. Quelque chose se trame, c\’est sûr.', '', 28153),
(136569, 'frFR', 'Corsaires, mercenaires… même les pirates sont les bienvenus. De toute évidence, la ville… est haute en couleur.', '', 28153),
(136568, 'frFR', 'Port-Liberté est un port franc. Contrairement à Boralus, la ville ne décide pas quels bateaux ont le droit d\’amarrer.', '', 28153),
(136567, 'frFR', '', 'Je regrette, $c, mais nous n\’avons plus d\’algues. Avec l\’épidémie qui sévit ici, les gens ne sont pas en état d\’aller en récolter en mer. Veuillez présenter mes excuses à Therold.', 28153),
(136566, 'frFR', '', 'Mes sœurs me vengeront…', 28153),
(136565, 'frFR', '', 'Vous n\’auriez pas dû intervenir !', 28153),
(136564, 'frFR', 'Vous avez des algues ? Therold en a besoin pour préparer un antidote.', 'Vous avez des algues ? Therold en a besoin pour préparer un antidote.', 28153),
(136563, 'frFR', '', 'La matrone vous réduira à néant…', 28153),
(136562, 'frFR', '', 'Cette ville appartient au Sabbat !', 28153),
(136561, 'frFR', '', 'Il y a tant à faire et si peu de temps !$b$bBénir les pêcheurs et leur matériel, scruter les marées en quête de signes annonciateurs, prier pour que nos marins nous reviennent sains et saufs...', 28153),
(136560, 'frFR', '', 'Vous servirez le Sabbat…', 28153),
(136559, 'frFR', '', 'Le Sabbat consumera tout !', 28153),
(136558, 'frFR', 'Les sirènes sont de sortie aujourd\’hui, mais ne quittez pas la terre ferme. Restez loin des îles et la chance vous sourira.', 'Les sirènes sont de sortie aujourd\’hui, mais ne quittez pas la terre ferme. Restez loin des îles et la chance vous sourira.', 28153),
(136557, 'frFR', 'La mer est agitée à l\’est, mais c\’est le calme plat par ici, à l\’ouest.', 'La mer est agitée à l\’est, mais c\’est le calme plat par ici, à l\’ouest.', 28153),
(136556, 'frFR', 'Ma bénédiction vous protégera jusque dans l\’eau.', 'Ma bénédiction vous protégera jusque dans l\’eau.', 28153),
(136555, 'frFR', 'Envoyez les pêcheurs sur le quai près du marché. Les poissons pullulent, aujourd\’hui.', 'Envoyez les pêcheurs sur le quai près du marché. Les poissons pullulent, aujourd\’hui.', 28153),
(136554, 'frFR', 'Grâce à vos conseils avisés, on ne risque rien.', 'Grâce à vos conseils avisés, on ne risque rien.', 28153),
(136553, 'frFR', 'On doit s\’aventurer en eaux profondes. Par où on ferait mieux de passer, à votre avis ?', 'On doit s\’aventurer en eaux profondes. Par où on ferait mieux de passer, à votre avis ?', 28153),
(136552, 'frFR', 'Dans ce cas, on n\’a rien à craindre. Merci !', 'Dans ce cas, on n\’a rien à craindre. Merci !', 28153),
(136551, 'frFR', 'On s\’apprête à s\’aventurer en eaux profondes. Comment s\’annoncent les marées ?', 'On s\’apprête à s\’aventurer en eaux profondes. Comment s\’annoncent les marées ?', 28153),
(136550, 'frFR', 'Je sens votre bénédiction couler dans mes veines. Merci infiniment.', 'Je sens votre bénédiction couler dans mes veines. Merci infiniment.', 28153),
(136549, 'frFR', 'Je m\’apprête à m\’aventurer sur le territoire du monstre. Je vous en supplie, accordez-moi votre bénédiction !', 'Je m\’apprête à m\’aventurer sur le territoire du monstre. Je vous en supplie, accordez-moi votre bénédiction !', 28153),
(136548, 'frFR', 'Je vais en informer les pêcheurs.', 'Je vais en informer les pêcheurs.', 28153),
(136547, 'frFR', 'Où est-ce qu\’on pêchera le plus de poissons aujourd\’hui ?', 'Où est-ce qu\’on pêchera le plus de poissons aujourd\’hui ?', 28153),
(136546, 'frFR', 'Hé ! Au kraal, on parle que d\’vous, $gétranger:étrangère;. Paraît que vous avez pas froid aux yeux !', '', 28153),
(136545, 'frFR', '', 'Vous faites partie de ceux qui marchent aux côtés des Loas. Mais faites gaffe, certains des Loas, y se supportent pas.', 28153),
(136538, 'frFR', 'Guerriers de la Horde ! Aujourd\’hui, nous nous soulevons. Nos haches ont soif du sang de nos ennemis.', '', 28153),
(136533, 'frFR', 'Mekkanivelle, vos engins volants peuvent-ils nous aider à traverser ?', '', 28153),
(136532, 'frFR', '', 'Voilà qui devrait rééquilibrer les chances, roi Wrynn !', 28153),
(136528, 'frFR', 'Jaina ! Bloquez les sorties, empêchez-les d\’appeler des renforts !', '', 28153),
(136527, 'frFR', 'Ce temple, il va tomber ! C\’est la prêtresse qui l\’a prédit !', '', 28153),
(136526, 'frFR', 'La prêtresse, protégez-la !', '', 28153),
(136525, 'frFR', 'La prêtresse, elle a besoin de sang pour le rituel. Le vôtre fera l\’affaire.', '', 28153),
(136524, 'frFR', 'Pour la prêtresse ! Pour G\’huun !', '', 28153),
(136523, 'frFR', 'Bwonsamdi, il a aucun pouvoir sur nous ! Pour le Dieu du sang !', '', 28153),
(136522, 'frFR', 'Au nom du seigneur de guerre !', '', 28153),
(136521, 'frFR', 'Je vais vous écraser, $gintrus:intruse; !', '', 28153),
(136520, 'frFR', 'Pour le seigneur de guerre Malaja ! Pour le Dieu du sang !', '', 28153),
(136519, 'frFR', 'Le seigneur de guerre, vous serez son esclave !', '', 28153),
(136518, 'frFR', '', 'Qui ose interrompre mon rituel ?', 28153),
(136517, 'frFR', '', 'C\’est bon, là ! Je vous ai dit que j\’allais réfléchir !', 28153),
(136516, 'frFR', 'Songez plutôt que vous pourriez doubler, voire tripler votre production ! Mes élixirs sont garantis cent pour cent naturels...', '', 28153),
(136515, 'frFR', '', 'Je sais pas… Notre façon de faire, elle a toujours marché et…', 28153),
(136514, 'frFR', 'Croyez-moi, c\’est une occasion unique ! Vous n\’allez tout de même pas rater ça !', '', 28153),
(136513, 'frFR', '', 'Vous allez regretter ça !', 28153),
(136512, 'frFR', '', 'Commencez le rituel ! Cette enveloppe misérable, je vais la laisser derrière moi !', 28153),
(136511, 'frFR', 'Circulez, y a rien à voir !', '', 28153),
(136510, 'frFR', 'M\’obligez pas à vous faire du mal.', '', 28153),
(136509, 'frFR', 'Hé ! Qu\’est-ce que vous fichez ici ?', '', 28153),
(136508, 'frFR', '', 'Ils se plieront tous… à la volonté du Dieu du sang…', 28153),
(136507, 'frFR', '', 'Plus de sang pour le Dieu du sang !', 28153),
(136498, 'frFR', 'Ils sont tous tombés sur la tête, ma parole ! Autant filer d\’ici avant qu\’il ne soit trop tard !', '', 28153),
(136497, 'frFR', '', 'C\’est terminé.\n\nIl… il n\’y avait pas d\’autre solution. Rien n\’aurait pu la racheter.\n\n<Rebecca renifle.>\n\nPardonnez-moi, j\’ai besoin d\’être seule.', 28153),
(136495, 'frFR', '', 'Je trouvais ça amusant au début, mais en réalité, c\’est de la folie !\n\nDans son grimoire, ma sœur parle de lever une armée d\’assemblages antiques ! Elle mettra Drustvar à genoux si personne ne l\’arrête !', 28153),
(136494, 'frFR', 'Disparaissez !', 'Disparaissez !', 28153),
(136493, 'frFR', '', 'Avec ma\’da, j\’espère qu\’on vous reverra.', 28153),
(136492, 'frFR', '', 'Ma\’da, elle a fait des erreurs, c\’est vrai… Mais j\’la pardonne. Maintenant, on va pouvoir passer l\’éternité toutes les deux, de l\’Autre côté.', 28153),
(136491, 'frFR', '', 'Ma\’da et moi, on est enfin réunies… pour toujours !', 28153),
(136490, 'frFR', '', 'Nooon… Je devais… vivre… éternellement…', 28153),
(136489, 'frFR', 'Attention à vous. Il y a des bestioles pas sympas par ici.', '', 28153),
(136488, 'frFR', '', 'Qu\’est-ce que c\’est ? Non ! Comment vous osez amener cette CHOSE devant moi ?', 28153),
(136487, 'frFR', '', 'Ma\’da ! Je t\’ai cherchée partout !', 28153),
(136486, 'frFR', '', 'Qui ose venir troubler mon repos ?', 28153),
(136485, 'frFR', '<Tenter d\’ouvrir le sarcophage.>', '<Tenter d\’ouvrir le sarcophage.>', 28153),
(136484, 'frFR', '<Le sarcophage est scellé, mais au prix de quelques efforts, vous devriez pouvoir l\’ouvrir.>', '', 28153),
(136483, 'frFR', '', 'On y est presque ! Ma\’da ! T\’es où, ma\’da ?', 28153),
(136482, 'frFR', '', 'Il fait tout noir ici… Passez devant, je reste juste derrière vous.', 28153),
(136481, 'frFR', '', 'Non, ça, c\’est la crypte de la grande reine. Ma\’da, elle aurait des ennuis si elle entrait là-dedans.', 28153),
(136480, 'frFR', '', 'Beurk, les prêtres du coin, ils sentent le vieux lombric ! Non, ma\’da serait jamais entrée là-dedans.', 28153),
(136479, 'frFR', '', 'Ma\’da m\’a fait rencontrer les prêtres du coin. C\’est même eux qui m\’ont donné ma robe. Ils étaient gentils !', 28153),
(136478, 'frFR', 'Je savais bien que vous n\’étiez pas de taille face à moi !', 'Je savais bien que vous n\’étiez pas de taille face à moi !', 28153),
(136477, 'frFR', '', 'Je crois pas que c\’est là. Jamais personne peut entrer dans le temple principal.', 28153),
(136476, 'frFR', 'Je dois m\’entraîner davantage...', 'Je dois m\’entraîner davantage...', 28153),
(136475, 'frFR', 'Argh... Vous êtes plus coriace que je ne pensais.', 'Argh... Vous êtes plus coriace que je ne pensais.', 28153),
(136474, 'frFR', 'Ça suffit ! Je me rends !', 'Ça suffit ! Je me rends !', 28153),
(136473, 'frFR', 'Vous gagnez. Pour cette fois...', 'Vous gagnez. Pour cette fois...', 28153),
(136472, 'frFR', 'Assez ! J\’abandonne !', 'Assez ! J\’abandonne !', 28153),
(136471, 'frFR', 'Essayez de ne pas me saigner dessus !', 'Essayez de ne pas me saigner dessus !', 28153),
(136470, 'frFR', 'Vous allez regretter de m\’avoir défié !', 'Vous allez regretter de m\’avoir défiée !', 28153),
(136469, 'frFR', 'J\’espère que votre épée est aussi acérée que votre langue !', 'J\’espère que votre épée est aussi acérée que votre langue !', 28153),
(136468, 'frFR', 'Vous osez me défier ? Je vais vous saigner à blanc !', 'Vous osez me défier ? Je vais vous saigner à blanc !', 28153),
(136467, 'frFR', 'M\’affronter sera votre dernière erreur !', 'M\’affronter sera votre dernière erreur !', 28153),
(136466, 'frFR', 'Si c\’est une raclée que vous cherchez, vous avez frappé à la bonne porte !', 'Si c\’est une raclée que vous cherchez, vous avez frappé à la bonne porte !', 28153),
(136465, 'frFR', '', 'Elle a dit qu\’elle allait dans un endroit sombre et qui fait peur. Je me demande où ça peut être. Brrr… Je déteste ça, quand il fait noir !', 28153),
(136464, 'frFR', '', 'Ouais ! Ma\’da, elle a parlé d\’un marché avec Bwonsamdi. J\’suis sûre qu\’elle est encore quelque part dans le temple.', 28153),
(136463, 'frFR', 'Razgaji m\’a demandé de vous provoquer en duel.', 'Razgaji m\’a demandé de vous provoquer en duel.', 28153),
(136462, 'frFR', 'Prenez garde... Je n\’ai aucune sympathie pour les étrangers.', 'Prenez garde... Je n\’ai aucune sympathie pour les étrangers.', 28153),
(136461, 'frFR', 'Le chemin qui m\’a mené à Vol\’dun passe par tous les cimetières du pays...', 'Le chemin qui m\’a menée à Vol\’dun passe par tous les cimetières du pays...', 28153),
(136460, 'frFR', 'Je vous donne jusqu\’à trois pour faire demi-tour... Trois !', 'Je vous donne jusqu\’à trois pour faire demi-tour... Trois !', 28153),
(136459, 'frFR', 'Vous ne voyez pas que je suis en train de m\’entraîner ? Fichez le camp !', 'Vous ne voyez pas que je suis en train de m\’entraîner ? Fichez le camp !', 28153),
(136458, 'frFR', 'Rokhan, je viens vous aider, vous et la princesse Talanji, à enquêter en Nazmir.', 'Rokhan, je viens vous aider, vous et la princesse Talanji, à enquêter en Nazmir.', 28153),
(136457, 'frFR', 'La princesse Talanji, elle nous envoie en Nazmir. On va avoir besoin de pterreurdactyles.', '', 28153),
(136453, 'frFR', '', 'Tâchez de prendre le contrôle de la ville. Je viendrai bientôt inspecter les ruines en personne.', 28153),
(136451, 'frFR', '', 'La tombe, à l\’intérieur, renferme de puissantes reliques qui pourraient s\’avérer utiles aux rituels du Sabbat.', 28153),
(136450, 'frFR', '', 'Les mineurs de Val-Archer ont découvert des ruines oubliées dans les profondeurs de la mine de Vieille-Roche.', 28153),
(136449, 'frFR', '', 'À toutes mes sœurs du Sabbat.', 28153),
(136448, 'frFR', '', 'Deux de mes hommes n\’en sont jamais revenus. Essayez de ne pas les imiter.', 28153),
(136447, 'frFR', '', 'Je sais pas ce qu\’il s\’y trame, mais la magie qui en émane semble siphonner l\’énergie vitale de tous ceux qui s\’en approchent.', 28153),
(136446, 'frFR', '', 'Au fait, $c, je vous conseille vivement d\’éviter la mine.', 28153),
(136445, 'frFR', '', 'Ce sont les derniers villageois. Avec un peu de chance, ils rejoindront Havrebrune sains et saufs.', 28153),
(136444, 'frFR', '', 'Ils envoient l\’artillerie lourde ! Tenez bon, les gars !', 28153),
(136443, 'frFR', '', 'Tenez-vous prêts pour une nouvelle attaque !', 28153),
(136442, 'frFR', '', 'Ils fondent droit sur nous. Protégez les civils !', 28153),
(136441, 'frFR', '', '$C, prenez position avec les autres et maintenez les ennemis à l\’écart de la ville !', 28153),
(136440, 'frFR', '', 'Allez, les gars. Faut qu\’on sécurise la route pour permettre aux habitants d\’évacuer.', 28153),
(136439, 'frFR', '', 'J\’espère que vous avez de la ressource.', 28153),
(136438, 'frFR', '', 'Vous avez entendu les gars ? Cette charmante personne va nous aider à reprendre la ville !', 28153),
(136437, 'frFR', '', 'Disons que ces affreuses créatures de bois ne se contentent pas d\’avoir l\’air patibulaires.\n\nTout a commencé avec la disparition mystérieuse de plusieurs mineurs, il y a quelques semaines. Et puis, sans crier gare, ces monstres se sont mis à nous attaquer, nous forçant à quitter le village. Ça correspond au moment où cette Malvoie a commencé à fouiner dans le coin ! Et après son départ, les problèmes n\’ont fait que s\’accentuer.\n\nCes créatures ont pris possession des lieux, et pour couronner le tout, elles ont capturé la majorité des habitants. J\’ai réussi à défendre cet endroit avec quelques résistants, mais j\’ignore comment reprendre le contrôle.\n\nDonc, si vous n\’êtes pas ici pour nous venir en aide, passez votre chemin.', 28153),
(136436, 'frFR', 'Je suis là pour vous aider.', 'Je suis là pour vous aider.', 28153),
(136435, 'frFR', 'Que se passe-t-il ici ?', 'Que se passe-t-il ici ?', 28153),
(136434, 'frFR', '', 'Tout va de mal en pis au village depuis que ces créatures cauchemardesques surgissent des mines.\n\nJ\’espère que vous aurez plus de chance que nous et que vous parviendrez à identifier la source de nos problèmes.', 28153),
(136432, 'frFR', 'Je vais t\’aider à retrouver ta mère.', 'Je vais t\’aider à retrouver ta mère.', 28153),
(136431, 'frFR', 'Tu as été très patiente.', 'Tu as été très patiente.', 28153),
(136430, 'frFR', '', 'C\’est trop triste ici sans ma\’da !$b$bVous pouvez m\’aider à la retrouver ? S\’il vous plaît ! Je serai sage.', 28153),
(136429, 'frFR', '', 'Ma\’da, elle m\’a dit de rester ici. J\’ai attendu longtemps, mais elle est toujours pas revenue !$b$bJe veux plus attendre, je veux voir ma ma\’da !', 28153),
(136428, 'frFR', 'Qu\’est-ce que tu fais ici ?', 'Qu\’est-ce que tu fais ici ?', 28153),
(136427, 'frFR', '', 'Où elle est, ma\’da ? J\’veux rentrer chez moi !', 28153),
(136426, 'frFR', '', 'Où elle est, ma\’da ? Ça fait longtemps qu\’elle est partie.', 28153),
(136425, 'frFR', '', 'Il fait froid… Elle est où, ma\’da ?', 28153),
(136422, 'frFR', 'Encore quelqu\’un qui part pour Nazmir ? Croyez-moi, vous en reviendrez pas.', '', 28153),
(136421, 'frFR', '', 'Humpf. Pas la peine d\’en dire plus, je pars tout de suite pour Nazmir. J\’espère qu\’on pourra rattraper la princesse.', 28153),
(136420, 'frFR', 'Talanji, elle est déjà en Nazmir ? J\’dois m\’grouiller, alors. On se voit là-bas.', '', 28153),
(136419, 'frFR', '', 'Il n\’y a pas un instant à perdre. Nous n\’avons aucune nouvelle de Butte-du-Faucon depuis des jours.', 28153),
(136418, 'frFR', '', 'Je p-pense pouvoir m\’in-infiltrer dans la grotte où se trouve ma sœur. Je vous y retrouverai.', 28153),
(136417, 'frFR', '', 'J\’pars pour Nazmir. On se retrouve là-bas.', 28153),
(136415, 'frFR', 'Les ingrédients dignes de ce nom, ça court pas les dunes, en Vol\’dun. Fermez les yeux et avalez votre pitance d\’un trait. Elle vous paraîtra moins infecte !', '', 28153),
(136414, 'frFR', 'Si vous voulez en savoir plus sur les alpagas, vous avez frappé à la bonne porte ! Je sais tout ce qu\’il y a à savoir, et plus encore.', '', 28153),
(136413, 'frFR', 'Vol\’dun a beau être un désert dangereux, c\’est aussi mon seul foyer.', '', 28153),
(136407, 'frFR', 'Là où on va, personne à Zuldazar veut s\’y risquer. Tenez-vous $gprêt:prête;.', '', 28153),
(136406, 'frFR', 'ÉCRASER !', '', 28153),
(136405, 'frFR', 'Je t\’amène cette âme qui veut te parler, puissant Loa.', '', 28153),
(136404, 'frFR', 'Venez. C\’est par ici.', '', 28153),
(136403, 'frFR', 'Ah, cette voix, je la connais ! Et j\’apprécie ces offrandes. Entrez, entrez !', '', 28153),
(136402, 'frFR', 'Le convoi se met en route ! Allez nous chercher des renforts sur-le-champ !', '', 28153),
(136398, 'frFR', 'Ma peau ! Elle brûle !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(136397, 'frFR', 'Ahhhhh !', '', 28153),
(136396, 'frFR', 'Grand Bwonsamdi, le tambour, il t\’appelle ! Ces offrandes sont pour toi !', '', 28153),
(136395, 'frFR', 'Doba quzhu ta towbo ! Metah bo chu !', '', 28153),
(136394, 'frFR', 'Très bien. Maintenant, faites sonner le tambour !', '', 28153),
(136393, 'frFR', 'La vision, laissez-la guider vos pas pour former le cercle du rituel. Mais attention ! Bwonsamdi sera pas content si vous bâclez la besogne.', '', 28153),
(136388, 'frFR', 'C\’est bon, vous avez fini votre petit boulot ? Un peu de <hips> professionnalisme, s\’il vous plaît.', '', 28153),
(136387, 'frFR', 'Des dards toxiques ? Je suis sûr qu\’il n\’y a absolument rien de louche dans leur commerce.', '', 28153),
(136386, 'frFR', 'Hé, c\’est dangereux là-bas ! <hips> Vous devriez rester avec moi !', '', 28153),
(136385, 'frFR', 'Je, euh… je crois que je vais attendre.', '', 28153),
(136384, 'frFR', '<hips> Par ici !', '', 28153),
(136383, 'frFR', 'Hé, qu\’est-ce que vous attendez ?!', '', 28153),
(136382, 'frFR', '<hips> Salut, le lézard.', '', 28153),
(136380, 'frFR', 'Brandissez vos lames ! Lok-tar ogar !', '', 28153),
(136379, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Creuser un tunnel', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [300] Creuser un tunnel', 28153),
(136378, 'frFR', 'Salut, $gmon pote:ma jolie;. Laissez-moi vous parler de la nouvelle technologie qui vient de débarquer sur le champ de bataille :\n\nles tunnels.\n\nVous avez bien entendu. En échange d\’UN SEUL énorme tas de pièces d\’or, mes associés et moi, on creusera un tunnel jusqu\’au front pour vos compagnons d\’armes et vous. Ça vous tente?', '', 28153),
(136377, 'frFR', 'C\’est une ville de rustres. Laissez-moi <hips> parler.', '', 28153),
(136376, 'frFR', 'Nous y voilà. Port-Liberté.', '', 28153),
(136375, 'frFR', 'Hmm. La dernière fois, on est allé à droite… du coup, ça DOIT être à gauche ! Je commence à y voir plus clair.', '', 28153),
(136374, 'frFR', '', 'La sphère, on doit la rapporter au camp avant que les Sephraks remarquent sa disparition ! Vite !', 28153),
(136373, 'frFR', 'Ahh. On se rapproche, je le sens.', '', 28153),
(136372, 'frFR', 'Fiou. Ça, c\’était de la grimpette. J\’ai besoin d\’une autre gorgée…', '', 28153),
(136371, 'frFR', 'Que... quoi ? Vous êtes qui, vous ? Et ça, c\’est quoi ?', 'Que... quoi ? Vous êtes qui, vous ? Et ça, c\’est quoi ?', 28153),
(136370, 'frFR', 'Cette chose contrôlait mon esprit ?', 'Cette chose contrôlait mon esprit ?', 28153),
(136369, 'frFR', 'Ah ! Ça me dit quelque chose. On doit être <hips> dans la bonne direction.', '', 28153),
(136368, 'frFR', 'Que... qu\’est-ce qui s\’est passé ?', 'Que... qu\’est-ce qui s\’est passé ?', 28153),
(136367, 'frFR', 'Uq naggwa… Notre maître… vient vous chercher…', 'Uq naggwa… Notre maître… vient vous chercher…', 28153),
(136366, 'frFR', 'Vous arrivez trop tard ! Vous n\’endiguerez pas le raz-de-marée !', 'Vous arrivez trop tard ! Vous n\’endiguerez pas le raz-de-marée !', 28153),
(136365, 'frFR', 'Ahh, voilà qui fait l\’affaire. Continuons.', '', 28153),
(136364, 'frFR', 'Euh, je me sens toujours embrumé. Un coup à boire m\’aidera à avoir les idées claires.', '', 28153),
(136363, 'frFR', 'Non, non, je suis CERTAIN que c\’était à droite.', '', 28153),
(136362, 'frFR', '<hips> Alors, c\’était par où, déjà… à gauche ?', '', 28153),
(136361, 'frFR', 'Les murmures… envahissent mes pensées…', 'Les murmures… envahissent mes pensées…', 28153),
(136360, 'frFR', 'Mon âme retournera à la mer…', 'Mon âme retournera à la mer…', 28153),
(136359, 'frFR', 'Y\’za qam yyqzz…', 'Y\’za qam yyqzz…', 28153),
(136358, 'frFR', 'Oh, vous qui venez ici, vous êtes indésirable !', 'Oh, vous qui venez ici, vous êtes indésirable !', 28153),
(136357, 'frFR', 'Votre cœur fera un parfait sacrifice !', 'Votre cœur fera un parfait sacrifice !', 28153),
(136356, 'frFR', 'Je m\’abandonne à cet immense pouvoir !', 'Je m\’abandonne à cet immense pouvoir !', 28153),
(136350, 'frFR', '%s vous suit.', '', 28153),
(136349, 'frFR', '%s en a assez de vous suivre et s\’enfuit.', '', 28153),
(136348, 'frFR', '', 'Maintenant que la mer a retrouvé son état normal, le moment est venu de nous occuper de la grotte.', 28153),
(136347, 'frFR', 'Les bougies, elles sont en place et les offrandes aussi. Maintenant, faut qu\’on trace le cercle…', '', 28153),
(136346, 'frFR', 'La gemme de mandeciel est en surcharge ! Qui sait ce qui se passera si vous l\’utilisez maintenant…', 'La gemme de mandeciel est en surcharge ! Qui sait ce qui se passera si vous l\’utilisez maintenant…', 28153),
(136345, 'frFR', 'Pour la Horde !', '', 28153),
(136341, 'frFR', 'Commençons.', 'Commençons.', 28153),
(136340, 'frFR', 'Le sang de nos ennemis abreuvera la terre de ces plaines.', '', 28153),
(136327, 'frFR', '', 'Attention !', 28153),
(136326, 'frFR', '', 'Attention !', 28153),
(136325, 'frFR', 'Bien… je pense que je suis prêt à y aller. Nous pouvons encore remédier à cela.', '', 28153),
(136324, 'frFR', 'Demander à Fozruk d\’attaquer Haut-Perchoir.', 'Demander à Fozruk d\’attaquer Haut-Perchoir.', 28153),
(136323, 'frFR', 'Demander à Fozruk d\’attaquer la passe de Vaillehuche.', 'Demander à Fozruk d\’attaquer la passe de Vaillehuche.', 28153),
(136322, 'frFR', 'Demander à Fozruk d\’attaquer Stromgarde.', 'Demander à Fozruk d\’attaquer Stromgarde.', 28153),
(136321, 'frFR', '<Fozruk vous regarde de haut.>', '', 28153),
(136320, 'frFR', 'Avec plaisir.', '', 28153),
(136319, 'frFR', 'Je vais vous écarteler !', '', 28153),
(136318, 'frFR', 'Imbécile… D\’autres viendront… récupérer la gemme…', '', 28153),
(136317, 'frFR', 'Quoi que vous fassiez, le véritable pouvoir de la gemme de mandeciel sera nôtre !', '', 28153),
(136316, 'frFR', 'Le désert s\’étendra sans fin !', '', 28153),
(136315, 'frFR', 'Nazmir appartient désormais aux Sephraks !', '', 28153),
(136314, 'frFR', 'Ces terres ne seront bientôt plus que sable !', '', 28153),
(136313, 'frFR', 'Vos terres sont les suivantes sur notre liste !', '', 28153),
(136312, 'frFR', 'Notre règne arrive, vous ne pouvez pas l\’arrêter !', '', 28153),
(136311, 'frFR', 'Les marais, on les aura !', '', 28153),
(136310, 'frFR', 'Tous devront se soumettre à notre domination !', '', 28153),
(136309, 'frFR', 'Le désert recouvrira ces terres !', '', 28153),
(136297, 'frFR', 'COMMENT AVEZ-VOUS OSÉ ?!', '', 28153),
(136296, 'frFR', 'Vous… vous avez tué l\’amour de ma vie !', '', 28153),
(136295, 'frFR', 'Argh… manquait plus que ça… coupé en deux par des Sephraks… On a connu plus glorieux, comme fin.', '', 28153),
(136292, 'frFR', 'Je vous accorde la bénédiction de la mer ! Puisse-t-elle vous bercer de sa tendre étreinte et vous accepter comme son $uallié:alliée;.', '', 28153),
(136291, 'frFR', 'Xibala... vous fera souffrir...', '', 28153),
(136290, 'frFR', 'C\’est le sanctuaire sacré de Xibala ici. Y va ajouter une nouvelle âme à sa collection !', '', 28153),
(136278, 'frFR', 'Le monde sera englouti par les flots… ak yar qi\’lwhuk h\’iwn…', 'Le monde sera englouti par les flots… ak yar qi\’lwhuk h\’iwn…', 28153),
(136277, 'frFR', 'Il est trop tard ! Vous ne pouvez pas nous arrêter !', 'Il est trop tard ! Vous ne pouvez pas nous arrêter !', 28153),
(136276, 'frFR', 'Ifis shuul qi\’nuq yyqzz…', '', 28153),
(136275, 'frFR', 'Brannon Chantorage est un avorton. Le véritable pouvoir appartient à la mer !', '', 28153),
(136274, 'frFR', 'Alby ? Que se passe-t-il ? Où est le seigneur Chantorage ?', '', 28153),
(136273, 'frFR', 'Vous n\’en croiriez pas vos oreilles, Therold. C\’est un véritable désastre.', '', 28153),
(136272, 'frFR', 'Baissez d\’un ton ! Si nous échouons, dame Sylvanas nous le fera regretter.', '', 28153),
(136271, 'frFR', 'Tucker ! J\’aurais dû m\’en douter. Eh bien, il a fini par payer le prix de son incompétence.', '', 28153),
(136270, 'frFR', 'Tucker. Mais les Sephraks l\’ont tué en premier.', '', 28153),
(136269, 'frFR', 'Nous aurions dû les voir venir. Qui était chargé de faire le guet ?', '', 28153),
(136268, 'frFR', '', 'On n\’a rien à se reprocher, patron. Ils n\’étaient pas censés être là, après tout. Comment aurait-on pu prévoir qu\’ils allaient nous tomber dessus ?', 28153),
(136267, 'frFR', 'Elle le sera si nous faisons notre travail correctement, Ingrid.', '', 28153),
(136266, 'frFR', '', 'Ça lui arrive d\’être satisfaite, patron ?', 28153),
(136265, 'frFR', 'Allez, on y va ! On n\’a pas encore fini d\’explorer, et on ne peut pas se permettre de tomber dans une autre embuscade.', '', 28153),
(136264, 'frFR', '<Le fétiche obscur, immobile quand vous le contemplez, semble se mettre à bouger dès que vous détournez le regard. Il s\’agit peut-être d\’une illusion d\’optique. Ou peut-être pas.>', '', 28153),
(136263, 'frFR', '', 'Oh, allez, quoi !', 28153),
(136262, 'frFR', 'C\’est une information… strictement confidentielle.', '', 28153),
(136261, 'frFR', '', 'Et c\’était quand, au juste, la première fois qu\’on vous a coupé en deux ?', 28153),
(136260, 'frFR', 'Bah, ce n\’est pas la première fois que ça m\’arrive. Reste à espérer que ce soit la dernière.', '', 28153),
(136259, 'frFR', 'Encore que, ça dépend des fois.', '', 28153),
(136258, 'frFR', '', 'Mais enfin, Clayton. On est des Morts-vivants. Évidemment qu\’on peut survivre même coupés en deux !', 28153),
(136257, 'frFR', 'Comment est-ce que vous avez survécu, patron ? Je vous ai vu vous faire couper en deux.', '', 28153),
(136256, 'frFR', '', 'Amusez-vous bien avec la gemme ! A priori, elle est sortie intacte du rituel… ou presque.', 28153),
(136255, 'frFR', 'Des vers qui vous dévorent le visage ? Comptez pas sur moi !', 'Des vers qui vous dévorent le visage ? Comptez pas sur moi !', 28153),
(136254, 'frFR', 'Comment la direction a-t-elle pu laisser passer ça ? Cette fois, c\’en est trop. Il nous faut un délégué syndical.', 'Comment la direction a-t-elle pu laisser passer ça ? Cette fois, c\’en est trop. Il nous faut un délégué syndical.', 28153),
(136253, 'frFR', 'Justement, c\’est l\’heure de ma pause. Je file.', 'Justement, c\’est l\’heure de ma pause. Je file.', 28153),
(136252, 'frFR', 'Je vais me poster en terrain surélevé. Dites aux autres de me rejoindre là-bas.', '', 28153),
(136251, 'frFR', 'Les morceaux de monstres sont monnaie courante dans les cargaisons, mais des monstres vivants ? Sans moi.', 'Les morceaux de monstres sont monnaie courante dans les cargaisons, mais des monstres vivants ? Sans moi.', 28153),
(136250, 'frFR', 'Il suffit de remboîter cette partie-là…', '', 28153),
(136249, 'frFR', '', 'Je vous retrouve de l\’autre côté de la zone d\’emballage. Je vais voir ce qui se passe en ville.', 28153),
(136248, 'frFR', '', 'Que se passe-t-il ici ? Que… Qu\’est-ce que c\’est ?', 28153),
(136243, 'frFR', '', '« Ne trafiquez pas avec la magie des Ombres », qu\’ils disaient.$B$B« Vous condamnez Azeroth à la ruine si vous persistez dans cette voie », qu\’ils m\’ont dit.$B$B« Rendez-moi ça, vous ne pouvez pas l\’utiliser comme ingrédient ! » qu\’il a hurlé alors que je lui arrachais le bras.$B$BOh, pardon ! Je ressassais de vieux souvenirs !', 28153),
(136242, 'frFR', 'Le oui l\’emporte. On dirait qu\’on va assister à un beau feu d\’artifice.', '', 28153),
(136241, 'frFR', 'Moi, nan.', '', 28153),
(136240, 'frFR', 'Contre.', '', 28153),
(136239, 'frFR', 'Bien… Et maintenant, qui est contre ?', '', 28153),
(136238, 'frFR', 'Moi.', '', 28153),
(136237, 'frFR', 'Je vous accompagne, histoire de surveiller que tout est bien fait.', '', 28153),
(136236, 'frFR', '', 'Moi.', 28153),
(136235, 'frFR', '', 'Moi.', 28153),
(136234, 'frFR', 'Nous allons soumettre ça au vote. Qui veut rester dans ce coupe-gorge marécageux pour regarder des hommes-serpents se faire trucider par le pouvoir d\’une gemme ?', '', 28153),
(136233, 'frFR', '', 'Allez, Chadwick ! Avec la gemme de mandeciel qu\’on va choper grâce à $n, on pourra les CRAMER !', 28153),
(136232, 'frFR', 'Mes mages et moi, nous vous retrouverons là-haut.', '', 28153),
(136231, 'frFR', 'Je ne m\’attendais pas à voir un visage amical dans les parages. Merci de m\’avoir sauvé. On vous a parlé du plan d\’Ingrid ?', '', 28153),
(136230, 'frFR', 'Nous aurions dû nous préparer plus soigneusement avant de nous aventurer dans un endroit aussi dangereux…', '', 28153),
(136229, 'frFR', '', 'Je file. Vous, vous réglez le problème… Ensuite, on va voir de quoi cette gemme est capable !', 28153),
(136228, 'frFR', 'Merci de m\’avoir secouru. Ces Sephraks cherchent à s\’emparer d\’une magie ténébreuse en Nazmir. La question, c\’est pourquoi ?', '', 28153),
(136227, 'frFR', '', 'Voilà qui est mieux. Les Sephraks cherchent à s\’emparer d\’une magie apte à libérer le pouvoir d\’un de leurs artéfacts.', 28153),
(136226, 'frFR', 'Vous êtes à jour sur vos livraisons ?', 'Vous êtes à jour sur vos livraisons ?', 28153),
(136225, 'frFR', 'AAAH ! DÉBARRASSEZ-MOI DE CE TRUC !', '', 28153),
(136224, 'frFR', 'Espèce de pourriture !', 'Espèce de pourriture !', 28153),
(136223, 'frFR', 'Oh mon dieu, il a tué Ken\’nai !', 'Oh mon dieu, il a tué Ken\’nai !', 28153),
(136222, 'frFR', 'Ça sent les ennuis à plein nez. Prudence !', '', 28153),
(136221, 'frFR', 'Je viens justement d\’être livré il y a quelques minutes à peine ! Vous voulez jeter un coup d\’œil ?', '', 28153),
(136220, 'frFR', '', 'Vous savez, cela fait plusieurs jours que le jeune Chantorage est aux abonnés absents. Je ne serais pas fâchée qu\’on le remplace par quelqu\’un de plus compétent, seulement on ne m\’a pas demandé mon avis.', 28153),
(136219, 'frFR', 'Auriez-vous remarqué quelque chose d\’inhabituel ?', 'Auriez-vous remarqué quelque chose d\’inhabituel ?', 28153),
(136218, 'frFR', 'Ça fait des jours que je n\’ai pas été livré ! Comment je suis censé préparer mon fameux battrodon frit sans ailerons frais, hein ?', '', 28153),
(136215, 'frFR', 'Il est grand temps d\’apprendre à ces Sephraks ce qu\’est la vraie souffrance.', '', 28153),
(136212, 'frFR', 'On y est ! Beau travail. Vous n\’en êtes pas à votre coup d\’essai, on dirait.', '', 28153),
(136211, 'frFR', 'AÏEUH ! Non, continuez, l\’opération est toujours un peu douloureuse. Allez, un quart de tour vers la gauche…', '', 28153),
(136210, 'frFR', 'Et allez-y doucement avec mes jambes. Elles ont tendance à frétiller une fois détachées de mon corps.', '', 28153),
(136207, 'frFR', 'Hé ! Rendez-moi ça !', '', 28153),
(136206, 'frFR', '', 'Faites sortir ces saurides de mon auberge !', 28153),
(136205, 'frFR', '', 'Quoi ? Qu\’est-ce que vous me voulez ?', 28153),
(136200, 'frFR', 'Entendu. J\’assurerai vos arrières.', '', 28153),
(136199, 'frFR', 'Genn, vous allez nous couvrir. Ne prenons pas le risque de faire passer tout le monde par le côté de la forteresse, il pourrait y avoir des pièges.', '', 28153),
(136198, 'frFR', '', 'Allons-y.', 28153),
(136197, 'frFR', 'Tout le monde en position. Nous attaquerons à mon signal !', '', 28153),
(136196, 'frFR', 'Oui. Sylvanas n\’a eu guère de temps pour se préparer à cette attaque, mais ce n\’est pas une raison pour la sous-estimer.', '', 28153),
(136194, 'frFR', 'Avez-vous remarqué quoi que ce soit qui sorte de l\’ordinaire ?', 'Avez-vous remarqué quoi que ce soit qui sorte de l\’ordinaire ?', 28153),
(136193, 'frFR', 'Besoin de quelque chose ?', '', 28153),
(136192, 'frFR', '', 'Oui, je peux vous aider ?', 28153),
(136191, 'frFR', 'Bienvenue ! Une petite faim, peut-être ?', '', 28153),
(136187, 'frFR', 'Un coup de main, c\’est possible ? Ou plutôt de jambe, pour être tout à fait exact. Mes mains, elles, se portent très bien.', '', 28153),
(136179, 'frFR', 'Il est temps de faire une démonstration de la puissance de la Horde à ces vermines de l\’Alliance !', '', 28153),
(136178, 'frFR', 'On dresse nos loups dès le plus jeune âge pour qu\’ils soient toujours prêts à se battre.', '', 28153),
(136177, 'frFR', 'Ce n\’est pas le moment de bavarder. On a du travail.', '', 28153),
(136176, 'frFR', '', 'Ouais ? Qu\’est-ce que j\’peux faire pour vous ?', 28153),
(136170, 'frFR', 'Jaina ! Louée soit la Lumière ! Nous avons grand besoin de votre aide.', '', 28153),
(136169, 'frFR', '', 'De son vivant, Kel\’vax était notre fils, mais aujourd\’hui, c\’est un monstre comme les autres. Tuez-le, qu\’on puisse envoyer son âme à Bwonsamdi.', 28153),
(136167, 'frFR', '', 'Kel\’vax, il bafoue tout ce que représente Bwonsamdi. Trouvez les phylactères, qu\’on mette un terme à cet affront.', 28153),
(136166, 'frFR', '', 'Il faut nous aider à purifier le sanctuaire de Bwonsamdi. Il était si beau, avant…', 28153),
(136165, 'frFR', '', 'Attends… Y a quelqu\’un d\’autre… et c\’est pas un Troll de sang ! Hé, venez ici !', 28153),
(136164, 'frFR', '', 'Mes créations… ne peuvent être vaincues…', 28153),
(136163, 'frFR', '', 'Ces âmes m\’appartiennent !', 28153),
(136162, 'frFR', 'Si on continue comme ça, on arrivera jamais à nettoyer cet endroit pour Bwonsamdi !', '', 28153),
(136161, 'frFR', '', 'Ah, vous êtes là ! Mutumba me faisait justement son rapport. Il semble que vous ayez vécu une sacrée aventure.', 28153),
(136160, 'frFR', '', 'Je protégeais la forêt de mon vivant. Je ne me laisserai pas manipuler par ces sorcières !', 28153),
(136159, 'frFR', 'C\’est… magnifique…', '', 28153),
(136156, 'frFR', '', 'Doucement. Tes blessures, elles sont profondes.', 28153),
(136153, 'frFR', 'Nous sommes prêts à partir.', 'Nous sommes prêts à partir.', 28153),
(136152, 'frFR', '', 'Ce n\’est jamais une bonne idée de voyager dans ces dunes sans escorte.', 28153),
(136151, 'frFR', 'Je protégeais ces terres de mon vivant.\n\nJe ferai de même dans la mort.', '', 28153),
(136150, 'frFR', '', 'On se reverra de l\’autre côté.', 28153),
(136149, 'frFR', 'La volonté de Bwonsamdi, elle sera faite. Notre dernière heure, elle a enfin sonné.', '', 28153),
(136148, 'frFR', 'Non ! Je veux pas voir Bwonsamdi, non… Pitié, ARRÊTEZ !', '', 28153),
(136147, 'frFR', '', 'Ton sort, il est entre les mains de Bwonsamdi, maintenant. Reste à espérer qu\’il soit plus clément que nous.', 28153),
(136146, 'frFR', 'Non ! Mère, fais quelque chose !', '', 28153),
(136145, 'frFR', 'Il est trop tard pour ça, mon fils. T\’as choisi de trahir Bwonsamdi et maintenant, tu dois en payer le prix.', '', 28153),
(136144, 'frFR', 'Mère… père… Je regrette. Je vous demande pardon. Expliquez à Bwonsamdi de ma part !', '', 28153),
(136141, 'frFR', 'Je m\’occupe des morts.$b$b<Allen hausse les épaules.>$b$bÇa me permet de gagner ma vie.', '', 28153),
(136140, 'frFR', '', 'Stupide Loa ! La mort, c\’est tout c\’que vous trouverez ici !', 28153),
(136116, 'frFR', 'Venez, regagnons plutôt le terrier.', '', 28153),
(136115, 'frFR', 'Ha ha ! Nos ennemis se carapatent !', '', 28153),
(136114, 'frFR', 'Bwonsamdi ! Non… G\’huun, il a promis que je serais invincible !', '', 28153),
(136113, 'frFR', 'Assez de ces craintes incessantes ! Les créatures des superstitions populaires ne sont jamais aussi effrayantes que les histoires voudraient le faire croire.', '', 28153),
(136112, 'frFR', 'Ça sent pas bon, tout ça... Faites gaffe, $n !', '', 28153),
(136111, 'frFR', 'Bien ! Le chef mort, nous n\’allons faire qu\’une bouchée de ses serviteurs. Gobez-en autant que vous pouvez !', '', 28153),
(136110, 'frFR', 'BAH ! Soyez maudits, et Bwonsamdi avec vous, il AURA PAS MON ÂME !', '', 28153),
(136109, 'frFR', 'Vos esprits nourriront le Dieu du sang !', '', 28153),
(136108, 'frFR', 'Kel\’vax , il est à nouveau vulnérable… c\’est à vous !', '', 28153),
(136107, 'frFR', 'Qu\’est-ce que… Impossible ! Je ne serai pas enchaîné. Pas par vous, ni par Bwonsamdi !', '', 28153),
(136106, 'frFR', 'C\’est l\’heure d\’affronter le jugement de Bwonsamdi. On a les phylactères, et $n m\’a donné les os, qui vont servir à contrer ton vaudou !', '', 28153),
(136105, 'frFR', 'Mère, père…', '', 28153),
(136104, 'frFR', '', 'Kel\’vax ! Ça suffit !', 28153),
(136103, 'frFR', 'Vous allez rejoindre les serviteurs de Bwonsamdi pour une éternité de souffrances !', '', 28153),
(136102, 'frFR', 'ASSEZ ! Le Dieu du sang exige votre destruction… et je vais lui obéir. Que Bwonsamdi soit maudit !', '', 28153),
(136101, 'frFR', 'Peu importe. Cette civilisation, j\’ai vu sa gloire et son déclin… Rien ne pourra m\’arrêter !', '', 28153),
(136100, 'frFR', 'Quoi ? Mes zombies, où ils sont passés ? Mes squelettes… Qu\’est-ce qui se passe ?', '', 28153),
(136099, 'frFR', 'Pauvre $gmortel:mortelle;… Mes armées, elles vont vous anéantir. À moi, mes serviteurs !', '', 28153),
(136096, 'frFR', 'Hé ! On se connaît pas, que je sache. Vous êtes ici pour nous aider ou quoi ?', '', 28153),
(136095, 'frFR', 'La plaisanterie a assez duré !', 'La plaisanterie a assez duré !', 28153),
(136094, 'frFR', '', 'Faites gaffe quand vous fourrez vot\’ nez dans les affaires des Corsandre. Ils sont mauvais comme le scorbut.', 28153),
(136093, 'frFR', 'Pas mal pour un sac à puces de fond de cale. Si je vous étais tombée dessus avant qu\’on s\’échoue, c\’est vos tripes qui saliraient mes bottes en ce moment même.', 'Pas mal pour un sac à puces de fond de cale. Si je vous étais tombée dessus avant qu\’on s\’échoue, c\’est vos tripes qui saliraient mes bottes en ce moment même.', 28153),
(136092, 'frFR', 'V\’nez donc me chercher, viles murènes ! J\’vais vous arracher la peau et en faire un drapeau !', 'V\’nez donc me chercher, viles murènes ! J\’vais vous arracher la peau et en faire un drapeau !', 28153),
(136086, 'frFR', '', 'Avant, mon père régnait d\’une main de fer et personne n\’aurait osé enfreindre ses lois. Il était sévère, mais juste et il n\’hésitait pas à tendre la main aux nécessiteux. Voilà pourquoi ses sujets l\’aimaient.$b$bMais tout ça c\’est du passé. Maintenant, ceux qui ont sa confiance déversent leur venin dans ses oreilles, ils manigancent et ils complotent.$b$bJe ne sais pas ce qu\’ils mijotent, mais notre peuple ne peut pas se permettre d\’attendre pour le découvrir.', 28153),
(136085, 'frFR', '', 'Tuez-moi cette créature, les enfants !', 28153),
(136072, 'frFR', 'La déferlante de sang venue du nord va s\’abattre sur vous et vous courberez l\’échine, de gré ou de force.', 'La déferlante de sang venue du nord va s\’abattre sur vous et vous courberez l\’échine, de gré ou de force.', 28153),
(136071, 'frFR', 'Bientôt, ils débarqueront de Nazmir et vous verrez tous ce qu\’on a vu.', 'Bientôt, ils débarqueront de Nazmir et vous verrez tous ce qu\’on a vu.', 28153),
(136070, 'frFR', 'Non ! Non ! Vous pouvez pas nous arrêter. Il nous l\’a promis.', 'Non ! Non ! Vous pouvez pas nous arrêter. Il nous l\’a promis.', 28153),
(136069, 'frFR', 'Le sang de héros, ça rapporte gros.', 'Le sang de héros, ça rapporte gros.', 28153),
(136068, 'frFR', 'Vous pourrez pas cafter auprès des gardes quand vous aurez rendu l\’âme.', 'Vous pourrez pas cafter auprès des gardes quand vous aurez rendu l\’âme.', 28153),
(136067, 'frFR', 'Vous êtes qui pour vous dresser contre nous ?', 'Vous êtes qui pour vous dresser contre nous ?', 28153),
(136039, 'frFR', 'Qu\’y a-t-il ? Nos ennemis nous talonnent ! Si vous ne les affrontez pas avec moi, j\’irai seul.', '', 28153),
(136015, 'frFR', 'Selon toute apparence, ce tonneau est rempli de morceaux de monstres inoffensifs.', '', 28153),
(136003, 'frFR', 'Il est temps d\’en finir ! Retrouvez-moi au bord de la rivière.', '', 28153),
(135928, 'frFR', '', 'Ces Morts-vivants, c\’est une insulte à Bwonsamdi. On ne va pas les laisser faire.', 28153),
(135927, 'frFR', 'La volonté de Bwonsamdi doit être faite. Et c\’est à nous d\’y veiller.', '', 28153),
(135904, 'frFR', 'Viens me rejoindre dans mon terrier. Nous avons fort à faire.', '', 28153),
(135903, 'frFR', '', 'Non ! Pardonne-moi, Krag\’wa.', 28153),
(135901, 'frFR', 'Aurais-tu l\’audace de contester la pertinence de mon jugement ?', '', 28153),
(135900, 'frFR', '', 'Krag\’wa ! C\’est un grand honneur, mais je le mérite pas… J\’ai pas réussi à arrêter les Nagas.', 28153),
(135898, 'frFR', 'Narez, tu t\’es montrée digne d\’intégrer les rangs de mes disciples.', '', 28153),
(135875, 'frFR', '', 'Moi, je reste ici pour surveiller les Nagas et faire mes preuves aux yeux de Krag\’wa. À un de ces quatre.', 28153),
(135874, 'frFR', 'Oh, ça non, $gétranger:étrangère; ! Z\’allez pas me priver de mon gagne-pain !', '', 28153),
(135869, 'frFR', 'Passe devant.', 'Passe devant.', 28153),
(135868, 'frFR', 'T\’es qui ? T\’es $gnouveau:nouvelle; ici ?$b$bLe Bon Corleone, il sera pas content que tu aies pas été le voir. Tu ferais mieux de venir avec moi.', '', 28153),
(135865, 'frFR', '', 'Et dire qu\’ils me traitaient d\’imbécile parce que je conservais ce parchemin « trop spécialisé ». Bah !', 28153),
(135861, 'frFR', '%s succombe à ses blessures.', '%s succombe à ses blessures.', 28153),
(135843, 'frFR', '', 'Les gueules démoniaques… j\’voulais juste… en faire encore… une…', 28153),
(135842, 'frFR', '', 'Vous serez une source d\’énergie parfaite pour les totems !', 28153),
(135795, 'frFR', '<Le corps sans vie de la grenouille géante gît dans la boue.>', '', 28153),
(135777, 'frFR', 'On se disperse !', '', 28153),
(135776, 'frFR', 'Aaaah !', '', 28153),
(135774, 'frFR', 'On dégage !', '', 28153),
(135772, 'frFR', 'Iiiik !', '', 28153),
(135771, 'frFR', 'Je vais tout raconter au Bon Corleone !', '', 28153),
(135770, 'frFR', 'Hé, j\’en avais besoin, figurez-vous !', '', 28153),
(135769, 'frFR', 'Ha ! Alerte ! Intrusion !', '', 28153),
(135768, 'frFR', 'Le Bon Corleone, il va pas apprécier !', '', 28153),
(135741, 'frFR', 'Quoi ?', 'Quoi ?', 28153),
(135740, 'frFR', 'Alors, qu\’est-ce qu\’on dit au féticheur, $r ?', '', 28153),
(135733, 'frFR', 'Il avait tort. Oh, des dégâts, il y en a eu... Mais Zul a fui avec notre flotte et il a déclenché des guerres. Ceux d\’entre nous qui sont restés, on a enduré l\’épreuve et on a tout reconstruit. Parce que c\’est ça, être Zandalari.', '', 28153),
(135732, 'frFR', 'Les visions de Zul ? Pff ! Il vous a parlé de cette fameuse prédiction qu\’il a faite un jour, comme quoi Zandalar allait sombrer sous les flots ?', '', 28153),
(135726, 'frFR', 'Je supervise les allées et venues des centaines de rafiots qui circulent dans ce port et je m\’assure qu\’aucun ne soit en retard.$b$bParlez vite. Mon temps, il est très précieux.', '', 28153),
(135719, 'frFR', '', 'Allez-y.', 28153),
(135701, 'frFR', 'Des histoires sur Xibala, y en a des tas, mais c\’est pas facile de démêler le vrai du faux. En tout cas, ce qu\’est sûr, c\’est que les anciens le craignaient.\n\nParaît qu\’il faisait pourrir ses victimes de l\’intérieur.\n\nMais aussi, on dit qu\’y suffisait de poser les yeux sur lui pour se changer en squelette ambulant.\n\nEt pis qu\’il restait planqué le jour et qu\’il sortait la nuit pour becqueter les gens pendant leur sommeil.\n\nMême que les voyageurs qui le croisaient en route, ben ils crevaient en crachant du sang.\n\nMême les plus braves guerriers, ils préfèrent passer au large.', '', 28153),
(135699, 'frFR', 'Qui était Xibala ?', 'Qui était Xibala ?', 28153),
(135694, 'frFR', '', 'Je p-pense pouvoir m\’in-infiltrer dans la grotte où se trouve ma sœur. Je vous y retrouverai.', 28153),
(135683, 'frFR', 'Qu\’est-ce que vous venez faire ici, $c ?', '', 28153),
(135680, 'frFR', 'Nous sommes prêts pour le procès.', 'Nous sommes prêtes pour le procès.', 28153),
(135679, 'frFR', 'Inutile de repousser l\’échéance. Nous finirons bien par découvrir la vérité sur mademoiselle Malvoie !', '', 28153),
(135674, 'frFR', 'Nos coursiers du vent sont tombés, mais notre vraie force tient au fer de nos haches !', '', 28153),
(135673, 'frFR', 'Artillerie ou pas, notre force reste inégalée !', '', 28153),
(135670, 'frFR', 'Mes lames taillent en pièces mes ennemis !', '', 28153),
(135638, 'frFR', 'Ces monstres ont massacré le dernier adorateur qui me restait. Je vais déchaîner sur eux dix mille ans de fureur contenue !', '', 28153),
(135610, 'frFR', '', 'La princesse Talanji vous attend en bas. Regardez où vous mettez les pieds.', 28153),
(135604, 'frFR', '', 'Suivez-moi. Je vais vous indiquer le chemin le plus rapide pour descendre.', 28153),
(135586, 'frFR', '', 'Revenez me voir quand vous en aurez l\’occasion. J\’ai hâte de vous révéler tout ce que j\’ai appris de ces gravures !', 28153),
(135579, 'frFR', '', 'Ne vous en faites pas pour moi... Je vais me débrouiller pour regagner l\’arène.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(135578, 'frFR', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma commence à lancer |cFFFF0404|Hspell:249924|h[Déchiqueter l\’âme]|h|r sur |cFFFF0000$n|r !', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma commence à lancer |cFFFF0404|Hspell:249924|h[Déchiqueter l\’âme]|h|r sur $n !', 28153),
(135577, 'frFR', 'Je sens mes forces revenir… Cet antivenin semble faire son office.', '', 28153),
(135576, 'frFR', 'J\’ignore combien de temps il reste à Julwaba… L\’antivenin, c\’est son seul espoir.', '', 28153),
(135574, 'frFR', 'Ça fait plusieurs jours que Julwaba et Taz\’jin n\’ont plus donné signe de vie. Je me fais du souci…', '', 28153),
(135565, 'frFR', 'Partez sur-le-champ ! Il faut éliminer ces Nagas pour sauver les fidèles de Krag\’wa.', '', 28153),
(135555, 'frFR', '', 'Les bénédictions de Krag\’wa, elles vous accompagnent. Montrez à Zaldraxia qu\’elle s\’est frottée au mauvais Loa.', 28153),
(135539, 'frFR', 'Il faut à tout prix arrêter les Nagas. Ne vous inquiétez pas pour moi.', '', 28153),
(135511, 'frFR', 'Amenez-moi au roi Rastakhan.', 'Amenez-moi au roi Rastakhan.', 28153),
(135496, 'frFR', 'Notre ville est attaquée !', 'Notre ville est attaquée !', 28153),
(135492, 'frFR', 'J\’envoie des mineurs s\’occuper tout de suite de cette veine pour vous.', '', 28153),
(135486, 'frFR', 'La mine est attaquée !', 'La mine est attaquée !', 28153),
(135469, 'frFR', '', 'Qu\’y a-t-il, $c ?', 28153),
(135466, 'frFR', 'Saleté de parchemin, tu vas marcher, oui ?! FAUT TROUVER SHOAK !', '', 28153),
(135465, 'frFR', 'Allez ! J\’ai besoin de toi pour trouver Shoak, PAS POUR FAIRE MUMUSE AVEC CE TOTEM !', '', 28153),
(135464, 'frFR', 'Mais marche, à la fin ! Trouve Shoak, et que ça saute !', '', 28153),
(135457, 'frFR', '', 'Des dommages collatéraux ne sont pas exclus, mais je suis sûre qu\’on arrivera à recoller les morceaux. Par contre, il va falloir songer à recruter d\’autres assistants...', 28153),
(135456, 'frFR', 'Moi je dis, les esprits, ils vont pas aimer ça. Et dites pas qu\’on vous a pas prévenus !', '', 28153),
(135455, 'frFR', 'Hé ! Z\’avez pas intérêt à larguer vos bombes sur ces ossements !', '', 28153),
(135446, 'frFR', '', 'Meurs, $gintrus:intruse; !', 28153),
(135445, 'frFR', '', 'Vous nous obéirez !', 28153),
(135444, 'frFR', '', 'Non… L\’échec n\’est pas une option !', 28153),
(135443, 'frFR', '', 'Non… On m\’avait promis… le pouvoir…', 28153),
(135442, 'frFR', '', 'Vous me supplierez de vous achever tant je vous ferai souffrir.', 28153),
(135441, 'frFR', '', 'Je vous mettrai aux fers !', 28153),
(135440, 'frFR', '', 'Vous ne pouvez pas m\’arrêter !', 28153),
(135439, 'frFR', 'J\’apporterai votre cœur à ma maîtresse !', '', 28153),
(135432, 'frFR', 'L\’Alliance a pris le contrôle d\’une veine d\’azérite !', '', 28153),
(135431, 'frFR', '$n a défendu une veine d\’azérite !', '', 28153),
(135430, 'frFR', 'La Horde a pris le contrôle d\’une veine d\’azérite !', '', 28153),
(135429, 'frFR', '$n a attaqué une veine d\’azérite !', '', 28153),
(135405, 'frFR', 'Très bien. Mais je demanderai la tête de cette créature au roi.', '', 28153),
(135400, 'frFR', 'Restez en dehors de tout ça, général. L\’intermédiaire de la Horde a passé les épreuves de deux tribus. Conformément à la loi, ça lui donne le droit de passer.', '', 28153),
(135399, 'frFR', '', '', 28153),
(135388, 'frFR', 'On raconte que le roi, il a plus quitté son trône depuis qu\’il a perdu sa femme.', 'On raconte que le roi, il a plus quitté son trône depuis qu\’il a perdu sa femme.', 28153),
(135387, 'frFR', 'La Horde ? Ici, à Zuldazar ? Ça sent mauvais, très mauvais.', 'La Horde ? Ici, à Zuldazar ? Ça sent mauvais, très mauvais.', 28153),
(135386, 'frFR', 'Quand Zul est parti, il a emmené bon nombre d\’entre nous. Et aujourd\’hui, on raconte que les Trolls de sang attaquent notre frontière nord.', 'Quand Zul est parti, il a emmené bon nombre d\’entre nous. Et aujourd\’hui, on raconte que les Trolls de sang attaquent notre frontière nord.', 28153),
(135385, 'frFR', '', 'Arg… Je suis désolée, mais je crains devoir solliciter votre aide une fois encore.', 28153),
(135384, 'frFR', 'Dans ce cas, nous devrons patienter.', '', 28153),
(135383, 'frFR', '', 'Mais cela pourrait prendre des années !', 28153),
(135382, 'frFR', 'Épreuves ou pas, vous ne serez lavée d\’aucun soupçon tant que la vérité ne sera pas faite sur les maux qui frappent le village.', '', 28153),
(135381, 'frFR', '', 'Quoi ? Après tout ce que j\’ai enduré !', 28153),
(135380, 'frFR', 'Je suis loin d\’être convaincu. Cela n\’explique toujours pas ce qui est arrivé à Val-Archer.', '', 28153),
(135379, 'frFR', 'Silence ! C\’est moi qui rends le verdict ici !', '', 28153),
(135378, 'frFR', 'Peut-être n\’a-t-elle rien d\’une sorcière après tout. Mais… pour notre village ?', 'Peut-être que ce n\’est pas une sorcière, après tout ! Mais et notre village, alors ?', 28153),
(135377, 'frFR', 'Elle vomit ! C\’est impossible !', '', 28153),
(135376, 'frFR', '', 'Oh… Je ne me sens pas très…', 28153),
(135375, 'frFR', '', 'Oui. Tenez, passez-moi le venin.', 28153),
(135374, 'frFR', 'Souhaitez-vous tenter de nous prouver le contraire, mademoiselle Malvoie ?', '', 28153),
(135373, 'frFR', 'Comme vous le savez, les sorcières délaissent la nourriture et se repaissent des âmes de leurs victimes. Leurs entrailles ne sont qu\’une enveloppe vide.', '', 28153),
(135372, 'frFR', 'Intéressant, mais loin d\’être concluant. Passons maintenant à l\’épreuve finale… la purge des viscères.', '', 28153),
(135371, 'frFR', 'Les mouches n\’ont pas l\’air de fuir. On dirait même qu\’elles se régalent.', 'Les mouches ne semblent pas l\’éviter. Au contraire, elles la piquent à fond !', 28153),
(135370, 'frFR', '', 'Aïe ! Ah, ça pique !', 28153),
(135369, 'frFR', '', 'Ne vous en faites pas. Je peux supporter quelques piqûres.', 28153),
(135368, 'frFR', 'Libérez les mouches, et regardez-les fuir la peau de la sorcière !', '', 28153),
(135367, 'frFR', 'La deuxième épreuve est celle des piqûres d\’insecte. Tout le monde sait que même les mouches de sang se refusent à goûter le sang vicié des sorcières.', '', 28153),
(135366, 'frFR', 'Du calme, du calme ! Rien ne dit qu\’il ne s\’agit pas d\’une supercherie. Poursuivons.', '', 28153),
(135365, 'frFR', 'Elle pleure ! Mais les sorcières peuvent pas verser de larmes, si ?', 'Elle pleure ! Les sorcières n\’ont pas de larmes, si ?', 28153),
(135364, 'frFR', '', 'Allez-y. Montrez-leur.', 28153),
(135363, 'frFR', 'L\’accusée est-elle seulement capable de pleurer ? Si tel est le cas, il est temps de le prouver.', '', 28153),
(135362, 'frFR', 'La première épreuve est celle des larmes. L\’audience entière peut attester que mademoiselle Malvoie n\’en a pas versé une seule depuis le début de ce procès.', '', 28153),
(135361, 'frFR', 'Elle a souhaité que cette personne supervise les épreuves… Un choix surprenant, mais que je lui accorde en signe de bonne foi.', '', 28153),
(135360, 'frFR', 'Comme le veut la coutume, dame Malvoie a choisi les épreuves auxquelles elle sera soumise pour prouver son innocence.', '', 28153),
(135359, 'frFR', 'Enfin ! Que le procès commence !', '', 28153),
(135358, 'frFR', 'Vous avez fini ? Je commence à perdre patience !', '', 28153),
(135357, 'frFR', 'J\’ai entendu parler d\’une sorcière qui vivait dans un marais et qui avait été démasquée parce que les mouches de sang ne s\’approchaient pas d\’elle.\n\nTout le monde se faisait piquer, sauf elle !\n\nC\’est parce que le sang d\’une sorcière est tellement fétide que même les mouches de sang refusent d\’y toucher !', '', 28153),
(135356, 'frFR', 'C\’est la première fois que je vois une vraie sorcière ! Ça me rend tout chose !', '', 28153),
(135355, 'frFR', 'Autrefois, on leur attachait des poids aux chevilles et on les jetait dans la rivière ! Si elles remontaient, c\’est qu\’elles avaient passé un pacte impie et qu\’on pouvait les pendre !\n\nC\’est la seule façon d\’innocenter une sorcière à mes yeux !', '', 28153),
(135354, 'frFR', 'La malédiction de la sorcière a emporté mon fils ! Justice doit être faite aujourd\’hui !', '', 28153),
(135353, 'frFR', '', 'Je… je ne sais pas…\n\nOn raconte qu\’une sorcière ne vomit jamais, parce que les ténèbres qui vivent en elle l\’empêchent d\’avoir le ventre plein.\n\nEn revanche, je ne sais pas comment le prouver…', 28153),
(135352, 'frFR', '', 'Il faut mettre un terme à la malédiction qui frappe notre village.\n\nTuer la sorcière à l\’origine du sort devrait faire l\’affaire, non ?', 28153),
(135351, 'frFR', 'J\’ai entendu dire que la peau d\’une sorcière ne craignait pas les flammes. C\’est pour ça qu\’on les pend !\n\nSi vous voulez me convaincre que dame Lucille n\’est pas une sorcière, portez-la au bûcher !', '', 28153),
(135350, 'frFR', 'Le mal est entré dans notre village à cause de cette femme. Elle doit payer !', '', 28153),
(135349, 'frFR', '', 'Ma mère m\’a toujours dit qu\’une sorcière ne pouvait pas verser de larmes, même si elle est triste ou si elle souffre.\n\nMademoiselle Malvoie n\’a pas pleuré quand on lui a annoncé son procès. Donc, c\’est forcément une sorcière !', 28153),
(135348, 'frFR', 'Comment innocenter une personne accusée de sorcellerie ?', 'Comment innocenter une personne accusée de sorcellerie ?', 28153),
(135347, 'frFR', '', 'C\’est terrible, ce procès, mais Val-Archer doit obtenir justice !', 28153),
(135346, 'frFR', 'Mademoiselle Malvoie, avez-vous décidé des modalités de votre défense ?', '', 28153),
(135345, 'frFR', 'Il était temps ! Que la justice fasse son œuvre.', '', 28153),
(135344, 'frFR', 'Connétable ! Vous pouvez reprendre votre… procès.', '', 28153),
(135343, 'frFR', 'Merci. Grâce à vous, nous avons gagné un temps précieux. Espérons que les villageois ne feront aucun mal à dame Malvoie.', '', 28153),
(135342, 'frFR', '', 'Me sauver ? Et vous avez l\’intention de massacrer ces villageois pour me libérer ?\n\nNon, le mieux serait que vous calmiez le maréchal.\n\nLeurs accusations sont injustifiées, mais ce sont mes concitoyens et je refuse de les voir souffrir pour m\’éviter un désagrément. Donnons-leur ce procès qu\’ils veulent tant, et je prouverai mon innocence.\n\nJe crains en revanche que le maréchal ne prenne les choses en main, je ne peux empêcher à l\’heure actuelle. Essayez de le convaincre de laisser le procès se dérouler normalement.', 28153),
(135341, 'frFR', 'Je viens vous sauver.', 'Je viens vous sauver.', 28153),
(135340, 'frFR', '', 'Navrée que vous soyez $gimpliqué:impliquée; dans cette triste affaire. Ce ne sont pas de mauvais bougres, mais les temps sont difficiles.', 28153),
(135339, 'frFR', '', 'Assez, maréchal ! Restez en dehors de cela.', 28153),
(135338, 'frFR', 'Je ne suis pas venu discuter. Si vous refusez de coopérer, je devrai recourir à la force !', '', 28153),
(135337, 'frFR', 'Mademoiselle Malvoie est accusée de sorcellerie ! Elle doit rendre compte de ses crimes !', '', 28153),
(135336, 'frFR', 'Connétable Collet ! Je vous ordonne de libérer dame Malvoie sur-le-champ !', '', 28153),
(135335, 'frFR', 'Encore ! De quoi s\’agit-il cette fois-ci ?', '', 28153),
(135334, 'frFR', 'Regardez ! Des cavaliers arrivent de la forêt !', 'Regardez ! Des cavaliers arrivent par les bois !', 28153),
(135333, 'frFR', 'Je déteste être interrompu ! Que diable venez-vous faire ici ?', '', 28153),
(135332, 'frFR', 'Connétable ! Quelqu\’un approche !', 'Connétable ! $gUn étranger:Une étrangère; approche !', 28153),
(135331, 'frFR', 'Devant la présente assistance, vous allez être jugée pour…', '', 28153),
(135330, 'frFR', 'Lucille Malvoie ! Vous êtes accusée de sorcellerie et d\’avoir lancé une malédiction sur le village de Val-Archer.', '', 28153),
(135301, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Invoquer un triklomoteur de guerre', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [70] Invoquer un triklomoteur de guerre', 28153),
(135286, 'frFR', '', 'C\’était stupide de ma part de partir seule à la recherche de reliques anciennes…', 28153),
(135281, 'frFR', 'Quoi… <hic !> ... que vous regardez comme ça ?', '', 28153),
(135272, 'frFR', 'Voyons ce qu\’on peut faire pour combattre les Trolls de sang.', 'Voyons ce qu\’on peut faire pour combattre les Trolls de sang.', 28153),
(135265, 'frFR', '', 'Il y en a un autre… ici !', 28153),
(135263, 'frFR', '', 'Là ! Torga, le Loa tortue. Il est sage et bienveillant. Je sais qu\’il nous aidera. Voyons qui d\’autre est là…', 28153),
(135261, 'frFR', '', 'Nazmir est un endroit maudit… mais c\’est la demeure des Loas. Reculez… Je vais découvrir qui se cache ici.', 28153),
(135226, 'frFR', 'Merci ! Je vivais un véritable cauchemar.', '', 28153),
(135225, 'frFR', 'Vous devez l\’arrêter !', '', 28153),
(135224, 'frFR', 'Que se passe-t-il ?', '', 28153),
(135221, 'frFR', 'Je vais vous tuer !', '', 28153),
(135220, 'frFR', 'Comment osez-vous interrompre l\’œuvre de notre maîtresse ?', '', 28153),
(135209, 'frFR', '', 'Voyons un peu ce qu\’on a là…', 28153),
(135190, 'frFR', 'Viens ici, Petit-Doigt ! J\’ai une friandise pour toi.', 'Viens ici, Petit-Doigt ! J\’ai une friandise pour toi.', 28153),
(135189, 'frFR', 'L\’Alliance a pris la mine.', 'L\’Alliance a pris la mine.', 28153),
(135188, 'frFR', 'Ben, dites donc, c\’était pas rien... Enfin, tout est bien qui finit bien, pas vrai ? Ha ha ha !', '', 28153),
(135187, 'frFR', 'Quiconque tient sssce mât… contrôle mon équipage…', '', 28153),
(135185, 'frFR', 'Certains, ils ont hâte de voir la flotte revenir. Mais j\’me souviens bien des Trolls qu\’ont pris la mer avec Zul. Z\’étaient pas commodes.', 'Certains, ils ont hâte de voir la flotte revenir. Mais j\’me souviens bien des Trolls qu\’ont pris la mer avec Zul. Z\’étaient pas commodes.', 28153),
(135184, 'frFR', 'C\’est vrai que Zul, il va être ramené en Zandalar ? J\’parie qu\’il aime pas trop cette idée.', 'C\’est vrai que Zul, il va être ramené en Zandalar ? J\’parie qu\’il aime pas trop cette idée.', 28153),
(135179, 'frFR', 'J\’aime pas trop la Horde, mais z\’avez tué un tas de racailles de l\’Alliance. Ça joue plutôt en votre faveur.', 'J\’aime pas trop la Horde, mais z\’avez tué un tas de racailles de l\’Alliance. Ça joue plutôt en votre faveur.', 28153),
(135178, 'frFR', 'Z\’avez vraiment combattu aux côtés de la princesse Talanji ? Elle a liquéfié quelqu\’un ? Ou ravagé un esprit ? Et ses maléfices, ils sont comment ?', 'Z\’avez vraiment combattu aux côtés de la princesse Talanji ? Elle a liquéfié quelqu\’un ? Ou ravagé un esprit ? Et ses maléfices, ils sont comment ?', 28153),
(135177, 'frFR', 'Paraît que vous et vos gars, vous servez une morte-vivante. Ça va pas plaire au vieux Bwonsamdi, ça.', 'Paraît que vous et vos gars, vous servez une morte-vivante. Ça va pas plaire au vieux Bwonsamdi, ça.', 28153),
(135176, 'frFR', 'Z\’êtes avec la Horde ? C\’est vrai que Vol\’jin, il est raide ?', 'Z\’êtes avec la Horde ? C\’est vrai que Vol\’jin, il est raide ?', 28153),
(135175, 'frFR', 'Loués soient les Loas pour le retour de la princesse Talanji. Elle est pas restée absente longtemps, mais ses opposants, y z\’ont pas eu besoin de plus.', 'Loués soient les Loas pour le retour de la princesse Talanji. Elle est pas restée absente longtemps, mais ses opposants, y z\’ont pas eu besoin de plus.', 28153),
(135174, 'frFR', 'D\’abord des non-Trolls, et maintenant la Horde ? À qui encore Talanji va donner le droit de venir dans notre cité ?', 'D\’abord des non-Trolls, et maintenant la Horde ? À qui encore Talanji va donner le droit de venir dans notre cité ?', 28153),
(135173, 'frFR', 'La Horde, elle est ici ? Sale époque.', 'La Horde, elle est ici ? Sale époque.', 28153),
(135147, 'frFR', 'Je… Que s\’est-il passé ? Je me taille fissa !', '', 28153),
(135140, 'frFR', 'Père, venez-moi en aide. Guidez-moi. J\’ai besoin de…', '', 28153),
(135138, 'frFR', 'Mon roi, nous avons perdu nos tours de siège et accusons de lourdes pertes…', '', 28153),
(135002, 'frFR', 'Je peux pas laisser ça là. Dépêchez-vous de l\’empocher, sinon je repars avec !', '', 28153),
(135001, 'frFR', 'Si personne n\’ouvre la cache, je vais devoir enclencher le système de rappel !', '', 28153),
(134991, 'frFR', 'On ne gagne pas à tous les coups, je suppose. Au revoir !', '', 28153),
(134989, 'frFR', 'Ça tente personne ? Sérieusement ? Bon, c\’est vous qui voyez !', '', 28153),
(134976, 'frFR', 'C\’est moi qui l\’avais vu en premier !', 'C\’est moi qui l\’avais vu en premier !', 28153),
(134975, 'frFR', 'Je peux faire un jet de besoin ?', 'Je peux faire un jet de besoin ?', 28153),
(134877, 'frFR', 'Allez, c\’est parti ! Le premier à l\’ouvrir empoche tout !', '', 28153),
(134876, 'frFR', 'Plus que quinze secondes. Attention les oreilles, ça va faire du boucan !', '', 28153),
(134875, 'frFR', 'Déverrouillage en cours ! Laissez-moi trente secondes, d\’accord ?', '', 28153),
(134869, 'frFR', 'Chargement en approche ! Attention à la tête !', '', 28153),
(134867, 'frFR', 'Écoutez bien. On a une cargaison de ravitaillement à destination des plaines !', '', 28153),
(134811, 'frFR', 'Déverrouillage terminé ! Le vainqueur prend tout !', '', 28153),
(134810, 'frFR', 'Déverrouillage terminé dans quinze secondes !', '', 28153),
(134809, 'frFR', 'Séquence de déverrouillage activée ! T moins trente secondes.', '', 28153),
(134790, 'frFR', 'Chargement déployé ! Faites attention en bas !', '', 28153),
(134789, 'frFR', 'Largage de ravitaillement en route pour les plaines !', '', 28153),
(134699, 'frFR', '', 'Continuez sans moi. Je n\’en ai pas encore fini avec cette vipère.', 28153),
(134678, 'frFR', 'On ne va pas tuer les grenouilles, mais vous, on va vous faire la peau !', '', 28153),
(134676, 'frFR', 'On va enfermer vos copains amphibiens et drainer leur mana !', '', 28153),
(134675, 'frFR', 'Je dois protéger sa nouvelle source de mana !', '', 28153),
(134674, 'frFR', 'Cette source de mana nous appartient, sale $r !', '', 28153),
(134673, 'frFR', 'On partira à la chasse aux grenouilles dès qu\’on se sera débarrassés de vous !', '', 28153),
(134672, 'frFR', 'On a ordre de ne pas tuer les grenouilles, mais ça ne vaut pas pour vous !', '', 28153),
(134671, 'frFR', 'Rien ne nous arrêtera. Ces grenouilles nous nourriront pendant des années !', '', 28153),
(134670, 'frFR', '', 'Les grenouilles appartiennent aux Nagas !', 28153),
(134669, 'frFR', '', 'Vous ne prendrez pas nos grenouilles !', 28153),
(134668, 'frFR', '', 'Mort aux voleurs de mana !', 28153),
(134667, 'frFR', '', 'Ces grenouilles nous appartiennent !', 28153),
(134666, 'frFR', '', 'Ces grenouilles sont à nous, imbécile !', 28153),
(134665, 'frFR', '', 'Ces grenouilles étancheront notre soif pour les années à venir !', 28153),
(134664, 'frFR', '', 'Avec ces grenouilles, nous sauverons notre peuple !', 28153),
(134663, 'frFR', '', 'Ces grenouilles nous nourriront !', 28153),
(134661, 'frFR', 'En attaquant Teldrassil, la Horde a agi avec lâcheté et déclenché la guerre… Les enjeux sont clairs.', '', 28153),
(134656, 'frFR', 'Krag\’wa récompensera votre loyauté. Venez.', '', 28153),
(134652, 'frFR', '', 'Les anciens nous racontaient des tas d\’histoires sur Krag\’wa. J\’étais la seule à vouloir y croire.', 28153),
(134651, 'frFR', 'Je lis dans votre cœur comme dans un livre ouvert, Narez. Vous êtes restée fidèle à Krag\’wa depuis le début.', '', 28153),
(134650, 'frFR', '', 'Attendez ! J\’ai un truc à vous dire…', 28153),
(134649, 'frFR', 'Il est temps pour moi de regagner le terrier. Merci encore pour votre aide.', '', 28153),
(134648, 'frFR', 'On dit même que votre père est devenu tellement faible qu\’il a envoyé sa fille unique supplier Zul de revenir avec la flotte. C\’est vrai, votre altesse ?', '', 28153),
(134647, 'frFR', '', 'Comment osez-vous me parler sur ce t…', 28153),
(134646, 'frFR', 'Quand Zaldraxia sera hors d\’état de nuire, les Nagas n\’auront qu\’à bien se tenir. Bonne chance.', '', 28153),
(134639, 'frFR', 'Un démolisseur ennemi est apparu dans le bâtiment sud de la Horde !', 'Un démolisseur ennemi est apparu dans le bâtiment sud de la Horde !', 28153),
(134638, 'frFR', '', 'J\’ai passé ma vie dans ces collines, et je n\’ai jamais vu pareil monstre !', 28153),
(134637, 'frFR', '<Lui montrer le message de Zul.>', '<Lui montrer le message de Zul.>', 28153),
(134630, 'frFR', '', 'J\’i-ignore ce que mijotent ma sœur et ses camarades, mais ça ne me d-dit rien qui vaille. Les s-sacrifices n\’augurent généralement rien de bon.', 28153),
(134629, 'frFR', '', 'T-tellement de pattes ! Tellement d\’yeux ! Et ces créatures sont à ma recherche !', 28153),
(134620, 'frFR', '', 'Il nous faut un vrai chef ! Pas un roitelet dégonflé.', 28153),
(134618, 'frFR', '', 'Nos frontières sont affaiblies, et notre peuple aussi. Nous avons besoin de la force que seul Zul peut nous conférer.', 28153),
(134617, 'frFR', '', 'Rappelez-vous la parole de Zul, notre prophète. Rappelez-vous la funeste fin qu\’il a prédite pour notre peuple.', 28153),
(134616, 'frFR', '', 'Le roi Rastakhan pourrit sur son trône, trop faible ou trop lâche pour aller voir ses gens. Il nous faut un chef digne de ce nom !', 28153),
(134615, 'frFR', '', 'Zul, il a prédit le Cataclysme et nous n\’avons rien fait. Nous n\’avons pas levé le petit doigt lorsque notre roi l\’a banni. Nous n\’avons pas bronché quand il a emmené nos frères et sœurs en exil. Et nous avons été les témoins impuissants des ravages du Cataclysme !', 28153),
(134613, 'frFR', '', 'Zul reviendra et alors, notre empire, il renaîtra de ses cendres.', 28153),
(134610, 'frFR', '', 'L\’heure, elle est venue ! Je dois vite avertir les autres. Ceux qui lui sont encore fidèles doivent savoir.', 28153),
(134599, 'frFR', '', 'Je serai à la hauteur, reine Azshara ! Les grenouilles seront à nous, je vous le promets !', 28153),
(134598, 'frFR', '', 'Toutes vos précieuses grenouilles seront enfermées pour combler nos besoins !', 28153),
(134597, 'frFR', '', 'Impudente VERMINE ! Notre peuple ne sera plus jamais assoiffé de magie. Nous serons enfin repus !', 28153),
(134596, 'frFR', '', 'Pourquoi… Nous étions si proches du but… Ne plus jamais avoir soif de magie…', 28153),
(134595, 'frFR', '', 'Vous ! Vous avez tout gâché… Ces grenouilles devaient alimenter notre magie pendant des années !', 28153),
(134594, 'frFR', 'Les Nagas paieront cher pour leurs crimes.', '', 28153),
(134593, 'frFR', 'Zaldraxia doit payer pour tout ce qu\’elle nous a fait. Je compte sur vous.', '', 28153),
(134592, 'frFR', 'Ha ! Mon pouvoir afflue à nouveau… et c\’est grâce à vous. Je vanterai vos mérites à Krag\’wa.', '', 28153),
(134591, 'frFR', 'Ah… Le pouvoir me revient enfin ! Beau travail, Krag\’wa saura ce que vous avez fait pour nous.', '', 28153),
(134590, 'frFR', 'Mon pouvoir… m\’est enfin rendu ! Merci, mais ma place est auprès de Krag\’wa.', '', 28153),
(134589, 'frFR', '', 'Il y a des années, quand il est revenu d\’exil avec notre flotte.$b$bIl m\’a décrit la vision qu\’il avait eue de ce jour, le jour où le monde saignerait, et il m\’a brossé votre portrait dans les moindres détails.', 28153),
(134588, 'frFR', 'Quand avez-vous parlé à Zul pour la dernière fois ?', 'Quand avez-vous parlé à Zul pour la dernière fois ?', 28153),
(134587, 'frFR', '', 'Vous ! C\’est bien vous !$b$bZul, il m\’a brossé votre portrait dans les moindres détails, jusqu\’à cette… chose… sur votre visage. En tous points conforme à sa description.$b$bAlors, est-ce vrai ? Vous m\’apportez sa parole ?', 28153),
(134584, 'frFR', 'Ainsi donc, le moment est venu. Je garde cette bête porte-message depuis l\’avènement du roi-tonnerre, et aujourd\’hui il semble que son heure soit enfin arrivée.', '', 28153),
(134583, 'frFR', 'La magie des grenouilles nourrira notre peuple. Nous n\’aurons plus jamais soif !', '', 28153),
(134581, 'frFR', '<Lui montrer le message de Zul.>', '<Lui montrer le message de Zul.>', 28153),
(134580, 'frFR', 'Qu\’y a-t-il, $gétranger:étrangère; ?', '', 28153),
(134492, 'frFR', '', 'Un coup de main, c\’est pas trop tôt ! Les Nagas m\’ont eue par surprise. Faut sauver les grenouilles.', 28153),
(134471, 'frFR', '', 'Le lionceau de Hurlevent se serait-il enfin décidé à quitter sa tanière ? Vous ne savez pas à qui vous avez affaire, jeune roi. La partie ne fait que commencer !', 28153),
(134465, 'frFR', '', 'Humpf… J\’reste cachée ici à poireauter, et j\’ai horreur des deux. Découvrez ce que les Nagas mijotent avec les grenouilles !', 28153),
(134464, 'frFR', 'C\’est tout ce dont vous êtes capable, Coursevent ?', '', 28153),
(134463, 'frFR', 'Toutes les unités aux portes ! La victoire appartient à l\’Alliance !', '', 28153),
(134460, 'frFR', '', 'Pervertir ces grenouilles… ces Nagas, ils l\’emporteront pas au paradis.', 28153),
(134453, 'frFR', 'La princesse, elle est plus là pour vous sauver, maintenant.', 'La princesse, elle est plus là pour vous sauver, maintenant.', 28153),
(134451, 'frFR', 'Ha ha ! Personne va venir vous sauver… sauf moi.', 'Ha ha ! Personne va venir vous sauver… sauf moi.', 28153),
(134450, 'frFR', 'Les gardes, ils en ont rien à cirer, de c\’qui arrive aux saletés d\’étrangers.', 'Les gardes, ils en ont rien à cirer, de c\’qui arrive aux saletés d\’étrangers.', 28153),
(134449, 'frFR', 'Mon couteau, il me dit que z\’allez me faire une p\’tite ristourne.', 'Mon couteau, il me dit que z\’allez me faire une p\’tite ristourne.', 28153),
(134448, 'frFR', 'Z\’avez pas payé à temps pour votre protection.', 'Z\’avez pas payé à temps pour votre protection.', 28153),
(134447, 'frFR', 'Votre Altesse, vous ne sentez pas la peur qui étreint cette ville ?', '', 28153),
(134442, 'frFR', 'Hé hé… Les commandes sont déjà parties…', '', 28153),
(134439, 'frFR', 'Ah ! Plus de viande pour faire des saucisses !', '', 28153),
(134438, 'frFR', 'Ha ! Vous en redemandez, c\’est ça ? Laissez-moi vous donner un avant-goût de ce que la Horde vous réserve.', '', 28153),
(134330, 'frFR', 'Sauve qui peut !', 'Sauve qui peut !', 28153),
(134329, 'frFR', 'C\’est le chaos ! Je dois vite me mettre à l\’abri.', 'C\’est le chaos ! Je dois vite me mettre à l\’abri.', 28153),
(134328, 'frFR', 'Ces Troggs sont sortis de nulle part !', 'Ces Troggs sont sortis de nulle part !', 28153),
(134310, 'frFR', 'Le temple est en ruine. C\’est encore pire que ce que je craignais.', '', 28153),
(134309, 'frFR', 'Avant d\’être assassiné, j\’étais le gardien de ce temple. Je crains qu\’il n\’ait perdu de sa splendeur au cours des décennies qui ont suivi ma mort…', '', 28153),
(134300, 'frFR', 'Aïe ! Vilain dino, vilain !', 'Aïe ! Vilain dino, vilain !', 28153),
(134299, 'frFR', 'C\’est bien !', 'C\’est bien !', 28153),
(134298, 'frFR', 'Argh ! Pas les doigts !', 'Argh ! Pas les doigts !', 28153),
(134297, 'frFR', 'Continue comme ça et je vais t\’apprendre les bonnes manières !', 'Continue comme ça et je vais t\’apprendre les bonnes manières !', 28153),
(134296, 'frFR', 'Aïeuh ! On ne mord pas !', 'Aïeuh ! On ne mord pas !', 28153),
(134295, 'frFR', 'Tout doux... tout doux !', 'Tout doux... tout doux !', 28153),
(134292, 'frFR', '%s se met à gémir en frissonnant.', '', 28153),
(134291, 'frFR', '%s pousse un couinement affolé.', '', 28153),
(134290, 'frFR', '%s pousse un couinement terrifié.', '', 28153),
(134289, 'frFR', 'Je vous accompagnerai dans les ruines du temple.', 'Je vous accompagnerai dans les ruines du temple.', 28153),
(134288, 'frFR', 'Nickel aboie en direction d\’une hermine.', '', 28153),
(134279, 'frFR', 'Ils se nourrissent de ma magie !', '', 28153),
(134278, 'frFR', 'Ils volent notre magie !', '', 28153),
(134277, 'frFR', 'Argh… Ma magie… elle me quitte…', '', 28153),
(134276, 'frFR', 'Je suis… à bout de forces… Ils m\’ont volé mon pouvoir !', '', 28153),
(134275, 'frFR', 'Ces misérables ont enlevé mes amis !', '', 28153),
(134274, 'frFR', 'Ces malotrus étaient en train de me vider de ma magie !', '', 28153),
(134272, 'frFR', 'Pas cette fois…', '', 28153),
(134271, 'frFR', 'L\’Alliance n\’abandonnera aucun de ses soldats !', '', 28153),
(134270, 'frFR', 'Les morts se relèvent ! Nous devons évacuer les blessés !', '', 28153),
(134266, 'frFR', 'VICTOIRE AUX RÉPROUVÉS !', '', 28153),
(134263, 'frFR', 'La peste est bien trop dangereuse, mon roi ! Nous devons…', '', 28153),
(134252, 'frFR', 'Que la Lumière vous bénisse tous. Amenez-moi les blessés !', '', 28153),
(134233, 'frFR', '', 'Merci à tous ! Je me charge du reste !', 28153),
(134230, 'frFR', 'Maudits… sauvages !', 'Maudits… sauvages !', 28153),
(134229, 'frFR', 'Je meurs… pour mon roi… pour Lordaer…', 'Je meurs… pour mon roi… pour Lordaer…', 28153),
(134227, 'frFR', 'Ça n\’en finira jamais… Il en vient toujours plus ! Héros, j\’ai besoin de vous !', 'Ça n\’en finira jamais… Il en vient toujours plus ! Héros, j\’ai besoin de vous !', 28153),
(134226, 'frFR', '', 'Euh… J\’aurais bien besoin d\’un coup de main.', 28153),
(134224, 'frFR', '', 'Archers, encochez vos flèches ! En avant !', 28153),
(134223, 'frFR', 'Héros ! Nous sommes submergés ! Je ne vais pas pouvoir les garder en vie bien longtemps…', '', 28153),
(134211, 'frFR', 'Si beeaauu…', '', 28153),
(134209, 'frFR', 'Minute… vous entendez ça ?', '', 28153),
(134208, 'frFR', 'Timonier, passez au large !', 'Timonier, passez au large !', 28153),
(134186, 'frFR', 'Vous avez raison ! $p doit officiellement rejoindre la bande. Préparez le rituel !', '', 28153),
(134164, 'frFR', '', 'Allez, Drekal. On poursuit les recherches.', 28153),
(134163, 'frFR', '', 'Je vois rien d\’intéressant ici.', 28153),
(134162, 'frFR', '', 'Pourquoi vous nous avez appelés ?', 28153),
(134161, 'frFR', '', 'Vous connaissez l\’histoire de l\’andouille |2 $R qui criait au loup ?', 28153),
(134159, 'frFR', '', 'Ça vous amuse, c\’est ça ?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(134158, 'frFR', 'Oh non… C\’est pas de la bière dans ce tonneau.', '', 28153),
(134157, 'frFR', 'Les clients en ont marre d\’attendre. Larguez les amarres !', 'Les clients en ont marre d\’attendre. Larguez les amarres !', 28153),
(134156, 'frFR', '', 'Le programme a changé, les gars ! Emportez vos grogs avec vous !', 28153),
(134155, 'frFR', '', 'Pourquoi vous nous faites perdre notre temps ?', 28153),
(134151, 'frFR', '', 'Cette fusée éclairante, c\’est pas un jouet.', 28153),
(134150, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Défendre le bâtiment sud de l\’Alliance', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Défendre le bâtiment sud de l\’Alliance', 28153),
(134149, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Défendre le bâtiment nord de l\’Alliance', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Défendre le bâtiment nord de l\’Alliance', 28153),
(134125, 'frFR', '', 'Tant pis, on n\’a pas le temps de l\’attendre. J\’ai trouvé quelqu\’un qui prétend savoir où est Rakera. Venez, par ici !', 28153),
(134123, 'frFR', '', 'Il ne faut pas s\’attarder ici. Envoyez une fusée éclairante si vous trouvez quelque chose.', 28153),
(134116, 'frFR', 'Ces terres nous appartiennent, chiens galeux ! Vous avez signé votre arrêt de mort !', '', 28153),
(134115, 'frFR', 'Soldats ! En formation !', '', 28153),
(134111, 'frFR', 'Cet endroit ne me manquera pas, ça, c\’est sûr !', '', 28153),
(134109, 'frFR', '', 'Vous avez beaucoup d\’exigences pour quelqu\’un qui est aussi près de mon épée.', 28153),
(134101, 'frFR', 'Vous n\’avez rien à faire ici !', 'Vous n\’avez rien à faire ici !', 28153),
(134100, 'frFR', 'Ooh, je prends le tonneau vide ! Vous n\’avez qu\’à prendre l\’autre.', '', 28153),
(134099, 'frFR', 'Vite, planquez-vous !', '', 28153),
(134096, 'frFR', 'Le petit secret de Corsandre.', '', 28153),
(134095, 'frFR', 'Qu\’est-ce que c\’était que ÇA ?!', '', 28153),
(134094, 'frFR', 'Voulez-vous vraiment construire une tour de guet pour 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 'Voulez-vous vraiment construire une tour de guet pour 50 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 28153),
(134093, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Construire une tour de guet', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Construire une tour de guet', 28153),
(134092, 'frFR', 'Mais oui, Man\’zul. On aurait dû t\’écouter. T\’as pas mérité ce sort. Et on aurait mieux fait de suivre ton plan. Et t\’es le plus malin. Mais maintenant, tu la boucles ou je te repince le nez !', '', 28153),
(134091, 'frFR', 'Man\’zul, cette auberge accueille des familles ! Tout ça, c\’est derrière nous.', '', 28153),
(134090, 'frFR', 'Ha ! J\’aime votre style, $p, mais j\’ai été plus rapide que vous. Tout ce qu\’il lui reste, c\’est cet affreux couvre-œil et son sourire éblouissant.', '', 28153),
(134089, 'frFR', 'Arrête de défier tous nos clients en duel, Volni ! Les deux derniers que tu as tués n\’ont jamais payé leurs dettes.', '', 28153),
(134088, 'frFR', 'Parlez plus fort ! Je peux pas écouter votre conversation si vous marmonnez dans votre coin !', '', 28153),
(134087, 'frFR', 'Tu trompes personne, Volni. Je sais que t\’adores ce chapeau et je te l\’enlèverai pas tant que tu l\’admettras pas !', '', 28153),
(134086, 'frFR', 'Attendez, elle entend rien à cause de son fichu tambour. Hé, Grenja, fais une pause, tu veux ? Comment faire pour te saluer sinon ? Grenja est notre barde, mais parfois elle oublie qu\’on a besoin de causer.', '', 28153),
(134085, 'frFR', 'Tout va bien, $p ? Vous fichez la trouille à Grenja, là… Vous avez un coup de chaud ?', '', 28153),
(134084, 'frFR', 'Bien vu, $p ! Grenja nous a tirés du pétrin plus d\’une fois à Zuldazar, en bloquant des portes… ou en les enfonçant. Et je vous raconte pas ce qu\’elle a fait à certains.', '', 28153),
(134079, 'frFR', 'OK, au boulot, mon vieux Tocant !', '', 28153),
(134078, 'frFR', 'Toutefois… Je vous suis très reconnaissant de ce que vous avez fait pour notre village. Je vais voir ce que je peux faire…', '', 28153),
(134077, 'frFR', 'Je doute qu\’ils souhaitent s\’entretenir avec $gun étranger:une étrangère; du continent.', '', 28153),
(134076, 'frFR', 'Une malédiction accable nos terres, et qu\’ont fait les Malvoie aux premiers signes ? Ils ont pris leurs jambes à leur cou. Ils sont cloîtrés dans leur manoir tandis que leurs sujets tombent aux mains d\’un mal invisible.', '', 28153),
(134075, 'frFR', 'Vous souhaitez rencontrer ces pleutres de Malvoie ? Je doute que cela vous apporte quoi que ce soit.', '', 28153),
(134074, 'frFR', 'Je souhaite voir le seigneur de la maison Malvoie.', 'Je souhaite voir le seigneur de la maison Malvoie.', 28153),
(134073, 'frFR', 'Je ne vous remercierai jamais assez d\’avoir sauvé notre village.\n\nHavrebrune a une grande dette envers vous.', '', 28153),
(134072, 'frFR', 'En quoi puis-je vous aider, $c ?', '', 28153),
(134070, 'frFR', '', 'Ah, vous êtes de retour ! Vous avez disparu plus longtemps que prévu. Vous avez eu des problèmes ?', 28153),
(134069, 'frFR', '', 'Vous pouvez prendre ma fusée pour rentrer à votre base. C\’est un aller simple, alors assurez-vous de ne rien oublier ici.', 28153),
(134068, 'frFR', '', 'Hey, c\’est du vrai travail de pro ce que vous avez fait, mais on peut se charger du reste, ici.', 28153),
(134067, 'frFR', 'Fichons le camp d\’ici.', 'Fichons le camp d\’ici.', 28153),
(134066, 'frFR', 'À en croire Triture, cette fusée constitue un véhicule fiable pour un aller simple. À en croire mes yeux, Triture raconte n\’importe quoi.', '', 28153),
(134065, 'frFR', 'Écrasez toute résissstance ! Pour la gloire de la reine !', '', 28153),
(134064, 'frFR', 'Anéantisssez tout ce qui sssort du temple !', '', 28153),
(134063, 'frFR', 'Sssaisisssez ces reliques pour la reine !', '', 28153),
(134062, 'frFR', 'La reine exige qu\’on lui apporte ssses reliques ! Dépêchez-vous de tout ramasssser !', '', 28153),
(134061, 'frFR', 'Ravi de vous voir tous en un seul morceau grâce à… Hé, voilà justement notre vedette !', '', 28153),
(134060, 'frFR', 'Mes… trésors…', '', 28153),
(134059, 'frFR', 'Vous osez toucher à mon trésor ?!', '', 28153),
(134018, 'frFR', '<Tenter d\’ouvrir le coffre.>', '<Tenter d\’ouvrir le coffre.>', 28153),
(134017, 'frFR', 'Le coffre est verrouillé, mais vous devriez pouvoir le forcer en insistant un peu.', '', 28153),
(134016, 'frFR', '', 'Un autre navire de l\’Alliance est déjà à quai. J\’espère que ses passagers ont reçu meilleur accueil que Jaina…', 28153),
(134015, 'frFR', 'Vous me sauvez la vie !', '', 28153),
(134014, 'frFR', 'Je ne l\’oublierai pas. Merci !', '', 28153),
(134013, 'frFR', 'Je vous dois une bonne pinte !', '', 28153),
(134012, 'frFR', 'Merci, j\’étais à deux doigts de flancher.', '', 28153),
(134011, 'frFR', 'Les Nagas ont enchaîné les autres et les ont emmenés. Pitié, sauvez-les !', '', 28153),
(134010, 'frFR', 'Sang et honneur ! La prochaine fois qu\’on se voit, je paie ma tournée !', '', 28153),
(134009, 'frFR', '', 'J\’ignore ce qui vous est arrivé, mais ça a fonctionné ! Comment… comment vous sentez-vous ?', 28153),
(134007, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(134003, 'frFR', 'Tous unis ! POUR L\’ALLIANCE !', '', 28153),
(134001, 'frFR', 'La reine banshee doit répondre de ses crimes si nous voulons assurer notre avenir. Son règne de terreur prend fin aujourd\’hui !', '', 28153),
(134000, 'frFR', 'Leur objectif n\’est pas de conquérir nos terres, mais d\’anéantir nos vies… ainsi que tout espoir pour les générations futures.', '', 28153),
(133999, 'frFR', 'Ensemble, nous repousserons le mal qui ronge ces terres… et hisserons de nouveau nos bannières sur Lordaeron !', '', 28153),
(133998, 'frFR', 'Mes frères et sœurs de l\’Alliance, écoutez-moi !', '', 28153),
(133996, 'frFR', 'Le roi Anduin mène l\’assaut ! Donnez tout ce que vous avez et prenez le contrôle du champ de bataille !', '', 28153),
(133990, 'frFR', 'Engin de siège opérationnel !', '', 28153),
(133989, 'frFR', 'Et un engin de siège pour notre $gami:amie;, un !', '', 28153),
(133988, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Construire un engin de siège', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [100] Construire un engin de siège', 28153),
(133986, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Former un spécialiste des mortiers - Attaque au nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Former un spécialiste des mortiers - Attaque au nord', 28153),
(133985, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Former des cavaliers - Attaque au nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Former des cavaliers - Attaque au nord', 28153),
(133984, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Former des fusiliers - Attaque au nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Former des fusiliers - Attaque au nord', 28153),
(133983, 'frFR', 'Va falloir cracher au bassinet si vous voulez que j\’honore les commandes.', '', 28153),
(133982, 'frFR', 'Bienvenue dans mon échoppe !', '', 28153),
(133981, 'frFR', '', 'Maître des écuries Lucia Faroncombe, à votre service !', 28153),
(133980, 'frFR', '', 'La formation de nos cavaliers s\’avère fort coûteuse, $n.', 28153),
(133979, 'frFR', '', 'Ravie de vous revoir, $n ! En quoi puis-je vous aider ?', 28153),
(133974, 'frFR', '', 'Tout travail mérite salaire !$B$BRevenez me voir quand vous aurez les moyens !', 28153),
(133971, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Former des cavaliers - Attaque au sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [60] Former des cavaliers - Attaque au sud', 28153),
(133970, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Former un spécialiste des mortiers - Attaque au sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [50] Former un spécialiste des mortiers - Attaque au sud', 28153),
(133969, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Former des fusiliers - Attaque au sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [40] Former des fusiliers - Attaque au sud', 28153),
(133968, 'frFR', '', 'Vous en avez mis, du temps ! Au boulot, et que ça saute !', 28153),
(133960, 'frFR', '<Vous présenter poliment.>', '<Vous présenter poliment.>', 28153),
(133959, 'frFR', '<Vous présenter poliment.>', '<Vous présenter poliment.>', 28153),
(133958, 'frFR', '', 'Elle va bien ? J\’avais pourtant dit à Kaja de ne pas partir à ma recherche.', 28153),
(133953, 'frFR', 'Cette ville engloutie était autrefois un auguste temple dédié à Gral, le Loa des mers.$b$bMais les Nagas ont débarqué et l\’ont détruit. Tous ses disciples ont été massacrés.$B$BSi Gral a survécu, il est grandement affaibli.', '', 28153),
(133952, 'frFR', 'Qu\’est-ce qui se passe ? On se fait attaquer, ou quoi ?', '', 28153),
(133951, 'frFR', 'Y a quelque chose qu\’est tombé du ciel, là-bas !', '', 28153),
(133950, 'frFR', 'Mes frères laissent leur haine pour les Nagas obscurcir leur jugement. Ce n\’est pas la première fois que la maîtresse Viss et ses Nagas anneaux-sinistres nous traquent ainsi.$b$bVoyez-vous, ils savent que nous savons quelque chose qu\’ils ignorent.', '', 28153),
(133947, 'frFR', '', 'Vous implorerez ma pitié !', 28153),
(133946, 'frFR', 'Il me faut un moyen de transport pour Glaucombe.', 'Il me faut un moyen de transport pour Glaucombe.', 28153),
(133945, 'frFR', 'Ma lame sera votre perte !', 'Ma lame sera votre perte !', 28153),
(133944, 'frFR', 'Je vous dépose quelque part ?', '', 28153),
(133943, 'frFR', 'Je ne fais pas de prisonniers !', 'Je ne fais pas de prisonniers !', 28153),
(133942, 'frFR', '', 'Vous allez payer cette interruption de votre vie !', 28153),
(133941, 'frFR', '', 'Ratissez-moi ce camp ! Je veux qu\’on m\’apporte tout ce sur quoi Goji et sa troupe travaillaient.', 28153),
(133939, 'frFR', 'La reine des pirates vengera ma mort !', '', 28153),
(133938, 'frFR', 'Qui a laissé cette andouille monter à bord de mon bateau ?', '', 28153),
(133936, 'frFR', 'À mort, vermisseau !', 'À mort, vermisseau !', 28153),
(133935, 'frFR', 'Alors, on joue les braves ?', 'Alors, on joue les braves ?', 28153),
(133934, 'frFR', 'Tout ce que vous possédez m\’appartient désormais !', 'Tout ce que vous possédez m\’appartient désormais !', 28153),
(133933, 'frFR', 'Cette terre appartient à la compagnie Corsandre !', 'Cette terre appartient à la compagnie Corsandre !', 28153),
(133929, 'frFR', 'Votre présence ici est malvenue !', 'Votre présence ici est malvenue !', 28153),
(133928, 'frFR', 'Vous allez périr ici !', 'Vous allez périr ici !', 28153),
(133926, 'frFR', 'Je n\’oublierai pas votre bonté...', 'Je n\’oublierai pas votre bonté...', 28153),
(133925, 'frFR', 'Mes tourments s\’achèvent enfin...', 'Mes tourments s\’achèvent enfin...', 28153),
(133924, 'frFR', 'Je vous remercie, $gétranger:étrangère;...', 'Je vous remercie, $gétranger:étrangère;...', 28153),
(133923, 'frFR', 'Je savais qu\’Eraka no Kimbul nous enverrait de l\’aide...', 'Je savais qu\’Eraka no Kimbul nous enverrait de l\’aide...', 28153),
(133919, 'frFR', 'Je peux enfin reposer en paix...', 'Je peux enfin reposer en paix...', 28153),
(133918, 'frFR', 'Je savais que les Loas ne nous oublieraient pas...', 'Je savais que les Loas ne nous oublieraient pas...', 28153),
(133917, 'frFR', 'Sautez par-dessus l\’obstacle indiqué. Le jury peut ne pas tenir compte d\’un saut si votre monture n\’est pas parfaitement alignée au centre !', 'Sautez par-dessus l\’obstacle indiqué. Le jury peut ne pas tenir compte d\’un saut si votre monture n\’est pas parfaitement alignée au centre !', 28153),
(133916, 'frFR', 'Si vous sautez trop tôt ou trop tard, votre cheval risque de vous désarçonner.', 'Si vous sautez trop tôt ou trop tard, votre cheval risque de vous désarçonner.', 28153),
(133915, 'frFR', 'T\’inquiète, je vais pas me perdre ! Et de toute façon, je sais que tu viendrais quand même me chercher.', '', 28153),
(133913, 'frFR', 'Une fois au petit galop, passez au Grand galop pour aller encore plus vite !', 'Une fois au petit galop, vous pouvez accélérer en passant au Grand galop !', 28153),
(133912, 'frFR', 'Utilisez Petit galop pour accélérer. C\’est l\’allure idéale pour le saut d\’obstacles !', 'Utilisez Petit galop pour accélérer. C\’est l\’allure idéale pour le saut d\’obstacles !', 28153),
(133911, 'frFR', 'Utilisez Pas pour avancer et Stop pour vous arrêter à tout instant.', 'Utilisez Pas pour avancer et Stop pour vous arrêter à tout instant.', 28153),
(133904, 'frFR', 'Les Gloubelins sont des créatures abjectes. Ces sales petits larbins des bas-fonds exécutent religieusement les ordres de leurs maîtres nagas, quel que soit le mépris avec lequel ils sont traités.', '', 28153),
(133899, 'frFR', 'Humpf, Shoak va peut-être enfin comprendre que ce n\’est pas le genre d\’endroit qu\’on explore, mais plutôt qu\’on fuit en vitesse !', '', 28153),
(133893, 'frFR', 'Humpf… De rien, pauvre crétin. Et que je ne t\’y reprenne plus !', '', 28153),
(133883, 'frFR', 'Un démolisseur ennemi est apparu dans le bâtiment nord de la Horde !', 'Un démolisseur ennemi est apparu dans le bâtiment nord de la Horde !', 28153),
(133835, 'frFR', 'Malheureusement, lever une armée coûte cher, $n. Les soldats, faut pouvoir les nourrir, les entraîner et leur fournir à chacun une armure fabriquée main.\n\nRevenez quand vous aurez les poches pleines.', '', 28153),
(133834, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Former des fantassins - Attaque au sud', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Former des fantassins - Attaque au sud', 28153),
(133833, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Former des fantassins - Attaque au nord', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [20] Former des fantassins - Attaque au nord', 28153),
(133832, 'frFR', '', 'Combien de corps… tu as mangés… pour avoir autant de pouvoir ?', 28153),
(133831, 'frFR', '', 'Les murmures, on les entend, ils parlent de vous… J\’ai hâte de vous dévorer !', 28153),
(133830, 'frFR', '', 'Personne… me mangera… pour prendre… mon pouvoir…', 28153),
(133829, 'frFR', '', 'Je vais me garder votre bras à manger, et ensuite je vais vous jeter au totem !', 28153),
(133828, 'frFR', '', 'Les murmures… ils disent que la chair… elle nous rendra plus forts…', 28153),
(133827, 'frFR', '', 'Les murmures, ils disent que cette chair, elle nous donnera le pouvoir !', 28153),
(133820, 'frFR', 'Vous n\’avez pas assez d\’or de front de guerre pour construire un bâtiment.', 'Vous n\’avez pas assez d\’or de front de guerre pour construire un bâtiment.', 28153),
(133819, 'frFR', 'Nous ne pouvons pas entreprendre de nouvelle construction tant que le chantier précédent n\’est pas terminé.', 'Nous ne pouvons pas entreprendre de nouvelle construction tant que le chantier précédent n\’est pas terminé.', 28153),
(133806, 'frFR', 'Si vous deviez revenir dans ce temple, ce serait en $uami:amie; et $uinvité:invitée; d\’honneur.', '', 28153),
(133805, 'frFR', 'Pour récompenser de votre courage, je vous offre une bénédiction de puissance. Puisse-t-elle vous servir lors de vos prochains combats.', '', 28153),
(133804, 'frFR', 'De plus, vous avez secouru les esprits de mes serviteurs et êtes $Uvenu:venue; en aide à ce temple.', '', 28153),
(133803, 'frFR', 'Kuppaka a enfin rendu l\’âme et les artéfacts de puissance dérobés ont été arrachés aux mains des Tortaka.', '', 28153),
(133801, 'frFR', 'Les Tortaka sont au-delà de toute rédemption. Kuppaka et sa tribu doivent mourir, et les sources de leur pouvoir occulte doivent être détruites.', '', 28153),
(133799, 'frFR', 'Je n\’aurais jamais imaginé que leur soif de pouvoir les conduirait à de telles extrémités… Que faire ?', '', 28153),
(133798, 'frFR', 'La tribu Tortaka n\’aura de cesse qu\’elle ait siphonné l\’énergie de tous les esprits du temple.', '', 28153),
(133794, 'frFR', 'Voulez-vous vraiment construire une forge pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 'Voulez-vous vraiment construire une forge pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 28153),
(133793, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire une forge', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire une forge', 28153),
(133790, 'frFR', 'Voulez-vous vraiment construire un atelier pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 'Voulez-vous vraiment construire un atelier pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 28153),
(133788, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire un atelier', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire un atelier', 28153),
(133786, 'frFR', 'Voulez-vous vraiment construire des écuries pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 'Voulez-vous vraiment construire des écuries pour 150 |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:20|t pièces d\’or de front de guerre ?', 28153),
(133785, 'frFR', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire des écuries', '|TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t [150] Construire des écuries', 28153),
(133784, 'frFR', 'Choisissez le bâtiment que vous souhaitez construire à cet endroit :', 'Choisissez le bâtiment que vous souhaitez construire à cet endroit :', 28153),
(133775, 'frFR', 'Shoak s\’est encore fourré dans un sale pétrin ! Je n\’arrive pas à croire que ce balourd se soit fait capturer par les Trolls de sang.', '', 28153),
(133769, 'frFR', 'SHOAK ! Où es-tu ? SHOAK !', '', 28153),
(133768, 'frFR', 'Je connais un endroit où nous pourrons rassembler tout le monde. Suivez-moi !', '', 28153),
(133765, 'frFR', 'Votre âme est condamnée !', '', 28153),
(133764, 'frFR', 'Votre Loa n\’a aucun pouvoir ici !', '', 28153),
(133763, 'frFR', 'Votre âme sera bientôt à nous !', '', 28153),
(133760, 'frFR', 'Les Tortaka ne tolèrent pas les étrangers !', '', 28153),
(133759, 'frFR', 'Vous n\’avez rien à faire ici !', '', 28153),
(133758, 'frFR', 'Eraka no Kimbul n\’a aucun pouvoir ici !', '', 28153),
(133757, 'frFR', 'La puissance de ce royaume est nôtre !', '', 28153),
(133756, 'frFR', 'Le Loa lui-même ne nous arrêtera pas !', '', 28153),
(133755, 'frFR', 'Laissez-moi vous montrer toute l\’étendue de ma puissance !', '', 28153),
(133754, 'frFR', 'La puissance sera nôtre !', '', 28153),
(133752, 'frFR', 'Nous allons nous repaître de votre âme !', '', 28153),
(133745, 'frFR', '', 'Que sssais-tu de nos plans ? Parle, à la fin !', 28153),
(133742, 'frFR', '', 'Parle ! Que sssais-tu des sssecrets du temple ?', 28153),
(133741, 'frFR', '', 'Tu parleras ou tu trépasssseras !', 28153),
(133732, 'frFR', 'Je vais me mettre à l\’abri pendant que vous secourez Shoak. Inutile de vous obliger à nous sauver tous les deux.', '', 28153),
(133731, 'frFR', '[Après une brève traversée en bac...]', '[Après une brève traversée en bac...]', 28153),
(133730, 'frFR', 'Merci pour la course, Tae. Je vais faire mon rapport au vieux.', '', 28153),
(133729, 'frFR', 'Quel abruti… Pourquoi a-t-il fallu qu\’il aille se faire capturer par les Trolls de sang ?', '', 28153),
(133728, 'frFR', 'Shoak est aux mains des Trolls natha\’vor.', '', 28153),
(133727, 'frFR', 'Non… Non, non !', '', 28153),
(133726, 'frFR', 'Oh, non…', '', 28153),
(133725, 'frFR', 'Arrête de me tourner autour ! Va plutôt chercher Shoak !', '', 28153),
(133724, 'frFR', 'C\’était quoi, ce bruit ? Je vais garder la princesse et vous, vous allez voir ce que c\’est.', '', 28153),
(133723, 'frFR', 'Havrebrune vous doit une fière chandelle. Comment pouvons-nous vous remercier ?', '', 28153),
(133722, 'frFR', 'Merci infiniment… J\’ai bien cru que j\’étais condamné à rester dans cet état pour l\’éternité…', '', 28153),
(133721, 'frFR', 'Que… Que s\’est-il passé ?', '', 28153),
(133720, 'frFR', '', 'Vous êtes de retour ! … Et les villageois ont l\’air de reprendre leurs esprits également !', 28153),
(133719, 'frFR', '', 'Vous ne pouvez rien contre… la malédiction…', 28153),
(133718, 'frFR', '', 'Notre pouvoir est ancien. Préparez-vous à mourir !', 28153),
(133717, 'frFR', '', 'Je vais vous montrer la puissance du Sabbat !', 28153),
(133716, 'frFR', '', 'Vous devriez partir. Ou vous risquez de subir le même sort.', 28153),
(133715, 'frFR', '', 'Misérable $c ! Ce village est à moi, au nom de la Matriarche !', 28153),
(133714, 'frFR', 'Elle est dangereuse… mais bien moins que moi si je découvre que tu trempes dans une sale affaire.', 'Elle est dangereuse… mais bien moins que moi si je découvre que tu trempes dans une sale affaire.', 28153),
(133713, 'frFR', 'Quoi que tu manigances, il vaudrait mieux pour toi que la vieille folle des bois ne soit pas impliquée.', 'Quoi que tu manigances, il vaudrait mieux pour toi que la vieille folle des bois ne soit pas impliquée.', 28153),
(133712, 'frFR', 'Mon cher mari… Sache que je ne suis pas dupe, je sais que tu sors en douce, la nuit, quand tu me crois endormie.', 'Mon cher mari… Sache que je ne suis pas dupe, je sais que tu sors en douce, la nuit, quand tu me crois endormie.', 28153),
(133711, 'frFR', 'Je tenterai une nouvelle livraison d\’ici la fin de la semaine.', 'Je tenterai une nouvelle livraison d\’ici la fin de la semaine.', 28153),
(133710, 'frFR', 'Mes cochons ont contracté une maladie qui les rend extrêmement agressifs et j\’ai eu le plus grand mal à les rassembler pour le transport.', 'Mes cochons ont contracté une maladie qui les rend extrêmement agressifs et j\’ai eu le plus grand mal à les rassembler pour le transport.', 28153),
(133709, 'frFR', 'La vieille dame en bas de la route m\’a gentiment proposé des épluchures pour nourrir les bêtes, mais je crains qu\’elles n\’aient été contaminées.', 'La vieille dame en bas de la route m\’a gentiment proposé des épluchures pour nourrir mes bêtes, mais je crains qu\’elles n\’aient été contaminées.', 28153),
(133708, 'frFR', 'Monsieur Staughton, je vous prie de m\’excuser pour le retard de la dernière livraison de porcs.', 'Monsieur Staughton, je vous prie de m\’excuser pour le retard de la dernière livraison de porcs.', 28153),
(133707, 'frFR', 'Veuillez signaler toute personne ou activité suspecte au maire Leblanc.', '', 28153),
(133706, 'frFR', 'De dangereuses créatures ont été repérées dans les environs. Aussi, nous invitons les habitants qui quittent la ville à redoubler de prudence.', '', 28153),
(133705, 'frFR', 'Pour la sécurité de tous, les villageois sont tenus de regagner leur maison avant le coucher du soleil.', '', 28153),
(133704, 'frFR', 'Suite aux récentes disparitions, un couvre-feu a été mis en place à Havrebrune.', '', 28153),
(133703, 'frFR', 'Je suis prêt à parier ma dernière torche que c\’est l\’œuvre de cette vieille mégère !', 'Je suis prêt à parier ma dernière torche que c\’est l\’œuvre de cette vieille mégère !', 28153),
(133702, 'frFR', 'À ce rythme, nous serons à court de nourriture pour cochons avant un mois. Cet endroit serait-il maudit ?', 'À ce rythme, nous serons à court de nourriture pour cochons avant un mois. Cet endroit serait-il maudit ?', 28153),
(133701, 'frFR', 'J\’ignore d\’où viennent ces satanées mouches, mais elles reviennent chaque matin depuis deux semaines.', 'J\’ignore d\’où viennent ces satanées mouches, mais elles reviennent chaque matin depuis deux semaines.', 28153),
(133700, 'frFR', '', 'Cherchez des écrits récents de villageois, ils nous mettront peut-être sur la piste des coupables.', 28153),
(133699, 'frFR', '', 'Le grand livre du village nous dira peut-être si les habitants ont remarqué des activités suspectes, je vais le consulter.', 28153),
(133698, 'frFR', '', 'Oh non… pas ici aussi !', 28153),
(133693, 'frFR', '', 'Tu ne comprends pas. On ne sera en sécurité nulle part si Jakra\’zet réussit.', 28153),
(133692, 'frFR', '', 'Je ne pouvais pas te laisser mourir ! On peut encore s\’enfuir et recommencer notre vie ailleurs, loin de tout ça.', 28153),
(133691, 'frFR', '', 'Tu n\’aurais pas dû venir me chercher, Kaja.', 28153),
(133690, 'frFR', '', 'J\’ai cru qu\’on se reverrait plus jamais…', 28153),
(133689, 'frFR', 'Partiellement détruits, vous dites… C\’est mieux que rien. Voyons si on peut trouver ce grand dadais…', '', 28153),
(133688, 'frFR', 'SHOAK ! La plaisanterie a assez duré. L\’avant-poste des Trolls de sang est dangereusement proche !', '', 28153),
(133686, 'frFR', '', 'Rakera ! Tu es vivante !', 28153),
(133685, 'frFR', 'Zolani, ma lame jurée, on doit défendre le temple. Vite !', '', 28153),
(133672, 'frFR', 'La volonté de ma maîtresse, elle sera faite !', '', 28153),
(133670, 'frFR', 'Je vais vous écraser !', '', 28153),
(133669, 'frFR', 'Allons-y, petit roi. Semons la mort parmi ces hérétiques !', '', 28153),
(133668, 'frFR', 'Mais je jure, à toi et au héraut de la Horde, que je ne m\’arrêterai que quand j\’aurai la tête de Zul.', '', 28153),
(133667, 'frFR', 'La vieillesse, elle m\’a ramolli. Beaucoup de gens m\’ont mis en garde, même ma propre fille, mais je n\’ai pas écouté.', '', 28153),
(133666, 'frFR', 'Le moment est venu de te demander si tu es le roi, ou bien la proie.', '', 28153),
(133665, 'frFR', 'La hache de guerre a été déterrée.', '', 28153),
(133664, 'frFR', 'Ton conseil remet ton autorité en question. Tes amis essaient de prendre ta vie.', '', 28153),
(133663, 'frFR', 'Rastakhan. Tes ennemis mettent à l\’épreuve la solidité de tes frontières.', '', 28153),
(133648, 'frFR', 'Grand Loa, tu es encore en vie ? Je suis venu te libérer de tes chaînes.', '', 28153),
(133646, 'frFR', 'Zul, il avait prédit votre venue. Tout se déroule comme il l\’avait dit.', '', 28153),
(133645, 'frFR', '', 'Imbécile ! Si j\’avais le temps, je vous écraserais pour ce que vous avez fait à Vol\’kaal !', 28153),
(133644, 'frFR', '', 'Meurs, Shadra ! Meurs pour l\’éternité ! À présent ton pouvoir, il m\’appartient !', 28153),
(133643, 'frFR', 'Je pars devant pendant que vous vous occupez de ces totems. Avec un peu de chance, on pourra enfin retrouver ce grand dadais après les avoir détruits.', '', 28153),
(133638, 'frFR', '', 'Vol\’kaal, débarrasse-nous de ces intrus pendant que je m\’occupe de Shadra !', 28153),
(133633, 'frFR', '', 'Shadra ! Ma main, tu l\’as guidée pendant des années. Mais je sers un nouveau maître !', 28153),
(133632, 'frFR', '', 'Vous arrivez trop tard ! Le sang du Loa, il a été versé !', 28153),
(133610, 'frFR', 'Gonk pas content ! Gonk écraser Yazma !', '', 28153),
(133606, 'frFR', 'Vos exploits en ces lieux ne m\’ont pas échappé. Ma bénédiction vous accompagne.', '', 28153),
(133605, 'frFR', 'Merci, $n. Vous avez bien mérité ma bénédiction.', '', 28153),
(133591, 'frFR', '<Un petit message est griffonné sur le flanc de la fusée.>$b$bATTENTION : message officiel.$B$BSi vous n\’avez pas le grade de commandant de la Horde, CESSEZ DE LIRE IMMÉDIATEMENT !$b$bSigné : Rustine, Brigade gob$b$bMon équipe a été envoyée pour déployer une puissance de feu dévastatrice qui nous permettra de poursuivre nos opérations en Nazmir. Nous apportons un canon qui balayera tout ce qui se dresse sur notre route.$B$BNous sommes à bord de « la Libation » et cherchons un point d\’ancrage au large de la côte est. Envoyez un guide pour nous conduire jusqu\’à un point de déploiement.', '', 28153),
(133582, 'frFR', 'Grrrr… Je vais rester pour l\’instant, ne serait-ce que pour aider les esprits de mes disciples compétents qui sont morts par ta faute, imbécile !', '', 28153),
(133581, 'frFR', 'J\’ai commis une erreur, c\’est vrai… mais regardez autour de vous ! Cet endroit ne vous rappelle-t-il pas de bons souvenirs ? Restez, et permettez-nous de rebâtir ce temple en votre honneur !', '', 28153),
(133580, 'frFR', 'Les Tortollans ont d\’étranges coutumes, mon seigneur. Comment aurais-je pu savoir que refuser une demande en mariage passerait pour une déclaration de guerre ?', '', 28153),
(133579, 'frFR', 'Ta tâche était pourtant simple. Faire la paix avec les Tortaka et veiller sur mon temple en mon absence. Regarde un peu le résultat !', '', 28153),
(133578, 'frFR', 'Ahem… C\’est moi, auguste Loa, votre fidèle serviteur et confident, Vunanju.', '', 28153),
(133576, 'frFR', '', 'Nous avons un vieux proverbe ici, en Kul Tiras.$B$BQuand les choses tournent mal, les marins se contentent de faire contre mauvaise fortune bon cœur, car selon eux, « on ne peut pas aller contre les vents ».$B$BJe déteste ce dicton.', 28153),
(133575, 'frFR', '', 'Cirrus veille sur moi depuis ma plus tendre enfance. Il m\’a appris à me battre, à monter à cheval et à naviguer.$B$BQuand j\’ai intégré la garde, j\’étais déjà mieux formée que certains de mes instructeurs.$B$BEt ça ne leur pas plu.', 28153),
(133574, 'frFR', '', 'La défaite de Daelin Portvaillant a tout changé ici.$B$BJaina devait avoir ses raisons... n\’est-ce pas ?', 28153),
(133573, 'frFR', '', 'Toute mon enfance, on m\’a conté la grandeur du noble royaume de Lordaeron.$B$BEt sa chute.$B$BLe Fléau m\’a pris ma mère, mon père et mon foyer avant même que je sois en âge de comprendre.', 28153),
(133572, 'frFR', 'Je suis prêt à prendre ma décision.', 'Je suis prête à prendre ma décision.', 28153),
(133571, 'frFR', 'LA BÊTE EST INCONTRÔLABLE !', '', 28153),
(133570, 'frFR', '', 'Votre décision est prise ? Que comptez-vous faire ?', 28153),
(133569, 'frFR', '', 'Vous avez toute ma gratitude, $n.', 28153),
(133568, 'frFR', 'Si tu te perds encore sur le chemin du retour, ne compte PAS sur moi pour venir te chercher !', '', 28153),
(133567, 'frFR', 'Allons retrouver les autres. J\’ai tant de choses à leur raconter !', '', 28153),
(133566, 'frFR', 'Faites gaffe, ces Trolls sont complètement cinglés. Sinon, pourquoi ils mangeraient les leurs, hein, pourquoi ?', '', 28153),
(133565, 'frFR', 'Hum… c\’est bon ! Ça manque juste un peu d\’assaisonnement. La prochaine fois, peut-être.', '', 28153),
(133564, 'frFR', 'J\’ai si faim… Là tout de suite, je serais prêt à avaler un raptor.', '', 28153),
(133563, 'frFR', 'Préparez-vous, mortels ! Le seigneur des bêtes est enfin de retour parmi nous !', '', 28153),
(133562, 'frFR', 'C\’est la gardelame Kaja qui m\’envoie.', 'C\’est la gardelame Kaja qui m\’envoie.', 28153),
(133561, 'frFR', '', 'Je suis contente de voir que Julwaba est en vie.', 28153),
(133560, 'frFR', '', 'Je vous dois tant, $n.', 28153),
(133559, 'frFR', '', 'Il vaut mieux que vous mettiez la combinaison et que vous alliez au camp. Je ne suis pas sûre de pouvoir me retenir d\’embrocher ceux qui ont posé la main sur Rakera.', 28153),
(133558, 'frFR', 'Nos… trésors…', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(133557, 'frFR', 'Ces trésors appartiennent aux Vilécaille !', '', 28153),
(133556, 'frFR', 'On est de simples fabricants de saucisses ! Qui en aurait après nous ?', '', 28153),
(133555, 'frFR', '', 'Je garderai l\’Humain à l\’œil. S\’il essaie de s\’enfuir, ma lame l\’arrêtera.', 28153),
(133554, 'frFR', 'Je vais me rendre à la plage. Retrouvez-moi là-bas quand vous aurez ce que je vous ai demandé.', '', 28153),
(133553, 'frFR', 'Maintenant que les offrandes sont en place, nous avons tout ce qu\’il faut pour invoquer le Loa.', '', 28153),
(133551, 'frFR', 'Les Zandalari auront besoin d\’un maximum de soutien pour faire face à cette menace. Une chance que la Horde soit là pour voler à leur secours.', '', 28153),
(133548, 'frFR', '', 'Je vais le surveiller, histoire qu\’il ne nous fausse pas compagnie.', 28153),
(133547, 'frFR', '', 'Une déferlante de sang va s\’abattre sur nous. Sommes-nous condamnés, $n ?', 28153),
(133540, 'frFR', 'Allez-y, $n. Soyez mon courroux. Je dois retrouver mon Loa avant qu\’il soit trop tard.', '', 28153),
(133539, 'frFR', '', 'La chair… devait me donner… le pouvoir…', 28153),
(133538, 'frFR', '', 'Impossible… Vous me mangez pas, pas touche à mon pouvoir !', 28153),
(133537, 'frFR', '', 'Hein ? Faut prendre le pouvoir de la chair, qu\’il a dit. Pourquoi vous mourez pas, hein ?!', 28153),
(133536, 'frFR', '', 'Vous sentez la force à plein nez. Votre pouvoir, j\’vais le dévorer !', 28153),
(133534, 'frFR', '', 'Bas les pattes ! Cet artéfact, vous l\’aurez pas !', 28153),
(133532, 'frFR', 'Je sais ! Quel imbécile je fais… J\’ai oublié les offrandes ! On n\’invoque pas un Loa les mains vides !', '', 28153),
(133527, 'frFR', 'Hmm… Quelque chose ne tourne pas rond. L\’idole a retrouvé sa juste place sur l\’autel. Normalement, le Loa devrait revenir…', '', 28153),
(133526, 'frFR', '', 'Ça, c\’est le médaillon de Rakera. Tous les gardes de guerre en reçoivent un pour les services rendus au roi. Au moins, elle n\’y a pas renoncé sans se battre.', 28153),
(133516, 'frFR', 'Zul et ses serviteurs, ils vont bientôt voir qu\’il y a toujours un prix à payer quand on défie un Loa.\n\nLeur dette augmente de jour en jour.', '', 28153),
(133515, 'frFR', '', 'On est là ! Alors, quoi de neuf ?', 28153),
(133514, 'frFR', '', 'Il faut pas s\’arrêter. On doit plus être bien loin.', 28153),
(133505, 'frFR', '', 'Je combattrai à vos côtés, mon roi. La Horde payera pour ses crimes. Je vais bloquer l\’entrée pour que nos troupes puissent se regrouper.', 28153),
(133503, 'frFR', 'Au moins deux, et pas des petites ! Oh, merci de m\’avoir soigné.', '', 28153),
(133502, 'frFR', 'Tu as failli te faire dévorer et… Des lances, dis-tu ? Combien ?', '', 28153),
(133501, 'frFR', 'Mais, Kajosh, tu aurais dû voir ça ! De la magie noire partout, des Trolls qui faisaient de drôles de trucs… On m\’a même planté plusieurs lances dans la panse !', '', 28153),
(133500, 'frFR', 'Abruti ! Je me suis fait un sang d\’encre pour toi !', '', 28153),
(133499, 'frFR', 'C\’est pas passé loin ! Mais je serai bientôt sur pied. On se débarrasse pas de moi comme ça !', '', 28153),
(133498, 'frFR', 'C\’est bon, je suis réveillé ! Pas la peine de vous énerver comme ça !', '', 28153),
(133497, 'frFR', '', 'Bien, vous avez vu ma fusée éclairante ! Où est Drekal ?', 28153),
(133496, 'frFR', 'Argh… Tout va bien, je peux bouger. Je vais retrouver Kajosh… Je parie… qu\’il est… drôlement furax !', '', 28153),
(133495, 'frFR', '', 'Ha… Jal\’aya… C\’est elle… qui a… l\’artéfact…', 28153),
(133494, 'frFR', '', 'Un repas de choix, après le Tortollan !', 28153),
(133492, 'frFR', '', 'Le marché attire des voyageurs de tout Azeroth. Il y a de nombreuses auberges, mais celle-ci est ma préférée !', 28153),
(133490, 'frFR', '', 'Les visions qui me sont apparues… Il faut à tout prix arrêter Zul et Yazma, $n !', 28153),
(133489, 'frFR', 'C\’est Kajosh qui m\’envoie. Les gueules démoniaques, j\’en fais mon affaire.', 'C\’est Kajosh qui m\’envoie. Les gueules démoniaques, j\’en fais mon affaire.', 28153),
(133488, 'frFR', 'Argh… Si vous n\’êtes pas là pour me manger… filez d\’ici, sauvez votre peau !\n\nLes gueules démoniaques vont débarquer… d\’une minute à l\’autre… en quête de « nourriture ».', '', 28153),
(133487, 'frFR', 'Argh… Attention, ils arrivent !', '', 28153),
(133481, 'frFR', 'Shadra, elle n\’est pas dans son état normal. Qu\’est-ce qui a bien pu lui arriver ?', 'Shadra, elle n\’est pas dans son état normal. Qu\’est-ce qui a bien pu lui arriver ?', 28153),
(133480, 'frFR', 'Zul et Yazma, c\’est eux les responsables de cette trahison. Il faut les arrêter !', 'Zul et Yazma, c\’est eux les responsables de cette trahison. Il faut les arrêter !', 28153),
(133479, 'frFR', 'Personne ne mérite de mourir comme ça. Merci de m\’avoir sauvé !', 'Personne ne mérite de mourir comme ça. Merci de m\’avoir sauvée !', 28153),
(133478, 'frFR', 'Le Loa, il va en entendre parler, comptez sur moi !', 'Le Loa, il va en entendre parler, comptez sur moi !', 28153),
(133477, 'frFR', 'À quoi bon remettre à demain un combat qu\’on peut livrer aujourd\’hui même ?', '', 28153),
(133476, 'frFR', 'La magie du sang, c\’est interdit ! Les traîtres, faut les arrêter !', '', 28153),
(133475, 'frFR', 'Je suis… moi ! Maintenant, il est temps d\’accomplir ma vengeance !', '', 28153),
(133474, 'frFR', 'Shadra et ses sbires, ils sont allés trop loin, c\’te fois !', '', 28153),
(133473, 'frFR', 'Splendide ! Mon pouvoir croît ! Déchaînez la puissance du dernier totem.', '', 28153),
(133472, 'frFR', 'Allez chercher Shoak. Moi, je vous attends ici.', '', 28153),
(133471, 'frFR', 'Il est dans ce temple, derrière nous. Tant mieux, ça va nous faciliter la tâche.', '', 28153),
(133470, 'frFR', 'Ha ha ! Il est…', '', 28153),
(133469, 'frFR', 'Zul, il va le payer cher, très cher !', '', 28153),
(133468, 'frFR', 'Ah, je sens ma force revenir ! Vite, libérez la magie d\’un autre totem.', '', 28153),
(133467, 'frFR', 'Que les Loas, ils vous bénissent, $gl\’ami:l\’amie; !', '', 28153),
(133466, 'frFR', 'À vrai dire, Shoak peut se trouver n\’importe où en Nazmir…', '', 28153),
(133465, 'frFR', 'Je suis prêt. Lancez le sort, qu\’on retrouve Shoak.', 'Je suis prête. Lancez le sort, qu\’on retrouve Shoak.', 28153),
(133463, 'frFR', '', 'Je sais ce que tu ressens… Nous irons bientôt faire un tour, je te le promets.', 28153),
(133461, 'frFR', '(Retour)', '(Retour)', 28153),
(133460, 'frFR', 'Je pourrais me contenter de mes rations habituelles, mais je n\’ai encore jamais goûté la viande de raptor. C\’est l\’occasion ou jamais !', '', 28153),
(133459, 'frFR', 'Certains des totems sont détruits. Votre sort va-t-il fonctionner, maintenant ?', 'Certains des totems sont détruits. Votre sort va-t-il fonctionner, maintenant ?', 28153),
(133455, 'frFR', '', 'Eh, salut, ma belle. Tu dois en avoir assez de rester ici toute la journée.', 28153),
(133450, 'frFR', 'Z\’allez mourir maintenant.', 'Z\’allez mourir maintenant.', 28153),
(133449, 'frFR', 'Zul, il a promis la puissance à celui qui lui apportera vot\’ tête.', 'Zul, il a promis la puissance à celui qui lui apportera vot\’ tête.', 28153),
(133448, 'frFR', 'Votre tête, je vais l\’offrir à Zul.', 'Votre tête, je vais l\’offrir à Zul.', 28153),
(133447, 'frFR', 'J\’vais ravager votre esprit.', 'J\’vais ravager votre esprit.', 28153),
(133446, 'frFR', 'On va vous saigner.', 'On va vous saigner.', 28153),
(133445, 'frFR', 'Où qu\’il est, le roi ?', 'Où qu\’il est, le roi ?', 28153),
(133444, 'frFR', 'Votre tête, elle va finir sur une pique !', 'Votre tête, elle va finir sur une pique !', 28153),
(133443, 'frFR', 'Ma vie pour Zul !', 'Ma vie pour Zul !', 28153),
(133438, 'frFR', '<La surface de l\’autel est légèrement concave, et vous remarquez la présence de profondes rainures aux quatre coins.$b$bOn dirait qu\’un objet lourd et imposant y trônait autrefois.$b$bQuoi que cela ait pu être, il a manifestement disparu.>', '', 28153),
(133432, 'frFR', 'Examiner l\’autel.', 'Examiner l\’autel.', 28153),
(133430, 'frFR', '<La pièce semble vide.$b$bL\’autel qui se dresse devant vous est gravé d\’antiques glyphes zandalari et d\’images du Loa Eraka no Kimbul.$b$bOn dirait que quelque chose reposait autrefois sur cet autel. Une statue, peut-être ?>', '', 28153),
(133428, 'frFR', '', 'La salle des dépôts est sous haute surveillance de jour comme de nuit. Vous pouvez laisser vos objets de valeur ici.', 28153),
(133412, 'frFR', 'Les Zanchuli, ils voient tout !', 'Les Zanchuli, ils voient tout !', 28153),
(133411, 'frFR', 'Vous ne pouvez pas m\’échapper !', 'Vous ne pouvez pas m\’échapper !', 28153),
(133410, 'frFR', 'Zul découvrira vos secrets !', 'Zul découvrira vos secrets !', 28153),
(133409, 'frFR', 'Dites adieu à votre vie !', 'Dites adieu à votre vie !', 28153),
(133407, 'frFR', 'Vous me barrerez pas la route !', 'Vous me barrerez pas la route !', 28153),
(133406, 'frFR', 'Zandalar, elle appartient aux Zanchuli maintenant !', 'Zandalar, elle appartient aux Zanchuli maintenant !', 28153),
(133405, 'frFR', 'Pour Zul ! Pour les Zanchuli !', 'Pour Zul ! Pour les Zanchuli !', 28153),
(133404, 'frFR', 'Les Zanchuli, ils prennent ce qu\’ils veulent !', 'Les Zanchuli, ils prennent ce qu\’ils veulent !', 28153),
(133403, 'frFR', 'Votre puissance sera mienne !', 'Votre puissance sera mienne !', 28153),
(133402, 'frFR', 'Vos morts vont me rendre plus fort.', 'Vos morts vont me rendre plus forte.', 28153),
(133401, 'frFR', 'Plus de sang pour Zul !', 'Plus de sang pour Zul !', 28153),
(133392, 'frFR', '', 'Ce bac fait la navette dans toute la rade.', 28153),
(133389, 'frFR', '', 'Une autorisation du bureau du maître du port est nécessaire pour l\’emprunter. Mais ce ne sera pas un souci.', 28153),
(133387, 'frFR', '', 'Ne pensez plus à votre évasion. Ce marché abonde de voyageurs, comme vous ! Venez, je vais vous faire visiter.', 28153),
(133380, 'frFR', '', 'Je vais garder la tête pour mon quatre heures !', 28153),
(133379, 'frFR', '', 'Joli morceau ! J\’en ai pour des jours à tout becqueter !', 28153),
(133374, 'frFR', '', 'Je vais me curer les dents avec vos os !', 28153),
(133372, 'frFR', '', 'Préparez les broches ! La boustifaille arrive !', 28153),
(133371, 'frFR', '', 'À la bouffe ! Le repas est servi !', 28153),
(133370, 'frFR', '', 'Vos jambes, elles ont l\’air tendres à souhait !', 28153),
(133369, 'frFR', '', 'Enfin, on a de quoi becqueter !', 28153),
(133368, 'frFR', '', 'Miam ! Vous me mettez l\’eau à la bouche !', 28153),
(133359, 'frFR', 'Ce crétin de Shoak a le chic pour se paumer. Il a intérêt à avoir de gros ennuis, après tout ce temps perdu à sa recherche.', '', 28153),
(133357, 'frFR', 'Au travail ! Cette azérite ne va pas s\’extraire toute seule !', 'Au travail ! Cette azérite ne va pas s\’extraire toute seule !', 28153),
(133356, 'frFR', 'Je suis prêt à vous accompagner jusqu\’au temple.', 'Je suis prête à vous accompagner jusqu\’au temple.', 28153),
(133355, 'frFR', 'Je n\’aurais jamais dû faire confiance à ces traîtres de Tortaka ! Dire qu\’ils m\’ont tué et emprisonné dans ce bocal pendant un siècle... ou cela en fait-il déjà deux ? Je ne me souviens même plus !', '', 28153),
(133354, 'frFR', '<Un effroyable rugissement de douleur retentit au-dessus de Zeb\’ahari.>', '<Un effroyable rugissement de douleur retentit au-dessus de Zeb\’ahari.>', 28153),
(133351, 'frFR', 'Je vais partir en quête du Loa. Retrouvez-moi à l\’intérieur du temple quand vous en aurez terminé ici.', '', 28153),
(133350, 'frFR', 'Enfin libre… Merci infiniment de m\’avoir fait sortir de cette maudite jarre ! J\’ai beau être un fantôme, je m\’y sentais drôlement à l\’étroit !', '', 28153),
(133349, 'frFR', '', 'Ces murs ne tiendront plus très longtemps. Ne nous attardons pas ici.', 28153),
(133348, 'frFR', '', 'Super boulot ! Revenez m\’voir dès que vous serez d\’attaque. On a une guerre sur le feu.', 28153),
(133346, 'frFR', '', 'Le Dieu du sang… m\’emporte ! C\’est pas… fini… pas encore…', 28153),
(133345, 'frFR', '', 'Tôt ou tard, le Dieu du sang, il aura ce qui lui revient. Vous ne pouvez pas nous arrêter !', 28153),
(133344, 'frFR', '', 'La princesse, il faut lui faire un rapport tout de suite. Ne la faites pas attendre.', 28153),
(133343, 'frFR', 'Lève-toi, et marche.', '', 28153),
(133342, 'frFR', 'Ton heure a pas encore sonné. C\’est loin d\’être fini.', '', 28153),
(133341, 'frFR', 'Lève-toi. Tu dois encore me servir.', '', 28153),
(133340, 'frFR', 'Debout ! On compte sur toi.', '', 28153),
(133339, 'frFR', 'Relève-toi !', '', 28153),
(133338, 'frFR', 'Debout ! Ton roi a besoin de toi.', '', 28153),
(133337, 'frFR', 'Je suis prêt à combattre les Trolls de sang.', 'Je suis prête à combattre les Trolls de sang.', 28153),
(133336, 'frFR', 'Les Trolls de sang rassemblent leurs forces pour nous attaquer une nouvelle fois, mes enfants et moi.$b$bMais cette fois, c\’est moi qui me chargerai de les tuer !$b$bVous êtes $gprêt:prête; ?', '', 28153),
(133325, 'frFR', 'Des attaquants de la Horde se dirigent vers la caserne !', 'Des attaquants de la Horde se dirigent vers la caserne !', 28153),
(133305, 'frFR', '', 'Vous vous sentirez vite chez vous. À présent, allons voir Cirrus !', 28153),
(133304, 'frFR', '', 'Elle est magnifique, n\’est-ce pas ? Cirrus me l\’a offerte quand elle n\’était qu\’un bébé.', 28153),
(133303, 'frFR', 'Je prendrai part à votre croisade contre les envahisseurs trolls de sang, mais je dois d\’abord reprendre des forces. Voulez-vous bien m\’aider ?', '', 28153),
(133302, 'frFR', 'Zentimo m\’a bien servi. Son esprit vivra parmi mes enfants.', '', 28153),
(133300, 'frFR', 'Randall Redmond crache dans le sable.', '', 28153),
(133298, 'frFR', 'À l\’aide ! Débarrassez-moi de ces choses !', '', 28153),
(133297, 'frFR', '', 'Ses blessures étaient trop graves… Je suis désolée.', 28153),
(133295, 'frFR', 'Vunanju ? Grrrrr. J\’aurais dû m\’en douter…', '', 28153),
(133294, 'frFR', 'Qui ose m\’invoquer dans ce temple délabré ?', '', 28153),
(133274, 'frFR', 'Je vais déjà me rendre au lieu du rituel pour le préparer. Retrouvez-moi là-bas quand vous pourrez.', '', 28153),
(133265, 'frFR', 'Préparez-vous à contempler l\’auguste Eraka no Kimbul, Loa des tigres, seigneur des bêtes, roi des félins et malédiction des proies !', '', 28153),
(133264, 'frFR', 'Vous avez trouvé l\’idole ! Maintenant qu\’elle est en place, nous allons pouvoir invoquer le Loa…', '', 28153),
(133263, 'frFR', '', 'Ce type, j\’vais le ramener à son Loa et tuer tous ceux qui passent.', 28153),
(133261, 'frFR', 'La caserne a été détruite ! Reconstruisez-la !', 'La caserne a été détruite ! Reconstruisez-la !', 28153),
(133260, 'frFR', 'La forge a été détruite ! Reconstruisez-la !', 'La forge a été détruite ! Reconstruisez-la !', 28153),
(133259, 'frFR', 'Les écuries ont été détruites ! Reconstruisez-les !', 'Les écuries ont été détruites ! Reconstruisez-les !', 28153),
(133258, 'frFR', 'L\’atelier a été détruit ! Reconstruisez-le !', 'L\’atelier a été détruit ! Reconstruisez-le !', 28153),
(133254, 'frFR', 'Je n\’ai même pas d\’arme !', '', 28153),
(133253, 'frFR', 'Je ne veux pas mourir !', '', 28153),
(133252, 'frFR', 'Je ne peux pas travailler dans ces conditions !', '', 28153),
(133251, 'frFR', 'Ça fonctionne ! Tenez-vous $gprêt:prête; !', '', 28153),
(133250, 'frFR', 'Nous allons essayer un sort de fossilisation inversée. Reculez !', '', 28153),
(133249, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(133248, 'frFR', 'Si cela fonctionne, ne vous attendez pas à ce que Xibala se laisse faire docilement.\n\nJ\’espère que vous êtes $gprêt:prête; à faire le nécessaire pour le soumettre.', '', 28153),
(133247, 'frFR', '', 'Par ici ! Il y a un blessé !', 28153),
(133240, 'frFR', '', 'Je vous offre cet abri de fortune en ces terres hostiles.', 28153),
(133239, 'frFR', 'J\’étais ici chez moi avant que les Zandalari décident de construire tout autour de moi.', '', 28153),
(133224, 'frFR', 'L\’idole doit être restituée au temple de Kimbul. Vous tenez entre vos mains la clé du retour de notre Loa !', '', 28153),
(133223, 'frFR', 'Mon esprit s\’affaiblit et il ne me reste que peu de temps. Écoutez-moi attentivement…', '', 28153),
(133214, 'frFR', 'Maintenant, partons d\’ici. Un peu plus loin, y a un sanctuaire appelé Zo\’bal. Retrouvez-moi là-bas.', '', 28153),
(133213, 'frFR', 'Le commandant de la Horde a été vaincu. Vous avez gagné !', 'Le commandant de la Horde a été vaincu. Vous avez gagné !', 28153),
(133212, 'frFR', 'Ah, en v\’là une aubaine ! On dirait que ces sales Orcs nous ont laissé quelques explosifs en cadeau. Je me demande ce qui se passerait si on les larguait près de leurs vilains bâtiments, là-bas…', '', 28153),
(133207, 'frFR', 'Ce secteur, ça fait un bail qu\’on l\’a abandonné aux esprits des temps passés, et c\’est pas un hasard.\n\nLa Horde, elle est libre de fouiner dans l\’coin si elle ose, c\’est pas notre problème...', '', 28153),
(133204, 'frFR', 'Même dans la mort, nos âmes sont restées fidèles au grand Loa Eraka no Kimbul. Les liens de notre foi sont éternels et plus forts que l\’étreinte de la mort elle-même.', '', 28153),
(133201, 'frFR', 'Il nous faut cette mine, mais ces maudits Orcs se dressent sur notre chemin. Éliminons-les, et les travailleurs pourront entamer la construction de notre caserne.', '', 28153),
(133200, 'frFR', 'Et une gueule cassée de moins, une ! À présent, débarrassons-nous de cette bannière et mettons-nous au travail.', '', 28153),
(133199, 'frFR', 'Les gars, il faut qu\’on aménage une base ici si on veut éliminer ce commandant orc et détruire son camp une bonne fois pour toutes.', '', 28153),
(133198, 'frFR', '', 'Ça change… rien du tout ! Bientôt… vous allez tous… mourir…', 28153),
(133197, 'frFR', 'Vous êtes le premier être mortel à pénétrer dans mon temple depuis de longues années. Comme il est bon de retrouver des disciples parmi les vivants.', '', 28153),
(133158, 'frFR', '', 'On a réussi. Imaginez ce qui arrivera quand cet assemblage géant bousillera les murs de Zuldazar les laissera tout le monde entrer. L\’aide de quelques Loas de plus, ça sera pas de trop.', 28153),
(133157, 'frFR', '', 'Visez-moi ça ! Ils font tous route vers Zuldazar… Attention ! Vous faites pas remarquer !', 28153),
(133156, 'frFR', '', 'L\’île est au sud. J\’vous y attendrai.', 28153),
(133155, 'frFR', '', 'Par ici. Le bateau, il attend plus que vous. Espérons ne pas croiser de monstres, pas vrai ?', 28153),
(133154, 'frFR', 'C\’EST PARTI !', '', 28153),
(133153, 'frFR', 'ÉVITEZ JUSTE DE LE FAIRE EXPLOSER !', '', 28153),
(133152, 'frFR', 'CONTINUEZ À FRAPPER !', '', 28153),
(133151, 'frFR', 'Qu\’est-ce que je peux faire pour vous, $gmon grand:ma grande; ?', '', 28153),
(133150, 'frFR', 'Je vais vous dire, prenez tout ce que vous trouverez là-dedans. Vous l\’avez bien mérité !', '', 28153),
(133149, 'frFR', 'AAAAAa….aahhhh….', '', 28153),
(133143, 'frFR', 'Votre présence en ces lieux est un sacrilège ! Prenez garde à Xibala !', '', 28153),
(133141, 'frFR', 'Il est désormais possible de recruter des grenadiers nains à l\’atelier.', 'Il est désormais possible de recruter des grenadiers nains à l\’atelier.', 28153),
(133140, 'frFR', 'Il est désormais possible de recruter des fusiliers à la forge.', 'Il est désormais possible de recruter des fusiliers à la forge.', 28153),
(133139, 'frFR', 'Il est désormais possible de recruter des cavaliers aux écuries.', 'Il est désormais possible de recruter des cavaliers aux écuries.', 28153),
(133138, 'frFR', 'Il est désormais possible de recruter des fantassins à la caserne.', 'Il est désormais possible de recruter des fantassins à la caserne.', 28153),
(133136, 'frFR', '', 'Vous vous rapprochez. La première présence que j\’ai ressentie était proche de l\’eau.', 28153),
(133133, 'frFR', '', 'Hmm… Cette offrande est encore fraîche. On dirait que Bwonsamdi a un fidèle, ici dans le marais.', 28153),
(133131, 'frFR', 'Les Trolls de sang sont trop nombreux. J\’abandonne le combat.', '', 28153),
(133126, 'frFR', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire une forge.', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire une forge.', 28153),
(133125, 'frFR', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire un atelier.', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire un atelier.', 28153),
(133124, 'frFR', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire des écuries.', 'La Horde a perdu un bâtiment. Vous pouvez désormais construire des écuries.', 28153),
(133123, 'frFR', '', 'Là, suivez le fantôme. Découvrons où l\’adorateur de Bwonsamdi s\’est rendu.', 28153),
(133122, 'frFR', '', 'Une Trollesse de sang. On dirait qu\’elle a été sacrifiée. Ah, le tueur a laissé une dague. Un simple sort devrait faire l\’affaire…', 28153),
(133114, 'frFR', 'SORTEZ-MOI DE LÀ !', '', 28153),
(133113, 'frFR', 'La bombe a été lâchée !', 'La bombe a été lâchée !', 28153),
(133112, 'frFR', 'La bombe a été ramassée !', 'La bombe a été ramassée !', 28153),
(133111, 'frFR', 'Ça va exploser ! Aux abris !', 'Ça va exploser ! Aux abris !', 28153),
(133108, 'frFR', 'Fantassin [25 pièces d\’or de front de guerre] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 'Fantassin [25 pièces d\’or de front de guerre] |TINTERFACE\\ICONS\\INV_MISC_COIN_17.BLP:15|t', 28153),
(133104, 'frFR', 'Commençons.', 'Commençons.', 28153),
(133103, 'frFR', '', '', 28153),
(133102, 'frFR', 'Le travail de sape de l\’Alliance nous ralentit !', 'Le travail de sape de l\’Alliance nous ralentit !', 28153),
(133101, 'frFR', 'Je serais bien plus efficace si je ne devais pas constamment craindre les saboteurs de l\’Alliance.', 'Je serais bien plus efficace si je ne devais pas constamment craindre les saboteurs de l\’Alliance.', 28153),
(133100, 'frFR', 'L\’Alliance n\’a rien à faire sur ces terres. Zuldazar appartient à la Horde !', 'L\’Alliance n\’a rien à faire sur ces terres. Zuldazar appartient à la Horde !', 28153),
(133099, 'frFR', 'On n\’arrivera à rien ici tant que ces fichus Nains n\’auront pas débarrassé le plancher !', '', 28153),
(133085, 'frFR', '', 'L\’Alliance… vaincra…', 28153),
(133084, 'frFR', '', 'C\’est un site de fouilles officiel de la Ligue des explorateurs. Vous n\’avez pas le droit d\’être ici !', 28153),
(133069, 'frFR', 'Pour l\’Alliance !', 'Pour l\’Alliance !', 28153),
(133066, 'frFR', 'Disparaissez !', 'Disparaissez !', 28153),
(133065, 'frFR', 'Personne ne nous prendra ces reliques !', 'Personne ne nous prendra ces reliques !', 28153),
(133064, 'frFR', 'Mort au Reliquaire !', 'Mort au Reliquaire !', 28153),
(133055, 'frFR', '', 'Salut ! Vous avez déjà allumé une fusée accrochée à votre dos, et tout ça les yeux bandés ? Moi, oui !', 28153),
(133054, 'frFR', 'L\’Alliance doit être éradiquée. Zuldazar appartient à la Horde !', '', 28153),
(133053, 'frFR', 'C\’était incroyable. Une découverte sans précédent !', '', 28153),
(133048, 'frFR', '', 'J\’ai passé beaucoup de temps ici à écouter les histoires des voyageurs. Surtout ceux des royaumes de l\’Est !', 28153),
(133047, 'frFR', '', 'Nous y voilà : le port de Boralus. Il s\’agit de l\’endroit le mieux gardé de la ville, après le donjon Portvaillant. Et c\’est aussi le seul endroit auquel la plupart des visiteurs ont accès.', 28153),
(133045, 'frFR', '', 'Estime-toi heureux qu\’il te paye. Maintenant rame !', 28153),
(133044, 'frFR', 'Émissaire de l\’Alliance ? Cirrus ne l\’avait pas dit, ça… Je lui aurais fait payer le double !', '', 28153),
(133043, 'frFR', '', 'Vous étiez avec Jaina Portvaillant ! Vous êtes l\’émissaire de l\’Alliance !', 28153),
(133042, 'frFR', '', 'Attendez… Je vous connais, vous…', 28153),
(133041, 'frFR', 'Oh, et j\’ai secouru la cible, bien entendu ! Camarade de cellule, Taelia. Taelia, camarade de cellule.', '', 28153),
(133040, 'frFR', '', 'Que s\’est-il passé là-dedans ? Tu as provoqué une émeute ?', 28153),
(133039, 'frFR', 'Je ne vois pas de quoi tu parles… Mais j\’ai des infos compromettantes sur Corsandre.', '', 28153),
(133038, 'frFR', 'Pile à l\’heure, comme toujours.', '', 28153),
(133037, 'frFR', 'Descendons dans les niveaux inférieurs et tâchons de trouver une sortie.', '', 28153),
(133036, 'frFR', 'Aaah, je préfère ça. Je me sentais tout nu sans elles ! Allons-y.', '', 28153),
(133013, 'frFR', '', 'Que vous cherchiez un nouveau tapis ou un nouveau manteau, on a la fourrure qu\’il vous faut !', 28153),
(133012, 'frFR', '', 'Elles sont chaudes, mes fourrures ! Chaudes, pratiques et confortables, avec ça !', 28153),
(133011, 'frFR', '', 'Fourrures de premier choix en provenance des quatre coins de Kul Tiras !', 28153),
(133009, 'frFR', '', 'Les inventions les plus fiables de Tiragarde, et c\’est pas du flanc !', 28153),
(133008, 'frFR', '', 'Les authentiques inventions gnomes sont ici, et nulle part ailleurs ! Méfiez-vous des imitations !', 28153),
(133007, 'frFR', '', 'Nos bibelots, c\’est du premier choix ! Vous ne trouverez pas mieux ailleurs !', 28153),
(133001, 'frFR', 'Ça alors ! C\’est... c\’est moi ou il grandit ? Hiiii !', 'Ça alors ! C\’est... c\’est moi ou il grandit ? Hiiii !', 28153),
(132999, 'frFR', 'Réanimation', 'Réanimation', 28153),
(132994, 'frFR', 'Mages, regagnons le camp. Le savoir nous appelle !', '', 28153),
(132993, 'frFR', 'Bon sang ! On dirait que les clés sont foutues. Ça, c\’était de l\’explosion !', '', 28153),
(132992, 'frFR', 'Prenez votre équipement et allons rendre visite au gardien de ce quartier. On aura besoin de ses clés.', '', 28153),
(132991, 'frFR', 'C\’est pas par ici qu\’on va pouvoir s\’échapper. Essayons de l\’autre côté.', '', 28153),
(132990, 'frFR', 'Caserne disponible', 'Caserne disponible', 28153),
(132989, 'frFR', 'C\’est l\’heure de la mutinerie, les gars !', '', 28153),
(132988, 'frFR', '[La porte de la cellule s\’ouvre. Les détenus se ruent à l\’extérieur avant de foncer dans le couloir.]', '[La porte de la cellule s\’ouvre. Les détenus se ruent à l\’extérieur avant de foncer dans le couloir.]', 28153),
(132987, 'frFR', 'Des attaquants de la Horde se dirigent vers l\’atelier !', 'Des attaquants de la Horde se dirigent vers l\’atelier !', 28153),
(132986, 'frFR', 'Apparition de fantassins', 'Apparition de fantassins', 28153),
(132985, 'frFR', 'La caserne est en cours de reconstruction après capture.', 'La caserne est en cours de reconstruction après capture.', 28153),
(132981, 'frFR', 'Des attaquants de la Horde se dirigent vers les écuries !', 'Des attaquants de la Horde se dirigent vers les écuries !', 28153),
(132980, 'frFR', 'Des attaquants de la Horde se dirigent vers la forge !', 'Des attaquants de la Horde se dirigent vers la forge !', 28153),
(132969, 'frFR', '', 'Maman, tous mes amis s\’amusent sans moi ! Je peux y aller aussi, dis ?', 28153),
(132968, 'frFR', '', 'Je m\’ennuie ! Je peux aller jouer ?', 28153),
(132967, 'frFR', '', 'On a bientôt fini les courses ?', 28153),
(132966, 'frFR', 'Voilà qui devrait suffire à le remettre sur pied.', '', 28153),
(132957, 'frFR', '', 'Ce vieux machin ?$B$B<Elle s\’esclaffe.>$B$BRegardez autour de vous. Où est-ce que je l\’ai trouvé, à votre avis ?', 28153),
(132955, 'frFR', 'Intéressant, votre bouclier. Où l\’avez-vous trouvé ?', 'Intéressant, votre bouclier. Où l\’avez-vous trouvé ?', 28153),
(132954, 'frFR', '', 'J\’ai beau être petite, j\’ai plus de force dans le bras que la plupart des mauviettes de la Horde que vous croiserez dans l\’coin.', 28153),
(132945, 'frFR', 'Que faites-vous ici ?', 'Que faites-vous ici ?', 28153),
(132944, 'frFR', 'J\’ai précisément ce qu\’il faut pour m\’occuper de lui. Tu vas déguster, mon grand !', '', 28153),
(132943, 'frFR', 'Géant en approche ! Hé, mais c\’est le lascar qui a ratiboisé notre bateau ! On va lui rendre la monnaie de sa pièce !', '', 28153),
(132941, 'frFR', 'Écoutez, $gmon grand:ma grande;... Je... euh, j\’ai oublié ce que j\’allais dire... Enfin bref, n\’allez pas mettre vos sales pattes n\’importe où.$B$BJe tiens pas à ce que vous mettiez du sang partout sur mon équipement.', '', 28153),
(132940, 'frFR', 'Tout est une question de taille. Chez moi, les émotions mettent plus de temps à arriver à la tête.$B$BPrenez votre mal en patience.', '', 28153),
(132939, 'frFR', 'Il faut qu\’on calibre la mire du canon avant de pouvoir viser quoi que ce soit. Pourquoi ne pas aligner quelques Nagas pour se faire la main ?', '', 28153),
(132938, 'frFR', 'Houla ! Attention ! Ils nous tirent dessus ! Dégommez-les avec des obus à fragmentation !', '', 28153),
(132935, 'frFR', 'En dessous ! Attention !', '', 28153),
(132932, 'frFR', '', 'On dirait, oui… Dirigeons-nous vers l\’ouest et évitons le conflit.', 28153),
(132931, 'frFR', 'Leur nombre semble avoir augmenté.', '', 28153),
(132928, 'frFR', 'Êtes-vous ici en quête d\’un refuge ou pour les affaires ?', 'Êtes-vous ici en quête d\’un refuge ou pour les affaires ?', 28153),
(132926, 'frFR', 'On est opérationnels et prêts à partir. Montez et posez votre derrière.', '', 28153),
(132924, 'frFR', 'Vite ! Actionnez ce levier !', '', 28153),
(132923, 'frFR', 'Venez, un bateau devrait nous attendre sur la plage.', '', 28153),
(132922, 'frFR', '', 'Prem\’s ! Cet or ne peut être qu\’à moi !', 28153),
(132920, 'frFR', 'Cinquante mille pièces d\’or au premier qui nous amène au point de déploiement !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132918, 'frFR', 'Mais je viens de bricoler des mines pour sécuriser la zone.', '', 28153),
(132917, 'frFR', 'J\’en ai officiellement fini avec ce trou à rats.', '', 28153),
(132916, 'frFR', 'Beurk… Ça renarde comme un hamac de flibustier galeux.', '', 28153),
(132915, 'frFR', 'Allez, ma brigade, on dégage d\’ici !', '', 28153),
(132912, 'frFR', 'Y a pas de frisson sans le risque de perdre ! Sérieux, tu devrais jouer plus souvent.', '', 28153),
(132911, 'frFR', '', 'Allez, c\’est pas rien quatre-vingt pour cent. Pourquoi vouloir tenter le diable ?', 28153),
(132910, 'frFR', 'Seulement quatre-vingts pour cent ? Tu pourrais demander vachement plus ! Où est ta cupidité ?', '', 28153),
(132909, 'frFR', 'Content de vous revoir à la Défense d\’or, frangine. Vous êtes ici en famille.\n\nPosez-vous et buvons un coup !', '', 28153),
(132908, 'frFR', 'Content de vous revoir à la Défense d\’or, frangin. Vous êtes ici en famille.\n\nPosez-vous et buvons un coup !', '', 28153),
(132907, 'frFR', 'Qu\’est-ce que vous fabriquez ? C\’est mon équipement, ça !', 'Qu\’est-ce que vous fabriquez ? C\’est mon équipement, ça !', 28153),
(132906, 'frFR', 'À l\’aide ! Quelqu\’un cherche à saboter nos efforts !', 'À l\’aide ! Quelqu\’un cherche à saboter nos efforts !', 28153),
(132905, 'frFR', 'Cet équipement est fragile !', 'Cet équipement est fragile !', 28153),
(132904, 'frFR', 'Hé ! Éloignez-vous de mon matériel !', 'Hé ! Éloignez-vous de mon matériel !', 28153),
(132897, 'frFR', 'Laissez-moi sortir de cette cage ! Je suis innocent, je le jure !', 'Laissez-moi sortir de cette cage ! Je suis innocente, je le jure !', 28153),
(132893, 'frFR', 'Je suis bien d\’accord, Grenja. $p fera l\’affaire si Zulsan revient pas.', '', 28153),
(132891, 'frFR', 'Qui a eu la brillante idée de voguer près de cette grotte de malheur, hein, qui ?', 'Qui a eu la brillante idée de voguer près de cette grotte de malheur, hein, qui ?', 28153),
(132890, 'frFR', 'Le chant a enfin cessé !', 'Le chant a enfin cessé !', 28153),
(132889, 'frFR', 'C\’est... c\’est de la bière ?', 'C\’est… c\’est de la bière ?', 28153),
(132880, 'frFR', 'Ha, je m\’en lasserai jamais.', '', 28153),
(132879, 'frFR', 'J\’ai fait bouillir le sang et les dards et je les ai mélangés dans le gobelet cérémoniel de la Défense d\’or… Ouais, c\’est un ananas. Le mangez pas. On n\’en a qu\’un.', '', 28153),
(132877, 'frFR', 'Merci de m\’avoir sauvé !', '', 28153),
(132876, 'frFR', 'Merci ! On se retrouve au point de rendez-vous !', '', 28153),
(132849, 'frFR', 'Je comprends à présent que j\’étais sur le point de tomber dans un piège maléfique... Merci !', 'Je comprends à présent que j\’étais sur le point de tomber dans un piège maléfique... Merci !', 28153),
(132848, 'frFR', 'Je ne sais pas ce qui m\’a pris...', 'Je ne sais pas ce qui m\’a prise...', 28153),
(132847, 'frFR', 'Je vous en prie, sauvez les autres… moi, je vais rejoindre Kimbul.', 'Je vous en prie, sauvez les autres… moi, je vais rejoindre Kimbul.', 28153),
(132846, 'frFR', 'J\’étais à deux doigts d\’y rester... Je vous remercie, $gétranger:étrangère;.', 'J\’étais à deux doigts d\’y rester... Je vous remercie, $gétranger:étrangère;.', 28153),
(132845, 'frFR', 'Cette illusion a failli me coûter mon âme...', 'Cette illusion a failli me coûter mon âme...', 28153),
(132844, 'frFR', 'Je réalise à présent que ce n\’était qu\’un enchantement. Je vais aller trouver Kimbul...', 'Je réalise à présent que ce n\’était qu\’un enchantement. Je vais aller trouver Kimbul...', 28153),
(132843, 'frFR', 'J\’ai été séduit par la lumière dévorante. Merci pour votre intervention…', 'J\’ai été séduite par la lumière dévorante. Merci pour votre intervention…', 28153),
(132841, 'frFR', '', 'Je ne tiendrai plus très longtemps sans boire ni manger. Après avoir tourné en rond toute la journée, j\’ai décidé que ma seule solution était de suivre le conseil du dément et de marcher vers le sud et la promesse d\’un refuge.', 28153),
(132840, 'frFR', '', 'Des assassins à la solde de Jakra\’zet ont attaqué notre camp en plein milieu de la nuit. Désarmés et encore ensommeillés, nous n\’avons pas pu nous défendre. J\’ai repoussé les traîtres, mais le mal était fait : les survivants s\’étaient dispersés, chacun condamné à arpenter seul ce milieu impitoyable.', 28153),
(132839, 'frFR', '', 'Le soleil s\’est couché derrière les dunes, nous offrant un répit face à la chaleur qui en a plongé plus d\’un dans le délire. Lors d\’une transe provoquée par le soleil, l\’un de nous s\’est mis à délirer à propos d\’un temple accueillant les exilés, au sud. Je doute qu\’il passe la nuit.', 28153),
(132838, 'frFR', '', 'J\’écris ceci assise dans une cage avec une dizaine d\’exilés, en route vers les sables où nous finirons nos jours, aussi peu nombreux soient-ils. L\’air chaud et lourd me dit que nous approchons de notre destination.', 28153),
(132830, 'frFR', '', 'Vous arrivez trop tard… les Loas… ils nourriront tous… le Dieu du sang.', 28153),
(132827, 'frFR', 'Ces saletés de Nagas vont me le payer cher !', '', 28153),
(132826, 'frFR', 'Je ne vous remercierai jamais assez !', '', 28153),
(132825, 'frFR', 'J\’ai une dette envers vous !', '', 28153),
(132824, 'frFR', 'Liberté !', '', 28153),
(132823, 'frFR', 'Je vous dois la vie. Ces hommes-serpents paieront pour ce qu\’ils ont fait à notre foyer…', 'Je vous dois la vie. Ces hommes-serpents paieront pour ce qu\’ils ont fait à notre foyer…', 28153),
(132821, 'frFR', '<Prendre la lettre.>', '<Prendre la lettre.>', 28153),
(132752, 'frFR', 'Nisha, loués soient les sables, tu es vivante !', '', 28153),
(132737, 'frFR', '', 'C\’est vraiment l\’homme le plus bienveillant que j\’aie connu.', 28153),
(132736, 'frFR', '%s s\’avance vers vous comme pour vous arrêter, puis se ravise. Son regard fixe à nouveau l\’horizon.', '', 28153),
(132735, 'frFR', 'Hé, c\’est jamais évident la première fois de boire le sang de scorpide. C\’est normal. Ça passera mieux la prochaine fois.', '', 28153),
(132734, 'frFR', 'Zuldazar nous a trahis et exilés comme des étrangers. Mais on s\’est jamais trahis. La Défense d\’or, elle reste unie !', '', 28153),
(132733, 'frFR', 'Ah, le sang a une telle saveur… Buvez et partagez ma vision, $p.', '', 28153),
(132714, 'frFR', 'Armes professionnelles pour chasseurs de tous poils !', '', 28153),
(132713, 'frFR', 'Vous allez chasser ? Il n\’y a pas de meilleur endroit pour vous équiper !', '', 28153),
(132712, 'frFR', 'Armes à feu, munitions et explosifs pour chasseurs de tous niveaux !', '', 28153),
(132711, 'frFR', 'À moitié endormi, le navrecorne juvénile bâille de fatigue.', '', 28153),
(132710, 'frFR', 'Oh, ça ? Juste un petit fortifiant que j\’administre généralement à mes gardes du corps. J\’en ai à revendre, si vous êtes prête à me faire une offre !', '', 28153),
(132696, 'frFR', 'Ça y est, je peux sortir ?', '', 28153),
(132692, 'frFR', 'Ha ! Ouais, je sais que notre visiteur peut pas te voir et doit penser que je suis fou. Ha ha !', '', 28153),
(132691, 'frFR', 'T\’en fais pas. notre visiteur peut pas te voir et doit penser que je suis fou. Ha ha !', '', 28153),
(132690, 'frFR', 'Tu as la vie sauve, Zulsan ! Je suis tellement heureux !', '', 28153),
(132688, 'frFR', 'Hé, $n ! Le prince marchand a hâte de commencer à faire des bénefs. Faites-moi signe si vous entendez parler d\’une bonne affaire, d\’accord ?', '', 28153),
(132684, 'frFR', '', 'Voilà la mariée, voilà la mariée !', 28153),
(132683, 'frFR', 'Par ici !', 'Par ici !', 28153),
(132682, 'frFR', 'Chaaaaargez ! On va y arriver !', 'Chaaaaargez ! On va y arriver !', 28153),
(132681, 'frFR', '<Murmurer que vous trouvez son couvre-œil ridicule.>', '<Murmurer que vous trouvez son couvre-œil ridicule.>', 28153),
(132680, 'frFR', 'Je peux récupérer votre matos ?', 'Je peux récupérer votre matos ?', 28153),
(132679, 'frFR', 'Votre couvre-œil est vraiment effrayant.', 'Votre couvre-œil est vraiment effrayant.', 28153),
(132678, 'frFR', '<Le couvre-œil de Man\’zul est agité de tremblements magiques.>', '', 28153),
(132677, 'frFR', '<Tenter de jouer à qui baissera les yeux en premier avec Grenja.>', '<Tenter de jouer à qui baissera les yeux en premier avec Grenja.>', 28153),
(132676, 'frFR', 'Vous feriez une butée de porte parfaite, vous savez.', 'Vous feriez une butée de porte parfaite, vous savez.', 28153),
(132675, 'frFR', 'Bien le bonjour !', 'Bien le bonjour !', 28153),
(132674, 'frFR', '<Grenja semble étonnamment joyeuse pour un crâne.>', '', 28153),
(132673, 'frFR', 'Taisez-vous tous ! On a de la visite.', '', 28153),
(132672, 'frFR', '<Vous présenter poliment.>', '<Vous présenter poliment.>', 28153),
(132671, 'frFR', '<Marmonner que tout ça vous paraît dingue.>', '<Marmonner que tout ça vous paraît dingue.>', 28153),
(132670, 'frFR', 'Sympa, votre chapeau.', 'Sympa, votre chapeau.', 28153),
(132669, 'frFR', 'Euh... Bonjour ?', 'Euh... Bonjour ?', 28153),
(132668, 'frFR', 'Waouh ! Que s\’est-il passé ? Je me sens en pleine forme.', '', 28153),
(132667, 'frFR', '', '<Volni a l\’air d\’être constamment en train de hurler.>', 28153),
(132663, 'frFR', '', 'Nos épices transformeraient la pire ragougnasse en civet quatre étoiles !', 28153),
(132662, 'frFR', '', 'Épices premier choix venues des quatre coins d\’Azeroth !', 28153),
(132661, 'frFR', '', 'Mettez un peu de piment dans votre vie avec nos fabuleuses épices !', 28153),
(132657, 'frFR', 'Aaaaah ! Essayez de le distraire avec un jouet !', 'Aaaaah ! Essayez de le distraire avec un jouet !', 28153),
(132656, 'frFR', 'Le meilleur poisson du marché, et j\’vous raconte pas des carpes !', 'Le meilleur poisson du marché, et j\’vous raconte pas des carpes !', 28153),
(132655, 'frFR', 'Rien de tel qu\’un poisson tout frais pêché pour le dîner !', 'Rien de tel qu\’un poisson tout frais pêché pour le dîner !', 28153),
(132654, 'frFR', 'Poisson, poisson frais des navires roharts !', 'Poisson, poisson frais des navires roharts !', 28153),
(132653, 'frFR', 'Des troupes semblent se rassembler dans les camps de la Horde, au sud-ouest. Tout porte à croire qu\’ils préparent une offensive.', '', 28153),
(132651, 'frFR', 'Ne les perdez pas de vue ! Vous savez ce que vous avez à faire s\’ils font mouvement.', '', 28153),
(132650, 'frFR', 'Flintwood ! Des nouvelles ?', '', 28153),
(132648, 'frFR', 'Sauvetage', 'Sauvetage', 28153),
(132646, 'frFR', 'Feu !', 'Feu !', 28153),
(132645, 'frFR', 'Vous faites partie de cette Horde dont tout le monde cause, c\’est ça ? Et vous vous êtes trouvé un jeune navrecorne ? La dresseuse de bêtes, elle sera curieuse de voir ça. Allez-y, passez.', 'Vous faites partie de cette Horde dont tout le monde cause, c\’est ça ? Et vous vous êtes trouvé un jeune navrecorne ? La dresseuse de bêtes, elle sera curieuse de voir ça. Allez-y, passez.', 28153),
(132636, 'frFR', '', 'Très intéressant…', 28153),
(132635, 'frFR', '', 'Voyons de quoi il s\’agit.', 28153),
(132634, 'frFR', '', 'Faites attention à vous.', 28153),
(132629, 'frFR', 'Utilisez Sprint pour courir plus vite !', 'Utilisez Sprint pour courir plus vite !', 28153),
(132628, 'frFR', '', 'On va tuer les chasseurs, et tes totems perdus, on va les récupérer.', 28153),
(132626, 'frFR', '', 'Quand les Zandalari vous verront combattre à leurs côtés, z\’aurez de nouveau des fidèles.', 28153),
(132624, 'frFR', '', 'Tu es un puissant Loa ! Avec ton soutien, on broierait notre ennemi !', 28153),
(132622, 'frFR', '', 'Grand Krag\’wa ! On vient te demander ton aide contre les Trolls de sang !', 28153),
(132620, 'frFR', 'Je t\’ai eu ! Maintenant, c\’est toi !', '', 28153),
(132619, 'frFR', 'Touché ! C\’est toi le chat !', '', 28153),
(132613, 'frFR', 'Je vous accorde une petite fraction de mon pouvoir. Utilisez-la pour aider Zentimo à rejoindre mes enfants.', '', 28153),
(132611, 'frFR', '', '', 28153),
(132609, 'frFR', 'L\’attaque s\’est passée si vite… On… On n\’a pas pu les arrêter.', 'L\’attaque s\’est passée si vite… On… On n\’a pas pu les arrêter.', 28153),
(132608, 'frFR', 'Le géant… il nous a anéantis…', 'Le géant… il nous a anéantis…', 28153),
(132607, 'frFR', 'L\’arme… détruite…', 'L\’arme… détruite…', 28153),
(132606, 'frFR', 'Les… les Nagas… Ils sont partout !', 'Les… les Nagas… Ils sont partout !', 28153),
(132605, 'frFR', 'M… merci !', 'M… merci !', 28153),
(132604, 'frFR', 'Voici donc le mot de la fin.', 'Voici donc le mot de la fin.', 28153),
(132603, 'frFR', 'Lâche !', 'Lâche !', 28153),
(132602, 'frFR', 'Vous ne m\’aurez jamais vivant !', 'Vous ne m\’aurez jamais vivante !', 28153),
(132601, 'frFR', 'Ordure sans honneur !', 'Ordure sans honneur !', 28153),
(132600, 'frFR', 'Misérable pourriture !', 'Misérable pourriture !', 28153),
(132599, 'frFR', 'Y faut du courage pour se pointer ici à la grande chasse. Je crois que cette journée, elle va être intéressante.', '', 28153),
(132581, 'frFR', 'C\’en est assez de ces insectes. Frappons leur chef !', '', 28153),
(132580, 'frFR', 'J\’en ai assez de ces attaques ! Brisez-les ! Je suis Krag\’wa et personne ne me gobe !', '', 28153),
(132579, 'frFR', 'Beau travail, $n. Vous avez amplement prouvé votre force et votre courage. Retournez au temple pour obtenir votre récompense.', '', 28153),
(132573, 'frFR', 'Quatre caravanes ont été dévorées à la dernière razzia des ranishu. Merci d\’avoir empêché que ça se reproduise.', '', 28153),
(132572, 'frFR', 'Un troupeau de brutosaures s\’est égaré en Vol\’dun et a déclenché une faim incontrôlable chez les ranishu ! Régulez leur population, ou la meute dévorera tout sur son passage.', '', 28153),
(132571, 'frFR', 'Prouvez votre valeur en revenant avec les offrandes et le Loa vous accordera une audience.', '', 28153),
(132566, 'frFR', 'Vous avez servi ce temple et prouvé votre valeur, $n. En retour, je vais vous accorder ma bénédiction, pour peu que vous soyez $gdisposé:disposée; à l\’accepter.', '', 28153),
(132565, 'frFR', 'Il vous faut trouver la tanière du mandecroc et tuer cette créature toutes affaires cessantes. La sécurité du temple en dépend.', '', 28153),
(132564, 'frFR', 'Si les Sephraks ne sont pas chassés du canyon, c\’est le temple qui sera menacé.', '', 28153),
(132563, 'frFR', 'J\’accepte vos offrandes. Approchez, je vous prie, ma vue n\’est plus ce qu\’elle était.', '', 28153),
(132562, 'frFR', 'Nous avons de la visite, Jal\’Nanji. Si vous voulez bien vous en occuper…', '', 28153),
(132560, 'frFR', 'Bienvenue à la vraie chasse.', '', 28153),
(132550, 'frFR', 'Le grand lézard-tonnerre nous a permis de nous réfugier dans le temple. Vous êtes $gle bienvenu:la bienvenue; ici tant que le Loa le permet.', '', 28153),
(132549, 'frFR', 'NOOON ! Il se fait la malle avec notre M.E.C.H. ! On va rembourser au moins toute notre VIE si on le récupère pas !', '', 28153),
(132547, 'frFR', 'Vous avez ce qu\’il nous faut ?', '', 28153),
(132545, 'frFR', '<Sous vos yeux, des centaines de mèches, toutes reliées à de petits flacons remplis d\’une poudre phosphorescente.>', '', 28153),
(132544, 'frFR', '<L\’éclat métallique des sabres stockés dans cette caisse vous rappelle quelque chose.>', '', 28153),
(132541, 'frFR', '<Des milliers de balles de mousquets sont soigneusement empaquetées dans cette caisse.>', '', 28153),
(132537, 'frFR', '<Cette caisse dégage une odeur caractéristique de poudre à canon.>', '', 28153),
(132536, 'frFR', '<En ôtant l\’enveloppe, vous apercevez le chatoiement métallique de l\’acier dans la caisse.>', '', 28153),
(132534, 'frFR', 'J\’aurais jamais cru risquer encore une fois ma peau pour Cirrus.$B$BFaut dire aussi que j\’aurais jamais cru qu\’on survivrait aussi longtemps !', '', 28153),
(132533, 'frFR', 'Retrouvez-moi là-bas quand vous aurez des informations sur ces cargaisons.', '', 28153),
(132532, 'frFR', 'Envoyez ces gamins à l\’extrémité ouest de la fonderie. J\’attendrai sur place et je m\’assurerai que personne ne tente de les embarquer.', '', 28153),
(132531, 'frFR', 'Cagney a repêché cette gamine avec son bac. Apparemment, elle essayait de s\’évader de la fonderie.$B$BÇa m\’étonne pas le moins du monde que ces ordures de Corsandre exploitent des enfants. J\’étais à peine plus âgé qu\’elle quand la mafia de Boralus m\’a enrôlé de force pour vider les poches des honnêtes gens et faire diversion auprès des gardes.$B$BEn ce bas monde, plus vous êtes faible, plus les autres essaient de profiter de vous.', '', 28153),
(132495, 'frFR', '', 'G\’huun… C\’est pas… ce que tu avais promis…', 28153),
(132494, 'frFR', '', 'Imbécile ! Maintenant, votre âme, elle appartient à G\’huun !', 28153),
(132493, 'frFR', '', 'Non ! Pas encore… prête… pour ça…', 28153),
(132492, 'frFR', '', 'Vous osez interrompre mon recueillement ? Z\’allez le regretter !', 28153),
(132453, 'frFR', '', 'J\’ai bien cru que j\’allais étouffer, là-d\’dans ! Merci, camarade !', 28153),
(132450, 'frFR', '', 'Triture a le souffle coupé.', 28153),
(132444, 'frFR', 'Par ici !', 'Par ici !', 28153),
(132416, 'frFR', 'Vous éloignez pas !', '', 28153),
(132415, 'frFR', 'Il faut aller au jardin des Loas avant qu\’il soit trop tard. Et fissa !', '', 28153),
(132408, 'frFR', '', 'Merci d\’avoir remis un peu d\’ordre. Zem\’lan est bien plus dangereux que ce qu\’en disent les légendes.', 28153),
(132406, 'frFR', 'Ça faisait longtemps que je ne m\’étais pas sentie aussi mal. Merci, $n !', '', 28153),
(132404, 'frFR', '', 'Quand je planterai enfin mes griffes dans Yazma et sa secte arachnéenne… le sang, il coulera à flots.', 28153),
(132403, 'frFR', 'Merci, $ct. Pour la Horde !', 'Merci, $ct. Pour la Horde !', 28153),
(132398, 'frFR', 'Je n\’ai pas de temps à perdre en bavardages.', '', 28153),
(132396, 'frFR', 'Pourquoi vous posez ce genre de questions ? Vous voulez qu\’on vous envoie dans les sables ?', '', 28153),
(132376, 'frFR', '', 'Vous me le paierez…', 28153),
(132374, 'frFR', 'Aaaaaaargh !', 'Aaaaaaargh !', 28153),
(132365, 'frFR', 'Le Loa est retourné au temple.', 'Le Loa est retourné au temple.', 28153),
(132364, 'frFR', 'Vous n\’êtes pas en sécurité ici. Vous feriez mieux de partir avant qu\’il soit trop tard.', 'Vous n\’êtes pas en sécurité ici. Vous feriez mieux de partir avant qu\’il soit trop tard.', 28153),
(132343, 'frFR', 'Il y a un creux bien caché de l\’autre côté de ces ruines. Ce serait l\’endroit rêvé pour installer une base opérationnelle. Dites à l\’équipe de se retrouver là-bas.', '', 28153),
(132342, 'frFR', 'Krag\’wa fixe brièvement les luisants, fasciné par leur lueur.', '', 28153),
(132340, 'frFR', 'Krag\’wa avale la viande d\’une seule bouchée !', '', 28153),
(132325, 'frFR', 'Vous osez m\’insulter ! Hors de ma vue !', '', 28153),
(132324, 'frFR', 'Krag\’wa devient enragé ! Vous avez trop tardé !', '', 28153),
(132323, 'frFR', 'J\’accepte vos offrandes. Maintenant, montrez-moi ce que vous savez faire.', '', 28153),
(132322, 'frFR', 'Krag\’wa regarde autour de lui, l\’air irrité. Il semble s\’ennuyer. Distrayez-le !', '', 28153),
(132321, 'frFR', 'Krag\’wa se lèche les babines et vous regarde avec appétit. Nourrissez-le !', '', 28153),
(132320, 'frFR', 'Vous m\’apportez des cadeaux ! J\’apprécie ! Vous allez pouvoir vivre quelques instants de plus.', '', 28153),
(132310, 'frFR', 'Utilisation du masque d\’esprit', 'Utilisation du masque d\’esprit', 28153),
(132308, 'frFR', 'Krag\’wa tout-puissant, voici mon offrande de chair et de parasites.', 'Krag\’wa tout-puissant, voici mon offrande de chair et de parasites.', 28153),
(132307, 'frFR', 'Vous êtes $gun ami:une amie; des grenouilles. Alors… je ne vais pas vous manger.', '', 28153),
(132306, 'frFR', 'Une invasion ! Êtes-vous ici pour voler mes enfants ? Je vais vous dévorer.', '', 28153),
(132297, 'frFR', 'On dirait qu\’un chemin part dans cette direction…', '', 28153),
(132296, 'frFR', 'Qu\’y a-t-il, Notley ?', '', 28153),
(132294, 'frFR', 'Je vous en prie, prenez ces pierres que j\’ai ramassées. Ma vieille carcasse ne peut plus s\’encombrer de trésors aussi lourds. Oh oh oh !', '', 28153),
(132293, 'frFR', 'Oh, bonjour ! Pourriez-vous éventuellement aider le vieil homme que je suis ? Il se trouve que j\’ai quelques ennuis…', '', 28153),
(132289, 'frFR', 'J\’ai un plan pour régler cette affaire, ne vous inquiétez pas.', '', 28153),
(132288, 'frFR', 'Barbe-Infâme dire merci ! Prendre qui-brille, eux porter malheur.', '', 28153),
(132287, 'frFR', '', 'Hé vous ! Un coup de main ne serait pas de refus !', 28153),
(132279, 'frFR', '', 'Il nous faut renforcer notre position. Nous sommes le dernier rempart qui protège mon pays de la destruction.', 28153),
(132275, 'frFR', '', 'Comment osez-vous profaner notre dernière demeure ?', 28153),
(132274, 'frFR', '', 'Déguerpissez ! Laissez-nous à notre tourment !', 28153),
(132267, 'frFR', 'Eh bien, pas de quoi pavoiser. Au moins, vous avez trouvé mon fusil.', '', 28153),
(132266, 'frFR', 'Tomber sur vous, ça me change des Trolls de sang que je traque tout le temps.', '', 28153),
(132265, 'frFR', 'Bougez pas. Votre caboche, faut que je la coupe proprement.', '', 28153),
(132264, 'frFR', 'Saluez Bwonsamdi de ma part.', '', 28153),
(132263, 'frFR', 'Approchez. Soyez pas timide.', '', 28153),
(132262, 'frFR', 'Faites attention...', '', 28153),
(132261, 'frFR', 'Votre tête, elle est pour moi.', '', 28153),
(132260, 'frFR', 'Montrez donc ce que vous avez dans le ventre, $R !', '', 28153),
(132254, 'frFR', '', 'Embuscade !', 28153),
(132243, 'frFR', '', 'J\’ai décidé de déménager à Havre-de-l\’Est. Prions pour qu\’ils n\’aient pas subi le même sort que Ruisseval.', 28153),
(132240, 'frFR', '', 'Je sens de la colère et du chagrin ici. Je ne sais pas ce qu\’il s\’est passé à cet endroit, mais cela ne s\’est pas bien terminé.', 28153),
(132237, 'frFR', '<La mâchoire d\’un piège mortel a perforé la jambe de ce défunt chasseur.$B$BIl semble que des fléchettes aient transpercé son armure.$B$BÀ en juger par l\’expression d\’étonnement figée sur son visage, il n\’a pas vu la mort venir.>', '', 28153),
(132236, 'frFR', '', 'Gentil, toutou ! Tu ne voudrais quand même pas que les invités partent le ventre vide… ou pire, à jamais !', 28153),
(132221, 'frFR', 'AJOUTER STAND DE TIR ICI', '', 28153),
(132205, 'frFR', 'Les geôliers de Jaina sont arrivés ici il y a quelques jours à peine pour l\’emmener en exil. Si nous faisons vite, nous avons une chance de la retrouver avant qu\’il ne soit trop tard.', '', 28153),
(132201, 'frFR', '', 'Vous allez payer pour la mort de mes sœurs !', 28153),
(132190, 'frFR', 'La dresseuse de bêtes, elle dit que z\’êtes des nôtres maintenant, et ça, ça vous donne le droit de rester ici. Par contre, allez pas vous imaginer qu\’on vous a pas à l\’œil.', '', 28153),
(132189, 'frFR', '', 'Chevaucher un pterreurdactyle, c\’est l\’éclate, et le mot est faible ! Z\’avez intérêt à vous accrocher !', 28153),
(132188, 'frFR', 'Très bien, c\’est donc ici que nous commencerons.', '', 28153),
(132187, 'frFR', 'Il est probable qu\’elle ait suivi la route à la recherche d\’un abri.', '', 28153),
(132186, 'frFR', 'Je ne m\’inquiète pas pour ça, Masse. Retrouvons tout d\’abord Jaina. Yorrick, des idées ?', '', 28153),
(132185, 'frFR', '', 'Quelque chose me dit qu\’ils n\’ouvriront pas la porte à notre retour…', 28153),
(132180, 'frFR', '', 'C\’est parti, par ici !', 28153),
(132179, 'frFR', 'Qu\’est-ce que vous voulez demander au vieux Bwonsamdi ?', '', 28153),
(132178, 'frFR', 'Pas mal, pas mal ! Le sang de faucheur d\’âme, il coule peut-être dans vos veines !', '', 28153),
(132177, 'frFR', 'Comment vous osez profaner mon cadavre !', '', 28153),
(132169, 'frFR', 'L\’Alliance est prête à offrir une importante récompense pour le retour de Jaina.', 'L\’Alliance est prête à offrir une importante récompense pour le retour de Jaina.', 28153),
(132168, 'frFR', 'En Drustvar ? C\’est une plaisanterie ?!\n\nNon merci, ma place est ici, au mur, à apporter leur ravitaillement à nos braves soldats ! Seul un simple d\’esprit choisirait de franchir ces portes !', '', 28153),
(132152, 'frFR', '', 'Vous combattez vaillamment, il faut bien l\’admettre. Le maréchal peut compter sur mon épée.', 28153),
(132149, 'frFR', '', 'Il est trop tard pour faire demi-tour, Yorrick. Denholm ne pardonnera pas à un garde de s\’être retourné contre les siens, même s\’il ne faisait qu\’obéir aux ordres.', 28153),
(132148, 'frFR', 'Jaina ? Elle est la raison de cette expédition ? Mais c\’est de la trahison !', '', 28153),
(132146, 'frFR', 'C\’est un risque que je dois prendre, capitaine. Soldats, suivez-moi.', '', 28153),
(132145, 'frFR', 'Allez-y, Reade, mais la reine en aura vent ! Vous ne mettrez plus jamais les pieds à Boralus !', '', 28153),
(132144, 'frFR', 'Assez, j\’abandonne !', '', 28153),
(132143, 'frFR', 'Ce n\’est vraiment pas le moment ! Soldats, à mes côtés !', '', 28153),
(132142, 'frFR', 'Sur ordre de la reine, nul ne doit franchir cette porte. Même pas vous.', '', 28153),
(132141, 'frFR', 'Capitaine Denholm, j\’ai mobilisé ces hommes en vue d\’une mission spéciale. Je vous ordonne de nous laisser passer !', '', 28153),
(132140, 'frFR', 'Halte-là ! Où croyez-vous aller comme ça avec mes hommes, maréchal ?', '', 28153),
(132139, 'frFR', 'Me voilà convaincu ! Dites au maréchal Reade que l\’intendant Notley est à son service !', '', 28153),
(132138, 'frFR', 'Je vais simplement… emprunter ce dont nous avons besoin…', '', 28153),
(132137, 'frFR', 'Une récompense, vous dites ? Voilà qui change la donne…', '', 28153),
(132136, 'frFR', 'Cessez le feu ! On dirait que nous les avons mis en fuite.', '', 28153),
(132135, 'frFR', 'Prenez une arbalète et aidez-moi !', '', 28153),
(132134, 'frFR', 'Puisqu\’il a besoin de moi, je suivrai ses ordres, mais ce serait manquer à nos devoirs que de partir sans réduire le nombre de ces bêtes.', '', 28153),
(132133, 'frFR', 'Je me doutais que le maréchal était là pour cette raison, mais je vous conseille de ne pas mentionner son nom par ici…', '', 28153),
(132132, 'frFR', '', 'Allez, si vous arrivez à me prouver votre valeur au combat, je rejoindrai le petit groupe de Reade. En garde !', 28153),
(132131, 'frFR', '', 'Les dangers du Tombois ne me font pas peur, mais je n\’ai aucune envie de jouer aux nounous avec $gun continental:une continentale; sans expérience.', 28153),
(132130, 'frFR', '', 'Bienvenue à la grande chasse, $r. Ici, tout ce qui bouge, c\’est une proie potentielle.$b$bEt en plus, on honore les chasseurs qui rapportent les plus belles prises.', 28153),
(132129, 'frFR', 'Faites gaffe, hein ! Cette sorcière a un mojo très puissant !', '', 28153),
(132128, 'frFR', 'La tablette est antique et érodée. Elle contraste nettement avec les offrandes fraîches qui ont été placées devant elle.', 'La tablette est antique et érodée. Elle contraste nettement avec les offrandes fraîches qui ont été placées devant elle.', 28153),
(132117, 'frFR', '', 'Votre cadavre, il servira la maîtresse !', 28153),
(132114, 'frFR', 'La Horde n\’est qu\’un ramassis de cloportes !', '', 28153),
(132113, 'frFR', 'Cette guerre n\’en finira donc jamais ?', '', 28153),
(132112, 'frFR', 'Je retourne aux ténèbres…', '', 28153),
(132111, 'frFR', 'Faites attention à vous, soldat.', '', 28153),
(132107, 'frFR', 'C\’est au nord. Suivez la rivière et traversez à gué dès que vous pourrez.', '', 28153),
(132106, 'frFR', '', 'J\’pars avec eux, histoire de vérifier que tout se passe sans accroc.', 28153),
(132105, 'frFR', 'Bienvenue ! Excusez le désordre, les visiteurs vivants sont plutôt rares.', '', 28153),
(132096, 'frFR', 'Hum, je vous crois… pour l\’instant. Alors causons.', '', 28153),
(132095, 'frFR', '', 'Je le jure !', 28153),
(132094, 'frFR', 'Attendez, Jhasan ! $GIl:Elle; a pas forcément tort. Peut-être que cette gamine, elle dit vrai.', '', 28153),
(132093, 'frFR', 'Alors, on discute pour laisser le temps à ses petits amis d\’arriver ?', '', 28153),
(132092, 'frFR', '', 'Attendez, y a rien à crain… $n, attention !', 28153),
(132081, 'frFR', 'Je regrette que Zulsan soit pas là pour vous accueillir. Il aurait adoré votre coiffure.', '', 28153),
(132068, 'frFR', 'Oui, j\’ai entendu, Man\’zul. Mais je maintiens que ton couvre-œil est plus laid que l\’arrière-train d\’un saurolisque.', '', 28153),
(132067, 'frFR', 'Ha ! Sois aimable, Volni ! T\’as pas tort, mais bon, c\’est ce qui arrive quand on s\’habille dans le noir…', '', 28153),
(132066, 'frFR', 'Grenja est notre barde. Elle peut jouer n\’importe quelle chanson… tant que c\’est au tambour. Elle adore taper sur des trucs. Vous, vous n\’avez rien à craindre… J\’en suis sûr, enfin… je crois.', '', 28153),
(132057, 'frFR', 'Non, Grenja, je t\’achèterai pas un tambour doré ! Arrête avec ça ou je te confisque ton nouveau chapeau !', '', 28153),
(132055, 'frFR', 'On a intérêt à ouvrir l\’œil, et le bon. Ce marais, c\’est la source d\’un puissant vaudou.', '', 28153),
(132054, 'frFR', 'Vous sentez la chair fraîche. L\’odeur des marais n\’a pas imprégné votre corps. Il faut qu\’on parle.', '', 28153),
(132053, 'frFR', '', 'Les êtres sombres ont appelé Annie, mais du mal elle s\’est tenue éloignée ! Personne ne sera donc vraiment surpris qu\’elle se retrouve à présent enchaînée !', 28153),
(132049, 'frFR', '', 'La ferme de Sam était bien tenue. Il prenait soin de ses animaux. Des bois il n\’est jamais revenu. Qui va s\’occuper de ses bestiaux ?', 28153),
(132048, 'frFR', '', 'L\’âme de monsieur Hayes était d\’une infinie douceur. Quel dommage que les sorcières aient sacrifié son cœur !', 28153),
(132047, 'frFR', '', 'Dame Mary nous a abandonnés au profit de forces diaboliques. Elle a apporté la mort au village et rendu les bois maléfiques.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(132046, 'frFR', 'Par ici, $gétranger:étrangère;. Passez cette porte et prenez l\’ascenseur. Le roi, il vous attend.', '', 28153),
(132045, 'frFR', '', 'Faites attention, on vous a à l\’œil. Vous allez rencontrer un des plus vieux Trolls au monde. Et s\’il a survécu pendant tout ce temps, c\’est parce que mon frère et moi, on veille sur lui. Alors, pas de blague.', 28153),
(132044, 'frFR', 'Vengeance pour Zul\’jin !', '', 28153),
(132043, 'frFR', 'J\’espère qu\’il y a à manger sur ce bateau !', 'J\’espère qu\’il y a à manger sur ce bateau !', 28153),
(132042, 'frFR', 'Et maintenant, je vais me réchauffer devant un bon feu !', 'Et maintenant, je vais me réchauffer devant un bon feu !', 28153),
(132041, 'frFR', 'S\’il vous plaît, aidez les adultes aussi !', 'S\’il vous plaît, aidez les adultes aussi !', 28153),
(132040, 'frFR', 'Merci !', 'Merci !', 28153),
(132039, 'frFR', 'Je retourne à l\’école…', 'Je retourne à l\’école…', 28153),
(132038, 'frFR', 'Ils m\’attraperont pas ! Je suis trop rapide pour eux !', 'Ils m\’attraperont pas ! Je suis trop rapide pour eux !', 28153),
(132037, 'frFR', 'Je file !', 'Je file !', 28153),
(132020, 'frFR', '', 'Du calme, Drekal. Ces créatures, elles nous ont offert l\’asile. On doit gagner leur confiance.', 28153),
(132019, 'frFR', 'Ho ho, ça, c\’était une âme puissante ! Le vieux Bwonsamdi se sent tout revigoré. Ha ha, ouais, mes pouvoirs, ils sont en train de grandir !', '', 28153),
(132017, 'frFR', '', 'Vous passez à côté d\’un pouvoir inimaginable...', 28153),
(132016, 'frFR', 'Bien joué. Ça les fera certainement reculer.', '', 28153),
(132015, 'frFR', 'Les Sephraks étendent leur empire et envahissent les plaines où vivaient nos ancêtres. Il faut mettre un terme à cette expansion !', '', 28153),
(132010, 'frFR', 'Rends-toi au bord de l\’eau. Un bateau t\’y attend pour te conduire en sécurité.', 'Rends-toi au bord de l\’eau. Un bateau t\’y attend pour te conduire en sécurité.', 28153),
(132009, 'frFR', '', 'Imbécile... Vous ne savez pas dans quoi vous mettez les pieds...', 28153),
(132004, 'frFR', 'J\’ai vu des sales types. Ils criaient sur tout le monde, même sur les autres grands !', 'J\’ai vu des sales types. Ils criaient sur tout le monde, même sur les autres grands !', 28153),
(132003, 'frFR', 'Vous êtes $gméchant:méchante; ?$B$BVous en avez pas l\’air, en tout cas.', 'Vous êtes $gméchant:méchante; ?$B$BVous en avez pas l\’air, en tout cas.', 28153),
(132002, 'frFR', 'Mon nez est gelé, mes oreilles sont gelées, mes orteils sont gelés...', 'Mon nez est gelé, mes oreilles sont gelées, mes orteils sont gelés...', 28153),
(131999, 'frFR', 'Ils ont dit qu\’ils allaient nous nourrir, mais j\’ai pas eu droit à une miette de pain depuis mon arrivée !', 'Ils ont dit qu\’ils allaient nous nourrir, mais j\’ai pas eu droit à une miette de pain depuis mon arrivée !', 28153),
(131998, 'frFR', '', 'Drekal et moi, on vous retrouvera sur place après avoir jeté un coup d\’œil.', 28153),
(131997, 'frFR', '', 'Vous devriez aller au temple un peu plus loin. Si ce Loa, il est aussi puissant qu\’on le raconte, il pourra peut-être nous aider à trouver Rakera.', 28153),
(131996, 'frFR', '<Tousse.> <Tousse.>$B$BJe veux rentrer chez moi.', '<Tousse> <Tousse>$B$BJe veux rentrer chez moi.', 28153),
(131995, 'frFR', 'Pitié, ne me criez pas dessus !', 'Pitié, ne me criez pas dessus !', 28153),
(131994, 'frFR', 'Je suis fatigué.', 'Je suis fatiguée.', 28153),
(131939, 'frFR', '', 'Bienvenue, soldat. Êtes-vous $gprêt:prête; à vous battre pour l\’Alliance ?', 28153),
(131931, 'frFR', 'Vous pensez avoir la vie dure ? Vous n\’imaginez même pas à quel point il est difficile de suivre toutes ces guerres.', '', 28153),
(131897, 'frFR', '', 'Continuons de voler en espérant de pas le découvrir.', 28153),
(131894, 'frFR', '', 'On va devoir traverser ce marais. Tant qu\’on vole de façon discrète, on devrait pas avoir trop de problèmes.', 28153),
(131893, 'frFR', '', 'Kaja, là, en dessous ! C\’est quoi, ces trucs ?', 28153),
(131888, 'frFR', 'Ce que ma\’da veut, ma\’da l\’aura.', '', 28153),
(131887, 'frFR', 'Ma vie pour la grande-mère !', '', 28153),
(131886, 'frFR', 'De la viande pour les mères de la guerre !', '', 28153),
(131885, 'frFR', 'Du sang neuf !', '', 28153),
(131884, 'frFR', 'Ma\’da a dit tuer... non... capturer. C\’est ça ! Capturer.', '', 28153),
(131883, 'frFR', 'Les tendons ! Faut les trancher. Ma\’da a dit, on coupe les tendons.', '', 28153),
(131882, 'frFR', 'Mourez, mourez, mourez !', '', 28153),
(131881, 'frFR', '<Vous trouvez une lettre en fouillant ses poches.>\n\nMa chère Mary,\n\nJe t\’en supplie, rentre à la maison. Russell n\’arrête pas de demander après toi. Que dois-je lui répondre ? Que sa mère s\’est enfuie dans les bois pour y faire dieu sait quoi ? Tu nous manques, ma chérie. Notre maison est si vide sans toi. Pitié, reviens-nous vite.\n\nTon mari qui t\’aime,\n\nJonathan', '', 28153),
(131880, 'frFR', 'Hips ! Attenchion où vous mettez les pieds...', 'Hips ! Attenchion où vous mettez les pieds...', 28153),
(131878, 'frFR', '<Inspecter le corps afin de l\’identifier.>', '<Inspecter le corps afin de l\’identifier.>', 28153),
(131875, 'frFR', 'Que contient la cargaison du jour ?', 'Que contient la cargaison du jour ?', 28153),
(131874, 'frFR', 'Oui ?', 'Oui ?', 28153),
(131869, 'frFR', 'Grog de la veuve, trois tonneaux !', 'Grog de la veuve, trois tonneaux !', 28153),
(131868, 'frFR', 'Vin épicé, cinq tonneaux ! Bière abyssale, sept tonneaux ! Et pour finir...', 'Vin épicé, cinq tonneaux ! Bière abyssale, sept tonneaux ! Et pour finir...', 28153),
(131867, 'frFR', 'Votre attention, s\’il vous plaît ! Voici la commande du jour !', 'Votre attention, s\’il vous plaît ! Voici la commande du jour !', 28153),
(131855, 'frFR', 'Merci encore pour votre aide. Je vais de ce pas apporter cette offrande au temple.', 'Merci encore pour votre aide. Je vais de ce pas apporter cette offrande au temple.', 28153),
(131851, 'frFR', 'Un peu de calme, tout le monde ! $p va venir saluer chacun d\’entre vous.', '', 28153),
(131845, 'frFR', 'C\’est bon pour l\’instant. La princesse, elle vous attend dans les grands escaliers. Moi, j\’vais continuer à patrouiller, au cas où y aurait des soudards de l\’Alliance qui nous ont échappé.', '', 28153),
(131844, 'frFR', 'On se sépare et on remonte la piste des larbins de l\’Alliance. J\’vais faire de mon mieux pour vous aider à les r\’trouver.', '', 28153),
(131843, 'frFR', 'Venir m\’attaquer dans mon propre temple ? Je rêve ! Ils vont me le payer. Hmm-hmm. Me le payer très cher, même.', '', 28153),
(131842, 'frFR', '', 'Ce monde, ça fait bien trop longtemps que j\’y vis. Enfin, je vais connaître la paix !', 28153),
(131841, 'frFR', 'Allez-y. Bwonsamdi, il vous regarde.', '', 28153),
(131840, 'frFR', 'Bien. Sylvanas sera satisfaite. Venez, « émissaire ». Il nous faut discuter de la prochaine étape.', '', 28153),
(131839, 'frFR', 'Attendez, on est vraiment obligés d\’aller au casse-pipe, tous ? Je me disais qu\’on pourrait peut-être... vous savez... envoyer un champion à notre place, par exemple.', '', 28153),
(131838, 'frFR', 'Pour utiliser le tambour, il faut le maillet de Mambu et celui de Gee\’dae. Les deux, y sont dans mon temple.', '', 28153),
(131832, 'frFR', 'Merci bien.', '', 28153),
(131831, 'frFR', 'Il me faut un moyen de transport pour Zul\’jan.', 'Il me faut un moyen de transport pour Zul\’jan.', 28153),
(131830, 'frFR', '', 'J\’suis morte, mais les créatures, elles répondent toujours à mon appel.\n\nBesoin d\’un moyen de transport ?', 28153),
(131829, 'frFR', 'Faut qu\’on cause. Je dois vous confier une affaire importante.', '', 28153),
(131828, 'frFR', 'Ah, vous voilà ! Je vous cherchais partout !', '', 28153),
(131818, 'frFR', 'N\’oubliez pas notre marché, hein. Continuez à envoyer des âmes à Bwonsamdi… si vous voulez garder ma faveur.', '', 28153),
(131816, 'frFR', 'Princesse, mieux vaut pas se précipiter. Explorons la zone et établissons un plan avant de nous lancer.', '', 28153),
(131803, 'frFR', '', 'Vous d\’vez être $gle héros:l\’héroïne; dont elle a causé. Si vous pouvez aider notre princesse, j\’vais tout vous dire. Je m\’occupe des blessés depuis un sacré moment, et les choses, elles font qu\’empirer.\n\nElle va en Nazmir. Une petite escorte l\’accompagne, mais votre ami Rokhan, il s\’est joint à elle. On leur a filé toutes les provisions dont on pouvait se passer.\n\nIls vont prendre la porte nord-ouest. Aucun Troll de sang a été aperçu dans les parages depuis qu\’ils ont commencé à assiéger la porte principale.\n\nLes yeux de mon Loa, ils sont aveugles là-bas. Faites gaffe.', 28153),
(131777, 'frFR', 'Je m\’acquitterai de cette dette. Vous avez ma parole.', 'Je m\’acquitterai de cette dette. Vous avez ma parole.', 28153),
(131776, 'frFR', 'Je suis libre de partir ? Sans contrepartie ? Vous n\’êtes pas comme la plupart.', '', 28153),
(131774, 'frFR', '', 'Quel cauchemar ! La princesse, elle aurait jamais dû partir. Les Trolls de sang, ils sont à nos portes et le roi, il lève pas le petit doigt !', 28153),
(131771, 'frFR', 'Elle est là à peine un jour et v\’là qu\’elle repart déjà !\n\nTalanji, elle se rend quelque part à l\’insu de son père. Elle a pris que quelques gardes de son escorte personnelle, histoire de faire semblant.\n\nElle a rien dit, mais moi, je crois qu\’elle va en Nazmir. C\’est un endroit dangereux. Si j\’peux pas y aller, j\’serais rassurée que z\’y alliez à ma place.\n\nElle va avoir besoin de ravitaillement. À tous les coups, elle invoquera des marqueurs avec les prêtres depuis son repère. Filez-moi votre carte.', '', 28153),
(131766, 'frFR', 'Où est Talanji ?', 'Où est Talanji ?', 28153),
(131765, 'frFR', 'Merci d\’avoir sauvé notre princesse. D\’expérience, je sais qu\’elle est pas toujours facile à protéger. Elle pense devoir sauver les Zandalari toute seule.', '', 28153),
(131764, 'frFR', 'Votre gentillesse est singulière.', 'Votre gentillesse est singulière.', 28153),
(131763, 'frFR', 'Nous n\’avons pas de temps à perdre en bavardage, soldat. Ceci est le quartier général avancé. Nous sommes aux premières loges, et le camp Taurajo nous envoie vague après vague de ces saletés de Taurens.\n\nSi nous cédons du terrain ici, nous n\’aurons plus aucune chance de prendre les portes.', '', 28153),
(131761, 'frFR', 'Le mojo, vous ne pouvez pas lui échapper !', '', 28153),
(131752, 'frFR', 'Valjabu, y a pas de raison de passer de l\’autre côté. Soumets-toi à G\’huun et la vie éternelle sera à toi !', '', 28153),
(131750, 'frFR', 'Encore un misérable être venu mourir en exil dans le désert ?', '', 28153),
(131745, 'frFR', '', 'Allez en Nazmir avec Rokhan. Je vous retrouverai là-bas. Il est temps d\’en finir avec les Trolls de sang.', 28153),
(131742, 'frFR', '', 'Que la bénédiction d\’Odin vous accompagne. Tenez, voici une récompense, vous la méritez.', 28153),
(131741, 'frFR', 'Allez, les gars. On entre là-dedans et que la fête commence. Postez des gardes aux portes au cas où ils chercheraient à nous fiche dehors. Je veux aussi un bar bien garni à ma disposition. Et pour finir, qu\’on m\’apporte une autre pierre de téléportation en cas d\’urgence.', '', 28153),
(131709, 'frFR', 'Qu\’est-ce qui se passe ici ? Pourquoi nous parque-t-on comme du bétail ?', '', 28153),
(131706, 'frFR', '', 'Yorrick, amenez votre nécessaire ici. On a un survivant !', 28153),
(131705, 'frFR', 'Euh… oh ! Oui, chef !', '', 28153),
(131703, 'frFR', '', 'Debout, enseigne ! Il faut trouver un moyen de sortir d\’ici !', 28153),
(131690, 'frFR', 'Le gardelame Hozzul ne réagit pas.', '', 28153),
(131689, 'frFR', '', 'La gardelame Jorana ne réagit pas.', 28153),
(131674, 'frFR', 'Bienvenue à la Défense d\’or !', '', 28153),
(131672, 'frFR', 'Cet exilé est toujours en vie, mais a toutes les peines du monde à respirer.\n\nAu-delà de ses blessures apparentes, sa maladie semble l\’affliger plus gravement qu\’il n\’y paraît.', '', 28153),
(131671, 'frFR', 'Une lueur semble percer à travers les décombres qui bloquent ce couloir.\n\nDéblayer ces débris devrait permettre de sortir des ruines.', '', 28153),
(131670, 'frFR', 'Ces créatures ont été vaincues grâce à la magie du Givre, preuve irréfutable du passage de Jaina.\n\nVous ignorez cependant où elle a pu disparaître.', '', 28153),
(131668, 'frFR', 'Ces empreintes ressemblent à celles de la bête qui a attaqué votre groupe dans la forêt. Elle semble avoir traîné quelque chose derrière elle.\n\nCurieusement, la piste disparaît au bout d\’un moment, comme si la créature s\’était volatilisée.', '', 28153),
(131667, 'frFR', 'Attention... Je commence à avoir les CROCS !', '', 28153),
(131666, 'frFR', '', 'C\’est QUOI, votre truc ?', 28153),
(131665, 'frFR', 'Le jeune navrecorne pousse des glapissements de surprise.', '', 28153),
(131664, 'frFR', 'Le navrecorne juvénile vous saute dessus pour vous faire un câlin.', '', 28153),
(131663, 'frFR', 'Le navrecorne juvénile vous mord affectueusement. Visiblement, il ne connaît pas sa force.', '', 28153),
(131662, 'frFR', 'Le navrecorne juvénile vous bouscule gentiment.', '', 28153),
(131661, 'frFR', 'J\’ai tellement faim que je pourrais avaler un brutosaure !', '', 28153),
(131659, 'frFR', 'M\’man, je peux avoir plus de viande, s\’il te plaît ?', '', 28153),
(131658, 'frFR', 'Les flagellants, c\’est bon, mais moi, je préfère la VIANDE !', '', 28153),
(131657, 'frFR', '%s pousse un grognement taquin.', '', 28153),
(131656, 'frFR', '%s vous décoche un regard malicieux.', '', 28153),
(131655, 'frFR', '%s caracole joyeusement autour de vous.', '', 28153),
(131654, 'frFR', '%s se met à gémir avec enthousiasme.', '', 28153),
(131653, 'frFR', 'Écoutez, $gmon petit:ma petite;, vous avez peut-être du cran, mais contrairement à moi, vous y connaissez rien en négociations.$b$bContentez-vous de m\’obtenir une audience avec leur roi de malheur, et je m\’arrangerai pour lui soutirer sa flotte, son trône, tout cet or gaspillé en décorations clinquantes et peut-être même quelques masques tiki, juste pour le style.', '', 28153),
(131652, 'frFR', 'Hé hé, voyez-vous ça ! Peut-être qu\’après tout, vous allez pas me faire perdre mon temps. Allons discuter dans le temple. Le vieux Bwonsamdi, il a peut-être une proposition à vous faire.', '', 28153),
(131651, 'frFR', 'Ah, Salazae… Ça fait trop longtemps qu\’elle s\’accroche au monde des vivants. Faites ce qui faut pour apporter son âme à Bwonsamdi, ce Loa à la patience infinie, d\’accord ?', '', 28153),
(131650, 'frFR', '', 'Je n\’ai rien à vous dire, à moins que vous puissiez me rendre mon bien-aimé.', 28153),
(131649, 'frFR', 'Nous sommes prêts à recevoir votre bénédiction.', 'Nous sommes prêts à recevoir votre bénédiction, grand Loa.', 28153),
(131648, 'frFR', 'Bien des années se sont écoulées depuis l\’édification de ce temple. Si ses murs sont restés les mêmes, mes disciples, eux, ont changé de visage.', '', 28153),
(131637, 'frFR', 'Salutations, petites créatures. Je suis de retour. Avancez, que je vous bénisse.', '', 28153),
(131633, 'frFR', 'Seuls les Zandalari sont autorisés à franchir les portes de ce lieu sacré ! La loi dit que…', '', 28153),
(131632, 'frFR', 'Que tous le sachent… Je vous nomme porte-parole de la Horde.', '', 28153),
(131631, 'frFR', 'Je suis le roi. La loi, c\’est ce que j\’en fais.', '', 28153),
(131630, 'frFR', 'Tous les yeux du royaume, ils sont sur vous. En ce jour, je vous nomme porte-parole de la Horde.', '', 28153),
(131629, 'frFR', 'Laissons la Horde prouver sa valeur à Zandalar. En tant qu\’invitée, elle restera au Grand Sceau… pour le moment.', '', 28153),
(131628, 'frFR', 'Talanji a peur que je ne voie pas nos vrais ennemis. Mais je ne suis pas aveugle.', '', 28153),
(131627, 'frFR', 'Mais ma fille, elle aussi dit vrai. J\’admire le courage qu\’il vous a fallu pour la sauver.', '', 28153),
(131626, 'frFR', 'Jakra\’zet a raison… Vous voulez la puissance de notre flotte pour affronter l\’Alliance.', '', 28153),
(131625, 'frFR', '', 'Super ! Prenez place pour le goûter ! Grâce à vous et à Poutou, je vais pouvoir appeler le dernier invité !', 28153),
(131624, 'frFR', '', 'Par ici ! Ça va être le meilleur goûter de ma vie !', 28153),
(131623, 'frFR', '', 'On se dépêche ! On va être en retard pour le goûter !', 28153),
(131620, 'frFR', '', 'Entre votre sacrifice et celui de mon mari, le rituel sera enfin accompli !', 28153),
(131619, 'frFR', '', 'Rejoignez-nous, ma sœur, et ensemble, nous aurons le pouvoir !', 28153),
(131618, 'frFR', '<Vous remarquez une plaie béante sur la poitrine de l\’homme. En l\’examinant de plus près, vous vous apercevez qu\’on lui a arraché le cœur.>', '', 28153),
(131617, 'frFR', 'Le nom « S. Aubepin » est gravé dans le bois.', '', 28153),
(131616, 'frFR', '', 'M. Aubepin essayait toujours de protéger ses animaux des toutous. Mais maintenant, les toutous peuvent enfin manger !', 28153),
(131615, 'frFR', '', 'Notre pauvre petit village a perdu toute vie.', 28153),
(131609, 'frFR', '', 'Restons sur nos gardes. Personne n\’est jamais revenu de Nazmir.', 28153),
(131608, 'frFR', '', 'Les Trolls de sang sont que des sauvages. Ça fait longtemps qu\’ils sont plus une menace.', 28153),
(131607, 'frFR', 'Assez. Je vais décider quoi faire avec notre « $Uinvité:invitée; ».', '', 28153),
(131606, 'frFR', '', 'Nous avons besoin d\’alliés pour vaincre les Trolls de sang. Je n\’ai fait que mon devoir.', 28153),
(131605, 'frFR', 'Talanji a amené ce rebut de la Horde avec elle. C\’est un acte de haute trahison, votre altesse !', '', 28153),
(131604, 'frFR', '', 'Une âme pour mon maître ! Une âme pour G\’huun !', 28153),
(131603, 'frFR', 'Ce… c\’est pas… terminé…', 'Ce… n\’est pas… terminé…', 28153),
(131602, 'frFR', '', 'G\’huun, c\’est le maître de ces terres. Bientôt, même ce guignol de Bwonsamdi le servira !', 28153),
(131544, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(131543, 'frFR', '', '<Annie vous dévisage, le regard inexpressif. Ses habits sont souillés de sang, mais elle semble à peu près indemne. Ses marmonnements sont incompréhensibles.>', 28153),
(131542, 'frFR', 'Masse, Notley et Yorrick ont indiqué être prêts à partir.', 'Masse, Notley et Yorrick ont indiqué être prêts à partir.', 28153),
(131541, 'frFR', 'Vous venez de Ruisseval ?', 'Vous venez de Ruisseval ?', 28153),
(131540, 'frFR', '', '<Annie tremble comme une feuille, l\’air hagard et le regard perdu à l\’horizon.>', 28153),
(131539, 'frFR', 'L\’heure est donc venue. Retrouvez-moi à la porte et partons à l\’assaut de Drustvar !', '', 28153),
(131505, 'frFR', 'Je ne l\’abandonnerai pas comme ça. Allez dire aux autres ce qu\’ils lui ont fait. Je vous retrouverai au temple.', '', 28153),
(131504, 'frFR', '*Sniff* Réveille-toi, je t\’en supplie...', '', 28153),
(131503, 'frFR', 'Hakasi, tu es hors de danger... Hakasi ? Hé... réveille-toi...', '', 28153),
(131497, 'frFR', 'Vilain diablosaure ! Vilain !', 'Vilain diablosaure ! Vilain !', 28153),
(131496, 'frFR', 'Merci de nous avoir aidés et d\’avoir relayé mes ordres. Je ferai mon rapport au maréchal Reade.', '', 28153),
(131494, 'frFR', 'Mais le temps qui passe est souvent l\’ennemi de la sagesse.', '', 28153),
(131493, 'frFR', 'Il serait plus sage d\’attendre la fin de la tempête pour nous aventurer en territoire hostile.', '', 28153),
(131492, 'frFR', 'Très bien, je prépare les fournitures au plus vite.', '', 28153),
(131491, 'frFR', 'Dites au maréchal Reade que l\’intendant Notley est à son service !', '', 28153),
(131490, 'frFR', '', 'Retrouvons-nous à la porte. J\’espère que vous êtes $gprêt:prête; pour ce qui nous attend.', 28153),
(131489, 'frFR', '', 'Ah ! Alors comme ça, Reade cherche à prendre d\’assaut les bois de Drustvar ? Il va enfin se passer quelque chose d\’intéressant ici !', 28153),
(131487, 'frFR', '', 'J\’espère que vous avez une bonne raison de m\’interrompre.\n\nOu n\’avez-vous pas remarqué que j\’étais occupée ?', 28153),
(131486, 'frFR', 'Une tempête se forme du côté du Tombois. Il va nous être difficile d\’anticiper une quelconque menace.\n\nComme si Drustvar n\’était déjà pas assez dangereux sans les intempéries…', '', 28153),
(131485, 'frFR', 'Le maréchal Reade mobilise des forces pour son expédition à la recherche de Jaina.', 'Le maréchal Reade mobilise des forces pour son expédition à la recherche de Jaina.', 28153),
(131484, 'frFR', 'Nous recevons rarement la visite de continentaux au mur.\n\nVous cherchez du ravitaillement ?', '', 28153),
(131479, 'frFR', 'Je dois avouer que votre courage me surprend.\n\nVous n\’êtes pas d\’ici et pourtant, vous avez affronté mille dangers pour sauver l\’un des nôtres. J\’espère que votre lame est aussi inflexible que votre détermination.\n\nNous attendons vos ordres pour partir.', '', 28153),
(131478, 'frFR', 'Tiens bon, Hakasi... On va te sauver, je le jure !', '', 28153),
(131477, 'frFR', 'Vous ne vous en tirerez... pas comme ça... espèce de monstre !', '', 28153),
(131476, 'frFR', 'Qu\’est-ce qu\’$gun continental:une continentale; vient faire au mur ? Constater la désolation qui règne en Drustvar sans se frotter à ses dangers ?\n\nRentrez chez vous, $ggamin:gamine;. Ce n\’est pas un endroit pour vous.', '', 28153),
(131475, 'frFR', 'Comment ?\n\nVeuillez excuser mon incivilité.\n\nVous êtes donc $gun allié:une alliée; de la maison Portvaillant ? J\’imagine que vous venez chercher des nouvelles de Jaina ? Pourquoi auriez-vous fait tout ce chemin, sinon ?\n\nEh bien, vous tombez à pic.', '', 28153),
(131472, 'frFR', '<Donner la note de Taelia à Reade.>', '<Donner la note de Taelia à Reade.>', 28153),
(131471, 'frFR', 'Ah, salut à toi, Hanzabu ! Tu viens payer tes dettes ?', '', 28153),
(131470, 'frFR', 'Quelles nouvelles m\’apportez-vous, $gvoyageur:voyageuse; ?', '', 28153),
(131469, 'frFR', 'Il faut le sauver !', '', 28153),
(131468, 'frFR', 'Je viens d\’entendre la voix d\’Hakasi. Elle venait de cette grotte ! Il avait l\’air d\’avoir des ennuis...', '', 28153),
(131467, 'frFR', '$n, par ici !', '', 28153),
(131466, 'frFR', 'Gardes ! Alliés ! Les troupes de la Horde approchent par le sud-ouest ! Défendez les portes !', '', 28153),
(131465, 'frFR', 'Occupez-vous des serpents pendant que j\’entre là-dedans à la recherche d\’Hakasi...', '', 28153),
(131461, 'frFR', 'BWAH HAH HAH ! Hanzabu, vous me prenez pour un imbécile ? C\’est pas vous qui les avez tués, ces deux-là.', '', 28153),
(131460, 'frFR', 'Y en a deux particulièrement puissants. Y devraient suffire à notre accord…', '', 28153),
(131459, 'frFR', 'Grand Bwonsamdi, je viens t\’apporter d\’autres âmes… comme convenu.', '', 28153),
(131458, 'frFR', '', 'Attendez… écoutez, je crois que j\’ai entendu un truc.', 28153),
(131457, 'frFR', '', 'La barrière, elle est morte ! On se tire d\’ici !', 28153),
(131456, 'frFR', 'Elle était inutile. Les Trolls de sang ont attaqué nos terres au nord, l\’Alliance a franchi nos frontières au sud et maintenant vous laissez ces barbares de la Horde entrer dans notre ville.', '', 28153),
(131455, 'frFR', '', 'Je sais pas ce que vous avez fait, mais ça a viré une partie du mojo qui alimente la barrière. Faut trouver d\’autres trucs comme ça.', 28153),
(131454, 'frFR', '', 'Rakera, c\’était un des plus grands chefs du royau…', 28153),
(131453, 'frFR', 'J\’ai des nouvelles d\’Hakasi.', 'J\’ai des nouvelles d\’Hakasi.', 28153),
(131452, 'frFR', '', 'Ennemis en approche !', 28153),
(131451, 'frFR', '', 'L\’issue, elle est bloquée ! Faut inspecter cet endroit. Doit bien y avoir un moyen de virer cette barrière.', 28153),
(131450, 'frFR', '', 'Pas de pitié !', 28153),
(131449, 'frFR', '', 'Personne peut nous arrêter !', 28153),
(131448, 'frFR', '', 'Un de moins !', 28153),
(131447, 'frFR', '', 'Tayhuwaniwanga !', 28153),
(131446, 'frFR', '<Un monstre rugit dans le lointain.>', '', 28153),
(131445, 'frFR', 'Il faut partir à sa recherche avant qu\’il ne soit trop tard ! Retrouvez-moi près du canyon dès que vous serez $gprêt:prête; !', '', 28153),
(131444, 'frFR', 'Hakasi est parti enquêter dans le canyon et il n\’est jamais revenu ? Ça ne me dit rien de bon.', '', 28153),
(131443, 'frFR', '', 'Restez sur vos gardes ! Les esprits, y sont en colère. Faut croire qu\’ils sont enfermés ici depuis un bail.', 28153),
(131442, 'frFR', '', 'Notre hôte se réveille.', 28153),
(131440, 'frFR', '', 'Poutou adooore les bois. On doit s\’assurer que les toutous ne l\’ont pas croqué !', 28153),
(131439, 'frFR', 'Vous m\’aurez jamais, sorcière !', '', 28153),
(131435, 'frFR', 'Aidez les dresseurs à mater le diablosaure !', 'Aidez les dresseurs à mater le diablosaure !', 28153),
(131434, 'frFR', 'Attaquez Mort rouge !', 'Attaquez Mort rouge !', 28153),
(131431, 'frFR', 'Lancez un jouet pour distraire le diablosaure !', 'Lancez un jouet pour distraire le diablosaure !', 28153),
(131430, 'frFR', 'Foncez sur la barrière pour la démolir !', 'Foncez sur la barrière pour la démolir !', 28153),
(131429, 'frFR', 'Sortez par la porte nord ! Et gare au diablosaure !', 'Sortez par la porte nord ! Et gare au diablosaure !', 28153),
(131428, 'frFR', 'Bonne chance !', '', 28153),
(131427, 'frFR', 'Bienvenue au terrain d\’entraînement ! Ça, c\’est Petit-Doigt, notre jeune diablosaure. Méfiez-vous, il est très joueur !', '', 28153),
(131426, 'frFR', 'Cette cargaison nous appartient, vermine de l\’Alliance !', 'Cette cargaison nous appartient, vermine de l\’Alliance !', 28153),
(131425, 'frFR', 'Inspecter le corps de plus près.', 'Inspecter le corps de plus près.', 28153),
(131424, 'frFR', '<Les blessures sont profondes. Ces entailles ont été pratiquées avec précision et minutie.$B$BÀ la lumière, vous repérez les traces d\’un liquide au pourtour des lésions.>', '', 28153),
(131419, 'frFR', '', 'C\’est quand vous voulez, mais ne traînons pas. Rakera ne pourra pas résister longtemps dans ces sables.', 28153),
(131418, 'frFR', '', 'Je m\’arrêterai pas avant d\’avoir retrouvé Rakera.', 28153),
(131416, 'frFR', 'Vous avez déjà eu affaire à un diablosaure ? Ils ne mordent pas trop fort… la plupart du temps !', 'Vous avez déjà eu affaire à un diablosaure ? Ils ne mordent pas trop fort… la plupart du temps !', 28153),
(131415, 'frFR', '', 'Vous avez raison ! Allons-y !', 28153),
(131414, 'frFR', '', 'Vos paroles, elles sont sages. Venez, on va chercher comment sortir de cette crypte.', 28153),
(131413, 'frFR', '', 'Z\’avez raison, mec. Faut fouiller cet endroit, y a forcément un moyen de sortir d\’ici.', 28153),
(131408, 'frFR', 'Un soldat n\’abandonne pas, Bwu\’ja. Maintenant, secouez-vous, et trouvons un moyen de sortir d\’ici. Pour la Horde !', 'Un soldat n\’abandonne pas, Bwu\’ja. Maintenant, secouez-vous, et trouvons un moyen de sortir d\’ici. Pour la Horde !', 28153),
(131407, 'frFR', 'Nous avons une mission, Bwu\’ja, et nous devons l\’accomplir coûte que coûte !', 'Nous avons une mission, Bwu\’ja, et nous devons l\’accomplir coûte que coûte !', 28153),
(131406, 'frFR', 'Pensez-vous que le chef de guerre voudrait voir une telle attitude ? Ils comptent sur nous !', 'Pensez-vous que le chef de guerre voudrait voir une telle attitude ? Ils comptent sur nous !', 28153),
(131405, 'frFR', '', 'Combattre sert plus à rien, on est perdus !', 28153),
(131404, 'frFR', 'Vous êtes une chasseuse des ombres, Bwu\’ja. Montrez-leur ce dont vous êtes capable.', 'Vous êtes une chasseuse des ombres, Bwu\’ja. Montrez-leur ce dont vous êtes capable.', 28153),
(131403, 'frFR', 'Laisserez-vous l\’espoir et les rêves de vos ancêtres mourir ici sans combattre ?', 'Laisserez-vous l\’espoir et les rêves de vos ancêtres mourir ici sans combattre ?', 28153),
(131399, 'frFR', 'Continuez à vous battre ! Croyez en vous et faites-leur honneur !', 'Continuez à vous battre ! Croyez en vous et faites-leur honneur !', 28153),
(131396, 'frFR', '', 'Quoi ? Évidemment que non !', 28153),
(131392, 'frFR', 'Reprenez-vous. Vous valez mieux que ça, vous êtes une chasseuse des ombres !', 'Reprenez-vous. Vous valez mieux que ça, vous êtes une chasseuse des ombres !', 28153),
(131391, 'frFR', 'La princesse Talanji, elle est pressée, on dirait. Même qu\’elle a déjà quitté les quais avec Zul. Vous avez intérêt à vous dépêcher si vous voulez les rattraper.', '', 28153),
(131389, 'frFR', '', '', 28153),
(131388, 'frFR', 'Si le désespoir vous ronge, c\’est que votre esprit est vivant et que vous pouvez agir pour changer la donne !', 'Si le désespoir vous ronge, c\’est que votre esprit est vivant et que vous pouvez agir pour changer la donne !', 28153),
(131387, 'frFR', 'Il se libère ! Fuyez !', 'Il se libère ! Fuyez !', 28153),
(131386, 'frFR', 'Tout espoir n\’est pas perdu ! En unissant nos forces, nous trouverons un moyen de vaincre cette malédiction.', 'Tout espoir n\’est pas perdu ! En unissant nos forces, nous trouverons un moyen de vaincre cette malédiction.', 28153),
(131385, 'frFR', 'Pour l\’heure, j\’aime autant vous laisser décider avec Rokhan de la marche à suivre. Il connaît ces gens mieux que moi.$b$bEn outre, ces Trolls voient d\’un mauvais œil les individus qui, comme moi, refusent d\’accepter la mort quand elle se présente. Je ne tiens pas à ce que leur conception étriquée de la vie nous prive du soutien de leur flotte.$b$bL\’échec n\’est pas permis. Sylvanas veut sa flotte, et elle l\’aura.', '', 28153),
(131384, 'frFR', '', 'Oh ? Et qu\’est-ce qui vous fait dire ça ?', 28153),
(131383, 'frFR', 'Reprenez-vous, nous n\’avons pas dit notre dernier mot !', 'Reprenez-vous, nous n\’avons pas dit notre dernier mot !', 28153),
(131382, 'frFR', 'Quand vous rencontrerez les esprits de vos ancêtres, vous tenez vraiment à leur dire que vous avez baissé les bras ?', 'Quand vous rencontrerez les esprits de vos ancêtres, vous tenez vraiment à leur dire que vous avez baissé les bras ?', 28153),
(131377, 'frFR', 'Ne cédez pas au désespoir ! On va s\’en sortir.', 'Ne cédez pas au désespoir ! On va s\’en sortir.', 28153),
(131372, 'frFR', 'Allons-y.', 'Allons-y.', 28153),
(131371, 'frFR', 'J\’arrive pas à croire que Hakasi nous a tout laissé à faire. Ça va lui coûter cher ! Il perd rien pour attendre !', '', 28153),
(131370, 'frFR', '', 'Hah ha ! Essayez encore !', 28153),
(131369, 'frFR', '', 'C\’est sans espoir. Comment qu\’on va faire, pour se barrer d\’ici ?', 28153),
(131333, 'frFR', 'Il m\’a parlé d\’une perturbation dans le canyon, mais je lui ai dit qu\’il n\’y a sûrement pas lieu de s\’en faire.', '', 28153),
(131332, 'frFR', 'Hum... Laissez-moi réfléchir. Ah oui ! Je l\’ai vu entrer dans le canyon, il n\’y a pas si longtemps. Je me demande ce qu\’il faisait là-bas.', '', 28153),
(131331, 'frFR', 'Hakasi ? Oui, je l\’ai vu dans les parages un peu plus tôt. Il cherchait des offrandes pour le rituel.', '', 28153),
(131329, 'frFR', '', 'Soldats, rompez les rangs ! Tous aux abris ! Éloignez-vous le plus possible de ces serpents !', 28153),
(131327, 'frFR', 'Kaja, on devrait ajuster notre cap. On s\’approche de l\’empire sephrak.', '', 28153),
(131325, 'frFR', '', 'Les hommes-serpents ? Je pensais qu\’ils restaient cachés sous les dunes…', 28153),
(131322, 'frFR', '', 'La passe est droit devant ! Volez en rase-mottes et essayez de voir où se trouve Rakera.', 28153),
(131306, 'frFR', 'Vous n\’avez jamais vu le grand Akunda ? Vous ne pouviez pas mieux tomber !', '', 28153),
(131305, 'frFR', 'J\’ai fort à faire avant l\’arrivée d\’Akunda ! Le temps presse... Il n\’y a pas un instant à perdre !', '', 28153),
(131304, 'frFR', 'Vous avez vu Hakasi ?', 'Vous avez vu Hakasi ?', 28153),
(131303, 'frFR', 'Cela fait des années que notre peuple n\’a plus invoqué Akunda. J\’ai hâte d\’être à nouveau en sa présence !', '', 28153),
(131302, 'frFR', '%s dévore chaque morceau avec entrain, puis éructe une flamme !', '', 28153),
(131300, 'frFR', '%s dévore bruyamment la plante.', '', 28153),
(131299, 'frFR', 'Enfin un vrai combat !\n\nCes idiots de la Horde cherchent à franchir le gouffre là-bas afin d\’investir le quartier général avancé. Vous savez ce que j\’en pense, moi ?\n\nQU\’ILS ESSAIENT POUR VOIR ! Voilà, ce que j\’en pense.\n\nVenez. Allons écraser ces misérables cloportes.', '', 28153),
(131298, 'frFR', '', 'Je suis bien contente de vous voir, soldat. Nous sommes en fâcheuse posture, je le crains !\n\nFort-Triomphe est un goulet d\’étranglement qu\’il faut passer pour assiéger les portes. Avec les renforts venus d\’Orgrimmar qui assaillent sans relâche le gouffre au nord, si nous ne tenons pas nos positions, tous nos convois en provenance de Theramore seront menacés.', 28153),
(131297, 'frFR', 'Comme vous voulez, maître Higashi...', '', 28153),
(131296, 'frFR', 'Goûter la nourriture et « préparer le festin » sont deux choses bien différentes. Je ne te le demanderai pas deux fois, Rifu.', '', 28153),
(131295, 'frFR', 'Mais j\’ai déjà tout le festin à préparer !', '', 28153),
(131294, 'frFR', 'Hakasi tarde à nous apporter les dernières offrandes. Va donc les chercher avec notre $gnouvel ami:nouvelle amie;, veux-tu ?', '', 28153),
(131293, 'frFR', 'Oui, maître Higashi !', '', 28153),
(131292, 'frFR', 'Rifu ! On a de la visite. Viens, que je te présente.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(131291, 'frFR', 'Sans elles, nous ne pourrons pas invoquer le Loa. Peut-être pourriez-vous nous aider...', '', 28153),
(131290, 'frFR', 'Il est presque temps d\’accomplir le rituel, mais nous attendons toujours la plupart des offrandes requises.', '', 28153),
(131289, 'frFR', 'Vous trouverez les tablettes antiques dans le temple. La légende d\’Akunda vous attend.', '', 28153),
(131255, 'frFR', 'Puissions-nous toujours rendre hommage au grand lézard-tonnerre, afin qu\’il veille à jamais sur cette jungle.', '', 28153),
(131254, 'frFR', '', 'Bien. L\’heure, elle est venue de choisir un œuf, novice. Vous saurez si votre jeune compagnon vous accepte quand vous entendrez sa voix dans votre tête…', 28153),
(131250, 'frFR', '', '<La matriarche Jaz\’lith vous observe pensivement.>', 28153),
(131249, 'frFR', '', 'La voilà. Un parfait mélange de grâce et de férocité, pas vrai ? Défiez-la si vous osez.', 28153),
(131248, 'frFR', '', 'Ce monument est ancien, mais il ressemble en tout point aux sanctuaires dédiés à Bwonsamdi à Zuldazar.', 28153),
(131247, 'frFR', 'Mon navrecorne et moi, on est ensemble depuis qu\’il a éclos. On ne fait qu\’un au combat.', 'Mon navrecorne et moi, on est ensemble depuis qu\’il a éclos. On ne fait qu\’un au combat.', 28153),
(131246, 'frFR', 'Pour devenir mande-bête, il faut une bonne dose de talent et une patience infinie. Les jeunes navrecornes, ils nous donnent pas mal de fil à retordre, vous savez !', 'Pour devenir mande-bête, il faut une bonne dose de talent et une patience infinie. Les jeunes navrecornes, ils nous donnent pas mal de fil à retordre, vous savez !', 28153),
(131245, 'frFR', 'Voilà pourquoi nous avons érigé en ce lieu précis un temple en l\’honneur d\’Akunda. Puissions-nous ne plus jamais oublier le grand Loa.', '', 28153),
(131244, 'frFR', 'Nous osâmes alors gagner le sommet de la montagne d\’où nous découvrîmes le corps sans vie de Zul\’khan. Mais Akunda avait disparu.', '', 28153),
(131243, 'frFR', 'Leur lutte nous sembla d\’abord condamnée à durer éternellement, mais la poussière finit par retomber et la terre retrouva son calme…', '', 28153),
(131242, 'frFR', 'Akunda était de retour ! Quelques instants plus tard, les deux bêtes se livraient un combat sans merci. Chacun de leurs coups faisait trembler la terre !', '', 28153),
(131241, 'frFR', 'Alors que tout espoir semblait perdu, un rugissement terrifiant retentit dans le canyon et une silhouette se dessina au sommet des falaises, masquant le clair de lune.', '', 28153),
(131240, 'frFR', 'Mais malgré l\’ardeur de nos attaques, Zul\’khan se révéla trop puissant ! Il parvint à se libérer… et l\’enfer s\’abattit sur nous.', '', 28153),
(131239, 'frFR', 'C\’est ainsi que Zul\’khan fut attiré dans le canyon où nous l\’attendions en embuscade avec un immense filet…', '', 28153),
(131238, 'frFR', 'Les anciens des tribus décidèrent alors de tenir conseil dans le cœur de Vol\’Aman. Allions-nous faire front et nous battre côte à côte ? Ou prendre ce que nous pouvions emporter et fuir la jungle ? Nous décidâmes de nous battre !', '', 28153),
(131237, 'frFR', 'Zul\’khan se trouva ainsi libre de terroriser toute la région. Il traqua et massacra mon peuple sans aucune retenue. Une bien triste époque…', '', 28153),
(131236, 'frFR', 'Nos offrandes au grand lézard-tonnerre cessèrent et Akunda finit par quitter la jungle…', '', 28153),
(131235, 'frFR', 'Longtemps, Akunda nous protégea du terrifiant Zul\’khan, mais au fil du temps, mon peuple devint négligent.', '', 28153),
(131234, 'frFR', 'Jaloux de la puissance du Loa, le diablosaure Zul\’khan rôdait lui aussi dans la jungle ténébreuse, toujours à l\’affût de nouvelles proies qu\’il tuait pour le plaisir.', '', 28153),
(131233, 'frFR', 'Toutes les créatures de la jungle vénéraient sa puissance majestueuse. Toutes, à l\’exception du tyrannique Zul\’khan…', '', 28153),
(131232, 'frFR', 'Il y a fort longtemps de cela, mon peuple partageait la jungle en toute humilité avec le grand lézard-tonnerre.', '', 28153),
(131231, 'frFR', 'Moi, Zen\’gaji, chef de ma tribu et architecte de ce temple, je dédie mon œuvre au puissant Akunda.', '', 28153),
(131230, 'frFR', 'Je m\’entraîne pour devenir mande-bête depuis ma naissance. Et vous, c\’est quoi, votre spécialité ?', 'Je m\’entraîne pour devenir mande-bête depuis ma naissance. Et vous, c\’est quoi, votre spécialité ?', 28153),
(131229, 'frFR', 'Battons-nous !', 'Battons-nous !', 28153),
(131228, 'frFR', '', 'Zandalar pour toujours !', 28153),
(131227, 'frFR', '', 'Les Loas sont à mes côtés !', 28153),
(131226, 'frFR', '', 'Pour Zuldazar !', 28153),
(131224, 'frFR', '', 'Rakera était mon commandant, le meilleur que cette cité ait connu.', 28153),
(131223, 'frFR', 'Moi, je pose pas de questions. Je suis les ordres. Et vous feriez mieux de suivre mon exemple.', '', 28153),
(131222, 'frFR', 'Accouchez, $n. Je suis pas payé pour papoter, moi.', '', 28153),
(131221, 'frFR', '', 'Vous voulez mourir ou quoi ? Le général a des yeux et des oreilles partout.', 28153),
(131220, 'frFR', '', 'Quoi que vous cherchiez, faites vite.', 28153),
(131218, 'frFR', '', 'Et, comme vous pouvez le voir, je suis pas la seule à penser ça.', 28153),
(131215, 'frFR', '', 'Vous, là ! Il paraît que vous arrêtez pas de poser des questions sur le général.', 28153),
(131214, 'frFR', '', 'Les dunes, c\’est une condamnation à mort. Je ne laisserai pas Rakera mourir là-bas !', 28153),
(131213, 'frFR', '', 'Ce qu\’elle a découvert là-bas, ça lui a valu un aller simple pour le désert.', 28153),
(131212, 'frFR', '', 'Elle m\’a dit qu\’elle n\’était pas loin de prouver que le général Jakra\’zet est un traître… Et puis elle a disparu.', 28153),
(131211, 'frFR', '', 'Venez avec moi, mais évitez d\’attirer l\’attention.', 28153),
(131210, 'frFR', 'Que pouvez-vous me dire au sujet du général Jakra\’zet ?', 'Que pouvez-vous me dire au sujet du général Jakra\’zet ?', 28153),
(131209, 'frFR', '', 'Qu\’est-ce que je peux faire pour vous ?', 28153),
(131208, 'frFR', 'Désolé que vous ayez été mêlés à tout ça. Au moins, z\’allez rencontrer Bwonsamdi, comme vous le vouliez ! Hé hé !', '', 28153),
(131207, 'frFR', 'Vous avez assuré. Cette âme-ci, elle fera une sacrée offrande pour Bwonsamdi !', '', 28153),
(131206, 'frFR', 'Bon sang, ils m\’ont trouvé ! Hé, aidez-moi et je verrai ce que j\’peux faire pour vous.', '', 28153),
(131205, 'frFR', 'Aux armes !', '', 28153),
(131204, 'frFR', '', 'Maréchal, non !', 28153),
(131203, 'frFR', '$gLâchez-le:Lâchez-la;, espèce de…', '', 28153),
(131202, 'frFR', '', 'Attention !', 28153),
(131201, 'frFR', 'Masse, Yorrick, parcourez le périmètre et cherchez…', '', 28153),
(131200, 'frFR', '', 'Vous pensez qu\’elle est allée… par là ?', 28153),
(131199, 'frFR', 'Je ne comprends pas. Le chemin part pourtant dans cette direction…', '', 28153),
(131198, 'frFR', 'C\’est une voie sans issue…', '', 28153),
(131197, 'frFR', '', 'Qu\’est-ce que… c\’est que cet endroit ?', 28153),
(131196, 'frFR', 'Je distingue un bâtiment à l\’horizon. Jaina s\’y dirigeait probablement !', '', 28153),
(131195, 'frFR', 'Ces créatures nous barrent la route. Forcez le passage !', '', 28153),
(131194, 'frFR', 'Nous devons nous enfoncer dans la forêt ! En formation !', '', 28153),
(131193, 'frFR', 'On dirait de la magie du Givre… Jaina doit être passée par là !', '', 28153),
(131192, 'frFR', 'Bon sang ! On va devoir continuer sans lui… Attendez, qu\’est-ce que c\’est ?', '', 28153),
(131191, 'frFR', 'Chef ! Pas la moindre trace de Notley et impossible de suivre une piste dans cette tempête !', '', 28153),
(131190, 'frFR', 'Cela ne me dit rien qui vaille…', '', 28153),
(131189, 'frFR', '', 'Qu\’est-ce que…', 28153),
(131188, 'frFR', 'Vite, ils sont partis par là !', '', 28153),
(131187, 'frFR', '', 'Une embuscade !', 28153),
(131186, 'frFR', 'Aaaaaïïe !', '', 28153),
(131185, 'frFR', 'Notley, non !', '', 28153),
(131184, 'frFR', 'Attendez… je crois que je vois quelque chose…', '', 28153),
(131183, 'frFR', 'Venez, nous devrions nous remettre en route.', '', 28153),
(131182, 'frFR', 'J\’aimerais le croire. Malheureusement, je pense que des forces bien plus sombres sont à l\’œuvre ici.', '', 28153),
(131181, 'frFR', '', 'On dirait que ces bois ne sont pas seulement peuplés de bêtes. Une exilée pourrait-elle être à l\’origine de tout ceci ?', 28153),
(131180, 'frFR', 'Halte ! Qu\’est-ce que c\’est ?', '', 28153),
(131179, 'frFR', 'Cela ne présage rien de bon…', '', 28153),
(131178, 'frFR', 'Les bêtes se montrent de plus en plus téméraires et attaquent en terrain dégagé comme ici.', '', 28153),
(131177, 'frFR', 'Qu\’est-ce que c\’est ? Soyez sur vos gardes, soldats !', '', 28153),
(131176, 'frFR', 'Suivez-moi !', '', 28153),
(131175, 'frFR', 'Fourbissez vos armes et préparez-vous au pire. Ce soir, nous chevauchons dans les ténèbres !', '', 28153),
(131174, 'frFR', 'Les bêtes de ces forêts n\’apprécient pas de… n\’apprécient rien du tout, en fait.', '', 28153),
(131173, 'frFR', 'La tempête va réduire notre visibilité. Restez groupés et ne vous écartez pas du chemin.', '', 28153),
(131172, 'frFR', 'Je suis prêt à m\’entraîner.', 'Je suis prête à m\’entraîner.', 28153),
(131171, 'frFR', 'Ici, on dresse des bêtes de toutes les tailles et de toutes les races. Même les animaux de bât, il faut les entraîner au combat !', '', 28153),
(131170, 'frFR', 'Nous allons emprunter le chemin en direction de Funesterre, c\’est dans cette direction que la caravane d\’exilés devait se rendre.', '', 28153),
(131169, 'frFR', '', 'Les esprits… m\’abandonnent…', 28153),
(131168, 'frFR', '', 'Arrgh !!', 28153),
(131167, 'frFR', '', 'Je… peux plus…', 28153),
(131166, 'frFR', '', 'Vous nous vaincrez jamais ! De mon dernier souffle, j\’vous maudis tous ! On se retrouvera de l\’Autre côté !', 28153),
(131165, 'frFR', '', 'Le lien entre la bête et son cavalier, il passe par un fétiche. Touchez notre saurite dès que vous serez $gprêt:prête;.', 28153),
(131158, 'frFR', 'Au nom d\’Akunda, le grand Loa, je vous souhaite la bienvenue dans ce temple, $gvoyageur:voyageuse;.', '', 28153),
(131148, 'frFR', '', 'Vous vous battez bien. Mes petits seront en sécurité avec vous.', 28153),
(131142, 'frFR', '', 'Mes petits méritent ce qui se fait de mieux !', 28153),
(131115, 'frFR', 'À l\’attaque, les gars !', '', 28153),
(131114, 'frFR', 'Lâches ! Envoyez-nous votre meilleur champion, qu\’on voie ce qu\’il a dans le ventre !', '', 28153),
(131113, 'frFR', 'Voyons ce que la Horde nous réserve, voulez-vous ?', '', 28153),
(131112, 'frFR', '', 'Votre sang, il va couler !', 28153),
(131111, 'frFR', '', 'Cette fois, je vous tiens, Hanzabu ! Vous allez payer pour la mort de mes sœurs !', 28153),
(131109, 'frFR', 'Nous sommes à la recherche du Loa Bwonsamdi.', 'Nous sommes à la recherche du Loa Bwonsamdi.', 28153),
(131108, 'frFR', 'On dirait que le pire est derrière nous. Prenons le temps de souffler un peu avant de continuer.', '', 28153),
(131107, 'frFR', 'Bien joué, ces troupes seront un atout inestimable pour notre effort de guerre.', '', 28153),
(131106, 'frFR', 'Repos, soldats. Nous allons attendre ici quelques instants avant de lancer la manœuvre.', '', 28153),
(131105, 'frFR', 'Soldats de l\’Alliance ! Escortez ce convoi jusqu\’au quartier général avancé !', '', 28153),
(131098, 'frFR', 'Ces griffes… ces crocs… Ils hanteront mes nuits pendant longtemps.', 'Ces griffes… ces crocs… Ils hanteront mes nuits pendant longtemps.', 28153),
(131097, 'frFR', 'Vous tombez à pic !', 'Vous tombez à pic !', 28153),
(131096, 'frFR', 'J\’ai bien cru que c\’était la fin. Merci !', 'J\’ai bien cru que c\’était la fin. Merci !', 28153),
(131094, 'frFR', 'Vous êtes pas tout $Ucrotté:crottée; et vous sentez même pas mauvais.$b$bVous êtes qui pour errer dans les marais ?', '', 28153),
(131093, 'frFR', 'Vous êtes qui, vous ? L\’odeur des Trolls de sang, vous l\’avez pas…', '', 28153),
(131088, 'frFR', '', 'Ouaiiis ! Ça va être le meilleur goûter de ma vie ! Allons chercher les autres invités.', 28153),
(131087, 'frFR', 'Vous lui voulez quoi, à Hanzabu ?', '', 28153),
(131086, 'frFR', '', 'Latrompe ! Tu sais bien que dame Mary ne veut pas te voir dans la maison ! Tu mets de la boue partout !', 28153),
(131085, 'frFR', '', 'M. Mangetout ! Tu avais faim… Viens avec moi, on va prendre le goûter.', 28153),
(131081, 'frFR', '', 'Méchant maire Striggs ! Toujours à fuir tes responsabilités envers les habitants ! Tu ne peux plus t\’échapper maintenant !', 28153),
(131080, 'frFR', '', 'Je lui fais pas confiance. On devr…', 28153),
(131079, 'frFR', 'Silence ! Assez pleurniché !', '', 28153),
(131078, 'frFR', '', 'Arrgh !', 28153),
(131077, 'frFR', 'Hmmm ouais, celui-ci va faire une très belle offrande !', '', 28153),
(131057, 'frFR', '$n a défendu la scierie !', '', 28153),
(131056, 'frFR', 'L\’Alliance a pris le contrôle de l\’épave !', '', 28153),
(131055, 'frFR', 'La Horde a pris le contrôle de l\’épave !', '', 28153),
(131054, 'frFR', '$n a attaqué l\’épave !', '', 28153),
(131049, 'frFR', 'La Horde a déployé un char sur la route du fort de Guet-du-Nord ! Il faut le détruire !', 'La Horde a déployé un char sur la route du fort de Guet-du-Nord ! Il faut le détruire !', 28153),
(131048, 'frFR', 'Scénario terminé.', 'Scénario terminé.', 28153),
(131033, 'frFR', '', 'Dégagez un chemin pour la 7e flotte ! Nous commencerons à monter dès que les renforts seront arrivés !', 28153),
(131032, 'frFR', 'Test', '', 28153),
(131030, 'frFR', '', 'Visez-moi ça, mec ! La piste du mojo, elle mène vers le nord, faut la suivre.', 28153),
(131025, 'frFR', '', 'Quelles nouvelles rapportez-vous du nord ?', 28153),
(131010, 'frFR', '', 'Mmm… un sacrifice, et le corps, il est encore frais. Le mojo du rituel a laissé une trace. Voyons où ça nous mène.', 28153),
(131009, 'frFR', 'Une petite dague est plantée dans le dos du corps.', 'Une petite dague est plantée dans le dos du corps.', 28153),
(131008, 'frFR', '', 'Je sens une forte présence au nord. Faut aller voir ça.', 28153),
(131007, 'frFR', '', 'Cette offrande, elle était pas là quand j\’ai découvert cet endroit. On dirait que Bwonsamdi, il a encore un fidèle ici.', 28153),
(131000, 'frFR', 'Le climat aride de Nazmir a effacé la plupart des inscriptions gravées sur ces tablettes. Seuls les mots « louer », « esprit » et « tombe » sont lisibles.', 'Le climat aride de Nazmir a effacé la plupart des inscriptions gravées sur ces tablettes. Seuls les mots « louer », « esprit » et « tombe » sont lisibles.', 28153),
(130979, 'frFR', 'Nos éclaireurs nous signalent que les troupes de la Horde marchent sur Guet-du-Nord à la faveur de la nuit. Nous avons besoin de votre aide, et vite !', '', 28153),
(130978, 'frFR', '', 'Soldats de l\’Alliance, voici venir l\’instant de vérité ! Notre assaut contre la Grande porte de Mulgore commence ici et maintenant. Serrez les rangs, et battez-vous jusqu\’au bout !', 28153),
(130977, 'frFR', '', 'Tous sur les quais !', 28153),
(130969, 'frFR', '', 'Ah, vous voilà, $p. Tout comme G\’huun, il me l\’avait murmuré. Je sens que ça va me plaire !', 28153),
(130967, 'frFR', '', 'Soldats de la 7e flotte, l\’heure est venue de sonner la charge. Rassemblez votre équipement et tenez-vous prêts à faire mouvement.', 28153),
(130947, 'frFR', 'Personne se rend compte que je meurs de faim ?', '', 28153),
(130946, 'frFR', 'Maman, c\’est quand qu\’on mange ?!', '', 28153),
(130945, 'frFR', '%s vous donne un coup de tête amical.', '', 28153),
(130944, 'frFR', '', 'La mort ne m\’arrêtera pas.', 28153),
(130943, 'frFR', 'Et si on jouait ? Vous, vous courez, et moi, j\’essaie de vous attraper pour vous manger !', '', 28153),
(130940, 'frFR', '%s vous regarde d\’un air plaintif.', '', 28153),
(130939, 'frFR', '%s se met à gémir comme un affamé.', '', 28153),
(130938, 'frFR', '%s gémit et vous donne un coup de museau insistant.', '', 28153),
(130937, 'frFR', 'L\’estomac |2 %s gargouille bruyamment.', '', 28153),
(130936, 'frFR', '%s vous donne un coup de museau affectueux.', '', 28153),
(130935, 'frFR', '', 'On est trop nombreux pour vous. Dazar\’alor va tomber !', 28153),
(130934, 'frFR', 'Je vais faire évacuer mes blessés. Retrouvez-nous à Raz\’lotec quand vous aurez terminé et on mettra un terme à ce siège.', '', 28153),
(130932, 'frFR', 'Éclosion…', 'Éclosion…', 28153),
(130931, 'frFR', '', 'J\’vais vous éventrer !', 28153),
(130930, 'frFR', '', 'J\’vais vous écorcher !', 28153),
(130929, 'frFR', '', 'Plus de sang ! Plus de sang !', 28153),
(130928, 'frFR', '', 'Ma\’da, elle a besoin de vot\’ sang !', 28153),
(130927, 'frFR', '', 'Sympas, ces ossements.', 28153),
(130926, 'frFR', '', 'De la chair fraîche, du sang tiède.', 28153),
(130925, 'frFR', 'Argh ! Ça va me prendre des jours pour guérir tout ça.', 'Argh ! Ça va me prendre des jours pour guérir tout ça.', 28153),
(130924, 'frFR', 'Sales brutes de Trolls de sang !', 'Sales brutes de Trolls de sang !', 28153),
(130923, 'frFR', 'Ha ! Mon sang, c\’est pas aujourd\’hui que vous l\’aurez.', 'Ha ! Mon sang, c\’est pas aujourd\’hui que vous l\’aurez.', 28153),
(130922, 'frFR', 'Ils ont dit qu\’ils allaient se servir de mon sang.', 'Ils ont dit qu\’ils allaient se servir de mon sang.', 28153),
(130921, 'frFR', 'Ha ! C\’est pas aujourd\’hui que vous m\’aurez, bande de sauvages.', 'Ha ! C\’est pas aujourd\’hui que vous m\’aurez, bande de sauvages.', 28153),
(130920, 'frFR', 'Ils étaient sur le point d\’accomplir un rituel. Même que mes os, je les ai sentis bouger sous ma peau.', 'Ils étaient sur le point d\’accomplir un rituel. Même que mes os, je les ai sentis bouger sous ma peau.', 28153),
(130919, 'frFR', 'Ces sauvages, ils m\’ont gravé tout un tas de symboles sur le bras.', 'Ces sauvages, ils m\’ont gravé tout un tas de symboles sur le bras.', 28153),
(130918, 'frFR', 'Ouais ! C\’est pas aujourd\’hui qu\’ils m\’auront, foi de Troll !', 'Ouais ! C\’est pas aujourd\’hui qu\’ils m\’auront, foi de Trollesse !', 28153),
(130917, 'frFR', 'Merci ! Merci beaucoup !', 'Merci ! Merci beaucoup !', 28153),
(130915, 'frFR', 'Cessez le feu. V\’là les renforts qui rappliquent !', '', 28153),
(130914, 'frFR', '', 'Faut y aller, mec. La chasse, elle est ouverte !', 28153),
(130913, 'frFR', '', 'Venez ! L\’éclosion, elle va pas tarder.', 28153),
(130907, 'frFR', 'Je suis prêt.', 'Je suis prête.', 28153),
(130906, 'frFR', '', 'Bienvenue au kraal des Bêtes de guerre, $n.\n\nJ\’ai entendu parler de votre Horde et je sais que vous êtes là pour parlementer avec le vieux Rastakhan.\n\nOn va voir si vous savez vous rendre utile. Si c\’est le cas, on plaidera peut-être en votre faveur dans les hautes sphères de Dazar, hein ?', 28153),
(130905, 'frFR', 'Si je trouve celui qui t\’a fait ça, mon pauvre…', '', 28153),
(130904, 'frFR', 'Les Trolls de sang, ils se battent pas à la loyale.', '', 28153),
(130903, 'frFR', 'C\’est de la magie ténébreuse, ça. C\’est pas naturel.', '', 28153),
(130902, 'frFR', 'Quel mauvais sort ils t\’ont lancé, mon pauvre vieux ?', '', 28153),
(130901, 'frFR', 'Allez, mon vieux. Tu peux t\’en sortir.', '', 28153),
(130900, 'frFR', 'Serrez les rangs ! Évacuez les morts et les blessés, mais surtout, serrez les rangs.', '', 28153),
(130899, 'frFR', 'Attention là-haut ! Encore des gorgesang en approche.', '', 28153),
(130898, 'frFR', 'Vous êtes des Zandalari, alors battez-vous en Zandalari !', '', 28153),
(130897, 'frFR', 'Aidez les blessés ! Ne laissez personne à la merci de ces sauvages.', '', 28153),
(130896, 'frFR', 'Tenez bon, frangins et frangines ! Ces sauvages, ils auront pas not\’ peau, pas aujourd\’hui !', '', 28153),
(130842, 'frFR', 'Conférer une amélioration à tout le monde.', 'Conférer une amélioration à tout le monde.', 28153),
(130841, 'frFR', '', 'Vous êtes peut-être plus coriace que vous en avez l\’air, mais mon champion, il ne vous fera pas de cadeau. Défiez-le quand vous vous sentirez d\’attaque.', 28153),
(130840, 'frFR', '', 'Évidemment, à vaincre un novice on triomphe sans gloire. Voyons plutôt comment vous vous en sortez face à un adversaire plus coriace.', 28153),
(130839, 'frFR', 'Je peux vous fournir différentes améliorations et commodités pour vous aider sur le front de guerre.', '', 28153),
(130838, 'frFR', '', 'Vous tenez vraiment à prendre un tel engagement ? Il n\’est pas trop tard pour changer d\’avis.', 28153),
(130822, 'frFR', 'De nouveaux généraux ont été promus !', 'De nouveaux généraux ont été promus !', 28153),
(130797, 'frFR', '', 'Z\’avez de la suite dans les idées, faut le reconnaître. Le temps, il est venu de rencontrer la matriarche Jaz\’lith. Venez donc.', 28153),
(130796, 'frFR', '', 'Vous êtes $Udisposé:disposée; à faire passer les besoins de votre jeune compagnon avant les vôtres ? Vous avez une idée de la quantité de nourriture qu\’ils avalent chaque jour ?', 28153),
(130795, 'frFR', 'Le lien qui nous unit à nos bêtes, il se tisse dès l\’éclosion et il dure jusqu\’à la mort. On forme une famille.', 'Le lien qui nous unit à nos bêtes, il se tisse dès l\’éclosion et il dure jusqu\’à la mort. On forme une famille.', 28153),
(130794, 'frFR', '', 'Les navrecornes sont herbivores. Ne vous avisez pas de lui donner de la viande !', 28153),
(130793, 'frFR', 'Les jeunes, ils ne se lient pas avec n\’importe qui. Pourquoi est-ce qu\’il a choisi quelqu\’un comme vous ? Je dois dire que ça m\’en bouche un coin !', 'Les jeunes, ils ne se lient pas avec n\’importe qui. Pourquoi est-ce qu\’il a choisi quelqu\’un comme vous ? Je dois dire que ça m\’en bouche un coin !', 28153),
(130732, 'frFR', '', 'Ah, Hir\’eek, le Loa chauve-souris… Il doit se trouver quelque part en Nazmir. C\’est un malin… Il doit savoir comment arrêter tout ça.', 28153),
(130731, 'frFR', '', 'Je ressens son pouvoir… Il est proche. Plus que tous les autres Loas.', 28153),
(130730, 'frFR', '', 'Bwonsamdi… le Loa de la mort. Il est puissant, mais dangereux… Toujours à marchander ses services.', 28153),
(130710, 'frFR', '', 'Le Loa grenouille, Krag\’wa… Il se trouve en Nazmir ! C\’est un puissant Loa qui ne tolérera pas ces maudits Trolls de sang.', 28153),
(130707, 'frFR', 'Donc, on va faire un marché avec le Loa de la mort, le Loa tortue, le Loa chauve-souris et le Loa grenouille… Tout ça pour arrêter les Trolls de sang.', '', 28153),
(130705, 'frFR', '', 'Il nous faut plus de puissance pour arrêter les Trolls de sang, ce qui ne nous laisse qu\’une seule option : les Loas de Nazmir.', 28153),
(130692, 'frFR', '', '<Elle vous dévisage d\’un air... lubrique.>', 28153),
(130625, 'frFR', '', 'Talanji parle de se battre pour obtenir un maigre soutien de la part de ses contacts à Zuldazar, et le personnage-joueur cherche l\’aide de Loas oubliés.', 28153),
(130566, 'frFR', '', 'SCÈNE DE TRANSITION/SURVOL. Vous voyez le super-assemblage de Titan corrompu ! La matriarche de sang vous aperçoit et lance un sort de capture sur Talanji !', 28153),
(130494, 'frFR', '', 'Enfin libre ! Il faut y aller, montez !', 28153),
(130490, 'frFR', '', 'Voilà d\’autres soldats, mais la route continue. Nous devons faire de même.', 28153),
(130485, 'frFR', '', 'Mon peuple… massacré ! Vous voyez contre qui on se bat, maintenant, $n. Les Trolls de sang, ce sont des monstres !', 28153),
(130383, 'frFR', '', 'Tu es de bon conseil, Rokhan, mais le moment d\’agir est arrivé. Il faut arrêter ces Trolls de sang.', 28153),
(130372, 'frFR', '', 'Soyez rapide et sans pitié. Zul et moi, nous vous attendrons sur les marches de la pyramide. Vous ne pouvez pas la manquer.', 28153),
(130361, 'frFR', '', 'Si vous en réchappez, retrouvez-nous à l\’entrée de l\’allée des Tonneliers. J\’aurai peut-être une tâche à vous confier.', 28153),
(130353, 'frFR', 'J\’avais encore jamais mis les pieds en Zandalar, mais faut bien reconnaître que ça vaut le détour, surtout Zuldazar. Y a pas à dire, le spectacle, il est vraiment grandiose.$b$bEnfin bref, surveillez vos arrières. Les Zandalari, ils ont beau avoir l\’air bien sous tous rapports, ça reste des Trolls. Et la faiblesse, elle a pas sa place dans la société trolle.', '', 28153),
(130352, 'frFR', 'La princesse Talanji, elle vous attend au bout de ces quais. Ne traînez pas en route et n\’entrez pas dans la ville avant la fin des rituels, ou vous le paierez de votre vie.\n\nQuant au cadavre ambulant, il ne bouge pas d\’ici jusqu\’à nouvel ordre du roi.', '', 28153),
(130121, 'frFR', '', 'Qu\’il en soit ainsi.', 28153),
(130120, 'frFR', 'Vous répondrez de vos crimes envers Kul Tiras devant elle.', '', 28153),
(130119, 'frFR', 'Nous allons vous conduire auprès de Katherine.', '', 28153),
(130099, 'frFR', '<Brève discussion au cours de laquelle je me moque de Zul et je le rabaisse et je dis à ma fille qu\’elle a abandonné son poste.>', '', 28153),
(130096, 'frFR', 'Vous devez savoir que notre roi, il a survécu à cent vingt-trois tentatives d\’assassinat.$b$bLes têtes des coupables ornent la salle du trône.', '', 28153),
(130081, 'frFR', '', 'Vous voulez voir le roi ? Alors, z\’avez qu\’à frapper le gong et on vous trouvera un défi digne de ce nom.', 28153),
(130079, 'frFR', '', 'Prenez votre bénédiction et disparaissez. Si vous remettez les pieds ici, vous pourrez dire adieu à la vie.', 28153),
(130075, 'frFR', '', 'Comment il va, Vol\’jin ? On raconte qu\’il est mort. C\’est dommage. On était quelques-uns à rêver de lui régler son compte nous-mêmes.', 28153),
(130032, 'frFR', 'Parlez et pis fichez le camp, $r. Les Amani, ils ont pas oublié que c\’est votre Horde qu\’a assassiné notre bien-aimé Zul\’jin.\n\nPar respect envers les Zandalari, j\’aime autant vous prévenir : z\’êtes en territoire amani, dans cette ambassade. Traînez pas trop ici, ou vous repartirez pas.', '', 28153),
(130031, 'frFR', 'Prenez-la, vot\’ bénédiction de malheur, et fichez le camp. Y a pas de place pour la Horde chez les Amani.', '', 28153),
(130030, 'frFR', 'C\’est brave, mais z\’avez pas idée de ce qui vous attend. Battez chacun de nos disciples, là derrière moi, et vous pourrez repartir avec notre bénédiction en prime.', '', 28153),
(130003, 'frFR', '', '.', 28153),
(129998, 'frFR', '', 'Je suis Jaina Portvaillant. Je souhaite obtenir une audience avec l\’amiral suprême, Katherine Portvaillant… ma mère.', 28153),
(129993, 'frFR', '', 'Espérons que tout se passe bien.', 28153),
(129983, 'frFR', 'Ah ! Non ! Gahz\’ragon ! Sale brute de la Horde ! Tenez, la voilà, vot\’ bénédiction ! Maintenant, fichez le camp d\’ici !', '', 28153),
(129980, 'frFR', 'Beaucoup de choses ont changé pendant votre absence, votre altesse. Rakera était trop faible pour son poste, alors j\’ai décidé de l\’envoyer en exil en Vol\’dun.', '', 28153),
(129979, 'frFR', '', 'Jakra\’zet. Où est le garde de guerre Rakera ?', 28153),
(129978, 'frFR', 'Vous n\’irez pas plus loin, rebut de la Horde.', '', 28153),
(129969, 'frFR', '[Écran de chargement -> IGC - Bateau en haute mer, cauchemar de Jaina, arrivée aux portes de Boralus.]', '[Écran de chargement -> IGC - Bateau en haute mer, cauchemar de Jaina, arrivée aux portes de Boralus.]', 28153),
(129968, 'frFR', 'Voulez relever not\’ défi, c\’est ça ? Z\’allez en avoir pour votre or. Le gong, là-bas, sonnez-le et vous en prendrez plein la vue.', '', 28153),
(129967, 'frFR', '<Lancer le défi.>', '<Lancer le défi.>', 28153),
(129966, 'frFR', 'Tiens, tiens, salut, $r. On peut dire que votre peuple, il a bien pourri la vie du mien, dans le passé. Alors, vous voulez quoi, au juste ?', '', 28153),
(129965, 'frFR', 'L\’Alliance va pas en rester là !', 'L\’Alliance va pas en rester là !', 28153),
(129964, 'frFR', 'Notre roi va en entendre parler !', 'Notre roi va en entendre parler !', 28153),
(129963, 'frFR', 'Vous avez gagné... pour cette fois.', 'Vous avez gagné... pour cette fois.', 28153),
(129962, 'frFR', 'Vous ne vous en tirerez pas comme ça.', 'Vous ne vous en tirerez pas comme ça.', 28153),
(129961, 'frFR', 'On reviendra !', 'On reviendra !', 28153),
(129960, 'frFR', 'Vous avez pas fini d\’entendre parler de nous, $p !', 'Vous avez pas fini d\’entendre parler de nous, $p !', 28153),
(129959, 'frFR', 'Saleté |2 $c !', 'Saleté |2 $c !', 28153),
(129958, 'frFR', 'À mort !', 'À mort !', 28153),
(129957, 'frFR', 'J\’ai entendu parler de vous, $p ! Je vais devenir une légende en vous trucidant.', 'J\’ai entendu parler de vous, $p ! Je vais devenir une légende en vous trucidant.', 28153),
(129956, 'frFR', 'Je partirai pas tant que vous respirerez encore.', 'Je partirai pas tant que vous respirerez encore.', 28153),
(129955, 'frFR', 'Les Zandalari, ils pourront pas s\’allier avec un cadavre.', 'Les Zandalari, ils pourront pas s\’allier avec un cadavre.', 28153),
(129954, 'frFR', 'Z\’allez pas vous débarrasser de moi aussi facilement !', 'Z\’allez pas vous débarrasser de moi aussi facilement !', 28153),
(129953, 'frFR', 'Racaille de la Horde !', 'Racaille de la Horde !', 28153),
(129952, 'frFR', 'Aucune vermine de la Horde pactisera avec les Zandalari.', 'Aucune vermine de la Horde pactisera avec les Zandalari.', 28153),
(129951, 'frFR', 'La princesse a ordonné votre bannissement. Partez, ou c\’est la mort qui vous attend.', 'La princesse a ordonné votre bannissement. Partez, ou c\’est la mort qui vous attend.', 28153),
(129950, 'frFR', 'Bas les pattes, raclure de la Horde.', 'Bas les pattes, raclure de la Horde.', 28153),
(129949, 'frFR', 'Tiens, tiens. Quelqu\’un de la Horde, ici, à Zuldazar. Voilà qui est très intéressant.', 'Tiens, tiens. Quelqu\’un de la Horde, ici, à Zuldazar. Voilà qui est très intéressant.', 28153),
(129948, 'frFR', 'Vous aussi, vous voulez ce truc ? Pas de bol, je l\’ai vu en premier, vous arrivez trop tard.', 'Vous aussi, vous voulez ce truc ? Pas de bol, je l\’ai vu en premier, vous arrivez trop tard.', 28153),
(129947, 'frFR', 'Qu\’est-ce que vous me voulez ? J\’ai pas que ça à faire.', 'Qu\’est-ce que vous me voulez ? J\’ai pas que ça à faire.', 28153),
(129946, 'frFR', 'Quoi encore, vermine de la Horde ?', 'Quoi encore, vermine de la Horde ?', 28153),
(129944, 'frFR', '', 'Je dois préparer mon navire. Héraut, rejoignez-moi au port quand vous souhaiterez partir.', 28153),
(129940, 'frFR', 'Que les choses soient bien claires entre nous, $gétranger:étrangère; : si vous cherchez la bagarre, c\’est dehors que ça se passe.\n\nRespectez ça, et vous pouvez dormir ici.\n\nEt si vous voyez un truc louche, vous avisez pas de me balancer.', '', 28153),
(129883, 'frFR', 'Aucun étranger n\’entre à Zuldazar sans que je goûte sa chair au préalable !', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129881, 'frFR', 'Allez, $gmortel:mortelle;. Dites à la fille de Rastakhan que je vous ai donné la permission de pénétrer dans la ville.', '', 28153),
(129880, 'frFR', 'Je souhaite entrer dans la ville.', 'Je souhaite entrer dans la ville.', 28153),
(129879, 'frFR', 'Vous sentez la nouveauté. Et la guerre, aussi. Une proie fort appétissante, ma foi. Qu\’est-ce qui vous amène ?', '', 28153),
(129660, 'frFR', 'Héraut ! Le conseil de guerre s\’est réuni en urgence. Votre présence est requise au donjon de Hurlevent.', '', 28153),
(128197, 'frFR', 'Je reviens des profondeurs !', '', 28153),
(128196, 'frFR', 'On est arrivés ! On va installer le détecteur pendant que vous vous familiarisez avec l\’île.', '', 28153),
(128195, 'frFR', 'Posons-nous ici, mes péons. Une minute, je sens l\’odeur nauséabonde des HUMAINS. Cette île appartient à Burgthok, vous m\’entendez ?', '', 28153),
(127581, 'frFR', 'Holà, ce n\’est pas un temps normal par ces latitudes. L\’azérite a attiré l\’attention d\’un seigneur élémentaire. Soyez prudents. Ou tuez-le. Ou faites les deux !', '', 28153),
(127580, 'frFR', '', 'Je dépêche immédiatement des mineurs pour exploiter cette veine d\’azérite.', 28153),
(127579, 'frFR', '$n, nos éclaireurs ont découvert plusieurs îles riches en azérite. Nous devons immédiatement y envoyer votre vaisseau.', '', 28153),
(127578, 'frFR', 'La Lumière nous a gratifiés de cette île, partez avant que le sang soit versé. Ceci était votre dernier avertissement.', '', 28153),
(127577, 'frFR', '', 'C\’est l\’heure du pillage, ha ha ! Dorp, tire sur tout ce qui bouge. Pete, déniche-moi ces vauriens de l\’Alliance. Et récupérez-moi cette azérite !', 28153),
(127576, 'frFR', 'Hé, y a du bon matos qui vous attend ici.', '', 28153),
(127575, 'frFR', '', 'Vos alliés des Sancteforge sont venus vous aider !', 28153),
(127574, 'frFR', 'Il y a des… navires de la Horde en approche. Je dis ça au cas où vous voudriez accélérer.', '', 28153),
(127573, 'frFR', 'Oui ? Nous avons nos ordres et l\’azérite nous attend. Jetez un coup d\’œil à la table, je me tiens prêt à appareiller à votre signal.\n\nJe vois bien que je vous fais de l\’effet, et ce n\’est pas une première, mais le moment est mal choisi pour nous disperser.', '', 28153),
(127569, 'frFR', 'Recommencer l\’île en cours.', 'Recommencer l\’île en cours.', 28153),
(127568, 'frFR', 'On est à mi-chemin, les gars. Ne me laissez pas tomber, hein.', '', 28153),
(127501, 'frFR', 'Vous ! Sauvez Barbe-Infâme ! Moi donner beaucoup qui-brille !', '', 28153),
(126508, 'frFR', '|cFFFFFF00Azérite|r |cFF0EA6DC+$1i|r', '|cFFFFFF00Azérite|r |cFF0EA6DC+$1i|r', 28153),
(124726, 'frFR', 'Déchiffrer les règles', 'Déchiffrer les règles', 28153),
(124724, 'frFR', 'Nouvelle partie', 'Nouvelle partie', 28153),
(124723, 'frFR', 'Lancer la partie', 'Lancer la partie', 28153),
(124717, 'frFR', '------------------------------$bDIFFICULTÉ ULTIME$b------------------------------$b\nLa console bourdonne et siffle lorsque vous y posez votre main. Le panneau central affiche rapidement une suite sans fin de glyphes, la plupart accompagnés de crânes ou de visages dont les yeux sont remplacés par des croix. Des bonus de temps sont disponibles à ce niveau, mais l\’un d\’eux est piégé.$b$bUne musique joyeuse se lance. La console vous souhaite-t-elle bonne chance dans ce niveau ultime, ou vous dit-elle adieu ?', '', 28153),
(124716, 'frFR', '---------------$b   NIVEAU 4$b---------------$b\nLa console réagit à votre toucher familier, allumant une série de motifs hexagonaux et jouant une musique entraînante.$b$bIl est difficile d\’interpréter les antiques symboles qui défilent sur le panneau central, mais vous en déduisez que le prochain niveau de difficulté a entraîné la mort de la plupart des joueurs qui s\’y sont frottés.$b$bLe seul point positif, c\’est qu\’il est possible d\’obtenir un bonus de temps sur l\’un des hexagones.', '', 28153),
(124715, 'frFR', '---------------$b   NIVEAU 3$b---------------$b\nLa console vous réserve un accueil chaleureux, malgré ses tentatives répétées de vous assassiner.$b$bLes symboles pour le niveau suivant vous laissent à penser que vous aurez moins d\’indices, moins de temps et plus de mines.', '', 28153),
(124714, 'frFR', '---------------$b   NIVEAU 2$b---------------$b\nLa console émet des bips et reconnaît votre main. Les règles ont changé et les symboles indiquent à présent qu\’il faut battre le temps imparti.$b$bLa pénalité en cas d\’échec semble pencher du côté de la souffrance plutôt que de la mort. Il y a du mieux.', '', 28153),
(124713, 'frFR', 'Vous faites de votre mieux pour interpréter les symboles et ignorer les avertissements répétés concernant une mort instantanée.$b$bLa console du Démageur va générer une grille d\’hexagones qui réagissent aux pas. Plusieurs de ces hexagones sont piégés et réduiront le personnage-joueur en cendres. Un pas sur un hexagone non piégé révèle par ailleurs le nombre de mines adjacentes.$b$bL\’objectif consiste à terminer une grille en révélant tous les hexagones non piégés et en indiquant ceux qui le sont grâce aux drapeaux blancs fournis.$b$bVous ne comprenez pas pourquoi le jeu trouve nécessaire d\’assassiner ceux qui posent un pied sur le mauvais hexagone.', '', 28153),
(124711, 'frFR', '---------------$b   NIVEAU 1$b---------------$b\nCette mystérieuse console s\’allume au contact de votre main. Une suite d\’instructions s\’affiche sur le panneau central. La langue est indéfinissable, mais les symboles ne laissent aucune place au doute :$bil y a des crânes partout.$b$bIl s\’agit du Démageur, un jeu extrêmement dangereux, dont l\’objectif consiste à traverser un champ de mines arcaniques et à identifier toutes les zones piégées. La moindre erreur vous est immédiatement fatale.$b$bVous vous demandez pourquoi quiconque voudrait y jouer pour le plaisir.', '', 28153),
(124677, 'frFR', 'NIVEAU 5', '', 28153),
(124676, 'frFR', 'NIVEAU 4', '', 28153),
(124675, 'frFR', 'NIVEAU 3', '', 28153),
(124674, 'frFR', 'NIVEAU 2', '', 28153),
(124673, 'frFR', 'NIVEAU 1', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(167308, 'itIT', 'I want to teleport to Waycrest Manor (Dungeon).', 'I want to teleport to Waycrest Manor (Dungeon).', 28153),
(167307, 'itIT', 'I want to teleport to Tol Dagor (Dungeon).', 'I want to teleport to Tol Dagor (Dungeon).', 28153),
(167306, 'itIT', 'I want to teleport to The Underrot (Dungeon).', 'I want to teleport to The Underrot (Dungeon).', 28153),
(167305, 'itIT', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 'I want to teleport to  The MOTHERLODE!! (Dungeon).', 28153),
(167304, 'itIT', 'I want to teleport to Temple of Sethraliss (Dungeon).', 'I want to teleport to Temple of Sethraliss (Dungeon).', 28153),
(167302, 'itIT', 'I want to teleport to Siege of Boralus (Dungeon).', 'I want to teleport to Siege of Boralus (Dungeon).', 28153),
(167301, 'itIT', 'I want to teleport to Shrine of the Storm (Dungeon).', 'I want to teleport to Shrine of the Storm (Dungeon).', 28153),
(167300, 'itIT', 'I want to teleport to Kings\' Rest (Dungeon).', 'I want to teleport to Kings\' Rest (Dungeon).', 28153),
(167299, 'itIT', 'I want to teleport to Freehold (Dungeon).', 'I want to teleport to Freehold (Dungeon).', 28153),
(167298, 'itIT', 'I want to teleport to Atal\'dazar (Dungeon).', 'I want to teleport to Atal\'dazar (Dungeon).', 28153),
(167297, 'itIT', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(167296, 'itIT', '', 'Greetings, and welcome to the Mythic Invitational!\n\nI can teleport you directly into any Battle for Azeroth dungeon instance.\n\nMake sure you have Mythic difficulty selected before teleporting.', 28153),
(162171, 'itIT', 'Forgiascura', 'Forgiascura', 28153),
(162170, 'itIT', 'Non puoi ignorare i tuoi doveri, torna a Darnassus!', 'Non puoi ignorare i tuoi doveri, torna a Darnassus!', 28153),
(162169, 'itIT', '', 'Sei $gpronto:pronta; a porre fine a tutto questo una volta per tutte, $n?', 28153),
(162168, 'itIT', '<Vola verso Dalaran>', '<Vola verso Dalaran>', 28153),
(162167, 'itIT', 'Riesci a guidare Loh a tutti i negozi e alla locanda senza fargli incrociare il suo stesso percorso?', '', 28153),
(162166, 'itIT', '', 'Sei $gpronto:pronta; a difendere le giovani tartarughe mentre si fanno strada verso il mare?', 28153),
(162165, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(162164, 'itIT', 'Ti do il benvenuto, $n. Credi di essere abbastanza $gastuto:astuta; per giocare al mio gioco?', '', 28153),
(162161, 'itIT', 'Vuoi davvero saltare l\'introduzione a Rivafosca?', 'Vuoi davvero saltare l\'introduzione a Rivafosca?', 28153),
(162160, 'itIT', 'Sì, $n? Sembri $gpreoccupato:preoccupata; per qualcosa...', '', 28153),
(162159, 'itIT', '<Il marinaio perduto critica la tua presenza. Non dovresti essere qui.>', '<Il marinaio perduto critica la tua presenza. Non dovresti essere qui.>', 28153),
(162158, 'itIT', 'Conosco già questa storia... <Salta le missioni introduttive e inizia il tuo viaggio a Rivafosca.>', 'Conosco già questa storia... <Salta lo scenario e inizia la tua prossima missione.>', 28153),
(162157, 'itIT', 'Ti riporterò al sicuro, $n. Tieniti forte!', '', 28153),
(162156, 'itIT', 'L\'ira della natura si abbatte su di voi!', '', 28153),
(162155, 'itIT', 'Tieniti forte, $C.', '', 28153),
(162152, 'itIT', 'Ci assicureremo che quest\'Azerite non cada nelle mani dell\'Alleanza!', 'Ci assicureremo che quest\'Azerite non cada nelle mani dell\'Alleanza!', 28153),
(162151, 'itIT', '|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t Le |cFFF00000|Hspell:260551|h[Spine d\'Anima]|h|r hanno intrappolato $n!', '', 28153),
(162150, 'itIT', 'Vorrei assistere l\'Ammiragliato nella sua missione a Kul Tiras. <Imposta la reputazione con l\'Ammiragliato dei Marefiero ad Amichevole.>', 'Vorrei assistere l\'Ammiragliato nella sua missione a Kul Tiras. <Imposta la reputazione con l\'Ammiragliato dei Marefiero ad Amichevole.>', 28153),
(162149, 'itIT', 'Sei $gil migliore:la migliore;, $n!', 'Sei $gil migliore:la migliore;, $n!', 28153),
(162148, 'itIT', '$n è davvero uno schianto.', '$n è davvero uno schianto.', 28153),
(162147, 'itIT', 'Ti sta davvero da favola!', 'Ti sta davvero da favola!', 28153),
(162146, 'itIT', 'Uooo!', 'Uooo!', 28153),
(162145, 'itIT', '$n! $n! $n!', '$n! $n! $n!', 28153),
(162144, 'itIT', 'È $n! $n è sul palco!', 'È $n! $n è sul palco!', 28153),
(162143, 'itIT', 'Vai $n! Uooo!', 'Vai $n! Uooo!', 28153),
(162142, 'itIT', 'Vai $n!', 'Vai $n!', 28153),
(162141, 'itIT', 'La mia forgia è sempre pronta, $n.', 'La mia forgia è sempre pronta, $n.', 28153),
(162140, 'itIT', 'Radunerò le razioni che ci restano e libererò tutti i letti disponibili. Lok\'tar ogar!', 'Siamo solo un piccolo avamposto, ma radunerò tutto ciò che abbiamo. La Capoguerra e la sua armata avranno tutto ciò che desiderano, lo giuro! Lok\'tar ogar!', 28153),
(162139, 'itIT', 'Zoram\'gar sarà pronta! Per l\'Orda!', 'Zoram\'gar sarà pronta! Per l\'Orda!', 28153),
(162138, 'itIT', 'La Capoguerra Sylvanas Ventolesto ha richiesto il tuo aiuto per riparare le armi dei suoi soldati.', 'La Capoguerra Sylvanas Ventolesto ha richiesto il tuo aiuto per riparare le armi dei suoi soldati.', 28153),
(162137, 'itIT', '', 'C\'è un sentiero nascosto qui vicino che potremmo usare per tornare all\'atrio del maniero.', 28153),
(162135, 'itIT', 'Torna alla Valle del Crepuscolo!', '', 28153),
(162134, 'itIT', '', 'La regola della forgia non cambia mai! Fateci vedere come si fa, Nani Ferroscuro!', 28153),
(162133, 'itIT', '', 'Impiccheranno Geddon con una corda d\'oro! Fatevi sentire, Nani Ferroscuro!', 28153),
(162132, 'itIT', '', 'Le loro movenze sono dell\'altro mondo. Un applauso per i Mag\'har!', 28153),
(162131, 'itIT', '', 'Facciamo salire i Mag\'har sul palco!', 28153),
(162130, 'itIT', 'Mostrami le nostre opzioni di ricerca.', 'Mostrami le nostre opzioni di ricerca.', 28153),
(162129, 'itIT', 'Torna al Fiume Lettocurvo!', '', 28153),
(162128, 'itIT', 'Torna al Gladio del Maestro!', '', 28153),
(162127, 'itIT', '', 'Se vuoi un lavoro fatto bene... usa esplosivi più grandi!', 28153),
(162123, 'itIT', '$n prepara un Banchetto Abbondante del Capitano!', '$n prepara un Banchetto Abbondante del Capitano!', 28153),
(162122, 'itIT', '$n prepara un Banchetto di Bordo!', '$n prepara un Banchetto di Bordo!', 28153),
(162121, 'itIT', 'Vuoi davvero saltare la Battaglia per Lordaeron?', 'Vuoi davvero saltare la Battaglia per Lordaeron?', 28153),
(162120, 'itIT', 'Conosco già questa storia... <Salta lo scenario e inizia la tua prossima missione.>', 'Conosco già questa storia... <Salta lo scenario e inizia la tua prossima missione.>', 28153),
(162119, 'itIT', '', 'Sorelle, venite con me! Dobbiamo proteggere le nostre terre dall\'Orda!', 28153),
(162118, 'itIT', '', 'Rivafosca è sotto attacco! Avvisate subito la Gran Sacerdotessa!', 28153),
(162117, 'itIT', 'Radunate i nostri alleati della foresta! L\'Albero del Mondo deve essere protetto!', '', 28153),
(162116, 'itIT', 'Rivafosca è sotto attacco! Dobbiamo muoverci in fretta se vogliamo difendere la nostra foresta!', '', 28153),
(162110, 'itIT', 'Dobbiamo occuparci del Generale Grebo.', 'Dobbiamo occuparci del Generale Grebo.', 28153),
(162109, 'itIT', 'Felice di vederti.', '', 28153),
(162108, 'itIT', 'L\'Orda ha fermato la sua avanzata al Fiume Lettocurvo! Dobbiamo respingerli immediatamente!', 'L\'Orda ha fermato la sua avanzata al Fiume Lettocurvo! Dobbiamo respingerli immediatamente!', 28153),
(162107, 'itIT', 'Riesco a sentire i tamburi di guerra echeggiare nella foresta. I Druidi dell\'Unghia sono pronti a difendere questa terra da chiunque intenda distruggerla!', '', 28153),
(162106, 'itIT', 'Quanto potere!', '', 28153),
(162105, 'itIT', 'Sì, è perfetto. È esattamente ciò di cui avevo bisogno. Dovrebbe volerci solo un momento.', '', 28153),
(162104, 'itIT', 'Riesco a sentirlo. Il frammento freme di potere! È... magnifico e allo stesso tempo terrificante.', '', 28153),
(162103, 'itIT', '', 'Era da tempo che lo aspettavamo. I Ferroscuro emergeranno finalmente dalla montagna e si prenderanno il posto che spetta loro di diritto nell\'Alleanza.', 28153),
(162102, 'itIT', 'Credi che mi lasceranno guidare il mio Capro Armato per le strade di Roccavento?', '', 28153),
(162101, 'itIT', 'Sarà meglio che gli altri membri dell\'Alleanza si abituino ad avere degli alleati focosi al loro fianco!', '', 28153),
(162100, 'itIT', 'Non mi piace come mi guardano gli altri Nani a Roccavento.', 'Non mi piace come mi guardano gli altri Nani a Roccavento.', 28153),
(162099, 'itIT', 'Non mi piace tutta quella luce che c\'è in superficie.', 'Non mi piace tutta quella luce che c\'è in superficie.', 28153),
(162098, 'itIT', 'Una casa non può considerarsi tale se non è benedetta da un sottile strato di fuliggine.', 'Una casa non può considerarsi tale se non è benedetta da un sottile strato di fuliggine.', 28153),
(162097, 'itIT', 'Le fiamme di Roccianera ardono per l\'Alleanza!', 'Le fiamme di Roccianera ardono per l\'Alleanza!', 28153),
(162096, 'itIT', 'Quasi tutto può essere riparato con una chiave meccanica e un polso allenato.', 'Quasi tutto può essere riparato con una chiave meccanica e un polso allenato.', 28153),
(162095, 'itIT', 'I Ferroscuro sono gli unici veri Nani. Gli altri clan sono troppo deboli!', 'I Ferroscuro sono gli unici veri Nani. Gli altri clan sono troppo deboli!', 28153),
(162094, 'itIT', 'Noi siamo la vera forza della montagna.', 'Noi siamo la vera forza della montagna.', 28153),
(162093, 'itIT', 'Perché mi rivolgi la parola? Fai attenzione, la mia pazienza ha un limite!', 'Perché mi rivolgi la parola? Fai attenzione, la mia pazienza ha un limite!', 28153),
(162089, 'itIT', 'Lascia questo posto!', '', 28153),
(162088, 'itIT', 'Vattene! Non sei $gil benvenuto:la benvenuta; nella nostra tana!', '', 28153),
(162087, 'itIT', 'Non ruberai la nostra dimora!', '', 28153),
(162086, 'itIT', 'Basta così! Pietà! Hai vinto...', '', 28153),
(162085, 'itIT', 'Molto bene... Lasciami radunare la nostra gente e ce ne andremo.', '', 28153),
(162084, 'itIT', 'Fermati! Ti prego! Mi arrendo...', '', 28153),
(162082, 'itIT', '', 'L\'Alleanza ha accolto i Draenei e i loro Forgialuce.\n\nÈ una ragione più che sufficiente per ridurre in polvere le loro città.', 28153),
(162081, 'itIT', '', 'Ci sono Draenei su questo mondo?\n\n<Geya\'rah strizza gli occhi.>\n\nNon per molto.', 28153),
(162080, 'itIT', '', 'Le nostre lame sono al servizio dell\'Orda!', 28153),
(162079, 'itIT', '', 'I Mag\'har faranno di Azeroth la loro nuova casa.', 28153),
(162078, 'itIT', '', 'Draenor sarà ormai perduta, ma il mio cuore mi dice che un giorno la rivedremo.\n\nAntenati, fate in modo che questo sogno diventi realtà!', 28153),
(162077, 'itIT', 'Squartamento? È una pratica barbara che si usava in passato. Non avrei neanche la minima idea di come iniziare un rituale del genere.\n\n<L\'Orco si avvicina e sussurra.>\n\nSo esattamente come iniziare. Sei qui per una dimostrazione?', 'Squartamento? È una pratica barbara che si usava in passato. Non avrei neanche la minima idea su come iniziare un rituale del genere.\n\n<L\'Orchessa si avvicina e sussurra.>\n\nSo esattamente come iniziare. Sei qui per una dimostrazione?', 28153),
(162076, 'itIT', 'A volte mi capita di pensare ai Draenei chiedendomi se ci sono delle ossa in quei tentacoli facciali perché in quel caso mi piacerebbe recuperarne qualche centinaio e intrecciarli per creare delle decorazioni da appendere alle mura in modo che i visitatori possano ammirarli dicendo ehi ma guarda che bei tentacoli scommetto che sono stati raccolti da un Orco saggio e talentuoso e io risponderei dicendo sì è quello che mi diceva sempre mia madre.\n\nChiedo scusa. Avevi una domanda?', 'A volte mi capita di pensare ai Draenei chiedendomi se ci sono delle ossa in quei tentacoli facciali perché in quel caso mi piacerebbe recuperarne qualche centinaio e intrecciarli per creare decorazioni da appendere alle mura in modo che i visitatori possano ammirarli dicendo ehi ma guarda che bei tentacoli scommetto che sono stati collezionati da un\'Orchessa saggia e talentuosa e io risponderei dicendo sì è quello che mi diceva sempre mia madre.\n\nChiedo scusa. Avevi una domanda?', 28153),
(162075, 'itIT', 'È ora di mangiare? Spero sia già ora di mangiare!\n\nCambiando discorso... se dovessi scegliere un arto da sacrificare, quale sceglieresti?', 'È ora di mangiare? Spero sia già ora di mangiare!\n\nCambiando discorso... se dovessi scegliere un arto da sacrificare, quale sceglieresti?', 28153),
(162074, 'itIT', '', '<Lasha fissa lo sguardo sulla tua testa.>\n\nCom\'è il tuo cranio? Si adatta bene?\n\nLa tua mente è libera... vuota... o divisa?', 28153),
(162073, 'itIT', '', 'Mi mancano i Botani.\n\nErano DELIZIOSI, se cotti a puntino.\n\n<Lasha si pulisce un rivolo di bava dalle labbra.>', 28153),
(162072, 'itIT', '', 'È già il momento di dar fuoco ai Vincolaluce?', 28153),
(162071, 'itIT', '$GBenvenuto:Benvenuta; nella mia locanda, viandante. Hai l\'aria stanca. Cosa posso fare per te?', '$GBenvenuto:Benvenuta; nella mia locanda, viandante. Hai l\'aria stanca. Cosa posso fare per te?', 28153),
(162070, 'itIT', 'Rendi questo luogo la mia dimora.', 'Rendi questo luogo la mia dimora.', 28153),
(162069, 'itIT', 'Coloro che sfidano il Capoguerra Malogrido pagheranno con la propria vita!', 'Coloro che sfidano il Capoguerra Malogrido pagheranno con la propria vita!', 28153),
(162068, 'itIT', 'Stai camminando sul NOSTRO mondo, $gstraniero:straniera;\n\nSe porterai qui la corruzione, la tua vita sarà condannata.', 'Stai camminando sul NOSTRO mondo, $gstraniero:straniera;\n\nSe porterai qui la corruzione, la tua vita sarà condannata.', 28153),
(162067, 'itIT', 'Se prendo uno di quei traditori Vincolaluce, gli taglierò la gola!', 'Se prendo uno di quei traditori Vincolaluce, gli taglierò la gola!', 28153),
(162066, 'itIT', 'Abbiamo sconfitto i Primordiali. Nessun nemico potrà opporsi a noi.', 'Abbiamo sconfitto i Primordiali. Nessun nemico potrà opporsi a noi.', 28153),
(162065, 'itIT', 'Draenor sarà libera!', 'Draenor sarà libera!', 28153),
(162064, 'itIT', 'Quando ti guadagnerai la fiducia della Suprema, avrai anche la mia.', 'Quando ti guadagnerai la fiducia della Suprema, avrai anche la mia.', 28153),
(162063, 'itIT', 'La Suprema Geya\'rah è il braccio destro del Capoguerra. Non esiste Orco più coraggioso di lei su Draenor.\n\nE nemmeno nel tuo mondo!', 'La Suprema Geya\'rah è il braccio destro del Capoguerra. Non esiste Orco più coraggioso di lei su Draenor.\n\nE nemmeno nel tuo mondo!', 28153),
(162062, 'itIT', '', 'Quand\'ero bambina, gli studiosi Draenei mi insegnarono a leggere e scrivere. Mi piacevano e li rispettavo.\n\nPoi arrivarono i Naaru e il fanatismo prese il sopravvento.\n\nI Draenei diventarono... No, hanno una parola diversa per descriverlo... si riforgiarono per mezzo della loro preziosa Luce.\n\nIl loro credo li rende ciechi e li obbliga a servire padroni che intendono controllare l\'universo, proprio come voleva fare la Legione.\n\nDraenei... Eredar... tutti così ansiosi di inchinarsi e accogliere la corruzione.', 28153),
(162061, 'itIT', '', 'Grommash Malogrido ci ha guidato bene. Lo rispetto tanto quanto mio padre.\n\nMa se dovessi rivedere quel traditore di suo figlio...\n\n<Geya\'rah sputa a terra.>\n\nLo ucciderò.', 28153),
(162060, 'itIT', '', 'Draenor deve essere libera dalla morsa di fanatici e tiranni.', 28153),
(162059, 'itIT', 'Degli eroi del nostro mondo una volta mi liberarono dalla morsa di un demone nella Cittadella del Fuoco Infernale. Anche tu eri tra loro?\n\n<Grommash ti scruta.>\n\nIn tal caso, sono in debito con te. Forse gli spiriti mi mostreranno un modo per ripagarti.', '', 28153),
(162058, 'itIT', 'I Mag\'har non si inchineranno davanti a nessuno. Nemmeno a coloro che un tempo chiamavamo amici.', '', 28153),
(162057, 'itIT', 'Hai viaggiato a lungo, $C. Troverai che il nostro mondo si è fatto più selvaggio dall\'ultima volta che la tua gente ha avuto modo di vederlo.', '', 28153),
(162047, 'itIT', '', 'Che ricordi posso riportarti alla luce quest\'oggi?', 28153),
(162046, 'itIT', 'Come può aiutarti il vecchio T\'omkus?', '', 28153),
(162045, 'itIT', 'Parlami della Battaglia per Lordaeron.', 'Parlami della Battaglia per Lordaeron.', 28153),
(162044, 'itIT', 'Parlami del confronto alla sala del trono.', 'Parlami del confronto alla sala del trono.', 28153),
(162043, 'itIT', 'Parlami del tradimento di Marefiero.', 'Parlami del tradimento di Marefiero.', 28153),
(162042, 'itIT', 'Parlami delle prove di Jaina.', 'Parlami delle prove di Jaina.', 28153),
(162041, 'itIT', 'Parlami dell\'incubo di Jaina.', 'Parlami dell\'incubo di Jaina.', 28153),
(162040, 'itIT', 'Parlami del ritorno di Jaina a Theramore.', 'Parlami del ritorno di Jaina a Theramore.', 28153),
(162039, 'itIT', 'Parlami della battaglia alla piramide.', 'Parlami della battaglia alla piramide.', 28153),
(162038, 'itIT', 'Parlami della scelta di Rastakhan.', 'Parlami della scelta di Rastakhan.', 28153),
(162037, 'itIT', 'Parlami del ritorno di Talanji a Zuldazar.', 'Parlami del ritorno di Talanji a Zuldazar.', 28153),
(162035, 'itIT', 'Questo non è un buon modo di morire.', 'Questo non è un buon modo di morire.', 28153),
(162034, 'itIT', 'Sento il freddo avvolgermi...', 'Sento il freddo avvolgermi...', 28153),
(162033, 'itIT', 'Hai i miei ringraziamenti.', 'Hai i miei ringraziamenti.', 28153),
(162032, 'itIT', 'Sarà meglio che non sia una trappola, abbiamo ancora bisogno dell\'aiuto di $n.', '', 28153),
(162031, 'itIT', 'Sono pronto a lasciare Fine del Destino.', 'Sono pronta a lasciare Fine del Destino.', 28153),
(162030, 'itIT', 'Sono pronto ad andare a Fine del Destino.', 'Sono pronta ad andare a Fine del Destino.', 28153),
(162029, 'itIT', 'Ma che...? Di cos\'ha bisogno Magni Barbabronzea?', '', 28153),
(162025, 'itIT', 'Non hai sentito? L\'Orda custodisce il corpo di Derek Marefiero al Porto del Saccheggio. Dama Marefiero ha praticamente mandato l\'intera flotta a recuperarlo.', 'Non hai sentito? L\'Orda custodisce il corpo di Derek Marefiero al Porto del Saccheggio. Dama Marefiero ha praticamente mandato l\'intera flotta a recuperarlo.', 28153),
(162024, 'itIT', 'Oggi è un giorno tranquillo. Dove sono tutti?', 'Oggi è un giorno tranquillo. Dove sono tutti?', 28153),
(162023, 'itIT', '', 'Sembra che Stone se la stia cavando bene.\n\nCol tempo, credo che diventerà una leale alleata.', 28153),
(162021, 'itIT', '', 'È stato... rinvigorente vedere quella gente beccarsi ciò che si meritava.\n\nÈ questo che vuol dire essere liberi? Poter stabilire le proprie regole?\n\nForse potrei abituarmici.', 28153),
(162020, 'itIT', '', 'Sembra che Amalia se la stia cavando abbastanza bene.\n\nCiò che sta passando non è facile, ma è più forte di quanto ero io subito dopo la trasformazione. Uccisi quasi tutti quelli che mi facevano arrabbiare. Amalia invece si è solo chiusa in se stessa.\n\nCon il tempo, si adatterà. Fidati.', 28153),
(162019, 'itIT', 'Si stanno avvicinando! Fategli provare il vero dolore!', '', 28153),
(162018, 'itIT', 'Andiamo, ragazzi. Fate piovere dolore!', '', 28153),
(162017, 'itIT', 'Vacillerai... Egli sta arrivando... Egli sta arrivando...', '', 28153),
(162016, 'itIT', '', 'Lasciami stare. Non voglio parlarti.', 28153),
(162015, 'itIT', 'Il padrone ha fame... Il cuore nutrirà il suo sogno...', '', 28153),
(162014, 'itIT', 'Li Zandalari adorano Bwonsamdi da molto tempo, proprio come i Lanciascura.\n\nGuarda chesto idolo di Bwonsamdi che ho comprato al porto. È magnifico! Più bello della maggior parte di chelli che ho visto a casa mia.\n\nI Lanciascura e li Zandalari sono molto diversi tra loro, è vero, ma teniamo molte più cose in comune.\n\nSe li Zandalari si toglieranno mai la scopa che tengono in chel posto, credo che potremmo diventare ottimi amici!', 'Quando andremo a caccia la prossima volta, $p?\n\nIn tutti i miei anni su Azeroth, non c\'è mai stata carenza di mostri da uccidere.', 28153),
(162013, 'itIT', '', 'No! La nostra casa...', 28153),
(162012, 'itIT', '', 'Non farai un solo altro passo verso la nostra casa, $R! Tor ilisar\'thera\'nal!', 28153),
(162011, 'itIT', 'Troppo tardi... stolti...', '', 28153),
(162010, 'itIT', 'Razzieremo ciò che rimane di questo piccolo villaggio, poi ci sbarazzeremo di te una volta per tutte!', '', 28153),
(162009, 'itIT', 'Ho sentito che gli Zandalari adorano un Loa Pterrordattilo.\n\nUn dio rettile... che vola!\n\n<Le palpebre di Lasan sembrano tremare.>\n\nAviash è pronto a sfidare i loro cavalieri migliori in una gara... o ancora meglio, uno scontro!\n\nA noi non importa, li batteremo in ogni caso!\n\nAhahahahah!', 'Quando andremo a caccia la prossima volta, $p?\n\nIn tutti i miei anni su Azeroth, non c\'è mai stata carenza di mostri da uccidere.', 28153),
(162008, 'itIT', 'Parlami del tuo piano, Nathanos.', 'Parlami del tuo piano, Nathanos.', 28153),
(162007, 'itIT', 'Molto bene. $n, avvisa Velamesta che siamo pronti a partire.', '', 28153),
(162006, 'itIT', 'E l\'Orda lo ruberà.', '', 28153),
(162005, 'itIT', 'Il manufatto è tenuto sotto stretta sorveglianza nel cuore della capitale dei Kul Tirani, Boralus.', '', 28153),
(162004, 'itIT', 'Chiunque possieda lo Scettro Abissale può controllare il potere del mare e delle tempeste.', '', 28153),
(162003, 'itIT', 'Lo Scettro Abissale.', '', 28153),
(162002, 'itIT', 'La Casata dei Sacraonda, in particolare i miei vecchi fratelli Saggi delle Maree, è in possesso di un potente manufatto.', '', 28153),
(162001, 'itIT', 'Sì, Selvamorta.', '', 28153),
(162000, 'itIT', 'Zelling, vuoi avere tu l\'onore?', '', 28153),
(161999, 'itIT', 'Guarda quanto sono grandi quei dinosauri!\n\n<Ji sospira ansiosamente.>\n\nNon vedo l\'ora di prenderne uno a pugni.', 'Quando andremo a caccia la prossima volta, $p?\n\nIn tutti i miei anni su Azeroth, non c\'è mai stata carenza di mostri da uccidere.', 28153),
(161998, 'itIT', 'Riva Dispersa', 'Riva Dispersa', 28153),
(161997, 'itIT', 'Volta di Neltharion', 'Volta di Neltharion', 28153),
(161996, 'itIT', 'Altopiano Elementale', 'Altopiano Elementale', 28153),
(161995, 'itIT', 'Rialzo della Fonderia dei Roccianera', 'Rialzo della Fonderia dei Roccianera', 28153),
(161994, 'itIT', 'Birrificio Triplo Malto', 'Birrificio Triplo Malto', 28153),
(161993, 'itIT', 'Mezzabotte', 'Mezzabotte', 28153),
(161992, 'itIT', 'Ho combattuto molte guerre. Ho visto eroi e codardi sanguinare sui campi di battaglia.\n\nMa questa guerra sembra... diversa.\n\nMette alla prova ben più del nostro carattere e delle nostre abilità... mette alla prova il nostro cuore e la nostra fede gli uni negli altri.\n\nQualsiasi cosa succeda, l\'Orda resisterà.\n\nDeve farlo.', 'Quando andremo a caccia la prossima volta, $p?\n\nIn tutti i miei anni su Azeroth, non c\'è mai stata carenza di mostri da uccidere.', 28153),
(161991, 'itIT', 'Santuario dei Draghi di Rubino', 'Santuario dei Draghi di Rubino', 28153),
(161990, 'itIT', 'Campi del Torneo d\'Argento', 'Campi del Torneo d\'Argento', 28153),
(161989, 'itIT', 'Skald', 'Skald', 28153),
(161988, 'itIT', 'Fosse Vili', 'Fosse Vili', 28153),
(161987, 'itIT', 'Rocca dell\'Onore', 'Rocca dell\'Onore', 28153),
(161986, 'itIT', 'Grande Fenditura', 'Grande Fenditura', 28153),
(161985, 'itIT', 'Trono delle Fiamme', 'Trono delle Fiamme', 28153),
(161984, 'itIT', 'Rilievo del Magma Colante', 'Rilievo del Magma Colante', 28153),
(161983, 'itIT', 'Corridoio Oscuro', 'Corridoio Oscuro', 28153),
(161982, 'itIT', 'Picco dell\'Aquila', 'Picco dell\'Aquila', 28153),
(161981, 'itIT', 'Forte di Guardiafatua', 'Forte di Guardiafatua', 28153),
(161980, 'itIT', 'Roccavento', 'Roccavento', 28153),
(161979, 'itIT', 'Forgiardente', 'Forgiardente', 28153),
(161978, 'itIT', 'Zandalar', 'Zandalar', 28153),
(161977, 'itIT', 'Kul Tiras', 'Kul Tiras', 28153),
(161976, 'itIT', 'Isole Disperse', 'Isole Disperse', 28153),
(161975, 'itIT', 'Nordania', 'Nordania', 28153),
(161974, 'itIT', 'Pandaria', 'Pandaria', 28153),
(161973, 'itIT', 'Draenor', 'Draenor', 28153),
(161972, 'itIT', 'Terre Esterne', 'Terre Esterne', 28153),
(161971, 'itIT', 'Kalimdor', 'Kalimdor', 28153),
(161970, 'itIT', 'Regni Orientali', 'Regni Orientali', 28153),
(161969, 'itIT', 'Qualsiasi cosa che valga la pena avere dovrebbe stare in una scatola.\n\nEccetto le persone, ovviamente! Non si può mettere $guno:una; $p in una scatola, giusto?\n\n<Hobart perde il filo del discorso per un momento.>\n\nComunque, sto solo facendo qualche modifica. Rimetterò in funzione questo esoscheletro in men che non si dica... con qualche miglioramento esplosivo!', 'Quando andremo a caccia la prossima volta, $p?\n\nIn tutti i miei anni su Azeroth, non c\'è mai stata carenza di mostri da uccidere.', 28153),
(161968, 'itIT', 'Non morirò su questa collina, George.', '', 28153),
(161967, 'itIT', 'Con Jeph combatti, con Jeph tu schiatti!', '', 28153),
(161966, 'itIT', 'Tua figlia è stata portata a Fine del Destino.', 'Tua figlia è stata portata a Fine del Destino.', 28153),
(161965, 'itIT', 'Ottimo! Gliel\'abbiamo fatta vedere!', '', 28153),
(161964, 'itIT', 'Un deserto? Che... carino.', '', 28153),
(161963, 'itIT', 'Sono qui come avevi richiesto, Sventradraghi.', '', 28153),
(161962, 'itIT', 'Ci siamo...', '', 28153),
(161961, 'itIT', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t Spostati nel |cFFFF0000|Hspell:267334|h[Globo della Corruzione]|h|r per rispedirlo in aria!', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t Spostati nel |cFFFF0000|Hspell:267334|h[Globo della Corruzione]|h|r per rispedirlo in aria!', 28153),
(161960, 'itIT', 'Fuoco!', 'Fuoco!', 28153),
(161959, 'itIT', 'Va bene! Quando vuoi!', '', 28153),
(161958, 'itIT', 'Tenete occupato quella maledetta cosa mentre preparo il cannone!', '', 28153),
(161957, 'itIT', '|cFF0000FF(Missione)|r Sono pronto a raggiungere Draenor.', '|cFF0000FF(Missione)|r Sono pronta a raggiungere Draenor.', 28153),
(161956, 'itIT', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s ti prende di mira con |cFFFF0000|Hspell:259720|h[Sollevazione Terrestre]|h|r!', '|TInterface\\Icons\\ABILITY_EARTHEN_PILLAR.BLP:20|t %s ti prende di mira con |cFFFF0000|Hspell:259720|h[Sollevazione Terrestre]|h|r!', 28153),
(161955, 'itIT', 'Ecco, ho l\'ultima chiave!', 'Ecco, ho l\'ultima chiave!', 28153),
(161954, 'itIT', 'Sono pronto a cercare l\'Eco di Garrosh.', 'Sono pronta a cercare l\'Eco di Garrosh.', 28153),
(161953, 'itIT', 'Non ti aiuterei in questo compito se non fossi convinto della sua importanza.', '', 28153),
(161952, 'itIT', 'Smettila di blaterare! Non c\'è bisogno di dirlo a tutti.', 'Avremmo dovuto andarcene ieri.', 28153),
(161950, 'itIT', 'Questo non è come pensavo sarebbe andata la giornata!', '', 28153),
(161949, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t Lo Sfollagente a Gettoni usa |cFFFF0000|Hspell:256214|h[Lancio Pallabomba]|h|r!', '|TINTERFACE\\ICONS\\INV_MISC_SOCCERBALL.BLP:20|t Lo Sfollagente a Gettoni usa |cFFFF0000|Hspell:256214|h[Lancio Pallabomba]|h|r!', 28153),
(161948, 'itIT', 'Il tuo frammento si fa più potente, $p.', '', 28153),
(161947, 'itIT', 'Il tanfo della mia stirpe permane. Occupati rapidamente di questa seccatura.', '', 28153),
(161946, 'itIT', 'Il nostro compito è finito, $p. Il Capo Telemante Oculeth attende il tuo arrivo a Zuldazar.', '', 28153),
(161945, 'itIT', '', 'Non se manterrai la tua parola, palla di melma.', 28153),
(161944, 'itIT', 'D\'accordo, cinquanta! Ci sto! Niente rancori, d\'accordo?', '', 28153),
(161943, 'itIT', '', 'Facciamo cinquanta. A meno che tu non preferisca che mi prenda il cinquanta percento dei tuoi denti.', 28153),
(161942, 'itIT', 'Sai che ti dico? Che ne dici se ti lascio una parte dei profitti sull\'argento e tu metti giù quel piccone? Facciamo il venti percento?', '', 28153),
(161941, 'itIT', 'Davvero? Me lo ricorderei...', '', 28153),
(161940, 'itIT', '', 'Perché ti stavamo urlando contro quando ci hai lasciati qui con le guardie!', 28153),
(161939, 'itIT', 'Ehi, calmati! Come facevo a sapere che c\'erano dei sopravvissuti?', '', 28153),
(161938, 'itIT', '', 'Codardo! Ci hai lasciati là a morire!', 28153),
(161937, 'itIT', 'Tieni il tempo del mio prossimo giro!', 'Tieni il tempo del mio prossimo giro!', 28153),
(161936, 'itIT', 'Spero tu sia $gpronto:pronta; a partire!', '', 28153),
(161935, 'itIT', '', 'Se non ti dispiace, vado a cercare Tetrok per mostrargli quanto bene so usare il mio piccone...', 28153),
(161934, 'itIT', '', 'Grazie ancora per l\'aiuto, $gstraniero:straniera;.', 28153),
(161933, 'itIT', 'Missioni mondiali sbloccate', '', 28153),
(161932, 'itIT', 'Hanno cercato di venderli come cibo!', 'Sigilla quella cassa, dobbiamo ripulire questo casino!', 28153),
(161931, 'itIT', 'Battaglia per Stromgarde sbloccata', '', 28153),
(161930, 'itIT', 'Odio quei bambini!', 'Sbarazzati di quelle cose!', 28153),
(161929, 'itIT', 'Sono stati quei terribili bambini a portare quelle cose in città!', 'Questa è un\'altra idea di quei bambini finita male!', 28153),
(161928, 'itIT', '|TInterface\\ICONS\\INV_Misc_Bell_Green:20|t Raal l\'Ingordo inizia a lanciare |cFFFF0404|Hspell:264931|h[Richiamo Servitore]|h|r!', '', 28153),
(161927, 'itIT', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dama Crestabianca inizia a lanciare |cFFFF0404|Hspell:268306|h[Cadenza Discordante]|h|r!', '|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dama Crestabianca inizia a lanciare |cFFFF0404|Hspell:268306|h[Cadenza Discordante]|h|r!', 28153),
(161926, 'itIT', 'Ce l\'hai fatta! Azeroth si è più forte... e anche tu!', '', 28153),
(161925, 'itIT', 'Un servitore degli Dei Antichi! Il Cuore di Azeroth è abbastanza potente da scacciarlo! Usa il cuore, $n!', '', 28153),
(161924, 'itIT', 'Isole sbloccate', '', 28153),
(161923, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Banchetto di Sangue]|h|r per purificare i tuoi accumuli di |cFFFF0404|Hspell:263227|h[Sangue Putrido]|h|r.', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_CANNIBALIZE.BLP:20|t Usa |cFFFF0404|Hspell:263235|h[Banchetto di Sangue]|h|r per purificare i tuoi accumuli di |cFFFF0404|Hspell:263227|h[Sangue Putrido]|h|r.', 28153),
(161922, 'itIT', 'Vola in alto oltre la tempesta. Lascia che siano gli altri a bagnarsi.', '', 28153),
(161921, 'itIT', '', 'Ce l\'abbiamo fatta! Torniamo a Roccavento e facciamo rapporto al Re.', 28153),
(161920, 'itIT', '', 'Abbiamo deciso di sfruttare le riparazioni dell\'Incudine Nera per fare dei miglioramenti.', 28153),
(161919, 'itIT', '', 'Continuerò a dare la caccia al nemico fin quando vinceremo questa guerra, $n.\n\nLo giuro in nome di tutti coloro che sono morti a Teldrassil.\n\n<Shandris abbassa la testa in segno di preghiera.>', 28153),
(161918, 'itIT', '', 'Cavalca le correnti. Affronta la tempesta!', 28153),
(161917, 'itIT', 'Ritorna alla Porta Insanguinata.', 'Ritorna alla Porta Insanguinata.', 28153),
(161916, 'itIT', 'Non posso dire di essere un grande amante delle barche, ma è incredibile cosa tu sia $griuscito:riuscita; a immagazzinare qua sotto.\n\nSe trovassi altre antiche reliquie degne di nota, sarò felice di dargli un\'occhiata.\n\nE porte. Porte misteriose. Le porte misteriose dei Titani sono la mia specialità!', '', 28153),
(161915, 'itIT', '', 'Halford ha degli appunti molto interessanti. Rapporti di combattimento, movimenti delle truppe...\n\n<Kelsey dà un\'occhiata alla porta e si avvicina per sussurrarti qualcosa.>\n\nE potrei aver trovato il suo diario privato!\n\n<Kelsey ammicca in segno di approvazione.>', 28153),
(161914, 'itIT', '', 'Non vuoi andartene senza i tuoi amici, vero?', 28153),
(161913, 'itIT', 'È un onore combattere al fianco di soldati dell\'Alleanza forti e onesti ancora una volta. Mi ricorda i giorni in cui stavo nella Compagnia Bravo.\n\n<Gli occhi di Keeshan sembrano fissare un punto in lontananza.>\n\nAbbi sempre la tua arma pronta, $n, e tienine una nascosta in caso di cattura. In qualche posto in cui non cercherebbero mai.', '', 28153),
(161912, 'itIT', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Flussafumi sta lanciando |cFFFF0000|Hspell:259940|h[Esplosione Propellente]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Flussafumi sta lanciando |cFFFF0000|Hspell:259940|h[Esplosione Propellente]|h|r!', 28153),
(161911, 'itIT', 'La mia gente si è allenata molto per perfezionare le proprie abilità.\n\n<Umbric strizza gli occhi.>\n\nI sussurri parlano di molte possibilità e saremo pronti a qualsiasi evenienza.', '', 28153),
(161910, 'itIT', 'Sì. Avevo dei dubbi su tutto questo, ma pare che le cose siano andate per il meglio.', '', 28153),
(161909, 'itIT', 'È un bel giorno per essere un Ferroscuro!', '', 28153),
(161908, 'itIT', '', 'L\'ultimo colpo spetta a te, $p.', 28153),
(161907, 'itIT', '', 'Che bella sensazione essere di nuovo in guerra, $n. Ma devo ammettere che guarire i feriti sta cominciando a diventare stancante. Ci sono modi migliori per sfruttare i miei talenti.\n\nMolte delle tecniche che noi Forgialuce abbiamo usato contro la Legione possono essere utilizzate anche contro l\'Orda.\n\nInforma gentilmente il Gran Comandante che mi assicurerò che ogni prigioniero catturato venga adeguatamente... \"purificato\".', 28153),
(161906, 'itIT', '', 'Non sono sorpresa che Jaina Marefiero abbia scelto di tornare a casa.\n\nUna ferita trascurata non può guarire e la sua è davvero grave.', 28153),
(161905, 'itIT', 'Il Guardiano del Cuore si muove per attaccarti!', 'Il Guardiano del Cuore si muove per attaccarti!', 28153),
(161904, 'itIT', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t Merektha sta per colpirti con |cFFFF0000|Hspell:263914|h[Sabbia Accecante]|h|r, distogli lo sguardo!', '|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|t Merektha sta per colpirti con |cFFFF0000|Hspell:263914|h[Sabbia Accecante]|h|r, distogli lo sguardo!', 28153),
(161903, 'itIT', '', 'Sono pronta quando vuoi, $n. Parla con me quando desideri partire per i Sotterranei di Roccianera.', 28153),
(161902, 'itIT', '', 'Sai cosa dobbiamo fare, $n. È ora di muoversi.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161901, 'itIT', '|cFF0000FF(Missione)|r Sono pronto a raggiungere le Terre del Fuoco.', '|cFF0000FF(Missione)|r Sono pronta a raggiungere le Terre del Fuoco.', 28153),
(161900, 'itIT', '', 'Vieni, $n. Dobbiamo ucciderla.', 28153),
(161899, 'itIT', 'Non si aspetteranno di trovarci qui a Vol\'dun, ma presto inizieranno a chiedersi chi sta uccidendo i loro agenti.', '', 28153),
(161898, 'itIT', 'Dobbiamo muoverci in fretta, $n. L\'Orda non sa che siamo già sbarcati.', '', 28153),
(161897, 'itIT', 'Piazzerà quelle bombe e tornerà in men che non si dica.', '', 28153),
(161896, 'itIT', 'Potrebbe non sembrare, ma può cavarsela benissimo da solo in combattimento e la sua esperienza in demolizioni non è seconda a nessuno.', '', 28153),
(161895, 'itIT', 'Non temere, ho già lavorato con Guzbert in passato. È un professionista.', '', 28153),
(161894, 'itIT', 'Se la Luce vorrà, li fermeremo.', '', 28153),
(161893, 'itIT', 'Vendono tutto ciò che non possono sfruttare e i ricavi finiscono col finanziare la campagna dell\'Orda.', '', 28153),
(161892, 'itIT', 'Tuttavia, sarebbe un grave errore. Quei farabutti sono famosi per aver riportato alla luce potenti artefatti e averli scatenati contro i loro nemici.', '', 28153),
(161891, 'itIT', 'È facile sottovalutare Mirasole e il Circolo del Reliquiario. Voglio dire... sono archeologi, dopotutto.', '', 28153),
(161890, 'itIT', '|cFF0000FF(Missione)|r Sono pronto a raggiungere i Sotterranei di Roccianera.', '|cFF0000FF(Missione)|r Sono pronta a raggiungere i Sotterranei di Roccianera.', 28153),
(161889, 'itIT', '', 'È troppo pericoloso mettere piede ad Arathi al momento.$B$BL\'accesso al portale verrà ripristinato non appena riavremo il controllo di Stromgarde.', 28153),
(161888, 'itIT', 'Cosa sappiamo degli Orchi Mag\'har?', 'Cosa sappiamo degli Orchi Mag\'har?', 28153),
(161887, 'itIT', 'Cosa mi sai dire sui Nani Ferroscuro?', 'Cosa mi sai dire sui Nani Ferroscuro?', 28153),
(161886, 'itIT', 'Quando sarò grande, voglio essere proprio come Nisha! È la migliore!\n\nO magari Kiro! È così intelligente...\n\nO forse Meerah, che è così gentile...\n\nO magari Jena! Sa fare un sacco di cose...\n\nO magari...\n\n<Rudo continua a elencare i nomi degli altri Vulpera nell\'accampamento.>', '', 28153),
(161885, 'itIT', '', 'È troppo pericoloso mettere piede ad Arathi al momento.$B$BL\'accesso al portale verrà ripristinato non appena riavremo il controllo di Ar\'gorok.', 28153),
(161884, 'itIT', '', 'Ti andrebbe una bella birra rinfrescante?', 28153),
(161883, 'itIT', 'Ti auguro proficui commerci! Non si può vincere senza!', '', 28153),
(161882, 'itIT', 'Ehi $gamico:amica;, abbiamo della bella roba.', 'Oh, spero ti piacciano le mie invenzioni!', 28153),
(161881, 'itIT', 'Ho delle armi e armature appena forgiate da offrirti!', '', 28153),
(161880, 'itIT', '', 'Forniture commerciali direttamente da Roccavento!', 28153),
(161879, 'itIT', 'Ti offro strumenti dell\'oscurità.', '', 28153),
(161878, 'itIT', 'Ho dei manufatti magici che potresti trovare interessanti.', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(161877, 'itIT', 'Birre in vendita!', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(161876, 'itIT', 'I Mag\'har sono al tuo fianco. Sangue e tuono!', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(161875, 'itIT', 'Ehi, voi ragazzi volete degli esplosivi? Ho proprio quello che cercate.', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(161874, 'itIT', 'Lok\'tar! Ho a disposizione forniture commerciali provenienti direttamente da Orgrimmar.', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(161873, 'itIT', 'Ho bella roba da vendere! Ti porterà tanta fortuna!', 'Ho bella roba da vendere! Ti porterà tanta fortuna!', 28153),
(161872, 'itIT', 'Si dice che Elisande avesse perfezionato incantesimi conosciuti solo ai Draghi di Bronzo. Forse potrebbero essere disposti ad aiutare la tua causa.', '', 28153),
(161871, 'itIT', 'La magia temporale era la specialità della nostra ex Gran Magistra Elisande. Molto di ciò che sapeva è morto con lei.', '', 28153),
(161870, 'itIT', 'Devo infiltrarmi nell\'Accademia dei Marefiero.', 'Devo infiltrarmi nell\'Accademia dei Marefiero.', 28153),
(161869, 'itIT', 'Devo infiltrarmi nella Caserma dei Marefiero.', 'Devo infiltrarmi nella Caserma dei Marefiero.', 28153),
(161868, 'itIT', '', 'Per l\'Alleanza!', 28153),
(161867, 'itIT', 'Manterremo la posizione mentre tu avanzerai. Per l\'Alleanza!', '', 28153),
(161866, 'itIT', 'Siamo con le spalle al muro, immobilizzati da un oceano colmo di navi nemiche.', '', 28153),
(161865, 'itIT', 'Temo di dover concordare con la Gnoma, $p.', '', 28153),
(161864, 'itIT', '', 'Ehi!', 28153),
(161863, 'itIT', '%s scappa verso le Paludi Gracidanti.', '%s scappa verso le Paludi Gracidanti.', 28153),
(161862, 'itIT', 'Questo parlerà. Almeno ha ancora la lingua, non come quei luridi Reietti.', '', 28153),
(161861, 'itIT', '', 'Diamoci una mossa, $p! Parla con il capitano della nave, così potremo partire!', 28153),
(161860, 'itIT', '', 'A volte vorrei tanto essere una macchina...', 28153),
(161859, 'itIT', '', 'Macchine... <Sospira>', 28153),
(161858, 'itIT', 'Hai i tuoi ordini. Puoi andare.', '', 28153),
(161857, 'itIT', 'Esamina gli accampamenti e fai rapporto sulle tue scoperte.', '', 28153),
(161856, 'itIT', '', 'Ohhh! Nani Ferroscuro! Adoro i Nani Ferroscuro! Hanno un sacco di macchine!', 28153),
(161855, 'itIT', 'Ti incontrerai con il Thane della Forgia Thurgaden, lungo la costa sudorientale di Zuldazar.', '', 28153),
(161854, 'itIT', '', 'Sissignore!', 28153),
(161853, 'itIT', 'Kelsey!', '', 28153),
(161852, 'itIT', 'Il suo equipaggio si è imbattuto in qualche problema in mare, ma sono riusciti a distruggere un accampamento lungo la costa orientale.', '', 28153),
(161851, 'itIT', 'Incontrati con il Brigadiere Thom, uno dei nostri ufficiali della VII Legione.', '', 28153),
(161850, 'itIT', '$p!', '', 28153),
(161849, 'itIT', '', 'C\'è tanto cibo fresco all\'interno.', 28153),
(161848, 'itIT', 'Abbiamo già messo piede non su una, ma su ben due posizioni a Zuldazar.', '', 28153),
(161847, 'itIT', 'Radunatevi, tutti quanti. Ecco il piano.', '', 28153),
(161846, 'itIT', 'Finirai... nella prigione dei Marefiero...', '', 28153),
(161845, 'itIT', '', 'Feccia... dell\'Orda...', 28153),
(161844, 'itIT', 'Recupereremo il corpo di Derek... in un modo o nell\'altro...', '', 28153),
(161843, 'itIT', '', 'Non riuscirai mai a padroneggiare il vero potere dei nostri insegnamenti...', 28153),
(161842, 'itIT', 'Verrai $gspazzato:spazzata; via...', '', 28153),
(161841, 'itIT', 'Vai. Torna da Oculeth. Ora che il frammento è ripristinato, può mandarti nel posto che cerchi.', '', 28153),
(161840, 'itIT', 'In caso ci fosse qualche dubbio, non avrei mai permesso al frammento di cadere nelle mani sbagliate. Non di nuovo.', '', 28153),
(161839, 'itIT', 'Percepisco i fili del destino su di te. Sei davvero $gdegno:degna; di ciò che accadrà.', '', 28153),
(161838, 'itIT', 'Anche sotto forma di eco del passato, Garrosh era un formidabile nemico.', '', 28153),
(161837, 'itIT', 'Ciò che hai visto qui è stata una delle sue peggiori incarnazioni possibili. Che spreco.', '', 28153),
(161836, 'itIT', 'Era visto come un eroe dalla sua gente in innumerevoli potenziali linee temporali. Alcuni lo definirono come il più grande Capoguerra dell\'Orda.', '', 28153),
(161835, 'itIT', 'Garrosh Malogrido... È un peccato come siano andate le cose.', '', 28153),
(161834, 'itIT', 'Credi che io tenga paura di te?', '', 28153),
(161833, 'itIT', 'Dicci tutto, Zandalari.', 'Dicci tutto, Zandalari.', 28153),
(161832, 'itIT', 'Vuoi sentire la storia mia?\n\nStavo sulla nave ammiraglia e ho visto tutto quanto.\n\nVa bene, ti dirò cos\'è successo. È meglio che tu lo sappia, così conoscerai la paura pure te.', '', 28153),
(161831, 'itIT', 'Andiamo, dobbiamo raggiungere il Tempio della Tigre Bianca.', '', 28153),
(161830, 'itIT', 'Gul\'dan non mancherà a nessuno... né in questa, né in qualsiasi altra linea temporale.', '', 28153),
(161829, 'itIT', 'Nonostante sia solo un\'eco di questo vecchio nemico di Azeroth, sappi che morire per mano di quest\'entità sarebbe più reale di ciò che pensi.', '', 28153),
(161828, 'itIT', 'Fu qui che Gul\'dan viaggiò tra un mondo e l\'altro con l\'aiuto della Visione del Tempo.', '', 28153),
(161827, 'itIT', 'Gli echi della magia riverberano attraverso le linee temporali.', '', 28153),
(161826, 'itIT', 'Anche in questo momento posso... Aspetta, cos\'è quello?', '', 28153),
(161825, 'itIT', 'In questa sala, il Cuore di Azeroth può diventare ancora più forte!', '', 28153),
(161824, 'itIT', 'La Sala del Cuore ora ha un aspetto decisamente migliore dall\'ultima volta che sei $gstato:stata; qui, vero?', '', 28153),
(161823, 'itIT', 'Non possiamo però abbandonarci alla disperazione. So che possiamo respingere quest\'ondata di oscurità!', '', 28153),
(161822, 'itIT', 'Temo che ci sia ancora molta strada da fare, $n. Le cose sembrano non fare altro che peggiorare.', '', 28153),
(161821, 'itIT', 'Lo percepisci? Il potere del cuore continua a crescere!', '', 28153),
(161820, 'itIT', 'Ricordati le mie parole: il Signore del Fuoco ritornerà. Ci rivedremo allora... amico mio.', '', 28153),
(161819, 'itIT', 'Ah, ora sì che ci siamo... Il profumo del fuoco la mattina... a mezzogiorno e di notte. Dobbiamo addentrarci nella tana del Signore del Fuoco per caricare quel Frammento del Nucleo Ardente.', '', 28153),
(161818, 'itIT', 'Farò cercare Tetrapietra ai nostri migliori esploratori. Dobbiamo fermare quel folle prima che altri seguaci si uniscano alla sua causa!', '', 28153),
(161817, 'itIT', 'Vuoi davvero saltare le missioni introduttive di Kul Tiras?', 'Vuoi davvero saltare le missioni introduttive di Kul Tiras?', 28153),
(161816, 'itIT', 'Conosco già questa storia... <Salta le missioni introduttive di Kul Tiras e inizia il tuo viaggio a Boralus.>', 'Conosco già questa storia... <Salta le missioni introduttive di Kul Tiras e inizia il tuo viaggio a Boralus.>', 28153),
(161815, 'itIT', 'Usa il suo potere con saggezza, $n. E fai attenzione... c\'è gente là fuori che non desidera altro che tu fallisca!', '', 28153),
(161814, 'itIT', 'Man mano che recupererà le forze, lo stesso farà il Cuore di Azeroth che hai attorno al collo!', '', 28153),
(161813, 'itIT', 'Azeroth sta ancora soffrendo, ma grazie ai tuoi sforzi sta riuscendo a resistere.', '', 28153),
(161812, 'itIT', 'D\'accordo, pensiamo al ponte. Credo di conoscere l\'incantesimo giusto...', '', 28153),
(161811, 'itIT', 'Così dovrebbe bastare! Andiamocene da qui.', '', 28153),
(161810, 'itIT', 'Ma pensiamo alle cose importanti. Dobbiamo caricare quel Frammento del Nucleo Ardente in modo da riparare l\'Incudine Nera.', '', 28153),
(161809, 'itIT', 'Pessime notizie, $p. Tetrapietra e i suoi fanatici vogliono riportare in vita Ragnaros... Non pensavo sarebbe arrivato a tanto.', '', 28153),
(161808, 'itIT', 'Mostrami gli eventi che hanno portato l\'Alleanza a Silitus.', 'Mostrami gli eventi che hanno portato l\'Alleanza a Silitus.', 28153),
(161807, 'itIT', 'Mostrami gli eventi che hanno portato l\'Orda a Silitus.', 'Mostrami gli eventi che hanno portato l\'Orda a Silitus.', 28153),
(161806, 'itIT', 'Continuate a portarne.', '', 28153),
(161805, 'itIT', 'Ho ancora sete!', '', 28153),
(161804, 'itIT', 'Ancora una!', '', 28153),
(161803, 'itIT', 'Un\'altra!', '', 28153),
(161802, 'itIT', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t Hadal crea una |cFFFF0000|Hspell:276068|h[Inoculazione Mareale]|h|r!', '|TInterface\\ICONS\\Spell_Shaman_TidalWaves.blp:20|t Hadal crea una |cFFFF0000|Hspell:276068|h[Inoculazione Mareale]|h|r!', 28153),
(161801, 'itIT', 'Molto bene, non perdiamo tempo coi convenevoli, allora.', '', 28153),
(161800, 'itIT', 'È proprio quello che farò!', '', 28153),
(161799, 'itIT', 'Quando il vero Signore del Fuoco risorgerà, tutti i Ferroscuro fedeli risponderanno alla sua chiamata. Intendi forse opporti a noi?', '', 28153),
(161798, 'itIT', 'Pensi che quell\'ammasso di braci che hai raccolto lo impressionerà? Abbiamo già fatto fuori la maggior parte dei tuoi cultisti mentre arrivavamo qui.', '', 28153),
(161797, 'itIT', 'A Thaurissan non mancava certo l\'ardore, ma nella sua follia stava cercando di controllare il Signore del Fuoco. Invece, noi dobbiamo servirlo in tutto e per tutto.', '', 28153),
(161796, 'itIT', 'Ragnaros?!? Vuoi riportare indietro quel tiranno? Quando il Thane Occultista ci ha provato...', '', 28153),
(161795, 'itIT', 'Legittima sovrana? Nelle vene di Moira non scorre alcun fuoco. Il nostro legittimo sovrano è il Signore del Fuoco, non un Barbabronzea... e nemmeno un pretendente al suo trono.', '', 28153),
(161794, 'itIT', 'Va bene. Fa\' attenzione, Alfiere. Stai calunniando la nostra legittima sovrana.', '', 28153),
(161793, 'itIT', 'Mostra un po\' di rispetto! Usa il mio titolo quando ti rivolgi a me!', '', 28153),
(161792, 'itIT', 'Fa\' attenzione a parlare così, Harrold. Sei tra l\'incudine e il martello.', '', 28153),
(161791, 'itIT', 'Ogni cosa a suo tempo, Thane della Forgia. Sai bene quanto me che la Regina Reggente è debole.', '', 28153),
(161790, 'itIT', 'Tetrapietra... Che cosa sta succedendo qui? Dov\'è Ardiron?', '', 28153),
(161789, 'itIT', 'Ehi, capo!', '', 28153),
(161788, 'itIT', 'IL THANE DELLA FORGIA THURGADEN È QUI! AVVERTITE IL GRAN GIUDICE TETRAPIETRA!', 'IL THANE DELLA FORGIA THURGADEN È QUI! AVVERTITE IL GRAN GIUDICE TETRAPIETRA!', 28153),
(161786, 'itIT', 'Ora basta! Sputa la verità, forza!', '', 28153),
(161785, 'itIT', 'Uh... be\', vedi...', 'Uh... be\', vedi...', 28153),
(161784, 'itIT', 'Chi ha ordinato di chiudere l\'accesso al ponte? Chi è che comanda qui?', '', 28153),
(161783, 'itIT', 'Thane della Forgia?!?', 'Thane della Forgia?!?', 28153),
(161782, 'itIT', 'Che significa tutto questo?', '', 28153),
(161781, 'itIT', 'Salutate il mio piccolo amico!', '', 28153),
(161780, 'itIT', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 'This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN\'T a--dreadlord, really?', 28153),
(161779, 'itIT', '<Non è chiaro come sia morto il mercante, ma è alla mercé dei corvi da molto tempo ormai.>', '', 28153),
(161774, 'itIT', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t Il kraken risveglia un |cFFFF0000|Hspell:279897|h[Terrore dagli Abissi]|h|r!', '|TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SHARK JAWS.BLP:20|t Il kraken risveglia un |cFFFF0000|Hspell:279897|h[Terrore dagli Abissi]|h|r!', 28153),
(161773, 'itIT', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t Gli squali fiutano |cFFFF0000|Hspell:279893|h[Odore di Sangue]|h|r!', '|TInterface\\ICONS\\INV_Pet_BabyShark.blp:20|t Gli squali fiutano |cFFFF0000|Hspell:279893|h[Odore di Sangue]|h|r!', 28153),
(161772, 'itIT', 'Ti ammirava per questo... e anche io provo lo stesso.', '', 28153),
(161771, 'itIT', 'Immagino fosse troppo sperare che avrebbero perdonato Jaina. Il suo destino incerto è preoccupante, ma dobbiamo rimanere concentrati sulla missione.\n\nDobbiamo far entrare Kul Tiras nell\'Alleanza. Se Katherine Marefiero non ha intenzione di ascoltarci, questi simpatizzanti potrebbero essere la nostra occasione migliore.', '', 28153),
(161770, 'itIT', 'Hrkk...', '', 28153),
(161769, 'itIT', 'L\'Alleanza? Qui?', '', 28153),
(161768, 'itIT', '', 'La mia vita per l\'archeologia...', 28153),
(161767, 'itIT', '', 'Teneteli lontani dal sito di scavo!', 28153),
(161766, 'itIT', 'Il Circolo del Reliquiario mi vendicherà...', '', 28153),
(161765, 'itIT', '', 'Devo avvisare... Mirasole...', 28153),
(161764, 'itIT', '', 'Ehi! Questo è territorio dell\'Orda! Non dovresti essere qui!', 28153),
(161763, 'itIT', 'Tu continua a combattere, capo! Io... aspetterò qui.', '', 28153),
(161762, 'itIT', 'Porteremo l\'Orda alla vittoria!', 'Porteremo l\'Orda alla vittoria!', 28153),
(161761, 'itIT', 'Ci vediamo al fronte.', 'Ci vediamo al fronte.', 28153),
(161760, 'itIT', 'Sei $gpronto:pronta; a prendere il largo?', 'Sei $gpronto:pronta; a prendere il largo?', 28153),
(161759, 'itIT', 'I nemici tremeranno di fronte a noi.', 'I nemici tremeranno di fronte a noi.', 28153),
(161758, 'itIT', 'La battaglia attende!', 'La battaglia attende!', 28153),
(161757, 'itIT', 'Questa dannata guerra è andata avanti fin troppo a lungo!', 'Questa dannata guerra è andata avanti fin troppo a lungo!', 28153),
(161756, 'itIT', 'Mi accoglierai tra i tuoi rami, Antico?', 'Mi accoglierai tra i tuoi rami, Antico?', 28153),
(161755, 'itIT', 'Perché l\'Orda non ci lascia stare?', 'Perché l\'Orda non ci lascia stare?', 28153),
(161754, 'itIT', 'Cittadini di Boralus, volgete lo sguardo sulle maree e osservate!', '', 28153),
(161753, 'itIT', 'I miei Granmartello attireranno l\'attenzione dell\'Orda su quella nave, mentre noi penseremo a Dreven a bordo dell\'altra.', '', 28153),
(161752, 'itIT', 'Sono pronto per tornare a Boralus.', 'Sono pronta per tornare a Boralus.', 28153),
(161751, 'itIT', '', 'La caccia è finita e il mondo è più sicuro.\n\nOggi è un bel giorno.', 28153),
(161750, 'itIT', 'Alla battaglia!', 'Alla battaglia!', 28153),
(161749, 'itIT', 'Fai strada.', 'Fai strada.', 28153),
(161748, 'itIT', 'Bene! Ora mettiamoci al lavoro.', 'Bene! Ora mettiamoci al lavoro.', 28153),
(161747, 'itIT', 'Combatterò al tuo fianco.', 'Combatterò al tuo fianco.', 28153),
(161746, 'itIT', 'Sono in debito con te, $n.', 'Sono in debito con te, $n.', 28153),
(161745, 'itIT', 'Ohhh, fantastico! Grazie mille, $p!', '', 28153),
(161744, 'itIT', '<Vuoi consegnare la Lettera di Rosaline ad Ancel Mildenhall?>', '<Vuoi consegnare la Lettera di Rosaline ad Ancel Mildenhall?>', 28153),
(161743, 'itIT', 'Abbiamo a che fare con un attacco dei Trogg! Salta in sella a Cooper e dai loro una lezione!', '', 28153),
(161742, 'itIT', 'Addio!', 'Addio!', 28153),
(161741, 'itIT', '', 'Sì. Mi mancano da morire e non vedo l\'ora di tornare a casa. Sono sicura che Raimond stia facendo del suo meglio, ma bisogna ammettere che un talento innato per incasinare qualunque cosa!', 28153),
(161740, 'itIT', 'Questo dovrebbe tenerti al caldo.', '', 28153),
(161739, 'itIT', 'Quel completo andrà bene.', '', 28153),
(161738, 'itIT', 'Forse quei vestiti miglioreranno le tue abilità di raccolta.', '', 28153),
(161737, 'itIT', 'Ti vedo bene, $n.', '', 28153),
(161736, 'itIT', 'Lancio Dardo di Gelo nell\'oscurità!', 'Lancio Dardo di Gelo nell\'oscurità!', 28153),
(161735, 'itIT', 'Grazie. Prometto che stavolta la consegnerò!', 'Grazie. Prometto che stavolta la consegnerò!', 28153),
(161734, 'itIT', 'Non versare la birra sulla mia scheda del personaggio!', 'Non versare la birra sulla mia scheda del personaggio!', 28153),
(161733, 'itIT', 'Io prendo la candela.', 'Io prendo la candela.', 28153),
(161732, 'itIT', 'Sì?', '', 28153),
(161731, 'itIT', 'Sarebbe più facile guarirti se non stessi nel fuoco tutto il tempo.', 'Sarebbe più facile guarirti se non stessi nel fuoco tutto il tempo.', 28153),
(161730, 'itIT', 'L\'ho... ehm... dimenticata da qualche parte. Posso averne un\'altra copia, per piacere?', 'L\'ho... ehm... dimenticata da qualche parte. Posso averne una copia, per piacere?', 28153),
(161729, 'itIT', 'La guardia mi vede depredare questo cadavere?', 'La guardia mi vede depredare questo cadavere?', 28153),
(161728, 'itIT', 'Finiscila di minacciare chi ti dà le missioni!', 'Finiscila di minacciare chi ti dà le missioni!', 28153),
(161727, 'itIT', 'No, l\'albero non è vulnerabile agli attacchi di fuoco.', 'No, l\'albero non è vulnerabile agli attacchi di fuoco.', 28153),
(161726, 'itIT', 'Te l\'ho già detto, il bardo non è una classe!', 'Te l\'ho già detto, il bardo non è una classe!', 28153),
(161725, 'itIT', '', 'Salve, $p. Non mi aspettavo di rivederti così presto. Come ha reagito Ancel alla mia lettera?', 28153),
(161724, 'itIT', '', 'Maledizione... $p, spero davvero che non sia una tua abitudine quella di perdere le cose. Aspetta un momento... te ne farò un altro.', 28153),
(161723, 'itIT', 'Vuoi dare a Rosaline l\'Amuleto del Miele Ritemprato?', 'Vuoi dare a Rosaline Mildenhall l\'Amuleto del Miele Ritemprato?', 28153),
(161722, 'itIT', '', 'Ah... Altro giorno, altra vittima.', 28153),
(161721, 'itIT', '', 'Aspetta... Hai detto di aver conosciuto Ancel e Raimond?', 28153),
(161720, 'itIT', 'Be\'... è una lunga storia, ma era conficcato in una specie di abominio vivente fatto di miele. L\'ho trovato mentre aiutavo Ancel e Raimond a ripulire la fattoria.', 'Be\'... è una lunga storia, ma era conficcato in una specie di abominio vivente fatto di miele. L\'ho trovato mentre aiutavo Ancel e Raimond a ripulire la fattoria.', 28153),
(161719, 'itIT', 'Ho trovato questo amuleto, è tuo?', 'Ho trovato questo amuleto, è tuo?', 28153),
(161718, 'itIT', '', 'Come posso aiutarti, $gamico:amica;? Hai qualche oggetto arcano da identificare?', 28153),
(161717, 'itIT', 'Siamo quasi pronti a riparare l\'Incudine Nera. Ora dobbiamo solo caricare il Frammento del Nucleo con l\'essenza di Ragnaros.', '', 28153),
(161716, 'itIT', '|cFF0000FF(Missione)|r Sono pronto a raggiungere il Nucleo Ardente.', '|cFF0000FF(Missione)|r Sono pronta a raggiungere il Nucleo Ardente.', 28153),
(161715, 'itIT', 'Bene, ora andiamocene da qui. La trivella dovrebbe riportarci a Roccavento tutti interi.', '', 28153),
(161714, 'itIT', 'Riprenditeli, fratello.', '', 28153),
(161713, 'itIT', 'Non sei mai stato al mio livello.', '', 28153),
(161712, 'itIT', 'È difficile dire di chi dei due sia più deluso.', '', 28153),
(161711, 'itIT', 'Cosa credi che penserebbe nostro padre di quello che siamo diventati, fratello?', '', 28153),
(161710, 'itIT', 'Staremo a vedere, fratello.', '', 28153),
(161709, 'itIT', 'Non conterai mai nulla.', '', 28153),
(161708, 'itIT', 'Sembra che dovremo proseguire a piedi da qui in poi.', '', 28153),
(161707, 'itIT', 'Be\', succede. Per fortuna ne ho qualcuno di riserva.', '', 28153),
(161706, 'itIT', 'SINISTRA! DESTRA! SINISTRA... LAVA!', '', 28153),
(161705, 'itIT', 'Argh! Non credo riuscirò mai a ripulire questi vestiti dalla sabbia.', '', 28153),
(161704, 'itIT', 'Attenzione!', '', 28153),
(161703, 'itIT', 'Ancora un po\' per riempire il carico e poi ci potremo finalmente lasciare questa dannata costa... e quest\'odore... alle spalle.', '', 28153),
(161702, 'itIT', 'Comunque, il mio Capro Armato dovrebbe rendere le cose un po\' più semplici. Aspetta un attimo, è quasi pronto.', '', 28153),
(161701, 'itIT', 'Senza contare che dovremo avere a che fare con Gezzrok per ottenere un pezzo di Nucleo.', '', 28153),
(161700, 'itIT', 'Potrebbero lavorare a ritmi un po\' più alti?', '', 28153),
(161699, 'itIT', 'L\'unico problema è che dovremo sbarazzarci di qualche bestia ardente per arrivare al vecchio Antro di Ragnaros.', '', 28153),
(161698, 'itIT', 'D\'accordo, $n, forse pensi che sia un\'operazione semplice e veloce. Be\', non ti sbagli di molto.', '', 28153),
(161697, 'itIT', 'Se la tua ciurma sarà in grado di raggiungere un livello anche leggermente superiore al mediocre, ne sarò impressionato.', '', 28153),
(161696, 'itIT', 'Vi consiglio di mantenere la concentrazione sul compito che vi è stato affidato.', '', 28153),
(161695, 'itIT', 'Francamente, le idee politiche del vostro... capo... non mi riguardano minimamente e nemmeno coloro che rappresento.', '', 28153),
(161694, 'itIT', 'Sì, sì... Ho capito.', '', 28153),
(161693, 'itIT', 'A nessuno interessa vederlo!', '', 28153),
(161692, 'itIT', 'Ehi, sacchi d\'immondizia, se continuiamo a perdere membri dell\'equipaggio e la nostra attrezzatura continua a rompersi, vi toccherà trasportare l\'Azerite con le vostre gracili gambe da Elfi.', '', 28153),
(161691, 'itIT', 'Già, non te ne importa niente.', '', 28153),
(161690, 'itIT', 'Sì, hai ragione. Le mie scuse, $n.', '', 28153),
(161689, 'itIT', '', 'Sappiamo tutti che hai una scorta quasi infinita di minerali alla Tesoreria Oscura.', 28153),
(161688, 'itIT', '', 'Non essere così avido, Thaelin. $n dovrà svolgere dei compiti molto importanti.', 28153),
(161687, 'itIT', 'L\'Incudine Nera è stata costruita soltanto con il ferroscuro più puro, fuso e raffinato con i segreti che ho rivelato soltanto ai nostri minatori e fabbri più fedeli.', '', 28153),
(161686, 'itIT', 'Ci serviranno tonnellate di ferroscuro per riparare quella roba!', '', 28153),
(161685, 'itIT', '', 'Si capisce benissimo che c\'è Volrath dietro a tutta quest\'Orda che gironzola per Kul Tiras.\n\nPrima Ashran, poi quella dannata isola al largo di Feralas e ora qui... È come un brutto raffreddore che non vuole andarsene.', 28153),
(161684, 'itIT', 'Immagino che duellare sia un buon modo per affinare le proprie tecniche di combattimento...\n\nPer quanto mi riguarda, quelli dell\'Alleanza sono degli ottimi bersagli.', 'Immagino che duellare sia un buon modo per affinare le proprie tecniche di combattimento...\n\nPer quanto mi riguarda, quelli dell\'Alleanza sono degli ottimi bersagli.', 28153),
(161683, 'itIT', 'Incontriamoci a bordo della Lamento della Banshee al Porto di Zandalar.', '', 28153),
(161682, 'itIT', 'Torna in formazione!', 'Torna in formazione!', 28153),
(161681, 'itIT', 'Il nostro prossimo gruppo di rinforzi si sta preparando a partire.', 'Il nostro prossimo gruppo di rinforzi si sta preparando a partire.', 28153),
(161680, 'itIT', 'Rispondi al richiamo della battaglia.', 'Rispondi al richiamo della battaglia.', 28153),
(161679, 'itIT', 'Questo è ciò per cui ci siamo addestrati.', 'Questo è ciò per cui ci siamo addestrati.', 28153),
(161678, 'itIT', 'La battaglia attende.', 'La battaglia attende.', 28153),
(161677, 'itIT', 'Bene, $n. Prendi un pezzo di quel Nucleo e poi potremo tornare alle caverne sopra di noi. Io preparo la trivella, intanto.', '', 28153),
(161676, 'itIT', '$gUn abile:Un\'abile; $C come te sarebbe un\'ottima aggiunta ai nostri ranghi.', '$gUn abile:Un\'abile; $C come te sarebbe un\'ottima aggiunta ai nostri ranghi.', 28153),
(161675, 'itIT', 'Preparati alla battaglia.', 'Preparati alla battaglia.', 28153),
(161674, 'itIT', 'Bene!', '', 28153),
(161673, 'itIT', 'Capisco. Sconfiggetemi e potrete andarvene con un frammento del Nucleo.', '', 28153),
(161672, 'itIT', 'Ci serve un Frammento del Nucleo Ardente per riparare l\'Incudine Nera.', '', 28153),
(161671, 'itIT', 'Che cosa cerchi, figlio del fuoco?', '', 28153),
(161670, 'itIT', 'Thaelin Forgiacupa del clan dei Nani Ferroscuro.', '', 28153),
(161669, 'itIT', 'Chi osa avvicinarsi?', '', 28153),
(161668, 'itIT', 'Bene, vi siete guadagnati un Frammento del Nucleo Ardente. Usatelo con saggezza.', '', 28153),
(161667, 'itIT', 'Fremilama crede di essere più furba di noi, con la sua banda di sciocchi dell\'Alleanza.\n\nLa sua arroganza sarà la sua rovina.', '', 28153),
(161666, 'itIT', '', 'Non dirlo agli altri, ma credo che la recente scarsità di falchi sia un bene.\n\nNon ho nulla contro gli uccelli, ma mi sono affezionata a questi animaletti pelosi.\n\nSenza quei falchi, i miei conigli saranno molto più... vivi.', 28153),
(161665, 'itIT', 'Per l\'Alleanza!', 'E per i caduti... Elune-Adore.', 28153),
(161664, 'itIT', 'Ah, Falstad! Sei qui.', '', 28153),
(161663, 'itIT', 'Lasciate questo posto!', 'Lasciate questo posto!', 28153),
(161662, 'itIT', 'Non distruggerete queste terre!', 'Non distruggerete queste terre!', 28153),
(161661, 'itIT', 'Li spiriti... mi accolgono...', 'Li spiriti... mi accolgono...', 28153),
(161660, 'itIT', 'Nun riuscirai ad acciderci... tutti...', 'Nun riuscirai ad acciderci... tutti...', 28153),
(161659, 'itIT', 'Torno tra li spiriti...', 'Torno tra li spiriti...', 28153),
(161658, 'itIT', 'Chesto nun l\'avevo... previsto...', 'Chesto nun l\'avevo... previsto...', 28153),
(161657, 'itIT', 'L\'Orda... continuerà a vivere...', 'L\'Orda... continuerà a vivere...', 28153),
(161656, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(161655, 'itIT', 'Nun muoverti!', 'Nun muoverti!', 28153),
(161654, 'itIT', 'Sta per arrivare nu brutto juju verso di te!', 'Sta per arrivare nu brutto juju verso di te!', 28153),
(161653, 'itIT', 'Nessuno ci può fermare...', 'Nessuno ci può fermare...', 28153),
(161652, 'itIT', '', 'Troviamoci nei miei alloggi a Sepulcra, dove potremo discutere la nostra prossima mossa... con discrezione.', 28153),
(161651, 'itIT', 'Whisky? Non ho mai toccato quella roba.\n\nNo, io sono qui per i pretzel.', '', 28153),
(161650, 'itIT', 'Grazie, Magistro. Il tuo contributo sarà di grande aiuto.', '', 28153),
(161649, 'itIT', 'Condividerò volentieri qualsiasi dettaglio riesca a ricordare che possa aiutarli.', '', 28153),
(161648, 'itIT', 'Solo uno è il vero Gallywix e lo troveremo. Informerò Shaw delle esche.', '', 28153),
(161647, 'itIT', '', 'Un Gallywix bastava e avanzava, ma ora ne abbiamo... che dici, Halford, una dozzina?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161645, 'itIT', 'Qualcuno si occupi di $gquel dannato:quella dannata; $PR! E qualcun altro mi porti del burro di cacao sulla balconata!', '', 28153),
(161644, 'itIT', 'Sono pronto ad andare!', 'Sono pronta ad andare!', 28153),
(161643, 'itIT', 'È un bene che tu ce l\'abbia fatta, $n! Fammi sapere quando sei $gpronto:pronta; e ti porterò da Ulfar.', '', 28153),
(161642, 'itIT', 'Io le feste dei Goblin non le capisco proprio.', '', 28153),
(161641, 'itIT', 'Non parliamo mai più di questo posto.', '', 28153),
(161640, 'itIT', 'Quanta ingordigia e spreco di risorse, mentre altri Goblin muoiono di fame.', '', 28153),
(161639, 'itIT', 'Bleah, cos\'è quest\'olezzo mefitico?', '', 28153),
(161638, 'itIT', 'Non ho mai sentito il bisogno di una doccia tanto quanto ora.', '', 28153),
(161637, 'itIT', 'Non intingerei nemmeno un\'unghia in quella lurida pozza. Chissà cosa ci hanno fatto dentro.', '', 28153),
(161636, 'itIT', 'Ovviamente non fanno che gettare la spazzatura in acqua. Che volgarità.', '', 28153),
(161635, 'itIT', 'Un gran bell\'angolo di natura... rovinato da fiumi di erba artificiale.', '', 28153),
(161634, 'itIT', '<Il tuo corpo si appesantisce mentre i polmoni si riempiono di fumo...>', '<Il tuo corpo si appesantisce mentre i polmoni si riempiono di fumo...>', 28153),
(161633, 'itIT', '', 'Sono... felice che... che tu stia bene...', 28153),
(161632, 'itIT', '', 'Ehi... Ehi? Riesci a sentirmi?', 28153),
(161631, 'itIT', 'Le fiamme si sono estinte! Raggiungi il Tempio della Luna!', 'Le fiamme si sono estinte! Raggiungi il Tempio della Luna!', 28153),
(161630, 'itIT', 'Ishala! Ishala! Sei là fuori?!? Ti prego, Ishala... ascolta la mia voce!', 'Ishala! Ishala! Sei là fuori?!? Ti prego, Ishala... ascolta la mia voce!', 28153),
(161629, 'itIT', 'Non posso andarmene senza la mia bambina! Vi prego, qualcuno mi aiuti!', 'Non posso andarmene senza la mia bambina! Vi prego, qualcuno mi aiuti!', 28153),
(161628, 'itIT', 'Qualcuno mi ascolti! Aiutatemi a ritrovare la mia famiglia!', 'Qualcuno mi ascolti! Aiutatemi a ritrovare la mia famiglia!', 28153),
(161627, 'itIT', 'Vi prego! Aiutatemi! Non riesco a trovare mia figlia!', 'Vi prego! Aiutatemi! Non riesco a trovare mia figlia!', 28153),
(161626, 'itIT', 'Non buttarla via. Riportala a casa.', '', 28153),
(161625, 'itIT', 'A te è stata data un\'altra opportunità.', '', 28153),
(161624, 'itIT', 'Darei qualunque cosa per poter abbracciare ancora mio figlio.', '', 28153),
(161623, 'itIT', 'Non è tardi... se riesci a sentirla.', '', 28153),
(161622, 'itIT', '', 'È troppo tardi, ormai.', 28153),
(161621, 'itIT', 'Katherine, lei ti sta chiamando... devi raggiungerla.', '', 28153),
(161620, 'itIT', '', 'Genn... lei sta bruciando.', 28153),
(161619, 'itIT', '', 'La vedo... nei miei sogni.', 28153),
(161618, 'itIT', 'Tuttavia, ora sta soffrendo ancora di più, o sbaglio?', '', 28153),
(161617, 'itIT', 'Jaina non ha fatto che seguire il suo cuore... e ha sofferto per questo.', '', 28153),
(161616, 'itIT', '', 'Jaina ha tradito il regno...', 28153),
(161615, 'itIT', 'Hai ancora Jaina.', '', 28153),
(161614, 'itIT', '', 'Non mi è rimasto... nulla... Nessuno...', 28153),
(161613, 'itIT', '', 'Priscilla, la mia migliore amica... mi ha tradito.', 28153),
(161612, 'itIT', '', 'Non so più cosa fare, Daelin. Non so più in cosa credere... né di chi fidarmi.', 28153),
(161611, 'itIT', 'Lei, i Kul Tirani e l\'intera Alleanza, se devo.\n\nAmo l\'Orda e ho promesso a Thrall che l\'avrei difesa.\n\nNon importa chi ha dato inizio a questa guerra, combatterò fino alla vittoria... o fino alla morte.', '', 28153),
(161610, 'itIT', 'Darnassus non può essere distrutta... Non può finire così!', 'Darnassus non può essere distrutta... Non può finire così!', 28153),
(161609, 'itIT', 'Sia maledetta l\'Orda. Siano maledetti tutti!', 'Sia maledetta l\'Orda. Siano maledetti tutti!', 28153),
(161608, 'itIT', 'Non... capisco...', 'Non... capisco...', 28153),
(161607, 'itIT', 'Grazie! Spero che gli altri ce l\'abbiano fatta...', 'Grazie! Spero che gli altri ce l\'abbiano fatta...', 28153),
(161606, 'itIT', 'Affronterai Jaina Marefiero?', 'Affronterai Jaina Marefiero?', 28153),
(161605, 'itIT', 'Jaina Marefiero.\n\nUna volta prese la decisione di salvarci dalla tirannia di suo padre. Una decisione difficile che non potei che rispettare.\n\nNon riusciva però a dimenticare ciò che Malogrido fece a Theramore, incanalando il suo odio contro tutta l\'Orda.\n\nOra però ha esagerato. Ha ucciso troppi innocenti e la sua ricerca di vendetta deve essere fermata.', '', 28153),
(161604, 'itIT', 'Grazie... Non credevo che ce l\'avrei fatta.', 'Grazie... Non credevo che ce l\'avrei fatta.', 28153),
(161603, 'itIT', 'Sta bruciando tutto... Tutto...', 'Sta bruciando tutto... Tutto...', 28153),
(161602, 'itIT', 'Che Elune ti benedica...', 'Che Elune ti benedica...', 28153),
(161601, 'itIT', 'Che Elune ti benedica, $n.', 'Che Elune ti benedica, $n.', 28153),
(161600, 'itIT', 'Mandami a Boralus!', 'Mandami a Boralus!', 28153),
(161599, 'itIT', '', 'Salve, $C. Desideri tornare a Boralus?', 28153),
(161598, 'itIT', '', 'Salve, $C. Stai andando al fronte?', 28153),
(161597, 'itIT', '\"Tornata\"? A chi ti riferisci?', '\"Tornata\"? A chi ti riferisci?', 28153),
(161596, 'itIT', 'Non riesco... a respirare...', 'Non riesco... a respirare...', 28153),
(161595, 'itIT', 'Avevo instaurato un bel legame con gli altri Cacciatori del Sentiero Invisibile. Abbiamo combattuto per difendere una terra devastata, ma ora il corno di guerra sta suonando di nuovo.\n\nQuando ho sentito che era tornata... ho dovuto rispondere alla chiamata.', '', 28153),
(161594, 'itIT', 'Cosa ti porta in questo conflitto, Rexxar?', 'Cosa ti porta in questo conflitto, Rexxar?', 28153),
(161593, 'itIT', 'Vi prego, aiutatemi!', 'Vi prego, aiutatemi!', 28153),
(161592, 'itIT', 'Spegnete le fiamme! Qualcuno ci aiuti!', 'Spegnete le fiamme! Qualcuno ci aiuti!', 28153),
(161591, 'itIT', 'Pare che abbiamo un\'altra guerra da combattere.\n\nC\'è ben poco tempo da perdere in chiacchiere.', '', 28153),
(161590, 'itIT', 'Fa così... caldo...', 'Fa così... caldo...', 28153),
(161589, 'itIT', 'Perché sta accadendo tutto questo?!?', 'Perché sta accadendo tutto questo?!?', 28153),
(161588, 'itIT', 'AAAHHH!', 'AAAHHH!', 28153),
(161587, 'itIT', 'Acqua! Vi prego! Vi prego!', 'Acqua! Vi prego! Vi prego!', 28153),
(161586, 'itIT', 'Elune, salvaci!', 'Elune, salvaci!', 28153),
(161585, 'itIT', 'Sì, concentrati sull\'obiettivo e sul compiacere Selvamorta. Mantienili al sicuro.\n\nIo devo pensare al mio lavoro, $n.', '', 28153),
(161584, 'itIT', 'Concentrati, Fratello Zelling!', 'Concentrati, Fratello Zelling!', 28153),
(161583, 'itIT', 'Sono TUTTO per me!\n\nHo... Ho capito che non mi vogliono più nelle loro vite. Ma le cose potrebbero cambiare!\n\nQuando capiranno che sono io, che li amo ancora, so che... so che...\n\nIo...', '', 28153),
(161582, 'itIT', 'Sono ancora nei tuoi pensieri.', 'Sono ancora nei tuoi pensieri.', 28153),
(161581, 'itIT', 'Non sono sicuro se... Non ho ancora...\n\nNon è facile, $n.\n\nDama Voss mi ha consigliato di concentrarmi sul compito che mi è stato affidato. Ha detto che dimostrare il mio valore a Selvamorta sia il modo migliore per tenere al sicuro la mia famiglia.\n\nLa mia famiglia...', '', 28153),
(161580, 'itIT', 'Com\'è stata la tua trasformazione, Zelling?', 'Com\'è stata la tua trasformazione, Zelling?', 28153),
(161579, 'itIT', 'Farò tutto il possibile per aiutare la causa dei Reietti.', '', 28153),
(161578, 'itIT', 'Mandami a Zuldazar!', 'Mandami a Zuldazar!', 28153),
(161577, 'itIT', '', 'Throm\'ka, $C. Desideri tornare a Zuldazar?', 28153),
(161576, 'itIT', '', 'Quando ero viva, mi insegnarono a odiare i non morti e fui addestrata col preciso scopo di eliminarli.\n\nQuando diventai una Reietta, iniziai a odiare me stessa più di qualunque altra cosa, ma ora ho capito che è l\'Alleanza a fomentare quest\'odio. I regni degli Umani ripudiano i loro vecchi fratelli e sorelle perché gli ricordiamo cosa si nasconde sotto l\'apparente sicurezza della carne.\n\nÈ ora di porre fine a tutto quest\'odio. L\'Alleanza merita l\'estinzione.', 28153),
(161575, 'itIT', '', 'L\'oscurità non può sopravvivere nella Luce!', 28153),
(161574, 'itIT', 'Chel vudù è davvero terribile.', '', 28153),
(161573, 'itIT', 'Va bene.', 'Va bene.', 28153),
(161572, 'itIT', 'Niente fermerà l\'Orda!', '', 28153),
(161571, 'itIT', 'E per quanto riguarda l\'Alleanza?', 'E per quanto riguarda l\'Alleanza?', 28153),
(161570, 'itIT', '', 'Non serve un profeta per capire che Sylvanas userà questa guerra come mezzo per portare nuovi Reietti su questo mondo.\n\nLa mia stessa conversione è stata... difficile. Ho dovuto superare molte difficoltà.\n\nNon mi sono ancora ripresa del tutto, ma sento anche l\'obbligo di aiutare i nuovi risorti ad adattarsi alla situazione. Forse, così facendo riuscirò a risparmiargli il dolore che ho dovuto sopportare io.', 28153),
(161569, 'itIT', 'Mmm, perché no?', 'Mmm, perché no?', 28153),
(161568, 'itIT', 'Abbiamo tutto sotto controllo. Rilassati e goditi la tua birra.', 'Abbiamo tutto sotto controllo. Rilassati e goditi la tua birra.', 28153),
(161567, 'itIT', 'Grazie per l\'offerta, ma ci muoveremo più in fretta da soli.', 'Grazie per l\'offerta, ma ci muoveremo più in fretta da soli.', 28153),
(161566, 'itIT', 'A voi Elfi serve aiuto con la vostra missione? I Ferroscuro possono dare una mano!', 'A voi Elfi serve aiuto con la vostra missione? I Ferroscuro possono dare una mano!', 28153),
(161565, 'itIT', 'Che tipo di opportunità?', 'Che tipo di opportunità?', 28153),
(161564, 'itIT', '', 'Pare che le mie abilità abbiano attirato l\'attenzione dei poteri forti. I miei servizi sono stati... \"richiesti\".\n\nHai compreso il messaggio? Chiedo scusa, nonostante la mia professione, non me la cavo molto bene con i sotterfugi.\n\nComunque, so riconoscere un\'opportunità quando mi si presenta davanti.', 28153),
(161563, 'itIT', 'Sembri aver accettato l\'invito dell\'Orda.', 'Sembri aver accettato l\'invito dell\'Orda.', 28153),
(161562, 'itIT', 'Halford, iniziamo i preparativi per far esplodere questa nave.', 'Halford, iniziamo i preparativi per far esplodere questa nave.', 28153),
(161561, 'itIT', 'Serve un passaggio?', '', 28153),
(161560, 'itIT', 'Serve un passaggio?', '', 28153),
(161559, 'itIT', 'Il Capitano Brewston ha detto che mi avresti fatto fare un giro dell\'area.', 'Il Capitano Brewston ha detto che mi avresti fatto fare un giro dell\'area.', 28153),
(161558, 'itIT', 'Grazie.', 'Grazie.', 28153),
(161557, 'itIT', 'Wistel ha detto che mi avresti fatto fare un giro dell\'area.', 'Wistel ha detto che mi avresti fatto fare un giro dell\'area.', 28153),
(161556, 'itIT', 'Grazie.', 'Grazie.', 28153),
(161555, 'itIT', 'Va bene, basta così. Scendiamo giù.', '', 28153),
(161554, 'itIT', 'Dritto davanti a noi si trova l\'Alto Osservatorio e dietro di esso Ar\'gorok. Il nemico. Il luogo che dobbiamo conquistare.', '', 28153),
(161553, 'itIT', 'Laggiù? Quella è la Nuova Fattoria. Pascoli e terre coltivate, niente di particolare.', '', 28153),
(161552, 'itIT', 'Laggiù, verso est, si trova il Circolo degli Elementi. Hanno dei grossi totem di pietra, enormi Elementali del Fuoco e giganteschi cerchi nel terreno. Il paradiso di ogni Sciamano.', '', 28153),
(161551, 'itIT', 'Non temere, non ci allontaneremo molto. Volevo solo farti vedere un paio di posizioni dove abbiamo dovuto rispondere agli attacchi dell\'Orda, in caso dovessimo... sai... ucciderli.', '', 28153),
(161550, 'itIT', 'Ti do il benvenuto alla Segheria delle Alture, il luogo da cui proviene tutta la legna di Stromgarde... o meglio, il luogo da cui DI SOLITO proviene la nostra legna. Dopo l\'ultimo attacco dell\'Orda, siamo stati cacciati via e la natura sembra aver reclamato il nostro vecchio mulino. Non appena i nostri soldati saranno qui, lo rimetteremo in sesto.', '', 28153),
(161549, 'itIT', 'Ti do il benvenuto alla Segheria delle Alture, il luogo da cui proviene tutta la legna di Stromgarde.\n\nLe foreste sono tranquille, oggi. Uno dei braccianti ha avuto un piccolo alterco con un orso, ma niente di nuovo. Sai come vanno le cose con loro...', '', 28153),
(161548, 'itIT', '', '$n, giusto? Tully.\n\n<La Caposquadra Tully ti allunga la mano callosa.>\n\nQuesta è la Vena Mineraria di Galson. Normalmente, i miei braccianti sarebbero impegnati a estrarre minerali per la campagna bellica, ma con l\'ultimo attacco dell\'Orda siamo stati cacciati con la forza.\n\nDi\' a Brewston che ci farebbe comodo un po\' di supporto militare. Siamo pronti a iniziare a lavorare, ma non riusciremo a mettere piede in quella miniera senza combattere.', 28153),
(161547, 'itIT', '', '$n, giusto? Tully.\n\n<La Caposquadra Tully ti allunga la mano callosa.>\n\nNulla da riferire, qui. L\'Orda continua a essere una spina nel fianco e i Coboldi continuano a essere... fastidiosi, ma nulla che non possiamo gestire.', 28153),
(161546, 'itIT', 'Va bene, basta così. Scendiamo giù.', '', 28153),
(161545, 'itIT', 'Dritto davanti a noi si trova l\'Alto Osservatorio e dietro di esso Stromgarde. Il nemico. Il luogo che dobbiamo conquistare.', '', 28153),
(161544, 'itIT', 'Laggiù? Quella è la Nuova Fattoria. Pascoli e terre coltivate, niente di particolare.', '', 28153),
(161543, 'itIT', 'Laggiù, verso est, si trova il Circolo degli Elementi. Hanno dei grossi e antichi totem di pietra, enormi Elementali del Fuoco e giganteschi cerchi nel terreno. Il paradiso di ogni Sciamano.', '', 28153),
(161542, 'itIT', 'Non temere, non ci allontaneremo molto. Volevo solo farti vedere un paio di posizioni dove abbiamo dovuto rispondere agli attacchi dell\'Alleanza, in caso dovessimo... sai... ucciderli.', '', 28153),
(161541, 'itIT', 'Ti do il benvenuto alla Cresta della Scure, il luogo da cui proviene tutta la legna di Ar\'gorok... o meglio, il luogo da cui DI SOLITO proviene la nostra legna. Dopo l\'ultimo attacco dell\'Alleanza, siamo stati cacciati via e la natura sembra aver reclamato il nostro vecchio mulino. Non appena i nostri Grunt saranno qui, lo rimetteremo in sesto.', '', 28153),
(161540, 'itIT', 'Ti do il benvenuto alla Cresta della Scure, il luogo da cui proviene tutta la legna di Ar\'gorok.\n\nLe foreste sono tranquille, oggi. Uno dei peoni ha avuto un piccolo alterco con un orso, ma niente di nuovo. Sai come vanno le cose con loro...', '', 28153),
(161539, 'itIT', '$n, giusto? Drogg.\n\n<Drogg ti allunga la mano callosa.>\n\nQuesta è la Miniera dei Baffosecco. Normalmente, i miei peoni sarebbero impegnati a estrarre minerali per la campagna bellica, ma con l\'ultimo attacco dell\'Alleanza siamo stati cacciati con la forza.\n\nDi\' a Wistel che ci farebbe comodo un po\' di supporto militare. Siamo pronti a iniziare a lavorare, ma non riusciremo a mettere piede in quella miniera senza combattere.', '', 28153),
(161538, 'itIT', '', '$n, giusto? Drogg.\n\n<Drogg ti allunga la mano callosa.>\n\nNulla da riferire, qui. L\'Alleanza continua a essere una spina nel fianco e i Coboldi continuano a essere... fastidiosi, ma nulla che non possiamo gestire.', 28153),
(161537, 'itIT', 'Fintanto che Lunargenta rimarrà dalla parte dell\'Orda, ci sarà sempre qualcuno che non si fiderà di noi.\n\nL\'Alleanza è la vera famiglia a cui appartiene la nostra gente, ora ne sono più certo che mai.\n\nNon perdere la via, $n. Mostra ai nostri compagni dell\'Alleanza che combattiamo per la stessa causa.\n\nUn giorno, la morsa dell\'Orda sulla nostra terra sarà strappata via e i figli di Quel\'Thalas saranno uniti ancora una volta.\n\nLo so.', '', 28153),
(161536, 'itIT', 'Credi che ci siamo guadagnati la fiducia dell\'Alleanza?', 'Credi che ci siamo guadagnati la fiducia dell\'Alleanza?', 28153),
(161535, 'itIT', 'Combatto per far tacere i sussurri, proprio come te, ma fortunatamente, Alleria Ventolesto continua a offrirci la sua guida.\n\nSenza il suo intervento... be\', temo che non avremmo avuto alcuna possibilità.\n\nAnche se ero riluttante a trattare con lui in principio, ho imparato molto dal Ramingo del Locus. Ricorda solo che ogni cosa ti offra è destinata a servire ai suoi scopi, in un modo o nell\'altro.', '', 28153),
(161534, 'itIT', 'Come va, Magistro Umbric?', 'Come va, Magistro Umbric?', 28153),
(161533, 'itIT', 'Non siamo dalla parte dell\'Alleanza per pura convenienza e nemmeno perché mossi solo dalla gratitudine che abbiamo verso Alleria.\n\nIl nostro calvario ci ha insegnato quanto sia importante che i poteri più forti siano nelle mani giuste. Non potevamo permettere all\'Orda di venire a conoscenza di ciò che sapevamo o di usarci come arma nei loro piani.\n\nCombattiamo per l\'Alleanza perché crediamo nei suoi valori e prego perché un giorno tutta Lunargenta si unisca alla causa.', '', 28153),
(161532, 'itIT', 'Ora combattete per l\'Alleanza.', 'Ora combattete per l\'Alleanza.', 28153),
(161531, 'itIT', 'Guidai la mia gente direttamente in una trappola degli Eterei. Se non fosse stato per l\'intervento di Alleria Ventolesto, non avremmo avuto speranze.\n\nLe energie dell\'Ombra ci trasformarono... e aprirono le nostre menti ai sussurri del Vuoto. Senza la guida di Alleria, saremmo caduti in preda alla follia.\n\nLei ci ha aiutati a calmare la mente, ad attenuare i sussurri... ma è una lotta continua.', '', 28153),
(161530, 'itIT', 'Il Vuoto ha avuto la meglio su di te?', 'Il Vuoto ha avuto la meglio su di te?', 28153),
(161529, 'itIT', 'I miei seguaci e io non sentivamo alcun legame con l\'Orda. Quando il Gran Magistro Rommath bandì le nostre ricerche sul Vuoto, non esitammo a prendere le distanze per seguire il nostro cammino.\n\nL\'arroganza però prese il sopravvento su di me. Ero certo di poter padroneggiare ogni genere di forza incontrassimo.\n\nMi sbagliavo...', '', 28153),
(161528, 'itIT', 'Quindi sei alla ricerca del potere dell\'Ombra?', 'Quindi sei alla ricerca del potere dell\'Ombra?', 28153),
(161527, 'itIT', 'In qualità di Magistro, i miei doveri sono sempre stati verso Lunargenta. Quando il folle Arthas devastò le nostre terre, sapevo che avremmo dovuto concentrare più potere possibile per assicurare la nostra sopravvivenza.\n\nIl Principe Kael\'thas propose un modo, ma io ne scelsi un altro.', '', 28153),
(161526, 'itIT', 'Qual è il tuo ruolo in questa campagna, Magistro?', 'Qual è il tuo ruolo in questa campagna, Magistro?', 28153),
(161525, 'itIT', '', 'Vogliamo andare?', 28153),
(161524, 'itIT', 'Già di ritorno?', '', 28153),
(161523, 'itIT', 'Ho perso il flauto.', 'Ho perso il flauto.', 28153),
(161521, 'itIT', 'Impressionante. Grazie, Magistro.', '', 28153),
(161520, 'itIT', 'Viaggerò insieme a te su questo vascello, così avremo il tempo di discutere della nostra strategia.', '', 28153),
(161519, 'itIT', 'Saranno alla spiaggia ad attenderci quando arriveremo, con un rapporto esplorativo completo sull\'area.', '', 28153),
(161518, 'itIT', 'Grazie, Magistro Umbric. Quanto ci vorrà perché ci raggiungano qui?', '', 28153),
(161517, 'itIT', 'Gran Comandante, ho incaricato un reggimento dei miei migliori esploratori e assassini di raggiungerci a Xibala.', '', 28153),
(161516, 'itIT', '', 'Abbiamo del pubblico, perfetto! Non muoverti, cane dell\'Alleanza. Guardami mentre uccido uno dei vostri eroi più grandi!', 28153),
(161515, 'itIT', 'Mandami agli Altopiani d\'Arathi!', 'Mandami agli Altopiani d\'Arathi!', 28153),
(161514, 'itIT', '', 'Throm\'ka, $C. Stai andando al fronte?', 28153),
(161513, 'itIT', '', 'Ehilà! Questo posto è fantastico, vero? Non riesco mai a decidere quale bar sia il mio preferito, ma questo è decisamente tra i dieci migliori.', 28153),
(161512, 'itIT', 'Nessun vascello può avere la meglio su di noi. Nessuno.', 'Nessun vascello può avere la meglio su di noi. Nessuno.', 28153),
(161511, 'itIT', 'Sia lodata la Madre delle Maree.', 'Sia lodata la Madre delle Maree.', 28153),
(161510, 'itIT', 'Ascolta gli abissi. Solo loro ci mostreranno la verità.', 'Ascolta gli abissi. Solo loro ci mostreranno la verità.', 28153),
(161509, 'itIT', '', 'Oh, ehi, un altro manufatto dei Drust. Dovrei portarlo a Jane.', 28153),
(161508, 'itIT', 'Che le correnti ti guidino.', 'Che le correnti ti guidino.', 28153),
(161507, 'itIT', '', 'Mmm, la testa del mio piccone è un po\' allentata. Dovrei chiedere a Grix di dargli un\'occhiata.', 28153),
(161506, 'itIT', '', 'Mi sta venendo fame. Dovrei andare da Byron insieme ad Alan.', 28153),
(161505, 'itIT', '', 'Odio ammetterlo, ma spostare i materiali era molto più semplice quando Franklin era qui.', 28153),
(161504, 'itIT', '', 'Ti do il benvenuto nella nostra umile locanda. Come posso aiutarti?', 28153),
(161503, 'itIT', '', 'Serve aiuto per tornare a Boralus?', 28153),
(161502, 'itIT', 'Hai dato prova di essere $gun vero alleato:una vera alleata;, $p.\n\nSarai sempre $gil benvenuto:la benvenuta; nella nostra carovana, qui o dovunque le sabbie ci porteranno.', '', 28153),
(161501, 'itIT', '', 'La vita non sarà mai facile a Vol\'dun, ma lo sarà di più dopo le nostre vittorie contro i Senzafede.\n\nGrazie, $p.\n\nRiposati e goditi l\'ospitalità della mia gente. Parla con i piccoletti che hai aiutato a salvare e fatti una bella bevuta.\n\nÈ per questi momenti di pace che combattiamo e dobbiamo fare il possibile per goderceli appieno.', 28153),
(161500, 'itIT', '', 'È stata una bella avventura, $p, una che non dimenticherò molto presto.\n\nRicorda di dare un saluto a Dolly, le manchi molto!', 28153),
(161499, 'itIT', 'La situazione al Campo di Taglio degli Algerson è tornata alla normalità. Tutti coloro che attendevano un ordine di legna dovrebbero riceverlo a breve.', '', 28153),
(161498, 'itIT', '', 'Il pelo di queste pelli di cinghiale non fa che rovinare il mio rasoio. Dovrei chiedere a Grix di costruirmi qualcosa di meglio.', 28153),
(161497, 'itIT', 'La Guardia dei Crestabianca ci ha informato che è nuovamente possibile viaggiare a Drustvar in sicurezza. Ad ogni modo, i viaggiatori sono invitati a stare sulle strade principali.', '', 28153),
(161496, 'itIT', 'Chi ci sta con Talanji? È qualcuno... dell\'Orda?', '', 28153),
(161495, 'itIT', 'Tiene dei teschi nuovi? Fammi vedere!', '', 28153),
(161494, 'itIT', 'La Principessa è tornata!', '', 28153),
(161493, 'itIT', 'Talanji! Talanji!', 'Talanji! Talanji!', 28153),
(161492, 'itIT', 'Riportami a Zuldazar.', 'Riportami a Zuldazar.', 28153),
(161491, 'itIT', 'Ser Norwington invita tutti i migliori cavalieri e cacciatori alla sua tenuta per partecipare alla quindicesima edizione del Festival Equestre e di Caccia dei Norwington.', '', 28153),
(161490, 'itIT', '', 'La civiltà è così noiosa... Dovrei essere là fuori a cacciare...', 28153),
(161489, 'itIT', 'Timbro... il cartellino... per l\'ultima volta...', 'Timbro... il cartellino... per l\'ultima volta...', 28153),
(161488, 'itIT', 'Ti schiaccerò!', 'Ti schiaccerò!', 28153),
(161487, 'itIT', 'La Guardia dei Marefiero ci sconsiglia di viaggiare a Drustvar fino a ulteriori aggiornamenti. Stanno aspettando risposta dalla Guardia dei Crestabianca. Per ora non ci sono altre informazioni disponibili.', '', 28153),
(161486, 'itIT', 'Non temere, di certo lo farà. Tieni, mi ha detto di darti questa lettera!', 'Non temere, di certo lo farà. Tieni, mi ha detto di darti questa lettera!', 28153),
(161485, 'itIT', '', 'Ehi, Cass. Non riesco a trovare il mio pugnale da scuoiatura preferito. Per caso l\'hai... No, niente, trovato!', 28153),
(161484, 'itIT', 'Per coloro preoccupati per gli strani rumori intorno al Campo di Taglio degli Algerson, Maynard ci tiene a informarvi che tutte le storie a riguardo sono state gonfiate per fare più scena e che al campo ci sono soltanto dei piccoli problemi d\'affari.', '', 28153),
(161483, 'itIT', 'Priscilla... avrà la tua testa per questo...', 'Priscilla... avrà la tua testa per questo...', 28153),
(161482, 'itIT', 'Ficcanasare non fa bene alla salute!', 'Ficcanasare non fa bene alla salute!', 28153),
(161481, 'itIT', 'Per decreto del Gran Ammiraglio, ricordo a tutti i cittadini che vogliono visitare Sacraonda che devono presentarsi al punto di controllo della valle per un\'ispezione delle guardie di Ser Sacraonda.', '', 28153),
(161480, 'itIT', 'Ahhh, mamma! Mi manca un sacco. Spero davvero torni a casa presto.', '', 28153),
(161479, 'itIT', 'I venti sono in continuo mutamento. A volte sono favorevoli, a volte no. Pa\'ku ci insegna ad andare dove i venti ci portano, ed è proprio lì che ci sta bisogno di noi.\n\nTu e l\'Orda avete reso nu grande servigio al Re e alla gente mia. Nun lo dimenticheremo mai.\n\nNun credo che Loti ce lo permetterà, ma forse dovrei perdonarla. O scusarmi con lei. Nun ricordo. Chesta potrebbe essere la fine di tutto.', '', 28153),
(161478, 'itIT', '', 'Ehilà!$b$bCerchi qualcuno esperto in ingegneria?', 28153),
(161477, 'itIT', 'Papà è stato operoso come un\'ape per cercare di rimettere a posto la fattoria!', '', 28153),
(161476, 'itIT', 'Mi manca la mamma... Non torna a casa da tantissimo tempo.', '', 28153),
(161475, 'itIT', 'Sai... anche a me piacerebbe diventare un avventuriero, un giorno.', '', 28153),
(161474, 'itIT', 'Non posso credere che tu abbia combattuto e vinto contro i Wendigo!', '', 28153),
(161473, 'itIT', 'Ohhh, ti prego, dimmi che hai qualche nuova storia interessante da raccontare!', '', 28153),
(161472, 'itIT', 'Ehilà, $p!', '', 28153),
(161471, 'itIT', 'Sarei morto se non fosse stato per te. Grazie.', 'Sarei morta se non fosse stato per te. Grazie.', 28153),
(161470, 'itIT', 'Oh Loa, sarà nu disastro!', 'Oh Loa, sarà nu disastro!', 28153),
(161469, 'itIT', 'Sia maledetta l\'Orda! Lor\'danel non ha fatto nulla per meritarsi questo!', 'Sia maledetta l\'Orda! Lor\'danel non ha fatto nulla per meritarsi questo!', 28153),
(161468, 'itIT', 'Ehi, salve! Ma guardati, sei un... disastro.$b$bNon preoccuparti, Danny ha proprio ciò di cui hai bisogno!', '', 28153),
(161467, 'itIT', 'Che i Loa siano con voi.', '', 28153),
(161466, 'itIT', 'Sono tempi oscuri per Zandalar. Troll del Sangue, Loa morenti e traditori. I cieli nostri sono bui e i venti sussurrano di altre difficoltà all\'orizzonte.\n\nPersino Loti è gentile con me. Nun è normale e nun mi piace.\n\nSono felice che tu stia accà, $n, insieme all\'Orda tua.', '', 28153),
(161465, 'itIT', 'Elune, aiutaci!', 'Elune, aiutaci!', 28153),
(161464, 'itIT', 'Aspetta, vuoi fare COSA?', 'Aspetta, vuoi fare COSA?', 28153),
(161463, 'itIT', 'Chi ha pensato che fosse na buona idea?', 'Chi ha pensato che fosse na buona idea?', 28153),
(161462, 'itIT', 'Questa fattoria è un disastro! Non so cosa sia successo!', '', 28153),
(161461, 'itIT', 'È successo tutto così in fretta...', 'È successo tutto così in fretta...', 28153),
(161460, 'itIT', 'Sia lodata Elune!', 'Sia lodata Elune!', 28153),
(161459, 'itIT', 'Vai da qualche parte?', 'Vai da qualche parte?', 28153),
(161458, 'itIT', 'Credevo fosse la fine. Grazie!', 'Credevo fosse la fine. Grazie!', 28153),
(161457, 'itIT', 'Nun puoi correre tutti chesti tris in chesto posto.', 'Nun puoi correre tutti chesti tris in chesto posto.', 28153),
(161456, 'itIT', 'Ci stanno troppi tris in chesto posto.', 'Ci stanno troppi tris in chesto posto.', 28153),
(161455, 'itIT', 'Lod\'danel non aveva speranze...', 'Lod\'danel non aveva speranze...', 28153),
(161454, 'itIT', 'Soffrirà per chesto!', 'Soffrirà per chesto!', 28153),
(161453, 'itIT', 'Ho incontrato tua madre. Ha detto di salutarti!', 'Ho incontrato tua madre. Ha detto di salutarti!', 28153),
(161452, 'itIT', 'Sono sconcertato delle prestazioni attuali di chesti cornofurente.', 'Sono sconcertata delle prestazioni attuali di chesti cornofurente.', 28153),
(161451, 'itIT', 'Ahia! Sono allergico al dolore!', 'Ahia! Sono allergica al dolore!', 28153),
(161450, 'itIT', 'Cosa succede se mi arrendo e nun mi muovo più?', 'Cosa succede se mi arrendo e nun mi muovo più?', 28153),
(161449, 'itIT', 'Gonk, nun abbandonarmi proprio mo\'!', 'Gonk, nun abbandonarmi proprio mo\'!', 28153),
(161448, 'itIT', 'Scappa!', 'Scappa!', 28153),
(161447, 'itIT', 'Perché ci attaccano?!?', 'Perché ci attaccano?!?', 28153),
(161446, 'itIT', 'No! Nonono! Nonononono!', 'No! Nonono! Nonononono!', 28153),
(161445, 'itIT', 'Sarai veloce, ma nun mi beccherai mai!', 'Sarai veloce, ma nun mi beccherai mai!', 28153),
(161444, 'itIT', 'Scappa!', 'Scappa!', 28153),
(161443, 'itIT', '<Il diario è aperto alla pagina che descrive in dettaglio l\'attacco dell\'Orda alla Piazza di Brennadam.>', '<Il diario è aperto alla pagina che descrive in dettaglio l\'attacco dell\'Orda alla Piazza di Brennadam.>', 28153),
(161442, 'itIT', '', 'Nun sapevo nemmeno a cosa servisse chel sigillo!\n\nOra più che mai, dobbiamo lavorare insieme per superare i pericoli che minacciano Zandalar. Cerca li amici tuoi e aiutali a trasportare i fardelli loro.\n\nIl traditore Zul è schiattato. Normalmente direi a Raal che tenevo ragione, ma forse, dato quanto pochi di noi sono rimasti, dovrei far pace con lui... Bah.', 28153),
(161441, 'itIT', '', '$gBenvenuto:Benvenuta; da \"Cuoio e Pelli di Kul Tiras\"!$b$bMmm, sì, ci serve un nome migliore.$b$BMi presento: sono Cass e offro lezioni di Conciatura. La mia partner, Cami, è un po\' rude, ma non troverai una scuoiatrice migliore.$b$bDetto questo, di cosa hai bisogno?', 28153),
(161440, 'itIT', '', 'La perdita di così tanti Loa... Che Gonk protegga chi ha perso la via. Soffro per il Re mio e per la Principessa. La perdita di Rezan è na ferita nel core loro.\n\nBah, potrei anche riuscire a essere gentile con Raal, ma solo per qualche giorno.\n\nGrazie, $n. Tu e l\'Orda tua siete forti e siete di grande aiuto al branco nostro. Terremo bisogno di voi.', 28153),
(161439, 'itIT', '', 'Hai dimostrato più e più volte il valore tuo all\'Impero delli Zandalari. La sconfitta dei Troll del Sangue, la minaccia dei Sethrak e mo\' pure il profeta traditore.\n\nÈ n\'onore stare al fianco tuo, $n.', 28153),
(161438, 'itIT', 'Immagino tu stia cercando un nuovo famiglio, vero?\n\n<Ulfar sogghigna.>\n\nLa magia di questo posto ha radici molto profonde e ha influenzato alcuni animali della regione. Sono potenti manifestazioni della natura che vanno rispettate.', '', 28153),
(161437, 'itIT', 'Non ti sfugge niente, eh?\n\n<Ulfir ridacchia.>\n\nIn effetti è così, ma non tutti i membri del mio popolo erano favorevoli al conflitto. Non ci sono mai state divisioni tra voi?\n\nNoi Cantaspine ci siamo inseriti nella società di Kul Tiras. Alcuni dei loro discendenti hanno sentito il richiamo della natura e hanno deciso di imparare le antiche arti, così glie le abbiamo insegnate. Forse l\'hai sentito anche tu? No?', '', 28153),
(161436, 'itIT', 'Zul è schiattato, ma a quale prezzo?\n\nIl Gran Sigillo è rotto e Mythrax l\'Annientatore cammina di nuovo su chesto mondo. Nu male più grande di qualsiasi altro li Zandalari abbiano mai dovuto affrontare attende all\'orizzonte, e il nome suo è G\'huun.\n\nIl fardello è mio, $n. Se avessi dato ascolto a Talanji, se avessi affrontato Zul ogni volta che il suo comportamento si faceva pericoloso, forse tutto chesto nun sarebbe successo. Forse il Loa mio sarebbe ancora in vita e nun avrei condannato la gente mia ad accettare l\'abbraccio del Loa della Morte.\n\nChesto disonore è solo per me.\n\nMa tu, $n, sei $gstato:stata; al fianco mio. L\'Orda tua ha combattuto con noi contro i più antichi nemici nostri. Li Zandalari nun lo dimenticheranno, puoi starne $gcerto:certa;.', '', 28153),
(161435, 'itIT', 'In effetti è così, ma non tutti i membri del mio popolo erano favorevoli al conflitto. Non ci sono mai state divisioni tra voi?\n\nNoi Cantaspine ci siamo inseriti nella società di Kul Tiras. Alcuni dei loro discendenti hanno sentito il richiamo della natura e hanno deciso di imparare le antiche arti, così gliele abbiamo insegnate.', '', 28153),
(161434, 'itIT', 'Io sono Ulfar, l\'ultimo Cantaspine dei Drust e maestro di questi studenti. Un giorno il mio compito sarà finito e tornerò alla terra, lasciando il posto a un nuovo Sommo Cantaspine, com\'è giusto che sia.\n\nMa quel giorno non è ancora giunto.', '', 28153),
(161433, 'itIT', 'Uff! Mi hai spaventato!$b$BQuindi... vuoi imparare a pescare? Io, onestamente, non so fare altro.', '', 28153),
(161432, 'itIT', 'Ho visto degli animali che sembravano essere in parte piante. Puoi dirmi qualcosa su di loro?', 'Ho visto degli animali che sembravano essere in parte piante. Puoi dirmi qualcosa su di loro?', 28153),
(161431, 'itIT', 'Sei un Drust? Non eravamo forse in guerra contro di voi?', 'Sei un Drust? Non eravamo forse in guerra contro di voi?', 28153),
(161430, 'itIT', 'Sei un Drust? Non eravamo forse in guerra contro di voi?', 'Sei un Drust? Non eravamo forse in guerra contro di voi?', 28153),
(161429, 'itIT', 'Puoi raccontarmi di nuovo la tua storia?', 'Puoi raccontarmi di nuovo la tua storia?', 28153),
(161428, 'itIT', 'Chi sei?', 'Chi sei?', 28153),
(161427, 'itIT', '', 'Dobbiamo anche pensare a noi stessi, $p. Non possiamo aiutare coloro che amiamo, se riusciamo a malapena a sopravvivere.', 28153),
(161426, 'itIT', 'Anche tu sei $gun Druido:una Druida;?', 'Anche tu sei $gun Druido:una Druida;?', 28153),
(161425, 'itIT', 'Voi siete Druidi?', 'Voi siete Druidi?', 28153),
(161424, 'itIT', '', 'Spero che le tue avventure stiano andando bene, $p!', 28153),
(161423, 'itIT', 'Lo siamo, $n. Siamo i difensori dell\'equilibrio della natura, i custodi del ciclo. La vita è parte della natura, proprio come la morte.', '', 28153),
(161422, 'itIT', 'Lo siamo, e non molto diversi da te, $n. Siamo i difensori dell\'equilibrio della natura, i custodi del ciclo. La vita è parte della natura, proprio come la morte. In quanto $gDruido:Druida;, questo lo saprai già.\n\nTi diamo il benvenuto nel nostro bosco.', '', 28153),
(161421, 'itIT', '', 'Ancel e suo padre mi mancano da morire. Con un po\' di fortuna, tra non molto potrò tornare a casa.', 28153),
(161420, 'itIT', '', 'È bello rivederti, $p. Spero tu te la sia passata bene.', 28153),
(161419, 'itIT', '<Leggi il diario.>', '<Leggi il diario.>', 28153),
(161418, 'itIT', 'Lo farò!', 'Lo farò!', 28153),
(161417, 'itIT', 'Leggi di quando tu e Talanji vi siete incontrati la prima volta nel Cuore di Tenebra.', 'Leggi di quando tu e Talanji vi siete incontrati la prima volta nel Cuore di Tenebra.', 28153),
(161416, 'itIT', '', 'Sì. Mi mancano da morire e non vedo l\'ora di tornare a casa. Sono sicura che Raimond stia facendo del suo meglio, ma bisogna ammettere che un talento innato per incasinare qualunque cosa!\n\nSe li rivedi, per favore, consegna questa lettera al mio adorato Ancel.', 28153),
(161414, 'itIT', '<Vaza il Pazzo prende nota di tutti gli eventi accaduti a Nazmir. Nonostante il suo nomignolo, i suoi appunti sembrano scritti in modo chiaro e organizzato.>', '', 28153),
(161413, 'itIT', '', 'Zul ha causato na tale devastazione...\n\nÈ nu bene che tu e l\'Orda siate ancora accà, $n, e sono felice che la fede mia non sia stata mal riposta. Il solo pensiero che li Zandalari avrebbero potuto dover affrontare chei cosi da soli... è più terrificante di quanto le parole possano esprimere.\n\nSe saremo ancora vivi quando tutto chesto sarà finito, spero di poter ricambiare il favore. Li Zandalari saranno per sempre in debito con te.', 28153),
(161412, 'itIT', '\"Be\', caro fratello\", disse Koralynn, \"sarai anche un pessimo marinaio, ma credo che saresti un ottimo Saggio delle Maree\".', '\"Be\', caro fratello\", disse Koralynn, \"sarai anche un pessimo marinaio, ma credo che saresti un ottimo Saggio delle Maree\".', 28153),
(161411, 'itIT', '', 'Ti seguirò, Eitrigg, per fare due chiacchiere con il tuo Capoguerra. È ancora il Troll di cui parlava mia madre?', 28153),
(161410, 'itIT', '', 'Rezan... il Loa mio... è schiattato.\n\nÈ na disgrazia. Nun ho mai visto nu tale peso sulle spalle del padre mio. Il tradimento di Zul ci ha colpito più a fondo di quanto immaginassimo... anche coloro che lo sospettavano sin dall\'inizio.\n\nNa tale eresia nun po\' rimanere impunita, $n. Dobbiamo radunare la gente nostra, i Loa e tutti li alleati che riusciamo a trovare! Solo allora avremo qualche possibilità di fermare i vili piani di Zul.', 28153),
(161409, 'itIT', '', 'Molto bene, allora. Alla prossima.', 28153),
(161408, 'itIT', 'Ehilà, $gragazzo:ragazza;!$b$B$gBenvenuto:Benvenuta; da Bistecche Bruciate Quantobasta B.B.Q.! Qui troverai la miglior carne affumicata di Forgiardente!$b$bDimmi, cosa posso fare per te?', '', 28153),
(161407, 'itIT', 'Parlami del patto di Rastakhan con Bwonsamdi.', 'Parlami del patto di Rastakhan con Bwonsamdi.', 28153),
(161406, 'itIT', 'Davanti a noi si ergono le mura di Orgrimmar, capitale dell\'Orda.', '', 28153),
(161405, 'itIT', 'Ci sono passato anch\'io, molto tempo fa. Può essere... disorientante. Farò il possibile per aiutare te e la tua gente.', '', 28153),
(161404, 'itIT', 'Ma che storia interessante.', 'Ma che storia interessante.', 28153),
(161403, 'itIT', '', 'Mythrax l\'Annientatore è di nuovo libero di camminare sul mondo! Credevamo fosse solo na leggenda, na storiella inventata per impedirci di soccombere alli effetti del tempo e del disinteresse. Ma grazie a chella serpe di Jakra\'zet e ai Senzafede, il regno del terrore suo vive di nuovo.\n\nNun è tutto perduto. Jakra\'zet ha avuto ciò che si meritava e abbiamo trovato dei nuovi alleati, i Vulpera e i seguaci del Loa Sethraliss. Però... temo che anche con l\'aiuto loro potremmo nun riuscire a prevalere contro nu tale avversario.\n\nChesti sono giorni bui... e spero che nun saranno li ultimi delli Zandalari.', 28153),
(161402, 'itIT', '', 'Pochi istanti fa, stavamo combattendo per le nostre vite su Draenor. Non avrei mai pensato di posare gli occhi su un altro mondo.', 28153),
(161401, 'itIT', 'Parlami del Ritiro di Talanji.', 'Parlami del Ritiro di Talanji.', 28153),
(161400, 'itIT', 'Parlami dell\'assalto di Mythrax.', 'Parlami dell\'assalto di Mythrax.', 28153),
(161399, 'itIT', 'Suprema, questa... è Azeroth.', '', 28153),
(161398, 'itIT', 'Parlami del tradimento di Zul.', 'Parlami del tradimento di Zul.', 28153),
(161397, 'itIT', '', 'Per generazioni, li Zandalari hanno combattuto contro i Nazmani. I confini nostri sono sotto assedio sin da prima che io nascessi e il padre mio nun ha mai conosciuto nient\'altro che la guerra con i Troll del Sangue. Ha finito per sottovalutarli e abbiamo lasciato che radunassero le forze loro. Ora sappiamo la verità.\n\nRispondono al Dio del Sangue, G\'huun.\n\nNun dobbiamo fallire: se Zuldazar dovesse cadere, il resto del mondo la seguirebbe. Nun si fermeranno fin quando il Dio del Sangue ci dominerà tutti.', 28153),
(161396, 'itIT', '', '$gBenvenuto:Benvenuta; al mio negozio.$b$bDai pure un\'occhiata in giro. Se hai bisogno di qualcosa, chiedi pure.', 28153),
(161395, 'itIT', '', 'Bip! Bip!', 28153),
(161394, 'itIT', 'Questi esemplari di Zandalar richiedono una nuova tassonomia!', 'Questi esemplari di Zandalar richiedono una nuova tassonomia!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161393, 'itIT', '', 'Ti do il benvenuto agli Incantamenti Incantevoli di Chiarosole!\n\nSe hai qualche domanda su qualsiasi cosa di mistico, non esitare a chiedere!', 28153),
(161391, 'itIT', '', 'Ohhh, ho rotto un\'altra penna...', 28153),
(161390, 'itIT', 'La chiave... gira ancora una volta.', '', 28153),
(161389, 'itIT', 'Mucchio di carne ambulante! Quando si sveglierà, conoscerai l\'eternità, e tremerai al suo cospetto!', '', 28153),
(161388, 'itIT', '', 'Ahhh, un crampo alla mano!', 28153),
(161387, 'itIT', 'Vi sono grandi e terribili verità alla base di ogni cosa. Io ne sono l\'alfiere. Ascolta la mia predica e conoscerai le infinite conseguenze.', '', 28153),
(161386, 'itIT', 'Non mi feci prendere dal panico, continuai a nuotare e a bere!', '', 28153),
(161385, 'itIT', 'E in men che non si dica, mi ritrovai intrappolato in un\'intera vasca di Birra Triplo Malto!', '', 28153),
(161384, 'itIT', 'Hai visto oltre il velo. Ora percepirai ogni cosa secondo la sua vera natura.', '', 28153),
(161383, 'itIT', '', 'Aspetta, cos\'è questo? Una macchia o un glifo?', 28153),
(161382, 'itIT', 'Sylvanas vuole me e intendo darle ciò che vuole.', '', 28153),
(161381, 'itIT', 'Qualche birreria nanica migliorerebbe di molto la qualità della vita a Radaluna.', '', 28153),
(161380, 'itIT', '', 'Andiamo! Il sottomarino dovrebbe essere già pronto.', 28153),
(161379, 'itIT', 'Un altro giro per i miei amici!', '', 28153),
(161378, 'itIT', 'Consegna speciale per te!', '', 28153),
(161377, 'itIT', 'Va bene, non era un granché. Comunque, siamo arrivati!', '', 28153),
(161376, 'itIT', 'Ormai ho messo le radici! L\'hai capita?', '', 28153),
(161375, 'itIT', 'I miei genitori mi volevano nella marina. Riesci a immaginarlo? Io no.', '', 28153),
(161374, 'itIT', 'Lui e gli altri sono i miei mentori sin da quando ho sentito la vocazione.', '', 28153),
(161373, 'itIT', 'Ulfar a volte può sembrare un insegnante severo, ma è sempre corretto.', '', 28153),
(161372, 'itIT', 'Resisti!', '', 28153),
(161371, 'itIT', 'Ehi, $n! Quaggiù!', '', 28153),
(161370, 'itIT', 'La via per il bosco di Ulfar potrebbe rivelarsi più impervia del previsto. Arthur, raggiungiamo i nostri amici alla fine del sentiero.', '', 28153),
(161369, 'itIT', 'Certo! Ci vediamo lì, $n!', '', 28153),
(161368, 'itIT', 'Tutta la Fenditura di Telogrus non fa che parlare dei tuoi trucchetti, $p.\n\nSono felice di averti al mio fianco in questa missione. Insieme, nulla potrà fermarci.', '', 28153),
(161367, 'itIT', 'Farò del mio meglio per tenere al sicuro la zona.', 'Farò del mio meglio per tenere al sicuro la zona.', 28153),
(161366, 'itIT', 'Ora che i dispositivi sono disarmati, l\'area dovrebbe essere più sicura... per ora.', 'Ora che i dispositivi sono disarmati, l\'area dovrebbe essere più sicura... per ora.', 28153),
(161365, 'itIT', 'Fai attenzione a dove metti i piedi.', 'Fai attenzione a dove metti i piedi.', 28153),
(161364, 'itIT', 'Ho disarmato tutti i dispositivi che ho trovato, ma fai comunque attenzione là fuori!', 'Ho disarmato tutti i dispositivi che ho trovato, ma fai comunque attenzione là fuori!', 28153),
(161363, 'itIT', '', 'Sì, ora funziona perfettamente! Ehi! Perché non rivediamo quei registri che ha trovato $n?', 28153),
(161362, 'itIT', 'Capisco. È un bene che tu l\'abbia riparato.', '', 28153),
(161361, 'itIT', 'Ma che grazioso fiorellino.', '', 28153),
(161360, 'itIT', '', 'Oh! Ahahah... be\', il campo di contenimento miniaturizzato non stava funzionando molto bene dieci minuti fa.', 28153),
(161359, 'itIT', 'Kelsey, perché non prendiamo semplicemente questo sottomarino per raggiungere l\'Isola delle Fauci?', '', 28153),
(161358, 'itIT', '', 'Stai indietro e rilassati, arriveremo al Porto da Guerra in men che non si dica.', 28153),
(161357, 'itIT', 'Il tuo Saltaonde si sta impaurendo. Torna subito indietro!', 'Il tuo Saltaonde si sta impaurendo. Torna subito indietro!', 28153),
(161356, 'itIT', 'Mmm... afidi... Di voi mi occuperò più tardi.', '', 28153),
(161355, 'itIT', 'Forza, piccolina. Germoglia.', '', 28153),
(161354, 'itIT', 'Ahhh, la delicata fragranza dell\'aethril! Adoro questo lavoro.', '', 28153),
(161353, 'itIT', 'L\'Isola di Yojamba, nella Valle di Rovotorto, molti anni fa fu meta di na spedizione. Anch\'io facevo parte delle forze che impedirono il ritorno di Hakkar su chesto mondo. Fornimmo armamenti gloriosi a chelli eroi che combatterono contro chell\'abominio di nu Loa.\n\nQuando tornammo vincitori a Zandalar, feci l\'errore di vantarmi della vittoria mia con il Profeta Zul. Probabilmente dissi qualcosa che nun fu di suo gradimento in pubblico...\n\nMo\' servo da mangiare.', '', 28153),
(161352, 'itIT', 'Inizi a non prestare più attenzione alla storia. Torna subito indietro!', 'Inizi a non prestare più attenzione alla storia. Torna subito indietro!', 28153),
(161351, 'itIT', '', 'È bello rivederti, $p. Ammiro molto la rapidità con cui hai scalato i ranghi dell\'Alleanza, ma ammiro ancora di più la tua capacità di resistere ai sussurri.\n\nLa guerra è caotica e brutale. Non importa ciò che vedi, o ciò che provi; non devi mai perdere il controllo. Non lasciare che le ombre abbiano la meglio.\n\nL\'Alleanza conta su di te e anch\'io.', 28153),
(161350, 'itIT', 'Cos\'è, o cos\'era, Yojamba?', 'Cos\'è, o cos\'era, Yojamba?', 28153),
(161349, 'itIT', 'L\'Alleanza sta attaccando, dobbiamo avvisare il Re!', 'L\'Alleanza sta attaccando, dobbiamo avvisare il Re!', 28153),
(161348, 'itIT', 'L\'Alleanza sta accà, avvisate tutti quanti!', 'L\'Alleanza sta accà, avvisate tutti quanti!', 28153),
(161347, 'itIT', 'Siamo sotto attacco dall\'Alleanza, devo avvisare li altri!', 'Siamo sotto attacco dall\'Alleanza, devo avvisare li altri!', 28153),
(161346, 'itIT', 'L\'Alleanza sta attaccando, dobbiamo avvisare li altri!', 'L\'Alleanza sta attaccando, dobbiamo avvisare li altri!', 28153),
(161345, 'itIT', '', 'Non abbassare la guardia, Umbric. Questo è un piano ambizioso e, se qualcosa dovesse andar storto, molte vite andrebbero perdute.', 28153),
(161344, 'itIT', 'Immagino che questo compito non sia così un suicidio come pensavo.', '', 28153),
(161343, 'itIT', 'Con tutto il rispetto, Halford, ma quello che proponi è un suicidio. Gli Zandalari hanno spazzato via l\'ultima flotta che ha tentato di attaccare le loro coste.', '', 28153),
(161342, 'itIT', 'Sì, ora come ora, le nostre perdite sarebbero catastrofiche se tentassimo un qualsiasi tipo di sbarco.', '', 28153),
(161341, 'itIT', 'Le loro difese navali hanno spazzato via l\'ultima flotta che si è avvicinata troppo all\'isola e stavano soltanto inseguendo una principessa.', '', 28153),
(161340, 'itIT', 'Bottino sepolto?', 'Bottino sepolto?', 28153),
(161339, 'itIT', 'Suppongo di doverti ringraziare...', 'Suppongo di doverti ringraziare...', 28153),
(161338, 'itIT', 'C\'è qualcosa di cui vuoi parlare?', 'C\'è qualcosa di cui vuoi parlare?', 28153),
(161337, 'itIT', 'Fa caldo qui.', 'Fa caldo qui.', 28153),
(161336, 'itIT', '<Gesticoli in giro per la zona.>', '<Gesticoli in giro per la zona.>', 28153),
(161335, 'itIT', 'Stavi dicendo?', 'Stavi dicendo?', 28153),
(161334, 'itIT', 'È questo che avevi in mente?', 'È questo che avevi in mente?', 28153),
(161333, 'itIT', 'Ué! Nun tenere paura.', '', 28153),
(161332, 'itIT', 'Ecco, dovrebbe anche bastare per na bella mancia!', '', 28153),
(161331, 'itIT', 'Già, qualcosa che ho nascosto prima che mi catturassero. Devi solo trovare la torre appena fuori da Radivia, vicino al fiume di Nazmir. Sarà ai piedi suoi ad aspettarti.', '', 28153),
(161330, 'itIT', 'Mi sento come se io ti debba dei soldi da parecchio tempo, quindi ti lascerò pigliare il bottino sepolto mio.', '', 28153),
(161329, 'itIT', 'Devo ammetterlo, sei la guida migliore che nu teschio potrebbe chiedere.', '', 28153),
(161328, 'itIT', 'Mi sento bene. Sembra nu posto accogliente.', '', 28153),
(161327, 'itIT', 'Te l\'ho detto che ho sentito uno di chei mezz\'uomini neri dire che viveva in nu vulcano?', '', 28153),
(161326, 'itIT', 'Be\', può succedere... stai diventando blu... Nun pensare di lasciarmi accà.', '', 28153),
(161325, 'itIT', 'Sai, stavo per aprire na gara di corse a Vol\'dun. Il socio mio temeva che n\'altro cataclisma potesse spedirci sott\'acqua e si è ritirato. E poi nun tenevamo soldi, ce li hanno pigliati tutti quando siamo stati esiliati.', '', 28153),
(161324, 'itIT', 'Chello nun è nu vero rettile... però nun dirgli che te l\'ho detto io.', '', 28153),
(161323, 'itIT', 'Teniamo grossi rettili a Zandalar, i più grossi di tutti i tempi.', '', 28153),
(161322, 'itIT', 'Credo di sentire più freddo. È possibile?', '', 28153),
(161321, 'itIT', 'Hai mai visto na tigre nella neve? Che idea folle... la neve, intendo.', '', 28153),
(161320, 'itIT', 'Chesto posto è proprio carino. Quasi quasi lo infesto.', '', 28153),
(161319, 'itIT', 'Quando andiamo a visitare qualche bel posticino?', '', 28153),
(161318, 'itIT', '', 'Siamo venuti in questa fattoria con la speranza di poter dare una svolta alle nostre vite. Le cose non andavano bene in città e Ancel aveva difficoltà a scuola. Suo padre e io abbiamo pensato che sarebbe stato meglio per tutti trasferirci in campagna, dove i ritmi sono meno frenetici.\n\nHo dovuto rinunciare ai miei studi arcani per dedicarmi alla fattoria. Le cose non erano facili, il lavoro era molto duro e siamo sopravvissuti a stento per un bel po\' di tempo. Ogni volta che Raimond pensava di essere arrivato a una svolta, puntualmente accadeva qualcosa di terribile.\n\nFu allora che decidemmo che la cosa migliore sarebbe stata che io riprendessi i miei studi. Ho viaggiato, affinato le mie abilità e supportato la mia famiglia offrendo il mio talento a quanti pagassero adeguatamente.', 28153),
(161317, 'itIT', 'Fa nu po\' freddo accà, no? O sono solo io?', '', 28153),
(161316, 'itIT', 'Chesto posto sembra interessante.', '', 28153),
(161315, 'itIT', 'Dove stiamo oggi?', '', 28153),
(161314, 'itIT', 'Grazie...', 'Grazie...', 28153),
(161313, 'itIT', 'Dovremo tenercela per la prossima volta.', 'Dovremo tenercela per la prossima volta.', 28153),
(161312, 'itIT', 'Forse. Ma io non sono un Druido.', 'Forse. Ma io non sono una Druida.', 28153),
(161311, 'itIT', 'Certamente.', 'Certamente.', 28153),
(161310, 'itIT', 'Deve essere molto frustrante.', 'Deve essere molto frustrante.', 28153),
(161309, 'itIT', 'Io scommetto di sì.', 'Io scommetto di sì.', 28153),
(161308, 'itIT', 'Ma quelle forme più esotiche non ti permettono di volare più velocemente?', 'Ma quelle forme più esotiche non ti permettono di volare più velocemente?', 28153),
(161307, 'itIT', 'A dire il vero, ho cambiato idea. Non lo voglio sapere.', 'A dire il vero, ho cambiato idea. Non lo voglio sapere.', 28153),
(161306, 'itIT', 'Cosa ti ha fatto arrabbiare così?', 'Cosa ti ha fatto arrabbiare così?', 28153),
(161305, 'itIT', 'Sembri proprio avere una bella storia da raccontare.', 'Sembri proprio avere una bella storia da raccontare.', 28153),
(161304, 'itIT', '', 'Be\', è una lunga storia, ma sarei felice di raccontartela, se ti andasse di ascoltarmi. Puoi concedermi un momento?', 28153),
(161303, 'itIT', 'Non ti nasconderò niente. Anzi, te lo scriverò a caratteri cubitali, così che sia facile da leggere.', '', 28153),
(161302, 'itIT', 'Mi chiedo... Forse se insegnassi a te come potrebbero mostrarsi in modo rispettabile, pur mantenendo il loro tanto amato volo veloce, potrebbero ascoltarmi.', '', 28153),
(161301, 'itIT', 'È così, ma nessuno vuole ascoltarmi. Non fanno che scrollarsi le chiome, le foglie, le... oh be\', non farmi parlare...', '', 28153),
(161300, 'itIT', 'Sì... ma posso chiederti perché non sei con loro? Hanno fatto un bel pasticcio alla fattoria!', 'Sì... ma posso chiederti perché non sei con loro? Hanno fatto un bel pasticcio alla fattoria!', 28153),
(161299, 'itIT', 'Quella è ignoranza. Chi dice che un vecchio come me non possa competere con quelle nuove forme volanti? Le nostre forme originali ci hanno servito per millenni.', '', 28153),
(161298, 'itIT', 'Be\', vedi, i Druidi di oggi non rispettano noi tradizionalisti. Non andrei mai in giro a svolazzare con fiocchetti o armature vistose.', '', 28153),
(161297, 'itIT', '', 'Dove l\'hai trovata? Pensavo di averla persa per sempre!', 28153),
(161296, 'itIT', 'Ah, sei $gun Runografo:una Runografa;? Forse potrei consigliarti un bell\'incantesimo.', '', 28153),
(161295, 'itIT', 'Sono tutti così pomposi.', '', 28153),
(161294, 'itIT', 'Ai miei tempi la gente rispettava i metodi degli anziani.', '', 28153),
(161293, 'itIT', 'Sono venuto a Kul Tiras per allontanarmi dalla guerra. Questa è la mia vita.', '', 28153),
(161292, 'itIT', 'I Druidi di oggi non sono più quelli di una volta.', '', 28153),
(161291, 'itIT', 'Non vedi che sto prendendo il sole?', '', 28153),
(161290, 'itIT', 'Va\' via.', '', 28153),
(161289, 'itIT', 'Ho aperto una via. Devi scappare subito!', 'Ho aperto una via. Devi scappare subito!', 28153),
(161288, 'itIT', 'Lasciami in pace.', '', 28153),
(161287, 'itIT', '', 'Quale grande avventura ti ha portato da queste parti?', 28153),
(161286, 'itIT', '', 'Fare sacrifici, anche se per un bene superiore, è sempre difficile...', 28153),
(161285, 'itIT', '', 'Un giorno spero di poter tornare a casa con un potere in grado di rimediare alle nostre sfortune.', 28153),
(161284, 'itIT', '', 'La ricerca della conoscenza arcana è estenuante. A volte, i miei viaggi mi lasciano totalmente priva di forze.', 28153),
(161283, 'itIT', '', 'Hai figli? Chissà come se la sta cavando il mio povero Ancel... dovrei mandargli una lettera.', 28153),
(161282, 'itIT', '', 'Non hai alcun tipo di oggetto magico raro da vendere?', 28153),
(161281, 'itIT', '', 'Ehilà! È un piacere fare la tua conoscenza.', 28153),
(161280, 'itIT', 'Argh! Avevo la bocca aperta!', 'Argh! Avevo la bocca aperta!', 28153),
(161279, 'itIT', 'La benda! Non serve a nulla!', 'La benda! Non serve a nulla!', 28153),
(161278, 'itIT', 'Ahhh! Ti strapperò le piume una a una, dannato ratto volante!', 'Ahhh! Ti strapperò le piume una a una, dannato ratto volante!', 28153),
(161277, 'itIT', 'Argh! Mi ha preso nell\'occhio buono!', 'Argh! Mi ha preso nell\'occhio buono!', 28153),
(161276, 'itIT', 'Che tu sia maledetto, demonio piumato!', 'Che tu sia maledetto, demonio piumato!', 28153),
(161275, 'itIT', 'Uggghhh...', 'Uggghhh...', 28153),
(161274, 'itIT', 'Non di nuovo!', 'Non di nuovo!', 28153),
(161273, 'itIT', 'Argh! Disgustoso!', 'Argh! Disgustoso!', 28153),
(161272, 'itIT', 'Voi ragazzi non avete intenzione di perdere, vero? Ho puntato dei soldi su di voi... e mio padre non mi perdonerebbe mai se li perdessi.', '', 28153),
(161271, 'itIT', 'Nun temere, tesoro mio. Presto tornerò a pigliarti!', 'Nun temere, tesoro mio. Presto tornerò a pigliarti!', 28153),
(161270, 'itIT', 'Occhi aperti, soldato! Siamo in una zona di guerra!', '', 28153),
(161269, 'itIT', 'Guarda tutto quell\'oro, Sergente... È così luccicante!', '', 28153),
(161268, 'itIT', 'Ciao! Sto cercando di intrattenere i bambini. Hai qualcosa da consigliare?', 'Ciao! Sto cercando di intrattenere i bambini. Hai qualcosa da consigliare?', 28153),
(161267, 'itIT', '', 'Ehi, tu! Ti andrebbe di risolvere degli enigmi in cui il fallimento ti porterebbe alla morte o a trasformarti in una gallina? Allora dovresti considerare l\'idea di imparare l\'Ingegneria!', 28153),
(161266, 'itIT', '', 'Sai... Devo ancora finire quel Golem dei Cieli su cui stavo lavorando.', 28153),
(161265, 'itIT', 'Vorrei ascoltare una canzone seria.', 'Vorrei ascoltare una canzone seria.', 28153),
(161264, 'itIT', 'Mi piacerebbe sentire una storia sui Saggi delle Maree.', 'Mi piacerebbe sentire una storia sui Saggi delle Maree.', 28153),
(161263, 'itIT', 'Vorrei ascoltare una canzoncina ridicola.', 'Vorrei ascoltare una canzoncina ridicola.', 28153),
(161262, 'itIT', 'Parlami di Athair.', 'Parlami di Athair.', 28153),
(161261, 'itIT', 'Argenteria! Bollitori! Posate! Il tutto di qualità Bracescura!', 'Argenteria! Bollitori! Posate! Il tutto di qualità Bracescura!', 28153),
(161260, 'itIT', '', 'Se aumento la forza della carica iniziale, aumenterà anche la resa finale... non ci sarà alcun ritorno di fiamma, vero?', 28153),
(161259, 'itIT', 'Ho qualcosa per tutti!', 'Ho qualcosa per tutti!', 28153),
(161258, 'itIT', 'Orologi da tasca per marinai! Alcuni di questi non vengono nemmeno più prodotti!', 'Orologi da tasca per marinai! Alcuni di questi non vengono nemmeno più prodotti!', 28153),
(161257, 'itIT', 'Dodici monete d\'argento in meno di ogni altro posto a Ventosaldo!', 'Dodici monete d\'argento in meno di ogni altro posto a Ventosaldo!', 28153),
(161256, 'itIT', 'Per tutte le bussole! Direttamente dalle scorte personali dell\'Ammiragliato!', 'Per tutte le bussole! Direttamente dalle scorte personali dell\'Ammiragliato!', 28153),
(161255, 'itIT', '', 'Dove avrò messo la mia Chiave ad Arco?', 28153),
(161254, 'itIT', 'Lascia che scappino come ratti di sentina. Lancia le cariche di profondità su di loro, $p!', 'Lascia che scappino come ratti di sentina. Lancia le cariche di profondità su di loro, $p!', 28153),
(161253, 'itIT', 'Guarda giù, $p! Hanno interi magazzini sott\'acqua. Lancia delle cariche di profondità!', '', 28153),
(161252, 'itIT', '', 'Magnifico! È incredibilmente lucrativo!', 28153),
(161251, 'itIT', '', 'Dov\'è finito quell\'anello? Ce l\'avevo addosso quando ero... oh cielo... non di nuovo.', 28153),
(161250, 'itIT', '', 'Anche il più forte dei guerrieri ha bisogno di armature e armi magiche. Impara l\'arte dell\'incantamento!', 28153),
(161249, 'itIT', '', 'Vuoi cimentarti nelle arti arcane? Imparerai a incantare oggetti con poteri magici!', 28153),
(161248, 'itIT', 'E i cannoni sulle mura!', '', 28153),
(161247, 'itIT', 'Concentrate il fuoco delle torce sulle canoe che sventolano bandiera rossa!', '', 28153),
(161246, 'itIT', 'E i cannoni sulle mura! Nun tengo intenzione di finire in pasto ai pesci oggi.', '', 28153),
(161245, 'itIT', 'Concentrate le torce sulle canoe che sventolano bandiera rossa!', '', 28153),
(161244, 'itIT', 'Impara a padroneggiare le spezie e le fiamme!', '', 28153),
(161243, 'itIT', 'Hai fame? Vuoi risolvere il problema? Cucinati qualcosa!', '', 28153),
(161242, 'itIT', 'La nostra carne affumicata vi farà venire l\'acquolina in bocca! Non è in vendita, ma potrete imparare a cucinarla!', '', 28153),
(161241, 'itIT', '', 'Il giorno che scoprirò il buontempone che continua a lasciare che queste reliquie si rompano durante il trasporto, gli romperò fino all\'ultimo osso.', 28153),
(161240, 'itIT', '', 'Hai dimostrato di avere grande coraggio e onore. Insieme a Re Rastakhan, abbiamo convenuto che potresti essere la persona giusta a cui affidare altri incarichi importanti.\n\nOra stai all\'erta, nun tengo dubbi che delli sguardi ostili stiano seguendo le mosse nostre.', 28153),
(161239, 'itIT', '', 'Questo mi frutterà un bel gruzzoletto da un collezionista.', 28153),
(161238, 'itIT', 'Ed è per questo che le nostre navi sono le migliori!', 'Ed è per questo che le nostre navi sono le migliori!', 28153),
(161237, 'itIT', 'Domenic, con le mani tremanti e gli occhi sgranati, capì che il mare aveva risposto al suo richiamo.', 'Domenic, con le mani tremanti e gli occhi sgranati, capì che il mare aveva risposto al suo richiamo.', 28153),
(161236, 'itIT', 'Le acque però si ritirarono e la bestia si incagliò sulle rocce!', 'Le acque però si ritirarono e la bestia si incagliò sulle rocce!', 28153),
(161234, 'itIT', 'Fece sobbalzare le navi oltre le rocce, mentre il kraken che li stava inseguendo cercò di fare di tutto per non perdere di vista la sua preda!', 'Fece sobbalzare le navi oltre le rocce, mentre il kraken che li stava inseguendo cercò di fare di tutto per non perdere di vista la sua preda!', 28153),
(161233, 'itIT', '', 'Devo calibrare il mio equipaggiamento di sopravvivenza per la prossima uscita.', 28153),
(161231, 'itIT', 'Poi, all\'improvviso, un kraken tre volte più grande di quello che stava dando loro la caccia, spuntò dalla superficie dell\'acqua!', 'Poi, all\'improvviso, un kraken tre volte più grande di quello che stava dando loro la caccia, spuntò dalla superficie dell\'acqua!', 28153),
(161229, 'itIT', '\"Siamo spacciati!\", urlò la ciurma.', '\"Siamo spacciati!\", urlò la ciurma.', 28153),
(161228, 'itIT', 'Delle enormi pietre spuntarono all\'improvviso dalle acque davanti a loro.', 'Delle enormi pietre spuntarono all\'improvviso dalle acque davanti a loro.', 28153),
(161227, 'itIT', 'Sfrecciando tra le rocce, le indicazioni di Domenic si rivelarono corrette, ma il kraken non faceva che guadagnare terreno.', 'Sfrecciando tra le rocce, le indicazioni di Domenic si rivelarono corrette, ma il kraken non faceva che guadagnare terreno.', 28153),
(161226, 'itIT', '\"A babordo!\", strillò Domenic in preda al panico, mentre le onde lo trascinavano in quella direzione. La nave si girò. \"A dritta, avanti così!\" Ancora una volta, la sorella seguì le sue direzioni.', '\"A babordo!\", strillò Domenic in preda al panico, mentre le onde lo trascinavano in quella direzione. La nave si girò. \"A dritta, avanti così!\" Ancora una volta, la sorella seguì le sue direzioni.', 28153),
(161225, 'itIT', 'Un enorme kraken, più grosso della loro nave più massiccia, spuntò dagli abissi!', 'Un enorme kraken, più grosso della loro nave più massiccia, spuntò dagli abissi!', 28153),
(161224, 'itIT', 'Ma quando arrivarono, scoprirono molto presto di essere loro le prede di un altro cacciatore.', 'Ma quando arrivarono, scoprirono molto presto di essere loro le prede di un altro cacciatore.', 28153),
(161223, 'itIT', '\"Credo che le acque saranno sicure e i venti calmi\", disse Domenic. Le sue previsioni si dimostrarono vere, e la piccola flotta rimase colpita dalla rapidità con cui raggiunsero la destinazione.', '\"Credo che le acque saranno sicure e i venti calmi\", disse Domenic. Le sue previsioni si dimostrarono vere, e la piccola flotta rimase colpita dalla rapidità con cui raggiunsero la destinazione.', 28153),
(161222, 'itIT', '\"Ma sono pericolose!\", urlò la ciurma. \"La nave verrà fatta a pezzi!\"', '\"Ma sono pericolose!\", urlò la ciurma. \"La nave verrà fatta a pezzi!\"', 28153),
(161221, 'itIT', 'Suo fratello considerò la questione per molto tempo, come se stesse ascoltando una canzone che nessun altro poteva sentire. Poi indicò una direzione. \"Ho un buon presentimento sulle secche vicino a Kalimdor\".', 'Suo fratello considerò la questione per molto tempo, come se stesse ascoltando una canzone che nessun altro poteva sentire. Poi indicò una direzione. \"Ho un buon presentimento sulle secche vicino a Kalimdor\".', 28153),
(161220, 'itIT', '\"Fratello, dove pensi dovremmo andare a caccia?\", chiese, affidandosi alla sua infallibile intuizione.', '\"Fratello, dove pensi dovremmo andare a caccia?\", chiese, affidandosi alla sua infallibile intuizione.', 28153),
(161219, 'itIT', 'Korralyn decise di andare a cercare altrove.', 'Korralyn decise di andare a cercare altrove.', 28153),
(161218, 'itIT', 'Un giorno partì per andare a caccia di Kraken per sfamare l\'intera flotta, ma non riuscì a trovare nulla nei soliti posti. Per settimane non riuscirono a trovare un solo pesce e la situazione diventò sempre più grave.', 'Un giorno partì per andare a caccia di Kraken per sfamare l\'intera flotta, ma non riuscì a trovare nulla nei soliti posti. Per settimane non riuscirono a trovare un solo pesce e la situazione diventò sempre più grave.', 28153),
(161217, 'itIT', 'Un giorno partì a caccia di kraken per sfamare l\'intera flotta, ma non riuscì a trovare nulla nei soliti posti.', 'Un giorno partì a caccia di kraken per sfamare l\'intera flotta, ma non riuscì a trovare nulla nei soliti posti.', 28153),
(161215, 'itIT', 'Sembrava conoscere il mare come nessun altro. Sapeva quando si sarebbero scatenate le tempeste, quando le maree sarebbero cambiate e dove pescare in cerca di cibo.', 'Sembrava conoscere il mare come nessun altro. Sapeva quando si sarebbero scatenate le tempeste, quando le maree sarebbero cambiate e dove pescare in cerca di cibo.', 28153),
(161214, 'itIT', 'Mentre Koralynn osservava e imparava, teneva sotto controllo anche suo fratello.', 'Mentre Koralynn osservava e imparava, teneva sotto controllo anche suo fratello.', 28153),
(161213, 'itIT', 'Interessante! Non era mai successo QUESTO prima d\'ora...', '', 28153),
(161212, 'itIT', 'Nota per me stesso: l\'estratto di Muschio Stellare scarseggia. Rimpolpare le scorte appena possibile.', '', 28153),
(161211, 'itIT', 'Per questo motivo, rimanemmo molto sorpresi quando Koralynn lo volle nella sua ciurma durante il suo primo comando.', 'Per questo motivo, rimanemmo molto sorpresi quando Koralynn lo volle nella sua ciurma durante il suo primo comando.', 28153),
(161210, 'itIT', 'Per non parlare dei suoi tentativi di condurre una galea!', 'Per non parlare dei suoi tentativi di condurre una galea!', 28153),
(161209, 'itIT', 'Ahhh, si è condensata a dovere.', '', 28153),
(161208, 'itIT', 'Inciampava continuamente nelle sartie e non riuscì mai a imparare come fare dei nodi appropriati o come maneggiare le vele.', 'Inciampava continuamente nelle sartie e non riuscì mai a imparare come fare dei nodi appropriati o come maneggiare le vele.', 28153),
(161207, 'itIT', 'Domenic era strano. Camminava come se fosse in un sogno, spesso borbottando tra sé e sé.', 'Domenic era strano. Camminava come se fosse in un sogno, spesso borbottando tra sé e sé.', 28153),
(161206, 'itIT', 'Devo solo alzare un po\' la temperatura per questa...', '', 28153),
(161205, 'itIT', 'Koralynn era tutto ciò che i Kul Tirani dovrebbero essere. Lo stesso non valeva per suo fratello.', 'Koralynn era tutto ciò che i Kul Tirani dovrebbero essere. Lo stesso non valeva per suo fratello.', 28153),
(161203, 'itIT', 'Studiava le carte astronomiche, le correnti e i campi da caccia. Imparava guardando i marinai.', 'Studiava le carte astronomiche, le correnti e i campi da caccia. Imparava guardando i marinai.', 28153),
(161202, 'itIT', 'Mmm... potrei dover ordinare a Enges altre Fjarnskaggl.', '', 28153),
(161201, 'itIT', 'Koralynn era forte e astuta.', 'Koralynn era forte e astuta.', 28153),
(161200, 'itIT', 'Molto tempo fa, vivevano due bambini, Koralynn e Domenic.', 'Molto tempo fa, vivevano due bambini, Koralynn e Domenic.', 28153),
(161199, 'itIT', '', 'Grazie, Comandante, saremmo morti tutti se non ci avessi salvati! Torneremo immediatamente ai nostri posti!', 28153),
(161198, 'itIT', '<Miimii decide di seguirti.>', '<Miimii decide di seguirti.>', 28153),
(161197, 'itIT', '<Un suono proviene dal sarcofago nelle vicinanze...>', '<Un suono proviene dal sarcofago nelle vicinanze...>', 28153),
(161196, 'itIT', '<Miimii la mummia ti guarda in attesa.>', '<Miimii la mummia ti guarda in attesa.>', 28153),
(161195, 'itIT', 'Nessun pesce? Mi sa che morirò...', '', 28153),
(161194, 'itIT', 'Ah, mi sembra passata un\'eternità dall\'ultima volta che ho mangiato.', '', 28153),
(161193, 'itIT', 'Non ha ancora abboccato nulla?!?', '', 28153),
(161192, 'itIT', 'Ho assistito a molti eventi importanti. Ho visto la storia evolversi, conflitti risolversi e rinnovarsi, tradimenti consumarsi e grandi vittorie compiersi.\n\nQuesta è una vera e propria sconfitta. Zul ci ha battuti a ogni occasione ed è riuscito a raggiungere il suo obiettivo. Non possiamo permettere che questa sia la fine di tutto.\n\nL\'imminente conflitto con quest\'antico nemico, un avversario che questa gente ha dovuto affrontare sin dall\'alba della loro civiltà, plasmerà il destino dell\'Orda e degli Zandalari. Risponderemo alla loro chiamata e saneremo ogni torto causato da Zul.\n\nSii $gpronto:pronta;, sii vigile e non cedere mai, $n.', '', 28153),
(161191, 'itIT', '', 'Temevo di non riuscire a portare queste provviste alla tua armata. Grazie, accetta queste risorse come ricompensa.', 28153),
(161190, 'itIT', 'Non so cosa stia pensando il Re degli Zandalari in questo momento, ma so che non possiamo lasciare che questi eventi ci distraggano dal nostro obiettivo. Gli Zandalari devono sopravvivere a questo conflitto. L\'Orda ha giurato di difenderli e potremmo ritrovarci soli se i loro dei non li salveranno.\n\nHanno bisogno di te, ora più che mai. Agisci in nostro nome, Voce dell\'Orda.', '', 28153),
(161189, 'itIT', '', 'Fantastico! Pensavo di essere spacciata, ma poi sei $garrivato:arrivata; tu! Per ringraziarti, potenzierò le armature della tua armata!', 28153),
(161188, 'itIT', 'Stai cercando magia e terre lontane? O forse è la guerra che ti sta portando lontano da noi?\n\nSe stai cercando i portali per Roccavento, Forgiardente ed Exodar, li troverai al piano inferiore del Mercato di Ventosaldo, lungo il lato meridionale. Cerca la stanza vicino quello strano trasmogrificatore Etereo.', 'Stai cercando magia e terre lontane? O forse è la guerra che ti sta portando lontano da noi?\n\nSe stai cercando i portali per Roccavento, Forgiardente ed Exodar, li troverai al piano inferiore del Mercato di Ventosaldo, lungo il lato meridionale. Cerca la stanza vicino quello strano trasmogrificatore Etereo.', 28153),
(161187, 'itIT', '', 'Dobbiamo avere speranza. Jaina potrebbe essere ancora in vita.', 28153),
(161186, 'itIT', 'Riesco a vedere l\'oscurità nei tuoi occhi. Il tuo prossimo sforzo ti lacererà la mente e diventerai un altro fantasma che tormenterà la mia vita.$b$bNon sei $gpronto:pronta;. Torna quando lo sarai e il tuo prossimo compito sarà qui ad attenderti. La corruzione ha avuto un\'eternità per attecchire e diffondersi, una manciata di giorni in più non cambierà nulla.', '', 28153),
(161185, 'itIT', 'Ho trovato quest\'indizio negli uffici dei Bracescura.', 'Ho trovato quest\'indizio negli uffici dei Bracescura.', 28153),
(161184, 'itIT', 'Quindi alla fine sei $griuscito:riuscita; a salvarmi, eh? Be\', direi che te ne devo una. Forse potrei ripagarti potenziando le armi della tua armata.', '', 28153),
(161183, 'itIT', '', 'Mi rifiuto di credere che Jaina sia morta.', 28153),
(161181, 'itIT', 'Ah, adoro la Birra di Ventosaldo! È fantastica!\n\nMi sa che darò questa indietro e ne prenderò un\'altra!', '', 28153),
(161180, 'itIT', 'Adoro la birra di qui. È tra le mie preferite!\n\nSalute!', '', 28153),
(161179, 'itIT', '$gBenvenuto:Benvenuta; alla nostra birreria!\n\nSpero ti piaceranno le birre che abbiamo qui. Se vuoi comprare dei barili per qualche evento, fammi un fischio.\n\nNel frattempo, perché non ti bevi qualcosa?', '', 28153),
(161178, 'itIT', 'Eccoti qui! Le forze di Zul hanno cercato di cacciarci via, ma l\'Orda ha dimostrato la sua forza. Lo scontro per ora è concluso.\n\nAvevamo ragione di sospettare che Zul stesse complottando contro di noi, ma non credevo che avrebbe agito così presto e con tanta fermezza. Immagino che le sue abilità di profeta fossero realmente valide.\n\nDobbiamo mobilitarci per aiutare i nostri nuovi alleati. Vai e fai il possibile per rimettere Re Rastakhan al potere. L\'Orda manterrà l\'ordine.', '', 28153),
(161177, 'itIT', 'Il potere che per primo di sedette su chesto trono dominò su tutta la gente civilizzata di chesto mondo.\n\nMo\' guardaci, ridotti a stare tutti su na sola isola. Pure i Troll più insignificanti nun temono più il potere nostro.\n\nMa nun sarà così per sempre.', '', 28153),
(161176, 'itIT', 'Sei $garrivato:arrivata; a bordo di quella nave? Sembra nuova. Parlami della sua architettura strutturale davanti a una bella birra!', '', 28153),
(161175, 'itIT', 'Altro giorno, altra birra!\n\nQual è la tua preferita?', '', 28153),
(161174, 'itIT', 'Qualcuno ha bisogno di un\'aggiustatina?', '', 28153),
(161173, 'itIT', 'Salute!', '', 28153),
(161172, 'itIT', 'La figlia mia crede che le minacce a Nazmir siano talmente grandi che dovremmo inviare l\'intera armata nostra al confine settentrionale.\n\nÈ giovane e impaziente e nun capisce che i Troll del Sangue sono na spina nel fianco della gente nostra da generazioni.\n\nSe crede che l\'Orda possa aiutarla, allora nun vedo l\'ora di vedere cosa riuscirete a fare. Potrebbe farle comodo nu po\' di esperienza con delle potenze straniere.\n\nSe le venisse fatto del male, sappi che ridurrò in cenere l\'intera Orda tua e trasformerò chella collezione di barchette che chiami flotta in nu cumulo di relitti.\n\nBuona fortuna.', '', 28153),
(161171, 'itIT', 'Salute a tutti!', '', 28153),
(161170, 'itIT', 'Non appena avrò finito di bere, andrò da loro ad aiutarli.', '', 28153),
(161169, 'itIT', 'Malfurion ci informò che la Legione Infuocata stava attaccando la Riva Dispersa!', '', 28153),
(161168, 'itIT', 'Tyrande e io stavamo insieme prima che conoscessi la mia cara Mildred.', '', 28153),
(161167, 'itIT', 'Mi misi subito al lavoro per salvare ogni singolo barile!', '', 28153),
(161166, 'itIT', 'La nave affondò, la gente iniziò ad affogare e trenta barili di rum di Tiragarde finirono sul fondo.', '', 28153),
(161165, 'itIT', 'Neanche una birra decente in tutto il Bosco dei Sogni. È per questo che non ci vado mai.', '', 28153),
(161164, 'itIT', 'Tutti a bordo per Zuldazar!', '', 28153),
(161163, 'itIT', 'Tutti a bordo per le Isole dell\'Eco!', '', 28153),
(161162, 'itIT', 'Non temere la guerra imminente, $p. Solo quando siamo messi a dura prova, viene fuori la parte più forte di noi.', '', 28153),
(161161, 'itIT', 'Devi convincere il Re a trasferirmi in un posto con un clima più temperato!', '', 28153),
(161160, 'itIT', 'La battaglia è appena iniziata, $p. Spero che tu sia in grado di affrontare le difficoltà della guerra.', '', 28153),
(161159, 'itIT', 'Qualcuno dovrebbe darmi un aumento. Indennità di rischio, $R! Indennità di rischio!', '', 28153),
(161158, 'itIT', 'Potrei darmi fuoco da solo al prossimo insetto che mi punge nelle parti basse. Odio questo posto!', '', 28153),
(161157, 'itIT', 'L\'Orda può anche mandare i suoi migliori soldati contro di noi. Muoio dalla voglia di provare la mia nuova lama contro un degno avversario.', '', 28153),
(161156, 'itIT', 'Ah! Che caldo! Riesci a vedere i rivoli di sudore sulla mia barba?', '', 28153),
(161155, 'itIT', 'Se pensi di poter dare una mano, per favore, fallo. Non serve chiedere il permesso in questi tempi difficili.', '', 28153),
(161154, 'itIT', 'Nun temere, chesta è una delle navi più veloci di Zandalar. Arriverai presto a destinazione.', '', 28153),
(161153, 'itIT', 'Se vogliamo eliminare l\'Orda, dobbiamo essere scaltri e precisi. Non bisogna commettere errori.', '', 28153),
(161152, 'itIT', 'In arrivo alle Isole dell\'Eco!', '', 28153),
(161151, 'itIT', 'In arrivo a Zuldazar!', '', 28153),
(161150, 'itIT', 'Ho appena finito di riordinare questi barili di birra dalla più chiara alla più scura.\n\nForse però dovrei metterli in ordine alfabetico... o per annata... o per tipo di malto...', '', 28153),
(161149, 'itIT', '', 'Ciao, $gcaro:cara;. Stai cercando un compagno fidato? Una creatura da coccolare nelle giornate piovose? Un migliore amico con cui condividere le gioie e le difficoltà della vita?', 28153),
(161148, 'itIT', 'Mmm... cheshto mi ricorda... di quando ho imparato a estrarre minerali... Secott mi diceva shempre... il trucco shta nel colpire col piccone con la giushta inclinazione... mantiene i... minerali...', 'Bleah! Troppa sholarancia...', 28153),
(161147, 'itIT', 'Grazie, Comandante, saremmo morti tutti se non ci avessi salvati! Torneremo immediatamente ai nostri posti!', '', 28153),
(161146, 'itIT', 'Cheshto è proprio na \"manata\", bene.', 'Cheshta sì che è n\'Amanata! Bene.', 28153),
(161145, 'itIT', 'Intravedo già la nostra vittoria.', 'Intravedo già la nostra vittoria.', 28153),
(161144, 'itIT', 'Ho sempre odiato questa foresta.', 'Ho sempre odiato questa foresta.', 28153),
(161143, 'itIT', 'Era forshe... nu shecchio d\'acqua lercia?', 'Era forshe... nu shecchio d\'acqua lercia?', 28153),
(161142, 'itIT', 'L\'albero sarà nostro.', 'L\'albero sarà nostro.', 28153),
(161141, 'itIT', 'Uh, no! Io odio il gin, cumpà!', 'Uh, no! Io odio il gin, cumpà!', 28153),
(161140, 'itIT', '', 'La nave dovrebbe aver lasciato Zandalar ed essere diretta accà in chesto momento.', 28153),
(161139, 'itIT', 'Almeno sono morto combattendo.', 'Almeno sono morta combattendo.', 28153),
(161138, 'itIT', '', 'Sta dall\'altra parte dell\'oceano, a Zandalar. Tornerà assai presto, nun temere.', 28153),
(161137, 'itIT', 'Non sei nient\'altro che un contrattempo.', 'Non sei nient\'altro che un contrattempo.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(161136, 'itIT', 'Cheshto sa di cadavere, cumpà.', 'Cheshto sa di cadavere, cumpà.', 28153),
(161135, 'itIT', '', 'La nave è appena partita per Zandalar. Tornerà assai presto.', 28153),
(161134, 'itIT', '', 'Sta proprio davanti a te. Sali su!', 28153),
(161133, 'itIT', 'Ugh, che cos\'è cheshto? Vino dei Tortolliani?', 'Ugh, che cos\'è cheshto? Vino dei Tortolliani?', 28153),
(161132, 'itIT', 'Consiglio di abbinare la nostra Birra Scura del Presidio della Pesca con dei deliziosi Semi Tostati di Pianta Sferzante.\n\nNon farti ingannare dal nome, i sentori tostati dei semi vanno perfettamente a nozze con il ricco sapore maltato della birra. Può sembrare uno strano abbinamento, ma ti posso garantire che è uno dei miei preferiti.', '', 28153),
(161131, 'itIT', 'Bleah! Troppa sholarancia...', 'Bleah! Troppa sholarancia...', 28153),
(161130, 'itIT', 'Consiglio di abbinare la nostra Birra Chiara con Patina al mio piatto preferito, la Gallina Speziata del Colonnello Teneroni.\n\nIl gusto mieloso della birra si sposa perfettamente con la piccantezza della gallina. È ideale per addolcire il palato, in caso la sensazione diventi troppo forte.', '', 28153),
(161129, 'itIT', 'Ciao! Sei qui per ammirare la mia collezione?', '', 28153),
(161128, 'itIT', 'Vi incoraggio a seguire l\'esempio suo. Piegatevi, così da nun spezzarvi, e lasciate cadere i nemici vostri sulle rocce, quando avete finito con loro!', 'Vi incoraggio a seguire l\'esempio suo. Piegatevi, così da nun spezzarvi, e lasciate cadere i nemici vostri sulle rocce, quando avete finito con loro!', 28153),
(161127, 'itIT', '', 'Nun ne sono sicura, ma na tempesta si sta formando all\'orizzonte.', 28153),
(161126, 'itIT', 'I venti portano altro, oltre a tempeste e commercio. Portano cambiamento. Cambiamento che Pa\'ku ci ha insegnato a sfruttare.', 'I venti portano altro, oltre a tempeste e commercio. Portano cambiamento. Cambiamento che Pa\'ku ci ha insegnato a sfruttare.', 28153),
(161125, 'itIT', 'Shtavo proprio penshando... Hic!... di prendere qualcosha da bere...', 'Shtavo proprio penshando... Hic!... di prendere qualcosha da bere...', 28153),
(161124, 'itIT', 'Hai già perso!', 'Hai già perso!', 28153),
(161123, 'itIT', 'Ci prenderemo ciò che è nostro!', 'Ci prenderemo ciò che è nostro!', 28153),
(161122, 'itIT', 'Guardate al di là delle parole infastidite di coloro che si sono spezzati sotto le tempeste sue. Guardate invece coloro che si sono piegati sotto di esse.', 'Guardate al di là delle parole infastidite di coloro che si sono spezzati sotto le tempeste sue. Guardate invece coloro che si sono piegati sotto di esse.', 28153),
(161121, 'itIT', 'Che cosh\'hai?', 'Che cosh\'hai?', 28153),
(161120, 'itIT', 'Si dice che sia capricciosa, soggetta alla rabbia e volubile, ma vi sfido a guardarla più da vicino.', 'Si dice che sia capricciosa, soggetta alla rabbia e volubile, ma vi sfido a guardarla più da vicino.', 28153),
(161119, 'itIT', 'Avrai l\'onore di morire per mano mia.', 'Avrai l\'onore di morire per mano mia.', 28153),
(161118, 'itIT', 'Tieni qualcosha da bere?', 'Tieni qualcosha da bere?', 28153),
(161117, 'itIT', 'Meglio che sia na cosha importante...', 'Meglio che sia na cosha importante...', 28153),
(161116, 'itIT', 'I venti suoi portano la pioggia, gonfiano le vele e spingono le navi nostre sui mari. La forza sua è tutto ciò che siamo!', 'I venti suoi portano la pioggia, gonfiano le vele e spingono le navi nostre sui mari. La forza sua è tutto ciò che siamo!', 28153),
(161115, 'itIT', 'Consiglio di abbinare la nostra Birra Chiara dei Pontili al nostro Merluzzo Marino Salato.\n\nL\'intensa amarezza della birra contrasta perfettamente la dolcezza del merluzzo, mentre i luppoli aggiungono un tocco speziato al noto sentore salmastro del pesce.', '', 28153),
(161114, 'itIT', '', 'Stai andando a Zandalar? È lì che sta andando la nave attraccata accà, cumpà.', 28153),
(161113, 'itIT', 'Arrivo, amore mio...', 'Arrivo, amore mio...', 28153),
(161112, 'itIT', 'Offri l\'Amanata', 'Offri l\'Amanata', 28153),
(161111, 'itIT', 'Offri il Succo di Jani', 'Offri il Succo di Jani', 28153),
(161110, 'itIT', 'Offri il Mojo\'ito', 'Offri il Mojo\'ito', 28153),
(161109, 'itIT', 'Offri il Zul\'gin', 'Offri il Zul\'gin', 28153),
(161108, 'itIT', 'Offri il Bwonzombi', 'Offri il Bwonzombi', 28153),
(161107, 'itIT', 'Offri la Sangria della Grotta', 'Offri la Sangria della Grotta', 28153),
(161106, 'itIT', 'Suggerirei di abbinare la nostra Birra Scura dell\'Ancora Gettata con un ottimo Formaggio Nordico di Guadobasso.\n\nAdoro gli abbinamenti di birra e formaggio e devo dire che questi due si sposano alla perfezione. Entrambi gli elementi hanno un retrogusto dolciastro e abbinati assieme fanno esplodere il palato.', '', 28153),
(161105, 'itIT', 'Offri il Trolgarita', 'Offri il Trolgarita', 28153),
(161104, 'itIT', 'Che la morte ti colga...', 'Che la morte ti colga...', 28153),
(161103, 'itIT', '', 'Quando una mia mascotte cade in battaglia, le altre si fanno solo più forti.', 28153),
(161102, 'itIT', 'Perché non sento gli uccelli cinguettare?', 'Perché non sento gli uccelli cinguettare?', 28153),
(161101, 'itIT', 'Dama Tyrande vi fermerà.', 'Dama Tyrande vi fermerà.', 28153),
(161100, 'itIT', '', 'Le specie di Zandalar sono di una forza impareggiabile. Le tue mascotte non hanno possibilità.', 28153),
(161099, 'itIT', 'Mai mettere alle strette una Fiera della Notte ferita...', 'Mai mettere alle strette una Fiera della Notte ferita...', 28153),
(161098, 'itIT', 'Questa terra è nostra!', 'Questa terra è nostra!', 28153),
(161097, 'itIT', '', 'Questo proprio non me lo aspettavo. La prossima volta vincerò io sicuramente.', 28153),
(161096, 'itIT', '', 'Pare che io abbia un bel vantaggio qui, a casa mia.', 28153),
(161095, 'itIT', 'Tutto questo per l\'onore.', 'Tutto questo per l\'onore.', 28153),
(161094, 'itIT', '', 'Osi affrontarmi nella mia stessa dimora? Buona fortuna.', 28153),
(161093, 'itIT', 'Non voglio ucciderti, ma lo farò.', 'Non voglio ucciderti, ma lo farò.', 28153),
(161092, 'itIT', '', 'Forse quella non era la specie più forte là fuori. Devo cercare di catturare esemplari migliori.', 28153),
(161091, 'itIT', 'Consiglierei di abbinare la nostra Birra al Sinforicarpo con un fantastico Semifreddo al Sinforicarpo!\n\nCon questo abbinamento, potrete assaporare entrambe le note di sapore del Sinforicarpo: il suo lato amaro sorseggiando la birra e la sua delicata dolcezza nel semifreddo. La cremosità del semifreddo fa da contrasto all\'aggressività della birra, facendovi provare un\'esperienza davvero straordinaria.', '', 28153),
(161090, 'itIT', '', 'Questo probabilmente lascerà una bella cicatrice.', 28153),
(161089, 'itIT', '', 'Mi serve più tempo per allenarmi con queste nuove specie. La prossima volta che ci incontreremo sarò più forte.', 28153),
(161088, 'itIT', '', 'Come ho già detto, gli animali di questa terra sono crudeli. Comunque, è stato un bello scontro.', 28153),
(161087, 'itIT', '', 'Gli animali di questa terra sono crudeli. Spero che tu sia $gpronto:pronta;', 28153),
(161086, 'itIT', '', 'Non ti preoccupare, piccolino, mi prenderò cura di te.', 28153),
(161085, 'itIT', 'Tutto deve morire.', 'Tutto deve morire.', 28153),
(161084, 'itIT', '', 'Non essere triste per averla persa, le altre mascotte che hai sembrano piuttosto forti.', 28153),
(161083, 'itIT', 'Volevo solo proteggere la mia casa.', 'Volevo solo proteggere la mia casa.', 28153),
(161082, 'itIT', '', 'Direi che sono fuori allenamento.', 28153),
(161081, 'itIT', 'Spero di sognare...', 'Spero di sognare...', 28153),
(161080, 'itIT', '', 'Santo cielo, a quanto pare avevo una squadra più forte di quanto pensassi.', 28153),
(161079, 'itIT', 'Le foglie cadono...', 'Le foglie cadono...', 28153),
(161078, 'itIT', 'Vorrei avere il tempo di ucciderti lentamente.', 'Vorrei avere il tempo di ucciderti lentamente.', 28153),
(161077, 'itIT', '', 'È da molto che non combatto. Spero di essere una degna avversaria.', 28153),
(161076, 'itIT', 'Fuori gli artigli!', 'Fuori gli artigli!', 28153),
(161075, 'itIT', 'Che le spine di trafiggano!', 'Che le spine di trafiggano!', 28153),
(161074, 'itIT', '', 'Non ero pronta. Questa non conta!', 28153),
(161073, 'itIT', 'Vendicherò la foresta!', 'Vendicherò la foresta!', 28153),
(161072, 'itIT', '', 'A quanto pare la mia serie di vittorie sta per continuare.', 28153),
(161071, 'itIT', 'Consiglio di abbinare la nostra Birra di Ventosaldo con il Pane di Segale al Cumino fatto in casa.\n\nIl gusto soffice della birra si abbina davvero perfettamente con il gusto dei cereali dato dal pane, ripulendo anche il palato dai sentori di carbonatazione.', '', 28153),
(161070, 'itIT', '', 'Questa non conta come sconfitta.', 28153),
(161069, 'itIT', '', 'Urrà, la mia serie di vittorie continua!', 28153),
(161068, 'itIT', '', 'Sono in piena serie di vittorie. Non hai possibilità contro di me e la mia squadra.', 28153),
(161067, 'itIT', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t L\'Avatar non è più |cFFFF0000|Hspell:274148|h[Contaminato]|h|r. Le tue cure ora hanno la massima efficacia!', '|TInterface\\Icons\\ABILITY_WARLOCK_HAUNT.BLP:20|t L\'Avatar non è più |cFFFF0000|Hspell:274148|h[Contaminato]|h|r. Le tue cure ora hanno la massima efficacia!', 28153),
(161066, 'itIT', 'Non temere la sconfitta, ti spronerà a migliorare.', '', 28153),
(161065, 'itIT', 'Mi piacerebbe acquistare del cibo.', 'Mi piacerebbe acquistare del cibo.', 28153),
(161064, 'itIT', 'La vittoria è a portata di mano. Riesco quasi a sentirla.', '', 28153),
(161063, 'itIT', 'Ringraziamo Gonk, corriamo con il branco suo, sapendo che tutti i sentieri sono aperti davanti a noi. Questo è il regalo suo alli Zandalari.', 'Ringraziamo Gonk, corriamo con il branco suo, sapendo che tutti i sentieri sono aperti davanti a noi. Questo è il regalo suo alli Zandalari.', 28153),
(161062, 'itIT', 'Ma Gonk è saggio e sa che insieme siamo più forti che da soli. Nun vuole che l\'idolo suo stia solo sulli altari vostri.', 'Ma Gonk è saggio e sa che insieme siamo più forti che da soli. Nun vuole che l\'idolo suo stia solo sulli altari vostri.', 28153),
(161061, 'itIT', 'Che cosa consigli di abbinare alla Birra Scura del Presidio della Pesca?', 'Che cosa consigli di abbinare alla Birra Scura del Presidio della Pesca?', 28153),
(161060, 'itIT', 'Incredibile. Erano anni che non perdevo uno scontro. Ottimo lavoro!', '', 28153),
(161059, 'itIT', 'Con un po\' di pratica, potresti diventare una bella sfida anche per me. Continua così.', '', 28153),
(161058, 'itIT', 'Che cosa consigli di abbinare alla Birra Chiara con Patina?', 'Che cosa consigli di abbinare alla Birra Chiara con Patina?', 28153),
(161057, 'itIT', 'Che cosa consigli di abbinare alla Birra Chiara dei Pontili?', 'Che cosa consigli di abbinare alla Birra Chiara dei Pontili?', 28153),
(161056, 'itIT', 'Che cosa consigli di abbinare alla Birra Scura dell\'Ancora Gettata?', 'Che cosa consigli di abbinare alla Birra Scura dell\'Ancora Gettata?', 28153),
(161055, 'itIT', 'Che cosa consigli di abbinare alla Birra al Sinforicarpo?', 'Che cosa consigli di abbinare alla Birra al Sinforicarpo?', 28153),
(161054, 'itIT', 'Che cosa consigli di abbinare alla Birra di Ventosaldo?', 'Che cosa consigli di abbinare alla Birra di Ventosaldo?', 28153),
(161053, 'itIT', 'Li altri Loa, all\'inizio, si arrabbiarono. Sputarono su di lui, lo chiamarono frivolo, debole, perché era disposto ad accettare meno del dovuto.', 'Li altri Loa, all\'inizio, si arrabbiarono. Sputarono su di lui, lo chiamarono frivolo, debole, perché era disposto ad accettare meno del dovuto.', 28153),
(161052, 'itIT', 'Egli ha detto ai seguaci suoi: \"Scegliete il sentiero che è giusto per voi, siamo tutti membri dello stesso branco alli occhi miei\".', 'Egli ha detto ai seguaci suoi: \"Scegliete il sentiero che è giusto per voi, siamo tutti membri dello stesso branco alli occhi miei\".', 28153),
(161051, 'itIT', 'Sei in cerca di cibo delizioso da abbinare alla tua birra?\n\nCredo di avere quello che fa al caso tuo.', '', 28153),
(161050, 'itIT', 'Il Loa Mutaforma ha osservato il popolo suo e ha visto che aveva molti bisogni. Esigenze che nun riusciva a soddisfare.', 'Il Loa Mutaforma ha osservato il popolo suo e ha visto che aveva molti bisogni. Esigenze che nun riusciva a soddisfare.', 28153),
(161049, 'itIT', 'Pensateci, fratelli e sorelle, e scegliete con saggezza.', 'Pensateci, fratelli e sorelle, e scegliete con saggezza.', 28153),
(161048, 'itIT', 'O vi ritroverete tra mille tormenti finché il sole nun si oscurerà nel cielo?', 'O vi ritroverete tra mille tormenti finché il sole nun si oscurerà nel cielo?', 28153),
(161047, 'itIT', 'Condividerete le risate sue? Ballerete con li altri morti a lui riconoscenti?', 'Condividerete le risate sue? Ballerete con li altri morti a lui riconoscenti?', 28153),
(161046, 'itIT', 'Quando verrà il momento e lo spirito vostro si ritroverà nell\'Aldilà, Bwonsamdi sarà per voi n\'amico?', 'Quando verrà il momento e lo spirito vostro si ritroverà nell\'Aldilà, Bwonsamdi sarà per voi n\'amico?', 28153),
(161045, 'itIT', 'Ma io sto accà per ricordarvi na cosa. Bwonsamdi osserva anche il mondo della vita. Lo studia. Lo misura.', 'Ma io sto accà per ricordarvi na cosa. Bwonsamdi osserva anche il mondo della vita. Lo studia. Lo misura.', 28153),
(161044, 'itIT', 'Ma io sono $gvivo:viva;, starete pensando, quindi chesto Loa nun tiene posto sull\'altare mio. Nun ancora.', 'Ma io sono $gvivo:viva;, starete pensando, quindi chesto Loa nun tiene posto sull\'altare mio. Nun ancora.', 28153),
(161043, 'itIT', 'Krag\'wa è ritornato e chesti sono gli insegnamenti che egli dona alli Zandalari.', 'Krag\'wa è ritornato e chesti sono gli insegnamenti che egli dona alli Zandalari.', 28153),
(161042, 'itIT', 'Per chelli di voi che stanno cercando il coraggio, il potere per proteggere li altri, la forza di volontà per andare avanti: nun cercate oltre.', 'Per chelli di voi che stanno cercando il coraggio, il potere per proteggere li altri, la forza di volontà per andare avanti: nun cercate oltre.', 28153),
(161041, 'itIT', 'Pigliate l\'esempio suo, fratelli e sorelle. La determinazione volta a proteggere ciò che è vostro è nu potere grandioso.', 'Pigliate l\'esempio suo, fratelli e sorelle. La determinazione volta a proteggere ciò che è vostro è nu potere grandioso.', 28153),
(161040, 'itIT', 'Egli ha dimostrato che anche di fronte alla minaccia del nulla, può ancora difendere la gente sua.', 'Egli ha dimostrato che anche di fronte alla minaccia del nulla, può ancora difendere la gente sua.', 28153),
(161039, 'itIT', 'Ora sto accà di fronte a voi per dirvi che il Grande Guardiano è tornato, la forza sua inalterata.', 'Ora sto accà di fronte a voi per dirvi che il Grande Guardiano è tornato, la forza sua inalterata.', 28153),
(161038, 'itIT', 'Apprezzo sempre una bella battaglia con un nuovo sfidante.', '', 28153),
(161037, 'itIT', 'Devo recuperare altre bende per mascotte.', '', 28153),
(161036, 'itIT', 'Hai combattuto bene, piccoletto. Ti rimetterai in sesto!', '', 28153),
(161035, 'itIT', 'Dannazione, odio perdere. Bello scontro.', '', 28153),
(161034, 'itIT', 'Poi, quando arriverà na nuova tempesta, saprete che è la possibilità vostra di ricominciare. Nun temerete più le nuvole all\'orizzonte.', 'Poi, quando arriverà na nuova tempesta, saprete che è la possibilità vostra di ricominciare. Nun temerete più le nuvole all\'orizzonte.', 28153),
(161033, 'itIT', 'Ho vinto? Eccellente, lo dirò a tutti i miei amici!', '', 28153),
(161032, 'itIT', 'È ora di lanciarsi in una bella avventura!', '', 28153),
(161031, 'itIT', 'Cheste sfide atmosferiche mettono alla prova la forza nostra, la determinazione nostra. Chelli che sono ancora in piedi dopo il passaggio delle nuvole, sono i più forti.', 'Cheste sfide atmosferiche mettono alla prova la forza nostra, la determinazione nostra. Chelli che sono ancora in piedi dopo il passaggio delle nuvole, sono i più forti.', 28153),
(161030, 'itIT', 'Quella mascotte era comunque un po\' inquietante, non è una grande perdita.', '', 28153),
(161029, 'itIT', 'Sì, ci sta la furia nel lampo, ci sta la rabbia nel tuono. Ma l\'inizio di qualsiasi cambiamento nun è mai facile.', 'Sì, ci sta la furia nel lampo, ci sta la rabbia nel tuono. Ma l\'inizio di qualsiasi cambiamento nun è mai facile.', 28153),
(161028, 'itIT', 'I venti ripuliranno la terra e faranno spazio alla crescita di cose nuove.', 'I venti ripuliranno la terra e faranno spazio alla crescita di cose nuove.', 28153),
(161027, 'itIT', 'Sarà meglio che te ne occupi, prima che diventi un componente per un qualche rituale del sangue.', '', 28153),
(161026, 'itIT', 'Akunda ci insegna a nun temere la tempesta all\'orizzonte, poiché le piogge sue spazzano via i rimpianti del passato.', 'Akunda ci insegna a nun temere la tempesta all\'orizzonte, poiché le piogge sue spazzano via i rimpianti del passato.', 28153),
(161025, 'itIT', 'Questo posto è maledetto. Non perdo mai così malamente.', '', 28153),
(161024, 'itIT', 'È stato un bel combattimento, ma non avevi speranze contro di me.', '', 28153),
(161023, 'itIT', 'Questo posto è inquietante, vediamo di fare in fretta.', '', 28153),
(161022, 'itIT', 'Mostro! Quella era la mia mascotte preferita.', '', 28153),
(161021, 'itIT', 'Mangia la polvere.', '', 28153),
(161020, 'itIT', 'Fa\' un fischio se vuoi un bicchiere!\n\nSe invece hai bisogno di un volo, chiedi a qualcun altro.', '', 28153),
(161019, 'itIT', '', 'Certo! Ecco qua.', 28153),
(161018, 'itIT', 'Odio perdere! Sarò più forte la prossima volta, ci puoi contare.', '', 28153),
(161017, 'itIT', 'Hai un altro secchio di latte a portata di mano?', 'Hai un altro secchio di latte a portata di mano?', 28153),
(161016, 'itIT', 'Un\'altra vittoria per la squadra migliore, io!', '', 28153),
(161015, 'itIT', 'È ora di lanciarci in battaglia! Carica!', '', 28153),
(161014, 'itIT', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t Dal cielo cade una |cFFFF0000|Hspell:269688|h[Pioggia di Rospi]|h|r!', '|TInterface\\Icons\\INV_PET_TOAD_BROWN.BLP:20|t Dal cielo cade una |cFFFF0000|Hspell:269688|h[Pioggia di Rospi]|h|r!', 28153),
(161013, 'itIT', '', 'Sei proprio $gun tipo carino:una tipa carina;.', 28153),
(161012, 'itIT', '', 'Se dovessi avere mai bisogno di qualcosa da me, non esitare a chiedere!', 28153),
(161011, 'itIT', '', 'Quando una cade in combattimento, le altre si fanno ancora più forti!', 28153),
(161010, 'itIT', '', 'Non so come ringraziarti per aver salvato Millie.', 28153),
(161009, 'itIT', '', 'Salve, $p. È sempre bello vederti.', 28153),
(161008, 'itIT', '', 'Ahah! Preso!', 28153),
(161007, 'itIT', '', 'Mi allenerò e la prossima volta che ci incontreremo sarò pronta.', 28153),
(161006, 'itIT', '', 'Non temere la sconfitta, impara dai tuoi errori e affronta le difficoltà.', 28153),
(161005, 'itIT', '', 'È quasi ora della transumanza. C\'è bisogno di braccia forti qui!', 28153),
(161004, 'itIT', '', 'Combattiamo con onore, $gstraniero:straniera;.', 28153),
(161003, 'itIT', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t Un frammento di energia si è formato nelle vicinanze, usalo per donare |cFFFF0000|Hspell:274149|h[Forza Vitale]|h|r all\'Avatar!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t Un frammento di energia si è formato nelle vicinanze, usalo per donare |cFFFF0000|Hspell:274149|h[Forza Vitale]|h|r all\'Avatar!', 28153),
(161002, 'itIT', '<Concedi a Genn un momento per parlare con Katherine.>', '<Concedi a Genn un momento per parlare con Katherine.>', 28153),
(161001, 'itIT', 'È la nostra occasione!', 'È la nostra occasione!', 28153),
(161000, 'itIT', 'Prendi le tue cose, presto!', 'Prendi le tue cose, presto!', 28153),
(160999, 'itIT', 'Andiamo!', 'Andiamo!', 28153),
(160998, 'itIT', 'Avanti, usciamo da qui!', 'Avanti, usciamo da qui!', 28153),
(160997, 'itIT', 'Un guardiano si forma nelle vicinanze per proteggere il Cuore di Sethraliss.', 'Un guardiano si forma nelle vicinanze per proteggere il Cuore di Sethraliss.', 28153),
(160996, 'itIT', 'I seguaci di Jakra\'zet assaltano il Cuore di Sethraliss.', 'I seguaci di Jakra\'zet caricano il Cuore di Sethraliss.', 28153),
(160995, 'itIT', 'Là fuori nella natura è pieno di orsi, lupi e capre assassine!', '', 28153),
(160994, 'itIT', 'Sei un bel tipo, ma rispetto la tua volontà di mantenere le distanze.', '', 28153),
(160993, 'itIT', 'Non voglio fare del male agli animali, serve solo per allontanarli.', '', 28153),
(160992, 'itIT', 'Ma bisogna fare anche attenzione, per questo mi porto sempre dietro un po\' di fuoco.', '', 28153),
(160991, 'itIT', 'Piccola curiosità: passeggiare nella natura è una delle cose più belle che ci siano.', '', 28153),
(160990, 'itIT', 'Questo è un pino. Si può capire che si tratta di un pino dal suo aspetto!', '', 28153),
(160989, 'itIT', 'Vuoi sapere una curiosità sulle cascate? Si chiamano così perché l\'acqua casca!', '', 28153),
(160988, 'itIT', 'Le cascate sono maestosamente... maestose.', '', 28153),
(160987, 'itIT', 'Quella che abbiamo qui si chiama cascata.', '', 28153),
(160986, 'itIT', 'Non è una vista magnifica?', '', 28153),
(160985, 'itIT', 'Che bellezza!', '', 28153),
(160984, 'itIT', 'È così che il Signore delle Bestie ha instillato il coraggio e la determinazione nei seguaci suoi.', 'È così che il Signore delle Bestie ha instillato il coraggio e la determinazione nei seguaci suoi.', 28153),
(160983, 'itIT', 'La vera fonte del potere nun sta nella forza, ma nell\'indomabile volontà che l\'età nun può distruggere.', 'La vera fonte del potere nun sta nella forza, ma nell\'indomabile volontà che l\'età nun può distruggere.', 28153),
(160982, 'itIT', 'Proprio come la decomposizione divora i germogli della giungla, anche l\'età divora la forza della giovinezza.', 'Proprio come la decomposizione divora i germogli della giungla, anche l\'età divora la forza della giovinezza.', 28153),
(160981, 'itIT', 'Agisci con coraggio in ogni situazione e nun perderai mai di vista la preda tua.', 'Agisci con coraggio in ogni situazione e nun perderai mai di vista la preda tua.', 28153),
(160980, 'itIT', 'Come la tigre balza tra rocce e ostacoli durante na caccia, anche i più coraggiosi nun devono sprecare tempo di fronte al volto della paura.', 'Come la tigre balza tra rocce e ostacoli durante na caccia, anche i più coraggiosi nun devono sprecare tempo di fronte al volto della paura.', 28153),
(160979, 'itIT', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 28153),
(160978, 'itIT', 'È così che il Re dei Felini ha instillato la virtù della devozione nei seguaci suoi.', 'È così che il Re dei Felini ha instillato la virtù della devozione nei seguaci suoi.', 28153),
(160977, 'itIT', 'Vivi con na determinazione incrollabile e il fallimento nun ti sconfiggerà mai.', 'Vivi con na determinazione incrollabile e il fallimento nun ti sconfiggerà mai.', 28153),
(160976, 'itIT', 'Come i canyon sono plasmati dal costante scorrere dell\'acqua, anche le gesta più grandi nascono dalla perseveranza.', 'Come i canyon sono plasmati dal costante scorrere dell\'acqua, anche le gesta più grandi nascono dalla perseveranza.', 28153),
(160975, 'itIT', 'Vivi na vita onorevole e sarà na vita degna di essere vissuta.', 'Vivi na vita onorevole e sarà na vita degna di essere vissuta.', 28153),
(160974, 'itIT', 'Come nu sovrano nun può barattare il più grande tesoro suo per na semplice manciata di terra, anche i più onorevoli nun possono barattare l\'integrità loro per ricchezze o fama.', 'Come nu sovrano nun può barattare il più grande tesoro suo per na semplice manciata di terra, anche i più onorevoli nun possono barattare l\'integrità loro per ricchezze o fama.', 28153),
(160973, 'itIT', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 28153),
(160972, 'itIT', 'È così che il Flagello delle Prede ha instillato la pazienza e il rispetto nei seguaci suoi.', 'È così che il Flagello delle Prede ha instillato la pazienza e il rispetto nei seguaci suoi.', 28153),
(160971, 'itIT', 'Coloro che rispettano l\'ordine naturale delle cose, prendono solo lo stretto necessario per vivere.', 'Coloro che rispettano l\'ordine naturale delle cose, prendono solo lo stretto necessario per vivere.', 28153),
(160970, 'itIT', 'I più saggi sanno di nun possedere la natura, ma di essere al servizio suo.', 'I più saggi sanno di nun possedere la natura, ma di essere al servizio suo.', 28153),
(160969, 'itIT', 'Proprio come la giungla sa concedere il dono della vita, lo stesso vale per il tocco della morte.', 'Proprio come la giungla sa concedere il dono della vita, lo stesso vale per il tocco della morte.', 28153),
(160968, 'itIT', 'Gli stolti sono trascinati dalla bramosia e dalle emozioni, ma nun sopravvivrebbero a lungo nella giungla.', 'Gli stolti sono trascinati dalla bramosia e dalle emozioni, ma nun sopravvivrebbero a lungo nella giungla.', 28153),
(160967, 'itIT', 'Come il giaguaro insegue la preda sua per giorni e giorni, anche il più saggio agisce con pazienza in ogni situazione.', 'Come il giaguaro insegue la preda sua per giorni e giorni, anche il più saggio agisce con pazienza in ogni situazione.', 28153),
(160966, 'itIT', 'Nun solo sopravvivere, ma prosperare! Io vi dico... Andate! Vivete nello sporco e tenete la testa alta. Chesto è il dominio di Jani.', 'Nun solo sopravvivere, ma prosperare! Io vi dico... Andate! Vivete nello sporco e tenete alta la capa. Poiché chesto è il dominio di Jani.', 28153),
(160965, 'itIT', 'Jani nun pretende preghiere stravaganti o grandi sacrifici. Per lodare Jani basta sopravvivere sotto il naso di chelli che vorrebbero sopprimere chi nun desiderano.', 'Jani nun pretende preghiere stravaganti o grandi sacrifici. Per lodare Jani basta sopravvivere sotto il naso di chelli che vorrebbero sopprimere chi nun desiderano.', 28153),
(160964, 'itIT', 'Dove li altri pigliano, Jani dà! Egli elargisce i doni suoi a tutti chelli che stanno aiutando se stessi. Chelli che i più grandi, i più ricchi, scartano.', 'Dove li altri pigliano, Jani dà! Egli elargisce i doni suoi a tutti chelli che stanno aiutando se stessi. Chelli che i più grandi, i più ricchi, scartano.', 28153),
(160963, 'itIT', 'Ma Jani è più forte di tutti li altri e vi rivelerò perché!', 'Ma Jani è più forte di tutti li altri e vi rivelerò perché!', 28153),
(160962, 'itIT', 'Alzeranno le mani loro, bramosi del favore della folla.', 'Alzeranno le mani loro, bramosi del favore della folla.', 28153),
(160961, 'itIT', 'Thros... divora...', '', 28153),
(160960, 'itIT', 'Non... c\'è... scampo...', '', 28153),
(160959, 'itIT', 'Ogni... Speranza... è perduta...', '', 28153),
(160958, 'itIT', 'Scorticateli!', '', 28153),
(160957, 'itIT', 'Soffri in agonia!', '', 28153),
(160956, 'itIT', 'Sputo sul vostro Loa da riccumpà!', 'Sputo sul vostro Loa da riccumpà!', 28153),
(160955, 'itIT', 'Soffri!', '', 28153),
(160954, 'itIT', 'Disperdetevi!', 'Disperdetevi!', 28153),
(160953, 'itIT', 'Jani è il Loa giusto per me! Ahahah!', 'Jani è il Loa giusto per me! Ahahah!', 28153),
(160952, 'itIT', 'Jani renderà ricchi tutti quanti!', 'Jani renderà ricchi tutti quanti!', 28153),
(160951, 'itIT', 'Basta con cheste sciocchezze. Via!', 'Basta con cheste sciocchezze. Via!', 28153),
(160950, 'itIT', 'Ci state pigliando in giro con cheste manifestazioni! Andatevene!', 'Ci state pigliando in giro con cheste manifestazioni! Andatevene!', 28153),
(160949, 'itIT', 'State mancando di rispetto all\'unico vero Loa! Portata via chesta monnezza!', 'State mancando di rispetto all\'unico vero Loa! Portata via chesta monnezza!', 28153),
(160948, 'itIT', 'Quando ci sta Jani, ci sta sempre casino! Sciò! Sciò!', 'Quando ci sta Jani, ci sta sempre casino! Sciò! Sciò!', 28153),
(160947, 'itIT', 'Chesto nun va bene. Piglia il dono del Loa mio!', 'Chesto nun va bene. Piglia il dono del Loa mio!', 28153),
(160946, 'itIT', 'Forse sono arrivato tardi...', 'Forse sono arrivata tardi...', 28153),
(160945, 'itIT', 'Tanta devozione mi commuove. Hai visto quanto è grande la generosità dei Loa?', 'Tanta devozione mi commuove. Hai visto quanto è grande la generosità dei Loa?', 28153),
(160944, 'itIT', 'Il rituale inizierà presto, $n.\n\nLa gente nostra, appartenente a qualsiasi ceto sociale, viene da ogni angolo di Zandalar per ascoltare la saggezza dei Loa. Molti vengono nella speranza che i Loa concedano loro nu dono, na benedizione. Forse ne concederanno una anche a te!\n\nResta, rendi lode ai Loa delli Zandalari con noi.', 'Il rituale inizierà presto, $n.\n\nLa gente nostra, appartenente a qualsiasi ceto sociale, viene da ogni angolo di Zandalar per ascoltare la saggezza dei Loa. Molti vengono nella speranza che i Loa concedano loro nu dono, na benedizione. Forse ne concederanno una anche a te!\n\nResta, rendi lode ai Loa delli Zandalari con noi.', 28153),
(160943, 'itIT', 'Desidererai... la morte...', '', 28153),
(160942, 'itIT', 'Le tue urla saranno eterne!', '', 28153),
(160941, 'itIT', 'Non... Potete... impedire... la nostra... vendetta...', '', 28153),
(160940, 'itIT', 'Lei appartiene a Gorak Tul!', '', 28153),
(160939, 'itIT', 'Non riuscirai a fermarci!', '', 28153),
(160938, 'itIT', 'Eri al mio fianco a Sepulcra. Li avevamo messi all\'angolo! La giustizia era a portata di mano!', '', 28153),
(160937, 'itIT', 'Ehi, $gfratello:sorella;, sembra che tu abbia bisogno di bere qualcosa. Vuoi una birra?', '', 28153),
(160936, 'itIT', 'Ho appena iniziato a creare una nuova birra con il miglior miele di Sacraonda.\n\nAbbiamo pagato qualche moneta di bronzo di troppo per averlo, ma credo che ne varrà la pena!', '', 28153),
(160935, 'itIT', '', 'Ti interessa una pinta? Ho anche fatto un po\' di caffè, se ne dovessi aver bisogno!', 28153),
(160934, 'itIT', 'Sarò nu riccumpà! Sììì!', 'Sarò na riccumpà! Sììì!', 28153),
(160933, 'itIT', 'Il Loa vostro nun è il benvenuto accà. Andatevene!', 'Il Loa vostro nun è il benvenuto accà. Andatevene!', 28153),
(160932, 'itIT', 'Il Dio dei Rifiuti vi offre il dono suo! Ahahah!', 'Il Dio dei Rifiuti vi offre il dono suo! Ahahah!', 28153),
(160931, 'itIT', 'Li altri vi diranno che il Loa loro è il più generoso, il più forte o il più veloce ad arrabbiarsi.', 'Li altri vi diranno che il Loa loro è il più generoso, il più forte o il più veloce ad arrabbiarsi.', 28153),
(160930, 'itIT', 'Ahahah! È tempo di lodare il Loa di tutti! Venite sulle scalinate di Dazar\'alor per celebrare Jani!', 'Ahahah! È tempo di lodare il Loa di tutti! Venite sulle scalinate di Dazar\'alor per celebrare Jani!', 28153),
(160929, 'itIT', 'Se sta in orario, la nave dovrebbe essere già partita dalle Isole dell\'Eco e arriverà presto.', '', 28153),
(160928, 'itIT', 'Gente di Zandalar! È tempo di lodare la Signora dei Venti, la Regina dei Cieli, la Matrona dei Mari! Venite sulle scalinate a rendere lode a Pa\'ku!', 'Gente di Zandalar! È tempo di lodare la Signora dei Venti, la Regina dei Cieli, la Matrona dei Mari! Venite sulle scalinate a rendere lode a Pa\'ku!', 28153),
(160927, 'itIT', 'Tutti voi che state accà di fronte a me avete sentito la benedizione di Pa\'ku, la Loa mia.', 'Tutti voi che state accà di fronte a me avete sentito la benedizione di Pa\'ku, la Loa mia.', 28153),
(160926, 'itIT', 'Sia lode a Pa\'ku! Che i venti suoi gonfino sempre le vele vostre!', 'Sia lode a Pa\'ku! Che i venti suoi gonfino sempre le vele vostre!', 28153),
(160925, 'itIT', 'Gonk ci omaggia del dono suo! Che il branco sia sempre con voi!', 'Gonk ci omaggia del dono suo! Che il branco sia sempre con voi!', 28153),
(160924, 'itIT', 'Siate i benvenuti, fratelli e sorelle, e sappiate che lo spirito di Gonk è con noi oggi.', 'Siate i benvenuti, fratelli e sorelle, e sappiate che lo spirito di Gonk è con noi oggi.', 28153),
(160923, 'itIT', 'Gente di Zandalar! Il Loa Mutaforma reclama le lodi del popolo suo. Venite, alziamo le nostre voci per il Signore del Branco, il più generoso dei Loa! Sia lode a Gonk!', 'Gente di Zandalar! Il Loa Mutaforma reclama le lodi del popolo suo. Venite, alziamo le nostre voci per il Signore del Branco, il più generoso dei Loa! Sia lode a Gonk!', 28153),
(160922, 'itIT', 'Miei cari Zandalari! Il potente Krag\'wa è tornato! Venite sulle scalinate di Dazar\'alor per rendere omaggio al Grande Guardiano!', 'Miei cari Zandalari! Il potente Krag\'wa è tornato! Venite sulle scalinate di Dazar\'alor per rendere omaggio al Grande Guardiano!', 28153),
(160921, 'itIT', 'Molti mi hanno detto: Krag\'wa? Il Grande Rospo? Nun è nu Loa, è na leggenda! Nun esiste!', 'Molti mi hanno detto: Krag\'wa? Il Grande Rospo? Nun è nu Loa, è na leggenda! Nun esiste!', 28153),
(160920, 'itIT', 'Il Grande Guardiano ci offre la protezione sua! Sia lode a Krag\'wa!', 'Il Grande Guardiano ci offre la protezione sua! Sia lode a Krag\'wa!', 28153),
(160919, 'itIT', 'Bwonsamdi osserva tutti noi. Siate degni del suo dono, fratelli e sorelle!', 'Bwonsamdi osserva tutti noi. Siate degni del suo dono, fratelli e sorelle!', 28153),
(160918, 'itIT', 'Sono sicuro che penserete di sapere tutto su Bwonsamdi. Penserete che sia solo il Loa della Morte.', 'Sono sicura che penserete di sapere tutto su Bwonsamdi. Penserete che sia solo il Loa della Morte.', 28153),
(160917, 'itIT', 'Che li spiriti siano con noi! Venite sulle scalinate di Dazar\'alor per lodare chi si occupa dei morti nostri. Gloria a Bwonsamdi!', 'Che li spiriti siano con noi! Venite sulle scalinate di Dazar\'alor per lodare chi si occupa dei morti nostri. Gloria a Bwonsamdi!', 28153),
(160916, 'itIT', 'La nave sta alle Isole dell\'Eco. Presto farà di nuovo rotta verso chesto porto.', '', 28153),
(160915, 'itIT', '', 'Ignora la lavagna. È ancora tutto temporaneo.', 28153),
(160914, 'itIT', 'L\'hai appena persa. Sta in rotta verso le Isole dell\'Eco, ma tornerà presto.', '', 28153),
(160913, 'itIT', 'Miei cari Zandalari! Venite sulle scalinate di Dazar\'alor per ascoltare la saggezza del Re dei Felini, il Flagello delle Prede, il Signore delle Bestie. Sia lode a Kimbul!', 'Miei cari Zandalari! Venite sulle scalinate di Dazar\'alor per ascoltare la saggezza del Re dei Felini, il Flagello delle Prede, il Signore delle Bestie. Sia lode a Kimbul!', 28153),
(160912, 'itIT', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 'Vi confido le parole del Loa mio. Egli parla così ai seguaci suoi.', 28153),
(160911, 'itIT', 'Che il Flagello delle Prede benedica la caccia vostra! Mo\' andate!', 'Che il Flagello delle Prede benedica la caccia vostra! Mo\' andate!', 28153),
(160910, 'itIT', 'Bagnatevi nella benedizione di Akunda!', 'Bagnatevi nella benedizione di Akunda!', 28153),
(160909, 'itIT', 'Condividerò con voi la saggezza di Akunda. Egli è il Loa delle Tempeste, dei nuovi inizi.', 'Condividerò con voi la saggezza di Akunda. Egli è il Loa delle Tempeste, dei nuovi inizi.', 28153),
(160908, 'itIT', 'Si avvicina na tempesta! Che la pioggia lavi via le preoccupazioni vostre, fratelli e sorelle. Venite sulle scalinate di Dazar\'alor a lodare Akunda!', 'Si avvicina na tempesta! Che la pioggia lavi via le preoccupazioni vostre, fratelli e sorelle. Venite sulle scalinate di Dazar\'alor a lodare Akunda!', 28153),
(160907, 'itIT', 'Sta già accà, cumpà. Sali a bordo, prima che salpi.', '', 28153),
(160906, 'itIT', '$gUn vero:Una vera; fan! Che gioia! Chissà che onore per te incontrarmi. Non temere, sono solo un normale avventuriero, proprio come te, tranne per il fatto che sono un ricchissimo autore vincitore di numerosi premi, con fan da tutto il mondo che attraverserebbero oceani per incontrarmi.\n\nEcco il tuo libro. Sono sicuro che lo apprezzerai.', '', 28153),
(160905, 'itIT', 'Altro giorno, altra birra! Hai già provato qualcosa di veramente delizioso?', '', 28153),
(160904, 'itIT', 'Sei un Cavaliere della Morte? Ho sempre voluto conoscerne uno! Com\'è la non morte? Tu volevi diventare un Cavaliere della Morte? Io voglio diventarlo. Dove devo firmare?', '', 28153),
(160903, 'itIT', 'Mi autograferesti il libro?', 'Mi autograferesti il libro?', 28153),
(160902, 'itIT', 'La mia ultima fatica è davvero un capolavoro. Un vero gioiello degli abissi, creato per affascinare e sedurre il lettore. Sei qui per congratularti con me?', '', 28153),
(160901, 'itIT', 'A dir la verità, nun ne sono sicuro al momento. Speriamo che l\'Alleanza nun l\'abbia attaccata.', '', 28153),
(160900, 'itIT', 'Non riusciremo a tenere a bada Mythrax a lungo. Uccidi Zul prima che sia troppo tardi.', '', 28153),
(160899, 'itIT', 'Mi hai salvato! Grazie mille! Ho una ricompensa per te, da qualche parte in questa borsa.', '', 28153),
(160898, 'itIT', 'Occupati della tua città, $geroe:eroina;. Io difenderò la strada settentrionale da questi infami Sethrak.', '', 28153),
(160897, 'itIT', '', 'Nun credevo che avrei mai visto le strade di Zuldazar invase da nu qualsiasi nemico...', 28153),
(160896, 'itIT', '', 'Dove stanno le difese? Zuldazar è rimasta così indebolita dal tradimento di Zul che nun è nemmeno in grado di difendersi da sola?\n\nHo chiesto a Meerah di venire accà in fretta per avvisare le guardie reali, ma ne sono rimaste troppo poche. Toccherà a noi difendere chel poco che rimane.', 28153),
(160895, 'itIT', '', 'Non crederesti mai alla strada che abbiamo dovuto prendere per venire qui prima dei Sethrak. Se non avessi aiutato i tuoi amici, non sarebbero mai riusciti a raggiungere quelle montagne in tempo.\n\nOh, e abbiamo portato anche Akunda e Kimbul. Akunda ci sta coprendo le spalle, ma non so dove sia finito Kimbul. Ha detto una cosa come \"squartare il nemico\" o qualcosa del genere.\n\nQuello che so è che abbiamo visto UN SACCO di Sethrak diretti da questa parte. UN SACCO!', 28153),
(160894, 'itIT', 'Puoi parlarci dei movimenti dell\'Orda nell\'area?', 'Puoi parlarci dei movimenti dell\'Orda nell\'area?', 28153),
(160893, 'itIT', 'Credevo di essere spacciato. Hai i miei ringraziamenti, $R. Vi chiamate ancora così, vero?', 'Credevo di essere spacciata. Hai i miei ringraziamenti, $R. Vi chiamate ancora così, vero?', 28153),
(160892, 'itIT', '', 'Ehi, ma quanto sei $galto:alta;?', 28153),
(160891, 'itIT', 'Fammi vedere la lista delle birre.', 'Fammi vedere la lista delle birre.', 28153),
(160890, 'itIT', '', 'Ti va di provare una birra? Ne abbiamo per tutti i gusti!', 28153),
(160889, 'itIT', 'Ti sei $gsbarazzato:sbarazzata; in fretta di loro. Sai, magari potrei fornire alle tue truppe delle nuove magnifiche armature. Offre la casa!', '', 28153),
(160888, 'itIT', '', 'Usare Tiro Lacerante ridurrà anche il tempo di recupero di Ira Bestiale.', 28153),
(160887, 'itIT', 'Sto lavorando il più in fretta possibile!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160886, 'itIT', '', 'Taglia più in fretta, Colton! Abbiamo dei clienti da sfamare!', 28153),
(160885, 'itIT', 'Usare Tiro Lacerante ridurrà anche il tempo di recupero di Ira Bestiale.', '', 28153),
(160884, 'itIT', 'Andiamo, ragazza!', '', 28153),
(160883, 'itIT', 'Sei pronta?', '', 28153),
(160882, 'itIT', 'È ora di giocare, Luna?', '', 28153),
(160881, 'itIT', 'Ho avuto fortuna a trovare una moglie così brillante.', '', 28153),
(160880, 'itIT', '', 'Ho una sorpresa per te!', 28153),
(160879, 'itIT', '', 'Affascinante, lo hai visto?', 28153),
(160878, 'itIT', 'Oh, non so, forse cercherò una brava ragazza e mi sistemerò in una piccola fattoria da qualche parte...\n\nCosa pensi che voglia fare?!?\n\nMi riprenderò il denaro da Cyrus, pagherò un giro a tutti a Porto Piccolo e partirò per la prossima avventura.\n\nQuesto è l\'unico modo di vivere la vita, $gamico mio:amica mia;.', '', 28153),
(160877, 'itIT', 'Che cosa farai ora?', 'Che cosa farai ora?', 28153),
(160876, 'itIT', 'Invasioni, colpi di stato, la rinascita degli Dei Antichi... Bah! Non lascerò questo Zocalo fin quando il Vecchio Tella salderà i suoi debiti.', '', 28153),
(160875, 'itIT', 'Chesto nun è nulla. Durante la Terza Guerra, ho assistito alla grande danza delle ossa di Radivia. È stata la cosa più divertente che abbia mai visto.', '', 28153),
(160874, 'itIT', 'Lo giuro, se sopravvivo a tutto chesto, prometto di nun fregare più neanche nu cliente per almeno due... facciamo tre settimane.', '', 28153),
(160873, 'itIT', 'Dov\'è la nave, ora?', 'Dov\'è la nave, ora?', 28153),
(160872, 'itIT', '', 'Manderò tutto il possibile per aiutarti, $n.', 28153),
(160871, 'itIT', '', 'Affrontai il Flagello quando decise di invadere Zul\'drak, ma chest\'attacco alla terra mia da coloro che credevamo amici...\n\nBe\', di solito nun sono na Troll violenta, ma in chesto caso sento davvero il bisogno di accidere qualcuno.', 28153),
(160870, 'itIT', 'Arcidruido, Malfurion ha richiesto il tuo aiuto a Rivafosca!', 'Arcidruido, Malfurion ha richiesto il tuo aiuto a Rivafosca!', 28153),
(160869, 'itIT', 'Sacerdotessa, abbiamo bisogno del tuo aiuto per tenere a bada l\'Orda al Fiume Lettocurvo.', 'Sacerdotessa, abbiamo bisogno del tuo aiuto per tenere a bada l\'Orda al Fiume Lettocurvo.', 28153),
(160868, 'itIT', 'Stai aiutando la Principessa. Molto bene, continua così. Elimina i Troll del Sangue, prima che ci consumino tutti quanti.\n\nLa persona che stai cercando si trova alle Rovine di Zul\'jan. Il nome suo è Approvvigionatrice Lija. Lei ti aiuterà a trovare ciò che cerchi.', 'Stai aiutando la Principessa. Molto bene, continua così. Elimina i Troll del Sangue, prima che ci consumino tutti quanti.\n\nLa persona che stai cercando si trova alle Rovine di Zul\'jan. Il nome suo è Approvvigionatrice Lija. Lei ti aiuterà a trovare ciò che cerchi.', 28153),
(160867, 'itIT', 'È nei migliori interessi della Capoguerra fare il possibile per assicurare che gli Zandalari e la loro flotta si uniscano all\'Orda. A tal fine, dobbiamo continuare ad aiutare Talanji. Se ciò significa distruggere fino all\'ultimo Troll del Sangue, allora così sia.\n\nTroverai la sua emissaria a Nazmir, nelle Rovine di Zul\'jan. Il suo nome è Approvvigionatrice Lija. La Dama Oscura veglia su di te.', 'È nei migliori interessi della Capoguerra fare il possibile per assicurare che gli Zandalari e la loro flotta si uniscano all\'Orda. A tal fine, dobbiamo continuare ad aiutare Talanji. Se ciò significa distruggere fino all\'ultimo Troll del Sangue, allora così sia.\n\nTroverai la sua emissaria a Nazmir, nelle Rovine di Zul\'jan. Il suo nome è Approvvigionatrice Lija. La Dama Oscura veglia su di te.', 28153),
(160866, 'itIT', 'Emissaria della Spedizione di Talanji', 'Emissaria della Spedizione di Talanji', 28153),
(160865, 'itIT', 'Questi Kul Tirani hanno della birra interessante!\n\nHa un sapore molto più deciso della nostra. Bisogna ammettere che si impegnano molto in fatto di birra!', '', 28153),
(160864, 'itIT', 'Raggiungi la Principessa Talanji e la Guardia da Guerra Rakera.', 'Raggiungi la Principessa Talanji e la Guardia da Guerra Rakera.', 28153),
(160863, 'itIT', '', 'Cultisti del sangue, Sethrak, Mogu e persino Zul? Mi mancano chei giorni in cui era tutto più semplice, quando stavamo solo cercando di conquistare il mondo.', 28153),
(160862, 'itIT', '', 'Anche se la nostra lunga guerra contro la Legione è finita, l\'Orda non può permettersi di abbassare la guardia.', 28153),
(160861, 'itIT', 'La Legione è caduta, ma una nuova minaccia si sta manifestando. Dai nostri agenti a Orgrimmar giungono messaggi preoccupanti. Ti aspetto al Forte di Roccavento per discutere la faccenda nei dettagli.', '', 28153),
(160860, 'itIT', '$gBenvenuto:Benvenuta; ad Acque Increspate! Sei in cerca di rifornimenti?', '', 28153),
(160859, 'itIT', '', 'Ho iniziato con tre gatti. Tre gatti! Insomma, sembrava una cosa sensata!\n\nPoi un amico ha dovuto trasferirsi e trovare una casa al suo gatto. Poi ne ho trovata una smarrita in un bosco, e quella ha fatto presto dei cuccioli. Poi è morto un vicino che aveva un gatto. Poi ne è arrivata un\'altra coppia per caso!\n\nLi adoro, tutti quanti. Non li darei via per nulla al mondo.', 28153),
(160858, 'itIT', 'Sì! Ancora!', '', 28153),
(160857, 'itIT', 'Nessuno di questi cuccioli è mio. Ho perso il mio dolce Willoughby molti anni fa. Vengo qui ogni giorno a cercare il più solo e lo accarezzo dicendogli che è un bravo cane.', '', 28153),
(160856, 'itIT', 'Farei qualunque cosa per il mio cane.', '', 28153),
(160855, 'itIT', 'Questo è il mio cane, si chiama Secchio. È molto bravo a fare buche nel terreno!\n\nL\'ho portato qui per coccolarlo un po\'. Mi sembra sia felice di essere qui.', '', 28153),
(160854, 'itIT', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Assicurati che almeno un giocatore si trovi in ogni area presa di mira da |cFFFF0000|Hspell:266948|h[Bomba Pestilenziale]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Assicurati che almeno un giocatore si trovi in ogni area presa di mira da |cFFFF0000|Hspell:266948|h[Bomba Pestilenziale]|h|r!', 28153),
(160853, 'itIT', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t Hai oltre 50 accumuli di |cFFFF0000|Hspell:272146|h[Annichilimento]|h|r! Usa i Frammenti d\'Essenza per recuperare la tua salute!', '|TInterface\\ICONS\\Spell_Priest_Void Blast.blp:20|t Hai oltre 50 accumuli di |cFFFF0000|Hspell:272146|h[Annichilimento]|h|r! Usa i Frammenti d\'Essenza per recuperare la tua salute!', 28153),
(160852, 'itIT', 'Ho sentito che ti serviva un aiuto con degli Ettin.', 'Ho sentito che ti serviva un aiuto con degli Ettin.', 28153),
(160851, 'itIT', 'Per l\'Alleanza!', '', 28153),
(160850, 'itIT', 'Mi assicurerò che Re Anduin venga a sapere delle vostre gesta eroiche di oggi. Avete fatto un lavoro fantastico, tutti quanti.', '', 28153),
(160849, 'itIT', 'E un piccolo riconoscimento al Gran Thane Falstad e all\'intero clan Granmartello.', '', 28153),
(160848, 'itIT', 'Stai assai $glontano:lontana; da casa, $R.$b$bChiederò alli spiriti di vegliare su di te mentre stai a Vol\'dun. Ti avviso, però: nun mi ascoltano più come na volta.', 'Stai assai $glontano:lontana; da casa, $R.$b$bChiederò alli spiriti di vegliare su di te mentre stai a Vol\'dun. Ti avviso, però: nun mi ascoltano più come na volta.', 28153),
(160847, 'itIT', 'Nun ci sta via di fuga da chesto caldo.', 'Nun ci sta via di fuga da chesto caldo.', 28153),
(160846, 'itIT', '$gCane maledetto:Cagna maledetta;! Avrò la tua testa!', '$gCane maledetto:Cagna maledetta;! Avrò la tua testa!', 28153),
(160845, 'itIT', 'Ancora tu? L\'ultima volta ho avuto pietà, un errore che non intendo ripetere!', 'Ancora tu? L\'ultima volta ho avuto pietà, un errore che non intendo ripetere!', 28153),
(160844, 'itIT', 'Grazie per avermi salvato. Sai che ti dico? Come ricompensa rifornirò la tua intera armata con le migliori armi delle Industrie Tarque. Alla pace! Salute.', '', 28153),
(160843, 'itIT', 'E io... che avevo paura... degli squali...', 'E io... che avevo paura... degli squali...', 28153),
(160842, 'itIT', 'Voglio una rivincita... a terra...', 'Voglio una rivincita... a terra...', 28153),
(160841, 'itIT', 'Per... l\'Orda...', 'Per... l\'Orda...', 28153),
(160840, 'itIT', 'Dove pensi... di scappare...?', 'Dove pensi... di scappare...?', 28153),
(160839, 'itIT', 'Non così...', 'Non così...', 28153),
(160838, 'itIT', 'Trascinami... alla barca...', 'Trascinami... alla barca...', 28153),
(160837, 'itIT', 'Lasciami... annegare...', 'Lasciami... annegare...', 28153),
(160836, 'itIT', 'Morire per... recuperare...', 'Morire per... recuperare...', 28153),
(160835, 'itIT', 'Non mi servono neanche i pantaloni per batterti!', 'Non mi servono neanche i pantaloni per batterti!', 28153),
(160834, 'itIT', 'Proprio come andare a pesca!', 'Proprio come andare a pesca!', 28153),
(160833, 'itIT', 'Questo lavoro inizia a farsi interessante!', 'Questo lavoro inizia a farsi interessante!', 28153),
(160832, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(160831, 'itIT', 'Non vale! Il mio equipaggiamento è nella barca!', 'Non vale! Il mio equipaggiamento è nella barca!', 28153),
(160830, 'itIT', 'Cos\'è successo mentre ero laggiù? L\'Alleanza è qui!', 'Cos\'è successo mentre ero laggiù? L\'Alleanza è qui!', 28153),
(160829, 'itIT', 'Anche l\'Alleanza è qui?', 'Anche l\'Alleanza è qui?', 28153),
(160828, 'itIT', 'Aspetta, che ci fai qui?', 'Aspetta, che ci fai qui?', 28153),
(160827, 'itIT', 'Non toccare!', 'Non toccare!', 28153),
(160826, 'itIT', 'Ripulirò il ponte col tuo sangue!', 'Ripulirò il ponte col tuo sangue!', 28153),
(160825, 'itIT', 'Fermo io $gquel dannato:quella dannata; $PR!', 'Fermo io $gquel dannato:quella dannata; $PR!', 28153),
(160824, 'itIT', 'Qualunque cosa tu stia facendo, smettila!', 'Qualunque cosa tu stia facendo, smettila!', 28153),
(160823, 'itIT', 'Cosa ci hanno portato i Loa oggi?', 'Cosa ci hanno portato i Loa oggi?', 28153),
(160822, 'itIT', 'Giù le mani dai rifornimenti!', 'Giù le mani dai rifornimenti!', 28153),
(160821, 'itIT', 'Non lasciate che si avvicinino ai cannoni!', 'Non lasciate che si avvicinino ai cannoni!', 28153),
(160820, 'itIT', 'Non toccare!', 'Non toccare!', 28153),
(160819, 'itIT', 'Vieni via da lì!', 'Vieni via da lì!', 28153),
(160818, 'itIT', 'Seppellitemi... in mare...', 'Seppellitemi... in mare...', 28153),
(160817, 'itIT', '$gMaledetto:Maledetta;... Tu e il tuo Re...', '$gMaledetto:Maledetta;... Tu e il tuo Re...', 28153),
(160816, 'itIT', 'Sei in trappola... qui con noi...', 'Sei in trappola... qui con noi...', 28153),
(160815, 'itIT', 'Per... la mia Capoguerra...', 'Per... la mia Capoguerra...', 28153),
(160814, 'itIT', 'Cane dell\'Alleanza...', 'Cane dell\'Alleanza...', 28153),
(160813, 'itIT', 'Doveva essere... una cosa... facile...', 'Doveva essere... una cosa... facile...', 28153),
(160812, 'itIT', 'Nathanos... vi... ucciderà... tutti...', 'Nathanos... vi... ucciderà... tutti...', 28153),
(160811, 'itIT', 'Per... la Regina... Banshee...', 'Per... la Regina... Banshee...', 28153),
(160810, 'itIT', 'Sapevo di aver sentito l\'odore di $gun brutto:una brutta; $PR.', 'Sapevo di aver sentito l\'odore di $gun brutto:una brutta; $PR.', 28153),
(160809, 'itIT', 'Ti faccio a fettine!', 'Ti faccio a fettine!', 28153),
(160808, 'itIT', 'Qualcuno lo dica a Nathanos!', 'Qualcuno lo dica a Nathanos!', 28153),
(160807, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(160806, 'itIT', 'Per la Dama Oscura!', 'Per la Dama Oscura!', 28153),
(160805, 'itIT', 'Addosso!', 'Addosso!', 28153),
(160804, 'itIT', 'Allontanati dalla nostra nave!', 'Allontanati dalla nostra nave!', 28153),
(160803, 'itIT', 'L\'Alleanza è qui!', 'L\'Alleanza è qui!', 28153),
(160802, 'itIT', 'Draven... ti eliminerà...', 'Draven... ti eliminerà...', 28153),
(160801, 'itIT', 'Solo un altro... po\'... di potere...', 'Solo un altro... po\'... di potere...', 28153),
(160800, 'itIT', 'Sono... invincibile...', 'Sono... invincibile...', 28153),
(160799, 'itIT', 'Che tu sia $gmaledetto:maledetta;...', 'Che tu sia $gmaledetto:maledetta;...', 28153),
(160798, 'itIT', 'Il Principe del Sangue... ti... prosciugherà...', 'Il Principe del Sangue... ti... prosciugherà...', 28153),
(160797, 'itIT', 'No!', 'No!', 28153),
(160796, 'itIT', 'Continua così! Ancora un po\'...', '', 28153),
(160795, 'itIT', 'Un ultimo... goccio...', 'Un ultimo... goccio...', 28153),
(160794, 'itIT', 'Solo... un altro...', 'Solo... un altro...', 28153),
(160793, 'itIT', 'Implorerai pietà prima che avrò finito con te.', 'Implorerai pietà prima che avrò finito con te.', 28153),
(160792, 'itIT', 'Non sei che cibo per i San\'layn!', 'Non sei che cibo per i San\'layn!', 28153),
(160791, 'itIT', 'Sì! Credo stia funzionando...', '', 28153),
(160790, 'itIT', '$gUn giovane:Una giovane; $PR... Curioso...', '$gUn giovane:Una giovane; $PR... Curioso...', 28153),
(160789, 'itIT', 'Ti prosciugherò la carne dalle ossa!', 'Ti prosciugherò la carne dalle ossa!', 28153),
(160788, 'itIT', 'Guarda un po\' cosa vagabondava sulla nostra nave.', 'Guarda un po\' cosa vagabondava sulla nostra nave.', 28153),
(160787, 'itIT', 'Questo ti farà male dolcemente.', 'Questo ti farà male dolcemente.', 28153),
(160786, 'itIT', 'Lascia che ti senta urlare.', 'Lascia che ti senta urlare.', 28153),
(160785, 'itIT', 'Avvicinati, $PR...', 'Avvicinati, $PR...', 28153),
(160784, 'itIT', '$gUn vero:Una vera; $C, eh? Cosa ti porta da queste parti?\n\nAh, deve essere a causa della battaglia che incombe, immagino. Bene allora, questa chiacchierata mi ha lasciato la gola secca.\n\nOra, se vuoi scusarmi, devo continuare i preparativi.', '', 28153),
(160783, 'itIT', 'La battaglia attende. Un tipo come te ci sarebbe molto utile nei nostri ranghi.', '', 28153),
(160782, 'itIT', 'Vieni con noi al sicuro. Non ti faremo del male.', 'Vieni con noi al sicuro. Non ti faremo del male.', 28153),
(160781, 'itIT', 'Ti prego, lasciami stare!', 'Ti prego, lasciami stare!', 28153),
(160780, 'itIT', 'L\'Orda... è qui?', 'L\'Orda... è qui?', 28153),
(160779, 'itIT', 'Vattene da qui, è troppo tardi...', 'Vattene da qui, è troppo tardi...', 28153),
(160778, 'itIT', 'Questo dovrebbe essere un momento di festa, ma questo mondo in continuo cambiamento spesso rende le cose difficili. Potrei aiutarti, se decidessi di unirti alle celebrazioni!', '', 28153),
(160777, 'itIT', '<Tiragli un pugno.>', '<Tiragli un pugno.>', 28153),
(160776, 'itIT', 'Roko ti manda i suoi saluti.', 'Roko ti manda i suoi saluti.', 28153),
(160775, 'itIT', 'Ti ricordi di me?', 'Ti ricordi di me?', 28153),
(160774, 'itIT', 'Che affari tieni con li esiliati e i rifugiati delle sabbie? Vol\'dun è dove mandiamo i criminali a schiattare.\n\nDi te però ci si può fidare, quindi ascolta attentamente. Cerca na Vulpera di nome Jena l\'Incettatrice, che dovresti trovare in nu posto chiamato Rifugio dei Vulpera.', 'Che affari tieni con li esiliati e i rifugiati delle sabbie? Vol\'dun è dove mandiamo i criminali a schiattare.\n\nDi te però ci si può fidare, quindi ascolta attentamente. Cerca na Vulpera di nome Jena l\'Incettatrice, che dovresti trovare in nu posto chiamato Rifugio dei Vulpera.', 28153),
(160773, 'itIT', 'Sei qui per chiedere l\'elemosina come tutta la massa puzzolente là fuori?$B$BNon farmi perdere tempo. Sono qui per fare affari.', 'Sei qui per chiedere l\'elemosina come tutta la massa puzzolente là fuori?$B$BNon farmi perdere tempo. Sono qui per fare affari.', 28153),
(160772, 'itIT', 'Che ti serve da loro? Sono un branco di sciacalli ed esiliati. La Dama Oscura ti ha forse chiesto di invitarli a combattere per noi?\n\nComunque, dovresti provare al Rifugio dei Vulpera a Vol\'dun. C\'è una piccola volpe di nome Jena l\'Incettatrice che potrebbe aiutarti.', 'Che ti serve da loro? Sono un branco di sciacalli ed esiliati. La Dama Oscura ti ha forse chiesto di invitarli a combattere per noi?\n\nComunque, dovresti provare al Rifugio dei Vulpera a Vol\'dun. C\'è una piccola volpe di nome Jena l\'Incettatrice che potrebbe aiutarti.', 28153),
(160771, 'itIT', 'Emissario Voldunai', 'Emissario Voldunai', 28153),
(160770, 'itIT', 'I Destatempesta sono brava gente, per quanto mi riguarda. Se vuoi parlare con uno dei loro capi, devi raggiungere Brennadam, nella Valle dei Sacraonda.\n\nUna volta lì, cerca Sorella Lilyana; può aiutarti in qualsiasi affare tu abbia in sospeso.', 'I Destatempesta sono brava gente, per quanto mi riguarda. Se vuoi parlare con uno dei loro capi, devi raggiungere Brennadam, nella Valle dei Sacraonda.\n\nUna volta lì, cerca Sorella Lilyana; può aiutarti in qualsiasi affare tu abbia in sospeso.', 28153),
(160769, 'itIT', 'Emissaria dei Destatempesta', 'Emissaria dei Destatempesta', 28153),
(160768, 'itIT', '<Ti fermi un attimo per ascoltare.>', '<Ti fermi un attimo per ascoltare.>', 28153),
(160767, 'itIT', 'A quanto pare abbiamo spaventato persino la tempesta.', '', 28153),
(160766, 'itIT', 'Questa guerra è durata abbastanza.\n\nL\'Alleanza si nasconde dietro un velo di rettitudine e pietà. Ipocriti! Non fanno che rinnegare e ripudiare chiunque non trovi spazio nella loro visione ottusa del mondo.', '', 28153),
(160765, 'itIT', '<Ti fermi un attimo per ascoltare.>', '<Ti fermi un attimo per ascoltare.>', 28153),
(160764, 'itIT', '', 'Pare sia stata richiamata in servizio ancora una volta, per eseguire i piani dell\'ennesimo signore.\n\nFarò il possibile per continuare a sopravvivere, ma prima o poi questa guerra finirà e dobbiamo essere pronti a ciò che ci aspetta.', 28153),
(160763, 'itIT', '<Ti fermi un attimo per ascoltare.>', '<Ti fermi un attimo per ascoltare.>', 28153),
(160762, 'itIT', 'Astuzia e sotterfugio sono le nostre migliori armi in questa guerra, $n.', '', 28153),
(160761, 'itIT', '<Ti fermi un attimo per ascoltare.>', '<Ti fermi un attimo per ascoltare.>', 28153),
(160759, 'itIT', 'Quando i Granmartello sono dalla tua parte, basta guardare in alto in caso di pericolo!', '', 28153),
(160758, 'itIT', 'La campagna procede spedita, $n, ed è certamente merito anche tuo.', '', 28153),
(160757, 'itIT', 'La Dama Oscura riderà di gusto... quando le dirò che sei $gmorto:morta; in trappola come lo scarafaggio che sei!', '', 28153),
(160756, 'itIT', 'Non vedevo l\'ora di porre fine alla tua misera esistenza.', '', 28153),
(160755, 'itIT', 'Facciamola finita.', '', 28153),
(160754, 'itIT', 'Ordine delle Braci? Cosa sarebbe? Sembra molto misterioso.\n\nHo sentito dire qualcosa a riguardo da un tizio al Presidio di Arom, a ovest, nella regione di Drustvar. Si fa chiamare Quartiermastro Alcorn. Immagino tu voglia sapere come arrivarci, se sei qui. Vieni, lascia che ti segni la posizione sulla mappa.', 'Ordine delle Braci? Cosa sarebbe? Sembra molto misterioso.\n\nHo sentito dire qualcosa a riguardo da un tizio al Presidio di Arom, a ovest, nella regione di Drustvar. Si fa chiamare Quartiermastro Alcorn. Immagino tu voglia sapere come arrivarci, se sei qui. Vieni, lascia che ti segni la posizione sulla mappa.', 28153),
(160753, 'itIT', 'Le sorelle Nerapalude hanno richiesto la mia assistenza. Il mondo ha già visto così tanti cambiamenti. Perché la cosa ci dovrebbe impedire di divertirci?', '', 28153),
(160752, 'itIT', 'Cosa ci fa qui un membro dello Stormo dei Draghi di Bronzo?', 'Cosa ci fa qui un membro dello Stormo dei Draghi di Bronzo?', 28153),
(160751, 'itIT', 'Ti stai godendo i festeggiamenti?', '', 28153),
(160750, 'itIT', 'Emissario dell\'Ordine delle Braci', 'Emissario dell\'Ordine delle Braci', 28153),
(160749, 'itIT', 'Ricevuto. Granmartello, rinfoderate le armi e rimanete in attesa fino al mio ordine.', '', 28153),
(160748, 'itIT', '', 'Non avvicinatevi troppo. Voglio osservarli e formulare un piano prima che si accorgano che siamo qui.', 28153),
(160747, 'itIT', 'Eccole lì, Generale. Due navi da guerra proprio davanti a noi. Reietti.', '', 28153),
(160746, 'itIT', 'Ximo dice che nun dovrei parlare con i clienti.', '', 28153),
(160745, 'itIT', '', 'Muori in pace, Grommash Malogrido.', 28153),
(160744, 'itIT', 'Non lasciamo che il suo sacrificio sia vano! Andiamo! Ora!', '', 28153),
(160743, 'itIT', '', 'No! Rimarrò al fianco del mio Capoguerra!', 28153),
(160742, 'itIT', 'Radunatevi, presto! Abbiamo solo una possibilità!', '', 28153),
(160741, 'itIT', 'Per i Mag\'har! Per Draenor! Lok\'tar ogar!', '', 28153),
(160740, 'itIT', '', 'Sono riuscita a portare via qualche cassa di rifornimenti prima di andarmene. Puoi prenderne qualcuna. Devi recuperare le forze!', 28153),
(160739, 'itIT', '', 'I miei fratelli e le mie sorelle hanno esagerato. Ora tocca a noi risolvere tutto questo.', 28153),
(160738, 'itIT', '', 'Abbiamo delle cuccette, se desideri riposare. Non è molto, ma è quello che abbiamo.', 28153),
(160737, 'itIT', 'Geya\'rah, fai uscire tutti da qui. Ora. Niente domande.', '', 28153),
(160736, 'itIT', '<Grommash abbassa la voce in modo che solo i Mag\'har possano sentire.>', '', 28153),
(160735, 'itIT', '', 'Mi addolora perdere un vecchio amico, Grommash. Ma... non fa niente. Risolveremo la cosa a modo tuo.', 28153),
(160734, 'itIT', 'Come puoi essere così cieca, Yrel? È la Luce ad aver condannato questo mondo!', '', 28153),
(160733, 'itIT', '', 'La tua gente sta prosciugando la linfa vitale del mondo... condannando a morte questa terra.', 28153),
(160732, 'itIT', '', 'Sono venuta a offrirti un\'ultima occasione di abbracciare la Luce.', 28153),
(160731, 'itIT', 'Gran Esarca. Che onore... inaspettato.', '', 28153),
(160730, 'itIT', '', 'Grommash Malogrido. È passato molto tempo.', 28153),
(160729, 'itIT', '', 'Dobbiamo! Cadere vittima di questa corruzione NON è il nostro destino!', 28153),
(160728, 'itIT', 'La barca per Kul Tiras è appena arrivata. Tutti a bordo. Destinazione: Boralus!', 'La barca per Kul Tiras è appena arrivata. Tutti a bordo. Destinazione: Boralus!', 28153),
(160727, 'itIT', 'Sono troppi! Non possiamo resistere per sempre!', '', 28153),
(160726, 'itIT', '$n, dirigiti in cima alla torre e scatena l\'inferno sui Vincolaluce!', '', 28153),
(160725, 'itIT', 'Supremo, Eitrigg. Aiutatemi a difendere la posizione!', '', 28153),
(160724, 'itIT', 'Lantresor, cavalca il più in fretta possibile! Raduna tutti gli Orchi che trovi e mandali qui!', '', 28153),
(160723, 'itIT', '...', '', 28153),
(160722, 'itIT', 'Tutti?', '', 28153),
(160721, 'itIT', 'Tutti quanti.', '', 28153),
(160720, 'itIT', 'Quanti ne dovremo affrontare, Lantresor?', '', 28153),
(160719, 'itIT', 'Capoguerra Malogrido! Si avvicina un\'armata!', '', 28153),
(160718, 'itIT', '<Vola a Roccavento.>', '<Vola a Roccavento.>', 28153),
(160717, 'itIT', '', 'L\'Implacabile ha appena attraccato! Tutti a bordo. Destinazione: Roccavento', 28153),
(160716, 'itIT', 'Suprema! Mazzapietra no vuole problemi con Orchi. Kor\'gall è in sua caverna.', '', 28153),
(160715, 'itIT', 'Stai già tornando a casa? Per tua fortuna, una delle poche navi dell\'Alleanza rimaste fa molto spesso spola tra qui e Roccavento. Dirigiti al molo di legno sul lato meridionale del Mercato di Ventosaldo.\n\nCi si vede.', 'Stai già tornando a casa? Per tua fortuna, una delle poche navi dell\'Alleanza rimaste fa molto spesso spola tra qui e Roccavento. Dirigiti al molo di legno sul lato meridionale del Mercato di Ventosaldo.\n\nCi si vede.', 28153),
(160714, 'itIT', 'Nave per Roccavento', 'Nave per Roccavento', 28153),
(160713, 'itIT', 'Rimarresti $gsorpreso:sorpresa; nel sapere quante riparazioni ho dovuto fare qui. Con tutta la magia che usano quei Saggi delle Maree, potevano pensare anche a dei materiali impermeabili.', '', 28153),
(160712, 'itIT', '<Vola a Orgrimmar.>', '<Vola a Orgrimmar.>', 28153),
(160711, 'itIT', 'Se devo dire la verità, non mi sono mai davvero fidato di loro. Voglio dire, hai visto i loro stendardi?', '', 28153),
(160710, 'itIT', 'I Saggi delle Maree sono tutti impazziti!', '', 28153),
(160709, 'itIT', 'Sei mai $gstato:stata; in uno dei bar sommersi nostri? Te li consiglio caldamente!', '', 28153),
(160708, 'itIT', 'Quando la barca è vuota, mi rilasso mettendo i piedi miei nell\'acqua.', '', 28153),
(160707, 'itIT', 'Nun ci sta nulla di meglio del profumo di salsedine nell\'aria.', '', 28153),
(160706, 'itIT', 'Viviamo su n\'isola per nun essere infastiditi dal resto del mondo. Perché nun se ne tornano tutti quanti a casa loro? Nun intendevo anche te, ovviamente.', '', 28153),
(160705, 'itIT', 'Il rumore dei remi nell\'acqua è così rilassante.', '', 28153),
(160704, 'itIT', 'Zeb\'ahari è sempre stato il posto preferito mio, così tranquillo e rilassante, assai lontano dal caos di Dazar\'alor. Si può apprezzare davvero molto il fascino di Zuldazar.', '', 28153),
(160703, 'itIT', 'Ricordo che quando ero nu Troll piccirillo, adoravo le nostre gite alla costa.', '', 28153),
(160702, 'itIT', 'Prima ripuliranno le spiagge nostre, più felice sarò!', '', 28153),
(160701, 'itIT', 'Mandami alla Vena Mineraria di Galson.', 'Mandami alla Vena Mineraria di Galson.', 28153),
(160700, 'itIT', 'Mandami alla Segheria delle Alture.', 'Mandami alla Segheria delle Alture.', 28153),
(160699, 'itIT', 'Mandami al Forte di Stromgarde.', 'Mandami al Forte di Stromgarde.', 28153),
(160698, 'itIT', 'Serve un passaggio?', '', 28153),
(160697, 'itIT', 'Metteremo le cose a posto se lavoriamo tutti insieme!', '', 28153),
(160696, 'itIT', 'Lascia che siano i periti a trovare i problemi!', '', 28153),
(160695, 'itIT', 'Hai un\'ammaccatura da qualche parte? Ci penso io!', '', 28153),
(160694, 'itIT', '<Prendi gli appunti.>', '<Prendi gli appunti.>', 28153),
(160693, 'itIT', '', '\"Dopo aver trovato finalmente una base adatta, abbiamo prodotto con successo un composto stabile.$B$BIn questa forma può essere immagazzinata, trasportata o aggiunta al processo di mescolamento per produrre una variante di polvere nera estremamente potente!$B$BHo così fiducia della sua stabilità che i primi campioni sono stati spediti a Boralus sospesi all\'interno di una collana.$B$BMentre i calderoni vengono mescolati giorno e notte per amalgamare le polveri, anche i lavori di prototipazione di nuovi possibili utilizzi continuano senza sosta. Il nostro progetto più promettente è una pistola, che speriamo diventi un nuovo dono per la nostra stimata responsabile.\"$B$B<Gli appunti continuano concentrandosi sui dettagli di vari progetti e aspirazioni.>', 28153),
(160692, 'itIT', 'Potenziamento', 'Potenziamento', 28153),
(160691, 'itIT', '', 'Quando Zandalar sarà in rovina, l\'impero degli Dei Antichi rinascerà!', 28153),
(160690, 'itIT', '', 'Nun tenete speranze... G\'huun sarà libero!', 28153),
(160689, 'itIT', '', 'Se l\'ultimo sigillo sarà distrutto, quel mostro si scatenerà su Azeroth!', 28153),
(160688, 'itIT', 'Le scansioni indicano che i dispositivi di Nazmir e Vol\'dun sono fuori uso. Ultimo sigillo funzionante: Zuldazar.', '', 28153),
(160687, 'itIT', 'Soggetto: G\'huun.', '', 28153),
(160686, 'itIT', '', 'Chesto finisce mo\'.', 28153),
(160685, 'itIT', '', 'I crimini tuoi nun rimarranno più impuniti.', 28153),
(160684, 'itIT', 'E nun ci sta posto per te tra i re.', '', 28153),
(160683, 'itIT', 'Nun capisci?', '', 28153),
(160682, 'itIT', 'Come dovremmo chiamarti mo\'?', '', 28153),
(160681, 'itIT', 'Hai sconfinato su un luogo sacro.', '', 28153),
(160680, 'itIT', 'Sono pronto ad assisterti.', 'Sono pronta ad assisterti.', 28153),
(160679, 'itIT', '', 'Anche se questi giorni sono stati funestati da numerose perdite, andremo avanti.', 28153),
(160678, 'itIT', 'Ricorda, tieni in basso la parte bagnata!', '', 28153),
(160677, 'itIT', 'Rosso di sera, il marinaio si schiera. Rosso di mattina, il marinaio sta in sentina.', '', 28153),
(160676, 'itIT', 'La nave sta al sicuro nel porto... ma dove sta il divertimento in chesto?', '', 28153),
(160675, 'itIT', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t Mythrax inizia a lanciare |cFFFF0000|Hspell:274113|h[Raggio dell\'Annichilimento]|h|r!', '|TInterface\\ICONS\\Spell_Priest_VoidSear.blp:20|t Mythrax inizia a lanciare |cFFFF0000|Hspell:274113|h[Raggio dell\'Annichilimento]|h|r!', 28153),
(160674, 'itIT', 'Ottimo lavoro, $p. Ben fatto, Shandris.', '', 28153),
(160673, 'itIT', 'Xibala', 'Xibala', 28153),
(160672, 'itIT', 'Se vuoi imparare a creare dell\'equipaggiamento più efficacemente, allora sei nel posto giusto. Ho proprio ciò che ti serve.', '', 28153),
(160671, 'itIT', 'I Granmartello racconteranno storie di questa missione per anni a venire... ma ora mi serve proprio una bella pinta.', '', 28153),
(160670, 'itIT', '', 'Terremo d\'occhio i movimenti dei Sethrak qui sotto. Puoi contare su di noi!', 28153),
(160669, 'itIT', 'Sei $gil migliore:la migliore;!', 'Sei $gil migliore:la migliore;!', 28153),
(160668, 'itIT', 'Falli saltare in aria ancora!', 'Falli saltare in aria ancora!', 28153),
(160667, 'itIT', 'Crescerò e diventerò proprio come te!', 'Crescerò e diventerò proprio come te!', 28153),
(160666, 'itIT', 'Sei $gun eroe:un\'eroina;!', 'Sei $gun eroe:un\'eroina;!', 28153),
(160665, 'itIT', 'Se vuoi imparare a creare dell\'equipaggiamento più efficacemente, allora sei nel posto giusto. Ho proprio ciò che ti serve.', '', 28153),
(160664, 'itIT', '|TInterface\\Icons\\70_inscription_vantus_rune_light:20|t %s crea una |cFFFF0000|Hspell:267905|h[Guardia di Rinforzo]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t %s crea una |cFFFF0000|Hspell:267891|h[Guardia della Rapidità]|h|r!', 28153),
(160663, 'itIT', '', 'Sia maledetta la Luce!', 28153),
(160662, 'itIT', '', 'No... Un Naaru... Non di nuovo!', 28153),
(160661, 'itIT', '', '...e del destino dei miei fratelli e sorelle al Forte di Vespreterno. Temo ci sia ben poco che possiamo fare per salvarli, ora.', 28153),
(160660, 'itIT', 'È ora di andare, eroi! Non mi pagano per starmene qui ad aspettare!', 'È ora di andare, eroi! Non mi pagano per starmene qui ad aspettare!', 28153),
(160659, 'itIT', 'Magni Barbabronzea ti attende a Silitus. Presto! La terra stessa si sta rivoltando contro di noi!', '', 28153),
(160658, 'itIT', 'Magni Barbabronzea ha bisogno del tuo aiuto, $gcampione:campionessa;. Dobbiamo parlare immediatamente.', '', 28153),
(160657, 'itIT', 'Devo parlare con te, $gcampione:campionessa;!', '', 28153),
(160656, 'itIT', '$gCampione:Campionessa;, dobbiamo parlare. Magni Barbabronzea ha bisogno del tuo aiuto!', '', 28153),
(160655, 'itIT', '$gCampione:Campionessa;! Porto un messaggio urgente da Magni Barbabronzea, l\'Oratore di Azeroth.', '', 28153),
(160654, 'itIT', 'Sono pronto a partire.', 'Sono pronta a partire.', 28153),
(160653, 'itIT', 'Sei $gpronto:pronta; a partire?', 'Sei $gpronto:pronta; a partire?', 28153),
(160652, 'itIT', '', 'Una volta fatto breccia, il dolore diventa... sopportabile. Dammi... solo un momento.', 28153),
(160650, 'itIT', '', 'Preparatevi...', 28153),
(160649, 'itIT', '', 'Attraverseremo le mura al mio ordine!', 28153),
(160648, 'itIT', 'L\'Autodistruzione è stata attivata!', 'L\'Autodistruzione è stata attivata!', 28153),
(160647, 'itIT', 'No, credo che ci sia qualcosa di sbagliato. Riproviamo?', '', 28153),
(160646, 'itIT', '', 'La mia gente resisterà.', 28153),
(160645, 'itIT', 'Sono pronto a partire.', 'Sono pronta a partire.', 28153),
(160644, 'itIT', '', 'L\'Orda pagherà per quest\'incursione!', 28153),
(160643, 'itIT', '', 'Elune... salvaci.', 28153),
(160642, 'itIT', '', 'Io servo i Kaldorei.', 28153),
(160641, 'itIT', '', 'Sono felice che tu sia con noi.', 28153),
(160640, 'itIT', '', 'C\'è molto da fare.', 28153),
(160639, 'itIT', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t La |cFFFF0000|Hspell:274149|h[Forza Vitale]|h|r dell\'Avatar è aumentata e viene curato!', '|TInterface\\Icons\\ABILITY_MONK_HEALTHSPHERE.BLP:20|t La |cFFFF0000|Hspell:274149|h[Forza Vitale]|h|r dell\'Avatar è aumentata e viene curato!', 28153),
(160638, 'itIT', 'Cavalieri di Grifoni, tornate in formazione. Qui abbiamo finito!', '', 28153),
(160637, 'itIT', 'Hai sentito il Generale, Alalesta. Riportaci a Boralus!', '', 28153),
(160636, 'itIT', '', 'Siamo pronti a partire, Falstad.', 28153),
(160635, 'itIT', 'L\'Orda è qui?!? Preferirei rischiare la vita nuotando tra gli squali!', 'L\'Orda è qui?!? Preferirei rischiare la vita nuotando tra gli squali!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160634, 'itIT', 'Meglio che se ne vadano loro, piuttosto che io sbagli per la fretta. I meloni richiedono movimenti delicati ma decisi.', '', 28153),
(160633, 'itIT', 'Forse potrei provare a tagliare il melone con la linguaccia tua, Grozzak.', '', 28153),
(160632, 'itIT', 'Sto tagliando più veloce che posso!', '', 28153),
(160631, 'itIT', 'Nun si può mettere fretta al cuoco. Tagliare i meloni è n\'arte.', '', 28153),
(160630, 'itIT', 'Tengo bisogno dei meloni o i clienti se ne andranno.', '', 28153),
(160629, 'itIT', 'Forse il coltello nun è ben affilato...', '', 28153),
(160628, 'itIT', 'Pare che ci voglia parecchio tempo per tagliare nu melone, Ka\'ro.', '', 28153),
(160627, 'itIT', 'I clienti stanno aspettando. Quanto ci vorrà?', '', 28153),
(160626, 'itIT', 'I miei Granmartello non riusciranno a tenere occupati Nathanos e il resto dell\'Orda ancora per molto. Sei $gpronto:pronta; a partire?', '', 28153),
(160625, 'itIT', 'Azeroth sarà un posto migliore senza quel Principe del Sangue. Hai agito bene, $p.', '', 28153),
(160624, 'itIT', 'Finisci lo scontro.', 'Finisci lo scontro.', 28153),
(160623, 'itIT', 'Avete fatto molto per Boralus oggi, eroi. Ora è il mio turno.', 'Avete fatto molto per Boralus oggi, eroi. Ora è il mio turno.', 28153),
(160622, 'itIT', 'Preparati a saltare, $p. Ti porterò direttamente sopra la Vento Cremisi.', '', 28153),
(160621, 'itIT', '', 'Per quale Loa vorresti che creassi una statua?', 28153),
(160620, 'itIT', 'Posso portarti alla Vento Cremisi, $p. Shandris ti sta aspettando lì.', '', 28153),
(160619, 'itIT', 'Non sfuggirà mai... Alle... Terre Ammorbate...', '', 28153),
(160618, 'itIT', 'Thros consuma tutto! Lei è nostra!', '', 28153),
(160617, 'itIT', 'Vorrei cambiare il Loa rappresentato qui da Vol\'dun.', 'Vorrei cambiare il Loa rappresentato qui da Vol\'dun.', 28153),
(160616, 'itIT', 'Vorrei cambiare il Loa rappresentato qui da Nazmir.', 'Vorrei cambiare il Loa rappresentato qui da Nazmir.', 28153),
(160615, 'itIT', '', 'Mi dirigo alla periferia per avvertire i cittadini. Andate al porto, presto. Ci vediamo là!', 28153),
(160614, 'itIT', '', 'Intesi... Ammiraglio Supremo.', 28153),
(160613, 'itIT', '', 'Sembra che la festa di benvenuto debba aspettare.', 28153),
(160612, 'itIT', 'Rieccoti! Cos\'è successo?', '', 28153),
(160611, 'itIT', 'Stai sparendo da...', '', 28153),
(160609, 'itIT', 'Buona fortuna.', '', 28153),
(160608, 'itIT', 'Io rimarrò con le nostre guide per aiutarti a ritrovare la strada verso la riva.', '', 28153),
(160607, 'itIT', 'Speriamo di trovare chi cerchiamo. Fai attenzione, quest\'isola trasuda malvagità.', '', 28153),
(160606, 'itIT', 'Non ho idea di cosa troveremo quando arriveremo a Fine del Destino, $p.', '', 28153),
(160605, 'itIT', 'Cosa? Eri $gpreoccupato:preoccupata;? Ahahah!\n\n<Tossisce>\n\nAh... mi fa ancora un po\' male, ma me la caverò.\n\nD\'altronde, il mio lavoro è finito. Tu e Taelia tornate a Boralus a fare le vostre cose da eroi.', '', 28153),
(160604, 'itIT', '', 'Vieni, Amalia. Continuiamo la nostra lezione su cosa significa essere Reietti.', 28153),
(160603, 'itIT', 'Mostrami cos\'hai da vendere.', 'Mostrami cos\'hai da vendere.', 28153),
(160602, 'itIT', 'Ero in cerca di rifornimenti quando ho iniziato ad aver problemi al motore. Ho fatto un atterraggio d\'emergenza proprio in questo punto e ho aspettato l\'arrivo degli aiuti per giorni.$b$bHai mai provato a sopravvivere in una palude mangiando solo rametti e muschio? Io sì!', '', 28153),
(160601, 'itIT', '', 'Segnalate a Falstad di raggiungermi in volo. Torneremo a Boralus insieme.', 28153),
(160600, 'itIT', '', 'Il Principe del Sangue Dreven è morto. Dobbiamo muoverci prima che Nathanos e gli altri si accorgano del diversivo dei Granmartello.', 28153),
(160599, 'itIT', '', 'Anu\'dorini talah... mostro.', 28153),
(160598, 'itIT', 'Gorak Tul... ti farà a pezzi...', '', 28153),
(160597, 'itIT', 'La pagherai!', '', 28153),
(160596, 'itIT', 'Chi osa dissacrare queste ossa?', '', 28153),
(160595, 'itIT', 'Oh, proprio come diceva mia madre dopo aver cucinato la sua famosa torta.\n\nMolto bene, ti mostrerò... il lavoro di tutta la mia vita!\n\nÈ nella cassa sul retro ed è tutta tua!\n\nSperiamo ne sia valsa la pena!', 'Oh, proprio come diceva mia madre dopo aver cucinato la sua famosa torta.\n\nMolto bene, ti mostrerò... il lavoro di tutta la mia vita!\n\nÈ nella cassa sul retro ed è tutta tua!\n\nSperiamo ne sia valsa la pena!', 28153),
(160594, 'itIT', 'Ho un buon odore?', 'Ho un buon odore?', 28153),
(160593, 'itIT', 'Eccellente. Ma... ehm... Ecco, io...', 'Eccellente. Ma... ehm... Ecco, io...', 28153),
(160592, 'itIT', 'Ho mandato dei messaggi ai tuoi nemici. Ora, riguardo a quei segreti...', 'Ho mandato dei messaggi ai tuoi nemici. Ora, riguardo a quei segreti...', 28153),
(160591, 'itIT', 'Sono io, il tuo amico. Hai qualche segreto da raccontarmi?', 'Sono io, la tua amica. Hai qualche segreto da raccontarmi?', 28153),
(160590, 'itIT', 'Non ho idea di cosa tu stia parlando!', 'Non ho idea di cosa tu stia parlando!', 28153),
(160589, 'itIT', 'Ciao! Non ricevo visitatori molto spesso, chiedo scusa per il disordine.', 'Ciao! Non ricevo visitatori molto spesso, chiedo scusa per il disordine.', 28153),
(160588, 'itIT', '', 'Dea, dammi la forza!', 28153),
(160587, 'itIT', '', 'No! Niente più trucchetti! Niente più fughe! La giustizia non può più aspettare.', 28153),
(160586, 'itIT', '<Il Principe del Sangue Dreven inizia a lanciare un incantesimo per fuggire!>', '', 28153),
(160585, 'itIT', 'Sono stanco della vostra patetica incompetenza in combattimento. Non perderò altro tempo con voi.', '', 28153),
(160584, 'itIT', 'Fai come se fosse casa tua.', 'Fai come se fosse casa tua.', 28153),
(160583, 'itIT', 'Ti accoglierei volentieri con un sorriso e un brindisi, ma non ho né pelle né qualcosa da bere.', 'Ti accoglierei volentieri con un sorriso e un brindisi, ma non ho né pelle né qualcosa da bere.', 28153),
(160582, 'itIT', 'Oh cielo, dei visitatori! E non ho nulla da mettermi addosso.', 'Oh cielo, dei visitatori! E non ho nulla da mettermi addosso.', 28153),
(160581, 'itIT', '', 'L\'Alleanza ha attaccato. Ti sei $gperso:persa; tutto il divertimento, $p.', 28153),
(160580, 'itIT', '$gBentornato:Bentornata;! Ci siamo... tenuti occupati mentre eri là sotto.', '', 28153),
(160579, 'itIT', 'Ha reso tutto più gustoso.', '', 28153),
(160578, 'itIT', 'Stupida ragazzina. Conoscevo già i loro nomi quando ho risucchiato la linfa vitale dai loro cadaveri.', '', 28153),
(160577, 'itIT', 'Io e Alalesta ti copriamo le spalle, $p! Continueremo a lanciare martelli dai boccaporti!', '', 28153),
(160576, 'itIT', '', 'Temo sia troppo tardi per quello, Amalia. Abbiamo $gun visitatore:una visitatrice;.', 28153),
(160575, 'itIT', '', 'Le forze di Dama Marefiero non si fermano, Nathanos. Dovremmo andarcene da qui il prima possibile.', 28153),
(160574, 'itIT', 'Ah, bene. Non solo sarà un grande vantaggio per la flotta degli Zandalari... ma sarà anche la condanna di quella dei Kul Tirani.', '', 28153),
(160573, 'itIT', 'Abbiamo recuperato con successo lo Scettro Abissale, Nathanos.', '', 28153),
(160572, 'itIT', 'Ahahah! Ce l\'hai fatta! La sala è al sicuro!', '', 28153),
(160571, 'itIT', 'No! Il sigillo si sta spezzando! Resisti! Ti prego, non mollare!', '', 28153),
(160570, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Ricorda di non fissare G\'huun mentre lancia |cFFFF0404|Hspell:267700|h[Sguardo di G\'huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t Ricorda di non fissare G\'huun mentre lancia |cFFFF0404|Hspell:267700|h[Sguardo di G\'huun]|h|r.', 28153),
(160569, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Recupera la |cFFFF0404|Hspell:263420|h[Matrice d\'Alimentazione]|h|r per scatenare una |cFFFF0404|Hspell:263482|h[Detonazione di Rioriginazione]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Recupera la |cFFFF0404|Hspell:263420|h[Matrice d\'Alimentazione]|h|r per scatenare una |cFFFF0404|Hspell:263482|h[Detonazione di Rioriginazione]|h|r!', 28153),
(160568, 'itIT', 'Zeb\'ahari', 'Zeb\'ahari', 28153),
(160567, 'itIT', 'Fammi sapere quando sarai $gpronto:pronta; a procedere verso il luogo del rituale, $n.', '', 28153),
(160566, 'itIT', '', 'Brutta storia.', 28153),
(160565, 'itIT', '', 'Aspetta, che succede laggiù?', 28153),
(160564, 'itIT', '', 'Era solo per provare le sue nuove armi... o per qualcosa di più?', 28153),
(160563, 'itIT', '', 'Non capisco... Perché Dama Bracescura avrebbe assoldato dei pirati per attaccare i Cancelli di Daelin?', 28153),
(160562, 'itIT', 'Vai con onore. Per l\'Orda.', '', 28153),
(160561, 'itIT', 'La prossima volta che ti chiamerò, sarà il momento di attaccare Boralus, la capitale di Kul Tiras.', '', 28153),
(160560, 'itIT', 'Abbiamo recuperato tutti i materiali che ci servono.', '', 28153),
(160558, 'itIT', 'Andiamo, allora. Dite a Velamesta che qui abbiamo finito.', '', 28153),
(160557, 'itIT', 'Sarà meglio muoversi prima che tornino. Non possiamo rischiare che scoprano le nostre recenti acquisizioni.', '', 28153),
(160556, 'itIT', 'L\'Alleanza ha attaccato mentre eri sott\'acqua, $p. Li abbiamo respinti, ma hanno distrutto l\'altra nostra nave.', '', 28153),
(160555, 'itIT', '', 'Sì, anche io.', 28153),
(160554, 'itIT', '', 'Anche tu?', 28153),
(160553, 'itIT', '', 'Dagli tempo, Stone. Tutti hanno bisogno di tempo per abituarsi alla vita dopo la morte.', 28153),
(160552, 'itIT', '', 'So che non mi accetterebbero mai... così... ma non posso voltare le spalle alla mia gente.', 28153),
(160551, 'itIT', '', 'Non posso farlo, Lilian.', 28153),
(160550, 'itIT', 'Come desideri.', '', 28153),
(160549, 'itIT', 'Eccellente. Tu e $p andate a parlare con Hobart. Egli fornirà a $p l\'equipaggiamento e le conoscenze necessarie a raggiungere il fondo dell\'oceano.', '', 28153),
(160548, 'itIT', 'Ne sono certo. Le maree non mentono: Valentine è laggiù.', '', 28153),
(160547, 'itIT', 'È questo il posto?', '', 28153),
(160546, 'itIT', 'Sì, mio signore.', '', 28153),
(160545, 'itIT', 'Dai le coordinate a Velamesta. Dobbiamo partire immediatamente.', '', 28153),
(160544, 'itIT', 'È un tabù di cui non dovrai più preoccuparti.', '', 28153),
(160543, 'itIT', 'Credo di sì, anche se devo dire che usare il potere di un Saggio delle Maree per recuperare un cadavere disperso in mare... è...', '', 28153),
(160542, 'itIT', 'Zelling. Sei sicuro di riuscire a scoprire dove si trova il corpo del Maresciallo Valentine?', '', 28153),
(160541, 'itIT', 'Vuoi fare un po\' di pratica? Buon per te, bisogna sempre rimanere reattivi, o si finisce morti. Bene, ciò che devi fare è raggiungere la sommità delle mura che sovrastano il Porto di Boralus.\n\nIl modo migliore per farlo è raggiungere Joan Weber, la Maestra di Volo del Mercato di Ventosaldo e scendere le scale alla sua sinistra. Segui la strada e vai a sud oltre il punto di controllo: troverai una piccola radura dove le mie guardie sono solite allenarsi.', 'Vuoi fare un po\' di pratica? Buon per te, bisogna sempre rimanere reattivi, o si finisce morti. Bene, ciò che devi fare è raggiungere la sommità delle mura che sovrastano il Porto di Boralus.\n\nIl modo migliore per farlo è raggiungere Joan Weber, la Maestra di Volo del Mercato di Ventosaldo e scendere le scale alla sua sinistra. Segui la strada e vai a sud oltre il punto di controllo: troverai una piccola radura dove le mie guardie sono solite allenarsi.', 28153),
(160540, 'itIT', '', 'Dobbiamo raggiungere Boralus. L\'Ammiraglio Supremo dev\'essere avvertito!', 28153),
(160539, 'itIT', '', 'Dirò al Tenente ciò che è successo. Vediamoci a Colle Vigile quando hai finito qui.', 28153),
(160538, 'itIT', '', 'Ma potrebbero tornare. E se puntassero quelle armi su Boralus...', 28153),
(160537, 'itIT', '', 'Facciamo in fretta!', 28153),
(160536, 'itIT', '', 'Messaggio urgente da Nathanos. I Marefiero sono sbarcati al Porto del Saccheggio.', 28153),
(160535, 'itIT', '', 'Usa Tiro Lacerante mentre attacchi il Manichino d\'Allenamento.', 28153),
(160534, 'itIT', 'Usa Tiro Lacerante mentre attacchi il Manichino.', '', 28153),
(160533, 'itIT', '', 'L\'odore del sangue fa impazzire il tuo famiglio, dandoti della concentrazione da sfruttare con le altre tue abilità.', 28153),
(160532, 'itIT', 'L\'odore del sangue fa impazzire il tuo famiglio, dandoti della concentrazione da sfruttare con le altre tue abilità.', '', 28153),
(160531, 'itIT', '', 'Puoi anche attaccare i nemici con un Tiro Lacerante, facendoli sanguinare per un periodo di tempo.', 28153),
(160530, 'itIT', '<La tua lampada frontale ha attirato uno Squalo Balena!>', '<La tua lampada frontale ha attirato uno Squalo Balena!>', 28153),
(160529, 'itIT', '', 'Ce l\'abbiamo fatta... Ce l\'abbiamo davvero fatta!', 28153),
(160528, 'itIT', 'Vuoi davvero tornare a evocare un Gargoyle invece di una Val\'kyr?', 'Vuoi davvero tornare a evocare un Gargoyle invece di una Val\'kyr?', 28153),
(160527, 'itIT', 'Vuoi davvero apprendere come evocare una Val\'kyr invece di un Gargoyle?', 'Vuoi davvero apprendere come evocare una Val\'kyr invece di un Gargoyle?', 28153),
(160526, 'itIT', '<Pare sia fuggito via.>', '<Pare sia fuggito via.>', 28153),
(160525, 'itIT', 'Non importa, dirò semplicemente a Sylvanas che le hai uccise tu... dopo aver fatto lo stesso con te!', '', 28153),
(160524, 'itIT', 'Il problema dei non morti è sempre stata la scarsezza di carne sulle loro ossa. Ho dovuto prosciugarne tre per eguagliare il potere di un Elfo della Notte.', '', 28153),
(160523, 'itIT', '<Percepisci qualcosa di grosso nascosto sotto le acque qui vicino...>', '<Percepisci qualcosa di grosso nascosto sotto le acque qui vicino...>', 28153),
(160522, 'itIT', '', 'Questa volta non andrai da nessuna parte, abominio. Sei sfuggito alla morte fin troppo a lungo.', 28153),
(160521, 'itIT', '', 'Imparerai il nome delle mie sorelle prima di morire, mostro!', 28153),
(160520, 'itIT', '', 'Sentinella Falia. Sentinella Aeolyn. Sentinella Lyrias.', 28153),
(160519, 'itIT', 'Stai in guardia, $n. Questa non è una semplice cantina... Ci troviamo nelle profondità più oscure di Boralus.', '', 28153),
(160518, 'itIT', '', 'Ricorda, giungerai nel cuore più profondo di Boralus. Stai all\'erta.', 28153),
(160517, 'itIT', 'Torniamo a Zuldazar.', 'Torniamo a Zuldazar.', 28153),
(160516, 'itIT', 'Abbiamo perso tutto!', 'Abbiamo perso tutto!', 28153),
(160515, 'itIT', 'Guarda! $gQuello è l\'eroe:Quella è l\'eroina; che ci ha aiutati a fuggire.', 'Guarda! $gQuello è l\'eroe:Quella è l\'eroina; che ci ha aiutati a fuggire.', 28153),
(160514, 'itIT', 'Immagino non abbiano intenzione di tenerci qui per sempre.', 'Immagino non abbiano intenzione di tenerci qui per sempre.', 28153),
(160513, 'itIT', 'Argh! È troppo luminoso qui!', 'Argh! È troppo luminoso qui!', 28153),
(160512, 'itIT', 'L\'entrata per la sala è da questa parte. Vieni!', '', 28153),
(160511, 'itIT', 'Lordaeron appartiene ai Reietti!', 'Lordaeron appartiene ai Reietti!', 28153),
(160510, 'itIT', '', 'Siamo arrivati proprio nel momento giusto. Thorgen non sarebbe sopravvissuto a lungo senza rinforzi... a prescindere da ciò che il Nano potrebbe dire.', 28153),
(160509, 'itIT', 'Sei $gtornato:tornata;. $gPronto:Pronta; ad andar giù di nuovo?', '', 28153),
(160508, 'itIT', 'Voglio tornare a evocare un Gargoyle invece di una Val\'kyr con il mio incantesimo Evocazione: Gargoyle.', 'Voglio tornare a evocare un Gargoyle invece di una Val\'kyr con il mio incantesimo Evocazione: Gargoyle.', 28153),
(160507, 'itIT', 'Voglio imparare a evocare una Val\'kyr invece di un Gargoyle con il mio incantesimo Evocazione: Gargoyle.', 'Voglio imparare a evocare una Val\'kyr invece di un Gargoyle con il mio incantesimo Evocazione: Gargoyle.', 28153),
(160506, 'itIT', 'L\'Orda? Prendi ciò che vuoi, ma risparmiami la vita!', '', 28153),
(160505, 'itIT', 'Ehi, ridammelo!', '', 28153),
(160504, 'itIT', '<Recupera il corpo di Derek Marefiero.>', '<Recupera il corpo di Derek Marefiero.>', 28153),
(160503, 'itIT', '<Recupera il corpo del Maresciallo Valentine.>', '<Recupera il corpo del Maresciallo Valentine.>', 28153),
(160502, 'itIT', 'Le Anime si nutRono di dolorE e Nel buiO urlAno ContorCendoSi in agoNia. Con ansia ti attendOno, E la sperAnZa svanisCe!', 'Le Anime si nutRono di dolorE e Nel buiO urlAno ContorCendoSi in agoNia. Con ansia ti attendOno, E la sperAnZa svanisCe!', 28153),
(160501, 'itIT', '', 'Le forze dell\'Orda stanno avanzando su Lor\'danel! Campione, con me!', 28153),
(160500, 'itIT', '', 'All\'attacco, $gamico:amica;! Usa le tue mascotte!', 28153),
(160499, 'itIT', '', 'Mangia le stelle, cattivone!', 28153),
(160498, 'itIT', '', 'Ohhh, so cosa fare con tizi come questo!', 28153),
(160497, 'itIT', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Marefiero\n\nPrincipe Erede di Kul Tiras', '|TINTERFACE\\ICONS\\INV_helm_crown_C_01_gold.blp:64|t\n\nDerek Marefiero\n\nPrincipe Erede di Kul Tiras', 28153),
(160496, 'itIT', '', 'La tua vile magia non può proteggerti, Dreven!', 28153),
(160495, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMaresciallo M. Valentine\n\nCapitano della Orgoglio di Tiragarde.\nMaresciallo della Terza Flotta di Kul Tiras.', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_12.BLP:64|t\n\nMaresciallo M. Valentine\n\nCapitano della Orgoglio di Tiragarde.\nMaresciallo della Terza Flotta di Kul Tiras.', 28153),
(160494, 'itIT', 'Non serve che ti ribadisca l\'importanza di questa missione, $n. La Dama Oscura conta su di noi.', '', 28153),
(160493, 'itIT', '', 'Attaccheremo il Principe del Sangue Dreven insieme. Nessuna pietà, nessuna fuga.', 28153),
(160492, 'itIT', 'Parla con me quando vuoi iniziare.', '', 28153),
(160491, 'itIT', 'Sì! Quella è la nave amm... No, aspetta... è solo una macchia sul vetro.', 'Sì! Quella è la nave amm... No, aspetta... è solo una macchia sul vetro.', 28153),
(160490, 'itIT', 'Vedi già i Kul Tirani?', 'Vedi già i Kul Tirani?', 28153),
(160489, 'itIT', 'La Scatola Rompicapo reagisce alla Proiezione di Yogg-Saron!', 'La Scatola Rompicapo reagisce alla Proiezione di Yogg-Saron!', 28153),
(160488, 'itIT', 'I Mag\'har sono condannati, Geya\'rah, ma ho fatto in modo che il mio clan possa resistere ben oltre la caduta del tuo.', '', 28153),
(160487, 'itIT', '', '|TInterface\\Icons\\Ability_Mage_RayofFrost:20|t %s attiva i |cFFFF0000|Hspell:268253|h[Raggi Difensivi di Uldir]|h|r!', 28153),
(160486, 'itIT', '', 'Silenzio! Se non ti farai indietro, sarò io stessa a costringerti a farlo.', 28153),
(160485, 'itIT', 'Ehi, datemi una mano con queste corde!', 'Ehi, datemi una mano con queste corde!', 28153),
(160484, 'itIT', 'Non lasciate che mi mangino!', 'Non lasciate che mi mangino!', 28153),
(160483, 'itIT', 'Aiuto!', 'Aiuto!', 28153),
(160482, 'itIT', 'Figlia dei lupi, non sei in grado di proteggere la tua stessa gente. Perché dovremmo seguirti?', '', 28153),
(160481, 'itIT', '', 'Cosa significa tutto questo, Kor\'gall? Lo sai che dobbiamo rimanere uniti, ora più che mai.', 28153),
(160480, 'itIT', 'Vorrei scegliere Akunda, il Loa delle Tempeste.', 'Vorrei scegliere Akunda, il Loa delle Tempeste.', 28153),
(160479, 'itIT', 'Vorrei scegliere Kimbul, il Signore delle Bestie.', 'Vorrei scegliere Kimbul, il Signore delle Bestie.', 28153),
(160478, 'itIT', 'Vorrei scegliere Bwonsamdi, il Loa della Morte.', 'Vorrei scegliere Bwonsamdi, il Loa della Morte.', 28153),
(160477, 'itIT', 'Vorrei scegliere Krag\'wa, l\'Enorme.', 'Vorrei scegliere Krag\'wa, l\'Enorme.', 28153),
(160476, 'itIT', '', 'Sembra che il Maresciallo Valentine abbia consegnato il nostro messaggio. La flotta dei Marefiero ha abboccato.', 28153),
(160475, 'itIT', '', 'Questo avamposto è pericolosamente vicino alla città, ma è ben nascosto e abbiamo una visuale perfetta sul Trono Dorato.\n\nLe nostre spie potranno tenere d\'occhio gli spostamenti di Re Rastakhan e dell\'Orda da qui.', 28153),
(160474, 'itIT', 'Sono pronto per iniziare.', 'Sono pronta per iniziare.', 28153),
(160473, 'itIT', 'Dovremo lavorare insieme per far sì che la Pergamena del Passaggio Sicuro funzioni.\n\nSei $gpronto:pronta;?', '', 28153),
(160472, 'itIT', 'Un po\'... cruento, non credi? Immagino che se volevamo attirare l\'attenzione di Dama Marefiero...', '', 28153),
(160471, 'itIT', 'Al fuoco!', 'Al fuoco!', 28153),
(160470, 'itIT', 'Chiamate i pompieri!', 'Chiamate i pompieri!', 28153),
(160469, 'itIT', 'Al fuoco! Al fuoco!', 'Al fuoco! Al fuoco!', 28153),
(160468, 'itIT', 'Non dev\'essere stato facile. Dobbiamo tenere gli occhi aperti.', 'Non dev\'essere stato facile. Dobbiamo tenere gli occhi aperti.', 28153),
(160467, 'itIT', 'Come credi abbiano fatto irruzione nelle Segrete?', 'Come credi abbiano fatto irruzione nelle Segrete?', 28153),
(160466, 'itIT', 'È rimasto forse qualcosa che quell\'arpia di Ventolesto non sarebbe disposta a provare?', 'È rimasto forse qualcosa che quell\'arpia di Ventolesto non sarebbe disposta a provare?', 28153),
(160465, 'itIT', 'Ho sentito che volevano assassinare il Re.', 'Ho sentito che volevano assassinare il Re.', 28153),
(160464, 'itIT', 'Non staranno mica cercando di attaccare la città con così pochi uomini?', 'Non staranno mica cercando di attaccare la città con così pochi uomini?', 28153),
(160463, 'itIT', 'Non posso permettere a nessuno di passare. Ordini del Re.', 'Non posso permettere a nessuno di passare. Ordini del Re.', 28153),
(160462, 'itIT', 'Non sarà fatto alcun male a voi o alle vostre famiglie. Tornate immediatamente nelle vostre case.', 'Non sarà fatto alcun male a voi o alle vostre famiglie. Tornate immediatamente nelle vostre case.', 28153),
(160461, 'itIT', 'Vi ho già detto tutto quello che so. Ora tornatevene a casa.', 'Vi ho già detto tutto quello che so. Ora tornatevene a casa.', 28153),
(160460, 'itIT', 'Ti prego, mia figlia vive nel Distretto Commerciale. Devo raggiungerla!', 'Ti prego, mia figlia vive nel Distretto Commerciale. Devo raggiungerla!', 28153),
(160459, 'itIT', 'Fatemi passare immediatamente! Esigo di parlare con il vostro superiore.', 'Fatemi passare immediatamente! Esigo di parlare con il vostro superiore.', 28153),
(160458, 'itIT', 'Cos\'è tutto questo chiasso? Avete idea di che ora è?', 'Cos\'è tutto questo chiasso? Avete idea di che ora è?', 28153),
(160457, 'itIT', 'Quanti ce ne sono? Siamo sotto attacco?', 'Quanti ce ne sono? Siamo sotto attacco?', 28153),
(160456, 'itIT', 'Credi che il Re sia in pericolo?', 'Credi che il Re sia in pericolo?', 28153),
(160455, 'itIT', 'Fai silenzio ora. Vai dentro e nasconditi come ti ho mostrato.', 'Fai silenzio ora. Vai dentro e nasconditi come ti ho mostrato.', 28153),
(160454, 'itIT', 'Ho paura...', 'Ho paura...', 28153),
(160453, 'itIT', 'Cosa sta succedendo? Perché il cancello è chiuso?', 'Cosa sta succedendo? Perché il cancello è chiuso?', 28153),
(160452, 'itIT', 'Non voglio guai, $R.', 'Non voglio guai, $R.', 28153),
(160451, 'itIT', 'Uh. È giusto che siano qui?', 'Uh. È giusto che siano qui?', 28153),
(160450, 'itIT', 'È questa la caduta di Roccavento? Ahah. Mi sono trovato un posto in prima fila!', 'È questa la caduta di Roccavento? Ahah. Mi sono trovata un posto in prima fila!', 28153),
(160449, 'itIT', 'Guardie! Guardie?!?', 'Guardie! Guardie?!?', 28153),
(160448, 'itIT', 'Stai indietro. Non ho intenzione di morire qui.', 'Stai indietro. Non ho intenzione di morire qui.', 28153),
(160447, 'itIT', 'Sì! Sei il mio biglietto di uscita da qui, $R!', 'Sì! Sei il mio biglietto di uscita da qui, $R!', 28153),
(160446, 'itIT', 'Ehi! Vieni qui e fammi uscire!', 'Ehi! Vieni qui e fammi uscire!', 28153),
(160445, 'itIT', 'Che succede? Cosa ci fa l\'Orda qui?!?', 'Che succede? Cosa ci fa l\'Orda qui?!?', 28153),
(160444, 'itIT', 'Il nostro amico Oculeth, un tempo una delle nostre guardie migliori, aprirà un portale per permettere a $n e Zelling di recuperare lo scettro.', '', 28153),
(160443, 'itIT', 'Le forze d\'élite dei Marefiero dovrebbero arrivare da un momento all\'altro per cercare di recuperare il corpo di Derek.', '', 28153),
(160442, 'itIT', 'Hannibal è il falco più veloce di tutta Kul Tiras.', '', 28153),
(160441, 'itIT', 'Un\'Unità di Smaltimento si apre, formando una Massa Mutata!', 'Un\'Unità di Smaltimento si apre, formando una Massa Mutata!', 28153),
(160440, 'itIT', 'Azeroth chiede a gran voce il tuo aiuto! Vieni a Silitus. C\'è qualcosa che devi vedere.', '', 28153),
(160439, 'itIT', 'Non è così che sarebbe dovuta andare. Dovevo vincere io!', '', 28153),
(160438, 'itIT', 'Centro d\'Allenamento per Mascotte da Combattimento di Smilzo. Mi piace come suona e ora sono un passo più vicino alla tua sconfitta!', '', 28153),
(160437, 'itIT', 'Dovrei diversificare le mie mascotte, ora che ci penso. Tre dello stesso tipo... Cosa mi era saltato in mente?!?', '', 28153),
(160436, 'itIT', 'Hanno un sacco di aculei e un aspetto crudele. Pensavi davvero di poter vincere?', '', 28153),
(160435, 'itIT', 'Questi piccoletti sono molto strani, ma non sono da sottovalutare. Sei $gsicuro:sicura; di voler combattere?', '', 28153),
(160434, 'itIT', '', 'Non me l\'aspettavo.', 28153),
(160433, 'itIT', '', 'Ti ho annientato!', 28153),
(160432, 'itIT', '', 'Questo proprio non me lo aspettavo. La prossima volta vincerò io sicuramente.', 28153),
(160431, 'itIT', '', 'Come ho detto prima, la mia squadra è chiaramente superiore.', 28153),
(160430, 'itIT', '', 'Prima di iniziare, volevo solo ricordarti di non prendertela troppo quando la mia squadra annienterà la tua.', 28153),
(160429, 'itIT', 'L\'odore del sangue nell\'acqua non farà che attirare altri squali.', '', 28153),
(160428, 'itIT', 'È ora di mangiare, ragazzi!', '', 28153),
(160427, 'itIT', 'Anche se mi hai battuto, mi toccherà restarmene qui per l\'eternità. Quantomeno oggi ho avuto una conversazione.', '', 28153),
(160426, 'itIT', 'Una persona contro uno squalo potrebbe anche essere uno scontro alla pari, ma contro tre? Sei folle!', '', 28153),
(160425, 'itIT', 'Se vuoi battere uno come me, ti servirà una barca più grossa per trasportare queste fuori di qui.', '', 28153),
(160424, 'itIT', '', 'La tua determinazione è ammirevole, ma l\'esito è già stato scritto.', 28153),
(160423, 'itIT', '', 'Tornatene da dove vieni!!', 28153),
(160422, 'itIT', '', 'Questo non doveva succedere... La profezia diceva diversamente.', 28153),
(160421, 'itIT', '', 'Dovrai allenarti di più prima di poter sfidare una maestra come me.', 28153),
(160420, 'itIT', '', 'Scommetto che le strane creature di quest\'isola daranno vita a una battaglia più unica che rara.', 28153),
(160419, 'itIT', '', 'Sei più utile come esca che come membro della mia squadra!', 28153),
(160418, 'itIT', '', 'A quanto pare stanotte dormirà con i pesci! Ahahah!', 28153),
(160417, 'itIT', '', 'Il mare è pieno di pesci, giusto? Forse questo non è il contesto giusto per quel detto, ora che ci penso...', 28153),
(160416, 'itIT', '', 'Non ho mai avuto dubbi.', 28153),
(160415, 'itIT', '', 'Le creature di mare più forti e resistenti combattono per me. Non hai alcuna possibilità.', 28153),
(160414, 'itIT', 'Ogni volta che alleno nuove api, è sempre la solita storia. Diventano grosse, forti e praticamente invincibili... poi pungono qualcosa e muoiono.', '', 28153),
(160413, 'itIT', 'Un punto per le api!', '', 28153),
(160412, 'itIT', 'No, le mie api! No!', '', 28153),
(160411, 'itIT', 'Le api sono chiaramente superiori. Questa ne è la prova.', '', 28153),
(160410, 'itIT', 'Ricorda solo che sei $gstato:stata; tu a chiedermelo.', '', 28153),
(160409, 'itIT', '', 'Quella era la mia preferita! È ora di togliersi i guanti di velluto! Preparati!', 28153),
(160408, 'itIT', '', 'Un punto per Fizzie!', 28153),
(160407, 'itIT', '', 'Ma le mie mascotte sono infuse d\'Azerite! Tutte le mascotte la adorano!', 28153),
(160406, 'itIT', '', 'Non posso dire di essere sorpresa, la mia squadra è chiaramente la migliore.', 28153),
(160405, 'itIT', '', 'Credi che le tue mascotte abbiano qualche possibilità contro la mia squadra infusa d\'Azerite? Ti piacerebbe!', 28153),
(160404, 'itIT', '', 'Ci stanno molte creature a Zuldazar, alcune piccole, altre enormi. Ho scelto di catturare e allenare le creature più piccole perché la nonna mia mi diceva sempre che è nella botte piccola che ci sta il vino buono.', 28153),
(160403, 'itIT', '', 'Troviamoci sul ponte inferiore quando hai finito. Troverò un modo per abbattere la barriera che protegge il Principe del Sangue Dreven.', 28153),
(160402, 'itIT', 'Il Divoratore Fetido ha |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t usato |cFFFF0000|Hspell:262370|h[Consumo Corruzione]|h|r! Uccidi i Corpuscoli della Corruzione non appena appaiono!', 'Il Divoratore Fetido ha |TInterface\\ICONS\\Ability_Creature_Poison_01.blp:20|t usato |cFFFF0000|Hspell:262370|h[Consumo Corruzione]|h|r! Uccidi i Corpuscoli della Corruzione non appena appaiono!', 28153),
(160401, 'itIT', 'Shandris ti aspetterà a bordo. Buona fortuna.', '', 28153),
(160400, 'itIT', 'Bel tiro! Ora raggiungiamo la Vento Cremisi.', '', 28153),
(160399, 'itIT', '', 'Aaaaaargh!', 28153),
(160398, 'itIT', '', 'Sì! Il sangue di G\'huun scorre nelle nostre vene!', 28153),
(160397, 'itIT', '', 'Sangue per il nostro padrone... La nostra carne, le nostre vite per G\'huun!', 28153),
(160396, 'itIT', 'Ci sono qua io, Alalesta. Nessun cannone dell\'Orda ci farà del male oggi.', '', 28153),
(160395, 'itIT', 'Oh, fantastico! Grazie, $gsignore:signora;!', 'Oh, fantastico! Grazie, $gsignore:signora;!', 28153),
(160394, 'itIT', 'Ci... ci hai portato delle altre caramelle? Più buone?', 'Ci... ci hai portato delle altre caramelle? Più buone?', 28153),
(160393, 'itIT', 'Ehi! Tu sei $gl\'ingordo:l\'ingorda; $R che ci ha rubato le caramelle!', 'Ehi! Tu sei $gl\'ingordo:l\'ingorda; $R che ci ha rubato le caramelle!', 28153),
(160392, 'itIT', '<Non è rimasta che qualche cartaccia del tuo assalto a questo scrigno... Qualche cartaccia e molta vergogna.>', '<Non è rimasta che qualche cartaccia del tuo assalto a questo scrigno... Qualche cartaccia e molta vergogna.>', 28153),
(160391, 'itIT', '<Metti delle caramelle più buone nello scrigno.>', '<Metti delle caramelle più buone nello scrigno.>', 28153),
(160390, 'itIT', 'Non vedo l\'ora di scoprire i segreti di Xibala. Questo posto suscita così tante domande!\n\nChi è Xibala? Cos\'è Xibala? Perché gli Zandalari hanno abbandonato questo posto? A cosa serve l\'Occhio di Xibala?\n\nSotto la guida dell\'Esaminatrice Tae\'shara, di certo scopriremo ogni cosa!', 'Non vedo l\'ora di scoprire i segreti di Xibala. Questo posto suscita così tante domande!\n\nChi è Xibala? Cos\'è Xibala? Perché gli Zandalari hanno abbandonato questo posto? A cosa serve l\'Occhio di Xibala?\n\nSotto la guida dell\'Esaminatrice Tae\'shara, di certo scopriremo ogni cosa!', 28153),
(160389, 'itIT', 'Credi che Astrandis potrebbe presentarmi al Capo Telemante Oculeth?\n\nHo sentito parlare così tanto di lui... Credi che mi farebbe un autografo sulla mia insegna di gilda?', 'Credi che Astrandis potrebbe presentarmi al Capo Telemante Oculeth?\n\nHo sentito parlare così tanto di lui... Credi che mi farebbe un autografo sulla mia insegna di gilda?', 28153),
(160388, 'itIT', 'Devo dargliene atto. Dopo aver passato un\'eternità in un luogo perfetto, tra soffici divani e vini, questi Nobili Oscuri si stanno adattando molto bene alla vita nel mondo esterno.\n\nSono anche riuscito a insegnare a uno di loro come usare una pala!', 'Devo dargliene atto. Dopo aver passato un\'eternità in un luogo perfetto, tra soffici divani e vini, questi Nobili Oscuri si stanno adattando molto bene alla vita nel mondo esterno.\n\nSono anche riuscito a insegnare a uno di loro come usare una pala!', 28153),
(160387, 'itIT', 'L\'Esaminatrice Tae\'shara è estremamente paziente. Una degna erede di suo padre, se mai dovesse rinunciare alla sua posizione.\n\nMi chiedo però se quell\'Astrandis non stia mettendo troppo a dura prova la sua incredibile tolleranza.', 'L\'Esaminatrice Tae\'shara è estremamente paziente. Una degna erede di suo padre, se mai dovesse rinunciare alla sua posizione.\n\nMi chiedo però se quell\'Astrandis non stia mettendo troppo a dura prova la sua incredibile tolleranza.', 28153),
(160386, 'itIT', 'Il Circolo del Reliquiario si è gettato a capofitto sull\'opportunità di scavare questo sito. Siamo fortunati che i Troll che vivono qui non abbiano detto nulla in contrario.', 'Il Circolo del Reliquiario si è gettato a capofitto sull\'opportunità di scavare questo sito. Siamo fortunati che i Troll che vivono qui non abbiano detto nulla in contrario.', 28153),
(160385, 'itIT', 'Ho offerto un piccone a un Nobile Oscuro e mi ha lanciato l\'occhiata più perplessa che abbia mai visto.\n\n\"A che serve?\", mi ha chiesto, come se non ne avesse davvero la più pallida idea.\n\nLa loro conoscenza magica è davvero impareggiabile, ma hanno ancora molto da imparare su come funziona il mondo. Per fortuna, noi Sin\'dorei abbiamo tutte le carte in regola per insegnarglielo.', 'Ho offerto un piccone a un Nobile Oscuro e mi ha lanciato l\'occhiata più perplessa che abbia mai visto.\n\n\"A che serve?\", mi ha chiesto, come se non ne avesse davvero la più pallida idea.\n\nLa loro conoscenza magica è davvero impareggiabile, ma hanno ancora molto da imparare su come funziona il mondo. Per fortuna, noi Sin\'dorei abbiamo tutte le carte in regola per insegnarglielo.', 28153),
(160384, 'itIT', 'I Nobili Oscuri sono stati di grande utilità per questa spedizione, ma non nel modo che mi aspettavo.\n\nÈ come se emanassero una certa aura di benessere quando viaggiano, il che è un miglioramento dalla solita aria irritata che hanno negli accampamenti.\n\n<Sorseggia da un calice di vino.>', 'I Nobili Oscuri sono stati di grande utilità per questa spedizione, ma non nel modo che mi aspettavo.\n\nÈ come se emanassero una certa aura di benessere quando viaggiano, il che è un miglioramento dalla solita aria irritata che hanno negli accampamenti.\n\n<Sorseggia da un calice di vino.>', 28153),
(160383, 'itIT', 'Non guardare, ma credo che quello Shal\'dorei stia tenendo il suo attrezzo per rilevamenti al contrario.', 'Non guardare, ma credo che quello Shal\'dorei stia tenendo il suo attrezzo per rilevamenti al contrario.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160382, 'itIT', 'Lo ammetto, non avevo idea di cosa stavo facendo quando ho accettato di visitare questa strana terra.\n\nFa più caldo di quanto mi aspettassi. Molto più caldo. Ma è anche un\'opportunità irripetibile per portare avanti la causa della Prima Arcanista e ingraziarci i nostri nuovi alleati.\n\nImmagino sia una buona ragione per stringere i denti e sopportare.\n\n<Fa un sorriso molto forzato.>', 'Lo ammetto, non avevo idea di cosa stavo facendo quando ho accettato di visitare questa strana terra.\n\nFa più caldo di quanto mi aspettassi. Molto più caldo. Ma è anche un\'opportunità irripetibile per portare avanti la causa della Prima Arcanista e ingraziarci i nostri nuovi alleati.\n\nImmagino sia una buona ragione per stringere i denti e sopportare.\n\n<Fa un sorriso molto forzato.>', 28153),
(160381, 'itIT', 'Spero che stiamo dando una buona impressione agli Zandalari. Sono stati così gentili... e riluttanti... a darci l\'opportunità di studiare questo sito.', 'Spero che stiamo dando una buona impressione agli Zandalari. Sono stati così gentili... e riluttanti... a darci l\'opportunità di studiare questo sito.', 28153),
(160380, 'itIT', 'Credi che i nostri alleati del Circolo del Reliquiario mi lasceranno usare uno di quei piccoli pennelli?', 'Credi che i nostri alleati del Circolo del Reliquiario mi lasceranno usare uno di quei piccoli pennelli?', 28153),
(160379, 'itIT', 'I nostri alleati Sin\'dorei mi hanno raccontato un sacco di storie sulle loro passate spedizioni. Percepisco un tema ricorrente nei loro continui incontri con la razza dei Nani.', 'I nostri alleati Sin\'dorei mi hanno raccontato un sacco di storie sulle loro passate spedizioni. Percepisco un tema ricorrente nei loro continui incontri con la razza dei Nani.', 28153),
(160378, 'itIT', 'Credi che i Troll ci permetterebbero di portare una di quelle creature dal collo lungo a Suramar? A Su\'esh piacerebbe davvero un animaletto da compagnia!\n\nForse dovresti chiedere!', 'Credi che i Troll ci permetterebbero di portare una di quelle creature dal collo lungo a Suramar?\n\nForse dovresti chiedere!', 28153),
(160377, 'itIT', '<Scaccia via una zanzara con le mani.>\n\nAh, cosa ci tocca sopportare per dimostrare il nostro valore all\'Orda! Le condizioni di lavoro qui sono spaventose!', '<Scaccia via una zanzara con le mani.>\n\nAh, cosa ci tocca sopportare per dimostrare il nostro valore all\'Orda! Le condizioni di lavoro qui sono spaventose!', 28153),
(160376, 'itIT', '<Si fa aria vigorosamente con le mani.>\n\nNon avevo mai apprezzato il clima di Suramar prima d\'ora. Sarà un sollievo tornare a casa una volta finiti gli scavi.', '<Si fa aria vigorosamente con le mani.>\n\nNon avevo mai apprezzato il clima di Suramar prima d\'ora. Sarà un sollievo tornare a casa una volta finiti gli scavi.', 28153),
(160375, 'itIT', 'Ho letto un sacco di cose sulle giungle nella nostra libreria, ma per qualche motivo si sono dimenticati di menzionare il caldo asfissiante!\n\nI vestiti mi si appiccicano alla pelle ed è pieno di insetti. Insetti!\n\nPerché mai uno dovrebbe scegliere volontariamente di vivere in un posto simile?', 'Ho letto un sacco di cose sulle giungle nella nostra libreria, ma per qualche motivo si sono dimenticati di menzionare il caldo asfissiante!\n\nI vestiti mi si appiccicano alla pelle ed è pieno di insetti. Insetti!\n\nPerché mai uno dovrebbe scegliere volontariamente di vivere in un posto simile?', 28153),
(160374, 'itIT', 'Oh, quei due. Nun fanno che bisticciare tra loro all\'interno del Gran Sigillo. Puoi trovarli sulla balconata sul lato orientale.\n\nLa presenza loro mi fa passare la voglia anche solo di avvicinarmi, ma devo dire che mi trovo del tutto d\'accordo col Tauren. Quasi del tutto.', 'Oh, quei due. Nun fanno che bisticciare tra loro all\'interno del Gran Sigillo. Puoi trovarli sulla balconata sul lato orientale.\n\nLa presenza loro mi fa passare la voglia anche solo di avvicinarmi, ma devo dire che mi trovo del tutto d\'accordo col Tauren. Quasi del tutto.', 28153),
(160373, 'itIT', 'Stai cercando Cringely e Ulla. Stanno avendo una discussione animata sulle politiche della Capoguerra. Naturalmente, è Cringely ad aver ragione, ma Ulla è testarda come poche.\n\nLi troverai all\'interno del Gran Sigillo, sulla balconata orientale che sovrasta la galleria.', 'Stai cercando Cringely e Ulla. Stanno avendo una discussione animata sulle politiche della Capoguerra. Naturalmente, è Cringely ad aver ragione, ma Ulla è testarda come poche.\n\nLi troverai all\'interno del Gran Sigillo, sulla balconata orientale che sovrasta la galleria.', 28153),
(160372, 'itIT', 'Merluzzo! Preparato e pronto da mangiare!', '', 28153),
(160371, 'itIT', 'La preda del giorno! Squalo fresco, arpionato in giornata!', '', 28153),
(160370, 'itIT', 'Accompagnateci oltre la tempesta.', '', 28153),
(160369, 'itIT', 'Guidateci attraverso le infide acque che ora sono il vostro regno.', '', 28153),
(160368, 'itIT', 'Varcate il velo e camminate sulla spiaggia.', '', 28153),
(160367, 'itIT', 'Anime perdute nel mare, tornate da noi.', '', 28153),
(160366, 'itIT', 'Siamo la luce che vi guida verso casa.', '', 28153),
(160365, 'itIT', 'Alziamo le nostre lanterne sulle acque oscure.', '', 28153),
(160364, 'itIT', 'Il loro suono vi riaccompagnerà a casa.', '', 28153),
(160363, 'itIT', 'Udite le nostre campane echeggiare tra le sacre onde.', '', 28153),
(160362, 'itIT', 'Su onde serene e correnti rapide, navigate.', '', 28153),
(160361, 'itIT', 'Con il sangue calmiamo i mari che vi hanno preso la vita.', '', 28153),
(160360, 'itIT', 'Abbandonate l\'abbraccio dell\'abisso per aiutare ancora una volta i vostri fratelli.', '', 28153),
(160359, 'itIT', 'Anime perdute delle profondità, noi vi invochiamo.', '', 28153),
(160358, 'itIT', 'Il vento e le correnti guideranno la nostra supplica.', '', 28153),
(160357, 'itIT', '', 'Fatto con il prosciutto migliore dei Regni Orientali! Direttamente da Malautunno!', 28153),
(160356, 'itIT', '', 'Salsicce! Appena insaccate provenienti da Drustvar e Roccavento!', 28153),
(160355, 'itIT', '', 'Non c\'è niente di meglio che sorseggiare una birra esotica mentre si passeggia tra le vie del mercato! O se la birra non fa per voi, ho portato anche un sacco di tè!', 28153),
(160354, 'itIT', '', 'Birra in vendita! Barili provenienti direttamente da Pandaria!', 28153),
(160353, 'itIT', 'Ehi, tu! Sì, tu! Ho qualcosa che potrebbe interessare a un tipo come te!', '', 28153),
(160352, 'itIT', 'La Capoguerra ci vuole svegli e organizzati, ora più che mai. Cos\'ha intenzione di sacrificare la tua gilda per la causa dell\'Orda?', '', 28153),
(160351, 'itIT', '', 'Cavoli freschi, coltivazione a chilometro zero!', 28153),
(160350, 'itIT', '', 'Verdure provenienti dalle fattorie di Sacraonda! Il miglior grano che possiate mai assaggiare!', 28153),
(160349, 'itIT', 'Non ho idea di dove si trovi la nave ora.', 'Non ho idea di dove si trovi la nave ora.', 28153),
(160348, 'itIT', 'L\'Implacabile dovrebbe aver appena lasciato il Porto di Roccavento.', 'L\'Implacabile dovrebbe aver appena lasciato il Porto di Roccavento.', 28153),
(160347, 'itIT', 'L\'Implacabile dovrebbe aver appena lasciato Boralus.', 'L\'Implacabile dovrebbe aver appena lasciato Boralus.', 28153),
(160346, 'itIT', 'Se mai avessi qualsiasi problema con le scarpe, io sarò sempre qui. Goditi questa rinnovata lucentezza!', '', 28153),
(160345, 'itIT', 'Lustrascarpe in arrivo!', '', 28153),
(160344, 'itIT', 'Sei $gnu professionista:na professionista;, vero? Bene, teniamo sempre bisogno di gente come te. Se stai cercando attrezzi per il lavoro tuo, troverai nu Tauren di nome Hanul Vento Rapido. Cercalo nella Sala dei Percorsi Antichi, che si trova sul lato orientale, dentro il Gran Sigillo.', 'Sei $gnu professionista:na professionista;, vero? Bene, teniamo sempre bisogno di gente come te. Se stai cercando attrezzi per il lavoro tuo, troverai nu Tauren di nome Hanul Vento Rapido. Cercalo nella Sala dei Percorsi Antichi, che si trova sul lato orientale, dentro il Gran Sigillo.', 28153),
(160343, 'itIT', 'Se stai cercando beni commerciali, ti consiglio di dirigerti all\'interno del Gran Sigillo. Una volta dentro, vai a est nella Sala dei Percorsi Antichi, dove troverai un Tauren di nome Hanul Vento Rapido. Dovrebbe avere tutto ciò che cerchi.', 'Se stai cercando beni commerciali, ti consiglio di dirigerti all\'interno del Gran Sigillo. Una volta dentro, vai a est nella Sala dei Percorsi Antichi, dove troverai un Tauren di nome Hanul Vento Rapido. Dovrebbe avere tutto ciò che cerchi.', 28153),
(160342, 'itIT', 'Beni generici? L\'Orda si è portata i suoi quand\'è arrivata accà. Parla con l\'Orchessa Araka nella Sala dei Percorsi Antichi. Ci sta na stanza sul lato orientale del Gran Sigillo. Tiene tutti i beni generici di cui hai bisogno.', 'Beni generici? L\'Orda si è portata i suoi quand\'è arrivata accà. Parla con l\'Orchessa Araka nella Sala dei Percorsi Antichi. Ci sta na stanza sul lato orientale del Gran Sigillo. Tiene tutti i beni generici di cui hai bisogno.', 28153),
(160341, 'itIT', 'Araka può aiutarti. Si trova nella Sala dei Percorsi Antichi, appena fuori dal lato orientale del Gran Sigillo.', 'Araka può aiutarti. Si trova nella Sala dei Percorsi Antichi, appena fuori dal lato orientale del Gran Sigillo.', 28153),
(160340, 'itIT', 'Vuoi creare una nuova gilda? Dovresti parlare con il Guardiano del Porto Finnson e Perry Charlton. Sono una coppia strana, ma ti sapranno dire cosa fare.\n\nCercali nell\'edificio che si trova all\'entrata che guarda la città nel porto vero e proprio.', 'Vuoi creare una nuova gilda? Dovresti parlare con il Guardiano del Porto Finnson e Perry Charlton. Sono una coppia strana, ma ti sapranno dire cosa fare.\n\nCercali nell\'edificio che si trova all\'entrata che guarda la città nel porto vero e proprio.', 28153),
(160339, 'itIT', 'Leila Stafford è semplicemente la migliore. Mi ha aiutato più di una volta con la mia piccola Morbidina quando era ammalata.\n\nLa troverai al piano superiore del Mercato di Ventosaldo, sul lato occidentale.', 'Leila Stafford è semplicemente la migliore. Mi ha aiutato più di una volta con la mia piccola Morbidina quando era ammalata.\n\nLa troverai al piano superiore del Mercato di Ventosaldo, sul lato occidentale.', 28153),
(160338, 'itIT', 'Avevamo un barbiere, ma è scomparso non molto tempo fa e nessuno sa cosa gli sia successo. È finito su tutti i giornali per quasi un giorno intero.\n\nOra c\'è uno Gnomo al suo posto. Ascolta, non voglio insinuare niente, ma se hai bisogno di un nuovo taglio o colore, puoi cercare Teri Piazzalucchetti al Presidio della Pesca.', 'Avevamo un barbiere, ma è scomparso non molto tempo fa e nessuno sa cosa gli sia successo. È finito su tutti i giornali per quasi un giorno intero.\n\nOra c\'è uno Gnomo al suo posto. Ascolta, non voglio insinuare niente, ma se hai bisogno di un nuovo taglio o colore, puoi cercare Teri Piazzalucchetti al Presidio della Pesca.', 28153),
(160337, 'itIT', '', 'La Fjarnskaggl è molto popolare tra i nobili qui. Ho finito le scorte in men che non si dica.\n\nTorna la prossima settimana, forse mi sarà arrivato un nuovo carico.', 28153),
(160336, 'itIT', 'Hai già acquistato i tuoi sigilli per questa settimana, smettila di farmi perdere tempo.\n\nDovrei averne altri disponibili la prossima.', '', 28153),
(160335, 'itIT', 'Henrick Wyther vende ogni genere di merce per dare supporto a professionisti come te. Puoi trovarlo al piano superiore del Mercato di Ventosaldo.\n\nÈ impossibile non notare il suo banchetto. È anche un patito di cospirazioni, quindi non ridere delle sue mappe o annotazioni. Prende quella roba molto sul serio... ed è un bravo ragazzo.', 'Henrick Wyther vende ogni genere di merce per dare supporto a professionisti come te. Puoi trovarlo al piano superiore del Mercato di Ventosaldo.\n\nÈ impossibile non notare il suo banchetto. È anche un patito di cospirazioni, quindi non ridere delle sue mappe o annotazioni. Prende quella roba molto sul serio... ed è un bravo ragazzo.', 28153),
(160334, 'itIT', 'Beni commerciali', 'Beni commerciali', 28153),
(160333, 'itIT', 'Non farmi nemmeno iniziare a parlare dell\'oro che ho speso in riparazioni. Per fortuna, l\'Ammiragliato ha il suo fabbro che si occupa della manutenzione dell\'equipaggiamento fornito da noi, ma per la tua roba personale, ti consiglio caldamente di rivolgerti a Patrick Markson. Sì, so che vende armi da fuoco, ma è bravo a riparare praticamente qualsiasi cosa.\n\nCerca il suo banchetto presso la fontana al piano inferiore del Mercato di Ventosaldo, in fondo alle scale che portano alla locanda.', 'Non farmi nemmeno iniziare a parlare dell\'oro che ho speso in riparazioni. Per fortuna, l\'Ammiragliato ha il suo fabbro che si occupa della manutenzione dell\'equipaggiamento fornito da noi, ma per la tua roba personale, ti consiglio caldamente di rivolgerti a Patrick Markson. Sì, so che vende armi da fuoco, ma è bravo a riparare praticamente qualsiasi cosa.\n\nCerca il suo banchetto presso la fontana al piano inferiore del Mercato di Ventosaldo, in fondo alle scale che portano alla locanda.', 28153),
(160332, 'itIT', 'Hai mai desiderato forzare la mano del destino? Magari per un particolare pezzo d\'armatura, un\'arma o un monile di grande potere?\n\nPer un giusto compenso, ti fornirò un sigillo capace di modificare il fato e fornirti un risultato aggiuntivo su un\'opportunità passata.\n\nQuando possiedi un sigillo, si attiverà una volta che avrai sconfitto un potente nemico in spedizioni o incursioni di elevata difficoltà.\n\nPresto metterò a disposizione dei Sigilli del Destino Bellico in cambio di oro, Risorse di Guerra o Contrassegni d\'Onore.\n\nAl momento, però, non ho nulla da offrirti.', '', 28153),
(160331, 'itIT', 'Offro vari metodi per acquistare un Sigillo del Destino Bellico.\n\nCosa preferisci sacrificare in cambio dell\'opportunità di cambiare il tuo destino?', '', 28153),
(160330, 'itIT', 'Possiedi già il numero massimo di sigilli che puoi portare.\n\nUsali prima di infastidirmi chiedendomene altri.', '', 28153),
(160329, 'itIT', 'Beni generici, capisco. Stai cercando Ninette Shoames, allora. Di solito la puoi trovare presso la fontana, sul lato meridionale del Mercato di Ventosaldo.', 'Beni generici, capisco. Stai cercando Ninette Shoames, allora. Di solito la puoi trovare presso la fontana, sul lato meridionale del Mercato di Ventosaldo.', 28153),
(160328, 'itIT', 'Questo molo ora serve come punto d\'attracco per l\'Implacabile.\n\nÈ stata selezionata dall\'Alleanza come mezzo di trasporto principale di diplomatici tra Roccavento e Kul Tiras. La nave ti porterà direttamente al Porto di Boralus.', 'Questo molo ora serve come punto d\'attracco per l\'Implacabile.\n\nÈ stata selezionata dall\'Alleanza come mezzo di trasporto principale di diplomatici tra Roccavento e Kul Tiras. La nave ti porterà direttamente al Porto di Boralus.', 28153),
(160327, 'itIT', 'Beni Generici', 'Beni Generici', 28153),
(160326, 'itIT', 'L\'Implacabile attracca regolarmente qui per trasportare la gente sul continente. Se vuoi raggiungere Roccavento, è la nave che cerchi. Attraccherà al porto della città.', 'L\'Implacabile attracca regolarmente qui per trasportare la gente sul continente. Se vuoi raggiungere Roccavento, è la nave che cerchi. Attraccherà al porto della città.', 28153),
(160325, 'itIT', 'Mercanti. Va bene. Che tipo di mercante stai cercando?', 'Mercanti. Va bene. Che tipo di mercante stai cercando?', 28153),
(160324, 'itIT', 'Un nuovo stile. Capisco. Ti sembrerà strano, ma dovresti recarti dal Mistico Distorcente Ezil. Lo so che assomiglia a una mummia ambulante, ma fidati, sa fare miracoli.\n\nHa aperto una bottega accanto alla Locanda di Porto Piccolo.', 'Un nuovo stile. Capisco. Ti sembrerà strano, ma dovresti recarti dal Mistico Distorcente Ezil. Lo so che assomiglia a una mummia ambulante, ma fidati, sa fare miracoli.\n\nHa aperto una bottega accanto alla Locanda di Porto Piccolo.', 28153),
(160323, 'itIT', 'Che tu stia cercando di imparare un nuovo stile di cucito o come suturare una ferita sanguinante, o magari anche solo come farti una nuova borsa... devi rivolgerti a Daniel Tessisale. Cercalo sul lato settentrionale del Mercato di Ventosaldo, al piano superiore.\n\nDaniel è un bravo ragazzo, anche se un po\' depresso. Mi ha ricucito le ferite più volte di quante ne vorrei ammettere, inoltre sembra amare davvero trasmettere le sue conoscenze agli altri.', 'Che tu stia cercando di imparare un nuovo stile di cucito o come suturare una ferita sanguinante, o magari anche solo come farti una nuova borsa... devi rivolgerti a Daniel Tessisale. Cercalo sul lato settentrionale del Mercato di Ventosaldo, al piano superiore.\n\nDaniel è un bravo ragazzo, anche se un po\' depresso. Mi ha ricucito le ferite più volte di quante ne vorrei ammettere, inoltre sembra amare davvero trasmettere le sue conoscenze agli altri.', 28153),
(160322, 'itIT', 'Sei $gappassionato:appassionata; di caccia grossa? Ho delle belle notizie per te, allora. Le creature di questa regione hanno la pelle più spessa che tu abbia mai visto. Qui a Kul Tiras abbiamo solo il meglio.\n\nSe vuoi imparare come muoverti, devi rivolgerti ai migliori. Camilla Cieloscuro è la persona giusta per te. Si trova al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 'Sei $gappassionato:appassionata; di caccia grossa? Ho delle belle notizie per te, allora. Le creature di questa regione hanno la pelle più spessa che tu abbia mai visto. Qui a Kul Tiras abbiamo solo il meglio.\n\nSe vuoi imparare come muoverti, devi rivolgerti ai migliori. Camilla Cieloscuro è la persona giusta per te. Si trova al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 28153),
(160321, 'itIT', 'Sicuro? Hai visto le cose che brulicano qui intorno?\n\nGrazie, ma preferisco tenermi le mie armi... arma... Be\', ci siamo capiti.', '', 28153),
(160320, 'itIT', 'Non serve brandire armi qui. È sicuro.', 'Non serve brandire armi qui. È sicuro.', 28153),
(160319, 'itIT', 'Sii $gpronto:pronta; a tutto.', '', 28153),
(160318, 'itIT', 'La battaglia incombe. Potrebbe farci comodo $guno:una; come te tra i nostri ranghi.', '', 28153),
(160317, 'itIT', 'Te lo leggo negli occhi. La tua mente è erosa dalla follia, ma forse c\'è qualche speranza.$b$bI saggi un tempo prosperavano qui, nel tentativo di combattere l\'oscurità. Costruirono cappelle, baluardi di fede e coraggio. Aprirono una taverna, per far tacere i sussurri sotto un mare di idromele. Ora non resta che polvere e macerie...$b$bDirigiti a nord-ovest e troverai l\'ultimo segno della loro presenza: un enorme idolo abissale. Trova l\'effige e potrai spazzare via gli orrori di questo posto. Fai attenzione: dovrai andare molto a fondo e il mare esige sempre un prezzo da pagare.', '', 28153),
(160316, 'itIT', 'Ho un problema. Puoi aiutarmi?', 'Ho un problema. Puoi aiutarmi?', 28153),
(160315, 'itIT', 'Riesci a sentirli? Le mura... si sgretolano. Stanno arrivando, un sussurro dopo l\'altro.', '', 28153),
(160314, 'itIT', 'Un tempo, queste rovine erano l\'invidia di tutta la valle.', '', 28153),
(160313, 'itIT', 'Devo ammettere che non ricordo neanche quando quella lettera è stata inviata...', '', 28153),
(160312, 'itIT', 'Ricorda, l\'eccessiva fiducia è un lento e insidioso veleno.', '', 28153),
(160311, 'itIT', 'Stai cercando oro? Platino? Argento della Tempesta? Se vuoi imparare le ultime tecniche di estrazione, dovresti rivolgerti a Myra Cabot. Ha un talento naturale, quando si tratta di fiutare una vena.\n\nSi trova sul lato settentrionale del Mercato di Ventosaldo, al piano superiore. Ricordati di me, se dovessi diventare $gricco:ricca;.', 'Stai cercando oro? Platino? Argento della Tempesta? Se vuoi imparare le ultime tecniche di estrazione, dovresti rivolgerti a Myra Cabot. Ha un talento naturale, quando si tratta di fiutare una vena.\n\nSi trova sul lato settentrionale del Mercato di Ventosaldo, al piano superiore. Ricordati di me, se dovessi diventare $gricco:ricca;.', 28153),
(160310, 'itIT', 'Bene, torneremo dopo per finirli.', '', 28153),
(160309, 'itIT', 'Non è la mia specialità, ma se stai cercando di migliorare le tue abilità in Conciatura, conosco la persona che fa per te. Si chiama Cassandra Brennor ed è una maga con ago e filo.\n\nDi solito la puoi trovare al lavoro insieme a Camilla Cieloscuro; condividono la stessa postazione al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 'Non è la mia specialità, ma se stai cercando di migliorare le tue abilità in Conciatura, conosco la persona che fa per te. Si chiama Cassandra Brennor ed è una maga con ago e filo.\n\nDi solito la puoi trovare al lavoro insieme a Camilla Cieloscuro; condividono la stessa postazione al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 28153),
(160308, 'itIT', 'Fammi sapere quando sei $gpronto:pronta; a iniziare il bombardamento.', '', 28153),
(160307, 'itIT', 'Samuel D. Colton III è la persona che stai cercando. È un miracolo che non si sia dato altri titoli onorifici. Il suo lavoro però è fantastico, gliene devo dare atto. Se stai cercando un istruttore, non esiste persona migliore di lui.\n\nLo troverai dietro le sue vetrine, al centro del piano superiore sul lato settentrionale del Mercato di Ventosaldo.', 'Samuel D. Colton III è la persona che stai cercando. È un miracolo che non si sia dato altri titoli onorifici. Il suo lavoro però è fantastico, gliene devo dare atto. Se stai cercando un istruttore, non esiste persona migliore di lui.\n\nLo troverai dietro le sue vetrine, al centro del piano superiore sul lato settentrionale del Mercato di Ventosaldo.', 28153),
(160306, 'itIT', 'Stai cercando Zooey Sporcaruote. Ha recentemente affittato un angolino sul lato settentrionale del Mercato di Ventosaldo, al piano superiore.\n\nÈ incredibile come si possa concentrare tanta conoscenza e potere in una creatura così piccola.', 'Stai cercando Zooey Sporcaruote. Ha recentemente affittato un angolino sul lato settentrionale del Mercato di Ventosaldo, al piano superiore.\n\nÈ incredibile come si possa concentrare tanta conoscenza e potere in una creatura così piccola.', 28153),
(160305, 'itIT', 'Se vogliamo avere qualche speranza di portare gli Zandalari nell\'Orda, dobbiamo occuparci gli uni degli altri.', '', 28153),
(160304, 'itIT', 'Ti piacciono i fiori? Anche a me. Hanno un profumo così buono... Be\', la maggior parte, almeno.\n\nSe sei alla ricerca del segreto su come coltivare al meglio la flora di questa parte del mondo, parla con Declan Senal. Lo troverai intento a occuparsi del suo giardino al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 'Ti piacciono i fiori? Anche a me. Hanno un profumo così buono... Be\', la maggior parte, almeno.\n\nSe sei alla ricerca del segreto su come coltivare al meglio la flora di questa parte del mondo, parla con Declan Senal. Lo troverai intento a occuparsi del suo giardino al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 28153),
(160303, 'itIT', 'Qualcuno sta proteggendo la Lamento della Banshee con qualche tipo di magia dei Saggi delle Maree!', '', 28153),
(160302, 'itIT', 'Alan Goyle ha il suo negozio di pesca al Mercato di Ventosaldo. È sempre lì, intento a pescare nel suo laghetto. Non chiedermi come faccia ad avere sempre i magazzini pieni. Immagino che i pesci cadano giù dalla cascata.\n\nC\'è un trucco per andare lassù: ti basterà trovare le scale tra gli istruttori di Sartoria e Oreficeria.', 'Alan Goyle ha il suo negozio di pesca al Mercato di Ventosaldo. È sempre lì, intento a pescare nel suo laghetto. Non chiedermi come faccia ad avere sempre i magazzini pieni. Immagino che i pesci cadano giù dalla cascata.\n\nC\'è un trucco per andare lassù: ti basterà trovare le scale tra gli istruttori di Sartoria e Oreficeria.', 28153),
(160301, 'itIT', 'Prendi i miei martelli, $p, e lanciali con tutta la forza che hai!', '', 28153),
(160300, 'itIT', 'Granmartello, concentrate l\'attenzione sulla Lamento della Banshee! Teneteli occupati!', '', 28153),
(160299, 'itIT', 'Sei $gun granatiere:una granatiera;, $gun cecchino:una cecchina; o $guno:una; di quei pazzi inventori?\n\nChiunque tu sia, Layla Chigliapiatta è la persona che cerchi. Puoi trovarla occupata ad armeggiare con le sue macchine al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 'Sei $gun granatiere:una granatiera;, $gun cecchino:una cecchina; o $guno:una; di quei pazzi inventori?\n\nChiunque tu sia, Layla Chigliapiatta è la persona che cerchi. Puoi trovarla occupata ad armeggiare con le sue macchine al piano superiore del Mercato di Ventosaldo, sul lato settentrionale.', 28153),
(160298, 'itIT', '', 'I Mag\'har... resisteranno...', 28153),
(160297, 'itIT', '', 'La tua fine è vicina!', 28153),
(160296, 'itIT', 'Questa inutile vittoria... non prova nulla...', '', 28153),
(160295, 'itIT', '', 'Tu cadrai!', 28153),
(160294, 'itIT', '', 'Guarda! Si ritirano!', 28153),
(160293, 'itIT', '', 'Ah-ahh! Prendete questo, vermi d\'acqua dolce!', 28153),
(160292, 'itIT', '', 'Lok\'tar ogar!', 28153),
(160291, 'itIT', '', 'Dranosh\'ek Mag\'har!', 28153),
(160290, 'itIT', 'Vi attenderò... nelle Terre Ammorbate...', '', 28153),
(160289, 'itIT', '', 'Non ci arrenderemo mai!', 28153),
(160288, 'itIT', 'La nostra battaglia... non è finita...', '', 28153),
(160287, 'itIT', '', 'Per i Mag\'har!', 28153),
(160286, 'itIT', 'Io... ritornerò...', '', 28153),
(160285, 'itIT', 'Sciocchi... Avete sconfitto solo un... ricettacolo...', '', 28153),
(160284, 'itIT', 'Credi di aver vinto? Guardati attorno... Ciò che cerchi non è qui.', '', 28153),
(160283, 'itIT', 'La tua ragazzina è nelle mie mani. Oh, sapessi come piange. La sua sofferenza sarà eterna!', '', 28153),
(160282, 'itIT', '', 'Se è questa la distruzione che l\'Azerite è in grado di causare, temo che nemmeno il grande cancello di Boralus sia in grado di resistere.', 28153),
(160281, 'itIT', '', 'Una tale devastazione... I Cancelli di Daelin non avevano speranze.', 28153),
(160280, 'itIT', '', 'Mira ai barili di polvere!', 28153),
(160279, 'itIT', 'Emily Chiarosole è la persona che cerchi. La troverai nella parte più alta del Mercato di Ventosaldo, sul lato settentrionale.\n\nMi ha incantato un paio di bracciali una volta. Non saprei raccomandarti qualcuno di più abile.', 'Emily Chiarosole è la persona che cerchi. La troverai nella parte più alta del Mercato di Ventosaldo, sul lato settentrionale.\n\nMi ha incantato un paio di bracciali una volta. Non saprei raccomandarti qualcuno di più abile.', 28153),
(160278, 'itIT', '', 'Le creature qui possono essere pericolose, ma io ho la pelle spessa e intendo catturarle tutte, fino all\'ultima. La mia collezione è appena iniziata, ma quelle che ho catturato sono già abbastanza letali. Ti va di sfidarmi?', 28153),
(160277, 'itIT', 'Qualcuno nella mia tana? Curioso.', '', 28153),
(160276, 'itIT', 'Quando l\'ultimo fuoco sarà acceso, la città saprà che siamo salvi! La ciurma mia tornerà a casa!', '', 28153),
(160275, 'itIT', 'È vulnerabile nel suo regno e farà qualsiasi cosa per impedire che tu ci metta piede.', '', 28153),
(160274, 'itIT', 'Ti auguro buona fortuna nel tuo viaggio, continentale. Procedi con cautela, poiché Gorak Tul ti terrà d\'occhio.', '', 28153),
(160273, 'itIT', 'La Radura Verdeggiante è un ottimo luogo per un avamposto nascosto. C\'è un sacco di Azerite e neanche un Troll nei paraggi! Cosa si può volere di più?', '', 28153),
(160272, 'itIT', '', 'Ormai siamo abituati agli insetti che svolazzano su queste terre. Alcuni sono innocui, altri molto pericolosi. Ho collezionato parecchie specie nel corso di molti, molti anni e siamo più che felici di intrattenere altri allenatori di mascotte con un bello scontro. Sei $ginteressato:interessata;?', 28153),
(160271, 'itIT', '', 'La prossima la colpiremo dall\'alto. Sei con me?', 28153),
(160270, 'itIT', '', 'Argh! Ci siamo avvicinati troppo...', 28153),
(160269, 'itIT', 'Dissotterramento', 'Dissotterramento', 28153),
(160268, 'itIT', 'Oh, stai cercando il \"Capitano\". Cerca il suo ristorante all\'aperto che si trova tra il recinto e la fossa del fabbro, al piano superiore del Mercato di Ventosaldo. Si trova sul lato settentrionale.\n\nDevi assolutamente provare il Fritto Misto di Palude! Solo a pensarci mi viene l\'acquolina in bocca.', 'Oh, stai cercando il \"Capitano\". Cerca il suo ristorante all\'aperto che si trova tra il recinto e la fossa del fabbro, al piano superiore del Mercato di Ventosaldo. Si trova sul lato settentrionale.\n\nDevi assolutamente provare il Fritto Misto di Palude! Solo a pensarci mi viene l\'acquolina in bocca.', 28153),
(160267, 'itIT', 'Se so dove si trova l\'Istruttore di Forgiatura? Ma certo che so dov\'è, sono una guardia, no?\n\nVai al piano superiore del Mercato di Ventosaldo. Sul lato settentrionale troverai una fossa, al cui interno lavora il fabbro più abile che io conosca, Grix \"Pugniferrei\" Barlow.', 'Se so dove si trova l\'Istruttore di Forgiatura? Ma certo che so dov\'è, sono una guardia, no?\n\nVai al piano superiore del Mercato di Ventosaldo. Sul lato settentrionale troverai una fossa, al cui interno lavora il fabbro più abile che io conosca, Grix \"Pugniferrei\" Barlow.', 28153),
(160266, 'itIT', 'Inizierò i preparativi. Ci rivedremo quando avrai trovato ciò che ci serve.', '', 28153),
(160265, 'itIT', 'C\'è mancato un po\' troppo poco per i miei gusti. Grazie per il salvataggio!', 'C\'è mancato un po\' troppo poco per i miei gusti. Grazie per il salvataggio!', 28153),
(160263, 'itIT', 'Supervisiono tutte le faccende burocratiche di gilde e compagnie commerciali qui nel porto. Come posso aiutarti?', '', 28153),
(160262, 'itIT', 'Stai scavando in cerca di tesori perduti? Come ti invidio. Hai già uno di quegli affascinanti dispositivi di rilevamento?\n\nJane Hudson è la persona che cerchi. Si trova al piano superiore del Mercato di Ventosaldo. Di solito è nella sua bottega, sul lato occidentale della terrazza vicino al recinto.', 'Stai scavando in cerca di tesori perduti? Come ti invidio. Hai già uno di quegli affascinanti dispositivi di rilevamento?\n\nJane Hudson è la persona che cerchi. Si trova al piano superiore del Mercato di Ventosaldo. Di solito è nella sua bottega, sul lato occidentale della terrazza vicino al recinto.', 28153),
(160261, 'itIT', '', 'Ci sei? Lancia!', 28153),
(160260, 'itIT', 'Un maestro di pozioni. Sì, ne conosco uno. Si chiama Elric Whalgrene. Puoi trovarlo al confine settentrionale del Mercato di Ventosaldo al piano superiore, di fronte alla fossa del fabbro.\n\nNon farti ingannare dalla mancanza di un cappello a punta e bastone, quel tizio è un Mago vero, molto potente e altrettanto strano. Voglio dire, bere una pozione per trasformarti in una nube? Proprio strano. Devo ammettere che adoro bere la sua Pozione del Piè Veloce, di tanto in tanto. Dà una bella carica.', 'Un maestro di pozioni. Sì, ne conosco uno. Si chiama Elric Whalgrene. Puoi trovarlo al confine settentrionale del Mercato di Ventosaldo al piano superiore, di fronte alla fossa del fabbro.\n\nNon farti ingannare dalla mancanza di un cappello a punta e bastone, quel tizio è un Mago vero, molto potente e altrettanto strano. Voglio dire, bere una pozione per trasformarti in una nube? Proprio strano. Devo ammettere che adoro bere la sua Pozione del Piè Veloce, di tanto in tanto. Dà una bella carica.', 28153),
(160259, 'itIT', 'Per far sì che la nostra terra guarisca, deve esserci un\'opportunità di redenzione. Per tutti noi.', '', 28153),
(160258, 'itIT', 'Chissà come si sarà sentita per le loro morti. Quant\'è forte il suo desiderio di espiazione?', '', 28153),
(160257, 'itIT', 'Dama Jaina si fece da parte quando suo padre e i molti altri morirono.', '', 28153),
(160256, 'itIT', 'Ancora oggi mi chiedo se avrei potuto fare di più. Il pensiero mi perseguita nel sonno.', '', 28153),
(160255, 'itIT', 'Erano ormai persi nella loro follia, ma provo ancora rimorso per le loro morti.', '', 28153),
(160254, 'itIT', 'Ho dovuto affrontare, persino uccidere, la mia stessa gente. È stata una scelta difficile, ma necessaria.', '', 28153),
(160253, 'itIT', 'Molti dei miei compaesani credono che Jaina Marefiero sia una traditrice. Alcuni si chiederanno perché io vi stia aiutando a risparmiarla.', '', 28153),
(160252, 'itIT', 'Sei $gun:una; professionista? Cerchi nuovi metodi di allenamento? Abbiamo tutto quel che ti serve. Questa è Boralus, non vi è posto migliore al mondo.', 'Sei $gun:una; professionista? Cerchi nuovi metodi di allenamento? Abbiamo tutto quel che ti serve. Questa è Boralus, non vi è posto migliore al mondo.', 28153),
(160251, 'itIT', 'Fate saltare in aria $gquel lurido:quella lurida; $PR!', '', 28153),
(160250, 'itIT', '', 'Vagando per queste dune ho trovato alcune delle specie di mascotte più spettacolari che abbia mai visto. Sopravvivono mangiando ciò che trovano, proprio come noi. La loro capacità di sopravvivenza elevata le rende particolarmente resistenti. Ti va di esaminare le mie scoperte?', 28153),
(160249, 'itIT', 'Non mangiarmi, Milden, sono tuo amico!', '', 28153),
(160248, 'itIT', 'Mangia solo la gente cattiva!', '', 28153),
(160247, 'itIT', 'Hanno cercato di spaventarlo, ma lui si è infuriato!', '', 28153),
(160246, 'itIT', 'Ha mangiato il signor Anderson!', '', 28153),
(160245, 'itIT', 'Fai in fretta!', 'Fai in fretta!', 28153),
(160244, 'itIT', 'Dovrai recuperare ciò che mi serve in fretta. C\'è una vita in gioco.', '', 28153),
(160242, 'itIT', 'Ma siamo ben lungi dal finire di epurare la nostra terra dalla corruzione.', '', 28153),
(160241, 'itIT', 'Fratelli e sorelle di buon cuore si sono uniti a me per cambiare le carte in tavola.', '', 28153),
(160240, 'itIT', 'Ser Sacraonda non c\'è più, ma l\'oscurità di cui fece parte permane ancora.', '', 28153),
(160239, 'itIT', 'Anche solo mettere piede sulle coste è come una condanna a morte.', '', 28153),
(160238, 'itIT', 'Noi Saggi delle Maree siamo gli unici che possono avvicinarci, ma solo perché rimaniamo in acqua.', '', 28153),
(160237, 'itIT', 'Non ho mai avuto il dispiacere di portare qualcuno a Fine del Destino.', '', 28153),
(160236, 'itIT', 'Mi spiace, non puoi entrare qui. Prendi ciò per cui sei $gvenuto:venuta; e vattene.', '', 28153),
(160235, 'itIT', 'Se Dama Jaina è stata condotta in quella costa maledetta, potrebbe non rimanerci molto tempo. Vieni con me.', '', 28153),
(160234, 'itIT', 'Ha fatto portare sua figlia a Fine del Destino? Per mille maree!', '', 28153),
(160233, 'itIT', 'Dama Katherine ha riconsiderato l\'ordine di esecuzione di sua figlia. Sappiamo che Jaina è stata portata a Fine del Destino. Ho bisogno di un passaggio fin lì.', 'Dama Katherine ha riconsiderato l\'ordine di esecuzione di sua figlia. Sappiamo che Jaina è stata portata a Fine del Destino. Ho bisogno di un passaggio fin lì.', 28153),
(160232, 'itIT', 'Il tempo scarseggia e dobbiamo fare in fretta se vogliamo salvare Jaina.', '', 28153),
(160230, 'itIT', 'La tua testa è perfetta per la mia prossima creazione!', '', 28153),
(160229, 'itIT', 'Uno dei miei lavori migliori. I pezzi si fondono tra loro in modo magnifico.', '', 28153),
(160228, 'itIT', 'Sono felice di rivederti. Che cosa ti riporta qui a Sacraonda?', '', 28153),
(160227, 'itIT', 'Dama Katherine vorrà certamente sapere cos\'hai trovato.', '', 28153),
(160226, 'itIT', '', 'È antico... e più terribile di quanto immagini...', 28153),
(160225, 'itIT', '', 'Sarai $gmio:mia;. Per sempre.', 28153),
(160224, 'itIT', '', 'Ciao, dolcezza. Ti va di ascoltare la mia canzone?', 28153),
(160223, 'itIT', 'Sei $guno stolto:una stolta;... a fidarti... proprio come noi.', '', 28153),
(160222, 'itIT', 'Non avrete quegli artefatti!', '', 28153),
(160221, 'itIT', 'Le spedizioni non possono tardare!', '', 28153),
(160220, 'itIT', 'Quali affari avresti con quel folle di uno Gnomo? Io starei alla larga da lui, se fossi in te.\n\nBe\', vedo che non riesco a dissuaderti. L\'individuo che cerchi si chiama Crenzo Spaccascintille e si trova al piano superiore del Mercato di Ventosaldo, sul lato orientale. Lo troverai impegnato a smanettare con la sua pila di cianfrusaglie. Buona fortuna.', 'Quali affari avresti con quel folle di uno Gnomo? Io starei alla larga da lui, se fossi in te.\n\nBe\', vedo che non riesco a dissuaderti. L\'individuo che cerchi si chiama Crenzo Spaccascintille e si trova al piano superiore del Mercato di Ventosaldo, sul lato orientale. Lo troverai impegnato a smanettare con la sua pila di cianfrusaglie. Buona fortuna.', 28153),
(160219, 'itIT', 'Lascia che te lo dica, il servizio di traghetti cittadino è una delle meraviglie del mondo. Non solo può portarti da un posto all\'altro di Boralus attraverso i suoi magnifici canali, ma anche in tutto il resto della Baia di Tiragarde.\n\nSe stai cercando un comodo trasporto, Will Melbourne è la persona che fa per te. Puoi trovarlo insieme a sua figlia Sally al livello del mare, sul lato meridionale del Mercato di Ventosaldo.', 'Lascia che te lo dica, il servizio di traghetti cittadino è una delle meraviglie del mondo. Non solo può portarti da un posto all\'altro di Boralus attraverso i suoi magnifici canali, ma anche in tutto il resto della Baia di Tiragarde.\n\nSe stai cercando un comodo trasporto, Will Melbourne è la persona che fa per te. Puoi trovarlo insieme a sua figlia Sally al livello del mare, sul lato meridionale del Mercato di Ventosaldo.', 28153),
(160218, 'itIT', 'Comandante del Traghetto', 'Comandante del Traghetto', 28153),
(160217, 'itIT', 'Ci sono un sacco di luoghi interessanti sparsi per tutta Boralus. Cosa potrebbe interessarti?', 'Ci sono un sacco di luoghi interessanti sparsi per tutta Boralus. Cosa potrebbe interessarti?', 28153),
(160216, 'itIT', 'Se stai cercando un posto dove riposarti, posso suggerirti la locanda di Porto Piccolo? La troverai al piano superiore, davanti alla fontana.\n\nWesley Rocciasalda è la persona che cerchi. Ti darà un bel letto comodo e, se per caso ha anche una pentola della sua leggendaria zuppa sul fuoco, non dimenticarti di assaggiarla!', 'Se stai cercando un posto dove riposarti, posso suggerirti la locanda di Porto Piccolo? La troverai al piano superiore, davanti alla fontana.\n\nWesley Rocciasalda è la persona che cerchi. Ti darà un bel letto comodo e, se per caso ha anche una pentola della sua leggendaria zuppa sul fuoco, non dimenticarti di assaggiarla!', 28153),
(160215, 'itIT', 'Wgullll naq xizzuoog.', '', 28153),
(160214, 'itIT', 'Wgul naq zzigla ouug anagih.', '', 28153),
(160213, 'itIT', 'Non me lo faccio ripetere due volte!', '', 28153),
(160212, 'itIT', 'Ti va di fare un viaggetto, eh? Sì, lo so. Conosco la sensazione di solcare le nubi verso terre lontane ed esotiche da un lato e l\'adrenalina di pericoli ignoti dall\'altro. La promessa di un dolce tesoro una volta sconfitto l\'avversario.\n\nNo? Vuoi... soltanto un passaggio in volo? Be\', perché non l\'hai detto subito! Dirigiti al piano superiore del lato occidentale del Mercato di Ventosaldo. Lì troverai Joan Weber, vicino al nido dei grifoni.', 'Ti va di fare un viaggetto, eh? Sì, lo so. Conosco la sensazione di solcare le nubi verso terre lontane ed esotiche da un lato e l\'adrenalina di pericoli ignoti dall\'altro. La promessa di un dolce tesoro una volta sconfitto l\'avversario.\n\nNo? Vuoi... soltanto un passaggio in volo? Be\', perché non l\'hai detto subito! Dirigiti al piano superiore del lato occidentale del Mercato di Ventosaldo. Lì troverai Joan Weber, vicino al nido dei grifoni.', 28153),
(160211, 'itIT', '', 'Mo\' vai.', 28153),
(160210, 'itIT', '', 'E tu, Voce dell\'Orda. Deciderò che fare di te a tempo debito.', 28153),
(160209, 'itIT', '', 'Tu, piccirillo verde, nun sei più il benvenuto al Kraal delle Bestie da Guerra. Vattene!', 28153),
(160208, 'itIT', '', 'Bene. Chel vudù innaturale è scomparso.', 28153),
(160207, 'itIT', '', 'Questo non era... nel mio contratto...', 28153),
(160206, 'itIT', '', 'Vi state introducendo nella proprietà della Compagnia dei Bracescura!', 28153),
(160205, 'itIT', '<Il Cornofurente Giovane grugnisce e crolla a terra.>', '', 28153),
(160204, 'itIT', '<Il Cornofurente Giovane si tira indietro una volta sentito il gusto.>', '', 28153),
(160203, 'itIT', '', 'Serve una scialuppa per raggiungere la prossima nave.', 28153),
(160202, 'itIT', 'Non chiedermi come faccio a saperlo, ma lo so. Se vuoi entrare in buoni rapporti con quel popolo misterioso di tartarughe, devi parlare con il loro emissario, il Collezionista Kojo.\n\nDove potrebbe trovarsi? È questa la brutta notizia. Si trova nel bel mezzo della Valle dei Sacraonda, in un posto che chiamano Veduta dei Cercatori. Mi spiace, ma ti toccherà andare da $gsolo:sola; fin lì. Dal tuo sguardo, però, deduco che hai già in mente un modo per farlo.', 'Non chiedermi come faccio a saperlo, ma lo so. Se vuoi entrare in buoni rapporti con quel popolo misterioso di tartarughe, devi parlare con il loro emissario, il Collezionista Kojo.\n\nDove potrebbe trovarsi? È questa la brutta notizia. Si trova nel bel mezzo della Valle dei Sacraonda, in un posto che chiamano Veduta dei Cercatori. Mi spiace, ma ti toccherà andare da $gsolo:sola; fin lì. Dal tuo sguardo, però, deduco che hai già in mente un modo per farlo.', 28153),
(160201, 'itIT', 'È ora d\'impugnare il martello!', '', 28153),
(160200, 'itIT', 'Martelli e grifoni, un\'accoppiata imbattibile!', '', 28153),
(160199, 'itIT', '', 'Ora! Lanciala!', 28153),
(160198, 'itIT', 'Stai entrando in confidenza con l\'Ammiragliato, eh? Buon per te.\n\nSì, so dove si trova. Stai cercando l\'Approvvigionatrice Fray, nell\'Ufficio del Maestro del Porto. È lì dentro in mezzo agli altri parrucconi.', 'Stai entrando in confidenza con l\'Ammiragliato, eh? Buon per te.\n\nSì, so dove si trova. Stai cercando l\'Approvvigionatrice Fray, nell\'Ufficio del Maestro del Porto. È lì dentro in mezzo agli altri parrucconi.', 28153),
(160197, 'itIT', 'Emissaria dell\'Ammiragliato dei Marefiero', 'Emissaria dell\'Ammiragliato dei Marefiero', 28153),
(160196, 'itIT', 'Emissari, eh? Quale stai cercando?', 'Emissari, eh? Quale stai cercando?', 28153),
(160195, 'itIT', 'La banca, sì. Puoi trovare ciò che cerchi all\'angolo nordoccidentale della città, sul lato orientale del piano inferiore del distretto del Mercato di Ventosaldo.\n\nMi hai fatto ricordare che devo andare a controllare il mio conto una volta finito il turno. Purtroppo non offrono assicurazioni in caso di conti scoperti.', 'La banca, sì. Puoi trovare ciò che cerchi all\'angolo nordoccidentale della città, sul lato orientale del piano inferiore del distretto del Mercato di Ventosaldo.\n\nMi hai fatto ricordare che devo andare a controllare il mio conto una volta finito il turno. Purtroppo non offrono assicurazioni in caso di conti scoperti.', 28153),
(160194, 'itIT', 'Oh, salve, $C. Che succede?', '', 28153),
(160193, 'itIT', 'Andiamo!', 'Andiamo!', 28153),
(160192, 'itIT', 'Perfetto. Vediamo...\n\n<Hobart scorre le pagine zuppe di un manuale.>\n\nLe regole dalla tre alla diciassette sono noiose e poco importanti. $gPronto:Pronta; ad andare?', '', 28153),
(160191, 'itIT', 'Non lasciare la luce frontale accesa troppo a lungo. Ricevuto.', 'Non lasciare la luce frontale accesa troppo a lungo. Ricevuto.', 28153),
(160190, 'itIT', 'Bene. Seconda regola: NON LASCIARE LA LUCE FRONTALE ACCESA.\n\nNon scherzo. Non lasciare la tua lampadina frontale accesa per più di... non so... venti secondi o giù di lì. A meno che tu non voglia essere $gdivorato:divorata; dagli squali. Se vedi uno squalo, spegni tutto. Chiaro?', '', 28153),
(160189, 'itIT', 'Non togliere mai l\'elmetto. Chiaro.', 'Non togliere mai l\'elmetto. Chiaro.', 28153),
(160188, 'itIT', 'Ottimo! Prima regola: tieni indossato l\'elmetto in ogni momento.\n\nNon c\'è scusa che tenga. La pressione là sotto ti schiaccerebbe immediatamente il cranio. Inoltre, userò un auricolare immune alla statica per comunicare con te durante la missione. È chiaro?', '', 28153),
(160187, 'itIT', 'Sì, sto ascoltando.', 'Sì, sto ascoltando.', 28153),
(160186, 'itIT', 'Ahahah! $gIl nostro sommozzatore:La nostra sommozzatrice; è qui!\n\nIl tuo tempismo è perfetto! Ho appena finito di rappezzare l\'ultimo buco nel tubo dell\'aria.\n\nCi sono una manciata di regole che dovresti conoscere, prima di procedere. Mi stai ascoltando?', '', 28153),
(160185, 'itIT', '', 'Io chiuderei la bocca se fossi in te.', 28153),
(160184, 'itIT', 'Non possiamo discuterne? Voglio dire, gli effetti collaterali sono piuttosto blandi...', '', 28153),
(160183, 'itIT', 'Oh... sei TU. Questa sì che è una vera delizia!', '', 28153),
(160182, 'itIT', '', 'Come hanno potuto fare tutto questo?', 28153),
(160181, 'itIT', 'Oh! Ehi, ehi, ehi! Che ne dici di mettere giù quelle cose appuntite?!?', '', 28153),
(160180, 'itIT', '', 'Dobbiamo trovare un modo per resistere.', 28153),
(160179, 'itIT', '', 'Spiegati!', 28153),
(160178, 'itIT', '', 'Io attenderò nell\'ombra, $n. Se dovessi aver bisogno di me, non esitare a chiamare.', 28153),
(160177, 'itIT', '', 'Se vuoi un consiglio, stai alla larga dai pozzi di energia magica. Non solo ne diverrai dipendente, ma ti trasformerai anche in qualche... sottospecie di Elfo.', 28153),
(160176, 'itIT', '', 'No, NON mi piacciono le bende. Be\'... forse un pochino.', 28153),
(160175, 'itIT', '', 'Mi piaci. Non è che per caso hai un fratello gemello?', 28153),
(160174, 'itIT', '', 'Puoi provare a fermarmi mentre cerco di portarlo via e morire, o rimanere qui in ginocchio, nella polvere, vivo.', 28153),
(160173, 'itIT', '', 'Re Anduin mi ha dato una Pietra del Ritorno per Roccavento. Là curerò le ferite del mio amato... e aiuterò la mia gente a trovare tregua da questa follia.', 28153),
(160172, 'itIT', 'Andiamocene da qui.', 'Andiamocene da qui.', 28153),
(160171, 'itIT', 'Le Guardie d\'Onore penseranno a sistemare questo caos. Sei $gpronto:pronta;?', '', 28153),
(160170, 'itIT', '', 'Tenersi pronti.', 28153),
(160169, 'itIT', '', 'Vieni qui!', 28153),
(160168, 'itIT', '', 'Attenzione!', 28153),
(160167, 'itIT', '|cFF0000FF(Missione)|r Portaci al relitto del Maresciallo Valentine, al largo del Grande Mare.', '|cFF0000FF(Missione)|r Portaci al relitto del Maresciallo Valentine, al largo del Grande Mare.', 28153),
(160166, 'itIT', '', 'Da questa parte.', 28153),
(160165, 'itIT', '$gBentrovato, viaggiatore:Bentrovata, viaggiatrice;. Come posso aiutarti oggi?', '$gBentrovato, viaggiatore:Bentrovata, viaggiatrice;. Come posso aiutarti oggi?', 28153),
(160164, 'itIT', '', 'Da questa parte!', 28153),
(160163, 'itIT', '', 'Nella sua luce, ogni verità è rivelata.', 28153),
(160162, 'itIT', 'L\'Azerite... chesto nun è... chello che Zul aveva promesso...', '', 28153),
(160161, 'itIT', 'Li sforzi tuoi sono inutili! I poteri dell\'Azerite scorrono attraverso me!', '', 28153),
(160160, 'itIT', 'Ripiegate! Li riprenderemo dall\'altra parte!', 'Ripiegate! Li riprenderemo dall\'altra parte!', 28153),
(160159, 'itIT', 'Ti copriamo noi, $p!', '', 28153),
(160158, 'itIT', 'Vorrei commerciare.', 'Vorrei commerciare.', 28153),
(160157, 'itIT', 'Torniamo al portale.', '', 28153),
(160156, 'itIT', '', 'È un onore servire Elune.', 28153),
(160155, 'itIT', '', 'Parlo a nome della mia gente.', 28153),
(160154, 'itIT', '', 'I nemici conosceranno la nostra furia.', 28153),
(160153, 'itIT', 'Hai il cuore di tua madre.', '', 28153),
(160152, 'itIT', 'Credo che nessuno dovrebbe perdere la propria casa. Non se la cosa li fa sentire così.', '', 28153),
(160151, 'itIT', 'Mamma ne ha parlato ogni tanto. Credo... l\'abbia fatta piangere.', '', 28153),
(160150, 'itIT', '', 'I Kaldorei resisteranno.', 28153),
(160149, 'itIT', 'Non eravamo... noi stessi. È difficile da spiegare, ragazzo.', '', 28153),
(160148, 'itIT', 'Ha reso tutti tristi?', '', 28153),
(160147, 'itIT', 'È stato molto tempo fa.', '', 28153),
(160146, 'itIT', 'Mi hai detto che noi Orchi una volta abbiamo perso la nostra casa.', '', 28153),
(160145, 'itIT', '', 'C\'è un tempo per essere pazienti... e uno per agire.', 28153),
(160144, 'itIT', 'Perché?', '', 28153),
(160143, 'itIT', 'Mi spiace che gli Elfi abbiano perso il loro albero.', '', 28153),
(160142, 'itIT', 'E la tua grazia riporterò ai poteri del profondo!', '', 28153),
(160141, 'itIT', 'Concedimi di eliminare i nemici del mondo...', '', 28153),
(160140, 'itIT', 'Ciò di cui noi non osiamo abusare.', '', 28153),
(160139, 'itIT', '', 'Combatteremo per proteggere il nostro futuro.', 28153),
(160138, 'itIT', 'Ma il tuo potere ci permetterà di sfruttare...', '', 28153),
(160137, 'itIT', '', 'Ascolta la voce di Elune.', 28153),
(160136, 'itIT', 'Lo vedremo, figlio mio. Lo vedremo.', '', 28153),
(160135, 'itIT', 'Credi che questa guerra cambierà l\'Orda?', '', 28153),
(160134, 'itIT', 'Gli oceani avran vita anche in tempi distanti.', '', 28153),
(160133, 'itIT', 'Le guerre non cambiano mai. Solo i guerrieri lo fanno.', '', 28153),
(160132, 'itIT', 'Questa è una guerra brutta? Voglio dire... peggiore delle altre?', '', 28153),
(160131, 'itIT', 'Maree vorticose, maree vincolanti...', '', 28153),
(160130, 'itIT', 'Che c\'è?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(160129, 'itIT', 'Padre?', '', 28153),
(160128, 'itIT', '', 'Il Monte Mugamba è un posto selvaggio e spietato, difeso da una tribù di gorilla giganti e circondato da rupi pericolose. Dubito che l\'Orda verrà a cercarci qui.', 28153),
(160127, 'itIT', '', 'Quando desideri tornare alla Rivafosca del presente, devi solo chiedermelo.', 28153),
(160126, 'itIT', 'Lo farò, padre.', '', 28153),
(160125, 'itIT', 'Ricordatelo sempre, figlio mio.', '', 28153),
(160124, 'itIT', 'La guerra è una prova d\'onore. Una volta perso, non è facile riconquistarlo.', '', 28153),
(160123, 'itIT', 'La guerra tira fuori sempre il peggio dalle persone.', '', 28153),
(160122, 'itIT', 'Ho sentito altri ragazzi parlare di guerra. L\'Orda... ha fatto qualcosa di brutto?', '', 28153),
(160121, 'itIT', 'Sei silenzioso, molto più del solito.', '', 28153),
(160120, 'itIT', 'Sì, padre?', '', 28153),
(160119, 'itIT', 'Figlio mio.', '', 28153),
(160118, 'itIT', 'Questa terra è piena di meraviglie e creature interessanti. Proprio come i nostri difensori del tempio si vantano delle proprie capacità in battaglia, anch\'io posso dire di aver allenato le mie mascotte per mettere in risalto al meglio le loro qualità. Ti va di sfidarle?', '', 28153),
(160117, 'itIT', 'Puoi mostrarmi com\'era il mondo prima che Teldrassil bruciasse?', 'Puoi mostrarmi com\'era il mondo prima che Teldrassil bruciasse?', 28153),
(160116, 'itIT', 'Aspetta... era una battuta sul mio peso? Guarda che stavo trasportando una cassa molto importante.', '', 28153),
(160115, 'itIT', 'È fatta. Prendi lo scettro e andiamocene da qui!', '', 28153),
(160114, 'itIT', 'Vieni via da lì!', '', 28153),
(160113, 'itIT', '', 'Be\', potevi buttare quel vecchio cappotto rattoppato, Flynn.', 28153),
(160112, 'itIT', 'Blasfemia!', '', 28153),
(160111, 'itIT', 'Va bene, va bene. Prenderemo del pesce per l\'uccellino e la faremo riposare un po\' prima di tornare.', '', 28153),
(160110, 'itIT', '', 'Non voglio che la mia piccola si stanchi troppo e oggi ha già trasportato un bel po\' di carichi.', 28153),
(160109, 'itIT', '', 'Torneremo in città, ma prima Cuorventoso deve riposarsi un po\'.', 28153),
(160108, 'itIT', 'Fai spazio, Taelia. Questa volta lo cavalcherò su una vera sella.', '', 28153),
(160107, 'itIT', 'Bene. Mentre farai visita a Tol Dagor, noi dovremmo portare questa cassa a Boralus.', '', 28153),
(160106, 'itIT', 'Sei fin troppo gentile per chesto mondo, $n. Cosa stavo dicendo? Ah, sì. La nostra fuga senza speranze.', '', 28153),
(160105, 'itIT', 'Molto meglio assai. Dov\'ero rimasto...', '', 28153),
(160104, 'itIT', 'Ah, ora mi sento meglio.', '', 28153),
(160103, 'itIT', 'Nooo! Nun... di nuovo...', '', 28153),
(160102, 'itIT', 'Sento la linfa vitale tornare alla forma mia! Devo avere più potere!', '', 28153),
(160101, 'itIT', 'Sfortunatamente, la nave è attualmente in riparazione. Il suo impareggiabile stato di servizio potrà anche essere compromesso, ma sono qui per offrirti altri mezzi per raggiungere la destinazione.\n\nUn semplice portale forse non sarà proprio come la carezza di una dolce brezza marina tra i capelli, ma ti permetterà di continuare i tuoi affari senza impedimenti.\n\nUsa questo portale ogni qualvolta tu ne abbia bisogno. Sono al tuo servizio.', 'Sfortunatamente, la nave è attualmente in riparazione. Il suo impareggiabile stato di servizio potrà anche essere compromesso, ma sono qui per offrirti altri mezzi per raggiungere la destinazione.\n\nUn semplice portale forse non sarà proprio come la carezza di una dolce brezza marina tra i capelli, ma ti permetterà di continuare i tuoi affari senza impedimenti.\n\nUsa questo portale ogni qualvolta tu ne abbia bisogno. Sono al tuo servizio.', 28153),
(160100, 'itIT', 'Bleah!', 'Bleah!', 28153),
(160099, 'itIT', 'Sbudellerò chiunque abbia messo chesta cosa accà!', 'Sbudellerò chiunque abbia messo chesta cosa accà!', 28153),
(160098, 'itIT', 'Nun di nuovo!', 'Nun di nuovo!', 28153),
(160097, 'itIT', 'Chi ha messo chesta cosa accà?!?', 'Chi ha messo chesta cosa accà?!?', 28153),
(160096, 'itIT', '', 'Portoponte è poco più avanti! Atterriamo lì!', 28153),
(160095, 'itIT', 'Thros si risveglia!', '', 28153),
(160094, 'itIT', 'Lo sai che non puoi sconfiggermi, Ulfar. Ma se sei davvero in cerca di un combattimento, allora lo avrai!', '', 28153),
(160093, 'itIT', 'Il potere... mio...', 'Il potere... mio...', 28153),
(160092, 'itIT', 'Potere... più grande di quanto io abbia mai visto! Devo averne di più!', 'Potere... più grande di quanto io abbia mai visto! Devo averne di più!', 28153),
(160091, 'itIT', 'Accà troverai la nave che collega il Porto di Zandalar alle Isole dell\'Eco.\n\nÈ lì che stai andando?', '', 28153),
(160090, 'itIT', '', 'Queste andranno benissimo. Lasciamo la nave e vediamo come funzionano!', 28153),
(160089, 'itIT', 'Occupati di questa seccatura, $n.', '', 28153),
(160088, 'itIT', 'Stai insultando il Loa mio! Ti strapperò la bocca dalla faccia!', 'Stai insultando il Loa mio! Ti strapperò la bocca dalla faccia!', 28153),
(160087, 'itIT', 'Ti insegnerò io a nun rispettare il Loa mio!', 'Ti insegnerò io a nun rispettare il Loa mio!', 28153),
(160086, 'itIT', 'Pagherai per chest\'insulto!', 'Pagherai per chest\'insulto!', 28153),
(160085, 'itIT', 'Perché mai dovresti farlo?', 'Perché mai dovresti farlo?', 28153),
(160084, 'itIT', 'In nome di tutti i Loa, cosa credi di fare?', 'In nome di tutti i Loa, cosa credi di fare?', 28153),
(160083, 'itIT', 'Smettila!', 'Smettila!', 28153),
(160082, 'itIT', 'Andiamo.', 'Andiamo.', 28153),
(160081, 'itIT', 'Sembra che abbiamo compagnia. Ti va di aiutarmi a dar loro il benvenuto?', '', 28153),
(160080, 'itIT', 'Katherine non si fermerà davanti a nulla per riavere il corpo di suo figlio.\n\nSfrutteremo la sua emotività a nostro vantaggio per avere la meglio sulla sua flotta.', '', 28153),
(160079, 'itIT', 'Un altro piano sgangherato dell\'Alleanza sventato. Credo sia doveroso farti le mie congratulazioni.', '', 28153),
(160078, 'itIT', 'Anche l\'Alleanza ha messo assieme una macchina da guerra alimentata ad Azerite. Se è potente anche solo la metà della nostra, va distrutta a ogni costo!', '', 28153),
(160077, 'itIT', 'Ecco perché si chiama \"Urlo della Rovina\". Ben fatto!', '', 28153),
(160076, 'itIT', 'Le forze dell\'Orda hanno assemblato un\'altra macchina da guerra alimentata ad Azerite. Distruggila prima che la usino per decimare Stromgarde!', '', 28153),
(160075, 'itIT', '', 'Combatteremo il fuoco col fuoco. Cerchiamo un po\' di quelle bombe d\'Azerite in una delle loro navi.', 28153),
(160074, 'itIT', '', 'Mi assicurerò che sia fatta giustizia. Prima con questi pirati, poi con la Compagnia dei Bracescura.', 28153),
(160073, 'itIT', '', 'Tieni duro, Flynn. Vedi... di non morire.', 28153),
(160072, 'itIT', 'La nostra posizione sopra la Strada Dorata ci dà un ottimo vantaggio per tenere sotto controllo il traffico nemico da e verso la capitale Zandalari.', '', 28153),
(160071, 'itIT', 'Posizionamento Esca', 'Posizionamento Esca', 28153),
(160070, 'itIT', 'Così sia. Recupererò il corpo di Derek passando sul tuo cadavere.', '', 28153),
(160069, 'itIT', 'Ma francamente, puoi farci quello che vuoi con Valentine. Non ha alcun valore per noi.', '', 28153),
(160068, 'itIT', 'Ah, caro mio. Questa è una tattica che potrebbe funzionare con qualcun altro...', '', 28153),
(160067, 'itIT', 'Consegnaci Derek Marefiero e potrai riavere il tuo amico.', '', 28153),
(160066, 'itIT', 'Inversione', 'Inversione', 28153),
(160065, 'itIT', 'Quando ho sentito i Troll parlare delle ombre, pensavo intendessero delle vere ombre. Non immaginavo fossero così portati per le metafore.', 'Quando ho sentito i Troll parlare delle ombre, pensavo intendessero delle vere ombre. Non immaginavo fossero così portati per le metafore.', 28153),
(160064, 'itIT', 'Sai di cos\'ha bisogno questo posto? Un bel po\' di melma verde.', 'Sai di cos\'ha bisogno questo posto? Un bel po\' di melma verde.', 28153),
(160063, 'itIT', 'Intollerabile! L\'acqua qui è troppo blu per i miei gusti.', 'Intollerabile! L\'acqua qui è troppo blu per i miei gusti.', 28153),
(160062, 'itIT', 'Sai, credo di aver bisogno anch\'io di un nuovo stile. La persona che cerchi è il Mistico Distorcente Hayri, vicino ai moli.\n\nPer raggiungerlo, procedi verso il Gran Bazar, che si trova su una terrazza che sovrasta il porto. Gestisce un posto chiamato Mercantile del Maelstrom, sul lato orientale.', 'Sai, credo di aver bisogno anch\'io di un nuovo stile. La persona che cerchi è il Mistico Distorcente Hayri, vicino ai moli.\n\nPer raggiungerlo, procedi verso il Gran Bazar, che si trova su una terrazza che sovrasta il porto. Gestisce un posto chiamato Mercantile del Maelstrom, sul lato orientale.', 28153),
(160061, 'itIT', 'Di certo nessuno noterà qualche pezzo di corpo mancante dal campo di battaglia.', 'Di certo nessuno noterà qualche pezzo di corpo mancante dal campo di battaglia.', 28153),
(160060, 'itIT', 'Stai accà per rivoluzionare l\'aspetto tuo? Ci sta n\'Etereo che chiamano Mistico Distorcente Hayri giù al porto.\n\nRaggiungi il Gran Bazar, sulla terrazza che sovrasta il porto; lo troverai in nu posto chiamato Mercantile del Maelstrom, sul lato orientale.', 'Stai accà per rivoluzionare l\'aspetto tuo? Ci sta n\'Etereo che chiamano Mistico Distorcente Hayri giù al porto.\n\nRaggiungi il Gran Bazar, sulla terrazza che sovrasta il porto; lo troverai in nu posto chiamato Mercantile del Maelstrom, sul lato orientale.', 28153),
(160059, 'itIT', 'Questo posto non è il Quartiere degli Speziali, ma dovrà bastare.', 'Questo posto non è il Quartiere degli Speziali, ma dovrà bastare.', 28153),
(160058, 'itIT', 'Ehi, tu! Sembra che tu abbia un po\' di esperienza con gli scontri tra mascotte. Non perdiamo altro tempo, vuoi sfidarmi?', '', 28153),
(160057, 'itIT', 'Questa città è fin troppo aperta per i miei gusti. Mi servono dei luoghi oscuri come questo per completare il mio lavoro.', 'Questa città è fin troppo aperta per i miei gusti. Mi servono dei luoghi oscuri come questo per completare il mio lavoro.', 28153),
(160056, 'itIT', 'Eccellente! Sento che il potere sta già tornando ad Azeroth.', '', 28153),
(160055, 'itIT', 'Trasmogrificatore', 'Trasmogrificatore', 28153),
(160054, 'itIT', 'Percepisco dell\'Azerite nelle vicinanze... e qualcosa ne sta prosciugando il potere! Devi fermarlo!', '', 28153),
(160053, 'itIT', 'Passarono molti giorni prima di scoprire la terribile verità...\n\nKaiani era morta, accisa dal padre suo, ma fui io a pigliarmene la colpa.\n\n<Zenbaro tossisce violentemente.>\n\nNun credo che mi rimanga molto tempo.\n\nPorteresti a chesto povero morente n\'ultimo sorso d\'acqua?', '', 28153),
(160052, 'itIT', 'Dopo n\'anno, tenevo abbastanza soldi per permettere a me e Kaiani di fuggire.\n\nNa notte decidemmo di partire. Le dissi di raggiungermi vicino alla vecchia strada dei mercanti al tramonto.\n\nNun appena il sole calò dietro le montagne, cominciai a correre verso il futuro mio.\n\nQuando raggiunsi la strada dei mercanti, c\'erano delle guardie armate ad aspettarmi.\n\nMi portarono via senza dire na parola.', '', 28153),
(160051, 'itIT', 'Che vergogna... anteporre la propria avidità alla salute di Azeroth. Grazie.', '', 28153),
(160050, 'itIT', 'Durante il periodo in cui lavorai con il padre suo, diventammo amici.\n\nMi implorò di lasciare le canaglie e la città, ma sapevo che nun sarei mai potuto fuggire.\n\nNun tenevo soldi. Tutto ciò che rubavo finiva nelle mani di Rajin. Ma doveva davvero essere così?\n\nDa chel giorno, ogni due monete che rubavo, me ne tenevo una per me.\n\n<Zenbaro tossisce violentemente.>\n\nHo bisogno di altra acqua, $n. Ti prego...', '', 28153),
(160049, 'itIT', 'Mi ero guadagnato la fiducia e il rispetto di Rajin.\n\nPer uno come me, era nu sogno diventato realtà, ma tenevo altre cose in mente...\n\nRajin teneva na figlia, Kaiani, ed era tutto l\'opposto del padre suo: onesta, gentile... e bellissima.', '', 28153),
(160048, 'itIT', 'Il capo si rese subito conto delle abilità mie.\n\nEntro poco, già mi occupavo delli affari personali di Rajin.\n\nSe qualcuno teneva bisogno di na bella strigliata, ero io a farlo.\n\nChesto raramente avveniva per mezzo delle parole.\n\n<Zenbaro tossisce.>\n\nMi serve altra acqua, $n.', '', 28153),
(160047, 'itIT', 'Qualcuno in questa caverna sta estraendo dell\'Azerite dalle ferite aperte del mondo. Metti fine a tutto questo!', '', 28153),
(160046, 'itIT', 'Dimmi di più.', 'Dimmi di più.', 28153),
(160045, 'itIT', 'Non è saggio infastidire un orso.', '', 28153),
(160044, 'itIT', 'La mia filosofia accetta la morte come parte del ciclo della vita. Vuoi una dimostrazione?', '', 28153),
(160043, 'itIT', 'Sarò anche vecchio, ma sono ancora lucido. Finiscila.', '', 28153),
(160042, 'itIT', 'Sii forte.', '', 28153),
(160041, 'itIT', 'Che la forza della foresta sia con te.', '', 28153),
(160040, 'itIT', 'Colpisci velocemente e senza rimorsi.', '', 28153),
(160039, 'itIT', 'Fa\' attenzione ai boschi.', '', 28153),
(160038, 'itIT', 'Mantieni l\'equilibrio.', '', 28153),
(160037, 'itIT', 'Salve, continentale.', '', 28153),
(160036, 'itIT', 'Le nostre radici affondano in questa terra.', '', 28153),
(160035, 'itIT', 'È l\'oscurità il nostro avversario.', '', 28153),
(160034, 'itIT', 'La vita segue un ritmo. Riesci a sentirlo?', '', 28153),
(160033, 'itIT', 'Sei qui per imparare?', '', 28153),
(160032, 'itIT', '', 'Ingozzati con questo cavolo!', 28153),
(160031, 'itIT', 'La mia saggezza non è per i deboli di cuore.', '', 28153),
(160030, 'itIT', 'Cosa chiedi ai Cantaspine?', '', 28153),
(160029, 'itIT', 'Come possiamo fare un\'offerta su ciò che ci serve quando non possediamo denaro?', 'Come possiamo fare un\'offerta su ciò che ci serve quando non possediamo denaro?', 28153),
(160028, 'itIT', 'Non abbiamo molte cose di valore da vendere.', 'Non abbiamo molte cose di valore da vendere.', 28153),
(160027, 'itIT', 'Questo dovrebbe bastare per acquistare dei rifornimenti... spero.', 'Questo dovrebbe bastare per acquistare dei rifornimenti... spero.', 28153),
(160026, 'itIT', 'Quanto oro ci è rimasto?', 'Quanto oro ci è rimasto?', 28153),
(160025, 'itIT', 'Ti è rimasto qualcosa di valore da vendere?', 'Ti è rimasto qualcosa di valore da vendere?', 28153),
(160024, 'itIT', 'Non credo che dei banchieri Goblin siano un gran miglioramento rispetto a quei tirchioni dei Montague.', 'Non credo che dei banchieri Goblin siano un gran miglioramento rispetto a quei tirchioni dei Montague.', 28153),
(160023, 'itIT', 'Scrollati più forte! Aspetta, non troppo!', '', 28153),
(160022, 'itIT', '', 'L\'ultimo non molla!', 28153),
(160021, 'itIT', 'Siamo scappati così in fretta che ho dovuto lasciarmi tutto alle spalle!', 'Siamo scappati così in fretta che ho dovuto lasciarmi tutto alle spalle!', 28153),
(160020, 'itIT', '', 'Via di qui, $R!', 28153),
(160019, 'itIT', '', 'Ti daranno la caccia, $R!', 28153),
(160018, 'itIT', '', 'Vattene da Roccavento, $R!', 28153),
(160017, 'itIT', 'Vediamo chi ha mandato Marefiero stavolta.', '', 28153),
(160016, 'itIT', 'Altolà!', 'Altolà!', 28153),
(160015, 'itIT', 'Pensavi di poterla fare franca, eh?', 'Pensavi di poterla fare franca, eh?', 28153),
(160014, 'itIT', 'Ah! Beccato!', 'Ah! Beccata!', 28153),
(160013, 'itIT', 'Vattene, feccia dell\'Orda!', 'Vattene, feccia dell\'Orda!', 28153),
(160012, 'itIT', '', 'CHIGLIATORI! APRITE IL FUOCO!', 28153),
(160011, 'itIT', 'Alimentazione ripristinata. Procedere con la prima direttiva. Sterminare!', 'Alimentazione ripristinata. Procedere con la prima direttiva. Sterminare!', 28153),
(160010, 'itIT', 'Strapperò quel martello dalle tue fredde mani morte!', 'Strapperò quel martello dalle tue fredde mani morte!', 28153),
(160009, 'itIT', '', 'Ne abbiamo per tutti i gusti!', 28153),
(160008, 'itIT', '', 'Quelli della tua razza hanno sempre bisogno di vitamine!', 28153),
(160007, 'itIT', '', 'Sembra che tu abbia bisogno di una bella rapa matura!', 28153),
(160006, 'itIT', '', 'Ci sono un sacco di cose in vendita qui!', 28153),
(160005, 'itIT', 'Vattene da lì!', '', 28153),
(160004, 'itIT', '$gFermo:Ferma;!', '', 28153),
(160003, 'itIT', 'Cosa fai qui?!?', '', 28153),
(160002, 'itIT', 'Altolà!', '', 28153),
(160001, 'itIT', 'Fatevi vedere, feccia dell\'Orda! Abbiamo uno dei vostri.', '', 28153),
(160000, 'itIT', 'Me ne andrò da qui non appena sarà tutto libero. Ci rivediamo a casa della nonna, buona fortuna!', '', 28153),
(159999, 'itIT', 'Da dove si comincia, Capoguerra?', 'Da dove si comincia, Capoguerra?', 28153),
(159998, 'itIT', 'Vuoi che rimuoro?', '', 28153),
(159997, 'itIT', 'Uno dei Lanciascura, il Caposquadra Al\'jibo, si sta occupando proprio di quello per le nostre forze. Puoi trovarlo nella Sala dei Percorsi Antichi, dentro il Gran Sigillo sul lato orientale.', 'Uno dei Lanciascura, il Caposquadra Al\'jibo, si sta occupando proprio di quello per le nostre forze. Puoi trovarlo nella Sala dei Percorsi Antichi, dentro il Gran Sigillo sul lato orientale.', 28153),
(159996, 'itIT', 'Stai cercando un buon modo per scialacquare i tuoi guadagni? Ti capisco. Che gusto c\'è ad andare in battaglia se non puoi spendere il tuo bottino di guerra? O magari hai solo bisogno di qualche riparazione?\n\nChe tipo di servizio ti serve?', 'Stai cercando un buon modo per scialacquare i tuoi guadagni? Ti capisco. Che gusto c\'è ad andare in battaglia se non puoi spendere il tuo bottino di guerra? O magari hai solo bisogno di qualche riparazione?\n\nChe tipo di servizio ti serve?', 28153),
(159995, 'itIT', 'Pin\'jin il Paziente è la persona giusta se vuoi imparare di più sulla Sartoria. Le sue abilità con ago e filo sono impareggiabili. L\'altro giorno mi ha riattaccato pure il braccio.\n\nLo troverai dietro i nobili blateranti della Terrazza degli Artigiani sul lato occidentale di Dazar\'alor.', 'Pin\'jin il Paziente è la persona giusta se vuoi imparare di più sulla Sartoria. Le sue abilità con ago e filo sono impareggiabili. L\'altro giorno mi ha riattaccato pure il braccio.\n\nLo troverai dietro i nobili blateranti della Terrazza degli Artigiani sul lato occidentale di Dazar\'alor.', 28153),
(159994, 'itIT', 'Facci un giretto quando vuoi e giudica da te!', '', 28153),
(159993, 'itIT', 'Sembrerà banale, ma Rakna la Tagliatrice è una delle migliori Scuoiatrici del mondo. Hai visto la fauna che gira qui attorno?\n\nCercala alla Terrazza degli Artigiani, alla base della piramide lungo il lato occidentale di Dazar\'alor.', 'Sembrerà banale, ma Rakna la Tagliatrice è una delle migliori Scuoiatrici del mondo. Hai visto la fauna che gira qui attorno?\n\nCercala alla Terrazza degli Artigiani, alla base della piramide lungo il lato occidentale di Dazar\'alor.', 28153),
(159992, 'itIT', 'Estrazione? Delizioso. Se fossi un minatore, andrei dritto nella loro famosa \"Città d\'Oro\", Atal\'dazar. Attenzione a non farti prendere, però.\n\nSe vuoi imparare nuove tecniche, parla con Secott il Fabbro d\'Oro. Lo troverai alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.', 'Estrazione? Delizioso. Se fossi una minatrice, andrei dritta nella loro famosa \"Città d\'Oro\", Atal\'dazar. Attenzione a non farti prendere, però.\n\nSe vuoi imparare nuove tecniche, parla con Secott il Fabbro d\'Oro. Lo troverai alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.', 28153),
(159991, 'itIT', '', 'Quando desideri tornare alle Radure di Tirisfal del presente, devi solo chiedermelo.', 28153),
(159990, 'itIT', 'Questa sì che si chiama bomba! Seriamente, potrebbe far saltare in aria il Palazzo dei Piaceri di Gallywix!', '', 28153),
(159989, 'itIT', 'Ah, oggi mi ha reso un Goblin davvero orgoglioso...', '', 28153),
(159987, 'itIT', 'Un pizzico del mio ingrediente segreto e... Ecco fatto! Modifiche ultimate!', '', 28153),
(159986, 'itIT', 'Polvere da sparo, qualche miccia e una spolverata di pezzi di rame...', '', 28153),
(159985, 'itIT', 'Aggiungerò un po\' di questo. Gli darà quel tocco in più.', '', 28153),
(159984, 'itIT', 'Dammi solo... aspetta un secondo, d\'accordo?', '', 28153),
(159983, 'itIT', 'Ohhh, mi hai portato dell\'Azerite? Questa sì che è roba buona...', '', 28153),
(159982, 'itIT', 'Vuoi delle esplosioni? Be\', le avrai. Salta su una di queste bellezze e fatti un giretto.', '', 28153),
(159981, 'itIT', 'Giù le mani dalla mia pozione!', 'Giù le mani dalla mia pozione!', 28153),
(159980, 'itIT', 'Buon Cumpà nun vuole che io parli con li adulti.', '', 28153),
(159979, 'itIT', 'Ingranaggi rotti e cavi penzolano da questo mietitore non funzionante.', 'Ingranaggi rotti e cavi penzolano da questo mietitore non funzionante.', 28153),
(159978, 'itIT', 'Un martello consumato si trova sul tavolo.', 'Un martello consumato si trova sul tavolo.', 28153),
(159977, 'itIT', 'Ripara il mietitore.', 'Ripara il mietitore.', 28153),
(159976, 'itIT', 'Hai mai visto le armature di pelle tipiche degli Zandalari? Se stai cercando di imparare i loro segreti, raggiungi la Terrazza degli Artigiani sul lato occidentale inferiore di Dazar\'alor.\n\nUna volta lì, cerca Xanjo. È il loro esperto di Conciatura.', 'Hai mai visto le armature di pelle tipiche degli Zandalari? Se stai cercando di imparare i loro segreti, raggiungi la Terrazza degli Artigiani sul lato occidentale inferiore di Dazar\'alor.\n\nUna volta lì, cerca Xanjo. È il loro esperto di Conciatura.', 28153),
(159975, 'itIT', 'Recupera il martello.', 'Recupera il martello.', 28153),
(159974, 'itIT', 'Esamina le proprietà della pozione.', 'Esamina le proprietà della pozione.', 28153),
(159973, 'itIT', 'Derek tornerà da noi... in un modo o nell\'altro.', '', 28153),
(159972, 'itIT', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a Nuova costruzione disponibile!', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a Nuova costruzione disponibile!', 28153),
(159971, 'itIT', 'La bottiglia è piena di uno strano liquido vorticoso.', 'La bottiglia è piena di uno strano liquido vorticoso.', 28153),
(159970, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCavalier Campione Dirk Grandamico\n\nCapitano della Drustvaria', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_09.BLP:64|t\n\nCavalier Campione Dirk Grandamico\n\nCapitano della Drustvaria', 28153),
(159969, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitano della Tregua del Vento', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_11.BLP:64|t\n\nComandante Priscilla Hawes\n\nCapitano della Tregua del Vento', 28153),
(159968, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTenente Comandante Andrew Avrinn\n\nCapitano della Mangiaonde', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_10.BLP:64|t\n\nTenente Comandante Andrew Avrinn\n\nCapitano della Mangiaonde', 28153),
(159967, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Aloysius Millsworth', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Aloysius Millsworth', 28153),
(159966, 'itIT', 'Uno sale a bordo di una barca per far rotta verso una nuova terra in cerca di nuovi animaletti da catturare e finisce in un posto inquietante come questo. Almeno, questo è quello che è successo a me. Ho catturato qualche esemplare interessante, però. Creature che non avevo mai visto prima d\'ora. Vuoi vedere cosa sanno fare?', '', 28153),
(159965, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldatessa Ava MacArthur', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldatessa Ava MacArthur', 28153),
(159964, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente Chris Lee', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente Chris Lee', 28153),
(159963, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente Evan Morris', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente Evan Morris', 28153),
(159962, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nCavalier Tenente Samuel Robertson', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_07.BLP:64|t\n\nCavalier Tenente Samuel Robertson', 28153),
(159961, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Eloise Hesterfield', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Eloise Hesterfield', 28153),
(159960, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldatessa Sarah Gallows', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldatessa Sarah Gallows', 28153),
(159959, 'itIT', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nQuartiermastro O\'keefe', '|TINTERFACE\\ICONS\\INV_Sword_04.blp:64|t\n\nQuartiermastro O\'keefe', 28153),
(159958, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente J. Mills', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_03.BLP:64|t\n\nSergente J. Mills', 28153),
(159957, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSergente Capo Murgatroyd Smith', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_04.BLP:64|t\n\nSergente Capo Murgatroyd Smith', 28153),
(159956, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato Geoffrey Van Houten', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato Geoffrey Van Houten', 28153),
(159955, 'itIT', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nApprovvigionatore Jarrod', '|TINTERFACE\\ICONS\\INV_Misc_Bag_10.blp:64|t\n\nApprovvigionatore Jarrod', 28153),
(159954, 'itIT', 'Hai bisogno di riparare un\'armatura? Ho la migliore forgia di tutto il deserto... o meglio... l\'unica forgia di tutto il deserto.', 'Hai bisogno di riparare un\'armatura? Ho la migliore forgia di tutto il deserto... o meglio... l\'unica forgia di tutto il deserto.', 28153),
(159953, 'itIT', 'Il mare ti ingoierà in un boccone!', '', 28153),
(159952, 'itIT', '', 'Cosa vuoi dai Kaldorei?', 28153),
(159951, 'itIT', '', 'Via dai nostri archivi! Non hai nulla a che fare con questa ricerca!', 28153),
(159950, 'itIT', '', 'Che Elune guidi la tua strada.', 28153),
(159949, 'itIT', '', 'Non perdere la fede.', 28153),
(159948, 'itIT', 'Con tutti gli Elfi del Sangue che ci siamo portati dietro, verrebbe naturale pensare che ci fosse un orefice tra loro, dato che sono praticamente stati loro a inventare la professione, ma immagino che gli Zandalari non si fidino a lasciarci le loro ricchezze.\n\nSe stai cercando di imparare nuove tecniche, parla con Seshuli. Puoi trovarla nella Sala dei Bagliori, raggiungibile dirigendosi alla Terrazza degli Artigiani, sul lato occidentale di Dazar\'alor. Una volta lì, volgi lo sguardo vero la piramide ed entra in una delle gallerie. La troverai lì.', 'Con tutti gli Elfi del Sangue che ci siamo portati dietro, verrebbe naturale pensare che ci fosse un orefice tra loro, dato che sono praticamente stati loro a inventare la professione, ma immagino che gli Zandalari non si fidino a lasciarci le loro ricchezze.\n\nSe stai cercando di imparare nuove tecniche, parla con Seshuli. Puoi trovarla nella Sala dei Bagliori, raggiungibile dirigendosi alla Terrazza degli Artigiani, sul lato occidentale di Dazar\'alor. Una volta lì, volgi lo sguardo vero la piramide ed entra in una delle gallerie. La troverai lì.', 28153),
(159947, 'itIT', 'Se stai cercando qualcuno che ti insegni i misteri della Runografia, raggiungi il Gran Sigillo.\n\nUna volta lì, sali la scalinata sul lato orientale per entrare nella Sala degli Storiografi. Lì troverai la Storiografa Kizani.', 'Se stai cercando qualcuno che ti insegni i misteri della Runografia, raggiungi il Gran Sigillo.\n\nUna volta lì, sali la scalinata sul lato orientale per entrare nella Sala degli Storiografi. Lì troverai la Storiografa Kizani.', 28153),
(159946, 'itIT', 'Erbalismo, eh? Sì, conosco la persona giusta. Si chiama Jahden Fla e lo troverai intento a occuparsi del suo giardino alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.', 'Erbalismo, eh? Sì, conosco la persona giusta. Si chiama Jahden Fla e lo troverai intento a occuparsi del suo giardino alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.', 28153),
(159945, 'itIT', '', 'Noi siamo i figli di Elune.', 28153),
(159944, 'itIT', '', 'Ishnu-alah.', 28153),
(159943, 'itIT', '', 'La dea mi dà forza.', 28153),
(159942, 'itIT', 'C\'è una Zandalari presso la Scheggia, a nord di Dazar\'alor. Il suo nome è Tali la Silente, e si dice sia in grado di pescare qualsiasi cosa, ovunque.\n\nOvviamente, come dice il suo stesso nome, non è una che tende a vantarsi, quindi dovrai valutare tu se le dicerie sono vere.', 'C\'è una Zandalari presso la Scheggia, a nord di Dazar\'alor. Il suo nome è Tali la Silente, e si dice sia in grado di pescare qualsiasi cosa, ovunque.\n\nOvviamente, come dice il suo stesso nome, non è una che tende a vantarsi, quindi dovrai valutare tu se le dicerie sono vere.', 28153),
(159941, 'itIT', 'Riposo.', 'Riposo.', 28153),
(159940, 'itIT', 'Troppo lento. Continua a provare!', 'Troppo lento. Continua a provare!', 28153),
(159939, 'itIT', 'Occhi aperti! Non si può sparare a ciò che non si vede!', 'Occhi aperti! Non si può sparare a ciò che non si vede!', 28153),
(159938, 'itIT', 'Molto impreciso! Andremo avanti fin quando non ti verrà bene!', 'Molto impreciso! Andremo avanti fin quando non ti verrà bene!', 28153),
(159937, 'itIT', 'Hai fatto cadere le munizioni, Kelada! <Sospira> Fallo bene la prossima volta!', 'Hai fatto cadere le munizioni, Kelada! <Sospira> Fallo bene la prossima volta!', 28153),
(159936, 'itIT', 'Quand\'è stata l\'ultima volta che hai pulito la tua arma, soldato? Non sei capace di farlo da solo?', 'Quand\'è stata l\'ultima volta che hai pulito la tua arma, soldato? Non sei capace di farlo da solo?', 28153),
(159935, 'itIT', 'Presentat-arm!', 'Presentat-arm!', 28153),
(159934, 'itIT', 'Spalla destra... arm!', 'Spalla destra... arm!', 28153),
(159933, 'itIT', 'Ora capisco perché Bracescura non è riuscita a convincere la sua gente ad andare. Quel posto è terrificante.', '', 28153),
(159932, 'itIT', 'Ehi tu, hai mai visto cosa sono capaci di fare queste creature? Cacciano sempre in branco, seguendo la preda per poi distrarla e ucciderla. Sono davvero astute. Sono io però ad avere il comando, e loro lo sanno benissimo! Vuoi vedere come se la cavano le tue mascotte contro le mie?', '', 28153),
(159931, 'itIT', '$n sgranocchia dei popcorn.', '$n sgranocchia dei popcorn.', 28153),
(159930, 'itIT', 'Stai cercando Shuga Scoppiatappi alla Terrazza degli Artigiani. La troverai insieme al suo amico, Myxle, sul lato occidentale inferiore di Dazar\'alor, alla base della piramide.\n\nCos\'hai intenzione di far saltare in aria?', 'Stai cercando Shuga Scoppiatappi alla Terrazza degli Artigiani. La troverai insieme al suo amico, Myxle, sul lato occidentale inferiore di Dazar\'alor, alla base della piramide.\n\nCos\'hai intenzione di far saltare in aria?', 28153),
(159929, 'itIT', 'Oh... Male. Molto male... L\'hanno portata a Fine del Destino.', '', 28153),
(159928, 'itIT', 'Ah, ci siamo.', '', 28153),
(159927, 'itIT', 'Abbastanza prove per incriminarlo a vita... ma è morto, quindi non penso gli interessi tanto.', '', 28153),
(159926, 'itIT', 'L\'Incantatrice Quinni è venuta con noi. Ascolta attentamente: per trovarla devi dirigerti giù, alla base occidentale di Dazar\'alor, presso la Terrazza degli Artigiani. Una volta lì, volgi lo sguardo verso la piramide e cerca un passaggio verso l\'interno. C\'è una galleria che ti porterà in un luogo chiamato Sala dei Bagliori.\n\nSe vuoi la mia opinione, secondo me abbiamo portato troppi Elfi del Sangue con noi. La gente potrebbe insospettirsi...', 'L\'Incantatrice Quinni è venuta con noi. Ascolta attentamente: per trovarla devi dirigerti giù, alla base occidentale di Dazar\'alor, presso la Terrazza degli Artigiani. Una volta lì, volgi lo sguardo verso la piramide e cerca un passaggio verso l\'interno. C\'è una galleria che ti porterà in un luogo chiamato Sala dei Bagliori.\n\nSe vuoi la mia opinione, secondo me abbiamo portato troppi Elfi del Sangue con noi. La gente potrebbe insospettirsi...', 28153),
(159925, 'itIT', 'Oro, gemme, alcune mappe del tesoro... prove chiaramente incriminanti... ma è morto, quindi non è più un problema.', '', 28153),
(159924, 'itIT', 'Devo ammetterlo, ammiro la tua etica di lavoro. Ben fatto.', '', 28153),
(159923, 'itIT', '', 'Di solito è un buon segno. Cosa c\'è dentro?', 28153),
(159922, 'itIT', 'Be\', che possiamo saperne... ehi, non è esploso!', '', 28153),
(159921, 'itIT', 'Quel gruppo di Acqualorda deve dar da mangiare ai ranishu per poter tenere attivi i robot. Aiuta i Goblin. Prima farai, prima se ne andranno!', '', 28153),
(159920, 'itIT', 'Manca un solo lucchetto. Speriamo che non sia una trappola.', '', 28153),
(159919, 'itIT', 'Bene. Apriamo questa cassa.', '', 28153),
(159918, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCavalier Tenente Ellis R. Ladimore\n\nCapitano della Fendiabissi', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_08.BLP:64|t\n\nCavalier Tenente Ellis R. Ladimore\n\nCapitano della Fendiabissi', 28153),
(159917, 'itIT', 'Inspettat... arm!', 'Inspettat... arm!', 28153),
(159916, 'itIT', 'I reali Zandalari ci hanno mandato il loro chef personale. Il suo nome è T\'sarah e si trova al Gran Sigillo, in cima alle scale lungo il lato occidentale.\n\nPer quanto mi riguarda, non ho idea della sua bravura. Non mangio cibo cucinato.', 'I reali Zandalari ci hanno mandato il loro chef personale. Il suo nome è T\'sarah e si trova al Gran Sigillo, in cima alle scale lungo il lato occidentale.\n\nPer quanto mi riguarda, non ho idea della sua bravura. Non mangio cibo cucinato.', 28153),
(159915, 'itIT', 'Sul lato occidentale inferiore di Dazar\'alor troverai la Terrazza degli Artigiani. C\'è un enorme Metatroll Zandalari chiamato Mastro Forgiatore Zach-qualcosa che si occupa della forgia. Non puoi non notarlo.', 'Sul lato occidentale inferiore di Dazar\'alor troverai la Terrazza degli Artigiani. C\'è un enorme Metatroll Zandalari chiamato Mastro Forgiatore Zach-qualcosa che si occupa della forgia. Non puoi non notarlo.', 28153),
(159914, 'itIT', 'Ci siamo portati l\'Esaminatrice Alerinda con noi. Si trova all\'interno del Gran Sigillo, in una stanza sul lato occidentale.\n\nCredo ci sia una specie di dinosauro gigante che la sua gente sta cercando di riportare alla luce a sud-ovest di qui. Dovresti andare a vedere se hanno bisogno d\'aiuto.', 'Ci siamo portati l\'Esaminatrice Alerinda con noi. Si trova all\'interno del Gran Sigillo, in una stanza sul lato occidentale.\n\nCredo ci sia una specie di dinosauro gigante che la sua gente sta cercando di riportare alla luce a sud-ovest di qui. Dovresti andare a vedere se hanno bisogno d\'aiuto.', 28153),
(159913, 'itIT', 'Fucilieri! In riga!', 'Fucilieri! In riga!', 28153),
(159912, 'itIT', '', 'Siamo entrambi felici di vedere che stai bene.', 28153),
(159911, 'itIT', '', 'Aspetta! Non ero io che... Uff.', 28153),
(159910, 'itIT', 'Ecco qua la nostra coraggiosa salvezza! Vedi, ti avevo detto che sarebbe andato tutto bene, Taelia.', '', 28153),
(159909, 'itIT', '', 'Ogni volta che la mia famiglia va tra quelle colline, mi preoccupo molto.', 28153),
(159908, 'itIT', 'Ehi! Occhio a dove le lanci!', '', 28153),
(159907, 'itIT', '', 'Sono rimaste alcune granate! Usale!', 28153),
(159906, 'itIT', 'Stai cercando Kumali l\'Astuta. Si trova alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nFai attenzione, i Lanciascura ci hanno messo in guardia dal vudù che tipi come lei sono soliti scatenare.', 'Stai cercando Kumali l\'Astuta. Si trova alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nFai attenzione, i Lanciascura ci hanno messo in guardia dal vudù che tipi come lei sono soliti scatenare.', 28153),
(159905, 'itIT', 'Se vedi qualcuno di sospetto, dillo a me. Gli farò sputare la verità sul pavimento.', '', 28153),
(159904, 'itIT', 'Chesta sala di sicurezza è protetta da Lok la Roccia. Nessuno ruberà mai nulla accà!', '', 28153),
(159903, 'itIT', 'Tu e io dovremmo parlare dei nostri interessi in comune, dopo tutto questo.', '', 28153),
(159902, 'itIT', '', 'Ora passiamo alla mia parte preferita!', 28153),
(159901, 'itIT', 'Ora siamo alla mia parte preferita.', '', 28153),
(159900, 'itIT', 'Torneremo sani e salvi... incluso il prigioniero.', '', 28153),
(159899, 'itIT', 'Ci stanno tesori di ogni forma e dimensione, a quanto pare. È sempre affascinante vedere cosa la gente nasconde accà.', '', 28153),
(159898, 'itIT', '', 'Ricevuto.', 28153),
(159897, 'itIT', 'Nun lascerò che accada niente ai valori tuoi, $p.\n\nHo difeso i tesori dei Re, le scorte dei mercanti, i monili di gente uscita pazza e pure i pasti dei mendicanti.\n\nNun importa cosa sia, con me sarà al sicuro.', '', 28153),
(159896, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nSergente Maggiore Alison Flint', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_05.BLP:64|t\n\nSergente Maggiore Alison Flint', 28153),
(159895, 'itIT', 'L\'ultimo che ha cercato di rubare accà ora sta a Vol\'dun... insieme a tutti li altri che ci hanno provato.', '', 28153),
(159894, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Jameson Keefe', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_02.BLP:64|t\n\nCaporale Jameson Keefe', 28153),
(159893, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato Lorelai Filalame', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato Lorelai Filalame', 28153),
(159892, 'itIT', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato James Simmons', '|TINTERFACE\\ICONS\\ACHIEVEMENT_PVP_A_01.BLP:64|t\n\nSoldato James Simmons', 28153),
(159891, 'itIT', 'Chesta è la sala di sicurezza più difesa di Zandalar. Nulla può entrare o uscire senza l\'approvazione mia.\n\nTieni le cose tue dentro accà e dormirai sonni tranquilli. È facile.', '', 28153),
(159890, 'itIT', 'Piglio il lavoro mio come guardia di sicurezza seriamente, $p.\n\nSe tieni buone intenzioni, allora tengo buone intenzioni pure io.\n\nSe tieni cattive intenzioni, allora infilerò il corpo tuo in na cassa piccirilla piccirilla e la spedirò a Vol\'dun, lasciando che i Sethrak ti diano in pasto alli avvoltoi loro.\n\nChiaro?', '', 28153),
(159889, 'itIT', 'Ho fatto un accordo con gli Zandalari. In cambio li invito ai miei festini stellari.', '', 28153),
(159888, 'itIT', 'Dall\'Alleanza a Zandalar, guardati sempre le spalle.\n\nSe ti scoprissero, passeresti dalle stelle alle stalle.', '', 28153),
(159887, 'itIT', 'Molto lontani da casa ormai siamo. Che dici se davanti a una pinta al Gran Bazar ci sediamo?', '', 28153),
(159886, 'itIT', '', 'Astarii... sbrigati. Evacua la città... prima che bruci!', 28153),
(159885, 'itIT', 'Oh, certo. Se stai cercando un po\' di aiuto con le professioni, troverai molti esperti alla Terrazza degli Artigiani, lungo il lato occidentale inferiore di Dazar\'alor.\n\nCosa stai cercando di imparare?', 'Oh, certo. Se stai cercando un po\' di aiuto con le professioni, troverai molti esperti alla Terrazza degli Artigiani, lungo il lato occidentale inferiore di Dazar\'alor.\n\nCosa stai cercando di imparare?', 28153),
(159884, 'itIT', 'Un Saurolisco ha rovesciato la carovana, facendo volare via tutte le provviste.', '', 28153),
(159883, 'itIT', '', 'Genn sarà conosciuto come il \"Vecchio Lupo\", ma posso fargli fare le fusa come un gattino.', 28153),
(159882, 'itIT', '', 'Gli Elfi della Notte hanno salvato la mia gente. Farò tutto il possibile per aiutarli.', 28153),
(159881, 'itIT', 'Starò qui e farò riposare i cavalli.', '', 28153),
(159880, 'itIT', '', 'I Kaldorei hanno bisogno del nostro aiuto.', 28153),
(159879, 'itIT', '', 'Ci rimane poco tempo.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159878, 'itIT', '', 'Grazie! Credo di poter tornare indietro da sola.', 28153),
(159877, 'itIT', '', 'Fagliela pagare per questo.', 28153),
(159876, 'itIT', '', 'Così tanto sangue innocente versato...', 28153),
(159875, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(159874, 'itIT', 'Quello brutto è mio!', 'Quello brutto è mio!', 28153),
(159873, 'itIT', 'Niente prigionieri!', 'Niente prigionieri!', 28153),
(159872, 'itIT', 'Questa è proprietà dell\'Alleanza! Vattene!', 'Questa è proprietà dell\'Alleanza! Vattene!', 28153),
(159871, 'itIT', 'Hai fatto un errore, feccia dell\'Orda!', 'Hai fatto un errore, feccia dell\'Orda!', 28153),
(159870, 'itIT', '', 'Metti in salvo tutti quelli che puoi!', 28153),
(159869, 'itIT', '', 'I colpevoli pagheranno per i loro crimini.', 28153),
(159868, 'itIT', 'Noi altri vi raggiungeremo una volta finito tutto per aiutarvi a riesaminare la situazione.', '', 28153),
(159867, 'itIT', '', 'Per l\'Alleanza.', 28153),
(159866, 'itIT', '', 'La mia dimora mi chiama.', 28153),
(159865, 'itIT', '', 'Ti ringrazio per i tuoi servigi.', 28153),
(159864, 'itIT', '', 'Come posso aiutarti?', 28153),
(159863, 'itIT', '', 'Un regno non è un luogo, ma un insieme di persone.', 28153),
(159862, 'itIT', '', 'Gilneas è onorata dei tuoi servigi.', 28153),
(159861, 'itIT', '', 'Salute a te.', 28153),
(159860, 'itIT', 'Coltello. Gola. Non è difficile.', '', 28153),
(159859, 'itIT', 'Uccidere ha i suoi vantaggi. Anche l\'oro però.', '', 28153),
(159858, 'itIT', '$n, dimmi quando sei $gpronto:pronta; e inizieremo i preparativi per far saltare in aria questa nave. Dopodiché, ho bisogno che tu faccia rapporto del nostro successo a Re Wrynn.', '', 28153),
(159857, 'itIT', 'Vediamo di impressionare la Capoguerra. E... ottenere una bella ricompensa.', '', 28153),
(159856, 'itIT', 'Diamo una lezione a quei selvaggi, d\'accordo?', '', 28153),
(159855, 'itIT', 'Keeshan, Kelsey, fate in modo che la nave esploda non appena tutti saranno scesi.', '', 28153),
(159854, 'itIT', 'Non perdiamo altro tempo.', '', 28153),
(159853, 'itIT', 'La guerra abbonda di opportunità.', '', 28153),
(159852, 'itIT', 'Umbric, ci servirà almeno un altro Varco del Vuoto per far uscire tutte le nostre forze da qui.', '', 28153),
(159851, 'itIT', 'Dobbiamo distruggere questa nave. Shandris, aiuta le nostre forze rimanenti con i preparativi per la partenza.', '', 28153),
(159848, 'itIT', 'Adoro il mio lavoro.', '', 28153),
(159847, 'itIT', 'Ci mettiamo al lavoro?', '', 28153),
(159845, 'itIT', 'La gente mia verrà a liberarmi, proprio come hanno fatto con la Principessa Talanji e Zul!', '', 28153),
(159844, 'itIT', 'Mi piacerebbe vederli provare. Comunque, passiamo ad altre questioni.', '', 28153),
(159843, 'itIT', 'Puoi scegliere se combatterci fino alla fine o cooperare con noi. Spetta solo a te decidere.', '', 28153),
(159842, 'itIT', 'Me ne occuperò io.', 'Me ne occuperò io.', 28153),
(159841, 'itIT', 'No. Ci sono già stati abbastanza morti oggi, Capitano. Ti porteremo a Roccavento come nostro prigioniero.', '', 28153),
(159840, 'itIT', 'Cani dell\'Alleanza! Accidetemi mo\' e facciamola finita!', '', 28153),
(159839, 'itIT', '', 'Il Capitano Zalkran stava cercando di fuggire a Zuldazar, ma Falstad e io l\'abbiamo catturato.', 28153),
(159838, 'itIT', 'Shandris, rapporto sulla situazione?', 'Shandris, rapporto sulla situazione?', 28153),
(159837, 'itIT', 'Puoi riportarmi al presente?', 'Puoi riportarmi al presente?', 28153),
(159836, 'itIT', 'Puoi mostrarmi com\'erano le Radure di Tirisfal prima della Battaglia per Lordaeron?', 'Puoi mostrarmi com\'erano le Radure di Tirisfal prima della Battaglia per Lordaeron?', 28153),
(159835, 'itIT', '', 'Oh... se vedi mio nipote, Charles, assicurati che non si stia nascondendo da qualche parte sotto un albero.', 28153),
(159834, 'itIT', 'Hai già iniziato a catturare le mascotte che questa strana terra ha da offrire? Per quanto mi riguarda, sto cercando una di quelle Maschere Tiki del Sangue, ma non ho idea di come la prenderebbero gli abitanti locali.\n\nSe stai cercando uno Stalliere, c\'è uno Zandalari che si fa chiamare Domatore di Bestie Kalatak, vicino alla base nordoccidentale di Dazar\'alor.', 'Hai già iniziato a catturare le mascotte che questa strana terra ha da offrire? Per quanto mi riguarda, sto cercando una di quelle Maschere Tiki del Sangue, ma non ho idea di come la prenderebbero gli abitanti locali.\n\nSe stai cercando uno Stalliere, c\'è uno Zandalari che si fa chiamare Domatore di Bestie Kalatak, vicino alla base nordoccidentale di Dazar\'alor.', 28153),
(159833, 'itIT', 'La ciurma della Principessa Viola è in sciopero. Forse qualcosa riguardo il non essere stati pagati negli ultimi undici anni... Non so, non stavo ascoltando.', 'La ciurma della Principessa Viola è in sciopero. Forse qualcosa riguardo il non essere stati pagati negli ultimi undici anni... Non so, non stavo ascoltando.', 28153),
(159832, 'itIT', 'Come posso raggiungere la Valle di Rovotorto?', 'Come posso raggiungere la Valle di Rovotorto?', 28153),
(159831, 'itIT', '', 'Sembra che avrò bisogno del tuo aiuto ancora una volta.', 28153),
(159830, 'itIT', '', 'Ti ringrazio, anche se sembra che non siamo ancora fuori pericolo.', 28153),
(159829, 'itIT', '', 'Sì, madre. Tornerò a breve con loro.', 28153),
(159828, 'itIT', '', 'Taelia! Porta con te il campione e raduna la milizia. Jaina e io prepareremo le difese.', 28153),
(159827, 'itIT', '', 'Sembra che avrò bisogno del tuo aiuto ancora una volta.', 28153),
(159826, 'itIT', '', 'Priscilla è tornata per prendersi la mia città...', 28153),
(159825, 'itIT', '', 'O... era già troppo tardi?', 28153),
(159824, 'itIT', '', 'Dimmi cos\'hai trovato. Qualche segno di Jaina?', 28153),
(159823, 'itIT', '', 'Rieccoti! Vedo che non c\'è nessuno con te.', 28153),
(159822, 'itIT', '', 'La carovana è a pezzi e avremmo potuto rimanerci secchi.\n\nLa bestia che ci ha attaccati è in quella caverna. Non me ne vado fin quando non sarà morta!', 28153),
(159821, 'itIT', '', 'Ammiraglio Supremo! Navi all\'orizzonte! Hanno la bandiera dei Bracescura!', 28153),
(159820, 'itIT', '', 'Madre... Io...', 28153),
(159819, 'itIT', '', 'Bene, vediamo se riesco a fare le cose nel modo giusto questa volta. Bentornata a casa, figlia mia.', 28153),
(159818, 'itIT', '', 'È bello sentire di nuovo la brezza del mare. Grazie. Senza il tuo intervento forse non avrei mai più provato questa sensazione...', 28153),
(159817, 'itIT', 'Salve, $gInquisitore:Inquisitrice;!\n\nDama Crestabianca mi ha incaricato di preparare il mio falco più veloce per consegnare un messaggio per te.', '', 28153),
(159816, 'itIT', 'Riferisci a Katherine Marefiero di incontrarmi a Gol Inath.', 'Riferisci a Katherine Marefiero di incontrarmi a Gol Inath.', 28153),
(159815, 'itIT', 'Sto cercando un modo di entrare nelle Terre Ammorbate.', 'Sto cercando un modo di entrare nelle Terre Ammorbate.', 28153),
(159814, 'itIT', '', 'Proteggila a costo della vita. Kul Tiras ha già perso fin troppi Marefiero.', 28153),
(159813, 'itIT', '', 'Ce l\'hai fatta! L\'effige ha funzionato!', 28153),
(159812, 'itIT', '', 'Ecco! I segni sul muro mostrano la sequenza corretta!', 28153),
(159811, 'itIT', '', 'Forse le rune devono essere attivate in un certo ordine...', 28153),
(159810, 'itIT', '', 'Non sarà stato piacevole...', 28153),
(159809, 'itIT', '', 'Prova ad attivarne un\'altra.', 28153),
(159808, 'itIT', '', 'Non c\'è più! Forse queste rune agiscono da protezione?', 28153),
(159807, 'itIT', '', 'Dovrebbe esserci qualche indizio qui su come funziona questa cosa.', 28153),
(159806, 'itIT', '', 'Be\', sembra... aver fatto qualcosa...', 28153),
(159805, 'itIT', '', 'Sembra una sorta di passaggio. Forse dovremmo posizionare qui l\'effige.', 28153),
(159804, 'itIT', '', 'Devo farmi forza. Jaina ha affrontato cose ben peggiori per colpa mia.', 28153),
(159803, 'itIT', '', 'Questo luogo mi gela l\'anima. È quasi come se stessi camminando sulla mia stessa tomba...', 28153),
(159802, 'itIT', '', 'Ora siamo solo io e te. Fai strada.', 28153),
(159801, 'itIT', '', 'Quei... mostri nei boschi hanno teso un\'imboscata alla mia guardia d\'onore. Sono sopravvissuta solo grazie al loro sacrificio.', 28153),
(159800, 'itIT', '', 'Per fortuna sei qui!', 28153),
(159799, 'itIT', 'Sì signore! Hannibal recapiterà il messaggio al Forte dei Marefiero in men che non si dica!', '', 28153),
(159798, 'itIT', 'Ora sei al sicuro.', 'Ora sei al sicuro.', 28153),
(159797, 'itIT', '', 'Ascolta, so che Katherine sta pensando di unirsi a te in questa folle ricerca.', 28153),
(159796, 'itIT', 'Quell\'inquietante Nobile Oscuro, Oculeth, ha aperto dei portali per Orgrimmar, Lunargenta e Picco del Tuono. Puoi trovarli nella Sala dei Percorsi Antichi, dentro il Gran Sigillo, sul lato orientale.\n\nPurtroppo, non vi è un portale per Sepulcra. Presto avremo la nostra rivincita sulla feccia dell\'Alleanza! Genn, Jaina e Re Anduin pagheranno per i loro crimini!\n\nVittoria per Sylvanas! Possa il suo regno come Capoguerra durare mille anni!', 'Quell\'inquietante Nobile Oscuro, Oculeth, ha aperto dei portali per Orgrimmar, Lunargenta e Picco del Tuono. Puoi trovarli nella Sala dei Percorsi Antichi, dentro il Gran Sigillo, sul lato orientale.\n\nPurtroppo, non vi è un portale per Sepulcra. Presto avremo la nostra rivincita sulla feccia dell\'Alleanza! Genn, Jaina e Re Anduin pagheranno per i loro crimini!\n\nVittoria per Sylvanas! Possa il suo regno come Capoguerra durare mille anni!', 28153),
(159795, 'itIT', 'La via che porta a Thros è pericolosa, ma non è che una piccola frazione di ciò che ti attende nelle Terre Ammorbate.\n\nPreparati, $C. I servitori di Thros useranno le tue paure e i tuoi rimorsi più profondi contro di te.', '', 28153),
(159794, 'itIT', 'L\'entrata per Thros giace all\'interno del grande albero, Gol Inath, ma oltrepassare quella soglia non sarà una passeggiata.\n\nPer aprire una via, avrai bisogno di un\'effige molto potente, ma non di una della congrega, ovviamente. Una più antica, infusa della magia dei Drust.', '', 28153),
(159793, 'itIT', '', 'La carovana si è rovesciata... È stato terrificante!\n\nVolevo tornare al villaggio per chiedere aiuto, ma avevo troppa paura.', 28153),
(159792, 'itIT', 'Ah, è bello vedere qualcun altro che segue il cammino.\n\nChe cosa ti serve dai Cantaspine?', '', 28153),
(159791, 'itIT', 'E così i continentali sono tornati, eh?\n\nIl nostro debito è stato saldato. Sei in cerca di altri favori dai Cantaspine?', '', 28153),
(159790, 'itIT', 'È passato molto tempo dall\'ultima volta che un continentale ha messo piede nel mio boschetto.\n\nSei qui in cerca della conoscenza dei Cantaspine o per rivendicare questa terra come piace fare alla tua gente?', '', 28153),
(159789, 'itIT', 'Questo... cambia le cose.', '', 28153),
(159788, 'itIT', 'Sembra che mi sia sbagliato. Thros è venuta da noi.', '', 28153),
(159787, 'itIT', 'Non finisce qui, vecchio orso.', '', 28153),
(159786, 'itIT', 'Mi assicurerò che siano tutti al sicuro.', 'Mi assicurerò che siano tutti al sicuro.', 28153),
(159785, 'itIT', 'Chi sei tu per giudicare chi è degno? Le tue azioni hanno gettato fango sulla nostra razza, Tul!', '', 28153),
(159784, 'itIT', 'Vorresti condividere i nostri doni con questi miserabili, Ulfar? Meriti di bruciare assieme a loro!', '', 28153),
(159783, 'itIT', 'Come posso raggiungere il Fiordo Echeggiante?', 'Come posso raggiungere il Fiordo Echeggiante?', 28153),
(159782, 'itIT', 'Cantaspine, alle armi!', '', 28153),
(159781, 'itIT', 'Abbiamo perso i contatti con la Bacianubi da qualche parte nel Grande Mare. Stavamo puntando al record di ottocentoquindici voli senza rifornimento! Di certo staranno tutti benissimo.', 'Abbiamo perso i contatti con la Bacianubi da qualche parte nel Grande Mare. Stavamo puntando al record di ottocentoquindici voli senza rifornimento! Di certo staranno tutti benissimo.', 28153),
(159780, 'itIT', 'Gorak Tul?!? Non può essere!', '', 28153),
(159779, 'itIT', 'Oh, siamo già ben oltre questo, vecchio orso.', '', 28153),
(159778, 'itIT', 'Certi confini non vanno attraversati, se non si vuole disturbare chi si trova dall\'altra parte.', '', 28153),
(159777, 'itIT', 'Temo di non poterti aiutare in questo, continentale.', '', 28153),
(159776, 'itIT', 'Vorresti entrare a Thros? Mi dispiace, ma temo di non poterti aiutare, continentale.', '', 28153),
(159775, 'itIT', '', 'Non avrete davvero intenzione di andare nelle Terre Ammorbate, vero?', 28153),
(159774, 'itIT', '', 'Inquisitrice! Abbiamo notizie di Katherine!', 28153),
(159773, 'itIT', '', 'Sono io la responsabile del suo destino. Voglio esserci quando lo cambieremo.', 28153),
(159772, 'itIT', '', 'Se... quando troverai Jaina, voglio esserci. Affronterò qualsiasi pericolo ci attenda.', 28153),
(159771, 'itIT', '', 'Ancora una cosa...', 28153),
(159770, 'itIT', 'Un Saurolisco ha spaventato i cavalli, la carovana si è capovolta e abbiamo perso i nostri rifornimenti.\n\nLe mie due bambine, Lorraine e Mallory, sono ancora là fuori e potrebbe far loro comodo il tuo aiuto.', '', 28153),
(159769, 'itIT', 'È dove io e altri siamo soliti andare una volta finito il turno. Bisogna sempre mantenere l\'allenamento.\n\nSono all\'Armeria Reale, sul lato settentrionale di Dazar\'alor, alla base della piramide. Dovresti unirti a noi.', 'È dove io e altri siamo soliti andare una volta finito il turno. Bisogna sempre mantenere l\'allenamento.\n\nSono all\'Armeria Reale, sul lato settentrionale di Dazar\'alor, alla base della piramide. Dovresti unirti a noi.', 28153),
(159768, 'itIT', '', 'Trova Fratello Pike! È un Saggio delle Maree leale e so che ci aiuterà.', 28153),
(159767, 'itIT', '', 'Dopotutto, stava agendo secondo i miei ordini.', 28153),
(159766, 'itIT', '', 'Solo i Saggi delle Maree vi si possono avvicinare in sicurezza e Bracescura non si sarebbe fatta alcuno scrupolo a servirsi di loro.', 28153),
(159765, 'itIT', '', 'Dimmi che non è già troppo tardi.', 28153),
(159764, 'itIT', '', 'Dov\'è stata portata Jaina?', 28153),
(159763, 'itIT', 'Già. Anch\'io.', '', 28153),
(159762, 'itIT', '', 'Ah, Flynn, sai cosa voglio dire. Prego per il bene di Dama Katherine che tu abbia torto.', 28153),
(159761, 'itIT', 'Ti sei data alle scommesse, eh? Vergognati. Cosa direbbe Cyrus?', '', 28153),
(159760, 'itIT', 'Immagino tu abbia degli affari con i Lanciascura. Sai che la nave è diretta alle Isole dell\'Eco, vero? O vuoi fare una piccola gitarella prima di tornare a Orgrimmar?\n\nPuoi trovarla in fondo al molo a sud del Porto di Zandalar.', 'Immagino tu abbia degli affari con i Lanciascura. Sai che la nave è diretta alle Isole dell\'Eco, vero? O vuoi fare una piccola gitarella prima di tornare a Orgrimmar?\n\nPuoi trovarla in fondo al molo a sud del Porto di Zandalar.', 28153),
(159759, 'itIT', '', 'Be\', abbiamo qui l\'unica persona su cui scommetterei per riportarla indietro.', 28153),
(159758, 'itIT', 'L\'isola si chiama Fine del Destino, Taelia. Non Speranza del Destino.', '', 28153),
(159757, 'itIT', 'Ottimo lavoro. Raduniamoci.', '', 28153),
(159756, 'itIT', 'Posso portarti sulla Lamento della Banshee, $p, ma dovrai tenerti forte!', '', 28153),
(159755, 'itIT', 'Granmartello, disperdetevi e tenete i cieli liberi, ma evitate di farvi scoprire, per ora.', '', 28153),
(159750, 'itIT', '', 'Ahah... il capitano... vi acciderà... tutti quanti...', 28153),
(159749, 'itIT', '', 'È troppo tardi! Il Capitano ha già comunicato la posizione vostra alla Principessa Talanji.', 28153),
(159748, 'itIT', 'Conosco il Goblin giusto. Il suo nome è Myxle Storcibudella e lo troverai insieme al suo Tritatutto V1 alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nDice che il suo dispositivo è in grado di fare a pezzi ogni equipaggiamento, per ricavarne materie prime da riutilizzare o vendere. Stavo per accettare la sua offerta, ma quest\'armatura è di proprietà dell\'Orda.', 'Conosco il Goblin giusto. Il suo nome è Myxle Storcibudella e lo troverai insieme al suo Ricicl-o-Matic 1000 alla Terrazza degli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nDice che il suo dispositivo è in grado di fare a pezzi ogni equipaggiamento, per ricavarne materie prime da riutilizzare o vendere. Stavo per accettare la sua offerta, ma quest\'armatura è di proprietà dell\'Orda.', 28153),
(159747, 'itIT', 'Per raggiungere il Trono Dorato, devi prendere l\'ascensore all\'interno del Gran Sigillo.\n\nStai entrando in confidenza con i reali? Cosa ne pensi di quei copricapi? Devono avere dei colli belli forti!', 'Per raggiungere il Trono Dorato, devi prendere l\'ascensore all\'interno del Gran Sigillo.\n\nStai entrando in confidenza con i reali? Cosa ne pensi di quei copricapi? Devono avere dei colli belli forti!', 28153),
(159746, 'itIT', 'Questo posto è enorme, glielo concedo. Conosco qualche punto d\'interesse, se stai cercando qualcosa di particolare.', 'Questo posto è enorme, glielo concedo. Conosco qualche punto d\'interesse, se stai cercando qualcosa di particolare.', 28153),
(159745, 'itIT', 'Brillin l\'Incantevole si trova al centro del Gran Sigillo. La sua danza non è forse divina?', 'Brillin l\'Incantevole si trova al centro del Gran Sigillo. La sua danza non è forse divina?', 28153),
(159744, 'itIT', 'C\'è una Zandalari di nome Paku\'ai che fornisce spostamenti in volo. Se vuoi uno Pterrordattilo, puoi trovarla poco fuori dal Gran Sigillo, sul lato orientale.', 'C\'è una Zandalari di nome Paku\'ai che fornisce spostamenti in volo. Se vuoi uno Pterrordattilo, puoi trovarla poco fuori dal Gran Sigillo, sul lato orientale.', 28153),
(159743, 'itIT', 'Immagino dipenda da quale emissario stai cercando, $n.', 'Immagino dipenda da quale emissario stai cercando, $n.', 28153),
(159742, 'itIT', 'Ti stai facendo amici gli Zandalari? Ottimo, proprio quello che vuole la Capoguerra.\n\nPuoi trovare il loro emissario, Natal\'hakata, dentro il Gran Sigillo.', 'Ti stai facendo amici gli Zandalari? Ottimo, proprio quello che vuole la Capoguerra.\n\nPuoi trovare il loro emissario, Natal\'hakata, dentro il Gran Sigillo.', 28153),
(159741, 'itIT', 'Stai cercando di scoprire i segreti dei Tortolliani? Si dice che vivano per secoli. Non tanto quanto vivrò io, ma è comunque un sacco di tempo.\n\nIn ogni caso, dovrai raggiungere l\'Emporio degli Scambiascaglie, a nord-est di Dazar\'alor. Cerca Kojo il Collezionista.', 'Stai cercando di scoprire i segreti dei Tortolliani? Si dice che vivano per secoli. Non tanto quanto vivrò io, ma è comunque un sacco di tempo.\n\nIn ogni caso, dovrai raggiungere l\'Emporio degli Scambiascaglie, a nord-est di Dazar\'alor. Cerca Kojo il Collezionista.', 28153),
(159740, 'itIT', 'Oh, certo. Uno stile diverso, o magari un nuovo colore? Stai cercando Connor Buzznick, nel Gran Bazar presso il porto.', 'Oh, certo. Uno stile diverso, o magari un nuovo colore? Stai cercando Connor Buzznick, nel Gran Bazar presso il porto.', 28153),
(159739, 'itIT', 'Perché finisce sempre che non sono io a cavalcare il grifone?', '', 28153),
(159738, 'itIT', 'Non troppo basso! Non troppo basso!', '', 28153),
(159737, 'itIT', '', 'Provo a seminarli volando basso! Giù, Cuorventoso!', 28153),
(159736, 'itIT', 'Tenermi è l\'unica cosa che posso fare al momento!', '', 28153),
(159735, 'itIT', '', 'Tieni duro! Ci sparano addosso!', 28153),
(159734, 'itIT', 'La Tesoreria Reale si trova nella piramide sul lato ovest del Gran Sigillo. Pensavamo di metterci dei Goblin a lavorare, ma gli Zandalari si sono rifiutati.\n\nSono furbi.', 'La Tesoreria Reale si trova nella piramide sul lato ovest del Gran Sigillo. Pensavamo di metterci dei Goblin a lavorare, ma gli Zandalari si sono rifiutati.\n\nSono furbi.', 28153),
(159733, 'itIT', 'Vuoi andare alle Isole dell\'Eco? Perché? Lì ci vivono i Lanciascura. È nu posto piccirillo. Stai accà a Zandalar, che è grande.\n\nNo? Vabbuo\', per fortuna tua abbiamo dato loro in prestito una delle nostre navi da guerra. Puoi trovarla in fondo al molo a sud del Porto di Zandalar.', 'Vuoi andare alle Isole dell\'Eco? Perché? Lì ci vivono i Lanciascura. È nu posto piccirillo. Stai accà a Zandalar, che è grande.\n\nNo? Vabbuo\', per fortuna tua abbiamo dato loro in prestito una delle nostre navi da guerra. Puoi trovarla in fondo al molo a sud del Porto di Zandalar.', 28153),
(159732, 'itIT', 'Nave per le Isole dell\'Eco', 'Nave per le Isole dell\'Eco', 28153),
(159731, 'itIT', 'Il Caposquadra Al\'jibo dei Lanciascura si trova nella Sala dei Percorsi Antichi sul lato est del Gran Sigillo. Posso garantire per lui, dato che è venuto insieme all\'Orda. Sarà perfettamente in grado di ripararti le ammaccature e affilarti le armi.\n\nAltrimenti, molto presto ballerai con Bwonsamdi.', 'Il Caposquadra Al\'jibo dei Lanciascura si trova nella Sala dei Percorsi Antichi sul lato est del Gran Sigillo. Posso garantire per lui, dato che è venuto insieme all\'Orda. Sarà perfettamente in grado di ripararti le ammaccature e affilarti le armi.\n\nAltrimenti, molto presto ballerai con Bwonsamdi.', 28153),
(159730, 'itIT', 'Se dovessi avere ancora bisogno di noi, mandaci un segnale. Io e Alalesta ti troveremo.', '', 28153),
(159729, 'itIT', 'Ah! Adoro questa parte!', '', 28153),
(159728, 'itIT', 'Andiamo, Alalesta. Vola radente al suolo, per evitare che ci scoprano. Vai il più veloce possibile.', '', 28153),
(159727, 'itIT', 'Riparazioni', 'Riparazioni', 28153),
(159726, 'itIT', 'Ovvio che tieni oro da spendere. Chesta è Zandalar! Neanche i Goblin tengono più oro di noi.\n\nCosa stai cercando?', 'Ovvio che tieni oro da spendere. Chesta è Zandalar! Neanche i Goblin tengono più oro di noi.\n\nCosa stai cercando?', 28153),
(159725, 'itIT', 'Mercanti', 'Mercanti', 28153),
(159724, 'itIT', '', 'Perlustrerò la Vento Cremisi mentre tu penserai alla Lamento della Banshee. Tor ilisar\'thera\'nal!', 28153),
(159723, 'itIT', '', 'Ci stiamo avvicinando. Riesco a sentire il lurido tanfo della non morte.', 28153),
(159722, 'itIT', 'L\'Elfo Nobile Oscuro sta usando il vudù suo nella Sala dei Percorsi Antichi. Cercalo sul lato orientale, dentro il Gran Sigillo.\n\nHa trovato nu modo per permetterti di raggiungere li altri piccoli villaggi tuoi. Com\'è che si chiamano? Orgrimmar, Lunargenta e Picco del Tuono? Umpf.', 'L\'Elfo Nobile Oscuro sta usando il vudù suo nella Sala dei Percorsi Antichi. Cercalo sul lato orientale, dentro il Gran Sigillo.\n\nHa trovato nu modo per permetterti di raggiungere li altri piccoli villaggi tuoi. Com\'è che si chiamano? Orgrimmar, Lunargenta e Picco del Tuono? Umpf.', 28153),
(159721, 'itIT', 'Portali', 'Portali', 28153),
(159720, 'itIT', 'Come sei finito qui?', 'Come sei finito qui?', 28153),
(159719, 'itIT', 'Ecco! Le informazioni sulla posizione di Jaina devono trovarsi qui dentro.\n\n<Flynn indica la cassa.>\n\nHai le chiavi, l\'onore è tuo.', '', 28153),
(159718, 'itIT', '', 'Troppo tardi!', 28153),
(159717, 'itIT', '', 'Ce l\'ho fatta comunque.', 28153),
(159716, 'itIT', 'Vuoi allenarti nu po\'? Accà a Dazar\'alor teniamo i migliori manichini d\'allenamento. Li troverai nell\'Armeria Reale, sul lato nord della piramide di Dazar\'alor.', 'Vuoi allenarti nu po\'? Accà a Dazar\'alor teniamo i migliori manichini d\'allenamento. Li troverai nell\'Armeria Reale, sul lato nord della piramide di Dazar\'alor.', 28153),
(159715, 'itIT', '<Zenbaro tossisce.>', '', 28153),
(159714, 'itIT', 'Manichini d\'Allenamento', 'Manichini d\'Allenamento', 28153),
(159713, 'itIT', '', 'Quando desideri tornare agli Altopiani d\'Arathi del presente, devi solo chiedermelo.', 28153),
(159712, 'itIT', 'Avrò bisogno che tu mi copra le spalle mentre eseguo il rituale. Dovrebbe volerci solo qualche momento.', '', 28153),
(159711, 'itIT', 'Puoi riportarmi al presente?', 'Puoi riportarmi al presente?', 28153),
(159710, 'itIT', '<Consegna la borraccia a Zenbaro.>', '<Consegna la borraccia a Zenbaro.>', 28153),
(159709, 'itIT', 'Bene, $n. Facciamola finita.', '', 28153),
(159708, 'itIT', 'Puoi mostrarmi com\'erano gli Altopiani d\'Arathi prima della guerra?', 'Puoi mostrarmi com\'erano gli Altopiani d\'Arathi prima della guerra?', 28153),
(159707, 'itIT', '', 'Vedo il tuo nome proprio qui! Sali le scale e raggiungi l\'ultimo ufficio in fondo al corridoio. Il signor Camden sarà lì ad aspettarti.', 28153),
(159706, 'itIT', '', 'La guerra infuria in queste terre e la storia si ripete. Il fiume del tempo è ciclico.\n\nChiedo perdono, a volte dimentico che la tua razza è così... lineare.\n\nCome posso aiutarti?', 28153),
(159705, 'itIT', '', 'Mi spiace, ma nessuno può entrare senza un appuntamento. Guardie!', 28153),
(159704, 'itIT', 'Sì, ho un appuntamento. È a nome di A. Brazorf.', 'Sì, ho un appuntamento. È a nome di A. Brazorf.', 28153),
(159703, 'itIT', 'Lo sai chi sono? Sono $n, $gcampione:campionessa; dell\'Alleanza! Fammi vedere subito i documenti!', 'Lo sai chi sono? Sono $n, $gcampione:campionessa; dell\'Alleanza! Fammi vedere subito i documenti!', 28153),
(159702, 'itIT', 'Ho un appuntamento con il tuo capo. È di vitale importanza che io gli parli immediatamente!', 'Ho un appuntamento con il tuo capo. È di vitale importanza che io gli parli immediatamente!', 28153),
(159701, 'itIT', '', 'Come posso aiutarti?', 28153),
(159700, 'itIT', '', '$gBenvenuto:Benvenuta; negli uffici della Compagnia dei Bracescura. Hai un appuntamento?', 28153),
(159699, 'itIT', 'Ah, eccoti, $p. Salta su!', '', 28153),
(159698, 'itIT', 'Già. Dobbiamo andare fino in fondo.', '', 28153),
(159697, 'itIT', '', 'Questa terra è ricca di storia. Devo mostrarti com\'erano le cose quando l\'Impero di Arathor era al culmine del suo splendore.\n\nMmm. Immagino che la cosa dovrà aspettare.\n\nHai concluso i tuoi affari nel passato, $gcampione:campionessa;?', 28153),
(159696, 'itIT', 'Lo è. Non voglio dire che sia la soluzione migliore, ma ci dobbiamo adattare alla situazione.', '', 28153),
(159695, 'itIT', 'Una brutta faccenda, non è vero Halford? Dover uccidere fino all\'ultimo Zandalari a bordo della nave.', '', 28153),
(159694, 'itIT', 'Quando sei $gpronto:pronta; a iniziare il rituale, posa la Chiave del Mare nella ciotola.', '', 28153),
(159693, 'itIT', 'Attendevo con molta ansia il ritorno tuo, $n.', '', 28153),
(159692, 'itIT', 'Stavo iniziando a pensare che nun saresti più $gtornato:tornata;.', '', 28153),
(159691, 'itIT', 'Sono felice di vederti, $n. Lo ammetto, nun pensavo saresti $gtornato:tornata;.', '', 28153),
(159689, 'itIT', 'Lascia che parta dall\'inizio.\n\nI primi ricordi che tengo sono anche i migliori, quando correvo in giro con le canaglie di Zuldazar.\n\nNun facevamo che cacciarci nei guai ai tempi, ma nun sapevamo fare di meglio.\n\nRajin era il capo nostro. Ci diede nu tetto sulla capa e, in cambio, facevamo tutto chello che chiedeva.\n\nDi solito significava truffare la gente in città o rubare dalle offerte ai Loa.', '', 28153),
(159688, 'itIT', '', 'Presto! Siamo in territorio nemico, non a Roccavento! Scarichiamo questa roba ed evacuiamo i feriti!', 28153),
(159687, 'itIT', 'Nun è forse la domanda che tutti ci facciamo?\n\n<Zenbaro tossisce.>\n\nLe sabbie nun sono state magnanime con me, $n. Mi sto avvicinando alla fine.\n\nLa gola mia è gonfia dal calore del deserto.\n\nPortami dell\'acqua fresca dalla fonte vicino accà e ti racconterò la storia mia.', '', 28153),
(159686, 'itIT', 'Stai parlando di chel Goblin e della folle invenzione sua alla Terrazza delli Artigiani? Dice che il suo Ricicl-o-Matic 1000 può ridurre ogni cosa in materie prime.\n\nTi basterà raggiungere il lato occidentale inferiore di Dazar\'alor.', 'Stai parlando di chel Goblin e della folle invenzione sua alla Terrazza delli Artigiani? Dice che il suo Ricicl-o-Matic 1000 può ridurre ogni cosa in materie prime.\n\nTi basterà raggiungere il lato occidentale inferiore di Dazar\'alor.', 28153),
(159685, 'itIT', 'Nun immaginavo che chesto sarebbe stato il destino mio. Schiattare da solo tra le dune.', '', 28153),
(159684, 'itIT', 'Riciclatore', 'Riciclatore', 28153),
(159683, 'itIT', 'Il posto è questo. Scendiamo giù in cantina.', '', 28153),
(159682, 'itIT', 'Che affari ti portano al Trono Dorato? Stai cercando n\'udienza?\n\nPer andare lassù, piglia l\'ascensore dall\'interno del Gran Sigillo.', 'Che affari ti portano al Trono Dorato? Stai cercando n\'udienza?\n\nPer andare lassù, piglia l\'ascensore dall\'interno del Gran Sigillo.', 28153),
(159681, 'itIT', 'La cantina in questione dovrebbe essere vicina. Non perdiamo altro tempo.', '', 28153),
(159680, 'itIT', 'Trono Dorato', 'Trono Dorato', 28153),
(159679, 'itIT', 'Sei $gpronto:pronta; ad andare?', '', 28153),
(159678, 'itIT', 'Facciamo alla svelta. Entriamo e usciamo, prima che ci scoprano.', '', 28153),
(159677, 'itIT', 'Diamoci da fare!', '', 28153),
(159676, 'itIT', '', 'Subito.', 28153),
(159675, 'itIT', 'Shandris, ho bisogno che tu tenga d\'occhio le spiagge per assicurarti che nessun sopravvissuto riesca a fuggire. Falstad si unirà a te non appena ci avrà lasciati.', '', 28153),
(159674, 'itIT', '', 'Non ci vedranno nemmeno arrivare.', 28153),
(159673, 'itIT', 'Ricevuto.', '', 28153),
(159672, 'itIT', 'Keeshan, Kelsey, prendete il portale di Umbric e stabilite un punto d\'atterraggio sul ponte della nave.', '', 28153),
(159671, 'itIT', 'Agli ordini.', '', 28153),
(159670, 'itIT', 'Umbric, apri un Portale del Vuoto per condurre i Nani Ferroscuro alla Chiamata di Gral.', '', 28153),
(159669, 'itIT', 'Dobbiamo assicurarci che nessuno su quella nave torni sano e salvo a Zuldazar, o noi e la nostra missione non vedremo l\'alba di domani.', '', 28153),
(159668, 'itIT', 'Sono pronto a partire.', 'Sono pronta a partire.', 28153),
(159667, 'itIT', '', 'Tutti quanti all\'accademia si prenderanno gioco di me! Oh, Yuke, sei così maldestra!', 28153),
(159666, 'itIT', '', 'Grazie! Faccio parte degli Shandaren, sai? Ho solo preso un giorno libero. Tieni, prendi quest\'Azerite e non dirlo a nessuno, d\'accordo?', 28153),
(159665, 'itIT', 'Per tutte le onde, questo non l\'avevo previsto. Perirò forse qui?', '', 28153),
(159664, 'itIT', 'I miei più sinceri ringraziamenti. Starò più attento in futuro. Tenete, un piccolo dono per la vostra gentilezza.', '', 28153),
(159663, 'itIT', 'Che buffo, mi sono cacciato in un vicolo cieco!', '', 28153),
(159662, 'itIT', 'Ahah! Che cosa sarebbe la cartografia senza un po\' di avventura o di pericolo? Il vostro sguardo vuoto mi fa capire che siete d\'accordo con me. Tenete, ecco qualcosa per voi.', '', 28153),
(159661, 'itIT', 'Tutto questo è alquanto imbarazzante per un drago, ma potreste aiutarmi a uscire da qui?', '', 28153),
(159660, 'itIT', 'Grazie, amici. Queste isole pullulano di oggetti magici degni del mio tempo e della mia attenzione. Certo, se ci fossero un po\' meno trappole...', '', 28153),
(159659, 'itIT', 'Aiutate Due Calzini, fate del bene e avrete in cambio tanti portabene!', '', 28153),
(159658, 'itIT', 'Due Calzini è libero! Oggi avrete tanta fortuna, amici! È nel vostro destino, ora!', '', 28153),
(159657, 'itIT', '', 'Oh, Tweets, sei di nuovo nei guai! Devo trovare un modo per cavarmela...', 28153),
(159656, 'itIT', '', 'Siete i migliori! Ma non smetterò mai di esplorare il mondo, mai! Se non lo facessi, non sarei Tweets Brillamolla!!!', 28153),
(159655, 'itIT', 'Meccanismo di gratitudine attivato. Distribuzione gratitudine. Gratitudine distribuita.', '', 28153),
(159654, 'itIT', 'Ostruzione dei circuiti. Inizializzazione modalità aiuto. AIUTO AIUTO AIUTO AIUTO AIUTO AIUTO AIUTO.', '', 28153),
(159653, 'itIT', '', 'Ehi, cumpà, che ci fate accà? Potete aiutarmi con chesto casino?', 28153),
(159652, 'itIT', '', 'Ah, mo\' va meglio. Tenete davvero na bella capa, ecco qualcosa per voi.', 28153),
(159651, 'itIT', 'Ehi, voi! Vi va di darmi una mano? Giuro che NON faccio più parte della Legione. Quei tizi se ne sono andati. Ora ci sono solo io, Sylvester, l\'Imp Onesto.', '', 28153),
(159650, 'itIT', 'Accidenti, non so davvero come ringraziarvi... quindi, addio. Non seguitemi.', '', 28153),
(159649, 'itIT', '', 'Ciao! Salve? Ehi, sì, ciao. Potete aiutarmi? Non so cosa fare qui. Mi sento un po\' persa.', 28153),
(159648, 'itIT', '', 'Grazie! Davvero, grazie mille. Sapete dove ci troviamo? Non ricordo nemmeno cosa stessi facendo. Dov\'è la mia barca? Ce l\'avevo una barca, vero?', 28153),
(159647, 'itIT', 'Ho bisogno d\'aiuto! Qualcuno riesce a sentirmi?', '', 28153),
(159646, 'itIT', 'Ah, grazie, amici pescatori. Come avete fatto ad arrivare fin qui? Non importa, ho capito, avete da fare.', '', 28153),
(159645, 'itIT', 'La grande città di Dazar\'alor è la migliore di tutto il mondo. I numerosi distretti suoi sono colmi di meraviglie e divertimenti. Li abitanti suoi sono i più forti e più saggi.\n\nSta\' solo accuort\' al vudù!', 'La grande città di Dazar\'alor è la migliore di tutto il mondo. I numerosi distretti suoi sono colmi di meraviglie e divertimenti. Li abitanti suoi sono i più forti e più saggi.\n\nSta\' solo accuort\' al vudù!', 28153),
(159644, 'itIT', 'Accidenti, e adesso? Mmm. Pensa, pensa.', '', 28153),
(159643, 'itIT', 'Grazie, amici. Ormai ho perso il conto delle volte che mi è successo. Forse un giorno imparerò, ma sembra che oggi non sia quel giorno. Ahah! Tenete. Non è molto, ma è tutto ciò che ho da offrirvi.', '', 28153),
(159642, 'itIT', 'Gregg ha bisogno di aiuto! Qualcuno aiuti Gregg!', '', 28153),
(159641, 'itIT', 'Voi aiutato Gregg! Gregg felice. Gregg dà voi rocce! Gregg ama rocce.', '', 28153),
(159640, 'itIT', 'Ehi, voi. Vi va di aiutare il vecchio Frankie? Forse può darvi in cambio qualcosa che volete? Che ne dite?', '', 28153),
(159639, 'itIT', 'Ah, ora va meglio. Non avrei mai pensato di essere salvato da gente come voi, ma la vita a volte ti sorprende. Ecco dell\'Azerite per il disturbo e non dite a nessuno di aver visto il vecchio Frankie.', '', 28153),
(159638, 'itIT', 'Sì! Fremistoppino ringraziare voi! Ecco, voi prendere gemme!', '', 28153),
(159637, 'itIT', 'Ehi! Voi! Aiutatemi! Aiuto!!!', '', 28153),
(159636, 'itIT', 'Ehi, Brul! Ho bisogno di aiuto qui!', '', 28153),
(159635, 'itIT', 'Forse ho messo troppi pesi sul bilanciere questa volta. Grazie, Brul.', '', 28153),
(159634, 'itIT', 'Emissario dell\'Impero degli Zandalari', 'Emissario dell\'Impero degli Zandalari', 28153),
(159633, 'itIT', '', 'Oh, grazie! Siete davvero i migliori. Cercherò di non rifarlo.', 28153),
(159632, 'itIT', '', 'Guarda in che guaio ti sei cacciata questa volta, Karyn. Oh, cosa farò adesso?', 28153),
(159631, 'itIT', 'Troverai Kojo il Collezionista all\'Emporio degli Scambiascaglie, a nord-est della città.\n\nFai attenzione con chel mojo tortolliano. È roba strana.', 'Troverai Kojo il Collezionista all\'Emporio degli Scambiascaglie, a nord-est della città.\n\nFai attenzione con chel mojo tortolliano. È roba strana.', 28153),
(159630, 'itIT', 'Emissario dei Cercatori Tortolliani', 'Emissario dei Cercatori Tortolliani', 28153),
(159629, 'itIT', 'Ne conosco parecchi. Quale stai cercando?', 'Ne conosco parecchi. Quale stai cercando?', 28153),
(159628, 'itIT', 'Punti d\'Interesse', 'Punti d\'Interesse', 28153),
(159627, 'itIT', '$gBenvenuto:Benvenuta; nella mia umile dimora, $C. Ti auguro di riposare... in pace.', '', 28153),
(159626, 'itIT', 'Non più. Lascia che ti spieghi...', '', 28153),
(159625, 'itIT', '', 'Non c\'è tempo per piangere le nostre vittime. I Mag\'har fonderanno una nuova casa. Qui.', 28153),
(159624, 'itIT', 'Il portale verso Azeroth starà aperto abbastanza a lungo affinché i tuoi soldati si preparino al viaggio e lo attraversino.', '', 28153),
(159623, 'itIT', 'Aka\'magosh, Geya\'rah. Informerò tua madre della tua scelta. Buon viaggio, Eitrigg. Anche a te, $n.', '', 28153),
(159622, 'itIT', '', 'Ti do il benvenuto, $n! L\'avamposto è ai tuoi ordini.', 28153),
(159621, 'itIT', 'È stato bello sentire di nuovo il terreno roccioso di Draenor sotto i miei piedi in battaglia...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159620, 'itIT', '', 'Avete già aperto un passaggio per Draenor. In fondo al mio cuore so che troveremo un modo per tornare.', 28153),
(159619, 'itIT', 'La magia per portarvi ad Azeroth è instabile. Forse non basterà per farvi tornare a casa.', '', 28153),
(159618, 'itIT', 'Hai la nostra gratitudine, $n. Preparati a tornare a...', '', 28153),
(159617, 'itIT', 'Sapevo che una volta combattuto al loro fianco in battaglia, ti saresti voluta unire a questi eroi, Geya\'rah. Hai la mia benedizione.', '', 28153),
(159616, 'itIT', '', 'Il Capoguerra penserà ai Draenei e a quei traditori dei Vincolaluce. I Mag\'har vi aiuteranno a vincere la vostra guerra, così il nostro debito sarà saldato.', 28153),
(159615, 'itIT', 'Tu, Suprema? Che ne sarà della tua gente che combatte qui?', '', 28153),
(159614, 'itIT', '', 'Me. Assieme a dei volontari. Con il tuo permesso, Capoguerra.', 28153),
(159613, 'itIT', 'Ora, per ripagare il debito che abbiamo nei confronti dell\'Orda, manderemo...', '', 28153),
(159612, 'itIT', '', 'Hanno combattuto con coraggio. Lo ammetto... Il mio giudizio nei tuoi confronti è stato affrettato, Eitrigg. Vale lo stesso anche per te, $n.', 28153),
(159611, 'itIT', 'Saremo pronti. E che mi dici di questi eroi di Azeroth? Ti sono stati d\'aiuto?', '', 28153),
(159610, 'itIT', '', 'L\'attacco dei Draenei è stato sventato, Capoguerra. Ma la Gran Esarca non si fermerà. I fanatici non lo fanno mai.', 28153),
(159609, 'itIT', 'Se i pirati sono partiti da Covo della Libertà, potremmo trovare altre informazioni lì. Forse conosco qualcuno che può aiutarci.', '', 28153),
(159608, 'itIT', '', 'Forse... forse hai ragione, Genn. Ma in ogni caso abbiamo ancora pochi indizi su cui lavorare.', 28153),
(159607, 'itIT', 'Potrebbero non essere ancora arrivati a destinazione. Potrebbe non essere troppo tardi, Katherine.', '', 28153),
(159606, 'itIT', 'Il contratto prevedeva di portare Jaina da qualche parte, non di ucciderla.', '', 28153),
(159605, 'itIT', '', 'Come puoi pensarlo?', 28153),
(159604, 'itIT', '', 'Ci rivediamo all\'accampamento, $n.', 28153),
(159603, 'itIT', '', 'Ha pagato dei pirati per giustiziare mia figlia, Genn! Pirati! La feccia dei mari!', 28153),
(159602, 'itIT', '', 'Il tempo stringe e tutto ciò che abbiamo è un contratto di Priscilla con alcuni pirati fuori dal Covo della Libertà!', 28153),
(159601, 'itIT', 'Riflettici, Katherine, potrebbero essere buone notizie.', '', 28153),
(159600, 'itIT', '', 'Ma... sei davvero...', 28153),
(159599, 'itIT', '', 'Solo noi possiamo accedere a questi piani di battaglia. È ora di morire, Troll del Sangue!', 28153),
(159598, 'itIT', 'Non puoi... essere $gun:una; Troll... del Sangue...', '', 28153),
(159597, 'itIT', 'Troll del Sangue! Ahahah, siete troppo stupidi per comprendere i segreti dell\'Alleanza.', '', 28153),
(159596, 'itIT', '', 'Tu... non sei... $gun:una; Troll del Sangue!', 28153),
(159595, 'itIT', '', '$gUn:Una; Troll del Sangue? Mi occuperò di questa seccatura prima di portare i piani agli Zandalari.', 28153),
(159594, 'itIT', 'Ora ho uno strano odore!', 'Non voglio più giocare a questo gioco!', 28153),
(159593, 'itIT', 'Ce li ha venduti un ometto verde alla spiaggia!', 'Ce li ha venduti un ometto verde alla spiaggia!', 28153),
(159592, 'itIT', 'La milizia è sempre qui a difenderci! Be\', a parte adesso. Sono andati a un qualche incontro importante con i Saggi delle Maree. A volte possono mettere soggezione, ma Fratello Pike è sempre gentilissimo quando ci fa visita.', 'La milizia è sempre qui a difenderci! Be\', a parte adesso. Sono andati a un qualche incontro importante con i Saggi delle Maree. A volte possono mettere soggezione, ma Fratello Pike è sempre gentilissimo quando ci fa visita.', 28153),
(159591, 'itIT', 'È stata tutta un\'idea di Grettle!', 'Ne vuoi uno come animaletto da compagnia?', 28153),
(159590, 'itIT', 'Perché l\'hanno chiamata Sacraonda? Non vedo onde qui in giro.$b$bGli adulti sono davvero strani.', 'Perché l\'hanno chiamata Sacraonda? Non vedo onde qui in giro.$b$bGli adulti sono davvero strani.', 28153),
(159589, 'itIT', 'Hai provato le bivalvi al vapore? Sono la specialità di Sacraonda!', 'Hai provato le bivalvi al vapore? Sono la specialità di Sacraonda!', 28153),
(159588, 'itIT', 'Adoro visitare la Distilleria dei Mildenhall! I miei genitori dicono che sono troppo giovane per l\'idromele, ma mi danno sempre un favo da mangiare!', 'Adoro visitare la Distilleria dei Mildenhall! I miei genitori dicono che sono troppo giovane per l\'idromele, ma mi danno sempre un favo da mangiare!', 28153),
(159587, 'itIT', 'Chissà se crescerò grande come mamma e papà. Loro mangiano sempre le verdure. Forse dovrei farlo anch\'io...', 'Chissà se crescerò grande come mamma e papà. Loro mangiano sempre le verdure. Forse dovrei farlo anch\'io...', 28153),
(159586, 'itIT', 'I miei genitori lavorano duramente per far sì che tutti abbiano da mangiare. Il cibo è davvero buono!', 'I miei genitori lavorano duramente per far sì che tutti abbiano da mangiare. Il cibo è davvero buono!', 28153),
(159585, 'itIT', 'Salve, $gsignore:signora;! Sei $gnuovo:nuova; della valle?', 'Salve, $gsignore:signora;! Sei $gnuovo:nuova; della valle?', 28153),
(159584, 'itIT', 'Spero che nessuno l\'abbia visto.', 'Fai finta che non sia mai successo!', 28153),
(159583, 'itIT', 'Ci siamo fidati della guida dei Saggi delle Maree per generazioni. Il mare dona loro saggezza, ne sono più che certo.', 'Ci siamo fidati della guida dei Saggi delle Maree per generazioni. Il mare dona loro saggezza, ne sono più che certa.', 28153),
(159582, 'itIT', 'Ho passato giorni migliori.', 'Non parliamone con nessuno.', 28153),
(159581, 'itIT', 'Hai avuto modo di provare le delizie della valle? Prova il nostro pane fresco con della salsiccia di Drustvar. Butta tutto giù con bel boccale di idromele... mi viene l\'acquolina in bocca solo a pensarci.', 'Hai avuto modo di provare le delizie della valle? Prova il nostro pane fresco con della salsiccia di Drustvar. Butta tutto giù con bel boccale di idromele... mi viene l\'acquolina in bocca solo a pensarci.', 28153),
(159580, 'itIT', 'Una volta avevamo la milizia a proteggerci. Mi chiedo cosa li abbia spinti ad andarsene...', 'Una volta avevamo la milizia a proteggerci. Mi chiedo cosa li abbia spinti ad andarsene...', 28153),
(159579, 'itIT', 'Lavoriamo nei campi per dar da mangiare a tutta Kul Tiras. È un lavoro duro, ma ne vale la pena!', 'Lavoriamo nei campi per dar da mangiare a tutta Kul Tiras. È un lavoro duro, ma ne vale la pena!', 28153),
(159578, 'itIT', 'Viviamo grazie alla terra, ma siamo comunque figli del mare.', 'Viviamo grazie alla terra, ma siamo comunque figli del mare.', 28153),
(159577, 'itIT', 'Che i mari ti guidino, $gstraniero:straniera;.', 'Che i mari ti guidino, $gstraniero:straniera;.', 28153),
(159576, 'itIT', 'Ti do il benvenuto nella valle!', 'Ti do il benvenuto nella valle!', 28153),
(159575, 'itIT', 'Ah, $n. Sei $garrivato:arrivata;. Alcuni dei Marefiero sono riusciti a passare, eliminali.', '', 28153),
(159574, 'itIT', '', 'Comincio a non star più nella pelle. Permettimi di aiutarti dalle ombre.', 28153),
(159573, 'itIT', '', 'Mamma, dov\'è papà?', 28153),
(159572, 'itIT', 'Salve, $R. Desideri riforgiare qualcosa?\n\nIl potere dell\'Azerite non conosce limiti. Per tua fortuna, lo stesso non vale per i miei prezzi.', '', 28153),
(159571, 'itIT', '', 'Venite, campioni di Azeroth. Dobbiamo informare il Capoguerra della nostra vittoria...', 28153),
(159570, 'itIT', '', 'La tua Gran Esarca non è riuscita a salvarti. La mia gente continuerà a combattere finché tutta Draenor sarà libera!', 28153),
(159569, 'itIT', 'Yrel... Ti ho delusa...', '', 28153),
(159568, 'itIT', 'Questa terra un tempo fertile ora è solo polvere senza vita. Questo è ciò che il vostro odio ha causato!', '', 28153),
(159567, 'itIT', '', 'Le nostre cicatrici non vi appartengono!', 28153),
(159566, 'itIT', 'Rinunciate al vostro odio! La Luce può curare le ferite della guerra!', '', 28153),
(159565, 'itIT', '', 'Volevi dire sottomissione!?!', 28153),
(159564, 'itIT', 'I Naaru offrono pace e ordine!', '', 28153),
(159563, 'itIT', 'Per Draenor! Per i Mag\'har!', '', 28153),
(159562, 'itIT', '', 'Sono stanca di tutto questo blaterare! L\'unico giudizio che ammetto è quello del campo di battaglia!', 28153),
(159561, 'itIT', 'La Gran Esarca vi ordina di sottomettervi... o affronterete il giudizio finale!', '', 28153),
(159560, 'itIT', '', 'Ritiratevi finché siete in tempo! Non ci obbligherete a seguire la vostra dottrina!', 28153),
(159559, 'itIT', 'Basta con questa inutile ribellione, Mag\'har! Arrendetevi e abbracciate la Luce!', '', 28153),
(159558, 'itIT', 'Siamo con te, Geya\'rah!', '', 28153),
(159557, 'itIT', '', 'Stanno attaccando il Forte di Vespreterno! Con me, eroi!', 28153),
(159556, 'itIT', 'La Gran Esarca vuole solo il meglio per tutti noi!', 'La Gran Esarca vuole solo il meglio per tutti noi!', 28153),
(159555, 'itIT', 'La Luce ci ha salvati e può salvare anche voi!', 'La Luce ci ha salvati e può salvare anche voi!', 28153),
(159554, 'itIT', 'Il tempo di Grommash è giunto al termine. Abbracciate un nuovo futuro!', 'Il tempo di Grommash è giunto al termine. Abbracciate un nuovo futuro!', 28153),
(159553, 'itIT', 'Unitevi a noi nella Luce, fratelli e sorelle!', 'Unitevi a noi nella Luce, fratelli e sorelle!', 28153),
(159552, 'itIT', 'Possiamo salvare Draenor insieme!', 'Possiamo salvare Draenor insieme!', 28153),
(159551, 'itIT', 'Avete rovinato questa terra, ma non è troppo tardi per salvarla!', 'Avete rovinato questa terra, ma non è troppo tardi per salvarla!', 28153),
(159550, 'itIT', 'Ammirate le visioni della Gran Esarca!', 'Ammirate le visioni della Gran Esarca!', 28153),
(159549, 'itIT', 'Siamo venuti a salvarvi dalla vostra brutalità!', 'Siamo venuti a salvarvi dalla vostra brutalità!', 28153),
(159548, 'itIT', 'Arrendetevi, Mag\'har! Abbracciate la Luce!', 'Arrendetevi, Mag\'har! Abbracciate la Luce!', 28153),
(159547, 'itIT', 'Ti do il benvenuto.', '', 28153),
(159546, 'itIT', '', 'Abbattete la corruzione della Luce!', 28153),
(159545, 'itIT', '', 'La vostra Luce non è la benvenuta qui, Draenei!', 28153),
(159544, 'itIT', '', 'Mantenete la posizione! Questa terra appartiene ai Mag\'har!', 28153),
(159543, 'itIT', 'Akunda dà il benvenuto a tutti.', '', 28153),
(159542, 'itIT', '', 'Distruggete le Batterie d\'Assedio!', 28153),
(159541, 'itIT', '', 'Allora combatteremo insieme per il sangue e l\'onore! Con me, eroi!', 28153),
(159540, 'itIT', 'Non mi sono mai tirato indietro di fronte a una battaglia. Non intendo iniziare oggi.', '', 28153),
(159539, 'itIT', '', 'Questa non è la vostra guerra, stranieri. Siete liberi di tornare su Azeroth.', 28153),
(159538, 'itIT', 'Stiamo mantenendo la posizione, Suprema. Ma sembra che il nemico si stia preparando per un attacco massiccio.', '', 28153),
(159537, 'itIT', '', 'Lantresor! Rapporto!', 28153),
(159536, 'itIT', 'Puoi anche attaccare i nemici con un Tiro Lacerante, facendoli sanguinare per un periodo di tempo.', '', 28153),
(159535, 'itIT', 'Combatteremo con te, Suprema!', '', 28153),
(159534, 'itIT', '', 'Non rimarrò con le mani in mano mentre la Gran Esarca guida la sua crociata contro la libertà dei Mag\'har! La tirannia della Luce deve finire!', 28153),
(159533, 'itIT', '', 'Alcuni Orchi si unirono ai Draenei in combattimento contro la loro stessa razza... Persino il figlio del Capoguerra subì la stessa sorte! Questi traditori vengono chiamati Vincolaluce.', 28153),
(159532, 'itIT', '', 'I loro padroni Naaru li costrinsero a diffondere la loro influenza sugli Orchi. Alcuni si convertirono spontaneamente. Altri invece furono forzati per mezzo della Luce.', 28153),
(159531, 'itIT', '', 'Ma senza demoni da combattere, i Draenei furono ossessionati dalla loro preziosa Luce.', 28153),
(159530, 'itIT', '', 'Dopo la caduta di Archimonde, gli Orchi e i Draenei hanno lavorato assieme per spazzare via la Legione da Draenor. È stato un bel periodo.', 28153),
(159529, 'itIT', '', 'Direi che ve lo siete guadagnato.', 28153),
(159528, 'itIT', 'È tempo che ci spieghi chi sono questi Vincolaluce, Suprema.', '', 28153),
(159527, 'itIT', '', 'Bene! Avevo proprio bisogno di un\'altra testa di Esarca sul muro. Venite, stranieri!', 28153),
(159526, 'itIT', 'C\'è un Esarca a guidarli e il loro numero è... considerevole.', 'C\'è un Esarca a guidarli e il loro numero è... considerevole.', 28153),
(159525, 'itIT', '', 'Maledetti traditori! Quanti sono?', 28153),
(159524, 'itIT', 'Suprema Geya\'rah! i Vincolaluce stanno attaccando Roccabestia!', 'Suprema Geya\'rah! i Vincolaluce stanno attaccando Roccabestia!', 28153),
(159523, 'itIT', 'Ecco. Ora sei... $gun:una; Troll del Sangue. Almeno temporaneamente.', '', 28153),
(159522, 'itIT', 'Ma non possiamo rischiare che anche un solo membro dell\'Alleanza venga visto al Porto da Guerra dei Rastari.', '', 28153),
(159521, 'itIT', 'Mi scuso per il dolore e la scomodità di questo rituale, $n.', '', 28153),
(159520, 'itIT', 'Umbric, sono pronto a diventare un Troll del Sangue.', 'Umbric, sono pronta a diventare una Troll del Sangue.', 28153),
(159519, 'itIT', 'Dicono che Pin\'jin sia uno dei Troll più pazienti che siano mai esistiti. Con tutti i nobili che continuano a infastidirlo riguardo i loro bei vestiti, esserlo mi pare il minimo.\n\nSe tieni la pazienza di imparare da lui, raggiungi la Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.', 'Dicono che Pin\'jin sia uno dei Troll più pazienti che siano mai esistiti. Con tutti i nobili che continuano a infastidirlo riguardo i loro bei vestiti, esserlo mi pare il minimo.\n\nSe tieni la pazienza di imparare da lui, raggiungi la Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.', 28153),
(159517, 'itIT', 'Credi sia facile scuoiare n\'Anchilodonte? Nun lo è! Se vuoi imparare, devi andare da Rakna.\n\nDa quanto ne so, è appena tornata in città. La troverai alla Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.\n\nSii gentile, o potrebbe decidere di scuoiare pure te!', 'Credi sia facile scuoiare n\'Anchilodonte? Nun lo è! Se vuoi imparare, devi andare da Rakna.\n\nDa quanto ne so, è appena tornata in città. La troverai alla Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.\n\nSii gentile, o potrebbe decidere di scuoiare pure te!', 28153),
(159515, 'itIT', 'Che vuoi da chel ladruncolo di Secott? Nun l\'abbiamo ancora catturato, ma sappiamo che ruba oro da Atal\'dazar! I Loa gliela faranno pagare, e se non lo faranno loro, ci penserò io.\n\nPuoi trovare l\'\"amichetto\" tuo alla Terrazza delli Artigiani. Vi terremo d\'occhio entrambi.', 'Che vuoi da chel ladruncolo di Secott? Nun l\'abbiamo ancora catturato, ma sappiamo che ruba oro da Atal\'dazar! I Loa gliela faranno pagare, e se non lo faranno loro, ci penserò io.\n\nPuoi trovare l\'\"amichetto\" tuo alla Terrazza delli Artigiani. Vi terremo d\'occhio entrambi.', 28153),
(159513, 'itIT', 'Xanjo piglia le pelli che gli porta Rakna per creare alcune tra le più belle armature che tu abbia mai visto.\n\nLo troverai alla Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.', 'Xanjo piglia le pelli che gli porta Rakna per creare alcune tra le più belle armature che tu abbia mai visto.\n\nLo troverai alla Terrazza delli Artigiani, sul lato occidentale di Dazar\'alor.', 28153),
(159511, 'itIT', 'La nostra Seshuli crea i migliori gioielli dei Mari del Sud. È lei che ti insegnerà tutto, puoi trovarla nella Sala dei Bagliori.\n\nPer arrivarci, vai alla Terrazza delli Artigiani sul lato occidentale inferiore di Dazar\'alor, poi vai a est e segui la galleria dentro la piramide. È impossibile nun vederla, con tutte chelle cose luccicanti che ci stanno laggiù.', 'La nostra Seshuli crea i migliori gioielli dei Mari del Sud. È lei che ti insegnerà tutto, puoi trovarla nella Sala dei Bagliori.\n\nPer arrivarci, vai alla Terrazza delli Artigiani sul lato occidentale inferiore di Dazar\'alor, poi vai a est e segui la galleria dentro la piramide. È impossibile nun vederla, con tutte chelle cose luccicanti che ci stanno laggiù.', 28153),
(159509, 'itIT', '', 'Prendi il mio ippogrifo e dirigiti a Darnassus. Assicurati che l\'occupazione dell\'Orda sia... sopportabile.', 28153),
(159506, 'itIT', 'Li storiografi viaggiano in lungo e in largo per conoscere la verità sul mondo. Chella che cerchi si chiama Kizani.\n\nLa troverai in cima alle scale del Gran Sigillo, nella Sala delli Storiografi.', 'Li storiografi viaggiano in lungo e in largo per conoscere la verità sul mondo. Chella che cerchi si chiama Kizani.\n\nLa troverai in cima alle scale del Gran Sigillo, nella Sala delli Storiografi.', 28153),
(159504, 'itIT', 'Jahden Fla è sempre impegnato a curare i fiori suoi alla Terrazza delli Artigiani, che si trova sul lato occidentale di Dazar\'alor.\n\nNun scherzava quando diceva di tenere il pollice verde.', 'Jahden Fla è sempre impegnato a curare i fiori suoi alla Terrazza delli Artigiani, che si trova sul lato occidentale di Dazar\'alor.\n\nNun scherzava quando diceva di tenere il pollice verde.', 28153),
(159503, 'itIT', 'La guerra ci mette alla prova. Ci costringe a mettere in dubbio il nostro onore, le nostre convinzioni.\n\nSono venuto a Zuldazar per assicurarmi che nel mezzo di questo scontro, l\'Orda non perda di vista ciò che ci definisce.\n\nConfido che tu non lo dimenticherai, Voce dell\'Orda.', '', 28153),
(159502, 'itIT', 'Devo diventare più forte!', '', 28153),
(159500, 'itIT', 'Spero vada tutto bene, $p.', '', 28153),
(159499, 'itIT', 'Grazie a te, inizierò ad addestrarmi per diventare un coraggioso guerriero. Voglio poter difendere il nostro villaggio!', '', 28153),
(159498, 'itIT', 'La nonna non smette mai di dirmi quanto avrebbe voluto che fossi più come te...', '', 28153),
(159497, 'itIT', 'Sono... solo felice che sei $garrivato:arrivata; al momento giusto.', '', 28153),
(159496, 'itIT', 'Vuoi imparare a pescare? Allora devi andare da Tali la Silente. Si trova alla Scheggia, a nord di Dazar\'alor.\n\nRicorda solo di nun fare rumore o spaventerai tutti i pesci suoi.', 'Vuoi imparare a pescare? Allora devi andare da Tali la Silente. Si trova alla Scheggia, a nord di Dazar\'alor.\n\nRicorda solo di nun fare rumore o spaventerai tutti i pesci suoi.', 28153),
(159495, 'itIT', 'Non voglio deludere la nonna, ma non sono tagliato per questo... Voglio solo che le cose tornino alla normalità.', '', 28153),
(159494, 'itIT', 'Attenzione alla testa, stanno cadendo rocce dal cielo!', '', 28153),
(159492, 'itIT', 'Ci sta nu Goblin di nome Shuga che insegna chelle cose alla Terrazza delli Artigiani, fuori dal lato occidentale di Dazar\'alor.\n\nSpero tu nun tenga intenzione di far esplodere nulla di importante. A noi Zuldazar piace così com\'è.', 'Ci sta nu Goblin di nome Shuga che insegna chelle cose alla Terrazza delli Artigiani, fuori dal lato occidentale di Dazar\'alor.\n\nSpero tu nun tenga intenzione di far esplodere nulla di importante. A noi Zuldazar piace così com\'è.', 28153),
(159491, 'itIT', 'Hanno ucciso la mia mucca!', 'Hanno ucciso la mia mucca!', 28153),
(159489, 'itIT', 'Questa non è la mia prima battaglia!', 'Questa non è la mia prima battaglia!', 28153),
(159488, 'itIT', 'Aiuterò al meglio delle mie capacità!', 'Aiuterò al meglio delle mie capacità!', 28153),
(159487, 'itIT', 'Lasciateli a me!', 'Lasciateli a me!', 28153),
(159486, 'itIT', 'Avranno ciò che meritano!', 'Avranno ciò che meritano!', 28153),
(159485, 'itIT', 'Sì! Pagheranno per questo!', 'Sì! Pagheranno per questo!', 28153),
(159484, 'itIT', 'Stai cercando n\'Elfa del Sangue chiamata Incantatrice Quinni. Puoi trovarla alla base occidentale di Dazar\'alor, alla Terrazza delli Artigiani. Na volta lì, guarda la piramide e scendi giù nella Sala dei Bagliori.', 'Stai cercando n\'Elfa del Sangue chiamata Incantatrice Quinni. Puoi trovarla alla base occidentale di Dazar\'alor, alla Terrazza delli Artigiani. Na volta lì, guarda la piramide e scendi giù nella Sala dei Bagliori.', 28153),
(159482, 'itIT', '', 'L\'eredità fallimentare dei Marefiero morirà con te!', 28153),
(159481, 'itIT', '', 'La tua famiglia è sempre stata troppo debole.', 28153),
(159480, 'itIT', '', 'E ne abbiamo le prove!', 28153),
(159479, 'itIT', '', 'Mi caricherò io sulle spalle questo fardello. Spero solo di esserne degna.', 28153),
(159478, 'itIT', 'Chi cerchi è la Chef Reale, T\'sarah. La troverai a Dazar\'alor presso la locanda Braciami Ancora, vicino al Gran Sigillo.', 'Chi cerchi è la Chef Reale, T\'sarah. La troverai a Dazar\'alor presso la locanda Braciami Ancora, vicino al Gran Sigillo.', 28153),
(159476, 'itIT', '', 'La mia amica Priscilla e io ne abbiamo parlato. Ritengo che sia meglio per Kul Tiras... che io... abbandoni la carica di Ammiraglio Supremo...', 28153),
(159475, 'itIT', '', 'Per tutta la vita, Katherine Marefiero ha sempre fatto il possibile per Kul Tiras!', 28153),
(159473, 'itIT', 'Muori, feccia dell\'Orda!', 'Muori, feccia dell\'Orda!', 28153),
(159472, 'itIT', 'Vi rispedirò dalla vostra Capoguerra in tanti piccoli pezzi!', 'Vi rispedirò dalla vostra Capoguerra in tanti piccoli pezzi!', 28153),
(159471, 'itIT', 'Non ci sconfiggerete mai!', 'Non ci sconfiggerete mai!', 28153),
(159470, 'itIT', 'Boralus non cadrà!', 'Boralus non cadrà!', 28153),
(159469, 'itIT', 'Per Boralus!', 'Per Boralus!', 28153),
(159468, 'itIT', 'Tieni duro, $p. Alalesta ci porterà lì in men che non si dica.', '', 28153),
(159467, 'itIT', '', 'Il brivido della caccia... Non c\'è nulla di meglio.', 28153),
(159466, 'itIT', '', '<Pa\'ku osserva Kua\'fon e sospira.>', 28153),
(159465, 'itIT', 'Andiamo, Alalesta! Torniamo tra le nuvole, la nostra vera casa.', '', 28153),
(159464, 'itIT', 'Chiusura', 'Chiusura', 28153),
(159463, 'itIT', 'È ESSENZIALE inviare i comandi d\'accensione da una posizione con visuale diretta su tutti i punti delle esplosioni. Sfortunatamente, devo verificare manualmente che tutti i parametri siano impostati correttamente ed è una cosa che non si può fare in nessun posto fuorché qui.\n\nPer farla breve, devi salire a bordo della Macchina Volante e premere il grosso pulsante rosso quando ti dico di farlo.', '', 28153),
(159462, 'itIT', '', 'Basta chiacchiere! Muoviamoci!', 28153),
(159461, 'itIT', 'Vincolaluce?', '', 28153),
(159460, 'itIT', '', 'Mia madre è al comando di una guarnigione a Nagrand. Mio padre è caduto in battaglia contro i Vincolaluce.', 28153),
(159459, 'itIT', 'Sei la figlia di Durotan e Draka. Riesco a vedere entrambi in te. I tuoi genitori sono ancora...', '', 28153),
(159458, 'itIT', '', 'Non mi serve l\'aiuto di qualche straniero... ma farò come comandi. Andiamo!', 28153),
(159457, 'itIT', 'Eitrigg e $n ti aiuteranno ad abbattere l\'istigatore Ogre, Geya\'rah.', '', 28153),
(159456, 'itIT', 'Durotan era in debito con questi eroi, Geya\'rah, proprio come me. Stai disonorando lo spirito di tuo padre con questo tuo sfogo. Eppure... mi hai dato un\'idea...', '', 28153),
(159455, 'itIT', '', 'Ci credi stupidi? Capoguerra, non possiamo fornire i nostri soldati a questa gente venuta da un altro mondo. Non quando dobbiamo affrontare dei nemici noi stessi!', 28153),
(159454, 'itIT', 'Degli eroi del mio mondo un tempo liberarono la tua gente dalla stretta dei tiranni. Ora Azeroth si trova di fronte a una minaccia simile, quindi siamo venuti a chiederti di ripagare quel debito.', '', 28153),
(159453, 'itIT', 'Eccoci qua dunque... due vecchi fantasmi. Perché sei tornato su Draenor dopo tutto questo tempo?', '', 28153),
(159452, 'itIT', 'E il Grommash Malogrido che conoscevo io diede la sua vita per liberarci dalla morsa dei demoni. Una degna morte.', '', 28153),
(159451, 'itIT', 'Eitrigg... Conoscevo un Eitrigg che ha servito Manonera. Era un Orco onorevole morto in una gloriosa battaglia.', '', 28153),
(159450, 'itIT', 'Esatto. Sono Eitrigg e $gquesto:questa; è $n, $gcampione:campionessa; dell\'Orda.', '', 28153),
(159449, 'itIT', 'Sono passati molti anni dall\'ultima volta che ho visto un Orco dalla pelle verde. E questo al tuo fianco è... familiare. Vieni da Azeroth, vero?', '', 28153),
(159448, 'itIT', 'Basta! Giudicherò io i prigionieri, Geya\'rah.', '', 28153),
(159447, 'itIT', '', 'Le tue parole mi toccano il cuore, vecchio. Continuiamo a onorare la storia dei nostri clan, pur rimanendo uniti come Mag\'har. Tuttavia, dovete ancora dimostra...', 28153),
(159446, 'itIT', 'Durotan era il Capotribù del clan Lupi Bianchi. Non ho mai conosciuto un Orco così onorevole. Era un vero capo che amava la sua gente. Mi manca la sua saggezza.', '', 28153),
(159445, 'itIT', 'Il clan Cantaguerra ha combattuto per generazioni contro gli Ogre. Anche se in numero molto inferiore, Grommash Malogrido ha condotto la sua gente a una grande vittoria contro gli Altomaglio.', '', 28153),
(159444, 'itIT', 'I Roccianera... il mio clan. Eravamo fieri Orchi e feroci soldati. Ma siamo stati ingannati dalla vilmagia di Gul\'dan e abbiamo fatto... cose terribili.', '', 28153),
(159443, 'itIT', '', 'Ogni vero Orco è in grado di riconoscere i tre stendardi di questo accampamento. Ditemi cosa rappresentano o verrete giustiziati!', 28153),
(159442, 'itIT', '', 'C\'è solo un Capoguerra... e tu non fai parte dei Roccianera! Ma bando alle ciance, vediamo se dici la verità.', 28153),
(159441, 'itIT', 'Sono Eitrigg del clan Roccianera. Siamo venuti da Azeroth per conto della nostra Capoguerra.', '', 28153),
(159440, 'itIT', '', 'Lo vedremo. Parlate, intrusi. Chi siete?', 28153),
(159439, 'itIT', 'Sono spie dei Vincolaluce! Sporchi traditori!', 'Sono spie dei Vincolaluce! Sporchi traditori!', 28153),
(159438, 'itIT', '', 'Portatemeli.', 28153),
(159437, 'itIT', 'Suprema Geya\'rah! Abbiamo catturato dei prigionieri.', '', 28153),
(159436, 'itIT', 'La Suprema saprà cosa fare.', 'La Suprema saprà cosa fare.', 28153),
(159435, 'itIT', 'Fa\' attenzione. Per quel che ne sappiamo, possono essere spie dei Draenei.', '', 28153),
(159434, 'itIT', 'Pelle verde... disgustoso! Avevo sentito storie riguardo a questa corruzione, ma non l\'avevo mai vista dal vivo.', 'Pelle verde... disgustoso! Avevo sentito storie riguardo a questa corruzione, ma non l\'avevo mai vista dal vivo.', 28153),
(159433, 'itIT', 'Silenzio! La Suprema deciderà il vostro destino. Incatenateli!', '', 28153),
(159432, 'itIT', 'Fermi! Veniamo in pace per parlare con il vostro Capoguerra.', '', 28153),
(159431, 'itIT', 'Intrusi!', 'Intrusi!', 28153),
(159430, 'itIT', 'Perché vorresti andare a scavare in giro per le terre nostre? Se proprio devi, puoi trovare l\'Esaminatrice Alerinda al Gran Sigillo.', 'Perché vorresti andare a scavare in giro per le terre nostre? Se proprio devi, puoi trovare l\'Esaminatrice Alerinda al Gran Sigillo.', 28153),
(159429, 'itIT', 'Archeologia', 'Archeologia', 28153),
(159428, 'itIT', 'Che ci fa chesto vudù del Vuoto accà?', 'Che ci fa chesto vudù del Vuoto accà?', 28153),
(159427, 'itIT', 'Che è sto vudù?', 'Che cos\'è chesto vudù?', 28153),
(159426, 'itIT', 'Che razza di vudù oscuro è chesto?', 'Che razza di vudù oscuro è chesto?', 28153),
(159425, 'itIT', 'Andate. Ma fate attenzione a non perdervi tra i fili del fato.', '', 28153),
(159424, 'itIT', 'Manderò anche il frammento con voi. Quando sarete pronti, vi riporterà a casa.', '', 28153),
(159423, 'itIT', 'Riesci a tenere aperto il passaggio abbastanza a lungo da far passare gli Orchi di Draenor?', '', 28153),
(159422, 'itIT', 'I flussi del tempo e della realtà sono in continua evoluzione. L\'ancora del mondo che cerchi sarà alquanto esile.', '', 28153),
(159421, 'itIT', 'Come posso raggiungere Orgrimmar?', 'Come posso raggiungere Orgrimmar?', 28153),
(159420, 'itIT', 'La battaglia nostra accà è finita, ma la guerra continua.', '', 28153),
(159419, 'itIT', 'La nostra Capoguerra non tollererà scuse. A quanto pare $p dovrà recarsi a Tanaris. Le mie vecchie ossa devono riposare.', '', 28153),
(159418, 'itIT', 'Se il frammento non fosse esaurito, potrei usarlo per mandarti sulla strada giusta. Sfortunatamente, la mia specialità è il teletrasporto, non la cronomanzia.', '', 28153),
(159417, 'itIT', 'Devi raggiungere la Terrazza delli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nNun troverai nu fabbro migliore del Mastro Forgiatore Zak\'aal in tutta Azeroth!', 'Devi raggiungere la Terrazza delli Artigiani, sul lato occidentale inferiore di Dazar\'alor.\n\nNun troverai nu fabbro migliore del Mastro Forgiatore Zak\'aal in tutta Azeroth!', 28153),
(159416, 'itIT', '', 'La fauna è fantastica accà. Krag\'wa sta vicino. Mi chiedo se la presenza sua renda li animali ancora più forti. Ti va di mettere alla prova le mascotte tue con le mie?', 28153),
(159415, 'itIT', '', '<Pa\'ku ridacchia con fare minaccioso.>', 28153),
(159414, 'itIT', 'Che sollievo!', 'Che sollievo!', 28153),
(159413, 'itIT', 'Il dolore è svanito!', 'Il dolore è svanito!', 28153),
(159412, 'itIT', 'Ora mi sento molto meglio.', 'Ora mi sento molto meglio.', 28153),
(159411, 'itIT', 'Sarebbe un onore, Generale. $p, salta in groppa ad Alalesta non appena sei $gpronto:pronta;.', '', 28153),
(159410, 'itIT', '', 'Falstad, tu fai strada insieme a $p. Io cavalcherò Jai\'alator.', 28153),
(159409, 'itIT', 'Ahhh, mo\' capisco. Forse nun è destinato a volare tra le nuvole. Ma con te al fianco suo, terrà comunque na bella vita.', '', 28153),
(159408, 'itIT', 'Noi faremo strada. Abbiate fiducia gli uni degli altri e andrà tutto bene. Mo\', in volo!', '', 28153),
(159407, 'itIT', 'Nun preoccuparti! La creatura alata tua starà bene. Tengo nu piano.', '', 28153),
(159405, 'itIT', 'Kumali l\'Astuta produce ogni genere di mojo alla Terrazza delli Artigiani. Puoi trovarla alla base sul lato occidentale di Dazar\'alor.', 'Kumali l\'Astuta produce ogni genere di mojo alla Terrazza delli Artigiani. Puoi trovarla alla base sul lato occidentale di Dazar\'alor.', 28153),
(159404, 'itIT', 'Dato che i membri dell\'Orda hanno sfruttato i nostri esemplari servizi per così tanto tempo, abbiamo deciso di mettere a disposizione dei portali magici a coloro che si sono distinti, come te. Il viaggio non dovrebbe essere troppo doloroso.', 'Dato che i membri dell\'Orda hanno sfruttato i nostri esemplari servizi per così tanto tempo, abbiamo deciso di mettere a disposizione dei portali magici a coloro che si sono distinti, come te. Il viaggio non dovrebbe essere troppo doloroso.', 28153),
(159403, 'itIT', '', 'Ahahahah!', 28153),
(159402, 'itIT', '', 'Che il vento sia sempre alle tue spalle!', 28153),
(159401, 'itIT', 'Come posso raggiungere le Radure di Tirisfal?', 'Come posso raggiungere le Radure di Tirisfal?', 28153),
(159399, 'itIT', 'La Spezzatuoni è in manutenzione, ha preso fuoco una volta di troppo. Che peccato.', '', 28153),
(159398, 'itIT', 'Sì, Pa\'ku.', 'Sì, Pa\'ku.', 28153),
(159397, 'itIT', 'Teniamo i migliori istruttori di tutto il mondo. Li troverai quasi tutti sul lato occidentale inferiore di Dazar\'alor, sulla Terrazza delli Artigiani.\n\nStai cercando qualcuno in particolare?', 'Teniamo i migliori istruttori di tutto il mondo. Li troverai quasi tutti sul lato occidentale inferiore di Dazar\'alor, sulla Terrazza delli Artigiani.\n\nStai cercando qualcuno in particolare?', 28153),
(159396, 'itIT', '', 'Ahhh, sapevo che presto saresti $gvenuto:venuta; da me. È passato un po\' di tempo dall\'ultima lezione del tuo cucciolo.\n\nVieni, vediamo cos\'ha imparato.', 28153),
(159395, 'itIT', 'Istruttori', 'Istruttori', 28153),
(159394, 'itIT', 'Famigli, eh? Li unici famigli che vale la pena avere sono i figli dei Loa.\n\nCerca il Domatore di Bestie Kalatak vicino alla base nordoccidentale di Dazar\'alor.', 'Famigli, eh? Li unici famigli che vale la pena avere sono i figli dei Loa.\n\nCerca il Domatore di Bestie Kalatak vicino alla base nordoccidentale di Dazar\'alor.', 28153),
(159392, 'itIT', 'Se hai eseguito il volere di Re Rastakhan, allora Natal\'hakata potrebbe tenere qualcosa di buono per te al Gran Sigillo.', 'Se hai eseguito il volere di Re Rastakhan, allora Natal\'hakata potrebbe tenere qualcosa di buono per te al Gran Sigillo.', 28153),
(159391, 'itIT', 'Emissari', 'Emissari', 28153),
(159390, 'itIT', '', 'Tirisfal ha visto grandi potenze nascere e cadere. Mi chiedo... la tua razza imparerà mai davvero la lezione dalla sua storia?\n\nMa sto divagando.\n\nHai concluso i tuoi affari nel passato?', 28153),
(159389, 'itIT', '', 'Teldrassil... Che vista magnifica, non trovi? Spesso le cose più belle sono le più effimere, soprattutto quando vengono colpite dal fuoco.\n\nHai concluso i tuoi affari nel passato, $gcampione:campionessa;?', 28153),
(159388, 'itIT', 'Se pensi di poter riposare con chella cosa schiattata che ti danza attorno, puoi trovarla al Gran Sigillo.', 'Se pensi di poter riposare con chella cosa schiattata che ti danza attorno, puoi trovarla al Gran Sigillo.', 28153),
(159386, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis inizia a lanciare |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis inizia a lanciare |cFFFF0000|Hspell:267242|h[Contagio]|h|r!', 28153),
(159385, 'itIT', 'Tutte le richieste di asilo saranno gestite caso per caso.', '', 28153),
(159384, 'itIT', '', 'Da queste rive, puoi ammirare Teldrassil. Un tempo culla della vita, ora è solo un cumulo di cenere.\n\nAnche gli Alberi del Mondo devono sottostare al ciclo della vita. Tutto ciò che nasce deve morire.\n\nNessuno comprende tutto ciò meglio dello Stormo dei Draghi di Bronzo.\n\nVorresti vedere com\'era un tempo l\'albero?', 28153),
(159383, 'itIT', 'Purtroppo le nostre risorse sono ridotte all\'osso, al momento.', '', 28153),
(159382, 'itIT', 'Puoi trovare Paku\'ai sulla sporgenza fuori dal Gran Sigillo. Dove vuoi andare?', 'Puoi trovare Paku\'ai sulla sporgenza fuori dal Gran Sigillo. Dove vuoi andare?', 28153),
(159381, 'itIT', 'Un po\' di pazienza, per favore. Stiamo facendo tutto il possibile, date le circostanze.', '', 28153),
(159379, 'itIT', '', 'Tirisfal, un luogo di bellezza e oscurità. Una terra piena di rimorsi... e tombe.\n\nLa tua razza ha combattuto per conquistarla molte volte.\n\nHai concluso i tuoi affari nel passato?', 28153),
(159378, 'itIT', 'Mi stavo stancando della carne di capra.', '', 28153),
(159377, 'itIT', 'Chi viene?', '', 28153),
(159376, 'itIT', 'Possiamo accompagnare te e una piccola squadra in men che non si dica.', '', 28153),
(159375, 'itIT', '<Falstad Granmartello fischia e dei Cavalieri di Grifoni giungono in volo sul ponte.>', '', 28153),
(159374, 'itIT', 'La tua nave è troppo lenta per arrivare in tempo, ma la velocità non è un problema per i Granmartello.', '', 28153),
(159373, 'itIT', 'Se Dreven si trova a bordo di quella barca, non avrà modo di scappare... possiamo colpire prima che attracchino.', '', 28153),
(159372, 'itIT', '', 'Durante la mia caccia, ho scoperto che il Principe del Sangue Dreven sta viaggiando su una barca insieme a un Saggio delle Maree traditore.', 28153),
(159371, 'itIT', '', 'A dire il vero, credo che questa sia la nostra priorità più alta. Grazie, Mathias.', 28153),
(159370, 'itIT', '', '<Shandris Piumaluna plana sul ponte della nave in sella al suo ippogrifo.>', 28153),
(159369, 'itIT', 'Non ne siamo sicuri, ma posso inviare altri agenti a indagare. Comunque sia, ha una priorità bassa.', '', 28153),
(159368, 'itIT', 'Cosa starà cercando l\'Orda in quei vecchi relitti?', '', 28153),
(159367, 'itIT', 'Grazie, Mathias.', '', 28153),
(159366, 'itIT', 'Noi, naturalmente, abbiamo lasciato che gli originali arrivassero a destinazione, ma ne abbiamo fatta una copia.', '', 28153),
(159365, 'itIT', 'Gran Comandante, i miei agenti hanno intercettato degli ordini di Sylvanas.', '', 28153),
(159364, 'itIT', 'La mia gente non farà lo stesso errore sfruttando il Vuoto, lo prometto.', '', 28153),
(159363, 'itIT', '', 'Come hai detto tu, Umbric, ho vissuto a lungo. Ho visto il potere corrompere le razze più nobili... L\'equilibrio non è più un concetto comune.', 28153),
(159362, 'itIT', 'Sembri sorpresa. Pensavi forse che la mia gente usasse la magia del Vuoto per gioco?', '', 28153),
(159361, 'itIT', '', 'Usato per proteggere? Interessante, Umbric.', 28153),
(159360, 'itIT', 'Il Vuoto può essere usato per proteggere, fintanto che riesci a non soccombere al suo potere.', '', 28153),
(159359, 'itIT', '', 'Eppure non sembri esitante nell\'usare i tuoi poteri del Vuoto contro di loro.', 28153),
(159358, 'itIT', 'Tu e io abbiamo vissuto a lungo, Shandris. So quanti sono stati colpiti dalle barbarie degli Zandalari.', '', 28153),
(159357, 'itIT', '', 'Sembra che tu abbia già avuto esperienza con gli Zandalari in passato.', 28153),
(159356, 'itIT', 'La mia gente e io non permetteremo che l\'Alleanza venga distrutta da questi Troll mostruosi. Hai la mia parola.', '', 28153),
(159355, 'itIT', '', 'La quantità di guardie in questo porto è pazzesca. Si staranno preparando a muovere la flotta.', 28153),
(159354, 'itIT', '', 'Dovremo avvertire Halford immediatamente, dopo aver fatto sbarcare $n.', 28153),
(159353, 'itIT', 'Lo è, se consideri dov\'è diretta... proprio a portata di tiro del nostro avamposto a Xibala.', '', 28153),
(159352, 'itIT', '', 'Una sola nave? Non sembra un grande problema.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(159351, 'itIT', 'Abbiamo un problema. C\'è una nave che non avevamo considerato. Forse era di stanza a Pandaria.', '', 28153),
(159350, 'itIT', 'Vediamo. Pare che le informazioni di Halford fossero corrette riguardo la posizione della maggior parte delle navi, così come sulle rotte di navigazione. Eppure...', '', 28153),
(159349, 'itIT', '', 'Di solito non sbircio... ma per questa volta posso fare un\'eccezione. Vediamo...', 28153),
(159348, 'itIT', 'Qualche novità dai registri che $n ha recuperato?', '', 28153),
(159347, 'itIT', '', 'Buona fortuna! Il Porto da Guerra dei Rastari brulicherà di Zandalari. Sono sicura che Shandris ha già un piano.', 28153),
(159346, 'itIT', 'Se vuoi nu cambio di stile, ci stanno chegli strani Goblin al Gran Bazar, vicino al porto.', 'Se vuoi nu cambio di stile, ci stanno chegli strani Goblin al Gran Bazar, vicino al porto.', 28153),
(159343, 'itIT', 'Ci sono un sacco di animaletti da queste parti. Alcuni sono normalissimi conigli, scoiattoli e castori, ma ce ne sono altri che sembrano una manciata di bastoncini ambulante. Dopo giorni e giorni, sono riuscito a catturarne uno e ad addestrarlo... Si è dimostrata una creatura piuttosto leale! Non fraintendermi, bisogna sempre fare attenzione alle parti più acuminate, ma penso siano animali davvero fantastici. Vuoi vederli in azione?', '', 28153),
(159342, 'itIT', 'Troverai la Tesoreria Reale al centro della piramide, accanto al Gran Sigillo.', 'Troverai la Tesoreria Reale al centro della piramide, accanto al Gran Sigillo.', 28153),
(159340, 'itIT', 'È ora di piazzare delle bombe... senza farle esplodere. Per ora.', '', 28153),
(159339, 'itIT', '', 'Non dire così, Flynn. Dobbiamo continuare a sperare che Dama Jaina sia ancora viva!', 28153),
(159338, 'itIT', 'Ti prego, porgi le mie più sincere condoglianze a Dama Katherine.', '', 28153),
(159337, 'itIT', 'Fine del Destino... non proprio dove vorrei farmi una vacanza, questo è sicuro.', '', 28153),
(159336, 'itIT', 'Giochiamo!', 'Giochiamo!', 28153),
(159335, 'itIT', 'Prendete le loro cose luccicanti!', 'Prendete le loro cose luccicanti!', 28153),
(159334, 'itIT', 'Ohhh, avete cose che luccicano!', 'Ohhh, avete cose luccicanti!', 28153),
(159333, 'itIT', 'Venite a giocare con noi!', 'Venite a giocare con noi!', 28153),
(159332, 'itIT', 'Ahahah!', 'Ahahah!', 28153),
(159331, 'itIT', 'Stai allo scherzo!', 'Stai allo scherzo!', 28153),
(159330, 'itIT', 'È scattata!', 'È scattata!', 28153),
(159329, 'itIT', 'Eheheh!', 'Eheheh!', 28153),
(159228, 'itIT', '', 'Fai attenzione. Attenderò il tuo segnale.', 28153),
(159227, 'itIT', 'Quando hai finito, ci vediamo al Covo della Libertà.', '', 28153),
(159226, 'itIT', 'Prendi delle granate. Io chiederò a un cadetto di mia conoscenza di un certo uccellino.', '', 28153),
(159225, 'itIT', 'Suppongo che non volessero rischiare di rivelare la sua destinazione in questo groviglio di legalese, ma scommetto di sapere dove trovare le informazioni giuste.', '', 28153),
(159224, 'itIT', 'Magari c\'è scritto qualcosa di utile in piccolo...', '', 28153),
(159223, 'itIT', 'Dama Katherine ti ha chiesto di cercare sua figlia, eh? Vediamo cosa c\'è scritto sul contratto.', '', 28153),
(159222, 'itIT', 'Andiamo, dove state portando Jaina?', '', 28153),
(159221, 'itIT', 'Definizioni, condizioni di servizio, cavilli che probabilmente non servirebbero a nulla in tribunale, sempre che il giudice non sia corrotto...', '', 28153),
(159220, 'itIT', 'Dieci pagine di misure di sicurezza... Venti pagine di liberatorie...', '', 28153),
(159219, 'itIT', 'Descrizione dei servizi: il portatore dovrà fornire al cliente... Bla, bla, bla...', '', 28153),
(159218, 'itIT', 'Contratto per i servizi pattuito con i Bracescura... bah, ma chi la scrive questa roba?', '', 28153),
(159217, 'itIT', '', 'Passa attraverso le mura, veloce! Non riuscirò a reggere ancora a lungo!', 28153),
(159216, 'itIT', 'Dama Katherine mi ha chiesto di cercare sua figlia. Questo è l\'unico indizio che ho trovato per ora.', 'Dama Katherine mi ha chiesto di cercare sua figlia. Questo è l\'unico indizio che ho trovato per ora.', 28153),
(159215, 'itIT', 'Ehi, $n. È bello rivederti.', '', 28153),
(159214, 'itIT', '', 'Torna da me non appena avrai scoperto dov\'è stata portata Jaina.', 28153),
(159213, 'itIT', '', 'Spero che tu abbia ragione, Genn.', 28153),
(159212, 'itIT', 'Hai davanti uno dei più grandi campioni dell\'Alleanza, Katherine. Nessun altro potrebbe essere in grado di trovare Jaina.', '', 28153),
(159211, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Sei sotto l\'effetto di |cFFFF0000|Hspell:265129|h[Vettore Omega]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CORPSEEXPLODE.BLP:20|t Sei sotto l\'effetto di |cFFFF0000|Hspell:265129|h[Vettore Omega]|h|r!', 28153),
(159210, 'itIT', 'Aspetta! Usa il Talismano del Controllo!', '', 28153),
(159209, 'itIT', 'Questa è la tua fermata. Fai attenzione e ricorda: piazza le bombe e non lasciare che avvisino il continente della tua presenza!', '', 28153),
(159208, 'itIT', 'Questo potrebbe essere l\'inizio di una fantastica amicizia.', '', 28153),
(159207, 'itIT', '', 'Una? No, no, ne ho PARECCHIE.', 28153),
(159206, 'itIT', 'Hai una collezione di coltelli?', '', 28153),
(159205, 'itIT', '', 'Abbiamo un sacco di cose in comune, Keeshan. Quando tutto questo sarà finito, dovremmo comparare le nostre collezioni di coltelli.', 28153),
(159204, 'itIT', 'E io aiuterò $n a piazzare le bombe di Kelsey sulle navi più piccole... e a uccidere ogni Zandalari che posi gli occhi su di me.', '', 28153),
(159203, 'itIT', '', 'Io lavorerò a un dispositivo per aiutare $n ad attraversare l\'acqua per la prossima parte del piano.', 28153),
(159202, 'itIT', 'Dovete assicurarvi che nessuno vi veda piazzare quelle bombe alla base delle navi.', '', 28153),
(159201, 'itIT', 'Non c\'è bisogno che tu me lo ripeta. Vi lascerò tutti sull\'Isola delle Fauci. Sarà abbastanza lontano dalla città da permettervi di agire impunemente contro gli Zandalari.', '', 28153),
(159200, 'itIT', 'Una volta sono quasi stato mangiato. Non ve lo consiglio.', '', 28153),
(159199, 'itIT', '', 'Ci darebbero in pasto ai loro dinosauri. Di noi non rimarrebbero che piccoli pezzettini.', 28153),
(159198, 'itIT', 'Già. Un conto è scoprire una persona sola, come $n... ma se scoprissero l\'intero accampamento?', '', 28153),
(159197, 'itIT', '', 'Perché credi che Halford si stia muovendo così in fretta? Sa che saremmo condannati se gli Zandalari ci scoprissero a casa loro.', 28153),
(159196, 'itIT', 'È difficile non notare l\'accampamento dell\'Alleanza. Dobbiamo essere pronti per quando gli Zandalari ci scopriranno.', '', 28153),
(159195, 'itIT', 'Lì! Dovrebbe essere abbastanza in alto da impedire agli Zandalari di vederci.', '', 28153),
(159194, 'itIT', 'Tieniti forte. Dovremo andare MOLTO in alto per evitare che ci scoprano!', '', 28153),
(159193, 'itIT', '', 'Puoi passare quando vuoi, $p.', 28153),
(159192, 'itIT', '', 'Non ti ho mai $gvisto:vista; col cappotto, $gcaro:cara;. Ti prenderai un brutto raffreddore se non fai attenzione!', 28153),
(159191, 'itIT', '', 'Spero ti stia riposando abbastanza. Ci saranno sempre una valanga di mostri da uccidere!', 28153),
(159190, 'itIT', 'Discutiamo del piano per indebolire la flotta Zandalari.', 'Discutiamo del piano per indebolire la flotta Zandalari.', 28153),
(159189, 'itIT', 'Come... OSATE...', 'Come... OSATE...', 28153),
(159188, 'itIT', 'La marea devastante... sta arrivando...', 'La marea devastante... sta arrivando...', 28153),
(159187, 'itIT', 'L\'oscurità... è solo temporanea...', 'L\'oscurità... è solo temporanea...', 28153),
(159186, 'itIT', 'Canaglie... insolenti...', 'Canaglie... insolenti...', 28153),
(159185, 'itIT', 'Abbiamo migliaia di costrutti... Non potete vincere...', 'Abbiamo migliaia di costrutti... Non potete vincere...', 28153),
(159184, 'itIT', 'Il mio spirito... tornerà...', 'Il mio spirito... tornerà...', 28153),
(159183, 'itIT', 'Non sarà la mia morte a fermarci...', 'Non sarà la mia morte a fermarci...', 28153),
(159182, 'itIT', 'Ricostruiremo... tutto...', 'Ricostruiremo... tutto...', 28153),
(159181, 'itIT', 'La morte è soltanto l\'inizio della vostra punizione!', 'La morte è soltanto l\'inizio della vostra punizione!', 28153),
(159180, 'itIT', '', 'Ehi, salve! Saresti disponibile ad aiutarmi in alcune commissioni? Solo se non ti dispiace, s\'intende!', 28153),
(159179, 'itIT', 'Il vostro destino è segnato.', 'Il vostro destino è segnato.', 28153),
(159178, 'itIT', 'Inchinatevi, intrusi!', 'Inchinatevi, intrusi!', 28153),
(159177, 'itIT', 'La vostra morte sarà lenta, intrusi!', 'La vostra morte sarà lenta, intrusi!', 28153),
(159176, 'itIT', 'Siamo qui da prima della vostra gente e saremo ancora qui quando vi estinguerete!', 'Siamo qui da prima della vostra gente e saremo ancora qui quando vi estinguerete!', 28153),
(159175, 'itIT', 'Creature di carne insolenti!', 'Creature di carne insolenti!', 28153),
(159174, 'itIT', 'Imparerete a rispettare chi vi è superiore!', 'Imparerete a rispettare chi vi è superiore!', 28153),
(159173, 'itIT', 'Non c\'è posto per i deboli a questo mondo!', 'Non c\'è posto per i deboli a questo mondo!', 28153),
(159172, 'itIT', 'Ciò che è morto... non può morire...', 'Ciò che è morto... non può morire...', 28153),
(159171, 'itIT', 'Torno da lei... solo per un momento...', 'Torno da lei... solo per un momento...', 28153),
(159170, 'itIT', 'Non saremo dimenticati negli abissi...', 'Non saremo dimenticati negli abissi...', 28153),
(159169, 'itIT', 'Lei ci libererà da questo tormento...', 'Lei ci libererà da questo tormento...', 28153),
(159168, 'itIT', 'Lei avrà il fluido dorato... non potete fermarci tutti...', 'Lei avrà il fluido dorato... non potete fermarci tutti...', 28153),
(159167, 'itIT', 'Siamo eterni... La vostra vittoria non conta niente...', 'Siamo eterni... La vostra vittoria non conta niente...', 28153),
(159166, 'itIT', 'Lei mi riporterà in vita...', 'Lei mi riporterà in vita...', 28153),
(159165, 'itIT', 'Non possiamo morire... per mano di mortali...', 'Non possiamo morire... per mano di mortali...', 28153),
(159164, 'itIT', 'Vi spremerò il fiato fuori dai polmoni!', 'Vi spremerò il fiato fuori dai polmoni!', 28153),
(159163, 'itIT', 'Queste acque appartengono a noi!', 'Queste acque appartengono a noi!', 28153),
(159162, 'itIT', 'Gli abissi schiacceranno le vostre fragili ossa!', 'Gli abissi schiacceranno le vostre fragili ossa!', 28153),
(159161, 'itIT', 'Che le maree vi colgano!', 'Che le maree vi colgano!', 28153),
(159160, 'itIT', 'Helya vi chiama!', 'Helya vi chiama!', 28153),
(159159, 'itIT', 'La vostra anima sarà nostra!', 'La vostra anima sarà nostra!', 28153),
(159158, 'itIT', 'Ci raggiungerete nella morte e vi unirete alla sua armata!', 'Ci raggiungerete nella morte e vi unirete alla sua armata!', 28153),
(159157, 'itIT', 'Le nebbie vengono a prendervi!', 'Le nebbie vengono a prendervi!', 28153),
(159156, 'itIT', 'Non avrete mai il controllo dei mari...', 'Non avrete mai il controllo dei mari...', 28153),
(159155, 'itIT', 'Uno muore, migliaia vivono...', 'Uno muore, migliaia vivono...', 28153),
(159154, 'itIT', 'Non pensssate di aver vinto...', 'Non pensssate di aver vinto...', 28153),
(159153, 'itIT', 'Il vostro futuro... è condannato...', 'Il vostro futuro... è condannato...', 28153),
(159152, 'itIT', 'La morte viene a prenderti...', 'La morte viene a prenderti...', 28153),
(159151, 'itIT', 'Azshara... è tutto...', 'Azshara... è tutto...', 28153),
(159150, 'itIT', 'Azshara... Ritorno tra le onde...', 'Azshara... Ritorno tra le onde...', 28153),
(159149, 'itIT', 'Mia regina...', 'Mia regina...', 28153),
(159148, 'itIT', 'Il dio degli abisssi vi attende con ansssia!', 'Il dio degli abisssi vi attende con ansssia!', 28153),
(159147, 'itIT', 'Gli occhi nell\'abissso vi porteranno alla follia!', 'Gli occhi nell\'abissso vi porteranno alla follia!', 28153),
(159146, 'itIT', 'Percepite la paura? L\'infinito terrore negli abisssi?', 'Percepite la paura? L\'infinito terrore negli abisssi?', 28153),
(159145, 'itIT', 'L\'Impero Nero rinascerà su quesssto mondo e la sua anima nutrirà i padroni!', 'L\'Impero Nero rinascerà su quesssto mondo e la sua anima nutrirà i padroni!', 28153),
(159144, 'itIT', 'Abbiamo atteso troppo. Ora ha inizio l\'era dei Naga!', 'Abbiamo atteso troppo. Ora ha inizio l\'era dei Naga!', 28153),
(159143, 'itIT', 'La città sommersssa sorgerà per annunciare la vossstra condanna!', 'La città sommersssa sorgerà per annunciare la vossstra condanna!', 28153),
(159142, 'itIT', 'N\'zoth ci chiama, non riuscite a sentirlo?', 'N\'zoth ci chiama, non riuscite a sentirlo?', 28153),
(159141, 'itIT', 'Per la grande regina Azshara, lunga vita al suo regno!', 'Per la grande regina Azshara, lunga vita al suo regno!', 28153),
(159140, 'itIT', 'Il vostro momento è arrivato!', 'Il vostro momento è arrivato!', 28153),
(159139, 'itIT', 'Noi veniamo dagli abisssi!', 'Noi veniamo dagli abisssi!', 28153),
(159138, 'itIT', 'Masssacrateli!', 'Masssacrateli!', 28153),
(159137, 'itIT', 'Annegherete nel dolore!', 'Annegherete nel dolore!', 28153),
(159136, 'itIT', 'Colui che freme ci chiama col suo canto!', 'Colui che freme ci chiama col suo canto!', 28153),
(159135, 'itIT', 'Gli abisssi susssurranti vi chiamano!', 'Gli abisssi susssurranti vi chiamano!', 28153),
(159134, 'itIT', 'Per Azshara!', 'Per Azshara!', 28153),
(159133, 'itIT', 'Tornate strisciando da dove siete venuti!', 'Tornate strisciando da dove siete venuti!', 28153),
(159132, 'itIT', 'Maledizione della carne rilevata. Attivazione protocolli di igienizzazione.', 'Maledizione della carne rilevata. Attivazione protocolli di igienizzazione.', 28153),
(159131, 'itIT', 'Il vostro corpo è debole e malleabile. Permettetemi di riplasmarvi.', 'Il vostro corpo è debole e malleabile. Permettetemi di riplasmarvi.', 28153),
(159130, 'itIT', 'State cercando di far del male all\'anima del mondo e di rubare il suo sangue. Dovete essere riplasmati.', 'State cercando di far del male all\'anima del mondo e di rubare il suo sangue. Dovete essere riplasmati.', 28153),
(159129, 'itIT', 'Siamo i difensori dell\'anima di questo mondo, non potete procedere.', 'Siamo i difensori dell\'anima di questo mondo, non potete procedere.', 28153),
(159128, 'itIT', 'State intralciando il nostro sacro dovere. Verrete purificati.', 'State intralciando il nostro sacro dovere. Verrete purificati.', 28153),
(159127, 'itIT', 'I maledetti devono essere rioriginati. È questo il nostro compito.', 'I maledetti devono essere rioriginati. È questo il nostro compito.', 28153),
(159126, 'itIT', 'Esistiamo per difendere questo mondo dalla maledizione della carne!', 'Esistiamo per difendere questo mondo dalla maledizione della carne!', 28153),
(159125, 'itIT', 'Siamo stati creati per epurare la vostra malattia. Non muovetevi.', 'Siamo stati creati per epurare la vostra malattia. Non muovetevi.', 28153),
(159124, 'itIT', 'I nostri ordini non cambieranno per merito vostro...', 'I nostri ordini non cambieranno per merito vostro...', 28153),
(159123, 'itIT', 'Ricostruiremo... ancora e ancora...', 'Ricostruiremo... ancora e ancora...', 28153),
(159122, 'itIT', 'La nostra missione... non deve fallire...', 'La nostra missione... non deve fallire...', 28153),
(159121, 'itIT', 'Le vostre azioni porteranno alla fine del vostro mondo...', 'Le vostre azioni porteranno alla fine del vostro mondo...', 28153),
(159120, 'itIT', 'Dobbiamo proteggere... l\'anima del mondo...', 'Dobbiamo proteggere... l\'anima del mondo...', 28153),
(159119, 'itIT', 'Non... capite...', 'Non... capite...', 28153),
(159118, 'itIT', 'Questo non è... il nostro destino...', 'Questo non è... il nostro destino...', 28153),
(159117, 'itIT', 'I Plasmatori... torneranno...', 'I Plasmatori... torneranno...', 28153),
(159116, 'itIT', 'Vi siete persi. Permetteteci di indicarvi la via.', 'Vi siete persi. Permetteteci di indicarvi la via.', 28153),
(159115, 'itIT', 'Il nostro sacro dovere non deve essere interrotto.', 'Il nostro sacro dovere non deve essere interrotto.', 28153),
(159114, 'itIT', 'I Plasmatori ci hanno affidato la cura di questo mondo, fatevi da parte!', 'I Plasmatori ci hanno affidato la cura di questo mondo, fatevi da parte!', 28153),
(159113, 'itIT', 'La maledizione della carne è fuori controllo!', 'La maledizione della carne è fuori controllo!', 28153),
(159112, 'itIT', 'Sarete rioriginati, non muovetevi.', 'Sarete rioriginati, non muovetevi.', 28153),
(159111, 'itIT', 'Siamo qui per curare la vostra malattia.', 'Siamo qui per curare la vostra malattia.', 28153),
(159110, 'itIT', 'Cureremo la vostra maledizione della carne.', 'Cureremo la vostra maledizione della carne.', 28153),
(159109, 'itIT', 'Il sangue del pianeta è sotto la nostra protezione.', 'Il sangue del pianeta è sotto la nostra protezione.', 28153),
(159108, 'itIT', 'Almeno muoio da ricco...', 'Almeno muoio da ricca...', 28153),
(159107, 'itIT', 'Dite ai miei figli... che non avranno neanche un soldo...', 'Dite ai miei figli... che non avranno neanche un soldo...', 28153),
(159106, 'itIT', 'Ricordatemi... per il mio fatturato...', 'Ricordatemi... per il mio fatturato...', 28153),
(159105, 'itIT', 'Aspetta! Ti pago per resuscitarmi! Daiii!', 'Aspetta! Ti pago per resuscitarmi! Daiii!', 28153),
(159104, 'itIT', 'Mi toglieranno dall\'inventario...', 'Mi toglieranno dall\'inventario...', 28153),
(159103, 'itIT', 'Spero... che questo non influisca... sulla mia pensione...', 'Spero... che questo non influisca... sulla mia pensione...', 28153),
(159102, 'itIT', 'Siamo in rosso!', 'Siamo in rosso!', 28153),
(159101, 'itIT', 'Un crollo... in borsa...', 'Un crollo... in borsa...', 28153),
(159100, 'itIT', 'Pronti a incassare!', 'Pronti a incassare!', 28153),
(159099, 'itIT', 'Se non li uccidiamo, i costi verranno detratti dal fondo caffè!', 'Se non li uccidiamo, i costi verranno detratti dal fondo caffè!', 28153),
(159098, 'itIT', 'Mi daranno un bel bonus per le vostre teste!', 'Mi daranno un bel bonus per le vostre teste!', 28153),
(159097, 'itIT', 'Avevo già in mente di fare qualche straordinario solo per uccidervi!', 'Avevo già in mente di fare qualche straordinario solo per uccidervi!', 28153),
(159096, 'itIT', 'Ai soci non farà piacere il vostro interesse nei nostri affari!', 'Ai soci non farà piacere il vostro interesse nei nostri affari!', 28153),
(159095, 'itIT', 'Basta, al diavolo le mie tecniche di gestione!', 'Basta, al diavolo le mie tecniche di gestione!', 28153),
(159094, 'itIT', 'Vi trasformerò in un dolcissimo profitto.', 'Vi trasformerò in un dolcissimo profitto.', 28153),
(159093, 'itIT', 'I guadagni sono migliori del previsto!', 'I guadagni sono migliori del previsto!', 28153),
(159092, 'itIT', 'Consideratevi acquisiti!', 'Consideratevi acquisiti!', 28153),
(159091, 'itIT', 'Questa è un\'acquisizione non autorizzata!', 'Questa è un\'acquisizione non autorizzata!', 28153),
(159090, 'itIT', 'Qualcuno attivi un kit d\'emergenza, abbiamo compagnia!', 'Qualcuno attivi un kit d\'emergenza, abbiamo compagnia!', 28153),
(159089, 'itIT', 'Grazie! È un piacere.', 'Grazie! È un piacere.', 28153),
(159088, 'itIT', 'State intaccando i miei margini di profitto!', 'State intaccando i miei margini di profitto!', 28153),
(159087, 'itIT', 'Non possiamo fermare le operazioni solo per questo!', 'Non possiamo fermare le operazioni solo per questo!', 28153),
(159086, 'itIT', 'Cosa ci fate qui? Questo è territorio della S.P.R. & Co., non vi avevano avvisato?', 'Cosa ci fate qui? Questo è territorio della S.P.R. & Co., non vi avevano avvisato?', 28153),
(159085, 'itIT', 'Dannazione! Intrusi! Qualcuno mi difenda!', 'Dannazione! Intrusi! Qualcuno mi difenda!', 28153),
(159084, 'itIT', 'Prendeteli! Ma usate roba economica!', 'Prendeteli! Ma usate roba economica!', 28153),
(159083, 'itIT', 'Ricordate, il nostro obiettivo principale è indebolire le loro difese e tenere nascoste le nostre forze. Se venissimo scoperti, tutto andrebbe perduto. Per l\'Alleanza!', '', 28153),
(159082, 'itIT', 'Vuoi dare 20 Gelati alla Fragola di Tigule e Foror a Marie Davenport?', 'Vuoi dare 20 Gelati alla Fragola di Tigule e Foror a Marie Davenport?', 28153),
(159081, 'itIT', '', 'Umbric e io andremo avanti a fare i preparativi per un attacco furtivo al Porto da Guerra.', 28153),
(159080, 'itIT', 'Non fate che marciare verso la fine del vostro mondo... accecati dall\'arroganza...', 'Non fate che marciare verso la fine del vostro mondo... accecati dall\'arroganza...', 28153),
(159079, 'itIT', 'Volevamo solo... ciò che è nostro...', 'Volevamo solo... ciò che è nostro...', 28153),
(159078, 'itIT', 'State solo... ritardando... l\'inevitabile...', 'State solo... ritardando... l\'inevitabile...', 28153),
(159077, 'itIT', 'Il nido si farà più forte... senza di me...', 'Il nido si farà più forte... senza di me...', 28153),
(159076, 'itIT', 'Il cielo si oscura...', 'Il cielo si oscura...', 28153),
(159075, 'itIT', 'Corretto. $n, tu ti occuperai di indebolire le difese portuali degli Zandalari. Kelsey, Falstad e Keeshan ti aiuteranno col primo obiettivo.', '', 28153),
(159074, 'itIT', 'Non abbiamo... scelto il nostro destino...', 'Non abbiamo... scelto il nostro destino...', 28153),
(159073, 'itIT', 'Non ci è mai stata data... una possibilità...', 'Non ci è mai stata data... una possibilità...', 28153),
(159072, 'itIT', 'Cadiamo... ancora una volta...', 'Cadiamo... ancora una volta...', 28153),
(159071, 'itIT', 'Siamo già caduti una volta per colpa vostra, non accadrà di nuovo! È l\'alba di un nuovo crepuscolo!', 'Siamo già caduti una volta per colpa vostra, non accadrà di nuovo! È l\'alba di un nuovo crepuscolo!', 28153),
(159070, 'itIT', 'Il minerale lucente deve essere nostro. Non possiamo sopravvivere da soli, non capite?', 'Il minerale lucente deve essere nostro. Non possiamo sopravvivere da soli, non capite?', 28153),
(159069, 'itIT', '', 'Quindi... poi aspettiamo a farle esplodere fino all\'arrivo delle nostre flotte. la città cadrebbe nel caos, permettendoci di sbarcare!', 28153),
(159068, 'itIT', 'Vogliamo soltanto ciò che ci era stato promesso così tanto tempo fa!', 'Vogliamo soltanto ciò che ci era stato promesso così tanto tempo fa!', 28153),
(159067, 'itIT', 'Il fluido dorato porterà al ritorno del nostro stormo... e alla vostra sconfitta!', 'Il fluido dorato porterà al ritorno del nostro stormo... e alla vostra sconfitta!', 28153),
(159066, 'itIT', 'Se facciamo un bel lavoro, gli Zandalari non si accorgeranno nemmeno del nostro sabotaggio.', '', 28153),
(159065, 'itIT', 'Ora siamo noi a controllare le nostre menti, lasciateci stare!', 'Ora siamo noi a controllare le nostre menti, lasciateci stare!', 28153),
(159064, 'itIT', 'Concordo. Shandris, Falstad e io abbiamo proposto un piano che è stato accettato da Re Wrynn. In caso di successo, le nostre forze avrebbero una possibilità.', '', 28153),
(159063, 'itIT', 'Questo stormo è nostro e non è sotto gli ordini di nessuno, men che meno i vostri!', 'Questo stormo è nostro e non è sotto gli ordini di nessuno, men che meno i vostri!', 28153),
(159062, 'itIT', 'Lo Stormo del Crepuscolo è tornato proprio sotto il vostro naso, per punire la vostra arroganza!', 'Lo Stormo del Crepuscolo è tornato proprio sotto il vostro naso, per punire la vostra arroganza!', 28153),
(159061, 'itIT', '', 'Ecco perché tutti volevate quelle bombe!', 28153),
(159060, 'itIT', 'I cosiddetti sovrani di questo mondo ci hanno messi da parte, ma non saremo dimenticati dalla storia!', 'I cosiddetti sovrani di questo mondo ci hanno messi da parte, ma non saremo dimenticati dalla storia!', 28153),
(159059, 'itIT', '', 'Gli Zandalari sono forti, ma non invincibili. Saboteremo i punti chiave delle loro difese portuali con delle bombe a controllo remoto.', 28153),
(159058, 'itIT', 'Non potete fermarci questa volta!', 'Non potete fermarci questa volta!', 28153),
(159057, 'itIT', 'Gloria al Crepuscolo!', 'Gloria al Crepuscolo!', 28153),
(159056, 'itIT', 'Siamo padroni solo di noi stessi ora!', 'Siamo padroni solo di noi stessi ora!', 28153),
(159055, 'itIT', 'Togliamocela di torno. L\'Alleanza ha bisogno del nostro aiuto per preparare un\'invasione su larga scala di Zuldazar.', '', 28153),
(159054, 'itIT', 'Non saremo messi di nuovo da parte!', 'Non saremo messi di nuovo da parte!', 28153),
(159053, 'itIT', 'Lo stormo dimenticato non attenderà oltre!', 'Lo stormo dimenticato non attenderà oltre!', 28153),
(159052, 'itIT', 'Veniamo dall\'oscurità per dominare questo mondo.', 'Veniamo dall\'oscurità per dominare questo mondo.', 28153),
(159051, 'itIT', 'Lo Stormo del Crepuscolo regnerà supremo!', 'Lo Stormo del Crepuscolo regnerà supremo!', 28153),
(159050, 'itIT', 'Per il Crepuscolo!', 'Per il Crepuscolo!', 28153),
(159049, 'itIT', 'Siamo i Custodi della Terra. Non potete prendere ciò che è nostro!', 'Siamo i Custodi della Terra. Non potete prendere ciò che è nostro!', 28153),
(159048, 'itIT', 'Non sapete dove si nasconde la nostra tana. Non potete vincere. Arrendetevi!', 'Non sapete dove si nasconde la nostra tana. Non potete vincere. Arrendetevi!', 28153),
(159047, 'itIT', 'Lo Stormo Nero si vendicherà una volta per tutte!', 'Lo Stormo Nero si vendicherà una volta per tutte!', 28153),
(159046, 'itIT', 'Noi difendiamo le pietre di questo mondo da gente come voi!', 'Noi difendiamo le pietre di questo mondo da gente come voi!', 28153),
(159045, 'itIT', 'Ridicole creature di carne, il sangue del mondo è sotto la nostra custodia!', 'Ridicole creature di carne, il sangue del mondo è sotto la nostra custodia!', 28153),
(159044, 'itIT', 'Questo mondo è stato dato ai draghi. La vostra gente è solo un\'infezione!', 'Questo mondo è stato dato ai draghi. La vostra gente è solo un\'infezione!', 28153),
(159043, 'itIT', 'Come osate rubare ciò che è nostro di diritto?', 'Come osate rubare ciò che è nostro di diritto?', 28153),
(159042, 'itIT', 'Il sangue del mondo è nostro! Siamo noi i suoi custodi!', 'Il sangue del mondo è nostro! Siamo noi i suoi custodi!', 28153),
(159041, 'itIT', 'State rubando... ciò che è nostro di diritto...', 'State rubando... ciò che è nostro di diritto...', 28153),
(159040, 'itIT', 'Non saremo dimenticati dalla storia...', 'Non saremo dimenticati dalla storia...', 28153),
(159039, 'itIT', 'Lo Stormo Nero verrà a prendervi...', 'Lo Stormo Nero verrà a prendervi...', 28153),
(159038, 'itIT', 'Non vincerete questa guerra...', 'Non vincerete questa guerra...', 28153),
(159037, 'itIT', 'Questo mondo appartiene... ai draghi...', 'Questo mondo appartiene... ai draghi...', 28153),
(159036, 'itIT', 'Qui non c\'è posto... per la vostra gente...', 'Qui non c\'è posto... per la vostra gente...', 28153),
(159035, 'itIT', 'Lo Stormo Nero non può essere sconfitto...', 'Lo Stormo Nero non può essere sconfitto...', 28153),
(159034, 'itIT', 'Torneremo...', 'Torneremo...', 28153),
(159033, 'itIT', 'Lo Stormo Nero rinascerà!', 'Lo Stormo Nero rinascerà!', 28153),
(159032, 'itIT', 'La vostra razza sarà epurata!', 'La vostra razza sarà epurata!', 28153),
(159031, 'itIT', 'Siamo portatori di fuoco e morte!', 'Siamo portatori di fuoco e morte!', 28153),
(159030, 'itIT', 'Osate sfidare uno Stormo dei Draghi?', 'Osate sfidare uno Stormo dei Draghi?', 28153),
(159029, 'itIT', 'Lo Stormo Nero sorgerà di nuovo!', 'Lo Stormo Nero sorgerà di nuovo!', 28153),
(159028, 'itIT', 'Gloria allo Stormo Nero!', 'Gloria allo Stormo Nero!', 28153),
(159027, 'itIT', 'Per i Custodi della Terra!', 'Per i Custodi della Terra!', 28153),
(159026, 'itIT', 'Difenderò lo stormo!', 'Difenderò lo stormo!', 28153),
(159025, 'itIT', 'Questo è per te... Imperatrice...', 'Questo è per te... Imperatrice...', 28153),
(159024, 'itIT', 'Ne schiacciate uno... molti prendono il suo posto...', 'Ne schiacciate uno... molti prendono il suo posto...', 28153),
(159023, 'itIT', 'Portate il minerale... all\'Imperatrice...', 'Portate il minerale... all\'Imperatrice...', 28153),
(159022, 'itIT', 'Il suo richiamo... è come musica...', 'Il suo richiamo... è come musica...', 28153),
(159021, 'itIT', 'La sento... anche nella morte...', 'La sento... anche nella morte...', 28153),
(159020, 'itIT', 'Il canto dell\'Imperatrice... svanisce...', 'Il canto dell\'Imperatrice... svanisce...', 28153),
(159019, 'itIT', 'Siamo... migliaia... Non potete fermarci...', 'Siamo... migliaia... Non potete fermarci...', 28153),
(159018, 'itIT', 'Kshh... Ho fallito...', 'Kshh... Ho fallito...', 28153),
(159017, 'itIT', 'Vi ucciderò e darò in pasto il vostro corpo allo sciame!', 'Vi ucciderò e darò in pasto il vostro corpo allo sciame!', 28153),
(159016, 'itIT', 'Avete così fretta di morire?', 'Avete così fretta di morire?', 28153),
(159015, 'itIT', 'Il minerale d\'oro è nostro! Un dono per l\'Imperatrice!', 'Il minerale d\'oro è nostro! Un dono per l\'Imperatrice!', 28153),
(159014, 'itIT', 'Sciamiamo per l\'Imperatrice!', 'Sciamiamo per l\'Imperatrice!', 28153),
(159013, 'itIT', 'Lo sciame non può essere fermato!', 'Lo sciame non può essere fermato!', 28153),
(159012, 'itIT', 'Il dolce canto dell\'Imperatrice esige la vostra morte!', 'Il dolce canto dell\'Imperatrice esige la vostra morte!', 28153),
(159011, 'itIT', 'L\'Imperatrice me lo ordina!', 'L\'Imperatrice me lo ordina!', 28153),
(159010, 'itIT', 'Per l\'Imperatrice!', 'Per l\'Imperatrice!', 28153),
(159009, 'itIT', 'L\'Alleanza resisterà... e l\'infido regno della Regina Banshee giungerà al termine.', '', 28153),
(159008, 'itIT', 'Si aspetta che questa atrocità spezzi i nostri spiriti, che distrugga la nostra unità. Ma quest\'oggi giuro che...', '', 28153),
(159007, 'itIT', 'Colpito... con onore...', 'Colpita... con onore...', 28153),
(159006, 'itIT', 'Argh! Questa è la morte che volevo!', 'Argh! Questa è la morte che volevo!', 28153),
(159005, 'itIT', 'Ma è un sogno che non potrà mai realizzarsi finché Sylvanas Ventolesto è al comando dell\'Orda.', '', 28153),
(159004, 'itIT', 'Faccio rotta... verso il tramonto...', 'Faccio rotta... verso il tramonto...', 28153),
(159003, 'itIT', 'Per tutta la vita ho pregato per la pace in questo mondo.', '', 28153),
(159002, 'itIT', 'Prenderò il mio posto tra i guerrieri del passato...', 'Prenderò il mio posto tra i guerrieri del passato...', 28153),
(159001, 'itIT', 'Hai dimostrato grande coraggio, proprio in uno dei giorni più bui per l\'Alleanza.', '', 28153),
(159000, 'itIT', 'Gli spiriti benedicono la mia morte...', 'Gli spiriti benedicono la mia morte...', 28153),
(158999, 'itIT', '', 'Riposa, finché puoi. Preparati per le battaglie a venire. Avrò bisogno di te.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158998, 'itIT', 'Muoio in una gloriosa battaglia!', 'Muoio in una gloriosa battaglia!', 28153),
(158997, 'itIT', 'Il clan mi vendicherà...', 'Il clan mi vendicherà...', 28153),
(158996, 'itIT', '', 'Tuttavia, li abbiamo fatti sanguinare. Nella guerra che verrà, la loro rabbia sarà una debolezza, non un punto di forza.', 28153),
(158995, 'itIT', 'La morte viene a prenderti...', 'La morte viene a prenderti...', 28153),
(158994, 'itIT', 'Altri esseri insignificanti da schiacciare!', 'Altri esseri insignificanti da schiacciare!', 28153),
(158993, 'itIT', 'Un\'altra battaglia gloriosa!', 'Un\'altra battaglia gloriosa!', 28153),
(158992, 'itIT', 'Vi strappo gli occhi!', 'Vi strappo gli occhi!', 28153),
(158991, 'itIT', '', 'Ci siamo riusciti solo parzialmente. L\'Alleanza si vendicherà. Verranno a cercarci. Sia me che te.', 28153),
(158990, 'itIT', '', 'Il nostro attacco doveva porre fine alla guerra ancor prima che cominciasse... annientando i loro capi e infliggendo un colpo dal quale l\'Alleanza difficilmente si sarebbe ripresa.', 28153),
(158989, 'itIT', '', 'Quando ti ho mandato in missione, non avevo previsto questo esito.', 28153),
(158988, 'itIT', 'Migliaia di navi salpano verso la vostra rovina!', 'Migliaia di navi salpano verso la vostra rovina!', 28153),
(158987, 'itIT', 'La mia vita per Jorun!', 'La mia vita per Jorun!', 28153),
(158986, 'itIT', 'Per i Vegliasangue!', 'Per i Vegliasangue!', 28153),
(158985, 'itIT', 'Morite con onore!', 'Morite con onore!', 28153),
(158984, 'itIT', 'Vi divorerò il cuore!', 'Vi divorerò il cuore!', 28153),
(158983, 'itIT', 'Mrglrggg...', 'Mrglrggg...', 28153),
(158982, 'itIT', 'Mrrg mrgl?', 'Mrrg mrgl?', 28153),
(158981, 'itIT', 'Rgll mgrgl... rgl...', 'Rgll mgrgl... rgl...', 28153),
(158980, 'itIT', 'Grgl...', 'Grgl...', 28153),
(158979, 'itIT', 'Mrg!', 'Mrg!', 28153),
(158978, 'itIT', 'Rgl... mrg...', 'Rgl... mrg...', 28153),
(158977, 'itIT', 'Mrrrmgrl!', 'Mrrrmgrl!', 28153),
(158976, 'itIT', 'Mrglrgl? Mrg! Rgl!', 'Mrglrgl? Mrg! Rgl!', 28153),
(158975, 'itIT', 'Rgrml grml grml!', 'Rgrml grml grml!', 28153),
(158974, 'itIT', '', 'Oh cielo, è perfetto! Grazie mille, $p, sei davvero un tesoro. Ecco, prendi dei biscotti.', 28153),
(158973, 'itIT', 'Mrg? Grml?!?', 'Mrg? Grml?!?', 28153),
(158972, 'itIT', 'Mrgl? Rgl!', 'Mrgl? Rgl!', 28153),
(158971, 'itIT', 'Mrglrglrgl!', 'Mrglrglrgl!', 28153),
(158970, 'itIT', 'La morte non conta nulla per il Vuoto eterno...', 'La morte non conta nulla per il Vuoto eterno...', 28153),
(158969, 'itIT', 'Ammirate la sua seconda venuta...', 'Ammirate la sua seconda venuta...', 28153),
(158968, 'itIT', 'La vostra condanna giunge dagli abissi...', 'La vostra condanna giunge dagli abissi...', 28153),
(158967, 'itIT', 'Non potete distruggerci... Siamo infiniti...', 'Non potete distruggerci... Siamo infiniti...', 28153),
(158966, 'itIT', 'Cadrete... i vostri amici vi abbandoneranno...', 'Cadrete... i vostri amici vi abbandoneranno...', 28153),
(158965, 'itIT', 'Sentite il richiamo dell\'oscurità?', 'Sentite il richiamo dell\'oscurità?', 28153),
(158964, 'itIT', 'Le profondità ossessionanti non possono essere fermate!', 'Le profondità ossessionanti non possono essere fermate!', 28153),
(158963, 'itIT', 'Dal mio cadavere, in migliaia nasceranno.', 'Dal mio cadavere, in migliaia nasceranno.', 28153),
(158962, 'itIT', 'L\'oscurità inquieta farà risuonare l\'ultimo rintocco.', 'L\'oscurità inquieta farà risuonare l\'ultimo rintocco.', 28153),
(158961, 'itIT', 'Il divoratore degli abissi brama il vostro mondo!', 'Il divoratore degli abissi brama il vostro mondo!', 28153),
(158960, 'itIT', 'Non potete affrontare ciò che temete!', 'Non potete affrontare ciò che temete!', 28153),
(158959, 'itIT', 'Ci diffonderemo fin quando il vostro mondo non sarà ricoperto di occhi e terrore.', 'Ci diffonderemo fin quando il vostro mondo non sarà ricoperto di occhi e terrore.', 28153),
(158958, 'itIT', 'Le profondità senza luce vi chiamano.', 'Le profondità senza luce vi chiamano.', 28153),
(158957, 'itIT', 'Scappate urlando negli abissi!', 'Scappate urlando negli abissi!', 28153),
(158956, 'itIT', 'Vi consumeremo tutti!', 'Vi consumeremo tutti!', 28153),
(158955, 'itIT', 'Il vostro corpo nutrirà l\'oscurità!', 'Il vostro corpo nutrirà l\'oscurità!', 28153),
(158954, 'itIT', 'Naufragato...', 'Naufragata...', 28153),
(158953, 'itIT', 'Ho sempre pensato che sarei morto... in mare...', 'Ho sempre pensato che sarei morta... in mare...', 28153),
(158952, 'itIT', 'Non me ne andrò... così...', 'Non me ne andrò... così...', 28153),
(158951, 'itIT', 'È stata colpa... del navigatore...', 'È stata colpa... del navigatore...', 28153),
(158950, 'itIT', 'Salvatemi... cani...', 'Salvatemi... cani...', 28153),
(158949, 'itIT', 'Meglio la morte... che stare ancora qui...', 'Meglio la morte... che stare ancora qui...', 28153),
(158948, 'itIT', 'Non saremmo mai... dovuti venire qui...', 'Non saremmo mai... dovuti venire qui...', 28153),
(158947, 'itIT', 'La peggiore... ciurma... di sempre...', 'La peggiore... ciurma... di sempre...', 28153),
(158946, 'itIT', 'La vostra nave sarà nostra, furfanti!', 'La vostra nave sarà nostra, furfanti!', 28153),
(158945, 'itIT', 'Guardate, il tesoro è venuto da noi! E ci hanno anche portato una nave!', 'Guardate, il tesoro è venuto da noi! E ci hanno anche portato una nave!', 28153),
(158944, 'itIT', 'Hanno una nave! Prendeteli!', 'Hanno una nave! Prendeteli!', 28153),
(158943, 'itIT', 'Vi pentirete di essere venuti qui!', 'Vi pentirete di essere venuti qui!', 28153),
(158942, 'itIT', 'Arrr, mi sa che ho esagerato col rum...', 'Arrr, mi sa che ho esagerato col rum...', 28153),
(158941, 'itIT', 'Siamo sotto attacco! Tutti in piedi!', 'Siamo sotto attacco! Tutti in piedi!', 28153),
(158940, 'itIT', 'Non sono qui per salvarci, prendeteli!', 'Non sono qui per salvarci, prendeteli!', 28153),
(158939, 'itIT', 'Ora ce ne andiamo di qui, ragazzi! Prendeteli!', 'Ora ce ne andiamo di qui, ragazzi! Prendeteli!', 28153),
(158938, 'itIT', 'Torno negli abissi... Una morte da marinaio...', 'Torno negli abissi... Una morte da marinaia...', 28153),
(158937, 'itIT', 'Datemi un sorso di rum... prima di morire...', 'Datemi un sorso di rum... prima di morire...', 28153),
(158936, 'itIT', 'Sta diventando... buio...', 'Sta diventando... buio...', 28153),
(158935, 'itIT', 'Uh... È stato un colpo basso...', 'Uh... È stato un colpo basso...', 28153),
(158934, 'itIT', 'Tornate... sulla nave...', 'Tornate... sulla nave...', 28153),
(158933, 'itIT', 'Argh! Dritto nelle budella...', 'Argh! Dritto nelle budella...', 28153),
(158932, 'itIT', 'Non troverete mai... il mio bottino...', 'Non troverete mai... il mio bottino...', 28153),
(158931, 'itIT', 'Arrr... Il mio tesoro...', 'Arrr... Il mio tesoro...', 28153),
(158930, 'itIT', 'Difendetemi, inutili vermi!', 'Difendetemi, inutili vermi!', 28153),
(158929, 'itIT', 'Al mio fianco, canaglie! Ci stanno abbordando!', 'Al mio fianco, canaglie! Ci stanno abbordando!', 28153),
(158928, 'itIT', 'Non sareste dovuti venire qui. Questo luogo appartiene ai pirati!', 'Non sareste dovuti venire qui. Questo luogo appartiene ai pirati!', 28153),
(158927, 'itIT', 'Arrr! Ci sono degli intrusi tra noi, ragazzi!', 'Arrr! Ci sono degli intrusi tra noi, ragazzi!', 28153),
(158926, 'itIT', 'Bottini e razzie, arrr!', 'Bottini e razzie, arrr!', 28153),
(158925, 'itIT', 'Desiderate una bella lama nelle budella?', 'Desiderate una bella lama nelle budella?', 28153),
(158924, 'itIT', 'Farete una passeggiata sulla passerella!', 'Farete una passeggiata sulla passerella!', 28153),
(158923, 'itIT', 'Ciurma, respingete gli invasori!', 'Ciurma, respingete gli invasori!', 28153),
(158922, 'itIT', 'Nessuno intralcerà la nostra caccia di Onoho!', '', 28153),
(158921, 'itIT', 'Il mare voi ha donato a noi. Ora non potete più andarvene...', '', 28153),
(158920, 'itIT', 'Affineremo le nostre abilità mentre attenderemo che il mare ci guidi!', '', 28153),
(158919, 'itIT', 'Lo scorrere dell\'acqua aveva previsto questo incontro.', '', 28153),
(158918, 'itIT', 'State affrontando il grande clan della caccia, come sperate di sopravvivere?', '', 28153),
(158917, 'itIT', 'Il mare ci porta altra carne e armi. Siano lodate le onde per questo dono!', '', 28153),
(158916, 'itIT', 'La vostra carne e le vostre provviste alimenteranno la grande caccia. Grazie!', '', 28153),
(158915, 'itIT', 'Il nostro clan ha dato la caccia al Grande per molti anni. Non ci fermerete oggi!', '', 28153),
(158914, 'itIT', 'Le secche... mi avevano mostrato questo destino...', '', 28153),
(158913, 'itIT', 'Le onde... mi prendono...', '', 28153),
(158912, 'itIT', 'La caccia... reclama un\'altra vita...', '', 28153),
(158911, 'itIT', 'Anche voi... siete ottimi... cacciatori...', '', 28153),
(158910, 'itIT', 'Argh... mi hanno colpito...', '', 28153),
(158909, 'itIT', 'Il mare alla fine ci ingoierà tutti...', '', 28153),
(158908, 'itIT', 'La caccia continuerà... senza di me...', '', 28153),
(158907, 'itIT', 'Non ci pentiamo... di nulla...', '', 28153),
(158906, 'itIT', 'Sembra che degli stranieri siano sbarcati.', '', 28153),
(158905, 'itIT', 'Vi ringraziamo per il vostro sacrificio.', '', 28153),
(158904, 'itIT', 'Prendete le loro cose. Stasera banchetteremo!', '', 28153),
(158903, 'itIT', 'Osate affrontare il nostro clan?', '', 28153),
(158902, 'itIT', 'Il vostro sangue alimenterà la caccia.', '', 28153),
(158901, 'itIT', 'Il vostro corpo ci sostenterà, grazie.', '', 28153),
(158900, 'itIT', 'Il mare ci ha portato nuovi rifornimenti...', '', 28153),
(158899, 'itIT', 'Le onde avevano predetto il vostro arrivo.', '', 28153),
(158898, 'itIT', '', 'Adoro le creature che si possono trovare qui. Coniglietti, uccellini, granchi... Qualsiasi cosa tu possa immaginare. Alcuni di loro li ho addestrati per diventare campioni. Vedi questa grossa carcassa vicino a me? Le mie mascotte ci hanno messo quattro minuti netti. Hanno sempre un sacco di fame. Vuoi vederle in azione?', 28153),
(158897, 'itIT', '', 'Tieni d\'occhio Meerah, d\'accordo?\n\nNon riesce a vedere i veri pericoli del deserto. Non sopporterei l\'idea di vederla ingoiata dalle sabbie...', 28153),
(158896, 'itIT', '', 'Il tuo amico sembra stare molto meglio. Sono felice che Kiro e Meerah siano stati in grado di aiutarti.', 28153),
(158895, 'itIT', '', 'Ti do il benvenuto nella nostra casa, $n, almeno per ora.\n\nLe carovane sono pronte a muoversi in qualsiasi momento, se i Sethrak dovessero scoprire il nostro nascondiglio.', 28153),
(158894, 'itIT', 'Cerca di guidare Loh al sicuro attraversando tutte le alghe lungo la strada.', '', 28153),
(158893, 'itIT', '', 'Certo! Ecco, prendi qualche Bomba di Farina con te. E fa\' attenzione, mi raccomando.', 28153),
(158892, 'itIT', 'Ti va di scambiare qualcosa per un po\' di carne d\'orso?', '', 28153),
(158891, 'itIT', '<Kua\'fon scappa via!>', '', 28153),
(158890, 'itIT', '<Kua\'fon tiene il teschio lontano dalla tua portata, menando la coda con fare dispettoso.>', '', 28153),
(158889, 'itIT', 'Non sei così... forte.', '', 28153),
(158888, 'itIT', 'Prenderò ciò che voglio!', '', 28153),
(158887, 'itIT', 'Mi piace il tuo equipaggiamento... ti va di barattare?', '', 28153),
(158886, 'itIT', 'Ritirata... in acqua...', '', 28153),
(158885, 'itIT', 'Il clan non morirà... oggi...', '', 28153),
(158884, 'itIT', 'Come...?', '', 28153),
(158883, 'itIT', 'Ritorno... tra le onde...', '', 28153),
(158882, 'itIT', 'Il tesoro... era mio...', '', 28153),
(158881, 'itIT', 'Sss... La pagherete...', '', 28153),
(158880, 'itIT', 'Sss... Ladri...', '', 28153),
(158879, 'itIT', 'Ahhh... Il mio sangue...', '', 28153),
(158878, 'itIT', 'Sss! Uccideteli! Difendete il tesoro!', '', 28153),
(158877, 'itIT', 'Le gemme ci rendono forti, non ci inchineremo di fronte a voi!', '', 28153),
(158876, 'itIT', 'Banchetterò con la vostra carne e userò le vostre ossa come stuzzicadenti!', '', 28153),
(158875, 'itIT', 'Osate sfidare un grande guerriero?', '', 28153),
(158874, 'itIT', 'Difenderò il clan! Morirete!', '', 28153),
(158873, 'itIT', 'Intrusi! Uccideteli, miei servi!', '', 28153),
(158872, 'itIT', 'Questo tesoro appartiene al mio clan, siete solo dei ladri!', '', 28153),
(158871, 'itIT', 'Il mio clan è potente, nessuno può fermarci!', '', 28153),
(158870, 'itIT', 'Vedrò di trovarne altro.', 'Vedrò di trovarne altro.', 28153),
(158869, 'itIT', 'Il vostro tesoro sarà nostro!', '', 28153),
(158868, 'itIT', 'Ho del gelato per te!', 'Ho del gelato per te!', 28153),
(158867, 'itIT', 'Vi sventrerò come un pesce!', '', 28153),
(158866, 'itIT', 'Difendete il clan!', '', 28153),
(158865, 'itIT', 'Fateli a pezzi, portatemi il loro bottino!', '', 28153),
(158864, 'itIT', 'Sss! Siamo sotto attacco!', '', 28153),
(158863, 'itIT', 'Sanguecaldo!', '', 28153),
(158862, 'itIT', 'Uccideteli! Prendete tutte le loro cose!', '', 28153),
(158861, 'itIT', 'Sss! Vi uccido!', '', 28153),
(158860, 'itIT', 'È arrivato altro cibo, piccoli miei!', 'È arrivato altro cibo, piccoli miei!', 28153),
(158859, 'itIT', 'Certo. Cosa posso fare per te?', 'Certo. Cosa posso fare per te?', 28153),
(158858, 'itIT', 'Altre vittime cadute nella nostra trappola. Il vostro viaggio è finito...', 'Altre vittime cadute nella nostra trappola. Il vostro viaggio è finito...', 28153),
(158857, 'itIT', 'Carne deliziosa, giunta dritta nella nostra tana. Che gioia.', 'Carne deliziosa, giunta dritta nella nostra tana. Che gioia.', 28153),
(158856, 'itIT', 'Il vostro sangue nutrirà i cuccioli, la vostra carne sazierà le regine, mentre io consumerò il vostro cervello!', 'Il vostro sangue nutrirà i cuccioli, la vostra carne sazierà le regine, mentre io consumerò il vostro cervello!', 28153),
(158855, 'itIT', 'Non troverete mai le uova. Il nostro sciame è eterno!', 'Non troverete mai le uova. Il nostro sciame è eterno!', 28153),
(158854, 'itIT', 'Non agitatevi, prede, prolungherete solamente il vostro dolore!', 'Non agitatevi, prede, prolungherete solamente il vostro dolore!', 28153),
(158853, 'itIT', 'Ah, altre vittime finiscono nelle nostre tele!', 'Ah, altre vittime finiscono nelle nostre tele!', 28153),
(158852, 'itIT', 'Difenderemo la stirpe fino all\'ultimo!', 'Difenderemo la stirpe fino all\'ultimo!', 28153),
(158851, 'itIT', 'Attenti... gli invasori...', 'Attenti... gli invasori...', 28153),
(158850, 'itIT', 'Le uova... sono al sicuro... da voi...', 'Le uova... sono al sicuro... da voi...', 28153),
(158849, 'itIT', 'Non ci troverete... tutti...', 'Non ci troverete... tutti...', 28153),
(158848, 'itIT', 'Non siamo arrivati fin qui... per essere uccisi da voi...', 'Non siamo arrivati fin qui... per essere uccisi da voi...', 28153),
(158847, 'itIT', 'Il mio corpo nutrirà i piccoli...', 'Il mio corpo nutrirà i piccoli...', 28153),
(158846, 'itIT', 'Arghhh... Dolore...', 'Arghhh... Dolore...', 28153),
(158845, 'itIT', 'Difendete... la stirpe...', 'Difendete... la stirpe...', 28153),
(158844, 'itIT', 'Kashhh...', 'Kashhh...', 28153),
(158843, 'itIT', 'I cuccioli si ciberanno della vostra carne!', 'I cuccioli si ciberanno della vostra carne!', 28153),
(158842, 'itIT', 'Venite nella mia tela!', 'Venite nella mia tela!', 28153),
(158841, 'itIT', 'Invasori!', 'Invasori!', 28153),
(158840, 'itIT', 'Proteggeremo la stirpe!', 'Proteggeremo la stirpe!', 28153),
(158839, 'itIT', 'Sangue fresco...', 'Sangue fresco...', 28153),
(158838, 'itIT', 'Le prede sono qui...', 'Le prede sono qui...', 28153),
(158837, 'itIT', 'State disturbando le nostre tele!', 'State disturbando le nostre tele!', 28153),
(158836, 'itIT', 'Kshhh... invasori...', 'Kshhh... invasori...', 28153),
(158835, 'itIT', '', 'Ultimamente mi sono fatta prendere un po\' troppo dalla gola. Quanto vorrei del buon gelato alla fragola!\n\nTe ne sarei immensamente grata se riuscissi a trovarmene un po\'. Se non è un problema, portane abbastanza perché duri per un po\'. Spero che la cosa non ti infastidisca!', 28153),
(158834, 'itIT', '', 'Sembri un po\' $gsciupato, caro:sciupata, cara;. Stai mangiando abbastanza?', 28153),
(158833, 'itIT', '', 'Ohhh. Sei $gvenuto:venuta; fino qui solo per vedermi?', 28153),
(158832, 'itIT', '', 'Ciao, $gcaro:cara;. È bello vederti.', 28153),
(158831, 'itIT', 'Rargh! Rargh!', '', 28153),
(158830, 'itIT', 'Voi... No...', '', 28153),
(158829, 'itIT', 'Arghrrr...', '', 28153),
(158828, 'itIT', 'Grrr...', '', 28153),
(158827, 'itIT', 'Avete... un cattivo odore...', '', 28153),
(158826, 'itIT', 'Devo... scappare...', '', 28153),
(158825, 'itIT', 'Urgh...', '', 28153),
(158824, 'itIT', 'Urgh... grah...', '', 28153),
(158823, 'itIT', 'Nuovo odore, non mi piace!', '', 28153),
(158822, 'itIT', 'Ahhh, sento odore di carne!', '', 28153),
(158821, 'itIT', 'Grah! Buon cibo!', '', 28153),
(158820, 'itIT', 'Vi mangio la carne!', '', 28153),
(158819, 'itIT', 'Morite! Rargh!', '', 28153),
(158818, 'itIT', 'Grrr... voi... io uccido!', '', 28153),
(158817, 'itIT', 'Grrrargh!', '', 28153),
(158816, 'itIT', 'Mmmrrr!', '', 28153),
(158815, 'itIT', 'Queste terre esistono da molto prima di voi e continueranno a farlo dopo la vostra morte.', 'Queste terre esistono da molto prima di voi e continueranno a farlo dopo la vostra morte.', 28153),
(158814, 'itIT', 'Le gemme luminose sono un dono della natura a noi. Le proteggeremo dalla vostra gente!', 'Le gemme luminose sono un dono della natura a noi. Le proteggeremo dalla vostra gente!', 28153),
(158813, 'itIT', 'Il ciclo della vita oggi vi assorbirà. Cresceremo grazie ai vostri resti.', 'Il ciclo della vita oggi vi assorbirà. Cresceremo grazie ai vostri resti.', 28153),
(158812, 'itIT', 'Porrò fine alla vostra minaccia prima che corrompiate ancora le nostre terre.', 'Porrò fine alla vostra minaccia prima che corrompiate ancora le nostre terre.', 28153),
(158811, 'itIT', 'Nutrirete la terra che avete calpestato venendo qui.', 'Nutrirete la terra che avete calpestato venendo qui.', 28153),
(158810, 'itIT', 'La vostra gente non rispetta l\'equilibrio. Non potete continuare a vivere. Devo intervenire!', 'La vostra gente non rispetta l\'equilibrio. Non potete continuare a vivere. Devo intervenire!', 28153),
(158809, 'itIT', 'Devo eliminarvi per preservare l\'equilibrio che avete infranto.', 'Devo eliminarvi per preservare l\'equilibrio che avete infranto.', 28153),
(158808, 'itIT', 'Il nostro compito è difendere questa terra e le sue bestie, non siete i benvenuti qui!', 'Il nostro compito è difendere questa terra e le sue bestie, non siete i benvenuti qui!', 28153),
(158807, 'itIT', 'La vostra gente... è una piaga...', 'La vostra gente... è una piaga...', 28153),
(158806, 'itIT', 'State corrompendo... le nostre terre...', 'State corrompendo... le nostre terre...', 28153),
(158805, 'itIT', 'Non si può uccidere... la natura...', 'Non si può uccidere... la natura...', 28153),
(158804, 'itIT', 'Ricresceremo...', 'Ricresceremo...', 28153),
(158803, 'itIT', 'La vostra gente... non può resistere...', 'La vostra gente... non può resistere...', 28153),
(158802, 'itIT', 'Nutrirò... la terra...', 'Nutrirò... la terra...', 28153),
(158801, 'itIT', 'Avete infranto... l\'equilibrio...', 'Avete infranto... l\'equilibrio...', 28153),
(158800, 'itIT', 'Ritorno... alla natura...', 'Ritorno... alla natura...', 28153),
(158799, 'itIT', 'Il nostro compito è difendere questo posto!', 'Il nostro compito è difendere questo posto!', 28153),
(158798, 'itIT', 'Le gemme luminose sono un dono alla natura!', 'Le gemme luminose sono un dono alla natura!', 28153),
(158797, 'itIT', 'Dobbiamo preservare l\'equilibrio!', 'Dobbiamo preservare l\'equilibrio!', 28153),
(158796, 'itIT', 'Non corromperete la nostra radura!', 'Non corromperete la nostra radura!', 28153),
(158795, 'itIT', 'Rispondo al richiamo della natura!', 'Rispondo al richiamo della natura!', 28153),
(158794, 'itIT', 'Questa terra non sarà profanata da voi, invasori!', 'Questa terra non sarà profanata da voi, invasori!', 28153),
(158793, 'itIT', 'La natura guida la mia ira!', 'La natura guida la mia ira!', 28153),
(158792, 'itIT', 'Devo proteggere la natura!', 'Devo proteggere la natura!', 28153),
(158791, 'itIT', 'Vengo accà tutti i giorni per parlare coi nonni miei. Credo riescano a sentirmi!', '', 28153),
(158790, 'itIT', 'Gruh...', 'Gruh...', 28153),
(158789, 'itIT', 'Dove... sono?', 'Dove... sono?', 28153),
(158788, 'itIT', 'Grah... Sangue...', 'Grah... Sangue...', 28153),
(158787, 'itIT', '', 'Quando avremo vinto la battaglia, comincerà il vero lavoro.', 28153),
(158786, 'itIT', 'La mia ira... ribolle...', 'La mia ira... ribolle...', 28153),
(158785, 'itIT', 'Voi... perché...', 'Voi... perché...', 28153),
(158784, 'itIT', 'Devo... scappare...', 'Devo... scappare...', 28153),
(158783, 'itIT', 'Ora... è tutto più chiaro...', 'Ora... è tutto più chiaro...', 28153),
(158782, 'itIT', 'Argh... Dolore...', 'Argh... Dolore...', 28153),
(158781, 'itIT', 'Argh!', 'Argh!', 28153),
(158780, 'itIT', 'Furia!', 'Furia!', 28153),
(158779, 'itIT', 'Non vi riconosco...', 'Non vi riconosco...', 28153),
(158778, 'itIT', 'Sento la vostra paura...', 'Sento la vostra paura...', 28153),
(158777, 'itIT', 'Sparite... Grrr...', 'Sparite... Grrr...', 28153),
(158776, 'itIT', 'Vi... uccido...', 'Vi... uccido...', 28153),
(158775, 'itIT', 'Grrr!', 'Grrr!', 28153),
(158774, 'itIT', 'Rargh!', 'Rargh!', 28153),
(158773, 'itIT', 'Guarda come sta diventando grande! Proprio come il padre suo.', '', 28153),
(158772, 'itIT', 'Vi maledico...', 'Vi maledico...', 28153),
(158771, 'itIT', 'Riesco a vedere... li antenati...', 'Riesco a vedere... li antenati...', 28153),
(158770, 'itIT', 'Li spiriti... mi accolgono...', 'Li spiriti... mi accolgono...', 28153),
(158769, 'itIT', 'Nun tenete... alcun onore...', 'Nun tenete... alcun onore...', 28153),
(158768, 'itIT', 'Uh... mi avete pigliato...', 'Uh... mi avete pigliato...', 28153),
(158767, 'itIT', 'Nun riuscirete ad acciderci... tutti...', 'Nun riuscirete ad acciderci... tutti...', 28153),
(158766, 'itIT', 'Mi vendicherò... dall\'Aldilà...', 'Mi vendicherò... dall\'Aldilà...', 28153),
(158765, 'itIT', 'Mi unisco alli spiriti...', 'Mi unisco alli spiriti...', 28153),
(158764, 'itIT', 'Farò nu feticcio con le ossa che tenete e maledirò le famiglie vostre!', 'Farò nu feticcio con le ossa che tenete e maledirò le famiglie vostre!', 28153),
(158763, 'itIT', 'Nun siete altro che luridi stranieri. Nun potete stare accà!', 'Nun siete altro che luridi stranieri. Nun potete stare accà!', 28153),
(158762, 'itIT', '', 'Ricordo come fosse ieri quando è nato il piccirillo del piccirillo nostro. Guardalo mo\'!', 28153),
(158761, 'itIT', 'E voi chi siete? Nun siete benvenuti.', 'E voi chi siete? Nun siete benvenuti.', 28153),
(158760, 'itIT', 'Vediamo che sapete fare, allora.', 'Vediamo che sapete fare, allora.', 28153),
(158759, 'itIT', 'Ora teniamo le gemme, il clan mio è il più forte di tutti!', 'Ora teniamo le gemme, il clan mio è il più forte di tutti!', 28153),
(158758, 'itIT', 'Nun mi troverete così facilmente, eheheh.', 'Nun mi troverete così facilmente, eheheh.', 28153),
(158757, 'itIT', 'Chesta è l\'isola mia, dove stanno le gemme mie. Accà nun troverete altro che la morte.', 'Chesta è l\'isola mia, dove stanno le gemme mie. Accà nun troverete altro che la morte.', 28153),
(158756, 'itIT', 'Abbiamo trovato noi chesto posto, nun ce lo piglierete!', 'Abbiamo trovato noi chesto posto, nun ce lo piglierete!', 28153),
(158755, 'itIT', 'Chesta è la nostra isola!', 'Chesta è la nostra isola!', 28153),
(158754, 'itIT', 'Che ci fate su chest\'isola?', 'Che ci fate su chest\'isola?', 28153),
(158753, 'itIT', 'Siamo sotto attacco, cumpà! Venite accà!', 'Siamo sotto attacco, cumpà! Venite accà!', 28153),
(158752, 'itIT', 'Fateli a fettine!', 'Fateli a fettine!', 28153),
(158751, 'itIT', 'Mi guarderete mentre vi mangio!', 'Mi guarderete mentre vi mangio!', 28153),
(158750, 'itIT', 'Vi spelleremo vivi!', 'Vi spelleremo vivi!', 28153),
(158749, 'itIT', 'Farò na collana con le ossa vostre!', 'Farò na collana con le ossa vostre!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158748, 'itIT', 'Vi squarterò e berrò il sangue vostro, cumpà!', 'Vi squarterò e berrò il sangue vostro, cumpà!', 28153),
(158747, 'itIT', 'Ahhh! Muoio con onore!', '', 28153),
(158746, 'itIT', 'Siete voi... gli invasori... Noi non abbiamo...', '', 28153),
(158745, 'itIT', 'Le gemme... non ci hanno salvato...', '', 28153),
(158744, 'itIT', 'Torneremo... più numerosi...', '', 28153),
(158743, 'itIT', 'Le stelle... hanno mentito...', '', 28153),
(158742, 'itIT', 'Sento il richiamo... degli antichi...', '', 28153),
(158741, 'itIT', 'Gli spiriti mi danno il benvenuto...', '', 28153),
(158740, 'itIT', 'Ritorno... dai miei antenati...', '', 28153),
(158739, 'itIT', 'Le stelle guidano i miei pugni. Il futuro è scritto col vostro sangue!', '', 28153),
(158738, 'itIT', 'I venti hanno predetto la vostra caduta.', '', 28153),
(158737, 'itIT', 'Gli spiriti mi daranno la forza di una fiamma inestinguibile!', '', 28153),
(158736, 'itIT', 'Vi state lanciando in uno scontro che non potete vincere!', '', 28153),
(158735, 'itIT', 'I tesori dell\'isola sono solo nostri!', '', 28153),
(158734, 'itIT', 'Gli antenati mi daranno forza e saggezza!', '', 28153),
(158733, 'itIT', 'Intingerò le mie corna nel vostro sangue, stolti!', '', 28153),
(158732, 'itIT', 'Difenderò il mio clan!', '', 28153),
(158731, 'itIT', 'Guerrieri, aiutatemi!', '', 28153),
(158730, 'itIT', 'Radunatevi, siamo sotto attacco!', '', 28153),
(158729, 'itIT', 'Questa è la nostra isola, non c\'è nulla per voi qui!', '', 28153),
(158728, 'itIT', 'Le gemme luminose sono nostre, non avete alcuna possibilità!', '', 28153),
(158727, 'itIT', 'Non ci ruberete questo luogo!', '', 28153),
(158726, 'itIT', 'Invasori! Respingeteli!', '', 28153),
(158725, 'itIT', 'Spiriti, guidate la mia arma!', '', 28153),
(158724, 'itIT', 'Per gli antenati!', '', 28153),
(158723, 'itIT', 'Fa... male...', '', 28153),
(158722, 'itIT', 'Perché... voi qui?', '', 28153),
(158721, 'itIT', 'Argh! Proprio in pancia...', '', 28153),
(158720, 'itIT', 'Siete... ladri...', '', 28153),
(158719, 'itIT', 'No! Mie gemme...', '', 28153),
(158718, 'itIT', 'Perché... avete fatto?', '', 28153),
(158717, 'itIT', 'No bene...', '', 28153),
(158716, 'itIT', 'Perché buio ora?', '', 28153),
(158715, 'itIT', '', 'Ci stanno chelli che credono che nu patto sia solo nu patto, nu sacco di promesse vuote fatte solo perché si deve. Ricompense nel presente, in cambio di nu futuro ignoto.\n\nRicorda chesto: alla fine, Bwonsamdi incassa sempre ogni debito.', 28153),
(158714, 'itIT', 'Tutti miei Ogre, ora di spaccare!', '', 28153),
(158713, 'itIT', 'No! Mie gemme! No vostre! Servono a me!', '', 28153),
(158712, 'itIT', 'Gemme ci rendono forti. Più forti di voi!', '', 28153),
(158711, 'itIT', 'Io prende vostra testa come trofeo quando finito!', '', 28153),
(158710, 'itIT', 'Prendeteli! Spaccate schiena!', '', 28153),
(158709, 'itIT', 'Questa mia isola, insetti! Mia!', '', 28153),
(158708, 'itIT', 'Io schiaccia voi, poi beve vostro sangue!', '', 28153),
(158707, 'itIT', 'Io spacca voi a pezzi! Rrrawgh!', '', 28153),
(158706, 'itIT', 'Queste mie gemme! Rrrawgh!', '', 28153),
(158705, 'itIT', 'Voi non prendere nostra roba!', '', 28153),
(158704, 'itIT', 'Prendeteli!', '', 28153),
(158703, 'itIT', 'Voi no prendere gemme!', '', 28153),
(158702, 'itIT', 'Questa mia isola! Andate via!', '', 28153),
(158701, 'itIT', 'Uccidete intrusi!', '', 28153),
(158700, 'itIT', 'Schiaccia, spacca, uccidi!', '', 28153),
(158699, 'itIT', 'Io schiaccia voi!', '', 28153),
(158698, 'itIT', 'Forse se solo prometto di essere na persona migliore d\'ora in poi... Nun come l\'ultima volta!', 'Forse se solo prometto di essere na persona migliore d\'ora in poi... Nun come l\'ultima volta!', 28153),
(158697, 'itIT', 'Cosa credi che Bwonsamdi potrebbe volere da me?', 'Cosa credi che Bwonsamdi potrebbe volere da me?', 28153),
(158696, 'itIT', 'Che devo fare... Che devo fare... Dev\'esserci nu modo per uscire da accà!', 'Che devo fare... Che devo fare... Dev\'esserci nu modo per uscire da accà!', 28153),
(158695, 'itIT', 'Se faccio nu patto con Bwonsamdi, tutto tornerà normale, vero?', 'Se faccio nu patto con Bwonsamdi, tutto tornerà normale, vero?', 28153),
(158694, 'itIT', 'Odio tutto chesto! Odio ogni cosa!', 'Odio tutto chesto! Odio ogni cosa!', 28153),
(158693, 'itIT', 'Chesto nun è accettabile! Nun sanno chi sono?', 'Chesto nun è accettabile! Nun sanno chi sono?', 28153),
(158692, 'itIT', 'Piglierò chiunque mi abbia fatto chesto! Anche se fosse l\'ultima cosa che faccio!', 'Piglierò chiunque mi abbia fatto chesto! Anche se fosse l\'ultima cosa che faccio!', 28153),
(158691, 'itIT', 'Com\'è potuto succedere? Nun è giusto!', 'Com\'è potuto succedere? Nun è giusto!', 28153),
(158690, 'itIT', 'Le cose nun miglioreranno e nun riuscirai a convincermi del contrario.', 'Le cose nun miglioreranno e nun riuscirai a convincermi del contrario.', 28153),
(158689, 'itIT', 'Stava andando tutto così bene, e mo\'... mo\' nun mi resta più nulla.', 'Stava andando tutto così bene, e mo\'... mo\' nun mi resta più nulla.', 28153),
(158688, 'itIT', 'Nun sentirò mai più il Sole sulla pelle mia.', 'Nun sentirò mai più il Sole sulla pelle mia.', 28153),
(158687, 'itIT', 'Se solo avessi avuto qualche giorno in più... Quante cose avrei potuto fare.', 'Se solo avessi avuto qualche giorno in più... Quante cose avrei potuto fare.', 28153),
(158686, 'itIT', 'Morto? No, sto solo facendo nu pisolino.', 'Morta? No, sto solo facendo nu pisolino.', 28153),
(158685, 'itIT', 'E tu chi saresti? Nun importa, nun può essere così importante...', 'E tu chi saresti? Nun importa, nun può essere così importante...', 28153),
(158684, 'itIT', 'Se nun lo vedo, allora nun sta succedendo. Nulla di più semplice.', 'Se nun lo vedo, allora nun sta succedendo. Nulla di più semplice.', 28153),
(158683, 'itIT', 'Continua... Continua... Nu giorno le cose andranno a posto...', 'Continua... Continua... Nu giorno le cose andranno a posto...', 28153),
(158682, 'itIT', 'Come osi mettere piede nella MIA proprietà. Basta!', '', 28153),
(158681, 'itIT', 'Sei debole. Affrontami in un vero combattimento!', '', 28153),
(158680, 'itIT', 'Credi che la tua ridicola macchina possa far qualcosa contro di me?!?', '', 28153),
(158679, 'itIT', 'Ma guarda, è $garrivato uno sfidante:arrivata una sfidante;! Addosso!', '', 28153),
(158678, 'itIT', 'Ma... sono troppo bello per morire...', '', 28153),
(158677, 'itIT', '', 'Ti... squarterò...', 28153),
(158676, 'itIT', '', 'Vi farò a pezzi!', 28153),
(158675, 'itIT', 'Seppellitemi in mare...', '', 28153),
(158674, 'itIT', 'Ti farò fare un giro di chiglia!', '', 28153),
(158673, 'itIT', 'Uh. Non sono sicuro cosa sia peggio... la quantità di prodotti per capelli che usa o la sua \"arte\" poetica. Reed è un combattente, ma anche un donnaiolo.', '', 28153),
(158672, 'itIT', 'Beckett crede di essere una leggenda.', '', 28153),
(158671, 'itIT', 'Luna è un po\'... dura, diciamo.', '', 28153),
(158670, 'itIT', 'Eheh... Le uniche cose certe al mondo sono... le tasse e...', '', 28153),
(158669, 'itIT', 'Cos\'abbiamo qui? Sembra proprio un conto da saldare!', '', 28153),
(158668, 'itIT', '', 'Prego che non sia troppo tardi. Vai, fa\' in fretta, trova mia figlia.', 28153),
(158666, 'itIT', '', 'Fine del Destino è un\'isola al largo della costa di Sacraonda. Lì vengono portati i peggiori criminali e nessuno di loro ha mai fatto ritorno.', 28153),
(158665, 'itIT', '', 'Eccoti! Cos\'hai trovato?', 28153),
(158661, 'itIT', 'Io me ne vado di qui! Grazie per l\'aiuto, $p!', '', 28153),
(158660, 'itIT', '<Kua\'fon emette un forte strillo e sferza la sua coda in preda all\'eccitazione.>', '', 28153),
(158659, 'itIT', '<Kua\'fon ripone il teschio nella tua mano.>', '', 28153),
(158658, 'itIT', '<Kua\'fon fa cadere il teschio davanti a sé e strilla giocosamente verso di te.>', '', 28153),
(158657, 'itIT', '', 'Questa guerra è persa. Presto Teldrassil cadrà.', 28153),
(158656, 'itIT', 'Le maree ti ingoieranno in un boccone!', '', 28153),
(158655, 'itIT', 'Vieni. Dobbiamo seguire la nostra Capoguerra verso... la vittoria.', '', 28153),
(158654, 'itIT', '', 'Sembra funzionare. Forza, tutti su!', 28153),
(158653, 'itIT', 'Anche tu devi fare una scelta. Portarlo a Darnassus e morire entrambi quando la conquisteremo, o scappare lontano da qui e sopravvivere.', '', 28153),
(158652, 'itIT', '', 'Hai risparmiato Malfurion, quindi ti propongo una scelta.', 28153),
(158651, 'itIT', '', 'Rimanete saldi.', 28153),
(158650, 'itIT', 'Non \"per niente\". È stato versato affinché l\'Orda potesse resistere.', '', 28153),
(158649, 'itIT', '', 'Tutta questa guerra è senza onore. Come osi versare tutto questo sangue... per niente!', 28153),
(158648, 'itIT', 'Ho colpito senza onore. Non merito di porre fine alla sua vita.', '', 28153),
(158647, 'itIT', '', 'Non l\'hai ucciso, Orco. Perché?', 28153),
(158646, 'itIT', '', 'Malfurion! No!', 28153),
(158645, 'itIT', 'Hai guidato... la tua Orda... nel nome... della morte. Rimpiangerai... questo giorno...', '', 28153),
(158642, 'itIT', '', 'Curati le ferite e riposati le ossa. Qui sei al sicuro.', 28153),
(158641, 'itIT', 'Sono schiattato per aver sfidato la bestia sbagliata. Sai a chi mi riferisco.', 'Sono schiattata per aver sfidato la bestia sbagliata. Sai a chi mi riferisco.', 28153),
(158640, 'itIT', 'Sono confuso tanto quanto te, cumpà.', 'Sono confusa tanto quanto te, cumpà.', 28153),
(158639, 'itIT', 'Nun sono riuscito a resistere alla piccantezza del chili di Haw\'li.', 'Nun sono riuscita a resistere alla piccantezza del chili di Haw\'li.', 28153),
(158638, 'itIT', 'Sono schiattato mentre correvo alla Torcanata. E lo rifarei, se potessi!', 'Sono schiattata mentre correvo alla Torcanata. E lo rifarei, se potessi!', 28153),
(158637, 'itIT', 'Hai lasciato pure tu il corpo nel guardaroba?', 'Hai lasciato pure tu il corpo nel guardaroba?', 28153),
(158636, 'itIT', 'Sono stato colpito da nu fulmine passeggiando allo Zocalo.', 'Sono stata colpita da nu fulmine passeggiando allo Zocalo.', 28153),
(158635, 'itIT', 'Sono schiattato cadendo dalla piramide e mo\' nun ricordo come sono finito accà.', 'Sono schiattata cadendo dalla piramide e mo\' nun ricordo come sono finita accà.', 28153),
(158634, 'itIT', 'Sono vestito a festa, ma nun tengo alcun posto dove andare.', 'Sono vestita a festa, ma nun tengo alcun posto dove andare.', 28153),
(158633, 'itIT', 'Calcolare la posizione corretta per aprire questo portale a Boralus non è stata una cosa facile, ma è stata una bella sfida! Fammi sapete com\'è andata, poi.', '', 28153),
(158632, 'itIT', 'Come desideri, Nathanos.', '', 28153),
(158631, 'itIT', 'Zelling, accompagna $n a Boralus. Oculeth vi aspetta con un portale.', '', 28153),
(158630, 'itIT', 'Salve, eroe. Dobbiamo parlare.', '', 28153),
(158629, 'itIT', 'Questa è la migliore sedia della casa... Puoi averla, quando mi alzo.', '', 28153),
(158628, 'itIT', '', '$p? Pfff, nun ho mai sentito parlare di te.', 28153),
(158627, 'itIT', 'Quando sei $gpronto:pronta; a raggiungere le navi, ci penserà Hobart ad aiutarti.', '', 28153),
(158626, 'itIT', 'Nun dire che nun ti avevamo $gavvertito:avvertita;!', 'Nun dire che nun ti avevamo $gavvertito:avvertita;!', 28153),
(158625, 'itIT', 'Sta\' indietro! È pericoloso.', 'Sta\' indietro! È pericoloso.', 28153),
(158624, 'itIT', '<Kua\'fon trema di paura.>', '', 28153),
(158623, 'itIT', 'I venti ora soffiano a nostro favore, non credi, $n?', '', 28153),
(158622, 'itIT', 'Vedo grandi cose all\'orizzonte, sia per me che per te.', '', 28153),
(158621, 'itIT', 'Nun puoi lasciarmi accà. Le ossa mie sono troppo vecchie per lavorare in cheste miniere.', 'Nun puoi lasciarmi accà. Le ossa mie sono troppo vecchie per lavorare in cheste miniere.', 28153),
(158620, 'itIT', 'Forse ho capito cos\'è andato storto con la fermentazione.', '', 28153),
(158619, 'itIT', 'L\'introduzione di contaminanti ignoti potrebbe avere un impatto sul processo iniziale di riduzione.', '', 28153),
(158618, 'itIT', 'Ricevuto.', '', 28153),
(158617, 'itIT', 'Farò qualunque cosa per dare una mano.', '', 28153),
(158616, 'itIT', 'Torno al lavoro.', '', 28153),
(158615, 'itIT', 'Certo, ti aiuterò.', '', 28153),
(158614, 'itIT', 'Credo di poter dare una mano.', '', 28153),
(158612, 'itIT', '', 'Guardati bene le spalle. Questi alberi hanno occhi ovunque. Accecali.', 28153),
(158611, 'itIT', 'Dovremmo concentrarci sullo stabilizzare i componenti principali, prima.', '', 28153),
(158610, 'itIT', 'Ohhh! Questo spiega molte cose! \"Prima legge dell\'Alchimia: per creare qualcosa di benefico, è necessaria una sostituzione reciproca.\"', '', 28153),
(158609, 'itIT', 'Facciamolo!', 'Facciamolo!', 28153),
(158608, 'itIT', 'Intrigante... L\'applicazione perfetta del calore è cruciale.', '', 28153),
(158607, 'itIT', 'Ahhh! Credo di aver capito cosa non ha funzionato del catalizzatore.', '', 28153),
(158606, 'itIT', 'Strano... Sarebbe stato impossibile per noi prevederlo.', '', 28153),
(158605, 'itIT', 'Mmm... Davvero interessante.', '', 28153),
(158604, 'itIT', 'Alcuni dei nostri sono stati catturati là fuori. Ti va di dar loro una mano?', '', 28153),
(158603, 'itIT', 'Ehi! Qualcuno si è fregato parte della nostra roba! Dobbiamo riprendercela, subito! Preferibilmente con gli interessi.', '', 28153),
(158602, 'itIT', 'Ohhh, ci sono feriti ovunque. Dobbiamo aiutarli!', '', 28153),
(158601, 'itIT', 'Ho un lavoro per un ladro esperto! Ce n\'è uno nei paraggi?', '', 28153),
(158600, 'itIT', 'Vedi se trovi delle parti di Treruote da Guerra là fuori. Ti ci farò fare un giro quando sarà nuovamente funzionante.', '', 28153),
(158599, 'itIT', 'C\'è una cosa che ha bisogno di un buon vecchio trattamento in stile Kezan.', '', 28153),
(158598, 'itIT', 'Guarda quant\'è GRANDE quell\'affare. Ehi, qualcuno vuole andare a ucciderlo?', '', 28153),
(158597, 'itIT', 'Parte delle nostre forze dell\'Alleanza è stata catturata. Che ne dici di un\'operazione di recupero?', '', 28153),
(158596, 'itIT', 'Delle forze nemiche sono fuggite con rifornimenti essenziali. Che ne dici di \"rifornire\" quei ladri con un po\' di giustizia dell\'Alleanza?', '', 28153),
(158595, 'itIT', 'Abbiamo dei soldati feriti sul campo. C\'è qualche medico?', '', 28153),
(158594, 'itIT', 'Sì, Elune era con loro. Ha benedetto i druidi con la forza di creare venti impetuosi per gonfiare le loro vele.', '', 28153),
(158593, 'itIT', '', 'Il Mar Velato è stato gentile con loro, Shan\'do?', 28153),
(158592, 'itIT', 'Rimandami al porto.', 'Rimandami al porto.', 28153),
(158591, 'itIT', 'Mandami sulla nave più piccola.', 'Mandami sulla nave più piccola.', 28153),
(158590, 'itIT', 'Siamo alla ricerca di volontari per un\'operazione segreta. Sono necessari talento e un ottimo grado di furtività.', '', 28153),
(158589, 'itIT', 'Stiamo cercando di recuperare alcune parti di una macchina da guerra nemica. Riporta qualunque pezzo tu riesca a trovare.', '', 28153),
(158588, 'itIT', 'Ah, ecco un bersaglio facile.', '', 28153),
(158587, 'itIT', 'Sembra che qualche gigantesca creatura ostile sia passata per il campo. Che la caccia abbia inizio!', '', 28153),
(158586, 'itIT', 'Vuoi salutare il mio amichetto?', '', 28153),
(158585, 'itIT', 'Sei un vero calcio nelle bombe.', '', 28153),
(158584, 'itIT', 'Ehi, piantala.', '', 28153),
(158583, 'itIT', 'Vedi di tornare con le tasche piene!', '', 28153),
(158582, 'itIT', 'Tieni gli occhi aperti.', '', 28153),
(158581, 'itIT', 'Attenzione là fuori.', '', 28153),
(158580, 'itIT', 'Che novità ci sono?', '', 28153),
(158579, 'itIT', 'Come butta?', '', 28153),
(158578, 'itIT', 'Ehilà, salve!', '', 28153),
(158577, 'itIT', 'Per la Luce, mi farebbe comodo un altro bicchiere.', '', 28153),
(158576, 'itIT', 'Nemmeno lo stipendio di un ufficiale vale tutta questa pena.', '', 28153),
(158575, 'itIT', 'Sì, sì...', '', 28153),
(158574, 'itIT', 'Muoviti.', '', 28153),
(158573, 'itIT', 'Puoi andare.', '', 28153),
(158572, 'itIT', 'Tieni d\'occhio i tuoi nemici.', '', 28153),
(158571, 'itIT', 'Sì?', '', 28153),
(158570, 'itIT', 'Hai la mia più completa attenzione.', '', 28153),
(158569, 'itIT', 'Gloria all\'Alleanza.', '', 28153),
(158568, 'itIT', '', 'No... Non può essere.', 28153),
(158565, 'itIT', '', 'Mi aiuterai a saggiare i limiti del mio potere!', 28153),
(158564, 'itIT', '', 'Alcuni dicono che la mia magia è crudele, ma io voglio solo esplorare i limiti di ciò che è possibile.', 28153),
(158563, 'itIT', 'Radicamento', 'Radicamento', 28153),
(158562, 'itIT', 'Mia... MIA! Apri gli occhi, mia regina... mia amata!', '', 28153),
(158561, 'itIT', 'Che la vostra dea vegli su di voi.', '', 28153),
(158560, 'itIT', 'La Banshee ha assassinato mio figlio, rubato il mio regno. Non mi porterà via anche la mia amata!', '', 28153),
(158559, 'itIT', '', 'Loro... non verranno...', 28153),
(158558, 'itIT', 'Astarii, hai fatto ciò che potevi! Ordina ai Sacerdoti di venire con noi!', '', 28153),
(158557, 'itIT', 'Giammai! Salverò entrambe!', '', 28153),
(158555, 'itIT', '', 'L\'albero... stanno bruciando l\'albero! La bambina... salva lei. Lasciami qui...', 28153),
(158554, 'itIT', 'Non potete più stare qui! Dovete scappare attraverso il portale!', '', 28153),
(158553, 'itIT', '', 'Non c\'è tempo da perdere, Astarii. Dobbiamo evacuare la città prima che sia ridotta in cenere!', 28153),
(158551, 'itIT', '', 'Finiscilo. Prenditi un momento, se vuoi... poi prendi la sua testa. Ci incontreremo all\'Albero del Mondo.', 28153),
(158550, 'itIT', '', 'La mia vittoria era inevitabile. Mi stava solo facendo perdere tempo.', 28153),
(158549, 'itIT', 'Non avrei dovuto... interferire.', '', 28153),
(158548, 'itIT', '', 'Non devi pentirtene. Hai agito bene.', 28153),
(158547, 'itIT', 'È stato un attacco disonorevole. Uh...Mi dispiace.', '', 28153),
(158546, 'itIT', 'ARGH! Fauci... saure!?!', '', 28153),
(158545, 'itIT', 'La Capoguerra affronta Grantempesta da sola! Devo...', '', 28153),
(158544, 'itIT', 'Da nord? Come... ah, ma certo, hanno scalato le montagne di Vilbosco. Non c\'è altra spiegazione!', '', 28153),
(158543, 'itIT', 'Campione, Delaryn. Intercettateli ad Auberdine. Io andrò a nord.', '', 28153),
(158542, 'itIT', 'È solo questione di tempo prima che l\'Orda sfondi le mura. Ci attaccheranno da entrambi i lati.', '', 28153),
(158541, 'itIT', 'I Fuochi Fatui... sono disorientati! Le mura stanno cedendo!', '', 28153),
(158540, 'itIT', '', 'Questo suono... Potrebbe essere... Shan\'do! L\'Orda sta arrivando da nord!', 28153),
(158539, 'itIT', '', 'È giunta l\'ora. L\'Albero del Mondo è nostro! Trova Faucisaure. Finiremo questa storia una volta per tutte.', 28153),
(158537, 'itIT', '', 'Guardati attorno. Che vista magnifica! I Fuochi Fatui sono in fuga. Uno dopo l\'altro, stanno abbandonando il muro.', 28153),
(158536, 'itIT', '', 'Faucisaure! Era ora.', 28153),
(158535, 'itIT', 'PER L\'ORDA!', '', 28153),
(158534, 'itIT', '', 'Dove credi di andare, uccellino?', 28153),
(158533, 'itIT', '', 'Argh! Gli occhi! Brucia!', 28153),
(158532, 'itIT', 'Vattene, strega!', '', 28153),
(158531, 'itIT', '', 'Chi avrebbe mai detto che saresti venuto a proteggere i tuoi preziosi alberelli?', 28153),
(158530, 'itIT', '', 'Malfurion! Gentile da parte tua unirti a noi...', 28153),
(158529, 'itIT', 'Sylvanas! La tua sporca razza ha profanato questo sacro luogo! Andu-falah-dor!', '', 28153),
(158528, 'itIT', '', 'Non possiamo concederci il lusso di una serena nottata di riposo. Siamo in guerra.', 28153),
(158527, 'itIT', '', 'Nel frattempo, faremo il possibile per mantenere i Kaldorei sotto pressione.', 28153),
(158526, 'itIT', '', 'Io continuerò a comandare le truppe alle mura mentre attendiamo notizie da Faucisaure.', 28153),
(158525, 'itIT', '', 'Dobbiamo stringere i denti, per ora.', 28153),
(158524, 'itIT', '', 'La battaglia al Fiume Lettocurvo è in stallo e Malfurion lo sa bene.', 28153),
(158523, 'itIT', '', 'Campioni dell\'Orda, il vostro aiuto è richiesto al Fiume Lettocurvo! È la nostra occasione di vittoria!', 28153),
(158522, 'itIT', '', '... Che si va a caccia di corvi.', 28153),
(158521, 'itIT', '', 'Forza, occupatevi di questo posto. Date l\'Azerite ai nostri ingegneri quando ne avrete raccolta a sufficienza.', 28153),
(158520, 'itIT', '', 'Quella nave dev\'essere arrivata da Darnassus... Il che significa...', 28153),
(158519, 'itIT', '', 'Procedi con cautela. Sembra che l\'Alleanza ci abbia preceduti.', 28153),
(158518, 'itIT', '', 'Azerite... Con questa nelle nostre mani, chiunque oserà opporsi all\'Orda perirà.', 28153),
(158517, 'itIT', '', 'Genieri! Prendete l\'equipaggiamento e seguitemi! Portate ogni Segatronchi a disposizione.', 28153),
(158516, 'itIT', '', 'Poni fine alla loro esistenza o ricopriranno questa foresta col sangue della nostra gente.', 28153),
(158515, 'itIT', '', 'Mmm. Vedo che non sei più molto a tuo agio. Questi Antichi sono stati aizzati contro di te, Druido... contro il loro sacro compito.', 28153),
(158514, 'itIT', 'Taelia! Un aiutino ci farebbe comodo!', '', 28153),
(158513, 'itIT', 'E con questo intendo \"saltare giù dall\'altura verso la salvezza\". Andiamo!', '', 28153),
(158512, 'itIT', 'E lanciarci in un\'uscita teatrale!', '', 28153),
(158511, 'itIT', 'Dobbiamo solo prendere la cassa...', '', 28153),
(158510, 'itIT', 'Non pensavo che il sole potesse essere così duro sulla pelle rimasta.', 'Non pensavo che il sole potesse essere così duro sulla pelle rimasta.', 28153),
(158509, 'itIT', 'Ti assicuro che il mio piano è geniale.', '', 28153),
(158508, 'itIT', 'Immagino che tu abbia un piano per uscire di qui con quello...', 'Immagino che tu abbia un piano per uscire di qui con quello...', 28153),
(158507, 'itIT', 'Harlan ha aumentato i livelli di sicurezza aggiungendo un altro lucchetto al suo forziere.\n\n<Flynn si gratta il mento.>\n\nGià, al momento non si può fare niente... se non portarlo via per intero.', '', 28153),
(158506, 'itIT', 'Ottima mossa, Harlan. Ottima mossa...', '', 28153),
(158505, 'itIT', 'Sto pensando a un centinaio di giri attorno all\'accademia per ogni cadetto che trovo.', '', 28153),
(158504, 'itIT', 'Devono essere qui da qualche parte.', '', 28153),
(158503, 'itIT', 'Non abbiamo mai chiesto di essere riportati indietro... o di subire tutto questo.', 'Non abbiamo mai chiesto di essere riportati indietro... o di subire tutto questo.', 28153),
(158502, 'itIT', 'Quattro lucchetti?!? Quattro?!?', '', 28153),
(158501, 'itIT', 'L\'Alleanza osa pensare che siamo NOI i mostri?', 'L\'Alleanza osa pensare che siamo NOI i mostri?', 28153),
(158500, 'itIT', 'Dove sono andati quei cadetti...', '', 28153),
(158499, 'itIT', 'Aaah... eccolo qua, il forziere di Harlan Sweete.', '', 28153),
(158498, 'itIT', 'Con tutto quello che è successo, non posso dire di invidiarla. Ma forse è arrivato il momento per lei di lasciare Kul Tiras in mano a qualcuno più qualificato.', 'Con tutto quello che è successo, non posso dire di invidiarla. Ma forse è arrivato il momento per lei di lasciare Kul Tiras in mano a qualcuno più qualificato.', 28153),
(158497, 'itIT', 'Ogni giorno che passa, diventa sempre più ovvio che Katherine stia solo seguendo le orme del suo defunto marito.', 'Ogni giorno che passa, diventa sempre più ovvio che Katherine stia solo seguendo le orme del suo defunto marito.', 28153),
(158496, 'itIT', 'Un\'altra settimana è passata senza alcun incontro tra le casate.', 'Un\'altra settimana è passata senza alcun incontro tra le casate.', 28153),
(158495, 'itIT', 'Già. Qualsiasi nobile di Tiragarde degno del suo nome avrebbe avuto il buon senso di non dar vita a una storia così triste che la vittima avrebbe potuto sfruttare a proprio vantaggio.', 'Già. Qualsiasi nobile di Tiragarde degno del suo nome avrebbe avuto il buon senso di non dar vita a una storia così triste che la vittima avrebbe potuto sfruttare a proprio vantaggio.', 28153),
(158494, 'itIT', 'Assassinato il giorno del loro matrimonio. Un piano da dilettanti.', 'Assassinato il giorno del loro matrimonio. Un piano da dilettanti.', 28153),
(158493, 'itIT', 'Parli del suo fidanzato? Certo, proprio un peccato.', 'Parli del suo fidanzato? Certo, proprio un peccato.', 28153),
(158492, 'itIT', 'Hai sentito cos\'è successo alla figlia di Crestabianca?', 'Hai sentito cos\'è successo alla figlia di Crestabianca?', 28153),
(158491, 'itIT', 'Che delusione. Come si fa a chiamarsi Sacraonda e non essere in grado di invocare l\'aiuto del mare? Se facessi parte di quella famiglia, avrei diseredato il ragazzo molto tempo fa.', 'Che delusione. Come si fa a chiamarsi Sacraonda e non essere in grado di invocare l\'aiuto del mare? Se facessi parte di quella famiglia, avrei diseredato il ragazzo molto tempo fa.', 28153),
(158490, 'itIT', 'Quindi suo zio l\'ha semplicemente spedito qui per occuparci del problema?', 'Quindi suo zio l\'ha semplicemente spedito qui per occuparci del problema?', 28153),
(158489, 'itIT', 'Ho sentito che Brannon è tornato a lavorare qui nella Baia.', 'Ho sentito che Brannon è tornato a lavorare qui nella Baia.', 28153),
(158488, 'itIT', 'È un sollievo vedere che Jaina ha preso il gusto da sua madre. Non si può dire che Daelin avesse un gran bell\'aspetto.', 'È un sollievo vedere che Jaina ha preso il gusto da sua madre. Non si può dire che Daelin avesse un gran bell\'aspetto.', 28153),
(158487, 'itIT', '', '<C\'è un pugnale conficcato nella sua schiena e tutti i suoi averi sono stati rubati.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158486, 'itIT', '', '<Questo cadavere di Zandalari sembra fresco.>', 28153),
(158485, 'itIT', '<Esamina il corpo.>', '<Esamina il corpo.>', 28153),
(158484, 'itIT', 'I Crestabianca non fanno visita a Boralus da molto tempo. Mi chiedo se Meredith abbia finalmente capito che non ha posto qui.', 'I Crestabianca non fanno visita a Boralus da molto tempo. Mi chiedo se Meredith abbia finalmente capito che non ha posto qui.', 28153),
(158483, 'itIT', 'Hai visto Ser Sacraonda l\'ultima volta che è stato qui? Un cappello con dei tentacoli lo trovo un po\' troppo all\'antica, se posso dire la mia.', 'Hai visto Ser Sacraonda l\'ultima volta che è stato qui? Un cappello con dei tentacoli lo trovo un po\' troppo all\'antica, se posso dire la mia.', 28153),
(158482, 'itIT', '<Simon osserva Kunga.>\n\nMmm, sì... Ah! Ahahah! Sei proprio divertente, $gamico mio:amica mia;! Proprio divertente!\n\nOra dovresti andare, prima che ne trovi un\'altra. Ahah!\n\nVai a guardare lo scontro mentre... riempio i magazzini.', '', 28153),
(158481, 'itIT', 'Ho trovato un corpo dietro la tenda.', 'Ho trovato un corpo dietro la tenda.', 28153),
(158480, 'itIT', 'Oh, salve.\n\nTi do il benvenuto nel mio negozio, lo Speciale... Spaccio... Scontato... di Simon.\n\nVendo...\n\n<Simon scruta dietro di lui velocemente.>\n\nArmi. Ogni genere di armi. Ma queste sono tutte prenotate.\n\nTorna tra qualche giorno, quando mi arriverà il nuovo... carico.', '', 28153),
(158479, 'itIT', 'Ti abbatterò, feccia dell\'Orda!', '', 28153),
(158478, 'itIT', 'L\'Alleanza non ha alcun diritto di rivendicazione sulle nostre terre!', 'L\'Alleanza non ha alcun diritto di rivendicazione sulle nostre terre!', 28153),
(158477, 'itIT', 'Qualunque cosa è meglio delle razioni di pane da viaggio.', '', 28153),
(158476, 'itIT', 'Tutte le nostre risorse stanno cercando di tenere l\'Orda a bada e far guadagnare tempo alla nostra gente in modo che possa fuggire. Cerca qualcosa da mangiare per le nostre sentinelle.', '', 28153),
(158475, 'itIT', '', 'Ti spedirò negli abissi del mare!', 28153),
(158474, 'itIT', 'Chello che tengo in tasca nun è nu mojo.', '', 28153),
(158473, 'itIT', 'Ti darò n\'assaggio della stessa medicina tua!', '', 28153),
(158472, 'itIT', 'Nun costringermi a trasformarti in nu brutto rospo!', '', 28153),
(158471, 'itIT', 'Sarà meglio che ti fermi. Sarò pure vecchio, ma chesto significa che so esattamente quali maledizioni usare.', '', 28153),
(158470, 'itIT', 'Sta\' calmo, cumpà. Nun serve continuare a toccarmi.', '', 28153),
(158469, 'itIT', 'Ho addestrato i Troll Lanciascura per generazioni.', '', 28153),
(158468, 'itIT', 'Buona fortuna, tieni sempre nu mojo a portata di mano.', '', 28153),
(158467, 'itIT', '', 'Qualunque cosa è meglio delle razioni da viaggio.', 28153),
(158466, 'itIT', '', 'Un\'armata si muove meglio a stomaco pieno, o almeno così mi è stato riferito. Ci deve pur essere qualcosa degno di essere mangiato in questa foresta.', 28153),
(158465, 'itIT', 'Ricorda che nun si può rigenerare tutto quanto.', '', 28153),
(158464, 'itIT', 'Attenzione!', '', 28153),
(158463, 'itIT', 'Ho quasi ricavato il campione che mi serve! Giusto un altro po\' di tempo...', '', 28153),
(158462, 'itIT', 'Mmm, queste foglie sono più tenaci di quanto pensassi... ma credo di star facendo progressi.', '', 28153),
(158461, 'itIT', 'Potrebbe volerci del tempo. Rimuovere le foglie è... un compito delicato.', '', 28153),
(158460, 'itIT', 'Ormai sono troppo vecchio per cheste cose.', '', 28153),
(158459, 'itIT', 'Che gli spiriti stiano con te.', '', 28153),
(158458, 'itIT', 'Ikum bokum.', '', 28153),
(158457, 'itIT', 'Qualcuno ha chiamato nu dottore?', '', 28153),
(158456, 'itIT', 'Tieni bisogno di aiuto?', '', 28153),
(158455, 'itIT', 'Salve, cumpà.', '', 28153),
(158454, 'itIT', 'Vorrei che gli spiriti mi guidassero.', 'Vorrei che gli spiriti mi guidassero.', 28153),
(158453, 'itIT', 'Gli spiriti possono guidarti in questo luogo.', '', 28153),
(158452, 'itIT', 'Una\'fe, $n! L\'avamposto è ai tuoi ordini.', '', 28153),
(158451, 'itIT', '', 'Li hai disarmati... per ora. Dobbiamo rimanere vigili fino a quando non avremo eliminato i loro fornitori.', 28153),
(158450, 'itIT', '', 'Riempiti la pancia e riposa un po\'!', 28153),
(158449, 'itIT', 'Il sigillo di questa sala protegge l\'anima del mondo, ma con tutta questa Azerite che fuoriesce, ormai sta per spezzarsi!', '', 28153),
(158448, 'itIT', 'Se userai il tuo amuleto per assorbire l\'Azerite, il suo potere dovrebbe riuscire a riparare il sigillo!', '', 28153),
(158447, 'itIT', '', 'Dicono che le bande siano entrate in possesso di alcuni potenti esplosivi d\'Azerite. Finché quegli armamenti non verranno recuperati, nessuno a Boralus sarà al sicuro.', 28153),
(158446, 'itIT', 'La mia barca è affondata e centinaia di uomini sono finiti in acqua. Gli squali sono arrivati dopo poco. Piccoli e grossi, ma tutti affamati. Li abbiamo affrontati al meglio delle nostre capacità. Quando li fissi in quegli occhi neri, ti sembra quasi che siano senza vita, fin quando non vengono a morderti. Poi l\'acqua si fa rossa, le cose si mettono male e in pochi secondi un marinaio finisce a pezzettini. Avrò perso metà equipaggio solo la prima notte. Ci saranno stati cento squali per ogni uomo. Alla fine sono arrivati i soccorsi, circa cinque giorni dopo, quando era ormai quasi troppo tardi. In trecentosedici sono morti annegati, sette si sono salvati... gli altri li hanno divorati gli squali.\n\nBasta con le chiacchiere, ti va di sfidare qualche squalo?', '', 28153),
(158445, 'itIT', 'Grazie. Ci proverò. Prestami gli stivali.', 'Grazie. Ci proverò. Prestami gli stivali.', 28153),
(158444, 'itIT', '', 'Ahia! Stavo solo cercando di spostare delle scatole che... uh... sono cadute giù dalla carovana.\n\nAlmeno Coda sta bene. Nulla può fargli del male!\n\nHo un secondo paio di stivali, se hai bisogno di tornare verso nord. Ti avverto... non li ho ancora provati.', 28153),
(158443, 'itIT', '', 'Siamo arrivati tardi.', 28153),
(158442, 'itIT', '', 'Controlla se questa gente ha bisogno di aiuto. Io vado avanti!', 28153),
(158441, 'itIT', '', 'Prima dobbiamo difendere i cancelli!', 28153),
(158440, 'itIT', '', 'Oh, no!', 28153),
(158439, 'itIT', '', 'Lo sappiamo. Ora riposa. Avrà quel che si merita.', 28153),
(158438, 'itIT', 'Harlan... Quel maledetto ci ha venduto ai Bracescura... È un... ARGH!', '', 28153),
(158437, 'itIT', 'Uhhh... dappertutto... <Tossisce>', '', 28153),
(158436, 'itIT', '', 'Flynn! Tutto a posto, sono io! Stai bene? Dove ti fa male?', 28153),
(158435, 'itIT', 'Ughh... ah... uooo... uoooOOOHHH!!!', '', 28153),
(158434, 'itIT', '', 'Molto bene. Vieni, madre. È ora di tornare a casa.', 28153),
(158433, 'itIT', '', 'Reggiti forte!', 28153),
(158432, 'itIT', 'Sono pronto a partire.', 'Sono pronta a partire.', 28153),
(158431, 'itIT', '', 'Posso teletrasportarci fuori di qui non appena sei $gpronto:pronta;, $C.\n\nTi prego, fai in fretta. Voglio andarmene da questo posto.', 28153),
(158430, 'itIT', 'CUTSCENE!', 'CUTSCENE!', 28153),
(158429, 'itIT', 'Gli Elfi della Notte sono degli ottimi vicini. Quei Fuochi Fatui invece... ci si mette un po\' ad abituarsi a loro.', '', 28153),
(158428, 'itIT', 'Sfruttare la terra, lavorare la terra. Era quello il nostro patto.', '', 28153),
(158427, 'itIT', 'Ciò che è successo al loro albero è una vergogna.', '', 28153),
(158426, 'itIT', 'Credi di poterci impedire di recuperare il corpo di Derek? Avrai ben altro di cui preoccuparti!', '', 28153),
(158425, 'itIT', 'Questa volta Loh deve semplicemente giungere all\'uscita, ma fa\' attenzione ai pericoli che si nascondono nel labirinto.', '', 28153),
(158424, 'itIT', 'Ora, riesci a guidare Loh a tutti i tesori e all\'uscita senza fargli incrociare il suo stesso percorso?', '', 28153),
(158423, 'itIT', 'Facile, no?', '', 28153),
(158422, 'itIT', 'Partiamo con una sfida semplice. Guida Loh fino all\'uscita.', '', 28153),
(158421, 'itIT', 'Durante queste storie, chiediamo ai giovani Tortolliani di guidare Loh attraverso piccoli labirinti per completare diverse sfide.', '', 28153),
(158420, 'itIT', 'Iniziamo l\'addestramento?', 'Iniziamo l\'addestramento?', 28153),
(158419, 'itIT', 'Facciamo del nostro meglio, $p!', 'Facciamo del nostro meglio, $p!', 28153),
(158418, 'itIT', 'Il successo iniziale di Loh portò a un grande senso di fiducia in se stesso, così egli continuò a cercare nuove fantastiche zone da esplorare.', '', 28153),
(158416, 'itIT', 'Riesci a guidare Loh a tutti i tesori e all\'uscita senza fargli incrociare il suo stesso percorso?', '', 28153),
(158415, 'itIT', 'Loh iniziò a esplorare le antiche rovine che incontrava, spesso scoprendo meravigliosi tesori.', '', 28153),
(158414, 'itIT', '\"Loh l\'Esploratore\". Più Loh cresceva, più diventava curioso del mondo.', '', 28153),
(158413, 'itIT', 'La sua diligenza ha portato i suoi frutti e la terra gli ha fornito molte cose nutrienti da mangiare.', '', 28153),
(158412, 'itIT', 'Puoi aiutare Loh a far visita a tutte le piantine del giardino una sola volta?', '', 28153),
(158411, 'itIT', 'Ogni mattina faceva visita a tutte le piante del suo giardino per controllare il loro stato.', '', 28153),
(158410, 'itIT', '', 'I Drust non hanno alcun interesse nel tenere in vita i loro prigionieri. Non possiamo permettere che Jaina subisca lo stesso destino.', 28153),
(158409, 'itIT', '\"Raccolto di Loh\". Loh adorava osservare le cose crescere.', '', 28153),
(158408, 'itIT', 'Loh riuscì a malapena a scappare, quindi decise di vivere una vita con meno avventure.', '', 28153),
(158407, 'itIT', 'Puoi aiutare Loh a spegnere le piastrelle illuminate per disattivare la trappola?', '', 28153),
(158406, 'itIT', '\"La curiosità dei Tortolliani\". La curiosità di Loh quasi gli costò la vita quando attivò un\'antica trappola Zandalari!', '', 28153),
(158405, 'itIT', '', 'Implora pietà!', 28153),
(158404, 'itIT', 'La vita della grande città non faceva per Loh. Decise così di tornare a un\'esistenza più semplice.', '', 28153),
(158403, 'itIT', 'Tuttavia, non faceva che perdersi. Riesci a guidare Loh a tutti i negozi e alla locanda senza fargli incrociare il suo stesso percorso?', '', 28153),
(158402, 'itIT', '\"La vita nella grande città\". Loh visitò una grande città una volta, una molto simile a Boralus.', '', 28153),
(158401, 'itIT', 'Loh andò a godersi una vita tranquilla e pacifica... con la pancia piena.', '', 28153),
(158399, 'itIT', '', 'Ho catturato alcuni elementali minori attorno a questi santuari. Sono piuttosto affascinanti. Ti va di vedere di cosa sono capaci?', 28153),
(158398, 'itIT', 'Ospiti scappano... $PR forte...', '', 28153),
(158397, 'itIT', 'Ho ancora fame...', '', 28153),
(158396, 'itIT', 'Dov\'è finita la luce?', '', 28153),
(158395, 'itIT', 'Addio, Gallywix...', '', 28153),
(158394, 'itIT', 'Niente violenza!', '', 28153),
(158393, 'itIT', 'Primo giorno di lavoro! Buona fortuna!', '', 28153),
(158392, 'itIT', 'Qui non possono entrare quelli come te!', '', 28153),
(158391, 'itIT', 'Una festa privata!', '', 28153),
(158390, 'itIT', 'Rimani comunque $gil secondo:la seconda; peggior cliente... della giornata...', 'Rimani comunque $gil secondo:la seconda; peggior cliente... della giornata...', 28153),
(158389, 'itIT', 'Un Goblin... con ghiaccio...', 'Un Goblin... con ghiaccio...', 28153),
(158388, 'itIT', 'Qualcuno vuole... altra Kaja\'cola...', 'Qualcuno vuole... altra Kaja\'cola...', 28153),
(158387, 'itIT', 'Spero tu abbia lasciato... una grossa mancia...', 'Spero tu abbia lasciato... una grossa mancia...', 28153),
(158386, 'itIT', 'Non ho mai imparato... a giocare... a golf...', 'Non ho mai imparato... a giocare... a golf...', 28153),
(158385, 'itIT', 'Tornatene a giocare... coi bambini...', 'Tornatene a giocare... coi bambini...', 28153),
(158384, 'itIT', 'Non seppellitemi con questa uniforme... è ridicola...', 'Non seppellitemi con questa uniforme... è ridicola...', 28153),
(158383, 'itIT', 'Io queste mazze non le porto più...', 'Io queste mazze non le porto più...', 28153),
(158382, 'itIT', 'Il Grande G... te la farà pagare per questo...', 'Il Grande G... te la farà pagare per questo...', 28153),
(158381, 'itIT', 'Aspetta, non ero ancora... alla parte divertente...', 'Aspetta, non ero ancora... alla parte divertente...', 28153),
(158380, 'itIT', 'Aspetta... Non ho ancora finito il tempo...', 'Aspetta... Non ho ancora finito il tempo...', 28153),
(158379, 'itIT', 'Dite a Gallywix di continuare... a pagarmi.', 'Dite a Gallywix di continuare... a pagarmi.', 28153),
(158378, 'itIT', 'Scommetto che non sei tipo da lasciare mance, $gspilorcio:spilorcia;.', 'Scommetto che non sei tipo da lasciare mance, $gspilorcio:spilorcia;.', 28153),
(158377, 'itIT', 'Non ti prenderai la mia Kaja\'cola!', 'Non ti prenderai la mia Kaja\'cola!', 28153),
(158376, 'itIT', 'Userò la tua milza per farci un martini... un milzini!', 'Userò la tua milza per farci un martini... un milzini!', 28153),
(158375, 'itIT', 'Sento qualcosa...', 'Sento qualcosa...', 28153),
(158374, 'itIT', 'Quei bicchieri ti stanno uscendo dalle tasche, $gamico:amica;!', 'Quei bicchieri ti stanno uscendo dalle tasche, $gamico:amica;!', 28153),
(158373, 'itIT', 'Che ne dici di una buca in uno... dei tuoi ginocchi!', 'Che ne dici di una buca in uno... dei tuoi ginocchi!', 28153),
(158372, 'itIT', '<Il dottore si rivolge a te con un sussurro.>$b$bSono feriti gravemente. Non possiamo muoverli, non nelle attuali condizioni. La cosa migliore da fare è rappezzare al meglio le loro ferite e andarcene.$b$bÈ follia pura là fuori...', 'n/a', 28153),
(158371, 'itIT', 'Qualsiasi cosa è meglio di guardare questi poveretti mancare il colpo tutto il giorno.', 'Qualsiasi cosa è meglio di guardare questi poveretti mancare il colpo tutto il giorno.', 28153),
(158370, 'itIT', 'In questi casi, raccomando un bel ferro nove sulla faccia!', 'In questi casi, raccomando un bel ferro nove sulla faccia!', 28153),
(158369, 'itIT', 'Finalmente è il mio turno di colpire qualcosa!', 'Finalmente è il mio turno di colpire qualcosa!', 28153),
(158368, 'itIT', 'Ahah! $gFregato:Fregata;! Sono un agente sotto copertura!', 'Ahah! $gFregato:Fregata;! Sono un agente sotto copertura!', 28153),
(158367, 'itIT', 'Niente paura, ci penso io.', 'Niente paura, ci penso io.', 28153),
(158366, 'itIT', 'State alla larga dagli ospiti!', 'State alla larga dagli ospiti!', 28153),
(158365, 'itIT', 'Non mi pagano abbastanza per questo.', 'Non mi pagano abbastanza per questo.', 28153),
(158364, 'itIT', 'Devo grigliare... un\'ultima... volta...', 'Devo grigliare... un\'ultima... volta...', 28153),
(158363, 'itIT', 'Lasciami al sole... e girami prima che bruci...', 'Lasciami al sole... e girami prima che bruci...', 28153),
(158362, 'itIT', 'Ah! E dicevano... che il sole mi avrebbe fatto male...', 'Ah! E dicevano... che il sole mi avrebbe fatto male...', 28153),
(158361, 'itIT', 'No... Il mio bellissimo corpo abbronzato...', 'No... Il mio bellissimo corpo abbronzato...', 28153),
(158360, 'itIT', 'Gallywix riceverà... le mie lamentele...', 'Gallywix riceverà... le mie lamentele...', 28153),
(158359, 'itIT', 'Volevo solo divertirmi...', 'Volevo solo divertirmi...', 28153),
(158358, 'itIT', 'Questo non è un piacere... e nemmeno un palazzo...', 'Questo non è un piacere... e nemmeno un palazzo...', 28153),
(158357, 'itIT', 'Tu non sai... chi sono io...', 'Tu non sai... chi sono io...', 28153),
(158356, 'itIT', 'Caddy, portami... alla buca.', 'Caddy, portami... alla buca.', 28153),
(158355, 'itIT', 'Almeno... muoio sotto il par.', 'Almeno... muoio sotto il par.', 28153),
(158354, 'itIT', 'Seppellitemi... nel banco di sabbia.', 'Seppellitemi... nel banco di sabbia.', 28153),
(158353, 'itIT', 'Di\' a mia moglie... che ero sotto il par.', 'Di\' a mio marito... che ero sotto il par.', 28153),
(158352, 'itIT', 'La migliore festa... della mia vita.', 'La migliore festa... della mia vita.', 28153),
(158351, 'itIT', 'La festa peggiore... della mia vita.', 'La festa peggiore... della mia vita.', 28153),
(158350, 'itIT', 'Voglio... un rimborso.', 'Voglio... un rimborso.', 28153),
(158349, 'itIT', 'Solo... un altro... bicchiere...', 'Solo... un altro... bicchiere...', 28153),
(158348, 'itIT', 'Siamo pieni. Vai a nuotare da qualche altra parte!', 'Siamo pieni. Vai a nuotare da qualche altra parte!', 28153),
(158347, 'itIT', 'Questa piscina non è aperta a quelli della tua razza!', 'Questa piscina non è aperta a quelli della tua razza!', 28153),
(158346, 'itIT', 'Hai visto che tuffo ho fatto prima? Era un dieci, come minimo!', 'Hai visto che tuffo ho fatto prima? Era un dieci, come minimo!', 28153),
(158345, 'itIT', 'Ehi, $PR. La tua brutta faccia sta bloccando il sole!', 'Ehi, $PR. La tua brutta faccia sta bloccando il sole!', 28153),
(158344, 'itIT', 'Il livello di sicurezza di Gallywix peggiora di giorno in giorno.', 'Il livello di sicurezza di Gallywix peggiora di giorno in giorno.', 28153),
(158343, 'itIT', 'Non ho pagato di più per essere infastidito da $gun lurido:una lurida; $PR!', 'Non ho pagato di più per essere infastidita da $gun lurido:una lurida; $PR!', 28153),
(158342, 'itIT', 'Vattene, $p. Vai a infastidire qualcun altro in piscina.', 'Vattene, $p. Vai a infastidire qualcun altro in piscina.', 28153),
(158341, 'itIT', 'Tienimi la Kaja\'cola. Ci penso io.', 'Tienimi la Kaja\'cola. Ci penso io.', 28153),
(158340, 'itIT', 'Allontanati dalla buca! Rovinerai l\'erba con quelle scarpe.', 'Allontanati dalla buca! Rovinerai l\'erba con quelle scarpe.', 28153),
(158339, 'itIT', 'Caddy, dammi il mio legno! Questo sarà un bel tiro lungo.', 'Caddy, dammi il mio legno! Questo sarà un bel tiro lungo.', 28153),
(158338, 'itIT', 'La mia prossima buca in uno la farò con il tuo bulbo oculare!', 'La mia prossima buca in uno la farò con il tuo bulbo oculare!', 28153),
(158337, 'itIT', 'Disturbi al campo di gioco! Datemi un tiro bonus!', 'Disturbi al campo di gioco! Datemi un tiro bonus!', 28153),
(158336, 'itIT', 'Vattene, $PR. Siamo occupati a bere, mangiare e bere ancora!', 'Vattene, $PR. Siamo occupati a bere, mangiare e bere ancora!', 28153),
(158335, 'itIT', 'Non dico mai di no a un po\' di divertimento in più.', 'Non dico mai di no a un po\' di divertimento in più.', 28153),
(158334, 'itIT', 'Sicurezza! Portate via questa seccatura!', 'Sicurezza! Portate via questa seccatura!', 28153),
(158333, 'itIT', 'Non avevo comprato il pacchetto scherzetti dell\'Alleanza!', 'Non avevo comprato il pacchetto scherzetti dell\'Alleanza!', 28153),
(158332, 'itIT', 'Ahia...', '', 28153),
(158331, 'itIT', 'Goblin... corri!', '', 28153),
(158330, 'itIT', 'Volevo solo... i luccicosi...', '', 28153),
(158329, 'itIT', 'Ho fatto del mio meglio...', '', 28153),
(158328, 'itIT', 'Scusa... Grande G...', '', 28153),
(158327, 'itIT', 'Lavorare, lavorare...', '', 28153),
(158326, 'itIT', 'Che sonno...', '', 28153),
(158325, 'itIT', 'Nulla ferma... l\'oro.', '', 28153),
(158324, 'itIT', 'Non toccare!', '', 28153),
(158323, 'itIT', 'Il nostro oro luccicoso!', '', 28153),
(158322, 'itIT', 'Il Grande G ha detto di schiacciare $PR.', '', 28153),
(158321, 'itIT', 'Vai via dai Goblin!', '', 28153),
(158320, 'itIT', 'Dammi l\'oro!', '', 28153),
(158319, 'itIT', 'Gallawick è il migliore!', '', 28153),
(158318, 'itIT', 'Niente pause!', '', 28153),
(158317, 'itIT', 'Niente ritardi!', '', 28153),
(158316, 'itIT', 'Si inchineranno davanti al Vuoto.', 'Si inchineranno davanti al Vuoto.', 28153),
(158315, 'itIT', 'Li ho visti attraverso il velo. Seguimi.', 'Li ho visti attraverso il velo. Seguimi.', 28153),
(158314, 'itIT', 'Venite qui, piccoli Goblin...', 'Venite qui, piccoli Goblin...', 28153),
(158313, 'itIT', '', 'Le nostre forze sono radunate ad Ar\'gorok. Raduna i tuoi alleati e prendi Stromgarde per l\'Orda!', 28153),
(158312, 'itIT', '<Unisciti all\'assalto di Lordaeron.>', '<Unisciti all\'assalto di Lordaeron.>', 28153),
(158311, 'itIT', 'Le sorprese continueranno fino al miglioramento del morale.', '', 28153),
(158310, 'itIT', 'Questa sarà una storia fantastica da raccontare agli amici.', '', 28153),
(158309, 'itIT', 'Preparare le telecamere in 3, 2, 1...', '', 28153),
(158308, 'itIT', 'Attivazione protocolli di divertimento.', '', 28153),
(158307, 'itIT', 'Richiesta di sorpresa ricevuta. Attivazione abbandono totale.', '', 28153),
(158306, 'itIT', 'Questa volta abbiamo esagerato con il livello massimo di divertimento.', '', 28153),
(158305, 'itIT', 'Gli ospiti noiosi non saranno tollerati.', '', 28153),
(158304, 'itIT', 'Carenza di divertimento rilevata. Correzione in corso.', '', 28153),
(158303, 'itIT', '', 'Lo dirò io quando la guerra sarà finita.', 28153),
(158302, 'itIT', 'Non importa.', 'Non importa.', 28153),
(158301, 'itIT', 'Sì.', 'Sì.', 28153),
(158300, 'itIT', '', 'Siamo a due passi da un importante luogo di raduno dell\'Orda e vuoi sapere perché ho una pozione che può renderti invisibile?', 28153),
(158299, 'itIT', 'Perché hai un Tonico dell\'Invisibilità?', 'Perché hai un Tonico dell\'Invisibilità?', 28153),
(158298, 'itIT', 'Shhh, vattene da accà. Mi farai saltare la copertura.', '', 28153),
(158297, 'itIT', 'Mandami sull\'ammiraglia.', 'Mandami sull\'ammiraglia.', 28153),
(158296, 'itIT', 'Se ti serve un passaggio per raggiungere quelle navi, sono quello che fa per te!', '', 28153),
(158295, 'itIT', 'Quel grosso albero ambulante è uno spettacolo!', '', 28153),
(158294, 'itIT', 'Pagherete per aver fatto Vog\'rish nervoso!', '', 28153),
(158293, 'itIT', 'Non è mai capitato a Vog\'rish prima!', '', 28153),
(158292, 'itIT', 'Argh! Vog\'rish imbarazzato!', '', 28153),
(158291, 'itIT', 'Gli Elfi sono veramente bravi nel far crescere le cose.', '', 28153),
(158290, 'itIT', 'Ora mostro vero potere di Vog\'rish!', '', 28153),
(158289, 'itIT', 'Preparate per inferno, insetti!', '', 28153),
(158288, 'itIT', 'Basta fare Ogre gentile!', '', 28153),
(158287, 'itIT', 'È bello avere un po\' d\'aiuto.', '', 28153),
(158286, 'itIT', '', 'Shandris... Devi... sopravvivere...', 28153),
(158285, 'itIT', '', 'Per... la mia... gente...', 28153),
(158284, 'itIT', 'Vog\'rish ti ha bruciato i piedi!', '', 28153),
(158283, 'itIT', 'La magia di Vog\'rish è fuori controllo!', '', 28153),
(158282, 'itIT', '', 'Unitevi a me nella morte!', 28153),
(158281, 'itIT', 'Ammirate un potere fantastico!', '', 28153),
(158280, 'itIT', 'Ah, tempismo perfetto.', '', 28153),
(158279, 'itIT', '', 'Pare che non dovrete aspettare a lungo, Nathanos.', 28153),
(158278, 'itIT', '', 'Sono così luccicanti! Direi che questa così grossa è stata benedetta dai Saggi delle Maree, mentre questa a spirale deve provenire dal tesoro di un pirata!', 28153),
(158277, 'itIT', '', 'Meno Fuochi Fatui a infastidire i nostri soldati. Ben fatto.', 28153),
(158276, 'itIT', '', 'Quest\'area deve essere liberata per garantire un passaggio sicuro alle nostre truppe. Non sottovalutare i Fuochi Fatui, sono letali in grande numero.', 28153),
(158275, 'itIT', '', 'Non crederesti mai alla stranissima roba che puoi tirar su pescando in questa zona. Ho catturato delle creature molto esotiche negli ultimi giorni, ti va di affrontarle?', 28153),
(158274, 'itIT', 'Lilian continua a dirmi che l\'Orda è come una famiglia.\n\nOra che la mia vera famiglia non vuole più accettarmi... onestamente, mi farebbe comodo il suo supporto.\n\nIn cambio, Lilian ha promesso che la mia famiglia sarebbe rimasta al sicuro... E se potessi assicurarmene dando il mio aiuto all\'Orda?\n\nÈ questo che farò.', '', 28153),
(158273, 'itIT', '', 'Noi ce ne andiamo da accà!', 28153),
(158272, 'itIT', '', 'Ostriche in vendita! Le migliori di tutta Kul Tiras. Ma che dico, le migliori di tutta Azeroth!', 28153),
(158271, 'itIT', '', 'Sto cominciando a capire, $n.\n\nCon l\'aiuto di Lilian, forse potrei accettare questo nuovo destino.\n\nDevo dire però... più sto alla larga da Kul Tiras, meglio è.', 28153),
(158270, 'itIT', 'Sono grato di questa opportunità di dimostrare il valore dei Ren\'dorei per la nostra causa.\n\nFaremo tutto il possibile per assicurare il successo dell\'Alleanza.', '', 28153),
(158269, 'itIT', '', 'Finora, sono rimasta molto impressionata dal Gran Comandante Sventradraghi.\n\nSfrutta un gran repertorio di tattiche e si adatta facilmente al variare delle circostanze usando strategie appropriate e necessarie.\n\nGli sforzi bellici dell\'Alleanza sono in buone mani. Proprio come te, anche io sono orgogliosa di poterne prendere parte.', 28153),
(158268, 'itIT', '', 'I San\'layn devono essere sterminati. L\'avventatezza dell\'Orda ci mette tutti in pericolo.', 28153),
(158267, 'itIT', 'Presto lo vedrai. Fuoco! Sì, grosso fuoco!', '', 28153),
(158266, 'itIT', 'Ti richiamerò quando ci sarà bisogno di te. Per l\'Alleanza.', '', 28153),
(158265, 'itIT', 'Re Anduin dev\'esserne informato subito. Il nostro compito qui è finito, ma la missione è appena iniziata.', '', 28153),
(158264, 'itIT', 'L\'Orda sta davvero reclutando quegli Elfi vampiri? Come sono caduti in basso.', '', 28153),
(158263, 'itIT', 'Tutto fumo, tutto arrosto!', '', 28153),
(158262, 'itIT', 'Ciò che descrivi sembra essere uno dei San\'layn... un Principe del Sangue.', '', 28153),
(158261, 'itIT', '', 'Guzzy è morto?', 28153),
(158260, 'itIT', 'Dove ci sta fumo, ci sta fuoco... fidati!', '', 28153),
(158259, 'itIT', 'È ora di muoversi verso la prossima fase del nostro piano.', '', 28153),
(158258, 'itIT', 'Abbiamo il corpo di Derek Marefiero. Non abbiamo bisogno di rianimare altri Kul Tirani, per ora.', '', 28153),
(158257, 'itIT', 'Speriamo che i tuoi sforzi non siano stati vani.', '', 28153),
(158256, 'itIT', 'La guerra è giunta a Rivafosca e dobbiamo proteggere la nostra gente con ogni mezzo. Manda ogni Fuoco Fatuo che trovi al fronte ed elimina qualsiasi minaccia.', '', 28153),
(158255, 'itIT', '', 'Ah! Ho sentito le urla di $gnu traditore:na traditrice;!', 28153),
(158254, 'itIT', '', 'Riposo per li stanchi, cibo per li affamati.', 28153),
(158253, 'itIT', '', 'Non avevo acconsentito ad attirare la flotta di Kul Tiras nel mio porto.\n\nSarà meglio che abbiate un piano adatto, mi rifiuto di perdere le mie libertà.', 28153),
(158252, 'itIT', 'Inizia il rituale.', 'Inizia il rituale.', 28153),
(158251, 'itIT', 'Da dove vieni?', 'Da dove vieni?', 28153),
(158250, 'itIT', 'Da quanto tempo eri qui?', 'Da quanto tempo eri qui?', 28153),
(158249, 'itIT', 'Questa è l\'unica casa che io abbia mai conosciuto.\n\nNoi andiamo dove le sabbie ci portano.', 'Questa è l\'unica casa che io abbia mai conosciuto.\n\nNoi andiamo dove le sabbie ci portano.', 28153),
(158248, 'itIT', 'La mia carovana chiama queste sabbie la propria casa da ben prima che io nascessi.\n\nCe ne sono altre dall\'altra parte del mare, ma non le ho mai viste con i miei occhi.', 'La mia carovana chiama queste sabbie la propria casa da ben prima che io nascessi.\n\nCe ne sono altre dall\'altra parte del mare, ma non le ho mai viste con i miei occhi.', 28153),
(158247, 'itIT', 'Stupidaggini. Tu e la tua gente avete fatto un ottimo lavoro, Magistro. Siete una grande risorsa per l\'Alleanza.', '', 28153),
(158246, 'itIT', 'A nome degli Elfi del Vuoto, chiedo perdono per il nostro fallimento.', '', 28153),
(158245, 'itIT', '', 'Dobbiamo raggiungere il Colle Vigile. Presto, salta su!', 28153),
(158244, 'itIT', '<Kua\'fon stride di felicità e si raggomitola per un sonnellino.>', '', 28153),
(158243, 'itIT', 'L\'abitante si contorce di dolore.', 'L\'abitante si contorce di dolore.', 28153),
(158242, 'itIT', 'Mok\'rah, $n! L\'avamposto è ai tuoi ordini.', '', 28153),
(158241, 'itIT', '', 'Mpf.', 28153),
(158240, 'itIT', 'Ti ripagheremo adeguatamente per il disturbo.', '', 28153),
(158239, 'itIT', '', 'Nathanos, avevo permesso alla tua Orda di usare il mio porto come base, non di guidare la flotta dei Marefiero direttamente alla mia porta!', 28153),
(158238, 'itIT', 'Lo scettro è un manufatto che possiede un immenso potere sul mare. Potremmo usarlo per ottenere un vantaggio notevole sulla flotta di Kul Tiras.', '', 28153),
(158237, 'itIT', '', 'Come intendi intrufolarti lì dentro? Non puoi certo passare dal cancello principale...', 28153),
(158236, 'itIT', 'Ho mandato Valentine a Boralus per consegnare un messaggio a Dama Marefiero, a qualsiasi costo: abbiamo tuo figlio.', '', 28153),
(158235, 'itIT', 'Calmatevi, amici miei. Vi assicuro che questo pirata pagherà per i suoi crimini. Ciò nonostante, dobbiamo aspettare che la corte pronunci la sua sentenza.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(158234, 'itIT', 'La nostra missione qui è recuperare lo Scettro Abissale, che si trova all\'interno del Monastero dei Sacraonda, a Boralus.', '', 28153),
(158233, 'itIT', '', 'Vieni dentro, $n. Nathanos ti aggiornerà sulla situazione.', 28153),
(158232, 'itIT', 'Per aver commesso il crimine di usura, la corte ti giudica colpevole. I tuoi metodi predatori hanno privato i bravi cittadini di Presidio della Pesca dei loro risparmi. Molti di loro ora sono per strada a causa delle tue azioni.', '', 28153),
(158231, 'itIT', 'Per aver commesso crimini di pirateria, rapina e assassinio, la corte ti giudica colpevole. La pirateria è uno dei crimini più vili secondo la legge di Kul Tiras, per questo sarai consegnato alla giustizia.', '', 28153),
(158230, 'itIT', 'Estorsione e crimine organizzato! Molte delle famiglie presenti qui oggi sono rimaste vittime dei tuoi affari loschi. Hai chiesto alla brava gente di Kul Tiras un prezzo troppo alto da pagare e ora sarai tu a pagarlo per loro.', '', 28153),
(158229, 'itIT', 'Seguimi. Ci porterò direttamente da Alleria e dal Gran Comandante.', '', 28153),
(158228, 'itIT', 'Questa non è la vittoria totale che speravo di ottenere per l\'Alleanza, ma non intendo aggiungere il ritardo alla mia lista di fallimenti.', '', 28153),
(158227, 'itIT', 'Abbiamo dato la caccia a un\'esca di Gallywix per tutto il tempo? I Goblin sono davvero i peggiori.', '', 28153),
(158226, 'itIT', 'Ci vediamo, perdenti!', '', 28153),
(158225, 'itIT', 'Quegli esoscheletri non costano poco, $p. Ti manderò il conto delle riparazioni!', '', 28153),
(158224, 'itIT', 'Siete caduti nel trucco più vecchio degli Acqualorda: lavoratori sottopagati di alto livello!', '', 28153),
(158223, 'itIT', 'Ah! Quanto vorrei che vedeste le vostre facce in questo momento.', '', 28153),
(158222, 'itIT', '', 'L\'idea che un qualsiasi spirito possa sfuggire da Bwonsamdi è incredibile. Speriamo che i legami con li amici suoi bastino ad aprirci nu canale di collegamento con lui nell\'Aldilà.', 28153),
(158221, 'itIT', '$n, c\'è un telescopio sul lato occidentale dell\'accampamento. Perché non vai a cercarlo?', '', 28153),
(158220, 'itIT', 'Mmm... già, dov\'è Guzbert? Dovrebbe comparire da dietro quell\'angolo da un momento all\'altro.', '', 28153),
(158219, 'itIT', '', 'Sono la prima a essere tornata? Dov\'è Guzzy?', 28153),
(158218, 'itIT', 'Bentornata, Signora Ferfavilla.', '', 28153),
(158217, 'itIT', '', 'Ehi, capo! Hai sentito quel botto? Credo di aver lanciato un Goblin in orbita.', 28153),
(158216, 'itIT', 'Guzbert e Kelsey dovrebbero essere qui da un momento all\'altro.', '', 28153),
(158215, 'itIT', 'E cos\'avrebbe fatto il mondo per me?', '', 28153),
(158214, 'itIT', 'Il tuo ego è gonfio come la tua pancia. Pensa al bene che avresti potuto fare per il mondo!', '', 28153),
(158213, 'itIT', 'Con tutte le ricchezze che hai accumulato, questo è tutto quello che sei riuscito a costruire, Gallywix? Un nido di depravazione?', '', 28153),
(158212, 'itIT', '', 'Usa Vivificazione per ripristinare la salute al massimo.', 28153),
(158211, 'itIT', 'Usa Vivificazione per ripristinare la salute al massimo.', '', 28153),
(158210, 'itIT', '', 'Subire danni fa parte della battaglia, ma puoi attingere alle nebbie spirituali per curare te o un alleato. Usa Vivificazione per guarire le tue ferite.', 28153),
(158209, 'itIT', 'Subire danni fa parte della battaglia, ma puoi attingere alle nebbie spirituali per curare te o un alleato. Usa Vivificazione per guarire le tue ferite.', '', 28153),
(158208, 'itIT', 'L\'Alleanza è stata sconfitta!', '', 28153),
(158207, 'itIT', '|A:Warfront-HordeWave3:25:23:0:0|a Una forza d\'assalto dell\'Orda è stata schierata!', '|A:Warfront-HordeWave3:25:23:0:0|a Una forza d\'assalto dell\'Orda è stata schierata!', 28153),
(158206, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è andato perso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è andato perso!', 28153),
(158205, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è andata persa!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è andata persa!', 28153),
(158204, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è andato perso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è andato perso!', 28153),
(158203, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è andato perso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è andato perso!', 28153),
(158202, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è andato perso!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è andato perso!', 28153),
(158201, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a La Vena Mineraria di Galson è andata persa!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a La Vena Mineraria di Galson è andata persa!', 28153),
(158200, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a La Segheria delle Alture è andata persa!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a La Segheria delle Alture è andata persa!', 28153),
(158199, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a La Vena Mineraria di Galson è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a La Vena Mineraria di Galson è sotto attacco!', 28153),
(158198, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a La Segheria delle Alture è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a La Segheria delle Alture è sotto attacco!', 28153),
(158197, 'itIT', '|A:Warfronts-BaseMapIcons-Alliance-MainHall-Minimap:25:23:0:0|a Il vostro comandante è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il vostro comandante è sotto attacco!', 28153),
(158196, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è sotto attacco!', 28153),
(158195, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è sotto attacco!', 28153),
(158194, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è sotto attacco!', 28153),
(158193, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è sotto attacco!', 28153),
(158192, 'itIT', 'Premere il grosso pulsante rosso appena me lo dici. Capito.', 'Premere il grosso pulsante rosso appena me lo dici. Capito.', 28153),
(158191, 'itIT', 'Mostrami dove posso volare.', 'Mostrami dove posso volare.', 28153),
(158190, 'itIT', 'Vuoi volare da qualche parte?', '', 28153),
(158189, 'itIT', 'Hanno superato ancora la nostra offerta! Perché la gente cerca di approfittarsi della miseria altrui?', 'Hanno superato ancora la nostra offerta! Perché la gente cerca di approfittarsi della miseria altrui?', 28153),
(158188, 'itIT', 'Non è rimasto nulla di valore da vendere.', 'Non è rimasto nulla di valore da vendere.', 28153),
(158187, 'itIT', 'Speriamo sia rimasto qualcosa che ci permetta di comprare le risorse di cui abbiamo bisogno.', 'Speriamo sia rimasto qualcosa che ci permetta di comprare le risorse di cui abbiamo bisogno.', 28153),
(158186, 'itIT', 'Quanto oro ci è rimasto?', 'Quanto oro ci è rimasto?', 28153),
(158185, 'itIT', 'Non ci sono abbastanza razioni...', 'Non ci sono abbastanza razioni...', 28153),
(158183, 'itIT', 'Tieni gli occhi sulla strada. Qualcosa di strano si nasconde tra le ombre di Drustvar.', 'Tieni gli occhi sulla strada. Qualcosa di strano si nasconde tra le ombre di Drustvar.', 28153),
(158182, 'itIT', 'Ehi... ehi... L\'esoscheletro non funziona!', '', 28153),
(158181, 'itIT', 'I corvi stanno osservando! Le risate non si fermano! Verranno per me!', '', 28153),
(158180, 'itIT', '', 'Mi hai fatto... rovesciare... da bere...', 28153),
(158179, 'itIT', '', 'Credi di riuscire a farmela, eh? Te la... Hic!... faccio vedere io!', 28153),
(158178, 'itIT', '', 'Ottimo lavoro. Ci vediamo dall\'altra parte dell\'accampamento.', 28153),
(158177, 'itIT', 'Guarda questo, Gallywix!', 'Guarda questo, Gallywix!', 28153),
(158176, 'itIT', 'Alleanza? Qui a Zandalar?', '', 28153),
(158175, 'itIT', 'Noi ci muoviamo con le sabbie.', 'Noi ci muoviamo con le sabbie.', 28153),
(158174, 'itIT', 'Le dune sono colme di tesori che aspettano solo di essere trovati.', 'Le dune sono colme di tesori che aspettano solo di essere trovati.', 28153),
(158173, 'itIT', 'La carovana è la nostra vera casa.', 'La carovana è la nostra vera casa.', 28153),
(158171, 'itIT', '|TInterface\\Icons\\INV_Mace_2H_CapturedTitanConstruct_D_01:20|t %s ti prende di mira con la |cFFFF0000|Hspell:271296|h[Mazza Ferrata Sanguinante]|h|r!', '', 28153),
(158170, 'itIT', '', 'Povere anime... Nessuno dovrebbe subire tutto questo. Una volta salvata Jaina, dobbiamo trovare un modo per aiutarle.', 28153),
(158169, 'itIT', 'Una cosa è certa, Drustvar è impazzita del tutto.', 'Una cosa è certa, Drustvar è impazzita del tutto.', 28153),
(158168, 'itIT', 'Ho sentito uno di loro parlare di un cervo affamato di carne umana.', 'Ho sentito uno di loro parlare di un cervo affamato di carne umana.', 28153),
(158167, 'itIT', 'Intendi quelli che parlavano degli uomini bestia e dei demoni di legno? Sì, li ho sentiti discutere a riguardo.', 'Intendi quelli che parlavano degli uomini bestia e dei demoni di legno? Sì, li ho sentiti discutere a riguardo.', 28153),
(158166, 'itIT', 'Hai sentito cosa stavano dicendo? Perché quei rifugiati sono qui?', 'Hai sentito cosa stavano dicendo? Perché quei rifugiati sono qui?', 28153),
(158165, 'itIT', 'A volte mi capita di pensare di poter emettere ronzii con la bocca e comunicare con le mie api, ma probabilmente non funzionerà mai finché non avrò finito il mio costume da ape integrale. A parte questo, le mie api sono le migliori della zona. Ti va di sfidarle o pensi di svolazzartene via?', '', 28153),
(158164, 'itIT', '', 'Possa la nostra volontà essere più forte delle loro macchine.', 28153),
(158163, 'itIT', 'Le tue gesta non saranno dimenticate dai Kaldorei. Il tuo aiuto in questi tempi oscuri potrebbe fare la differenza.', '', 28153),
(158162, 'itIT', 'Anche se dobbiamo affrontare una dura prova, non disperare: la dea ci ha donato la forza e noi dobbiamo aggrapparci a essa.', '', 28153),
(158161, 'itIT', 'Le sorti di una guerra non dipendono da una singola battaglia. Il nostro giorno arriverà.', '', 28153),
(158160, 'itIT', 'Re Anduin invierà i suoi soldati ad aiutarci. Dobbiamo mantenere la posizione fino al loro arrivo.', '', 28153),
(158159, 'itIT', 'La nostra flotta è tornata da Silitus. Sia lodata Elune! La loro forza ci farà sicuramente comodo.', '', 28153),
(158158, 'itIT', 'Sebbene il muro di Fuochi Fatui resista, l\'Orda continua ad assediare Rivafosca.', '', 28153),
(158157, 'itIT', 'Questo ha intaccato il loro morale. Mai sottovalutare il valore della pressione psicologica.', '', 28153),
(158156, 'itIT', 'Parole dure quelle che hai detto a Nathanos.', 'Parole dure quelle che hai detto a Nathanos.', 28153),
(158155, 'itIT', 'I Pirati del Covo della Libertà diventano ogni giorno più audaci. Dobbiamo seminare il caos tra i loro ranghi. Usa una delle loro stesse cavalcature per umiliarli dal cielo.', '', 28153),
(158154, 'itIT', '', 'Tutti i marinai temono il richiamo delle sirene, ma alcuni nun lo temono abbastanza.', 28153),
(158153, 'itIT', '', 'Le sirene si sono pigliate n\'altra nave di Kul Tiras. Cerca nel relitto qualsiasi cosa che potrebbe esserci utile... ma cerca di nun fare la stessa fine della ciurma!', 28153),
(158152, 'itIT', 'Vi attende un destino peggiore della morte...', '', 28153),
(158151, 'itIT', 'Credete di aver vinto?!? La mia caduta è solo l\'inizio della vostra fine!', '', 28153),
(158150, 'itIT', 'Ben fatto. I nostri nemici non avranno l\'equipaggiamento per sconfiggerci.', '', 28153),
(158149, 'itIT', 'Non dobbiamo permettere ai Kul Tirani di produrre delle altre munizioni d\'Azerite. Ferma la produzione alla fonderia!', '', 28153),
(158148, 'itIT', '', 'Quando dei fanatici iniziano a mettere in dubbio la tua lealtà, non si è destinati a durare molto.\n\nMi sono arruolata per partecipare a questa campagna. Forse lo stesso vale per te. Dobbiamo fare tutto il possibile per sopravvivere.\n\nMa sappi questo: c\'è solo una guerra che conta, e non è questa.', 28153),
(158147, 'itIT', 'Condividerete... il suo... destino...', '', 28153),
(158146, 'itIT', 'È troppo... tardi... per salvarla...', '', 28153),
(158145, 'itIT', 'Il tormento... Attende... tutti voi...', '', 28153),
(158144, 'itIT', 'È già... condannata...', '', 28153),
(158143, 'itIT', 'La vendetta è a portata di mano!', '', 28153),
(158142, 'itIT', 'Marefiero è nostra!', '', 28153),
(158141, 'itIT', 'Anche voi sarete consumati!', '', 28153),
(158140, 'itIT', 'Vi unirete alla sua sofferenza!', '', 28153),
(158139, 'itIT', '', 'Lavoro in questo campo abbastanza a lungo da aver trovato alcune interessanti manifestazioni di quell\'Azerite. Ti va di sfidare la fortuna contro alcuni Elementali d\'Azerite che ho preso con le mie mani?', 28153),
(158138, 'itIT', 'STOLTI! Non potete sperare di comprendere i poteri con cui state giocando!', '', 28153),
(158137, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è sotto attacco!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è sotto attacco!', 28153),
(158136, 'itIT', '', 'Non esattamente. Quando si vede un\'opportunità, bisogna coglierla.\n\nHo sempre avuto piani per il mio futuro, era ora che facessi qualcosa per renderli realtà.', 28153),
(158135, 'itIT', 'Credevo servissi i Senza Corona. Hai cambiato idea?', 'Credevo servissi i Senza Corona. Hai cambiato idea?', 28153),
(158134, 'itIT', 'Sono libero! Grazie... Ora le vostre anime sazieranno la mia fame!!!', '', 28153),
(158133, 'itIT', 'Decidi tu quale regione colpire per prima. Quando avrai scelto, salperemo immediatamente.', '', 28153),
(158132, 'itIT', '', 'Bel lavoro. Le guardie possono occuparsi di quelli rimasti. Noi dobbiamo tenere d\'occhio il maniero.', 28153),
(158131, 'itIT', '', 'Degli abomini hanno iniziato a fuoriuscire dal Maniero dei Crestabianca! Dobbiamo fermarli, prima che raggiungano il Presidio di Arom!', 28153),
(158129, 'itIT', 'Noi vinceremo questa guerra. Per l\'Alleanza!', '', 28153),
(158128, 'itIT', 'Cerca dei bersagli nelle terre dei Troll. Mina gli sforzi della Capoguerra a ogni occasione.', '', 28153),
(158127, 'itIT', 'Stabilire degli accampamenti a Zandalar è stato un buon primo passo. Ora li useremo per sferrare l\'attacco all\'Orda!', '', 28153),
(158126, 'itIT', 'La guerra ha effetti imprevedibili. È ora di concentrarsi su nuovi obiettivi con la nostra campagna.', '', 28153),
(158125, 'itIT', 'Non mi sono mai sentito... così affamato...', 'Non mi sono mai sentita... così affamata...', 28153),
(158124, 'itIT', 'I tuoi sforzi a Kul Tiras sono stati vitali per la nostra causa. Solo attraverso l\'unità l\'Alleanza diventerà più forte.', '', 28153),
(158123, 'itIT', 'Per l\'Alleanza!', '', 28153),
(158122, 'itIT', 'Per ora, sappi che sei di grande ispirazione per tutti coloro che ti circondano. E per questo hai i miei ringraziamenti.', '', 28153),
(158121, 'itIT', 'L\'Alleanza ha ancora bisogno di te. È chiaro che non possiamo sperare di porre fine al regno della Capoguerra senza recidere i suoi legami con gli Zandalari. Quel giorno arriverà... molto presto.', '', 28153),
(158120, 'itIT', 'Vorrei poterti dire che il tuo lavoro è finito, ma c\'è ancora molto da fare. Temo che i giorni che verranno saranno sempre più bui... prima che possano tornare a risplendere.', '', 28153),
(158119, 'itIT', 'Hai guidato in prima linea una lunga campagna contro uno spietato nemico. E come se non bastasse, hai affrontato l\'Orda con coraggio... e onore.', '', 28153),
(158118, 'itIT', '', 'Per l\'Orda!', 28153),
(158117, 'itIT', '', 'Tu incarni le qualità migliori dell\'Orda. Sarai tu la scintilla che manderà in fiamme Boralus.', 28153),
(158116, 'itIT', '', 'Kul Tiras è diventato un punto di raduno per l\'Alleanza. Il ritorno della loro famosa flotta li ha rinvigoriti, ma presto quei cani pagheranno per la loro insolenza.', 28153),
(158115, 'itIT', '', 'Anche se la vittoria ci elude, si fa sempre più vicina. Non dobbiamo fermarci finché anche l\'ultimo briciolo di speranza nel cuore del Re moccioso sarà diventato cenere.', 28153),
(158114, 'itIT', '', 'Il mondo è pieno di soldati, ma pochi sono davvero portati per la guerra. Sembra che tu... abbia questo dono.', 28153),
(158113, 'itIT', '', 'Togli loro la loro speranza e otterrai la vittoria. Per l\'Orda!', 28153),
(158112, 'itIT', '', 'Usa gli avamposti di Kul Tiras per indebolire le forze del Re moccioso. Fa\' vacillare la loro fede.', 28153),
(158111, 'itIT', '', 'Ma per vincere non basterà rinforzare i nostri ranghi. Dovremo mutilare i nostri nemici fino a che non strisceranno davanti a noi.', 28153),
(158110, 'itIT', '', 'Sapevo che nessuno meglio di te poteva convincere gli Zandalari a unirsi alla nostra causa.', 28153),
(158109, 'itIT', '', 'Quando la Principessa Talanji è venuta in cerca d\'aiuto, ho capito subito che sarebbe stato possibile avvalersi della potenza del suo regno.', 28153),
(158108, 'itIT', 'La terra stessa è schiattata accà. Chesto è terribile, cumpà. Terribile assai.', '', 28153),
(158107, 'itIT', '', 'Scaldati le mani e riposa le ossa, $C.', 28153),
(158106, 'itIT', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s inizia a lanciare |cFFFF0000|Hspell:273361|h[Pozza delle Tenebre]|h|r!', '|TInterface\\ICONS\\INV_Misc_Food_Legion_gooAmberPink_pool.BLP:20|t %s inizia a lanciare |cFFFF0000|Hspell:273361|h[Pozza delle Tenebre]|h|r!', 28153),
(158105, 'itIT', '$gBenvenuto:Benvenuta; all\'Avamposto degli Arialesta, $n. Attendiamo i tuoi ordini.', '', 28153),
(158104, 'itIT', 'Avrei dovuto... fare... l\'assicurazione...', '', 28153),
(158103, 'itIT', 'Ti do il benvenuto nel Palazzo del DOLORE di Gallywix, $gdannato ladro:dannata ladra;!', '', 28153),
(158102, 'itIT', 'Chiedi a Fozruk di attaccare Ar\'gorok.', 'Chiedi a Fozruk di attaccare Ar\'gorok.', 28153),
(158101, 'itIT', 'La corruzione si sta diffondendo più velocemente di quanto immaginassi...', '', 28153),
(158100, 'itIT', 'Queste spore non sono naturali. Dobbiamo scoprire da dove arrivano.', '', 28153),
(158099, 'itIT', 'Abbiamo fatto il possibile. Possano trovare pace nella prossima vita.', '', 28153),
(158098, 'itIT', 'Gli spiriti si fanno inquieti. Dobbiamo porre fine al loro tormento.', '', 28153),
(158097, 'itIT', '', 'Ben fatto. Possano finalmente riposare.', 28153),
(158096, 'itIT', '', 'Li spiriti sono inquieti. Aiutali a trovare la pace.', 28153),
(158095, 'itIT', '', 'Con cheste spore, possiamo trovare la fonte del marciume e distruggerla.', 28153),
(158094, 'itIT', '', 'Il marciume si sta diffondendo in fretta. Dobbiamo fermarlo. Recupera delle spore, così potremo scoprire di più.', 28153),
(158093, 'itIT', 'Fratelli e sorelle! L\'Orda continua a spingere verso l\'interno di Rivafosca! Raduniamoci al Fiume Lettocurvo.', '', 28153),
(158092, 'itIT', 'Sei stato infuso con il potere del vento!', 'Sei stata infusa con il potere del vento!', 28153),
(158091, 'itIT', 'Voglio che tutto quest\'oro sia portato immediatamente al palazzo, poi...', '', 28153),
(158090, 'itIT', 'Niente ritardi! Niente scuse! Niente promozioni!', '', 28153),
(158089, 'itIT', 'Fuori dai piedi! L\'Alleanza è qui!', '', 28153),
(158088, 'itIT', 'Non morirò... per mano di un Goblin.', '', 28153),
(158087, 'itIT', 'L\'Alleanza ha riposto la sua fiducia negli Elfi del Vuoto. Non la deluderemo.', '', 28153),
(158086, 'itIT', 'Gallywiiiiiix!', 'Gallywiiiiiix!', 28153),
(158085, 'itIT', 'Dannazione! È l\'Alleanza!', 'Dannazione! È l\'Alleanza!', 28153),
(158084, 'itIT', '', 'L\'Orda deve aver cacciato i Mezzorsi dalle loro tane.', 28153),
(158083, 'itIT', '', 'L\'Orda... Sono così tanti...', 28153),
(158082, 'itIT', 'Santi numi! Da dov\'è $gspuntato quell\'Elfo:spuntata quell\'Elfa;?!?', 'Santi numi! Da dov\'è $gspuntato quell\'Elfo:spuntata quell\'Elfa;?!?', 28153),
(158081, 'itIT', '', 'I Mezzorsi di solito sono pacifici. Venir cacciati dalla propria dimora deve averli fatti infuriare.', 28153),
(158078, 'itIT', '', 'Cammino nell\'ombra.', 28153),
(158077, 'itIT', '', 'Subito!', 28153),
(158076, 'itIT', '', 'Fai attenzione! Non devono sentirci!', 28153),
(158075, 'itIT', '', 'Uccidi il bersaglio velocemente, prima che allerti gli altri!', 28153),
(158074, 'itIT', '', 'Non facciamoci scoprire! Non dobbiamo attirare troppo l\'attenzione...', 28153),
(158073, 'itIT', 'Scendo subito, Lanfa!', '', 28153),
(158072, 'itIT', '', 'Dopo di te. Se desideri che tramortisca uno di loro, basta chiedere. Ma... a bassa voce.', 28153),
(158071, 'itIT', 'Harli ti porterà lì e tornerà da me. Io devo occuparmi dell\'amico mio!', '', 28153),
(158070, 'itIT', 'Gli hai dato na bella lezione. Vediamo se la impareranno.', '', 28153),
(158069, 'itIT', 'Chesta sottospecie di Nani nun riesce proprio a capire. Nun sono i benvenuti accà! Mostragli chello che fanno li Zandalari agli intrusi.', '', 28153),
(158068, 'itIT', 'Uccidete chiunque cerchi di salire su questo colle!', '', 28153),
(158067, 'itIT', 'Una volta smantellata la flotta, Zandalar sarà nostra!', '', 28153),
(158066, 'itIT', 'Alzate quei pilastri!', '', 28153),
(158065, 'itIT', '<Wait a moment while Genn convinces Katherine in a really awesome cutscene>', '<Wait a moment while Genn convinces Katherine in a really awesome cutscene>', 28153),
(158064, 'itIT', 'Il popolo di Kul Tiras è unito, ma la loro casata principale non lo è. L\'Alleanza si trova senza uno dei nostri comandanti più abili.\n\nSpero davvero che questa frattura venga sanata.', '', 28153),
(158063, 'itIT', 'Vediamoci al memoriale di famiglia presso il Forte dei Marefiero. Con un po\' di fortuna, riusciremo a convincere l\'Ammiraglio Supremo a revocare l\'esecuzione di sua figlia.', '', 28153),
(158062, 'itIT', 'Hai aiutato a unire i Kul Tirani, guadagnando il loro supporto per l\'Alleanza. Forse potresti riuscire a riunire anche una madre e sua figlia.', '', 28153),
(158061, 'itIT', 'Tagliare i rifornimenti dell\'Orda ne rallenterà l\'assalto. Ci hai fatto guadagnare del tempo.', '', 28153),
(158060, 'itIT', 'Quei Goblin stanno trivellando in cerca di carburante per le loro macchine. Poni fine alla loro profanazione!', '', 28153),
(158059, 'itIT', '', 'Il fuoco continua a bruciare e noi avanziamo.', 28153),
(158058, 'itIT', '', 'Quegli elementali faranno da carburante per i nostri Demolitori. Elimina loro e qualunque Kaldorei si ponga sulla tua strada.', 28153),
(158057, 'itIT', 'Possiamo attraversare il Vuoto per guadagnare tempo. Seguimi.', '', 28153),
(158056, 'itIT', 'Gallywix è astuto. Non rimarrà allo scoperto per molto.', '', 28153),
(158055, 'itIT', 'Avrei dovuto immaginare che un Goblin come Gallywix non sarebbe riuscito a resistere alla tentazione di saccheggiare una città fatta d\'oro.', '', 28153),
(158054, 'itIT', '', 'Ci hanno scoperti! Raccogli tutta l\'Azerite che puoi. Non possiamo rimanere qui ancora a lungo!', 28153),
(158053, 'itIT', '', 'Per la dea... Azerite! È ovunque!', 28153),
(158052, 'itIT', 'I nodi d\'Azerite spuntano fuori da tutte le parti.', 'I nodi d\'Azerite spuntano fuori da tutte le parti.', 28153),
(158051, 'itIT', '<Poggia la mano sul Giacimento d\'Azerite.>', '<Poggia la mano sul Giacimento d\'Azerite.>', 28153),
(158050, 'itIT', '<La vena d\'Azerite vibra di potere.>', '', 28153),
(158049, 'itIT', '', 'Tu occupati del Segatronchi. Io scaccerò gli invasori!', 28153),
(158048, 'itIT', 'Il Bosco degli Antichi! Oh cielo...', 'Il Bosco degli Antichi! Oh cielo...', 28153),
(158047, 'itIT', 'Ci penso io!', 'Ci penso io!', 28153),
(158046, 'itIT', 'Fai attenzione ai Mezzorsi. Ne sono comparsi improvvisamente una gran quantità.', 'Fai attenzione ai Mezzorsi. Ne sono comparsi improvvisamente una gran quantità.', 28153),
(158045, 'itIT', 'Mi metto subito a lavoro!', 'Mi metto subito a lavoro!', 28153),
(158044, 'itIT', 'I Mezzorsi sembrano stranamente aggressivi...', 'I Mezzorsi sembrano stranamente aggressivi...', 28153),
(158043, 'itIT', '|TInterface\\Icons\\INV_misc_boilingblood:20|t %s ti prende di mira con |cFFFF0000|Hspell:271224|h[Scarica di Plasma]|h|r!', '', 28153),
(158042, 'itIT', 'Non sottovalutare il valore delle tue azioni. Mentre si riprendono dalle sconfitte, noi possiamo rafforzare la nostra posizione in queste terre.', '', 28153),
(158041, 'itIT', 'L\'Orda vuole rafforzare la sua posizione qui. Impedisciglielo!', '', 28153),
(158040, 'itIT', '', 'Il branco sopravvive, ahahah! Hai agito bene.', 28153),
(158039, 'itIT', '', 'Ci sta nu gruppo di cuccioli piuttosto inusuale che tiene bisogno d\'aiuto. Va\' da loro e ottieni il favore di Gonk.', 28153),
(158038, 'itIT', 'Un gruppo armato in meno di cui preoccuparci. Ottimo lavoro.', '', 28153),
(158037, 'itIT', '', 'Zandalar per sempre!', 28153),
(158036, 'itIT', '', 'Se nun fosse stato per chesto campione dell\'Orda, le perdite nostre sarebbero state ancora maggiori.$bChesta è la prova del fatto che dobbiamo adattarci e tornare a far parte del mondo.', 28153),
(158035, 'itIT', '', 'Che chesta lama sia esposta e ci ricordi che nun importa come cadiamo o quanto perdiamo. Siamo Zandalari!$bCi adattiamo e troviamo sempre nu modo per sopravvivere!', 28153),
(158034, 'itIT', '', 'Egli ha causato le morti di innumerevoli fratelli e sorelle nostri.', 28153),
(158033, 'itIT', '', 'Ammirate il Sangue di G\'huun. Egli ha causato le morti di Shadra, Hir\'eek, Torga, e... e Rezan.', 28153),
(158032, 'itIT', 'Gli esploratori ci hanno riferito che c\'è una nave da guerra dell\'Orda vicina alla costa. Assicurati che i loro rinforzi non attracchino mai.', '', 28153),
(158031, 'itIT', '', 'Chest\'impresa nun è stata opera mia.', 28153),
(158030, 'itIT', 'Non possiamo dare nulla per scontato in questa terra. Grazie a te, i nostri esploratori sono salvi... almeno per oggi.', '', 28153),
(158029, 'itIT', 'Mostra loro la lama. Diventa il simbolo di cui tengono bisogno.', '', 28153),
(158028, 'itIT', 'Sei stata tu a cominciare ciò che serviva per salvare la gente tua. Ora più che mai, tengono bisogno di nu capo di cui fidarsi.', '', 28153),
(158027, 'itIT', 'Hai portato nu campione su cheste terre contro la volontà del padre tuo. Hai appreso i segreti di G\'huun quando nessuno ti ascoltava.', '', 28153),
(158026, 'itIT', 'Molti agenti dell\'IR:7 sono stati mandati in questa regione, ma non abbiamo ricevuto rapporti da loro. Occupati subito della causa di questo ritardo.', '', 28153),
(158025, 'itIT', 'Va\', capo degli Zandalari. Mostra la lama a coloro che ne hanno più bisogno. Donagli la pace.', '', 28153),
(158024, 'itIT', '', 'Vol\'jin, riesci a sentirci? Rivelati, spirito.', 28153),
(158023, 'itIT', 'L\'Orda pagherà col sangue per ogni metro di terra che cercherà di rivendicare. Anche le vittorie più piccole sono preziose. Ottimo lavoro.', '', 28153),
(158022, 'itIT', 'Perdite... perdite. Così tante perdite. Così tanti senza guida. Così tanti senza giustizia. G\'huun s\'è pigliato la speranza loro.', '', 28153),
(158021, 'itIT', 'L\'Orda pensa di poter operare incontrastata in quest\'area. Dimostra loro che si sbagliano.', '', 28153),
(158020, 'itIT', '', 'Silenzio!', 28153),
(158019, 'itIT', 'L\'ho sentito!', '', 28153),
(158018, 'itIT', 'Perdite...', '', 28153),
(158017, 'itIT', '', 'Vol\'jin, figlio di Sen\'jin, ascolta le voci degli amici e della famiglia tua. Si chiedono dove tu stia.', 28153),
(158016, 'itIT', 'Posizionamento Azerite', 'Posizionamento Azerite', 28153),
(158015, 'itIT', 'Devi difendere il Bosco degli Antichi!', 'Devi difendere il Bosco degli Antichi!', 28153),
(158014, 'itIT', 'Rimango vigile.', 'Rimango vigile.', 28153),
(158013, 'itIT', '<Aiutalo.>', '<Aiutalo.>', 28153),
(158012, 'itIT', 'Sarò onesto. Sono sceso anche più in basso di così.\n\nMa non di molto.', '', 28153),
(158011, 'itIT', '', 'Gli Antichi ci stanno chiamando! Cerca i Druidi dell\'Unghia nella foresta e incontriamoci al Bosco degli Antichi!', 28153),
(158009, 'itIT', '', 'Abbiamo guadagnato un po\' di tempo. Sentinelle, mantenete la posizione!', 28153),
(158008, 'itIT', '', 'Non ho mai visto nessuno così. Temo che il tuo amico sia caduto vittima del canto di una sirena.', 28153),
(158007, 'itIT', '<Chiedile se ha visto Flynn.>', '<Chiedile se ha visto Flynn.>', 28153),
(158006, 'itIT', 'Niente? Come non è rimasto niente? Voglio un rimborso!', 'Niente? Come non è rimasto niente? Voglio un rimborso!', 28153),
(158005, 'itIT', '', 'Non sei l\'unico ad aver richiesto fascicoli all\'IR:7.', 28153),
(158004, 'itIT', 'Come fa un generale degli Elfi pluridecorato a conoscere uno come me?', '', 28153),
(158003, 'itIT', '', 'Anche tu sei un eroe, Keeshan, grazie ai tuoi servigi nelle prime tre guerre e al valore che hai dimostrato a Crestarossa.', 28153),
(158002, 'itIT', 'Per quanto mi riguarda, sono appena degno di servire al tuo fianco. Il minimo che posso fare è mostrare un po\' di rispetto.', '', 28153),
(158001, 'itIT', 'Signora, ho letto il tuo fascicolo dell\'IR:7. Hai più di diecimila anni e hai combattuto in più guerre di quante io possa immaginare.', '', 28153),
(158000, 'itIT', '', 'Keeshan, puoi abbandonare quell\'aria marziale con me.', 28153),
(157999, 'itIT', 'Ha detto che dovrebbe essere là fuori a uccidere l\'Alleanza, invece di occuparsi di altre sciocchezze. Dopo quello ho capito che sarebbe stato meglio andarsene prima di barattare altre storie.', '', 28153),
(157998, 'itIT', 'Quest\'Areiel che state cercando è nella Necropoli, insieme a un bel numero di scagnozzi dell\'Orda! Sembrava molto preoccupata a causa di una lettera che ha ricevuto.', '', 28153),
(157997, 'itIT', 'Sarà divertente! Vi dirò cosa volete sapere e poi mi racconterete tutto sulle vostre esperienze in battaglia.', '', 28153),
(157996, 'itIT', '', 'Ho più di 10.000 anni e ho combattuto in ogni guerra. Ho visto il vero Pozzo dell\'Eternità con i miei occhi.', 28153),
(157995, 'itIT', 'Ho prestato servizio durante le prime tre guerre, ho vissuto prigioniero di un gruppo di Orchi selvaggi e ho aiutato a uccidere un Drago Nero.', '', 28153),
(157994, 'itIT', 'Una bella storia! Torga ne avrebbe raccontate di fantastiche, ma purtroppo ora è morto. Voi ne conoscete di belle?', '', 28153),
(157993, 'itIT', 'Ti abbiamo appena salvato la vita. Cos\'altro vuoi?', '', 28153),
(157992, 'itIT', 'Posso dirti tutto sull\'Orda. Mi serve solo un piccolo incentivo.', '', 28153),
(157991, 'itIT', 'Grazie, signora.', '', 28153),
(157990, 'itIT', '', 'Grazie per l\'aiuto, $n e Keeshan. Ora devo continuare a dare la caccia Dreven. Possa Elune illuminarvi il cammino.', 28153),
(157989, 'itIT', 'Vai! Io ti copro i fianchi!', '', 28153),
(157988, 'itIT', '', '$n, Keeshan, venite. Torniamo al Forte Vittoria... e diamo una degna sepoltura ai miei amici.', 28153),
(157987, 'itIT', '', 'Elfi, Umani, siamo tutti uguali, Keeshan. Nessuno di noi vale più degli altri.', 28153),
(157986, 'itIT', 'Sarò... come nuovo in un attimo... ma non avrei dovuto essere io. I tuoi amici meritavano di sopravvivere più di me.', '', 28153),
(157985, 'itIT', '', 'Keeshan! Sia lodata Elune, almeno qualcuno è sopravvissuto a questo massacro.', 28153),
(157984, 'itIT', '<Tossisce> Signora... sono vivo... per ora. Pare che il suo potere... non sia così grande... senza quei servitori.', '', 28153),
(157983, 'itIT', '', 'Falia... Lyrias... Aeolyn... Keeshan... Lo giuro, $n, Dreven la pagherà!', 28153),
(157982, 'itIT', 'Argh!', '', 28153),
(157981, 'itIT', 'Non mi arrenderò mai, Shandris Piumaluna. Osserva come sono fragili i tuoi alleati!', '', 28153),
(157980, 'itIT', 'Sarà meglio andarcene. Lascia che li spiriti trovino da soli la strada per Bwonsamdi.', '', 28153),
(157979, 'itIT', 'I Troll del Sangue torneranno, ne sono certo, ma ora sanno che possiamo colpirli nella terra loro. Ci penseranno due volte prima di attaccarci di nuovo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157978, 'itIT', '', 'Shandris, vai avanti... senza di me...', 28153),
(157977, 'itIT', 'Vado in avanscoperta per trovare nu posto sicuro dove radunarci. Incontriamoci fuori dal villaggio quando avrai finito.', '', 28153),
(157976, 'itIT', 'Accogli la morte insieme a me, Elfa della Notte!', '', 28153),
(157975, 'itIT', 'È ora di mostrarti cosa sa fare questo patetico Umano!', '', 28153),
(157974, 'itIT', '', 'Disattivate lo scudo, così potremo attaccare! Stromgarde sarà nostra!', 28153),
(157973, 'itIT', '', 'A tutti i cannoni, FUOCO!', 28153),
(157972, 'itIT', '', 'Sì?', 28153),
(157971, 'itIT', 'Di sicuro ci lasceranno andare a riprendere parte dei nostri averi. Una volta che il fumo si sarà diradato, ovviamente.', 'Di sicuro ci lasceranno andare a riprendere parte dei nostri averi. Una volta che il fumo si sarà diradato, ovviamente.', 28153),
(157970, 'itIT', 'Tutto ciò che avevamo era al Ramo degli Eterni!', 'Tutto ciò che avevamo era al Ramo degli Eterni!', 28153),
(157969, 'itIT', 'Ti pentirai di non essere arsa viva insieme a Darnassus!', '', 28153),
(157968, 'itIT', 'Shandris Piumaluna che tenta un\'imboscata? Quanto coraggio.', '', 28153),
(157967, 'itIT', 'Forse farò di questo patetico Umano un esempio per tutti.', '', 28153),
(157966, 'itIT', '', 'I tuoi assassinii finiscono oggi, Dreven.', 28153),
(157965, 'itIT', 'Quanti dei vostri devo ancora uccidere prima di farvi capire che dovete stare alla larga da noi?', '', 28153),
(157964, 'itIT', 'Alleanza. Sapevo che eravate troppo stupidi per imparare la lezione dal nostro ultimo incontro.', '', 28153),
(157963, 'itIT', 'Pare sia il momento di scremare un po\' i ragni buoni da quelli cattivi.', '', 28153),
(157962, 'itIT', 'Un tizio, tre ragni, ventisei gambe in totale. Non avevi speranze.', '', 28153),
(157961, 'itIT', 'Quando una cade, un\'altra prende il suo posto!', '', 28153),
(157960, 'itIT', 'Calma, piccolino. Ci aiuterai?', 'Calma, piccolino. Ci aiuterai?', 28153),
(157959, 'itIT', '<Flappy ti osserva con sospetto.> Flappy?', '', 28153),
(157958, 'itIT', 'Sì, proprio così. Siamo cattivi! A tutta birra!', '', 28153),
(157957, 'itIT', 'Sono pronto a uccidere Dreven e i suoi seguaci.', 'Sono pronta a uccidere Dreven e i suoi seguaci.', 28153),
(157956, 'itIT', 'Ehilà, mi chiamo Dilbert McClint, gestione infestazioni. È sempre bello sfidare un collega amante dei ragni.', '', 28153),
(157955, 'itIT', 'A quanto pare siamo un\'esca per un gruppo di Elfi vampiri assetati di sangue. $gPronto:Pronta; a ciò che ci aspetta?', '', 28153),
(157954, 'itIT', '', 'Avviserò gli altri, Keeshan ti raggiungerà alle gallerie.', 28153),
(157953, 'itIT', '', 'Ben fatto. Da qui dovremmo riuscire a gestire la cosa.', 28153),
(157952, 'itIT', '', 'Le forze dell\'Orda hanno aperto una breccia! Stanno cercando di stabilire una base! Respingile con il tuo Drago Fatato!', 28153),
(157951, 'itIT', 'Camminando attraverso questo boschetto potresti pensare che i ragni non amano il vento e l\'aria aperta, ma in verità essi sono proprio come te e me. Inoltre, le ragnatele rendono piuttosto ovvia la presenza di aracnidi.', '', 28153),
(157950, 'itIT', '', 'Troviamoci fuori dalle rovine di Zo\'bal. Fai attenzione.', 28153),
(157949, 'itIT', 'Ah, il brivido della caccia. Assaporalo, proprio come faccio io.', '', 28153),
(157948, 'itIT', '', 'Riposo per gli stanchi, cibo per gli affamati.', 28153),
(157947, 'itIT', 'Sempre, Principessa.', '', 28153),
(157946, 'itIT', '', 'Capisco. Tornerò a Zuldazar. Tienimi informata sulle operazioni dell\'Orda a Nazmir. Tieni li occhi aperti, Rokhan.', 28153),
(157945, 'itIT', 'Sylvanas vuole dar loro na possibilità. Nun tengono più na casa e, lavorando con noi, avrebbero nu posto in cui stare nell\'Orda. Altrimenti, li cacceremo via.', '', 28153),
(157944, 'itIT', 'Questa minaccia alata preda in mare aperto, prendendo di mira le navi che mandiamo contro Kul Tiras. Poni fine alla sua caccia.', '', 28153),
(157943, 'itIT', '', 'Nun mi fido di chesto Dreven, Rokhan. Nun è saggio coinvolgere i San\'layn in chesto conflitto.', 28153),
(157942, 'itIT', 'Farò come chiedi, per ora. Libereremo questa galleria e avviseremo quando le vostre forze potranno muoversi.', '', 28153),
(157941, 'itIT', 'Perché parte dell\'accordo tuo con Sylvanas prevedeva il rispetto dell\'autorità gerarchica nell\'Orda, e io sono più alto in grado di te, cumpà.', '', 28153),
(157940, 'itIT', 'Vuoi che usiamo le nostre abilità... per muovere rocce. E per quale motivo dovrei seguirti, Troll?', '', 28153),
(157939, 'itIT', 'Ci sta na galleria crollata che collega Nazmir a Vol\'dun. Piglia dei seguaci, usa i poteri tuoi per aprire nu varco e poi attaccheremo le forze principali dell\'Alleanza.', '', 28153),
(157938, 'itIT', '', 'Ci sta na galleria crollata a sud di qui che collega Nazmir a Vol\'dun. Apri il passaggio e l\'Orda potrà colpire la base principale dell\'Alleanza a Vol\'dun con facilità.', 28153),
(157937, 'itIT', 'Sylvanas nun ne sarà felice. Dobbiamo muoverci in fretta se vogliamo fermare l\'Alleanza, Principe Dreven.', '', 28153),
(157936, 'itIT', 'Diciamo che è una delle mie specialità. L\'Alleanza ha smantellato le forze dell\'Orda nella Necropoli, uccidendo Areiel nello scontro.', '', 28153),
(157935, 'itIT', '', 'Principessa Talanji per te, Principe Dreven. E tu come lo sai?', 28153),
(157934, 'itIT', 'Il Capitano Areiel nun verrà perché è stato acciso, Talanji.', '', 28153),
(157933, 'itIT', '', 'Eppure nun sta accà. È troppo occupata per darci nu rapporto della situazione?', 28153),
(157932, 'itIT', 'Areiel ha acciso sia l\'Alleanza che i Troll del Sangue e ci ha aiutati a stabilire na base nella Necropoli.', '', 28153),
(157931, 'itIT', '', 'Chiedo scusa per il ritardo, Rokhan. Dimmi come procedono le cose. Chesto Capitano Areiel si è dimostrato utile?', 28153),
(157930, 'itIT', 'Principessa, grazie per essere venuta accà fin da Zandalar. Stiamo lavorando duramente per tenere a bada i Troll del Sangue e li invasori dell\'Alleanza.', '', 28153),
(157929, 'itIT', '', '$gBenvenuto:Benvenuta;, $n. L\'avamposto è ai tuoi ordini.', 28153),
(157927, 'itIT', 'Sono al tuo servizio.', '', 28153),
(157926, 'itIT', '<Prendi il Tonico dell\'Invisibilità.>', '<Prendi il Tonico dell\'Invisibilità.>', 28153),
(157925, 'itIT', '', 'Rimani $gnascosto:nascosta;. Solo uno di noi dovrebbe entrare. Io starò qui per assicurarmi che nessuno scopra cosa stiamo facendo.\n\nHo un Tonico dell\'Invisibilità che puoi usare per intrufolarti là dentro. Dovrebbe renderti completamente invisibile... ma per poco tempo.\n\nBevi il tonico e poi addentrati nelle rovine. Scopri cosa sta pianificando l\'Orda e poi vattene.', 28153),
(157924, 'itIT', 'Temo che anche le vittorie più piccole stiano solo rimandando l\'inevitabile.', '', 28153),
(157923, 'itIT', 'Stiamo tenendo a bada l\'Orda, ma la loro attenzione si è spostata su un\'eruzione di Azerite lungo la costa. Dobbiamo fermarli.', '', 28153),
(157920, 'itIT', 'Avvicinati, $gcaro:cara;. Wunja è cieca ma nun è sorda! Eheheh! Stai accà dalla vecchia Wunja in cerca di na pozione?', 'Avvicinati, $gcaro:cara;. Wunja è cieca ma nun è sorda! Eheheh! Stai accà dalla vecchia Wunja in cerca di na pozione?', 28153),
(157919, 'itIT', '', 'Al Grande G non piacerà tutto questo...', 28153),
(157918, 'itIT', '', 'Ora ti arriva un cazzotto, dritto sul muso!', 28153),
(157917, 'itIT', 'La mia gente è pronta, $p. Per l\'Alleanza.', '', 28153),
(157916, 'itIT', '', 'A quanto pare sarai al mio fianco, $p. Ci vediamo all\'accampamento del Circolo del Reliquiario.', 28153),
(157915, 'itIT', 'Micciapazza, muoviamoci.', '', 28153),
(157914, 'itIT', 'Ho combattuto in tutte e tre le guerre. Credevo di aver visto il peggio che Azeroth potesse offrire.\n\nMi sbagliavo.', '', 28153),
(157913, 'itIT', '', 'Ho qualcosa che potrebbe aiutare.', 28153),
(157912, 'itIT', '', 'Rimani soltanto tu, $geroe:eroina;. Fai rapporto al Capitano Lunestiva e rinforza il confine!', 28153),
(157911, 'itIT', '', 'Arcieri Cavalcaippogrifi, venite con me. Ci raduneremo a Lor\'danel e rimarremo all\'erta come un\'unità di risposta mobile!', 28153),
(157910, 'itIT', '', 'Sentinelle, create un fronte al Fiume Lettocurvo! Radunate gli alleati al Bosco degli Antichi!', 28153),
(157909, 'itIT', '', 'Cacciatrici, dovete rinforzare il confine meridionale di Rivafosca! Portate i Lancialame!', 28153),
(157908, 'itIT', '', 'Dobbiamo fare qualcosa! Sentinelle, avanzate!', 28153),
(157907, 'itIT', 'Capitano, l\'Orda ha raggiunto il Fiume Lettocurvo! Non possiamo trattenerli ancora a lungo!', 'Capitano, l\'Orda ha raggiunto il Fiume Lettocurvo! Non possiamo trattenerli ancora a lungo!', 28153),
(157906, 'itIT', 'Un alpaca! Fantastico!', '', 28153),
(157905, 'itIT', 'Vuoi davvero farlo?', 'Vuoi davvero farlo?', 28153),
(157904, 'itIT', '', 'Ai tuoi ordini!', 28153),
(157903, 'itIT', '<Attacca.>', '<Attacca.>', 28153),
(157902, 'itIT', 'Che ne dici di un po\' d\'oro?', 'Che ne dici di un po\' d\'oro?', 28153),
(157900, 'itIT', 'Sylvanas vuole me e intendo darle ciò che vuole. Il messaggio è già stato inviato alla nostra flotta. Presto torneranno, se Elune lo vorrà.', '', 28153),
(157899, 'itIT', 'Devo chiederti di occuparti della difesa di Darnassus.', '', 28153),
(157898, 'itIT', 'Delaryn, raggiungi i nostri avamposti. Raduna tutti i soldati che riesci a trovare e portali qui.', '', 28153),
(157897, 'itIT', '', 'E tu, Shan\'do?', 28153),
(157896, 'itIT', 'La Regina Banshee vuole conquistare l\'Albero del Mondo.', '', 28153),
(157895, 'itIT', '', 'Malfurion! Le forze dell\'Orda si sono radunate all\'Avamposto di Zoram\'gar.', 28153),
(157894, 'itIT', 'Puoi passare attraverso il muro. I Fuochi Fatui non ti faranno del male.', '', 28153),
(157893, 'itIT', '', 'Anche nei tuoi ultimi istanti non riesci a vedere il vero potenziale degli Umani.', 28153),
(157892, 'itIT', '', 'Vedo che non hai ancora abbandonato la tua antiquata visione sugli Umani. Avrei dovuto ucciderti molto tempo fa.', 28153),
(157891, 'itIT', '', 'Sono destinata a vivere per l\'eternità. Non morirò qui oggi!', 28153),
(157890, 'itIT', '', 'È un peccato che tu stia combattendo al fianco di questo lurido Umano, Shandris! Hanno vite così corte e insignificanti.', 28153),
(157889, 'itIT', '', 'Shandris! Sono passati... due, tremila anni? Non mi sarei mai aspettata di rivederti in circostanze simili e con te impegnata ad aiutare un Umano, per giunta.', 28153),
(157888, 'itIT', '', 'Oscurità... Sylvanas... è questo ciò che hai visto... da cui desideravi salvarci?', 28153),
(157887, 'itIT', '', 'E io che credevo sarebbe stata una semplice missione esplorativa. Sarà divertente!', 28153),
(157886, 'itIT', '', 'È finita. Trova i suoi piani e torna al Presidio di Camporosso quando hai finito.', 28153),
(157885, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso Xibala a Zuldazar.', '|cFF0000FF(Missione)|r Fai rotta verso Xibala a Zuldazar.', 28153),
(157884, 'itIT', 'Ben fatto! Con l\'annientamento di quella creatura, le nostre truppe potranno attraversare l\'area indisturbate.', '', 28153),
(157883, 'itIT', 'Il rum è per i veri Marferreo. Giù le mani!', 'Il rum è per i veri Marferreo. Giù le mani!', 28153),
(157882, 'itIT', 'È già abbastanza difficile stabilire delle linee di rifornimenti attraverso una palude senza che delle bestie magiche ci intralcino la strada. Eliminala e liberaci la via.', '', 28153),
(157881, 'itIT', '', 'Ben fatto! Chella creatura nun ci creerà più problemi.', 28153),
(157880, 'itIT', '', 'Il mojo oscuro sta nutrendo chesta creatura! Riporta le anime tra le braccia di Bwonsamdi.', 28153),
(157879, 'itIT', '', 'Un\'altra vittoria.', 28153),
(157878, 'itIT', 'Imparerai che ci sta nu prezzo da pagare per chi osa interrompere Bwonsamdi! Perché nun vai a farti nu giro?', '', 28153),
(157877, 'itIT', '', 'I miei esploratori dicono che c\'è stata un\'improvvisa eruzione di Azerite qui a Rivafosca. Aiuta i nostri alleati Goblin a portarla al sicuro.', 28153),
(157876, 'itIT', 'Non avvicinarti troppo a Bwonsamdi!', 'Non avvicinarti troppo a Bwonsamdi!', 28153),
(157875, 'itIT', 'Cos\'hai a quelle orecchie?$B$BAaah, si chiama moda, OVVIAMENTE.', '', 28153),
(157874, 'itIT', 'Canaglie Hozen. Spero per voi che non manchi una goccia di rum.', 'Canaglie Hozen. Spero per voi che non manchi una goccia di rum.', 28153),
(157873, 'itIT', 'Inutili ratti di sentina, smettetela di bere il rum!', 'Inutili ratti di sentina, smettetela di bere il rum!', 28153),
(157872, 'itIT', 'La nostra priorità è spezzare i legami dell\'Orda con gli Zandalari. Per farlo, dobbiamo stabilire degli avamposti nel territorio nemico.', '', 28153),
(157871, 'itIT', 'È ora di mostrare all\'orda che la VII Legione fa sul serio.', '', 28153),
(157870, 'itIT', '', 'Soldati... No! Non attaccate i...', 28153),
(157869, 'itIT', 'Uhm, funziona questo affare?', '', 28153),
(157868, 'itIT', 'Ahah, gli hai dato una bella ripassata! Ci vorrà un po\' prima che le loro forze si organizzino di nuovo. Ottimo.', '', 28153),
(157867, 'itIT', 'Siamo riusciti a recuperare un\'altra delle armi d\'assedio dell\'Orda. È ora di ribaltare la situazione!', '', 28153),
(157866, 'itIT', 'No! No! Impossibile. Al capo nun piacerà tutto chesto. Il vecchio Bwonsamdi nun perdeva no spirito da... Oh, che brutta situazione.', '', 28153),
(157865, 'itIT', 'Ehi, Vol\'jin? Vieni fuori da chell\'urna. Eheh. Aspetta... aspetta, aspetta... no! Dove sta lo spirito? Dove sta Vol\'jin?!?', '', 28153),
(157864, 'itIT', 'Vattene, campione. Nun ci sta niente per te accà.', '', 28153),
(157863, 'itIT', 'Fortunatamente, i lavoratori non sembrano interessati ai nostri affari... al contrario degli scagnozzi della compagnia.\n\nHai ciò che ci serve?', '', 28153),
(157862, 'itIT', 'Oggi è stato fatto molto. Possiamo radunarci fuori.', 'Oggi è stato fatto molto. Possiamo radunarci fuori.', 28153),
(157861, 'itIT', '', 'Jakra\'zet dev\'essere fermato.', 28153),
(157860, 'itIT', 'Cosa sta facendo il Re per la nostra terra natale?', 'Cosa sta facendo il Re per la nostra terra natale?', 28153),
(157859, 'itIT', 'Le risorse di Roccavento stanno scarseggiando. Non ne rimarranno abbastanza per tenerci in vita.', 'Le risorse di Roccavento stanno scarseggiando. Non ne rimarranno abbastanza per tenerci in vita.', 28153),
(157858, 'itIT', 'No, no, no. Tu nun lascerai chella roba accà.', '', 28153),
(157857, 'itIT', 'Ben fatto! Fauci in meno di cui preoccuparsi.', '', 28153),
(157856, 'itIT', 'Invece di combattere per delle rovine, l\'Alleanza dovrebbe riprendersi la nostra città natale!', 'Invece di combattere per delle rovine, l\'Alleanza dovrebbe riprendersi la nostra città natale!', 28153),
(157855, 'itIT', 'Quella è stata la seconda casa che abbiamo perso.', 'Quella è stata la seconda casa che abbiamo perso.', 28153),
(157854, 'itIT', 'Dove dovremmo andare ora?', 'Dove dovremmo andare ora?', 28153),
(157853, 'itIT', 'Ben fatto. Chesto permetterà alle prossime generazioni di prosperare.', '', 28153),
(157852, 'itIT', 'C\'è in gioco qualcosa di più grande, Generale. Dobbiamo adattarci a queste nuove informazioni.', '', 28153),
(157851, 'itIT', '', 'Non possiamo lasciare che quel mostro scappi, Sventradraghi.', 28153),
(157850, 'itIT', 'Niente Lanciascura! Nessun Troll stupido può entrare accà!', '', 28153),
(157849, 'itIT', 'Nessuna feccia dell\'Orda può essere degna di chesto posto. Noi dei Sabbiafurente ti sfidiamo!', 'Nessuna feccia dell\'Orda può essere degna di chesto posto. Noi dei Sabbiafurente ti sfidiamo!', 28153),
(157848, 'itIT', '', 'Grazie, Alleria. Il tuo aiuto è il benvenuto.', 28153),
(157847, 'itIT', 'Un\'ottima strategia. Approvo.', '', 28153),
(157846, 'itIT', '', 'Noi gli daremo la caccia e ti porteremo la sua testa, mentre Shandris si occuperà di seguire le tracce del Principe del Sangue.', 28153),
(157845, 'itIT', '', 'I miei Elfi del Vuoto possono occuparsi dell\'eliminazione di Gallywix.', 28153),
(157844, 'itIT', '', '<Alleria apre un Portale del Vuoto dietro di lei.>', 28153),
(157843, 'itIT', '', 'Non possiamo lasciare che nessuno dei bersagli ci sfugga... e non sarà necessario farlo.', 28153),
(157842, 'itIT', '', 'Perdonate l\'interruzione, ma credo abbiate ragione entrambi.', 28153),
(157841, 'itIT', '', 'Ho visto di cos\'era capace Dreven, Sventradraghi. E se ce ne fossero altri come lui?', 28153),
(157840, 'itIT', 'Tatticamente parlando, lui rappresenta il loro punto debole. Questa è un\'opportunità rara. Dobbiamo colpire subito.', '', 28153),
(157839, 'itIT', 'Gallywix finanzia la campagna militare dell\'Orda e conosce l\'Azerite meglio di tutti gli altri comandanti.', '', 28153),
(157838, 'itIT', '', 'Possiamo uccidere quel dannato Goblin quando ci pare! Se Dreven dovesse fuggire, potremmo non riuscire a trovarlo di nuovo.', 28153),
(157837, 'itIT', 'Presto ci occuperemo del Principe del Sangue Dreven, Generale, ma questa è una rara opportunità per mettere in ginocchio l\'armata dell\'Orda. Tutto il resto dovrà aspettare.', '', 28153),
(157836, 'itIT', 'Una bestia alata sta dando in pasto i miei uomini ai suoi piccoli! Fa\' che il suo prossimo pasto sia a base d\'acciaio.', '', 28153),
(157835, 'itIT', 'Nun porterete $gchel traditore:chella traditrice; dell\'Orda in chesto sacro luogo!', '', 28153),
(157834, 'itIT', '', 'I nostri alleati attendono i tuoi ordini.', 28153),
(157833, 'itIT', 'La grande Pa\'ku ha deciso che il tempo di Ji\'arak è giunto al termine. Raduna le forze tue e accidi chella creatura.', '', 28153),
(157832, 'itIT', 'Ti do il benvenuto. Abbiamo del lavoro da fare.', '', 28153),
(157831, 'itIT', 'Quello è... sangue? Davvero? Mi stai dicendo che c\'è letteralmente uno scudo di sangue a protezione di quella cosa? Va bene... ora le ho davvero viste tutte.', '', 28153),
(157830, 'itIT', '', 'Il circolo è nostro! Tutti ai vostri posti!', 28153),
(157829, 'itIT', 'La guerra successiva. E quella dopo ancora.', '', 28153),
(157828, 'itIT', 'La Luce perdurerà a lungo quando non ci saremo più. Ma quando questa guerra sarà finita, a te cosa rimarrà, Shaw?', '', 28153),
(157827, 'itIT', 'La tua fede nella Luce? O in Turalyon?', '', 28153),
(157826, 'itIT', 'Al contrario. Osservare il ritorno di Turalyon e sapere come la Luce lo avesse sostenuto e trasformato non fece che rafforzare la mia risolutezza. Sapevo che la mia fede era ben riposta.', '', 28153),
(157825, 'itIT', 'E l\'aver scoperto che Turalyon era vivo non ha minato la tua devozione? Le tue scelte?', '', 28153),
(157824, 'itIT', 'Quando partì per la Spedizione dell\'Alleanza nelle Terre Esterne e fu dato per disperso, grazie alla Luce realizzai di poter essere sia un soldato che un Paladino. Giurai di onorare il suo sacrificio.', '', 28153),
(157823, 'itIT', 'Ma osservando questi Paladini, ne fui ispirato. In particolare uno... Turalyon. La sua fede lo sostenne, alimentò la sua dedizione e lo rese un grande capo.', '', 28153),
(157822, 'itIT', 'Drukan si sta riposando.', '', 28153),
(157821, 'itIT', 'Ho servito come cavaliere nell\'ordine della Mano d\'Argento. Ero dubbioso riguardo alla coesistenza di un ordine sacerdotale con le arti marziali, così mi sono concentrato sul combattimento.', '', 28153),
(157820, 'itIT', 'Dimmi, Sventradraghi, come mai un Paladino è alla guida delle forze d\'élite? Non dovresti essere in giro a consacrare templi o cose del genere?', '', 28153),
(157819, 'itIT', 'Ah, certo.', '', 28153),
(157818, 'itIT', 'Gentile da parte tua, ma se dovessi scegliere tra l\'onore e il compimento di una missione, sceglierei sempre la seconda opzione. Per l\'Alleanza, ovviamente.', '', 28153),
(157817, 'itIT', 'Devo ammetterlo... essendo un Paladino, non ero sicuro della necessità di spie e assassini nell\'Alleanza. Ma l\'onore e la lealtà che hai dimostrato al nostro Re è indubbia.', '', 28153),
(157816, 'itIT', 'L\'IR:7 è stata creata per agire dietro le quinte. Preferisco stare nelle ombre dove non sono così... esposto.', '', 28153),
(157815, 'itIT', 'Ne ho perso il conto. Seguo gli ordini dell\'Alleanza... e vado dove la Luce mi chiama. Ma anche per te la guerra non è sconosciuta.', '', 28153),
(157814, 'itIT', 'Quante campagne contro l\'Orda hai diretto con questa, Sventradraghi?', '', 28153),
(157813, 'itIT', 'Fai attenzione a dove punti quel coso, $n.', '', 28153),
(157812, 'itIT', 'Pensavo fosse giusto informarti.', '', 28153),
(157811, 'itIT', 'L\'Officina è operativa! Se ti serve qualcosa, abbiamo tutto ciò che serve per trasformarla in realtà!', '', 28153),
(157810, 'itIT', 'I danni a Zannaguerra vi saranno restituiti dieci volte tanto!', '', 28153),
(157809, 'itIT', 'Non temo più la morte. È lei a temere me...', '', 28153),
(157808, 'itIT', 'La Capoguerra non permetterà che la cosa resti impunita.', '', 28153),
(157807, 'itIT', 'Per voi la morte è troppo poco.', '', 28153),
(157806, 'itIT', 'Banchetterò sul tuo cadavere!', '', 28153),
(157805, 'itIT', 'Ti apro in due!', '', 28153),
(157804, 'itIT', '', 'Ottimo lavoro, ma qualcosa mi dice che continueranno ad attaccare.', 28153),
(157803, 'itIT', '', 'I pirati continuano ad attaccare Colle Vigile! Ma quando impareranno?!? Aiuta i soldati a sbarazzarsi di loro!', 28153),
(157802, 'itIT', 'Grazie! Ora devo tornare dalla mia famiglia.', 'Grazie! Ora devo tornare dalla mia famiglia.', 28153),
(157801, 'itIT', 'Hai visto l\'espressione sui loro volti? Oh, è stato fantastico! Dovranno ripulire per giorni interi!', '', 28153),
(157800, 'itIT', 'L\'Orda è un nugolo di barbari!', 'L\'Orda è un nugolo di barbari!', 28153),
(157799, 'itIT', 'Una tale infida corruzione deve essere epurata... prima che infetti l\'Orda.', '', 28153),
(157798, 'itIT', 'Ben fatto. Non possiamo stare a guardare mentre gli abissi corrompono la nostra terra!', '', 28153),
(157797, 'itIT', 'Venrik e io adoravamo prendere un paio di pappagalli cavalcabili e fargli fare un bel giro di tanto in tanto. Provaci anche tu e fai piovere un po\' di giustizia su quei briganti!', '', 28153),
(157796, 'itIT', 'Non rimane che polvere di te...', '', 28153),
(157795, 'itIT', 'Ho... sbagliato i calcoli.', '', 28153),
(157794, 'itIT', 'Questo abominio è l\'incarnazione della follia e della corruzione. Distruggilo immediatamente!', '', 28153),
(157793, 'itIT', 'Spero solo che la mia famiglia sia riuscita a fuggire in tempo.', 'Spero solo che la mia famiglia sia riuscita a fuggire in tempo.', 28153),
(157792, 'itIT', 'Il fumo era così denso che ci saremmo potuti perdere là dentro, se non fosse stato per la Regina Mantogrigio.', 'Il fumo era così denso che ci saremmo potuti perdere là dentro, se non fosse stato per la Regina Mantogrigio.', 28153),
(157791, 'itIT', 'Dobbiamo rispedire questa creatura negli abissi. Annientala!', '', 28153),
(157790, 'itIT', 'Siamo riusciti a malapena a salvarci.', 'Siamo riusciti a malapena a salvarci.', 28153),
(157789, 'itIT', 'Perché hanno fatto una cosa del genere?', 'Perché hanno fatto una cosa del genere?', 28153),
(157788, 'itIT', 'Mi state facendo girare i congegni!', '', 28153),
(157787, 'itIT', 'È tuuutto mio!', '', 28153),
(157786, 'itIT', 'Ti trivellerò fino a farti a pezzettini!', '', 28153),
(157785, 'itIT', '', 'Sarebbe stata una grande perdita per la Guardia dei Marefiero. Grazie a te, è stato solo un contrattempo.', 28153),
(157784, 'itIT', '', 'Una delle nostre navi di rifornimenti si è arenata. Gran parte della ciurma è fuggita, ma ha lasciato a bordo dei beni preziosi.', 28153),
(157783, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t L\'Araldo della Guerra Yenajz inizia a lanciare |cFFF00000|Hspell:274932|h[Abisso Interminabile]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_GATHERSHADOWS.BLP:20|t L\'Araldo della Guerra Yenajz inizia a lanciare |cFFF00000|Hspell:274932|h[Abisso Interminabile]|h|r!', 28153),
(157782, 'itIT', 'Cosa?!? Era Grog? Ah, speravo di trovare un bel tesoro... da SPENDERE in Grog!', '', 28153),
(157781, 'itIT', 'Al Covo della Libertà gira voce che uno di quei pirati abbia un ricco bottino nascosto nelle acque del molo. Vedi se riesci a trovarlo!', '', 28153),
(157780, 'itIT', 'Ottimo lavoro. Questo dovrebbe limitare la quantità di armi d\'Azerite che giungeranno a Boralus mentre ci occupiamo dell\'ammutinamento dei Bracescura.', '', 28153),
(157779, 'itIT', 'La Compagnia dei Bracescura deve ancora fermare la sua produzione di armi come ordinato. Ferma quella fonderia, ma cerca di non fare del male ai civili.', '', 28153),
(157778, 'itIT', 'Ehi, non ti preoccupare. Troveremo loro delle nuove case. La cosa importante è che siano fuori pericolo.', '', 28153),
(157777, 'itIT', 'La Compagnia dei Bracescura promette cibo agli orfani, ma non fa altro che sfruttarli. Fai fuggire quei bambini da là!', '', 28153),
(157776, 'itIT', 'Dicono che Azurethos riuscisse a tirare fuori un kraken dalle onde con i suoi artigli. Hai corso un grande pericolo, ma ora sei una leggenda.', '', 28153),
(157775, 'itIT', 'I marinai cantano del famoso Azurethos, in grado di ribaltare un galeone con un semplice soffio. Be\', quelle storie sono vere. Abbattilo e diventerai tu la leggenda nelle loro canzoni.', '', 28153),
(157774, 'itIT', '', 'Fate rapporto al Gran Supremo Faucisaure. Mostrate loro il prezzo della loro follia. Per l\'Orda!', 28153),
(157773, 'itIT', 'Quando chiudo gli occhi... vedo ancora le fiamme.', 'Quando chiudo gli occhi... vedo ancora le fiamme.', 28153),
(157772, 'itIT', 'Spero che i nostri amici siano al sicuro.', 'Spero che i nostri amici siano al sicuro.', 28153),
(157771, 'itIT', 'Non possiamo perdere Kalimdor.', 'Non possiamo perdere Kalimdor.', 28153),
(157770, 'itIT', 'Non posso credere che l\'Albero del Mondo... non esista più...', 'Non posso credere che l\'Albero del Mondo... non esista più...', 28153),
(157769, 'itIT', 'Quei cani dell\'Orda hanno distrutto la nostra casa!', 'Quei cani dell\'Orda hanno distrutto la nostra casa!', 28153),
(157768, 'itIT', 'Cosa vuoi? Oh, hai proprio la faccia di un collega ingegnere...', '', 28153),
(157767, 'itIT', 'Ho altre domande da farti.', 'Ho altre domande da farti.', 28153),
(157766, 'itIT', 'Quel cuoco folle? Credo sia un cugino di secondo grado. È triste, non fa che pensare a bombe e a bombe ancora più grandi. Il vero genio sta nell\'inventare la fonte d\'energia definitiva, così da poter alimentare macchine in grado di fare a pezzi un sacco di cose, il più a lungo possibile.', '', 28153),
(157765, 'itIT', 'Buongiorno, dottore. Vorrei acquistare uno dei tuoi reattori. Posso pagarti molto bene.', 'Buongiorno, dottore. Vorrei acquistare uno dei tuoi reattori. Posso pagarti molto bene.', 28153),
(157764, 'itIT', 'Sei davvero QUEL Dott. Boom?', 'Sei davvero QUEL Dott. Boom?', 28153),
(157763, 'itIT', 'Oh, davvero? Vedo che sei un ingegnere di grande abilità! Neanche lontanamente al mio livello, ma in pochi lo sono.', '', 28153),
(157762, 'itIT', '', 'Non ho idea di chi sia, ma di certo si merita di morire!', 28153),
(157761, 'itIT', 'Dottore, il livello d\'ingegneria di quel pezzo è straordinario!', 'Dottore, il livello d\'ingegneria di quel pezzo è straordinario!', 28153),
(157760, 'itIT', '', 'Rincontriamoci tutti all\'Incudine Nera! Serve un rapporto sui danni!', 28153),
(157759, 'itIT', 'Ehi, sto lavorando! Torna quando le tue abilità in ingegneria saranno degne di nota.', '', 28153),
(157758, 'itIT', '', 'Bene, li hai fatti fuori in fretta! Ora apriremo la porta. Riesco a sentire un sacco di nemici dall\'altra parte. Guardati le spalle!', 28153),
(157757, 'itIT', 'Ho passato gli ultimi cinque anni a riparare e migliorare la più avanzata e letale squadra di robot mai concepita. Vuoi vedere come le tue noiosissime mascotte se la cavano contro quelle costruite dal più grande meccanico di basso livello esistente nell\'universo?', '', 28153),
(157756, 'itIT', 'Malfunzionamento?!? Questo non dovrebbe succedere!', '', 28153),
(157755, 'itIT', 'La mia mente brillante e le mie macchine ancora più brillanti sono una combinazione letale.', '', 28153),
(157754, 'itIT', '', 'Ben fatto! Ora quel costrutto non è che un cumulo di macerie e tutta Drustvar è salva.', 28153),
(157753, 'itIT', '', 'Un enorme costrutto di pietra si è risvegliato nelle montagne qui vicino! Dobbiamo abbatterlo prima che si scateni contro la gente di Drustvar!', 28153),
(157752, 'itIT', 'Inconcepibile! La prossima volta costruirò robot più grandi.', '', 28153),
(157751, 'itIT', 'Nessuna mascotte può competere con la mia squadra. Sono invincibile!', '', 28153),
(157750, 'itIT', 'Preparati ad affrontare la mia formidabile squadra di robot altamente personalizzata!', '', 28153),
(157749, 'itIT', 'Sono pronto ad andare, Krag\'wa.', 'Sono pronta ad andare, Krag\'wa.', 28153),
(157748, 'itIT', 'Anche in questo momento i Troll del Sangue non fanno che massacrare i miei figli.$b$bTi aiuterò a raggiungere il loro capo, ma io devo tornare nella palude per difendere i miei piccoli.', '', 28153),
(157747, 'itIT', 'Krag\'wa, il capo dei Troll del Sangue è fuggito all\'interno di una grossa struttura in lontananza. Ti prego, aiutaci.', 'Krag\'wa, il capo dei Troll del Sangue è fuggito all\'interno di una grossa struttura in lontananza. Ti prego, aiutaci.', 28153),
(157746, 'itIT', 'Ah... ehm. Non ora, Venrik. Abbiamo cose più serie di cui occuparci.', '', 28153),
(157745, 'itIT', '', 'Sono qui per aiutare. Alla battaglia!', 28153),
(157744, 'itIT', '', 'Io combatto per la mia gente.', 28153),
(157743, 'itIT', '', 'Un nemico debole. Sbarazzatevene in fretta!', 28153),
(157742, 'itIT', 'Sai, quella che aveva i capelli \"come le piume di un corvo\". Eheh. Eheheh!', '', 28153),
(157741, 'itIT', '', 'In ricordo di Darnassus!', 28153),
(157740, 'itIT', '', 'Sarò felice di lasciarmi questo posto alle spalle.', 28153),
(157739, 'itIT', '', 'Sarà meglio andare, prima che arrivino altre di quelle... cose.', 28153),
(157738, 'itIT', '', 'Sì... me la caverò.', 28153),
(157737, 'itIT', 'Dimmi, Flynn. Che ne è stato di quella donna di cui parlavi sempre?', '', 28153),
(157736, 'itIT', '', 'Madre! Va tutto bene?', 28153),
(157735, 'itIT', '', 'Andrai a recuperare il martello? Nasconde un grande potere e sarebbe un disastro per noi se i Goblin scoprissero come usarlo.', 28153),
(157734, 'itIT', '', '$n, ho un altro compito da darti. Quei selvaggi erano della S.P.R. & Co., il che significa che saranno a Kezan, probabilmente per consegnare Ferroavverso nelle mani sudaticce del Magnate Trucirazzi.', 28153),
(157733, 'itIT', '', 'Thane della Forgia, Forgiacupa, scoprite come riparare l\'Incudine Nera.', 28153),
(157732, 'itIT', '', 'Ferroavverso è stato rubato e hanno tagliato in due l\'Incudine Nera!', 28153),
(157731, 'itIT', '', 'E Kul Tiras non si tirerà mai indietro.', 28153),
(157730, 'itIT', 'I Drust... non si fermeremo... mai...', '', 28153),
(157729, 'itIT', 'Per la barba di uno Gnomo!', '', 28153),
(157728, 'itIT', 'Voi due, aprite gli occhi! Guardate l\'Incudine Nera!', '', 28153),
(157727, 'itIT', '', 'Figlio di un nucleo! Dev\'essere stato il grosso robot con cui mi sono scontrata!', 28153),
(157726, 'itIT', 'Qualcuno mi ha teso un\'imboscata e ha rubato Ferroavverso!', '', 28153),
(157725, 'itIT', '', 'Sto bene. Tu, invece? Non hai un bell\'aspetto.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157724, 'itIT', 'Regina Reggente! Stai bene?!?', '', 28153),
(157723, 'itIT', '', 'Bene, signore e signori, possiamo andarcene!', 28153),
(157722, 'itIT', '', 'La mia gente ha già sconfitto la vostra razza una volta, mostro. Lo faremo di nuovo!', 28153),
(157721, 'itIT', 'Thros vi consumerà tutti! Finalmente avrò la mia vendetta!', '', 28153),
(157720, 'itIT', '', 'Proprio quando le cose cominciavano a mettersi bene per noi.', 28153),
(157719, 'itIT', '', '<Moira mormora qualcosa fra sé e sé.>', 28153),
(157718, 'itIT', '', 'Thaelin, dirigiti alla Sala degli Artigiani! Potrebbero essere andati verso la Tesoreria Oscura.', 28153),
(157717, 'itIT', '', 'Campione, prendi la Strada dei Ferroscuro e fa\' in modo che sia sicura!', 28153),
(157716, 'itIT', '', 'Thane della Forgia, prepara i tuoi incantatori per un contrattacco!', 28153),
(157715, 'itIT', '', 'Quei buoni a nulla verdastri pensano di attaccarci direttamente a casa nostra?', 28153),
(157714, 'itIT', 'Ci sono Goblin dappertutto!', '', 28153),
(157713, 'itIT', '', 'Alle armi!', 28153),
(157712, 'itIT', '', 'Hai sfidato la famiglia sbagliata, demone!', 28153),
(157711, 'itIT', '', 'Madre!', 28153),
(157710, 'itIT', '', 'Madre, attenta!', 28153),
(157709, 'itIT', '', 'Caspita, quello è bello grosso!', 28153),
(157708, 'itIT', 'Nessuno di voi fuggirà!', '', 28153),
(157707, 'itIT', '', 'Vieni, figlia mia. Troveremo il modo di uscire da qui.', 28153),
(157706, 'itIT', '', 'Attenzione, ne arrivano altri!', 28153),
(157705, 'itIT', '', 'Arrivano degli elementali!', 28153),
(157704, 'itIT', '', 'Abbiamo scoperto che l\'applicazione di una grande magia sull\'Azerite a volte può portare a risultati inaspettati.', 28153),
(157703, 'itIT', '', 'Jaina? Sei davvero tu?', 28153),
(157702, 'itIT', 'Quello che intende dire questo sgarbato topo da biblioteca è che devi guardarci le spalle dagli attacchi degli elementi.', '', 28153),
(157701, 'itIT', 'È troppo... tardi...', '', 28153),
(157700, 'itIT', '$C, di sicuro avremo a che fare con qualche problemino di natura azeritica durante la forgiatura. Credi di potertene occupare?', '', 28153),
(157699, 'itIT', 'Ti va di mettere un po\' di Azerite sull\'incudine per me?', '', 28153),
(157698, 'itIT', 'Voi sarete i prossimi!', '', 28153),
(157697, 'itIT', 'Stolti insolenti! Lei non ha alcuna speranza!', '', 28153),
(157696, 'itIT', 'Sì, Regina Reggente.', '', 28153),
(157695, 'itIT', '', 'Thaelin, Thurgaden, lavorateci su.', 28153),
(157694, 'itIT', '', 'Basta! Mostraci il tuo vero volto, creatura!', 28153),
(157693, 'itIT', '', 'Stanno facendo progressi. Anduin continua a chiedere aggiornamenti ogni giorno, quindi pensavo che potremmo mostrarti cos\'abbiamo appreso.', 28153),
(157692, 'itIT', '', 'I miei uomini migliori stanno raffinando l\'Azerite da quando è apparsa nelle nostre profondità.', 28153),
(157691, 'itIT', '', 'Grazie per essere $gvenuto:venuta;, $n.', 28153),
(157690, 'itIT', '', 'Padre... ti prego...', 28153),
(157689, 'itIT', '', 'Ci vediamo alla statua sulla collina.', 28153),
(157688, 'itIT', '', 'Grande Krag\'wa, teniamo bisogno dell\'aiuto tuo!', 28153),
(157687, 'itIT', 'Proprio come durante la Terza Guerra.', '', 28153),
(157686, 'itIT', 'Per la Compagnia Bravo!', '', 28153),
(157685, 'itIT', 'Proprio come su Draenor!', '', 28153),
(157684, 'itIT', 'Mi ricorda la Seconda Guerra.', '', 28153),
(157683, 'itIT', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff.', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff.', 28153),
(157682, 'itIT', 'Riesaminiamo il piano per uccidere il Capitano Areiel.', 'Riesaminiamo il piano per uccidere il Capitano Areiel.', 28153),
(157681, 'itIT', 'Generale.', '', 28153),
(157680, 'itIT', '', 'Muoviamoci subito. $n presiederà la zona, mentre noi daremo supporto e perlustreremo in avanscoperta. Keeshan, questo include anche te.', 28153),
(157679, 'itIT', '', 'Potremmo ottenere informazioni sui movimenti dell\'Orda se salviamo i Tortolliani, che dovrebbero condurci al Capitano Areiel.', 28153),
(157678, 'itIT', 'Signora, ci sono dei Tortolliani a Nazmir e le informazioni indicano che sono a conoscenza degli spostamenti dell\'Orda. Molti di loro sono stati catturati dai Troll del Sangue.', '', 28153),
(157677, 'itIT', 'È come al tiro a segno!', 'È come al tiro a segno!', 28153),
(157676, 'itIT', 'Proprio in mezzo alle pinne!', 'Proprio in mezzo alle pinne!', 28153),
(157675, 'itIT', '', 'Ci servono informazioni e alleati all\'interno di Nazmir per riuscirci. Per fortuna, abbiamo un\'opportunità. Keeshan?', 28153),
(157674, 'itIT', '', 'La morte del Capitano Areiel intralcerà le operazioni dell\'Orda a Nazmir, indebolendo anche le Guardaboschi Oscure di Sylvanas.', 28153),
(157673, 'itIT', 'Questi Troll hanno fatto del male ai miei figli troppo a lungo! Ora sarò io a fare del male a loro.', '', 28153),
(157672, 'itIT', 'Ho sempre creduto che Flussomorto fosse dall\'altra parte.', '', 28153),
(157671, 'itIT', '', 'È stato tutto molto tranquillo da quando Nedly è sparito.', 28153),
(157670, 'itIT', 'Non possiamo permettere che accada. Raduna i tuoi alleati. Stromgarde appartiene all\'Alleanza!', '', 28153),
(157669, 'itIT', 'Tuttavia, l\'Orda sta radunando le sue forze per toglierci il controllo su di essa. Se dovesse riuscirci, otterrebbe un punto strategico fondamentale nei Regni Orientali.', '', 28153),
(157668, 'itIT', 'Stromgarde era un centro nevralgico del potere dell\'Alleanza a Lordaeron. Faremo in modo che torni a esserlo.', '', 28153),
(157667, 'itIT', 'Organizza una spedizione e impadronisciti di quell\'Azerite... prima che lo faccia l\'Orda.', '', 28153),
(157666, 'itIT', 'Gli esploratori di Shaw hanno scoperto dei depositi di Azerite su alcune isole sparse nei mari. L\'Alleanza ne ha bisogno.', '', 28153),
(157665, 'itIT', 'Gli agenti che recluterai mineranno gli sforzi dell\'Orda... e ci aiuteranno a ottenere la vittoria.', '', 28153),
(157664, 'itIT', 'Collabora con Mathias Shaw per assemblare una squadra di agenti segreti. Nessuno è più indicato per questo lavoro del Maestro delle Spie di Roccavento.', '', 28153),
(157663, 'itIT', 'La vittoria in una guerra richiede la forza delle armi. Ma a volte serve un approccio più... discreto.', '', 28153),
(157662, 'itIT', 'Sono pronto a evocare Krag\'wa.', 'Sono pronta a evocare Krag\'wa.', 28153),
(157661, 'itIT', '', 'Zelling sta parlando con la sua famiglia. Stai indietro. Se ci sarà bisogno di intervenire, lo vedremo.', 28153),
(157660, 'itIT', '', 'Usa la loro furtività e astuzia per identificare le debolezze del nemico... e sfruttale a dovere.', 28153),
(157659, 'itIT', '', 'Lavora con Garona Mezzorco per mettere insieme un gruppo con i più subdoli e scaltri agenti dell\'Orda. Manderai queste forze in missione sotto copertura a Kul Tiras e Zandalar.', 28153),
(157658, 'itIT', '', 'Per assicurarmi che tu abbia successo, manderò con te un agente con delle doti davvero... particolari. Sono sicura che sarà molto utile per questa missione.', 28153),
(157657, 'itIT', '', 'Devi agire in fretta. Col favore della notte cerca i resti senza farti vedere. Quelle acque pullulano di pattuglie dell\'Alleanza.', 28153),
(157656, 'itIT', '', 'Nathanos, la conversione di Fratello Zelling sta già portando i suoi frutti. Ci ha rivelato la posizione del relitto che cercavamo.', 28153),
(157655, 'itIT', '', 'Ora il Re moccioso sta mandando i suoi sottoposti a riconquistarla. Non possiamo permetterlo.', 28153),
(157654, 'itIT', '', 'Stromgarde era un centro di potere dell\'Alleanza nel cuore dei Regni Orientali... prima che la fortezza cadesse in rovina.', 28153),
(157653, 'itIT', '', 'Dobbiamo sfruttare il vantaggio. Esplora quelle isole e rivendicale... prima che lo faccia l\'Alleanza.', 28153),
(157652, 'itIT', '', 'I nostri alleati Goblin continuano a dimostrare le loro capacità. Hanno individuato dei depositi d\'Azerite sulle isole sparse nei mari.', 28153),
(157651, 'itIT', '', 'In guerra, ci sono momenti in cui un singolo colpo di pugnale in una schiena fa più danni di mille spade su un campo di battaglia.', 28153),
(157650, 'itIT', '', 'Quel maledetto Mildenhall è pazzo. A quanto pare la distilleria è stata invasa dai suoi esperimenti. Vai a controllare, prima che la cosa sfugga di mano.', 28153),
(157649, 'itIT', '', 'Ringrazio te e la tua Orda per aver aiutato a liberare la mia ciurma.\n\nFintanto che rimarrò al comando, i Solcanebbia saranno liberi!', 28153),
(157648, 'itIT', '', 'Era il sacrificio finale... abbiamo fallito.', 28153),
(157647, 'itIT', 'No... Non può essere!', '', 28153),
(157646, 'itIT', 'Ma lo farai!', '', 28153),
(157645, 'itIT', 'Sofferenza? Nun hai visto la vera sofferenza. Nun ancora...', '', 28153),
(157644, 'itIT', 'Taelia, quando il tempo te lo permetterà, devi venire a Roccavento come mia ospite. Ho molte storie su tuo padre da raccontarti.', '', 28153),
(157643, 'itIT', '', 'Le lettere smisero di arrivare. Ho... ho così tante domande.', 28153),
(157642, 'itIT', '', 'Dagli na morte rapida. Abbiamo già visto abbastanza sofferenza oggi.', 28153),
(157641, 'itIT', '', '\"Stellina mia\".', 28153),
(157640, 'itIT', 'Ora ricordo! Era solito scriverti delle lettere. Usava sempre un nomignolo con te...', '', 28153),
(157639, 'itIT', 'Il Gran Signore Bolvar era un grand\'uomo. Un vero eroe per l\'Alleanza... e per me.', '', 28153),
(157638, 'itIT', '', 'Conoscevi mio padre?', 28153),
(157637, 'itIT', '<Spasmi.>', '', 28153),
(157636, 'itIT', 'Taelia... ti prego, alzati. L\'onore è mio.', '', 28153),
(157635, 'itIT', '', 'La figlia di Bolvar. Cresciuta sotto la nostra protezione sin dalla Terza Guerra.', 28153),
(157634, 'itIT', 'Domadraghi?!?', '', 28153),
(157633, 'itIT', '', 'Taelia Domadraghi.', 28153),
(157632, 'itIT', '', 'È un onore fare la tua conoscenza, Re Wrynn. Sono Taelia.', 28153),
(157631, 'itIT', '', 'Anche lei è stata di fondamentale aiuto nella salvezza del nostro regno... e della mia vita.', 28153),
(157630, 'itIT', '', 'Re Wrynn, c\'è qualcuno che dovresti incontrare.', 28153),
(157629, 'itIT', 'È un grande onore e piacere ridare il benvenuto a Kul Tiras nell\'Alleanza. Possa la Luce guidarci alla vittoria.', '', 28153),
(157628, 'itIT', '', 'Grazie... a tutti voi. Farò tutto il possibile per dimostrarmi degna della vostra fiducia.', 28153),
(157627, 'itIT', '', 'Cosa dite?', 28153),
(157626, 'itIT', '', 'È finita, Generale. I complotti, le bugie, gli assassinii.', 28153),
(157625, 'itIT', '', 'Sam, no!', 28153),
(157624, 'itIT', 'SACRAONDA!', '', 28153),
(157623, 'itIT', 'Sei condannato, Pike. Consegnerò la flotta alla nostra gloriosa salvatrice... Azshara.', '', 28153),
(157622, 'itIT', 'Tutto ciò che vedo sono anime perdute in cerca di libertà.', '', 28153),
(157621, 'itIT', 'È finita, Sacraonda! Guardati attorno... sei circondato!', '', 28153),
(157620, 'itIT', 'Mi pare evidente che sai il fatto tuo. Posso sempre contare su di te per un piccolo massacro!', '', 28153),
(157619, 'itIT', 'Non abbiamo molte armi a disposizione, quindi dobbiamo sfruttare ogni risorsa. Trova un modo per provocare dei seri danni prima che si rendano conto di cosa li ha colpiti.', '', 28153),
(157618, 'itIT', '', 'Chissà quanti danni quella cosa avrebbe provocato alla flotta. Grazie a te, non lo scopriremo mai.', 28153),
(157617, 'itIT', '', 'Sei troppo debole per governare, Katherine.', 28153),
(157616, 'itIT', '', 'E io per poco non... Priscilla... come hai potuto tradire il regno? Come hai potuto tradire me?', 28153),
(157615, 'itIT', '', 'Quel golem potrebbe tagliare una nave a metà! Non possiamo lasciare che Ser Sacraonda abbia un\'arma di quella portata.', 28153),
(157614, 'itIT', '', 'Hai ingaggiato i pirati, li hai armati fino ai denti e li hai mandati contro i tuoi stessi contadini.', 28153),
(157613, 'itIT', '', 'Si chiama Azerite... L\'Orda e l\'Alleanza stanno già combattendo per ottenerla.', 28153),
(157612, 'itIT', '', 'La tua compagnia ha creato le armi usate per distruggere i Cancelli di Daelin con questa!', 28153),
(157611, 'itIT', '', 'Dama Priscilla Bracescura, ti dichiaro in arresto per traffico illegale, cospirazione coi pirati e alto tradimento contro l\'Ammiragliato di Kul Tiras.', 28153),
(157610, 'itIT', 'L\'oceano ci dà molto, ma sotto la sua superficie non esiste altro che disperazione.', '', 28153),
(157609, 'itIT', '', 'Cosa significa tutto questo?!?', 28153),
(157608, 'itIT', '', 'Quindi questo era il tuo piano sin dall\'inizio. Spregevole.', 28153),
(157607, 'itIT', '', 'Una bugiarda!', 28153),
(157606, 'itIT', 'Un antico orrore degli abissi ha fatto la sua comparsa. Rispediscilo sotto le onde.', '', 28153),
(157605, 'itIT', '', 'Dama Bracescura è stata al mio fianco sin dal tempo in cui entrambe perdemmo i nostri mariti. Ora sarà al fianco del regno. Ora... lei è...', 28153),
(157603, 'itIT', '', 'Ma non è bastato.', 28153),
(157602, 'itIT', '', 'Ottimo! Le nostre forze potranno combattere sulla terraferma un altro giorno.', 28153),
(157601, 'itIT', 'L\'ultima volta che ho visto così tanto fumo, nonna Davenport stava cercando di insegnare a suo nipote come cucinare. Ottimo lavoro!', '', 28153),
(157600, 'itIT', '', 'Vergogna!', 28153),
(157599, 'itIT', '', 'I Naga hanno richiamato una macchina d\'assedio vivente per distruggere lo sbarramento! Alle armi!', 28153),
(157598, 'itIT', 'Pirati? I Marefiero non riescono nemmeno più a proteggerci dai pirati!', '', 28153),
(157597, 'itIT', '', 'Una flotta pirata ha distrutto i cancelli con forza travolgente...', 28153),
(157596, 'itIT', 'La furia della tempesta è imprevedibile e pericolosa, ma non ha speranze contro i tuoi talenti.', '', 28153),
(157595, 'itIT', 'Questo porta il marchio della magia dei Saggi delle Maree. Fai il possibile per contenerla!', '', 28153),
(157594, 'itIT', 'Noi continuiamo a colpirli, ma riescono a ricostruire più velocemente di quanto riusciamo a distruggere. Dobbiamo tagliare i loro rifornimenti di legna! Brucia tutto!', '', 28153),
(157593, 'itIT', '', 'Allora ciò che si dice è vero. I Cancelli di Daelin... sono caduti.', 28153),
(157592, 'itIT', 'Quelle esplosioni erano fortissime. È rimasto qualcosa oltre a un cumulo di macerie?', '', 28153),
(157591, 'itIT', '', 'Il raccolto è al sicuro, grazie a te. Vedremo se riusciremo a spostare quei piccoletti lontano dai campi coltivati.', 28153),
(157590, 'itIT', '', 'Ero più che sicura che ne sarebbe valsa la pena. Siamo fortunati ad averla al nostro fianco!', 28153),
(157589, 'itIT', '', 'Qualcosa sta mangiando i semi dei contadini locali prima che possano germogliare. Vedi se riesci a scoprire di cosa si tratta!', 28153),
(157588, 'itIT', '', 'Dama Davenport ha richiesto la consegna di alcuni oggetti per aiutare la campagna bellica. Quella vecchia signora è un tipo tosto. Sarebbe una follia rifiutarci di aiutarla!', 28153),
(157587, 'itIT', 'Continueremo a spazzar via la loro corruzione fin quando il Santuario della Tempesta non sarà finalmente puro.', '', 28153),
(157586, 'itIT', 'I demoni vogliono profanare i nostri luoghi più sacri. Non può succedere!', '', 28153),
(157585, 'itIT', '', 'So che la disinfestazione non è un lavoro nobile, ma il tuo intervento è stato assai apprezzato dalla gente di Borgo della Macina.', 28153),
(157584, 'itIT', '', 'Gli abitanti del Borgo della Macina sono stati colpiti da ogni genere di sfortuna. I loro magazzini di cibo sono infestati di parassiti. Aiutiamoli.', 28153),
(157583, 'itIT', 'Un giorno, i suoni gioiosi degli incantesimi dei Saggi delle Maree avvolgeranno di nuovo queste terre... ma non oggi.', '', 28153),
(157582, 'itIT', '', 'Speriamo che questo rispedisca quegli orrendi giganti tra le montagne, dove si meritano di essere!', 28153),
(157581, 'itIT', 'I tentacoli del mio vecchio maestro vanno ancora a fondo. Sradicane ogni traccia.', '', 28153),
(157580, 'itIT', 'Grazie. La gente della valle non dimenticherà mai le tue gesta.', '', 28153),
(157579, 'itIT', '', 'Gli Ettin stanno terrorizzando il Borgo della Macina e i civili non hanno modo di rispondere. Siamo la loro unica speranza!', 28153),
(157578, 'itIT', 'Abbiamo bisogno di te a Brennadam. Non abbiamo ancora abbastanza forze da organizzare un contrattacco.', '', 28153),
(157577, 'itIT', 'Parla col Capitano Angelica quando vuoi partire.', '', 28153),
(157576, 'itIT', '', 'Mi spiace, avrei dovuto chiederti se avevi l\'allergia alle api prima di mandarti in missione. A quanto pare però stai bene. Ora so a chi chiedere la prossima volta!', 28153),
(157575, 'itIT', 'Mi fa piacere vederti già di ritorno. Partirai insieme alla Terza Flotta.', '', 28153),
(157574, 'itIT', 'Una tale perfidia non deve essere lasciata libera di agire nel nostro mondo.', '', 28153),
(157573, 'itIT', '', 'Le api stanno terrorizzando di nuovo gli abitanti nei pressi della distilleria, e i contadini hanno perso il controllo della situazione. Sai che sorpresa!', 28153),
(157572, 'itIT', 'Mi ha mandato Re Anduin, Maestro delle Spie.', 'Mi ha mandata Re Anduin, Maestro delle Spie.', 28153),
(157571, 'itIT', '', 'In quella fattoria sta accadendo qualcosa che sta facendo infuriare i Wendigo. Se ne stavano in disparte prima che arrivassero quei pazzi dei Mildenhall.', 28153),
(157570, 'itIT', '', 'Abbiamo saputo che la Distilleria dei Mildenhall sta avendo qualche problema con i Wendigo. Credi di poter andare a dargli una mano?', 28153),
(157569, 'itIT', 'I K\'thir praticano indisturbati le loro arti oscure a bordo della Melodia Abissale. Spazza via la loro corruzione dal ponte della nave.', '', 28153),
(157568, 'itIT', 'Saremo anche in inferiorità numerica, ma grazie a te siamo ancora in piedi.', '', 28153),
(157567, 'itIT', 'I Saggi delle Maree caduti hanno schiavizzato dei marinai dispersi e intendono invadere Varcamarea. Ferma la loro avanzata!', '', 28153),
(157566, 'itIT', '', 'Un tempo quella creatura sarà stata certamente un Fungariano rispettabile. Che destino terribile per un guerriero così nobile.', 28153),
(157565, 'itIT', '', 'Stiamo ricevendo rapporti su una potente presenza all\'interno della caverna a sud. Fai attenzione. Le descrizioni di quella creatura mi fanno venire la pelle d\'oca...', 28153),
(157564, 'itIT', '', 'Ottimo lavoro, ma mi sa tanto che non sarà l\'ultima volta che ci toccherà salvargli la pelle...', 28153),
(157563, 'itIT', 'Non siamo ancora riusciti a scacciare l\'Orda dal passo. Colpisci le loro strutture di produzione, a qualsiasi costo. Fai saltare tutto in aria, se devi!', '', 28153),
(157562, 'itIT', '', 'Ogni arma che esce dalle fonderie dei Sacraonda dovrebbe servire a proteggere la gente, non a opprimerla.', 28153),
(157561, 'itIT', 'Sarà anche un compito semplice, data la tua esperienza... ma qualcuno lo deve pur fare.', '', 28153),
(157560, 'itIT', 'Il Rifugio dei Kennings non riesce a stare dietro agli ordini dell\'Ammiragliato a causa di alcune... complicazioni. Aiutarli sarà un gioco da ragazzi per te.', '', 28153),
(157559, 'itIT', '', 'Sarebbe un peccato se tutte quelle munizioni andassero sprecate. Sai cosa fare.', 28153),
(157558, 'itIT', 'È compito nostro tenerli sotto controllo, ora che la milizia non c\'è più.', '', 28153),
(157557, 'itIT', 'I Verrospino stanno combinando qualcosa nelle loro gallerie. Ferma i loro piani, prima che recuperino le forze!', '', 28153),
(157556, 'itIT', 'Nura, sono qui per aiutare.', 'Nura, sono qui per aiutare.', 28153),
(157555, 'itIT', '', 'Cosa ti porta fin da queste parti?', 28153),
(157554, 'itIT', 'Ci vediamo dopo nel villaggio per dividercelo!', '', 28153),
(157553, 'itIT', 'Puoi portarmi vicino all\'Altavia nelle Savane Meridionali?', 'Puoi portarmi vicino all\'Altavia nelle Savane Meridionali?', 28153),
(157552, 'itIT', 'Una nave senza vele è come un cavaliere senza cavallo. Non serve... davvero a niente.', '', 28153),
(157551, 'itIT', 'Una temibile tempesta minaccia i nostri magazzini. Trova un modo per calmarla!', '', 28153),
(157550, 'itIT', 'Hai reso giustizia all\'eredità di Addington. Grazie.', '', 28153),
(157549, 'itIT', 'Fratello Addington non avrebbe mai approvato una tale follia. Riconquista i cantieri in suo nome!', '', 28153),
(157548, 'itIT', '', 'Ogni cosa si crea a partire da materiali grezzi. Il resto è merito di duro lavoro e cuori sinceri.', 28153),
(157547, 'itIT', '', 'I carpentieri navali dei Sacraonda sono leggendari, ma hanno bisogno di legna per lavorare. Riporta subito l\'ordine!', 28153),
(157546, 'itIT', '', 'Questo gli farà capire che la valle sarà sempre aperta a tutti!', 28153),
(157545, 'itIT', '', 'Le forze di Ser Sacraonda hanno dato inizio a un nuovo embargo! Fai qualcosa per permettere ai commercianti di passare!', 28153),
(157544, 'itIT', 'Su, muoviti!', '', 28153),
(157543, 'itIT', 'Parla con Isabella. Si assicurerà che tu raggiunga il punto d\'incontro a Sepulcra in sicurezza.', '', 28153),
(157542, 'itIT', 'Una volta radunati abbastanza rinforzi, ti dirò cosa fare.', '', 28153),
(157541, 'itIT', 'Grazie per aver risposto così rapidamente. Non c\'è tempo da perdere.', '', 28153),
(157540, 'itIT', 'Proteggere, nutrire e guidare. Questa è la via dei Saggi delle Maree.', '', 28153),
(157539, 'itIT', 'Tutti i Saggi delle Maree fanno un patto sacro con la nostra gente. Aiutaci a mantenerlo e ad aiutare quelle povere anime!', '', 28153),
(157538, 'itIT', 'I nemici non conoscono tregua, ma grazie a te potremo combattere un altro giorno.', '', 28153),
(157537, 'itIT', 'Pare che il rituale sia fallito senza incidenti. L\'infame magia dei Naga non può continuare a corrompere i mari.', '', 28153),
(157536, 'itIT', 'I seguaci di Azshara stanno cercando di eseguire un nuovo rituale in seguito alla loro recente sconfitta. Rispediscili negli abissi che amano così tanto.', '', 28153),
(157535, 'itIT', '', 'I Naga sembrano farsi più aggressivi ogni giorno che passa. Non oso pensare cosa possa significare per noi.', 28153),
(157534, 'itIT', '', 'I Destatempesta stanno ancora recuperando le forze dall\'ultimo attacco dei Naga. Aiutali a difendere la zona fino a quando avranno tutto sotto controllo!', 28153),
(157533, 'itIT', 'Le nostre forze farebbero buon uso di queste risorse. Impadroniscitene per la nostra causa!', '', 28153),
(157532, 'itIT', 'Che le maree ti benedicano. Non ci porteranno via questa valle finché saremo in piedi!', '', 28153),
(157531, 'itIT', 'C\'è una prima volta per tutto, ma speriamo che non ci sia una seconda volta per quello.', '', 28153),
(157530, 'itIT', 'Mmm, non so bene cosa pensare, ma sta succedendo qualcosa di molto strano in città. Vedi se riesci a capirci qualcosa.', '', 28153),
(157529, 'itIT', '', 'Se abbandoni i tuoi sentimenti, rimarrà solo una vuota oscurità.', 28153),
(157528, 'itIT', '', 'Tesoro mio... non può essere la sola ragione a determinare le tue scelte.', 28153),
(157527, 'itIT', '', 'Non è reale, Jaina! Nulla di tutto questo lo è!', 28153),
(157526, 'itIT', '', 'Ma... mi hanno mentito...', 28153),
(157525, 'itIT', 'Sono stato uno stupido a pensare che tu potessi guidarci!', '', 28153),
(157524, 'itIT', 'Hai lasciato che i tuoi pregiudizi corrompessero il Kirin Tor!', '', 28153),
(157523, 'itIT', '', 'Vorrei che anche tuo padre avesse imparato quella lezione.', 28153),
(157522, 'itIT', '', 'Cercare di porre fine a un massacro è una nobile azione, Jaina.', 28153),
(157521, 'itIT', 'Le armate di Ser Sacraonda minacciano di riconquistare questa zona. Assicurati che non cada nelle loro mani.', '', 28153),
(157520, 'itIT', '', 'Allontanatevi da lei!', 28153),
(157519, 'itIT', 'Hir\'eek è il Loa della Notte. Nun serve che tu sappia altro.', 'Hir\'eek è il Loa della Notte. Nun serve che tu sappia altro.', 28153),
(157518, 'itIT', '', 'È stata tutta colpa mia...', 28153),
(157517, 'itIT', 'Ma tu... Tu hai fermato la mia spada. Quanti soldati dell\'Alleanza sono morti quel giorno? E in tutte le battaglie che sono seguite?', '', 28153),
(157516, 'itIT', 'Avrei potuto ucciderli tutti! Sylvanas... Thrall... Pensa a come sarebbe stato il nostro mondo senza di loro e senza la loro Orda corrotta!', '', 28153),
(157515, 'itIT', '', 'No. Dev\'essere un\'altra di quelle creature che tormentano Jaina. Sbrighiamoci!', 28153),
(157514, 'itIT', '', 'Quella voce... Daelin?!?', 28153),
(157513, 'itIT', '', 'Un\'altra illusione? Jaina dev\'essere ancora intrappolata nelle vicinanze.', 28153),
(157512, 'itIT', '', 'La troveremo... e la libereremo da questo posto maledetto.', 28153),
(157511, 'itIT', '', 'Mia figlia è qui da qualche parte. Nascosta. Sofferente.', 28153),
(157510, 'itIT', 'Ottimo combattimento! Le correnti porteranno le storie delle tue gesta in ogni angolo del mondo.', '', 28153),
(157509, 'itIT', '', 'Dobbiamo continuare la nostra ricerca.', 28153),
(157508, 'itIT', '', 'Se n\'è andata. Quella bambina era solo un riflesso... un\'eco della sofferenza di Jaina.', 28153),
(157507, 'itIT', '', 'Ma neanche il più forte tra noi può salvare tutti.', 28153),
(157506, 'itIT', '', 'Jaina... tu eri... sei... l\'orgoglio di Kul Tiras. Il suo potere e la sua furia...', 28153),
(157505, 'itIT', '', 'No! Non ascoltarli, Jaina!', 28153),
(157504, 'itIT', '', 'Li ho delusi... tutti quanti...', 28153),
(157503, 'itIT', '', 'Avresti potuto fermarlo! Avresti potuto salvarci!', 28153),
(157502, 'itIT', 'A rapporto, Gran Supremo.', 'A rapporto, Gran Supremo.', 28153),
(157501, 'itIT', 'I Destatempesta richiedono il tuo aiuto ancora una volta. Che le maree ti guidino alla vittoria.', '', 28153),
(157500, 'itIT', 'Ci hai lasciati qui a morire!', '', 28153),
(157499, 'itIT', '', 'Fai strada, $p.', 28153),
(157498, 'itIT', '', 'Allora la trovavo sempre... e lo farò anche stavolta.', 28153),
(157497, 'itIT', '', 'Quando Jaina era bambina, si nascondeva ogni volta che era triste o spaventata.', 28153),
(157496, 'itIT', '', 'Aspetta!', 28153),
(157495, 'itIT', '', 'No! Non puoi aiutarmi! Nessuno può farlo!', 28153),
(157494, 'itIT', '', 'Va tutto bene, cara...', 28153),
(157493, 'itIT', '', 'Jaina è poco più avanti. Sbrighiamoci!', 28153),
(157492, 'itIT', 'Thros... vi consumerà...', '', 28153),
(157491, 'itIT', '', 'Non se ho qualcosa da dire!', 28153),
(157490, 'itIT', 'La figlia di Marefiero è nostra!', '', 28153),
(157489, 'itIT', '', 'Dobbiamo seguirla!', 28153),
(157488, 'itIT', '', 'Jaina, aspetta!', 28153),
(157487, 'itIT', '', 'No! Vai via!', 28153),
(157486, 'itIT', '', 'Jaina?!?', 28153),
(157485, 'itIT', '', 'È... tutta colpa mia...', 28153),
(157484, 'itIT', '', 'Le Terre Ammorbate... Questo posto certamente rispecchia il suo nome.', 28153),
(157483, 'itIT', 'Che le maree ti benedicano. La nostra valle è di nuovo al sicuro.', '', 28153),
(157482, 'itIT', 'Per le profondità abissali... quest\'aberrazione non deve più minacciare la nostra gente!', '', 28153),
(157481, 'itIT', 'Che serva da lezione per chi possiede i doni della Madre delle Maree.', '', 28153),
(157480, 'itIT', 'Un tale disdegno del potere del mare non può essere tollerato.', '', 28153),
(157479, 'itIT', 'Torga è un potente essere, spesso sottovalutato. Ma noi Tortolliani teniamo viva la sua memoria.', '', 28153),
(157478, 'itIT', 'Fermiamoci qui un secondo, $p.', '', 28153),
(157477, 'itIT', 'Gral è nu Loa saggio. Tiene na visione totale su ogni cosa. Il mare più profondo è dove regna e chello più buio è dove domina.', 'Gral è nu Loa saggio. Tiene na visione totale su ogni cosa. Il mare più profondo è dove regna e chello più buio è dove domina.', 28153),
(157476, 'itIT', 'Che le maree li respingano, come essi hanno fatto con la loro gente.', '', 28153),
(157475, 'itIT', 'Parecchie spine in meno nel nostro fianco! Eheheh! Ottimo lavoro.', '', 28153),
(157474, 'itIT', 'I Verrospino stanno progettando qualcosa alla fattoria poco fuori dalle loro gallerie. Perché non fai un salto lì per porre fine ai loro progetti?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157473, 'itIT', 'Un\'altra anima dannata ha risposto alla chiamata di Ser Sacraonda. Non deve rovinare il nostro lavoro!', '', 28153),
(157472, 'itIT', 'Ora riposa, miserabile anima. Non soffrirai più.', '', 28153),
(157471, 'itIT', 'Quali orrori ha portato la mia gente... Poni fine alla sofferenza di questa creatura.', '', 28153),
(157470, 'itIT', 'Allora vado...', 'Allora vado...', 28153),
(157469, 'itIT', 'Shì... shignore.', 'Shì... shignore.', 28153),
(157468, 'itIT', 'Cosha c\'è?', 'Cosha c\'è?', 28153),
(157467, 'itIT', 'Allora vado!', 'Allora vado!', 28153),
(157466, 'itIT', 'Altro lavoro?', 'Altro lavoro?', 28153),
(157465, 'itIT', '', 'Ci penso io, capo!', 28153),
(157464, 'itIT', 'Vedo un altro piccolo scavo a ovest di qui. Kelsey?', '', 28153),
(157463, 'itIT', 'Rimanete uniti. Non siamo venuti fin qui per fallire!', '', 28153),
(157462, 'itIT', 'Gli scavi più grandi del Circolo del Reliquiario si trovano a sud. Come sospettavo.', '', 28153),
(157461, 'itIT', 'L\'Orda ha dato alle fiamme gli edifici! Estinguile prima che tutta la valle vada a fuoco!', '', 28153),
(157460, 'itIT', 'Ottimo lavoro! Le fiamme recedono e le nostre case sono ancora in piedi. Grazie.', '', 28153),
(157459, 'itIT', 'Mi assicurerò che i Sethrak non si portino dietro neanche una briciola di bottino quando se ne andranno.', 'Mi assicurerò che i Sethrak non si portino dietro neanche una briciola di bottino quando se ne andranno.', 28153),
(157458, 'itIT', 'Anche se non posso riportare a casa i nostri marinai, sappiamo che quelle navi sono là fuori da qualche parte. Il loro destino è ora nelle mani dei Marefiero.', '', 28153),
(157457, 'itIT', 'Jani è il Loa di tutto ciò che è rifiutato e di chiunque sia esiliato o ignorato. Egli veglia sulli orfani come me e su chiunque sia costretto a vivere nella sfortuna.', '', 28153),
(157456, 'itIT', 'Qui la mia magia è più forte. Se c\'è una speranza di ritrovare la flotta, questo è il momento per provarci.', '', 28153),
(157455, 'itIT', 'Ehm... Vattene... Hic! Shono occupato.', '', 28153),
(157454, 'itIT', 'Noi siamo seguaci di Torcali, la Montagna Vivente, il Baluardo Errante. Grazie a lui, nulla può infrangere li scudi nostri.', '', 28153),
(157453, 'itIT', '', 'Una minaccia in meno nella valle! Ben fatto!', 28153),
(157452, 'itIT', '', 'Accidenti... sono senza parole. È stato un combattimento pazzesco!', 28153),
(157451, 'itIT', 'Aspetta qui. Credo di aver visto qualcosa.', '', 28153),
(157450, 'itIT', 'Non credevo avrebbe funzionato, ma quell\'oro aiuterà un sacco di gente a ripartire con la propria vita!', '', 28153),
(157449, 'itIT', 'Sì... percepisco le navi... la nostra flotta! Le nebbie oscure che l\'avvolgono si stanno dissipando!', '', 28153),
(157448, 'itIT', 'Sono qui per risolvere i tuoi problemi, Krog.', 'Sono qui per risolvere i tuoi problemi, Krog.', 28153),
(157447, 'itIT', '', 'Dei Destatempesta hanno avvistato una pericolosa bestia nelle vicinanze. Scommetto che riuscirai a occupartene facilmente!', 28153),
(157446, 'itIT', '', 'Una pericolosa creatura si aggira sulle colline. Trovala prima che faccia del male a qualcuno.', 28153),
(157445, 'itIT', 'I cacciatori di tesori a Flussomorto doneranno delle monete d\'oro per aiutare a ricostruire Brennadam. La fregatura è che dovremo recuperare quell\'oro con le nostre mani!', '', 28153),
(157444, 'itIT', 'Arthur...', '', 28153),
(157443, 'itIT', 'Doras, mi serve una Viverna dei Venti per raggiungere Felcimura.', 'Doras, mi serve una Viverna dei Venti per raggiungere Felcimura.', 28153),
(157442, 'itIT', '', 'Ben fatto. Salvando Ai\'twen, hai aiutato i Tortolliani... e compiaciuto pure i Loa, almeno credo.', 28153),
(157441, 'itIT', 'Ehi, ho distrutto delle pietre! Delle pietre molto arrabbiate.', '', 28153),
(157440, 'itIT', 'I tuoi ordini erano di distruggere i cairn.', '', 28153),
(157439, 'itIT', 'Oh, andiamo! Alla fine è andato tutto bene. Io e $gil continentale:la continentale; abbiamo abbattuto quel mostro di rocce e siamo sopravvissuti! Direi che è una vittoria.', '', 28153),
(157438, 'itIT', 'Arthur! Cosa ti avevo detto a proposito di non gettarti a capofitto nelle cose?', '', 28153),
(157437, 'itIT', '', 'I Tortolliani venerano la grande tartaruga Ai\'twen, nu potente alleato del passato loro. Tienila al sicuro e ben nutrita, così potrà aiutarci ancora na volta.', 28153),
(157436, 'itIT', 'Via di qua!', '', 28153),
(157435, 'itIT', 'Che le correnti ti guidino! Le tue azioni saranno un esempio per tutti.', '', 28153),
(157434, 'itIT', 'Continueremo verso sud, allora. Ci terremo in contatto, Guzbert.', '', 28153),
(157433, 'itIT', 'Ce la puoi fare, Guzzy!', '', 28153),
(157432, 'itIT', '', 'Valli a prendere, Guzbert!', 28153),
(157431, 'itIT', 'Con una VAGONATA DI BOMBE!', '', 28153),
(157430, 'itIT', 'Piccolo scavo, eh? Sembra proprio un lavoro adatto a uno Gnomo...', '', 28153),
(157429, 'itIT', 'C\'è un piccolo scavo del Circolo del Reliquiario a circa mezzo chilometro da qui.', '', 28153),
(157428, 'itIT', '$n, dietro di te! Aiutami a sbarazzarmi di queste seccature.', '', 28153),
(157427, 'itIT', 'L\'antica tartaruga Ai\'twen è un mistero dei mari che va difeso. Aiuta i Tortolliani a tenerla al sicuro e ben nutrita.', '', 28153),
(157426, 'itIT', 'Faremo pagare a Ser Sacraonda le sue trasgressioni... o moriremo provandoci.', '', 28153),
(157425, 'itIT', 'La gente di Sacraonda merita di sentirsi al sicuro. Non mostrare alcuna pietà a chiunque minacci il loro benessere.', '', 28153),
(157424, 'itIT', 'Dobbiamo agire subito per evitare che la flotta cada nella morsa di Azshara.', '', 28153),
(157423, 'itIT', 'Qui non siamo al sicuro. Vieni, c\'è un vecchio posto di guardia che sovrasta il santuario qui vicino.', '', 28153),
(157422, 'itIT', 'Ma non sarà dimenticato, non fintanto che ci saremo noi.', '', 28153),
(157421, 'itIT', '<La voce ora echeggia insieme alla tua. Senti che è in cerca di una risposta, perché la stai cercando anche tu.>\n\n\"A quale scopo?\"', '', 28153),
(157420, 'itIT', '<Ti contorci di dolore mentre la voce urla dentro di te.>\n\n\"Da dov\'è iniziato tutto?\"', '', 28153),
(157419, 'itIT', 'Ti ringrazio. I contadini dovrebbero riuscire a tornare ai loro campi molto presto.', '', 28153),
(157418, 'itIT', 'Ho ricevuto rapporti preoccupanti dalle fattorie nei dintorni. Ti prego, aiuta a riportare l\'ordine nella valle!', '', 28153),
(157417, 'itIT', '<La voce si fa più forte e intensa.>\n\n\"Ancora! Ancora! Ancora!\"', '', 28153),
(157416, 'itIT', '<La voce antica è ora solo un\'eco, che ti sta chiamando dalle profondità della mente.>\n\n\"Cosa stai cercando?\"', '', 28153),
(157415, 'itIT', 'Sei davvero una sorpresa continua! Mi devi insegnare qualche trucchetto uno di questi giorni.', '', 28153),
(157414, 'itIT', 'Ottimo lavoro. Se avrai bisogno di andartene da Boralus, abbiamo degli agenti nelle vicinanze.', '', 28153),
(157413, 'itIT', 'Tornerò indietro e avviserò Betulla. Ci vediamo lì!', '', 28153),
(157412, 'itIT', 'Ah! È $gcrollato:crollata; di fronte alla nostra forza!', '', 28153),
(157411, 'itIT', '', 'Sam... lui è... è morto...', 28153),
(157410, 'itIT', 'Quando l\'ultimo dei suoi sottoposti sarà stato ucciso e rianimato come Reietto, il Re moccioso si inginocchierà dinnanzi alla Dama Oscura. Allora, finalmente, ci sarà una sola Regina a comandarli tutti.', '', 28153),
(157409, 'itIT', 'Vendetta. Disprezzo. Chiamalo come vuoi.', '', 28153),
(157408, 'itIT', '', 'Ah, sei mosso dalla vendetta. Capisco.', 28153),
(157407, 'itIT', 'Quando il controllo del Re dei Lich su di noi venne meno, Sylvanas cercò degli alleati. Invece di aiutare i loro caduti di Lordaeron, gli Umani ci diedero la caccia. Così decisi che sarei stato io a dare la caccia a loro.', '', 28153),
(157406, 'itIT', '', 'Voltato le spalle?', 28153),
(157405, 'itIT', 'Un tempo ho combattuto per la loro causa. L\'intollerabile arroganza dell\'Alleanza è aumentata a dismisura da quando ci hanno voltato le spalle.', '', 28153),
(157404, 'itIT', '', 'Lo zelo con cui attacchi l\'Alleanza non sembra nascere da un semplice rispetto per la tua Regina, Selvamorta.', 28153),
(157403, 'itIT', '', 'Ho causato la caduta di un re. Forse è ora che io metta fine al regno di un altro.', 28153),
(157402, 'itIT', 'Bene. L\'Alleanza non merita simpatie. Non dar loro tregua. Falli soffrire e la Dama Oscura ti ricompenserà a dovere.', '', 28153),
(157401, 'itIT', '', 'No. E di sicuro sai anche che ho collaborato con l\'Alleanza quando era utile ai miei scopi. Ma non devo loro niente. È l\'Orda la mia casa.', 28153),
(157400, 'itIT', 'Siete solo degli stolti...', '', 28153),
(157399, 'itIT', 'Nel nome di Kul Tiras, vattene da questo posto!', '', 28153),
(157398, 'itIT', 'Conosco la storia. Ma so anche che non è stata una tua scelta quella di uccidere Re Llane Wrynn.', '', 28153),
(157397, 'itIT', '', 'Solo perché un tempo ero amica del nonno del giovane Re? L\'ho assassinato, se ben ricordi.', 28153),
(157396, 'itIT', 'I tuoi attacchi ai bersagli dell\'Alleanza sono stati notevoli, Garona. Ammetto di aver avuto dei dubbi circa la tua... lealtà.', '', 28153),
(157395, 'itIT', 'Eheheh... Carne Fresca!', '', 28153),
(157394, 'itIT', 'Assaggia la furia della natura!', '', 28153),
(157393, 'itIT', 'Ti renderò poltiglia!', '', 28153),
(157392, 'itIT', 'Vuoi davvero continuare?', 'Vuoi davvero continuare?', 28153),
(157391, 'itIT', 'Ottimo lavoro. La Valle dei Sacraonda ti deve più di quanto potremo mai ripagarti.', '', 28153),
(157390, 'itIT', 'Sogna, sogna la Città Sommersa.', 'Sogna, sogna la Città Sommersa.', 28153),
(157389, 'itIT', 'Ritrovati nell\'oscurità del suo sguardo...', 'Ritrovati nell\'oscurità del suo sguardo...', 28153),
(157388, 'itIT', 'Persi nel Suo abbraccio eterno...', 'Persi nel Suo abbraccio eterno...', 28153),
(157387, 'itIT', 'Per respirare la saggezza degli annegati...', 'Per respirare la saggezza degli annegati...', 28153),
(157386, 'itIT', 'I sopravvissuti al Rifugio dei Colli Infausti stanno combattendo da giorni. Vedi se riesci ad aiutarli e dai loro l\'occasione di riposare.', '', 28153),
(157383, 'itIT', 'Sono esplose un bel po\' di cose! Mi fa piacere sapere che tu e Toki non eravate tra queste.', '', 28153),
(157382, 'itIT', 'Dissetati con la marea scintillante...', 'Dissetati con la marea scintillante...', 28153),
(157381, 'itIT', 'La S.P.R. & Co. non fa che distruggere le coste. Incontrati con Toki e vedi se riesci ad aiutarlo.', '', 28153),
(157380, 'itIT', 'Ehm...', 'Ehm...', 28153),
(157379, 'itIT', '<Hai trovato uno strano altare. Appena vi poni la mano sopra, delle parole iniziano a scorrere nella tua mente.>\n\n\"Come intendi iniziare?\"', '', 28153),
(157378, 'itIT', 'Ottimo lavoro. Ti devo una birra!', '', 28153),
(157377, 'itIT', 'Aspetta che ti metta gli artigli addosso!', '', 28153),
(157376, 'itIT', 'Ti farò a pezzi!', '', 28153),
(157375, 'itIT', 'Voglio che i Marferreo se ne vadano da qui. Vediamo se vorranno ancora rimanere quando avremo reso la loro vita più difficile.', '', 28153),
(157374, 'itIT', 'Per Drustvar!', '', 28153),
(157373, 'itIT', 'Andiamo! Trasformiamo quel mostro in macerie!', '', 28153),
(157372, 'itIT', '', 'I Tortolliani ti ringraziano per l\'aiuto, e pure io.', 28153),
(157371, 'itIT', '', 'Chei bruti della S.P.R. & Co. continuano a infastidire i Tortolliani! Incontrati con Toki e aiutali.', 28153),
(157370, 'itIT', '', 'I nemici nostri si ricorderanno di chi ha posto fine ai piani loro. Ben fatto.', 28153),
(157369, 'itIT', '', 'I nemici nostri si fanno più audaci ogni giorno che passa! Privali delle risorse... e pure delle vite loro, se necessario.', 28153),
(157368, 'itIT', '', 'Mentre i nemici nostri si fanno più deboli, noi diventiamo più forti. A volte, piccole vittorie portano a nu trionfo più grande.', 28153),
(157367, 'itIT', '', 'I soldati nun possono vincere alcuna guerra con la pancia vuota. La carne d\'orso terrà ben nutrite le forze nostre. Nun lasciare che i nemici interferiscano.', 28153),
(157362, 'itIT', 'Antiche creature che non dovrebbero esistere si stanno destando. Sta\' in guardia.', 'Antiche creature che non dovrebbero esistere si stanno destando. Sta\' in guardia.', 28153),
(157361, 'itIT', 'Non ci aspettavamo che i morti camminassero!', 'Non ci aspettavamo che i morti si alzassero e iniziassero a camminare!', 28153),
(157360, 'itIT', 'Non ci aspettavamo un tale potere! Fai attenzione, continentale.', 'Non ci aspettavamo un tale potere! Fai attenzione, continentale.', 28153),
(157359, 'itIT', 'I costrutti devono essere distrutti. Aiutaci!', 'I costrutti devono essere distrutti. Aiutaci!', 28153),
(157358, 'itIT', 'Proprio al momento giusto, continentale.', 'Proprio al momento giusto, continentale.', 28153),
(157357, 'itIT', '$p, fermati. Lo vedi quello?', '', 28153),
(157356, 'itIT', 'Per ora sono stati respinti e il villaggio è ancora in piedi. Ti dobbiamo le nostre vite.', '', 28153),
(157355, 'itIT', 'L\'Orda è tornata in forze per finire il lavoro. Fermali con ogni mezzo necessario!', '', 28153),
(157354, 'itIT', 'Di solito se ne sta per i fatti suoi... ma capisce bene quando si trova nei guai. Grazie per averlo aiutato.', '', 28153),
(157353, 'itIT', 'Terraricca dice che gli farebbe comodo il tuo aiuto. Le incursioni alla sua fattoria continuano ed è ormai a corto di rifornimenti. Dagli tutto il supporto possibile.', '', 28153),
(157352, 'itIT', 'Adesso ci penseranno due volte prima di riprovarci! Fai un grattino in più a quel cane da parte mia.', '', 28153),
(157351, 'itIT', 'I Verrospino stanno cercando di espandere la loro rete di gallerie, mettendo in pericolo l\'intera valle. I nostri mastini possono rintracciarli seguendone l\'odore.', '', 28153),
(157350, 'itIT', '$p, muoviamoci.', '', 28153),
(157349, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Sei sotto l\'effetto di |cFFFF0000|Hspell:272536|h[Rovina Imminente]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_SHADOWFURY.BLP:20|t Sei sotto l\'effetto di |cFFFF0000|Hspell:272536|h[Rovina Imminente]|h|r!', 28153),
(157348, 'itIT', 'Chesta stanza sarebbe perfetta per mettere in mostra la collezione di antichità reale. Forse dovre...', '', 28153),
(157347, 'itIT', '', 'Non sarò molto lontana.', 28153),
(157346, 'itIT', 'Shandris, mantieni un basso profilo. Rimani nell\'ombra... se ne trovi.', '', 28153),
(157345, 'itIT', '', '10-4, Gran Comandante! Andiamo!', 28153),
(157344, 'itIT', 'Kelsey, tu sei i nostri occhi in cielo. Avvisaci se dovessi vedere qualcosa.', '', 28153),
(157343, 'itIT', 'Puoi ripetere il piano?', 'Puoi ripetere il piano?', 28153),
(157342, 'itIT', 'I miei genitori dicevano sempre che avevo troppa immaginazione.', '', 28153),
(157341, 'itIT', 'A volte ci lanciavamo giù dalle colline della valle con un carretto! Facevamo finta che Hobbs fosse una tigre! Eheh.', '', 28153),
(157340, 'itIT', 'Hobbs e io ci fiondavamo in ogni genere di avventura da piccoli.', '', 28153),
(157339, 'itIT', 'Mostrami.', 'Mostrami.', 28153),
(157338, 'itIT', 'Le visioni possono aiutarci a osservare il massacro, $R.', 'Le visioni possono aiutarci a osservare il massacro, $R.', 28153),
(157337, 'itIT', 'Presto anche la flotta si crogiolerà nella sua luce e tutta Kul Tiras si inchinerà al potere che si nasconde sotto le maree.', '', 28153),
(157336, 'itIT', 'Siete ciechi. I doni della Madre delle Maree ci hanno reso forti ancora una volta.', '', 28153),
(157335, 'itIT', 'Anime dei corrotti, manterrete fede al vostro giuramento. Abbattete questo cancello!', '', 28153),
(157334, 'itIT', '', '|TINTERFACE\\ICONS\\INV_TikiMan2_Bloodtroll.blp:20|t L\'Anziana Leaxa inizia a lanciare |cFFF00000|Hspell:264603|h[Specchio di Sangue]|h|r!', 28153),
(157333, 'itIT', '', 'Ho un buon presentimento su questa caverna. Mi sto immaginando un sacco d\'oro all\'interno.', 28153),
(157332, 'itIT', 'Ma stavo giusto arrivando alla parte in cui mi sono infilato nella sua gola e l\'ho fatta a pezzi dall\'interno!', 'Ma stavo giusto arrivando alla parte in cui mi sono infilata nella sua gola e l\'ho fatta a pezzi dall\'interno!', 28153),
(157331, 'itIT', 'Va bene, va bene, Line e Piombo hanno aiutato. Ma tutto il resto è vero... lo giuro!', 'Va bene, va bene, Line e Piombo hanno aiutato. Ma tutto il resto è vero, eh... lo giuro!', 28153),
(157330, 'itIT', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff, mmmpfff, mmmpfff!', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff, mmmpfff, mmmpfff!', 28153),
(157329, 'itIT', 'Chiudi la bocca, Line. Aspetta il tuo turno!', 'Chiudi il becco, Line. Aspetta il tuo turno!', 28153),
(157328, 'itIT', '', 'Niente oro, ma un sacco di rum!', 28153),
(157327, 'itIT', 'Esatto, con la mia grande abilità di pescatore!', 'Esatto, con la mia grande abilità di pescatore!', 28153),
(157326, 'itIT', 'Grazie alla mia astuzia, ho capito immediatamente come affrontarla.', 'Grazie alla mia astuzia, capii immediatamente come affrontarla.', 28153),
(157325, 'itIT', 'Poi la vidi avvicinarsi all\'orizzonte. Una bestia come non ne avevo mai viste prima!', 'Poi la vidi avvicinarsi all\'orizzonte. Una bestia come non ne avevo mai viste prima!', 28153),
(157324, 'itIT', 'Avevo il primo turno di guardia ed ero occupato a tenere d\'occhio quei maledetti Naga.', 'Avevo il primo turno di guardia e dovevo tenere d\'occhio quei maledetti Naga.', 28153),
(157323, 'itIT', 'Ora lascia che ti racconti come ho conosciuto quei due marinai.', 'Ora lascia che ti racconti come ho conosciuto quei due marinai.', 28153),
(157322, 'itIT', 'Già, concordo anch\'io... Ehi, aspetta un momento!', 'Già, concordo... Ehi, aspetta un momento!', 28153),
(157321, 'itIT', 'Quell\'elmo ti ha dato alla testa. Crederei più al fatto che Line sia riuscito a prendere davvero un pesce!', 'Quell\'elmo ti ha dato alla testa. Crederei più al fatto che Line sia riuscito a prendere davvero un pesce!', 28153),
(157320, 'itIT', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff, mmmpfff. Mmmpfff.', 'Mmmpfff, mmmpfff, mmmpfff. Mmmpfff, mmmpfff. Mmmpfff.', 28153),
(157319, 'itIT', 'MPF!!!', 'MPF!!!', 28153),
(157318, 'itIT', 'Mmmpfff... mmmpfff.', 'Mmmpfff... mmmpfff.', 28153),
(157317, 'itIT', 'Per fortuna, avevo un proiettile speciale che mi porto sempre al collo per questo genere di occasioni.', 'Per fortuna, avevo un proiettile speciale che mi porto sempre al collo per queste occasioni.', 28153),
(157316, 'itIT', 'Sto di guardia al rum fino al ritorno del Capitano.', '', 28153),
(157315, 'itIT', 'Capitano... io non ho bevuto niente.', '', 28153),
(157314, 'itIT', '', 'Dove ci sono pirati, di solito c\'è anche l\'oro!', 28153),
(157313, 'itIT', '', 'Alcuni dei lavoratori hanno detto di aver visto una nave pirata vicino alla caverna.', 28153),
(157312, 'itIT', '', 'Brennadam è poco più avanti. Andiamo!', 28153),
(157311, 'itIT', '', 'Tutta Kul Tiras è indifesa senza di essa ed è solo una questione di tempo prima che ci attacchino.', 28153),
(157310, 'itIT', '', 'Dobbiamo trovare Fratello Pike immediatamente. Forse potrebbe aiutarci a riportare la flotta a casa.', 28153),
(157309, 'itIT', '', 'Non è magnifica questa valle? Ora capisco perché in così tanti decidono di sistemarsi qui.', 28153),
(157308, 'itIT', '', 'Questo passo è l\'unica via che porta alla valle. La Casata dei Sacraonda sta progettando qualcosa.', 28153),
(157307, 'itIT', '', 'Brennadam è il più grande nodo commerciale di Kul Tiras, all\'infuori di Boralus.', 28153),
(157306, 'itIT', 'Datevi da fare, inutili sacchi di carne!', 'Datevi da fare, inutili sacchi di carne!', 28153),
(157305, 'itIT', 'È quassù. Due teste... e belle grosse!', 'È lassù e si sta preparando ad attaccare!', 28153),
(157304, 'itIT', 'Fatti gli affari tuoi. Sono in vesti ufficiali!', 'Fatti gli affari tuoi. Sono in vesti ufficiali!', 28153),
(157303, 'itIT', 'Cosa stai combinando? Devi evacuare insieme a noi!', 'Cosa stai combinando? Devi evacuare insieme a noi!', 28153),
(157302, 'itIT', 'Attenzione a quella mazza!', 'Sarà meglio correre, Tom. Abbiamo ciò che ci serve!', 28153),
(157301, 'itIT', 'Tutto questo... è per colpa tua.', 'Tutto questo... è per colpa tua.', 28153),
(157300, 'itIT', 'Affrontami... entrambi!', 'Affrontami... entrambi!', 28153),
(157299, 'itIT', 'Io prendo la testa a destra.', 'È più grosso di quanto pensassi.', 28153),
(157298, 'itIT', 'Ispezione', 'Ispezione', 28153),
(157296, 'itIT', 'Bentornati, piccoli amici. Ascoltate questa nuova canzone che ho imparato!', '', 28153),
(157294, 'itIT', 'Tu schiatta, poi schiaccio tutto il villaggio!', 'Tu schiatta, poi schiaccio tutto il villaggio!', 28153),
(157293, 'itIT', 'I Destatempesta guideranno la flotta alla vittoria per l\'Alleanza, come abbiamo già fatto in passato.', '', 28153),
(157292, 'itIT', '', 'La Casata dei Crestabianca è con te, Ammiraglio Supremo, e con l\'Alleanza.', 28153),
(157291, 'itIT', '', 'E di rinnovare il nostro legame con l\'Alleanza, i cui eroi ci hanno salvato dall\'estinzione.', 28153),
(157290, 'itIT', '', 'Ora vi chiedo di riporre la vostra fiducia in mia figlia, Jaina... il vero Ammiraglio Supremo di Kul Tiras.', 28153),
(157289, 'itIT', '', 'Anche l\'Orda ha reso chiare le sue intenzioni. Quei selvaggi vogliono vederci bruciare.', 28153),
(157288, 'itIT', '', 'Le divisioni ci hanno reso vulnerabili. I nostri nemici si nascondono in mezzo a noi.', 28153),
(157287, 'itIT', '', 'Grazie a tutti per essere venuti. Cercherò di essere breve.', 28153),
(157286, 'itIT', 'Scommetto che noi due potremmo far fuori quei mostri!', '', 28153),
(157285, 'itIT', 'Quando Daelin mi chiese di lasciare la sua guardia e crescere questa ragazzina dei Regni Orientali, all\'inizio non ne capii il motivo.\n\nPerché affidarmi questo fardello? Perché negarmi l\'onore di combattere al suo fianco? Credetti di aver fatto qualcosa che gli avesse fatto perdere la sua fiducia in me.\n\nCol passare degli anni, capii che era l\'esatto opposto. Voleva che Taelia crescesse forte e con un cuore nobile ed era convinto che potessi aiutarla a riuscirci.', '', 28153),
(157284, 'itIT', '', 'È vero che si può raggiungere Forgiardente da Roccavento con una specie di treno sotterraneo?$B$BSembra incredibile! Un giorno vorrei vederlo.', 28153),
(157283, 'itIT', 'E ne abbiamo usata soltanto un pizzico! Immaginate i danni che potrebbero causare usandone di più.', '', 28153),
(157282, 'itIT', '', 'Grazie. Ora la gente del posto potrà finalmente tornare a lavorare nei campi.', 28153),
(157281, 'itIT', '', 'C\'è una creatura nelle vicinanze che minaccia i contadini locali. Dobbiamo aiutarli!', 28153),
(157280, 'itIT', '', 'Eccellente! Scommetto che troveranno facilmente un modo per sfruttarle.', 28153),
(157279, 'itIT', '', 'Un giorno, i cittadini di Kul Tiras torneranno a fidarsi della guida dei Saggi delle Maree, ma fino ad allora, dobbiamo seguire la nostra strada.', 28153),
(157278, 'itIT', '', 'Questo dovrebbe darci un po\' di respiro. Grazie.', 28153),
(157277, 'itIT', '', 'La gente di Sacraonda non dimenticherà le tue azioni. Ottimo lavoro!', 28153),
(157276, 'itIT', '', 'Queste colline sono ricche di risorse molto importanti per gli sforzi dei Destatempesta. Forse potresti aiutarli.', 28153),
(157275, 'itIT', '', 'Le forze di Ser Sacraonda stanno causando di nuovo problemi. Non possiamo permettere che i loro rituali continuino!', 28153),
(157274, 'itIT', '', 'Abbiamo perso il controllo della zona! Vai lì e respingi il nemico!', 28153),
(157273, 'itIT', '', 'I Destatempesta hanno bisogno di assistenza. Fai il possibile per riportare un po\' di pace in questa valle!', 28153),
(157272, 'itIT', '', 'Cannonieri! Preparate la raffica finale!', 28153),
(157271, 'itIT', '', 'Tenete in piedi lo scudo! Riusciamo a malapena a tenerla in piedi!', 28153),
(157270, 'itIT', 'Un\'altra dei Reietti. Forse è un <Tossisce> segno. Dimmi, Dama...?', '', 28153),
(157269, 'itIT', '<Tossisce> L\'Orda. Pensavo che qui sarei morto in pace.\n\nTu sei $gun Reietto:una Reietta;? Interessante, ma è troppo tardi.\n\nBe\', cosa stai aspettando?', '', 28153),
(157268, 'itIT', 'Ci rivediamo alla carovana, $p!', '', 28153),
(157267, 'itIT', '', 'Uooo! È ora di depredare!', 28153),
(157266, 'itIT', 'Per favore riportami indietro.', 'Per favore riportami indietro.', 28153),
(157265, 'itIT', 'Grazie per l\'aiuto. Dovremmo tornare indietro.', 'Grazie per l\'aiuto. Dovremmo tornare indietro.', 28153),
(157264, 'itIT', '<Osserva l\'incontro tra Zelling e la sua famiglia.>', '<Osserva l\'incontro tra Zelling e la sua famiglia.>', 28153),
(157263, 'itIT', 'Un lavoro fantastico, come sempre. Se tutti i membri dell\'Alleanza cavalcano come te, sono i benvenuti alla mia tenuta!', '', 28153),
(157262, 'itIT', 'Ah, che bellissima giornata per uno spettacolo! In sella, amici miei, e mostrate le vostre abilità!', '', 28153),
(157261, 'itIT', '', 'Fai pure. Forza, $n.', 28153),
(157260, 'itIT', 'Io torno alla base. So come finirà anche senza vederlo.', '', 28153),
(157259, 'itIT', 'Sappi che siamo tuoi superiori. Nun rovinare il tempo mio con il Signore del Maleficio.', '', 28153),
(157258, 'itIT', '', 'Fantastico! Questo dovrebbe rallentare i Naga.', 28153),
(157257, 'itIT', '', 'Hai la mia parola. Vieni. $n, torna da Nathanos e informalo che abbiamo ciò che ci serve.', 28153),
(157256, 'itIT', 'Mi unirò a voi... e vi aiuterò a trovare il Maresciallo Valentine, se mi prometterai che la mia famiglia rimarrà al sicuro.', '', 28153),
(157255, 'itIT', '', 'I Naga stanno attaccando di nuovo il forte. Occupati di loro in stile tortolliano.', 28153),
(157254, 'itIT', '', 'Unisciti ai Reietti e plasma il tuo destino. Sarai tra coloro che ti accettano per ciò che sei diventato.', 28153),
(157253, 'itIT', 'E questo cosa fa di me? Solo uno schiavo senza cervello della Regina Banshee?', '', 28153),
(157252, 'itIT', '', 'Chesto è n\'onore che raramente viene assegnato a qualcuno nun di Zandalar. Vieni, cammina con me e raccontami le gesta di chesto Vol\'jin.', 28153),
(157250, 'itIT', '', 'Ho cercato di avvertirti, Zelling. Il processo ti ha cambiato, non sarai più accettato dai vivi.', 28153),
(157249, 'itIT', 'No... Julia... Matthew... Hannah... Cosa ho fatto? Cosa... sono?', '', 28153),
(157248, 'itIT', '', 'Manda via il mostro!', 28153),
(157247, 'itIT', '', 'Lasciaci stare!', 28153),
(157246, 'itIT', 'Vai via!', '', 28153),
(157245, 'itIT', 'Silenzio!', '', 28153),
(157244, 'itIT', '', 'Non so chi tu sia, ma mio marito non ha MAI cercato di fare del male a me o ai suoi figli. Ora ce ne andiamo... e non seguirci!', 28153),
(157243, 'itIT', 'Io... Io...', '', 28153),
(157242, 'itIT', 'ORA BASTA!', '', 28153),
(157241, 'itIT', 'Mamma! Aiuto!', '', 28153),
(157240, 'itIT', '', 'Tienilo lontano!', 28153),
(157239, 'itIT', 'Papà è qui. Ascoltate la mia voce! Perché non riuscite a capire?!?', '', 28153),
(157238, 'itIT', '', 'Vai via!', 28153),
(157237, 'itIT', 'Mamma, il mostro mi fa paura!', '', 28153),
(157236, 'itIT', 'Perché non vuoi capire?!? Sono tuo marito... bambini, sono il vostro papà!', '', 28153),
(157235, 'itIT', '', 'Per l\'ultima volta, STAI INDIETRO! Non sei mio marito!', 28153),
(157234, 'itIT', 'Anche nella morte... la mia forza non svanisce...', '', 28153),
(157233, 'itIT', 'Non eri $gpronto:pronta; ad affrontarmi in combattimento!', '', 28153),
(157232, 'itIT', 'Zelling, devi aiutarci a trovare il corpo del Maresciallo Valentine.', 'Zelling, devi aiutarci a trovare il corpo del Maresciallo Valentine.', 28153),
(157231, 'itIT', 'La mia famiglia... mi vendicherà.', '', 28153),
(157230, 'itIT', 'Tu sarai il bersaglio della mia furia!', '', 28153),
(157229, 'itIT', '', 'Vedremo cosa succederà.', 28153),
(157228, 'itIT', 'Sono vivo! Ahahah! Devo andare subito da Julia e dai bambini. Saranno felicissimi di vedermi!', '', 28153),
(157227, 'itIT', '', 'Ben pochi spiriti hanno mostrato nu tale... potere. Maestro Gadrin, ti invito a portare le ceneri di chesto Capo Tribù ad Atal\'dazar. Se lo spirito suo ne è degno, potrà avere nu posto tra i più grandi re.', 28153),
(157226, 'itIT', 'Zalazane nun potrà tornare indietro da lì. Anche nella morte, Vol\'jin veglia su di noi.', '', 28153),
(157225, 'itIT', 'I morti stanno cedendo...', '', 28153),
(157224, 'itIT', 'I rinforzi attendono il tuo ordine.', '', 28153),
(157223, 'itIT', 'Se l\'Orda vuole la guerra, allora la guerra è ciò che avranno!', '', 28153),
(157222, 'itIT', 'Spero tu abbia buone notizie.', '', 28153),
(157221, 'itIT', 'Sacraonda resisterà.', '', 28153),
(157220, 'itIT', 'Buon viaggio.', '', 28153),
(157219, 'itIT', 'Che le maree ti guidino.', '', 28153),
(157218, 'itIT', 'Eccellente! I rifornimenti ci saranno molto utili e troveremo un modo di sfruttare anche quei maialini.', '', 28153),
(157217, 'itIT', 'I Verrospino stanno attaccando di nuovo i nostri magazzini. Riportaci i nostri rifornimenti e... qualsiasi cosa ti sembri utile!', '', 28153),
(157216, 'itIT', 'Ricevuto.', '', 28153),
(157215, 'itIT', '', 'Sì signore.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(157214, 'itIT', '', 'Misericordiosa Elune, benedici i caduti.', 28153),
(157213, 'itIT', 'Taelia, preparati. Riferisci alle guardie della città di stare all\'erta per qualunque arma inusuale all\'interno di Boralus.', '', 28153),
(157212, 'itIT', '', 'Che si sappia che ritengo Vol\'jin, figlio di Sen\'jin, degno di cheste sacre tombe. Però, per entrare ad Atal\'dazar, dovrai combattere. Raccomando che sia la Voce dell\'Orda a portare cheste ceneri nel luogo del riposo eterno.', 28153),
(157211, 'itIT', '', 'È difficile fare qualcosa che i capi tuoi nun vogliono fare.', 28153),
(157210, 'itIT', 'Quando era ormai chiaro che il Capoguerra nostro, Garrosh, nun avrebbe regnato con onore, Vol\'jin guidò la ribellione per deporlo.', '', 28153),
(157209, 'itIT', '', 'A chel tempo, il padre mio era affascinato assai dalla visione di Zul di nu grande impero dei Troll. Devo dare atto al capo vostro di aver capito il quadro generale.', 28153),
(157208, 'itIT', 'Quando Zandalar tentò di riunire le tribù Troll, Vol\'jin scelse la sicurezza della gente sua invece degli oscuri poteri del Profeta.', '', 28153),
(157207, 'itIT', 'Vol\'jin strinse nu patto con Bwonsamdi per sconfiggere il potente Zalazane.', '', 28153),
(157206, 'itIT', '', 'Ci sono più Fuochi Fatui di quanti ne riesca a contare. Quante vite perdute...', 28153),
(157205, 'itIT', 'Stiamo accà con le ceneri di Vol\'jin, figlio di Sen\'jin, affinché vengano onorate in chesto sacro luogo.', '', 28153),
(157204, 'itIT', 'Flynn, ho un altro lavoro per te: aiuta la nostra nuova forza alleata a capire da dove arriva questa polvere da sparo.', '', 28153),
(157203, 'itIT', 'Minacce antiche si destano in queste terre. Fai attenzione.', '', 28153),
(157202, 'itIT', 'Invocatore del Vento, sono qui per conto della Capoguerra.', 'Invocatore del Vento, sono qui per conto della Capoguerra.', 28153),
(157201, 'itIT', 'Sì, devo andare a Silitus.', 'Sì, devo andare a Silitus.', 28153),
(157200, 'itIT', 'Perché sono qui?', 'Perché sono qui?', 28153),
(157199, 'itIT', 'Ti va di dare una piccola dimostrazione ai nostri colleghi scettici?', '', 28153),
(157198, 'itIT', 'No, non come queste.', '', 28153),
(157197, 'itIT', 'E questa sarebbe una pista? Creano nuove armi di continuo.', '', 28153),
(157196, 'itIT', '', 'D\'accordo, Flynn. Cos\'è questa tua nuova pista? C\'entra una nuova polvere da sparo dei Bracescura?', 28153),
(157195, 'itIT', 'Mi serve una Viverna dei Venti per raggiungere il Rifugio dei Grant nel Cratere di Un\'Goro.', 'Mi serve una Viverna dei Venti per raggiungere il Rifugio dei Grant nel Cratere di Un\'Goro.', 28153),
(157194, 'itIT', 'Ah, rieccoti... Meno male! Temevo già di dover dire alla Principessa che eri stato rapito da un Nano fatto di diamanti!', '', 28153),
(157193, 'itIT', 'Oh, fantastico! Abbiamo fatto un gran bel lavoro!', '', 28153),
(157192, 'itIT', 'Dobbiamo recuperare alcuni di quei carichi perduti. E con \"noi\" intendo te.', '', 28153),
(157191, 'itIT', 'Dovunque tu stia andando, spero che il viaggio tuo sia breve. La Principessa terrà bisogno dell\'aiuto tuo!', 'Dovunque tu stia andando, spero che il viaggio tuo sia breve. La Principessa terrà bisogno dell\'aiuto tuo!', 28153),
(157190, 'itIT', 'Chesto è straordinario! Devo prenderne nota.', 'Chesto è straordinario! Devo prenderne nota.', 28153),
(157189, 'itIT', 'Difendere le linee di rifornimento è un elemento fondamentale nella guerra... come anche l\'intralciare quelle dei propri nemici.', '', 28153),
(157188, 'itIT', 'Relitti dell\'Alleanza... È sempre un bel panorama da vedere! Perlustra l\'area in cerca di risorse che l\'Orda potrebbe sfruttare.', '', 28153),
(157187, 'itIT', 'In una sola giornata di lavoro!', '', 28153),
(157186, 'itIT', 'Quell\'estrattore è sotto attacco! Proteggetelo!', '', 28153),
(157185, 'itIT', 'Queste risorse saranno di vitale importanza per l\'Orda. Ottimo lavoro.', '', 28153),
(157184, 'itIT', 'Proteggete l\'estrattore! Abbiamo bisogno di quell\'Azerite!', '', 28153),
(157183, 'itIT', 'Qual è la tua strategia, Shandris?', 'Qual è la tua strategia, Shandris?', 28153),
(157182, 'itIT', '', '<La vista acuta di Shandris scruta l\'orizzonte. Ti annuisce in segno di assenso.>', 28153),
(157181, 'itIT', 'Trovare Mirasole e poi tempestarlo di frecce.', '', 28153),
(157180, 'itIT', 'La mia strategia?', '', 28153),
(157179, 'itIT', 'La squadra di agenti segreti di Gnomeregan piazzerà delle bombe per attirare l\'attenzione di Mirasole, poi lo colpiremo nel bel mezzo della confusione.', '', 28153),
(157178, 'itIT', '', 'Ehi, ehi!', 28153),
(157177, 'itIT', 'Affermativo! Per questo motivo, ho reclutato una squadra con l\'esperienza tecnica adatta.', '', 28153),
(157176, 'itIT', '', 'Vuoi... far saltare un sacco di bombe insieme.', 28153),
(157175, 'itIT', 'Mi piacerebbe eseguire un attacco incendiario sincronizzato contro tutti i loro siti di scavo.', '', 28153),
(157174, 'itIT', 'Sì. Le ultime informazioni parlano di almeno tre scavi.', '', 28153),
(157173, 'itIT', '', 'Archeologica?', 28153),
(157172, 'itIT', 'Mirasole, in quanto membro del Circolo del Reliquiario, è qui per una missione archeologica.', '', 28153),
(157171, 'itIT', 'Io... nun ricordo. Ma forse è meglio così.', '', 28153),
(157170, 'itIT', '', 'Chiedo scusa, chi sei tu? Era di te che parlava Malfurion?', 28153),
(157168, 'itIT', 'Ho consegnato il tuo messaggio a B\'wizati.', 'Ho consegnato il tuo messaggio a B\'wizati.', 28153),
(157167, 'itIT', '', 'E i civili... non hanno risparmiato nemmeno loro. Spero solo che qualcuno sia riuscito a fuggire...', 28153),
(157166, 'itIT', '', 'I nostri avamposti sono caduti uno dopo l\'altro. Sono stati colti alla sprovvista. Le guardie sono state avvelenate.', 28153),
(157165, 'itIT', '', '%s si asciuga una lacrima.', 28153),
(157164, 'itIT', '', 'Abbiamo provato a far cadere l\'Orda in trappola, ma abbiamo fallito. Non siamo riusciti a fermarli.', 28153),
(157163, 'itIT', 'È bello vedere che stai bene, $n.\n\nAnche io me la cavo.\n\nAkunda mi ha dato l\'opportunità di ripartire da zero.', '', 28153),
(157162, 'itIT', 'Qual è il tuo piano, Gran Comandante?', 'Qual è il tuo piano, Gran Comandante?', 28153),
(157161, 'itIT', 'La VII Legione rappresenta il meglio che Azeroth ha da offrire.\n\nPer l\'Alleanza!', '', 28153),
(157160, 'itIT', 'Chi? Nun conosco nessun Troll con chel nome.', '', 28153),
(157159, 'itIT', '', 'Cadaveri... Così tanti cadaveri...', 28153),
(157158, 'itIT', 'Ho qualcosa da mostrare al nostro campione. Un dono che potrebbe aiutare la gente di questa terra.', '', 28153),
(157157, 'itIT', 'Un Nano... fatto di diamanti... nel core di Zuldazar? Cosa...', '', 28153),
(157156, 'itIT', '', 'Ho già visto cose strane in queste foreste, ma mai niente di simile.', 28153),
(157155, 'itIT', 'Lo senti? La terra sta tremando...', '', 28153),
(157153, 'itIT', 'La Capoguerra mi ha ordinato di assisterti.', 'La Capoguerra mi ha ordinato di assisterti.', 28153),
(157152, 'itIT', 'Devo volare a Meccania, nella regione di Tanaris.', 'Devo volare a Meccania, nella regione di Tanaris.', 28153),
(157151, 'itIT', 'Devi... farlo...', '', 28153),
(157150, 'itIT', 'Condannerei... la mia anima... alla dannazione... se servisse a dare felicità alla mia famiglia... Ti prego! Devi...', '', 28153),
(157149, 'itIT', '', 'Me lo chiedo tutti i giorni, Zelling.', 28153),
(157148, 'itIT', 'Bersaglio acquisito.', '', 28153),
(157147, 'itIT', '', 'Tutti si abbandonano alla follia quando diventano Reietti. Alcuni più degli altri.', 28153),
(157146, 'itIT', 'Conosci Akunda?', 'Conosci Akunda?', 28153),
(157145, 'itIT', 'Lascia che Akunda rimuova il peso che tieni nel core.', 'Lascia che Akunda rimuova il peso che tieni nel core.', 28153),
(157144, 'itIT', 'Akunda ci dà l\'opportunità di nu nuovo inizio.', 'Akunda ci dà l\'opportunità di nu nuovo inizio.', 28153),
(157143, 'itIT', 'Sarai sempre di casa, qui.', 'Sarai sempre di casa, qui.', 28153),
(157142, 'itIT', 'Il Loa accoglie tutti nel tempio suo.', 'Il Loa accoglie tutti nel tempio suo.', 28153),
(157141, 'itIT', 'Conosci Akunda?', 'Conosci Akunda?', 28153),
(157140, 'itIT', 'Lascia che Akunda rimuova il peso che tieni nel core.', 'Lascia che Akunda rimuova il peso che tieni nel core.', 28153),
(157139, 'itIT', 'Akunda ci dà l\'opportunità di nu nuovo inizio.', 'Akunda ci dà l\'opportunità di nu nuovo inizio.', 28153),
(157138, 'itIT', 'Sarai sempre di casa, qui.', 'Sarai sempre di casa, qui.', 28153),
(157137, 'itIT', 'Il Loa accoglie tutti nel tempio suo.', 'Il Loa accoglie tutti nel tempio suo.', 28153),
(157136, 'itIT', 'Sono qui per aiutare, Nyse.', 'Sono qui per aiutare, Nyse.', 28153),
(157135, 'itIT', 'Ah, l\'incubo è finito.', 'Ah, l\'incubo è finito.', 28153),
(157134, 'itIT', 'Armati e pronti! Rispedite quel kraken in fondo agli abissi!', 'Armati e pronti! Rispedite quel kraken in fondo agli abissi!', 28153),
(157133, 'itIT', 'Pronti a far fuoco!', 'Pronti a far fuoco!', 28153),
(157132, 'itIT', 'Doras, ho bisogno di un volo per Melmarmitta ad Acquemorte.', 'Doras, ho bisogno di un volo per Melmarmitta ad Acquemorte.', 28153),
(157131, 'itIT', 'Cannoni pronti! Riducete quella bestia in poltiglia!', 'Cannoni pronti! Riducete quella bestia in poltiglia!', 28153),
(157130, 'itIT', 'No... NO!', 'No... NO!', 28153),
(157129, 'itIT', 'Grazie! Ora preparerò questo cannone per una bella rappresaglia!', 'Grazie! Ora preparerò questo cannone per una bella rappresaglia!', 28153),
(157128, 'itIT', '<Zabanji russa.>', '<Zabanji russa.>', 28153),
(157127, 'itIT', 'Te ne devo una! Ora dammi un secondo per far funzionare questo cannone!', 'Te ne devo una! Ora dammi un secondo per far funzionare questo cannone!', 28153),
(157126, 'itIT', 'Era tutto nu sogno?', 'Era tutto nu sogno?', 28153),
(157125, 'itIT', 'Non lasciate che questa bestia mi mangi!', 'Non lasciate che questa bestia mi mangi!', 28153),
(157124, 'itIT', 'Bruciateli fino a ridurli in cenere!', '', 28153),
(157123, 'itIT', 'Levatemi questo coso di dosso!', 'Levatemi questo coso di dosso!', 28153),
(157122, 'itIT', '$p, prendi una torcia e colpisci qualsiasi cosa si muova. Questi abomini non morti non sono degni neanche di uno sguardo!', '', 28153),
(157121, 'itIT', 'Esatto, soldato, e questo dannato porto è colmo di mostri con cui divertirci.', '', 28153),
(157120, 'itIT', 'Aiuto!', 'Aiuto!', 28153),
(157119, 'itIT', 'E nessuno ci ruberà le uccisioni, signore.', '', 28153),
(157118, 'itIT', 'Chi sei? Dove siamo?', 'Chi sei? Dove siamo?', 28153),
(157117, 'itIT', 'Non ci sono rinforzi e non ci sarà alcun salvataggio se le cose dovessero mettersi male.', '', 28153),
(157116, 'itIT', 'Ascoltate, soldati. Questa è una missione non autorizzata.', '', 28153),
(157115, 'itIT', 'Cosa stai aspettando, $p?\n\nAbbiamo armi e un nemico da affrontare. Sali a bordo!', 'Cosa stai aspettando, $p?\n\nAbbiamo armi e un nemico da affrontare. Sali a bordo!', 28153),
(157114, 'itIT', '<Akunda l\'Esausto russa.>', '<Akunda l\'Esausto russa.>', 28153),
(157113, 'itIT', 'Siamo tutti... Akunda.', 'Siamo tutti... Akunda.', 28153),
(157112, 'itIT', 'Altro lavoro?', '', 28153),
(157111, 'itIT', 'Giusto.', '', 28153),
(157110, 'itIT', 'Benissimo.', '', 28153),
(157109, 'itIT', 'Sì, signore.', '', 28153),
(157108, 'itIT', '', 'Sissignore.', 28153),
(157107, 'itIT', 'Va bene, proseguiamo senza di lei. Se non ci raggiungerà presto... state pronti.', '', 28153),
(157106, 'itIT', '', 'Le ci vuole un po\' di tempo per... acclimatarsi.', 28153),
(157105, 'itIT', '', 'Hnn... gh...', 28153),
(157104, 'itIT', 'Stone, sii gentile e dimmi il nome dell\'eroe di guerra più importante di questo cimitero.', '', 28153),
(157103, 'itIT', 'Ora che sei qui, possiamo cominciare.', '', 28153),
(157102, 'itIT', 'Combattete per i vostri fratelli e sorelle!', 'Combattete per i vostri fratelli e sorelle!', 28153),
(157101, 'itIT', 'Vittoria per l\'Alleanza!', 'Vittoria per l\'Alleanza!', 28153),
(157100, 'itIT', 'Alla battaglia!', 'Alla battaglia!', 28153),
(157099, 'itIT', 'Hai risolto brillantemente il problema. Stasera potranno tutti tornare a casa al sicuro.', '', 28153),
(157098, 'itIT', 'Arathi è nostra!', 'Arathi è nostra!', 28153),
(157097, 'itIT', 'Morte all\'Orda!', 'Morte all\'Orda!', 28153),
(157096, 'itIT', 'Con me!', 'Con me!', 28153),
(157095, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(157094, 'itIT', 'Da questa parte! Abbiamo una guerra da vincere!', 'Da questa parte! Abbiamo una guerra da vincere!', 28153),
(157093, 'itIT', 'Le forze dell\'Orda in questa zona hanno dato la caccia alla fauna fino ai bassopiani. Aiuta i cacciatori a occuparsi degli orsi.', '', 28153),
(157092, 'itIT', 'Mi hai... fatto uccidere il mio amico! Ora morirai!', '', 28153),
(157091, 'itIT', 'Fratelli e sorelle, ammirate il nostro glorioso destino!', '', 28153),
(157090, 'itIT', 'Grazie, $gamico:amica;. La valle è al tuo fianco.', 'Sono così felice di vederti, $p. Me ne ricorderò.', 28153),
(157089, 'itIT', 'Ora posso farcela. Fai attenzione.', 'Sei una gioia per gli occhi!', 28153),
(157088, 'itIT', 'Pensavo di essere già morto!', 'Grazie, non lo dimenticherò.', 28153),
(157087, 'itIT', 'Ah! Forse quei cinghiali non sono poi così male. Chissà se gli piacciono le ostriche al vapore...', '', 28153),
(157086, 'itIT', 'Alcuni cinghiali sono stati avvistati fuori dalle gallerie. Se ti va di cavalcarne uno, potremmo usarlo contro i Verrospino!', '', 28153),
(157085, 'itIT', 'Vendicami... Caramellino...', '', 28153),
(157084, 'itIT', '', 'Finalmente... il tormento è finito...', 28153),
(157083, 'itIT', '', 'Sì... Libera...', 28153),
(157082, 'itIT', '', 'Era... una trappola...', 28153),
(157081, 'itIT', '', 'Eheh... il predatore diventa la preda...', 28153),
(157080, 'itIT', '', 'Sta arrivando per tutti noi...', 28153),
(157079, 'itIT', 'Un momento, vostra altezza! Abbiamo delle nuove informazioni.', '', 28153),
(157078, 'itIT', '', 'Questo non... doveva... succedere...', 28153),
(157077, 'itIT', '', 'È così comodo quando la preda si getta da sola nella trappola!', 28153),
(157076, 'itIT', '', 'Ma guarda, sei $gfinito:finita; nella mia trappola!', 28153),
(157075, 'itIT', '', 'Sei un po\' $gpiccolo:piccola;, ma mi prenderò lo stesso la tua pelle!', 28153),
(157074, 'itIT', '', 'Mi avevano promesso tutti i bottini della foresta!', 28153),
(157073, 'itIT', '', 'La tua pelle mi farà fare un sacco di soldi!', 28153),
(157072, 'itIT', '', 'Un\'altra pelliccia da prendere!', 28153),
(157071, 'itIT', 'Tu... fallirai...', '', 28153),
(157070, 'itIT', 'Ritorno alla terra...', '', 28153),
(157069, 'itIT', 'La fine... si avvicina...', '', 28153),
(157068, 'itIT', 'Che cosa vuoi? Sciò! Vattene!', '', 28153),
(157067, 'itIT', 'La mia anima... è ammorbata...', '', 28153),
(157066, 'itIT', 'Il velo è caduto...', '', 28153),
(157065, 'itIT', 'Thros ci consumerà tutti!', '', 28153),
(157064, 'itIT', 'Sta parlando dall\'Aldilà!', '', 28153),
(157063, 'itIT', 'Compi la vendetta tua e piglia il tesoro!', '', 28153),
(157062, 'itIT', 'Piglia na torcia e mettiti al lavoro, $p!', 'Piglia na torcia e mettiti al lavoro, $p!', 28153),
(157061, 'itIT', 'Già, li rispediremo giù nelli abissi oscuri!', '', 28153),
(157060, 'itIT', 'Quindi li bruceremo tutti quanti?', 'Quindi li bruceremo tutti quanti?', 28153),
(157059, 'itIT', 'La vecchia ciurma maledetta nel Porto di Zem\'lan sta inviando dei grossi gruppi all\'attacco e noi siamo uno delli obiettivi loro.', '', 28153),
(157058, 'itIT', 'Bentornati in mare, ragazzi!', '', 28153),
(157057, 'itIT', 'Tutti ai remi!', 'Tutti ai remi!', 28153),
(157056, 'itIT', 'Quando avrò capito l\'incantesimo, forse mi lasceranno entrare. E se fosse... Ta ergsi leinad!', '', 28153),
(157055, 'itIT', 'Caramellino, se riesci a capirmi, volevo solo scusarmi per averti trasformato. Permanentemente, si intende.', '', 28153),
(157054, 'itIT', 'Mi domando se il tuo nome funzioni, Caramellino. Proviamo. Nolem asi Caramellino!', '', 28153),
(157053, 'itIT', 'Non è stato bello essere espulso, Caramellino. Gli mostrerò il mio vero potere... non appena mi tornerà in mente come funzionava.', '', 28153),
(157052, 'itIT', 'Mmm... no, direi che non funziona.', '', 28153),
(157051, 'itIT', 'Non mi ricordo quel dannato incantesimo. Com\'era, Caramellino? Leinad qualcosa... Nos fatsug?', '', 28153),
(157050, 'itIT', 'I miei occhi sono aperti!', '', 28153),
(157049, 'itIT', 'Il tuo sangue sfamerà la foresta!', '', 28153),
(157048, 'itIT', 'Arrrghhh!', '', 28153),
(157047, 'itIT', 'Un lavoro eccellente. Forse un giorno questo posto tornerà a essere usato per pregare.', '', 28153),
(157046, 'itIT', 'La magia che avvolge questo posto corromperà le acque, se lasciata agire. Fai il possibile per rallentare i Saggi delle Maree.', '', 28153),
(157045, 'itIT', 'Possano le loro anime perdute venir spazzate via dalle maree per giungere alla pace.', '', 28153),
(157044, 'itIT', 'L\'influenza oscura della Casata dei Sacraonda è stata portata in questo posto da alcuni individui. Uccidili prima che causino altri problemi.', '', 28153),
(157043, 'itIT', 'Ben fatto! Riesco a vedere il fumo da qui! Li colpiremo di nuovo non appena possibile.', '', 28153),
(157042, 'itIT', 'Spero tu vada d\'accordo con i grifoni! Contatta Bernadette Robels. Ha ideato un piano per colpire l\'Orda al Forte di Zannaguerra.', '', 28153),
(157041, 'itIT', '', 'Arrr?', 28153),
(157040, 'itIT', 'Sei debole senza il Loa! Finiscilo!', '', 28153),
(157039, 'itIT', 'Il demonio si nasconde dietro il potere di Rezan! Glielo strapperò dalle mani!', '', 28153),
(157038, 'itIT', 'Ricorda, continentale, stai sempre all\'erta su ciò che vive negli abissi. Nulla di buono si nasconde nelle ombre.', '', 28153),
(157037, 'itIT', 'Alcuni Saggi delle Maree stanno cercando di evocare una forza che potrebbe spazzare via Boralus. Devono essere fermati!', '', 28153),
(157036, 'itIT', '', 'Lascia a lei la guida. Arriverai e tornerai indietro in un pezzo solo.', 28153),
(157035, 'itIT', '', 'È pronta ad andare!', 28153),
(157034, 'itIT', '', 'È il grifone più veloce della valle. Se qualcuno ti dice il contrario, sta mentendo.', 28153),
(157033, 'itIT', 'Sei $gil prossimo:la prossima; della fila.', 'Sei $gil prossimo:la prossima; della fila.', 28153),
(157032, 'itIT', 'Tu e l\'uccellino non siete simpatici.', 'Tu e l\'uccellino non siete simpatici.', 28153),
(157031, 'itIT', 'Anch\'io voglio volare!', 'Anch\'io voglio volare!', 28153),
(157030, 'itIT', 'Odio l\'Alleanza.', 'Odio l\'Alleanza.', 28153),
(157029, 'itIT', 'Guarda! Bell\'uccellino.', 'Guarda! Bell\'uccellino.', 28153),
(157028, 'itIT', '', 'Il Motore di Rioriginazione è pronto. Ora tocca a noi porre fine alla piaga di G\'huun na volta per tutte.', 28153),
(157027, 'itIT', 'Il Motore di Rioriginazione è pronto. Attiviamolo e facciamo scoppiare G\'huun come la pustola che è.', '', 28153),
(157026, 'itIT', 'Io... schiacciata?', 'Io... schiacciata?', 28153),
(157025, 'itIT', 'Creatura piccirilla! Me schiaccia te come insetto!', 'Creatura piccirilla! Me schiaccia te come insetto!', 28153),
(157024, 'itIT', 'Fatemi uscire da qui!', 'Fatemi uscire da qui!', 28153),
(157023, 'itIT', '<Il Cornofurente Giovane muggisce e corre da sua madre!>', '<Il Cornofurente Giovane muggisce e corre da sua madre!>', 28153),
(157022, 'itIT', 'Portatemi dentro!', 'Portatemi dentro!', 28153),
(157021, 'itIT', 'Serve un passaggio?', 'Serve un passaggio?', 28153),
(157020, 'itIT', '', 'Everit ti ha insegnato bene. So che sarebbe fiero di te.', 28153),
(157019, 'itIT', '', 'Grazie, mia signora. Non ti deluderò.', 28153),
(157018, 'itIT', '', 'Ti promuovo pertanto al grado di Maresciallo e ti nomino capo della guardia dei Crestabianca.', 28153),
(157017, 'itIT', '', 'Ma Drustvar ha bisogno dei tuoi talenti in misura ancora più grande.', 28153),
(157016, 'itIT', '', 'Inquisitrice Albachiara, hai superato le nostre aspettative. Hai mostrato compassione, valore, capacità di comando e astuzia.', 28153),
(157015, 'itIT', '', 'Abbiamo tutti sofferto il dolore della perdita, ma il fuoco della speranza arde con forza.', 28153),
(157014, 'itIT', 'Niente di personale.', 'Niente di personale.', 28153),
(157013, 'itIT', 'Il nostro nemico controlla il Circolo degli Elementi... per ora.', 'Il nostro nemico controlla il Circolo degli Elementi... per ora.', 28153),
(157012, 'itIT', 'Vedo i vessilli dell\'Orda al Circolo degli Elementi!', 'Vedo i vessilli dell\'Orda al Circolo degli Elementi!', 28153),
(157011, 'itIT', 'L\'Orda ha il controllo del Circolo degli Elementi!', 'L\'Orda ha il controllo del Circolo degli Elementi!', 28153),
(157010, 'itIT', 'Il Circolo degli Elementi mostra i nostri vessilli!', 'Il Circolo degli Elementi mostra i nostri vessilli!', 28153),
(157009, 'itIT', 'Le nostre forze controllano il Circolo degli Elementi.', 'Le nostre forze controllano il Circolo degli Elementi.', 28153),
(157008, 'itIT', 'Il Circolo degli Elementi rimane sotto il nostro controllo.', 'Il Circolo degli Elementi rimane sotto il nostro controllo.', 28153),
(157007, 'itIT', 'La Nuova Fattoria mostra i vessilli dell\'Orda... per ora.', 'La Nuova Fattoria mostra i vessilli dell\'Orda... per ora.', 28153),
(157006, 'itIT', 'Quei mostri credono di controllare la Nuova Fattoria? Gliela faremo vedere...', 'Quei mostri credono di controllare la Nuova Fattoria? Gliela faremo vedere...', 28153),
(157005, 'itIT', 'Quei demoni non possono tenersi la Nuova Fattoria per sempre.', 'Quei demoni non possono tenersi la Nuova Fattoria per sempre.', 28153),
(157004, 'itIT', 'Le nostre forze hanno il controllo della Nuova Fattoria.', 'Le nostre forze hanno il controllo della Nuova Fattoria.', 28153),
(157003, 'itIT', 'La Nuova Fattoria è sotto il nostro controllo.', 'La Nuova Fattoria è sotto il nostro controllo.', 28153),
(157002, 'itIT', 'A quanto pare abbiamo il controllo della Nuova Fattoria. Facciamo in modo che rimanga così.', 'A quanto pare abbiamo il controllo della Nuova Fattoria. Facciamo in modo che rimanga così.', 28153),
(157001, 'itIT', 'Il Loa dei Re è caduto. Dobbiamo stare attenti se vogliamo lanciare un\'altra battuta di caccia.\n\nRastakhan è gravemente ferito e invecchia rapidamente. Solo il potere di Rezan potrebbe tenere a bada Bwonsamdi. Gli offrirei il mio potere, ma non è in mio potere sfidare il Loa della Morte.', '', 28153),
(157000, 'itIT', 'Cosa, signora?', '', 28153),
(156999, 'itIT', '', '<La Signora delle Bestie L\'kala guarda con sospetto il Goblin accanto a lei.>', 28153),
(156998, 'itIT', '', 'Sembra che voi piccirilli siate stanchi, dopo tutto chel lottare. Starete al sicuro accà. Mi prenderò cura di voi io stessa.', 28153),
(156996, 'itIT', '<Il Cucciolo di Cornofurente sbadiglia e chiude gli occhi.>', '<Il Cucciolo di Cornofurente sbadiglia e chiude gli occhi.>', 28153),
(156995, 'itIT', 'È ora di andare!', 'È ora di andare!', 28153),
(156994, 'itIT', 'Mi sento come se qualcuno avesse strappato l\'anima dal corpo mio.', '', 28153),
(156993, 'itIT', 'C\'è mancato poco! Apprezzo molto l\'aiuto!', 'C\'è mancato poco! Apprezzo molto l\'aiuto!', 28153),
(156992, 'itIT', 'Apprezzo l\'aiuto! Per qualche ragione, i miei stivali da fuga non hanno funzionato.', 'Apprezzo l\'aiuto! Per qualche ragione, i miei stivali da fuga non hanno funzionato.', 28153),
(156991, 'itIT', 'Grazie mille! Non appena sarò di ritorno, manderò una lamentela. I problemi logistici che stanno affliggendo questa spedizione sono più gravi di quanto preventivato.', 'Grazie mille! Non appena sarò di ritorno, manderò una lamentela. I problemi logistici che stanno affliggendo questa spedizione sono più gravi di quanto preventivato.', 28153),
(156990, 'itIT', 'Mi rinchiuderò nel Sanitron per una settimana dopo tutto questo!', 'Mi rinchiuderò nel Sanitron per una settimana dopo tutto questo!', 28153),
(156989, 'itIT', 'Era davvero una brutta situazione! Ti ringrazio davvero!', 'Era davvero una brutta situazione! Ti ringrazio davvero!', 28153),
(156988, 'itIT', 'Che i mari benedicano chesti minerali e che essi nun reclamino mai coloro che li hanno benedetti.', 'Che i mari benedicano chesti minerali e che essi nun reclamino mai coloro che li hanno benedetti.', 28153),
(156987, 'itIT', 'Potresti benedire questi Lingotti d\'Argento della Tempesta?', 'Potresti benedire questi Lingotti d\'Argento della Tempesta?', 28153),
(156986, 'itIT', 'Nessuno dovrebbe pensare di diventare un Reietto come se fosse una seconda possibilità.', '', 28153),
(156985, 'itIT', 'Non mi piace quello che stai insinuando, Zelling.', '', 28153),
(156984, 'itIT', 'Sì! Ammira il potere dei crostacei!', '', 28153),
(156983, 'itIT', 'A quanto pare dovrai tornartene nel tuo guscio! L\'hai capita? Gusci? Granchi? La vittoria è mia!', '', 28153),
(156982, 'itIT', 'È tutto inutile! Non hai ancora visto nulla del Capitano Hermes e il suo trio di spietati granchi!', '', 28153),
(156981, 'itIT', 'Com\'è possibile?', '', 28153),
(156980, 'itIT', 'Finalmente, una sfida!', '', 28153),
(156979, 'itIT', 'Fai rotta verso la Valle dei Sacraonda.', 'Fai rotta verso la Valle dei Sacraonda.', 28153),
(156978, 'itIT', 'Fai rotta verso la Baia di Tiragarde.', 'Fai rotta verso la Baia di Tiragarde.', 28153),
(156977, 'itIT', 'Fai rotta verso Drustvar.', 'Fai rotta verso Drustvar.', 28153),
(156976, 'itIT', '...Che c\'è?', '', 28153),
(156974, 'itIT', 'Quel tizio con la maglietta rossa laggiù mi ha detto che \"non sono canonico\". Be\', ovvio! Sono un marinaio, non un Sacerdote!', '', 28153),
(156973, 'itIT', 'Puoi riassumermi di nuovo la situazione a Kul Tiras?', 'Puoi riassumermi di nuovo la situazione a Kul Tiras?', 28153),
(156972, 'itIT', 'Metteremo le cose a posto.', '', 28153),
(156971, 'itIT', '', 'Sì, come posso aiutarti?', 28153),
(156970, 'itIT', 'Ottimo lavoro! Di certo gli hai messo un bel bastone tra le ruote.', '', 28153),
(156969, 'itIT', 'I mari ti chiamano come fanno con me?', '', 28153),
(156968, 'itIT', 'Devo sapere se la mia famiglia è al sicuro! <Tossisce>', '', 28153),
(156967, 'itIT', '', 'Ti ho detto di non mettere alla prova la mia...', 28153),
(156966, 'itIT', 'Ho ricevuto rapporti di una qualche specie di pianta mostruosa vicino alle gallerie. I nostri contadini meccanici dovrebbero riuscire a sbarazzarsene in fretta.', '', 28153),
(156965, 'itIT', 'Che i mari ti guidino a casa.', '', 28153),
(156964, 'itIT', 'Cosa vuoi dalla Casata dei Marefiero?', '', 28153),
(156963, 'itIT', 'Fai rotta verso Zuldazar.', 'Fai rotta verso Zuldazar.', 28153),
(156962, 'itIT', 'Fai rotta verso Nazmir!', 'Fai rotta verso Nazmir!', 28153),
(156961, 'itIT', 'Insieme siamo forti.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156960, 'itIT', 'Onorerò il retaggio di mio padre.', '', 28153),
(156959, 'itIT', 'Ho passato anni per mare in cerca dei più letali granchi eremiti che questo mondo conosca. Ti va di combattere o hai troppa paura che le tue mascotte vengano spazzate via?', '', 28153),
(156958, 'itIT', 'Ottimo lavoro. Diremo ai nostri migliori ricercatori di iniziare a esaminare queste scritture. Grazie.', '', 28153),
(156957, 'itIT', 'I nostri Maghi Guerrieri hanno visto molte pergamene magiche Tortolliane tra i caduti. Dobbiamo recuperarle prima che l\'Orda se ne accorga. Cerca e recupera tutte quelle che riesci.', '', 28153),
(156956, 'itIT', 'L\'Alleanza ha riconquistato Stromgarde!', 'L\'Alleanza ha riconquistato Stromgarde!', 28153),
(156955, 'itIT', 'Ehi, $n! Vieni qui!', '', 28153),
(156954, 'itIT', 'Ehilà, $p. Ho sentito che sei $gamico:amica; di Kiro e dei Vulpera.\n\nNun teniamo tempo di discutere e la parola di Kiro mi è sufficiente.\n\nSe ti va di fare nu po\' di razzie in mare aperto, puoi unirti alla ciurma nostra quando preferisci.\n\nSalta a bordo e, quando sarai $gpronto:pronta;, spiegheremo le vele.', '', 28153),
(156953, 'itIT', 'Interessante... Farò fare altri studi su questa pergamena ai nostri Maghi. Grazie!', '', 28153),
(156952, 'itIT', 'Salve, $p! È bello rivederti.\n\nTi senti in vena di nu po\' di razzie lungo la costa? Zem\'lan sta ordinando alle ciurme sue di raggiungere le barche, il che li rende dei bersagli facili per noi... se tieni na buona mira.\n\nTi ho già $gvisto:vista; in azione in passato, so che sei capace di sbarazzarti in fretta di chegli scheletri scorbutici.\n\nSalta a bordo della barca quando sei $gpronto:pronta; a partire.', '', 28153),
(156951, 'itIT', 'Tornerò alla Redenzione del Vento. Informa il Gran Ammiraglio quando sei $gpronto:pronta; a tornare a Boralus.', '', 28153),
(156950, 'itIT', 'Ho passato anni in cerca dei più spietati granchi con cui farti combattere. Ti interessa vedere quanto sanno resistere le tue mascotte?', '', 28153),
(156949, 'itIT', '$n! Cosa posso fare per te?', '', 28153),
(156948, 'itIT', 'Cosh\'è queshto?', 'Cosh\'è queshto?', 28153),
(156947, 'itIT', '$n! È bello rivederti. È passato un po\' di tempo da quando ho servito sotto di te a Draenor.', '', 28153),
(156946, 'itIT', 'I Kul Tirani non conoscono la paura!', '', 28153),
(156945, 'itIT', 'Ma cosha...', 'Ma cosha...', 28153),
(156944, 'itIT', 'Bleah! Troppo amara!', 'Bleah! Troppo amara!', 28153),
(156943, 'itIT', 'Sa di... uncino...', 'Sa di... uncino...', 28153),
(156942, 'itIT', 'Che ti shembro?... Un Vrykul?... Hic!', 'Che ti shembro?... Un Vrykul?... Hic!', 28153),
(156941, 'itIT', 'Odio... Hic!... la birra chiara...', 'Odio... Hic!... la birra chiara...', 28153),
(156940, 'itIT', 'Apri un portale per far attraversare le nostre truppe.', 'Apri un portale per far attraversare le nostre truppe.', 28153),
(156939, 'itIT', 'È un onore servire l\'Orda come parte dei miei studi sulla telemanzia sotto la guida di Oculeth.\n\nSarà un onore anche lasciare questo posto, non appena tutto sarà compiuto.', '', 28153),
(156938, 'itIT', 'I miei segugi... abbaiano... ma non mordono...', 'I miei segugi... abbaiano... ma non mordono...', 28153),
(156937, 'itIT', 'Perfetto, la cava è venuta a noi!', 'Perfetto, la cava è venuta a noi!', 28153),
(156936, 'itIT', 'Infondi potere in questo amuleto... potrebbe essere l\'unico modo che abbiamo per salvarla!', '', 28153),
(156935, 'itIT', 'Senti anche tu? Una specie di... tremore...', '', 28153),
(156934, 'itIT', '', 'Soggetto: Azeroth. Grave aritmia rilevata.\n\nSegni vitali oltre i parametri accettabili.\n\nAggiornamento dei rapporti sull\'incidente...\n\nERRORE. ERRORE. ERRORE. ERRORE.', 28153),
(156933, 'itIT', 'Ohhh! È forte!', '', 28153),
(156932, 'itIT', 'Mmm... queshto mi ricorda... di quand\'ero minatore... Il trucco era colpire col piccone negli angoli... Mantiene i... minerali...', '', 28153),
(156931, 'itIT', '', 'PERICOLO: Rilevate brecce multiple al sistema di contenimento.\n\nSi raccomanda l\'epurazione delle seguenti strutture:\n\nUldaman. Uldum. Uldorus. Ulduar. Uldir. Uldaz. Uld... Uld... Uld...', 28153),
(156930, 'itIT', 'Argh... Non fa proprio al casho mio...', '', 28153),
(156929, 'itIT', 'Secondo i miei calcoli, abbiamo perso il 2,39%, periodico ovviamente, di probabilità di vittoria. Dobbiamo sbrigarci con le riparazioni!', 'Secondo i miei calcoli, abbiamo perso il 2,39%, periodico ovviamente, di probabilità di vittoria. Dobbiamo sbrigarci con le riparazioni!', 28153),
(156928, 'itIT', 'Andiamo! Riparate quei carri! Siamo indietro con la tabella di marcia!', 'Andiamo! Riparate quei carri! Siamo indietro con la tabella di marcia!', 28153),
(156927, 'itIT', 'Presto, gente! Abbiamo poco tempo per schierare questi Carri d\'Assedio prima che l\'Orda scopra che siamo qui.', 'Presto, gente! Abbiamo poco tempo per schierare questi Carri d\'Assedio prima che l\'Orda scopra che siamo qui.', 28153),
(156926, 'itIT', 'Offri del Caffè Forte del Maggiore.', 'Offri del Caffè Forte del Maggiore.', 28153),
(156925, 'itIT', 'Offri dell\'\"Aurora Boreale\".', 'Offri dell\'\"Aurora Boreale\".', 28153),
(156924, 'itIT', 'Offri del Liquore Amaro di Cepposcuro.', 'Offri del Liquore Amaro di Cepposcuro.', 28153),
(156923, 'itIT', 'Offri del Brandy di Mele di Brennadam.', 'Offri del Brandy di Mele di Brennadam.', 28153),
(156922, 'itIT', 'Offri delle Bollicine del Presidio della Pesca.', 'Offri delle Bollicine del Presidio della Pesca.', 28153),
(156921, 'itIT', 'Offri dell\'Idromele dei Mildenhall.', 'Offri dell\'Idromele dei Mildenhall.', 28153),
(156920, 'itIT', 'Offri della Birra Chiara di Selvabianca.', 'Offri della Birra Chiara di Selvabianca.', 28153),
(156919, 'itIT', 'Offri del Sanguinello dei Dentineri.', 'Offri del Sanguinello dei Dentineri.', 28153),
(156918, 'itIT', 'Riportaci a Boralus.', 'Riportaci a Boralus.', 28153),
(156917, 'itIT', '', 'Oh cielo! Non ti deluderò, $n, lo giuro!', 28153),
(156916, 'itIT', '', 'Chiedo scusa, $gsignor:signora;? $n? Quaggiù!', 28153),
(156915, 'itIT', 'Oh, hai bisogno di qualcosa da me?', '', 28153),
(156914, 'itIT', 'Dove dovremmo concentrare i nostri sforzi?', '', 28153),
(156913, 'itIT', 'Riportaci a Zuldazar.', 'Riportaci a Zuldazar.', 28153),
(156912, 'itIT', '', 'Hai bisogno di una barca? Di recapitare un messaggio?\n\nDI UCCIDERE QUALCUNO?', 28153),
(156911, 'itIT', 'Vattene, cumpà... Nun vedi che sto... Hic!... che sto occupato?', '', 28153),
(156910, 'itIT', '', 'Soggetto: Azeroth.\n\nPERICOLO: Errore di sistema catastrofico rilevato.\n\nIntegrità planetaria al...\n\nCalcolo in corso... Calcolo in corso... Calcolo in corso...', 28153),
(156909, 'itIT', 'Questo non era nei miei calcoli...', 'Questo non era nei miei calcoli...', 28153),
(156908, 'itIT', 'Secondo i miei calcoli, le vostre probabilità di successo sono... zero!', 'Secondo i miei calcoli, le vostre probabilità di successo sono... zero!', 28153),
(156907, 'itIT', '', 'Chel Verrospino teneva nu potente mojo, ma nun poteva nulla contro di te.', 28153),
(156906, 'itIT', '', 'Le terre stesse stanno marciando al comando di no Sciamano Verrospino. Sbarazzati di chesta nuova minaccia prima che sconvolga i piani nostri.', 28153),
(156905, 'itIT', 'Stanotte dormirò sereno sapendo che a Sacraonda ci sono meno massi viventi in giro.', '', 28153),
(156904, 'itIT', '<Il Piccolo Pterrordattilo Selvatico strilla spaventato!>', '<Il Piccolo Pterrordattilo Selvatico strilla spaventato!>', 28153),
(156903, 'itIT', 'C\'è un Invocatore della Terra Verrospino che sta evocando un\'armata di elementali. Sfoltiscila e poi occupati di lui!', '', 28153),
(156902, 'itIT', 'Grazie. Pensavo che fosse la fine.', 'Grazie. Pensavo che fosse la fine.', 28153),
(156901, 'itIT', 'Sono felice di vedere che esistono ancora persone gentili al mondo.', 'Sono felice di vedere che esistono ancora persone gentili al mondo.', 28153),
(156900, 'itIT', 'Grazie! Da qui in poi, posso farcela da solo.', 'Grazie! Da qui in poi, posso farcela da sola.', 28153),
(156899, 'itIT', 'Vendica chi non abbiamo potuto salvare.', 'Vendica chi non abbiamo potuto salvare.', 28153),
(156898, 'itIT', 'Non hai idea di quello che ci hanno fatto passare...', 'Non hai idea di quello che ci hanno fatto passare...', 28153),
(156897, 'itIT', 'Mi hai salvato la vita!', 'Mi hai salvato la vita!', 28153),
(156896, 'itIT', 'Ti ringrazio veramente.', 'Ti ringrazio veramente.', 28153),
(156895, 'itIT', 'Sono in debito con te.', 'Sono in debito con te.', 28153),
(156894, 'itIT', 'Il tuo coraggio non ha eguali.', 'Il tuo coraggio non ha eguali.', 28153),
(156893, 'itIT', 'Non dimenticherò mai la tua gentilezza.', 'Non dimenticherò mai la tua gentilezza.', 28153),
(156892, 'itIT', 'Sei $garrivato:arrivata; proprio al momento giusto!', 'Sei $garrivato:arrivata; proprio al momento giusto!', 28153),
(156891, 'itIT', 'La tua compassione non sarà dimenticata.', 'La tua compassione non sarà dimenticata.', 28153),
(156890, 'itIT', 'Ti devo la mia vita.', 'Ti devo la mia vita.', 28153),
(156889, 'itIT', 'Farò meglio a tornare in battaglia.', 'Farò meglio a tornare in battaglia.', 28153),
(156888, 'itIT', 'Mescolate fino a farla diventare vellutata!', '', 28153),
(156887, 'itIT', 'Mischiala per bene!', '', 28153),
(156886, 'itIT', 'Finalmente, accendiamo i fornelli!', '', 28153),
(156885, 'itIT', 'Aggiungiamo un po\' di sapore!', '', 28153),
(156884, 'itIT', 'Uno alla volta!', '', 28153),
(156883, 'itIT', 'Vale la pena salvare questa valle.', '', 28153),
(156882, 'itIT', 'Hai qualche rifornimento in più?', 'Hai qualche rifornimento in più?', 28153),
(156881, 'itIT', 'Rezan... è... sparito. Chel... coso nun è nu Loa.', '', 28153),
(156880, 'itIT', 'Argh! Questa sala è in rovina. Non resterà su ancora a lungo!', '', 28153),
(156879, 'itIT', 'Kul Tiras si trova davanti a un grave pericolo, Magni. Ma immagino tu sia qui per... altre ragioni.', '', 28153),
(156878, 'itIT', '', 'Dove ho messo la canna da pesca mia? Giurerei di averla appoggiata accà...', 28153),
(156877, 'itIT', '', 'Si può andare a caccia e a pesca accà nei dintorni, se sai dove cercare.', 28153),
(156876, 'itIT', '<Il legno fatiscente scricchiola mentre il dolce vento accarezza un lato della carrozza.>\n\n<Una delle ruote sembra bloccata.>', '', 28153),
(156875, 'itIT', '<Dai una spinta alla carovana.>', '<Dai una spinta alla carovana.>', 28153),
(156874, 'itIT', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t Ti stai avvicinando alla nave dell\'Orda. Fai attenzione!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t Ti stai avvicinando alla nave dell\'Orda. Fai attenzione!', 28153),
(156873, 'itIT', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t Ti stai avvicinando alla nave dell\'Alleanza. Fai attenzione!', '|TInterface\\Icons\\ABILITY_HISEK_AIM.BLP:20|t Ti stai avvicinando alla nave dell\'Alleanza. Fai attenzione!', 28153),
(156872, 'itIT', '', 'Le mura devono cadere. Il mare tornerà.', 28153),
(156871, 'itIT', '$n... Vai a renderti utile da qualche altra parte. Ti farò sapere quando avremo ancora bisogno di te.', '', 28153),
(156870, 'itIT', 'Lilian. Stone. Venite, aiutatemi a trovare questi... Saggi delle Maree.', '', 28153),
(156869, 'itIT', 'Sono stanco morto di questi continui problemi.', '', 28153),
(156868, 'itIT', 'Be\', $n, cos\'hai trovato? Fa\' vedere.', '', 28153),
(156867, 'itIT', 'Be\', hai del lavoro da fare. La piattaforma di teletrasporto ti riporterà dai tuoi alleati. Buona fortuna... a tutti noi.', '', 28153),
(156866, 'itIT', 'Io continuerò a cercare un modo per curare le ferite di Azeroth. Se avrò bisogno di te, ti contatterò tramite l\'amuleto.', '', 28153),
(156865, 'itIT', 'Porta sempre con te quell\'amuleto. Ti aiuterà nei tempi bui che ci attendono.', '', 28153),
(156864, 'itIT', 'Quindi tutto quello di cui abbiamo bisogno è qualcosa che ci conduca a lui.', '', 28153),
(156863, 'itIT', '', 'Le mura della fortezza crolleranno sotto i tuoi colpi.', 28153),
(156862, 'itIT', '', 'Skoloth, al segnale tu attaccherai le mura.', 28153),
(156861, 'itIT', '', 'Sarai $gricompensato:ricompensata; per i tuoi servigi.', 28153),
(156860, 'itIT', '', 'Amalia, di\' a Nathanos dei Saggi delle Maree.', 28153),
(156859, 'itIT', '', 'Aiutano... trovare... relitti...', 28153),
(156858, 'itIT', '', 'Saggi delle Maree... Sacerdoti... del mare...', 28153),
(156857, 'itIT', '', 'Ah, penso che potremmo farcela noi.', 28153),
(156856, 'itIT', 'Disperso in mare? Dobbiamo recuperare il suo corpo!', '', 28153),
(156855, 'itIT', '', 'Maresciallo M. Valentine... vincitore della Seconda Guerra... disperso in mare...', 28153),
(156854, 'itIT', 'Voglio tornare alla Baia di Tiragarde.', 'Voglio tornare alla Baia di Tiragarde.', 28153),
(156853, 'itIT', 'Terrò le vele pronte, mentre tu vai là fuori a fare le tue cose.', '', 28153),
(156851, 'itIT', 'DOV\'È IL CORPO?', '', 28153),
(156850, 'itIT', 'Aspetta... Cos\'è questo?', '', 28153),
(156849, 'itIT', 'Valentine... Ci sei sfuggito per parecchio tempo.', '', 28153),
(156848, 'itIT', 'Non facciamo aspettare Valentine.', '', 28153),
(156847, 'itIT', 'Tigrotron attivato... Argh!', '', 28153),
(156846, 'itIT', 'Ma che... Non siamo pronti!', '', 28153),
(156845, 'itIT', 'Nulla può resistere a Tigrotron!', '', 28153),
(156844, 'itIT', 'Cinque felini si uniscono per formare una supertigre!', '', 28153),
(156843, 'itIT', 'La tua presa non proteggerà più questo vascello!', '', 28153),
(156842, 'itIT', 'Vattene, oscurità immonda!', '', 28153),
(156841, 'itIT', 'Che le Maree consumino la tua carne corrotta.', '', 28153),
(156840, 'itIT', '', 'Non lasciare che facciano del male a Dot!!!', 28153),
(156839, 'itIT', '', 'Aiuto!', 28153),
(156838, 'itIT', 'Fai rotta verso Vol\'dun.', 'Fai rotta verso Vol\'dun.', 28153),
(156837, 'itIT', 'Uff! Anche se è morto, infesterà ancora i miei sogni.', '', 28153),
(156836, 'itIT', 'È una... cosa! Uccidila! Bruciala col fuoco!', '', 28153),
(156835, 'itIT', '|A:Warfront-AllianceWave3:25:23:0:0|aUna forza d\'assalto dell\'Alleanza è stata schierata!', '|A:Warfront-AllianceWave3:25:23:0:0|aUna forza d\'assalto dell\'Alleanza è stata schierata!', 28153),
(156834, 'itIT', 'I Sethrak hanno trovato la carovana di Meerah tra le dune. È tutta sola e potrebbe farle comodo un po\' di aiuto per affrontarli, se decidessero di attaccare.', '', 28153),
(156833, 'itIT', '', 'Come comandi. Sia fatto il volere della Dama Oscura.', 28153),
(156832, 'itIT', '', 'Riporta indietro quest\'uomo. È stato scelto per diventare un Reietto.', 28153),
(156831, 'itIT', 'Lilian, possiamo trovare altri Saggi delle Maree. Sai bene che la sua famiglia non lo accetterà.', '', 28153),
(156830, 'itIT', '', 'Lilian Voss. Perché mi hai chiamata?', 28153),
(156829, 'itIT', 'Un piccolo inconveniente. Fai in modo che non interferisca con i nostri piani.', '', 28153),
(156828, 'itIT', 'Desiderare è una parola grossa. È una cosa che... vorrei riuscire ad affrontare, per poter aiutare la mia famiglia.', '', 28153),
(156827, 'itIT', '', 'Con molto dolore.', 28153),
(156826, 'itIT', 'Ma parte di te è sopravvissuta, vero?', '', 28153),
(156825, 'itIT', '', 'Speriamo tu viva abbastanza a lungo da aiutarci a trovare Valentine.', 28153),
(156824, 'itIT', 'Andiamo!', 'Andiamo!', 28153),
(156823, 'itIT', '', 'È possibile richiedere immediatamente altre forze dell\'Orda. Ti basterà dare l\'ordine.', 28153),
(156822, 'itIT', 'Mpf. Sarà meglio.', '', 28153),
(156821, 'itIT', '', 'Nathanos, proseguite senza di noi. Me ne occupo io.', 28153),
(156820, 'itIT', '', 'Ferma!', 28153),
(156819, 'itIT', '', 'AHHHHHHHHHHH!', 28153),
(156818, 'itIT', '', 'Io... Non posso...', 28153),
(156817, 'itIT', '', 'Lo considero un buon inizio. Vediamo cos\'altro sei in grado di fare.', 28153),
(156816, 'itIT', 'Ci sono forze dell\'Alleanza e di Kul Tiras, nella Loggia dei Saggi. Stanno aspettando i rinforzi e sono vulnerabili in questo momento.', '', 28153),
(156815, 'itIT', 'La mia famiglia è al sicuro?', '', 28153),
(156814, 'itIT', '', 'Bene. Dimostra quanto puoi essere utile all\'Orda e decideremo quanto a lungo potrà ancora vivere tua moglie.', 28153),
(156813, 'itIT', 'Sono al sicuro. Aiutaci e ci assicureremo che rimangano tali.', '', 28153),
(156812, 'itIT', '<Tossisce> Io... Io farò tutto quello che posso, Dama Voss. Vuoi che rintracci qualcosa, giusto? Vediamo cosa riesco a fare senza il mio libro...', '', 28153),
(156811, 'itIT', '', 'Non mettere alla prova la mia pazienza, o ti farò desiderare di essere già morto. Devo capire quanto è forte la tua magia prima di proseguire.', 28153),
(156810, 'itIT', 'Dama Voss. Avevi ancora qualcuna delle malattie o dei tormenti che avevi in vita, quando sei rinata?', '', 28153),
(156809, 'itIT', '', 'Lilian Voss. E sono io che faccio le domande. Sei in grado di rintracciare delle persone? Degli oggetti?', 28153),
(156808, 'itIT', 'Una dei Reietti. Forse è un <Tossisce> segno. Dimmi, Dama...', '', 28153),
(156807, 'itIT', '', '$n ha ragione, più o meno. Non ti faremo del male se ci aiuterai, possibilmente prima di morire.', 28153),
(156806, 'itIT', 'La Dama Oscura veglia su di te.', '', 28153),
(156805, 'itIT', 'Mi servono dei rinforzi.', 'Mi servono dei rinforzi.', 28153),
(156804, 'itIT', 'Hai bisogno di rinforzi? Impartisci l\'ordine e organizzerò il trasporto da Roccavento.', '', 28153),
(156803, 'itIT', 'Abbiamo poco tempo da perdere. Cosa serve?', '', 28153),
(156802, 'itIT', 'Sei davvero difficile da uccidere... molto più di quell\'avversario.', '', 28153),
(156801, 'itIT', 'Ci stiamo muovendo senza un vero e proprio piano, quindi... occupati della minaccia e non farti uccidere.', '', 28153),
(156799, 'itIT', '%s morde il cibo fresco e croccante.', '', 28153),
(156798, 'itIT', '%s mastica entusiasticamente le foglie verdi.', '', 28153),
(156797, 'itIT', '%s seppellisce il naso nel cibo.', '', 28153),
(156796, 'itIT', 'Ti schiaccerò la testa!', 'Ti schiaccerò la testa!', 28153),
(156795, 'itIT', 'Chi vuole essere il prossimo a morire?', 'Chi vuole essere il prossimo a morire?', 28153),
(156794, 'itIT', 'Andiamo!', 'Andiamo!', 28153),
(156793, 'itIT', '[CUTSCENE] - Jaina Arrives! Her forces successfully blast through the wall of Lordaeron Keep! And btw it was *totally* cool.', '[CUTSCENE] - Jaina Arrives! Her forces successfully blast through the wall of Lordaeron Keep! And btw it was *totally* cool.', 28153),
(156792, 'itIT', '[CUTSCENE] - Sylvanas is waiting in the throne room when Anduin arrives. Anduin offers her the chance to surrender. Instead, she  blows up the entire city. I mean, what did you expect?', '[CUTSCENE] - Sylvanas is waiting in the throne room when Anduin arrives. Anduin offers her the chance to surrender. Instead, she  blows up the entire city. I mean, what did you expect?', 28153),
(156791, 'itIT', '', 'Se riuscissi a riportare Kul Tiras tra le file dell\'Alleanza...', 28153),
(156790, 'itIT', '', 'La mia gente controlla la più potente flotta di tutta Azeroth.', 28153),
(156789, 'itIT', '', 'È un incantesimo piuttosto semplice, a patto che il soggetto collabori.', 28153),
(156788, 'itIT', '', 'Tieni, bevi questo.', 28153),
(156787, 'itIT', '', 'Sì, sì, Amalia. Dammi un secondo...', 28153),
(156786, 'itIT', 'Sono qui per chiederti aiuto, non per ucciderti.', 'Sono qui per chiederti aiuto, non per ucciderti.', 28153),
(156785, 'itIT', '<Tossisce> L\'Orda. Pensavo che qui sarei morto in pace.\n\nBe\'? Cosa stai aspettando?', '', 28153),
(156784, 'itIT', '', 'Ehi, $n, vicino al segatronchi.', 28153),
(156783, 'itIT', 'Se vogliamo l\'aiuto di questo Saggio delle Maree, dobbiamo sbrigarci.', '', 28153),
(156782, 'itIT', '', 'Qualsiasi cosa facciate, non può essere peggio della malattia... È andato verso est, per morire in pace lontano dai nostri figli. Lasciateci stare.', 28153),
(156781, 'itIT', 'Voglio solo sapere dove si trova tuo marito. Ti prometto che a nessuno di voi verrà fatto del male.', '', 28153),
(156780, 'itIT', '', 'L\'Orda... Cos\'altro siete venuti a prendermi? Mio marito sta morendo, io sono senza un soldo... Lasciate in pace i miei figli, vi prego.', 28153),
(156779, 'itIT', 'Non c\'è alcun onore in questo. Possiamo semplicemente chiedere. Non vogliamo fare del male a una madre ferita.', '', 28153),
(156778, 'itIT', 'Meglio tenersi a distanza!', '', 28153),
(156777, 'itIT', 'Usiamo l\'artiglieria pesante.', '', 28153),
(156776, 'itIT', 'Hai invocato il tuono!', '', 28153),
(156775, 'itIT', 'Illumina il bersaglio...', '', 28153),
(156774, 'itIT', 'Adoro il mio lavoro.', '', 28153),
(156773, 'itIT', 'Ah ah! Pare che quel coso abbia trovato pane per i suoi denti!', '', 28153),
(156772, 'itIT', 'Il cagnone ha rotto la catena.', '', 28153),
(156771, 'itIT', 'Non sapranno mai cosa li ha colpiti.', '', 28153),
(156770, 'itIT', 'Qualcuno ha chiamato un riconfiguratore?', '', 28153),
(156769, 'itIT', 'Questa ti piacerà!', '', 28153),
(156768, 'itIT', 'AR-8 operativo.', '', 28153),
(156767, 'itIT', 'Reggetevi, stiamo per ballare un po\'.', '', 28153),
(156766, 'itIT', 'Siamo sulla rotta al cento per cento.', '', 28153),
(156765, 'itIT', '', 'Hnngh...', 28153),
(156764, 'itIT', '', 'Prima raccoglierai i fiori, prima Amalia potrà essere di qualche utilità.', 28153),
(156763, 'itIT', 'Ho sentito storie di vermi giganti che si nutrono di marciume e che stanno scatenando il caos in superficie. Se dovessimo trovarne uno, dobbiamo ucciderlo!', '', 28153),
(156762, 'itIT', 'Ottimo lavoro nel salvare quei bambini. Immagino che ora vogliano tutti scappare per diventare come te!', '', 28153),
(156761, 'itIT', 'Dei bambini di Flussomorto pensavano di poter scappare e diventare pirati, ma sono finiti prigionieri dei Marferreo! Devi aiutarci a salvarli!', '', 28153),
(156760, 'itIT', '', 'Pssst... $n, vieni qui!', 28153),
(156759, 'itIT', '', 'Un mostro in meno a terrorizzare la gente mia in superficie. I Loa saranno compiaciuti delle azioni tue.', 28153),
(156758, 'itIT', '', 'Ho sentito che i vermi si nutrono del marciume e stanno scatenando il caos in superficie. Dobbiamo acciderne il più possibile!', 28153),
(156757, 'itIT', 'Dicevano che ci sarebbero state delle caramelle.', 'Sono un pirata ora?', 28153),
(156756, 'itIT', 'Ascolta, capo. So che stai finanziando questa spedizione, ma Gallywix farà di tutto per assicurarsi che la Dama Oscura riceva la sua parte.', '', 28153),
(156755, 'itIT', 'Mi serve un passaggio per il Cimitero di Poggiostretto.', 'Mi serve un passaggio per il Cimitero di Poggiostretto.', 28153),
(156754, 'itIT', '', 'Ho i razzi più sicuri di tutta Kul Tiras!$b$bNon farti influenzare dal mio cognome.', 28153),
(156753, 'itIT', 'Ritirata! Combatteremo n\'altro giorno.', '', 28153),
(156752, 'itIT', 'Zandalari, ripiegate e raggruppatevi! Nun possiamo lasciarli vivere n\'altro giorno.', '', 28153),
(156751, 'itIT', 'Distruggete chesti invasori!', '', 28153),
(156750, 'itIT', 'Sei debole!', '', 28153),
(156749, 'itIT', 'La morte tua è vicina!', '', 28153),
(156748, 'itIT', 'Sono il Pirata del Terrore Beuford! Non ci saranno sopravvissuti!', 'Credo di vedere il mio gatto!', 28153),
(156747, 'itIT', 'Salta nella tempesta, così porremo fine a tutto questo.', '', 28153),
(156746, 'itIT', 'Tu non sei un pirata!', 'Dicevano che mi avrebbero dato un cappello!', 28153),
(156745, 'itIT', 'Argh! Dammi del rum!', 'Che cos\'è un cassero di poppa?', 28153),
(156744, 'itIT', '', 'Bene, non sporcarti le mani.', 28153),
(156743, 'itIT', 'Voglio tornare a Zuldazar.', 'Voglio tornare a Zuldazar.', 28153),
(156742, 'itIT', 'Terrò spiegate le vele, così potremo andarcene in fretta. Vai a prendere chell\'Azerite!', '', 28153),
(156741, 'itIT', '', 'Ci penso io al cadavere, $n. Tu torna da Nathanos, fagli sapere che tutto sta procedendo secondo i piani.', 28153),
(156740, 'itIT', 'Non intendo dare il mio aiuto nel rendere quest\'uomo un Reietto. Occupatene tu.', 'Non intendo dare il mio aiuto nel rendere quest\'uomo un Reietto. Occupatene tu.', 28153),
(156739, 'itIT', '', 'Imparerai ad accettarlo, e io ti aiuterò a farlo.', 28153),
(156738, 'itIT', 'Non ho bisogno di essere salvato!', 'Ora sono una piratessa. Non ho bisogno di ascoltarti.', 28153),
(156737, 'itIT', '', 'Tu sei $guno:una; di noi ora. Non ti accetteranno mai.', 28153),
(156736, 'itIT', 'Lilian, uccidi Zelling.', 'Lilian, uccidi Zelling.', 28153),
(156735, 'itIT', '', 'Stone, capisco quello che stai passando. Non riesci ad accettare questo cambiamento, com\'è successo a me.', 28153),
(156734, 'itIT', 'Non vale! Sarei dovuto diventare un pirata.', 'Grettly mi ha venduta ai pirati!', 28153),
(156733, 'itIT', 'Lilian, fai ciò che devi con Zelling.', 'Lilian, fai ciò che devi con Zelling.', 28153),
(156732, 'itIT', '', 'Vedremo. Forse questa volta sarà diverso.', 28153),
(156731, 'itIT', '', 'Terribile. Quelli che non ti eviteranno, non ti tratteranno comunque mai più come prima. Ti guarderai allo specchio e vedrai un mostro, una cosa che non sei tu.', 28153),
(156730, 'itIT', 'Ti prego... devo... prendermi cura... della mia famiglia... a qualsiasi costo.', '', 28153),
(156729, 'itIT', '', 'Sarebbe terribile se diventassi uno di noi. Ti guarderesti allo specchio e non vedresti nient\'altro che un mostro.', 28153),
(156728, 'itIT', 'Dama Voss, <Tossisce> ti prego... riportami indietro... Devo aiutare la mia famiglia... Farò qualsiasi cosa... Qualsiasi cosa...', '', 28153),
(156727, 'itIT', '', 'Cosa? La tua famiglia crederà che sei un mostro, non essere ridicolo!', 28153),
(156726, 'itIT', '', 'Bene. C\'è una cosa che vorrei sapere.', 28153),
(156725, 'itIT', '<Ansima> Mi... dispiace. Non... posso... Non mi resta più nulla...', '', 28153),
(156724, 'itIT', '', 'Zelling! Dannazione a te, ci servi vivo!', 28153),
(156723, 'itIT', 'Sì! La vita eterna, finalmente. Sono pronto!', '', 28153),
(156722, 'itIT', '', 'Molto bene, Zelling. Hai capito, capito VERAMENTE, cosa succederà adesso?', 28153),
(156721, 'itIT', 'Lavoro eccellente. Gli hai mostrato come facciamo le cose qui nella valle.', '', 28153),
(156720, 'itIT', 'Gli esploratori parlano di una nuova minaccia nella zona. Eliminala, prima che diventi un problema più grosso.', '', 28153),
(156719, 'itIT', 'Fai attenzione, Jaina. Che la Luce sia con te.', '', 28153),
(156718, 'itIT', '', 'Tornerò con la flotta... o non tornerò affatto.', 28153),
(156717, 'itIT', 'Sarà difficile... e pericoloso.', '', 28153),
(156716, 'itIT', 'Credo di sì... E credo tu possa riuscirci.', '', 28153),
(156715, 'itIT', '', 'Affrontare il problema è l\'unico modo per farli tornare sui loro passi.', 28153),
(156714, 'itIT', 'Jaina, tu sei il motivo per cui hanno abbandonato l\'Alleanza.', '', 28153),
(156713, 'itIT', '', 'Allora dobbiamo cercare alleati anche noi.', 28153),
(156710, 'itIT', '', 'Mostraci... mostraci cos\'è accaduto...', 28153),
(156709, 'itIT', 'Se l\'Orda si allea con gli Zandalari, non ci sarà modo di fermarla.', '', 28153),
(156708, 'itIT', 'Impossibile! Dev\'essere uno dei trucchetti di Sylvanas. Deve esserlo...', '', 28153),
(156707, 'itIT', 'E... un\'enorme flotta Zandalari.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156706, 'itIT', 'I sopravvissuti dicono di aver incontrato una strana e terrificante forma di magia.', '', 28153),
(156705, 'itIT', 'Solo uno è tornato.', '', 28153),
(156704, 'itIT', 'Ne sono al corrente. E le otto navi da guerra che abbiamo mandato a inseguirli?', '', 28153),
(156703, 'itIT', 'Una principessa e un profeta.', '', 28153),
(156702, 'itIT', 'Recentemente, degli agenti dell\'Orda sono entrati nelle segrete e hanno liberato due prigionieri Zandalari.', '', 28153),
(156701, 'itIT', 'Jaina, forse potresti aiutarci a vedere ciò a cui ha assistito questo sopravvissuto.', '', 28153),
(156700, 'itIT', 'Molti viaggiatori sono stati uccisi in questo posto. Devi eliminare chiunque sia dietro questi attacchi.', '', 28153),
(156699, 'itIT', 'Ci siamo tutti. Che notizie porti, Maestro delle Spie?', '', 28153),
(156698, 'itIT', 'Un lavoro fantastico! Sapevo di poter contare su di te per difenderci.', '', 28153),
(156697, 'itIT', 'Dopo piglierò n\'aeronave. E la chiamerò come il figlio mio!', '', 28153),
(156696, 'itIT', 'Chesta l\'ho rubata io! L\'ho chiamata Destino di Mala... Mala, come la figlia mia!', '', 28153),
(156695, 'itIT', 'Quando mi hanno detto che avremmo avuto a che fare con dei pirati, mi sono detto che c\'era bisogno di na nave pirata!', '', 28153),
(156694, 'itIT', 'I Naga stanno architettando qualcosa!', '', 28153),
(156693, 'itIT', 'Sì... Eternità...!', '', 28153),
(156692, 'itIT', 'Quando sei $gpronto:pronta; ad andare, usa la corda. Voglio mostrarti la barca mia!', '', 28153),
(156691, 'itIT', '', 'Il prossimo di voi che si lamenta è morto!', 28153),
(156690, 'itIT', '', 'Lavorate più in fretta, patetici vermi!', 28153),
(156689, 'itIT', '', 'Più lavoro, meno chiacchiere! Quest\'Azerite non si estrarrà da sola!', 28153),
(156688, 'itIT', '', 'E quello tu lo chiami lavoro? I tuoi cani sono fortunati che non vi stiamo pagando un centesimo!', 28153),
(156687, 'itIT', '', 'Tornate al lavoro, cani! Datevi da fare!', 28153),
(156686, 'itIT', 'Ti prego, uccidimi! Consegnami all\'eternità come Reietto!', '', 28153),
(156685, 'itIT', 'So che stavi rubando dalla compagnia. Sono qui per assicurarmi che non accada di nuovo.', 'So che stavi rubando dalla compagnia. Sono qui per assicurarmi che non accada di nuovo.', 28153),
(156684, 'itIT', 'Vuoi botte? Fatti gli affari tuoi!', 'Vuoi botte? Fatti gli affari tuoi!', 28153),
(156683, 'itIT', 'Continua a camminare! Non c\'è nulla da vedere...', 'Continua a camminare! Non c\'è nulla da vedere...', 28153),
(156682, 'itIT', 'Cos\'hai da guardare?', 'Cos\'hai da guardare?', 28153),
(156681, 'itIT', '<Tossisce> Dama Voss, come sei diventata una Reietta?', '', 28153),
(156680, 'itIT', 'I ladri dell\'Orda stanno rubando l\'Azerite dalla Compagnia dei Bracescura. Schiaccia i nostri nemici e reclama il minerale in nome della VII Legione!', '', 28153),
(156679, 'itIT', 'Rubo solamente per riempire il cuore di qualcuno che non ha mai conosciuto l\'amore!', 'Rubo solamente per riempire il cuore di qualcuno che non ha mai conosciuto l\'amore!', 28153),
(156678, 'itIT', 'È stata la mia scarsa educazione a farmelo fare!', 'È stata la mia scarsa educazione a farmelo fare!', 28153),
(156677, 'itIT', 'Non lo farò più, promesso!', 'Non lo farò più, promesso!', 28153),
(156676, 'itIT', 'Quel lupo di mare di un Harrington ha chiamato la cavalleria!', 'Quel lupo di mare di un Harrington ha chiamato la cavalleria!', 28153),
(156675, 'itIT', 'Ho smesso di rubare! Non lo faccio più!', 'Ho smesso di rubare! Non lo faccio più!', 28153),
(156674, 'itIT', 'Non uccidermi, ti prego! Non ruberò mai più!', 'Non uccidermi, ti prego! Non ruberò mai più!', 28153),
(156673, 'itIT', 'I nostri soldati sono tenuti in ostaggio dagli esiliati di Zuldazar. Noi non negoziamo con gli alleati dell\'Orda. Mostra loro la vera forza dell\'Alleanza!', '', 28153),
(156672, 'itIT', 'Un lavoro pulito. Ben fatto.', '', 28153),
(156671, 'itIT', 'Le nostre spie hanno localizzato un piccolo accampamento di truppe dell\'Orda tra le dune. Colpisci con rapidità e decima le forze nemiche!', '', 28153),
(156670, 'itIT', 'È stato davvero un piacere fare affari con te. Se mai ti interessasse un lavoro come pirata, la mia ciurma sarebbe pronta ad accoglierti!', '', 28153),
(156669, 'itIT', 'Sono un uomo di parola, $C. Lo scrigno del Capitano è tutto tuo!', '', 28153),
(156668, 'itIT', 'Ti raggiungerò negli alloggi del capitano, una volta che Hartford sarà morto. Non preoccuparti dello scrigno, tutto ciò che c\'è all\'interno sarà nostro!', '', 28153),
(156667, 'itIT', '', 'Non abbiamo ancora finito. Hai molte informazioni, ma dobbiamo capire quanto tu sia forte.', 28153),
(156666, 'itIT', 'Ti prego! Basta con tutto questo. Il tuo campione ha portato caos e distruzione nella Loggia dei Saggi. Rendimi un Reietto!', '', 28153),
(156665, 'itIT', '', 'Abbiamo sbagliato... ad aiutare l\'Alleanza?', 28153),
(156664, 'itIT', '', 'L\'Orda non spezzerà mai la volontà di Kul Tiras!', 28153),
(156663, 'itIT', 'Il libro... Gettalo... in mare...', '', 28153),
(156662, 'itIT', 'Non puoi prendere questo libro! È troppo pericoloso!', '', 28153),
(156661, 'itIT', '', 'Moriresti prima del tuo prossimo patetico colpo di tosse, Zelling. Vuoi mettermi alla prova?', 28153),
(156660, 'itIT', '<Ansima> Non hai paura che io possa attaccarti? Non cerchi nemmeno di scappare?', '', 28153),
(156659, 'itIT', 'Anche il Capitano Stone è impazzito quando si è trasformato? So benissimo cosa è successo.', '', 28153),
(156658, 'itIT', '', 'Diventare Reietti è un processo imprevedibile. Sia il corpo che la mente cambiano, ma fino a che punto... è impossibile da sapere. Così come con che facilità sopporterai l\'intero processo.', 28153),
(156657, 'itIT', 'No, ma posso chiederti una cosa? Quando si diventa Reietti, si viene purificati da qualsiasi malattia?', '', 28153),
(156656, 'itIT', 'Con te al mio fianco, sarò un passo più vicino ad andarmene da questo dannato deserto!', '', 28153),
(156655, 'itIT', 'Troviamoci al Porto dei Rocciarossa quando il lavoro sarà finito.', '', 28153),
(156654, 'itIT', 'Be\', è stato... ingegnoso.', '', 28153),
(156653, 'itIT', 'I nostri alleati non possono portare a termine le loro missioni con L\'Orda che si aggira in queste rovine. I Ferroscuro sanno come fare.', '', 28153),
(156652, 'itIT', '2 minuti alla Battaglia per Stromgarde.', '', 28153),
(156651, 'itIT', 'Credo di aver perso il mio splendido cappello.', 'Credo di aver perso il mio splendido cappello.', 28153),
(156650, 'itIT', 'Portaci alla Valle dei Sacraonda.', 'Portaci alla Valle dei Sacraonda.', 28153),
(156649, 'itIT', 'Ben fatto. Vediamo se c\'è qualcosa di utile.', '', 28153),
(156648, 'itIT', 'Queste rovine sembrano appartenere a un tempio che fu inghiottito dal mare. Anche la presenza dei Naga è un problema. Buona fortuna con la tua perlustrazione.', '', 28153),
(156647, 'itIT', 'Sono pronto a parlare, Ty\'jin.', 'Sono pronta a parlare, Ty\'jin.', 28153),
(156646, 'itIT', 'Fammi sapere quando vuoi iniziare, cumpà!', '', 28153),
(156645, 'itIT', 'Ottimo lavoro. Meglio affrontare subito una minaccia, prima che diventi troppo grossa.', '', 28153),
(156644, 'itIT', 'I nostri esploratori hanno scoperto un\'infestazione di Murloc. Non possiamo rischiare che aumentino di numero e ci colgano alla sprovvista.', '', 28153),
(156643, 'itIT', '', 'Ben fatto! I Loa ti arridono.', 28153),
(156642, 'itIT', '', 'La S.P.R. & Co. sta rovinando la terra con le azioni sue. I Loa nun ne saranno contenti. Poni fine alle attività loro e fa\' nu poco di pulizia.', 28153),
(156641, 'itIT', '', 'Ben fatto! Chei Tortolliani si ricorderanno di chi li ha salvati dal destino loro.', 28153),
(156640, 'itIT', '', 'Ho saputo che i Naga di cheste spiagge tengono i Tortolliani prigionieri per motivi ignoti. Nun devi permetterglielo! Accidi i Naga e libera i Tortolliani.', 28153),
(156639, 'itIT', 'I Saggi delle Maree sono soliti guidare le anime perdute in mare... ma non così.', '', 28153),
(156637, 'itIT', 'Ottimo lavoro. Speriamo che i Tortolliani si ricordino di questo quando avremo bisogno di loro!', '', 28153),
(156636, 'itIT', 'Sono pronto a far vela verso Lordaeron.', 'Sono pronta a far vela verso Lordaeron.', 28153),
(156635, 'itIT', 'La S.P.R. & Co. sta combinando disastri lungo la costa. Guadagniamoci il favore dei Tortolliani facendo un po\' di pulizia.', '', 28153),
(156634, 'itIT', '', 'La scuola è finita... Per sempre...', 28153),
(156633, 'itIT', '', 'Ti insegnerò una lezione!', 28153),
(156632, 'itIT', 'Ottimo lavoro. Non oso immaginare cosa avessero in mente per quei Tortolliani.', '', 28153),
(156631, 'itIT', 'Gli esploratori dicono che i Naga della zona stanno facendo prigionieri i Tortolliani. Qualsiasi cosa stiano progettando, dobbiamo fermarli.', '', 28153),
(156630, 'itIT', '', 'Combatti come una mucca!', 28153),
(156629, 'itIT', 'Ben fatto! Siamo un passo più vicini alla vittoria!', '', 28153),
(156628, 'itIT', 'Questo terrà sotto controllo il loro numero, per ora. Ben fatto.', '', 28153),
(156627, 'itIT', 'Le Vipere Piumate sono conosciute per la loro aggressività, ma la cosa sta sfuggendo di mano! Distruggi subito le loro uova.', '', 28153),
(156626, 'itIT', 'Queste andranno benissimo. I nostri soldati feriti saranno grati per il tuo aiuto.', '', 28153),
(156625, 'itIT', 'Dobbiamo fare buon uso delle risorse della zona. Ottieni delle ghiandole salivari dagli pterrordattili selvatici. Le loro proprietà rigenerative potrebbero aiutare i nostri feriti.', '', 28153),
(156624, 'itIT', 'Ora capisco perché quei devasauri possono mangiare quasi tutto! Saranno sfruttati a dovere. Grazie mille.', '', 28153),
(156623, 'itIT', 'Abbiamo bisogno di provviste più resistenti e si dice che i devasauri di questa terra abbiano degli stomaci capaci di resistere a tutto. Ti andrebbe di recuperarne un po\'?', '', 28153),
(156622, 'itIT', 'Arghhh... tornatene... negli abissi di Neptulon...', '', 28153),
(156621, 'itIT', 'Cos\'è questo... ammutinamento? Sparisci, maiale!', '', 28153),
(156620, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(156619, 'itIT', '', 'La mia ricerca è completata, per ora. Grazie per l\'aiuto.', 28153),
(156618, 'itIT', '', 'Questo insegnerà all\'Orda che non deve interferire! Questa magia non dovrà mai cadere nelle loro mani...', 28153),
(156617, 'itIT', '', 'Il tuo aiuto è molto apprezzato. Questa barriera è così forte...', 28153),
(156616, 'itIT', 'L\'immortalità è a portata di mano! Non vedo l\'ora di diventare un Reietto. Immagina le possibilità!\n\nQuando hai un momento, devi dirmi cosa si prova. La non morte, l\'eternità, avere il mondo a portata di mano!', '', 28153),
(156615, 'itIT', 'Mi rifiuto di lasciare che la mia vita finisca a causa di qualche... malattia. Devo vivere per tenere la mia famiglia al sicuro.', '', 28153),
(156614, 'itIT', 'Non disturbare i morti, $R.', '', 28153),
(156613, 'itIT', '', 'Mi farebbe comodo un piccolo aiuto!', 28153),
(156612, 'itIT', 'Se non si va avanti, alla fine si rimane indietro. È quello che dico sempre!', '', 28153),
(156611, 'itIT', '', 'Dovrò fare alcune prove e recuperare dati. Tieni gli occhi aperti, in caso qualcuno interferisca.', 28153),
(156610, 'itIT', '', 'Forse potremmo sfruttarla, o addirittura replicarla.', 28153),
(156609, 'itIT', '', 'Questa magia è affascinante! È diversa da qualsiasi cosa io abbia mai visto.', 28153),
(156608, 'itIT', '', 'Non è finita qui!', 28153),
(156607, 'itIT', 'Ma tieni tempo da perdere?', '', 28153),
(156606, 'itIT', 'Ho bisogno di un nuovo travestimento.', 'Ho bisogno di un nuovo travestimento.', 28153),
(156605, 'itIT', 'L\'Orda è qui, scappate! Esiste qualche posto ancora sicuro?!?', 'L\'Orda è qui, scappate! Esiste qualche posto ancora sicuro?!?', 28153),
(156604, 'itIT', 'Fantastico! Altri problemi con l\'Orda proprio ora che è arrivata l\'Alleanza!', 'Fantastico! Altri problemi con l\'Orda proprio ora che è arrivata l\'Alleanza!', 28153),
(156603, 'itIT', 'Non rischierò la vita se l\'Orda si trova già qui!', 'Non rischierò la vita se l\'Orda si trova già qui!', 28153),
(156602, 'itIT', 'Scappiamo! È questo che ci meritiamo per aver aiutato l\'Alleanza!', 'Scappiamo! È questo che ci meritiamo per aver aiutato l\'Alleanza!', 28153),
(156601, 'itIT', 'Credevo fossimo al sicuro dall\'Orda!', 'Credevo fossimo al sicuro dall\'Orda!', 28153),
(156600, 'itIT', 'Come fa a trovarsi qui l\'Orda?', 'Come fa a trovarsi qui l\'Orda?', 28153),
(156599, 'itIT', 'L\'Orda! Via!', 'L\'Orda! Via!', 28153),
(156598, 'itIT', 'This is test text, I say things in it.', '', 28153),
(156597, 'itIT', '', 'Arrivederci, Nathanos.', 28153),
(156596, 'itIT', '', '<Sylvanas fa per andarsene, poi esita e guarda indietro da sopra la spalla.>', 28153),
(156595, 'itIT', 'Non ti deluderemo. Buon viaggio, mia signora.', '', 28153),
(156594, 'itIT', '', 'Eseguite e mandatemi i rapporti sui vostri progressi.', 28153),
(156593, 'itIT', 'Come comandate, Capoguerra.', '', 28153),
(156592, 'itIT', '', 'Bene. Scegliete un luogo dove edificare il primo accampamento.', 28153),
(156591, 'itIT', 'Sì, mia signora. La Lamento della Banshee è pronta a partire in qualunque momento.', '', 28153),
(156590, 'itIT', '', 'È tutto in ordine?', 28153),
(156589, 'itIT', '<Nathanos si inchina profondamente.>', '', 28153),
(156588, 'itIT', 'Mia Regina.', '', 28153),
(156587, 'itIT', 'La tua presenza è richiesta sulla Lamento della Banshee. La Dama Oscura ci ha dato l\'ordine di iniziare la campagna sulle coste di Kul Tiras.', '', 28153),
(156586, 'itIT', '', 'Seguimi.', 28153),
(156585, 'itIT', '', 'Campione.', 28153),
(156584, 'itIT', 'A supervisione della squadra c\'è Garona Mezzorco. Sarà lei a guidare le missioni con il tuo aiuto.', '', 28153),
(156583, 'itIT', 'Abbiamo radunato un gruppo d\'élite per eseguire gli ordini della Dama Oscura.', '', 28153),
(156582, 'itIT', 'Bel lavoro là fuori!', '', 28153),
(156581, 'itIT', 'L\'Orda è stata avvisata della nostra presenza e sta inviando truppe ad attaccarci. Devi intervenire, così da permettere agli ispettori di completare la missione!', '', 28153),
(156580, 'itIT', '', 'Be\', penso che potrei prendere in considerazione la cosa, Zelling, ma solo se dimostrerai di essere degno dell\'Orda.', 28153),
(156579, 'itIT', 'Mi chiamo Thomas Zelling e sono un Saggio delle Maree, un saggio ILLUMINATO! Farò qualsiasi cosa, anche aiutarti ad attaccare l\'Alleanza, ma ti prego, ti scongiuro, rendimi un Reietto!', '', 28153),
(156578, 'itIT', 'Pare che la carovana sia giunta a casa sana e salva. La tua ricompensa ti attende nella Fortezza.', '', 28153),
(156577, 'itIT', '', 'Chi sei? Perché pensi di meritare un tale dono?', 28153),
(156576, 'itIT', 'Finalmente, una Reietta! Ti prego, uccidimi, rendimi un Reietto... Dammi il dono dell\'immortalità!', '', 28153),
(156575, 'itIT', '', 'Potrei provare a minacciare la donna, magari potrebbe darci qualche dettaglio...', 28153),
(156574, 'itIT', 'Il Vuoto, gli elementi... <tossisce> Nulla può fermare questa maledetta malattia. Perché deve finire così?', '', 28153),
(156573, 'itIT', 'Mmm, il Saggio delle Maree era qui tempo fa. L\'ho visto proteggere e servire la su famiglia.', '', 28153),
(156572, 'itIT', 'Qualche indizio su dove potremmo trovare un Saggio delle Maree?', 'Qualche indizio su dove potremmo trovare un Saggio delle Maree?', 28153),
(156571, 'itIT', 'Abbiamo notato l\'Orda spostare rifornimenti lungo il campo di battaglia. Balinda sta cercando volontari che l\'aiutino... a rifornire le nostre riserve.', '', 28153),
(156570, 'itIT', 'Abbiamo ricevuto rapporti dagli esploratori dell\'Orda vicino alla miniera. Parla con Genny all\'Officina per avere altre informazioni.', '', 28153),
(156569, 'itIT', 'Genny avrebbe bisogno di una mano all\'Officina. I rifornimenti stanno scarseggiando.', '', 28153),
(156568, 'itIT', 'Ci sono soldi da fare e nuove terre da sfruttare...$B$BQuesti sì che sono tempi emozionanti!', '', 28153),
(156567, 'itIT', 'No.', '', 28153),
(156566, 'itIT', 'Misha, stai qui. Noi troveremo questo Saggio delle Maree così Lilian potrà... fare qualsiasi cosa abbia in mente.', '', 28153),
(156565, 'itIT', '', 'Non ti interessano i dettagli, Rexxar?', 28153),
(156564, 'itIT', 'Sono pronto a raggiungere Sepulcra.', 'Sono pronta a raggiungere Sepulcra.', 28153),
(156563, 'itIT', '', 'Albamorta non esiste più. Ti porterò al Distretto dei Maghi per incontrare il Gran Supremo, non appena sei $gpronto:pronta;.', 28153),
(156562, 'itIT', '', 'Campioni, l\'ora è giunta. L\'Alleanza cadrà sotto i colpi delle nostre lame nel disperato tentativo di conquistare la Fortezza di Lordaeron.', 28153),
(156560, 'itIT', 'Campioni dell\'Alleanza, è giunta l\'ora di riprendere ciò che ci spetta! L\'attacco finale alla Fortezza di Lordaeron avrà inizio all\'alba. L\'Orda intera e la sua Capoguerra dovranno rispondere dei loro crimini!', '', 28153),
(156559, 'itIT', '', 'Puoi trovare il Nobile Oscuro amico tuo nella Sala dei Percorsi Antichi. Vieni da me quando hai finito di guardarti in giro.', 28153),
(156558, 'itIT', '', 'Il padre mio tiene molti dei tesori suoi accà nella tesoreria reale.', 28153),
(156557, 'itIT', '', 'Si dice che il Gran Sigillo sia una delle poche cose rimaste più antiche dell\'Impero degli Zandalari.', 28153),
(156556, 'itIT', '', 'Vieni, lascia che ti mostri il posto.', 28153),
(156555, 'itIT', 'Sarà meglio che te ne occupi tu.', '', 28153),
(156554, 'itIT', 'Ho perso il conto dei giorni che ho passato in questa cella, ma alla fine non ha importanza.', '', 28153),
(156553, 'itIT', 'Mi chiamo Sam... Sam Williams. È bello vedere qualcuno dalla nostra parte, finalmente.', '', 28153),
(156552, 'itIT', 'Questi pirati sono creature terribili. Uccidili dal primo all\'ultimo.', 'Questi pirati sono creature terribili. Uccidili dal primo all\'ultimo.', 28153),
(156551, 'itIT', 'Ma in che pasticcio siamo finiti?', 'Ma in che pasticcio siamo finiti?', 28153),
(156550, 'itIT', 'Non è l\'ultima volta che sentirete parlare di me, mostri!', 'Non è l\'ultima volta che sentirete parlare di me, mostri!', 28153),
(156549, 'itIT', 'Ho ucciso una dozzina di quei mostri, prima che avessero la meglio su di me!', 'Ho ucciso una dozzina di quei mostri, prima che avessero la meglio su di me!', 28153),
(156548, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(156547, 'itIT', 'Che nessuno rimanga indietro!', 'Che nessuno rimanga indietro!', 28153),
(156546, 'itIT', 'Sapevo che Sventradraghi non ci avrebbe abbandonati qua!', 'Sapevo che Sventradraghi non ci avrebbe abbandonati qua!', 28153),
(156545, 'itIT', 'Ti devo una birra, non appena saremo sulla barca.', 'Ti devo una birra, non appena saremo sulla barca.', 28153),
(156544, 'itIT', 'Non credevo potessero mangiare così tanto...', '', 28153),
(156543, 'itIT', 'I ranishu hanno un appetito insaziabile, ma delle menti semplici. Mangerebbero qualsiasi cosa sul loro cammino, inclusi i loro simili. Usiamo la loro fame a nostro vantaggio!', '', 28153),
(156542, 'itIT', '', '<Garona fa roteare le sue lame fino a far sembrare che scompaiano.>', 28153),
(156541, 'itIT', 'Queste aquile da guerra ci porteranno fino a destinazione. Salta su!', '', 28153),
(156540, 'itIT', 'Su, andiamo!', '', 28153),
(156539, 'itIT', 'La mia Regina ha previsto tutto. Il nostro trasporto ci aspetta ai bastioni.', '', 28153),
(156538, 'itIT', 'Volevo solo nu po\' del tesoro che tengono.', 'Volevo solo nu po\' del tesoro che tengono.', 28153),
(156537, 'itIT', 'Tornerò, pirati! Molto presto!', 'Tornerò, pirati! Molto presto!', 28153),
(156536, 'itIT', 'Accidi tutta chella ciurma di codardi!', 'Accidi tutta chella ciurma di codardi!', 28153),
(156535, 'itIT', 'Mi manca Zuldazar... Per quanto ancora mi toccherà soffrire accà?', 'Mi manca Zuldazar... Per quanto ancora mi toccherà soffrire accà?', 28153),
(156534, 'itIT', 'Accà nun vedo traccia di alcun tesoro. Erano tutte menzogne!', 'Accà nun vedo traccia di alcun tesoro. Erano tutte menzogne!', 28153),
(156533, 'itIT', 'Nun mi lasciano entrare nella ciurma loro! Nun è giusto.', 'Nun mi lasciano entrare nella ciurma loro! Nun è giusto.', 28153),
(156532, 'itIT', 'Nu raro esempio di gentilezza nel deserto.', 'Nu raro esempio di gentilezza nel deserto.', 28153),
(156531, 'itIT', 'Non pensavo che qualcuno sarebbe mai arrivato a salvarmi. Grazie, $gstraniero:straniera;.', 'Non pensavo che qualcuno sarebbe mai arrivato a salvarmi. Grazie, $gstraniero:straniera;.', 28153),
(156530, 'itIT', 'Si è aperto qualcosa.', '', 28153),
(156529, 'itIT', 'Ne mancano ancora...', '', 28153),
(156528, 'itIT', 'Credo siano tutti. Ottimo lavoro. Sapevo di poter contare su di te.', '', 28153),
(156527, 'itIT', 'Ci sono ancora molti Vulpera intrappolati nelle tane. Possiamo contare su di te per aiutarli a fuggire?', '', 28153),
(156526, 'itIT', '<Il Ripulitore Accuratamente Calibrato emette un breve ronzio non riuscendo a localizzare alcun fossile nelle vicinanze.>', '<Il Ripulitore Accuratamente Calibrato emette un breve ronzio non riuscendo a localizzare alcun fossile nelle vicinanze.>', 28153),
(156525, 'itIT', '<L\'Elementale degli Scavi borbotta infastidito non riuscendo a localizzare alcun fossile nelle vicinanze.>', '<L\'Elementale degli Scavi borbotta infastidito non riuscendo a localizzare alcun fossile nelle vicinanze.>', 28153),
(156524, 'itIT', '', 'Per Gilneas!', 28153),
(156523, 'itIT', '', 'Guardie, all\'attacco! Portatemi le loro teste!', 28153),
(156522, 'itIT', '|TINTERFACE\\ICONS\\SPELL_HOLY_DIVINEPROVIDENCE:20|t Il Guardiano dei Titani Hezrel inizia a lanciare |cFFF00000|Hspell:269310|h[Luce Purificante]|h|r!', '', 28153),
(156521, 'itIT', '', 'Quindi l\'Orda ha deciso di attaccarci qui? Be\', almeno mi risparmia la fatica di venirvi a cercare. Gilneani, all\'attacco!', 28153),
(156520, 'itIT', 'Ci sono molti più conti da fare di quanto pensassi. Torna più tardi per avere la tua fetta del tesoro.', '', 28153),
(156519, 'itIT', '', 'Questo è un lavoretto per cinque persone, proprio come per la banca di Forgiardente.', 28153),
(156518, 'itIT', 'Saremo degli eroi... eroi ricchissimi!', '', 28153),
(156517, 'itIT', 'Fammi diventare ricco, $p. Voglio comprarmi dei denti d\'oro!', '', 28153),
(156516, 'itIT', '', 'Come va il dente, Eddard?', 28153),
(156514, 'itIT', '', 'Ho fatto un sogno simile a questo, ma mi trovavo nella banca di Forgiardente.', 28153),
(156513, 'itIT', '', 'Quando avremo l\'oro, mi comprerò un sacco di profumo e mi ci farò il bagno dentro.', 28153),
(156512, 'itIT', 'Forse ci incontreremo di nuovo. Arrivederci!', '', 28153),
(156511, 'itIT', 'Siamo liberi...', '', 28153),
(156510, 'itIT', 'Dobbiamo... fuggire...', '', 28153),
(156509, 'itIT', '', 'Grazie per il tuo aiuto, $n. Io continuerò da un\'altra parte.', 28153),
(156508, 'itIT', '', 'Non farò finta di comprendere le tue motivazioni, $n, ma apprezzo la tua volontà di colpire un altro Cavaliere della Morte.', 28153),
(156507, 'itIT', '', 'Occhi in alto, $n! Percepisco qualcuno in avvicinamento!', 28153),
(156506, 'itIT', 'Come butta, $p?', 'Se riguarda dell\'oro, conta su di me!', 28153),
(156505, 'itIT', 'Ho bisogno del tuo aiuto.', 'Ho bisogno del tuo aiuto.', 28153),
(156504, 'itIT', 'Sono sopravvissuto al Re dei Lich solo per morire per mano vostra...', '', 28153),
(156503, 'itIT', 'Che spreco...', '', 28153),
(156502, 'itIT', 'Ho bisogno del tuo aiuto.', 'Ho bisogno del tuo aiuto.', 28153),
(156501, 'itIT', 'Hai vinto... drago...', '', 28153),
(156500, 'itIT', 'Una morte... definitiva...', '', 28153),
(156499, 'itIT', 'Non... vale...', '', 28153),
(156498, 'itIT', 'In tal caso mi prenderò ciò per cui sono venuto... con la forza!', '', 28153),
(156497, 'itIT', 'Ora capisco, $n! Vuoi essere l\'unico Cavaliere della Morte con una cavalcatura così bella!', '', 28153),
(156496, 'itIT', 'Ma avevo già posato lo sguardo su quell\'antica bestia d\'ossa dietro di te. Quindi, se non ti dispiace, mi riprendo ciò che è mio.', '', 28153),
(156495, 'itIT', 'Il draco sembra un po\' piccolo... e ancora in vita. Be\', non è certo un ostacolo.', '', 28153),
(156494, 'itIT', 'Sto seguendo i tuoi passi. Sei qui per assistermi? Vedo che hai portato un dono!', '', 28153),
(156493, 'itIT', '$gSignore della Morte:Signora della Morte; $n! Che sorpresa!', '', 28153),
(156492, 'itIT', 'Argh. Se preferisci le maniere forti, così sia!', '', 28153),
(156491, 'itIT', '', '$n, proteggimi! Il rituale deve essere completato!', 28153),
(156490, 'itIT', 'Fatti da parte, piccolo draco, ho degli affari in sospeso con quel cumulo d\'ossa.', '', 28153),
(156489, 'itIT', 'Credo che rimarrò col mio piano originale e procederò con l\'antico.', '', 28153),
(156488, 'itIT', 'Andiamocene di qui!', 'Andiamocene di qui!', 28153),
(156487, 'itIT', 'Un cavaliere magnifico come me dovrebbe avere solo le cavalcature migliori.', '', 28153),
(156486, 'itIT', 'Due draghi! Ma che sorpresa! Anche se quello ancora in vita è... minuscolo.', '', 28153),
(156485, 'itIT', '', 'Non sei $gil benvenuto:la benvenuta; qui, Cavaliere della Morte.', 28153),
(156484, 'itIT', 'Bene, bene... Cos\'abbiamo qui?', '', 28153),
(156483, 'itIT', 'I seguaci di Zul nun permetteranno che Rezan sfugga al destino suo così facilmente. Dobbiamo uscire da accà.\n\nSei $gpronto:pronta;?', '', 28153),
(156482, 'itIT', 'Perché questa fretta? Rallenta. Riprendi fiato... fatti un pisolino! Sei al sicuro con noi.', '', 28153),
(156481, 'itIT', 'È stato mio padre a insegnarmi la Forgiatura... Questo martello è stato il primo attrezzo che abbiamo creato insieme.', '', 28153),
(156480, 'itIT', 'Il mio martello! Me l\'hai riportato!', '', 28153),
(156479, 'itIT', '', 'Chesti esiliati sono la cosa più vicina a na famiglia che tengo.', 28153),
(156478, 'itIT', '', 'Ti do il benvenuto nella banda, $p.', 28153),
(156477, 'itIT', 'Ti do il benvenuto nella banda, $p.', '', 28153),
(156476, 'itIT', '', 'Ti do il benvenuto nella banda, $p.', 28153),
(156475, 'itIT', 'Ti do il benvenuto nella banda, $p.', '', 28153),
(156474, 'itIT', 'Vuoi qualcosa di forte da bere o qualcosa da mangiare?', 'Vuoi qualcosa di forte da bere o qualcosa da mangiare?', 28153),
(156473, 'itIT', 'Oh, sei tu $p? I Sabbiafurente nun ti hanno $gseguito:seguita;, vero?', '', 28153),
(156472, 'itIT', 'Ancora qualche altra carovana e poi razzieremo l\'arena per il vero bottino!', '', 28153),
(156471, 'itIT', 'Tengo sete! Andate a rubare nu po\' di chei gustosi alcolici Zandalari!', '', 28153),
(156470, 'itIT', 'Le legna sta scarseggiando. Trovatemi n\'altra carovana dei Vulpera da razziare!', '', 28153),
(156469, 'itIT', 'I deserti appartengono ai Sabbiafurente! Tutti li altri sono intrusi!', '', 28153),
(156468, 'itIT', 'Portatemi più schiavi. Tengo ancora nu un sacco di lance da scagliare.', '', 28153),
(156467, 'itIT', 'Colpiteli! Colpiteli come i cani che sono!', '', 28153),
(156466, 'itIT', 'Nun fai più il gradasso mo\', Zandalari arrogante!', '', 28153),
(156465, 'itIT', 'Ah! Ne ho pigliato uno! Dritto sul petto, lurido Vulpera...', '', 28153),
(156464, 'itIT', 'Rivuoi indietro il tuo martello, fetida patata pelosa? VIENI A PRENDERTELO.', '', 28153),
(156463, 'itIT', 'Elimineremo questa feccia di Kul Tiras dalle nostre terre! $n, raduna l\'Orda e poniamo fine a tutto questo.', '', 28153),
(156462, 'itIT', 'Dovresti badare alla lingua tua. Yazma è la Gran Sacerdotessa del Loa mio e l\'orecchio di Re Rastakhan.$b$bSe le voci sono vere, ci sta dell\'altro tra lei e il Grande Profeta Zul.', 'Dovresti badare alla lingua tua. Yazma è la Gran Sacerdotessa del Loa mio e l\'orecchio di Re Rastakhan.$b$bSe le voci sono vere, ci sta dell\'altro tra lei e il Grande Profeta Zul.', 28153),
(156461, 'itIT', 'Shadra è la Loa preferita dal Concilio delli Zanchuli, quindi i seguaci suoi, come me, godono di molti privilegi. Tra chesti ci sta il diritto di nun dover rispondere a persone come te.', 'Shadra è la Loa preferita dal Concilio delli Zanchuli, quindi i seguaci suoi, come me, godono di molti privilegi. Tra chesti ci sta il diritto di nun dover rispondere a persone come te.', 28153),
(156460, 'itIT', 'Dannazione a te...', 'Dannazione a te...', 28153),
(156459, 'itIT', 'Perderai...', 'Perderai...', 28153),
(156458, 'itIT', 'Mio Re... mi dispiace...', 'Mio Re... mi dispiace...', 28153),
(156457, 'itIT', 'La... pagherai...', 'La... pagherai...', 28153),
(156456, 'itIT', 'Per... l\'Alleanza...', 'Per... l\'Alleanza...', 28153),
(156455, 'itIT', 'I seguaci di Shadra hanno seguito la razza tua con grande interesse.$B$BOsserviamo l\'Orda inoltrarsi sempre più in profondità in na grande rete di bugie. Presto la trappola si chiuderà e nun ve ne accorgerete finché nun sarà troppo tardi.', 'I seguaci di Shadra hanno seguito la razza tua con grande interesse.$B$BOsserviamo l\'Orda inoltrarsi sempre più in profondità in na grande rete di bugie. Presto la trappola si chiuderà e nun ve ne accorgerete finché nun sarà troppo tardi.', 28153),
(156454, 'itIT', 'Muori!', 'Muori!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156453, 'itIT', 'Ti rispedirò a Orgrimmar a pezzi!', 'Ti rispedirò a Orgrimmar a pezzi!', 28153),
(156452, 'itIT', 'La pagherai per i tuoi crimini contro l\'Alleanza!', 'La pagherai per i tuoi crimini contro l\'Alleanza!', 28153),
(156451, 'itIT', 'Io servo Shadra, Signora delle Spie e dei Veleni. Chi servi tu?', 'Io servo Shadra, Signora delle Spie e dei Veleni. Chi servi tu?', 28153),
(156450, 'itIT', 'Muori, feccia dell\'Orda!', 'Muori, feccia dell\'Orda!', 28153),
(156449, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(156448, 'itIT', 'La Signora ha notato la presenza tua. Muoviti con cautela.', 'La Signora ha notato la presenza tua. Muoviti con cautela.', 28153),
(156447, 'itIT', 'Cammina con la Madre Terra, $n.', 'Cammina con la Madre Terra, $n.', 28153),
(156446, 'itIT', 'La nostra caccia in questa terra è appena iniziata.', '', 28153),
(156445, 'itIT', 'Rhan\'ka si sta ancora nascondendo nell\'oasi? Dovrei andare a fargli visita uno di questi giorni...', '', 28153),
(156444, 'itIT', 'Sapevo che saresti $gtornato:tornata;! Ho qui un bel carico fresco fresco, proprio per te.', '', 28153),
(156443, 'itIT', '[SCENE SHOWING GENERAL JAKRA\'ZET AND EMPEROR KORTHEK COLLUDING.]', '', 28153),
(156442, 'itIT', 'Le profondità... ti osservano...', 'Le profondità... ti osservano...', 28153),
(156441, 'itIT', 'Butterò la tua carcassa nell\'oceano!', 'Butterò la tua carcassa nell\'oceano!', 28153),
(156440, 'itIT', '', 'Sarei dovuta nascere Goblin, avrebbero apprezzato di più le mie capacità.', 28153),
(156439, 'itIT', 'Dovremmo fare un patto con i Marferreo. Sono ancora più stupidi degli altri.', '', 28153),
(156438, 'itIT', 'Fai ciò che devi mentre noi cerchiamo Zul. Ma stai all\'erta, presto avremo bisogno della tua ferocia.', '', 28153),
(156437, 'itIT', '', 'Cacceremo questi eretici fino ai confini di Azeroth. Raccoglierò il mio stormo e faremo piovere morte sulle teste di queste infami creature che hanno osato voltarci le spalle.\n\nPer ora, ci limiteremo a scrutare i cieli e profetizzare ciò che faranno Zul e i suoi traditori.', 28153),
(156436, 'itIT', 'Il colpo di grazia è stato tuo... chesta volta...', '', 28153),
(156435, 'itIT', '<Metti in coda il mio gruppo per una Scorreria sulle Isole PvP.>', '<Metti in coda il mio gruppo per una Scorreria sulle Isole PvP.>', 28153),
(156434, 'itIT', '<Mettiti in coda per una Scorreria sulle Isole PvP.>', '<Mettiti in coda per una Scorreria sulle Isole PvP.>', 28153),
(156433, 'itIT', 'Usa il Feticcio di Jin\'tiki per distruggere Zulajin!', 'Usa il Feticcio di Jin\'tiki per distruggere Zulajin!', 28153),
(156432, 'itIT', 'Spero solo di aver nascosto abbastanza bene la mia chiave, così che tu sia l\'unico a sapere come trovarla.', '', 28153),
(156431, 'itIT', 'Kaya, il tuo valore è fuori questione, ma non sei in condizioni di poter combattere. $n, accompagnerò io Kaya. Vediamoci alla torre quando $gsarai pronto:sarai pronta;.', '', 28153),
(156430, 'itIT', 'Grazie. Andrò a mettere al sicuro la torre. Ci servirà per chiamare il resto delle truppe.', 'Grazie. Andrò a mettere al sicuro la torre. Ci servirà per chiamare il resto delle truppe.', 28153),
(156429, 'itIT', '', 'Le mie sorelle... vi uccideranno...', 28153),
(156428, 'itIT', 'L\'Orda cadrà...', 'L\'Orda cadrà...', 28153),
(156427, 'itIT', 'Stai seguendo una pazza...', 'Stai seguendo una pazza...', 28153),
(156426, 'itIT', 'Mostri...', 'Mostri...', 28153),
(156425, 'itIT', 'Ti... ucciderò...', 'Ti... ucciderò...', 28153),
(156424, 'itIT', 'L\'Orda la pagherà...', 'L\'Orda la pagherà...', 28153),
(156423, 'itIT', 'Per Teldrassil...', 'Per Teldrassil...', 28153),
(156422, 'itIT', 'Sorelle... Ci ho provato...', 'Sorelle... Ci ho provato...', 28153),
(156421, 'itIT', '', 'La mia famiglia è morta a Teldrassil! Ti ucciderò!', 28153),
(156420, 'itIT', '', 'Ci vendicheremo per Teldrassil!', 28153),
(156419, 'itIT', 'Facciamo in modo che i Kul Tirani ci pensino due volte prima di scommettere contro l\'Orda.', '', 28153),
(156418, 'itIT', 'Per Teldrassil e l\'Alleanza!', 'Per Teldrassil e l\'Alleanza!', 28153),
(156417, 'itIT', 'Soffrite e morite, feccia dell\'Orda!', 'Soffrite e morite, feccia dell\'Orda!', 28153),
(156416, 'itIT', '', 'Assassini! Come osate mostrare il vostro volto?', 28153),
(156415, 'itIT', 'Andiamo accà!', '', 28153),
(156414, 'itIT', 'Ora penso io a camminare!', '', 28153),
(156413, 'itIT', 'Noi ora andiamo dove voglio!', '', 28153),
(156412, 'itIT', 'Io promosso a gambe!', '', 28153),
(156411, 'itIT', 'Io guido mo\'!', '', 28153),
(156410, 'itIT', 'Che il fuoco sacro ti purifichi!', '', 28153),
(156409, 'itIT', 'No... devo trovare... l\'anello...', '', 28153),
(156408, 'itIT', 'Mostri! Spedirò la vostra testa alla Capoguerra!', 'Mostri! Spedirò la vostra testa alla Capoguerra!', 28153),
(156407, 'itIT', 'La tua tesssta sarà un trofeo per la mia Regina!', '', 28153),
(156406, 'itIT', '', 'L\'Orda pagherà per ciò che ha fatto a Teldrassil!', 28153),
(156405, 'itIT', '', 'Ti mostrerò come bruciano i corpi!', 28153),
(156404, 'itIT', '', 'Pare che il nostro lavoro qui sia finito! In bocca al lupo là fuori, $p.', 28153),
(156403, 'itIT', 'I miei soldati saranno vendicati. Lo giuro.', 'I miei soldati saranno vendicati. Lo giuro.', 28153),
(156402, 'itIT', 'Sciocchi mortali. Non potete fermare il mio ritorno.', '', 28153),
(156401, 'itIT', '', 'Tu! Orda. Tengo bisogno delle abilità tue.', 28153),
(156400, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Una nuova |cFFFF0404|Hspell:263420|h[Matrice d\'Alimentazione]|h|r è disponibile.', '|TINTERFACE\\ICONS\\ABILITY_TITANKEEPER_CLEANSINGORB.BLP:20|t Una nuova |cFFFF0404|Hspell:263420|h[Matrice d\'Alimentazione]|h|r è disponibile.', 28153),
(156399, 'itIT', 'Quel Troll è più pazzo di uno sciame di ranishu.', '', 28153),
(156398, 'itIT', 'Rikati alza gli occhi al cielo.', '', 28153),
(156397, 'itIT', 'Va bene, amico. Sarà fatto! Grazie!', '', 28153),
(156396, 'itIT', 'Nun ci sta tempo da perdere in chiacchiere, Rikati! I Sabbiafurente sono scatenati! Nascondi il miele!', '', 28153),
(156395, 'itIT', 'L\'Anello delle Maree sarà nossstro! La Regina Azshara lo desidera!', 'L\'Anello delle Maree sarà nossstro! La Regina Azshara lo desidera!', 28153),
(156394, 'itIT', 'Non ci fermeremo fin quando l\'anello sarà nossstro!', 'Non ci fermeremo fin quando l\'anello sarà nossstro!', 28153),
(156393, 'itIT', 'Che stai dicendo? Contare? Io? No, io nun lo faccio, se tu che dovresti contare.\n\nFacciamo così, ripartiamo da zero.', '', 28153),
(156392, 'itIT', 'Dov\'è l\'Anello delle Maree? Non nascondercelo!', 'Dov\'è l\'Anello delle Maree? Non nascondercelo!', 28153),
(156391, 'itIT', 'L\'Anello delle Maree è andato perssso qui vicino. La Regina deve riaverlo!', 'L\'Anello delle Maree è andato perssso qui vicino. La Regina deve riaverlo!', 28153),
(156390, 'itIT', 'I Destatempesta continuano a crescere. Sei con noi?', 'I Destatempesta continuano a crescere. Sei con noi?', 28153),
(156389, 'itIT', 'Ho già raggiunto il milione di anime?', 'Ho già raggiunto il milione di anime?', 28153),
(156388, 'itIT', 'Nesssuno intralcerà la strada alla nossstra Regina!', 'Nesssuno intralcerà la strada alla nossstra Regina!', 28153),
(156387, 'itIT', 'L\'Anello delle Maree è nossstro di diritto!', 'L\'Anello delle Maree è nossstro di diritto!', 28153),
(156386, 'itIT', 'Possiamo ancora fermare Ser Sacraonda.', 'Possiamo ancora fermare Ser Sacraonda.', 28153),
(156385, 'itIT', 'L\'anello sarà nossstro!', 'L\'anello sarà nossstro!', 28153),
(156384, 'itIT', 'La Regina Azshara esige l\'Anello delle Maree!', 'La Regina Azshara esige l\'Anello delle Maree!', 28153),
(156383, 'itIT', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t Il Serpente Dorato assorbe dell\'Oro Animato, ottenendo |cFFFF0000|Hspell:265991|h[Lustro]|h|r!', '|TInterface\\ICONS\\INV_Misc_Gem_Pearl_04.blp:20|t Il Serpente Dorato assorbe dell\'Oro Animato, ottenendo |cFFFF0000|Hspell:265991|h[Lustro]|h|r!', 28153),
(156382, 'itIT', '', 'Oh oh! Non va bene! NON VA BENE!', 28153),
(156381, 'itIT', 'Usa una di quelle corde per raggiungere velocemente un mezzo da sbarco... a meno che tu non preferisca nuotare.', '', 28153),
(156380, 'itIT', 'Non laverò un solo altro paio di sudicie mutande di Umano!', '', 28153),
(156379, 'itIT', '', 'Sono zuppa fino alle calze! Grazie.', 28153),
(156378, 'itIT', '', 'Ne ho avuto abbastanza!', 28153),
(156377, 'itIT', 'Mi hai salvato da un terribile destino.', '', 28153),
(156375, 'itIT', 'Mentre ti davi all\'avventura, io ho studiato l\'arte della spada.', 'Mentre ti davi all\'avventura, io ho studiato l\'arte della spada.', 28153),
(156374, 'itIT', '<Il Maestro delle Spie Shaw annuisce.>', '', 28153),
(156373, 'itIT', 'Siamo arrivati, Maestro delle Spie.', '', 28153),
(156372, 'itIT', 'Lavorerò con il Maestro delle Spie Shaw. Non è la persona più affabile del mondo, ma sa fare il suo lavoro.', '', 28153),
(156371, 'itIT', 'Il Re ha invitato degli eroi davvero impressionanti per questa campagna.', '', 28153),
(156370, 'itIT', 'Alalesta, trovati qualcosa da mangiare.', '', 28153),
(156369, 'itIT', 'Vieni con me, $gragazzo:ragazza;!', '', 28153),
(156368, 'itIT', 'L\'ho preso nel ginocchio!', 'Oh... Chissà che male!', 28153),
(156367, 'itIT', 'Non gettiamo la spugna così facilmente.', 'Avrebbero dovuto scappare mentre ne avevano l\'opportunità.', 28153),
(156366, 'itIT', 'Un altro in meno!', 'Non sono così forti come pensavano!', 28153),
(156365, 'itIT', 'Saluti, Capitano Stone. Non vedevo l\'ora di incontrarti.', '', 28153),
(156364, 'itIT', 'Caricalo sul carro, allora. Ti stai rivelando più utile di quanto pensassi, Dama Voss.', '', 28153),
(156363, 'itIT', '', 'Abbastanza.', 28153),
(156362, 'itIT', 'Intatto?', '', 28153),
(156361, 'itIT', '', 'Proprio qui, Selvamorta. Ho recuperato il suo corpo.', 28153),
(156360, 'itIT', 'Ottimo lavoro, $p. Ora, dov\'è Lilian? ', '', 28153),
(156359, 'itIT', 'Devi sbrigarti... Stanno attaccando Rezan!', '', 28153),
(156358, 'itIT', 'Loro... mi hanno costretto a raccontare come i Drakkari ci sono riusciti.', '', 28153),
(156357, 'itIT', 'Eccellente. Taelia ti aggiornerà sulla situazione.', '', 28153),
(156356, 'itIT', '', 'Signore! Il rapporto sulla situazione è pronto!', 28153),
(156355, 'itIT', '', 'Hai ridotto la loro armata in briciole! Ben fatto.', 28153),
(156354, 'itIT', '', 'Le streghe stanno iniziando a ricostituire le loro forze. Prendi il controllo di un Demolitore e distruggi la loro armata!', 28153),
(156353, 'itIT', '', 'Dobbiamo mostrare ai Kul Tirani cosa significa mettersi contro l\'Orda.', 28153),
(156352, 'itIT', 'Ricorda: Portoponte è un insediamento grande e ben protetto. Cerca di stare ai bordi della città... per il momento.', '', 28153),
(156351, 'itIT', 'Abbiamo fatto la nostra parte, $p. Sono orgoglioso di ciò che abbiamo ottenuto, ma ora è il momento che io vada in cerca della mia gente per assicurarmi che stia bene.\n\nNon ho dubbi che ci rivedremo. Sono felice di poterti chiamare $gamico:amica;.', '', 28153),
(156350, 'itIT', 'I Senzafede trattano le loro bestie in modo crudele. Non sarà difficile aizzarli contro i loro padroni.', '', 28153),
(156349, 'itIT', 'Nun posso accettare tutto chesto. Sono stato nominato dal Profeta Zul in persona!', '', 28153),
(156348, 'itIT', '', 'Quella sì che è stata una battaglia degna di una leggenda!\n\nÈ stato un onore combattere al fianco tuo e di Vorrik. Spero capiti di nuovo in futuro.\n\nDopotutto, ci saranno sempre altri Senzafede da uccidere.', 28153),
(156347, 'itIT', 'Poniamo fine a tutto questo insieme.', '', 28153),
(156346, 'itIT', '', 'Insegniamo a questi Sethrak una lezione.', 28153),
(156345, 'itIT', '', 'Questi rifornimenti ci aiuteranno a continuare lo scontro con la congrega. Grazie.', 28153),
(156344, 'itIT', 'Seguimi, la fortezza non è lontana da qui.', '', 28153),
(156343, 'itIT', 'Bene. Allora saranno il nostro primo bersaglio.', '', 28153),
(156342, 'itIT', '', 'La città che abbiamo appena superato, Portoponte, sembra essere la minaccia più grande della zona.', 28153),
(156341, 'itIT', 'Rexxar! <Tossisce> Molti resistono. Ma... non gli rimane molto tempo.', 'Rexxar! <Tossisce> Molti resistono. Ma... non gli rimane molto tempo.', 28153),
(156340, 'itIT', 'Quella bestia non si ciberà di altri soldati dell\'Orda. Una gran bella uccisione.', '', 28153),
(156339, 'itIT', '', 'Siamo a corto di argento, un elemento cruciale nella nostra battaglia contro le streghe. Avventurati nelle miniere e recupera tutto quello che riesci a trovare.', 28153),
(156338, 'itIT', 'Rakjan sembra disposto ad aiutarci ed è facile capire il perché.\n\nI Senzafede sono stati crudeli con lui e la sua stirpe. Guarda le cicatrici sul suo corpo e i vuoti trespoli sul suo monte.\n\nSi merita vendetta proprio come tutti noi. Ce la guadagneremo insieme.', '', 28153),
(156337, 'itIT', 'Sì, Samuel. Resisti.', '', 28153),
(156336, 'itIT', 'Ho freddo. Queste voci si fermeranno mai?', '', 28153),
(156335, 'itIT', '$n, gira la pozione o si brucerà.', '', 28153),
(156334, 'itIT', 'Un gran bel lavoro. Ora assicuriamoci che questa festa sia anche l\'ultima del concilio.', '', 28153),
(156333, 'itIT', 'Ah, ottimo lavoro, riccumpà. Ora siamo pronti a rovinare la festa del concilio.', '', 28153),
(156332, 'itIT', 'Non agitarti. Queste erbe leniranno il dolore. Puoi dirci qualcosa della situazione nella fortezza? Ci sono altri sopravvissuti?', '', 28153),
(156331, 'itIT', '|TInterface\\ICONS\\ABILITY_DEATHKNIGHT_SOULREAPER:20|t I danni inflitti dal Goliath Vincolato aumentano con ogni accumulo di |cFFFF0404|Hspell:260512|h[Mietitura delle Anime]|h|r!', '', 28153),
(156330, 'itIT', 'Guarda! Questo respira ancora!', '', 28153),
(156329, 'itIT', 'Molti guerrieri coraggiosi sono caduti in battaglia. Il tuo arrivo è stato provvidenziale.', '', 28153),
(156328, 'itIT', 'Mentre stavamo cercando di salvare gli equipaggi, i Kul Tirani hanno attaccato. Le nostre truppe erano troppo sparpagliate per riuscire a difendere entrambe le posizioni, quindi abbiamo dovuto ritirarci sulla riva.', '', 28153),
(156327, 'itIT', 'L\'attacco è avvenuto stamattina presto. I Maghi di Kul Tiras hanno usato uno strano oggetto per evocare quegli orrori che hai visto attorcigliati sulle nostre navi.', '', 28153),
(156326, 'itIT', 'Ah! Confermato! Missione compiuta. Avete agito alla perfezione! Adoro i piani ben riusciti! Ahahah! Passo e chiudo.', '', 28153),
(156325, 'itIT', 'Eseguite le seguenti istruzioni. Vedete quel grosso bottone rosso? State lontani dall\'area e premetelo. Eseguire non appena pronti. Passo.', '', 28153),
(156324, 'itIT', 'Il codice d\'autenticazione è uno, nove, nove. Allineamento degli strumenti fuori dai parametri accettabili... Contrordine... Posso farlo funzionare. Rimanete in attesa. Passo.', '', 28153),
(156323, 'itIT', 'Sì! Ricevuto! Calibrazione completata. Dovrete orientare gli strumenti verso posizioni ben specifiche. Contattatemi quando saranno pronte. Passo.', '', 28153),
(156322, 'itIT', 'Prova. Qui Alfa 1. Squadrone alfa, mi ricevete? Passo.', '', 28153),
(156321, 'itIT', 'Una battaglia gloriosa! E siamo sopravvissuti!', '', 28153),
(156320, 'itIT', '', 'La fiamma non si spegne mai...', 28153),
(156319, 'itIT', '', 'Cenere alla cenere...', 28153),
(156318, 'itIT', 'Ci sentiamo onorati di averti al nostro fianco. Grazie infinite, $p.', '', 28153),
(156317, 'itIT', '', 'Le tue ossa saranno ottime da ardere.', 28153),
(156316, 'itIT', '', 'Non lascerò che nessuno rimanga indietro a piangere sulle tue ceneri.', 28153),
(156315, 'itIT', 'La nostra lunga storia ha visto ben pochi giorni grandiosi come questo!', '', 28153),
(156314, 'itIT', 'Creerò una nuova zuppa in tuo onore!', '', 28153),
(156313, 'itIT', 'La Zuppa di Tartaruga non è neanche lontanamente comparabile alla zuppa di $R.\n\nTrovami la Carne di Verme del Fango e lascia stare le tartarughe.\n\nVieni a trovarmi un giorno, così esploreremo nuove zuppe insieme!', '', 28153),
(156312, 'itIT', '|TInterface\\Icons\\SPELL_PRIEST_SHADOWORBS.BLP:20|t %s inizia a lanciare |cFFFF0000|Hspell:267334|h[Globo della Corruzione]|h|r!', 'Una proiezione appare in lontananza...', 28153),
(156311, 'itIT', '', 'È facile perdere la via.', 28153),
(156310, 'itIT', 'Fammi sapere se tieni bisogno dell\'aiuto mio!', '', 28153),
(156309, 'itIT', 'Mo\' che accà è tutto a posto, devo tornare indietro.', '', 28153),
(156308, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso la Baia di Tiragarde.', '|cFF0000FF(Missione)|r Fai rotta verso la Baia di Tiragarde.', 28153),
(156307, 'itIT', '|TInterface\\Icons\\ABILITY_DEATHKNIGHT_DEATHSIPHON2.BLP:20|t %s inizia a lanciare |cFFFF0000|Hspell:265360|h[Inganno Torbido]|h|r!', 'Una proiezione appare in lontananza...', 28153),
(156306, 'itIT', '', 'Ti sono grata per il tuo aiuto.', 28153),
(156305, 'itIT', '', 'Le ombre del passato ci circondano.', 28153),
(156304, 'itIT', 'Sai che mi piace fare nel tempo libero? Giocare al lancio dello gnomo! Ahahah!', '', 28153),
(156303, 'itIT', 'Stai cercando di tagliare i ponti?', '', 28153),
(156302, 'itIT', 'Non costringermi usare il martello!', '', 28153),
(156301, 'itIT', 'Che il tuo fuoco arda vigoroso.', '', 28153),
(156300, 'itIT', 'Batti il ferro finché è caldo.', '', 28153),
(156299, 'itIT', 'Divertiti!', '', 28153),
(156298, 'itIT', 'Hai visto la mia chiave da qualche parte?', '', 28153),
(156297, 'itIT', 'Come posso aiutarti?', '', 28153),
(156296, 'itIT', 'Spara!', '', 28153),
(156286, 'itIT', '', 'Quanto dolore. Quante perdite.', 28153),
(156285, 'itIT', '', 'Qual è il sentiero da seguire?', 28153),
(156284, 'itIT', '', 'Devo trovare un modo per superare tutto questo.', 28153),
(156283, 'itIT', 'La sabbia è rossa.', 'La sabbia è rossa.', 28153),
(156282, 'itIT', 'Come sono finito qui?', 'Come sono finita qui?', 28153),
(156281, 'itIT', 'I miei amici mi vendicheranno.', 'I miei amici mi vendicheranno.', 28153),
(156280, 'itIT', 'Quindi, Turalyon si fa tutto luminoso e Alleria si fa tutta ombrosa... Mmm... Ora che sono tornato in azione, conviene che trovi anch\'io qualche bel trucchetto!', '', 28153),
(156279, 'itIT', 'Sono stato bravo?', 'Sono stata brava?', 28153),
(156278, 'itIT', 'Ti distruggerò!', 'Ti distruggerò!', 28153),
(156277, 'itIT', 'Questa è la tua fine!', 'Questa è la tua fine!', 28153),
(156276, 'itIT', 'Non puoi fermarci!', 'Non puoi fermarci!', 28153),
(156275, 'itIT', 'Per fortuna me ne sono andato dalla Rocca dell\'Onore. Il caldo stava iniziando a seccarmi la pelle.', '', 28153),
(156274, 'itIT', 'Non oggi, demone!', 'Non oggi, demone!', 28153),
(156273, 'itIT', 'Khadgar e io ci vediamo una volta alla settimana per giocare a scacchi. Bara ogni volta...', '', 28153),
(156272, 'itIT', 'Ognuno di noi deve fare la sua parte.', '', 28153),
(156271, 'itIT', 'Per Stromgarde!', '', 28153),
(156270, 'itIT', 'Nun ti voglio mentire, cumpà.\n\nHo sempre sognato di partecipare a n\'ammutinamento.', '', 28153),
(156269, 'itIT', 'Per l\'Alleanza!', '', 28153),
(156268, 'itIT', 'L\'Alleanza prevarrà.', '', 28153),
(156267, 'itIT', 'Combatti bene.', '', 28153),
(156266, 'itIT', 'Azeroth ci chiama e noi dobbiamo rispondere.', '', 28153),
(156265, 'itIT', 'Combatteremo per ciò che è nostro.', '', 28153),
(156264, 'itIT', 'Qualsiasi cosa arrivi, la affronteremo insieme.', '', 28153),
(156263, 'itIT', 'La mia vita per l\'Alleanza.', '', 28153),
(156262, 'itIT', 'Stromgarde combatterà con orgoglio ancora una volta.', '', 28153),
(156261, 'itIT', 'Fa\' quello che vuoi, ma lo dirò lo stesso... È ORA DI IMPUGNARE IL MARTELLO!', '', 28153),
(156260, 'itIT', 'Si potrebbe dire che soffro della sindrome del figlio di mezzo, ma quando un fratello è fatto di diamanti e l\'altro è un famoso esploratore, è difficile trovare la propria nicchia!', '', 28153),
(156259, 'itIT', 'Ma che...?!? Qualcuno mi ha appena chiamato \"Re dei Bon Bon\" e mi ha chiesto un leccalecca!', '', 28153),
(156258, 'itIT', 'Noi non ci arrendiamo mai!', '', 28153),
(156257, 'itIT', 'Il Clan Barbabronzea ti ringrazia.', '', 28153),
(156256, 'itIT', 'Forgiardente vincerà.', '', 28153),
(156255, 'itIT', 'Che il tuo cammino ti porti gloria.', '', 28153),
(156254, 'itIT', 'Possa il tuo martello colpire duramente.', '', 28153),
(156253, 'itIT', 'Che la forgia sia con te.', '', 28153),
(156252, 'itIT', 'Ho il mio martello e ho la mia ascia. Mettiamoci al lavoro!', '', 28153),
(156251, 'itIT', 'Sei qui per aiutare l\'Alleanza?', '', 28153),
(156250, 'itIT', 'I Tre Martelli sono uniti.', '', 28153),
(156249, 'itIT', 'Forgiardente è qui per fare la sua parte.', '', 28153),
(156248, 'itIT', 'Sai cos\'è successo alle prime sei legioni? Ti va di scoprirlo?', '', 28153),
(156247, 'itIT', 'Vuoi fare una visitina in cella, soldato?', '', 28153),
(156246, 'itIT', 'Stai mettendo alla prova la mia pazienza.', '', 28153),
(156245, 'itIT', 'Il nostro lavoro è appena cominciato.', '', 28153),
(156244, 'itIT', 'Al prossimo incontro.', '', 28153),
(156243, 'itIT', 'Che la Luce sia con te.', '', 28153),
(156242, 'itIT', 'Grazie alla forza dell\'Alleanza, i nostri nemici conosceranno solo la sconfitta.', '', 28153),
(156241, 'itIT', 'Per la Luce, il primo colpo spetta a noi.', '', 28153),
(156240, 'itIT', 'La tua leggenda non fa che crescere.', '', 28153),
(156239, 'itIT', 'Il destino ci sorride quest\'oggi.', '', 28153),
(156238, 'itIT', 'L\'Orda cadrà.', '', 28153),
(156237, 'itIT', 'Di\' pure.', '', 28153),
(156236, 'itIT', 'Siamo i figli e le figlie dell\'Alleanza.', '', 28153),
(156235, 'itIT', '', 'Questo mondo deve essere difeso. Avanti, Ferroscuro! Marciamo verso la battaglia!', 28153),
(156234, 'itIT', '', 'Lo stesso sangue che scorre nelle nostre vene... scorre anche attraverso Azeroth.', 28153),
(156233, 'itIT', '', 'Il nostro regno fu forgiato con l\'incudine e il martello. Con cuori di fuoco... e volontà di ferro.', 28153),
(156232, 'itIT', '', 'La montagna ci dona la vita e grande forza.', 28153),
(156231, 'itIT', '', 'Thurgaden e Thaelin hanno creato un\'armatura come riconoscimento per le tue imprese. Indossala con orgoglio.', 28153),
(156230, 'itIT', '', 'Ora l\'Alleanza sa che noi Ferroscuro facciamo parte dei giochi. Non avrei potuto chiedere un campione migliore.', 28153),
(156229, 'itIT', '', 'Torna alla montagna. Abbiamo preparato qualcosa di speciale per te.', 28153),
(156228, 'itIT', '', 'Ci hai reso orgogliosi. Ho sentito storie sul coraggio che hai dimostrato nei tuoi viaggi su Azeroth.', 28153),
(156227, 'itIT', '', 'Siamo stati forgiati nelle fiamme della montagna. Mostra a tutti il fuoco che arde in te.', 28153),
(156226, 'itIT', '', 'Azeroth ti attende e Roccavento sarà la tua prima destinazione.', 28153),
(156225, 'itIT', '', 'Ora è il momento per i Ferroscuro di emergere dalle ombre.', 28153),
(156224, 'itIT', '', 'Molti ci avevano consigliato di non avventurarci in superficie, ma a noi il coraggio non manca.', 28153),
(156223, 'itIT', 'Per l\'Alleanza!', '', 28153),
(156222, 'itIT', '', 'I Ferroscuro accettano il tuo invito. Per l\'Alleanza!', 28153),
(156221, 'itIT', '', 'È solo una formalità, maestà! Nessun problema.', 28153),
(156220, 'itIT', 'Eppure non abbiamo mai chiesto ufficialmente al tuo clan di unirsi all\'Alleanza, un errore che spero mi permetterai di correggere al più presto.', '', 28153),
(156219, 'itIT', '', 'Sì.', 28153),
(156218, 'itIT', 'E anche se il clan Ferroscuro è conosciuto per il suo... spirito d\'indipendenza, nessuno può mettere in dubbio la determinazione e la lealtà della tua gente.', '', 28153),
(156217, 'itIT', 'La tua posizione nel Concilio dei Tre Martelli ha garantito ordine e stabilità a Forgiardente.', '', 28153),
(156216, 'itIT', '', 'Lo stesso vale per me, Re Wrynn.', 28153),
(156215, 'itIT', 'Regina Reggente Thaurissan, sono lieto di rivederti.', '', 28153),
(156214, 'itIT', 'Ehi! Sto lavorando!', '', 28153),
(156213, 'itIT', '', 'Grazie. Dobbiamo preservare ciò che rimane delle fattorie di Drustvar.', 28153),
(156212, 'itIT', '', 'I maiali di un allevatore locale sono spariti nel cuore della foresta. Salvali prima che le spore li infettino!', 28153),
(156211, 'itIT', '', 'Le streghe sono state smascherate e la mia gente è di nuovo al sicuro. Grazie.', 28153),
(156210, 'itIT', '', 'La congrega sta cercando di infiltrarsi nel Presidio di Arom. Scopri i loro piani e brucia la corruzione prima che faccia del male a qualcuno.', 28153),
(156209, 'itIT', '<Offri la Polvere Coagulante: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', '<Offri la Polvere Coagulante: |TInterface\\ICONS\\INV_MISC_POWDER_COPPER.BLP:20|t>', 28153),
(156208, 'itIT', '<Offri l\'Antica Pergamena dei Tortolliani: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', '<Offri l\'Antica Pergamena dei Tortolliani: |TInterface\\ICONS\\TRADE_ARCHAEOLOGY_SILVERSCROLLCASE.BLP:20|t>', 28153),
(156207, 'itIT', '<Offri l\'Acqua di Riccio di Mare: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', '<Offri l\'Acqua di Riccio di Mare: |TInterface\\ICONS\\INV_Misc_Food_Legion_gooOil_multi.BLP:20|t>', 28153),
(156206, 'itIT', '<Offri le Spezie Astringenti: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', '<Offri le Spezie Astringenti: |TInterface\\ICONS\\INV_Misc_Dust_01.blp:20|t>', 28153),
(156205, 'itIT', 'Stai all\'erta, $n. Ti guiderò non appena sarò pronto per altri ingredienti.', '', 28153),
(156204, 'itIT', 'Chesto va oltre tutti noi, cumpà. Il Loa della Morte se l\'è pigliato!', '', 28153),
(156203, 'itIT', 'Be\'... questo va un po\' oltre le mie competenze, mi spiace.', '', 28153),
(156202, 'itIT', '<Jamil Abul\'housin trema per il terrore!>', '', 28153),
(156201, 'itIT', 'Jamil?', '', 28153),
(156200, 'itIT', 'A momenti.', '', 28153),
(156199, 'itIT', 'Ecco... il Re dovrebbe risvegliarsi, ora', '', 28153),
(156198, 'itIT', 'Il sanguinamento non si ferma... Presto, $n, portami subito la Polvere Coagulante!', '', 28153),
(156196, 'itIT', '<Il canto di Jamil Abul\'housin si fa più forte e disperato.>', '', 28153),
(156195, 'itIT', 'Fatto! Ora gliela somministrerò.', '', 28153),
(156194, 'itIT', '<Jamil Abul\'housin inizia a recitare una preghiera sottovoce.>', '', 28153),
(156193, 'itIT', 'Giusto, TRE manciate.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(156192, 'itIT', 'L\'ho scritta sette secoli fa. Vorrei vedere te ricordare qualcosa che è più vecchio del nonno di tuo nonno.', '', 28153),
(156191, 'itIT', 'Ti sei scordato la ricetta?!?', '', 28153),
(156190, 'itIT', 'Erano una o due manciate? $n, portami la pergamena.', '', 28153),
(156188, 'itIT', 'Grazie. Sto mescolando il più velocemente possibile. Abbi pazienza.', '', 28153),
(156187, 'itIT', 'Niente? Jol, farai meglio a sbrigarti con chei medicamenti...', '', 28153),
(156186, 'itIT', 'Ora del sale. Controlla la dispensa.', '', 28153),
(156185, 'itIT', 'Non far scappare i crog!', 'Non far scappare i crog!', 28153),
(156184, 'itIT', 'Sono pronto, Jol.', 'Sono pronta, Jol.', 28153),
(156183, 'itIT', 'Questi ingredienti sono complessi da usare. Richiederanno la mia più completa attenzione. Sarai tu ad aiutarmi a produrre questo intruglio. Ricorda, la vita del Re dipende da noi.\n\nSei $gpronto:pronta; a iniziare?', '', 28153),
(156182, 'itIT', '', 'Se ciò che dice chesto esiliato è vero, devi andare a investigare. Fai attenzione, però. Jakra\'zet potrebbe stare nei paraggi.', 28153),
(156181, 'itIT', 'Be\', non pensavo ti importasse! Da dove posso iniziare?\n\nFacciamo questo pellegrinaggio a Nazmir una volta ogni manciata d\'anni. A volte sono cinque, altre volte venti. Dipende da quando Torga ha una storia da raccontare.\n\nQuando iniziamo a sentire voci sulla possibilità che Torga abbia una nuova storia da raccontare, diamo inizio al pellegrinaggio. Veniamo qui, ci sediamo e ascoltiamo tutte le storie di Torga, che poi tramandiamo a chiunque incontriamo.\n\nDovresti considerarti $gfortunato:fortunata;, è raro vedere così tanti di noi radunati nello stesso luogo. Anche questo varrebbe la pena raccontare ai tuoi amici, se gli interessa.', '', 28153),
(156180, 'itIT', 'Dovrai passare... sul mio cadavere...', 'Dovrai passare... sul mio cadavere...', 28153),
(156179, 'itIT', 'Parlami di questo pellegrinaggio.', 'Parlami di questo pellegrinaggio.', 28153),
(156178, 'itIT', 'Nessuno sfuggirà al mio controllo!', 'Nessuno sfuggirà al mio controllo!', 28153),
(156177, 'itIT', 'Diciamo che è un pareggio.', '', 28153),
(156176, 'itIT', 'Una nuova polvere da sparo, di un tipo mai visto prima.', '', 28153),
(156175, 'itIT', 'Boralus appartiene a me.', '', 28153),
(156174, 'itIT', 'Che succede?', 'Che succede?', 28153),
(156173, 'itIT', '', 'Per l\'Orda!', 28153),
(156172, 'itIT', '', 'Benissimo! Ora portaci oltre gli esplosivi, dall\'altra parte del ponte.', 28153),
(156171, 'itIT', '', 'Continua a muoverti! Raduna tutte le guardie della città... e il loro capo!', 28153),
(156170, 'itIT', '', 'Venite a prenderci, codardi!', 28153),
(156169, 'itIT', '', 'L\'Orda vi farà a pezzi!', 28153),
(156168, 'itIT', '', 'Kul Tirani! Il vostro patto con l\'Alleanza sarà la vostra sentenza di morte!', 28153),
(156167, 'itIT', '', 'Vai in città e raduna più guardie che puoi!', 28153),
(156166, 'itIT', '', 'Flynn! Qui!', 28153),
(156165, 'itIT', 'Come ho potuto fallire?', 'Come ho potuto fallire?', 28153),
(156164, 'itIT', '', 'Le cose stanno così. Uccidi il Capitano, così che i Solcanebbia restino uomini e donne liberi!', 28153),
(156163, 'itIT', '', 'Credi davvero di sapere cosa si prova a frequentare un ragazzaccio? Non ne hai la minima idea...', 28153),
(156162, 'itIT', '', 'Strano... non mi ero mai accorta di aver perso il mio accento di Kul Tiras.', 28153),
(156161, 'itIT', '', 'Naturalmente ho anch\'io il bastone pecora. Chi pensi che abbia coniato il termine \"Tosapecore\"?', 28153),
(156160, 'itIT', 'Rubiamo qualche arma prima di andare.', 'Rubiamo qualche arma prima di andare.', 28153),
(156159, 'itIT', 'Comprare e vendere gente... non è giusto.', 'Comprare e vendere gente... non è giusto.', 28153),
(156158, 'itIT', 'Mescolatura', 'Mescolatura', 28153),
(156157, 'itIT', 'Noi Vulpera non subiremo più tutto questo!', 'Noi Vulpera non subiremo più tutto questo!', 28153),
(156156, 'itIT', 'Non hanno ancora visto niente!', '', 28153),
(156155, 'itIT', 'Non voglio mai più vedere un Sethrak in vita mia.', 'Non voglio mai più vedere un Sethrak in vita mia.', 28153),
(156154, 'itIT', 'Per questo non si punzecchia mai una tartaruga!', '', 28153),
(156153, 'itIT', 'Pensavo che mi avrebbero mangiato!', 'Pensavo che mi avrebbero mangiata!', 28153),
(156152, 'itIT', 'Per le sabbie ardenti, come sono felice di vederti!', 'Per le sabbie ardenti, come sono felice di vederti!', 28153),
(156151, 'itIT', '', 'Dopo tutti questi anni, cerchi ANCORA di infastidirmi? Certe cose non cambiano mai...', 28153),
(156150, 'itIT', '', 'La vera battaglia si trova davanti a noi.', 28153),
(156149, 'itIT', '', 'Farò ciò che posso.', 28153),
(156148, 'itIT', '', 'Il sentiero davanti a noi non sarà facile.', 28153),
(156147, 'itIT', 'Fa più male di quanto mi aspettassi.', 'Fa più male di quanto mi aspettassi.', 28153),
(156146, 'itIT', 'Ho preso un po\' dei loro cristalli... Chi è che ride ultimo, ora? Ahah!', '', 28153),
(156145, 'itIT', 'Questo guscio non è in vendita!', '', 28153),
(156144, 'itIT', 'Nessuno di questi Sethrak potrebbe permettersi il mio aiuto, comunque.', '', 28153),
(156143, 'itIT', 'I Senzafede non hanno rispetto per l\'età o la saggezza.', '', 28153),
(156142, 'itIT', 'Racconterò a tutta la gente di Zuldazar questa storia!', '', 28153),
(156141, 'itIT', '', 'Non possiamo lasciare che il mondo cada nell\'oscurità.', 28153),
(156140, 'itIT', 'Alla fine la fortuna mi ha sorriso!', '', 28153),
(156139, 'itIT', 'La Capoguerra esige l\'annientamento della presenza dell\'Alleanza in questa regione. Sbarazzati di loro!', '', 28153),
(156138, 'itIT', '', 'Il tempo dei sogni è finito.', 28153),
(156137, 'itIT', 'Quegli stolti dell\'Alleanza si sono accampati qui vicino. Fagli visita e dimostragli la futilità delle loro ambizioni.', '', 28153),
(156136, 'itIT', 'Le forze dell\'Alleanza si trovano vicino alla tua posizione. Assicurati che questo sia il loro ultimo giorno.', '', 28153),
(156135, 'itIT', '', 'Cosa vuoi chiedere alla figlia del mare?', 28153),
(156134, 'itIT', 'L\'Alleanza trema dinanzi a noi! La Dama Oscura sarà compiaciuta.', '', 28153),
(156133, 'itIT', 'Una brutalità senza pari! L\'Alleanza ha provato sulla sua pelle la nostra ira.', '', 28153),
(156132, 'itIT', 'Aprire il fuoco!', '', 28153),
(156131, 'itIT', 'Alleanza... patetici! Ci penseranno due volte prima di interferire di nuovo con i nostri piani.', '', 28153),
(156130, 'itIT', '', 'Abbiamo una lunga strada davanti a noi.', 28153),
(156129, 'itIT', 'Trattieni il respiro!', '', 28153),
(156128, 'itIT', '', 'L\'Alleanza prevarrà.', 28153),
(156127, 'itIT', '', 'So cosa dobbiamo fare.', 28153),
(156126, 'itIT', '', 'Una sola scintilla può incendiare il mondo.', 28153),
(156125, 'itIT', '', 'Controlla il tuo potere... o esso controllerà te.', 28153),
(156124, 'itIT', 'Per Lordaeron.', 'Per Lordaeron.', 28153),
(156123, 'itIT', '', 'Non dimenticherò mai.', 28153),
(156122, 'itIT', '', 'Abbiamo tutti i nostri spettri.', 28153),
(156121, 'itIT', 'Finalmente un po\' di divertimento!', 'Finalmente un po\' di divertimento!', 28153),
(156120, 'itIT', '', 'Non fidarti di nessuno.', 28153),
(156119, 'itIT', 'La mia anima ha sete.', 'La mia anima ha sete.', 28153),
(156118, 'itIT', 'È tempo di sanguinare!', 'È tempo di sanguinare!', 28153),
(156117, 'itIT', 'Apprezzo sempre un\'uccisione efficiente, ci permette di mantenere la tabella di marcia.', '', 28153),
(156116, 'itIT', 'Tipico... un altro nemico che ha affrontato la forza dell\'Orda, solo per perdere.', '', 28153),
(156115, 'itIT', 'La Dama Oscura sceglie bene i suoi campioni.', '', 28153),
(156114, 'itIT', 'Un lavoro ben fatto... anche se non con la dovuta finezza. Puoi tornare ai tuoi compiti.', '', 28153),
(156113, 'itIT', 'Ah... i piaceri del fare a pezzi l\'avversario. Il dovere non può impedire a nessuno di assaporare una vittoria!', '', 28153),
(156112, 'itIT', 'Ottimo lavoro. Le nostre operazioni possono procedere come previsto.', '', 28153),
(156111, 'itIT', 'L\'Orda presto reclamerà quest\'area, ma un potente nemico si trova sul nostro cammino. Apri la strada alle nostre forze.', '', 28153),
(156110, 'itIT', 'I piani della Capoguerra per questa zona non includono... quel mostro. Eliminalo!', '', 28153),
(156109, 'itIT', '', 'Ascolta, non hai mai pensato che la TUA linea temporale sia quella \"alternativa\" e la MIA quella reale? Eheheh... scommetto che non te l\'aspettavi...', 28153),
(156108, 'itIT', 'Un grande avversario è vicino alla tua posizione. Ti va di portare ai nostri ricercatori un nuovo cadavere da studiare?', '', 28153),
(156107, 'itIT', 'Un nemico nelle vicinanze si sta sbarazzando delle nostre reclute. Vista la tua fama, confido che saprai fare di meglio.', '', 28153),
(156106, 'itIT', '', 'Avete combattuto una guerra contro la Legione... ma non avete pensato di chiamarci? Seriamente? Il destino dell\'intero universo era in bilico e non avete avuto la decenza di... bah, fa niente.', 28153),
(156105, 'itIT', 'I rapporti indicano che un potente nemico si trova vicino alla tua posizione. Colpiscilo e goditi la sua morte!', '', 28153),
(156104, 'itIT', 'La Capoguerra ti ha chiesto di eliminare un bersaglio nell\'area. Non deluderla.', '', 28153),
(156103, 'itIT', '', 'Da quando sono venuta in città, questi Orchi di Orgrimmar sembrano camminare più dritti.', 28153),
(156102, 'itIT', '', 'Continua a darmi fastidio e ti faccio vedere gli Orchi verdi.', 28153),
(156101, 'itIT', 'Iniziavo ad avere fame...', 'Iniziavo ad avere fame...', 28153),
(156100, 'itIT', '', 'Parla in fretta. Ci sono battaglie da vincere!', 28153),
(156099, 'itIT', '', 'Il cuore dei Mag\'har è forte e puro.', 28153),
(156098, 'itIT', '', 'Siamo qui per vincere questa guerra.', 28153),
(156097, 'itIT', '', 'Ascolterò le tue parole... ma ti giudicherò dalle azioni.', 28153),
(156096, 'itIT', '', 'Non riesco a immaginare cosa sarebbe successo se gli avessimo permesso di continuare quei rituali. Grazie per l\'aiuto.', 28153),
(156095, 'itIT', '', 'Parla.', 28153),
(156094, 'itIT', '', 'Ammirerò i cieli di Draenor ancora una volta.', 28153),
(156093, 'itIT', '', 'Non conosciamo altro che la guerra.', 28153),
(156092, 'itIT', '', 'Che i nemici striscino ai tuoi piedi.', 28153),
(156091, 'itIT', '', 'Sembra che le streghe di Corlain stiano provando un nuovo tipo di rituale. Fermale prima che sia troppo tardi!', 28153),
(156090, 'itIT', '', 'Vivi con onore! Muori con gloria!', 28153),
(156089, 'itIT', '', 'I Mag\'har otterranno la vittoria.', 28153),
(156088, 'itIT', '', 'Muori bene.', 28153),
(156087, 'itIT', '', 'Vai con onore.', 28153),
(156086, 'itIT', '', 'Throm\'ka!', 28153),
(156085, 'itIT', '', 'Lok\'tar!', 28153),
(156084, 'itIT', 'Poveri uccelli... possano i vostri spiriti volare liberi per sempre.', '', 28153),
(156083, 'itIT', 'I falchi di questa zona sono sotto l\'influenza delle streghe. Vorrei ci fosse un modo per salvarli, ma è troppo tardi ormai. Queste cipolle dovrebbero aiutarti a occuparti di loro!', '', 28153),
(156082, 'itIT', '', 'Gran bel lavoro. L\'Alleanza capirà mai che li Zandalari nun possono essere fermati?', 28153),
(156081, 'itIT', '', 'Hai agito bene. L\'Alleanza imparerà a temere la forza delli Zandalari.', 28153),
(156080, 'itIT', '', 'L\'Alleanza presto scoprirà che nun si possono conquistare li Zandalari.', 28153),
(156079, 'itIT', '', 'Ho saputo che l\'Alleanza sta radunando le forze sue vicino accà. Ferma qualsiasi cosa stiano pianificando.', 28153),
(156078, 'itIT', '', 'L\'Alleanza crede di poter sfidare l\'Impero delli Zandalari. Mostra loro quanto si sbagliano.', 28153),
(156077, 'itIT', '', 'Bene ragazzi, è ora di ammutinarsi! Come Solcanebbia ci rifiutiamo di rinunciare alla nostra libertà!', 28153),
(156076, 'itIT', '', 'Prima tutta quest\'accondiscendenza verso di me non faceva che irritarmi, ma per te farò un\'eccezione!', 28153),
(156075, 'itIT', '', 'L\'Alleanza sta complottando qualcosa nelle vicinanze. Distruggili. Fai in modo che temano l\'Impero delli Zandalari.', 28153),
(156074, 'itIT', 'Ah... Possiamo riposare più serenamente ora che il problema è stato risolto.', '', 28153),
(156073, 'itIT', 'I soldati che combattono per l\'Alleanza non dimenticheranno ciò che hai fatto oggi.', '', 28153),
(156072, 'itIT', 'Ottimo. Un giorno dovrò raccontarti delle storie della Terza Guerra, tutto questo mi ricorda molto quei giorni.', '', 28153),
(156071, 'itIT', 'Ottimo, queste risorse ci aiuteranno a resistere.', '', 28153),
(156070, 'itIT', 'Questa zona si sta rivelando pericolosa per le nostre forze. Mi ricorda i tempi della Seconda Guerra. Puoi darci una mano?', '', 28153),
(156069, 'itIT', 'Dobbiamo occuparci immediatamente dei problemi che affliggono la zona limitrofa. Pensi di riuscirci?', '', 28153),
(156068, 'itIT', '', 'Ma certo che ho una relazione complicata con mio padre. È già difficile aver a fare con i genitori in generale, figurarsi uno fatto di diamante!', 28153),
(156067, 'itIT', 'La zona qui vicino ci sarebbe assai utile. Va ripulita e resa sicura.', '', 28153),
(156066, 'itIT', 'Ci sono risorse importanti nelle vicinanze. Se fossero nostre, potremmo cambiare le sorti dello scontro.', '', 28153),
(156065, 'itIT', '', 'Fai pure, prendimi in giro per l\'altezza. Vedremo poi come te la cavi senza rotule!', 28153),
(156064, 'itIT', 'Nun rompere il ritmo mio.', '', 28153),
(156063, 'itIT', 'Che cosa ci fai qui?', 'Che cosa ci fai qui?', 28153),
(156062, 'itIT', '', 'Kiro e io siamo solo di passaggio. La nostra prossima tappa è l\'impero dei Senzafede.\n\nIl mio piano è pronto.\n\nQuei Sethrak non sapranno mai cosa li ha colpiti.', 28153),
(156061, 'itIT', '', 'E così ci incontriamo di nuovo.', 28153),
(156060, 'itIT', 'Hai reso un grande onore ai caduti della VII Legione. Faremo buon uso di questa zona.', '', 28153),
(156059, 'itIT', 'Hai agito bene. Lascia il resto ai miei soldati.', '', 28153),
(156058, 'itIT', '', 'La mia gente vive dentro un vulcano. Continua a infastidirmi e ti farò vedere come erutta un Ferroscuro!', 28153),
(156057, 'itIT', 'Ottima strategia. Presto potremo sfruttare la zona a dovere.', '', 28153),
(156056, 'itIT', 'Bel lavoro. Queste risorse daranno grande sostentamento alla VII Legione.', '', 28153),
(156055, 'itIT', 'Ci serve il tuo aiuto per mettere al sicuro la zona. Le mie forze non ce la fanno da sole.', '', 28153),
(156054, 'itIT', 'Molti dei miei soldati sono caduti cercando di conquistare la zona qui vicino. Poni fine alla minaccia.', '', 28153),
(156053, 'itIT', 'Gli esploratori della VII Legione hanno definito questa regione di estrema importanza. Assicurati che non ci siano pericoli.', '', 28153),
(156052, 'itIT', '', 'I Tre Martelli sono uniti.', 28153),
(156051, 'itIT', 'La VII Legione ha bisogno di risorse che si trovano qui vicino. Impadroniscitene con ogni mezzo necessario.', '', 28153),
(156050, 'itIT', '', 'Possa il tuo martello colpire duramente.', 28153),
(156049, 'itIT', '', 'Che l\'Incudine Nera vegli su di te.', 28153),
(156048, 'itIT', '', 'I Ferroscuro si prenderanno il posto che gli spetta in questo mondo.', 28153),
(156047, 'itIT', '', 'Bene, procedi. Io ho del lavoro da fare!', 28153),
(156046, 'itIT', '', 'Ora puoi andare.', 28153),
(156045, 'itIT', '', 'Ti congedo.', 28153),
(156044, 'itIT', 'Bombardate il mio bersaglio!', 'Bombardate il mio bersaglio!', 28153),
(156043, 'itIT', 'Cannoni! Fuoco!', 'Cannoni! Fuoco!', 28153),
(156042, 'itIT', 'Bersaglio agganciato!', 'Bersaglio agganciato!', 28153),
(156041, 'itIT', 'Artiglieria! Fuoco sul mio bersaglio!', 'Artiglieria! Fuoco sul mio bersaglio!', 28153),
(156040, 'itIT', '', 'Passiamo agli affari, allora.', 28153),
(156039, 'itIT', '', 'Be\'? Sto ascoltando.', 28153),
(156038, 'itIT', '', 'Usa le buone maniere in presenza di una regina.', 28153),
(156037, 'itIT', 'È bello vedere che le sabbie non ti hanno ancora divorato.', '', 28153),
(156036, 'itIT', '', 'La montagna ci dona la sua forza.', 28153),
(156035, 'itIT', '', 'Ti stai rivolgendo alla Regina Reggente del Clan Ferroscuro.', 28153),
(156034, 'itIT', '', 'Il Clan Ferroscuro avrà il rispetto che merita.', 28153),
(156033, 'itIT', '', 'L\'Alleanza ha bisogno della nostra magia come della nostra forza.', 28153),
(156032, 'itIT', 'Vestizione', 'Vestizione', 28153),
(156031, 'itIT', 'Pulizia', 'Pulizia', 28153),
(156030, 'itIT', '', 'Ottimo lavoro. Cheste risorse aiuteranno molto li Zandalari.', 28153),
(156029, 'itIT', '', 'Nu lavoro coi fiocchi. Presto tutti sapranno che nun si possono intralciare i piani delli Zandalari.', 28153),
(156028, 'itIT', '', 'N\'altra vittoria per l\'Orda. Potrei quasi abituarmi all\'idea di poter contare sull\'aiuto tuo.', 28153),
(156027, 'itIT', '', 'Li Zandalari ti ringraziano per li sforzi tuoi.', 28153),
(156026, 'itIT', '', 'Nathanos nun crede che riusciremo a conquistare l\'area. Dimostragli che si sbaglia.', 28153),
(156025, 'itIT', '', 'L\'area vicino a te dev\'essere ripulita se vogliamo che la campagna nostra continui. Fa\' chello che sai fare meglio.', 28153),
(156024, 'itIT', '', 'Dobbiamo rendere sicura chest\'area per li alleati nostri. Nun mostrare pietà a chiunque tenti di fermarti.', 28153),
(156023, 'itIT', '', 'Ci stanno risorse nelle vicinanze che saranno utili alla campagna nostra. Recuperale.', 28153),
(156022, 'itIT', 'Dot e Dolly li divoreranno in un baleno.', '', 28153),
(156021, 'itIT', 'Dot e Dolly sono creature capricciose. Non lavorerebbero mai a stomaco vuoto. Aiutali a trovare qualcosa da mangiare.', '', 28153),
(156020, 'itIT', 'Sciò!', 'Sciò!', 28153),
(156019, 'itIT', 'Vai via!', 'Vai via!', 28153),
(156018, 'itIT', 'Non puoi toccare!', 'Non puoi toccare!', 28153),
(156017, 'itIT', 'Quando sei vicino, ti schiaccio la testa con una roccia!', 'Quando sei vicino, ti schiaccio la testa con una roccia!', 28153),
(156016, 'itIT', 'Vai via, o ti uccido!', 'Vai via, o ti uccido!', 28153),
(156015, 'itIT', '', 'Vai. Recupera ciò che serve per guarire chest\'uomo serpente. Io dirò a Julwaba ciò che sappiamo.', 28153),
(156014, 'itIT', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a Nuova costruzione disponibile!', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a Nuova costruzione disponibile!', 28153),
(156013, 'itIT', 'Ho servito molti Capoguerra. Ti basta viaggiare un po\' per il mondo per incontrarne parecchi.', '', 28153),
(156012, 'itIT', 'Perché continui a toccarmi? C\'è un\'altra guerra da combattere? Ah, ma cosa dico, c\'è SEMPRE un\'altra guerra da combattere.', '', 28153),
(156011, 'itIT', 'Se sapessi quanto sangue ha già macchiato la mia ascia, ci penseresti due volte prima di infastidirmi!', '', 28153),
(156010, 'itIT', 'Ah, sono troppo vecchio per queste assurdità.', '', 28153),
(156009, 'itIT', 'Io servo l\'Orda.', '', 28153),
(156008, 'itIT', 'Parla in fretta... e di\' il vero.', '', 28153),
(156007, 'itIT', 'Non è il momento dei convenevoli.', '', 28153),
(156006, 'itIT', 'Che cosa vuoi da me?', '', 28153),
(156005, 'itIT', 'Throm\'ka!', '', 28153),
(156004, 'itIT', 'Lok\'tar!', '', 28153),
(156003, 'itIT', 'Il mio nome è Faucisaure, fratello di Broxigar.', '', 28153),
(156002, 'itIT', 'L\'Orda resisterà.', '', 28153),
(156001, 'itIT', 'Non mi piacciono più. Vado via!', 'Non mi piacciono più. Vado via!', 28153),
(156000, 'itIT', 'In battaglia, la strategia è importante quanto la forza.', '', 28153),
(155999, 'itIT', 'Urrà! Sono libero!', 'Urrà! Sono libero!', 28153),
(155998, 'itIT', 'Vado via di qui!', 'Vado via di qui!', 28153),
(155997, 'itIT', 'Noi siamo la vera forza di Kalimdor.', '', 28153),
(155996, 'itIT', 'Perché è successo???', 'Perché è successo???', 28153),
(155995, 'itIT', 'Non posso morire! Guardami le spalle!', 'Non posso morire! Guardami le spalle!', 28153),
(155994, 'itIT', 'Cosa succede?!?', 'Cosa succede?!?', 28153),
(155993, 'itIT', 'Attenzione, Umani pazzi ovunque!', 'Attenzione, Umani pazzi ovunque!', 28153),
(155992, 'itIT', 'Non invecchiare... se puoi scegliere.', '', 28153),
(155991, 'itIT', 'Senza onore non siamo nulla.', '', 28153),
(155990, 'itIT', 'Morire oggi, su questo campo di battaglia, significa morire come un vero Orco.', '', 28153),
(155989, 'itIT', 'Che tu possa morire in battaglia contro un nemico odiato.', '', 28153),
(155988, 'itIT', 'Cerca di guidare Loh al sicuro tra le alghe.', '', 28153),
(155987, 'itIT', '\"Loh e il mare\". Un giovane Tortolliano deve trovare la strada per la salvezza dopo essere emerso dalle sabbie.', '', 28153),
(155986, 'itIT', '', 'Le forze delle streghe sono state cacciate e i nostri lavoratori possono tornare. Grazie per averli tenuti al sicuro.', 28153),
(155985, 'itIT', 'Chesta la cancello...', '', 28153),
(155984, 'itIT', '', 'Le streghe hanno mandato i loro servitori a intralciare le nostre operazioni di taglio. Raduna i taglialegna e brucia quelle streghe!', 28153),
(155983, 'itIT', '', 'La Conca degli Impennatori è di nuovo libera dall\'influenza della congrega. Grazie.', 28153),
(155982, 'itIT', '', 'La Conca degli Impennatori è stata invasa dalle forze della congrega! Libera i cittadini e riconquista il villaggio!', 28153),
(155981, 'itIT', 'Pssst, di qua $n!', '', 28153),
(155980, 'itIT', '', 'Dobbiamo combattere per ciò che è giusto.', 28153),
(155979, 'itIT', '', 'Quando verrà il momento, sarò con te.', 28153),
(155978, 'itIT', '', 'Fa\' il tuo dovere.', 28153),
(155977, 'itIT', '', 'Dobbiamo aiutare chi non può aiutarsi da solo.', 28153),
(155976, 'itIT', '', 'Senza onore non siamo nulla.', 28153),
(155975, 'itIT', '', 'Se dici a CHIUNQUE ciò che è appena successo, ti darò in pasto al mio grifone. Capito?!?', 28153),
(155974, 'itIT', '', 'Combatterò fino all\'ultimo.', 28153),
(155973, 'itIT', '', '<Grugnisce> Oh no... questo non l\'hai sentito.', 28153),
(155972, 'itIT', '', 'Sono una... ahahah... scudiera disciplinata... ahahah... con una volontà... di ferro!', 28153),
(155971, 'itIT', '', 'Mi fa il solletico! Smettila!', 28153),
(155970, 'itIT', '', 'Ehi, smettila!', 28153),
(155969, 'itIT', '', 'Possiamo farcela.', 28153),
(155968, 'itIT', '', 'Servi con onore.', 28153),
(155967, 'itIT', '', 'Non perdere la rotta.', 28153),
(155966, 'itIT', '', 'Buon viaggio, amici. La mia battaglia è qui, al fianco dei Vulpera.', 28153),
(155965, 'itIT', '', 'Torna quando avrai altre storie!', 28153),
(155964, 'itIT', '', 'Per Kul Tiras!', 28153),
(155963, 'itIT', '', 'Il dovere chiama.', 28153),
(155962, 'itIT', '', 'Addio.', 28153),
(155961, 'itIT', '', 'Com\'è la situazione?', 28153),
(155960, 'itIT', '', 'Finalmente un po\' d\'azione!', 28153),
(155959, 'itIT', '', 'Mi sono preparata tutta la vita per questo.', 28153),
(155956, 'itIT', '', 'Insieme possiamo unificare Kul Tiras.', 28153),
(155955, 'itIT', '', 'Ho sempre sognato un po\' di avventura.', 28153),
(155953, 'itIT', 'La valle è la nostra vera casa.', '', 28153),
(155952, 'itIT', 'Ti copro le spalle, se tu copri le mie.', '', 28153),
(155950, 'itIT', 'Prenditi cura di te.', '', 28153),
(155947, 'itIT', 'Sono con te.', '', 28153),
(155946, 'itIT', '', 'Aggiornamento. Detonazione di Rioriginazione quasi alla potenza massima.', 28153),
(155945, 'itIT', '', 'Attenzione. Detonazione di Rioriginazione quasi a piena capacità.', 28153),
(155944, 'itIT', '', 'Attenzione. Potenza massima imminente.', 28153),
(155943, 'itIT', '', 'Aggiornamento. Livello di potenza quasi al limite.', 28153),
(155942, 'itIT', 'Non c\'è nulla che una giornata di duro lavoro non può sistemare.', '', 28153),
(155941, 'itIT', 'Il mio cuore appartiene a questa valle.', '', 28153),
(155939, 'itIT', '', 'Come posso aiutarti?', 28153),
(155938, 'itIT', 'Hai sentito? Gli abissi mi stanno sussurrando qualcosa. Riguarda te! Cosa? Uh, capisco. Dicono \"smettila di toccare Pike, mostro che non sei altro!\". Affascinante!', '', 28153),
(155937, 'itIT', 'Oh, sono piuttosto utili per un sacco di motivi!$b$bOltre ovviamente a bucare le cose, le piume possiedono anche delle proprietà uniche. Se ridotte in polvere finissima, sono ottime per incollare e basta bollirle per usarne gli olii come detergente. Vanno benissimo anche come stuzzicadenti!', '', 28153),
(155936, 'itIT', 'Dovrò acciderti con le mani mie insieme al resto degli stupidi amici tuoi!', '', 28153),
(155935, 'itIT', 'Tongo... acciso da $gno straniero:na straniera;? L\'avevo sopravvalutato!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155934, 'itIT', 'Nun così... no... arghhh...', '', 28153),
(155933, 'itIT', 'Ho giurato di mantenere la pace in queste terre, ma per te farei volentieri un\'eccezione.', '', 28153),
(155932, 'itIT', 'Infastidiscimi quanto vuoi. La pazienza di un Saggio delle Maree è leggendaria.', '', 28153),
(155931, 'itIT', '', 'Salve!', 28153),
(155930, 'itIT', 'A che ti servono tutte queste penne?', 'A che ti servono tutte queste penne?', 28153),
(155929, 'itIT', 'Offerta', 'Offerta', 28153),
(155928, 'itIT', 'Hai bevuto? E non me ne hai lasciato neanche un po\'? Mi sento offeso.', '', 28153),
(155927, 'itIT', 'Calma, marinaio. So che ho un bell\'aspetto, ma abbiamo del lavoro da fare.', '', 28153),
(155926, 'itIT', 'Be\', a meno che tu non abbia prestato servizio nella marina... o che non ti abbiano catturato i pirati... E, POI, la marina...', '', 28153),
(155925, 'itIT', 'Ah, il mare aperto. I canti pirateschi. Il vento che ti accarezza i peli del petto. QUELLA è libertà!', '', 28153),
(155924, 'itIT', 'Non guardarti indietro.', '', 28153),
(155923, 'itIT', 'Occhi fissi all\'orizzonte.', '', 28153),
(155922, 'itIT', 'Il prossimo giro lo offro io.', '', 28153),
(155921, 'itIT', 'Facciamoci pagare.', '', 28153),
(155920, 'itIT', 'Ci si vede in giro.', '', 28153),
(155919, 'itIT', '<Il respiro di Re Rastakhan è corto e affannato. Le bende che gli fasciano il petto sono inzuppate di sangue.>', '', 28153),
(155918, 'itIT', 'Guardati le spalle là fuori.', '', 28153),
(155917, 'itIT', 'Tieni asciutta la polvere da sparo.', '', 28153),
(155916, 'itIT', 'Qual è la tua storia?', '', 28153),
(155915, 'itIT', 'Eccellente! Inizierò subito a produrre ciò che ci serve. Di sicuro i pescatori locali saranno ben felici di aver a che fare con uno stormo più piccolo.', '', 28153),
(155914, 'itIT', 'Sono Jamil Abul\'housin, Medico Reale di Re Rastakhan. Chesta nun è la prima volta che curo il Re e nun sarà l\'ultima, se i Loa lo vorranno.', '', 28153),
(155913, 'itIT', 'Mi servono delle parti dai pesci e granchi della zona. Sfortunatamente, i gabbiani locali hanno lo stesso desiderio. Recupera ciò di cui ho bisogno e sbarazzati di quegli uccelli!', '', 28153),
(155912, 'itIT', 'Come procedono le cure?', 'Come procedono le cure?', 28153),
(155911, 'itIT', 'Sì... sì! Che questa terra tremi davanti alla potenza dell\'Orda!', '', 28153),
(155910, 'itIT', 'Abbiamo superato molte avversità, il vecchio Re Rastakhan e io. Ma chesta...\n\n<Jamil indica il corpo martoriato del Re.>\n\nChesta è brutta assai.', '', 28153),
(155909, 'itIT', '<Jol non alza lo sguardo dai suoi miscugli.>\n\nIl tempo del Re sta per finire.', '', 28153),
(155908, 'itIT', 'Un lavoro è un lavoro.', '', 28153),
(155907, 'itIT', 'Andrà benissimo. Un peccato che non sia stato possibile sfruttare la minaccia contro i nostri nemici.', '', 28153),
(155906, 'itIT', 'Un potente nemico qui vicino si è dimostrato... problematico per le nostre forze. Confido che tu sappia cosa fare.', '', 28153),
(155905, 'itIT', 'La Capoguerra sarà compiaciuta del tuo successo.', '', 28153),
(155904, 'itIT', 'Un pericoloso nemico si nasconde qui vicino. Eliminalo, prima che intralci i nostri piani.', '', 28153),
(155903, 'itIT', 'Le forze nemiche della zona sono una spina nel fianco per i nostri piani. La Capoguerra desidera che il problema venga risolto. Non deluderla.', '', 28153),
(155902, 'itIT', 'Come ha potuto Rhenik lasciare che succedesse?', 'Come ha potuto Rhenik lasciare che succedesse?', 28153),
(155901, 'itIT', 'Non di nuovo!', 'Non di nuovo!', 28153),
(155900, 'itIT', 'Qualcuno la pagherà per questo!', 'Qualcuno la pagherà per questo!', 28153),
(155899, 'itIT', 'Perché ci va sempre di mezzo il grog?', 'Perché ci va sempre di mezzo il grog?', 28153),
(155898, 'itIT', 'Non il grog!', 'Non il grog!', 28153),
(155897, 'itIT', 'Che sia sangue o oro, ogni cosa ha un costo.', '', 28153),
(155896, 'itIT', 'Be\', non è così che la storia dovrebbe andare. Perché non riprovi?', '', 28153),
(155895, 'itIT', 'Hai sete? Io sì.', '', 28153),
(155894, 'itIT', 'Sono tutt\'orecchi!', '', 28153),
(155893, 'itIT', 'Che si dice?', '', 28153),
(155892, 'itIT', 'Salve!', '', 28153),
(155891, 'itIT', 'Fai attenzione là fuori.', '', 28153),
(155890, 'itIT', 'Alla prossima.', '', 28153),
(155889, 'itIT', 'Salute!', '', 28153),
(155888, 'itIT', 'Grog o birra? O entrambe?', '', 28153),
(155887, 'itIT', 'Vuoi ordinare qualcosa?', '', 28153),
(155886, 'itIT', 'Ben fatto!', '', 28153),
(155885, 'itIT', 'Cosa posso fare per te?', '', 28153),
(155884, 'itIT', 'Riesci a guidare Loh a tutto il cibo sull\'isola e poi alla sua tenda senza fargli incrociare il suo stesso percorso?', '', 28153),
(155883, 'itIT', '\"La vita semplice.\" Un giorno, Loh decise di vivere una vita semplice su un\'isola remota.', '', 28153),
(155882, 'itIT', 'Sai come li chiamavo i cadetti come te durante la Seconda Guerra? Ventose... perché non fate che appiccicarvi a me!', '', 28153),
(155881, 'itIT', 'I viaggi di Loh erano spesso colmi di pericoli. Ascolta questa storia, per esempio...', '', 28153),
(155880, 'itIT', 'Noi Tortolliani adoriamo la storia di Loh, un giovane Tortolliano che viaggiò per il mondo.', '', 28153),
(155879, 'itIT', 'Che cosa vuoi, una storia di guerra?', '', 28153),
(155878, 'itIT', 'Ai miei tempi, sapevamo quando una conversazione era finita.', '', 28153),
(155877, 'itIT', '', 'Il cerchio della vita può essere crudele...', 28153),
(155876, 'itIT', '', 'Una tartaruga ha raggiunto l\'acqua!', 28153),
(155875, 'itIT', '', 'Ti ringrazio.', 28153),
(155874, 'itIT', '', 'Un Tortolliano inizia la sua vita tra grandi pericoli, come queste tartarughe qui sulla spiaggia. Difendile mentre tornano al sicuro in mare!', 28153),
(155873, 'itIT', '', 'Ottimo lavoro! Non proprio l\'utilizzo tipico di una macchina del genere, ma è stato comunque efficace.', 28153),
(155872, 'itIT', '', 'Fate fuori chiunque non indossi un cartellino identificativo!', 28153),
(155871, 'itIT', '', 'Chi è l\'idiota che si è perso svariate casse di bombe?', 28153),
(155870, 'itIT', '', 'Alcuni dei soldati al Presidio di Arom sono riusciti a far funzionare quella macchina d\'estrazione. Scatenala contro i suoi creatori dell\'Orda!', 28153),
(155869, 'itIT', '', 'Potrei risolvere il problema dei costi eccessivi togliendoti dal libro paga!', 28153),
(155868, 'itIT', '', 'Mi toccherà fare dei tagli per riportare i costi in ordine.', 28153),
(155867, 'itIT', 'Invasori nella Fonderia! Ripeto, invas...', 'Invasori nella Fonderia! Ripeto, invas...', 28153),
(155866, 'itIT', 'Che l\'onore ti guidi.', '', 28153),
(155865, 'itIT', 'Per l\'Ammiraglio Supremo.', '', 28153),
(155864, 'itIT', 'Per Kul Tiras.', '', 28153),
(155863, 'itIT', 'Nascondi sempre il tuo sudore al nemico!', '', 28153),
(155862, 'itIT', 'Rimani vigile.', '', 28153),
(155861, 'itIT', 'Che i venti ti siano propizi.', '', 28153),
(155860, 'itIT', 'Puoi andare!', '', 28153),
(155859, 'itIT', '', '', 28153),
(155858, 'itIT', '', '', 28153),
(155857, 'itIT', 'Sputa il rospo!', '', 28153),
(155856, 'itIT', '', '', 28153),
(155855, 'itIT', 'Ho già visto abbastanza guerre per entrambi.', '', 28153),
(155854, 'itIT', 'Novità dal fronte?', '', 28153),
(155853, 'itIT', 'Cosa ti serve?', '', 28153),
(155852, 'itIT', 'Queste vecchie ossa bramano ancora la battaglia.', '', 28153),
(155851, 'itIT', 'Hai qualcosa da segnalare?', '', 28153),
(155850, 'itIT', 'Salve!', '', 28153),
(155849, 'itIT', '', 'Non chiedere favori.', 28153),
(155848, 'itIT', '', 'Per cielo e per mare, la libertà è familiare.', 28153),
(155847, 'itIT', '', 'Kul Tiras resisterà a ogni tempesta.', 28153),
(155846, 'itIT', '', 'Ti ascolto.', 28153),
(155845, 'itIT', '', 'Parla pure.', 28153),
(155844, 'itIT', 'Dobbiamo perseverare.', '', 28153),
(155843, 'itIT', 'Non aver paura delle maree.', '', 28153),
(155842, 'itIT', 'Che le correnti ti guidino.', '', 28153),
(155841, 'itIT', 'Non dimenticare i caduti.', '', 28153),
(155840, 'itIT', 'Guarda sempre il mare.', '', 28153),
(155839, 'itIT', '', 'Non ho tempo da perdere in chiacchiere.', 28153),
(155838, 'itIT', 'La tempesta si risveglia in tutti noi.', '', 28153),
(155837, 'itIT', 'Sono qui per duellare.', 'Sono qui per duellare.', 28153),
(155836, 'itIT', 'Quasi. Eh eh eh! Riprova.', '', 28153),
(155835, 'itIT', 'Oh, uno scontro!', '', 28153),
(155834, 'itIT', 'Ben fatto!', '', 28153),
(155833, 'itIT', 'Ho collezionato molte cose nel corso degli anni. Vedi se riesci a fare lo stesso.', '', 28153),
(155832, 'itIT', 'Certo, se ti piace correre. Se preferisci volare, cerca Pa\'ku, la Loa dei Venti. I totem suoi sono più rari, ma facilitano assai gli spostamenti in città.', '', 28153),
(155831, 'itIT', '', 'Gonk, il Signore delle Forme e il Capobranco, è nu potente Loa. Può darti accesso ai numerosi totem suoi sparsi per la città, che aumenteranno la velocità tua standoci vicino.', 28153),
(155830, 'itIT', 'Le profondità hanno previsto il vostro arrivo.', '', 28153),
(155829, 'itIT', 'Sto ascoltando.', '', 28153),
(155828, 'itIT', 'Hai bisogno di me?', '', 28153),
(155827, 'itIT', 'Che le maree ti benedicano.', '', 28153),
(155826, 'itIT', 'Tirate su le passerelle, partiamo immediatamente. Non voglio buchi nella mia nave.', '', 28153),
(155825, 'itIT', 'Vedo che anche loro stanno cercando l\'Azerite. Molto astuti, ma non veloci abbastanza da fermarci. Muoviamoci prima di attirare la loro attenzione.', '', 28153),
(155824, 'itIT', 'E con questo abbiamo finito. Pare che l\'isola sia libera, e proprio al momento giusto. Nave degli Zandalari all\'orizzonte.', '', 28153),
(155823, 'itIT', 'E sono anche loro interessati all\'Azerite. Non va bene. Uccideteli e prendete tutto ciò che hanno trovato.', '', 28153),
(155822, 'itIT', 'Hozen? Qui? Oh, ormai su queste isole arrivano cani e porci.', '', 28153),
(155821, 'itIT', 'Abbiamo appena rilevato un grosso carico di Azerite nelle vicinanze. Ci sarà da divertirsi.', '', 28153),
(155820, 'itIT', 'Bello! Cioè, volevo dire, è un lavoro sporco e schifoso, ma che ci volete fare? L\'Azerite è pur sempre Azerite.', '', 28153),
(155819, 'itIT', 'Uooo, quello sì che è un mostro enorme! Ed è completamente ricoperto di residui d\'Azerite! Uccidetelo e recupereremo il possibile.', '', 28153),
(155818, 'itIT', 'Va bene, il rilevatore sta evidenziando un\'altra fonte di Azerite vicino alla vostra posizione. Date un\'occhiata.', '', 28153),
(155817, 'itIT', 'Uooo, un gran bel carico! Ottimo lavoro!', '', 28153),
(155816, 'itIT', 'Quello sì che è un bel pezzo d\'Azerite. Estraetelo per bene e noi penseremo a portare i frammenti sulla nave.', '', 28153),
(155815, 'itIT', 'Il nostro Rilevatore d\'Azerite sta mostrando... una fonte di Azerite nelle vicinanze. Perché non andate a investigare? Io, be\', me ne starò qui.', '', 28153),
(155814, 'itIT', 'Avviciniamoci e cercate di non colpire niente. E preparate le passerelle, grazie.', '', 28153),
(155813, 'itIT', 'Potrebbero esserci anche, per esempio, dei ragni giganti. Era solo per dire, non si sa mai!', '', 28153),
(155812, 'itIT', 'Questo è sicuramente il posto giusto. Dovrebbe esserci un sacco di Azerite qui attorno.', '', 28153),
(155811, 'itIT', '$n! Grazie alla Dama Oscura sei $garrivato:arrivata;! Rexxar ha attirato un gruppo di Kul Tirani negli edifici più avanti. Ha bisogno di aiuto!', '$n! Grazie alla Dama Oscura sei $garrivato:arrivata;! Rexxar ha attirato un gruppo di Kul Tirani negli edifici più avanti. Ha bisogno di aiuto!', 28153),
(155810, 'itIT', 'Presto, sottocoperta e pistola in pugno! Le nostre truppe hanno bisogno di noi!', '', 28153),
(155809, 'itIT', 'Questo è ciò che rimane di Vadekius. Era un possente drago.', 'Questo è ciò che rimane di Vadekius. Era un possente drago.', 28153),
(155808, 'itIT', 'Non farti strane idee.', 'Non farti strane idee.', 28153),
(155807, 'itIT', 'Per ucciderlo sarebbe stato necessario qualcosa di davvero oscuro e potente.', 'Per ucciderlo sarebbe stato necessario qualcosa di davvero oscuro e potente.', 28153),
(155806, 'itIT', 'Questo è ciò che rimane di Vadekius. Era un possente drago.', 'Questo è ciò che rimane di Vadekius. Era un possente drago.', 28153),
(155805, 'itIT', 'Ma è un inizio.', 'Ma è un inizio.', 28153),
(155804, 'itIT', 'Il mio cuore non è grande come quello della mia Regina.', 'Il mio cuore non è grande come quello della mia Regina.', 28153),
(155803, 'itIT', 'Ciò che hai fatto a Kyranastrasz non è qualcosa che posso perdonare facilmente.', 'Ciò che hai fatto a Kyranastrasz non è qualcosa che posso perdonare facilmente.', 28153),
(155802, 'itIT', 'Immagino di doverti ringraziare.', 'Immagino di doverti ringraziare.', 28153),
(155801, 'itIT', 'Grazie per il tuo aiuto, $n.', 'Grazie per il tuo aiuto, $n.', 28153),
(155800, 'itIT', 'Non vogliamo che si ripetano quei terribili eventi.', 'Non vogliamo che si ripetano quei terribili eventi.', 28153),
(155799, 'itIT', 'Per trovare il suo luogo di riposo, il Signore della Morte ha invaso il nostro Santuario di Rubino.', 'Per trovare il suo luogo di riposo, il Signore della Morte ha invaso il nostro Santuario di Rubino.', 28153),
(155798, 'itIT', 'Durante la recente guerra con la Legione, uno dei nostri è stato resuscitato come creatura non morta.', 'Durante la recente guerra con la Legione, uno dei nostri è stato resuscitato come creatura non morta.', 28153),
(155797, 'itIT', 'Io e $n ci occuperemo di questo incarico. Vieni, $C, ti accompagno al luogo del rituale.', 'Io e $n ci occuperemo di questo incarico. Vieni, $C, ti accompagno al luogo del rituale.', 28153),
(155796, 'itIT', '', '$n è $gtornato:tornata; dal suo incarico. Potrebbe aiutarti, Zallestrasza.', 28153),
(155795, 'itIT', 'Vi state lamentando fin troppo. Mi sento molto meglio.', 'Vi state lamentando fin troppo. Mi sento molto meglio.', 28153),
(155794, 'itIT', 'Resistete, mentre mi occupo delle cure.', 'Resistete, mentre mi occupo delle cure.', 28153),
(155793, 'itIT', 'Riesci a malapena a stare in piedi, Theo!', 'Riesci a malapena a stare in piedi, Theo!', 28153),
(155792, 'itIT', '', 'Ben fatto, $n! Andiamo nel mio nuovo ufficio.', 28153),
(155791, 'itIT', '', 'Quelle uccisioni erano mie! Le conto lo stesso.', 28153),
(155790, 'itIT', 'Mi servirà un potere incredibile per affrontare Korthek in battaglia. È sempre stato il migliore a combattere, tra noi due.\n\nAssorbirò tutto il possibile da questi cristalli. Speriamo solo che basti.', '', 28153),
(155789, 'itIT', '', 'Il numero dei ragni è tornato a livelli accettabili. La nostra gente può tornare nelle foreste senza paura di finire in una ragnatela.', 28153),
(155788, 'itIT', '', 'Dei pericolosi ragni hanno infestato queste foreste, minacciando i cacciatori di Drustvar. Bruciali tutti!', 28153),
(155787, 'itIT', 'Scambio', 'Scambio', 28153),
(155786, 'itIT', '', 'Ottimo lavoro. Cheste provviste aiuteranno le forze nostre a resistere alle intemperie.', 28153),
(155785, 'itIT', '', 'Li esploratori nostri dicono che li Umani hanno scoperto nu modo per raccogliere il pelo delli animali senza far loro del male. È strano ma... funziona.', 28153),
(155784, 'itIT', 'Qualcosa di maligno si aggira nel campo di taglio. È troppo vicino a Boralus per lasciarlo stare.', '', 28153),
(155783, 'itIT', 'Un\'uccisione pulita! I giorni di quel mostro erano contati sin dal suo ingresso a Kul Tiras.', '', 28153),
(155782, 'itIT', 'I Chigliatori hanno preso qualcosa di grosso. Potrebbero aver bisogno del tuo aiuto.', '', 28153),
(155781, 'itIT', 'Bruciatura', 'Bruciatura', 28153),
(155780, 'itIT', 'Combatteremo insieme. Non ti abbandonerò!', 'Combatteremo insieme. Non ti abbandonerò!', 28153),
(155779, 'itIT', 'Se oggi morirò... sarà combattendo!', 'Se oggi morirò... sarà combattendo!', 28153),
(155778, 'itIT', 'Mojambo nun mi piglierà mai vivo!', 'Mojambo nun mi piglierà mai viva!', 28153),
(155777, 'itIT', 'Mi rifiuto di inchinarmi a Mojambo e alla sua banda!', 'Mi rifiuto di inchinarmi a Mojambo e alla sua banda!', 28153),
(155776, 'itIT', 'Combatterò fino al mio ultimo respiro!', 'Combatterò fino al mio ultimo respiro!', 28153),
(155775, 'itIT', 'Mojambo non ci avrà senza combattere!', 'Mojambo non ci avrà senza combattere!', 28153),
(155774, 'itIT', 'La battaglia si avvicina. Prendi questa spada e tieni gli occhi aperti.', 'La battaglia si avvicina. Prendi questa spada e tieni gli occhi aperti.', 28153),
(155773, 'itIT', 'Chesto posto è la casa nostra. Nessuno ci caccerà via senza combattere.', 'Chesto posto è la casa nostra. Nessuno ci caccerà via senza combattere.', 28153),
(155772, 'itIT', '', 'Ottimo lavoro! I soldati ora hanno un problema in meno di cui preoccuparsi.', 28153),
(155771, 'itIT', '', 'Che uccisione! Potrei imparare molto osservandoti combattere.', 28153),
(155770, 'itIT', '', 'Le vie di Kul Tiras da oggi sono più sicure grazie a te.', 28153),
(155769, 'itIT', '', 'L\'esercito ha già avuto problemi in passato con una bestia qui. Risolviamoli una volta per tutte!', 28153),
(155768, 'itIT', '', 'C\'è una bestia malefica nella zona. Per il bene di Kul Tiras, non possiamo ignorare questa minaccia!', 28153),
(155767, 'itIT', '', 'Un tale abominio non può essere lasciato libero di scatenare il caos tra i civili. Fallo fuori!', 28153),
(155766, 'itIT', 'Non dovresti essere da qualche altra parte?', 'Non dovresti essere da qualche altra parte?', 28153),
(155765, 'itIT', 'Ehi! $gQuello:Quella; mi sta guardando in modo strano!', 'Ehi! $gQuello:Quella; mi sta guardando in modo strano!', 28153),
(155764, 'itIT', 'Sei molto $glontano:lontana; da casa!', 'Sei molto $glontano:lontana; da casa!', 28153),
(155763, 'itIT', 'Rosso di sera, il marinaio si schiera. Rosso di mattina, il marinaio sta in sentina.', '', 28153),
(155762, 'itIT', 'Voglio teletrasportarmi da G\'huun.', 'Voglio teletrasportarmi da G\'huun.', 28153),
(155761, 'itIT', 'Voglio teletrasportarmi da Mythrax.', 'Voglio teletrasportarmi da Mythrax.', 28153),
(155760, 'itIT', 'Voglio teletrasportarmi da Zul.', 'Voglio teletrasportarmi da Zul.', 28153),
(155759, 'itIT', 'Voglio teletrasportarmi dall\'Elementale del Sangue.', 'Voglio teletrasportarmi dall\'Elementale del Sangue.', 28153),
(155758, 'itIT', 'Voglio teletrasportarmi da Zek\'voz.', 'Voglio teletrasportarmi da Zek\'voz.', 28153),
(155757, 'itIT', 'Voglio teletrasportarmi dal Divoratore Fetido.', 'Voglio teletrasportarmi dal Divoratore Fetido.', 28153),
(155756, 'itIT', 'Voglio teletrasportarmi dalla M.A.D.R.E.', 'Voglio teletrasportarmi dalla M.A.D.R.E.', 28153),
(155755, 'itIT', 'Salve, e grazie per il tuo aiuto nel testing di Uldir!\n\nPosso teletrasportarti direttamente da qualunque boss disponibile per il testing.', 'Salve, e grazie per il tuo aiuto nel testing di Uldir!\n\nPosso teletrasportarti direttamente da qualunque boss disponibile per il testing.', 28153),
(155754, 'itIT', '', 'Il mio gatto è scomparso.', 28153),
(155753, 'itIT', 'Nun fare il passo più lungo della gamba, specialmente se tieni na gamba di legno!', '', 28153),
(155752, 'itIT', 'Ricorda, tieni in basso la parte bagnata!', '', 28153),
(155750, 'itIT', 'Vuoi conoscere Bwonsamdi?', '', 28153),
(155749, 'itIT', 'Oh, vivere a terra deve essere na vita davvero triste per te.', '', 28153),
(155748, 'itIT', 'Quando osserverai la Baia dei Re e vedrai le fiamme blu benedette, ricorda che chest\'oggi hai cambiato il destino di molti! È stata na vittoria degna, $n. La flotta apparterrà a Zandalar per sempre!', '', 28153),
(155747, 'itIT', 'Nun esiterò a farti fare nu giro di chiglia.', '', 28153),
(155746, 'itIT', 'Che le vele tue siano piene di venti e l\'anima tua di intenti!', '', 28153),
(155745, 'itIT', 'Ci vediamo!', '', 28153),
(155744, 'itIT', 'Stammi buono! I mari mi chiamano!', '', 28153),
(155743, 'itIT', 'Nun si impara nulla navigando acque tranquille.', '', 28153),
(155742, 'itIT', 'Che i venti ti siano propizi!', '', 28153),
(155741, 'itIT', 'Possano le maree farci incontrare di nuovo!', '', 28153),
(155740, 'itIT', 'Fatti guidare dal vento! Trova nuovi orizzonti!', '', 28153),
(155739, 'itIT', 'Riesci a sentire il sale nell\'aria? Mo\' stai a casa.', '', 28153),
(155738, 'itIT', 'Taz\'okun! Ti do il benvenuto!', '', 28153),
(155737, 'itIT', 'Il lavoro è finito... ma avresti potuto evitare di lasciarti quella scia di sangue dietro le spalle. Cerca di fare meglio la prossima volta.', '', 28153),
(155736, 'itIT', 'Ah, sei tu!', '', 28153),
(155735, 'itIT', 'La Capoguerra ti ordina di prendere il controllo della zona nel nome dell\'Orda. Usa qualsiasi metodo tu ritenga appropriato... basta che conduca alla vittoria.', '', 28153),
(155734, 'itIT', 'Nu giorno senza terra in vista è nu bel giorno!', '', 28153),
(155733, 'itIT', 'Tutto pronto per l\'epico viaggio tuo?', '', 28153),
(155732, 'itIT', 'Voglio raggiungere Uldir (Incursione).', 'Voglio raggiungere Uldir (Incursione).', 28153),
(155731, 'itIT', 'Ben fatto! I nostri falchi troveranno un posto più sicuro dove annidarsi e abbiamo anche meno nemici di cui occuparci.', '', 28153),
(155730, 'itIT', 'Attendo il tuo ritorno con grande ansia!', '', 28153),
(155729, 'itIT', 'Torna il prima possibile!', '', 28153),
(155728, 'itIT', 'Mirate!', 'Mirate!', 28153),
(155727, 'itIT', 'Capisco, di nuovo...', '', 28153),
(155726, 'itIT', 'Mi sembra di capire che hai rotto qualcosa...', '', 28153),
(155725, 'itIT', 'Posso aiutarti?', '', 28153),
(155724, 'itIT', 'Cosa posso fare per te?', '', 28153),
(155723, 'itIT', 'Al riparo!', 'Al riparo!', 28153),
(155722, 'itIT', 'Per tua fortuna, tutto sommato mi piaci. Lo riparerò... di nuovo...', '', 28153),
(155721, 'itIT', 'Davvero? Appoggiare tutto quel peso su una cosa così delicata l\'ha rotta? Chi l\'avrebbe mai detto...', '', 28153),
(155720, 'itIT', 'Non devi essere molto più $gsveglio:sveglia; del mio martello.', '', 28153),
(155719, 'itIT', 'Sono abbastanza sicuro che sia lo stesso che ho riparato l\'ultima volta.', '', 28153),
(155718, 'itIT', 'Vorrei che questi pazzi la smettessero di rompere cose.', '', 28153),
(155717, 'itIT', 'Voglio raggiungere il Maniero dei Crestabianca (Spedizione).', 'Voglio raggiungere il Maniero dei Crestabianca (Spedizione).', 28153),
(155716, 'itIT', 'Voglio raggiungere Tol Dagor (Spedizione).', 'Voglio raggiungere Tol Dagor (Spedizione).', 28153),
(155715, 'itIT', 'Voglio raggiungere l\'Assedio di Boralus (Spedizione).', 'Voglio raggiungere l\'Assedio di Boralus (Spedizione).', 28153),
(155714, 'itIT', 'Voglio raggiungere il Santuario della Tempesta (Spedizione).', 'Voglio raggiungere il Covo della Libertà (Spedizione).', 28153),
(155713, 'itIT', 'Voglio raggiungere il Covo della Libertà (Spedizione).', 'Voglio raggiungere il Covo della Libertà (Spedizione).', 28153),
(155712, 'itIT', 'Per le piume di Plumeria! Mi hai spaventato!', '', 28153),
(155711, 'itIT', 'Gli schiavi di quelle streghe hanno rubato i nostri falchi! Liberali e fai fuori i servitori delle streghe!', '', 28153),
(155710, 'itIT', 'Ti serve qualcosa in particolare? Un cacciavite? O magari un bel cartonato!', '', 28153),
(155709, 'itIT', 'Voglio raggiungere Grottamarcia (Spedizione).', 'Voglio raggiungere Grottamarcia (Spedizione).', 28153),
(155708, 'itIT', 'Voglio raggiungere la Vena Madre (Spedizione).', 'Voglio raggiungere la Vena Madre (Spedizione).', 28153),
(155707, 'itIT', 'Voglio raggiungere il Tempio di Sethraliss (Spedizione).', 'Voglio raggiungere il Tempio di Sethraliss (Spedizione).', 28153),
(155706, 'itIT', 'Voglio raggiungere Requie dei Re (Spedizione).', 'Voglio raggiungere Requie dei Re (Spedizione).', 28153),
(155705, 'itIT', 'I Chigliatori sono pronti a tutto!', '', 28153),
(155704, 'itIT', 'I nostri amici pennuti sono ancora una volta al sicuro dalla magia delle streghe.', '', 28153),
(155703, 'itIT', 'Sembra che le streghe stiano utilizzando dei talismani per maledire i nostri cuccioli appena nati! Elimina quei talismani e tutti i Falconieri ammaliati che vedi, prima che la loro influenza si diffonda!', '', 28153),
(155702, 'itIT', '', 'Scrostati.', 28153),
(155701, 'itIT', '', 'Ho un\'arma e non ho paura di usarla.', 28153),
(155700, 'itIT', '', 'Uff... Sono stufa della tua faccia.', 28153),
(155699, 'itIT', '', 'Mostrami una bestia e i miei Chigliatori se ne occuperanno.', 28153),
(155698, 'itIT', '', 'Muffy, sei un gatto cattivo. Vieni qui subito!', 28153),
(155697, 'itIT', '', 'Qui, bel micetto!', 28153),
(155696, 'itIT', 'Voglio raggiungere Atal\'dazar (Spedizione).', 'Voglio raggiungere Atal\'dazar (Spedizione).', 28153),
(155695, 'itIT', '', 'Fammi sapere quando vuoi giocare coi grandi.', 28153),
(155694, 'itIT', '', 'Ho dei mostri da uccidere.', 28153),
(155693, 'itIT', '', 'Cosa vuoi?', 28153),
(155692, 'itIT', 'Missione compiuta, vero? Bene. Farò rapporto del tuo successo alla Capoguerra.', '', 28153),
(155691, 'itIT', 'Salve, e grazie per il tuo aiuto durante la beta di Battle for Azeroth!\n\nPosso teletrasportarti direttamente nelle incursioni o spedizioni attualmente aperte per il testing. Posso solo teletrasportarti, non cercare un gruppo per te, per cui ti consiglio di organizzarne uno prima di cominciare. Se non dovessi averne uno già pronto, prova la nuova funzione di Ricerca gruppi per trovare nuovi alleati.\n\nAssicurati di scegliere la difficoltà giusta prima di teletrasportarti, perché non potrai uscire facilmente dalla zona per poterla cambiare!', 'Salve, e grazie per il tuo aiuto durante la beta di Battle for Azeroth!\n\nPosso teletrasportarti direttamente nelle incursioni o spedizioni attualmente aperte per il testing. Posso solo teletrasportarti, non cercare un gruppo per te, per cui ti consiglio di organizzarne uno prima di cominciare. Se non dovessi averne uno già pronto, prova la nuova funzione di Ricerca gruppi per trovare nuovi alleati.\n\nAssicurati di scegliere la difficoltà giusta prima di teletrasportarti, perché non potrai uscire facilmente dalla zona per poterla cambiare!', 28153),
(155690, 'itIT', '$n (Orda) possiede ora una |c00FFFF00|Hspell:272295|h[Taglia sulla Testa]|h|r! $gUccidilo:Uccidila; per ottenere la ricompensa.', '$n (Orda) possiede ora una |c00FFFF00|Hspell:272295|h[Taglia sulla Testa]|h|r! $gUccidilo:Uccidila; per ottenere la ricompensa.', 28153),
(155689, 'itIT', '$n (Alleanza) possiede ora una |c00FFFF00|Hspell:272295|h[Taglia sulla Testa]|h|r! $gUccidilo:Uccidila; per ottenere la ricompensa.', '$n (Alleanza) possiede ora una |c00FFFF00|Hspell:272295|h[Taglia sulla Testa]|h|r! $gUccidilo:Uccidila; per ottenere la ricompensa.', 28153),
(155688, 'itIT', 'Le forze nemiche della zona devono essere tenute sotto controllo. Confido che tu sappia come fare.', '', 28153),
(155687, 'itIT', '', 'Mai incontrato un mostro che non fossi in grado di uccidere.', 28153),
(155686, 'itIT', 'Ci è voluto più di quanto mi aspettassi... ma i risultati sono accettabili. La nostra campagna può continuare.', '', 28153),
(155685, 'itIT', 'La Capoguerra reclama il possesso di tutte le risorse dell\'area. Prendi ciò che è nostro.', '', 28153),
(155684, 'itIT', 'Nun tirare in ballo mia sorella.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155683, 'itIT', '', 'Faremo buon uso di queste risorse. Ben fatto!', 28153),
(155682, 'itIT', '', 'Combatti come tua sorella.', 28153),
(155681, 'itIT', '', 'In quest\'area ci sono risorse che farebbero comodo all\'Ordine. Prendi il controllo della zona e recuperale!', 28153),
(155680, 'itIT', 'Come desideri, Madre...', '', 28153),
(155679, 'itIT', '', 'Micio, dove sei?', 28153),
(155678, 'itIT', '', 'Vieni, Arthur.', 28153),
(155677, 'itIT', '', 'Ora, Maresciallo, sii gentile e accompagna Lucille nelle mie stanze, dopo che ti sarai sbarazzato di questa feccia...', 28153),
(155676, 'itIT', '', 'Hai visto il mio gatto?', 28153),
(155675, 'itIT', '', 'Oh, Maresciallo? Non ci si rivolge così a una dama. Forse dovrei insegnarti le buone maniere.', 28153),
(155674, 'itIT', '', 'Ce la fai a stare al passo?', 28153),
(155673, 'itIT', 'Stalle lontano, strega senza cuore!', '', 28153),
(155672, 'itIT', '', 'Un po\' di riconoscenza, figlia mia! Non solo tuo padre è vivo e vegeto, ma presto sarà anche il signore di Kul Tiras! Vieni, unisciti a noi...', 28153),
(155671, 'itIT', '', 'Cosa... Cosa gli hai fatto?!?', 28153),
(155670, 'itIT', '', 'Sono così felice che tu sia qui tra noi, mia cara. Sei mancata molto anche a tuo padre.', 28153),
(155669, 'itIT', '', 'Madre? Sei... tu?', 28153),
(155668, 'itIT', '', 'Adesso basta.', 28153),
(155667, 'itIT', 'Ho sentito che ha a che fare con quelle casse dei Bracescura che siamo andati a prendere.', 'Ho sentito che ha a che fare con quelle casse dei Bracescura che siamo andati a prendere.', 28153),
(155666, 'itIT', 'Il Capitano Stone è davvero entusiasta per qualcosa.', 'Il Capitano Stone è davvero entusiasta per qualcosa.', 28153),
(155665, 'itIT', 'Sono davvero felice di essere stato assegnato qui, oggi.', 'Sono davvero felice di essere stata assegnata qui, oggi.', 28153),
(155664, 'itIT', 'Cosa? Questa è una BOMBA? Pensavo fosse un avocado.', '', 28153),
(155663, 'itIT', '', 'Attento, John. Quella polvere da sparo potrebbe farti saltar via le mani.', 28153),
(155662, 'itIT', 'Ritirate le passerelle, ce ne andiamo! Ottimo lavoro là fuori.', '', 28153),
(155661, 'itIT', 'A quanto pare stanno cercando l\'Azerite pure loro. Andiamocene prima che ci notino. Dobbiamo fare subito rapporto.', '', 28153),
(155660, 'itIT', 'È tutta. A quanto pare abbiamo ripulito l\'isola, e proprio al momento giusto. Ci sta na nave di Kul Tiras all\'orizzonte.', '', 28153),
(155659, 'itIT', 'Pare stiano raccogliendo Azerite pure loro. È nu bene per noi, così sarà tutta in un posto solo! Su, andate a impossessarvene.', '', 28153),
(155658, 'itIT', 'Hozen! Ah! Nun si sa mai cosa aspettarsi in posti del genere.', '', 28153),
(155657, 'itIT', 'Ho visto parecchia Azerite vicino alla posizione vostra. Andate subito a controllare.', '', 28153),
(155656, 'itIT', 'Mmm, così si fa! Avremo la stiva piena in men che nun si dica.', '', 28153),
(155655, 'itIT', 'Uhhh! Quel mostro è enorme, ed è ricoperto di residui d\'Azerite. Accidetelo, e poi penseremo a recuperarne il più possibile.', '', 28153),
(155654, 'itIT', 'Pare che ci sia n\'altra fonte di Azerite vicino a voi. Forse vi conviene andare a controllare.', '', 28153),
(155653, 'itIT', 'Ecco fatto, chesto sì che è nu bel carico. Ottimo lavoro.', '', 28153),
(155652, 'itIT', 'Ah, sì! Chisto è nu bel pezzo d\'Azerite. Estraetelo e noi lo porteremo a bordo il prima possibile.', '', 28153),
(155651, 'itIT', 'Il dispositivo sta indicando la presenza di Azerite nei paraggi. Andate là fuori e cercate in giro.', '', 28153),
(155650, 'itIT', 'Abbassate le passerelle. Siamo arrivati.', '', 28153),
(155649, 'itIT', 'Nun abbiamo idea di cos\'altro ci attenda accà. Guardatevi le spalle.', '', 28153),
(155648, 'itIT', 'Ci siamo quasi. Chesta è l\'isola che gli esploratori nostri dicono nasconda nu sacco di Azerite.', '', 28153),
(155647, 'itIT', 'Subito, Capitano.', 'Subito, Capitano.', 28153),
(155646, 'itIT', '', 'Bene, allora caricatela sulla nave! Quegli esplosivi sono un pericolo per la sicurezza.', 28153),
(155645, 'itIT', 'S... Sì, Capitano Stone.', 'S... Sì, Capitano Stone.', 28153),
(155644, 'itIT', '', 'Quella polvere da sparo proviene dalla Fonderia dei Bracescura?', 28153),
(155643, 'itIT', 'Sangue e tuono, che stregoneria è questa? Le nostre navi distrutte e le nostre truppe gettate in mare!', '', 28153),
(155642, 'itIT', 'Sai, qualcuno al Covo della Libertà potrebbe fare un sacco di soldi vendendo tappi per le orecchie.', '', 28153),
(155641, 'itIT', 'Hai... hai sentito? Aspetta! Non di nuovo! Uccidilo, presto!', '', 28153),
(155640, 'itIT', 'Ottimo! Forse il Covo della Libertà sarà un posto più sicuro ora. Bah, chi voglio prendere in giro?', '', 28153),
(155639, 'itIT', 'Ah! Prendi questo, pappagallo!', '', 28153),
(155638, 'itIT', 'Grandioso! Un debito in meno di cui preoccuparsi.', '', 28153),
(155637, 'itIT', 'Cosa puzza di grog e indossa un cappello rosso? Un pirata. E non uno di quelli amichevoli.', '', 28153),
(155636, 'itIT', 'Alcuni miei amici hanno visto un ricercato, qui vicino. Prendiamoci la sua taglia!', '', 28153),
(155635, 'itIT', 'In quest\'area si trova un fuorilegge particolarmente crudele. Forse dovresti sbarazzartene.', '', 28153),
(155634, 'itIT', 'Ehi, sono i nostri amici della S.P.R. & Co., venuti qui per alleviarci del peso dell\'Azerite. Che tipi gentili. Se vi piacciono, fateveli pure amici.', '', 28153),
(155633, 'itIT', 'La S.P.R. & Co. sta iniziando le operazioni in svariati punti dell\'isola. Dovreste andare a intralciare i loro affari.', '', 28153),
(155632, 'itIT', 'Sono appena arrivati quelli della S.P.R. & Co., vogliosi di guadagnare un sacco di soldi con l\'Azerite come solo i Goblin sanno fare.', '', 28153),
(155631, 'itIT', 'Abbiamo individuato scagnozzi della S.P.R. & Co. in giro per l\'isola. Pare intendano controllare la zona con la forza.', '', 28153),
(155630, 'itIT', 'Barcacce di fattura Vrykul, e parecchie. Pare che un intero clan sia partito in cerca dell\'Azerite.', '', 28153),
(155629, 'itIT', 'Un grosso gruppo di Vrykul si sta avvicinando, probabilmente in cerca del nostro carico. Non lasciamo che lo prendano.', '', 28153),
(155628, 'itIT', 'Una flottiglia di Vrykul è appena arrivata. Un bel gruppo di temibili guerrieri si è accampato sull\'isola, da quel poco che riesco a vedere da dietro questo barile.', '', 28153),
(155627, 'itIT', 'Delle navi di Vrykul si stanno avvicinando. Sembra una squadra d\'incursione. Non fanno altro che depredare. È la loro passione.', '', 28153),
(155626, 'itIT', 'Alcuni Troll poco amichevoli hanno deciso di imbucarsi alla festa. Si sono accampati sull\'isola.', '', 28153),
(155625, 'itIT', 'Canoe dei Troll all\'orizzonte! Saranno qui da un momento all\'altro. Quest\'Azerite sta attirando la feccia peggiore.', '', 28153),
(155624, 'itIT', 'È arrivato un gruppo di Troll dell\'isola, probabilmente in cerca del bottino di Azerite. Se riusciste a tenerli lontani dalla nave, ve ne saremmo molto grati.', '', 28153),
(155623, 'itIT', 'Ascoltate, è appena arrivata una manciata di navi Troll. Perché era proprio quello che ci mancava, un\'intera incursione di Troll. Ottima idea.', '', 28153),
(155622, 'itIT', 'E un ENORME drago è appena apparso dal nulla sopra le nostre teste, proprio quello che ci voleva! È stata una settimana pesante per me, sapete? Comunque, pensiamo al drago.', '', 28153),
(155621, 'itIT', 'Ehi, amici? Un grosso drago ha appena deciso di divertirsi con noi e pare molto interessato alla vostra Azerite. Mi sembrava giusto avvisarvi.', '', 28153),
(155620, 'itIT', 'Draghi, abbiamo dei draghi, e stanno puntando direttamente alla nostra nave. Credo mi stiano guardando. Potreste, ehm, fare qualcosa?', '', 28153),
(155619, 'itIT', 'Un intero stormo di draghi è appena atterrato e credo di sapere dove sono diretti. Buona fortuna!', '', 28153),
(155618, 'itIT', 'E ora che succede al cielo? Perché è così buio? E perché ora l\'isola è piena di cadaveri? Dannazione.', '', 28153),
(155617, 'itIT', 'È la cosa più disgustosa che abbia mai annusato. Chi è stato? Ah, sono i morti. Ehi ragazzi, i morti sono arrivati e stanno cercando l\'Azerite!', '', 28153),
(155616, 'itIT', 'Come se non bastasse, pare che i non morti stiano invadendo tutta l\'isola. Non voglio sapere altro.', '', 28153),
(155615, 'itIT', 'I non morti? Qui? Non ho idea di cosa stia succedendo, ma scommetto niente di buono.', '', 28153),
(155614, 'itIT', 'Occhi aperti, ci sono delle navi dei Tol\'vir all\'orizzonte e non sembrano intenzionati a mercanteggiare pacificamente. Potreste darvi una mossa?', '', 28153),
(155613, 'itIT', 'Oh, i Tol\'vir eh? Non vedevo una di quelle navi da molto, molto tempo. Be\', adesso sono qui e ci odiano a morte.', '', 28153),
(155612, 'itIT', 'Le navi dei Tol\'vir hanno appena attraccato. Come fanno tutti a sapere dove si trova l\'Azerite? Odio questa cosa. Potete occuparvi di loro?', '', 28153),
(155611, 'itIT', 'Cos\'è quello, un Centauro? Un Umantauro? Ehi, sono appena comparsi quelli che sembrano essere dei Tol\'vir.', '', 28153),
(155610, 'itIT', 'Nave di pirati all\'orizzonte. Probabilmente intendono saccheggiare questo posto. I pirati non fanno altro.', '', 28153),
(155609, 'itIT', 'Una ciurma di pirati sta per sbarcare. Ovviamente, dove c\'è un tesoro su un\'isola, i pirati non possono mancare.', '', 28153),
(155608, 'itIT', 'E ora è arrivata una TERZA nave, perché ovviamente le missioni più divertenti me le becco io. Sono pirati, nel caso ve lo stiate chiedendo.', '', 28153),
(155607, 'itIT', 'Ohhh! I cannoni ci hanno appena mancato. Abbiamo dei pirati, un sacco di pirati, diretti verso la costa.', '', 28153),
(155606, 'itIT', 'Sono appena comparsi dei Saurok. Probabilmente hanno sentito l\'odore dell\'Azerite. Aspetta, ma ce l\'hanno un naso? Io non ho intenzione di chiederglielo.', '', 28153),
(155605, 'itIT', 'Un\'intera brigata di Saurok è appena spuntata fuori dall\'oceano. Non sto scherzando.', '', 28153),
(155604, 'itIT', 'Cos\'è quella cosa tra le onde? Oh, fantastico, un plotone di Saurok è appena spuntato dagli abissi. Ve ne dovrete occupare voi.', '', 28153),
(155603, 'itIT', 'Delle lucertole dall\'aspetto minaccioso stanno puntando la nostra nave e l\'Azerite a bordo. Non lasciate che la prendano.', '', 28153),
(155602, 'itIT', 'Abbiamo dei nuovi arrivi: dei tizi che non avevo mai visto prima. Immagino non siano qui per aiutarci.', '', 28153),
(155601, 'itIT', 'Sono appena sbarcate delle facce nuove. Pare stiano recuperando dell\'Azerite come noi, ma c\'è qualcosa... di strano in loro.', '', 28153),
(155600, 'itIT', 'Ah! E quelli da dove sono spuntati? È come se fossero comparsi dal nulla. Eroi, abbiamo compagnia.', '', 28153),
(155599, 'itIT', 'Chi diavolo sono quei tizi? Non riesco a vedere le loro facce. Che siano amichevoli? Probabilmente no.', '', 28153),
(155598, 'itIT', 'Pare che abbiamo attirato l\'attenzione di niente meno che un Dio Antico e i suoi servitori. Potete occuparvi del problema?', '', 28153),
(155597, 'itIT', 'Abbiamo delle mostruosità tentacolose sull\'isola e sì, ne ho abbastanza, io me ne vado. Ci vediamo di sotto.', '', 28153),
(155596, 'itIT', 'Qualcun altro sente dei sussurri? O sto impazzendo, o deve esserci qualche Senzavolto sull\'isola. Oh, naturalmente stanno cercando l\'Azerite!', '', 28153),
(155595, 'itIT', 'Quella è una tempesta di oscurità. Fantastico! Deve essere opera degli Dei Antichi. Fate attenzione ai tentacoli.', '', 28153),
(155594, 'itIT', 'E abbiamo anche dei Mogu, un sacco di Mogu, in cerca di Azerite. Probabilmente intendono venire qui.', '', 28153),
(155593, 'itIT', 'Ho visto dei Mogu nei pressi dell\'isola, poco fa. Tenete gli occhi aperti: non sono... molto... amichevoli.', '', 28153),
(155592, 'itIT', 'Alcuni... ehm... Mogu sono appena sbarcati sull\'isola. Non ho idea di cosa stiano facendo. Lascerò controllare a voi.', '', 28153),
(155591, 'itIT', 'I Mogu stanno per mandare una squadra d\'incursione. Devono aver seguito l\'Azerite, come sempre.', '', 28153),
(155590, 'itIT', 'Bene, ora sono arrivati anche i Naga. Proprio quello che ci voleva. Non farti uccidere là fuori, va bene?', '', 28153),
(155589, 'itIT', 'Ho visto dei Naga con il cannocchiale e saranno qui molto presto. Dagli un bel benvenuto da parte nostra.', '', 28153),
(155588, 'itIT', 'Alcuni Naga sono appena arrivati sull\'isola in cerca di Azerite. Senza dubbio saranno qui per conto di Azshara. Chissà cosa sta escogitando.', '', 28153),
(155587, 'itIT', 'I Naga stanno strisciando fuori dagli abissi e pare abbiano intenzione di colpire i nostri magazzini. Vado a caricare i cannoni.', '', 28153),
(155586, 'itIT', 'La nebbia avanza. No aspetta, vedo delle navi marcescenti. Bene, sono i Kvaldir. Grandioso.', '', 28153),
(155585, 'itIT', 'Ehi, abbiamo rilevato alcune navi dei Kvaldir e saranno qui da un momento all\'altro. Deve essere per l\'Azerite. Perché ho accettato questo lavoro?', '', 28153),
(155584, 'itIT', 'Le cose si fanno fumose. Devono essere i Kvaldir. Tenete gli occhi aperti... in caso riusciate a vedere qualcosa.', '', 28153),
(155583, 'itIT', 'Cos\'è questo odore di alghe? Oh, ehi, sono arrivati i Kvaldir, ragazzi.', '', 28153),
(155582, 'itIT', 'Stiamo per trovarci negli insetti fino al collo... Un enorme sciame di Mantid sta per arrivare. Io me ne sto sotto coperta, voi ragazzi divertitevi!', '', 28153),
(155581, 'itIT', 'Ho sentito parlare di loro, credo si chiamino Mantid. Occupati tu di loro, va bene? Io sono allergico.', '', 28153),
(155580, 'itIT', 'Quello è uno sciame d\'api? No, sono molto più grossi. Ah, giusto! Sono Mantid, e ci sono quasi addosso.', '', 28153),
(155579, 'itIT', 'Questo vi piacerà un sacco: i Mantid sono qui e stanno ovviamente cercando l\'Azerite... ovviamente!', '', 28153),
(155578, 'itIT', 'Oh! Cosa ci è appena volato sopra la testa? L\'avete visto? C\'è un enorme drago da qualche parte sull\'isola. Fate attenzione.', '', 28153),
(155577, 'itIT', 'Un grosso drago è appena apparso, insieme a un gruppetto di draghi più piccoli, e non sembrano felici di ciò che stiamo facendo con l\'Azerite.', '', 28153),
(155576, 'itIT', 'Ma che fortuna, un Drago Nero. Un Drago Nero! E metà del suo stormo! Che fortuna!', '', 28153),
(155575, 'itIT', 'Un grosso drago è appena atterrato sull\'isola. Sapete che la mia barca è infiammabile, vero? Tenetelo lontano. Molto, molto lontano.', '', 28153),
(155574, 'itIT', 'I Tol\'vir stanno dando la caccia all\'Azerite con tutte le forze loro. Guardatevi le spalle, là fuori.', '', 28153),
(155573, 'itIT', 'Ahhh, ci stanno dei Tol\'vir accà. Stanno cercando l\'Azerite proprio come noi.', '', 28153),
(155572, 'itIT', 'Nun avrei mai pensato di vedere n\'altra nave dei Tol\'vir. Ne stanno arrivando n\'altro po\' sulla costa, e sembrano minacciose.', '', 28153),
(155571, 'itIT', 'Sono appena arrivate delle barche. Le ho già viste na volta prima d\'ora: sono i Tol\'vir. Nun sembrano molto amichevoli.', '', 28153),
(155570, 'itIT', '', 'Cerca di riportare indietro la reliquia tutta intera, $n. Astrandis è... un po\' troppo entusiasta.', 28153),
(155569, 'itIT', '', 'È nell\'interesse nostro tenere chei pirati fuori dall\'acqua. Tieni i ringraziamenti miei.', 28153),
(155568, 'itIT', 'Ti getterò dal molo.', '', 28153),
(155567, 'itIT', 'Non sono solo le maree a essere infuriate.', '', 28153),
(155566, 'itIT', 'Non sai chi stai facendo innervosire.', '', 28153),
(155565, 'itIT', '', 'Dobbiamo sapere cosa stanno tramando chei pirati. Intercetta li ordini loro... a qualsiasi costo.', 28153),
(155564, 'itIT', 'Le maree ritornano, sempre.', '', 28153),
(155561, 'itIT', 'Che il mare ti trasporti veloce.', '', 28153),
(155560, 'itIT', 'Non abbandonare mai il mare.', '', 28153),
(155558, 'itIT', 'Odio gli uccelli. Luride bestie strillanti. Ma passiamo a questioni più urgenti.', '', 28153),
(155557, 'itIT', 'Uno dei nostri contatti al Covo della Libertà richiede assistenza per... calmare i suoi uccelli. Confido che saprai come fare.', '', 28153),
(155556, 'itIT', 'Io servo le maree.', '', 28153),
(155554, 'itIT', 'Riesci a sentire... anche tu... il potere della roccia?', '', 28153),
(155553, 'itIT', 'Questa roccia ci renderà RICCHI! Non potete averla!', '', 28153),
(155552, 'itIT', 'Che le maree ti guidino.', '', 28153),
(155551, 'itIT', 'Se dai ascolto alle maree, puoi imparare molto sul mondo.', '', 28153),
(155550, 'itIT', 'Ho i miei sospetti...', '', 28153),
(155549, 'itIT', 'Non farmi chiamare le guardie.', '', 28153),
(155548, 'itIT', 'Se hai qualcosa da dire, ti prego, dilla!', '', 28153),
(155547, 'itIT', 'Ti prego... risparmia il mio gatto.', '', 28153),
(155546, 'itIT', 'Ehm... Perdonami, sono molto occupato.', '', 28153),
(155545, 'itIT', 'Torna con altre storie delle tue avventure!', '', 28153),
(155543, 'itIT', 'Direi che è più uno dei ragazzi di Nedly! Lo pianterò nel fango come tutti gli altri!', '', 28153),
(155540, 'itIT', 'Straordinario!', '', 28153),
(155539, 'itIT', 'Ti auguro una fantastica giornata!', '', 28153),
(155538, 'itIT', 'Fai come se fossi a casa tua. La mia tenuta è la tua tenuta.', '', 28153),
(155536, 'itIT', 'Mangia, bevi, divertiti!', '', 28153),
(155535, 'itIT', 'Ti do il benvenuto al Festival Equestre e di Caccia dei Norwington.', '', 28153),
(155534, 'itIT', '', 'E cinquecento miliardi di norgabyte di immagini di adorabili gattini.', 28153),
(155533, 'itIT', 'Ottimo tempismo! Abbiamo a che fare con un attacco dei Trogg!', '', 28153),
(155532, 'itIT', '', 'Stanno giocando con forze con cui nessuno dovrebbe aver a che fare. Dobbiamo difendere i mari!', 28153),
(155531, 'itIT', 'Guerrieri dell\'Orda! Mostrate all\'Alleanza per cosa combattiamo! Avanzate verso la Fortezza!', '', 28153),
(155530, 'itIT', '', 'Restate uniti! Avanzate! Arathi sarà nostra!', 28153),
(155529, 'itIT', '', 'Li Umani stanno richiamando qualcosa di terribile dalli abissi. Fermali!', 28153),
(155528, 'itIT', 'Tortolliano?', 'Tortolliano?', 28153),
(155527, 'itIT', '', 'Il guscio con braccia e gambe è laggiù!\n\nNon farti ingannare. È molto furbo e ficcanaso! È sempre in giro in cerca di vecchie reliquie, pergamene e cianfrusaglie.\n\nNon vogliamo che trovi per primo il tesoro.', 28153),
(155526, 'itIT', 'Mio zio lo verrà a sapere!', '', 28153),
(155525, 'itIT', 'Fai giusto qualche passo indietro... Per favore.', '', 28153),
(155524, 'itIT', 'Di grazia, potresti lasciarmi stare?', '', 28153),
(155522, 'itIT', 'Immagino sia tutto.', '', 28153),
(155521, 'itIT', 'Nessuno mi aveva detto quanto fosse... difficile guidare gli altri. Ah...', '', 28153),
(155520, 'itIT', 'Sto facendo quello che posso.', '', 28153),
(155516, 'itIT', 'Pescagrossa è sotto il mio controllo!', '', 28153),
(155515, 'itIT', 'Devo dimostrare le mie capacità a mio zio.', '', 28153),
(155514, 'itIT', 'Le maree ti danno il benvenuto.', '', 28153),
(155513, 'itIT', 'D\'accordo.', '', 28153),
(155512, 'itIT', 'Se non ti serve nulla, ti prego di andartene.', '', 28153),
(155511, 'itIT', 'Torno al mio posto.', '', 28153),
(155510, 'itIT', 'Ho doveri da rispettare.', '', 28153),
(155509, 'itIT', 'Mpf.', '', 28153),
(155508, 'itIT', 'Fantastico! Dovrei riuscire a creare delle pozioni... interessanti con questi reagenti.', '', 28153),
(155507, 'itIT', 'Quest\'area è colma di risorse naturali e di reagenti alchemici molto interessanti che possiamo sfruttare! Recuperamene un po\'.', '', 28153),
(155506, 'itIT', '', 'I nostri contadini ti sono grati per aver tenuto la fauna a bada.', 28153),
(155505, 'itIT', '', 'Delle bestie selvagge si stanno avvicinando alle fattorie lungo la costa. Aiuta i nostri contadini e occupati del problema.', 28153),
(155504, 'itIT', 'Toccaci di nuovo e causerai una reazione violenta e potenzialmente fatale.', '', 28153),
(155503, 'itIT', 'Fallo di nuovo e scoprirai che non siamo sempre così mattacchioni.', '', 28153),
(155502, 'itIT', 'Staccaci il cappello e te ne pentirai.', '', 28153),
(155501, 'itIT', 'Tutto qua?', '', 28153),
(155500, 'itIT', 'Cresci con onore. La nostra mente è chiara.', '', 28153),
(155499, 'itIT', 'Che le spore siano con te.', '', 28153),
(155498, 'itIT', 'Ti vediamo.', '', 28153),
(155497, 'itIT', 'I miei saluti!', '', 28153),
(155496, 'itIT', 'Ci dovrà sempre essere... un Re dei Licheni...', '', 28153),
(155495, 'itIT', 'Funganima ha fame!', '', 28153),
(155494, 'itIT', 'ARGH!', '', 28153),
(155493, 'itIT', 'Le spore ci troveranno...', '', 28153),
(155492, 'itIT', 'Non... possiamo... sentire...', '', 28153),
(155491, 'itIT', 'Ti uccido! Muori! Muori!', '', 28153),
(155490, 'itIT', 'Unisciti a noi!', '', 28153),
(155489, 'itIT', 'Muori! Muori! Muori!', '', 28153),
(155488, 'itIT', '', 'Ah! Un\'uccisione del genere farebbe ingelosire i Chigliatori.', 28153),
(155487, 'itIT', 'Una dannata mostruosità sta banchettando con le budella dei nostri allievi. Uccidila... prima che sia costretto a reclutare altri coscritti impreparati.', '', 28153),
(155486, 'itIT', '', 'Alcuni della guardia di Kul Tiras parlano di una grossa bestia nelle vicinanze. È una minaccia per chiunque solchi queste acque.', 28153),
(155485, 'itIT', 'I pirati raccontano storie di un demonio scheletrico che vive nella baia. Questa sì che è una spiegazione migliore.', '', 28153),
(155484, 'itIT', 'Una grossa bestia si è trascinata fino in spiaggia. Non so da dove arrivi, ma sembra pericolosa.', '', 28153),
(155483, 'itIT', 'Ottimo lavoro! Alcuni dei detenuti di Tol Dagor erano lì per un motivo. Era uno di loro.', '', 28153),
(155482, 'itIT', '', 'Nu vero pazzo. Hai salvato molte vite oggi.', 28153),
(155481, 'itIT', 'Ora devo andare...', 'Ora devo andare...', 28153),
(155480, 'itIT', 'Ora sono al sicuro.', 'Ora sono al sicuro.', 28153),
(155479, 'itIT', 'Grazie.', 'Grazie.', 28153),
(155478, 'itIT', 'Voglio riposare...', 'Voglio riposare...', 28153),
(155477, 'itIT', 'Mi sentivo perduto...', 'Mi sentivo perduta...', 28153),
(155476, 'itIT', 'Avevo così paura... Ma ora non più...', 'Avevo così paura... Ma ora non più...', 28153),
(155475, 'itIT', 'Tutto bene?', '', 28153),
(155474, 'itIT', 'La Luce è così accogliente...', 'La Luce è così accogliente...', 28153),
(155473, 'itIT', '', 'Grazie per l\'aiuto. Non lo dimenticheremo.', 28153),
(155471, 'itIT', 'Di qua.', 'Da questa parte.', 28153),
(155470, 'itIT', 'Ricaricate!', 'Ricaricate!', 28153),
(155469, 'itIT', '', 'Eresia! T\'impedirò di interferire!', 28153),
(155468, 'itIT', 'Fuoco!', 'Fuoco!', 28153),
(155467, 'itIT', '', 'Zandalar è fatta interamente d\'oro. Ci deve pur essere un modo per rubare l\'intera città.', 28153),
(155466, 'itIT', '', 'Un evaso dalla prigione delli Umani è sbarcato vicino al porto dell\'Orda. Rappresenta nu pericolo per tutti noi.', 28153),
(155465, 'itIT', 'Credo di riconoscere quel tizio! Aspetta... certo che lo conosco. Questo non è un bene.', '', 28153),
(155464, 'itIT', 'Gli abissi... ci daranno... di più!', '', 28153),
(155463, 'itIT', 'Questo potere è un dono dagli abissi!', '', 28153),
(155462, 'itIT', 'Pensavo che quei Kul Tirani si sarebbero dimostrati dei degni avversari... ma cadono proprio come quei buoni a nulla dell\'Alleanza.', '', 28153),
(155461, 'itIT', 'Una Guardaboschi Oscura ha attirato allo scoperto uno dei consiglieri del Gran Ammiraglio. La trappola è pronta... ti lascerò l\'onore di farla scattare.', '', 28153),
(155460, 'itIT', '', 'Gli spiriti dei morti potranno riposare ancora una volta.', 28153),
(155459, 'itIT', 'Va bene, ma... poi torni, vero?', '', 28153),
(155458, 'itIT', 'Bene, ci vediamo più tardi!', '', 28153),
(155457, 'itIT', 'Mmm! Questo insegnerà all\'Orda che non si scherza con i nostri soldati, ottimo lavoro.', '', 28153),
(155456, 'itIT', 'Uno degli ufficiali dei Marefiero ha messo all\'angolo una Guardaboschi Oscura: aiutalo!', '', 28153),
(155455, 'itIT', 'Sono così orgoglioso di mio padre!', '', 28153),
(155454, 'itIT', 'Sarà proprio una bella giornata!', '', 28153),
(155453, 'itIT', 'Papà dice che a volte anche la gente forte ha paura. Tu hai paura?', '', 28153),
(155452, 'itIT', 'Oh, guarda quei bei pony!', '', 28153),
(155451, 'itIT', 'Non è mai troppo tardi per imparare!', '', 28153),
(155450, 'itIT', 'Arrivederci, per ora!', '', 28153),
(155449, 'itIT', '', 'Questi spiriti sono stati portati alla follia dai servitori delle streghe. Rimuovi quest\'influenza maligna e riportali sul sentiero della pace.', 28153),
(155448, 'itIT', 'Oh be\'... almeno ho asshaggiato la Riserva delli Zanchuli n\'ultima... Hic!... volta prima di morire!', '', 28153),
(155447, 'itIT', 'Li ho sentiti dire che Mojambo stava assoldando rinforzi per la battaglia. La ciurma di Tongo ora è al fianco suo...', '', 28153),
(155446, 'itIT', 'Ho intravisto la banda di Mojambo impegnata a perlustrare l\'arena...', '', 28153),
(155445, 'itIT', 'Hai mantenuto la parte del patto tua, quindi io manterrò la mia...', '', 28153),
(155444, 'itIT', 'Ahhh, erano anni che nun asshaporavo della buona Riserva degli Zanchuli... Hic!', '', 28153),
(155443, 'itIT', 'Ecco il rum. Dimmi cos\'hai sentito.', 'Ecco il rum. Dimmi cos\'hai sentito.', 28153),
(155442, 'itIT', 'Bene, ci si vede! Io sarò... qui.', '', 28153),
(155441, 'itIT', 'Sono in cerca di conoscenza. Tu cosa stai cercando?', '', 28153),
(155440, 'itIT', 'Abbiamo viaggiato in lungo e in largo, ma finalmente siamo qui!', '', 28153),
(155439, 'itIT', 'Buona caccia.', '', 28153),
(155438, 'itIT', 'Per l\'Orda!', '', 28153),
(155437, 'itIT', 'Hai qualche preda da braccare?', '', 28153),
(155436, 'itIT', 'Per le zanne e gli artigli.', '', 28153),
(155435, 'itIT', 'Basta così! Ora ti darò la caccia!', '', 28153),
(155434, 'itIT', 'Smettila! Non sto scherzando!', '', 28153),
(155433, 'itIT', 'Io... ecco... vado a caccia da solo.', '', 28153),
(155432, 'itIT', 'Che la caccia abbia inizio.', '', 28153),
(155431, 'itIT', 'E sia.', '', 28153),
(155430, 'itIT', 'A caccia!', '', 28153),
(155429, 'itIT', 'Inizia la caccia.', '', 28153),
(155428, 'itIT', 'La mia preda si avvicina.', '', 28153),
(155427, 'itIT', 'Sento il richiamo della selva.', '', 28153),
(155426, 'itIT', 'Li vedi quei cavalli? Che bestie fantastiche!', '', 28153),
(155425, 'itIT', 'Spero di rivederti presto!', '', 28153),
(155424, 'itIT', 'Ricorda: non dare da mangiare alla fauna!', '', 28153),
(155423, 'itIT', 'Goditi la permanenza!', '', 28153),
(155422, 'itIT', '...', '', 28153),
(155421, 'itIT', 'Perché siamo quaggiù?', 'Perché siamo quaggiù?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155420, 'itIT', 'Cosa volevi dirmi?', 'Cosa volevi dirmi?', 28153),
(155419, 'itIT', 'Non dobbiamo perdere tempo, non ce ne resta molto.', 'Non dobbiamo perdere tempo, non ce ne resta molto.', 28153),
(155418, 'itIT', 'Come stai?', '', 28153),
(155417, 'itIT', 'Ehilà!', '', 28153),
(155416, 'itIT', 'Ti do il benvenuto al Villaggio Turistico Frizzafonti!', '', 28153),
(155415, 'itIT', '', 'Le mie sorelle... avranno... il potere della pietra!', 28153),
(155414, 'itIT', '', 'La Madre apprezzerà il potere di questa pietra!', 28153),
(155413, 'itIT', 'Decidi tu quale regione colpire per prima. Quando avrai scelto, salperemo immediatamente.', '', 28153),
(155412, 'itIT', 'Bene, non c\'è miglior momento di questo per iniziare. Abbiamo un agente pronto a svolgere un\'importante missione.', '', 28153),
(155411, 'itIT', 'Che la Luce sia con te, Re Wrynn.', '', 28153),
(155410, 'itIT', 'Buon viaggio, mio Re.', '', 28153),
(155409, 'itIT', 'I miei doveri mi impongono di tornare a Roccavento, ma non vedo l\'ora di avere notizie dei tuoi progressi. Sono sicuro che questa campagna è in buone mani. Buona fortuna a tutti voi.', '', 28153),
(155408, 'itIT', 'Campione.', '', 28153),
(155407, 'itIT', 'Per le situazioni che richiedono un approccio più... discreto, il Maestro Mathias Shaw e i suoi agenti dell\'IR:7 sono a tua disposizione.', '', 28153),
(155406, 'itIT', 'È un onore lavorare con te.', '', 28153),
(155405, 'itIT', 'Potrai contare sul pieno supporto dei migliori uomini dell\'Alleanza, ovvero la VII Legione, sotto il comando del Gran Comandante Halford Sventradraghi.', '', 28153),
(155404, 'itIT', 'Sei tra i più grandi eroi dell\'Alleanza, e come tale avrai un ruolo cruciale per la vittoria di questa guerra. Dobbiamo impedire che l\'Orda si allei con gli Zandalari.', '', 28153),
(155403, 'itIT', 'Eroe, è giunto il momento di portare lo scontro a Zandalar. Attendo il tuo arrivo sulla Redenzione del Vento a Boralus.', '', 28153),
(155402, 'itIT', 'Queste foreste sono maledette! Scappa! Scappa finché sei in tempo!', 'Queste foreste sono maledette! Scappa! Scappa finché sei in tempo!', 28153),
(155401, 'itIT', 'Non avevo mai visto nessuno così folle!', 'Non avevo mai visto nessuno così folle!', 28153),
(155400, 'itIT', 'Hanno mangiato il mio cane! Poi avrebbero mangiato me!', 'Hanno mangiato il mio cane! Poi avrebbero mangiato me!', 28153),
(155399, 'itIT', 'Per tutte le chiglie incrostate di cozze, cosa sta succedendo qui?', 'Per tutte le chiglie incrostate di cozze, cosa sta succedendo qui?', 28153),
(155398, 'itIT', 'Un branco di conigli mi stava inseguendo. Conigli!', 'Un branco di conigli mi stava inseguendo. Conigli!', 28153),
(155397, 'itIT', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 'Ahhhhhhhhhhhhhhhhhhhhhh!', 28153),
(155396, 'itIT', 'Gli animali sono impazziti!', 'Gli animali sono impazziti!', 28153),
(155395, 'itIT', 'Ti ringrazio, $gamico:amica;!', 'Ti ringrazio, $gamico:amica;!', 28153),
(155394, 'itIT', 'Teniamo dei Naga striscianti sulla spiaggia laggiù. Ce ne stanno nu sacco in attesa di saccheggiare l\'isola.', '', 28153),
(155393, 'itIT', 'Abbiamo avvistato dei Naga. Dev\'essere per colpa di tutta chell\'Azerite che avete recuperato. Tenete gli occhi aperti.', '', 28153),
(155392, 'itIT', 'Sono appena apparse delle forze dei Naga. Fategliela vedere. Ah!', '', 28153),
(155391, 'itIT', 'Naga in arrivo dalli abissi, in cerca di gemme come noi. State accuort\'.', '', 28153),
(155390, 'itIT', 'Guardatevi le spalle. Nu grosso drago e lo stormo suo sono appena stati avvistati in lontananza, diretti verso di noi.', '', 28153),
(155389, 'itIT', 'Sono appena arrivati nu sacco di draghi e hanno iniziato a raccogliere l\'Azerite. Forse sarebbe il caso di fermarli.', '', 28153),
(155388, 'itIT', 'Ah, teniamo dei visitatori. Uno Stormo di Draghi è appena giunto e sta adocchiando la nave nostra.', '', 28153),
(155387, 'itIT', 'Qualcosa si avvicina in volo... draghi, a quanto pare. Devono essere in cerca dell\'Azerite. State all\'erta.', '', 28153),
(155386, 'itIT', 'Draghi Neri... accà? Stanno cercando pure loro l\'Azerite. Stateve accuort\'.', '', 28153),
(155385, 'itIT', 'Draghi... nun credevo che ne avrei mai visto uno adulto. Stanno cercando l\'Azerite. La nostra Azerite.', '', 28153),
(155384, 'itIT', 'Ué, ci stanno alcuni draghi che stanno atterrando laggiù. A quanto pare l\'Azerite ha attirato l\'attenzione loro.', '', 28153),
(155383, 'itIT', 'Il cielo si sta oscurando... è nu Drago Nero! E si è portato dietro lo stormo suo per saccheggiare l\'isola. Aiuto!', '', 28153),
(155382, 'itIT', 'Sono appena arrivati membri e macchine della S.P.R. & Co. in quantità. Stanno cercando l\'Azerite.', '', 28153),
(155381, 'itIT', 'La S.P.R. & Co. sta cercando di avviare n\'operazione su chest\'isola. Dovete fermarli.', '', 28153),
(155380, 'itIT', 'Ci stanno delli investitori della S.P.R. & Co. intenzionati a pigliare la roba nostra. Ho bisogno che andiate a farci quattro chiacchiere.', '', 28153),
(155379, 'itIT', 'Ehi, amici miei, la S.P.R. & Co. è arrivata. A quanto pare stanno preparando n\'accampamento.', '', 28153),
(155378, 'itIT', 'Ehi, laggiù! Nu gruppo di navi dei Troll. Stanno cercando anche loro l\'Azerite. Nun lasciategliela pigliare!', '', 28153),
(155377, 'itIT', 'Dei Troll isolani sono appena arrivati. Scommetto che intendono depredare tutta quanta l\'isola. Tenete gli occhi aperti.', '', 28153),
(155376, 'itIT', 'Canoe dei Troll all\'orizzonte. Nun mi sono mai piaciuti. Vi andrebbe di acciderne nu po\' per me?', '', 28153),
(155375, 'itIT', 'Una di chelle tribù di Troll sta sbarcando sulla costa, e nun sembrano amichevoli.', '', 28153),
(155374, 'itIT', 'Stiamo sotto il fuoco dei cannoni nemici. Na nave di pirati ha appena gettato l\'ancora e intende depredare l\'isola.', '', 28153),
(155373, 'itIT', 'Ora teniamo anche dei pirati. Sono appena sbarcati sulla costa. Andate a dargli il benvenuto.', '', 28153),
(155372, 'itIT', 'Sta per sbarcare na ciurma di pirati, in cerca dello stesso bottino nostro. State in guardia.', '', 28153),
(155371, 'itIT', 'Argh! Ugh... non mi piaci...', 'Tu... dovresti... andartene...', 28153),
(155370, 'itIT', 'Ci sta n\'altra nave all\'orizzonte. Sembrano pirati. Sbarazzatevene in fretta o ci ruberanno tutto quanto il bottino.', '', 28153),
(155369, 'itIT', 'Riconosco chel suono strisciante. Ci sta n\'incursione di Saurok in arrivo.', '', 28153),
(155368, 'itIT', 'Ci stanno degli strani movimenti nell\'acqua. Ah, a quanto pare sono spuntati dei Saurok... nu sacco di Saurok.', '', 28153),
(155367, 'itIT', 'Delle lucertole dall\'aspetto fetente stanno puntando la nave nostra. Fatele fuori. In fretta, se potete.', '', 28153),
(155366, 'itIT', 'Na brigata di Saurok è spuntata fuori dall\'acqua. Anche loro stanno in cerca dell\'Azerite.', '', 28153),
(155365, 'itIT', 'No... Non la faccia!', 'Ora puoi smetterla...', 28153),
(155364, 'itIT', 'Ahhh! Farò tardi per la consegna!', 'La mia polizza non include questo!', 28153),
(155363, 'itIT', 'Avete sentito? I Mantid stanno accà, in cerca dell\'Azerite. Nun fatevi pungere, eh!', '', 28153),
(155362, 'itIT', 'Nu grosso sciame d\'insetti sta arrivando. Fate attenzione, stanno accà per lo stesso motivo nostro.', '', 28153),
(155361, 'itIT', 'Sono appena comparsi dei tizi, dei Mantid credo. Penso che siano anche loro alla ricerca dell\'Azerite.', '', 28153),
(155360, 'itIT', 'Chel rumore ronzante... proviene dal cielo. Ci stanno nu sacco di insetti in arrivo sull\'isola, credo.', '', 28153),
(155359, 'itIT', 'Ahhh! La mia assicurazione mi pagherà il doppio...', 'Tutto ciò è imbarazzante!', 28153),
(155358, 'itIT', 'Spiriti... accoglietemi...', 'Spiriti... accoglietemi...', 28153),
(155357, 'itIT', 'Cos\'è chesto odore di alghe? Laggiù, dei Kvaldir stanno sbarcando sulla riva.', '', 28153),
(155356, 'itIT', 'Nun si riesce a vedere niente in chesta nebbia. Devono esserci dei Kvaldir là fuori. Guardatevi le spalle.', '', 28153),
(155355, 'itIT', 'Delle navi putrescenti si stanno avvicinando e puzzano di Kvaldir. Stanno accà per l\'Azerite nostra.', '', 28153),
(155354, 'itIT', 'La nebbia sta salendo, ma nun è na foschia normale. I Kvaldir presto saranno accà.', '', 28153),
(155353, 'itIT', 'Chesto nun era... chello che avevo previsto...', 'Chesto nun era... chello che avevo previsto...', 28153),
(155352, 'itIT', 'Ho sempre desiderato na nave di pirati, capo. L\'ho battezzata come la figlia mia, Mala!\n\nSe mai terrò nu dirigibile, lo chiamerò come il figlio mio!', '', 28153),
(155351, 'itIT', 'Come ti è venuto in mente quel nome?', 'Come ti è venuto in mente quel nome?', 28153),
(155350, 'itIT', 'Eheheh...\n\nChesta storia dovrà aspettare, capo.', '', 28153),
(155349, 'itIT', 'Dove hai trovato questa nave?', 'Dove hai trovato questa nave?', 28153),
(155348, 'itIT', 'Garona mi ha mandato a cercare na barca. Eccola accà.', '', 28153),
(155347, 'itIT', 'Perché hai una nave di pirati?', 'Perché hai una nave di pirati?', 28153),
(155346, 'itIT', 'Sono arrivati dei nuovi amichetti. Ahahah! Dei Guerrieri Vrykul, credo.', '', 28153),
(155345, 'itIT', 'Ué, è appena arrivata altra gente. Pare si tratti di Incursori Vrykul. Stateve accuort\'.', '', 28153),
(155344, 'itIT', 'Le barcacce dei Vrykul stanno sbarcando sulla costa. È nu gruppo d\'incursione in cerca della roba nostra.', '', 28153),
(155343, 'itIT', 'Ehi, capo. $gPronto:Pronta; per n\'ammutinamento?', '', 28153),
(155342, 'itIT', 'Vedo delle barcacce all\'orizzonte. Devono essere dei Vrykul in cerca di gemme.', '', 28153),
(155341, 'itIT', 'Qualcuno sta mandando i morti contro di noi. Stateve accuort\', nun fanno parte di chesto mondo.', '', 28153),
(155340, 'itIT', 'Gli spiriti mi dicono che accà ci stanno i morti, e anche loro vogliono l\'Azerite.', '', 28153),
(155339, 'itIT', 'Che tanfo. Devono esserci dei non morti in cerca del bottino nostro. Occhi aperti.', '', 28153),
(155338, 'itIT', 'Chest\'oscurità nun è naturale, qualcosa sta cercando l\'Azerite. Qualcosa di malvagio.', '', 28153),
(155337, 'itIT', 'Ci stanno delli strani nuovi visitatori in cerca dell\'Azerite. Pare facciano parte di nu culto di qualche tipo.', '', 28153),
(155336, 'itIT', 'Ohhh, nun li avevo nemmeno visti arrivare. Tenete compagnia!', '', 28153),
(155335, 'itIT', 'Ehi, chi sono chelli? Pare stiano cercando pure loro l\'Azerite. Forse vi conviene fermarli.', '', 28153),
(155334, 'itIT', 'Teniamo dei nuovi amici. Nun li avevo mai visti prima. Probabilmente stanno accà per l\'Azerite.', '', 28153),
(155333, 'itIT', 'Delle serpi dei Mogu si trovano al largo della costa. Saranno accà da nu momento all\'altro.', '', 28153),
(155332, 'itIT', 'Sono arrivati dei Mogu. Vogliono rubarci il carico nostro. Dategli nu caldo benvenuto. Ah!', '', 28153),
(155331, 'itIT', 'Uno dei Mogu sta venendo a pigliare l\'Azerite nostra. Tenete gli occhi aperti in caso arrivino gruppi d\'incursione.', '', 28153),
(155330, 'itIT', 'Ho visto delle serpi volanti nun molto lontano da accà. Presto i Mogu ci raggiungeranno.', '', 28153),
(155329, 'itIT', 'Mmm... si avvicina na tempesta d\'ombra... Dei Senzavolto stanno venendo verso di noi.', '', 28153),
(155328, 'itIT', 'Pure voi sentite chesti sussurri? Deve essere nu Dio Antico intento a scatenarci contro le forze sue.', '', 28153),
(155327, 'itIT', 'Delli amichetti tentacolosi sono venuti accà in cerca di Azerite. Io... me ne vado di sotto.', '', 28153),
(155326, 'itIT', 'L\'Azerite deve aver attirato l\'attenzione dei Senzavolto. Ne è appena arrivato nu gruppo.', '', 28153),
(155325, 'itIT', 'Uccello cattivo! Niente sangue.', 'Uccello cattivo! Niente sangue.', 28153),
(155324, 'itIT', 'Sciò!', 'Sciò!', 28153),
(155323, 'itIT', '', 'I boschi degli Acqualunga sono di nuovo un luogo sicuro per i nostri cacciatori.', 28153),
(155322, 'itIT', '', 'Gli animali sono caduti vittima del richiamo delle streghe e stanno dando la caccia ai nostri cacciatori! Salvali e uccidi quelle bestie maledette!', 28153),
(155321, 'itIT', '', '$p, sei un po\' la mia spalla comica.', 28153),
(155320, 'itIT', '', 'Hai un aspetto familiare... sei mai $gstato:stata; a Tol Dagor?', 28153),
(155319, 'itIT', '', 'Ben fatto. La fauna della zona non sarà più una minaccia per le comunità circostanti.', 28153),
(155318, 'itIT', '', 'La fauna di queste colline è stata ammaliata dalla maledizione delle streghe! Poni fine a tutto questo, prima che raggiunga il villaggio.', 28153),
(155317, 'itIT', 'Sta diventando difficile riuscire a respirare!', 'Sta diventando difficile riuscire a respirare!', 28153),
(155312, 'itIT', 'Ci vorrà un po\' di tempo perché si riprendano completamente dall\'attacco. Per la Dama Oscura!', '', 28153),
(155311, 'itIT', 'Le forze della nostra Capoguerra hanno stabilito un avamposto nell\'accademia militare. Assistile!', '', 28153),
(155310, 'itIT', '', 'Mi sono addestrata al fianco di quegli uomini. L\'Orda pagherà per i danni che ha fatto.', 28153),
(155309, 'itIT', '', 'Un contingente di élite dell\'Orda ha raggiunto l\'Accademia dei Marefiero. Ai soldati farebbe comodo il nostro aiuto!', 28153),
(155308, 'itIT', '', 'Malautunno è al sicuro ancora una volta, ma dobbiamo rimanere vigili.', 28153),
(155307, 'itIT', '', 'Malautunno è di nuovo sotto l\'influenza della maledizione delle streghe. Spezzala, prima che il villaggio vada perduto!', 28153),
(155306, 'itIT', '', 'Ahah... il potere delle rocce... apparterrà... ai Sacraonda!', 28153),
(155305, 'itIT', '', 'Questa roccia è un dono dal profondo. Non l\'avrete!', 28153),
(155304, 'itIT', 'Quando lo stelo marino è appassito, sapevo di essere rimasto solo, così ho immediatamente trovato nu lavoro al porto. Chel fiore mi ha impedito di diventare nu vagabondo, come tanti altri.', 'Quando lo stelo marino è appassito, sapevo di essere rimasta sola, così ho immediatamente trovato nu lavoro al porto. Chel fiore mi ha impedito di diventare na vagabonda, come tanti altri.', 28153),
(155303, 'itIT', 'Che siano Verrospino o invasori dell\'Orda, la gente di questa valle resisterà.', '', 28153),
(155302, 'itIT', 'No prendere... rocce di Trogg...', '', 28153),
(155301, 'itIT', 'Mie rocce...', '', 28153),
(155300, 'itIT', 'Vi... schiaccio...', '', 28153),
(155299, 'itIT', 'Trogg... rotto...', '', 28153),
(155298, 'itIT', 'Trogg si sbriciola...', '', 28153),
(155297, 'itIT', 'Trogg... uccide...', '', 28153),
(155296, 'itIT', 'Arrrgh!', '', 28153),
(155295, 'itIT', 'Garuuu...', '', 28153),
(155294, 'itIT', 'Questa terra di Trogg! Sparite!', '', 28153),
(155293, 'itIT', 'Aaaaargh! Trogg vi uccide!', '', 28153),
(155292, 'itIT', 'Vi spacco in ciottoli!', '', 28153),
(155291, 'itIT', '', 'Mi sono occupata di far funzionare le cose a dovere qui a Kul Tiras. Come posso aiutarti?', 28153),
(155290, 'itIT', 'Rocce luminose sono di Trogg! Via!', '', 28153),
(155289, 'itIT', 'Graaaah! Distruggere!', '', 28153),
(155288, 'itIT', 'Trogg spacca vostra faccia!', '', 28153),
(155287, 'itIT', 'Trogg spacca vostro cranio!', '', 28153),
(155286, 'itIT', 'Questa terra di Trogg!', '', 28153),
(155285, 'itIT', 'Troggzor!', '', 28153),
(155284, 'itIT', 'Mie rocce! Non vostre!', '', 28153),
(155283, 'itIT', 'Mio tesoro! Mio!', '', 28153),
(155282, 'itIT', 'Rarrragh!', '', 28153),
(155281, 'itIT', 'Aaaaaaaargh!', '', 28153),
(155280, 'itIT', 'Schiacciare! Spezzare! UCCIDERE!', '', 28153),
(155279, 'itIT', 'Trogg spacca!', '', 28153),
(155278, 'itIT', 'Trogg no stupido!', '', 28153),
(155277, 'itIT', 'Oh! Hai visto cos\'ha fatto la Principessa all\'Alleanza? Alla sinistra tua puoi ammirare nu po\' di relitti. Chello sì che il potere di nu Loa!', '', 28153),
(155276, 'itIT', 'I Naga sono stati lontani, per un po\'. Si è parlato di ricostruzione, ma con Gral perduto o troppo debole per aiutare, sono rimaste solo parole.', '', 28153),
(155275, 'itIT', 'Tutti i seguaci suoi sono stati accisi. Gral era furioso! Tutti chelli che si trovavano vicino all\'acqua chella notte sentirono il dolore suo... ogni volta che uno di loro cadeva.', '', 28153),
(155274, 'itIT', 'Oh ho! Era come se un peso si fosse sollevato! Sapevamo che quella strega dai capelli neri era morta!', '', 28153),
(155273, 'itIT', 'Ti auguro una splendida giornata.', '', 28153),
(155272, 'itIT', 'Fai attenzione. Questa terra non è più sicura.', '', 28153),
(155271, 'itIT', 'Ci sono tesori ovunque a Sacraonda.', '', 28153),
(155270, 'itIT', 'Ti do il benvenuto nella valle.', '', 28153),
(155269, 'itIT', 'Salve!', '', 28153),
(155268, 'itIT', 'Brennadam è la mia casa e io la proteggerò.', '', 28153),
(155267, 'itIT', '', 'Sono una donna di parola. Tu e la tua Orda siete i benvenuti nel mio porto.', 28153),
(155266, 'itIT', 'Sì, Capitano. La causa vostra ci sta a cuore. Come speriamo a voi stia a cuore la nostra.', '', 28153),
(155265, 'itIT', '', 'Liberi... Sembra che tu intendessi davvero quello che hai detto.', 28153),
(155264, 'itIT', 'Perché siete venuti...?', '', 28153),
(155263, 'itIT', 'Avete distrutto solo una spina... i rovi rimangono...', '', 28153),
(155262, 'itIT', 'Grah!', '', 28153),
(155261, 'itIT', 'No... le gemme...', '', 28153),
(155260, 'itIT', 'Non potete ucciderci... tutti...', '', 28153),
(155259, 'itIT', 'Avvizzisco...', '', 28153),
(155258, 'itIT', 'Mi spezzo...', '', 28153),
(155257, 'itIT', 'Spine... spezzate...', '', 28153),
(155256, 'itIT', 'Le gemme luminose di questo posto sono nostre!', '', 28153),
(155255, 'itIT', 'Le rocce rendono le nostre spine più forti!', '', 28153),
(155254, 'itIT', 'Questa terra e il suo potere sono nostri!', '', 28153),
(155253, 'itIT', 'La vostra carne non può nulla contro le nostre lancespine.', '', 28153),
(155252, 'itIT', 'Appenderò la vostra carne alla mia capanna!', '', 28153),
(155251, 'itIT', 'Abbiamo scelto bene.', '', 28153),
(155250, 'itIT', 'I nostri rovi reclameranno quest\'isola e la vostra carne!', '', 28153),
(155249, 'itIT', 'Spezzaspine, qui non c\'è posto per la vostra razza.', '', 28153),
(155248, 'itIT', 'Servitori, difendetemi!', '', 28153),
(155247, 'itIT', 'Diamogli un assaggio della loro stessa medicina!', '', 28153),
(155246, 'itIT', 'Non potete fermare i rovi!', '', 28153),
(155245, 'itIT', 'Il vostro sangue nutrirà le spine.', '', 28153),
(155244, 'itIT', 'Attenzione!', '', 28153),
(155243, 'itIT', 'A pezzi!', '', 28153),
(155242, 'itIT', 'Morirete, nemici delle spine.', '', 28153),
(155241, 'itIT', 'Questo posto è nostro!', '', 28153),
(155240, 'itIT', 'Non saremmo stati molto utili, chiusi in una gabbia.', '', 28153),
(155239, 'itIT', 'Infilzate la loro carne!', '', 28153),
(155238, 'itIT', 'Squartate gli intrusi!', '', 28153),
(155237, 'itIT', '', 'Le acque sono agitate davanti a noi!', 28153),
(155236, 'itIT', 'Invasori!', '', 28153),
(155235, 'itIT', 'Morite, spezzaspine!', '', 28153),
(155234, 'itIT', '', 'Che le maree ti guidino.', 28153),
(155233, 'itIT', 'Le reliquie sono al sicuro. Gral non è ancora perduto.', '', 28153),
(155232, 'itIT', 'Sangue e tuono.', '', 28153),
(155231, 'itIT', 'Ho anche trovato questo interessante monile.', '', 28153),
(155230, 'itIT', 'Non avremmo dovuto lasciare l\'avamposto in modo così sbrigativo.', '', 28153),
(155229, 'itIT', '', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_01.BLP:20|t %s piazza una miccia accesa su di te. Stai alla larga dai Barili di Munizioni!', 28153),
(155228, 'itIT', 'Goditi l\'ultimo giorno tuo, Razgaji. La prossima volta che ci vedremo... sarà l\'ultima!', '', 28153),
(155227, 'itIT', 'Il nostro viaggio ci ha portato qui. Le scoperte che abbiamo fatto sono un altro tassello di questo rompicapo.', '', 28153),
(155226, 'itIT', '', 'Fai attenzione là fuori.', 28153),
(155225, 'itIT', '', 'Il sindaco è qui. Come posso aiutarti?', 28153),
(155224, 'itIT', '', 'Devo proteggere gli abitanti di Sacraonda.', 28153),
(155223, 'itIT', '', 'Sei qui per dare una mano?', 28153),
(155222, 'itIT', 'Per l\'Orda!', '', 28153),
(155221, 'itIT', 'Guarda come si dibatte! Sarà divertente togliergli le viscere!', 'Guarda come si dibatte! Sarà divertente togliergli le viscere!', 28153),
(155220, 'itIT', 'Ah! Un\'altra preda nella rete!', 'Ah! Un\'altra preda nella rete!', 28153),
(155219, 'itIT', 'Certo, cumpà. Tengo parecchie belle storie da raccontarti!', '', 28153),
(155218, 'itIT', '', 'Allora, Ty\'jin. Se dobbiamo lavorare insieme, devi dirmi qualcosa di più dell\'Orda.', 28153),
(155217, 'itIT', 'Tutta l\'Azerite... sarà... nostra...', '', 28153),
(155216, 'itIT', 'Quest\'Azerite è proprietà della Compagnia dei Bracescura!', '', 28153),
(155215, 'itIT', '', 'Le forze nemiche si stanno muovendo! Respingile!', 28153),
(155214, 'itIT', '', 'Hai dato alle nostre forze un po\' di respiro.', 28153),
(155213, 'itIT', '', 'Le streghe sono state scacciate! Ben fatto!', 28153),
(155212, 'itIT', '', 'La congrega sta attaccando quest\'area. Sbarazzati di loro!', 28153),
(155211, 'itIT', '', 'Ci hai dato un po\' di respiro. Grazie.', 28153),
(155210, 'itIT', '', 'I cittadini di Drustvar sono sotto l\'attacco dalle forze della congrega! Ricaccia indietro quelle streghe!', 28153),
(155209, 'itIT', '', 'A nome della mia gente, grazie per l\'aiuto.', 28153),
(155208, 'itIT', '', 'La mia gente ha bisogno della tua assistenza. Ti prego, aiutala!', 28153),
(155207, 'itIT', 'No! Per ora faremo come dice. Ce ne andremo... ma quando torneremo nun saremo così generosi!', '', 28153),
(155206, 'itIT', 'Mi occupo io di $gchel buffone:chella buffona; $R, capo! Nessun problema!', 'Mi occupo io di $gchel buffone:chella buffona; $R, capo! Nessun problema!', 28153),
(155205, 'itIT', 'Nun tornerò con te. Voi teppisti credete davvero di poter resistere all\'$gamico mio:amica mia;? Nun iniziate no scontro che nun potete vincere.', '', 28153),
(155204, 'itIT', 'Hai finito? Sono io a decidere quando smetterai! Sai bene cosa succede ai disertori!', '', 28153),
(155203, 'itIT', 'Basta così, Mojambo. Sono stanco di accidere e rubare per sopravvivere. Me ne vado per la strada mia...', '', 28153),
(155202, 'itIT', 'Eheheh...', 'Eheheh...', 28153),
(155201, 'itIT', 'Nun ti stavi nascondendo dai vecchi amici tuoi, vero?', '', 28153),
(155200, 'itIT', 'Ma guarda nu po\', Razgaji! Ve l\'avevo detto che l\'avremmo trovato accà...', '', 28153),
(155199, 'itIT', 'Stai in guardia, nun ci si può fidare di Mojambo...', '', 28153),
(155198, 'itIT', 'Sono pronto. Andiamo.', 'Sono pronta. Andiamo.', 28153),
(155197, 'itIT', 'Che il mare benedica questi lingotti e non li reclami mai.', 'Che il mare benedica questi lingotti e non li reclami mai.', 28153),
(155196, 'itIT', '', 'Grazie al potere del nostro padrone, risorgeremo!', 28153),
(155195, 'itIT', 'Potresti benedire questi Lingotti d\'Argento della Tempesta?', 'Potresti benedire questi Lingotti d\'Argento della Tempesta?', 28153),
(155194, 'itIT', 'Buon viaggio, $R.', 'Buon viaggio, $R.', 28153),
(155193, 'itIT', '', 'Tutti si inchineranno dinnanzi alla Regina Azshara!', 28153),
(155192, 'itIT', '', 'I tuoi occhi bruceranno mentre la sua volontà ti consumerà!', 28153),
(155191, 'itIT', 'Libera l\'arpione.', 'Libera l\'arpione.', 28153),
(155190, 'itIT', '<La creatura ti osserva per un momento prima di tornare con lo sguardo sull\'arpione che le si è conficcato nel fianco.>', '<La creatura ti osserva per un momento prima di tornare con lo sguardo sull\'arpione che le si è conficcato nel fianco.>', 28153),
(155189, 'itIT', 'Dove stai andando?', '', 28153),
(155188, 'itIT', 'Muuga maguduuu! Schiacciateli!', '', 28153),
(155187, 'itIT', 'Ugafa! Mo\' vi faccio male!', '', 28153),
(155186, 'itIT', 'Oooh voi gente fetente! Andate via!', '', 28153),
(155185, 'itIT', 'Chi maguba è questo?', '', 28153),
(155184, 'itIT', 'Gwaahr! Queste rocce... mie rocce!', '', 28153),
(155183, 'itIT', 'Bwaaah! Voi no pigliare tesoro!', '', 28153),
(155182, 'itIT', 'Gwaaah? Chi questo?', '', 28153),
(155181, 'itIT', 'Bwaaguugh! Io vi do in pasto a pesci!', '', 28153),
(155180, 'itIT', 'Agu...?', '', 28153),
(155179, 'itIT', 'Argh!', '', 28153),
(155178, 'itIT', 'Gafu... mogo...', '', 28153),
(155177, 'itIT', 'Uug...', '', 28153),
(155176, 'itIT', 'Muug?!?', '', 28153),
(155175, 'itIT', 'Matufa...', '', 28153),
(155174, 'itIT', 'Gurk!', '', 28153),
(155173, 'itIT', 'A-bu-bu-bu-bu!', '', 28153),
(155172, 'itIT', 'Urga magu?!?', '', 28153),
(155171, 'itIT', 'Gribi!', '', 28153),
(155170, 'itIT', 'Buga buga!', '', 28153),
(155169, 'itIT', 'Argh!', '', 28153),
(155168, 'itIT', 'Uga magudu!', '', 28153),
(155167, 'itIT', 'Bogum?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(155166, 'itIT', 'Buga mabugu!', '', 28153),
(155165, 'itIT', 'Ah gah mah gahma!', '', 28153),
(155164, 'itIT', 'Il suo cuore si sta indebolendo... Non c\'è altro che io possa fare per lui, se non porre fine alle sue sofferenze.', '', 28153),
(155163, 'itIT', 'I Bracescura hanno messo una taglia sulla tua testa!', 'I Bracescura hanno messo una taglia sulla tua testa!', 28153),
(155162, 'itIT', 'Prenderò un trofeo dal tuo cadavere!', 'Prenderò un trofeo dal tuo cadavere!', 28153),
(155161, 'itIT', 'Non potete sconfiggere i Bracescura!', 'Non potete sconfiggere i Bracescura!', 28153),
(155160, 'itIT', 'La città è nostra!', 'La città è nostra!', 28153),
(155159, 'itIT', 'Boralus brucerà!', 'Boralus brucerà!', 28153),
(155158, 'itIT', 'Ti raggiungerò in un posto un po\' più sicuro!', 'Ti raggiungerò in un posto un po\' più sicuro!', 28153),
(155157, 'itIT', 'Mi serve un traghetto per Drustvar.', 'Mi serve un traghetto per Drustvar.', 28153),
(155156, 'itIT', 'Perché... voi qui...?', '', 28153),
(155155, 'itIT', 'Rocce luminose... mie...', '', 28153),
(155154, 'itIT', 'Mia candela!', '', 28153),
(155153, 'itIT', 'Ahi, ahi, ahi!', '', 28153),
(155152, 'itIT', 'Grah!', '', 28153),
(155151, 'itIT', 'Candela... si spegne...', '', 28153),
(155150, 'itIT', 'Aaaaaaaaaaaaaaaaaaah!', '', 28153),
(155149, 'itIT', 'No!', '', 28153),
(155148, 'itIT', 'Vi brucio come candela gigante!', '', 28153),
(155147, 'itIT', 'Vostre candele mie ora!', '', 28153),
(155146, 'itIT', 'Vi schiaccio! Io prendo vostra roba!', '', 28153),
(155145, 'itIT', 'Faccio tunnel in vostro cranio!', '', 28153),
(155144, 'itIT', 'Voi no prendere mie rocce luminose!', '', 28153),
(155143, 'itIT', 'Mia isola! Io re!', '', 28153),
(155142, 'itIT', 'Rocce luminose mie! Mie!', '', 28153),
(155141, 'itIT', 'Noi trovato posto, non voi!', '', 28153),
(155140, 'itIT', 'Questo mio spazio!', '', 28153),
(155139, 'itIT', 'Mordeteli! Prendete loro candele!', '', 28153),
(155138, 'itIT', 'Argh! Invasori!', '', 28153),
(155135, 'itIT', 'Voi no prendere candela!', '', 28153),
(155134, 'itIT', 'Bishibosh!', '', 28153),
(155133, 'itIT', 'Rocce luminose nostre!', '', 28153),
(155132, 'itIT', 'Rocce luccicose fanno candele più luminose!', '', 28153),
(155131, 'itIT', 'Buona fortuna, continentale! Se preghi qualche dio, ti auguro che vegli su di te.', 'Buona fortuna, continentale. Se preghi qualche dio, ti auguro che vegli su di te.', 28153),
(155130, 'itIT', 'Eccoci. Più in là di così non voglio andare.', 'Eccoci. Più in là di così non posso andare.', 28153),
(155129, 'itIT', 'L\'ultima volta che ho gettato l\'ancora lì, un lupo mi ha quasi portato via una gamba...', 'L\'ultima volta che ho gettato l\'ancora lì, un lupo mi ha quasi portato via una gamba...', 28153),
(155128, 'itIT', 'Attracchiamo più avanti. Il Porto del Norcino non è un luogo amichevole di questi giorni.', 'Attraccheremo più avanti. Il Porto del Norcino non è un luogo amichevole di questi giorni.', 28153),
(155127, 'itIT', 'Quali che siano i tuoi affari qui, ti suggerisco di fare in fretta.', 'Quali che siano i tuoi affari qui, ti suggerisco di fare in fretta.', 28153),
(155126, 'itIT', 'Non sono superstizioso come gli altri Kul Tirani, ma devo ammettere che c\'è qualcosa a Drustvar che mette i brividi anche a me.', 'Non sono superstizioso come gli altri Kul Tirani, ma devo ammettere che c\'è qualcosa a Drustvar che mette i brividi anche a me.', 28153),
(155125, 'itIT', 'Ultimamente, però, le miniere sembrano prosciugate e non c\'è più alcuna traccia dei macellai.', 'Ultimamente, però, queste miniere sembrano prosciugate e non c\'è più alcuna traccia dei macellai.', 28153),
(155124, 'itIT', 'Fino a poco tempo fa, i commercianti usavano questo trasporto per portare al sicuro merci dai contadini e minatori della zona.', 'Fino a poco tempo fa, i commercianti usavano questa rotta per portare al sicuro merci dai contadini e minatori della zona.', 28153),
(155123, 'itIT', 'La maggior parte dei marinai non ha il coraggio di attraccare lì, con tutte le voci inquietanti che girano.', 'La maggior parte dei marinai non ha coraggio di attraccare lì, con tutte le voci inquietanti a riguardo.', 28153),
(155122, 'itIT', 'Stai andando a Drustvar, eh? È una fortuna che ci sia io a guidare questa barca.', 'Stai andando a Drustvar, eh? È una fortuna che ci sia io a guidare questa barca.', 28153),
(155121, 'itIT', 'Ooh ahh! Ahhhh!', '', 28153),
(155120, 'itIT', 'Argh...', '', 28153),
(155119, 'itIT', 'Vi... gruggo...', '', 28153),
(155118, 'itIT', 'Oh! Dritto nelle frugghe!', '', 28153),
(155117, 'itIT', 'Bleah!', '', 28153),
(155116, 'itIT', 'Sgugga... cattivi...', '', 28153),
(155115, 'itIT', 'Ugga... guggoso...', '', 28153),
(155114, 'itIT', 'No, i miei sbrilli!', '', 28153),
(155113, 'itIT', 'La flora e la fauna di Zandalar richiedono ricerche e catalogazioni.', 'La flora e la fauna di Zandalar richiedono ricerche e catalogazioni.', 28153),
(155112, 'itIT', 'Da dove arrivano questi guggosi?', '', 28153),
(155111, 'itIT', 'Vi gruggo dove fa più male!', '', 28153),
(155110, 'itIT', 'Gruggateli e sguggateli!', '', 28153),
(155109, 'itIT', 'Ottimo lavoro! Torneremo a creare potenti pozioni in men che non si dica!', '', 28153),
(155108, 'itIT', 'Mi spiace, $gamico:amica;, non ho tempo per altri lavori. Il calendario è pieno di... Ehi, non è che hai delle monete? Dimentica ciò che ho appena detto. Come posso aiutarti?', 'Mi spiace, $gamico:amica;, non ho tempo per altri lavori. Il calendario è pieno di... Ehi, non è che hai delle monete? Dimentica ciò che ho appena detto. Come posso aiutarti?', 28153),
(155107, 'itIT', 'Le nostre forze hanno bisogno di altri rifornimenti d\'Alchimia! Recupera i reagenti necessari da quest\'area, ma... fai attenzione agli orsi.', '', 28153),
(155106, 'itIT', '', 'Le streghe stanno attaccando Collefalco! Spazza via ogni traccia della loro infame magia e ripristina l\'ordine nell\'abitato!', 28153),
(155105, 'itIT', '', 'Le streghe sono state cacciate e i cittadini di Collefalco sono di nuovo al sicuro. Hai i nostri ringraziamenti.', 28153),
(155104, 'itIT', '$gBenvenuto:Benvenuta;. Tutto quello che vedi è fresco di razzia dai nativi del luogo. Prova oggi qualcosa di nuovo ed esotico!', '$gBenvenuto:Benvenuta;. Tutto quello che vedi è fresco di razzia dai nativi del luogo. Prova oggi qualcosa di nuovo ed esotico!', 28153),
(155103, 'itIT', 'Uggatevene via, gli sbrilli sono miei!', '', 28153),
(155102, 'itIT', 'Sgugga gruggosi, questa è la mia isola!', '', 28153),
(155101, 'itIT', 'Vi schiaccio, guggosi!', '', 28153),
(155100, 'itIT', 'Colpite con ogni attrezzo!', 'Uccideteli!', 28153),
(155099, 'itIT', 'Sta per capitare un brutto incidente sul lavoro!', 'Niente più sicurezza sul lavoro, ah!', 28153),
(155098, 'itIT', 'So riconoscere un perdente quando lo vedo!', 'Prendi una chiave... nei denti!', 28153),
(155097, 'itIT', 'Periamo... di spada...', '', 28153),
(155096, 'itIT', 'Ci hai sconfitti... ma non hai vinto...', '', 28153),
(155095, 'itIT', 'Che le spore ti colgano...', '', 28153),
(155094, 'itIT', 'Continueremo... oltre la morte...', '', 28153),
(155093, 'itIT', 'Abbandoniamo questo corpo...', '', 28153),
(155092, 'itIT', 'Almeno... moriamo... con onore...', '', 28153),
(155091, 'itIT', 'Infine, cadiamo.', '', 28153),
(155090, 'itIT', 'Cresciamo... per combattere... ancora...', '', 28153),
(155089, 'itIT', 'Per le spore!', '', 28153),
(155088, 'itIT', 'La nostra volontà è una sola!', '', 28153),
(155087, 'itIT', 'Ehi! Qui abbiamo delle regole, e tu le stai infrangendo tutte!', 'Ehi tu... Sei licenziato!', 28153),
(155086, 'itIT', 'Hai esitato! Abbiamo vinto!', '', 28153),
(155085, 'itIT', 'Assaggia la punta delle nostre lame!', '', 28153),
(155084, 'itIT', 'Il nostro volere ci difende!', '', 28153),
(155083, 'itIT', 'È una battaglia che hai già perso!', '', 28153),
(155082, 'itIT', 'Devi fare più pratica!', '', 28153),
(155081, 'itIT', 'Ti faremo a pezzi dalla testa ai piedi!', '', 28153),
(155080, 'itIT', 'Per favore, difendi Boralus!', 'Per favore, difendi Boralus!', 28153),
(155079, 'itIT', 'Quei pirati stanno facendo a pezzi Boralus!', 'Quei pirati stanno facendo a pezzi Boralus!', 28153),
(155078, 'itIT', 'Grazie!', 'Grazie!', 28153),
(155077, 'itIT', 'Schiacciate gli sgugga fino alle frugghe!', '', 28153),
(155076, 'itIT', 'Sono io il re, sgugga!', '', 28153),
(155075, 'itIT', 'Uccideteli! Strappategli le frugghe!', '', 28153),
(155074, 'itIT', 'Sgugga invasori!', '', 28153),
(155073, 'itIT', 'Uccidete gli sgugga!', '', 28153),
(155072, 'itIT', 'Sbrilli ci rendono forti!', '', 28153),
(155071, 'itIT', 'L\'isola è nostra! Non vostra!', '', 28153),
(155070, 'itIT', 'Vi gruggo!', '', 28153),
(155069, 'itIT', 'Non potete prendere i nostri sbrilli!', '', 28153),
(155068, 'itIT', 'Di qui gli sgugga non passano!', '', 28153),
(155067, 'itIT', 'Anni fa, insegnai a Zalazane e Vol\'jin come perfezionare le arti loro. Nun avrei mai immaginato come i destini loro avrebbero cambiato il mondo.', '', 28153),
(155066, 'itIT', 'Stavo solo facendo il mio lavoro!', 'Stavo solo facendo il mio lavoro!', 28153),
(155065, 'itIT', 'Avrei dovuto lavorare per te!', 'Avrei dovuto lavorare per te!', 28153),
(155064, 'itIT', '', 'Mmmsì? Posso aiutarti in qualche modo?', 28153),
(155063, 'itIT', 'Argh... Mi mancherà... la birra...', 'Mi mancherà... la birra...', 28153),
(155062, 'itIT', 'Sapevo che finiva male.', 'Sapevo che questo lavoro sarebbe stato terribile!', 28153),
(155061, 'itIT', 'Spiriti... mi unisco a voi...', 'Spiriti... mi unisco a voi...', 28153),
(155060, 'itIT', 'Devo solo riposare... nu momento...', 'Devo solo riposare... nu momento...', 28153),
(155059, 'itIT', 'Lo dirò a... a... ahhh...', '', 28153),
(155058, 'itIT', 'Prossima volta lascia vincere me...', '', 28153),
(155057, 'itIT', 'Ahah! Io vince... Ugh, aspetta... Ahhh', '', 28153),
(155056, 'itIT', 'No... io no perde...', '', 28153),
(155055, 'itIT', 'Tu problema... Io risolve problema.', '', 28153),
(155054, 'itIT', 'Io tecnico te- term-mi... termico. Io intelligente. Io fa fuoco!', '', 28153),
(155053, 'itIT', 'Tu sta nell\'olio... Io dà fiammifero!', 'Tu sta nell\'olio... Io dà fiammifero!', 28153),
(155052, 'itIT', 'Me no piace fuoco... Tu ha fuoco!', 'Me no piace fuoco... Tu ha fuoco!', 28153),
(155051, 'itIT', 'Per te ho in serbo na bella cottura al sangue.', 'Per te ho in serbo na bella cottura al sangue.', 28153),
(155050, 'itIT', 'Dovevi pensarci due volte prima di infastidirci.', 'Dovevi pensarci due volte prima di infastidirci.', 28153),
(155049, 'itIT', 'Nun scherzare con me, o ti brucerai.', 'Nun scherzare con me, o ti brucerai.', 28153),
(155048, 'itIT', 'Presto sfrigolerai per bene.', 'Presto sfrigolerai per bene.', 28153),
(155047, 'itIT', 'Ah, qualcuno aveva chiesto di scaldare la situazione?', 'Qualcuno aveva chiesto di scaldare la situazione?', 28153),
(155046, 'itIT', 'È tornata negli abissi da cui proveniva.', '', 28153),
(155045, 'itIT', 'La bestia è tornata! Presto, seguila prima che causi altri danni alle mura!', '', 28153),
(155044, 'itIT', 'Cosa? Vol\'jin... nun saresti mai diventato così forte senza diventare nu...', '', 28153),
(155043, 'itIT', 'Credi che distruggere il corpo mio mi impedirà... di farti a pezzi?', '', 28153),
(155042, 'itIT', 'Credi di vincere? Puoi solo ritardare il destino tuo.', '', 28153),
(155041, 'itIT', 'Ho imparato assai guardando Bwonsamdi torturare l\'anima mia. Lascia che ti mostri nu poco del vudù suo.', '', 28153),
(155040, 'itIT', 'Non puoi nasconderlo da me per sempre. Avrò la mia vendetta su Vol\'jin e tutti i Lanciascura!', '', 28153),
(155039, 'itIT', 'Servitori! Accidete chillo campione e portatemi le ceneri di Vol\'jin.', '', 28153),
(155038, 'itIT', 'Dove? Dove ti nascondi Vol\'jin? Dove lo tenete nascosto?', '', 28153),
(155037, 'itIT', 'Dove lo nascondete, Lanciascura? Dove sta il mio vecchio amico?', '', 28153),
(155036, 'itIT', 'Schiacciate i Lanciascura e trovatemi chelle ceneri.', '', 28153),
(155035, 'itIT', 'Cercate, servitori. Trovate le ceneri di Vol\'jin e portatele a me.', '', 28153),
(155034, 'itIT', 'Quei maledetti insetti! Mangerebbero ogni cosa, è disgustoso.', '', 28153),
(155033, 'itIT', 'I ranishu stanno iniziando ad attaccare! Schiacciali prima che diventino un problema troppo grande per noi.', '', 28153),
(155032, 'itIT', 'Lo faremo. Che il vento ti sia favorevole.', 'Lo faremo. Che il vento ti sia favorevole.', 28153),
(155031, 'itIT', 'Sei $griuscito:riuscita; a indicarmi la giusta direzione. Tu te la caverai?', 'Sei $griuscito:riuscita; a indicarmi la giusta direzione. Tu te la caverai?', 28153),
(155030, 'itIT', 'Ci dispiace di non essere stati di più grande aiuto.', 'Mi dispiace che mio fratello e io non siamo stati maggiormente d\'aiuto.', 28153),
(155029, 'itIT', '', 'Ben fatto! È nu bene averti al fianco nostro.', 28153),
(155028, 'itIT', '', 'Ci sta nu nido di Ragni Filasabbia vicino all\'arena. Vai lì e spazzali via!', 28153),
(155027, 'itIT', 'Pare che quell\'arma sia di origine gnomesca. Comunque, dovrebbe andare bene in battaglia.', '', 28153),
(155026, 'itIT', 'I nostri soldati hanno trovato delle... armi interessanti, che potrebbero esserci utili, se riusciamo a capire come usarle. Provale sulla fauna locale.', '', 28153),
(155025, 'itIT', '', 'Ci vorranno settimane perché la Compagnia dei Bracescura recuperi così tanta merce. Ottimo lavoro!', 28153),
(155024, 'itIT', '', 'La Compagnia dei Bracescura sta causando diversi problemi accà vicino. Devi fermarli.', 28153),
(155023, 'itIT', 'Un centinaio di tizi sono finiti su un\'isola piena d\'armi! Vendiamo biglietti per assistere all\'evento a bordo di uno zeppelin!', 'Un centinaio di tizi sono finiti su un\'isola piena d\'armi! Vendiamo biglietti per assistere all\'evento a bordo di uno zeppelin!', 28153),
(155022, 'itIT', 'Tasse sui robot. E poi robot esattori! Soldi infiniti!', 'Tasse sui robot. E poi robot esattori! Soldi infiniti!', 28153),
(155021, 'itIT', 'Una scuradina! Fa l\'esatto opposto di una lampadina!', 'Una scuradina! Fa l\'esatto opposto di una lampadina!', 28153),
(155020, 'itIT', 'Piccoli cappelli formali per cappelli informali da indossare durante eventi formali!', 'Piccoli cappelli formali per cappelli informali da indossare durante eventi formali!', 28153),
(155019, 'itIT', 'Totem levitanti: ideali per viaggi campati in aria!', 'Totem levitanti: ideali per viaggi campati in aria!', 28153),
(155018, 'itIT', 'Scarpe da fuoco! Aspetta, no... le abbiamo già fatte. CALZE da fuoco!', 'Scarpe da fuoco! Aspetta, no... le abbiamo già fatte. CALZE da fuoco!', 28153),
(155017, 'itIT', 'Razzi riciclabili!', 'Razzi riciclabili!', 28153),
(155016, 'itIT', 'Una squadra di genieri Goblin su slitta!', 'Una squadra di genieri Goblin su slitta!', 28153),
(155015, 'itIT', 'Formaggio grana senza grane.', 'Formaggio grana senza grane.', 28153),
(155014, 'itIT', 'Lame da Guerra Rotanti a due mani! Il sogno di ogni Illidari!', 'Lame da Guerra Rotanti a due mani! Il sogno di ogni Illidari!', 28153),
(155013, 'itIT', 'Un sogno dentro un sogno, per riposarsi il doppio!', 'Un sogno dentro un sogno, per riposarsi il doppio!', 28153),
(155012, 'itIT', 'Pinze per barbecue tattiche!', 'Pinze per barbecue tattiche!', 28153),
(155011, 'itIT', 'Una storia d\'amore... tra un Umano e... un Jinyu!', 'Una storia d\'amore... tra un Umano e... un Jinyu!', 28153),
(155010, 'itIT', 'Ben fatto! È un bene averti al nostro fianco.', '', 28153),
(155009, 'itIT', 'Un pilastro, non per tenere in piedi il soffitto, ma per tenere giù il pavimento!', 'Un pilastro, non per tenere in piedi il soffitto, ma per tenere giù il pavimento!', 28153),
(155008, 'itIT', 'C\'è un nido di Ragni Filasabbia, qui vicino, che sta bloccando il passaggio nel canyon. Devi liberare la strada per le nostre forze!', '', 28153),
(155007, 'itIT', 'La prima volta che ho sentito parlare dell\'Azerite credevo fosse una malattia incurabile.', 'La prima volta che ho sentito parlare dell\'Azerite credevo fosse una malattia incurabile.', 28153),
(155006, 'itIT', 'Carbone di Teldrassil! Per un\'affumicatura ricca e gustosa!', 'Carbone di Teldrassil! Per un\'affumicatura ricca e gustosa!', 28153),
(155005, 'itIT', 'Macchine che viaggiano sull\'acqua invece che a terra!', 'Macchine che viaggiano sull\'acqua invece che a terra!', 28153),
(155004, 'itIT', 'Bardi!', 'Bardi!', 28153),
(155003, 'itIT', 'Un fischietto in grado di richiamare l\'attenzione di un maestro di volo!', 'Un fischietto in grado di richiamare l\'attenzione di un maestro di volo!', 28153),
(155002, 'itIT', 'Ottimo lavoro! Un mostro in meno di cui preoccuparsi in questa trappola mortale che chiamano Vol\'dun!', '', 28153),
(155001, 'itIT', 'Un qualche tipo di cristallo arcano capace di renderti migliore in ogni aspetto! Un po\' instabile, forse, ma nulla di cui preoccuparsi!', 'Un qualche tipo di cristallo arcano capace di renderti migliore in ogni aspetto! Un po\' instabile, forse, ma nulla di cui preoccuparsi!', 28153),
(155000, 'itIT', 'Un ranishu gigante sta terrorizzando la gola, ma è troppo feroce per affrontarlo apertamente. Dovrai trovare un altro modo per fermarlo!', '', 28153),
(154999, 'itIT', 'Fucili sparacarta igienica! Immaginati quanto tempo potreste risparmiare!', 'Fucili sparacarta igienica! Immaginati quanto tempo potreste risparmiare!', 28153),
(154998, 'itIT', 'Barcuccette! Avremo un sacco di spazio in mare per altre attività. Io mi prendo quella in alto!', 'Barcuccette! Avremo un sacco di spazio in mare per altre attività. Io mi prendo quella in alto!', 28153),
(154997, 'itIT', 'Gomma da masticare riutilizzabile! Condividetela con i vostri amici, animali o anche stranieri!', 'Gomma da masticare riutilizzabile! Condividetela con i vostri amici, animali o anche stranieri!', 28153),
(154996, 'itIT', 'È stato un lavoro sporco, ma qualcuno doveva farlo! Meglio te che me!', '', 28153),
(154995, 'itIT', 'Dobbiamo trovare un modo per coltivare qualcosa in questo deserto, se vogliamo sopravvivere. Ci servirà del fertilizzante. Vedi cosa riesci a trovare.', '', 28153),
(154994, 'itIT', 'Ammetto che ero scettico, ma sarà davvero utile contro i Senzafede.', '', 28153),
(154993, 'itIT', 'Tacha ha portato alla luce un altro totem Zandalari in una delle rovine. Provalo, così vediamo cos\'è in grado di fare.', '', 28153),
(154992, 'itIT', 'Quello sì che sembrava divertente! Lo terrò da parte per qualche Orco!', '', 28153),
(154991, 'itIT', 'Ci vorranno settimane perché la Compagnia dei Bracescura recuperi così tanta merce. Ottimo lavoro!', '', 28153),
(154990, 'itIT', 'I nostri esploratori hanno trovato questo antico totem Zandalari in una delle rovine. Vediamo cos\'è in grado di fare.', '', 28153),
(154989, 'itIT', 'La Compagnia dei Bracescura sta conducendo operazioni minerarie illegali qui vicino, devi fermarli.', '', 28153),
(154988, 'itIT', 'Le sabbie si diffondono, ma la vita permane. Grazie.', '', 28153),
(154987, 'itIT', 'Le oasi di Vol\'dun sono una preziosa fonte di risorse. Dobbiamo difenderle con cura.', '', 28153),
(154986, 'itIT', 'Non tutte le vittorie vengono da gloriose battaglie. I rifornimenti ci aiuteranno a sopravvivere qui.', '', 28153),
(154985, 'itIT', 'Za uull og nuq i fssh zz oou iiyoq ez oou gul\'kafh anagg.', '', 28153),
(154984, 'itIT', 'Quest\'oasi ci fornirà un grande vantaggio tattico mentre ci espandiamo nel continente.', '', 28153),
(154983, 'itIT', 'La mia caduta non è che un battito del cuore dell\'abisso infinito.', '', 28153),
(154982, 'itIT', 'Devo ammetterlo, è andata meglio di quanto mi aspettassi.', '', 28153),
(154981, 'itIT', 'I nostri... insoliti alleati al Porto di Zem\'lan hanno ideato un nuovo piano. Aiutali, se ti fidi di loro.', '', 28153),
(154980, 'itIT', 'Ah! Così imparano a sfidare l\'Alleanza!', '', 28153),
(154979, 'itIT', 'Alcune nostre truppe hanno rubato una barca riempiendola di armi. Andiamo a sfidare quei mostri non morti!', '', 28153),
(154978, 'itIT', 'Ben fatto! Quei maledetti demoni ci penseranno due volte prima di attaccare di nuovo l\'Alleanza.', '', 28153),
(154977, 'itIT', 'Degli sporchi pirati non morti hanno catturato alcuni dei nostri soldati. Liberali e non lasciare nessuno indietro!', '', 28153),
(154976, 'itIT', '', 'Grazie. Persino gli esiliati si meritano nu destino migliore.', 28153),
(154975, 'itIT', '', 'I pirati di Zem\'lan stanno tenendo prigionieri g]li esiliati Zandalari. Liberali!', 28153),
(154974, 'itIT', 'I Senzafede sono distratti. Fai piovere morte su di loro dal cielo!', '', 28153),
(154973, 'itIT', 'Di certo torneranno, ma per ora possiamo goderci un momento di pace.', '', 28153),
(154972, 'itIT', 'Il numero dei Senzafede pare infinito. Dobbiamo tenerli bloccati qui.', '', 28153),
(154971, 'itIT', 'Gloria a Sethraliss! Possano tutti i Sethrak un giorno ricordare il suo nome...', '', 28153),
(154970, 'itIT', 'Prendi una parte del mio potere e spazza via i Senzafede da queste terre.', '', 28153),
(154969, 'itIT', '', 'La forza mia... Cos\'hai fatto?', 28153),
(154968, 'itIT', '', 'Chesto potere... Nun riesco... a muovermi...', 28153),
(154967, 'itIT', 'La mia vita... mi abbandona...', '', 28153),
(154966, 'itIT', 'Non riesco a muovermi... Aiuto...', '', 28153),
(154965, 'itIT', 'Unnngggrrrh...', '', 28153),
(154964, 'itIT', 'Pensavi davvero di poter sfidare nu dio e sopravvivere? MUORI!', '', 28153),
(154963, 'itIT', 'Altro sangue! La sete deve essere estinta!', '', 28153),
(154962, 'itIT', 'Il sangue tuo mi rafforza!', '', 28153),
(154961, 'itIT', 'Lavorare fa schifo. Basta! Io vado ad allenarmi, così diventerò qualcuno!', 'Lavorare fa schifo. Basta! Io vado ad allenarmi, così diventerò qualcuno!', 28153),
(154960, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk si prepara a lanciare |cFFFF0000|Hspell:258622|h[Impulso Risonante]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Azerokk si prepara a lanciare |cFFFF0000|Hspell:258622|h[Impulso Risonante]|h|r!', 28153),
(154959, 'itIT', 'L\'unica cosa che otterrai da questo grifone è una mano mozzata.', 'L\'unica cosa che otterrai da questo grifone è una mano mozzata.', 28153),
(154956, 'itIT', 'Le ombre si allungano. I prescelti si radunano. Il nostro tempo giunge.', '', 28153),
(154955, 'itIT', 'Darò uno scopo alla vostra carne.', '', 28153),
(154954, 'itIT', '', 'Il mio potere... la mia maledizione... non può esssere...', 28153),
(154953, 'itIT', 'Se... tornerai.', '', 28153),
(154952, 'itIT', 'Al mio ritorno, parleremo di onore... e di come riottenerlo.', '', 28153),
(154951, 'itIT', 'Portatelo alle segrete.', '', 28153),
(154950, 'itIT', 'La vostra specie esiste per nutrire la mia crescita.', '', 28153),
(154949, 'itIT', 'In questo momento... sì.', '', 28153),
(154948, 'itIT', 'Non spetta a un Re dell\'Alleanza deciderlo!', '', 28153),
(154947, 'itIT', 'Ascoltami. Non c\'è onore in tutto questo.', '', 28153),
(154946, 'itIT', 'Mio padre diceva che... Varok Faucisaure incarnava l\'onore dell\'Orda...', '', 28153),
(154945, 'itIT', 'No! Io esigo... una morte onorevole!', '', 28153),
(154944, 'itIT', 'Alleanza... fermi!', '', 28153),
(154940, 'itIT', '', 'Quanta tenacia! Dovressste esssere onorati di esssere visssuti così a lungo da affrontare il mio orgoglio.', 28153),
(154939, 'itIT', 'A tutte le forze, concentrate il fuoco su quel mostro! I Naga non faranno breccia nel muro! Non quest\'oggi!', '', 28153),
(154937, 'itIT', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Mitica.>', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Mitica.>', 28153),
(154936, 'itIT', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Eroica.>', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Eroica.>', 28153),
(154935, 'itIT', '<Mettiti in coda per una Scorreria sulle Isole a difficoltà Mitica.>', '<Mettiti in coda per una Scorreria sulle Isole a difficoltà Mitica.>', 28153),
(154934, 'itIT', '<Mettiti in coda per una Scorreria sulle Isole a difficoltà Eroica.>', '<Mettiti in coda per una Scorreria sulle Isole a difficoltà Eroica.>', 28153),
(154933, 'itIT', 'Va\', Capobranco, ed erigi una statua in mio onore ai piedi di Dazar\'alor. Fa\' in modo che gli altri conoscano la forza del branco e avrai il mio dono.', '', 28153),
(154932, 'itIT', '', 'Con queste tre pergamene, posso renderti più semplice viaggiare qui.', 28153),
(154931, 'itIT', '|TInterface\\ICONS\\Ability_Skyreach_Four_Wind.BLP:20|t %s affronta |cFFFF0000$n|r e prepara una |cFFFF0000|Hspell:268403|h[Sferzata di Burrasca]|h|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s si sta preparando a effettuare un |cFFFF0000|Hspell:268932|h[Balzo Sismico]|h|r verso |cFFFF0000$n|r!', 28153),
(154930, 'itIT', 'Almeno morirò... con entrambi i piedi... a terra...', '', 28153),
(154929, 'itIT', 'Ottimo lancio! Ora hai la mia più completa attenzione.', '', 28153),
(154928, 'itIT', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s ha subito una |cFFFF0000|Hspell:267702|h[Tumulazione]|h|r! Cerca dei segnali su dove potrebbero trovarsi!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s ha subito una |cFFFF0000|Hspell:267702|h[Tumulazione]|h|r! Cerca dei segnali su dove potrebbero trovarsi!', 28153),
(154927, 'itIT', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Sei intrappolato in un sarcofago! Lancia una |cFFFF0000|Hspell:267764|h[Richiesta d\'Aiuto]|h|r per far sapere ai tuoi amici dove ti trovi!', '|TInterface\\ICONS\\INV_Relics_TotemofRage.blp:20|t Sei intrappolata in un sarcofago! Lancia una |cFFFF0000|Hspell:267764|h[Richiesta d\'Aiuto]|h|r per far sapere ai tuoi amici dove ti trovi!', 28153),
(154926, 'itIT', 'Dobbiamo sbrigarci a tornare nel Santuario dei Devoti per impedire al Generale Jakra\'zet di liberare Mythrax!', '', 28153),
(154925, 'itIT', 'Stolto! Mythrax non può essere controllato!', '', 28153),
(154924, 'itIT', 'Mythrax risorgerà e noi conquisteremo tutta Azeroth!', '', 28153),
(154923, 'itIT', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s si sta preparando a lanciare |cFFFF0000|Hspell:267702|h[Tumulazione]|h|r su |cFFFF0000$n|r!', '|TInterface\\ICONS\\Achievement_BG_Xkills_AVgraveyard.blp:20|t %s si sta preparando a lanciare |cFFFF0000|Hspell:267702|h[Tumulazione]|h|r su |cFFFF0000$n|r!', 28153),
(154922, 'itIT', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s si sta preparando a effettuare un |cFFFF0000|Hspell:268932|h[Balzo Sismico]|h|r verso |cFFFF0000$n|r!', '|TInterface\\ICONS\\Ability_Karoz_Leap.blp:20|t %s si sta preparando a effettuare un |cFFFF0000|Hspell:268932|h[Balzo Sismico]|h|r verso |cFFFF0000$n|r!', 28153),
(154921, 'itIT', 'Argh! Vieni avanti e rispondi dei tuoi crimini, Korthek!', '', 28153),
(154920, 'itIT', '', 'Sto accà per osservare. Noi Zandalari siamo assai interessati a chesti Reietti.', 28153),
(154919, 'itIT', '', 'Te lo assicuro, Selvamorta, il piacere è tutto mio.', 28153),
(154918, 'itIT', '', 'Cercherò di scoprire perché la strada è chiusa. Vedi se riesci a convincere i soldati ad andarsene!', 28153),
(154917, 'itIT', 'Preparatevi a partire, sacchi di sterco. Abbiamo pesci più grossi da prendere.', 'Preparatevi a partire, inutili sacchi di sterco. Abbiamo pesci più grossi da prendere.', 28153),
(154916, 'itIT', 'Vattene, pidocchio.', 'Fila via, pidocchio.', 28153),
(154915, 'itIT', 'Sparisci dalla mia vista.', 'Sparisci dalla mia vista.', 28153),
(154914, 'itIT', 'Questa volta ci sono andato leggero.', 'Questa volta ci sono andata leggera.', 28153),
(154913, 'itIT', 'Ne avevo comunque abbastanza di te.', 'Ne avevo comunque abbastanza di te.', 28153),
(154912, 'itIT', '', 'Ti stai concentrando troppo sui dettagli! Andrà tutto bene!', 28153),
(154911, 'itIT', '', 'Ogni cosa ha un prezzo... e questi insetti mi faranno guadagnare una fortuna una volta che li avrò spediti a Kalimdor!', 28153),
(154910, 'itIT', '', 'Tengono bisogno di sangue per sopravvivere, come intendi nutrirli?', 28153),
(154909, 'itIT', '', 'Perché stai mettendo degli insetti in chella scatola?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154908, 'itIT', 'Apri subito il passo.', 'Apri subito il passo.', 28153),
(154907, 'itIT', 'Vedo che il tempo non ha fatto che affinare la tua ferocia e la tua saggezza, Rakjan... Puniremo questi Senzafede per come hanno trattato te e la tua gente.', '', 28153),
(154906, 'itIT', 'L\'unico modo per entrare qui è passare su di me, $gamico:amica;.', 'L\'unico modo per entrare qui è passare su di me, $gamico:amica;.', 28153),
(154905, 'itIT', 'Non ci senti? La valle è chiusa.', 'Non ci senti? La valle è chiusa.', 28153),
(154904, 'itIT', 'Una Maschera Antigas e un Recipiente di Piaga, grazie. Voglio vedere cos\'è capace di fare.', 'Una Maschera Antigas e un Recipiente di Piaga, grazie. Voglio vedere cos\'è capace di fare.', 28153),
(154903, 'itIT', 'Solo una Maschera Antigas per me, grazie.', 'Solo una Maschera Antigas per me, grazie.', 28153),
(154902, 'itIT', 'Torna in fila se non vuoi problemi, cane.', 'Torna in fila se non vuoi problemi, cane.', 28153),
(154901, 'itIT', 'Senza documenti non si entra. Sono le regole.', 'Senza documenti non si entra. Sono le regole.', 28153),
(154899, 'itIT', 'L\'aiuto di Ai\'twen, la mia brillante strategia e la tua incredibile determinazione sono una combinazione imbattibile.', '', 28153),
(154898, 'itIT', 'Io raggiungerò la cima della montagna per assicurarmi che Rakjan non mi abbia dimenticato dopo tutti questi anni.', '', 28153),
(154897, 'itIT', '', 'Riposerò non appena finiranno di arrivare i feriti.', 28153),
(154896, 'itIT', '', 'Sto bene. Questi marinai hanno bisogno di me.', 28153),
(154895, 'itIT', 'Di questo passo, ti servirà un guaritore. Non puoi certo aiutarli da una lettiga.', '', 28153),
(154894, 'itIT', 'Sembri stanca, Feorea, dovresti riposare.', '', 28153),
(154893, 'itIT', 'Prendi il mio bastone e caricalo assorbendo il potere dalle Guglie di Soppressione dei Senzafede.', '', 28153),
(154892, 'itIT', 'Ai\'twen e io ti aspetteremo al campo minato della S.P.R. & Co.', '', 28153),
(154891, 'itIT', 'Mamma! Meerah ci ha salvati!', 'Mamma! Meerah ci ha salvati!', 28153),
(154890, 'itIT', 'Te l\'avevo detto che Meerah non si sarebbe scordata di noi! È la migliore!', 'Te l\'avevo detto che Meerah non si sarebbe scordata di noi! È la migliore!', 28153),
(154889, 'itIT', '', 'Kiro! Sono così felice di rivederti! Hai avuto paura là fuori? Come hai messo le mani su uno dei loro krolusk? Ha un nome? Posso dargliene uno? È gentile?', 28153),
(154888, 'itIT', 'Ti racconterò tutto dopo, Meerah. Prima portiamo la nostra gente al sicuro.', '', 28153),
(154887, 'itIT', 'È stato... sorprendentemente divertente!', '', 28153),
(154886, 'itIT', 'Salta sul krolusk e andiamocene di qui prima che i Senzafede mandino rinforzi!', '', 28153),
(154885, 'itIT', '', 'Cosa succede laggiù? Cuorventoso, portaci lì!', 28153),
(154884, 'itIT', '', 'Inizieremo la ricerca a Brennadam. Quantomeno, con un po\' di fortuna troveremo Fratello Pike.', 28153),
(154883, 'itIT', '', 'Ser Sacraonda governa la casata e praticamente l\'intera valle. Pare sia lui la chiave di tutto questo, ma non si fa vedere a Boralus da mesi.', 28153),
(154882, 'itIT', '', 'Prima dovremo riportare la Casata Sacraonda dalla nostra parte. Hanno il controllo dei Saggi delle Maree, e loro della flotta.', 28153),
(154881, 'itIT', '', 'Tremate sotto l\'ombra della bandiera dei Vulpera, feccia Senzafede!', 28153),
(154880, 'itIT', 'Ti servirà una Maschera Antigas per sopravvivere alla Piaga. Se preferisci, puoi anche portarti un Recipiente di Piaga e aiutarci.', 'Ti servirà una Maschera Antigas per sopravvivere alla Piaga. Se preferisci, puoi anche portarti un Recipiente di Piaga e aiutarci.', 28153),
(154879, 'itIT', '', 'Temo che Kul Tiras sarà di poco aiuto all\'Alleanza fin quando la flotta non tornerà a casa.', 28153),
(154878, 'itIT', '', 'E la nostra gente prigioniera in catene deve sapere che non l\'abbiamo abbandonata.', 28153),
(154877, 'itIT', '', 'Bene. Devono sapere chi sta per ucciderli.', 28153),
(154876, 'itIT', 'È rischioso, Nisha. I Senzafede sapranno che ci troviamo qui.', '', 28153),
(154875, 'itIT', 'Ottimo lavoro. Quel Lich stava attaccando i nostri esploratori con le sue forze. Ora possiamo concentrarci sull\'Orda.', '', 28153),
(154874, 'itIT', 'A Drustvar ci sono le streghe e a Nazmir sembra ci siano dei Lich. Distruggi l\'armata di questo demonio e qualunque cosa la stia potenziando.', '', 28153),
(154873, 'itIT', '', 'Nisha sarà così felice di vederti! È giù al cratere a uccidere Sethrak... come sempre.', 28153),
(154872, 'itIT', 'Impressionante, anche se ho sentito che gli Gnomi si sono rifiutati di lavorare con tecnologia Goblin. Se non altro ora sappiamo di cosa sono capaci.', '', 28153),
(154871, 'itIT', 'Le nostre forze hanno strappato dalle mani dei Goblin un dispositivo sperimentale. Testalo sull\'armata dei Troll del Sangue per avere un\'idea del suo reale potere.', '', 28153),
(154870, 'itIT', 'Ho la brutta sensazione che i Naga stiano tramando qualcos\'altro. Tieni gli occhi aperti.', '', 28153),
(154869, 'itIT', 'Naga! Hanno terrorizzato questo mondo fin troppo a lungo. Poni fine a qualunque cosa stiano facendo.', '', 28153),
(154866, 'itIT', 'È dalla Terza Guerra che non vedevo una tale ferocia contro l\'Orda. Ben fatto.', '', 28153),
(154864, 'itIT', 'Hai combattuto bene contro l\'Orda. La gente di Kul Tiras saprà del tuo coraggio.', '', 28153),
(154863, 'itIT', 'Ottimo lavoro. Speriamo solo che questo conflitto finisca meglio della Seconda Guerra.', '', 28153),
(154861, 'itIT', '', 'I bambini sono prigionieri nel cratere sottostante. Fa\' attenzione!', 28153),
(154859, 'itIT', 'Ottimo lavoro! Niente fermerà l\'Orda!', '', 28153),
(154858, 'itIT', 'Molti esploratori sono stati uccisi nel tentativo di fermare l\'Orda in quest\'area. Tocca a te impedire qualsiasi cosa stiano combinando.', '', 28153),
(154857, 'itIT', 'Ben fatto! Credo che potrei imparare na cosa o due da te, cumpà.', '', 28153),
(154856, 'itIT', 'Il nemico è stato sistemato, ma presto n\'altro prenderà il posto suo. Mo\' però goditi il meritato riposo.', '', 28153),
(154855, 'itIT', '', 'Chiamerò Cuorventoso. C\'è un osservatorio al molo orientale dove può raggiungerci.', 28153),
(154854, 'itIT', 'Ah, vittoria! Ha un sapore dolce, eh, cumpà?', '', 28153),
(154853, 'itIT', 'Durante la Terza Guerra, cominciai a capire le tattiche dell\'Orda. Pare che qui ne abbiano usate di molto pericolose. Manda in fumo i loro piani.', '', 28153),
(154852, 'itIT', 'Ahah! Nun sapeva con chi aveva a che fare, vero?', '', 28153),
(154851, 'itIT', 'Le operazioni dell\'Orda qui vicino mi ricordano la Seconda Guerra. Dobbiamo fermarli prima che riescano nel loro intento.', '', 28153),
(154850, 'itIT', 'Davvero impressionante, cumpà!', '', 28153),
(154848, 'itIT', 'Ci sta na potente anima accà. Sbrigati, abbattila!', '', 28153),
(154846, 'itIT', 'Ci sta nu potente nemico nelle vicinanze. Dobbiamo acciderlo!', '', 28153),
(154845, 'itIT', 'A nome della VII Legione, ti ringrazio per i tuoi sforzi contro l\'Orda.', '', 28153),
(154843, 'itIT', 'La sconfitta dell\'Orda permetterà alla VII Legione di avanzare. Ben fatto!', '', 28153),
(154842, 'itIT', 'Re Anduin verrà a sapere delle tue gesta eroiche contro l\'Orda.', '', 28153),
(154838, 'itIT', 'Gli esploratori affermano che forze dell\'Orda si avvicinano alla tua posizione. Sono vulnerabili a un\'imboscata. Eliminale!', '', 28153),
(154836, 'itIT', 'Abbiamo saputo che c\'è un grosso contingente dell\'Orda qui vicino. È la nostra occasione per colpire!', '', 28153),
(154833, 'itIT', 'Nu bersaglio è vicino, colpisci con rapidità!', '', 28153),
(154832, 'itIT', 'La VII Legione ha scoperto forze dell\'Orda in movimento nelle vicinanze. I tuoi ordini sono di fermarle, insieme ai loro piani!', '', 28153),
(154831, 'itIT', 'Ci sta n\'altra minaccia in agguato nei dintorni. Sai cosa fare.', '', 28153),
(154830, 'itIT', 'Li spiriti parlano di nu potente nemico nella zona. Dovremmo occuparcene... prima che diventi nu problema.', '', 28153),
(154829, 'itIT', 'Na potente minaccia sta in agguato accà vicino. Eliminala!', '', 28153),
(154828, 'itIT', 'Ottimo lavoro! Hai mai pensato di unirti permanentemente alla VII Legione? Ci farebbe davvero comodo il tuo aiuto!', '', 28153),
(154827, 'itIT', 'Un lavoro eccellente. Per Re Anduin! Per l\'Alleanza!', '', 28153),
(154826, 'itIT', 'Quest\'oggi hai reso un grande servizio alla VII Legione e all\'Alleanza.', '', 28153),
(154825, 'itIT', 'Hai i miei ringraziamenti, e quelli di tutti i soldati della VII Legione.', '', 28153),
(154824, 'itIT', 'Mi assicurerò che Re Anduin venga a sapere del tuo coraggio.', '', 28153),
(154823, 'itIT', 'I nostri esploratori dicono che un potente nemico si nasconde vicino alla tua posizione. Eliminalo.', '', 28153),
(154822, 'itIT', 'La VII Legione ha ricevuto l\'ordine di eliminare un obiettivo nelle tue vicinanze.', '', 28153),
(154821, 'itIT', 'Sarà meglio che la prossima volta stiano più attenti. Non potremo essere sempre qui a tirarli fuori dai guai. Grazie.', '', 28153),
(154820, 'itIT', 'Un gruppo di ricerca è stato catturato dai non morti! Aiutali, prima che sia troppo tardi!', '', 28153),
(154819, 'itIT', 'Ci penseremo noi da qui. È tempo di distruggere quel G\'huun.', '', 28153),
(154818, 'itIT', 'Bleah, quindi è un corpo rianimato? Ricacciamolo sottoterra.', '', 28153),
(154817, 'itIT', 'Riconosco il brutto grugno di quel Troll. Cosa sta combinando Zul?', '', 28153),
(154816, 'itIT', '...', '', 28153),
(154815, 'itIT', '...', '', 28153),
(154814, 'itIT', '...', '', 28153),
(154813, 'itIT', '...', '', 28153),
(154812, 'itIT', '...', '', 28153),
(154811, 'itIT', '...', '', 28153),
(154810, 'itIT', '...', '', 28153),
(154809, 'itIT', '...', '', 28153),
(154808, 'itIT', 'Ve ne siete persi uno!', '', 28153),
(154807, 'itIT', '', 'Questa struttura ha sperimentato su numerose forme di vita in cerca di una soluzione contro la corruzione degli Dei Antichi.', 28153),
(154806, 'itIT', 'Argh! Ma che diavolo è quella cosa?!?', '', 28153),
(154805, 'itIT', '...', '', 28153),
(154804, 'itIT', 'Ho sentito storie sul potere dei servitori di N\'zoth, ma non credevo che ne avrei mai visto uno. Spero che non capiti più.', '', 28153),
(154803, 'itIT', 'Uuuh, c\'è mancato poco! Se non l\'avessimo fermato, chissà quanti sarebbero rimasti infettati sulla superficie.', '', 28153),
(154802, 'itIT', 'Mi sembra un buon piano. Già che ci siamo, cercherò di scoprire quali altri segreti i Titani si sono lasciati alle spalle.', '', 28153),
(154801, 'itIT', '...', '', 28153),
(154800, 'itIT', 'Argh! Non so se abbiamo tutto questo tempo. Sarà meglio sbarazzarsi di G\'huun, prima che il marciume peggiori.', '', 28153),
(154799, 'itIT', 'Hai trovato la risposta?', '', 28153),
(154798, 'itIT', 'Questo spiega perché i Troll del Sangue sono qui, ma... perché i Titani dovrebbero tenere in vita un Dio Antico?', '', 28153),
(154797, 'itIT', 'Che bello vedervi! Da quello che ho capito, questo è una specie di laboratorio di ricerca.', '', 28153),
(154796, 'itIT', 'Ecco! Ci siamo! Questa tecnologia non è poi così strana, se sai come muoverti.', '', 28153),
(154795, 'itIT', 'Per la dodicesima volta!', '', 28153),
(154794, 'itIT', 'Cosa?!? No, le porte blindate sono sigillate! Spaccate ogni cosa finché non si aprono!', '', 28153),
(154793, 'itIT', 'Datemi un attimo e aprirò le porte.', '', 28153),
(154792, 'itIT', 'Ah ahhh! Ce l\'avete fatta! Datemi solo un secondo. Sono riuscito ad accedere a una sorta di custode che credo stia controllando la struttura.', '', 28153),
(154791, 'itIT', 'Sono arrivato a Leggenda.', '', 28153),
(154789, 'itIT', 'La battaglia infuria, continua la lotta contro i nostri nemici!', '', 28153),
(154788, 'itIT', 'Un nemico d\'alto rango è stato avvistato nelle vicinanze. Abbiamo bisogno del tuo aiuto per abbatterlo.', '', 28153),
(154787, 'itIT', 'Un potente nemico è nelle vicinanze. Eliminalo, senza alcuna pietà!', '', 28153),
(154780, 'itIT', 'Pronto per la Battaglia.', 'Pronta per la Battaglia.', 28153),
(154779, 'itIT', '', 'Torcanata! Ah! Ah!', 28153),
(154777, 'itIT', '', 'Oggi inizia la Torcanata! Se vuoi partecipare, piglia na torcia e preparati a correre.', 28153),
(154774, 'itIT', '', 'Campione, sembri sulla strada giusta per ottenere la fiducia degli Zandalari. Ora ho altro di cui occuparmi. Buona fortuna.', 28153),
(154772, 'itIT', '', 'Oculeth, vedi cosa riesci a fare con questo sistema di portali. Avremo bisogno di rifornimenti per le capitali dell\'Orda.', 28153),
(154770, 'itIT', 'Troviamoci alla Caduta di Bwoljin il prima possibile. Ci infiltreremo nella fortezza di Korthek insieme.', '', 28153),
(154769, 'itIT', '', 'La Principessa Talanji è stata così gentile da informarci di un\'antica rete di portali a cui potremmo attingere.', 28153),
(154768, 'itIT', '', 'Parlate con me quando siete pronti ad affrontare la flotta dei Bracescura.', 28153),
(154767, 'itIT', '', 'Avete agito bene, eroi, ma Boralus non è ancora al sicuro.', 28153),
(154766, 'itIT', 'Torna al tuo lavoro. Loro sono con me.', 'Torna al tuo lavoro. Loro sono con me.', 28153),
(154765, 'itIT', 'Gli stranieri non possono entrare negli archivi, Fratello.', 'Gli stranieri non possono entrare negli archivi, Fratello.', 28153),
(154764, 'itIT', 'Ero lì, sulla spiaggia, circondato da infami Branclin... quando $gun eroe:un\'eroina; venne a salvarmi! Oh! Salve di nuovo, $n!', '', 28153),
(154763, 'itIT', 'Recupera quelle pergamene! Io prenderò la... via panoramica verso l\'accampamento e riferirò quello che hai appreso.', '', 28153),
(154762, 'itIT', 'Può mandarci contro tutte le truppe che vuole, ma l\'Alleanza non conoscerà altro che la sconfitta.', '', 28153),
(154761, 'itIT', 'Alcuni campioni dell\'Alleanza sono arrivati e stanno cercando di salvare la città. Poni fine ai loro sforzi.', '', 28153),
(154760, 'itIT', 'Scateneremo il caos sull\'Alleanza con queste munizioni.', '', 28153),
(154759, 'itIT', 'Le forze dei Bracescura usano armi d\'Azerite per attaccare la città. Requisiscile per l\'Orda!', '', 28153),
(154758, 'itIT', 'Senza i loro ufficiali, i Kul Tirani saranno rispediti nel mare.', '', 28153),
(154757, 'itIT', 'Un ufficiale di Kul Tiras sta cercando di organizzare una difesa. Spazzali via dal campo di battaglia.', '', 28153),
(154756, 'itIT', '', 'Bel lavoro. Hai dimostrato all\'Orda che nessun nemico conquisterà mai Boralus!', 28153),
(154755, 'itIT', '', 'Pare che l\'Orda stia sfruttando l\'assedio per saccheggiare la città! Fermali, prima che depredino tutta Boralus!', 28153),
(154754, 'itIT', '', 'Ben fatto. Hai insegnato ai Bracescura che i mercenari non saranno mai alla tua altezza.', 28153),
(154753, 'itIT', '', 'Uno dei mercenari di Bracescura sta scatenando il caos in città. Fermalo!', 28153),
(154752, 'itIT', '', 'Ben fatto. Gli unici che meritano di rimanere in catene sono quei furfanti!', 28153),
(154751, 'itIT', '', 'I pirati stanno facendo schiavi gli abitanti! Falli smettere!', 28153),
(154750, 'itIT', 'Gorak Tul... sta arrivando...', '', 28153),
(154749, 'itIT', 'Tutta Kul Tiras soffrirà; tu prima di tutti gli altri!', '', 28153),
(154748, 'itIT', 'Folle! Morirai urlando!', '', 28153),
(154747, 'itIT', 'Oou ph\'magg an\'qov nuq.', '', 28153),
(154746, 'itIT', 'Ywaq ongg uul\'gwa no AN\'zig!', '', 28153),
(154745, 'itIT', 'Arwi ryiu yrr oou qam!', '', 28153),
(154744, 'itIT', 'AN\'zig wgah qam za zyqtahg...', '', 28153),
(154743, 'itIT', 'AN\'zig wgah zzof!', '', 28153),
(154742, 'itIT', 'Ywaq fhssh wgah qam!', '', 28153),
(154741, 'itIT', 'Uulg\'ma zyqtahg yrr!', '', 28153),
(154740, 'itIT', 'Hnakf ywaq shuul\'wah yawifk yrr uull zz thyzz!', '', 28153),
(154739, 'itIT', 'Ora andatevene, fintanto che potete! Gli altri cominciano a sospettare qualcosa.', 'Ora andatevene, fintanto che potete! Gli altri se ne sono sicuramente già occupati.', 28153),
(154738, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:260838|h[Urto Trivella]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_SIEGE_ENGINEER_SOCKWAVE_MISSILE.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:260838|h[Urto Trivella]|h|r!', 28153),
(154737, 'itIT', 'Og qam shfk wgah iiqaah halahs ma!', '', 28153),
(154736, 'itIT', 'Trovate Fratello Pike a Brennadam e dategli questo pendaglio. La nostra opera è appena iniziata e gli servirà il vostro aiuto.', 'Trovate Fratello Pike a Brennadam e dategli questo pendaglio. Il nostro lavoro è appena iniziato e ci serve il vostro aiuto.', 28153),
(154735, 'itIT', 'Maq oou kaaxth zz ak\'uq yrr sk\'yahf ma!', '', 28153),
(154734, 'itIT', 'La nostra gente sta seguendo un sentiero oscuro. Alcuni tra noi, però, hanno formato una resistenza.', 'La nostra gente sta seguendo un sentiero oscuro. Alcuni tra noi, però, hanno formato una resistenza.', 28153),
(154733, 'itIT', 'Zuq ag\'xig ka\'kar za wgah!', '', 28153),
(154732, 'itIT', 'Puul qi\'plahf ni oou bormax!', '', 28153),
(154731, 'itIT', 'Xith wgah!', '', 28153),
(154729, 'itIT', 'Naz raqul!', '', 28153),
(154728, 'itIT', 'I wgah far\'al zuq ni shn!', '', 28153),
(154727, 'itIT', 'La flotta non è andata perduta. È prigioniera in una tempesta innaturale.', 'La flotta non è andata perduta. È prigioniera in una tempesta innaturale.', 28153),
(154726, 'itIT', 'Zuq wgah qam n\'lyeth!', '', 28153),
(154725, 'itIT', 'Zuq ag\'xig gag wgah naggwa\'fssh!', '', 28153),
(154724, 'itIT', 'Zuq ag\'xig bormax oou iiqaath!', '', 28153),
(154723, 'itIT', 'Dovevo immaginare che anche Wade sarebbe stato soggiogato dall\'ombra che ha avvolto la Casata dei Sacraonda.', 'State tutti bene? Dovevo immaginare che anche Wade sarebbe stata soggiogata dall\'ombra che ha avvolto la Casata dei Sacraonda.', 28153),
(154722, 'itIT', '', 'Cosa intendi dire con \"pericolo\"?', 28153),
(154721, 'itIT', 'Sì, fratello.', 'Sì, fratello.', 28153),
(154720, 'itIT', 'Mandate via tutti i visitatori, ho degli ospiti.', 'Mandate via tutti i visitatori, ho degli ospiti.', 28153),
(154719, 'itIT', 'Voi non avete idea di quanto siate in pericolo qui.', '', 28153),
(154718, 'itIT', 'Seguitemi. Tenete lo sguardo basso.', '', 28153),
(154717, 'itIT', 'Le nostre fortificazioni sono ancora piuttosto deboli. Presto, fermate l\'avanzata dell\'Orda prima che si avvicini!', '', 28153),
(154716, 'itIT', 'Stromgarde è ancora debole, non reggerà a un attacco diretto. Annientate l\'avanguardia dell\'Orda prima che si avvicini!', '', 28153),
(154715, 'itIT', 'Ah! Na degna dimostrazione di rispetto... per Pa\'ku!', '', 28153),
(154714, 'itIT', 'Mandate le forze nostre! Dobbiamo annientare chegli insetti dell\'Alleanza prima che si disperdano!', '', 28153),
(154713, 'itIT', '', 'È giunto il momento! Sali i gradini di Zanchul e porgi omaggio ai Loa nostri. Con il favore loro, Zandalar resisterà! Fa\' che Gonk sia fiero di te!', 28153),
(154712, 'itIT', '', 'Schierate le nostre forze, ora! Non permetteremo che l\'Alleanza si assicuri un avamposto!', 28153),
(154711, 'itIT', 'Preparate le armi! È tempo di combattere!', '', 28153),
(154710, 'itIT', 'Mandate le nostre forze! Le mura di Stromgarde si sgretoleranno dinnanzi alla potenza dell\'Orda!', '', 28153),
(154709, 'itIT', 'La Roccaforte tiene bisogno di rifornimenti. Fate in modo che le forze loro nun si avvicinino!', '', 28153),
(154708, 'itIT', 'Non perdete tempo. Ser Sacraonda necessita di queste mappe al Santuario della Tempesta immediatamente!', '', 28153),
(154707, 'itIT', 'Mandate le truppe! Della loro base non rimarranno che rovine.', '', 28153),
(154706, 'itIT', '', 'I Saggi delle Maree possiedono alcune delle biblioteche più complete del mondo. Scommetto che troveremo il nostro archivista lì.', 28153),
(154705, 'itIT', '', 'L\'Alleanza sta marciando su Ar\'gorok! Dobbiamo fermarli prima che raggiungano la Roccaforte!', 28153),
(154704, 'itIT', 'Soldati dell\'Alleanza! Abbatteteli!', '', 28153),
(154703, 'itIT', 'Soldati, carica!', '', 28153),
(154702, 'itIT', 'Orda, alla battaglia! Schiacciate quei codardi prima che distruggano i nostri cancelli!', '', 28153),
(154701, 'itIT', '', 'Palla curva! Palla curva!', 28153),
(154700, 'itIT', 'Oh! Palla curva! Palla curva!', '', 28153),
(154699, 'itIT', '', 'Non mi piace. Cambiamo aria.', 28153),
(154698, 'itIT', 'Tornatene negli archivi con quello stolto di Alen, o ti userò per stabilizzare il timone.', '', 28153),
(154697, 'itIT', 'Raddoppiate gli sforzi, stolti, prima che perdiamo il controllo!', '', 28153),
(154696, 'itIT', '', 'D\'accordo, è quello che faremo!', 28153),
(154695, 'itIT', '', 'Perché non andate a infastidire Alen se siete qui per perdere tempo?', 28153),
(154694, 'itIT', '', 'Aprite la vostra anima alle maree. I loro sussurri nascondono la verità!', 28153),
(154693, 'itIT', 'Semina', 'Semina', 28153),
(154692, 'itIT', '', 'Gilneani, caricate i cannoni! Avanzare!', 28153),
(154691, 'itIT', 'Ehm... signore e signori, accendete i motori! All\'attaaacco!!!', '', 28153),
(154690, 'itIT', 'Tiratori! Colpo in canna! Avanzare!', 'Tiratori! Colpo in canna! Avanzare!', 28153),
(154689, 'itIT', '', 'Possiamo assicurare un passaggio sicuro al tuo vascello, dietro compenso.', 28153),
(154688, 'itIT', '', 'Che tragedia. Forse dovremmo smetterla di celebrare qui i matrimoni.', 28153),
(154687, 'itIT', '', 'Quella che doveva essere una festa gioiosa è stata rovinata! Uccidi i mostri responsabili di questo e metti in salvo gli invitati!', 28153),
(154686, 'itIT', '', 'Quindi... lo prendiamo per un no?', 28153),
(154685, 'itIT', '', 'Sei insopportabile quasi quanto Fratello Alen.', 28153),
(154684, 'itIT', '', 'Ehi tu, chi comanda qui?', 28153),
(154683, 'itIT', 'Mmm.', 'Mmm.', 28153),
(154682, 'itIT', 'Prosciugate le vostre ferite infette e cantate in agonia!', '', 28153),
(154681, 'itIT', 'Non voltate le spalle alla follia, divoratela!', '', 28153),
(154680, 'itIT', 'Ammirate il fascino del disfacimento e accoglietelo!', '', 28153),
(154679, 'itIT', 'Ti ridurrò in cenere!', '', 28153),
(154678, 'itIT', 'Xalzaix ha fame di annientamento!', '', 28153),
(154677, 'itIT', 'Non sopravviverai!', '', 28153),
(154676, 'itIT', 'Non potete sfuggire alla distruzione!', '', 28153),
(154675, 'itIT', 'Non potete sfuggire alle ombre!', '', 28153),
(154674, 'itIT', 'Sterminio!', '', 28153),
(154673, 'itIT', 'Annientamento!', '', 28153),
(154672, 'itIT', 'Non puoi resistere al mio richiamo.', '', 28153),
(154671, 'itIT', 'Concediti alla piaga!', '', 28153),
(154670, 'itIT', 'G\'huun non verrà fermato...', '', 28153),
(154669, 'itIT', 'Il marciume consumerà tutto!', '', 28153),
(154668, 'itIT', 'Il tuo corpo appartiene a G\'huun.', '', 28153),
(154667, 'itIT', 'Più cibo per il marciume!', '', 28153),
(154666, 'itIT', 'G\'huun risorgerà!', '', 28153),
(154665, 'itIT', 'Il vostro mondo finirà!', '', 28153),
(154664, 'itIT', 'La tua decomposizione è inevitabile.', '', 28153),
(154663, 'itIT', 'Quel solletico in gola. Quel prurito nella mente. Sono sempre stato con te.', '', 28153),
(154662, 'itIT', 'Ogni forma di vita avvizzisce. Accettatelo e lasciatevi trasformare.', '', 28153),
(154661, 'itIT', '', 'Disco di Rioriginazione ripristinato. Accesso alla volta confermato.', 28153),
(154660, 'itIT', '', 'Console attivata. Riavvio delle difese della struttura.', 28153),
(154659, 'itIT', 'Oh, ancora una cosa. Be\', due.', '', 28153),
(154658, 'itIT', '', 'Prima console attivata. Riattivazione matrice energetica.', 28153),
(154657, 'itIT', '', 'Esemplare G\'huun eliminato. Nessun campione rimasto.', 28153),
(154656, 'itIT', '', 'Corruzione in diminuzione entro livelli accettabili. Integrità dei sistemi ripristinata.', 28153),
(154655, 'itIT', 'Alla fine, quando il pianeta scoppierà come un enorme bubbone, il marciume si diffonderà nel cosmo.', '', 28153),
(154654, 'itIT', 'Sarete portatori della mia pestilenza e un esercito di pustolose cisti putride ricoprirà il mondo.', '', 28153),
(154653, 'itIT', 'Che ospiti impazienti. Voi sarete i primi a ricevere il mio dono.', '', 28153),
(154652, 'itIT', 'I sigilli, infranti. I Titani, spariti. L\'era della decomposizione ha inizio.', '', 28153),
(154651, 'itIT', '', 'Chesto è per Dazar\'alor, infame creatura!', 28153),
(154650, 'itIT', '', 'Ora tocca a noi. Debelleremo l\'infezione di G\'huun.', 28153),
(154649, 'itIT', '', 'Attenzione. Grave pericolo di contaminazione oltre questo punto. I protocolli di quarantena mi impediscono di procedere.', 28153),
(154648, 'itIT', 'Perfetto! Abbiamo abbastanza mine per infliggere un duro colpo alla S.P.R. & Co.', '', 28153),
(154647, 'itIT', '', 'Nun importa come ha fatto a tornare. La lama mia lo rispedirà nell\'abisso.', 28153),
(154646, 'itIT', 'Ci sono molte mine tra cui scegliere.', '', 28153),
(154645, 'itIT', '', 'Le analisi indicano alti livelli di corruzione. Ipotesi: G\'huun ha rianimato l\'esemplare potenziandolo. Ulteriori analisi richieste.', 28153),
(154644, 'itIT', '', 'Zul?!? Come fa a essere vivo? L\'ho visto schiattare per mano del padre mio!', 28153),
(154643, 'itIT', 'Queste mine non erano fatte per rilevare tartarughe! Possiamo recuperarle in sicurezza.', '', 28153),
(154642, 'itIT', '', 'A quanto pare ve ne siete dimenticati uno.', 28153),
(154641, 'itIT', '', 'Gli esperimenti si concentrarono sulla capacità della corruzione di G\'huun di rianimare tessuti morti. I risultati furono inconcludenti e i campioni vennero distrutti.', 28153),
(154640, 'itIT', '', 'Osservazione accurata. Questa struttura ha condotto numerosi esperimenti sui Loa in cerca di soluzioni contro la corruzione degli Dei Antichi.', 28153),
(154639, 'itIT', '', 'Cos\'è chesta creatura?!? Sembra che na volta fosse nu Loa.', 28153),
(154638, 'itIT', '', 'Se chello era uno dei servitori di G\'huun, dobbiamo fermarlo prima che n\'intera armata di chelli raggiunga la superficie.', 28153),
(154637, 'itIT', '', 'Errore. Malfunzionamento del disco. Flusso dati corrotto rilasciato.', 28153),
(154636, 'itIT', '', 'Sequenza d\'accensione avviata.', 28153),
(154635, 'itIT', '', 'Prego, fare rapporto in infermeria per estrazione neurale e recupero di tessuti cerebrali.', 28153),
(154634, 'itIT', '', 'L\'analisi delle vostre cortecce cerebrali indica che tutti gli individui presenti hanno interagito in passato con esemplari di Dei Antichi.', 28153),
(154633, 'itIT', '', 'Ogni dato disponibile delle vostre passate esperienze può contribuire alla ricerca.', 28153),
(154632, 'itIT', '', 'L\'analisi delle vostre cortecce cerebrali indica che alcuni individui presenti hanno interagito in passato con esemplari degli Dei Antichi.', 28153),
(154631, 'itIT', '', 'E novecentocinquanta miliardi di norgabyte di brani musicali e selfie.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154630, 'itIT', '', 'Settantacinque norgabyte di tutti i composti chimici noti.', 28153),
(154629, 'itIT', '', 'Questi dischi contengono cinquanta norgabyte di dati biologici sulle forme di vita conosciute dell\'universo.', 28153),
(154628, 'itIT', '', 'Accesso all\'archivio dati. Contengono gran parte della conoscenza dei Titani.', 28153),
(154627, 'itIT', 'Ti stai opponendo all\'inevitabile. La mia piaga non può essere fermata. Si sta già diffondendo dentro di te.', '', 28153),
(154626, 'itIT', '', 'Se nun avessimo fermato chella cosa, avrebbe infettato tutta la vita sulla superficie.', 28153),
(154625, 'itIT', 'Ah, ti do il benvenuto. I visitatori sono cosa rara di questi tempi, soprattutto qui negli archivi.\n\nCome posso aiutarti?', 'Ah, ti do il benvenuto. I visitatori sono cosa rara di questi tempi, soprattutto qui negli archivi.\n\nCome posso aiutarti?', 28153),
(154624, 'itIT', '', 'Allarme. Contenimento virale compromesso. Campione contaminato in avvicinamento. Rischio di infezione imminente.', 28153),
(154623, 'itIT', '', 'Questo laboratorio contiene migliaia di ceppi virali tra i più pericolosi dell\'universo conosciuto, ordinati alfabeticamente per semplicità di utilizzo.', 28153),
(154622, 'itIT', '', 'Accesso all\'ala di ecologia virale.', 28153),
(154621, 'itIT', '', 'Fai in modo di tenere Parola del Potere: Scudo attiva costantemente per beneficiare di Espiazione.', 28153),
(154620, 'itIT', 'Fai in modo di tenere Parola del Potere: Scudo attiva costantemente per beneficiare di Espiazione.', '', 28153),
(154619, 'itIT', '', 'Lancia Parola del Potere: Scudo su di te e attacca il Manichino d\'Allenamento per curarti.', 28153),
(154618, 'itIT', 'Lancia Parola del Potere: Scudo su di te e attacca il Manichino d\'Allenamento per curarti.', '', 28153),
(154617, 'itIT', '', 'Quando infliggi danni a un nemico, tutti coloro affetti da Espiazione riceveranno una cura.', 28153),
(154616, 'itIT', 'Quando infliggi danni a un nemico, tutti coloro affetti da Espiazione riceveranno una cura.', '', 28153),
(154615, 'itIT', '', 'Alcuni incantesimi, come Parola del Potere: Scudo, applicano l\'effetto Espiazione sul bersaglio.', 28153),
(154614, 'itIT', 'Puoi dirmi qualcosa riguardo la flotta scomparsa?', 'Puoi dirmi qualcosa riguardo la flotta scomparsa?', 28153),
(154613, 'itIT', 'Alcuni incantesimi, come Parola del Potere: Scudo, applicano l\'effetto Espiazione sul bersaglio.', '', 28153),
(154612, 'itIT', 'Dovremo convincere la Capoguerra. E avrò bisogno di te per questo. Vieni.', '', 28153),
(154611, 'itIT', 'Forse è ora di riscuotere un vecchio debito. In questo modo porteremo altri soldati leali nell\'Orda.', '', 28153),
(154610, 'itIT', 'So che hai a cuore l\'Orda quanto me... ma temo che se non agiamo, non sopravviveremo a questa guerra.', '', 28153),
(154609, 'itIT', '', 'Teniamo nu piano. Attivare le console ed epurare la piaga di G\'huun na volta per tutte.', 28153),
(154608, 'itIT', '', 'Attivando tutte le console, sarà possibile accedere alla volta di G\'huun, dove l\'esemplare potrà essere disintegrato attivando il Disco di Rioriginazione.', 28153),
(154607, 'itIT', '', 'Per distruggere l\'esemplare, è necessario riattivare le console situate in quest\'ala.', 28153),
(154606, 'itIT', '', 'Nun teniamo tutto chesto tempo! G\'huun dev\'essere fermato subito!', 28153),
(154605, 'itIT', '', 'Negativo. Dati inconcludenti. Esperimenti alternativi sono in sviluppo e programmati per l\'attivazione in duemilatrecentosessantaquattro cicli.', 28153),
(154604, 'itIT', 'Argh! Quella roba è una bomba!', '', 28153),
(154603, 'itIT', '', 'E l\'avete trovata chesta risposta?', 28153),
(154602, 'itIT', 'Ora basta solo una scintilla. Ti conviene stare indietro.', '', 28153),
(154601, 'itIT', 'Forse possiamo far saltare la serratura. Mettici un po\' di polvere da sparo.', '', 28153),
(154600, 'itIT', '', 'Il recupero di dati è imperativo per la ricerca contro gli Dei Antichi. La genetica unica di G\'huun potrebbe nascondere la risposta a questa minaccia.', 28153),
(154599, 'itIT', '', 'Avete tenuto in vita chell\'abominio?!? Perché?', 28153),
(154598, 'itIT', '', 'Denominazione: Uldir. Questa struttura è stata progettata per contenere e studiare l\'entità conosciuta come G\'huun.', 28153),
(154597, 'itIT', '', 'Cos\'è chisto posto?', 28153),
(154596, 'itIT', '', 'Sistemi del laboratorio compromessi. Procedere con cautela.', 28153),
(154595, 'itIT', '', 'Le porte sono bloccate! Spegnete chella macchina... prima che ci riduca in cenere!', 28153),
(154594, 'itIT', '', 'Allarme. Forme di vita contaminate rilevate. Inceneritori attivati.', 28153),
(154593, 'itIT', '', 'Dev\'essere il motivo per cui la corruzione nun ha ancora avvolto l\'intera struttura.', 28153),
(154592, 'itIT', '', 'Sono la Matrona delle Analisi, Determinata Ricercatrice Eterna. Nome in codice: M.A.D.R.E.', 28153),
(154591, 'itIT', '', 'Per l\'Orda!', 28153),
(154590, 'itIT', '', 'Cos\'era chella voce?', 28153),
(154589, 'itIT', '', 'Per l\'Orda!', 28153),
(154588, 'itIT', 'Lok\'tar ogar! Per l\'Orda!', '', 28153),
(154587, 'itIT', '', 'Campione virulento rimosso. Apertura camera di contenimento.', 28153),
(154586, 'itIT', '', 'Accetto la tua lealtà, Suprema. La tua gente è benvenuta tra le mura di Orgrimmar.', 28153),
(154585, 'itIT', '', 'Draenor è caduta, ma troveremo una nuova casa su Azeroth. I vostri nemici ora sono i nostri nemici!', 28153),
(154584, 'itIT', 'Spolverata di Polvere da Sparo', 'Spolverata di Polvere da Sparo', 28153),
(154583, 'itIT', '', 'Eitrigg e il tuo campione hanno dimostrato coraggio e nobiltà d\'animo. Se sono l\'incarnazione del cuore dell\'Orda, allora combatteremo al vostro fianco.', 28153),
(154582, 'itIT', '', 'Taloc è sopravvissuto all\'attacco del M.IM.MO?!? Nun possiamo lasciare che chel mostro si metta tra noi e G\'huun!', 28153),
(154581, 'itIT', 'Bwonsamdi...', 'Così lontani da casa...', 28153),
(154580, 'itIT', 'So che sei arrabbiata, amore mio, ma ci sono dei veri mostri. Dobbiamo andarcene.', 'So che sei arrabbiato, amore mio, ma ci sono dei veri mostri. Dobbiamo andarcene.', 28153),
(154578, 'itIT', '', 'L\'onore è tutto per noi! Non stiamo prestando questo giuramento alla leggera, Capoguerra.', 28153),
(154577, 'itIT', 'Possiamo farci fare un\'altra torta, ma dobbiamo andare.', 'Possiamo farci fare un\'altra torta, ma dobbiamo andare.', 28153),
(154576, 'itIT', 'So che sei arrabbiata, ma ora dobbiamo davvero andare.', 'So che sei arrabbiato, ma ora dobbiamo davvero andare.', 28153),
(154575, 'itIT', 'Amore, dobbiamo andare.', 'Amore, dobbiamo andare.', 28153),
(154574, 'itIT', '', 'Eitrigg mi ha raccontato della forza della vostra gente. Immagino che anche tu, come lui, dia grande valore all\'onore.', 28153),
(154572, 'itIT', 'Hai rovinato il mio vestito! Era perfetto! Era di seta importata direttamente da Quel\'Thalas e il velo era di mia madre! Come hai potuto!', 'Hai rovinato il mio vestito! Era perfetto! Era di seta importata direttamente da Quel\'Thalas e il velo era di mia madre! Come hai potuto!', 28153),
(154570, 'itIT', 'La nostra missione ha avuto successo, Capoguerra. La Suprema Geya\'rah ha fornito i suoi soldati all\'Orda.', '', 28153),
(154569, 'itIT', 'Hai ucciso il Mastro Chef! Non aveva ancora nemmeno servito gli antipasti!', 'Hai ucciso il Mastro Chef! Non aveva ancora nemmeno servito gli antipasti!', 28153),
(154568, 'itIT', 'Perso tra le sabbie...', 'Finalmente, na morte dignitosa!', 28153),
(154567, 'itIT', 'Te la farò pagare per aver rovinato il mio matrimonio, $gbrutto... brutto:brutta... brutta;... qualsiasi cosa tu sia!', 'Te la farò pagare per aver rovinato il mio matrimonio, $gbrutto... brutto:brutta... brutta;... qualsiasi cosa tu sia!', 28153),
(154566, 'itIT', 'Sai quanto mi ci è voluto per renderla così perfetta?', 'Sai quanto mi ci è voluto per renderla così perfetta?', 28153),
(154565, 'itIT', 'Come osi rovinare la mia giornata?!?', 'Come osi rovinare la mia giornata?!?', 28153),
(154564, 'itIT', 'Finalmente... è finita...', 'Nun può finire... Nun così.', 28153),
(154563, 'itIT', 'Non mangio pane da quattro mesi!', 'Non mangio pane da quattro mesi!', 28153),
(154562, 'itIT', 'Le sabbie... ci reclameranno... a tutti.', 'La morte è l\'unica via di fuga.', 28153),
(154561, 'itIT', 'Avete un\'idea di quanto costi quella torta?', 'Avete un\'idea di quanto costi quella torta?', 28153),
(154560, 'itIT', 'Ero in lista d\'attesa da due anni per questo posto!', 'Ero in lista d\'attesa da due anni per questo posto! Due anni!', 28153),
(154559, 'itIT', 'La morte non mi ha mai fermato prima...', '', 28153),
(154558, 'itIT', 'Potrei ucciderti con un solo dito!', '', 28153),
(154557, 'itIT', '', 'Una nuova Matrice d\'Alimentazione può essere recuperata.', 28153),
(154556, 'itIT', '', 'Una Matrice d\'Alimentazione è pronta per l\'acquisizione.', 28153),
(154555, 'itIT', '', 'Attenzione. Nuova Matrice d\'Alimentazione disponibile.', 28153),
(154554, 'itIT', '', 'Attenzione. Esplosione rioriginante imminente. Prego, abbandonare l\'area.', 28153),
(154553, 'itIT', '', 'Allarme. Sequenza esplosione rioriginante attivata. Abbandonare l\'area.', 28153),
(154551, 'itIT', 'L\'Orda è stata sconfitta!', '', 28153),
(154550, 'itIT', 'Presto capirai la follia della tua resistenza!', 'Presto capirai la follia della tua resistenza!', 28153),
(154549, 'itIT', 'Vieni fuori, sottomettiti al tuo destino!', 'Vieni fuori, sottomettiti al tuo destino!', 28153),
(154548, 'itIT', 'Colui che si cela nelle profondità userà la tua pelle come mantello!', 'Colui che si cela nelle profondità userà la tua pelle come mantello!', 28153),
(154547, 'itIT', 'Lotta per la tua patetica esistenza! Alla fine la marea eterna ti reclamerà!', 'Lotta per la tua patetica esistenza! Alla fine la marea eterna ti reclamerà!', 28153),
(154546, 'itIT', '', 'Usa Contrizione per guarire le tue ferite.', 28153),
(154545, 'itIT', 'Che tipo di polvere da sparo è? Ehi, aiutami a prendere un po\' di questa roba.', '', 28153),
(154544, 'itIT', 'Usa Contrizione per guarire le tue ferite.', '', 28153),
(154543, 'itIT', '', 'Lanciare Contrizione su di te o su un alleato guarirà i danni subiti, invece di infliggerne.', 28153),
(154542, 'itIT', 'Lanciare Contrizione su di te o su un alleato guarirà i danni subiti, invece di infliggerne.', '', 28153),
(154541, 'itIT', 'Uccidi quei mostri!', 'Uccidi quei mostri!', 28153),
(154540, 'itIT', 'Questo dovrebbe essere un evento gioioso!', 'Questo dovrebbe essere un evento gioioso!', 28153),
(154539, 'itIT', 'Cosa succede? Cosa sta succedendo? Cosa sono quei mostri?', 'Cosa succede? Cosa sta succedendo? Cosa sono quei mostri?', 28153),
(154538, 'itIT', 'Questo è molto peggio dei cognati ubriachi!', 'Questo è molto peggio dei cognati ubriachi!', 28153),
(154537, 'itIT', 'Perché sta accadendo tutto questo?', 'Perché sta accadendo tutto questo?', 28153),
(154536, 'itIT', 'Non abbiamo potuto nemmeno fare il ballo dello struzzo!', 'Non abbiamo potuto nemmeno fare il ballo dello struzzo!', 28153),
(154535, 'itIT', 'Questa doveva essere una giornata felice!', 'Questa doveva essere una giornata felice!', 28153),
(154534, 'itIT', 'Ahhhhhhhhh!', 'Ahhhhhhhhh!', 28153),
(154533, 'itIT', 'Con permesso, Capoguerra. Vieni.', '', 28153),
(154532, 'itIT', '', 'I nostri alleati Nobili Oscuri hanno una spiccata affinità con il teletrasporto. Suggerisco di attingere alla loro conoscenza perché ti aiuti nel viaggio.', 28153),
(154531, 'itIT', 'Ho ottenuto un frammento del manufatto che Garrosh usò per viaggiare in quel mondo. Credo che possa aprire il passaggio... Ma avrò bisogno di aiuto per farlo.', '', 28153),
(154530, 'itIT', '', 'Sembra un ottimo piano, ma pensavo che il passaggio verso quell\'altra Draenor fosse chiuso.', 28153),
(154529, 'itIT', 'Andrò a parlare con Owings. Mi piace il mio lavoro e voglio continuare a farlo. A modo mio.', '', 28153),
(154528, 'itIT', 'Vuol dire che... Capisco.', '', 28153),
(154527, 'itIT', 'Mmm... Non credo che il Capitano si schiererebbe mai contro i Bracescura. Sembrava piuttosto convinto.', '', 28153),
(154526, 'itIT', '', 'Tu che ne dici? Credi sia giunto il momento di farci dei nuovi alleati?', 28153),
(154525, 'itIT', '', 'L\'abilità in battaglia degli Orchi Mag\'har è leggendaria. Avrò bisogno di soldati con un coraggio del genere nei giorni a venire.', 28153),
(154524, 'itIT', '', 'Un\'armata di Orchi proveniente da un altro mondo? Soldati addestrati... armi in attesa di essere scatenate sull\'Alleanza. Ah! Interessante...', 28153),
(154523, 'itIT', 'Salvando Draenor da Garrosh e dalla Legione, questo campione ha ottenuto la fiducia degli Orchi del luogo. Devono molto all\'Orda. Io dico che è ora di riscuotere ciò che ci è dovuto.', '', 28153),
(154522, 'itIT', 'Capoguerra. Anni fa l\'Orda ha inseguito Garrosh Malogrido mentre tentava la fuga in un\'eco della Draenor che conoscevo.', '', 28153),
(154521, 'itIT', 'Diremo no ai Bracescura. Ecco gli ordini del Capitano.', 'Diremo no ai Bracescura. Ecco gli ordini del Capitano.', 28153),
(154520, 'itIT', 'Hai degli abiti davvero fantastici, $gamico:amica;. Ti serve qualcosa?', '', 28153),
(154519, 'itIT', 'Bevete, amici miei. Sembrate avere la gola nu po\' secca... Ah!', 'Bevete, amici miei. Sembrate avere la gola nu po\' secca... Ah!', 28153),
(154518, 'itIT', 'Rottura', 'Rottura', 28153),
(154516, 'itIT', 'Non sei $guno studente:una studentessa;. Spero tu abbia una buona ragione per interrompere la mia lezione.', 'Non sei $guno studente:una studentessa;. Spero tu abbia una buona ragione per interrompere la mia lezione.', 28153),
(154515, 'itIT', '<Non sembra che Darrel si sia accorto della tua presenza.>', '<Non sembra che Darrel si sia accorto della tua presenza.>', 28153),
(154514, 'itIT', 'È maleducato interrompere, $gstraniero:straniera;.', 'È maleducato interrompere, $gstraniero:straniera;.', 28153),
(154513, 'itIT', 'Non riesco a vedere nulla qui che possa dirmi dove sono andati a finire i miei amici Gnomi. Fammi esaminare le informazioni che hai raccolto e ti contatterò se dovessi trovare qualcosa di interessante.', '', 28153),
(154512, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso la Valle dei Sacraonda.', '|cFF0000FF(Missione)|r Fai rotta verso la Valle dei Sacraonda.', 28153),
(154511, 'itIT', 'Attenzione! Attenzione! Allarme intrusi! Allarme intrusi!', '', 28153),
(154510, 'itIT', '', 'Accetta questo dono... l\'armatura tradizionale della nostra gente. Indossala con orgoglio, in ricordo della tua terra. Dranosh\'ek Mag\'har!', 28153),
(154509, 'itIT', '', 'Hai portato grande onore ai Mag\'har, difendendo l\'Orda dai suoi nemici.', 28153),
(154508, 'itIT', '', 'Torna a Orgrimmar in modo che io possa riconoscere la tua dedizione verso la nostra gente.', 28153),
(154507, 'itIT', '', 'Hai combattuto innumerevoli battaglie su Azeroth. Hai mostrato sia ai nostri alleati che ai nostri nemici cosa significa essere un Mag\'har!', 28153),
(154506, 'itIT', '', 'Ovunque ti conduca il tuo viaggio, non dimenticare mai che in te batte il cuore di Draenor. Lok\'tar ogar!', 28153),
(154505, 'itIT', '', 'Ogni nostra vittoria mostrerà alla gente di Azeroth che siamo maestri nell\'arte della guerra!', 28153),
(154504, 'itIT', '', 'Ora l\'Orda ha bisogno della nostra forza contro l\'Alleanza. E noi abbiamo risposto alla chiamata.', 28153),
(154503, 'itIT', '', 'La nostra gente rimase unita sotto la guida di Grommash Malogrido. Un\'unica tribù. I Mag\'har.', 28153),
(154502, 'itIT', '', 'Anni fa, gli eroi di questo mondo si avventurarono a Draenor e combatterono al nostro fianco contro la Legione Infuocata.', 28153),
(154501, 'itIT', '', 'Mio caro Rokhan, la Tribù Lanciascura si è più che guadagnata l\'aiuto delli Zandalari. Mi unirò a te e ti aiuterò come posso.', 28153),
(154500, 'itIT', 'Devo chiedere l\'aiuto del campione. Nu vecchio nemico è riuscito a sfuggire a Bwonsamdi e mo\' sta minacciando la dimora mia.', '', 28153),
(154499, 'itIT', 'Sono pronto. Iniziamo il rituale.', 'Sono pronta. Iniziamo il rituale.', 28153),
(154498, 'itIT', '', 'Qualcuno qui deve sapere qualcosa. Non si può perdere di vista un\'intera flotta!', 28153),
(154497, 'itIT', 'Invece... apriremo il nostro porto all\'Orda?', '', 28153),
(154496, 'itIT', 'Non ci consegneremo nelle mani dei Bracescura...', '', 28153),
(154495, 'itIT', 'E io dovrei crederti, $R? Dammi qua.', '', 28153),
(154494, 'itIT', 'Ordini del Capitano, signore. Ha deciso di non schierarsi con i Bracescura!', 'Ordini del Capitano, signore. Ha deciso di non schierarsi con i Bracescura!', 28153),
(154493, 'itIT', 'Da dove sei $gvenuto:venuta;? Di certo non sei di queste parti.', '', 28153),
(154492, 'itIT', '', 'Cosa? Fammi vedere.', 28153),
(154491, 'itIT', 'Ho altri ordini per te dal Capitano.', 'Ho altri ordini per te dal Capitano.', 28153),
(154490, 'itIT', '', 'Non solo per riportare a casa la flotta, ma per unire di nuovo Kul Tiras... e curare l\'\"infezione\" come la chiama Cyrus.', 28153),
(154489, 'itIT', '', 'Chi sei? E cosa vuoi esattamente?', 28153),
(154488, 'itIT', '', 'Inoltre, benedicono ogni singola nave di Kul Tiras. È questo che le differenzia da ogni altro vascello che vedi nel porto.', 28153),
(154487, 'itIT', '', 'Non ho mai visto così tanta Azerite nello stesso posto. Sono allo stesso tempo preoccupata e deliziata.', 28153),
(154486, 'itIT', '', 'Un elementale... di pura Azerite. Uccidilo, ma non distruggerlo. Ottieni quanta più della sua resina puoi portare!', 28153),
(154485, 'itIT', '', 'Questo dovrebbe saziare i loro appetiti... almeno per un po\'.', 28153),
(154484, 'itIT', '', 'Gli Orchi sono ottimi soldati, ma ognuno di loro mangia come una dozzina di Goblin! Le nostre riserve di cibo scarseggiano, ti andrebbe di cacciare qualche bestia mentre ti occupi dei Kaldorei?', 28153),
(154483, 'itIT', '', 'Come dico sempre, \"taglia la rosa prima che crescano le spine\".', 28153),
(154482, 'itIT', '', 'Un altro comandante Kaldorei nel luogo sbagliato al momento sbagliato. Sbarazzatene immediatamente. Non possiamo permetterle di radunare rinforzi.', 28153),
(154481, 'itIT', '', 'Hai dimostrato di essere la scelta giusta per il compito.', 28153),
(154480, 'itIT', '', 'Faucisaure ha raggiunto la sommità delle montagne tra Rivafosca e Vilbosco. Raggiungilo alla Valle dei Lanciarotta e fa\' in modo che il passaggio che cerca sia sicuro.', 28153),
(154479, 'itIT', 'Ce l\'abbiamo fatta, ciurma! Il Re dei Pirati Zem\'lan è schiattato, per ora, e il tesoro è nostro!', '', 28153),
(154478, 'itIT', '', 'Non ho dubitato di te nemmeno per un istante.', 28153),
(154477, 'itIT', '', 'Pare che i Kaldorei abbiano richiamato rinforzi. Sarà una sfida, ma mi aspetto una vittoria.', 28153),
(154476, 'itIT', '', 'Combatti con grazia e fervore. I tuoi sforzi saranno di grande ispirazione per i miei soldati.', 28153),
(154475, 'itIT', '', 'L\'Alleanza sta perlustrando Rivafosca per sradicare i nostri avamposti. Non dobbiamo perdere terreno! Difendi ciò che è nostro!', 28153),
(154474, 'itIT', '', 'In tempi di guerra, o si è carnefici oppure vittime. Non c\'è molto altro da aggiungere.', 28153),
(154473, 'itIT', '', 'Non fermarti! Quegli Elfi selvaggi non ti daranno tregua.', 28153),
(154472, 'itIT', '', 'Abbiamo inferto un duro colpo alle loro scorte. Ben fatto.', 28153),
(154471, 'itIT', '', 'I Kaldorei sono più pericolosi nell\'oscurità. Gettati nella mischia e occupati di loro prima che cali la notte!', 28153),
(154470, 'itIT', '', 'La mia fiducia in te era ben riposta. La volontà dei Kaldorei presto crollerà.', 28153),
(154469, 'itIT', '', 'La nostra armata ha i soldati di Malfurion alle calcagna! Dobbiamo avanzare nel cuore di Rivafosca mentre abbiamo ancora un vantaggio!', 28153),
(154468, 'itIT', '', 'Poveretta... non ha nemmeno avuto l\'occasione di colpire.', 28153),
(154467, 'itIT', '', 'Quella comandante degli Elfi della Notte sta mettendo a dura prova la mia pazienza. Eliminala.', 28153),
(154466, 'itIT', '', 'Immagina: dormire per migliaia di anni e risvegliarsi sconfitti. Ah, che pena!', 28153),
(154465, 'itIT', '', 'Quindi gli Antichi hanno deciso di uscire a giocare, eh? Facciamo in modo che abbiano un brusco risveglio.', 28153),
(154464, 'itIT', 'Suppongo potesse anche andare peggio. Assicurati che la sua resina non venga raccolta dall\'Orda.', '', 28153),
(154463, 'itIT', '', 'Un elementale di pura Azerite! Non so davvero che genere di minaccia possa essere, ma fa\' attenzione.', 28153),
(154462, 'itIT', 'Gli Elfi della Notte ci affronteranno a ogni passo.', 'Gli Elfi della Notte ci affronteranno a ogni passo.', 28153),
(154461, 'itIT', '', 'Hai mai usato una bomba d\'Azerite prima d\'ora? Vuoi ammirare il suo vero potere? Tieniti forte, sarà una piacevolissima sorpresa.', 28153),
(154460, 'itIT', 'Che esemplare meraviglioso! Mi vengono già in mente un sacco di utilizzi alchemici per questa creatura.', '', 28153),
(154459, 'itIT', 'È sempre difficile per i nuovi cadetti. Non temere, tempra lo spirito!', '', 28153),
(154458, 'itIT', '', 'I Kaldorei ci intralceranno la strada... a meno che non facciamo qualcosa per impedirglielo.\n\nDobbiamo colpirli duramente, in modo che comprendano ciò che è in gioco. Devono perdere qualcosa... qualcuno... in cui ripongono la loro più totale fiducia. Un simbolo di speranza.\n\n<La Dama Oscura stringe gli occhi.>\n\nMalfurion Grantempesta deve morire.', 28153),
(154457, 'itIT', 'I pescatori dicono di aver visto qualcosa di grosso e strano in acqua. Un campione da studiare ci sarebbe molto utile.', '', 28153),
(154456, 'itIT', '', 'L\'Alleanza vuole usare le armi d\'assedio contro di noi? Bizzarro. Fagli vedere di cosa è capace l\'Orda.', 28153),
(154455, 'itIT', 'Con l\'attuale carenza di ferro, non possiamo nemmeno permetterci di sprecare le munizioni d\'addestramento. I nostri soldati hanno ideato un modo geniale per recuperarle.', '', 28153),
(154454, 'itIT', '', 'Queste rovine sono ricche di risorse naturali... È ora di prendercele! Non permettere ai Kaldorei di metterci i bastoni tra le ruote.', 28153),
(154453, 'itIT', '', 'Abbiamo a disposizione dei Cavalieri del Vento. Prendi gli esplosivi e distruggi quel muro di Fuochi Fatui. Manderemo un messaggio a Malfurion.', 28153),
(154452, 'itIT', '', 'Ah! Bel colpo! Non vorrei essere nei panni di chiunque debba recuperare quelle palle di cannone.', 28153),
(154451, 'itIT', 'Una Sciamana della S.P.R. & Co. è al comando di elementali che trasudano Azerite! Dei ladri buoni a nulla come loro non meritano un tale potere. Eliminala!', '', 28153),
(154450, 'itIT', '', 'Pare che stiano facendo pratica di tiro nella zona d\'addestramento. Scommetto che potresti mostrare ai cadetti un paio di trucchetti su come usare un cannone.', 28153),
(154449, 'itIT', '', 'Le armi che hai recuperato ci saranno molto utili. Un gran bel lavoro.', 28153),
(154448, 'itIT', '', 'Sia come sia, abbiamo bisogno dell\'aiuto dei Saggi delle Maree... ora più che mai.', 28153),
(154447, 'itIT', 'Ottimo lavoro! Avrai probabilmente alleggerito un bel po\' di portafogli. Incluso il mio.', '', 28153),
(154446, 'itIT', '', 'Ora nessuno sa perché la flotta non è ancora tornata a casa.', 28153),
(154445, 'itIT', '', 'La gente dice che i Saggi delle Maree hanno perso la loro magia, ma credo solo che si contendano il potere, come Bracescura.', 28153),
(154444, 'itIT', '', 'Quel carico appartiene all\'Orda! Non permettere all\'Alleanza di mettervi mano.', 28153),
(154443, 'itIT', 'Alcuni degli Sferzamaree qui organizzano un torneo di duelli tra pirati, di tanto in tanto, e non sono schizzinosi su chi vi partecipa.', '', 28153),
(154442, 'itIT', '', 'Anche con tutto l\'addestramento, quelle Guardaboschi Oscure hanno calcolato male i loro attacchi. Forse Selvamorta dovrebbe scambiare un paio di parole con loro...', 28153),
(154441, 'itIT', '', 'Le nostre navi più grandi hanno sempre a bordo un Saggio delle Maree, per aiutarle a superare le tempeste e avere sempre vento favorevole.', 28153),
(154440, 'itIT', '', 'Le mie Guardaboschi Oscure richiedono il tuo aiuto. Fai tutto il possibile!', 28153),
(154439, 'itIT', '', 'I tuoi sforzi sono richiesti altrove. Ho una squadra di Goblin pronta a recuperare ciò che è rimasto.', 28153),
(154438, 'itIT', 'Pensano davvero che sfamare un Ogre con la linfa vitale del pianeta servirà a dargli un cervello? Insomma... non funzionerà, vero? Meglio ucciderlo prima di scoprirlo, che ne dici?', '', 28153),
(154437, 'itIT', 'Stupende! Queste attireranno l\'attenzione di tutti!', '', 28153),
(154436, 'itIT', '', 'I Barili di Polvere da Sparo d\'Azerite sono finiti in mare! Recuperali in fretta, prima che affondino!', 28153),
(154435, 'itIT', 'Ho finito le fotografie che mi avevi fatto. Se ti avanza del tempo libero, mi farebbero comodo altre foto.', '', 28153),
(154434, 'itIT', '', 'Il nostro accampamento ora è al sicuro, ma rimani all\'erta.', 28153),
(154433, 'itIT', 'Il capo della ricerca per le armi della S.P.R. & Co. è qui! Abbiamo cercato di prenderlo per anni. Va\' a dargli una lezione da parte mia!', '', 28153),
(154432, 'itIT', '', 'Quanto vorrei mostrarti la flotta. Anche il più veterano tra gli avventurieri ne rimarrebbe impressionato!', 28153),
(154431, 'itIT', 'Ah, Boralus! La città famosa per le sue bande criminali e i suoi fastidiosi nobili. Gnomeregan non ha mai avuto problemi simili.', '', 28153),
(154430, 'itIT', 'Ho deciso di aggiungere un po\' di vedute locali alla pubblicità. La città è il posto ideale per iniziare.', '', 28153),
(154429, 'itIT', '', 'Dei sabotatori dell\'Alleanza si sono infiltrati nel nostro accampamento! Falli sanguinare!', 28153),
(154428, 'itIT', '', 'Comunque, è il momento di sfruttare quel lasciapassare!', 28153),
(154427, 'itIT', 'Il capo della ricerca per le armi ha preso un mucchio di soldi per andare a lavorare con la S.P.R. & Co. Non posso certo biasimarlo per questo. È un vero peccato che dovrai ucciderlo però, vero?', '', 28153),
(154426, 'itIT', 'Fantastico! La cosa migliore di queste foto è che non si riesce a sentire l\'odore dei cavalli.', '', 28153),
(154425, 'itIT', 'Ser Norwington vuole che la sua magnifica villa sia protagonista del prossimo catalogo Frizzafonti. Per quanto mi riguarda, va benissimo.', '', 28153),
(154424, 'itIT', 'La S.P.R. & Co. sta riempiendo i suoi Ogre di Azerite, dicendo che li renderà più intelligenti. Non credo funzionerà ma... credo sia meglio che te ne occupi. Non si sa mai.', '', 28153),
(154423, 'itIT', '', 'L\'Essenza di Pozzo Lunare ti sarà molto utile in battaglia. Assicurati di fare lo stesso con qualsiasi altro pozzo i Kaldorei dovessero consacrare in futuro.', 28153),
(154422, 'itIT', '', 'I Kaldorei usano i Pozzi Lunari per rigenerare le loro forze in battaglia. Attingi a tutto il potere che contengono, poi... rendili inutilizzabili. Tutto chiaro?', 28153),
(154421, 'itIT', 'Ottimo tempismo! Ancora un po\' e la mia reputazione di albergatore sarebbe rimasta danneggiata.', '', 28153),
(154420, 'itIT', 'Fai attenzione là fuori, Taelia. Non mi fido per niente di quei tizi incappucciati.', '', 28153),
(154419, 'itIT', 'Dicono che la S.P.R. & Co. abbia capito come addomesticare elementali composti di pura Azerite. Dobbiamo fermarli. E con dobbiamo, intendo devi.', '', 28153),
(154418, 'itIT', '', 'Ordinerò ai nostri incantatori di infondere la Pietraluna con l\'Azerite. Il loro potere ora è al servizio dell\'Orda!', 28153),
(154417, 'itIT', '', 'I Kaldorei traggono il loro potere da pendagli fatti di Pietraluna. Fai tutto ciò che è in tuo potere per rubarglieli.', 28153),
(154416, 'itIT', '', 'Molto bene. Farò aggiungere l\'Azerite alle nostre scorte.', 28153),
(154415, 'itIT', '', 'Fra le rovine di Rivafosca è emersa dell\'Azerite. L\'Alleanza non deve prenderne nemmeno un frammento!', 28153),
(154414, 'itIT', '', 'Questo è proprio il tipo di messaggio che volevo mandare a Malfurion. Ottimo lavoro.', 28153),
(154413, 'itIT', '', 'Questi Fuochi Fatui sono poco più di semplici insetti. Spegni la loro luce uno dopo l\'altro e presto il cielo sarà avvolto dall\'oscurità.', 28153),
(154412, 'itIT', 'È un disastro! Gli elementali delle terme sono impazziti e stanno attaccando gli ospiti!', '', 28153),
(154411, 'itIT', '', 'Folli! G\'huun nun cadrà! Il potere vostro è inutile!', 28153),
(154410, 'itIT', '', 'I nostri cuochi dovrebbero riuscire a tirarne fuori qualcosa di buono. Grazie.', 28153),
(154409, 'itIT', '', 'I miei compagni Druidi... mangiano come orsi. È un lavoro ingrato, ma qualcuno deve rimpolpare le nostre scorte. Ti va di occupartene?', 28153),
(154408, 'itIT', 'È ora di guadagnarci la paga! Fuoco a volontà!', '', 28153),
(154407, 'itIT', 'Ahah! Bella questa.', 'Ahah! Bella questa.', 28153),
(154406, 'itIT', 'Che maleducazione.', 'Che maleducazione.', 28153),
(154405, 'itIT', 'Perché mai dovresti farlo?', 'Perché mai dovresti farlo?', 28153),
(154404, 'itIT', 'In nome di tutti i Loa, cosa credi di fare?', 'In nome di tutti i Loa, cosa credi di fare?', 28153),
(154403, 'itIT', 'Smettila!', 'Smettila!', 28153),
(154402, 'itIT', 'Fuori dai piedi! Arrivano i pezzi grossi!', '', 28153),
(154401, 'itIT', 'Ecco l\'ottavo pezzo. Insieme fanno na moneta intera, riccumpà!', '', 28153),
(154400, 'itIT', 'I pirati tengono l\'abitudine di dividere le monete loro in otto parti. Sarebbe nu vero colpo di fortuna se trovassi otto pezzi! Di certo intorno al Covo della Libertà i tesori nun mancano.', '', 28153),
(154399, 'itIT', 'Ahahah! Na vera ghiottoneria. Qualcuno vuole n\'assaggino?', '', 28153),
(154398, 'itIT', 'Na medusa gigante ha fatto di Covo della Libertà la dimora sua. Tutti quanti gli arpioni infilzati dentro chella bestia nun sono serviti a niente!', '', 28153),
(154397, 'itIT', 'Avete acciso il Capitano del Terrore Vandegrim e dato riposo all\'anima sua! Pensate a quanti tesori sono liberi dalla maledizione, mo\'!', '', 28153),
(154396, 'itIT', 'Il Capitano Vandegrim ha razziato cheste coste in lungo e in largo. Pare che in vita fosse così avido che continua a razziarle pure da morto.', '', 28153),
(154395, 'itIT', 'Iggksh ywaq ag\'rr ni ky!', '', 28153),
(154394, 'itIT', 'Ah\'shel ywaq qam yrr woth\'gl!', '', 28153),
(154393, 'itIT', 'Ecco l\'ottavo pezzo. Insieme fanno una moneta intera! Siamo ricchi!', '', 28153),
(154392, 'itIT', 'Za ag\'rr wgah thyzz zuq!', '', 28153),
(154391, 'itIT', 'I pirati hanno l\'abitudine di dividere le loro monete in otto parti. Sarebbe un vero colpo di fortuna se trovassi otto pezzi! Di certo intorno al Covo della Libertà i tesori non mancano.', '', 28153),
(154390, 'itIT', 'A proposito di cose spiacevoli. Qualcuno vuole dei calamari?', '', 28153),
(154389, 'itIT', 'Una medusa gigante ha fatto di Covo della Libertà la sua dimora. Tutti gli arpioni infilzati dentro quella bestia non sono serviti a niente!', '', 28153),
(154388, 'itIT', 'Ga ag\'rr ez AN\'zig wgha kyth zuq!', '', 28153),
(154387, 'itIT', 'Avete ucciso il Capitano del Terrore Vandegrim e dato riposo alla sua anima! Pensate a quanti tesori sono stati liberati dalla maledizione!', '', 28153),
(154386, 'itIT', 'Il Capitano Vandegrim ha razziato queste coste in lungo e in largo. Pare che in vita fosse così avido che continua a razziarle anche da morto.', '', 28153),
(154385, 'itIT', 'Chesto... uhhh... nun era il futuro... argh... che mi avevano promesso...', '', 28153),
(154384, 'itIT', 'Il sangue di G\'huun scorre nelle vene mie! Tremate di fronte al vero potere!', '', 28153),
(154383, 'itIT', 'Ho visto cose...', 'Oh! La tua gentilezza è inaspettata.', 28153),
(154382, 'itIT', 'Il potere mio vi spezzerà!', '', 28153),
(154381, 'itIT', 'Grazie. Non sarei durato ancora a lungo.', 'Grazie. Cercherò di guardare avanti.', 28153),
(154380, 'itIT', 'Il potere di G\'huun sarà la rovina vostra!', '', 28153),
(154379, 'itIT', 'Assistete alla vostra fine e disperate!', '', 28153),
(154378, 'itIT', 'Sorgete, prescelti miei! Conquisteremo ogni cosa col sangue!', '', 28153),
(154377, 'itIT', 'Sorgete dal sangue mio per schiacciare i deboli!', '', 28153),
(154376, 'itIT', 'Venite, figli miei! Cibatevi delli infedeli!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154375, 'itIT', 'Ridatemi il vostro sangue!', '', 28153),
(154374, 'itIT', 'G\'huun! Accetta chest\'offerta di sangue!', '', 28153),
(154373, 'itIT', 'Tanto nun tenevi alcun futuro.', '', 28153),
(154372, 'itIT', 'Debole. Proprio come predetto.', '', 28153),
(154371, 'itIT', 'Tutto è come avevo previsto!', '', 28153),
(154370, 'itIT', 'Venite, stolti! Ho già previsto la fine vostra.', '', 28153),
(154369, 'itIT', 'Mia madre schiattò quando ero molto piccolo, lasciando mio padre solo a crescermi. Lui era nu marinaio, e mi lasciava sempre nu stelo marino quando salpava.', 'Mia madre schiattò quando ero molto piccola, lasciando mio padre solo a crescermi. Lui era nu marinaio, e mi lasciava sempre nu stelo marino quando salpava.', 28153),
(154368, 'itIT', '', 'Allarme. Manifestazione proiezione oscura.', 28153),
(154367, 'itIT', '', 'Allarme. Protezioni di contenimento del Vuoto compromesse.', 28153),
(154366, 'itIT', '', 'È stato davvero nobile da parte tua.', 28153),
(154365, 'itIT', '', 'Allarme. Rilevamento di livelli critici di energia del Vuoto.', 28153),
(154363, 'itIT', '', 'Pericolo. Replicazione di Nerubiani aggiuntivi.', 28153),
(154362, 'itIT', 'L\'equilibrio è stato ristabilito. Anu\'dorini talah!', '', 28153),
(154361, 'itIT', 'Egli cammina tra le ombre, ma nessuno può nascondersi dalla luce benedetta di Elune. Eliminalo.', '', 28153),
(154360, 'itIT', '', 'Pericolo. Replicazione di Silitidi aggiuntivi.', 28153),
(154359, 'itIT', 'Bah! Maledetti! Per me li steli marini significano soltanto marinai che nun torneranno e carichi dispersi in fondo al mare.', 'Bah! Maledetti! Per me li steli marini significano soltanto marinai che nun torneranno e carichi dispersi in fondo al mare.', 28153),
(154358, 'itIT', '', 'Non c\'è posto per Mythrax in questo mondo.', 28153),
(154357, 'itIT', '', 'Che Elune ti benedica. Il tuo spirito brilla più luminoso di una stella.', 28153),
(154356, 'itIT', '', 'I miei arcieri hanno bisogno del tuo aiuto. Dai una mano a tutti quelli che trovi!', 28153),
(154355, 'itIT', '', 'Questa guerra deve finire.', 28153),
(154354, 'itIT', '', 'Veglierò su di te.', 28153),
(154353, 'itIT', '', 'Caricamento ultimato. Spegnimento del disco.', 28153),
(154352, 'itIT', '', 'Hai eliminato la minaccia e riportato la Macchina d\'Assedio tutta intera. Avrai un riconoscimento particolare per questo.', 28153),
(154351, 'itIT', '', 'L\'ordine dev\'essere ripristinato.', 28153),
(154350, 'itIT', '', 'Tutti noi abbiamo un ruolo. Il mio è questo.', 28153),
(154349, 'itIT', '', 'Sono debole, ma sono qui.', 28153),
(154348, 'itIT', '', 'Hai mai usato uno di questi prima d\'ora? Tieniti forte, avrai una bella sorpresa.', 28153),
(154347, 'itIT', '', 'Accesso al disco effettuato. Caricamento dati corrotti.', 28153),
(154346, 'itIT', 'Manderò tutti i soldati a disposizione in questo luogo. Speriamo che riescano a sventare l\'attacco. Non possiamo combattere una guerra su due fronti.', '', 28153),
(154345, 'itIT', 'Percepisco un disturbo verso nord. Che l\'Orda abbia cominciato ad attaccarci da oltre le montagne? Va\' a indagare, presto!', '', 28153),
(154344, 'itIT', '', 'Vedo che hai qualche... bruciatura. Le cose non sono andate come previsto?', 28153),
(154343, 'itIT', '', 'Anche sott\'acqua, quei barili di polvere d\'Azerite sono ancora pericolosi. Voglio che tu li faccia esplodere prima che tornino a galleggiare in superficie. Cerca di tornare in un pezzo solo, d\'accordo?', 28153),
(154342, 'itIT', '', 'Sovraccarico della matrice dati. Accesso a dischi multipli.', 28153),
(154341, 'itIT', 'Uno stelo marino, eh? Alcuni della ciurma mia ne lasciano sempre uno in mano alle consorti loro, prima di ogni viaggio. Vogliono soltanto risparmiare alle famiglie loro inutili speranze in caso gli dovesse capitare qualcosa di brutto.', 'Uno stelo marino, eh? Alcuni della ciurma mia ne lasciano sempre uno in mano alle consorti loro, prima di ogni viaggio. Vogliono soltanto risparmiare alle famiglie loro inutili speranze in caso gli dovesse capitare qualcosa di brutto.', 28153),
(154340, 'itIT', '', 'Non ho mai dubitato di te nemmeno per un istante.', 28153),
(154339, 'itIT', '', 'I membri dell\'Orda sono arrivati in gran numero e non dobbiamo sottovalutare nessuno di loro. Questo in particolare sembra... resistente. Fa\' attenzione.', 28153),
(154338, 'itIT', '', 'Accesso al disco effettuato. Caricamento dati di Yogg-Saron.', 28153),
(154337, 'itIT', '', 'Accesso al disco effettuato. Caricamento dati di C\'thun.', 28153),
(154335, 'itIT', '', 'Dei sabotatori dell\'Orda si sono infiltrati tra i nostri ranghi! Falli soffrire come abbiamo sofferto noi!', 28153),
(154334, 'itIT', '', 'Devo ammetterlo... davvero un ottimo colpo. Perfino le Sentinelle avrebbero qualcosa da imparare da te.', 28153),
(154333, 'itIT', '', 'È ora di combattere il fuoco con il fuoco! Dobbiamo privare l\'Orda dei suoi Demolitori e rispedirli nelle Savane da cui sono venuti!', 28153),
(154332, 'itIT', '', 'Elune ti sorride. E anch\'io.', 28153),
(154331, 'itIT', '', 'L\'Orda sta cercando di rubare l\'essenza dai nostri Pozzi Lunari! Non lasciare che quella feccia dissacri le nostre fonti benedette!', 28153),
(154330, 'itIT', '', 'Che quella feccia dell\'Orda rimanga nelle sue terre desolate. Gli insegneremo noi a stare lontani dalle nostre foreste.', 28153),
(154329, 'itIT', '', 'L\'Orda ha stabilito un avamposto oltre i confini di Valtetra. Raduna i Druidi che sorvegliano la foresta!', 28153),
(154328, 'itIT', '', 'Hai combattuto bene. E con un tale fervore...', 28153),
(154327, 'itIT', '', 'I soldati dell\'Orda stanno rubando risorse dalle nostre terre! Fermali, prima che distruggano la nostra sacra foresta.', 28153),
(154326, 'itIT', '', 'Millenni di morte nun hanno intaccato l\'abilità loro. Hai contrastato il potere loro in modo magistrale.', 28153),
(154325, 'itIT', '', 'Chelle... sono le prime guardie di Re Dazar! Nun s\'arrenderanno facilmente!', 28153),
(154324, 'itIT', 'Ah! Sembra che quei non morti ora siano davvero morti! Ottimo lavoro.', '', 28153),
(154323, 'itIT', 'Quei Troll Non Morti sembrano più resistenti degli altri. Fa\' attenzione!', '', 28153),
(154322, 'itIT', 'Cosa sai dirmi degli steli marini?', 'Cosa sai dirmi degli steli marini?', 28153),
(154321, 'itIT', '', 'Queste andranno bene. Il tuo contributo di oggi non sarà dimenticato.', 28153),
(154320, 'itIT', '', 'L\'Orda ha già delle armi d\'Azerite. Vediamo se riusciamo a confiscarne qualcuna, che ne dici?', 28153),
(154319, 'itIT', '... Ovviamente quelli delle Sale della Pietra non contano.', '', 28153),
(154318, 'itIT', 'Pfff, i costrutti nanici non impazzirebbero in quel modo.', '', 28153),
(154317, 'itIT', '', 'Ottimo lavoro! Dirò ai miei alchimisti di tenere l\'Azerite lontana dalle grinfie dell\'Orda.', 28153),
(154316, 'itIT', 'Bah, tipica manifattura Troll di basso livello. Quel golem è fuori controllo. Fermalo definitivamente!', '', 28153),
(154315, 'itIT', '', 'Dobbiamo trovare Julwaba prima che lo faccia Jakra\'zet.', 28153),
(154314, 'itIT', '', 'La magia oscura di Zul ha corrotto chesto guardiano. Poni fine all\'ira sua, così potremo ripararlo.', 28153),
(154313, 'itIT', '', 'Zul... ciò che hai fatto a chesto sacro luogo è imperdonabile.', 28153),
(154312, 'itIT', '', 'Addio, Halu. Riposa in pace.', 28153),
(154311, 'itIT', '', 'Ahhh, il Maestro d\'Armi Halu... ha allenato mio padre, e il padre suo prima di lui. Mo\' è ora di donare nuovamente la pace al suo spirito.', 28153),
(154310, 'itIT', 'Ah! Sembra che tu gli abbia fatto vedere chi è il vero maestro!', '', 28153),
(154309, 'itIT', 'Un guerriero che ha allenato i reali Zandalari sta infestando questa tomba. Eliminalo!', '', 28153),
(154308, 'itIT', '', 'Ora i miei arcieri dovrebbero riuscire a cavarsela. La tua presenza ha davvero fatto la differenza. Hai i miei ringraziamenti.', 28153),
(154307, 'itIT', '', 'Le forze nemiche ci stanno attaccando da nord. Ora è il nostro turno di sferrare un attacco.', 28153),
(154306, 'itIT', 'Fateli passare!', '', 28153),
(154305, 'itIT', '', 'È quasi fatta! Riesco a sentire la voce di Akunda entrare nella mente mia.', 28153),
(154304, 'itIT', '', 'Farò quello che posso per guarire la mente di Akunda, ma preparati ad affrontare qualsiasi ricordo venga risvegliato.', 28153),
(154303, 'itIT', 'Ywaq ongg an\'qov i lal halahs nuq.', '', 28153),
(154302, 'itIT', 'Ywaq mh\'naus wgah zaix zyqtahg.', '', 28153),
(154301, 'itIT', 'Mojambo te la farà... pagare...', '', 28153),
(154300, 'itIT', '', 'Do... dove sono? Che ci faccio accà?', 28153),
(154299, 'itIT', 'Oou thyzz lal ak\'uq qwaz Zuq shkul ma sk\'tek...', '', 28153),
(154298, 'itIT', '', 'Sono un po\' misteriosi, ma sono importanti per Kul Tiras. Aiutano ad attirare i pesci nelle reti e far piovere sui campi coltivati della valle.', 28153),
(154297, 'itIT', '', 'Molti qui si affidano al mare per avere una guida, come altri fanno con la Luce, ma i Saggi delle Maree hanno un rapporto più profondo con l\'acqua.', 28153),
(154296, 'itIT', '', 'Ti offrirei volentieri un passaggio su Cuorventoso, ma i Saggi delle Maree accettano solo visitatori via mare.', 28153),
(154295, 'itIT', '', 'Andrà tutto bene, Cyrus. So badare a me stessa. E comunque, non sono sola!', 28153),
(154294, 'itIT', 'Oou yyqzz ez thyzz phquathi zuq!', '', 28153),
(154293, 'itIT', 'Oou gul\'kafh lal lwhuk!', '', 28153),
(154292, 'itIT', 'Qam oou iilth ez i awtgsshu amun on\'ma!', '', 28153),
(154291, 'itIT', 'Log\'loth w\'oq Ongg!', '', 28153),
(154290, 'itIT', '', 'Fra le rovine di Rivafosca è emersa dell\'Azerite. Non possiamo permettere che l\'Orda vi metta sopra le mani!', 28153),
(154289, 'itIT', 'W\'oq uhn\'agth ez qam Shandai!', '', 28153),
(154288, 'itIT', 'Awtgssh shn ongg shg\'ullwaq!', '', 28153),
(154287, 'itIT', 'Zuq ag\'xig bormaz ag\'thyzak!', '', 28153),
(154286, 'itIT', 'Grazie!', 'Grazie!', 28153),
(154285, 'itIT', 'Za qualar ag\'xig za al\'tha!', '', 28153),
(154284, 'itIT', 'Non mi pagano abbastanza per questo!', 'Non mi pagano abbastanza per questo!', 28153),
(154283, 'itIT', 'AHHHHHHHHHHHHHHHHHHHHHHHH!', 'AHHHHHHHHHHHHHHHHHHHHHHHH!', 28153),
(154282, 'itIT', 'Grazie per avermi $gsalvato:salvata;!', 'Grazie per avermi $gsalvato:salvata;!', 28153),
(154281, 'itIT', 'Credevo di essere già salsiccia!', 'Credevo di essere già salsiccia!', 28153),
(154280, 'itIT', 'Oou vwahuHn ag\'xig shfk zuq!', '', 28153),
(154279, 'itIT', 'Ti ringrazio, $gamico:amica;!', 'Ti ringrazio, $gamico:amica;!', 28153),
(154278, 'itIT', 'I ongg za ywaq qvsakf.', '', 28153),
(154277, 'itIT', 'Vwah oou kaaxth zz ywaq iiyoq Ag\'xlg fhssh I on\'ma.', '', 28153),
(154276, 'itIT', 'Za awtgsshu wgah uulg\'ma ywaq zaix.', '', 28153),
(154275, 'itIT', 'Qam oou uhnish kyth zuq Ongg za fhssh as\'rr.', '', 28153),
(154274, 'itIT', 'Ywaq zuq ywag shn\'ma Bo\'al za qwor.', '', 28153),
(154273, 'itIT', 'Oou qam puul zyqtahg ywaq vorzz Qam ma shn\'ma.', '', 28153),
(154272, 'itIT', 'Oou shath\'yar lwhuk shn\'ma yrr shandi agth fhssh.', '', 28153),
(154271, 'itIT', 'Quando gli spiriti sono in pace, lo è anche la foresta. Ti sono grato.', '', 28153),
(154270, 'itIT', 'Gli spiriti di fronte a te non sono altro che ombre di ciò che erano un tempo. Riscaldali con il tuo tocco. Dona loro la pace.', '', 28153),
(154269, 'itIT', 'Nun mi chiamano Signore del Maleficio per niente.', '', 28153),
(154268, 'itIT', 'Piglia il bastone del maleficio mio e trasforma nu po\' di chei sacerdoti in qualcosa di più interessante.', '', 28153),
(154267, 'itIT', 'Se pensi che sia stato rude, dovresti vedere cosa fanno fare alcuni degli altri Loa ai seguaci loro.', '', 28153),
(154266, 'itIT', 'Se non riusciamo a fermare la corruzione, chi lo farà?', 'Se non riusciamo a fermare la corruzione, chi lo farà?', 28153),
(154265, 'itIT', 'I Druidi di Gonk sono così seri. Va\' a fare qualche scherzetto vicino alli altari loro. Vediamo se si sciolgono nu pochetto. Oh, forse potrebbero cercare di acciderti.', '', 28153),
(154264, 'itIT', 'Se tutto questo si diffondesse... Azeroth sarebbe spacciata.', 'Se tutto questo si diffondesse... Azeroth sarebbe spacciata.', 28153),
(154263, 'itIT', 'La natura grida aiuto... Come possiamo fermare questa follia?', 'La natura grida aiuto... Come possiamo fermare questa follia?', 28153),
(154262, 'itIT', 'I nostri poteri non hanno alcun effetto... Come possiamo guarire il pianeta?', 'I nostri poteri non hanno alcun effetto... Come possiamo guarire il pianeta?', 28153),
(154261, 'itIT', '', 'È stato un bel viaggio! Ottimo lavoro... tutti e due.', 28153),
(154260, 'itIT', '', 'I nostri Draghi Fatati non sono abituati alle briglie, quindi il viaggio sarà alquanto movimentato. Sali in sella e guida i loro attacchi.', 28153),
(154259, 'itIT', 'Mi nutro del vostro terrore!', '', 28153),
(154258, 'itIT', 'Rinforzi di Forgiardente! In marcia verso la base nemica!', '', 28153),
(154257, 'itIT', 'Schiacciate Ar\'gorok, per Arathor! Per Stromgarde! PER L\'ALLEANZA!', '', 28153),
(154256, 'itIT', '', 'Combatti come li Zandalari delle leggende. Impressionante.', 28153),
(154255, 'itIT', '', 'Continui a dimostrare il valore tuo. Ottimo lavoro.', 28153),
(154252, 'itIT', '', 'I popoli nostri saranno entrambi al sicuro, grazie a te.', 28153),
(154251, 'itIT', '', 'Li sforzi nostri possono finalmente continuare con la morte di chel nemico.', 28153),
(154246, 'itIT', '', 'Il rifugio dovrebbe essere poco più avanti. Lì saremo al sicuro. Almeno per un po\'.', 28153),
(154245, 'itIT', '', 'Speriamo che sia l\'ultima volta che ne sentiamo parlare.', 28153),
(154244, 'itIT', '', 'La vittoria tua è stata prevista dai Loa. È bello vedere che nun si sbagliavano.', 28153),
(154243, 'itIT', '', 'I membri dell\'Orda tua saranno felici di sapere che hai risolto il problema.', 28153),
(154242, 'itIT', '', 'Sapevo che nun avrebbe avuto possibilità contro di te.', 28153),
(154240, 'itIT', 'Sentite quel brivido lungo la schiena? È lì che io esisto.', '', 28153),
(154239, 'itIT', '', 'Ho saputo che nu potente nemico nelle vicinanze desidera la morte tua. Nun mostrargli alcuna pietà.', 28153),
(154238, 'itIT', '', 'Dei guerrieri dell\'Orda mi hanno detto che nu pericoloso nemico si trova vicino a te. Eliminalo e liberali da chesto peso.', 28153),
(154237, 'itIT', '', 'I tuoi esploratori dell\'Orda parlano di nu nemico formidabile nelle vicinanze. Concordo con loro su come risolvere il problema: acciderlo.', 28153),
(154234, 'itIT', 'Sembra che Nazmir tenga n\'armata infinita di chesti selvaggi. Grazie per aver ridotto il numero loro.', '', 28153),
(154232, 'itIT', 'Ah ah ahhh! Hai un talento naturale! Non vedevo qualcuno destreggiarsi sulle piste così da tanto tempo!', '', 28153),
(154230, 'itIT', 'I Troll del Sangue stanno assaltando i cancelli nostri. Guida le bestie da guerra contro chesti selvaggi.', '', 28153),
(154228, 'itIT', 'Non ho nulla da farti fare oggi. La maggior parte dei Collorozzo è andata a divertirsi con le slitte. Perciò, prenditi un pinguino e raggiungili!', '', 28153),
(154225, 'itIT', '', 'Statt\' accuort\'. Ci sta nu pericoloso avversario vicino a te. Devi distruggerlo prima che causi altri problemi.', 28153),
(154224, 'itIT', 'Elune ti ringrazia per il tuo coraggio.', '', 28153),
(154223, 'itIT', '', 'I Loa sussurrano di nu possente avversario vicino accà. Esigono che venga spazzato via dalla faccia di Azeroth.', 28153),
(154222, 'itIT', 'Gli attacchi della Regina Banshee sono incessanti. Perlustra la foresta ed elimina la sua presenza oscura da questo posto!', '', 28153),
(154221, 'itIT', '', 'Li esploratori miei parlano di nu potente nemico vicino accà. Accidilo, qualunque cosa sia, prima che diventi na minaccia.', 28153),
(154220, 'itIT', 'Mo\' ci penseranno le forze mie. Grazie per avergli dato il tempo necessario per radunarsi.', '', 28153),
(154219, 'itIT', '', 'Stai in guardia... percepisco qua vicino qualcosa di sinistro assai. Distruggilo prima che distrugga te!', 28153),
(154218, 'itIT', 'Per ora la minaccia è stata contenuta. Gli Antichi sono nuovamente in pace, per ora.', '', 28153),
(154217, 'itIT', '', 'Ci sta nu nemico letale in chesta zona. Accidilo prima che faccia del male alli alleati nostri.', 28153),
(154216, 'itIT', 'Accidi tutto chello che nun è nu Zandalari!', '', 28153),
(154215, 'itIT', 'Gli Antichi si risvegliano di fronte alla minaccia dell\'Orda. Elimina gli invasori cosicché la nostra foresta trovi la pace.', '', 28153),
(154213, 'itIT', 'Le tue azioni oggi ci hanno dato il tempo per andare avanti.', '', 28153),
(154212, 'itIT', 'Gli alberi di questa foresta si piegano e si spezzano sotto la marcia dell\'Orda nelle nostre terre. Non dobbiamo permettergli di avanzare oltre!', '', 28153),
(154211, 'itIT', 'Statt\' accuort\' là fuori.', 'Sta\' accuort\' là fuori.', 28153),
(154210, 'itIT', 'Le sabbie ingoiano i deboli.', 'Le sabbie ingoiano i deboli.', 28153),
(154209, 'itIT', 'Non fidarti di nessuno.', 'Guardati le spalle là fuori.', 28153),
(154208, 'itIT', 'Nessuno merita chisto destino.', 'Nessuno si merita chesto destino.', 28153),
(154207, 'itIT', 'Che ti serve?', 'Tutti sono i benvenuti accà.', 28153),
(154205, 'itIT', 'Salve, cumpà.', 'Salve, cumpà.', 28153),
(154204, 'itIT', '', 'Riesssco ancora a sentirti... padrone...', 28153),
(154203, 'itIT', 'I miei sussurri scioglieranno la vostra mente.', '', 28153),
(154202, 'itIT', 'Lascia che la fame ti colga. Cibati del loro sangue.', '', 28153),
(154201, 'itIT', 'Cerca i tuoi amici. Condividi il mio dono.', '', 28153),
(154200, 'itIT', 'Requisizione eccellente. Presto, ora annienta ciò che resta dei Senzafede!', '', 28153),
(154199, 'itIT', 'Il marciume scorre nelle tue vene. Lascia che si diffonda.', '', 28153),
(154198, 'itIT', 'Recupera uno dei dispositivi dagli incantatori Senzafede e caricalo d\'energia. Ci sarà una ricompensa per i tuoi sforzi.', '', 28153),
(154197, 'itIT', 'I nostri incantatori hanno percepito delle correnti elettriche stranamente forti nel tempio.', '', 28153),
(154196, 'itIT', 'Che il banchetto delle mille fauci abbia inizio!', '', 28153),
(154195, 'itIT', 'Ottimo lavoro! Ora occupati del cuore di Sethraliss.', '', 28153),
(154194, 'itIT', 'Portami quelle reliquie e ti darò una ricompensa.', '', 28153),
(154193, 'itIT', 'Figli miei, venite a nutrirvi!', '', 28153),
(154192, 'itIT', 'So che i Senzafede hanno nascosto parecchi manufatti della nostra gente da qualche parte nel bazar, poco prima del cuore del tempio.', '', 28153),
(154191, 'itIT', 'Venite, servi del marciume. Consumate!', '', 28153),
(154190, 'itIT', 'Un ottimo esemplare! Presto, ora libera il tempio da quella feccia dei Senzafede!', '', 28153),
(154189, 'itIT', 'Ho sentito che una strana razza di krolusk ha fatto dell\'interno del tempio la sua tana. Portami uno dei loro cuccioli e ti ricompenserò.', '', 28153),
(154188, 'itIT', 'Nulla può sfuggire alla mia pestilenza!', '', 28153),
(154187, 'itIT', 'La mia piaga non può essere estirpata!', '', 28153),
(154186, 'itIT', 'I Titani non possono salvarvi!', '', 28153),
(154185, 'itIT', 'Non potete sfuggire all\'infezione!', '', 28153),
(154184, 'itIT', 'I sigilli sono rotti. La fine è giunta. Venite e siate i primi a ricevere il mio dono.', '', 28153),
(154183, 'itIT', 'I lavoratori ti sono molto grati per il salvataggio. Hai davvero salvato la loro pellaccia.', '', 28153),
(154182, 'itIT', 'Il contagio... ha attecchito dentro di voi...', '', 28153),
(154181, 'itIT', 'Le streghe hanno invaso il Porto del Norcino ancora una volta. Salva i lavoratori prima che vengano trasformati in salsicce!', '', 28153),
(154180, 'itIT', '', 'Gli spiriti degli antichi riposano e i Drust sono a pezzi. Ben fatto.', 28153),
(154179, 'itIT', '', 'Quest\'infinita battaglia minaccia i rifugiati al Presidio di Arom. Riduci i ranghi del nemico!', 28153),
(154178, 'itIT', 'Richiama la tempesta e deponi questo usurpatore!', '', 28153),
(154177, 'itIT', 'Usi bene il mio potere.', '', 28153),
(154176, 'itIT', 'Finalmente puoi sentirmi. C\'è un traditore nel nostro tempio.', '', 28153),
(154175, 'itIT', '', 'Una creatura estremamente corrotta sta minacciando la mia gente. Eliminala.', 28153),
(154174, 'itIT', '', 'Le streghe hanno liberato una potente creatura in questa zona. Distruggila!', 28153),
(154173, 'itIT', '', 'Ben fatto! La gente di Drustvar è più al sicuro grazie a te.', 28153),
(154172, 'itIT', '', 'Ben fatto! Ci penseranno due volte prima di tornare a Drustvar!', 28153),
(154171, 'itIT', 'Finalmente, sono libero! Grazie!', '', 28153),
(154170, 'itIT', '', 'Gli esploratori dicono che un pericoloso nemico si nasconde nelle vicinanze. Fallo fuori!', 28153),
(154169, 'itIT', '', 'La mia gente è minacciata da un potente nemico in questa zona. Neutralizza la minaccia.', 28153),
(154168, 'itIT', 'Come ho potuto perdere?', '', 28153),
(154167, 'itIT', '', 'Hai i più sentiti ringraziamenti della mia gente. Stanotte dormiremo tutti sonni più tranquilli.', 28153),
(154166, 'itIT', '', 'La gente di Drustvar ti è grata per il tuo aiuto.', 28153),
(154165, 'itIT', 'Non è stato molto saggio.', '', 28153),
(154164, 'itIT', '', 'Abbiamo ricevuto rapporti di un nemico nell\'area. Uccidilo.', 28153),
(154163, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t G\'huun lancia |cFFFF0404|Hspell:272506|h[Corruzione Esplosiva]|h|r su di te!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_DEATHCOIL.BLP:20|t G\'huun lancia |cFFFF0404|Hspell:272506|h[Corruzione Esplosiva]|h|r su di te!', 28153),
(154162, 'itIT', 'Finalmente la pace...', '', 28153),
(154161, 'itIT', '', 'Un nemico pericoloso sta minacciando la gente di Drustvar. Occupatene!', 28153),
(154160, 'itIT', 'Se l\'oceano non è riuscito a uccidermi, cosa ti fa credere di poterlo fare tu?', '', 28153),
(154159, 'itIT', 'Mi diffonderò e consumerò l\'intero mondo.', '', 28153),
(154158, 'itIT', 'Ci serve un trasporto per il Monastero dei Sacraonda.', 'Ci serve un trasporto per il Monastero dei Sacraonda.', 28153),
(154157, 'itIT', 'Il tuo corpo serve un nuovo padrone ora.', '', 28153),
(154155, 'itIT', 'Quante parole non dette...', '', 28153),
(154154, 'itIT', 'Posso ancora combattere!', '', 28153),
(154153, 'itIT', 'Le tue urla echeggeranno per l\'eternità!', '', 28153),
(154152, 'itIT', 'La maledizione della carne vi consuma!', '', 28153),
(154151, 'itIT', 'L\'epidemia è iniziata!', '', 28153),
(154150, 'itIT', '', 'Lo sai che devo, Kaja. Il dovere viene prima di ogni cosa.', 28153),
(154149, 'itIT', '', 'Jakra\'zet è nu traditore, ma il Re non farà nulla senza prove.', 28153),
(154148, 'itIT', 'Forse... posso riposare ora...', 'Forse... posso riposare ora...', 28153),
(154147, 'itIT', 'Abbiamo cercato di avvisarti!', 'Abbiamo cercato di avvisarti!', 28153),
(154146, 'itIT', '', 'Va\' e vedi cosa riesci a scoprire. Io starò accà con Rakera.', 28153),
(154145, 'itIT', 'Ora puoi ascoltare le parole di Akunda, ma in solitudine. Va\' all\'altare e prega quando senti che è il momento.', '', 28153),
(154144, 'itIT', 'Akunda entrerà nella tua mente solo quando sarà pura.', '', 28153),
(154143, 'itIT', 'Desidero tornare in questo posto.', 'Desidero tornare in questo posto.', 28153),
(154142, 'itIT', 'Livelli al massimo. Ripristino recupero.', '', 28153),
(154141, 'itIT', '<Althair ti saluta calorosamente.>', '<Althair ti saluta calorosamente.>', 28153),
(154140, 'itIT', '<Athair ti saluta con fermezza.>', '<Athair ti saluta con fermezza.>', 28153),
(154139, 'itIT', 'Rilascio di fluido in corso. Attivazione modalità d\'attesa.', '', 28153),
(154138, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun inizia a lanciare |cFFFF0404|Hspell:267700|h[Sguardo di G\'huun]|h|r.', '|TINTERFACE\\ICONS\\SPELL_SHADOW_POSSESSION.BLP:20|t G\'huun inizia a lanciare |cFFFF0404|Hspell:267700|h[Sguardo di G\'huun]|h|r.', 28153),
(154133, 'itIT', 'Esemplare identificato per l\'annientamento.', '', 28153),
(154132, 'itIT', 'Inizializzazione dispersione sanguigna dell\'ospite.', '', 28153),
(154131, 'itIT', 'Attivazione recupero martello.', '', 28153),
(154130, 'itIT', 'Rilascio del martello.', '', 28153),
(154129, 'itIT', 'Livelli di ca-carburante minimi. Spegnimento...', '', 28153),
(154128, 'itIT', '', 'Dranosh\'ek Mag\'har!', 28153),
(154127, 'itIT', 'Soggetti per la contaminazione selezionati.', '', 28153),
(154126, 'itIT', '', 'La guerra attanaglia questa terra. Ahah, bene! In questo massacro... noi otterremo la vittoria!', 28153),
(154125, 'itIT', '', 'Siamo gli unici sopravvissuti di un\'orgogliosa tribù. Gli incorrotti. I puri di spirito. I Mag\'har.', 28153),
(154124, 'itIT', '', 'Semplici parole per gli altri... ma dense di significato per noi.', 28153),
(154123, 'itIT', '', 'Forza e onore. Sangue e tuono.', 28153),
(154122, 'itIT', 'Risorse aggiuntive per la decomposizione.', '', 28153),
(154121, 'itIT', 'Nuovo candidato per la corruzione.', '', 28153),
(154120, 'itIT', 'Ospiti rilevati. Infezione avviata.', '', 28153),
(154119, 'itIT', '', 'Te lo assicuro, sono più reali che mai, e molto pericolosi. Nemmeno i Sethrak mettono piede nel canyon.', 28153),
(154118, 'itIT', 'Avvio recupero del plasma.', '', 28153),
(154117, 'itIT', 'Più veloci, vermi! Riparatelo e sarete pagati!', '', 28153),
(154116, 'itIT', 'Che isola magnifica...', 'Che isola magnifica...', 28153),
(154115, 'itIT', 'È stata gloriosa?', 'È stata gloriosa?', 28153),
(154114, 'itIT', '', 'Continuiamo a muoverci. Rakera nun sopravviverà a lungo in chesto deserto.', 28153),
(154113, 'itIT', 'Non fa male quanto pensav...', 'Non fa male quanto pensav...', 28153),
(154112, 'itIT', 'Perché ho fallito?', 'Perché ho fallito?', 28153),
(154111, 'itIT', 'Muori, avvoltoio!', 'Muori, avvoltoio!', 28153),
(154110, 'itIT', 'Non avrai la meglio!', 'Non avrai la meglio!', 28153),
(154109, 'itIT', 'Dov\'è la tua Regina Banshee, ora?', 'Dov\'è la tua Regina Banshee, ora?', 28153),
(154108, 'itIT', 'Non sono sopravvissuto all\'oceano per morire per mano tua!', 'Non sono sopravvissuta all\'oceano per morire per mano tua!', 28153),
(154107, 'itIT', '', 'Oh, non credo proprio.', 28153),
(154106, 'itIT', 'È ora di mettere in azione il piano di Nisha. I Sethrak non se lo aspetteranno.', '', 28153),
(154105, 'itIT', '', 'Avrei dovuto spendere di più in sicurezza.', 28153),
(154104, 'itIT', '', 'Non è ammessa alcuna distrazione!', 28153),
(154103, 'itIT', '', 'Picchiali pure, se devi! Voglio quello Spezzacoralli operativo immediatamente.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(154102, 'itIT', 'Potrebbe non resistere a lungo. Le sue ferite sono gravi.', '', 28153),
(154101, 'itIT', '', 'Io trovo sempre un modo. C\'è qualche altro sopravvissuto?', 28153),
(154100, 'itIT', 'Salva più cose possibili, prima che venga tutto distrutto.', 'Salva più cose possibili, prima che venga tutto distrutto.', 28153),
(154099, 'itIT', 'Ci sono un sacco di oggetti affascinanti qui.', 'Ci sono un sacco di oggetti affascinanti qui.', 28153),
(154098, 'itIT', 'Ci vorrà nu po\' di tempo per avere tante guardie quante ne avevamo na volta per l\'Antica Via del Mercante. L\'aiuto tuo è molto apprezzato.', '', 28153),
(154097, 'itIT', 'Grazie...', 'Grazie...', 28153),
(154096, 'itIT', 'Oh no... Non di nuovo.', 'Oh no... Non di nuovo.', 28153),
(154095, 'itIT', 'Non lasciare che mi mangino...', 'Non lasciare che mi mangino...', 28153),
(154094, 'itIT', 'Mi avevano detto... che sarebbe stato facile...', 'Mi avevano detto... che sarebbe stato facile...', 28153),
(154093, 'itIT', 'Il tuo teschio sarà un sontuoso trofeo.', 'Il tuo teschio sarà un sontuoso trofeo.', 28153),
(154092, 'itIT', 'Alcuni dei mercanti nostri hanno richiesto delle guardie per le carovane loro. Ti va di scortarle?', '', 28153),
(154091, 'itIT', 'La Piaga ti coglierà!', 'La Piaga ti coglierà!', 28153),
(154090, 'itIT', 'Il mare ti ha risparmiato la vita, ma io non lo farò!', 'Il mare ti ha risparmiato la vita, ma io non lo farò!', 28153),
(154089, 'itIT', 'Tu morirai!', 'Tu morirai!', 28153),
(154088, 'itIT', 'MOSTRI IL TUO VERO VOLTO, $GSIGNORE:SIGNORA; DELLA MORTE! VATTENE DA QUESTO LUOGO SACRO!', 'MOSTRI IL TUO VERO VOLTO, $GSIGNORE:SIGNORA; DELLA MORTE! VATTENE DA QUESTO LUOGO SACRO!', 28153),
(154087, 'itIT', 'Il passo migliore che uno può prendere è il successivo, $n. Continua così.', 'Il passo migliore che uno può prendere è il successivo, $n. Continua così.', 28153),
(154086, 'itIT', '$n, non sei che un mostruoso riflesso di Arthas. Quando la morte ultima giungerà anche per te, ti auguro che sia lenta e dolorosa, al pari della sofferenza che hai inflitto agli altri.\n\nQuando tutto il mondo era occupato in affari più importanti, non hai fatto che vagare in giro trascinando i morti in una non vita maledetta. Di certo avrai pensato che fosse per un bene superiore, ma ricorda le mie parole, $gSignore:Signora; della Morte... ci saranno conseguenze.\n\n<Zallestrasza scrolla le spalle.>\n\nMa per ora, potresti esserci utile.', '$n, non sei che un mostruoso riflesso di Arthas. Quando la morte ultima giungerà anche per te, ti auguro che sia lenta e dolorosa, al pari della sofferenza che hai inflitto agli altri.\n\nQuando tutto il mondo era occupato in affari più importanti, non hai fatto che vagare in giro trascinando i morti in una non vita maledetta. Di certo avrai pensato che fosse per un bene superiore, ma ricorda le mie parole, $gSignore:Signora; della Morte... ci saranno conseguenze.\n\n<Zallestrasza scrolla le spalle.>\n\nMa per ora, potresti esserci utile.', 28153),
(154085, 'itIT', '<L\'espressione di Zallestrasza si ammorbidisce leggermente.>\n\nAnche questo non è passato inosservato, $n. La mia gente è poca e ogni vita è preziosa.\n\nCiò non giustifica l\'offesa al mio stormo, ma comprendiamo e apprezziamo la tua... compostezza. Per una creatura come te non deve essere stato facile.', '<L\'espressione di Zallestrasza si ammorbidisce leggermente.>\n\nAnche questo non è passato inosservato, $n. La mia gente è poca e ogni vita è preziosa.\n\nCiò non giustifica l\'offesa al mio stormo, ma comprendiamo e apprezziamo la tua... compostezza. Per una creatura come te non deve essere stato facile.', 28153),
(154084, 'itIT', 'Lo sappiamo, $gSignore:Signora; della Morte $n.\n\nSappiamo che sei $gstato:stata; tu ad attaccare il nostro santuario e che hai corrotto e schiavizzato Kyranastrasz.\n\nSono insulti alla vita stessa a cui un giorno dovrai rispondere.', 'Lo sappiamo, $gSignore:Signora; della Morte $n.\n\nSappiamo che sei $gstato:stata; tu ad attaccare il nostro santuario e che hai corrotto e schiavizzato Kyranastrasz.\n\nSono insulti alla vita stessa a cui un giorno dovrai rispondere.', 28153),
(154083, 'itIT', 'Sappiamo ciò che hai fatto, Cavaliere della Morte. Le tue azioni hanno aiutato a salvare Azeroth dalla Legione Infuocata, ma la nostra fiducia è stata danneggiata.\n\nFai molta attenzione.', 'Sappiamo ciò che hai fatto, Cavaliere della Morte. Le tue azioni hanno aiutato a salvare Azeroth dalla Legione Infuocata, ma la nostra fiducia è stata danneggiata.\n\nFai molta attenzione.', 28153),
(154082, 'itIT', 'Sembra che io abbia dimenticato qualche drago al Santuario di Rubino. <Cerca di ucciderla.>', 'Sembra che io abbia dimenticato qualche drago al Santuario di Rubino. <Cerca di ucciderla.>', 28153),
(154081, 'itIT', 'Spero che le mie azioni ci abbiano fatto guadagnare un po\' di fiducia.', 'Spero che almeno le mie azioni ci abbiano fatto guadagnare un po\' di fiducia.', 28153),
(154080, 'itIT', 'La tua gente è debole ed era già comunque quasi morta. Non ho fatto altro che velocizzare le cose.', 'La tua gente è debole ed era già comunque quasi morta. Non ho fatto altro che velocizzare le cose.', 28153),
(154079, 'itIT', 'Ho risparmiato tutte le vite che potevo.', 'Ho risparmiato tutte le vite che potevo.', 28153),
(154078, 'itIT', 'Sapete chi sono?', 'Sapete chi sono?', 28153),
(154077, 'itIT', 'No! No! Nooooooo!', 'No! No! Nooooooo!', 28153),
(154076, 'itIT', '', 'Per l\'Alleanza.', 28153),
(154075, 'itIT', 'Vai via! Salvati la pelle!', 'Vai via! Salvati la pelle!', 28153),
(154074, 'itIT', 'Credo... Credo di essermela fatta sotto...', 'Credo... Credo di essermela fatta sotto...', 28153),
(154073, 'itIT', 'Fatemi uscire da qui!', 'Fatemi uscire da qui!', 28153),
(154072, 'itIT', 'Grazie! Per poco non mi facevano fuori.', 'Grazie! Per poco non mi facevano fuori.', 28153),
(154071, 'itIT', 'Cosa sono quei cosi?!? Io me la squaglio!', 'Cosa sono quei cosi?!? Io me la squaglio!', 28153),
(154070, 'itIT', 'Sono salvo! Stavo giusto per diventare cibo per mostri!', 'Sono salva! Stavo giusto per diventare cibo per mostri!', 28153),
(154069, 'itIT', 'Tsk! Una minaccia piuttosto debole, a quanto pare.', '', 28153),
(154068, 'itIT', 'Incredibile... quali altri terrori ha in serbo Ser Sacraonda?!?', '', 28153),
(154067, 'itIT', 'Un grande orrore ci attende nel santuario. Vieni, lo affronteremo faccia a faccia!', '', 28153),
(154066, 'itIT', 'Fa\' attenzione! Riesco a percepire una grande corruzione nel santuario. Non dobbiamo permettere che si diffonda!', '', 28153),
(154065, 'itIT', 'Non noto nessun cambiamento in te. Mmm. Non importa, la caccia attende.', '', 28153),
(154064, 'itIT', 'Senti la calma pervadere il tuo corpo? La tua risolutezza rafforzarsi? Avanti, facciamo il nostro dovere.', '', 28153),
(154063, 'itIT', 'Gira voce che i Saggi delle Maree siano diventati più forti grazie alle acque delle loro Fonti Purificatrici. Vediamo se è vero, prima di mettere piede nel santuario.', '', 28153),
(154062, 'itIT', 'Bah! Seguitemi, allora!', '', 28153),
(154061, 'itIT', 'Tutti devono essere puri prima di mettere piede nel nostro luogo più sacro. Accetta la benedizione di ogni Fonte Purificante prima di entrare nel cuore del santuario.', '', 28153),
(154060, 'itIT', 'Ogni piccolo contributo aiuta. Per l\'Orda!', '', 28153),
(154059, 'itIT', 'È un grande sollievo per me sapere che non tutto è alla portata di Ser Sacraonda. Grazie.', '', 28153),
(154058, 'itIT', 'C\'è molta forza in queste pozze. Recupera dei Granuli d\'Acqua Pura e il nostro potere aumenterà!', '', 28153),
(154057, 'itIT', 'Sento che c\'è ancora del buono in questo luogo sacro. Recupera dei Granuli d\'Acqua Pura, così potremo riportare il santuario alla sua antica gloria.', '', 28153),
(154056, 'itIT', 'Me l\'avevano quasi fatta. Grazie, $C.', 'Me l\'avevano quasi fatta. Grazie, $C.', 28153),
(154055, 'itIT', '', 'Contagio in espansione.', 28153),
(154054, 'itIT', '', 'Livelli virali in aumento.', 28153),
(154053, 'itIT', '', 'Nuovo ceppo rilevato.', 28153),
(154052, 'itIT', '', 'Campo chirurgico attivato. Preparazione dei campioni per l\'esame.', 28153),
(154051, 'itIT', '', 'Livelli d\'infezione critici. Purificazione totale iniziata.', 28153),
(154050, 'itIT', '', 'Aerazione camera di contenimento.', 28153),
(154049, 'itIT', '', 'Prova resistenza batterica a temperature estreme.', 28153),
(154048, 'itIT', '', 'Protocollo di dissezione attivato.', 28153),
(154047, 'itIT', '', 'Sistemi ripristinati. Livelli entro la soglia di sicurezza.', 28153),
(154046, 'itIT', 'Di certo non è stata un\'operazione tranquilla, ma quantomeno efficace.', '', 28153),
(154045, 'itIT', '', 'Chesto era l\'ultimo. Yazma nun ci spierà più mo\'!', 28153),
(154044, 'itIT', '', 'Yazma tiene spie ovunque. Osservano tutto quanto dalli occhi dei ragni. Schiacciateli.', 28153),
(154043, 'itIT', '', 'Sanitizzazione completata.', 28153),
(154042, 'itIT', 'Questa è una missione di salvataggio. Trova i nostri soldati catturati, liberali e raggiungi il punto d\'estrazione. L\'uso della forza è autorizzato. Anzi, raccomandato.', '', 28153),
(154041, 'itIT', '', 'Livello di contagio ridotto.', 28153),
(154040, 'itIT', 'Bene. La seconda squadra riuscirà a recuperare facilmente i nostri soldati.', '', 28153),
(154039, 'itIT', '', 'La Lama dell\'Ombra Razi nun acciderà più nessuno della gente mia. Grazie.', 28153),
(154038, 'itIT', '', 'Infezione epurata.', 28153),
(154037, 'itIT', 'L\'operazione è semplice. Creare caos. Ho un\'altra squadra pronta a recuperare i nostri guerrieri catturati, ma prima dovrai occuparti di quelle guardie. Entra, uccidi tutti quelli che trovi e dattela a gambe.', '', 28153),
(154036, 'itIT', '', 'Uno degli assassini più fidati di Yazma è stato avvistato nella zona. Stateve accuort\'!', 28153),
(154035, 'itIT', '', 'Ceppo virulento rilevato. Neutralizzare con estremo pregiudizio.', 28153),
(154034, 'itIT', '', 'Chesto insegnerà a Yazma e ai suoi a nun giocare col vudù oscuro.', 28153),
(154033, 'itIT', '', 'Protocollo di purificazione attivato.', 28153),
(154032, 'itIT', '', 'Il vudù fetente di Yazma ha animato chelle Maschere Tiki! Distruggete i suoi costrutti corrotti.', 28153),
(154031, 'itIT', 'Ben fatto! Ora gli uomini della Lega degli Esploratori potranno esaminare il tempio in pace.', '', 28153),
(154030, 'itIT', 'Qualcuno ha ucciso i Troll Zandalari in questa zona ed è troppo pericoloso per la Lega degli Esploratori avventurarsi nel tempio con questa minaccia! Andate là dentro ed eliminate la causa di queste morti!', '', 28153),
(154029, 'itIT', 'Fantastico! Faremo partire una spedizione immediatamente.', '', 28153),
(154028, 'itIT', 'Non posso far addentrare i miei uomini nel tempio con quelle Maschere Tiki nei paraggi. La loro magia è troppo forte!', '', 28153),
(154027, 'itIT', 'Fantastico! Anche se... continuo a sentire quelle bestiacce nella mia barba!', '', 28153),
(154026, 'itIT', 'Bah, ragni! Yazma ha riempito questo posto di maledetti ragni. Schiacciatene un po\', così potremo lavorare in pace!', '', 28153),
(154025, 'itIT', 'Forgialuce, abbattete quei Demolitori!', '', 28153),
(154024, 'itIT', 'Cavalieri di Grifoni, spiccate il volo!', '', 28153),
(154023, 'itIT', 'Ferroscuro, ora! Attaccateli dal basso!', '', 28153),
(154022, 'itIT', '', 'Bene, abbiamo le prove, ma non ne hai lasciati abbastanza perché possano attuare i loro piani! Comunque, ottimo lavoro.', 28153),
(154021, 'itIT', 'Gloria... all\'Alleanza...', '', 28153),
(154020, 'itIT', 'Sarò anche un Solcanebbia, ora, ma pensare che avrei insultato le mie radici nell\'Alleanza per mettermi con l\'Orda... come osi!', '', 28153),
(154019, 'itIT', '', 'Le ciurme di pirati del Covo della Libertà stanno sempre tramando qualcosa. Scopri di che si tratta stavolta.', 28153),
(154018, 'itIT', 'La VII Legione avrà un problema in meno di cui preoccuparsi, grazie a te.', '', 28153),
(154017, 'itIT', 'Ben fatto! Metteremo subito al sicuro l\'intera area per l\'Alleanza!', '', 28153),
(154016, 'itIT', 'È stata una grande sfida, ma hai combattuto con coraggio. Ottimo lavoro, avanti così!', '', 28153),
(154015, 'itIT', 'Il nemico è stato distrutto. È un peccato che sia dovuta finire così, ma hai fatto ciò che andava fatto.', '', 28153),
(154014, 'itIT', 'Il tuo aiuto mi avrebbe fatto davvero comodo durante la Terza Guerra, sai? Ottimo lavoro.', '', 28153),
(154013, 'itIT', 'Il tuo aiuto sarebbe stato fondamentale durante la Seconda Guerra. Ben fatto.', '', 28153),
(154012, 'itIT', 'Ottimo lavoro. Ora abbiamo una minaccia in meno di cui preoccuparci.', '', 28153),
(154011, 'itIT', 'Grazie per averci prestato la tua forza. I Devoti non lo dimenticheranno!', '', 28153),
(154010, 'itIT', '', 'Colpiscili dove fa più male! I loro portafogli!', 28153),
(154009, 'itIT', '', 'Se avessimo uno dei registri della banda, potremmo usarlo per intralciare le loro operazioni finanziarie!', 28153),
(154008, 'itIT', 'Grazie. Non possiamo ancora spostare i feriti, ma ci hai donato del tempo prezioso.', 'Grazie. Non possiamo ancora spostare i feriti, ma ci hai donato del tempo prezioso.', 28153),
(154007, 'itIT', 'Ecco, questo fermerà il sangue per un po\'...', 'Ecco, questo fermerà il sangue per un po\'...', 28153),
(154006, 'itIT', 'So che fa male, ma cerca di non muoverti...', 'So che fa male, ma cerca di non muoverti...', 28153),
(154005, 'itIT', 'Silenzio! Ci sentiranno...', 'Silenzio! Ci sentiranno...', 28153),
(154004, 'itIT', 'Andate a cercare aiuto! Vedrò cosa posso fare da dentro Uldir per fermare la corruzione!', '', 28153),
(154003, 'itIT', '', 'Riconoscerei la calligrafia di Owings dappertutto. Prima ucciderò te e poi quella traditrice!', 28153),
(154002, 'itIT', 'Argh, l\'entrata si sta chiudendo! Non posso farmi scappare questa opportunità!', '', 28153),
(154001, 'itIT', '', 'Proprio dove l\'avevo lasciato!', 28153),
(154000, 'itIT', '', 'Capitano! Abbiamo a che fare con un ammutinamento...', 28153),
(153999, 'itIT', 'Sbaglio, o quella cosa ha appena detto G\'huun?!? Seguite quella macchina!', '', 28153),
(153997, 'itIT', 'Potrebbe essere connessa a Uldir. Sbrighiamoci e scopriamolo!', '', 28153),
(153996, 'itIT', 'Ugh. Non ho mai visto questo tipo di corruzione prima d\'ora.', '', 28153),
(153995, 'itIT', '', 'Ehilà, $C. Ti interessa imparare nu po\' di Alchimia?$b$bSono la migliore istruttrice di tutta la regione, te lo posso assicurare.', 28153),
(153994, 'itIT', 'Chissà quali segreti nasconde! Potrebbe persino esserci ciò che serve per sconfiggere gli Dei Antichi!', '', 28153),
(153993, 'itIT', 'I Titani costruirono questo luogo dopo la caduta dell\'Impero Nero per fare esperimenti su ogni genere di bestia.', '', 28153),
(153992, 'itIT', 'Dannazione! Che genere di bestia è mai questa?!?', '', 28153),
(153991, 'itIT', 'Queste caverne devono portare alla leggendaria Uldir!', '', 28153),
(153990, 'itIT', 'Grazie per l\'aiuto. Il deserto è un luogo più sicuro grazie ai tuoi sforzi.', '', 28153),
(153989, 'itIT', '', 'È stata na grande sfida, ma hai combattuto bene. Ottimo lavoro, continua così!', 28153),
(153988, 'itIT', '', 'Nu problema in meno di cui preoccuparci. Hai fatto nu bel lavoro!', 28153),
(153987, 'itIT', '', 'Ben fatto. Hai dato al nemico na lezione che nun dimenticherà tanto facilmente.', 28153),
(153986, 'itIT', 'Fai strada.', 'Fai strada.', 28153),
(153985, 'itIT', '', 'Questa casa è piena di segreti. Ora che i piani superiori sono al sicuro, posso mostrarti il passaggio nascosto verso la cantina.', 28153),
(153984, 'itIT', 'Grazie per averci dato una mano. A Vol\'dun servirebbero più eroi come te!', '', 28153),
(153983, 'itIT', 'Ottimo lavoro. Il deserto ora è un po\' più sicuro grazie a te.', '', 28153),
(153982, 'itIT', 'Un pericolo in meno di cui preoccuparsi a Vol\'dun. Ben fatto!', '', 28153),
(153981, 'itIT', 'Ma pensa a tutto... quell\'oro...', '', 28153),
(153980, 'itIT', 'Hai la minima idea di ciò in cui ti stai immischiando? I Bracescura ci renderanno più potenti di quanto possiamo immaginare!', '', 28153),
(153979, 'itIT', 'Non farai alcun male alla mia gente!', '', 28153),
(153978, 'itIT', 'Le pietre sono... dappertutto... i Mogu... le avranno tutte!', '', 28153),
(153977, 'itIT', 'Lì! All\'attacco!', '', 28153),
(153976, 'itIT', '', 'Credo che siano finiti. Ottimo lavoro là dietro.', 28153),
(153975, 'itIT', 'Con queste pietre, i Mogu saranno invincibili!', '', 28153),
(153974, 'itIT', 'Osi affrontarmi faccia a faccia? Sparisci!', '', 28153),
(153973, 'itIT', '', 'Abbiamo compagnia. Dai fuoco alle polveri!', 28153),
(153972, 'itIT', '', 'Reggiti forte! Stiamo per ballare un po\'.', 28153),
(153971, 'itIT', 'Lascia che questo vecchio lupo ti mostri i suoi denti!', '', 28153),
(153970, 'itIT', 'Sei nelle mie mani!', '', 28153),
(153969, 'itIT', 'Hai un bel coraggio! Ah!', '', 28153),
(153968, 'itIT', '', 'Non credo proprio.', 28153),
(153967, 'itIT', '', 'Patetico.', 28153),
(153966, 'itIT', '', 'Non oggi!', 28153),
(153965, 'itIT', 'I miei esploratori parlano di un pericoloso avversario qui vicino. Ho bisogno che venga neutralizzato.', '', 28153),
(153962, 'itIT', 'Alcuni dei miei soldati hanno perso la vita a causa di un pericoloso nemico. Vendicali!', '', 28153),
(153959, 'itIT', 'La VII Legione ha parlato di un potente nemico qui vicino. Occupatene immediatamente.', '', 28153),
(153958, 'itIT', 'Nessun tesoro... solo oscurità.', 'Oro, a perdita d\'occhio...', 28153),
(153957, 'itIT', 'Liberami...', 'Sono... libera?', 28153),
(153956, 'itIT', 'Tesoro maledetto... Oro maledetto...', 'Sei solo nu furfante...', 28153),
(153955, 'itIT', 'Aggiungi il cadavere mio alla pila...', 'Ossa dorate...', 28153),
(153954, 'itIT', 'I rapporti parlano di un pericoloso nemico vicino alla tua posizione: eliminalo, ma guardati le spalle.', '', 28153),
(153953, 'itIT', 'Abbiamo perso degli esploratori nei pressi di un pericoloso nemico. Onorali ponendo fine a questa minaccia.', '', 28153),
(153952, 'itIT', 'Fai attenzione, c\'è una minaccia nei paraggi. Mantieni la calma e abbattila prima che riesca a fuggire.', '', 28153),
(153951, 'itIT', 'Niente male, capo. Ma se nun ti piace, puoi sempre continuare a scavare.', '', 28153),
(153950, 'itIT', 'Ho una pozione per ognuno di voi, ma... non bevetela ancora.', '', 28153),
(153949, 'itIT', 'Bene. Siete riusciti a far infuriare una città dormiente.\n\nNon perdiamo altro tempo a incolparci a vicenda.', '', 28153),
(153948, 'itIT', 'Conosco già questa storia... <Salta lo scenario e teletrasportati al Porto di Zuldazar, a Zandalar.>', 'Conosco già questa storia... <Salta lo scenario e teletrasportati al Porto di Zuldazar, a Zandalar.>', 28153),
(153947, 'itIT', 'Che questo sia un messaggio per i tuoi padroni. I Destatempesta non cadranno mai!', '', 28153),
(153946, 'itIT', 'Non lasciare che entri nella tua testa! Tieni duro!', '', 28153),
(153945, 'itIT', '', 'Tutto questo dolore e sofferenza è colpa tua. MOSTRO!', 28153),
(153944, 'itIT', 'Ci proteggerò dal suo assalto!', '', 28153),
(153943, 'itIT', 'Ni plahf Ni bormaz Oou sshoq\'meg vwyq yyg\'far', '', 28153),
(153942, 'itIT', 'Oro. Oro. Oro.', 'Altri tesori da accumulare.', 28153),
(153941, 'itIT', 'Nessuna luce. Nessuna fuga. Il Re Dimenticato ritorna.', '', 28153),
(153940, 'itIT', 'Nessuna ciurma accà...', 'Corri...', 28153),
(153939, 'itIT', 'Tutto il tesoro per Zem\'lan.', 'Solo Zem\'lan tiene il tesoro.', 28153),
(153938, 'itIT', 'È ora di passare alle presentazioni. Primo Ufficiale Owings, $n. $n, Owings. Bene, mo\' passiamo alli affari.', '', 28153),
(153937, 'itIT', '', 'Avevo avvisato Kiro che presto i Sethrak ci avrebbero attaccato. Potevamo farci trovare pronti... forse ora finalmente mi ascolterà.', 28153),
(153936, 'itIT', '', 'Non eravamo preparati al loro attacco. I Sethrak massacrano e schiavizzano senza rimorso.', 28153),
(153935, 'itIT', 'Oro...', 'Luccica...', 28153),
(153934, 'itIT', 'Una pericolosa minaccia si nasconde nelle vicinanze. Annientala prima che uccida altri innocenti.', '', 28153),
(153933, 'itIT', 'Alcuni dei nostri alleati sono stati attaccati. Elimina la minaccia immediatamente!', '', 28153),
(153930, 'itIT', 'C\'è una creatura pericolosa nelle vicinanze. Devi eliminarla prima che faccia del male ad altri innocenti.', '', 28153),
(153929, 'itIT', '', 'Ho ricevuto rapporti su una minaccia nella zona. Devi eliminarla il prima possibile!', 28153),
(153928, 'itIT', '', 'Alcuni degli alleati nostri sono stati attaccati accà vicino. Elimina la minaccia prima che colpisca di nuovo!', 28153),
(153927, 'itIT', '', 'Accà si nasconde qualcosa di assai pericoloso. Devi acciderlo prima che possa accidere te.', 28153),
(153926, 'itIT', 'Ho ricevuto rapporti su una pericolosa creatura nella zona. Devi eliminarla il prima possibile.', '', 28153),
(153925, 'itIT', 'Presto, a me!', '', 28153),
(153924, 'itIT', 'Una delle nostre carovane è stata attaccata qui vicino. Elimina la minaccia prima che accada di nuovo!', '', 28153),
(153923, 'itIT', 'So che è n\'Umana, ma cerca di essere tollerante.', '', 28153),
(153922, 'itIT', 'L\'obiettivo nostro è semplice. Se aiuteremo l\'ammutinamento, ci permetteranno di usare chesto come punto d\'appoggio per l\'attacco.', '', 28153),
(153921, 'itIT', 'Owings nun vuole rinunciare alla libertà sua come stanno facendo li altri pirati.', '', 28153),
(153920, 'itIT', 'C\'è una creatura pericolosa nelle vicinanze. Ho bisogno che te ne occupi prima che sia troppo tardi!', '', 28153),
(153919, 'itIT', 'Ho sentito parlare del contatto nostro perlustrando Tiragarde in cerca di punti di sbarco.', '', 28153),
(153918, 'itIT', 'Salve, cumpà pirata!', '', 28153),
(153917, 'itIT', 'Il regno sommerso accetterà volentieri le vostre anime.', '', 28153),
(153916, 'itIT', 'Oou c\'toth shuul phquathi ywaq uulg\'ma on\'ma', '', 28153),
(153915, 'itIT', 'Non ha più speranze! Non rimane che l\'oscurità!', '', 28153),
(153914, 'itIT', '', 'Sam, so che sei lì. Devi combattere!', 28153),
(153913, 'itIT', 'Però... nessuna creatura può bloccarti la strada tanto a lungo.', '', 28153),
(153912, 'itIT', '', 'Eccellente. Ora la via è libera.', 28153),
(153911, 'itIT', 'Era solo una replica. Non parliamone più.', '', 28153),
(153910, 'itIT', '', 'Perfetto! Da qui ci pensiamo noi e scopriremo cosa si nasconde all\'interno.', 28153),
(153909, 'itIT', 'Andranno bene. La Capoguerra ti ringrazia.', '', 28153),
(153908, 'itIT', '', 'Fantastico! Queste ci aiuteranno molto.', 28153),
(153907, 'itIT', 'Va bene, capo. Andiamo a conoscere il primo ufficiale. Comportati da pirata.', '', 28153),
(153906, 'itIT', 'Tengo proprio nu bell\'aspetto, vero? Arr!', '', 28153),
(153905, 'itIT', 'Una fastidiosa bestia sta bloccando la nostra via di fuga dalla prigione. Uccidila.', '', 28153),
(153904, 'itIT', '', 'Una potente bestia ci sta impedendo di mettere al sicuro la spiaggia. Ho bisogno che te ne occupi, così potremo liberare una via di fuga.', 28153),
(153903, 'itIT', 'Lascia che pensi io al vestiario, capo.', '', 28153),
(153902, 'itIT', 'I nostri Maestri delle Spie dicono che la Orgoglio di Kul Tiras è ormeggiata a Tol Dagor. Se è vero, dovrai rubare quella nave per conto nostro.', '', 28153),
(153901, 'itIT', '', 'Il Sovrintendente tiene un cimelio nascosto all\'interno di un modellino di una nave. Vorrei che lo recuperassi.', 28153),
(153900, 'itIT', 'La macchina bellica dell\'Orda richiede armi e armature. Prendi ciò che riesci e fai di nuovo rapporto a me.', '', 28153),
(153899, 'itIT', '', 'Con tutto questo caos, devono esserci ancora dei mercantili in giro. Vediamo se riusciamo a rubare qualcosa da sotto il loro naso.', 28153),
(153898, 'itIT', 'Hanno preso tuo padre... tradito il tuo Re... e tu non hai fatto nulla! Abbandonerai tutti i tuoi alleati per l\'Orda?', '', 28153),
(153897, 'itIT', 'Quelli dell\'Orda non sono altro che mostri. Non mi stupisce che si siano rivoltati contro di te!', '', 28153),
(153896, 'itIT', 'Sei stata dalla loro parte invece che col sangue del tuo sangue!', '', 28153),
(153895, 'itIT', 'Sei rimasta a guardare mentre quegli animali mi facevano a pezzi. Che cosa ci hai guadagnato a tradirmi?', '', 28153),
(153894, 'itIT', 'Un folto gruppo di Troll Scorzasecca si sta avvicinando a Stromgarde da est. Che ne dici di rispedirne un po\' nel luogo da cui sono venuti? Gli altri uccidili pure.', '', 28153),
(153893, 'itIT', 'Chesta nun bruciarla, idiota. Ci servirà per andarcene dall\'isola.', '', 28153),
(153892, 'itIT', 'Molti dei nostri Cavalieri di Grifoni sono stati abbattuti. Tieni gli occhi aperti!', '', 28153),
(153891, 'itIT', '', 'Ahahah! Mo\' capite! G\'huun si piglierà tutto quanto!', 28153),
(153890, 'itIT', '', 'Se chella mostruosità verrà liberata, sarà la fine di Zuldazar!', 28153),
(153889, 'itIT', '', 'Sapevo che i Troll del Sangue erano na minaccia, ma nun avrei mai immaginato... chesto...', 28153),
(153888, 'itIT', 'Chi sei?', 'Chi sei?', 28153),
(153886, 'itIT', '$gBenvenuto:Benvenuta;, $n. Voci sulle tue gesta eroiche sono giunte fino a noi.', '$gBenvenuto:Benvenuta;, $n. Voci sulle tue gesta eroiche sono giunte fino a noi.', 28153),
(153885, 'itIT', 'Maledetti abomini! Tornate negli abissi.', '', 28153),
(153884, 'itIT', 'Temo che i cultisti della Casata Sacraonda stiano cercando di allargare la loro influenza a Boralus. Rivela a tutti il loro vero volto.', '', 28153),
(153883, 'itIT', '', 'Quindi le voci erano vere. Almeno le strade sono un po\' più al sicuro, per ora.', 28153),
(153882, 'itIT', 'Venite, fratelli e sorelle. Rimaniamo uniti!', '', 28153),
(153881, 'itIT', 'Continua a muoverti. L\'oscurità sta strisciando nella sua mente!', '', 28153),
(153880, 'itIT', '', 'Tieni duro Sam! Ci siamo quasi!', 28153),
(153879, 'itIT', 'MAREE DI SANGUE! SORGETE! SORGETEEE!', '', 28153),
(153878, 'itIT', '', 'Si dice che la Guardia di Boralus sia sul libro paga delle bande criminali. Ti andrebbe di indagare?', 28153),
(153877, 'itIT', 'Fiuuu. Questo li terrà occupati per... mmm... cinque minuti?', '', 28153),
(153876, 'itIT', 'Ehi! Quegli uccelli sono fuori controllo! Dai loro un croccantino o qualcos\'altro! Presto!', '', 28153),
(153875, 'itIT', 'Va bene, nessuno di questi è mio, ma... li terrò fin quando troveremo i proprietari.', '', 28153),
(153874, 'itIT', 'Uh? Ma... dov\'è il mio portafogli? Aspetta! Quel ladruncolo me l\'ha fregato?!? Prendetelo!', '', 28153),
(153873, 'itIT', '', 'Spero che gli altri ce l\'abbiano fatta.', 28153),
(153872, 'itIT', '', 'I Vulpera non sono aggressivi. Viaggiamo in carovane, rovistando e commerciando quando possibile.', 28153),
(153871, 'itIT', 'Ce l\'hai fatta. Ai\'twen si risveglia!', '', 28153),
(153870, 'itIT', '', 'Guarda cos\'hanno fatto quei Sethrak alla nostra casa...', 28153),
(153869, 'itIT', '', 'Ottima scelta. Mi sta bene.', 28153),
(153868, 'itIT', 'Alcuni Ogre Rocciadura intendono attaccare Stromgarde. Fa\' vedere loro molto gentilmente ciò che è successo agli ultimi energumeni che hanno bussato alla nostra porta.', '', 28153),
(153867, 'itIT', 'Pazienza, Taelia. Arriveranno.', '', 28153),
(153866, 'itIT', '', 'Gli altri Destatempesta arriveranno mai qui in tempo?', 28153),
(153865, 'itIT', 'Puoi riportare quei furfanti al loro villaggio sul lago a sud-ovest per ottenere una ricompensa, ma ti sconsiglio di passare dall\'acqua... è lì che vengono concepiti, dopotutto.', '', 28153),
(153864, 'itIT', 'Sembra ci sia un branco di girini Murloc che scorrazzano in giro.', '', 28153),
(153863, 'itIT', 'I nostri esploratori riferiscono di un carico di minerali rubato nella miniera a nord-est. Dobbiamo recuperarlo, anche con la forza se necessario.', '', 28153),
(153862, 'itIT', 'Abbiamo avvistato dei taglialegna dell\'Orda indifesi. È ora di procurarsi un po\' di legna.', '', 28153),
(153861, 'itIT', 'Ricordati che la legna senziente e aggressiva è comunque... legna. Un bel po\' di legna, a dire il vero.', '', 28153),
(153860, 'itIT', 'Il Signore dei Rami Aldrus è stato avvistato nel bosco.', '', 28153),
(153859, 'itIT', 'Il Gigante della Pietra Fozruk sta seminando il panico sulla strada a sud-est. Fai attenzione a non farti calpestare.', '', 28153),
(153858, 'itIT', 'Che ne direste se lo aizzassimo contro la prima linea dell\'Orda?', '', 28153),
(153857, 'itIT', 'Abbiamo avvistato un Elementale della Terra!', '', 28153),
(153856, 'itIT', 'Coraggiosi soldati, è giunta l\'ora.', '', 28153),
(153855, 'itIT', 'Crociati, verso Ar\'gorok! La Luce lo reclama!', '', 28153),
(153854, 'itIT', 'L\'Orda sta attaccando la Vena Mineraria di Galson. Fai vedere loro che siamo in vena di combattere.', '', 28153),
(153853, 'itIT', 'L\'Orda sta attaccando i nostri alleati al Mulino delle Alture. L\'ascia che capiscano chi comanda.', '', 28153),
(153852, 'itIT', 'Le forze dell\'Orda sono entrate a Stromgarde. Proteggi il comandante e rispediscili da dove sono venuti.', '', 28153),
(153851, 'itIT', 'L\'Alto Osservatorio è sotto l\'attacco dell\'Orda. Posso suggerire di farli rotolare giù dalla collina?', '', 28153),
(153850, 'itIT', '', 'Dimmi quando e inizieremo!', 28153),
(153849, 'itIT', '', 'La Capoguerra si aspetta che ogni eroe dell\'Orda sia sveglio e pronto. Dovremmo sfruttare questo momento per allenarci un po\' in combattimento.', 28153),
(153848, 'itIT', '', 'Salve! Ti do il benvenuto a Silitus, a difesa delle nostre operazioni di estrazione dell\'Azerite.', 28153),
(153847, 'itIT', 'Contorto... distorto... i sussurri...', '', 28153),
(153846, 'itIT', 'Fammi sapere quando vuoi iniziare!', '', 28153),
(153845, 'itIT', 'Mentre pattugliamo Silitus, sfruttiamo l\'occasione per ripassare le tue abilità di combattimento.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153844, 'itIT', 'Ti do il benvenuto! Re Wrynn avrà bisogno di ogni eroe dell\'Alleanza quando affronteremo l\'Orda.', '', 28153),
(153843, 'itIT', 'Fate attenzione. Non si è guadagnato il suo nome immeritatamente.', '', 28153),
(153842, 'itIT', '', 'Notevole! Ora vediamo... Aspetta, ma quella è... Preparatevi a combattere! L\'Alleanza sta attaccando!', 28153),
(153841, 'itIT', 'La marea si alza... nessuna fuga...', '', 28153),
(153840, 'itIT', 'Difendi le balconate! Guadagna il tempo necessario affinché Zul schiacci quelle patetiche creature.', '', 28153),
(153839, 'itIT', 'Forze dell\'Orda si avvicinano al Circolo degli Elementi. Forse è ora di dargli una bella lezione di magia.', '', 28153),
(153838, 'itIT', '', 'Per mio padre!', 28153),
(153837, 'itIT', '', 'Non ci andrò leggera con te!', 28153),
(153836, 'itIT', 'Ben fatto! Ora vedremo come... Aspetta, ma quella è... Alle armi! L\'Orda sta attaccando!', '', 28153),
(153835, 'itIT', '', 'La tua ora è giunta!', 28153),
(153834, 'itIT', '', 'Per Kul Tiras!', 28153),
(153833, 'itIT', 'L\'Orda ci sta attaccando al Crocevia dei Norten. Potremmo mostrargli la nostra ospitalità con qualche carro.', '', 28153),
(153832, 'itIT', '', 'Metamorfosi Demoniaca ti trasforma in un demone, potenziando Assalto del Caos e Lame Danzanti.', 28153),
(153831, 'itIT', '', 'Siamo con te!', 28153),
(153830, 'itIT', 'L\'Orda sta marciando sul Passo di Granvalore. Quella è la nostra via d\'accesso principale. Accoglili a dovere.', '', 28153),
(153829, 'itIT', 'Metamorfosi Demoniaca ti trasforma in un demone, potenziando Assalto del Caos e Lame Danzanti.', '', 28153),
(153828, 'itIT', 'L\'Orda sta attaccando la Nuova Fattoria. Mettiamo fine a tutto questo.', '', 28153),
(153827, 'itIT', '', 'Lame Danzanti scatena una serie di attacchi rapidi che colpiscono tutti i nemici nelle vicinanze.', 28153),
(153826, 'itIT', 'Lame Danzanti scatena una serie di attacchi rapidi che colpiscono tutti i nemici nelle vicinanze.', '', 28153),
(153825, 'itIT', '', 'Anche se dispendioso, questo è il tuo attacco più potente e dovrebbe essere usato il più spesso possibile.', 28153),
(153824, 'itIT', 'Anche se dispendioso, questo è il tuo attacco più potente e dovrebbe essere usato il più spesso possibile.', '', 28153),
(153823, 'itIT', '', 'Raggio Oculare scioglie i tuoi nemici con il caos demoniaco che arde dentro di te.', 28153),
(153822, 'itIT', 'Raggio Oculare scioglie i tuoi nemici con il caos demoniaco che arde dentro di te.', '', 28153),
(153821, 'itIT', '', 'Questo è uno degli attacchi più potenti. Usalo spesso per evitare di sprecare Furia.', 28153),
(153820, 'itIT', 'Questo è uno degli attacchi più potenti. Usalo spesso per evitare di sprecare Furia.', '', 28153),
(153819, 'itIT', 'Stavo giusto per andare a cercare aiuto, ed eccoti qui! Mi hai risparmiato un viaggio.', '', 28153),
(153818, 'itIT', 'Soldati dell\'Orda in arrivo. Fa\' del tuo meglio per respingerli.', '', 28153),
(153817, 'itIT', '', 'Usa Dominazione sul Manichino d\'Allenamento.', 28153),
(153816, 'itIT', 'Usa Dominazione sul Manichino.', '', 28153),
(153815, 'itIT', 'Sembra che abbiamo sollevato un vespaio. L\'Orda ci sta attaccando con ogni cosa a disposizione.', '', 28153),
(153814, 'itIT', '', 'Questo attacco devastante potenzia il tuo prossimo Assalto Mortale, quindi cerca di usarlo il più possibile.', 28153),
(153813, 'itIT', 'Questo attacco devastante potenzia il tuo prossimo Assalto Mortale, quindi cerca di usarlo il più possibile.', '', 28153),
(153812, 'itIT', '', 'Dominazione sfrutta la tua immensa forza per sferrare un colpo critico sul nemico.', 28153),
(153811, 'itIT', 'Dominazione sfrutta la tua immensa forza per sferrare un colpo devastante sul nemico.', '', 28153),
(153810, 'itIT', '', 'Hai subito dei danni, ma non è certo un problema per te.', 28153),
(153809, 'itIT', 'Hai subito dei danni, ma non è certo un problema per te.', '', 28153),
(153804, 'itIT', 'Usa Risucchio di Vita per rigenerare la tua salute.', '', 28153),
(153803, 'itIT', '', 'Usa Risucchio di Vita per rigenerare la tua salute.', 28153),
(153802, 'itIT', '', 'Risucchio di Vita consuma la linfa vitale del tuo bersaglio, curandoti mentre infligge danni.', 28153),
(153801, 'itIT', 'Risucchio di Vita consuma la linfa vitale del tuo bersaglio, curandoti mentre infligge danni.', '', 28153),
(153798, 'itIT', '', 'Usa Dardo d\'Ombra sul Manichino.', 28153),
(153797, 'itIT', 'Usa Dardo d\'Ombra sul Manichino.', '', 28153),
(153796, 'itIT', '', 'Lancia Dardo d\'Ombra mentre i tuoi altri incantesimi stanno tormentando la vittima.', 28153),
(153795, 'itIT', 'Lancia Dardo d\'Ombra mentre i tuoi altri incantesimi stanno tormentando la vittima.', '', 28153),
(153794, 'itIT', '', 'Dopo aver colpito il bersaglio con Agonia e Corruzione, continua l\'attacco sfruttando la magia dell\'ombra.', 28153),
(153793, 'itIT', 'Dopo aver colpito il bersaglio con Agonia e Corruzione, continua l\'attacco sfruttando la magia dell\'ombra.', '', 28153),
(153792, 'itIT', 'Che le ombre ti consumino!', '', 28153),
(153791, 'itIT', '', 'Usare Frenesia Feroce ridurrà anche il tempo di recupero di Ira Bestiale.', 28153),
(153790, 'itIT', 'Usare Frenesia Feroce ridurrà anche il tempo di recupero di Ira Bestiale.', '', 28153),
(153789, 'itIT', '', 'Le tue azioni non saranno tollerate!', 28153),
(153788, 'itIT', '', 'Usa Frenesia Feroce mentre attacchi il Manichino.', 28153),
(153787, 'itIT', 'Usa Frenesia Feroce mentre attacchi il Manichino.', '', 28153),
(153786, 'itIT', '', 'Frenesia Feroce fa infuriare il tuo famiglio mandandolo all\'attacco, lasciandoti concentrare sulle tue altre abilità.', 28153),
(153785, 'itIT', 'Frenesia Feroce fa infuriare il tuo famiglio mandandolo all\'attacco, lasciandoti concentrare sulle tue altre abilità.', '', 28153),
(153784, 'itIT', '', 'Puoi anche ordinare al tuo famiglio di eseguire una serie di attacchi rapidi.', 28153),
(153783, 'itIT', 'Puoi anche ordinare al tuo famiglio di eseguire una serie di attacchi rapidi.', '', 28153),
(153782, 'itIT', '', 'Usa Bomba di Fuocobrado per bruciare tutti i nemici.', 28153),
(153781, 'itIT', 'Usa Bomba di Fuocobrado per bruciare tutti i nemici.', '', 28153),
(153780, 'itIT', '', 'Sono più efficaci contro gruppi di avversari, in quanto il fuoco può colpire ogni nemico in un cono alle spalle del bersaglio.', 28153),
(153779, 'itIT', 'Sono più efficaci contro gruppi di avversari, in quanto il fuoco può colpire ogni nemico in un cono alle spalle del bersaglio.', '', 28153),
(153778, 'itIT', '', 'Le Bombe di Fuocobrado sono un altro strumento a tua disposizione: incendiano i nemici infliggendo danni periodici.', 28153),
(153777, 'itIT', 'Le Bombe di Fuocobrado sono un altro strumento a tua disposizione, incendiano i nemici infliggendo danni periodici.', '', 28153),
(153776, 'itIT', '', 'Usa Morso del Serpente sul Manichino.', 28153),
(153775, 'itIT', 'Usa Morso del Serpente sul Manichino.', '', 28153),
(153774, 'itIT', '', 'Morso del Serpente scaglia una freccia imbevuta di veleno che infligge danni da natura periodici.', 28153),
(153773, 'itIT', 'Morso del Serpente scaglia una freccia imbevuta di veleno che infligge danni da natura periodici.', '', 28153),
(153772, 'itIT', '', 'Le tue abilità di survivalista ti forniscono potenti mezzi per affrontare gli avversari.', 28153),
(153771, 'itIT', 'Le tue abilità di survivalista ti forniscono potenti mezzi per affrontare gli avversari.', '', 28153),
(153770, 'itIT', 'Sto serpente...!', '', 28153),
(153769, 'itIT', 'Vento in poppa!', 'Vento in poppa!', 28153),
(153768, 'itIT', 'Sta\' alla larga dalle sirene!', 'Sta\' alla larga dalle sirene!', 28153),
(153767, 'itIT', 'Il Loa mio urla di dolore! L\'eresia di Zul nun tiene limiti!', '', 28153),
(153766, 'itIT', 'Stai al caldo!', 'Stai al caldo!', 28153),
(153765, 'itIT', 'Recupera la nave mia, poi ci occuperemo degli usurpatori che hanno cercato di rubarmi il trono.', '', 28153),
(153764, 'itIT', 'Salpare le ancore!', 'Salpiamo l\'ancora!', 28153),
(153763, 'itIT', 'A presto!', 'A presto!', 28153),
(153762, 'itIT', 'I pesci sono strani.', 'I pesci sono strani.', 28153),
(153761, 'itIT', 'Tu ce l\'hai uno scorbuto?', 'Tu ce l\'hai uno... scorbuto?', 28153),
(153759, 'itIT', 'Ho fatto... la parte mia...', '', 28153),
(153758, 'itIT', 'Mi piacciono i Tortolliani.', 'Mi piacciono i Tortolliani.', 28153),
(153757, 'itIT', 'Mmm... quale parte è Tribordo?', 'Mmm... quale parte è Tribordo?', 28153),
(153756, 'itIT', 'YARRR!!! Sembro un pirata?', 'YARRR!!! Sembro un pirata?', 28153),
(153755, 'itIT', 'Salve!', 'Salve!', 28153),
(153754, 'itIT', '', 'Usa Ordine di Morte più volte sul Manichino d\'Allenamento.', 28153),
(153753, 'itIT', 'Usa Ordine di Morte più volte sul Manichino d\'Allenamento.', '', 28153),
(153752, 'itIT', '', 'Ordine di Morte permette al tuo famiglio di eseguire un potente attacco che genera Focus utilizzabile per altre abilità.', 28153),
(153751, 'itIT', 'Ordine di Morte permette al tuo famiglio di eseguire un potente attacco che genera Focus utilizzabile per altre abilità.', '', 28153),
(153750, 'itIT', 'Mio padre dice sempre che devo diventare un lupo di mare, ma a me i lupi fanno paura!', 'Mio padre dice sempre che devo diventare un lupo di mare, ma a me i lupi fanno paura!', 28153),
(153749, 'itIT', '', 'Ora che hai accorciato la distanza dalla preda, è tempo di scatenare la tua furia.', 28153),
(153748, 'itIT', 'Ora che hai accorciato la distanza dalla preda, è tempo di scatenare la tua furia.', '', 28153),
(153747, 'itIT', 'Sento... freddo...', 'Sento... freddo...', 28153),
(153746, 'itIT', 'Non dovresti essere qui!', 'Non dovresti essere qui!', 28153),
(153745, 'itIT', 'E sia. Dirigiti a Kezan. Recupera i piani per il raffinamento dell\'Azerite che ci spettano... e fa\' soffrire il Magnate Trucirazzi per non aver rispettato il patto con la Dama Oscura.', '', 28153),
(153744, 'itIT', 'Lo sapevo che quell\'affare ci avrebbe portato solo guai. C\'è un modo più semplice per ottenere ciò che vogliamo. Eliminare l\'intermediario. Capisci ciò che intendo?', '', 28153),
(153743, 'itIT', 'La Capoguerra non ne sarà felice. Contavamo molto sui metodi di raffinamento dell\'Azerite di Trucirazzi, nella guerra contro l\'Alleanza.', '', 28153),
(153742, 'itIT', 'Chiedo scuuusa, Principe Banshee. Scusa se sono scosso dopo essere stato quasi ucciso... a causa di un affare a cui ero contrario!', '', 28153),
(153741, 'itIT', 'Cerca di ricomporti, Principe del Commercio. Un balbettamento simile non si addice a un capo dell\'Orda.', '', 28153),
(153740, 'itIT', 'Il Magnate Trucirazzi ci ha ingannato! È stato pazzesco! Non l\'avevo mai visto ritirarsi da un affare così. Non crederesti mai a cosa...', '', 28153),
(153739, 'itIT', 'Ehi, Sig. Selvamorta. Ho delle brutte notizie...', '', 28153),
(153738, 'itIT', '', 'Troll del Sangue... prendete... più potere!', 28153),
(153737, 'itIT', '', 'Potere! POTERE!', 28153),
(153736, 'itIT', 'Ai\'twen sta riposando, recuperando le forze per quando avremo ancora bisogno di lui.', '', 28153),
(153735, 'itIT', 'Teletrasportami da G\'huun.', 'Teletrasportami da G\'huun.', 28153),
(153734, 'itIT', 'Teletrasportami da Mythrax.', 'Teletrasportami da Mythrax.', 28153),
(153733, 'itIT', 'Teletrasporto a Discesa alle Rovine.', 'Teletrasporto a Discesa alle Rovine.', 28153),
(153732, 'itIT', 'Teletrasportami all\'ingresso di Uldir.', 'Teletrasportami all\'ingresso di Uldir.', 28153),
(153731, 'itIT', 'La Piattaforma di Dislocazione sembra attiva e stabile.', 'La Piattaforma di Dislocazione sembra attiva e stabile.', 28153),
(153730, 'itIT', 'Un altro giorno, un\'altra vittoria!', '', 28153),
(153729, 'itIT', 'Le mie guardie dicono che i Trogg starebbero preparando un altro attacco! Fermali prima che sia troppo tardi!', '', 28153),
(153728, 'itIT', 'Fatto? Bene. Meno animali impazziti capaci di mangiarmi vivo ci sono, meglio è.', '', 28153),
(153727, 'itIT', 'Orsi stregati? No! Assolutamente no. Ti prego... sbarazzati di loro.', '', 28153),
(153726, 'itIT', '', 'Pensa pure quello che vuoi, ma non mi fido degli alberi che possono camminare.', 28153),
(153725, 'itIT', '', 'Sembra ci siano di nuovo problemi al cantiere degli Algerson. Aiutali!', 28153),
(153724, 'itIT', 'Fantastico! Tu e il tuo amichetto peloso siete una squadra formidabile.', '', 28153),
(153723, 'itIT', 'Nickel continua a voler uscire per andare a caccia di falchi. Ti andrebbe di portarlo con te per farlo esercitare un po\'?', '', 28153),
(153722, 'itIT', 'Ah, una preda notevole, come al solito. Complimenti!', '', 28153),
(153721, 'itIT', 'Altro giorno, altra caccia! Vediamo cosa riesci ad abbattere questa volta!', '', 28153),
(153720, 'itIT', 'Sono successe molte cose in città ultimamente. Stare sull\'acqua è meglio. È bello accà.', '', 28153),
(153719, 'itIT', 'I Naga sono arrivati alcuni anni fa. I giganti loro hanno devastato il tempio.', '', 28153),
(153718, 'itIT', 'È na vergogna chello che è accaduto ad Atal\'gral.', '', 28153),
(153717, 'itIT', 'Continuo a controllare sotto la barca di notte. Chei Naga stanno ovunque.', '', 28153),
(153716, 'itIT', 'Atal\'gral', 'Atal\'gral', 28153),
(153715, 'itIT', 'Porto di Zuldazar', 'Porto di Zuldazar', 28153),
(153714, 'itIT', '', 'Gral si è avvicinato troppo.', 28153),
(153713, 'itIT', '', 'Raggiungi Atal\'gral. Spero davvero che il tempio sia ancora in piedi.', 28153),
(153712, 'itIT', 'Con il tuo aiuto, Pescagrossa sarà ripristinata un giorno.', '', 28153),
(153711, 'itIT', 'La morsa di Scrutafondi su Pescagrossa è ancora forte. Dobbiamo riportare questo pontile alla normalità!', '', 28153),
(153710, 'itIT', 'Le acque tirano un respiro di sollievo. Hai alleviato il loro dolore, e per questo ti ringrazio.', '', 28153),
(153709, 'itIT', 'C\'è bisogno d\'aiuto per ripulire la baia dalla corruzione. Purifica le acque dalle creature infette!', '', 28153),
(153708, 'itIT', 'Grazie mille. Li manderò immediatamente all\'avamposto!', '', 28153),
(153707, 'itIT', 'Rosaline ha richiesto altro filo spinato. Ti andrebbe di dare una mano?', '', 28153),
(153706, 'itIT', 'Eccellente! Questo dovrebbe tenere alta la fiducia di Majo per un po\'.', '', 28153),
(153705, 'itIT', 'Il nostro amico dal guscio duro, Majo, sta facendo pratica di equitazione, ma di tanto in tanto ha bisogno di un piccolo aiutino. Ti andrebbe di portargli la sua bevanda preferita?', '', 28153),
(153704, 'itIT', '', 'Speriamo che i contrabbandieri abbiano imparato la lezione. Il crimine non paga!', 28153),
(153703, 'itIT', '', 'Quei contrabbandieri pensano di potersene andare da Boralus con le armi della nostra milizia. Mostragli quanto si sbagliano!', 28153),
(153702, 'itIT', 'Bambini, mettetevi in salvo! Presto!', 'Bambini, mettetevi in salvo! Presto!', 28153),
(153701, 'itIT', 'Non temete, sarò dietro di voi...', 'Non temete, sarò dietro di voi...', 28153),
(153700, 'itIT', 'Presto, qui dentro!', 'Presto, qui dentro!', 28153),
(153699, 'itIT', 'Va bene, da qui ce ne occupiamo noi. Ehi, avete tutti ancora entrambi gli occhi! Ben fatto!', '', 28153),
(153698, 'itIT', 'I mari di Kul Tiras vi inghiottiranno!', 'I mari di Kul Tiras vi inghiottiranno!', 28153),
(153697, 'itIT', 'E sia. La mia famiglia è al sicuro.', 'E sia! La mia famiglia è al sicuro.', 28153),
(153696, 'itIT', 'La pagherete!', 'La pagherete!', 28153),
(153695, 'itIT', 'Selvaggi!', 'Selvaggi!', 28153),
(153694, 'itIT', 'Questa piazza è stata invasa dagli uccelli! Sarà meglio evacuare i civili, prima che quelle bestiacce inizino a strappar loro gli occhi. Ma non dir loro che te l\'ho detto!', '', 28153),
(153693, 'itIT', 'Aiuto! Salvaci!', 'Aiuto! Salvateci!', 28153),
(153692, 'itIT', 'Non così...', 'Non così...', 28153),
(153691, 'itIT', 'Ho paura!', 'Ho paura!', 28153),
(153690, 'itIT', 'Ma... i miei genitori...', 'Ma i miei genitori...', 28153),
(153689, 'itIT', 'Moriremo?', 'Moriremo?', 28153),
(153688, 'itIT', 'Perché non ti muovi? Ho paura!', 'Perché non ti muovi? Ho paura!', 28153),
(153687, 'itIT', 'Svegliati! Ti prego svegliati...', 'Svegliati! Ti prego... svegliati...', 28153),
(153686, 'itIT', 'PAPÀ!', 'PAPÀ!', 28153),
(153685, 'itIT', 'MAMMA!', 'MAMMA!', 28153),
(153684, 'itIT', 'Sta\' accuort\' là fuori! Che tu tenga sempre il vento in poppa!', '', 28153),
(153683, 'itIT', '', 'Il tuo arrivo era stato predetto dalle pergamene.', 28153),
(153682, 'itIT', 'Ahhh, sì. Si sono dimostrati particolarmente utili.', '', 28153),
(153681, 'itIT', 'Ho bisogno di riparazioni.', 'Ho bisogno di riparazioni.', 28153),
(153680, 'itIT', '', 'Ricorda di riposare. Devi essere in forze per servire l\'Alleanza.', 28153),
(153679, 'itIT', 'L\'Orda ha preso il controllo del Circolo degli Elementi!', 'L\'Orda ha preso il controllo del Circolo degli Elementi!', 28153),
(153678, 'itIT', '$n ha conquistato il Circolo degli Elementi!', '$n ha conquistato il Circolo degli Elementi!', 28153),
(153677, 'itIT', 'L\'Orda ha preso il controllo della Vena Mineraria di Galson!', 'L\'Orda ha preso il controllo della Vena Mineraria di Galson!', 28153),
(153676, 'itIT', '$n ha conquistato la Vena Mineraria di Galson!', '$n ha conquistato la Vena Mineraria di Galson!', 28153),
(153675, 'itIT', 'L\'Orda ha preso il controllo del Crocevia dei Norten!', 'L\'Orda ha preso il controllo del Crocevia dei Norten!', 28153),
(153674, 'itIT', '$n ha conquistato il Crocevia dei Norten!', '$n ha conquistato il Crocevia dei Norten!', 28153),
(153673, 'itIT', 'L\'Orda ha preso il controllo dell\'Alto Osservatorio!', 'L\'Orda ha preso il controllo dell\'Alto Osservatorio!', 28153),
(153672, 'itIT', '$n ha conquistato l\'Alto Osservatorio!', '$n ha conquistato l\'Alto Osservatorio!', 28153),
(153671, 'itIT', 'L\'Orda ha preso il controllo della Nuova Fattoria!', 'L\'Orda ha preso il controllo della Nuova Fattoria!', 28153),
(153670, 'itIT', '$n ha conquistato la Nuova Fattoria!', '$n ha conquistato la Nuova Fattoria!', 28153),
(153669, 'itIT', 'L\'Orda ha preso il controllo della Segheria delle Alture!', 'L\'Orda ha preso il controllo della Segheria delle Alture!', 28153),
(153668, 'itIT', '$n ha conquistato la Segheria delle Alture!', '$n ha conquistato la Segheria delle Alture!', 28153),
(153667, 'itIT', 'L\'Orda ha preso il controllo del Passo di Granvalore!', 'L\'Orda ha preso il controllo del Passo di Granvalore!', 28153),
(153666, 'itIT', '$n ha conquistato il Passo di Granvalore!', '$n ha conquistato il Passo di Granvalore!', 28153),
(153665, 'itIT', 'Le nostre eroiche gesta rimarranno nelle pergamene di storia militare.', '', 28153),
(153664, 'itIT', 'La nostra brillante strategia e la sua perfetta esecuzione hanno confuso il nemico.', '', 28153),
(153663, 'itIT', 'Credo che li abbiamo colti alla sprovvista. Ahah!', '', 28153),
(153662, 'itIT', '', 'Victoria! Non ce l\'ha fatta...', 28153),
(153661, 'itIT', '', 'Seguite tutti Nathanos nel cortile! Io bloccherò l\'Alleanza da dietro!', 28153),
(153660, 'itIT', 'Soldati, in posizione! L\'Alleanza si avvicina!', '', 28153),
(153659, 'itIT', '', 'Gli Zandalari non conoscono gli orrori che li attendono. Devono essere avvisati.', 28153),
(153658, 'itIT', '', 'La Regina Azshara sta pianificando qualcosa, e non è da sola.', 28153),
(153657, 'itIT', '', 'Oh cielo! È terribile. Questi ordini dicono di uccidere tutti coloro leali a Gral!', 28153),
(153656, 'itIT', 'Ci troveremo in vantaggio di dieci a uno all\'aperto!', '', 28153),
(153655, 'itIT', 'Nun... rimettetemi... nel... golem...', 'Lasciate andare lo spirito mio. Vi prego...', 28153),
(153654, 'itIT', 'Stiamo... venendo a pigliarti, Zak\'rajan...', 'Tu sei il prossimo, Zak\'rajan...', 28153),
(153653, 'itIT', 'Final... mente... è... finita...', 'Finalmente... Lasciami riposare...', 28153),
(153652, 'itIT', 'Bwonsamdi... non mi lascerà schiattare...', 'Dove sta... l\'Aldilà?', 28153),
(153651, 'itIT', 'L\'arboscello è stato consumato dalla fauna!', 'L\'arboscello è stato consumato dalla fauna!', 28153),
(153650, 'itIT', 'AAAUUUH!', '', 28153),
(153649, 'itIT', 'L\'Orda non deve fuggire!', '', 28153),
(153648, 'itIT', 'Guardie, siamo sotto attacco! Ai vostri posti! Chiudete i cancelli e sigillate le uscite!', '', 28153),
(153647, 'itIT', 'Fantastico. In sella!', '', 28153),
(153646, 'itIT', 'Sicuro.', 'Sicuro.', 28153),
(153645, 'itIT', 'I tuoi amici sono stati torturati e uccisi dalle streghe.', 'I tuoi amici sono stati torturati e uccisi dalle streghe.', 28153),
(153644, 'itIT', 'Ahhh, che fregatura! Non va bene.\n\nHo delle buone notizie: ho quasi finito di preparare un avamposto in cima alla collina. Ti va di andare a vederlo?', '', 28153),
(153643, 'itIT', 'Pare che tu sia $garrivato:arrivata; dalla foresta. Come stanno i ragazzi laggiù?', '', 28153),
(153642, 'itIT', 'E giusto in tempo. Ho appena finito di inventare il Lupociclo!', '', 28153),
(153641, 'itIT', 'Capo, sei qui! E hai portato la Treruote!', '', 28153),
(153640, 'itIT', '1 minuto alla Battaglia per Stromgarde.', '', 28153),
(153639, 'itIT', 'Uniti siamo più forti!', '', 28153),
(153638, 'itIT', 'Mai arrendersi, sopravvivere sempre.', '', 28153),
(153637, 'itIT', 'Fa\' attenzione.', '', 28153),
(153636, 'itIT', 'Cos\'avevo detto sul nun fare niente di stupido?', '', 28153),
(153635, 'itIT', 'Gli Esiliati ti danno il benvenuto, viandante.', '', 28153),
(153634, 'itIT', 'Sei $gvenuto:venuta; a dare una mano?', '', 28153),
(153633, 'itIT', 'Cosa ti porta qui?', '', 28153),
(153632, 'itIT', 'Che il vento sia sempre alle tue spalle.', '', 28153),
(153631, 'itIT', 'Forza e virtù.', '', 28153),
(153630, 'itIT', 'Vai con onore.', '', 28153),
(153629, 'itIT', 'Cheste terre si rivolteranno... contro di voi...', 'Cheste terre si rivolteranno... contro di voi...', 28153),
(153628, 'itIT', 'No! Dovevo prendermi la capa tua...', 'No! Dovevo prendermi la capa tua...', 28153),
(153627, 'itIT', 'Stupida... Alleanza...', 'Stupida... Alleanza...', 28153),
(153626, 'itIT', 'Nun durerai ancora a lungo...', 'Nun durerai ancora a lungo...', 28153),
(153625, 'itIT', 'L\'impero... vive...', 'L\'impero... vive...', 28153),
(153624, 'itIT', 'Le forze nostre nun si arrenderanno mai...', 'Le forze nostre nun si arrenderanno mai...', 28153),
(153623, 'itIT', 'Hai la mia attenzione.', '', 28153),
(153622, 'itIT', 'Nun finisce accà...', 'Nun finisce accà...', 28153),
(153621, 'itIT', 'Ti do il benvenuto fra noi.', '', 28153),
(153620, 'itIT', 'Per... l\'Orda.', 'Per... l\'Orda.', 28153),
(153619, 'itIT', 'Mi daranno na ricompensa per la capa tua.', 'Mi daranno na ricompensa per la capa tua.', 28153),
(153618, 'itIT', 'Pensi di essere più $gfurbo:furba; di noi? Ahahah!', 'Pensi di essere più $gfurbo:furba; di noi? Ahahah!', 28153),
(153617, 'itIT', 'Ci prenderemo le cape vostre come trofei!', 'Ci prenderemo le cape vostre come trofei!', 28153),
(153616, 'itIT', 'Nun puoi trovarci tutti quanti!', 'Nun puoi trovarci tutti quanti!', 28153),
(153615, 'itIT', 'Giochiamo a fare la guerra, Alleanza?', 'Giochiamo a fare la guerra, Alleanza?', 28153),
(153614, 'itIT', 'Cheste terre appartengono alli Zandalari!', 'Cheste terre appartengono alli Zandalari!', 28153),
(153613, 'itIT', 'Ti pentirai di essere $gvenuto:venuta; accà!', 'Ti pentirai di essere $gvenuto:venuta; accà!', 28153),
(153612, 'itIT', 'Nun appartieni a cheste terre!', 'Nun appartieni a cheste terre!', 28153),
(153611, 'itIT', 'Neanche per sogno. Siamo migliori di questi selvaggi.', 'Neanche per sogno. Siamo migliori di questi selvaggi.', 28153),
(153610, 'itIT', 'No, non senza di te!', 'No, non senza di te!', 28153),
(153609, 'itIT', 'Ora ce ne andremo da qui!', 'Ora ce ne andiamo da qui!', 28153),
(153608, 'itIT', 'Io non ti lascio!', 'Io non ti lascio!', 28153),
(153607, 'itIT', 'Cosa stai facendo? Mettiti in salvo!', 'Che stai facendo? Mettiti in salvo!', 28153),
(153606, 'itIT', 'Vai a cercare aiuto! Io me la caverò!', 'Cerca aiuto! Io me la caverò!', 28153),
(153605, 'itIT', 'Vattene, è troppo tardi...', 'Vattene, è troppo tardi...', 28153),
(153604, 'itIT', 'Devi scappare...', 'Devi scappare...', 28153),
(153603, 'itIT', 'Ti tengo d\'occhio.', '', 28153),
(153602, 'itIT', 'Forse la prossima volta saranno più cauti ed eviteranno di farsi catturare. Sono fortunati che l\'Orda abbia un campione come te tra i suoi ranghi.', '', 28153),
(153601, 'itIT', 'I nostri alleati hanno bisogno di aiuto. Sembra che siano stati catturati. Liberali.', '', 28153),
(153600, 'itIT', 'Con queste informazioni, la vittoria contro l\'Alleanza è sempre più vicina. I tuoi sforzi verranno ricompensati.', '', 28153),
(153599, 'itIT', 'Le nostre spie ci hanno informato che tra non molto un importante messaggio verrà consegnato in quest\'area. Intercettalo con ogni mezzo necessario.', '', 28153),
(153598, 'itIT', 'Il favore dei Loa è con te. Chesta è na buona cosa! Ma nun montarti la capa.', '', 28153),
(153597, 'itIT', 'I nemici nostri stanno infestando di nuovo il Giardino dei Loa. Tengono bisogno di na bella lezione di buone maniere. Che il potere dei Loa sia con te!', '', 28153),
(153596, 'itIT', 'Troviamoci all\'avamposto, dobbiamo scoprire la risposta. Sento puzza di una possibile rivolta.', '', 28153),
(153595, 'itIT', 'Non è stato un lavoro molto discreto, ma era necessario. Dobbiamo continuare a tenere i nostri nemici all\'oscuro.', '', 28153),
(153594, 'itIT', 'L\'Alleanza ha mandato le sue spie a ficcare il naso nei nostri piani. Dobbiamo impedirglielo. Occupatene tu.', '', 28153),
(153593, 'itIT', 'L\'Alleanza ci annienterà se non avremo l\'aiuto della flotta degli Zandalari.', '', 28153),
(153592, 'itIT', 'L\'Alleanza non starà ad aspettare che costruiamo una flotta prima di attaccare. Abbiamo bisogno degli Zandalari.', '', 28153),
(153591, 'itIT', 'Fai unire quegli Zandalari all\'Orda.', '', 28153),
(153590, 'itIT', 'Abbiamo bisogno della flotta degli Zandalari.', '', 28153),
(153589, 'itIT', 'Sia fatto il volere della Capoguerra.', '', 28153),
(153588, 'itIT', 'Con te e Ai\'twen al nostro fianco, il piano non può fallire.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153587, 'itIT', 'Sembra che io non piaccia molto agli Zandalari.', '', 28153),
(153586, 'itIT', 'Voce dell\'Orda.', '', 28153),
(153585, 'itIT', 'La flotta degli Zandalari DEVE unirsi all\'Orda. Fa\' in modo che succeda.', '', 28153),
(153584, 'itIT', '', 'Chesto campione ha sfidato la potenza di Roccavento per salvare me e Zul. Nu tale coraggio merita n\'udienza, padre.', 28153),
(153583, 'itIT', 'Mio Re, l\'Orda è venuta solamente per rubare la flotta nostra per conto della Capoguerra sua.', '', 28153),
(153582, 'itIT', 'Abbiamo della bella roba qui, ma non fare domande.', 'Abbiamo della bella roba qui, ma non fare domande.', 28153),
(153581, 'itIT', 'Porto rifornimenti da Alto Monte.', 'Porto rifornimenti da Alto Monte.', 28153),
(153580, 'itIT', 'Osserva gli eventi che hanno provocato la ferita di Azeroth.', 'Osserva gli eventi che hanno provocato la ferita di Azeroth.', 28153),
(153579, 'itIT', '<La console dei Titani mostra una serie di dati sullo schermo. Puoi selezionarne uno per visualizzarlo.>', '', 28153),
(153578, 'itIT', 'Spero tu abbia delle mutande ignifughe!', 'Spero tu abbia delle mutande ignifughe!', 28153),
(153577, 'itIT', 'La situazione sta per farsi calda!', 'La situazione sta per farsi calda!', 28153),
(153576, 'itIT', 'È ora di accendere il tuo entusiasmo!', 'È ora di accendere il tuo entusiasmo!', 28153),
(153575, 'itIT', 'Quel \"Nano di diamante\" parla per conto dell\'anima del mondo. Non interverrebbe se la situazione non fosse grave.', '', 28153),
(153574, 'itIT', '', 'Te l\'immagini? Il Nano di diamante potrebbe mandarci ovunque su Azeroth!', 28153),
(153573, 'itIT', 'Mi piace questo Nano di diamante che regala potenti doni. Possiamo tenerlo?', '', 28153),
(153572, 'itIT', 'Sono sicuro che sia importante, Magni, ma per il bene dei Kul Tirani... ti chiedo di fare in fretta.', '', 28153),
(153571, 'itIT', 'Vieni. Azeroth stessa ci sta chiamando!', '', 28153),
(153570, 'itIT', 'Ah, avevo dimenticato di averla salvata qui.', 'Ah, avevo dimenticato di averla salvata qui. Spara.', 28153),
(153569, 'itIT', 'Sono troppo vecchio per queste cose. Io me ne vado!', 'Sono troppo vecchia per queste cose. Io me ne vado!', 28153),
(153568, 'itIT', 'Soldato, sarà meglio che ti dia una regolata.', 'Soldato, sarà meglio che ti dia una regolata.', 28153),
(153567, 'itIT', 'Signore... farò del mio meglio, signore.', 'Signore... farò del mio meglio, signore.', 28153),
(153566, 'itIT', 'Soldato James, i tuoi genitori non ti avevano dato abbastanza attenzioni da piccolo? Perché mi stai facendo perdere tempo a seguirti in lungo e in largo?', 'Soldato James, i tuoi genitori non ti avevano dato abbastanza attenzioni da piccolo? Perché mi stai facendo perdere tempo a seguirti in lungo e in largo?', 28153),
(153565, 'itIT', 'Sergente... grazie per essere venuto...', 'Sergente... grazie per essere venuto...', 28153),
(153564, 'itIT', 'Diamoci da fare!', 'Diamoci da fare!', 28153),
(153563, 'itIT', 'È ora di tornare indietro. Sventradraghi vorrà un rapporto completo.', 'È ora di tornare indietro. Sventradraghi vorrà un rapporto completo.', 28153),
(153562, 'itIT', '', 'Gli Spinomanto non sono riusciti a uccidermi e se ne pentiranno amaramente.', 28153),
(153561, 'itIT', '', 'Credo che riarrederò un po\' tutto quando torno. Pensavo a un tema a base di zanne... ma dove potrei mai trovarle?$b$b<Deal digrigna i denti.>', 28153),
(153560, 'itIT', '', 'Mi serve da bere, poi ho una casa da conquistare e ricostruire. Grazie per averli sfoltiti!', 28153),
(153559, 'itIT', 'Non posso rimanere a lungo, devo tornare alla mia fattoria. Il sindaco mi ha detto di congratularmi con te per l\'aiuto che ci hai dato con gli Spinomanto.$b$bOttimo lavoro.', '', 28153),
(153558, 'itIT', 'Ottimo lavoro con quei Verrospino!', '', 28153),
(153557, 'itIT', 'Non posso rimanere a lungo. Dobbiamo riparare quei contadini meccanici per rimediare ai danni che hanno provocato ai campi.$b$bÈ importante però fare una pausa di tanto in tanto.', '', 28153),
(153556, 'itIT', 'Ho lasciato il contadino meccanico in modalità d\'auto-difesa. Se la caverà benissimo.', '', 28153),
(153555, 'itIT', 'Cerca in giro delle spine di Verrospino. Possono essere particolarmente utili e loro stessi le usano come ingredienti nei loro calderoni!', '', 28153),
(153554, 'itIT', 'Orda da nord, Verrospino da ovest. Possiamo ancora fidarci della milizia?', '', 28153),
(153553, 'itIT', 'Spero che Rolf, Mort e Spif siano riusciti a salvarsi.', '', 28153),
(153552, 'itIT', '', 'Le spie mie dicono che nun si può vincere na guerra contro l\'Alleanza senza la flotta nostra.\n\nQuindi... significa che eseguirai ogni singolo compito che ti darò senza esitazione!', 28153),
(153551, 'itIT', '', 'Nun faccio che dire a Zolani e Talanji che il porto è sicuro, ma mi ascoltano? Ovviamente no.$b$bCi sono risse? Baruffe? Certamente, ma nulla di così grave da far preoccupare il Re.', 28153),
(153550, 'itIT', 'Seguimi, per piacere.', 'Seguimi, per piacere.', 28153),
(153549, 'itIT', 'Ho qualcosa da mostrare al nostro campione. Un dono che potrebbe aiutare anche questa terra.', '', 28153),
(153548, 'itIT', 'Riposo, tutti quanti. Questo è Magni Barbabronzea, un tempo Re di Forgiardente e ora Oratore di Azeroth.', '', 28153),
(153547, 'itIT', 'Be\'... Ehm. Questo sì che è nuovo.', '', 28153),
(153546, 'itIT', 'Stregoneria!', '', 28153),
(153545, 'itIT', '', 'Un... Nano di diamante?!?', 28153),
(153544, 'itIT', 'Ora rilascia il potere del cuore!', '', 28153),
(153543, 'itIT', 'Pessime notizie. Sarà meglio fare rapporto al Gran Comandante.', 'Pessime notizie. Sarà meglio fare rapporto al Gran Comandante.', 28153),
(153542, 'itIT', 'Korthek è pazzo! Va fermato!', 'Korthek è pazzo! Va fermato!', 28153),
(153541, 'itIT', 'Qualche tempo dopo, Korthek si stancò della pace. Tradì il sacrificio di Sethraliss e cercò di recuperare le chiavi per scatenare il C\'thrax sui suoi nemici.', 'Qualche tempo dopo, Korthek si stancò della pace. Tradì il sacrificio di Sethraliss e cercò di recuperare le chiavi per scatenare il C\'thrax sui suoi nemici.', 28153),
(153540, 'itIT', 'Il grande saggio Sulthis chiese l\'aiuto mio e di Korthek per erigere una barriera magica che sigillasse il C\'thrax caduto. Giurammo che non avremmo mai permesso a un tale orrore di camminare di nuovo.', 'Il grande saggio Sulthis chiese l\'aiuto mio e di Korthek per erigere una barriera magica che sigillasse il C\'thrax caduto. Giurammo che non avremmo mai permesso a un tale orrore di camminare di nuovo.', 28153),
(153539, 'itIT', 'Il potere scatenato dalla distruzione fu immenso. La nostra terra ne uscì completamente stravolta.', 'Il potere scatenato dalla distruzione fu immenso. La nostra terra ne uscì completamente stravolta.', 28153),
(153538, 'itIT', 'È stato solo grazie all\'intervento della nostra Loa che siamo stati risparmiati. Sethraliss sacrificò se stessa per soggiogare il C\'thrax, ma non prima che riuscisse a distruggere un\'antica piramide che si ergeva al centro di questa terra.', 'È stato solo grazie all\'intervento della nostra Loa che siamo stati risparmiati. Sethraliss sacrificò se stessa per soggiogare il C\'thrax, ma non prima che riuscisse a distruggere un\'antica piramide che si ergeva al centro di questa terra.', 28153),
(153537, 'itIT', 'Molto tempo fa, prima che le sabbie iniziassero a diffondersi, un mostruoso Araldo della Guerra C\'thrax discese sulle nostre terre, massacrando Troll e Sethrak indistintamente.', 'Molto tempo fa, prima che le sabbie iniziassero a diffondersi, un mostruoso Araldo della Guerra C\'thrax discese sulle nostre terre, massacrando Troll e Sethrak indistintamente.', 28153),
(153536, 'itIT', '', 'Dobbiamo tenere gli occhi aperti per l\'Orda. Non fanno che attaccare la piazza.', 28153),
(153535, 'itIT', '', 'Se trovassi qualcosa là fuori che avesse l\'intenzione di invadere il mio villaggio, apprezzerei molto un avvertimento.', 28153),
(153534, 'itIT', '', 'Tutti contano su di me per guidare il villaggio. Non li deluderò!', 28153),
(153533, 'itIT', '', 'Tutti sembrano essere al sicuro... per ora.', 28153),
(153532, 'itIT', 'Questa non è una semplice pietra, è una chiave. Una delle chiavi usate per contenere un grande e terribile potere.', 'Questa non è una semplice pietra, è una chiave. Una delle chiavi usate per contenere un grande e terribile potere.', 28153),
(153531, 'itIT', 'Oh! C\'è una pietra di qualche tipo qui.', 'Oh! C\'è una pietra di qualche tipo qui.', 28153),
(153530, 'itIT', '\"Attenti alla Figlia del Mar.\"', '\"Attenti alla Figlia del Mar.\"', 28153),
(153529, 'itIT', 'Con l\'ultimo fiato egli gridò.', 'Con l\'ultimo fiato egli gridò.', 28153),
(153528, 'itIT', 'Lasciato ad annegar.', 'Lasciato ad annegar.', 28153),
(153527, 'itIT', '', 'Chesto Nano ha promesso di armare il campione in modo che salvi la gente mia. Correrò il rischio.', 28153),
(153526, 'itIT', 'Tradito dal filiale amor.', 'Tradito dal filiale amor.', 28153),
(153525, 'itIT', 'Lei stette lì a guardar.', 'Lei stette lì a guardar.', 28153),
(153524, 'itIT', 'E quando quei selvaggi fronteggiò.', 'E quando quei selvaggi fronteggiò.', 28153),
(153523, 'itIT', 'Orde da affrontar.', 'Orde da affrontar.', 28153),
(153522, 'itIT', 'Ma in quei remoti lidi egli trovò.', 'Ma in quei remoti lidi egli trovò.', 28153),
(153521, 'itIT', 'Di rivederla un dì.', 'Di rivederla un dì.', 28153),
(153520, 'itIT', 'Con l\'unica speranza nel suo cuor.', 'Con l\'unica speranza nel suo cuor.', 28153),
(153519, 'itIT', 'Suppongo che lasceremo che il nostro campione faccia un giro con il re dei diamanti.', '', 28153),
(153518, 'itIT', 'Il padre la seguì.', 'Il padre la seguì.', 28153),
(153517, 'itIT', 'Quand\'ella il grande oceano traversò.', 'Quand\'ella il grande oceano traversò.', 28153),
(153516, 'itIT', 'E adesso cosa sei?', 'E adesso cosa sei?', 28153),
(153515, 'itIT', 'Eri l\'orgoglio del tuo popolo.', 'Eri l\'orgoglio del tuo popolo.', 28153),
(153514, 'itIT', 'Perché l\'hai fatto? Chiederti vorrei.', 'Perché l\'hai fatto? Chiederti vorrei.', 28153),
(153513, 'itIT', 'Perché? Perché, oh tu Figlia del Mar?', 'Perché? Perché, oh tu Figlia del Mar?', 28153),
(153512, 'itIT', 'Perché lei lo tradì.', 'Perché lei lo tradì.', 28153),
(153511, 'itIT', 'E l\'ammiraglio cadde a Theramore.', 'E l\'ammiraglio cadde a Theramore.', 28153),
(153510, 'itIT', 'Nessuno seppellì.', 'Nessuno seppellì.', 28153),
(153509, 'itIT', 'I marinai morti a Kalimdor.', 'I marinai morti a Kalimdor.', 28153),
(153508, 'itIT', 'Poi l\'onda lo ghermì.', 'Poi l\'onda lo ghermì.', 28153),
(153507, 'itIT', 'Nel vento la sua voce risuonar.', 'Nel vento la sua voce risuonar.', 28153),
(153506, 'itIT', '\"Attenti a lei,\" si udì.', '\"Attenti a lei,\" si udì.', 28153),
(153505, 'itIT', '\"Non ti fidar della Figlia del Mar.\"', '\"Non ti fidar della Figlia del Mar.\"', 28153),
(153504, 'itIT', 'Buona giornata, $R.', '', 28153),
(153502, 'itIT', 'Hai qualcosa in tasca?', 'Hai qualcosa in tasca?', 28153),
(153501, 'itIT', 'Io starò qui e mi occuperò delle difese. Grazie ancora, $gamico mio:amica mia;.', 'Io starò qui e mi occuperò delle difese. Grazie ancora, $gamico mio:amica mia;.', 28153),
(153500, 'itIT', '', '', 28153),
(153499, 'itIT', '', 'Servitori! ACCIDETE!', 28153),
(153498, 'itIT', 'Non sarei qui se non fosse stato per te e il sergente. Grazie ancora.', 'Non sarei qui se non fosse stato per te e il sergente. Grazie ancora.', 28153),
(153497, 'itIT', '', 'Informerò Zul. Deciderà lui se sei meritevole di incontrare Rastakhan.', 28153),
(153496, 'itIT', 'Accideteli, prima che passino oltre!', '', 28153),
(153495, 'itIT', 'Nun ci fermeremo fin quando nun avremo raggiunto il porto. Dimmi quando vuoi iniziare.', '', 28153),
(153494, 'itIT', 'Ma che vuoi schiattare?', '', 28153),
(153493, 'itIT', 'Ehi, nun farci scoprire.', '', 28153),
(153492, 'itIT', 'Stai cercando di farci ammazzare?', '', 28153),
(153491, 'itIT', 'Ehi! Nun scappare!', '', 28153),
(153490, 'itIT', 'Torna accà, cumpà!', '', 28153),
(153489, 'itIT', 'È $n, sia ringraziata la Luce! Io andrò al tempio. Qui non è sicuro.', '', 28153),
(153488, 'itIT', 'E prega di non dover mai scegliere tra le due.', '', 28153),
(153487, 'itIT', 'Fai in modo di capire la differenza fra lealtà e onore.', '', 28153),
(153486, 'itIT', 'Cosa vuoi dire?', 'Cosa vuoi dire?', 28153),
(153485, 'itIT', 'Dopo tutto quello che ha fatto, non tornerò mai nella sua Orda.', '', 28153),
(153484, 'itIT', 'Credi di essere qui per riportarmi a Orgrimmar, nelle braccia della Capoguerra, ma ti sbagli.', '', 28153),
(153483, 'itIT', 'È ora di colpire al cuore la S.P.R. & Co.!', '', 28153),
(153482, 'itIT', 'Dimmi solo quando.', '', 28153),
(153477, 'itIT', '', 'Nun schiattare ancora. Teniamo molte cose da fare.', 28153),
(153476, 'itIT', '', 'Nun danzare con Bwonsamdi.', 28153),
(153475, 'itIT', '', 'Cammina.', 28153),
(153474, 'itIT', '', 'Alzati. Nun abbiamo ancora finito.', 28153),
(153473, 'itIT', '', 'Il Loa mio nun ti abbandonerà.', 28153),
(153472, 'itIT', 'Pare che le nostre informazioni fossero errate. Non tutti i Sethrak sono malvagi.', 'Pare che le nostre informazioni fossero errate. Non tutti i Sethrak sono malvagi.', 28153),
(153471, 'itIT', 'Se vuoi inizio a farlo anch\'io!', 'Se vuoi inizio a farlo anch\'io!', 28153),
(153470, 'itIT', '', 'Il nuovo impero dei Troll è giunto. Il tempo nostro è arrivato!', 28153),
(153469, 'itIT', '', 'Zul aveva predetto chesto giorno. Sorgete, discepoli del sangue. Preparatevi per la nuova era di chesto mondo!', 28153),
(153468, 'itIT', 'No! No...', 'No! No...', 28153),
(153467, 'itIT', 'Come osi rubare la mia parte...', 'Come osi rubare la mia parte...', 28153),
(153466, 'itIT', 'Un giorno la pagherai...', 'Un giorno la pagherai...', 28153),
(153465, 'itIT', 'Eroi, seguitemi!', '', 28153),
(153464, 'itIT', 'Ti... prenderò...', 'Ti... prenderò...', 28153),
(153463, 'itIT', 'Siete morti! Tutti morti!', 'Siete morti! Tutti morti!', 28153),
(153462, 'itIT', 'Credete di poter rubare così la mia parte?', 'Credete di poter rubare così la mia parte?', 28153),
(153461, 'itIT', 'Traditori! Avrò le vostre teste!', 'Traditori! Avrò le vostre teste!', 28153),
(153460, 'itIT', 'Traditori! Tutti quanti!', 'Traditori! Tutti quanti!', 28153),
(153459, 'itIT', 'Capitano Eudora... guidaci alla vittoria...', '', 28153),
(153458, 'itIT', 'Carne fresca? Ratti di sentina! È ora di mangiare!', '', 28153),
(153457, 'itIT', 'Oggi persino I grandi Loa udiranno le grida di battaglia e il clangore delle armi tue! E i caduti si uniranno a loro... nell\'Aldilà!', '', 28153),
(153456, 'itIT', 'Concedile na morte onorevole...', '', 28153),
(153455, 'itIT', 'Concedigli na morte onorevole...', '', 28153),
(153454, 'itIT', 'Ahhh!', '', 28153),
(153453, 'itIT', 'Nell\'Aldilà...', '', 28153),
(153452, 'itIT', 'Nun tenevi la benedizione dei Loa oggi.', '', 28153),
(153451, 'itIT', 'Per Zandalar!', '', 28153),
(153450, 'itIT', 'Venduta! Una Spada Cromatica per 281 monete d\'oro! Di certo nessuno potrà fare a meno di notarti.', '', 28153),
(153449, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:260838|h[Missile a Ricerca]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_RACIAL_ROCKETBARRAGE.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:260838|h[Missile a Ricerca]|h|r!', 28153),
(153448, 'itIT', 'Questo è un buon giorno per Kul Tiras!', '', 28153),
(153447, 'itIT', 'Oggi il terreno sarà cosparso di nasi e di orecchie.', '', 28153),
(153446, 'itIT', 'Non è detta l\'ultima parola.', '', 28153),
(153445, 'itIT', 'Silenzio, ora! Il combattimento non è ancora finito!', '', 28153),
(153444, 'itIT', 'Presto scorrerà il sangue! Abbiate pazienza.', '', 28153),
(153443, 'itIT', 'Venduto! Un Ricordo Infestato per 18 monete d\'oro! Onestamente, non pagherei neanche una moneta di rame per questo, ma i soldi non sono i miei!', '', 28153),
(153442, 'itIT', 'No, no, no. Bel salvataggio.', '', 28153),
(153441, 'itIT', 'Muori... ma non come uno di noi.', '', 28153),
(153440, 'itIT', 'Oh, acciderbolina!', '', 28153),
(153439, 'itIT', 'Questa è una buona notte per Kul Tiras!', '', 28153),
(153438, 'itIT', 'Non sarà uno scontro molto tranquillo, quindi mantenete le distanze. Siete pronti?', '', 28153),
(153437, 'itIT', 'Solo l\'ultimo a sopravvivere avrà questo onore.', '', 28153),
(153436, 'itIT', 'Amici! Siamo qui riuniti oggi per vedere quale di questi ladri, di questi delinquenti, di questi farabutti potrà finalmente dirsi degno di Kul Tiras!', '', 28153),
(153435, 'itIT', 'Venduto! Un Grande Razzo dell\'Amore alla giovane ragazza per 1.412 monete d\'oro! Di certo ora sarà sulla bocca di tutti al villaggio!', '', 28153),
(153434, 'itIT', 'Venduti! Paraspalle dell\'Ardore al giovanotto qui di fronte per 756 monete d\'oro! Non sembra tu possa indossarli, ma fa niente!', '', 28153),
(153433, 'itIT', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Azerokk sta lanciando |cFFFF0000|Hspell:257597|h[Infusione d\'Azerite]|h|r!', '|TINTERFACE\\ICONS\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t Azerokk sta lanciando |cFFFF0000|Hspell:257597|h[Infusione d\'Azerite]|h|r!', 28153),
(153432, 'itIT', 'Traditrice! Pigliatela!', '', 28153),
(153431, 'itIT', 'È fondamentale per noi che la chiave rimanga lontano dalle grinfie di Korthek. Vieni, il nostro tempio è poco più avanti.', '', 28153),
(153430, 'itIT', 'L\'ho messa nella tasca di un prigioniero che avevano appena preso. Credo che si chiamasse James.', '', 28153),
(153429, 'itIT', 'Quegli stupidi! Mi hanno catturato e perquisito, ma l\'avevo già nascosta in un luogo che non si sarebbero mai aspettati.', '', 28153),
(153428, 'itIT', 'Ma Korthek ci tradì e Sulthis venne ucciso. Ora Korthek e i suoi seguaci, i Senzafede, mi stanno dando la caccia per mettere le mani sulla mia chiave.', '', 28153),
(153427, 'itIT', 'Molto tempo fa, Korthek, Sulthis e io governavamo uniti e fummo incaricati dal nostro Loa di proteggere le tre chiavi che sigillano un antico e potente male nascosto sotto le sabbie.', '', 28153),
(153426, 'itIT', 'Il nostro tempio è l\'ultima difesa contro i Senzafede.', '', 28153),
(153425, 'itIT', '', 'Sì, sì. Forse teniamo nu microscopico problemino accà. Ma nun è nulla che valga la pena di disturbare il Re.', 28153),
(153424, 'itIT', '', 'Il tempo dei patti coi Loa è finito. L\'era del sangue è giunta!', 28153),
(153423, 'itIT', '', 'Nun ti preoccupare di qualche crimine di poco conto. Teniamo problemi più importanti di cui preoccuparci.', 28153),
(153421, 'itIT', '', 'Spero ti piacciano!', 28153),
(153419, 'itIT', '', 'Ecco qua. Non potevo certo lasciarti andare con senza qualcosa da mangiare, giusto?', 28153),
(153418, 'itIT', '', 'Ahhh, questi sono assolutamente perfetti!', 28153),
(153417, 'itIT', '', 'Solo un attimo, ho qualcosa per te.', 28153),
(153416, 'itIT', 'Ben fatto! L\'Impero degli Zandalari cadrà in ginocchio dopo il colpo che hai inferto!', '', 28153),
(153415, 'itIT', 'Vorrei scegliere Pa\'ku, Signora dei Venti.', 'Vorrei scegliere Pa\'ku, Signora dei Venti.', 28153),
(153414, 'itIT', 'Vorrei scegliere Gonk, Signore del Branco.', 'Vorrei scegliere Gonk, Signore del Branco.', 28153),
(153413, 'itIT', 'Gli Zandalari tengono al guinzaglio una bestia feroce, credendo possa tenerli al sicuro. Dimostra loro che si sbagliano!', '', 28153),
(153412, 'itIT', 'Finalmente, abbiamo riconquistato Stromgarde.', '', 28153),
(153411, 'itIT', 'Muori, feccia!', '', 28153),
(153410, 'itIT', 'Stai al tuo posto.', '', 28153),
(153409, 'itIT', 'Non mancherà a nessuno.', '', 28153),
(153408, 'itIT', 'Un giorno, Stromgarde tonerà nelle mani dell\'Alleanza.', '', 28153),
(153407, 'itIT', 'Fate piovere morte sull\'Orda!', '', 28153),
(153406, 'itIT', 'Terza divisione, fuoco!', '', 28153),
(153405, 'itIT', 'Vorrei cambiare il Loa rappresentato qui da Zuldazar.', 'Vorrei cambiare il Loa rappresentato qui da Zuldazar.', 28153),
(153404, 'itIT', 'Bastioni, scoccare!', '', 28153),
(153403, 'itIT', 'Echi del Passato, sorgete!', '', 28153),
(153402, 'itIT', 'Lo spirito di Arathor vi distruggerà!', '', 28153),
(153401, 'itIT', 'Il male non potrà più nascondersi, nemmeno in queste terre. Ottimo lavoro.', '', 28153),
(153400, 'itIT', 'Sorgete, miei antenati, e proteggete la vostra dimora.', '', 28153),
(153399, 'itIT', 'Ne ho uccisi a migliaia come te. Tu non sei di certo speciale.', '', 28153),
(153398, 'itIT', 'N\'altra vittoria per l\'Impero delli Zandalari! Ben fatto, campione dell\'Orda.', '', 28153),
(153397, 'itIT', 'Un grande male sta infettando questo luogo selvaggio. Fai in modo che venga estirpato!', '', 28153),
(153396, 'itIT', 'Chest\'area è minacciata da una delle creature più potenti della giungla. Trovala e occupatene.', '', 28153),
(153395, 'itIT', 'I giusti vincono sempre.', '', 28153),
(153394, 'itIT', 'Colpevole!', '', 28153),
(153393, 'itIT', 'Il tuo fato è segnato.', '', 28153),
(153392, 'itIT', 'Il giudizio è stato emesso.', '', 28153),
(153391, 'itIT', 'Avremo anche perso Stromgarde, ma l\'Alleanza non cadrà mai.', '', 28153),
(153390, 'itIT', 'Per la forza della Luce!', '', 28153),
(153389, 'itIT', 'Subisci l\'Ira della Luce, verme!', '', 28153),
(153388, 'itIT', 'La Luce vi punirà.', '', 28153),
(153387, 'itIT', 'Un\'altra minaccia sventata e un\'altra vittoria per l\'Alleanza!', '', 28153),
(153386, 'itIT', 'La Luce trionferà!', '', 28153),
(153385, 'itIT', '', 'Sono la prima Storiografa. Il Re mi ha scelta per scolpire la nostra storia nella pietra, e così rimarrà per eoni a venire.', 28153),
(153384, 'itIT', 'Lascia che la Luce ti purifichi!', '', 28153),
(153383, 'itIT', 'La gente mia d\'ora in poi ti chiamerà campione delli Zandalari. Ottimo lavoro!', '', 28153),
(153382, 'itIT', 'Che la Luce ti purifichi!', '', 28153),
(153381, 'itIT', 'Per la Luce!', '', 28153),
(153380, 'itIT', 'Il male si diffonde su questa terra come una malerba. Dobbiamo estirparlo e proteggere le truppe.', '', 28153),
(153379, 'itIT', 'Nun lascerò che la gente mia venga minacciata da chesto nemico. Eliminalo!', '', 28153),
(153378, 'itIT', 'Ora che la via è libera, possiamo raddoppiare i nostri sforzi contro gli Zandalari. Grazie!', '', 28153),
(153377, 'itIT', 'N\'altro nemico caduto nel nome dell\'Impero delli Zandalari.', '', 28153),
(153376, 'itIT', 'Le nostre forze sono minacciate da questa terribile creatura. Eliminala, in nome dell\'Alleanza!', '', 28153),
(153375, 'itIT', 'Nun tollererò chesta minaccia all\'interno dei confini miei! Eliminala.', '', 28153),
(153374, 'itIT', 'Salta sulla moto non appena sei $gpronto:pronta;.', '', 28153),
(153372, 'itIT', '', 'Questi Naga hanno paura. Qualcosa li sta spingendo ad agire, ma non è semplicemente la loro lealtà alla Regina Azshara.', 28153),
(153371, 'itIT', '', 'Salve.', 28153),
(153370, 'itIT', 'Aaah, tutto qui quello che sapete fare? Ahah! Datemi una vera sfida!', '', 28153),
(153369, 'itIT', 'Ehi, è divertente!', '', 28153),
(153368, 'itIT', 'Non lo farai mai più.', '', 28153),
(153367, 'itIT', 'Salutami i tuoi antenati!', '', 28153),
(153366, 'itIT', 'Non la passerete liscia!', '', 28153),
(153365, 'itIT', 'Il segreto sta tutto nel movimento continuo.', '', 28153),
(153364, 'itIT', 'Ahahah! Così si fa!', '', 28153),
(153363, 'itIT', 'Andatevene da lì!', '', 28153),
(153362, 'itIT', 'Per Khaz Modan!', '', 28153),
(153361, 'itIT', 'Ho un regalino per te!', '', 28153),
(153360, 'itIT', 'Eccone uno per te.', '', 28153),
(153359, 'itIT', 'Ehi tu, prendi!', '', 28153),
(153357, 'itIT', 'È giunta la tua ora!', '', 28153),
(153351, 'itIT', 'Magni, cosa vuole darmi Azeroth?', 'Magni, cosa vuole darmi Azeroth?', 28153),
(153350, 'itIT', 'Ora che i gorilla sono sistemati, possiamo concentrare i nostri sforzi contro l\'Orda. Ben fatto.', '', 28153),
(153349, 'itIT', 'Questi gorilla hanno assorbito l\'essenza della kaja\'mite, ottenendo una grande intelligenza. Non possiamo lasciare che escano dalla Gola.', '', 28153),
(153348, 'itIT', 'Esplosione A.T.O.M.I.C.A. rilevata.', 'Esplosione A.T.O.M.I.C.A. rilevata.', 28153),
(153347, 'itIT', 'L\'Orda è caduta davvero in basso se crede di poterci fare prigionieri. Grazie a te, la nostra gente è ora libera. Ben fatto!', '', 28153),
(153346, 'itIT', 'Non posso riposare fintanto che so che uno dei miei è ancora là fuori.', 'Non posso riposare fintanto che so che uno dei miei è ancora là fuori.', 28153),
(153345, 'itIT', 'Non ci sentiranno mai arrivare. Ah! Hai i miei ringraziamenti.', '', 28153),
(153344, 'itIT', 'L\'Orda crede di poterci spiare qui, a Zuldazar... ma si sbaglia di grosso! Metti fine a questa storia, e fai capire loro che l\'Alleanza non vacillerà.', '', 28153),
(153343, 'itIT', 'Non entrerò mai più in uno di quei cosi senza una chiave!', 'Non entrerò mai più in uno di quei cosi senza una chiave!', 28153),
(153342, 'itIT', 'Ancora un minuto in quella cosa e avrei scatenato la mia vendetta!', 'Ancora un minuto in quella cosa e avrei scatenato la mia vendetta!', 28153),
(153341, 'itIT', 'Perché Thurgaden ci ha lasciati in quelle lattine per così tanto tempo? Bah!', 'Perché Thurgaden ci ha lasciati in quelle lattine per così tanto tempo? Bah!', 28153),
(153340, 'itIT', 'Quaggiù era più caldo del sedere infernale di Ragnaros!', 'Quaggiù era più caldo del sedere infernale di Ragnaros!', 28153),
(153339, 'itIT', 'Manderò qualcuno per avvisare Sventradraghi che abbiamo il controllo dell\'area. Grazie per l\'aiuto, $n.', '', 28153),
(153338, 'itIT', 'E tutto in una sola giornata di lavoro!', '', 28153),
(153337, 'itIT', 'È stato dannatamente terrificante!', '', 28153),
(153336, 'itIT', 'Stiamo attingendo potere dalle Terre del Fuoco, ma nulla di pericoloso risponderà alla chiamata.', '', 28153),
(153335, 'itIT', 'Tieni a freno la lingua, Thaelin. Non sono stupido come il Thane-Occultista Thaurissan.', '', 28153),
(153334, 'itIT', 'Attento alla tua evocazione, Thane della Forgia.', '', 28153),
(153333, 'itIT', 'Una gran bella evocazione, ragazzi. Sei tu ad averne il controllo, $n, mostra a quel gruppetto dell\'Orda cosa succede a chi scherza con i Ferroscuro!', '', 28153),
(153332, 'itIT', '$C, piazza un po\' di quelle scorie sul magma instabile e preparati.', '', 28153),
(153331, 'itIT', 'La Battaglia per Stromgarde è iniziata!', '', 28153),
(153330, 'itIT', '30 secondi alla Battaglia per Stromgarde.', '', 28153),
(153329, 'itIT', 'Sì, nessun problema.', '', 28153),
(153328, 'itIT', 'Aspetta, ti sei tenuto la chiave?', '', 28153),
(153327, 'itIT', 'A quanto pare i miei Sciamani sono ancora nelle trivelle. Sapevo di aver dimenticato qualcosa.', '', 28153),
(153326, 'itIT', 'Siamo partiti molto bene. Cosa manca?', '', 28153),
(153325, 'itIT', 'Non hai idea delle forze in gioco qui, giovane.', '', 28153),
(153324, 'itIT', '<Metti dentro la mano e tira fuori qualcosa che sembri più un edificio.>', '<Metti dentro la mano e tira fuori qualcosa che sembri più un edificio.>', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153323, 'itIT', '<Metti dentro la mano e tira fuori qualcosa.>', '<Metti dentro la mano e tira fuori qualcosa.>', 28153),
(153322, 'itIT', '<Un tunnel spaziotemporale si apre davanti a te. A quanto pare dovresti usarlo per costruire un edificio, in qualche modo.>', '', 28153),
(153321, 'itIT', 'Non mettere alla prova la mia pazienza, verme. Muori.', '', 28153),
(153320, 'itIT', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_CTHUN.BLP:20|t %s inizia a lanciare |cFFFF0000|Hspell:264382|h[Raggio Oculare]|h|r!', 'Una proiezione appare in lontananza...', 28153),
(153319, 'itIT', 'Il mare è casa nostra. Ci sta qualcosa là fuori che ci tiene alla larga. Spero davvero tu riesca a fare qualcosa!', '', 28153),
(153318, 'itIT', 'Stai andando a incontrare i Cercatori, vero? È nu gruppo che sa il fatto suo, sarai al sicuro da loro.', '', 28153),
(153317, 'itIT', 'Barche disperse. Tempeste dove mai se n\'erano viste prima. Li altri tengono persino paura di mettersi in mare.', '', 28153),
(153316, 'itIT', 'Voci dicono che stanno accadendo cose strane lungo la costa.', '', 28153),
(153315, 'itIT', 'Come desideri.', '', 28153),
(153314, 'itIT', 'E vi prego... Tenete d\'occhio Jaina.', '', 28153),
(153313, 'itIT', 'Stabilite un quartier generale a Kul Tiras. Il piano non deve fallire.', '', 28153),
(153312, 'itIT', 'Fatti scortare da un vascello della VII Legione.', '', 28153),
(153311, 'itIT', 'Mmm. Come ai vecchi tempi.', '', 28153),
(153310, 'itIT', 'Possano le profondità rinnegarti, come tu hai rinnegato la tua gente.', '', 28153),
(153309, 'itIT', 'Non rappresenti nient\'altro che odio e sofferenza.', '', 28153),
(153308, 'itIT', 'Ascolta il risveglio della tempesta e abbandonati alla fine.', '', 28153),
(153307, 'itIT', 'Non temere, è giunta l\'ora del tuo giudizio.', '', 28153),
(153306, 'itIT', 'Quindi, Genn... Come te la cavi in mare?', '', 28153),
(153305, 'itIT', 'Ascolta le urla della nostra gente e sappi che il tuo momento è giunto.', '', 28153),
(153304, 'itIT', 'Non c\'è alcuna redenzione per te.', '', 28153),
(153303, 'itIT', 'Non eri all\'altezza.', '', 28153),
(153302, 'itIT', 'Che la tua anima soffra in eterno.', '', 28153),
(153301, 'itIT', '', 'Non appena metterò le mani su un\'arma...', 28153),
(153300, 'itIT', '', 'Non sono riusciti a uccidermi. Quello è stato il loro primo errore.', 28153),
(153299, 'itIT', '', 'Hanno distrutto la mia fattoria e osano pure catturarmi. La pagheranno cara!', 28153),
(153298, 'itIT', 'Non me ne andrò fin quando non ci saremo occupati di questa minaccia!', 'Non me ne andrò fin quando non ci saremo occupati di questa minaccia!', 28153),
(153297, 'itIT', 'La pagheranno per ciò che hanno fatto!', 'La pagheranno per ciò che hanno fatto!', 28153),
(153296, 'itIT', 'Devo a quei Verrospino una bella lezione!', 'Devo a quei Verrospino una bella lezione!', 28153),
(153295, 'itIT', '', 'Torna a fare qualche scambio ogni tanto.', 28153),
(153294, 'itIT', '', 'Finalmente libera! Ora mostrerò a quei luridi maiali cosa succede quando si minaccia la mia fattoria!', 28153),
(153293, 'itIT', 'Ehi, guarda chi ha riaperto gli occhi.', '', 28153),
(153292, 'itIT', 'Non ti fidar, non ti fidar... della Figlia del Mar... Mmm... mmm...', '', 28153),
(153291, 'itIT', 'Tieni... Tieni quella cosha lontana da me. Voglio sholo... penshare... a bere! Hic!', 'Tieni... Tieni quella cosha lontana da me. Voglio sholo... penshare... a bere! Hic!', 28153),
(153290, 'itIT', 'Il marito di mia sorella le ha dato uno stelo marino prima di partire per un viaggio di quattro mesi, ma il fiore è appassito dopo soli tre giorni. Era colma di dolore, ma si era preparata al peggio ed è riuscita a occuparsi dei suoi figli con quei pochi soldi che aveva.', 'Il marito di mia sorella le ha dato uno stelo marino prima di partire per un viaggio di quattro mesi, ma il fiore è appassito dopo soli tre giorni. Era colma di dolore, ma si era preparata al peggio ed è riuscita a occuparsi dei suoi figli con quei pochi soldi che aveva.', 28153),
(153289, 'itIT', 'Abbiamo delle cuccette al primo piano e spazio in cantina per custodire il tuo equipaggiamento.\n\nNon è molto, ma è sempre meglio che starsene là fuori con quelle streghe.', 'Abbiamo delle cuccette al primo piano e spazio in cantina per custodire il tuo equipaggiamento.\n\nNon è molto, ma è sempre meglio che starsene là fuori con quelle streghe.', 28153),
(153288, 'itIT', 'Alcuni marinai credono che portino sfortuna, che siano una sfida al destino. Altri vogliono che i loro cari non debbano stare in attesa di brutte notizie. Non biasimo nessuna scelta.', 'Alcuni marinai credono che portino sfortuna, che siano una sfida al destino. Altri vogliono che i loro cari non debbano stare in attesa di brutte notizie. Non biasimo nessuna scelta.', 28153),
(153287, 'itIT', 'Ricorda, fintanto che gli alberi rimarranno in piedi, lo stesso faremo noi. Non possiamo sprecare le nostre vite qui.', '', 28153),
(153286, 'itIT', 'Troviamo altri della nostra razza. Insieme, potremmo riuscire a guarire parte di ciò che sta affliggendo Drustvar.', '', 28153),
(153285, 'itIT', '', 'Ma...', 28153),
(153284, 'itIT', 'Abbiamo recuperato tutte le cose più importanti dal bosco. Se i Fungariani non avessero attaccato, la corruzione ci avrebbe raggiunti da sud.', '', 28153),
(153283, 'itIT', '', 'Andare? Andare dove? Legnosecco è la nostra casa, Morwin, ed è ricoperta di spore. Non possiamo abbandonarla!', 28153),
(153282, 'itIT', 'Ben fatto, Amalie. Ora credo che dovremmo andare.', '', 28153),
(153278, 'itIT', 'Cosa sai dirmi di questo stelo marino?', 'Cosa sai dirmi di questo stelo marino?', 28153),
(153277, 'itIT', 'Tambureggiamento', 'Tambureggiamento', 28153),
(153276, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso Zuldazar.', '|cFF0000FF(Missione)|r Fai rotta verso Zuldazar.', 28153),
(153275, 'itIT', 'Le forze stanno tornando!', '', 28153),
(153274, 'itIT', 'Le cose qui erano tranquille. Poi c\'è stata una tempesta e gli altri Cercatori hanno smesso di tornare. Cosa succede là fuori?', '', 28153),
(153273, 'itIT', 'I miei più sentiti ringraziamenti, vi meritate una frazione dei miei possedimenti personali per il disturbo. Ora devo andare, ossequi!', '', 28153),
(153272, 'itIT', 'A quanto pare sono incorso in una brutta seccatura. Siate gentili e datemi una mano.', '', 28153),
(153271, 'itIT', 'Oh, grazie, siete davvero gentili. Ecco qualcosa per il disturbo. Ora, aria!', 'Oh, grazie, siete davvero gentili. Ecco qualcosa per il disturbo. Ora, aria!', 28153),
(153270, 'itIT', '', 'Ehi voi! Dovete aiutarmi a uscire di qui! Sono tutta sola e disperata, sapete?', 28153),
(153269, 'itIT', 'Oh, sapete che non mi piace dare via la mia Azerite, ma eccone una parte per ringraziarvi. Ora fuori dai piedi.', '', 28153),
(153268, 'itIT', 'Ehi amici, vi andrebbe di aiutarmi con quest\'impiccio?', '', 28153),
(153267, 'itIT', 'Guarda, è solo un costume! Vedi? Toccalo!$b$bOra puoi dire agli altri di lasciarmi uscire da qui? Era solo uno scherzo! Boccalarga non stava davvero terrorizzando Roccavento!', 'Guarda, è solo un costume! Vedi? Toccalo!$b$bOra puoi dire agli altri di lasciarmi uscire da qui? Era solo uno scherzo! Boccalarga non stava davvero terrorizzando Roccavento!', 28153),
(153266, 'itIT', '', 'Grazie! Immagino vogliate un po\' della mia Azerite. Mi pare giusto.', 28153),
(153265, 'itIT', '', 'Ehilà! Credete di potermi aiutare a uscire di qui?', 28153),
(153264, 'itIT', '', 'Immagino di essermelo meritato.', 28153),
(153263, 'itIT', '', 'Pagherò ciò che devo...', 28153),
(153262, 'itIT', 'È... È tornata per finirci!', '', 28153),
(153261, 'itIT', 'Assassina!', 'Assassina!', 28153),
(153260, 'itIT', 'Traditrice!', 'Traditrice!', 28153),
(153259, 'itIT', 'È la figlia del mare!', '', 28153),
(153258, 'itIT', '', 'Dama Jaina... è davvero lei?', 28153),
(153257, 'itIT', '', 'Su, torniamo a casa. Subito!', 28153),
(153256, 'itIT', 'Mamma, chi è quella signora?', 'Mamma, chi è quella signora?', 28153),
(153255, 'itIT', 'Don Cosciotto... cosa ti hanno fatto...', '', 28153),
(153254, 'itIT', 'La mia testa... cos\'è successo ai miei maiali?', '', 28153),
(153253, 'itIT', 'Un giorno racconterò storie sulla tua grande vittoria, ma prima... vedi di vincere!', '', 28153),
(153252, 'itIT', 'Stai per ritornare alla Foresta Cremisi!', 'Stai per ritornare alla Foresta Cremisi!', 28153),
(153250, 'itIT', 'Tenete lontani quei civili! Formate un perimetro!', '', 28153),
(153249, 'itIT', '%s fugge.', '%s fugge.', 28153),
(153248, 'itIT', '', 'E ora mi vedono come una criminale.', 28153),
(153247, 'itIT', '', 'Vedo che la guardia cittadina è disciplinata come sempre. Mio padre ne era così orgoglioso.', 28153),
(153246, 'itIT', 'Non farmi fretta! Sto cercando di salvare il tuo maestro!', '', 28153),
(153245, 'itIT', 'Ehi, $n! Vieni qui!', 'Ehi, $n! Vieni qui!', 28153),
(153244, 'itIT', 'La solita fortuna mia! Ero in viaggio verso Dol\'watha quando la bestia mia si è ammalata. È proprio vero chello che dicono, piove sempre sul bagnato.', '', 28153),
(153243, 'itIT', 'Adunata!', 'Adunata!', 28153),
(153242, 'itIT', 'C\'è un sacco di sangue dell\'Orda da versare là fuori. Lasciane un po\' anche a me, va bene?', 'C\'è un sacco di sangue dell\'Orda da versare là fuori. Lasciane un po\' anche a me, va bene?', 28153),
(153241, 'itIT', 'Facciamo in modo che soffra.', 'Facciamo in modo che soffra.', 28153),
(153240, 'itIT', 'Abbiamo l\'ordine di uccidere il prigioniero.', 'Abbiamo l\'ordine di uccidere il prigioniero.', 28153),
(153239, 'itIT', '', 'Rimani nei paraggi, non voglio rischiare che ci scoprano.', 28153),
(153238, 'itIT', '', 'Mantieni la concentrazione.', 28153),
(153237, 'itIT', '', 'Stai cercando di attirare l\'attenzione su di noi?', 28153),
(153236, 'itIT', 'Ehi, Boris... Credo che i tuoi giorni da ladruncolo siano finiti...', '', 28153),
(153235, 'itIT', 'Tieni le mani lontane dalla mia bestia!', '', 28153),
(153234, 'itIT', 'Ora sì che si ragiona. Guarda tutta quest\'Azerite!', '', 28153),
(153233, 'itIT', 'Capo! Sei qui!', '', 28153),
(153231, 'itIT', 'Fate largo! Abbiamo dei pericolosi prigionieri!', '', 28153),
(153230, 'itIT', 'Alt! Dichiarate le vostre intenzioni!', '', 28153),
(153229, 'itIT', '', 'Non è il momento di perdere tempo.', 28153),
(153228, 'itIT', 'Chiudi la b-bocca.', '', 28153),
(153227, 'itIT', 'Ohhh... forse è stata una STREGA!', '', 28153),
(153226, 'itIT', 'Un altro dei tuoi esploratori, Gallywix... e questo è pure morto.', '', 28153),
(153225, 'itIT', 'Dobbiamo far breccia nel cuore della città per evacuare i cittadini rimasti!', '', 28153),
(153224, 'itIT', 'A-attenzione...', '', 28153),
(153223, 'itIT', '', 'Ci siamo quasi! Fate in fretta, eroi!', 28153),
(153222, 'itIT', '', 'Muovetevi!', 28153),
(153220, 'itIT', 'Campioni, con me! Ci raduneremo nella fortezza! La vostra Capoguerra ve lo ordina!', '', 28153),
(153217, 'itIT', '', 'Faucisaure, dove sei stato?', 28153),
(153216, 'itIT', 'Fai attenzione, i Campi Crollati sono ancora pericolosi! La via a destra dovrebbe essere un po\' più sicura e portarti direttamente al mulino. La fattoria di Deal è poco oltre.', '', 28153),
(153215, 'itIT', '', 'Se ti va di combattere, mi farebbe comodo un po\' di aiuto.', 28153),
(153214, 'itIT', '', 'Ho finito tutte le pozioni e ci sono una valanga di Sethrak tra me e la carovana.', 28153),
(153213, 'itIT', '', 'Tutto bene là dentro? Te la cavi con quell\'arma?', 28153),
(153212, 'itIT', '', 'Non oggi, uomini serpente!', 28153),
(153211, 'itIT', 'Riportami all\'entrata.', 'Riportami all\'entrata.', 28153),
(153210, 'itIT', '<L\'Avatar di Sethraliss è rinato grazie agli sforzi tuoi e dei tuoi alleati.>', '<L\'Avatar di Sethraliss è rinato grazie agli sforzi tuoi e dei tuoi alleati.>', 28153),
(153209, 'itIT', 'Magni, riportami a Zandalar.', 'Magni, riportami a Zandalar.', 28153),
(153207, 'itIT', 'Ah, questa può portarci dove dobbiamo andare! Vieni, campione.', '', 28153),
(153206, 'itIT', 'Sconfiggi qualsiasi intruso rimasto.', 'Sconfiggi qualsiasi intruso rimasto.', 28153),
(153205, 'itIT', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t L\'Avatar si unisce a te, fornendoti |cFFFF0000|Hspell:269670|h[Potenziamento]|h|r per terminare il combattimento!', '|TInterface\\Icons\\SPELL_NATURE_REGENERATION_02.BLP:20|t L\'Avatar si unisce a te, fornendoti |cFFFF0000|Hspell:269670|h[Potenziamento]|h|r per terminare il combattimento!', 28153),
(153204, 'itIT', '<Vedi l\'Avatar di Sethraliss davanti a te. Anche se ancora in vita, è molto indebolito dalle azioni dei Troll. Tutte intorno a te, antiche difese prendono vita...>', '<Vedi l\'Avatar di Sethraliss davanti a te. Anche se ancora in vita, è molto indebolito dalle azioni dei Troll. Tutte intorno a te, antiche difese prendono vita...>', 28153),
(153203, 'itIT', '|cffffff00+$1i Legna|r', '|cffffff00+$1i Legna|r', 28153),
(153202, 'itIT', 'Sentito la principessa? Fuoco a volontà!', '', 28153),
(153201, 'itIT', '', 'Lo scudo! Sta cominciando a svanire!', 28153),
(153199, 'itIT', 'Non abbiate paura! Immagino che la mia entrata sia stata un po\' brusca ma... sono Magni Barbabronzea, e parlo per conto di Azeroth.', '', 28153),
(153198, 'itIT', '', 'Ah, eccoti qua. Vieni, teniamo dei piani da discutere.', 28153),
(153197, 'itIT', 'Ah, eccoti. Devo scambiare due parole con te!', '', 28153),
(153196, 'itIT', '[IGC - Audience with Katherine - Jaina leaves her fate in Katherine\'s hands. Urged by Lady Ashvane to treat Jaina as a traitor, Katherine allows Jaina to be taken away to face justice. \"She is already dead to me.\" Player is arrested.]', '[IGC - Audience with Katherine - Jaina leaves her fate in Katherine\'s hands. Urged by Lady Ashvane to treat Jaina as a traitor, Katherine allows Jaina to be taken away to face justice. \"She is already dead to me.\"]', 28153),
(153195, 'itIT', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:265212|h[Gestazione]|h|r!', '|TINTERFACE\\ICONS\\SPELL_SHADOW_ABOMINATIONEXPLOSION.BLP:20|t Sei il bersaglio di |cFFFF0000|Hspell:265212|h[Gestazione]|h|r!', 28153),
(153194, 'itIT', 'Ripristineremo le tue forze!', 'Ripristineremo le tue forze!', 28153),
(153193, 'itIT', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Vectis inizia a lanciare |cFFFF0000|Hspell:265217|h[Liquefazione]|h|r!', '|TInterface\\ICONS\\INV_misc_boilingblood.blp:20|t Vectis inizia a lanciare |cFFFF0000|Hspell:265217|h[Liquefazione]|h|r!', 28153),
(153192, 'itIT', 'Non far caso a Gallywix. Stiamo andando a Drustvar per esaminare la posizione del nemico. Il profitto non è la priorità.', '', 28153),
(153191, 'itIT', 'Ora c\'è solo... silenzio.', '', 28153),
(153190, 'itIT', 'Oh, muoio...', '', 28153),
(153189, 'itIT', 'Assicurati che Eitrigg e il capitano siano pronti. Abbiamo un bel po\' di soldi da fare!', '', 28153),
(153188, 'itIT', 'Mi hai... distrutto...', '', 28153),
(153187, 'itIT', 'Da questo momento... non dirò più una parola.', '', 28153),
(153186, 'itIT', 'Fermati, basta così!', '', 28153),
(153185, 'itIT', 'Infame, mi hai ucciso!', '', 28153),
(153184, 'itIT', 'Oh, sono morto!', '', 28153),
(153183, 'itIT', 'Ora il mio spirito vaga. Io... non più.', '', 28153),
(153182, 'itIT', '', 'No. Nun farai più del male alla gente mia. La follia tua sta per finire!', 28153),
(153180, 'itIT', '', 'Tieni ragione, principessa!', 28153),
(153177, 'itIT', 'Tre dispositivi furono creati per sigillare la corruzione.', '', 28153),
(153174, 'itIT', '[Awesome cutscene.]', '[Awesome cutscene.]', 28153),
(153173, 'itIT', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Vectis lancia |cFFFF0000|Hspell:266948|h[Bomba Pestilenziale]|h|r!', '|TInterface\\ICONS\\artifactability_BloodDeathknight_UmbilicusEternus.blp:20|t Vectis lancia |cFFFF0000|Hspell:266948|h[Bomba Pestilenziale]|h|r!', 28153),
(153172, 'itIT', '', 'Nu Dio Antico? È per chesto che i Troll del Sangue hanno attaccato la mia città...', 28153),
(153171, 'itIT', 'Dati recuperati. Corruzione del Dio Antico contenuta a Nazmir. ', '', 28153),
(153169, 'itIT', 'E un bel gallone di tequila!', 'E un bel gallone di tequila!', 28153),
(153168, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso Drustvar.', '|cFF0000FF(Missione)|r Fai rotta verso Drustvar.', 28153),
(153167, 'itIT', '', 'La Lamento della Banshee è una delle navi migliori della Dama Oscura. Potrebbe non sembrarlo a prima vista, ma è solida e resistente.\n\nAnche il suo capitano non se la cava male.', 28153),
(153166, 'itIT', 'Sì, sono pronto ad andare a Drustvar.', 'Sì, sono pronta ad andare a Drustvar.', 28153),
(153165, 'itIT', 'Non lasciarti ingannare da quel Goblin, $n. Il nostro compito è anche raccogliere INFORMAZIONI sull\'Alleanza, non solo recuperare quanta più Azerite possibile.\n\nSei $gpronto:pronta; ad andare?', '', 28153),
(153164, 'itIT', 'Non lasciatevi distrarre dal Principe del Commercio. Il nostro obiettivo principale è fare ricognizione, non profitto.', '', 28153),
(153163, 'itIT', 'Ho sentito dire che c\'è un sacco d\'Azerite là fuori che ci sta aspettando. Tutto ciò che dobbiamo fare è prenderla, e spetta a te farlo.\n\nSe finiranno con l\'ucciderti, ho già prenotato il tuo cappello! Ahah!', '', 28153),
(153162, 'itIT', 'Continua a rigenerare l\'Avatar di Sethraliss mentre ti occupi degli altri intrusi.', 'Continua a rigenerare l\'Avatar di Sethraliss mentre ti occupi degli altri intrusi.', 28153),
(153161, 'itIT', 'Ben fatto. Dobbiamo rimanere vigili e tenere il tempio libero da quei ragni.', '', 28153),
(153160, 'itIT', 'I ragni Tessigiungla stanno infestando le rovine del tempio. Ripulisci l\'infestazione e salva i miei seguaci intrappolati nei bozzoli.', '', 28153),
(153159, 'itIT', 'Riporta l\'avatar al massimo della salute.', 'Riporta l\'avatar al massimo della salute.', 28153),
(153158, 'itIT', 'Dannati ragni!', '', 28153),
(153157, 'itIT', 'Grazie, $n! Ti devo la mia vita.', '', 28153),
(153156, 'itIT', 'Riesco di nuovo a respirare! Grazie!', '', 28153),
(153155, 'itIT', 'Questi ragni si mangerebbero tutto!', '', 28153),
(153154, 'itIT', 'Grazie! C\'è mancato poco...', '', 28153),
(153153, 'itIT', 'Credevo di essere spacciato!', '', 28153),
(153152, 'itIT', 'Cosa vuoi da noi?', 'Cosa vuoi da noi?', 28153),
(153151, 'itIT', 'No, ti prego...', 'No, ti prego...', 28153),
(153150, 'itIT', '', 'Allora in sella! Noi andremo alla ricerca del Maestro Ashton. Ci rivedremo nella Foresta Cremisi!', 28153),
(153149, 'itIT', 'Le mie ossa! Che dolore!', 'Le mie ossa! Che dolore!', 28153),
(153148, 'itIT', 'Oh, come ho fatto a perdermelo.', 'Oh, come ho fatto a perdermelo.', 28153),
(153147, 'itIT', 'Mi annoi. Rendiamoti più... interessante.', 'Mi annoi. Rendiamoti più... interessante.', 28153),
(153146, 'itIT', 'Dimmi, ti fa male?', 'Dimmi, ti fa male?', 28153),
(153145, 'itIT', 'Credo di sì.', '', 28153),
(153144, 'itIT', '', 'Marten, pensi di farcela a metterti in viaggio?', 28153),
(153143, 'itIT', 'Il villaggio è in buone mani. Ora, mi spieghi cosa sta succedendo?', '', 28153),
(153142, 'itIT', 'Naturalmente! Non ho idea del perché avresti bisogno del mio aiuto, ma in quanto $gsalvatore:salvatrice; della mia terra, lo avrai!\n\nDovrai aspettare un po\', però. Di certo la città sarà allo sfascio.', '', 28153),
(153141, 'itIT', 'Dobbiamo andarcene da qui!', 'Dobbiamo andarcene da qui!', 28153),
(153140, 'itIT', 'Oh no, ancora loro!', 'Oh no, ancora loro!', 28153),
(153139, 'itIT', 'Sarei morto se non fosse stato per te...', 'Sarei morta se non era per te...', 28153),
(153138, 'itIT', 'L\'Orda! Che cosa ci fanno qui?', 'L\'Orda! Cosa ci fanno qui?', 28153),
(153137, 'itIT', 'Leviamo le ancore, comandante!', 'Leviamo le ancore, comandante!', 28153),
(153136, 'itIT', 'Posso farti arrivare lì più veloce di un gabbiano. Fammi solo sapere quando $gsei pronto:sei pronta;.', '', 28153),
(153135, 'itIT', 'State cercando Ashton? Venite con me. Non l\'ho incontrato recentemente ma... ho visto il suo apprendista.', '', 28153),
(153134, 'itIT', 'Fiuuu. Queste non sono adatte ai deboli di cuore... o di stomaco.', '', 28153),
(153133, 'itIT', 'Una volta ho sentito parlare di un gustoso piatto tipico del deserto oltre il mare. Portami delle ali di condor e pungiglioni di scorpide. Voglio provarne una nuova variante, con un po\' più di mordente.', '', 28153),
(153132, 'itIT', 'Alla via così, timoniere.', 'Alla via così, timoniere.', 28153),
(153131, 'itIT', 'No, idiota, DALL\'ALTRA PARTE!', 'No, idiota! DALL\'ALTRA PARTE!', 28153),
(153130, 'itIT', 'GLI IMPURI NON POSSONO ENTRARE NELLE SALE DEI MORTI.', '', 28153),
(153129, 'itIT', 'NON PUOI PROCEDERE.', '', 28153),
(153128, 'itIT', 'NESSUNO PUÒ PASSARE.', '', 28153),
(153127, 'itIT', 'Ci si vede.', '', 28153),
(153126, 'itIT', 'Ehi.', '', 28153),
(153125, 'itIT', '', 'Ho fallito come insegnante.', 28153),
(153124, 'itIT', '', 'È ora dell\'intervallo.', 28153),
(153123, 'itIT', '', 'La lezione... è finita.', 28153),
(153122, 'itIT', '', 'La lezione ha inizio!', 28153),
(153121, 'itIT', '', 'Vi insegnerò la legge delle tre R: rune, rituali e reliquie!', 28153),
(153120, 'itIT', '', 'Ti darò una lezione!', 28153),
(153119, 'itIT', 'Chi si occuperà di tenere d\'occhio le riserve, ora?', '', 28153),
(153118, 'itIT', 'Questa partita... è rovinata.', '', 28153),
(153117, 'itIT', 'Non devi toccare le nostre scorte!', '', 28153),
(153116, 'itIT', 'Questa collezione è solo per gli ospiti!', '', 28153),
(153115, 'itIT', 'Eccellente! Questi dureranno per un bel po\'... a patto che non me li mangi tutti in una volta, ovviamente.', '', 28153),
(153114, 'itIT', 'Non hai idea di cos\'è capace la natura per sopravvivere, qui. Le Piante Sferzanti hanno i semi più gustosi e resistenti che io conosca! Recuperane un po\', ma fai attenzione alle spine!', '', 28153),
(153113, 'itIT', 'Mi piace il tuo modo di pensare, Walt.', '', 28153),
(153112, 'itIT', 'Oppure... perché non gli diciamo che ci hanno attaccati e ci beviamo tutto l\'idromele? Tanto siamo già stati pagati!', '', 28153),
(153111, 'itIT', 'Va bene, credo sia sicuro ora. Portiamo questi barili a Hatherford.', '', 28153),
(153110, 'itIT', 'Andrò a caccia di indizi su James mentre tu penserai a richiamare la nave. Non lascerò che rimanga tra le grinfie di quei viscidi bastardi.', 'Andrò a caccia di indizi su James mentre tu penserai a richiamare la nave. Non lascerò che rimanga tra le grinfie di quei viscidi bastardi.', 28153),
(153109, 'itIT', 'Quella cosa sta colando di miele!', '', 28153),
(153108, 'itIT', 'Vieni qui, stupido gabbiano!', '', 28153),
(153107, 'itIT', 'Be\', non sono mai stato più pronto! Facci vedere cosa sai fare, natura!', '', 28153),
(153106, 'itIT', 'Diamoci da fare!', 'Diamoci da fare!', 28153),
(153105, 'itIT', 'Altre bestie feroci saranno qui a momenti, $C. Proteggi l\'idromele come se la tua vita ne dipendesse!', '', 28153),
(153103, 'itIT', 'Coraggio, Bradford! Non possiamo lasciare che abbiano la meglio!', '', 28153),
(153102, 'itIT', 'Va bene, Walt, questa è la fine. Non so a quante altre di queste bestie riusciremo a resistere!', '', 28153),
(153101, 'itIT', '%s punta un cannone d\'Azerite carico contro la torre d\'assedio.', '', 28153),
(153100, 'itIT', '$n! Abbiamo bisogno di te, subito!', '$n! Abbiamo bisogno di te, subito!', 28153),
(153099, 'itIT', 'Dannazione, Leonard, non ti avevo dato il permesso di andartene!', 'Dannazione, Leonard, non ti avevo dato il permesso di andartene!', 28153),
(153098, 'itIT', 'Voi altri seguitemi, li aggireremo dai fianchi.', 'Voi altri seguitemi, li aggireremo dai fianchi.', 28153),
(153097, 'itIT', 'Affascinante. Delle viaggiatrici davvero notevoli. Mi chiedo che tipo di storie sapranno raccontarci.', '', 28153),
(153096, 'itIT', 'Normalmente, le fluttuole vivono soltanto qualche mese, ma gli esemplari di questo posto sono diversi. Portamene qualcuna, ma sii gentile. Sono molto delicate.', '', 28153),
(153093, 'itIT', '', 'Chi veglierà sulla terra, ora?', 28153),
(153092, 'itIT', '', 'Ritorno alla terra.', 28153),
(153091, 'itIT', '', 'Sarete ottimo fertilizzante.', 28153),
(153090, 'itIT', '', 'Si raccoglie ciò che si semina!', 28153),
(153089, 'itIT', '', 'Intrusi nel mio giardino!', 28153),
(153088, 'itIT', '', 'Fatti a pezzi.', 28153),
(153087, 'itIT', '', 'I miei piani... in fumo.', 28153),
(153086, 'itIT', '', 'La mia trama vi condurrà alla rovina!', 28153),
(153085, 'itIT', '', 'La tua fine si avvicina!', 28153),
(153084, 'itIT', '', 'Cucirò le vostre anime alla mia tappezzeria!', 28153),
(153083, 'itIT', 'È bello concludere con una buona caccia.', '', 28153),
(153082, 'itIT', 'Quanta ferocia.', '', 28153),
(153081, 'itIT', 'Non avrei mai pensato... di diventare il trofeo.', '', 28153),
(153080, 'itIT', 'È ora di colpire!', '', 28153),
(153079, 'itIT', 'Sarete degli ottimi trofei sul mio muro!', '', 28153),
(153078, 'itIT', 'La caccia è aperta!', '', 28153),
(153077, 'itIT', 'Carne fresca da grigliare!', '', 28153),
(153076, 'itIT', 'La cena è servita!', '', 28153),
(153075, 'itIT', 'Il santuario deve essere aperto un\'altra volta. La nostra redenzione è giunta!', '', 28153),
(153074, 'itIT', 'Quest\'oscurità non ci sbarrerà la strada.', '', 28153),
(153073, 'itIT', 'Ottimo lavoro. Non dimenticheremo mai i coraggiosi scarafaggi che hanno sacrificato con coraggio le proprie vite per salvarci da Re Rakataka!', '', 28153),
(153072, 'itIT', 'La mia gente uccide per molto meno.', '', 28153),
(153071, 'itIT', 'La disciplina e il tatto non ti appartengono, a quanto pare.', '', 28153),
(153070, 'itIT', 'Ogni cosa ha un valore. Persino tu.', '', 28153),
(153069, 'itIT', 'Le sabbie puniranno chi spreca.', '', 28153),
(153068, 'itIT', 'Le sabbie ci mostreranno la via.', '', 28153),
(153067, 'itIT', 'Andiamo dove ci portano le sabbie.', '', 28153),
(153066, 'itIT', 'Le dune hanno tutto ciò che ci serve.', '', 28153),
(153065, 'itIT', 'Sopravvivere alle sabbie significa valorizzare ogni cosa.', '', 28153),
(153064, 'itIT', 'Ricorda, ogni cosa ha il suo scopo.', '', 28153),
(153063, 'itIT', 'Parla liberamente.', '', 28153),
(153062, 'itIT', 'Salve.', '', 28153),
(153061, 'itIT', 'Cosa mi hai portato?', '', 28153),
(153060, 'itIT', 'Sei qui per commerciare?', '', 28153),
(153059, 'itIT', 'Ti serve qualcosa?', '', 28153),
(153058, 'itIT', '', 'Zandalar resisterà.', 28153),
(153057, 'itIT', '', 'Statt\' accuort\'.', 28153),
(153056, 'itIT', '', 'Le sabbie sono nu destino che nessuno si merita.', 28153),
(153055, 'itIT', '', 'Cosa posso fare per te?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(153054, 'itIT', '', 'Parla in fretta.', 28153),
(153053, 'itIT', '', 'Sto ascoltando.', 28153),
(153052, 'itIT', '', 'Sì?', 28153),
(153051, 'itIT', 'Non ci arrenderemo mai.', 'Non ci arrenderemo mai.', 28153),
(153050, 'itIT', 'L\'impero dei Senzafede cadrà.', 'L\'impero dei Senzafede cadrà.', 28153),
(153049, 'itIT', 'Che Sethraliss ci salvi tutti.', 'Che Sethraliss ci salvi tutti.', 28153),
(153048, 'itIT', 'Korthek ci ha trascinati in questa guerra.', 'Korthek ci ha trascinati in questa guerra.', 28153),
(153047, 'itIT', 'Dobbiamo rimanere forti.', 'Dobbiamo rimanere forti.', 28153),
(153046, 'itIT', 'Sei qui per aiutare?', 'Sei qui per aiutare?', 28153),
(153045, 'itIT', 'Re Rakataka sta terrorizzando la Gola Tracciaossa! È troppo potente per essere affrontato faccia a faccia, ma ha un appetito insaziabile. Mangerebbe fino a scoppiare!', '', 28153),
(153044, 'itIT', 'La mia gente uccide per molto meno.', 'La mia gente uccide per molto meno.', 28153),
(153043, 'itIT', 'La disciplina e il tatto non ti competono, a quanto pare.', 'La disciplina e il tatto non ti competono, a quanto pare.', 28153),
(153042, 'itIT', 'Ogni cosa ha il suo valore, persino tu.', 'Ogni cosa ha il suo valore, persino tu.', 28153),
(153041, 'itIT', 'Vivi con rapidità e astuzia.', 'Vivi con rapidità e astuzia.', 28153),
(153040, 'itIT', 'Sopravvivere significa sfruttare ogni risorsa.', 'Sopravvivere significa sfruttare ogni risorsa.', 28153),
(153039, 'itIT', 'Ricorda, ogni cosa ha la sua utilità.', 'Ricorda, ogni cosa ha il suo scopo!', 28153),
(153038, 'itIT', 'Le dune hanno tutto ciò che ci serve.', 'Le dune hanno tutto ciò che ci serve.', 28153),
(153037, 'itIT', 'Prenditi cura di te. Nessun altro lo farà.', 'Prenditi cura di te. Nessun altro lo farà.', 28153),
(153036, 'itIT', 'Non morire là fuori.', 'Non morire là fuori.', 28153),
(153035, 'itIT', 'Cosa mi hai portato?', 'Cosa mi hai portato?', 28153),
(153034, 'itIT', 'Ti serve qualcosa?', 'Ti serve qualcosa?', 28153),
(153033, 'itIT', 'Sei qui per commerciare?', 'Sei qui per commerciare?', 28153),
(153032, 'itIT', 'Ehilà!', 'Ehilà!', 28153),
(153031, 'itIT', 'Hai qualcosa per me?', 'Hai qualcosa per me?', 28153),
(153030, 'itIT', 'Portami un ricordino dalla tua prossima avventura!', 'Portami un ricordino dalla tua prossima avventura!', 28153),
(153029, 'itIT', 'Ora siamo amici?', 'Ora siamo amici?', 28153),
(153028, 'itIT', 'Grazie per aver parlato con me.', 'Grazie per aver parlato con me.', 28153),
(153027, 'itIT', 'Stai per lanciarti in una grossa avventura? Ma è fantastico!', 'Stai per lanciarti in una grossa avventura? Ma è fantastico!', 28153),
(153026, 'itIT', 'Hai mai mangiato della sabbia di proposito?', 'Hai mai mangiato della sabbia di proposito?', 28153),
(153025, 'itIT', 'Se tu dovessi morire, posso avere la tua roba?', 'Se tu dovessi morire, posso avere la tua roba?', 28153),
(153024, 'itIT', 'Non ci arrenderemo mai.', '', 28153),
(153023, 'itIT', 'L\'impero dei Senzafede cadrà.', '', 28153),
(153022, 'itIT', 'Che Sethraliss ci salvi tutti.', '', 28153),
(153021, 'itIT', 'Korthek ci ha trascinati in questa guerra.', '', 28153),
(153020, 'itIT', 'Dobbiamo essere forti.', '', 28153),
(153019, 'itIT', 'Sei qui per aiutare?', '', 28153),
(153018, 'itIT', 'Facciamo ciò che dobbiamo.', '', 28153),
(153017, 'itIT', 'Sethraliss ci salverà.', '', 28153),
(153016, 'itIT', 'I Senzafede non conquisteranno il nostro tempio.', '', 28153),
(153015, 'itIT', 'Korthek ci ha trascinati in questa guerra.', '', 28153),
(153014, 'itIT', 'Dobbiamo essere forti.', '', 28153),
(153013, 'itIT', 'Sei qui per aiutare?', '', 28153),
(153012, 'itIT', '', 'Non avremmo mai dovuto salvarti. Oh! Aspetta! Non volevo...', 28153),
(153011, 'itIT', '', 'Non l\'hai fatto di nuovo... vero?', 28153),
(153010, 'itIT', '', 'Forse dovresti smetterla.', 28153),
(153009, 'itIT', '', 'Eheh. Che cosa stai facendo?', 28153),
(153008, 'itIT', '', 'Eheheh! Tornerai, vero?', 28153),
(153007, 'itIT', '', 'Ehi, non morire là fuori!', 28153),
(153006, 'itIT', '', 'Non è mai sicuro viaggiare da soli.', 28153),
(153005, 'itIT', '', 'Piaci a Dolly. Te lo dico io!', 28153),
(153004, 'itIT', '', 'Conosco queste dune meglio di chiunque altro.', 28153),
(153003, 'itIT', '', 'Oh! Salve!', 28153),
(153002, 'itIT', '', 'Posso aiutare!', 28153),
(153001, 'itIT', '', 'La città nun cadrà.', 28153),
(153000, 'itIT', '', 'Sta\' sempre accuort\'.', 28153),
(152999, 'itIT', '', 'Ho giurato di difendere la famiglia reale.', 28153),
(152998, 'itIT', '', 'Noi resisteremo.', 28153),
(152997, 'itIT', '', 'Parla rapidamente.', 28153),
(152996, 'itIT', '', 'Sì?', 28153),
(152995, 'itIT', '', 'Sto ascoltando.', 28153),
(152994, 'itIT', 'Che le sabbie seppelliscano i peccati miei.', '', 28153),
(152993, 'itIT', 'Le sabbie non saranno mai un luogo sicuro.', '', 28153),
(152992, 'itIT', 'Alcune cose non si possono cancellare.', '', 28153),
(152991, 'itIT', 'Cosa ti serve?', '', 28153),
(152990, 'itIT', 'Se posso aiutare, lo farò.', '', 28153),
(152989, 'itIT', 'Mi merito il destino mio.', '', 28153),
(152988, 'itIT', 'Allontanati finché puoi!', '', 28153),
(152987, 'itIT', 'Ti tengo d\'occhio.', '', 28153),
(152986, 'itIT', 'Guardati le spalle.', '', 28153),
(152985, 'itIT', 'Nun dovresti stare accà.', '', 28153),
(152984, 'itIT', 'Nun tengo tempo per te.', '', 28153),
(152983, 'itIT', 'Cosa vuoi?', '', 28153),
(152982, 'itIT', 'Lasciati guidare dalla tempesta.', '', 28153),
(152981, 'itIT', 'Non temere la tempesta.', '', 28153),
(152980, 'itIT', 'La quiete viene dopo la tempesta.', '', 28153),
(152979, 'itIT', 'La tempesta sta chiamando.', '', 28153),
(152978, 'itIT', 'Tutti sono i benvenuti qui.', '', 28153),
(152977, 'itIT', 'Io sono la tempesta.', '', 28153),
(152976, 'itIT', 'Cosa ti porta qui?', '', 28153),
(152975, 'itIT', 'Il banchetto è iniziato!', '', 28153),
(152973, 'itIT', '', 'Mi farebbe comodo un nuovo elmo...', 28153),
(152972, 'itIT', '', 'Questo mi ricorda un Sethrak che una volta mi aveva infastidito. Una volta.', 28153),
(152971, 'itIT', '', 'Che il tuo passo sia rapido e furioso.', 28153),
(152970, 'itIT', '', 'Vento alle spalle, spada alla mano.', 28153),
(152969, 'itIT', '', 'Fai in modo che ti temano.', 28153),
(152968, 'itIT', '', 'Lasciami qualche Sethrak.', 28153),
(152967, 'itIT', '', 'Mai arrendersi.', 28153),
(152966, 'itIT', '', 'Dimmi, quanti Sethrak hai ucciso?', 28153),
(152965, 'itIT', '', 'Oggi è un buon giorno per combattere. Ogni giorno lo è.', 28153),
(152964, 'itIT', '', 'I Vulpera sono più forti di quel che sembra.', 28153),
(152963, 'itIT', '', 'La nostra gente sarà libera.', 28153),
(152962, 'itIT', '', 'Sono pronta a combattere.', 28153),
(152961, 'itIT', 'La vita mia per il Re.', '', 28153),
(152960, 'itIT', 'Tieni sempre pronte le armi tue.', '', 28153),
(152959, 'itIT', 'Che i Loa siano con te.', '', 28153),
(152958, 'itIT', 'Zandalar resiste.', '', 28153),
(152957, 'itIT', 'Affronterò il pericolo.', '', 28153),
(152956, 'itIT', 'I nemici nostri cadranno.', '', 28153),
(152955, 'itIT', '', 'Oh, so che non lo farete.', 28153),
(152954, 'itIT', 'Noi non ti deluderemo, mia Regina.', '', 28153),
(152953, 'itIT', '', 'Te la senti di farlo?', 28153),
(152952, 'itIT', '', 'Dovrai infiltrarti a Roccavento e liberare un prigioniero politico che potrebbe cambiare il corso della guerra... in nostro favore.', 28153),
(152951, 'itIT', '', 'Il Re moccioso possiede qualcosa che non gli appartiene e io lo rivoglio indietro.', 28153),
(152950, 'itIT', '', 'Per vincere questa guerra, l\'Orda ha bisogno di alleati.', 28153),
(152949, 'itIT', '', 'Ma conosco molto bene il concetto di discrezione.', 28153),
(152948, 'itIT', '', 'Alcuni membri dell\'Orda sembra reputino le mie recenti azioni... indiscriminate.', 28153),
(152947, 'itIT', '', 'Mi serve l\'aiuto di qualcuno di cui possa fidarmi ciecamente.', 28153),
(152946, 'itIT', '', 'Ah, eccoti qui. Stavo iniziando a chiedermi dove fossi.', 28153),
(152945, 'itIT', '...all\'Orda.', '', 28153),
(152944, 'itIT', 'I suoi consiglieri sono fedeli...', '', 28153),
(152943, 'itIT', 'Forse la mia Regina sarebbe più disposta a farlo, se fosse certa della loro fedeltà.', '', 28153),
(152942, 'itIT', 'Come facciamo ad aiutare la Capoguerra se nasconde le cose ai suoi consiglieri?', '', 28153),
(152941, 'itIT', 'Questo non ti riguarda.', '', 28153),
(152940, 'itIT', 'Ti ha convocato la Capoguerra?', '', 28153),
(152939, 'itIT', 'Nemmeno io so di cosa si tratta.', '', 28153),
(152938, 'itIT', 'La nostra Capoguerra ha richiesto la tua presenza per una missione di grande importanza... e segretezza.', '', 28153),
(152937, 'itIT', 'Di\' ai tuoi amici di visitare la Locanda Zannadoro!', '', 28153),
(152936, 'itIT', 'Nun dimenticare di firmare il registro delli ospiti.', '', 28153),
(152935, 'itIT', 'Nun mi morire.', '', 28153),
(152934, 'itIT', 'Tieni qualche banana?', '', 28153),
(152933, 'itIT', 'Li Zannadoro nun mollano mai.', '', 28153),
(152932, 'itIT', 'Ti do il benvenuto alla Locanda Zannadoro!', '', 28153),
(152931, 'itIT', 'Ammutinamento o schiavitù.', '', 28153),
(152930, 'itIT', 'Prenditi cura della ciurma tua.', '', 28153),
(152929, 'itIT', 'Attenzione alle profondità salmastre.', '', 28153),
(152928, 'itIT', 'Piange per suo marito, che cadde a Theramore... ma quel giorno perse anche sua figlia.', '', 28153),
(152927, 'itIT', 'Smettila di blaterare! Non c\'è bisogno di dirlo a tutti.', 'Smettila di blaterare! Non c\'è bisogno di dirlo a tutti.', 28153),
(152926, 'itIT', 'Silenzio! Abbiamo tra le mani qualcosa di grosso.', 'Silenzio! Abbiamo tra le mani qualcosa di grosso.', 28153),
(152925, 'itIT', 'Aria! Non abbiamo bisogno di nessuno che faccia domande.', 'Aria! Non abbiamo bisogno di nessuno che faccia domande.', 28153),
(152924, 'itIT', 'Zem\'lan nun è nu posto adatto ai vivi.', '', 28153),
(152923, 'itIT', 'Stai cercando na ciurma?', '', 28153),
(152921, 'itIT', 'Salve!', '', 28153),
(152920, 'itIT', 'Katherine ha un enorme fardello. Non c\'è da stupirsi che il ritorno di Jaina sia stato così duro per lei.', '', 28153),
(152918, 'itIT', '', 'Dobbiamo riunire le casate sotto il vessillo dei Marefiero e ritrovare la flotta scomparsa, altrimenti Kul Tiras potrebbe cadere prima ancora che la guerra inizi.', 28153),
(152917, 'itIT', 'Il mio clan fu spazzato via dal Martello del Crepuscolo. Riuscii a sfuggire solo perché mio fratello Keeland mi mandò via sul suo grifone, salvandomi la vita.\n\nHo viaggiato in tutto il mondo, prima di stabilirmi qui a Kul Tiras, tra questa gente che va a caccia di grifoni per cibo e pelli. Ho mostrato loro che c\'era un altro modo e ora sono diventati la nuova generazione di Cavalieri di Grifoni.\n\nNon credo che tornerò a casa, è questo il mio clan ora.', '', 28153),
(152916, 'itIT', 'Riportami a Zul\'jan.', 'Riportami a Zul\'jan.', 28153),
(152915, 'itIT', 'Taglio', 'Taglio', 28153),
(152914, 'itIT', 'Cosa ci fa qui un Nano Granmartello?', 'Cosa ci fa qui un Nano Granmartello?', 28153),
(152913, 'itIT', 'Diventeremo ricchi dopo questo carico.', 'Diventeremo ricchi dopo questo carico.', 28153),
(152912, 'itIT', 'Quegli stolti non conoscevano il valore della roba sotto i loro piedi.', 'Quegli stolti non conoscevano il valore della roba sotto i loro piedi.', 28153),
(152911, 'itIT', 'Ho un compratore a Lunargenta che mi darà un sacco di soldi per queste reliquie.', 'Ho un compratore a Lunargenta che mi darà un sacco di soldi per queste reliquie.', 28153),
(152910, 'itIT', 'Nulla di questa roba finirà in un museo.', '', 28153),
(152907, 'itIT', 'Di tutte le cose che nun sembrano a posto a Nazmir... chesta sembra la peggiore. Sta\' in guardia.', '', 28153),
(152906, 'itIT', 'Hezrel è occupato! Cosa starà facendo laggiù?', '', 28153),
(152905, 'itIT', 'Ci aspettavamo che Hezrel ci aiutasse in combattimento, ma se n\'è andato a fare le cose sue. Chissà cosa sta escogitando...', '', 28153),
(152900, 'itIT', 'Giù le mani dal tesoro mio...', 'Mi hai battuto, ma tornerò presto...', 28153),
(152899, 'itIT', 'Chesta terra è maledetta... come tutti noi...', 'Zem\'lan nun ci lascia schiattare... chesta è la vera maledizione...', 28153),
(152898, 'itIT', 'Nun sento... niente...', 'Le gambe mortali tue si inginocchieranno...', 28153),
(152897, 'itIT', 'Il Capitano... lo verrà a sapere...', 'Risponderai... al Re dei Pirati Zem\'lan per chesto...', 28153),
(152896, 'itIT', 'Voliamo giù e incontriamoci con il Guardiano dei Titani Hezrel.', 'Voliamo giù e incontriamoci con il Guardiano dei Titani Hezrel.', 28153),
(152895, 'itIT', '', 'Devo informare mio padre di quanto successo accà. Abbiamo ottenuto na grande vittoria, ma la lotta contro i Troll del Sangue nun è finita.', 28153),
(152894, 'itIT', '', 'Nun dimenticherò tutto chello che l\'Orda ha fatto per la gente mia. Senza di voi, niente di chesto sarebbe stato possibile.', 28153),
(152893, 'itIT', '', 'Ai tuoi ordini!', 28153),
(152892, 'itIT', '', 'La caverna sta crollando! Via!', 28153),
(152891, 'itIT', 'Perirete qui tra le macerie o verrete massacrati dai miei servi. Non vivrete abbastanza per vedere la mia vittoria.', '', 28153),
(152890, 'itIT', '', 'Ti porterò con me!', 28153),
(152889, 'itIT', '', 'Un po\' più vicino!', 28153),
(152888, 'itIT', '', 'Divertiamoci un po\'!', 28153),
(152887, 'itIT', '', 'Andiamo, dammi un abbraccio!', 28153),
(152886, 'itIT', 'Seguitemi! Fate in fretta e mantenete il passo!', 'Seguitemi! Fate in fretta e mantenete il passo!', 28153),
(152885, 'itIT', '|TInterface\\Icons\\Spell_shadow_mindflay.blp:20|t Un |cFFFF0000|Hspell:269131|h[Plagiamente Antico]|h|r si attacca a |cFFFF0000$n|r!', '', 28153),
(152884, 'itIT', 'Eroi della Terza Flotta, preparatevi! Fate immediatamente rapporto a Re Mantogrigio!', 'Eroi della Terza Flotta, preparatevi! Fate immediatamente rapporto a Re Mantogrigio!', 28153),
(152883, 'itIT', 'Come non detto. È birra. Tutto a posto.', '', 28153),
(152882, 'itIT', '', '.', 28153),
(152881, 'itIT', '', 'Le forze nostre stanno tenendo lontani i Troll del Sangue, ma nun potranno farlo ancora a lungo. Dobbiamo farla finita, e presto.', 28153),
(152880, 'itIT', '', '.', 28153),
(152879, 'itIT', '', 'Nessuno però ha più avuto notizie della flotta da mesi! I Saggi delle Maree si sono rintanati nei loro chiostri e non sembrano intenzionati a cercare le navi scomparse.', 28153),
(152878, 'itIT', '', 'La Casata dei Crestabianca è stata una fedele alleata dei Marefiero per secoli, ma la sua recente assenza agli incontri del concilio ha fatto nascere voci preoccupanti.', 28153),
(152877, 'itIT', 'Torna, tesoruccio!', '', 28153),
(152876, 'itIT', 'Non volevo lasciarlo raffreddare.', 'Non volevo lasciarlo raffreddare.', 28153),
(152875, 'itIT', 'Lasciami morire chesta volta, Bwonsamdi... Ti prego...', '', 28153),
(152874, 'itIT', 'Forza, sputa il rospo.', '', 28153),
(152873, 'itIT', '', 'Continueremo il nostro... Perché mi guardi così? HAI QUALCOSA DA DIRE?!?', 28153),
(152872, 'itIT', 'Subito, sì. Assolutamente e senza indugio!', '', 28153),
(152871, 'itIT', 'Ho visto di peggio, ma è comunque una brutta storia. Dovremo aggiornare il Gran Comandante su ciò che abbiamo scoperto.', '', 28153),
(152870, 'itIT', 'Oh santo cielo, è peggio di quanto pensassi. Le mie più sincere scuse per averti messo in una situazione così pericolosa, Barbabronzea.', '', 28153),
(152869, 'itIT', 'BENE?!? Quella tipa era più pazza di un Murloc in calore. Ha cercato di sacrificare $gil nostro amato:la nostra amata; $C qui a un certo Dio del Sangue chiamato G\'huun.', '', 28153),
(152868, 'itIT', 'Il Capitano Conrad... sta bene, vero?', '', 28153),
(152867, 'itIT', 'Zul\'nazman, credo. O era Tul\'vor? A dire il vero credo siano la stessa cosa, più o meno.', '', 28153),
(152866, 'itIT', 'Che lo sapesse o meno, è ora di andare a fondo della questione. Dove stava andando questo capitano?', '', 28153),
(152865, 'itIT', 'Oh... santo cielo. Di certo lo stimato Capitano Conrad non era a conoscenza di queste macabre circostanze.', '', 28153),
(152864, 'itIT', '<Harry sbianca in volto.>', '', 28153),
(152863, 'itIT', 'Cosa significa tutto questo, Harry?!? Quelle offerte che stavi mandando... I soldati sono stati sacrificati! Gli hanno prosciugato tutto il sangue come fossero barili di doppio malto alla Festa della Birra.', '', 28153),
(152862, 'itIT', 'Non mi interessa! Da noi non avranno nemmeno una moneta di rame fin quando io e $n non avremo le cose ben chiare.', '', 28153),
(152861, 'itIT', 'Accordi commerciali con i Troll! Abbiamo persino dei pipistrelli pronti a mandare un\'altra offerta commerciale a Zalamar.', '', 28153),
(152860, 'itIT', 'Oh, cielo! Be\', in realtà sì. Direi che è piuttosto accurato, ma il Capitano Conrad è pieno di risorse, senza ombra di dubbio.', '', 28153),
(152859, 'itIT', 'Ho sentito che sono dei selvaggi che praticano sacrifici di sangue.', '', 28153),
(152858, 'itIT', 'Niente di importante, ve l\'assicuro! Il nostro glorioso Capitano è occupato a stipulare accordi commerciali con i Troll locali.', '', 28153),
(152857, 'itIT', 'Bene, nessun segno del Capitano. Cosa succede?', '', 28153),
(152856, 'itIT', 'Ah ah! Dritto al punto. Non temete, è tutto a posto! Che ne dite di spostarci in un luogo più sicuro dietro le mura?', '', 28153),
(152855, 'itIT', 'Dov\'è il Capitano?', '', 28153),
(152854, 'itIT', 'Il Capitano Conrad mi ha lasciato istruzioni.', '', 28153),
(152853, 'itIT', 'Vi stavamo aspettando, stimati consiglieri e futuri amici.', '', 28153),
(152852, 'itIT', 'Benvenuti, benvenuti!', '', 28153),
(152851, 'itIT', 'A quanto pare è arrivato il comitato di benvenuto. Harry è un tipo interessante, tienilo d\'occhio.', '', 28153),
(152850, 'itIT', 'E... bleah... tieni il naso tappato. Cos\'è questo tanfo terribile?', '', 28153),
(152849, 'itIT', 'Non fa niente. Ascolta, tieni gli occhi aperti. Terre pericolose come queste non perdonano i viaggiatori impreparati, $n.', '', 28153),
(152848, 'itIT', 'Eppure, questa terra non adora certo la presenza degli Zandalari e dei loro amici dell\'Orda. L\'amico del mio nemico è mio... aspetta, com\'era il detto?', '', 28153),
(152847, 'itIT', 'Abbiamo mandato avanti il Capitano Conrad a costruire un forte. Dicono che i Troll del Sangue qui potrebbero essere disposti a commerciare, ma non credo che lo faranno a un prezzo che valga la pena pagare.', '', 28153),
(152846, 'itIT', 'Mi piace! Se ti si rizzano i peli, significa che grandi avventure o conoscenze attendono dietro l\'angolo.', '', 28153),
(152845, 'itIT', 'Questo posto mi fa venire i brividi...', '', 28153),
(152844, 'itIT', 'Tuttavia, voi non sopravvivrete fino a quel giorno. Guardiano, sorgi ed elimina questi intrusi!', '', 28153),
(152843, 'itIT', 'I Kul Tirani saranno spazzati via e queste terre saranno di nuovo nostre!', '', 28153),
(152842, 'itIT', 'I vostri antenati erano degli sciocchi... proprio come voi!', '', 28153),
(152841, 'itIT', 'usa una delle corde per scendere sulla scialuppa da sbarco, $n. Buona fortuna.', '', 28153),
(152840, 'itIT', '', 'Quelle sono sicuramente altre incisioni. Andiamo!', 28153),
(152839, 'itIT', '', 'Gorak Tul non è sopravvissuto! Ci sono delle testimonianze a provarlo!', 28153),
(152838, 'itIT', 'Le autorità locali ci hanno dato il permesso di aprire dei portali qui.', 'Le autorità locali ci hanno dato il permesso di aprire dei portali qui.', 28153),
(152837, 'itIT', 'Questo posto è pregno di magia. Riesci a sentirla?\n\nMi chiedo che genere di rituali abbiano compiuto qui...', 'Questo posto è pregno di magia. Riesci a sentirla?\n\nMi chiedo che genere di rituali abbiano compiuto qui...', 28153),
(152836, 'itIT', '', 'Un\'altra stele! Anche questa raffigura Gorak Tul.', 28153),
(152835, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso Vol\'dun.', '|cFF0000FF(Missione)|r Fai rotta verso Vol\'dun.', 28153),
(152834, 'itIT', '|cFFEF0201+$1i|r |cFFFFFF00Azerite|r', '|cFFEF0201+$1i|r |cFFFFFF00Azerite|r', 28153),
(152833, 'itIT', 'Dicevano che avrei lavorato con dei <Tossisce> del Sangue. Ho chiesto tipo, Elfi del Sangue?!? E mi hanno ripetuto <Tossisce> del Sangue.\n\nTROLL del Sangue. Non ELFI. Mai una gioia.', '', 28153),
(152832, 'itIT', '', 'Signorsì.', 28153),
(152831, 'itIT', '', 'Aspetta... Che succede?', 28153),
(152830, 'itIT', 'L\'unione fa la forza.', '', 28153),
(152829, 'itIT', 'Sì, avevo annotato qualcosa riguardo a quelli rossi. L\'avevo pure cerchiato. In rosso. Grazie per il tuo aiuto. Sarebbe finita male senza di te.', '', 28153),
(152828, 'itIT', 'Ehi. Vorrei recuperare dei campioni di questo raro Bocciolo del Deserto. Mi aiuteresti?', '', 28153),
(152827, 'itIT', 'Che pazzoide! Ci rivedremo al Forte Vittoria. Andiamocene da questo luogo oscuro prima che vengano a cercarci.', '', 28153),
(152826, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(152825, 'itIT', 'Un panorama che non si vede spesso da queste parti del mondo. Si dice che le foglie di pianta sferzante rossa abbiano delle proprietà curative.$b$bVorrei recuperarne un po\', ma strapparle rilascerebbe l\'odore della pianta nell\'aria, attirando l\'attenzione della fauna locale.$b$bProteggimi mentre ne raccolgo un po\'. Ti ricompenserò adeguatamente.', '', 28153),
(152824, 'itIT', 'Alleria, prendi il resto delle truppe e concentrati a fermare l\'armata nemica.', '', 28153),
(152823, 'itIT', 'LA MIA VITA PER L\'ORDA!', '', 28153),
(152822, 'itIT', 'Mio padre ha dato tutto per l\'Alleanza! La vera domanda è: tu sei disposto a fare lo stesso per l\'Orda?', '', 28153),
(152821, 'itIT', 'Non mi farò MAI da parte! Vivo e muoio per combattere. Tu che prezzo hai pagato per la tua gente?', '', 28153),
(152820, 'itIT', 'Tuo padre era un uomo d\'onore, moccioso. Tu non sai nemmeno cosa significa.', '', 28153),
(152819, 'itIT', 'Fatti da parte, Faucisaure. Questa guerra non è solo tua e non c\'è alcun onore nell\'ucciderti.', '', 28153),
(152818, 'itIT', '', 'Sono pronta!', 28153),
(152817, 'itIT', 'Ottimo lavoro, gente! Continuiamo così.', '', 28153),
(152816, 'itIT', 'Quattro occhi... la fine... lei sta arrivando!', '', 28153),
(152815, 'itIT', 'Ombra eterna... migliaia di braccia...', '', 28153),
(152814, 'itIT', 'Ti devo tutto, $p, nun me lo dimenticherò.\n\nPer ora, aiuteremo Norah e li altri Vulpera a saccheggiare tutti i bottini rubati da Zem\'lan, ma nun esitare a chiedere se ti serve la mano di na ciurma di pirati non morti.\n\nAbbiamo organizzato nu buon ammutinamento, ma so che Zem\'lan nun ha dovuto obbligare tutti a trasformarsi in mostri, molti l\'hanno fatto di loro spontanea volontà.\n\nSta\' accuort\', se torni al porto.', '', 28153),
(152813, 'itIT', 'Dobbiamo assicurarci che il sacrificio di Victoria non sia stato vano. Il suo bastone è la chiave per aprire la via verso il santuario.', '', 28153),
(152812, 'itIT', 'Ammutinamento o schiavitù, $p. Io sono con te.', '', 28153),
(152811, 'itIT', 'Hai mai visto nu tesoro così grande in nu posto solo?\n\nChesti sono i frutti di na vita intera dedicata alla pirateria. È bellissimo...', '', 28153),
(152810, 'itIT', '', '<Ahna russa pesantemente mentre fa finta di dormire.>', 28153),
(152809, 'itIT', 'Suona il gong per sfidare il Re dei Pirati Zem\'lan. Sono pronto ad affrontarlo.', '', 28153),
(152808, 'itIT', 'Capisco. Allora dimostreremo a Katherine Marefiero la stessa verità che ho imparato io a caro prezzo...', '', 28153),
(152807, 'itIT', 'Ottimo lavoro! Le monete d\'oro dell\'antico impero dei Troll valgono una fortuna. Ecco la tua parte!', '', 28153),
(152806, 'itIT', 'Alla Corte di Zak\'rajan ho trovato un antico totem, il cui potere è in grado di resuscitare i morti. Portalo alla Fossa delle Ossa e usalo per riportare alla luce qualche tesoro sepolto!', '', 28153),
(152805, 'itIT', 'Ah, basta. Non ho tempo per questo. Devo andare a una festa!', '', 28153),
(152804, 'itIT', 'Voi giovani d\'oggi siete sempre così impazienti. Mi sto solo scaldando!', '', 28153),
(152803, 'itIT', 'Se continuerai a infastidirmi, ti racconterò una storia. Una storia mooolto lunga e noiosa.', '', 28153),
(152802, 'itIT', 'Ci racconteremo delle storie la prossima volta.', '', 28153),
(152801, 'itIT', 'Va bene, vai. Ho altre cose da fare.', '', 28153),
(152800, 'itIT', 'Non fare le cose di fretta.', '', 28153),
(152799, 'itIT', 'Abbassa la voce!', '', 28153),
(152798, 'itIT', 'Hai qualche bella storia da raccontare?', '', 28153),
(152797, 'itIT', 'Sì, sì... sto ascoltando.', '', 28153),
(152796, 'itIT', 'La flora della giungla può essere più pericolosa della fauna, se nun ci fai attenzione.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152795, 'itIT', 'Non metterò mai più piede in questa miniera!', 'Non metterò mai più piede in questa miniera!', 28153),
(152794, 'itIT', 'Sono sbucati dal nulla!', 'Sono sbucati dal nulla!', 28153),
(152793, 'itIT', 'Grazie! Credevo fosse giunta la mia ora.', 'Grazie! Credevo fosse giunta la mia ora.', 28153),
(152792, 'itIT', 'Fatemi uscire da qui!', 'Fatemi uscire da qui!', 28153),
(152791, 'itIT', '', 'Questo vi porterà sul ponte di sotto.', 28153),
(152790, 'itIT', 'Non credo che la tua faccia e il mio stivale si siano già presentati. Che ne dici di risolvere la cosa?', '', 28153),
(152789, 'itIT', 'Vola via, uccellino...', '', 28153),
(152788, 'itIT', 'Ci vediamo in volo.', '', 28153),
(152787, 'itIT', '', 'Nella Valle dei Sacraonda, a nord, i Saggi delle Maree della Casata dei Sacraonda costruiscono e benedicono le navi della nostra leggendaria flotta.', 28153),
(152786, 'itIT', 'Va bene. Ora vai.', '', 28153),
(152785, 'itIT', 'Torniamo al lavoro!', '', 28153),
(152784, 'itIT', 'Sì, che c\'è?', '', 28153),
(152783, 'itIT', 'Che ti serve?', '', 28153),
(152782, 'itIT', 'Sì? Ho un sacco da fare!', '', 28153),
(152781, 'itIT', 'Quelle bestie sono state la rovina di molte carovane a Vol\'dun. Ben fatto.', '', 28153),
(152780, 'itIT', 'Gli Avvoltoi Durobecco non sono una razza addomesticabile. Sono diventati una seccatura e dobbiamo sbarazzarcene.', '', 28153),
(152779, 'itIT', 'Sentiti $glibero:libera; di dare un\'occhiata, ma non toccare nulla, per favore.$b$bQueste piante sono molto delicate.', '', 28153),
(152778, 'itIT', '', 'A ovest c\'è Drustvar, regione montana da dove proviene la maggior parte dei minerali e alcuni dei nostri guerrieri migliori.', 28153),
(152777, 'itIT', '', 'Oltre la Baia di Tiragarde, ci sono le terre controllate dalle famiglie Crestabianca e Sacraonda.', 28153),
(152776, 'itIT', 'Per te ci sarà solo dolore!', 'Per te ci sarà solo dolore!', 28153),
(152775, 'itIT', 'Conosco diversi modi per farti parlare!', 'Conosco diversi modi per farti parlare!', 28153),
(152774, 'itIT', 'Spezzerò il tuo spirito.', 'Spezzerò il tuo spirito.', 28153),
(152773, 'itIT', 'Tutta la vita finisce in cenere...', '', 28153),
(152772, 'itIT', 'Provammo a chiedere aiuto... ma era troppo tardi.', '', 28153),
(152771, 'itIT', 'Kul Tiras sta cadendo a pezzi... così ho chiesto il vostro aiuto. Abbiamo bisogno dell\'Alleanza tanto quanto voi ne avete di noi.', '', 28153),
(152770, 'itIT', 'Ma... ha perso la via. I suoi consiglieri l\'hanno tenuta all\'oscuro dell\'infezione che sta divorando l\'intero regno.', '', 28153),
(152769, 'itIT', 'Kul Tiras nasconde ancora le cicatrici della Terza Guerra e nessuno ne soffre più di Katherine Marefiero.', '', 28153),
(152768, 'itIT', '', 'Cerca di non farmi fare una brutta figura.', 28153),
(152767, 'itIT', 'Pochi giorni dopo si svegliò urlando, coperto di sudore. L\'infezione aveva divorato le sue interiora. E così egli non visse abbastanza a lungo da vedere un\'altra alba.', '', 28153),
(152766, 'itIT', '', 'Se non ci sono più monete, controlla gli altri luoghi.', 28153),
(152765, 'itIT', 'Sarebbe dovuto essere... il suo biglietto di ritorno, ma si rifiutava di ritirarsi dalla guerra prima che fosse vinta. Così, si bendò le ferite e disse ai guaritori che stava bene.', '', 28153),
(152763, 'itIT', 'Una nave da guerra orchesca colpì il nostro trasporto e le schegge attraversarono l\'intero ponte, ferendo seriamente un mio amico.', '', 28153),
(152762, 'itIT', 'Mi trovavo in battaglia, molti anni fa. Forse era... la Seconda Guerra? Difficile a dirsi.', '', 28153),
(152761, 'itIT', 'Mmm... Fate divertire un po\' questo vecchio cavaliere!', '', 28153),
(152760, 'itIT', 'Perché desideri aiutarci?', '', 28153),
(152759, 'itIT', 'Katherine Marefiero ci ha voltato le spalle e ha cacciato via sua figlia come traditrice.', '', 28153),
(152758, 'itIT', 'Un vagabondo Zandalari mi ha offerto questa pozione in un baratto. Dovrebbe cucinare istantaneamente l\'oggetto su cui è utilizzata. Significa carne gratis! Provala sulle creature della zona.', '', 28153),
(152757, 'itIT', 'Taelia! Preparati ad aggiornare i nostri ospiti.', '', 28153),
(152756, 'itIT', 'Tutto si scioglierà.', '', 28153),
(152755, 'itIT', 'Re Mantogrigio, è un onore. Sei libero di rimanere nella baia, col mio permesso.', '', 28153),
(152754, 'itIT', 'I risultati sono innegabili! Ma per essere sicuri la farò assaggiare prima ai nostri amici zannuti...', '', 28153),
(152753, 'itIT', '', 'Il desiderio di potere. La ricerca di una verità più grande. La brama di sangue.', 28153),
(152752, 'itIT', '', 'I metodi dei Nazmani erano... discutibili, all\'inizio, ma ora li conosco bene. È gente semplice con desideri semplici.', 28153),
(152751, 'itIT', '', 'Ecco, lascia che ti mostri cos\'ho imparato.', 28153),
(152750, 'itIT', '', 'C\'è ancora molto da scoprire su di loro. Questa magia del sangue... è più potente di quanto tu possa immaginare.', 28153),
(152749, 'itIT', '', 'Potrebbero rivelarsi un potente mezzo contro i Troll Zandalari e i loro alleati dell\'Orda.', 28153),
(152748, 'itIT', '', 'Il mio rapporto con i Troll del Sangue, questi Nazmani, ha raggiunto livelli che non mi aspettavo.', 28153),
(152747, 'itIT', 'Chiudi quella fogna!', '', 28153),
(152746, 'itIT', '', 'Arrrgh!', 28153),
(152745, 'itIT', '', 'Non c\'è niente di personale, spero tu lo capisca, ma non puoi intralciare tutti i progressi che ho fatto. Le cose che ho imparato... e ciò che devo ancora scoprire.', 28153),
(152744, 'itIT', '', 'Questo Zandalari verrà sacrificato per incrementare il nostro potere.', 28153),
(152743, 'itIT', 'Ci hai condotti fino accà. Ti seguiremo.', 'Ci hai condotti fino accà. Ti seguiremo.', 28153),
(152742, 'itIT', 'Il campione sa dove sta na ciurma di Vulpera. Io dico di unirci a loro, per ora, finché la situazione nun si sarà calmata.', '', 28153),
(152741, 'itIT', 'I lacchè di Zem\'lan ci staranno cercando in mare.', '', 28153),
(152740, 'itIT', 'Sì, ma dovremo restare nascosti per nu poco, almeno.', '', 28153),
(152739, 'itIT', 'Liberi di tenerci tutto il bottino.', 'Liberi di tenerci tutto il bottino.', 28153),
(152738, 'itIT', 'Liberi di saccheggiare ovunque ci piaccia.', 'Liberi di saccheggiare ovunque ci piaccia.', 28153),
(152737, 'itIT', 'Liberi di salpare per il mare aperto.', 'Liberi di salpare per il mare aperto.', 28153),
(152736, 'itIT', 'Ce l\'abbiamo fatta, compagni. Siamo finalmente liberi da Zem\'lan!', '', 28153),
(152735, 'itIT', 'Tutti ai remi! A doppia velocità verso la costa!', 'Tutti ai remi! A doppia velocità verso la costa!', 28153),
(152734, 'itIT', 'Tu devi essere l\'$gemissario:emissaria; dell\'Alleanza. Sono felice che Flynn e Taelia siano riusciti a farti uscire da quella dannata prigione.\n\nSono Ser Cyrus Granscogliera e, a nome dell\'Ammiragliato dei Marefiero, ti do il benvenuto a Kul Tiras.\n\n<Cyrus ti porge la mano.>', '', 28153),
(152733, 'itIT', '<Stringi la sua mano.>', '<Stringi la sua mano.>', 28153),
(152732, 'itIT', 'Mi restano meno giorni davanti a me, rispetto a quelli che ho passato.\n\nNon li sprecherò osservando Kul Tiras cadere a pezzi.', '', 28153),
(152731, 'itIT', 'Va bene, ciurma. Pigliate il tesoro e salite sulla barca!', '', 28153),
(152730, 'itIT', 'Winston sta volando fuori dalla tua portata. Torna a Corlain!', '', 28153),
(152729, 'itIT', 'Principessa. Li esploratori miei dicono che Hezrel sta girovagando alla base di chesta struttura.', '', 28153),
(152728, 'itIT', 'Le menti dei Gurubashi sono sempre state deboli, sin dai tempi di Hakkar. Vengono plagiati troppo facilmente e devono essere epurati.', '', 28153),
(152727, 'itIT', '', 'Non... ci... sconfiggerete...', 28153),
(152726, 'itIT', 'Agli ordini, capitano.', '', 28153),
(152725, 'itIT', '', 'Corlain appartiene alla congrega!', 28153),
(152724, 'itIT', 'Riposate e godetevi l\'ospitalità dell\'accampamento. Domani parleremo di come recuperare il resto del tesoro.', 'Riposate e godetevi l\'ospitalità dell\'accampamento. Domani parleremo di come recuperare il resto del tesoro.', 28153),
(152723, 'itIT', 'Benvenuti nella carovana!', 'Benvenuti nella carovana!', 28153),
(152722, 'itIT', 'Bene, allora...', 'Bene, allora...', 28153),
(152721, 'itIT', 'Certo. Ce ne sta n\'isola piena al largo della costa. Più tesori di quanti tu possa immaginare.', '', 28153),
(152720, 'itIT', 'Una piccola maledizione non ha mai tenuto lontani i Vulpera da un degno tesoro... Ne avete altri da qualche parte?', 'Una piccola maledizione non ha mai tenuto lontani i Vulpera da un degno tesoro... Ne avete altri da qualche parte?', 28153),
(152719, 'itIT', 'L\'unico problema è che il tesoro è maledetto.', 'L\'unico problema è che il tesoro è maledetto.', 28153),
(152718, 'itIT', 'Stiamo cercando na nuova ciurma a cui unirci. Se ci accetti, condivideremo il tesoro nostro.', '', 28153),
(152717, 'itIT', 'Il Re dei Pirati Zem\'lan ha acciso l\'amico tuo. Ci siamo ammutinati contro di lui e abbiamo rubato il tesoro suo.', '', 28153),
(152716, 'itIT', 'Sto ascoltando...', 'Sto ascoltando...', 28153),
(152715, 'itIT', 'Contrordine! Stiamo accà per trattare.', '', 28153),
(152714, 'itIT', 'S-s-scheletri! N-N-Norah, uccidili!', 'S-s-scheletri! N-N-Norah, uccidili!', 28153),
(152713, 'itIT', 'Ottimo lavoro. Quei cannoni avranno certamente rallentato l\'assedio dei Senzafede.', '', 28153),
(152712, 'itIT', 'Io vivo per un bel combattimento!', 'Io vivo per un bel combattimento!', 28153),
(152711, 'itIT', 'I Senzafede stanno intensificando l\'attacco! Usa i cannoni che abbiamo requisito per aiutare a difendere il tempio!', '', 28153),
(152710, 'itIT', '', 'Asdrubal, ora!', 28153),
(152709, 'itIT', 'Quando vuoi.', 'Quando vuoi.', 28153),
(152708, 'itIT', 'Ti vuoi muovere? Non siamo qui in vacanza.', '', 28153),
(152707, 'itIT', 'Scatenate l\'inferno!', '', 28153),
(152706, 'itIT', 'Fuoco!', '', 28153),
(152705, 'itIT', 'Fategliela vedere!', '', 28153),
(152704, 'itIT', 'Bersaglio acquisito! Fuoco!', '', 28153),
(152703, 'itIT', 'Fuoco a volontà!', '', 28153),
(152702, 'itIT', 'Ecco il bersaglio! Fuoco!', '', 28153),
(152701, 'itIT', 'Ahahah!', '', 28153),
(152700, 'itIT', 'Già. Un po\' troppo spaventoso per i nostri potenziali clienti.', '', 28153),
(152699, 'itIT', 'Troppo spaventosa?', '', 28153),
(152698, 'itIT', 'Ho fatto delle piccole valutazioni sui profitti in relazione alle perdite e non credo che valga la pena perdere altro tempo in questa zona.', '', 28153),
(152697, 'itIT', 'Ma... per quanto riguarda l\'Azerite?', '', 28153),
(152696, 'itIT', 'Bene. Salta su e andiamo.', '', 28153),
(152695, 'itIT', 'Assolutamente sì.', '', 28153),
(152694, 'itIT', 'Quindi... ehm... che ne dici se ce ne andiamo di qui?', '', 28153),
(152693, 'itIT', 'No no no no...', '', 28153),
(152692, 'itIT', 'Sarà meglio farti passare questa paura delle streghe, Eitrigg. Questa zona è PIENA di Azerite, e... URGH!', '', 28153),
(152691, 'itIT', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t %s ottiene uno |cFFFF0000|Hspell:263246|h[Scudo di Fulmini]|h|r!', '|TInterface\\ICONS\\Spell_Nature_LightningShield.blp:20|t %s ottiene uno |cFFFF0000|Hspell:263246|h[Scudo di Fulmini]|h|r!', 28153),
(152690, 'itIT', 'Basta!', '', 28153),
(152689, 'itIT', '', 'Il tuo sangue è mio!', 28153),
(152688, 'itIT', 'Chi se ne frega! Hai trovato la vena d\'Azerite?', '', 28153),
(152687, 'itIT', 'Cosa? Che c\'è?', '', 28153),
(152686, 'itIT', 'Chiudi la b-bocca.', '', 28153),
(152685, 'itIT', 'Ahhh... ahahah! Un grosso vecchio Orco che ha paura delle streghe.', '', 28153),
(152684, 'itIT', 'NO! Volevo dire, no. È solo che... non mi piacciono, tutto qui.', '', 28153),
(152683, 'itIT', 'Cos\'hai detto?', '', 28153),
(152682, 'itIT', 'Attenzione... alle streghe...', '', 28153),
(152681, 'itIT', 'Eitrigg... hai paura delle streghe?', '', 28153),
(152680, 'itIT', 'Ha detto... s-s-streghe?', '', 28153),
(152679, 'itIT', 'L\'Area del Mercato non è sicura! Gli uccelli ci sono addosso!', 'L\'Area del Mercato non è sicura! Gli uccelli ci sono addosso!', 28153),
(152678, 'itIT', 'Allora fai il tuo lavoro e difendimi!', '', 28153),
(152677, 'itIT', 'No... ma qualcosa lo vedo. Abbiamo compagnia.', '', 28153),
(152676, 'itIT', 'Bah... succede ogni volta. Vedi dell\'Azerite da qualche parte?', '', 28153),
(152675, 'itIT', 'Sono dappertutto!', 'Sono dappertutto!', 28153),
(152674, 'itIT', 'Gallywix... lo vedi questo corpo maciullato? Il tuo esploratore è morto.', '', 28153),
(152673, 'itIT', 'Sì, certo.', '', 28153),
(152672, 'itIT', 'D\'accordo, cercheremo l\'Azerite. Dopo però DOBBIAMO concentrarci sull\'Alleanza!', '', 28153),
(152671, 'itIT', 'Troppi... uccelli!', 'Troppi... uccelli!', 28153),
(152670, 'itIT', 'Non mi fiderò mai più di un gabbiano!', 'Non mi fiderò mai più di un gabbiano!', 28153),
(152669, 'itIT', 'La vecchia MacMillan aveva ragione. Questi uccelli sono malvagi!', 'La vecchia MacMillan aveva ragione. Questi uccelli sono malvagi!', 28153),
(152668, 'itIT', 'Pfff. Servi.', '', 28153),
(152667, 'itIT', 'Prima andremo a controllare quella.', '', 28153),
(152666, 'itIT', 'Prima le cose importanti! I miei esploratori mi hanno parlato di un\'ENORME vena d\'Azerite qui a Drustvar.', '', 28153),
(152665, 'itIT', 'Allora sparisci dalla mia vista, o ti darò un vero motivo per aver paura!', '', 28153),
(152664, 'itIT', 'Dovremmo fare attenzione. Le sue parole sono... preoccupanti.', '', 28153),
(152663, 'itIT', 'Sì, ma...', '', 28153),
(152662, 'itIT', '...terribile maledizione... gli altri sono tutti...', '', 28153),
(152661, 'itIT', 'Dovete tornare indietro! È...', '', 28153),
(152660, 'itIT', '', 'Uh. Credevo sarebbe stata più grossa.', 28153),
(152659, 'itIT', '', 'La scarica non basta. Serve più energia.', 28153),
(152658, 'itIT', 'Preferiamo la natura alla fredda pietra della città. Molti Zandalari ci credono eretici e dicono che la matrona nostra nun sia nu Loa.\n\nPossono pensare chello che vogliono, ma noi Lun\'alai possediamo da molto i doni della natura e sappiamo assumere forme selvagge. La nostra è la via dell\'equilibrio, nun dei patti.', '', 28153),
(152655, 'itIT', 'Magnifico! Stupendo! Oh, questo ha un po\' di sabbia sopra. Non fa niente, ottimo lavoro!', '', 28153),
(152654, 'itIT', 'Un sacco di vetro marino finisce sulle coste di questa palude, ma i Murloc non fanno che rubarlo tutto! Vedi se riesci a recuperare qualche bel pezzettino.', '', 28153),
(152653, 'itIT', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma inizia a lanciare |cFFFF0404|Hspell:249924|h[Laceranima]|h|r!', '|TINTERFACE\\ICONS\\Ability_DemonHunter_SoulCleave2.blp:20|t Yazma inizia a lanciare |cFFFF0404|Hspell:249924|h[Laceranima]|h|r!', 28153),
(152652, 'itIT', 'Troppo tardi. L\'invasione è già iniziata!', 'Troppo tardi. L\'invasione è già iniziata!', 28153),
(152651, 'itIT', 'Pensavi forse che lavorassi da solo? Ti presento i miei soci!', 'Pensavi forse che lavorassi da sola? Ti presento i miei soci!', 28153),
(152650, 'itIT', '', 'Le azioni della congrega sono terribili, ma questo era troppo anche per loro! Le parole non possono esprimere la mia gratitudine per aver fermato questa... mattanza.', 28153),
(152649, 'itIT', 'Le attività della congrega rasentano il sacrilegio. Così ha fine uno dei loro piani più oscuri.', '', 28153),
(152648, 'itIT', 'Mo\' usiamo la capa! Troviamoci alla barca. Mi assicurerò che la ciurma la carichi di tesori.', '', 28153),
(152647, 'itIT', '', 'Ogni vita salvata da quel culto è una vittoria. Ottimo lavoro.', 28153),
(152646, 'itIT', 'Manipolare la morte e la rinascita è solo nostra competenza. Hai fatto bene a ricordarglielo.', '', 28153),
(152645, 'itIT', '', 'Hai salvato i cittadini di Drustvar da quel terrore dei cieli. Hai i miei ringraziamenti.', 28153),
(152644, 'itIT', 'Non causare problemi.', 'Non causare problemi.', 28153),
(152643, 'itIT', 'Le nostre Guardaboschi Oscure faranno buon uso di queste penne.', '', 28153),
(152642, 'itIT', 'N\'eternità di razzie e saccheggi... senza di te!', '', 28153),
(152641, 'itIT', 'Cosa c\'è di meglio di n\'eternità di razzie e saccheggi?', '', 28153),
(152640, 'itIT', 'Sei nu capitano crudele, Zem\'lan. La ciurma si merita di meglio!', '', 28153),
(152639, 'itIT', '', 'Dovete, o sarà la fine per tutti. Ora andate!', 28153),
(152638, 'itIT', '', 'Non ti lasceremo qui a morire!', 28153),
(152637, 'itIT', '', 'C\'è mancato poco. A quanto pare dovremo tenere d\'occhio anche il mare, non solo le sabbie di Vol\'dun.', 28153),
(152636, 'itIT', '', 'C\'è mancato poco. A quanto pare dovremo tenere d\'occhio anche il mare, oltre che le sabbie.', 28153),
(152635, 'itIT', '', 'N\'enorme mostro marino sta devastando la costa. Dobbiamo fermare la bestia, prima che raggiunga l\'entroterra.', 28153),
(152634, 'itIT', '', 'Un enorme mostro marino sta devastando la costa. Dobbiamo fermare la bestia, prima che si avvicini al nostro accampamento!', 28153),
(152633, 'itIT', '', 'Xorrath era nu comandante d\'alto rango dell\'armata dei Sethrak. La morte sua è na grande vittoria per noi.', 28153),
(152632, 'itIT', '', 'L\'Invocatore delle Zanne Xorrath era un comandante d\'alto rango dell\'armata dei Sethrak. La sua morte è una grande vittoria per noi.', 28153),
(152631, 'itIT', '', 'Li esploratori Vulpera riferiscono della presenza di nu comandante Sethrak nelle vicinanze. Dobbiamo cogliere l\'opportunità per acciderlo.', 28153),
(152630, 'itIT', '', 'I nostri esploratori riferiscono della presenza di un comandante Sethrak di alto rango nelle vicinanze. Dobbiamo cogliere l\'opportunità per eliminarlo, finché possiamo.', 28153),
(152629, 'itIT', '', 'Ottimo lavoro! La tribù andrà in pezzi senza nu capo a guidarla.', 28153),
(152628, 'itIT', '', 'Ottimo lavoro! La tribù andrà in pezzi senza un capo a guidarla.', 28153),
(152627, 'itIT', '', 'C\'è una tribù di Murloc qui vicino che ci sta causando problemi. Uccidi il loro capo e la tribù andrà allo sbando.', 28153),
(152626, 'itIT', '', 'Ci sta na tribù di Murloc vicino accà che ci sta causando problemi. Accidi il capo loro e la tribù andrà allo sbando.', 28153),
(152625, 'itIT', '', 'Ottimo lavoro. I nostri esploratori saranno felici della dipartita di Mor\'fani.', 28153),
(152624, 'itIT', '', 'Ottimo lavoro. I Vulpera saranno felici della morte di Mor\'fani.', 28153),
(152623, 'itIT', 'Un enorme corvo è stato ammaliato dalla congrega per essere usato contro i civili. Non provo alcuna compassione per gli abitanti di Drustvar, ma le sue penne potrebbero essere molto utili alle nostre Guardaboschi Oscure.', '', 28153),
(152622, 'itIT', 'Una delle streghe più potenti della congrega sta sacrificando delle accolite con lo scopo di ottenere più potere. Uccidila e mostra a quelle presuntuose che solo la Dama Oscura possiede il dominio sulla morte.', '', 28153),
(152621, 'itIT', 'Pare che la congrega abbia \"assunto\" gli chef del maniero per creare dei piatti a dir poco disgustosi. Sarebbe meglio per tutti se li eliminassi il prima possibile.', '', 28153),
(152620, 'itIT', '', 'Le Frangicuore hanno ammaliato un enorme volatile nativo di Drustvar. Uccidilo prima che si metta a predare i civili!', 28153),
(152619, 'itIT', '', 'Un membro della congrega di Dama Crestabianca sta sacrificando i suoi accoliti. Ferma il rituale prima che troppe vite vadano perse!', 28153),
(152618, 'itIT', '', 'Un esiliato Zandalari sta terrorizzando i nostri esploratori. Trovalo ed eliminalo, prima che si prenda altre vite.', 28153),
(152617, 'itIT', '', 'N\'esiliato sta terrorizzando i Vulpera. Trovalo ed eliminalo, prima che si pigli altre vite.', 28153),
(152616, 'itIT', '', 'Gli chef stanno servendo piatti dai dubbi contenuti a degli ospiti ignari. Metti fine a quegli orrori culinari!', 28153),
(152615, 'itIT', 'Agli ordini!', '', 28153),
(152614, 'itIT', 'N... no, signore.', '', 28153),
(152613, 'itIT', 'Riposo. Lasciateli passare. Parleremo nel mio ufficio.', '', 28153),
(152612, 'itIT', 'No! Voi servite Kul Tiras! Indossate il sigillo dei Marefiero! E ricevete gli ordini da ME.', '', 28153),
(152611, 'itIT', 'È impossibile coltivare cose a Vol\'dun senza fertilizzante. Di solito lo prendiamo dalle iene, ma ultimamente non ci stanno lasciando molto. Cerca di nutrirle per velocizzare le cose!', '', 28153),
(152610, 'itIT', 'Dama Bracescura? Servite forse Dama Bracescura? È il sigillo di Dama Bracescura quello sul vostro scudo?', '', 28153),
(152609, 'itIT', 'Ma signore... Dama Bracescura ha ordinato...', '', 28153),
(152608, 'itIT', 'Abbassate le armi! Sapete chi avete davanti?', '', 28153),
(152607, 'itIT', 'Questo è fertilizzante di alta qualità! Ottimo lavoro... però, non dimenticare di lavarti le mani!', '', 28153),
(152606, 'itIT', 'Immagino che dovremmo rovinare loro la festa, giusto?', '', 28153),
(152605, 'itIT', 'Sono vele quelle all\'orizzonte? Forse hanno fatto un patto con gli Zandalari.', '', 28153),
(152604, 'itIT', 'Calcio', 'Calcio', 28153),
(152603, 'itIT', '<La scatola emette un suono neutro.>', '', 28153),
(152602, 'itIT', '<La scatola emette un suono gioioso.>', '', 28153),
(152601, 'itIT', '<La scatola emette un suono neutro.>', '', 28153),
(152600, 'itIT', 'Non ne ho idea, ma stasera offro io da bere.', '', 28153),
(152599, 'itIT', '', 'Cos\'è?', 28153),
(152598, 'itIT', '', 'Mi divertirò a teletrasportarti negli abissi del Grande Mare! Per l\'Orda!', 28153),
(152597, 'itIT', 'Co...', '', 28153),
(152596, 'itIT', '', 'A causa delle voci sugli invasori stranieri e sulla possibile presenza di spie, non si può mai essere abbastanza cauti. Obbedite ai loro ordini per evitare qualsiasi incidente.', 28153),
(152595, 'itIT', '', 'Discuteremo del pagamento più tardi, Ormeggiatore.', 28153),
(152594, 'itIT', 'Eccolo qui. Lo impacchetteremo e lo rispediremo a Roccavento.', '', 28153),
(152591, 'itIT', '', 'Oculeth... mi dispiace...', 28153),
(152590, 'itIT', 'L\'ago punta a est. Ci vediamo alle rovine, $n.', '', 28153),
(152589, 'itIT', '', 'Troppo lento, Nano.', 28153),
(152588, 'itIT', 'Stammi $gvicino:vicina;. L\'Orda è nei paraggi. Sento il loro odore.', '', 28153),
(152587, 'itIT', 'È un po\' più floreale di quanto mi aspettassi. È uscito un nuovo gusto di Elfo?', '', 28153),
(152586, 'itIT', 'Non è qui. E pare che abbiamo i Nobili Oscuri alle calcagna. Mai una gioia.', '', 28153),
(152585, 'itIT', 'Ci stiamo avvicinando. Tu pensa a tenere quei mangiamana lontani da me, $n.', '', 28153),
(152584, 'itIT', 'È proprio sotto i miei piedi... dove...?', '', 28153),
(152583, 'itIT', 'Ouch! Che trucchetto infame!', '', 28153),
(152581, 'itIT', '<La scatola emette un debole brusio.>', '', 28153),
(152580, 'itIT', '<La scatola emette un debole brusio.>', '', 28153),
(152579, 'itIT', '<La scatola emette un debole brusio.>', '', 28153),
(152578, 'itIT', 'Fermo! Li idoli nun possono essere distrutti, ma hanno liberato nu ricordo... che ho cercato di dimenticare.', '', 28153),
(152577, 'itIT', 'Quindi mi stai dicendo che c\'è un\'ENORME spada conficcata nel cuore del pianeta... e tu sei qui a ridere e scherzare? TORNA AL LAVORO!', '', 28153),
(152576, 'itIT', 'Ricorda ciò che devi fare per Azeroth.', '', 28153),
(152575, 'itIT', 'Il nostro mondo dev\'essere curato!', '', 28153),
(152574, 'itIT', 'Azeroth urla di dolore.', '', 28153),
(152573, 'itIT', 'Il nostro mondo ha bisogno di noi, campione.', '', 28153),
(152572, 'itIT', '', 'E pensare che i Troll se ne sono stati qui seduti su quello che potrebbe essere il ritrovamento archeologico del secolo!', 28153),
(152571, 'itIT', 'Tieniti le tue ossa. Qui c\'è molto potere, riesco a sentirlo, e lo prenderemo proprio da sotto il naso dell\'Orda.', '', 28153),
(152570, 'itIT', '', 'Fai attenzione a dove metti le mani. Lento ma costante.', 28153),
(152569, 'itIT', '', 'Cerca di non danneggiarlo. Sì, così...', 28153),
(152568, 'itIT', '', 'Aaaahhh... ma guarda un po\'. Un giorno diventerai $gun grande archeologo:una grande archeologa;!', 28153),
(152567, 'itIT', 'Davvero? Intendi farlo con le tue mani?', '', 28153),
(152566, 'itIT', 'Vai avanti e dai un colpo al mio elementale. Ci penserà lui a farlo per te.', '', 28153),
(152565, 'itIT', '', 'Aspetta!', 28153),
(152564, 'itIT', 'Bene. Ora, passiamo al lavoro vero.', '', 28153),
(152563, 'itIT', '', 'L\'hai graffiato! Non possiamo metterlo in esposizione in questo stato!', 28153),
(152562, 'itIT', 'Non importa, $gragazzo:ragazza;, non è messo poi così male.', '', 28153),
(152561, 'itIT', 'Le ossa mie sono stanche. La maledizione è nu grosso fardello.', '', 28153),
(152560, 'itIT', 'Il Re dei Pirati Zem\'lan nun dimenticherà mai chesto giorno.', '', 28153),
(152559, 'itIT', '', 'Forza! L\'ufficio del Maestro del Porto è qui avanti.', 28153),
(152558, 'itIT', '<Annusa> Devo anche dare una lavata al cappotto.', '', 28153),
(152557, 'itIT', 'Un bel martello solido è uno strumento indispensabile e un\'arma fidata.', '', 28153),
(152556, 'itIT', 'Non sono nulla senza il mio martello. È come se mi mancasse una mano.', '', 28153),
(152555, 'itIT', '', 'Non posso trattenerli a lungo. Prendete la mia verga e andatevene!', 28153),
(152554, 'itIT', 'Analisi', 'Analisi', 28153),
(152553, 'itIT', 'Queste caverne brulicano di Coboldi.', '', 28153),
(152552, 'itIT', 'Tutti ai remi! Ci vediamo presto.', '', 28153),
(152551, 'itIT', 'Siamo quasi pronti a levare l\'ancora. Zem\'lan nun se l\'aspetterà mai.', '', 28153),
(152550, 'itIT', 'Sì.', 'Sì.', 28153),
(152549, 'itIT', 'Sì.', 'Sì.', 28153),
(152548, 'itIT', 'Sì. Zem\'lan nun è nu capitano, è nu tiranno. L\'ammutinamento è l\'unica via.', 'Sì. Zem\'lan nun è nu capitano, è nu tiranno. L\'ammutinamento è l\'unica via.', 28153),
(152547, 'itIT', 'Allora teniamo n\'accordo?', '', 28153),
(152546, 'itIT', 'Certo, e prenderci la parte nostra del bottino.', '', 28153),
(152545, 'itIT', 'Guarda tutto chell\'oro...', 'Guarda tutto chell\'oro...', 28153),
(152544, 'itIT', 'Chesto è n\'ammutinamento, ratto di sentina! Infilzeremo le lame nostre nel corpo ossuto di Zem\'lan.', 'Chesto è n\'ammutinamento, ratto di sentina! Infilzeremo le lame nostre nel corpo ossuto di Zem\'lan.', 28153),
(152543, 'itIT', 'E ci stiamo andando esattamente incontro.', 'E ci stiamo andando esattamente incontro.', 28153),
(152542, 'itIT', 'È l\'unico destino peggiore del nostro.', '', 28153),
(152541, 'itIT', 'Le uniche persone accà sono li Schiavi dell\'Oro, vecchi membri della ciurma costretti a difendere i tesori di Zem\'lan per l\'eternità.', '', 28153),
(152540, 'itIT', 'Ci stiamo dirigendo all\'Isola d\'Oro, dove Zem\'lan trasporta i tesori saccheggiati in tutti chesti anni.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152539, 'itIT', 'Tutti ai remi!', 'Tutti ai remi!', 28153),
(152538, 'itIT', '*Some fun mine cart transitional action here.*', '', 28153),
(152537, 'itIT', 'È così luminoso accà... Rimetti le ossa mie in chel buco.', 'È così luminoso accà... Rimetti le ossa mie in chel buco.', 28153),
(152536, 'itIT', '', 'Kul Tiras è governata da diverse casate. Erano unificate sotto il comando di Daelin Marefiero, ma le cose cambiarono dopo la sua sconfitta a Theramore.', 28153),
(152535, 'itIT', '', 'L\'Ammiraglio Supremo Katherine Marefiero prese il suo posto, al comando sia della guardia che dell\'esercito.', 28153),
(152534, 'itIT', '', 'Nonostante i nostri sforzi per mantenere l\'ordine, Kul Tiras ha subito un aumento di criminalità, corruzione e pirateria. La gente sta perdendo fiducia nei Marefiero.', 28153),
(152533, 'itIT', '', '.', 28153),
(152532, 'itIT', '', '.', 28153),
(152531, 'itIT', 'Buongiorno. Desideri un posto dove riposare? Qualcosa da bere?', '', 28153),
(152530, 'itIT', 'È un onore servire Ser e Dama Norwington come loro maggiordomo. Se desideri una stanza per riposare, non esitare a chiedere.', '', 28153),
(152529, 'itIT', 'Una villa come questa richiede molto lavoro di manutenzione. Tra ferrare i cavalli, riparare rastrelli e l\'occasionale lavoretto qui e là, un fabbro non ha mai un attimo di riposo!', '', 28153),
(152528, 'itIT', 'Devi riparare qualcosa? Sono specializzato in ferri di cavallo, ma posso vedere di fare qualcosa per la tua armatura.', '', 28153),
(152527, 'itIT', '', 'Correte. CORRETE!', 28153),
(152526, 'itIT', '', 'È molto semplice. Non farti male e non dovrò curarti.', 28153),
(152525, 'itIT', '', 'Li respingerò il più a lungo possibile!', 28153),
(152524, 'itIT', 'Hai un talento naturale con la pesca, sapevo che te la saresti cavata bene! E hai ancora tutti gli arti attaccati... fantastico!', '', 28153),
(152523, 'itIT', 'I Vermisabbio sono feroci predatori che si nascondono sotto le dune. Sono pericolosi, ma le loro zanne valgono una fortuna! Prendi la mia canna da pesca e vedi cosa riesci a catturare!', '', 28153),
(152522, 'itIT', 'Le cose possono sempre peggiorare. Facciamo il possibile con ciò che abbiamo.', '', 28153),
(152521, 'itIT', 'La flotta di Kul Tiras è ai miei ordini e presto lo sarete anche voi.', '', 28153),
(152520, 'itIT', '', 'Non... non credo di poter andare avanti.', 28153),
(152519, 'itIT', '', 'Mancano ancora pochi passi. Non ti lasceremo indietro!', 28153),
(152518, 'itIT', 'Da\' loro un assaggio del potere dei nostri nuovi alleati.', '', 28153),
(152517, 'itIT', 'Nun tengo nient\'altro da dare, Zem\'lan... hai già preso tutto.', 'Nun tengo nient\'altro da dare, Zem\'lan... hai già preso tutto.', 28153),
(152516, 'itIT', 'N\'altra creatura di carne da dominare! Sarà divertente.', 'N\'altra creatura di carne da dominare! Sarà divertente.', 28153),
(152514, 'itIT', '', 'Andiamo, ci siamo quasi!', 28153),
(152513, 'itIT', '', 'Ora non ci resta che raggiungere l\'altare.', 28153),
(152512, 'itIT', 'Credete di intralciare i miei piani, ma il destino di Kul Tiras è stato deciso molto tempo fa.', '', 28153),
(152507, 'itIT', 'Ti lascerò riferire le buone notizie. Io penserò a occuparmi di quei cannoni.', '', 28153),
(152506, 'itIT', 'Quello era l\'ultimo!', '', 28153),
(152505, 'itIT', 'Ahah, giù un altro. Ne manca solo uno...', '', 28153),
(152504, 'itIT', 'FUOCO!', '', 28153),
(152503, 'itIT', 'Di certo ha attirato la loro attenzione. Tieni a bada l\'Orda mentre ricarico!', '', 28153),
(152502, 'itIT', 'Ecco, ci siamo. Copritevi le orecchie!', '', 28153),
(152501, 'itIT', 'Se solo usassero il loro potere per guarire Azeroth invece di ferirla. Ottimo lavoro.', '', 28153),
(152500, 'itIT', 'Qualcuno sta assorbendo il potere dell\'Azerite da questa zona. Devi impedirlo!', '', 28153),
(152499, 'itIT', 'E sarò io a condurci al nostro futuro glorioso sotto le maree.', '', 28153),
(152498, 'itIT', '', 'Questo potere... sarà... nostro!', 28153),
(152497, 'itIT', '', 'Nessuno può opporsi ai Sethrak con questo potere!', 28153),
(152496, 'itIT', 'Recuperate i gioielli e rimetteteli al loro posto, così potremo passare!', '', 28153),
(152495, 'itIT', 'Gli Occhi di Sethraliss sono stati rimossi!', '', 28153),
(152494, 'itIT', 'Ho tutto ciò che mi serve. Parla con me quando vuoi iniziare il rituale.', '', 28153),
(152493, 'itIT', 'L\'ho visto vagare verso la città. Speriamo nun faccia nulla di stupido, o potrebbe cacciarsi nei guai.', '', 28153),
(152492, 'itIT', 'T\'ho $gvisto:vista; andare e venire molte volte, cercando di fare qualcosa per chel piccirillo. Dovresti essere $gfiero:fiera;, di averci provato con così tanta insistenza. Nun molti accà l\'avrebbero fatto.\n\nTratta bene Kua\'fon. Sarà n\'ottimo compagno, anche se nun il più bravo a volare.', '', 28153),
(152491, 'itIT', '', 'G\'huun... desidera... chesto potere...', 28153),
(152490, 'itIT', '', 'Chesta energia ci darà il potere! Nun ci fermerai!', 28153),
(152489, 'itIT', 'Aiuto', 'Aiuto', 28153),
(152488, 'itIT', 'Sventramento', 'Sventramento', 28153),
(152487, 'itIT', 'A volte è come se l\'intera palude cercasse di ammazzarci! Fortuna che ci sei tu a fermarla!', '', 28153),
(152486, 'itIT', 'Ho un brutto presentimento... I nostri esploratori sarebbero dovuti tornare molto tempo fa. Indaga sulla causa di questo ritardo.', '', 28153),
(152484, 'itIT', '', 'Su, muoviamoci.', 28153),
(152483, 'itIT', '', 'Fu suo padre a guidarci in questa valle molti anni fa.', 28153),
(152482, 'itIT', '', 'Assolutamente no. Era un brav\'uomo, prima di iniziare a udire i sussurri.', 28153),
(152481, 'itIT', '', 'Ser Sacraonda è sempre stato così crudele?', 28153),
(152480, 'itIT', '', 'Tanti saluti all\'effetto sorpresa.', 28153),
(152479, 'itIT', '', 'Volete lasciarmi qui a morire?', 28153),
(152478, 'itIT', 'È il potere di Azshara in persona che fa pulsare questa pietra! Portala alle truppe del forte. Loro sapranno cosa fare.', '', 28153),
(152477, 'itIT', 'Grazie. Ma tu e io dovremmo andarcene da qui!', 'Grazie. Ma tu e io dovremmo andarcene da qui!', 28153),
(152476, 'itIT', 'Non intendo diventare cibo per cuccioli di pterrordattilo!', 'Non intendo diventare cibo per cuccioli di pterrordattilo!', 28153),
(152475, 'itIT', 'Il comandante vorrà la mia testa per essermi fatto catturare dalla fauna locale.', 'Il comandante vorrà la mia testa per essermi fatta catturare dalla fauna locale.', 28153),
(152474, 'itIT', 'Grazie! Credevo di essere stato cauto, ma un\'altra bestia mi è saltata addosso. Astuta.', 'Grazie! Credevo di essere stata cauta, ma un\'altra bestia mi è saltata addosso. Astuta.', 28153),
(152473, 'itIT', 'Argh, quei loro artigli fanno male!', 'Argh, quei loro artigli fanno male!', 28153),
(152472, 'itIT', 'Chesti dannati pterrordattili sono na seccatura. Nun voglio che le truppe mie diventino carne da macello!', 'Chesti dannati pterrordattili sono na seccatura. Nun voglio che le truppe mie diventino carne da macello!', 28153),
(152471, 'itIT', 'Chesti dannati pterrordattili sono na seccatura. Nun voglio che le truppe mie diventino carne da macello!', 'Chesti dannati pterrordattili sono na seccatura. Nun voglio che le truppe mie diventino carne da macello!', 28153),
(152470, 'itIT', 'Speravo di poter eliminare gli pterrordattili da una posizione rialzata, come quella collina, ma finiremmo per essere uccisi uno a uno come nulla fosse.', 'Speravo di poter eliminare gli pterrordattili da una posizione rialzata, come quella collina, ma finiremmo per essere uccisi uno a uno come nulla fosse.', 28153),
(152469, 'itIT', 'I Mogu... troveranno... altre... pietre...', '', 28153),
(152468, 'itIT', 'Il potere di questa pietra farà rivivere l\'impero dei Mogu!', '', 28153),
(152467, 'itIT', 'Bel lavoro! Erano un po\' più di quanto mi aspettassi.', '', 28153),
(152466, 'itIT', 'I Gurubashi sono entrati in no stato di frenesia assassina! Aiutiamoli nu po\'... a schiattare! Suona il gong e guardali correre!', '', 28153),
(152465, 'itIT', 'Ci sono voci di alcuni Troll infuriati, nella zona... e crediamo che un attacco sia ormai imminente. Dobbiamo sfoltire il loro numero. Suona il gong in cima alle scale per attirare la loro attenzione!', '', 28153),
(152464, 'itIT', 'Qualsiasi cosa tu voglia fare per aiutarci, sarà apprezzata.', 'Qualsiasi cosa tu voglia fare per aiutarci, sarà apprezzata.', 28153),
(152463, 'itIT', 'Dammi un\'ascia e ti taglio quello che vuoi!', '', 28153),
(152462, 'itIT', 'Che siano piante o bestie... combatterò ogni cosa!', '', 28153),
(152461, 'itIT', 'I Kul Tirani non cederanno senza combattere!', '', 28153),
(152460, 'itIT', 'Grazie per l\'aiuto.', '', 28153),
(152459, 'itIT', '', 'Abbiamo compagnia!', 28153),
(152458, 'itIT', 'VIA! VIA! VIA!', 'VIA! VIA! VIA!', 28153),
(152457, 'itIT', 'Va bene, soldati, ascoltate! Quando colpiremo la spiaggia, voglio che $n prenda il controllo del punto. Usa quella spararazzi per dar fuoco a qualsiasi cosa si muova.', 'Va bene, soldati, ascoltate! Quando colpiremo la spiaggia, voglio che $n prenda il controllo del punto. Usa quella spararazzi per dar fuoco a qualsiasi cosa si muova.', 28153),
(152456, 'itIT', 'Per l\'Alleanza!', 'Per l\'Alleanza!', 28153),
(152455, 'itIT', 'Schiacciate quegli intrusi o mi terrò il vostro indennizzo!', '', 28153),
(152454, 'itIT', 'Protocollo per Riparazioni d\'Emergenza attivo...', '', 28153),
(152453, 'itIT', 'Dolce, dolce Azerite!', '', 28153),
(152452, 'itIT', 'Scava, dolcezza, scava!', '', 28153),
(152451, 'itIT', '', 'Se Sacraonda non si accorgerà di noi, saremo a cavallo.', 28153),
(152450, 'itIT', '', 'È più... diretto.', 28153),
(152449, 'itIT', '', 'E... va bene?', 28153),
(152448, 'itIT', '', 'I Saggi delle Maree seguono questo cammino cerimoniale per ottenere la benedizione al santuario.', 28153),
(152447, 'itIT', '', 'Le tue ferite non possono guarire con quella maledizione!', 28153),
(152446, 'itIT', '', 'Questa non può essere la fine.', 28153),
(152445, 'itIT', '', 'Il vostro fallimento sarebbe la mia fine!', 28153),
(152444, 'itIT', '', 'Non dovete cadere!', 28153),
(152443, 'itIT', 'Attenzione! Livello di carburante critico!', '', 28153),
(152442, 'itIT', 'Attenzione! Utente non autorizzato rilevato.', '', 28153),
(152441, 'itIT', 'Attenzione! Ti rimangono 0 punti sulla patente.', '', 28153),
(152440, 'itIT', 'Eccone un altro, preparati!', 'Eccone un altro, preparati a sputare.', 28153),
(152439, 'itIT', 'Sputa più in alto, andrà più lontano e non mancherà il bersaglio.', 'Sputa più in alto, andrà più lontano e non mancherà il bersaglio.', 28153),
(152438, 'itIT', 'Preparati!', 'Preparati!', 28153),
(152437, 'itIT', 'Sputa appena decollano. Li colpiremo di sicuro!', 'Sputa appena decollano. Li colpiremo di sicuro!', 28153),
(152436, 'itIT', 'Nano in arrivooo!', '', 28153),
(152435, 'itIT', 'È una vergogna che l\'Azerite porti alla follia quegli elementali. Una ragione in più per porre fine a tutto questo.', '', 28153),
(152434, 'itIT', 'Alcuni Elementali della Terra sono stati infusi d\'Azerite e sono impazziti. Abbattili e assorbi tutta quella che contengono!', '', 28153),
(152433, 'itIT', 'Sono qui! Fuoco alle polveri!', '', 28153),
(152432, 'itIT', '', 'La pietra freme... le avremo tutte!', 28153),
(152431, 'itIT', '', 'Il potere di questa pietra alimenterà il nostro impero!', 28153),
(152430, 'itIT', '<Glibb ti osserva con curiosità. Brann non ha il coraggio di dirgli che non è una scimmia.>', '<Glibb ti osserva con curiosità. Brann non ha il coraggio di dirgli che non è una scimmia.>', 28153),
(152429, 'itIT', '$gBenvenuto:Benvenuta; a Nido del Falcone. Grazie a te, i mostri sono stati respinti e possiamo riconquistare il villaggio. Rimani pure quanto ti pare.', '$gBenvenuto:Benvenuta; a Nido del Falcone. Grazie a te, i mostri sono stati respinti e possiamo riconquistare il villaggio. Rimani pure quanto ti pare.', 28153),
(152428, 'itIT', 'Pare che le armi siano di origine Goblin. Comunque, dovrebbero funzionare bene contro i Sethrak.', '', 28153),
(152427, 'itIT', 'Nisha ha recuperato delle... armi interessanti, che potrebbero aiutarci contro i Sethrak, se riusciamo a capire come usarle.', '', 28153),
(152426, 'itIT', 'Non ho mai visto nulla come quei mostri prima d\'ora!', 'Non ho mai visto nulla come quei mostri prima d\'ora!', 28153),
(152425, 'itIT', 'Posso volare via da qui?', 'Posso volare via da qui?', 28153),
(152424, 'itIT', 'Purtroppo non in questo momento.\n\nHo cercato di volare via quando tutto questo casino è iniziato, ma ci hanno attaccati da terra usando la magia. Lionel si è preso un colpo sul fianco e siamo riusciti a malapena a tornare a Collefalco in vita.\n\nIl Sindaco Royston ci ha detto di rimanere fin quando la situazione non sarà migliorata.\n\nMi spiace, siamo bloccati a terra.', 'Purtroppo non in questo momento.\n\nHo cercato di volare via quando tutto questo casino è iniziato, ma ci hanno attaccati da terra usando la magia. Lionel si è preso un colpo sul fianco e siamo riusciti a malapena a tornare a Collefalco in vita.\n\nIl Sindaco Royston ci ha detto di rimanere fin quando la situazione non sarà migliorata.\n\nMi spiace, siamo bloccati a terra.', 28153),
(152423, 'itIT', 'Be\', non è quello che mi aspettavo. Sono sicuro che i nostri Maghi vorranno dargli un\'occhiata. Lavoro eccellente.', '', 28153),
(152422, 'itIT', 'I nostri rapporti indicano che l\'Orda sta pianificando il recupero di qualche tipo di artefatto da questi Sethrak. Vediamo di riuscirci prima di loro.', '', 28153),
(152421, 'itIT', 'Diamoci da fare, $n!', '', 28153),
(152420, 'itIT', 'Uaaaaaaaaaaaauuu!', '', 28153),
(152417, 'itIT', '', 'Ben fatto! Quelle cose dovrebbero starsene sottoterra.', 28153),
(152416, 'itIT', '', 'Luride creature... Stanno sacrificando i loro simili per dar vita a delle mostruosità. Fermali prima che quelle piante carnivore ci divorino!', 28153),
(152415, 'itIT', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Normale.>', '<Metti in coda il mio gruppo per una Scorreria sulle Isole in modalità Normale.>', 28153),
(152414, 'itIT', '', 'L\'Azerite... sarà... sotto il controllo... nostro!', 28153),
(152413, 'itIT', '', 'L\'Azerite si piega alla magia del sangue mia!', 28153),
(152412, 'itIT', 'Per tutte le ossa! Certo che sono pronto ad ammutinarmi. Sono settimane che aspetto!', 'Per tutte le ossa! Certo che sono pronta ad ammutinarmi. Sono settimane che aspetto!', 28153),
(152411, 'itIT', '', 'Interessante. Forse ci aiuteranno a capire lo strano fenomeno che abbiamo visto a Nazmir e le origini di questi maledetti Troll del Sangue.', 28153),
(152410, 'itIT', '', 'I nostri ricercatori hanno chiesto di tenere gli occhi aperti per qualsiasi manufatto dovessimo trovare e per evitare che cadano nelle mani dell\'Orda. Cerca qui tra le rovine.', 28153),
(152409, 'itIT', 'Nun ho mai incontrato n\'ammutinato che nun mi piacesse. Ci sto.', 'Nun ho mai incontrato n\'ammutinato che nun mi piacesse. Ci sto.', 28153),
(152407, 'itIT', 'Mi unirò volentieri all\'ammutinamento tuo. Il Re dei Pirati Zem\'lan la pagherà per avermi tradito.', 'Mi unirò volentieri all\'ammutinamento tuo. Il Re dei Pirati Zem\'lan la pagherà per avermi tradito.', 28153),
(152406, 'itIT', 'Se hai i soldi, qui troverai pane per i tuoi denti.\n\nNon rovinare gli affari degli altri e nessuno ti darà problemi. Chiaro?', 'Se hai i soldi, qui troverai pane per i tuoi denti.\n\nNon rovinare gli affari degli altri e nessuno ti darà problemi. Chiaro?', 28153),
(152405, 'itIT', '', 'Parla con qualcuno dei pezzi grossi qui in giro: Klause Ventofermo, Kane Carlyle, Clonk Ungipezzi e Fixi Lamascaltra.\n\nFai le mie veci e vedi se han bisogno di qualche favore; mi servirà anche il loro supporto.\n\nSe non c\'è altro, torno a occuparmi delle altre brave, ma preoccupate, persone qui.', 28153),
(152404, 'itIT', 'Con chi dovrei parlare?', 'Con chi dovrei parlare?', 28153),
(152403, 'itIT', 'Nun possiamo ammutinarci solo noi due. Recluta qualcun altro!', '', 28153),
(152402, 'itIT', 'Dov\'è il tuo padrone?', '', 28153),
(152401, 'itIT', 'Non sei na bestia molto educata.', '', 28153),
(152400, 'itIT', 'Me lo stavo per mangiare.', '', 28153),
(152399, 'itIT', 'Dovresti fermarti.', '', 28153),
(152398, 'itIT', 'Chello lo devi pagare!', 'Chello lo devi pagare!', 28153),
(152397, 'itIT', 'Chello nun è tuo!', 'Chello nun è tuo!', 28153),
(152396, 'itIT', 'Ehi! Sputalo fuori!', 'Ehi! Sputalo fuori!', 28153),
(152395, 'itIT', 'Le mie ossa risorgeranno di nuovo.', '', 28153),
(152394, 'itIT', 'Sorgete, servi miei! Distruggete!', '', 28153),
(152393, 'itIT', 'Venite, avvoltoi... Vi aspetta un pasto... coi fiocchi...', '', 28153),
(152392, 'itIT', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t $n lascia |cFFFF0000|Hspell:267343|h[Rilasciare]|h|r il globo!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t $n lascia |cFFFF0000|Hspell:267343|h[Rilasciare]|h|r il globo!', 28153),
(152391, 'itIT', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t Il globo viene |cFFFF0000|Hspell:267633|h[Strappato]|h|r dalle mani di $n!', '|TInterface\\ICONS\\INV_Misc_Bag_11.blp:20|t Il globo viene |cFFFF0000|Hspell:267633|h[Strappato]|h|r dalle mani di $n!', 28153),
(152390, 'itIT', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t %s |cFFFF0000|Hspell:265755|h[Rivendica]|h|r uno dei globi!', '|TInterface\\ICONS\\Item_enchantedpearl.blp:20|t %s |cFFFF0000|Hspell:265755|h[Rivendica]|h|r uno dei globi!', 28153),
(152389, 'itIT', 'Ti appenderò per i piedi e lascerò che gli avvoltoi ti divorino!', '', 28153),
(152388, 'itIT', 'Prima dobbiamo spargere la voce, così capirai davvero con chi abbiamo a che fare.', '', 28153),
(152387, 'itIT', 'Allora è ammutinamento!', '', 28153),
(152386, 'itIT', 'Ho altre domande da farti.', 'Ho altre domande da farti.', 28153),
(152385, 'itIT', 'Ehi! Smettila!', 'Ehi! Smettila!', 28153),
(152384, 'itIT', 'Va\' via!', 'Va\' via!', 28153),
(152383, 'itIT', 'Sciò, sciò!', 'Sciò, sciò!', 28153),
(152382, 'itIT', 'Smettila di fare baccano!', 'Smettila di fare baccano!', 28153),
(152381, 'itIT', 'Vieni giù di lì!', 'Vieni giù di lì!', 28153),
(152380, 'itIT', 'Un pappagallo? Niente aquiloni?', 'Un pappagallo? Niente aquiloni?', 28153),
(152379, 'itIT', '<Tan scrolla le spalle.>\n\nI pappagalli sono molto più interessanti e intelligenti di un aquilone.\n\n<Tan apre un occhio e guarda il suo volatile.>\n\nAnche se a volte gracchiano senza motivo.', '<Tan scrolla le spalle.>\n\nI pappagalli sono molto più interessanti e intelligenti di un aquilone.\n\n<Tan apre un occhio e guarda il suo volatile.>\n\nAnche se a volte gracchiano senza motivo.', 28153),
(152378, 'itIT', 'Da quando sono arrivati i Marferreo, Richard Strappavele è stato incaricato di approvare tutti i voli in entrata e uscita.\n\nQuesto dovrebbe mantenere \"sicuro\" e \"segreto\" il Covo, ma per me è solo un tentativo di tenere tutto sotto controllo.\n\nÈ lui che dovrebbe darti il permesso. Ci andrà di mezzo la mia pellaccia e le ali della mia creatura se non sarà avvisato.\n\n<Tan si china e abbassa la voce.>\n\nOppure qualcun altro potrebbe prendere il suo posto.', 'Da quando sono arrivati i Marferreo, Richard Strappavele è stato incaricato di approvare tutti i voli in entrata e uscita.\n\nQuesto dovrebbe mantenere \"sicuro\" e \"segreto\" il Covo, ma per me è solo un tentativo di tenere tutto sotto controllo.\n\nÈ lui che dovrebbe darti il permesso. Ci andrà di mezzo la mia pellaccia e le ali della mia creatura se non sarà avvisato.\n\n<Tan si china e abbassa la voce.>\n\nOppure qualcun altro potrebbe prendere il suo posto.', 28153),
(152377, 'itIT', 'Posso prendere un volo via da qui?', 'Posso prendere un volo via da qui?', 28153),
(152376, 'itIT', 'Dovrai aiutarmi. Mi hanno legato accà dopo l\'ultimo ammutinamento mio.', '', 28153),
(152375, 'itIT', 'Fantastico! Io me la squaglio!', 'Fantastico! Io me la squaglio!', 28153),
(152374, 'itIT', 'Forse... se te la senti... digli che la prossima volta gli porto nu cappello!', '', 28153),
(152373, 'itIT', 'Ti manca la tua forza mo\', eh? Vai, servitore mio. Vai e trova chel ratto di Nokano che ti ha detto di accidere la gente mia. Mordilo e ripigliati la forma da riccumpà tua.', '', 28153),
(152372, 'itIT', 'L\'Orda è qui? Da dove sono arrivati! Chi ci proteggerà?', 'L\'Orda è qui? Da dove sono arrivati! Chi ci proteggerà?', 28153),
(152371, 'itIT', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Merektha usa |cFFFF0000|Hspell:264206|h[Rintanamento]|h|r spostandosi sul campo di battaglia!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Merektha usa |cFFFF0000|Hspell:264206|h[Rintanamento]|h|r spostandosi sul campo di battaglia!', 28153),
(152370, 'itIT', 'Grazie $gamico:amica;. Credevo di essere spacciato!', 'Grazie $gamico:amica;. Credevo di essere spacciato!', 28153),
(152369, 'itIT', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t $n è $gavvolto:avvolta; da un |cFFFF0000|Hspell:263958|h[Groviglio di Serpenti]|h|r! $gLiberalo:Liberala;!', '|TInterface\\Icons\\ABILITY_HUNTER_SNAKETRAP.BLP:20|t $n è $gavvolto:avvolta; da un |cFFFF0000|Hspell:263958|h[Groviglio di Serpenti]|h|r! $gLiberalo:Liberala;!', 28153),
(152368, 'itIT', 'Il giorno in cui il Porto di Zem\'lan fu maledetto... molto tempo fa.', '', 28153),
(152367, 'itIT', 'Il medaglione ti donerà na visione del passato mio.', '', 28153),
(152366, 'itIT', 'G-grazie. M-meeki è un buon amico.', 'G-grazie. M-meeki è un buon amico.', 28153),
(152365, 'itIT', 'Ti ho deluso, Korthek...', '', 28153),
(152364, 'itIT', 'A quanto pare desideri morire! Ti accontenterò!', '', 28153),
(152363, 'itIT', 'Nessuno... può... fermarci...', '', 28153),
(152362, 'itIT', 'Insolente! Pagherai per quest\'intrusione!', '', 28153),
(152361, 'itIT', '', 'Il tuo comandante attende sul campo di battaglia.', 28153),
(152360, 'itIT', 'Questa non è... la fine...', 'Questa non è... la fine...', 28153),
(152359, 'itIT', 'Abbiamo trovato una strana pergamena che dovrebbe servire a evocare un essere di incredibile potere. Un grosso gruppo di non morti si sta radunando sulla costa. Vediamo se questa pergamena è davvero così potente.', '', 28153),
(152358, 'itIT', 'Questa non è... la fine...', 'Questa... non è... la fine.', 28153),
(152357, 'itIT', 'La mia vita... per l\'impero!', 'La mia vita... per l\'impero!', 28153),
(152356, 'itIT', 'Non può essere...', 'Non può essere...', 28153),
(152355, 'itIT', 'Le sabbie... si diffonderanno...', 'Le sabbie... si diffonderanno...', 28153),
(152354, 'itIT', 'La mia morte... sarà... vendicata...', 'La mia morte sarà vendicata...', 28153),
(152353, 'itIT', 'Korthek... ti ho deluso...', 'Korthek... ti ho deluso...', 28153),
(152352, 'itIT', 'Non... avete... vinto...', 'Non... avete... vinto...', 28153),
(152351, 'itIT', 'Non ci... fermerete...', 'Non ci... fermerete...', 28153),
(152349, 'itIT', 'La mia vita... per l\'impero!', 'La mia vita... per l\'impero!', 28153),
(152348, 'itIT', 'Non può essere...', 'Non può essere...', 28153),
(152347, 'itIT', 'Le sabbie... si diffonderanno...', 'Argh... le sabbie... si diffonderanno...', 28153),
(152346, 'itIT', 'La mia morte... sarà... vendicata...', 'La mia morte... sarà... vendicata...', 28153),
(152345, 'itIT', 'Korthek... ti ho deluso...', 'Korthek... ti ho deluso...', 28153),
(152344, 'itIT', 'Non... avete... vinto...', 'Non... avete... vinto...', 28153),
(152343, 'itIT', 'Non ci... fermerete...', 'Non ci... fermerete...', 28153),
(152342, 'itIT', '', 'Ottimo lavoro. Come sempre, sei una garanzia per un lavoro ben fatto.', 28153),
(152341, 'itIT', '', 'I Troll del Sangue stanno attaccando Forte Vittoria. Mostragli la giusta punizione per le loro incursioni!', 28153),
(152340, 'itIT', 'Sbrigatevi, ragazzi! L\'Azerite non si farà esplodere da sola!', '', 28153),
(152339, 'itIT', '', 'Hanno incendiato Brennadam. Nessuno di noi tornerà a casa.', 28153),
(152338, 'itIT', 'Dobbiamo andare più veloci!', '', 28153),
(152337, 'itIT', 'Ah, mi ricordi un giovane Hozen che ho incontrato una volta. Credeva di essere un re delle scimmie o qualcosa del genere. Non faceva che punzecchiarmi.', '', 28153),
(152336, 'itIT', 'Se credi di potermi infastidire, ti sbagli di grosso.', '', 28153),
(152335, 'itIT', 'Penso che dovremmo commerciare con gente di ogni razza e credo... eccetto i Naga. Creature orribili.', '', 28153),
(152334, 'itIT', 'Se trovassi dei potenti manufatti, portali da me e non tentare di utilizzarli senza la mia supervisione.', '', 28153),
(152333, 'itIT', 'Mmm. È meglio che i manufatti di grande potere rimangano nelle mani degli anziani, non di un avventuriero qualunque.', '', 28153),
(152332, 'itIT', 'Mai sottovalutare il valore o il potere di qualcosa più antico di due secoli.', '', 28153),
(152331, 'itIT', 'Bla bla bla. Veniamo al sodo.', '', 28153),
(152330, 'itIT', 'Quali sono le tue tariffe e le spese funerarie stimate?', '', 28153),
(152329, 'itIT', 'Ah, bene! Avevo giusto bisogno del tuo aiuto.', '', 28153),
(152328, 'itIT', 'Ti dono... la Catena di Rocce!', '', 28153),
(152327, 'itIT', 'State guardando il futuro, ragazzi!', '', 28153),
(152326, 'itIT', 'Congratulazioni, ragazzi, diventeremo ricchi!', '', 28153),
(152325, 'itIT', '', 'Andiamo! Non fare il paurosauro!', 28153),
(152324, 'itIT', 'Mai accettare doni dall\'Impero Nero.', '', 28153),
(152323, 'itIT', 'Forse ci vedremo ancora sul campo di battaglia. Fianco a fianco, schiena contro schiena... in inferiorità numerica, svantaggiati e mal equipaggiati. Ahahah!', '', 28153),
(152322, 'itIT', 'Tocca a me, vieni a pigliare il pesce!', '', 28153),
(152321, 'itIT', 'Siediti, sorella!', '', 28153),
(152320, 'itIT', 'Sei così immatura!', '', 28153),
(152319, 'itIT', 'Ah! Hai spaventato i pesci!', '', 28153),
(152318, 'itIT', '', 'Kraaa! Sono Pa\'ku! Uooosh!', 28153),
(152317, 'itIT', '', 'Ehi, guarda, sono Gral!', 28153),
(152316, 'itIT', '', 'Taz\'okun!', 28153),
(152315, 'itIT', '', 'Uoooooo!', 28153),
(152314, 'itIT', 'Buona fortuna. Cerca di non morire.', '', 28153),
(152313, 'itIT', 'Guardati sempre le spalle, o fatti un guscio.', '', 28153),
(152312, 'itIT', 'La... pagherai...', 'La... pagherai...', 28153),
(152311, 'itIT', 'Non... vale...', 'Non... vale...', 28153),
(152310, 'itIT', 'Discepoli! Gli intrusi si avvicinano alle sacre pozze!', '', 28153),
(152309, 'itIT', 'No... È mio...', 'No... È mio...', 28153),
(152308, 'itIT', 'Come... osi...', 'Come... osi...', 28153),
(152307, 'itIT', 'Mi prenderò la tua pelle come pagamento!', 'Mi prenderò la tua pelle come pagamento!', 28153),
(152306, 'itIT', 'Apprezzo le zuffe. A volte mi sono cimentato anche in qualche scazzottata e addirittura un paio di risse. Ahah.', '', 28153),
(152305, 'itIT', 'Per te tariffa doppia!', 'Per te tariffa doppia!', 28153),
(152304, 'itIT', 'Il conto è: una gamba e un braccio!', 'Il conto è: una gamba e un braccio!', 28153),
(152303, 'itIT', 'Ehi! Questo ti costerà caro!', 'Ehi! Questo ti costerà caro!', 28153),
(152302, 'itIT', 'Sono stato pugnalato alle spalle da più razze di quante tu possa immaginare, quindi non farti venire strane idee.', '', 28153),
(152301, 'itIT', 'La morte è l\'unica cosa che Zem\'lan può offrire... e a molti viene pure negato chesto lusso.', '', 28153),
(152300, 'itIT', 'Estrazione', 'Estrazione', 28153),
(152299, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(152298, 'itIT', '', 'Non mi fermerò fin quando la testa di Ser Sacraonda non sarà appesa a queste mura.', 28153),
(152297, 'itIT', '', 'Questa è proprio la potenza di fuoco che ci serve!', 28153),
(152296, 'itIT', 'Eheh... Hai vinto... tu...', 'Eheh... Hai vinto... tu...', 28153),
(152295, 'itIT', 'La... pagherai...', 'La... pagherai...', 28153),
(152294, 'itIT', 'Non posso... essere... sconfitto...', 'Non posso... essere... sconfitta...', 28153),
(152293, 'itIT', 'Ma... sono io il capo...', 'Ma... sono io il capo...', 28153),
(152292, 'itIT', 'Ti vuoi candidare a capo del Covo, eh? AH! Ti batterò come ho fatto con l\'ultimo!', 'Ti vuoi candidare a capo del Covo, eh? AH! Ti batterò come ho fatto con l\'ultimo!', 28153),
(152291, 'itIT', 'Sono io il capo di questo posto! Farai meglio a metterti in riga!', 'Sono io il capo di questo posto! Farai meglio a metterti in riga!', 28153),
(152290, 'itIT', 'Fate silenzio. Meeki sta bene e sto cercando di dormire qui.', 'Fate silenzio. Meeki sta bene e sto cercando di dormire qui.', 28153),
(152289, 'itIT', 'Ti farò fare un giro di chiglia!', 'Ti farò fare un giro di chiglia!', 28153),
(152288, 'itIT', 'Nessuno può far rotta contro i Marferreo!', 'Nessuno può far rotta contro i Marferreo!', 28153),
(152287, 'itIT', 'Come osi!', 'Come osi!', 28153),
(152286, 'itIT', 'Se trovassi dei tesori lungo la strada, non dimenticare di prenderli. Ti ricompenseremmo a dovere.', 'Se trovassi dei tesori lungo la strada, non dimenticare di prenderli. Ti ricompenseremmo a dovere.', 28153),
(152285, 'itIT', 'La pagherai...', 'La pagherai...', 28153),
(152284, 'itIT', 'Nessuno può sfidare i Marferreo...', 'Nessuno può sfidare i Marferreo...', 28153),
(152283, 'itIT', 'Ti... prenderò...', 'Ti... prenderò...', 28153),
(152282, 'itIT', 'Perdonami... capo...', 'Perdonami... capo...', 28153),
(152281, 'itIT', 'Non dovresti essere qui!', 'Non dovresti essere qui!', 28153),
(152280, 'itIT', 'Dove credi di ficcare il naso?', 'Dove credi di ficcare il naso?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152279, 'itIT', 'Non appartieni a questo posto!', 'Non appartieni a questo posto!', 28153),
(152278, 'itIT', 'Ehi!', 'Ehi!', 28153),
(152277, 'itIT', '', 'Sapevi che le pinne dello squalo balena sono ottime per la zuppa? Prevengono la decomposizione delle scaglie! Oh, d-d-di cosa stavamo parlando?', 28153),
(152276, 'itIT', '', 'Be\', con tutti intendevo quelli con soldi da spendere. Umani, Goblin, Tauren, Elfi, non importa. Ciò che conta sono i soldi.\n\n<Cesi ti scruta dall\'alto in basso>\n\nOh, volevi sapere se accetterei anche l\'Orda.\n\nAscolta, devo campare in qualche modo. Se trovassi delle ancore arrugginite abbandonate da qualche nave, le venderei al primo che passa. Quando sarò il capo, tutti potranno fare affari nel Covo.\n\nTu non vuoi avere nulla a che fare con quei pirati Marferreo, vero?\n\nFidati di me, sarà fantastico.', 28153),
(152275, 'itIT', 'I miei figli tengono maniere migliori delle tue.', '', 28153),
(152274, 'itIT', 'Cosa vuoi dire con aprire il commercio a tutti?', 'Cosa vuoi dire con aprire il commercio a tutti?', 28153),
(152271, 'itIT', 'A meno che tu non voglia sacrificare chel dito a me, ti consiglio di nun toccarmi.', '', 28153),
(152270, 'itIT', 'La locanda della zona è piena di rifugiati, ma mi avanza una stanza se hai bisogno di un posto dove riposare.', '', 28153),
(152269, 'itIT', 'Ricorda, se trovi qualcosa di valore, portalo al vecchio Jani.', '', 28153),
(152268, 'itIT', 'Quando te ne andrai, posso avere la roba tua?', '', 28153),
(152266, 'itIT', 'Che tu possa trovare sempre amici bassolocati. Ah!', '', 28153),
(152265, 'itIT', 'Ben fatto! Queste terre sono più al sicuro grazie ai tuoi sforzi.', '', 28153),
(152264, 'itIT', 'Le nostre spie hanno identificato una pericolosa minaccia nella zona. Trovala, e neutralizzala!', '', 28153),
(152263, 'itIT', '', 'Riassemblateli e uccidete il suo animaletto, prima che non ci rimanga nulla per respingere la flotta di Bracescura!', 28153),
(152262, 'itIT', '', 'Era un Tortolliano così orgoglioso, anche se un po\' troppo grande per il suo guscio, se capisci ciò che intendo. È un peccato sia finito divorato da uno squalo.', 28153),
(152261, 'itIT', '', 'Quasi non mi ero accorta che stava russando. Sai, la sua voce è piuttosto roca. Un po\' come quella del mio secondo nipote.', 28153),
(152260, 'itIT', '', 'Alcuni dicono che ho la tendenza a divagare. Mia sorella era molto peggio, però. Sapevi che una volta si addormentò a metà di una frase?', 28153),
(152259, 'itIT', 'Un cumulo di spazzatura è solo nu posto dove tenere le cose tue mentre vai in giro a cercare altre cose.', '', 28153),
(152258, 'itIT', '', 'Gli avventurieri sono così gentili di questi tempi.', 28153),
(152257, 'itIT', '', 'Non è stato carino?', 28153),
(152256, 'itIT', '', 'Torna dalla vecchia Nola qualche volta.', 28153),
(152255, 'itIT', '', 'Questo mi ricorda una storia...', 28153),
(152254, 'itIT', '', 'Sei proprio un tipo vivace!', 28153),
(152253, 'itIT', '', 'È bello vederti, tesoro.', 28153),
(152252, 'itIT', 'Tansbohgrificatore. Trasforma idee terribili in qualcosa di poco meglio!', 'Tansbohgrificatore. Trasforma idee terribili in qualcosa di poco meglio!', 28153),
(152251, 'itIT', 'Kaja\'cola, ora con vera acqua!', 'Kaja\'cola, ora con vera acqua!', 28153),
(152250, 'itIT', '', 'Dai tuoi occhi noto che apprezzeresti una bella storia.', 28153),
(152249, 'itIT', '', 'Raggiungimi a nord di questo buco infernale quando avrai la verga. Ti basterà seguire la scia di morti.', 28153),
(152248, 'itIT', 'Continua così e scoprirai perché mi chiamano brontolone.', '', 28153),
(152246, 'itIT', 'Salute, riccumpà.', '', 28153),
(152243, 'itIT', 'Come dico sempre, la spazzatura di uno può essere il Loa di n\'altro.', '', 28153),
(152241, 'itIT', '', 'Troppi pericoli risiedono a Nazmir. Mo\' ce ne sta uno di meno.', 28153),
(152239, 'itIT', '', 'Cosa sono quei cosi? Fortuna che i nostri ingegneri hanno proprio quello che ci serve. Bruciali tutti prima che invadano i nostri accampamenti!', 28153),
(152232, 'itIT', 'La tua amicizia conta molto per noi. Ora queste dune sono più sicure grazie a te.', '', 28153),
(152231, 'itIT', 'La nostra carovana ha scoperto qualcosa di pericoloso tra le dune. Confido che te ne occuperai tu.', '', 28153),
(152230, 'itIT', 'Taelia, questo fardello spetta a te. Io prenderò Samuel e ci rivedremo al santuario non appena possibile.', '', 28153),
(152229, 'itIT', 'Comunione', 'Comunione', 28153),
(152228, 'itIT', 'Sapevo di poter contare su di te. Andiamo, ci vediamo lì!', 'Sapevo di poter contare su di te. Andiamo, ci vediamo lì!', 28153),
(152227, 'itIT', 'Auguri a scacciarli via! Io contrabbando merce, non sono un mercenario.', 'Auguri a scacciarli via! Io contrabbando merce, non sono una mercenaria.', 28153),
(152226, 'itIT', 'Allora magari è tempo che i Marferreo se ne vadano!', 'Allora magari è tempo che i Marferreo se ne vadano!', 28153),
(152225, 'itIT', 'I Marferreo stanno prosciugando tutti i miei averi, Cesi. Riesco a malapena ad arrivare a fine mese.', 'I Marferreo stanno prosciugando tutti i miei averi, Cesi. Riesco a malapena ad arrivare a fine mese.', 28153),
(152224, 'itIT', 'Ora... che la caccia abbia inizio!', '', 28153),
(152223, 'itIT', '', 'Ascolta, possiamo ancora ricavarne qualche profitto!', 28153),
(152222, 'itIT', '', 'Questa gente sta cercando di fuggire. Devono esserci altri sopravvissuti da qualche parte.', 28153),
(152221, 'itIT', 'Questa è una prova.', 'Questa è una prova.', 28153),
(152220, 'itIT', 'Sarà meglio colpire ora, prima che le voci raggiungano Ser Sacraonda.', '', 28153),
(152219, 'itIT', '|cFF0000FF(Missione)|r Fai rotta verso Nazmir.', '|cFF0000FF(Missione)|r Fai rotta verso Nazmir.', 28153),
(152218, 'itIT', '', 'Questa nave è al tuo comando, $n. La ciurma è pronta a ogni eventualità.', 28153),
(152217, 'itIT', 'Dove dovremmo concentrare i nostri sforzi?', '', 28153),
(152216, 'itIT', 'Ehi, capita. La prossima volta che vedrete quei ragazzi, pensate a quanto sarà dolce la vendetta.', '', 28153),
(152215, 'itIT', 'Non prendetevela troppo, abbiamo comunque un carico decente.', '', 28153),
(152214, 'itIT', 'Tutti a bordo! Dobbiamo andarcene da qui prima di perdere la nave.', '', 28153),
(152213, 'itIT', 'Non si può vincere sempre. Li prenderemo la prossima volta.', '', 28153),
(152212, 'itIT', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t Alcune |cFFFF0000|Hspell:267931|h[Guardie Difensive]|h|r subiscono un sovraccarico!', '|TInterface\\Icons\\ABILITY_THUNDERKING_OVERCHARGE.BLP:20|t Alcune |cFFFF0000|Hspell:267931|h[Guardie Difensive]|h|r subiscono un sovraccarico!', 28153),
(152211, 'itIT', 'Ugh, ne abbiamo pigliata abbastanza. Jammucenne.', '', 28153),
(152210, 'itIT', 'Nun si può vincere ogni scontro. Eh, così è la vita.', '', 28153),
(152209, 'itIT', 'Bah! Mo\' dobbiamo andare. Li piglierete la prossima volta.', '', 28153),
(152208, 'itIT', 'Ottimo lavoro oggi! Gliel\'avete fatta vedere, ahahah!', '', 28153),
(152207, 'itIT', 'Abbiamo finito! Ué, sparate due colpi a chella nave dell\'Alleanza mentre ce ne andiamo, ahah!', '', 28153),
(152206, 'itIT', 'La cambusa è piena. Spiegate le vele e torniamocene a casa!', '', 28153),
(152205, 'itIT', 'Chesto è tutto ciò di cui abbiamo bisogno. È ora di andarcene! Ahah!', '', 28153),
(152204, 'itIT', 'Pigliate ciò che riuscite. Toccherà partire in fretta!', '', 28153),
(152203, 'itIT', 'Pare che l\'altra nave partirà presto. Dobbiamo muoverci in fretta.', '', 28153),
(152202, 'itIT', 'Sembra che chella nave di Kul Tirani sia quasi piena. Dobbiamo andarcene alla svelta.', '', 28153),
(152201, 'itIT', 'Ci siete quasi. Tenete giù la capa ancora nu poco.', '', 28153),
(152200, 'itIT', 'La cambusa è quasi piena, ancora nu poco e abbiamo finito.', '', 28153),
(152199, 'itIT', 'Abbiamo quasi finito. State andando bene!', '', 28153),
(152198, 'itIT', 'Oh! Nun riesco nemmeno a stare in piedi con chesto terremoto. Ci sta nu potente Elementale della Terra là fuori, alla ricerca d\'Azerite proprio come noi.', '', 28153),
(152197, 'itIT', 'Il vento sta distruggendo tutto quanto... Scommetto che ci sta n\'Elementale dell\'Aria accà vicino. Probabilmente tiene pure nu sacco d\'Azerite... pronta per essere presa!', '', 28153),
(152196, 'itIT', 'Ah, chesta tormenta dev\'essere stata causata da qualche Signore dell\'Acqua. Accidetelo velocemente. Odio il freddo.', '', 28153),
(152195, 'itIT', 'Uhhh, comincia a fare caldo accà. Dev\'essere opera di qualche Signore del Fuoco arrivato per pigliare l\'Azerite nostra. Spegnetelo, prima che bruci le vele. Ahahah!', '', 28153),
(152194, 'itIT', 'Ci dev\'essere nu Signore Elementale dietro a tutto chesto. Accidetelo, e pigliate l\'Azerite sua!', '', 28153),
(152193, 'itIT', 'Gli elementi sono contro di noi chest\'oggi. Probabilmente stanno cercando l\'Azerite pure loro.', '', 28153),
(152192, 'itIT', 'Ué, abbiamo attirato l\'attenzione di potenti elementali. Tenete gli occhi aperti per il capo loro!', '', 28153),
(152191, 'itIT', 'Chesto tempo nun è normale. Ci dev\'essere nu potente elementale in cerca dell\'Azerite nostra!', '', 28153),
(152190, 'itIT', 'Manca all\'incirca metà nave da riempire. Tenete gli occhi aperti.', '', 28153),
(152189, 'itIT', 'State andando alla grande. Siamo già a metà strada!', '', 28153),
(152188, 'itIT', 'La cambusa è mezza piena. Continuiamo così e avremo finito a breve.', '', 28153),
(152187, 'itIT', 'Ohhh, le cose si stanno per fare interessanti.', '', 28153),
(152186, 'itIT', 'Sono appena arrivati dei nuovi amici, eheh.', '', 28153),
(152185, 'itIT', 'Ué, occhi aperti! Teniamo compagnia.', '', 28153),
(152184, 'itIT', 'Chesto è il posto. L\'Azerite vi sta aspettando. Andate a pigliarla!', '', 28153),
(152183, 'itIT', 'Abbiamo attraccato. Nun fateve ammazzare là fuori, mi raccomando. Ahah!', '', 28153),
(152182, 'itIT', 'Siamo arrivati. Attiveremo il rilevatore in men che nun si dica.', '', 28153),
(152181, 'itIT', 'Ué, ci sta nu sacco d\'Azerite là. Sarà meglio che andate a vedere.', '', 28153),
(152180, 'itIT', 'Nu grosso frammento d\'Azerite è appena emerso dal terreno. Andate a vedere!', '', 28153),
(152179, 'itIT', 'Ué, il rilevatore sta uscendo pazzo! Ci dev\'essere nu grosso giacimento d\'Azerite là fuori.', '', 28153),
(152178, 'itIT', 'Ah ah! Mo\' siamo pienamente operativi! Sto segnando sulla mappa i giacimenti d\'Azerite.', '', 28153),
(152177, 'itIT', 'Il rilevatore è in funzione! Cercate le zone ad alta concentrazione di Azerite sulla mappa.', '', 28153),
(152176, 'itIT', 'Stavo solo riposando gli occhi! Torno subito al lavoro!', '', 28153),
(152175, 'itIT', 'D\'accordo, capo. Torno in miniera.', '', 28153),
(152174, 'itIT', 'Ho tanto... sonno...', '', 28153),
(152173, 'itIT', 'Ahi! Va bene, $n: torno al lavoro!', '', 28153),
(152172, 'itIT', 'Eliminate i Malefici del Vudù e i loro Totem dell\'Adescamento Magico.', 'Eliminate i Malefici del Vudù e i loro Totem dell\'Adescamento Magico.', 28153),
(152171, 'itIT', 'Altro continente, altro demone da cacciare.', '', 28153),
(152170, 'itIT', 'Ah! Non mi deludete mai. È la cosa che apprezzo di più in una ciurma.', '', 28153),
(152169, 'itIT', 'Qui abbiamo finito. Ottimo lavoro, torniamo a casa.', '', 28153),
(152168, 'itIT', 'Tutte le casse di Azerite sono piene! Ora andiamocene da qui prima che se ne accorgano.', '', 28153),
(152167, 'itIT', 'Abbiamo finito! Accidenti, che bottino. Gran bel lavoro là fuori.', '', 28153),
(152166, 'itIT', 'L\'Orda ci ha quasi battuto. Prendete quell\'Azerite il più in fretta possibile!', '', 28153),
(152165, 'itIT', 'Io vado... da Xibala...', '', 28153),
(152164, 'itIT', 'Pare che l\'Orda sia pronta a partire. Ci prenderanno alla sprovvista se non ce ne andiamo in fretta.', '', 28153),
(152163, 'itIT', 'L\'Orda ha già messo le mani su un sacco di Azerite. Voi cercate di recuperarne il più possibile.', '', 28153),
(152162, 'itIT', 'Non vorrei allarmarvi, ma la nave dell\'Orda sembra quasi piena e, una volta che lo sarà del tutto, dovremo salpare anche noi.', '', 28153),
(152161, 'itIT', 'Abbiamo quasi finito qui! Occhi e orecchie aperti... mi raccomando.', '', 28153),
(152160, 'itIT', 'Che bottino splendente! Ancora un po\' di quelle rocce e avremo finito.', '', 28153),
(152159, 'itIT', 'La cambusa è quasi piena di Azerite, issate le vele! Saremo pronti a salpare non appena avrete finito.', '', 28153),
(152158, 'itIT', 'Ehi, abbiamo quasi finito qui! Ancora un po\' e potremo salpare di nuovo.', '', 28153),
(152157, 'itIT', 'Perché la terra sta tremando? Sto per sentirmi male. Abbiamo localizzato degli Elementali della Terra, quindi c\'è un Signore Elementale dietro a tutto questo. Occupatevi di questa minaccia prima di pranzo.', '', 28153),
(152156, 'itIT', 'Le vele non dureranno a lungo con questo uragano. Dev\'essere colpa di un Signore Elementale e dei suoi servitori alla ricerca di Azerite. Non sarà facile salpare finché saranno qui.', '', 28153),
(152155, 'itIT', 'Ehi, e-eroi? Un Signore dell\'Acqua ha mandato le sue truppe a rubare la nostra Azerite e io sto c-congelando. Pensateci voi ad abbatterli, i-io non ho l\'abbigliamento adatto.', '', 28153),
(152154, 'itIT', 'Comincia a fare davvero caldo. Che diavolo sta... Oh. Ora si spiega tutto. Un Signore del Fuoco ha mandato le sue forze alla ricerca di Azerite. Fantastico!', '', 28153),
(152153, 'itIT', 'Abbiamo raggiunto la metà! Continuate così e saremo fuori di qui in un batter d\'occhio.', '', 28153),
(152152, 'itIT', 'La cambusa è mezza piena di Azerite. State andando alla grande.', '', 28153),
(152151, 'itIT', 'Sei su un terreno sacro!', '', 28153),
(152150, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(152149, 'itIT', 'Il rilevamento puntava a queste rovine. L\'accampamento dell\'Orda è alle pendici della collina a nord-est, quindi sarà meglio muoverci in fretta.\n\nPrenderemo il Soffio di Xibala prima di loro, te lo posso assicurare.\n\nFammi sapere quando sei $gpronto:pronta; a iniziare il rilevamento.', '', 28153),
(152148, 'itIT', 'Il rilevatore è in azione! Guardate la mappa per vedere dove si trova l\'Azerite.', '', 28153),
(152147, 'itIT', 'Rilevatore attivato. Segnerò la posizione dell\'Azerite sulla mappa. Non c\'è di che.', '', 28153),
(152146, 'itIT', 'Abbiamo localizzato una formazione di cristalli d\'Azerite nelle vicinanze. Probabilmente è la causa del terremoto.', '', 28153),
(152145, 'itIT', 'Fantastico! C\'è un sacco di Azerite vicino a noi. Sarà meglio controllare prima che lo faccia l\'Orda.', '', 28153),
(152144, 'itIT', 'Ancore in sicurezza. Siamo pronti! Noi attiviamo il Rilevatore d\'Azerite, voi pensate ai cattivi.', '', 28153),
(152143, 'itIT', 'La nave è attraccata! Godetevi la vostra avventura mentre noi pensiamo ad attivare il rilevatore.', '', 28153),
(152142, 'itIT', 'Questo vento continua a scompigliarmi i capelli. Prendiamo l\'Azerite e andiamocene in fretta.', '', 28153),
(152141, 'itIT', 'Ehi, sembra che ci sia un Signore Elementale sulle tracce dell\'Azerite che stiamo cercando. Io me ne starò sottocoperta mentre voi vi occuperete di questa... situazione.', '', 28153),
(152140, 'itIT', 'Sembra che l\'Azerite abbia attirato le attenzioni di alcune forze elementali. Forse un Signore Elementale ha adocchiato le nostre scorte, ma chi trova tiene, giusto?', '', 28153),
(152139, 'itIT', 'Sembra che anche l\'Orda abbia trovato questo posto. Una loro nave ha appena attraccato.', '', 28153),
(152138, 'itIT', 'Uh... l\'Orda è arrivata a farci compagnia. Guardatevi le spalle, intesi?', '', 28153),
(152137, 'itIT', 'Vedo una nave con dell\'oro... dappertutto. Sì, sono gli Zandalari. L\'Orda è qui, fate attenzione.', '', 28153),
(152136, 'itIT', 'Una volta ero un avventuriero come te... e poi sono migliorato. Ahah.', '', 28153),
(152135, 'itIT', 'Sembri un tipo che ne ha passate tante. Dovremmo condividere le nostre storie.', '', 28153),
(152134, 'itIT', 'Ricordo la grande guerra tra Re Raka e sua sorella, la Regina Tola. O almeno, ricordo qualcosa. Sono quasi sicuro sia avvenuta. Diciamo metà e metà.', '', 28153),
(152133, 'itIT', 'Mi ricordi un tizio con cui avevo assaltato le spiagge di Krasarang durante la terza dinastia. È un peccato ciò che quei Mogu gli hanno fatto.', '', 28153),
(152132, 'itIT', 'Non è il momento di Contadibecco! Kraaa!', '', 28153),
(152131, 'itIT', 'Ecco perché mi piace lavorare da solo.', '', 28153),
(152130, 'itIT', 'Quando hai detto di chiamarti Stroncavile, pensavo intendessi uno che stronca i vili, non il contrario.', '', 28153),
(152129, 'itIT', 'Ora di farli fuori!', '', 28153),
(152128, 'itIT', '\"Andiamo nella giungla\", mi hai detto, \"a vedere il panorama\". Dovevo immaginare che la tua limitatezza ci avrebbe messo nei guai.', '', 28153),
(152127, 'itIT', 'Se moriamo, sarà colpa tua.', '', 28153),
(152126, 'itIT', 'Ho sentito dire che eri qui in giro.$b$bGrazie a una piccola... intromissione... da parte di Marius, siamo finiti in questo umido buco infernale pieno di cosi che masticano ossa per trovare quel maledetto demone.$b$bAiutaci e potrai tenerti qualsiasi cosa di valore troverai sul suo corpo.$b$bA noi interessa solo il pezzo di carta che possiede. Nulla che valga la pena leggere.', '', 28153),
(152125, 'itIT', 'Kraaa! Tutti tuoi!', '', 28153),
(152124, 'itIT', 'Contadibecco prende del pesce?', '', 28153),
(152123, 'itIT', 'Basta colpire! Mio Umano!', '', 28153),
(152122, 'itIT', 'Voi non imparate mai.', '', 28153),
(152121, 'itIT', 'Forse se non glielo avessi detto così spesso. Kraaa!', '', 28153),
(152120, 'itIT', 'Quel bottino... sarà sempre mio...', 'Quel bottino... sarà sempre mio...', 28153),
(152119, 'itIT', '', 'Uh, ahia, mi hai preso.', 28153),
(152118, 'itIT', '', 'Vieni qui, Contadibecco, smettila di fare il pigro!', 28153),
(152117, 'itIT', '', 'Indietro, uccellaccio, non ho bisogno del tuo aiuto!', 28153),
(152116, 'itIT', '', 'Non mi ha fatto neanche un graffio. È questo il meglio che sai fare, Skipper?', 28153),
(152115, 'itIT', 'AH! Cercavo proprio l\'occasione per sfogarmi un po\'!', 'AH! Cercavo proprio l\'occasione per sfogarmi un po\'!', 28153),
(152114, 'itIT', '', 'Ero gentilissima... finché non si sono rifiutati di fare ciò che dicevo...', 28153),
(152113, 'itIT', '', 'Cosa intendi con \"voi\"?', 28153),
(152112, 'itIT', '', 'Lasceranno la mia nave? Puoi giurare che ricostruirò il Grande Corno e impalerò ogni singolo traditore all\'albero maestro!', 28153),
(152111, 'itIT', '', 'Inutili sacchi di letame!', 28153),
(152110, 'itIT', 'Lei... dominerà... per sempre...', 'Lei dominerà... per sempre...', 28153),
(152109, 'itIT', 'Sconfitto... argh... da feccia... come te!', 'Sconfitta... da feccia come te!', 28153),
(152108, 'itIT', 'L\'Orda... sarà sempre... sua...', 'L\'Orda... sarà sempre... sua...', 28153),
(152107, 'itIT', 'Oh, no, di nuovo...', 'Non... di nuovo...', 28153),
(152106, 'itIT', 'La morte... è l\'unica via!', 'Ah! La morte è l\'unica via!', 28153),
(152105, 'itIT', 'Le senti le urla?', 'Ahahah! Le senti le urla?', 28153),
(152104, 'itIT', 'Niente sopravvissuti!', 'Niente sopravvissuti!', 28153),
(152103, 'itIT', 'Per la Dama Oscura!', 'Per la Dama Oscura!', 28153),
(152102, 'itIT', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(152101, 'itIT', 'Lok narash!', 'Lok narash!', 28153),
(152100, 'itIT', 'Gakarah ma!', 'Gakarah ma!', 28153),
(152099, 'itIT', 'Vittoria o morte!', 'Vittoria o morte!', 28153),
(152098, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(152097, 'itIT', 'Morte ai nostri nemici!', 'Morte ai nostri nemici!', 28153),
(152096, 'itIT', 'Morirai in questo giorno!', 'Morirai in questo giorno!', 28153),
(152095, 'itIT', 'Una morte... onorevole.', 'Una morte... onorevole...', 28153),
(152094, 'itIT', 'Antenati... arrivo...', 'Antenati... arrivo...', 28153),
(152093, 'itIT', 'Perderete... questa guerra...', 'Perderete... questa guerra...', 28153),
(152092, 'itIT', 'La vostra ora... giungerà...', 'La vostra ora... giungerà...', 28153),
(152091, 'itIT', 'Muoio... da guerriero...', 'Muoio... da guerriera...', 28153),
(152090, 'itIT', 'La mia battaglia... è finita...', 'La mia battaglia... è finita...', 28153),
(152089, 'itIT', 'La mia vita... per Draenor...', 'La mia vita... per Draenor...', 28153),
(152088, 'itIT', 'Va\' per la tua strada.', 'Va\' per la tua strada.', 28153),
(152087, 'itIT', 'Adesso vai.', 'Adesso vai.', 28153),
(152086, 'itIT', 'Non deludere l\'Orda.', 'Non deludere l\'Orda.', 28153),
(152085, 'itIT', 'Muori in pace.', 'Muori bene.', 28153),
(152084, 'itIT', 'Non ho altro da dire.', 'Non ho altro da dire.', 28153),
(152083, 'itIT', 'Lasciami stare.', 'Adesso va\'.', 28153),
(152082, 'itIT', 'Vai con onore.', 'Vai con onore.', 28153),
(152081, 'itIT', 'Possano le tue lame mai consumarsi.', 'Possano le tue lame mai consumarsi.', 28153),
(152080, 'itIT', 'Vai avanti verso la vittoria.', 'Vai avanti verso la vittoria.', 28153),
(152079, 'itIT', 'Non dimenticare i tuoi doveri.', 'Non dimenticare i tuoi doveri.', 28153),
(152078, 'itIT', 'Dimmi cosa vuoi.', 'Dimmi cosa vuoi.', 28153),
(152077, 'itIT', 'Non ho tempo per le assurdità.', 'Non ho tempo per le assurdità.', 28153),
(152076, 'itIT', 'Be\'? Sto aspettando...', 'Be\'? Sto aspettando...', 28153),
(152075, 'itIT', 'Parla.', 'Parla.', 28153),
(152074, 'itIT', 'Felice di vederti.', 'Felice di vederti.', 28153),
(152073, 'itIT', 'Lok\'tar!', 'Lok\'tar!', 28153),
(152072, 'itIT', 'Throm\'ka!', 'Throm\'ka!', 28153),
(152071, 'itIT', 'Cosa ti serve?', 'Cosa ti serve?', 28153),
(152070, 'itIT', 'Zug zug.', 'Zug zug.', 28153),
(152069, 'itIT', 'Forza e onore.', 'Forza e onore.', 28153),
(152068, 'itIT', 'Sono tutti così fastidiosi ad Azeroth?', 'Sono tutti così fastidiosi ad Azeroth?', 28153),
(152067, 'itIT', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi davvero continuare a punzecchiarmi?', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi DAVVERO continuare a punzecchiarmi?', 28153),
(152066, 'itIT', 'Ascolta, mi stai facendo arrabbiare. E non è una cosa che ti consiglio di fare.', 'Ascolta, mi stai facendo arrabbiare. E non è una cosa che ti consiglio di fare.', 28153),
(152065, 'itIT', 'ORCHI... SPACCANO!!!', 'ORCHI... SPACCANO!!!', 28153),
(152064, 'itIT', 'Temo siano ancora impegnati coi servitori della congrega fuori dalle mura.', '', 28153),
(152063, 'itIT', '', 'Ma dove sono gli altri Inquisitori?', 28153),
(152062, 'itIT', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(152061, 'itIT', 'Cadi dinnanzi alla mia furia!', 'Cadi dinnanzi alla mia furia!', 28153),
(152060, 'itIT', 'Il tuo destino è segnato!', 'Il tuo destino è segnato!', 28153),
(152059, 'itIT', 'Trema di fronte all\'Orda!', 'Trema di fronte all\'Orda!', 28153),
(152058, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(152057, 'itIT', 'Morte ai nostri nemici!', 'Morte ai nostri nemici!', 28153),
(152056, 'itIT', 'Morirai in questo giorno!', 'Morirai in questo giorno!', 28153),
(152055, 'itIT', 'Una morte... onorevole.', 'Una morte... onorevole.', 28153),
(152054, 'itIT', 'Antenati... arrivo...', 'Antenati... arrivo...', 28153),
(152053, 'itIT', 'Perderete... questa guerra...', 'Perderete... questa guerra...', 28153),
(152052, 'itIT', 'La vostra ora... giungerà...', 'La vostra ora... giungerà...', 28153),
(152051, 'itIT', 'Spiriti... accoglietemi...', 'Spiriti... accoglietemi...', 28153),
(152050, 'itIT', 'La mia... battaglia... è finita...', 'La mia battaglia... è finita...', 28153),
(152049, 'itIT', 'Il mio spirito torna... a Draenor...', 'Il mio spirito... torna... a Draenor...', 28153),
(152048, 'itIT', 'Torna quando avrai altro denaro.', 'Torna quando avrai altro denaro.', 28153),
(152047, 'itIT', 'Che questa merce ti serva a dovere.', 'Possa questa merce servirti bene.', 28153),
(152046, 'itIT', 'Passa di nuovo.', 'Torna quando vuoi.', 28153),
(152045, 'itIT', 'Muori bene.', 'Muori in pace.', 28153),
(152044, 'itIT', 'Ho ben poco altro da dire.', 'Non ho altro da dire.', 28153),
(152043, 'itIT', 'Qui abbiamo finito.', 'Qui abbiamo finito.', 28153),
(152042, 'itIT', 'Vai con onore.', 'Vai con onore.', 28153),
(152041, 'itIT', 'Possano gli spiriti guidare la tua mano.', 'Possano gli spiriti guidare la tua mano.', 28153),
(152040, 'itIT', 'Vai avanti verso la vittoria.', 'Vai avanti verso la vittoria.', 28153),
(152039, 'itIT', 'E sia.', 'E sia.', 28153),
(152038, 'itIT', 'Cosa stai cercando?', 'Cosa stai cercando?', 28153),
(152037, 'itIT', 'Cosa ti serve?', 'Cosa ti serve?', 28153),
(152036, 'itIT', 'Dai un\'occhiata.', 'Dai pure un\'occhiata.', 28153),
(152035, 'itIT', 'Parla.', 'Parla.', 28153),
(152034, 'itIT', 'Felice di vederti.', 'Felice di vederti.', 28153),
(152033, 'itIT', 'Lok\'tar!', 'Lok\'tar!', 28153),
(152032, 'itIT', 'Throm\'ka!', 'Throm\'ka!', 28153),
(152031, 'itIT', 'Cosa ti serve?', 'Cosa ti serve?', 28153),
(152030, 'itIT', 'Zug zug.', 'Zug zug.', 28153),
(152029, 'itIT', 'Forza e onore.', 'Forza e onore.', 28153),
(152028, 'itIT', 'Sono tutti così fastidiosi ad Azeroth?', 'Sono tutti così fastidiosi ad Azeroth?', 28153),
(152027, 'itIT', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi DAVVERO continuare a punzecchiarmi?', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi DAVVERO continuare a punzecchiarmi?', 28153),
(152026, 'itIT', 'Ascolta, mi stai facendo arrabbiare. E non è una cosa che ti consiglio di fare.', 'Ascolta, mi stai facendo arrabbiare. È una cosa che non ti consiglio di fare.', 28153),
(152025, 'itIT', 'ORCHI... SPACCANO!!!', 'ORCHI... SPACCANO!!!', 28153),
(152024, 'itIT', 'Sto cucinando del pesce fresco. Nun si può chiedere di meglio.', '', 28153),
(152023, 'itIT', '', 'Stiamo cercando di scappare da tutto chesto. Strano come più di così nun si riesca a fare. Il panorama è imbattibile.', 28153),
(152017, 'itIT', 'Come ha fatto a rompere le catene?', 'Come ha fatto a rompere le catene?', 28153),
(152016, 'itIT', 'Vediamo di non rimanere nei paraggi per scoprirlo!', 'Vediamo di non rimanere nei paraggi per scoprirlo!', 28153),
(152015, 'itIT', 'Contagio di sangue!', '', 28153),
(152014, 'itIT', 'Analisi del fiore', 'Analisi del fiore', 28153),
(152013, 'itIT', 'L\'Avatar di Sethraliss non è più maledetto! Riportatelo in piena salute per disabilitare le difese!', 'L\'Avatar di Sethraliss non è più maledetto! Riportatelo in piena salute per disabilitare le difese!', 28153),
(152012, 'itIT', 'Evoluzione!', '', 28153),
(152011, 'itIT', 'Infezione!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(152010, 'itIT', 'La pestilenza si diffonde!', '', 28153),
(152009, 'itIT', 'Gestazione violenta!', '', 28153),
(152008, 'itIT', 'Consumare corpi!', '', 28153),
(152007, 'itIT', 'Ora basta! Voi dell\'Orda la pagherete.', '', 28153),
(152006, 'itIT', 'Ceppo fatale. Contagio avvenuto.', '', 28153),
(152005, 'itIT', 'Ho perso il mio travestimento. Hai un\'altra pergamena?', 'Ho perso il mio travestimento. Hai un\'altra pergamena?', 28153),
(152004, 'itIT', '<La Raganella della Giungla salta in acqua!>', '', 28153),
(152003, 'itIT', 'Ammuffisci!', '', 28153),
(152002, 'itIT', 'Pronto per l\'infezione!', '', 28153),
(152001, 'itIT', 'Contagio inevitabile...', '', 28153),
(152000, 'itIT', '', 'Buono. BAH. No, non c\'è niente di buono in lui.', 28153),
(151999, 'itIT', '', 'Hai trovato quel Buon Cumpà?', 28153),
(151998, 'itIT', 'Corpi freschi!', '', 28153),
(151990, 'itIT', 'È il momento di prenderci il nostro trofeo.', '', 28153),
(151989, 'itIT', 'La perla è nostra! Con essa, i nostri vascelli diverranno predatori dei mari.', '', 28153),
(151987, 'itIT', '', 'Godetevi quesssta vittoria. Sssarà l\'ultima della vossstra vita.', 28153),
(151986, 'itIT', 'È la legge della giungla. Il più forte vince sempre sul più debole.', '', 28153),
(151985, 'itIT', 'Tenete gli occhi aperti. Delle forze sconosciute ci stanno alle calcagna.', '', 28153),
(151983, 'itIT', 'L\'Alleanza non deve mettere le mani su questo tesoro. Tutti coloro che ci ostacoleranno, moriranno!', '', 28153),
(151982, 'itIT', '', 'Mi hai riportato in affari, quindi sì. Avere Cesi come capo significherebbe tornare a fare dei bei soldoni di nuovo.', 28153),
(151981, 'itIT', 'Darai il tuo supporto a Cesi Bombapazza?', 'Darai il tuo supporto a Cesi Bombapazza?', 28153),
(151980, 'itIT', '', 'Questo posto un tempo era più proficuo.', 28153),
(151979, 'itIT', '', 'Andiamocene da qui prima che ci circondino. Andiamo!', 28153),
(151978, 'itIT', 'La Casata dei Sacraonda comanderà questo regno sommerso. L\'ira della Madre delle Maree ce lo permetterà.', '', 28153),
(151977, 'itIT', 'La flotta... sarà sua...', '', 28153),
(151976, 'itIT', 'Stavo solo giocando con loro, mio signore. Sarà fatto!', '', 28153),
(151975, 'itIT', 'Il nostro destino incombe. Non devono entrare nel Santuario della Tempesta.', '', 28153),
(151974, 'itIT', '', 'Guarda cosa sei diventato. Tutto questo sangue è colpa tua!', 28153),
(151973, 'itIT', 'La pergamena fluttua e ronza, visioni di altri posti oscurati dalla magia.', '', 28153),
(151972, 'itIT', 'Sopravvivenza dell\'anima del mondo improbabile...', '', 28153),
(151971, 'itIT', 'Infezione planetaria imminente.', '', 28153),
(151970, 'itIT', 'Dovremmo lasciare che i Marferreo si prendano il tesoro.', 'Dovremmo lasciare che i Marferreo si prendano il tesoro.', 28153),
(151969, 'itIT', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t %s crea una |cFFFF0000|Hspell:267891|h[Guardia della Rapidità]|h|r!', '|TInterface\\Icons\\70_inscription_vantus_rune_azure:20|t %s crea una |cFFFF0000|Hspell:267891|h[Guardia della Rapidità]|h|r!', 28153),
(151968, 'itIT', '<Pugnalalo.>', '<Pugnalalo.>', 28153),
(151967, 'itIT', 'Ma stai dicendo sul serio?', 'Ma stai dicendo sul serio?', 28153),
(151966, 'itIT', 'Questo è un oltraggio! Non ho intenzione di pagare!', 'Questo è un oltraggio! Non ho intenzione di pagare!', 28153),
(151965, 'itIT', 'Un posto sul pavimento per la notte sono 50 monete d\'oro. 60 se lo vuoi vicino al fuoco. Portati una coperta.\n\nI letti stanno a 100 monete d\'oro.\n\nVincolare la Pietra del Ritorno viene 75 monete d\'oro a settimana.\n\nNon ti sta bene?\n\n<Scrolla le spalle e incrocia le braccia con fare spocchioso.>\n\nPeccato. Queste sono le tariffe.', '', 28153),
(151964, 'itIT', 'Le profondità hanno previsto il vostro arrivo... e la vostra caduta!', '', 28153),
(151963, 'itIT', 'Breccia ingente rilevata.', '', 28153),
(151962, 'itIT', '', 'Dobbiamo radunare le forze nostre e fermare l\'infezione alla fonte.', 28153),
(151961, 'itIT', '', 'Il Titano ci ha dato del tempo, ma G\'huun nun rimarrà sotto controllo a lungo.', 28153),
(151960, 'itIT', 'Campione virulento rilevato. Contenimento prioritario.', '', 28153),
(151959, 'itIT', 'Divora! Consuma! Diffondi!', '', 28153),
(151958, 'itIT', '', 'Chesta cosa sta cercando la ma\'ma sua? Speriamo ci conduca a qualcosa che possa fermare la diffusione di chesta piaga.', 28153),
(151957, 'itIT', 'Contenimento di G\'huun critico. Impossibile contattare la M.A.D.R.E.', '', 28153),
(151954, 'itIT', '', 'Se si diffondesse in superficie, nun saremmo in grado di contenerla.', 28153),
(151953, 'itIT', '', 'Nun ho mai visto chesto tipo di corruzione prima d\'ora.', 28153),
(151952, 'itIT', '', 'Nun deve raggiungere la superficie! Distruggetela!', 28153),
(151951, 'itIT', '', 'Argh! Che razza di creatura è chesta?!?', 28153),
(151950, 'itIT', '', 'State in guardia. Nessuno sa cosa si nasconde in cheste caverne.', 28153),
(151949, 'itIT', '', 'I Troll del Sangue stanno sparsi, ma dobbiamo trovare la fonte dell\'infezione e distruggerla.', 28153),
(151948, 'itIT', 'Teniamo nu dono per te, grande Loa della morte!', '', 28153),
(151947, 'itIT', 'Se significa vedere volti nuovi qui in giro, allora sì.', '', 28153),
(151946, 'itIT', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s inizia a lanciare |cFFFF0404|Hspell:260773|h[Rituale Infausto]|h|r!', '|TInterface\\ICONS\\SPELL_SHADOW_ANTISHADOW:20|t %s inizia a lanciare |cFFFF0404|Hspell:260773|h[Rituale Infausto]|h|r!', 28153),
(151945, 'itIT', 'Darai il tuo supporto a Cesi Bombapazza?', 'Darai il tuo supporto a Cesi Bombapazza?', 28153),
(151944, 'itIT', 'Vuoi comprare o vendere?', '', 28153),
(151943, 'itIT', '', 'Ho un pessimo presentimento...', 28153),
(151942, 'itIT', 'Con piacere. Soffriranno in tuo nome!', '', 28153),
(151941, 'itIT', 'Contagio rilevato. Igienizzare.', '', 28153),
(151940, 'itIT', 'Esplosione di pestilenza!', '', 28153),
(151939, 'itIT', 'Attivazione difese finali. Distruggere sorgente virulenta.', '', 28153),
(151938, 'itIT', 'Subito, mio signore. Devo solo sbarazzarmi di una manciata di ratti, prima.', 'Subito, mio signore. Devo solo sbarazzarmi di una manciata di ratti, prima.', 28153),
(151937, 'itIT', 'Area purificatrice.', '', 28153),
(151936, 'itIT', 'Sistemi di epurazione attivati.', '', 28153),
(151935, 'itIT', 'Perforazione vile!', '', 28153),
(151934, 'itIT', 'Solo qualche osso rotto... niente di serio.', '', 28153),
(151933, 'itIT', 'Guidaci all\'accampamento dei Vulpera. Noi porteremo il tesoro.', '', 28153),
(151932, 'itIT', 'Espulsione di sangue!', '', 28153),
(151931, 'itIT', '', 'Abbassa le armi! Non c\'è bisogno che tu lo faccia!', 28153),
(151930, 'itIT', 'Devo... diffondermi...', '', 28153),
(151929, 'itIT', 'La piaga ti affligge!', '', 28153),
(151928, 'itIT', 'Ti ho infettato!', '', 28153),
(151927, 'itIT', 'Carne... corrotta...', '', 28153),
(151926, 'itIT', 'Consumare!', '', 28153),
(151925, 'itIT', 'Devo diffondermi!', '', 28153),
(151924, 'itIT', 'Mo\' nun dimenticarti la TUA parte del patto...', '', 28153),
(151923, 'itIT', 'Ahahah! Vedi, Maestà? Bwonsamdi mantiene sempre la parola sua!', '', 28153),
(151922, 'itIT', 'Sorgete... sorgete! Nun siate pigri! Afferrate le lance vostre e COMBATTETE!', '', 28153),
(151921, 'itIT', 'Calma, altezza. Bwonsamdi aiuta sempre li amici suoi... Eheheh...', '', 28153),
(151920, 'itIT', '', 'Nun serve che mi guardi lavorare da lassù. Teniamo entrambi del lavoro da fare.', 28153),
(151919, 'itIT', 'La barca è pronta a partire.', '', 28153),
(151918, 'itIT', 'Chesti traditori stanno tra me e il regno mio, ma dove sta l\'aiuto che mi avevi promesso? Tieni intenzione di mantenere la parola tua?', '', 28153),
(151916, 'itIT', 'Ottimo lavoro. Riesco a sentire Azeroth recuperare le forze, grazie al tuo intervento.', '', 28153),
(151915, 'itIT', 'Ci sono parecchie ferite d\'Azerite nelle vicinanze. Usa il tuo Cuore di Azeroth per richiuderle!', '', 28153),
(151913, 'itIT', 'Scappa fintanto che puoi!', '', 28153),
(151912, 'itIT', 'Tsk! Il tono che usi con il Loa tuo nun è rispettoso, vostra altezza. Ma con tutte le anime che riceverò oggi, farò finta di niente.', '', 28153),
(151911, 'itIT', 'Ci siamo dentro insieme, $p.\n\nAmmutinamento o schiavitù.', '', 28153),
(151910, 'itIT', 'Bwonsamdi, mostrati!', '', 28153),
(151909, 'itIT', 'Troppi stanno al fianco di Zul. Ci sta solo na via da seguire...', '', 28153),
(151908, 'itIT', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t %s prende di mira |cFFFF0000$n|r e si prepara a fare |cFFFF0000|Hspell:266951|h[Irruzione]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t %s prende di mira |cFFFF0000$n|r e si prepara a fare |cFFFF0000|Hspell:266951|h[Irruzione]|h|r!', 28153),
(151907, 'itIT', 'Le antiche difese del cuore di Sethraliss sono state disabilitate da un gruppo di Zandalari...', 'Le antiche difese del cuore di Sethraliss sono state disabilitate da un gruppo di Zandalari...', 28153),
(151906, 'itIT', 'Sì, Cesi può contare sul mio supporto.', '', 28153),
(151905, 'itIT', 'Mettetevi al lavoro, Goblin perditempo. Voglio quella Base in Scatola pronta immediatamente!', 'Mettetevi al lavoro, Goblin perditempo. Voglio quella Base in Scatola pronta immediatamente!', 28153),
(151904, 'itIT', 'Darai il tuo supporto a Cesi Bombapazza?', 'Darai il tuo supporto a Cesi Bombapazza?', 28153),
(151902, 'itIT', 'Mmm. Sì, fammi vedere.\n\n<Kooda fruga per un po\', prima di tirar fuori una giara dalle sue sacche.>\n\nQuesta l\'ho comprata un paio di secoli fa. L\'avevo completamente dimenticata, ma direi che potrei vendertela.', '', 28153),
(151901, 'itIT', 'Hai mai sentito parlare di una cosa chiamata \"Salsa Centenaria\"? Ne hai un po\'?', 'Hai mai sentito parlare di una cosa chiamata \"Salsa Centenaria\"? Ne hai un po\'?', 28153),
(151900, 'itIT', 'Ciao, $R. Hai qualcosa di interessante da vendere?', '', 28153),
(151899, 'itIT', 'Per tutte le maree, ecco che arriva!', 'Per tutte le maree, ecco che arriva!', 28153),
(151898, 'itIT', 'Fame insaziabile, il padrone si nutre.', '', 28153),
(151897, 'itIT', 'La ferita si infetta. Il mondo marcisce.', '', 28153),
(151896, 'itIT', 'Siamo sempre stati nella tua mente.', '', 28153),
(151895, 'itIT', 'Urla putrefatte preannunceranno il suo arrivo.', '', 28153),
(151894, 'itIT', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t Zanazal il Saggio inizia a lanciare |cFFFF0000|Hspell:267273|h[Esplosione Venefica]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|t Zanazal il Saggio inizia a lanciare |cFFFF0000|Hspell:267273|h[Esplosione Venefica]|h|r!', 28153),
(151893, 'itIT', '', 'Gli striscianti sono indeboliti!', 28153),
(151892, 'itIT', '', 'Kril lax qutholil!', 28153),
(151890, 'itIT', 'Hai affrontato i Naga come mio avatar e posto fine all\'assalto contro il mio tempio.', '', 28153),
(151889, 'itIT', '', 'Oh! Era da secoli che volevo provare la Salsa Centenaria! È una salsa da cucina fatta con una miscela di ingredienti lasciata fermentare per centinaia d\'anni. Più a lungo è lasciata fermentare, più ricco è il sapore finale. Si dice aggiunga un tocco distintivo a qualsiasi piatto.\n\nC\'è chi dice che alcuni commercianti Tortolliani la vendano, ma è rara e molto costosa.\n\n<Xun Xun sospira.>\n\nÈ l\'ingrediente dei sogni di ogni chef!', 28153),
(151888, 'itIT', 'Hai una gran bella dispensa. Non manca nulla nella tua collezione di spezie?', 'Hai una gran bella dispensa. Non manca nulla nella tua collezione di spezie?', 28153),
(151887, 'itIT', '', 'Un volto nuovo! E amichevole, a quanto pare. Ti va di provare qualcosa di speciale? O forse stai cercando delle spezie o ricette rare?', 28153),
(151886, 'itIT', 'Il Cuore di Azeroth si sta rafforzando, grazie a te. Siamo un passo più vicini a guarire Azeroth dalle sue ferite.', '', 28153),
(151885, 'itIT', 'Percepisco dell\'Azerite nelle vicinanze... e coloro che intendono abusarne per i propri scopi. Devi fermarli!', '', 28153),
(151884, 'itIT', 'Vieni, piccolo arboscello. Calma il tuo cuore e aiutami a guarire questa persona.', '', 28153),
(151883, 'itIT', '', 'Il sangue scorre verso gli abissi.', 28153),
(151882, 'itIT', '', 'Sotto le maree, la verità ti attende.', 28153),
(151881, 'itIT', '', 'Ascolta il canto degli annegati.', 28153),
(151880, 'itIT', '', 'La tenebra avanza. La pestilenza si diffonde. La via è aperta.', 28153),
(151879, 'itIT', '', 'Gli abissi divoreranno la tua anima!', 28153),
(151878, 'itIT', '', 'I tuoi polmoni sono la mia dimora!', 28153),
(151877, 'itIT', '', 'Ti attenderò... nell\'oscurità...', 28153),
(151876, 'itIT', '', 'Sei nelle mie mani!', 28153),
(151875, 'itIT', '', 'I tuoi alleati si sono divertiti nel vederti morire.', 28153),
(151874, 'itIT', '', 'Il nostro legame sarà eterno nella vastità degli abissi.', 28153),
(151873, 'itIT', 'Neanche un degno tratto tra di voi.', '', 28153),
(151872, 'itIT', 'Così fragile! Così immeritevole!', '', 28153),
(151871, 'itIT', 'Eri il ceppo più debole!', '', 28153),
(151870, 'itIT', 'Argh! Com\'è... possibile...', '', 28153),
(151869, 'itIT', 'Ul basha krix.', '', 28153),
(151868, 'itIT', '', 'Riempite il cielo di fuoco! Abbatteteli.', 28153),
(151867, 'itIT', 'Le creature inferiori devono servire, o... morire!', '', 28153),
(151866, 'itIT', '', 'Per l\'Orda!', 28153),
(151865, 'itIT', '', 'Non abbiate pietà!', 28153),
(151864, 'itIT', 'Ug\' crish zul Thraxas!', '', 28153),
(151863, 'itIT', '', 'Mantenete il fuoco! Le nostre truppe di terra dipendono da voi.', 28153),
(151862, 'itIT', '', 'Continuate a scoccare!', 28153),
(151861, 'itIT', 'Chesta tomba sarà il luogo dell\'eterno riposo vostro!', '', 28153),
(151860, 'itIT', 'Nun potete far niente contro gli Zandalari!', '', 28153),
(151859, 'itIT', 'Chesto tempio sta sotto il controllo di G\'huun!', '', 28153),
(151858, 'itIT', 'Gli Zandalari regneranno!', '', 28153),
(151857, 'itIT', '', 'Da questa parte! Una gloriosa battaglia ci attende!', 28153),
(151856, 'itIT', 'G\'huun nun può essere fermato!', '', 28153),
(151855, 'itIT', 'Sanguinate per il Dio del Sangue!', '', 28153),
(151854, 'itIT', 'Farò un po\' di ricerche per conto mio. Dovessi trovare qualcosa, sarete i primi a saperlo.', '', 28153),
(151853, 'itIT', 'Sentito? Sarà meglio scoprire la fonte della corruzione del Dio Antico, così potremo dargli una bella martellata!', '', 28153),
(151852, 'itIT', 'Ah! Se questo è il meglio che sai fare, Zul, ora capisco perché l\'impero dei Troll è caduto!', '', 28153),
(151850, 'itIT', 'Avrei dovuto gettare il tuo corpo infetto in uno di questi sarcofagi.', '', 28153),
(151849, 'itIT', 'Gloria e onore, io combatto per i Destatempesta!', 'Gloria e onore, io combatto per i Destatempesta!', 28153),
(151848, 'itIT', 'Hai la mia spada.', 'Hai la mia spada.', 28153),
(151847, 'itIT', 'Non sono ancora morto!', 'Non sono ancora morta!', 28153),
(151846, 'itIT', 'Fermeremo quei demoni insieme!', 'Fermeremo quei demoni insieme!', 28153),
(151845, 'itIT', 'Questa valle sarà libera finché ci sarò io!', 'Questa valle sarà libera finché ci sarò io!', 28153),
(151844, 'itIT', 'Se i Destatempesta ci chiamano, dobbiamo rispondere.', 'Se i Destatempesta ci chiamano, dobbiamo rispondere.', 28153),
(151843, 'itIT', 'Vivere o morire, è il nostro momento.', 'Vivere o morire, è il nostro momento.', 28153),
(151842, 'itIT', 'Sono con te!', 'Sono con te!', 28153),
(151841, 'itIT', 'È un peccato che tu non sia qui, Zul, per assistere alla sua distruzione.', '', 28153),
(151840, 'itIT', 'Argh! Lo vedremo, maledetto Troll!', '', 28153),
(151839, 'itIT', 'Presto si ergeranno e tutti coloro che si oppongono a G\'huun cadranno!', '', 28153),
(151838, 'itIT', 'Forse abbiamo ancora una possibilità! Per i Destatempesta!', 'Forse abbiamo ancora una possibilità! Per i Destatempesta!', 28153),
(151837, 'itIT', 'Stolti! Il potere mio ha già vincolato gli antichi spiriti al volere del padrone.', '', 28153),
(151836, 'itIT', 'Sento l\'onda sacra. C\'è ancora speranza!', 'Sento l\'onda sacra. C\'è ancora speranza!', 28153),
(151835, 'itIT', 'Ce ne sono altri. Non è tutto perduto!', 'Ce ne sono altri. Non è tutto perduto!', 28153),
(151834, 'itIT', 'Non so che sorta di magia oscura ci sia qui, ma sarà meglio trovare un modo per dissolverla.', '', 28153),
(151833, 'itIT', 'Noi non siamo così! Possiamo ancora fermare Ser Sacraonda!', 'Noi non siamo così! Possiamo ancora fermare Ser Sacraonda!', 28153),
(151832, 'itIT', 'Secondo la mia ricerca, questo è il luogo dove riposa il primo Re di Zandalar.', '', 28153),
(151831, 'itIT', 'Il cancello è caduto. Muoviamoci! Riconquistate Arathi, per l\'Alleanza!', '', 28153),
(151830, 'itIT', 'Pike è ancora in vita? Andrò a cercarlo immediatamente.', 'Pike è ancora in vita? Andrò a cercarlo immediatamente.', 28153),
(151829, 'itIT', 'Il cancello è caduto. Avanti! Riprendiamo Arathi dalle mani dell\'Orda!', '', 28153),
(151828, 'itIT', 'Il cancello è stato abbattuto! Avanziamo!', '', 28153),
(151827, 'itIT', '', 'I cancelli sono caduti! Continuate ad attaccare!', 28153),
(151826, 'itIT', 'I cancelli sono caduti! Assaltate la fortezza!', '', 28153),
(151825, 'itIT', 'Per il bene di Zandalar... e di tutti i regni vostri... dovete fermarlo.', '', 28153),
(151824, 'itIT', 'I cancelli sono caduti! Ora prendiamo la base!', '', 28153),
(151823, 'itIT', 'Dobbiamo aprire immediatamente il Santuario della Tempesta!', 'Dobbiamo aprire immediatamente il Santuario della Tempesta!', 28153),
(151822, 'itIT', 'Il padrone suo sta raccogliendo più potere. Zul nun si fermerà finché il mondo nun sarà del Dio del Sangue.', '', 28153),
(151821, 'itIT', 'È fatta. Arathi appartiene di nuovo a noi. Per l\'Alleanza!', '', 28153),
(151820, 'itIT', 'La tempesta si risveglia in me. Affronterò l\'ombra!', 'La tempesta si risveglia in me. Affronterò l\'ombra!', 28153),
(151819, 'itIT', '', 'La nostra vittoria non è mai stata in dubbio. Per l\'Orda!', 28153),
(151818, 'itIT', 'Mi avete liberato da nu destino crudele, ma Zul nun è che nu burattino di nu piano più grande.', '', 28153),
(151817, 'itIT', 'Torna dal padrone tuo e scopri la ricompensa del fallimento!', '', 28153),
(151816, 'itIT', 'Sapevo che sarebbe arrivato questo giorno. Mi unirò agli altri.', 'Sapevo che sarebbe arrivato questo giorno. Mi unirò agli altri.', 28153),
(151815, 'itIT', 'Impossible! Nessuno può fermare G\'huun!', '', 28153),
(151814, 'itIT', 'Avete spezzato il controllo di Zul! Nun servo più chel maiale!', '', 28153),
(151813, 'itIT', 'Lamentati quanto vuoi, Re mio... ma dovresti aver capito che nun si può fuggire da G\'huun.', '', 28153),
(151812, 'itIT', 'Chesti intrusi moriranno... ma nun intendo ascoltarti blaterare mentre lo faccio.', '', 28153),
(151811, 'itIT', 'Ho passato la vita a resistere al padrone tuo, solo per finire al servizio suo dopo la morte.', '', 28153),
(151810, 'itIT', 'Silenzio, profeta di menzogne!', '', 28153),
(151809, 'itIT', 'Chesto è il luogo di riposo del primo re di Zandalar. Dazar era testardo... ma mo\' sta al servizio nostro!', '', 28153),
(151808, 'itIT', 'Sei $gmatto:matta;?', 'Sei $gmatto:matta;?', 28153),
(151807, 'itIT', 'Parla pure.', 'Parla pure.', 28153),
(151806, 'itIT', 'Ma dopo la morte loro, gli ho dato nu scopo comune. Accidervi.', '', 28153),
(151805, 'itIT', 'La terra mi coglie.', 'La terra mi coglie.', 28153),
(151804, 'itIT', 'Si odiavano, in vita, e alla fine arrivarono a distruggersi l\'un l\'altro.', '', 28153),
(151803, 'itIT', 'Vi state avvicinando ai tre sovrani che controllavano l\'impero in un periodo durante il quale nessun Troll poteva regnare.', '', 28153),
(151802, 'itIT', 'Agli estranei non è permesso stare qui.', 'Agli estranei non è permesso stare qui.', 28153),
(151801, 'itIT', 'Il mare si ritira, la terra avanza!', 'Il mare si ritira, la terra avanza!', 28153),
(151800, 'itIT', 'Di certo nun terranno problemi a sbarazzarsi anche di voi.', '', 28153),
(151799, 'itIT', 'Visto che i templi pullulavano di morti, furono costruiti dei golem per sbarazzarsi dei cadaveri.', '', 28153),
(151798, 'itIT', 'Migliaia di anni fa, na malattia del sangue spazzò via quasi tutti gli Zandalari.', '', 28153),
(151797, 'itIT', 'Presto si ergeranno e tutti coloro che si oppongono a G\'huun cadranno!', '', 28153),
(151796, 'itIT', 'Il potere mio ha già attecchito, vincolando gli antichi spiriti al volere del padrone.', '', 28153),
(151795, 'itIT', 'Benvenuti nella tomba del primo Re dei Troll. Quanto vorrei potervelo dire di persona.', '', 28153),
(151794, 'itIT', 'Te l\'ho detto, non ti seguirò in questa follia!', 'Te l\'ho detto, non ti seguirò in questa follia!', 28153),
(151793, 'itIT', 'Non ci cascherò di nuovo.', 'Non ci cascherò di nuovo.', 28153),
(151792, 'itIT', 'È... è sicuro?', 'È... è sicuro?', 28153),
(151791, 'itIT', 'Siamo imprenditori e specialisti in traslochi. Non come quei dannati mercenari dai mantelli rossi. Non siamo pirati.', '', 28153),
(151790, 'itIT', '', 'Vieni, torniamo da Katherine.', 28153),
(151789, 'itIT', '', 'Voi tre, fate venire qui una squadra di ricerca e trovatela!', 28153),
(151788, 'itIT', '', 'Aspetta... no!', 28153),
(151787, 'itIT', '', 'Canaglia insolente! Non è finita qui!', 28153),
(151786, 'itIT', '', 'È finita. Non puoi più scappare.', 28153),
(151785, 'itIT', '', 'Fuori dai piedi, carne da esca!', 28153),
(151784, 'itIT', '', 'Prendi questo!', 28153),
(151783, 'itIT', '', 'Il tuo spettacolino non è servito a nulla! Questa città è MIA!', 28153),
(151782, 'itIT', 'Aspetterò qui in caso qualcuno di loro dovesse tornare!', '', 28153),
(151781, 'itIT', '', 'Le cose andranno molto meglio quando sarò il capo.\n\nQuando quei pirati Marferreo se ne saranno andati, tutti potranno venire qui a commerciare. Sarà fantastico!', 28153),
(151780, 'itIT', '', 'Argh! Le cose andavano meglio prima che quegli imbecilli dal mantello rosso arrivassero.', 28153),
(151779, 'itIT', 'Ascolta, sto solo cercando di guadagnarmi da vivere.', '', 28153),
(151778, 'itIT', 'Strappavele e la sua gente sono un danno per gli affari. Se le cose dovessero peggiorare, prenderei i miei uccelli e me ne andrei.', '', 28153),
(151777, 'itIT', 'Stavo per diventare ricco...', '', 28153),
(151776, 'itIT', 'Stai cercando di intralciarci la strada? Ho ucciso per molto meno!', '', 28153),
(151775, 'itIT', '', 'Non prenderete questa foresta!', 28153),
(151774, 'itIT', '', 'Grazie. Credevo di poterli affrontare da sola. Torno immediatamente da Morwin.', 28153),
(151773, 'itIT', 'Mi sento come tu hai ridotto questo posto.', '', 28153),
(151772, 'itIT', 'Noi Tortolliani commerciamo in questo luogo da molto tempo. Col tempo, gli Zandalari hanno preso il sopravvento, ma tempi duri stanno arrivando per loro. Noi, ovviamente, resisteremo.', '', 28153),
(151771, 'itIT', 'Io lavoro qui. Non serve andare in strada pericolosa.', '', 28153),
(151770, 'itIT', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(151769, 'itIT', 'Lok narash!', 'Lok narash!', 28153),
(151768, 'itIT', 'Gakarah ma!', 'Gakarah ma!', 28153),
(151767, 'itIT', 'Trema di fronte all\'Orda!', 'Trema di fronte all\'Orda!', 28153),
(151766, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(151765, 'itIT', 'Morte ai nostri nemici!', 'Morte ai nostri nemici!', 28153),
(151764, 'itIT', 'Oggi morirai!', 'Morirai in questo giorno!', 28153),
(151763, 'itIT', 'Una morte... onorevole.', 'Una morte... onorevole.', 28153),
(151762, 'itIT', 'Ahah! Sei qui a rapporto, vedo. Gettalo nella cassa e torna a lavorare!', '', 28153),
(151761, 'itIT', 'Antenati... arrivo...', 'Antenati... arrivo...', 28153),
(151760, 'itIT', 'Perderete... questa guerra...', 'Perderete... questa guerra...', 28153),
(151759, 'itIT', 'La vostra ora... giungerà...', 'La vostra ora... giungerà...', 28153),
(151758, 'itIT', 'Muoio... da guerriero...', 'Muoio... da guerriera...', 28153),
(151757, 'itIT', 'La mia battaglia... è finita...', 'La mia battaglia... è finita...', 28153),
(151756, 'itIT', 'Il mio spirito ritorna... a Draenor...', 'Il mio spirito... torna... a Draenor...', 28153),
(151755, 'itIT', 'Muori in pace.', 'Muori in pace.', 28153),
(151754, 'itIT', 'Non ho altro da dire.', 'Non ho altro da dire.', 28153),
(151753, 'itIT', 'Adesso va\'.', 'Lasciami stare.', 28153),
(151752, 'itIT', 'Vai con onore.', 'Vai con onore.', 28153),
(151751, 'itIT', 'Possano le tue lame non consumarsi mai.', 'Possano le tue lame mai consumarsi.', 28153),
(151750, 'itIT', 'Vai avanti verso la vittoria.', 'Vai avanti verso la vittoria.', 28153),
(151749, 'itIT', 'È tutto.', 'E sia.', 28153),
(151748, 'itIT', 'Parla.', 'Parla.', 28153),
(151747, 'itIT', 'Felice di vederti.', 'Felice di vederti.', 28153),
(151746, 'itIT', 'Lok\'tar!', 'Lok\'tar!', 28153),
(151745, 'itIT', 'Throm\'ka!', 'Throm\'ka!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151744, 'itIT', 'Cosa ti serve?', 'Cosa ti serve?', 28153),
(151743, 'itIT', 'Zug zug.', 'Zug zug.', 28153),
(151742, 'itIT', 'Forza e onore.', 'Forza e onore.', 28153),
(151741, 'itIT', 'Compra di più la prossima volta.', 'Compra di più la prossima volta.', 28153),
(151740, 'itIT', 'Possa questa merce servirti bene.', 'Possa questa merce servirti bene.', 28153),
(151739, 'itIT', 'Nessun rimborso!', 'Nessun rimborso!', 28153),
(151738, 'itIT', 'Cosa stai cercando?', 'Cosa stai cercando?', 28153),
(151737, 'itIT', 'Cosa ti serve?', 'Cosa ti serve?', 28153),
(151736, 'itIT', 'Dai un\'occhiata.', 'Dai un\'occhiata.', 28153),
(151735, 'itIT', 'Sono tutti così fastidiosi ad Azeroth?', 'Sono tutti così fastidiosi ad Azeroth?', 28153),
(151734, 'itIT', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi DAVVERO continuare a punzecchiarmi?', 'Il mio passatempo è uccidere ogni cosa che mi infastidisce. Vuoi DAVVERO continuare a punzecchiarmi?', 28153),
(151733, 'itIT', 'Ascolta, mi stai facendo arrabbiare. E non è una cosa che ti consiglio di fare.', 'Ascolta, mi stai facendo arrabbiare. E non è una cosa che ti consiglio di fare.', 28153),
(151732, 'itIT', 'ORCHI... SPACCANO!!!', 'ORCHI... SPACCANO!!!', 28153),
(151731, 'itIT', 'Vieni... vieni, mio caro Reban. È ora di mangiare!', '', 28153),
(151730, 'itIT', '<Applause sounds>', '', 28153),
(151729, 'itIT', '<Yawning sound>', '', 28153),
(151728, 'itIT', '<Short cheer--Wooooo!>', '', 28153),
(151727, 'itIT', '<Slightly longer cheer--Woohoo!>', '', 28153),
(151726, 'itIT', '<Chicken sounds>', '', 28153),
(151725, 'itIT', '<Crying sounds>', '', 28153),
(151724, 'itIT', '<Crying sounds, variant>', '', 28153),
(151723, 'itIT', '<Crying sounds, variant.>', '', 28153),
(151722, 'itIT', '<Kiss sound>', '', 28153),
(151721, 'itIT', '<Laughing sounds>', '', 28153),
(151720, 'itIT', '<Laughing>', '', 28153),
(151719, 'itIT', '<Making a raspberry sound--Pfffthblth!>', '', 28153),
(151718, 'itIT', '<Roar of dominance>', '', 28153),
(151717, 'itIT', '<Variant roar>', '', 28153),
(151716, 'itIT', '<Sighing sound>', '', 28153),
(151715, 'itIT', '<Train noises--chugga chugga choo choo!>', '', 28153),
(151714, 'itIT', 'Mi... dispiace.', '', 28153),
(151713, 'itIT', 'Patetico! Cadrai dinnanzi ai Mag\'har!', '', 28153),
(151712, 'itIT', 'Ti sono grato.', '', 28153),
(151711, 'itIT', 'Ti ringrazio.', '', 28153),
(151710, 'itIT', 'Sono in debito con te.', '', 28153),
(151709, 'itIT', 'Cadrai ai miei piedi!', '', 28153),
(151708, 'itIT', 'Per le lune di Draenor!', '', 28153),
(151707, 'itIT', 'Ho fatto solo il mio dovere.', '', 28153),
(151706, 'itIT', 'Non chiedermelo di nuovo.', '', 28153),
(151705, 'itIT', 'È un piacere.', '', 28153),
(151704, 'itIT', 'Parla.', '', 28153),
(151703, 'itIT', 'Felice di vederti.', '', 28153),
(151702, 'itIT', 'Lok\'tar!', '', 28153),
(151701, 'itIT', 'Throm\'ka!', '', 28153),
(151700, 'itIT', 'No.', '', 28153),
(151699, 'itIT', 'Ho detto no!', '', 28153),
(151698, 'itIT', 'Mai!', '', 28153),
(151697, 'itIT', 'Proprio così.', '', 28153),
(151696, 'itIT', 'Giusto.', '', 28153),
(151695, 'itIT', 'Davvero.', '', 28153),
(151694, 'itIT', 'Richiamo Peone', 'Richiamo Peone', 28153),
(151693, 'itIT', 'Ho portato disonore al mio clan!', '', 28153),
(151692, 'itIT', 'Lasciami recuperare mana.', '', 28153),
(151691, 'itIT', 'Ho bisogno di mana!', '', 28153),
(151690, 'itIT', 'Che tipo di musica ascolto? Rock-cianera, ovviamente!', '', 28153),
(151689, 'itIT', 'Un\'altra notte in bianco, lupi miei.', '', 28153),
(151688, 'itIT', 'Ahhh! Quel chiropratico a Orgrimmar ha fatto miracoli con la mia schiena.', '', 28153),
(151687, 'itIT', 'Prova tu a passare qualche decennio su un pianeta con Draenei fanatici da tutte le parti e vediamo come ne esci fuori!', '', 28153),
(151686, 'itIT', 'I Teschio Ridente una volta mi hanno fischiato durante uno spettacolo di cabaret. Con un nome come quello, pensavo avessero un senso dell\'umorismo migliore.', '', 28153),
(151685, 'itIT', 'Su Azeroth i Capoguerra cambiano con la stessa facilità con cui le linee temporali si alternano su Draenor.', '', 28153),
(151684, 'itIT', 'Non ho mai conosciuto Gul\'dan, ma ho sentito dire che era un incubo alle feste. Cercava sempre di contaminare i cocktail.', '', 28153),
(151683, 'itIT', 'Il circolo del rituale di Xal\'vor si illumina!', 'Il circolo del rituale di Xal\'vor si illumina!', 28153),
(151682, 'itIT', 'Per favore, ti supplico!', '', 28153),
(151681, 'itIT', 'Abbi pietà di questo povero Orco!', '', 28153),
(151680, 'itIT', 'Mostra un po\' di compassione!', '', 28153),
(151679, 'itIT', 'Un lavoro ben fatto.', '', 28153),
(151678, 'itIT', 'Incredibile, direi.', '', 28153),
(151677, 'itIT', 'Mi congratulo con te.', '', 28153),
(151676, 'itIT', 'Tu devi far parte dei Lupi Bianchi, perché hai lasciato un\'impronta nel mio cuore.', '', 28153),
(151675, 'itIT', 'Sei un tipo interessante. Mag\'har potremmo uscire insieme...', '', 28153),
(151674, 'itIT', 'La mia parola d\'ordine è \"zug zug\".', '', 28153),
(151673, 'itIT', 'Non sei solo avvenente... sei una mak\'goraviglia!', '', 28153),
(151672, 'itIT', 'Vieni con me, sarò la tua Roccianera.', '', 28153),
(151671, 'itIT', 'Ti va di camminare con me al chiaro di Torvaluna?', '', 28153),
(151670, 'itIT', 'Tua madre è un Elementale del Fuoco? Perché il mio cuore brucia per te.', '', 28153),
(151669, 'itIT', 'Muori bene.', '', 28153),
(151668, 'itIT', 'Non ho altro da dire.', '', 28153),
(151667, 'itIT', 'Puoi andare.', '', 28153),
(151666, 'itIT', 'Vai con onore.', '', 28153),
(151665, 'itIT', '<Breathe as if you are running: Total 3>', '', 28153),
(151664, 'itIT', '<Jumping off ground: Total 3>', '', 28153),
(151663, 'itIT', '<Landing from jump: Total 3>', '', 28153),
(151662, 'itIT', '<Vocalized cheer: Total 3>', '', 28153),
(151661, 'itIT', '<Deep breath before focusing magic: Total 3>', '', 28153),
(151660, 'itIT', '<Release after expending magic: Total 3>', '', 28153),
(151659, 'itIT', '<Distressed cry: Total 3>', '', 28153),
(151658, 'itIT', '<Convey summoning power. Energy buildup: Total 5-7>', '', 28153),
(151657, 'itIT', '<Release spell, throwing energy: Total 3-5>', '', 28153),
(151656, 'itIT', '<Standard attack: Total 10>', '', 28153),
(151655, 'itIT', '<Big attack: Total 5>', '', 28153),
(151654, 'itIT', '<Falling from high terrain. Impending injury or death: Total 1>', '', 28153),
(151653, 'itIT', '<Player takes a wound: Total 10>', '', 28153),
(151652, 'itIT', '<Player takes significant wound: Total 5>', '', 28153),
(151651, 'itIT', '<Long attack with wind up. Jump attacks: Total 5-7>', '', 28153),
(151650, 'itIT', '<Convey releasing power or charging enemy: Total 4-6>', '', 28153),
(151649, 'itIT', '<Charging to attack enemy: Total 5-7>', '', 28153),
(151648, 'itIT', '<Dying sounds: Total 5>', '', 28153),
(151647, 'itIT', 'Non può unirsi a questo gruppo.', '', 28153),
(151646, 'itIT', 'Ho finito le munizioni.', '', 28153),
(151645, 'itIT', 'Non ho abbastanza energia.', '', 28153),
(151644, 'itIT', 'Mi manca l\'energia necessaria.', '', 28153),
(151643, 'itIT', 'Ho bisogno di mana prima di farlo.', '', 28153),
(151642, 'itIT', 'Ho poco mana.', '', 28153),
(151641, 'itIT', 'Ho bisogno di mana.', '', 28153),
(151640, 'itIT', 'Non ho abbastanza rabbia.', '', 28153),
(151639, 'itIT', 'Devo avere più rabbia!', '', 28153),
(151638, 'itIT', 'È troppo distante.', '', 28153),
(151637, 'itIT', 'Sono fuori portata.', '', 28153),
(151636, 'itIT', 'Devo avvicinarmi.', '', 28153),
(151635, 'itIT', 'Non possiamo invitare nessun altro.', '', 28153),
(151634, 'itIT', 'Non posso bere altro al momento.', '', 28153),
(151633, 'itIT', 'Non ho ancora quest\'abilità.', '', 28153),
(151632, 'itIT', 'Non posso ancora farlo.', '', 28153),
(151631, 'itIT', 'L\'incantesimo non è pronto.', '', 28153),
(151630, 'itIT', 'Non posso ancora lanciarlo.', '', 28153),
(151629, 'itIT', 'Si levino le ancore.', 'Salpiamo l\'ancora.', 28153),
(151628, 'itIT', 'Si sta ancora ricaricando.', '', 28153),
(151627, 'itIT', 'Tieni la polvere da sparo asciutta.', 'Tieni la polvere da sparo asciutta.', 28153),
(151626, 'itIT', 'Sempre fedeli.', 'Sempre fedeli.', 28153),
(151625, 'itIT', 'Ricordati di legare gli ormeggi.', 'Ricordati di legare gli ormeggi.', 28153),
(151624, 'itIT', 'La marea non aspetta nessuno.', 'La marea non aspetta nessuno.', 28153),
(151623, 'itIT', 'Una tempesta è in arrivo, lo percepisco.', 'Arriva una tempesta, lo sento.', 28153),
(151622, 'itIT', 'La congrega cadrà.', 'La congrega cadrà.', 28153),
(151621, 'itIT', 'L\'unica strega buona è una strega morta.', 'L\'unica strega buona è una strega morta.', 28153),
(151620, 'itIT', 'Gloria alla Casata dei Crestabianca.', 'Gloria alla Casata dei Crestabianca.', 28153),
(151619, 'itIT', 'Venti taglienti e ancora salda.', 'Venti taglienti e ancora salda.', 28153),
(151618, 'itIT', 'Rimani sempre vigile.', 'Rimani sempre vigile.', 28153),
(151617, 'itIT', 'Che i venti ti siano propizi.', 'Che i venti ti siano propizi.', 28153),
(151616, 'itIT', 'Per Kul Tiras!', 'Per Kul Tiras!', 28153),
(151615, 'itIT', 'Non posso depredarlo in questo momento.', '', 28153),
(151614, 'itIT', 'Non ho un bersaglio.', '', 28153),
(151613, 'itIT', 'Prima devo avere un bersaglio.', '', 28153),
(151612, 'itIT', 'Ho bisogno di un bersaglio.', '', 28153),
(151611, 'itIT', 'Non posso farlo.', '', 28153),
(151610, 'itIT', 'Prima devo ottenere il permesso.', '', 28153),
(151609, 'itIT', 'Non posso attaccare quel bersaglio.', '', 28153),
(151608, 'itIT', 'Non lo posso attaccare.', '', 28153),
(151607, 'itIT', 'Il mio inventario è pieno.', '', 28153),
(151606, 'itIT', 'Non posso portare altro.', '', 28153),
(151605, 'itIT', 'È bloccato.', '', 28153),
(151604, 'itIT', 'Non posso trasportarne altri.', '', 28153),
(151603, 'itIT', 'Stromgarde è ancora debole, non sopravviverà a un attacco diretto con i Demolitori. Distruggeteli prima che si avvicinino!', '', 28153),
(151602, 'itIT', 'Non posso ancora usare quest\'oggetto.', '', 28153),
(151601, 'itIT', 'Non è ancora pronto.', '', 28153),
(151600, 'itIT', 'L\'oggetto si sta ancora ricaricando.', '', 28153),
(151599, 'itIT', 'Le nostre fortificazioni sono ancora piuttosto deboli. Presto, distruggete quei Demolitori prima che si avvicinino!', '', 28153),
(151598, 'itIT', 'Non ho abbastanza furia.', '', 28153),
(151597, 'itIT', 'Ho poca furia.', '', 28153),
(151596, 'itIT', 'Non ho abbastanza dolore.', '', 28153),
(151595, 'itIT', 'Ho poco dolore.', '', 28153),
(151594, 'itIT', 'Non è una sacca.', '', 28153),
(151593, 'itIT', 'Dobbiamo fermare quei Demolitori prima che demoliscano noi!', '', 28153),
(151592, 'itIT', 'Non ho i fondi necessari.', '', 28153),
(151591, 'itIT', 'Questo va oltre le mie disponibilità.', '', 28153),
(151590, 'itIT', '', 'Schierate i Demolitori! Non permetteremo che l\'Alleanza si assicuri un avamposto!', 28153),
(151589, 'itIT', 'Costa troppo.', '', 28153),
(151588, 'itIT', 'Hai mai visto lo stomaco di un kraken? Continua così e forse lo farai.', 'Hai mai visto lo stomaco di un kraken? Continua così e forse lo farai.', 28153),
(151587, 'itIT', 'Inviate i Demolitori! Dobbiamo schiacciare chilli insetti dell\'Alleanza prima che lo facciano con noi!', '', 28153),
(151586, 'itIT', 'Mi sa che non hai tutti i remi al posto giusto.', 'Mi sa che non hai tutti i remi al posto giusto.', 28153),
(151585, 'itIT', 'Mandate i Demolitori! Le mura di Stromgarde si sgretoleranno dinanzi alla potenza dell\'Orda!', '', 28153),
(151584, 'itIT', 'Trabocchi di sale, non è così?', 'Cos\'è, hai bevuta troppa acqua salata?', 28153),
(151583, 'itIT', 'Macchine d\'Assedio! Abbatteteli!', '', 28153),
(151582, 'itIT', 'Voi vermi impudenti non avete alcun diritto qui.', '', 28153),
(151581, 'itIT', '', 'Stanno arrivando le loro Macchine d\'Assedio! Distruggiamole prima che si avvicinino alla base.', 28153),
(151580, 'itIT', 'La mia arma richiede due mani.', '', 28153),
(151579, 'itIT', 'L\'abilità non è pronta.', '', 28153),
(151578, 'itIT', 'Non posso ancora farlo.', '', 28153),
(151577, 'itIT', 'Non è ancora pronta.', '', 28153),
(151576, 'itIT', 'Non è la posizione giusta.', '', 28153),
(151575, 'itIT', 'Questa sacca è piena.', '', 28153),
(151574, 'itIT', 'Non posso farlo qui.', '', 28153),
(151573, 'itIT', 'Non posso lasciare quest\'oggetto.', '', 28153),
(151572, 'itIT', 'Quest\'oggetto è vincolato a me.', '', 28153),
(151571, 'itIT', 'Non lo posso equipaggiare.', '', 28153),
(151570, 'itIT', 'Non sono di livello abbastanza alto per usarlo.', '', 28153),
(151569, 'itIT', 'Non lo posso ancora usare.', '', 28153),
(151568, 'itIT', 'La mia competenza non è abbastanza alta.', '', 28153),
(151567, 'itIT', 'Non potrò mai equipaggiare quest\'oggetto.', '', 28153),
(151566, 'itIT', 'Per prima cosa avremo bisogno di legna dalla Segheria delle Alture. Inoltre ci servirà del ferro, che troveremo alla Vena Mineraria di Galson.', '', 28153),
(151565, 'itIT', 'Non posso imparare quest\'incantesimo.', '', 28153),
(151564, 'itIT', 'Ti sbagli, Dama Liadrin. Le bandiere dell\'Alleanza sventoleranno ancora per tutta Arathi.', '', 28153),
(151563, 'itIT', '', 'Finiscila con questa farsa, Danath. I Cacciatroll non hanno più alcun diritto su questa terra.', 28153),
(151562, 'itIT', 'Non posso depredarlo.', '', 28153),
(151561, 'itIT', 'Quest\'oggetto non è mio.', '', 28153),
(151560, 'itIT', 'Devo avvicinarmi.', '', 28153),
(151559, 'itIT', 'Il sentimento non è reciproco, Cacciatore dell\'Ombra.', '', 28153),
(151558, 'itIT', 'È troppo lontano.', '', 28153),
(151557, 'itIT', 'Non ci arrivo.', '', 28153),
(151556, 'itIT', 'Danath Cacciatroll. È nu piacere fare finalmente la conoscenza tua...', '', 28153),
(151555, 'itIT', 'Non posso scambiare quest\'oggetto.', '', 28153),
(151554, 'itIT', 'Non posso usare quest\'oggetto.', '', 28153),
(151553, 'itIT', 'Quest\'oggetto non è equipaggiato.', '', 28153),
(151552, 'itIT', 'No, Arathi appartiene a ME. Tu e la tua Orda pagherete per questo affronto, Eitrigg.', '', 28153),
(151551, 'itIT', 'Deve essere prima equipaggiato.', '', 28153),
(151550, 'itIT', 'Cacciatroll! Faresti meglio a muoverti. Arathi appartiene all\'Orda ora.', '', 28153),
(151549, 'itIT', 'Per prima cosa, dobbiamo rafforzare questa posizione. Recupera della legna e del ferro.', '', 28153),
(151548, 'itIT', 'Schiacciate questo nemico!', '', 28153),
(151547, 'itIT', 'Concordo, Dama Liadrin. Non vedo l\'ora di far calare la giustizia su una Paladina deviata dell\'Orda.', '', 28153),
(151546, 'itIT', 'Sul mio bersaglio!', '', 28153),
(151545, 'itIT', 'Il mio bersaglio deve cadere!', '', 28153),
(151544, 'itIT', 'Da questa parte.', '', 28153),
(151543, 'itIT', 'Lasciate la guida a un Orco.', '', 28153),
(151542, 'itIT', '', 'Turalyon? Ah! Sarà... interessante...', 28153),
(151541, 'itIT', 'Di qua.', '', 28153),
(151540, 'itIT', 'Per l\'Orda!', '', 28153),
(151539, 'itIT', 'Sono ferito!', '', 28153),
(151538, 'itIT', 'Ho bisogno di cure!', '', 28153),
(151537, 'itIT', 'Non startene là, dammi una mano!', '', 28153),
(151536, 'itIT', 'Aiuto!', '', 28153),
(151535, 'itIT', 'Non un altro passo.', '', 28153),
(151534, 'itIT', 'Nessuno si muova.', '', 28153),
(151533, 'itIT', 'La Luce è con noi, Rokhan. Non abbiamo paura delle ombre.', '', 28153),
(151532, 'itIT', 'Statt\' accuort\' alle ombre, Turalyon. Io e l\'Orda stiamo venendo a pigliarti...', '', 28153),
(151531, 'itIT', 'Morte prima del disonore!', '', 28153),
(151530, 'itIT', 'Attacchiamo!', '', 28153),
(151529, 'itIT', 'Mok-thora ka!', '', 28153),
(151528, 'itIT', 'Schiacciamo i nostri nemici!', '', 28153),
(151527, 'itIT', 'È ora di eliminare te e la tua armata dell\'Orda dalle colline di Arathi, Eitrigg.', '', 28153),
(151526, 'itIT', 'Spezziamo le loro difese!', '', 28153),
(151525, 'itIT', 'Ripiegate, o morirete!', '', 28153),
(151524, 'itIT', 'Combatteremo un altro giorno!', '', 28153),
(151523, 'itIT', 'Via! Andate via!', '', 28153),
(151522, 'itIT', 'È odore di feccia dell\'Alleanza quello che sento? Sembra che sia ora di combattere.', '', 28153),
(151521, 'itIT', 'Tenersi pronti!', '', 28153),
(151520, 'itIT', 'Torna a controllare di tanto in tanto. Non sopporterei di veder sprecato quel ferro.', '', 28153),
(151519, 'itIT', 'Bruciamoli tutti!', '', 28153),
(151518, 'itIT', 'Fuoco!', '', 28153),
(151517, 'itIT', 'Arriveranno presto. Dobbiamo costruire la base e per farlo ci servono legna e ferro.', '', 28153),
(151516, 'itIT', 'La vostra Orda se ne andrà via zoppicando quando avrò finito di prendervi a calci! Ahah!', '', 28153),
(151515, 'itIT', '', 'Fatti da parte, Muradin. Questo territorio è dell\'Orda.', 28153),
(151514, 'itIT', 'No, sto cercando qualche feccia dell\'Orda su cui provare la mia nuova lama!', '', 28153),
(151513, 'itIT', 'Che ci fai accà, Muradin? Stai cercando guai?', '', 28153),
(151512, 'itIT', 'Perché invece non torni tu nella tua landa desolata, Orco pulcioso?!?', '', 28153),
(151511, 'itIT', 'Muradin! I tuoi Nani hanno oltrepassato il limite. Tornatevene fra le vostre montagne.', '', 28153),
(151510, 'itIT', '', 'Presto l\'Alleanza sarà alle nostre porte. Dobbiamo muoverci in fretta. Raccogliete legna e ferro, cosicché potremo stabilire una posizione.', 28153),
(151509, 'itIT', '', 'Non illuderti, vecchio. Siamo qui per riprenderci Stromgarde.', 28153),
(151508, 'itIT', 'Dama Liadrin! Benvenuta ad Arathi. Immagino che tu sia qui per arrenderti.', '', 28153),
(151507, 'itIT', '', 'Sei stato via troppo a lungo, Turalyon. Il mondo è andato avanti senza di te.', 28153),
(151506, 'itIT', 'Cosa? Invasori dell\'Orda con una Paladina al comando? Dove siamo finiti?', '', 28153),
(151505, 'itIT', '', 'Provaci se vuoi, Muradin. Questo è territorio dell\'Orda ora.', 28153),
(151504, 'itIT', 'Faresti meglio a fermarti, bellezza, o la tua faccia diventerà il bersaglio dei mortai dell\'Alleanza.', '', 28153),
(151503, 'itIT', 'Danath Cacciatroll... io e te teniamo nu conto in sospeso! Ci vediamo sul campo di battaglia...', '', 28153),
(151502, 'itIT', 'Osate invadere Arathi? Con un TROLL al comando? Avete commesso un terribile errore.', '', 28153),
(151501, 'itIT', '\"Pelleverde\"? Oh oh... ora sì che mi hai fatto arrabbiare.', '', 28153),
(151500, 'itIT', 'Recupero', 'Recupero', 28153),
(151499, 'itIT', '<Klause trattiene una risata.>\n\nSì, probabilmente sì. Ho un bel po\' di parenti in giro per il mondo.', '', 28153),
(151498, 'itIT', 'Osi invadere Stromgarde, dimora dei Cacciatroll? Fuori dai piedi, maledetto pelleverde.', '', 28153),
(151497, 'itIT', 'Oggi rivendichiamo ciò che è nostro di diritto. Per l\'Alleanza!', '', 28153),
(151496, 'itIT', 'Per troppo tempo Stromgarde è stata profanata dagli invasori.', '', 28153),
(151495, 'itIT', 'Per l\'Alleanza!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151494, 'itIT', 'Soldati dell\'Alleanza! Oggi strapperemo la nobile città di Stromgarde dalle mostruose grinfie dell\'Orda.', '', 28153),
(151493, 'itIT', 'Oggi ci riprenderemo le colline di Arathi... per l\'Alleanza!', '', 28153),
(151492, 'itIT', 'Caricate i fucili e sguainate le lame!', '', 28153),
(151491, 'itIT', '', 'Arathi sarà nostra! Per l\'Orda!', 28153),
(151490, 'itIT', '', 'Concentriamoci sulla missione. Prima conquisteremo Ar\'gorok, poi proseguiremo verso Stromgarde!', 28153),
(151489, 'itIT', 'Ventofermo? Ho già conosciuto qualcuno con quel nome prima d\'ora.', 'Ventofermo? Ho già conosciuto qualcuno con quel nome prima d\'ora.', 28153),
(151488, 'itIT', 'Impacchettate tutto, ragazzi! Portiamo queste armi fuori di qui!', '', 28153),
(151487, 'itIT', 'La Fortezza di Stromgarde è stata potenziata in un Castello.', '', 28153),
(151486, 'itIT', 'Abbiamo terminato la costruzione dell\'Armeria.', '', 28153),
(151485, 'itIT', 'L\'Officina è pronta.', '', 28153),
(151484, 'itIT', 'Il nostro Palazzo è stato potenziato in una Fortezza.', '', 28153),
(151483, 'itIT', 'L\'Altare dei Re è ultimato.', '', 28153),
(151482, 'itIT', 'La nostra Fortezza ora è un Castello!', '', 28153),
(151481, 'itIT', 'L\'Armeria è stata ultimata.', '', 28153),
(151480, 'itIT', 'L\'Officina è pronta per costruire dei carri.', '', 28153),
(151479, 'itIT', 'Il nostro Palazzo è stato potenziato in una Fortezza.', '', 28153),
(151478, 'itIT', 'L\'Altare dei Re è stato completato.', '', 28153),
(151477, 'itIT', 'Benissimo! La nostra Fortezza è stata potenziata in un Castello!', '', 28153),
(151476, 'itIT', 'L\'armeria è pronta. Possiamo armare le nostre truppe!', '', 28153),
(151475, 'itIT', 'Officina operativa. È ora di costruire qualche carro!', '', 28153),
(151474, 'itIT', 'Il Palazzo è stato potenziato in una Fortezza!', '', 28153),
(151473, 'itIT', 'L\'Altare dei Re è pronto!', '', 28153),
(151472, 'itIT', '', 'La nostra Roccaforte ora è un Bastione. Per l\'Orda!', 28153),
(151471, 'itIT', '', 'Questa nuova Armeria fornirà un equipaggiamento migliore alle nostre truppe.', 28153),
(151470, 'itIT', '', 'L\'Officina è stata completata.', 28153),
(151469, 'itIT', '', 'La potenza della nostra base cresce. La Sala del Consiglio ora è una Roccaforte.', 28153),
(151468, 'itIT', '', 'L\'Altare delle Tempeste è pronto.', 28153),
(151467, 'itIT', 'La Caserma è pronta per l\'addestramento di nuove truppe.', '', 28153),
(151466, 'itIT', 'Abbiamo ultimato la nostra Caserma. Cominciamo ad addestrare le truppe.', '', 28153),
(151465, 'itIT', 'Caserma completata! È ora di addestrare le nostre truppe!', '', 28153),
(151464, 'itIT', '', 'La Caserma è pronta a iniziare l\'addestramento di nuove truppe.', 28153),
(151463, 'itIT', 'La Roccaforte è ora nu Bastione!', '', 28153),
(151462, 'itIT', 'Abbiamo fatto diventare la Sala del Consiglio na Roccaforte.', '', 28153),
(151461, 'itIT', 'L\'Altare delle Tempeste è pronto.', '', 28153),
(151460, 'itIT', 'La Caserma è pronta. Vinceremo chesta guerra sulle spalle dei Grunt.', '', 28153),
(151459, 'itIT', 'La nostra Roccaforte ora è un Bastione!', '', 28153),
(151458, 'itIT', 'La nostra Sala del Consiglio ora è una Roccaforte!', '', 28153),
(151457, 'itIT', 'Altare delle Tempeste completato.', '', 28153),
(151456, 'itIT', 'La Caserma è pronta. È ora di addestrare dei Grunt!', '', 28153),
(151455, 'itIT', '', 'Non ci riuscirete. Cavalieri del Sangue, abbatteteli!', 28153),
(151454, 'itIT', 'E allora indovina perché mi chiamano Cacciatore dell\'Ombra. Colpite ora, assassini!', '', 28153),
(151453, 'itIT', 'Conosco perfettamente la \"giustizia dell\'Alleanza\". Cavalcaviverne, mostrate loro la furia dell\'Orda!', '', 28153),
(151452, 'itIT', '', 'Mai!', 28153),
(151451, 'itIT', 'Nessuna di cheste terre sarà tua, Cacciatroll. I Troll stavano accà assai prima di te.', '', 28153),
(151450, 'itIT', 'Ha! Questo è quello che pensi tu.', '', 28153),
(151449, 'itIT', '', 'Ora ne ho abbastanza! Cavalieri del Sangue, colpite con la furia della Luce!', 28153),
(151448, 'itIT', 'La Luce nun può più salvarvi, ormai. Cacciatori dell\'Ombra, mostratevi!', '', 28153),
(151447, 'itIT', 'Cavalcaviverne, attaccate dal cielo!', '', 28153),
(151446, 'itIT', '', 'Lo vedremo, Turalyon. Devi ancora vedertela con me.', 28153),
(151445, 'itIT', 'E io starò là ad aspettarvi.', '', 28153),
(151444, 'itIT', 'Non penso proprio, Turalyon.', '', 28153),
(151443, 'itIT', '', 'Non basterà, Nano. Cavalieri del Sangue, alle armi!', 28153),
(151442, 'itIT', 'Sei caduto dritto nella trappola mia, Muradin. Cacciatori dell\'Ombra, tocca a voi!', '', 28153),
(151441, 'itIT', 'Ora, Cavalieri del Vento! Attaccate!', '', 28153),
(151440, 'itIT', '', 'Mai.', 28153),
(151439, 'itIT', 'Guardati le spalle, Muradin!', '', 28153),
(151438, 'itIT', 'Non per molto, Nano. Per l\'Orda!', '', 28153),
(151437, 'itIT', 'Ho perso questa città una volta... non la perderò di nuovo. Specialmente contro di voi. Difensori, mostrate loro la forza di Stromgarde!', '', 28153),
(151436, 'itIT', 'Io al sicuro ora. Torno al lavoro.', '', 28153),
(151435, 'itIT', 'La Luce è al mio fianco. Difensori, avanzate!', '', 28153),
(151434, 'itIT', 'Difenderò Stromgarde fino alla fine, Liadrin. Difensori, resistete!', '', 28153),
(151433, 'itIT', 'Aspetta a festeggiare, Elfa del Sangue. Devi ancora vedertela con me.', '', 28153),
(151432, 'itIT', 'Sì... ci conto.', '', 28153),
(151431, 'itIT', 'Bah! Le posizioni sopraelevate sono sopravvalutate!', '', 28153),
(151430, 'itIT', 'Questo stupido vecchio ha ancora qualche asso nella manica, Troll. Difensori, mostrate loro la forza di Stromgarde!', '', 28153),
(151429, 'itIT', 'La Luce sconfiggerà sempre l\'Ombra, Rokhan. Difensori, avanti!', '', 28153),
(151428, 'itIT', 'Fatti sotto, Rokhan! Ti stavo aspettando. Difensori, mostrategli di che pasta siamo fatti!', '', 28153),
(151427, 'itIT', 'Chiudi la bocca, Troll. L\'Alleanza prevarrà sulla tua spregevole armata di mostri.', '', 28153),
(151426, 'itIT', 'Eppure la Luce brilla ancora su Stromgarde.', '', 28153),
(151425, 'itIT', 'Non c\'è fretta. Ti farò prima ammorbidire un po\' dai miei Archibugieri.', '', 28153),
(151424, 'itIT', 'Stromgarde resiste, Orco. Sarà divertente veder galleggiare il tuo corpo nel mio fossato. Difensori, mostrate loro la forza della nostra città!', '', 28153),
(151423, 'itIT', 'Ho vinto e perso migliaia di battaglie in più di quelle che hai visto tu, Eitrigg. E questa è ben lontana dall\'essere finita. Difensori, avanzate!', '', 28153),
(151422, 'itIT', 'Dovrai prima prenderla, bellezza. Difensori, respingeteli!', '', 28153),
(151421, 'itIT', 'Tsk, tu e la tua razza siete tutti uguali. Ma non importa, morirete in ginocchio come gli altri!', '', 28153),
(151420, 'itIT', 'Abbi pazienza, Orco. Arriverà molto presto.', '', 28153),
(151419, 'itIT', 'E io sento la puzza del tuo alito da quaggiù! Fatti sotto, Orco!', '', 28153),
(151418, 'itIT', 'Ora, Macchine d\'Assedio, abbattete quel cancello. Metteremo la testa di quell\'Elfa del Sangue su una picca!', '', 28153),
(151417, 'itIT', 'Ora, Macchine d\'Assedio, abbattete quel cancello e portatemi Rokhan! Non mi chiamano Cacciatroll per niente...', '', 28153),
(151416, 'itIT', 'Ora, Macchine d\'Assedio, abbattete quel cancello. Quest\'Orco incorrerà nella giustizia dell\'Alleanza!', '', 28153),
(151415, 'itIT', 'L\'Alto Osservatorio è nostro. Questa è la tua ultima occasione, Elfa del Sangue. Arrenditi e forse ti risparmierò.', '', 28153),
(151414, 'itIT', 'L\'Alto Osservatorio è al sicuro. Presto saccheggeremo Ar\'gorok e reclameremo tutto ciò che è nostro!', '', 28153),
(151413, 'itIT', 'L\'Alto Osservatorio è nostro. Un passo importante nella lotta a questi intrusi.', '', 28153),
(151412, 'itIT', 'Il controllo della Vena Mineraria di Galson ci garantirà scorte infinite di ferro.', '', 28153),
(151411, 'itIT', 'Perfetto. La Segheria delle Alture ci fornirà la legna necessaria per ricostruire Stromgarde.', '', 28153),
(151410, 'itIT', 'È la nostra occasione. Assaltate il cancello! Fate calare il castigo su questi intrusi dell\'Orda!', '', 28153),
(151409, 'itIT', 'È la nostra occasione. Assaltate il cancello! La Luce viene a prenderti, Rokhan!', '', 28153),
(151408, 'itIT', 'È la nostra occasione. Assaltate il cancello! La tua ora è giunta, Eitrigg!', '', 28153),
(151407, 'itIT', 'L\'Alto Osservatorio è stato conquistato. La Luce è con l\'Alleanza.', '', 28153),
(151406, 'itIT', 'L\'Alto Osservatorio è nostro. Presto rivendicheremo anche Ar\'gorok. Veniamo a prenderti, Rokhan.', '', 28153),
(151405, 'itIT', 'Abbiamo conquistato l\'Alto Osservatorio. Presto spazzeremo via tutte le forze dell\'Orda.', '', 28153),
(151404, 'itIT', 'Ben fatto. La Vena Mineraria di Galson ci fornirà tutto il ferro di cui avremo bisogno.', '', 28153),
(151403, 'itIT', 'La legna della Segheria sarà fondamentale per costruire la base.', '', 28153),
(151402, 'itIT', 'Presto, mandate le Macchine d\'Assedio! Abbattete il cancello! Mostrate a quell\'Elfa del Sangue cosa possono fare i mortai nanici!', '', 28153),
(151401, 'itIT', 'Presto, mandate le Macchine d\'Assedio! Abbattete il cancello! Bruciate quella capanna dei Troll!', '', 28153),
(151400, 'itIT', 'Presto, mandate le Macchine d\'Assedio! Abbattete il cancello! Fate a brandelli questi orchi!', '', 28153),
(151399, 'itIT', 'L\'Alto Osservatorio è dell\'Alleanza! Siete già pronti a sventolare bandiera bianca?', '', 28153),
(151398, 'itIT', 'Abbiamo conquistato l\'Alto Osservatorio! Veniamo a prenderti, Rokhan.', '', 28153),
(151397, 'itIT', 'Eheh... Non ho mai pagato il conto al bar...', 'Eheh... Non ho mai pagato il conto al bar...', 28153),
(151396, 'itIT', 'L\'Alto Osservatorio è nostro! Per l\'Alleanza!', '', 28153),
(151395, 'itIT', 'Forse... possiamo trovare un accordo...', 'Forse... possiamo trovare un accordo...', 28153),
(151394, 'itIT', 'Con la Vena Mineraria di Galson sotto il nostro controllo, avremo molto ferro.', '', 28153),
(151393, 'itIT', 'Bene, abbiamo conquistato la Segheria delle Alture. Possiamo utilizzare la legna per costruire la nostra base.', '', 28153),
(151392, 'itIT', '', 'Chesto scontro richiede abilità. Qualcosa che voi nun tenete!', 28153),
(151391, 'itIT', '', 'Mandate i Demolitori! Distruggete il cancello! Riducete Stromgarde in polvere!', 28153),
(151390, 'itIT', '$gAttento:Attenta; a quello che fai!', '$gAttento:Attenta; a quello che fai!', 28153),
(151389, 'itIT', '', 'Mandate i Demolitori! Distruggete il cancello! La tua ora è giunta, Turalyon!', 28153),
(151388, 'itIT', 'Qual è il piano?', 'Qual è il piano?', 28153),
(151387, 'itIT', '', 'Mandate i Demolitori! Distruggete il cancello! Facciamo uscire allo scoperto quel Nano!', 28153),
(151386, 'itIT', '', 'L\'Alto Osservatorio è nostro! Un altro passo in avanti verso la conquista di Arathi!', 28153),
(151385, 'itIT', '', 'Ci siamo impadroniti dell\'Alto Osservatorio! Presto l\'Orda verrà a prenderti, Turalyon.', 28153),
(151384, 'itIT', '', 'Abbiamo conquistato l\'Alto Osservatorio, e con esso il vantaggio strategico. La battaglia volge a nostro favore.', 28153),
(151383, 'itIT', '', 'Ben fatto. Non saremmo andati lontano senza il ferro di quella miniera.', 28153),
(151382, 'itIT', 'Anche nella morte nun potete vincere! Fatevi da parte e ammirate la grandezza!', '', 28153),
(151381, 'itIT', '', 'Useremo la legna della Cresta della Scure per costruire le fondamenta della nostra base. Ben fatto.', 28153),
(151380, 'itIT', 'Mandate i Demolitori! Distruggete il cancello! E portatemi la capa di chello stupido vecchio di Cacciatroll!', '', 28153),
(151379, 'itIT', 'Mandate i Demolitori! Nessuna Luce potrà proteggere quel Paladino dalla potenza dell\'Orda!', '', 28153),
(151378, 'itIT', 'Mandate i Demolitori! Quel Nano nun può nascondersi in eterno!', '', 28153),
(151377, 'itIT', 'L\'Alto Osservatorio cadrà in mano all\'Orda, Cacciatroll.', '', 28153),
(151376, 'itIT', 'L\'Alto Osservatorio è nostro, Turalyon. Le ombre si avvicinano...', '', 28153),
(151375, 'itIT', 'Muradin... conquisteremo l\'Alto Osservatorio. Sei pronto a combattere?', '', 28153),
(151374, 'itIT', 'La Miniera dei Baffosecco appartiene all\'Orda.', '', 28153),
(151373, 'itIT', '', 'Da morti valete tanto quanto da vivi. Niente! Me ne occuperò io!', 28153),
(151372, 'itIT', 'Bene. Useremo la legna della Cresta della Scure per costruire la fortezza nostra.', '', 28153),
(151371, 'itIT', 'Mandate i Demolitori! Abbattete il cancello! Facciamo vedere a quell\'idiota Cacciatroll cosa può fare un gruppo di pelleverde!', '', 28153),
(151370, 'itIT', '', 'Sei diventata una giovane donna coraggiosa, Taelia. Tuo padre sarebbe orgoglioso.', 28153),
(151369, 'itIT', 'Mandate i Demolitori! Abbattete il cancello! La battaglia è agli sgoccioli!', '', 28153),
(151368, 'itIT', 'Mandate i Demolitori! Abbattete il cancello! Infilzeremo la testa di quello schifoso Nano su una picca!', '', 28153),
(151367, 'itIT', 'Il capo non sarà felice...', 'Il capo non sarà felice...', 28153),
(151366, 'itIT', 'L\'Alto Osservatorio appartiene all\'Orda. O forse dovrei dire... ai \"pelleverde\".', '', 28153),
(151365, 'itIT', 'L\'Alto Osservatorio è nostro. Dov\'è quell\'ira di cui parlavi, Turalyon? Sto aspettando...', '', 28153),
(151364, 'itIT', 'Oh...', 'Oh...', 28153),
(151363, 'itIT', 'Non era nulla di... personale...', 'Non era nulla di... personale...', 28153),
(151362, 'itIT', 'Abbiamo conquistato l\'Alto Osservatorio. Muradin! Riesco a vedere il tuo grosso naso da quassù!', '', 28153),
(151361, 'itIT', 'Stavo solo... facendo il mio lavoro...', 'Stavo solo... facendo il mio lavoro...', 28153),
(151360, 'itIT', '', 'Taelia... naturalmente. La nostra giovane scudiera dall\'altra parte del mare. È già passato tanto tempo?', 28153),
(151359, 'itIT', 'Ben fatto. Con la Miniera dei Baffosecco, le scorte di ferro non si esauriranno mai.', '', 28153),
(151358, 'itIT', 'La Cresta della Scure è nostra. Possiamo utilizzare la Segheria per costruire la nostra base.', '', 28153),
(151357, 'itIT', 'Niente di personale, ma ci sono regole da rispettare!', 'Niente di personale, ma ci sono regole da rispettare!', 28153),
(151356, 'itIT', 'Il Passo di Granvalore è nostro. Continuate ad attaccare!', '', 28153),
(151355, 'itIT', '', 'Taelia, signora.', 28153),
(151354, 'itIT', 'Ben fatto. Abbiamo riconquistato il Circolo degli Elementi.', '', 28153),
(151353, 'itIT', 'Gli stendardi dell\'Alleanza tornano a sventolare sulla Nuova Fattoria.', '', 28153),
(151352, 'itIT', '', 'Certamente. Il tuo nome?', 28153),
(151351, 'itIT', 'Abbiamo conquistato il Passo di Granvalore.', '', 28153),
(151350, 'itIT', 'Il Circolo degli Elementi ora appartiene all\'Alleanza.', '', 28153),
(151349, 'itIT', 'Ben fatto, soldati. La Nuova Fattoria è nostra.', '', 28153),
(151348, 'itIT', 'Smettila!', 'Smettila!', 28153),
(151347, 'itIT', '', 'Ammiraglio Supremo, dovremmo riportarti al forte. Lì possiamo riesaminare le prove contro la Casata dei Bracescura.', 28153),
(151346, 'itIT', 'Bene, li abbiamo respinti dal Passo di Granvalore. Continuiamo a muoverci!', '', 28153),
(151345, 'itIT', 'Abbiamo conquistato il Circolo degli Elementi!', '', 28153),
(151344, 'itIT', 'Hai superato il limite!', 'Hai superato il limite!', 28153),
(151343, 'itIT', 'Abbiamo saccheggiato la Nuova Fattoria!', '', 28153),
(151342, 'itIT', '', 'Il Circolo degli Elementi è nostro.', 28153),
(151341, 'itIT', '', 'Abbiamo messo in sicurezza la Nuova Fattoria.', 28153),
(151340, 'itIT', 'Sappiamo perfettamente come trattare con i piantagrane!', 'Sappiamo perfettamente come trattare con i piantagrane!', 28153),
(151338, 'itIT', '', 'Bene, questo dovrebbe darci un po\' di tempo.', 28153),
(151337, 'itIT', 'Ehi!', 'Ehi!', 28153),
(151336, 'itIT', 'Statt\' accuort\' alle ombre, feccia dell\'Alleanza. L\'Orda sta venendo a pigliarti...', '', 28153),
(151335, 'itIT', 'Ottimo combattimento. Con la conquista del Crocevia dei Norten, potremo concentrarci su obiettivi più importanti.', '', 28153),
(151333, 'itIT', '', 'Ehi, tu! Posso parlarti un attimo?', 28153),
(151332, 'itIT', 'Per tempo immemore ho atteso la mia vendetta e alla fine tua madre mi ha dato i mezzi per metterla in atto.', '', 28153),
(151331, 'itIT', 'I tuoi antenati hanno spazzato via la mia gente, ma non me.', '', 28153),
(151330, 'itIT', '', 'Gorak Tul?!? Com\'è possibile? I miei antenati ti hanno sconfitto secoli fa!', 28153),
(151329, 'itIT', 'Macchine d\'Assedio, distruggete quella base!', '', 28153),
(151328, 'itIT', 'Vi avevo avvisato, feccia dell\'Orda. Preparatevi a essere annientati!', '', 28153),
(151327, 'itIT', 'Queste terre sono dell\'Alleanza! Le mura di Stromgarde sono benedette dalla Luce e non cadranno contro gente come voi!', '', 28153),
(151326, 'itIT', 'Orda? Sul mio campo di battaglia? Non vedevo l\'ora di un bel combattimento!', '', 28153),
(151324, 'itIT', 'Devi fermarli e assorbire quell\'Azerite per potenziare il cuore!', '', 28153),
(151323, 'itIT', 'Altre ferite stanno comparendo su tutta Azeroth... e in molti intendono usare l\'Azerite per i propri scopi.', '', 28153),
(151322, 'itIT', 'Il Cuore di Azeroth è la chiave per guarire il nostro mondo... ma avremo bisogno di più potere se vogliamo avere una possibilità di successo.', '', 28153),
(151321, 'itIT', 'Magni, è il momento di potenziare il Cuore di Azeroth.', 'Magni, è il momento di potenziare il Cuore di Azeroth.', 28153),
(151320, 'itIT', 'Devo parlare con te a Silitus. Bisogna fare di più per guarire il nostro mondo!', '', 28153),
(151319, 'itIT', '', 'Ho una scopa e non ho paura di usarla!', 28153),
(151318, 'itIT', '', 'Andatevene, maledetti roditori alati!', 28153),
(151317, 'itIT', '', 'Via dalle mie scale!', 28153),
(151316, 'itIT', '', 'Via di qua, brutti uccellacci!', 28153),
(151315, 'itIT', 'Pagate, schifosi!', '', 28153),
(151314, 'itIT', 'Bestie dell\'Incubo, avanzate!', '', 28153),
(151313, 'itIT', 'Ho un buon presentimento. Oggi lo troveremo.', 'Ho un buon presentimento. Oggi lo troveremo.', 28153),
(151312, 'itIT', 'Quegli stivali mi staranno benissimo.', 'Quegli stivali mi staranno benissimo.', 28153),
(151311, 'itIT', 'Ti taglio in due!', 'Ti taglio in due!', 28153),
(151310, 'itIT', 'Nessuno può salvarti qui, feccia.', 'Nessuno può salvarti qui, feccia.', 28153),
(151309, 'itIT', 'Attenzione a dove metti i piedi.', 'Attenzione a dove metti i piedi.', 28153),
(151308, 'itIT', 'Ti spezzerai facilmente...', 'Ti spezzerai facilmente...', 28153),
(151307, 'itIT', 'Aspetta e vedrai...', 'Aspetta e vedrai...', 28153),
(151306, 'itIT', 'Quelle risorse non ti appartengono!', 'Quelle risorse non ti appartengono!', 28153),
(151305, 'itIT', 'Carne fresca!', 'Carne fresca!', 28153),
(151304, 'itIT', 'Gli oceani si scatenano! Sorgete, miei servi!', '', 28153),
(151303, 'itIT', 'Orrori striscianti, venite a nutrirvi!', '', 28153),
(151302, 'itIT', 'Creature del profondo, udite il mio richiamo!', '', 28153),
(151301, 'itIT', 'L\'aria ha buon profumo qui. Non come mia piena d\'Orchi.', '', 28153),
(151300, 'itIT', 'Che l\'oscurità vi colga!', '', 28153),
(151299, 'itIT', 'Inizio a stancarmi di tutto questo. È giunta la tua ora!', '', 28153),
(151298, 'itIT', 'I servitori di Azshara non avranno mai fine. Perché resistere?', '', 28153),
(151297, 'itIT', 'Io non molta paura ora, ma rocce fanno stancare braccia.', '', 28153),
(151295, 'itIT', 'Ora riesce a sentire i sussurri. Non ci resta molto tempo.', '', 28153),
(151294, 'itIT', '', 'Io sarò dietro di voi. Non serve che mi aspettiate!', 28153),
(151293, 'itIT', 'Sotto le maree... in attesa... ci chiama...', '', 28153),
(151292, 'itIT', 'Da questa parte. Io prendo ferro.', '', 28153),
(151291, 'itIT', 'Cerca le rastrelliere di armi vicino. I Senzafede le tengono dappertutto.\n\nTerrò giù la testa fin quando tornerai.', 'Cerca le rastrelliere di armi vicino. I Senzafede le tengono dappertutto.\n\nTerrò giù la testa fin quando tornerai.', 28153),
(151290, 'itIT', '', 'Venti, proteggetemi!', 28153),
(151289, 'itIT', 'Tornerò quando avrò trovato un\'arma da darti.', 'Tornerò quando avrò trovato un\'arma da darti.', 28153),
(151288, 'itIT', '', 'Il vento ci è sempre in poppa!', 28153),
(151287, 'itIT', 'Vi farò a pezzi!', '', 28153),
(151286, 'itIT', 'Il mio scafo è impenetrabile!', '', 28153),
(151285, 'itIT', 'Gli elementi si infuriano!', 'Gli elementi si infuriano!', 28153),
(151284, 'itIT', 'I ladri del regno mortale periranno.', 'I ladri del regno mortale periranno.', 28153),
(151283, 'itIT', 'Ci riprenderemo tutto ciò che avete razziato!', 'Ci riprenderemo tutto ciò che avete razziato!', 28153),
(151282, 'itIT', 'Gli elementi regneranno supremi!', 'Gli elementi regneranno supremi!', 28153),
(151281, 'itIT', 'Non ruberete ciò che è nostro!', 'Non ruberete ciò che è nostro!', 28153),
(151280, 'itIT', 'Queste gemme appartengono ai Signori degli Elementi!', 'Queste gemme appartengono ai Signori degli Elementi!', 28153),
(151279, 'itIT', '<Libera lo schiavo e dagli un\'arma con cui combattere.>', '<Libera la schiava e dagli un\'arma con cui combattere.>', 28153),
(151278, 'itIT', 'Con questo potere, riconquisteremo questo mondo!', 'Con questo potere, riconquisteremo questo mondo!', 28153),
(151277, 'itIT', '<Libera lo schiavo e dagli un\'arma con cui combattere.>', '<Libera la schiava e dagli un\'arma con cui combattere.>', 28153),
(151276, 'itIT', 'Il mio signore mi ricompenserà per la vostra distruzione.', 'Il mio signore mi ricompenserà per la vostra distruzione.', 28153),
(151275, 'itIT', 'Dammi un\'arma e ti ricompenserò con dieci Senzafede morti.', 'Dammi un\'arma e ti ricompenserò con dieci Senzafede morti.', 28153),
(151274, 'itIT', 'Raduna le tue cose. Tu vieni con me!', 'Raduna le tue cose. Tu vieni con me!', 28153),
(151273, 'itIT', 'Spezza queste catene, $gamico:amica;. I Vulpera sono nati per essere liberi.', 'Spezza queste catene, $gamico:amica;. I Vulpera sono nati per essere liberi.', 28153),
(151272, 'itIT', 'Vorrei lavorare, ma non è sicuro.', '', 28153),
(151271, 'itIT', 'Liberami, $PR, e ti aiuterò a uccidere i Senzafede.', 'Liberami, $PR, e ti aiuterò a uccidere i Senzafede.', 28153),
(151270, 'itIT', 'Nessuna pietà per i Senzafede. Non dopo ciò che hanno fatto.', 'Nessuna pietà per i Senzafede. Non dopo ciò che hanno fatto.', 28153),
(151269, 'itIT', 'La farò pagare ai Senzafede per ciò che mi hanno fatto.', 'La farò pagare ai Senzafede per ciò che mi hanno fatto.', 28153),
(151268, 'itIT', 'Ti ha $gmandato:mandata; Nisha? Qualsiasi sia il suo piano, ci sto.', 'Ti ha $gmandato:mandata; Nisha? Qualsiasi sia il suo piano, ci sto.', 28153),
(151267, 'itIT', 'Dammi solo un\'arma, al resto ci penso io.', 'Dammi solo un\'arma, al resto ci penso io.', 28153),
(151266, 'itIT', 'Mi serve soltanto un\'arma.', 'Mi serve soltanto un\'arma.', 28153),
(151265, 'itIT', 'No... le gemme sono mie... non potete... averle...', '', 28153),
(151264, 'itIT', 'No! Stolti!', '', 28153),
(151263, 'itIT', 'Non... avete... vinto...', '', 28153),
(151262, 'itIT', 'Tornerò!', '', 28153),
(151261, 'itIT', 'Il nostro tempo sta arrivando...', '', 28153),
(151260, 'itIT', 'State solo... ritardando... l\'inevitabile.', '', 28153),
(151259, 'itIT', 'Il caos... non può essere contenuto...', '', 28153),
(151258, 'itIT', 'Gli elementi... non possono essere fermati...', '', 28153),
(151257, 'itIT', 'I vostri mari bolliranno, il vostro cielo si infrangerà, le vostre montagne si ergeranno e noi torneremo!', '', 28153),
(151256, 'itIT', 'L\'alba degli elementi sta per giungere!', '', 28153),
(151255, 'itIT', 'Il vostro tempo sta per scadere, mortali.', '', 28153),
(151254, 'itIT', 'Con queste gemme, vi distruggeremo fino all\'ultimo.', '', 28153),
(151253, 'itIT', 'Gli elementi domineranno ancora!', '', 28153),
(151252, 'itIT', 'I minerali dorati ci potenziano!', '', 28153),
(151251, 'itIT', 'Il vostro mondo sarà di nuovo nostro!', '', 28153),
(151250, 'itIT', 'Come osate affrontarmi sul mio piano d\'esistenza?', '', 28153),
(151249, 'itIT', 'Io guardo. Mani troppo piene!', '', 28153),
(151248, 'itIT', 'Mandami a Orgrimmar.', 'Mandami a Orgrimmar.', 28153),
(151247, 'itIT', '', '$n, è bello vederti. Io starò accà per rimanere vicina a Krag\'wa.\n\nI genitori miei mi hanno raccontato nu sacco di storie sul Loa Rana. È n\'onore per me difenderlo dai Troll del Sangue.', 28153),
(151246, 'itIT', 'Così dovrebbe andare. Grazie!', 'Così dovrebbe andare. Grazie!', 28153),
(151245, 'itIT', 'Portami le palle di cannone, così posso continuare a sparare!', 'Portami le palle di cannone, così posso continuare a sparare!', 28153),
(151244, 'itIT', '', 'Drannor. Draynor? Draanor. Drahnor. <Sospira> Dirò semplicemente che vengo dalle Terre Esterne.', 28153),
(151243, 'itIT', '', 'Probabilmente saprai che il mio sangue non è corrotto, ma anche il resto è 100% naturale.', 28153),
(151242, 'itIT', '', 'Una volta mi sono colorata i capelli di verde. Il Capoguerra Malogrido NON l\'ha presa bene.', 28153),
(151241, 'itIT', '', 'Basta con questa traballante e traballosa... roba... temporaleggiante... AHHH! Fatemi spaccare cose!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(151240, 'itIT', '', 'I Manomozza sono guerrieri leggendari, ma non chiedergli mai di farti un massaggio. Fidati di me...', 28153),
(151239, 'itIT', '', 'Azeroth ha così tante regole su chi puoi pugnalare e chi no... chi puoi prendere a pugni e chi no... Dovreste prendere la vita più serenamente!', 28153),
(151238, 'itIT', '', 'Ehi... sei tu che hai lasciato quella Guarnigione ad accumulare spazzatura nella Landa di Fuocogelo?', 28153),
(151237, 'itIT', '', 'Stai pure quanto ti pare, ma ricorda: se lo rompi, lo paghi!', 28153),
(151236, 'itIT', '', 'Prima di procedere, devo sapere una cosa... Quant\'è alta la tua soglia del dolore?', 28153),
(151235, 'itIT', '', 'Solo perché mi piace stare con te non significa che non voglia anche tirarti un pugno.', 28153),
(151234, 'itIT', '', 'Uno Sciamano dei Guerci Insanguinati ci ha appena provato con me. O almeno, è quello che sembrava. O mi stava ammiccando, o aveva qualcosa in un occhio.', 28153),
(151233, 'itIT', '', 'L\'ultima persona che ha cercato di far colpo su di me ha scoperto il vero significato di \"colpire\".', 28153),
(151232, 'itIT', '', 'Un Orco verde mi ha regalato un cuore di zucchero dicendomi \"Ti vil-io bene\". Gli ho detto che poteva tenersi il suo sangue demoniaco e l\'ho preso a mazzate.', 28153),
(151231, 'itIT', '', 'Sai se Faucisaure è scapolo? Quel sale e pepe ha un certo fascino...', 28153),
(151230, 'itIT', '', 'Non ti serve un Portale Oscuro... hai già invaso il mio cuore.', 28153),
(151229, 'itIT', '', 'Ehm... Mi dispiace.', 28153),
(151228, 'itIT', '', 'Patetico! Cadrai dinnanzi ai Mag\'har!', 28153),
(151227, 'itIT', 'Se vuoi una cosa fatta bene...', 'Se vuoi una cosa fatta bene...', 28153),
(151226, 'itIT', 'Avrei dovuto chiedere... quella promozione... Ahhh...', 'A quanto pare... ho bruciato le tappe...', 28153),
(151225, 'itIT', 'Seppellitemi... con i miei soldi...', 'Nulla ferma la morte... e le tasse...', 28153),
(151224, 'itIT', 'La sconfitta... brucia...', 'La pagherai... per questo...', 28153),
(151223, 'itIT', 'Non ne valeva... la pena...', 'Non ne valeva... la pena...', 28153),
(151222, 'itIT', 'Dov\'è... il mio... Indennizzo...? Argh...', 'Non ne valeva... la pena...', 28153),
(151221, 'itIT', '', 'Ti sono grata.', 28153),
(151220, 'itIT', '', 'Ti ringrazio.', 28153),
(151219, 'itIT', 'La Capoguerra ci permette qualsiasi danno collaterale. Brucia!', 'La Capoguerra ci permette qualsiasi danno collaterale. Brucia!', 28153),
(151218, 'itIT', 'Danni collaterali approvati! Brucia!', 'C\'è una taglia sulla tua testa... e intendo riscuoterla!', 28153),
(151217, 'itIT', '', 'Sono in debito con te.', 28153),
(151216, 'itIT', '', 'Cadrai ai miei piedi!', 28153),
(151215, 'itIT', 'Non la fermerai... mai...', 'Non la fermerete... mai...', 28153),
(151214, 'itIT', 'Hai cercato di salvare il villaggio sbagliato.', 'Hai fatto un grossissimo errore!', 28153),
(151213, 'itIT', '', 'Per le lune di Draenor!', 28153),
(151212, 'itIT', 'Mi divertirò un sacco!', 'Adoro le cose che bruciano!', 28153),
(151211, 'itIT', 'Per l\'Orda... e per il profitto!', 'Per l\'Orda!', 28153),
(151210, 'itIT', '', 'Ho fatto solo il mio dovere.', 28153),
(151209, 'itIT', '', 'Non chiedermelo di nuovo.', 28153),
(151208, 'itIT', '', 'È un piacere.', 28153),
(151207, 'itIT', '', 'No.', 28153),
(151206, 'itIT', '', 'Io dico di no.', 28153),
(151205, 'itIT', '', 'Mai!', 28153),
(151204, 'itIT', '', 'Proprio così.', 28153),
(151203, 'itIT', '', 'Giusto.', 28153),
(151202, 'itIT', '', 'Davvero.', 28153),
(151201, 'itIT', '', 'Ho portato disonore al mio clan!', 28153),
(151200, 'itIT', '', 'Lasciami recuperare mana.', 28153),
(151199, 'itIT', '', 'Ho bisogno di mana!', 28153),
(151198, 'itIT', '', 'Muori bene.', 28153),
(151197, 'itIT', '', 'Non ho altro da dire.', 28153),
(151196, 'itIT', '', 'Puoi andare.', 28153),
(151195, 'itIT', '', 'Vai con onore.', 28153),
(151194, 'itIT', '', 'Parla.', 28153),
(151193, 'itIT', '', 'Felice di vederti.', 28153),
(151192, 'itIT', '', 'Lok\'tar!', 28153),
(151191, 'itIT', '', 'Throm\'ka!', 28153),
(151190, 'itIT', '', 'Per favore, ti supplico!', 28153),
(151189, 'itIT', '', 'Abbi pietà di questa povera Orchessa!', 28153),
(151188, 'itIT', '', 'Mostra un po\' di compassione!', 28153),
(151187, 'itIT', '', 'Un lavoro ben fatto.', 28153),
(151186, 'itIT', '', 'Incredibile, direi.', 28153),
(151185, 'itIT', '', 'Mi congratulo con te.', 28153),
(151184, 'itIT', 'Andiamo, queste difese non si pagheranno da sole!', '', 28153),
(151183, 'itIT', '', 'Schiacciate questo nemico!', 28153),
(151182, 'itIT', '', 'Sul mio bersaglio!', 28153),
(151181, 'itIT', '', 'Il mio bersaglio deve cadere!', 28153),
(151180, 'itIT', '', 'Morte prima del disonore!', 28153),
(151179, 'itIT', '', 'Attacchiamo!', 28153),
(151178, 'itIT', '', 'Mok-thora ka!', 28153),
(151177, 'itIT', 'Perché combatti?', 'Perché combatti?', 28153),
(151176, 'itIT', 'L\'Orda prevarrà.', 'L\'Orda prevarrà.', 28153),
(151175, 'itIT', '', 'Siamo sotto attacco!', 28153),
(151174, 'itIT', '', 'Schiacciamo i nemici!', 28153),
(151173, 'itIT', '', 'Spezziamo le loro difese!', 28153),
(151172, 'itIT', '', 'Ripiegate, o morirete!', 28153),
(151171, 'itIT', '', 'Combatteremo un altro giorno!', 28153),
(151170, 'itIT', '', 'Via! Andate via!', 28153),
(151169, 'itIT', '', 'Da questa parte.', 28153),
(151168, 'itIT', '', 'Lasciate la guida a un\'Orchessa.', 28153),
(151167, 'itIT', 'Compagni... continuate senza di me...', 'Compagni... continuate senza di me...', 28153),
(151166, 'itIT', 'Adesso riposerò.', 'Adesso riposerò.', 28153),
(151165, 'itIT', '', 'Di qua.', 28153),
(151164, 'itIT', 'Spiriti... guidatemi!', 'Spiriti... guidatemi!', 28153),
(151163, 'itIT', 'Fatti da parte e potrai vivere.', 'Fatti da parte e potrai vivere.', 28153),
(151162, 'itIT', 'Guariamo o uccidiamo secondo necessità.', 'Guariamo o uccidiamo secondo necessità.', 28153),
(151161, 'itIT', '', 'Per l\'Orda!', 28153),
(151160, 'itIT', 'Orda, a me! Curerò le vostre ferite!', 'Orda, a me! Curerò le vostre ferite!', 28153),
(151159, 'itIT', '', 'Sono ferita!', 28153),
(151158, 'itIT', '', 'Ho bisogno di cure!', 28153),
(151157, 'itIT', 'Che la Madre Terra ci guidi.', 'Che la Madre Terra ci guidi.', 28153),
(151156, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(151155, 'itIT', '', 'Mi farebbe comodo una mano!', 28153),
(151154, 'itIT', '', 'Aiuto!', 28153),
(151153, 'itIT', '', 'Tenersi pronti!', 28153),
(151152, 'itIT', '', 'Bruciamoli tutti!', 28153),
(151151, 'itIT', '', 'Fuoco!', 28153),
(151150, 'itIT', '', 'Non un altro passo.', 28153),
(151149, 'itIT', '', 'Nessuno si muova.', 28153),
(151148, 'itIT', '', '<Applaude>', 28153),
(151147, 'itIT', '', '<Sbadiglia>', 28153),
