(151141, 'itIT', '', '<Piange a dirotto>', 28153),
(151140, 'itIT', '', '<Bacio>', 28153),
(151139, 'itIT', '', '<Ride>', 28153),
(151138, 'itIT', '', '<Ride a crepapelle>', 28153),
