(151113, 'itIT', 'Intendi QUESTI ratti, Reid? Finiscili. Ora.', '', 28153),
(151112, 'itIT', '', 'La mia arma richiede due mani.', 28153),
(151111, 'itIT', '', 'L\'abilità non è pronta.', 28153),
(151110, 'itIT', '', 'Non posso ancora farlo.', 28153),
(151109, 'itIT', '', 'Non è ancora pronta.', 28153),
