(151060, 'itIT', '', 'Ho bisogno di mana prima di farlo.', 28153),
(151059, 'itIT', '', 'Ho poco mana.', 28153),
(151058, 'itIT', '', 'Ho bisogno di mana.', 28153),
(151057, 'itIT', '', 'Non ho abbastanza rabbia.', 28153),
(151056, 'itIT', '', 'Devo avere più rabbia!', 28153),
(151055, 'itIT', '', 'È troppo lontano.', 28153),
(151054, 'itIT', '', 'Sono fuori portata.', 28153),
(151053, 'itIT', '', 'Devo avvicinarmi.', 28153),
(151052, 'itIT', '', 'Non possiamo invitare nessun altro.', 28153),
(151051, 'itIT', '', 'Non posso bere altro al momento.', 28153),
(151050, 'itIT', '', 'Non ho ancora quest\'abilità.', 28153),
(151049, 'itIT', '', 'Non posso ancora farlo.', 28153),
(151047, 'itIT', '', 'L\'incantesimo non è pronto.', 28153),
(151046, 'itIT', '', 'Non posso ancora lanciarlo.', 28153),
(151045, 'itIT', '', 'Si sta ancora ricaricando.', 28153),
(151044, 'itIT', 'Perché dovrei... lasciatemi andare!', '', 28153),
(151043, 'itIT', 'Chesto... nun l\'avevo... previsto...', 'Davvero... notevole, cumpà...', 28153),
(151042, 'itIT', 'Tenete quel buono a nulla lontano da me!', '', 28153),
(151041, 'itIT', 'Andiamo, ragazzi, valgo ogni centesimo!', '', 28153),
(151040, 'itIT', 'Prima di attaccare, dovremmo capire che cosa stanno escogitando questi Troll e come fermarli.', '', 28153),
(151039, 'itIT', 'Qualcosa mi dice che ci aspettano altri guai all\'interno del tempio.', '', 28153),
(151038, 'itIT', 'Ottimo lavoro con quella bestia!', '', 28153),
(151037, 'itIT', 'Ovviamente non siamo gli unici attirati qui da loro.', '', 28153),
(151036, 'itIT', 'Sì, il posto è questo. Percepisco il potere di queste reliquie nelle mie ossa.', '', 28153),
(151034, 'itIT', '', 'Ehi, tu! I miei amici mi hanno data per morta. Puoi darmi una mano?', 28153),
(151031, 'itIT', '', 'Mmm... Affascinante...', 28153),
(151030, 'itIT', 'Impara a cucinarti i tuoi pasti! Mai fidarsi di un cuoco magro!', '', 28153),
(151029, 'itIT', 'I Loa... mi... chiamano...', 'Solo un colpo... fortunato...', 28153),
(151028, 'itIT', 'L\'Orda... continuerà a vivere...', 'L\'Orda... vincerà...', 28153),
(151027, 'itIT', 'Bwonsamdi, arrivo da te...', 'Bwonsamdi, arrivo da te...', 28153),
(151026, 'itIT', 'Stupidi! Ma come si fa a morire per mano di un Loa di un tempio in rovina e senza seguaci?!? Uccidetelo!', '', 28153),
(151025, 'itIT', 'Bwonsamdi... arrivo... da te...', 'Ci vediamo... nell\'Aldilà...', 28153),
(151024, 'itIT', 'Sta per arrivare nu brutto juju verso di te!', 'Nu brutto juju è in arrivo!', 28153),
(151023, 'itIT', 'Oh, sì. Ordini della Capoguerra. Nessun sopravvissuto.', 'Oh, sì. Ordini della Capoguerra. Nessun sopravvissuto.', 28153),
(151022, 'itIT', 'Nun muoverti!', 'Chesto nun lo schiverai, cumpà!', 28153),
(151021, 'itIT', 'Che teniamo accà? Umani pronti da massacrare?', 'Chi teniamo accà? Umani pronti... da massacrare?', 28153),
(151020, 'itIT', 'Razdunk dice che non dovresti stare qui!', '', 28153),
(151019, 'itIT', 'Razdunk manda i saluti suoi.', '', 28153),
(151018, 'itIT', 'Bah! Andiamo, sto morendo di fame!', '', 28153),
(151017, 'itIT', 'I miei fratelli e le mie sorelle un tempo si occupavano di questa terra e degli alberi, ma ormai non è più così da tanto tempo.\n\nSono rimasti ben pochi tra noi a non aver abbandonato quella via.\n\nIl Bosco Legnosecco era uno dei nostri santuari. Un rifugio dalla corruzione che lentamente stava avvolgendo la Foresta Cremisi.\n\nA causa di questa infestazione, pare che anche il suo tempo sia giunto al termine. Ora osservo mentre svanisce, nutrendomi solo dei ricordi di ciò che era un tempo.', '', 28153),
(151016, 'itIT', 'Che i Loa guidino la lama mia!', 'Ti spedirò da Bwonsamdi!', 28153),
(151015, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(151014, 'itIT', 'C\'è qualcosa che non va nella foresta?', 'C\'è qualcosa che non va nella foresta?', 28153),
(151013, 'itIT', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t G\'huun lancia |cFFFF0404|Hspell:267509|h[Millefauci]|h|r, evocando creature che lo assistono!', '|TINTERFACE\\ICONS\\INV_MISC_MONSTERFANG_02.BLP:20|t G\'huun lancia |cFFFF0404|Hspell:267509|h[Millefauci]|h|r, evocando creature che lo assistono!', 28153),
(151011, 'itIT', '', 'Ci vorrà tempo prima che il mio potere sia ripristinato, ma la maledizione che impediva il mio ritorno è stata spezzata.', 28153),
(151010, 'itIT', '', 'Avete la mia gratitudine, eroi.', 28153),
(151009, 'itIT', 'Aspetta, chi sono questi intrusi?!? Stanno corrompendo Sethraliss!', '', 28153),
(151008, 'itIT', 'Mandami al campo di battaglia.', 'Mandami al campo di battaglia.', 28153),
(151007, 'itIT', 'Il suo santuario dovrebbe essere poco più avanti.', '', 28153),
(151006, 'itIT', 'Se non fosse stato per lei, il mondo sarebbe precipitato nel caos.', '', 28153),
(151005, 'itIT', 'Ero lì quando Sethraliss si sacrificò per fermare Mythrax.', '', 28153),
(151003, 'itIT', 'Anche da qui, sento le radici della Foresta Cremisi bramare il sangue. Non mi sarei mai aspettato che la corruzione potesse arrivare a tanto.', '', 28153),
(151002, 'itIT', 'Dovete per forza setacciare ogni corpo in cerca di bottino? Il nostro vero obiettivo è Sethraliss!', '', 28153),
(151001, 'itIT', 'Be\', di certo avete buon gusto in fatto di distruzione.', '', 28153),
(151000, 'itIT', 'Ora vi prego, fate in fretta. Sento che un\'oscurità crescente sta avvolgendo il tempio.', '', 28153),
(150999, 'itIT', 'Avete la mia gratitudine per aver rimosso l\'infestazione.', '', 28153),
(150998, 'itIT', 'Sacrificò sé stessa per fermare Mythrax, ma con la sua morte, le giungle di Vol\'dun avvizzirono diventando sabbia.', '', 28153),
(150997, 'itIT', 'Questo tempio è il luogo dove riposa Sethraliss, una potente Loa che difese la mia gente dalla distruzione molto tempo fa.', '', 28153),
(150996, 'itIT', '', 'Sì! Colpiscili!', 28153),
(150995, 'itIT', '', 'Dieci monete d\'oro su quello grosso!', 28153),
(150993, 'itIT', 'Il tempo della sua rinascita è passato e ora temo che qualcosa stia impedendo il suo ritorno.', '', 28153),
(150990, 'itIT', 'Stai lasciando l\'area designata e sarai $grimosso:rimossa; dal veicolo.', 'Stai lasciando l\'area designata e sarai $grimosso:rimossa; dal veicolo.', 28153),
(150989, 'itIT', 'Un po\' di respiro. Speriamo che basti a permettere di radunarci e recuperare le forze.', '', 28153),
(150988, 'itIT', 'Presto! I nostri marinai hanno bisogno di aiuto! Sono feriti e l\'Orda sta avanzando!', '', 28153),
(150987, 'itIT', 'Che le maree ti siano favorevoli.', '', 28153),
(150986, 'itIT', 'Cavoli freschi!', '', 28153),
(150985, 'itIT', 'Che tu possa sempre avere il vento in poppa.', '', 28153),
(150984, 'itIT', 'Che i venti ti siano propizi.', '', 28153),
(150983, 'itIT', 'Oh, salve.', '', 28153),
(150982, 'itIT', 'Cosa ti serve?', '', 28153),
(150981, 'itIT', 'Lieto di vederti.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150980, 'itIT', 'È ora di spaccare!', '', 28153),
(150979, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(150978, 'itIT', 'L\'Orda è inarrestabile!', 'L\'Orda è inarrestabile!', 28153),
(150977, 'itIT', 'Siamo solo la punta della lancia...', 'Siamo solo la punta della lancia...', 28153),
(150976, 'itIT', '', 'Ugalazul bwrxil\' qu rax.', 28153),
(150975, 'itIT', 'Sconfitta... dalla tua razza?', 'Sconfitta... dalla tua razza?', 28153),
(150974, 'itIT', 'L\'Orda... prevarrà...', 'Queste terre... saranno nostre...', 28153),
(150973, 'itIT', 'Siamo solo la punta... della lancia...', 'Muoio... con onore...', 28153),
(150972, 'itIT', 'Nessuno... può... fermarci...', 'Feccia... incapace...', 28153),
(150971, 'itIT', '', 'L\'abissso... inghiottirà quesssta terra!', 28153),
(150970, 'itIT', '', 'No... l\'ho delusa!', 28153),
(150969, 'itIT', '', 'Sia maledetta la tua razza!', 28153),
(150968, 'itIT', '', 'Acque... prendetemi!', 28153),
(150967, 'itIT', '', 'La mia vita... per la nossstra regina!', 28153),
(150966, 'itIT', '', 'Egli sorge... dagli abisssi...', 28153),
(150965, 'itIT', '', 'La nossstra regina prevarrà...', 28153),
(150964, 'itIT', 'Oh! Torno subito indietro. Ti prego, non denunciarmi!', 'Oh! Torno subito indietro. Ti prego, non denunciarmi!', 28153),
(150963, 'itIT', 'Sarai un degno avversario.', 'Sarai un degno avversario.', 28153),
(150962, 'itIT', 'Non ficcare il naso dove non devi!', 'Non ficcare il naso dove non devi!', 28153),
(150961, 'itIT', 'L\'abissso... inghiottirà quesssta terra!', '', 28153),
(150960, 'itIT', 'No... l\'ho delusa!', '', 28153),
(150959, 'itIT', 'Sia maledetta la tua razza!', '', 28153),
(150958, 'itIT', 'Acque... prendetemi!', '', 28153),
(150957, 'itIT', 'La mia vita... per la nossstra regina!', '', 28153),
(150956, 'itIT', 'Non la fermerete... mai...', '', 28153),
(150955, 'itIT', 'Egli sorge... dagli abisssi...', '', 28153),
(150954, 'itIT', 'La nossstra regina prevarrà...', '', 28153),
(150953, 'itIT', '', 'Impedire loro di mettere in piedi n\'avamposto ha reso la dimora nostra più sicura. Che Gonk ti doni la giusta ricompensa per aver amministrato la vendetta sua.', 28153),
(150952, 'itIT', '', 'Permettere all\'Alleanza di allargare l\'influenza sua a Zandalar sarebbe disastroso. Recupera il possibile, ma nun mostrare alcuna pietà.', 28153),
(150951, 'itIT', 'Se vuoi una cosa fatta bene...', '', 28153),
(150950, 'itIT', 'La tua morte mi darà onore!', 'Questa è la vostra fine!', 28153),
(150949, 'itIT', 'Fateli fuori tutti!', 'Lok\'tar!', 28153),
(150948, 'itIT', 'Sarai un degno avversario!', 'Niente prigionieri!', 28153),
(150947, 'itIT', 'Per... l\'Orda...', 'Per... l\'Orda...', 28153),
(150946, 'itIT', 'Ah, è una bellezza! Ti meriti una ricompensa.', '', 28153),
(150945, 'itIT', '', 'Come osate interferire nei miei affari? Credete davvero di potervi opporre al mio volere?', 28153),
(150944, 'itIT', 'Preparatevi. Questa bestia sarà una degna preda!', '', 28153),
(150943, 'itIT', 'Ci ha condotti nella sua tana!', '', 28153),
(150942, 'itIT', 'Mmm... La traccia continua oltre questo passaggio nauseabondo.', '', 28153),
(150941, 'itIT', 'La perla non è qui. Forse il servo di Azshara è stato più astuto di quanto sembrasse.', '', 28153),
(150940, 'itIT', 'Presto la tua testa decorerà la mia parete!', '', 28153),
(150939, 'itIT', 'Fai pace con la tua regina, la tua vita finisce qui.', '', 28153),
(150938, 'itIT', 'Intrusi?!? Spedirò i vostri corpi nel profondo degli abissi per l\'eternità!', '', 28153),
(150937, 'itIT', 'Il Loa è troppo potente! Ritiratevi al sicuro nell\'oceano! La battaglia è persssa!', '', 28153),
(150936, 'itIT', 'Dissstruggete il tempio! Non lasciate nulla in piedi, neanche una statua! Tutti si inchineranno davanti alla nossstra regina!', '', 28153),
(150935, 'itIT', 'Poteri oscuri o no, tu sarai la nostra prossima preda!', '', 28153),
(150934, 'itIT', 'Benvenuti, intrusi. Siete giusto in tempo per ammirare il vero potere!', '', 28153),
(150933, 'itIT', 'Ottima uccisione... ma la nostra vera preda si è ritirata nel santuario.', '', 28153),
(150932, 'itIT', '', 'La regina esige la tua morte!', 28153),
(150931, 'itIT', '', 'Gloria ad Azshara!', 28153),
(150930, 'itIT', '', 'Il nossstro dessstino è a portata di mano!', 28153),
(150929, 'itIT', '', 'Mi godrò la gloria della tua morte!', 28153),
(150928, 'itIT', '', 'Nesssuno si opporrà alla Regina Azshara!', 28153),
(150927, 'itIT', '', 'L\'Anello delle Maree è nossstro!', 28153),
(150926, 'itIT', '', 'Non puoi comprendere il nossstro potere!', 28153),
(150925, 'itIT', 'Taci, tu nun indossi scarpe.', '', 28153),
(150924, 'itIT', '', 'Magari solo uno? Mi farebbero comodo delle scarpe nuove.', 28153),
(150923, 'itIT', 'Pazienza, sorellina.', '', 28153),
(150922, 'itIT', '', 'Nun si accorgeranno mai. Nessuno sta dicendo di attaccare l\'accampamento, ma farne fuori nu paio nun farebbe male!', 28153),
(150921, 'itIT', 'La regina esige la tua morte!', '', 28153),
(150920, 'itIT', 'Gloria ad Azshara!', '', 28153),
(150919, 'itIT', 'Il nossstro dessstino è a portata di mano!', '', 28153),
(150918, 'itIT', 'Mi godrò la gloria della tua morte!', '', 28153),
(150917, 'itIT', 'Nesssuno si opporrà alla Regina Azshara!', '', 28153),
(150916, 'itIT', 'L\'Anello delle Maree è nossstro!', '', 28153),
(150914, 'itIT', 'Dobbiamo rimanere accà. Se scappi e ci fai accidere tutti, nun rimarrà nessuno a fare rapporto.', '', 28153),
(150913, 'itIT', 'Non puoi comprendere il nossstro potere!', '', 28153),
(150912, 'itIT', 'I miei cavoli!!!', '', 28153),
(150911, 'itIT', 'È ora di prendere un altro grifone. Salta su!', '', 28153),
(150908, 'itIT', 'Il lavoro dei Collorozzo non è sempre di alta qualità, ma paga.', '', 28153),
(150907, 'itIT', 'Abbiamo un grosso ordine di selle per grifoni, ma ci servono altre pellicce. Mettiti al lavoro!', '', 28153),
(150906, 'itIT', 'Meno di loro lassù significa meno di loro giù dalla montagna. Ottimo lavoro!', '', 28153),
(150905, 'itIT', 'I Wendigo stanno aumentando di numero nel ghiacciaio. Vai lassù e fai qualcosa a riguardo!', '', 28153),
(150904, 'itIT', 'Con il potere della Perla delle Maree, le nostre flotte saranno invincibili.', '', 28153),
(150903, 'itIT', '', 'Guarda che non sono fatta d\'oro!', 28153),
(150902, 'itIT', 'Perdonami... capo...', '', 28153),
(150901, 'itIT', '', 'Idiota! Erano costosissimi!', 28153),
(150900, 'itIT', 'Vi ringrazio, eroi. Avete ridato speranza alla gente di Kul Tiras.', '', 28153),
(150899, 'itIT', 'Percepisco la presenza oscura retrocedere. Il santuario tornerà al suo antico splendore.', '', 28153),
(150898, 'itIT', 'Non date ascolto ai sussurri! Quest\'orrore cercherà di corrompere le vostre anime.', '', 28153),
(150897, 'itIT', 'Per la Madre delle Maree!', '', 28153),
(150896, 'itIT', 'All\'erta, eroi. Un male ignoto si nasconde ancora nell\'oscurità. Dobbiamo eliminare la sua influenza da questo santuario.', '', 28153),
(150895, 'itIT', 'C\'è qualcosa che non va. L\'oscurità affligge ancora questo posto.', '', 28153),
(150894, 'itIT', 'Hai voltato le spalle alla marea, maestro, e ora ne sei rimasto sopraffatto.', '', 28153),
(150893, 'itIT', 'Allora spedirò i vostri corpi nel profondo degli abissi per l\'eternità.', '', 28153),
(150892, 'itIT', 'Mai.', '', 28153),
(150891, 'itIT', 'Per l\'ultima volta, unitevi a me... o morite.', '', 28153),
(150890, 'itIT', 'Stolto! Dobbiamo tornare nell\'abbraccio del mare e la Regina Azshara ci darà il potere per farlo!', '', 28153),
(150889, 'itIT', 'Maestro! Ferma questa follia! La flotta di Kul Tiras non deve cadere nell\'oscurità!', '', 28153),
(150888, 'itIT', '', 'Pare che tu abbia ossspiti, Ser Sacraonda.', 28153),
(150887, 'itIT', '', 'Mostra nu po\' di rispetto e lascia che ci parli io... e forse nun ti getterà giù dalla piramide.', 28153),
(150886, 'itIT', 'La flotta di Kul Tiras è quasi nelle tue mani, mia regina.', '', 28153),
(150885, 'itIT', 'Acqua all\'acqua, cenere alla cenere, marea alla marea. Possano le vostre anime trovar pace nelle correnti.', '', 28153),
(150884, 'itIT', 'Presto, eroi! Fermateli prima che la flotta vada persa!', '', 28153),
(150883, 'itIT', 'Dischi dei Titani operativi: inizializzazione Protocollo di Corruzione', 'Dischi dei Titani operativi: inizializzazione Protocollo di Corruzione', 28153),
(150882, 'itIT', 'Dischi dei Titani attivati: inizializzazione Protocollo d\'Inganno', 'Dischi dei Titani attivati: inizializzazione Protocollo d\'Inganno', 28153),
(150881, 'itIT', '', 'Una volta completato il rituale, la flotta di Kul Tiras apparterrà alla Regina Azshara!', 28153),
(150880, 'itIT', 'Benvenuto, Fratello Pike. Sei giusto in tempo per assistere alla nostra vittoria.', '', 28153),
(150879, 'itIT', 'Sacraonda ha corrotto questo luogo sacro. Dobbiamo avanzare e rimediare ai suoi danni.', '', 28153),
(150878, 'itIT', 'Voci?', 'Voci?', 28153),
(150877, 'itIT', 'Fate attenzione. Una presenza oscura ci sta osservando.', '', 28153),
(150876, 'itIT', 'Il santuario deve essere purificato dal male di Ser Sacraonda, eroi.', '', 28153),
(150875, 'itIT', '', 'Padrone! Non abbandonarmi! Nooo!', 28153),
(150874, 'itIT', '', 'Vuoi davvero sfidare il potere di G\'huun? Soffrirai per l\'arroganza tua!', 28153),
(150873, 'itIT', 'Ci sono delle voci nel fango!', 'Ci sono delle voci nel fango!', 28153),
(150872, 'itIT', '', 'Siamo corrotti.\n\nLa luce di Rezan ci ha lasciati. Solo na manciata di coloro che seguivano il grande Re dei Loa possiede ancora qualche briciola di potere, ma persino di loro nun ci si può fidare.\n\nLa nostra era una vita di devozione. Ora cosa diventeremo?', 28153),
(150871, 'itIT', 'È ora di fare qualche aggiornamento!', '', 28153),
(150870, 'itIT', 'Va bene, sono stufo di combattere secondo le regole.', '', 28153),
(150869, 'itIT', 'Fantastico! I nostri soldati faranno buon uso di questi rifornimenti. Ben fatto!', '', 28153),
(150868, 'itIT', 'Gli esploratori dicono che una nave da carico degli Zandalari è stata dirottata da una squadra d\'incursione dei Troll del Sangue. Uccidili e recupera la loro merce.', '', 28153),
(150867, 'itIT', 'Ehi, ragazzi, ci siamo trovati degli avvocati!', '', 28153),
(150866, 'itIT', 'Sì! Vai a cercarti uno stilista!', '', 28153),
(150865, 'itIT', '', '$n! Ehi, $n! Abbiamo una missione per te!', 28153),
(150864, 'itIT', 'Salta!', 'Salta!', 28153),
(150863, 'itIT', 'Nun puoi nasconderti da Bwonsamdi.', '', 28153),
(150862, 'itIT', 'Ci sta qualcosa di strano in te... Bleah, il tanfo dei Cacciatori di Demoni.', '', 28153),
(150861, 'itIT', '|A:Warfronts-BaseMapIcons-Horde-MainHall-Minimap:25:23:0:0|a Il vostro comandante è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il vostro comandante è sotto attacco!', 28153),
(150860, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è sotto attacco!', 28153),
(150859, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è sotto attacco!', 28153),
(150858, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è sotto attacco!', 28153),
(150857, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è sotto attacco!', 28153),
(150856, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è sotto attacco!', 28153),
(150855, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a La Miniera dei Baffosecco è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|a La Miniera dei Baffosecco è sotto attacco!', 28153),
(150854, 'itIT', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a La Cresta della Scure è sotto attacco!', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|a La Cresta della Scure è sotto attacco!', 28153),
(150853, 'itIT', 'Dobbiamo raggiungere i nostri esploratori d\'avanguardia. Fai fuori quella feccia volante!', 'Dobbiamo raggiungere i nostri esploratori d\'avanguardia. Fai fuori quella feccia volante!', 28153),
(150852, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è andato perso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Passo di Granvalore è andato perso!', 28153),
(150851, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è andata persa!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a La Nuova Fattoria è andata persa!', 28153),
(150850, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è andato perso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Circolo degli Elementi è andato perso!', 28153),
(150849, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è andato perso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a L\'Alto Osservatorio è andato perso!', 28153),
(150848, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è andato perso!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|a Il Crocevia dei Norten è andato perso!', 28153),
(150847, 'itIT', 'Eheheh, no, nun è il Sogno, cumpà.', '', 28153),
(150846, 'itIT', 'Ora li spiriti stanno con te, cumpà.', '', 28153),
(150845, 'itIT', 'Ah, nu Cavaliere della Morte. Dovresti vedere il Portale della Morte MIO!', '', 28153),
(150844, 'itIT', 'Le vostre terre saranno le prossime a cadere!', 'Le vostre terre saranno le prossime a cadere!', 28153),
(150843, 'itIT', 'Non puoi fermare le sabbie!', 'Non puoi fermare le sabbie!', 28153),
(150842, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a La Miniera dei Baffosecco è andata persa!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|a La Miniera dei Baffosecco è andata persa!', 28153),
(150841, 'itIT', 'Ahah! Dovevi ricordarti di rotolare via.', '', 28153),
(150840, 'itIT', 'Noi dominiamo ogni cosa!', 'Noi dominiamo ogni cosa!', 28153),
(150839, 'itIT', 'Vi schiacceremo come insetti!', 'Vi schiacceremo come insetti!', 28153),
(150838, 'itIT', 'Stai cercando na Morte Apparente, cumpà? Peccato...', '', 28153),
(150837, 'itIT', 'Per l\'Imperatore!', 'Per l\'Imperatore!', 28153),
(150836, 'itIT', 'Mi sa che hai seguito la luce sbagliata, cumpà.', '', 28153),
(150835, 'itIT', 'Eh... chella Traslazione nun è servita a molto, eh?', '', 28153),
(150834, 'itIT', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a La Cresta della Scure è andata persa!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|a La Cresta della Scure è andata persa!', 28153),
(150833, 'itIT', 'Sì! Voglio dire, ha un aspetto terribile, ma sicuramente $gdiverso:diversa;!', '', 28153),
(150832, 'itIT', '', 'Be\', quell\'$gavventuriero:avventuriera; sembra davvero $gdiverso:diversa;.', 28153),
(150831, 'itIT', 'Credo sia un altro di quegli \"eroi\". Puzza come qualcuno con tutti i peli bruciati!', '', 28153),
(150830, 'itIT', '', 'Cosa diavolo è questa puzza?', 28153),
(150829, 'itIT', '', 'Waldorf, quello non è un Verrospino, è solo un altro di quegli \"eroi\"!', 28153),
(150828, 'itIT', 'Ahah, tutta chell\'armatura nun ti è servita a molto, eh?', '', 28153),
(150827, 'itIT', 'Ehi, Statler, passami la mia spada! C\'è un Verrospino in arrivo lungo la strada!', '', 28153),
(150826, 'itIT', 'Ohhh, hai perso la tua piccola Pietra dell\'Anima, eh?', '', 28153),
(150825, 'itIT', '', 'Hai ragione! Sono brutti anche da vicino!', 28153),
(150824, 'itIT', 'Vedi gli abiti di $n? Non sono lontanamente così brutti!', '', 28153),
(150823, 'itIT', 'Ah, stai accà per passare nu po\' di tempo di qualità con Bwonsamdi?', '', 28153),
(150822, 'itIT', 'Ahahah! Chella sì che è stata na morte divertente!', '', 28153),
(150821, 'itIT', 'Magari sono gli abiti... ma mi sa che sono tutti brutti così!', '', 28153),
(150820, 'itIT', '', 'Bene, bene, bene... guarda un po\' cosa mi ha portato il Saurolisco! È $n!', 28153),
(150819, 'itIT', '', 'Dove l\'ha preso quel completo? Da un Trogg?', 28153),
(150818, 'itIT', 'Ehi, Statler, guarda che roba che indossa $n!', '', 28153),
(150817, 'itIT', 'Credo di sì! Cielo, puzza più di quanto immaginassi! Ah!', '', 28153),
(150816, 'itIT', '', 'Ehi, Waldorf! È $gquello il \"famoso\":quella la \"famosa\"; $R che era insieme a Jaina?', 28153),
(150815, 'itIT', '', 'Sì! Puzzi! Ahahah!', 28153),
(150814, 'itIT', 'Ehi tu! Sì, tu, $R con la faccia!', '', 28153),
(150813, 'itIT', 'Ho visto cavalli con uno stile migliore!', '', 28153),
(150812, 'itIT', '', 'Ehi, $n! Pensi davvero che quell\'elmo stia bene con quegli stivali?', 28153),
(150811, 'itIT', 'Volevo sapere altro.', 'Volevo sapere altro.', 28153),
(150810, 'itIT', '', 'Gli antichi Drust. Il loro odio per i Kul Tirani trascende le loro vite mortali. Persino dall\'aldilà si riesce a percepire l\'odio per la nostra esistenza.\n\nProvo pena per chiunque sia stato la causa della loro venuta.', 28153),
(150809, 'itIT', 'Gli spiriti vendicativi dei morti?', 'Gli spiriti vendicativi dei morti?', 28153),
(150808, 'itIT', 'Ti sradicherò!', '', 28153),
(150807, 'itIT', '', 'La magia che queste streghe usano è antica e profondamente corrotta. Hanno costretto la fauna a servirle, distruggendo l\'equilibrio. Le loro creazioni abominevoli contengono gli spiriti vendicativi dei morti.', 28153),
(150806, 'itIT', '', 'Ci sta gioia nella caccia e soddisfazione nella vendetta!', 28153),
(150805, 'itIT', '', 'Quei traditori ammazza-Loa stanno ancora cercando di infangare il Tempio di Rezan. Il vecchio K\'zlotec gli insegnerà che succede a chi insulta il Loa dei Re.', 28153),
(150804, 'itIT', 'Naza bul rexil qalic ul\'.', '', 28153),
(150803, 'itIT', 'Cos\'è successo alla foresta?', 'Cos\'è successo alla foresta?', 28153),
(150802, 'itIT', 'Ca\' lish!', '', 28153),
(150801, 'itIT', '', 'Potresti trovarlo in una delle caverne nelle vicinanze. Buona fortuna, $n.', 28153),
(150800, 'itIT', '', 'Calcaverde era debole, ma era solo questione di tempo prima che tornasse alla caccia.', 28153),
(150799, 'itIT', 'Ug\' bwafa qilikx za!', '', 28153),
(150798, 'itIT', 'Queste mura ti accoglieranno sempre a braccia aperte.', '', 28153),
(150797, 'itIT', 'Oh, povera creatura, ti serve aiuto dal vecchio Bwonsamdi? Ihihih...', '', 28153),
(150796, 'itIT', 'I ranishu hanno avvelenato i miei figli. Sono deboli e la loro vita è appesa a un filo. Usa il mio potere per salvarli, come hai fatto con me.', '', 28153),
(150795, 'itIT', 'Hul bala miz rilakich...', '', 28153),
(150794, 'itIT', 'Mmm, mmm, mmm. Be\', nun mi aspettavo di vederti accà così presto.', '', 28153),
(150793, 'itIT', 'Lok\'tar ogar!', 'Lok\'tar ogar!', 28153),
(150792, 'itIT', 'PER L\'ORDA!', 'PER L\'ORDA!', 28153),
(150791, 'itIT', 'Sono superiore a voi!', '', 28153),
(150790, 'itIT', 'Soldati dell\'Orda, preparate le vostre lame! Oggi marceremo contro i Kaldorei!', '', 28153),
(150789, 'itIT', 'Ah, fammi indovinare... Hai esagerato nu poco, eh? Ahahah!!!', '', 28153),
(150788, 'itIT', 'Il qul zerakish!', '', 28153),
(150787, 'itIT', 'You should now be fixed. Journey to Sylvanas in Orgrimmar to begin your epic shenanigans.', '', 28153),
(150786, 'itIT', 'I started Nazmir but can\'t start Zuldazar. Please fix me.', 'I started Nazmir but can\'t start Zuldazar. Please fix me.', 28153),
(150785, 'itIT', 'Che ti serve?', '', 28153),
(150784, 'itIT', 'È nel nostro interesse che continui a farlo.', '', 28153),
(150783, 'itIT', 'Mettete in fuga i lealisti Crestabianca e sarete ricompensati a dovere.', '', 28153),
(150781, 'itIT', 'Raduna la tua ciurma e va\' al Porto del Commercio. Una volta là, saccheggiate ogni cosa fino ad arrivare alle loro terre. Privateli delle loro risorse e riempite i nostri scrigni.', '', 28153),
(150779, 'itIT', 'Capitano Maniferree, mi è stato riferito dal nostro benefattore che la Casata dei Crestabianca sta cadendo in rovina.', '', 28153),
(150778, 'itIT', 'Perché non sei al tuo posto?', 'Perché non sei al tuo posto?', 28153),
(150777, 'itIT', 'Desidero scegliere Kimbul come mio Loa.', 'Desidero scegliere Kimbul come mio Loa.', 28153),
(150776, 'itIT', 'L\'autentico Cuore di Azeroth!', '', 28153),
(150775, 'itIT', '<Il santuario fu costruito come tributo a Kimbul, il Signore delle Bestie.>', '<Il santuario fu costruito come tributo a Kimbul, il Signore delle Bestie.>', 28153),
(150773, 'itIT', 'Sì?', 'Sì?', 28153),
(150772, 'itIT', 'Io posso anche essere la sua voce, ma tu sei il suo campione. E ha bisogno che tu combatta per lei.', '', 28153),
(150771, 'itIT', 'Azeroth ti chiama, campione. Ti offre un dono... nato dalla sua stessa essenza.', '', 28153),
(150770, 'itIT', 'Libero! Dobbiamo metterci al sicuro all\'interno del tempio!', 'Libera! Dobbiamo metterci al sicuro all\'interno del tempio!', 28153),
(150769, 'itIT', 'Cos... Cosa mi è successo?', 'Cos... Cosa mi è successo?', 28153),
(150768, 'itIT', '', 'G\'huun! Dammi la forza tua!', 28153),
(150767, 'itIT', 'Te ne devo una nell\'Aldilà, $gamico:amica;.', 'Te ne devo una nell\'Aldilà, $gamico:amica;.', 28153),
(150766, 'itIT', '', 'La fine si avvicina!', 28153),
(150765, 'itIT', '', 'Implora pietà!', 28153),
(150764, 'itIT', '', 'Tutti serviranno il padrone!', 28153),
(150763, 'itIT', 'Finalmente, libero da chelle ossa maledette!', 'Finalmente, libera da chelle ossa maledette!', 28153),
(150762, 'itIT', 'Mo\' è il momento di privare Harlan Sweete delle ricchezze sue.', '', 28153),
(150761, 'itIT', 'Dischi dei Titani attivati: inizializzazione Protocollo di Caos', 'Dischi dei Titani attivati: inizializzazione Protocollo di Caos', 28153),
(150760, 'itIT', 'La ridarò indietro, lo giuro!', 'La ridarò indietro! Lo giuro!', 28153),
(150759, 'itIT', 'E chesta è la fine di Harlan Sweete. Mo\' i mari sono nostri!', '', 28153),
(150758, 'itIT', 'Ahhh!', 'Ahhh!', 28153),
(150757, 'itIT', 'L\'ho rubata io, con le mie mani!', 'L\'ho rubata con le mie mani!', 28153),
(150756, 'itIT', 'Ah! Sapevo che puntare su di voi era na mossa saggia!', '', 28153),
(150755, 'itIT', 'Scappate!', 'Scappate!!!', 28153),
(150754, 'itIT', 'Ah! Allarme stranieri!', 'Ahhh!!! Allarme stranieri!!!', 28153),
(150753, 'itIT', 'Che ne dite di pigliare nu poco d\'oro spaccando qualche cranio?', '', 28153),
(150752, 'itIT', 'L\'isola sarà inaccessibile fino alla fine delle feste alla fossa di combattimento.', '', 28153),
(150750, 'itIT', 'Ottimo lavoro... ma presentare ad Harlan il freddo acciaio nostro sarà tutta n\'altra storia.', '', 28153),
(150749, 'itIT', 'Se terrete n\'invito, sarà tutto più... facile. Sennò potreste andare là e affrontare tre dei pirati più temuti dei mari, tutti assieme. La decisione è vostra, riccumpà.', '', 28153),
(150748, 'itIT', 'Nemmeno i pesci bevono quanto i Ratti di Sentina! Se starete loro dietro, il Capitano Eudora vi vorrà sicuramente all\'incontro.', '', 28153),
(150747, 'itIT', 'I Filibustieri Dentineri adorano fare a pugni in nu buon combattimento. Se vi farete valere, il Capitano Raoul vi farà sicuramente partecipare all\'incontro.', '', 28153),
(150746, 'itIT', 'Ho sentito che i capitani si stanno riunendo. Se riusciremo a infiltrarci, potremo pigliare molti piccioni con na fava sola.', '', 28153),
(150745, 'itIT', 'Questa guerra non si vincerà da sola. Abbiamo del lavoro da fare!', '', 28153),
(150744, 'itIT', 'Poi affronteremo Harlan Sweete... na volta per tutte.', '', 28153),
(150743, 'itIT', 'Ecco il piano: sbaragliamo gli Sferzamaree, sfondiamo i Ratti di Sentina, sgominiamo i Dentineri e schiacciamo i Marferreo.', '', 28153),
(150742, 'itIT', 'Se ce la farà, sarà a capo di na flotta in grado di minacciare i nostri interessi in mare.', '', 28153),
(150741, 'itIT', 'Harlan sta sfruttando i Marferreo per unire le altre ciurme sotto il vessillo suo.', '', 28153),
(150740, 'itIT', 'Grazie per avermi liberato. Sento il richiamo di Bwonsamdi dall\'interno del tempio. Lasciaci andare.', 'Grazie per avermi liberata. Sento il richiamo di Bwonsamdi dall\'interno del tempio. Lasciaci andare.', 28153),
(150739, 'itIT', 'Credevo di rimanere nu brutto scheletro per sempre. Devo tornare subito al tempio!', 'Credevo di rimanere nu brutto scheletro per sempre. Devo tornare subito al tempio!', 28153),
(150738, 'itIT', 'Riportami al tempio... Bwonsamdi... presto...', 'Riportami al tempio... Bwonsamdi... presto...', 28153),
(150737, 'itIT', 'I sensi che mi rimangono sono offuscati dai rituali loro... aiutami a salire le scale del tempio.', 'I sensi che mi rimangono sono offuscati dai rituali loro... aiutami a salire le scale del tempio.', 28153),
(150736, 'itIT', 'Grazie, cumpà! Mi sto dissolvendo in fretta. Aiutami a tornare al tempio di Bwonsamdi.', 'Grazie, cumpà! Mi sto dissolvendo in fretta. Aiutami a tornare al tempio di Bwonsamdi.', 28153),
(150735, 'itIT', 'Cosa tieni lì con te, riccumpà? Nu bel monile per il vecchio Jani? Avvicinati...', '', 28153),
(150734, 'itIT', 'Sono l\'unico qui che sa la matematica! Per questo mi occupo di controllare le spese e di assicurarmi che tutti rimangano con le mani nelle tasche giuste.', '', 28153),
(150733, 'itIT', 'I Peoni sono la spina dorsale di questa guerra.', '', 28153),
(150732, 'itIT', 'Cerca di nun farti male!', '', 28153),
(150731, 'itIT', 'Statt\' accuort\' ai Troll del Sangue.', '', 28153),
(150730, 'itIT', 'Fai attenzione, ho bisogno che tu rimanga in vita!', '', 28153),
(150729, 'itIT', 'Tempi duri per Zandalar.', '', 28153),
(150728, 'itIT', 'Argh. ODIO i Troll del Sangue.', '', 28153),
(150727, 'itIT', 'Come faremo a risolvere chesta situazione?', '', 28153),
(150726, 'itIT', 'Mmm! L\'Orda ha avuto ciò che si meritava. Porterò quest\'aggeggio al Presidio di Arom per vedere se può essere utile a qualcuno. Ottimo lavoro.', '', 28153),
(150719, 'itIT', 'Sono pronto a difendere Zandalar!', 'Sono pronta a difendere Zandalar!', 28153),
(150718, 'itIT', 'Da questa parte! Le nostre truppe di terra stanno aspettando.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150717, 'itIT', '', 'La foresta grida agonizzante. Riesci a sentirla?', 28153),
(150716, 'itIT', 'Stiamo tornando a casa!', 'Stiamo tornando a casa!', 28153),
(150715, 'itIT', 'A quanto pare nun tenevi bisogno dell\'aiuto mio! Siamo tornati il prima possibile!', '', 28153),
(150714, 'itIT', 'Daryl e io veniamo su queste colline da tutta la vita. Sappiamo sopravvivere qui più a lungo di qualsiasi scagnozzo dell\'Orda.', '', 28153),
(150713, 'itIT', 'Preferisci tornare a Zuldazar e morire o stare qui a farti uccidere dai raptor?', 'Preferisci tornare a Zuldazar e morire o stare qui a farti uccidere dai raptor?', 28153),
(150712, 'itIT', 'Nun intendo andare a Vol\'dun, capito? Vivrò il resto della vita mia in città!', '', 28153),
(150711, 'itIT', '', 'Tartarughe fresche, Emma! Ora dammi la mia parte!', 28153),
(150710, 'itIT', 'Cosa tieni lì con te, riccumpà? Nu bel monile per il vecchio Jani? Avvicinati...', '', 28153),
(150709, 'itIT', '', 'Xul krass qi\' UN skush!', 28153),
(150708, 'itIT', '', 'Skitsh qi\'uthik illith!', 28153),
(150707, 'itIT', '', 'Il sangue trasuda dalle assi del pavimento.', 28153),
(150706, 'itIT', '', 'Perché non venite nel sotterraneo ad ammirare la bellezza della morte?', 28153),
(150705, 'itIT', '', 'Oh cielo, a quanto pare avete massacrato tutta la mia servitù.', 28153),
(150704, 'itIT', '<Vedi l\'immagine di un giovane Troll mentre osserva quello che sembra un funerale. Ha uno sguardo curioso e innocente.>', '<Vedi l\'immagine di un giovane Troll mentre osserva quello che sembra un funerale. Ha uno sguardo curioso e innocente.>', 28153),
(150703, 'itIT', 'State lontani dal cancello! Non è sicuro lassù.', 'State lontani dal cancello! Non è sicuro lassù.', 28153),
(150702, 'itIT', '<Kua\'fon ti ringhia. Torna da Raal o cadrai a terra!>', '<Kua\'fon ti ringhia. Torna da Raal o cadrai a terra!>', 28153),
(150701, 'itIT', '', 'Soffri in agonia!', 28153),
(150700, 'itIT', '', 'Strapperò le vostre anime!', 28153),
(150699, 'itIT', '', 'Usare quel coso mi ha fatto diventare i capelli verdi!', 28153),
(150698, 'itIT', '', 'Le tue urla echeggeranno per l\'eternità!', 28153),
(150697, 'itIT', '', 'Io ho il dominio su ogni cosa!', 28153),
(150696, 'itIT', '', 'Kiro, sono vivi! Non possiamo lasciarli qui...', 28153),
(150695, 'itIT', 'Presto, prendete tutto il possibile. Lasciate il resto agli avvoltoi.', '', 28153),
(150694, 'itIT', 'Morirete tra queste dune...', '', 28153),
(150693, 'itIT', 'Invasori!', '', 28153),
(150692, 'itIT', 'Tu fai la tua parte, Generale, io farò la mia.', '', 28153),
(150691, 'itIT', 'Dobbiamo sveltire le cose. Il Re tiene dei visitatori ficcanaso. Potrebbero essere nu problema.', '', 28153),
(150690, 'itIT', '', 'C\'era una guardia a Tol Dagor che ti assomigliava tantissimo!', 28153),
(150689, 'itIT', '', 'Pensi di potermi far entrare nella Banca di Boralus?', 28153),
(150688, 'itIT', '', 'Non ti preoccupi mai delle radiazioni?', 28153),
(150687, 'itIT', '', 'Sai fare qualcosa di utile, come contraffare monete o aprire serrature?', 28153),
(150686, 'itIT', '', 'La tempesta si è placata e sono di nuovo me stessa. Grazie.', 28153),
(150685, 'itIT', '', 'Le vostre vite non contano nulla, presto sarete dimenticati.', 28153),
(150684, 'itIT', '', 'Profanatori!', 28153),
(150683, 'itIT', '', 'Guaritemi e le disattiverò', 28153),
(150682, 'itIT', '', 'Il maleficio è sparito, ma le difese del tempio sono indebolite!', 28153),
(150681, 'itIT', '', 'Il vostro tormento non avrà fine!', 28153),
(150680, 'itIT', 'Mi divertirò a vedervi bruciare!', '', 28153),
(150679, 'itIT', 'Morite, vermi!', '', 28153),
(150678, 'itIT', 'Fendente elettrico!', '', 28153),
(150677, 'itIT', 'A pezzi!', '', 28153),
(150676, 'itIT', 'Perdente!', '', 28153),
(150675, 'itIT', 'In frantumi come vetro!', '', 28153),
(150674, 'itIT', 'Non è che ho paura o cose del genere, non ho semplicemente voglia!', '', 28153),
(150673, 'itIT', 'Nessuno può opporsi al nostro impero!', '', 28153),
(150672, 'itIT', 'Ovvio che riesco a scalarla. Non sono una femminuccia!', '', 28153),
(150671, 'itIT', 'Non ho niente da dimostrarti!', '', 28153),
(150670, 'itIT', 'Andiamo, Abraham. Ho visto bambini riuscirci.', '', 28153),
(150669, 'itIT', 'Andiamo, non è così alta.', '', 28153),
(150668, 'itIT', 'Scommetto che non riesci a scalarla.', '', 28153),
(150667, 'itIT', 'Non è divertente! Fammi scendere da qui!', '', 28153),
(150666, 'itIT', 'Smettila di blaterare e aiutami a scendere!', '', 28153),
(150665, 'itIT', 'Aiutami a scendere!', '', 28153),
(150664, 'itIT', 'Scappa finché sei in tempo!', 'Scappa finché sei in tempo!', 28153),
(150663, 'itIT', 'Non mi prenderanno!', 'Non mi prenderanno!', 28153),
(150662, 'itIT', 'Possono tenersi la mia parte!', 'Possono tenersi la mia parte!', 28153),
(150661, 'itIT', 'Uccideremo tutti i Marferreo!', 'Uccideremo tutti i Marferreo!', 28153),
(150660, 'itIT', 'Non mi prenderanno!', 'Non mi prenderanno!', 28153),
(150659, 'itIT', 'Io non lavoro coi pirati!', 'Io non lavoro coi pirati!', 28153),
(150658, 'itIT', '', 'Ti schiaccerò la testa!', 28153),
(150657, 'itIT', 'Ti stai divertendo? Ahah!', '', 28153),
(150656, 'itIT', 'C\'è qualche problema, Abraham?', '', 28153),
(150655, 'itIT', 'Ehi, idiota! Ti sei bloccato lassù!', '', 28153),
(150654, 'itIT', 'Sethraliss ha dato la propria vita per salvare il nostro mondo. Se Mythrax tornasse, il suo sacrificio sarebbe stato vano...', '', 28153),
(150653, 'itIT', 'Anche nella morte, l\'essenza di Mythrax è ancora forte, qui. Non oso immaginare cosa accadrebbe al mondo se risorgesse...', '', 28153),
(150652, 'itIT', 'C\'è una presenza oscura qui. Dobbiamo stare in guardia...', '', 28153),
(150651, 'itIT', '', 'Il viaggio loro verso la grandezza sta per cominciare.', 28153),
(150650, 'itIT', '', 'Ah, è giunta l\'ora di mettere alla prova chesti piccoletti, in modo che possano compiere il destino loro. Falli tornare alla Sala delle Caste.', 28153),
(150649, 'itIT', 'Bene! Con queste prede faremo frecce per i cacciatori e imbottiture per le armature.', '', 28153),
(150648, 'itIT', 'È difficile aprire una linea di rifornimento nella palude. Per mantenere i nostri sforzi bellici, abbiamo bisogno che tu vada in cerca di materiali tra la fauna locale.', '', 28153),
(150647, 'itIT', 'Ah, questo va benissimo! Spero che quegli animaletti non ti abbiano dato troppo fastidio. Eh eh eh!', '', 28153),
(150646, 'itIT', 'Un branco di Sputainchiostro? Gentile da parte loro venire qui proprio quando avevo finito il mio! Sfrutta il potere di questa pergamena per estrarre il loro prezioso inchiostro.', '', 28153),
(150645, 'itIT', '', 'Questa tecnologia sarà incredibilmente utile per le nostre forze. Ben fatto!', 28153),
(150644, 'itIT', '', 'Meccatork ha migliorato la sua tecnologia D.R.O.N.E. e necessita di una valutazione sul campo delle sue capacità. Abbiamo sentito che c\'è un gran numero di Troll nascosti qui vicino. Usala per eliminarli!', 28153),
(150643, 'itIT', '<Sali in groppa.>', '<Sali in groppa.>', 28153),
(150642, 'itIT', '<Kua\'fon gira la testa per esaminarti. Emette un chiaro gracchio come per salutarti.>\n\nReee!', '', 28153),
(150641, 'itIT', '', 'Sudici piccoli mostriciattoli.', 28153),
(150640, 'itIT', '', 'I ranishu hanno più di uno stomaco, così possono continuare a scavare quando uno è pieno.', 28153),
(150639, 'itIT', 'Gli ci vorrà del tempo per tornare al nido, nun essendo capace di volare. Sta sicuramente bene.$b$bTorna più tardi e dovresti trovarlo.', '', 28153),
(150638, 'itIT', 'Be\', tutto a posto. Prego, comunque.$b$bHo notato che teneva n\'aspetto triste. Forse potresti accompagnarlo a volare ancora! Gli farebbe bene nu po\' di esercizio.', '', 28153),
(150637, 'itIT', 'Che succede all\'aquilone?', 'Che succede all\'aquilone?', 28153),
(150636, 'itIT', '', 'Dobbiamo raggiungerla. Andiamo!', 28153),
(150635, 'itIT', '', 'Dobbiamo sbrigarci e trovare Rakera!', 28153),
(150634, 'itIT', 'Già fatto, Kenzou.', '', 28153),
(150633, 'itIT', 'Grazie, $p. Non ce l\'avremmo mai fatta senza di te. Tieniti la tua parte.', '', 28153),
(150632, 'itIT', 'E ora, Tacha e Omi... ripuliremo questo posto da ogni cosa di valore.', '', 28153),
(150631, 'itIT', 'Basta! Avrete l\'onore di morire per mano mia!', '', 28153),
(150630, 'itIT', 'Persino la morte nun può rompere i legami nostri, piccoli miei. Va\', T\'zala... BANCHETTA!', '', 28153),
(150629, 'itIT', 'Nessuno può resistere alla mia spada!', '', 28153),
(150628, 'itIT', 'È l\'ora del sangue!', '', 28153),
(150627, 'itIT', 'Ti strapperò la carne dalle ossa!', '', 28153),
(150626, 'itIT', 'Può essere? Sì... Finalmente!', '', 28153),
(150625, 'itIT', 'La leggenda mia supererà la tua!', '', 28153),
(150624, 'itIT', 'Nun avresti potuto pigliare la corona mia!', '', 28153),
(150623, 'itIT', 'Chesto è il motivo per cui io sono re... e voi nun siete nulla.', '', 28153),
(150622, 'itIT', 'La pagherete per aver dissacrato il tempio mio!', '', 28153),
(150621, 'itIT', 'La stagione della caccia è iniziata!', '', 28153),
(150620, 'itIT', 'Nun esiste antidoto per chesto veleno!', '', 28153),
(150619, 'itIT', 'Gli elementi rispondono al richiamo mio!', '', 28153),
(150618, 'itIT', 'Ti mostrerò il vero significato di maleficio!', '', 28153),
(150617, 'itIT', '', 'Arriva il dolore!', 28153),
(150616, 'itIT', '', 'Mo\' schiatti!', 28153),
(150615, 'itIT', '', 'È ora di pigliarsi n\'ascia!', 28153),
(150614, 'itIT', '', 'Farai meglio a camminare, se ci tieni alla tua salute.', 28153),
(150613, 'itIT', '', 'Qualcuno sta per perdere la capa!', 28153),
(150612, 'itIT', 'Ti prego... seppelliscimi lontano da chesti... imbecilli...', '', 28153),
(150611, 'itIT', '', 'La capa mia... sarà... nu sontuoso trofeo...', 28153),
(150610, 'itIT', '', 'Argh... la furia mia... è... immortale...', 28153),
(150609, 'itIT', 'Shhh... sto cercando di trovare delle farfalle!', '', 28153),
(150608, 'itIT', '', 'Ohhh! Le cape vostre saranno ottime decorazioni.', 28153),
(150607, 'itIT', '', 'Ho schiacciato insetti più grossi di voi!', 28153),
(150606, 'itIT', 'Che il vudù ti colga!', '', 28153),
(150605, 'itIT', '', 'Niente sopravvive alla furia mia!', 28153),
(150603, 'itIT', 'Mi prendo il tesoro!', 'Mi prendo il tesoro!', 28153),
(150602, 'itIT', 'Ferma le voci!', 'Ferma le voci!', 28153),
(150601, 'itIT', 'Il tesoro è mio!', 'Il tesoro è mio!', 28153),
(150599, 'itIT', '', 'Ah! Ti ho tolto nu peso dalle spalle!', 28153),
(150598, 'itIT', 'Ah! Nun avreste mai dovuto risvegliare il potere mio.', '', 28153),
(150597, 'itIT', '', 'Eheh! Sangue e ossa!', 28153),
(150596, 'itIT', '', 'Nun c\'è scampo per te!', 28153),
(150595, 'itIT', 'È arrivato il Taumaturgo!', '', 28153),
(150594, 'itIT', 'Prepara il tuo corpo!', '', 28153),
(150593, 'itIT', 'Numerose uova iniziano a schiudersi a nord!', 'Numerose uova iniziano a schiudersi a nord!', 28153),
(150592, 'itIT', 'Avete disturbato i morti!', '', 28153),
(150591, 'itIT', 'Delle uova impolverate iniziano a schiudersi a est!', 'Delle uova impolverate iniziano a schiudersi a est!', 28153),
(150590, 'itIT', 'Delle uova coperte di veleno iniziano a schiudersi a ovest!', 'Delle uova coperte di veleno iniziano a schiudersi a ovest!', 28153),
(150589, 'itIT', 'Prevenire l\'infezione! Rimuovere il cervello!', '', 28153),
(150588, 'itIT', 'La maledizione del sangue deve essere epurata!', '', 28153),
(150587, 'itIT', 'I morti... devono essere... conservati...', '', 28153),
(150586, 'itIT', '', 'Ho detto a Kaja di continuare a muoversi. Dobbiamo fermare Jakra\'zet prima che sia troppo tardi.', 28153),
(150585, 'itIT', 'Ti libero dalla pestilenza!', '', 28153),
(150584, 'itIT', 'Torna alla polvere!', '', 28153),
(150583, 'itIT', 'Ora riposate.', '', 28153),
(150582, 'itIT', 'Il vostro sangue è maledetto!', '', 28153),
(150581, 'itIT', 'I vostri corpi saranno infettati!', '', 28153),
(150580, 'itIT', '', 'Uh... la capa mia... Cosa sono cheste cose?', 28153),
(150574, 'itIT', 'Ah! Lo vedremo, creatura indegna!', '', 28153),
(150573, 'itIT', 'La tempesta si risveglia.', 'La tempesta si risveglia.', 28153),
(150572, 'itIT', 'Sparisci!', 'Sparisci!', 28153),
(150571, 'itIT', 'Certo, vediamo cos\'hai, Vali.', 'Certo, vediamo cos\'hai, Vali.', 28153),
(150570, 'itIT', 'Perché ti servono delle monete?', 'Perché ti servono delle monete?', 28153),
(150569, 'itIT', 'Le facce di zanne che vengono qui hanno sempre monete da offrire.$B$BVali crede che siano importanti per il commercio fuori da Vol\'dun!$B$BSe Vali vuole andarsene da Vol\'dun, Vali ha bisogno di monete.', '', 28153),
(150568, 'itIT', 'Vali ha la merce giusta per le tue monete!', '', 28153),
(150567, 'itIT', 'Ciao! Sì, dico a te! Sembra proprio che tu abbia bisogno di acqua!', '', 28153),
(150566, 'itIT', '', 'Grazie, Mace. Quando tutto sarà finito, dovremo discutere di una tua promozione come mia diplomatica.', 28153),
(150565, 'itIT', '', 'Io mi fido di te. Se qualcuno dovesse darti problemi, un bel colpo in testa dovrebbe risolvere la cosa.', 28153),
(150564, 'itIT', 'Dovrei tornare all\'altare. Quest\'essenza merita di essere esaminata.', 'Dovrei tornare all\'altare. Quest\'essenza merita di essere esaminata.', 28153),
(150563, 'itIT', 'Tieni qualcosa da riparare? Li strumenti sono vecchi, ma so ancora usarli bene.', 'Tieni qualcosa da riparare? Li strumenti sono vecchi, ma so ancora usarli bene.', 28153),
(150562, 'itIT', 'Desidero scegliere Akunda come mio Loa.', 'Desidero scegliere Akunda come mio Loa.', 28153),
(150561, 'itIT', '<Il santuario fu costruito come tributo ad Akunda, il Loa delle Tempeste.>', '<Il santuario fu costruito come tributo ad Akunda, il Loa delle Tempeste.>', 28153),
(150560, 'itIT', '', 'Che insolenza! Aspetta che ti senta tuo padre. Nel frattempo, lascerò che i miei servi si occupino di voi.', 28153),
(150559, 'itIT', '', 'Non osare chiamarmi figlia, strega!', 28153),
(150558, 'itIT', '', 'Bentornata a casa, figlia mia. Vedo che hai degli ospiti.', 28153),
(150557, 'itIT', 'AAAHHH!', 'AAAHHH!', 28153),
(150556, 'itIT', 'Esamina la tessitura più da vicino.', 'Esamina la tessitura più da vicino.', 28153),
(150555, 'itIT', 'Questo telaio e le sue creazioni sembrano infusi della magia della congrega.', 'Questo telaio e le sue creazioni sembrano infusi della magia della congrega.', 28153),
(150554, 'itIT', 'Prendi la bottiglia.', 'Prendi la bottiglia.', 28153),
(150553, 'itIT', 'Anche se questa bottiglia è vuota da molto tempo, potrebbe ancora essere utile a uno chef di esperienza.', 'Anche se questa bottiglia è vuota da molto tempo, potrebbe ancora essere utile a uno chef di esperienza.', 28153),
(150552, 'itIT', 'Ahhh! Che succede? Aiuto!', '', 28153),
(150551, 'itIT', 'Distruggi il baccello acerbo.', 'Distruggi il baccello acerbo.', 28153),
(150550, 'itIT', 'Un baccello malato giace dormiente. Pare che qualcuno lo stia coltivando per scopi nefasti.', 'Un baccello malato giace dormiente. Pare che qualcuno lo stia coltivando per scopi nefasti.', 28153),
(150549, 'itIT', 'Prendi la mappa.', 'Prendi la mappa.', 28153),
(150548, 'itIT', '<Una mappa molto rovinata che indica i luoghi locali di caccia e la posizione dei mercanti di pellame.>', '<Una mappa molto rovinata che indica i luoghi locali di caccia e la posizione dei mercanti di pellame.>', 28153),
(150547, 'itIT', 'Vuoi davvero farlo?', 'Vuoi davvero farlo?', 28153),
(150546, 'itIT', 'Sei... Sei $gSALTATO:SALTATA; nel calderone! Che razza di demonio ha preso possesso di te per fare una cosa simile!? Dobbiamo rifare tutto da capo!', '', 28153),
(150545, 'itIT', '', 'La via è libera! Difendete i cancelli prima che arrivi la prossima ondata.', 28153),
(150544, 'itIT', '', 'Maestro, eccoti un valido aiuto per qualunque cosa di cui tu abbia bisogno. Io andrò ad aiutare il Sindaco Royston.', 28153),
(150543, 'itIT', 'Non mi avrete mai vivo!', 'Non mi avrete mai viva!', 28153),
(150542, 'itIT', '', 'Ne sono molto felice, Maestro Ashton.', 28153),
(150541, 'itIT', 'Assisterò te e Dama Lucille in questo compito con grandissimo piacere.', '', 28153),
(150540, 'itIT', 'Affascinante! Una formula notevole! Molto infiammabile!', '', 28153),
(150539, 'itIT', 'Dama Lucille crede che possa essere utile? D\'accordo, vediamola!', '', 28153),
(150538, 'itIT', '', 'Ha trovato una formula alchemica che fu molto efficace in passato. Vorrebbe che provassi a replicarla.', 28153),
(150537, 'itIT', '', 'Dama Lucille ha riformato l\'Ordine delle Braci. Utilizzando gli antichi testi come guida, combatteremo quelle streghe come un tempo abbiamo fatto con i Drust.', 28153),
(150536, 'itIT', '', 'Krax il\' oni OGOG!', 28153),
(150535, 'itIT', '', 'Ul tala kraza.', 28153),
(150534, 'itIT', '', 'Bwaxa za\' raga xil.', 28153),
(150533, 'itIT', '', 'Kryl!', 28153),
(150532, 'itIT', 'Oh, ma... perché proprio io?', '', 28153),
(150531, 'itIT', '', 'Bwixki amala zal qulllll...', 28153),
(150530, 'itIT', '', 'Aglathrax hig\' thrixa.', 28153),
(150529, 'itIT', '', 'Maestro Ashton, Dama Lucille Crestabianca ci ha mandati a cercarti.', 28153),
(150528, 'itIT', '', 'ULL vera skish!!!', 28153),
(150527, 'itIT', 'Quali possibilità avevate contro il mio potere?', '', 28153),
(150526, 'itIT', 'Epurato!', '', 28153),
(150525, 'itIT', 'Purificato!', '', 28153),
(150524, 'itIT', 'Le maree si alzano... contro di me...', '', 28153),
(150523, 'itIT', 'Non vedo l\'ora di annegarvi con le mie mani!', '', 28153),
(150522, 'itIT', 'Non tollererò più la vostra insolenza!', '', 28153),
(150521, 'itIT', 'Invoco le acque impetuose! Scatenatevi e spazzate via questi intrusi!', '', 28153),
(150520, 'itIT', 'Come osate profanare questo luogo sacro con la vostra presenza!', '', 28153),
(150519, 'itIT', 'Goditi la tua tomba d\'acqua!', '', 28153),
(150518, 'itIT', '[SCENE SHOWS JAKRA\'ZET AND SETHRAK EMPEROR KORTHEK SURROUNDED BY SETHRAK, CONSPIRING ABOUT BREAKING INTO THE PYRAMID. KORTHEK SHOOTS YOU OUT OF THE SKY.]', '', 28153),
(150517, 'itIT', 'Magni, cosa vuole da me Azeroth?', 'Magni, cosa vuole da me Azeroth?', 28153),
(150516, 'itIT', 'Dovevi rimanere sulla terraferma!', '', 28153),
(150515, 'itIT', 'Riportatemi... nel mare...', '', 28153),
(150514, 'itIT', 'Vi getterò negli abissi per questo!', '', 28153),
(150513, 'itIT', 'NO!', '', 28153),
(150512, 'itIT', 'Le maree vi coglieranno!', '', 28153),
(150511, 'itIT', 'Nessun potere potrà spezzare il nostro legame.', '', 28153),
(150510, 'itIT', '', 'Insieme, amore mio, siamo una forza della natura.', 28153),
(150509, 'itIT', '', 'La tempesta ti purifica!', 28153),
(150508, 'itIT', '', 'La tua vita ha preso il largo!', 28153),
(150507, 'itIT', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t %s ha ricevuto un\'|cFFFF0000|Hcurrency:1559|hEssenza delle Tempeste!|h|r!', '|TInterface\\Icons\\INV_MISC_LESSERESSENCE:20|t %s ha ricevuto un\'|cFFFF0000|Hcurrency:1559|hEssenza delle Tempeste!|h|r!', 28153),
(150506, 'itIT', '', 'Le nubi... si spezzano...', 28153),
(150505, 'itIT', '', 'I venti sferzeranno la vostra carne!', 28153),
(150504, 'itIT', '', 'Amore mio! No!', 28153),
(150503, 'itIT', 'Se c\'è qualcuno che può essere sopravvissuto, è lui. Darò un\'occhiata ai giardini del laboratorio.', '', 28153),
(150502, 'itIT', '', 'Nessuno può opporsi alla tempesta!', 28153),
(150501, 'itIT', '', 'L\'attacco a Collefalco è stato feroce. Spero che il Maestro Ashton sia ancora vivo.', 28153),
(150500, 'itIT', '', 'Priscilla sta fuggendo a cavallo! Prendi uno dei nostri destrieri e seguila!', 28153),
(150499, 'itIT', 'Maestro Ashton, ci serve il tuo aiuto!', 'Maestro Ashton, ci serve il tuo aiuto!', 28153),
(150498, 'itIT', 'Grazie. Ora me ne vado.', 'Grazie. Ora me ne vado.', 28153),
(150497, 'itIT', 'Non lo dimenticherò mai! Ora me ne vado da qui!', 'Non lo dimenticherò mai! Ora me ne vado da qui!', 28153),
(150496, 'itIT', 'Temevo di rimanere qui per sempre... accetta questo come mio ringraziamento!', 'Temevo di rimanere qui per sempre... accetta questo come mio ringraziamento!', 28153),
(150495, 'itIT', 'Grazie per avermi liberato, forse questo ti aiuterà.', 'Grazie per avermi liberata, forse questo ti aiuterà.', 28153),
(150494, 'itIT', 'Grazie al cielo mi hai salvato! Fammi sapere cosa posso fare per aiutare.', 'Grazie al cielo mi hai salvata! Fammi sapere cosa posso fare per aiutare.', 28153),
(150493, 'itIT', 'Non lasciarmi qui!', 'Non lasciarmi qui!', 28153),
(150492, 'itIT', 'Fammi uscire!', 'Fammi uscire!', 28153),
(150491, 'itIT', '', 'Vi prego, aiutateci! Se Gorak Tul non verrà fermato, diffonderà il male su tutta Azeroth.', 28153),
(150490, 'itIT', 'Aiuto!', 'Aiuto!', 28153),
(150489, 'itIT', 'Presto, trova un modo per aprire questa cella!', 'Presto, trova un modo per aprire questa cella!', 28153),
(150488, 'itIT', 'Liberami!', 'Liberami!', 28153),
(150487, 'itIT', 'Ti prego, aiutami!', 'Ti prego, aiutami!', 28153),
(150486, 'itIT', 'Nu Sauride? Che ci fa accà?', '', 28153),
(150485, 'itIT', '', 'Non importa chi sono. Abbiamo bisogno del loro aiuto. Non possiamo permettere a Gorak Tul di mettere piede nel nostro mondo!', 28153),
(150484, 'itIT', '', 'Calmati, Maestro Ashton! Siamo amici!', 28153),
(150483, 'itIT', 'Siamo arrivati troppo tardi! Un attimo, voi chi siete?', '', 28153),
(150482, 'itIT', 'Be\', avete comunque un\'aria pericolosa. L\'attacco è finito, allora?', '', 28153),
(150480, 'itIT', 'Indietro! Ho Alchimia e non ho paura di usarla!', '', 28153),
(150479, 'itIT', 'Eliminando Dama Crestabianca, avete aperto la via per il vostro mondo.', '', 28153),
(150478, 'itIT', 'Mortali, mancate di lungimiranza. La morte non può essere fermata.', '', 28153),
(150477, 'itIT', '', 'Vi siete approfittati fin troppo della nostra ospitalità. Molto bene. Non lascerete mai queste mura!', 28153),
(150476, 'itIT', '', 'Continuate a interferire nei miei affari e le vostre morti saranno lente e dolorose.', 28153),
(150475, 'itIT', '', 'A giudicare dalle vostre facce inebetite, direi che il concetto di una dimora non fatta di escrementi vi è particolarmente estraneo.', 28153),
(150474, 'itIT', '', 'A ben pensarci... è meglio se non rispondete.', 28153),
(150473, 'itIT', '', 'Nel paese da dove venite è considerata cortesia uccidere i servi di chi vi ospita?', 28153),
(150472, 'itIT', 'Sono pronto. Raggiungiamo le altre.', 'Sono pronto. Raggiungiamo le altre.', 28153),
(150471, 'itIT', 'Non abbiamo tempo da perdere. I tuoi amici sono già all\'interno di Atul\'aman...', '', 28153),
(150470, 'itIT', '<Kua\'fon strilla d\'indignazione e corre via.>', '', 28153),
(150469, 'itIT', '', 'Piccolino! Se vuoi tornare al nido, farai meglio a iniziare a correre.', 28153),
(150468, 'itIT', '', 'Per ora gli daremo una lezione più pratica.', 28153),
(150467, 'itIT', '', 'Il tuo piccolino non ha fiducia nelle sue ali. Devi continuare a mostrargli la gioia di volare.', 28153),
(150466, 'itIT', '', 'Perché stai usando ancora le zampe?!?', 28153),
(150465, 'itIT', '', 'Siete vivi entrambi. Bene. Proprio come dicevo...', 28153),
(150464, 'itIT', '', 'Grazie, eroi. Avete annientato la congrega di Crestabianca e ci avete liberati da Gorak Tul. Siamo in debito con voi.', 28153),
(150463, 'itIT', '', 'Visto? Non c\'è nulla che un braccio forte e una lama affilata non possano risolvere.', 28153),
(150462, 'itIT', 'Ce l\'abbiamo fatta! Gorak Tul è stato esiliato.', '', 28153),
(150461, 'itIT', '<Per timore dell\'impatto imminente, Kua\'fon strilla chiedendo aiuto!>', '<Per timore dell\'impatto imminente, Kua\'fon strilla chiedendo aiuto!>', 28153),
(150460, 'itIT', 'Venite, mortali. La morte vi attende.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150459, 'itIT', '', 'Ondafiera e io li terremo impegnati. Voi mettete fine a questa storia!', 28153),
(150458, 'itIT', '', 'Tutti gli orrori del maniero si fanno strada verso di noi!', 28153),
(150457, 'itIT', '', 'Non possiamo permettere a Gorak Tul di mettere piede nel nostro mondo!', 28153),
(150456, 'itIT', '<L\'aquilone inizia a vibrare violentemente. Segui le correnti più tranquille!>', '<L\'aquilone inizia a vibrare violentemente. Segui le correnti più tranquille!>', 28153),
(150455, 'itIT', '|TInterface\\ICONS\\INV_POTION_24:20|t Usa |cFFFF0404|Hspell:266198|h[Fuoco Alchemico]|h|r per distruggere i corpi degli Schiavisti Sfiorati dalla Morte!', '', 28153),
(150454, 'itIT', 'Il vostro incubo è appena cominciato.', '', 28153),
(150453, 'itIT', 'Dama Crestabianca era una semplice latrice del mio potere. Eliminandola, avete aperto la via per il vostro mondo.', '', 28153),
(150452, 'itIT', 'Assorbimento', 'Assorbimento', 28153),
(150451, 'itIT', 'Stupida ragazzina. Manchi di lungimiranza. La morte è una forza da cui non si può sfuggire.', '', 28153),
(150450, 'itIT', '', 'Finalmente, l\'incubo è finito.', 28153),
(150448, 'itIT', 'Va\'. Piglia il cappello suo e ottieni il favore di Jani, ma fa\' attenzione a nun farti vedere dai predatori...', '', 28153),
(150446, 'itIT', '', 'Hai ragione. Eppure, come farò a riconquistare la fiducia della gente quando saprà degli orrori di cui si è macchiata la mia famiglia?', 28153),
(150445, 'itIT', '', 'Ciò che conta ora è porre fine alla sua malvagità.', 28153),
(150444, 'itIT', '', 'Mia madre aveva un lato crudele, ma non credevo fosse capace di tanto.', 28153),
(150443, 'itIT', 'Andate avanti. Trovate Dama Crestabianca e pareggiate i conti.', '', 28153),
(150442, 'itIT', 'Eheh! Carne morta.', '', 28153),
(150441, 'itIT', 'Assicuratevi che Dama Crestabianca paghi caro per ciò che ha fatto.', '', 28153),
(150440, 'itIT', 'Avete reso un grande servizio a queste anime liberandole.', '', 28153),
(150439, 'itIT', 'Continua la ricerca di Dama Crestabianca. Io penserò a liberare le stanze.', '', 28153),
(150438, 'itIT', 'Dormirei più tranquillo se sapessi che quelle creature non sono più un pericolo.', '', 28153),
(150437, 'itIT', 'Esamineremo la zona mentre vi occupate dei suoi servi. Buona caccia.', '', 28153),
(150436, 'itIT', '', 'Eroi, ci serve la vostra forza. Dobbiamo porre fine a questa malvagità.', 28153),
(150435, 'itIT', 'Scappare non mi sembra una buona idea. Abbiamo un piano migliore, vero?', '', 28153),
(150434, 'itIT', 'Mace!', '', 28153),
(150433, 'itIT', '', 'Torna indietro e affrontami!', 28153),
(150432, 'itIT', '', 'Ai tuoi ordini, signora.', 28153),
(150431, 'itIT', '', 'Signore, mettete i nostri visitatori a proprio agio.', 28153),
(150430, 'itIT', '', 'Pare che abbiamo degli ospiti inattesi. Non importa, troveremo certamente un modo per accomodarli.', 28153),
(150429, 'itIT', 'Sei $gpieno:piena; di sorprese.', 'Sei $gpieno:piena; di sorprese.', 28153),
(150428, 'itIT', 'Ottimo lavoro, $R!', 'Ottimo lavoro, $p!', 28153),
(150427, 'itIT', 'Sono libero!', 'Sono libera!', 28153),
(150426, 'itIT', 'Te ne devo una!', 'Te ne devo una!', 28153),
(150425, 'itIT', 'Molte grazie!', 'Molte grazie!', 28153),
(150421, 'itIT', 'Ti darò una parte del mio potere, con cui potrai spazzare via ogni Senzafede che oserà sfidarti.', '', 28153),
(150420, 'itIT', 'Hai così paura, amico mio, da nasconderti mentre la tua gente soffre? Affrontami, Korthek!', '', 28153),
(150419, 'itIT', '$p, dovresti lavorare con me. Lo troverò.', '$p, dovresti lavorare con me. Lo troverò.', 28153),
(150418, 'itIT', '', 'È solo un piccolo inconveniente! Quando le mie forze si saranno radunate, questo miserabile villaggio sarà nostro!', 28153),
(150417, 'itIT', 'Il tradimento di Zul è ben più profondo di quanto pensassi. Con la ribellione sua, ha praticamente distrutto ogni resistenza.\n\nChelli ancora leali a me stanno schiattando sul campo di battaglia a causa di sciami infiniti di Troll del Sangue.\n\nAvrei dovuto ascoltare Talanji.', '', 28153),
(150416, 'itIT', 'Conosco un tizio che sa dove si trova.', 'Conosco un tizio che sa dove si trova.', 28153),
(150415, 'itIT', 'Sai dov\'è il tesoro?', 'Sai dov\'è il tesoro?', 28153),
(150414, 'itIT', 'Trovami il tesoro e faremo a metà.', 'Trovami il tesoro e faremo a metà.', 28153),
(150413, 'itIT', 'Ho sentito che i Marferreo l\'hanno già trovato.', 'Ho sentito che i Marferreo l\'hanno già trovato.', 28153),
(150412, 'itIT', 'Ehi, aiutami a trovare il tesoro!', 'Ehi, aiutami a trovare il tesoro!', 28153),
(150411, 'itIT', 'Questo tizio ha un amico che ha sentito uno dei Marferreo dire di sapere dove si trova.', 'Questo tizio ha un amico che ha sentito uno dei Marferreo dire di sapere dove si trova.', 28153),
(150410, 'itIT', 'Forse tutte queste storie sull\'oro sono solo una menzogna.', 'Forse tutte queste storie sull\'oro sono solo una menzogna.', 28153),
(150409, 'itIT', 'Dobbiamo trovare questo tesoro prima che i Marferreo assaltino questo posto.', 'Dobbiamo trovare questo tesoro prima che i Marferreo assaltino questo posto.', 28153),
(150408, 'itIT', '', 'Magari qualcuno si è mangiato il gatto.', 28153),
(150407, 'itIT', 'Torna a casa, fiero Rak\'jani, e di\' a tuo padre chi ti ha donato la libertà.', '', 28153),
(150406, 'itIT', '', 'Radunerò la ciurma e dirò alli altri di prendere le scialuppe. Buon divertimento, $n!', 28153),
(150405, 'itIT', 'Svelti! Dategli fuoco prima che il Re dei Drust li riporti in vita!', '', 28153),
(150404, 'itIT', 'Presto! Brucialo!', '', 28153),
(150403, 'itIT', 'Ci servirebbe una mano qui!', '', 28153),
(150402, 'itIT', 'Ci stanno soverchiando!', '', 28153),
(150401, 'itIT', 'Soccombi all\'oscurità!', '', 28153),
(150400, 'itIT', 'Sorgete!', '', 28153),
(150399, 'itIT', 'Nessuno può opporsi a me!', '', 28153),
(150398, 'itIT', 'Non valevi nulla!', '', 28153),
(150397, 'itIT', 'Tutta la vita finisce.', '', 28153),
(150396, 'itIT', 'La morte... non può trattenermi...', '', 28153),
(150395, 'itIT', 'La morte consuma tutti!', '', 28153),
(150394, 'itIT', 'Nessuno sfuggirà alla mia vendetta!', '', 28153),
(150393, 'itIT', 'Tutto il personale in cucina!', '', 28153),
(150392, 'itIT', 'Una bella frollatura!', '', 28153),
(150391, 'itIT', 'Il menù di oggi sarà MOLTO gustoso...', '', 28153),
(150390, 'itIT', 'Che... deliziosa... agonia...', '', 28153),
(150388, 'itIT', '', 'I Vulpera ti proteggono, $p.\n\nManda qualsiasi Senzafede dovesse crearti problemi da me e sarò felice di occuparmene.', 28153),
(150387, 'itIT', 'Ahhh, è succulento!', '', 28153),
(150386, 'itIT', 'Ahhh, carne fresca!', '', 28153),
(150385, 'itIT', 'Ho l\'acquolina!', '', 28153),
(150384, 'itIT', 'Rimanete pure per cena!', '', 28153),
(150383, 'itIT', 'Quota tripla a chiunque troverà il tesoro!', '', 28153),
(150382, 'itIT', 'Volete diventare ricchi? Trovatemi quel tesoro!', '', 28153),
(150381, 'itIT', 'Moxie, fai lavorare quegli scansafatiche!', '', 28153),
(150380, 'itIT', 'Dannati Marferreo, non avrete mai il tesoro!', '', 28153),
(150379, 'itIT', 'Uccidi quello con il cappello da pirata! Sì, proprio quello!', '', 28153),
(150378, 'itIT', 'Controllate sotto le rocce! Controllate dappertutto!', '', 28153),
(150377, 'itIT', 'Spazza via quei Marferreo!', '', 28153),
(150376, 'itIT', '<Muggisce>', '', 28153),
(150375, 'itIT', '', '<Muggisce>', 28153),
(150374, 'itIT', '', 'Mi dispiace...', 28153),
(150373, 'itIT', '', 'Sono la Matrona delle Analisi, Determinata Ricercatrice Eterna. Nome in codice: M.A.D.R.E.', 28153),
(150372, 'itIT', '', 'Qualsiasi cosa stavate facendo, finisce oggi!', 28153),
(150371, 'itIT', '', 'Dove sono i soldi?', 28153),
(150370, 'itIT', '', 'So che state nascondendo qualcosa!', 28153),
(150369, 'itIT', '', 'Cadrete tutti a pezzi nei cantieri.', 28153),
(150368, 'itIT', '', 'Non siete duri quanto mi aspettavo.', 28153),
(150367, 'itIT', '', 'Indosserete queste catene fino ai cantieri!', 28153),
(150366, 'itIT', 'Salve, riccumpà. Hai portato qualcosa di solido e duro al Santuario delli Sciacalli?', '', 28153),
(150365, 'itIT', 'Che se lo prendano! I soldi non servono a nulla da morti!', 'Che se lo prendano! I soldi non servono a nulla da morti!', 28153),
(150364, 'itIT', 'Non abbandonerò il tesoro. È qui!', 'Non abbandonerò il tesoro. È qui!', 28153),
(150363, 'itIT', 'I Marferreo stanno arrivando! Meglio andarsene da qui!', 'I Marferreo stanno arrivando! Meglio andarsene da qui!', 28153),
(150362, 'itIT', 'Salve, riccumpà. Hai portato qualcosa di brillante e liscio al Santuario delli Sciacalli?', '', 28153),
(150361, 'itIT', 'Ah, siamo arrivati e il cielo è limpido. Na giornata perfetta per andare in esplorazione.', '', 28153),
(150360, 'itIT', 'Oh, chesto nun è nu terremoto normale! L\'Azerite sta fuoriuscendo accà vicino.', '', 28153),
(150359, 'itIT', 'Il dispositivo è attivo. Ora dovreste riuscire a vedere tutta l\'Azerite.', '', 28153),
(150358, 'itIT', 'Stateve accuort\'! Na nave di Kul Tirani ha appena attraccato.', '', 28153),
(150357, 'itIT', 'Non vale, l\'ultimo era mio!', 'Non vale, l\'ultimo era mio!', 28153),
(150356, 'itIT', 'Ehi... quello è mio!', 'Ehi... quello è mio!', 28153),
(150355, 'itIT', 'Frugate nelle sue tasche!', 'Frugate nelle sue tasche!', 28153),
(150354, 'itIT', 'Prendi le chiavi!', 'Prendi le chiavi!', 28153),
(150353, 'itIT', '$gStolto:Stolta;! Razgaji ti ha $gmandato:mandata; a morire!', '', 28153),
(150352, 'itIT', '', 'Stavo pensando la stessa cosa. Campione, saresti così gentile da provare la nostra teoria?', 28153),
(150351, 'itIT', 'Interessante. I Fuochi Fatui rispondono solo al richiamo di Malfurion. Ma se altre parti della foresta chiedessero aiuto?', '', 28153),
(150350, 'itIT', '', 'Non possiamo eliminare i Fuochi Fatui... non tanti da cambiare qualcosa, ma forse possiamo disperderli.', 28153),
(150349, 'itIT', 'Nessuno ruba a Tongo senza pagarne le conseguenze.', '', 28153),
(150348, 'itIT', '', 'La squadra d\'esplorazione che ho guidato da Malfurion aveva sottovalutato i Fuochi Fatui. Hanno pagato caro per questo.', 28153),
(150347, 'itIT', 'Un muro di Fuochi Fatui? Niente che le nostre Guardaboschi Oscure e qualche Demolitore non possano superare, mia signora.', '', 28153),
(150346, 'itIT', 'Non riuscirai... a spezzarmi.', '', 28153),
(150345, 'itIT', 'Un altro Pterrordattilo troppo debole per i Senzafede!', '', 28153),
(150344, 'itIT', '', 'È bello vederti! Vieni, riposati un po\'.', 28153),
(150343, 'itIT', '', 'Se ti serve qualcosa, fammelo sapere!', 28153),
(150342, 'itIT', '', 'Ti do il benvenuto nella mia locanda! Vieni, prendi da bere.', 28153),
(150341, 'itIT', '', 'Va tutto bene, $gpiccolino:piccolina;? Entra, fai come se fossi a casa tua.', 28153),
(150340, 'itIT', '', 'Hai la faccia di $guno:una; a cui farebbe comodo un po\' di riposo. Siediti, mangia qualche verme!', 28153),
(150339, 'itIT', 'Salve, riccumpà. Hai portato qualcosa di statico e affilato al Santuario delli Sciacalli?', '', 28153),
(150338, 'itIT', 'L\'Azerite è tutta mia!', 'L\'Azerite è tutta mia!', 28153),
(150337, 'itIT', '', 'Fammi sapere se fa male...', 28153),
(150336, 'itIT', '', 'Accidenti! Certo che sanguini davvero tanto!', 28153),
(150335, 'itIT', '', 'Capitano! L\'aggeggio ha localizzato dei nemici nelle vicinanze. È ora di sfoderare i coltelli!', 28153),
(150334, 'itIT', '', 'Spegni i fuochi... Pensa alle esplosioni... Pfff! Schiavisti!', 28153),
(150333, 'itIT', '', 'Può funzionare ED esplodere. Le due cose non sono incompatibili, sai?', 28153),
(150332, 'itIT', '', 'Questo... non farà piacere... al capitano...', 28153),
(150331, 'itIT', '', 'Adesso ti accoltello!', 28153),
(150330, 'itIT', '', 'Sorpresa!', 28153),
(150329, 'itIT', '', 'È ora di accoltellare!', 28153),
(150328, 'itIT', 'Ehi, inizia a fare male!', '', 28153),
(150327, 'itIT', 'Ohhh, quanta esuberanza!', '', 28153),
(150326, 'itIT', 'Ora sei cibo per pesci!', '', 28153),
(150325, 'itIT', 'Che c\'è da guardare?', '', 28153),
(150324, 'itIT', 'Ora sono io... cibo per pesci...', '', 28153),
(150323, 'itIT', 'Mmm, non sembra esserci la solita gentaglia su quest\'isola. Forse questa deviazione si dimostrerà utile, dopotutto.', '', 28153),
(150322, 'itIT', 'Esche perfette per il mio amo!', '', 28153),
(150321, 'itIT', 'Riduceteli in poltiglia!', '', 28153),
(150320, 'itIT', 'Ora raccogli tempesta!', '', 28153),
(150319, 'itIT', '', 'Veloci, un secchio! Non bisogna sprecarne neanche una goccia!', 28153),
(150318, 'itIT', '', 'Un\'isola che pullula di creature, persone, cose e... Orda. Andate e portatemi del sangue!', 28153),
(150317, 'itIT', '', 'Ciurma! Portatemi del sangue... il mio stupendo, amato sangue! Ci sarà anche una ricompensa per voi.', 28153),
(150316, 'itIT', '', 'Sangue dell\'Orda... il mio preferito! Ciurma, sapete cosa fare!', 28153),
(150315, 'itIT', '', 'Salve! Avete bisogno di tutto il vostro sangue? Magari potete darmene un po\'...', 28153),
(150314, 'itIT', '', 'Tutto quel sangue... sprecato...', 28153),
(150313, 'itIT', '', 'Uccideteli velocemente! Voglio il sangue!', 28153),
(150312, 'itIT', '', 'È l\'ora del sangue!', 28153),
(150311, 'itIT', '', 'Niente sopravvissuti!', 28153),
(150310, 'itIT', 'Ahhh! Ahahah!', '', 28153),
(150309, 'itIT', 'Eheheh!', '', 28153),
(150308, 'itIT', 'Alleaaanzaaa... Giochiamo a fare la guerra?', '', 28153),
(150307, 'itIT', 'Ciao!', '', 28153),
(150306, 'itIT', 'Aheh... eh... eh...', '', 28153),
(150305, 'itIT', 'A cuccia!', '', 28153),
(150304, 'itIT', 'Pete il Furtivo!', '', 28153),
(150303, 'itIT', 'Pete il Furtivo!', '', 28153),
(150302, 'itIT', 'Pete il Furtivo!', '', 28153),
(150301, 'itIT', 'Smettila di infastidirmi!', '', 28153),
(150300, 'itIT', 'Ehi, fa il solletico!', '', 28153),
(150299, 'itIT', 'Ti faccio saltare in aria!', '', 28153),
(150298, 'itIT', 'Ah ah! Preso!', '', 28153),
(150297, 'itIT', 'Leggi il testo runico ad alta voce.', 'Leggi il testo runico ad alta voce.', 28153),
(150295, 'itIT', 'Portami al Trono Dorato.', 'Portami al Trono Dorato.', 28153),
(150294, 'itIT', '', 'Dobbiamo distrarre i Kaldorei mentre cerco di trovare una soluzione al problema dei Fuochi Fatui.', 28153),
(150293, 'itIT', '', 'Mmm, i Fuochi Fatui si stavano disperdendo? Ottimo. Il nostro piano sembra promettente...', 28153),
(150292, 'itIT', '', 'Il mio Demolitore ti farà a pezzi! Non fai che rimandare l\'inevitabile!', 28153),
(150291, 'itIT', '', 'Accoliti, abbattete quella barricata!', 28153),
(150290, 'itIT', '', 'Andate! Fateli a pezzi!', 28153),
(150289, 'itIT', '', 'Campioni, con me. Voi siete invitati ad assistere al gran finale.', 28153),
(150288, 'itIT', '', 'O forse potrai finalmente incontrare di nuovo tuo figlio.', 28153),
(150287, 'itIT', '', 'Allora insegui pure la tua morte da guerriero, Gran Supremo Faucisaure. A me non interessa. Magari rianimerò il tuo corpo senza vita per servirmi ancora una volta.', 28153),
(150286, 'itIT', '', 'Forse a te non interessa che la tua gente muoia, purché sia con onore, ma per me la salvezza dell\'Orda è fondamentale. Chiunque non la pensi così non è degno di stare tra noi.', 28153),
(150285, 'itIT', '', 'L\'onore non ha alcun valore per un cadavere, Faucisaure. Hai il lusso di sottovalutare la morte, ma... è qualcosa che io conosco molto bene.', 28153),
(150284, 'itIT', 'Abbi fede nel piano della Capoguerra, Theron.', '', 28153),
(150283, 'itIT', 'Gli Elfi del Vuoto... dobbiamo occuparci di quei traditori.', '', 28153),
(150282, 'itIT', 'Lordaeron appartiene ai Reietti! Non cedete!', '', 28153),
(150281, 'itIT', 'Il loro assalto presto cederà. Resistete!', '', 28153),
(150280, 'itIT', 'L\'Alleanza è agli sgoccioli, campioni! Oltre la metà dei suoi soldati è caduta.', '', 28153),
(150279, 'itIT', 'Ahahah! Guarda un po\' chi c\'è. Bene, speravo proprio che arrivassi per rendere le cose interessanti!', '', 28153),
(150278, 'itIT', 'È meglio che sia lei in persona a dirtelo. Ora vai!', '', 28153),
(150277, 'itIT', 'Quanto pensi di riuscire a tenerli a bada? Qual è la strategia della Capoguerra?', '', 28153),
(150276, 'itIT', 'No. Degli intrusi ci occuperemo Lor\'themar e io. Non posso rischiare di lasciare la Capoguerra indifesa. Non dovete perderla di vista.', '', 28153),
(150275, 'itIT', 'Intesi. Ti raggiungerò appena possibile.', '', 28153),
(150274, 'itIT', 'La strozzatura li condurrà ai lati della fortezza e assottiglierà i loro ranghi.', '', 28153),
(150273, 'itIT', 'Non c\'è tempo! Ci restano ancora pochi istanti prima di perdere il vantaggio tattico!', '', 28153),
(150272, 'itIT', 'Sì, Selvamorta. Ma... dov\'è Faucisaure?', '', 28153),
(150271, 'itIT', 'Baine! Raduna le catapulte e ogni speziale che riesci a trovare. Mandali alla fortezza immediatamente!', '', 28153),
(150270, 'itIT', 'Con piacere, Selvamorta.', '', 28153),
(150269, 'itIT', 'Lor\'themar, tu colpirai sui fianchi con i Guardaboschi! Posizionali sui tetti!', '', 28153),
(150268, 'itIT', 'Lanciapiaga, sarete la nostra prima linea! Creerete un fiume di Piaga tra noi e il nemico!', '', 28153),
(150267, 'itIT', 'Agli ordini, mia regina.', '', 28153),
(150266, 'itIT', '', 'Incontrati con Lor\'themar. PRESTO! Non deludermi, Nathanos!', 28153),
(150265, 'itIT', 'Maschere antigas! Prendete qui le vostre maschere antigas! E se vi sentite impavidi, prendete uno di quegli zaini e mettetevi al lavoro! Eheheh!', '', 28153),
(150264, 'itIT', 'Tenete alto il vostro onore, eroi. Lok narash.', '', 28153),
(150263, 'itIT', '', 'Uccideteli tutti, campioni! Ricordate le mie parole: Re Anduin e la sua armata non sono venuti qui in pace. Intendono annientarci! Non abbiate alcuna pietà, perché voi non ne riceverete!', 28153),
(150262, 'itIT', 'Soldati dell\'Orda! I vostri fratelli e sorelle giacciono feriti sul campo di battaglia! Non vi sarà onore nella vittoria se li abbandoneremo al loro destino!', '', 28153),
(150261, 'itIT', 'Lok\'tar ogar!', '', 28153),
(150260, 'itIT', 'Sono molti, ma noi siamo più forti. Noi siamo l\'Orda! E schiacceremo tutti coloro che osano sfidarci!', '', 28153),
(150259, 'itIT', 'Campioni! La vostra Capoguerra vi ordina di impugnare le armi contro l\'Alleanza!', '', 28153),
(150258, 'itIT', '', 'Allora è il momento di porre fine a tutto questo una volta per tutte. Faucisaure, raduna le truppe. Io preparerò la Macchina d\'Azerite.', 28153),
(150257, 'itIT', 'Sì, Capoguerra.', '', 28153),
(150256, 'itIT', 'Fai in fretta! La Capoguerra attende!', '', 28153),
(150255, 'itIT', 'Al mio fianco, presto! Dobbiamo continuare ad avanzare prima che l\'Orda abbia modo di reagire!', '', 28153),
(150254, 'itIT', 'I suoi venti sono forti, ma insieme noi lo siamo di più! Continuate, campioni!', '', 28153),
(150253, 'itIT', 'Non così in fretta!', '', 28153),
(150252, 'itIT', '', 'E fate in fretta! Le barriere di ghiaccio non reggeranno per sempre!', 28153),
(150251, 'itIT', 'Eroi! Concentratevi prima sui rinforzi, poi ci occuperemo di quegli Sciamani!', '', 28153),
(150250, 'itIT', 'La Capoguerra... vi... fermerà...', '', 28153),
(150249, 'itIT', 'I venti dello Spirito dell\'Aquila SFERZERANNO LE OSSA VOSTRE!', '', 28153),
(150248, 'itIT', '', '', 28153),
(150246, 'itIT', 'REEE.', '', 28153),
(150245, 'itIT', 'REEEEEE!', '', 28153),
(150244, 'itIT', 'REEE!', '', 28153),
(150242, 'itIT', 'Il libro è pieno di rune incantate che saltano da pagina a pagina.', 'Il libro è pieno di rune incantate che saltano da pagina a pagina.', 28153),
(150241, 'itIT', 'Non posso ancora ucciderli? Me l\'avevate promesso.', '', 28153),
(150240, 'itIT', 'CHE C\'È?', '', 28153),
(150239, 'itIT', 'Pensa a trovare la tua di scatola, $R $garraffone:arraffona;!', 'No, la scatola è mia!\n\nSono venuto qui in cerca di vermi per una zuppa. Alcuni Tortolliani dicono che quella di crostaceo è migliore, ma per me si sbagliano. Non vale la pena scomodare degli stranieri per quella sbobba.\n\nLa Zuppa di Vermi del Fango crea amicizie che durano tutta la vita, e noi Tortolliani viviamo davvero a lungo.\n\nTi darò questa vecchia scatola in cambio di un po\' di Carne di Verme del Fango.', 28153),
(150238, 'itIT', 'Che... male...', '', 28153),
(150237, 'itIT', 'Graaah!', '', 28153),
(150236, 'itIT', 'Prima di sfoderare la spada, ascoltami un attimo...', '', 28153),
(150235, 'itIT', '', 'Qualcuno perquisisca il suo corpo.', 28153),
(150234, 'itIT', '', 'C\'è un tesoro su quell\'isola che non è ancora a bordo della mia nave. Fate qualcosa! Prendete anche quello dell\'Alleanza.', 28153),
(150233, 'itIT', '', 'Vedo che l\'Alleanza è qui e i suoi membri respirano ancora. Rimediamo.', 28153),
(150232, 'itIT', '', 'Quest\'isola ha bisogno di una bella razzia, ragazzi. Procediamo! Odio dover aspettare.', 28153),
(150231, 'itIT', '', 'Aaah?', 28153),
(150230, 'itIT', '', 'Non... ridategli... nulla...', 28153),
(150229, 'itIT', '', 'Ora basta! Uccideteli, ora!', 28153),
(150228, 'itIT', '', 'Sarà più facile depredarvi quando sarete morti.', 28153),
(150227, 'itIT', '', 'Ho sentito dire brutte cose sull\'Alleanza. State lontani da loro.', 28153),
(150226, 'itIT', '', 'Questo ti aiuterà.', 28153),
(150225, 'itIT', '', 'Lascia che me ne occupi io.', 28153),
(150224, 'itIT', '', 'Salve.', 28153),
(150223, 'itIT', '', 'Avevo... ragione.', 28153),
(150222, 'itIT', '', 'Oh, no, sono qui.', 28153),
(150221, 'itIT', 'Forse sarebbe il caso di ritirarci.', '', 28153),
(150220, 'itIT', 'Sono stanco di voi.', '', 28153),
(150219, 'itIT', 'State lontani da noi, Alleanza, o sarò costretto a schiacciarvi.', '', 28153),
(150218, 'itIT', 'Salute.', '', 28153),
(150217, 'itIT', '<Kua\'fon divora il cibo, spargendo pezzetti da tutte le parti.>', '', 28153),
(150216, 'itIT', 'La Luce... Tornerò...', '', 28153),
(150215, 'itIT', 'Scatenate la vostra furia!', '', 28153),
(150214, 'itIT', 'Non ho tempo per questo!', '', 28153),
(150213, 'itIT', '', 'Fai piano.', 28153),
(150212, 'itIT', '', 'Rallenta un po\'.', 28153),
(150211, 'itIT', '', 'Il tuo momento è arrivato.', 28153),
(150210, 'itIT', '', 'Cenere alla cenere.', 28153),
(150209, 'itIT', '', 'I venti ci hanno guidato qui... insieme all\'Alleanza. A volte gli elementi mi sorprendono.', 28153),
(150208, 'itIT', '', 'Alleanza, ascoltate. Non infastiditeci e noi faremo altrettanto.', 28153),
(150207, 'itIT', '', 'Gli elementi non sono in equilibrio qui. Vediamo cosa possiamo fare, ma non mettetevi sulla nostra strada, Alleanza.', 28153),
(150206, 'itIT', '', 'Che cosa vi porta qui?', 28153),
(150205, 'itIT', '', 'Il mio spirito... tornerà...', 28153),
(150204, 'itIT', '', 'State mettendo alla prova la mia pazienza.', 28153),
(150203, 'itIT', '', 'Elementi, aiutateci.', 28153),
(150202, 'itIT', '', 'Lascia che ti aiuti.', 28153),
(150201, 'itIT', '', 'Che la Luce illumini la tua via!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(150200, 'itIT', '', 'Non c\'è gioia nel porre fine a una vita.', 28153),
(150199, 'itIT', '', 'Fate attenzione, i nemici sono arrivati. Evitiamoli, se possibile.', 28153),
(150198, 'itIT', '<Offri del |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Cibo per Dinosauri Extracroccante]|h|r>', '<Offri del |TINTERFACE\\ICONS\\INV_MISC_BAG_07.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Cibo per Dinosauri Extracroccante]|h|r>', 28153),
(150197, 'itIT', '', 'La Luce vi accoglie!', 28153),
(150196, 'itIT', '', 'La Luce... mi chiama...', 28153),
(150195, 'itIT', '<Kua\'fon serra le fauci impazientemente.>\n\nREEE.', '', 28153),
(150194, 'itIT', '', 'Arrendetevi! Risparmiatevi una morte inutile!', 28153),
(150193, 'itIT', '<Kua\'fon ti annusa.>\n\nReee.', '', 28153),
(150192, 'itIT', 'Are you sure you want to do this? It has zero impact on the storyline, apart from bragging rights.', 'Are you sure you want to do this? It has zero impact on the storyline, apart from bragging rights.', 28153),
(150191, 'itIT', 'Questo è un nemico potente!', '', 28153),
(150190, 'itIT', 'La Luce ti ha giudicato!', '', 28153),
(150189, 'itIT', 'La Capoguerra vuole spaventare i Fuochi Fatui, eh? Ho proprio quello che serve.\n\nPreferisci guidarlo o lanciare le bombe?', '', 28153),
(150188, 'itIT', 'La Luce brilla intensamente in questo luogo. Qui giace molta Azerite.', '', 28153),
(150187, 'itIT', 'I\'m still trying to figure out the space for this. We may need to clear some trees out or get a tree asset that I can make glow. \n\nPretend it was awesome and that wisps broke out from the wall, creating visible cracks where you bombed.', 'I\'m still trying to figure out the space for this, we may need to clear some trees out or get a tree asset that I can make glow. Pretend it was awesome and wisps broke out all over the place, creating cracks in the wall of wisps.', 28153),
(150186, 'itIT', 'Voliamo.', 'Voliamo.', 28153),
(150185, 'itIT', 'Posso volare. Dare fuoco alle foreste non è nel mio stile.', 'Posso volare. Dare fuoco alle foreste non è nel mio stile.', 28153),
(150184, 'itIT', 'Che la Luce sia con voi.', '', 28153),
(150183, 'itIT', 'Davvero... un bel combattimento...', '', 28153),
(150181, 'itIT', 'Luce, colpisci il mio nemico!', '', 28153),
(150180, 'itIT', 'Per la Luce!', '', 28153),
(150179, 'itIT', '', 'Non così in fretta.', 28153),
(150178, 'itIT', '', 'Sta\' indietro.', 28153),
(150177, 'itIT', '', 'Chiudiamo questa storia!', 28153),
(150176, 'itIT', '', 'La vittoria è nostra!', 28153),
(150175, 'itIT', '', 'Che avventura! Un\'isola inesplorata colma di pericoli e tesori nascosti! Aspettate, anche l\'Orda è qui?', 28153),
(150174, 'itIT', '', 'Vediamo quali avventure ci attendono qui. Tutto ciò che dobbiamo fare è sbarazzarci dell\'Orda.', 28153),
(150173, 'itIT', '', 'Abitanti dell\'oscurità, non prevarrete! La Vendetta della Luce vi punirà!', 28153),
(150172, 'itIT', '', 'Salve.', 28153),
(150171, 'itIT', '', 'La Luce... mi salverà...', 28153),
(150170, 'itIT', '', 'Non puoi nulla contro le nostre forze!', 28153),
(150169, 'itIT', '<Kua\'fon ti saluta gracchiando.>\n\nReee!', '', 28153),
(150168, 'itIT', '<Kua\'fon scuote la testa vigorosamente nella tua direzione.>', '', 28153),
(150166, 'itIT', '<Kua\'fon gorgoglia giocosamente.>', '', 28153),
(150165, 'itIT', '', 'Date la sua anima in pasto al Vuoto!', 28153),
(150164, 'itIT', '<Kua\'fon inclina la testa mentre ti avvicini.>\n\nReee?', '', 28153),
(150163, 'itIT', '', 'Ah! PER IL VUOTO!', 28153),
(150162, 'itIT', '', 'Qui! Atterriamo qui, me l\'hanno detto i sussurri! Sì! Ahahah. Sììì! Sì, sì, sì, sì, sì, sì!', 28153),
(150161, 'itIT', '', 'Cosa? Chi ha parlato?', 28153),
(150160, 'itIT', '', 'Ahahah, ahhh... Finisco nel Vuoto...', 28153),
(150159, 'itIT', '', 'Cibatevi, miei piccoli!', 28153),
(150158, 'itIT', '', 'Anime deliziose per il Vuoto!', 28153),
(150157, 'itIT', 'Assapora l\'entropia!', '', 28153),
(150156, 'itIT', 'Patetico.', '', 28153),
(150155, 'itIT', 'I selvaggi dell\'Orda sono già arrivati. Non che abbiano qualche possibilità contro il Vuoto.', '', 28153),
(150154, 'itIT', 'Coboldi e Catacombe!', 'Coboldi e Catacombe!', 28153),
(150153, 'itIT', 'Da Coboldi e Catacombe!', 'Da Coboldi e Catacombe!', 28153),
(150152, 'itIT', 'Ti volevi arricchir, riuscirai a fuggir?', 'Ti volevi arricchir, riuscirai a fuggir?', 28153),
(150151, 'itIT', 'Senti ormai che la tua fine incombe!', 'Senti ormai che la tua fine incombe!', 28153),
(150150, 'itIT', 'Vuoto, dammi la forza!', '', 28153),
(150149, 'itIT', 'Ti stan raggiungendo, hanno un fiato tremendo...', 'Ti stan raggiungendo, hanno un fiato tremendo...', 28153),
(150148, 'itIT', 'È una fuga a perdifiato, il nemico è scatenato, e intanto devi pure seguire la mappa!', 'È una fuga a perdifiato, il nemico è scatenato, e intanto devi pure seguire la mappa!', 28153),
(150147, 'itIT', 'Accogli il Vuoto!', '', 28153),
(150146, 'itIT', 'Se quel lume tu sottrai, poi filartela dovrai, fra trappole e pericoli, tu scappa!', 'Se quel lume tu sottrai, poi filartela dovrai, fra trappole e pericoli, tu scappa!', 28153),
(150145, 'itIT', 'TU NO PRENDERE CANDELA!', 'TU NO PRENDERE CANDELA!', 28153),
(150144, 'itIT', 'TU NO PRENDERE CANDELA!', 'TU NO PRENDERE CANDELA!', 28153),
(150143, 'itIT', 'Ruba quello che vuoi, ma una cosa non puoi...', 'Ruba quello che vuoi, ma una cosa non puoi...', 28153),
(150142, 'itIT', 'Sembra perfetto, se c\'è qualche raro oggetto, lo puoi prender con debita cautela.', 'Sembra perfetto, se c\'è qualche raro oggetto, lo puoi prender con debita cautela.', 28153),
(150141, 'itIT', 'Tesori sepolti, ma i rischi son molti, come pure le strutture non a norma.', 'Tesori sepolti, ma i rischi son molti, come pure le strutture non a norma.', 28153),
(150140, 'itIT', 'Ossequi.', '', 28153),
(150139, 'itIT', 'Sperando che il nemico ancora dorma.', 'Sperando che il nemico ancora dorma.', 28153),
(150138, 'itIT', 'Ah... l\'oscurità... mi avvolge...', '', 28153),
(150137, 'itIT', 'Che patetica combriccola. Preparatevi a essere consumati.', '', 28153),
(150136, 'itIT', 'Provaci ancora.', '', 28153),
(150135, 'itIT', 'Con aria da campione, affronti la missione.', 'Con aria da campione, affronti la missione.', 28153),
(150134, 'itIT', 'e degli infiniti tesori che attendono gli avventurieri più impavidi...', 'e degli infiniti tesori che attendono gli avventurieri più impavidi...', 28153),
(150133, 'itIT', 'Ora posso fare la mia posa vittoriosa? Come? Prima devo ucciderli? Oh, d\'accordo.', '', 28153),
(150132, 'itIT', 'Narrano le leggende di un vasto mondo sotterraneo...', 'Narrano le leggende di un vasto mondo sotterraneo...', 28153),
(150131, 'itIT', 'Sì!', 'Sì!', 28153),
(150130, 'itIT', 'Oh, sarete emozionati all\'idea di incontrarmi! E chissà come vi sentirete quando passerete a miglior vita!', '', 28153),
(150129, 'itIT', 'Una nave dell\'Orda! Chissà che faccia faranno quando si accorgeranno che siamo qui.', '', 28153),
(150128, 'itIT', 'Ragazzi, vi va di cantare insieme?', 'Ragazzi, vi va di cantare insieme?', 28153),
(150127, 'itIT', 'Eeeheee!', 'Eeeheee!', 28153),
(150126, 'itIT', 'Oh, benvenuti!', '', 28153),
(150125, 'itIT', 'Ahah!', 'Ahah!', 28153),
(150124, 'itIT', 'Da questa parte!', '', 28153),
(150123, 'itIT', 'Qualcosa non va? Non riuscite a starmi dietro?', '', 28153),
(150122, 'itIT', 'Sì!', 'Sì!', 28153),
(150121, 'itIT', 'Addosso!', 'Addosso!', 28153),
(150120, 'itIT', 'C\'era una probabilità... su un milione...', '', 28153),
(150119, 'itIT', 'Oh, cielo!', 'Oh, cielo!', 28153),
(150118, 'itIT', 'SONO IO! Non temete, ci andrò piano!', '', 28153),
(150117, 'itIT', 'Salve, Orda, sono Kelain. È un piacere incontrarvi qui.', '', 28153),
(150116, 'itIT', '', 'Vattene, verme!', 28153),
(150115, 'itIT', 'Se incontri Grozztok, nun esitare a infilare na spada nel cuore nero suo.', '', 28153),
(150114, 'itIT', '', 'Lurida feccia!', 28153),
(150113, 'itIT', '', 'Come osi sanguinare su di me! Ah, fai più attenzione!', 28153),
(150112, 'itIT', '', 'Oh, che peccato... per voi, Alleanza. Vi metteremo al vostro posto molto presto.', 28153),
(150111, 'itIT', 'Grozztok meritava il destino suo. Spero che tu l\'abbia fatto soffrire assai.', '', 28153),
(150110, 'itIT', '', 'Santo cielo! Questo non è un lavoro da donne.', 28153),
(150109, 'itIT', 'Schiatterò tra cheste dune, e me lo merito.', '', 28153),
(150108, 'itIT', '', 'Be\', penserò io a ripararlo.', 28153),
(150107, 'itIT', '', 'Oh, siete voi. Salve.', 28153),
(150106, 'itIT', '', 'Che scarsa... soddisfazione...', 28153),
(150105, 'itIT', '', 'Mettete i guanti! Non possiamo sporcarci le mani.', 28153),
(150104, 'itIT', '', 'Ehi, prendiamo quello debole!', 28153),
(150103, 'itIT', '', 'Sì!!! Avete visto?', 28153),
(150102, 'itIT', '', 'Andiamo, scendiamo da questa nave. Stiamo perdendo tempo! Andiamo, andiamo!', 28153),
(150101, 'itIT', '', 'Perché sono qui quando potrei essere là fuori a combattere?', 28153),
(150100, 'itIT', 'Con le chiavi del Sovrintendente in nostro possesso, possiamo liberare la nostra risorsa e sfruttarne le abilità per i nostri scopi.', '', 28153),
(150099, 'itIT', '', 'Ah, ah! Bel tentativo!', 28153),
(150098, 'itIT', '', 'Che lentezza!', 28153),
(150097, 'itIT', 'La Dama Oscura sarà compiaciuta.', '', 28153),
(150096, 'itIT', '', 'No... non... vale! Siete della... brutta gente...', 28153),
(150095, 'itIT', '', 'Tutti all\'attacco!', 28153),
(150094, 'itIT', '', 'Non potete sfuggirmi!', 28153),
(150093, 'itIT', 'Ora! Eliminate il bersaglio!', '', 28153),
(150092, 'itIT', 'Umpf! Un destino inevitabile.', '', 28153),
(150091, 'itIT', 'Prendetegli le chiavi, mettete al sicuro la nostra risorsa e uccidete chiunque si metta sulla vostra strada.', '', 28153),
(150090, 'itIT', 'È ora. Ricordate l\'addestramento e mostrate all\'Alleanza cosa significa essere degli Alti Nobili.', '', 28153),
(150089, 'itIT', 'Raggiungete il piano superiore e troverete il Sovrintendente.', '', 28153),
(150088, 'itIT', 'Concentratevi, ci sono degni avversari nei paraggi. E anche dei membri dell\'Alleanza.', '', 28153),
(150087, 'itIT', 'Una recente fuga ha scatenato il caos nei livelli più bassi della prigione, che possiamo sfruttare a nostro vantaggio.', '', 28153),
(150086, 'itIT', 'L\'Alleanza è qui. Convogliate le vostre energie. Non commetteremo errori.', '', 28153),
(150085, 'itIT', 'Il nostro obiettivo è rinchiuso a Tol Dagor.', '', 28153),
(150084, 'itIT', 'Salute.', '', 28153),
(150083, 'itIT', 'Presto... ritirata...', '', 28153),
(150082, 'itIT', 'Seguite il piano. Addosso!', '', 28153),
(150081, 'itIT', 'Abbatteteli! Seguite me!', '', 28153),
(150080, 'itIT', 'Oh, oh, oh, Bersaglio prioritario!', '', 28153),
(150079, 'itIT', 'Ne ho preso uno! Ne ho preso uno!', '', 28153),
(150078, 'itIT', 'L\'Orda è qui? Siete sicuri? Vo-vo-voglio dire, ho degli strumenti delicati e sono COSTOSISSIMI.', '', 28153),
(150077, 'itIT', 'Salve!', '', 28153),
(150076, 'itIT', 'Avevo... ragione... ragazzi...', '', 28153),
(150075, 'itIT', '$n è completamente $gcarico:carica;!', '$n è completamente $gcarico:carica;!', 28153),
(150074, 'itIT', '$n inizia a vibrare di potere!', '$n inizia a vibrare di potere!', 28153),
(150073, 'itIT', 'Va\' via!', '', 28153),
(150072, 'itIT', 'Il potere di $n continua a crescere...', 'Il potere di $n continua a crescere...', 28153),
(150071, 'itIT', 'Be\', Io-io-io... non... non credo che dovremmo farlo!', '', 28153),
(150070, 'itIT', 'Il potere di $n cresce...', 'Il potere di $n cresce...', 28153),
(150069, 'itIT', '', 'Medico!', 28153),
(150068, 'itIT', 'Una Scintilla Caotica carica sul campo di battaglia!', 'Una Scintilla Caotica carica sul campo di battaglia!', 28153),
(150067, 'itIT', '', 'Bersaglio eliminato.', 28153),
(150066, 'itIT', 'Un Nucleo d\'Energia si forma nelle vicinanze.', 'Un Nucleo d\'Energia si forma nelle vicinanze.', 28153),
(150065, 'itIT', '', 'Preparatevi, ragazzi, l\'Orda è qui. Prima sparate, poi razziate.', 28153),
(150064, 'itIT', '', 'Mai farsi scappare una cosa buona.', 28153),
(150063, 'itIT', '', 'Ritirata.', 28153),
(150062, 'itIT', 'Una creatura di pura energia si forma davanti a te!', 'Una creatura di pura energia si forma davanti a te!', 28153),
(150061, 'itIT', '', 'Argh... fa male...', 28153),
(150060, 'itIT', '', 'Nemici in arrivo!', 28153),
(150059, 'itIT', '', 'Mira alla testa, è il loro punto debole!', 28153),
(150058, 'itIT', 'È ora. Di farli. FUORI!', '', 28153),
(150057, 'itIT', 'Mai usare un coltello in una battaglia contro un robot.', '', 28153),
(150056, 'itIT', 'Hanno abbattuto il mio Tecnostruzzo! Ritirata!', '', 28153),
(150055, 'itIT', 'Tecnostruzzo abbattuto! Dobbiamo evacuare, e in fretta!', '', 28153),
(150054, 'itIT', 'Come uno scarafaggio.', '', 28153),
(150053, 'itIT', 'L\'unico insetto buono è un insetto morto. E voi dell\'Orda sembrate proprio insetti.', '', 28153),
(150052, 'itIT', 'La violenza, nel corso della storia, ha risolto più questioni di qualsiasi altro fattore, aggiungiamone una all\'elenco.', '', 28153),
(150051, 'itIT', 'L\'Orda è qui, quindi ascoltatemi. Se non fate il vostro dovere vi ammazzo. Serrate i ranghi!', '', 28153),
(150050, 'itIT', 'Arruolatevi ora!', '', 28153),
(150049, 'itIT', 'Fuoco in buca!', '', 28153),
(150048, 'itIT', 'Ora non... deludetemi...', '', 28153),
(150047, 'itIT', 'Occhi aperti, abbiamo compagnia!', '', 28153),
(150046, 'itIT', 'ARRIVANO!', '', 28153),
(150044, 'itIT', 'È tempo di riparazioni.', '', 28153),
(150043, 'itIT', 'Scavate più in fretta, il tesoro deve essere qui da qualche parte!', 'Scavate più in fretta, il tesoro deve essere qui da qualche parte!', 28153),
(150041, 'itIT', 'Ahahah! Blam!', '', 28153),
(150040, 'itIT', 'Affilate i coltelli, abbiamo dei corpi da far sparire. Muoviamoci con passo felpato.', '', 28153),
(150039, 'itIT', 'Cosa volete?', '', 28153),
(150038, 'itIT', 'Che lentezza!', '', 28153),
(150037, 'itIT', 'Non siete... niente...', '', 28153),
(150036, 'itIT', 'Non scappate, Alleanza.', '', 28153),
(150035, 'itIT', '', 'La gente nostra tiene paura del cambiamento che propone Talanji, e quando è spaventata, la gente fa cose stupide.', 28153),
(150034, 'itIT', '', 'A tutti i cannoni, pronti a far fuoco!', 28153),
(150033, 'itIT', '', 'Sono stanca di questi giochetti. Ridurrò Boralus in cenere piuttosto che lasciarvi vincere!', 28153),
(150032, 'itIT', '', 'Osate ferire la mia bellissima creatura?!?', 28153),
(150031, 'itIT', '', 'Tocca a te.', 28153),
(150030, 'itIT', '', 'Tutto secondo i piani.', 28153),
(150029, 'itIT', '', 'Ho tracciato la rotta. È audace ed efficiente, esattamente come ogni piano dovrebbe essere. Cercate di adeguarvi.', 28153),
(150028, 'itIT', '', 'Armatura interessante... ma ha bisogno di più spuntoni.', 28153),
(150027, 'itIT', '', 'Questo... non... ci fermerà...', 28153),
(150026, 'itIT', '', 'Scossa!', 28153),
(150025, 'itIT', '', 'Per Kul Tiras!', 28153),
(150024, 'itIT', '', 'Non l\'avevate organizzata proprio bene, eh?', 28153),
(150023, 'itIT', 'Di nuovo in affari!', '', 28153),
(150022, 'itIT', 'È ora di scatenare il segatronchi!', '', 28153),
(150021, 'itIT', 'Ehi! Costerà una fortuna metterlo a posto!', '', 28153),
(150020, 'itIT', '', 'Il cancello è caduto! Fate breccia nella città e uccidete chiunque si opponga a me!', 28153),
(150019, 'itIT', 'Bah! Stupido rottame.', '', 28153),
(150018, 'itIT', 'Ahahah! Soldi!', '', 28153),
(150017, 'itIT', 'Pare che questo posto abbia molto da offrire! Ombre, bottini... Alleanza? Bah, è tutto rovinato ora.', '', 28153),
(150016, 'itIT', 'Questa è una grandiosa opportunità d\'affari. Potrei persino vendere quelli dell\'Alleanza come pezzi di ricambio! Eheheh!', '', 28153),
(150015, 'itIT', '', 'Permettetemi di dimostrarvelo.', 28153),
(150014, 'itIT', '', 'Godetevi quest\'inutile vittoria, stolti! Senza la flotta di Kul Tiras, non avete speranze di sconfiggermi.', 28153),
(150013, 'itIT', 'Lo senti questo odore? È il profumo del bottino, una montagna di bottino. Preparate le sacche!', '', 28153),
(150012, 'itIT', 'Che succede?', '', 28153),
(150011, 'itIT', 'Non sarà l\'ultima vol... ta... che ci vediamo...', '', 28153),
(150010, 'itIT', '', 'Ce l\'avete fatta! Senza quel gigante, le forze di Bracescura saranno cacciate dalla città.', 28153),
(150009, 'itIT', 'È per questo che questa bellezza è stata costruita!', '', 28153),
(150008, 'itIT', 'Modalità assassina, attivata!', '', 28153),
(150007, 'itIT', 'Nella mischia!', '', 28153),
(150006, 'itIT', 'Ops, forse ho esagerato.', '', 28153),
(150005, 'itIT', 'Yawn! Siamo già arrivati? Ma questo è il momento perfetto per un pisolino.', '', 28153),
(150004, 'itIT', 'Non dovrei farlo tutte le volte, se smettessimo di combattere.', '', 28153),
(150003, 'itIT', 'Qualcuno deve leccare le tue ferite.', '', 28153),
(150002, 'itIT', 'Grrr-salve!', '', 28153),
(150001, 'itIT', 'Oh, finalmente! È ora di un bel sonnellino...', '', 28153),
(150000, 'itIT', 'È l\'ora della pennichella!', '', 28153),
(149999, 'itIT', 'Ahahah! Oh, scappate pure, Ordaioli. Non vi inseguiremo!', '', 28153),
(149998, 'itIT', '', 'Prega... preda!', 28153),
(149997, 'itIT', '', 'Avrò bisogno di una nuova preda!', 28153),
(149996, 'itIT', '', 'Ahhh... c\'è profumo di prede nell\'aria. Adoro dare la caccia prima di uccidere!', 28153),
(149995, 'itIT', '', 'Avete un odore strano.', 28153),
(149994, 'itIT', '', 'Ah... il dolce profumo... del sangue...', 28153),
(149993, 'itIT', '', 'Non temere... presto toccherà a te!', 28153),
(149992, 'itIT', '', 'Colpite alla gola!', 28153),
(149991, 'itIT', 'Ben fatto! Queste terre sono più al sicuro grazie ai tuoi sforzi.', '', 28153),
(149990, 'itIT', 'Senza Pietà!', '', 28153),
(149989, 'itIT', 'Chesto mostrerà loro la forza delli Zandalari!', '', 28153),
(149988, 'itIT', 'Sento l\'odore della tua paura.', '', 28153),
(149987, 'itIT', 'Oh, questo mi è piaciuto!', '', 28153),
(149986, 'itIT', 'Orda! Li faremo fuori. Che la caccia abbia inizio! Auuu!', '', 28153),
(149985, 'itIT', 'Le nostre spie hanno rilevato una pericolosa minaccia nella zona. Trovala ed eliminala!', '', 28153),
(149984, 'itIT', 'Orda! Quanto vorrei non essere controvento...', '', 28153),
(149983, 'itIT', '', 'Non fa alcuna differenza. I miei cannoni presto ridurranno ogni opposizione in cenere!', 28153),
(149982, 'itIT', 'Restate col branco e non andatevene in giro soli. Sento qualcosa di infetto nell\'aria.', '', 28153),
(149981, 'itIT', 'Roar...', '', 28153),
(149980, 'itIT', 'Non potete... tenere a bada la bestia...', '', 28153),
(149979, 'itIT', 'Si pentirà di chesta eresia! Di chuka Rezan!', '', 28153),
(149978, 'itIT', 'Fateli a pezzi!', '', 28153),
(149977, 'itIT', 'Auuu! Branco, attaccate!', '', 28153),
(149976, 'itIT', '', 'Ha! La capa tua mo\' è mia! Ahahah!', 28153),
(149975, 'itIT', '', 'Ohhh, chest\'isola sembra molto promettente. Fate largo, tengo parecchi vudù da fare.', 28153),
(149974, 'itIT', '', 'Mo\' ti riparo io.', 28153),
(149973, 'itIT', '', 'Uhhh! Tieni na bella capa! Posso pigliarla quando schiatti?', 28153),
(149972, 'itIT', '', 'Coff, coff... Eheheh... i Lanciascura nun schiattano mai...', 28153),
(149971, 'itIT', '', 'Pigliati sto maleficio!', 28153),
(149970, 'itIT', '', 'Ahahah! Nun tieni scampo!', 28153),
(149969, 'itIT', '', 'Ehi, tu! Lasciati rimpicciolire la capa!', 28153),
(149968, 'itIT', 'Eliminiamo chesto.', '', 28153),
(149967, 'itIT', 'Direi che ti ho pigliato.', '', 28153),
(149966, 'itIT', 'Chesta è na bella isola. Chissà cosa ci troveremo oggi.', '', 28153),
(149965, 'itIT', 'Che vuoi?', '', 28153),
(149964, 'itIT', 'Mi riposo solo n\'attimo...', '', 28153),
(149963, 'itIT', 'Fatti nu pisolino.', '', 28153),
(149962, 'itIT', 'Da dove arrivano chesti? Che ci fanno accà?', '', 28153),
(149961, 'itIT', '', 'ROAAAR!', 28153),
(149960, 'itIT', '', 'Più sangue!', 28153),
(149959, 'itIT', '', 'Ancora! Ne voglio ancora!', 28153),
(149958, 'itIT', '', 'Tattiche... di squadra... Bah, accideteli! Aaargh!', 28153),
(149957, 'itIT', '', 'Alleanza, ah! Accideteli tutti quanti! Portatemi i cuori loro...', 28153),
(149956, 'itIT', '', 'Attaccateli, smembrateli! Ci starà sangue ovunque! Ahahah!', 28153),
(149955, 'itIT', '', 'Che vuoi?', 28153),
(149954, 'itIT', '', 'Schiatterò da guerriera! <Sputa>', 28153),
(149953, 'itIT', '', 'Strappate le braccia loro!', 28153),
(149952, 'itIT', 'Ehiii! Sono qui.', '', 28153),
(149951, 'itIT', 'Dove credi di andare?', '', 28153),
(149950, 'itIT', 'Bene, bene... Salve.', '', 28153),
(149949, 'itIT', 'Ben... fatto...', '', 28153),
(149948, 'itIT', 'Un\'uccisione per me. Sono sicuramente in vantaggio.', '', 28153),
(149947, 'itIT', 'Apriamo le danze!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149946, 'itIT', 'Dovrai comprarti una faccia nuova, prima.', 'Dovrai comprarti una faccia nuova, prima.', 28153),
(149945, 'itIT', '', 'Vedo incertezza nei tuoi occhi, $n.\n\nTi permetterò di chiedermi informazioni sui miei piani, se lo desideri.', 28153),
(149944, 'itIT', 'Capoguerra, posso chiederti perché vogliamo conquistare Teldrassil?', 'Capoguerra, posso chiederti perché vogliamo conquistare Teldrassil?', 28153),
(149943, 'itIT', 'Opportunità?', 'Opportunità?', 28153),
(149942, 'itIT', 'È incerto, Capoguerra.', 'È incerto, Capoguerra.', 28153),
(149940, 'itIT', '', 'Ciò che è certo è che l\'Alleanza userà Darnassus come porto sicuro per portare l\'Azerite nei Regni Orientali. Anduin Wrynn costruirà delle nuove e potenti armi e prima o poi le punterà contro la nostra terra. Prima colpirà Sepulcra e Lunargenta, poi si concentrerà sulla caduta di Kalimdor.\n\nPer garantire il futuro dell\'Orda, dobbiamo essere noi i primi ad agire.\n\nOccupando Darnassus, controlleremo il flusso d\'Azerite e faremo in modo che non venga usata contro di noi. L\'Alleanza non oserà attaccare la sua stessa città per paura di fare del male ai propri civili.\n\nCon un solo colpo, garantiremo la pace per generazioni.', 28153),
(149939, 'itIT', '', 'Il tempo non è un lusso che possiamo concederci, ma rispetto il tuo desiderio di sapere di più.\n\n<Sylvanas indica Silitus sulla mappa.>\n\nQUESTO ha cambiato per sempre l\'equilibrio di potere su Azeroth.\n\nStiamo continuando a trovare Depositi d\'Azerite in tutto il mondo, $n. Anche se non conosciamo ancora il suo pieno potenziale, è chiaro che questa sostanza abbia una grande potenza distruttiva.\n\nCome sarà la guerra tra vent\'anni? E tra cento?\n\nCome può l\'Orda sperare di difendere i suoi confini se l\'Alleanza avrà il controllo dell\'Azerite?', 28153),
(149938, 'itIT', '', 'Vuoi farmi una domanda, $n?', 28153),
(149937, 'itIT', 'I Senzafede tengono le bestie selvagge rinchiuse qui vicino. A me pare un\'ottima opportunità.', '', 28153),
(149936, 'itIT', 'Sembra che l\'Orda sia arrivata. Le cose si stanno per fare... interessanti.', '', 28153),
(149935, 'itIT', 'Non riesci proprio a starmi lontano, vero?', '', 28153),
(149934, 'itIT', 'Congelateli, ragazzi!', '', 28153),
(149933, 'itIT', 'Salve, bellezza.', '', 28153),
(149932, 'itIT', 'Bel colpo... Ci rivedremo... alla prossima...', '', 28153),
(149931, 'itIT', 'Ah! Un\'altra uccisione per me!', '', 28153),
(149930, 'itIT', 'Il mio corpo è pronto!', '', 28153),
(149929, 'itIT', 'Ma queste armi ci daranno un vantaggio ben più grande.', '', 28153),
(149928, 'itIT', 'Ti gallano le mie ali nuove? Come un lampo mi fan saettare, nessuno sguiscio mi può scappare!$b$bNemmeno gli sgugga.$b$bDannati sgugga.', '', 28153),
(149927, 'itIT', 'Gli sguisci di Zandalar sono strani. Troppo uggosamente salacidi, e a volte rispondono anche.', '', 28153),
(149926, 'itIT', 'Orda! Finalmente un po\' d\'azione. Sarà meglio togliersi la camicia questa volta!', '', 28153),
(149925, 'itIT', '<Kua\'fon gracchia di gioia e ingoia il boccone.>', '', 28153),
(149924, 'itIT', '<Kua\'fon annusa il cibo prima di divorarlo con gusto.>', '', 28153),
(149923, 'itIT', '<Kua\'fon afferra il cibo al volo.>', '', 28153),
(149922, 'itIT', '<Kua\'fon si getta verso il cibo offerto e lo ingoia intero.>', '', 28153),
(149921, 'itIT', 'Ci sono molti segreti, misteriosi e divini. Alcuni son veri, altri son meschini.', '', 28153),
(149920, 'itIT', 'Reee?', '', 28153),
(149919, 'itIT', 'REEE!', '', 28153),
(149918, 'itIT', 'Reee!', '', 28153),
(149917, 'itIT', 'REEE.', '', 28153),
(149916, 'itIT', 'Un Hozen volante? Come?', 'Un Hozen volante? Come?', 28153),
(149915, 'itIT', 'Serve una ritirata strategica!', '', 28153),
(149914, 'itIT', 'Ci penso io alle tue ferite!', '', 28153),
(149913, 'itIT', 'Salve. Siete venuti ad ammirare il migliore?', '', 28153),
(149912, 'itIT', 'Nun ci restano molte provviste, ma posso darti qualcosa. Aiutaci e forse potrei procurarti qualcosa di veramente buono.', 'Nun ci restano molte provviste, ma posso darti qualcosa. Aiutaci e forse potrei procurarti qualcosa di veramente buono.', 28153),
(149911, 'itIT', '<Offri del |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Cibo per Dinosauri Biologico]|h|r>', '<Offri del |TINTERFACE\\ICONS\\INV_MISC_BAG_10.BLP:16|t |Hitem:157779:0:0:0:0:0:0:0:0:0|h|cFFFFFFFF[Cibo per Dinosauri Biologico]|h|r>', 28153),
(149910, 'itIT', 'Questo è il punto migliore, il tesoro deve essere qui.', 'Questo è il punto migliore, il tesoro deve essere qui.', 28153),
(149909, 'itIT', 'Non... finisce... qui...', '', 28153),
(149908, 'itIT', '<Kua\'fon ti guarda le mani in cerca di cibo.>\n\nReee? REEE.', '', 28153),
(149907, 'itIT', 'Stai. Al tuo. Posto.', '', 28153),
(149906, 'itIT', 'Via, cani dell\'Orda!', '', 28153),
(149905, 'itIT', 'State per essere surclassati!', '', 28153),
(149904, 'itIT', 'L\'Orda... così priva d\'immaginazione, d\'ingegno, d\'intelletto. Come avete fatto a trovare quest\'isola? Ci sarete capitati per caso, non c\'è altra spiegazione.', '', 28153),
(149903, 'itIT', 'Parlerò lentamente, in modo che possiate seguirmi. Isola... nostra. Voi... andare via. Avete capito?', '', 28153),
(149902, 'itIT', 'Selvaggi dell\'Orda! Accetteremo la vostra resa solo se ci consegnerete la vostra Azerite. Spero sarete abbastanza furbi da accettare la mia offerta.', '', 28153),
(149901, 'itIT', '', 'Sì? Ci conosciamo?', 28153),
(149900, 'itIT', '', 'Uh! È così che si vestono normalmente quelli dell\'Alleanza? Dovreste andarvene... prima di morire per l\'imbarazzo!', 28153),
(149899, 'itIT', '', 'Quella è veramente la nave dell\'Alleanza? È stata attaccata da un Gigante del Mare o è sempre stata così?', 28153),
(149898, 'itIT', 'Fa caldo qui, o sono io? Eheh, sto scherzando... certo che sono io!', '', 28153),
(149897, 'itIT', 'Carne alla griglia!', '', 28153),
(149896, 'itIT', 'Più fuoco!', '', 28153),
(149895, 'itIT', 'Appicchiamo qualche fuoco!', '', 28153),
(149894, 'itIT', 'Saboterò i loro cannoni ai livelli superiori mentre darai fuoco alla gola. Troviamoci ai loro recinti delle bestie quando avrai finito.', '', 28153),
(149893, 'itIT', '', 'Uh! Se solo potessi non guardarvi mentre vi uccido!', 28153),
(149892, 'itIT', 'Annegate il vostro odore nell\'oceano o lavatevi nelle mie fiamme. La scelta è vostra, Alleanza!', '', 28153),
(149891, 'itIT', 'Argh! Che cos\'è questo tanfo? Oh... l\'Alleanza ha mandato i suoi campioni \"migliori\". Sai perché puzzano così? È perché mangiano troppo formaggio.', '', 28153),
(149890, 'itIT', 'Che la Luce vi benedica.', '', 28153),
(149889, 'itIT', 'Hai combattuto bene, ma io ho combattuto meglio.', '', 28153),
(149888, 'itIT', 'Ritirata.', '', 28153),
(149887, 'itIT', 'Che la Luce ti guarisca!', '', 28153),
(149886, 'itIT', 'Ahhh, l\'Alleanza. Era una giornata così bella. Che ne dite di migliorarla andandovene?', '', 28153),
(149885, 'itIT', 'Quest\'isola è nostra, Alleanza. La violenza non sarà necessaria se ve ne andrete.', '', 28153),
(149884, 'itIT', 'Il nemico ci è addosso!', '', 28153),
(149883, 'itIT', '$n inizia a lanciare Cura Maggiore!', '$n inizia a lanciare Cura Maggiore!', 28153),
(149882, 'itIT', '', 'Trovate una via, o createla con la forza. Il tempo non è un lusso che possiamo concederci.', 28153),
(149881, 'itIT', '', 'Allora è deciso. Faucisaure, Nathanos... Partite immediatamente.', 28153),
(149880, 'itIT', 'La maggior parte dei contrabbandieri preferirebbe evitare l\'attenzione del Gran Supremo... ma forse ne abbiamo trovato uno che convinceremo ad aiutarci.', '', 28153),
(149879, 'itIT', 'Non sono un ingenuo. Le probabilità che Lungavista abbia ricevuto tutta la sua merce legittimamente sono molto scarse. Qualcuno sta usando una via segreta che attraversa Vilbosco.', '', 28153),
(149878, 'itIT', 'Chiedo scusa?', '', 28153),
(149877, 'itIT', 'Mmm, conosci molti contrabbandieri, Selvamorta?', '', 28153),
(149876, 'itIT', '', 'Schiacceremo Malfurion da entrambi i lati.', 28153),
(149875, 'itIT', '', 'Faucisaure, prendi una squadra e raggiungi Vilbosco. Trova un sentiero tra le montagne che conduca a Rivafosca, ma lascia le armi d\'assedio al mio comando.', 28153),
(149874, 'itIT', '', 'A quanto pare i Fuochi Fatui sono suscettibili alle distrazioni. Dobbiamo sfruttare questa loro debolezza.', 28153),
(149873, 'itIT', 'Capoguerra, non vi è passaggio sicuro attraverso Vilbosco.', '', 28153),
(149872, 'itIT', '', 'Zuldazar, una delle uniche città sopravvissute alla Separazione che ancora riesce a prosperare. Al culmine della sua gloria, l\'Impero degli Zandalari dominava mezzo mondo. A Suramar, mettiamo ancora in guardia i nostri figli dei pericoli delle arti oscure dei Troll.\n\nLi abbiamo già visti assetati di sangue, ma questo... be\', è facile immaginare chi abbia davvero bisogno dell\'altro: gli Zandalari o l\'Orda.', 28153),
(149871, 'itIT', '', 'La furia dei Vulpera sorge dalle sabbie per chiedere vendetta. E io... l\'avrò!', 28153),
(149870, 'itIT', '', 'La morte bussa alla vostra porta, Senzafede!', 28153),
(149869, 'itIT', '', 'A Zoram\'gar, presto!', 28153),
(149868, 'itIT', 'La cerimonia è pronta a iniziare.', 'La cerimonia è pronta a iniziare.', 28153),
(149867, 'itIT', 'Mi sento un po\' in imbarazzo.\n\nAvevo scritto il mio discorso su un quaderno, ma devo averlo... lasciato da qualche parte che non ricordo.\n\nDeve essere qui in questa stanza. Se mi aiutassi a trovarlo, te ne sarei immensamente grato.', '', 28153),
(149866, 'itIT', 'Oh, salve. Temo che non ci siamo mai visti, ma ti ringrazio per essere qui per la mia cara Lucy.\n\nCome posso aiutarti?', '', 28153),
(149865, 'itIT', 'Nun temere, Vaza si occuperà di te a Nazmir!', '', 28153),
(149864, 'itIT', 'La piccola Lucille non sa che le facevo visita ogni volta che veniva a Selvabianca.\n\nLa sua disperazione per ciò che era successo qui le impediva di vedere il mio spirito. Posso solo sperare che qualche parte di lei sappia che sono qui.', '', 28153),
(149858, 'itIT', 'E ora tu ti unirai a loro. Che Sethraliss abbia pietà di te.', '', 28153),
(149857, 'itIT', 'CI VOLEVA PROPRIO UNA BELLA RISSA!', 'CI VOLEVA PROPRIO UNA BELLA RISSA!', 28153),
(149856, 'itIT', '<Kua\'fon divora il pesce.>', '', 28153),
(149855, 'itIT', '<Kua\'fon annusa il pesce con fare interdetto.>', '', 28153),
(149854, 'itIT', '<Offri della Carne di Brillapinna.>', '<Offri della Carne di Brillapinna.>', 28153),
(149853, 'itIT', '<Kua\'fon si copre dalla paura, allontanandosi mentre ti avvicini.>$b$b<Forse dovresti persuaderlo in qualche modo. Con un bocconcino, magari?>', '', 28153),
(149852, 'itIT', 'Sempre...', '', 28153),
(149851, 'itIT', 'Sarò con te per sempre, Lucy...', '', 28153),
(149850, 'itIT', '', 'Oh, Alexander, quanto vorrei che fossi qui ora...', 28153),
(149849, 'itIT', 'Ti sono grato.', '', 28153),
(149848, 'itIT', 'Finalmente... posso abbandonare i ricordi di questo luogo.', '', 28153),
(149847, 'itIT', 'No, amico mio. Il nostro popolo è morto a causa tua.', '', 28153),
(149846, 'itIT', 'Non ho costretto nessuno a seguirmi, Vorrik. Il nostro è un popolo di conquistatori...', '', 28153),
(149845, 'itIT', 'Ti pentirai di aver assistito... a tutto questo...', 'Ti pentirai di aver assistito... a tutto questo...', 28153),
(149844, 'itIT', 'Ugh... Dama Crestabianca è un nemico potente...', 'Dama Crestabianca è un nemico potente...', 28153),
(149843, 'itIT', '', 'Sarà meglio!', 28153),
(149842, 'itIT', 'Non preoccupatevi, me ne occupo io.', 'Non preoccupatevi, me ne occupo io.', 28153),
(149841, 'itIT', '', 'Idiota! Non devono esserci testimoni!', 28153),
(149840, 'itIT', 'Sembra che abbiamo compagnia...', 'Sembra che abbiamo compagnia...', 28153),
(149839, 'itIT', 'È sempre un piacere fare affari con voi, signora.', 'È sempre un piacere fare affari con lei, signora.', 28153),
(149838, 'itIT', '', 'Ecco i tuoi soldi, fuorilegge. Prendili, prima che qualcuno ti veda!', 28153),
(149837, 'itIT', 'Un\'imboscata! Lucy, dietro di me! Guardie, alle armi!', '', 28153),
(149836, 'itIT', '', 'Alexander, no!', 28153),
(149835, 'itIT', 'Niente di personale, ragazzo.', 'Niente di personale, ragazzo.', 28153),
(149834, 'itIT', 'Alexander, hai preparato... Aspetta, cos\'è stato?', '', 28153),
(149833, 'itIT', 'In qualità di sovrano di Drustvar e padre di Lucille, è mio grande onore celebrare il matrimonio, al cospetto della terra, del cielo e del mare.', '', 28153),
(149832, 'itIT', 'Amici, parenti, onorati ospiti. Siamo qui riuniti in questa bella giornata d\'autunno per celebrare l\'unione di Lucille e Alexander.', '', 28153),
(149831, 'itIT', 'Molto bene.', '', 28153),
(149830, 'itIT', '', 'Certamente. Procedi, padre.', 28153),
(149829, 'itIT', 'Procediamo?', '', 28153),
(149828, 'itIT', 'Scenderà tra poco. Ha detto di cominciare senza di lei.', '', 28153),
(149827, 'itIT', '', 'Non fa niente, padre. Dov\'è la mamma?', 28153),
(149826, 'itIT', 'Vogliate scusare il mio ritardo.', '', 28153),
(149825, 'itIT', 'Ma dov\'è Dama Crestabianca?', '', 28153),
(149824, 'itIT', '', 'Ecco che arriva!', 28153),
(149823, 'itIT', 'Oh, e porgi le mie scuse per il ritardo.', '', 28153),
(149822, 'itIT', 'Per favore, informa i piccioncini che scenderò a breve.', '', 28153),
(149821, 'itIT', 'Oh, l\'hai trovato! Grazie al cielo!', '', 28153),
(149820, 'itIT', '', 'Stai cercando di farci perdere del tempo?', 28153),
(149819, 'itIT', '', 'Stiamo cercando un libro. Credi che non abbiamo già controllato nella libreria?', 28153),
(149818, 'itIT', '', 'Fai sul serio? Perché mai mio marito avrebbe dovuto mettere il suo diario nello zaino di Lucille?!? ', 28153),
(149817, 'itIT', 'Non credo siano tra le lettere di Lucy, ma suppongo che dovremmo controllare comunque.', '', 28153),
(149816, 'itIT', 'Ti ringrazio per l\'aiuto, ma ti chiederei gentilmente di non rovistare nella biancheria di mia figlia...', '', 28153),
(149815, 'itIT', '', 'Il suo cuore non gioverà di certo alla casata...', 28153),
(149814, 'itIT', 'Lucy sta semplicemente seguendo il suo cuore, Meredith. Proprio come ho fatto io quando ti ho sposata.', '', 28153),
(149813, 'itIT', '', 'Arthur, non dovresti permettere tutto questo. Insomma, nostra figlia che sposa un comune mercante?', 28153),
(149812, 'itIT', '', 'Ti ringrazio per essere qui. Siamo onorati della tua presenza.', 28153),
(149811, 'itIT', 'Perché sei qui?', '', 28153),
(149810, 'itIT', 'Lucy? Sei venuta... aspetta, tu non sei Lucy.', '', 28153),
(149809, 'itIT', 'Nemmeno tu. Il padre tuo è irritato dal fatto che hai portato cheste creature accà. Mi ha ordinato di prenderti in custodia.', '', 28153),
(149807, 'itIT', 'Ho assicurato la mia vittoria a prescindere da ciò che accade qui. Il Generale Jakra\'zet ha già la mia chiave e a quest\'ora... suppongo abbia anche la vostra.', '', 28153),
(149806, 'itIT', 'Che cos\'hai fatto, Korthek?', '', 28153),
(149805, 'itIT', 'Mi chiedo, Vorrik... Se tu sei qui, chi sta proteggendo le chiavi del tuo tempio?', '', 28153),
(149804, 'itIT', '', 'Io esisto per difendere la mia gente. Morirai per mano di questa Vulpera di basso rango!', 28153),
(149803, 'itIT', 'Vulpera miserabile, esisti solo per servire il mio impero!', '', 28153),
(149802, 'itIT', '', '', 28153),
(149801, 'itIT', 'Mi farò dei denti nuovi, tutti d\'oro!', 'Mi farò dei denti nuovi, tutti d\'oro!', 28153),
(149800, 'itIT', 'Terremo sigillata la prigione di Mythrax e riuniremo la nostra gente.', '', 28153),
(149799, 'itIT', 'Stiamo facendo noi il lavoro sporco, dovremmo tenerci tutto il tesoro.', 'Stiamo facendo noi il lavoro sporco, dovremmo tenerci tutto il tesoro.', 28153),
(149798, 'itIT', 'No. Tu sei solo il nostro fallimento. Sethraliss si è sacrificata perché potessimo vivere in pace.', '', 28153),
(149797, 'itIT', 'Sono io il vero potere dei Sethrak!', '', 28153),
(149796, 'itIT', 'Sarà meglio che nessuno si porti via la mia parte.', 'Sarà meglio che nessuno si porti via la mia parte.', 28153),
(149795, 'itIT', 'Se lo trovo io, me la squaglio con tutto!', 'Se lo trovo io, me la squaglio con tutto!', 28153),
(149794, 'itIT', 'Daranno una parte in più a chiunque lo trovi per primo!', 'Daranno una parte in più a chiunque lo trovi per primo!', 28153),
(149793, 'itIT', 'Tre milioni di monete d\'oro... Saremo ricchi!', 'Tre milioni di monete d\'oro... Saremo ricchi!', 28153),
(149792, 'itIT', 'Forse stiamo scavando nel posto sbagliato?', 'Forse stiamo scavando nel posto sbagliato?', 28153),
(149791, 'itIT', 'Mi comprerò un castello, con un bagno caldo e dei servi.', 'Mi comprerò un castello, con un bagno caldo e dei servi.', 28153),
(149790, 'itIT', 'Nedly dice che ci stiamo avvicinando, ogni giorno è buono.', 'Nedly dice che ci stiamo avvicinando, ogni giorno è buono.', 28153),
(149789, 'itIT', 'Comprerò una barca più grossa di qualsiasi altra nella flotta!', 'Comprerò una barca più grossa di qualsiasi altra nella flotta!', 28153),
(149788, 'itIT', 'Quant\'è 1/267esimo di tre milioni?', 'Quant\'è 1/267esimo di tre milioni?', 28153),
(149787, 'itIT', 'È così tanto che Jaina Marefiero vorrà sposarmi per tutti i miei soldi!', 'È così tanto che Jaina Marefiero vorrà sposarmi per tutti i miei soldi!', 28153),
(149786, 'itIT', '', 'Be\', a volte capita anche quello.', 28153),
(149785, 'itIT', '', 'Per la prima volta proverà la sensazione del vento sotto le sue ali. La gioia del volo! La...', 28153),
(149784, 'itIT', '', 'Ah, un altro risponde al richiamo dei cieli!', 28153),
(149783, 'itIT', 'Torna presto. Dobbiamo colpire l\'Imperatore Korthek senza indugio.', '', 28153),
(149782, 'itIT', 'Io starò qui a predisporre l\'assalto mentre tu semini il caos tra i Senzafede.', '', 28153),
(149781, 'itIT', '<Spingi il cucciolo giù dal nido.>', '<Spingi il cucciolo giù dal nido.>', 28153),
(149779, 'itIT', '[Client Scene - Taelia steps up to accuse Lady Ashvane of being behind the attack. Don\'t you see, Katherine? Replacing you has been her plan all along. Katherine turns to Priscilla - is this true? Priscilla cuts the soft and sympathetic act. Goes hard against Katherine: Weak! Unfit to rule! Ashvane BUILT this city! Takes a shot at Katherine with her pistol. Guards jump into action. Priscilla shoots barrels on a wagon near the crowd, igniting a smokescreen that quickly envelops the plaza. Chaos ensues.]', '[Client Scene - Taelia steps up to accuse Lady Ashvane of being behind the attack. Don\'t you see, Katherine? Replacing you has been her plan all along. Katherine turns to Priscilla - is this true? Priscilla cuts the soft and sympathetic act. Goes hard against Katherine: Weak! Unfit to rule! Ashvane BUILT this city! Takes a shot at Katherine with her pistol. Guards jump into action. Priscilla shoots barrels on a wagon near the crowd, igniting a smokescreen that quickly envelops the plaza. Chaos ensues.]', 28153),
(149778, 'itIT', 'Vorrik, sono pronto ad affrontare l\'Imperatore Korthek!', 'Vorrik, sono pronta ad affrontare l\'Imperatore Korthek!', 28153),
(149777, 'itIT', '', 'Il bottino mio... nooo...', 28153),
(149776, 'itIT', 'Punite questo dannato vascello e liberate la nostra gente!', '', 28153),
(149775, 'itIT', '', 'Tieni proprio na bella arma, la voglio!', 28153),
(149774, 'itIT', 'Grandi tempeste del mare, ascoltate il mio richiamo!', '', 28153),
(149772, 'itIT', 'Notevole, \"amico mio\". Ma non basterà a fermarmi!', '', 28153),
(149771, 'itIT', 'La chiave è nelle profondità della mia fortezza, Vorrik. O credevi fossi così stupido da portarla con me?', '', 28153),
(149770, 'itIT', 'Però hai ragione su una cosa. Basta chiacchiere!', '', 28153),
(149769, 'itIT', 'Basta chiacchiere, amico mio. Dacci la tua chiave, o ci condannerai tutti!', '', 28153),
(149768, 'itIT', 'State affrontando il potente Korthek, l\'Imperatore Eterno!', '', 28153),
(149767, 'itIT', 'È fatta, posso assorbire il potere di questa guglia. Al cancello, presto!', '', 28153),
(149766, 'itIT', '', 'Per tutte le sabbie, che bello vederti! Ne ho fin sopra le orecchie...', 28153),
(149765, 'itIT', '', 'Kiro è difficile da individuare. È in continuo movimento, sempre a lavoro su qualche nuovo piano.\n\nL\'ultima volta che l\'ho sentito si stava dirigendo con Nisha nella gola per rubare rifornimenti, sabotare cannoni o cose del genere.', 28153),
(149764, 'itIT', '', 'Nisha sta causando problemi all\'accampamento di schiavi. Vai a ovest, fuori dalla caverna, e dirigiti giù lungo la prima rampa che trovi sulla destra.\n\nSe sei in dubbio, segui le urla dei Sethrak morenti: lei sarà certamente nelle vicinanze.', 28153),
(149763, 'itIT', '', 'Questa è la parte migliore! Probabilmente non li hai nemmeno visti mentre entravi, vero?\n\nDei Vulpera si stanno nascondendo lungo la via di fuga, per tenere d\'occhio i Senzafede!\n\nQuando confermeranno che la strada è sicura, prenderò la guida di un gruppo di Vulpera e raggiungerò le carovane, che penseranno a portarli al sicuro.\n\nPoi tornerò dentro e preparerò un altro gruppo. È molto eccitante e per ora ho pianto di paura soltanto tre volte!\n\nSe dovessi andartene, ti basterà uscire dalla caverna e dirigerti a ovest. Attraversa il ponte che porta alle rovine e sarai a casa.', 28153),
(149762, 'itIT', '', 'Ciò che ci fai tu, immagino. Guarda questi Vulpera... sono feriti e hanno bisogno di qualcuno che li aiuti.\n\nI Senzafede hanno schiavizzato molti di noi, costringendoci a lavorare e combattere per loro.\n\nNon siamo mai riusciti a fermarli prima d\'ora, ma Nisha e Kiro ci hanno dimostrato che possiamo affrontarli.\n\nDi notte, Kiro e gli altri si infiltrano nel campo di prigionia per salvare i Vulpera più indifesi.\n\nLi portano qui e io penso ad accompagnarli al sicuro attraverso le dune, dove abbiamo carovane in attesa che li portino in salvo.\n\nÈ pericoloso e preferirei di gran lunga restare all\'accampamento, ad ascoltare il dolce canto di Ahna accanto a un fuocherello. Ma come potrei farlo, sapendo che i miei amici hanno bisogno del mio aiuto?', 28153),
(149761, 'itIT', 'Ho altre domande da farti.', 'Ho altre domande da farti.', 28153),
(149760, 'itIT', 'Dov\'è Nisha?', 'Dov\'è Nisha?', 28153),
(149759, 'itIT', 'Dov\'è Kiro?', 'Dov\'è Kiro?', 28153),
(149758, 'itIT', 'Come fai a far scappare i prigionieri?', 'Come fai a far scappare i prigionieri?', 28153),
(149757, 'itIT', 'Che cosa ci fai qui?', 'Che cosa ci fai qui?', 28153),
(149756, 'itIT', '', '$p! Sapevo che saresti $gvenuto:venuta;! Gliel\'avevo detto, \"a $p stanno a cuore i Vulpera e non ci abbandonerebbe mai.\"\n\nAnch\'io sono qui per aiutare! Kiro e Nisha stanno salvando gli schiavi Vulpera e sto organizzando le carovane perché li portino via da qui.\n\nFa abbastanza paura trovarsi così vicini ai Sethrak, ma so che è la cosa giusta da fare. L\'ha detto Nisha.\n\nComunque, ti do il benvenuto nel nostro piccolo nascondiglio.', 28153),
(149755, 'itIT', 'Fai strada.', 'Fai strada.', 28153),
(149754, 'itIT', 'Se stai mentendo ti farò impiccare.', 'Se stai mentendo ti farò impiccare.', 28153),
(149753, 'itIT', 'Sono con te.', 'Sono con te.', 28153),
(149752, 'itIT', '', 'Le forze nostre faranno buon uso di questi rifornimenti. Ben fatto!', 28153),
(149751, 'itIT', '', 'Abbiamo trovato il relitto di na barca saccheggiata dai Troll del Sangue. Recupera il carico suo, prima che lo facciano loro!', 28153),
(149750, 'itIT', 'Meglio che sia una cosa importante.', 'Meglio che sia una cosa importante.', 28153),
(149749, 'itIT', 'Mmm. D\'accordo, andiamo.', 'Mmm. D\'accordo, andiamo.', 28153),
(149748, 'itIT', 'Cosa?!? Sarà meglio che tu abbia ragione...', 'Cosa?!? Sarà meglio che tu abbia ragione...', 28153),
(149747, 'itIT', 'Bene, $gmio giovane scudiero:mia giovane scudiera;, il nostro lavoro è finito. Se vuoi scusarmi, ho un Ettin da spacciare.', '', 28153),
(149746, 'itIT', 'Un bandito! Non temere, damigella, ti proteggerò io!', '', 28153),
(149745, 'itIT', 'Un Demone Astrale? Non me ne starò qui ad ascoltare mentre Scintillo Secondo viene insultato così! Preparati ad assaggiare il potere di Johnny... È un Ettin quello?', '', 28153),
(149744, 'itIT', 'Ho visto come hai sconfitto questo Demone Astrale! I miei complimenti per averlo spacciato con le tue mani! Ti ha forse arrecato ferite?', '', 28153),
(149743, 'itIT', '', 'La gente sta perdendo fiducia in Katherine...', 28153),
(149742, 'itIT', '', 'Grandioso... Forse ci toccherà fare una sceneggiata.', 28153),
(149741, 'itIT', '', 'Fase uno, scatenare una rivolta.', 28153),
(149740, 'itIT', 'Siete andati anche troppo oltre. Mythrax risorgerà e voi traditori perirete!', '', 28153),
(149739, 'itIT', 'Le chiavi saranno nostre... e Mythrax rinascerà!', '', 28153),
(149738, 'itIT', 'Scintillo Secondo... Perché non hai volato?', '', 28153),
(149737, 'itIT', 'Ora inizio e... puntuali come sempre, ecco le forze di Korthek!', '', 28153),
(149736, 'itIT', 'Sono pronto a difenderti dai Sethrak. Inizia pure il rituale.', 'Sono pronta a difenderti dai Sethrak. Inizia pure il rituale.', 28153),
(149735, 'itIT', 'Sei $gpronto:pronta;? Dobbiamo muoverci, le forze di Korthek cercheranno di impedirmi di assorbire il potere della guglia e dovrai difendermi mentre completo l\'incantesimo.', '', 28153),
(149730, 'itIT', 'Da dove sono spuntati tutti quei Fuochi Fatui?', '', 28153),
(149729, 'itIT', 'Argh! Quei dannati Fuochi Fatui pungono!', '', 28153),
(149726, 'itIT', 'Avete spazzato via una grande minaccia da Boralus, ma scommetto il mio grog che la città non è ancora fuori pericolo.', '', 28153),
(149725, 'itIT', 'Senza quel dannato codardo e i suoi capitani, questi pirati non saprebbero distinguere un tirante da una pompa di sentina!', '', 28153),
(149724, 'itIT', 'Harlan doveva aspettarsi che tradirmi avrebbe portato a questo.', '', 28153),
(149723, 'itIT', 'Ma questo non è assolutamente un problema per voi, vero?', '', 28153),
(149722, 'itIT', 'Eccetto la sua ciurma di efferati assassini e tagliagole, naturalmente.', '', 28153),
(149720, 'itIT', 'Io raggiungerò la guglia. Troviamoci lì. Le forze di Korthek cercheranno sicuramente di impedirci di assorbirne il potere.', '', 28153),
(149719, 'itIT', 'Dolce donzella, cosa ti turba? Maximillian della Contea del Nord è qui per prestarti aiuto!', '', 28153),
(149717, 'itIT', '', 'Nun avremmo mai trovato Rakera senza di te.', 28153),
(149716, 'itIT', 'Sembrava una damigella in cerca d\'aiuto. Con me, $gscudiero:scudiera;!', '', 28153),
(149715, 'itIT', 'Vedi, $gscudiero:scudiera;, i miei precedenti tentativi di spacciare questo Ettin hanno solo fatto sì che le mie lance si conficcassero nel suo fianco. Quindi, il tuo primo compito sarà...', '', 28153),
(149714, 'itIT', '', 'Ora siamo amici, giusto?', 28153),
(149713, 'itIT', '', 'Le rovine sono lungo la strada per Zem\'lan. Vi ci accompagno volentieri! Dolly e Dot sono di ottima compagnia, ma è bello avere qualcuno con cui parlare.', 28153),
(149712, 'itIT', 'Quindi, quella bolla... Oh! Non ti piace l\'acqua di mare? Che strano.', '', 28153),
(149711, 'itIT', 'NOOO! NON PUÒ ESSERE!!!', '', 28153),
(149710, 'itIT', 'Aspetta... cosa ci fanno i Vulpera qui?', '', 28153),
(149709, 'itIT', 'È abbandonato da anni, ma sarà il luogo ideale da dove lanciare il nostro...', '', 28153),
(149708, 'itIT', 'Il mio santuario personale era nascosto nelle colline, un piccolo altare dedicato a Sethraliss dove meditare.', '', 28153),
(149707, 'itIT', 'Allora, io e Korthek guidavamo il culto di Sethraliss insieme a tutti i Sethrak.', '', 28153),
(149706, 'itIT', 'Il sogno annegato mi consuma!', 'Il sogno annegato mi consuma!', 28153),
(149705, 'itIT', 'Anch\'io, molto tempo fa, ho vissuto qui, prima che Korthek tradisse la nostra gente per il potere e la follia.', '', 28153),
(149704, 'itIT', 'È un luogo crudele di roccia e terra, brulicante di Sethrak che hanno rinnegato il nostro Loa.', '', 28153),
(149703, 'itIT', 'Mi disseterò del Vuoto infinito.', 'Mi disseterò del Vuoto infinito.', 28153),
(149702, 'itIT', 'Ora vedo la verità.', 'Ora vedo la verità.', 28153),
(149701, 'itIT', 'Ci stiamo dirigendo nel cuore dell\'impero dei Senzafede.', '', 28153),
(149700, 'itIT', 'Il cerchio... Vedo il cerchio!', 'Sì... Il cerchio... Vedo il cerchio!', 28153),
(149699, 'itIT', 'L\'ombra inquieta giunge per me!', 'Oh... L\'ombra inquieta giunge per me!', 28153),
(149698, 'itIT', 'Sento la voce! Le mille verità!', 'Ah... Sento la voce! Le mille verità!', 28153),
(149697, 'itIT', 'Vivrò in eterno nell\'abisso.', 'Vivrò in eterno nell\'abisso.', 28153),
(149696, 'itIT', 'Finalmente! La strada che porta a Harlan Sweete è libera. Niente potrà fermarci.', '', 28153),
(149695, 'itIT', 'La mia anima per l\'Antico!', 'La mia anima per l\'Antico!', 28153),
(149694, 'itIT', '', 'Difenderemo la gente vostra come se fosse la nostra.', 28153),
(149693, 'itIT', 'Quindi, perché non sfruttiamo al meglio... le vostre doti da pugili?', '', 28153),
(149692, 'itIT', 'Quel marinaio d\'acqua dolce ha reso l\'isola inaccessibile fino alla fine delle feste alla fossa di combattimento.', '', 28153),
(149691, 'itIT', 'Nun tengo Sbocciapace per feccia come te, cane dell\'Alleanza!', 'Nun tengo Sbocciapace per feccia come te, cane dell\'Alleanza!', 28153),
(149690, 'itIT', 'Nun so nulla del Tram degli Abissi!', 'Nun so nulla del Tram degli Abissi!', 28153),
(149689, 'itIT', 'Ora non rimane che far conoscere alla gola di Harlan un po\' di freddo acciaio. Non sarà facile, però.', '', 28153),
(149688, 'itIT', 'I Lunagufo nun volano! Te ne devi andare!', 'I Lunagufo nun volano! Te ne devi andare!', 28153),
(149687, 'itIT', 'Nun sono na spia!', 'Nun sono na spia!', 28153),
(149686, 'itIT', 'I Murloc cosa a cosa? Nun tieni la capa a posto!', 'I Murloc cosa a cosa? Nun tieni la capa a posto!', 28153),
(149685, 'itIT', '\"Na bottiglia di sudore di Troll\"? Accà nun vendiamo chelle cose!', '\"Na bottiglia di sudore di Troll\"? Accà nun vendiamo chelle cose!', 28153),
(149684, 'itIT', 'Li alberi sono belli, ma il fuoco è pericoloso, nun trovi?', 'Li alberi sono belli, ma il fuoco è pericoloso, nun trovi?', 28153),
(149683, 'itIT', 'Zandalar per sempre!', 'Zandalar per sempre!', 28153),
(149682, 'itIT', '', 'Qualcosa nun va in chesto tempio. Dobbiamo trovare nu modo per entrarci.', 28153),
(149681, 'itIT', 'Se non fossi così nobile d\'animo, saresti un pirata eccezionale.', '', 28153),
(149680, 'itIT', 'Dormo... solo... per svegliarmi...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149679, 'itIT', 'Davvero... grandioso, Maximillian. Io me ne vado.', 'Davvero... grandioso, Maximillian. Io me ne vado.', 28153),
(149678, 'itIT', 'L\'ombra infinita... mi accoglie...', '', 28153),
(149677, 'itIT', 'Non hai... speranza...', '', 28153),
(149676, 'itIT', 'Uh... Cosa?', 'Uh... Cosa?', 28153),
(149675, 'itIT', 'Il seme... attecchisce...', '', 28153),
(149674, 'itIT', 'Sono solo uno... di molti...', '', 28153),
(149673, 'itIT', 'Il ciclo... continua...', '', 28153),
(149672, 'itIT', 'Persino la morte... può... morire...', '', 28153),
(149671, 'itIT', 'Alla fine... conoscerai la verità...', '', 28153),
(149670, 'itIT', 'Hai sentito? I Cancelli di Daelin sono caduti!', 'Hai sentito? I Cancelli di Daelin sono caduti!', 28153),
(149669, 'itIT', 'Che ne pensi di tutto questo?', 'Che ne pensi di tutto questo?', 28153),
(149668, 'itIT', 'Le correnti ti trascineranno nell\'abisso.', '', 28153),
(149667, 'itIT', 'A me, me fa veni\' voglia di tornare ai vecchi metodi miei.', '', 28153),
(149666, 'itIT', 'I Filibustieri Dentineri adorano fare a pugni in un buon combattimento. Se riuscirete a tener loro testa, il Capitano Raoul vi farà sicuramente partecipare all\'incontro.', '', 28153),
(149665, 'itIT', 'Che è chel rumore che esce dalla bocca tua?', '', 28153),
(149664, 'itIT', 'Nemmeno i pesci bevono quanto i Ratti di Sentina! Se riuscirete a tenere loro testa, il Capitano Eudora non potrà far altro che invitarvi all\'incontro.', '', 28153),
(149663, 'itIT', 'Cos\'hai sentito dire sull\'attacco?', 'Cos\'hai sentito dire sull\'attacco?', 28153),
(149662, 'itIT', 'Che nessuno dica che non ho fatto nulla in questa guerra. Ecco il mio rapporto.', 'Che nessuno dica che non ho fatto nulla in questa guerra. Ecco il mio rapporto.', 28153),
(149661, 'itIT', '', 'Va bene, allora. Dot e Dolly sono i miei migliori amici. La mia carovana conducono felici!', 28153),
(149660, 'itIT', 'Non so... le cose peggiorano di giorno in giorno. Forse è ora che Katherine lasci il posto.', 'Non so... le cose peggiorano di giorno in giorno. Forse è ora che Katherine lasci il posto.', 28153),
(149659, 'itIT', 'Non deluderò l\'Alleanza. Anche se ho dovuto starmene in mezzo al fango per tre giorni. Ecco, tieni il mio rapporto.', 'Non deluderò l\'Alleanza. Anche se ho dovuto starmene in mezzo al fango per tre giorni. Ecco, tieni il mio rapporto.', 28153),
(149658, 'itIT', '', 'A Dot e Dolly piace quando canto. Li calma.', 28153),
(149657, 'itIT', 'Ma com\'è possibile che la gente creda che i Troll e gli Elfi della Notte siano imparentati? Che terribile esperienza. Ecco il mio rapporto.', 'Ma com\'è possibile che la gente creda che i Troll e gli Elfi della Notte siano imparentati? Che terribile esperienza. Ecco il mio rapporto.', 28153),
(149656, 'itIT', 'Ottenere un invito vi renderà le cose più facili. Oppure potete provare a uccidere tre dei pirati più temibili al mondo, tutti assieme. Decidete voi.', '', 28153),
(149655, 'itIT', '', 'Dolly e Dot sono i miei migliori amici. La mia carovana conducono felici! Han dei bei dentini e adorano mangiar...', 28153),
(149654, 'itIT', 'Ho detto che avrei fatto qualsiasi cosa per vendicare Teldrassil. Far finta di essere un Troll, evidentemente, era compreso nel pacchetto. Ecco il mio rapporto.', 'Ho detto che avrei fatto qualsiasi cosa per vendicare Teldrassil. Far finta di essere un Troll, evidentemente, era compreso nel pacchetto. Ecco il mio rapporto.', 28153),
(149653, 'itIT', 'Fonti attendibili riferiscono che i capitani stanno per incontrarsi. Se riuscissimo a partecipare alla festa, potremmo prendere molti piccioni con una fava.', '', 28153),
(149652, 'itIT', 'Dov\'è il mio pterrordattilo?', 'Dov\'è il mio pterrordattilo?', 28153),
(149651, 'itIT', 'Che succede al mio cucciolo?', 'Che succede al mio cucciolo?', 28153),
(149650, 'itIT', 'Solo una piccola scampagnata nella giungla, dicevano. Sarà facile, dicevano. Bah, prendi il rapporto.', 'Solo una piccola scampagnata nella giungla, dicevano. Sarà facile, dicevano. Bah, prendi il rapporto.', 28153),
(149649, 'itIT', 'Perché fa quel rumore?', 'Perché fa quel rumore?', 28153),
(149648, 'itIT', 'Selvaggi. Dei completi selvaggi. Ecco, prendi il mio rapporto.', 'Selvaggi. Dei completi selvaggi. Ecco, prendi il mio rapporto.', 28153),
(149647, 'itIT', 'Non chiedermi dove ho dovuto dormire la notte scorsa. Ecco il tuo rapporto.', 'Non chiedermi dove ho dovuto dormire la notte scorsa. Ecco il tuo rapporto.', 28153),
(149646, 'itIT', 'Grazie.', 'Grazie.', 28153),
(149645, 'itIT', 'Io ho delineato il quadro generale, lascerò a voi i dettagli dell\'operazione.', '', 28153),
(149644, 'itIT', 'Dopodiché, Harlan avrà ciò che si merita.', '', 28153),
(149643, 'itIT', 'Annegherai nel sangue dell\'infinito.', '', 28153),
(149642, 'itIT', 'Ecco il piano. Sbaragliamo gli Sferzamaree, sfondiamo i Ratti di Sentina, sgominiamo i Dentineri e schiacciamo i Marferreo.', '', 28153),
(149641, 'itIT', 'Se ce la farà, sarà a capo di una flotta in grado di minacciare l\'intera regione.', '', 28153),
(149640, 'itIT', 'Credevo di aver sentito delli strilli, ma nun posso abbandonare i nidi per andare a controllare.$b$bFai in fretta, o potresti nun tenere più no pterrordattilo di cui prenderti cura. Nun tutti arrivano vivi alla maturità.', '', 28153),
(149639, 'itIT', 'Harlan Sweete sta sfruttando i Marferreo per unire le altre ciurme sotto il suo vessillo.', '', 28153),
(149638, 'itIT', 'Oh, è scappato. Si annoiava, probabilmente.$b$bDovresti andare a cercarlo, prima che si faccia male. Nun è ancora in grado di difendersi da solo.', '', 28153),
(149637, 'itIT', 'Sembra nu po\' triste, nun trovi?$b$bSicuramente gli manca la ma\'ma sua. Ehi, sei tu, giusto?', '', 28153),
(149636, 'itIT', 'La tua anima conoscerà solo la fame.', '', 28153),
(149635, 'itIT', 'Anche le stelle temono la nostra ascesa.', '', 28153),
(149634, 'itIT', 'Chel rumore che fa significa che tiene fame.$b$bNutrilo, prima che ti stacchi nu dito dalla fame.$b$bSe nun tieni nulla da dargli, puoi comprare qualcosa al Kraal delle Bestie da Guerra.', '', 28153),
(149633, 'itIT', 'Conoscerai l\'abbraccio del vero nulla.', '', 28153),
(149632, 'itIT', 'Dormirai un sonno eterno a Ny\'alotha.', '', 28153),
(149631, 'itIT', 'La Luce muore negli abissi infiniti.', '', 28153),
(149630, 'itIT', 'Sono la Pterrorbalia Goja. Pa\'ku è la Loa mia e servo la Signora dei Venti prendendomi cura dei piccirilli suoi.$b$bMi ha detto che potresti tenere bisogno dell\'aiuto mio.$b$b<La Pterrorbalia Goja ridacchia.>$B$BChe ti serve?', '', 28153),
(149629, 'itIT', 'Ammira l\'ombra della tua dipartita.', '', 28153),
(149628, 'itIT', 'Ho sentito che erano pirati. Riesci a crederci? Dei rozzi, scorbutici PIRATI! I Marefiero sono ancora in grado di proteggerci?', 'Ho sentito che erano pirati. Riesci a crederci? Dei rozzi, scorbutici PIRATI! I Marefiero sono ancora in grado di proteggerci?', 28153),
(149627, 'itIT', 'Ah! $gMio fedele scudiero:Mia fedele scudiera;! Il tuo arrivo è sempre d\'uopo.\n\nSono venuto a Kul Tiras con speme di trovar cittadini in periglio cui prestare aiuto. Il mio compito è salvare i pescatori di questo tranquillo villaggio dagli Ettin che recano loro sì tanto patimento.\n\nHanno una pelle straordinariamente spessa.', '', 28153),
(149626, 'itIT', 'Sì, tu e tutti gli altri. Rimanete in riga e cercare di non combinare casini. La folla è già abbastanza nervosa.', 'Sì, tu e tutti gli altri. Rimanete in riga e cercare di non combinare casini. La folla è già abbastanza nervosa.', 28153),
(149625, 'itIT', 'Devo parlare immediatamente con Katherine Marefiero.', 'Devo parlare immediatamente con Katherine Marefiero.', 28153),
(149624, 'itIT', 'L\'Ammiraglio Supremo Marefiero si sta preparando a parlare al pubblico. Abbiate pazienza.', 'L\'Ammiraglio Supremo Marefiero si sta preparando a parlare al pubblico. Abbiate pazienza.', 28153),
(149623, 'itIT', 'L\'Ammiraglio Supremo è in pericolo. Vieni con noi!', 'L\'Ammiraglio Supremo è in pericolo. Vieni con noi!', 28153),
(149622, 'itIT', 'Vi prego, rimanete calmi. È tutto sotto controllo.', 'Vi prego, rimanete calmi. È tutto sotto controllo.', 28153),
(149621, 'itIT', 'A Nedly Grinner non piace essere scavalcato. Nessuno troverà quel tesoro prima di me!', '', 28153),
(149620, 'itIT', 'Non perdere tempo.\n\nCerca di fregarmi e ti spedirò dai lealisti.', '', 28153),
(149619, 'itIT', 'Questo Sangue di Marea è stato corrotto di recente. Dovrei riuscire a purificarlo.', '', 28153),
(149618, 'itIT', 'Ah! È più instabile di quanto pensassi.', '', 28153),
(149617, 'itIT', 'Oh salve!\n\nHai seguito le mie gesta eroiche nella speranza di divenir $glo scudiero:la scudiera; di Maximillian della Contea del Nord?\n\nAbbandona la tua speme, poiché oggi divien certezza! Ho bisogno di qualcuno che mi assista mentre affronto perigliosi nemici.', '', 28153),
(149616, 'itIT', '', 'La troverò, o schiatterò provandoci.', 28153),
(149615, 'itIT', '', 'Il Porto di Zem\'lan è a sud. Le navi non attraccano al suo molo da anni. Ma è ancora la nostra migliore possibilità di trovare ciò che serve a Kiro e Nisha per l\'attacco ai Sethrak.', 28153),
(149614, 'itIT', '', 'Tieni gli occhi aperti per la tua amica, io terrò lo sguardo sulla strada.', 28153),
(149613, 'itIT', '', 'Qui la battaglia è finita, ma... Tul non è morto. È ferito e sconfitto, ma non è morto!', 28153),
(149612, 'itIT', '', 'Si narra che Ser Arom abbia ucciso Gorak Tul e che assieme a lui cadde anche la sua armata. Qui puoi vedere i suoi costrutti che si sgretolano nel momento in cui viene infilzato e perde il suo potere. Insomma, sembra che ci fosse un legame.', 28153),
(149611, 'itIT', '', 'Quello è Ser Arom Crestabianca quando era ancora Colonnello e guidava l\'attacco finale. E là... c\'è Gorak Tul mentre viene infilzato da Ser Arom.', 28153),
(149610, 'itIT', '', 'Questo non è Drust. Sono incisioni di Kul Tiras su un Monolito Drust.', 28153),
(149609, 'itIT', '', 'Interessante. Non sapevo che i costrutti fossero stati creati in seguito a causa della sua brama di vittoria.', 28153),
(149608, 'itIT', 'Zuq yoh\'ghyl ma oou shandai nuq Ez iilth thyzz.', '', 28153),
(149607, 'itIT', 'Fhssh zzof og far\'al awtgsshu.', '', 28153),
(149606, 'itIT', '', 'Ben fatto! hai donato nu po\' di tregua alla prole di Krag\'wa. Grazie.', 28153),
(149605, 'itIT', '<Kua\'fon gracchia di gioia e ingoia il boccone.>', '', 28153),
(149604, 'itIT', '<Kua\'fon annusa il cibo prima di divorarlo con gusto.>', '', 28153),
(149603, 'itIT', '<Kua\'fon afferra il cibo al volo.>', '', 28153),
(149602, 'itIT', '<Kua\'fon si getta verso il cibo offerto e lo ingoia intero.>', '', 28153),
(149601, 'itIT', '', 'I Troll del Sangue sono tornati a cacciare la stirpe di Krag\'wa. Il cuore del Signore delle Rane ribolle d\'ira. Aiutalo nella vendetta sua!', 28153),
(149600, 'itIT', 'Nel nome dei Sacraonda!', 'Nel nome dei Sacraonda!', 28153),
(149599, 'itIT', 'Questa valle è nostra, verme!', 'Questa valle è nostra, verme!', 28153),
(149598, 'itIT', 'Kul Tiras non vale nulla senza di noi!', 'Kul Tiras non vale nulla senza di noi!', 28153),
(149597, 'itIT', 'La nostra flotta ti schiaccerà!', 'La nostra flotta ti schiaccerà!', 28153),
(149596, 'itIT', 'Tutti coloro che ci ostacolano moriranno!', 'Tutti coloro che ci ostacolano moriranno!', 28153),
(149595, 'itIT', 'Siamo implacabili come le profondità!', 'Siamo implacabili come gli abissi!', 28153),
(149594, 'itIT', 'Come osi opporti alla Casata dei Sacraonda?', 'Come osi opporti alla Casata dei Sacraonda?', 28153),
(149593, 'itIT', 'Kul Tiras appartiene all\'oceano!', 'Kul Tiras appartiene all\'oceano!', 28153),
(149592, 'itIT', 'La mia vita... per il mare...', 'La mia vita... per il mare...', 28153),
(149591, 'itIT', 'Saggi delle Maree... beneditemi...', 'Saggi delle Maree... beneditemi...', 28153),
(149590, 'itIT', 'Stavo solo... eseguendo gli ordini...', 'Stavo solo... eseguendo gli ordini...', 28153),
(149589, 'itIT', 'Abbiamo... già vinto...', 'Abbiamo... già vinto...', 28153),
(149588, 'itIT', 'La mia morte... non fermerà nulla...', 'La mia morte... non fermerà nulla...', 28153),
(149587, 'itIT', 'Noi non ci fermeremo... mai...', 'Noi non ci fermeremo... mai...', 28153),
(149586, 'itIT', 'Sanguino... la linfa della marea...', 'Il mio sangue... alimenterà... la marea...', 28153),
(149585, 'itIT', 'Ho visto la verità... negli abissi...', 'Ho visto la verità... negli abissi...', 28153),
(149584, 'itIT', 'Non hai idea di quanto sia dura. Ecco il tuo rapporto.', 'Non hai idea di quanto sia dura. Ecco il tuo rapporto.', 28153),
(149583, 'itIT', '', 'Oh, idioti... Se non altro ora sappiamo quanto siano pericolosi i Fuochi Fatui.', 28153),
(149582, 'itIT', '', 'Non avrai dove fuggire al nostro prossimo incontro, Malfurion!', 28153),
(149581, 'itIT', 'Non farai un altro passo, Regina Banshee!', '', 28153),
(149580, 'itIT', '<Kua\'fon riposa con la testa sotto le sue ali, gemendo dolcemente.>', '', 28153),
(149579, 'itIT', '', 'È ora di accoltellare!', 28153),
(149577, 'itIT', 'Fagliela pagare, $p.', '', 28153),
(149575, 'itIT', '', 'Cosa ti aspettavi? È appena nato. Deve nutrirsi. Vai a chiedere al Kraal della carne.', 28153),
(149574, 'itIT', 'Hai invocato il tuono!', '', 28153),
(149573, 'itIT', '', 'Riesco a sentirlo. Il piccolino ha dei bei polmoni.\n\nPerché hai così paura?', 28153),
(149571, 'itIT', '<Ti guarda con sguardo fisso.>', '<Ti guarda con sguardo fisso.>', 28153),
(149570, 'itIT', 'Io nun dico niente.', 'Io nun dico niente.', 28153),
(149569, 'itIT', 'Tieni na moneta da darmi?', 'Tieni na moneta da darmi?', 28153),
(149568, 'itIT', 'Tu sì che sei nu Troll dall\'aspetto strano.', 'Tu sì che sei nu Troll dall\'aspetto strano.', 28153),
(149567, 'itIT', 'Che c\'è?!?', 'Che c\'è?!?', 28153),
(149566, 'itIT', 'Mi stai bloccando la vista.', 'Mi stai bloccando la vista.', 28153),
(149565, 'itIT', '<Rutta.>', '<Rutta.>', 28153),
(149564, 'itIT', '<Pronuncia la frase in codice.>', '<Pronuncia la frase in codice.>', 28153),
(149563, 'itIT', 'Che vuoi?', 'Che vuoi?', 28153),
(149562, 'itIT', 'La Zuppa di Tartaruga non è neanche lontanamente comparabile alla zuppa di $R.\n\nTrovami la Carne di Verme del Fango e lascia stare le tartarughe.\n\nVieni a trovarmi un giorno, così esploreremo nuove zuppe insieme!', '', 28153),
(149561, 'itIT', 'Zuppa di Tartaruga?', 'Zuppa di Tartaruga?', 28153),
(149560, 'itIT', 'PER SETHRALISS!', '', 28153),
(149559, 'itIT', 'I Senzafede bloccano il passaggio verso l\'Imperatore Korthek. Dobbiamo distruggere quella barriera!', '', 28153),
(149558, 'itIT', 'Bene, ascoltate! Margie è in cerca di aiuto giù all\'Officina per delle parti di un... insomma, di qualcosa! Non sono affari di mia competenza, va bene?', '', 28153),
(149557, 'itIT', 'Eccellente. Queste informazioni saranno di vitale importanza. E... no, non ho idea di chi abbia ideato la frase segreta questa volta.', '', 28153),
(149556, 'itIT', 'Le nostre spie si sono infiltrate nella capitale degli Zandalari, ma dobbiamo recuperare i loro rapporti. Parla con i nomadi. Chi lavora per noi risponderà alla frase segreta.', '', 28153),
(149555, 'itIT', 'Ci sono degli Ogre nei pressi della nostra base e non sembrano contenti. Signore e signori, alle armi!', '', 28153),
(149554, 'itIT', 'Troverai solo Akunda accà. Solo coloro che ne condividono il nome possono entrare nella sala sua.', '', 28153),
(149553, 'itIT', 'Stai cercando redenzione? Akunda accoglie tutti.', '', 28153),
(149552, 'itIT', '', 'Stiamo cercando n\'esiliata di nome Rakera. Crediamo possa trovarsi in chesto tempio.', 28153),
(149551, 'itIT', '', 'Andrò per prima, in caso ci fosse dell\'oro.', 28153),
(149550, 'itIT', '', 'Quando arrivammo qui, volevamo la pace, ma i Drust ci dichiararono subito guerra. Pochi di loro ci tolleravano.', 28153),
(149549, 'itIT', '', 'Aspetta, qui è raffigurato uno dei primi insediamenti di Kul Tiras. Uno degli insediamenti perduti.', 28153),
(149548, 'itIT', 'Parlerò con Maokka.', 'Parlerò con Maokka.', 28153),
(149547, 'itIT', 'Bene, siamo tutti qui.', '', 28153),
(149545, 'itIT', 'Salve, cumpà.', '', 28153),
(149544, 'itIT', '', 'Ci vediamo ancora una volta.', 28153),
(149543, 'itIT', '', 'Questo mondo non può sopravvivere alla distruzione che scatenerà Mythrax.', 28153),
(149542, 'itIT', 'Lascialo perdere, Taelia!', '', 28153),
(149541, 'itIT', '', 'Sam, no!', 28153),
(149540, 'itIT', 'Per gli Addington! Per la Valle dei Sacraonda!', '', 28153),
(149539, 'itIT', 'Quei maledetti la pagheranno per ciò che hanno fatto.', '', 28153),
(149538, 'itIT', '', 'Jakra\'zet meritava il destino suo.', 28153),
(149537, 'itIT', 'Siamo al tuo fianco. Per i Destatempesta!', '', 28153),
(149535, 'itIT', '', 'Mi sono presa la libertà di metterti insieme una squadra. Recupera il mio trofeo.', 28153),
(149533, 'itIT', 'Altri che hanno abbandonato il mio ordine. Bene, forse non è tutto perduto.', '', 28153),
(149532, 'itIT', 'Se camminano tra noi, la flotta è in grave pericolo.', '', 28153),
(149531, 'itIT', 'In molti pensano siano solo leggende, storie nate per metterci in guardia dall\'osare troppo con la nostra magia.', '', 28153),
(149530, 'itIT', 'Quei... cosi... sono K\'thir. Provengono dagli angoli più oscuri degli abissi.', '', 28153),
(149529, 'itIT', '', '', 28153),
(149528, 'itIT', 'Che cosa intendi chiedermi, Capoguerra?', 'Che cosa intendi chiedermi, Capoguerra?', 28153),
(149527, 'itIT', '', 'Baine, richiama le truppe!', 28153),
(149526, 'itIT', '', 'Userai il Designatore Telecomandato per muovere Earl-E. Mandalo vicino ai disturbi nel terreno e attirerà in superficie i vermi!', 28153),
(149525, 'itIT', 'Abbiamo cercato di difenderci da essi, di resistere, ma temo sia stato un fallimento.', '', 28153),
(149523, 'itIT', 'Col tempo, quei sussurri... sono cambiati. A volte sembravano persino violenti.', '', 28153),
(149522, 'itIT', 'Il mio ordine ha ascoltato a lungo il mare in cerca di guida per le navi e il popolo. Sussurri delicati, impercettibili per molti.', '', 28153),
(149521, 'itIT', 'Qui vicino c\'è un ponte che ha una visuale diretta sul Santuario della Tempesta. Il presagio proviene da lì.', '', 28153),
(149520, 'itIT', 'Mi divertirò a farti a pezzi.', '', 28153),
(149519, 'itIT', '', 'Fai attenzione con quella cosa, a meno che tu non intenda affrontare un po\' di quei buoni a nulla. In tal caso... lavali col fuoco!', 28153),
(149518, 'itIT', 'Folle. Mo\' ti accido.', '', 28153),
(149517, 'itIT', 'Chesti prigionieri appartengono alli Zandalari!', '', 28153),
(149516, 'itIT', 'Ahahah!', '', 28153),
(149515, 'itIT', 'Mo\' schiatti!', '', 28153),
(149514, 'itIT', 'Debole Alleanza.', '', 28153),
(149513, 'itIT', 'Io schiacciare te!', '', 28153),
(149512, 'itIT', 'Vuoi andare dall\'Interrogatore?', '', 28153),
(149511, 'itIT', 'Carne fresca!', '', 28153),
(149510, 'itIT', 'Quella cosa è... sicura? Sono disposto a rischiare!', 'Quella cosa è... sicura? Sono disposta a rischiare!', 28153),
(149509, 'itIT', 'Fatemi uscire da qui!', 'Fatemi uscire da qui!', 28153),
(149508, 'itIT', 'Madre delle Maree... cosa siamo diventati?', '', 28153),
(149507, 'itIT', 'Il tuo tempismo è impeccabile!', 'Il tuo tempismo è impeccabile!', 28153),
(149506, 'itIT', 'Quella è... una trivella?', 'Quella è... una trivella?', 28153),
(149505, 'itIT', 'Ho paura di andare sotto terra... ma ho ancora più paura di questi Troll!', 'Ho paura di andare sotto terra... ma ho ancora più paura di questi Troll!', 28153),
(149504, 'itIT', 'Grazie, grazie!', 'Grazie, grazie!', 28153),
(149503, 'itIT', 'Sei $garrivato:arrivata; giusto in tempo!', 'Sei $garrivato:arrivata; giusto in tempo!', 28153),
(149502, 'itIT', 'Pensavo volessero mangiarmi!', 'Pensavo volessero mangiarmi!', 28153),
(149501, 'itIT', 'Comandante, la Capoguerra ha richiesto di preparare l\'avamposto per l\'arrivo di un\'armata.', 'Comandante, la Capoguerra ha richiesto di preparare l\'avamposto per l\'arrivo di un\'armata.', 28153),
(149500, 'itIT', 'Dobbiamo far spazio per l\'arrivo della flotta della Capoguerra. Puoi liberare i moli?', 'Dobbiamo far spazio per l\'arrivo della flotta della Capoguerra. Puoi liberare i moli?', 28153),
(149499, 'itIT', 'La Capoguerra ha bisogno di razioni e alloggi per l\'arrivo di un\'armata.', 'La Capoguerra ha bisogno di razioni e alloggi per l\'arrivo di un\'armata.', 28153),
(149498, 'itIT', 'Duecento soldati al fianco della Capoguerra, hai detto? Preparerò l\'avamposto per il suo arrivo.', '', 28153),
(149497, 'itIT', 'Qualsiasi cosa per la Capoguerra. Radunerò le guardie per liberare i moli immediatamente. Lok\'tar.', '', 28153),
(149496, 'itIT', '', 'La Capoguerra ha bisogno di alloggi e cibo per la sua armata? Le nostre riserve dovrebbero bastare, la primavera ha dato buoni frutti e l\'inverno mite ha aiutato molto.', 28153),
(149495, 'itIT', 'Sta uccidendo le sue stesse truppe...', '', 28153),
(149494, 'itIT', 'Lasciate che vi aiuti. So cosa lo affligge.', '', 28153),
(149493, 'itIT', 'Rimandami a Roccavento. (Riavvio scenario)', 'Rimandami a Roccavento. (Riavvio scenario)', 28153),
(149492, 'itIT', 'Mandami a Zuldazar. (Salta introduzione scenario)', 'Mandami a Zuldazar. (Salta introduzione scenario)', 28153),
(149491, 'itIT', '', 'Troppe navi della nostra flotta sono state distrutte dalla Legione o dall\'Alleanza. Sto facendo lavorare i nostri armatori giorno e notte, ma ce ne servono altre.', 28153),
(149490, 'itIT', 'Fermati.', '', 28153),
(149489, 'itIT', 'Io parlo... per G\'huun. Lui... guiderà. Tu... servirai... o morirai.', '', 28153),
(149488, 'itIT', 'Vieni.', '', 28153),
(149487, 'itIT', 'Il guscio del Loa... mi nutre. Nutre... G\'huun.', '', 28153),
(149486, 'itIT', 'Proverai... a fermare G\'huun. Fallirai... e soffrirai.', '', 28153),
(149485, 'itIT', 'Sì... combatti... resisti... G\'huun ha fame... della tua... sofferenza.', '', 28153),
(149484, 'itIT', 'I tuoi sforzi... sono inutili. Io sono... intoccabile.', '', 28153),
(149483, 'itIT', 'I vostri sforzi... sono inutili. Io sono... intocc... cosa? No. NO!', '', 28153),
(149482, 'itIT', 'Questo... non significa... NULLA! Otterrà... un nuovo... ricettacolo. I sigilli... saranno spezzati... G\'huun... sarà libero!', '', 28153),
(149481, 'itIT', 'Aspetta... questo proviene dalla cantina?', '', 28153),
(149480, 'itIT', '', 'Buona fortuna.', 28153),
(149479, 'itIT', '', 'La pattuglia è appena passata. Ora dovrebbe essere sicuro attraversare.', 28153),
(149478, 'itIT', '', '', 28153),
(149477, 'itIT', '', 'I Senzafede non sapranno cosa li ha colpiti.', 28153),
(149476, 'itIT', '', '', 28153),
(149475, 'itIT', '<Il ragazzino scappa via ridacchiando mentre lo insegui.>', '<La ragazzina scappa via ridacchiando mentre la insegui.>', 28153),
(149474, 'itIT', '|TInterface\\Icons\\SPELL_NATURE_EARTHQUAKE:20|t %s prende di mira |cFFFF0000$n|r con |cFFFF0000|Hspell:257617|h[Rivolta]|h|r! Sparpagliatevi!', '', 28153),
(149473, 'itIT', 'Stavo pensando che potremmo eliminare gli pterrordattili da na posizione rialzata, come chella collina, ma finiremmo per essere pigliati uno a uno come nulla fosse.', 'Stavo pensando che potremmo eliminare gli pterrordattili da na posizione rialzata, come chella collina, ma finiremmo per essere pigliati uno a uno come nulla fosse.', 28153),
(149472, 'itIT', 'Nessuna offesa.', '', 28153),
(149471, 'itIT', '', 'Non mi piace fare discorsi, quindi sarò breve: grazie. Troverai sempre degli alleati nella Valle dei Sacraonda.', 28153),
(149470, 'itIT', '', 'Senza offesa, Calvin.', 28153),
(149469, 'itIT', '', 'Hai scacciato i Verrospino oltre le fattorie, fino alla loro tana, salvando nel frattempo anche gli abitanti e i contadini... Hai fatto ben più di quanto la milizia avrebbe mai potuto... o voluto.', 28153),
(149468, 'itIT', '', 'Ti risparmio i complimenti. Non sono mai stata brava a esprimerli.', 28153),
(149466, 'itIT', 'Gli Zandalari trasportano i loro prigionieri via nave. Non possiamo lasciare che la cosa continui! Usa la Trivella dei Ferroscuro per salvarli dalla tortura e dalla morte.', '', 28153),
(149465, 'itIT', '', 'Dobbiamo rubare i piani d\'attacco nelle mani di Kiro. Non c\'è tempo da perdere. Andiamo!', 28153),
(149464, 'itIT', '', 'Ha ragione, Ser Arom Crestabianca deve il titolo alla sua vittoria qui.', 28153),
(149463, 'itIT', '', 'Be\'... Se seguiamo gli ordini, nessuno di questi mostri arriverà al Presidio di Arom. Aiutiamoli.', 28153),
(149462, 'itIT', '', 'Pensa che facciamo parte della sua milizia...', 28153),
(149461, 'itIT', '', 'I sacrifici di sangue devono finire! Chisto nun è che nu passo avanti per riuscire a fermare il Dio del Sangue.', 28153),
(149460, 'itIT', '', 'I rituali oscuri di Zul\'nazman hanno diffuso la corruzione loro sulla terra, richiamando li spiriti dalla morte! Purifica i resti loro e fa\' che trovino la pace!', 28153),
(149459, 'itIT', 'Dio... del Sangue... argh!', 'Dio... del Sangue... argh!', 28153),
(149458, 'itIT', 'Troviamoci ad Atul\'aman. Le altre ci stanno aspettando all\'interno.', '', 28153),
(149457, 'itIT', 'Ci sta chiamando...', 'Ci sta chiamando...', 28153),
(149456, 'itIT', 'Alcuni dei nostri Cavalieri del Vento sono nei guai. Pattuglia il campo di battaglia in cerca di sopravvissuti!', '', 28153),
(149455, 'itIT', 'Lasciami stare!', 'Lasciami stare!', 28153),
(149454, 'itIT', 'No no no no!', 'No no no no!', 28153),
(149453, 'itIT', 'Esci dalla capa mia!', 'Esci dalla capa mia!', 28153),
(149452, 'itIT', 'Argh!', 'Argh!', 28153),
(149451, 'itIT', 'Basta!', 'Basta!', 28153),
(149450, 'itIT', 'Speravo che i Senzafede accettassero la pace, ma le loro continue aggressioni ci hanno fatto forzare la mano.\n\nElimineremo l\'Imperatore Korthek... e ci prenderemo ogni cosa di utile lungo la strada.', '', 28153),
(149449, 'itIT', '', '|TInterface\\Icons\\SPELL_MAGE_FLAMEORB:20|t Sposta velocemente i Barili di Munizioni lontano dalle fiamme per evitare che %s li faccia esplodere!', 28153),
(149448, 'itIT', 'Avanguardia! Pronti a dare supporto al Colonnello Crestabianca!', 'Avanguardia! Pronti a dare supporto al Colonnello Arom!', 28153),
(149447, 'itIT', 'Per Drustvar e Kul Tiras!', 'Per Drustvar e Kul Tiras!', 28153),
(149446, 'itIT', 'Hanno preso i nostri figli! Fategliela pagare!', 'Hanno preso i nostri figli! Fategliela pagare!', 28153),
(149445, 'itIT', 'È ora di rendere orgogliosi i vostri antenati!', 'È ora di rendere orgogliosi i vostri antenati!', 28153),
(149444, 'itIT', 'Li abbiamo respinti! Continuate!', 'Li abbiamo respinti! Continuate!', 28153),
(149443, 'itIT', 'Rimanete saldi!', 'Rimanete saldi!', 28153),
(149442, 'itIT', 'Abbiamo respinto il nemico!\n\nNon startene lì, vai a combattere!', 'Abbiamo respinto il nemico!\n\nNon startene lì, vai a combattere!', 28153),
(149441, 'itIT', 'Una Nube Minacciosa inizia a ribollire toccando $n!', 'Una Nube Minacciosa inizia a ribollire toccando $n!', 28153),
(149440, 'itIT', 'Grazie...', 'Grazie...', 28153),
(149439, 'itIT', 'Finalmente... posso riposare...', 'Finalmente... posso riposare...', 28153),
(149438, 'itIT', 'La mia guardia si è conclusa...', 'La mia guardia si è conclusa...', 28153),
(149437, 'itIT', 'Ritorno... alla pace...', 'Ritorno... alla pace...', 28153),
(149436, 'itIT', 'Il mio dovere è compiuto...', 'Il mio dovere è compiuto...', 28153),
(149435, 'itIT', 'Ti troverò la carne.', 'Ti troverò la carne.', 28153),
(149434, 'itIT', 'La scatola è mia, ficcanaso di $gun:una; $R.\n\nHo bisogno di Vermi del Fango per fare la mia zuppa, ma si sono nascosti! Sono un tipo paziente, posso aspettare qualche giorno... forse potrei trovare altre scatole?\n\nTrovami della Carne di Verme del Fango e in cambio ti darò questa scatola.', 'No, la scatola è mia!\n\nSono venuto qui in cerca di vermi per una zuppa. Alcuni Tortolliani dicono che quella di crostaceo è migliore, ma per me si sbagliano. Non vale la pena scomodare degli stranieri per quella sbobba.\n\nLa Zuppa di Vermi del Fango crea amicizie che durano tutta la vita, e noi Tortolliani viviamo davvero a lungo.\n\nTi darò questa vecchia scatola in cambio di un po\' di Carne di Verme del Fango.', 28153),
(149433, 'itIT', 'Quella scatola?', 'Quella scatola?', 28153),
(149432, 'itIT', 'Ero qui fermo da molto tempo, quando ho trovato un\'interessante scatola nel fango.', 'Ero qui fermo da molto tempo, quando ho trovato un\'interessante scatola nel fango.', 28153),
(149431, 'itIT', 'Ottimo lavoro, cumpà. Stavo... uscendo pazzo. Lo spirito mio stava avvizzendo lento come na carovana di Tortolliani!', 'Ottimo lavoro, cumpà. Stavo... uscendo pazza. Lo spirito mio stava avvizzendo lento come na carovana di Tortolliani!', 28153),
(149430, 'itIT', 'Ti ringrazio davvero, $gstraniero:straniera;.', 'Ti ringrazio davvero, $gstraniero:straniera;.', 28153),
(149429, 'itIT', 'Finalmente è tutto finito. Grazie.', 'Finalmente è tutto finito. Grazie.', 28153),
(149428, 'itIT', 'Mo\' posso dormire sonni tranquilli. Grazie mille.', 'Mo\' posso dormire sonni tranquilli. Grazie mille.', 28153),
(149427, 'itIT', 'Tutto... finisce...', 'Tutto... finisce...', 28153),
(149426, 'itIT', 'Qual è il piano?', 'Qual è il piano?', 28153),
(149425, 'itIT', '', 'Pensavo a delle scosse elettriche, o del fuoco, o magari degli esplosivi!\n\nPorta sfortuna, però, uccidere un Tortolliano e non ho assolutamente bisogno di altra sfortuna.\n\nDimmi, come intendi gestire questa situazione?', 28153),
(149424, 'itIT', '', 'Abbiamo un problema, $p. I Tortolliani hanno trovato una scatola e noi la rivogliamo!', 28153),
(149423, 'itIT', 'Dannata palude! Sta cadendo tutto a pezzi con questa umidità.\n\nBene, di che hai bisogno? Facciamo in fretta, così posso tornare a occuparmi delle riparazioni.', 'Dannata palude! Sta cadendo tutto a pezzi con questa umidità.\n\nBene, di che hai bisogno? Facciamo in fretta, così posso tornare a occuparmi delle riparazioni.', 28153),
(149422, 'itIT', '', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149421, 'itIT', 'Solo uno sciocco arrogante troverebbe saggio ospitare gli Amani tra i propri confini. Hai agito bene.', '', 28153),
(149420, 'itIT', 'L\'unico Amani buono è un Amani morto, ma gli Zandalari hanno dato loro rifugio in città. Sconfiggi i loro discepoli, per l\'Alleanza!', '', 28153),
(149419, 'itIT', 'La bestia è morta! Bracescura, mettete al sicuro i piani superiori! Mi occuperò io di questo ladruncolo...', 'La bestia è morta! Bracescura, mettete al sicuro i piani superiori! Mi occuperò io di questo ladruncolo...', 28153),
(149418, 'itIT', 'Fintanto che avrò forza, non lascerò cadere il bastione!', '', 28153),
(149417, 'itIT', 'Questo dovrebbe ricordare loro il posto che si meritano.', '', 28153),
(149416, 'itIT', '<Mostra a Kellam la Pietra Evocatrice.>', '<Mostra a Kellam la Pietra Evocatrice.>', 28153),
(149415, 'itIT', 'La tribù Amani farà meglio a ricordare che l\'Orda ha grande influenza a Zuldazar. Perché non rinfreschi loro la memoria? Suona il gong e sconfiggi i loro discepoli.', '', 28153),
(149414, 'itIT', 'Io vado avanti a cercare i contadini. Qualsiasi cosa succeda, non farti catturare!', '', 28153),
(149413, 'itIT', '', 'Taz\'dingo!', 28153),
(149411, 'itIT', 'Ci sono un sacco di tesori là fuori, nascosti nel fango. Tu e Moxie lavorerete insieme per trovarli!', '', 28153),
(149410, 'itIT', 'No! I crog... non devono essere liberati...', '', 28153),
(149409, 'itIT', 'Alla battaglia!', 'Alla battaglia!', 28153),
(149408, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(149407, 'itIT', 'Combattiamo uniti.', 'Combattiamo uniti.', 28153),
(149406, 'itIT', 'Combatterò al tuo fianco!', 'Combatterò al tuo fianco!', 28153),
(149405, 'itIT', 'Sono in debito con te, $n.', 'Sono in debito con te, $n.', 28153),
(149404, 'itIT', 'Il rituale non è ancora completo, i crog devono essere soggiogati!', '', 28153),
(149403, 'itIT', 'Continuate ad attaccare. So badare a me stesso.', '', 28153),
(149402, 'itIT', '', 'La forza mia... Cos\'è tutto chesto?', 28153),
(149401, 'itIT', '', 'Il mio corpo... Nun riesco... Argh!', 28153),
(149400, 'itIT', 'Va bene.', 'Va bene.', 28153),
(149399, 'itIT', '', 'Alcuni lavoratori dicono di sentire delle voci che gli fanno perdere la ragione provenire dal fango!\n\nIo mi limito a non ascoltare!', 28153),
(149398, 'itIT', '', 'Alcuni Kul Tirani mi hanno accusata di alcune rapine, delle quali non so veramente nulla.', 28153),
(149397, 'itIT', '', 'Faccio rotta... verso acque sconosciute...', 28153),
(149396, 'itIT', '', 'Si comporta come se non avesse mai visto una Gnoma prima d\'ora!', 28153),
(149395, 'itIT', '', 'Mi avete stufata!', 28153),
(149394, 'itIT', '', 'Fuoco coi decimatori!', 28153),
(149393, 'itIT', '', 'Assaggiate un po\' di piombo!', 28153),
(149392, 'itIT', '', 'Vi taglierò in tante piccole fette!', 28153),
(149391, 'itIT', '', 'Ripulite il ponte!', 28153),
(149390, 'itIT', 'Zandalari... pieni di false promesse.', 'Zandalari... pieni di false promesse.', 28153),
(149389, 'itIT', 'Avrai notizie dal Loa mio per chesto...', 'Avrai notizie dal Loa mio per chesto...', 28153),
(149388, 'itIT', 'Nessun luogo è più sicuro per noi.', 'Nessun luogo è più sicuro per noi.', 28153),
(149387, 'itIT', 'Ci hanno lasciati schiattare... nella città loro.', 'Ci hanno lasciati schiattare... nella città loro.', 28153),
(149386, 'itIT', 'Che ne sarà di noi mo\'?', 'Che ne sarà di noi mo\'?', 28153),
(149385, 'itIT', 'L\'impero... è davvero caduto.', 'L\'impero... è davvero caduto.', 28153),
(149384, 'itIT', 'Come hanno potuto lasciare... che succeda?', 'Come hanno potuto lasciare... che succeda?', 28153),
(149383, 'itIT', 'Li Zandalari... avevano promesso che saremmo stati al sicuro...', 'Li Zandalari... avevano promesso che saremmo stati al sicuro...', 28153),
(149382, 'itIT', 'Finalmente! Qualcuno ha trovato le offerte mie per Bwonsamdi. Usale bene!', 'Finalmente! Qualcuno ha trovato le offerte mie per Bwonsamdi. Usale bene!', 28153),
(149381, 'itIT', '', 'Portatemi i loro pollici! Fate ciò che volete del resto.', 28153),
(149380, 'itIT', '', 'Mi prenderò la tua fetta se ci lasci le penne!', 28153),
(149379, 'itIT', '', 'La capa tua starà benissimo nella collezione mia.', 28153),
(149378, 'itIT', '', 'Tu e io siamo amici, ora. Puoi prestarmi dell\'oro?', 28153),
(149377, 'itIT', '', 'Ho visto qualcuno che ti assomigliava molto a Tol Dagor.', 28153),
(149376, 'itIT', 'Stai facendo nu grosso errore!', 'Stai facendo nu grosso errore!', 28153),
(149375, 'itIT', 'Aiuto! La terrazza sta sotto attacco!', 'Aiuto! La terrazza sta sotto attacco!', 28153),
(149374, 'itIT', 'Pigliateli!', 'Pigliateli!', 28153),
(149373, 'itIT', 'Nun dovresti stare accà, cumpà!', 'Nun dovresti stare accà, cumpà!', 28153),
(149372, 'itIT', 'Vattene! Zandalar appartiene ai Troll!', 'Vattene! Zandalar appartiene ai Troll!', 28153),
(149371, 'itIT', 'Sapevo di aver sentito n\'odore terribile...', 'Sapevo di aver sentito n\'odore terribile...', 28153),
(149370, 'itIT', 'Aiuto! Mi stanno attaccando!', 'Aiuto! Mi stanno attaccando!', 28153),
(149369, 'itIT', 'Lurida feccia!', 'Lurida feccia!', 28153),
(149368, 'itIT', '<Coda borbotta e osserva la gola.>', '', 28153),
(149367, 'itIT', '', 'Sono preoccupata anch\'io, Coda.', 28153),
(149366, 'itIT', 'Mi serve un passaggio per la Stazione Orientale.', 'Mi serve un passaggio per la Stazione Orientale.', 28153),
(149365, 'itIT', '', 'Dove stai andando?', 28153),
(149364, 'itIT', '', 'Grazie! E dai un forte abbraccio anche a Poda!', 28153),
(149363, 'itIT', '', 'A tutti i cannoni! Fuoco!', 28153),
(149362, 'itIT', 'I cantieri saranno la vostra nuova casa.', '', 28153),
(149361, 'itIT', 'Voi tutti servirete Ser Sacraonda ai cantieri.', '', 28153),
(149360, 'itIT', 'Tutti sulle carovane.', '', 28153),
(149359, 'itIT', 'I Troll del Sangue stanno minacciando ancora i miei figli!$B$BVieni, insieme gli ricorderemo cosa succede a chi fa infuriare Krag\'wa!', '', 28153),
(149358, 'itIT', '', 'La città è nostra, ciurma!', 28153),
(149357, 'itIT', '', 'Le tue budella penzoleranno dal mio pennone, ahahah!', 28153),
(149356, 'itIT', '', 'Un\'altra tacca sulla mia spada.', 28153),
(149355, 'itIT', '', 'Fuoco a volontà!', 28153),
(149354, 'itIT', '', 'Niente sopravvissuti!', 28153),
(149353, 'itIT', 'La loro attesa è quasi finita.', '', 28153),
(149352, 'itIT', 'Quanto presto?', 'Quanto presto?', 28153),
(149351, 'itIT', 'I Marferreo ci attaccano ogni giorno e c\'è anche un\'armata dell\'Orda diretta verso di noi. Non ci vorrà molto perché l\'intero villaggio debba essere evacuato.', '', 28153),
(149348, 'itIT', 'Completerò il rituale... con il sangue vostro!', '', 28153),
(149347, 'itIT', 'VA BENE.', 'VA BENE.', 28153),
(149346, 'itIT', 'Fallito? Ahahah! No...', '', 28153),
(149345, 'itIT', 'C\'è un immenso tesoro sul fondo di quel lago, nascosto in una nave ricca di bottini affondata durante la Seconda Guerra!\n\nL\'intero villaggio sta lavorando per trovarlo prima di noi! Non c\'è molto tempo, però, dobbiamo sbrigarci!', '', 28153),
(149344, 'itIT', 'Lith qul\'shoth wshh... yzsh uovssh qvask.', '', 28153),
(149343, 'itIT', '', 'È finita, Jakra\'zet. Il piano tuo è fallito!', 28153),
(149341, 'itIT', 'Pensate di soffrire in superficie... ma Egli attende nell\'abisso.', '', 28153),
(149340, 'itIT', '', 'Giusto in tempo per fermarti!', 28153),
(149339, 'itIT', 'Siete arrivati giusto in tempo...', '', 28153),
(149338, 'itIT', '', 'Sì! Sono tutti tornati a casa!', 28153),
(149337, 'itIT', 'Il rituale del sangue è quasi completo!', '', 28153),
(149336, 'itIT', '', 'Ti prego, sbrigati a trovarli! Coda sarebbe tristissimo se perdesse la sua famiglia.', 28153),
(149335, 'itIT', 'Tesoro?', 'Tesoro?', 28153),
(149334, 'itIT', 'I Marferreo fanno chiunque prigioniero. Stanno cercando di impedirci di trovare il tesoro per primi!', '', 28153),
(149333, 'itIT', '', 'Tornate indietro, piccoletti! Possiamo aiutarvi!', 28153),
(149332, 'itIT', '', 'Se andiamo là dentro, quegli insetti ci attaccheranno!', 28153),
(149331, 'itIT', '', 'Non riesco a vederli, Coda!', 28153),
(149330, 'itIT', 'Zaix lal sk\'woth\'gl Zaix lal uulwi.', '', 28153),
(149329, 'itIT', 'I Marferreo stanno facendo prigionieri. Ci farebbe comodo il tuo aiuto!', '', 28153),
(149328, 'itIT', 'Essi sono la redenzione. Essi sono la verità.', '', 28153),
(149327, 'itIT', 'Zuq wgah nuq iilth zz oou ga\'halahs anagg.', '', 28153),
(149326, 'itIT', 'Annegherete tutti nell\'abisso senza luce.', '', 28153),
(149325, 'itIT', '', 'Se non esplode, basta riprovarci.', 28153),
(149323, 'itIT', 'Non credo proprio. Ho l\'ordine di condurti direttamente dalla Capoguerra.', '', 28153),
(149322, 'itIT', '', 'Dato che chesta nave è mia, forse dovresti rivalutare i piani tuoi.', 28153),
(149321, 'itIT', 'Possiamo discuterne lungo la strada, altezza.', '', 28153),
(149320, 'itIT', '', 'Andiamo. Facciamo vela per Zuldazar.', 28153),
(149319, 'itIT', 'Credo che chello che volevi dire fosse \"Grazie.\"', '', 28153),
(149318, 'itIT', 'Na Maga dalle tue... abilità... potrebbe essere parecchio utile, ora... Che ne dici?', '', 28153),
(149317, 'itIT', '', 'No! Non può essere...', 28153),
(149315, 'itIT', 'Puoi cercare di soggiogarci, e potresti pure riuscirci.', '', 28153),
(149314, 'itIT', 'So che vedi le fiamme che divorano la città.', '', 28153),
(149313, 'itIT', 'Nun tenere fretta, ora.', '', 28153),
(149312, 'itIT', '', 'Allora morite.', 28153),
(149311, 'itIT', 'Con tutto il rispetto, abbiamo una nave da prendere.', '', 28153),
(149310, 'itIT', '', 'Arrendetevi e vi riporterò nelle Segrete dove meritate di stare. Lì attenderete il giudizio del Re.', 28153),
(149309, 'itIT', 'Aspettatemi accà.', '', 28153),
(149307, 'itIT', 'È già tutto pronto. Osserva.', '', 28153),
(149306, 'itIT', 'Smettetela di blaterare e aprite un passaggio in quel ghiaccio!', '', 28153),
(149305, 'itIT', 'Nun conosco alcun Rezan, ma nun mancherò di ringraziarlo.', '', 28153),
(149303, 'itIT', '', 'Morite, feccia dell\'Orda!', 28153),
(149302, 'itIT', '', 'Ci ha bloccato la via di fuga!', 28153),
(149300, 'itIT', '', 'Me ne servono venti di chegli uccelli.', 28153),
(149299, 'itIT', 'Ahah! Lasan, astuto vecchio mio!', '', 28153),
(149298, 'itIT', 'No... ma credo di sapere perché. Guardate.', '', 28153),
(149297, 'itIT', 'Che i Loa aiutino chi oserà sfidarti, Zul.', '', 28153),
(149296, 'itIT', '', 'Avete sparso molto sangue innocente, ma la vostra piccola fuga finisce qui.', 28153),
(149295, 'itIT', '', 'Non ci inseguono?', 28153),
(149294, 'itIT', 'Ahahahah!', '', 28153),
(149292, 'itIT', '', 'Le loro forze devono essere tornate a Lordaeron. Come facciamo a passare?', 28153),
(149291, 'itIT', 'Muoviamoci!', '', 28153),
(149290, 'itIT', '', 'Il Loa mio ci ascolta. Potente Rezan, donami la forza tua!', 28153),
(149289, 'itIT', '', 'Non farete più del male a nessuno in questa città!', 28153),
(149288, 'itIT', '', 'Siete andati troppo oltre!', 28153),
(149287, 'itIT', 'Guardate dove mettete i piedi. Pare che la \"diplomatica\" dell\'Alleanza non farà prigionieri questa volta.', '', 28153),
(149286, 'itIT', 'Coff! Bleah!', '', 28153),
(149285, 'itIT', '', 'Hai trovato mia mamma! Grazie per averla salvata da quei mostri terribili!', 28153),
(149284, 'itIT', '', 'Grazie per avermi portato il mio giocattolo. Se vedi mia mamma, le chiederesti di venire a casa?\n\nÈ da un po\' che non la vedo.', 28153),
(149283, 'itIT', 'Ora infrangi l\'ultimo sigillo.', '', 28153),
(149282, 'itIT', '', 'Talanji, tu e il campione tuo seguirete le tracce di Zul. Io radunerò i soldati per cercare di fermare l\'Annientatore. Servirà n\'armata per abbattere chel coso.', 28153),
(149281, 'itIT', 'Sta comandando Mythrax. Dobbiamo fermare i servi dell\'Impero Nero.', '', 28153),
(149280, 'itIT', '', 'Io e il Loa terremo a bada Mythrax il più a lungo possibile. Trova il padre mio e accidi Zul!', 28153),
(149279, 'itIT', 'Vieni, Mythrax. Vieni, Annientatore. L\'ultimo sigillo dev\'essere infranto.', '', 28153),
(149278, 'itIT', 'La via è libera, piccoletti. Muoviamoci. Mythrax si avvicina.', '', 28153),
(149277, 'itIT', '', 'Fratelli e sorelle di Zandalar, ripigliamoci la città nostra! Avanti, in marcia!', 28153),
(149276, 'itIT', '', 'Cerca i civili che sono ancora allo Zocalo e mandali da noi. Arriveremo quando potremo.', 28153),
(149275, 'itIT', '', 'Male. Siamo circondati. I Loa stanno facendo il possibile, ma dobbiamo radunare ogni Troll capace di impugnare na lancia.', 28153),
(149274, 'itIT', '', 'Tempi oscuri richiedono grandi gesta. Come vanno le cose?', 28153),
(149273, 'itIT', '', 'Ah, Talanji, vedo che stai guidando i Loa in battaglia.', 28153),
(149272, 'itIT', '', 'Rakera, vedo che hai assunto il comando delle forze nostre.', 28153),
(149271, 'itIT', '', 'In riga! Arcieri da Guerra pronti!', 28153),
(149270, 'itIT', '', 'Be\'... questo è... spiacevole.', 28153),
(149269, 'itIT', '', 'La Voce dell\'Orda afferma che Mythrax l\'Annientatore è risorto.', 28153),
(149268, 'itIT', '', 'Qualcosa ha indotto i Sethrak ad attaccare. Stanno sciamando come mai prima d\'ora.', 28153),
(149267, 'itIT', '', 'Statt\' accuort\', padre. Chesti sono i piani di nu nemico al di là della nostra concezione.', 28153),
(149266, 'itIT', 'Talanji, piglia la Voce dell\'Orda e raduna le forze nostre. Io e Krag\'wa metteremo al sicuro la Scheggia.', '', 28153),
(149265, 'itIT', '', 'Rastakhan! I serpenti di Vol\'dun stanno attaccando il confine occidentale. Fa\' qualcosa!', 28153),
(149264, 'itIT', 'In troppi stanno superando le difese. Raggiungi il ponte per Dazar\'alor. Possiamo provare a forzarli in qualche strettoia.', '', 28153),
(149263, 'itIT', 'Un dono per il vecchio Bwonsamdi.', '', 28153),
(149262, 'itIT', 'Schiattate, invasori!', '', 28153),
(149261, 'itIT', 'Ce ne stanno troppi.', '', 28153),
(149260, 'itIT', 'La Porta Insanguinata è perduta. Presto, dobbiamo eliminare più invasori possibile prima che raggiungano la città.', '', 28153),
(149259, 'itIT', '', 'Non puoi fermare... la tempesta...', 28153),
(149258, 'itIT', '', 'Non puoi fermare l\'impero dei Senzafede!', 28153),
(149257, 'itIT', 'Troverò un modo per uscire. Fai attenzione!', '', 28153),
(149256, 'itIT', 'Che gli dei ti benedicano... Pensavo fosse la fine.', '', 28153),
(149255, 'itIT', 'Dovrebbe bastare. Come ci si sente a saccheggiare un\'intera città da soli?', '', 28153),
(149254, 'itIT', 'Scappa... SCAPPA!!!', '', 28153),
(149253, 'itIT', 'È troppo presto. Non è ancora annegato nella gloria del maestro!', '', 28153),
(149252, 'itIT', 'No, no, no! La città è in subbuglio! Ci tirerò fuori di qui.', '', 28153),
(149250, 'itIT', 'Prova a usare il pugnale che ti ho nascosto in tasca. Credo che ti piacerà.', '', 28153),
(149249, 'itIT', 'Dopo di te. Tu marchia i bersagli, io li abbatto.', '', 28153),
(149248, 'itIT', 'Fiducia... una volta rotta è quasi impossibile da riparare. Questo danneggerà duramente gli Zandalari. Ben fatto.', '', 28153),
(149247, 'itIT', 'I rappresentanti delle tribù minori dei Troll si sono riuniti sotto la protezione degli Zandalari, ma sono vulnerabili. Uccidi gli Oratori e semina discordia tra i nostri nemici.', '', 28153),
(149246, 'itIT', 'Bruciate le loro carovane e spezzategli le ossa!', 'Bruciate le loro carovane e spezzategli le ossa!', 28153),
(149245, 'itIT', 'Se questi vermi stanno nascondendo la chiave, la troveremo!', 'Se questi vermi stanno nascondendo la chiave, la troveremo!', 28153),
(149244, 'itIT', 'Risparmia quelli più forti. Si venderanno bene al mercato.', 'Risparmia quelli più forti. Si venderanno bene al mercato.', 28153),
(149243, 'itIT', 'È quasi finita? Dimmi che è quasi finita, ti prego!', '', 28153),
(149242, 'itIT', 'Torna qui!', 'Torna qui!', 28153),
(149241, 'itIT', '', 'Dirigiamoci alla cresta di nord-ovest. Dal Presidio di Arom dovrebbero riuscire a vedere il nostro segnale.', 28153),
(149240, 'itIT', '', 'Ma prima di partire, dovremmo approfittare della situazione e annientare le loro forze!', 28153),
(149239, 'itIT', '', 'Possiamo segnalare l\'estrazione al punto strategico, a nord-ovest.', 28153),
(149238, 'itIT', 'Questa è follia! Rallenta!', '', 28153),
(149237, 'itIT', 'Ahahahahah! Adoro quando fa tremare la terra!', '', 28153),
(149236, 'itIT', '', 'È alquanto soddisfacente utilizzare le armi della congrega contro di loro.', 28153),
(149235, 'itIT', 'Questo fuoco emana un fumo violaceo. Presto dovrebbero vederlo alzarsi dagli alberi.', '', 28153),
(149234, 'itIT', 'Lasciami segnalare agli altri di iniziare l\'assalto.', '', 28153),
(149233, 'itIT', 'No. Col tempo verranno loro da noi.', '', 28153),
(149232, 'itIT', '', 'Nun dovremmo seguirlo?', 28153),
(149231, 'itIT', 'Basta patti con gli stranieri... E nemmeno coi Loa. Il sangue è la via nostra, adesso... la via di G\'HUUN!', '', 28153),
(149230, 'itIT', 'Io nun tiene fame mo\'. Tu torna dopo...', '', 28153),
(149229, 'itIT', 'Mi crederesti se ti dicessi che sta andando tutto secondo i piani? Non credo proprio.', '', 28153),
(149228, 'itIT', 'Buone notizie! Ho scoperto la posizione dei nemici. Ci hanno circondati.', '', 28153),
(149227, 'itIT', 'Possiamo... evitare di dirlo a Roz?', '', 28153),
(149226, 'itIT', 'Non è proprio il mio momento migliore.', '', 28153),
(149225, 'itIT', 'Chesta è la profezia mia. L\'impero dei Troll dominerà chesto mondo, com\'era nu tempo. Sul trono suo siederà nu re, com\'era nu tempo, anche se né tu ne io vivremo tanto a lungo da vederlo. È chesto ciò che il dio mio mi ha mostrato...', '', 28153),
(149224, 'itIT', 'Ti sei fatto vecchio, amico mio. Hai lasciato marcire l\'impero nostro sotto la tua guida. Io ho previsto la rinascita dell\'impero dei Troll.', '', 28153),
(149223, 'itIT', 'Avresti dovuto dare ascolto a Talanji.', '', 28153),
(149221, 'itIT', 'No! Habutu!', '', 28153),
(149220, 'itIT', 'Ahahah! Ottimo lavoro!', '', 28153),
(149219, 'itIT', 'L\'ora del sangue si avvicina.', '', 28153),
(149218, 'itIT', 'Il tempo dei Loa... è finito.', '', 28153),
(149217, 'itIT', 'Nun tieni potere su di me!', '', 28153),
(149216, 'itIT', 'Rezan, Rezan...', '', 28153),
(149215, 'itIT', 'Sta\' attento a come parli, traditore.', '', 28153),
(149214, 'itIT', 'Ah, eccolo... Il Loa del... Mmm...', '', 28153),
(149212, 'itIT', '', 'Sarà meglio che le tue visioni siano corrette.', 28153),
(149211, 'itIT', 'Eretico!', '', 28153),
(149210, 'itIT', '', 'Anticipate le mosse del vostro avversario!', 28153),
(149209, 'itIT', '', 'Colpite come il vento! Parate!', 28153),
(149208, 'itIT', '', 'Niente pausa finché le trivellazioni non saranno finite!', 28153),
(149207, 'itIT', '', 'Concentratevi sul vostro compagno! Colpite con forza!', 28153),
(149206, 'itIT', 'Comandante! È... svenuta?', 'Comandante! È... svenuta?', 28153),
(149205, 'itIT', 'Sorella, stai bene?!? Non volevo colpirti così forte!', 'Sorella, stai bene?!? Non volevo colpirti così forte!', 28153),
(149204, 'itIT', 'Oh santo cielo... stai bene?!?', 'Oh santo cielo... stai bene?!?', 28153),
(149200, 'itIT', 'Non c\'è niente come la soddisfazione di annientare un comandante dell\'Alleanza. E con una tale facilità...', '', 28153),
(149199, 'itIT', '', 'Che i venti siano con te.', 28153),
(149198, 'itIT', '', 'Ancora una volta l\'Ordine delle Braci si è opposto a Gorak Tul. Continueremo a combattere al fianco dei nostri alleati.', 28153),
(149197, 'itIT', '', 'Grazie di avermi aiutato. Informerò Dama Lucille del successo ottenuto.', 28153),
(149196, 'itIT', 'Tremo al solo pensiero di cosa sarei potuto diventare se tu e l\'Inquisitrice non foste intervenuti.', '', 28153),
(149195, 'itIT', 'Ringrazio di non essere morto.', '', 28153),
(149194, 'itIT', '', 'Sorvolare la foresta è sicuro, ora. Spero solo che arrivino in fretta.', 28153),
(149193, 'itIT', '', 'Ci sono dei Cavalieri di Grifoni che aspettano il segnale.', 28153),
(149192, 'itIT', 'Debole e approssimativo! La prossima volta fa\' meno rumore!', '', 28153),
(149191, 'itIT', 'Dannazione! Doveva essere qualcosa di rapido e tranquillo. Concentrati!', '', 28153),
(149190, 'itIT', 'Uccidi subito il bersaglio, prima che avverta gli altri!', '', 28153),
(149189, 'itIT', 'Cerca di non farti scoprire! Non possiamo attirare troppa attenzione...', '', 28153),
(149187, 'itIT', 'Ah ah ah ah ah... No... Ora appartiene a me.', '', 28153),
(149186, 'itIT', 'Farò finta di non aver visto niente. Non posso certo dire di non aver mai ucciso nessuno nel sonno.', '', 28153),
(149185, 'itIT', 'Ehi. Fai attenzione con i civili. Potremmo attirare l\'attenzione delle guardie.', '', 28153),
(149184, 'itIT', 'Quella non era una guardia, ma lungi da me impedirti di assassinare qualsiasi membro dell\'Alleanza.', '', 28153),
(149183, 'itIT', 'Tecnicamente, non ci sarebbe bisogno di uccidere civili... ma mi piace il tuo stile.', '', 28153),
(149182, 'itIT', 'Hai un\'anima fredda come il ghiaccio... mi piace.', '', 28153),
(149181, 'itIT', 'Uno dei nostri ingegneri ha avvistato l\'Alleanza vicino alla nostra miniera, mentre recuperava parti di ricambio. Raggiungi Margie all\'Officina per i dettagli e... per prepararti.', '', 28153),
(149180, 'itIT', 'Il petto... non riesco a respirare!', 'Il petto... non riesco a respirare!', 28153),
(149179, 'itIT', 'La mia gola... sto soffocando!', 'La mia gola... sto soffocando!', 28153),
(149178, 'itIT', 'Mi sta per venire da vomitare...', 'Mi sta per venire da vomitare...', 28153),
(149177, 'itIT', 'Devo solo... riposarmi...', 'Devo solo... riposarmi...', 28153),
(149176, 'itIT', 'È tutto così... oscuro...', 'È tutto così... oscuro...', 28153),
(149175, 'itIT', 'Mi sento... strano...', 'Mi sento... strana...', 28153),
(149174, 'itIT', 'No! Nooo!!!', '', 28153),
(149173, 'itIT', 'Co... Cosa?', '', 28153),
(149172, 'itIT', 'Ehi, tu! Altolà!', '', 28153),
(149171, 'itIT', '', 'È come se volessero schiattare... Spero che il sangue loro nun alimenti G\'huun in qualche modo.', 28153),
(149170, 'itIT', '', 'Continuano a sfidare Bwonsamdi. Nun finirà bene per loro. Il patto nostro con il Loa dei Morti dev\'essere rispettato. Manda a lui chelle anime perdute!', 28153),
(149169, 'itIT', 'Aspetta, no. Era solo l\'altra gamba. Va tutto bene.', '', 28153),
(149168, 'itIT', 'Qualcosa mi ha toccato la gamba!', '', 28153),
(149167, 'itIT', 'La Vena Madre è al sicuro. Venite a prendere la vostra parte!', '', 28153),
(149166, 'itIT', 'Oh! Sembra che i nostri minatori abbiano fatto bingo! Riporta il carrello alla base e ne beneficeremo tutti.', '', 28153),
(149165, 'itIT', '', 'Andiamo! Ti terrò d\'occhio.', 28153),
(149164, 'itIT', '', 'Gli esplosivi non sono mai abbastanza!', 28153),
(149163, 'itIT', '', 'Conosci qualche nobile di Kul Tiras con tanti soldi e poche guardie?', 28153),
(149162, 'itIT', '', 'Sto cercando gente sveglia come te, $p, per investire un sacco d\'oro in una nuova attività che sto per iniziare.', 28153),
(149161, 'itIT', '', 'Una Gnoma deve sempre guardarsi le spalle in mezzo a tutti questi Kul Tirani.', 28153),
(149160, 'itIT', '', 'Quando sei in dubbio, fallo esplodere!', 28153),
(149159, 'itIT', '', 'Tol Barad, Tol Dagor, le Segrete di Roccavento... le ho viste tutte!', 28153),
(149158, 'itIT', 'Manda il segnale. Andiamocene da qui!', 'Manda il segnale. Andiamocene da qui!', 28153),
(149157, 'itIT', '', 'Ti prego, Rakera, nun farlo! T\'accideranno!', 28153),
(149156, 'itIT', '', 'Lode alle sabbie, sei ancora in vita!', 28153),
(149155, 'itIT', '', 'Chesta intrusione finisce mo\'! Nessuno interrompe la signora!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(149154, 'itIT', 'Chesti piccirilli nun sembrano na grossa minaccia, $R.', '', 28153),
(149151, 'itIT', '', 'Sei ancora $gvivo:viva;, $p! Sei $gfortunato:fortunata; quanto me.', 28153),
(149150, 'itIT', 'Ci vediamo dopo.', '', 28153),
(149149, 'itIT', 'Tutto accà?', '', 28153),
(149148, 'itIT', 'Vacci piano.', '', 28153),
(149147, 'itIT', 'Nun preoccuparti.', '', 28153),
(149146, 'itIT', 'Ti serve il vudù?', '', 28153),
(149145, 'itIT', 'Cosa ti serve?', '', 28153),
(149144, 'itIT', '', 'I Troll del Sangue nun ci fregheranno più... finché sarò in vita.', 28153),
(149143, 'itIT', '', 'I Troll del Sangue stanno cercando di aggirarci di nascosto, ma tengo qualcosa per aiutarti a vederli. E toglierli di mezzo.', 28153),
(149142, 'itIT', 'Riprendete fiato. Non ci fermeremo finché non saremo alla nave.', '', 28153),
(149141, 'itIT', 'Me ne vado via di corsa!', 'Me ne vado via di corsa!', 28153),
(149140, 'itIT', 'Zul ci farà schiattare tutti quanti.', 'Zul ci farà schiattare tutti quanti.', 28153),
(149139, 'itIT', 'È la fine del mondo!', 'È la fine del mondo!', 28153),
(149138, 'itIT', 'Chesto è nu disastro per li affari.', 'Chesto è nu disastro per li affari.', 28153),
(149137, 'itIT', 'Io me la squaglio.', 'Io me la squaglio.', 28153),
(149136, 'itIT', 'Ehi! Che succede lì?', '', 28153),
(149135, 'itIT', 'GUARDIE! GUARDIE, AIUTO! OHHH!!!', '', 28153),
(149134, 'itIT', 'OUCH! MALEDETTO!', '', 28153),
(149133, 'itIT', 'Non avere paura! Fammi vedere che sai fare.', '', 28153),
(149132, 'itIT', 'Avanti, colpiscimi!', '', 28153),
(149131, 'itIT', 'Colpiscimi.', '', 28153),
(149130, 'itIT', 'Va bene, ecco il piano:', '', 28153),
(149129, 'itIT', 'Appunto 3: ce l\'ho quasi fatta! Le api stanno crescendo e la produttività sta aumentando esponenzialmente. Devo tenere d\'occhio la regina, però.', '', 28153),
(149128, 'itIT', 'Appunto 2: il sidro animato ha iniziato a mostrare segni di aggressività. Forse ho sbagliato qualche calcolo.', '', 28153),
(149127, 'itIT', 'Appunto 1: il miele ha preso vita, ma si sta replicando più velocemente di quanto sperassi. Devo fare altre prove!', '', 28153),
(149126, 'itIT', 'Spegnete quelle fiamme! Raggiugeteli!', '', 28153),
(149125, 'itIT', 'Garda come scappano con la coda tra le gambe!', '', 28153),
(149124, 'itIT', 'Scappate, come i ratti che siete!', '', 28153),
(149123, 'itIT', '', 'Questa è follia. Morirete qui, e una tomba senza nome sarà l\'unica cosa rimasta di voi.', 28153),
(149122, 'itIT', '', 'Sapevo che l\'Orda era senza cuore. Spietata nella sua ricerca della vittoria. Ma questa...', 28153),
(149121, 'itIT', 'Li ho trovati, mio Re! Ti porterò le loro pelli come trofeo!', '', 28153),
(149120, 'itIT', 'Nun far finta di nun essere felice di vederci.', '', 28153),
(149119, 'itIT', 'Deliziato. Davvero. Ora, muoviamoci. Al tuo segnale.', '', 28153),
(149118, 'itIT', '', 'Sei nu nemico crudele, Zul.', 28153),
(149117, 'itIT', '', 'Non possiamo affrontarla. Via!', 28153),
(149116, 'itIT', '', 'E mo\' che c\'è?', 28153),
(149115, 'itIT', 'Be\', vi siete messi in un bel pasticcio.', '', 28153),
(149114, 'itIT', '', 'La baia! Dobbiamo avanzare!', 28153),
(149113, 'itIT', 'Eppure na città di pietra dovrebbe essere meno... infiammabile.', '', 28153),
(149112, 'itIT', 'Ci bloccano le vie d\'uscita. Nun possiamo farci mettere all\'angolo!', '', 28153),
(149111, 'itIT', 'Voi aspettate accà.', '', 28153),
(149110, 'itIT', 'Dobbiamo tornare ai canali. Seguitemi!', '', 28153),
(149109, 'itIT', 'Be\', chesto ci sarà utile.', '', 28153),
(149108, 'itIT', '', 'Dobbiamo trovare un riparo!', 28153),
(149107, 'itIT', '', 'Attenzione!', 28153),
(149106, 'itIT', 'Il vecchio lupo ci ha fiutato. Dobbiamo andarcene da accà!', '', 28153),
(149105, 'itIT', '', 'Ce ne sono troppi... la barriera non reggerà!', 28153),
(149104, 'itIT', 'Ci siamo! Fermateli prima che raggiungano i cancelli!', 'Ci siamo! Fermateli prima che raggiungano i cancelli!', 28153),
(149103, 'itIT', 'Pensavi di averla fatta franca? $gIlluso:Illusa;!', 'Pensavi di averla fatta franca? $gIlluso:Illusa;!', 28153),
(149102, 'itIT', 'Laggiù! Recupera quelle risorse!', 'Laggiù! Recupera quelle risorse!', 28153),
(149101, 'itIT', '', 'I Troll del Sangue sono creature malate e corrotte. Nun c\'è speranza che cambino.', 28153),
(149100, 'itIT', '', 'I Troll del Sangue stanno divorando la gente mia! Vanno fermati!', 28153),
(149099, 'itIT', '<Beccamorti è attirato dal frastuono!>', '<Beccamorti è attirato dal frastuono!>', 28153),
(149098, 'itIT', '<I Fendibecco sono attirati dall\'odore di esca nell\'acqua!>', '<I Fendibecco sono attirati dall\'odore di esca nell\'acqua!>', 28153),
(149097, 'itIT', 'Grazie! Non avevo nessuna voglia di finire su una picca.', '', 28153),
(149096, 'itIT', 'Eccoti! Ti spiace darmi una mano qui?', '', 28153),
(149095, 'itIT', 'Il tuo entusiasmo è apprezzato. Parleremo con Dama Crestabianca.', '', 28153),
(149094, 'itIT', '', 'Ci daresti una mano?', 28153),
(149093, 'itIT', 'Grazie per l\'aiuto.', '', 28153),
(149092, 'itIT', 'Dannate streghe e le loro barriere!', '', 28153),
(149091, 'itIT', '', 'Ah, chesti giovani cuccioli stanno crescendo bene. Nu giorno saranno delle ottime bestie da guerra.', 28153),
(149090, 'itIT', '', 'Le giovani bestie da guerra richiedono costante cura e attenzione. Devono imparare a interagire con noi, tanto quanto noi dobbiamo imparare a interagire con esse.', 28153),
(149089, 'itIT', 'Sento le evocazioni!', '', 28153),
(149088, 'itIT', 'Ho perso tutte le armi mie, ma almeno sto ancora in vita.', '', 28153),
(149087, 'itIT', 'Mi hanno pigliato alla sprovvista mentre stavo in esplorazione, nun accadrà di nuovo.', '', 28153),
(149086, 'itIT', 'Tornerò per farla pagare a chesti Troll del Sangue!', '', 28153),
(149085, 'itIT', 'Grazie, ora tornerò a Zul\'jan.', '', 28153),
(149084, 'itIT', '', 'Grazie. Sarà meglio che chei Goblin si concentrino a salvare la città mia, invece di fare profitti!', 28153),
(149083, 'itIT', '', 'Nu gruppo di prospettori Goblin è stato catturato dai non morti. Dobbiamo liberarli!', 28153),
(149082, 'itIT', 'Sai a cosa potrebbe servire questa pece? Nemmeno io, ma ho sentito dire che vale una fortuna!', '', 28153),
(149081, 'itIT', 'Queste sono le fosse... in tutti i sensi! Io me ne vado.', '', 28153),
(149080, 'itIT', 'Be\', sì, stavo giusto per andarmene in ogni caso. Questa pece frutterà un sacco!', '', 28153),
(149079, 'itIT', 'C\'è mancato poco! Ehi, ti andrebbe di andare a prendermi della pece? Possiamo rivenderla a un buon prezzo.', '', 28153),
(149078, 'itIT', 'Grazie, chi avrebbe immaginato che sarebbe stato pericoloso tirar fuori della pece da una palude dimenticata?', '', 28153),
(149076, 'itIT', 'Korthek ha superato i limiti. Devo occuparmene personalmente. Difendi le chiavi, mentre sono via.', '', 28153),
(149075, 'itIT', '', 'Chesto mostrerà ai Troll del Sangue che i giorni loro stanno per finire.', 28153),
(149074, 'itIT', '', 'La Squadra Gob tiene nu piano per i Troll del Sangue. Fai il possibile per portarli in salvo.', 28153),
(149073, 'itIT', 'Saliamo sul M.IM.MO.VO e fermiamo l\'armata dei Troll del Sangue.', 'Saliamo sul M.IM.MO.VO e fermiamo l\'armata dei Troll del Sangue.', 28153),
(149072, 'itIT', 'Ehi! Ci sono dei maledetti Troll del Sangue diretti verso Zuldazar. Per fortuna, abbiamo fatto un piccolo aggiornamento al M.IM.MO.!\n\nLustrati gli occhi con il M.IM.MO.VO! Questa bellezza può VOLARE! Una dispensatrice di morte dall\'alto!\n\nNaturalmente, abbiamo dovuto eliminare lo scudo, o non avrebbe funzionato.\n\nTi andrebbe di fare un giro di prova? Possiamo ridurre in cenere quell\'armata!', '', 28153),
(149071, 'itIT', 'Non vali niente... proprio come gli altri...', '', 28153),
(149070, 'itIT', 'Altri esiliati da massacrare? Oggi è proprio una bella giornata.', '', 28153),
(149066, 'itIT', 'Vai, piccolo re. Ingoierò chiunque cerchi di seguirti.', '', 28153),
(149065, 'itIT', 'Be\', nun proprio \"nulla\".', '', 28153),
(149064, 'itIT', '', 'Zul non è tipo da sporcarsi le mani. Potrebbe nun essere nulla.', 28153),
(149063, 'itIT', 'Non possono essere andati lontano. La vostra vigilanza ci proteggerà.', '', 28153),
(149062, 'itIT', 'Degli infiltrati dell\'Orda hanno fatto breccia nelle Segrete! Che tutti rimangano nelle proprie case fino al risolversi della situazione!', '', 28153),
(149061, 'itIT', 'Per ordine del Re!', '', 28153),
(149060, 'itIT', 'Posso tenerci nascosti, se nessuno fa niente di stupido.', '', 28153),
(149059, 'itIT', 'Ahah! Non temere, mio caro Ancel, è stato solo un contrattempo! Ci rimetteremo in sesto in men che non si dica.', 'Ahah! Non temere, mio caro Ancel, è stato solo un contrattempo! Ci rimetteremo in sesto in men che non si dica.', 28153),
(149058, 'itIT', 'Di cosa stai parlando?!? Ti sei quasi fatto uccidere e hai distrutto l\'intera fattoria!', '', 28153),
(149057, 'itIT', 'Spetta a noi portare avanti l\'arte della produzione del miele, a qualsiasi costo!', 'Spetta a noi portare avanti l\'arte della produzione del miele, a qualsiasi costo!', 28153),
(149056, 'itIT', 'Evidentemente nun vi serviva.', '', 28153),
(149055, 'itIT', 'ORA.', '', 28153),
(149054, 'itIT', 'Eh?', '', 28153),
(149053, 'itIT', '', 'Nun preoccuparti, se sarà in pericolo lo sapremo.', 28153),
(149052, 'itIT', 'Continua.', '', 28153),
(149051, 'itIT', '', 'Aspetta... Dove sono le guardie?', 28153),
(149050, 'itIT', 'Andiamo. Rimaniamo uniti.', '', 28153),
(149049, 'itIT', 'Nu poco più di preavviso sarebbe stato comodo.', '', 28153),
(149048, 'itIT', 'State all\'erta. L\'IR:7 ci ha informati che il nemico è stato avvistato vicino al forte.', '', 28153),
(149047, 'itIT', 'Saltate giù dal ponte. Ora.', '', 28153),
(149046, 'itIT', 'Attraversiamo il ponte. A meno che il Profeta tuo nun tenga qualcosa da dire.', '', 28153),
(149045, 'itIT', 'Presto, spostiamoci dalla strada.', '', 28153),
(149044, 'itIT', 'Aspettatemi accà.', '', 28153),
(149043, 'itIT', 'Attenzione, cittadini di Roccavento!', '', 28153),
(149042, 'itIT', 'Vabbuo\'. Stiamo vicini. Siamo tutti amici mo\'.', '', 28153),
(149041, 'itIT', '', 'La città si sta agitando. Non possiamo indugiare a lungo.', 28153),
(149040, 'itIT', 'Sono pronto a salpare!', 'Sono pronta a salpare!', 28153),
(149039, 'itIT', '', 'Sei $gpronto:pronta; ad avventurarti a Kul Tiras?', 28153),
(149038, 'itIT', '', 'Grazie al lavoro tuo, abbiamo guadagnato del tempo per permettere a Krag\'wa di preparare le difese. Ben fatto.', 28153),
(149037, 'itIT', 'Rivendicherò ciò che è mio, non mi fermerete!', '', 28153),
(149036, 'itIT', '', 'I Troll del Sangue continuano gli attacchi contro Krag\'wa! Taglia i rifornimenti loro. Che paghino per chesto assalto!', 28153),
(149035, 'itIT', 'Sethraliss... Ho dimenticato la tua voce...', '', 28153),
(149034, 'itIT', 'Non siamo legati ai Loa. La nostra forza è solo nostra!', '', 28153),
(149033, 'itIT', 'Intrusi! Vi state immischiando in affari più grandi di voi.', '', 28153),
(149031, 'itIT', 'PLACEHOLDER SCENE - Talanji asks if things are really over, Rokhan says evil has a way of surviving and he doubts this will be the last we see of this place.\nShot: Close ups of Talanji and Rokhan, then ominous shot of the now revealed pit.', 'PLACEHOLDER SCENE - Talanji asks if things are really over, Rokhan says evil has a way of surviving and he doubts this will be the last we see of this place.\nShot: Close ups of Talanji and Rokhan, then ominous shot of the now revealed pit.', 28153),
(149030, 'itIT', '', 'Padrone... ho... fallito...', 28153),
(149029, 'itIT', '', 'Gorak Tul... sta arrivando...', 28153),
(149028, 'itIT', '', 'Gorak Tul mi aveva promesso... il potere...', 28153),
(149027, 'itIT', '', 'Non servirò a molto in combattimento, ma mia madre dev\'essere consegnata alla giustizia... e io devo essere presente.', 28153),
(149026, 'itIT', '', 'Per mio padre e per Drustvar!', 28153),
(149025, 'itIT', '', 'Ti raggiungerò dentro, Inquisitrice.', 28153),
(149024, 'itIT', '', 'Inquisitori, a me! Gloria alla Casata dei Crestabianca!', 28153),
(149023, 'itIT', '', 'Sì, signora. Seppelliremo la congrega.', 28153),
(149022, 'itIT', '', 'Inquisitori, l\'ultima battaglia si avvicina. Possano i venti guidarvi alla vittoria.', 28153),
(149021, 'itIT', '', 'Madre... che cos\'hai fatto?', 28153),
(149020, 'itIT', '', 'Maresciallo, no...', 28153),
(149019, 'itIT', 'Mi... dispiace...', '', 28153),
(149018, 'itIT', 'Cara Lucy... ti ho... delusa...', '', 28153),
(149017, 'itIT', '', 'Resisti, Maresciallo!', 28153),
(149016, 'itIT', 'No... non può essere!', '', 28153),
(149015, 'itIT', 'Io... obbedisco...', '', 28153),
(149014, 'itIT', 'Noi copriremo i fianchi. Rimani con Lucille e il Maresciallo!', '', 28153),
(149013, 'itIT', '', 'Hai strillato alla persona sbagliata, strega!', 28153),
(149012, 'itIT', 'Continuate a muovervi, ci siamo quasi! Mira agli occhi, Winston!', '', 28153),
(149011, 'itIT', 'Io sarò dietro di te.', 'Io sarò dietro di te.', 28153),
(149010, 'itIT', 'Per la Casata dei Crestabianca!', '', 28153),
(149009, 'itIT', 'Rimanete uniti e non fermate l\'avanzata fino a quando non avrete fatto breccia nei cancelli del maniero!', '', 28153),
(149008, 'itIT', 'Nun dureremo a lungo di chesto passo. Dobbiamo raggiungere i moli.\n\nPartiremo al segnale tuo.', '', 28153),
(149007, 'itIT', 'Inquisitori! Questa è la nostra possibilità di salvare Ser e Dama Crestabianca e fermare finalmente quella congrega!', '', 28153),
(149005, 'itIT', '', 'State tremando. Avete paura, Alleanza?', 28153),
(149004, 'itIT', '', 'Ti gira la testa?', 28153),
(149003, 'itIT', '', 'Credevate davvero di poter vincere?', 28153),
(149002, 'itIT', '', 'Uccisa... da feccia così...', 28153),
(149001, 'itIT', 'Le vostre probabilità di vincere sono quasi nulle!', '', 28153),
(149000, 'itIT', 'Non sei nella posizione corretta!', '', 28153),
(148999, 'itIT', 'Fate che diventi cenere!', '', 28153),
(148998, 'itIT', 'Hai... imbrogliato...', '', 28153),
(148997, 'itIT', 'Ci sono io con te!', '', 28153),
(148996, 'itIT', 'Posizione difensiva!', '', 28153),
(148995, 'itIT', 'La Luce... mi guiderà a casa.', '', 28153),
(148994, 'itIT', '', 'Strappateli il cuore!', 28153),
(148993, 'itIT', '', 'Manderò la tua anima a Gorak Tul!', 28153),
(148991, 'itIT', 'Preparatevi! Arrivano!', 'Preparatevi! Arrivano!', 28153),
(148990, 'itIT', 'Proteggete le risorse!', 'Proteggete le risorse!', 28153),
(148989, 'itIT', 'Questa legna appartiene a noi!', 'Questa legna appartiene a noi!', 28153),
(148988, 'itIT', 'Non avvicinarti!', 'Non avvicinarti!', 28153),
(148987, 'itIT', 'Stai indietro!', 'Stai indietro!', 28153),
(148986, 'itIT', 'I Custodi erano i più potenti tra noi, incaricati di tenere al sicuro il corpo di Mythrax nella grande piramide.\n\nSulthis fu il fondatore, ma non poteva sigillare la tomba da solo.\n\nChiese a Vorrik e Korthek il loro aiuto e, insieme, eressero una barriera attorno alla grande piramide, sigillando il corpo di Mythrax all\'interno.', 'I Custodi erano i più potenti tra noi, incaricati di tenere al sicuro il corpo di Mythrax nella grande piramide.\n\nSulthis fu il fondatore, ma non poteva sigillare la tomba da solo.\n\nChiese a Vorrik e Korthek il loro aiuto e, insieme, eressero una barriera attorno alla grande piramide, sigillando il corpo di Mythrax all\'interno.', 28153),
(148985, 'itIT', 'Si fa chiamare Imperatore Korthek, ma molto tempo fa era uno dei Custodi, incaricato di proteggere la tomba.\n\nLa sua sete di guerra va contro tutto ciò che è più caro alla nostra Loa, eppure non fa che insultarla e disonorarla radunando un\'armata che progetta di conquistare tutta Zuldazar.', 'Si fa chiamare Imperatore Korthek, ma molto tempo fa era uno dei Custodi, incaricato di proteggere la tomba.\n\nLa sua sete di guerra va contro tutto ciò che è più caro alla nostra Loa, eppure non fa che insultarla e disonorarla radunando un\'armata che progetta di conquistare tutta Zuldazar.', 28153),
(148984, 'itIT', 'I Senzafede sono un gruppo militante di Sethrak, guidati dall\'Imperatore Korthek.\n\nMolto tempo fa, eravamo uniti, come Sethraliss avrebbe voluto.\n\nSin dal tradimento di Korthek, i Senzafede hanno portato la guerra su queste terre.\n\nNon si fermeranno fin quando non avranno conquistato il mondo intero.', 'I Senzafede sono un gruppo militante di Sethrak, guidati dall\'Imperatore Korthek.\n\nMolto tempo fa, eravamo uniti, come Sethraliss avrebbe voluto.\n\nSin dal tradimento di Korthek, i Senzafede hanno portato la guerra su queste terre.\n\nNon si fermeranno fin quando non avranno conquistato il mondo intero.', 28153),
(148983, 'itIT', 'Sethraliss è la nostra amata Loa.\n\nQuando Mythrax devastò le nostre terre, minacciando la nostra stessa esistenza, fu lei a fermarlo, sacrificando la sua vita per noi.\n\nA differenza dei Senzafede, sentiamo ancora la sua presenza e crediamo che un giorno tornerà da noi.', 'Sethraliss è la nostra amata Loa.\n\nQuando Mythrax devastò le nostre terre, minacciando la nostra stessa esistenza, fu lei a fermarlo, sacrificando la sua vita per noi.\n\nA differenza dei Senzafede, sentiamo ancora la sua presenza e crediamo che un giorno tornerà da noi.', 28153),
(148982, 'itIT', 'I Custodi erano i più potenti tra noi, incaricati di tenere al sicuro il corpo di Mythrax nella grande piramide.\n\nSulthis fu il fondatore, ma non poteva sigillare la tomba da solo.\n\nChiese a Vorrik e Korthek il loro aiuto e, insieme, eressero una barriera attorno alla grande piramide, sigillando il corpo di Mythrax all\'interno.', '', 28153),
(148981, 'itIT', 'Si fa chiamare Imperatore Korthek, ma molto tempo fa era uno dei Custodi, incaricato di proteggere la tomba.\n\nLa sua sete di guerra va contro tutto ciò che è più caro alla nostra Loa, eppure non fa che insultarla e disonorarla radunando un\'armata che progetta di conquistare tutta Zuldazar.', '', 28153),
(148980, 'itIT', 'Sethraliss è la nostra amata Loa.\n\nQuando Mythrax devastò le nostre terre, minacciando la nostra stessa esistenza, fu lei a fermarlo, sacrificando la sua vita per noi.\n\nA differenza dei Senzafede, sentiamo ancora la sua presenza e crediamo che un giorno tornerà da noi.', '', 28153),
(148979, 'itIT', '', 'Richiedo la tua presenza immediata a Orgrimmar per una missione estremamente urgente. Non farmi attendere.', 28153),
(148978, 'itIT', '', 'Il nostro successo potrebbe dipendere dalle tue abilità.', 28153),
(148977, 'itIT', 'I Senzafede sono un gruppo militante di Sethrak, guidati dall\'Imperatore Korthek.\n\nMolto tempo fa, eravamo uniti, come Sethraliss avrebbe voluto.\n\nSin dal tradimento di Korthek, i Senzafede hanno portato la guerra su queste terre.\n\nNon si fermeranno fin quando non avranno conquistato il mondo intero.', '', 28153),
(148976, 'itIT', '', 'L\'Orda è ora in guerra aperta con l\'Alleanza.', 28153),
(148975, 'itIT', 'Quest\'isola sta buttando fuori un\'enorme quantità di Azerite. Ce ne dovrebbe essere un bel po\' qui vicino.', '', 28153),
(148974, 'itIT', 'Il Rilevatore d\'Azerite è attivo! Ora dovremmo avere una panoramica dell\'intera isola.', '', 28153),
(148973, 'itIT', 'Sethraliss è la nostra amata Loa.\n\nQuando Mythrax devastò le nostre terre, minacciando la nostra stessa esistenza, fu lei a fermarlo, sacrificando la sua vita per noi.\n\nA differenza dei Senzafede, sentiamo ancora la sua presenza e crediamo che un giorno tornerà da noi.', '', 28153),
(148972, 'itIT', 'Si fa chiamare Imperatore Korthek, ma molto tempo fa era uno dei Custodi, incaricato di proteggere la tomba.\n\nLa sua sete di guerra va contro tutto ciò che è più caro alla nostra Loa, eppure non fa che insultarla e disonorarla radunando un\'armata che progetta di conquistare tutta Zuldazar.', '', 28153),
(148971, 'itIT', 'Non dimenticheremo mai ciò che il Loa ha fatto per noi.', 'Non dimenticheremo mai ciò che il Loa ha fatto per noi.', 28153),
(148970, 'itIT', '', 'Ti ringrazio. Li aiutanti miei nun vedono l\'ora di esaminare i testi. Spero che riescano a decifrare qualcosa di utile da usare contro il Dio del Sangue.', 28153),
(148969, 'itIT', '', 'Chest\'installazione potrebbe darci delle informazioni utili per imprigionare o distruggere G\'huun. Cerca qualsiasi reliquia o testo che potrebbe farci comodo.', 28153),
(148968, 'itIT', 'La nostra fede ci mantiene forti.', 'La nostra fede ci mantiene forti.', 28153),
(148966, 'itIT', 'Difenderemo il tempio a ogni costo.', 'Difenderemo il tempio a ogni costo.', 28153),
(148965, 'itIT', 'Non abbandoneremo questo tempio.', 'Non abbandoneremo questo tempio.', 28153),
(148962, 'itIT', 'A ship enters the dungeon. Pike expresses grave concern as to why a ship bearing villagers would enter his order\'s sanctum.', 'A ship enters the dungeon. Pike expresses grave concern as to why a ship bearing villagers would enter his order\'s sanctum.', 28153),
(148959, 'itIT', 'Cosa?', 'Cosa?', 28153),
(148958, 'itIT', 'Qui lo sento molto bene. Qualcosa di oscuro si sta destando.', '', 28153),
(148955, 'itIT', 'Mi domando cosa stesse facendo papà qui sotto...', '', 28153),
(148954, 'itIT', 'Dobbiamo andarcene. Posso farci oltrepassare le guardie.\n\nFammi sapere quando vuoi procedere.', '', 28153),
(148953, 'itIT', 'Fate largo!', '', 28153),
(148952, 'itIT', 'Sulla destra! Ho visto una via d\'uscita!', '', 28153),
(148946, 'itIT', 'Bene! Chesti materiali saranno ottimi per creare frecce e imbottiture per armature.', '', 28153),
(148945, 'itIT', 'Nazmir è pericolosa assai, ma ci stanno innumerevoli risorse se sai dove guardare. Sfrutta la fauna lungo la costa e trova ciò che ci serve per rifornire le truppe.', '', 28153),
(148944, 'itIT', 'Cosa facciamo, $p?!?', '', 28153),
(148943, 'itIT', '', 'Jinx!', 28153),
(148942, 'itIT', '', 'Dovresti fare rapporto a Theock! Sarà sicuramente felice di sapere che la miniera è sotto controllo.', 28153),
(148941, 'itIT', '', 'Ce l\'abbiamo fatta!', 28153),
(148940, 'itIT', '', 'Schiatto... così lontana... da... G\'huun...?', 28153),
(148939, 'itIT', '', 'SANGUE PER G\'HUUN!', 28153),
(148938, 'itIT', 'Ci rivediamo al laboratorio!', 'Ci rivediamo al laboratorio!', 28153),
(148936, 'itIT', 'Il tempio è poco più avanti.', '', 28153),
(148935, 'itIT', 'Faremo tutto il possibile per fermarlo.', '', 28153),
(148934, 'itIT', 'Lui li guida in combattimento, in cerca delle chiavi per abbattere la barriera che circonda Atul\'aman e usare ciò che vi è nascosto all\'interno per conquistare tutta Zuldazar.', '', 28153),
(148933, 'itIT', 'Dal tradimento di Korthek, i Senzafede hanno portato la guerra in queste terre.', '', 28153),
(148932, 'itIT', 'Molto tempo fa... vivevamo uniti, come il nostro Loa avrebbe voluto.', '', 28153),
(148931, 'itIT', 'Il nostro tempio è l\'ultima difesa contro i Senzafede.', '', 28153),
(148930, 'itIT', 'Guerrieri dell\'Orda, ascoltate il richiamo della battaglia! Date ai nemici una morte rapida.', '', 28153),
(148929, 'itIT', 'Hai la faccia di $guno:una; che vorrebbe un Tortolliano, non è vero?', 'Hai la faccia di $guno:una; che vorrebbe un Tortolliano, non è vero?', 28153),
(148928, 'itIT', 'Venite, prendetevi un Tortolliano! Potete tenerlo vivo o usare il loro guscio come portagioie.', 'Venite, prendetevi un Tortolliano! Potete tenerlo vivo o usare il loro guscio come portagioie.', 28153),
(148927, 'itIT', 'Qualche altra offerta? Tortolliani appena catturati dal loro pellegrinaggio a Nazmir!', 'Qualche altra offerta? Tortolliani appena catturati dal loro pellegrinaggio a Nazmir!', 28153),
(148925, 'itIT', 'Non avrete altra occasione di trovare dei Vulpera come questi!', 'Non avrete altra occasione di trovare dei Vulpera come questi!', 28153),
(148924, 'itIT', 'Comprate il vostro Vulpera, hanno un sacco di energie!', 'Comprate il vostro Vulpera, hanno un sacco di energie!', 28153),
(148923, 'itIT', 'Qualche offerta per un Vulpera? Vi servirà a dovere!', 'Qualche offerta per un Vulpera? Vi servirà a dovere!', 28153),
(148922, 'itIT', 'I Senzafede devono essere fermati!', 'I Senzafede devono essere fermati!', 28153),
(148921, 'itIT', 'Dovrei riuscire a trovare la strada di casa.', 'Dovrei riuscire a trovare la strada di casa.', 28153),
(148920, 'itIT', 'Grazie! Da qui in poi, posso farcela da solo.', 'Grazie! Da qui in poi, posso farcela da sola.', 28153),
(148919, 'itIT', 'Vendica chi non abbiamo potuto salvare.', 'Vendica chi non abbiamo potuto salvare.', 28153),
(148918, 'itIT', 'Non hai idea di quello che ci hanno fatto passare...', 'Non hai idea di quello che ci hanno fatto passare...', 28153),
(148917, 'itIT', 'Fai attenzione. Ti stai dirigendo proprio verso la loro tana.', '', 28153),
(148916, 'itIT', 'Troviamoci lì quando avrai recuperato la pietra di Korthek.', '', 28153),
(148910, 'itIT', 'Osi mettere piede su chesta sacra terra?', 'Osi mettere piede su chesta sacra terra?', 28153),
(148909, 'itIT', 'La pagherai per chesto!', 'La pagherai per chesto!', 28153),
(148908, 'itIT', 'Accà nun ci sta posto per l\'Alleanza!', 'Accà nun ci sta posto per l\'Alleanza!', 28153),
(148907, 'itIT', 'La Riserva appartiene alli Zandalari!', 'La Riserva appartiene alli Zandalari!', 28153),
(148906, 'itIT', 'Avanti, perdiamo pure tempo a discuterne.', '', 28153),
(148905, 'itIT', '', 'Fuori, se il Troll dice la verità.', 28153),
(148904, 'itIT', 'Ehi, chesto dove porta?', '', 28153),
(148903, 'itIT', '', 'Tiene n\'odore... spiacevole.', 28153),
(148902, 'itIT', '', 'I Troll del Sangue impareranno che nun ci nasconderemo più da loro. Bel lavoro.', 28153),
(148901, 'itIT', '', 'Argh... qualcuno... li fermi...', 28153),
(148900, 'itIT', '', 'Nessuno coglie alla sprovvista la VII Legione. Morite, feccia!', 28153),
(148899, 'itIT', '', 'Li esploratori miei dicono che i Troll del Sangue si stanno radunando accà. Mostra loro cosa succede a chi si oppone alli Zandalari.', 28153),
(148898, 'itIT', '', 'Non andrete da nessuna parte!', 28153),
(148897, 'itIT', '', 'È un campo di annullamento. Non posso lanciare incantesimi!', 28153),
(148896, 'itIT', 'Chillo vudù è davvero terribile. Thalyssra?', '', 28153),
(148895, 'itIT', '', 'Ho bisogno di un attimo. Sono ore che cerco di aprire questa gabbia.', 28153),
(148894, 'itIT', '', 'Non disssolverete mai la mia maledizione!', 28153),
(148893, 'itIT', 'Tutte queste bestie potrebbero un giorno essere al servizio dell\'Orda. Non possiamo permetterlo.', '', 28153),
(148892, 'itIT', 'Le bestie recupereranno presto le loro perdite, ma ci vorrà molto più tempo perché l\'Orda trovi dei nuovi Custodi delle Bestie. Ben fatto!', '', 28153),
(148891, 'itIT', 'La Riserva degli Zandalari è piena di bestie da guerra, pericolose solo a causa del loro addestramento. Avvelenale, così da attirare allo scoperto i Custodi delle Bestie. Sono loro il tuo vero obiettivo.', '', 28153),
(148890, 'itIT', '', 'Sarà meglio che tu tenga ragione, Zul.', 28153),
(148889, 'itIT', 'Sarebbe n\'errore. Sta dall\'altra parte.', '', 28153),
(148888, 'itIT', 'Di qua!', '', 28153),
(148887, 'itIT', '', 'Come ce ne andiamo da accà?', 28153),
(148886, 'itIT', '', 'Grazie a te, abbiamo fatto n\'altro passo per fermare chesti Troll del Sangue per sempre.', 28153),
(148885, 'itIT', '', 'Percepisco nu mojo oscuro accà. Devono essere i Troll del Sangue! Trovali e ferma chello che stanno facendo!', 28153),
(148884, 'itIT', '', 'Dobbiamo muoverci!', 28153),
(148883, 'itIT', '', 'Rinchiudeteli!', 28153),
(148879, 'itIT', 'Le nubi si diradano... La tempesta tace...', '', 28153),
(148878, 'itIT', 'Sono l\'araldo delle tempeste!', '', 28153),
(148877, 'itIT', 'I saluti dovranno attendere.', '', 28153),
(148876, 'itIT', '', 'Siamo qui a nome dell\'Orda. Sono Thalyssra, e questo è Rokhan.', 28153),
(148875, 'itIT', '', 'Mmm... grazie. Il Profeta mio dice che siete alleati.', 28153),
(148874, 'itIT', 'Ahahah, e jamme, cumpà. Lo so chi sei. Sei chella serpe che...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148872, 'itIT', 'Ah, è arrivata la scorta nostra. Come avevo detto, principessa.', '', 28153),
(148871, 'itIT', 'Andiamo. Da chesta parte.', '', 28153),
(148870, 'itIT', 'Mi serve un attimo per riprendere fiato.', '', 28153),
(148868, 'itIT', 'Korthek crede di potersi nascondere dietro un muro? Sempre il solito stolto.', '', 28153),
(148867, 'itIT', 'Attieniti al piano. Ti raggiungo dopo.', '', 28153),
(148858, 'itIT', '', 'Capisco... Se ne sei certo, Gran Supremo.', 28153),
(148857, 'itIT', 'No. Lok\'tar.', '', 28153),
(148856, 'itIT', 'Tu nun verrai con noi.', '', 28153),
(148855, 'itIT', 'Sappiamo entrambi che non sei qui per me. Quelli che cerchi sono nella sala principale.', '', 28153),
(148854, 'itIT', 'In base ai rapporti, il momento migliore per colpire l\'imperatore è durante la sua visita al mercato, che si trova qui vicino.', '', 28153),
(148853, 'itIT', 'Credo che sarebbe meglio se lo prendessi tu.', '', 28153),
(148852, 'itIT', '', 'Noi attireremo la loro attenzione. Sta\' in guardia.', 28153),
(148851, 'itIT', 'Io vado avanti in cerca dei prigionieri. Copritemi le spalle.', '', 28153),
(148850, 'itIT', 'La VII Legione sta accà. Chiunque riusciremo a liberare, li Umani nun terranno scampo.', '', 28153),
(148849, 'itIT', 'Io vi raggiungerò. Buona fortuna.', '', 28153),
(148848, 'itIT', 'Quella è la nostra via d\'uscita. Raggiungete la nave, una volta salvati i prigionieri.', '', 28153),
(148847, 'itIT', 'Ho fornito a ognuno di voi un modo veloce per morire. Usatelo, in caso non abbiate altra scelta.', '', 28153),
(148846, 'itIT', 'La Capoguerra e l\'Orda negheranno di essere a conoscenza della missione, qualora veniate catturati.', '', 28153),
(148845, 'itIT', 'Gli esploratori hanno trovato un\'entrata segreta. Io e il Tauren vi copriremo le spalle.', '', 28153),
(148844, 'itIT', 'Tu, Thalyssra e Rokhan vi infiltrerete nelle Segrete di Roccavento per liberare i prigionieri.', '', 28153),
(148843, 'itIT', 'Ascoltate attentamente. Non potremo comunicare una volta che sarete dentro Roccavento.', '', 28153),
(148842, 'itIT', '', 'Ci assicureremo che i Verrospino non dichiarino più guerra su così vasta scala.', 28153),
(148841, 'itIT', 'La tua fine... si avvicina...', 'La tua fine... si avvicina...', 28153),
(148840, 'itIT', 'Come... è... possibile...', 'Com\'è... possibile...', 28153),
(148839, 'itIT', 'Affronterai... l\'occhio... del ciclone...', 'Affronterai... l\'occhio... del ciclone...', 28153),
(148838, 'itIT', 'Anche tu... cadrai...', 'Tu... cadrai...', 28153),
(148837, 'itIT', 'La mia anima... fluirà... nel mare.', 'La mia anima... fluirà... nel mare.', 28153),
(148836, 'itIT', 'Mi incammino... sotto... le maree...', 'Mi incammino... sotto le maree...', 28153),
(148835, 'itIT', 'Ritorno... agli abissi...', 'Ritorno... agli abissi...', 28153),
(148834, 'itIT', 'Persino le maree... recedono...', 'Persino le maree... recedono...', 28153),
(148833, 'itIT', 'Il suo potere mi scorre nelle vene!', 'Il suo potere scorre nelle mie vene!', 28153),
(148832, 'itIT', 'Accogli la tua fine!', 'Accogli la tua fine!', 28153),
(148831, 'itIT', 'I tentacoli del fato ti reclamano!', 'I tentacoli del fato ti reclamano!', 28153),
(148830, 'itIT', 'Di te non rimarrà che un guscio senza vita!', 'Di te non rimarrà che un guscio senza vita!', 28153),
(148829, 'itIT', 'Annegherai mentre la tua luce svanisce!', 'Annegherai mentre la tua luce svanisce!', 28153),
(148828, 'itIT', 'Nessuno può fermare la marea infinita!', 'Nessuno può fermare la marea infinita!', 28153),
(148827, 'itIT', 'Ascolta il richiamo degli abissi!', 'Ascolta il richiamo degli abissi!', 28153),
(148826, 'itIT', 'Il mare ti spazzerà via!', 'Il mare ti spazzerà via!', 28153),
(148825, 'itIT', 'È così... buio...', 'È così... buio...', 28153),
(148824, 'itIT', 'Uh... maree... Ugh... accoglietemi...', 'Maree... accoglietemi...', 28153),
(148823, 'itIT', 'Almeno... muoio... libero...', 'Almeno... muoio... libera...', 28153),
(148822, 'itIT', 'Come hai... fatto...', 'Come... hai... fatto...', 28153),
(148821, 'itIT', 'Non... così...', 'Non... così...', 28153),
(148820, 'itIT', 'Mi ricompenseranno profumatamente per la tua pelle!', 'Mi ricompenseranno profumatamente per la tua pelle!', 28153),
(148819, 'itIT', 'Ripulirò il ponte con la tua faccia!', 'Ripulirò il ponte con la tua faccia!', 28153),
(148818, 'itIT', 'Fatti avanti!', 'Fatti avanti!', 28153),
(148817, 'itIT', 'Sarà una bella storia da raccontare in locanda!', 'Sarà una bella storia da raccontare alla locanda!', 28153),
(148816, 'itIT', 'Te ne pentirai!', 'Te ne pentirai!', 28153),
(148815, 'itIT', 'Il traghettatore... mi chiama...', 'Il traghettatore... mi chiama...', 28153),
(148814, 'itIT', 'Maree... accoglietemi...', 'Maree... accoglietemi...', 28153),
(148813, 'itIT', 'Almeno... muoio... libero...', 'Almeno... muoio... libera...', 28153),
(148812, 'itIT', 'Il mare... avrà... ciò che gli spetta...', 'Il mare... avrà... ciò che gli spetta...', 28153),
(148811, 'itIT', 'Il destino... mi chiama...', 'Il destino... mi chiama...', 28153),
(148810, 'itIT', 'Un altro trofeo per la mia collezione!', 'Un altro trofeo per la mia collezione!', 28153),
(148809, 'itIT', '', 'Qui possiamo parlare liberamente. Lo stesso non vale per Orgrimmar.', 28153),
(148808, 'itIT', 'Userò le tue interiora come esche!', 'Userò le tue interiora come esche!', 28153),
(148807, 'itIT', 'Fatti sotto!', 'Fatti sotto!', 28153),
(148806, 'itIT', '', 'Perdona la messinscena, $n. Mathias Shaw ha inviato un gran numero di spie.', 28153),
(148805, 'itIT', 'Brinderò alla tua morte alla locanda!', 'Brinderò alla tua morte alla locanda!', 28153),
(148804, 'itIT', 'Te ne pentirai.', 'Te ne pentirai.', 28153),
(148803, 'itIT', '', 'Ehi! Fammi uscire di qui!', 28153),
(148802, 'itIT', 'Torna al lavoro, verme!', 'Torna al lavoro, verme!', 28153),
(148801, 'itIT', 'Un giorno... la... pagherai...', 'Un giorno... la... pagherai...', 28153),
(148800, 'itIT', 'Questa... è... insubordinazione...', 'Questa... è... insubordinazione...', 28153),
(148799, 'itIT', 'Ti sollevo... dall\'incarico...', 'Ti... sollevo... dall\'incarico...', 28153),
(148798, 'itIT', 'Non è facile... trovare... un aiuto valido...', 'Non è facile... trovare... un aiuto valido...', 28153),
(148797, 'itIT', 'Ti farò rapporto... per questo...', 'Ti farò rapporto... per questo...', 28153),
(148796, 'itIT', 'Ohhh... maledizione...', 'Ohhh... maledizione...', 28153),
(148795, 'itIT', 'Non sai fare... di meglio...? Ohhh...', 'Non sai fare... di meglio...?', 28153),
(148794, 'itIT', 'Inutile... verme...', 'Inutile... verme...', 28153),
(148793, 'itIT', 'Ho forse detto di fermarti?!?', 'Ho forse detto di fermarti?!?', 28153),
(148792, 'itIT', 'Grrr, di te farò un esempio per tutti!', 'Di te farò un esempio per tutti!', 28153),
(148791, 'itIT', 'La pausa è finita, pidocchio!', 'La pausa è finita, pidocchio!', 28153),
(148790, 'itIT', 'Ti pentirai di avermi disobbedito!', 'Ti pentirai di avermi disobbedito!', 28153),
(148789, 'itIT', 'Osi uscire dai ranghi?!?', 'Osi uscire dai ranghi?!?', 28153),
(148788, 'itIT', 'Pagherai per la tua insubordinazione!', 'Pagherai per la tua insubordinazione!', 28153),
(148787, 'itIT', 'Devo metterti in riga!', 'Devo metterti in riga!', 28153),
(148786, 'itIT', 'Filiamo di qui!', '', 28153),
(148785, 'itIT', '', 'Serrik, per fortuna sei tornato! I Senzafede hanno preso Vorrik!', 28153),
(148783, 'itIT', '', 'Lasciaci la stanza.', 28153),
(148782, 'itIT', '', 'Ahhh, $n. Grazie per aver risposto prontamente.', 28153),
(148781, 'itIT', '', 'Algerson sta abbattendo le foreste! Non possiamo lasciare che questo abuso della natura continui!', 28153),
(148780, 'itIT', 'Dobbiamo incontrarci con il Loa. Sei $gpronto:pronta;?', '', 28153),
(148779, 'itIT', 'La statua si trova da qualche parte nelle rovine del tempio...', '', 28153),
(148778, 'itIT', 'Dobbiamo eliminare i ragni prima che la tribù possa trovare rifugio qui.', '', 28153),
(148775, 'itIT', 'Dobbiamo avvisare la tribù di ciò che abbiamo scoperto!', '', 28153),
(148774, 'itIT', 'Temo che la nostra tribù rimarrà presto senza cibo...', '', 28153),
(148773, 'itIT', 'Dobbiamo scoprire cosa stessero cercando quei Naga...', '', 28153),
(148772, 'itIT', 'I miei calcoli... Non capisco...', 'I miei calcoli... Non capisco...', 28153),
(148771, 'itIT', '<Sospira> Non me ne andrò mai di qui.', '<Sospira> Non me ne andrò mai di qui.', 28153),
(148770, 'itIT', 'Se solo avessi gli ingredienti giusti...', 'Se solo avessi gli ingredienti giusti...', 28153),
(148769, 'itIT', 'Finalmente! Sono libero!', 'Finalmente! Sono libera!', 28153),
(148767, 'itIT', 'Comunque, rimane ancora una cosa da fare. Parla con me quando vorrai affrontare l\'armata degli Spiratempesta.', '', 28153),
(148766, 'itIT', 'Ora posso accettare i Tortaka come seguaci. Questo tempio sarà per sempre un luogo di rifugio per la loro tribù.', '', 28153),
(148765, 'itIT', 'Hai infranto la maledizione di Mepjila e portato pace alle anime dei miei antichi seguaci.', '', 28153),
(148764, 'itIT', 'E il buon marinaio perdette le... aspetta, com\'era? La pelle. Perdette la pelle.', '', 28153),
(148763, 'itIT', 'Il suo amore fuggì ed ella prese il pugnale...', '', 28153),
(148762, 'itIT', 'Nello stomaco aveva gioiose farfalle...', '', 28153),
(148761, 'itIT', 'C\'era a Boralus una donna speciale...', '', 28153),
(148760, 'itIT', 'Ora va\'. Non ha senso trascinare l\'ancora.', '', 28153),
(148759, 'itIT', 'Non saltare il turno di vedetta.', '', 28153),
(148758, 'itIT', 'Vai pure.', '', 28153),
(148757, 'itIT', 'Che può fare questo vecchio per te?', '', 28153),
(148756, 'itIT', 'Fatti gli affari tuoi.', '', 28153),
(148755, 'itIT', 'Sputa il rospo.', '', 28153),
(148754, 'itIT', 'Muoio per la mia casata...', 'Muoio per la mia casata...', 28153),
(148753, 'itIT', 'Kul Tiras resiste...', 'Kul Tiras resiste...', 28153),
(148752, 'itIT', 'Gettate le mie ossa... nel mare...', 'Gettate le mie ossa... nel mare...', 28153),
(148751, 'itIT', 'Vado a fondo... con la nave...', 'Vado a fondo... con la nave...', 28153),
(148750, 'itIT', 'Mi hanno... affondato...', 'Mi hanno... affondata...', 28153),
(148749, 'itIT', 'Pendaglio da forca!', 'Pendaglio da forca!', 28153),
(148748, 'itIT', 'Dimostra quanto vali!', 'Vediamo quanto vali!', 28153),
(148747, 'itIT', 'Non muoverti!', 'Non muoverti!', 28153),
(148746, 'itIT', 'Ti aprirò da parte a parte!', 'Ti aprirò da parte a parte!', 28153),
(148745, 'itIT', 'Per Kul Tiras!', 'Per Kul Tiras!', 28153),
(148744, 'itIT', 'Muoio... per la mia casata...', 'Muoio... per la mia casata...', 28153),
(148743, 'itIT', 'Kul Tiras resiste...', 'Kul Tiras... resiste...', 28153),
(148742, 'itIT', 'Gettate le mie ossa... in mare...', 'Gettate le mie ossa... in mare...', 28153),
(148741, 'itIT', 'Affondo... con la nave...', 'Affondo... con la nave...', 28153),
(148740, 'itIT', 'Mi hanno... affondato...', 'Mi hanno... affondata...', 28153),
(148739, 'itIT', 'Pendaglio da forca!', 'Pendaglio da forca!', 28153),
(148738, 'itIT', 'Dimostra quanto vali!', 'Dimostra quanto vali!', 28153),
(148737, 'itIT', 'Fermo, intruso!', 'Fermo, intruso!', 28153),
(148736, 'itIT', 'Ti aprirò da parte a parte!', 'Ti aprirò da parte a parte!', 28153),
(148735, 'itIT', 'Per Kul Tiras!', 'Per Kul Tiras!', 28153),
(148734, 'itIT', 'Gioite! La Strega del Mare Mepjila è stata sconfitta!', 'Gioite! La Strega del Mare Mepjila è stata sconfitta!', 28153),
(148733, 'itIT', 'Ce l\'avete fatta! Il tempio è salvo!', 'Ce l\'avete fatta! Il tempio è salvo!', 28153),
(148732, 'itIT', 'Mepjila è stata sconfitta! Siamo salvi!', 'Mepjila è stata sconfitta! Siamo salvi!', 28153),
(148731, 'itIT', 'I Naga sono troppo forti! Nun possiamo reggere ancora a lungo!', 'I Naga sono troppo forti! Nun possiamo reggere ancora a lungo!', 28153),
(148730, 'itIT', 'Dove sta Eraka no Kimbul? Il tempio è stato invaso!', 'Dove sta Eraka no Kimbul? Il tempio è stato invaso!', 28153),
(148729, 'itIT', 'Il tempio è sotto attacco! Dobbiamo evocare il Loa!', 'Il tempio è sotto attacco! Dobbiamo evocare il Loa!', 28153),
(148728, 'itIT', '', 'Scommetto che sei per metà Goblin.', 28153),
(148727, 'itIT', '', 'Più esplosioni!', 28153),
(148726, 'itIT', '', 'La libertà... è evanescente...', 28153),
(148725, 'itIT', '', 'Mmm, ti venderò a caro prezzo.', 28153),
(148724, 'itIT', 'Addosso!', 'Addosso!', 28153),
(148723, 'itIT', 'Ti mostro io come ci si comporta!', 'Ti mostrerò io come ci si comporta!', 28153),
(148722, 'itIT', 'Per la gloria di Kul Tiras!', 'Per la gloria di Kul Tiras!', 28153),
(148721, 'itIT', 'Difenditi, canaglia!', 'Difenditi, canaglia!', 28153),
(148720, 'itIT', 'Non puoi competere con me!', 'Non puoi competere con me!', 28153),
(148719, 'itIT', 'Impossibile...', 'Impossibile...', 28153),
(148718, 'itIT', 'Ho perso... contro un continentale?', 'Ho perso... contro un continentale?', 28153),
(148717, 'itIT', 'Muoio... con onore...', 'Muoio... con onore...', 28153),
(148716, 'itIT', 'Com\'è potuto... succedere...', 'Com\'è potuto... succedere...', 28153),
(148715, 'itIT', 'Per... Kul... Tiras...', 'Per... Kul... Tiras...', 28153),
(148714, 'itIT', 'Per... Kul... Tiras...', 'Per... Kul... Tiras...', 28153),
(148713, 'itIT', 'L\'unico modo per spezzare la maledizione è distruggere lo spirito di Mepjila.', '', 28153),
(148712, 'itIT', 'Com\'è potuto... succedere...', 'Com\'è potuto... succedere...', 28153),
(148711, 'itIT', 'Muoio... con onore...', 'Muoio... con onore...', 28153),
(148710, 'itIT', 'Gli spiriti dei miei seguaci sono prigionieri di una battaglia eterna.', '', 28153),
(148709, 'itIT', 'Sconfitto... dai continentali?', 'Sconfitta... dai continentali?', 28153),
(148708, 'itIT', 'Impossibile...', 'Impossibile...', 28153),
(148707, 'itIT', 'Non puoi competere con me!', 'Non puoi competere con me!', 28153),
(148706, 'itIT', 'Difenditi, canaglia!', 'Difenditi, canaglia!', 28153),
(148705, 'itIT', 'Per la gloria di Kul Tiras!', 'Per la gloria di Kul Tiras!', 28153),
(148704, 'itIT', 'Ti mostrerò come ci si comporta!', 'Ti mostrerò come ci si comporta!', 28153),
(148703, 'itIT', 'Fatti sotto!', 'Fatti sotto!', 28153),
(148701, 'itIT', 'Questo non c\'era sul mio contratto!', 'Questo non c\'era sul mio contratto!', 28153),
(148700, 'itIT', 'Non mi pagano abbastanza per questo!', 'Non mi pagano abbastanza per questo!', 28153),
(148699, 'itIT', '', 'La sicurezza prima di tutto!', 28153),
(148698, 'itIT', '', 'Mi piace l\'odore del propellente al mattino!', 28153),
(148697, 'itIT', 'È na lunga storia che può aspettare. Presto si incontrerà con Bwonsamdi se nun ci sbrighiamo.', 'È na lunga storia che può aspettare. Presto si incontrerà con Bwonsamdi se nun ci sbrighiamo.', 28153),
(148696, 'itIT', '', 'Ti sei alleata con nu Sethrak?', 28153),
(148695, 'itIT', 'Sto bene, ma l\'amico mio accà nun durerà a lungo.', 'Sto bene, ma l\'amico mio accà nun durerà assai a lungo.', 28153),
(148694, 'itIT', 'L\'Alleanza crede di poter spostare risorse senza lasciarci la nostra fetta? Drom\'kal avrà bisogno di un po\' di volontari all\'Armeria, se vogliamo procedere col piano... e in fretta!', '', 28153),
(148693, 'itIT', 'Ehi! Vedo dei Boscaioli dell\'Alleanza indifesi! Quella Segheria sarà nostra... una volta che li avrete uccisi!', '', 28153),
(148692, 'itIT', 'Uh, non va bene per niente! Scorzasecca in arrivo da est!', '', 28153),
(148691, 'itIT', 'Rimetteremo in sesto questa valle.', 'Rimetteremo in sesto questa valle.', 28153),
(148690, 'itIT', 'Fai molta attenzione là fuori.', 'Fai molta attenzione là fuori.', 28153),
(148689, 'itIT', 'Ricorda l\'onda sacra.', 'Ricorda l\'onda sacra.', 28153),
(148688, 'itIT', 'Non vacilleremo.', 'Non vacilleremo.', 28153),
(148687, 'itIT', 'Sacraonda resisterà.', 'Sacraonda resisterà.', 28153),
(148686, 'itIT', 'Sei molto distante da casa.', 'Sei molto distante da casa.', 28153),
(148685, 'itIT', 'Diffida degli sconosciuti.', 'Diffida degli sconosciuti.', 28153),
(148684, 'itIT', 'Sta\' alla larga dagli intrighi delle streghe.', 'Sta\' alla larga dagli intrighi delle streghe.', 28153),
(148683, 'itIT', 'Gloria alla Casata dei Crestabianca.', 'Gloria alla Casata dei Crestabianca.', 28153),
(148682, 'itIT', 'Ripassa quando vuoi.', 'Ripassa quando vuoi.', 28153),
(148681, 'itIT', 'È stato davvero un piacere.', 'È stato davvero un piacere.', 28153),
(148680, 'itIT', 'Spero di rivederti presto.', 'Spero di rivederti presto.', 28153),
(148679, 'itIT', 'Che i venti ti siano propizi.', 'Che i venti ti siano propizi.', 28153),
(148678, 'itIT', 'Attenzione a ciò che si cela negli abissi.', 'Fa\' attenzione a ciò che si cela negli abissi.', 28153),
(148677, 'itIT', 'Sacraonda sarà nuovamente pura.', 'Sacraonda sarà nuovamente pura.', 28153),
(148676, 'itIT', 'Venti costanti e vele gonfie.', 'Venti costanti e vele gonfie.', 28153),
(148675, 'itIT', 'I Marefiero ci proteggeranno, come sempre.', 'I Marefiero ci proteggeranno, come sempre.', 28153),
(148674, 'itIT', 'Stammi bene.', 'Stammi bene.', 28153),
(148673, 'itIT', 'Buona fortuna.', 'Buona fortuna.', 28153),
(148672, 'itIT', 'Mantieni la calma e continua.', 'Mantieni la calma e continua.', 28153),
(148671, 'itIT', 'Dritti e sicuri.', 'Dritti e sicuri.', 28153),
(148670, 'itIT', 'Che gli affari ti arridano.', 'Che gli affari ti arridano.', 28153),
(148669, 'itIT', 'Dimmi cosa vuoi.', 'Dimmi cosa vuoi.', 28153),
(148668, 'itIT', 'Vieni in pace?', 'Vieni in pace?', 28153),
(148667, 'itIT', 'Mantieni le distanze, continentale.', 'Mantieni le distanze, continentale.', 28153),
(148666, 'itIT', 'Vogliamo parlare d\'affari?', 'Vogliamo parlare d\'affari?', 28153),
(148665, 'itIT', 'Sei qui per negoziare?', 'Sei qui per negoziare?', 28153),
(148664, 'itIT', 'Guarda pure quello che ti pare.', 'Guarda pure quello che ti pare.', 28153),
(148663, 'itIT', 'Le maree ti danno il benvenuto.', 'Le maree ti danno il benvenuto.', 28153),
(148662, 'itIT', 'Vivo per servire coloro che seguono il mare.', 'Vivo per servire coloro che seguono il mare.', 28153),
(148661, 'itIT', 'Affronterò il pericolo.', 'Affronterò il pericolo.', 28153),
(148660, 'itIT', 'Situazione inquietante, nevvero?', 'Situazione inquietante, nevvero?', 28153),
(148659, 'itIT', 'Che novità porti dal continente?', 'Che novità porti dal continente?', 28153),
(148658, 'itIT', 'Temo che non conosceremo mai la pace.', 'Temo che non conosceremo mai la pace.', 28153),
(148657, 'itIT', 'È un piacere fare la tua conoscenza.', 'È un piacere fare la tua conoscenza.', 28153),
(148656, 'itIT', 'Cosa raccontano i venti?', 'Cosa raccontano i venti?', 28153),
(148655, 'itIT', 'A cosa devo il piacere?', 'A cosa devo il piacere?', 28153),
(148654, 'itIT', 'Incantato.', 'Incantata.', 28153),
(148653, 'itIT', 'Ma guarda, come passa il tempo! Chissà quanti altri impegni avrai...', 'Ma guarda... come passa il tempo! Chissà quanti altri impegni avrai...', 28153),
(148652, 'itIT', 'Hai sentito? Qualcuno ti sta chiamando da quella parte. Sembra davvero importante!', 'Hai sentito? Qualcuno ti sta chiamando da quella parte. Sembra davvero importante!', 28153),
(148651, 'itIT', 'Non hai qualcosa, qualsiasi cosa, di meglio da fare?', 'Non hai qualcosa, qualsiasi cosa, di meglio da fare?', 28153),
(148650, 'itIT', 'Cosa posso fare per te?', 'Cosa posso fare per te?', 28153),
(148649, 'itIT', 'In gloria dell\'Ammiraglio Supremo.', 'In gloria dell\'Ammiraglio Supremo!', 28153),
(148648, 'itIT', 'Buona giornata a te.', 'Buona giornata a te.', 28153),
(148647, 'itIT', 'Ah, salve!', 'Salve!', 28153),
(148646, 'itIT', 'Aiuto, aiuto! Mi stanno opprimendo!', 'Aiuto, aiuto! Mi stanno opprimendo!', 28153),
(148645, 'itIT', 'Non mi piace il taglio della tua vela.', 'Non mi piace il taglio della tua vela.', 28153),
(148644, 'itIT', 'Sei una testa calda, non è vero?', 'Sei una testa calda, non è vero?', 28153),
(148643, 'itIT', 'Che il mare ti nutra.', 'Che il mare ti nutra.', 28153),
(148642, 'itIT', 'Ogni percorso ha degli intoppi.', 'Ogni percorso ha degli intoppi.', 28153),
(148641, 'itIT', 'Riprenderemo ciò che ci spetta.', 'Riprenderemo ciò che ci spetta.', 28153),
(148640, 'itIT', 'Le cose un tempo erano più semplici.', 'Le cose un tempo erano più semplici.', 28153),
(148639, 'itIT', 'Ogni mano conta.', 'Ogni mano conta.', 28153),
(148638, 'itIT', 'Non sei di queste parti, vero?', 'Non sei di queste parti, vero?', 28153),
(148637, 'itIT', 'Hai i soldi? Perché io ho la merce.', 'Hai i soldi? Perché io ho la merce.', 28153),
(148636, 'itIT', 'Le migliori merci di Kul Tiras!', 'Le migliori merci di Kul Tiras!', 28153),
(148635, 'itIT', 'Lascia che ti mostri cos\'ho da offrire.', 'Lascia che ti mostri cos\'ho da offrire.', 28153),
(148634, 'itIT', 'Fai buon viaggio.', 'Fai buon viaggio.', 28153),
(148633, 'itIT', 'Apprezzo il tuo favore.', 'Apprezzo il tuo favore.', 28153),
(148632, 'itIT', 'Torna quando vuoi.', 'Torna quando vuoi.', 28153),
(148631, 'itIT', 'Ti auguro un passaggio sicuro.', 'Ti auguro un passaggio sicuro.', 28153),
(148630, 'itIT', 'Che il vento segua le tue vele.', 'Che il vento segua le tue vele.', 28153),
(148629, 'itIT', 'Guarda sempre il mare.', 'Guarda sempre il mare.', 28153),
(148628, 'itIT', 'Buona navigazione.', 'Buona navigazione.', 28153),
(148627, 'itIT', 'Buona giornata a te.', 'Buona giornata a te.', 28153),
(148626, 'itIT', 'Salve!', 'Salve!', 28153),
(148625, 'itIT', 'Salpiamo le ancore.', 'Salpiamo le ancore.', 28153),
(148624, 'itIT', 'Tieni la polvere da sparo asciutta.', 'Tieni la polvere da sparo asciutta.', 28153),
(148623, 'itIT', 'Sempre fedeli.', 'Sempre fedeli.', 28153),
(148622, 'itIT', 'Problemi in vista?', 'Problemi in vista?', 28153),
(148621, 'itIT', 'Siamo vicini al nostro obiettivo.', '', 28153),
(148620, 'itIT', 'Il meglio dei Marefiero, al tuo servizio.', 'Il meglio dei Marefiero, al tuo servizio.', 28153),
(148619, 'itIT', 'Ti auguro un passaggio sicuro.', 'Ti auguro un passaggio sicuro.', 28153),
(148618, 'itIT', 'Che il vento segua le tue vele.', 'Che il vento segua le tue vele.', 28153),
(148617, 'itIT', 'Guarda sempre il mare.', 'Guarda sempre il mare.', 28153),
(148616, 'itIT', 'Buona navigazione.', 'Buona navigazione.', 28153),
(148615, 'itIT', 'Le interiora dei devasauri tengono nu sacco di possibili utilizzi! Puoi bollirle, essiccarle o rosolarle... Forse sto pensando ad altro. Come? È già ora di pranzo?', '', 28153),
(148614, 'itIT', 'Fai buon viaggio.', 'Fai buon viaggio.', 28153),
(148613, 'itIT', 'Apprezzo il tuo favore.', 'Apprezzo il tuo favore.', 28153),
(148612, 'itIT', 'Torna quando vuoi!', 'Torna quando vuoi!', 28153),
(148611, 'itIT', 'La moglie mia dice che i devasauri possono mangiare chello che vogliono! Se fosse vero, allora lo stomaco loro sarebbe duro come il ferro! Recuperamene nu po\', prima che lei se ne accorga.', '', 28153),
(148610, 'itIT', 'Allora... ti interessa qualcosa in particolare?', 'Ti interessa qualcosa in particolare?', 28153),
(148609, 'itIT', 'Hai qualcosa da segnalare?', 'Hai qualcosa da segnalare?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148608, 'itIT', 'Le migliori merci di Kul Tiras!', 'Le migliori merci di Kul Tiras!', 28153),
(148607, 'itIT', 'Niente oggetti rattoppati, qui.', 'Niente oggetti rattoppati, qui.', 28153),
(148606, 'itIT', 'Cosa posso fare per te?', 'Cosa posso fare per te?', 28153),
(148605, 'itIT', 'In gloria dell\'Ammiraglio Supremo!', 'In gloria dell\'Ammiraglio Supremo!', 28153),
(148604, 'itIT', 'Stammi bene.', 'Stammi bene.', 28153),
(148603, 'itIT', 'Buona giornata a te.', 'Buona giornata a te.', 28153),
(148602, 'itIT', 'Vuoi del tè?', 'Vuoi del tè?', 28153),
(148601, 'itIT', 'Evita i vicoli bui.', 'Evita i vicoli bui.', 28153),
(148600, 'itIT', 'Procedi con forza.', 'Procedi con forza.', 28153),
(148599, 'itIT', 'La città è pericolosa di questi tempi.', 'La città è pericolosa di questi tempi.', 28153),
(148598, 'itIT', 'Chiama se trovi qualcosa! Il tuo nome sarà ricordato.', '', 28153),
(148597, 'itIT', 'Se la troviamo, l\'imperatore potrà soggiogare il mondo per la gloria dei Sethrak! Ho sempre desiderato viaggiare.', '', 28153),
(148596, 'itIT', 'Colui che dorme si risveglierà.', '', 28153),
(148595, 'itIT', 'Se dovesse risvegliarsi, nessuno sarebbe più al sicuro.', '', 28153),
(148594, 'itIT', 'Credi ci sia una chiave?', '', 28153),
(148593, 'itIT', 'L\'Imperatore Korthek crede che trovando la chiave, potremo riunire di nuovo i Sethrak.', '', 28153),
(148592, 'itIT', 'Hai sentito?', '', 28153),
(148591, 'itIT', 'Sono occupato con la roba dell\'impero, capo.', '', 28153),
(148590, 'itIT', 'Quei \"devoti\" si inchineranno molto presto.', '', 28153),
(148589, 'itIT', 'Oggi il vento infuria.', 'Oggi il vento infuria.', 28153),
(148588, 'itIT', 'Tutto bene, spero.', 'Tutto bene, spero.', 28153),
(148587, 'itIT', 'Il Sovrintendente dice che la chiave è qui. Prima la troviamo, prima potremo andarcene da questo posto. Mi fa venire i brividi.', '', 28153),
(148586, 'itIT', 'Stammi bene.', 'Stammi bene.', 28153),
(148585, 'itIT', 'I Marefiero ci proteggeranno, come sempre.', 'I Marefiero ci proteggeranno, come sempre.', 28153),
(148584, 'itIT', 'Venti costanti e vele gonfie.', 'Venti costanti e vele gonfie.', 28153),
(148583, 'itIT', 'Temo che non conosceremo mai la pace.', 'Temo che non conosceremo mai la pace.', 28153),
(148582, 'itIT', 'Che novità porti dal continente?', 'Che novità porti dal continente?', 28153),
(148581, 'itIT', 'Situazione inquietante, nevvero?', 'Situazione inquietante, nevvero?', 28153),
(148580, 'itIT', 'Torna a trovarci per nuovi articoli.', 'Torna a trovarci per nuovi articoli.', 28153),
(148579, 'itIT', 'Mi arrivano oggetti esotici tutti i giorni.', 'Mi arrivano oggetti esotici tutti i giorni.', 28153),
(148578, 'itIT', 'Ripassa quando vuoi.', 'Ripassa quando vuoi.', 28153),
(148577, 'itIT', 'Guarda pure quello che ti pare.', 'Guarda pure quello che ti pare.', 28153),
(148576, 'itIT', 'Vieni, negoziamo.', 'Vieni, negoziamo.', 28153),
(148575, 'itIT', 'Questa... non è... la fine...', '', 28153),
(148574, 'itIT', 'È troppo tardi...', '', 28153),
(148573, 'itIT', 'Non ci fermeremo mai...', '', 28153),
(148572, 'itIT', 'Questa terra... sarà nostra...', '', 28153),
(148571, 'itIT', 'Ritorno... a Thros...', '', 28153),
(148570, 'itIT', 'Vogliamo parlare d\'affari?', 'Vogliamo parlare d\'affari?', 28153),
(148569, 'itIT', 'La vendetta sarà nostra!', '', 28153),
(148568, 'itIT', 'Nessuna pietà!', '', 28153),
(148567, 'itIT', 'I Drust rivendicheranno questa terra!', '', 28153),
(148566, 'itIT', 'Ti inchinerai di fronte a Gorak Tul!', '', 28153),
(148565, 'itIT', 'Sono rinato!', '', 28153),
(148564, 'itIT', 'Non hai qualcosa, qualsiasi cosa, di meglio da fare?', 'Non hai qualcosa, qualsiasi cosa, di meglio da fare?', 28153),
(148563, 'itIT', 'Hai sentito? Qualcuno ti sta chiamando da quella parte. Sembra davvero importante!', 'Hai sentito? Io... credo che qualcuno ti sta chiamando da quella parte. Sembra davvero importante!', 28153),
(148562, 'itIT', 'Ma guarda... come passa il tempo! Chissà quanti altri impegni avrai...', 'Ma guarda... come passa il tempo! Chissà quanti altri impegni avrai...', 28153),
(148561, 'itIT', 'Va\' per la tua strada.', 'Va\' per la tua strada.', 28153),
(148560, 'itIT', 'Non perdere la rotta.', 'Non perdere la rotta.', 28153),
(148559, 'itIT', 'Mantieni la calma e continua.', 'Mantieni la calma e continua.', 28153),
(148553, 'itIT', 'Radiamo al suolo questo posto!', 'Uccidiamoli come farebbe Nisha!', 28153),
(148552, 'itIT', 'Buona fortuna.', 'Buona fortuna.', 28153),
(148551, 'itIT', 'Il prossimo Senzafede è mio!', 'Farò buon uso di quest\'arma!', 28153),
(148550, 'itIT', 'È bello avere di nuovo un\'arma in pugno.', 'Impareranno a temere i Vulpera!', 28153),
(148549, 'itIT', 'Incantato.', 'Incantata.', 28153),
(148548, 'itIT', 'A cosa devo il piacere?', 'A cosa devo il piacere?', 28153),
(148547, 'itIT', '', 'Ah, cheste saranno perfette! Nun temere di offendere i sentimenti di Raal, prima o poi supererà la cosa.', 28153),
(148546, 'itIT', '', 'Il marito mio sta facendo di tutto per evitare di andare a recuperare della saliva di pterrordattilo per gli alchimisti. Si sta rammollendo. Vai e recupera tutte le ghiandole che riesci! ', 28153),
(148545, 'itIT', 'Ottimo lavoro, cumpà. I saggi nostri si metteranno subito al lavoro.', '', 28153),
(148544, 'itIT', 'Cosa raccontano i venti?', 'Cosa raccontano i venti?', 28153),
(148543, 'itIT', 'È un piacere fare la tua conoscenza.', 'È un piacere fare la tua conoscenza.', 28153),
(148542, 'itIT', 'Molti Tortolliani sono stati accisi da quei macellai Troll del Sangue, ma possiamo ancora salvare la loro conoscenza. Trova e recupera quante più pergamene puoi!', '', 28153),
(148541, 'itIT', 'Aiuto, aiuto! Mi stanno opprimendo!', 'Aiuto, aiuto! Mi stanno opprimendo!', 28153),
(148540, 'itIT', '', 'Non... può essere...', 28153),
(148539, 'itIT', 'Ah, adesso salta fuori la violenza insita nel sistema!', 'Ah, adesso salta fuori la violenza insita nel sistema!', 28153),
(148538, 'itIT', '', 'La mia magia... ha fallito?', 28153),
(148537, 'itIT', '', 'Mi era stato promesso... il potere...', 28153),
(148536, 'itIT', 'Fin quando le loro anime non saranno libere, non posso accettare nuovi seguaci. L\'onore non me lo permette.', '', 28153),
(148535, 'itIT', 'Stai forse agitando quell\'arma verso di me?', 'Stai forse agitando quell\'arma verso di me?', 28153),
(148534, 'itIT', '', 'Il potere... svanisce...', 28153),
(148533, 'itIT', '', 'Le mie sorelle ti uccideranno...', 28153),
(148532, 'itIT', '', 'Il tuo sangue alimenterà i miei rituali!', 28153),
(148531, 'itIT', '', 'Sarai un degno sacrificio!', 28153),
(148530, 'itIT', '', 'Tutti serviranno le Frangicuore!', 28153),
(148529, 'itIT', '', 'Madre, donami il potere!', 28153),
(148528, 'itIT', 'Ma quando le mie zanne trafissero il cuore del loro capo, ella condannò le anime dei miei seguaci a un eterno tormento.', '', 28153),
(148527, 'itIT', '', 'La mia vita per la congrega!', 28153),
(148526, 'itIT', 'Non mi interessa che sia morta. Una persona in meno sulla mia strada.', '', 28153),
(148525, 'itIT', 'Che arrivasse a convertirsi alla stregoneria oscura per tramare vendetta contro di me...', '', 28153),
(148524, 'itIT', 'Ho dato la caccia ai Naga fino all\'ultimo. Nessuno è sfuggito alla mia ira...', '', 28153),
(148523, 'itIT', 'Il mio lavoro è la mia vita! Non Petula, né Benjamin, questo è il mio retaggio.', '', 28153),
(148522, 'itIT', 'Sono partito dal nulla! Ho iniziato l\'attività per dare supporto a mia moglie e alla mia famiglia.', '', 28153),
(148521, 'itIT', 'Gloria alla Casata dei Crestabianca.', 'Gloria alla Casata dei Crestabianca.', 28153),
(148520, 'itIT', 'Non sono sempre stato il presidente di un\'azienda di falegnameria di successo, sai.', '', 28153),
(148519, 'itIT', 'Stai alla larga dagli intrighi delle streghe.', 'Sta\' alla larga dagli intrighi delle streghe.', 28153),
(148518, 'itIT', 'Diffida degli sconosciuti.', 'Diffida degli sconosciuti.', 28153),
(148517, 'itIT', 'Mantieni le distanze, continentale.', 'Mantieni le distanze, continentale.', 28153),
(148516, 'itIT', 'Vieni in pace?', 'Vieni in pace?', 28153),
(148515, 'itIT', 'Dimmi cosa vuoi.', 'Dimmi cosa vuoi.', 28153),
(148514, 'itIT', 'Secoli fa, questo tempio fu attaccato dai Naga. Arrivai troppo tardi per salvare i miei seguaci dalla sconfitta.', '', 28153),
(148513, 'itIT', 'Provo simpatia per i Tortaka e il loro odio per i Naga, ma non posso proteggerli.', '', 28153),
(148512, 'itIT', 'Che i mari ti siano favorevoli.', 'Che i mari ti siano favorevoli.', 28153),
(148511, 'itIT', 'Ogni percorso ha degli intoppi.', 'Ogni percorso ha degli intoppi.', 28153),
(148510, 'itIT', 'Riprenderemo ciò che ci spetta.', 'Riprenderemo ciò che ci spetta.', 28153),
(148509, 'itIT', 'Un tempo le cose erano più semplici.', 'Un tempo le cose erano più semplici.', 28153),
(148508, 'itIT', 'Ogni mano conta.', 'Ogni mano conta.', 28153),
(148507, 'itIT', 'Non sei di queste parti, vero?', 'Non sei di queste parti, vero?', 28153),
(148506, 'itIT', 'Sacraonda sarà nuovamente pura.', 'Sacraonda sarà nuovamente pura.', 28153),
(148505, 'itIT', 'Guardati da ciò che cova negli abissi.', 'Guardati da ciò che cova negli abissi.', 28153),
(148504, 'itIT', 'Che i venti ti siano propizi.', 'Che i venti ti siano propizi.', 28153),
(148503, 'itIT', 'Dobbiamo superare questo pericolo.', 'Dobbiamo superare questo pericolo.', 28153),
(148502, 'itIT', 'Chi onora il mare è benvenuto.', 'Chi onora il mare è benvenuto.', 28153),
(148501, 'itIT', 'Le maree ti danno il benvenuto.', 'Le maree ti danno il benvenuto.', 28153),
(148500, 'itIT', 'Rimetteremo in sesto questa valle.', 'Rimetteremo in sesto questa valle.', 28153),
(148499, 'itIT', 'Fa\' molta attenzione là fuori.', 'Fai molta attenzione là fuori.', 28153),
(148498, 'itIT', 'Ricorda l\'onda sacra.', 'Ricorda l\'onda sacra.', 28153),
(148497, 'itIT', 'Non vacilleremo.', 'Non vacilleremo.', 28153),
(148496, 'itIT', 'Sacraonda resisterà.', 'Sacraonda resisterà.', 28153),
(148495, 'itIT', 'Sei molto distante da casa.', 'Sei molto distante da casa.', 28153),
(148493, 'itIT', 'Anche tu. E $n, tu possiedi il vero mojo. Vieni a trovarmi, se mai dovessi passare dalle parti di Vol\'dun, vabbuo\'?', '', 28153),
(148492, 'itIT', 'Addio, Jin\'tiki. Cerca di sopravvivere.', '', 28153),
(148491, 'itIT', 'Me ne occupo io.', '', 28153),
(148490, 'itIT', 'Il piano è pronto. Muoviamoci.', '', 28153),
(148489, 'itIT', 'Ahah! Chesta è la cosa più folle che io abbia mai fatto.', '', 28153),
(148488, 'itIT', 'Zulajin è schiattato! Andiamocene da accà.', '', 28153),
(148487, 'itIT', 'Ottimo lavoro! Continua così!', '', 28153),
(148486, 'itIT', 'Bleah!', 'Bleah!', 28153),
(148485, 'itIT', 'Non mi mangiare!', 'Non mi mangiare!', 28153),
(148484, 'itIT', 'Aaah!', 'Aaah!', 28153),
(148483, 'itIT', 'A cosa stava lavorando papà per causare tutto questo?', '', 28153),
(148482, 'itIT', 'Come fa questo ammasso di miele a muoversi da solo?', '', 28153),
(148481, 'itIT', '<Sussulta> Mmm, $p... il miele ha preso vita?!?', '', 28153),
(148480, 'itIT', 'Ti ringrazio, $gstraniero:straniera;.', 'Ti ringrazio, $gstraniero:straniera;.', 28153),
(148479, 'itIT', 'Mi assicurerò che i Sethrak non si portino dietro neanche una briciola quando se ne andranno.', 'Mi assicurerò che i Sethrak non si portino dietro neanche una briciola quando se ne andranno.', 28153),
(148478, 'itIT', 'È ora di giocare a un piccolo gioco chiamato \"Volpi e serpenti\"...', 'È ora di giocare a un piccolo gioco chiamato \"Volpi e serpenti\"...', 28153),
(148477, 'itIT', 'Ohhh! Sono libero! Non mi hai divorato!', 'Ohhh! Sono libera! Non mi hai divorata!', 28153),
(148476, 'itIT', 'Basta, ora voglio il doppio.', 'Basta, ora voglio il doppio.', 28153),
(148475, 'itIT', '', 'È bello vedere che le sabbie non ti hanno ancora divorato, $n!', 28153),
(148473, 'itIT', 'Grande Loa, quest\'offerta viene dalla Tribù Tortaka.', 'Grande Loa, quest\'offerta viene dalla Tribù Tortaka.', 28153),
(148472, 'itIT', 'Mettila giù!', '', 28153),
(148471, 'itIT', 'Non così in fretta!', '', 28153),
(148470, 'itIT', 'Te ne pentirai!', '', 28153),
(148469, 'itIT', 'Io non lo farei, se fossi in te...', '', 28153),
(148468, 'itIT', 'Ridammelo!', '', 28153),
(148467, 'itIT', 'Non credo proprio! È mio.', '', 28153),
(148466, 'itIT', 'Quello non è tuo.', '', 28153),
(148463, 'itIT', 'Pessima decisione.', '', 28153),
(148462, 'itIT', 'Apprezzo sempre un buon combattimento.', '', 28153),
(148461, 'itIT', 'Pagherai per le tue azioni!', '', 28153),
(148460, 'itIT', 'Ehi, tu!', '', 28153),
(148459, 'itIT', 'Te ne pentirai!', '', 28153),
(148458, 'itIT', 'Non oggi!', '', 28153),
(148456, 'itIT', 'Attenzione a dove metti i piedi.', '', 28153),
(148455, 'itIT', 'Il mio cannocchiale si trova sulla cengia inferiore che sovrasta il cratere a nord.', '', 28153),
(148454, 'itIT', '', 'Dinomanzia dei cornofurente! Fantastico! Ora mettiamole fuori dalla portata di Kojo.', 28153),
(148453, 'itIT', '', 'Ho rinvenuto delle vecchie pergamene, ma non ho la minima idea di cosa facciano. Provale tu per me e scopri cosa combinano. Potrebbe essere divertente!', 28153),
(148452, 'itIT', 'Usa il feticcio! Fallo a pezzi!', '', 28153),
(148451, 'itIT', 'SCAPPA!', '', 28153),
(148450, 'itIT', 'AAAHHH!', '', 28153),
(148449, 'itIT', 'Uh... ci sta qualcosa che nun va. Sento della terribile magia del sangue provenire da lì.', '', 28153),
(148448, 'itIT', 'Ce l\'hai fatta! Chesta sarà la fine per Zulajin.', '', 28153),
(148447, 'itIT', 'Ahah! Devo assolutamente raccontarlo a Pa\'ku!', '', 28153),
(148446, 'itIT', 'I Nobili Oscuri tengono n\'idea su come gestire li invasori a Xibala. Sarà divertente assai.', '', 28153),
(148420, 'itIT', '', 'Ottimo lavoro. Forse un giorno queste acque saranno di nuovo sicure.', 28153),
(148419, 'itIT', '', 'Basta cantare voi due!', 28153),
(148418, 'itIT', '', 'Bene, stiamo tutti accà. Nun perdiamo altro tempo.', 28153),
(148416, 'itIT', 'Grazie, cumpà. Quei Troll del Sangue si sono meritati ogni colpo contro di loro!', '', 28153),
(148415, 'itIT', 'Quei degenerati stanno dissacrando il corpo di nu Loa. Mo\' basta! Massacrali!', '', 28153),
(148414, 'itIT', '', 'Chi è il mordifacce Zandalari più bravo di tutti quanti? Sì, sei tu!', 28153),
(148413, 'itIT', '', 'I potenti alleati nostri devono imparare ad affrontare i nemici delli Zandalari. Aiuta chisto piccirillo a muoversi in battaglia.', 28153),
(148412, 'itIT', 'E così fu detto:\n\nun giorno, il grande Loa si rivolse a un gruppo di suoi seguaci e così parlò:\n\ncome il giaguaro insegue la sua preda per giorni e giorni, anche il più saggio agisce con pazienza in ogni situazione. Gli stolti sono trascinati dalla bramosia e dalle emozioni, ma non sopravvivrebbero a lungo nella giungla.\n\nProprio come la giungla sa concedere il dono della vita, lo stesso vale per il tocco della morte. I più saggi sanno di non possedere la natura, ma di essere al suo servizio. Coloro che rispettano l\'ordine naturale delle cose, prendono solo lo stretto necessario per vivere.\n\nNell\'ascoltare quelle parole, i seguaci di Eraka no Kimbul si sentirono colmi di pazienza e rispetto.', '', 28153),
(148411, 'itIT', 'E così fu detto:\n\nun giorno, il grande Loa si rivolse a un gruppo di suoi seguaci e così parlò:\n\ncome un sovrano non può barattare il suo più grande tesoro per una semplice manciata di terra, anche i più onorevoli non possono barattare la propria integrità per ricchezze o fama. Vivi una vita onorevole, e sarà una vita degna di essere vissuta.\n\nCome i canyon sono plasmati dal costante scorrere dell\'acqua, anche le gesta più grandi nascono dalla perseveranza. Vivi con una determinazione incrollabile e il fallimento non ti sconfiggerà mai.\n\nNell\'ascoltare quelle parole, i seguaci di Eraka no Kimbul si sentirono colmi di virtù e dedizione.', '', 28153),
(148410, 'itIT', 'E così fu detto:\n\nun giorno, il grande Loa si rivolse a un gruppo di suoi seguaci e così parlò:\n\ncome la tigre balza tra rocce e ostacoli durante una caccia, anche i più coraggiosi non devono sprecare tempo di fronte al volto della paura. Agisci con coraggio in ogni situazione e non perderai mai di vista la tua preda.\n\nProprio come la decomposizione divora i germogli della giungla, anche l\'età divora la forza della giovinezza. La vera fonte del potere non sta nella forza, ma nell\'indomabile volontà che l\'età non può distruggere.\n\nNell\'ascoltare quelle parole, i seguaci di Eraka no Kimbul si sentirono colmi di coraggio e convinzione.', '', 28153),
(148408, 'itIT', 'Eraka no Kimbul, il Loa delle Tigri, Signore delle Bestie, Re dei Felini e Flagello delle Prede!', '', 28153),
(148400, 'itIT', 'Ho cicatrici più vecchie della lingua che parli.', '', 28153),
(148399, 'itIT', 'Mi serve qualcuno giovane, con la schiena sana e pronto a combattere le forze del male... per profitto, ovviamente. Eh eh eh!', '', 28153),
(148398, 'itIT', '', 'Sei qua per parlare con la vecchia Nola?', 28153),
(148397, 'itIT', 'Sto lavorando!', 'Sto lavorando!', 28153),
(148396, 'itIT', 'Non sarà bello per voi quando saremo liberi...', 'Non sarà bello per voi quando saremo liberi...', 28153),
(148395, 'itIT', 'Va bene! Va bene!', 'Va bene! Va bene!', 28153),
(148394, 'itIT', 'Argh! Via da me!', 'Argh! Via da me!', 28153),
(148393, 'itIT', '<Sembra ci siano dei segni sulla statua. Il loro significato, se mai ne avessero avuto uno, è andato perduto molto tempo fa.>', '', 28153),
(148392, 'itIT', '<Sembra ci siano dei segni sulla statua. Il loro significato, se mai ne avessero avuto uno, è andato perduto molto tempo fa.>', '<Sembra ci siano dei segni sulla statua. Il loro significato, se mai ne avessero avuto uno, è andato perduto molto tempo fa.>', 28153),
(148391, 'itIT', '<Sembra ci siano dei segni sulla statua. Il loro significato, se mai ne avessero avuto uno, è andato perduto molto tempo fa.>', '', 28153),
(148389, 'itIT', 'Sulthis venne assassinato, ma non prima di aver messo al sicuro la sua chiave. Io e gli altri ancora leali a Sethraliss fummo costretti a lasciare le nostre case e a nasconderci. È da quel giorno che combattiamo i Senzafede.', '', 28153),
(148388, 'itIT', 'Korthek radunò un\'armata di seguaci Sethrak e iniziò a massacrare chiunque si opponesse a loro.', '', 28153),
(148387, 'itIT', '', 'Dobbiamo avvertire la Principessa.', 28153),
(148386, 'itIT', '', 'N\'arma... dev\'essere chesto che Jakra\'zet sta cercando! Nu C\'thrax...', 28153),
(148385, 'itIT', 'Complottò segretamente di riportare alla luce il C\'thrax per usarlo come arma e conquistare il continente.', '', 28153),
(148384, 'itIT', 'Col passare degli anni, Korthek si stufò di seguire il nostro stile di vita. Anche se eravamo sempre rimasti in pace con i nostri vicini Troll, Korthek bramava la guerra.', '', 28153),
(148383, 'itIT', 'Per anni vivemmo in pace, come Sethraliss avrebbe voluto. La nostra terra era in rovina, il nostro Loa sparito, ma ci adattammo. Sapevamo che un giorno sarebbe tornata.', '', 28153),
(148382, 'itIT', 'Per assicurarci che la barriera non potesse essere abbattuta facilmente, ognuno di noi creò una chiave. La magia della barriera poteva essere infranta solo in presenza di tutte e tre le chiavi. Così nacquero i Custodi.', '', 28153),
(148381, 'itIT', 'Io e gli altri ancora leali a Sethraliss fummo costretti a lasciare le nostre case e a nasconderci. È da quel giorno che combattiamo i Senzafede.', '', 28153),
(148380, 'itIT', 'Korthek radunò un\'armata di seguaci Sethrak e iniziò a massacrare chiunque si opponesse a loro... Sulthis fu il primo a cadere, ma non prima di aver messo al sicuro la sua chiave.', '', 28153),
(148379, 'itIT', 'Mentre le sabbie continuavano a diffondersi, Korthek divenne impaziente di combattere. Complottò per riportare alla luce il C\'thrax e usarlo come arma per conquistare il continente.', '', 28153),
(148378, 'itIT', 'Anche se incredibilmente potente, Sulthis non poteva creare la barriera da solo. Chiese aiuto a me e Korthek e, insieme, riuscimmo a sigillare Mythrax nella grande piramide.', '', 28153),
(148377, 'itIT', 'Dopo aver assistito a tale distruzione con i suoi occhi, sapevamo che andava fatto qualcosa per impedire a chiunque di far risorgere Mythrax.', '', 28153),
(148376, 'itIT', 'Il nostro Loa si sacrificò per salvarci da quel mostro. Abbatté il C\'thrax, ma non prima che riuscisse a distruggere il disco nel cuore di Atul\'aman.', '', 28153),
(148375, 'itIT', 'Molto tempo fa, Mythrax l\'Annientatore discese sulle nostre terre, massacrando Troll e Sethrak indistintamente.', '', 28153),
(148374, 'itIT', 'Questa chiave appartiene al primo Custode. Il suo nome era Sulthis e morì per mano di Korthek.', '', 28153),
(148365, 'itIT', '', 'Ah, dunque Maynard ha mandato i suoi scagnozzi a risolvere i suoi problemi, come fa sempre. Mi occuperò di te, come ho fatto con gli altri!', 28153),
(148364, 'itIT', 'Una strega... Perché una strega dovrebbe avercela con noi?!? Devo andarmene di qui. Lo dirò a mio padre!', '', 28153),
(148361, 'itIT', 'Francois nota la tua grossa borsa, considerandoti $gdegno:degna; del suo tempo.', '', 28153),
(148360, 'itIT', 'Fai ondeggiare leggermente la borsa.', 'Fai ondeggiare leggermente la borsa.', 28153),
(148359, 'itIT', 'Se riuscissi a uccidere quel ragno... faresti un favore a un sacco di gente.', '', 28153),
(148358, 'itIT', 'Va bene... A quanto pare hai liberato un passaggio. Credo di potermela cavare da solo ora.', '', 28153),
(148357, 'itIT', 'Francois osserva distrattamente i tuoi piedi.', '', 28153),
(148356, 'itIT', 'L\'imperatore si occuperà di voi.', '', 28153),
(148355, 'itIT', 'Hai interrotto il mio pasto. Ho ucciso per molto meno.', '', 28153),
(148354, 'itIT', '<Dai a Vorrik la Pietra di Sulthis.>', '<Dai a Vorrik la Pietra di Sulthis.>', 28153),
(148353, 'itIT', 'Via libera! La potenza di chesto mojo è impressionante.', '', 28153),
(148352, 'itIT', 'I Naga stanno assorbendo i poteri del Loa Rana per fortificarsi! Fermali e distruggi l\'accampamento loro!', '', 28153),
(148351, 'itIT', 'Buona fortuna. Li amici alati miei stanno pronti a condurti ovunque tu voglia.', 'Buona fortuna. Li amici alati miei stanno pronti a condurti ovunque tu voglia.', 28153),
(148350, 'itIT', 'Vivo di nuovo! Grazie. Se vorrai, ti aiuterò nel momento del bisogno.', 'Vivo di nuovo! Grazie. Se vorrai, ti aiuterò nel momento del bisogno.', 28153),
(148349, 'itIT', 'Che Bwonsamdi ti benedica!', 'Che Bwonsamdi ti benedica!', 28153),
(148348, 'itIT', 'La mia bella pietra! No te!', '', 28153),
(148347, 'itIT', '', 'Dobbiamo parlare con Vorrik.', 28153),
(148345, 'itIT', 'Abbassate le armi. Se stanno cercando Vorrik, forse possono aiutarci...', '', 28153),
(148344, 'itIT', 'Mi sento rinnovato! Grazie, $gstraniero:straniera;.', 'Mi sento rinnovata! Grazie, $gstraniero:straniera;.', 28153),
(148342, 'itIT', '', 'Vedo che hai portato rinforzi.', 28153),
(148340, 'itIT', '', 'State tutti calmi. È uno dei buoni.', 28153),
(148339, 'itIT', 'Sì! È questo l\'importante, Nimmy, le conchiglie. Devi imparare ad apprezzare le conchiglie...', '', 28153),
(148338, 'itIT', 'Si fermò tutto per un minuto. Faceva freddo. Faceva caldo... Stavo dicendo...', '', 28153),
(148337, 'itIT', 'E Korl, Korl prese quella spada... i suoi occhi, si... spensero...', '', 28153),
(148336, 'itIT', 'Pinne e lame e risa e oscurità... c\'era tanto sangue...', '', 28153),
(148335, 'itIT', 'Era il posto più noioso del mare... fin quando non lo è stato più... quando vennero loro...', '', 28153),
(148334, 'itIT', 'Comunque, è stata gloriosa! È stata terribile!', '', 28153),
(148333, 'itIT', 'Aspetta, tu sei qualcuno, vero? Ho già fatto un errore del genere in passato...', '', 28153),
(148332, 'itIT', 'Non ci posso credere... non c\'è nessuno che non abbia sentito parlare della Fossa di Scarvin.', '', 28153),
(148331, 'itIT', 'COSA?!? Non hai mai sentito parlare della Fossa di Scarvin?', '', 28153),
(148330, 'itIT', 'Sai, la Battaglia della Fossa di Scarvin? In fondo a...', '', 28153),
(148329, 'itIT', 'Comunque, Korl e io stavamo parlando di quella battaglia.', '', 28153),
(148328, 'itIT', 'Ti voglio bene, piccolo amico scaglioso.', '', 28153),
(148327, 'itIT', 'L\'ho visto una volta, era belliiiiiissimo!', '', 28153),
(148326, 'itIT', 'Sai che c\'era del fuoco in un posto sott\'acqua?!?', '', 28153),
(148325, 'itIT', 'Ma questo non è nemmeno il punto, il fatto è che...', '', 28153),
(148324, 'itIT', 'Be\', lui non l\'ha fatto. Mi ha guardato e ha spolpato un granchio...', '', 28153),
(148323, 'itIT', 'A te interessa, vero? O almeno faresti finta?', '', 28153),
(148322, 'itIT', 'Ci sono rimasto molto male.', '', 28153),
(148321, 'itIT', 'Una volta ho trovato una conchiglia. Era una bella conchiglia. L\'ho detto anche a Korl, ma non gli interessava.', '', 28153),
(148320, 'itIT', 'Non mi piacciono i cirripedi. Korl dice che la gente a cui piacciono i cirripedi è brutta.', '', 28153),
(148318, 'itIT', 'Tante cose sono cambiate dai giorni in cui io e Korthek insegnavamo assieme la saggezza di Sethraliss proprio qui...\n\nOra questi luoghi sacri giacciono in rovina e Sethraliss è stata dimenticata, se non peggio.\n\nKorthek... Cos\'hai fatto alla nostra gente, vecchio amico mio?', '', 28153),
(148317, 'itIT', 'I cirripedi sono proprio odiosi. A te piacciono, Signor Nimmy?', '', 28153),
(148316, 'itIT', 'Non mi piacciono i cirripedi perché mi fanno prudere i piedi. Anche Korl dice che non gli piacciono i cirripedi.', '', 28153),
(148315, 'itIT', 'I cirripedi sono brutte persone.', '', 28153),
(148314, 'itIT', 'Comunque, il mio amico Korl... lo conosci? Be\', Korl dice che usare una balista è l\'ideale per rimuovere i cirripedi tra le dita dei piedi.', '', 28153),
(148313, 'itIT', 'Non dovresti essere qui!', 'Non dovresti essere qui!', 28153),
(148312, 'itIT', 'Ti insegno io a sfidare un Ferroscuro!', 'Ti insegno io a sfidare una Ferroscuro!', 28153),
(148311, 'itIT', 'Assaggia il potere della montagna!', 'Assaggia il potere della montagna!', 28153),
(148310, 'itIT', 'Ora ti faccio a pezzettini!', 'Ora ti faccio a pezzettini!', 28153),
(148309, 'itIT', 'Mostrami il tuo colpo migliore!', 'Mostrami il tuo colpo migliore!', 28153),
(148308, 'itIT', 'Assapora il tuo ultimo respiro!', 'Assapora il tuo ultimo respiro!', 28153),
(148307, 'itIT', 'Brucia nelle fiamme della mia ira!', 'Brucia nelle fiamme della mia ira!', 28153),
(148306, 'itIT', 'Il mio fuoco... arderà... per sempre...', 'Il mio fuoco... arderà... per sempre...', 28153),
(148305, 'itIT', 'La mia gente... mi... vendicherà...', 'La mia gente... mi... vendicherà...', 28153),
(148304, 'itIT', 'La mia anima... riposerà... all\'Incudine...', 'La mia anima... riposerà... all\'Incudine...', 28153),
(148303, 'itIT', 'Mi farei... un goccetto...', 'Ehi... mi farei... un goccetto...', 28153),
(148302, 'itIT', 'Ti... maledico...', 'Ti... maledico...', 28153),
(148301, 'itIT', 'Dono la mia vita... alla Regina.', 'Dono la mia vita... alla regina.', 28153),
(148300, 'itIT', 'Rinascerò... nel fuoco...', 'Rinascerò... nel fuoco...', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(148299, 'itIT', 'Non dovresti essere qui!', 'Non dovresti essere qui!', 28153),
