(145818, 'itIT', 'Nun posso attaccare quel bersaglio.', '', 28153),
(145817, 'itIT', 'Nun lo posso attaccare.', '', 28153),
(145816, 'itIT', 'L\'inventario mio è pieno.', '', 28153),
(145815, 'itIT', 'Nun posso portare altro.', '', 28153),
(145814, 'itIT', 'Sta bloccato.', '', 28153),
(145813, 'itIT', 'Nun posso trasportarne altri.', '', 28153),
(145812, 'itIT', 'Nun posso ancora usare chest\'oggetto.', '', 28153),
(145811, 'itIT', 'Nun è ancora pronto.', '', 28153),
(145810, 'itIT', 'Chiunque non obbedisca sarà punito!', 'Ogni fallimento sarà punito!', 28153),
(145809, 'itIT', 'L\'oggetto si sta ancora caricando.', '', 28153),
(145808, 'itIT', 'Nun tengo abbastanza furia.', '', 28153),
(145807, 'itIT', 'Tengo poca furia.', '', 28153),
(145806, 'itIT', 'Nun tengo abbastanza dolore.', '', 28153),
(145805, 'itIT', 'Tengo poco dolore.', '', 28153),
(145804, 'itIT', 'Nun è na sacca.', '', 28153),
(145803, 'itIT', 'Nun tengo i fondi necessari.', '', 28153),
(145802, 'itIT', 'Chesto va oltre le disponibilità mie.', '', 28153),
(145801, 'itIT', 'Costa troppo.', '', 28153),
(145800, 'itIT', 'Nun può unirsi al gruppo nostro.', '', 28153),
(145799, 'itIT', 'Ho finito le munizioni.', '', 28153),
(145798, 'itIT', 'Nun tengo abbastanza energia.', '', 28153),
(145797, 'itIT', 'Mi manca l\'energia necessaria.', '', 28153),
(145796, 'itIT', 'Tengo bisogno di mana prima di farlo.', '', 28153),
(145795, 'itIT', 'Tengo poco mana.', '', 28153),
(145794, 'itIT', 'Tengo bisogno di mana.', '', 28153),
(145793, 'itIT', 'Nun tengo abbastanza rabbia.', '', 28153),
(145792, 'itIT', 'Devo tenere più rabbia!', '', 28153),
(145791, 'itIT', 'Sta troppo lontano.', '', 28153),
(145790, 'itIT', 'Sto fuori portata.', '', 28153),
(145789, 'itIT', 'Devo avvicinarmi.', '', 28153),
(145788, 'itIT', 'Nun possiamo invitare nessun altro.', '', 28153),
(145787, 'itIT', 'Nun posso bere altro al momento.', '', 28153),
(145786, 'itIT', 'Nun tengo ancora chest\'abilità.', '', 28153),
(145785, 'itIT', 'Nun posso ancora farlo.', '', 28153),
(145784, 'itIT', 'L\'incantesimo nun è pronto.', '', 28153),
(145783, 'itIT', 'Nun posso ancora lanciarlo.', '', 28153),
(145782, 'itIT', 'Si sta ancora ricaricando.', '', 28153),
(145781, 'itIT', 'L\'arma mia richiede due mani.', '', 28153),
(145780, 'itIT', 'L\'abilità nun è pronta.', '', 28153),
(145779, 'itIT', 'Nun posso ancora farlo.', '', 28153),
(145778, 'itIT', 'Nun sto ancora pronto.', '', 28153),
(145777, 'itIT', 'Nun posso metterlo lì.', '', 28153),
(145776, 'itIT', 'Chesta sacca è piena.', '', 28153),
(145775, 'itIT', 'Nun posso farlo accà.', '', 28153),
(145774, 'itIT', 'Nun posso lasciare chest\'oggetto.', '', 28153),
(145773, 'itIT', 'Chest\'oggetto è vincolato a me.', '', 28153),
(145772, 'itIT', 'Nun lo posso equipaggiare.', '', 28153),
(145771, 'itIT', 'Il livello mio nun è abbastanza alto per usarlo.', '', 28153),
(145770, 'itIT', 'Nun lo posso ancora usare.', '', 28153),
