INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145767, 'itIT', 'Nun posso imparare chest\'incantesimo.', '', 28153),
(145766, 'itIT', 'Nun posso depredarlo.', '', 28153),
(145765, 'itIT', 'Chest\'oggetto nun è mio.', '', 28153),
(145764, 'itIT', 'Devo avvicinarmi.', '', 28153),
(145763, 'itIT', 'Sta troppo lontano.', '', 28153),
(145762, 'itIT', 'Nun ci arrivo.', '', 28153),
(145761, 'itIT', 'Nun posso scambiare chest\'oggetto.', '', 28153),
(145760, 'itIT', 'Nun posso usare chest\'oggetto.', '', 28153),
(145759, 'itIT', 'Chest\'oggetto nun è equipaggiato.', '', 28153),
(145758, 'itIT', 'Deve essere prima equipaggiato.', '', 28153),
(145757, 'itIT', 'Nun posso depredarlo in chesto momento.', '', 28153),
(145756, 'itIT', 'Nun tengo nu bersaglio.', '', 28153),
(145755, 'itIT', 'Prima devo tenere nu bersaglio.', '', 28153),
(145754, 'itIT', 'Tengo bisogno di nu bersaglio.', '', 28153),
(145753, 'itIT', 'Nun posso farlo.', '', 28153),
(145752, 'itIT', 'Prima devo ottenere il permesso.', '', 28153),
(145751, 'itIT', 'Attaccate il nemico mio!', '', 28153),
(145750, 'itIT', 'Colpite il bersaglio mio!', '', 28153),
(145749, 'itIT', 'Concentrate li attacchi vostri!', '', 28153),
(145748, 'itIT', 'Carica!', '', 28153),
(145747, 'itIT', 'Colpite insieme!', '', 28153),
(145746, 'itIT', 'Per Zandalar!', '', 28153),
(145745, 'itIT', 'Avanziamo, tutti quanti.', '', 28153),
(145744, 'itIT', 'Respingeteli!', '', 28153),
(145743, 'itIT', 'Ripiegare!', '', 28153),
(145742, 'itIT', 'Dobbiamo ritirarci!', '', 28153),
(145741, 'itIT', 'Via! Andate via!', '', 28153),
(145740, 'itIT', 'Da chesta parte.', '', 28153),
(145739, 'itIT', 'Faccio strada io.', '', 28153),
(145738, 'itIT', 'Vieni con me.', '', 28153),
(145737, 'itIT', 'Per l\'Orda!', '', 28153),
(145736, 'itIT', 'Le ferite mie sono gravi!', '', 28153),
(145735, 'itIT', 'Tengo bisogno di cure!', '', 28153),
(145734, 'itIT', 'Aiuto!', '', 28153),
(145733, 'itIT', 'Aiutatemi!', '', 28153),
(145732, 'itIT', 'Pericolo in arrivo!', '', 28153),
(145731, 'itIT', 'Attaccate con tutte le armi!', '', 28153),
(145730, 'itIT', 'Fuoco!', '', 28153),
(145729, 'itIT', 'Resta accà.', '', 28153),
(145728, 'itIT', 'Nun ti muovere.', '', 28153),
(145727, 'itIT', 'Con i miei fratelli in libertà, cercherò gli Zandalari al villaggio. Qui non è rimasto altro per noi.', '', 28153),
(145726, 'itIT', 'Non sono un combattente. Ti aspetto nelle profondità della Gola quando avrai liberato i miei fratelli.', '', 28153),
(145725, 'itIT', 'Niente mancia?', 'Niente mancia?', 28153),
(145724, 'itIT', 'Sento il potere di Reid che mi chiama, come un faro. Presto!', '', 28153),
(145723, 'itIT', 'Pare che tu ne abbia avuto abbastanza. Via di qui!', '', 28153),
(145722, 'itIT', 'Posizionamento', 'Posizionamento', 28153),
(145721, 'itIT', '', 'La biologia evolutiva delle specie di Silitidi è incredibilmente accattivante!', 28153),
(145720, 'itIT', 'Ti piacciono davvero tanto i gatti!', 'Ti piacciono davvero tanto i gatti!', 28153),
(145719, 'itIT', 'Signora Batuffolina?', 'Signora Batuffolina?', 28153),
(145718, 'itIT', 'Sembra che li tratti davvero bene.', 'Sembra che li tratti davvero bene.', 28153),
(145717, 'itIT', '<Provi a parlare, ma vieni subito interrotto>', '<Provi a parlare, ma vieni subito interrotta>', 28153),
(145716, 'itIT', '', '<Inizia a piangere.>\n\nScusa, mi sono emozionata... amo davvero i gatti. Ogni tipo di gatto. i gatti bombay, i calico, i siamesi, i soriani, i vilinfusi, i non vilinfusi, le fiere dell\'alba, le vilfiere, le fiere delle fiamme, le fiere del gelo, del mana, della nebbia, della luna, della notte, delle rune, della tempesta, i leoni, le linci, le pantere, le panthara, specialmente quelle di colore indaco, anche se dicono che abbiano davvero un caratteraccio, ma sono sicura che la gente non le capisca come le capisco io, le tigri, le tigri spettrali... La prima cosa che ho fatto quando ho lasciato Suramar è stata vedere con i miei occhi ogni tipo di gatto, e vorrei abbracciarli tutti, ma non posso.\n\n<Inizia di nuovo a piangere.>', 28153),
(145715, 'itIT', '', '<Indica un terzo gattino di mana.>\n\nGuardala, come se ne sta tranquilla... devo dire che ha un\'immaginazione davvero incredibile in fatto di cibo. Potresti pensare che si accontenti dell\'ottimo pesce che abbiamo qui, ma in realtà la Signora Batuffolina è una vera intenditrice di cibi deliziosi. Che tu ci creda o meno, e anche io stento a crederci ogni tanto, il suo cibo preferito sono i Dolcetti di Mana!\n\nDopotutto ha senso, considerando che i miei genitori gliene davano spesso quando ero piccola. Formiamo davvero una bella squadra io e lei.', 28153),
(145714, 'itIT', '', 'Questi gattini meritano il meglio perché sono il meglio e vorrei davvero poter condividere la loro gioia e il loro amore con il resto del mondo, ma non posso. Credimi, ci ho provato. Non sai cosa significhi per me che tu sia qui e possa coccolarli. È una fortuna che avessi altri due gatti da coccolare quando cercavo di ottenere la fiducia di Miu. Mi viene male solo a pensarci, ma non so davvero come avrei fatto! Immagina di avere una casa senza gatti! Non la potrei nemmeno chiamare casa, sarebbe solo un posto dove vivere, e se non avessi alcun gatto, che senso avrebbe vivere? Ah, ecco uno di quei due gatti, si chiama Signora Batuffolina!', 28153),
(145713, 'itIT', '', 'All\'inizio era davvero impaurito e non si faceva accarezzare, il che mi rese ancora più determinata. Ci sono voluti tanti anni di perseveranza e regali. MAI sottovalutare l\'importanza dei REGALI. Ora siamo MIGLIORI AMICI proprio come con gli altri gattini!\n\nDevo fare attenzione a non farmi sentire, sennò comincerà a miagolare e miagolare e... come puoi dire di no a quegli occhioni? Guardali, guarda che roba! Sono così pieni d\'amore che mi riscaldano il cuore! Io ci provo a non viziarlo ma finisco sempre per dargli tutto quello che vuole!', 28153),
(145712, 'itIT', '', 'Metti pure l\'Arcavino lì so... oh, non mi sembra di conoscerti. Il che significa... che devi essere $gnuovo:nuova; di queste parti. Permettimi di presentarti ai miei piccoli allora!\n\n<Indica uno dei gattini di mana.>\n\nQuesto è Ombra. Porta sempre con sé i suoi giocattoli durante le sue innumerevoli avventure e finisce puntualmente per perderli. Dove stai andando? Giù al Serraglio a vedere le creature esotiche di questo mondo? O alle Vigne del Crepuscolo? Forse la prossima volta potresti portarmi qualche cosina dai tuoi viaggi! Be\', in realtà una volta mi ha portato qualcosa da una delle sue escursioni... il mio piccolo Miu! Quel giorno gli aprii la porta per farlo entrare e con grande stupore mia accorsi che aveva portato un amico con sé! E gli amici di Ombra sono anche amici miei!', 28153),
(145706, 'itIT', '', 'Cos\'è stato? Voi tre! Controllate i motori!', 28153),
(145703, 'itIT', 'Hai firmato la tua condanna a morte. Ricorda le mie parole...', '', 28153),
(145702, 'itIT', 'Hai versato il mio grog! La pagherai per questo!', '', 28153),
(145701, 'itIT', 'Ripulirò il ponte dalla tua lurida presenza!', '', 28153),
(145700, 'itIT', 'Ah, te la sei cavata contro qualche Grunt... Vediamo quanto resisti contro un veterano dei Lupi di Mare!', '', 28153),
(145699, 'itIT', 'Forza ragazzi, mostrate a questa canaglia cosa succede a chi si mette contro l\'Orda!', '', 28153),
(145698, 'itIT', 'Se pensi di poter fermare la ciurma di un Lupo di Mare, ti sbagli di grosso!', '', 28153),
(145697, 'itIT', 'Quindi la canaglia dell\'Alleanza ha deciso di mostrare il suo volto?', '', 28153),
(145686, 'itIT', '', 'Stanotte dormirai con i Pinnamozza, $n.', 28153),
(145685, 'itIT', '', 'Pregherò per te!', 28153),
(145684, 'itIT', '', 'Non sprecare soldi per la mia tomba.', 28153),
(145683, 'itIT', '', 'Osi digrignare i denti a me, $n!', 28153),
(145682, 'itIT', '', 'Abbi pietà!', 28153),
(145681, 'itIT', '', 'Ti piacciono le esplosioni, $n?', 28153),
(145680, 'itIT', '', 'Ti prego, sii gentile.', 28153),
(145679, 'itIT', '', 'Ho voglia di accoltellarti.', 28153),
(145678, 'itIT', '', 'Che li spiriti abbiano pietà!', 28153),
(145677, 'itIT', '', 'Congratulazioni.', 28153),
(145676, 'itIT', '', 'I Loa ti hanno benedetto.', 28153),
(145675, 'itIT', '', 'Davvero notevole.', 28153),
(145674, 'itIT', '', 'La tua pietà mi disgusta!', 28153),
(145673, 'itIT', '', 'Sento odore di peli bruciati.', 28153),
(145672, 'itIT', '', 'Nun fare patti con li spiriti.', 28153),
(145671, 'itIT', '', 'Preparati a una scossa.', 28153),
(145670, 'itIT', '', 'Che Bwonsamdi stia sempre lontano dalla dimora tua.', 28153),
(145669, 'itIT', 'Era ora.', 'Era ora.', 28153),
(145668, 'itIT', '', 'Che i Loa veglino su di te.', 28153),
(145667, 'itIT', '', 'Addio.', 28153),
(145666, 'itIT', '', 'Li spiriti ti danno il benvenuto.', 28153),
(145665, 'itIT', '', 'Salve.', 28153),
(145664, 'itIT', '', 'I Loa ci circondano.', 28153),
(145663, 'itIT', '', 'Ho il tuo affitto proprio qua!', 28153),
(145662, 'itIT', '', 'Felice di vederti.', 28153),
(145661, 'itIT', '', 'No.', 28153),
(145660, 'itIT', '', 'Niente da fare.', 28153),
(145659, 'itIT', '', 'Assolutamente no.', 28153),
(145658, 'itIT', '', 'Capisco.', 28153),
(145657, 'itIT', '', 'Concordo.', 28153),
(145656, 'itIT', '', 'Giusto.', 28153),
(145655, 'itIT', '', 'Mi serve mana.', 28153),
(145654, 'itIT', '', 'Abbi pazienza mentre recupero il mana.', 28153),
(145653, 'itIT', '<Senti uno strano sguardo su di te. Sembra così... compiaciuto?>', '<Senti il rombo di un motore in lontananza.>', 28153),
(145652, 'itIT', '', 'Davvero apprezzato.', 28153),
(145651, 'itIT', '', 'Ti ringrazio veramente.', 28153),
(145650, 'itIT', '', 'Te ne sarò grata per sempre.', 28153),
(145649, 'itIT', 'Corretto! Hai risposto a tutti i miei indovinelli!', '', 28153),
(145648, 'itIT', '', 'Siano lodati i Loa!', 28153),
(145647, 'itIT', '', 'Sei in trappola, in minoranza e senza via di scampo! Di\' le tue ultime preghiere!', 28153),
(145646, 'itIT', '', 'Puzzi come nu Troll del Sangue!', 28153),
(145645, 'itIT', '', 'Le ossa tue decoreranno l\'altare mio!', 28153),
(145644, 'itIT', '', 'Prego.', 28153),
(145643, 'itIT', '', 'Nun c\'è di che.', 28153),
(145642, 'itIT', '', 'È stato nu vero piacere.', 28153),
(145641, 'itIT', 'La velocità di volo di un Fendibecco.', 'La velocità di volo di un Fendibecco.', 28153),
(145640, 'itIT', 'Un Depredatore di Bottino Automatico.', 'Un Depredatore di Bottino Automatico.', 28153),
(145639, 'itIT', 'Non posso morire, sono... Gas... ton...', '', 28153),
(145638, 'itIT', 'Non ho fatto tutta questa strada per arrendermi.', 'Non ho fatto tutta questa strada per arrendermi.', 28153),
(145637, 'itIT', 'Sbagliato!\n\nVuoi riprovare?', '', 28153),
(145636, 'itIT', 'Un cuore infranto.', 'Un cuore infranto.', 28153),
(145635, 'itIT', 'Il tempo.', 'Il tempo.', 28153),
(145634, 'itIT', 'Rispondi a chesto.\n\nCosa può sempre essere misurato, ma nun viene mai visto?', '', 28153),
(145633, 'itIT', 'Sono particolarmente bravo a sveeentrare!', '', 28153),
(145632, 'itIT', 'La realtà delle illusioni di Gaston non ha eguali!', '', 28153),
(145631, 'itIT', 'Gira con Gaston in un turbinio di spine!', '', 28153),
(145630, 'itIT', 'Sono pronto!', 'Sono pronta!', 28153),
(145629, 'itIT', 'Nessuno colpisce come Gaston!', '', 28153),
(145628, 'itIT', 'Il passato.', 'Il passato.', 28153),
(145626, 'itIT', '', 'Attaccate il nemico mio!', 28153),
(145625, 'itIT', '', 'Colpite il bersaglio mio!', 28153),
(145624, 'itIT', '', 'Concentrate li attacchi vostri!', 28153),
(145623, 'itIT', '', 'Carica!', 28153),
(145622, 'itIT', '', 'Colpite insieme!', 28153),
(145621, 'itIT', '', 'Per Zandalar!', 28153),
(145620, 'itIT', '', 'Avanziamo, tutti quanti.', 28153),
(145619, 'itIT', '', 'Respingeteli!', 28153),
(145618, 'itIT', '', 'Ripiegare!', 28153),
(145617, 'itIT', 'Il sole.', 'Il sole.', 28153),
(145616, 'itIT', '', 'Dobbiamo ritirarci!', 28153),
(145615, 'itIT', '', 'Via! Andate via!', 28153),
(145614, 'itIT', '', 'Da chesta parte.', 28153),
(145613, 'itIT', '', 'Faccio strada io.', 28153),
(145612, 'itIT', '', 'Vieni con me.', 28153),
(145611, 'itIT', '', 'Per l\'Orda!', 28153),
(145610, 'itIT', '', 'Le ferite mie sono gravi!', 28153),
(145609, 'itIT', 'Risposta esatta! Resta nu solo indovinello.\n\nSei $Gpronto:pronta;?', '', 28153),
(145608, 'itIT', 'La mia ombra.', 'La mia ombra.', 28153),
(145607, 'itIT', '', 'Tengo bisogno di cure!', 28153),
(145606, 'itIT', '', 'Aiuto!', 28153),
(145605, 'itIT', 'Fammi riprovare.', 'Fammi riprovare.', 28153),
(145604, 'itIT', 'Direi di no!\n\nTieni n\'altra risposta?', '', 28153),
(145603, 'itIT', '', 'Aiutatemi!', 28153),
(145602, 'itIT', 'Un Ladro.', 'Un Ladro.', 28153),
(145601, 'itIT', 'Rispondi a chesto.\n\nA volte cammino davanti a te, a volte cammino dietro di te. Solo al buio ti abbandono. Cosa sono?', '', 28153),
(145600, 'itIT', '', 'Pericolo in arrivo!', 28153),
(145599, 'itIT', 'Una cassa del tesoro.', 'Una cassa del tesoro.', 28153),
(145598, 'itIT', '', 'Attaccate con tutte le armi!', 28153),
(145597, 'itIT', '', 'Fuoco!', 28153),
(145595, 'itIT', '', 'Resta accà.', 28153),
(145594, 'itIT', '', 'Nun ti muovere.', 28153),
(145593, 'itIT', 'Ti prego, dimmi che abbiamo quasi finito.', 'Ti prego, dimmi che abbiamo quasi finito.', 28153),
(145592, 'itIT', 'Sono pronto!', 'Sono pronta!', 28153),
(145591, 'itIT', 'Esatto!\n\nTi va di proseguire?', '', 28153),
(145590, 'itIT', 'Una pianta.', 'Una pianta.', 28153),
