(145335, 'itIT', 'Non ho abbastanza energia.', '', 28153),
(145334, 'itIT', 'Mi manca l\'energia necessaria.', '', 28153),
(145333, 'itIT', 'Ho bisogno di mana prima di farlo.', '', 28153),
