(145330, 'itIT', 'Non ho abbastanza rabbia.', '', 28153),
(145329, 'itIT', 'Devo avere più rabbia!', '', 28153),
(145328, 'itIT', 'È troppo lontano.', '', 28153),
(145327, 'itIT', 'Sono fuori portata.', '', 28153),
(145326, 'itIT', 'Devo avvicinarmi.', '', 28153),
(145325, 'itIT', 'Non possiamo invitare nessun altro.', '', 28153),
(145324, 'itIT', 'Non posso bere altro al momento.', '', 28153),
(145323, 'itIT', 'Non ho ancora quest\'abilità.', '', 28153),
(145322, 'itIT', 'Non posso ancora farlo.', '', 28153),
(145321, 'itIT', 'L\'incantesimo non è pronto.', '', 28153),
(145320, 'itIT', 'Non posso ancora lanciarlo.', '', 28153),
(145319, 'itIT', 'Si sta ancora ricaricando.', '', 28153),
(145318, 'itIT', 'Rispondi a chesto.\n\nSe ce l\'ho, nun lo condivido. Se lo condivido, nun ce l\'ho. Che cos\'è?', '', 28153),
(145317, 'itIT', 'Abbattetelo!', '', 28153),
(145316, 'itIT', 'Uccidete il mio bersaglio!', '', 28153),
(145315, 'itIT', 'Concentratevi sul nemico!', '', 28153),
(145314, 'itIT', 'Alle armi!', '', 28153),
(145313, 'itIT', 'Per la regina!', '', 28153),
(145312, 'itIT', 'Per il potere della montagna!', '', 28153),
(145311, 'itIT', 'Annientateli!', '', 28153),
(145310, 'itIT', 'Respingeteli!', '', 28153),
(145309, 'itIT', 'Dovete ripiegare!', '', 28153),
(145308, 'itIT', '<Senti uno strano sguardo su di te. Sembra così... compiaciuto?>', '<Senti uno strano sguardo su di te. Sembra così... compiaciuto?>', 28153),
(145307, 'itIT', 'Ritirata!', '', 28153),
(145306, 'itIT', 'Via di qui!', '', 28153),
(145305, 'itIT', 'Da questa parte.', '', 28153),
(145304, 'itIT', 'Faccio strada.', '', 28153),
(145303, 'itIT', 'Vieni con me.', '', 28153),
(145302, 'itIT', 'Davvero, ancora una?', 'Davvero, ancora una?', 28153),
(145301, 'itIT', 'Sono pronto!', 'Sono pronta!', 28153),
(145300, 'itIT', 'Quelli che giocano duro sono sempre le prede più appaganti. Vengo a prendervi!', '', 28153),
(145299, 'itIT', 'Proprio così!\n\nSei $gpronto:pronta; per il prossimo?', '', 28153),
(145298, 'itIT', 'Per l\'Alleanza!', '', 28153),
(145297, 'itIT', 'Le mie ferite sono gravi!', '', 28153),
(145296, 'itIT', 'Ho bisogno di cure!', '', 28153),
(145295, 'itIT', 'Mi serve aiuto!', '', 28153),
(145294, 'itIT', 'Aiutami!', '', 28153),
(145293, 'itIT', 'Pericolo in arrivo!', '', 28153),
(145292, 'itIT', 'Scatena la tua furia!', '', 28153),
(145291, 'itIT', 'Fuoco!', '', 28153),
(145290, 'itIT', 'Resta qui.', '', 28153),
(145289, 'itIT', 'Non muoverti.', '', 28153),
(145288, 'itIT', 'Una pianta carnivora.', 'Una pianta carnivora.', 28153),
(145287, 'itIT', '', 'Lasciami recuperare del mana!', 28153),
(145286, 'itIT', '', 'Devo recuperare il mana.', 28153),
(145285, 'itIT', 'Un pesce.', 'Un pesce.', 28153),
(145283, 'itIT', 'Ancora un tentativo.', 'Ancora un tentativo.', 28153),
(145282, 'itIT', 'No!\n\nVuoi riprovare?', '', 28153),
(145281, 'itIT', 'Un Pandaren.', 'Un Pandaren.', 28153),
(145280, 'itIT', 'Un fuoco.', 'Un fuoco.', 28153),
(145279, 'itIT', 'Rispondi a chesto.\n\nSe mangio, vivo. Se bevo, schiatto. Cosa sono?', '', 28153),
(145278, 'itIT', 'Sono pronto!', 'Sono pronta!', 28153),
(145277, 'itIT', 'Esatto!\n\nSei $gpronto:pronta; per il prossimo?', '', 28153),
(145276, 'itIT', 'Uuna viene avvolta dall\'oscurità.', 'Uuna viene avvolta dall\'oscurità.', 28153),
(145275, 'itIT', '', 'Arghhh! No! Aiuto!', 28153),
(145273, 'itIT', '', '<Una voce tonante rimbomba, facendoti rabbrividire.>', 28153),
(145272, 'itIT', '', 'Ti prego!', 28153),
(145271, 'itIT', '', 'Mostra un po\' di gentilezza, ti prego!', 28153),
(145270, 'itIT', '', 'Chiedo pietà!', 28153),
(145269, 'itIT', '', 'Niente male.', 28153),
(145268, 'itIT', '', 'Notevole.', 28153),
(145267, 'itIT', '', 'Complimenti.', 28153),
(145266, 'itIT', '', 'Ma... non ancora.', 28153),
(145265, 'itIT', '', 'So che un giorno dovrò tornare da mamma e papà.', 28153),
(145264, 'itIT', '', 'Che la forgia illumini la tua strada.', 28153),
(145263, 'itIT', '', 'Mi hai mostrato così tante cose interessanti. Sei davvero $gil migliore amico:la migliore amica; del mondo!', 28153),
(145262, 'itIT', '', 'Va be\', abbiamo finito.', 28153),
(145261, 'itIT', '', 'Pagherai per chello che hai fatto!', 28153),
(145260, 'itIT', '', 'Ci si vede!', 28153),
(145259, 'itIT', '', 'Addio.', 28153),
(145258, 'itIT', '', 'Grazie infinite per avermi mostrato tutto questo, $gamico:amica;!', 28153),
(145257, 'itIT', '', 'Non sono morti tutti su Argus?', 28153),
(145256, 'itIT', '', 'La mia gente è qui! Sono sopravvissuti!', 28153),
(145255, 'itIT', '', 'È così... bella...', 28153),
(145254, 'itIT', '', 'È davvero ridicolo, $gamico:amica;.', 28153),
(145253, 'itIT', '', 'Ma si muove come l\'acqua... è un lago luminoso?', 28153),
(145252, 'itIT', '', 'Cosa ti porta qui?', 28153),
(145251, 'itIT', 'Vorrei riprovare.', 'Vorrei riprovare.', 28153),
(145250, 'itIT', 'Sbagliato!\n\nVuoi riprovare?', '', 28153),
(145249, 'itIT', 'Un Loa.', 'Un Loa.', 28153),
(145248, 'itIT', 'Una candela.', 'Una candela.', 28153),
(145247, 'itIT', '', 'Guarda laggiù. Brilla tutto!', 28153),
(145246, 'itIT', '', 'Dove siamo? Perché c\'è tutto questo fumo?', 28153),
(145245, 'itIT', '', 'Fai attenzione, va bene?', 28153),
(145244, 'itIT', 'Un albero.', 'Un albero.', 28153),
(145243, 'itIT', '', 'Non cadere! A me non accadrebbe nulla, ma tu faresti SPLAT!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(145242, 'itIT', '', 'Salve.', 28153),
(145241, 'itIT', '', 'Non sapevo che le montagne potessero essere così alte!', 28153),
(145240, 'itIT', '', 'Da qui riesco a vedere tutto!', 28153),
(145239, 'itIT', '', 'È bello vederti.', 28153),
(145238, 'itIT', '', 'Felice di vederti.', 28153),
(145237, 'itIT', '', 'Cra cra cra cra cra cra!', 28153),
(145236, 'itIT', '', 'Nah.', 28153),
(145235, 'itIT', '', 'No.', 28153),
(145234, 'itIT', '', 'Neanche per sogno.', 28153),
(145233, 'itIT', '', 'Proprio così.', 28153),
(145232, 'itIT', '', 'Mmm-mmm.', 28153),
(145231, 'itIT', '', 'Già.', 28153),
(145230, 'itIT', '', 'I miei più sentiti ringraziamenti.', 28153),
(145229, 'itIT', '', 'Ti ringrazio.', 28153),
(145228, 'itIT', 'Uno Gnomo.', 'Uno Gnomo.', 28153),
(145227, 'itIT', '', 'Te ne devo una.', 28153),
(145226, 'itIT', '', 'Per l\'Incudine Nera!', 28153),
(145225, 'itIT', '', 'Tipo... DIECI uccelli!', 28153),
(145224, 'itIT', '', 'È questo il meglio che sai fare?', 28153),
(145222, 'itIT', '', 'Ti spacco la faccia!', 28153),
(145221, 'itIT', '', 'Mi chiedo quanti uccelli vivano in quell\'albero. Devono essere tantissimi!', 28153),
(145220, 'itIT', 'Rispondi a chesto.\n\nSono alto da giovane e corto da vecchio. Cosa sono?', '', 28153),
(145219, 'itIT', '', 'È stato un piacere.', 28153),
(145218, 'itIT', '', '$gAmico:Amica;, guarda! Siamo sotto un albero gigante!', 28153),
(145217, 'itIT', '', 'Felice di aiutare.', 28153),
(145216, 'itIT', '', 'Non c\'è di che, davvero.', 28153),
(145215, 'itIT', 'Giochiamo.', 'Giochiamo.', 28153),
(145214, 'itIT', 'Stai $gpronto:pronta; a mettere alla prova la mente tua?', '', 28153),
(145213, 'itIT', '', 'Posso tenerne uno?', 28153),
(145212, 'itIT', '', 'Tranne le lucertole volanti.', 28153),
(145211, 'itIT', '', 'Quella torre è gigantesca. Sembra... un\'enorme voliera!', 28153),
(145210, 'itIT', '', 'Ehi, cosa sono quei cosi volanti? Sono bellissimi!', 28153),
(145209, 'itIT', '', 'Ora che ci penso... ma tu vivi da qualche parte?', 28153),
(145208, 'itIT', '', 'Tu vivi qui?', 28153),
(145207, 'itIT', '', 'Come riesce a farlo?', 28153),
(145206, 'itIT', '', 'Oh cielo... una città volante! Non posso crederci!', 28153),
(145205, 'itIT', '', 'Vuoi giocare alle principesse con me?', 28153),
(145204, 'itIT', '', 'Tu sai chi vive qui? Scommetto che è una principessa.', 28153),
(145203, 'itIT', '', 'Questa deve essere la casa più bella di sempre!', 28153),
(145202, 'itIT', '', 'Bleah!', 28153),
(145201, 'itIT', '', 'Sono insetti? Scommetto che sono insetti. Bleah! Che schifo gli insetti!', 28153),
(145200, 'itIT', '', 'Cosa credi volessero tenere fuori?', 28153),
(145199, 'itIT', '', 'Ooh! Questo è il muro più grande che abbia mai visto!', 28153),
(145197, 'itIT', '', 'Uuna ti abbraccia.', 28153),
(145196, 'itIT', 'Voi no prendere scarpa!', '', 28153),
(145195, 'itIT', '', 'Va bene, andiamo via da qui! Abbiamo un sacco di posti da visitare!', 28153),
(145194, 'itIT', '', 'Di\' a mamma e papà che mi mancano e... che li rivedrò presto!', 28153),
(145193, 'itIT', '', 'La Luce dice che posso rimanere! Evviva!', 28153),
(145192, 'itIT', '', 'Va bene se sto ancora un po\' con $gil mio amico:la mia amica;? Solo un pochino...', 28153),
(145191, 'itIT', '', 'Ci sono un sacco di cose che non ho mai potuto fare. Così tanti posti da visitare...', 28153),
(145190, 'itIT', '', 'Aspetta un secondo...', 28153),
(145189, 'itIT', '', 'Mamma! Papà! Mi stanno aspettando!', 28153),
(145188, 'itIT', '', 'La Luce... mi sta dicendo di seguirla...', 28153),
(145187, 'itIT', '', 'Cosa... Cosa sta succedendo?', 28153),
(145186, 'itIT', '', 'Oh! Ce l\'abbiamo fatta! Li abbiamo battuti!', 28153),
(145185, 'itIT', '', 'L\'oscurità se ne è andata! Posso vederci!', 28153),
(145184, 'itIT', '', 'Pagherai per chello che hai fatto!', 28153),
(145183, 'itIT', 'Maledizione... Maledizione! Non avevo finito...', '', 28153),
(145182, 'itIT', 'La tua morte compiacerà la Regina Banshee!', '', 28153),
(145181, 'itIT', 'Feccia dell\'Alleanza! Porterò la tua testa alla Dama Oscura!', '', 28153),
(145180, 'itIT', '', 'Taglierò la gola tua!', 28153),
(145179, 'itIT', '<In lontananza si ode un rumore di zoccoli. Qualcosa sta arrivando.>', '<In lontananza si ode un rumore di zoccoli. Qualcosa sta arrivando.>', 28153),
(145178, 'itIT', '', 'Come osi interrompermi? Pagherai con la vita tua!', 28153),
(145177, 'itIT', '', 'Ti stavo osservando.', 28153),
(145176, 'itIT', 'Ti farò a pezzi, proprio come il re tuo! Per l\'Orda!', '', 28153),
(145175, 'itIT', '<Senti uno strano odore e l\'aria comincia a crepitare.>', '<Senti uno strano odore e l\'aria comincia a crepitare.>', 28153),
(145173, 'itIT', '', 'Nun male, ma nun mi servo solo della magia!', 28153),
(145172, 'itIT', 'Sono pronto. Iniziamo il rituale.', 'Sono pronta. Iniziamo il rituale.', 28153),
(145171, 'itIT', 'Sento il pianto del mondo sotto ai miei piedi. Azeroth sta tremando di dolore! Devo trovare un modo per alleviare questa sofferenza...', '', 28153),
(145170, 'itIT', '', 'Nun schiatterò così facilmente. Subirai la vendetta mia!', 28153),
(145169, 'itIT', '', 'Sorpresa! Eheheh.', 28153),
(145168, 'itIT', 'Ti frantumerò la testa!', '', 28153),
(145167, 'itIT', 'Strapperò la carne dalle tue ossa!', '', 28153),
(145166, 'itIT', 'Resterò sulla tua tomba per l\'eternità.', '', 28153),
(145165, 'itIT', 'Ho perso ogni speranza.', '', 28153),
(145164, 'itIT', 'Maledizione. Non di nuovo...', '', 28153),
(145163, 'itIT', 'Soffrirai per ciò che mi hai fatto.', '', 28153),
(145162, 'itIT', 'Risucchierò la tua forza vitale.', '', 28153),
(145161, 'itIT', 'Adoro il suono del metallo e l\'odore della paura.', '', 28153),
(145160, 'itIT', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Sei bersaglio di |cFFF00000|Hspell:260953|h[Sguardo di Ferro]|h|r!', '|TInterface\\ICONS\\Sha_Ability_Rogue_BloodyEye_nightmare.blp:20|t Sei il bersaglio di |cFFF00000|Hspell:257459|h[Gancio]|h|r!', 28153),
(145159, 'itIT', '', 'NON AVRÒ PIÙ PAURA DI NIENTE!', 28153),
(145158, 'itIT', '', 'La mia luce è fortissima!', 28153),
(145157, 'itIT', 'Voglio andare a casa.', '', 28153),
(145156, 'itIT', '', 'Fintanto che la mia luce è con me, l\'oscurità non potrà vincere!', 28153),
(145155, 'itIT', '', 'Mamma mi diceva che la Luce mi avrebbe sempre trovata. Sei tu, $gamico:amica;. Sei tu la mia luce!', 28153),
(145154, 'itIT', '', '$gAmico:Amica;, sei qui! Non mi hai abbandonata!', 28153),
(145153, 'itIT', 'No... no...', 'No... no...', 28153),
(145152, 'itIT', 'Dama Oscura... Ho fallito...', 'Dama Oscura... Ho fallito...', 28153),
(145151, 'itIT', 'Sono il pezzo più basso del Totem, cumpà.', '', 28153),
(145150, 'itIT', 'Finalmente...', 'Finalmente...', 28153),
(145149, 'itIT', 'Oh... non di nuovo...', 'Oh... non di nuovo...', 28153),
(145148, 'itIT', 'Per la Dama Oscura!', 'Per la Dama Oscura!', 28153),
(145147, 'itIT', 'Abbandona ogni speranza!', 'Abbandona ogni speranza!', 28153),
(145146, 'itIT', 'Unisciti a noi nella morte!', 'Unisciti a noi nella morte!', 28153),
(145145, 'itIT', 'Mi ciberò delle tue ossa!', 'Mi ciberò delle tue ossa!', 28153),
(145144, 'itIT', 'Morte ai vivi!', 'Morte ai vivi!', 28153),
(145143, 'itIT', 'Per Sylvanas!', 'Per Sylvanas!', 28153),
(145142, 'itIT', '', 'Uuna si raggomitola su se stessa e inizia a piangere.', 28153),
(145141, 'itIT', '', 'Non... Non ce la faccio! Voglio solo tornare a casa!', 28153),
(145140, 'itIT', '', '$gAmico:Amica;? Sei ancora qui? Ho paura!', 28153),
(145139, 'itIT', 'Il juju fetente ti avrà!', '', 28153),
(145137, 'itIT', 'Gli antenati tuoi ti stanno chiamando.', '', 28153),
(145136, 'itIT', 'Che lo sguardo del fratello mio ti maledica!', '', 28153),
(145135, 'itIT', 'Vediamo qual è il vudù tuo, cumpà!', '', 28153),
(145133, 'itIT', 'Che le ossa cadano.', '', 28153),
(145130, 'itIT', 'Le spine anelano le vostre anime!', '', 28153),
(145129, 'itIT', 'Si voltò e scomparve nei boschi. Da allora, i valorosi e i giusti trovano sempre rifugio nella foresta del cervo bianco.', 'Si voltò e scomparve nei boschi. Da allora, i valorosi e i giusti trovano sempre rifugio nella foresta del cervo bianco.', 28153),
(145128, 'itIT', '\"Sono Athair, il cuore di questa foresta. Finché sarò in vita, proteggerò te e la tua gente\", disse il cervo.', '\"Sono Athair, il cuore di questa foresta. Finché sarò in vita, proteggerò te e la tua gente\", disse il cervo.', 28153),
(145127, 'itIT', '\"Per la Luce! Sta parlando!\", esclamò Arom.', '\"Per la Luce! Sta parlando!\", esclamò Arom.', 28153),
(145126, 'itIT', '', '<Risata>', 28153),
(145125, 'itIT', '', '<Yawning sound>', 28153),
(145124, 'itIT', '', '<Short cheer--Wooooo!>', 28153),
(145123, 'itIT', '', '<Slightly longer cheer--Woohoo!>', 28153),
(145122, 'itIT', 'Il fuoco sarà la sua rovina!', '', 28153),
(145121, 'itIT', '', '<Chiocciare di gallina>', 28153),
(145120, 'itIT', '', '<Pianto>', 28153),
(145119, 'itIT', '\"Prego. Ti stavo solo ripagando della gentilezza che hai mostrato nei miei confronti\".', '\"Prego. Ti stavo solo ripagando della gentilezza che hai mostrato nei miei confronti\".', 28153),
(145118, 'itIT', '', '<Pianto>', 28153),
(145117, 'itIT', '', '<Crying sounds, variant.>', 28153),
(145116, 'itIT', '', '<Kiss sound>', 28153),
(145115, 'itIT', '\"Grazie, amico mio\", disse Arom al cervo.', '\"Grazie, amico mio\", disse Arom al cervo.', 28153),
(145114, 'itIT', '', '<Laughing sounds>', 28153),
(145113, 'itIT', '', '<Risata>', 28153),
(145112, 'itIT', '', '<Making a raspberry sound--Pfffthblth!>', 28153),
(145111, 'itIT', 'Insieme, Arom e il cervo bianco combatterono i guerrieri e li sconfissero.', 'Insieme, Arom e il cervo bianco combatterono i guerrieri e li sconfissero.', 28153),
(145110, 'itIT', '', '<Roar of dominance>', 28153),
(145109, 'itIT', '', '<Variant roar>', 28153),
(145108, 'itIT', '', '<Sighing sound>', 28153),
(145107, 'itIT', '', '<Train noises--chugga chugga choo choo!>', 28153),
(145106, 'itIT', 'Il cervo bianco tornò e travolse dei Drust!', 'Il cervo bianco tornò e travolse dei Drust!', 28153),
(145105, 'itIT', 'Un potente bramito arrivò dalla foresta.', 'Un potente bramito arrivò dalla foresta.', 28153),
(145104, 'itIT', 'Determinato a eliminare quanti più guerrieri possibile, continuò a combattere.', 'Determinato a eliminare quanti più guerrieri possibile, continuò a combattere.', 28153),
(145103, 'itIT', 'Ser Arom diede battaglia a dieci guerrieri! Combatté valorosamente e con scaltrezza, ma si ritrovò circondato e sopraffatto dal loro numero!', 'Ser Arom diede battaglia a dieci guerrieri! Combatté valorosamente e con scaltrezza, ma si ritrovò circondato e sopraffatto dal loro numero!', 28153),
(145102, 'itIT', 'Curioso.', 'Curioso.', 28153),
(145101, 'itIT', 'Durante la notte, i Drust attaccarono.', 'Durante la notte, i Drust attaccarono.', 28153),
(145100, 'itIT', 'Il cervo tornò nei boschi e Arom stabilì un accampamento.', 'Il cervo tornò nei boschi e Arom stabilì un accampamento.', 28153),
(145099, 'itIT', '\"Chiunque sia in grado di combattere così tanti Drust deve rimanere in questa foresta\", pensò. Arom si mise quindi a curare le ferite del cervo.', '\"Chiunque sia in grado di combattere così tanti Drust deve rimanere in questa foresta\", pensò. Arom si mise quindi a curare le ferite del cervo.', 28153),
(145098, 'itIT', 'Attenzione alle spine!', '', 28153),
(145097, 'itIT', 'La gente di Arom aveva bisogno di cibo e l\'enorme cervo sarebbe stato perfetto per questo scopo, ma egli decise di non attaccarlo.', 'La gente di Arom aveva bisogno di cibo e l\'enorme cervo sarebbe stato perfetto per questo scopo, ma egli decise di non attaccarlo.', 28153),
(145096, 'itIT', 'Il cervo era stato attaccato dai Drust. Ne aveva uccisi parecchi, ma era ferito.', 'Il cervo era stato attaccato dai Drust. Ne aveva uccisi parecchi, ma era ferito.', 28153),
(145095, 'itIT', 'Un giorno, mentre Ser Arom stava cacciando nella foresta, si imbatté in un gigantesco cervo bianco.', 'Un giorno, mentre Ser Arom stava cacciando nella foresta, si imbatté in un gigantesco cervo bianco.', 28153),
(145094, 'itIT', 'Sì! Liberateci!', '', 28153),
(145093, 'itIT', 'Ci avete... liberati...', '', 28153),
(145092, 'itIT', 'Finalmente... liberi...', '', 28153),
(145091, 'itIT', 'Grazie...', '', 28153),
(145090, 'itIT', 'Ora sei dei nostri.', '', 28153),
(145089, 'itIT', 'Non c\'è via di fuga.', '', 28153),
(145088, 'itIT', '', 'Abbattetelo!', 28153),
(145087, 'itIT', '', 'Uccidete il mio bersaglio!', 28153),
(145086, 'itIT', '', 'Concentratevi sul nemico!', 28153),
(145085, 'itIT', 'Scappate! Non c\'è alcuna speranza!', '', 28153),
(145084, 'itIT', 'Insieme... per l\'eternità.', '', 28153),
(145083, 'itIT', '', 'Alle armi!', 28153),
(145082, 'itIT', '', 'Per la regina!', 28153),
(145081, 'itIT', '', 'Per il potere della montagna!', 28153),
(145080, 'itIT', 'Fuggite dal nostro tormento!', '', 28153),
(145079, 'itIT', '', 'Annientateli!', 28153),
(145078, 'itIT', '', 'Respingeteli!', 28153),
(145077, 'itIT', '', 'Dovete ripiegare!', 28153),
(145076, 'itIT', '', 'Ritirata!', 28153),
(145075, 'itIT', '', 'Via da qui!', 28153),
(145074, 'itIT', '', 'Da questa parte.', 28153),
(145073, 'itIT', '', 'Faccio strada.', 28153),
(145072, 'itIT', '', 'Vieni con me.', 28153),
(145071, 'itIT', '', 'Per l\'Alleanza!', 28153),
(145070, 'itIT', '', 'Mi serve aiuto!', 28153),
(145069, 'itIT', '', 'Aiutatemi!', 28153),
(145068, 'itIT', '', 'Pericolo in arrivo!', 28153),
(145067, 'itIT', '', 'Fuoco alle polveri!', 28153),
(145066, 'itIT', '', 'Fuoco!', 28153),
(145065, 'itIT', '', 'Resta qui.', 28153),
(145064, 'itIT', '', 'Non muoverti.', 28153),
(145063, 'itIT', '', 'Le mie ferite sono gravi!', 28153),
(145062, 'itIT', '', 'Ho bisogno di cure!', 28153),
