(145060, 'itIT', '', '<Big attack: Total 5>', 28153),
(145059, 'itIT', '', '<Convey releasing power or charging enemy: Total 4-6>', 28153),
(145058, 'itIT', '', '<Release spell, throwing energy: Total 3-5>', 28153),
(145057, 'itIT', '', '<Convey summoning power. Energy buildup: Total 5-7>', 28153),
(145056, 'itIT', '', '<Charging to attack enemy: Total 5-7>', 28153),
