(145052, 'itIT', '', '<Falling from high terrain. Impending injury or death: Total 1>', 28153),
(145051, 'itIT', '', '<Deep breath before focusing magic: Total 3>', 28153),
(145050, 'itIT', '', '<Jumping off ground: Total 3>', 28153),
(145049, 'itIT', '', '<Landing from jump: Total 3>', 28153),
