(145045, 'itIT', '', '<Player takes a wound: Total 10>', 28153),
(145044, 'itIT', '', '<Player takes significant wound: Total 5>', 28153),
(145043, 'itIT', '', 'Mantieni gli occhi sull\'obiettivo.', 28153),
(145042, 'itIT', '', 'Facciamo ciò che dobbiamo per coloro che amiamo.', 28153),
(145041, 'itIT', '', 'Che la tua mira sia salda.', 28153),
(145040, 'itIT', '', 'Addio.', 28153),
(145039, 'itIT', '', 'Le ombre possono essere un alleato... se controllate.', 28153),
(145038, 'itIT', '', 'Salve.', 28153),
(145037, 'itIT', '', 'Non possiamo invitare nessun altro.', 28153),
(145036, 'itIT', '', 'Ognuno di noi segue un sentiero. Sta a te scegliere quale.', 28153),
(145035, 'itIT', '', 'Non posso bere altro al momento.', 28153),
(145034, 'itIT', '', 'Non ho ancora quest\'abilità.', 28153),
(145033, 'itIT', '', 'Non posso ancora farlo.', 28153),
(145032, 'itIT', '', 'L\'incantesimo non è pronto.', 28153),
(145031, 'itIT', '', 'Ci sono novità?', 28153),
(145030, 'itIT', '', 'Non posso ancora lanciarlo.', 28153),
(145029, 'itIT', '', 'Si sta ancora ricaricando.', 28153),
(145028, 'itIT', '', 'Usa ogni arma a tua disposizione.', 28153),
(145027, 'itIT', '', 'Oggi è un buon giorno per cacciare.', 28153),
(145026, 'itIT', '', 'Finisco dispersa per tutti questi anni ed è così che mi tratti?', 28153),
(145025, 'itIT', '', 'Non posso farlo.', 28153),
(145024, 'itIT', '', 'Prima devo ottenere il permesso.', 28153),
(145023, 'itIT', '', 'Non posso attaccare quel bersaglio.', 28153),
(145022, 'itIT', '', 'Il mio Vuoto ti consumerà... se lo chiederai con gentilezza.', 28153),
(145021, 'itIT', '', 'Non lo posso attaccare.', 28153),
(145020, 'itIT', '', 'Il mio inventario è pieno.', 28153),
(145019, 'itIT', '', 'Non posso portare altro.', 28153),
(145018, 'itIT', '', 'Eh... Le sorelle sono complicate. Soprattutto quelle non morte.', 28153),
(145017, 'itIT', '', 'È bloccato.', 28153),
(145016, 'itIT', '', 'Non posso trasportarne altri.', 28153),
(145015, 'itIT', '', 'Non posso ancora usare quest\'oggetto.', 28153),
(145014, 'itIT', '', 'Non è ancora pronto.', 28153),
(145013, 'itIT', '', 'L\'oggetto si sta ancora caricando.', 28153),
(145012, 'itIT', '', 'Non ho abbastanza furia.', 28153),
(145011, 'itIT', '', 'Ho poca furia.', 28153),
(145010, 'itIT', '', 'Ho poco dolore.', 28153),
(145009, 'itIT', '', 'Non ho abbastanza dolore.', 28153),
(145008, 'itIT', '', 'Non è una sacca.', 28153),
(145007, 'itIT', '', 'Non ho i fondi necessari.', 28153),
(145006, 'itIT', '', 'Questo va oltre le mie disponibilità.', 28153),
(145005, 'itIT', '', 'Costa troppo.', 28153),
(145004, 'itIT', '', 'Non può unirsi a questo gruppo.', 28153),
(145003, 'itIT', '', 'Ho finito le munizioni.', 28153),
(145002, 'itIT', '', 'Non ho abbastanza energia.', 28153),
(145001, 'itIT', '', 'Mi manca l\'energia necessaria.', 28153),
(145000, 'itIT', '', 'Ho bisogno di mana prima di farlo.', 28153),
(144999, 'itIT', '', 'Ho poco mana.', 28153),
(144998, 'itIT', '', 'Ho bisogno di mana.', 28153),
(144997, 'itIT', '', 'Non ho abbastanza rabbia.', 28153),
(144996, 'itIT', '', 'Devo avere più rabbia!', 28153),
(144995, 'itIT', '', 'È troppo lontano.', 28153),
(144994, 'itIT', '', 'Sì, certo che lo amo ancora. Ora vuoi smetterla di importunarmi?', 28153),
(144993, 'itIT', '', 'Sono fuori portata.', 28153),
(144992, 'itIT', '', 'Devo avvicinarmi.', 28153),
(144991, 'itIT', '', 'La mia arma richiede due mani.', 28153),
(144990, 'itIT', '', 'L\'abilità non è pronta.', 28153),
(144989, 'itIT', '', 'Non posso ancora farlo.', 28153),
(144988, 'itIT', '', 'Non sono ancora pronta.', 28153),
(144987, 'itIT', '', 'Non è la posizione giusta.', 28153),
(144986, 'itIT', '', 'Questa sacca è piena.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144985, 'itIT', '', 'Non posso farlo qui.', 28153),
(144984, 'itIT', '', 'Non posso lasciare quest\'oggetto.', 28153),
(144983, 'itIT', '', 'Quest\'oggetto è vincolato a me.', 28153),
(144982, 'itIT', '', 'Non lo posso equipaggiare.', 28153),
(144981, 'itIT', '', 'Non sono di livello abbastanza alto per usarlo.', 28153),
(144980, 'itIT', '', 'Non lo posso ancora usare.', 28153),
(144979, 'itIT', '', 'La mia competenza non è abbastanza alta.', 28153),
(144978, 'itIT', '', 'Non potrò mai equipaggiare quest\'oggetto.', 28153),
(144977, 'itIT', '', 'Non posso imparare quest\'incantesimo.', 28153),
(144976, 'itIT', '', 'Non posso depredarlo.', 28153),
(144975, 'itIT', '', 'Quest\'oggetto non è mio.', 28153),
(144974, 'itIT', '', 'Devo avvicinarmi.', 28153),
(144973, 'itIT', '', 'È troppo lontano.', 28153),
(144972, 'itIT', '', 'Non ci arrivo.', 28153),
(144971, 'itIT', '', 'Non posso scambiare quest\'oggetto.', 28153),
(144970, 'itIT', '', 'Non posso usare quest\'oggetto.', 28153),
(144969, 'itIT', '', 'Quest\'oggetto non è equipaggiato.', 28153),
(144968, 'itIT', '', 'Deve essere prima equipaggiato.', 28153),
(144967, 'itIT', '', 'Non posso depredarlo in questo momento.', 28153),
(144966, 'itIT', '', 'Non ho un bersaglio.', 28153),
(144965, 'itIT', '', 'Prima devo avere un bersaglio.', 28153),
(144964, 'itIT', '', 'Ho bisogno di un bersaglio.', 28153),
(144963, 'itIT', '', 'Di fuochi e spiriti è la danza, spenta la luce l\'ombra avanza!', 28153),
(144962, 'itIT', '', 'Dai l\'iride a me, sorella!', 28153),
(144961, 'itIT', '', 'Le mie spine ti faranno a pezzi!', 28153),
(144960, 'itIT', '', 'Più ti dimeni, più fa male!', 28153),
(144959, 'itIT', '', 'Il marchio nero è su di te!', 28153),
(144958, 'itIT', '', 'I vostri teschi saranno dei bellissimi soprammobili.', 28153),
(144956, 'itIT', '', 'Le mie radici spunteranno ancora...', 28153),
(144955, 'itIT', '', 'Adoro il suono degli arti che si spezzano.', 28153),
(144954, 'itIT', 'Chesta sera mangerò bene assai. Nu ringraziamento e na preghiera per te.', 'Chesta sera mangerò bene assai. Nu ringraziamento e na preghiera per te.', 28153),
(144953, 'itIT', 'Quanta gentilezza per nu vagabondo. Grazie!', 'Quanta gentilezza per na vagabonda. Grazie!', 28153),
(144952, 'itIT', 'Grazie, $gamico mio:amica mia;.', 'Grazie, $gamico mio:amica mia;.', 28153),
(144951, 'itIT', '', 'Che fragile mucchio d\'ossa!', 28153),
(144950, 'itIT', '<Dona dieci monete d\'oro.>', '<Dona dieci monete d\'oro.>', 28153),
(144949, 'itIT', '<Dona una moneta d\'oro.>', '<Dona una moneta d\'oro.>', 28153),
(144948, 'itIT', '<Dona cinque monete di rame.>', '<Dona cinque monete di rame.>', 28153),
(144947, 'itIT', 'Tieni qualche moneta di rame da prestarmi?', 'Tieni qualche moneta di rame da prestarmi?', 28153),
(144946, 'itIT', '', 'Volti alla luna non potete scappar, ballano le streghe di Drustvar!', 28153),
(144945, 'itIT', '', 'Ahahah! La tua distruzione è vicina.', 28153),
(144944, 'itIT', '', 'Ha! Il tuo turno è finito!', 28153),
(144943, 'itIT', '', 'E Rezan ruggì sui cadaveri dell\'esercito dei Troll del Sangue. Trionfante!', 28153),
(144942, 'itIT', '', 'Il vostro tormento è appena iniziato. Ahahah!', 28153),
(144941, 'itIT', '', 'Ahahah! Che magnifica agonia! Ahah!', 28153),
(144940, 'itIT', '', 'Il mio corpo è distrutto... ma la mia maledizione continua...', 28153),
(144939, 'itIT', '', 'Ha-ahah! Strapperò le urla dalla tua carne!', 28153),
(144938, 'itIT', '', 'Spiriti potenti, vi invochiamo! Vegliate su noi, che stanotte uccidiamo!', 28153),
(144937, 'itIT', '', 'Adesso appartieni a me!', 28153),
(144936, 'itIT', '', 'Balla, burattino! Balla!', 28153),
(144935, 'itIT', '', 'Dammi l\'iride! Solo io posso sfruttare il suo potere!', 28153),
(144934, 'itIT', '', 'Le vostre anime appartengono a me... per sempre.', 28153),
(144933, 'itIT', '', 'La morte non mi fermerà...', 28153),
(144932, 'itIT', '', 'Che anima fragile!', 28153),
(144931, 'itIT', '', 'Non hai alcun potere qui!', 28153),
(144930, 'itIT', '', 'Seguimi. Tutti li altri si uniscano a Rokhan sul fronte di battaglia a nord.', 28153),
(144929, 'itIT', 'Guardate! Soldati dell\'Alleanza! Stanno mandando tutte le truppe a disposizione!', '', 28153),
(144928, 'itIT', 'Ci stanno mandando contro un sacco di soldati! Non lasciateli passare!', '', 28153),
(144926, 'itIT', '', 'Salve, $C.', 28153),
(144925, 'itIT', '', 'Ricorda sempre cosa significa servire la Luce.', 28153),
(144924, 'itIT', '', '<Fareeya ti accoglie con un caldo sorriso.>$B$BHai agito bene durante le prove, $C, ma sento che la tua storia è soltanto all\'inizio.', 28153),
(144923, 'itIT', 'Se stai cercando Maela, sta aiutando al fronte.$B$BRoccavento è dimora di numerosi sarti di talento che possono insegnarti un po\' di cose.', '', 28153),
(144921, 'itIT', '', 'Per la Luce! Non potrò mai più usare di nuovo questo laboratorio.$B$BLa corruzione emanata dalle pelli di quelle bestie di Argus non accenna a diminuire, a prescindere da quante volte provi a grattarle.', 28153),
(144908, 'itIT', 'La Vindicaar attende il suo prossimo viaggio, proprio come me.', '', 28153),
(144907, 'itIT', 'Grazie per l\'aiuto, $gragazzo:ragazza;! Te ne devo una!', '', 28153),
(144906, 'itIT', 'Va be\', io me ne torno alla locanda.', '', 28153),
(144905, 'itIT', 'Ahhh, ora va meglio. Un\'armatura degna di un potente eroe, le cui leggendarie gesta scuotono le stesse fondamenta di Azeroth!', '', 28153),
(144904, 'itIT', 'Ci puoi scommettere! Ho comprato quest\'armatura a tutti gli effetti, anche se non ho ancora finito di pagarla.', '', 28153),
(144903, 'itIT', '', 'A quanto pare oggi è il tuo giorno fortunato, Cigliadure. Puoi riprenderti la merce.', 28153),
(144902, 'itIT', 'Tieni le tue zampe lontane da me, palla di pelo!', '', 28153),
(144901, 'itIT', '', 'Sì, signora.', 28153),
(144900, 'itIT', '', 'Andate via! Non abbiamo paura di voi!', 28153),
(144899, 'itIT', '%s annuisce.', '', 28153),
(144898, 'itIT', '', 'Chu, accompagna questo Nano fuori di qui. Xulian, rimetti l\'armatura in inventario.', 28153),
(144897, 'itIT', 'Ho spedito l\'assegno stamattina, lo giuro! Non puoi lasciarmi a secco!', '', 28153),
(144896, 'itIT', '', 'Questa è l\'ultima volta che ti dimentichi di pagare, Cigliadure. Sono qui per requisire la merce, come da contratto.', 28153),
(144895, 'itIT', '', 'Sono qui...', 28153),
(144894, 'itIT', '', 'Lo faremo. Ora siediti.', 28153),
(144893, 'itIT', 'Sono arrivati dai boschi. Abbiamo combattuto. Il Maestro Ashton mi ha spinto via ed è stato catturato. Dobbiamo salvarlo!', '', 28153),
(144892, 'itIT', '', 'Lo so, Marten. Dicci cosa è successo.', 28153),
(144891, 'itIT', 'Ho fatto del mio meglio per respingerli!', '', 28153),
(144889, 'itIT', '', 'Quindi... perché hai portato la Nana? Una dimostrazione di forza? Un deterrente?', 28153),
(144888, 'itIT', 'Ha funzionato esattamente come mi immaginavo.', '', 28153),
(144887, 'itIT', 'Giusto... Sì. Naturalmente!', '', 28153),
(144886, 'itIT', 'Non dimenticarti del nostro obiettivo qui. Dobbiamo trovare l\'Occhio prima dell\'Alleanza.', '', 28153),
(144885, 'itIT', '', 'E pensare che i Troll se ne sono stati qui seduti su quello che potrebbe essere il ritrovamento archeologico del millennio!', 28153),
(144884, 'itIT', '', 'La battaglia è iniziata! Portaci alla vittoria!', 28153),
(144883, 'itIT', 'Quando te ne sei andata, hai detto a tuo padre che eri andata in esplorazione. Nun a negoziare con quei cani dell\'Orda.', '', 28153),
(144882, 'itIT', 'Principessa.', '', 28153),
(144881, 'itIT', 'Stiamo facendo attendere il padre tuo.', '', 28153),
(144880, 'itIT', '', 'Principessa... permettimi di essere il primo a darti...', 28153),
(144879, 'itIT', '', 'Sappi chesto... Il padre mio è testardo, ma nun è no stupido. Scommetto che è al corrente del tuo ruolo nella liberazione mia da Roccavento.', 28153),
(144878, 'itIT', '', 'Nun sarai tu a decidere il destino loro, Generale.', 28153),
(144877, 'itIT', 'Il modo migliore per proteggere il regno sarebbe esiliare chesta... cosa... a Vol\'dun. L\'Orda nun tiene diritto di stare a Zandalar.', '', 28153),
(144876, 'itIT', '', 'Hai giurato di proteggere chesto regno. Se nun fai il dovere tuo, allora devo chiedere a qualcun altro.', 28153),
(144875, 'itIT', '<Tocca la lacrima.>', '<Tocca la lacrima.>', 28153),
(144874, 'itIT', '', 'Generale.', 28153),
(144873, 'itIT', '<La lacrima di un Drago Verde, gettata nell\'ombra da forze sconosciute.>', '', 28153),
(144872, 'itIT', '', 'Nel frattempo, il Concilio delli Zanchuli, dei vecchi e decrepiti politici cospiratori, negano del tutto la minaccia. Hanno convinto mio padre che nun ci stava alcun pericolo.', 28153),
(144871, 'itIT', '', 'I Troll del Sangue attaccano i confini settentrionali e trascinano la gente nostra nelle paludi di Nazmir, da cui nessuno torna.', 28153),
(144870, 'itIT', '', 'Zandalar è circondata da nemici, sia interni che esterni. È per chesto che ho cercato l\'aiuto dell\'Orda... e il tuo.', 28153),
(144869, 'itIT', '', 'Teniamo solo qualche momento da soli. Ci stanno alcune cose sul regno mio che devi sapere.', 28153),
(144868, 'itIT', '', 'Vieni, facciamo visita al padre mio. Zul... parleremo più tardi.', 28153),
(144867, 'itIT', '', 'Tze\'na! Ciao piccirilla, ti sono mancata?', 28153),
(144866, 'itIT', '', 'Ho sentito i pianti della bambina di cui parli.\n\nTi lascerò un marchio, così potrai mettere piede in questo reame per andare a cercarla.\n\nSi trova in un luogo in cui il confine tra i reami della vita e della morte è sottile e si confonde con il tuo mondo.\n\nFai attenzione, però: non hai alcun potere in questo posto, e i suoi abitanti non possono essere toccati dai mortali.\n\nSei $glibero:libera; di provarci, ma non ti assicuro che riuscirai ad aiutare la tua amica.', 28153),
(144864, 'itIT', 'Che la Luce sia con te.', 'Che la Luce sia con te.', 28153),
(144863, 'itIT', 'Sto cercando una ragazzina di nome Uuna, l\'hai vista?', 'Sto cercando una ragazzina di nome Uuna, l\'hai vista?', 28153),
(144862, 'itIT', '', 'T\'paartos ci ha insegnato a giocare a masso, pergamena, lama... ma ho dimenticato le regole.', 28153),
(144860, 'itIT', 'Il Cancello dell\'Alleanza è stato distrutto!', '', 28153),
(144859, 'itIT', '', 'Grifoni! All\'attacco!', 28153),
(144853, 'itIT', 'I nostri guerrieri più coraggiosi sono spesso impegnati al fronte. Vegliare sulle loro famiglie fino al loro ritorno è il minimo che io possa fare.', 'I nostri guerrieri più coraggiosi sono spesso impegnati al fronte. Vegliare sulle loro famiglie fino al loro ritorno è il minimo che io possa fare.', 28153),
(144852, 'itIT', 'Entri nelle mie gallerie? Folle!', '', 28153),
(144851, 'itIT', '', 'La sua coda è così soffice!', 28153),
(144850, 'itIT', '', 'Posso tenerla?', 28153),
(144849, 'itIT', '', 'No! Rimani e raccontaci le tue avventure, T\'paartos!', 28153),
(144848, 'itIT', '', 'È tornato!', 28153),
(144847, 'itIT', '', 'È T\'paartos!', 28153),
(144846, 'itIT', 'Non preoccupatevi! T\'paartos tornerà con altre storie e forse un altro amico.', '', 28153),
(144845, 'itIT', 'T\'paartos ora deve riportare a casa questa cuccioletta. Salutatela, bambini.', '', 28153),
(144842, 'itIT', '', 'Ohhh!', 28153),
(144841, 'itIT', 'Ho bisogno di sapere cos\'è successo alla festa.', 'Ho bisogno di sapere cos\'è successo alla festa.', 28153),
(144840, 'itIT', 'La Dama Oscura ha un incarico importante per te, $C. Spero tu sia $gpronto:pronta;...', '', 28153),
(144839, 'itIT', '', 'T\'paartos!', 28153),
(144838, 'itIT', '', 'Promettimi che non mi abbandonerai, $gamico mio:amica mia;. Anche quando diventerà buio...', 28153),
(144837, 'itIT', '', 'Ma ora sei qui. Insieme possiamo combatterli! Credo...', 28153),
(144836, 'itIT', '', 'Io non faccio che correre... ma alla fine riescono sempre a trovarmi.', 28153),
(144835, 'itIT', '', 'Presto saranno qui, $gamico:amica;.', 28153),
(144834, 'itIT', '', 'Eccoti! Ora va molto meglio.', 28153),
(144833, 'itIT', 'Ahahah! T\'paartos è felice di vedere che stai bene! T\'paartos ti ha portato un regalo. Questa piccoletta era a Val\'sharah.', '', 28153),
(144832, 'itIT', 'Stai SCHERZANDO?!?', '', 28153),
(144831, 'itIT', 'Questi globi sembrano contenere un qualche tipo di potere. Forse, rimuovendo l\'involucro...', '', 28153),
(144830, 'itIT', 'Bleah!', '', 28153),
(144829, 'itIT', 'Questi occhi sembrano belli sodi. Basterà strizzarli un po\' e...', '', 28153),
(144828, 'itIT', '', 'Ho tanto freddo, ed è così buio. Non so che fare!', 28153),
(144827, 'itIT', '', 'Non mi arrenderò, $gamico:amica;! Lo prometto!', 28153),
(144826, 'itIT', '', '$gAmico:Amica;? Sei tu?', 28153),
(144825, 'itIT', 'I nostri agenti si sono già infiltrati nella miniera dei Goblin qui sotto. Molto presto conosceremo tutti i dettagli su cosa stanno combinando...', '', 28153),
(144824, 'itIT', 'Bisogna scavare... più a fondo...', 'Bisogna scavare... più a fondo...', 28153),
(144823, 'itIT', 'Un Elfo... che scava... ahahah!', 'Un Elfo... che scava... ahahah!', 28153),
(144822, 'itIT', 'Troppo tardi. Abbiamo trovato...', 'Troppo tardi. Abbiamo trovato...', 28153),
(144821, 'itIT', 'Chi cerca, trova e tiene...', 'Chi cerca, trova e tiene...', 28153),
(144820, 'itIT', 'Non lo troverai mai...', 'Non lo troverai mai...', 28153),
(144819, 'itIT', 'La tua ricerca finisce qui. Muori!', 'La tua ricerca finisce qui. Muori!', 28153),
(144818, 'itIT', 'Mi divertirò a seppellirti.', 'Mi divertirò a seppellirti.', 28153),
(144817, 'itIT', 'Scaveremo la terra sotto i tuoi piedi!', 'Scaveremo la terra sotto i tuoi piedi!', 28153),
(144816, 'itIT', 'Pensi di poterti mettere contro i Ferroscuro? Ti sbagli di grosso.', 'Pensi di poterti mettere contro i Ferroscuro? Ti sbagli di grosso.', 28153),
(144815, 'itIT', 'Ficcanaso! Queste rovine appartengono ai Ferroscuro!', 'Ficcanaso! Queste rovine appartengono ai Ferroscuro!', 28153),
(144812, 'itIT', '', 'Rinforzi nemici in arrivo!', 28153),
(144811, 'itIT', 'Le letture sono chiarissime! Andremo a ovest!', '', 28153),
(144810, 'itIT', '', 'La Gola è nostra! Raggruppiamoci, dobbiamo pianificare il prossimo assalto.', 28153),
(144809, 'itIT', '', 'Cerchi di far entrare nu totem quadrato in nu supporto per totem tondi. Il vudù conosce li stati d\'animo, Goblin.', 28153),
(144808, 'itIT', 'Si materializzano dalle ombre, sono dappertutto!', 'Si materializzano dalle ombre. Sono dappertutto!', 28153),
(144807, 'itIT', '', 'Una qualità ammirevole. È una cosa che apprezzo molto di lui.', 28153),
(144806, 'itIT', '', 'Oh, sì, proprio come ieri, il giorno prima e quello prima ancora!', 28153),
(144805, 'itIT', 'Le gallerie sono al sicuro. Aprite i cancelli!', '', 28153),
(144804, 'itIT', 'Oggi è di buon umore, vedo.', '', 28153),
(144803, 'itIT', '', 'Il nemico si avvicina! Bwonsalaka!', 28153),
(144802, 'itIT', 'Tornerò dagli altri. Dobbiamo fermare tutto questo finché è ancora possibile.', '', 28153),
(144801, 'itIT', 'Grazie. Temo che la situazione sia più grave di quanto pensassimo.', '', 28153),
(144800, 'itIT', 'Ho bisogno di sapere cos\'è successo al Riposo del Leone.', 'Ho bisogno di sapere cos\'è successo al Riposo del Leone.', 28153),
(144799, 'itIT', 'I miei agenti hanno messo al sicuro l\'area. Comunque, è sempre prudente tenere le voci basse.', '', 28153),
(144798, 'itIT', 'Bwon\'chaga di choka!', 'Bwon\'chaga di choka!', 28153),
(144796, 'itIT', '', 'Il vudù tocca tutti nel core, Cala, che uno ci creda oppure no.', 28153),
(144795, 'itIT', '', 'Il vudù può permetterti di leggere la mente dei dinosauri? Sul serio?!?', 28153),
(144794, 'itIT', '', 'Si tratta di na questione d\'amore, Cala. Il core, pure il tuo, sa che il vudù è meglio del cervello.', 28153),
(144792, 'itIT', 'La volontà tua m\'appartiene!', 'Mo\' appartieni a me!', 28153),
(144791, 'itIT', 'I vapori nascondono la verità!', 'I vapori nascondono la verità!', 28153),
(144790, 'itIT', 'Respira profondamente!', 'Respira profondamente!', 28153),
(144789, 'itIT', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Rezan |cFFFF0000|Hspell:260683|h[risveglia]|h|r le pile d\'ossa rimanenti!', '|TInterface\\Icons\\SPELL_SHAMAN_EARTHQUAKE.BLP:20|t Rezan |cFFFF0000|Hspell:260683|h[risveglia]|h|r le pile d\'ossa rimanenti!', 28153),
(144788, 'itIT', '', 'G\'huun...', 28153),
(144787, 'itIT', '', 'No... nun così...', 28153),
(144786, 'itIT', '', 'Le sorelle mie... mi vendicheranno...', 28153),
(144785, 'itIT', '', 'Gachaga...', 28153),
(144784, 'itIT', '', 'Zuldazar... cadrà...', 28153),
(144783, 'itIT', '', 'Padrona... vendicami...', 28153),
(144782, 'itIT', '', 'Dovevo essere... la più potente...', 28153),
(144781, 'itIT', '', 'Pohkiza...', 28153),
(144780, 'itIT', 'Be\', fantastico.', '', 28153),
(144779, 'itIT', 'Ottimo lavoro con quelle pozioni, $n. Ora non resta che aggiungere un paio di gocce di ognuna e...', '', 28153),
(144778, 'itIT', '', 'Nu giochetto da niente!', 28153),
(144777, 'itIT', '', 'La morte tua sarà rapida!', 28153),
(144776, 'itIT', '', 'Ah! Fin troppo facile!', 28153),
(144775, 'itIT', '', 'N\'altro teschio per la collezione mia!', 28153),
(144774, 'itIT', '', 'Chesta terra è nostra!', 28153),
(144773, 'itIT', 'Forza! Vieni qui! Abbiamo del lavoro da fare!', '', 28153),
(144772, 'itIT', 'Fa bene riposarsi di tanto in tanto.$B$BSoprattutto dopo un\'avventura remunerativa!', '', 28153),
(144771, 'itIT', 'Tu spegni quegli incendi, io preparerò ciò di cui abbiamo bisogno nel laboratorio.', '', 28153),
(144770, 'itIT', 'Al momento sono a corto di materiali. Ti porgo le mie scuse.', '', 28153),
(144769, 'itIT', 'Ho parecchi globi per te, Elric.', 'Ho parecchi globi per te, Elric.', 28153),
(144768, 'itIT', 'Ho quelle erbe che stavi cercando.', 'Ho quelle erbe che stavi cercando.', 28153),
(144767, 'itIT', 'Ecco gli occhi che avevi chiesto.', 'Ecco gli occhi che avevi chiesto.', 28153),
(144766, 'itIT', 'Ecco le pozioni che ti servivano.', 'Ecco le pozioni che ti servivano.', 28153),
(144765, 'itIT', 'Ah, $gun :un\';Alchimista! Forse potrebbero interessarti alcune delle mie ultime ricette.$b$bLe pozioni sono la mia specialità, ma mi occupo anche di trasmutazioni di tanto in tanto.', '', 28153),
(144764, 'itIT', 'Ti do il benvenuto nella mia bottega, $C! Ti interessa una bevanda rinfrescante o preferisci altro?$b$bLe pozioni sono la mia specialità, ma mi occupo anche di trasmutazioni di tanto in tanto.', '', 28153),
(144763, 'itIT', '', 'Carne fresca!', 28153),
(144762, 'itIT', '', 'Le orecchie loro penzoleranno dalla collana mia!', 28153),
(144761, 'itIT', '', 'Sangue per G\'huun!', 28153),
(144760, 'itIT', 'Shhh! Non muoverti! Può vedere soltanto i movimenti.', 'Shhh! Non muoverti! Può vedere soltanto i movimenti.', 28153),
(144759, 'itIT', 'Che la Luce mi salvi... è tornato!', 'Che la Luce mi salvi... è tornato!', 28153),
(144758, 'itIT', '<Il Vendicatore Forgialuce emette un gemito.>', '<Il Vendicatore Forgialuce emette un gemito.>', 28153),
(144757, 'itIT', 'Credevo che la mia mente fosse condannata.', 'Credevo che la mia mente fosse condannata.', 28153),
(144756, 'itIT', 'Che la Madre Terra ti benedica!', 'Che la Madre Terra ti benedica!', 28153),
(144755, 'itIT', 'È stato terribile, $R.', 'È stato terribile, $R.', 28153),
(144754, 'itIT', 'Devo... La mia mente... Devo andarmene da questo posto!', 'Devo... La mia mente... Devo andarmene da questo posto!', 28153),
(144753, 'itIT', 'I sussurri... mi stavano facendo impazzire!', 'I sussurri... mi stavano facendo impazzire!', 28153),
(144752, 'itIT', 'Grazie, $gcampione:campionessa;.', 'Grazie, $gcampione:campionessa;.', 28153),
(144751, 'itIT', '', 'Anche l\'arma migliore si consuma con l\'uso. Prenditi un po\' di tempo per guarire, T\'paartos.', 28153),
(144750, 'itIT', 'T\'paartos è molto grato a Lysara. T\'paartos sente di essere di nuovo pronto a combattere!', '', 28153),
(144749, 'itIT', 'Non c\'è tempo per fermare T\'paartos!', '', 28153),
(144748, 'itIT', 'Piglia l\'Amuleto con Effige mio. Fidati, è la cosa migliore che tengo.', '', 28153),
(144747, 'itIT', 'Chesta è n\'ottima contraffazione! Dove l\'hai presa? Nun dirmi i nomi, ma di\' loro di venirmi a trovare.', '', 28153),
(144746, 'itIT', 'Tieni la bocca chiusa su come lo hai ottenuto o ti mostrerò l\'origine del nome mio.', '', 28153),
(144745, 'itIT', '', 'Ancora, T\'paartos? Quante volte devi ancora...', 28153),
(144744, 'itIT', 'Non è una testa di Elfa della Notte qualsiasi... migliaia d\'anni fa apparteneva alla nobiltà!', '', 28153),
(144743, 'itIT', 'Il tempo lo dirà. $p, provvedi a chel Bocciolo Secolare. Sboccia na volta ogni cento anni.', '', 28153),
(144742, 'itIT', '', 'Semi Dorati! Li pianteremo subito per il re. Cosa credi che crescerà, Jahden?', 28153),
(144741, 'itIT', 'Chesto pepe sarà perfetto per la prossima porzione di chili extra piccante mia... mentre chei Semi Dorati sanno di terra!', '', 28153),
(144740, 'itIT', '', 'Erano reali. Sono reali. Dama Lucille è determinata a riprendersi le nostre terre e la nostra gente.', 28153),
(144739, 'itIT', 'Se è così, avrà il mio pieno supporto.', '', 28153),
(144738, 'itIT', 'Davvero? Pensavo fossero solo una leggenda!', '', 28153),
(144737, 'itIT', '', 'Ora sono un\'Inquisitrice, Sindaco. Dama Lucille ha riformato l\'Ordine delle Braci per combattere queste streghe.', 28153),
(144736, 'itIT', 'Non ti ringrazieremo mai abbastanza per il tuo arrivo tempestivo, Tenente.', '', 28153),
(144735, 'itIT', '', 'Grazie, $p! La scorta di Pietre del Ritorno nostra era scarsa. Piglia del pepe, offre la casa.', 28153),
(144734, 'itIT', 'Ti interessa del lavoro, $p? Trova qualcuno interessato a comprare chelle Pietre del Ritorno. Scambiale con qualcosa di grande valore, e io ti sarò riconoscente.', '', 28153),
(144733, 'itIT', 'Sai cosa significa... Legna gratuita!', '', 28153),
(144732, 'itIT', 'Ehm, ehi... capo? Sto ricevendo rapporti su una sorta di albero-mostro gigante che vaga nei pressi dei boschi.', '', 28153),
(144731, 'itIT', 'Screee! Tua madre era un Trogg! Screee!', '', 28153),
(144730, 'itIT', 'Stupidi marinai d\'acqua dolce! SCREEE!', '', 28153),
(144729, 'itIT', 'SCREEE!', '', 28153),
(144728, 'itIT', 'Pssst! Hai mai voluto dare nu pugno potente a qualcuno ma sapevi di nun poterlo fare? Tengo la soluzione giusta per te proprio accà!', '', 28153),
(144727, 'itIT', 'Amuleti incredibili! Oggettistica spettacolare! Tengo offerte speciali per i migliori commercianti!', '', 28153),
(144726, 'itIT', 'Ascolta i sussurri. Sono meravigliosi.', 'Ascolta i sussurri. Sono meravigliosi.', 28153),
(144725, 'itIT', 'Le ombre ti consumeranno.', 'Le ombre ti consumeranno.', 28153),
(144724, 'itIT', 'Benedizioni e urla sono fuori moda! Solo l\'Azerite può darti la forza necessaria ad affrontare i pericoli e le esigenze del mondo. Bevi Azerite Imbottigliata!', '', 28153),
(144723, 'itIT', 'La tua morte è necessaria.', 'La tua morte è necessaria.', 28153),
(144722, 'itIT', 'BASTA! BASTA!', 'BASTA! BASTA!', 28153),
(144721, 'itIT', 'L\'oscurità sta arrivando...', 'L\'oscurità sta arrivando...', 28153),
(144720, 'itIT', 'Se Vol\'jin avesse avuto il suo fidato Totem dell\'Invulnerabilità con sé sulla Riva Dispersa, starebbe ancora tra noi. Nun compiere lo stesso errore!', '', 28153),
(144719, 'itIT', 'Spia i nemici, tieni d\'occhio li amici, dai na sbirciatina alle sale regali... tutto chesto con li incredibili sussurri del Totem degli Spiriti Sussurranti!', '', 28153),
(144718, 'itIT', 'La fiamma di chesto totem ha bruciato sin da quando Re Rastakhan si è seduto sul trono suo. Piglia nu pezzo della storia delli Zandalari!', '', 28153),
(144717, 'itIT', 'Garantito da Griftah. Se nun fai domande, ti becchi no sconto!', '', 28153),
(144716, 'itIT', 'T\'paartos è qui!', '', 28153),
(144715, 'itIT', '', 'Ora mi sento molto meglio.', 28153),
(144714, 'itIT', 'T\'PAARTOS!', '', 28153),
(144713, 'itIT', '', 'Non puoi combattere l\'oscurità senza una corona, $gamico:amica;. Sono le regole.', 28153),
(144712, 'itIT', '', 'Lancia stelline! Ai cattivi non piacerà neanche un po\'.', 28153),
(144711, 'itIT', 'La mia gente si occupa di collezionare e custodire ogni fonte di conoscenza.\n\nÈ mio dovere far sì che le nostre scoperte vengano adeguatamente archiviate.', '', 28153),
(144706, 'itIT', 'Ho molto da preparare. Occupati di loro.', 'Ho molto da preparare. Occupatevi di loro.', 28153),
(144705, 'itIT', 'Bando alle ciance.', 'Sono stufo di queste assurdità.', 28153),
(144704, 'itIT', 'Quelle voci offrono solo menzogne!', '', 28153),
(144703, 'itIT', 'Non percepisci il suo potere sotto di noi? Grazie a lei, saremo finalmente una cosa sola!', 'Non percepisci il suo potere sotto di noi? Grazie a lei, saremo finalmente una cosa sola!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144702, 'itIT', 'Abbiamo giurato entrambi di proteggere Brennadam e la nostra gente! L\'hai forse dimenticato?', '', 28153),
(144701, 'itIT', 'Sei sempre stato troppo debole per servire Ser Sacraonda, abbandonato a Brennadam come uno stupido.', 'Sei sempre stato troppo debole per servire Ser Sacraonda, abbandonato a Brennadam come uno stupido.', 28153),
(144700, 'itIT', 'Sei tu ad essere condannato!', '', 28153),
(144699, 'itIT', 'I mari... ti divoreranno...', '', 28153),
(144698, 'itIT', 'La mia vita... per... Azshara...', '', 28153),
(144697, 'itIT', 'L\'abissso ti prenderà...', '', 28153),
(144696, 'itIT', 'Mia regina... ho fallito...', '', 28153),
(144695, 'itIT', 'La marea... rifluisce...', '', 28153),
(144694, 'itIT', '', 'La marea... rifluisce...', 28153),
(144693, 'itIT', '', 'Mia regina... ho fallito...', 28153),
(144692, 'itIT', '', 'L\'abissso ti prenderà...', 28153),
(144691, 'itIT', '', 'La mia vita per Azshara!', 28153),
(144690, 'itIT', '', 'I mari... ti divoreranno...', 28153),
(144689, 'itIT', 'Ho un\'altra domanda...', 'Ho un\'altra domanda...', 28153),
(144688, 'itIT', 'Sembra tu abbia bisogno di un amico.', 'Sembra tu abbia bisogno di un\'amica.', 28153),
(144687, 'itIT', 'Che cosa stai facendo?', 'Che cosa stai facendo?', 28153),
(144686, 'itIT', 'Sono qui per aiutare, Kugro!', 'Sono qui per aiutare, Kugro!', 28153),
(144685, 'itIT', 'Puoi dare un\'occhiata a questa pergamena?', 'Puoi dare un\'occhiata a questa pergamena?', 28153),
(144684, 'itIT', 'Risparmia il fiato, giovane.\n\nQualsiasi cosa tu voglia, non ho tempo.', '', 28153),
(144683, 'itIT', '$gUn amico:Un\'amica;? No, ma $gun :un\';aiutante sì.', '', 28153),
(144682, 'itIT', 'Posso dirti cosa non sto facendo, ovvero perdere tempo con $gun semplice:una semplice; $R quando c\'è molto altro da fare.', '', 28153),
(144681, 'itIT', 'In tal caso, spero tu sia in grado di gestire più cose alla volta.', '', 28153),
(144680, 'itIT', 'Non posso accettare altri lavori al momento, sono troppo indietro con il resto. Le pergamene non si scrivono da sole.', '', 28153),
(144679, 'itIT', 'Sono in rosso.', '', 28153),
(144678, 'itIT', '', '<Arluelle fissa l\'orizzonte con sguardo vago.>$B$BSe solo mio fratello potesse vedere la città ora...', 28153),
(144677, 'itIT', '', 'Ho il presentimento che presto toccherà alla nostra città. Sarà meglio prepararsi prima che arrivi il momento.', 28153),
(144676, 'itIT', 'È un peccato che i Forgialuce non si siano uniti a noi, le loro abilità in combattimento sono formidabili.', '', 28153),
(144675, 'itIT', 'A che numero ero? Dannazione!', '', 28153),
(144674, 'itIT', 'La Guardia del Vespro sarà felice di avere Victoire di nuovo tra i suoi ranghi.', '', 28153),
(144673, 'itIT', '', 'Continuiamo, forza.', 28153),
(144672, 'itIT', 'Sono felice di vedere che Arluelle sta continuando l\'addestramento; sembra già più forte!$B$BForse dovrei mettere alla prova i suoi miglioramenti.', '', 28153),
(144671, 'itIT', 'Le maree mutano, fratello. Se non vuoi unirti a noi, allora sei condannato.', 'Le maree mutano, fratello. Se non vuoi unirti a noi, allora sei condannato.', 28153),
(144670, 'itIT', 'Uno per te. Uno per me.', '', 28153),
(144669, 'itIT', 'Cucinare libri è delizioso!', '', 28153),
(144668, 'itIT', 'Reid! La flotta deve tornare immediatamente a Kul Tiras!', '', 28153),
(144667, 'itIT', 'Ma questo mucchio l\'ho già contato?', '', 28153),
(144666, 'itIT', 'Uno... Due... Sette... Rosso... Due...', '', 28153),
(144665, 'itIT', '', 'In caso non ti fosse chiaro, sono piuttosto brava a far saltare in aria le cose... e indovina chi sta scalando la mia lista di obiettivi?', 28153),
(144664, 'itIT', '', 'Continua così e potrebbe capitarti un piccolissimo incidente.', 28153),
(144663, 'itIT', '', 'Uh! Questo ti costerà caro!', 28153),
(144662, 'itIT', '', 'A più tardi.', 28153),
(144661, 'itIT', '', 'Uh? Tutto qui?', 28153),
(144660, 'itIT', '', 'Ci vediamo!', 28153),
(144659, 'itIT', '', 'Di cosa hai bisogno?', 28153),
(144658, 'itIT', '', 'Si va?', 28153),
(144657, 'itIT', '', 'Ehilà, come butta?', 28153),
(144656, 'itIT', 'Allora è QUESTA la mia vita ora. Fantastico. Davvero fantastico.', '', 28153),
(144655, 'itIT', 'Dico, vuoi proprio continuare così? Seriamente? Sempre con questo solito pat pat pat...', '', 28153),
(144654, 'itIT', 'Non hai niente di meglio da fare? Tipo... baciare un Murloc o qualcosa del genere?', '', 28153),
(144653, 'itIT', 'Oh, andiamo! Mi merito ben più rispetto!', '', 28153),
(144652, 'itIT', 'Sì, sì, come ti pare...', '', 28153),
(144651, 'itIT', 'Va bene, aria...', '', 28153),
(144650, 'itIT', 'A più tardi!', '', 28153),
(144649, 'itIT', 'Carico e pronto a colpire!', '', 28153),
(144648, 'itIT', 'Pronto a partire!', '', 28153),
(144647, 'itIT', 'Se continui a cliccare in quel modo, perderai un dito.', '', 28153),
(144646, 'itIT', 'Era una giornata così bella prima del tuo arrivo.', '', 28153),
(144645, 'itIT', 'Ciao, sono Asdrubal, ma tu puoi chiamarmi \"signore\".', '', 28153),
(144644, 'itIT', 'Le stragi sono sottovalutate.', '', 28153),
(144643, 'itIT', 'Adoro i piani ben riusciti.', '', 28153),
(144642, 'itIT', 'A più tardi.', '', 28153),
(144641, 'itIT', 'Qual è il piano?', '', 28153),
(144640, 'itIT', 'Quali sono gli ordini?', '', 28153),
(144639, 'itIT', 'Ehilà!', '', 28153),
(144638, 'itIT', 'Quindi è chesto che fai. Infastidisci la gente.', '', 28153),
(144637, 'itIT', 'Vuoi sapere da dove vengono chesti teschi?', '', 28153),
(144636, 'itIT', 'Sfortunatamente, la tribù Lanciarosa esisteva già...', '', 28153),
(144635, 'itIT', 'Ho perso la capa mia! Vedi se la trovi in giro... me l\'avevi fatta grossa così.', '', 28153),
(144634, 'itIT', 'Torna accà se ti serve l\'aiuto mio.', '', 28153),
(144633, 'itIT', 'Nun ti immischiare col vudù.', '', 28153),
(144632, 'itIT', 'Guardati le spalle.', '', 28153),
(144631, 'itIT', 'Che c\'è, capo?', '', 28153),
(144630, 'itIT', 'Per i Lanciascura!', '', 28153),
(144629, 'itIT', 'Sto ascoltando.', '', 28153),
(144628, 'itIT', 'Molto bene. Avete selezionato il protocollo di rioriginazione dell\'universo. Procedere?', '', 28153),
(144627, 'itIT', 'Un continuo disturbo non velocizzerà le operazioni di sistema.', '', 28153),
(144626, 'itIT', 'Potenziale nuovo obiettivo per il contenimento.', '', 28153),
(144625, 'itIT', 'Errore. Si prega di non riprovare.', '', 28153),
(144624, 'itIT', 'Interazione terminata.', '', 28153),
(144623, 'itIT', 'Ripresa protocollo di contenimento.', '', 28153),
(144622, 'itIT', 'Riavvio scansioni.', '', 28153),
(144621, 'itIT', '', 'Salve, $p! Nuove terre e alleati ci attendono su Azeroth.$B$BQuando ti sentirai $gpronto:pronta;, puoi prendere i portali che Oculeth ha preparato al piano di sotto.', 28153),
(144620, 'itIT', 'Corruzione individuata. Contenere a tutti i costi.', '', 28153),
(144619, 'itIT', 'Protocollo ad alta priorità: contenere la corruzione.', '', 28153),
(144618, 'itIT', 'Unità Hezrel attiva. Obiettivo: contenimento corruzione.', '', 28153),
(144617, 'itIT', '', 'Il tuo comportamento inizia a stancarmi... più di quanto non abbia già fatto!', 28153),
(144616, 'itIT', '', 'Hai mai sentito la storia della Tortolliana che perse il senno e attaccò chi la infastidiva?', 28153),
(144614, 'itIT', '', 'Mi stai facendo arrabbiare.', 28153),
(144613, 'itIT', '', 'Abbiamo finito?', 28153),
(144612, 'itIT', '', 'Vedi di infastidire qualcun altro.', 28153),
(144611, 'itIT', '', 'Ce ne hai messo di tempo!', 28153),
(144610, 'itIT', '', 'Uh. Cosa c\'è?', 28153),
(144609, 'itIT', '', 'Devi parlare proprio con me?', 28153),
(144608, 'itIT', '', 'Che cosa vuoi?', 28153),
(144605, 'itIT', 'Vattene, prima che usi la tua anima per ripagare il debito mio!', '', 28153),
(144604, 'itIT', 'Ti do nu consiglio: MAI fare nu patto con nu Loa della Morte!', '', 28153),
(144603, 'itIT', 'Tieni stretta l\'anima tua.', '', 28153),
(144602, 'itIT', 'Resta all\'erta.', '', 28153),
(144601, 'itIT', 'Statt\' accuort\'.', '', 28153),
(144600, 'itIT', 'Salve.', '', 28153),
(144599, 'itIT', 'Cosa vuoi da Hanzabu?', '', 28153),
(144598, 'itIT', 'Tengo assai da fare.', '', 28153),
(144597, 'itIT', 'Perché non vai a farti un girino?', '', 28153),
(144596, 'itIT', 'Smettila, o ti faccio saltare.', '', 28153),
(144595, 'itIT', 'Sto per suonarti come una raganella!', '', 28153),
(144594, 'itIT', 'Non sei qui per darmi un bacio, vero?', '', 28153),
(144593, 'itIT', 'Alla prossima.', '', 28153),
(144592, 'itIT', 'Fai attenzione a dove salti.', '', 28153),
(144591, 'itIT', 'Che tu possa prendere insetti freschi.', '', 28153),
(144590, 'itIT', 'Parla.', '', 28153),
(144589, 'itIT', 'Vuoi parlare con Krag\'wa?', '', 28153),
(144588, 'itIT', 'Sì, piccolo essere?', '', 28153),
(144587, 'itIT', 'Ci vediamo presto... MOLTO presto.', '', 28153),
(144586, 'itIT', 'Sciò! Vattene!', '', 28153),
(144585, 'itIT', 'Prima o poi... tutti arrivano da me.', '', 28153),
(144584, 'itIT', 'Mi dai l\'idea di tener sete. Vuoi qualcosa? Che ne dici di nu \"zombi\"? Ahahah!', '', 28153),
(144583, 'itIT', 'Vedo la gente morta. È la passione mia, sai?', '', 28153),
(144582, 'itIT', 'Mmm... a qualcuno piace fare giochi pericolosi.', '', 28153),
(144581, 'itIT', 'Ué! Nun ti scordare con chi hai a che fare.', '', 28153),
(144580, 'itIT', 'Salve, salve! Stai accà per nu patto?', '', 28153),
(144579, 'itIT', 'Che cosa chiedi alla morte?', '', 28153),
(144578, 'itIT', 'Allora... Che cosa ti porta a far visita al vecchio Bwonsamdi?', '', 28153),
(144577, 'itIT', 'Sono pronto.', 'Sono pronta.', 28153),
(144576, 'itIT', 'Dobbiamo fermare questa follia prima che sia troppo tardi.', '', 28153),
(144575, 'itIT', '', 'Lo terrò d\'occhio, così non si perderà di nuovo.', 28153),
(144574, 'itIT', 'Proprio da sotto il nostro naso! Che nervoso!', '', 28153),
(144573, 'itIT', 'No, no, non è possibile. Secondo i miei calcoli dovrebbe essere...', '', 28153),
(144572, 'itIT', 'Questi risultati sono strani. Se questi piccoli... Com\'è che si chiamano? Barbosetti... mi lasciassero concentrare!', '', 28153),
(144571, 'itIT', 'Devo riprovarci. Hai agito bene, anche se mi è parso che i nostri nemici fossero più alti.', '', 28153),
(144570, 'itIT', 'Sono certo che saprai fronteggiare qualsiasi interruzione, vero?', '', 28153),
(144569, 'itIT', 'Da questa parte! Una volta iniziata la divinazione, dovrò dedicarle tutta la mia attenzione.', '', 28153),
(144567, 'itIT', '', 'Nuu è qui per aiutarci. Sapevo che ci avresti trovati, Nuu.', 28153),
(144566, 'itIT', 'Ci sono gravi danni strutturali ed energia instabile in questi acquedotti. Il cancello rimarrà chiuso per il momento.', 'Ci sono gravi danni strutturali ed energia instabile in questi acquedotti. Il cancello rimarrà chiuso per il momento.', 28153),
(144565, 'itIT', 'Continuerò a tenerlo d\'occhio, ma sembra abbastanza a suo agio da vagare per i giardini.', 'Continuerò a tenerlo d\'occhio, ma sembra abbastanza a suo agio da vagare per i giardini.', 28153),
(144564, 'itIT', '', 'Molto bene! Sono impressionata!', 28153),
(144563, 'itIT', '', 'Convogliare il chi verso un bersaglio può essere difficile, all\'inizio.\n\nTu, in prima fila! Cerca di colpire quel manichino laggiù.', 28153),
(144562, 'itIT', 'Psst, $PR... vuoi comprare qualche cosa?', '', 28153),
(144561, 'itIT', 'Che cos\'hai, $p? Si tratta di un Bocciolo Secolare?', '', 28153),
(144560, 'itIT', '', 'Dobbiamo prepararci alla prossima stagione di semina, Jahden.', 28153),
(144559, 'itIT', 'Mmm... a chesto chili manca qualcosa... deve stare più piccante.', '', 28153),
(144558, 'itIT', '', 'Zancha! Ti sei dimenticato nuovamente di riempire il bidone delle Pietre del Ritorno?', 28153),
(144557, 'itIT', 'Addiiiooo!', '', 28153),
(144556, 'itIT', 'Buona nuotata.', '', 28153),
(144555, 'itIT', 'L\'acqua è così bella. Mi piace l\'acqua. A te piace? Cosa ti piace di più dell\'acqua? Io adoro il fatto che è bagnata. L\'acqua è fantastica, vero?', '', 28153),
(144554, 'itIT', 'La mia mamma dice che siamo anfo... ambi... ah... uhm... ANFIBI! Ecco come si diceva!', '', 28153),
(144553, 'itIT', 'Porta in alto la mano, sono il tuo Tortolliano, ruota un po\' il tuo guscino, mi fa male già il pancino.', '', 28153),
(144552, 'itIT', 'Quando sarò grande, voglio leggere tutto!', '', 28153),
(144551, 'itIT', 'Come fai a portare la tua roba senza un guscio?', '', 28153),
(144550, 'itIT', 'Mi piace rotolarmi!', '', 28153),
(144549, 'itIT', 'Ben presto sarò vecchio quanto te!', '', 28153),
(144548, 'itIT', 'Va bene, vai pure. Non avevo comunque altro da dirti.', '', 28153),
(144547, 'itIT', 'Non tutto ciò che si trova nell\'oceano è bello ed educato quanto me.', '', 28153),
(144546, 'itIT', 'Se dovessi trovare qualcosa di esotico, portamelo!', '', 28153),
(144545, 'itIT', 'Torna con delle storie migliori.', '', 28153),
(144544, 'itIT', 'Ho visto cose che ti farebbero rimpiangere di non avere il guscio.', '', 28153),
(144543, 'itIT', 'Avvicinati e non borbottare.', '', 28153),
(144542, 'itIT', 'Salute, signore... o signora.', '', 28153),
(144541, 'itIT', 'Hai qualche cosa di antico da commerciare? Deve avere almeno un paio di secoli.', '', 28153),
(144540, 'itIT', '', 'Che, ti stai allontanando da me?!?', 28153),
(144539, 'itIT', '', 'Ciao, ciao.', 28153),
(144538, 'itIT', '', 'Na volta, ho rubato n\'alpaca e l\'ho portato al tempio. Ma poi la ma\'ma mia me l\'ha fatto liberare.', 28153),
(144537, 'itIT', '', 'Na volta, ho sconfitto n\'avventuriero e ho pigliato il teschio suo. Era più grande del tuo...', 28153),
(144536, 'itIT', '', 'Na volta ho pigliato nu brutosauro per la coda. Mi ha trascinato per trentadue respiri e mezzo.', 28153),
(144535, 'itIT', '<Un Albatros Malvagio si getta in picchiata verso l\'uovo in schiusura.>', '', 28153),
(144534, 'itIT', '', 'Na volta ho pigliato nu sauride. Era grosso assai, assai, assai, assai, assai. Mi hanno detto che era nu devasauro, ma credo stessero scherzando.', 28153),
(144533, 'itIT', '', 'Na volta ho catturato il più grosso pesce mai visto. Poi però ho scoperto che era na guardia maledetta.', 28153),
(144532, 'itIT', '', 'Taz\'okun!', 28153),
(144531, 'itIT', '', 'Taz\'dingo!', 28153),
(144530, 'itIT', '', 'Il Loa mio batterebbe sicuramente il tuo!', 28153),
(144529, 'itIT', '', 'Nu giorno diventerò na Loa!', 28153),
(144528, 'itIT', 'Ciao ciao, cumpà.', '', 28153),
(144527, 'itIT', 'Dove te ne vai?', '', 28153),
(144526, 'itIT', 'I Loa sono così affascinanti. Molti di loro sono così grossi che potrebbero mangiarti!', '', 28153),
(144525, 'itIT', 'Da grande sarò nu Druido brutosauro! Roar!', '', 28153),
(144524, 'itIT', 'Io tengo dieci pollici, ma solo quattro sono miei.', '', 28153),
(144523, 'itIT', 'Qualcuno ha rubato le cape rimpicciolite mie. Ne sai qualcosa?', '', 28153),
(144522, 'itIT', 'Oh, salve.', '', 28153),
(144521, 'itIT', 'Taz\'okun!', '', 28153),
(144520, 'itIT', 'Taz\'dingo!', '', 28153),
(144519, 'itIT', 'Roar!', '', 28153),
(144518, 'itIT', 'I Loa sono potenti accà.', 'I Loa sono potenti accà.', 28153),
(144517, 'itIT', 'Che li spiriti stiano con te.', 'Che gli spiriti stiano con te.', 28153),
(144516, 'itIT', 'I Loa ci osservano sempre.', 'I Loa ci osservano sempre.', 28153),
(144515, 'itIT', 'Bah! Prendi due di cheste e rivediamoci domani mattina.', 'Bah! Piglia due di cheste e rivediamoci domani mattina.', 28153),
(144513, 'itIT', 'Stai sfidando il destino facendo così.', 'Stai sfidando il destino facendo così.', 28153),
(144512, 'itIT', 'Accà puoi trovare solo i mojo migliori.', 'Accà puoi trovare solo i mojo migliori.', 28153),
(144511, 'itIT', 'Li spiriti sussurrano il nome tuo.', 'Gli spiriti sussurrano il nome tuo.', 28153),
(144510, 'itIT', 'Con quale Loa tieni nu patto tu?', 'Con quale Loa tieni nu patto tu?', 28153),
(144509, 'itIT', '', 'Per il futuro di Zandalar! Avanti!', 28153),
(144508, 'itIT', 'Una presentazione davvero imbarazzante... Sarà meglio tornare indietro presto, o Kugro non sarà felice.', '', 28153),
(144498, 'itIT', 'Zandalar resisterà.', 'Zandalar resisterà.', 28153),
(144497, 'itIT', 'Mai tremare di fronte ai deboli.', '', 28153),
(144496, 'itIT', 'Che le ferite dei tuoi nemici siano profonde.', '', 28153),
(144495, 'itIT', 'Che tu possa assaporare la carne dei nemici.', '', 28153),
(144494, 'itIT', 'Che c\'è, membro dell\'Orda?', '', 28153),
(144493, 'itIT', 'Cammini nelle mie terre.', '', 28153),
(144492, 'itIT', 'Sei un predatore... o una preda?', '', 28153),
(144491, 'itIT', 'Sei qui per stringere un patto?', '', 28153),
(144490, 'itIT', 'Racconta agli altri di me.', '', 28153),
(144489, 'itIT', 'Che i tuoi nemici non ti sentano mai arrivare.', '', 28153),
(144488, 'itIT', 'Porta forza al tuo branco.', '', 28153),
(144486, 'itIT', 'Se intendi scappare, ricorda... posso aprire le porte.', '', 28153),
(144484, 'itIT', 'Continua così, e diventerai la mia prossima preda.', '', 28153),
(144481, 'itIT', 'Sono il Signore delle Forme, il Capobranco e il Signore della Caccia.', '', 28153),
(144480, 'itIT', 'Cosa ti porta al cospetto del Signore della Caccia?', '', 28153),
(144479, 'itIT', 'Sei qui per stringere un patto?', '', 28153),
(144478, 'itIT', '', 'Che il vento sia sempre alle tue spalle... e che ti spinga lontano da me.', 28153),
(144477, 'itIT', '', 'Ricorda, i cieli sono miei.', 28153),
(144476, 'itIT', '', 'Che tu possa far piovere morte dall\'alto.', 28153),
(144475, 'itIT', '', 'Il vento è il mio volere. ', 28153),
(144474, 'itIT', '', 'Ti porterò in cielo con me... e ti farò cadere su una roccia!', 28153),
(144473, 'itIT', '', 'Stai invocando la mia ira?', 28153),
(144472, 'itIT', '', 'Stai mettendo alla prova la mia pazienza, giovane.', 28153),
(144471, 'itIT', '', 'Perché devo respirare la tua aria?', 28153),
(144470, 'itIT', '', 'Che c\'è?', 28153),
(144469, 'itIT', '', 'Sei qui per stringere un patto?', 28153),
(144468, 'itIT', '', 'Psst, $PR... Ti sei $gstufato:stufata; di sembrare nu sauride? Il mojo mio ti farà sembrare nu gigantosauro!', 28153),
(144462, 'itIT', '', 'Scegli il tuo Loa con attenzione.', 28153),
(144461, 'itIT', '', 'Che tu possa sempre trovare le tracce dei nemici tuoi.', 28153),
(144460, 'itIT', '', 'Per il branco.', 28153),
(144459, 'itIT', '', 'Non ammansire mai la bestia dentro di te.', 28153),
(144458, 'itIT', '', 'Abbraccia il tuo lato selvaggio.', 28153),
(144457, 'itIT', '', 'Resta nei paraggi. Potrei avere bisogno di te più tardi.', 28153),
(144456, 'itIT', '', 'E mo\' basta, però...', 28153),
(144455, 'itIT', '', 'Vabbuo\', Continua pure.', 28153),
(144454, 'itIT', '', 'Se continui a fare così, il marito mio si ingelosirà.', 28153),
(144453, 'itIT', '', 'Nun hai mai abbracciato il tuo lato selvaggio?', 28153),
(144452, 'itIT', 'Mi toccherà occuparmene di persona. Non ti lascerò rovinare tutta l\'operazione!', '', 28153),
(144451, 'itIT', 'Grazie, $n. Pare che Kugro sia stato occupato. Ora... che ne facciamo di tutte queste pergamene?', '', 28153),
(144450, 'itIT', '', 'La forza dei Loa è grande accà.', 28153),
(144449, 'itIT', '', 'È davvero chesta la forma con cui hai deciso di andare in giro?', 28153),
(144448, 'itIT', 'Tu non sei il mio contatto! Venite, gente, c\'è carne fresca!', '', 28153),
(144447, 'itIT', '', 'Io servo Gonk, il Signore delle Forme.', 28153),
(144446, 'itIT', '<Dai a Itokka le pergamene.>', '<Dai a Itokka le pergamene.>', 28153),
(144445, 'itIT', '', 'Quanto vorrei che Nuu fosse qui. Lui saprebbe cosa fare.', 28153),
(144444, 'itIT', '', 'Oh, ciao! Chi sei? Io sono Uuna. Vuoi essere $gmio amico:mia amica;? Forse insieme riusciremo a uscire da questo posto.', 28153),
(144443, 'itIT', 'Ehi! Tengo proprio ciò di cui tieni bisogno tu. La Protezione Sauride di Zul! Tieni lontane chelle pesti fetenti!', '', 28153),
(144442, 'itIT', '', 'È troppo luminosa! Troppo! Arghhh!', 28153),
(144441, 'itIT', 'Hai la mia benedizione, viandante.\n\nRiponi le armi e recupera le forze.\n\nLa guerra può attendere.', '', 28153),
(144440, 'itIT', 'Salve, Pakura\'ai!', '', 28153),
(144439, 'itIT', 'Scegli il Loa tuo con attenzione.', '', 28153),
(144438, 'itIT', 'Come mi dice sempre il Loa mio: vattene.', '', 28153),
(144437, 'itIT', 'Che Pa\'ku spii i nemici tuoi prima che loro possano spiare te.', '', 28153),
(144436, 'itIT', 'Che i venti della guerra soffino sempre in favore tuo.', '', 28153),
(144435, 'itIT', 'Perfetto! Hai toccato il punto giusto!', '', 28153),
(144434, 'itIT', 'Oh sì, continua così... solo nu poco più a destra...', '', 28153),
(144433, 'itIT', 'Sarei felice se la moglie mia mi desse tutte cheste attenzioni.', '', 28153),
(144432, 'itIT', 'Come mi diceva sempre il Loa mio: nun mi toccare!', '', 28153),
(144431, 'itIT', 'Come mi dice sempre il Loa mio: stai ancora accà?', '', 28153),
(144430, 'itIT', 'Vuoi stare con i sauri?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144429, 'itIT', 'I cieli sono gli occhi miei.', '', 28153),
(144428, 'itIT', 'Io servo Pa\'ku, uno dei Loa più antichi.', '', 28153),
(144427, 'itIT', '', 'Combatto per proteggere coloro che nun possono farlo.', 28153),
(144425, 'itIT', 'Tutti teniamo nu ruolo da recitare, pure tu.', '', 28153),
(144424, 'itIT', 'Ho seguito i grandi eventi del tempo nostro, e tu eri presente a tutti quanti. Curioso.', '', 28153),
(144423, 'itIT', 'Giorni oscuri ci aspettano.', '', 28153),
(144422, 'itIT', 'Si metterà male. Molto male.', '', 28153),
(144421, 'itIT', 'L\'Impero dei Troll risorgerà. L\'ho predetto.', '', 28153),
(144420, 'itIT', 'I Troll sono stati i primi a governare chesto mondo, e saranno gli ultimi.', '', 28153),
(144419, 'itIT', 'Ahimè, il fato nun sta dalla tua parte.', '', 28153),
(144418, 'itIT', 'Ho già previsto ciò che dirai, per cui ti chiedo di fare in fretta.', '', 28153),
(144417, 'itIT', 'Ho visto come finirà chesto mondo, e a te nun piacerà.', '', 28153),
(144416, 'itIT', '', 'Zandalar resisterà.', 28153),
(144415, 'itIT', '', 'Vendetta per i caduti.', 28153),
(144414, 'itIT', '', 'Che i teschi dei nemici adornino le vesti tue.', 28153),
(144413, 'itIT', '', 'I tempi cambiano, e li Zandalari pure.', 28153),
(144412, 'itIT', '', 'Ci sta molto da fare. Parla in fretta.', 28153),
(144411, 'itIT', 'Che i nemici tuoi tremino dinanzi a te.', '', 28153),
(144410, 'itIT', 'Zandalar per sempre.', '', 28153),
(144409, 'itIT', 'Che Rezan ti dia la forza.', '', 28153),
(144408, 'itIT', 'Ahahah! È bello essere il Re.', '', 28153),
(144407, 'itIT', 'Stai di fronte a Re Rastakhan.', '', 28153),
(144406, 'itIT', 'È nu piacere averti a Zuldazar.', '', 28153),
(144405, 'itIT', 'Sei nu predatore... o na preda?', '', 28153),
(144404, 'itIT', '', 'Vorrei poter vedere meglio, è sempre così buio qui!', 28153),
(144403, 'itIT', '', 'Ma tu sei $gmio amico:mia amica; e so che andrà tutto bene.', 28153),
(144402, 'itIT', '', 'Ora almeno siamo insieme. Semplicemente... non sappiamo dove ci troviamo.', 28153),
(144401, 'itIT', '', 'Aiuto! AIUTO!', 28153),
(144400, 'itIT', '', 'Chi sei? Puoi aiutarmi?', 28153),
(144399, 'itIT', '', 'È così buio! Non riesco a vedere!', 28153),
(144397, 'itIT', '', 'Il problema Elisande è risolto, ma c\'è ancora molto da fare per questa città.', 28153),
(144396, 'itIT', '', 'I Nobili Oscuri sono finalmente liberi e non hanno più bisogno del Pozzo Oscuro e del suo potere.$b$bPossiamo forgiare il nostro destino.', 28153),
(144395, 'itIT', 'Ho portato degli assaggi per far tacere le voci infondate sul nostro vino troppo muschiato... volevo dire, fruttato!', '', 28153),
(144394, 'itIT', 'Alcuni dei nostri viticoltori hanno rinunciato alla cura dei loro vigneti e ora si occupano di altre forme di botanica.', '', 28153),
(144393, 'itIT', 'Sì, i Troll del Sangue stavano combattendo con le guardie quando siamo arrivati. Nun si aspettavano n\'attacco alle spalle.', '', 28153),
(144392, 'itIT', 'Accidenti, quello è grosso. Mi servirà il tuo aiuto per abbatterlo!', '', 28153),
(144391, 'itIT', 'Se li vedi, lancia una di quelle Bombe di Spine e fagli assaggiare un po\' della loro medicina!', '', 28153),
(144390, 'itIT', 'Scommetto che fa male, vero? Vattene dalla mia terra!', '', 28153),
(144389, 'itIT', 'Ahahah, dritto in mezzo agli occhi!', '', 28153),
(144388, 'itIT', 'Puoi tornare indietro e dire a Roz che sto bene, ma non lascerò mai la mia fattoria. Mai.', '', 28153),
(144387, 'itIT', 'Sì, andrà bene. Hanno sempre amato questo posto.', '', 28153),
(144386, 'itIT', 'Puoi usare il portale a Orgrimmar per incontrare i nostri alleati dell\'Orda nella loro capitale a Kalimdor.', '', 28153),
(144385, 'itIT', '', 'Rokhan! Stai bene? Pare che ci sia stata na battaglia accà.', 28153),
(144384, 'itIT', 'Ho sentito che a Dalaran c\'è un intero piano dedicato al trasporto magico.$B$BImmagina quante possibilità!', '', 28153),
(144383, 'itIT', 'Questi portali sono incredibilmente tediosi da mantenere, ma soprattutto distolgono l\'attenzione da ricerche più importanti.$B$BSono certo che con la telemanzia potremmo ottenere una soluzione più efficiente.', '', 28153),
(144382, 'itIT', 'Chi dice che i Goblin non hanno cultura?', '', 28153),
(144381, 'itIT', 'Ne hanno uno anche ai tamburi!', '', 28153),
(144380, 'itIT', '...e certa nu tamburo libero!', '', 28153),
(144379, 'itIT', '$gBenvenuto:Benvenuta; al Tamburino Ubriaco, $PR! Piglia qualcosa da bere...', '', 28153),
(144378, 'itIT', 'Argh! Credevo che il piano mio fosse perfetto, cumpà!', '', 28153),
(144377, 'itIT', '$gStupido:Stupida;! Pagherai per essere $gpassato:passata; sotto il ponte mio!', '', 28153),
(144376, 'itIT', 'Ehi cumpà! Stai attraversando il ponte mio, cumpà. Paga il pizzo, o pagherai col sangue tuo, cumpà!', '', 28153),
(144375, 'itIT', 'Sono pronto a iniziare la prova.', 'Sono pronta a iniziare la prova.', 28153),
(144374, 'itIT', '', 'Che ne dici se ci legassimo attorno dell\'esplosivo? Pensa che roba... dinosauri esplosivi!', 28153),
(144373, 'itIT', '', 'Apprezzo il tuo entusiasmo, Shuga. Resto però convinta che gli Zandalari preferiscano che le loro armi vengano incantate da potenti magie invece di essere ricoperte da una viscida poltiglia.', 28153),
(144372, 'itIT', 'Cosa... cosa siamo diventati?', '', 28153),
(144371, 'itIT', '', 'No! Lasciami stare! Aiuto! $gAmico:Amica;! Aiuto!!!', 28153),
(144370, 'itIT', '', 'È di nuovo buio! Dove sei $gfinito:finita;? Non lasciarmi!', 28153),
(144369, 'itIT', '', 'Anch\'io avevo una bacchetta come quella! L\'ho persa molto tempo fa.', 28153),
(144368, 'itIT', '', 'Una corona! Che bella!', 28153),
(144367, 'itIT', '', 'Nuu-Nuu! Temevo che non ti avrei più rivisto! Come sei finito qui?', 28153),
(144366, 'itIT', '', 'Una luce! Riesco quasi... a vederci.', 28153),
(144365, 'itIT', '', 'Cos\'è quello? Vedo una luce nell\'oscurità! È così luminosa...', 28153),
(144364, 'itIT', 'Aveva... promesso...', '', 28153),
(144363, 'itIT', 'Dicevano che avremmo potuto stare insieme così!', '', 28153),
(144362, 'itIT', '', 'Con il Loa al fianco nostro e le forze unite, oggi otterremo la vittoria!', 28153),
(144361, 'itIT', '', 'Colpiremo i Troll del Sangue. Ci assicureremo che l\'abominio che stanno evocando nun venga mai usato contro di noi!', 28153),
(144360, 'itIT', '', 'I nemici vogliono distruggere le case nostre e tutto ciò che ci sta a cuore. Nun possiamo permettere che il piano loro vada in porto! Oggi, tutto quanto dipende da noi!', 28153),
(144359, 'itIT', '', 'Soldati... amici. Abbiamo passato tempi durissimi, ma mo\' la fine delle nostre sofferenze è vicina.', 28153),
(144358, 'itIT', 'Mostrami dove puoi portarmi.', 'Mostrami dove puoi portarmi.', 28153),
(144357, 'itIT', 'Cerchi un passaggio?', 'Cerchi un passaggio?', 28153),
(144356, 'itIT', '', 'Per fortuna mi sono messa i miei stivali!', 28153),
(144355, 'itIT', 'Porterò con me qualche Tortolliano e ci muoveremo verso Zul\'jan. Buona fortuna.', '', 28153),
(144354, 'itIT', 'Vivo e muoio... per l\'Orda!', 'Vivo e muoio... per l\'Orda!', 28153),
(144353, 'itIT', 'Sangue e onore!', 'Sangue e onore!', 28153),
(144352, 'itIT', 'Arathi appartiene all\'Orda!', 'Arathi appartiene all\'Orda!', 28153),
(144351, 'itIT', 'Con me!', 'Con me!', 28153),
(144350, 'itIT', 'Morte all\'Alleanza!', 'Morte all\'Alleanza!', 28153),
(144349, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(144348, 'itIT', 'Da questa parte! Alla battaglia!', 'Da questa parte! Alla battaglia!', 28153),
(144347, 'itIT', 'Andiamo, Grunt! Abbiamo una guerra da vincere!', 'Andiamo, Grunt! Abbiamo una guerra da vincere!', 28153),
(144346, 'itIT', 'Io sono Gral!', '', 28153),
(144345, 'itIT', 'A sud troverai ciò che resta del mio tempio. Ti attenderò lì e insieme mostreremo a questi Naga la furia del Loa Squalo!', '', 28153),
(144344, 'itIT', 'Oh... che delizia.', '', 28153),
(144343, 'itIT', 'Non ci sono oscurità profonde abbastanza per te!', '', 28153),
(144342, 'itIT', 'I Naga non sono i benvenuti ad Atal\'gral!', '', 28153),
(144341, 'itIT', 'Il delizioso odore del sangue rabbioso dei Naga... piccoli dolci bocconcini... attenderò per questo.', '', 28153),
(144340, 'itIT', '', 'Mamma, Benjamin mi ha detto tutto.\n\nPrima non riuscivi a sentirmi, ora ci riesci? Volevo solo una spiegazione.', 28153),
(144339, 'itIT', '', 'Mamma, so che non sei lì. Ma se riesci a sentirmi...', 28153),
(144338, 'itIT', 'Non sarò il gestore più abile, ma mia madre era incredibile. Vederla cadere così in basso...$b$bCe la caveremo, $n. Grazie per l\'aiuto.', '', 28153),
(144337, 'itIT', '', 'Dove stai andando?', 28153),
(144336, 'itIT', '', 'Per favore, non lasciarmi.', 28153),
(144335, 'itIT', 'La nostra padrona sotto le maree ci guiderà alla vittoria!', 'La nostra padrona sotto le maree ci guiderà alla vittoria!', 28153),
(144334, 'itIT', 'È bello vedere che siete tutti interi, ed è tutto merito di... ehi, ecco l\'eroina del momento!', '', 28153),
(144333, 'itIT', 'Resti o te ne vai?', '', 28153),
(144332, 'itIT', 'Perdonami, devo andare a cercare mia sorella.', '', 28153),
(144331, 'itIT', 'Quando papà è morto, mia madre è scomparsa. Ma non avrei mai pensato...', '', 28153),
(144330, 'itIT', 'Lei e mio padre hanno lavorato tutta la vita per portare avanti l\'attività e crescere me e mia sorella.', '', 28153),
(144329, 'itIT', 'Quella strega... era mia madre.', '', 28153),
(144328, 'itIT', 'Sembra che tu sia a tuo agio attorno alle bestie. Di cosa hai bisogno?', '', 28153),
(144327, 'itIT', 'Che c\'è ora? Hai perso qualcosa?', '', 28153),
(144326, 'itIT', 'Eccellente! Ancora una volta, dall\'inizio.', '', 28153),
(144325, 'itIT', 'Usare troppe energie in una volta sola è pericoloso. Fate con calma, studenti.', '', 28153),
(144324, 'itIT', 'Il chi focalizzato è estremamente potente. Il Maestro Tau Li vi guiderà quando sarete pronti.', '', 28153),
(144323, 'itIT', 'Per guarire è necessario concentrare la vostra forza interiore e trasmetterla agli altri.', '', 28153),
(144322, 'itIT', 'Sono felice di non aver dovuto dare TUTTO.', 'Sono felice di non aver dovuto dare TUTTO.', 28153),
(144321, 'itIT', 'I nostri fratelli e sorelle corrotti vagano ancora nelle foreste.', 'I nostri fratelli e sorelle corrotti vagano ancora nelle foreste.', 28153),
(144320, 'itIT', '', 'La mia vita... per l\'Orda.', 28153),
(144319, 'itIT', '', 'Ci vediamo presto, amico mio.', 28153),
(144318, 'itIT', '', 'Sangue e tuono!', 28153),
(144317, 'itIT', '', 'Ti farò a fettine.', 28153),
(144316, 'itIT', '', 'La mia spada brama il tuo sangue.', 28153),
(144315, 'itIT', '', 'La tua forza non è nulla in confronto a quella di un Orco!', 28153),
(144314, 'itIT', '', 'Le tue ossa non hanno speranza contro la mia lama!', 28153),
(144313, 'itIT', '', 'Mantenete la posizione! Non deve passare niente!', 28153),
(144312, 'itIT', 'Grazie, $gamico:amica;.', '', 28153),
(144311, 'itIT', 'Se non ti riconoscerò la prossima volta che ci incontreremo, me ne dispiace.', '', 28153),
(144310, 'itIT', 'Grazie per esserti $goccupato:occupata; di Torok. Si rifiutava di vedere i pericoli del potere che bramava.', 'Grazie per esserti $goccupato:occupata; di Torok. Si rifiutava di vedere i pericoli del potere che bramava.', 28153),
(144309, 'itIT', '<Il Tauren addormentato russa sonoramente e si gira di lato.>', '<La Tauren addormentata russa sonoramente e si gira di lato.>', 28153),
(144308, 'itIT', 'Zzz zzz...', 'Zzz zzz...', 28153),
(144307, 'itIT', 'Certo, principessa. Fino alla fine.', '', 28153),
(144306, 'itIT', '', 'Chesta è l\'unica via per salvare la gente mia, Rokhan. Darei qualunque cosa per la salvezza loro. Sei con me?', 28153),
(144305, 'itIT', 'Ancora non riesco a credere che i miei fratelli siano caduti vittime della magia vile.', 'Ancora non riesco a credere che i miei fratelli e sorelle siano caduti vittime della magia vile.', 28153),
(144304, 'itIT', '', 'Figlie mie, è così che ci si occupa delli ospiti!', 28153),
(144303, 'itIT', '', 'Il sangue... mi vendicherà...', 28153),
(144302, 'itIT', '', 'Per le Madri della Guerra!', 28153),
(144301, 'itIT', 'Ora concentrate il vostro chi. Allontanate le energie da voi.', '', 28153),
(144300, 'itIT', '', 'L\'essenza tua ci servirà meglio na volta fuori!', 28153),
(144299, 'itIT', '', 'Sarà divertente prosciugarti.', 28153),
(144298, 'itIT', '', 'Il sangue tuo ci alimenterà!', 28153),
(144297, 'itIT', '', 'Piglierò il sangue tuo. Il resto può marcire!', 28153),
(144296, 'itIT', '', 'Il tuo sangue bagnerà la lama mia.', 28153),
(144295, 'itIT', 'Se ti servisse qualcosa, sai dove trovarmi!', '', 28153),
(144294, 'itIT', '', 'Sangue per i salmodianti!', 28153),
(144293, 'itIT', '', 'Farò delle briglie con la pellaccia tua!', 28153),
(144292, 'itIT', '', 'I cieli... mi chiamano.', 28153),
(144291, 'itIT', '', 'Un giorno perfetto per una battaglia.', 28153),
(144290, 'itIT', '', 'I crog mangeranno assai chesta notte!', 28153),
(144289, 'itIT', 'Tieni duro! Vado a vedere come sta Satao.', '', 28153),
(144288, 'itIT', 'NOTA - L\'Esperimento delle Melme\n\nL\'animazione delle melme ha avuto successo. Invece di dissolvere materia organica come carne o vegetali, possono sussistere unicamente col miele. La grande massa di rifiuti prodotta può essere fermentata all\'interno di barili, creando un idromele incredibilmente potente e delizioso.\n\nComunque, senza contenerle a dovere, le melme prima o poi cercano una via di fuga e consumano interi alveari. Tendono a diventare più aggressive e a diventare incontrollabili nel processo.\n\nNaturalmente, in risposta a questo, le api hanno assunto un atteggiamento più difensivo e ora è più difficile lavorarci. È ovvio che prima o poi dovrò pensare a una soluzione, perché non è facile sostituire le api.', '', 28153),
(144287, 'itIT', '', 'Pohkiza...', 28153),
(144286, 'itIT', '', 'Il Dio del Sangue... reclama... tutto...', 28153),
(144285, 'itIT', '', 'Ahahah!', 28153),
(144284, 'itIT', '', 'Zuldazar... cadrà...', 28153),
(144283, 'itIT', '', 'Gachaga!', 28153),
(144282, 'itIT', '', 'Le sorelle mie... mi vendicheranno...', 28153),
(144281, 'itIT', '', 'Il sangue mio... per... G\'huun!', 28153),
(144280, 'itIT', '', 'G\'huun!', 28153),
(144279, 'itIT', '<Tsunga grugnisce con affetto nella tua direzione.>', '', 28153),
(144278, 'itIT', 'Vengo dalle nebbie per avvertire la gente di Zandalar. La Kaja\'mite ha donato grande intelligenza ai gorilla. E con l\'intelligenza arriva la guerra.', '', 28153),
(144277, 'itIT', 'Pohkiza...', '', 28153),
(144276, 'itIT', 'Il Dio del Sangue... reclama... tutto...', '', 28153),
(144275, 'itIT', 'Hai... già perso, ahahah...', '', 28153),
(144274, 'itIT', 'Zuldazar... cadrà...', '', 28153),
(144273, 'itIT', 'Gachaga!', '', 28153),
(144272, 'itIT', 'La vita mia per... le ma\'ma!', '', 28153),
(144271, 'itIT', 'Il sangue mio... per... G\'huun!', '', 28153),
(144270, 'itIT', 'G\'huun!', '', 28153),
(144269, 'itIT', 'Bene, bene! Ancora una volta!', '', 28153),
(144268, 'itIT', 'Smettila di agitarti.', '', 28153),
(144266, 'itIT', '', 'Aiuterò a rinforzare le difese del villaggio. Ci vediamo lì!', 28153),
(144265, 'itIT', '', 'Li abbiamo sconfitti. Forza! Dobbiamo parlare con il Sindaco Royston.', 28153),
(144264, 'itIT', '', '<Alleria sospira inarcando le sopracciglia.>', 28153),
(144263, 'itIT', '<Ti fermi un attimo per ascoltare.>', '<Ti fermi un attimo per ascoltare.>', 28153),
(144262, 'itIT', '', '<Lo sguardo di Alleria si sposta dalla fredda statua alla placca incisa con il suo epitaffio.>', 28153),
(144261, 'itIT', 'Resistete! Manteniamo la posizione!', 'Resistete! Manteniamo la posizione!', 28153),
(144260, 'itIT', '<Senti un flebile piagnucolio nel respiro morente di Rohn\'kor.>', '', 28153),
(144259, 'itIT', '', 'Userò la pancia tua per fare nu nuovo cappello!', 28153),
(144258, 'itIT', '', 'No! Il piccirillo mio!', 28153),
(144257, 'itIT', '', 'Smettila di mazziarlo! Nun riuscirai a fuggire da chesta fossa!', 28153),
(144256, 'itIT', '', 'Vogliono vederci schiattare! Mangiali tutti quanti!', 28153),
(144255, 'itIT', 'Bwonsamdi... sii misericordioso!', 'Bwonsamdi... sii misericordioso!', 28153),
(144254, 'itIT', 'Zandalar... per sempre...', 'Zandalar... per sempre...', 28153),
(144253, 'itIT', 'Mo\' ti mettiamo a riposare, Urok. Mi spiace che debba andare così!', '', 28153),
(144252, 'itIT', 'Ma che... Che stanno facendo chei cosi dentro Urok?', '', 28153),
(144251, 'itIT', 'Siamo così vicini! Devo solo indossare la roba mia...', '', 28153),
(144250, 'itIT', 'Non così...', 'Nun... nun così...', 28153),
(144249, 'itIT', 'Bwonsamdi... viene... a pigliarmi...', 'Bwonsamdi... viene... a pigliarmi...', 28153),
(144248, 'itIT', 'Mantenete la posizione, altri nemici in arrivo!', 'Mantenete la posizione, altri nemici in arrivo!', 28153),
(144247, 'itIT', 'La mia vita... per Zandalar...', 'La mia vita... per Zandalar...', 28153),
(144245, 'itIT', 'Di chuka Zandalar!', 'Di chuka Zandalar!', 28153),
(144243, 'itIT', 'Accideteli tutti quanti!', 'Accidili tutti!', 28153),
(144242, 'itIT', 'Per l\'unica vera Zandalar!', 'Per l\'unica vera Zandalar!', 28153),
(144240, 'itIT', 'Il sangue tuo impregnerà la nostra terra!', 'Il sangue tuo impregnerà la terra nostra!', 28153),
(144239, 'itIT', 'Ti seppelliremo!', 'Ti seppelliremo!', 28153),
(144238, 'itIT', 'Schiatterai!', 'Schiatterai!', 28153),
(144237, 'itIT', 'Zandalar per sempre!', 'Zandalar per sempre!', 28153),
(144236, 'itIT', 'La Principessa ha detto di trovare i mostri. Sono tutti mostri!', '', 28153),
(144235, 'itIT', 'Dove sta il sole? Nun si vede niente in chesta dannata palude.', '', 28153),
(144234, 'itIT', 'Nun tiene senso! Ci sta nu grosso buco accà. Ma sulla mappa nun ci stanno buchi!', '', 28153),
(144233, 'itIT', 'Oh! Chesto... nun è niente... Che delusione.', '', 28153),
(144232, 'itIT', 'Taz\'okun! Chesto potrebbe essere nu pezzo d\'Azerite!', '', 28153),
(144231, 'itIT', 'Ma che è chesto spuntone? Uh, perché è appiccicoso?', '', 28153),
(144230, 'itIT', 'Oh, che carino. A Talanji potrebbe piacere.', '', 28153),
(144229, 'itIT', 'Un Balestriere Malstregato ti ha preso di mira! Schivalo!', '', 28153),
(144228, 'itIT', 'Non arrivano molte richieste per la forgiatura di spade da queste parti, ma adoro crearle. Diciamo che non mi piace molto il fatto che ne servano così tante.', '', 28153),
(144227, 'itIT', 'Capisco perché la gente tiene paura di chesta palude.', '', 28153),
(144226, 'itIT', 'Mmm... strano.', '', 28153),
(144225, 'itIT', 'Nun credo che riuscirò mai a togliere chesto sporco dalle mani. Povere pergamene.', '', 28153),
(144224, 'itIT', 'Che strana roccia... Oh! Si muove!', '', 28153),
(144223, 'itIT', 'Affascinante.', '', 28153),
(144222, 'itIT', 'Che Gonk guidi il cammino tuo.', 'Che Gonk guidi il cammino tuo.', 28153),
(144221, 'itIT', 'Pa\'ku vegli su di te.', 'Pa\'ku vegli su di te.', 28153),
(144220, 'itIT', 'Rezan ti dia la forza.', 'Rezan ti dia la forza.', 28153),
(144219, 'itIT', 'Comportati bene.', 'Comportati bene.', 28153),
(144218, 'itIT', 'Statt\' accuort\' dentro la città nostra.', 'Statt\' accuort\' dentro la città nostra.', 28153),
(144217, 'itIT', 'Zandalar per sempre!', 'Zandalar per sempre!', 28153),
(144216, 'itIT', 'Tieni bisogno di protezione?', 'Tieni bisogno di protezione?', 28153),
(144215, 'itIT', 'Nun troverai n\'affare migliore.', 'Nun troverai n\'offerta migliore.', 28153),
(144214, 'itIT', 'Che affari ti portano?', 'Che affari ti portano?', 28153),
(144213, 'itIT', 'Salve.', 'Salve.', 28153),
(144209, 'itIT', 'Ho giurato di difendere la famiglia reale.', 'Ho giurato di difendere la famiglia reale.', 28153),
(144208, 'itIT', 'Il regno nostro sarà difeso.', 'Il regno nostro sarà difeso.', 28153),
(144201, 'itIT', 'Cominciamo.', 'Cominciamo.', 28153),
(144200, 'itIT', '$n, siamo molto vicini.$b$bInizierò la divinazione al tuo ordine.$b$bOh, mi sono dimenticato di dire che i nostri avversari si sono accampati lungo la via, sulla spiaggia. Tieni d\'occhio l\'area nel caso vogliano tenderci un\'imboscata.$b$bConfido che mi proteggerai se venissimo attaccati!', '', 28153),
(144199, 'itIT', 'Continuate così! Li stiamo respingendo!', '', 28153),
(144198, 'itIT', 'La notte sta arrivando! Mantenete accesi quei fuochi! Non esitate a chiedere se avete bisogno di altro carburante!', '', 28153),
(144197, 'itIT', 'Non lasciate passare quei mostri! Abbiamo ucciso il loro Behemoth, ma abbiamo perso parecchie navi.', '', 28153),
(144196, 'itIT', 'Se avete riposato, prendete il posto di qualcuno sulla barricata! Dobbiamo sopravvivere a questi demoni!', '', 28153),
(144195, 'itIT', 'Mi servono dei volontari che vadano da Ashton! Potrebbe aiutarci con qualche razzo di segnalazione.', '', 28153),
(144194, 'itIT', 'Assicuratevi di nutrire per primi i bambini, poi pensate ai feriti!', '', 28153),
(144193, 'itIT', 'I guaritori devono ruotare e riposare un po\'. Questo vale anche per te, Krystin!', '', 28153),
(144192, 'itIT', 'Rinforzate la barricata! Usate qualsiasi cosa non sia già inchiodata... e quando finiranno, usate ogni altra cosa!', '', 28153),
(144191, 'itIT', '<Il Croglino fa degli strani suoni e sfrega le zampe sulla ninfea.>', '', 28153),
(144190, 'itIT', 'Quei marinai dovrebbero passare il tempo a tener d\'occhio l\'Orda, non noi.', 'Quei marinai dovrebbero passare il tempo a tener d\'occhio l\'Orda, non noi.', 28153),
(144189, 'itIT', 'Prima troveremo quello che ci serve e ce ne andremo, meglio è.', 'Prima troveremo quello che ci serve e ce ne andremo, meglio è.', 28153),
(144188, 'itIT', 'L\'Orda è vicina, attenzione!', 'L\'Orda è vicina, attenzione!', 28153),
(144187, 'itIT', 'Avrei tanto voluto che la Lega degli Esploratori avesse potuto assegnare più personale a questa spedizione.', 'Avrei tanto voluto che la Lega degli Esploratori avesse potuto assegnare più personale a questa spedizione.', 28153),
(144186, 'itIT', 'Se non tenessimo d\'occhio i Ferroscuro, chissà cosa combinerebbero.', 'Se non tenessimo d\'occhio i Ferroscuro, chissà cosa combinerebbero.', 28153),
(144185, 'itIT', '', 'E anche ai loro bambini! Potrei allestire una cabina per le foto e creare dei dinosauri giocattolo. Ovviamente avresti una parte del guadagno, tipo 70-30. 70 per me ovviamente, in quanto ideatrice di tutto questo.', 28153),
(144184, 'itIT', 'Più avanti ce ne sta n\'altro che tiene bisogno d\'aiuto, se nun ti dispiace.', '', 28153),
(144183, 'itIT', '', 'RESUSE ME: It\'s time to use the injector to enrage Ben\'jin and then follow him and help him destroy the invasive species.', 28153),
(144182, 'itIT', 'Quando finiremo di scavare qui, l\'Orda sarà già arrivata a Forgiardente!', 'Quando finiremo di scavare qui, l\'Orda sarà già arrivata a Forgiardente!', 28153),
(144181, 'itIT', 'I Ferroscuro non temono il caldo, ma questa umidità...', 'I Ferroscuro non temono il caldo, ma questa umidità...', 28153),
(144180, 'itIT', 'La Lega degli Esploratori adora passare il proprio tempo a scavare, anche quando c\'è una guerra da vincere.', 'La Lega degli Esploratori adora passare il proprio tempo a scavare, anche quando c\'è una guerra da vincere.', 28153),
(144179, 'itIT', 'Abbiamo abbandonato la nostra montagna per questo?', 'Abbiamo abbandonato la nostra montagna per questo?', 28153),
(144178, 'itIT', 'Non essere così drammatica...', '', 28153),
(144177, 'itIT', '', 'I graffi... l\'imprecisa rimozione della terra... come faremo adesso?', 28153),
(144176, 'itIT', 'È andata così male?', '', 28153),
(144175, 'itIT', '', 'Aspetta!', 28153),
(144174, 'itIT', 'Prenditi pure la libertà di accelerare le operazioni, se vuoi. Questo dispositivo farà al caso tuo.', '', 28153),
(144173, 'itIT', 'Soddisfazione? Signora, staremo qui tutto l\'anno, di questo passo.', '', 28153),
(144172, 'itIT', '', 'Ahhh, fantastico. Che soddisfazione, vero?', 28153),
(144171, 'itIT', '', 'Cerca di non danneggiare il fossile... Eccellente.', 28153),
(144170, 'itIT', '', 'Molto bene. Tieni ferma la mano ora...', 28153),
(144169, 'itIT', '', 'Occhio a dove mettete i piedi, Druidi! Questo posto è una trappola mortale!', 28153),
(144168, 'itIT', 'Ben fatto! Dovremmo riuscire a usarlo contro quelle mostruose creature di legno. Ah... non farne fuoriuscire neanche una goccia!', '', 28153),
(144167, 'itIT', 'Grazie per averla riportata da me.', '', 28153),
(144166, 'itIT', '', 'RESUSE ME: Here is the box for the injector contraption. Please install it.', 28153),
(144165, 'itIT', '', 'Ciao papà!', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(144164, 'itIT', 'Penny! Oh, mia cara!', '', 28153),
(144163, 'itIT', 'La vostra vittoria alla Segheria non durerà a lungo! Ce la riprenderemo!', '', 28153),
(144162, 'itIT', 'Andiamo a trovare tuo papà.', 'Andiamo a trovare tuo papà.', 28153),
(144161, 'itIT', '', 'Ciao! Come ti chiami?', 28153),
(144160, 'itIT', 'Non capisci in quale pericolo ti trovi?', 'Non capisci in quale pericolo ti trovi?', 28153),
(144159, 'itIT', 'Non puoi fermarci tutti!', 'Non puoi fermarci tutti!', 28153),
(144158, 'itIT', 'Non ci troverai mai tutti!', 'Non ci troverai mai tutti!', 28153),
(144157, 'itIT', 'La mia posizione è compromessa!', 'La mia posizione è compromessa!', 28153),
(144156, 'itIT', 'Guarda! Hanno anche uno dei nostri tamburi!\n\nChi dice che i Goblin non hanno cultura?', '', 28153),
(144153, 'itIT', 'Ora serve qualche goccia di Linfa Instabile. Attenzione a non agitare troppo il contenitore!', '', 28153),
(144152, 'itIT', 'Aggiungiamo un po\' di zolfo. Fa\' attenzione ai fumi!', '', 28153),
(144151, 'itIT', 'Ora aggiungi delicatamente un po\' di Bocciolo del Focolare.', '', 28153),
(144150, 'itIT', 'Dobbiamo aggiungere un po\' di salnitro per dargli un tocco particolare!', '', 28153),
(144148, 'itIT', '<Krag\'wa annuisce al tuo animaletto.>', '', 28153),
(144147, 'itIT', '<Sembra che Krag\'wa e il piccolo Croglino stiano comunicando.>', '', 28153),
(144146, 'itIT', 'No! Non tornerò mai in quella cella! MAI!', '', 28153),
(144145, 'itIT', '', 'Difendete il santuario! Non possiamo perderlo.', 28153),
(144144, 'itIT', 'Eccellente! Ti dirò cosa aggiungere nel calderone. Segui le mie istruzioni o i risultati potrebbero essere... esplosivi.', '', 28153),
(144142, 'itIT', 'Ciao Penny!', '', 28153),
(144141, 'itIT', '', 'Sì! Ci vediamo dopo, Joe!', 28153),
(144140, 'itIT', '', 'Ciao Joe!', 28153),
(144139, 'itIT', 'Oh, ciao Penny. Stai andando a trovare tuo padre?', '', 28153),
(144138, 'itIT', 'Ma che hanno tutti quanti?!?', '', 28153),
(144137, 'itIT', '', 'Ho bisogno di cure!', 28153),
(144136, 'itIT', '', 'Arrenditi agli elementi!', 28153),
(144135, 'itIT', '$n, non posso fare nulla per farlo tornare come prima. Avrà una vita migliore assieme a te. Tienilo con te. Tienilo al sicuro.', '', 28153),
(144134, 'itIT', 'Capisco.', '', 28153),
(144133, 'itIT', 'Vieni più vicino, $gpiccoletto:piccoletta;.', '', 28153),
(144132, 'itIT', 'Incubo...', '', 28153),
(144131, 'itIT', 'La luna... sta sorgendo...', '', 28153),
(144130, 'itIT', 'Spiagge distanti...', '', 28153),
(144129, 'itIT', 'Nun rimestare... il pentolone...', '', 28153),
(144128, 'itIT', 'Altre due bevande... e il più grande peperone tuo...', '', 28153),
(144127, 'itIT', 'La montagna centrale... rovesciata...', '', 28153),
(144126, 'itIT', 'Ancora dieci minuti...', '', 28153),
(144125, 'itIT', 'Nun ancora...', '', 28153),
(144124, 'itIT', '<Sinuosino ringhia difensivamente.>', '', 28153),
(144123, 'itIT', 'Affronta la tua fine!', 'Affronta la tua fine!', 28153),
(144122, 'itIT', 'Osserva la verità... della tua fine...', '', 28153),
(144121, 'itIT', 'Non c\'è vittoria per voi... solo... morte...', '', 28153),
(144120, 'itIT', 'Sei insignificante... dinnanzi al Vuoto...', '', 28153),
(144119, 'itIT', 'Non hai ottenuto... nulla...', '', 28153),
(144118, 'itIT', 'I padroni... si levano...', '', 28153),
(144117, 'itIT', 'Il Vuoto arriva... per tutti...', '', 28153),
(144116, 'itIT', 'Inutile... tutto diventerà... oscurità...', '', 28153),
(144115, 'itIT', 'Troveranno il tuo cadavere arenato al porto!', 'Troveranno il tuo cadavere arenato al porto!', 28153),
(144114, 'itIT', 'Kul Tiras non ha bisogno dell\'Alleanza!', 'Kul Tiras non ha bisogno dell\'Alleanza!', 28153),
(144113, 'itIT', 'Ti darò in pasto alle onde!', 'Ti darò in pasto alle onde!', 28153),
(144112, 'itIT', 'Mettiti in coda per la Battaglia di Stromgarde.', 'Mettiti in coda per la Battaglia di Stromgarde.', 28153),
(144111, 'itIT', 'Da questo tavolo, puoi metterti in coda per un Fronte di Guerra.', '', 28153),
(144110, 'itIT', 'Katherine ci farà annegare tutti!', 'Katherine ci farà annegare tutti!', 28153),
(144109, 'itIT', 'Azeroth è nostra.', '', 28153),
(144108, 'itIT', 'L\'impero rinascerà!', '', 28153),
(144107, 'itIT', 'Trovali!', '', 28153),
(144106, 'itIT', 'Tutto sarà perduto.', '', 28153),
(144105, 'itIT', 'Tutto cadrà.', '', 28153),
(144104, 'itIT', 'Nessuna speranza... nessuna vita.', '', 28153),
(144103, 'itIT', 'Tutto verrà consumato.', '', 28153),
(144102, 'itIT', 'Tutto diventerà ombra.', '', 28153),
(144101, 'itIT', 'Il Vuoto consuma tutto.', '', 28153),
(144100, 'itIT', '', 'Druidi dell\'Unghia, ATTACCATE!', 28153),
(144099, 'itIT', '<Fischia>', '', 28153),
(144097, 'itIT', '', 'E piano B sia.', 28153),
(144096, 'itIT', 'Ho le informazioni, ora dobbiamo soltanto uscire di qui!', '', 28153),
(144095, 'itIT', '', 'Siamo stati scoperti!', 28153),
(144094, 'itIT', 'Sa... Sa-sangue di Azeroth individuato. Richiesta installazione nucleo di da-da-dati.', '', 28153),
(144093, 'itIT', 'Ugh! Tiene nu sapore orribile!', '', 28153),
(144092, 'itIT', 'Jabari, tieni la memoria di n\'elekk e l\'umorismo di Gonk.', '', 28153),
(144091, 'itIT', 'Certo, paragoniamo il \"piccante\" suo a nu \"avvelenamento che porta alla morte\"...', '', 28153),
(144090, 'itIT', 'Nun tengo bisogno delle cure tue, Jabari! Sono sopravvissuto al chili di Haw\'li!', '', 28153),
(144089, 'itIT', 'Smettila, animale. Tieni pure la gola arrossata.', '', 28153),
(144088, 'itIT', 'Zitto, fratello. Prendi chesto.', '', 28153),
(144087, 'itIT', 'Stai senza pensieri, cumpà!', '', 28153),
(144086, 'itIT', 'Perfetto! Vediamo cos\'altro serve...', '', 28153),
(144085, 'itIT', 'Si vede che ci sai fare con l\'Alchimia, non è di certo la tua prima volta!', '', 28153),
(144084, 'itIT', 'Ben fatto. Ora dobbiamo...', '', 28153),
(144082, 'itIT', 'Il primo colpo è carico. Una volta iniziato l\'attacco, sapranno che siamo qui.$b$bSei $gpronto:pronta;?', '', 28153),
(144081, 'itIT', 'È solo questione di tempo prima che vengano quassù a controllare...', '', 28153),
(144080, 'itIT', '', 'Dai! Andiamo!', 28153),
(144079, 'itIT', '', 'Aspetta! Dobbiamo tenerci la mano!', 28153),
(144078, 'itIT', 'I Marefiero periranno!', 'I Marefiero periranno!', 28153),
(144077, 'itIT', 'La mia morte non fermerà il mutamento delle maree.', 'La mia morte non fermerà il mutamento delle maree.', 28153),
(144076, 'itIT', 'Te ne pentirai!', 'Te ne pentirai!', 28153),
(144075, 'itIT', 'Qui non c\'è posto per te!', 'Qui non c\'è posto per te!', 28153),
(144074, 'itIT', 'Boralus appartiene a noi!', 'Boralus appartiene a noi!', 28153),
(144073, 'itIT', '', 'Ci saranno nu sacco di soldati di Zul tra accà e Atal\'dazar. Dobbiamo farli fuori.', 28153),
(144072, 'itIT', 'Elfi...', 'Elfi...', 28153),
(144071, 'itIT', 'L\'Esecutore Rastari sputa per terra.', 'L\'Esecutrice Rastari sospira.', 28153),
(144070, 'itIT', 'Certamente. È così primitivo. Va bene: 3... 2... 1...', '', 28153),
(144069, 'itIT', '', 'Assicurati di inquadrare il grosso e orrendo tempio dietro di me.', 28153),
(144068, 'itIT', '', 'Tutti i nostri amici a Lunargenta saranno così invidiosi quando vedranno questa foto.', 28153),
(144067, 'itIT', 'La prima prova era giunta al termine. Finita l\'ultima parte della mia storia, tornai al mondo reale.', 'La prima prova era giunta al termine. Finita l\'ultima parte della mia storia, tornai al mondo reale.', 28153),
(144066, 'itIT', 'Catturò il mio sguardo e la sentii entrarmi nella mente, riempiendola della conoscenza necessaria per evocarla.', 'Catturò il mio sguardo e la sentii entrarmi nella mente, riempiendola della conoscenza necessaria per evocarla.', 28153),
(144065, 'itIT', 'Le sue urla riecheggiarono nella stanza.', 'Le sue urla riecheggiarono nella stanza.', 28153),
(144064, 'itIT', 'Una volta completato il rituale, dinnanzi ai miei occhi comparve una creatura.', 'Una volta completato il rituale, dinnanzi ai miei occhi comparve una creatura.', 28153),
(144063, 'itIT', 'Appena entrato, notai tre rune sul pavimento. Forse è a questo che serviva l\'inchiostro.', 'Appena entrata, notai tre rune sul pavimento. Forse è a questo che serviva l\'inchiostro.', 28153),
(144062, 'itIT', 'Una volta raccolto abbastanza inchiostro, mi sentii attirare verso il fondo di una di queste stanze.', 'Una volta raccolto abbastanza inchiostro, mi sentii attirare verso il fondo di una di queste stanze.', 28153),
(144061, 'itIT', 'Uno scheletro per terra mi ricordò la mia mortalità. Mi chiesi se altri avessero fallito questa prova prima di me.', 'Uno scheletro per terra mi ricordò la mia mortalità. Mi chiesi se altri avessero fallito questa prova prima di me.', 28153),
(144060, 'itIT', 'Quelle più viscose stavano cominciando a diventare una seccatura.', 'Quelle più viscose stavano cominciando a diventare una seccatura.', 28153),
(144059, 'itIT', 'Le melme erano la chiave per risolvere l\'enigma. E fino a ora, stavo trovando ciò che mi serviva.', 'Le melme erano la chiave per risolvere l\'enigma. E fino a ora, stavo trovando ciò che mi serviva.', 28153),
(144058, 'itIT', 'In qualche modo, sapevo cosa dovevo fare. Decisi di continuare.', 'In qualche modo, sapevo cosa dovevo fare. Decisi di continuare.', 28153),
(144057, 'itIT', 'Attenzione al getto, raccogli il cremisi e il tuo assassino vincolato dal sangue potrai risvegliare.\"', 'Attenzione al getto, raccogli il cremisi e il tuo assassino vincolato dal sangue potrai risvegliare.\"', 28153),
(144056, 'itIT', '\"Ciò che esce dalla penna e dalle vene qui si deve mescolare.\"', '\"Ciò che esce dalla penna e dalle vene qui si deve mescolare.\"', 28153),
(144055, 'itIT', 'Mi risvegliai in una stanza. Una strana voce recitava una poesia nella mia mente.', 'Mi risvegliai in una stanza. Una strana voce recitava una poesia nella mia mente.', 28153),
(144054, 'itIT', 'Inizi a scrivere sul libro: \"Non appena la mia penna toccò la pagina, mi sentii subito trascinare\".', 'Inizi a scrivere sul libro: \"Non appena la mia penna toccò la pagina, mi sentii subito trascinare\".', 28153),
(144053, 'itIT', '<Sfogliando tutto il libro rapidamente, ogni pagina sembra essere bianca. Volgi lo sguardo verso Kronah e ti chiedi se sappia come risolvere questo enigma.>', '', 28153),
(144052, 'itIT', 'Non vedo l\'ora di leggere le tue avventure.', '', 28153),
(144051, 'itIT', 'Tira fuori una penna e comincia a scrivere. Non preoccuparti, il libro farà il resto.', '', 28153),
(144050, 'itIT', 'È molto semplice. Devi scrivere la tua storia su quel libro.', '', 28153),
(144049, 'itIT', 'Oh no, ecco che arriva...', '', 28153),
(144048, 'itIT', 'Vorrei scambiare alcune penne.', 'Vorrei scambiare alcune penne.', 28153),
(144047, 'itIT', 'Mmm... Non è andata proprio secondo i piani. Proviamo di nuovo!', '', 28153),
(144046, 'itIT', 'L\'Alchimia è una scienza esatta! Cerca di fare più attenzione.', '', 28153),
(144045, 'itIT', 'No, non ci siamo. Dobbiamo ripartire da zero!', '', 28153),
(144044, 'itIT', 'La miscela ha preso fuoco! Dobbiamo cominciare da capo!', 'La miscela ha preso fuoco! Dobbiamo cominciare da capo!', 28153),
(144043, 'itIT', 'Zul lo aveva predetto. Continuando a combattere per cambiare il destino, dimostri solo la sua inevitabilità!', '', 28153),
(144042, 'itIT', 'Zul... non aveva detto... che avrei perso...', '', 28153),
(144041, 'itIT', 'Non raggiungerai mai il precipizio in tempo!', '', 28153),
(144040, 'itIT', 'Sono pronto per cominciare!', 'Sono pronta per cominciare!', 28153),
(144039, 'itIT', 'Aspetta! Ora sto meglio! Argh...', 'Aspetta! Ora sto meglio! Argh...', 28153),
(144038, 'itIT', 'Sono stato uno stupido!', 'Sono stato uno stupido!', 28153),
(144037, 'itIT', 'Non riesco più a sentire il suo canto...', 'Non riesco più a sentire il suo canto...', 28153),
(144036, 'itIT', 'Lei non ti amerà mai!', 'Lei non ti amerà mai!', 28153),
(144035, 'itIT', 'Nooo, amore mio!', 'Nooo, amore mio!', 28153),
(144034, 'itIT', 'L\'amore fa male.', 'L\'amore fa male.', 28153),
(144033, 'itIT', 'Ne è valsa la pena!', 'Ne è valsa la pena!', 28153),
(144032, 'itIT', 'Separarsi è un dolore così dolce.', 'Separarsi è un dolore così dolce.', 28153),
(144031, 'itIT', 'Ehi, bella, guardami mentre faccio nero quel tipo.', 'Ehi, bella, guardami mentre faccio nero quel tipo.', 28153),
(144030, 'itIT', 'Stai guardando la mia ragazza?!?', 'Stai guardando la mia ragazza?!?', 28153),
(144029, 'itIT', 'L\'amore conquista ogni cosa!', 'L\'amore conquista ogni cosa!', 28153),
(144028, 'itIT', 'È mia! MIA!', 'È mia! MIA!', 28153),
(144027, 'itIT', 'Hai i nostri ringraziamenti. Hai salvato il villaggio, ispirando molto coraggio in me. Alby, Therold, assicuratevi che Pescagrossa si riprenda. Presto avrete mie notizie.', '', 28153),
(144026, 'itIT', 'Non toccarla!', 'Non toccarla!', 28153),
(144025, 'itIT', 'Zul vuole risvegliare Dazar!?! Non resterò qui mentre questo \"profeta\" profana le ossa del primo re. Vieni, e unisciti a noi ai cancelli meridionali.', '', 28153),
(144024, 'itIT', 'Ora devo tornare a casa. Mio zio e i suoi Saggi delle Maree nella Valle dei Sacraonda potrebbero avere altre informazioni su questa magia oscura.', '', 28153),
(144023, 'itIT', 'Scrutafondi è sempre stato intelligente, ma non sapevo che praticasse questo tipo di magia. Attingere a un tale potere potrebbe gettare nel panico l\'intero oceano...', '', 28153),
(144022, 'itIT', 'Stai alla larga, è già impegnata!', 'Stai alla larga, è già impegnata!', 28153),
(144021, 'itIT', '', 'Sì! C\'è una breccia tra i Frangicieli. Volate, figli miei! Uccidete questi eretici!', 28153),
(144020, 'itIT', 'Pescagrossa è stata salvata, ma ho paura che non sia finita. Scrutafondi, per quanto astuto potesse essere, non possedeva quel tipo di potere.', '', 28153),
(144019, 'itIT', 'Ti proteggerò, amore mio!', 'Ti proteggerò, amore mio!', 28153),
(144018, 'itIT', 'La amo così tanto!', 'La amo così tanto!', 28153),
(144017, 'itIT', 'LA MANO DEL DESTINO È SAZIA. TI PORTERÒ AL SICURO. A VOLTE IL DESTINO È GENTILE.', '', 28153),
(144016, 'itIT', 'Vattene dalla città nostra, $p! Ci condannerai tutti quanti!', '', 28153),
(144015, 'itIT', 'Fate largo a $p, $gbenedetto:benedetta; dai Loa!', '', 28153),
(144013, 'itIT', '', 'I presagi sono contrastanti... Affronterai sfide impossibili, ma riuscirai a superarle. I Loa nun ti abbandoneranno.', 28153),
(144012, 'itIT', '', 'Temo che chesti siano tutti cattivi presagi... Vedo infiniti problemi nel futuro tuo. Mi dispiace.', 28153),
(144011, 'itIT', '', 'Oggi evita l\'acqua. Nun è sicura.', 28153),
(144010, 'itIT', '', 'Vuoto? No... devi cambiare chesto.', 28153),
(144009, 'itIT', '', 'Verrai $gesposto:esposta; a stenti e tradimenti. Oggi scegli con attenzione i compagni tuoi.', 28153),
(144008, 'itIT', '', 'Nun sentivo chesto presagio da molto tempo... devi cambiare il destino tuo.', 28153),
(144007, 'itIT', '', 'Nun prendere scorciatoie per raggiungere li obiettivi tuoi. Qualsiasi compromesso ti porterà a na triste fine.', 28153),
(144006, 'itIT', '', 'Chesto avvertimento viene dall\'Aldilà. Sta\' accuort\'.', 28153),
(144005, 'itIT', '', 'Guardati dalla Città d\'Oro. Nun vale il rischio.', 28153),
(144004, 'itIT', '', 'Temo tu debba affrontare il futuro senza vedere.', 28153),
(144003, 'itIT', '', 'Gral viene trascinato nelle profondità da na mano nascosta.', 28153),
(144002, 'itIT', '', 'Il nido di Shadra sta vuoto.', 28153),
(144001, 'itIT', '', 'Torcali dorme.', 28153),
(144000, 'itIT', '', 'Rezan cade a terra... schiattato.', 28153),
(143999, 'itIT', '', 'Bwonsamdi offre nu patto con nu sorriso.', 28153),
(143998, 'itIT', '', 'Krag\'wa ingoia nu branco di cornofurente blu.', 28153),
(143997, 'itIT', '', 'Gonk sta solo, nuota attraverso nu fiume d\'oro.', 28153),
(143996, 'itIT', '', 'Pa\'ku chiude li occhi nell\'oscurità.', 28153),
(143995, 'itIT', '', 'Ci stanno pochi presagi peggiori di chesto. Sta\' accuort\'.', 28153),
(143994, 'itIT', '', 'Nu presagio oscuro per tutti noi. Cosa hai portato sulle rive nostre?', 28153),
(143993, 'itIT', '', 'Tu sprechi il potenziale tuo. Sorgi di fronte a cheste opportunità, o verrai $gdimenticato:dimenticata; tra i morti senza nome.', 28153),
(143992, 'itIT', '', 'Le divisioni tra li alleati tuoi rischiano di metterci tutti in pericolo. Tu devi riunire Zandalar.', 28153),
(143991, 'itIT', '', 'Nu presagio funesto, ma potrà essere superato con la forza e la determinazione.', 28153),
(143990, 'itIT', '', 'Comandanti divisi nun sono veri comandanti. Devi cooperare con i rivali tuoi o pagarne le conseguenze.', 28153),
(143989, 'itIT', '', 'N\'oscurità che si leverà e consumerà anche i più forti tra di noi. Compreso te.', 28153),
(143988, 'itIT', '', 'Nu presagio oscuro per tutti noi...', 28153),
(143987, 'itIT', '', 'La morte di nu nuovo amico.', 28153),
(143986, 'itIT', '', 'Nu tramonto nelle oscure paludi di Nazmir.', 28153),
(143985, 'itIT', '', 'Nu vaso spezzato, da cui esce del vino.', 28153),
(143984, 'itIT', '', 'Due Sacerdoti che si ammazzano a vicenda.', 28153),
(143983, 'itIT', '', 'Na nave delli Umani sulle spiagge nostre...', 28153),
(143982, 'itIT', '', 'Nu trono infranto di fuoco e ghiaccio...', 28153),
(143981, 'itIT', '', 'Nu brutosauro che affoga nel sangue.', 28153),
(143980, 'itIT', '', 'Nu fiume di sangue, con cadaveri che galleggiano controcorrente...', 28153),
(143979, 'itIT', 'Coraggio, Graffietta, andiamo!', 'Coraggio, Graffietta, andiamo!', 28153),
(143978, 'itIT', 'Sì! Grazie!', 'Sì! Grazie!', 28153),
(143977, 'itIT', 'Accidenti, ora va assai meglio!', '', 28153),
(143976, 'itIT', 'Gli ho detto di andarsene, ma dovevano vederne n\'altro... Io stesso sono vivo per miracolo... Se nun fosse stato per l\'aiuto tuo, nun ce l\'avrei fatta.', '', 28153),
(143975, 'itIT', '', 'Parlate attraverso il ricettacolo vostro, Zetoa!', 28153),
(143974, 'itIT', '', 'Parlate attraverso il ricettacolo vostro, Iluna!', 28153),
(143973, 'itIT', '', 'Siamo pronti. Riempite i ricettacoli miei e rivelateci il futuro.', 28153),
(143972, 'itIT', '', 'Spiriti dei morti, spiriti dei Loa, spiriti di coloro che sono perduti e in pericolo, ascoltatemi!', 28153),
(143971, 'itIT', 'Tornerò indietro alla linea difensiva!', 'Tornerò indietro alla linea difensiva!', 28153),
(143970, 'itIT', 'Non riuscivo a muovermi!', 'Non riuscivo a muovermi!', 28153),
(143969, 'itIT', 'Pensavo sarei stato trascinato nella foresta!', 'Pensavo sarei stata trascinata nella foresta!', 28153),
(143968, 'itIT', 'Hanno già portato della gente nella foresta!', 'Hanno già portato della gente nella foresta!', 28153),
(143967, 'itIT', 'Tornerò indietro al fronte!', 'Tornerò indietro al fronte!', 28153),
(143966, 'itIT', '', 'Chesti sono tutti presagi buoni... Oggi sii audace nelle azioni tue!', 28153),
(143965, 'itIT', 'Credevo di essere spacciato!', 'Credevo di essere spacciata!', 28153),
(143964, 'itIT', 'Grazie!', 'Grazie!', 28153),
(143963, 'itIT', '', 'Na fuga precipitosa...', 28153),
(143962, 'itIT', '', 'Nu presagio di spensieratezza... Nun permettere all\'ansia di sopraffarti. Gioia e allegria ti porteranno al successo.', 28153),
(143961, 'itIT', 'La piaga si diffonde!', '', 28153),
(143960, 'itIT', 'Tutto... avvizzisce...', '', 28153),
(143959, 'itIT', '', 'La più comune benedizione di Shadra, con n\'aggiunta imprevista. È ancora nu buon presagio, ma nun lo comprendo appieno.', 28153),
(143958, 'itIT', '', 'La benedizione del difensore... Tu salverai molte vite, ma forse donerai la tua.', 28153),
(143957, 'itIT', '', 'Il Loa dei Re è nu presagio raro assai. Potente e forte. Tu distruggerai i nemici suoi.', 28153),
(143956, 'itIT', '', 'Nu buon presagio di vita lunga e morte rapida.', 28153),
(143955, 'itIT', 'Devo nutrirmi!', '', 28153),
(143954, 'itIT', 'Avvizzite!', '', 28153),
(143953, 'itIT', 'La corruzione sboccia!', '', 28153),
(143952, 'itIT', '', 'Se l\'isola nun è la tua terra natia, chesto è nu buon presagio.', 28153),
(143951, 'itIT', 'Crescete!', '', 28153),
(143950, 'itIT', '', 'Combatterai sempre al fianco delli alleati tuoi. Gonk nun ti abbandonerà nel momento del bisogno.', 28153),
(143949, 'itIT', '', 'Pa\'ku guiderà il viaggio tuo e allontanerà i nemici...', 28153),
(143948, 'itIT', 'Che terreno fertile.', '', 28153),
(143947, 'itIT', '', 'Gral salta sopra la flotta del Re...', 28153),
(143946, 'itIT', '', 'Le uova di Shadra si schiudono. Infiniti occhi emergono...', 28153),
(143945, 'itIT', '', 'Torcali resta ritto sulla vetta di na montagna, da solo...', 28153),
(143944, 'itIT', '', 'Rezan percuote la terra e i Troll del Sangue fuggono...', 28153),
(143943, 'itIT', '', 'Bwonsamdi guarda in lontananza...', 28153),
(143942, 'itIT', '', 'Krag\'wa ingoia n\'isola...', 28153),
(143941, 'itIT', 'Ammuffisci!', '', 28153),
(143940, 'itIT', '', 'Gonk corre insieme al branco suo...', 28153),
(143939, 'itIT', 'Mietitura!', '', 28153),
(143938, 'itIT', 'Il marciume deve espandersi!', '', 28153),
(143937, 'itIT', '', 'Quasi sempre nu buon presagio, ma dipende dalli amici tuoi...', 28153),
(143936, 'itIT', '', 'Nu buon presagio per tutti noi. La presenza tua dovrebbe essere benvenuta a Zandalar.', 28153),
(143935, 'itIT', '', 'Contrariamente a quanto molti credono, nun hai ancora raggiunto il pieno potenziale tuo. Il potere tuo crescerà ancora e supererà ogni aspettativa.', 28153),
(143934, 'itIT', '', 'Nu... presagio sorprendete per nu straniero. Che significa?', 28153),
(143933, 'itIT', '', 'Nu potente presagio! La fortuna ti assiste...', 28153),
(143932, 'itIT', '', 'Nu buon presagio di espansione e crescita per la gente nostra. È interessante che sia stato fatto a te...', 28153),
(143931, 'itIT', '', 'Nu buon presagio di prosperità e patrimonio spirituale.', 28153),
(143930, 'itIT', '', 'Nu buon presagio di forza, potere e successo.', 28153),
(143929, 'itIT', '', 'La resurrezione di nu vecchio amico...', 28153),
(143928, 'itIT', '', 'Nu sole sull\'acqua dorata...', 28153),
(143927, 'itIT', '', 'Nu grosso uovo che si agita ma nun si apre...', 28153),
(143926, 'itIT', '', 'Tutte le tribù dei Troll, unite sotto lo stendardo delli Zandalari...', 28153),
(143925, 'itIT', '', 'La testa mozzata di n\'Elfo...', 28153),
(143924, 'itIT', '', 'Antiche acque, nun disturbate da generazioni...', 28153),
(143923, 'itIT', '', 'Maschere d\'oro...', 28153),
(143922, 'itIT', '', 'L\'ombra di Pa\'ku incrocia nu sentiero di pietra...', 28153),
(143921, 'itIT', '', 'Molto bene. Scopriamo cosa li spiriti vogliono dirti...', 28153),
(143920, 'itIT', '', 'Vuoi davvero sapere il futuro tuo, $p?\n\nNun tutti i presagi parlano di grandi gesta e lieti fini...', 28153),
(143919, 'itIT', 'Non ho paura. Dimmi cosa vedi nel mio futuro.', 'Non ho paura. Dimmi cosa vedi nel mio futuro.', 28153),
(143918, 'itIT', 'Cosa vedi nel mio futuro?', 'Cosa vedi nel mio futuro?', 28153),
(143917, 'itIT', '', 'Ascoltatemi, spiriti, perduti e antichi. Pigliate i ricettacoli miei e rivelateci il futuro.', 28153),
(143916, 'itIT', 'Non importa. Siamo ovunque... sotto i tuoi piedi.', '', 28153),
(143915, 'itIT', 'Sei debole... La nostra tribù... è più forte.', 'Sei debole... La nostra tribù... è più forte.', 28153),
(143914, 'itIT', '', '$gBenvenuto:Benvenuta; al Salone Spirituale Perduto, $p.\n\nSei in ritardo. Nun ero certa che ce l\'avresti fatta.\n\nAllora dimmi: cosa può fare per te oggi Dama Konawla?', 28153),
(143913, 'itIT', 'Muoio in pace...', 'Muoio in pace...', 28153),
(143912, 'itIT', 'Le nostre spine... ricopriranno il mondo...', 'Le nostre spine... ricopriranno il mondo...', 28153),
(143911, 'itIT', 'Gli Spinomanto... diventeranno più forti...', 'Gli Spinomanto... diventeranno più forti...', 28153),
(143910, 'itIT', 'Il mio cammino... è finito.', 'Argh... il mio cammino... è finito.', 28153),
(143909, 'itIT', 'La tua morte mi darà gloria.', 'La tua morte mi darà gloria.', 28153),
(143908, 'itIT', 'Le spine cresceranno forti nutrendosi del tuo sangue.', 'Le spine cresceranno forti nutrendosi del tuo sangue.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143907, 'itIT', 'Nessuna ritirata, nessuna resa!', 'Nessuna ritirata, nessuna resa!', 28153),
(143906, 'itIT', 'Perché il Compendio della Carneficina è vuoto?', 'Perché il Compendio della Carneficina è vuoto?', 28153),
(143905, 'itIT', 'I nostri cinghiali si ciberanno di te.', 'I nostri cinghiali si ciberanno di te.', 28153),
(143904, 'itIT', 'Non potete fermarci!', 'Non potete fermarci!', 28153),
(143903, 'itIT', 'Questa terra è nostra!', 'Questa terra è nostra!', 28153),
(143902, 'itIT', 'Inizia a scrivere sul libro.', 'Inizia a scrivere sul libro.', 28153),
(143901, 'itIT', 'Sfoglia tutto il libro.', 'Sfoglia tutto il libro.', 28153),
(143900, 'itIT', 'Graffettaaa! Sei ancora lì? Miagola due volte se riesci a sentirmi!', 'Graffiettaaa! Sei ancora lì? Miagola due volte se mi senti!', 28153),
(143899, 'itIT', '<Molte altre pagine da questo punto in poi sembrano essere bianche.>', '', 28153),
(143898, 'itIT', 'Ti faremo scendere, Graffietta! Fai la brava!', 'Ti faremo scendere, Graffietta! Fai la brava!', 28153),
(143897, 'itIT', 'Andrà tutto bene! Aspetta lì!', 'Andrà tutto bene, Graffietta! Aspetta lì!', 28153),
(143896, 'itIT', 'Gira ancora qualche pagina.', 'Gira ancora qualche pagina.', 28153),
(143895, 'itIT', '<Le pagine del libro sembrano essere bianche.>', '', 28153),
(143894, 'itIT', 'MiaaaOOOooo.', '', 28153),
(143893, 'itIT', 'Resisti, Graffietta! Gli aiuti sono in arrivo!', 'Resisti, Graffietta! Gli aiuti sono in arrivo!', 28153),
(143892, 'itIT', 'Vieni giù, Graffietta, vieni giù! Non è sicuro lassù!', 'Vieni giù, Graffietta, vieni giù! Non è sicuro là sopra!', 28153),
(143891, 'itIT', 'Salta giù, Graffietta! Ti prendo io!', 'Salta giù, Graffietta! Ti prendo io!', 28153),
(143890, 'itIT', 'Graffiettaaa!!! Vieni giù!!!', 'Graffietta!!! Vieni giù!!!', 28153),
(143889, 'itIT', '', 'Ti darò in pasto ai famigli miei, $R!', 28153),
(143888, 'itIT', 'Ehi, tu, di qua!', '', 28153),
(143887, 'itIT', 'Da questa parte!', '', 28153),
(143886, 'itIT', 'Attenzione!', '', 28153),
(143885, 'itIT', 'Di qua.', '', 28153),
(143884, 'itIT', 'Di qua.', '', 28153),
(143883, 'itIT', 'Attenzione!', '', 28153),
(143882, 'itIT', 'Da questa parte!', '', 28153),
(143881, 'itIT', 'Tu. Di qua!', '', 28153),
(143879, 'itIT', 'Epurazione!', '', 28153),
(143876, 'itIT', 'È finita.', '', 28153),
(143875, 'itIT', 'Sangue! Sangue! Sangue!', '', 28153),
(143874, 'itIT', 'Zuldazar cadrà!', '', 28153),
(143873, 'itIT', 'Carne fresca!', '', 28153),
(143872, 'itIT', 'Voglio il sangue tuo!', '', 28153),
(143871, 'itIT', 'Le ossa tue ci serviranno a dovere.', '', 28153),
(143870, 'itIT', 'Il sangue tuo per G\'huun!', '', 28153),
(143869, 'itIT', 'Nun puoi nasconderti dal Dio del Sangue!', '', 28153),
(143868, 'itIT', 'Guzincha!', '', 28153),
(143867, 'itIT', 'Kachago!', '', 28153),
(143865, 'itIT', 'Non hai letto il testo in piccolo?\n\nNiente rimborsi. Niente eccezioni. Niente lamentele.\n\nPerò so cosa ti alzerà l\'umore... una Caduta Allegra di Volapiume!', '', 28153),
(143864, 'itIT', 'Una Caduta Allegra di Volapiume, grazie.', 'Una Caduta Allegra di Volapiume, grazie.', 28153),
(143863, 'itIT', 'Voglio un rimborso.', 'Voglio un rimborso.', 28153),
(143862, 'itIT', '$gBentornato:Bentornata;, $p!\n\nSono certo tu ti sia $ggoduto:goduta; il tempo passato alla Caduta Allegra per Famiglie di Volapiume.\n\nIn quanto membro, hai accesso a un numero illimitato di cadute lente dalla cima di questa divertente ziggurat. Fammi sapere quando dovesse servirtene un\'altra!\n\nTi ricordo che non sono previsti rimborsi!', '', 28153),
(143861, 'itIT', 'Unitevi alla Caduta Allegra per Famiglie di Volapiume!\n\nPer una piccola quota, avrete accesso a infinite cadute lente dalla cima di questa ziggurat. Sopravvivenza garantita!\n\nNiente rimborsi.', '', 28153),
(143860, 'itIT', 'I venti quassù sono più forti che ad Alto Monte. La nostra decisione di unirsi all\'Orda ci sta già ripagando.', '', 28153),
(143859, 'itIT', 'Torna alla tempesta e trova la pace. Scorri attraverso il santuario, così condivideremo la tua forza.', '', 28153),
(143858, 'itIT', '', 'Che città meravigliosa. Esplorare il mondo è così divertente!', 28153),
(143857, 'itIT', 'Ascolta la nostra chiamata. Le tue ignobili gesta oggi saranno perdonate.', '', 28153),
(143856, 'itIT', 'Quando te la senti, libera le anime all\'interno della campana.', '', 28153),
(143855, 'itIT', 'Rosaline, mi spiace, ma devi attendere. Abbiamo questioni più importanti della caccia a cui pensare.', '', 28153),
(143854, 'itIT', '', 'Ehi, Therold! Basta perdere tempo, ci serve la tua benedizione per andare a caccia!', 28153),
(143853, 'itIT', 'Torna presto, $p!', '', 28153),
(143852, 'itIT', 'Dieci punti per ogni sputata sui Troll del Sangue!', '', 28153),
(143851, 'itIT', 'Voli Voluttuosi di Volapiume! Dillo ai tuoi amici!', '', 28153),
(143850, 'itIT', 'È bello rivederti, $p. Buona caduta!', '', 28153),
(143849, 'itIT', 'Cerca di atterrare sul brutosauro!', '', 28153),
(143848, 'itIT', 'Cerca di atterrare in una cascata!', '', 28153),
(143847, 'itIT', 'Fai attenzione agli pterrordattili!', '', 28153),
(143846, 'itIT', 'Buon viaggio, $p.', '', 28153),
(143845, 'itIT', 'Aaargh!', '', 28153),
(143844, 'itIT', 'Per l\'Alleanza.', '', 28153),
(143843, 'itIT', 'Per l\'Orda!', '', 28153),
(143842, 'itIT', 'Stromgarde è caduta. Arrenditi mo\', Rogers, e la vita tua sarà salva.', '', 28153),
(143841, 'itIT', 'Sì, eccolo... il mio martello!', '', 28153),
(143840, 'itIT', 'Toc toc, Barbabronzea piccirillo. Ci sta qualcuno in casa?', '', 28153),
(143839, 'itIT', 'La Luce è ancora con me. Non cadrò così facilmente!', '', 28153),
(143838, 'itIT', 'Ammiraglio Rogers! Abbiamo preso d\'assalto la fortezza. Che ne è del tuo castigo ora, Paladino?', '', 28153),
(143837, 'itIT', 'Pensano che basti qualche soldato a cavallo per fermarci? Ah! Mostriamo loro la potenza dell\'Orda!', '', 28153),
(143836, 'itIT', 'La Roccaforte tiene bisogno di rifornimenti. Distruggete quei carri prima che si avvicinino troppo!', '', 28153),
(143835, 'itIT', 'Le nostre difese sono ancora molto deboli. Soldati dell\'Orda, tornate alla base e difendete la nostra posizione!', '', 28153),
(143834, 'itIT', 'Molto bene. Se vuoi la guerra, l\'avrai. Manda un battaglione di cavalieri ad annientarli!', '', 28153),
(143833, 'itIT', 'Il Circolo degli Elementi sta ora sotto il controllo dell\'Orda.', '', 28153),
(143832, 'itIT', 'La Nuova Fattoria è nostra... e con essa, anche i Cavalcalupi.', '', 28153),
(143831, 'itIT', 'L\'Armeria è pronta, cumpà.', '', 28153),
(143830, 'itIT', 'L\'Officina è pronta. I Demolitori si libereranno velocemente dell\'Alleanza!', '', 28153),
(143829, 'itIT', 'Macchine d\'Assedio, distruggeteli!', '', 28153),
(143828, 'itIT', 'Vi avevo avvisato, feccia dell\'Orda. Preparatevi a essere annientati!', '', 28153),
(143827, 'itIT', 'Tutte cheste terre appartenevano ai Troll prima ancora che l\'Alleanza sapesse dell\'esistenza nostra, Turalyon.', '', 28153),
(143826, 'itIT', 'Umpf. Ti starà perfettamente.', '', 28153),
(143825, 'itIT', 'Per ora dovrai farti bastare quei vestiti.', '', 28153),
(143824, 'itIT', 'Per prima cosa, ci serviranno legna e ferro per costruire na base dell\'Orda. Dovresti trovarne facilmente accà vicino.', '', 28153),
(143823, 'itIT', 'Stavo aspettando la stessa cosa, Muradin.', '', 28153),
(143822, 'itIT', 'Forse quei vestiti miglioreranno le tue abilità di raccolta.', '', 28153),
(143821, 'itIT', 'Puah! Ecco cosa penso della vostra ira, Turalyon!', '', 28153),
(143820, 'itIT', 'Queste terre sono dell\'Alleanza! Gli invasori dell\'Orda assaggeranno la nostra ira!', '', 28153),
(143819, 'itIT', 'Chist\'oggi, appartiene all\'Orda!', '', 28153),
(143818, 'itIT', 'Anni fa, tutta chesta terra apparteneva ai Troll.', '', 28153),
(143817, 'itIT', 'Ah, con piacere! Vi siete messi contro il Nano sbagliato!', '', 28153),
(143816, 'itIT', 'Muradin! Fatti vedere, codardo!', '', 28153),
(143815, 'itIT', 'Le nostre difese sono ancora deboli. Fermate quei carri prima che arrivino alla nostra base!', '', 28153),
(143814, 'itIT', 'Neanche lontanamente brutti come il tuo, Barbabronzea!', '', 28153),
(143813, 'itIT', 'Chiedo perdono, Esaminatrice.', '', 28153),
(143812, 'itIT', 'È un onore servirti, Esaminatrice.', '', 28153),
(143811, 'itIT', '', 'La battaglia è finita... e siamo sopravvissuti. Ateena la pagherà per la follia sua!', 28153),
(143810, 'itIT', '', 'Ammira il distruttore di Zuldazar! Spero che cercherai di fermarci... la sofferenza tua sarà gloriosa!', 28153),
(143809, 'itIT', '', 'Hai viaggiato tanto, solo per cadere di fronte alla furia del padrone!', 28153),
(143808, 'itIT', 'Lavorare per il Reliquiario è estenuante...', '', 28153),
(143807, 'itIT', 'Troppo facile! Fammi vedere che sai fare. Un po\' di legna in più fa sempre comodo.', '', 28153),
(143806, 'itIT', 'Farò come dici, Esaminatrice.', '', 28153),
(143805, 'itIT', 'Farò del mio meglio, Esaminatrice.', '', 28153),
(143804, 'itIT', 'Sono felice d\'essere d\'aiuto, Esaminatrice.', '', 28153),
(143803, 'itIT', '', 'La pelle tua sarà nu degno ricettacolo per il padrone mio!', 28153),
(143802, 'itIT', '', 'Poi toccherà all\'Orda. Pagherai per aver acciso Hir\'eek! Nun puoi scappare, ormai.', 28153),
(143801, 'itIT', '', 'Zuldazar cadrà... e il padrone mio sarà presto libero! I deboli Loa tuoi nun possono fermarlo!', 28153),
(143800, 'itIT', 'Naturalmente, Esaminatrice.', '', 28153),
(143799, 'itIT', 'Arrivo subito, Esaminatrice.', '', 28153),
(143798, 'itIT', '', 'Interessante... Baeloth, vieni qua e dimmi cosa vedi.', 28153),
(143797, 'itIT', '', 'Dove ti sei cacciato, Baeloth? Ho nuove nozioni che dovresti trascrivere.', 28153),
(143796, 'itIT', '', 'Mio caro Baeloth, vieni a vedere.', 28153),
(143795, 'itIT', '', 'Non c\'è mai tempo per riposarsi qua nel Reliquiario, Baeloth.', 28153),
(143794, 'itIT', '', 'Baeloth, non toccare i manufatti!', 28153),
(143793, 'itIT', '', 'Meraviglioso... Baeloth, vieni a vedere quanto è meraviglioso!', 28153),
(143792, 'itIT', '', 'Lo scudo di Hezrel è alzato! Rifugiati all\'interno!', 28153),
(143791, 'itIT', '', 'Baeloth, stai nuovamente sognando? Avrei bisogno del tuo aiuto.', 28153),
(143790, 'itIT', '', 'Baeloth, sii gentile e trascrivi tutto ciò che dirò.', 28153),
(143789, 'itIT', 'I Chigliatori hanno bisogno di molti rifornimenti per rimanere al massimo del loro potenziale! Il mio lavoro è tenere traccia e rifornire i magazzini, così come riparare attrezzi e ammennicoli!$b$b...$b$bRompono un sacco di attrezzi ogni giorno.$b$bNon si può certo dire che siano persone gentili.', '', 28153),
(143788, 'itIT', '', 'Ehi, posso parlarti un attimo? Avrei bisogno del tuo aiuto.', 28153),
(143787, 'itIT', '<< An event plays out where me and the laborers walk towards the causeway with cannons. >>', '', 28153),
(143786, 'itIT', 'Ti para quest\'osso. Ti para quest\'oss. T\'para quest\'oss. T\'para st\'oss. T\'paar st\'os. T\'paartos!', '', 28153),
(143785, 'itIT', 'Ci sono cascati tutti! È incredibile che abbiano creduto che io potessi essere così stupido da... Aspetta, come sarebbe a dire che possono sentirmi? Ma... io... T\'paartos!', '', 28153),
(143784, 'itIT', 'Lista delle cose che a T\'paartos non piacciono: serpenti, bambini cattivi, serpenti, caverne buie, serpenti... e gli insignificanti che infastidiscono T\'paartos.', '', 28153),
(143783, 'itIT', 'Certo, T\'paartos ha letto molti libri. Libri con poche parole e molti disegni, ma pur sempre libri.', '', 28153),
(143782, 'itIT', 'L\'insignificante non sta cercando di sfruttare la natura gentile di T\'paartos... vero?', '', 28153),
(143781, 'itIT', 'T\'paartos ha ancora un po\' paura dei serpenti.', '', 28153),
(143780, 'itIT', 'T\'paartos è onorato di essere un Forgialuce!', '', 28153),
(143779, 'itIT', 'Torna da T\'paartos quando vuoi.', '', 28153),
(143778, 'itIT', 'T\'paartos deve tornare al lavoro.', '', 28153),
(143777, 'itIT', 'T\'paartos ha molto da fare.', '', 28153),
(143776, 'itIT', 'T\'paartos ti rivedrà presto.', '', 28153),
(143775, 'itIT', 'T\'paartos.', '', 28153),
(143774, 'itIT', 'Fai in fretta, $n. Ci sono vite in gioco.', '', 28153),
(143773, 'itIT', 'T\'paartos è pronto!', '', 28153),
(143772, 'itIT', 'Che la Luce sia con te.', '', 28153),
(143771, 'itIT', 'Pericolo? T\'paartos non teme il pericolo!', '', 28153),
(143770, 'itIT', 'L\'insignificante ha bisogno di qualcosa da T\'paartos?', '', 28153),
(143769, 'itIT', 'T\'paartos saluta l\'insignificante.', '', 28153),
(143768, 'itIT', 'T\'paartos?', '', 28153),
(143767, 'itIT', 'T\'paartos!', '', 28153),
(143766, 'itIT', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t %s inizia a lanciare |cFFFF0000|Hspell:259610|h[Apocalisse Sanguinaria]|h|r! Trova un riparo!', '|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t %s inizia a lanciare |cFFFF0000|Hspell:259610|h[Apocalisse Sanguinaria]|h|r! Trova un riparo!', 28153),
(143765, 'itIT', '', 'Reagisci! Combatti! Le sofferenze tue alimentano il padrone!', 28153),
(143764, 'itIT', 'Dama Jaina? Direi più Damigiana! Modera? Direi più... mmm... be\', non ti aspetterai mica che mi vengano tutte al volo!', '', 28153),
(143763, 'itIT', 'Khadgar? Direi più Khaccar, no?', '', 28153),
(143762, 'itIT', 'Kirin Tor? Direi più Kirin Citrulliti, no?', '', 28153),
(143761, 'itIT', 'Se faceste semplicemente tutto quello che dico, invece di pensare a voi stessi, Azeroth sarebbe un posto migliore.', '', 28153),
(143760, 'itIT', 'Non sarebbe saggio opporsi a noi.', '', 28153),
(143759, 'itIT', 'Per Quel\'Thalas.', '', 28153),
(143758, 'itIT', 'Abbiamo superato grandi ostacoli.', '', 28153),
(143757, 'itIT', 'Costruiamo il nostro futuro sulle spalle delle tradizioni.', '', 28153),
(143756, 'itIT', 'Pensa al tuo lavoro.', '', 28153),
(143755, 'itIT', 'Non permettere che gli stranieri interferiscano.', '', 28153),
(143754, 'itIT', 'Rispetta le nostre tradizioni.', '', 28153),
(143753, 'itIT', 'Il sole eterno continua a guidarci.', '', 28153),
(143752, 'itIT', 'Che cosa vuoi da me?', '', 28153),
(143751, 'itIT', 'Io servo Lunargenta.', '', 28153),
(143750, 'itIT', 'Sono piuttosto occupato.', '', 28153),
(143749, 'itIT', 'Non sprecare risorse.', '', 28153),
(143748, 'itIT', 'Che c\'è?', '', 28153),
(143747, 'itIT', 'Il Pozzo Solare dev\'essere protetto.', '', 28153),
(143746, 'itIT', 'Accetta questo come ringraziamento.', '', 28153),
(143745, 'itIT', '', 'Progetti? Alla mia età? Quali progetti potrei mai avere?', 28153),
(143744, 'itIT', '', 'Pensavi che non avrei notato il modo in cui osservi le mie Guardaboschi Oscure? Ti suggerisco di tenere gli occhi, e i pensieri, a bada.', 28153),
(143743, 'itIT', '', 'Ho preso nota dei tuoi progressi. Pare che debba mandarti da Nathanos per un riaddestramento immediato.', 28153),
(143742, 'itIT', '', 'Sono io la tua preferita fra le sorelle Ventolesto... vero? Vero?', 28153),
(143741, 'itIT', '', 'La linfa vitale di Azeroth appartiene all\'Orda.', 28153),
(143740, 'itIT', 'Inizio a dubitare dell\'esistenza di una tale creatura!', '', 28153),
(143739, 'itIT', '', 'Ci riprenderemo ciò che è nostro.', 28153),
(143738, 'itIT', '', 'Col tempo, tutti serviranno l\'Orda.', 28153),
(143737, 'itIT', '', 'Rinfoltirò i ranghi dei Reietti. In un modo... o nell\'altro.', 28153),
(143736, 'itIT', '', 'Metteremo in ginocchio l\'Alleanza.', 28153),
(143735, 'itIT', '', 'Servi l\'Orda. Servi me.', 28153),
(143734, 'itIT', 'È bellissimo!', '', 28153),
(143733, 'itIT', '', 'Va\'. Ho molto da fare.', 28153),
(143732, 'itIT', '', 'Servimi bene e avrai una ricompensa.', 28153),
(143731, 'itIT', '', 'Ci sarà un nuovo futuro per l\'Orda.', 28153),
(143730, 'itIT', '', 'La nostra opera è solo all\'inizio.', 28153),
(143729, 'itIT', '', 'Salute a te.', 28153),
(143728, 'itIT', '', 'Fatti avanti.', 28153),
(143727, 'itIT', '', 'Confido che tu non intenda farmi perdere tempo.', 28153),
(143726, 'itIT', '', 'Dichiara il motivo della tua visita alla Capoguerra.', 28153),
(143725, 'itIT', '', 'Gli elementi di Zandalar hanno sofferto molto. Dobbiamo fermare gli Sciamani Oscuri che abusano del loro potere per fini egoistici.', 28153),
(143724, 'itIT', 'Mi chiamo Berthold e sono un grande appassionato di cavalli.\n\nSi dice che esista un esemplare magnifico di una creatura dalle sembianze equine a ovest di qui, in cima a un\'altura. Ho accettato il lavoro qui nella speranza di poterlo vedere almeno una volta nel mio tempo libero.\n\nCosa darei per ammirare una cosa del genere...', '', 28153),
(143721, 'itIT', 'Affermativo. Richiesta presa in carico dal Guardiano dei Titani Hezrel. Movimento in corso, area designata: Zul\'nazman.', '', 28153),
(143720, 'itIT', '', 'Hezrel, i Troll del Sangue si stanno radunando a Zul\'nazman. Se vuoi aiutarci, è lì che devi andare.', 28153),
(143719, 'itIT', 'Offrimi nu boccale, $PR.\n\nLa gente mia salvò chesto mondo mentre voi correvate a nascondervi come codardi tra le nebbie.\n\nMi devi da bere.', '', 28153),
(143718, 'itIT', 'Sistemi del Guardiano dei Titani Hezrel operativi al 50%. È necessario conservare energia per l\'epurazione dei Troll del Sangue.', '', 28153),
(143717, 'itIT', 'Chesta era la stanza di miscelatura mia. La famiglia reale intratteneva la nobiltà di tutto il mondo, e io soddisfacevo tutti loro con le bevande mie.\n\nOra è nu covo di sporchi stranieri e delli orrendi amici loro. Che disgrazia.', '', 28153),
(143716, 'itIT', 'Rispetto alcuni dei cartelli dei Goblin: neutrali e forti, pronti a fare tutto ciò che serve. Come li Zandalari... ma peggio, chiaramente.\n\nPerò voi Acqualorda siete na disgrazia. A braccetto con li Elfi e l\'Orda. Siete dei venduti.', '', 28153),
(143715, 'itIT', 'Assaggia il mio potere!', '', 28153),
(143714, 'itIT', 'Mi piace come funziona l\'Orda tua. Comandanti forti. Uniti da no scopo. Flusso di risorse costante.\n\nState reclutando?', '', 28153),
(143713, 'itIT', 'Sono pronto a contattare i nostri prossimi alleati.', 'Sono pronta a contattare i nostri prossimi alleati.', 28153),
(143712, 'itIT', '', 'Finalmente, la ridicola tregua tra Orda e Alleanza è quasi giunta al termine.$b$bL\'ora della guerra si avvicina.', 28153),
(143711, 'itIT', 'Mi ha sempre stupito che voi Lanciascura vi foste uniti all\'Orda. Troppo deboli per resistere da soli, immagino.\n\nCome sta Vol\'jin?', '', 28153),
(143710, 'itIT', 'Senti, $gElfo:Elfa;: chesta locanda nun è più mia, per cui nun devo far finta che tu mi piaccia.\n\nVattene dalla vista mia.', '', 28153),
(143709, 'itIT', 'Mi sembri $gassetato:assetata;. Serviti da bere e resta a chiacchierare nu poco.\n\nZuldazar esiste da tempi antichi assai. Nun scomparirà dall\'oggi al domani.', '', 28153),
(143708, 'itIT', 'Ho sentito che alcuni di voi si stanno dirigendo a Nazmir. Evita chell\'incarico, se puoi. Nulla di buono è mai uscito da chella palude da generazioni.', '', 28153),
(143707, 'itIT', 'Ho sentito che ci stanno più problemi del solito tra le sabbie di Vol\'dun. Sta\' accuort\' se vai da chelle parti.', '', 28153),
(143706, 'itIT', 'La gente mia fondò la civiltà all\'alba dei tempi, portando il resto di voi sulla schiena da allora.\n\nDimmi, $PR: cosa ha fatto la gente tua per essere ricordata?\n\nNun mi viene in mente niente.', '', 28153),
(143705, 'itIT', '<Salta sulle spalle di Hezrel per tornare alla Conca Nera.>', '<Salta sulle spalle di Hezrel per tornare alla Conca Nera.>', 28153),
(143704, 'itIT', 'Riparazione di G\'huun fallita. Non bisogna permettere ai Troll del Sangue di distruggere Zuldazar per impedire il rilascio di G\'huun.\n\nStruttura circondata dai Troll del Sangue. Il Guardiano dei Titani Hezrel metterà al sicuro $n e la Principessa Talanji.\n\nSaltate sulle spalle e abbassate la testa.', '', 28153),
(143703, 'itIT', 'Che schifo. Puzzi più di nu Troll del Sangue.\n\nSe chesta locanda fosse ancora mia, ti getterei nella monnezza.', '', 28153),
(143702, 'itIT', 'Hai sentito delle novità da fuori città?', '', 28153),
(143700, 'itIT', 'Gallywix è alla guida di alcune operazioni a Silitus. Raggiungilo immediatamente e, se dovessi incontrare qualche membro dell\'Alleanza, sbarazzatene.', '', 28153),
(143699, 'itIT', 'Abbiamo stabilito una base operativa a Silitus. Contatta i nostri agenti operativi sul posto e tieni gli occhi aperti in caso di attacco dell\'Orda.', '', 28153),
(143698, 'itIT', 'Voi Orchi sapete bere. Ve lo concedo.\n\nMa di\' alli amici Elfi tuoi di stare alla larga, capito?', '', 28153),
(143697, 'itIT', 'Alleria e Turalyon? Non dureranno. Voglio dire... non che ce l\'abbia con loro e voglia ostacolarli, ma... dobbiamo per forza parlarne?', '', 28153),
(143696, 'itIT', 'Posso capire il fatto che non apprezzi molto gli Elfi. Dopotutto, ci odiamo già abbastanza tra di noi.', '', 28153),
(143695, 'itIT', 'Lo ammetto, il viola non è mai stato il mio colore preferito. Però dicono che mi stia come una seconda pelle...', '', 28153),
(143694, 'itIT', 'Alto Elfo? Oh, ti prego. Chi mai vorrebbe essere un Alto Elfo quando si può avere un fascino tragico e minaccioso?', '', 28153),
(143693, 'itIT', 'Mantieni concentrazione e controllo.', '', 28153),
(143692, 'itIT', 'Non cedere ai sussurri.', '', 28153),
(143691, 'itIT', 'Accogli ogni possibilità.', '', 28153),
(143690, 'itIT', 'Le ombre vegliano su di te.', '', 28153),
(143689, 'itIT', 'Noi serviamo l\'Alleanza.', '', 28153),
(143688, 'itIT', 'La Luce non è l\'unica via.', '', 28153),
(143687, 'itIT', 'I Ren\'dorei dimostreranno il nostro valore.', '', 28153),
(143686, 'itIT', 'Ho molte cose da insegnarti.', '', 28153),
(143685, 'itIT', 'Vieni con la mente aperta.', '', 28153),
(143684, 'itIT', 'Ogni via è possibile.', '', 28153),
(143683, 'itIT', 'Noi accogliamo il potere, non lo temiamo.', '', 28153),
(143682, 'itIT', 'Le ombre sono al nostro servizio.', '', 28153),
(143681, 'itIT', 'Bal\'a dash, malanore.', '', 28153),
(143680, 'itIT', 'Salute, viandante.', '', 28153),
(143679, 'itIT', 'La mia benda non ha mai cambiato posizione! Chi mai sbaglierebbe una cosa così?', '', 28153),
(143678, 'itIT', 'Lavorare per Sylvanas presenta le sue... sfide. Essere morta l\'ha resa ancora più esigente. Ma... non dirle che te l\'ho detto.', '', 28153),
(143677, 'itIT', 'Campione della regina o no, potrei battere Nathanos quando mi pare e piace.', '', 28153),
(143676, 'itIT', 'Capelli come questi non si modellano da soli. Serve attenzione costante.', '', 28153),
(143675, 'itIT', 'Nessun sovrano regnerà più a Lunargenta.', '', 28153),
(143674, 'itIT', 'Siamo una nazione in ascesa.', '', 28153),
(143673, 'itIT', 'Al diel shala.', '', 28153),
(143672, 'itIT', 'Troviamo forza nell\'Orda.', '', 28153),
(143671, 'itIT', 'Ciò che faccio... lo faccio per Quel\'Thalas.', '', 28153),
(143670, 'itIT', 'Che la Luce del Pozzo Solare sia con te.', '', 28153),
(143669, 'itIT', 'Lunargenta prospererà di nuovo.', '', 28153),
(143668, 'itIT', 'La bellezza di Cantoeterno perdura.', '', 28153),
(143667, 'itIT', 'Il sole eterno continua a guidarci.', '', 28153),
(143666, 'itIT', 'La ricostruzione continua.', '', 28153),
(143665, 'itIT', 'Abbiamo fatto molti sacrifici.', '', 28153),
(143664, 'itIT', 'Sono onorato di servire come Reggente.', '', 28153),
(143663, 'itIT', 'Bal\'a dash, malanore.', '', 28153),
(143662, 'itIT', 'Ti do il benvenuto a nome di Lunargenta.', '', 28153),
(143651, 'itIT', 'Oh, credo di averne preso uno bello grosso!', '', 28153),
(143650, 'itIT', 'PLACEHOLDER SCENE - Hezrel reveals G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike.', 'PLACEHOLDER SCENE - Hezrel talks about G\'huun being an old god, being experimented upon, and reveals blood trolls want to destroy Zuldazar in order to free G\'huun. No way of fixing current containment, must protect Zuldazar. Ateena, blood troll matriarch, arrives, badly damages Hezrel, and prepares to strike', 28153),
(143649, 'itIT', '', 'Torna indietro, $R! La sua voce appartiene a me!', 28153),
(143648, 'itIT', '', 'C\'è un tale... potere... qui...', 28153),
(143647, 'itIT', '', 'Attento, Umbric. Le risposte a tali misteri spesso esigono un prezzo.', 28153),
(143646, 'itIT', 'Prendi questo cubo, per esempio. È un dispositivo antico, forse più della vita stessa su Azeroth. Pare sia chiuso a chiave, e non c\'è modo di aprirlo.', '', 28153),
(143645, 'itIT', 'Già! Anche noi crediamo che si possa sfruttare il Vuoto per difendere la vita, anziché consumarla. Abbiamo fatto progressi, Dama Ventolesto, ma molti misteri rimangono.', '', 28153),
(143644, 'itIT', '', 'Magari un\'altra volta. Vi stavamo cercando. Sappiamo del vostro esilio da Lunargenta e sentiamo di avere qualcosa in comune con voi.', 28153),
(143643, 'itIT', 'Io e la mia gente abbiamo saputo ciò che è successo su Argus. Come puoi immaginare, abbiamo un sincero interesse per il tuo rapporto con la Naaru oscura.', '', 28153),
(143642, 'itIT', 'Alleria Ventolesto?!? Ma come... Che onore inaspettato!', '', 28153),
(143641, 'itIT', '', 'Magistro Umbric! Sono Alleria Ventolesto.', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143640, 'itIT', '', 'Lì, poco più avanti. Dev\'essere Umbric.', 28153),
(143639, 'itIT', '', 'In base a questi appunti, credo di poter riaprire il passaggio di cui parla. Mmm, vediamo...', 28153),
(143638, 'itIT', '', '<Landing from jump: Total 3>', 28153),
(143637, 'itIT', 'Drathir credeva che questa fenditura nascondesse un antico oggetto di inimmaginabile potere. Forse è la chiave che ci permetterà di controllare le ombre.', '', 28153),
(143636, 'itIT', 'I suoi appunti dicevano che si trovava all\'interno di uno strappo tra le dimensioni. Non riuscì mai a trovare questo luogo... ma io sì. Presto la via da seguire ci sarà chiara!', '', 28153),
(143635, 'itIT', 'La sete di potere di Drathir lo condusse a cercare i frammenti di un antico mondo, ai confini del Vuoto stesso.', '', 28153),
(143634, 'itIT', '<Landing from jump: Total 3>', '', 28153),
(143633, 'itIT', '', 'Vieni. Dobbiamo raggiungere la Torre degli Albastella.', 28153),
(143632, 'itIT', 'Comunque, questo sapere può essere usato a fin di bene. Gran parte delle ricerche di Drathir furono condotte alla Torre degli Albastella. È lì che dobbiamo andare.', '', 28153),
(143631, 'itIT', 'Fu il tradimento di Drathir che permise ad Arthas di corrompere il Pozzo Solare... lasciando il nostro regno in rovina. Ora capisco perché Rommath si oppone ai nostri studi.', '', 28153),
(143630, 'itIT', 'A quanto pare non siamo i primi ad aver cercato di imbrigliare il Vuoto. Ho trovato gli appunti di uno studioso il cui stesso nome è una maledizione... Dar\'khan Drathir.', '', 28153),
(143629, 'itIT', '<Landing from jump: Total 3>', '', 28153),
(143628, 'itIT', '', 'A quanto pare abbiamo trovato degli appunti.', 28153),
(143627, 'itIT', '', '<Landing from jump: Total 3>', 28153),
(143626, 'itIT', 'Purtroppo, pare che le nostre ricerche siano arrivate a un punto morto. Credo che il sapere custodito nel Padiglione di Andilien potrebbe farle ripartire.', '', 28153),
(143625, 'itIT', 'Il Gran Magistro deve capire che questo potere è cruciale per la difesa di Lunargenta. I Sin\'dorei non saranno più preda del nemico!', '', 28153),
(143624, 'itIT', 'Gli esperimenti col Vuoto procedono bene. Siamo a un passo da una svolta... nonostante le ottuse proteste di Rommath.', '', 28153),
(143623, 'itIT', '<Landing from jump: Total 3>', '', 28153),
(143622, 'itIT', '', '<Landing from jump: Total 3>', 28153),
(143621, 'itIT', '<Distressed cry: Total 3>', '', 28153),
(143620, 'itIT', '<Landing from jump: Total 3>', '', 28153),
(143619, 'itIT', 'Hezrel, inizia le tue scansioni per trovare una soluzione dalla corruzione degli Dei Antichi che ha colpito Nazmir.', 'Hezrel, inizia le tue scansioni per trovare una soluzione dalla corruzione degli Dei Antichi che ha colpito Nazmir.', 28153),
(143618, 'itIT', 'Vediamo se questi pesci sono pronti a mordere!', '', 28153),
(143617, 'itIT', '', '<Landing from jump: Total 3>', 28153),
(143616, 'itIT', '', 'Questa foresta un tempo era fonte di gioia per me e le mie sorelle. Vederla in questo stato... mi riempie il cuore di dolore.', 28153),
(143615, 'itIT', 'Insieme, dimostreremo quanto si sbagliano.', '', 28153),
(143614, 'itIT', 'Ci vorrà un po\' di tempo per abituarci alla nostra nuova forma. Attendiamo il tuo ritorno, Dama Ventolesto... hai la nostra più sincera gratitudine.', '', 28153),
(143613, 'itIT', '', 'In cambio, giuro di aiutarvi nel vostro cammino. Informerò Re Wrynn della notizia. Al mio ritorno, daremo inizio all\'addestramento.', 28153),
(143612, 'itIT', 'Lunargenta ci ha voltato le spalle molto tempo fa. Oggi siamo rinati... ed è il momento di intraprendere un nuovo cammino. Da questo giorno, saremo fedeli all\'Alleanza.', '', 28153),
(143611, 'itIT', '', 'Percepisco i poteri che controllate. Sono... notevoli. Sareste dei grandi alleati per l\'Alleanza.', 28153),
(143610, 'itIT', 'La mia arroganza ci è quasi costata la vita. Ho giocato con poteri ben oltre il mio controllo. Se ci insegnerai, Alleria, ti seguiremo fino alla fine.', '', 28153),
(143609, 'itIT', '', 'Ho autorizzato la costruzione di un\'ambasciata a Orgrimmar. Con essa, altri potranno unirsi alla nostra causa. Vediamoci lì immediatamente.', 28153),
(143608, 'itIT', '', 'La temeraria guida dell\'Orda nella guerra contro la Legione ha lasciato una grave carenza nelle nostre schiere. I nemici non vedono l\'ora di prendere ciò che è nostro, ma non glielo permetteremo.', 28153),
(143607, 'itIT', '', 'Hai seguito le nostre operazioni a Silitus. Evidentemente l\'Alleanza sta facendo tutto il possibile per intralciare i nostri sforzi.', 28153),
(143606, 'itIT', 'È ora che l\'Alleanza accolga nuovi membri per perseguire la sua causa. Abbiamo stabilito un\'ambasciata a Roccavento a tal fine. Vediamoci lì.', '', 28153),
(143605, 'itIT', 'L\'Orda non si fermerà davanti a nulla pur di appropriarsi della linfa vitale di Azeroth. Temo che dopo la guerra con la Legione, le nostre forze non siano sufficienti a fermarla.', '', 28153),
(143604, 'itIT', 'Hai visto la devastazione di Silitus con i tuoi occhi. Sai bene ciò che c\'è in gioco.', '', 28153),
(143603, 'itIT', 'Troviamoci fuori dal Mastio Grommash. Mantieni il segreto... o le conseguenze saranno gravissime.', '', 28153),
(143602, 'itIT', 'Le informazioni si sono rivelate di estremo interesse per l\'Orda. È essenziale rimanere sempre un passo avanti rispetto ai nostri rivali.', '', 28153),
(143601, 'itIT', '$p! La Dama Oscura ti ha chiesto di incontrarmi a Orgrimmar.', '', 28153),
(143600, 'itIT', 'Troviamoci al Riposo del Leone. Non serve che ti dica che i dettagli di questo incontro devono rimanere segreti, vero?', '', 28153),
(143599, 'itIT', 'Abbiamo scoperto alcune... informazioni importanti che egli insiste tu debba sapere.', '', 28153),
(143598, 'itIT', 'Ascolta! Re Wrynn ti ha chiesto di incontrarmi a Roccavento.', '', 28153),
(143597, 'itIT', 'Porto anche chesto straniero che desidera parlare con te, possente Loa.', '', 28153),
(143596, 'itIT', '', 'I Nobili Oscuri sono un popolo saggio e potente. L\'antica conoscenza che possiedi si dimostrerà molto utile alla nostra causa.', 28153),
(143595, 'itIT', '', 'Ma basta con i convenevoli. Hai molto da dimostrare. Ovunque il tuo cammino ti porti, sappi che combatterai... per l\'Orda!', 28153),
(143594, 'itIT', '', 'Non preoccuparti, terrò nota dei tuoi progressi. In quanto Capoguerra, mi aspetto molto da te... e io ricompenso sempre coloro che mi servono bene.', 28153),
(143593, 'itIT', '', 'L\'Orda ha molti rivali in questo mondo. Alcuni ci chiamano nemici... altri emarginati. Ma è nell\'unità che noi troviamo forza... in barba a coloro che mettono in dubbio la nostra libertà.', 28153),
(143592, 'itIT', '', 'I Tauren di Alto Monte hanno grande forza e coraggio, qualità che ci serviranno nei giorni a venire.', 28153),
(143591, 'itIT', '', 'Ah, ecco la giovane promessa di cui si parla tanto. Mi dicono che hai grandi potenzialità... speriamo che le voci siano fondate.', 28153),
(143590, 'itIT', 'Buon viaggio. Che la Luce sia sempre con te.', '', 28153),
(143589, 'itIT', 'Gli Elfi del Vuoto si sono aggiunti solo di recente ai nostri ranghi, ma Alleria Ventolesto è una delle nostre più grandi eroine. Sotto la sua guida, il potere che controlli aiuterà la nostra causa.', '', 28153),
(143588, 'itIT', 'Vi scacceremo da queste terre!', '', 28153),
(143587, 'itIT', 'Buon viaggio. Anche se cammini tra le ombre, rimani un faro di speranza per tutti noi.', '', 28153),
(143586, 'itIT', 'Non vedo l\'ora di sapere dei tuoi progressi. Qualcosa mi dice che parleremo di nuovo molto presto.', '', 28153),
(143585, 'itIT', 'Sono tempi duri per Azeroth. Nei prossimi giorni, affronterai molte prove... e molti avversari. Sappi che non dovrai mai affrontare l\'oscurità senza aiuto, perché l\'Alleanza sarà sempre al tuo fianco.', '', 28153),
(143584, 'itIT', 'I Forgialuce si sono aggiunti solo di recente ai nostri ranghi, ma conosco bene i Draenei. So per certo che incarnerai il coraggio e la dedizione dell\'Armata della Luce.', '', 28153),
(143583, 'itIT', 'Ti do il benvenuto. Sono Re Anduin Wrynn e, in quanto nuovo membro dell\'Alleanza, volevo accoglierti personalmente.', '', 28153),
(143582, 'itIT', 'Ho bisogno di cure!', '', 28153),
(143581, 'itIT', 'Questo non è posto per voi!', '', 28153),
(143580, 'itIT', 'In quale oscuro e intrigante angolo del mondo ci ha inviato l\'Orda?\n\nVoglio sperare che la maggior parte delle strutture della mia nuova fazione siano più eleganti e pulite di questa.', '', 28153),
(143579, 'itIT', 'Perdonami, $p.\n\nVorrei davvero parlare con te, ma temo di non sentirmi molto bene.\n\nNon assaggiare il vino.', '', 28153),
(143578, 'itIT', '<Il Vinaio Thesnala fissa negli occhi il barista mentre versa lentamente il vino per terra.>', '', 28153),
(143577, 'itIT', 'Hai già provato il vino locale?\n\nDevi farlo assolutamente: il gusto è orrendamente incredibile.\n\nI Bardi potranno scrivere canzoni sul suo leggendario terribile retrogusto.\n\nDavvero un\'impresa epica su come rovinare una bevanda.', '', 28153),
(143576, 'itIT', 'Per ora, confido che gli Zandalari siano capaci di costruire edifici immensi e sgradevoli.\n\nNON confido siano capaci di fare il vino.', '', 28153),
(143575, 'itIT', 'Se non si è capaci di fare del buon vino, è meglio non farne del tutto.', '', 28153),
(143574, 'itIT', 'Offrimi un altro bicchiere di vino, così potrò sputare quell\'obbrobrio una seconda volta per terra.', '', 28153),
(143573, 'itIT', 'Osano chiamare vino questa brodaglia? Non mi stupisce che i Troll stiano abbandonando la città.', '', 28153),
(143572, 'itIT', 'Siamo liberi! Presto, andiamocene da qui!', 'Siamo liberi! Presto, andiamocene da qui!', 28153),
(143571, 'itIT', 'Quegli abomini di legno sembrano usciti da un incubo!', '', 28153),
(143569, 'itIT', 'Spero che... la mia assicurazione... mi copra...', 'Spero che... la mia assicurazione... mi coprirà...', 28153),
(143568, 'itIT', '', 'Pure se devastato, chesto posto mi sembra familiare...', 28153),
(143567, 'itIT', 'Datevi da fare, inutili sacchi di carne!', 'Datevi da fare, inutili sacchi di carne!', 28153),
(143566, 'itIT', 'Interno della struttura vuoto. Come designato, la Principessa Talanji è arrivata.', '', 28153),
(143565, 'itIT', 'È deciso. Dirigiamoci a Corlain!', '', 28153),
(143562, 'itIT', 'Troppo tardi. G\'huun non può essere contenuto. Tutti cadranno. Tutti moriranno.', '', 28153),
(143561, 'itIT', 'La fine incombe su di voi. G\'huun sarà libero. Azeroth sarà nostra.', '', 28153),
(143560, 'itIT', 'Metti li oggetti di valore tuoi nella sala di sicurezza e nun fermarti, $p.\n\nTi tengo d\'occhio...', '', 28153),
(143559, 'itIT', 'Sono tempi duri per Drustvar, ma dobbiamo riprenderci la nostra terra!', '', 28153),
(143558, 'itIT', 'Per Zandalar!', '', 28153),
(143557, 'itIT', 'Rezan! Ahahah, è ora di cacciare.', '', 28153),
(143556, 'itIT', 'Sì. Seguiremo gli ordini della tua scorta.', '', 28153),
(143555, 'itIT', 'Pa\'ku, Loa dei Venti, vola in cielo e stana gli eretici. Scopri gli obiettivi loro. Ci rivedremo al tempio.', '', 28153),
(143554, 'itIT', 'Gonk, Loa della Caccia, guida i seguaci tuoi al Tempio del Profeta e accidi tutti chelli che trovi. Fai uscire i nemici nostri.', '', 28153),
(143553, 'itIT', 'Fratelli e sorelle di Zandalar, è giunto il tempo di accidere i traditori che hanno giurato fedeltà a Zul.', '', 28153),
(143552, 'itIT', '', 'Il resto di noi si preparerà a raggiungere Corlain. Maresciallo, mi è sembrato di capire che tu abbia un piano.', 28153),
(143551, 'itIT', '', 'Sì, signora!', 28153),
(143550, 'itIT', '', 'Porta questa ricetta per creare del Fuoco Alchemico al Maestro Ashton a Collefalco. Lui saprà cosa fare.', 28153),
(143549, 'itIT', '', 'Fortunatamente, conosco un alchimista esperto a Collefalco, a sud. I boschi sono alquanto pericolosi, quindi dovrai passare dalle vecchie strade di montagna.', 28153),
(143548, 'itIT', '', 'Il tomo contiene la ricetta per creare del fuoco alchemico, ma credo che nessuno di noi sia abbastanza abile da farlo.', 28153),
(143547, 'itIT', '', 'Se vogliamo sconfiggere la congrega una volta per tutte, non ci servirà l\'argento, ma il fuoco.', 28153),
(143546, 'itIT', '', 'Grazie, signore! Come posso esservi utile, mia signora?', 28153),
(143545, 'itIT', 'Puoi fare affidamento sul Capit... ehm, volevo dire sull\'Inquisitrice Albachiara. Sono sicuro che svolgerà al meglio qualunque cosa le chiederai.', '', 28153),
(143544, 'itIT', '', 'Qualche raccomandazione, Maresciallo?', 28153),
(143543, 'itIT', '', 'Bene. Prima di partire, mi serve qualcuno che si occupi di un compito speciale per l\'Ordine.', 28153),
(143542, 'itIT', 'Ti sembra possibile che l\'Orda non abbia mai fondato un\'agenzia ufficiale per la telemanzia? Come fa la gente a viaggiare con un minimo di sicurezza? L\'idea di tutti quei portali casuali che fendono la realtà senza un appropriato ancoramento...\n\nBe\', in ogni caso sono felice di offrire una rete stabilizzata di teletrasporti per l\'Orda. Procediamo, per favore.', '', 28153),
(143540, 'itIT', 'La gente della mia città è tosta, ma questo mette alla prova il nostro coraggio.', '', 28153),
(143539, 'itIT', '', 'Annegate quesssti insssetti, figli miei. Rendetevi degni del mio orgoglio.', 28153),
(143537, 'itIT', 'Brgl! Brglrgl!', '', 28153),
(143536, 'itIT', 'Mrgl, mrglrglrgl! Mrrrg! Mrrrg!!!', '', 28153),
(143531, 'itIT', 'Apertura', 'Apertura', 28153),
(143530, 'itIT', 'Chesto è per te! Salta a bordo!', '', 28153),
(143529, 'itIT', 'Ci sta qualcosa che nun va sulla Artiglio di Rezan. Abbiamo piazzato na vedetta vicino all\'accampamento.', '', 28153),
(143523, 'itIT', 'Datemi il vostro oro, ho una riunione sui profitti economici fra cinque minuti!', '', 28153),
(143520, 'itIT', 'Sono pronto a ricevere l\'essenza sintetica di G\'huun.', 'Sono pronta a ricevere l\'essenza sintetica di G\'huun.', 28153),
(143519, 'itIT', 'Re Da\'ka! Ci ha trovati! Aiuto!', '', 28153),
(143518, 'itIT', 'Avete perso? Per mano loro? Patetico! Fate rapporto a Sepulcra per un riaddestramento immediato. A quanto pare dovrò ripartire dalle basi con voi...', '', 28153),
(143517, 'itIT', 'Siamo ben lontani da una vittoria elegante, ma almeno avete insegnato a quei cani dell\'Alleanza qual è il loro posto. Per l\'Orda!', '', 28153),
(143516, 'itIT', 'È... odore di Worgen quello che sto sentendo? È difficile esserne sicuri, con tutto questo tanfo di Alleanza.', '', 28153),
(143515, 'itIT', 'Fateli fuori! Non vorrete mica deludere la vostra Capoguerra, vero?', '', 28153),
(143514, 'itIT', 'E l\'Alleanza osa chiamarli \"soldati\"? Ridicolo! Quello lì riesce a malapena a brandire una spada!', '', 28153),
(143513, 'itIT', 'Fuoco! Non lasciate nessuno di quei bastardi in vita!', '', 28153),
(143512, 'itIT', 'Accidenti, c\'è ancora parecchia Azerite! Seguite la mappa e impossessatevene!', '', 28153),
(143511, 'itIT', 'Ci sono altre formazioni di Azerite in giro per quest\'isola! Controllate la mappa per trovarle!', '', 28153),
(143510, 'itIT', 'Ci siamo quasi. Non abbassate la guardia, serve più Azerite!', '', 28153),
(143509, 'itIT', 'Ah! Strappata dalle mani dell\'Alleanza! Ben fatto!', '', 28153),
(143508, 'itIT', 'Un risultato accettabile, ma abbiamo bisogno di altra Azerite!', '', 28153),
(143507, 'itIT', 'Prendete questi rifornimenti, se ne avete bisogno. Ma non perdete di vista il tesoro della Regina Banshee!', '', 28153),
(143506, 'itIT', 'I rifornimenti sono in arrivo. Sarà meglio che non finiscano nelle mani dell\'Alleanza!', '', 28153),
(143505, 'itIT', 'Laggiù... Azerite! Prendetela per la vostra Capoguerra. E se quelli dell\'Alleanza dovessero impedirvelo, seminate i loro corpi lungo tutta la spiaggia. Muovetevi!', '', 28153),
(143504, 'itIT', 'Fatevi dare un\'occhiata. Mmm... patetico! Perché non ci sono Guardaboschi Oscure tra di voi? Va be\', dovremo accontentarci.', '', 28153),
(143503, 'itIT', 'Nave dell\'Alleanza in arrivo! Quei cani ci sono alle calcagna. Be\', che aspettate? Ai posti di combattimento!', '', 28153),
(143502, 'itIT', 'La vostra missione è semplice. Recuperate ogni briciola di Azerite e non lasciate nulla all\'Alleanza. Confido che non sia troppo difficile da afferrare.', '', 28153),
(143501, 'itIT', 'Campioni dell\'Orda! Abbiamo trovato dei giacimenti di Azerite su una dannata isola al largo di Feralas. È vostro dovere recuperare il minerale in nome della Dama Oscura!', '', 28153),
(143500, 'itIT', 'Cacciateli! Quest\'isola è nostra!', '', 28153),
(143499, 'itIT', 'Per il Re! Per l\'Alleanza!', '', 28153),
(143498, 'itIT', 'Ah. Quelli dell\'Orda si credono astuti. Date loro una lezione!', '', 28153),
(143497, 'itIT', 'Fuoco! Eliminate quei guaritori!', '', 28153),
(143496, 'itIT', 'Sembrate dei tipi duri. Mmm... mi farebbe comodo un altro paio di Ladri... ma andrà bene lo stesso!', '', 28153),
(143495, 'itIT', 'Dannazione! L\'Orda è riuscita ad avere la meglio stavolta, ma giuro sul Riposo del Leone che alla fine riusciremo a vincere!', '', 28153),
(143494, 'itIT', 'Ben fatto, campioni! Re Wrynn sarà contento di sapere della vostra vittoria. Per l\'Alleanza!', '', 28153),
(143493, 'itIT', 'Rifornimenti in arrivo! Tutti vostri, campioni!', '', 28153),
(143492, 'itIT', 'Altre formazioni di Azerite! Trovatele sulla mappa e recuperatele!', '', 28153),
(143491, 'itIT', 'State facendo un ottimo lavoro. Ancora un po\' di Azerite e avremo finito!', '', 28153),
(143490, 'itIT', 'Avete tenuto l\'Azerite lontana dalle mani dell\'Orda. Ben fatto!', '', 28153),
(143489, 'itIT', 'Ottimo lavoro, eroi, ma ci serve altra Azerite!', '', 28153),
(143488, 'itIT', 'Eroi! Vi stiamo mandando dei rifornimenti. Non lasciate che cadano in mano all\'Orda!', '', 28153),
(143487, 'itIT', 'Abbiamo trovato altre formazioni di Azerite sull\'isola! Le posizioni sono evidenziate sulla vostra mappa.', '', 28153),
(143486, 'itIT', 'C\'è un ricco giacimento di Azerite sotto di noi. Andate laggiù e prendetene il più possibile. Se quei predoni dell\'Orda dovessero impedirvelo... Toglieteli di mezzo.', '', 28153),
(143485, 'itIT', 'Nave dell\'Orda in arrivo! Quella feccia deve averci seguiti fin qui. Ai posti di combattimento!', '', 28153),
(143484, 'itIT', 'Abbiamo condotto la nave verso il centro dell\'isola. Recuperate più Azerite possibile, è la chiave per la vittoria!', '', 28153),
(143483, 'itIT', 'Campioni, abbiamo individuato dei giacimenti di Azerite su un\'isola al largo delle coste di Feralas. Dobbiamo impossessarcene prima che lo faccia l\'Orda.', '', 28153),
(143482, 'itIT', '', 'Sarebbe un onore, Dama Liadrin. Oculeth conosce le coordinate per la capitale. Radunerò Silgryn e Valtrois e ti raggiungerò a Lunargenta.', 28153),
(143481, 'itIT', '', 'Sono certa che il Reggente sarà felice di venire a sapere del tuo interesse. Sei pronta a partire?', 28153),
(143480, 'itIT', '', 'È per questo che sono grata per il tuo invito a Lunargenta. Mi piacerebbe sapere se c\'è un posto per i Nobili Oscuri nella tua Orda.', 28153),
(143479, 'itIT', '', 'L\'Alleanza è troppo chiusa... isolata entro le sue stesse mura. La mia gente non resisterebbe di nuovo a una tale stagnazione.', 28153),
(143478, 'itIT', '', 'Anche i Sin\'dorei sono disprezzati da Tyrande e la sua cerchia, eppure, per anni la sua gente si è nascosta in eremi o all\'ombra degli alberi mentre la mia combatteva per salvare questo mondo.', 28153),
(143477, 'itIT', '', 'Pare che la \"saggezza di Elune\" l\'abbia condotta lontana dal legame che un tempo avevamo. Così sia.', 28153),
(143476, 'itIT', '', 'I Kaldorei combatteranno per assistere alla sconfitta della Legione e alla distruzione del Pozzo. Dopodiché... ci affideremo a Elune.', 28153),
(143475, 'itIT', '', 'Non intendiamo essere schiavi del Pozzo Oscuro. Vogliamo scacciare la Legione da Suramar e mettere fine all\'oppressione di Elisande.', 28153),
(143474, 'itIT', '', 'Arcanista Thalyssra, ricordo quando il tuo ordine partecipò alla Guerra degli Antichi. Come posso essere certa che non ci tradirai per diventare la prossima Elisande... o la prossima Azshara?', 28153),
(143473, 'itIT', '', 'Pensavo che i nostri fratelli di Kalimdor sarebbero stati nostri alleati, ma la loro arroganza e diffidenza hanno dimostrato il contrario.', 28153),
(143472, 'itIT', '', 'Devo ammetterlo, la prima volta che ho sentito parlare dell\'Orda, non credevo che avremmo mai trovato qualcosa in comune.', 28153),
(143471, 'itIT', '', 'È stato un onore per l\'Orda combattere al vostro fianco contro la Legione Infuocata, mia signora.', 28153),
(143470, 'itIT', '', 'Siamo in debito con entrambi per tutto questo. Non ce l\'avremmo mai fatta senza di voi.', 28153),
(143469, 'itIT', '', 'È bello vedere la tua città finalmente libera, Prima Arcanista.', 28153),
(143468, 'itIT', '', 'Salve, Dama Liadrin. Campione. Bentornati a Suramar. Sono felice di potervi ricevere in circostanze più piacevoli.', 28153),
(143467, 'itIT', '', 'Deludente, ma comprensibile... I Loa nun ti hanno dato la benedizione loro. Nun ti unirai a noi sulla Terrazza dei Prescelti.', 28153),
(143466, 'itIT', 'Hai viaggiato molto per farmi visita, giovane.$b$bHo parecchi libri sulla storia dei granchi, se è un argomento di tuo interesse.', '', 28153),
(143465, 'itIT', '', 'Resistente e imponente, puoi sfiancare i nemici e contrastare la tempesta. La forza tua verrà benedetta per difendere la città.', 28153),
(143464, 'itIT', '', 'Chesto è... davvero insolito. La forza tua sarà richiesta nei tempi a venire.', 28153),
(143463, 'itIT', '', 'Egoista e senza onore... ti conviene trovare n\'altra via.', 28153),
(143462, 'itIT', '', 'Interessante... Furtività e precisione per colpire dalle ombre. La sorpresa sarà l\'arma tua più forte.', 28153),
(143461, 'itIT', '', 'Capisco. Li attacchi tuoi sono veloci e letali. La pazienza tua verrà ricompensata.', 28153),
(143460, 'itIT', '', 'Guarda dentro di te. Mostrami come caccerai la preda tua. Userai saggezza, forza o qualcosa di completamente differente?', 28153),
(143459, 'itIT', '', 'Il richiamo del branco è forte in te. Abbraccia i legami di affinità e caccia con le sorelle e i fratelli tuoi.', 28153),
(143458, 'itIT', 'Lo senti anche tu? Io sento odore di cavolo.$b$b<Kronah si avvicina a te e ti annusa.>$b$bNo, non sei tu, ma qualcosa nei dintorni.$b$bDimmi, com\'è la tua calligrafia? Hai bisogno di qualche lezione? Che tu ci creda o no, sono un maestro scriba.', '', 28153),
(143457, 'itIT', 'Siamo sotto attacco!', 'Siamo sotto attacco!', 28153),
(143456, 'itIT', 'Mano alle armi, fratelli e sorelle!', 'Mano alle armi, fratelli e sorelle!', 28153),
(143455, 'itIT', 'Ci sono nemici tra di noi!', 'Ci sono nemici tra di noi!', 28153),
(143454, 'itIT', 'Intrusi! Alle armi!', 'Intrusi! Alle armi!', 28153),
(143452, 'itIT', 'Io felice.', '', 28153),
(143451, 'itIT', 'Forza!', '', 28153),
(143450, 'itIT', 'Abbiamo degli ordini da portare a termine!', '', 28153),
(143449, 'itIT', '', 'Per favore, nun distrarre i piccirilli.\n\nLi sto mettendo alla prova alla ricerca di segni di connessione con i Loa. Chelli benedetti da nu Loa riceveranno il pieno addestramento da Sacerdote e li onori e privilegi che ne conseguono.\n\nColoro che nun sono stati benedetti, terranno l\'opportunità di crescere come forti Guerrieri.\n\nColoro che falliscono entrambe le prove, nun tengono valore per noi. Probabilmente finiranno a rubare nel porto o chiedere l\'elemosina allo Zocalo.', 28153),
(143448, 'itIT', 'Io posso fare.', '', 28153),
(143447, 'itIT', 'Certo certosino.', '', 28153),
(143446, 'itIT', 'Lavoro, lavoro.', '', 28153),
(143445, 'itIT', 'Ci serve altra legna!', '', 28153),
(143444, 'itIT', 'Avrete tempo per riposare quando sarete morti. Ma fino ad allora, avete degli ordini da eseguire!', '', 28153),
(143443, 'itIT', 'Mi recherò al villaggio il più celermente possibile, prima che tutto questo svanisca. Forse mi rammentano ancora.', '', 28153),
(143442, 'itIT', 'Non credo riuscirei a vivere come prima. Non dopo tutto ciò che ho provato, anche se per un breve lasso di tempo.', '', 28153),
(143441, 'itIT', 'Da\'ka aveva ragione. Già percepisco la mia mente involvere a uno stadio primordiale.', '', 28153),
(143440, 'itIT', 'Salve. Ti interessano delle pergamene?$b$bO magari degli inchiostri esotici creati con le erbe più rare?', '', 28153),
(143439, 'itIT', 'Quei maledetti Goblin hanno il cervello piccolo. Dovrai ucciderne qualche centinaio prima che capiscano la lezione.', '', 28153),
(143438, 'itIT', 'Ah ah! Avete insegnato a quei Goblin cosa succede quando si intralciano i piani dei Nani Ferroscuro! Ottimo lavoro.', '', 28153),
(143437, 'itIT', 'Distruggete le loro macchine e i loro attrezzi! Schiacciate ogni piccoletto verdognolo che vi trovate tra i piedi!', '', 28153),
(143436, 'itIT', 'Questi Goblin stanno corrompendo l\'Azerite! Non possiamo permettergli di continuare!', '', 28153),
(143435, 'itIT', 'Ferroavverso è finalmente a portata di mano. Insegnate a quei Goblin cosa accade a chi ruba ai Ferroscuro!', '', 28153),
(143434, 'itIT', 'Chi qui? Chi fermato nebbie? Re Da\'ka uccide te!', '', 28153),
(143433, 'itIT', 'Per l\'Orda!', 'Per l\'Orda!', 28153),
(143432, 'itIT', '<La Piccola Tika guarda i maiali con sguardo famelico.>', '', 28153),
(143431, 'itIT', '<La Piccola Tika si dimena dalla felicità.>', '', 28153),
(143430, 'itIT', '', 'Chi è il cuccioletto mangiafacce preferito mio? Sei tu! Bello di mamma sua!', 28153),
(143429, 'itIT', '', 'Oh, è così bello vederti! $n... Grazie.', 28153),
(143428, 'itIT', '', 'Chella è Tika?', 28153),
(143427, 'itIT', '<La Piccola Tika trilla felice.>', '', 28153),
(143426, 'itIT', '', 'Altri... arriveranno...', 28153),
(143425, 'itIT', '', 'Il sole tramonta sull\'Impero degli Zandalari. I Senzafede si prenderanno quel poco rimasto!', 28153),
(143424, 'itIT', 'Ti farò annegare e squartare per questo!', 'Ti farò annegare e squartare per questo!', 28153),
(143423, 'itIT', '<La Piccola Tika alza il muso verso il vento. Emette un grido lamentoso.>', '', 28153),
(143422, 'itIT', 'Ti inginocchierai davanti alla tua regina, verme!', 'Ti inginocchierai davanti alla tua regina, verme!', 28153),
(143421, 'itIT', 'Lei... prenderà... anche te...', 'Lei... prenderà... anche te...', 28153),
(143420, 'itIT', 'La Casata dei Sacraonda regnerà su questa terra!', 'La Casata dei Sacraonda regnerà su questa terra!', 28153),
(143419, 'itIT', '', 'Grazie a entrambi per il vostro aiuto! $n, stai $gpronto:pronta; a raggiungere la caverna di Codatenebra per aiutare Ben\'jin, non appena questo coso inizierà a funzionare.', 28153),
(143418, 'itIT', '', 'Avrei potuto creare un dispositivo per effettuare una scansione della mente dei brutosauri ed eseguire un\'analisi. Tanto per dire.', 28153),
(143417, 'itIT', '', 'La scienza è l\'unica risposta, Jangalar. Non è mia intenzione denigrare i tuoi poteri, ma tutto questo folclore non è una valida alternativa alla logica dell\'Alchimia.', 28153),
(143416, 'itIT', 'Mostreremo a quei deboli Umani la forza dell\'Orda!', '', 28153),
(143415, 'itIT', 'Quegli Umani dovrebbero avere paura di noi, o presto le nostre lame si bagneranno del loro sangue!', '', 28153),
(143414, 'itIT', 'Per l\'Orda!', '', 28153),
(143413, 'itIT', 'Tornerò a Zuldazar... Nun preoccuparti per me, conosco la strada. Vieni a trovarmi la prossima volta che stai in città!', '', 28153),
(143412, 'itIT', 'Aspetta, Jin\'tiki. Piglia il raptor. Sembra... che tu gli piaccia più di me, dopotutto.', '', 28153),
(143411, 'itIT', 'Tenete gli occhi aperti! Non voglio che quegli Umani vengano a curiosare vicino ai nostri edifici!', '', 28153),
(143410, 'itIT', 'Più veloci!', '', 28153),
(143409, 'itIT', 'Pare che il lavoro nostro sia finito. È il momento per me di andare a Vol\'dun e pagare per i crimini miei.', '', 28153),
(143408, 'itIT', 'Se becco qualcuno a dormire sul lavoro, finisce in pasto ai lupi!', '', 28153),
(143407, 'itIT', 'Forza, continuate a generare risorse!', '', 28153),
(143404, 'itIT', 'La tua fine... si avvicina...', 'La tua fine... si avvicina...', 28153),
(143403, 'itIT', 'Com\'è... possibile...', 'Com\'è... possibile...', 28153),
(143402, 'itIT', '', 'Piglia le bestie tue e vai in città. Ti porterò nu cesto di cape di serpente quando avremo finito!', 28153),
(143401, 'itIT', 'Affronterai... l\'occhio... del ciclone...', 'Affronterai... l\'occhio... del ciclone...', 28153),
(143400, 'itIT', 'Tu... cadrai...', 'Tu... cadrai...', 28153),
(143399, 'itIT', 'Eccolo. È da qui che la nebbia esce dalle profondità.', '', 28153),
(143398, 'itIT', 'La mia anima... fluirà... nel mare.', 'La mia anima... fluirà... nel mare.', 28153),
(143397, 'itIT', 'Mi incammino... sotto le maree...', 'Mi incammino... sotto le maree...', 28153),
(143396, 'itIT', 'Hanno acciso il capo nostro! L\'intero villaggio è andato!', '', 28153),
(143395, 'itIT', 'Lo sfiato principale è qua dentro. Vieni, in fretta!', '', 28153),
(143394, 'itIT', 'Ritorno... agli abissi...', 'Ritorno... agli abissi...', 28153),
(143391, 'itIT', 'Persino le maree... recedono...', 'Persino le maree... recedono...', 28153),
(143390, 'itIT', 'Il suo potere scorre nelle mie vene!', 'Il suo potere scorre nelle mie vene!', 28153),
(143389, 'itIT', 'Accetta la tua fine!', 'Accetta la tua fine!', 28153),
(143388, 'itIT', 'I tentacoli del fato ti reclamano!', 'I tentacoli del fato ti reclamano!', 28153),
(143387, 'itIT', 'Di te non rimarrà che un guscio senza vita!', 'Di te non rimarrà che un guscio senza vita!', 28153),
(143386, 'itIT', 'Annegherai mentre la tua luce svanisce!', 'Annegherai mentre la tua luce svanisce!', 28153),
(143385, 'itIT', 'Nessuno può fermare la marea infinita!', 'Nessuno può fermare la marea infinita!', 28153),
(143384, 'itIT', 'Ascolta il richiamo degli abissi!', 'Ascolta il richiamo degli abissi!', 28153),
(143383, 'itIT', 'Il mare ti spazzerà via!', 'Il mare ti spazzerà via!', 28153),
(143382, 'itIT', 'Così cade... Re Da\'ka.', '', 28153),
(143381, 'itIT', '', 'Ma... mi era stato promesso... il potere...', 28153),
(143380, 'itIT', 'Crudele! Tu come candela, meglio quando consumata.', '', 28153),
(143379, 'itIT', '', 'Sei forte, ma cadrai dinnanzi alla congrega come tutti gli altri!', 28153),
(143378, 'itIT', '', 'Comunque sia, presto questa scoperta morirà con te. Servi, attaccate! Ahahah!', 28153),
(143377, 'itIT', '', 'Quindi ci hai trovato. Pensi di essere tanto in gamba...', 28153),
(143376, 'itIT', 'Ah! Quale sarebbe l\'uso dell\'intelligenza se non ottenere potere? Diventerò il re di Zandalar. Lo vedrai di persona, o morirai!', '', 28153),
(143375, 'itIT', 'Da\'ka, devi essere fermato. La nostra intelligenza non doveva esistere, e non doveva portarci alla guerra!', '', 28153),
(143374, 'itIT', 'Tsunga... hai portato un essere inferiore nelle sacre nebbie. Perché sei qui?', '', 28153),
(143373, 'itIT', 'Che succede quaggiù?', 'Che succede quaggiù?', 28153),
(143372, 'itIT', 'Ho visto la verità... negli abissi...', 'Ho visto la verità... negli abissi...', 28153),
(143371, 'itIT', 'Sanguino... la linfa della marea...', 'Sanguino... la linfa della marea...', 28153),
(143370, 'itIT', 'Vai, la sorgente di chesta nebbia è in chella caverna. Nun so dove stia Re Da\'ka. In fretta!', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143369, 'itIT', 'La magia del sangue è potente in chesto posto. Nun serve nu Taumaturgo per sentirla nell\'aria... sta dappertutto...', '', 28153),
(143368, 'itIT', '', 'Oh, che cosa ci fai qui, continentale?\n\nC\'è qualcosa che posso fare per te?', 28153),
(143367, 'itIT', 'Chi devo uccidere?', '', 28153),
(143366, 'itIT', 'Taz\'dingo!', '', 28153),
(143365, 'itIT', 'Per l\'Orda!', '', 28153),
(143364, 'itIT', 'Tempo di uccidere!', '', 28153),
(143363, 'itIT', 'Uccidere è facile.', '', 28153),
(143362, 'itIT', 'Nessuna pietà!', '', 28153),
(143361, 'itIT', 'Cadranno delle teste!', '', 28153),
(143360, 'itIT', 'Gloria all\'Orda!', '', 28153),
(143359, 'itIT', '', 'Gloria all\'Orda!', 28153),
(143358, 'itIT', '', 'Cadranno delle teste!', 28153),
(143357, 'itIT', '', 'Nessuna pietà!', 28153),
(143356, 'itIT', 'Non ci fermeremo... mai...', 'Noi non ci fermeremo... mai...', 28153),
(143355, 'itIT', 'La mia morte... non fermerà nulla...', 'La mia morte... non fermerà nulla...', 28153),
(143354, 'itIT', 'Abbiamo... già vinto...', 'Abbiamo... già vinto...', 28153),
(143353, 'itIT', '', 'Uccidere è facile.', 28153),
(143352, 'itIT', 'Stavo solo... eseguendo gli ordini...', 'Stavo solo... eseguendo gli ordini...', 28153),
(143351, 'itIT', 'Saggi delle Maree... beneditemi...', 'Saggi delle Maree... beneditemi...', 28153),
(143350, 'itIT', 'La mia vita... per il mare...', 'La mia vita... per il mare...', 28153),
(143349, 'itIT', 'Kul Tiras appartiene all\'oceano!', 'Kul Tiras appartiene all\'oceano!', 28153),
(143348, 'itIT', 'Osi metterti contro la Casata dei Sacraonda?', 'Osi metterti contro la Casata dei Sacraonda?', 28153),
(143347, 'itIT', 'Siamo implacabili come le profondità!', 'Siamo implacabili come le profondità!', 28153),
(143346, 'itIT', 'Tutti coloro che ci ostacolano moriranno!', 'Tutti coloro che ci ostacolano moriranno!', 28153),
(143345, 'itIT', 'La nostra flotta ti schiaccerà!', 'La nostra flotta ti schiaccerà!', 28153),
(143344, 'itIT', '', 'Tempo di uccidere!', 28153),
(143343, 'itIT', '', 'Vieni accà, cumpà!', 28153),
(143342, 'itIT', 'Kul Tiras non vale nulla senza di noi!', 'Kul Tiras non vale nulla senza di noi!', 28153),
(143341, 'itIT', '', 'Vieni accà, cumpà!', 28153),
(143340, 'itIT', 'Questa valle è nostra, verme!', 'Questa valle è nostra, verme!', 28153),
(143339, 'itIT', 'Nel nome dei Sacraonda!', 'Nel nome dei Sacraonda!', 28153),
(143338, 'itIT', '', 'Così tanti sauri morti... avevo allevato ognuno di loro. È come assistere alla morte dei guaglioni miei.$b$bLi uomini serpente pagheranno.', 28153),
(143337, 'itIT', 'Individuata corruzione nell\'area circostante la struttura. Richiesta azione immediata.', '', 28153),
(143336, 'itIT', 'Ripristino parziale completato. Avanzamento necessario per riparazione contenimento corruzione.', '', 28153),
(143335, 'itIT', 'Aggiornamento sistemi ausiliari. Si prega di attendere...', '', 28153),
(143334, 'itIT', 'Sai riparare l\'equipaggiamento?', 'Sai riparare l\'equipaggiamento?', 28153),
(143333, 'itIT', 'Il villaggio è perduto, ma dovranno passare sul freddo cadavere mio per pigliare la forgia.', '', 28153),
(143332, 'itIT', '', 'Per l\'Orda!', 28153),
(143331, 'itIT', '', 'Taz\'dingo!', 28153),
(143330, 'itIT', '', 'Chi devo uccidere?', 28153),
(143329, 'itIT', 'Sono lieto che gli innocenti siano al sicuro, ma c\'è ancora molto da fare.', '', 28153),
(143328, 'itIT', '', 'Ho solo sentito storie su Roccavento prima d\'ora. Esplorerò i suoi vicoli e le meraviglie che nasconde. Che le ombre ti guidino, $n.', 28153),
(143327, 'itIT', 'Che la Luce sia con te, $n. Ho intenzione di dare la caccia alla Legione su Azeroth per continuare la nostra eterna battaglia.', '', 28153),
(143326, 'itIT', 'Ovviamente non lo farò, però ci ho pensato. Per quasi un intero secondo!', '', 28153),
(143325, 'itIT', 'Devo ammetterlo, ho quasi considerato di darvi una parte dei profitti, dopo avervi visto all\'opera.', '', 28153),
(143324, 'itIT', 'Ottimo lavoro! Ora comincia la parte difficile... Firmare tutti questi fogli per ottenere la proprietà della miniera, nero su bianco.', '', 28153),
(143323, 'itIT', 'No, dico davvero, meglio distruggerli prima che danneggino i miei profitti.', '', 28153),
(143322, 'itIT', 'Obiettivo completato. Spostamento in corso. Consegna richiesta alla nuova posizione.', '', 28153),
(143321, 'itIT', 'Ah! Guarda come vengono schiacciati quegli idioti. Quegli elementali li stanno conciando per le feste!', '', 28153),
(143320, 'itIT', '<La Piccola Tika ringhia in modo minaccioso.>', '', 28153),
(143319, 'itIT', '<La Piccola Tika trilla spaventata!>', '', 28153),
(143318, 'itIT', 'Il mondo sanguina e voi allargate le sue ferite?!? Morite!', '', 28153),
(143317, 'itIT', 'Voglio vedere esplosioni, caos e atti di violenza indimenticabili! Insomma... quello che sapete fare meglio.', '', 28153),
(143316, 'itIT', 'Insegnate alla S.P.R. & Co. che non c\'è nulla in loro possesso che io non possa prendere.', '', 28153),
(143315, 'itIT', 'C\'è solo un piccolo problema. Non appartiene a me! È qui che entrate in gioco voi.', '', 28153),
(143314, 'itIT', 'Quindi è da qui che arriva tutta quell\'Azerite immessa nel mercato nero, eh? Un\'operazione niente male.', '', 28153),
(143313, 'itIT', '', 'Non so bene sia questo \"anatema dei worg\", ma... aspetta, cos\'è questo?', 28153),
(143312, 'itIT', 'Eri troppo buono per questo mondo, fratello. Mi assicurerò che tu riceva un funerale adeguato.', '', 28153),
(143311, 'itIT', 'Mi piace l\'odore del mojo al mattino!', '', 28153),
(143310, 'itIT', '', 'Rokhan mi ha detto che tieni esperienza in chesto genere di cose. Fa\' chello che puoi. Io starò accà ad aspettare la Squadra Gob.', 28153),
(143308, 'itIT', '', 'Teniamo bisogno di tutti li alleati possibili. Aiuta chesto guardiano appena puoi.', 28153),
(143307, 'itIT', 'Aiuto richiesto. Riparare Hezrel. Raggiungere interno della struttura vicina. Contenere tutta la corruzione di Nazmir.', '', 28153),
(143306, 'itIT', 'Enormi livelli di corruzione rilevati a Nazmir. Attivazione contenimento.', '', 28153),
(143305, 'itIT', 'Ho combattuto molte battaglie... ma nun ho mai visto nu mostro del genere... prima d\'ora...', '', 28153),
(143304, 'itIT', 'Nun mi piglierete mai vivo!', '', 28153),
(143303, 'itIT', 'Spero che Vol\'dun sia più sicura di chesto posto!', '', 28153),
(143302, 'itIT', 'No! Nun farlo! I raptor... mi mangeranno!', '', 28153),
(143301, 'itIT', 'Grazie, Zaluto. Forse in na vita diversa, saremmo stati grandi amici.', '', 28153),
(143300, 'itIT', 'Usa il Feticcio del Sangue su Zulajin per assorbire il potere suo e rispedirlo nella tomba!', '', 28153),
(143299, 'itIT', 'Nun temere, cumpà! Mi occuperò io del Capitano mentre ripulirai le rovine!', '', 28153),
(143298, 'itIT', 'Va bene! Ora mettiti addosso il camuffamento e piglia la chiave!', '', 28153),
(143297, 'itIT', 'Ti servirà nu travestimento per nun farti scoprire da Zulajin. Torna subito nun appena hai le provviste!', '', 28153),
(143296, 'itIT', 'Sono nu criminale, ma nun sono cattivo. Nun ti lascerò accà a morire!', '', 28153),
(143295, 'itIT', 'Grazie a te, se schiatterò... l\'onore mio rimarrà intatto...', '', 28153),
(143294, 'itIT', 'Qui, qui! Un brindisi $gal coraggioso campione:alla coraggiosa campionessa; che ci ha salvati tutti!', '', 28153),
(143293, 'itIT', '', 'Vai a Orgrimmar. Unisciti ai nostri alleati e forgia un nuovo futuro insieme a loro.', 28153),
(143292, 'itIT', '', 'Mentre ti avventuri per Azeroth, racconta a tutti del grande passato dei Nobili Oscuri... e mostra loro che non vivremo più nascosti agli occhi del mondo.', 28153),
(143291, 'itIT', 'Cosa sappiamo dei Nobili Oscuri?', 'Cosa sappiamo dei Nobili Oscuri?', 28153),
(143290, 'itIT', '', '$n, sono felice che tu sia qui. Dobbiamo convincere la Capoguerra ad allearsi con i Nobili Oscuri.', 28153),
(143289, 'itIT', 'Cosa sappiamo a proposito dei Tauren di Alto Monte?', 'Cosa sappiamo a proposito dei Tauren di Alto Monte?', 28153),
(143288, 'itIT', '', 'Ora tocca a noi dimostrare la forza e l\'onore che metteremo a disposizione dell\'Orda.', 28153),
(143287, 'itIT', 'Abbiamo molto in comune con i Tauren di Alto Monte. Credo che sarebbero gli alleati ideali per ciò che ci attende.', '', 28153),
(143286, 'itIT', '', 'Nun temere per Tsunga. Ci prenderemo cura di lui. Anche se nun ricorda più il nome suo.', 28153),
(143285, 'itIT', '', 'Era un tipo davvero grosso, vero? Ottimo lavoro!', 28153),
(143284, 'itIT', '', 'Che le stelle ti guidino, $p. Ho sentito voci interessanti riguardo le Alture di Colletorto. Probabilmente andrò a visitarle.', 28153),
(143283, 'itIT', '', 'Sei sicuro di chesto, Tsunga? Sai cosa perderai se $gchesto campione:chesta campionessa; dovesse diradare le nebbie?', 28153),
(143282, 'itIT', 'Io preparerò il rituale per liberare le anime. Troviamoci sulla costa poco a nord di qui.', '', 28153),
(143281, 'itIT', 'Ne sono pienamente cosciente. Ciò nonostante, so che bisogna fare la cosa giusta, indipendentemente dalle conseguenze.', '', 28153),
(143280, 'itIT', 'Prenderò un\'altra strada per la Gola. Ci incontreremo lì.', '', 28153),
(143279, 'itIT', 'Non spezzate i ranghi! I rinforzi sono in arrivo. Non possiamo lasciare che i Naga distruggano gli argini!', '', 28153),
(143278, 'itIT', 'Lascia che il tuo cuore dimentichi l\'odio.', '', 28153),
(143277, 'itIT', '', 'Ma i Sin\'dorei, gli Elfi del Sangue, ci hanno mostrato rispetto e comprensione. La loro amicizia ci ha dimostrato che altri condividono i nostri valori.', 28153),
(143276, 'itIT', '', 'Quando la nostra città affrontò il suo momento più cupo, gli eroi di Azeroth combatterono insieme a noi contro la Legione. Alcuni lo fecero con riluttanza.', 28153),
(143275, 'itIT', '', 'Ti dono le vesti tradizionali di Suramar. Indossale come ricordo del nostro antico passato... e del futuro che forgeremo insieme ai nostri alleati.', 28153),
(143274, 'itIT', 'Non serve che tu me lo ripeta due volte!', '', 28153),
(143273, 'itIT', '', 'Hai mostrato all\'Orda e a tutta la gente di Azeroth che i Nobili Oscuri possiedono la volontà e il coraggio di difendere il nostro mondo.', 28153),
(143272, 'itIT', 'Fatti strada verso la costa, dall\'altra parte del cantiere. Trova una giovane cadetta dei Marefiero, Taelia. Vai!', '', 28153),
(143271, 'itIT', '', 'Torna a Suramar e ti ringrazieremo per aver aiutato la nostra gente a riconquistare un posto in questo mondo.', 28153),
(143270, 'itIT', '', 'Tu sei tra i primi Shal\'dorei che si sono avventurati nell\'ignoto e hanno esplorato le terre di Azeroth. Ma ora è il momento di tornare a casa.', 28153),
(143269, 'itIT', 'Quei braccianti... sono tenuti prigionieri dalla magia dei Saggi delle Maree! Dobbiamo aiutarli.', '', 28153),
(143268, 'itIT', 'Siano ringraziate le maree, non tutti hanno perso la testa. Metà casata è impazzita!', '', 28153),
(143267, 'itIT', 'Mi farebbe comodo qualcosa di più leggero.', 'Mi farebbe comodo qualcosa di più leggero.', 28153),
(143266, 'itIT', '', 'Io perlustro più avanti. Ci vediamo sulla spiaggia.', 28153),
(143265, 'itIT', 'Ti vedo bene, $n.', '', 28153),
(143264, 'itIT', 'Abbiamo del lavoro da fare.', '', 28153),
(143263, 'itIT', 'Mi farebbe comodo qualcosa di più spesso.', 'Mi farebbe comodo qualcosa di più spesso.', 28153),
(143262, 'itIT', '', 'Alle armi!', 28153),
(143261, 'itIT', '', 'Per il Re!', 28153),
(143260, 'itIT', '', 'Addosso!', 28153),
(143259, 'itIT', '', 'Fino alla morte!', 28153),
(143258, 'itIT', '', 'Per Roccavento!', 28153),
(143257, 'itIT', '', 'Per l\'Alleanza!', 28153),
(143256, 'itIT', '', 'Nessuna ritirata!', 28153),
(143255, 'itIT', '', 'Me ne occuperò io!', 28153),
(143254, 'itIT', '', 'Di che corruzione sta parlando? Forse chesta cosa considera \"corruzione\" i Troll del Sangue.', 28153),
(143253, 'itIT', '', 'Tu lo sai che cos\'è? Credi che sarà disposto ad aiutarci?', 28153),
(143252, 'itIT', '', 'Che razza di vudù è chesto!?! Forse potrebbe aiutarci a fermare i Troll del Sangue e G\'huun...', 28153),
(143251, 'itIT', 'Me ne occuperò io!', '', 28153),
(143250, 'itIT', 'Nessuna ritirata!', '', 28153),
(143249, 'itIT', 'Per l\'Alleanza!', '', 28153),
(143248, 'itIT', 'Per Roccavento!', '', 28153),
(143247, 'itIT', 'Fino alla morte!', '', 28153),
(143246, 'itIT', 'Addosso!', '', 28153),
(143245, 'itIT', 'Per il Re!', '', 28153),
(143244, 'itIT', 'Alle armi!', '', 28153),
(143243, 'itIT', 'Uooo, il rilevatore sta impazzendo. Ci deve essere una grossa formazione d\'Azerite da qualche parte sull\'isola.', '', 28153),
(143242, 'itIT', 'Dobbiamo scoprire la fonte di questa profanazione.', '', 28153),
(143241, 'itIT', '', 'Lascia che quest\'armatura ti ricordi tutto ciò che hai fatto. Accettala con la mia gratitudine.', 28153),
(143240, 'itIT', 'Assolutamente.', '', 28153),
(143239, 'itIT', 'Cre-credi che anche le creature marine ne siano state influenzate?', '', 28153),
(143238, 'itIT', 'Te lo do io un altro \"presagio oscuro\". La baia pullula di prede dei Chigliatori.', '', 28153),
(143237, 'itIT', '<Tsunga dà un\'occhiata all\'ingresso della caverna, preoccupato.>', '', 28153),
(143236, 'itIT', '', 'Molti dubitavano che i Ren\'dorei potessero controllare il potere del Vuoto senza cadere vittima della sua influenza. Tu hai dimostrato che si sbagliavano.', 28153),
(143235, 'itIT', 'Le urla dell\'acqua sono più forti al largo della baia. Percepisco il tormento delle maree. Cattivi presagi, invero.', '', 28153),
(143234, 'itIT', '', 'Ora sei un\'arma formidabile nell\'arsenale dell\'Alleanza. Torna alla fenditura del Vuoto, così potremo onorare i tuoi risultati.', 28153),
(143233, 'itIT', 'Bene, diamoci da fare.', '', 28153),
(143230, 'itIT', 'Mi metto al lavoro sull\'addestramento. Tu vai a cercare Tagart, ha altro per te.', '', 28153),
(143229, 'itIT', 'Guardiano dei Titani Hezrel riavviato. Protocollo: contenere la corruzione entro Nazmir. Impossibile procedere: sistemi danneggiati.', '', 28153),
(143228, 'itIT', '', 'Nei tuoi viaggi per Azeroth, hai raggiunto una maestria totale sulle forze che cercano costantemente di controllarti.', 28153),
(143227, 'itIT', 'Ottimo esemplare. Vediamo se sa volare. Hyah!', '', 28153),
(143226, 'itIT', 'Oh, oh! Guarda cos\'ha portato il gatto! Incredibile!', '', 28153),
(143224, 'itIT', 'Dirò a Re Rastakhan che quando ci ripiglieremo le navi nostre, accenderemo le torri! Sarà il segnale alla ciurma mia che potranno tornare a casa!', '', 28153),
(143223, 'itIT', 'Il soggetto richiesto non è chiaro dalla foto, Wulferd non l\'accetterà.', 'Il soggetto richiesto non è chiaro dalla foto, Wulferd non l\'accetterà.', 28153),
(143222, 'itIT', 'Ti prego, prestami aiuto!', '', 28153),
(143221, 'itIT', 'No, i miei lavoratori! Io... li ho delusi!', '', 28153),
(143220, 'itIT', '', 'Aiuto! Il Comandante è stato colpito!', 28153),
(143219, 'itIT', 'Aiuto! Sono sotto attacco!', '', 28153),
(143218, 'itIT', 'La pagherete per questo!', '', 28153),
(143217, 'itIT', 'Questo tipo mi fa arruffare le piume!', '', 28153),
(143216, 'itIT', 'I miei premi assicurativi!', '', 28153),
(143215, 'itIT', 'Ma che cosa vi pago a fare?!? Venite qua fuori e mettetelo a posto!', '', 28153),
(143214, 'itIT', 'Assaporate un massacro di grosso calibro!', '', 28153),
(143213, 'itIT', 'Godetevi la potenza di trecento colpi al minuto!', '', 28153),
(143212, 'itIT', 'Sotto ai miei piedi! È lì che dovete stare.', '', 28153),
(143211, 'itIT', 'Mangia la polvere!', '', 28153),
(143210, 'itIT', '', 'Io vado in esplorazione, ci vediamo più avanti lungo la strada!', 28153),
(143209, 'itIT', 'Non mi avrete mai vivo! Ahahah!', '', 28153),
(143208, 'itIT', 'Avrei dovuto scegliere... il pacchetto... con sedile eiettabile...', '', 28153),
(143207, 'itIT', 'Metterò queste munizioni sul conto dei vostri parenti.', '', 28153),
(143206, 'itIT', '', 'Sfrutta i consigli che ti ho dato per mantenere il controllo. Diventa un\'arma dell\'Alleanza... anche se cammini sull\'orlo dell\'oscurità.', 28153),
(143205, 'itIT', 'Alcuni dubiteranno di te e metteranno in discussione la tua risolutezza, la tua abilità di controllare un potere che portò all\'oblio menti più deboli.', '', 28153),
(143204, 'itIT', '', 'Ma noi vediamo delle alternative. Ci sono molte possibilità, molte vie da seguire.', 28153),
(143203, 'itIT', '', 'Alcuni ti diranno che la Luce è l\'unica via, la sola arma in grado di fermare i nemici di Azeroth.', 28153),
(143202, 'itIT', 'Avete idea di quanti danni a proprietà avete causato?', '', 28153),
(143201, 'itIT', 'Ti do il benvenuto tra i Collorozzo!', '', 28153),
(143200, 'itIT', 'DELETE ME', '', 28153),
(143199, 'itIT', 'Vi distruggerò!', '', 28153),
(143198, 'itIT', 'Vi spiaccicherò!', '', 28153),
(143197, 'itIT', 'Vi ridurrò in polvere! Eheh!', '', 28153),
(143196, 'itIT', 'Peccato che nun sia riuscito a insegnargli la lezione più importante.', '', 28153),
(143195, 'itIT', 'Fai sapere al vecchio Rastakhan che tornerò a tempo debito. Oh, e grazie per l\'aiuto.', '', 28153),
(143193, 'itIT', 'Quando affonderò i miei artigli su Yazma e Zul, li farò sfracellare su una roccia!', '', 28153),
(143192, 'itIT', 'La nostra preda è vicina. Il sangue di Zul, Yazma e dei loro eretici verrà presto sparso. Sarà una grande caccia.', '', 28153),
(143191, 'itIT', 'Gloria per Pa\'ku!', 'Gloria per Pa\'ku!', 28153),
(143190, 'itIT', 'La nave sarà nostra!', 'La nave sarà nostra!', 28153),
(143189, 'itIT', 'Taz\'okun!', 'Taz\'okun!', 28153),
(143188, 'itIT', 'È solo una ferita superficiale. Sto bene...', '', 28153),
(143185, 'itIT', '', 'Brucerete tra le fiamme! Eheheh!', 28153),
(143184, 'itIT', '', 'Bruciate! Sì! Eheheh! Bruciate!', 28153),
(143183, 'itIT', '', 'Volete l\'Azerite? Eccovela servita!', 28153),
(143182, 'itIT', '', 'Oh oh, dovremo azzerare il nostro contatore dei \"giorni trascorsi dall\'ultima morte orribile\".', 28153),
(143181, 'itIT', 'Nulla vale tanto!', '', 28153),
(143180, 'itIT', '', 'L\'inesperienza porta alla morte!', 28153),
(143179, 'itIT', 'Per l\'Alleanza!', '', 28153),
(143178, 'itIT', '', 'È un onore servirti, maestà. Per l\'Alleanza!', 28153),
(143177, 'itIT', '', 'Oh, non avevi abbastanza qualifiche!', 28153),
(143176, 'itIT', 'Ci avete reso un grande servigio oggi, Dama Ventolesto. Avete entrambi la mia gratitudine.', '', 28153),
(143175, 'itIT', 'Ci vorrà del tempo perché questi Elfi del Vuoto guadagnino la fiducia di alcuni di noi, ma finché seguiranno i tuoi insegnamenti, saranno i benvenuti nell\'Alleanza.', '', 28153),
(143174, 'itIT', '', 'Avrei dovuto... farmi pagare il doppio...', 28153),
(143173, 'itIT', '', 'Io sarò la loro guida. Li addestrerò a controllare i sussurri dell\'ombra. In cambio, combatteranno per l\'Alleanza contro i suoi nemici.', 28153),
(143172, 'itIT', '', 'Re Wrynn, abbiamo trovato gli esiliati Sin\'dorei. Sono stati trasformati dal Vuoto, proprio come me, ma le loro menti e i loro cuori sono quelli di un tempo.', 28153),
(143171, 'itIT', '', 'Se vuoi un lavoro fatto bene... usa esplosivi più grandi!', 28153),
(143170, 'itIT', '', 'Sei tu la causa di tutto questo disordine?', 28153),
(143169, 'itIT', '', 'Ehi, voialtri! Dove pensate di andare?', 28153),
(143168, 'itIT', 'Intrusi?!? Scappate!', 'Intrusi?!? Scappate!', 28153),
(143167, 'itIT', 'Non so quale oscurità abbia ottenebrato la tua mente, sorella, ma non tormenterà più la nostra gente.', '', 28153),
(143166, 'itIT', 'L\'hai presa!', '', 28153),
(143165, 'itIT', 'Scappa!', '', 28153),
(143164, 'itIT', '', 'Non voglio più sentire lamentele sulle condizioni di lavoro!', 28153),
(143163, 'itIT', 'Non è sicuro qui. Dovete andarvene!', '', 28153),
(143162, 'itIT', 'Comunque, nun è nemmeno na bella isola!', '', 28153),
(143161, 'itIT', 'Siamo spacciati!', '', 28153),
(143160, 'itIT', 'Andatevene! Il vostro lavoro qui è finito.', '', 28153),
(143159, 'itIT', 'Si è liberato! Torna indietro!', '', 28153),
(143158, 'itIT', 'Fratelli e sorelle, ora siete liberi.', '', 28153),
(143157, 'itIT', '', 'Se vi lamentate, vuol dire che non state trattenendo il fiato! Quindi è colpa vostra se respirate gas tossici!', 28153),
(143156, 'itIT', 'Correte dalle vostre famiglie. Risolveremo noi la questione.', '', 28153),
(143155, 'itIT', 'Fuggite, sciocchi!', '', 28153),
(143154, 'itIT', 'Lascia che la tua anima si liberi dal suo guscio mortale e abbandonati alle acque.', '', 28153),
(143153, 'itIT', 'Ascolta l\'onda sacra e abbandonati alla pace.', '', 28153),
(143152, 'itIT', 'Non chiederti per chi si illumina il faro. Lo fa per te.', '', 28153),
(143151, 'itIT', '', 'Per l\'Orda!', 28153),
(143150, 'itIT', '', 'Per l\'Orda!', 28153),
(143149, 'itIT', '', 'Suramar è al fianco dell\'Orda!', 28153),
(143148, 'itIT', '', 'Per millenni Suramar è rimasta sola. Oggi diventate parte di qualcosa di più grande. Accetto il tuo giuramento, Thalyssra.', 28153),
(143147, 'itIT', '', 'È ora che i Nobili Oscuri trovino nuovi alleati tra i regni di Azeroth. Se ci accetterete, sarà un onore per noi mettere le nostre forze a vostra disposizione.', 28153),
(143146, 'itIT', '', 'L\'Orda incarna forza, determinazione e individualità. Tratti molto importanti anche per noi Shal\'dorei.', 28153),
(143145, 'itIT', '', 'Concordo, Prima Arcanista.', 28153),
(143144, 'itIT', '', 'È un onore, Capoguerra. Ho combattuto al fianco sia di Dama Liadrin che del Reggente. Il loro coraggio è un vanto per la vostra Orda.', 28153),
(143143, 'itIT', 'Non temere, fratello. Le onde ti giudicano per ciò che sei.', '', 28153),
(143142, 'itIT', 'La grande onda, dalle coste agli abissi, il tuo spirito monda.', '', 28153),
(143141, 'itIT', 'Il tuo spirito intrepido riposerà per sempre.', '', 28153),
(143140, 'itIT', 'Che gli abissi accolgano la tua anima consumata.', '', 28153),
(143139, 'itIT', 'Che la Madre delle Maree purifichi la tua carne corrotta.', '', 28153),
(143138, 'itIT', 'Le correnti ti guideranno.', '', 28153),
(143137, 'itIT', 'La terra vi consumerà!', '', 28153),
(143136, 'itIT', 'Acqua all\'acqua, cenere alla cenere, marea alla marea.', '', 28153),
(143135, 'itIT', 'Frantumazione!', '', 28153),
(143134, 'itIT', 'Il sangue di Azeroth scorre dentro di te!', '', 28153),
(143133, 'itIT', 'Non possiamo permettere che queste anime perdute vaghino ancora. Posso scambiare due parole con te?', '', 28153),
(143132, 'itIT', 'Scatena il tuo potere!', '', 28153),
(143131, 'itIT', 'Un po\' zuppo, ma ancora leggibile. Questi incantesimi ci saranno utili.', '', 28153),
(143130, 'itIT', 'Le nebbie degli oceani celano molto, ma questo segnalatore ci permetterà di raggiungerli.', '', 28153),
(143129, 'itIT', 'Risvegliatevi!', '', 28153),
(143128, 'itIT', '', '$gBenvenuto, figliolo:Benvenuta, figliola;. La vista può avermi abbandonato, ma Pa\'ku nun lo ha fatto.\n\nSiediti con me e porgi le domande tue alla grande Loa. Io risponderò al meglio delle mie possibilità.', 28153),
(143127, 'itIT', 'Bene, questa lama è ancora buona. Lama affilata, lama fidata.', '', 28153),
(143126, 'itIT', 'Non farai più del male a nessuno.', '', 28153),
(143125, 'itIT', 'Quanto vale il tuo sangue?', '', 28153),
(143124, 'itIT', '', 'Capoguerra Sylvanas Ventolesto, ti presento la Prima Arcanista Thalyssra di Suramar.', 28153),
(143123, 'itIT', '', 'Mi unirò agli altri e attenderò i tuoi comandi, continentale.', 28153),
(143122, 'itIT', '', 'Ho i miei dubbi... ma eseguirò gli ordini.', 28153),
(143121, 'itIT', '', 'Dunque il Maresciallo Reade pensa che tu sia la chiave per respingere la congrega?', 28153),
(143120, 'itIT', 'Colpisci più forte!', '', 28153),
(143119, 'itIT', 'Eheheh, era ora.', '', 28153),
(143118, 'itIT', 'Mettici un po\' di forza!', '', 28153),
(143117, 'itIT', 'Tira!', '', 28153),
(143116, 'itIT', 'Vieni, Winston. Sembra che abbiamo delle streghe di cui occuparci.', '', 28153),
(143115, 'itIT', 'Ancora qualche taglio profondo e ci siamo.', '', 28153),
(143114, 'itIT', 'Ce l\'ha quasi fatta! Ancora un po\'...', '', 28153),
(143113, 'itIT', 'Nuovi ordini, eh?', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(143112, 'itIT', 'Grazie di aver consegnato gli ordini. Farò rapporto a Dama Crestabianca al più presto.', '', 28153),
(143111, 'itIT', 'E io che pensavo che le loro storie fossero solo il frutto della fervida immaginazione di qualche storico...', '', 28153),
(143110, 'itIT', 'Non eravate altro che parassiti.', '', 28153),
(143109, 'itIT', 'Dunque è vero quanto si dice? L\'Ordine delle Braci è stato riformato.', '', 28153),
(143108, 'itIT', 'Le ferite... devono essere guarite...', '', 28153),
(143107, 'itIT', '', 'La mia lama è al tuo servizio.', 28153),
(143106, 'itIT', 'Avete messo piede nel mio dominio!', '', 28153),
(143105, 'itIT', '', 'Sebbene non creda molto in tutte queste diavolerie, è sempre meglio che restare qui ad aspettare che la congrega ci uccida.', 28153),
(143104, 'itIT', '', 'Quindi ci sei tu dietro a questo \"Ordine delle Braci\" di cui ho sentito parlare.', 28153),
(143103, 'itIT', '<Consegni gli ordini del Maresciallo Reade.>', '<Consegni gli ordini del Maresciallo Reade.>', 28153),
(143102, 'itIT', '', 'I costrutti cominciarono a scendere sul campo di battaglia. I guerrieri viventi scarseggiavano, quindi creò una nuova armata. Ma cosa potenziò le pietre?', 28153),
(143101, 'itIT', '', 'Cosa posso fare per te, $C?', 28153),
(143100, 'itIT', '', 'Questo è chiaramente Gorak Tul, il loro più grande capo. Ah! Sta eseguendo un rituale per creare i costrutti di pietra!', 28153),
(143099, 'itIT', '<Il Tenente Ondafiera fa un cenno con la testa, vedendoti arrivare.>', '', 28153),
(143098, 'itIT', 'Un bell\'esemplare, vero? La Casata dei Crestabianca è da tempo conosciuta per l\'esperienza nell\'arte della falconeria\n\nSfortunatamente, la maggior parte dei nostri uccelli è caduta vittima della maledizione della congrega. Winston è tra i pochi falchi dei Crestabianca a non essere stato influenzato di quella magia.\n\nTutto questo è davvero triste.', '', 28153),
(143097, 'itIT', '', 'Ma qui... hanno glorificato il massacro! I Kul Tirani non brandivano nemmeno delle armi!', 28153),
(143096, 'itIT', 'Qualcosa di malvagio si muove nei boschi, continentale. Di notte, l\'antico monumento dei Drust si illumina di un\'empia magia.\n\n Fossi in te, ci starei molto alla larga.', '', 28153),
(143095, 'itIT', '', 'Cosa c\'è, continentale?\n\nSe non ti serve nulla, sappi che avrei del lavoro da fare.', 28153),
(143094, 'itIT', 'ELIMINARE INTRUSO. RIPULIRE. RIPULIRE.', '', 28153),
(143093, 'itIT', 'RILASCIO CORRUZIONE IMMINENTE. AT... ATTIVAZIONE PROTOCOLLO DI SI... SI... SICUREZZA. IN... INTRUSO INDIVIDUATO.', '', 28153),
(143092, 'itIT', 'ERRORE... INTRUSIONE... RI-RILEVATA... SCANSIONE... CORRUZIONE.', '', 28153),
(143091, 'itIT', 'Uso di gas tossico approvato.', '', 28153),
(143090, 'itIT', 'Voltaggio aumentato.', '', 28153),
(143089, 'itIT', 'Sistemi attivati. Inizio sfollamento.', '', 28153),
(143088, 'itIT', '', 'Sembra che i Kul Tirani in questa stele fossero... civili? Solo marinai e contadini?', 28153),
(143087, 'itIT', '', 'Persino il loro capo è in fuga.', 28153),
(143086, 'itIT', '', 'AH! Qui rispondiamo ai loro attacchi!', 28153),
(143085, 'itIT', '', 'È interessante osservare come non si veda alcun costrutto sul campo di battaglia.', 28153),
(143084, 'itIT', 'La S.P.R. & Co. vi ringrazia per la vostra fedeltà. Avete optato per il pacchetto sfollamento élite.', '', 28153),
(143083, 'itIT', '', 'Qui è raffigurata un\'altra vittoria sui Kul Tirani. La grossa figura al centro è il loro leggendario capo, almeno credo.', 28153),
(143082, 'itIT', 'La S.P.R. & Co. vi ringrazia per la vostra fedeltà. Avete optato per il pacchetto sfollamento base.', '', 28153),
(143081, 'itIT', 'Dammi qualche mese e trasformerò questo posto in un albergo a sei stelle!', '', 28153),
(143080, 'itIT', 'Sei matta? Non si acquista MAI l\'estensione di garanzia!', 'Idiota! Non si acquista MAI l\'estensione di garanzia!', 28153),
(143079, 'itIT', 'Va bene, va bene! Aspetta... Mi conviene acquistare l\'estensione di garanzia?', 'Va bene, va bene! Aspetta... Mi conviene acquistare l\'estensione di garanzia?', 28153),
(143078, 'itIT', '', '', 28153),
(143077, 'itIT', 'Ci uccideranno!', 'Ci uccideranno!', 28153),
(143076, 'itIT', 'Non farmi fretta! Sto leggendo l\'accordo di licenza!', 'Non mettermi fretta! Sto leggendo l\'accordo di licenza!', 28153),
(143075, 'itIT', 'Presto, stanno arrivando!', 'Sbrigatevi! Stanno arrivando!', 28153),
(143074, 'itIT', 'Avevo solo bisogno di una piccola pausa.', '', 28153),
(143073, 'itIT', 'Calmati, ragazzina. Calmati.', '', 28153),
(143072, 'itIT', 'Errore-e... di si-sistema. Mo-mo-malfunziona-na-mento nel rilascio dei gettoni...', '', 28153),
(143071, 'itIT', 'Chi vuole volare un po\'? Tu vuoi volare? Facciamoci un giro in volo!', '', 28153),
(143070, 'itIT', 'Non mordere!', '', 28153),
(143069, 'itIT', 'Procedura di controllo dei danni iniziata.', '', 28153),
(143068, 'itIT', 'Il danneggiamento di questa unità viola le condizioni d\'uso.', '', 28153),
(143067, 'itIT', 'Bombardamento a tappeto!', 'Bombe in arrivo!', 28153),
(143066, 'itIT', 'Fate attenzione là sotto, carogne!', 'Attenzione là sotto, carogne!', 28153),
(143065, 'itIT', 'Ehi, tu. Torna al lavoro!', 'Ehi, tu. Torna al lavoro!', 28153),
(143064, 'itIT', 'Utilizzo della forza letale autorizzato.', '', 28153),
(143063, 'itIT', 'Assembramento di persone oltre il limite consentito. Disperdere.', '', 28153),
(143062, 'itIT', 'Servizi funerari disponibili a prezzi ragionevoli.', '', 28153),
(143061, 'itIT', 'Un altro cliente soddisfatto.', '', 28153),
(143060, 'itIT', 'La S.P.R. & Co. non è tenuta alla restituzione degli arti.', '', 28153),
(143059, 'itIT', 'L\'Orda si è difesa con successo dall\'assalto!', 'L\'Orda si è difesa con successo dall\'assalto!', 28153),
(143058, 'itIT', 'E disperdetevi! Quei cani dell\'Alleanza manderanno rinforzi contro di noi.', '', 28153),
(143057, 'itIT', '', 'Quando chesta nave arriverà al porto, io diventerò capitano! Ascolta bene le parole mie e impara a inchinarti!', 28153),
(143056, 'itIT', '', 'Chesti prigionieri nun sanno quanto sono fortunati! Presto staranno con Zul.', 28153),
(143055, 'itIT', '', 'Se vogliamo pigliare chesto porto, dovrai faticare più di così!', 28153),
(143054, 'itIT', 'Non posso... aiutarti... AAAARGH!', '', 28153),
(143050, 'itIT', 'No! Nun schiatterò! Nun è l\'ora mia!', '', 28153),
(143049, 'itIT', 'Come faceva... a saperlo...', '', 28153),
(143048, 'itIT', 'Chesto... nun può accadere!', '', 28153),
(143047, 'itIT', 'Sei forte... ma la vista mia lo è di più!', '', 28153),
(143046, 'itIT', 'Andatevene! Ve lo ordino!', '', 28153),
(143045, 'itIT', 'Miei prescelti! Il padrone vostro tiene bisogno di voi!', '', 28153),
(143044, 'itIT', 'Sarai tu a schiattare!', '', 28153),
(143043, 'itIT', 'Nun sai con chi hai a che fare, vecchio!', '', 28153),
(143042, 'itIT', 'Tieni ragione. Nun sarò IO a farlo.', '', 28153),
(143041, 'itIT', 'Sappiamo entrambi che nun schiatterò per mano tua. Nun puoi fermarmi.', '', 28153),
(143040, 'itIT', 'Brava ragazza. È quasi l\'ora di un dolcetto!', '', 28153),
(143039, 'itIT', 'Chesto gioco m\'ha stancato. Hai consegnato il messaggio. Ora affronterai il fato tuo.', '', 28153),
(143038, 'itIT', '<Zul ingoia la pozione in un sol colpo. Rabbrividisce per il cattivo gusto.>', '', 28153),
(143037, 'itIT', 'Deve essere la prima su cui hai posato gli occhi. Nessun ripensamento.', '', 28153),
(143036, 'itIT', 'I servitori suoi cercheranno di fermarti. Statt\' accuort\'!', '', 28153),
(143035, 'itIT', 'Mmm.', '', 28153),
(143034, 'itIT', 'Vieni accà. È giunta l\'ora.', '', 28153),
(143033, 'itIT', 'Bene. Ora scambia una delle pozioni di Vol\'jamba con chella che ti ho dato.', '', 28153),
(143032, 'itIT', 'Ripensandoci... spostala nu poco a sinistra.', '', 28153),
(143031, 'itIT', 'Ora metti l\'urna vicino all\'arco.', '', 28153),
(143030, 'itIT', 'Tieni le armi pronte fuori dall\'ambasciata. Agli Zandalari manca la forza e la volontà di mantenere il controllo. Hanno bisogno di una Capoguerra forte come la nostra.\n\nCosa posso fare per te?', 'Tieni le armi pronte fuori dall\'ambasciata. Agli Zandalari manca la forza e la volontà di mantenere il controllo. Hanno bisogno di una Capoguerra forte come la nostra.\n\nCosa posso fare per te?', 28153),
(143029, 'itIT', 'Se vedi qualcuno dell\'Alleanza nei paraggi, fammelo sapere. Me ne occuperò io.\n\nNel frattempo, cosa stai cercando?', 'Se vedi qualcuno dell\'Alleanza nei paraggi, fammelo sapere. Me ne occuperò io.\n\nNel frattempo, cosa stai cercando?', 28153),
(143028, 'itIT', 'Non c\'è niente da fare: gli Zandalari sì che sanno come costruire un\'ambasciata. E poi, questa città è enorme!\n\nTi sei $gperso:persa;?', 'Non c\'è niente da fare: gli Zandalari sì che sanno come costruire un\'ambasciata. E poi, questa città è enorme!\n\nTi sei $gperso:persa;?', 28153),
(143027, 'itIT', 'Non ho tempo da perdere. Parla in fetta.', 'Non ho tempo da perdere. Parla in fetta.', 28153),
(143026, 'itIT', 'Cosa ti serve, $PR?', 'Cosa ti serve, $PR?', 28153),
(143025, 'itIT', 'Gloria alla Capoguerra! Cerchi qualcosa?', 'Gloria alla Capoguerra! Cerchi qualcosa?', 28153),
(143024, 'itIT', 'Questa immensa ambasciata prova che gli Zandalari rispettano la forza della nostra Capoguerra. Devono anche temerla.\n\nCosa vuoi?', 'Questa immensa ambasciata prova che gli Zandalari rispettano la forza della nostra Capoguerra. Devono anche temerla.\n\nCosa vuoi?', 28153),
(143023, 'itIT', 'Quest\'umidità mi sta facendo sudare le ossa. Cosa posso fare per te?', 'Quest\'umidità mi sta facendo sudare le ossa. Cosa posso fare per te?', 28153),
(143022, 'itIT', 'Stiamo facendo carriera. Un giorno tutto questo sarà nostro.', '', 28153),
(143021, 'itIT', 'Ti paghiamo forse per poltrire?', '', 28153),
(143020, 'itIT', '', 'Forse il vero retaggio dei Ventolesto è la morte.', 28153),
(143019, 'itIT', '', 'Già. A volte mi sento come se fossi già morta due volte. La prima quando ci diedero per dispersi su Draenor e la seconda quando fui corrotta dall\'ombra della Naaru caduta.', 28153),
(143018, 'itIT', 'È inquietante vedere questi monumenti eretti in nostra memoria.', '', 28153),
(143017, 'itIT', '', 'È ora, Turalyon. Devo rivedere la mia terra con i miei stessi occhi... e sentire da Sylvanas in persona come abbia potuto indossare le vesti di Capoguerra.', 28153),
(143016, 'itIT', 'Ognuna di voi ha una via da seguire. Se la Luce esige che i vostri sentieri si incontrino, così sarà. Non serve forzare la mano del destino.', '', 28153),
(143015, 'itIT', 'Nessuno ti obbliga ad andare. Non devi vederla per forza.', '', 28153),
(143014, 'itIT', '', 'Come nessun altro, amore mio.', 28153),
(143013, 'itIT', 'Sei ansiosa. Lo nascondi bene... ma io ti conosco.', '', 28153),
(143012, 'itIT', 'So che ci sarà da lottare nei giorni a venire, ciò nonostante... non dimenticate mai il vostro dovere nei confronti di Azeroth!', '', 28153),
(143011, 'itIT', 'L\'energia che scorre nelle vostre armi... Non avevo mai visto niente di simile! Ma ricordate, ogni potere esige un prezzo.', '', 28153),
(143010, 'itIT', 'Ce l\'avete fatta! La spada di Sargeras si è assopita. Azeroth non è ancora guarita... ma le vostre azioni ci hanno fatto guadagnare tempo prezioso.', '', 28153),
(143009, 'itIT', 'Insieme, campioni! Per Azeroth!', '', 28153),
(143008, 'itIT', 'Unite il loro potere... e sradicate la corruzione dalla lama del Titano Oscuro!', '', 28153),
(143007, 'itIT', 'Le uniche cose in grado di contenere un tale potere... sono le potenti armi che brandite.', '', 28153),
(143006, 'itIT', 'La spada di Sargeras sta avvelenando la linfa vitale del mondo.', '', 28153),
(143005, 'itIT', 'Venite a Silitus... finché esiste ancora un mondo da salvare.', '', 28153),
(143004, 'itIT', 'So che le tensioni stanno crescendo... ma vi chiedo di unire le forze ancora una volta.', '', 28153),
(143003, 'itIT', 'Campioni, avete unito i vostri ordini e avete combattuto per cacciare la Legione da Azeroth.', '', 28153),
(143002, 'itIT', 'È in arrivo una tempesta. Se non troviamo un modo per guarire Azeroth... tutto il resto non avrà più importanza.', '', 28153),
(143001, 'itIT', 'Non so come mettere a posto le cose, e non credo ci sia qualcuno che sappia come fare. Ma dobbiamo provarci.', '', 28153),
(143000, 'itIT', 'Sin dal ritorno da Argus, i lamenti di Azeroth sono stati... insopportabili. Quanto dolore...', '', 28153),
(142999, 'itIT', 'È bello vedere una faccia conosciuta in questi tempi oscuri.', '', 28153),
(142998, 'itIT', 'Li stiamo ancora aspettando, Principessa. Teniamo anche delli indizi che potrebbero portarci al Loa, Krag\'wa.', '', 28153),
(142997, 'itIT', '', 'E chesto è ciò che è successo a Torga. Ci stanno novità riguardo ai rinforzi dell\'Orda?', 28153),
(142996, 'itIT', 'Abbiamo quasi finito con chesto, $n. Jammucenne un po\' più avanti.', '', 28153),
(142995, 'itIT', 'Non posso credere che quei mostri abbiano ucciso Torga...', '', 28153),
(142994, 'itIT', 'Bah, Torga è morto e non ho nulla da raccontare agli altri quando tornerò.', '', 28153),
(142993, 'itIT', 'Dov\'è Kisha? Pensavo sarebbe stata qui a impartire ordini...', '', 28153),
(142992, 'itIT', 'Va bene, andrò alla Conca Nera, vediamo cosa succederà...', '', 28153),
(142991, 'itIT', 'Be\', immagino che combattere un\'orda di Troll del Sangue sarebbe un\'ottima storia. Va bene, andrò alla Conca Nera.', '', 28153),
(142990, 'itIT', 'Hai fatto... COSA? Non posso perdermi questa storia, vado alla Conca Nera.', '', 28153),
(142989, 'itIT', 'D\'accordo, Kisha. Dirigiamoci alla Conca Nera e raduniamo tutta la nostra gente. L\'eroe si occuperà di coloro che abbiamo perso.', '', 28153),
(142988, 'itIT', '', 'Io mi dirigerò alla Conca Nera, tu occupati dei Tortolliani lungo il tragitto.', 28153),
(142987, 'itIT', '$n, ai cannoni, presto!', '', 28153),
(142986, 'itIT', 'Buona fortuna, $p. Per quanto mi riguarda, andrò a mettere alla prova le mie abilità a Valtetra. Per l\'Orda!', '', 28153),
(142985, 'itIT', 'La Respiro di Pa\'ku e la Artiglio di Rezan hanno fatto il giro del mondo. Aiutale a finire il viaggio fino a casa.', '', 28153),
(142984, 'itIT', 'Quando le navi sono tornate, ci stava n\'oscurità su di esse. Tenevo na brutta sensazione nella pancia mia.', '', 28153),
(142983, 'itIT', 'La Respiro di Pa\'ku è stata la casa mia per anni. Il core mio, come chesto molo, è vuoto da quando se ne è andata.', '', 28153),
(142982, 'itIT', '<Il ruggito di Anji il Tonante ti riempie di vigore.>', '', 28153),
(142981, 'itIT', 'Ehi! Sali a bordo! Il Capitano dice che la Respiro di Pa\'ku è in pericolo!', '', 28153),
(142980, 'itIT', '', 'Comandante, siamo qui per aiutare. Lo sbarramento non cederà oggi!', 28153),
(142979, 'itIT', '', 'Raggiungiamo lo sbarramento. Il Comandante Reed non ama aspettare gli altri.', 28153),
(142977, 'itIT', 'Non sei $gadatto:adatta; a questo posto!', '', 28153),
(142976, 'itIT', 'Folle pusillanime!', '', 28153),
(142975, 'itIT', 'Lurido verme spregevole!', '', 28153),
(142974, 'itIT', 'Vattene, infame!', '', 28153),
(142973, 'itIT', 'Ti concerò per le feste!', '', 28153),
(142972, 'itIT', 'Ti colpirò fin quando non piangerai!', '', 28153),
(142971, 'itIT', 'Con questa mano, ti strapperò i denti!', '', 28153),
(142970, 'itIT', 'Attenzione!', '', 28153),
(142969, 'itIT', '', 'Per l\'autorità conferitami dalla Casata dei Crestabianca, vi nomino Inquisitori dell\'Ordine delle Braci!', 28153),
(142968, 'itIT', '', 'Oggi diventate la speranza contro il nemico infinito.', 28153),
(142967, 'itIT', '', 'Oggi diventate la lama lucente che squarcia la malvagità.', 28153),
(142966, 'itIT', '', 'Fratelli e sorelle, oggi diventate il fuoco bruciante che spazza via l\'oscurità.', 28153),
(142965, 'itIT', '', 'Ah, ecco qui.', 28153),
(142964, 'itIT', '', 'Qui nel tomo dovrebbe esserci qualcosa di buono per un discorso. Vediamo...', 28153),
(142963, 'itIT', '', 'Grazie per avermi ceduto i tuoi uomini, Maresciallo. Ora cominciamo a sembrare un vero ordine!', 28153),
(142962, 'itIT', 'È da giorni che desidero vedere il Re. Pensavo fosse più interessato a ciò che i Goblin stanno facendo in cheste terre.', '', 28153),
(142961, 'itIT', 'Abbiamo molte truppe capaci qui, mia signora. Saranno degne reclute del tuo Ordine delle Braci.', '', 28153),
(142960, 'itIT', '', 'Maresciallo, potremmo aver trovato delle armi da usare contro la congrega. Ci serviranno soldati in grado di usarle.', 28153),
(142959, 'itIT', 'Nun tradirei mai il Loa o la città!', '', 28153),
(142958, 'itIT', 'Io venero Pa\'ku. La magia del sangue è proibita!', '', 28153),
(142957, 'itIT', 'Sto dicendo la verità. Nun so nulla delle reliquie del sangue!', '', 28153),
(142956, 'itIT', 'Sono innocente! Pietà!', '', 28153),
(142955, 'itIT', 'Nun contrabbanderei mai reliquie del sangue. La magia del sangue è malvagia!', '', 28153),
(142954, 'itIT', 'Nun ho mai visto nessuna reliquia del sangue!', '', 28153),
(142953, 'itIT', 'Nun so di cosa stai parlando!', '', 28153),
(142952, 'itIT', 'Nun ho fatto niente di sbagliato!', '', 28153),
(142951, 'itIT', 'Nun costringermi a pugnalarti ancora...', '', 28153),
(142950, 'itIT', 'A chi hai venduto le reliquie del sangue?', '', 28153),
(142949, 'itIT', 'Mi fai schifo, traditore.', '', 28153),
(142948, 'itIT', 'Ti farò soffrire, Pro\'ditor. Di te farò n\'esempio per tutti.', '', 28153),
(142947, 'itIT', 'Se confesserai, ti prometto na morte rapida.', '', 28153),
(142946, 'itIT', 'Sei fetente assai, Pro\'ditor. La magia del sangue sta accidendo la gente nostra!', '', 28153),
(142945, 'itIT', 'Sappiamo che hai contrabbandato le reliquie del sangue nella città nostra.', '', 28153),
(142944, 'itIT', 'Dicci come hai pigliato le reliquie del sangue, Pro\'ditor!', '', 28153),
(142943, 'itIT', 'Chesto miserabile ha contrabbandato delle reliquie del sangue nella città nostra.\n\nConfesserà e la punizione sua sarà esemplare.', '', 28153),
(142942, 'itIT', 'Nun ho fatto niente di sbagliato! Diglielo!', '', 28153),
(142941, 'itIT', '<Vai via.>', '<Vai via.>', 28153),
(142940, 'itIT', '<I resti strappati e insanguinati della nota criminale Teshyambi sono difficilmente riconoscibili. Sembra siano stati i raptor a fare questo.>', '<I resti strappati e insanguinati della nota criminale Teshyambi sono difficilmente riconoscibili. Sembra siano stati i raptor a fare questo.>', 28153),
(142939, 'itIT', 'So chi sei, Mojoba. Va\' a Vol\'dun e vivi in pace il tuo esilio.', 'So chi sei, Mojoba. Va\' a Vol\'dun e vivi in pace il tuo esilio.', 28153),
(142938, 'itIT', 'Chi sei? Che vuoi?', '', 28153),
(142937, 'itIT', 'Mi dispiace, ma sei stato esiliato a Vol\'dun per i tuoi crimini.', 'Mi dispiace, ma sei stato esiliato a Vol\'dun per i tuoi crimini.', 28153),
(142936, 'itIT', 'Shhh! Mi sto nascondendo dai raptor e da Zulajin. Devo trovare nu modo per tornare a Zuldazar.', '', 28153),
(142935, 'itIT', '', 'Ottimo lavoro... per qualcuno che voleva evadere.', 28153),
(142934, 'itIT', '', 'Ora che abbiamo la prigione sotto controllo e le chiavi in nostro possesso, possiamo iniziare a mettere al sicuro l\'Azerite e liberare gli ostaggi.', 28153),
(142933, 'itIT', '', 'A quanto pare Dama Bracescura avrà bisogno di un nuovo Sovrintendente.', 28153),
(142932, 'itIT', 'Fa\' attenzione! Parlo con te, scagliafiamme. Se una di queste munizioni d\'Azerite dovesse esplodere, qui saltiamo tutti in aria!', '', 28153),
(142931, 'itIT', 'State in guardia! Arrivano!', '', 28153),
(142930, 'itIT', '', 'Finiremo di mettere al sicuro i livelli inferiori mentre vi fate strada verso il Sovrintendente.', 28153),
(142929, 'itIT', '', 'Ben fatto. A quanto pare avete le cose sotto controllo.', 28153),
(142928, 'itIT', 'Una volta messe le mani sugli ostaggi del Sovrintendente, il riscatto ci farà nuotare nell\'oro!', '', 28153),
(142927, 'itIT', 'Forza, ragazzi! Sfondate quelle porte!', '', 28153),
(142926, 'itIT', '', 'Lo spero per te, o il primo incarico del tuo sostituto sarà quello di guardarti annegare insieme al resto di quella feccia.', 28153),
(142925, 'itIT', 'Le mie scuse, Dama Bracescura. Confido che i miei uomini risolveranno presto la questione.', '', 28153),
(142924, 'itIT', '', 'Korgus! Spiegami perché non hai allagato i livelli inferiori e annegato quegli inutili ratti!', 28153),
(142923, 'itIT', '', 'Puah! Avete dovuto strisciare attraverso questa roba per scappare? Cercate di starmi controvento.', 28153),
(142922, 'itIT', '', 'Quella creatura dev\'essere il motivo per cui il Sovrintendente non aveva molte pattuglie su questo lato dell\'isola. Ottimo lavoro.', 28153),
(142921, 'itIT', '', 'Metteremo al sicuro il perimetro mentre voi vi farete strada attraverso le fognature. Dovrebbero condurvi all\'interno della prigione.', 28153),
(142920, 'itIT', '', 'Secondo le nostre spie, le chiavi per accedere alle scorte di Azerite e alla zona degli ostaggi le tiene il Sovrintendente... attorno al collo.', 28153),
(142919, 'itIT', '', 'Abbassate la testa! Non ci hanno ancora visti.', 28153),
(142918, 'itIT', 'Devo proprio?', '', 28153),
(142917, 'itIT', 'Che vuoi?', '', 28153),
(142916, 'itIT', 'Pronto per lavoro.', '', 28153),
(142915, 'itIT', 'La nostra Caserma è stata distrutta!', '', 28153),
(142914, 'itIT', 'Ci servono rinforzi per vincere questa guerra.', '', 28153),
(142913, 'itIT', 'Torna al lavoro!', '', 28153),
(142912, 'itIT', 'Questo edificio non si costruirà da solo!', '', 28153),
(142911, 'itIT', 'Alza quel martello!', '', 28153),
(142910, 'itIT', '', '<Alleria assume un\'aria di sfida.>', 28153),
(142909, 'itIT', 'Mi hai salvato la vita!', 'Mi hai salvato la vita!', 28153),
(142908, 'itIT', 'Dovrei riuscire a trovare la strada. Grazie.', 'Dovrei riuscire a trovare la strada. Grazie.', 28153),
(142907, 'itIT', 'Ci attaccano senza requie. Grazie per il tuo aiuto.', 'Ci attaccano senza requie. Grazie per il tuo aiuto.', 28153),
(142906, 'itIT', 'Non dimenticherò mai il tuo coraggio.', 'Non dimenticherò mai il tuo coraggio.', 28153),
(142905, 'itIT', 'Credevo di morire là fuori!', 'Credevo di morire là fuori!', 28153),
(142904, 'itIT', 'Al villaggio farebbero comodo più eroi come te!', 'Al villaggio farebbero comodo più eroi come te!', 28153),
(142903, 'itIT', 'Vendica chi non abbiamo potuto salvare!', 'Vendica chi non abbiamo potuto salvare!', 28153),
(142902, 'itIT', 'Quei Naga sono dei mostri!', 'Quei Naga sono dei mostri!', 28153),
(142901, 'itIT', 'Questo gioiellino vi trapasserà la cassa toracica!', '', 28153),
(142900, 'itIT', 'Gli intrusi stanno passando attraverso le fogne!', '', 28153),
(142898, 'itIT', 'Questa pietra emana un silenzioso e potente canto. C\'è solo una persona in grado di udire la sua melodia. Possiamo solo sperare che non giunga mai su queste coste.', '', 28153),
(142897, 'itIT', 'Ho visto ciò che dovevo vedere. Questa pietra è maligna, deve essere distrutta.', '', 28153),
(142894, 'itIT', 'Dubito che ce le consegnerà di sua spontanea volontà, quindi dovrete prendere quell\'arma dal suo cadavere.', '', 28153),
(142893, 'itIT', 'Ho avvistato il nostro prossimo bersaglio a sud. Farete meglio a muovervi.', '', 28153),
(142892, 'itIT', 'È un peccato che distruggere quel vascello permetterà ai Kul Tirani di riorganizzarsi.', '', 28153),
(142891, 'itIT', 'La Dama Oscura sarà contenta dei vostri servigi.', '', 28153),
(142890, 'itIT', '', 'Sarà un piacere, Reggente. Quanto a te, ci rivedremo a Lunargenta.', 28153),
(142889, 'itIT', 'Eccellente! Dama Liadrin, torna a Orgrimmar e comunica alla Capoguerra la buona notizia.', '', 28153),
(142888, 'itIT', '', 'A nome dei Nobili Oscuri, accetto la tua offerta. Da questo giorno in avanti, Suramar combatterà per l\'Orda.', 28153),
(142887, 'itIT', 'L\'Orda ti offre questo, Prima Arcanista. Unitevi a noi. Le porte di Lunargenta saranno sempre aperte per voi.', '', 28153),
(142886, 'itIT', '', 'Suramar sarà sempre la nostra casa, ma alcuni di noi desiderano avventurarsi nel mondo e reclamare di nuovo il nostro posto su Azeroth. Per riuscirci, abbiamo bisogno di alleati.', 28153),
(142885, 'itIT', '', 'Traiamo forza dai nostri alleati... ma non abbiamo dimenticato ciò che siamo.', 28153),
(142884, 'itIT', '', 'Al contrario. Questo conflitto ha dimostrato la tua dedizione alla tua gente. Vedo che l\'Orda vi ha permesso di mantenere le vostre tradizioni, un elemento molto importante per noi.', 28153),
(142883, 'itIT', 'Mi spiace che tu abbia dovuto assistere a tutto questo, Thalyssra. Non è così che avevo pianificato la tua visita.', '', 28153),
(142882, 'itIT', '', 'Come desideri, Reggente. Per ora.', 28153),
(142881, 'itIT', 'Basta! Vattene immediatamente, Alleria. Incidente o no, la tua presenza rappresenta un pericolo per Quel\'Thalas. Tornatene a Roccavento, non sei più la benvenuta a Lunargenta.', '', 28153),
(142880, 'itIT', '', 'Non sarò fatta prigioniera nella mia stessa terra.', 28153),
(142879, 'itIT', 'Guardie! Fermate questa sabotatrice.', '', 28153),
(142878, 'itIT', 'Il Pozzo Solare è al sicuro. Il tuo aiuto è stato prezioso, Thalyssra. E anche il tuo, campione.', '', 28153),
(142877, 'itIT', 'State solo rimandando l\'inevitabile! Avrò il mio trofeo!', '', 28153),
(142876, 'itIT', '', 'Ora! Concentrate il vostro potere col mio!', 28153),
(142875, 'itIT', 'La porta si apre. Sì... questo andrà bene.', '', 28153),
(142874, 'itIT', '', 'Dicci cosa fare e noi ti presteremo aiuto.', 28153),
(142873, 'itIT', '', 'Posso chiudere la fenditura... ma mi servirà aiuto.', 28153),
(142872, 'itIT', 'Qualcosa sta cercando di aprire una fenditura nella sala. Se dovesse riuscire a passare, potremmo perdere il Pozzo Solare.', '', 28153),
(142871, 'itIT', 'Inizia a lanciare l\'incantesimo, Rikal.', 'Inizia a lanciare l\'incantesimo, Rikal.', 28153),
(142870, 'itIT', 'Prima o poi le maree cambieranno. Come sempre.', '', 28153),
(142869, 'itIT', 'La tua presa si sta allentando!', '', 28153),
(142868, 'itIT', '|TInterface\\Icons\\ABILITY_ROGUE_FANOFKNIVES:20|t %s si prepara a lanciare |cFFFF0000|Hspell:257785|h[Pugnali Scintillanti]|h|r! Nasconditi!', '', 28153),
(142867, 'itIT', 'Bal\'a dash, malanore.', '', 28153),
(142866, 'itIT', 'Ognuno di noi deve seguire il proprio cammino.', '', 28153),
(142865, 'itIT', 'La nostra gente rappresenta un nuovo futuro.', '', 28153),
(142864, 'itIT', 'Nessuna verità è scontata.', '', 28153),
(142863, 'itIT', 'L\'universo è colmo di misteri.', '', 28153),
(142862, 'itIT', 'Nuove opportunità sono dinnanzi a noi.', '', 28153),
(142861, 'itIT', 'Il passato è già scritto. Il futuro no.', '', 28153),
(142860, 'itIT', 'Shorel\'aran.', '', 28153),
(142859, 'itIT', 'La nostra gente non teme le ombre.', '', 28153),
(142858, 'itIT', 'Non esiste una sola verità.', '', 28153),
(142857, 'itIT', 'I sussurri non ci controllano.', '', 28153),
(142856, 'itIT', 'Ogni impulso deve essere tenuto sotto controllo.', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142855, 'itIT', 'Non temere il potere. Controllalo.', '', 28153),
(142854, 'itIT', 'Considera ogni possibilità.', '', 28153),
(142853, 'itIT', 'Il tuo comportamento infantile non basta a provocarmi.', '', 28153),
(142852, 'itIT', '\"Ricorda il Pozzo Solare\"? Oh, per piacere. Puoi fare di meglio.', '', 28153),
(142851, 'itIT', 'Se un portale per il nulla infinito dovesse aprirsi sotto i tuoi piedi per consumarti in mia presenza, sarebbe certamente uno sfortunato incidente. Ma gli incidenti capitano, dopotutto.', '', 28153),
(142850, 'itIT', 'Oh certo, prima una forza cosmica nota per indurre alla follia altera la mia forma fisica e di colpo divento un \"tipo sospetto\". Razzisti!', '', 28153),
(142849, 'itIT', 'Che cosa cerchi?', '', 28153),
(142848, 'itIT', 'Offro merci rare provenienti da regni lontani.', '', 28153),
(142847, 'itIT', 'Ogni cosa ha un prezzo... se si è disposti a pagarlo.', '', 28153),
(142846, 'itIT', 'Spero che l\'acquisto ti soddisfi.', '', 28153),
(142845, 'itIT', 'Grazie per la tua visita.', '', 28153),
(142844, 'itIT', 'Torna quando vuoi.', '', 28153),
