(142820, 'itIT', '', 'Bal\'a dash, malanore.', 28153),
(142819, 'itIT', 'Quella creatura vi sta bloccando la via di fuga. Dovrete ucciderla per raggiungere le barche sulla riva opposta.', '', 28153),
(142818, 'itIT', 'Dama Bracescura... ha un kraken?!?', '', 28153),
(142817, 'itIT', 'Pare che Bracescura ci abbia lasciato una comoda via d\'uscita. È ora di andarcene e lasciare Boralus alle fiamme.', '', 28153),
(142816, 'itIT', 'Questa bestia sta usando delle armi potenziate con l\'Azerite.', '', 28153),
(142815, 'itIT', 'Bal\'a dash, malanore.', '', 28153),
(142814, 'itIT', 'Segui il tuo cammino.', '', 28153),
(142813, 'itIT', 'Combattiamo per un nuovo futuro.', '', 28153),
(142812, 'itIT', 'Dubita di ogni cosa.', '', 28153),
(142811, 'itIT', 'L\'universo è colmo di misteri.', '', 28153),
(142810, 'itIT', 'Salute.', '', 28153),
(142809, 'itIT', 'Nuove porte si sono aperte per noi.', '', 28153),
(142808, 'itIT', 'Shorel\'aran.', '', 28153),
(142807, 'itIT', 'C\'è forza nell\'ombra.', '', 28153),
(142806, 'itIT', 'Siamo noi a decidere il nostro destino.', '', 28153),
(142805, 'itIT', 'I sussurri non mi controllano.', '', 28153),
(142804, 'itIT', 'Mantieni il controllo. Sempre.', '', 28153),
(142803, 'itIT', 'Il potere va dominato, non temuto.', '', 28153),
(142802, 'itIT', 'Quella nave è colma di Azerite. Massacra la ciurma e io penserò a trasportare il carico fuori dalla città.', '', 28153),
(142801, 'itIT', 'Il Vuoto offre infinite possibilità.', '', 28153),
