INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(142039, 'itIT', 'Morso del Demone è un attacco capace di accumulare Furia.', '', 28153),
(142038, 'itIT', 'Ora che sei a portata, è ora di scatenare i tuoi feroci attacchi.', '', 28153),
(142036, 'itIT', '', 'Usa Vilscatto per lanciarti verso il Manichino d\'Allenamento.', 28153),
(142035, 'itIT', 'Qual buon vento?', '', 28153),
(142034, 'itIT', 'Il fiume provvede a noi.', '', 28153),
(142033, 'itIT', 'Salute, viandante.', '', 28153),
(142032, 'itIT', '', 'Con incredibile agilità, scegli dove e quando affrontare i tuoi nemici.', 28153),
(142031, 'itIT', '', 'In quanto Cacciatrice di Demoni della Rovina, hai sacrificato molto per sfruttare il vilpotere dei demoni.', 28153),
(142030, 'itIT', '', 'In quanto Cacciatore di Demoni della Rovina, hai sacrificato molto per sfruttare il vilpotere dei demoni.', 28153),
(142029, 'itIT', 'Alto Monte resiste.', '', 28153),
(142028, 'itIT', 'In quanto Cacciatrice di Demoni della Rovina, hai sacrificato molto per sfruttare il vilpotere dei demoni.', '', 28153),
(142027, 'itIT', 'Usa Vilscatto per avventarti sul Manichino d\'Allenamento.', '', 28153),
(142026, 'itIT', 'Con incredibile agilità, scegli dove e quando affrontare i tuoi nemici.', '', 28153),
(142025, 'itIT', 'In quanto Cacciatore di Demoni della Rovina, hai sacrificato molto per sfruttare il vilpotere dei demoni.', '', 28153),
(142022, 'itIT', 'Pare che tu tenga già nu piano, principessa.', '', 28153),
(142021, 'itIT', '', 'Chesto \"G\'huun\" sta dando loro altro potere... più di quanto possiamo gestire. Dobbiamo rivedere i piani nostri.', 28153),
(142020, 'itIT', 'Tengono COSA?!? Avevi detto che erano solo dei selvaggi venuti dalla palude!', '', 28153),
(142019, 'itIT', 'Udite, udite! Ser Sacraonda ha condiviso le sue parole con i suoi fedeli!', 'Udite, udite! Ser Sacraonda ha condiviso le sue parole con i suoi fedeli!', 28153),
(142018, 'itIT', 'Il Caposquadra Scripps ha perso la testa. L\'hanno persa tutti quanti!', 'Il Caposquadra Scripps ha perso la testa. L\'hanno persa tutti quanti!', 28153),
(142017, 'itIT', 'Credevo di svenire!', 'Credevo di svenire!', 28153),
(142016, 'itIT', 'Non ci lasceranno scappare!', 'Non ci lasceranno scappare!', 28153),
(142015, 'itIT', 'Che le maree ti benedicano!', 'Che le maree ti benedicano!', 28153),
(142014, 'itIT', 'Ti sono riconoscente.', 'Ti sono riconoscente.', 28153),
(142013, 'itIT', 'I Mietitori si sono rivoltati contro di noi!', 'I Mietitori si sono rivoltati contro di noi!', 28153),
(142012, 'itIT', 'Le maree mi conservano!', 'Le maree mi conservano!', 28153),
(142011, 'itIT', 'Sapevo che il mare non ci avrebbe abbandonati!', 'Sapevo che il mare non ci avrebbe abbandonati!', 28153),
(142007, 'itIT', 'Un giorno... la... pagherai...', 'Un giorno... la... pagherai...', 28153),
(142006, 'itIT', 'Questa... è... insubordinazione...', 'Questa... è... insubordinazione...', 28153),
(142004, 'itIT', 'Ti... sollevo... dall\'incarico...', 'Ti... sollevo... dall\'incarico...', 28153),
(142003, 'itIT', 'Le mie bestie devono nutrirsi!', '', 28153),
(142002, 'itIT', 'Rompere!', '', 28153),
(142001, 'itIT', 'Restituite... il mio corpo... all\'oceano...', '', 28153),
(142000, 'itIT', 'È difficile... trovare... persone valide...', 'È difficile... trovare... un equipaggio decente...', 28153),
(141999, 'itIT', 'Avrai una nota di demerito... per questo...', 'Avrai una nota di demerito... per questo...', 28153),
(141998, 'itIT', 'Ohhh... maledizione...', 'Ohhh... maledizione...', 28153),
(141997, 'itIT', 'Niente sopravvive alle profondità.', '', 28153),
(141996, 'itIT', 'È questo... il meglio... che sai fare...?', 'È questo... il meglio... che sai fare...', 28153),
(141995, 'itIT', 'Inutile... verme...', 'Inutile... verme...', 28153),
(141994, 'itIT', 'Ti ho forse detto di fermarti?!?', 'Ti ho forse detto di fermarti?!?', 28153),
(141993, 'itIT', 'Ora sei polvere!', '', 28153),
(141992, 'itIT', 'Farò di te un esempio per tutti!', 'Farò di te un esempio per tutti!', 28153),
(141991, 'itIT', 'La pausa è finita, verme!', 'La pausa è finita, verme!', 28153),
(141990, 'itIT', 'Ti pentirai di avermi disobbedito!', 'Ti pentirai di avermi disobbedito!', 28153),
(141989, 'itIT', 'Osi uscire dai ranghi?!?', 'Osi uscire dai ranghi?!?', 28153),
(141988, 'itIT', 'Pagherai per la tua insubordinazione!', 'Pagherai per la tua insubordinazione!', 28153),
(141987, 'itIT', 'Fin troppo facile.', '', 28153),
(141986, 'itIT', 'Devo metterti in riga!', 'Devo metterti in riga!', 28153),
(141985, 'itIT', 'Torna al lavoro, verme!', 'Torna al lavoro, verme!', 28153),
(141984, 'itIT', 'Livelli di alimentazione critici.', '', 28153),
(141983, 'itIT', 'Riavvio del sistema richiesto.', '', 28153),
(141982, 'itIT', 'Gli abissi saranno la vostra tomba!', '', 28153),
(141981, 'itIT', 'Entità estranea rilevata al molo A.', '', 28153),
(141980, 'itIT', 'Unità disattivata.', '', 28153),
(141979, 'itIT', 'Protocollo di mietitura fallito.', '', 28153),
(141978, 'itIT', 'A cinque tese sotto, le vostre ossa staran sepolte!', '', 28153),
(141977, 'itIT', 'Integrità strutturale allo 0%%!', '', 28153),
(141976, 'itIT', 'Perdita rilevata.', '', 28153),
(141975, 'itIT', 'Sistemi disattivati.', '', 28153),
(141974, 'itIT', 'Entità ostile rilevata.', '', 28153),
(141973, 'itIT', 'Attivazione contromisure.', '', 28153),
(141972, 'itIT', 'Avvio sequenza di mietitura.', '', 28153),
(141971, 'itIT', 'Allarme intrusi.', '', 28153),
(141970, 'itIT', 'Utente non autorizzato.', '', 28153),
(141969, 'itIT', 'Sequenza d\'attacco avviata.', '', 28153),
(141968, 'itIT', 'Ingaggio.', '', 28153),
(141967, 'itIT', 'Minaccia rilevata.', '', 28153),
(141966, 'itIT', 'Artiglieria! Eliminate questa feccia dal mio campo di battaglia!', '', 28153),
(141965, 'itIT', 'Cannoni! Fuoco sulla mia posizione!', '', 28153),
(141964, 'itIT', 'Nessuno può sopravvivere alle maree!', '', 28153),
(141963, 'itIT', 'Preparati a morire!', '', 28153),
(141962, 'itIT', 'Ti farò a pezzi!', '', 28153),
(141961, 'itIT', 'Assaggiate l\'acciaio!', '', 28153),
(141960, 'itIT', 'Ah! Proprio quello che mi aspettavo dall\'Orda.', '', 28153),
(141959, 'itIT', 'Impara la disciplina!', '', 28153),
(141958, 'itIT', 'Il mare rivendicherà le tue ossa!', '', 28153),
(141957, 'itIT', 'Non... vi meritate... la vittoria...', '', 28153),
(141956, 'itIT', 'La vostra fine è prossima, feccia dell\'Orda!', '', 28153),
(141955, 'itIT', 'Per Boralus!', '', 28153),
(141954, 'itIT', 'Il nemico ci ha circondati!', '', 28153),
(141953, 'itIT', 'Attenzione!', '', 28153),
(141952, 'itIT', 'Da questa parte!', '', 28153),
(141951, 'itIT', 'Di qua!', '', 28153),
(141950, 'itIT', '', 'Indossa quest\'armatura con orgoglio. L\'Armata della Luce sarà sempre onorata di averti tra le sue schiere.', 28153),
(141949, 'itIT', '', 'Durante le tue avventure, hai portato la Luce nei luoghi più oscuri. Hai mostrato all\'Alleanza cosa significa essere un Forgialuce.', 28153),
(141948, 'itIT', '', 'Vieni, raggiungimi sulla Vindicaar. È il momento di ricompensare il tuo impegno!', 28153),
(141947, 'itIT', '', 'I tuoi servigi all\'Alleanza sono stati davvero notevoli. Io stessa non avrei saputo fare di meglio. Be\', forse sì... ma non di molto.', 28153),
(141946, 'itIT', 'Salva in arrivo!', '', 28153),
(141945, 'itIT', 'Eheheh, bruciate!', '', 28153),
(141944, 'itIT', '', 'È un onore per me donarti l\'armatura della nostra gente. Dovunque ti conduca il destino, essa ti servirà come ricordo delle tue radici.', 28153),
(141943, 'itIT', '', 'Anche nei momenti più cupi, hai dimostrato forza e coraggio. Grazie a te, l\'Orda ha compreso che cosa significa essere un Alto Monte.', 28153),
(141942, 'itIT', 'Adesso ti aggancio!', '', 28153),
(141941, 'itIT', '', 'Ora Totem del Fulmine ti richiama a casa. È il momento di ringraziarti per tutto ciò che hai fatto per noi.', 28153),
(141940, 'itIT', '', 'Hai girovagato in lungo e largo per Azeroth, portando grande onore ad Alto Monte.', 28153),
(141939, 'itIT', 'Vieni qui!', '', 28153),
(141938, 'itIT', 'Ora tocca a te!', '', 28153),
(141937, 'itIT', 'Non mi scappi...', '', 28153),
(141936, 'itIT', 'Banchetterò col vostro sangue!', '', 28153),
(141935, 'itIT', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Argus!', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Argus!', 28153),
(141934, 'itIT', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Gelidanima!', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Gelidanima!', 28153),
(141933, 'itIT', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Sha!', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Sha!', 28153),
(141932, 'itIT', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Terre del Fuoco!', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Terre del Fuoco!', 28153),
(141931, 'itIT', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Crepuscolo!', 'La Fotocamera S.E.L.F.I.E. ha sbloccato il Filtro Crepuscolo!', 28153),
(141930, 'itIT', 'Ah! Non lasciate marcire... il mio corpo...', '', 28153),
(141929, 'itIT', 'Quanti bocconi succulenti...', '', 28153),
(141928, 'itIT', 'Altro cibo per gli oceani!', '', 28153),
(141926, 'itIT', 'Questo è quello che chiamo un ottimo filetto!', '', 28153),
(141925, 'itIT', 'Vi farò a pezzi!', '', 28153),
(141924, 'itIT', '<Il pescatore osserva ossessivamente l\'acqua, borbottando fra sé e sé. Le sue labbra sono secche, le sue mani sanguinanti e il suo corpo è pieno di tagli e graffi, probabilmente causati dagli uccelli famelici che infestano la spiaggia.\n\nSembra che non si sia mosso da quel punto per giorni interi.\n\nÈ chiaramente sotto l\'effetto della magia della congrega ma, a differenza degli altri che hai incontrato finora, riesce a muoversi e parlare, anche se sembra noncurante della tua presenza.>', '', 28153),
(141923, 'itIT', 'Come agnelli al macello!', '', 28153),
(141922, 'itIT', '', 'Rimani fedele ai tuoi valori. Se mai dovessi sentire nostalgia di casa, sappi che Alto Monte sarà sempre qui ad attenderti.', 28153),
(141921, 'itIT', '', 'Vai a Orgrimmar. Incontra i nostri nuovi alleati e scopri le loro motivazioni... per cosa combattono.', 28153),
(141920, 'itIT', '', 'Oggi inizierai un nuovo viaggio. Tu sarai la nostra voce nelle terre oltre la montagna.', 28153),
(141919, 'itIT', '', 'È tempo di cambiare le cose.', 28153),
(141918, 'itIT', '', 'Per molte generazioni, la nostra gente ha considerato le Isole Disperse la propria casa. Sappiamo poco della Azeroth che esiste oltre le nostre coste.', 28153),
(141917, 'itIT', 'Ho sentito che ci sono delle spie! Cosa devo fare?', 'Ho sentito che ci sono delle spie! Cosa devo fare?', 28153),
(141916, 'itIT', '', 'Cammina sempre nella Luce.', 28153),
(141915, 'itIT', '', 'La tua missione inizia a Roccavento. Esplora il mondo di Azeroth e impara a conoscere la gente e i luoghi che abbiamo giurato di difendere.', 28153),
(141914, 'itIT', '', 'Ma non dobbiamo abbassare la guardia. Una guerra finisce e un\'altra comincia. Questa è la vita di un soldato.', 28153),
(141913, 'itIT', '', 'Ora, per la prima volta da eoni, abbiamo la possibilità di camminare sotto un cielo libero dalla follia della Legione... e di sentire di nuovo la terra sotto gli zoccoli.', 28153),
(141912, 'itIT', '', 'Per migliaia di anni, i Forgialuce hanno combattuto i demoni nella Distorsione Fatua. La Xenedar era l\'unica casa che conoscevamo.', 28153),
(141911, 'itIT', 'Ah, ottimo tempismo. Ora potrai vedere con i tuoi occhi cosa significa diventare un Forgialuce. Procedi pure, Fareeya.', '', 28153),
(141910, 'itIT', '', 'Sai quanto adoro i tuoi discorsi, ma potresti aspettare? Stavamo giusto per sottoporre questi iniziati alle prove.', 28153),
(141909, 'itIT', 'Decisamente. È ansioso di avere l\'Armata della Luce al fianco dell\'Alleanza. Raduna le nostre forze, capitano, e farò l\'annuncio.', '', 28153),
(141908, 'itIT', '', 'Non ti aspettavo di ritorno così presto, Gran Esarca. Immagino che il tuo incontro con il re sia andato bene.', 28153),
(141905, 'itIT', 'Addington! Per tutti gli abissi...', '', 28153),
(141902, 'itIT', 'Torna nel Vuoto che ti ha generato!', '', 28153),
(141901, 'itIT', 'Picco del Tuono sarà libera dalla tua presenza!', '', 28153),
(141900, 'itIT', 'Ahahah! È bello poter scatenare la mia mazza ancora una volta!', '', 28153),
(141899, 'itIT', 'Scacceremo la tua ombra da Mulgore!', '', 28153),
(141898, 'itIT', 'Per l\'Alleanza!', '', 28153),
(141897, 'itIT', 'Per l\'Alleanza!', '', 28153),
(141896, 'itIT', 'Spesso mi chiedo se abbia fatto bene.', '', 28153),
(141895, 'itIT', 'Sono entrambe qualità che ci serviranno nei giorni a venire. Grazie per averli convinti a unirsi alla nostra causa.', '', 28153),
(141894, 'itIT', 'Ho combattuto al fianco di questi Draenei nella Distorsione Fatua per oltre un millennio. Non troverai soldati più abili né più leali.', '', 28153),
(141893, 'itIT', 'La forza dei Forgialuce è benvenuta tra noi, Gran Esarca.', '', 28153),
(141892, 'itIT', 'Re Wrynn. L\'Armata della Luce ha giurato di difendere l\'Alleanza.', '', 28153),
(141891, 'itIT', 'Ser Sacraonda ora ha vietato tali rituali. Si sta concentrando sulla costruzione di nuove navi.', '', 28153),
(141890, 'itIT', 'Quando esamino la superficie dell\'acqua, incontro una tempesta oscura che offusca la mia visione.', '', 28153),
(141889, 'itIT', '', 'Sai dove si trova la flotta?', 28153),
(141888, 'itIT', 'La Casata dei Sacraonda è cambiata da quando la flotta non ha fatto ritorno.', '', 28153),
(141887, 'itIT', 'Uno dei miei fratelli... e risposte. Almeno spero.', '', 28153),
(141886, 'itIT', '', 'E cosa dovremmo trovare lì, esattamente?', 28153),
(141885, 'itIT', 'Riva del Marinaio è poco più avanti. Vieni.', '', 28153),
(141884, 'itIT', 'Stai giù!', '', 28153),
(141883, 'itIT', '', 'Nessuno di voi tornerà da Nazmir. Il povero Re nostro ha perso la figlia sua in chesta folle crociata!', 28153),
(141882, 'itIT', 'Devo raggiungere Nazmir. Eh, statt\' accuort\': là ci stanno solo Troll del Sangue e vudù oscuro.', '', 28153),
(141881, 'itIT', '', 'Nun lascerò che gli animaletti miei diventino cibo per i Troll del Sangue! Nessuno torna mai da Nazmir.', 28153),
(141880, 'itIT', 'Prima che tu parta, però, lascia che ti istruisca sulla posizione dei prossimi tre santuari.', '', 28153),
(141879, 'itIT', 'Si chiama Zandalar. Potresti dover noleggiare una barca, poiché si trova praticamente dall\'altra parte del globo.', '', 28153),
(141878, 'itIT', 'Credo di sapere dove trovarne altri, ma sono in territorio ostile.', '', 28153),
(141877, 'itIT', 'Mentre eri via, ho sfogliato il diario cercando di trovare l\'ubicazione di altri santuari.', '', 28153),
(141876, 'itIT', '', 'Con piacere, Gran Esarca.', 28153),
(141875, 'itIT', 'È ora che noi due torniamo a Roccavento. Fareeya, spargi la voce: i Forgialuce ora combattono per l\'Alleanza.', '', 28153),
(141874, 'itIT', 'T\'paartos è un po\'... particolare. Ma servirà bene la nostra causa.', '', 28153),
(141873, 'itIT', 'T\'paartos!', '', 28153),
(141872, 'itIT', '', 'Pheta thones gamera. Luce, guida il nostro cammino.', 28153),
(141871, 'itIT', 'Da questo giorno in avanti, tu farai parte dei Forgialuce.', '', 28153),
(141870, 'itIT', 'T\'paartos è dispiaciuto.', '', 28153),
(141869, 'itIT', '<Annusa l\'alito di Wees\'ki. Accidenti!>', '', 28153),
(141868, 'itIT', 'È stata la migliore notte di sempre. Peccato nun mi ricordi nulla.\n\nAlmeno, teniamo uova di dinosauro per colazione!', '', 28153),
(141867, 'itIT', 'Io e i Cacciatori dell\'Ombra miei perlustreremo la zona. Affido a te la difesa della Principessa.', '', 28153),
(141866, 'itIT', 'Ti ricordi cosa è successo la notte scorsa?\n\nNeppure io.', '', 28153),
(141865, 'itIT', 'Principessa, l\'Orda presto manderà i rinforzi suoi. Temo che nun teniamo tempo per chesta cosa.', '', 28153),
(141864, 'itIT', 'Uh... devo iniziare... a prendermi più cura di me stesso...', '', 28153),
(141863, 'itIT', 'Tu vai avanti. Io guarirò... Mi serve solo... ARGH! Mi serve solo tempo.', '', 28153),
(141862, 'itIT', 'Nun teniamo tempo per chesto!\n\nL\'Orda presto ci manderà dei rifornimenti e teniamo bisogno di nu porto per riceverli.', '', 28153),
(141861, 'itIT', '', 'Questa volta sono troppi! Fuoco!', 28153),
(141860, 'itIT', 'Vorrei tanto saperlo.', '', 28153),
(141859, 'itIT', '', 'Che sta succedendo qui, fratello?', 28153),
(141858, 'itIT', '', 'Cittadini, tornate ai vostri affari!', 28153),
(141857, 'itIT', 'Non prenderai mai il tesoro del mio padrone. Preparati all\'annientamento, $gintruso:intrusa;!', '', 28153),
(141856, 'itIT', 'CHI OSA METTERE PIEDE NELLA CRIPTA?!?', '', 28153),
(141855, 'itIT', '', 'Quando avrai la loro attenzione, li porterò via di qui.', 28153),
(141852, 'itIT', 'La paura... seguiva T\'paartos dappertutto!', '', 28153),
(141851, 'itIT', 'T\'paartos è dispiaciuto di averti chiamato insignificante.', '', 28153),
(141850, 'itIT', 'T\'paartos non conosce la paura!', '', 28153),
(141849, 'itIT', 'Qui!', '', 28153),
(141848, 'itIT', 'Attenzione!', '', 28153),
(141847, 'itIT', 'Da questa parte!', '', 28153),
(141846, 'itIT', 'Di qua!', '', 28153),
(141845, 'itIT', 'Abbiamo messo al sicuro la scorta di Azerite e le guardie dei Bracescura rimaste sono sotto controllo. La prigione è nostra.', 'Abbiamo messo al sicuro la scorta di Azerite e le guardie dei Bracescura rimaste sono sotto il nostro controllo. La prigione è nostra.', 28153),
(141844, 'itIT', 'Spero che tu abbia l\'abbia fatta pagare cara a Korgus per la sua crudeltà.', 'Spero che tu abbia l\'abbia fatta pagare cara a Korgus per la sua crudeltà.', 28153),
(141843, 'itIT', 'Grazie!', 'Grazie!', 28153),
(141842, 'itIT', 'Abbiamo messo al sicuro i prigionieri e stabilito un perimetro. I livelli inferiori sono in mano nostra.', 'Abbiamo messo al sicuro i prigionieri e stabilito un perimetro. I livelli inferiori sono in mano nostra.', 28153),
(141841, 'itIT', '', 'Subito, Gran Esarca.', 28153),
(141840, 'itIT', 'Fareeya, ho bisogno di un dislocatore per la Vindicaar.', '', 28153),
(141839, 'itIT', 'Vieni, da questa parte.', '', 28153),
(141838, 'itIT', 'Sarà fatto, Maestà.', '', 28153),
(141837, 'itIT', 'Sarebbe un onore avere i Forgialuce tra i ranghi dell\'Alleanza. Turalyon, porta con te il nostro campione sulla Vindicaar, così che possiate parlare entrambi alle truppe.', '', 28153),
(141836, 'itIT', '', 'Mi piaci, non sei mai $gsoddisfatto:soddisfatta;, proprio come me. È l\'eterna ricerca della perfezione.$B$BPerò, sai, non sono così convinta. Questa fotocamera contiene tutto il meglio dell\'ingegneria goblin in un unico prodotto. Abbiamo tra le mani un potenziale inimmaginabile.$B$BPotresti trovare una fonte di grande energia e vedere che succede. Non ti prometto nulla, però.', 28153),
(141835, 'itIT', '', 'Niko, più luce! Oh, ciao, bellezza, non ti avevo $gvisto:vista;. Cosa posso fare per te?', 28153),
(141834, 'itIT', '', 'Sai, non ne sono sicura! È il prodotto di un qualche tipo di potente ingegneria... forse con un paio di funzionalità nascoste.$B$BDovresti provare a portarla vicino a una fonte di grande energia. Di solito è un buon metodo per iniziare!', 28153),
(141833, 'itIT', 'Questa fotocamera può fare altro?', 'Questa fotocamera può fare altro?', 28153),
(141832, 'itIT', 'Ho perso la mia fotocamera. Puoi procurarmene un\'altra?', 'Ho perso la mia fotocamera. Puoi procurarmene un\'altra?', 28153),
(141831, 'itIT', '', 'Sistema Elettronico a Laser Focale per Immagini Egodinamiche', 28153),
(141830, 'itIT', 'Cosa significa S.E.L.F.I.E.?', 'Cosa significa S.E.L.F.I.E.?', 28153),
(141829, 'itIT', '', 'Oh, ciao! Volevi farti un S.E.L.F.I.E. con me?', 28153),
(141828, 'itIT', 'Vogliamo delle risposte, Pike!', 'Vogliamo delle risposte, Pike!', 28153),
(141827, 'itIT', 'È troppo occupata a mietere il raccolto \"per i soldati\"!', 'Sono troppo occupata a mietere il raccolto \"per i soldati\"!', 28153),
(141826, 'itIT', 'La milizia non pattuglia da giorni!', 'La milizia non pattuglia da giorni!', 28153),
(141825, 'itIT', 'Sepulcra è sotto attacco! Raggiungi il portale dei Maghi!', 'Sepulcra è sotto attacco! Raggiungi il portale dei Maghi!', 28153),
(141824, 'itIT', 'Dovremmo forse abbandonare tutto e rifugiarci a Orgrimmar?', 'Dovremmo forse abbandonare tutto e rifugiarci a Orgrimmar?', 28153),
(141823, 'itIT', 'Hanno chiuso improvvisamente i cancelli, cosa sta succedendo?', 'Hanno chiuso improvvisamente i cancelli, cosa sta succedendo?', 28153),
(141822, 'itIT', 'Sicuro o no, non ho intenzione di perdere la mia merce in questa guerra!', 'Sicuro o no, non ho intenzione di perdere la mia merce in questa guerra!', 28153),
(141821, 'itIT', 'Devo trovare i miei amici!', 'Devo trovare i miei amici!', 28153),
(141820, 'itIT', 'Mamma diceva che i soldati tenevano a bada i cattivi. Dove sono i soldati?', 'Mamma diceva che i soldati tengono sempre a bada i cattivi. Dove sono i soldati?', 28153),
(141819, 'itIT', 'Avevo così tanta paura! Grazie!', 'Avevo così tanta paura! Grazie!', 28153),
(141818, 'itIT', 'Voglio il mio papà!', 'Voglio il mio papà!', 28153),
(141817, 'itIT', 'Dov\'è la milizia?', 'Dov\'è la milizia?', 28153),
(141816, 'itIT', 'Mi hai salvato. Grazie!', 'Mi hai salvata. Grazie!', 28153),
(141815, 'itIT', 'Non siamo mai stati attaccati così duramente prima d\'ora!', 'Non siamo mai stati attaccati così duramente prima d\'ora!', 28153),
(141814, 'itIT', 'Posso farcela da qui. Spero che gli altri siano in salvo!', 'Posso farcela da qui. Spero che gli altri siano in salvo!', 28153),
(141813, 'itIT', 'Non... saprei. Mayla, tu e io dobbiamo procedere. Baine e il campione raduneranno gli altri per incontrarci sulla vetta.', '', 28153),
(141812, 'itIT', 'Figlio del... cosa intende dire?', '', 28153),
(141811, 'itIT', 'Sì... vieni! La tua forza diverrà nostra, figlio dell\'oscurità!', '', 28153),
(141810, 'itIT', 'L\'ultima protezione fu messa sulla Vetta di Alto Monte. È lì che dobbiamo andare. Dobbiamo restare uniti, proprio come fece Huln con i suoi alleati.', '', 28153),
(141809, 'itIT', 'Infatti. E quando ho lasciato la montagna per far visita a Mulgore, le difese si sono indebolite tanto da permettere all\'Oscurità di passare.', '', 28153),
(141808, 'itIT', '', 'Per tutto questo tempo, i Necronotte sono rimasti nell\'ombra, in attesa del richiamo del loro padrone.', 28153),
(141807, 'itIT', 'Così Huln ideò un altro piano. Posizionò delle protezioni per neutralizzare l\'influenza degli Dei Antichi. Anche se Uul\'gyneth riuscì a sopravvivere, la sua essenza venne intrappolata.', '', 28153),
(141806, 'itIT', 'Huln radunò gli eroi di tutte le tribù. Combatterono contro i servi di Uul\'gyneth, i Necronotte... ma le forze dell\'ombra erano troppo imponenti per essere sconfitte.', '', 28153),
(141805, 'itIT', 'Molto tempo fa, gli Dei Antichi cercarono di impadronirsi di Alto Monte. La loro campagna era guidata da una creatura dell\'incubo... Uul\'gyneth l\'Oscurità.', '', 28153),
(141804, 'itIT', '', 'Ma il nostro lavoro non è ancora finito. Corna Nere, dobbiamo scoprire cosa vuole questa Oscurità.', 28153),
(141803, 'itIT', 'Cielo Grigio mi ha parlato del tuo coraggio.', '', 28153),
(141802, 'itIT', 'Ho di nuovo il controllo della mia mente. Torniamo a Totem del Fulmine e recuperiamo le forze per ciò che ci aspetta.', '', 28153),
(141801, 'itIT', '', 'Presto! Sento li altri vicini.', 28153),
(141800, 'itIT', '', 'Io rimarrò qui, Cielo Grigio verrà con te. Speriamo che le protezioni sanino la mente di Corna Nere.', 28153),
(141799, 'itIT', '', 'Le acque hanno placato Corna Nere, ma temo che presto lo perderemo.', 28153),
(141798, 'itIT', 'Vai ad Alto Monte e aiuta Mayla. Io ti raggiungerò presto.', '', 28153),
(141797, 'itIT', 'Devo assicurarmi che i servi degli Dei Antichi vengano cacciati da Mulgore.', '', 28153),
(141796, 'itIT', 'I tuoi padroni non conquisteranno la mia città, mostro!', '', 28153),
(141795, 'itIT', 'Annientateli! Non devono impedire il mio ritorno!', '', 28153),
(141794, 'itIT', '', 'Se liberano quel mostro, i Troll del Sangue saranno inarrestabili. Anche con te e l\'Orda al fianco nostro, nun basterà. Ci serve nu nuovo piano.', 28153),
(141793, 'itIT', '', 'Nun ci stanno seguendo. A quanto pare teniamo la via libera.', 28153),
(141792, 'itIT', 'Molto bene. Elimineremo questa feccia degli Dei Antichi da Picco del Tuono.', '', 28153),
(141791, 'itIT', '', 'Capisco, amico mio. Baine, devo riportare Corna Nere ad Alto Monte!', 28153),
(141790, 'itIT', 'Mayla... le pozze...', '', 28153),
(141789, 'itIT', '', 'Nun temo te e nemmeno i mostri tuoi! Morirete tutti per mano mia!', 28153),
(141788, 'itIT', '', 'Corri, Principessa! Niente ti salverà dal padrone mio! G\'huun, ti divorerà!', 28153),
(141787, 'itIT', '', 'Dobbiamo muoverci! Tieni duro!', 28153),
(141786, 'itIT', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t La Regina delle Sabbie lancia |cFFFF0000|Hspell:257609|h[Rabbia]|h|r!', '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t La Regina delle Sabbie lancia |cFFFF0000|Hspell:257609|h[Rabbia]|h|r!', 28153),
(141784, 'itIT', 'Le protezioni si sono indebolite! Sarà nostro!', '', 28153),
(141783, 'itIT', 'Insieme, torneremo alle maree. Insieme, saremo di nuovo imbattibili!', '', 28153),
(141782, 'itIT', 'I nostri potenti Saggi delle Maree ci guideranno alla vittoria grazie al potere del mare!', '', 28153),
(141781, 'itIT', 'Dobbiamo stare uniti e raccogliere le forze. Kul Tiras apparterrà per sempre alla sua gente!', '', 28153),
(141780, 'itIT', 'La Casata dei Sacraonda deve ottenere il controllo di questo regno infranto e ricondurlo alla gloria!', '', 28153),
(141779, 'itIT', 'Non lavoreremo più i campi né costruiremo più navi per la sprezzante casta di Boralus senza avere nulla in cambio.', '', 28153),
(141778, 'itIT', 'Figli del mare, oggi è l\'alba di una nuova era per tutti noi.', '', 28153),
(141777, 'itIT', 'Se tu avessi visto ciò che ho visto io, faresti lo stesso. Entra, ti faccio vedere!', '', 28153),
(141774, 'itIT', 'Energia del sistema in esaurimento.', '', 28153),
(141773, 'itIT', 'Puntamento primario in a-a-avaria...', '', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141772, 'itIT', 'Livello salute basso. Assistenza richiesta.', '', 28153),
(141771, 'itIT', 'Malfunzionamento!', '', 28153),
(141770, 'itIT', '', 'Il santuario dorato? Probabilmente si tratta di Atal\'Dazar. È una città. D\'oro. Tutta d\'oro.$b$bSantuario? Forse per l\'oro. O per i dinosauri. O per i dinosauri placcati d\'oro!$b$bAndrò a controllare!', 28153),
(141769, 'itIT', 'Pare siano stati trascinati da quella parte, in cima al ghiacciaio a nord-ovest.', '', 28153),
(141768, 'itIT', 'Hai mai sentito parlare di un luogo noto come il \"santuario dorato\"?', 'Hai mai sentito parlare di un luogo noto come il \"santuario dorato\"?', 28153),
(141767, 'itIT', 'La tua missione è stanare quei vermi, eliminarli e assicurare che i nostri cittadini vengano portati al sicuro a Orgrimmar.', '', 28153),
(141766, 'itIT', 'Abbiamo radunato i codardi al Distretto dei Maghi e messo al sicuro il resto della città.', '', 28153),
(141765, 'itIT', 'I nostri nemici stanno attaccando Sepulcra e intendono conquistare Lordaeron.', '', 28153),
(141764, 'itIT', 'Sepulcra non è più un luogo sicuro per i civili. La guerra infuria e decine di spie si sono infiltrate tra le nostre mura.', '', 28153),
(141762, 'itIT', 'Soldati dell\'Orda, è giunto il momento!', '', 28153),
(141761, 'itIT', '', 'Incontriamoci nella Valle dell\'Onore appena raggiungi Orgrimmar! Non è sicuro qui!', 28153),
(141760, 'itIT', '', 'Il mio portale è aperto, dobbiamo evacuare!', 28153),
(141759, 'itIT', '', 'Raggiungi Orgrimmar! Non è sicuro qui!', 28153),
(141758, 'itIT', 'Bel... colpo...', '', 28153),
(141757, 'itIT', 'Correte quanto vi pare! Io non manco mai un colpo.', '', 28153),
(141756, 'itIT', 'Finirete nel bel mezzo del fuoco incrociato!', '', 28153),
(141755, 'itIT', 'Non vedevo l\'ora di provare questi colpi contro bersagli viventi.', '', 28153),
(141754, 'itIT', 'Consideratevi... riabilitati.', '', 28153),
(141753, 'itIT', 'Goditi l\'ultimo pasto... a base di piombo!', '', 28153),
(141752, 'itIT', 'La tua sentenza è... MORTE.', '', 28153),
(141751, 'itIT', 'Gentile da parte vostra tornare in tempo per la vostra esecuzione.', '', 28153),
(141750, 'itIT', 'Altre bombe in arrivo!', '', 28153),
(141749, 'itIT', 'Sì, signora!', '', 28153),
(141748, 'itIT', '', 'Voglio che le fiamme ardano più calde!', 28153),
(141747, 'itIT', '', 'Presto! Altro combustibile per il fuoco!', 28153),
(141746, 'itIT', '', 'Vi ridurrò in cenere!', 28153),
(141745, 'itIT', '', 'Bruciate nella pira!', 28153),
(141744, 'itIT', '', 'È ora di scaldare la situazione!', 28153),
(141743, 'itIT', 'Avete ucciso il mio amico!', '', 28153),
(141742, 'itIT', '', 'Le stelle più luminose... ardono... più in fretta.', 28153),
(141741, 'itIT', 'Pagherete per ciò che avete fatto!', '', 28153),
(141740, 'itIT', 'Tienili occupati! Io li farò a fette.', '', 28153),
(141739, 'itIT', '', 'Dobbiamo trovare chest\'arma prima che Jakra\'zet possa mettervi sopra le mani sue.', 28153),
(141738, 'itIT', '', 'Nun tengo idea di cosa sia chest\'arma, o dove trovarla, ma nun deve essere niente di buono se Jakra\'zet sta nascondendo l\'esistenza sua al Re.', 28153),
(141737, 'itIT', '', 'Vagano tra le dune, in cerca di n\'arma capace di distruggere la città, accidendo chiunque si trovi sul cammino loro.', 28153),
(141736, 'itIT', '', 'È come sospettavo. Il Generale Jakra\'zet tiene alcune truppe nel deserto, all\'insaputa del Re.', 28153),
(141735, 'itIT', 'Prospezione', 'Prospezione', 28153),
(141734, 'itIT', 'Certamente! Vieni qui, $gragazzo:ragazza;, ho qualcosa da farti fare.', '', 28153),
(141733, 'itIT', 'Ehi, Rulf! $gQuesto ragazzo:Questa ragazza; promette bene! Devi fare qualche lavoretto?', '', 28153),
(141732, 'itIT', '', 'Mi piacciono le bolle. Mi fanno sentire al sicuro!', 28153),
(141731, 'itIT', 'Ci credi che esistono città che NON sono protette da uno scudo magico? Ma come fanno a tener fuori la polvere? Selvaggi...', '', 28153),
(141730, 'itIT', '', 'Credevo che nun l\'avrei più rivista...', 28153),
(141729, 'itIT', 'Tornano i ricordi, e con essi anche il dolore...', '', 28153),
(141728, 'itIT', '', 'Non ha resistito al calore!', 28153),
(141727, 'itIT', '', 'Oh... Senti come sfrigola la carne!', 28153),
(141726, 'itIT', '', 'I vostri corpi saranno un ottimo combustibile.', 28153),
(141725, 'itIT', '', 'Non vedo l\'ora di vedervi sciogliere!', 28153),
(141724, 'itIT', '', 'Vieni, presto! I ricordi di Rakera stanno tornando!', 28153),
(141723, 'itIT', 'Sei tu... che dovresti... sanguinare...', '', 28153),
(141722, 'itIT', '', 'Ahhhh... La mia testa... Kaja, se-sei tu?', 28153),
(141721, 'itIT', 'È ora della caccia!', '', 28153),
(141720, 'itIT', 'Avete ucciso il mio fratellino. Ora vi ridurrò a brandelli.', '', 28153),
(141719, 'itIT', 'Fratellino!', '', 28153),
(141718, 'itIT', 'In piedi, fratellino! Abbiamo un sacco di cose da uccidere.', '', 28153),
(141717, 'itIT', 'Venite, ragazzi! Fategli vedere chi è che comanda qui!', '', 28153),
(141716, 'itIT', 'Ho affilato queste lame proprio per voi.', '', 28153),
(141715, 'itIT', 'Io volevo... solo... patteggiare...', '', 28153),
(141714, 'itIT', 'Dovevate restare nelle vostre celle.', '', 28153),
(141713, 'itIT', 'Mandami a Ulduar. (Incursione nel Tempo)', 'Mandami a Ulduar. (Incursione nel Tempo)', 28153),
(141712, 'itIT', '', 'Salve, $n. Probabilmente non ti ricordi di me, ma ci siamo incontrati la settimana prossima.$b$bTi andrebbe di visitare di nuovo Ulduar?', 28153),
(141711, 'itIT', 'Sono io l\'alfa!', '', 28153),
(141710, 'itIT', 'Carne morta.', '', 28153),
(141709, 'itIT', 'Carne fresca!', '', 28153),
(141708, 'itIT', 'Indebolisci il grifone ma mantieni la presa con |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Presa Salda]|h|r', '', 28153),
(141707, 'itIT', 'Sono pronto a partire.', 'Sono pronta a partire.', 28153),
(141706, 'itIT', '', 'Mettiamoci al lavoro.', 28153),
(141705, 'itIT', '', 'Siamo fuori pericolo. Dovremo muoverci in fretta na volta arrivati alle Rovine di Zul\'jan.', 28153),
(141704, 'itIT', '', 'I Troll del Sangue sono inarrestabili e infiniti grazie al potere di nu Dio Antico.', 28153),
(141703, 'itIT', '', 'Sono felice che tu l\'abbia riconosciuto, Asdrubal. Stai nu passo avanti al padre mio.', 28153),
(141701, 'itIT', '', 'Non Morti! Staranno andando verso Zuldazar. Dobbiamo eliminarli!', 28153),
(141696, 'itIT', 'Sembra che il talismano non stia funzionando. Provalo prima su qualche Schiavo Malovolto.', '', 28153),
(141695, 'itIT', 'Questo tizio non mi sembra molto sveglio.', '', 28153),
(141694, 'itIT', '<Codaventura scappa verso le cascate!>', '', 28153),
(141693, 'itIT', '', '', 28153),
(141692, 'itIT', '|cffffff00+$1i Resti di Battaglia|r', '|cffffff00+$1i Resti di Battaglia|r', 28153),
(141691, 'itIT', '<Codaventura fugge per mettersi in salvo!>', '', 28153),
(141690, 'itIT', '', 'Cos\'hanno fatto chei cultisti a Rakera... Nun si ricorda nemmeno il nome suo.', 28153),
(141689, 'itIT', 'Tu! Sì, tu. Avvicinati lemme lemme. Nun attirare l\'attenzione.', '', 28153),
(141688, 'itIT', '', 'Che t\'hanno fatto...?', 28153),
(141687, 'itIT', '', 'Siamo tutti Akunda.', 28153),
(141686, 'itIT', '', 'Rakera?', 28153),
(141685, 'itIT', '', 'Sta accà. È viva! Rakera!', 28153),
(141684, 'itIT', '', 'Rakera!', 28153),
(141683, 'itIT', '', 'Qualcuno in chesto strano tempio deve sapere qualcosa.', 28153),
(141682, 'itIT', 'Nun mi importa quale accordo intendi mercanteggiare con il re e la figlia sua. So che la presenza tua nun è benvenuta a Zuldazar.$b$bE benché la principessa abbia molta autorità, nun è ancora la regina.$b$bFino ad allora, il vero potere di Zuldazar sta nelle mani mie e del Concilio delli Zanchuli.', '', 28153),
(141681, 'itIT', '', 'Questa è una cerimonia ufficiale. Non interrompere.', 28153),
(141680, 'itIT', 'T\'paartos ora comprende.', '', 28153),
(141679, 'itIT', 'L\'oscurità si nasconde in tutti noi. Non è una cosa facile da ammettere.', '', 28153),
(141678, 'itIT', '', 'T\'paartos... Hai affrontato le tue paure... i tuoi fallimenti... e sei rinato.', 28153),
(141677, 'itIT', '', 'Bentornato, T\'paartos.', 28153),
(141676, 'itIT', '', 'Se Rakera sta all\'interno del tempio, la troveremo.', 28153),
(141675, 'itIT', 'Craaa! Puzzi di cose strane. Craaa!', '', 28153),
(141674, 'itIT', 'Scusa! Puzzi di guano! Craaa!', '', 28153),
(141673, 'itIT', 'Craaa! Kragg morto! Skipper dispiaciuto!', '', 28153),
(141672, 'itIT', '', 'Ah nu membro dell\'Orda. Curioso...', 28153),
(141671, 'itIT', '$n ha attaccato le forze dell\'Alleanza alla Segheria!', '$n ha attaccato le forze dell\'Alleanza alla Segheria!', 28153),
(141669, 'itIT', '', 'Il vento stesso è vivo grazie ai poteri dei Loa. Pa\'ku vola in chesti cieli, posso sentire la presenza sua.$b$bNun ho mai messo piede a Zandalar prima d\'ora, ma il vecchio nonno mio mi raccontava storie di chesto posto.', 28153),
(141668, 'itIT', '', 'I Loa sono potenti accà. Riesco a sentire la presenza di Gonk dietro ogni albero e cespuglio.$b$bGonk sta vicino. Sarà bello vederlo con li occhi miei.', 28153),
(141667, 'itIT', 'Non cadremo così facilmente. Soldati, riprendete la nostra Segheria!', '', 28153),
(141666, 'itIT', 'Salve, $gpiccirillo:piccirilla;.$b$bSono il Signore del Maleficio Raal, il più grande tra coloro che hanno stretto nu patto con Pa\'ku, la Loa dei Venti, nonché membro del Concilio delli Zanchuli.$b$bSono importante e occupato assai. Cosa vuoi?', '', 28153),
(141665, 'itIT', '', 'Il tempo nostro con il Signore del Maleficio è limitato. Nun interrompere, teniamo molto di cui parlare.', 28153),
(141664, 'itIT', 'Amico mio!', '', 28153),
(141663, 'itIT', '', 'Ora i Sethrak impareranno a temere i Vulpera!', 28153),
(141662, 'itIT', 'Pare che il Generale Jakra\'zet, il Troll Sabbiafurente che gestisce l\'esercito di Zuldazar, abbia deciso di ritirare le guardie sue dal porto.\n\nNun tutti i Troll sono felici del decreto della Principessa Talanji che permette l\'accesso al porto alle altre razze.\n\nPer procedere, la Principessa terrà bisogno del supporto di almeno nu membro del Concilio delli Zanchuli. Fortunatamente, so dove stanno due di loro.', '', 28153),
(141660, 'itIT', '', 'I Vulpera sono tutt\'altro che deboli. Ci temeranno!', 28153),
(141658, 'itIT', 'Risucchio', 'Risucchio', 28153),
(141657, 'itIT', '', 'I Sethrak la pagheranno per ciò che hanno fatto alla nostra casa.', 28153),
(141655, 'itIT', 'No, non preoccuparti per me... hic! Me ne andrò per la mia shtrada ora... oh... ma dove shono?$b$bAshcolta, fammi riprendere un attimo... hic! Vedrai che al tuo ritorno sarò shobrio, lo giuro!', '', 28153),
(141654, 'itIT', 'Ahah, quella è la parte divertente. Ashcolta, è andato là e shi è fatto prendere... hic! Quello shtupido farabutto ha cercato di uccidere qualcuno$b$bL\'hanno shbattuto in prigione col reshto della feccia. She è ancora in shuo posshessho, shcommetto che l\'unico modo per recuperarlo shia prenderlo dalle shue mani una volta che sharà morto.$b$bNon proverai a uccidere anche me, giushto? Hic! Non ti ho mai fatto niente.$b$bAshcolta, me ne vado da qualche altra parte a riprendermi. Hic!', '', 28153),
(141653, 'itIT', 'Dov\'è la persona che ha preso il gioiello?', 'Dov\'è la persona che ha preso il gioiello?', 28153),
(141652, 'itIT', 'Quel figlio di brava donna she n\'è andato con il noshtro gioiello, hic! Tutto quel tempo per tirar fuori quel dannato affare e lui cosha fa? Hic!$b$bShe ne va via nel cuore della notte... Hic! Sharemmo diventati ricchi!$b$b<Salton beve un altro sorso dalla sua fiaschetta.>$b$bEhi, hai per casho un po\' d\'oro?', '', 28153),
(141651, 'itIT', '', 'Sono pronta. Andiamo a caccia di Sethrak.', 28153),
(141649, 'itIT', 'La Principessa Talanji ha bisogno del tuo aiuto con Jakra\'zet.', 'La Principessa Talanji ha bisogno del tuo aiuto con Jakra\'zet.', 28153),
(141648, 'itIT', '', 'Stai di fronte alla Druida da Guerra Loti, devota di Gonk, Campionessa della Caccia e Signora delle Tracce. Cosa vuoi, $C?', 28153),
(141647, 'itIT', 'Scaldate le seghe circolari! Ci serve più legna.', '', 28153),
(141646, 'itIT', 'Oh, direi che teniamo nu problema con chesto. Jakra\'zet si rifiuta di seguire li ordini della Principessa.$b$bTengo bisogno dell\'aiuto di nu membro del Concilio delli Zanchuli, ma i due presenti stanno impegnati con na disputa tribale.$b$bVai a Tal\'aman o a Tal\'farrak e vedi se riesci a ottenere l\'aiuto di uno di loro.$b$bIo sono troppo importante per nu compito come chesto, altrimenti me ne sarei occupato di persona.', '', 28153),
(141645, 'itIT', 'La Principessa Talanji vuole sapere dove sono le guardie.', 'La Principessa Talanji vuole sapere dove sono le guardie.', 28153),
(141644, 'itIT', 'Dal momento in cui ho visto la faccia tua a Roccavento, ho capito che era giunta l\'ora della profezia.$b$bLi spiriti mi mostrano tante cose, e in cheste visioni ho visto il volto tuo alla guida dei grandi eventi in arrivo.$b$bLi ingranaggi sono in movimento, $C. Presto, tu e io scuoteremo le fondamenta stesse di chesto mondo.', '', 28153),
(141643, 'itIT', 'Se fossi in te, farei lo stesso. Buona fortuna.', 'Se fossi in te, farei lo stesso. Buona fortuna.', 28153),
(141642, 'itIT', 'Sì... lasciati andare, T\'paartos. Accogli il vero potere!', '', 28153),
(141641, 'itIT', 'Liberati delle catene della Luce.', '', 28153),
(141640, 'itIT', 'La Luce non è la via per il vero potere.', '', 28153),
(141639, 'itIT', 'Il potere ci attende, T\'paartos.', '', 28153),
(141638, 'itIT', 'La Luce è sempre stata con T\'paartos! Lui non abbandonerà MAI la Luce!', '', 28153),
(141637, 'itIT', 'BASTA!!!', '', 28153),
(141636, 'itIT', 'No...', '', 28153),
(141635, 'itIT', 'No... non può essere. Questo non può essere il vero T\'paartos!', '', 28153),
(141634, 'itIT', 'Ugh! Puoi far andare via quei serpenti?', '', 28153),
(141633, 'itIT', 'Questo è... vagamente imbarazzante per T\'paartos.', '', 28153),
(141632, 'itIT', 'Ah ah! T\'paartos può sollevare le montagne!', '', 28153),
(141631, 'itIT', 'T\'paartos ha affrontato molti demoni nell\'Armata della Luce.', '', 28153),
(141630, 'itIT', 'Ahhh, Ika. T\'paartos accudì questo Elekk quando sua madre venne uccisa.', '', 28153),
(141629, 'itIT', 'No! L\'oscurità non avrà T\'paartos!', '', 28153),
(141628, 'itIT', 'T\'paartos era destinato a seguire questa strada? T\'paartos è degno di diventare Forgialuce?', '', 28153),
(141623, 'itIT', 'Mi hai salvato di nuovo la pelle! Tornerò all\'accampamento, prima che mi venga un accidente.', '', 28153),
(141620, 'itIT', '', 'Non ucciderli senza di me!', 28153),
(141619, 'itIT', '', 'I Vulpera sono pronti. I Senzafede ci temeranno.', 28153),
(141618, 'itIT', 'Mmm... a prenderti... mmm...', '', 28153),
(141617, 'itIT', 'Avrei ushato quell\'oro per sposharmi... <singhiozza>.', '', 28153),
(141616, 'itIT', 'Non appena avrò una barca... Hic!... verrò a prenderti!', '', 28153),
(141615, 'itIT', 'Hai preso il noshtro dannato gioiello, farabutto! Hic!', '', 28153),
(141614, 'itIT', 'Hai preso il noshtro... Hic!', '', 28153),
(141613, 'itIT', 'Devo smettere di lasciare che Nisha si occupi dei piani...', '', 28153),
(141612, 'itIT', '', 'Non credo l\'abbia fatto. Gran parte della tua razza non può. Be\', non più.', 28153),
(141611, 'itIT', 'Vacci piano, Meerah. Le nostre carovane non sono adatte alle antiche strade dei Troll.', '', 28153),
(141610, 'itIT', '', 'I Sethrak si pentiranno di aver attaccato la nostra carovana.', 28153),
(141609, 'itIT', 'Datevi da fare con quelle corde! Tenetela ferma!', '', 28153),
(141608, 'itIT', '', 'Ecco qua, $n, il diario tradotto. Direi che con questo abbiamo voltato pagina.', 28153),
(141607, 'itIT', '', 'Sì? Sì! Finalmente! Ora vediamo... dove sono i miei libri vuoti? Ah, eccone uno.', 28153),
(141606, 'itIT', '', 'Oh, quindi è a questo che serve quella runa. Interessante...', 28153),
(141605, 'itIT', '', 'Li hai presi tutti?!? Ottimo lavoro, $n. Ora pensiamo a tradurre questo diario.', 28153),
(141604, 'itIT', '<Il soldato mugugna qualcosa di incomprensibile.>', '<La soldatessa mugugna qualcosa di incomprensibile.>', 28153),
(141603, 'itIT', 'Ecco i libri che avevi richiesto.', 'Ecco i libri che avevi richiesto.', 28153),
(141602, 'itIT', 'Il mare si sta alzando, o siamo noi che stiamo cadendo?\n\nSempre più a fondo...', 'Il mare si sta alzando, o siamo noi che stiamo cadendo?\n\nSempre più a fondo...', 28153),
(141601, 'itIT', 'Perfetto, perfetto, ha detto che tutto deve essere perfetto...\n\nMa chi l\'ha detto?', 'Perfetto, perfetto, ha detto che tutto deve essere perfetto...\n\nMa chi l\'ha detto?', 28153),
(141600, 'itIT', 'Quelli Zandalari presto terranno na bella sorpresa!', 'Quelli Zandalari presto terranno na bella sorpresa!', 28153),
(141599, 'itIT', 'I crog crescono bene. Presto saranno pronti per essere cavalcati.', 'I crog crescono bene. Presto saranno pronti per essere cavalcati.', 28153),
(141598, 'itIT', 'Mi dispiace, ma\'ma. Me ne andrò subito dalla vista tua.', 'Mi dispiace, ma\'ma. Me ne andrò subito dalla vista tua.', 28153),
(141597, 'itIT', 'Ti consiglio di affilare bene il coltello tuo. Ho sentito che presto combatteremo contro li Zandalari.', 'Ti consiglio di affilare bene il coltello tuo. Ho sentito che presto combatteremo contro li Zandalari.', 28153),
(141596, 'itIT', 'Capoguerra Sylvanas Ventolesto, ti presento la Capo Tribù Mayla Alto Monte.', '', 28153),
(141595, 'itIT', 'Uno dei nostri zaini! Pare che abbiamo trovato il posto giusto.', '', 28153),
(141594, 'itIT', 'Ah! Una delle nostre asce: siamo sulla pista giusta.', '', 28153),
(141593, 'itIT', 'Questa pover\'anima è morta da un pezzo. Cerchiamo il carro dei rifornimenti a est.', '', 28153),
(141592, 'itIT', 'Nun ti ho mai $gvisto:vista; prima. Pare che il gruppo di lavoro di Najima sia stato trovato schiattato.', 'Nun ti ho mai $gvisto:vista; prima. Pare che il gruppo di lavoro di Najima sia stato trovato schiattato.', 28153),
(141591, 'itIT', '', '', 28153),
(141590, 'itIT', '', '', 28153),
(141589, 'itIT', '', 'Così i Necronotte sono rimasti nell\'ombra, in attesa del richiamo del loro padrone.', 28153),
(141588, 'itIT', '', '', 28153),
(141587, 'itIT', '', '', 28153),
(141586, 'itIT', '', '', 28153),
(141585, 'itIT', 'Seguimi.', '', 28153),
(141584, 'itIT', '<Il sindaco non risponde.>', '', 28153),
(141583, 'itIT', '<Cerca l\'origine dell\'incantesimo.>', '<Cerca l\'origine dell\'incantesimo.>', 28153),
(141582, 'itIT', '<L\'effige al centro della città pulsa di un\'energia oscura simile a quella che ha colpito i cittadini. Forse è qui che ha avuto origine la magia.>\n\n<Se venisse distrutta, l\'incantesimo potrebbe spezzarsi.>', '', 28153),
(141581, 'itIT', '<Quest\'uomo corrisponde alla descrizione di Cyril White, sindaco di Malautunno. Sfortunatamente, non è in grado di aiutarti in questo momento.>\n\n<Il sindaco, insieme al resto dei cittadini di Malautunno, sembra essere sotto l\'effetto di qualche magia sconosciuta. Sebbene respiri ancora, non si muove né riesce a rispondere.>\n\n<Se vuoi il suo aiuto per contattare la Casata dei Crestabianca, devi trovare un modo per spezzare questa maledizione.>', '', 28153),
(141580, 'itIT', 'Mi hai salvato la vita! Mi chiedo dove mi manderanno la prossima volta quei Collorozzo...', '', 28153),
(141579, 'itIT', 'Le protezioni si sono indebolite! Sarà nostro!', '', 28153),
(141578, 'itIT', 'Avete fallito! L\'Oscurità si erge... e Alto Monte cade!', '', 28153),
(141577, 'itIT', 'La Legione non era niente in confronto a noi! Arrendetevi!', '', 28153),
(141576, 'itIT', 'I Corno Celeste serviranno i miei padroni! Diverrete l\'ombra che oscurerà i cieli!', '', 28153),
(141575, 'itIT', 'Servite i vostri veri padroni, Drogbar! Disobbedienza significa morte!', '', 28153),
(141573, 'itIT', '', 'Ehilà! Ehm... ti interessa per caso la storia di Kul Tiras? Ho diversi volumi che narrano della sua fondazione e della politica della nostra grande nazione. È davvero un argomento interessante!$b$bSappi che sono anche molto bravo nell\'arte della trascrizione e potrei insegnarti tutto ciò che so fare con penna e inchiostro!', 28153),
(141572, 'itIT', 'Fai nu solo errore e ti seppelliremo accà.', '', 28153),
(141571, 'itIT', 'Meerah, prepara la carovana e stai pronta a prendere i rifornimenti al porto. I nostri nuovi alleati possono procedere oltre e continuare la ricerca.', '', 28153),
(141570, 'itIT', 'Chesta umidità è quasi fastidiosa quanto la faccia tua.', 'Chesta umidità è quasi fastidiosa quanto la faccia tua.', 28153),
(141569, 'itIT', 'Cosa stai guardando?', 'Cosa stai guardando?', 28153),
(141568, 'itIT', 'Tieni l\'attenzione dei reali, per cui nun ti accideremo... per ora.', 'Tieni l\'attenzione dei reali, per cui nun ti accideremo... per ora.', 28153),
(141567, 'itIT', 'Usurpatori. L\'Orda pagherà per ciò che ha fatto alla gente mia a Tanaris.', 'Usurpatori. L\'Orda pagherà per ciò che ha fatto alla gente mia a Tanaris.', 28153),
(141566, 'itIT', 'Buongiorno $gsignore:signora;. Le interessa la delicata arte dell\'intaglio, meglio conosciuta come oreficeria?', '', 28153),
(141565, 'itIT', 'Sorridi finché puoi, $C. Nu passo falso accà, e ti accideremo con le mani nostre.', 'Sorridi finché puoi, $C. Nu passo falso accà, e ti accideremo con le mani nostre.', 28153),
(141564, 'itIT', 'L\'Orda ha preferito li Elfi del Sangue a noi, e poi ha acciso il più grande capo nostro, Zul\'jin$b$bSangue. La gente vostra ci deve tanto sangue, cumpà.', '', 28153),
(141563, 'itIT', 'Sta\' accuort\', cumpà. Quando la Principessa avrà finito con te, dovrai fare na chiacchierata col coltello mio per chello che l\'Orda ha fatto a Zul\'jin.', '', 28153),
(141562, 'itIT', 'Tieni il marchio della Principessa Talanji. Significa che nun possiamo acciderti, ma nun ci piaci comunque.', '', 28153),
(141561, 'itIT', 'Cosa ti guardi?', '', 28153),
(141559, 'itIT', 'Il tempio è in rovina! È anche peggio di quanto pensassi...', '', 28153),
(141558, 'itIT', 'Devo tornare al tempio. Chissà com\'è diventato durante l\'assenza mia...', '', 28153),
(141557, 'itIT', '', 'Ora appartengono a me!', 28153),
(141556, 'itIT', 'Sono libero dalla morsa degli Dei Antichi. Grazie, amici miei.', '', 28153),
(141555, 'itIT', 'Mayla! Dobbiamo rimanere uniti!', '', 28153),
(141554, 'itIT', '', 'Non posso permettere che l\'Oscurità si impossessi del corpo di mio padre!', 28153),
(141552, 'itIT', 'Volevo... vedere...', 'Volevo... vedere...', 28153),
(141549, 'itIT', 'Tornatene nel calderone!', 'Tornatene nel calderone!', 28153),
(141547, 'itIT', 'Ah, grazie per avermi liberato! Nun avrei dovuto fidarmi di chei traditori dei Tortaka!', '', 28153),
(141546, 'itIT', 'Vol\'jamba aveva promesso...', 'Vol\'jamba aveva promesso...', 28153),
(141544, 'itIT', 'Ha forse... sbagliato?', 'Forse... si sbagliava...?', 28153),
(141538, 'itIT', 'Solo Vol\'jamba può salvarci!', 'Solo Vol\'jamba può salvarci!', 28153),
(141536, 'itIT', 'Fatti sotto. Vediamo chi tiene la volontà più forte!', '', 28153),
(141535, 'itIT', 'Nun mi sottometterò... mai...', 'Nun mi sottometterò... mai...', 28153),
(141528, 'itIT', 'Diceva... che saremmo sopravvissuti...', 'Diceva... che saremmo... sopravvissuti...', 28153),
(141527, 'itIT', 'Perché nessuno vuole ascoltare?!? La fine sta arrivando!', 'Perché nessuno vuole ascoltare?!? La fine sta arrivando!', 28153),
(141524, 'itIT', 'Agli ordini.', '', 28153),
(141523, 'itIT', 'Leo!', '', 28153),
(141522, 'itIT', 'Ladri di legna! Leo, prendili!', '', 28153),
(141519, 'itIT', '', 'Argh... Ehi, sei tu? Dove stiamo?', 28153),
(141518, 'itIT', 'Questo T\'paartos è un servo della Luce... ma corteggia l\'oscurità? Questo non può essere il destino di T\'paartos!', '', 28153),
(141517, 'itIT', 'Tutto è come il Profeta aveva detto. Forse ora capirai perché lo tengo al fianco mio.', '', 28153),
(141512, 'itIT', 'Piglia il sigillo che ti ho dato e piazzalo sul gong.', '', 28153),
(141510, 'itIT', 'Bah!', '', 28153),
(141509, 'itIT', 'Allontanati! Nun toccarlo!', '', 28153),
(141508, 'itIT', 'La visione è chesta: vele dorate segnalano l\'arrivo della fine. Il manipolatore vuole spezzare l\'ultimo sigillo.', '', 28153),
(141507, 'itIT', 'Mi sento generoso. Sentiamo che hai da dire. L\'amico mio accà, però...', '', 28153),
(141506, 'itIT', 'Tengo na cosa da dire al vecchio allievo mio. Mi troverai quando ti sarai occupato dei folli che gli obbediscono.', '', 28153),
(141505, 'itIT', 'Smettetela di nascondervi dietro le maschere vostre. State solo cercando di guadagnare tempo...', '', 28153),
(141504, 'itIT', 'Allora porta la nuova Voce nostra con te e occupatevene.', '', 28153),
(141503, 'itIT', 'Sarà fatto come desideri. Però... Ho previsto che Vol\'jamba nun morirà per mano mia.', '', 28153),
(141502, 'itIT', 'Chesta è opera tua, profeta. Tocca a te sistemare tutto quanto.', '', 28153),
(141500, 'itIT', 'Nigel! Eccoti qua!', '', 28153),
(141499, 'itIT', '', 'Che gusto c\'è a esplorare senza un pizzico di pericolo? Non mi sono nemmeno graffiata.', 28153),
(141498, 'itIT', '', 'Ed è praticamente l\'unica cosa che sono riuscita a salvare.', 28153),
(141497, 'itIT', 'Sono solo felice di vedere che sei riuscita a salvarti.', '', 28153),
(141496, 'itIT', 'Questa via condurrà alla grandezza? Alla gloria? O all\'annientamento?', '', 28153),
(141495, 'itIT', 'In una sola anima si nascondono molte verità. Alcune nobili. Altre...', '', 28153),
(141494, 'itIT', 'Un\'offerta rifiutata. Eppure... la paura rimane.', '', 28153),
(141493, 'itIT', 'Forse, per superare la paura dell\'oscurità, bisogna accettarla.', '', 28153),
(141492, 'itIT', 'La paura non riposa. È implacabile. Un nemico da sconfiggere.', '', 28153),
(141491, 'itIT', 'Al sicuro. Lontano da tutti. Da tutto.', '', 28153),
(141490, 'itIT', 'Che sia la solitudine la risposta? Nessuno può ferirci quando siamo soli.', '', 28153),
(141489, 'itIT', 'I nemici si nascondono nell\'ombra. Questa oscurità può essere fermata?', '', 28153),
(141488, 'itIT', 'Non è giusto! Nulla è mai ciò che sembra!', '', 28153),
(141487, 'itIT', 'Le distrazioni sono una via di fuga.', '', 28153),
(141486, 'itIT', 'Fuggi più lontano... trova sicurezza... trova conforto...', '', 28153),
(141485, 'itIT', 'Nessun sollievo? Nessun conforto?', '', 28153),
(141484, 'itIT', 'Anche nella disperazione può esserci sollievo.', '', 28153),
(141483, 'itIT', 'Angoscia e dolore... la ricerca di conforto.', '', 28153),
(141482, 'itIT', 'Non vi è gentilezza qui.', '', 28153),
(141481, 'itIT', 'Il dolore è ciò da cui nascono i ricordi.', '', 28153),
(141480, 'itIT', 'L\'unica strada è quella che porta avanti.', '', 28153),
(141479, 'itIT', 'Ricordo un tempo in cui solo i Troll erano autorizzati a Zandalar. Be\', Troll e Tortolliani, chiaramente.\n\nHanno cercato di allontanarci una volta. Credo sia stato il bisnonno di Rastakhan, Re Tezlekhan il Virulento. Un tipo alquanto pieno di sé. Gli abbiamo fatto cambiare idea più velocemente di un elementale a un raduno di Sciamani.\n\nNon ti immagini quante informazioni compromettenti puoi ottenere sulla famiglia reale se vivi più a lungo di loro.', 'Ricordo un tempo in cui solo i Troll erano autorizzati a Zandalar. Be\', Troll e Tortolliani, chiaramente.\n\nHanno cercato di allontanarci una volta. Credo sia stato il bisnonno di Rastakhan, Re Tezlekhan il Virulento. Un tipo alquanto pieno di sé. Gli abbiamo fatto cambiare idea più velocemente di un elementale a un raduno di Sciamani.\n\nNon ti immagini quante informazioni compromettenti puoi ottenere sulla famiglia reale se vivi più a lungo di loro.', 28153),
(141478, 'itIT', 'Gli Zandalari permettono alla mia gente di passare nelle loro terre a causa delle utili informazioni che forniamo.\n\nMi chiedo cosa abbia promesso in cambio il tuo popolo.', 'Gli Zandalari permettono alla mia gente di passare nelle loro terre grazie alle informazioni utili che forniamo.\n\nMi chiedo cosa abbia promesso in cambio il tuo popolo.', 28153),
(141477, 'itIT', 'Ah... $gun:una; prode $C. E da quale continente arrivi?', 'Ah... $gun:una; prode $C. E da quale continente arrivi?', 28153);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(141476, 'itIT', '', 'Speriamo che Rokhan e li altri riescano a tornare a Zul\'jan... o chesto sarà nu viaggio assai breve.', 28153),
(141475, 'itIT', 'Ah, $gun avventuriero:un\'avventuriera;. Qual è il tuo compenso? Potrei aver bisogno del tuo aiuto per un\'operazione di recupero alquanto... pericolosa.', 'Ah, $gun avventuriero:un\'avventuriera;. Qual è il tuo compenso? Potrei aver bisogno del tuo aiuto per un\'operazione di recupero alquanto... pericolosa.', 28153),
(141474, 'itIT', 'Ci siamo già incontrati? La mia memoria non è più quella di cento anni fa.', 'Ci siamo già incontrati? La mia memoria non è più quella di cento anni fa.', 28153),
(141473, 'itIT', 'Oh, lasciano entrare l\'Orda a Zuldazar? Che atteggiamento progressista.', 'Oh, lasciano entrare l\'Orda a Zuldazar? Che atteggiamento progressista.', 28153),
(141472, 'itIT', '', '', 28153),
(141471, 'itIT', '', 'Uccidi chesti Troll del Sangue! Nun possiamo lasciargli affondare la barca nostra!', 28153),
(141470, 'itIT', '', 'Guarda, Troll del Sangue! Si preparano ad attaccare la città mia.', 28153),
(141463, 'itIT', 'Cos\'è questo suono?', '', 28153),
(141462, 'itIT', 'Ehilà? C\'è qualcuno laggiù?', '', 28153),
(141461, 'itIT', 'NUBBO NUBBO, VIENI QUI A SPAZZARE IL PONTE!', '', 28153),
(141460, 'itIT', 'Muoviti, fessolisco.', 'Muoviti, fessolisco.', 28153),
(141459, 'itIT', '', 'Negozi come nu verme. Basta raggiri, che cosa vuoi?', 28153),
(141458, 'itIT', '', 'Raal, la moglie tua ha cercato di accidermi stamattina. Cosa crede che stai per fare accà?', 28153),
(141457, 'itIT', '', 'Raal, dobbiamo risolvere chesto problema. Nun voglio più vedere petizioni da parte delli Amani.', 28153),
(141456, 'itIT', 'Un Wendigo! Be\', ci avevo quasi preso. Ha sembianze umane ma è peloso come un orso.', '', 28153),
(141455, 'itIT', '', 'Ugh... sholo pensare alle alghe mi fa... shtar male... Oh, oh...', 28153),
(141454, 'itIT', '', 'Qualcosha riguardo a una copertura d\'alghe?', 28153),
(141453, 'itIT', '', '<Rutta> Ohhh, shì, ricordo qualcuno che shi vantava di un teshoro.', 28153),
(141452, 'itIT', 'Perché dobbiamo restare a fare la guardia accà? Che fregatura.', 'Perché dobbiamo restare a fare la guardia accà? Che fregatura.', 28153),
(141451, 'itIT', '', 'Uooohhh! Hic!$B$BEh? Che shuccede?', 28153),
(141450, 'itIT', '<Sospira> Di certo non aiuta Nubbo Nubbo.', '', 28153),
(141449, 'itIT', 'Ha detto solo che era sepolto \"in un posto sabbioso\". Ti può aiutare?', '', 28153),
(141448, 'itIT', 'Nubbo Nubbo ha sentito parlare di tesori. Tutta la taverna ha sentito!', '', 28153),
(141447, 'itIT', 'C\'è da shpazzare qualcosa?', '', 28153),
(141446, 'itIT', 'TESORO. SEPOLTO.', 'TESORO. SEPOLTO.', 28153),
(141445, 'itIT', 'CASTORO SCONVOLTO?!?', '', 28153),
(141444, 'itIT', 'No, no. Tesoro sepolto.', 'No, no. Tesoro sepolto.', 28153),
(141443, 'itIT', 'LAVORO RISOLTO?', '', 28153),
(141442, 'itIT', 'UN TIZIO NELLA TAVERNA SI STAVA VANTANDO DEL SONORO DISTORTO, COME SE A QUALCUNO INTERESSASSE.', '', 28153),
(141441, 'itIT', 'NO. NON SO NULLA DI ALCUN TESORO.', '', 28153),
(141440, 'itIT', 'OHHHHH. TESORO SEPOLTO.', '', 28153),
(141439, 'itIT', '<Mostra il manifesto.> Cosa sai di questo tesoro sepolto?', '<Mostra il manifesto.> Cosa sai di questo tesoro sepolto?', 28153),
(141438, 'itIT', 'COOOSA? DEVI PARLARE PIÙ FORTE. NON SENTO PIÙ BENE DA...$B$BDALL\'INCIDENTE.', '', 28153),
(141435, 'itIT', 'Pete il Furtivo!', '', 28153),
(141434, 'itIT', '', 'Sorridete sempre! Non si può mai sapere quando gli ospiti ci osservano, soprattutto quelli più furtivi!', 28153),
(141433, 'itIT', '', 'Ricorda, se un ospite dovesse chiederti qualcosa a cui non sai rispondere, inventati qualcosa! Usa il tuo genio gnomesco.', 28153),
(141432, 'itIT', '', 'Mettete in mostra quelle fossette, reclute! Mostrate a tutti quanto adorabili noi Gnomi sappiamo essere!', 28153),
(141431, 'itIT', 'Cosa?!? Non vale! NON VALE!', '', 28153),
(141430, 'itIT', '', 'Flynn! Tieni duro!', 28153),
(141429, 'itIT', 'Diecimila monete d\'oro a chi mi porta le loro teste!', '', 28153),
(141428, 'itIT', 'I Marefiero sono finiti! E quando Dama Bracescura prenderà il trono, sarò io a comandare la sua flotta!', '', 28153),
(141427, 'itIT', 'Basta! Siete comunque arrivati tardi! Il nostro attacco ai Cancelli di Daelin è già iniziato!', '', 28153),
(141426, 'itIT', 'Gah! Questi dadi sono maledetti! Forza, entrate!', '', 28153),
(141425, 'itIT', '<Harlan tira fuori una borsa piena di dadi, rivelando molti tesori.>', '<Harlan tira fuori una borsa piena di dadi, rivelando molti tesori.>', 28153),
(141424, 'itIT', '<Harlan rilancia un cannone e due teschi.>', '<Harlan rilancia un cannone e due teschi.>', 28153),
(141423, 'itIT', '<Harlan lancia due tesori e una bussola.>', '<Harlan lancia due tesori e una bussola.>', 28153),
(141422, 'itIT', '<Harlan lancia tre spade.>', '<Harlan lancia tre spade.>', 28153),
(141421, 'itIT', 'Ah, così va meglio! Ve l\'ho detto che mi piace giocare sporco? Ahah!', '', 28153),
(141420, 'itIT', 'Cosa?!? No, no, no. È tutto sbagliato.', '', 28153),
(141419, 'itIT', 'Umpf! E va bene! Un altro giro!', '', 28153),
(141418, 'itIT', 'Ah, ma guarda, una faccia nuova! Mi auguro tu sia più interessante di questa gente.', '', 28153),
(141417, 'itIT', 'Uhhh, che sfortuna! Ahah! Squartateli!', '', 28153),
(141416, 'itIT', 'Mmm... Cosa potremmo farcene di due ratti ammutinati... Perché non lasciamo che siano i dadi a decidere?', '', 28153),
(141415, 'itIT', 'Oh oh oh! La nostra nuova \"recluta\" è arrivata! Ci sarà da divertirsi!', '', 28153),
(141414, 'itIT', '', 'Lo sfruttamento dei lavoratori di mio marito non finirà mai...', 28153),
(141413, 'itIT', 'Le cose sono cambiate, Flynn. Ora sono io il capitano. E quando i Marefiero saranno fuori dai giochi, saremo liberi di saccheggiare tutta Kul Tiras! Ihihih!', '', 28153),
(141412, 'itIT', 'Nghh... argh... scappa!', '', 28153),
(141411, 'itIT', 'Bene, ragazzi! Fatelo nero.', '', 28153),
(141410, 'itIT', '', 'È giunto il momento per te di avventurarti oltre le nostre sacre vette.', 28153),
(141409, 'itIT', '', 'A volte siamo stati divisi, a volte abbiamo perso la via. Ma gli spiriti dei nostri antenati ci hanno ricordato che siamo tutti legati dalla terra, dai fiumi e dal cielo. Siamo una famiglia e per essa vale la pena combattere.', 28153),
(141408, 'itIT', '', 'Queste parole non raccontano solo della terra e della pietra. Narrano la storia della nostra gente, tra difficoltà e conflitti che ci unirono contro nemici comuni.', 28153),
(141407, 'itIT', '', 'Alto Monte resiste.', 28153),
(141406, 'itIT', '', 'Sei $guno stolto:una stolta; a metterti sulla mia strada!', 28153),
(141405, 'itIT', '', 'Silgryn! Valtrois! Aiutate il reggente!', 28153),
(141404, 'itIT', 'Basta! Dobbiamo purificare questa corruzione prima che il pozzo vada perduto!', '', 28153),
(141403, 'itIT', '', 'Io non volevo che la mia presenza...', 28153),
(141402, 'itIT', 'Perciò ho chiesto che Umbric e i suoi seguaci venissero esiliati. Chiunque sfrutti il potere del Vuoto è un pericolo per il Pozzo Solare!', '', 28153),
(141401, 'itIT', 'Che sta succedendo?', '', 28153),
(141400, 'itIT', 'Indietro!', '', 28153),
(141399, 'itIT', '', 'Il Pozzo Solare è cambiato... ma la sua bellezza permane. È passato così tanto tempo.', 28153),
(141398, 'itIT', '', 'Il Pozzo Solare fu corrotto dai nostri nemici, ma il sacrificio di un Naaru permise di purificare le sue acque. Ora l\'essenza della Luce ci dà forza.', 28153),
(141397, 'itIT', '', 'La sensazione di potere è tangibile. Forte quanto il Pozzo Oscuro, ma di natura differente.', 28153),
(141396, 'itIT', 'Prego, seguitemi.', '', 28153),
(141395, 'itIT', 'Rommath, facci gentilmente strada.', '', 28153),
(141394, 'itIT', '', 'Vedere il Pozzo Solare sarebbe un grande onore, Lor\'themar. E preferisco che gli amici mi chiamino Thalyssra.', 28153),
(141393, 'itIT', 'Qualsiasi cosa sia diventata, Alleria rimane una figlia di Quel\'Thalas. Non posso negarle un pellegrinaggio al nostro luogo più sacro. Prima Arcanista, sarei lieto se tu e il tuo seguito vi uniste a noi.', '', 28153),
(141392, 'itIT', 'Consiglierei di non farlo. Non possiamo essere sicuri che lei...', '', 28153),
(141391, 'itIT', '', 'Sono passati millenni dall\'ultima volta che ho posato gli occhi sul Pozzo Solare. Mi concedi un\'ultima visita?', 28153),
(141389, 'itIT', '', 'Pare che l\'offerta che porto sia stata anticipata... e respinta. Molto bene. Prima di andarmene, però, ho un\'ultima richiesta.', 28153),
(141388, 'itIT', 'Dubiti delle mie parole, ma come potremmo noi fidarci delle tue? Neghi forse che i signori del Vuoto ti sussurrano? Non hai forse ceduto alle ombre su Argus?', '', 28153),
(141387, 'itIT', '', 'Parole taglienti, Lor\'themar. Sono tue, mi chiedo, o il Guardaboschi che conoscevo sta soltanto facendo le veci della Capoguerra?', 28153),
(141384, 'itIT', 'Speravo che la tua visita fosse motivata dal tuo amore per Lunargenta. Invece sei qui al servizio del Re ragazzino dell\'Alleanza. Che delusione.', '', 28153),
(141383, 'itIT', '', 'Come desideri. Sono qui per presentarvi un\'offerta di Re Anduin Wr...', 28153),
(141382, 'itIT', 'Sciocchezze. Qualsiasi cosa tu sia venuta a dirci, puoi farlo davanti ai nostri ospiti.', '', 28153),
(141381, 'itIT', '', 'L\'onore è mio, Prima Arcanista. Non volevo interrompere la tua visita. Forse dovrei tornare in un altro momento.', 28153),
(141380, 'itIT', '', 'Un onore inaspettato, Dama Ventolesto. Silgryn mi ha parlato del tuo coraggio durante la campagna su Argus.', 28153),
(141379, 'itIT', 'Ti prego, chiamami Lor\'themar. Ma dove ho lasciato le buone maniere? Permettetemi di presentarvi Dama Alleria Ventolesto, una grande condottiera del passato di Lunargenta.', '', 28153),
(141376, 'itIT', '', 'È un piacere visitare finalmente la vostra bella città. Ti ringrazio per aver esteso l\'invito a noi, Reggente.', 28153),
(141375, 'itIT', '', 'Prima Arcanista Thalyssra e onorati ospiti, benvenuti a Lunargenta.', 28153),
(141374, 'itIT', 'Non vedo motivo di avere segreti con i nostri alleati, Alleria. Alcuni dei nostri nuovi amici stanno arrivando proprio adesso.', '', 28153),
(141373, 'itIT', '', 'Salve di nuovo, Liadrin. Lor\'themar, sono qui per parlare di un problema di cui sarebbe meglio discutere in privato.', 28153),
(141372, 'itIT', 'Dama Liadrin... benvenuta. Come puoi vedere, abbiamo... un ospite inatteso.', '', 28153),
(141371, 'itIT', '', 'Come desideri, Capoguerra. Quanto a te, ci rivedremo alla villa di Dama Thalyssra a Suramar.', 28153),
(141370, 'itIT', '', 'Conto su di voi. Non tornate fino a quando le forze di Suramar non saranno al servizio dell\'Orda.', 28153),
(141369, 'itIT', '', 'Il reggente ha invitato i Nobili Oscuri a Lunargenta. Io andrò a Suramar per accompagnare Dama Thalyssra all\'incontro.', 28153),
(141366, 'itIT', '', 'Per assicurare il futuro della nostra gente, devi aiutarci a reclamare il nostro posto su Azeroth.', 28153),
(141365, 'itIT', '', 'I nostri capi ci hanno traditi, stringendo un patto con i demoni, ma ci siamo ribellati contro la tirannia cacciandoli dalla nostra terra. Suramar è di nuovo nostra e non lasceremo che cada di nuovo nell\'oscurità.', 28153),
(141364, 'itIT', '', 'Col passare delle ere, Azeroth è cambiata attorno a noi... per poi cadere nella stretta della Legione.', 28153),
(141363, 'itIT', '', 'Per 10.000 anni, Suramar è stato l\'unico mondo che potevamo conoscere.', 28153),
(141362, 'itIT', '', 'Sei un Forgialuce, un faro di speranza contro l\'oscurità.', 28153),
(141361, 'itIT', '', 'Finalmente il nostro nemico è caduto. La Legione è sconfitta, ma la guerra è lungi dall\'essere conclusa. Nuovi pericoli si annidano nelle ombre, in attesa di colpire.', 28153),
(141360, 'itIT', '', 'Nel corso di millenni di battaglie, la Luce ci ha mostrato il vero cammino.', 28153),
(141359, 'itIT', '', 'Siamo soldati.', 28153),
(141358, 'itIT', '', 'Il Vuoto ci ha plasmati... cambiati. Ma tu ne avrai il pieno controllo.', 28153),
(141357, 'itIT', '', 'Ma noi conosciamo una verità che essi ignorano.', 28153),
(141356, 'itIT', '', 'Saggi e studiosi temono il Vuoto.', 28153),
(141355, 'itIT', '', 'Il Vuoto. Una forza dalla fame infinita.', 28153),
(141354, 'itIT', '', 'Io andrò alla barca. Ci vediamo lì.', 28153),
(141353, 'itIT', 'Che Bwonsamdi ti benedica, $gstraniero:straniera;.', '', 28153),
(141352, 'itIT', '', 'I Goblin mi hanno assicurato che chesto piano funzionerà... e tu stai accà per assicurarti che sia così.$B$BFammi sapere quando vuoi partire.', 28153),
(141351, 'itIT', 'Il nostro campione più acclamato, il favorito della folla fremente, il maestro delle mascelle maciullate, il potente pugile predatore! Trothak, lo Squalificatore!', '', 28153),
(141350, 'itIT', 'Incredibile! Questi furfanti sudaticci hanno avuto la meglio anche su Gryff e Stevin! Rimane solo uno sfidante, e non ha bisogno di alcuna introduzione.', '', 28153),
(141349, 'itIT', 'Gli affamati, affamatissimi araldi dell\'agonia, i brutali brutalizzatori di bucanieri, i devastanti doppi distruttori! Gryff e Stevin!', '', 28153),
(141348, 'itIT', 'Senza ulteriori indugi, ecco che dai mari arriva un pericoloso duo di bestie gladiatorie senza eguali, che incute timore anche nei cuori dei più valorosi guerrieri.', '', 28153),
(141347, 'itIT', 'Soffri, $gprofanatore:profanatrice;!', '', 28153),
(141345, 'itIT', 'Non te ne andrai di qui!', '', 28153),
(141344, 'itIT', 'E Ludwig va al tappeto! Che combattimento! Questi bucanieri puzzolenti sono davvero tosti... e fanno bene a esserlo, perché la loro prossima sfida è il simbolo della brutalità!', '', 28153),
(141343, 'itIT', 'Salvati...', '', 28153),
(141342, 'itIT', '', 'Disgraziata! Il patto mio con Bwonsamdi prevedeva vita eterna in cambio dell\'anima tua! Rovinerai tutto quanto!', 28153),
(141341, 'itIT', 'Dalle fogne del Covo della Libertà, un brigante Tortolliano disposto a tutto per ottenere la vittoria. Ahahah! Il portento della protezione, il sergente della strage, la creatura dalla scorza dura: Ludwig!', '', 28153),
(141340, 'itIT', 'Chi l\'avrebbe detto, hanno preso un maiale. Forse sarebbe meglio proseguire con una sfida un po\' più... stuzzicante!', '', 28153),
(141334, 'itIT', '', 'Hai mai sentito parlare del Clan Dentecupo? Nun mi stupisce, è stato spazzato via dal Martello del Crepuscolo.\n\nLi Zandalari mi tengono come na reliquia del passato. Sono na semplice curiosità.\n\nNun è così male però, nun mi capita mai di dover pagare da bere.', 28153),
(141332, 'itIT', 'Si dice che Re Rastakhan nun stia facendo le cose giuste in chesti giorni. È solo questione di tempo prima che tutta Zandalar cada. Cosa succederà a noi?', 'Si dice che Re Rastakhan nun stia facendo le cose giuste in chesti giorni. È solo questione di tempo prima che tutta Zandalar cada. Cosa succederà a noi?', 28153),
(141331, 'itIT', 'Li Zandalari governavano tutti i Troll na volta. Ora nun sono neanche capaci di difendere i confini loro.', 'Li Zandalari governavano tutti i Troll na volta. Ora nun sono neanche capaci di difendere i confini loro.', 28153),
(141330, 'itIT', 'Li Zandalari permettono la magia del sangue entro i confini loro. È solo questione di tempo prima che essa li consumi.', 'Li Zandalari permettono la magia del sangue entro i confini loro. È solo questione di tempo prima che essa li consumi.', 28153),
(141329, 'itIT', 'Li Zandalari inviano tutti coloro che causano problemi nel deserto. Nessuno torna indietro.', 'Li Zandalari inviano tutti coloro che causano problemi nel deserto. Nessuno torna indietro.', 28153),
