(140135, 'itIT', '', 'Combatti per la pace, ma preparati alla guerra.', 28153),
(140134, 'itIT', 'Vivi in pace, ma preparati alla guerra.', '', 28153),
(140133, 'itIT', 'Servi con valore e umiltà.', '', 28153),
(140132, 'itIT', '', 'Servi con valore e umiltà.', 28153),
(140131, 'itIT', 'Troveremo il nostro posto in questo mondo.', '', 28153),
(140130, 'itIT', '', 'Troveremo il nostro posto in questo mondo.', 28153),
(140129, 'itIT', 'Che il dono dell\'Arcan\'dor ti dia forza.', '', 28153),
(140128, 'itIT', '', 'Che il dono dell\'Arcan\'dor ti dia forza.', 28153),
(140127, 'itIT', '', 'Suramar ricorda sempre i suoi campioni.', 28153),
(140126, 'itIT', 'Suramar ricorda sempre i suoi campioni.', '', 28153),
(140125, 'itIT', '', 'Cammina sempre nella Luce.', 28153),
(140124, 'itIT', 'Cammina sempre nella Luce.', '', 28153),
