(140117, 'itIT', '', 'Seguimi.', 28153),
(140116, 'itIT', '', 'Faccio strada io.', 28153),
(140115, 'itIT', 'Seguimi.', '', 28153),
(140114, 'itIT', 'Lascia che ti guidi.', '', 28153),
(140113, 'itIT', '', 'Da questa parte.', 28153),
(140112, 'itIT', '', 'Da questa parte.', 28153),
(140111, 'itIT', 'Vieni con me.', '', 28153),
(140110, 'itIT', 'Vieni con me.', '', 28153),
(140109, 'itIT', 'Che rimanga tra noi, vabbuo\'? Nu segreto tra Zannadoro.', '', 28153),
(140108, 'itIT', 'Mmm, chesto frutto sembra delizioso! Mettiamolo sul tavolo del banchetto.', '', 28153),
(140107, 'itIT', 'Mentre ci porti della frutta, farò dei kebab di scorpide per colazione!', '', 28153),
(140106, 'itIT', '<Le scaglie di $n sono infuse di elettricità statica!>', '<Le scaglie di $n sono infuse di elettricità statica!>', 28153),
(140105, 'itIT', '', 'Il primo volo è tuo, se lo desideri. Fammi sapere dove desideri andare.', 28153),
(140104, 'itIT', '', 'Fai attenzione ai Saurolischi che si nascondono sull\'altura qui sopra... sono creature violente.', 28153),
(140103, 'itIT', 'Tornate indietro!', '', 28153),
(140102, 'itIT', '', 'Tornate indietro!', 28153),
(140101, 'itIT', 'Tornate indietro!', '', 28153),
(140100, 'itIT', '', 'Via di qua!', 28153),
(140099, 'itIT', '', 'Al riparo!', 28153),
(140098, 'itIT', 'Tutti al riparo!', '', 28153),
(140097, 'itIT', '', 'Al riparo!', 28153),
(140096, 'itIT', 'Al riparo!', '', 28153),
(140095, 'itIT', 'Ritirata!', '', 28153),
(140094, 'itIT', '', 'Ritirata!', 28153),
(140093, 'itIT', 'Ritirata!', '', 28153),
(140092, 'itIT', '', 'Ritirata!', 28153),
(140091, 'itIT', 'Il Loa guida i passi tuoi. Devi avvertire il re prima che sia troppo tardi.', '', 28153),
(140090, 'itIT', 'Ci incontreremo alla nave da guerra di Kao quando la strada starà libera. Che li spiriti stiano con te.', '', 28153),
(140089, 'itIT', 'Sì.', '', 28153),
(140088, 'itIT', '', 'Sì.', 28153),
(140087, 'itIT', 'Sì.', '', 28153),
(140086, 'itIT', '', 'Sì.', 28153),
(140085, 'itIT', 'Troverai i guerrieri nostri nella terrazza superiore. Per Zuldazar!', '', 28153),
